window.PV_BANK=[{"id":"licensing-001","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what is the youngest age to get a learner license?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It comes one year before the age for a regular Class E license.","h2":"You can get a Florida learner license when you are 15 years old, one year before you can get a Class E license at 16.","p":"Right. The learner license starts at age 15."},"es":{"q":"En Florida, ¿cuál es la edad mínima para obtener una licencia de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la edad para la licencia Clase E normal.","h2":"Usted puede obtener la licencia de aprendiz en Florida a los 15 años, un año antes de poder obtener la licencia Clase E a los 16.","p":"Correcto. La licencia de aprendiz empieza a los 15 años."},"zh":{"q":"在 Florida，最小几岁可以拿到学习驾照？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比普通 Class E 驾照的年龄早一年。","h2":"你 15 岁时可以拿到 Florida 学习驾照，比 16 岁可以拿到的 Class E 驾照早一年。","p":"对。学习驾照从 15 岁开始。"},"vi":{"q":"Ở Florida, tuổi nhỏ nhất để được cấp giấy phép tập lái là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Tuổi này sớm hơn một năm so với tuổi được cấp bằng lái Class E thông thường.","h2":"Bạn có thể được cấp giấy phép tập lái ở Florida khi bạn 15 tuổi, sớm hơn một năm so với bằng lái Class E lúc 16 tuổi.","p":"Đúng. Giấy phép tập lái bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Florida, ilang taon ang pinakabatang edad para makakuha ng learner license?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ang edad para sa karaniwang Class E license.","h2":"Puwede kang kumuha ng Florida learner license kapag 15 taong gulang ka na, isang taon bago ka puwedeng kumuha ng Class E license sa edad na 16.","p":"Tama. Nagsisimula ang learner license sa edad na 15."},"ar":{"q":"في Florida، ما أصغر عمر للحصول على رخصة متعلم؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هذا العمر يأتي قبل سنة واحدة من عمر الرخصة العادية Class E.","h2":"يمكنك الحصول على رخصة متعلم في Florida عندما يكون عمرك 15 سنة، أي قبل سنة من الحصول على رخصة Class E في عمر 16.","p":"صحيح. رخصة المتعلم تبدأ في عمر 15 سنة."},"ht":{"q":"Nan Florida, ki laj ki pi piti pou w ka jwenn yon lisans aprantisaj?","o":["14 an","15 an","16 an","17 an"],"h1":"Li vini yon ane anvan laj pou yon lisans Class E nòmal.","h2":"Ou ka jwenn yon lisans aprantisaj nan Florida lè ou gen 15 an, yon ane anvan ou ka jwenn yon lisans Class E a 16 an.","p":"Se sa. Lisans aprantisaj la kòmanse a 15 an."},"ref":{"doc":"FL","page":8}},{"id":"licensing-002","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, a driver with a learner license must have someone with them. How old must that person be?","o":["At least 16 years old","At least 18 years old","At least 25 years old","At least 21 years old"],"h1":"The helper must be an experienced adult, older than a new 18-year-old driver.","h2":"A learner must always drive with a licensed driver who is at least 21 years old, because that person needs adult experience to guide them.","p":"Right. The person with you must be a licensed driver age 21 or older."},"es":{"q":"En Florida, quien tiene licencia de aprendiz debe ir acompañado. ¿Qué edad debe tener esa persona?","o":["Por lo menos 16 años","Por lo menos 18 años","Por lo menos 25 años","Por lo menos 21 años"],"h1":"El acompañante debe ser un adulto con experiencia, mayor que un conductor nuevo de 18 años.","h2":"El aprendiz siempre debe manejar con un conductor con licencia que tenga por lo menos 21 años, porque esa persona necesita experiencia de adulto para guiarlo.","p":"Correcto. Su acompañante debe tener licencia y 21 años o más."},"zh":{"q":"在 Florida，持学习驾照的司机必须有人陪同。这个人必须几岁？","o":["至少 16 岁","至少 18 岁","至少 25 岁","至少 21 岁"],"h1":"陪同的人必须是有经验的成年人，比刚满 18 岁的新司机年龄大。","h2":"学习驾驶的人必须一直和一位至少 21 岁、有驾照的司机一起开车，因为这个人需要有成年人的经验来指导。","p":"对。陪你的人必须是 21 岁或以上、有驾照的司机。"},"vi":{"q":"Ở Florida, người có giấy phép tập lái phải có người đi cùng. Người đó phải bao nhiêu tuổi?","o":["Ít nhất 16 tuổi","Ít nhất 18 tuổi","Ít nhất 25 tuổi","Ít nhất 21 tuổi"],"h1":"Người đi cùng phải là người lớn có kinh nghiệm, lớn tuổi hơn một tài xế mới 18 tuổi.","h2":"Người tập lái luôn phải lái xe cùng một người có bằng lái và ít nhất 21 tuổi, vì người đó cần có kinh nghiệm của người lớn để hướng dẫn.","p":"Đúng. Người đi cùng bạn phải có bằng lái và từ 21 tuổi trở lên."},"tl":{"q":"Sa Florida, ang driver na may learner license ay dapat may kasama. Ilang taon dapat ang kasamang iyon?","o":["Hindi bababa sa 16 taong gulang","Hindi bababa sa 18 taong gulang","Hindi bababa sa 25 taong gulang","Hindi bababa sa 21 taong gulang"],"h1":"Ang kasama ay dapat isang adult na may karanasan, mas matanda pa sa bagong driver na 18 taong gulang.","h2":"Ang learner ay dapat laging magmaneho kasama ang isang lisensyadong driver na hindi bababa sa 21 taong gulang, dahil kailangan ng taong iyon ang karanasan ng adult para gabayan siya.","p":"Tama. Ang kasama mo ay dapat lisensyadong driver na 21 taong gulang o higit pa."},"ar":{"q":"في Florida، يجب أن يكون مع السائق الذي يحمل رخصة متعلم شخص آخر. كم يجب أن يكون عمر هذا الشخص؟","o":["16 سنة على الأقل","18 سنة على الأقل","25 سنة على الأقل","21 سنة على الأقل"],"h1":"يجب أن يكون المرافق شخصًا بالغًا له خبرة، وأكبر من سائق جديد عمره 18 سنة.","h2":"يجب على المتعلم أن يقود دائمًا مع سائق مرخّص عمره 21 سنة على الأقل، لأن هذا الشخص يحتاج إلى خبرة البالغين ليرشده.","p":"صحيح. يجب أن يكون الشخص الذي معك سائقًا مرخّصًا عمره 21 سنة أو أكثر."},"ht":{"q":"Nan Florida, yon chofè ki gen lisans aprantisaj dwe toujou gen yon moun avè l. Ki laj moun sa a dwe genyen?","o":["Omwen 16 an","Omwen 18 an","Omwen 25 an","Omwen 21 an"],"h1":"Moun ki ede w la dwe yon granmoun ki gen eksperyans, ki pi gran pase yon nouvo chofè 18 an.","h2":"Yon apranti dwe toujou kondi ak yon chofè ki gen lisans epi ki gen omwen 21 an, paske moun sa a bezwen eksperyans granmoun pou l gide l.","p":"Se sa. Moun ki avè w la dwe yon chofè ki gen lisans, ki gen 21 an oswa plis."},"ref":{"doc":"FL","page":25}},{"id":"licensing-003","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, where must the licensed adult sit when a learner is driving?","o":["In the front passenger seat","In any back seat","Behind the driver","Anywhere in the car"],"h1":"The adult must be able to see the road and help right away.","h2":"The licensed adult must sit in the front passenger seat, next to the learner, so they can watch the road and help quickly.","p":"Right. The adult sits in the front seat, next to you."},"es":{"q":"En Florida, ¿dónde debe sentarse el adulto con licencia cuando maneja un aprendiz?","o":["En el asiento delantero del pasajero","En cualquier asiento de atrás","Detrás del conductor","En cualquier lugar del carro"],"h1":"El adulto debe poder ver la calle y ayudar enseguida.","h2":"El adulto con licencia debe sentarse en el asiento delantero del pasajero, al lado del aprendiz, para ver la calle y ayudar rápido.","p":"Correcto. El adulto va en el asiento de adelante, a su lado."},"zh":{"q":"在 Florida，学习驾驶的人开车时，有驾照的成年人必须坐在哪里？","o":["前排乘客座位","任何后排座位","司机后面","车里任何地方"],"h1":"这个成年人必须能看到道路，并能马上帮忙。","h2":"有驾照的成年人必须坐在前排乘客座位，在学习驾驶的人旁边，这样才能看着道路并很快帮忙。","p":"对。成年人坐在前排，在你旁边。"},"vi":{"q":"Ở Florida, khi người tập lái đang lái xe, người lớn có bằng lái phải ngồi ở đâu?","o":["Ở ghế hành khách phía trước","Ở bất kỳ ghế sau nào","Ngồi sau lưng tài xế","Ở bất kỳ chỗ nào trong xe"],"h1":"Người lớn phải nhìn thấy đường và giúp được ngay lập tức.","h2":"Người lớn có bằng lái phải ngồi ở ghế hành khách phía trước, cạnh người tập lái, để họ quan sát đường và giúp đỡ nhanh chóng.","p":"Đúng. Người lớn ngồi ở ghế trước, cạnh bạn."},"tl":{"q":"Sa Florida, saan dapat umupo ang lisensyadong adult kapag nagmamaneho ang learner?","o":["Sa upuan ng pasahero sa harap","Sa kahit anong upuan sa likod","Sa likod ng driver","Kahit saan sa loob ng kotse"],"h1":"Dapat makita ng adult ang daan at makatulong agad.","h2":"Ang lisensyadong adult ay dapat umupo sa upuan ng pasahero sa harap, katabi ng learner, para mabantayan niya ang daan at makatulong agad.","p":"Tama. Ang adult ay umuupo sa harap, katabi mo."},"ar":{"q":"في Florida، أين يجب أن يجلس البالغ المرخّص عندما يقود المتعلم؟","o":["في المقعد الأمامي بجانب السائق","في أي مقعد خلفي","خلف السائق","في أي مكان في السيارة"],"h1":"يجب أن يستطيع البالغ رؤية الطريق والمساعدة فورًا.","h2":"يجب أن يجلس البالغ المرخّص في المقعد الأمامي بجانب المتعلم، حتى يراقب الطريق ويساعد بسرعة.","p":"صحيح. البالغ يجلس في المقعد الأمامي بجانبك."},"ht":{"q":"Nan Florida, ki kote granmoun ki gen lisans lan dwe chita lè yon apranti ap kondi?","o":["Sou chèz pasaje devan an","Sou nenpòt chèz dèyè","Dèyè chofè a","Nenpòt kote nan machin nan"],"h1":"Granmoun nan dwe ka wè wout la epi ede touswit.","h2":"Granmoun ki gen lisans lan dwe chita sou chèz pasaje devan an, bò kote apranti a, pou l ka gade wout la epi ede vit.","p":"Se sa. Granmoun nan chita devan, bò kote w."},"ref":{"doc":"FL","page":null}},{"id":"licensing-004","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, during the first 3 months with a learner license, when may you drive?","o":["Any time of day or night","Only until midnight","Only during daylight hours","Only on weekends"],"h1":"New learners start with the easiest light conditions.","h2":"For the first 3 months, a learner may drive only during daylight, because seeing well makes it easier to learn safely.","p":"Right. The first 3 months are daylight only."},"es":{"q":"En Florida, durante los primeros 3 meses con licencia de aprendiz, ¿cuándo puede manejar?","o":["A cualquier hora del día o de la noche","Solo hasta la medianoche","Solo durante las horas de luz del día","Solo los fines de semana"],"h1":"Los aprendices nuevos empiezan con la luz más fácil.","h2":"Durante los primeros 3 meses, el aprendiz solo puede manejar de día, porque ver bien hace más fácil aprender con seguridad.","p":"Correcto. Los primeros 3 meses son solo de día."},"zh":{"q":"在 Florida，持学习驾照的前 3 个月，你什么时候可以开车？","o":["白天晚上任何时间","只能开到午夜","只能在白天","只能在周末"],"h1":"新学员从光线最好、最容易的条件开始。","h2":"在前 3 个月，学习驾驶的人只能在白天开车，因为看得清楚更容易安全地学习。","p":"对。前 3 个月只能在白天开车。"},"vi":{"q":"Ở Florida, trong 3 tháng đầu có giấy phép tập lái, bạn được lái xe khi nào?","o":["Bất kỳ giờ nào, ngày hay đêm","Chỉ đến nửa đêm","Chỉ vào ban ngày","Chỉ vào cuối tuần"],"h1":"Người mới tập lái bắt đầu với điều kiện ánh sáng dễ nhất.","h2":"Trong 3 tháng đầu, người tập lái chỉ được lái xe vào ban ngày, vì nhìn rõ giúp việc học lái an toàn hơn.","p":"Đúng. 3 tháng đầu chỉ được lái vào ban ngày."},"tl":{"q":"Sa Florida, sa unang 3 buwan na may learner license, kailan ka puwedeng magmaneho?","o":["Kahit anong oras, araw man o gabi","Hanggang hatinggabi lang","Habang may liwanag ng araw lang","Tuwing weekend lang"],"h1":"Nagsisimula ang mga bagong learner sa pinakamadaling kondisyon ng liwanag.","h2":"Sa unang 3 buwan, ang learner ay puwedeng magmaneho habang may liwanag ng araw lang, dahil mas madaling matuto nang ligtas kapag malinaw ang nakikita.","p":"Tama. Sa unang 3 buwan, sa araw lang puwedeng magmaneho."},"ar":{"q":"في Florida، في أول 3 أشهر مع رخصة المتعلم، متى يُسمح لك بالقيادة؟","o":["في أي وقت من النهار أو الليل","حتى منتصف الليل فقط","في ساعات النهار فقط","في عطلة نهاية الأسبوع فقط"],"h1":"المتعلمون الجدد يبدؤون في أسهل ظروف الإضاءة.","h2":"في أول 3 أشهر، يُسمح للمتعلم بالقيادة في النهار فقط، لأن الرؤية الجيدة تجعل التعلم الآمن أسهل.","p":"صحيح. أول 3 أشهر للقيادة في النهار فقط."},"ht":{"q":"Nan Florida, pandan 3 premye mwa ou gen lisans aprantisaj la, ki lè ou ka kondi?","o":["Nenpòt lè, lajounen kou lannwit","Sèlman jiska minwi","Sèlman lajounen, lè gen limyè solèy","Sèlman nan wikenn"],"h1":"Nouvo apranti yo kòmanse ak limyè ki pi fasil la.","h2":"Pandan 3 premye mwa yo, yon apranti ka kondi sèlman lajounen, paske lè ou wè byen, li pi fasil pou aprann san danje.","p":"Se sa. 3 premye mwa yo, se lajounen sèlman."},"ref":{"doc":"FL","page":25}},{"id":"licensing-005","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, after 3 months with a learner license, until what time may you drive?","o":["Until 8 p.m.","Until 10 p.m.","Until midnight","Until 1 a.m."],"h1":"After 3 months, you may drive later, but not late into the night.","h2":"After the first 3 months, a learner may drive until 10 p.m., still with a licensed driver age 21 or older.","p":"Right. After 3 months, a learner may drive until 10 p.m."},"es":{"q":"En Florida, después de 3 meses con licencia de aprendiz, ¿hasta qué hora puede manejar?","o":["Hasta las 8 p.m.","Hasta las 10 p.m.","Hasta la medianoche","Hasta la 1 a.m."],"h1":"Después de 3 meses puede manejar más tarde, pero no hasta muy tarde en la noche.","h2":"Después de los primeros 3 meses, el aprendiz puede manejar hasta las 10 p.m., siempre con un conductor con licencia de 21 años o más.","p":"Correcto. Después de 3 meses, el aprendiz puede manejar hasta las 10 p.m."},"zh":{"q":"在 Florida，持学习驾照 3 个月以后，你可以开车到几点？","o":["到晚上 8 点","到晚上 10 点","到午夜","到凌晨 1 点"],"h1":"3 个月以后，你可以开得晚一些，但不能开到深夜。","h2":"前 3 个月以后，学习驾驶的人可以开车到晚上 10 点，但仍然要有一位 21 岁或以上、有驾照的司机陪同。","p":"对。3 个月以后，学习驾驶的人可以开车到晚上 10 点。"},"vi":{"q":"Ở Florida, sau 3 tháng có giấy phép tập lái, bạn được lái xe đến mấy giờ?","o":["Đến 8 giờ tối","Đến 10 giờ tối","Đến nửa đêm","Đến 1 giờ sáng"],"h1":"Sau 3 tháng, bạn được lái muộn hơn, nhưng không được lái khuya.","h2":"Sau 3 tháng đầu, người tập lái được lái xe đến 10 giờ tối, vẫn phải có người có bằng lái từ 21 tuổi trở lên đi cùng.","p":"Đúng. Sau 3 tháng, người tập lái được lái đến 10 giờ tối."},"tl":{"q":"Sa Florida, pagkalipas ng 3 buwan na may learner license, hanggang anong oras ka puwedeng magmaneho?","o":["Hanggang 8 p.m.","Hanggang 10 p.m.","Hanggang hatinggabi","Hanggang 1 a.m."],"h1":"Pagkalipas ng 3 buwan, puwede ka nang magmaneho nang mas gabi, pero hindi hanggang malalim na gabi.","h2":"Pagkalipas ng unang 3 buwan, ang learner ay puwedeng magmaneho hanggang 10 p.m., kasama pa rin ang lisensyadong driver na 21 taong gulang o higit pa.","p":"Tama. Pagkalipas ng 3 buwan, puwedeng magmaneho ang learner hanggang 10 p.m."},"ar":{"q":"في Florida، بعد 3 أشهر مع رخصة المتعلم، حتى أي ساعة يُسمح لك بالقيادة؟","o":["حتى الساعة 8 مساءً","حتى الساعة 10 مساءً","حتى منتصف الليل","حتى الساعة 1 بعد منتصف الليل"],"h1":"بعد 3 أشهر يمكنك القيادة لوقت أطول، لكن ليس حتى وقت متأخر من الليل.","h2":"بعد أول 3 أشهر، يُسمح للمتعلم بالقيادة حتى الساعة 10 مساءً، ويبقى معه سائق مرخّص عمره 21 سنة أو أكثر.","p":"صحيح. بعد 3 أشهر يُسمح للمتعلم بالقيادة حتى الساعة 10 مساءً."},"ht":{"q":"Nan Florida, apre 3 mwa ak lisans aprantisaj la, jiska ki lè ou ka kondi?","o":["Jiska 8 p.m.","Jiska 10 p.m.","Jiska minwi","Jiska 1 a.m."],"h1":"Apre 3 mwa, ou ka kondi pi ta, men pa twò ta nan nwit lan.","h2":"Apre 3 premye mwa yo, yon apranti ka kondi jiska 10 p.m., toujou ak yon chofè ki gen lisans epi ki gen 21 an oswa plis.","p":"Se sa. Apre 3 mwa, yon apranti ka kondi jiska 10 p.m."},"ref":{"doc":"FL","page":25}},{"id":"licensing-006","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, what course must a first-time driver finish before getting a license?","o":["A defensive driving course for truck drivers","A first aid and CPR course","A motorcycle safety course","The Traffic Law and Substance Abuse Education course (TLSAE)"],"h1":"The course covers traffic laws and the danger of alcohol and drugs.","h2":"First-time drivers must finish the Traffic Law and Substance Abuse Education course, called TLSAE, which teaches traffic laws and how alcohol and drugs affect driving.","p":"Right. First-time drivers must take the TLSAE course."},"es":{"q":"En Florida, ¿qué curso debe terminar una persona que saca su primera licencia?","o":["Un curso de manejo defensivo para camioneros","Un curso de primeros auxilios y RCP","Un curso de seguridad en motocicleta","El curso de Ley de Tránsito y Educación sobre Abuso de Sustancias (TLSAE)"],"h1":"El curso trata de las leyes de tránsito y del peligro del alcohol y las drogas.","h2":"Quien saca su primera licencia debe terminar el curso de Ley de Tránsito y Educación sobre Abuso de Sustancias, llamado TLSAE, que enseña las leyes de tránsito y cómo el alcohol y las drogas afectan al manejar.","p":"Correcto. Los conductores nuevos deben tomar el curso TLSAE."},"zh":{"q":"在 Florida，第一次考驾照的人拿驾照前必须完成什么课程？","o":["卡车司机的防御性驾驶课程","急救和心肺复苏 (CPR) 课程","摩托车安全课程","交通法规与药物酒精滥用教育课程 (TLSAE)"],"h1":"这个课程讲交通法规，以及酒精和毒品的危险。","h2":"第一次考驾照的人必须完成交通法规与药物酒精滥用教育课程，叫做 TLSAE，它教交通法规，以及酒精和毒品怎样影响开车。","p":"对。第一次考驾照的人必须上 TLSAE 课程。"},"vi":{"q":"Ở Florida, người lái xe lần đầu phải học xong khóa học nào trước khi được cấp bằng lái?","o":["Khóa lái xe phòng vệ cho tài xế xe tải","Khóa sơ cứu và hồi sức tim phổi (CPR)","Khóa an toàn lái xe máy","Khóa Luật Giao thông và Giáo dục về Lạm dụng Chất gây nghiện (TLSAE)"],"h1":"Khóa học này nói về luật giao thông và sự nguy hiểm của rượu bia và ma túy.","h2":"Người lái xe lần đầu phải học xong khóa Luật Giao thông và Giáo dục về Lạm dụng Chất gây nghiện, gọi là TLSAE, khóa này dạy luật giao thông và cách rượu bia, ma túy ảnh hưởng đến việc lái xe.","p":"Đúng. Người lái xe lần đầu phải học khóa TLSAE."},"tl":{"q":"Sa Florida, anong kurso ang dapat tapusin ng unang beses na driver bago kumuha ng lisensya?","o":["Kurso sa defensive driving para sa mga truck driver","Kurso sa first aid at CPR","Kurso sa kaligtasan sa motorsiklo","Ang Traffic Law and Substance Abuse Education course (TLSAE)"],"h1":"Tungkol ang kurso sa mga batas trapiko at sa panganib ng alak at droga.","h2":"Ang mga unang beses na driver ay dapat tumapos ng Traffic Law and Substance Abuse Education course, na tinatawag na TLSAE, na nagtuturo ng mga batas trapiko at kung paano naaapektuhan ng alak at droga ang pagmamaneho.","p":"Tama. Ang mga unang beses na driver ay dapat kumuha ng TLSAE course."},"ar":{"q":"في Florida، ما الدورة التي يجب أن يُنهيها السائق لأول مرة قبل الحصول على الرخصة؟","o":["دورة القيادة الدفاعية لسائقي الشاحنات","دورة الإسعافات الأولية والإنعاش القلبي","دورة السلامة لسائقي الدراجات النارية","دورة قوانين المرور والتوعية بالكحول والمخدرات (TLSAE)"],"h1":"الدورة تشرح قوانين المرور وخطر الكحول والمخدرات.","h2":"يجب على السائقين لأول مرة أن يُنهوا دورة قوانين المرور والتوعية بالكحول والمخدرات، واسمها TLSAE، وهي تعلّم قوانين المرور وتأثير الكحول والمخدرات على القيادة.","p":"صحيح. السائقون لأول مرة يجب أن يأخذوا دورة TLSAE."},"ht":{"q":"Nan Florida, ki kou yon moun k ap kondi pou premye fwa dwe fini anvan l jwenn yon lisans?","o":["Yon kou kondi pridan pou chofè kamyon","Yon kou premye swen ak CPR","Yon kou sekirite pou motosiklèt","Kou Traffic Law and Substance Abuse Education (TLSAE)"],"h1":"Kou a pale sou lwa wout yo ak danje alkòl ak dwòg.","h2":"Moun k ap kondi pou premye fwa dwe fini kou Traffic Law and Substance Abuse Education, yo rele TLSAE, ki aprann lwa wout yo ak jan alkòl ak dwòg chanje fason ou kondi.","p":"Se sa. Moun k ap kondi pou premye fwa dwe pran kou TLSAE a."},"ref":{"doc":"FL","page":17}},{"id":"licensing-007","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, the learner license knowledge test has 50 questions. How many must you answer correctly to pass?","o":["At least 40","At least 30","At least 35","All 50"],"h1":"You need 80 percent of the questions right.","h2":"You must answer at least 40 of the 50 questions correctly, which is 80 percent, to pass the knowledge test.","p":"Right. You need 40 correct answers out of 50."},"es":{"q":"En Florida, el examen de conocimientos para la licencia de aprendiz tiene 50 preguntas. ¿Cuántas debe contestar bien para aprobar?","o":["Por lo menos 40","Por lo menos 30","Por lo menos 35","Las 50"],"h1":"Necesita el 80 por ciento de las preguntas correctas.","h2":"Usted debe contestar bien por lo menos 40 de las 50 preguntas, que es el 80 por ciento, para aprobar el examen de conocimientos.","p":"Correcto. Necesita 40 respuestas correctas de 50."},"zh":{"q":"在 Florida，学习驾照的笔试有 50 道题。你必须答对多少道才能通过？","o":["至少 40 道","至少 30 道","至少 35 道","全部 50 道"],"h1":"你需要答对 80% 的题目。","h2":"你必须在 50 道题里至少答对 40 道，也就是 80%，才能通过笔试。","p":"对。50 道题里你需要答对 40 道。"},"vi":{"q":"Ở Florida, bài thi kiến thức để lấy giấy phép tập lái có 50 câu hỏi. Bạn phải trả lời đúng bao nhiêu câu để đậu?","o":["Ít nhất 40 câu","Ít nhất 30 câu","Ít nhất 35 câu","Cả 50 câu"],"h1":"Bạn cần trả lời đúng 80 phần trăm số câu hỏi.","h2":"Bạn phải trả lời đúng ít nhất 40 trên 50 câu hỏi, tức là 80 phần trăm, để đậu bài thi kiến thức.","p":"Đúng. Bạn cần 40 câu đúng trên 50 câu."},"tl":{"q":"Sa Florida, ang knowledge test para sa learner license ay may 50 tanong. Ilan ang dapat mong masagot nang tama para pumasa?","o":["Hindi bababa sa 40","Hindi bababa sa 30","Hindi bababa sa 35","Lahat ng 50"],"h1":"Kailangan mong makuha nang tama ang 80 porsyento ng mga tanong.","h2":"Dapat mong masagot nang tama ang hindi bababa sa 40 sa 50 tanong, na 80 porsyento, para pumasa sa knowledge test.","p":"Tama. Kailangan mo ng 40 tamang sagot sa 50."},"ar":{"q":"في Florida، اختبار المعرفة لرخصة المتعلم فيه 50 سؤالًا. كم سؤالًا يجب أن تجيب عنه إجابة صحيحة لتنجح؟","o":["40 على الأقل","30 على الأقل","35 على الأقل","كل الأسئلة الـ 50"],"h1":"تحتاج إلى إجابة صحيحة عن 80 بالمئة من الأسئلة.","h2":"يجب أن تجيب إجابة صحيحة عن 40 سؤالًا على الأقل من 50، أي 80 بالمئة، لتنجح في اختبار المعرفة.","p":"صحيح. تحتاج إلى 40 إجابة صحيحة من 50."},"ht":{"q":"Nan Florida, egzamen konesans pou lisans aprantisaj la gen 50 kesyon. Konbyen ou dwe reponn kòrèk pou w pase?","o":["Omwen 40","Omwen 30","Omwen 35","Tout 50 yo"],"h1":"Ou bezwen 80 pousan nan kesyon yo bon.","h2":"Ou dwe reponn omwen 40 nan 50 kesyon yo kòrèk, sa ki fè 80 pousan, pou w pase egzamen konesans lan.","p":"Se sa. Ou bezwen 40 bon repons sou 50."},"ref":{"doc":"FL","page":null}},{"id":"licensing-008","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, a 16-year-old wants a Class E license. How long must they first hold a learner license?","o":["3 months, with no traffic convictions","6 months, even with traffic convictions","12 months, or until age 18, with no traffic convictions","24 months, with no traffic convictions"],"h1":"Think about one full year of practice without breaking traffic laws.","h2":"A teen must hold the learner license for 12 months, or until turning 18, with no traffic convictions before getting a Class E license.","p":"Right. Hold the learner license 12 months with a clean record."},"es":{"q":"En Florida, una persona de 16 años quiere la licencia Clase E. ¿Cuánto tiempo debe tener antes la licencia de aprendiz?","o":["3 meses, sin condenas de tránsito","6 meses, aunque tenga condenas de tránsito","12 meses, o hasta cumplir 18, sin condenas de tránsito","24 meses, sin condenas de tránsito"],"h1":"Piense en un año completo de práctica sin violar las leyes de tránsito.","h2":"Un joven debe tener la licencia de aprendiz por 12 meses, o hasta cumplir 18 años, sin condenas de tránsito antes de obtener la licencia Clase E.","p":"Correcto. Tenga la licencia de aprendiz 12 meses con un récord limpio."},"zh":{"q":"在 Florida，一个 16 岁的人想拿 Class E 驾照。他必须先持有学习驾照多久？","o":["3 个月，没有交通违法定罪","6 个月，即使有交通违法定罪","12 个月，或者到 18 岁，没有交通违法定罪","24 个月，没有交通违法定罪"],"h1":"想一想整整一年的练习，而且不违反交通法规。","h2":"青少年必须持有学习驾照 12 个月，或者到满 18 岁，并且没有交通违法定罪，才能拿到 Class E 驾照。","p":"对。持有学习驾照 12 个月，记录要干净。"},"vi":{"q":"Ở Florida, một thiếu niên 16 tuổi muốn có bằng lái Class E. Trước đó, em phải giữ giấy phép tập lái trong bao lâu?","o":["3 tháng, không bị kết tội vi phạm giao thông","6 tháng, dù có bị kết tội vi phạm giao thông","12 tháng, hoặc đến khi 18 tuổi, không bị kết tội vi phạm giao thông","24 tháng, không bị kết tội vi phạm giao thông"],"h1":"Hãy nghĩ đến một năm tập lái trọn vẹn mà không vi phạm luật giao thông.","h2":"Thiếu niên phải giữ giấy phép tập lái trong 12 tháng, hoặc đến khi 18 tuổi, và không bị kết tội vi phạm giao thông, rồi mới được cấp bằng lái Class E.","p":"Đúng. Giữ giấy phép tập lái 12 tháng với hồ sơ sạch."},"tl":{"q":"Sa Florida, ang isang 16 taong gulang ay gustong kumuha ng Class E license. Gaano katagal muna niyang dapat hawak ang learner license?","o":["3 buwan, nang walang traffic conviction","6 na buwan, kahit may traffic conviction","12 buwan, o hanggang edad 18, nang walang traffic conviction","24 na buwan, nang walang traffic conviction"],"h1":"Isipin ang isang buong taon ng pagsasanay nang hindi lumalabag sa batas trapiko.","h2":"Ang teen ay dapat may hawak na learner license nang 12 buwan, o hanggang mag-18 taong gulang, nang walang traffic conviction bago makakuha ng Class E license.","p":"Tama. Hawakan ang learner license nang 12 buwan na malinis ang record."},"ar":{"q":"في Florida، شاب عمره 16 سنة يريد رخصة Class E. كم من الوقت يجب أن يحمل رخصة المتعلم أولًا؟","o":["3 أشهر، بدون مخالفات مرورية مُدان بها","6 أشهر، حتى مع مخالفات مرورية مُدان بها","12 شهرًا، أو حتى عمر 18، بدون مخالفات مرورية مُدان بها","24 شهرًا، بدون مخالفات مرورية مُدان بها"],"h1":"فكّر في سنة كاملة من التدريب بدون مخالفة قوانين المرور.","h2":"يجب على الشاب أن يحمل رخصة المتعلم 12 شهرًا، أو حتى يبلغ 18 سنة، بدون أي إدانة بمخالفة مرورية، قبل أن يحصل على رخصة Class E.","p":"صحيح. احمل رخصة المتعلم 12 شهرًا بسجل نظيف."},"ht":{"q":"Nan Florida, yon moun 16 an vle yon lisans Class E. Konbyen tan li dwe gen lisans aprantisaj la anvan?","o":["3 mwa, san okenn kondanasyon pou enfraksyon wout","6 mwa, menm si li gen kondanasyon pou enfraksyon wout","12 mwa, oswa jiskaske li gen 18 an, san okenn kondanasyon pou enfraksyon wout","24 mwa, san okenn kondanasyon pou enfraksyon wout"],"h1":"Panse ak yon ane konplè pratik san ou pa vyole lwa wout yo.","h2":"Yon jèn dwe gen lisans aprantisaj la pandan 12 mwa, oswa jiskaske li gen 18 an, san okenn kondanasyon pou enfraksyon wout, anvan li jwenn yon lisans Class E.","p":"Se sa. Kenbe lisans aprantisaj la 12 mwa ak yon dosye pwòp."},"ref":{"doc":"FL","page":8}},{"id":"licensing-009","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, how many hours of supervised driving must a teen complete before getting a Class E license?","o":["20 hours","50 hours","30 hours","100 hours"],"h1":"It is a large number, with some of the hours at night.","h2":"A teen must complete 50 hours of supervised driving, and 10 of those hours must be at night.","p":"Right. Teens need 50 hours of supervised driving."},"es":{"q":"En Florida, ¿cuántas horas de manejo supervisado debe completar un joven antes de obtener la licencia Clase E?","o":["20 horas","50 horas","30 horas","100 horas"],"h1":"Es un número grande, y algunas de las horas son de noche.","h2":"Un joven debe completar 50 horas de manejo supervisado, y 10 de esas horas deben ser de noche.","p":"Correcto. Los jóvenes necesitan 50 horas de manejo supervisado."},"zh":{"q":"在 Florida，青少年拿 Class E 驾照前，必须完成多少小时有人监督的驾驶？","o":["20 小时","50 小时","30 小时","100 小时"],"h1":"这是一个比较大的数字，其中有一些小时要在晚上。","h2":"青少年必须完成 50 小时有人监督的驾驶，其中 10 小时必须在晚上。","p":"对。青少年需要 50 小时有人监督的驾驶。"},"vi":{"q":"Ở Florida, thiếu niên phải lái xe có người giám sát bao nhiêu giờ trước khi được cấp bằng lái Class E?","o":["20 giờ","50 giờ","30 giờ","100 giờ"],"h1":"Đây là một con số lớn, và một phần số giờ phải lái vào ban đêm.","h2":"Thiếu niên phải lái xe có người giám sát đủ 50 giờ, và 10 giờ trong số đó phải lái vào ban đêm.","p":"Đúng. Thiếu niên cần 50 giờ lái xe có người giám sát."},"tl":{"q":"Sa Florida, ilang oras ng supervised driving (pagmamaneho na may kasamang lisensyadong adult) ang dapat tapusin ng teen bago makakuha ng Class E license?","o":["20 oras","50 oras","30 oras","100 oras"],"h1":"Malaking bilang ito, at ang ilan sa mga oras ay sa gabi.","h2":"Ang teen ay dapat tumapos ng 50 oras ng supervised driving, at 10 sa mga oras na iyon ay dapat sa gabi.","p":"Tama. Kailangan ng teen ang 50 oras ng supervised driving."},"ar":{"q":"في Florida، كم ساعة من القيادة تحت الإشراف يجب أن يُكملها الشاب قبل الحصول على رخصة Class E؟","o":["20 ساعة","50 ساعة","30 ساعة","100 ساعة"],"h1":"إنه عدد كبير، وبعض الساعات تكون في الليل.","h2":"يجب على الشاب أن يُكمل 50 ساعة من القيادة تحت الإشراف، ويجب أن تكون 10 ساعات منها في الليل.","p":"صحيح. يحتاج الشباب إلى 50 ساعة من القيادة تحت الإشراف."},"ht":{"q":"Nan Florida, konbyen èdtan kondi ak siveyans yon jèn dwe fè anvan li jwenn yon lisans Class E?","o":["20 èdtan","50 èdtan","30 èdtan","100 èdtan"],"h1":"Se yon gwo kantite, epi kèk nan èdtan yo dwe fèt lannwit.","h2":"Yon jèn dwe fè 50 èdtan kondi ak siveyans, epi 10 nan èdtan sa yo dwe fèt lannwit.","p":"Se sa. Jèn yo bezwen 50 èdtan kondi ak siveyans."},"ref":{"doc":"FL","page":8}},{"id":"licensing-010","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, of the supervised driving hours a teen needs, how many must be at night?","o":["5 hours","25 hours","50 hours","10 hours"],"h1":"It is a small part of the total supervised hours.","h2":"Of the 50 supervised hours, at least 10 must be at night, so the teen learns to drive in the dark before driving alone.","p":"Right. At least 10 of the hours must be at night."},"es":{"q":"En Florida, de las horas de manejo supervisado que necesita un joven, ¿cuántas deben ser de noche?","o":["5 horas","25 horas","50 horas","10 horas"],"h1":"Es una parte pequeña del total de horas supervisadas.","h2":"De las 50 horas supervisadas, por lo menos 10 deben ser de noche, para que el joven aprenda a manejar en la oscuridad antes de manejar solo.","p":"Correcto. Por lo menos 10 de las horas deben ser de noche."},"zh":{"q":"在 Florida，青少年需要的有人监督驾驶时间中，有多少小时必须在晚上？","o":["5 小时","25 小时","50 小时","10 小时"],"h1":"这只是全部监督时间里的一小部分。","h2":"在 50 小时有人监督的驾驶中，至少 10 小时必须在晚上，这样青少年在自己开车前就学会在黑暗中开车。","p":"对。至少 10 小时必须在晚上。"},"vi":{"q":"Ở Florida, trong số giờ lái xe có người giám sát mà thiếu niên cần có, bao nhiêu giờ phải lái vào ban đêm?","o":["5 giờ","25 giờ","50 giờ","10 giờ"],"h1":"Đây là một phần nhỏ trong tổng số giờ có người giám sát.","h2":"Trong 50 giờ có người giám sát, ít nhất 10 giờ phải lái vào ban đêm, để thiếu niên học lái trong bóng tối trước khi lái một mình.","p":"Đúng. Ít nhất 10 giờ phải lái vào ban đêm."},"tl":{"q":"Sa Florida, sa mga oras ng supervised driving na kailangan ng teen, ilan ang dapat sa gabi?","o":["5 oras","25 oras","50 oras","10 oras"],"h1":"Maliit na bahagi ito ng kabuuang supervised na oras.","h2":"Sa 50 supervised na oras, hindi bababa sa 10 ang dapat sa gabi, para matutong magmaneho ang teen sa dilim bago siya magmaneho nang mag-isa.","p":"Tama. Hindi bababa sa 10 sa mga oras ang dapat sa gabi."},"ar":{"q":"في Florida، من ساعات القيادة تحت الإشراف التي يحتاجها الشاب، كم ساعة يجب أن تكون في الليل؟","o":["5 ساعات","25 ساعة","50 ساعة","10 ساعات"],"h1":"إنه جزء صغير من مجموع ساعات الإشراف.","h2":"من الـ 50 ساعة تحت الإشراف، يجب أن تكون 10 ساعات على الأقل في الليل، حتى يتعلم الشاب القيادة في الظلام قبل أن يقود وحده.","p":"صحيح. 10 ساعات على الأقل يجب أن تكون في الليل."},"ht":{"q":"Nan Florida, nan èdtan kondi ak siveyans yon jèn bezwen, konbyen ladan yo dwe fèt lannwit?","o":["5 èdtan","25 èdtan","50 èdtan","10 èdtan"],"h1":"Se yon ti pati nan total èdtan siveyans yo.","h2":"Nan 50 èdtan siveyans yo, omwen 10 dwe fèt lannwit, pou jèn nan aprann kondi nan fènwa anvan li kondi pou kont li.","p":"Se sa. Omwen 10 nan èdtan yo dwe fèt lannwit."},"ref":{"doc":"FL","page":8}},{"id":"licensing-011","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, who certifies that a teen under 18 completed the supervised driving hours?","o":["A parent, legal guardian, or responsible adult","The teen alone","A police officer","The school principal"],"h1":"Think about the adult who is legally responsible for the teen.","h2":"A parent, legal guardian, or responsible adult must certify that the teen completed the supervised driving hours.","p":"Right. A parent or guardian certifies the driving hours."},"es":{"q":"En Florida, ¿quién certifica que un joven menor de 18 completó las horas de manejo supervisado?","o":["Un padre, tutor legal o adulto responsable","El joven solo","Un oficial de policía","El director de la escuela"],"h1":"Piense en el adulto que es legalmente responsable del joven.","h2":"Un padre, tutor legal o adulto responsable debe certificar que el joven completó las horas de manejo supervisado.","p":"Correcto. Un padre o tutor certifica las horas de manejo."},"zh":{"q":"在 Florida，谁来证明 18 岁以下的青少年完成了有人监督的驾驶时间？","o":["父母、法定监护人或负责任的成年人","青少年自己","警察","学校校长"],"h1":"想一想在法律上对这个青少年负责的成年人。","h2":"父母、法定监护人或负责任的成年人必须证明青少年完成了有人监督的驾驶时间。","p":"对。父母或监护人证明驾驶时间。"},"vi":{"q":"Ở Florida, ai xác nhận rằng một thiếu niên dưới 18 tuổi đã lái đủ số giờ có người giám sát?","o":["Cha mẹ, người giám hộ hợp pháp, hoặc một người lớn có trách nhiệm","Chỉ một mình thiếu niên đó","Một cảnh sát","Hiệu trưởng nhà trường"],"h1":"Hãy nghĩ đến người lớn chịu trách nhiệm pháp lý cho thiếu niên đó.","h2":"Cha mẹ, người giám hộ hợp pháp, hoặc một người lớn có trách nhiệm phải xác nhận rằng thiếu niên đã lái đủ số giờ có người giám sát.","p":"Đúng. Cha mẹ hoặc người giám hộ xác nhận số giờ lái xe."},"tl":{"q":"Sa Florida, sino ang nagpapatunay na natapos ng teen na wala pang 18 ang mga oras ng supervised driving?","o":["Isang magulang, legal na guardian, o responsableng adult","Ang teen lang mismo","Isang pulis","Ang principal ng paaralan"],"h1":"Isipin ang adult na may legal na pananagutan sa teen.","h2":"Isang magulang, legal na guardian, o responsableng adult ang dapat magpatunay na natapos ng teen ang mga oras ng supervised driving.","p":"Tama. Ang magulang o guardian ang nagpapatunay ng mga oras ng pagmamaneho."},"ar":{"q":"في Florida، من يشهد بأن الشاب تحت 18 سنة أكمل ساعات القيادة تحت الإشراف؟","o":["أحد الوالدين، أو الوصي القانوني، أو شخص بالغ مسؤول","الشاب وحده","شرطي","مدير المدرسة"],"h1":"فكّر في الشخص البالغ المسؤول قانونيًا عن الشاب.","h2":"يجب على أحد الوالدين، أو الوصي القانوني، أو شخص بالغ مسؤول، أن يشهد بأن الشاب أكمل ساعات القيادة تحت الإشراف.","p":"صحيح. أحد الوالدين أو الوصي يشهد على ساعات القيادة."},"ht":{"q":"Nan Florida, kiyès ki sètifye ke yon jèn ki poko gen 18 an fini èdtan kondi ak siveyans yo?","o":["Yon paran, yon gadyen legal, oswa yon granmoun ki responsab","Jèn nan pou kont li","Yon polis","Direktè lekòl la"],"h1":"Panse ak granmoun ki responsab jèn nan devan lalwa.","h2":"Yon paran, yon gadyen legal, oswa yon granmoun ki responsab dwe sètifye ke jèn nan fini èdtan kondi ak siveyans yo.","p":"Se sa. Yon paran oswa yon gadyen sètifye èdtan kondi yo."},"ref":{"doc":"FL","page":8}},{"id":"licensing-012","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, a 16-year-old with a Class E license may not drive alone during which hours?","o":["From 9 p.m. to 5 a.m.","From 1 a.m. to 5 a.m.","From 11 p.m. to 6 a.m.","From midnight to 8 a.m."],"h1":"The younger the driver, the longer the night hours they cannot drive alone.","h2":"A 16-year-old may not drive from 11 p.m. to 6 a.m. unless a licensed driver age 21 or older is with them or they are driving to or from work.","p":"Right. At 16, no driving alone from 11 p.m. to 6 a.m."},"es":{"q":"En Florida, una persona de 16 años con licencia Clase E, ¿durante qué horas no puede manejar sola?","o":["De 9 p.m. a 5 a.m.","De 1 a.m. a 5 a.m.","De 11 p.m. a 6 a.m.","De medianoche a 8 a.m."],"h1":"Mientras más joven es el conductor, más largas son las horas de la noche en que no puede manejar solo.","h2":"Una persona de 16 años no puede manejar de 11 p.m. a 6 a.m., a menos que vaya con un conductor con licencia de 21 años o más, o que maneje hacia o desde el trabajo.","p":"Correcto. A los 16, no se maneja solo de 11 p.m. a 6 a.m."},"zh":{"q":"在 Florida，持 Class E 驾照的 16 岁司机在哪段时间不能单独开车？","o":["晚上 9 点到早上 5 点","凌晨 1 点到早上 5 点","晚上 11 点到早上 6 点","午夜到早上 8 点"],"h1":"司机年龄越小，夜里不能单独开车的时间就越长。","h2":"16 岁的司机在晚上 11 点到早上 6 点不能开车，除非有一位 21 岁或以上、有驾照的司机陪同，或者他是在上班或下班的路上。","p":"对。16 岁时，晚上 11 点到早上 6 点不能单独开车。"},"vi":{"q":"Ở Florida, một thiếu niên 16 tuổi có bằng lái Class E không được lái xe một mình trong khoảng giờ nào?","o":["Từ 9 giờ tối đến 5 giờ sáng","Từ 1 giờ sáng đến 5 giờ sáng","Từ 11 giờ tối đến 6 giờ sáng","Từ nửa đêm đến 8 giờ sáng"],"h1":"Tài xế càng nhỏ tuổi thì khoảng giờ ban đêm không được lái một mình càng dài.","h2":"Thiếu niên 16 tuổi không được lái xe từ 11 giờ tối đến 6 giờ sáng, trừ khi có người có bằng lái từ 21 tuổi trở lên đi cùng hoặc em đang lái xe đi làm hay đi làm về.","p":"Đúng. Ở tuổi 16, không lái một mình từ 11 giờ tối đến 6 giờ sáng."},"tl":{"q":"Sa Florida, ang 16 taong gulang na may Class E license ay hindi puwedeng magmaneho nang mag-isa sa anong mga oras?","o":["Mula 9 p.m. hanggang 5 a.m.","Mula 1 a.m. hanggang 5 a.m.","Mula 11 p.m. hanggang 6 a.m.","Mula hatinggabi hanggang 8 a.m."],"h1":"Kapag mas bata ang driver, mas mahaba ang mga oras sa gabi na hindi siya puwedeng magmaneho nang mag-isa.","h2":"Ang 16 taong gulang ay hindi puwedeng magmaneho mula 11 p.m. hanggang 6 a.m. maliban kung kasama niya ang lisensyadong driver na 21 taong gulang o higit pa, o papunta o pauwi siya mula sa trabaho.","p":"Tama. Sa edad na 16, bawal magmaneho nang mag-isa mula 11 p.m. hanggang 6 a.m."},"ar":{"q":"في Florida، شاب عمره 16 سنة يحمل رخصة Class E. في أي ساعات لا يُسمح له بالقيادة وحده؟","o":["من 9 مساءً إلى 5 صباحًا","من 1 بعد منتصف الليل إلى 5 صباحًا","من 11 مساءً إلى 6 صباحًا","من منتصف الليل إلى 8 صباحًا"],"h1":"كلما كان السائق أصغر، كانت ساعات الليل التي لا يقود فيها وحده أطول.","h2":"لا يُسمح لمن عمره 16 سنة بالقيادة من 11 مساءً إلى 6 صباحًا، إلا إذا كان معه سائق مرخّص عمره 21 سنة أو أكثر، أو كان ذاهبًا إلى العمل أو عائدًا منه.","p":"صحيح. في عمر 16، لا قيادة وحدك من 11 مساءً إلى 6 صباحًا."},"ht":{"q":"Nan Florida, yon moun 16 an ki gen lisans Class E pa ka kondi pou kont li nan ki lè?","o":["Soti 9 p.m. rive 5 a.m.","Soti 1 a.m. rive 5 a.m.","Soti 11 p.m. rive 6 a.m.","Soti minwi rive 8 a.m."],"h1":"Plis chofè a jèn, plis lè nan nwit li pa ka kondi pou kont li yo long.","h2":"Yon moun 16 an pa ka kondi soti 11 p.m. rive 6 a.m., sof si yon chofè ki gen lisans epi ki gen 21 an oswa plis avè l, oswa si l ap ale oswa l ap soti travay.","p":"Se sa. A 16 an, ou pa kondi pou kont ou soti 11 p.m. rive 6 a.m."},"ref":{"doc":"FL","page":25}},{"id":"licensing-013","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, a 17-year-old with a Class E license may not drive alone during which hours?","o":["From 11 p.m. to 6 a.m.","From 1 a.m. to 5 a.m.","From 10 p.m. to 6 a.m.","From 2 a.m. to 7 a.m."],"h1":"A 17-year-old gets a shorter limit than a 16-year-old.","h2":"A 17-year-old may not drive from 1 a.m. to 5 a.m. unless a licensed driver age 21 or older is with them or they are driving to or from work.","p":"Right. At 17, no driving alone from 1 a.m. to 5 a.m."},"es":{"q":"En Florida, una persona de 17 años con licencia Clase E, ¿durante qué horas no puede manejar sola?","o":["De 11 p.m. a 6 a.m.","De 1 a.m. a 5 a.m.","De 10 p.m. a 6 a.m.","De 2 a.m. a 7 a.m."],"h1":"A los 17 años el límite es más corto que a los 16.","h2":"Una persona de 17 años no puede manejar de 1 a.m. a 5 a.m., a menos que vaya con un conductor con licencia de 21 años o más, o que maneje hacia o desde el trabajo.","p":"Correcto. A los 17, no se maneja solo de 1 a.m. a 5 a.m."},"zh":{"q":"在 Florida，持 Class E 驾照的 17 岁司机在哪段时间不能单独开车？","o":["晚上 11 点到早上 6 点","凌晨 1 点到早上 5 点","晚上 10 点到早上 6 点","凌晨 2 点到早上 7 点"],"h1":"17 岁的司机受到的限制比 16 岁的司机短。","h2":"17 岁的司机在凌晨 1 点到早上 5 点不能开车，除非有一位 21 岁或以上、有驾照的司机陪同，或者他是在上班或下班的路上。","p":"对。17 岁时，凌晨 1 点到早上 5 点不能单独开车。"},"vi":{"q":"Ở Florida, một thiếu niên 17 tuổi có bằng lái Class E không được lái xe một mình trong khoảng giờ nào?","o":["Từ 11 giờ tối đến 6 giờ sáng","Từ 1 giờ sáng đến 5 giờ sáng","Từ 10 giờ tối đến 6 giờ sáng","Từ 2 giờ sáng đến 7 giờ sáng"],"h1":"Thiếu niên 17 tuổi bị giới hạn ngắn hơn thiếu niên 16 tuổi.","h2":"Thiếu niên 17 tuổi không được lái xe từ 1 giờ sáng đến 5 giờ sáng, trừ khi có người có bằng lái từ 21 tuổi trở lên đi cùng hoặc em đang lái xe đi làm hay đi làm về.","p":"Đúng. Ở tuổi 17, không lái một mình từ 1 giờ sáng đến 5 giờ sáng."},"tl":{"q":"Sa Florida, ang 17 taong gulang na may Class E license ay hindi puwedeng magmaneho nang mag-isa sa anong mga oras?","o":["Mula 11 p.m. hanggang 6 a.m.","Mula 1 a.m. hanggang 5 a.m.","Mula 10 p.m. hanggang 6 a.m.","Mula 2 a.m. hanggang 7 a.m."],"h1":"Mas maikli ang limitasyon ng 17 taong gulang kaysa sa 16 taong gulang.","h2":"Ang 17 taong gulang ay hindi puwedeng magmaneho mula 1 a.m. hanggang 5 a.m. maliban kung kasama niya ang lisensyadong driver na 21 taong gulang o higit pa, o papunta o pauwi siya mula sa trabaho.","p":"Tama. Sa edad na 17, bawal magmaneho nang mag-isa mula 1 a.m. hanggang 5 a.m."},"ar":{"q":"في Florida، شاب عمره 17 سنة يحمل رخصة Class E. في أي ساعات لا يُسمح له بالقيادة وحده؟","o":["من 11 مساءً إلى 6 صباحًا","من 1 بعد منتصف الليل إلى 5 صباحًا","من 10 مساءً إلى 6 صباحًا","من 2 بعد منتصف الليل إلى 7 صباحًا"],"h1":"من عمره 17 سنة له وقت منع أقصر ممن عمره 16 سنة.","h2":"لا يُسمح لمن عمره 17 سنة بالقيادة من 1 بعد منتصف الليل إلى 5 صباحًا، إلا إذا كان معه سائق مرخّص عمره 21 سنة أو أكثر، أو كان ذاهبًا إلى العمل أو عائدًا منه.","p":"صحيح. في عمر 17، لا قيادة وحدك من 1 بعد منتصف الليل إلى 5 صباحًا."},"ht":{"q":"Nan Florida, yon moun 17 an ki gen lisans Class E pa ka kondi pou kont li nan ki lè?","o":["Soti 11 p.m. rive 6 a.m.","Soti 1 a.m. rive 5 a.m.","Soti 10 p.m. rive 6 a.m.","Soti 2 a.m. rive 7 a.m."],"h1":"Yon moun 17 an gen yon limit ki pi kout pase yon moun 16 an.","h2":"Yon moun 17 an pa ka kondi soti 1 a.m. rive 5 a.m., sof si yon chofè ki gen lisans epi ki gen 21 an oswa plis avè l, oswa si l ap ale oswa l ap soti travay.","p":"Se sa. A 17 an, ou pa kondi pou kont ou soti 1 a.m. rive 5 a.m."},"ref":{"doc":"FL","page":25}},{"id":"licensing-014","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, when may a 16-year-old drive alone during curfew hours?","o":["When driving to a friend's house","When the roads are empty","When the trip is under 5 miles","When driving to or from work"],"h1":"The law makes an exception for a job.","h2":"A 16-year-old may drive alone during curfew hours only when driving to or from work, or when a licensed driver age 21 or older is with them.","p":"Right. Driving to or from work is allowed during curfew."},"es":{"q":"En Florida, ¿cuándo puede una persona de 16 años manejar sola en las horas restringidas?","o":["Cuando va a la casa de un amigo","Cuando las calles están vacías","Cuando el viaje es de menos de 5 millas","Cuando maneja hacia o desde el trabajo"],"h1":"La ley hace una excepción por el empleo.","h2":"Una persona de 16 años puede manejar sola en las horas restringidas solo cuando va hacia o desde el trabajo, o cuando la acompaña un conductor con licencia de 21 años o más.","p":"Correcto. Se permite manejar hacia o desde el trabajo en esas horas."},"zh":{"q":"在 Florida，16 岁的司机在宵禁时间什么时候可以单独开车？","o":["开车去朋友家时","路上没有车时","路程少于 5 英里时","上班或下班的路上"],"h1":"法律对工作有一个例外。","h2":"16 岁的司机在宵禁时间只能在上班或下班的路上单独开车，或者有一位 21 岁或以上、有驾照的司机陪同。","p":"对。宵禁时间可以开车上班或下班。"},"vi":{"q":"Ở Florida, khi nào thiếu niên 16 tuổi được lái xe một mình trong giờ giới nghiêm?","o":["Khi lái xe đến nhà bạn","Khi đường vắng","Khi chuyến đi ngắn hơn 5 dặm","Khi lái xe đi làm hoặc đi làm về"],"h1":"Luật có một ngoại lệ dành cho công việc.","h2":"Thiếu niên 16 tuổi chỉ được lái xe một mình trong giờ giới nghiêm khi đi làm hoặc đi làm về, hoặc khi có người có bằng lái từ 21 tuổi trở lên đi cùng.","p":"Đúng. Được phép lái xe đi làm hoặc đi làm về trong giờ giới nghiêm."},"tl":{"q":"Sa Florida, kailan puwedeng magmaneho nang mag-isa ang 16 taong gulang sa oras ng curfew?","o":["Kapag papunta sa bahay ng kaibigan","Kapag walang laman ang mga daan","Kapag wala pang 5 milya ang biyahe","Kapag papunta o pauwi mula sa trabaho"],"h1":"May exception ang batas para sa trabaho.","h2":"Ang 16 taong gulang ay puwedeng magmaneho nang mag-isa sa oras ng curfew kapag papunta o pauwi lang siya mula sa trabaho, o kapag kasama niya ang lisensyadong driver na 21 taong gulang o higit pa.","p":"Tama. Puwede ang pagmamaneho papunta o pauwi mula sa trabaho sa oras ng curfew."},"ar":{"q":"في Florida، متى يُسمح لمن عمره 16 سنة بالقيادة وحده في ساعات المنع الليلي؟","o":["عندما يذهب إلى بيت صديق","عندما تكون الطرق فارغة","عندما تكون الرحلة أقل من 5 أميال","عندما يذهب إلى العمل أو يعود منه"],"h1":"القانون يسمح باستثناء من أجل الوظيفة.","h2":"يُسمح لمن عمره 16 سنة بالقيادة وحده في ساعات المنع فقط عندما يذهب إلى العمل أو يعود منه، أو عندما يكون معه سائق مرخّص عمره 21 سنة أو أكثر.","p":"صحيح. الذهاب إلى العمل أو العودة منه مسموح في ساعات المنع."},"ht":{"q":"Nan Florida, ki lè yon moun 16 an ka kondi pou kont li pandan lè kouvrefe a?","o":["Lè l ap kondi al lakay yon zanmi","Lè wout yo vid","Lè vwayaj la mwens pase 5 mil","Lè l ap ale oswa l ap soti travay"],"h1":"Lalwa fè yon eksepsyon pou yon travay.","h2":"Yon moun 16 an ka kondi pou kont li pandan lè kouvrefe a sèlman lè l ap ale oswa l ap soti travay, oswa lè yon chofè ki gen lisans epi ki gen 21 an oswa plis avè l.","p":"Se sa. Ou gen dwa kondi pou ale oswa soti travay pandan kouvrefe a."},"ref":{"doc":"FL","page":25}},{"id":"licensing-015","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, what happens if you get 12 points on your driving record within 12 months?","o":["Your license is suspended for 30 days","You get a warning letter only","Your license is suspended for 1 year","Nothing happens"],"h1":"This is the first and shortest point suspension.","h2":"If you get 12 points within 12 months, your license is suspended for 30 days.","p":"Right. 12 points in 12 months means a 30-day suspension."},"es":{"q":"En Florida, ¿qué pasa si acumula 12 puntos en su récord de manejo dentro de 12 meses?","o":["Le suspenden la licencia por 30 días","Solo recibe una carta de advertencia","Le suspenden la licencia por 1 año","No pasa nada"],"h1":"Es la primera suspensión por puntos y la más corta.","h2":"Si acumula 12 puntos dentro de 12 meses, le suspenden la licencia por 30 días.","p":"Correcto. 12 puntos en 12 meses significa 30 días de suspensión."},"zh":{"q":"在 Florida，如果你在 12 个月内驾驶记录被扣 12 分，会怎么样？","o":["你的驾照被暂停 30 天","你只会收到一封警告信","你的驾照被暂停 1 年","什么事也没有"],"h1":"这是第一种、也是最短的扣分暂停。","h2":"如果你在 12 个月内被扣 12 分，你的驾照会被暂停 30 天。","p":"对。12 个月内扣 12 分，驾照暂停 30 天。"},"vi":{"q":"Ở Florida, điều gì xảy ra nếu bạn bị 12 điểm trong hồ sơ lái xe trong vòng 12 tháng?","o":["Bằng lái của bạn bị đình chỉ 30 ngày","Bạn chỉ nhận một thư cảnh cáo","Bằng lái của bạn bị đình chỉ 1 năm","Không có gì xảy ra"],"h1":"Đây là mức đình chỉ do điểm đầu tiên và ngắn nhất.","h2":"Nếu bạn bị 12 điểm trong vòng 12 tháng, bằng lái của bạn bị đình chỉ 30 ngày.","p":"Đúng. 12 điểm trong 12 tháng nghĩa là bị đình chỉ 30 ngày."},"tl":{"q":"Sa Florida, ano ang mangyayari kung makakuha ka ng 12 points sa iyong driving record sa loob ng 12 buwan?","o":["Masususpinde ang lisensya mo nang 30 araw","Warning letter lang ang matatanggap mo","Masususpinde ang lisensya mo nang 1 taon","Walang mangyayari"],"h1":"Ito ang una at pinakamaikling suspensyon dahil sa points.","h2":"Kung makakuha ka ng 12 points sa loob ng 12 buwan, masususpinde ang lisensya mo nang 30 araw.","p":"Tama. Ang 12 points sa loob ng 12 buwan ay suspensyon nang 30 araw."},"ar":{"q":"في Florida، ماذا يحدث إذا حصلت على 12 نقطة في سجل القيادة خلال 12 شهرًا؟","o":["تُوقف رخصتك لمدة 30 يومًا","تحصل على رسالة تحذير فقط","تُوقف رخصتك لمدة سنة واحدة","لا يحدث شيء"],"h1":"هذا هو أول إيقاف بسبب النقاط، وهو الأقصر.","h2":"إذا حصلت على 12 نقطة خلال 12 شهرًا، تُوقف رخصتك لمدة 30 يومًا.","p":"صحيح. 12 نقطة في 12 شهرًا تعني إيقاف الرخصة 30 يومًا."},"ht":{"q":"Nan Florida, kisa k rive si ou jwenn 12 pwen sou dosye kondi ou nan 12 mwa?","o":["Yo sispann lisans ou pou 30 jou","Ou jwenn yon lèt avètisman sèlman","Yo sispann lisans ou pou 1 an","Anyen pa rive"],"h1":"Se premye sispansyon pou pwen yo, epi se li ki pi kout.","h2":"Si ou jwenn 12 pwen nan 12 mwa, yo sispann lisans ou pou 30 jou.","p":"Se sa. 12 pwen nan 12 mwa vle di yon sispansyon 30 jou."},"ref":{"doc":"FL","page":29}},{"id":"licensing-016","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, what happens if you get 18 points on your driving record within 18 months?","o":["Your license is suspended for 30 days","Your license is suspended for 5 years","Your license is suspended for 3 months","You must only pay a fine"],"h1":"It is longer than the 30-day suspension, but shorter than one year.","h2":"If you get 18 points within 18 months, your license is suspended for 3 months.","p":"Right. 18 points in 18 months means a 3-month suspension."},"es":{"q":"En Florida, ¿qué pasa si acumula 18 puntos en su récord de manejo dentro de 18 meses?","o":["Le suspenden la licencia por 30 días","Le suspenden la licencia por 5 años","Le suspenden la licencia por 3 meses","Solo tiene que pagar una multa"],"h1":"Es más larga que la suspensión de 30 días, pero más corta que un año.","h2":"Si acumula 18 puntos dentro de 18 meses, le suspenden la licencia por 3 meses.","p":"Correcto. 18 puntos en 18 meses significa 3 meses de suspensión."},"zh":{"q":"在 Florida，如果你在 18 个月内驾驶记录被扣 18 分，会怎么样？","o":["你的驾照被暂停 30 天","你的驾照被暂停 5 年","你的驾照被暂停 3 个月","你只需要交罚款"],"h1":"它比 30 天的暂停长，但比一年短。","h2":"如果你在 18 个月内被扣 18 分，你的驾照会被暂停 3 个月。","p":"对。18 个月内扣 18 分，驾照暂停 3 个月。"},"vi":{"q":"Ở Florida, điều gì xảy ra nếu bạn bị 18 điểm trong hồ sơ lái xe trong vòng 18 tháng?","o":["Bằng lái của bạn bị đình chỉ 30 ngày","Bằng lái của bạn bị đình chỉ 5 năm","Bằng lái của bạn bị đình chỉ 3 tháng","Bạn chỉ phải đóng tiền phạt"],"h1":"Thời gian này dài hơn mức đình chỉ 30 ngày, nhưng ngắn hơn một năm.","h2":"Nếu bạn bị 18 điểm trong vòng 18 tháng, bằng lái của bạn bị đình chỉ 3 tháng.","p":"Đúng. 18 điểm trong 18 tháng nghĩa là bị đình chỉ 3 tháng."},"tl":{"q":"Sa Florida, ano ang mangyayari kung makakuha ka ng 18 points sa iyong driving record sa loob ng 18 buwan?","o":["Masususpinde ang lisensya mo nang 30 araw","Masususpinde ang lisensya mo nang 5 taon","Masususpinde ang lisensya mo nang 3 buwan","Multa lang ang babayaran mo"],"h1":"Mas mahaba ito kaysa sa suspensyon nang 30 araw, pero mas maikli kaysa sa isang taon.","h2":"Kung makakuha ka ng 18 points sa loob ng 18 buwan, masususpinde ang lisensya mo nang 3 buwan.","p":"Tama. Ang 18 points sa loob ng 18 buwan ay suspensyon nang 3 buwan."},"ar":{"q":"في Florida، ماذا يحدث إذا حصلت على 18 نقطة في سجل القيادة خلال 18 شهرًا؟","o":["تُوقف رخصتك لمدة 30 يومًا","تُوقف رخصتك لمدة 5 سنوات","تُوقف رخصتك لمدة 3 أشهر","يجب أن تدفع غرامة فقط"],"h1":"المدة أطول من إيقاف الـ 30 يومًا، لكنها أقصر من سنة.","h2":"إذا حصلت على 18 نقطة خلال 18 شهرًا، تُوقف رخصتك لمدة 3 أشهر.","p":"صحيح. 18 نقطة في 18 شهرًا تعني إيقاف الرخصة 3 أشهر."},"ht":{"q":"Nan Florida, kisa k rive si ou jwenn 18 pwen sou dosye kondi ou nan 18 mwa?","o":["Yo sispann lisans ou pou 30 jou","Yo sispann lisans ou pou 5 an","Yo sispann lisans ou pou 3 mwa","Ou dwe peye yon amann sèlman"],"h1":"Li pi long pase sispansyon 30 jou a, men li pi kout pase yon ane.","h2":"Si ou jwenn 18 pwen nan 18 mwa, yo sispann lisans ou pou 3 mwa.","p":"Se sa. 18 pwen nan 18 mwa vle di yon sispansyon 3 mwa."},"ref":{"doc":"FL","page":29}},{"id":"licensing-017","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what happens if you get 24 points on your driving record within 36 months?","o":["Your license is suspended for 3 months","Your license is suspended for 1 year","Your license is suspended for 30 days","You must retake only the vision test"],"h1":"This is the most points, so it brings the longest point suspension.","h2":"If you get 24 points within 36 months, your license is suspended for 1 year.","p":"Right. 24 points in 36 months means a 1-year suspension."},"es":{"q":"En Florida, ¿qué pasa si acumula 24 puntos en su récord de manejo dentro de 36 meses?","o":["Le suspenden la licencia por 3 meses","Le suspenden la licencia por 1 año","Le suspenden la licencia por 30 días","Solo tiene que repetir el examen de la vista"],"h1":"Son la mayor cantidad de puntos, así que traen la suspensión más larga.","h2":"Si acumula 24 puntos dentro de 36 meses, le suspenden la licencia por 1 año.","p":"Correcto. 24 puntos en 36 meses significa 1 año de suspensión."},"zh":{"q":"在 Florida，如果你在 36 个月内驾驶记录被扣 24 分，会怎么样？","o":["你的驾照被暂停 3 个月","你的驾照被暂停 1 年","你的驾照被暂停 30 天","你只需要重新考视力"],"h1":"这是最多的分数，所以扣分暂停的时间也最长。","h2":"如果你在 36 个月内被扣 24 分，你的驾照会被暂停 1 年。","p":"对。36 个月内扣 24 分，驾照暂停 1 年。"},"vi":{"q":"Ở Florida, điều gì xảy ra nếu bạn bị 24 điểm trong hồ sơ lái xe trong vòng 36 tháng?","o":["Bằng lái của bạn bị đình chỉ 3 tháng","Bằng lái của bạn bị đình chỉ 1 năm","Bằng lái của bạn bị đình chỉ 30 ngày","Bạn chỉ phải thi lại phần kiểm tra mắt"],"h1":"Đây là số điểm cao nhất, nên dẫn đến mức đình chỉ do điểm dài nhất.","h2":"Nếu bạn bị 24 điểm trong vòng 36 tháng, bằng lái của bạn bị đình chỉ 1 năm.","p":"Đúng. 24 điểm trong 36 tháng nghĩa là bị đình chỉ 1 năm."},"tl":{"q":"Sa Florida, ano ang mangyayari kung makakuha ka ng 24 points sa iyong driving record sa loob ng 36 na buwan?","o":["Masususpinde ang lisensya mo nang 3 buwan","Masususpinde ang lisensya mo nang 1 taon","Masususpinde ang lisensya mo nang 30 araw","Vision test lang ang uulitin mo"],"h1":"Ito ang pinakamaraming points, kaya ito ang pinakamahabang suspensyon dahil sa points.","h2":"Kung makakuha ka ng 24 points sa loob ng 36 na buwan, masususpinde ang lisensya mo nang 1 taon.","p":"Tama. Ang 24 points sa loob ng 36 na buwan ay suspensyon nang 1 taon."},"ar":{"q":"في Florida، ماذا يحدث إذا حصلت على 24 نقطة في سجل القيادة خلال 36 شهرًا؟","o":["تُوقف رخصتك لمدة 3 أشهر","تُوقف رخصتك لمدة سنة واحدة","تُوقف رخصتك لمدة 30 يومًا","يجب أن تعيد اختبار النظر فقط"],"h1":"هذا أكبر عدد من النقاط، لذلك يأتي معه أطول إيقاف بسبب النقاط.","h2":"إذا حصلت على 24 نقطة خلال 36 شهرًا، تُوقف رخصتك لمدة سنة واحدة.","p":"صحيح. 24 نقطة في 36 شهرًا تعني إيقاف الرخصة سنة واحدة."},"ht":{"q":"Nan Florida, kisa k rive si ou jwenn 24 pwen sou dosye kondi ou nan 36 mwa?","o":["Yo sispann lisans ou pou 3 mwa","Yo sispann lisans ou pou 1 an","Yo sispann lisans ou pou 30 jou","Ou dwe refè egzamen je a sèlman"],"h1":"Se plis pwen yo, kidonk li pote sispansyon pou pwen ki pi long lan.","h2":"Si ou jwenn 24 pwen nan 36 mwa, yo sispann lisans ou pou 1 an.","p":"Se sa. 24 pwen nan 36 mwa vle di yon sispansyon 1 an."},"ref":{"doc":"FL","page":29}},{"id":"licensing-018","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, a driver under 18 gets 6 points within 12 months. What happens?","o":["Nothing until they reach 12 points","They get a free extra license","They must only write a letter","Driving is limited to business purposes only"],"h1":"Young drivers face limits sooner than adults.","h2":"A driver under 18 who gets 6 points within 12 months may drive only for business purposes, such as school or work, for one year.","p":"Right. Six points before 18 limits driving to business purposes only."},"es":{"q":"En Florida, un conductor menor de 18 acumula 6 puntos dentro de 12 meses. ¿Qué pasa?","o":["Nada hasta que llegue a 12 puntos","Recibe una licencia extra gratis","Solo tiene que escribir una carta","Solo puede manejar por motivos de negocio"],"h1":"Los conductores jóvenes tienen límites antes que los adultos.","h2":"Un conductor menor de 18 que acumula 6 puntos dentro de 12 meses solo puede manejar por motivos de negocio, como ir a la escuela o al trabajo, durante un año.","p":"Correcto. Seis puntos antes de los 18 limitan el manejo a motivos de negocio."},"zh":{"q":"在 Florida，一个 18 岁以下的司机在 12 个月内被扣 6 分。会怎么样？","o":["要到 12 分才会有事","他会得到一张免费的额外驾照","他只需要写一封信","只能为了办正事开车"],"h1":"年轻司机比成年人更早受到限制。","h2":"18 岁以下的司机如果在 12 个月内被扣 6 分，一年内只能为了办正事开车，例如上学或上班。","p":"对。18 岁前扣 6 分，就只能为了办正事开车。"},"vi":{"q":"Ở Florida, một tài xế dưới 18 tuổi bị 6 điểm trong vòng 12 tháng. Điều gì xảy ra?","o":["Không có gì cho đến khi bị 12 điểm","Tài xế được thêm một bằng lái miễn phí","Tài xế chỉ phải viết một lá thư","Tài xế chỉ được lái xe cho mục đích công việc"],"h1":"Tài xế trẻ bị giới hạn sớm hơn người lớn.","h2":"Tài xế dưới 18 tuổi bị 6 điểm trong vòng 12 tháng thì chỉ được lái xe cho mục đích công việc, như đi học hoặc đi làm, trong một năm.","p":"Đúng. Bị sáu điểm trước 18 tuổi thì chỉ được lái xe cho mục đích công việc."},"tl":{"q":"Sa Florida, ang driver na wala pang 18 ay nakakuha ng 6 points sa loob ng 12 buwan. Ano ang mangyayari?","o":["Wala, hangga't hindi umaabot sa 12 points","Bibigyan siya ng libreng dagdag na lisensya","Kailangan lang niyang sumulat ng liham","Limitado ang pagmamaneho sa business purposes lang"],"h1":"Mas maaga nagkakaroon ng limitasyon ang mga batang driver kaysa sa mga adult.","h2":"Ang driver na wala pang 18 na nakakuha ng 6 points sa loob ng 12 buwan ay puwedeng magmaneho para sa business purposes lang, gaya ng paaralan o trabaho, nang isang taon.","p":"Tama. Ang anim na points bago mag-18 ay naglilimita ng pagmamaneho sa business purposes lang."},"ar":{"q":"في Florida، سائق عمره أقل من 18 سنة حصل على 6 نقاط خلال 12 شهرًا. ماذا يحدث؟","o":["لا شيء حتى يصل إلى 12 نقطة","يحصل على رخصة إضافية مجانية","يجب أن يكتب رسالة فقط","تصبح القيادة مسموحة لأغراض العمل والدراسة فقط"],"h1":"السائقون الصغار يواجهون القيود أسرع من البالغين.","h2":"السائق الذي عمره أقل من 18 سنة ويحصل على 6 نقاط خلال 12 شهرًا يُسمح له بالقيادة لأغراض العمل والدراسة فقط، مثل المدرسة أو العمل، لمدة سنة واحدة.","p":"صحيح. ست نقاط قبل عمر 18 تحدّ القيادة لأغراض العمل والدراسة فقط."},"ht":{"q":"Nan Florida, yon chofè ki poko gen 18 an jwenn 6 pwen nan 12 mwa. Kisa k rive?","o":["Anyen pa rive jiskaske li rive 12 pwen","Li jwenn yon lòt lisans gratis","Li dwe ekri yon lèt sèlman","Li ka kondi sèlman pou rezon biznis"],"h1":"Jèn chofè yo jwenn limit pi vit pase granmoun yo.","h2":"Yon chofè ki poko gen 18 an epi ki jwenn 6 pwen nan 12 mwa ka kondi sèlman pou rezon biznis, tankou lekòl oswa travay, pandan yon ane.","p":"Se sa. Sis pwen anvan 18 an limite w pou kondi sèlman pou rezon biznis."},"ref":{"doc":"FL","page":29}},{"id":"licensing-019","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, what is the minimum Personal Injury Protection (PIP) insurance a car owner must carry?","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"It is the same amount as the minimum property damage coverage.","h2":"A Florida car owner must carry at least $10,000 of Personal Injury Protection, which helps pay for your own injuries after a crash.","p":"Right. The PIP minimum is $10,000."},"es":{"q":"En Florida, ¿cuál es el seguro mínimo de Protección contra Lesiones Personales (PIP) que debe tener el dueño de un carro?","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"Es la misma cantidad que la cobertura mínima de daños a la propiedad.","h2":"El dueño de un carro en Florida debe tener por lo menos $10,000 de Protección contra Lesiones Personales, que ayuda a pagar sus propias lesiones después de un choque.","p":"Correcto. El mínimo de PIP es $10,000."},"zh":{"q":"在 Florida，车主必须买的个人伤害保障 (PIP) 保险最低是多少？","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"它和财产损失保险的最低金额一样。","h2":"Florida 的车主必须买至少 $10,000 的个人伤害保障 (PIP)，它帮助支付你自己在车祸后的伤害费用。","p":"对。PIP 最低是 $10,000。"},"vi":{"q":"Ở Florida, chủ xe phải có bảo hiểm Bảo vệ Thương tích Cá nhân (PIP) tối thiểu là bao nhiêu?","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"Số tiền này bằng với mức bảo hiểm tối thiểu cho thiệt hại tài sản.","h2":"Chủ xe ở Florida phải có ít nhất $10,000 bảo hiểm Bảo vệ Thương tích Cá nhân, giúp trả chi phí cho thương tích của chính bạn sau tai nạn.","p":"Đúng. Mức PIP tối thiểu là $10,000."},"tl":{"q":"Sa Florida, magkano ang pinakamababang Personal Injury Protection (PIP) insurance na dapat mayroon ang may-ari ng kotse?","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"Pareho ito ng halaga ng pinakamababang coverage para sa pinsala sa ari-arian.","h2":"Ang may-ari ng kotse sa Florida ay dapat may hindi bababa sa $10,000 na Personal Injury Protection, na tumutulong magbayad para sa sarili mong mga pinsala sa katawan pagkatapos ng banggaan.","p":"Tama. Ang pinakamababang PIP ay $10,000."},"ar":{"q":"في Florida، ما أقل مبلغ لتأمين الحماية من الإصابات الشخصية (PIP) يجب أن يكون لدى مالك السيارة؟","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"إنه نفس مبلغ أقل تغطية لأضرار الممتلكات.","h2":"يجب أن يكون لدى مالك السيارة في Florida تأمين حماية من الإصابات الشخصية بمبلغ $10,000 على الأقل، وهو يساعد في دفع تكاليف إصاباتك أنت بعد الحادث.","p":"صحيح. أقل مبلغ لتأمين PIP هو $10,000."},"ht":{"q":"Nan Florida, ki pi piti kantite asirans Personal Injury Protection (PIP) yon mèt machin dwe genyen?","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"Se menm kantite ak pi piti kouvèti pou domaj sou byen moun.","h2":"Yon mèt machin nan Florida dwe gen omwen $10,000 asirans Personal Injury Protection, ki ede peye pou pwòp blesi pa w apre yon aksidan.","p":"Se sa. Minimòm PIP la se $10,000."},"ref":{"doc":"FL","page":23}},{"id":"licensing-020","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, what is the minimum Property Damage Liability (PDL) insurance a car owner must carry?","o":["$1,000","$100,000","$10,000","$2,500"],"h1":"It is the same amount as the minimum PIP coverage.","h2":"A Florida car owner must carry at least $10,000 of Property Damage Liability, which pays for damage you cause to other people's property.","p":"Right. The PDL minimum is $10,000."},"es":{"q":"En Florida, ¿cuál es el seguro mínimo de Responsabilidad por Daños a la Propiedad (PDL) que debe tener el dueño de un carro?","o":["$1,000","$100,000","$10,000","$2,500"],"h1":"Es la misma cantidad que la cobertura mínima de PIP.","h2":"El dueño de un carro en Florida debe tener por lo menos $10,000 de Responsabilidad por Daños a la Propiedad, que paga los daños que usted causa a la propiedad de otras personas.","p":"Correcto. El mínimo de PDL es $10,000."},"zh":{"q":"在 Florida，车主必须买的财产损失责任 (PDL) 保险最低是多少？","o":["$1,000","$100,000","$10,000","$2,500"],"h1":"它和 PIP 保险的最低金额一样。","h2":"Florida 的车主必须买至少 $10,000 的财产损失责任保险 (PDL)，它支付你给别人财产造成的损失。","p":"对。PDL 最低是 $10,000。"},"vi":{"q":"Ở Florida, chủ xe phải có bảo hiểm Trách nhiệm Thiệt hại Tài sản (PDL) tối thiểu là bao nhiêu?","o":["$1,000","$100,000","$10,000","$2,500"],"h1":"Số tiền này bằng với mức PIP tối thiểu.","h2":"Chủ xe ở Florida phải có ít nhất $10,000 bảo hiểm Trách nhiệm Thiệt hại Tài sản, giúp trả cho thiệt hại bạn gây ra cho tài sản của người khác.","p":"Đúng. Mức PDL tối thiểu là $10,000."},"tl":{"q":"Sa Florida, magkano ang pinakamababang Property Damage Liability (PDL) insurance na dapat mayroon ang may-ari ng kotse?","o":["$1,000","$100,000","$10,000","$2,500"],"h1":"Pareho ito ng halaga ng pinakamababang PIP coverage.","h2":"Ang may-ari ng kotse sa Florida ay dapat may hindi bababa sa $10,000 na Property Damage Liability, na nagbabayad para sa pinsalang nagawa mo sa ari-arian ng ibang tao.","p":"Tama. Ang pinakamababang PDL ay $10,000."},"ar":{"q":"في Florida، ما أقل مبلغ لتأمين المسؤولية عن أضرار الممتلكات (PDL) يجب أن يكون لدى مالك السيارة؟","o":["$1,000","$100,000","$10,000","$2,500"],"h1":"إنه نفس مبلغ أقل تغطية لتأمين PIP.","h2":"يجب أن يكون لدى مالك السيارة في Florida تأمين مسؤولية عن أضرار الممتلكات بمبلغ $10,000 على الأقل، وهو يدفع ثمن الضرر الذي تسببه لممتلكات الآخرين.","p":"صحيح. أقل مبلغ لتأمين PDL هو $10,000."},"ht":{"q":"Nan Florida, ki pi piti kantite asirans Property Damage Liability (PDL) yon mèt machin dwe genyen?","o":["$1,000","$100,000","$10,000","$2,500"],"h1":"Se menm kantite ak pi piti kouvèti PIP la.","h2":"Yon mèt machin nan Florida dwe gen omwen $10,000 asirans Property Damage Liability, ki peye pou domaj ou fè sou byen lòt moun.","p":"Se sa. Minimòm PDL la se $10,000."},"ref":{"doc":"FL","page":23}},{"id":"licensing-021","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what should you do with your proof of insurance?","o":["Keep it at home in a safe place","Keep it in the car and show it when an officer asks","Show it only when you renew your license","Mail it to the police every year"],"h1":"An officer may ask for it at a traffic stop or after a crash.","h2":"You must keep proof of insurance with you in the car and show it when a law enforcement officer asks for it.","p":"Right. Keep proof of insurance in the car and show it when asked."},"es":{"q":"En Florida, ¿qué debe hacer con su comprobante de seguro?","o":["Guardarlo en casa en un lugar seguro","Tenerlo en el carro y mostrarlo cuando un oficial lo pida","Mostrarlo solo cuando renueve la licencia","Enviarlo por correo a la policía cada año"],"h1":"Un oficial se lo puede pedir en una parada de tránsito o después de un choque.","h2":"Usted debe tener el comprobante de seguro en el carro y mostrarlo cuando un oficial de la ley se lo pida.","p":"Correcto. Tenga el comprobante de seguro en el carro y muéstrelo cuando se lo pidan."},"zh":{"q":"在 Florida，你的保险证明应该怎么处理？","o":["放在家里安全的地方","放在车里，警察要的时候给他看","只在更新驾照时出示","每年寄给警察"],"h1":"在交通拦停或车祸后，警察可能会要看。","h2":"你必须把保险证明带在车里，执法人员要看的时候给他看。","p":"对。把保险证明放在车里，有人要看时出示。"},"vi":{"q":"Ở Florida, bạn nên làm gì với giấy chứng nhận bảo hiểm của mình?","o":["Cất ở nhà, ở một chỗ an toàn","Để trong xe và đưa ra khi cảnh sát yêu cầu","Chỉ đưa ra khi gia hạn bằng lái","Gửi qua bưu điện cho cảnh sát mỗi năm"],"h1":"Cảnh sát có thể yêu cầu xem giấy này khi chặn xe hoặc sau tai nạn.","h2":"Bạn phải để giấy chứng nhận bảo hiểm trong xe và đưa ra khi nhân viên công lực yêu cầu.","p":"Đúng. Để giấy chứng nhận bảo hiểm trong xe và đưa ra khi được yêu cầu."},"tl":{"q":"Sa Florida, ano ang dapat mong gawin sa iyong proof of insurance (patunay ng insurance)?","o":["Itago ito sa bahay sa ligtas na lugar","Itago ito sa kotse at ipakita kapag hiningi ng pulis","Ipakita lang ito kapag nagre-renew ka ng lisensya","Ipadala ito sa pulis bawat taon"],"h1":"Puwede itong hingin ng pulis kapag pinara ka o pagkatapos ng banggaan.","h2":"Dapat nasa kotse mo ang iyong proof of insurance at ipakita mo ito kapag hiningi ng law enforcement officer.","p":"Tama. Itago ang proof of insurance sa kotse at ipakita kapag hiningi."},"ar":{"q":"في Florida، ماذا يجب أن تفعل بإثبات التأمين؟","o":["احتفظ به في البيت في مكان آمن","احتفظ به في السيارة وأظهره عندما يطلبه الشرطي","أظهره فقط عندما تجدد رخصتك","أرسله بالبريد إلى الشرطة كل سنة"],"h1":"قد يطلبه الشرطي عند إيقافك في الطريق أو بعد حادث.","h2":"يجب أن تحتفظ بإثبات التأمين معك في السيارة، وأن تُظهره عندما يطلبه رجل الشرطة.","p":"صحيح. احتفظ بإثبات التأمين في السيارة وأظهره عند الطلب."},"ht":{"q":"Nan Florida, kisa ou dwe fè ak prèv asirans ou?","o":["Kenbe l lakay ou nan yon bon kote","Kenbe l nan machin nan epi montre l lè yon polis mande l","Montre l sèlman lè w ap renouvle lisans ou","Voye l bay lapolis pa lapòs chak ane"],"h1":"Yon polis ka mande l lè li kanpe w sou wout la oswa apre yon aksidan.","h2":"Ou dwe kenbe prèv asirans ou avè w nan machin nan epi montre l lè yon polis mande w li.","p":"Se sa. Kenbe prèv asirans lan nan machin nan epi montre l lè yo mande l."},"ref":{"doc":"FL","page":23}},{"id":"licensing-022","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, you are in a crash and someone is hurt. What must you do?","o":["Leave and call your insurance later","Drive the injured person home","Wait until the next day to report it","Stay at the scene and call the police"],"h1":"When someone is injured, the law requires an official report right away.","h2":"When a crash injures someone, you must stay at the scene, call the police, and help the injured person get medical care.","p":"Right. If someone is hurt, stay and call the police."},"es":{"q":"En Florida, usted tiene un choque y alguien está herido. ¿Qué debe hacer?","o":["Irse y llamar a su seguro después","Llevar al herido a su casa","Esperar al día siguiente para reportarlo","Quedarse en el lugar y llamar a la policía"],"h1":"Cuando alguien está herido, la ley exige un reporte oficial enseguida.","h2":"Cuando un choque deja a alguien herido, usted debe quedarse en el lugar, llamar a la policía y ayudar a que el herido reciba atención médica.","p":"Correcto. Si alguien está herido, quédese y llame a la policía."},"zh":{"q":"在 Florida，你发生车祸，有人受伤。你必须做什么？","o":["离开，以后再打电话给保险公司","开车送受伤的人回家","等到第二天再报告","留在现场，打电话报警"],"h1":"有人受伤时，法律要求马上做正式报告。","h2":"车祸让人受伤时，你必须留在现场，打电话报警，并帮助受伤的人得到医疗救助。","p":"对。有人受伤时，留下来并报警。"},"vi":{"q":"Ở Florida, bạn bị tai nạn và có người bị thương. Bạn phải làm gì?","o":["Rời đi và gọi cho công ty bảo hiểm sau","Chở người bị thương về nhà","Đợi đến ngày hôm sau mới báo","Ở lại hiện trường và gọi cảnh sát"],"h1":"Khi có người bị thương, luật yêu cầu phải báo cáo chính thức ngay.","h2":"Khi tai nạn làm có người bị thương, bạn phải ở lại hiện trường, gọi cảnh sát, và giúp người bị thương được chăm sóc y tế.","p":"Đúng. Nếu có người bị thương, hãy ở lại và gọi cảnh sát."},"tl":{"q":"Sa Florida, nabangga ka at may nasaktan. Ano ang dapat mong gawin?","o":["Umalis at tumawag sa insurance mo mamaya","Ihatid pauwi ang taong nasaktan","Maghintay hanggang kinabukasan bago i-report","Manatili sa lugar ng banggaan at tumawag sa pulis"],"h1":"Kapag may nasaktan, hinihingi ng batas ang opisyal na report agad.","h2":"Kapag may nasaktan sa banggaan, dapat kang manatili sa lugar, tumawag sa pulis, at tulungan ang nasaktan na makakuha ng medikal na tulong.","p":"Tama. Kapag may nasaktan, manatili at tumawag sa pulis."},"ar":{"q":"في Florida، وقع لك حادث وأصيب شخص. ماذا يجب أن تفعل؟","o":["اذهب واتصل بشركة التأمين لاحقًا","خذ المصاب بالسيارة إلى بيته","انتظر حتى اليوم التالي لتبلّغ عن الحادث","ابقَ في مكان الحادث واتصل بالشرطة"],"h1":"عندما يصاب شخص، يطلب القانون تقريرًا رسميًا فورًا.","h2":"عندما يصاب شخص في حادث، يجب أن تبقى في مكان الحادث، وأن تتصل بالشرطة، وأن تساعد المصاب في الحصول على علاج طبي.","p":"صحيح. إذا أصيب شخص، ابقَ واتصل بالشرطة."},"ht":{"q":"Nan Florida, ou fè yon aksidan epi gen yon moun ki blese. Kisa ou dwe fè?","o":["Ale, epi rele asirans ou pita","Mennen moun ki blese a lakay li","Tann jouk demen pou w deklare l","Rete kote aksidan an epi rele lapolis"],"h1":"Lè yon moun blese, lalwa mande yon rapò ofisyèl touswit.","h2":"Lè yon aksidan blese yon moun, ou dwe rete kote aksidan an, rele lapolis, epi ede moun ki blese a jwenn swen medikal.","p":"Se sa. Si yon moun blese, rete epi rele lapolis."},"ref":{"doc":"FL","page":77}},{"id":"licensing-023","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, what is true about leaving the scene of a crash where someone was hurt?","o":["It is a serious crime and can be a felony","It is allowed if you were not at fault","It is allowed if you are late for work","It is only a small parking fine"],"h1":"Think about how serious the law treats leaving a hurt person behind.","h2":"Leaving the scene of a crash where someone was hurt is a serious crime in Florida and can be a felony, with jail time and loss of your license.","p":"Right. Leaving a crash with injuries is a serious crime."},"es":{"q":"En Florida, ¿qué es cierto sobre irse del lugar de un choque donde alguien resultó herido?","o":["Es un delito grave y puede ser un delito mayor (felony)","Está permitido si usted no tuvo la culpa","Está permitido si va tarde al trabajo","Es solo una multa pequeña de estacionamiento"],"h1":"Piense en lo grave que la ley considera dejar atrás a una persona herida.","h2":"Irse del lugar de un choque donde alguien resultó herido es un delito grave en Florida y puede ser un delito mayor, con cárcel y pérdida de la licencia.","p":"Correcto. Irse de un choque con heridos es un delito grave."},"zh":{"q":"在 Florida，离开有人受伤的车祸现场，哪一个说法是对的？","o":["这是严重的犯罪，可能是重罪","如果不是你的错，就可以离开","如果你上班要迟到了，就可以离开","这只是一张小小的停车罚单"],"h1":"想一想法律怎样严肃地看待丢下受伤的人。","h2":"在 Florida，离开有人受伤的车祸现场是严重的犯罪，可能是重罪，会坐牢并失去驾照。","p":"对。离开有人受伤的车祸现场是严重的犯罪。"},"vi":{"q":"Ở Florida, điều nào đúng về việc bỏ đi khỏi hiện trường tai nạn có người bị thương?","o":["Đó là tội nghiêm trọng và có thể là trọng tội","Được phép nếu bạn không có lỗi","Được phép nếu bạn bị trễ giờ làm","Đó chỉ là một khoản phạt đậu xe nhỏ"],"h1":"Hãy nghĩ xem luật coi việc bỏ lại người bị thương nghiêm trọng đến mức nào.","h2":"Bỏ đi khỏi hiện trường tai nạn có người bị thương là tội nghiêm trọng ở Florida và có thể là trọng tội, có thể bị tù và mất bằng lái.","p":"Đúng. Bỏ đi khỏi tai nạn có người bị thương là tội nghiêm trọng."},"tl":{"q":"Sa Florida, ano ang totoo tungkol sa pag-alis sa lugar ng banggaan kung saan may nasaktan?","o":["Malubhang krimen ito at puwedeng maging felony","Puwede ito kung hindi ikaw ang may kasalanan","Puwede ito kung late ka na sa trabaho","Maliit na multa lang ito, gaya ng sa parking"],"h1":"Isipin kung gaano kabigat ang tingin ng batas sa pag-iwan sa taong nasaktan.","h2":"Ang pag-alis sa lugar ng banggaan kung saan may nasaktan ay malubhang krimen sa Florida at puwedeng maging felony, na may kulong at pagkawala ng lisensya.","p":"Tama. Malubhang krimen ang pag-alis sa banggaan na may nasaktan."},"ar":{"q":"في Florida، ما الصحيح عن ترك مكان حادث أصيب فيه شخص؟","o":["إنه جريمة خطيرة وقد يكون جناية","إنه مسموح إذا لم تكن أنت المخطئ","إنه مسموح إذا كنت متأخرًا عن العمل","إنه مجرد غرامة وقوف صغيرة"],"h1":"فكّر في مدى جدية القانون مع من يترك شخصًا مصابًا.","h2":"ترك مكان حادث أصيب فيه شخص هو جريمة خطيرة في Florida وقد يكون جناية، وعقوبته السجن وفقدان الرخصة.","p":"صحيح. ترك حادث فيه إصابات جريمة خطيرة."},"ht":{"q":"Nan Florida, kisa ki vre lè yon moun kite kote yon aksidan kote gen yon moun ki te blese?","o":["Se yon krim grav, epi li ka yon felony","Ou gen dwa fè l si se pa t fòt ou","Ou gen dwa fè l si ou an reta pou travay","Se sèlman yon ti amann pou pakin"],"h1":"Panse ak jan lalwa pran l oserye lè yon moun kite yon moun ki blese dèyè.","h2":"Kite kote yon aksidan kote yon moun te blese se yon krim grav nan Florida, epi li ka yon felony, ak prizon epi ou ka pèdi lisans ou.","p":"Se sa. Kite yon aksidan kote gen moun ki blese se yon krim grav."},"ref":{"doc":"FL","page":77}},{"id":"licensing-024","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, you hit a parked car and no one is around. What must you do?","o":["Drive away because no one saw it","Wait one hour, then leave","Find the owner or leave a note with your name and address, and report it to police","Report it only if the damage is large"],"h1":"The owner needs a way to contact you.","h2":"If you hit an unattended car, you must find the owner or leave a note with your name and address in a safe place on the car, and report the crash to the police.","p":"Right. Leave your name and address, and tell the police."},"es":{"q":"En Florida, usted choca un carro estacionado y no hay nadie. ¿Qué debe hacer?","o":["Irse porque nadie lo vio","Esperar una hora y luego irse","Buscar al dueño o dejar una nota con su nombre y dirección, y reportarlo a la policía","Reportarlo solo si el daño es grande"],"h1":"El dueño necesita una forma de comunicarse con usted.","h2":"Si choca un carro sin nadie adentro, debe buscar al dueño o dejar una nota con su nombre y dirección en un lugar seguro del carro, y reportar el choque a la policía.","p":"Correcto. Deje su nombre y dirección, y avise a la policía."},"zh":{"q":"在 Florida，你撞到一辆停着的车，周围没有人。你必须做什么？","o":["开走，因为没人看到","等一个小时，然后离开","找到车主，或留下写有你姓名和地址的纸条，并向警察报告","只有损坏很大时才报告"],"h1":"车主需要有办法联系你。","h2":"如果你撞到一辆没有人的车，你必须找到车主，或在车上安全的地方留下写有你姓名和地址的纸条，并向警察报告这次车祸。","p":"对。留下你的姓名和地址，并告诉警察。"},"vi":{"q":"Ở Florida, bạn đụng vào một xe đang đậu và không có ai xung quanh. Bạn phải làm gì?","o":["Lái đi vì không ai nhìn thấy","Đợi một giờ rồi rời đi","Tìm chủ xe hoặc để lại giấy ghi tên và địa chỉ của bạn, và báo cho cảnh sát","Chỉ báo nếu hư hỏng lớn"],"h1":"Chủ xe cần có cách để liên lạc với bạn.","h2":"Nếu bạn đụng vào một xe không có người trông, bạn phải tìm chủ xe hoặc để lại giấy ghi tên và địa chỉ của bạn ở chỗ an toàn trên xe, và báo tai nạn cho cảnh sát.","p":"Đúng. Để lại tên và địa chỉ, và báo cho cảnh sát."},"tl":{"q":"Sa Florida, nabangga mo ang isang nakaparadang kotse at walang tao sa paligid. Ano ang dapat mong gawin?","o":["Umalis dahil walang nakakita","Maghintay ng isang oras, saka umalis","Hanapin ang may-ari o mag-iwan ng sulat na may pangalan at address mo, at i-report sa pulis","I-report lang kung malaki ang sira"],"h1":"Kailangan ng may-ari ng paraan para makontak ka.","h2":"Kung nabangga mo ang kotseng walang tao, dapat mong hanapin ang may-ari o mag-iwan ng sulat na may pangalan at address mo sa ligtas na lugar sa kotse, at i-report ang banggaan sa pulis.","p":"Tama. Iwan ang pangalan at address mo, at sabihin sa pulis."},"ar":{"q":"في Florida، صدمت سيارة واقفة ولا يوجد أحد حولها. ماذا يجب أن تفعل؟","o":["اذهب لأن لا أحد رأى ذلك","انتظر ساعة واحدة ثم اذهب","ابحث عن المالك أو اترك ورقة فيها اسمك وعنوانك، وبلّغ الشرطة","بلّغ فقط إذا كان الضرر كبيرًا"],"h1":"المالك يحتاج إلى طريقة للتواصل معك.","h2":"إذا صدمت سيارة ليس فيها أحد، يجب أن تجد المالك أو تترك ورقة فيها اسمك وعنوانك في مكان آمن على السيارة، وأن تبلّغ الشرطة عن الحادث.","p":"صحيح. اترك اسمك وعنوانك، وأخبر الشرطة."},"ht":{"q":"Nan Florida, ou frape yon machin ki pake epi pa gen pèsonn la. Kisa ou dwe fè?","o":["Ale paske pèsonn pa wè sa","Tann inèdtan, epi ale","Chèche mèt la oswa kite yon nòt ak non ou ak adrès ou, epi deklare l bay lapolis","Deklare l sèlman si domaj la gwo"],"h1":"Mèt machin nan bezwen yon fason pou l kontakte w.","h2":"Si ou frape yon machin ki pa gen pèsonn ladan l, ou dwe chèche mèt la oswa kite yon nòt ak non ou ak adrès ou nan yon kote ki an sekirite sou machin nan, epi deklare aksidan an bay lapolis.","p":"Se sa. Kite non ou ak adrès ou, epi di lapolis sa."},"ref":{"doc":"FL","page":77}},{"id":"licensing-025","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, after a minor crash with no injuries, the cars can still be driven. What should you do?","o":["Leave the cars where they stopped","Move the cars out of the travel lanes","Drive home without talking to anyone","Stand in the road to direct traffic"],"h1":"Blocking traffic can cause a second crash.","h2":"If no one is hurt and the cars can be driven, move them out of the travel lanes to a safe place, then exchange information.","p":"Right. Move the cars out of traffic if no one is hurt."},"es":{"q":"En Florida, después de un choque leve sin heridos, los carros todavía pueden andar. ¿Qué debe hacer?","o":["Dejar los carros donde quedaron","Sacar los carros de los carriles de tránsito","Irse a casa sin hablar con nadie","Pararse en la calle para dirigir el tráfico"],"h1":"Bloquear el tráfico puede causar un segundo choque.","h2":"Si nadie está herido y los carros pueden andar, sáquelos de los carriles de tránsito a un lugar seguro y después intercambie información.","p":"Correcto. Si nadie está herido, saque los carros del tráfico."},"zh":{"q":"在 Florida，一次小车祸后没有人受伤，车还能开。你应该做什么？","o":["把车留在停下的地方","把车移出行车道","不和任何人说话就开回家","站在路中间指挥交通"],"h1":"挡住交通可能引起第二次车祸。","h2":"如果没有人受伤，车也还能开，就把车移出行车道，开到安全的地方，然后交换资料。","p":"对。没有人受伤时，把车移出车流。"},"vi":{"q":"Ở Florida, sau một tai nạn nhẹ không ai bị thương, các xe vẫn còn chạy được. Bạn nên làm gì?","o":["Để các xe ở nguyên chỗ dừng","Đưa các xe ra khỏi làn xe chạy","Lái về nhà mà không nói chuyện với ai","Đứng giữa đường để điều khiển giao thông"],"h1":"Chắn đường có thể gây ra tai nạn thứ hai.","h2":"Nếu không ai bị thương và các xe còn chạy được, hãy đưa xe ra khỏi làn xe chạy đến chỗ an toàn, rồi trao đổi thông tin.","p":"Đúng. Đưa xe ra khỏi dòng xe nếu không ai bị thương."},"tl":{"q":"Sa Florida, pagkatapos ng maliit na banggaan na walang nasaktan, puwede pang imaneho ang mga kotse. Ano ang dapat mong gawin?","o":["Iwan ang mga kotse kung saan sila huminto","Ilipat ang mga kotse palabas ng mga lane na dinadaanan","Umuwi nang hindi kumakausap ng kahit sino","Tumayo sa daan para ayusin ang trapiko"],"h1":"Ang pagharang sa trapiko ay puwedeng magdulot ng pangalawang banggaan.","h2":"Kung walang nasaktan at puwede pang imaneho ang mga kotse, ilipat ang mga ito palabas ng mga lane na dinadaanan papunta sa ligtas na lugar, saka magpalitan ng impormasyon.","p":"Tama. Ilipat ang mga kotse palabas ng trapiko kung walang nasaktan."},"ar":{"q":"في Florida، بعد حادث بسيط بدون إصابات، ما زالت السيارات تستطيع السير. ماذا يجب أن تفعل؟","o":["اترك السيارات حيث توقفت","أبعد السيارات عن مسارات السير","اذهب إلى البيت بدون أن تتكلم مع أحد","قف في الطريق لتنظّم حركة السير"],"h1":"إغلاق الطريق قد يسبب حادثًا ثانيًا.","h2":"إذا لم يُصب أحد وكانت السيارات تستطيع السير، أبعدها عن مسارات السير إلى مكان آمن، ثم تبادلوا المعلومات.","p":"صحيح. أبعد السيارات عن حركة السير إذا لم يُصب أحد."},"ht":{"q":"Nan Florida, apre yon ti aksidan san moun blese, machin yo ka toujou woule. Kisa ou ta dwe fè?","o":["Kite machin yo kote yo te kanpe a","Deplase machin yo soti nan liy kote machin ap pase yo","Kondi al lakay ou san w pa pale ak pèsonn","Kanpe nan mitan wout la pou dirije sikilasyon an"],"h1":"Bloke sikilasyon an ka lakòz yon dezyèm aksidan.","h2":"Si pèsonn pa blese epi machin yo ka woule, deplase yo soti nan liy kote machin ap pase yo pou ale nan yon kote ki an sekirite, epi apre sa, echanje enfòmasyon.","p":"Se sa. Si pèsonn pa blese, deplase machin yo soti nan sikilasyon an."},"ref":{"doc":"FL","page":77}},{"id":"licensing-026","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, after a crash, what information must you give to the other driver?","o":["Only your phone number","Your bank account number","Nothing, unless they are hurt","Your name, address, and vehicle registration, and show your license"],"h1":"The other driver needs to know who you are and which car was involved.","h2":"After a crash, you must give your name, address, and vehicle registration number, and show your driver license to the other driver.","p":"Right. Share your name, address, registration, and license."},"es":{"q":"En Florida, después de un choque, ¿qué información debe darle al otro conductor?","o":["Solo su número de teléfono","Su número de cuenta bancaria","Nada, a menos que esté herido","Su nombre, dirección y registro del vehículo, y mostrar su licencia"],"h1":"El otro conductor necesita saber quién es usted y qué carro estuvo involucrado.","h2":"Después de un choque, usted debe dar su nombre, dirección y número de registro del vehículo, y mostrar su licencia de conducir al otro conductor.","p":"Correcto. Dé su nombre, dirección, registro y licencia."},"zh":{"q":"在 Florida，车祸后你必须给另一位司机什么资料？","o":["只给你的电话号码","你的银行账号","什么都不用给，除非他受伤","你的姓名、地址和车辆登记，并出示你的驾照"],"h1":"另一位司机需要知道你是谁，以及是哪辆车。","h2":"车祸后，你必须把你的姓名、地址和车辆登记号码告诉另一位司机，并给他看你的驾照。","p":"对。告诉对方你的姓名、地址、车辆登记，并出示驾照。"},"vi":{"q":"Ở Florida, sau tai nạn, bạn phải đưa thông tin gì cho tài xế kia?","o":["Chỉ số điện thoại của bạn","Số tài khoản ngân hàng của bạn","Không đưa gì, trừ khi họ bị thương","Tên, địa chỉ, giấy đăng ký xe của bạn, và cho xem bằng lái"],"h1":"Tài xế kia cần biết bạn là ai và xe nào liên quan.","h2":"Sau tai nạn, bạn phải đưa tên, địa chỉ, và số đăng ký xe của bạn, và cho tài xế kia xem bằng lái của bạn.","p":"Đúng. Đưa tên, địa chỉ, giấy đăng ký xe, và bằng lái."},"tl":{"q":"Sa Florida, pagkatapos ng banggaan, anong impormasyon ang dapat mong ibigay sa kabilang driver?","o":["Ang phone number mo lang","Ang bank account number mo","Wala, maliban kung nasaktan siya","Ang pangalan, address, at vehicle registration mo, at ipakita ang lisensya mo"],"h1":"Kailangang malaman ng kabilang driver kung sino ka at kung aling kotse ang nasangkot.","h2":"Pagkatapos ng banggaan, dapat mong ibigay ang pangalan, address, at vehicle registration number mo, at ipakita ang iyong driver license sa kabilang driver.","p":"Tama. Ibigay ang pangalan, address, registration, at lisensya mo."},"ar":{"q":"في Florida، بعد حادث، ما المعلومات التي يجب أن تعطيها للسائق الآخر؟","o":["رقم هاتفك فقط","رقم حسابك في البنك","لا شيء، إلا إذا أصيب","اسمك وعنوانك وتسجيل السيارة، وأن تُظهر رخصتك"],"h1":"السائق الآخر يحتاج أن يعرف من أنت وأي سيارة كانت في الحادث.","h2":"بعد الحادث، يجب أن تعطي السائق الآخر اسمك وعنوانك ورقم تسجيل السيارة، وأن تُظهر له رخصة القيادة.","p":"صحيح. أعطِ اسمك وعنوانك وتسجيل السيارة ورخصتك."},"ht":{"q":"Nan Florida, apre yon aksidan, ki enfòmasyon ou dwe bay lòt chofè a?","o":["Nimewo telefòn ou sèlman","Nimewo kont labank ou","Anyen, sof si li blese","Non ou, adrès ou, ak anrejistreman machin nan, epi montre lisans ou"],"h1":"Lòt chofè a bezwen konnen kiyès ou ye ak ki machin ki te nan aksidan an.","h2":"Apre yon aksidan, ou dwe bay lòt chofè a non ou, adrès ou, ak nimewo anrejistreman machin nan, epi montre l lisans kondi ou.","p":"Se sa. Bay non ou, adrès ou, anrejistreman an, ak lisans ou."},"ref":{"doc":"FL","page":77}},{"id":"licensing-027","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, you had a crash, and the law did not require a police report. What must you do?","o":["Send a written crash report to the state within 10 days","Do nothing at all","Report it only when you renew your license","Wait a year, then report it"],"h1":"When no officer writes a report, the job falls to you, and there is a short deadline.","h2":"If no police report was required for your crash, you must send your own written crash report to the state within 10 days.","p":"Right. Send your own crash report within 10 days."},"es":{"q":"En Florida, usted tuvo un choque y la ley no exigía un reporte de la policía. ¿Qué debe hacer?","o":["Enviar un reporte escrito del choque al estado dentro de 10 días","No hacer nada","Reportarlo solo cuando renueve la licencia","Esperar un año y luego reportarlo"],"h1":"Cuando ningún oficial hace el reporte, la tarea es suya, y el plazo es corto.","h2":"Si su choque no necesitaba un reporte de la policía, usted debe enviar su propio reporte escrito del choque al estado dentro de 10 días.","p":"Correcto. Envíe su propio reporte del choque dentro de 10 días."},"zh":{"q":"在 Florida，你发生了车祸，法律没有要求警察报告。你必须做什么？","o":["10 天内向州政府寄一份书面车祸报告","什么都不用做","只在更新驾照时报告","等一年再报告"],"h1":"没有警察写报告时，这件事就由你来做，而且期限很短。","h2":"如果你的车祸不需要警察报告，你必须在 10 天内自己向州政府寄一份书面车祸报告。","p":"对。10 天内寄出你自己的车祸报告。"},"vi":{"q":"Ở Florida, bạn bị tai nạn, và luật không yêu cầu cảnh sát lập biên bản. Bạn phải làm gì?","o":["Gửi bản báo cáo tai nạn bằng văn bản cho tiểu bang trong vòng 10 ngày","Không cần làm gì cả","Chỉ báo khi gia hạn bằng lái","Đợi một năm rồi mới báo"],"h1":"Khi không có cảnh sát lập biên bản, việc này là của bạn, và thời hạn rất ngắn.","h2":"Nếu tai nạn của bạn không cần cảnh sát lập biên bản, bạn phải tự gửi bản báo cáo tai nạn bằng văn bản cho tiểu bang trong vòng 10 ngày.","p":"Đúng. Tự gửi báo cáo tai nạn trong vòng 10 ngày."},"tl":{"q":"Sa Florida, nagkaroon ka ng banggaan, at hindi hinihingi ng batas ang police report. Ano ang dapat mong gawin?","o":["Magpadala ng nakasulat na crash report sa estado sa loob ng 10 araw","Wala kang kailangang gawin","I-report lang ito kapag nagre-renew ka ng lisensya","Maghintay ng isang taon, saka i-report"],"h1":"Kapag walang pulis na gumawa ng report, ikaw ang may tungkulin, at maikli ang deadline.","h2":"Kung hindi kailangan ang police report para sa banggaan mo, dapat kang magpadala ng sarili mong nakasulat na crash report sa estado sa loob ng 10 araw.","p":"Tama. Magpadala ng sarili mong crash report sa loob ng 10 araw."},"ar":{"q":"في Florida، وقع لك حادث، والقانون لم يطلب تقريرًا من الشرطة. ماذا يجب أن تفعل؟","o":["أرسل تقريرًا مكتوبًا عن الحادث إلى الولاية خلال 10 أيام","لا تفعل أي شيء","بلّغ فقط عندما تجدد رخصتك","انتظر سنة ثم بلّغ"],"h1":"عندما لا يكتب الشرطي تقريرًا، تصبح المهمة عليك، والمهلة قصيرة.","h2":"إذا لم يكن تقرير الشرطة مطلوبًا لحادثك، يجب أن ترسل تقريرك المكتوب عن الحادث إلى الولاية خلال 10 أيام.","p":"صحيح. أرسل تقريرك عن الحادث خلال 10 أيام."},"ht":{"q":"Nan Florida, ou te fè yon aksidan, epi lalwa pa t mande yon rapò lapolis. Kisa ou dwe fè?","o":["Voye yon rapò aksidan ekri bay leta nan 10 jou","Pa fè anyen ditou","Deklare l sèlman lè w ap renouvle lisans ou","Tann yon ane, epi deklare l"],"h1":"Lè pa gen polis ki ekri yon rapò, se ou ki gen travay la, epi ou pa gen anpil tan.","h2":"Si yo pa t mande yon rapò lapolis pou aksidan ou a, ou dwe voye pwòp rapò aksidan ekri pa w bay leta nan 10 jou.","p":"Se sa. Voye pwòp rapò aksidan pa w nan 10 jou."},"ref":{"doc":"FL","page":77}},{"id":"licensing-028","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, what does the implied consent law mean?","o":["You must agree to let police search your phone","You agree to pay any ticket without going to court","By driving, you agree to be tested for alcohol or drugs if lawfully arrested","Your passengers agree to be tested too"],"h1":"You gave this agreement when you accepted your driver license.","h2":"Implied consent means that by driving in Florida, you agree to take a breath, blood, or urine test if you are lawfully arrested for impaired driving.","p":"Right. Driving means you agree to alcohol and drug testing."},"es":{"q":"En Florida, ¿qué significa la ley de consentimiento implícito?","o":["Debe permitir que la policía revise su teléfono","Acepta pagar cualquier multa sin ir a la corte","Al manejar, usted acepta hacerse pruebas de alcohol o drogas si lo arrestan legalmente","Sus pasajeros también aceptan hacerse pruebas"],"h1":"Usted dio este acuerdo cuando aceptó su licencia de conducir.","h2":"Consentimiento implícito significa que, al manejar en Florida, usted acepta hacerse una prueba de aliento, sangre u orina si lo arrestan legalmente por manejar bajo los efectos.","p":"Correcto. Manejar significa aceptar las pruebas de alcohol y drogas."},"zh":{"q":"在 Florida，“默示同意”法律是什么意思？","o":["你必须同意让警察搜查你的手机","你同意不上法庭就交任何罚单","只要开车，就表示你同意在被合法逮捕时接受酒精或毒品检测","你的乘客也同意接受检测"],"h1":"你在接受驾照时就已经做了这个同意。","h2":"默示同意的意思是：在 Florida 开车，就表示你同意在因酒后或药后驾驶被合法逮捕时，接受呼气、血液或尿液检测。","p":"对。开车就表示你同意接受酒精和毒品检测。"},"vi":{"q":"Ở Florida, luật đồng ý ngầm định (implied consent) có nghĩa là gì?","o":["Bạn phải đồng ý cho cảnh sát lục soát điện thoại của bạn","Bạn đồng ý trả mọi giấy phạt mà không ra tòa","Khi lái xe, bạn đồng ý được kiểm tra rượu bia hoặc ma túy nếu bị bắt hợp pháp","Hành khách của bạn cũng đồng ý được kiểm tra"],"h1":"Bạn đã đưa ra sự đồng ý này khi nhận bằng lái.","h2":"Luật đồng ý ngầm định có nghĩa là khi lái xe ở Florida, bạn đồng ý làm xét nghiệm hơi thở, máu, hoặc nước tiểu nếu bạn bị bắt hợp pháp vì lái xe khi bị ảnh hưởng.","p":"Đúng. Lái xe nghĩa là bạn đồng ý được kiểm tra rượu bia và ma túy."},"tl":{"q":"Sa Florida, ano ang ibig sabihin ng implied consent law?","o":["Dapat kang pumayag na halughugin ng pulis ang phone mo","Pumapayag kang magbayad ng kahit anong ticket nang hindi pumupunta sa korte","Sa pagmamaneho, pumapayag kang ma-test para sa alak o droga kung legal kang inaresto","Pumapayag din ang mga pasahero mo na ma-test"],"h1":"Ibinigay mo ang pagpayag na ito nang tanggapin mo ang iyong driver license.","h2":"Ang implied consent ay nangangahulugang sa pagmamaneho sa Florida, pumapayag kang kumuha ng breath, blood, o urine test kung legal kang inaresto dahil sa impaired driving.","p":"Tama. Ang pagmamaneho ay nangangahulugang pumapayag ka sa test para sa alak at droga."},"ar":{"q":"في Florida، ما معنى قانون الموافقة الضمنية؟","o":["يجب أن توافق على أن تفتش الشرطة هاتفك","توافق على دفع أي مخالفة بدون الذهاب إلى المحكمة","بمجرد أنك تقود، أنت توافق على فحص الكحول أو المخدرات إذا اعتُقلت بشكل قانوني","الركاب معك يوافقون على الفحص أيضًا"],"h1":"أنت أعطيت هذه الموافقة عندما قبلت رخصة القيادة.","h2":"الموافقة الضمنية تعني أنك بمجرد أن تقود في Florida، توافق على فحص النَّفَس أو الدم أو البول إذا اعتُقلت بشكل قانوني بسبب القيادة تحت التأثير.","p":"صحيح. القيادة تعني أنك توافق على فحص الكحول والمخدرات."},"ht":{"q":"Nan Florida, kisa lwa konsantman enplisit la (implied consent) vle di?","o":["Ou dwe kite lapolis fouye telefòn ou","Ou dakò peye nenpòt kontravansyon san w pa al nan tribinal","Lè ou kondi, ou dakò pou yo teste w pou alkòl oswa dwòg si yo arete w legalman","Pasaje ou yo dakò pou yo teste yo tou"],"h1":"Ou te bay akò sa a lè ou te aksepte lisans kondi ou.","h2":"Konsantman enplisit vle di ke lè ou kondi nan Florida, ou dakò pran yon tès souf, san, oswa pipi si yo arete w legalman paske ou t ap kondi sou enfliyans.","p":"Se sa. Lè ou kondi, ou dakò pou yo teste w pou alkòl ak dwòg."},"ref":{"doc":"FL","page":25}},{"id":"licensing-029","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what happens the first time you refuse a lawful breath, blood, or urine test?","o":["Nothing, refusing is your right","Your license is suspended for 1 year","Your license is suspended for 10 days","You get a warning only"],"h1":"Refusing has a cost, even if you were not proven drunk.","h2":"If you refuse a lawful test for the first time, your license is suspended for 1 year.","p":"Right. A first refusal means a 1-year suspension."},"es":{"q":"En Florida, ¿qué pasa la primera vez que se niega a una prueba legal de aliento, sangre u orina?","o":["Nada, negarse es su derecho","Le suspenden la licencia por 1 año","Le suspenden la licencia por 10 días","Solo recibe una advertencia"],"h1":"Negarse tiene un costo, aunque no se pruebe que estaba borracho.","h2":"Si se niega por primera vez a una prueba legal, le suspenden la licencia por 1 año.","p":"Correcto. La primera negativa significa 1 año de suspensión."},"zh":{"q":"在 Florida，你第一次拒绝合法的呼气、血液或尿液检测，会怎么样？","o":["什么事也没有，拒绝是你的权利","你的驾照被暂停 1 年","你的驾照被暂停 10 天","你只会收到警告"],"h1":"拒绝是有代价的，即使没有证明你喝醉了。","h2":"如果你第一次拒绝合法的检测，你的驾照会被暂停 1 年。","p":"对。第一次拒绝，驾照暂停 1 年。"},"vi":{"q":"Ở Florida, điều gì xảy ra lần đầu tiên bạn từ chối xét nghiệm hơi thở, máu, hoặc nước tiểu hợp pháp?","o":["Không có gì, từ chối là quyền của bạn","Bằng lái của bạn bị đình chỉ 1 năm","Bằng lái của bạn bị đình chỉ 10 ngày","Bạn chỉ bị cảnh cáo"],"h1":"Từ chối sẽ có hậu quả, dù chưa chứng minh được bạn say.","h2":"Nếu bạn từ chối xét nghiệm hợp pháp lần đầu, bằng lái của bạn bị đình chỉ 1 năm.","p":"Đúng. Từ chối lần đầu nghĩa là bị đình chỉ 1 năm."},"tl":{"q":"Sa Florida, ano ang mangyayari sa unang beses na tumanggi ka sa legal na breath, blood, o urine test?","o":["Wala, karapatan mong tumanggi","Masususpinde ang lisensya mo nang 1 taon","Masususpinde ang lisensya mo nang 10 araw","Warning lang ang makukuha mo"],"h1":"May kapalit ang pagtanggi, kahit hindi napatunayang lasing ka.","h2":"Kung tumanggi ka sa legal na test sa unang beses, masususpinde ang lisensya mo nang 1 taon.","p":"Tama. Ang unang pagtanggi ay suspensyon nang 1 taon."},"ar":{"q":"في Florida، ماذا يحدث في المرة الأولى التي ترفض فيها فحصًا قانونيًا للنَّفَس أو الدم أو البول؟","o":["لا شيء، الرفض حقك","تُوقف رخصتك لمدة سنة واحدة","تُوقف رخصتك لمدة 10 أيام","تحصل على تحذير فقط"],"h1":"الرفض له ثمن، حتى إذا لم يثبت أنك كنت سكرانًا.","h2":"إذا رفضت فحصًا قانونيًا للمرة الأولى، تُوقف رخصتك لمدة سنة واحدة.","p":"صحيح. الرفض الأول يعني إيقاف الرخصة سنة واحدة."},"ht":{"q":"Nan Florida, kisa k rive premye fwa ou refize yon tès souf, san, oswa pipi ki legal?","o":["Anyen, ou gen dwa refize","Yo sispann lisans ou pou 1 an","Yo sispann lisans ou pou 10 jou","Ou jwenn yon avètisman sèlman"],"h1":"Refize gen yon pri, menm si yo pa pwouve ou te sou.","h2":"Si ou refize yon tès legal pou premye fwa, yo sispann lisans ou pou 1 an.","p":"Se sa. Yon premye refi vle di yon sispansyon 1 an."},"ref":{"doc":"FL","page":25}},{"id":"licensing-030","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, you already refused a test once before. What happens if you refuse again?","o":["A 30-day suspension only","Nothing more than the first time","A small fine only","An 18-month suspension, and the refusal is a crime"],"h1":"A second refusal is treated more harshly than the first.","h2":"If your license was suspended before for refusing, a second refusal brings an 18-month suspension, and the refusal itself is a misdemeanor crime.","p":"Right. A second refusal means 18 months and a criminal charge."},"es":{"q":"En Florida, usted ya se negó a una prueba antes. ¿Qué pasa si se niega otra vez?","o":["Solo una suspensión de 30 días","Nada más que la primera vez","Solo una multa pequeña","Una suspensión de 18 meses, y negarse es un delito"],"h1":"La segunda negativa se castiga más fuerte que la primera.","h2":"Si antes le suspendieron la licencia por negarse, una segunda negativa trae una suspensión de 18 meses, y negarse es en sí un delito menor.","p":"Correcto. La segunda negativa significa 18 meses y un cargo criminal."},"zh":{"q":"在 Florida，你以前已经拒绝过一次检测。如果你再拒绝，会怎么样？","o":["只暂停 30 天","和第一次一样，不会更多","只有一小笔罚款","暂停 18 个月，而且拒绝本身就是犯罪"],"h1":"第二次拒绝会比第一次处罚得更重。","h2":"如果你以前因为拒绝检测被暂停过驾照，第二次拒绝会让驾照暂停 18 个月，而且拒绝本身就是轻罪。","p":"对。第二次拒绝，驾照暂停 18 个月，还会被刑事起诉。"},"vi":{"q":"Ở Florida, bạn đã từng từ chối xét nghiệm một lần. Điều gì xảy ra nếu bạn từ chối lần nữa?","o":["Chỉ bị đình chỉ 30 ngày","Không nặng hơn lần đầu","Chỉ bị phạt tiền nhỏ","Bị đình chỉ 18 tháng, và việc từ chối là một tội"],"h1":"Từ chối lần thứ hai bị xử nặng hơn lần đầu.","h2":"Nếu bằng lái của bạn đã từng bị đình chỉ vì từ chối, lần từ chối thứ hai sẽ bị đình chỉ 18 tháng, và chính việc từ chối là một tội nhẹ (misdemeanor).","p":"Đúng. Từ chối lần thứ hai nghĩa là 18 tháng và bị buộc tội hình sự."},"tl":{"q":"Sa Florida, tumanggi ka na sa test minsan noon. Ano ang mangyayari kung tumanggi ka ulit?","o":["Suspensyon nang 30 araw lang","Wala nang higit pa sa unang beses","Maliit na multa lang","Suspensyon nang 18 buwan, at krimen ang pagtanggi"],"h1":"Mas mabigat ang parusa sa pangalawang pagtanggi kaysa sa una.","h2":"Kung nasuspinde na ang lisensya mo dati dahil sa pagtanggi, ang pangalawang pagtanggi ay magdudulot ng suspensyon nang 18 buwan, at ang pagtanggi mismo ay krimen na misdemeanor.","p":"Tama. Ang pangalawang pagtanggi ay 18 buwan at kasong kriminal."},"ar":{"q":"في Florida، أنت رفضت فحصًا مرة من قبل. ماذا يحدث إذا رفضت مرة أخرى؟","o":["إيقاف لمدة 30 يومًا فقط","لا شيء أكثر من المرة الأولى","غرامة صغيرة فقط","إيقاف لمدة 18 شهرًا، والرفض يصبح جريمة"],"h1":"الرفض الثاني يُعامل بشدة أكبر من الأول.","h2":"إذا أوقفت رخصتك من قبل بسبب الرفض، فإن الرفض الثاني يؤدي إلى إيقاف لمدة 18 شهرًا، والرفض نفسه يصبح جنحة.","p":"صحيح. الرفض الثاني يعني 18 شهرًا وتهمة جنائية."},"ht":{"q":"Nan Florida, ou te deja refize yon tès yon fwa anvan. Kisa k rive si ou refize ankò?","o":["Yon sispansyon 30 jou sèlman","Anyen plis pase premye fwa a","Yon ti amann sèlman","Yon sispansyon 18 mwa, epi refi a se yon krim"],"h1":"Yo trete yon dezyèm refi pi di pase premye a.","h2":"Si yo te deja sispann lisans ou paske ou te refize, yon dezyèm refi pote yon sispansyon 18 mwa, epi refi a li menm se yon krim (misdemeanor).","p":"Se sa. Yon dezyèm refi vle di 18 mwa ak yon akizasyon kriminèl."},"ref":{"doc":"FL","page":26}},{"id":"licensing-031","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, a driver age 21 or older is legally drunk at what blood alcohol level?","o":["0.08 or higher","0.02 or higher","0.04 or higher","0.15 or higher"],"h1":"This is the standard limit for adult drivers of regular cars.","h2":"A driver age 21 or older is driving under the influence with a blood alcohol level of 0.08 or higher, and can also be charged with less if impaired.","p":"Right. For adults, the limit is 0.08."},"es":{"q":"En Florida, ¿a qué nivel de alcohol en la sangre se considera legalmente borracho a un conductor de 21 años o más?","o":["0.08 o más","0.02 o más","0.04 o más","0.15 o más"],"h1":"Es el límite normal para adultos que manejan carros comunes.","h2":"Un conductor de 21 años o más maneja bajo los efectos del alcohol con un nivel de 0.08 o más, y también puede recibir un cargo con menos si está afectado.","p":"Correcto. Para adultos, el límite es 0.08."},"zh":{"q":"在 Florida，21 岁或以上的司机，血液酒精浓度达到多少在法律上算醉酒？","o":["0.08 或更高","0.02 或更高","0.04 或更高","0.15 或更高"],"h1":"这是成年人开普通汽车的标准上限。","h2":"21 岁或以上的司机，血液酒精浓度达到 0.08 或更高，就是酒后驾驶；如果已经受到影响，浓度更低也可能被起诉。","p":"对。成年人的上限是 0.08。"},"vi":{"q":"Ở Florida, tài xế từ 21 tuổi trở lên bị coi là say theo luật khi nồng độ cồn trong máu ở mức nào?","o":["0.08 trở lên","0.02 trở lên","0.04 trở lên","0.15 trở lên"],"h1":"Đây là giới hạn chuẩn cho người lớn lái xe thông thường.","h2":"Tài xế từ 21 tuổi trở lên bị coi là lái xe khi bị ảnh hưởng nếu nồng độ cồn trong máu từ 0.08 trở lên, và vẫn có thể bị buộc tội ở mức thấp hơn nếu khả năng lái bị suy giảm.","p":"Đúng. Với người lớn, giới hạn là 0.08."},"tl":{"q":"Sa Florida, ang driver na 21 taong gulang o higit pa ay legal na lasing sa anong blood alcohol level?","o":["0.08 o higit pa","0.02 o higit pa","0.04 o higit pa","0.15 o higit pa"],"h1":"Ito ang karaniwang limit para sa mga adult na driver ng ordinaryong kotse.","h2":"Ang driver na 21 taong gulang o higit pa ay nagmamaneho nang lasing (DUI) kapag ang blood alcohol level niya ay 0.08 o higit pa, at puwede rin siyang makasuhan kahit mas mababa kung apektado na siya.","p":"Tama. Para sa mga adult, ang limit ay 0.08."},"ar":{"q":"في Florida، السائق الذي عمره 21 سنة أو أكثر يُعتبر سكرانًا قانونيًا عند أي نسبة كحول في الدم؟","o":["0.08 أو أكثر","0.02 أو أكثر","0.04 أو أكثر","0.15 أو أكثر"],"h1":"هذا هو الحد العادي للسائقين البالغين في السيارات العادية.","h2":"السائق الذي عمره 21 سنة أو أكثر يقود تحت التأثير إذا كانت نسبة الكحول في دمه 0.08 أو أكثر، ويمكن أيضًا اتهامه بنسبة أقل إذا كانت قدرته على القيادة ضعيفة.","p":"صحيح. للبالغين، الحد هو 0.08."},"ht":{"q":"Nan Florida, a ki nivo alkòl nan san lalwa di yon chofè ki gen 21 an oswa plis sou?","o":["0.08 oswa plis","0.02 oswa plis","0.04 oswa plis","0.15 oswa plis"],"h1":"Sa a se limit nòmal pou granmoun k ap kondi machin òdinè.","h2":"Yon chofè ki gen 21 an oswa plis ap kondi sou enfliyans lè nivo alkòl nan san li se 0.08 oswa plis, epi yo ka akize l menm ak mwens si li pa an kondisyon pou kondi.","p":"Se sa. Pou granmoun, limit la se 0.08."},"ref":{"doc":"FL","page":25}},{"id":"licensing-032","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, a driver under 21 can lose their license at what blood alcohol level?","o":["0.08 or higher","0.10 or higher","0.02 or higher","0.05 or higher"],"h1":"Drivers under 21 may not legally drink, so the limit is very low.","h2":"A driver under 21 with a blood alcohol level of 0.02 or higher will have their license suspended, because people under 21 may not drink at all.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Florida, ¿con qué nivel de alcohol en la sangre puede perder la licencia un conductor menor de 21?","o":["0.08 o más","0.10 o más","0.02 o más","0.05 o más"],"h1":"Los menores de 21 no pueden tomar alcohol legalmente, así que el límite es muy bajo.","h2":"A un conductor menor de 21 con un nivel de alcohol de 0.02 o más le suspenden la licencia, porque los menores de 21 no pueden tomar nada.","p":"Correcto. Para menores de 21, el límite es 0.02."},"zh":{"q":"在 Florida，21 岁以下的司机血液酒精浓度达到多少会失去驾照？","o":["0.08 或更高","0.10 或更高","0.02 或更高","0.05 或更高"],"h1":"21 岁以下的人在法律上不能喝酒，所以上限很低。","h2":"21 岁以下的司机，血液酒精浓度达到 0.02 或更高，驾照就会被暂停，因为 21 岁以下的人完全不能喝酒。","p":"对。21 岁以下，上限是 0.02。"},"vi":{"q":"Ở Florida, tài xế dưới 21 tuổi có thể mất bằng lái khi nồng độ cồn trong máu ở mức nào?","o":["0.08 trở lên","0.10 trở lên","0.02 trở lên","0.05 trở lên"],"h1":"Tài xế dưới 21 tuổi không được phép uống rượu bia theo luật, nên giới hạn rất thấp.","h2":"Tài xế dưới 21 tuổi có nồng độ cồn trong máu từ 0.02 trở lên sẽ bị đình chỉ bằng lái, vì người dưới 21 tuổi hoàn toàn không được uống rượu bia.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa Florida, ang driver na wala pang 21 ay puwedeng mawalan ng lisensya sa anong blood alcohol level?","o":["0.08 o higit pa","0.10 o higit pa","0.02 o higit pa","0.05 o higit pa"],"h1":"Bawal uminom ng alak ang mga driver na wala pang 21, kaya napakababa ng limit.","h2":"Ang driver na wala pang 21 na may blood alcohol level na 0.02 o higit pa ay masususpinde ang lisensya, dahil bawal talagang uminom ang mga taong wala pang 21.","p":"Tama. Kapag wala pang 21, ang limit ay 0.02."},"ar":{"q":"في Florida، السائق الذي عمره أقل من 21 سنة قد يخسر رخصته عند أي نسبة كحول في الدم؟","o":["0.08 أو أكثر","0.10 أو أكثر","0.02 أو أكثر","0.05 أو أكثر"],"h1":"السائقون تحت 21 سنة لا يُسمح لهم بشرب الكحول قانونيًا، لذلك الحد منخفض جدًا.","h2":"السائق الذي عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02 أو أكثر تُوقف رخصته، لأن من هم تحت 21 سنة لا يُسمح لهم بالشرب أبدًا.","p":"صحيح. تحت 21 سنة، الحد هو 0.02."},"ht":{"q":"Nan Florida, yon chofè ki poko gen 21 an ka pèdi lisans li a ki nivo alkòl nan san?","o":["0.08 oswa plis","0.10 oswa plis","0.02 oswa plis","0.05 oswa plis"],"h1":"Chofè ki poko gen 21 an pa gen dwa bwè alkòl dapre lalwa, kidonk limit la ba anpil.","h2":"Yon chofè ki poko gen 21 an ki gen yon nivo alkòl nan san 0.02 oswa plis ap wè yo sispann lisans li, paske moun ki poko gen 21 an pa gen dwa bwè ditou.","p":"Se sa. Anba 21 an, limit la se 0.02."},"ref":{"doc":"FL","page":26}},{"id":"licensing-033","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what is the blood alcohol limit for someone driving a commercial vehicle?","o":["0.08","0.04","0.10","0.02"],"h1":"Commercial drivers have a stricter limit than regular adult drivers.","h2":"A person driving a commercial motor vehicle is over the limit at a blood alcohol level of 0.04, which is half the limit for regular adult drivers.","p":"Right. For commercial drivers, the limit is 0.04."},"es":{"q":"En Florida, ¿cuál es el límite de alcohol en la sangre para quien maneja un vehículo comercial?","o":["0.08","0.04","0.10","0.02"],"h1":"Los conductores comerciales tienen un límite más estricto que los adultos comunes.","h2":"Una persona que maneja un vehículo motorizado comercial pasa el límite con un nivel de alcohol de 0.04, que es la mitad del límite para adultos comunes.","p":"Correcto. Para conductores comerciales, el límite es 0.04."},"zh":{"q":"在 Florida，驾驶商用车辆的人，血液酒精浓度上限是多少？","o":["0.08","0.04","0.10","0.02"],"h1":"商用车司机的上限比普通成年司机更严格。","h2":"驾驶商用机动车的人，血液酒精浓度达到 0.04 就超过上限，这是普通成年司机上限的一半。","p":"对。商用车司机的上限是 0.04。"},"vi":{"q":"Ở Florida, giới hạn nồng độ cồn trong máu cho người lái xe thương mại là bao nhiêu?","o":["0.08","0.04","0.10","0.02"],"h1":"Tài xế xe thương mại có giới hạn nghiêm hơn người lớn lái xe thông thường.","h2":"Người lái xe cơ giới thương mại bị coi là vượt giới hạn khi nồng độ cồn trong máu là 0.04, bằng một nửa giới hạn của người lớn lái xe thông thường.","p":"Đúng. Với tài xế xe thương mại, giới hạn là 0.04."},"tl":{"q":"Sa Florida, ano ang blood alcohol limit para sa taong nagmamaneho ng commercial vehicle?","o":["0.08","0.04","0.10","0.02"],"h1":"Mas mahigpit ang limit para sa mga commercial driver kaysa sa mga ordinaryong adult na driver.","h2":"Ang taong nagmamaneho ng commercial motor vehicle ay lampas na sa limit sa blood alcohol level na 0.04, na kalahati ng limit para sa mga ordinaryong adult na driver.","p":"Tama. Para sa mga commercial driver, ang limit ay 0.04."},"ar":{"q":"في Florida، ما حد الكحول في الدم لمن يقود مركبة تجارية؟","o":["0.08","0.04","0.10","0.02"],"h1":"سائقو المركبات التجارية لهم حد أشد من السائقين البالغين العاديين.","h2":"الشخص الذي يقود مركبة تجارية يكون فوق الحد عندما تصل نسبة الكحول في دمه إلى 0.04، وهذا نصف حد السائقين البالغين العاديين.","p":"صحيح. لسائقي المركبات التجارية، الحد هو 0.04."},"ht":{"q":"Nan Florida, ki limit alkòl nan san pou yon moun k ap kondi yon machin komèsyal?","o":["0.08","0.04","0.10","0.02"],"h1":"Chofè komèsyal yo gen yon limit ki pi sevè pase granmoun k ap kondi machin òdinè.","h2":"Yon moun k ap kondi yon machin komèsyal depase limit la lè nivo alkòl nan san li rive 0.04, sa ki mwatye limit pou granmoun k ap kondi machin òdinè.","p":"Se sa. Pou chofè komèsyal yo, limit la se 0.04."},"ref":{"doc":"FL","page":null}},{"id":"licensing-034","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, a driver under 21 is found with a blood alcohol level of 0.02. What happens to the license the first time?","o":["It is suspended for 5 years","It is not affected","It is suspended for 1 week","It is suspended for 6 months"],"h1":"It is a real suspension, longer than a few weeks but shorter than a year.","h2":"For a first offense, a driver under 21 with a blood alcohol level of 0.02 or higher has the license suspended for 6 months.","p":"Right. The first time, the license is suspended for 6 months."},"es":{"q":"En Florida, un conductor menor de 21 tiene un nivel de alcohol de 0.02. ¿Qué pasa con su licencia la primera vez?","o":["Se la suspenden por 5 años","No le pasa nada","Se la suspenden por 1 semana","Se la suspenden por 6 meses"],"h1":"Es una suspensión real, más larga que unas semanas pero más corta que un año.","h2":"La primera vez, a un conductor menor de 21 con un nivel de alcohol de 0.02 o más le suspenden la licencia por 6 meses.","p":"Correcto. La primera vez, la licencia se suspende por 6 meses."},"zh":{"q":"在 Florida，一个 21 岁以下的司机被发现血液酒精浓度是 0.02。第一次会对驾照怎么样？","o":["暂停 5 年","没有影响","暂停 1 个星期","暂停 6 个月"],"h1":"这是真正的暂停，比几个星期长，但比一年短。","h2":"第一次违法时，21 岁以下、血液酒精浓度 0.02 或更高的司机，驾照会被暂停 6 个月。","p":"对。第一次，驾照暂停 6 个月。"},"vi":{"q":"Ở Florida, một tài xế dưới 21 tuổi bị phát hiện có nồng độ cồn trong máu là 0.02. Lần đầu, bằng lái bị xử lý thế nào?","o":["Bị đình chỉ 5 năm","Không bị ảnh hưởng","Bị đình chỉ 1 tuần","Bị đình chỉ 6 tháng"],"h1":"Đây là đình chỉ thật sự, dài hơn vài tuần nhưng ngắn hơn một năm.","h2":"Với lần vi phạm đầu, tài xế dưới 21 tuổi có nồng độ cồn trong máu từ 0.02 trở lên bị đình chỉ bằng lái 6 tháng.","p":"Đúng. Lần đầu, bằng lái bị đình chỉ 6 tháng."},"tl":{"q":"Sa Florida, ang driver na wala pang 21 ay nakitaan ng blood alcohol level na 0.02. Ano ang mangyayari sa lisensya sa unang beses?","o":["Masususpinde ito nang 5 taon","Walang epekto rito","Masususpinde ito nang 1 linggo","Masususpinde ito nang 6 na buwan"],"h1":"Totoong suspensyon ito, mas mahaba sa ilang linggo pero mas maikli sa isang taon.","h2":"Sa unang offense, ang driver na wala pang 21 na may blood alcohol level na 0.02 o higit pa ay masususpinde ang lisensya nang 6 na buwan.","p":"Tama. Sa unang beses, masususpinde ang lisensya nang 6 na buwan."},"ar":{"q":"في Florida، وُجد سائق عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02. ماذا يحدث لرخصته في المرة الأولى؟","o":["تُوقف لمدة 5 سنوات","لا تتأثر","تُوقف لمدة أسبوع واحد","تُوقف لمدة 6 أشهر"],"h1":"إنه إيقاف حقيقي، أطول من بضعة أسابيع وأقصر من سنة.","h2":"في المخالفة الأولى، السائق الذي عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02 أو أكثر تُوقف رخصته لمدة 6 أشهر.","p":"صحيح. في المرة الأولى، تُوقف الرخصة لمدة 6 أشهر."},"ht":{"q":"Nan Florida, yo jwenn yon chofè ki poko gen 21 an ak yon nivo alkòl nan san 0.02. Kisa k rive lisans li premye fwa a?","o":["Yo sispann li pou 5 an","Pa gen anyen ki rive l","Yo sispann li pou 1 semèn","Yo sispann li pou 6 mwa"],"h1":"Se yon vrè sispansyon, pi long pase kèk semèn men pi kout pase yon ane.","h2":"Pou yon premye fwa, yon chofè ki poko gen 21 an ki gen yon nivo alkòl nan san 0.02 oswa plis ap wè yo sispann lisans li pou 6 mwa.","p":"Se sa. Premye fwa a, yo sispann lisans lan pou 6 mwa."},"ref":{"doc":"FL","page":26}},{"id":"licensing-035","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, who may have an open container of alcohol in a moving car?","o":["No one, not the driver and not the passengers","Only the passengers","Only the driver","Anyone over 21"],"h1":"The rule covers everyone inside a regular car.","h2":"In a regular car, neither the driver nor the passengers may have an open container of alcohol while the car is on the road.","p":"Right. No one in the car may have an open container."},"es":{"q":"En Florida, ¿quién puede tener un envase abierto de alcohol en un carro en movimiento?","o":["Nadie, ni el conductor ni los pasajeros","Solo los pasajeros","Solo el conductor","Cualquier persona mayor de 21"],"h1":"La regla aplica a todos los que van en un carro común.","h2":"En un carro común, ni el conductor ni los pasajeros pueden tener un envase abierto de alcohol mientras el carro está en la calle.","p":"Correcto. Nadie en el carro puede tener un envase abierto."},"zh":{"q":"在 Florida，在行驶的车里谁可以有打开的酒瓶或酒罐？","o":["没有人可以，司机和乘客都不行","只有乘客","只有司机","21 岁以上的任何人"],"h1":"这条规定适用于普通汽车里的每一个人。","h2":"在普通汽车里，车在路上时，司机和乘客都不能有打开的酒类容器。","p":"对。车里任何人都不能有打开的酒类容器。"},"vi":{"q":"Ở Florida, ai được để chai hoặc lon rượu bia đã mở trong xe đang chạy?","o":["Không ai cả, không phải tài xế và cũng không phải hành khách","Chỉ hành khách","Chỉ tài xế","Bất kỳ ai trên 21 tuổi"],"h1":"Quy định này áp dụng cho mọi người trong một chiếc xe thông thường.","h2":"Trong một chiếc xe thông thường, cả tài xế lẫn hành khách đều không được để chai hoặc lon rượu bia đã mở khi xe đang chạy trên đường.","p":"Đúng. Không ai trong xe được để rượu bia đã mở."},"tl":{"q":"Sa Florida, sino ang puwedeng may bukas na lalagyan ng alak sa umaandar na kotse?","o":["Wala, hindi ang driver at hindi ang mga pasahero","Ang mga pasahero lang","Ang driver lang","Kahit sino na lampas 21"],"h1":"Sakop ng patakaran ang lahat ng nasa loob ng ordinaryong kotse.","h2":"Sa ordinaryong kotse, hindi puwedeng may bukas na lalagyan ng alak ang driver o ang mga pasahero habang nasa daan ang kotse.","p":"Tama. Walang sinuman sa kotse ang puwedeng may bukas na lalagyan ng alak."},"ar":{"q":"في Florida، من يُسمح له بأن يكون معه وعاء كحول مفتوح في سيارة تسير؟","o":["لا أحد، لا السائق ولا الركاب","الركاب فقط","السائق فقط","أي شخص فوق 21 سنة"],"h1":"القاعدة تشمل كل من في داخل السيارة العادية.","h2":"في السيارة العادية، لا يُسمح للسائق ولا للركاب بأن يكون معهم وعاء كحول مفتوح عندما تكون السيارة على الطريق.","p":"صحيح. لا أحد في السيارة يُسمح له بوعاء كحول مفتوح."},"ht":{"q":"Nan Florida, kiyès ki gen dwa gen yon boutèy oswa yon bwat alkòl ki louvri nan yon machin k ap woule?","o":["Pèsonn, ni chofè a ni pasaje yo","Pasaje yo sèlman","Chofè a sèlman","Nenpòt moun ki gen plis pase 21 an"],"h1":"Règ la kouvri tout moun ki andedan yon machin òdinè.","h2":"Nan yon machin òdinè, ni chofè a ni pasaje yo pa gen dwa gen yon boutèy oswa yon bwat alkòl ki louvri pandan machin nan sou wout la.","p":"Se sa. Pèsonn nan machin nan pa gen dwa gen alkòl ki louvri."},"ref":{"doc":"FL","page":null}},{"id":"licensing-036","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, who must wear a seat belt?","o":["Only the driver","Only children under 5","The driver, front-seat passengers, and all passengers under 18","Only people on the highway"],"h1":"Think about the front of the car and about young people anywhere in the car.","h2":"The driver and all front-seat passengers must wear seat belts, and every passenger under 18 must be buckled in any seat.","p":"Right. Driver, front seat, and everyone under 18 must buckle up."},"es":{"q":"En Florida, ¿quién debe usar el cinturón de seguridad?","o":["Solo el conductor","Solo los niños menores de 5","El conductor, los pasajeros de adelante y todos los pasajeros menores de 18","Solo las personas en la autopista"],"h1":"Piense en la parte de adelante del carro y en los jóvenes en cualquier asiento.","h2":"El conductor y todos los pasajeros del asiento de adelante deben usar el cinturón, y todo pasajero menor de 18 debe ir abrochado en cualquier asiento.","p":"Correcto. El conductor, los de adelante y todos los menores de 18 deben abrocharse."},"zh":{"q":"在 Florida，谁必须系安全带？","o":["只有司机","只有 5 岁以下的儿童","司机、前排乘客，以及所有 18 岁以下的乘客","只有在高速公路上的人"],"h1":"想一想车的前排，以及坐在车里任何位置的年轻人。","h2":"司机和所有前排乘客都必须系安全带，每一位 18 岁以下的乘客不管坐在哪里都必须系好。","p":"对。司机、前排乘客和所有 18 岁以下的人都必须系安全带。"},"vi":{"q":"Ở Florida, ai phải thắt dây an toàn?","o":["Chỉ tài xế","Chỉ trẻ em dưới 5 tuổi","Tài xế, hành khách ngồi ghế trước, và mọi hành khách dưới 18 tuổi","Chỉ người đi trên xa lộ"],"h1":"Hãy nghĩ đến phía trước xe và đến người trẻ ở bất kỳ chỗ nào trong xe.","h2":"Tài xế và mọi hành khách ngồi ghế trước phải thắt dây an toàn, và mọi hành khách dưới 18 tuổi phải thắt dây ở bất kỳ ghế nào.","p":"Đúng. Tài xế, ghế trước, và mọi người dưới 18 tuổi phải thắt dây an toàn."},"tl":{"q":"Sa Florida, sino ang dapat magsuot ng seat belt?","o":["Ang driver lang","Ang mga batang wala pang 5 lang","Ang driver, mga pasahero sa harap, at lahat ng pasaherong wala pang 18","Ang mga tao sa highway lang"],"h1":"Isipin ang harap ng kotse at ang mga kabataan kahit saan sa loob ng kotse.","h2":"Ang driver at lahat ng pasahero sa harap ay dapat magsuot ng seat belt, at bawat pasaherong wala pang 18 ay dapat naka-seat belt sa kahit anong upuan.","p":"Tama. Ang driver, ang nasa harap, at lahat ng wala pang 18 ay dapat naka-seat belt."},"ar":{"q":"في Florida، من يجب أن يربط حزام الأمان؟","o":["السائق فقط","الأطفال تحت 5 سنوات فقط","السائق، وركاب المقعد الأمامي، وكل الركاب تحت 18 سنة","الناس على الطريق السريع فقط"],"h1":"فكّر في مقدمة السيارة، وفي الصغار في أي مكان في السيارة.","h2":"يجب على السائق وكل ركاب المقعد الأمامي أن يربطوا حزام الأمان، ويجب على كل راكب تحت 18 سنة أن يربط الحزام في أي مقعد.","p":"صحيح. السائق، والمقعد الأمامي، وكل من هو تحت 18 سنة يجب أن يربطوا الحزام."},"ht":{"q":"Nan Florida, kiyès ki dwe mete senti sekirite?","o":["Chofè a sèlman","Timoun ki poko gen 5 an sèlman","Chofè a, pasaje ki chita devan yo, ak tout pasaje ki poko gen 18 an","Moun ki sou otowout sèlman"],"h1":"Panse ak devan machin nan, epi ak jèn moun ki nenpòt kote nan machin nan.","h2":"Chofè a ak tout pasaje ki chita devan dwe mete senti sekirite, epi chak pasaje ki poko gen 18 an dwe mete senti l sou nenpòt chèz.","p":"Se sa. Chofè a, moun devan yo, ak tout moun ki poko gen 18 an dwe mete senti."},"ref":{"doc":"FL","page":27}},{"id":"licensing-037","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, how must a child age 3 or younger ride in a car?","o":["On an adult's lap","In a separate child carrier or a car's built-in child seat","With only a regular seat belt","In any seat without a belt"],"h1":"The youngest children need the most protection.","h2":"A child age 3 or younger must ride in a separate crash-tested child carrier or in a child seat built into the car.","p":"Right. Children 3 and under need a child carrier or built-in seat."},"es":{"q":"En Florida, ¿cómo debe viajar en el carro un niño de 3 años o menos?","o":["En las piernas de un adulto","En un asiento para niños aparte o en un asiento para niños integrado al carro","Solo con un cinturón de seguridad normal","En cualquier asiento sin cinturón"],"h1":"Los niños más pequeños necesitan la mayor protección.","h2":"Un niño de 3 años o menos debe viajar en un asiento para niños aparte, probado contra choques, o en un asiento para niños integrado al carro.","p":"Correcto. Los niños de 3 años o menos necesitan un asiento para niños."},"zh":{"q":"在 Florida，3 岁或以下的儿童坐车必须怎么坐？","o":["坐在大人腿上","坐在单独的儿童安全座椅里，或车上内置的儿童座椅里","只用普通安全带","坐在任何座位，不系安全带"],"h1":"年龄最小的孩子需要最多的保护。","h2":"3 岁或以下的儿童必须坐在单独的、经过碰撞测试的儿童安全座椅里，或车上内置的儿童座椅里。","p":"对。3 岁及以下的儿童需要儿童安全座椅或内置儿童座椅。"},"vi":{"q":"Ở Florida, trẻ em từ 3 tuổi trở xuống phải ngồi trong xe như thế nào?","o":["Ngồi trên đùi người lớn","Trong ghế an toàn trẻ em riêng hoặc ghế trẻ em gắn sẵn trong xe","Chỉ với dây an toàn thông thường","Ở bất kỳ ghế nào, không cần dây"],"h1":"Trẻ nhỏ nhất cần được bảo vệ nhiều nhất.","h2":"Trẻ em từ 3 tuổi trở xuống phải ngồi trong ghế an toàn trẻ em riêng đã được thử nghiệm va chạm, hoặc trong ghế trẻ em gắn sẵn trong xe.","p":"Đúng. Trẻ từ 3 tuổi trở xuống cần ghế an toàn trẻ em hoặc ghế gắn sẵn."},"tl":{"q":"Sa Florida, paano dapat sumakay sa kotse ang batang 3 taong gulang o mas bata?","o":["Sa kandungan ng adult","Sa hiwalay na child carrier o sa child seat na nakakabit na sa kotse","Sa ordinaryong seat belt lang","Sa kahit anong upuan nang walang seat belt"],"h1":"Ang pinakabatang mga bata ang nangangailangan ng pinakamalaking proteksyon.","h2":"Ang batang 3 taong gulang o mas bata ay dapat sumakay sa hiwalay na child carrier na na-crash test, o sa child seat na nakakabit na sa kotse.","p":"Tama. Ang mga batang 3 taon pababa ay nangangailangan ng child carrier o child seat na nakakabit sa kotse."},"ar":{"q":"في Florida، كيف يجب أن يركب الطفل الذي عمره 3 سنوات أو أقل في السيارة؟","o":["في حضن شخص بالغ","في مقعد أطفال منفصل أو في مقعد أطفال مدمج في السيارة","بحزام أمان عادي فقط","في أي مقعد بدون حزام"],"h1":"الأطفال الأصغر يحتاجون إلى أكثر حماية.","h2":"الطفل الذي عمره 3 سنوات أو أقل يجب أن يركب في مقعد أطفال منفصل مُختبَر في اختبارات التصادم، أو في مقعد أطفال مدمج في السيارة.","p":"صحيح. الأطفال بعمر 3 سنوات وأقل يحتاجون إلى مقعد أطفال منفصل أو مدمج."},"ht":{"q":"Nan Florida, kijan yon timoun ki gen 3 an oswa mwens dwe chita nan yon machin?","o":["Sou janm yon granmoun","Nan yon chèz timoun apa oswa nan yon chèz timoun ki fèt ladan machin nan","Ak yon senti sekirite òdinè sèlman","Sou nenpòt chèz san senti"],"h1":"Timoun ki pi piti yo bezwen plis pwoteksyon.","h2":"Yon timoun ki gen 3 an oswa mwens dwe chita nan yon chèz timoun apa ki te teste pou aksidan, oswa nan yon chèz timoun ki fèt ladan machin nan.","p":"Se sa. Timoun 3 an oswa mwens bezwen yon chèz timoun apa oswa yon chèz ki fèt ladan machin nan."},"ref":{"doc":"FL","page":28}},{"id":"licensing-038","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, what may a child age 4 or 5 use in a car?","o":["Nothing, they may ride free","Only an adult's lap","Only the front seat with no belt","A child carrier, a built-in child seat, or a booster seat"],"h1":"Children this age have one more choice than younger children.","h2":"A child age 4 or 5 must use a separate child carrier, a built-in child seat, or a booster seat.","p":"Right. Ages 4 and 5 may use a car seat or a booster seat."},"es":{"q":"En Florida, ¿qué puede usar en el carro un niño de 4 o 5 años?","o":["Nada, puede ir suelto","Solo las piernas de un adulto","Solo el asiento de adelante sin cinturón","Un asiento para niños, un asiento integrado o un asiento elevador (booster)"],"h1":"Los niños de esta edad tienen una opción más que los niños más pequeños.","h2":"Un niño de 4 o 5 años debe usar un asiento para niños aparte, un asiento para niños integrado al carro o un asiento elevador.","p":"Correcto. A los 4 y 5 años se usa un asiento para niños o un asiento elevador."},"zh":{"q":"在 Florida，4 岁或 5 岁的儿童坐车可以用什么？","o":["什么都不用，可以随便坐","只能坐在大人腿上","只能坐前排，不系安全带","儿童安全座椅、内置儿童座椅或增高座椅"],"h1":"这个年龄的孩子比更小的孩子多一个选择。","h2":"4 岁或 5 岁的儿童必须使用单独的儿童安全座椅、内置儿童座椅或增高座椅。","p":"对。4 岁和 5 岁的儿童可以用儿童安全座椅或增高座椅。"},"vi":{"q":"Ở Florida, trẻ em 4 hoặc 5 tuổi được dùng gì trong xe?","o":["Không cần gì, trẻ được ngồi tự do","Chỉ ngồi trên đùi người lớn","Chỉ ngồi ghế trước, không cần dây","Ghế an toàn trẻ em, ghế trẻ em gắn sẵn, hoặc ghế nâng (booster seat)"],"h1":"Trẻ ở tuổi này có thêm một lựa chọn so với trẻ nhỏ hơn.","h2":"Trẻ em 4 hoặc 5 tuổi phải dùng ghế an toàn trẻ em riêng, ghế trẻ em gắn sẵn, hoặc ghế nâng (booster seat).","p":"Đúng. Trẻ 4 và 5 tuổi được dùng ghế an toàn trẻ em hoặc ghế nâng."},"tl":{"q":"Sa Florida, ano ang puwedeng gamitin ng batang 4 o 5 taong gulang sa kotse?","o":["Wala, puwede silang sumakay nang malaya","Kandungan lang ng adult","Upuan lang sa harap nang walang seat belt","Child carrier, child seat na nakakabit sa kotse, o booster seat"],"h1":"May isa pang pagpipilian ang mga batang ganito ang edad kaysa sa mas batang mga bata.","h2":"Ang batang 4 o 5 taong gulang ay dapat gumamit ng hiwalay na child carrier, child seat na nakakabit sa kotse, o booster seat.","p":"Tama. Ang edad 4 at 5 ay puwedeng gumamit ng car seat o booster seat."},"ar":{"q":"في Florida، ماذا يمكن أن يستعمل الطفل الذي عمره 4 أو 5 سنوات في السيارة؟","o":["لا شيء، يمكنه الركوب بحرية","حضن شخص بالغ فقط","المقعد الأمامي فقط بدون حزام","مقعد أطفال منفصل، أو مقعد أطفال مدمج، أو مقعد رافع (booster)"],"h1":"الأطفال في هذا العمر لهم خيار واحد إضافي مقارنة بالأطفال الأصغر.","h2":"الطفل الذي عمره 4 أو 5 سنوات يجب أن يستعمل مقعد أطفال منفصلًا، أو مقعد أطفال مدمجًا، أو مقعدًا رافعًا (booster).","p":"صحيح. في عمر 4 و5 سنوات يمكن استعمال مقعد أطفال أو مقعد رافع."},"ht":{"q":"Nan Florida, kisa yon timoun 4 oswa 5 an ka itilize nan yon machin?","o":["Anyen, yo ka chita lib","Janm yon granmoun sèlman","Chèz devan an sèlman, san senti","Yon chèz timoun apa, yon chèz timoun ki fèt ladan machin nan, oswa yon chèz booster"],"h1":"Timoun laj sa a gen yon chwa anplis pase timoun ki pi piti yo.","h2":"Yon timoun 4 oswa 5 an dwe itilize yon chèz timoun apa, yon chèz timoun ki fèt ladan machin nan, oswa yon chèz booster.","p":"Se sa. Timoun 4 ak 5 an ka itilize yon chèz timoun oswa yon chèz booster."},"ref":{"doc":"FL","page":28}},{"id":"licensing-039","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, can a police officer stop you just for texting while driving?","o":["Yes, texting while driving is a primary offense","No, only if you also break another law","No, texting while driving is legal","Only on interstate highways"],"h1":"Think about whether the officer needs a second reason to stop you.","h2":"Texting while driving is a primary offense in Florida, so an officer can stop you for texting alone.","p":"Right. You can be stopped just for texting."},"es":{"q":"En Florida, ¿puede un policía detenerlo solo por enviar mensajes de texto mientras maneja?","o":["Sí, enviar textos mientras maneja es una infracción primaria","No, solo si también viola otra ley","No, enviar textos mientras maneja es legal","Solo en las autopistas interestatales"],"h1":"Piense si el oficial necesita una segunda razón para detenerlo.","h2":"Enviar textos mientras maneja es una infracción primaria en Florida, así que un oficial puede detenerlo solo por eso.","p":"Correcto. Lo pueden detener solo por enviar textos."},"zh":{"q":"在 Florida，警察可以只因为你开车时发短信就让你停车吗？","o":["可以，开车发短信是主要违法行为","不可以，除非你也违反了别的法律","不可以，开车发短信是合法的","只在州际高速公路上可以"],"h1":"想一想警察是否需要第二个理由才能让你停车。","h2":"在 Florida，开车发短信是主要违法行为，所以警察只因为你发短信就可以让你停车。","p":"对。只因为发短信，你就可能被拦下。"},"vi":{"q":"Ở Florida, cảnh sát có thể chặn xe bạn chỉ vì bạn nhắn tin khi lái xe không?","o":["Có, nhắn tin khi lái xe là vi phạm chính (primary offense)","Không, chỉ khi bạn vi phạm thêm luật khác","Không, nhắn tin khi lái xe là hợp pháp","Chỉ trên xa lộ liên bang"],"h1":"Hãy nghĩ xem cảnh sát có cần thêm lý do thứ hai để chặn xe bạn không.","h2":"Nhắn tin khi lái xe là vi phạm chính ở Florida, nên cảnh sát có thể chặn xe bạn chỉ vì nhắn tin.","p":"Đúng. Bạn có thể bị chặn xe chỉ vì nhắn tin."},"tl":{"q":"Sa Florida, puwede ka bang parahin ng pulis dahil lang nagte-text ka habang nagmamaneho?","o":["Oo, ang pag-text habang nagmamaneho ay primary offense","Hindi, kung may iba ka lang ding nilabag na batas","Hindi, legal ang pag-text habang nagmamaneho","Sa interstate highway lang"],"h1":"Isipin kung kailangan pa ng pulis ng pangalawang dahilan para parahin ka.","h2":"Ang pag-text habang nagmamaneho ay primary offense sa Florida, kaya puwede kang parahin ng pulis dahil lang sa pag-text.","p":"Tama. Puwede kang parahin dahil lang sa pag-text."},"ar":{"q":"في Florida، هل يمكن للشرطي أن يوقفك فقط لأنك تكتب رسائل أثناء القيادة؟","o":["نعم، كتابة الرسائل أثناء القيادة مخالفة أساسية","لا، فقط إذا خالفت قانونًا آخر أيضًا","لا، كتابة الرسائل أثناء القيادة مسموحة","فقط على الطرق السريعة بين الولايات"],"h1":"فكّر: هل يحتاج الشرطي إلى سبب ثانٍ ليوقفك؟","h2":"كتابة الرسائل أثناء القيادة مخالفة أساسية في Florida، لذلك يمكن للشرطي أن يوقفك بسبب كتابة الرسائل وحدها.","p":"صحيح. يمكن أن يوقفوك فقط بسبب كتابة الرسائل."},"ht":{"q":"Nan Florida, èske yon polis ka kanpe w sèlman paske w ap voye tèks pandan w ap kondi?","o":["Wi, voye tèks pandan w ap kondi se yon enfraksyon prensipal","Non, sèlman si ou vyole yon lòt lwa tou","Non, voye tèks pandan w ap kondi pa kont lalwa","Sèlman sou otowout entèeta yo"],"h1":"Panse si polis la bezwen yon dezyèm rezon pou l kanpe w.","h2":"Voye tèks pandan w ap kondi se yon enfraksyon prensipal nan Florida, kidonk yon polis ka kanpe w sèlman paske w ap voye tèks.","p":"Se sa. Yo ka kanpe w sèlman paske w ap voye tèks."},"ref":{"doc":"FL","page":null}},{"id":"licensing-040","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, how may you use a phone while driving in a school zone or an active work zone?","o":["Holding it in your hand","Only to read texts","Only hands-free","Any way you want"],"h1":"In these zones, your hands must stay off the phone.","h2":"In a school zone or an active work zone, you may not hold a phone in your hand, so you may use it only in hands-free mode.","p":"Right. In school and work zones, phones must be hands-free."},"es":{"q":"En Florida, ¿cómo puede usar el teléfono mientras maneja en una zona escolar o en una zona de construcción activa?","o":["Sosteniéndolo en la mano","Solo para leer mensajes","Solo con manos libres","Como usted quiera"],"h1":"En estas zonas, sus manos no deben tocar el teléfono.","h2":"En una zona escolar o en una zona de construcción activa, no puede tener el teléfono en la mano, así que solo puede usarlo con manos libres.","p":"Correcto. En zonas escolares y de construcción, el teléfono debe ser de manos libres."},"zh":{"q":"在 Florida，在学校区域或正在施工的工作区开车时，你可以怎样用手机？","o":["拿在手里","只能看短信","只能免提","想怎么用就怎么用"],"h1":"在这些区域，你的手不能碰手机。","h2":"在学校区域或正在施工的工作区，你不能手里拿着手机，所以只能用免提模式。","p":"对。在学校区域和工作区，手机只能免提。"},"vi":{"q":"Ở Florida, bạn được dùng điện thoại như thế nào khi lái xe trong khu vực trường học hoặc khu vực đang thi công?","o":["Cầm điện thoại trên tay","Chỉ để đọc tin nhắn","Chỉ ở chế độ rảnh tay (hands-free)","Dùng cách nào cũng được"],"h1":"Trong những khu vực này, tay bạn không được chạm vào điện thoại.","h2":"Trong khu vực trường học hoặc khu vực đang thi công, bạn không được cầm điện thoại trên tay, nên bạn chỉ được dùng ở chế độ rảnh tay.","p":"Đúng. Trong khu vực trường học và thi công, điện thoại phải ở chế độ rảnh tay."},"tl":{"q":"Sa Florida, paano mo puwedeng gamitin ang phone habang nagmamaneho sa school zone o sa active work zone?","o":["Hawak ito sa kamay mo","Para magbasa lang ng text","Hands-free lang","Kahit anong paraan na gusto mo"],"h1":"Sa mga zone na ito, hindi dapat hawak ng mga kamay mo ang phone.","h2":"Sa school zone o sa active work zone, bawal hawakan ang phone sa kamay mo, kaya puwede mo lang itong gamitin nang hands-free.","p":"Tama. Sa mga school at work zone, dapat hands-free ang phone."},"ar":{"q":"في Florida، كيف يمكنك استعمال الهاتف أثناء القيادة في منطقة مدرسة أو منطقة أعمال نشطة؟","o":["وأنت تمسكه بيدك","لقراءة الرسائل فقط","بدون استعمال اليدين فقط","بأي طريقة تريدها"],"h1":"في هذه المناطق، يجب أن تبقى يداك بعيدتين عن الهاتف.","h2":"في منطقة المدرسة أو منطقة الأعمال النشطة، لا يُسمح لك بإمساك الهاتف بيدك، لذلك يمكنك استعماله فقط بدون استعمال اليدين.","p":"صحيح. في مناطق المدارس والأعمال، الهاتف بدون استعمال اليدين فقط."},"ht":{"q":"Nan Florida, kijan ou ka itilize yon telefòn pandan w ap kondi nan yon zòn lekòl oswa nan yon zòn travay ki aktif?","o":["Kenbe l nan men ou","Sèlman pou li tèks","Sèlman san men (hands-free)","Jan ou vle"],"h1":"Nan zòn sa yo, men ou pa dwe touche telefòn nan.","h2":"Nan yon zòn lekòl oswa nan yon zòn travay ki aktif, ou pa gen dwa kenbe telefòn nan men ou, kidonk ou ka itilize l sèlman san men (hands-free).","p":"Se sa. Nan zòn lekòl ak zòn travay, telefòn nan dwe san men (hands-free)."},"ref":{"doc":"FL","page":34}},{"id":"licensing-041","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, you move to a new home. How soon must you update the address on your license?","o":["Within 1 year","Within 30 days","Only at your next renewal","Within 6 months"],"h1":"There is a deadline of about one month.","h2":"When you move, you must update the address on your driver license within 30 days.","p":"Right. Update your address within 30 days."},"es":{"q":"En Florida, usted se muda a una casa nueva. ¿En cuánto tiempo debe actualizar la dirección de su licencia?","o":["Dentro de 1 año","Dentro de 30 días","Solo en la próxima renovación","Dentro de 6 meses"],"h1":"Hay un plazo de más o menos un mes.","h2":"Cuando se muda, usted debe actualizar la dirección de su licencia de conducir dentro de 30 días.","p":"Correcto. Actualice su dirección dentro de 30 días."},"zh":{"q":"在 Florida，你搬了新家。你必须在多长时间内更新驾照上的地址？","o":["1 年内","30 天内","只在下次更新驾照时","6 个月内"],"h1":"期限大约是一个月。","h2":"你搬家后，必须在 30 天内更新驾照上的地址。","p":"对。30 天内更新你的地址。"},"vi":{"q":"Ở Florida, bạn chuyển đến nhà mới. Bạn phải cập nhật địa chỉ trên bằng lái trong bao lâu?","o":["Trong vòng 1 năm","Trong vòng 30 ngày","Chỉ khi gia hạn lần tới","Trong vòng 6 tháng"],"h1":"Có thời hạn khoảng một tháng.","h2":"Khi chuyển nhà, bạn phải cập nhật địa chỉ trên bằng lái trong vòng 30 ngày.","p":"Đúng. Cập nhật địa chỉ trong vòng 30 ngày."},"tl":{"q":"Sa Florida, lumipat ka sa bagong bahay. Gaano kabilis mo dapat palitan ang address sa lisensya mo?","o":["Sa loob ng 1 taon","Sa loob ng 30 araw","Sa susunod na renewal lang","Sa loob ng 6 na buwan"],"h1":"May deadline na mga isang buwan.","h2":"Kapag lumipat ka, dapat mong palitan ang address sa iyong driver license sa loob ng 30 araw.","p":"Tama. Palitan ang address mo sa loob ng 30 araw."},"ar":{"q":"في Florida، انتقلت إلى بيت جديد. خلال كم من الوقت يجب أن تغيّر العنوان في رخصتك؟","o":["خلال سنة واحدة","خلال 30 يومًا","فقط عند التجديد القادم","خلال 6 أشهر"],"h1":"المهلة حوالي شهر واحد.","h2":"عندما تنتقل، يجب أن تغيّر العنوان في رخصة القيادة خلال 30 يومًا.","p":"صحيح. غيّر عنوانك خلال 30 يومًا."},"ht":{"q":"Nan Florida, ou demenaje nan yon nouvo kay. Nan konbyen tan ou dwe chanje adrès ki sou lisans ou?","o":["Nan 1 an","Nan 30 jou","Sèlman lè w ap renouvle l pwochen fwa","Nan 6 mwa"],"h1":"Gen yon dènye dat ki se apeprè yon mwa.","h2":"Lè ou demenaje, ou dwe chanje adrès ki sou lisans kondi ou nan 30 jou.","p":"Se sa. Chanje adrès ou nan 30 jou."},"ref":{"doc":"FL","page":12}},{"id":"licensing-042","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, how long is a Class E license valid?","o":["2 years","4 years","20 years","6 to 8 years"],"h1":"It lasts many years, but not for life.","h2":"A Florida Class E license is valid for six to eight years, and then you must renew it.","p":"Right. A Class E license lasts six to eight years."},"es":{"q":"En Florida, ¿por cuánto tiempo es válida la licencia Clase E?","o":["2 años","4 años","20 años","De 6 a 8 años"],"h1":"Dura muchos años, pero no toda la vida.","h2":"La licencia Clase E de Florida es válida de seis a ocho años, y después usted debe renovarla.","p":"Correcto. La licencia Clase E dura de seis a ocho años."},"zh":{"q":"在 Florida，Class E 驾照的有效期是多久？","o":["2 年","4 年","20 年","6 到 8 年"],"h1":"它可以用很多年，但不是一辈子。","h2":"Florida 的 Class E 驾照有效期是六到八年，之后你必须更新。","p":"对。Class E 驾照有效六到八年。"},"vi":{"q":"Ở Florida, bằng lái Class E có giá trị trong bao lâu?","o":["2 năm","4 năm","20 năm","6 đến 8 năm"],"h1":"Bằng có giá trị nhiều năm, nhưng không phải suốt đời.","h2":"Bằng lái Class E ở Florida có giá trị từ sáu đến tám năm, sau đó bạn phải gia hạn.","p":"Đúng. Bằng lái Class E có giá trị từ sáu đến tám năm."},"tl":{"q":"Sa Florida, gaano katagal valid ang Class E license?","o":["2 taon","4 na taon","20 taon","6 hanggang 8 taon"],"h1":"Tumatagal ito nang maraming taon, pero hindi habambuhay.","h2":"Ang Florida Class E license ay valid nang anim hanggang walong taon, at pagkatapos ay dapat mo itong i-renew.","p":"Tama. Tumatagal ang Class E license nang anim hanggang walong taon."},"ar":{"q":"في Florida، كم مدة صلاحية رخصة Class E؟","o":["سنتان","4 سنوات","20 سنة","من 6 إلى 8 سنوات"],"h1":"إنها تبقى سنوات كثيرة، لكن ليس طوال الحياة.","h2":"رخصة Class E في Florida صالحة من ست إلى ثماني سنوات، ثم يجب أن تجددها.","p":"صحيح. رخصة Class E تبقى من ست إلى ثماني سنوات."},"ht":{"q":"Nan Florida, pandan konbyen tan yon lisans Class E bon?","o":["2 an","4 an","20 an","6 a 8 an"],"h1":"Li dire anpil ane, men se pa pou tout lavi.","h2":"Yon lisans Class E nan Florida bon pou sis a uit ane, epi apre sa ou dwe renouvle l.","p":"Se sa. Yon lisans Class E dire sis a uit ane."},"ref":{"doc":"FL","page":13}},{"id":"licensing-043","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, what must a driver age 80 or older pass when renewing a license?","o":["A vision test","A new road test every time","A written essay","A physical fitness test"],"h1":"Think about the sense you use most to drive safely.","h2":"Drivers age 80 or older must pass a vision test each time they renew their license, because good eyesight is needed to drive safely.","p":"Right. Drivers 80 and older must pass a vision test to renew."},"es":{"q":"En Florida, ¿qué debe aprobar un conductor de 80 años o más al renovar la licencia?","o":["Un examen de la vista","Un nuevo examen de manejo cada vez","Un ensayo escrito","Una prueba de condición física"],"h1":"Piense en el sentido que más usa para manejar con seguridad.","h2":"Los conductores de 80 años o más deben aprobar un examen de la vista cada vez que renuevan la licencia, porque se necesita buena vista para manejar con seguridad.","p":"Correcto. Los conductores de 80 años o más deben aprobar el examen de la vista para renovar."},"zh":{"q":"在 Florida，80 岁或以上的司机更新驾照时必须通过什么？","o":["视力检查","每次都要新的路考","书面作文","体能测试"],"h1":"想一想你安全开车时用得最多的感官。","h2":"80 岁或以上的司机每次更新驾照都必须通过视力检查，因为安全开车需要好的视力。","p":"对。80 岁及以上的司机更新驾照必须通过视力检查。"},"vi":{"q":"Ở Florida, tài xế từ 80 tuổi trở lên phải đậu bài kiểm tra nào khi gia hạn bằng lái?","o":["Bài kiểm tra mắt","Bài thi lái xe mới mỗi lần","Một bài luận viết","Bài kiểm tra thể lực"],"h1":"Hãy nghĩ đến giác quan bạn dùng nhiều nhất để lái xe an toàn.","h2":"Tài xế từ 80 tuổi trở lên phải đậu bài kiểm tra mắt mỗi lần gia hạn bằng lái, vì cần có mắt tốt để lái xe an toàn.","p":"Đúng. Tài xế từ 80 tuổi trở lên phải đậu bài kiểm tra mắt để gia hạn."},"tl":{"q":"Sa Florida, ano ang dapat ipasa ng driver na 80 taong gulang o higit pa kapag nagre-renew ng lisensya?","o":["Vision test (pagsusuri ng mata)","Bagong road test sa bawat renewal","Nakasulat na sanaysay","Physical fitness test"],"h1":"Isipin ang pandama na pinakaginagamit mo para magmaneho nang ligtas.","h2":"Ang mga driver na 80 taong gulang o higit pa ay dapat pumasa sa vision test sa bawat pag-renew ng lisensya, dahil kailangan ang malinaw na paningin para magmaneho nang ligtas.","p":"Tama. Ang mga driver na 80 pataas ay dapat pumasa sa vision test para mag-renew."},"ar":{"q":"في Florida، ما الاختبار الذي يجب أن ينجح فيه السائق الذي عمره 80 سنة أو أكثر عند تجديد الرخصة؟","o":["اختبار النظر","اختبار قيادة جديد في كل مرة","مقال مكتوب","اختبار لياقة بدنية"],"h1":"فكّر في الحاسة التي تستعملها أكثر شيء لتقود بأمان.","h2":"السائقون الذين عمرهم 80 سنة أو أكثر يجب أن ينجحوا في اختبار النظر في كل مرة يجددون فيها الرخصة، لأن النظر الجيد ضروري للقيادة الآمنة.","p":"صحيح. السائقون بعمر 80 وأكثر يجب أن ينجحوا في اختبار النظر للتجديد."},"ht":{"q":"Nan Florida, kisa yon chofè ki gen 80 an oswa plis dwe pase lè l ap renouvle lisans li?","o":["Yon egzamen je","Yon nouvo egzamen sou wout la chak fwa","Yon redaksyon ekri","Yon tès fòm fizik"],"h1":"Panse ak sans ou itilize plis pou kondi san danje.","h2":"Chofè ki gen 80 an oswa plis dwe pase yon egzamen je chak fwa y ap renouvle lisans yo, paske ou bezwen wè byen pou kondi san danje.","p":"Se sa. Chofè 80 an oswa plis dwe pase yon egzamen je pou renouvle."},"ref":{"doc":"FL","page":14}},{"id":"licensing-044","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, you just moved here and became a resident. How soon must you get a Florida driver license?","o":["Within 1 year","Only when your old license expires","Within 30 days","Within 90 days"],"h1":"New residents have about one month.","h2":"A new Florida resident must get a Florida driver license within 30 days of becoming a resident.","p":"Right. New residents must get a Florida license within 30 days."},"es":{"q":"En Florida, usted se acaba de mudar y ya es residente. ¿En cuánto tiempo debe obtener una licencia de conducir de Florida?","o":["Dentro de 1 año","Solo cuando se venza su licencia anterior","Dentro de 30 días","Dentro de 90 días"],"h1":"Los residentes nuevos tienen más o menos un mes.","h2":"Un nuevo residente de Florida debe obtener una licencia de conducir de Florida dentro de 30 días después de hacerse residente.","p":"Correcto. Los residentes nuevos deben obtener la licencia de Florida dentro de 30 días."},"zh":{"q":"在 Florida，你刚搬来这里，成为居民。你必须在多长时间内拿到 Florida 驾照？","o":["1 年内","只在旧驾照过期时","30 天内","90 天内"],"h1":"新居民大约有一个月的时间。","h2":"Florida 的新居民必须在成为居民后 30 天内拿到 Florida 驾照。","p":"对。新居民必须在 30 天内拿到 Florida 驾照。"},"vi":{"q":"Ở Florida, bạn mới chuyển đến đây và trở thành cư dân. Bạn phải lấy bằng lái Florida trong bao lâu?","o":["Trong vòng 1 năm","Chỉ khi bằng lái cũ hết hạn","Trong vòng 30 ngày","Trong vòng 90 ngày"],"h1":"Cư dân mới có khoảng một tháng.","h2":"Cư dân mới của Florida phải lấy bằng lái Florida trong vòng 30 ngày kể từ khi trở thành cư dân.","p":"Đúng. Cư dân mới phải lấy bằng lái Florida trong vòng 30 ngày."},"tl":{"q":"Sa Florida, kalilipat mo lang dito at naging residente ka na. Gaano kabilis ka dapat kumuha ng Florida driver license?","o":["Sa loob ng 1 taon","Kapag nag-expire na lang ang luma mong lisensya","Sa loob ng 30 araw","Sa loob ng 90 araw"],"h1":"May mga isang buwan ang mga bagong residente.","h2":"Ang bagong residente ng Florida ay dapat kumuha ng Florida driver license sa loob ng 30 araw mula nang maging residente siya.","p":"Tama. Ang mga bagong residente ay dapat kumuha ng Florida license sa loob ng 30 araw."},"ar":{"q":"في Florida، انتقلت إلى هنا للتو وأصبحت مقيمًا. خلال كم من الوقت يجب أن تحصل على رخصة قيادة من Florida؟","o":["خلال سنة واحدة","فقط عندما تنتهي رخصتك القديمة","خلال 30 يومًا","خلال 90 يومًا"],"h1":"المقيمون الجدد لديهم حوالي شهر واحد.","h2":"المقيم الجديد في Florida يجب أن يحصل على رخصة قيادة من Florida خلال 30 يومًا من أن يصبح مقيمًا.","p":"صحيح. المقيمون الجدد يجب أن يحصلوا على رخصة Florida خلال 30 يومًا."},"ht":{"q":"Nan Florida, ou fèk vin rete isit la epi ou vin yon rezidan. Nan konbyen tan ou dwe jwenn yon lisans kondi Florida?","o":["Nan 1 an","Sèlman lè ansyen lisans ou a ekspire","Nan 30 jou","Nan 90 jou"],"h1":"Nouvo rezidan yo gen apeprè yon mwa.","h2":"Yon nouvo rezidan Florida dwe jwenn yon lisans kondi Florida nan 30 jou apre li vin rezidan.","p":"Se sa. Nouvo rezidan yo dwe jwenn yon lisans Florida nan 30 jou."},"ref":{"doc":"FL","page":3}},{"id":"licensing-045","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what kind of license do most people need to drive a regular car?","o":["A Class A license","A Class E license","A Class B license","A motorcycle endorsement"],"h1":"Classes A and B are for large commercial vehicles.","h2":"Most people need a Class E license to drive a regular car, because Classes A, B, and C are for commercial vehicles.","p":"Right. A regular car needs a Class E license."},"es":{"q":"En Florida, ¿qué tipo de licencia necesita la mayoría de las personas para manejar un carro común?","o":["Una licencia Clase A","Una licencia Clase E","Una licencia Clase B","Un endoso de motocicleta"],"h1":"Las Clases A y B son para vehículos comerciales grandes.","h2":"La mayoría de las personas necesita una licencia Clase E para manejar un carro común, porque las Clases A, B y C son para vehículos comerciales.","p":"Correcto. Un carro común requiere una licencia Clase E."},"zh":{"q":"在 Florida，大多数人开普通汽车需要哪种驾照？","o":["Class A 驾照","Class E 驾照","Class B 驾照","摩托车附加许可"],"h1":"Class A 和 Class B 是给大型商用车的。","h2":"大多数人开普通汽车需要 Class E 驾照，因为 Class A、B 和 C 是给商用车的。","p":"对。普通汽车需要 Class E 驾照。"},"vi":{"q":"Ở Florida, đa số người cần loại bằng lái nào để lái xe hơi thông thường?","o":["Bằng lái Class A","Bằng lái Class E","Bằng lái Class B","Chứng nhận lái xe máy"],"h1":"Class A và Class B dành cho xe thương mại lớn.","h2":"Đa số người cần bằng lái Class E để lái xe hơi thông thường, vì Class A, B và C dành cho xe thương mại.","p":"Đúng. Xe hơi thông thường cần bằng lái Class E."},"tl":{"q":"Sa Florida, anong klase ng lisensya ang kailangan ng karamihan para magmaneho ng ordinaryong kotse?","o":["Class A license","Class E license","Class B license","Motorcycle endorsement"],"h1":"Ang Class A at B ay para sa malalaking commercial vehicle.","h2":"Karamihan ng tao ay nangangailangan ng Class E license para magmaneho ng ordinaryong kotse, dahil ang Class A, B, at C ay para sa mga commercial vehicle.","p":"Tama. Ang ordinaryong kotse ay nangangailangan ng Class E license."},"ar":{"q":"في Florida، ما نوع الرخصة التي يحتاجها معظم الناس لقيادة سيارة عادية؟","o":["رخصة Class A","رخصة Class E","رخصة Class B","إضافة الدراجة النارية على الرخصة"],"h1":"الفئتان A وB للمركبات التجارية الكبيرة.","h2":"معظم الناس يحتاجون إلى رخصة Class E لقيادة سيارة عادية، لأن الفئات A وB وC للمركبات التجارية.","p":"صحيح. السيارة العادية تحتاج إلى رخصة Class E."},"ht":{"q":"Nan Florida, ki kalite lisans pifò moun bezwen pou kondi yon machin òdinè?","o":["Yon lisans Class A","Yon lisans Class E","Yon lisans Class B","Yon andòsman motosiklèt"],"h1":"Class A ak Class B se pou gwo machin komèsyal.","h2":"Pifò moun bezwen yon lisans Class E pou kondi yon machin òdinè, paske Class A, B, ak C se pou machin komèsyal.","p":"Se sa. Yon machin òdinè bezwen yon lisans Class E."},"ref":{"doc":"FL","page":4}},{"id":"right-of-way-001","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, at a four-way stop, which car goes first?","o":["The car that came to a full stop first","The largest vehicle at the stop","The car on the far left","The car that is going straight"],"h1":"Think about the order in which the cars arrived.","h2":"At a four-way stop, the driver who stopped first goes first, and the others follow in the order they arrived.","p":"Right. At a four-way stop, the first car to stop goes first."},"es":{"q":"En Florida, en un pare de cuatro vías, ¿qué carro sigue primero?","o":["El carro que hizo el alto total primero","El vehículo más grande en el pare","El carro que está más a la izquierda","El carro que va derecho"],"h1":"Piense en el orden en que llegaron los carros.","h2":"En un pare de cuatro vías, el conductor que paró primero sigue primero, y los demás siguen en el orden en que llegaron.","p":"Correcto. En un pare de cuatro vías, el primer carro en parar sigue primero."},"zh":{"q":"在 Florida，在四向停车路口，哪辆车先走？","o":["最先完全停下的车","路口最大的车","最左边的车","直行的车"],"h1":"想一想车辆到达的先后顺序。","h2":"在四向停车路口，最先停下的司机先走，其他车按到达的顺序跟着走。","p":"对。在四向停车路口，最先停下的车先走。"},"vi":{"q":"Ở Florida, tại ngã tư có biển \"STOP\" ở cả bốn phía, xe nào được đi trước?","o":["Xe dừng hẳn lại trước tiên","Xe lớn nhất tại chỗ dừng","Xe ở phía xa bên trái","Xe đang đi thẳng"],"h1":"Hãy nghĩ về thứ tự các xe đến nơi.","h2":"Tại ngã tư có biển \"STOP\" ở cả bốn phía, người lái dừng trước sẽ đi trước, và các xe khác đi theo thứ tự đã đến.","p":"Đúng. Tại ngã tư bốn biển \"STOP\", xe dừng trước được đi trước."},"tl":{"q":"Sa Florida, sa four-way stop, aling kotse ang unang aandar?","o":["Ang kotseng unang huminto nang buo","Ang pinakamalaking sasakyan sa hintuan","Ang kotseng nasa pinakakaliwa","Ang kotseng diretso ang punta"],"h1":"Isipin ang pagkakasunod-sunod ng pagdating ng mga kotse.","h2":"Sa four-way stop, ang drayber na unang huminto ang unang aandar, at susunod ang iba ayon sa pagkakasunod ng kanilang pagdating.","p":"Tama. Sa four-way stop, ang unang kotseng huminto ang unang aandar."},"ar":{"q":"في Florida، عند تقاطع فيه علامة توقف من أربع جهات، أي سيارة تمر أولًا؟","o":["السيارة التي توقفت توقفًا كاملًا أولًا","أكبر مركبة عند التقاطع","السيارة التي في أقصى اليسار","السيارة التي تسير إلى الأمام مباشرة"],"h1":"فكّر في الترتيب الذي وصلت به السيارات.","h2":"عند تقاطع فيه علامة توقف من أربع جهات، يمر أولًا السائق الذي توقف أولًا، ثم يمر الآخرون حسب ترتيب وصولهم.","p":"صحيح. عند علامة التوقف من أربع جهات، تمر أولًا السيارة التي توقفت أولًا."},"ht":{"q":"Nan Florida, nan yon kafou ki gen siy \"STOP\" sou kat bò, ki machin ki pase anvan?","o":["Machin ki te kanpe nèt an premye a","Pi gwo machin ki nan kafou a","Machin ki pi lwen sou bò gòch la","Machin k ap kontinye tou dwat la"],"h1":"Panse ak lòd machin yo te rive.","h2":"Nan yon kafou ki gen siy \"STOP\" sou kat bò, chofè ki te kanpe an premye a pase anvan, epi lòt yo swiv nan lòd yo te rive a.","p":"Wi, se sa. Nan yon kafou ki gen \"STOP\" sou kat bò, premye machin ki kanpe a pase anvan."},"ref":{"doc":"FL","page":47}},{"id":"right-of-way-002","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, two cars stop at a four-way stop at the same time. Who goes first?","o":["The driver who honks first","The driver on the left","The driver on the right","The driver who is in a hurry"],"h1":"Look at where the other car is, to your left or to your right.","h2":"When two cars stop at the same time, the driver on the left lets the driver on the right go first.","p":"Right. When you arrive together, the car on the right goes first."},"es":{"q":"En Florida, dos carros paran al mismo tiempo en un pare de cuatro vías. ¿Quién sigue primero?","o":["El conductor que toca la bocina primero","El conductor de la izquierda","El conductor de la derecha","El conductor que tiene prisa"],"h1":"Fíjese dónde está el otro carro, a su izquierda o a su derecha.","h2":"Cuando dos carros paran al mismo tiempo, el conductor de la izquierda deja pasar primero al conductor de la derecha.","p":"Correcto. Si llegan juntos, sigue primero el carro de la derecha."},"zh":{"q":"在 Florida，两辆车同时停在四向停车路口。谁先走？","o":["先按喇叭的司机","左边的司机","右边的司机","赶时间的司机"],"h1":"看看另一辆车在你的左边还是右边。","h2":"两辆车同时停下时，左边的司机让右边的司机先走。","p":"对。同时到达时，右边的车先走。"},"vi":{"q":"Ở Florida, hai xe dừng cùng lúc tại ngã tư có biển \"STOP\" ở cả bốn phía. Ai được đi trước?","o":["Người bấm còi trước","Người lái ở bên trái","Người lái ở bên phải","Người lái đang vội"],"h1":"Hãy xem xe kia ở đâu, bên trái hay bên phải của bạn.","h2":"Khi hai xe dừng cùng lúc, người lái bên trái phải để người lái bên phải đi trước.","p":"Đúng. Khi đến cùng lúc, xe bên phải được đi trước."},"tl":{"q":"Sa Florida, dalawang kotse ang sabay na huminto sa four-way stop. Sino ang unang aandar?","o":["Ang drayber na unang bumusina","Ang drayber na nasa kaliwa","Ang drayber na nasa kanan","Ang drayber na nagmamadali"],"h1":"Tingnan kung nasaan ang ibang kotse, sa kaliwa mo o sa kanan mo.","h2":"Kapag sabay na huminto ang dalawang kotse, pinauuna ng drayber na nasa kaliwa ang drayber na nasa kanan.","p":"Tama. Kapag sabay kayong dumating, ang kotse sa kanan ang unang aandar."},"ar":{"q":"في Florida، توقفت سيارتان عند تقاطع فيه علامة توقف من أربع جهات في الوقت نفسه. من يمر أولًا؟","o":["السائق الذي يستعمل البوق أولًا","السائق الذي على اليسار","السائق الذي على اليمين","السائق المستعجل"],"h1":"انظر أين السيارة الأخرى: على يسارك أم على يمينك؟","h2":"عندما تتوقف سيارتان في الوقت نفسه، يترك السائق الذي على اليسار السائقَ الذي على اليمين يمر أولًا.","p":"صحيح. عندما تصلان معًا، تمر السيارة التي على اليمين أولًا."},"ht":{"q":"Nan Florida, de machin kanpe nan yon kafou ki gen \"STOP\" sou kat bò an menm tan. Kiyès ki pase anvan?","o":["Chofè ki klaksonnen an premye a","Chofè ki sou bò gòch la","Chofè ki sou bò dwat la","Chofè ki prese a"],"h1":"Gade kote lòt machin nan ye, sou bò gòch ou oswa sou bò dwat ou.","h2":"Lè de machin kanpe an menm tan, chofè ki sou bò gòch la kite chofè ki sou bò dwat la pase anvan.","p":"Wi, se sa. Lè nou rive ansanm, machin ki sou bò dwat la pase anvan."},"ref":{"doc":"FL","page":47}},{"id":"right-of-way-003","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, you reach an intersection with no signs or lights. A car is already crossing it. What do you do?","o":["Go first, because you are on the wider road","Let the car that is already in the intersection go first","Honk and go at the same time","Speed up to cross before it"],"h1":"Think about who is already using the space.","h2":"At an intersection with no signs or lights, you must yield to a vehicle that is already in the intersection.","p":"Right. Yield to the car that is already in the intersection."},"es":{"q":"En Florida, usted llega a una intersección sin señales ni semáforos. Un carro ya la está cruzando. ¿Qué hace?","o":["Sigue primero, porque usted va por la calle más ancha","Deja pasar primero al carro que ya está en la intersección","Toca la bocina y sigue al mismo tiempo","Acelera para cruzar antes que él"],"h1":"Piense en quién ya está usando ese espacio.","h2":"En una intersección sin señales ni semáforos, usted debe ceder el paso al vehículo que ya está dentro de la intersección.","p":"Correcto. Ceda el paso al carro que ya está en la intersección."},"zh":{"q":"在 Florida，你来到一个没有标志也没有红绿灯的路口。有一辆车已经在通过路口。你该怎么做？","o":["你先走，因为你的路更宽","让已经在路口里的车先走","按喇叭，同时开过去","加速，抢在它前面通过"],"h1":"想一想谁已经在使用这个空间。","h2":"在没有标志也没有红绿灯的路口，你必须让已经在路口里的车先走。","p":"对。让已经在路口里的车先走。"},"vi":{"q":"Ở Florida, bạn đến một giao lộ không có biển báo hay đèn. Một xe đang chạy qua giao lộ. Bạn làm gì?","o":["Đi trước, vì đường của bạn rộng hơn","Để xe đang ở trong giao lộ đi trước","Bấm còi và đi cùng lúc","Tăng tốc để qua trước xe đó"],"h1":"Hãy nghĩ xem ai đang dùng chỗ đó rồi.","h2":"Tại giao lộ không có biển báo hay đèn, bạn phải nhường đường cho xe đã ở trong giao lộ.","p":"Đúng. Hãy nhường xe đã ở trong giao lộ."},"tl":{"q":"Sa Florida, dumating ka sa intersection na walang karatula o ilaw trapiko. May kotseng tumatawid na roon. Ano ang gagawin mo?","o":["Mauna ka, dahil mas malapad ang daan mo","Paunahin ang kotseng nasa loob na ng intersection","Bumusina at sabay na umandar","Bumilis para makatawid bago ito"],"h1":"Isipin kung sino na ang gumagamit ng lugar.","h2":"Sa intersection na walang karatula o ilaw, dapat kang magbigay-daan sa sasakyang nasa loob na ng intersection.","p":"Tama. Magbigay-daan sa kotseng nasa loob na ng intersection."},"ar":{"q":"في Florida، وصلت إلى تقاطع ليس فيه علامات ولا إشارات ضوئية. هناك سيارة تعبره الآن. ماذا تفعل؟","o":["أمر أولًا لأن طريقي أعرض","أترك السيارة التي في التقاطع تمر أولًا","أستعمل البوق وأمر في الوقت نفسه","أسرع لأعبر قبلها"],"h1":"فكّر في من يستعمل المكان الآن.","h2":"عند تقاطع ليس فيه علامات ولا إشارات ضوئية، يجب أن تعطي حق المرور للمركبة الموجودة داخل التقاطع.","p":"صحيح. أعطِ حق المرور للسيارة الموجودة داخل التقاطع."},"ht":{"q":"Nan Florida, ou rive nan yon kafou ki pa gen siy ni limyè. Gen yon machin ki deja ap travèse l. Kisa ou fè?","o":["Ou pase anvan, paske wout ou a pi laj","Ou kite machin ki deja nan kafou a pase anvan","Ou klaksonnen epi ou pase an menm tan","Ou akselere pou travèse anvan li"],"h1":"Panse ak kiyès ki deja ap sèvi ak espas la.","h2":"Nan yon kafou ki pa gen siy ni limyè, ou dwe kite yon machin ki deja nan kafou a pase anvan.","p":"Wi, se sa. Kite machin ki deja nan kafou a pase anvan."},"ref":{"doc":"FL","page":62}},{"id":"right-of-way-004","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, you and another car reach an intersection with no signs at the same time. The other car is on your right. Who goes first?","o":["You go first, because you are on the left","The faster car goes first","Both cars go at the same time","The car on your right goes first"],"h1":"The rule is the same as when two cars stop together at a stop sign.","h2":"When two cars reach an open intersection at the same time, the driver on the left yields, so the car on your right goes first.","p":"Right. At the same time, the car on the right goes first."},"es":{"q":"En Florida, usted y otro carro llegan al mismo tiempo a una intersección sin señales. El otro carro está a su derecha. ¿Quién sigue primero?","o":["Usted sigue primero, porque está a la izquierda","Sigue primero el carro más rápido","Los dos carros siguen al mismo tiempo","Sigue primero el carro que está a su derecha"],"h1":"La regla es igual que cuando dos carros paran juntos en un pare.","h2":"Cuando dos carros llegan al mismo tiempo a una intersección sin control, cede el paso el conductor de la izquierda, así que sigue primero el carro de su derecha.","p":"Correcto. Si llegan juntos, sigue primero el carro de la derecha."},"zh":{"q":"在 Florida，你和另一辆车同时来到一个没有标志的路口。另一辆车在你的右边。谁先走？","o":["你先走，因为你在左边","开得快的车先走","两辆车同时走","你右边的车先走"],"h1":"规则和两辆车同时停在停车标志前一样。","h2":"两辆车同时来到没有管制的路口时，左边的司机要让行，所以你右边的车先走。","p":"对。同时到达时，右边的车先走。"},"vi":{"q":"Ở Florida, bạn và một xe khác đến giao lộ không có biển báo cùng lúc. Xe kia ở bên phải bạn. Ai được đi trước?","o":["Bạn đi trước, vì bạn ở bên trái","Xe nhanh hơn đi trước","Cả hai xe đi cùng lúc","Xe bên phải bạn đi trước"],"h1":"Quy tắc giống như khi hai xe cùng dừng ở biển \"STOP\".","h2":"Khi hai xe đến giao lộ không có biển báo cùng lúc, người lái bên trái phải nhường, nên xe bên phải bạn được đi trước.","p":"Đúng. Khi đến cùng lúc, xe bên phải được đi trước."},"tl":{"q":"Sa Florida, sabay kayong dumating ng isa pang kotse sa intersection na walang karatula. Nasa kanan mo ang kotse. Sino ang mauuna?","o":["Ikaw ang mauuna, dahil nasa kaliwa ka","Ang mas mabilis na kotse ang mauuna","Sabay na aandar ang dalawang kotse","Ang kotse sa kanan mo ang mauuna"],"h1":"Pareho ang patakaran kapag sabay na huminto ang dalawang kotse sa stop sign.","h2":"Kapag sabay na dumating ang dalawang kotse sa bukas na intersection, nagbibigay-daan ang drayber sa kaliwa, kaya ang kotse sa kanan mo ang mauuna.","p":"Tama. Kapag sabay, ang kotse sa kanan ang mauuna."},"ar":{"q":"في Florida، وصلت أنت وسيارة أخرى إلى تقاطع ليس فيه علامات في الوقت نفسه. السيارة الأخرى على يمينك. من يمر أولًا؟","o":["أنت تمر أولًا لأنك على اليسار","السيارة الأسرع تمر أولًا","تمر السيارتان في الوقت نفسه","السيارة التي على يمينك تمر أولًا"],"h1":"القاعدة هي نفسها عندما تتوقف سيارتان معًا عند علامة توقف.","h2":"عندما تصل سيارتان إلى تقاطع مفتوح في الوقت نفسه، يعطي السائق الذي على اليسار حق المرور، لذلك تمر السيارة التي على يمينك أولًا.","p":"صحيح. إذا وصلتما في الوقت نفسه، تمر السيارة التي على اليمين أولًا."},"ht":{"q":"Nan Florida, ou menm ak yon lòt machin rive an menm tan nan yon kafou ki pa gen siy. Lòt machin nan sou bò dwat ou. Kiyès ki pase anvan?","o":["Ou pase anvan, paske ou sou bò gòch la","Machin ki pi vit la pase anvan","De machin yo pase an menm tan","Machin ki sou bò dwat ou a pase anvan"],"h1":"Règ la se menm jan ak lè de machin kanpe ansanm devan yon siy \"STOP\".","h2":"Lè de machin rive an menm tan nan yon kafou ki pa gen siy, chofè ki sou bò gòch la kite lòt la pase, kidonk machin ki sou bò dwat ou a pase anvan.","p":"Wi, se sa. Lè nou rive an menm tan, machin ki sou bò dwat la pase anvan."},"ref":{"doc":"FL","page":62}},{"id":"right-of-way-006","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, you want to turn left at a green light. A car is coming toward you. What do you do?","o":["Turn quickly before it gets close","Turn, because a green light gives you the right of way","Wait and let the oncoming car pass first","Flash your lights and turn"],"h1":"A green light lets you go, but it does not clear the road in front of you.","h2":"When you turn left, you must yield to oncoming traffic, so you wait until the car passes and the way is clear.","p":"Right. When turning left, let oncoming traffic go first."},"es":{"q":"En Florida, usted quiere doblar a la izquierda con luz verde. Viene un carro de frente. ¿Qué hace?","o":["Dobla rápido antes de que se acerque","Dobla, porque la luz verde le da el derecho de paso","Espera y deja pasar primero al carro que viene de frente","Hace cambio de luces y dobla"],"h1":"La luz verde le permite seguir, pero no despeja la calle delante de usted.","h2":"Cuando usted dobla a la izquierda, debe ceder el paso al tráfico que viene de frente, así que espera hasta que el carro pase y el camino esté libre.","p":"Correcto. Al doblar a la izquierda, deje pasar primero al tráfico de frente."},"zh":{"q":"在 Florida，绿灯时你想左转。对面有一辆车开过来。你该怎么做？","o":["趁它还没靠近，赶快转","转弯，因为绿灯给你先行权","等一等，让对面的车先过去","闪一下车灯，然后转弯"],"h1":"绿灯让你可以走，但不代表你前面的路是空的。","h2":"左转时，你必须让对面来的车先走，所以要等那辆车过去、路上安全了再转。","p":"对。左转时，让对面来的车先走。"},"vi":{"q":"Ở Florida, bạn muốn rẽ trái khi đèn xanh. Có một xe đang chạy ngược chiều về phía bạn. Bạn làm gì?","o":["Rẽ nhanh trước khi xe đó đến gần","Rẽ, vì đèn xanh cho bạn quyền ưu tiên","Chờ và để xe ngược chiều đi qua trước","Nháy đèn rồi rẽ"],"h1":"Đèn xanh cho phép bạn đi, nhưng không làm đường phía trước trống.","h2":"Khi rẽ trái, bạn phải nhường xe đi ngược chiều, nên bạn chờ xe đó đi qua và đường trống rồi mới rẽ.","p":"Đúng. Khi rẽ trái, hãy để xe ngược chiều đi trước."},"tl":{"q":"Sa Florida, gusto mong kumaliwa sa berdeng ilaw. May kotseng paparating mula sa harap mo. Ano ang gagawin mo?","o":["Kumaliwa agad bago ito makalapit","Kumaliwa, dahil binibigyan ka ng berdeng ilaw ng karapatan sa daan","Maghintay at paunahin ang paparating na kotse","Mag-flash ng ilaw at kumaliwa"],"h1":"Pinapayagan kang umandar ng berdeng ilaw, pero hindi nito nililinis ang daan sa harap mo.","h2":"Kapag kumakaliwa ka, dapat kang magbigay-daan sa paparating na trapiko, kaya maghihintay ka hanggang makalampas ang kotse at malinis ang daan.","p":"Tama. Kapag kumakaliwa, paunahin ang paparating na trapiko."},"ar":{"q":"في Florida، تريد أن تنعطف يسارًا والإشارة خضراء. هناك سيارة قادمة نحوك. ماذا تفعل؟","o":["أنعطف بسرعة قبل أن تقترب","أنعطف، لأن الإشارة الخضراء تعطيني حق المرور","أنتظر وأترك السيارة القادمة تمر أولًا","أومض بالأضواء وأنعطف"],"h1":"الإشارة الخضراء تسمح لك بالتحرك، لكنها لا تجعل الطريق أمامك فارغًا.","h2":"عندما تنعطف يسارًا، يجب أن تعطي حق المرور للسيارات القادمة نحوك، لذلك تنتظر حتى تمر السيارة ويصبح الطريق فارغًا.","p":"صحيح. عند الانعطاف يسارًا، اترك السيارات القادمة نحوك تمر أولًا."},"ht":{"q":"Nan Florida, ou vle vire agòch lè limyè a vèt. Gen yon machin k ap vin sou ou. Kisa ou fè?","o":["Ou vire vit anvan li rive pre","Ou vire, paske limyè vèt la ba ou dwa pou pase anvan","Ou tann epi ou kite machin k ap vin sou ou a pase anvan","Ou flache limyè ou epi ou vire"],"h1":"Yon limyè vèt kite ou ale, men li pa libere wout ki devan ou a.","h2":"Lè w ap vire agòch, ou dwe kite machin k ap vin sou ou yo pase anvan, kidonk ou tann machin nan pase epi wout la lib.","p":"Wi, se sa. Lè w ap vire agòch, kite machin k ap vin sou ou yo pase anvan."},"ref":{"doc":"FL","page":62}},{"id":"right-of-way-007","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, you are pulling out of a driveway onto a street. Who must you yield to?","o":["Only to large trucks","No one, if you use your signal","Only to cars on your left","All cars on the street and all people walking"],"h1":"You are joining a road that others are already using.","h2":"When you enter a street from a driveway or alley, you must yield to every vehicle on the street and to every pedestrian.","p":"Right. Coming out of a driveway, yield to cars and people walking."},"es":{"q":"En Florida, usted sale de una entrada de casa hacia la calle. ¿A quién debe ceder el paso?","o":["Solo a los camiones grandes","A nadie, si usa la direccional","Solo a los carros de su izquierda","A todos los carros de la calle y a todas las personas que caminan"],"h1":"Usted entra a una calle que otros ya están usando.","h2":"Cuando usted entra a una calle desde una entrada de casa o un callejón, debe ceder el paso a todos los vehículos de la calle y a todos los peatones.","p":"Correcto. Al salir de una entrada de casa, ceda el paso a carros y peatones."},"zh":{"q":"在 Florida，你正从私人车道开上街道。你必须给谁让行？","o":["只给大卡车","谁都不用，只要你打了转向灯","只给你左边的车","街上所有的车和所有走路的人"],"h1":"你要开上一条别人已经在用的路。","h2":"从私人车道或小巷开上街道时，你必须让街上的每一辆车和每一个行人先走。","p":"对。从私人车道出来时，要让车和行人先走。"},"vi":{"q":"Ở Florida, bạn đang lái xe từ lối vào nhà ra đường. Bạn phải nhường ai?","o":["Chỉ nhường xe tải lớn","Không ai cả, nếu bạn bật đèn xi nhan","Chỉ nhường xe bên trái","Mọi xe trên đường và mọi người đi bộ"],"h1":"Bạn đang đi vào con đường mà người khác đang dùng.","h2":"Khi bạn từ lối vào nhà hoặc hẻm đi ra đường, bạn phải nhường mọi xe trên đường và mọi người đi bộ.","p":"Đúng. Khi ra từ lối vào nhà, hãy nhường xe và người đi bộ."},"tl":{"q":"Sa Florida, lalabas ka mula sa driveway papunta sa kalye. Kanino ka dapat magbigay-daan?","o":["Sa malalaking trak lang","Wala, kung gagamit ka ng signal","Sa mga kotse lang sa kaliwa mo","Sa lahat ng kotse sa kalye at sa lahat ng taong naglalakad"],"h1":"Papasok ka sa daan na ginagamit na ng iba.","h2":"Kapag pumapasok ka sa kalye mula sa driveway o eskinita, dapat kang magbigay-daan sa bawat sasakyan sa kalye at sa bawat taong naglalakad.","p":"Tama. Paglabas sa driveway, magbigay-daan sa mga kotse at sa mga naglalakad."},"ar":{"q":"في Florida، تخرج بسيارتك من ممر خاص إلى الشارع. لمن يجب أن تعطي حق المرور؟","o":["للشاحنات الكبيرة فقط","لا أحد، إذا استعملت إشارة الانعطاف","للسيارات التي على يساري فقط","لكل السيارات في الشارع ولكل المشاة"],"h1":"أنت تدخل طريقًا يستعمله آخرون الآن.","h2":"عندما تدخل الشارع من ممر خاص أو من زقاق، يجب أن تعطي حق المرور لكل مركبة في الشارع ولكل شخص يمشي.","p":"صحيح. عند الخروج من ممر خاص، أعطِ حق المرور للسيارات وللمشاة."},"ht":{"q":"Nan Florida, w ap sòti nan antre yon kay pou antre nan yon lari. Kiyès ou dwe kite pase anvan?","o":["Sèlman gwo kamyon","Pèsonn, si ou mete siyal ou","Sèlman machin ki sou bò gòch ou","Tout machin ki nan lari a ak tout moun k ap mache a pye"],"h1":"W ap antre sou yon wout lòt moun deja ap sèvi.","h2":"Lè w ap antre nan yon lari sòti nan antre yon kay oswa nan yon ti ri, ou dwe kite tout machin ki nan lari a ak tout moun k ap mache a pye pase anvan.","p":"Wi, se sa. Lè w ap sòti nan antre yon kay, kite machin yo ak moun k ap mache yo pase anvan."},"ref":{"doc":"FL","page":62}},{"id":"right-of-way-008","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, you drive out of an alley. There is a sidewalk before the street. Where must you stop?","o":["Before you cross the sidewalk","In the middle of the sidewalk","At the edge of the street, past the sidewalk","You do not need to stop"],"h1":"Think about people who may be walking on the sidewalk.","h2":"When you come out of an alley or driveway, you must stop before the sidewalk, so you do not hit someone walking there.","p":"Right. Stop before the sidewalk when you leave an alley or driveway."},"es":{"q":"En Florida, usted sale de un callejón. Hay una acera antes de la calle. ¿Dónde debe parar?","o":["Antes de cruzar la acera","En medio de la acera","En el borde de la calle, después de la acera","No necesita parar"],"h1":"Piense en las personas que pueden ir caminando por la acera.","h2":"Cuando usted sale de un callejón o de una entrada de casa, debe parar antes de la acera, para no golpear a alguien que camina por ahí.","p":"Correcto. Pare antes de la acera al salir de un callejón o entrada."},"zh":{"q":"在 Florida，你从小巷开出来。到街道前有一段人行道。你必须在哪里停车？","o":["在穿过人行道之前","在人行道中间","在街道边上，过了人行道以后","你不需要停车"],"h1":"想一想可能正在人行道上走路的人。","h2":"从小巷或私人车道开出来时，你必须在人行道前停车，这样才不会撞到在那里走路的人。","p":"对。离开小巷或私人车道时，要在人行道前停车。"},"vi":{"q":"Ở Florida, bạn lái xe ra khỏi một con hẻm. Trước đường có vỉa hè. Bạn phải dừng ở đâu?","o":["Trước khi đi qua vỉa hè","Ở giữa vỉa hè","Ở mép đường, sau vỉa hè","Bạn không cần dừng"],"h1":"Hãy nghĩ đến những người có thể đang đi trên vỉa hè.","h2":"Khi ra khỏi hẻm hoặc lối vào nhà, bạn phải dừng trước vỉa hè, để không đụng vào người đang đi bộ ở đó.","p":"Đúng. Hãy dừng trước vỉa hè khi ra khỏi hẻm hoặc lối vào nhà."},"tl":{"q":"Sa Florida, lumabas ka mula sa eskinita. May bangketa bago ang kalye. Saan ka dapat huminto?","o":["Bago ka tumawid sa bangketa","Sa gitna ng bangketa","Sa gilid ng kalye, lampas sa bangketa","Hindi mo kailangang huminto"],"h1":"Isipin ang mga taong maaaring naglalakad sa bangketa.","h2":"Kapag lumalabas ka mula sa eskinita o driveway, dapat kang huminto bago ang bangketa, para hindi ka makabangga ng taong naglalakad doon.","p":"Tama. Huminto bago ang bangketa kapag lumalabas sa eskinita o driveway."},"ar":{"q":"في Florida، تخرج بسيارتك من زقاق. يوجد رصيف قبل الشارع. أين يجب أن تتوقف؟","o":["قبل أن أعبر الرصيف","في وسط الرصيف","عند طرف الشارع، بعد الرصيف","لا أحتاج إلى التوقف"],"h1":"فكّر في الناس الذين قد يمشون على الرصيف.","h2":"عندما تخرج من زقاق أو ممر خاص، يجب أن تتوقف قبل الرصيف، حتى لا تصدم شخصًا يمشي هناك.","p":"صحيح. توقف قبل الرصيف عندما تخرج من زقاق أو ممر خاص."},"ht":{"q":"Nan Florida, w ap sòti nan yon ti ri. Gen yon twotwa anvan lari a. Ki kote ou dwe kanpe?","o":["Anvan ou travèse twotwa a","Nan mitan twotwa a","Bò lari a, apre twotwa a","Ou pa bezwen kanpe"],"h1":"Panse ak moun ki ka ap mache sou twotwa a.","h2":"Lè w ap sòti nan yon ti ri oswa nan antre yon kay, ou dwe kanpe anvan twotwa a, pou ou pa frape yon moun k ap mache la.","p":"Wi, se sa. Kanpe anvan twotwa a lè w ap sòti nan yon ti ri oswa nan antre yon kay."},"ref":{"doc":"FL","page":62}},{"id":"right-of-way-009","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, a person is crossing at a corner with no painted crosswalk lines. Must you yield?","o":["No, only painted crosswalks count","Yes, the corner of an intersection is a crosswalk even without lines","Only if the person is a child","Only if a police officer is there"],"h1":"A crosswalk does not always have paint.","h2":"Every corner of an intersection has a crosswalk even when no lines are painted, so you must yield to the person crossing.","p":"Right. Yield to people crossing at a corner, with or without lines."},"es":{"q":"En Florida, una persona cruza en una esquina sin líneas pintadas de cruce peatonal. ¿Debe usted ceder el paso?","o":["No, solo cuentan los cruces pintados","Sí, la esquina de una intersección es un cruce peatonal aunque no tenga líneas","Solo si la persona es un niño","Solo si hay un policía"],"h1":"Un cruce peatonal no siempre tiene pintura.","h2":"Cada esquina de una intersección tiene un cruce peatonal aunque no tenga líneas pintadas, así que usted debe ceder el paso a la persona que cruza.","p":"Correcto. Ceda el paso a quien cruza en la esquina, con o sin líneas."},"zh":{"q":"在 Florida，有人在一个没有画人行横道线的路口拐角过马路。你必须让行吗？","o":["不用，只有画了线的人行横道才算","要，路口的拐角就算没有画线，也是人行横道","只有过马路的是小孩时才要","只有警察在场时才要"],"h1":"人行横道不一定都画了线。","h2":"路口的每个拐角都有人行横道，就算没有画线也一样，所以你必须让过马路的人先走。","p":"对。不管有没有画线，都要让在拐角过马路的人先走。"},"vi":{"q":"Ở Florida, một người đang băng qua đường ở góc giao lộ không có vạch kẻ cho người đi bộ. Bạn có phải nhường không?","o":["Không, chỉ chỗ có vạch kẻ mới tính","Có, góc giao lộ là lối qua đường dù không có vạch kẻ","Chỉ khi người đó là trẻ em","Chỉ khi có cảnh sát ở đó"],"h1":"Lối qua đường cho người đi bộ không phải lúc nào cũng có sơn.","h2":"Mỗi góc của giao lộ đều có lối qua đường dù không có vạch sơn, nên bạn phải nhường người đang băng qua.","p":"Đúng. Hãy nhường người băng qua ở góc giao lộ, có vạch hay không có vạch."},"tl":{"q":"Sa Florida, may taong tumatawid sa kanto na walang pinturang guhit ng crosswalk. Dapat ka bang magbigay-daan?","o":["Hindi, ang may pinturang crosswalk lang ang binibilang","Oo, ang kanto ng intersection ay crosswalk kahit walang guhit","Kung bata lang ang tao","Kung may pulis lang doon"],"h1":"Hindi laging may pintura ang crosswalk.","h2":"Bawat kanto ng intersection ay may crosswalk kahit walang pinturang guhit, kaya dapat kang magbigay-daan sa taong tumatawid.","p":"Tama. Magbigay-daan sa mga tumatawid sa kanto, may guhit man o wala."},"ar":{"q":"في Florida، شخص يعبر الشارع عند زاوية تقاطع ليس فيها خطوط ممر مشاة مرسومة. هل يجب أن تعطيه حق المرور؟","o":["لا، ممرات المشاة المرسومة فقط هي المهمة","نعم، زاوية التقاطع هي ممر مشاة حتى بدون خطوط","فقط إذا كان الشخص طفلًا","فقط إذا كان هناك شرطي"],"h1":"ممر المشاة ليس مرسومًا دائمًا.","h2":"عند كل زاوية من زوايا التقاطع يوجد ممر مشاة حتى لو لم تكن هناك خطوط مرسومة، لذلك يجب أن تعطي حق المرور للشخص الذي يعبر.","p":"صحيح. أعطِ حق المرور للناس الذين يعبرون عند الزاوية، مع خطوط أو بدونها."},"ht":{"q":"Nan Florida, yon moun ap travèse nan kwen yon kafou ki pa gen liy pasaj pyeton ki pentire. Èske ou dwe kite l pase?","o":["Non, se sèlman pasaj pyeton ki pentire ki konte","Wi, kwen yon kafou se yon pasaj pyeton menm si li pa gen liy","Sèlman si moun nan se yon timoun","Sèlman si gen yon polis la"],"h1":"Yon pasaj pyeton pa toujou gen penti.","h2":"Chak kwen yon kafou gen yon pasaj pyeton menm lè pa gen liy ki pentire, kidonk ou dwe kite moun k ap travèse a pase.","p":"Wi, se sa. Kite moun k ap travèse nan kwen kafou a pase, kit gen liy kit pa gen liy."},"ref":{"doc":"FL","page":87}},{"id":"right-of-way-010","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, you turn right on a green light. People are crossing the street you are turning into. What do you do?","o":["Drive slowly between them","Honk so they move faster","Stop and let them finish crossing","Turn, because your light is green"],"h1":"Your path crosses their path.","h2":"When you turn, you must yield to people walking in the crosswalk, so you stop and wait until they are out of your way.","p":"Right. When you turn, let people in the crosswalk cross first."},"es":{"q":"En Florida, usted dobla a la derecha con luz verde. Hay personas cruzando la calle a la que usted va a entrar. ¿Qué hace?","o":["Pasa despacio entre ellas","Toca la bocina para que caminen más rápido","Para y las deja terminar de cruzar","Dobla, porque su luz está en verde"],"h1":"Su camino se cruza con el camino de ellas.","h2":"Cuando usted dobla, debe ceder el paso a las personas que caminan en el cruce peatonal, así que para y espera hasta que salgan de su camino.","p":"Correcto. Al doblar, deje cruzar primero a las personas en el cruce peatonal."},"zh":{"q":"在 Florida，你在绿灯时右转。有人正在过你要转进去的那条街。你该怎么做？","o":["从他们中间慢慢开过去","按喇叭让他们走快一点","停车，让他们走完","转弯，因为你是绿灯"],"h1":"你的路线和他们的路线交叉。","h2":"转弯时，你必须让人行横道上的行人先走，所以你要停下来，等他们离开你的路线。","p":"对。转弯时，让人行横道上的人先过。"},"vi":{"q":"Ở Florida, bạn rẽ phải khi đèn xanh. Có người đang băng qua con đường bạn sắp rẽ vào. Bạn làm gì?","o":["Lái chậm len giữa họ","Bấm còi để họ đi nhanh hơn","Dừng lại và để họ qua hết đường","Rẽ, vì đèn của bạn là đèn xanh"],"h1":"Đường đi của bạn cắt ngang đường đi của họ.","h2":"Khi rẽ, bạn phải nhường người đi bộ trên lối qua đường, nên bạn dừng lại và chờ đến khi họ đi khỏi đường của bạn.","p":"Đúng. Khi rẽ, hãy để người trên lối qua đường đi trước."},"tl":{"q":"Sa Florida, kumanan ka sa berdeng ilaw. May mga taong tumatawid sa kalyeng papasukan mo. Ano ang gagawin mo?","o":["Dahan-dahang dumaan sa pagitan nila","Bumusina para bumilis sila","Huminto at hayaan silang matapos tumawid","Kumanan, dahil berde ang ilaw mo"],"h1":"Nagtatagpo ang daan mo at ang daan nila.","h2":"Kapag lumiliko ka, dapat kang magbigay-daan sa mga taong naglalakad sa crosswalk, kaya hihinto ka at maghihintay hanggang wala na sila sa daan mo.","p":"Tama. Kapag lumiliko, paunahing tumawid ang mga tao sa crosswalk."},"ar":{"q":"في Florida، تنعطف يمينًا والإشارة خضراء. هناك أشخاص يعبرون الشارع الذي تدخل إليه. ماذا تفعل؟","o":["أقود ببطء بينهم","أستعمل البوق ليسرعوا","أتوقف وأتركهم ينهون العبور","أنعطف، لأن الإشارة عندي خضراء"],"h1":"طريقك يقطع طريقهم.","h2":"عندما تنعطف، يجب أن تعطي حق المرور للمشاة في ممر المشاة، لذلك تتوقف وتنتظر حتى يبتعدوا عن طريقك.","p":"صحيح. عندما تنعطف، اترك الناس في ممر المشاة يعبرون أولًا."},"ht":{"q":"Nan Florida, ou vire adwat lè limyè a vèt. Gen moun k ap travèse lari kote w ap vire a. Kisa ou fè?","o":["Ou kondi dousman nan mitan yo","Ou klaksonnen pou yo mache pi vit","Ou kanpe epi ou kite yo fin travèse","Ou vire, paske limyè ou a vèt"],"h1":"Chemen pa w la kwaze chemen pa yo a.","h2":"Lè w ap vire, ou dwe kite moun k ap mache nan pasaj pyeton an pase anvan, kidonk ou kanpe epi ou tann yo sòti nan chemen ou.","p":"Wi, se sa. Lè w ap vire, kite moun ki nan pasaj pyeton an travèse anvan."},"ref":{"doc":"FL","page":87}},{"id":"right-of-way-011","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, a person with a white cane or a guide dog is crossing the street. What must you do?","o":["Honk to let the person know you are there","Drive around the person carefully","Go if your light is green","Stop and let the person cross"],"h1":"A white cane or guide dog tells you the person may not be able to see you.","h2":"A person who is blind and uses a white cane or a guide dog always has the right of way, so you must stop and let them cross.","p":"Right. Always stop for a person with a white cane or guide dog."},"es":{"q":"En Florida, una persona con bastón blanco o con perro guía está cruzando la calle. ¿Qué debe hacer usted?","o":["Tocar la bocina para avisar que usted está ahí","Pasar alrededor de la persona con cuidado","Seguir si su luz está en verde","Parar y dejar que la persona cruce"],"h1":"Un bastón blanco o un perro guía le indican que la persona tal vez no puede verlo.","h2":"Una persona ciega que usa bastón blanco o perro guía siempre tiene el derecho de paso, así que usted debe parar y dejarla cruzar.","p":"Correcto. Siempre pare por una persona con bastón blanco o perro guía."},"zh":{"q":"在 Florida，有一个拿白色手杖或带导盲犬的人正在过马路。你必须怎么做？","o":["按喇叭，让这个人知道你在那里","小心地绕过这个人","如果你是绿灯，就开过去","停车，让这个人过马路"],"h1":"白色手杖或导盲犬告诉你，这个人可能看不见你。","h2":"使用白色手杖或导盲犬的盲人永远有先行权，所以你必须停车，让他们过马路。","p":"对。看到拿白色手杖或带导盲犬的人，一定要停车。"},"vi":{"q":"Ở Florida, một người cầm gậy trắng hoặc có chó dẫn đường đang băng qua đường. Bạn phải làm gì?","o":["Bấm còi để người đó biết bạn ở đó","Lái vòng qua người đó một cách cẩn thận","Đi tiếp nếu đèn của bạn là đèn xanh","Dừng lại và để người đó băng qua"],"h1":"Gậy trắng hoặc chó dẫn đường cho bạn biết người đó có thể không nhìn thấy bạn.","h2":"Người khiếm thị dùng gậy trắng hoặc chó dẫn đường luôn có quyền ưu tiên, nên bạn phải dừng lại và để họ băng qua.","p":"Đúng. Luôn dừng lại cho người cầm gậy trắng hoặc có chó dẫn đường."},"tl":{"q":"Sa Florida, may taong may puting tungkod o guide dog na tumatawid sa kalye. Ano ang dapat mong gawin?","o":["Bumusina para malaman niyang nandiyan ka","Maingat na umiwas sa paligid niya","Umandar kung berde ang ilaw mo","Huminto at hayaan siyang tumawid"],"h1":"Ang puting tungkod o guide dog ay nagsasabing maaaring hindi ka nakikita ng tao.","h2":"Ang taong bulag na gumagamit ng puting tungkod o guide dog ay laging may karapatan sa daan, kaya dapat kang huminto at hayaan siyang tumawid.","p":"Tama. Laging huminto para sa taong may puting tungkod o guide dog."},"ar":{"q":"في Florida، شخص معه عصا بيضاء أو كلب مرشد يعبر الشارع. ماذا يجب أن تفعل؟","o":["أستعمل البوق حتى يعرف أنني هنا","أقود حوله بحذر","أتحرك إذا كانت الإشارة عندي خضراء","أتوقف وأترك الشخص يعبر"],"h1":"العصا البيضاء أو الكلب المرشد يخبرك أن الشخص قد لا يستطيع أن يراك.","h2":"الشخص الكفيف الذي يستعمل عصا بيضاء أو كلبًا مرشدًا له حق المرور دائمًا، لذلك يجب أن تتوقف وتتركه يعبر.","p":"صحيح. توقف دائمًا لشخص معه عصا بيضاء أو كلب مرشد."},"ht":{"q":"Nan Florida, yon moun ki gen yon baton blan oswa yon chen gid ap travèse lari a. Kisa ou dwe fè?","o":["Ou klaksonnen pou moun nan konnen ou la","Ou fè yon ti detou dousman bò kote moun nan","Ou pase si limyè ou a vèt","Ou kanpe epi ou kite moun nan travèse"],"h1":"Yon baton blan oswa yon chen gid montre ou moun nan ka pa ka wè ou.","h2":"Yon moun ki avèg epi ki sèvi ak yon baton blan oswa yon chen gid toujou gen dwa pou pase anvan, kidonk ou dwe kanpe epi kite l travèse.","p":"Wi, se sa. Toujou kanpe pou yon moun ki gen yon baton blan oswa yon chen gid."},"ref":{"doc":"FL","page":88}},{"id":"right-of-way-012","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, you are about to enter a roundabout. Who has the right of way?","o":["Traffic already moving inside the roundabout","You, because you are entering","The car on your right that is also entering","The driver who honks first"],"h1":"Think about who is already driving in the circle.","h2":"When you enter a roundabout, you must yield to traffic that is already in the circle, then enter when there is a safe gap.","p":"Right. Yield to cars already in the roundabout."},"es":{"q":"En Florida, usted va a entrar a una rotonda. ¿Quién tiene el derecho de paso?","o":["El tráfico que ya va dentro de la rotonda","Usted, porque está entrando","El carro de su derecha que también está entrando","El conductor que toca la bocina primero"],"h1":"Piense en quién ya va manejando dentro del círculo.","h2":"Cuando usted entra a una rotonda, debe ceder el paso al tráfico que ya está en el círculo, y luego entrar cuando haya un espacio seguro.","p":"Correcto. Ceda el paso a los carros que ya están en la rotonda."},"zh":{"q":"在 Florida，你马上要进入环岛。谁有先行权？","o":["已经在环岛里行驶的车","你，因为你正在进入","你右边也正在进入的车","先按喇叭的司机"],"h1":"想一想谁已经在环岛里开车。","h2":"进入环岛时，你必须让已经在环岛里的车先走，等有安全的空隙再进去。","p":"对。让已经在环岛里的车先走。"},"vi":{"q":"Ở Florida, bạn sắp đi vào vòng xuyến. Ai có quyền ưu tiên?","o":["Xe đang chạy bên trong vòng xuyến","Bạn, vì bạn đang đi vào","Xe bên phải bạn cũng đang đi vào","Người lái bấm còi trước"],"h1":"Hãy nghĩ xem ai đang chạy trong vòng xuyến rồi.","h2":"Khi đi vào vòng xuyến, bạn phải nhường xe đã ở trong vòng xuyến, rồi đi vào khi có khoảng trống an toàn.","p":"Đúng. Hãy nhường xe đã ở trong vòng xuyến."},"tl":{"q":"Sa Florida, papasok ka na sa roundabout. Sino ang may karapatan sa daan?","o":["Ang trapikong umaandar na sa loob ng roundabout","Ikaw, dahil papasok ka","Ang kotse sa kanan mo na papasok din","Ang drayber na unang bumusina"],"h1":"Isipin kung sino na ang nagmamaneho sa loob ng bilog.","h2":"Kapag pumapasok ka sa roundabout, dapat kang magbigay-daan sa trapikong nasa loob na ng bilog, at pumasok kapag may ligtas na puwang.","p":"Tama. Magbigay-daan sa mga kotseng nasa loob na ng roundabout."},"ar":{"q":"في Florida، أنت على وشك أن تدخل دوّارًا. من له حق المرور؟","o":["السيارات التي تسير الآن داخل الدوّار","أنت، لأنك تدخل","السيارة التي على يمينك وتدخل أيضًا","السائق الذي يستعمل البوق أولًا"],"h1":"فكّر في من يقود الآن داخل الدائرة.","h2":"عندما تدخل دوّارًا، يجب أن تعطي حق المرور للسيارات الموجودة داخل الدائرة، ثم تدخل عندما توجد مسافة آمنة.","p":"صحيح. أعطِ حق المرور للسيارات الموجودة داخل الدوّار."},"ht":{"q":"Nan Florida, ou pral antre nan yon wonpwen. Kiyès ki gen dwa pou pase anvan?","o":["Machin ki deja ap woule anndan wonpwen an","Ou menm, paske w ap antre","Machin ki sou bò dwat ou ki ap antre tou a","Chofè ki klaksonnen an premye a"],"h1":"Panse ak kiyès ki deja ap kondi nan wonn nan.","h2":"Lè w ap antre nan yon wonpwen, ou dwe kite machin ki deja nan wonn nan pase anvan, epi ou antre lè gen yon espas ki san danje.","p":"Wi, se sa. Kite machin ki deja nan wonpwen an pase anvan."},"ref":{"doc":"FL","page":63}},{"id":"right-of-way-013","scope":"US","cat":"right-of-way","sign":null,"c":1,"en":{"q":"Which way do cars travel in a roundabout in the United States?","o":["Clockwise, to the left","Counterclockwise, to the right","Either way the driver picks","Straight across the middle"],"h1":"In the United States, you drive on the right side of the road.","h2":"In a roundabout in the United States, you enter to the right and travel counterclockwise around the center.","p":"Right. In a roundabout, go to the right, counterclockwise."},"es":{"q":"¿Hacia qué lado van los carros en una rotonda en los Estados Unidos?","o":["En el sentido del reloj, hacia la izquierda","En contra del reloj, hacia la derecha","Hacia el lado que el conductor escoja","Derecho por el centro"],"h1":"En los Estados Unidos se maneja por el lado derecho de la calle.","h2":"En una rotonda en los Estados Unidos, usted entra hacia la derecha y da la vuelta en contra del sentido del reloj alrededor del centro.","p":"Correcto. En una rotonda, vaya hacia la derecha, en contra del reloj."},"zh":{"q":"在美国，车在环岛里朝哪个方向行驶？","o":["顺时针，向左","逆时针，向右","司机想走哪边都行","从中间直接穿过去"],"h1":"在美国，车靠道路右边行驶。","h2":"在美国的环岛里，你向右进入，然后绕着中心逆时针行驶。","p":"对。在环岛里，向右走，逆时针方向。"},"vi":{"q":"Ở Hoa Kỳ, xe chạy theo chiều nào trong vòng xuyến?","o":["Theo chiều kim đồng hồ, sang trái","Ngược chiều kim đồng hồ, sang phải","Theo chiều nào người lái chọn cũng được","Đi thẳng qua giữa"],"h1":"Ở Hoa Kỳ, bạn lái xe bên phải đường.","h2":"Trong vòng xuyến ở Hoa Kỳ, bạn đi vào về phía bên phải và chạy ngược chiều kim đồng hồ quanh tâm.","p":"Đúng. Trong vòng xuyến, đi sang phải, ngược chiều kim đồng hồ."},"tl":{"q":"Saang direksiyon umiikot ang mga kotse sa roundabout sa United States?","o":["Kasunod ng ikot ng orasan (clockwise), papuntang kaliwa","Salungat sa ikot ng orasan (counterclockwise), papuntang kanan","Kahit saan, depende sa drayber","Diretso sa gitna"],"h1":"Sa United States, sa kanang bahagi ng daan ka nagmamaneho.","h2":"Sa roundabout sa United States, papasok ka pakanan at iikot nang salungat sa ikot ng orasan (counterclockwise) sa paligid ng gitna.","p":"Tama. Sa roundabout, pumunta pakanan, salungat sa ikot ng orasan."},"ar":{"q":"في أي اتجاه تسير السيارات داخل الدوّار في الولايات المتحدة؟","o":["مع عقارب الساعة، إلى اليسار","عكس عقارب الساعة، إلى اليمين","في أي اتجاه يختاره السائق","مباشرة عبر الوسط"],"h1":"في الولايات المتحدة، تقود على الجانب الأيمن من الطريق.","h2":"في الدوّار في الولايات المتحدة، تدخل إلى اليمين وتسير عكس عقارب الساعة حول الوسط.","p":"صحيح. في الدوّار، اذهب إلى اليمين، عكس عقارب الساعة."},"ht":{"q":"Nan Etazini, nan ki direksyon machin yo woule nan yon wonpwen?","o":["Nan direksyon zegwi mont, sou bò gòch","Kont direksyon zegwi mont, sou bò dwat","Nan direksyon chofè a chwazi a","Tou dwat nan mitan an"],"h1":"Nan Etazini, ou kondi sou bò dwat wout la.","h2":"Nan yon wonpwen nan Etazini, ou antre sou bò dwat epi ou woule kont direksyon zegwi mont toutotou mitan an.","p":"Wi, se sa. Nan yon wonpwen, ale sou bò dwat, kont direksyon zegwi mont."},"ref":{"doc":"FL","page":63}},{"id":"right-of-way-014","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, an ambulance with a siren and flashing lights is coming behind you. What do you do?","o":["Speed up to stay ahead of it","Stop right where you are, in your lane","Pull to the nearest edge of the road and stop","Move to the left lane and keep driving"],"h1":"The ambulance needs a clear path. Think about where you can get out of its way.","h2":"When an emergency vehicle comes with a siren and flashing lights, you pull to the nearest edge of the road and stop until it passes.","p":"Right. Pull to the nearest edge and stop for emergency vehicles."},"es":{"q":"En Florida, una ambulancia con sirena y luces intermitentes viene detrás de usted. ¿Qué hace?","o":["Acelera para mantenerse delante","Para donde está, en su carril","Se orilla al borde más cercano de la calle y para","Se pasa al carril izquierdo y sigue manejando"],"h1":"La ambulancia necesita el camino libre. Piense dónde puede quitarse de su camino.","h2":"Cuando viene un vehículo de emergencia con sirena y luces intermitentes, usted se orilla al borde más cercano de la calle y para hasta que pase.","p":"Correcto. Oríllese al borde más cercano y pare para los vehículos de emergencia."},"zh":{"q":"在 Florida，一辆鸣着警笛、闪着灯的救护车从你后面开过来。你该怎么做？","o":["加速，保持在它前面","就在你的车道里原地停下","靠到离你最近的路边，然后停车","换到左边车道，继续开"],"h1":"救护车需要一条畅通的路。想一想你可以躲到哪里。","h2":"当急救车辆鸣着警笛、闪着灯开过来时，你要靠到最近的路边停车，等它过去。","p":"对。遇到急救车辆，靠到最近的路边停车。"},"vi":{"q":"Ở Florida, một xe cứu thương hú còi và nháy đèn đang đến từ phía sau bạn. Bạn làm gì?","o":["Tăng tốc để chạy trước xe đó","Dừng ngay tại chỗ, trong làn của bạn","Tấp vào mép đường gần nhất và dừng lại","Chuyển sang làn trái và tiếp tục chạy"],"h1":"Xe cứu thương cần đường trống. Hãy nghĩ xem bạn có thể tránh ra ở đâu.","h2":"Khi xe khẩn cấp đến với còi hú và đèn nháy, bạn tấp vào mép đường gần nhất và dừng lại cho đến khi xe đó đi qua.","p":"Đúng. Hãy tấp vào mép đường gần nhất và dừng lại cho xe khẩn cấp."},"tl":{"q":"Sa Florida, may ambulansiyang may sirena at kumikislap na ilaw na paparating sa likod mo. Ano ang gagawin mo?","o":["Bumilis para manatiling nauuna rito","Huminto kung nasaan ka, sa lane mo","Tumabi sa pinakamalapit na gilid ng daan at huminto","Lumipat sa kaliwang lane at magpatuloy"],"h1":"Kailangan ng ambulansiya ng malinis na daan. Isipin kung saan ka puwedeng umiwas.","h2":"Kapag may emergency vehicle na may sirena at kumikislap na ilaw, tatabi ka sa pinakamalapit na gilid ng daan at hihinto hanggang makalampas ito.","p":"Tama. Tumabi sa pinakamalapit na gilid at huminto para sa mga emergency vehicle."},"ar":{"q":"في Florida، سيارة إسعاف بصفارة وأضواء وامضة تأتي خلفك. ماذا تفعل؟","o":["أسرع لأبقى أمامها","أتوقف في مكاني، داخل مساري","أتحرك إلى أقرب طرف للطريق وأتوقف","أنتقل إلى المسار الأيسر وأستمر في القيادة"],"h1":"سيارة الإسعاف تحتاج إلى طريق فارغ. فكّر أين يمكنك أن تبتعد عن طريقها.","h2":"عندما تأتي مركبة طوارئ بصفارة وأضواء وامضة، تتحرك إلى أقرب طرف للطريق وتتوقف حتى تمر.","p":"صحيح. تحرك إلى أقرب طرف وتوقف لمركبات الطوارئ."},"ht":{"q":"Nan Florida, yon anbilans ki gen siren ak limyè k ap flache ap vini dèyè ou. Kisa ou fè?","o":["Ou akselere pou rete devan l","Ou kanpe la menm, nan liy ou a","Ou rale sou bò wout ki pi pre a epi ou kanpe","Ou ale nan liy gòch la epi ou kontinye kondi"],"h1":"Anbilans lan bezwen yon chemen ki lib. Panse ak ki kote ou ka sòti nan chemen l.","h2":"Lè yon machin ijans vini ak siren ak limyè k ap flache, ou rale sou bò wout ki pi pre a epi ou kanpe jiskaske li pase.","p":"Wi, se sa. Rale sou bò wout ki pi pre a epi kanpe pou machin ijans yo."},"ref":{"doc":"FL","page":84}},{"id":"right-of-way-015","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, you are in the middle of an intersection when you hear a fire truck siren behind you. What do you do?","o":["Drive through the intersection, then pull to the nearest edge and stop","Stop in the middle of the intersection","Back up out of the intersection","Turn left right away"],"h1":"Stopping inside the intersection can block the fire truck.","h2":"If you are already in an intersection, you keep going through it and then pull to the nearest edge and stop, so you do not block the emergency vehicle.","p":"Right. Clear the intersection first, then pull over and stop."},"es":{"q":"En Florida, usted está en medio de una intersección cuando oye la sirena de un camión de bomberos detrás. ¿Qué hace?","o":["Cruza la intersección y luego se orilla al borde más cercano y para","Para en medio de la intersección","Da reversa para salir de la intersección","Dobla a la izquierda de inmediato"],"h1":"Parar dentro de la intersección puede bloquear al camión de bomberos.","h2":"Si usted ya está en una intersección, sigue hasta cruzarla y luego se orilla al borde más cercano y para, para no bloquear al vehículo de emergencia.","p":"Correcto. Primero salga de la intersección, luego oríllese y pare."},"zh":{"q":"在 Florida，你正在路口中间，听到后面有消防车的警笛声。你该怎么做？","o":["开过路口，然后靠到最近的路边停车","停在路口中间","倒车退出路口","马上左转"],"h1":"停在路口里面可能会挡住消防车。","h2":"如果你已经在路口里，就继续开过去，然后靠到最近的路边停车，这样就不会挡住急救车辆。","p":"对。先开出路口，再靠边停车。"},"vi":{"q":"Ở Florida, bạn đang ở giữa giao lộ thì nghe tiếng còi xe cứu hỏa phía sau. Bạn làm gì?","o":["Chạy qua hết giao lộ, rồi tấp vào mép đường gần nhất và dừng lại","Dừng lại giữa giao lộ","Lùi xe ra khỏi giao lộ","Rẽ trái ngay lập tức"],"h1":"Dừng lại trong giao lộ có thể chắn đường xe cứu hỏa.","h2":"Nếu bạn đã ở trong giao lộ, bạn tiếp tục chạy qua, rồi tấp vào mép đường gần nhất và dừng lại, để không chắn đường xe khẩn cấp.","p":"Đúng. Hãy ra khỏi giao lộ trước, rồi tấp vào lề và dừng lại."},"tl":{"q":"Sa Florida, nasa gitna ka ng intersection nang marinig mo ang sirena ng trak ng bumbero sa likod mo. Ano ang gagawin mo?","o":["Tumawid sa intersection, saka tumabi sa pinakamalapit na gilid at huminto","Huminto sa gitna ng intersection","Umatras palabas ng intersection","Kumaliwa agad"],"h1":"Kapag huminto ka sa loob ng intersection, maaari mong maharangan ang trak ng bumbero.","h2":"Kung nasa intersection ka na, magpatuloy ka hanggang makalabas dito, saka tumabi sa pinakamalapit na gilid at huminto, para hindi mo maharangan ang emergency vehicle.","p":"Tama. Lumabas muna sa intersection, saka tumabi at huminto."},"ar":{"q":"في Florida، أنت في وسط التقاطع وتسمع صفارة سيارة إطفاء خلفك. ماذا تفعل؟","o":["أعبر التقاطع، ثم أتحرك إلى أقرب طرف وأتوقف","أتوقف في وسط التقاطع","أرجع إلى الخلف وأخرج من التقاطع","أنعطف يسارًا فورًا"],"h1":"إذا توقفت داخل التقاطع، قد تسد الطريق على سيارة الإطفاء.","h2":"إذا كنت داخل التقاطع، تستمر حتى تعبره، ثم تتحرك إلى أقرب طرف وتتوقف، حتى لا تسد الطريق على مركبة الطوارئ.","p":"صحيح. اعبر التقاطع أولًا، ثم ابتعد إلى الطرف وتوقف."},"ht":{"q":"Nan Florida, ou nan mitan yon kafou lè ou tande siren yon kamyon ponpye dèyè ou. Kisa ou fè?","o":["Ou travèse kafou a, apre sa ou rale sou bò ki pi pre a epi ou kanpe","Ou kanpe nan mitan kafou a","Ou fè bak pou sòti nan kafou a","Ou vire agòch touswit"],"h1":"Si ou kanpe anndan kafou a, ou ka bloke kamyon ponpye a.","h2":"Si ou deja nan yon kafou, ou kontinye travèse l, apre sa ou rale sou bò ki pi pre a epi ou kanpe, pou ou pa bloke machin ijans lan.","p":"Wi, se sa. Libere kafou a anvan, apre sa rale sou kote epi kanpe."},"ref":{"doc":"FL","page":84}},{"id":"right-of-way-016","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, a funeral procession is passing through an intersection. What should you do?","o":["Drive between the cars when there is a gap","Join the end of the line","Honk so they move faster","Yield and wait until the whole procession passes"],"h1":"The cars in the procession are traveling together as one group.","h2":"You must yield to a funeral procession and must not cut through it or join it, so you wait until all of it has passed.","p":"Right. Yield to a funeral procession and let it pass."},"es":{"q":"En Florida, un cortejo fúnebre está pasando por una intersección. ¿Qué debe hacer?","o":["Pasar entre los carros cuando haya un espacio","Unirse al final de la fila","Tocar la bocina para que avancen más rápido","Ceder el paso y esperar hasta que pase todo el cortejo"],"h1":"Los carros del cortejo viajan juntos como un solo grupo.","h2":"Usted debe ceder el paso a un cortejo fúnebre y no debe cruzarlo ni unirse a él, así que espera hasta que pase completo.","p":"Correcto. Ceda el paso al cortejo fúnebre y déjelo pasar."},"zh":{"q":"在 Florida，一支送葬车队正在通过路口。你应该怎么做？","o":["趁有空隙，从车队中间开过去","跟在车队最后面","按喇叭让他们走快一点","让行，等整个车队过去"],"h1":"送葬车队里的车是作为一个整体一起走的。","h2":"你必须给送葬车队让行，不能从中间穿过，也不能加入车队，所以要等整个车队都过去。","p":"对。给送葬车队让行，让它过去。"},"vi":{"q":"Ở Florida, một đoàn xe đưa tang đang đi qua giao lộ. Bạn nên làm gì?","o":["Chạy chen vào giữa các xe khi có khoảng trống","Nhập vào cuối đoàn xe","Bấm còi để họ đi nhanh hơn","Nhường đường và chờ cả đoàn xe đi qua"],"h1":"Các xe trong đoàn đưa tang đi cùng nhau như một nhóm.","h2":"Bạn phải nhường đoàn xe đưa tang và không được chen ngang hay nhập vào đoàn, nên bạn chờ đến khi cả đoàn đi qua.","p":"Đúng. Hãy nhường đoàn xe đưa tang và để đoàn đi qua."},"tl":{"q":"Sa Florida, may prusisyon ng libing na dumaraan sa intersection. Ano ang dapat mong gawin?","o":["Sumingit sa pagitan ng mga kotse kapag may puwang","Sumama sa dulo ng hanay","Bumusina para bumilis sila","Magbigay-daan at maghintay hanggang makalampas ang buong prusisyon"],"h1":"Magkakasamang bumibiyahe ang mga kotse sa prusisyon bilang isang grupo.","h2":"Dapat kang magbigay-daan sa prusisyon ng libing at hindi ka dapat sumingit o sumama rito, kaya maghihintay ka hanggang makalampas ang lahat ng ito.","p":"Tama. Magbigay-daan sa prusisyon ng libing at hayaan itong makalampas."},"ar":{"q":"في Florida، موكب جنازة يعبر التقاطع. ماذا يجب أن تفعل؟","o":["أقود بين السيارات عندما توجد فجوة","أنضم إلى آخر الموكب","أستعمل البوق ليسرعوا","أعطي حق المرور وأنتظر حتى يمر الموكب كله"],"h1":"السيارات في الموكب تسير معًا كمجموعة واحدة.","h2":"يجب أن تعطي حق المرور لموكب الجنازة، ولا يجوز أن تقطعه أو تنضم إليه، لذلك تنتظر حتى يمر كله.","p":"صحيح. أعطِ حق المرور لموكب الجنازة واتركه يمر."},"ht":{"q":"Nan Florida, yon kòtèj antèman ap travèse yon kafou. Kisa ou ta dwe fè?","o":["Ou pase nan mitan machin yo lè gen yon espas","Ou antre nan bout liy lan","Ou klaksonnen pou yo ale pi vit","Ou kite yo pase epi ou tann tout kòtèj la fin pase"],"h1":"Machin ki nan kòtèj la ap mache ansanm tankou yon sèl gwoup.","h2":"Ou dwe kite yon kòtèj antèman pase, ou pa dwe koupe l ni antre ladan l, kidonk ou tann jiskaske tout kòtèj la fin pase.","p":"Wi, se sa. Kite yon kòtèj antèman pase."},"ref":{"doc":"FL","page":84}},{"id":"right-of-way-017","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, a police car is stopped on the shoulder with its lights flashing. You are on a road with two lanes going your way. What must you do?","o":["Keep your speed and stay in your lane","Move out of the lane closest to the police car if it is safe","Stop next to the police car","Honk as you pass"],"h1":"Florida's Move Over law asks you to give stopped workers more space.","h2":"Under Florida's Move Over law, you must leave the lane closest to the stopped emergency vehicle when it is safe to change lanes.","p":"Right. Move over a lane for a stopped emergency vehicle."},"es":{"q":"En Florida, una patrulla de policía está parada en el acotamiento con las luces intermitentes. Usted va por una calle con dos carriles en su dirección. ¿Qué debe hacer?","o":["Mantener su velocidad y seguir en su carril","Salir del carril más cercano a la patrulla si es seguro","Parar al lado de la patrulla","Tocar la bocina al pasar"],"h1":"La ley Move Over de Florida le pide dar más espacio a quienes están parados trabajando.","h2":"Según la ley Move Over de Florida, usted debe salir del carril más cercano al vehículo de emergencia parado cuando sea seguro cambiar de carril.","p":"Correcto. Cámbiese de carril para un vehículo de emergencia parado."},"zh":{"q":"在 Florida，一辆警车停在路肩上，车灯在闪。你所在的路，你的方向有两条车道。你必须怎么做？","o":["保持车速，留在你的车道里","如果安全，离开最靠近警车的那条车道","停在警车旁边","经过时按喇叭"],"h1":"Florida 的 Move Over 法要求你给停在路边工作的人多留空间。","h2":"根据 Florida 的 Move Over 法，在可以安全换道时，你必须离开最靠近停着的急救车辆的那条车道。","p":"对。遇到停着的急救车辆，要让出一条车道。"},"vi":{"q":"Ở Florida, một xe cảnh sát đang dừng trên lề đường và nháy đèn. Đường của bạn có hai làn cùng chiều. Bạn phải làm gì?","o":["Giữ tốc độ và ở lại trong làn của bạn","Rời khỏi làn gần xe cảnh sát nhất nếu an toàn","Dừng lại cạnh xe cảnh sát","Bấm còi khi chạy qua"],"h1":"Luật \"Move Over\" của Florida yêu cầu bạn chừa thêm chỗ cho người đang làm việc bên đường.","h2":"Theo luật \"Move Over\" của Florida, bạn phải rời khỏi làn gần xe khẩn cấp đang dừng nhất khi đổi làn an toàn.","p":"Đúng. Hãy chuyển sang làn khác khi có xe khẩn cấp đang dừng."},"tl":{"q":"Sa Florida, may kotse ng pulis na nakahinto sa shoulder (gilid ng daan) na kumikislap ang ilaw. Nasa daan ka na may dalawang lane papunta sa direksiyon mo. Ano ang dapat mong gawin?","o":["Panatilihin ang bilis mo at manatili sa lane mo","Umalis sa lane na pinakamalapit sa kotse ng pulis kung ligtas","Huminto sa tabi ng kotse ng pulis","Bumusina habang dumaraan"],"h1":"Hinihiling ng Move Over law ng Florida na bigyan mo ng mas malaking espasyo ang mga nakahintong manggagawa.","h2":"Ayon sa Move Over law ng Florida, dapat mong iwan ang lane na pinakamalapit sa nakahintong emergency vehicle kapag ligtas lumipat ng lane.","p":"Tama. Lumipat ng isang lane para sa nakahintong emergency vehicle."},"ar":{"q":"في Florida، سيارة شرطة متوقفة على كتف الطريق وأضواؤها تومض. أنت على طريق فيه مساران في اتجاهك. ماذا يجب أن تفعل؟","o":["أحافظ على سرعتي وأبقى في مساري","أترك المسار الأقرب إلى سيارة الشرطة إذا كان ذلك آمنًا","أتوقف بجانب سيارة الشرطة","أستعمل البوق وأنا أمر"],"h1":"قانون Move Over في Florida يطلب منك أن تعطي العاملين المتوقفين مساحة أكبر.","h2":"حسب قانون Move Over في Florida، يجب أن تترك المسار الأقرب إلى مركبة الطوارئ المتوقفة عندما يكون تغيير المسار آمنًا.","p":"صحيح. ابتعد مسارًا واحدًا عن مركبة الطوارئ المتوقفة."},"ht":{"q":"Nan Florida, yon machin polis kanpe sou bò wout la ak limyè l ap flache. Ou sou yon wout ki gen de liy k ap ale nan menm direksyon ak ou. Kisa ou dwe fè?","o":["Ou kenbe menm vitès la epi ou rete nan liy ou","Ou sòti nan liy ki pi pre machin polis la si sa pa danjere","Ou kanpe bò kote machin polis la","Ou klaksonnen lè w ap pase"],"h1":"Lwa Move Over Florida a mande ou bay moun k ap travay epi ki kanpe yo plis espas.","h2":"Dapre lwa Move Over Florida a, ou dwe kite liy ki pi pre machin ijans ki kanpe a lè ou ka chanje liy san danje.","p":"Wi, se sa. Chanje liy pou yon machin ijans ki kanpe."},"ref":{"doc":"FL","page":65}},{"id":"right-of-way-018","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, you cannot safely move over for a stopped emergency vehicle. The speed limit is 55 mph. What must you do?","o":["Keep driving at 55 mph","Stop in your lane","Slow to 20 mph below the limit, so 35 mph","Speed up to pass it quickly"],"h1":"If you cannot move over, the law asks for a big cut in speed.","h2":"When you cannot move over, Florida law says you must slow to 20 mph below the posted speed limit, so on a 55 mph road you slow to 35 mph.","p":"Right. If you cannot move over, slow to 20 mph below the limit."},"es":{"q":"En Florida, usted no puede cambiarse de carril con seguridad para un vehículo de emergencia parado. El límite de velocidad es 55 mph. ¿Qué debe hacer?","o":["Seguir manejando a 55 mph","Parar en su carril","Bajar a 20 mph menos que el límite, o sea 35 mph","Acelerar para pasarlo rápido"],"h1":"Si no puede cambiarse de carril, la ley le pide bajar mucho la velocidad.","h2":"Cuando usted no puede cambiarse de carril, la ley de Florida dice que debe bajar a 20 mph menos que el límite marcado, así que en una calle de 55 mph baja a 35 mph.","p":"Correcto. Si no puede cambiarse de carril, baje 20 mph del límite."},"zh":{"q":"在 Florida，你没办法安全地给停着的急救车辆让出车道。限速是 55 英里/小时。你必须怎么做？","o":["继续以 55 英里/小时行驶","停在你的车道里","减速到比限速低 20 英里/小时，也就是 35 英里/小时","加速，快点开过去"],"h1":"如果你不能换道，法律要求你大幅减速。","h2":"不能换道时，Florida 法律规定你必须减速到比限速低 20 英里/小时，所以在限速 55 英里/小时的路上，你要减到 35 英里/小时。","p":"对。不能换道时，要减速到比限速低 20 英里/小时。"},"vi":{"q":"Ở Florida, bạn không thể chuyển làn an toàn để tránh một xe khẩn cấp đang dừng. Giới hạn tốc độ là 55 mph. Bạn phải làm gì?","o":["Tiếp tục chạy 55 mph","Dừng lại trong làn của bạn","Giảm xuống thấp hơn giới hạn 20 mph, tức là 35 mph","Tăng tốc để vượt qua nhanh"],"h1":"Nếu không thể chuyển làn, luật yêu cầu bạn giảm tốc độ nhiều.","h2":"Khi không thể chuyển làn, luật Florida nói bạn phải giảm xuống thấp hơn giới hạn tốc độ 20 mph, nên trên đường 55 mph bạn giảm xuống 35 mph.","p":"Đúng. Nếu không thể chuyển làn, hãy giảm xuống thấp hơn giới hạn 20 mph."},"tl":{"q":"Sa Florida, hindi ka ligtas na makalipat ng lane para sa nakahintong emergency vehicle. Ang speed limit ay 55 mph. Ano ang dapat mong gawin?","o":["Magpatuloy sa 55 mph","Huminto sa lane mo","Bumagal sa 20 mph na mas mababa sa limit, kaya 35 mph","Bumilis para madaanan ito agad"],"h1":"Kung hindi ka makalipat, malaking bawas sa bilis ang hinihingi ng batas.","h2":"Kapag hindi ka makalipat ng lane, sinasabi ng batas ng Florida na dapat kang bumagal sa 20 mph na mas mababa sa nakapaskil na speed limit, kaya sa daang 55 mph, bababa ka sa 35 mph.","p":"Tama. Kung hindi ka makalipat, bumagal sa 20 mph na mas mababa sa limit."},"ar":{"q":"في Florida، لا تستطيع أن تبتعد بأمان عن مركبة طوارئ متوقفة. حد السرعة 55 ميلًا في الساعة. ماذا يجب أن تفعل؟","o":["أستمر بسرعة 55 ميلًا في الساعة","أتوقف في مساري","أخفف السرعة إلى 20 ميلًا في الساعة أقل من الحد، أي 35 ميلًا في الساعة","أسرع لأتجاوزها بسرعة"],"h1":"إذا لم تستطع أن تبتعد، يطلب القانون تخفيضًا كبيرًا في السرعة.","h2":"عندما لا تستطيع أن تبتعد، يقول قانون Florida إنه يجب أن تخفف السرعة إلى 20 ميلًا في الساعة أقل من حد السرعة المكتوب، لذلك على طريق حده 55 ميلًا في الساعة تخفف إلى 35 ميلًا في الساعة.","p":"صحيح. إذا لم تستطع أن تبتعد، خفف السرعة إلى 20 ميلًا في الساعة أقل من الحد."},"ht":{"q":"Nan Florida, ou pa ka chanje liy san danje pou yon machin ijans ki kanpe. Limit vitès la se 55 mph. Kisa ou dwe fè?","o":["Ou kontinye kondi a 55 mph","Ou kanpe nan liy ou","Ou ralanti pou ou desann 20 mph anba limit la, sa vle di 35 mph","Ou akselere pou pase l vit"],"h1":"Si ou pa ka chanje liy, lwa a mande ou bese vitès ou anpil.","h2":"Lè ou pa ka chanje liy, lwa Florida di ou dwe ralanti pou ou desann 20 mph anba limit vitès ki afiche a, kidonk sou yon wout 55 mph ou desann a 35 mph.","p":"Wi, se sa. Si ou pa ka chanje liy, desann 20 mph anba limit la."},"ref":{"doc":"FL","page":65}},{"id":"right-of-way-019","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, the speed limit is 20 mph. A tow truck is stopped with its lights flashing, and you cannot move over. How fast may you pass it?","o":["5 mph","15 mph","20 mph","10 mph"],"h1":"Twenty below the limit would be zero, so the law gives a special number.","h2":"When the speed limit is 20 mph or less and you cannot move over, Florida law says you must slow to 5 mph.","p":"Right. On a road of 20 mph or less, slow to 5 mph."},"es":{"q":"En Florida, el límite de velocidad es 20 mph. Una grúa está parada con las luces intermitentes y usted no puede cambiarse de carril. ¿A qué velocidad puede pasarla?","o":["5 mph","15 mph","20 mph","10 mph"],"h1":"Veinte menos que el límite sería cero, así que la ley da un número especial.","h2":"Cuando el límite es 20 mph o menos y usted no puede cambiarse de carril, la ley de Florida dice que debe bajar a 5 mph.","p":"Correcto. En una calle de 20 mph o menos, baje a 5 mph."},"zh":{"q":"在 Florida，限速是 20 英里/小时。一辆拖车停着，车灯在闪，你又没办法换道。你最快可以用多少速度经过它？","o":["5 英里/小时","15 英里/小时","20 英里/小时","10 英里/小时"],"h1":"比限速低 20 就变成零了，所以法律给了一个特别的数字。","h2":"当限速是 20 英里/小时或更低，而你又不能换道时，Florida 法律规定你必须减速到 5 英里/小时。","p":"对。在限速 20 英里/小时或更低的路上，要减速到 5 英里/小时。"},"vi":{"q":"Ở Florida, giới hạn tốc độ là 20 mph. Một xe kéo đang dừng và nháy đèn, và bạn không thể chuyển làn. Bạn được chạy qua với tốc độ bao nhiêu?","o":["5 mph","15 mph","20 mph","10 mph"],"h1":"Thấp hơn giới hạn 20 thì sẽ là số không, nên luật đưa ra một con số riêng.","h2":"Khi giới hạn tốc độ là 20 mph hoặc thấp hơn và bạn không thể chuyển làn, luật Florida nói bạn phải giảm xuống 5 mph.","p":"Đúng. Trên đường 20 mph hoặc thấp hơn, hãy giảm xuống 5 mph."},"tl":{"q":"Sa Florida, 20 mph ang speed limit. May tow truck na nakahinto na kumikislap ang ilaw, at hindi ka makalipat ng lane. Gaano kabilis ka puwedeng dumaan?","o":["5 mph","15 mph","20 mph","10 mph"],"h1":"Kung babawasan ng dalawampu ang limit, magiging zero ito, kaya may espesyal na numero ang batas.","h2":"Kapag 20 mph o mas mababa ang speed limit at hindi ka makalipat ng lane, sinasabi ng batas ng Florida na dapat kang bumagal sa 5 mph.","p":"Tama. Sa daang 20 mph o mas mababa, bumagal sa 5 mph."},"ar":{"q":"في Florida، حد السرعة 20 ميلًا في الساعة. شاحنة سحب متوقفة وأضواؤها تومض، ولا تستطيع أن تبتعد عنها. بأي سرعة يمكنك أن تمر بجانبها؟","o":["5 أميال في الساعة","15 ميلًا في الساعة","20 ميلًا في الساعة","10 أميال في الساعة"],"h1":"عشرون أقل من الحد تساوي صفرًا، لذلك يعطي القانون رقمًا خاصًا.","h2":"عندما يكون حد السرعة 20 ميلًا في الساعة أو أقل ولا تستطيع أن تبتعد، يقول قانون Florida إنه يجب أن تخفف السرعة إلى 5 أميال في الساعة.","p":"صحيح. على طريق حده 20 ميلًا في الساعة أو أقل، خفف السرعة إلى 5 أميال في الساعة."},"ht":{"q":"Nan Florida, limit vitès la se 20 mph. Yon kamyon remòk kanpe ak limyè l ap flache, epi ou pa ka chanje liy. Ak ki vitès ou ka pase bò kote l?","o":["5 mph","15 mph","20 mph","10 mph"],"h1":"Ven anba limit la ta bay zewo, kidonk lwa a bay yon chif espesyal.","h2":"Lè limit vitès la se 20 mph oswa mwens epi ou pa ka chanje liy, lwa Florida di ou dwe desann a 5 mph.","p":"Wi, se sa. Sou yon wout 20 mph oswa mwens, desann a 5 mph."},"ref":{"doc":"FL","page":65}},{"id":"right-of-way-020","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, which of these stopped vehicles is covered by the Move Over law?","o":["A parked car with no lights on","A city bus at a bus stop","A delivery van at a store","A garbage truck with its warning lights flashing"],"h1":"The law covers workers on the road who show flashing warning lights.","h2":"Florida's Move Over law covers sanitation trucks, utility trucks, tow trucks, and road crews when they are stopped with warning lights flashing, so you must move over or slow down.","p":"Right. Move over for a stopped garbage truck with flashing lights."},"es":{"q":"En Florida, ¿cuál de estos vehículos parados está cubierto por la ley Move Over?","o":["Un carro estacionado sin luces encendidas","Un autobús de la ciudad en una parada","Una camioneta de reparto frente a una tienda","Un camión de basura con las luces de advertencia intermitentes"],"h1":"La ley cubre a trabajadores en la vía que muestran luces de advertencia intermitentes.","h2":"La ley Move Over de Florida cubre camiones de basura, de servicios públicos, grúas y equipos de carretera cuando están parados con luces de advertencia intermitentes, así que usted debe cambiarse de carril o bajar la velocidad.","p":"Correcto. Cámbiese de carril por un camión de basura parado con luces intermitentes."},"zh":{"q":"在 Florida，下面哪一辆停着的车受 Move Over 法保护？","o":["一辆没开灯的停放汽车","一辆停在车站的公交车","一辆停在商店门口的送货车","一辆闪着警示灯的垃圾车"],"h1":"这条法律保护在路上工作、并闪着警示灯的人。","h2":"Florida 的 Move Over 法保护停着并闪着警示灯的环卫车、公用事业车、拖车和道路施工人员，所以你必须换道或减速。","p":"对。遇到闪着灯停着的垃圾车，要让出车道。"},"vi":{"q":"Ở Florida, xe nào sau đây khi đang dừng thì thuộc luật \"Move Over\"?","o":["Xe hơi đậu không bật đèn","Xe buýt thành phố ở trạm xe buýt","Xe giao hàng ở cửa hàng","Xe rác đang nháy đèn cảnh báo"],"h1":"Luật này bảo vệ người làm việc trên đường có đèn cảnh báo nhấp nháy.","h2":"Luật \"Move Over\" của Florida áp dụng cho xe rác, xe của công ty điện nước, xe kéo và đội sửa đường khi họ dừng và nháy đèn cảnh báo, nên bạn phải chuyển làn hoặc giảm tốc.","p":"Đúng. Hãy chuyển làn khi có xe rác đang dừng và nháy đèn."},"tl":{"q":"Sa Florida, alin sa mga nakahintong sasakyang ito ang sakop ng Move Over law?","o":["Nakaparadang kotse na walang ilaw","Bus ng lungsod sa bus stop","Delivery van sa harap ng tindahan","Trak ng basura na kumikislap ang warning lights"],"h1":"Sakop ng batas ang mga manggagawa sa daan na nagpapakita ng kumikislap na warning lights.","h2":"Sakop ng Move Over law ng Florida ang mga trak ng basura, trak ng utility, tow truck, at mga road crew kapag nakahinto sila na kumikislap ang warning lights, kaya dapat kang lumipat ng lane o bumagal.","p":"Tama. Lumipat ng lane para sa nakahintong trak ng basura na kumikislap ang ilaw."},"ar":{"q":"في Florida، أي مركبة متوقفة من هذه المركبات يشملها قانون Move Over؟","o":["سيارة مركونة وأضواؤها مطفأة","حافلة مدينة عند محطة الحافلات","شاحنة توصيل صغيرة عند متجر","شاحنة نفايات أضواء التحذير فيها تومض"],"h1":"القانون يشمل العاملين على الطريق الذين يُظهرون أضواء تحذير وامضة.","h2":"قانون Move Over في Florida يشمل شاحنات النفايات، وشاحنات المرافق، وشاحنات السحب، وعمال الطرق عندما يتوقفون وأضواء التحذير تومض، لذلك يجب أن تبتعد أو تخفف السرعة.","p":"صحيح. ابتعد عن شاحنة نفايات متوقفة أضواؤها تومض."},"ht":{"q":"Nan Florida, kiyès nan machin ki kanpe sa yo lwa Move Over la kouvri?","o":["Yon machin ki pake san limyè limen","Yon bis vil ki kanpe nan yon arè bis","Yon kamyonèt livrezon devan yon magazen","Yon kamyon fatra ki gen limyè avètisman l ap flache"],"h1":"Lwa a kouvri moun k ap travay sou wout la ki montre limyè avètisman k ap flache.","h2":"Lwa Move Over Florida a kouvri kamyon fatra, kamyon sèvis piblik, kamyon remòk ak ekip k ap travay sou wout la lè yo kanpe ak limyè avètisman k ap flache, kidonk ou dwe chanje liy oswa ralanti.","p":"Wi, se sa. Chanje liy pou yon kamyon fatra ki kanpe ak limyè k ap flache."},"ref":{"doc":"FL","page":65}},{"id":"right-of-way-021","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, a car is stopped on the shoulder with its hazard lights flashing. Does the Move Over law apply?","o":["No, it is only for police and ambulances","Yes, move over or slow down as you would for an emergency vehicle","Only at night","Only on toll roads"],"h1":"Florida widened the Move Over law to protect more people stopped by the road.","h2":"Florida's Move Over law also covers a disabled vehicle that is stopped and showing hazard lights or other warning signs, so you must move over or slow down.","p":"Right. Move over or slow down for a stopped car with hazard lights."},"es":{"q":"En Florida, un carro está parado en el acotamiento con las luces de emergencia encendidas. ¿Se aplica la ley Move Over?","o":["No, es solo para policías y ambulancias","Sí, cámbiese de carril o baje la velocidad como para un vehículo de emergencia","Solo de noche","Solo en carreteras de peaje"],"h1":"Florida amplió la ley Move Over para proteger a más personas paradas en la orilla.","h2":"La ley Move Over de Florida también cubre a un vehículo descompuesto que está parado y muestra luces de emergencia u otras señales de advertencia, así que usted debe cambiarse de carril o bajar la velocidad.","p":"Correcto. Cámbiese de carril o baje la velocidad por un carro parado con luces de emergencia."},"zh":{"q":"在 Florida，一辆车停在路肩上，开着双闪灯。Move Over 法适用吗？","o":["不适用，它只针对警车和救护车","适用，要像遇到急救车辆一样换道或减速","只在晚上适用","只在收费公路上适用"],"h1":"Florida 扩大了 Move Over 法，保护更多停在路边的人。","h2":"Florida 的 Move Over 法也保护停着并开着双闪灯或有其他警示的故障车，所以你必须换道或减速。","p":"对。遇到开着双闪灯停着的车，要换道或减速。"},"vi":{"q":"Ở Florida, một xe hơi đang dừng trên lề và bật đèn khẩn cấp nhấp nháy. Luật \"Move Over\" có áp dụng không?","o":["Không, luật chỉ dành cho cảnh sát và xe cứu thương","Có, hãy chuyển làn hoặc giảm tốc như với xe khẩn cấp","Chỉ vào ban đêm","Chỉ trên đường thu phí"],"h1":"Florida đã mở rộng luật \"Move Over\" để bảo vệ thêm nhiều người dừng bên đường.","h2":"Luật \"Move Over\" của Florida cũng áp dụng cho xe bị hỏng đang dừng và bật đèn khẩn cấp hoặc dấu hiệu cảnh báo khác, nên bạn phải chuyển làn hoặc giảm tốc.","p":"Đúng. Hãy chuyển làn hoặc giảm tốc khi có xe dừng bật đèn khẩn cấp."},"tl":{"q":"Sa Florida, may kotseng nakahinto sa shoulder na kumikislap ang hazard lights. Sakop ba ito ng Move Over law?","o":["Hindi, para lang ito sa pulis at ambulansiya","Oo, lumipat ng lane o bumagal gaya ng gagawin mo para sa emergency vehicle","Sa gabi lang","Sa toll road lang"],"h1":"Pinalawak ng Florida ang Move Over law para protektahan ang mas maraming taong nakahinto sa tabi ng daan.","h2":"Sakop din ng Move Over law ng Florida ang sirang sasakyan na nakahinto at nagpapakita ng hazard lights o iba pang babala, kaya dapat kang lumipat ng lane o bumagal.","p":"Tama. Lumipat ng lane o bumagal para sa nakahintong kotse na may hazard lights."},"ar":{"q":"في Florida، سيارة متوقفة على كتف الطريق وأضواء الخطر فيها تومض. هل ينطبق قانون Move Over؟","o":["لا، هو للشرطة وسيارات الإسعاف فقط","نعم، ابتعد أو خفف السرعة كما تفعل لمركبة طوارئ","فقط في الليل","فقط على الطرق التي فيها رسوم"],"h1":"Florida وسّعت قانون Move Over لتحمي عددًا أكبر من الناس المتوقفين بجانب الطريق.","h2":"قانون Move Over في Florida يشمل أيضًا المركبة المعطلة المتوقفة التي تُظهر أضواء الخطر أو علامات تحذير أخرى، لذلك يجب أن تبتعد أو تخفف السرعة.","p":"صحيح. ابتعد أو خفف السرعة لسيارة متوقفة أضواء الخطر فيها تعمل."},"ht":{"q":"Nan Florida, yon machin kanpe sou bò wout la ak limyè ijans li (flachè) k ap flache. Èske lwa Move Over la aplike?","o":["Non, se sèlman pou polis ak anbilans","Wi, chanje liy oswa ralanti menm jan ou ta fè pou yon machin ijans","Sèlman lannwit","Sèlman sou wout peyan"],"h1":"Florida te elaji lwa Move Over la pou pwoteje plis moun ki kanpe bò wout la.","h2":"Lwa Move Over Florida a kouvri tou yon machin ki an pàn epi ki kanpe ak limyè ijans oswa lòt siy avètisman, kidonk ou dwe chanje liy oswa ralanti.","p":"Wi, se sa. Chanje liy oswa ralanti pou yon machin ki kanpe ak limyè ijans li."},"ref":{"doc":"FL","page":65}},{"id":"right-of-way-022","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, on a two-way road, a school bus ahead is stopped with its stop arm out. You are coming from the other direction. What do you do?","o":["Slow down and pass with care","Keep going, because you are on the other side","Stop and stay stopped","Honk and pass"],"h1":"On a two-way road with no median, the rule is the same for both directions.","h2":"On a two-way road, traffic going both ways must stop for a school bus that shows its stop signal, so you stop even when coming from the other side.","p":"Right. On a two-way road, both directions stop for a stopped school bus."},"es":{"q":"En Florida, en una calle de doble sentido, un autobús escolar adelante está parado con el brazo de pare afuera. Usted viene en la dirección contraria. ¿Qué hace?","o":["Baja la velocidad y pasa con cuidado","Sigue, porque usted va del otro lado","Para y se queda parado","Toca la bocina y pasa"],"h1":"En una calle de doble sentido sin división, la regla es igual para las dos direcciones.","h2":"En una calle de doble sentido, el tráfico de las dos direcciones debe parar ante un autobús escolar que muestra su señal de pare, así que usted para aunque venga del otro lado.","p":"Correcto. En calle de doble sentido, las dos direcciones paran por el autobús escolar."},"zh":{"q":"在 Florida，在一条双向道路上，前面一辆校车停着，伸出了停车臂。你从对面方向开过来。你该怎么做？","o":["减速，小心地开过去","继续开，因为你在另一边","停车，并保持停着","按喇叭，然后开过去"],"h1":"在没有中间隔离带的双向道路上，两个方向的规则是一样的。","h2":"在双向道路上，两个方向的车都必须为亮出停车信号的校车停车，所以就算你从对面来，也要停车。","p":"对。在双向道路上，两个方向都要为停着的校车停车。"},"vi":{"q":"Ở Florida, trên đường hai chiều, xe buýt trường học phía trước đang dừng và giơ cần biển \"STOP\". Bạn đến từ hướng ngược lại. Bạn làm gì?","o":["Giảm tốc và chạy qua cẩn thận","Tiếp tục chạy, vì bạn ở phía bên kia","Dừng lại và giữ nguyên ở đó","Bấm còi và chạy qua"],"h1":"Trên đường hai chiều không có dải phân cách, quy tắc giống nhau cho cả hai hướng.","h2":"Trên đường hai chiều, xe đi cả hai hướng đều phải dừng khi xe buýt trường học bật tín hiệu dừng, nên bạn phải dừng dù đến từ phía bên kia.","p":"Đúng. Trên đường hai chiều, cả hai hướng đều dừng cho xe buýt trường học đang dừng."},"tl":{"q":"Sa Florida, sa daang two-way, may school bus sa unahan na nakahinto at nakalabas ang stop arm. Galing ka sa kabilang direksiyon. Ano ang gagawin mo?","o":["Bumagal at dumaan nang maingat","Magpatuloy, dahil nasa kabilang panig ka","Huminto at manatiling nakahinto","Bumusina at dumaan"],"h1":"Sa daang two-way na walang median, pareho ang patakaran sa dalawang direksiyon.","h2":"Sa daang two-way, dapat huminto ang trapiko sa dalawang direksiyon para sa school bus na nagpapakita ng stop signal, kaya hihinto ka kahit galing ka sa kabilang panig.","p":"Tama. Sa daang two-way, humihinto ang dalawang direksiyon para sa nakahintong school bus."},"ar":{"q":"في Florida، على طريق باتجاهين، حافلة مدرسية أمامك متوقفة وذراع التوقف فيها مفتوح. أنت قادم من الاتجاه الآخر. ماذا تفعل؟","o":["أخفف السرعة وأمر بحذر","أستمر، لأنني على الجانب الآخر","أتوقف وأبقى متوقفًا","أستعمل البوق وأمر"],"h1":"على طريق باتجاهين بدون فاصل في الوسط، القاعدة هي نفسها في الاتجاهين.","h2":"على طريق باتجاهين، يجب على السيارات في الاتجاهين أن تتوقف لحافلة مدرسية تُظهر إشارة التوقف، لذلك تتوقف حتى لو كنت قادمًا من الجانب الآخر.","p":"صحيح. على طريق باتجاهين، يتوقف الاتجاهان لحافلة مدرسية متوقفة."},"ht":{"q":"Nan Florida, sou yon wout de sans, gen yon bis lekòl devan ki kanpe ak bra \"STOP\" li louvri. W ap vini nan lòt direksyon an. Kisa ou fè?","o":["Ou ralanti epi ou pase avèk atansyon","Ou kontinye, paske ou sou lòt bò a","Ou kanpe epi ou rete kanpe","Ou klaksonnen epi ou pase"],"h1":"Sou yon wout de sans ki pa gen separasyon nan mitan, règ la se menm pou de direksyon yo.","h2":"Sou yon wout de sans, machin k ap ale nan de direksyon yo dwe kanpe pou yon bis lekòl ki montre siyal \"STOP\" li, kidonk ou kanpe menm si w ap vini nan lòt bò a.","p":"Wi, se sa. Sou yon wout de sans, de direksyon yo kanpe pou yon bis lekòl ki kanpe."},"ref":{"doc":"FL","page":89}},{"id":"right-of-way-023","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, a school bus is stopped across a raised concrete median, on the other side of a divided highway. Must you stop?","o":["No, you may keep going, with care","Yes, you must always stop","Only if children are on your side","Only if the bus honks"],"h1":"A raised barrier keeps the two directions apart.","h2":"On a divided highway with a raised median, you do not have to stop when the school bus is on the other side, but you should still watch for children.","p":"Right. With a raised median, the opposite side does not have to stop."},"es":{"q":"En Florida, un autobús escolar está parado del otro lado de una división de concreto elevada en una carretera dividida. ¿Debe usted parar?","o":["No, puede seguir con cuidado","Sí, siempre debe parar","Solo si hay niños de su lado","Solo si el autobús toca la bocina"],"h1":"Una división elevada separa las dos direcciones.","h2":"En una carretera dividida con una división elevada, usted no tiene que parar cuando el autobús escolar está del otro lado, pero igual debe estar atento a los niños.","p":"Correcto. Con división elevada, el lado contrario no tiene que parar."},"zh":{"q":"在 Florida，一辆校车停在一条分隔公路的另一边，中间有凸起的水泥隔离带。你必须停车吗？","o":["不用，你可以小心地继续开","要，你永远必须停车","只有你这边有小孩时才要","只有校车按喇叭时才要"],"h1":"凸起的隔离带把两个方向分开了。","h2":"在有凸起隔离带的分隔公路上，校车在另一边时你不用停车，但你还是要注意小孩。","p":"对。有凸起隔离带时，对面方向不用停车。"},"vi":{"q":"Ở Florida, một xe buýt trường học đang dừng ở phía bên kia của xa lộ có dải phân cách bằng bê tông nổi cao. Bạn có phải dừng không?","o":["Không, bạn có thể tiếp tục chạy, nhưng cẩn thận","Có, bạn luôn phải dừng","Chỉ khi có trẻ em ở phía bên bạn","Chỉ khi xe buýt bấm còi"],"h1":"Một rào chắn nổi cao tách hai hướng xe ra.","h2":"Trên xa lộ có dải phân cách nổi cao, bạn không phải dừng khi xe buýt trường học ở phía bên kia, nhưng bạn vẫn nên để ý trẻ em.","p":"Đúng. Có dải phân cách nổi cao thì phía bên kia không phải dừng."},"tl":{"q":"Sa Florida, may school bus na nakahinto sa kabila ng nakataas na konkretong median, sa kabilang panig ng divided highway. Dapat ka bang huminto?","o":["Hindi, puwede kang magpatuloy, nang maingat","Oo, dapat kang laging huminto","Kung may mga bata lang sa panig mo","Kung bumusina lang ang bus"],"h1":"Pinaghihiwalay ng nakataas na harang ang dalawang direksiyon.","h2":"Sa divided highway na may nakataas na median, hindi mo kailangang huminto kapag nasa kabilang panig ang school bus, pero dapat ka pa ring magbantay sa mga bata.","p":"Tama. Kapag may nakataas na median, hindi kailangang huminto ang kabilang panig."},"ar":{"q":"في Florida، حافلة مدرسية متوقفة على الجانب الآخر من طريق سريع مقسوم بفاصل إسمنتي مرتفع. هل يجب أن تتوقف؟","o":["لا، يمكنني أن أستمر بحذر","نعم، يجب أن أتوقف دائمًا","فقط إذا كان هناك أطفال على جانبي","فقط إذا استعملت الحافلة البوق"],"h1":"الحاجز المرتفع يفصل بين الاتجاهين.","h2":"على طريق سريع مقسوم بفاصل مرتفع، ليس عليك أن تتوقف عندما تكون الحافلة المدرسية على الجانب الآخر، لكن يجب أن تنتبه للأطفال.","p":"صحيح. مع فاصل مرتفع، ليس على الجانب المقابل أن يتوقف."},"ht":{"q":"Nan Florida, yon bis lekòl kanpe lòt bò yon separasyon an beton ki leve, sou lòt bò yon gran wout ki separe. Èske ou dwe kanpe?","o":["Non, ou ka kontinye, avèk atansyon","Wi, ou dwe toujou kanpe","Sèlman si gen timoun sou bò pa w la","Sèlman si bis la klaksonnen"],"h1":"Yon baryè ki leve kenbe de direksyon yo apa.","h2":"Sou yon gran wout ki separe ak yon separasyon ki leve, ou pa oblije kanpe lè bis lekòl la sou lòt bò a, men ou dwe toujou veye timoun yo.","p":"Wi, se sa. Lè gen yon separasyon ki leve, machin ki sou lòt bò a pa oblije kanpe."},"ref":{"doc":"FL","page":89}},{"id":"right-of-way-024","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, a highway has an unpaved grass median. How wide must it be so that traffic on the other side does not have to stop for a school bus?","o":["At least 2 feet","At least 10 feet","At least 20 feet","At least 5 feet"],"h1":"The number is small, about the length of a sofa.","h2":"Florida law says that if an unpaved median is at least 5 feet wide, traffic going the other way does not have to stop for a stopped school bus.","p":"Right. An unpaved median of at least 5 feet means the other side does not stop."},"es":{"q":"En Florida, una carretera tiene una división de césped sin pavimentar. ¿Qué ancho debe tener para que el tráfico del otro lado no tenga que parar por un autobús escolar?","o":["Por lo menos 2 pies","Por lo menos 10 pies","Por lo menos 20 pies","Por lo menos 5 pies"],"h1":"El número es pequeño, más o menos el largo de un sofá.","h2":"La ley de Florida dice que si una división sin pavimentar mide por lo menos 5 pies de ancho, el tráfico que va en la otra dirección no tiene que parar por un autobús escolar parado.","p":"Correcto. Con una división sin pavimentar de por lo menos 5 pies, el otro lado no para."},"zh":{"q":"在 Florida，一条公路中间有没铺路面的草地隔离带。它至少要多宽，对面方向的车才不用为校车停车？","o":["至少 2 英尺","至少 10 英尺","至少 20 英尺","至少 5 英尺"],"h1":"这个数字很小，大约是一张沙发的长度。","h2":"Florida 法律规定，如果没铺路面的隔离带至少有 5 英尺宽，对面方向的车就不用为停着的校车停车。","p":"对。没铺路面的隔离带至少 5 英尺宽，对面就不用停车。"},"vi":{"q":"Ở Florida, một xa lộ có dải phân cách bằng cỏ, không tráng nhựa. Dải đó phải rộng bao nhiêu để xe phía bên kia không phải dừng cho xe buýt trường học?","o":["Ít nhất 2 feet","Ít nhất 10 feet","Ít nhất 20 feet","Ít nhất 5 feet"],"h1":"Con số này nhỏ, khoảng bằng chiều dài một chiếc ghế sofa.","h2":"Luật Florida nói nếu dải phân cách không tráng nhựa rộng ít nhất 5 feet, xe đi hướng ngược lại không phải dừng cho xe buýt trường học đang dừng.","p":"Đúng. Dải phân cách không tráng nhựa rộng ít nhất 5 feet thì phía bên kia không phải dừng."},"tl":{"q":"Sa Florida, may median na damo at walang semento ang isang highway. Gaano ito dapat kalapad para hindi na kailangang huminto ng trapiko sa kabilang panig para sa school bus?","o":["Hindi bababa sa 2 feet","Hindi bababa sa 10 feet","Hindi bababa sa 20 feet","Hindi bababa sa 5 feet"],"h1":"Maliit ang numero, mga kasinghaba ng sofa.","h2":"Sinasabi ng batas ng Florida na kung ang median na walang semento ay hindi bababa sa 5 feet ang lapad, hindi kailangang huminto ng trapiko sa kabilang direksiyon para sa nakahintong school bus.","p":"Tama. Kapag ang median na walang semento ay hindi bababa sa 5 feet, hindi humihinto ang kabilang panig."},"ar":{"q":"في Florida، طريق سريع في وسطه فاصل من العشب غير مرصوف. كم يجب أن يكون عرضه حتى لا تتوقف السيارات على الجانب الآخر للحافلة المدرسية؟","o":["2 قدم على الأقل","10 أقدام على الأقل","20 قدمًا على الأقل","5 أقدام على الأقل"],"h1":"الرقم صغير، تقريبًا طول أريكة.","h2":"يقول قانون Florida إنه إذا كان عرض الفاصل غير المرصوف 5 أقدام على الأقل، فليس على السيارات في الاتجاه الآخر أن تتوقف لحافلة مدرسية متوقفة.","p":"صحيح. فاصل غير مرصوف عرضه 5 أقدام على الأقل يعني أن الجانب الآخر لا يتوقف."},"ht":{"q":"Nan Florida, yon gran wout gen yon separasyon an zèb, ki pa asfalte, nan mitan l. Ki lajè separasyon an dwe genyen pou machin ki sou lòt bò a pa oblije kanpe pou yon bis lekòl?","o":["Omwen 2 pye","Omwen 10 pye","Omwen 20 pye","Omwen 5 pye"],"h1":"Chif la piti, apeprè longè yon kanape.","h2":"Lwa Florida di si yon separasyon ki pa asfalte gen omwen 5 pye lajè, machin k ap ale nan lòt direksyon an pa oblije kanpe pou yon bis lekòl ki kanpe.","p":"Wi, se sa. Yon separasyon ki pa asfalte ki gen omwen 5 pye vle di lòt bò a pa kanpe."},"ref":{"doc":"FL","page":89}},{"id":"right-of-way-025","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, a road has a paved center turn lane. A school bus is stopped on the other side with its stop arm out. What do you do?","o":["Keep going, because a turn lane divides the road","Stop, because a paved turn lane does not count as a divider","Pass using the turn lane","Slow down only"],"h1":"Only a raised barrier or a wide unpaved median lets the other side keep going.","h2":"A paved center turn lane is not a raised barrier or an unpaved median, so traffic in both directions must stop for the school bus.","p":"Right. A paved turn lane does not excuse you. Stop for the bus."},"es":{"q":"En Florida, una calle tiene un carril central pavimentado para doblar. Un autobús escolar está parado del otro lado con el brazo de pare afuera. ¿Qué hace?","o":["Sigue, porque el carril para doblar divide la calle","Para, porque un carril pavimentado para doblar no cuenta como división","Pasa usando el carril para doblar","Solo baja la velocidad"],"h1":"Solo una división elevada o una división ancha sin pavimentar permite que el otro lado siga.","h2":"Un carril central pavimentado para doblar no es una división elevada ni una división sin pavimentar, así que el tráfico de las dos direcciones debe parar por el autobús escolar.","p":"Correcto. Un carril para doblar no lo exime. Pare por el autobús."},"zh":{"q":"在 Florida，一条路中间有铺了路面的中央转弯车道。一辆校车停在另一边，伸出了停车臂。你该怎么做？","o":["继续开，因为转弯车道把路分开了","停车，因为铺了路面的转弯车道不算隔离带","从转弯车道开过去","只要减速就行"],"h1":"只有凸起的隔离带或很宽的没铺路面的隔离带，才能让对面继续开。","h2":"铺了路面的中央转弯车道不是凸起的隔离带，也不是没铺路面的隔离带，所以两个方向的车都必须为校车停车。","p":"对。铺了路面的转弯车道不能当理由。要为校车停车。"},"vi":{"q":"Ở Florida, một con đường có làn rẽ ở giữa được tráng nhựa. Một xe buýt trường học đang dừng ở phía bên kia và giơ cần biển \"STOP\". Bạn làm gì?","o":["Tiếp tục chạy, vì làn rẽ chia đôi con đường","Dừng lại, vì làn rẽ tráng nhựa không được tính là dải phân cách","Chạy qua bằng làn rẽ","Chỉ cần giảm tốc"],"h1":"Chỉ có rào chắn nổi cao hoặc dải phân cách không tráng nhựa đủ rộng mới cho phía bên kia tiếp tục chạy.","h2":"Làn rẽ ở giữa được tráng nhựa không phải là rào chắn nổi cao hay dải phân cách không tráng nhựa, nên xe cả hai hướng phải dừng cho xe buýt trường học.","p":"Đúng. Làn rẽ tráng nhựa không miễn cho bạn. Hãy dừng cho xe buýt."},"tl":{"q":"Sa Florida, may sementadong center turn lane ang daan. May school bus na nakahinto sa kabilang panig na nakalabas ang stop arm. Ano ang gagawin mo?","o":["Magpatuloy, dahil hinahati ng turn lane ang daan","Huminto, dahil hindi binibilang na harang ang sementadong turn lane","Dumaan gamit ang turn lane","Bumagal lang"],"h1":"Ang nakataas na harang lang o malapad na median na walang semento ang nagpapahintulot sa kabilang panig na magpatuloy.","h2":"Ang sementadong center turn lane ay hindi nakataas na harang o median na walang semento, kaya dapat huminto ang trapiko sa dalawang direksiyon para sa school bus.","p":"Tama. Hindi dahilan ang sementadong turn lane. Huminto para sa bus."},"ar":{"q":"في Florida، في وسط الطريق مسار مرصوف للانعطاف. حافلة مدرسية متوقفة على الجانب الآخر وذراع التوقف فيها مفتوح. ماذا تفعل؟","o":["أستمر، لأن مسار الانعطاف يقسم الطريق","أتوقف، لأن مسار الانعطاف المرصوف لا يُعتبر فاصلًا","أتجاوز الحافلة من مسار الانعطاف","أخفف السرعة فقط"],"h1":"فقط الحاجز المرتفع أو الفاصل العريض غير المرصوف يسمح للجانب الآخر بأن يستمر.","h2":"مسار الانعطاف المرصوف في الوسط ليس حاجزًا مرتفعًا ولا فاصلًا غير مرصوف، لذلك يجب على السيارات في الاتجاهين أن تتوقف للحافلة المدرسية.","p":"صحيح. مسار الانعطاف المرصوف لا يعفيك. توقف للحافلة."},"ht":{"q":"Nan Florida, yon wout gen yon liy pou vire nan mitan ki asfalte. Yon bis lekòl kanpe sou lòt bò a ak bra \"STOP\" li louvri. Kisa ou fè?","o":["Ou kontinye, paske liy pou vire a separe wout la","Ou kanpe, paske yon liy pou vire ki asfalte pa konte kòm separasyon","Ou pase nan liy pou vire a","Ou ralanti sèlman"],"h1":"Se sèlman yon baryè ki leve oswa yon separasyon laj ki pa asfalte ki kite lòt bò a kontinye.","h2":"Yon liy pou vire nan mitan ki asfalte pa yon baryè ki leve ni yon separasyon ki pa asfalte, kidonk machin nan de direksyon yo dwe kanpe pou bis lekòl la.","p":"Wi, se sa. Yon liy pou vire ki asfalte pa egzante ou. Kanpe pou bis la."},"ref":{"doc":"FL","page":89}},{"id":"right-of-way-026","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, you are driving behind a school bus on a divided highway. The bus stops and shows its stop arm. What do you do?","o":["Pass on the left","Keep going, because the highway is divided","Stop behind the bus","Pass on the right shoulder"],"h1":"The median only helps traffic on the other side.","h2":"Traffic going the same way as a stopped school bus must always stop, even on a divided highway.","p":"Right. If you are behind a stopped school bus, you always stop."},"es":{"q":"En Florida, usted maneja detrás de un autobús escolar en una carretera dividida. El autobús para y saca el brazo de pare. ¿Qué hace?","o":["Lo rebasa por la izquierda","Sigue, porque la carretera está dividida","Para detrás del autobús","Lo rebasa por el acotamiento derecho"],"h1":"La división solo ayuda al tráfico del otro lado.","h2":"El tráfico que va en la misma dirección que un autobús escolar parado siempre debe parar, aunque la carretera esté dividida.","p":"Correcto. Si va detrás de un autobús escolar parado, siempre para."},"zh":{"q":"在 Florida，你在一条分隔公路上跟在一辆校车后面。校车停下，伸出了停车臂。你该怎么做？","o":["从左边超过去","继续开，因为公路是分隔的","在校车后面停车","从右边路肩超过去"],"h1":"隔离带只对另一边的车有用。","h2":"和停着的校车同方向行驶的车永远必须停车，就算在分隔公路上也一样。","p":"对。如果你在停着的校车后面，一定要停车。"},"vi":{"q":"Ở Florida, bạn đang chạy sau một xe buýt trường học trên xa lộ có dải phân cách. Xe buýt dừng lại và giơ cần biển \"STOP\". Bạn làm gì?","o":["Vượt bên trái","Tiếp tục chạy, vì xa lộ có dải phân cách","Dừng lại phía sau xe buýt","Vượt bằng lề bên phải"],"h1":"Dải phân cách chỉ giúp xe ở phía bên kia.","h2":"Xe đi cùng hướng với xe buýt trường học đang dừng luôn phải dừng, kể cả trên xa lộ có dải phân cách.","p":"Đúng. Nếu bạn ở sau xe buýt trường học đang dừng, bạn luôn phải dừng."},"tl":{"q":"Sa Florida, nasa likod ka ng school bus sa divided highway. Huminto ang bus at inilabas ang stop arm. Ano ang gagawin mo?","o":["Lumampas sa kaliwa","Magpatuloy, dahil divided ang highway","Huminto sa likod ng bus","Lumampas sa kanang shoulder"],"h1":"Ang median ay tumutulong lang sa trapiko sa kabilang panig.","h2":"Ang trapikong papunta sa parehong direksiyon ng nakahintong school bus ay dapat laging huminto, kahit sa divided highway.","p":"Tama. Kung nasa likod ka ng nakahintong school bus, laging huminto."},"ar":{"q":"في Florida، تقود خلف حافلة مدرسية على طريق سريع مقسوم. توقفت الحافلة وفتحت ذراع التوقف. ماذا تفعل؟","o":["أتجاوزها من اليسار","أستمر، لأن الطريق السريع مقسوم","أتوقف خلف الحافلة","أتجاوزها من كتف الطريق الأيمن"],"h1":"الفاصل في الوسط يساعد فقط السيارات على الجانب الآخر.","h2":"السيارات التي تسير في نفس اتجاه الحافلة المدرسية المتوقفة يجب أن تتوقف دائمًا، حتى على طريق سريع مقسوم.","p":"صحيح. إذا كنت خلف حافلة مدرسية متوقفة، تتوقف دائمًا."},"ht":{"q":"Nan Florida, w ap kondi dèyè yon bis lekòl sou yon gran wout ki separe. Bis la kanpe epi li louvri bra \"STOP\" li. Kisa ou fè?","o":["Ou pase sou bò gòch","Ou kontinye, paske gran wout la separe","Ou kanpe dèyè bis la","Ou pase sou bò wout la adwat"],"h1":"Separasyon an ede sèlman machin ki sou lòt bò a.","h2":"Machin k ap ale nan menm direksyon ak yon bis lekòl ki kanpe dwe toujou kanpe, menm sou yon gran wout ki separe.","p":"Wi, se sa. Si ou dèyè yon bis lekòl ki kanpe, ou toujou kanpe."},"ref":{"doc":"FL","page":89}},{"id":"right-of-way-027","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, you stopped for a school bus. When may you start driving again?","o":["When the stop arm is pulled back and the children are clear","As soon as the door closes","After you count to ten","When the driver waves at you"],"h1":"Watch the bus signal and the children, not a timer.","h2":"You must stay stopped until the bus pulls back its stop signal and the children are out of the road.","p":"Right. Wait until the stop arm is back in and the children are clear."},"es":{"q":"En Florida, usted paró por un autobús escolar. ¿Cuándo puede volver a manejar?","o":["Cuando el brazo de pare se recoge y los niños están fuera del camino","Apenas se cierra la puerta","Después de contar hasta diez","Cuando el chofer le hace una seña"],"h1":"Fíjese en la señal del autobús y en los niños, no en el tiempo.","h2":"Usted debe quedarse parado hasta que el autobús recoja su señal de pare y los niños estén fuera de la calle.","p":"Correcto. Espere a que se recoja el brazo de pare y los niños estén a salvo."},"zh":{"q":"在 Florida，你为校车停了车。什么时候可以再开车？","o":["停车臂收回，而且小孩都离开了路面","车门一关就可以","数到十以后","司机向你挥手的时候"],"h1":"看校车的信号和小孩，不是看时间。","h2":"你必须一直停着，直到校车收回停车信号，而且小孩都离开了路面。","p":"对。等停车臂收回、小孩都离开了再走。"},"vi":{"q":"Ở Florida, bạn đã dừng cho xe buýt trường học. Khi nào bạn được chạy tiếp?","o":["Khi cần biển \"STOP\" đã thu lại và trẻ em đã ra khỏi đường","Ngay khi cửa xe buýt đóng lại","Sau khi bạn đếm đến mười","Khi tài xế xe buýt vẫy tay với bạn"],"h1":"Hãy nhìn tín hiệu của xe buýt và trẻ em, không phải đếm giờ.","h2":"Bạn phải dừng cho đến khi xe buýt thu tín hiệu dừng lại và trẻ em đã ra khỏi đường.","p":"Đúng. Hãy chờ đến khi cần biển \"STOP\" thu lại và trẻ em đã ra khỏi đường."},"tl":{"q":"Sa Florida, huminto ka para sa school bus. Kailan ka puwedeng umandar ulit?","o":["Kapag naibalik na ang stop arm at wala na ang mga bata sa daan","Pagsara pa lang ng pinto","Pagkatapos mong magbilang hanggang sampu","Kapag kinawayan ka ng drayber"],"h1":"Bantayan ang signal ng bus at ang mga bata, hindi ang orasan.","h2":"Dapat kang manatiling nakahinto hanggang maibalik ng bus ang stop signal nito at wala na ang mga bata sa daan.","p":"Tama. Maghintay hanggang maibalik ang stop arm at wala na ang mga bata sa daan."},"ar":{"q":"في Florida، توقفت لحافلة مدرسية. متى يمكنك أن تبدأ القيادة مرة أخرى؟","o":["عندما يُسحب ذراع التوقف ويبتعد الأطفال عن الطريق","مباشرة عندما يُغلق الباب","بعد أن أعدّ إلى عشرة","عندما يلوّح لي السائق"],"h1":"راقب إشارة الحافلة والأطفال، وليس الوقت.","h2":"يجب أن تبقى متوقفًا حتى تسحب الحافلة إشارة التوقف ويخرج الأطفال من الطريق.","p":"صحيح. انتظر حتى يرجع ذراع التوقف ويبتعد الأطفال."},"ht":{"q":"Nan Florida, ou te kanpe pou yon bis lekòl. Kilè ou ka kòmanse kondi ankò?","o":["Lè bra \"STOP\" la fèmen epi timoun yo fin sòti nan wout la","Depi pòt la fèmen","Apre ou fin konte jiska dis","Lè chofè a fè ou siy ak men l"],"h1":"Gade siyal bis la ak timoun yo, pa yon revèy.","h2":"Ou dwe rete kanpe jiskaske bis la fèmen siyal \"STOP\" li epi timoun yo fin sòti nan wout la.","p":"Wi, se sa. Tann bra \"STOP\" la fèmen epi timoun yo fin sòti nan wout la."},"ref":{"doc":"FL","page":89}},{"id":"right-of-way-028","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, the lights are flashing at a railroad crossing. Where must you stop?","o":["Right on the tracks","Between 15 and 50 feet from the nearest rail","More than 100 feet away","Within 5 feet of the nearest rail"],"h1":"You need a safe gap from the train, but not so far that you block the road behind you.","h2":"Florida law says you must stop no closer than 15 feet and no farther than 50 feet from the nearest rail when a train is coming.","p":"Right. Stop between 15 and 50 feet from the nearest rail."},"es":{"q":"En Florida, las luces están intermitentes en un cruce de tren. ¿Dónde debe parar?","o":["Encima de las vías","Entre 15 y 50 pies del riel más cercano","A más de 100 pies","A menos de 5 pies del riel más cercano"],"h1":"Necesita una distancia segura del tren, pero no tan lejos que bloquee la calle detrás de usted.","h2":"La ley de Florida dice que usted debe parar a no menos de 15 pies y no más de 50 pies del riel más cercano cuando viene un tren.","p":"Correcto. Pare entre 15 y 50 pies del riel más cercano."},"zh":{"q":"在 Florida，铁路道口的灯在闪。你必须在哪里停车？","o":["就停在铁轨上","离最近的铁轨 15 到 50 英尺之间","超过 100 英尺远","离最近的铁轨 5 英尺以内"],"h1":"你需要和火车保持安全距离，但也不能太远，挡住后面的路。","h2":"Florida 法律规定，有火车开来时，你必须停在离最近的铁轨不少于 15 英尺、不超过 50 英尺的地方。","p":"对。停在离最近的铁轨 15 到 50 英尺之间。"},"vi":{"q":"Ở Florida, đèn đang nháy tại chỗ giao nhau với đường sắt. Bạn phải dừng ở đâu?","o":["Ngay trên đường ray","Cách thanh ray gần nhất từ 15 đến 50 feet","Cách xa hơn 100 feet","Trong vòng 5 feet từ thanh ray gần nhất"],"h1":"Bạn cần khoảng cách an toàn với tàu hỏa, nhưng không quá xa để chắn đường phía sau.","h2":"Luật Florida nói khi có tàu đang đến, bạn phải dừng không gần hơn 15 feet và không xa hơn 50 feet từ thanh ray gần nhất.","p":"Đúng. Hãy dừng cách thanh ray gần nhất từ 15 đến 50 feet."},"tl":{"q":"Sa Florida, kumikislap ang mga ilaw sa railroad crossing. Saan ka dapat huminto?","o":["Mismo sa ibabaw ng riles","Sa pagitan ng 15 at 50 feet mula sa pinakamalapit na riles","Higit sa 100 feet ang layo","Sa loob ng 5 feet mula sa pinakamalapit na riles"],"h1":"Kailangan mo ng ligtas na layo mula sa tren, pero hindi gaanong malayo na mahaharangan mo ang daan sa likod mo.","h2":"Sinasabi ng batas ng Florida na kapag may paparating na tren, dapat kang huminto nang hindi lalapit sa 15 feet at hindi lalayo sa 50 feet mula sa pinakamalapit na riles.","p":"Tama. Huminto sa pagitan ng 15 at 50 feet mula sa pinakamalapit na riles."},"ar":{"q":"في Florida، الأضواء تومض عند تقاطع سكة حديد. أين يجب أن تتوقف؟","o":["على السكة نفسها","على مسافة بين 15 و50 قدمًا من أقرب قضيب","على مسافة أكثر من 100 قدم","على مسافة أقل من 5 أقدام من أقرب قضيب"],"h1":"تحتاج إلى مسافة آمنة من القطار، لكن ليس بعيدًا جدًا حتى لا تسد الطريق على من خلفك.","h2":"يقول قانون Florida إنه عندما يأتي قطار، يجب أن تتوقف على مسافة لا تقل عن 15 قدمًا ولا تزيد على 50 قدمًا من أقرب قضيب.","p":"صحيح. توقف على مسافة بين 15 و50 قدمًا من أقرب قضيب."},"ht":{"q":"Nan Florida, limyè yo ap flache nan yon kwazman tren. Ki kote ou dwe kanpe?","o":["Dirèkteman sou ray yo","Ant 15 ak 50 pye de ray ki pi pre a","Plis pase 100 pye lwen","Mwens pase 5 pye de ray ki pi pre a"],"h1":"Ou bezwen yon espas ki san danje ant ou ak tren an, men pa twò lwen pou ou pa bloke wout la dèyè ou.","h2":"Lwa Florida di lè yon tren ap vini, ou dwe kanpe pa pi pre pase 15 pye epi pa pi lwen pase 50 pye de ray ki pi pre a.","p":"Wi, se sa. Kanpe ant 15 ak 50 pye de ray ki pi pre a."},"ref":{"doc":"FL","page":56}},{"id":"right-of-way-029","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, the gates at a railroad crossing are down, but you do not see a train. What do you do?","o":["Drive around the gates carefully","Honk and cross slowly","Back up and look for another way, then cross","Wait until the gates go up and the lights stop"],"h1":"Trains can be closer and faster than they look.","h2":"You must never drive around lowered railroad gates, so you wait until the gates are all the way up and the lights stop flashing.","p":"Right. Never go around railroad gates. Wait until they go up."},"es":{"q":"En Florida, las barreras de un cruce de tren están abajo, pero usted no ve ningún tren. ¿Qué hace?","o":["Pasa alrededor de las barreras con cuidado","Toca la bocina y cruza despacio","Da reversa, busca otro camino y cruza","Espera hasta que suban las barreras y se apaguen las luces"],"h1":"Los trenes pueden estar más cerca y ser más rápidos de lo que parece.","h2":"Usted nunca debe pasar alrededor de las barreras bajas del tren, así que espera hasta que las barreras suban por completo y las luces dejen de parpadear.","p":"Correcto. Nunca pase alrededor de las barreras del tren. Espere a que suban."},"zh":{"q":"在 Florida，铁路道口的栏杆放下来了，但你没看到火车。你该怎么做？","o":["小心地绕过栏杆","按喇叭，慢慢开过去","倒车，找另一条路，然后过去","等栏杆升起、灯不再闪"],"h1":"火车可能比看起来更近、更快。","h2":"你永远不能绕过放下的铁路栏杆，所以要等栏杆完全升起、灯不再闪。","p":"对。永远不要绕过铁路栏杆。等它升起来。"},"vi":{"q":"Ở Florida, thanh chắn ở chỗ giao nhau với đường sắt đã hạ xuống, nhưng bạn không thấy tàu. Bạn làm gì?","o":["Lái vòng qua thanh chắn một cách cẩn thận","Bấm còi và chạy qua chậm","Lùi xe và tìm đường khác, rồi chạy qua","Chờ đến khi thanh chắn nâng lên và đèn ngừng nháy"],"h1":"Tàu có thể ở gần hơn và chạy nhanh hơn bạn nghĩ.","h2":"Bạn không bao giờ được lái vòng qua thanh chắn đường sắt đã hạ, nên bạn chờ đến khi thanh chắn nâng lên hết và đèn ngừng nháy.","p":"Đúng. Không bao giờ lái vòng qua thanh chắn đường sắt. Hãy chờ đến khi nó nâng lên."},"tl":{"q":"Sa Florida, nakababa ang mga harang sa railroad crossing, pero wala kang nakikitang tren. Ano ang gagawin mo?","o":["Maingat na umikot sa mga harang","Bumusina at dahan-dahang tumawid","Umatras at maghanap ng ibang daan, saka tumawid","Maghintay hanggang tumaas ang mga harang at tumigil ang mga ilaw"],"h1":"Maaaring mas malapit at mas mabilis ang tren kaysa sa tingin mo.","h2":"Hindi ka dapat kailanman umikot sa nakababang harang ng riles, kaya maghihintay ka hanggang tuluyang tumaas ang mga harang at tumigil sa pagkislap ang mga ilaw.","p":"Tama. Huwag kailanman umikot sa harang ng riles. Maghintay hanggang tumaas ito."},"ar":{"q":"في Florida، الحواجز عند تقاطع سكة الحديد نازلة، لكنك لا ترى قطارًا. ماذا تفعل؟","o":["ألتف حول الحواجز بحذر","أستعمل البوق وأعبر ببطء","أرجع إلى الخلف وأبحث عن طريق آخر، ثم أعبر","أنتظر حتى ترتفع الحواجز وتتوقف الأضواء"],"h1":"القطار قد يكون أقرب وأسرع مما يبدو.","h2":"لا يجوز أبدًا أن تلتف حول حواجز سكة الحديد النازلة، لذلك تنتظر حتى ترتفع الحواجز كليًا وتتوقف الأضواء عن الوميض.","p":"صحيح. لا تلتف أبدًا حول حواجز سكة الحديد. انتظر حتى ترتفع."},"ht":{"q":"Nan Florida, baryè kwazman tren an desann, men ou pa wè okenn tren. Kisa ou fè?","o":["Ou fè yon ti detou bò baryè yo avèk atansyon","Ou klaksonnen epi ou travèse dousman","Ou fè bak pou chèche yon lòt chemen, apre sa ou travèse","Ou tann baryè yo leve epi limyè yo sispann flache"],"h1":"Yon tren ka pi pre epi pi rapid pase sa ou kwè.","h2":"Ou pa dwe janm fè detou bò baryè tren ki desann, kidonk ou tann jiskaske baryè yo fin leve nèt epi limyè yo sispann flache.","p":"Wi, se sa. Pa janm fè detou bò baryè tren yo. Tann yo leve."},"ref":{"doc":"FL","page":56}},{"id":"right-of-way-030","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, traffic is backed up past a railroad crossing. When may you start across the tracks?","o":["When the car in front of you moves","Right away, if no train is in sight","Only when there is room for your whole car on the other side","When the driver behind you honks"],"h1":"Think about where your car will be if traffic stops again.","h2":"You may start across the tracks only when there is room for your whole vehicle on the other side, so you never get stuck on the rails.","p":"Right. Do not cross until your whole car fits on the other side."},"es":{"q":"En Florida, el tráfico está detenido más allá de un cruce de tren. ¿Cuándo puede empezar a cruzar las vías?","o":["Cuando avance el carro de adelante","De inmediato, si no se ve ningún tren","Solo cuando haya espacio para todo su carro del otro lado","Cuando el conductor de atrás toque la bocina"],"h1":"Piense dónde quedará su carro si el tráfico se detiene otra vez.","h2":"Usted puede empezar a cruzar las vías solo cuando haya espacio para todo su vehículo del otro lado, para nunca quedar atrapado sobre los rieles.","p":"Correcto. No cruce hasta que todo su carro quepa del otro lado."},"zh":{"q":"在 Florida，车流一直排到铁路道口的另一边。你什么时候可以开始过铁轨？","o":["前面的车一动就可以","马上，只要看不到火车","只有另一边有足够的空间放下你整辆车时","后面的司机按喇叭的时候"],"h1":"想一想，如果车流又停下来，你的车会在哪里。","h2":"只有另一边有足够的空间放下你整辆车时，你才可以开始过铁轨，这样你就永远不会被困在铁轨上。","p":"对。另一边放不下你整辆车时，不要过铁轨。"},"vi":{"q":"Ở Florida, xe đang kẹt kéo dài qua chỗ giao nhau với đường sắt. Khi nào bạn được bắt đầu chạy qua đường ray?","o":["Khi xe phía trước bạn chạy","Ngay lập tức, nếu không thấy tàu","Chỉ khi có đủ chỗ cho cả chiếc xe của bạn ở phía bên kia","Khi người lái phía sau bấm còi"],"h1":"Hãy nghĩ xem xe của bạn sẽ ở đâu nếu dòng xe lại dừng.","h2":"Bạn chỉ được bắt đầu chạy qua đường ray khi có đủ chỗ cho cả chiếc xe ở phía bên kia, để bạn không bao giờ bị kẹt trên đường ray.","p":"Đúng. Đừng chạy qua cho đến khi cả chiếc xe vừa chỗ ở phía bên kia."},"tl":{"q":"Sa Florida, nakapila ang trapiko hanggang lampas sa railroad crossing. Kailan ka puwedeng magsimulang tumawid sa riles?","o":["Kapag umandar ang kotse sa harap mo","Agad, kung walang tren na nakikita","Kapag may lugar lang para sa buong kotse mo sa kabilang panig","Kapag bumusina ang drayber sa likod mo"],"h1":"Isipin kung nasaan ang kotse mo kung huminto ulit ang trapiko.","h2":"Puwede kang magsimulang tumawid sa riles kapag may lugar lang para sa buong sasakyan mo sa kabilang panig, para hindi ka maipit sa ibabaw ng riles.","p":"Tama. Huwag tumawid hanggang kasya ang buong kotse mo sa kabilang panig."},"ar":{"q":"في Florida، الطريق مزدحم وطابور السيارات يصل إلى ما بعد تقاطع سكة الحديد. متى يمكنك أن تبدأ عبور السكة؟","o":["عندما تتحرك السيارة التي أمامي","فورًا، إذا لم أرَ قطارًا","فقط عندما يوجد مكان لسيارتي كلها على الجانب الآخر","عندما يستعمل السائق الذي خلفي البوق"],"h1":"فكّر أين ستكون سيارتك إذا توقفت السيارات مرة أخرى.","h2":"يمكنك أن تبدأ عبور السكة فقط عندما يوجد مكان لمركبتك كلها على الجانب الآخر، حتى لا تعلق أبدًا على القضبان.","p":"صحيح. لا تعبر حتى تجد مكانًا لسيارتك كلها على الجانب الآخر."},"ht":{"q":"Nan Florida, machin yo kanpe an liy rive pi lwen pase yon kwazman tren. Kilè ou ka kòmanse travèse ray yo?","o":["Lè machin ki devan ou a avanse","Touswit, si ou pa wè okenn tren","Sèlman lè gen plas pou tout machin ou sou lòt bò a","Lè chofè ki dèyè ou a klaksonnen"],"h1":"Panse ak ki kote machin ou ap ye si sikilasyon an kanpe ankò.","h2":"Ou ka kòmanse travèse ray yo sèlman lè gen plas pou tout machin ou sou lòt bò a, pou ou pa janm rete bloke sou ray yo.","p":"Wi, se sa. Pa travèse jiskaske tout machin ou ka antre sou lòt bò a."},"ref":{"doc":"FL","page":57}},{"id":"right-of-way-031","scope":"US","cat":"right-of-way","sign":{"shape":"crossbuck","text":"RAILROAD CROSSING"},"c":0,"en":{"q":"What does this white X-shaped sign mean?","o":["A railroad crossing. Yield to trains.","An intersection with four roads","A hospital is nearby","No parking in this area"],"h1":"This sign stands where a road meets something that cannot stop or swerve to miss you.","h2":"The white X-shaped sign, called a crossbuck, marks a railroad crossing, and you must yield to any train.","p":"Right. The crossbuck marks a railroad crossing. Yield to trains."},"es":{"q":"¿Qué significa esta señal blanca en forma de X?","o":["Un cruce de tren. Ceda el paso a los trenes.","Una intersección de cuatro calles","Hay un hospital cerca","No se permite estacionar en esta área"],"h1":"Esta señal está donde una calle se cruza con algo que no puede parar ni desviarse para no chocar con usted.","h2":"La señal blanca en forma de X, llamada crossbuck, marca un cruce de tren, y usted debe ceder el paso a cualquier tren.","p":"Correcto. La señal en X marca un cruce de tren. Ceda el paso a los trenes."},"zh":{"q":"这个白色 X 形的标志是什么意思？","o":["铁路道口。要给火车让行。","一个有四条路的路口","附近有医院","这里禁止停车"],"h1":"这个标志立在道路和一种无法停下、也无法躲开你的东西交叉的地方。","h2":"这个白色 X 形的标志叫做铁路交叉标志，它标出铁路道口，你必须给任何火车让行。","p":"对。白色 X 形标志表示铁路道口。要给火车让行。"},"vi":{"q":"Biển báo màu trắng hình chữ X này có nghĩa là gì?","o":["Chỗ giao nhau với đường sắt. Nhường đường cho tàu.","Giao lộ có bốn con đường","Gần đây có bệnh viện","Không được đậu xe ở khu vực này"],"h1":"Biển này đặt ở nơi con đường gặp một thứ không thể dừng lại hay tránh bạn.","h2":"Biển màu trắng hình chữ X, gọi là biển \"crossbuck\", đánh dấu chỗ giao nhau với đường sắt, và bạn phải nhường đường cho mọi đoàn tàu.","p":"Đúng. Biển \"crossbuck\" đánh dấu chỗ giao nhau với đường sắt. Hãy nhường tàu."},"tl":{"q":"Ano ang ibig sabihin ng puting karatulang hugis X na ito?","o":["Railroad crossing (tawiran ng tren). Magbigay-daan sa tren.","Intersection ng apat na daan","May ospital sa malapit","Bawal pumarada sa lugar na ito"],"h1":"Nakatayo ang karatulang ito kung saan nagtatagpo ang daan at isang bagay na hindi kayang huminto o umiwas sa iyo.","h2":"Ang puting karatulang hugis X, na tinatawag na crossbuck, ay nagmamarka ng railroad crossing, at dapat kang magbigay-daan sa anumang tren.","p":"Tama. Ang crossbuck ay nagmamarka ng railroad crossing. Magbigay-daan sa tren."},"ar":{"q":"ماذا تعني هذه العلامة البيضاء التي على شكل حرف X؟","o":["تقاطع سكة حديد. أعطِ حق المرور للقطارات.","تقاطع فيه أربعة طرق","يوجد مستشفى قريب","ممنوع الوقوف في هذه المنطقة"],"h1":"هذه العلامة موجودة حيث يلتقي الطريق بشيء لا يستطيع أن يتوقف أو يبتعد عنك.","h2":"العلامة البيضاء التي على شكل حرف X، واسمها crossbuck، تدل على تقاطع سكة حديد، ويجب أن تعطي حق المرور لأي قطار.","p":"صحيح. علامة crossbuck تدل على تقاطع سكة حديد. أعطِ حق المرور للقطارات."},"ht":{"q":"Kisa siy blan sa a ki gen fòm yon X vle di?","o":["Yon kwazman tren. Kite tren yo pase anvan.","Yon kafou ki gen kat wout","Gen yon lopital tou pre","Pa gen pakin nan zòn sa a"],"h1":"Siy sa a kanpe kote yon wout kwaze yon bagay ki pa ka kanpe ni vire pou evite ou.","h2":"Siy blan ki gen fòm yon X la, ki rele \"crossbuck\", make yon kwazman tren, epi ou dwe kite nenpòt tren pase anvan.","p":"Wi, se sa. Siy \"crossbuck\" la make yon kwazman tren. Kite tren yo pase anvan."},"ref":{"doc":"FL","page":56}},{"id":"right-of-way-032","scope":"US","cat":"right-of-way","sign":{"shape":"rr-advance","text":"RR"},"c":2,"en":{"q":"What does this round yellow sign with an X and the letters RR mean?","o":["A rest area is ahead","A road repair zone is ahead","A railroad crossing is ahead","You must turn right"],"h1":"This sign gives you a warning before you reach something.","h2":"The round yellow sign with an X and RR warns you that a railroad crossing is ahead, so you slow down, look, and listen.","p":"Right. The round yellow RR sign means a railroad crossing is ahead."},"es":{"q":"¿Qué significa esta señal amarilla redonda con una X y las letras RR?","o":["Hay un área de descanso adelante","Hay una zona de reparación de la calle adelante","Hay un cruce de tren adelante","Debe doblar a la derecha"],"h1":"Esta señal le avisa antes de que usted llegue a algo.","h2":"La señal amarilla redonda con una X y RR le avisa que hay un cruce de tren adelante, así que baje la velocidad, mire y escuche.","p":"Correcto. La señal amarilla redonda con RR significa cruce de tren adelante."},"zh":{"q":"这个圆形黄色、上面有一个 X 和字母 \"RR\" 的标志是什么意思？","o":["前面有休息区","前面有道路维修区","前面有铁路道口","你必须右转"],"h1":"这个标志是在你到达某个地方之前给你的警告。","h2":"这个圆形黄色、有 X 和 \"RR\" 的标志警告你前面有铁路道口，所以你要减速，看一看，听一听。","p":"对。圆形黄色的 \"RR\" 标志表示前面有铁路道口。"},"vi":{"q":"Biển báo tròn màu vàng có chữ X và hai chữ \"RR\" này có nghĩa là gì?","o":["Phía trước có trạm dừng nghỉ","Phía trước có khu vực sửa đường","Phía trước có chỗ giao nhau với đường sắt","Bạn phải rẽ phải"],"h1":"Biển này cảnh báo bạn trước khi bạn đến một nơi nào đó.","h2":"Biển tròn màu vàng có chữ X và \"RR\" cảnh báo phía trước có chỗ giao nhau với đường sắt, nên bạn giảm tốc, nhìn và lắng nghe.","p":"Đúng. Biển tròn màu vàng \"RR\" có nghĩa là phía trước có đường sắt."},"tl":{"q":"Ano ang ibig sabihin ng bilog na dilaw na karatulang ito na may X at mga letrang RR?","o":["May rest area sa unahan","May lugar ng pagkukumpuni ng daan sa unahan","May railroad crossing sa unahan","Dapat kang kumanan"],"h1":"Binabalaan ka ng karatulang ito bago ka dumating sa isang bagay.","h2":"Binabalaan ka ng bilog na dilaw na karatulang may X at RR na may railroad crossing sa unahan, kaya babagal ka, titingin, at makikinig.","p":"Tama. Ang bilog na dilaw na karatulang RR ay nangangahulugang may railroad crossing sa unahan."},"ar":{"q":"ماذا تعني هذه العلامة الصفراء المستديرة التي عليها X والحرفان \"RR\"؟","o":["توجد استراحة أمامك","توجد منطقة إصلاح طريق أمامك","يوجد تقاطع سكة حديد أمامك","يجب أن تنعطف يمينًا"],"h1":"هذه العلامة تحذرك قبل أن تصل إلى شيء ما.","h2":"العلامة الصفراء المستديرة التي عليها X و\"RR\" تحذرك أن تقاطع سكة حديد أمامك، لذلك تخفف السرعة وتنظر وتسمع.","p":"صحيح. العلامة الصفراء المستديرة \"RR\" تعني أن تقاطع سكة حديد أمامك."},"ht":{"q":"Kisa siy jòn won sa a ki gen yon X ak lèt \"RR\" yo vle di?","o":["Gen yon zòn repo devan","Gen yon zòn reparasyon wout devan","Gen yon kwazman tren devan","Ou dwe vire adwat"],"h1":"Siy sa a avèti ou anvan ou rive nan yon bagay.","h2":"Siy jòn won ki gen yon X ak \"RR\" a avèti ou gen yon kwazman tren devan, kidonk ou ralanti, ou gade epi ou koute.","p":"Wi, se sa. Siy jòn won \"RR\" a vle di gen yon kwazman tren devan."},"ref":{"doc":"FL","page":56}},{"id":"right-of-way-033","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, you want to turn right. Which lane should you be in?","o":["The left lane","The right lane, close to the curb","The center lane","Any lane, if you signal"],"h1":"Pick the lane on the same side as your turn.","h2":"To turn right, you get into the right lane near the curb and turn into the right lane of the new street.","p":"Right. Turn right from the right lane, near the curb."},"es":{"q":"En Florida, usted quiere doblar a la derecha. ¿En qué carril debe estar?","o":["En el carril izquierdo","En el carril derecho, cerca de la orilla","En el carril del centro","En cualquier carril, si pone la direccional"],"h1":"Escoja el carril del mismo lado de su vuelta.","h2":"Para doblar a la derecha, usted se coloca en el carril derecho cerca de la orilla y dobla al carril derecho de la nueva calle.","p":"Correcto. Doble a la derecha desde el carril derecho, cerca de la orilla."},"zh":{"q":"在 Florida，你想右转。你应该在哪条车道？","o":["左边车道","右边车道，靠近路缘","中间车道","哪条车道都行，只要打转向灯"],"h1":"选和你转弯方向同一边的车道。","h2":"要右转，你应该进入靠近路缘的右边车道，然后转进新街道的右边车道。","p":"对。从靠近路缘的右边车道右转。"},"vi":{"q":"Ở Florida, bạn muốn rẽ phải. Bạn nên ở làn nào?","o":["Làn bên trái","Làn bên phải, sát lề đường","Làn ở giữa","Làn nào cũng được, nếu bạn bật xi nhan"],"h1":"Hãy chọn làn ở cùng phía với hướng bạn rẽ.","h2":"Để rẽ phải, bạn vào làn bên phải gần lề đường và rẽ vào làn bên phải của con đường mới.","p":"Đúng. Rẽ phải từ làn bên phải, sát lề đường."},"tl":{"q":"Sa Florida, gusto mong kumanan. Saang lane ka dapat naroon?","o":["Sa kaliwang lane","Sa kanang lane, malapit sa curb (gilid ng bangketa)","Sa gitnang lane","Kahit anong lane, basta mag-signal ka"],"h1":"Piliin ang lane na nasa parehong panig ng liko mo.","h2":"Para kumanan, pumunta ka sa kanang lane malapit sa curb at kumanan papunta sa kanang lane ng bagong kalye.","p":"Tama. Kumanan mula sa kanang lane, malapit sa curb."},"ar":{"q":"في Florida، تريد أن تنعطف يمينًا. في أي مسار يجب أن تكون؟","o":["المسار الأيسر","المسار الأيمن، قريبًا من الرصيف","المسار الأوسط","أي مسار، إذا استعملت الإشارة"],"h1":"اختر المسار الذي في جهة انعطافك نفسها.","h2":"لكي تنعطف يمينًا، تدخل المسار الأيمن قرب الرصيف، وتنعطف إلى المسار الأيمن في الشارع الجديد.","p":"صحيح. انعطف يمينًا من المسار الأيمن، قرب الرصيف."},"ht":{"q":"Nan Florida, ou vle vire adwat. Nan ki liy ou ta dwe ye?","o":["Liy gòch la","Liy dwat la, pre rebò twotwa a","Liy mitan an","Nenpòt liy, si ou mete siyal"],"h1":"Chwazi liy ki sou menm bò ak kote w ap vire a.","h2":"Pou vire adwat, ou antre nan liy dwat la pre rebò twotwa a, epi ou vire nan liy dwat lari kote w ap antre a.","p":"Wi, se sa. Vire adwat sòti nan liy dwat la, pre rebò twotwa a."},"ref":{"doc":"FL","page":70}},{"id":"right-of-way-034","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, you turn left from a two-way street onto another two-way street. Which lane do you turn into?","o":["The bike lane","The lane for oncoming traffic","The center turn lane","Any lane going your way that you may legally use"],"h1":"Think about which lanes carry traffic in your direction.","h2":"When you turn left, you may finish in any lane going your way that you are allowed to use, and you never enter a lane for oncoming traffic.","p":"Right. Turn left into a lane going your way that you may legally use."},"es":{"q":"En Florida, usted dobla a la izquierda de una calle de doble sentido a otra calle de doble sentido. ¿A qué carril dobla?","o":["Al carril de bicicletas","Al carril del tráfico que viene de frente","Al carril central de vuelta","A cualquier carril en su misma dirección que usted pueda usar legalmente"],"h1":"Piense en qué carriles llevan el tráfico en su misma dirección.","h2":"Cuando usted dobla a la izquierda, puede terminar en cualquier carril en su misma dirección que tenga permitido usar, y nunca entra a un carril del tráfico que viene de frente.","p":"Correcto. Doble a la izquierda a un carril en su misma dirección que usted pueda usar legalmente."},"zh":{"q":"在 Florida，你从一条双向街道左转到另一条双向街道。你应该转进哪条车道？","o":["自行车道","对面来车的车道","中央转弯车道","任何和你同方向、而且你可以合法使用的车道"],"h1":"想一想哪些车道上的车和你同一个方向。","h2":"左转时，你可以转进任何和你同方向、而且你可以使用的车道，但永远不能进入对面来车的车道。","p":"对。左转进入和你同方向、你可以合法使用的车道。"},"vi":{"q":"Ở Florida, bạn rẽ trái từ một đường hai chiều sang một đường hai chiều khác. Bạn rẽ vào làn nào?","o":["Làn xe đạp","Làn của xe đi ngược chiều","Làn rẽ ở giữa","Bất kỳ làn nào cùng chiều với bạn mà bạn được phép dùng"],"h1":"Hãy nghĩ xem làn nào có xe chạy cùng hướng với bạn.","h2":"Khi rẽ trái, bạn có thể vào bất kỳ làn nào cùng chiều mà bạn được phép dùng, và bạn không bao giờ đi vào làn của xe ngược chiều.","p":"Đúng. Rẽ trái vào làn cùng chiều mà bạn được phép dùng."},"tl":{"q":"Sa Florida, kumaliwa ka mula sa kalyeng two-way papunta sa isa pang kalyeng two-way. Saang lane ka papasok?","o":["Sa bike lane","Sa lane ng paparating na trapiko","Sa center turn lane","Sa kahit anong lane na papunta sa direksiyon mo na legal mong magagamit"],"h1":"Isipin kung aling mga lane ang may trapiko sa direksiyon mo.","h2":"Kapag kumaliwa ka, puwede kang pumasok sa kahit anong lane na papunta sa direksiyon mo na pinapayagan kang gamitin, at hindi ka kailanman papasok sa lane ng paparating na trapiko.","p":"Tama. Kumaliwa papunta sa lane na papunta sa direksiyon mo na legal mong magagamit."},"ar":{"q":"في Florida، تنعطف يسارًا من شارع باتجاهين إلى شارع آخر باتجاهين. إلى أي مسار تنعطف؟","o":["مسار الدراجات","مسار السيارات القادمة نحوك","مسار الانعطاف في الوسط","أي مسار في اتجاهك يُسمح لك باستعماله"],"h1":"فكّر في المسارات التي تسير فيها السيارات في اتجاهك.","h2":"عندما تنعطف يسارًا، يمكنك أن تنهي الانعطاف في أي مسار في اتجاهك يُسمح لك باستعماله، ولا تدخل أبدًا مسار السيارات القادمة نحوك.","p":"صحيح. انعطف يسارًا إلى مسار في اتجاهك يُسمح لك قانونيًا باستعماله."},"ht":{"q":"Nan Florida, ou vire agòch sòti nan yon lari de sans pou antre nan yon lòt lari de sans. Nan ki liy ou antre?","o":["Liy pou bisiklèt la","Liy pou machin k ap vin sou ou yo","Liy pou vire nan mitan an","Nenpòt liy k ap ale nan direksyon pa w la ou gen dwa sèvi ak li"],"h1":"Panse ak ki liy ki pote machin nan direksyon pa w la.","h2":"Lè ou vire agòch, ou ka fini nan nenpòt liy k ap ale nan direksyon pa w la ou gen dwa sèvi ak li, epi ou pa janm antre nan yon liy pou machin k ap vin sou ou.","p":"Wi, se sa. Vire agòch nan yon liy k ap ale nan direksyon pa w la ou gen dwa sèvi ak li."},"ref":{"doc":"FL","page":70}},{"id":"right-of-way-035","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, how far before a turn should you turn on your signal?","o":["Only as you start to turn","At least 10 feet before","At least 25 feet before","At least 100 feet before"],"h1":"Other drivers need time to see what you plan to do.","h2":"In Florida you should signal at least 100 feet before you turn, so drivers and people walking know what you will do.","p":"Right. Signal at least 100 feet before you turn."},"es":{"q":"En Florida, ¿con cuánta anticipación debe poner la direccional antes de doblar?","o":["Solo cuando empieza a doblar","Por lo menos 10 pies antes","Por lo menos 25 pies antes","Por lo menos 100 pies antes"],"h1":"Los otros conductores necesitan tiempo para ver lo que usted va a hacer.","h2":"En Florida usted debe poner la direccional por lo menos 100 pies antes de doblar, para que los conductores y los peatones sepan lo que va a hacer.","p":"Correcto. Ponga la direccional por lo menos 100 pies antes de doblar."},"zh":{"q":"在 Florida，转弯前多远应该打开转向灯？","o":["只在开始转弯的时候","至少提前 10 英尺","至少提前 25 英尺","至少提前 100 英尺"],"h1":"其他司机需要时间看清你要做什么。","h2":"在 Florida，你应该在转弯前至少 100 英尺打转向灯，让司机和行人知道你要做什么。","p":"对。转弯前至少 100 英尺打转向灯。"},"vi":{"q":"Ở Florida, bạn nên bật xi nhan bao xa trước khi rẽ?","o":["Chỉ khi bạn bắt đầu rẽ","Ít nhất 10 feet trước đó","Ít nhất 25 feet trước đó","Ít nhất 100 feet trước đó"],"h1":"Người lái khác cần thời gian để thấy bạn định làm gì.","h2":"Ở Florida, bạn nên bật xi nhan ít nhất 100 feet trước khi rẽ, để người lái và người đi bộ biết bạn sẽ làm gì.","p":"Đúng. Hãy bật xi nhan ít nhất 100 feet trước khi rẽ."},"tl":{"q":"Sa Florida, gaano kalayo bago lumiko dapat mong buksan ang signal mo?","o":["Habang nagsisimula ka lang lumiko","Hindi bababa sa 10 feet bago lumiko","Hindi bababa sa 25 feet bago lumiko","Hindi bababa sa 100 feet bago lumiko"],"h1":"Kailangan ng ibang drayber ng oras para makita ang balak mong gawin.","h2":"Sa Florida, dapat kang mag-signal nang hindi bababa sa 100 feet bago ka lumiko, para malaman ng mga drayber at ng mga naglalakad ang gagawin mo.","p":"Tama. Mag-signal nang hindi bababa sa 100 feet bago ka lumiko."},"ar":{"q":"في Florida، قبل الانعطاف بكم مسافة يجب أن تشغّل إشارة الانعطاف؟","o":["فقط عندما أبدأ الانعطاف","10 أقدام على الأقل قبله","25 قدمًا على الأقل قبله","100 قدم على الأقل قبله"],"h1":"السائقون الآخرون يحتاجون إلى وقت ليروا ماذا تريد أن تفعل.","h2":"في Florida يجب أن تشغّل الإشارة قبل الانعطاف بمسافة 100 قدم على الأقل، حتى يعرف السائقون والمشاة ماذا ستفعل.","p":"صحيح. شغّل الإشارة قبل الانعطاف بمسافة 100 قدم على الأقل."},"ht":{"q":"Nan Florida, a ki distans anvan yon vire ou ta dwe limen siyal ou?","o":["Sèlman lè w ap kòmanse vire","Omwen 10 pye anvan","Omwen 25 pye anvan","Omwen 100 pye anvan"],"h1":"Lòt chofè yo bezwen tan pou yo wè sa ou vle fè.","h2":"Nan Florida ou ta dwe mete siyal omwen 100 pye anvan ou vire, pou chofè yo ak moun k ap mache yo konnen sa ou pral fè.","p":"Wi, se sa. Mete siyal omwen 100 pye anvan ou vire."},"ref":{"doc":"FL","page":69}},{"id":"right-of-way-036","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, when may you make a U-turn?","o":["Any time you miss your street","Only when it is safe and no sign forbids it","Only on a highway","Only at a railroad crossing"],"h1":"Think about signs and about traffic around you.","h2":"You may make a U-turn only where no sign forbids it and only when you can do it safely without getting in the way of other traffic.","p":"Right. Make a U-turn only when it is safe and allowed."},"es":{"q":"En Florida, ¿cuándo puede dar una vuelta en U?","o":["Cada vez que se pase de su calle","Solo cuando es seguro y ninguna señal lo prohíbe","Solo en la autopista","Solo en un cruce de tren"],"h1":"Piense en las señales y en el tráfico a su alrededor.","h2":"Usted puede dar una vuelta en U solo donde ninguna señal lo prohíba y solo cuando pueda hacerla con seguridad, sin estorbar a otros vehículos.","p":"Correcto. Dé vuelta en U solo cuando sea seguro y permitido."},"zh":{"q":"在 Florida，什么时候可以掉头（U-turn）？","o":["每次错过你要去的街道时","只有在安全、而且没有标志禁止时","只在高速公路上","只在铁路道口"],"h1":"想一想标志，也想一想你周围的车。","h2":"只有在没有标志禁止的地方，而且你能安全掉头、不妨碍其他车辆时，你才可以掉头。","p":"对。只有在安全而且允许的时候才掉头。"},"vi":{"q":"Ở Florida, khi nào bạn được quay đầu xe hình chữ U?","o":["Bất cứ lúc nào bạn đi lố con đường của mình","Chỉ khi an toàn và không có biển báo cấm","Chỉ trên xa lộ","Chỉ ở chỗ giao nhau với đường sắt"],"h1":"Hãy nghĩ đến biển báo và xe cộ xung quanh bạn.","h2":"Bạn chỉ được quay đầu chữ U ở nơi không có biển báo cấm và chỉ khi bạn làm được một cách an toàn mà không cản trở xe khác.","p":"Đúng. Chỉ quay đầu chữ U khi an toàn và được phép."},"tl":{"q":"Sa Florida, kailan ka puwedeng mag-U-turn?","o":["Anumang oras na nalampasan mo ang kalye mo","Kapag ligtas lang at walang karatulang nagbabawal","Sa highway lang","Sa railroad crossing lang"],"h1":"Isipin ang mga karatula at ang trapiko sa paligid mo.","h2":"Puwede ka lang mag-U-turn kung walang karatulang nagbabawal nito at kung magagawa mo ito nang ligtas, nang hindi nakaharang sa ibang trapiko.","p":"Tama. Mag-U-turn lang kapag ligtas at pinapayagan."},"ar":{"q":"في Florida، متى يمكنك أن تقوم بدوران كامل للخلف (U-turn)؟","o":["في أي وقت عندما يفوتني الشارع","فقط عندما يكون آمنًا ولا توجد علامة تمنعه","فقط على الطريق السريع","فقط عند تقاطع سكة حديد"],"h1":"فكّر في العلامات وفي السيارات حولك.","h2":"يمكنك أن تقوم بدوران كامل للخلف فقط حيث لا توجد علامة تمنعه، وفقط عندما تستطيع أن تقوم به بأمان بدون أن تعيق السيارات الأخرى.","p":"صحيح. قم بالدوران الكامل للخلف فقط عندما يكون آمنًا ومسموحًا."},"ht":{"q":"Nan Florida, kilè ou ka fè yon demi-tou (U-turn)?","o":["Nenpòt lè ou rate lari ou a","Sèlman lè li pa danjere epi pa gen okenn siy ki entèdi l","Sèlman sou yon gran wout","Sèlman nan yon kwazman tren"],"h1":"Panse ak siy yo ak machin ki bò kote ou yo.","h2":"Ou ka fè yon demi-tou sèlman kote pa gen okenn siy ki entèdi l epi sèlman lè ou ka fè l san danje san ou pa jennen lòt machin yo.","p":"Wi, se sa. Fè yon demi-tou sèlman lè li pa danjere epi li pèmèt."},"ref":{"doc":"FL","page":47}},{"id":"right-of-way-037","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, you stopped at a red light and want to turn right. A person is crossing in front of you. What do you do?","o":["Turn now, because right on red is allowed","Honk and turn","Wait for the person to cross, then turn when traffic is clear","Turn into the far lane to go around the person"],"h1":"A right turn on red is allowed only after you yield.","h2":"When you turn right on red, you must first stop and yield to people crossing and to traffic, so you wait until the way is clear.","p":"Right. On red, yield to people and traffic before you turn right."},"es":{"q":"En Florida, usted paró en una luz roja y quiere doblar a la derecha. Una persona está cruzando delante de usted. ¿Qué hace?","o":["Dobla ahora, porque se permite doblar a la derecha en rojo","Toca la bocina y dobla","Espera que la persona cruce y luego dobla cuando el tráfico esté libre","Dobla al carril lejano para pasar alrededor de la persona"],"h1":"Doblar a la derecha en rojo se permite solo después de ceder el paso.","h2":"Cuando usted dobla a la derecha en rojo, primero debe parar y ceder el paso a las personas que cruzan y al tráfico, así que espera hasta que el camino esté libre.","p":"Correcto. En rojo, ceda el paso a peatones y tráfico antes de doblar a la derecha."},"zh":{"q":"在 Florida，你在红灯前停下，想右转。有一个人正在你前面过马路。你该怎么做？","o":["现在就转，因为红灯可以右转","按喇叭，然后转","等这个人过完马路，路上没车了再转","转进最远的车道，绕过这个人"],"h1":"红灯右转只有在你让行以后才可以。","h2":"红灯右转时，你必须先停车，让过马路的人和其他车先走，所以要等路上安全了再转。","p":"对。红灯右转前，先让行人和车辆走。"},"vi":{"q":"Ở Florida, bạn đã dừng ở đèn đỏ và muốn rẽ phải. Có người đang băng qua đường trước mặt bạn. Bạn làm gì?","o":["Rẽ ngay, vì được phép rẽ phải khi đèn đỏ","Bấm còi và rẽ","Chờ người đó qua hết, rồi rẽ khi không có xe","Rẽ vào làn xa để vòng qua người đó"],"h1":"Rẽ phải khi đèn đỏ chỉ được phép sau khi bạn đã nhường đường.","h2":"Khi rẽ phải lúc đèn đỏ, trước tiên bạn phải dừng lại và nhường người đi bộ và xe cộ, nên bạn chờ đến khi đường trống.","p":"Đúng. Khi đèn đỏ, hãy nhường người đi bộ và xe cộ trước khi rẽ phải."},"tl":{"q":"Sa Florida, huminto ka sa pulang ilaw at gusto mong kumanan. May taong tumatawid sa harap mo. Ano ang gagawin mo?","o":["Kumanan na, dahil pinapayagan ang pagkanan sa pula","Bumusina at kumanan","Hintaying makatawid ang tao, saka kumanan kapag malinis na ang trapiko","Kumanan papunta sa malayong lane para iwasan ang tao"],"h1":"Pinapayagan ang pagkanan sa pula pagkatapos mo lang magbigay-daan.","h2":"Kapag kumakanan ka sa pula, dapat ka munang huminto at magbigay-daan sa mga tumatawid at sa trapiko, kaya maghihintay ka hanggang malinis ang daan.","p":"Tama. Sa pula, magbigay-daan sa mga tao at trapiko bago ka kumanan."},"ar":{"q":"في Florida، توقفت عند إشارة حمراء وتريد أن تنعطف يمينًا. شخص يعبر أمامك. ماذا تفعل؟","o":["أنعطف الآن، لأن الانعطاف يمينًا عند الإشارة الحمراء مسموح","أستعمل البوق وأنعطف","أنتظر حتى يعبر الشخص، ثم أنعطف عندما يكون الطريق فارغًا","أنعطف إلى المسار البعيد لألتف حول الشخص"],"h1":"الانعطاف يمينًا عند الإشارة الحمراء مسموح فقط بعد أن تعطي حق المرور.","h2":"عندما تنعطف يمينًا عند الإشارة الحمراء، يجب أولًا أن تتوقف وتعطي حق المرور للمشاة وللسيارات، لذلك تنتظر حتى يصبح الطريق فارغًا.","p":"صحيح. عند الإشارة الحمراء، أعطِ حق المرور للناس وللسيارات قبل أن تنعطف يمينًا."},"ht":{"q":"Nan Florida, ou kanpe nan yon limyè wouj epi ou vle vire adwat. Gen yon moun k ap travèse devan ou. Kisa ou fè?","o":["Ou vire kounye a, paske yo pèmèt vire adwat sou limyè wouj","Ou klaksonnen epi ou vire","Ou tann moun nan travèse, apre sa ou vire lè pa gen machin","Ou vire nan liy ki pi lwen an pou ou pase bò kote moun nan"],"h1":"Yo pèmèt ou vire adwat sou limyè wouj sèlman apre ou fin kite lòt yo pase.","h2":"Lè ou vire adwat sou limyè wouj, ou dwe kanpe anvan epi kite moun k ap travèse yo ak machin yo pase, kidonk ou tann jiskaske chemen an lib.","p":"Wi, se sa. Sou limyè wouj, kite moun yo ak machin yo pase anvan ou vire adwat."},"ref":{"doc":"FL","page":51}},{"id":"right-of-way-038","scope":"US","cat":"right-of-way","sign":{"shape":"yield","text":"YIELD"},"c":2,"en":{"q":"What does this red and white upside-down triangle sign tell you to do?","o":["Stop fully every time","Speed up and merge","Slow down and let other traffic go first, stopping if needed","Turn around"],"h1":"This sign does not always mean a full stop.","h2":"A yield sign means you slow down and let other traffic and people go first, and you stop only if you need to.","p":"Right. A yield sign means slow down and let others go first."},"es":{"q":"¿Qué le indica esta señal de triángulo rojo y blanco con la punta hacia abajo?","o":["Pare por completo siempre","Acelere y únase al tráfico","Baje la velocidad y deje pasar primero a los demás, parando si hace falta","Dé la vuelta"],"h1":"Esta señal no siempre significa un alto total.","h2":"Una señal de ceda el paso significa que usted baja la velocidad y deja pasar primero a otros vehículos y personas, y para solo si es necesario.","p":"Correcto. Ceda el paso significa bajar la velocidad y dejar pasar a los demás."},"zh":{"q":"这个红白色、倒三角形的标志告诉你要做什么？","o":["每次都要完全停车","加速并入车流","减速，让其他车先走，需要时停车","掉头"],"h1":"这个标志不一定是要你完全停车。","h2":"让行标志的意思是你要减速，让其他车和行人先走，只有在需要时才停车。","p":"对。让行标志的意思是减速，让别人先走。"},"vi":{"q":"Biển báo hình tam giác ngược màu đỏ và trắng này bảo bạn làm gì?","o":["Luôn luôn dừng hẳn","Tăng tốc và nhập làn","Giảm tốc và để xe khác đi trước, dừng lại nếu cần","Quay đầu xe"],"h1":"Biển này không phải lúc nào cũng có nghĩa là dừng hẳn.","h2":"Biển \"YIELD\" (Nhường đường) có nghĩa là bạn giảm tốc và để xe khác và người đi bộ đi trước, và bạn chỉ dừng lại nếu cần.","p":"Đúng. Biển \"YIELD\" có nghĩa là giảm tốc và để người khác đi trước."},"tl":{"q":"Ano ang sinasabi sa iyo ng pula at puting baligtad na tatsulok na karatulang ito?","o":["Huminto nang buo sa bawat pagkakataon","Bumilis at sumanib sa trapiko","Bumagal at paunahin ang ibang trapiko, at huminto kung kailangan","Umikot pabalik"],"h1":"Hindi laging buong paghinto ang ibig sabihin ng karatulang ito.","h2":"Ang \"YIELD\" sign (magbigay-daan) ay nangangahulugang babagal ka at paunahin ang ibang trapiko at mga tao, at hihinto ka lang kung kailangan.","p":"Tama. Ang \"YIELD\" sign ay nangangahulugang bumagal at paunahin ang iba."},"ar":{"q":"هذه العلامة مثلث أحمر وأبيض مقلوب. ماذا تطلب منك أن تفعل؟","o":["أتوقف توقفًا كاملًا كل مرة","أسرع وأندمج","أخفف السرعة وأترك السيارات الأخرى تمر أولًا، وأتوقف إذا لزم الأمر","أرجع من حيث جئت"],"h1":"هذه العلامة لا تعني دائمًا توقفًا كاملًا.","h2":"علامة \"YIELD\" (أعطِ حق المرور) تعني أن تخفف السرعة وتترك السيارات الأخرى والمشاة يمرون أولًا، وتتوقف فقط إذا احتجت إلى ذلك.","p":"صحيح. علامة \"YIELD\" (أعطِ حق المرور) تعني: خفف السرعة واترك الآخرين يمرون أولًا."},"ht":{"q":"Kisa siy wouj e blan sa a ki gen fòm yon triyang tèt anba di ou fè?","o":["Kanpe nèt chak fwa","Akselere epi antre nan sikilasyon an","Ralanti epi kite lòt machin yo pase anvan, kanpe si sa nesesè","Fè demi-tou"],"h1":"Siy sa a pa toujou vle di kanpe nèt.","h2":"Yon siy \"YIELD\" (kite pase) vle di ou ralanti epi ou kite lòt machin ak moun yo pase anvan, epi ou kanpe sèlman si ou bezwen.","p":"Wi, se sa. Yon siy \"YIELD\" vle di ralanti epi kite lòt yo pase anvan."},"ref":{"doc":"FL","page":47}},{"id":"right-of-way-039","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, you are on a ramp joining a highway. Who has the right of way?","o":["Traffic already on the highway","You, because you are on the ramp","The faster car","Whoever signals first"],"h1":"Think about who is already on the main road.","h2":"When you merge onto a highway, you must yield to the traffic already on it and find a safe gap.","p":"Right. When merging, yield to traffic already on the highway."},"es":{"q":"En Florida, usted va por una rampa para entrar a una carretera. ¿Quién tiene el derecho de paso?","o":["El tráfico que ya va por la carretera","Usted, porque va por la rampa","El carro más rápido","El que pone la direccional primero"],"h1":"Piense en quién ya está en la vía principal.","h2":"Cuando usted entra a una carretera, debe ceder el paso al tráfico que ya va por ella y buscar un espacio seguro.","p":"Correcto. Al entrar a la carretera, ceda el paso al tráfico que ya va por ella."},"zh":{"q":"在 Florida，你在匝道上，准备并入高速公路。谁有先行权？","o":["已经在高速公路上的车","你，因为你在匝道上","开得快的车","先打转向灯的人"],"h1":"想一想谁已经在主路上。","h2":"并入高速公路时，你必须让已经在高速公路上的车先走，并找到一个安全的空隙。","p":"对。并入时，让已经在高速公路上的车先走。"},"vi":{"q":"Ở Florida, bạn đang ở trên đường dẫn để nhập vào xa lộ. Ai có quyền ưu tiên?","o":["Xe đã ở trên xa lộ","Bạn, vì bạn đang ở trên đường dẫn","Xe chạy nhanh hơn","Người bật xi nhan trước"],"h1":"Hãy nghĩ xem ai đã ở trên đường chính rồi.","h2":"Khi nhập vào xa lộ, bạn phải nhường xe đã ở trên xa lộ và tìm khoảng trống an toàn.","p":"Đúng. Khi nhập làn, hãy nhường xe đã ở trên xa lộ."},"tl":{"q":"Sa Florida, nasa ramp ka papasok sa highway. Sino ang may karapatan sa daan?","o":["Ang trapikong nasa highway na","Ikaw, dahil nasa ramp ka","Ang mas mabilis na kotse","Kung sino ang unang mag-signal"],"h1":"Isipin kung sino na ang nasa pangunahing daan.","h2":"Kapag sumasanib ka sa highway, dapat kang magbigay-daan sa trapikong nasa highway na at maghanap ng ligtas na puwang.","p":"Tama. Kapag sumasanib, magbigay-daan sa trapikong nasa highway na."},"ar":{"q":"في Florida، أنت على منحدر الدخول إلى طريق سريع. من له حق المرور؟","o":["السيارات الموجودة على الطريق السريع","أنت، لأنك على منحدر الدخول","السيارة الأسرع","من يشغّل الإشارة أولًا"],"h1":"فكّر في من هو موجود الآن على الطريق الرئيسي.","h2":"عندما تندمج في طريق سريع، يجب أن تعطي حق المرور للسيارات الموجودة عليه وتجد مسافة آمنة.","p":"صحيح. عند الاندماج، أعطِ حق المرور للسيارات الموجودة على الطريق السريع."},"ht":{"q":"Nan Florida, ou sou yon ranp k ap antre sou yon gran wout. Kiyès ki gen dwa pou pase anvan?","o":["Machin ki deja sou gran wout la","Ou menm, paske ou sou ranp lan","Machin ki pi vit la","Moun ki mete siyal an premye a"],"h1":"Panse ak kiyès ki deja sou wout prensipal la.","h2":"Lè w ap antre sou yon gran wout, ou dwe kite machin ki deja sou li yo pase anvan epi chèche yon espas ki san danje.","p":"Wi, se sa. Lè w ap antre, kite machin ki deja sou gran wout la pase anvan."},"ref":{"doc":"FL","page":63}},{"id":"safe-driving-001","scope":"FL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Florida, how much space must you leave when you pass a bicycle?","o":["At least 1 foot","At least 2 feet","At least 3 feet","At least 10 feet"],"h1":"Think about a safe gap between your car and the rider.","h2":"Florida law says you must leave at least 3 feet between your car and a bicycle when you pass it.","p":"Right. Give a bicycle at least 3 feet when you pass."},"es":{"q":"En Florida, ¿cuánto espacio debe dejar al rebasar una bicicleta?","o":["Al menos 1 pie","Al menos 2 pies","Al menos 3 pies","Al menos 10 pies"],"h1":"Piense en un espacio seguro entre su carro y el ciclista.","h2":"La ley de Florida dice que debe dejar al menos 3 pies entre su carro y una bicicleta cuando la rebasa.","p":"Correcto. Deje al menos 3 pies al rebasar una bicicleta."},"zh":{"q":"在 Florida，你超过自行车时必须留出多少空间？","o":["至少 1 英尺","至少 2 英尺","至少 3 英尺","至少 10 英尺"],"h1":"想一想你的车和骑车人之间安全的距离。","h2":"Florida 法律规定，你超过自行车时，你的车和自行车之间必须留出至少 3 英尺。","p":"对。超过自行车时，至少留出 3 英尺。"},"vi":{"q":"Ở Florida, khi vượt qua xe đạp, bạn phải chừa khoảng cách bao nhiêu?","o":["Ít nhất 1 foot","Ít nhất 2 feet","Ít nhất 3 feet","Ít nhất 10 feet"],"h1":"Hãy nghĩ đến một khoảng trống an toàn giữa xe bạn và người đi xe đạp.","h2":"Luật Florida nói rằng bạn phải chừa ít nhất 3 feet giữa xe bạn và xe đạp khi vượt qua.","p":"Đúng. Chừa cho xe đạp ít nhất 3 feet khi bạn vượt qua."},"tl":{"q":"Sa Florida, gaano kalaking espasyo ang dapat mong iwan kapag nag-overtake ka sa bisikleta?","o":["Hindi bababa sa 1 foot","Hindi bababa sa 2 feet","Hindi bababa sa 3 feet","Hindi bababa sa 10 feet"],"h1":"Isipin ang ligtas na pagitan ng kotse mo at ng nagbibisikleta.","h2":"Sinasabi ng batas ng Florida na dapat kang mag-iwan ng hindi bababa sa 3 feet sa pagitan ng kotse mo at ng bisikleta kapag nag-overtake ka rito.","p":"Tama. Bigyan ang bisikleta ng hindi bababa sa 3 feet kapag nag-overtake ka."},"ar":{"q":"في Florida، كم مسافة يجب أن تترك عندما تتجاوز دراجة هوائية؟","o":["قدم واحدة (1 foot) على الأقل","2 قدم (feet) على الأقل","3 أقدام (feet) على الأقل","10 أقدام (feet) على الأقل"],"h1":"فكّر في مسافة آمنة بين سيارتك وراكب الدراجة.","h2":"قانون Florida يقول إنه يجب أن تترك 3 أقدام (feet) على الأقل بين سيارتك والدراجة الهوائية عندما تتجاوزها.","p":"صحيح. اترك للدراجة 3 أقدام (feet) على الأقل عندما تتجاوزها."},"ht":{"q":"Nan Florida, konbyen espas ou dwe kite lè w ap pase yon bisiklèt?","o":["Omwen 1 pye","Omwen 2 pye","Omwen 3 pye","Omwen 10 pye"],"h1":"Panse ak yon espas ki an sekirite ant machin ou ak moun ki sou bisiklèt la.","h2":"Lalwa Florida di ou dwe kite omwen 3 pye ant machin ou ak yon bisiklèt lè w ap pase l.","p":"Se sa. Bay yon bisiklèt omwen 3 pye lè w ap pase l."},"ref":{"doc":"FL","page":81}},{"id":"safe-driving-002","scope":"FL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Florida, you want to turn right. A bicycle is in the bike lane next to you. What should you do?","o":["Speed up and turn in front of it","Let the bicycle go by, then turn","Honk so the rider will stop","Turn from the left lane instead"],"h1":"Think about who is already moving straight in that lane.","h2":"The bicycle is going straight in its own lane, so you must let it pass before you turn right across the bike lane.","p":"Right. Let the bicycle go by first, then turn."},"es":{"q":"En Florida, usted quiere girar a la derecha. Hay una bicicleta en el carril de bicicletas a su lado. ¿Qué debe hacer?","o":["Acelerar y girar delante de ella","Dejar pasar la bicicleta y luego girar","Tocar la bocina para que pare","Girar desde el carril izquierdo"],"h1":"Piense en quién ya va derecho en ese carril.","h2":"La bicicleta va derecho en su propio carril, así que debe dejarla pasar antes de girar a la derecha y cruzar el carril de bicicletas.","p":"Correcto. Deje pasar la bicicleta primero y luego gire."},"zh":{"q":"在 Florida，你想右转。有一辆自行车在你旁边的自行车道上。你应该怎么做？","o":["加速，在它前面转弯","让自行车先过去，然后再转弯","按喇叭让骑车人停下","改从左边车道转弯"],"h1":"想一想谁已经在那条车道上直行。","h2":"自行车在自己的车道上直行，所以你必须让它先过去，然后再穿过自行车道右转。","p":"对。先让自行车过去，然后再转弯。"},"vi":{"q":"Ở Florida, bạn muốn rẽ phải. Có một xe đạp đang ở làn xe đạp cạnh bạn. Bạn nên làm gì?","o":["Tăng tốc và rẽ trước xe đạp","Để xe đạp đi qua, rồi mới rẽ","Bấm còi để người đi xe đạp dừng lại","Rẽ từ làn bên trái thay vào đó"],"h1":"Hãy nghĩ xem ai đang đi thẳng trong làn đó.","h2":"Xe đạp đang đi thẳng trong làn của nó, nên bạn phải để xe đạp đi qua trước khi rẽ phải cắt ngang làn xe đạp.","p":"Đúng. Để xe đạp đi qua trước, rồi mới rẽ."},"tl":{"q":"Sa Florida, gusto mong kumanan. May bisikleta sa bike lane sa tabi mo. Ano ang dapat mong gawin?","o":["Bumilis at kumanan sa harap nito","Hayaang dumaan muna ang bisikleta, saka kumanan","Bumusina para huminto ang nagbibisikleta","Kumanan na lang mula sa kaliwang lane"],"h1":"Isipin kung sino ang diretsong umaandar na sa lane na iyon.","h2":"Diretsong umaandar ang bisikleta sa sarili nitong lane, kaya dapat mo itong hayaang dumaan bago ka kumanan patawid sa bike lane.","p":"Tama. Hayaang dumaan muna ang bisikleta, saka kumanan."},"ar":{"q":"في Florida، تريد أن تنعطف يمينًا. توجد دراجة هوائية في مسار الدراجات بجانبك. ماذا يجب أن تفعل؟","o":["أسرع وانعطف أمامها","اترك الدراجة تمرّ، ثم انعطف","استعمل البوق حتى يتوقف راكب الدراجة","انعطف من المسار الأيسر بدلًا من ذلك"],"h1":"فكّر: من يسير إلى الأمام مباشرة في ذلك المسار الآن؟","h2":"الدراجة تسير إلى الأمام في مسارها، لذلك يجب أن تتركها تمرّ قبل أن تنعطف يمينًا وتقطع مسار الدراجات.","p":"صحيح. اترك الدراجة تمرّ أولًا، ثم انعطف."},"ht":{"q":"Nan Florida, ou vle vire adwat. Gen yon bisiklèt nan liy bisiklèt la bò kote w. Kisa ou ta dwe fè?","o":["Akselere epi vire devan l","Kite bisiklèt la pase, epi vire","Klaksonen pou moun nan kanpe","Vire soti nan liy goch la pito"],"h1":"Panse ak kiyès ki deja ap ale tou dwat nan liy sa a.","h2":"Bisiklèt la ap ale tou dwat nan pwòp liy pa l, kidonk ou dwe kite l pase anvan ou vire adwat travèse liy bisiklèt la.","p":"Se sa. Kite bisiklèt la pase anvan, epi vire."},"ref":{"doc":"FL","page":81}},{"id":"safe-driving-003","scope":"FL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Florida, you parked on a busy street. What should you do before you open your door on the traffic side?","o":["Open it fast so you are quick","Turn on your wipers first","Honk the horn one time","Look back for bikes and cars"],"h1":"Think about who might be coming up beside your car.","h2":"A door that opens suddenly can hit a cyclist or a car, so you must look back and wait until it is safe to open it.","p":"Right. Look back for bikes and cars before you open your door."},"es":{"q":"En Florida, usted se estacionó en una calle con mucho tráfico. ¿Qué debe hacer antes de abrir la puerta del lado del tráfico?","o":["Abrirla rápido para no tardar","Encender los limpiaparabrisas","Tocar la bocina una vez","Mirar atrás por bicicletas y carros"],"h1":"Piense en quién podría venir al lado de su carro.","h2":"Una puerta que se abre de repente puede golpear a un ciclista o a un carro, así que debe mirar atrás y esperar hasta que sea seguro abrirla.","p":"Correcto. Mire atrás por bicicletas y carros antes de abrir la puerta."},"zh":{"q":"在 Florida，你把车停在一条车很多的街上。打开靠车流一侧的车门前，你应该做什么？","o":["快速打开，节省时间","先打开雨刷","按一下喇叭","回头看有没有自行车和汽车"],"h1":"想一想谁可能正从你的车旁边过来。","h2":"突然打开的车门可能撞到骑自行车的人或汽车，所以你必须回头看，等到安全时再开门。","p":"对。开门前回头看有没有自行车和汽车。"},"vi":{"q":"Ở Florida, bạn đậu xe trên một con đường đông xe. Bạn nên làm gì trước khi mở cửa xe ở phía có xe chạy?","o":["Mở nhanh cho kịp","Bật cần gạt nước trước","Bấm còi một lần","Nhìn ra sau xem có xe đạp và xe hơi không"],"h1":"Hãy nghĩ xem ai có thể đang đến gần bên cạnh xe bạn.","h2":"Cửa xe mở đột ngột có thể đụng vào người đi xe đạp hoặc xe hơi, nên bạn phải nhìn ra sau và chờ đến khi an toàn mới mở cửa.","p":"Đúng. Nhìn ra sau xem có xe đạp và xe hơi không trước khi mở cửa."},"tl":{"q":"Sa Florida, nag-park ka sa mataong kalye. Ano ang dapat mong gawin bago buksan ang pinto mo sa gilid ng trapiko?","o":["Buksan ito nang mabilis para mabilis ka","I-on muna ang wipers mo","Bumusina nang isang beses","Lumingon sa likod para tingnan kung may bisikleta o kotse"],"h1":"Isipin kung sino ang puwedeng paparating sa tabi ng kotse mo.","h2":"Ang pintong biglang bumukas ay puwedeng tumama sa nagbibisikleta o sa kotse, kaya dapat kang lumingon sa likod at maghintay hanggang ligtas nang buksan ito.","p":"Tama. Lumingon sa likod para sa bisikleta at kotse bago buksan ang pinto mo."},"ar":{"q":"في Florida، أوقفت سيارتك في شارع مزدحم. ماذا يجب أن تفعل قبل أن تفتح بابك من جهة السير؟","o":["افتحه بسرعة حتى تنتهي بسرعة","شغّل المساحات أولًا","استعمل البوق مرة واحدة","انظر إلى الخلف لترى الدراجات والسيارات"],"h1":"فكّر: من قد يقترب بجانب سيارتك؟","h2":"الباب الذي يُفتح فجأة قد يضرب راكب دراجة أو سيارة، لذلك يجب أن تنظر إلى الخلف وتنتظر حتى يصبح فتحه آمنًا.","p":"صحيح. انظر إلى الخلف لترى الدراجات والسيارات قبل أن تفتح بابك."},"ht":{"q":"Nan Florida, ou pake nan yon lari ki gen anpil machin. Kisa ou ta dwe fè anvan ou louvri pòt ou bò kote machin yo ap pase a?","o":["Louvri l vit pou w fè vit","Limen wipè ou anvan","Klaksonen yon fwa","Gade dèyè pou bisiklèt ak machin"],"h1":"Panse ak kiyès ki ka ap vini bò kote machin ou.","h2":"Yon pòt ki louvri sanzatann ka frape yon moun sou bisiklèt oswa yon machin, kidonk ou dwe gade dèyè epi tann jiskaske li an sekirite pou w louvri l.","p":"Se sa. Gade dèyè pou bisiklèt ak machin anvan ou louvri pòt ou."},"ref":{"doc":"FL","page":81}},{"id":"safe-driving-004","scope":"FL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Florida, a person is walking across the street in a crosswalk in front of you. What must you do?","o":["Stop and let the person cross","Drive slowly around the person","Honk so the person hurries","Keep going if you have a green light"],"h1":"Think about who has the right to use the crosswalk first.","h2":"A person in a crosswalk has the right of way, so you must stop and wait until the person has crossed.","p":"Right. Stop and let people in the crosswalk cross."},"es":{"q":"En Florida, una persona cruza la calle por el paso peatonal frente a usted. ¿Qué debe hacer?","o":["Parar y dejar que la persona cruce","Pasar despacio alrededor de la persona","Tocar la bocina para que se apure","Seguir si tiene luz verde"],"h1":"Piense en quién tiene primero el derecho de usar el paso peatonal.","h2":"Una persona en el paso peatonal tiene el derecho de paso, así que debe parar y esperar a que termine de cruzar.","p":"Correcto. Pare y deje cruzar a las personas en el paso peatonal."},"zh":{"q":"在 Florida，有一个人正在你前面的人行横道上过马路。你必须做什么？","o":["停车，让这个人过马路","慢慢绕过这个人","按喇叭让这个人快点走","如果是绿灯就继续开"],"h1":"想一想谁有权先使用人行横道。","h2":"在人行横道上的人有先行权，所以你必须停车，等这个人过完马路。","p":"对。停车，让人行横道上的人过马路。"},"vi":{"q":"Ở Florida, có một người đang đi bộ qua đường trên vạch qua đường trước mặt bạn. Bạn phải làm gì?","o":["Dừng lại và để người đó đi qua","Lái chậm vòng qua người đó","Bấm còi để người đó đi nhanh hơn","Cứ đi tiếp nếu bạn có đèn xanh"],"h1":"Hãy nghĩ xem ai có quyền dùng vạch qua đường trước.","h2":"Người đi trên vạch qua đường có quyền ưu tiên, nên bạn phải dừng lại và chờ đến khi người đó đi qua hết.","p":"Đúng. Dừng lại và để người trên vạch qua đường đi qua."},"tl":{"q":"Sa Florida, may taong tumatawid sa crosswalk sa harap mo. Ano ang dapat mong gawin?","o":["Huminto at hayaang tumawid ang tao","Dahan-dahang lumihis sa paligid ng tao","Bumusina para magmadali ang tao","Tumuloy kung green light ka"],"h1":"Isipin kung sino ang unang may karapatang gumamit ng crosswalk.","h2":"Ang taong nasa crosswalk ang may right of way, kaya dapat kang huminto at maghintay hanggang makatawid ang tao.","p":"Tama. Huminto at hayaang tumawid ang mga tao sa crosswalk."},"ar":{"q":"في Florida، شخص يعبر الشارع على ممر المشاة أمامك. ماذا يجب أن تفعل؟","o":["توقف واترك الشخص يعبر","قُد ببطء حول الشخص","استعمل البوق حتى يُسرع الشخص","تابع السير إذا كانت الإشارة خضراء لك"],"h1":"فكّر: من له الحق في استعمال ممر المشاة أولًا؟","h2":"الشخص الذي على ممر المشاة له حق الأولوية، لذلك يجب أن تتوقف وتنتظر حتى يعبر.","p":"صحيح. توقف واترك الناس على ممر المشاة يعبرون."},"ht":{"q":"Nan Florida, yon moun ap travèse lari a nan pasaj pyeton an devan w. Kisa ou dwe fè?","o":["Kanpe epi kite moun nan travèse","Kondi dousman bò kote moun nan","Klaksonen pou moun nan fè vit","Kontinye si limyè a vèt pou ou"],"h1":"Panse ak kiyès ki gen dwa sèvi ak pasaj pyeton an anvan.","h2":"Yon moun ki nan pasaj pyeton an gen priyorite, kidonk ou dwe kanpe epi tann jiskaske moun nan fin travèse.","p":"Se sa. Kanpe epi kite moun ki nan pasaj pyeton an travèse."},"ref":{"doc":"FL","page":87}},{"id":"safe-driving-005","scope":"FL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Florida, a person with a white cane or a guide dog is starting to cross the street. What should you do?","o":["Honk to warn the person","Drive around the person slowly","Stop and wait until the person crosses","Wave the person back to the curb"],"h1":"Think about a person who may not be able to see your car.","h2":"A white cane or a guide dog shows that the person may be blind, so you must stop and wait until the person is safely across.","p":"Right. Stop for a person with a white cane or a guide dog."},"es":{"q":"En Florida, una persona con un bastón blanco o un perro guía empieza a cruzar la calle. ¿Qué debe hacer?","o":["Tocar la bocina para avisarle","Pasar despacio alrededor de la persona","Parar y esperar a que la persona cruce","Hacerle señas para que vuelva a la acera"],"h1":"Piense en una persona que tal vez no puede ver su carro.","h2":"Un bastón blanco o un perro guía indica que la persona puede ser ciega, así que debe parar y esperar a que cruce con seguridad.","p":"Correcto. Pare para una persona con bastón blanco o perro guía."},"zh":{"q":"在 Florida，一个拿着白色手杖或带着导盲犬的人正要过马路。你应该怎么做？","o":["按喇叭提醒这个人","慢慢绕过这个人","停车，等这个人过完马路","挥手让这个人回到路边"],"h1":"想一想一个可能看不到你车的人。","h2":"白色手杖或导盲犬表示这个人可能看不见，所以你必须停车，等这个人安全过完马路。","p":"对。为拿白色手杖或带导盲犬的人停车。"},"vi":{"q":"Ở Florida, một người cầm gậy trắng hoặc đi cùng chó dẫn đường đang bắt đầu qua đường. Bạn nên làm gì?","o":["Bấm còi để báo cho người đó","Lái chậm vòng qua người đó","Dừng lại và chờ đến khi người đó qua hết đường","Vẫy tay bảo người đó quay lại lề đường"],"h1":"Hãy nghĩ đến một người có thể không nhìn thấy xe bạn.","h2":"Gậy trắng hoặc chó dẫn đường cho thấy người đó có thể bị mù, nên bạn phải dừng lại và chờ đến khi người đó qua đường an toàn.","p":"Đúng. Dừng lại cho người cầm gậy trắng hoặc đi cùng chó dẫn đường."},"tl":{"q":"Sa Florida, ang taong may puting tungkod o guide dog ay nagsisimulang tumawid sa kalye. Ano ang dapat mong gawin?","o":["Bumusina para bigyan ng babala ang tao","Dahan-dahang lumihis sa paligid ng tao","Huminto at maghintay hanggang makatawid ang tao","Senyasan ang tao na bumalik sa gilid ng kalsada"],"h1":"Isipin ang taong maaaring hindi nakakakita sa kotse mo.","h2":"Ang puting tungkod o guide dog ay nagpapakitang maaaring bulag ang tao, kaya dapat kang huminto at maghintay hanggang ligtas na siyang nakatawid.","p":"Tama. Huminto para sa taong may puting tungkod o guide dog."},"ar":{"q":"في Florida، شخص معه عصا بيضاء أو كلب مرشد يبدأ بعبور الشارع. ماذا يجب أن تفعل؟","o":["استعمل البوق لتحذّر الشخص","قُد ببطء حول الشخص","توقف وانتظر حتى يعبر الشخص","أشِر إلى الشخص ليعود إلى الرصيف"],"h1":"فكّر في شخص قد لا يستطيع أن يرى سيارتك.","h2":"العصا البيضاء أو الكلب المرشد تدل على أن الشخص قد يكون كفيفًا، لذلك يجب أن تتوقف وتنتظر حتى يعبر بأمان.","p":"صحيح. توقف لشخص معه عصا بيضاء أو كلب مرشد."},"ht":{"q":"Nan Florida, yon moun ki gen yon baton blan oswa yon chen gid ap kòmanse travèse lari a. Kisa ou ta dwe fè?","o":["Klaksonen pou avèti moun nan","Kondi dousman bò kote moun nan","Kanpe epi tann jiskaske moun nan fin travèse","Fè moun nan siy pou l retounen sou twotwa a"],"h1":"Panse ak yon moun ki ka pa ka wè machin ou.","h2":"Yon baton blan oswa yon chen gid montre ke moun nan ka avèg, kidonk ou dwe kanpe epi tann jiskaske moun nan fin travèse san danje.","p":"Se sa. Kanpe pou yon moun ki gen yon baton blan oswa yon chen gid."},"ref":{"doc":"FL","page":88}},{"id":"safe-driving-006","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Why should you look twice for motorcycles before you turn or change lanes?","o":["Motorcycles must always use the right lane","Motorcycles are small and easy to miss","Motorcycles cannot use turn signals","Motorcycles always drive faster than cars"],"h1":"Think about how big a motorcycle looks next to a car.","h2":"A motorcycle is much smaller than a car, so it can hide in a blind spot or be easy to miss, and you should look twice.","p":"Right. Motorcycles are small and easy to miss, so look twice."},"es":{"q":"¿Por qué debe mirar dos veces por motocicletas antes de girar o cambiar de carril?","o":["Las motos siempre deben ir por la derecha","Las motos son pequeñas y fáciles de no ver","Las motos no pueden usar direccionales","Las motos siempre van más rápido que los carros"],"h1":"Piense en el tamaño de una moto al lado de un carro.","h2":"Una motocicleta es mucho más pequeña que un carro, así que puede esconderse en un punto ciego o pasar desapercibida, y debe mirar dos veces.","p":"Correcto. Las motos son pequeñas y fáciles de no ver; mire dos veces."},"zh":{"q":"为什么你在转弯或换车道前，应该看两次有没有摩托车？","o":["摩托车必须一直走右边车道","摩托车很小，很容易看漏","摩托车不能用转向灯","摩托车总是比汽车开得快"],"h1":"想一想摩托车在汽车旁边看起来有多大。","h2":"摩托车比汽车小很多，所以它可能藏在盲区里，或很容易被看漏，你应该看两次。","p":"对。摩托车很小，很容易看漏，所以要看两次。"},"vi":{"q":"Tại sao bạn nên nhìn hai lần để tìm xe máy trước khi rẽ hoặc đổi làn?","o":["Xe máy luôn phải đi làn bên phải","Xe máy nhỏ và dễ bị bỏ sót","Xe máy không thể dùng đèn xi-nhan","Xe máy luôn chạy nhanh hơn xe hơi"],"h1":"Hãy nghĩ xem một chiếc xe máy trông lớn cỡ nào khi ở cạnh xe hơi.","h2":"Xe máy nhỏ hơn xe hơi rất nhiều, nên nó có thể bị che trong điểm mù hoặc dễ bị bỏ sót, và bạn nên nhìn hai lần.","p":"Đúng. Xe máy nhỏ và dễ bị bỏ sót, nên hãy nhìn hai lần."},"tl":{"q":"Bakit dapat kang tumingin nang dalawang beses para sa motorsiklo bago kumanan o kumaliwa, o lumipat ng lane?","o":["Dapat laging gumamit ng kanang lane ang mga motorsiklo","Maliit ang mga motorsiklo at madaling hindi mapansin","Hindi puwedeng gumamit ng signal light ang mga motorsiklo","Laging mas mabilis ang mga motorsiklo kaysa sa mga kotse"],"h1":"Isipin kung gaano kalaki ang tingin sa motorsiklo kapag katabi ng kotse.","h2":"Mas maliit nang husto ang motorsiklo kaysa sa kotse, kaya puwede itong matago sa blind spot o madaling hindi mapansin, at dapat kang tumingin nang dalawang beses.","p":"Tama. Maliit ang mga motorsiklo at madaling hindi mapansin, kaya tumingin nang dalawang beses."},"ar":{"q":"لماذا يجب أن تنظر مرتين بحثًا عن الدراجات النارية قبل أن تنعطف أو تغيّر المسار؟","o":["الدراجات النارية يجب أن تستعمل المسار الأيمن دائمًا","الدراجات النارية صغيرة ومن السهل ألا تراها","الدراجات النارية لا تستطيع استعمال إشارات الانعطاف","الدراجات النارية تسير دائمًا أسرع من السيارات"],"h1":"فكّر في حجم الدراجة النارية بجانب السيارة.","h2":"الدراجة النارية أصغر بكثير من السيارة، لذلك قد تختفي في النقطة العمياء أو من السهل ألا تراها، ويجب أن تنظر مرتين.","p":"صحيح. الدراجات النارية صغيرة ومن السهل ألا تراها، لذلك انظر مرتين."},"ht":{"q":"Poukisa ou ta dwe gade de fwa pou motosiklèt anvan ou vire oswa chanje liy?","o":["Motosiklèt yo dwe toujou sèvi ak liy dwat la","Motosiklèt yo piti epi li fasil pou w pa wè yo","Motosiklèt yo pa ka sèvi ak siyal pou vire","Motosiklèt yo toujou kondi pi vit pase machin"],"h1":"Panse ak gwosè yon motosiklèt bò kote yon machin.","h2":"Yon motosiklèt pi piti anpil pase yon machin, kidonk li ka kache nan yon kote ou pa ka wè (blind spot) oswa li fasil pou w pa wè l, epi ou ta dwe gade de fwa.","p":"Se sa. Motosiklèt yo piti epi li fasil pou w pa wè yo, kidonk gade de fwa."},"ref":{"doc":"FL","page":85}},{"id":"safe-driving-007","scope":"FL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Florida, may you share a lane side by side with a motorcycle?","o":["Yes, if the motorcycle is slow","Yes, on any multi-lane road","Yes, if you signal first","No, a motorcycle gets the full lane"],"h1":"Think about how much room a motorcycle needs to move safely.","h2":"In Florida a motorcycle has the right to use the full width of a lane, so you may not drive next to it in the same lane.","p":"Right. A motorcycle gets the full lane, so do not share it."},"es":{"q":"En Florida, ¿puede compartir un carril lado a lado con una motocicleta?","o":["Sí, si la moto va despacio","Sí, en cualquier vía de varios carriles","Sí, si pone la direccional antes","No, la moto tiene derecho a todo el carril"],"h1":"Piense en cuánto espacio necesita una moto para moverse con seguridad.","h2":"En Florida una motocicleta tiene derecho a usar todo el ancho del carril, así que usted no puede manejar a su lado en el mismo carril.","p":"Correcto. La moto tiene derecho a todo el carril; no lo comparta."},"zh":{"q":"在 Florida，你可以和摩托车在同一条车道上并排行驶吗？","o":["可以，如果摩托车开得慢","可以，在任何多车道的路上","可以，如果你先打转向灯","不可以，摩托车可以使用整条车道"],"h1":"想一想摩托车需要多少空间才能安全行驶。","h2":"在 Florida，摩托车有权使用整条车道的宽度，所以你不能在同一条车道上开在它旁边。","p":"对。摩托车可以使用整条车道，所以不要和它共用。"},"vi":{"q":"Ở Florida, bạn có được chạy song song với xe máy trong cùng một làn không?","o":["Có, nếu xe máy chạy chậm","Có, trên bất kỳ đường nhiều làn nào","Có, nếu bạn bật xi-nhan trước","Không, xe máy được dùng trọn cả làn"],"h1":"Hãy nghĩ xem xe máy cần bao nhiêu chỗ để di chuyển an toàn.","h2":"Ở Florida, xe máy có quyền dùng toàn bộ chiều rộng của một làn, nên bạn không được chạy cạnh xe máy trong cùng một làn.","p":"Đúng. Xe máy được dùng trọn cả làn, nên đừng chạy chung làn."},"tl":{"q":"Sa Florida, puwede ka bang makihati ng lane nang magkatabi sa isang motorsiklo?","o":["Oo, kung mabagal ang motorsiklo","Oo, sa kahit anong daan na maraming lane","Oo, kung mag-signal ka muna","Hindi, sa motorsiklo ang buong lane"],"h1":"Isipin kung gaano kalaking espasyo ang kailangan ng motorsiklo para umandar nang ligtas.","h2":"Sa Florida, may karapatan ang motorsiklo na gamitin ang buong lapad ng lane, kaya hindi ka puwedeng magmaneho sa tabi nito sa parehong lane.","p":"Tama. Sa motorsiklo ang buong lane, kaya huwag makihati rito."},"ar":{"q":"في Florida، هل يُسمح لك بأن تسير جنبًا إلى جنب مع دراجة نارية في نفس المسار؟","o":["نعم، إذا كانت الدراجة النارية بطيئة","نعم، على أي طريق فيه عدة مسارات","نعم، إذا استعملت الإشارة أولًا","لا، الدراجة النارية لها المسار كله"],"h1":"فكّر في المساحة التي تحتاجها الدراجة النارية لتتحرك بأمان.","h2":"في Florida، للدراجة النارية الحق في استعمال عرض المسار كله، لذلك لا يُسمح لك بالقيادة بجانبها في نفس المسار.","p":"صحيح. الدراجة النارية لها المسار كله، فلا تشاركها فيه."},"ht":{"q":"Nan Florida, èske ou ka pataje yon liy ak yon motosiklèt, kòt a kòt?","o":["Wi, si motosiklèt la ap mache dousman","Wi, sou nenpòt wout ki gen plizyè liy","Wi, si ou bay siyal anvan","Non, yon motosiklèt gen dwa sou tout liy lan"],"h1":"Panse ak konbyen espas yon motosiklèt bezwen pou l deplase san danje.","h2":"Nan Florida, yon motosiklèt gen dwa sèvi ak tout lajè yon liy, kidonk ou pa gen dwa kondi bò kote l nan menm liy lan.","p":"Se sa. Yon motosiklèt gen dwa sou tout liy lan, kidonk pa pataje l."},"ref":{"doc":"FL","page":85}},{"id":"safe-driving-008","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"You are driving next to a large truck. You cannot see the driver's face in the truck's side mirror. What does this mean?","o":["The driver probably cannot see you","The driver is not paying attention","The mirror is broken","You are at a safe distance"],"h1":"Think about how mirrors work in both directions.","h2":"If you cannot see the truck driver in the mirror, the driver cannot see you either, so you are in a blind spot and should move out of it.","p":"Right. If you cannot see the driver in the mirror, the driver cannot see you."},"es":{"q":"Usted maneja al lado de un camión grande. No puede ver la cara del chofer en el espejo lateral del camión. ¿Qué significa?","o":["El chofer probablemente no lo ve a usted","El chofer no está prestando atención","El espejo está roto","Usted está a una distancia segura"],"h1":"Piense en cómo funcionan los espejos en las dos direcciones.","h2":"Si usted no ve al chofer en el espejo, el chofer tampoco lo ve a usted, así que está en un punto ciego y debe salir de ahí.","p":"Correcto. Si no ve al chofer en el espejo, él no lo ve a usted."},"zh":{"q":"你开在一辆大卡车旁边。你在卡车的侧后视镜里看不到司机的脸。这是什么意思？","o":["司机很可能看不到你","司机没有注意","后视镜坏了","你在安全的距离"],"h1":"想一想镜子是两个方向都能看到的。","h2":"如果你在镜子里看不到卡车司机，司机也看不到你，所以你在盲区里，应该离开那里。","p":"对。如果你在镜子里看不到司机，司机也看不到你。"},"vi":{"q":"Bạn đang lái xe cạnh một xe tải lớn. Bạn không nhìn thấy mặt tài xế trong gương chiếu hậu bên hông của xe tải. Điều này có nghĩa là gì?","o":["Có lẽ tài xế không nhìn thấy bạn","Tài xế không chú ý","Gương bị hỏng","Bạn đang ở khoảng cách an toàn"],"h1":"Hãy nghĩ xem gương hoạt động theo cả hai chiều như thế nào.","h2":"Nếu bạn không nhìn thấy tài xế xe tải trong gương, thì tài xế cũng không nhìn thấy bạn, nên bạn đang ở điểm mù và nên ra khỏi đó.","p":"Đúng. Nếu bạn không thấy tài xế trong gương, tài xế cũng không thấy bạn."},"tl":{"q":"Nagmamaneho ka sa tabi ng malaking truck. Hindi mo makita ang mukha ng driver sa side mirror ng truck. Ano ang ibig sabihin nito?","o":["Malamang hindi ka rin nakikita ng driver","Hindi nag-iingat ang driver","Sira ang salamin","Nasa ligtas na layo ka"],"h1":"Isipin kung paano gumagana ang salamin sa magkabilang direksyon.","h2":"Kung hindi mo makita ang truck driver sa salamin, hindi ka rin niya nakikita, kaya nasa blind spot ka at dapat kang umalis doon.","p":"Tama. Kung hindi mo makita ang driver sa salamin, hindi ka rin nakikita ng driver."},"ar":{"q":"أنت تقود بجانب شاحنة كبيرة. لا تستطيع أن ترى وجه السائق في المرآة الجانبية للشاحنة. ماذا يعني هذا؟","o":["السائق على الأغلب لا يستطيع أن يراك","السائق لا ينتبه","المرآة مكسورة","أنت على مسافة آمنة"],"h1":"فكّر في أن المرايا تعمل في الاتجاهين.","h2":"إذا لم تستطع أن ترى سائق الشاحنة في المرآة، فالسائق أيضًا لا يستطيع أن يراك، لذلك أنت في النقطة العمياء ويجب أن تخرج منها.","p":"صحيح. إذا لم ترَ السائق في المرآة، فالسائق لا يراك."},"ht":{"q":"W ap kondi bò kote yon gwo kamyon. Ou pa ka wè figi chofè a nan retwovizè bò kamyon an. Kisa sa vle di?","o":["Chofè a pwobableman pa ka wè w","Chofè a pa fè atansyon","Retwovizè a kase","Ou nan yon distans ki an sekirite"],"h1":"Panse ak jan retwovizè yo mache nan de direksyon.","h2":"Si ou pa ka wè chofè kamyon an nan retwovizè a, chofè a pa ka wè w nonplis, kidonk ou nan yon kote li pa ka wè (blind spot) epi ou ta dwe soti la.","p":"Se sa. Si ou pa ka wè chofè a nan retwovizè a, chofè a pa ka wè w."},"ref":{"doc":"FL","page":82}},{"id":"safe-driving-009","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"A large truck ahead has its right turn signal on. It moves a little to the left first. What should you do?","o":["Pass it on the right side","Honk to tell the driver to hurry","Stay back and wait for it to turn","Move up close behind the truck"],"h1":"Think about how much room a long truck needs to turn a corner.","h2":"Large trucks often swing left to make a wide right turn, so you should stay back and never squeeze in between the truck and the curb.","p":"Right. Stay back and let the truck make its wide right turn."},"es":{"q":"Un camión grande adelante tiene puesta la direccional derecha. Primero se mueve un poco a la izquierda. ¿Qué debe hacer?","o":["Rebasarlo por el lado derecho","Tocar la bocina para que se apure","Quedarse atrás y esperar a que gire","Acercarse mucho detrás del camión"],"h1":"Piense en cuánto espacio necesita un camión largo para doblar una esquina.","h2":"Los camiones grandes a menudo se abren a la izquierda para hacer un giro amplio a la derecha, así que debe quedarse atrás y nunca meterse entre el camión y la acera.","p":"Correcto. Quédese atrás y deje que el camión haga su giro amplio."},"zh":{"q":"前面一辆大卡车打开了右转向灯。它先稍微往左移动。你应该怎么做？","o":["从它右边超过去","按喇叭让司机快点","留在后面，等它转弯","开到卡车后面很近的地方"],"h1":"想一想长卡车转过一个路口需要多少空间。","h2":"大卡车常常先往左摆，才能大弯右转，所以你应该留在后面，绝不要挤进卡车和路边之间。","p":"对。留在后面，让卡车大弯右转。"},"vi":{"q":"Một xe tải lớn phía trước đang bật xi-nhan phải. Nó lấn sang trái một chút trước. Bạn nên làm gì?","o":["Vượt qua nó ở bên phải","Bấm còi giục tài xế nhanh lên","Lùi lại phía sau và chờ nó rẽ","Chạy sát lên phía sau xe tải"],"h1":"Hãy nghĩ xem một xe tải dài cần bao nhiêu chỗ để rẽ ở góc đường.","h2":"Xe tải lớn thường lấn sang trái để rẽ phải một vòng rộng, nên bạn nên lùi lại phía sau và không bao giờ chen vào giữa xe tải và lề đường.","p":"Đúng. Lùi lại phía sau và để xe tải rẽ phải một vòng rộng."},"tl":{"q":"Ang malaking truck sa unahan ay naka-signal pakanan. Kumikilos muna ito nang kaunti pakaliwa. Ano ang dapat mong gawin?","o":["Lampasan ito sa kanang bahagi","Bumusina para magmadali ang driver","Manatili sa likod at hintayin itong kumanan","Lumapit nang husto sa likod ng truck"],"h1":"Isipin kung gaano kalaking espasyo ang kailangan ng mahabang truck para lumiko sa kanto.","h2":"Madalas lumihis pakaliwa ang malalaking truck para makagawa ng malapad na pagkanan, kaya dapat kang manatili sa likod at huwag kailanman sumingit sa pagitan ng truck at ng gilid ng kalsada.","p":"Tama. Manatili sa likod at hayaang gawin ng truck ang malapad nitong pagkanan."},"ar":{"q":"شاحنة كبيرة أمامك شغّلت إشارة الانعطاف اليمنى. لكنها تتحرك قليلًا إلى اليسار أولًا. ماذا يجب أن تفعل؟","o":["تجاوزها من الجهة اليمنى","استعمل البوق لتقول للسائق أن يُسرع","ابقَ في الخلف وانتظر حتى تنعطف","اقترب كثيرًا خلف الشاحنة"],"h1":"فكّر في المساحة التي تحتاجها شاحنة طويلة لتنعطف عند الزاوية.","h2":"الشاحنات الكبيرة تميل غالبًا إلى اليسار لتنعطف يمينًا انعطافًا واسعًا، لذلك يجب أن تبقى في الخلف ولا تدخل أبدًا بين الشاحنة والرصيف.","p":"صحيح. ابقَ في الخلف واترك الشاحنة تنعطف يمينًا انعطافها الواسع."},"ht":{"q":"Yon gwo kamyon devan w limen siyal pou vire adwat. Li deplase yon ti kras agoch anvan. Kisa ou ta dwe fè?","o":["Pase l sou bò dwat la","Klaksonen pou di chofè a fè vit","Rete dèyè epi tann li vire","Vin kole dèyè kamyon an"],"h1":"Panse ak konbyen espas yon kamyon long bezwen pou l vire nan yon kwen.","h2":"Gwo kamyon yo souvan ale agoch pou yo ka fè yon gwo vire adwat, kidonk ou ta dwe rete dèyè epi pa janm foure kò w ant kamyon an ak bò twotwa a.","p":"Se sa. Rete dèyè epi kite kamyon an fè gwo vire adwat li."},"ref":{"doc":"FL","page":83}},{"id":"safe-driving-010","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"You just passed a large truck. When should you move back in front of it?","o":["Right away, as soon as you pass its bumper","When you can see the whole truck front in your mirror","After you slow down a little","Only after the truck flashes its lights"],"h1":"Think about how long it takes a heavy truck to stop.","h2":"A heavy truck needs a long distance to stop, so you should wait until you can see its whole front in your rearview mirror before you move in.","p":"Right. Move in only when you can see the whole truck front in your mirror."},"es":{"q":"Usted acaba de rebasar un camión grande. ¿Cuándo debe volver a ponerse delante de él?","o":["De inmediato, al pasar su parachoques","Cuando vea todo el frente del camión en su espejo","Después de bajar un poco la velocidad","Solo cuando el camión le haga cambio de luces"],"h1":"Piense en cuánto le toma a un camión pesado frenar.","h2":"Un camión pesado necesita mucha distancia para frenar, así que debe esperar hasta ver todo su frente en el espejo retrovisor antes de ponerse delante.","p":"Correcto. Póngase delante solo cuando vea todo el frente del camión en el espejo."},"zh":{"q":"你刚超过一辆大卡车。什么时候可以回到它前面？","o":["马上，一超过它的保险杠就回去","当你在后视镜里能看到整个卡车车头时","在你稍微减速以后","只在卡车闪灯以后"],"h1":"想一想重型卡车需要多久才能停下来。","h2":"重型卡车需要很长的距离才能停下来，所以你应该等到在车内后视镜里能看到它整个车头，再回到它前面。","p":"对。只有在后视镜里能看到整个卡车车头时才回到前面。"},"vi":{"q":"Bạn vừa vượt qua một xe tải lớn. Khi nào bạn nên quay lại làn phía trước nó?","o":["Ngay lập tức, khi vừa qua khỏi cản xe của nó","Khi bạn nhìn thấy toàn bộ đầu xe tải trong gương","Sau khi bạn giảm tốc một chút","Chỉ sau khi xe tải nháy đèn"],"h1":"Hãy nghĩ xem một xe tải nặng cần bao lâu để dừng lại.","h2":"Xe tải nặng cần một quãng đường dài để dừng lại, nên bạn nên chờ đến khi nhìn thấy toàn bộ đầu xe tải trong gương chiếu hậu rồi mới quay vào làn.","p":"Đúng. Chỉ quay vào làn khi bạn nhìn thấy toàn bộ đầu xe tải trong gương."},"tl":{"q":"Kalalampas mo lang sa isang malaking truck. Kailan ka dapat bumalik sa harap nito?","o":["Agad-agad, pagkalampas mo sa bumper nito","Kapag nakikita mo na ang buong harap ng truck sa salamin mo","Pagkatapos mong bumagal nang kaunti","Pagkatapos lang mag-flash ng ilaw ang truck"],"h1":"Isipin kung gaano katagal bago makahinto ang mabigat na truck.","h2":"Kailangan ng mabigat na truck ng mahabang distansya para huminto, kaya dapat kang maghintay hanggang makita mo ang buong harap nito sa iyong rearview mirror bago ka bumalik sa lane.","p":"Tama. Bumalik lang sa lane kapag nakikita mo na ang buong harap ng truck sa salamin mo."},"ar":{"q":"تجاوزت شاحنة كبيرة الآن. متى يجب أن تعود إلى المسار أمامها؟","o":["فورًا، بمجرد أن تتجاوز مقدمتها","عندما ترى مقدمة الشاحنة كلها في مرآتك","بعد أن تخفف سرعتك قليلًا","فقط بعد أن تومض الشاحنة بأضوائها"],"h1":"فكّر في الوقت الذي تحتاجه الشاحنة الثقيلة لتتوقف.","h2":"الشاحنة الثقيلة تحتاج إلى مسافة طويلة لتتوقف، لذلك يجب أن تنتظر حتى ترى مقدمتها كلها في المرآة الداخلية قبل أن تدخل أمامها.","p":"صحيح. ادخل أمامها فقط عندما ترى مقدمة الشاحنة كلها في مرآتك."},"ht":{"q":"Ou fèk pase yon gwo kamyon. Ki lè ou ta dwe retounen devan l?","o":["Touswit, depi ou pase defans li","Lè ou ka wè tout devan kamyon an nan retwovizè ou","Apre ou ralanti yon ti kras","Sèlman apre kamyon an limen limyè li plizyè fwa"],"h1":"Panse ak konbyen tan yon kamyon lou pran pou l kanpe.","h2":"Yon kamyon lou bezwen yon long distans pou l kanpe, kidonk ou ta dwe tann jiskaske ou ka wè tout devan l nan retwovizè mitan an anvan ou retounen devan l.","p":"Se sa. Retounen devan l sèlman lè ou ka wè tout devan kamyon an nan retwovizè ou."},"ref":{"doc":"FL","page":83}},{"id":"safe-driving-011","scope":"FL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Florida, a school bus on a two-lane road stops. Its red lights flash and its stop arm is out. You are coming from the other direction. What must you do?","o":["Slow down and pass with care","Keep going because you are on the other side","Honk and then pass slowly","Stop and wait until the stop arm is pulled in"],"h1":"Think about children who may cross the road to reach the bus.","h2":"On a road without a divider, drivers in both directions must stop for a school bus with its stop arm out, and wait until the arm is pulled back in.","p":"Right. Stop for the school bus, even from the other direction."},"es":{"q":"En Florida, un autobús escolar para en una carretera de dos carriles. Sus luces rojas parpadean y tiene el brazo de pare afuera. Usted viene en dirección contraria. ¿Qué debe hacer?","o":["Bajar la velocidad y pasar con cuidado","Seguir porque va del otro lado","Tocar la bocina y pasar despacio","Parar y esperar a que recojan el brazo de pare"],"h1":"Piense en los niños que pueden cruzar la calle para llegar al autobús.","h2":"En una vía sin división, los conductores de las dos direcciones deben parar ante un autobús escolar con el brazo de pare afuera, y esperar hasta que lo recojan.","p":"Correcto. Pare ante el autobús escolar, aunque venga en dirección contraria."},"zh":{"q":"在 Florida，一辆校车在双车道的路上停下。它的红灯在闪，停车臂也伸出来了。你从对面方向开过来。你必须做什么？","o":["减速，小心地开过去","继续开，因为你在另一边","按喇叭，然后慢慢开过去","停车，等到停车臂收回去"],"h1":"想一想孩子们可能会过马路去坐校车。","h2":"在没有隔离带的路上，两个方向的司机都必须为伸出停车臂的校车停车，并等到停车臂收回去。","p":"对。即使你从对面方向来，也要为校车停车。"},"vi":{"q":"Ở Florida, một xe buýt trường học dừng lại trên đường hai làn. Đèn đỏ nhấp nháy và tay chắn STOP đang mở ra. Bạn đang đi từ hướng ngược lại. Bạn phải làm gì?","o":["Giảm tốc và cẩn thận vượt qua","Cứ đi tiếp vì bạn ở phía bên kia","Bấm còi rồi chạy chậm qua","Dừng lại và chờ đến khi tay chắn STOP được thu vào"],"h1":"Hãy nghĩ đến trẻ em có thể băng qua đường để lên xe buýt.","h2":"Trên đường không có dải phân cách, tài xế ở cả hai chiều phải dừng lại khi xe buýt trường học mở tay chắn STOP, và chờ đến khi tay chắn được thu vào.","p":"Đúng. Dừng lại cho xe buýt trường học, dù bạn đi từ hướng ngược lại."},"tl":{"q":"Sa Florida, huminto ang school bus sa daang may dalawang lane. Kumikislap ang pulang ilaw nito at nakalabas ang stop arm. Galing ka sa kabilang direksyon. Ano ang dapat mong gawin?","o":["Bumagal at lumampas nang maingat","Tumuloy dahil nasa kabilang bahagi ka","Bumusina at saka lumampas nang dahan-dahan","Huminto at maghintay hanggang maibalik ang stop arm"],"h1":"Isipin ang mga batang maaaring tumawid sa daan para makarating sa bus.","h2":"Sa daang walang divider, dapat huminto ang mga driver sa magkabilang direksyon para sa school bus na nakalabas ang stop arm, at maghintay hanggang maibalik ang arm.","p":"Tama. Huminto para sa school bus, kahit galing ka sa kabilang direksyon."},"ar":{"q":"في Florida، حافلة مدرسية تتوقف على طريق فيه مساران. أضواؤها الحمراء تومض وذراع التوقف مفتوح. أنت قادم من الاتجاه الآخر. ماذا يجب أن تفعل؟","o":["خفّف السرعة وتجاوزها بحذر","تابع السير لأنك في الجهة الأخرى","استعمل البوق ثم تجاوز ببطء","توقف وانتظر حتى يُغلق ذراع التوقف"],"h1":"فكّر في الأطفال الذين قد يعبرون الطريق ليصلوا إلى الحافلة.","h2":"على طريق بدون فاصل، يجب على السائقين في الاتجاهين أن يتوقفوا للحافلة المدرسية عندما يكون ذراع التوقف مفتوحًا، وأن ينتظروا حتى يُغلق الذراع.","p":"صحيح. توقف للحافلة المدرسية، حتى إذا كنت في الاتجاه الآخر."},"ht":{"q":"Nan Florida, yon bis lekòl kanpe sou yon wout ki gen de liy. Limyè wouj li yo ap flache epi bra STOP li a louvri. W ap vini nan lòt direksyon an. Kisa ou dwe fè?","o":["Ralanti epi pase ak prekosyon","Kontinye paske ou sou lòt bò a","Klaksonen epi pase dousman","Kanpe epi tann jiskaske yo rantre bra STOP la"],"h1":"Panse ak timoun ki ka travèse wout la pou yo rive nan bis la.","h2":"Sou yon wout ki pa gen separasyon nan mitan, chofè nan tou de direksyon yo dwe kanpe pou yon bis lekòl ki gen bra STOP li louvri, epi tann jiskaske yo rantre bra a.","p":"Se sa. Kanpe pou bis lekòl la, menm si w ap vini nan lòt direksyon an."},"ref":{"doc":"FL","page":89}},{"id":"safe-driving-012","scope":"FL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Florida, you are on a divided highway with a raised median. A school bus stops on the other side of the median. What should you do?","o":["You do not have to stop, but drive with care","Stop until the bus drives away","Stop, then pass at walking speed","Change to the lane closest to the bus"],"h1":"Think about what the raised median does between you and the bus.","h2":"When a raised barrier or wide median separates you from the bus, you do not have to stop, but you should still watch for children.","p":"Right. With a raised median between you, you do not have to stop, but stay alert."},"es":{"q":"En Florida, usted va por una carretera dividida con una mediana elevada. Un autobús escolar para del otro lado de la mediana. ¿Qué debe hacer?","o":["No tiene que parar, pero maneje con cuidado","Parar hasta que el autobús se vaya","Parar y luego pasar muy despacio","Cambiarse al carril más cerca del autobús"],"h1":"Piense en lo que hace la mediana elevada entre usted y el autobús.","h2":"Cuando una barrera elevada o una mediana ancha lo separa del autobús, no tiene que parar, pero debe seguir atento a los niños.","p":"Correcto. Con una mediana elevada entre ustedes, no tiene que parar, pero esté atento."},"zh":{"q":"在 Florida，你在一条有凸起中央隔离带的分隔公路上。一辆校车在隔离带的另一边停下。你应该怎么做？","o":["你不必停车，但要小心开","停车，直到校车开走","停车，然后用走路的速度开过去","换到离校车最近的车道"],"h1":"想一想凸起的隔离带在你和校车之间起了什么作用。","h2":"当凸起的护栏或很宽的中央隔离带把你和校车分开时，你不必停车，但仍然要注意孩子。","p":"对。你们之间有凸起的隔离带时，你不必停车，但要保持警觉。"},"vi":{"q":"Ở Florida, bạn đang đi trên xa lộ có dải phân cách nhô cao ở giữa. Một xe buýt trường học dừng lại ở phía bên kia dải phân cách. Bạn nên làm gì?","o":["Bạn không phải dừng lại, nhưng hãy lái cẩn thận","Dừng lại đến khi xe buýt chạy đi","Dừng lại, rồi vượt qua với tốc độ đi bộ","Chuyển sang làn gần xe buýt nhất"],"h1":"Hãy nghĩ xem dải phân cách nhô cao có tác dụng gì giữa bạn và xe buýt.","h2":"Khi có rào chắn nhô cao hoặc dải phân cách rộng ngăn cách bạn với xe buýt, bạn không phải dừng lại, nhưng vẫn nên để ý trẻ em.","p":"Đúng. Khi có dải phân cách nhô cao ở giữa, bạn không phải dừng lại, nhưng hãy luôn cảnh giác."},"tl":{"q":"Sa Florida, nasa divided highway ka na may nakataas na median. Huminto ang school bus sa kabilang bahagi ng median. Ano ang dapat mong gawin?","o":["Hindi mo kailangang huminto, pero magmaneho nang maingat","Huminto hanggang umalis ang bus","Huminto, saka lumampas sa bilis ng paglalakad","Lumipat sa lane na pinakamalapit sa bus"],"h1":"Isipin kung ano ang ginagawa ng nakataas na median sa pagitan mo at ng bus.","h2":"Kapag may nakataas na harang o malapad na median sa pagitan mo at ng bus, hindi mo kailangang huminto, pero dapat ka pa ring magbantay sa mga bata.","p":"Tama. Kapag may nakataas na median sa pagitan ninyo, hindi mo kailangang huminto, pero manatiling alerto."},"ar":{"q":"في Florida، أنت على طريق سريع مقسوم بجزيرة وسطية مرتفعة. حافلة مدرسية تتوقف في الجهة الأخرى من الجزيرة. ماذا يجب أن تفعل؟","o":["ليس عليك أن تتوقف، لكن قُد بحذر","توقف حتى تذهب الحافلة","توقف، ثم تجاوز بسرعة المشي","انتقل إلى المسار الأقرب إلى الحافلة"],"h1":"فكّر في ما تفعله الجزيرة المرتفعة بينك وبين الحافلة.","h2":"عندما يفصلك حاجز مرتفع أو جزيرة وسطية عريضة عن الحافلة، ليس عليك أن تتوقف، لكن يجب أن تنتبه للأطفال.","p":"صحيح. مع جزيرة مرتفعة بينكما، ليس عليك أن تتوقف، لكن ابقَ منتبهًا."},"ht":{"q":"Nan Florida, ou sou yon otowout ki gen yon separasyon wo nan mitan an. Yon bis lekòl kanpe sou lòt bò separasyon an. Kisa ou ta dwe fè?","o":["Ou pa oblije kanpe, men kondi ak prekosyon","Kanpe jiskaske bis la ale","Kanpe, epi pase menm vitès ak yon moun k ap mache","Ale nan liy ki pi pre bis la"],"h1":"Panse ak sa separasyon wo a fè ant ou menm ak bis la.","h2":"Lè yon separasyon wo oswa yon separasyon ki laj nan mitan wout la separe w ak bis la, ou pa oblije kanpe, men ou ta dwe toujou veye timoun yo.","p":"Se sa. Avèk yon separasyon wo ant nou, ou pa oblije kanpe, men rete veyatif."},"ref":{"doc":"FL","page":89}},{"id":"safe-driving-013","scope":"FL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Florida, what is the rule for holding a phone while driving in an active school zone?","o":["You may hold it for short calls","You may hold it if you drive slowly","You may not hold it; hands-free only","You may hold it only at a red light"],"h1":"Think about the extra danger near schools when children are present.","h2":"In Florida you may not hold a phone while driving in an active school zone, so you may only use it hands-free.","p":"Right. In an active school zone, no handheld phone, hands-free only."},"es":{"q":"En Florida, ¿cuál es la regla para sostener el teléfono mientras maneja en una zona escolar activa?","o":["Puede sostenerlo para llamadas cortas","Puede sostenerlo si maneja despacio","No puede sostenerlo; solo manos libres","Puede sostenerlo solo en luz roja"],"h1":"Piense en el peligro extra cerca de las escuelas cuando hay niños.","h2":"En Florida no puede sostener el teléfono mientras maneja en una zona escolar activa, así que solo puede usarlo con manos libres.","p":"Correcto. En una zona escolar activa, nada de teléfono en la mano; solo manos libres."},"zh":{"q":"在 Florida，在正在生效的学校区域开车时，拿着手机的规定是什么？","o":["打短电话时可以拿着","开得慢就可以拿着","不能拿在手里，只能免提","只在红灯时可以拿着"],"h1":"想一想有孩子在学校附近时多出来的危险。","h2":"在 Florida，在正在生效的学校区域开车时，你不能手拿手机，所以只能用免提。","p":"对。在正在生效的学校区域，不能手拿手机，只能免提。"},"vi":{"q":"Ở Florida, quy định về việc cầm điện thoại khi lái xe trong khu vực trường học đang hoạt động là gì?","o":["Bạn được cầm để gọi nhanh","Bạn được cầm nếu lái chậm","Bạn không được cầm; chỉ được dùng rảnh tay (hands-free)","Bạn chỉ được cầm khi dừng đèn đỏ"],"h1":"Hãy nghĩ đến mối nguy hiểm thêm gần trường học khi có trẻ em.","h2":"Ở Florida, bạn không được cầm điện thoại khi lái xe trong khu vực trường học đang hoạt động, nên bạn chỉ được dùng ở chế độ rảnh tay.","p":"Đúng. Trong khu vực trường học đang hoạt động, không cầm điện thoại, chỉ dùng rảnh tay."},"tl":{"q":"Sa Florida, ano ang patakaran sa paghawak ng phone habang nagmamaneho sa active school zone?","o":["Puwede mo itong hawakan para sa maiikling tawag","Puwede mo itong hawakan kung mabagal ka","Bawal itong hawakan; hands-free lang","Puwede mo itong hawakan sa red light lang"],"h1":"Isipin ang dagdag na panganib malapit sa paaralan kapag may mga bata.","h2":"Sa Florida, bawal kang humawak ng phone habang nagmamaneho sa active school zone, kaya puwede mo lang itong gamitin nang hands-free.","p":"Tama. Sa active school zone, bawal ang phone na hawak sa kamay; hands-free lang."},"ar":{"q":"في Florida، ما القاعدة عن إمساك الهاتف أثناء القيادة في منطقة مدرسة نشطة؟","o":["يمكنك أن تمسكه لمكالمات قصيرة","يمكنك أن تمسكه إذا كنت تقود ببطء","لا يُسمح لك بإمساكه؛ بدون استعمال اليدين فقط","يمكنك أن تمسكه فقط عند الإشارة الحمراء"],"h1":"فكّر في الخطر الزائد قرب المدارس عندما يكون الأطفال موجودين.","h2":"في Florida، لا يُسمح لك بإمساك الهاتف أثناء القيادة في منطقة مدرسة نشطة، لذلك يمكنك استعماله فقط بدون استعمال اليدين.","p":"صحيح. في منطقة مدرسة نشطة، لا هاتف في اليد، بدون استعمال اليدين فقط."},"ht":{"q":"Nan Florida, ki règ la pou kenbe yon telefòn nan men pandan w ap kondi nan yon zòn lekòl ki aktif?","o":["Ou ka kenbe l pou ti apèl kout","Ou ka kenbe l si w ap kondi dousman","Ou pa ka kenbe l; san men (hands-free) sèlman","Ou ka kenbe l sèlman nan limyè wouj"],"h1":"Panse ak danje anplis toupre lekòl yo lè gen timoun.","h2":"Nan Florida, ou pa gen dwa kenbe yon telefòn nan men pandan w ap kondi nan yon zòn lekòl ki aktif, kidonk ou ka itilize l sèlman san men (hands-free).","p":"Se sa. Nan yon zòn lekòl ki aktif, pa gen telefòn nan men, san men (hands-free) sèlman."},"ref":{"doc":"FL","page":34}},{"id":"safe-driving-014","scope":"FL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Florida, can a police officer stop you only because you are texting while driving?","o":["No, only if you also break another rule","Yes, texting while driving is enough","No, texting is only a warning","Yes, but only on the interstate"],"h1":"Think about how serious Florida treats texting at the wheel.","h2":"In Florida, texting while driving is a primary offense, so an officer may stop you for that reason alone.","p":"Right. In Florida you can be stopped just for texting while driving."},"es":{"q":"En Florida, ¿puede un policía detenerlo solo porque está enviando mensajes de texto mientras maneja?","o":["No, solo si también rompe otra regla","Sí, enviar mensajes al manejar es suficiente","No, los mensajes solo reciben una advertencia","Sí, pero solo en la autopista interestatal"],"h1":"Piense en qué tan en serio toma Florida los mensajes de texto al volante.","h2":"En Florida, enviar mensajes de texto mientras maneja es una infracción principal, así que un policía puede detenerlo solo por eso.","p":"Correcto. En Florida lo pueden detener solo por enviar mensajes al manejar."},"zh":{"q":"在 Florida，警察可以只因为你开车时发短信就让你停车吗？","o":["不可以，除非你也违反了别的规定","可以，开车发短信就足够了","不可以，发短信只会被警告","可以，但只在州际公路上"],"h1":"想一想 Florida 对开车时发短信有多严肃。","h2":"在 Florida，开车发短信是主要违法行为，所以警察只因为这个原因就可以让你停车。","p":"对。在 Florida，你可能只因为开车发短信就被拦下。"},"vi":{"q":"Ở Florida, cảnh sát có thể chặn xe bạn chỉ vì bạn nhắn tin khi lái xe không?","o":["Không, chỉ khi bạn vi phạm thêm quy định khác","Có, nhắn tin khi lái xe là đủ lý do","Không, nhắn tin chỉ bị cảnh cáo","Có, nhưng chỉ trên xa lộ liên bang"],"h1":"Hãy nghĩ xem Florida coi việc nhắn tin khi cầm lái nghiêm trọng đến mức nào.","h2":"Ở Florida, nhắn tin khi lái xe là vi phạm chính (primary offense), nên cảnh sát có thể chặn xe bạn chỉ vì lý do đó.","p":"Đúng. Ở Florida, bạn có thể bị chặn xe chỉ vì nhắn tin khi lái xe."},"tl":{"q":"Sa Florida, puwede ka bang parahin ng pulis dahil lang nagte-text ka habang nagmamaneho?","o":["Hindi, kung may iba ka lang ding nilabag na patakaran","Oo, sapat na ang pag-text habang nagmamaneho","Hindi, warning lang ang pag-text","Oo, pero sa interstate lang"],"h1":"Isipin kung gaano kabigat ang tingin ng Florida sa pag-text habang nagmamaneho.","h2":"Sa Florida, ang pag-text habang nagmamaneho ay primary offense, kaya puwede kang parahin ng pulis dahil lang doon.","p":"Tama. Sa Florida, puwede kang parahin dahil lang sa pag-text habang nagmamaneho."},"ar":{"q":"في Florida، هل يمكن للشرطي أن يوقفك فقط لأنك تكتب رسائل أثناء القيادة؟","o":["لا، فقط إذا خالفت قاعدة أخرى أيضًا","نعم، كتابة الرسائل أثناء القيادة سبب كافٍ","لا، كتابة الرسائل تعطي تحذيرًا فقط","نعم، لكن فقط على الطريق السريع بين الولايات"],"h1":"فكّر في مدى جدية Florida مع كتابة الرسائل وأنت خلف المقود.","h2":"في Florida، كتابة الرسائل أثناء القيادة مخالفة أساسية، لذلك يمكن للشرطي أن يوقفك لهذا السبب وحده.","p":"صحيح. في Florida يمكن أن يوقفوك فقط لأنك تكتب رسائل أثناء القيادة."},"ht":{"q":"Nan Florida, èske yon polis ka kanpe w sèlman paske w ap voye tèks pandan w ap kondi?","o":["Non, sèlman si ou vyole yon lòt règ tou","Wi, voye tèks pandan w ap kondi ase","Non, voye tèks se yon avètisman sèlman","Wi, men sèlman sou otowout entèeta a"],"h1":"Panse ak jan Florida pran voye tèks nan volan an oserye.","h2":"Nan Florida, voye tèks pandan w ap kondi se yon enfraksyon prensipal, kidonk yon polis ka kanpe w pou rezon sa a sèlman.","p":"Se sa. Nan Florida, yo ka kanpe w sèlman paske w ap voye tèks pandan w ap kondi."},"ref":{"doc":"FL","page":null}},{"id":"safe-driving-015","scope":"FL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Florida, what happens to a speeding fine in a work zone when workers are present?","o":["The fine is doubled","The fine is cut in half","There is no fine, only a warning","The fine is the same as anywhere else"],"h1":"Think about how the law protects people working on the road.","h2":"In Florida, the fine for speeding in a work zone is doubled when workers are present, to protect the people working there.","p":"Right. Speeding fines in a work zone are doubled when workers are present."},"es":{"q":"En Florida, ¿qué pasa con la multa por exceso de velocidad en una zona de construcción cuando hay trabajadores?","o":["La multa se duplica","La multa se reduce a la mitad","No hay multa, solo una advertencia","La multa es igual que en otro lugar"],"h1":"Piense en cómo la ley protege a las personas que trabajan en la carretera.","h2":"En Florida, la multa por exceso de velocidad en una zona de construcción se duplica cuando hay trabajadores presentes, para proteger a quienes trabajan ahí.","p":"Correcto. Las multas por exceso de velocidad en zona de construcción se duplican cuando hay trabajadores."},"zh":{"q":"在 Florida，在有工人在场的工作区超速，罚款会怎么样？","o":["罚款加倍","罚款减半","没有罚款，只有警告","罚款和其他地方一样"],"h1":"想一想法律怎样保护在路上工作的人。","h2":"在 Florida，有工人在场时，在工作区超速的罚款会加倍，这是为了保护在那里工作的人。","p":"对。有工人在场时，工作区的超速罚款加倍。"},"vi":{"q":"Ở Florida, tiền phạt chạy quá tốc độ trong khu vực thi công thay đổi thế nào khi có công nhân đang làm việc?","o":["Tiền phạt tăng gấp đôi","Tiền phạt giảm một nửa","Không bị phạt, chỉ bị cảnh cáo","Tiền phạt giống như ở nơi khác"],"h1":"Hãy nghĩ xem luật bảo vệ người làm việc trên đường như thế nào.","h2":"Ở Florida, tiền phạt chạy quá tốc độ trong khu vực thi công tăng gấp đôi khi có công nhân đang làm việc, để bảo vệ những người làm việc ở đó.","p":"Đúng. Tiền phạt chạy quá tốc độ trong khu vực thi công tăng gấp đôi khi có công nhân."},"tl":{"q":"Sa Florida, ano ang nangyayari sa multa sa overspeeding sa work zone kapag may mga trabahador?","o":["Dinodoble ang multa","Hinahati sa dalawa ang multa","Walang multa, warning lang","Pareho ang multa sa ibang lugar"],"h1":"Isipin kung paano pinoprotektahan ng batas ang mga taong nagtatrabaho sa daan.","h2":"Sa Florida, dinodoble ang multa sa overspeeding sa work zone kapag may mga trabahador, para protektahan ang mga taong nagtatrabaho roon.","p":"Tama. Dinodoble ang multa sa overspeeding sa work zone kapag may mga trabahador."},"ar":{"q":"في Florida، ماذا يحدث لغرامة السرعة في منطقة أعمال عندما يكون العمال موجودين؟","o":["الغرامة تتضاعف","الغرامة تنقص إلى النصف","لا توجد غرامة، فقط تحذير","الغرامة نفسها كما في أي مكان آخر"],"h1":"فكّر في كيف يحمي القانون الناس الذين يعملون على الطريق.","h2":"في Florida، غرامة السرعة في منطقة الأعمال تتضاعف عندما يكون العمال موجودين، لحماية الناس الذين يعملون هناك.","p":"صحيح. غرامات السرعة في منطقة الأعمال تتضاعف عندما يكون العمال موجودين."},"ht":{"q":"Nan Florida, kisa k rive amann pou vitès nan yon zòn travay lè gen travayè ki la?","o":["Amann nan double","Amann nan koupe an de","Pa gen amann, se yon avètisman sèlman","Amann nan menm jan ak nenpòt lòt kote"],"h1":"Panse ak jan lalwa pwoteje moun k ap travay sou wout la.","h2":"Nan Florida, amann pou vitès nan yon zòn travay double lè gen travayè ki la, pou pwoteje moun k ap travay la.","p":"Se sa. Amann pou vitès nan yon zòn travay double lè gen travayè ki la."},"ref":{"doc":"FL","page":29}},{"id":"safe-driving-016","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In a work zone, a flagger holds up a sign and signals you. What should you do?","o":["Follow the posted speed sign instead","Drive past if the lane looks clear","Honk so the flagger lets you go","Follow the flagger's signals"],"h1":"Think about who controls traffic in a work zone right now.","h2":"A flagger directs traffic in a work zone, so you must follow the flagger's signals even if other signs say something else.","p":"Right. In a work zone, follow the flagger's signals."},"es":{"q":"En una zona de construcción, un abanderado muestra una señal y le hace indicaciones. ¿Qué debe hacer?","o":["Seguir la señal de velocidad en su lugar","Pasar si el carril parece libre","Tocar la bocina para que lo deje pasar","Seguir las indicaciones del abanderado"],"h1":"Piense en quién controla el tráfico en la zona de construcción en este momento.","h2":"Un abanderado dirige el tráfico en una zona de construcción, así que debe seguir sus indicaciones aunque otras señales digan otra cosa.","p":"Correcto. En una zona de construcción, siga las indicaciones del abanderado."},"zh":{"q":"在工作区，一位旗手举起一块牌子向你打信号。你应该怎么做？","o":["改为按照路边的限速牌开","如果车道看起来没人就开过去","按喇叭让旗手放你过去","按照旗手的信号做"],"h1":"想一想现在是谁在工作区指挥交通。","h2":"旗手在工作区指挥交通，所以即使其他标志写的不一样，你也必须按照旗手的信号做。","p":"对。在工作区，按照旗手的信号做。"},"vi":{"q":"Trong khu vực thi công, một người cầm cờ điều khiển giao thông giơ biển và ra hiệu cho bạn. Bạn nên làm gì?","o":["Làm theo biển tốc độ được cắm thay vào đó","Chạy qua nếu làn đường có vẻ trống","Bấm còi để người cầm cờ cho bạn đi","Làm theo hiệu lệnh của người cầm cờ"],"h1":"Hãy nghĩ xem ai đang điều khiển giao thông trong khu vực thi công lúc này.","h2":"Người cầm cờ điều khiển giao thông trong khu vực thi công, nên bạn phải làm theo hiệu lệnh của người cầm cờ, dù các biển báo khác nói khác.","p":"Đúng. Trong khu vực thi công, hãy làm theo hiệu lệnh của người cầm cờ."},"tl":{"q":"Sa work zone, may flagger na nagtataas ng karatula at sumesenyas sa iyo. Ano ang dapat mong gawin?","o":["Sundin na lang ang nakapaskil na speed sign","Lumampas kung mukhang maluwag ang lane","Bumusina para paraanin ka ng flagger","Sundin ang mga senyas ng flagger"],"h1":"Isipin kung sino ang kumokontrol sa trapiko sa work zone ngayon.","h2":"Ang flagger ang nagdidirekta ng trapiko sa work zone, kaya dapat mong sundin ang mga senyas ng flagger kahit iba ang sinasabi ng ibang karatula.","p":"Tama. Sa work zone, sundin ang mga senyas ng flagger."},"ar":{"q":"في منطقة أعمال، عامل تنظيم السير يرفع لافتة ويعطيك إشارة. ماذا يجب أن تفعل؟","o":["اتبع لافتة السرعة المكتوبة بدلًا من ذلك","تجاوزه إذا بدا المسار فارغًا","استعمل البوق حتى يتركك تمرّ","اتبع إشارات عامل تنظيم السير"],"h1":"فكّر: من ينظّم حركة السير في منطقة الأعمال الآن؟","h2":"عامل تنظيم السير يوجّه الحركة في منطقة الأعمال، لذلك يجب أن تتبع إشاراته حتى إذا كانت اللافتات الأخرى تقول شيئًا آخر.","p":"صحيح. في منطقة الأعمال، اتبع إشارات عامل تنظيم السير."},"ht":{"q":"Nan yon zòn travay, yon travayè ki gen drapo leve yon pankat epi li fè w siy. Kisa ou ta dwe fè?","o":["Swiv pankat vitès ki poste a pito","Pase si liy lan sanble li vid","Klaksonen pou travayè a kite w pase","Swiv siy travayè ki gen drapo a"],"h1":"Panse ak kiyès ki dirije sikilasyon an nan zòn travay la kounye a.","h2":"Yon travayè ki gen drapo dirije sikilasyon an nan yon zòn travay, kidonk ou dwe swiv siy li fè yo menm si lòt pankat di yon lòt bagay.","p":"Se sa. Nan yon zòn travay, swiv siy travayè ki gen drapo a."},"ref":{"doc":"FL","page":54}},{"id":"safe-driving-017","scope":"US","cat":"safe-driving","sign":{"shape":"diamond-orange"},"c":1,"en":{"q":"What does an orange diamond-shaped sign usually warn you about?","o":["A school zone ahead","A work zone ahead","A railroad crossing ahead","A hospital ahead"],"h1":"Think about the color used for road work.","h2":"Orange warning signs are used for work zones, so an orange diamond tells you that road work is ahead.","p":"Right. An orange diamond sign warns of a work zone ahead."},"es":{"q":"¿Sobre qué le advierte normalmente una señal anaranjada en forma de rombo?","o":["Una zona escolar adelante","Una zona de construcción adelante","Un cruce de tren adelante","Un hospital adelante"],"h1":"Piense en el color que se usa para trabajos en la vía.","h2":"Las señales de advertencia anaranjadas se usan para zonas de construcción, así que un rombo anaranjado le dice que hay trabajos en la vía adelante.","p":"Correcto. Un rombo anaranjado advierte una zona de construcción adelante."},"zh":{"q":"橙色菱形标志通常提醒你注意什么？","o":["前面有学校区域","前面有工作区","前面有铁路道口","前面有医院"],"h1":"想一想道路施工用的是什么颜色。","h2":"橙色警告标志用于工作区，所以橙色菱形标志告诉你前面有道路施工。","p":"对。橙色菱形标志提醒你前面有工作区。"},"vi":{"q":"Biển báo màu cam hình thoi thường cảnh báo bạn về điều gì?","o":["Phía trước có khu vực trường học","Phía trước có khu vực thi công","Phía trước có đường ray xe lửa cắt ngang","Phía trước có bệnh viện"],"h1":"Hãy nghĩ đến màu được dùng cho công việc sửa đường.","h2":"Biển cảnh báo màu cam được dùng cho khu vực thi công, nên biển màu cam hình thoi cho bạn biết phía trước có công việc sửa đường.","p":"Đúng. Biển màu cam hình thoi cảnh báo phía trước có khu vực thi công."},"tl":{"q":"Ano ang karaniwang babala ng karatulang kulay orange na hugis diamond?","o":["May school zone sa unahan","May work zone sa unahan","May tawiran ng tren sa unahan","May ospital sa unahan"],"h1":"Isipin ang kulay na ginagamit para sa trabaho sa daan.","h2":"Ang mga karatulang babala na kulay orange ay ginagamit para sa mga work zone, kaya ang orange na diamond ay nagsasabing may trabaho sa daan sa unahan.","p":"Tama. Ang orange na diamond na karatula ay babala na may work zone sa unahan."},"ar":{"q":"لافتة برتقالية على شكل معيّن (مثل الماسة). مِمّ تحذّرك عادةً؟","o":["منطقة مدرسة أمامك","منطقة أعمال أمامك","تقاطع سكة حديد أمامك","مستشفى أمامك"],"h1":"فكّر في اللون المستعمل لأعمال الطرق.","h2":"لافتات التحذير البرتقالية تُستعمل لمناطق الأعمال، لذلك اللافتة البرتقالية على شكل معيّن تخبرك بأن هناك أعمال طرق أمامك.","p":"صحيح. اللافتة البرتقالية على شكل معيّن تحذّر من منطقة أعمال أمامك."},"ht":{"q":"Kisa yon pankat oranj ki gen fòm dyaman (lozanj) konn avèti w?","o":["Yon zòn lekòl devan","Yon zòn travay devan","Yon kwazman tren devan","Yon lopital devan"],"h1":"Panse ak koulè yo itilize pou travay sou wout.","h2":"Yo itilize pankat avètisman oranj pou zòn travay, kidonk yon dyaman oranj di w gen travay sou wout la devan.","p":"Se sa. Yon pankat dyaman oranj avèti w gen yon zòn travay devan."},"ref":{"doc":"FL","page":54}},{"id":"safe-driving-018","scope":"FL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Florida, a police car is stopped on the shoulder with its lights flashing. You are on a highway with two lanes going your way. What should you do?","o":["Keep your speed and stay in your lane","Stop next to the police car","Move over a lane if safe; if not, slow down","Speed up to pass the area quickly"],"h1":"Think about giving space to people working beside the road.","h2":"Florida's Move Over law says you must move out of the lane next to the stopped vehicle when it is safe, and if you cannot, you must slow down.","p":"Right. Move over a lane if you safely can, or slow down."},"es":{"q":"En Florida, un carro de policía está parado en el acotamiento con las luces encendidas. Usted va por una carretera con dos carriles en su dirección. ¿Qué debe hacer?","o":["Mantener su velocidad y su carril","Parar al lado del carro de policía","Cambiarse de carril si es seguro; si no, bajar la velocidad","Acelerar para pasar rápido"],"h1":"Piense en dar espacio a las personas que trabajan al lado de la vía.","h2":"La ley Move Over de Florida dice que debe salir del carril junto al vehículo detenido cuando sea seguro, y si no puede, debe bajar la velocidad.","p":"Correcto. Cámbiese de carril si es seguro, o baje la velocidad."},"zh":{"q":"在 Florida，一辆警车停在路肩上，灯在闪。你在一条你这个方向有两条车道的公路上。你应该怎么做？","o":["保持速度，留在你的车道","停在警车旁边","安全的话就换开一条车道；不行的话就减速","加速，快点开过这个地方"],"h1":"想一想给在路边工作的人留出空间。","h2":"Florida 的 Move Over 法律规定，安全时你必须离开紧挨停着的车辆的那条车道；如果不能，你就必须减速。","p":"对。安全的话就换开一条车道，不行就减速。"},"vi":{"q":"Ở Florida, một xe cảnh sát đang dừng trên lề đường và nháy đèn. Bạn đang đi trên xa lộ có hai làn cùng chiều với bạn. Bạn nên làm gì?","o":["Giữ tốc độ và ở yên trong làn","Dừng lại cạnh xe cảnh sát","Chuyển sang làn khác nếu an toàn; nếu không, hãy giảm tốc","Tăng tốc để đi qua khu vực đó thật nhanh"],"h1":"Hãy nghĩ đến việc chừa chỗ cho những người đang làm việc bên đường.","h2":"Luật Move Over của Florida nói rằng bạn phải rời khỏi làn sát xe đang dừng khi an toàn, và nếu không thể, bạn phải giảm tốc.","p":"Đúng. Chuyển sang làn khác nếu an toàn, hoặc giảm tốc."},"tl":{"q":"Sa Florida, may police car na nakahinto sa shoulder at kumikislap ang mga ilaw nito. Nasa highway ka na may dalawang lane papunta sa direksyon mo. Ano ang dapat mong gawin?","o":["Panatilihin ang bilis mo at manatili sa lane mo","Huminto sa tabi ng police car","Lumipat ng isang lane kung ligtas; kung hindi, bumagal","Bumilis para mabilis na malampasan ang lugar"],"h1":"Isipin ang pagbibigay ng espasyo sa mga taong nagtatrabaho sa tabi ng daan.","h2":"Sinasabi ng Move Over law ng Florida na dapat kang umalis sa lane na katabi ng nakahintong sasakyan kapag ligtas, at kung hindi mo kaya, dapat kang bumagal.","p":"Tama. Lumipat ng isang lane kung ligtas mong magagawa, o bumagal."},"ar":{"q":"في Florida، سيارة شرطة متوقفة على كتف الطريق وأضواؤها تومض. أنت على طريق سريع فيه مساران في اتجاهك. ماذا يجب أن تفعل؟","o":["حافظ على سرعتك وابقَ في مسارك","توقف بجانب سيارة الشرطة","انتقل مسارًا واحدًا بعيدًا إذا كان ذلك آمنًا؛ وإذا لم يكن آمنًا، خفّف السرعة","أسرع لتمرّ من المكان بسرعة"],"h1":"فكّر في إعطاء مساحة للناس الذين يعملون بجانب الطريق.","h2":"قانون Move Over في Florida يقول إنه يجب أن تخرج من المسار المجاور للمركبة المتوقفة عندما يكون ذلك آمنًا، وإذا لم تستطع، يجب أن تخفّف السرعة.","p":"صحيح. انتقل مسارًا واحدًا إذا استطعت بأمان، أو خفّف السرعة."},"ht":{"q":"Nan Florida, yon machin polis kanpe bò wout la ak limyè l ap flache. Ou sou yon otowout ki gen de liy nan direksyon pa w. Kisa ou ta dwe fè?","o":["Kenbe menm vitès la epi rete nan liy ou","Kanpe bò kote machin polis la","Chanje liy si li an sekirite; si se pa sa, ralanti","Akselere pou pase zòn nan vit"],"h1":"Panse ak bay moun k ap travay bò wout la espas.","h2":"Lwa Move Over Florida a di ou dwe soti nan liy ki bò kote machin ki kanpe a lè li an sekirite, epi si ou pa kapab, ou dwe ralanti.","p":"Se sa. Chanje liy si ou ka fè l san danje, oswa ralanti."},"ref":{"doc":"FL","page":65}},{"id":"safe-driving-019","scope":"FL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Florida, you cannot move over for a stopped emergency vehicle on a road with a 55 mph limit. How slow must you go?","o":["20 mph below the limit","5 mph below the limit","10 mph below the limit","Exactly 25 mph"],"h1":"Think about a big drop in speed, not a small one.","h2":"Under Florida's Move Over law, if you cannot change lanes you must slow to 20 mph below the posted limit, so on a 55 mph road you go 35 mph.","p":"Right. If you cannot move over, slow to 20 mph below the limit."},"es":{"q":"En Florida, usted no puede cambiarse de carril ante un vehículo de emergencia detenido en una vía con límite de 55 mph. ¿A qué velocidad debe ir?","o":["20 mph por debajo del límite","5 mph por debajo del límite","10 mph por debajo del límite","Exactamente 25 mph"],"h1":"Piense en una reducción grande de velocidad, no pequeña.","h2":"Según la ley Move Over de Florida, si no puede cambiarse de carril debe bajar a 20 mph por debajo del límite, así que en una vía de 55 mph va a 35 mph.","p":"Correcto. Si no puede cambiarse de carril, baje 20 mph por debajo del límite."},"zh":{"q":"在 Florida，在限速 55 mph 的路上，你不能为停着的紧急车辆换车道。你必须减到多慢？","o":["比限速低 20 mph","比限速低 5 mph","比限速低 10 mph","正好 25 mph"],"h1":"想一想大幅度减速，而不是一点点。","h2":"按照 Florida 的 Move Over 法律，如果你不能换车道，就必须减到比标示的限速低 20 mph，所以在 55 mph 的路上你要开 35 mph。","p":"对。如果不能换车道，就减到比限速低 20 mph。"},"vi":{"q":"Ở Florida, bạn không thể chuyển làn để tránh một xe cấp cứu đang dừng trên đường có giới hạn 55 mph. Bạn phải chạy chậm đến mức nào?","o":["Thấp hơn giới hạn 20 mph","Thấp hơn giới hạn 5 mph","Thấp hơn giới hạn 10 mph","Đúng 25 mph"],"h1":"Hãy nghĩ đến việc giảm tốc độ nhiều, không phải chỉ một chút.","h2":"Theo luật Move Over của Florida, nếu không thể chuyển làn, bạn phải giảm xuống thấp hơn giới hạn được cắm biển 20 mph, nên trên đường 55 mph bạn chạy 35 mph.","p":"Đúng. Nếu không thể chuyển làn, hãy giảm xuống thấp hơn giới hạn 20 mph."},"tl":{"q":"Sa Florida, hindi ka makalipat ng lane para sa nakahintong emergency vehicle sa daang may 55 mph na limit. Gaano ka dapat kabagal?","o":["20 mph na mas mababa sa limit","5 mph na mas mababa sa limit","10 mph na mas mababa sa limit","Eksaktong 25 mph"],"h1":"Isipin ang malaking pagbaba ng bilis, hindi maliit.","h2":"Ayon sa Move Over law ng Florida, kung hindi ka makalipat ng lane, dapat kang bumagal sa 20 mph na mas mababa sa nakapaskil na limit, kaya sa daang 55 mph ay 35 mph ang takbo mo.","p":"Tama. Kung hindi ka makalipat, bumagal sa 20 mph na mas mababa sa limit."},"ar":{"q":"في Florida، لا تستطيع أن تبتعد عن مركبة طوارئ متوقفة، على طريق حد السرعة فيه 55 mph (ميلًا في الساعة). إلى أي سرعة يجب أن تخفّف؟","o":["20 mph أقل من الحد","5 mph أقل من الحد","10 mph أقل من الحد","25 mph بالضبط"],"h1":"فكّر في نقص كبير في السرعة، وليس نقصًا صغيرًا.","h2":"حسب قانون Move Over في Florida، إذا لم تستطع تغيير المسار يجب أن تخفّف سرعتك إلى 20 mph أقل من الحد المكتوب، فعلى طريق حده 55 mph تسير بسرعة 35 mph.","p":"صحيح. إذا لم تستطع الابتعاد، خفّف سرعتك إلى 20 mph أقل من الحد."},"ht":{"q":"Nan Florida, ou pa ka chanje liy pou yon machin ijans ki kanpe sou yon wout kote limit la se 55 mph. Ki vitès ou dwe desann?","o":["20 mph anba limit la","5 mph anba limit la","10 mph anba limit la","Egzakteman 25 mph"],"h1":"Panse ak yon gwo bès nan vitès, pa yon ti bès.","h2":"Dapre lwa Move Over Florida a, si ou pa ka chanje liy, ou dwe ralanti pou w kondi 20 mph anba limit ki poste a, kidonk sou yon wout 55 mph ou kondi a 35 mph.","p":"Se sa. Si ou pa ka chanje liy, ralanti a 20 mph anba limit la."},"ref":{"doc":"FL","page":65}},{"id":"safe-driving-020","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"Your car starts to skid on a slippery road. What should you do?","o":["Slam on the brakes hard","Turn the wheel sharply the other way","Press the gas to get control back","Ease off the gas and steer where you want to go"],"h1":"Think about gentle moves, not sudden ones.","h2":"In a skid, sudden braking or sharp steering makes it worse, so you should ease off the gas and gently steer in the direction you want the car to go.","p":"Right. Ease off the gas and steer where you want to go."},"es":{"q":"Su carro empieza a patinar en una vía resbalosa. ¿Qué debe hacer?","o":["Frenar de golpe con fuerza","Girar el volante bruscamente al otro lado","Acelerar para recuperar el control","Soltar el acelerador y dirigir hacia donde quiere ir"],"h1":"Piense en movimientos suaves, no bruscos.","h2":"Al patinar, frenar de golpe o girar bruscamente lo empeora, así que debe soltar el acelerador y dirigir suavemente hacia donde quiere que vaya el carro.","p":"Correcto. Suelte el acelerador y dirija hacia donde quiere ir."},"zh":{"q":"你的车在很滑的路上开始打滑。你应该怎么做？","o":["用力猛踩刹车","把方向盘猛地往反方向转","踩油门来重新控制车","慢慢松开油门，把方向盘转向你想去的方向"],"h1":"想一想轻柔的动作，而不是突然的动作。","h2":"打滑时，突然刹车或猛转方向盘会让情况更糟，所以你应该慢慢松开油门，轻轻地把方向盘转向你想让车去的方向。","p":"对。慢慢松开油门，转向你想去的方向。"},"vi":{"q":"Xe của bạn bắt đầu bị trượt trên đường trơn. Bạn nên làm gì?","o":["Đạp phanh thật mạnh","Đánh tay lái gắt sang hướng ngược lại","Nhấn ga để lấy lại kiểm soát","Nhả ga từ từ và lái về hướng bạn muốn đi"],"h1":"Hãy nghĩ đến những động tác nhẹ nhàng, không đột ngột.","h2":"Khi xe bị trượt, phanh gấp hoặc đánh lái gắt sẽ làm tệ hơn, nên bạn nên nhả ga từ từ và nhẹ nhàng lái về hướng bạn muốn xe đi.","p":"Đúng. Nhả ga từ từ và lái về hướng bạn muốn đi."},"tl":{"q":"Nagsisimulang dumulas ang kotse mo sa madulas na daan. Ano ang dapat mong gawin?","o":["Tapakan nang malakas ang preno","Biglang iikot ang manibela sa kabilang direksyon","Tapakan ang gas para makontrol ulit","Dahan-dahang bitawan ang gas at imaneho kung saan mo gustong pumunta"],"h1":"Isipin ang mahinahong galaw, hindi ang biglaan.","h2":"Sa pagdulas, lumalala ito kapag biglang nagpreno o biglang iniikot ang manibela, kaya dapat mong dahan-dahang bitawan ang gas at marahang imaneho ang kotse sa direksyong gusto mo.","p":"Tama. Dahan-dahang bitawan ang gas at imaneho kung saan mo gustong pumunta."},"ar":{"q":"سيارتك تبدأ بالانزلاق على طريق زلق. ماذا يجب أن تفعل؟","o":["اضغط على الفرامل بقوة","أدِر المقود بقوة إلى الجهة الأخرى","اضغط على البنزين لتستعيد السيطرة","ارفع قدمك عن البنزين بهدوء ووجّه السيارة إلى حيث تريد أن تذهب"],"h1":"فكّر في حركات هادئة، وليس حركات مفاجئة.","h2":"أثناء الانزلاق، الفرملة المفاجئة أو إدارة المقود بقوة تجعل الوضع أسوأ، لذلك يجب أن ترفع قدمك عن البنزين بهدوء وتوجّه السيارة بلطف إلى الاتجاه الذي تريده.","p":"صحيح. ارفع قدمك عن البنزين بهدوء ووجّه السيارة إلى حيث تريد أن تذهب."},"ht":{"q":"Machin ou kòmanse glise sou yon wout ki glise. Kisa ou ta dwe fè?","o":["Peze fren an fò sanzatann","Vire volan an rapid nan lòt direksyon an","Peze gaz la pou w reprann kontwòl","Leve pye ou dousman sou gaz la epi dirije machin nan kote ou vle ale"],"h1":"Panse ak mouvman dous, pa mouvman sanzatann.","h2":"Lè machin nan ap glise, frennen sanzatann oswa vire volan an rapid fè l pi mal, kidonk ou ta dwe leve pye ou dousman sou gaz la epi dirije machin nan dousman nan direksyon ou vle l ale.","p":"Se sa. Leve pye ou sou gaz la epi dirije machin nan kote ou vle ale."},"ref":{"doc":"FL","page":79}},{"id":"safe-driving-021","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Your tires start to ride on top of water on a wet road (hydroplaning). What should you do?","o":["Brake hard right away","Ease off the gas and steer where you want to go","Speed up to get through the water","Turn the wheel quickly left and right"],"h1":"Think about letting the tires touch the road again.","h2":"When you hydroplane, the tires lose their grip on the road, so you should ease off the gas, stay off the brakes, and gently steer where you want to go.","p":"Right. Ease off the gas, avoid the brakes, and steer where you want to go."},"es":{"q":"Sus llantas empiezan a deslizarse sobre el agua en una vía mojada (hidroplaneo). ¿Qué debe hacer?","o":["Frenar fuerte de inmediato","Soltar el acelerador y dirigir hacia donde quiere ir","Acelerar para pasar el agua","Mover el volante rápido a los lados"],"h1":"Piense en dejar que las llantas vuelvan a tocar la vía.","h2":"En el hidroplaneo las llantas pierden el agarre con la vía, así que debe soltar el acelerador, no usar los frenos y dirigir suavemente hacia donde quiere ir.","p":"Correcto. Suelte el acelerador, no frene y dirija hacia donde quiere ir."},"zh":{"q":"在湿的路上，你的轮胎开始浮在水面上（水滑）。你应该怎么做？","o":["马上用力刹车","慢慢松开油门，把方向盘转向你想去的方向","加速冲过水","把方向盘快速地左右转"],"h1":"想一想让轮胎重新接触路面。","h2":"发生水滑时，轮胎失去了对路面的抓地力，所以你应该慢慢松开油门，不要踩刹车，轻轻地把方向盘转向你想去的方向。","p":"对。慢慢松开油门，不要踩刹车，转向你想去的方向。"},"vi":{"q":"Bánh xe của bạn bắt đầu lướt trên mặt nước trên đường ướt (hydroplaning). Bạn nên làm gì?","o":["Phanh mạnh ngay lập tức","Nhả ga từ từ và lái về hướng bạn muốn đi","Tăng tốc để đi qua vùng nước","Đánh tay lái nhanh qua trái qua phải"],"h1":"Hãy nghĩ đến việc để bánh xe chạm lại mặt đường.","h2":"Khi xe lướt nước, bánh xe mất độ bám đường, nên bạn nên nhả ga từ từ, không đạp phanh, và nhẹ nhàng lái về hướng bạn muốn đi.","p":"Đúng. Nhả ga từ từ, tránh đạp phanh, và lái về hướng bạn muốn đi."},"tl":{"q":"Nagsisimulang lumutang sa ibabaw ng tubig ang mga gulong mo sa basang daan (hydroplaning). Ano ang dapat mong gawin?","o":["Magpreno nang malakas agad","Dahan-dahang bitawan ang gas at imaneho kung saan mo gustong pumunta","Bumilis para malampasan ang tubig","Mabilis na iikot ang manibela pakaliwa at pakanan"],"h1":"Isipin kung paano muling dadampi sa daan ang mga gulong.","h2":"Kapag nag-hydroplane ka, nawawalan ng kapit sa daan ang mga gulong, kaya dapat mong dahan-dahang bitawan ang gas, huwag magpreno, at marahang imaneho kung saan mo gustong pumunta.","p":"Tama. Dahan-dahang bitawan ang gas, iwasan ang preno, at imaneho kung saan mo gustong pumunta."},"ar":{"q":"إطاراتك بدأت تسير فوق الماء على طريق مبلل (انزلاق مائي). ماذا يجب أن تفعل؟","o":["اضغط على الفرامل بقوة فورًا","ارفع قدمك عن البنزين بهدوء ووجّه السيارة إلى حيث تريد أن تذهب","أسرع لتعبر الماء","أدِر المقود بسرعة يمينًا ويسارًا"],"h1":"فكّر في أن تترك الإطارات تلمس الطريق مرة أخرى.","h2":"في الانزلاق المائي، الإطارات تفقد تماسكها مع الطريق، لذلك يجب أن ترفع قدمك عن البنزين بهدوء، وألا تستعمل الفرامل، وأن توجّه السيارة بلطف إلى حيث تريد أن تذهب.","p":"صحيح. ارفع قدمك عن البنزين، وتجنّب الفرامل، ووجّه السيارة إلى حيث تريد أن تذهب."},"ht":{"q":"Kawotchou ou yo kòmanse woule sou dlo a sou yon wout mouye (hydroplaning). Kisa ou ta dwe fè?","o":["Frennen fò touswit","Leve pye ou dousman sou gaz la epi dirije machin nan kote ou vle ale","Akselere pou w travèse dlo a","Vire volan an vit agoch ak adwat"],"h1":"Panse ak kite kawotchou yo touche wout la ankò.","h2":"Lè kawotchou yo ap glise sou dlo (hydroplaning), yo pèdi kenbe yo sou wout la, kidonk ou ta dwe leve pye ou dousman sou gaz la, pa touche fren an, epi dirije machin nan dousman kote ou vle ale.","p":"Se sa. Leve pye ou sou gaz la, pa touche fren an, epi dirije machin nan kote ou vle ale."},"ref":{"doc":"FL","page":79}},{"id":"safe-driving-022","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"A front tire suddenly blows out while you are driving. What should you do first?","o":["Hold the wheel firmly and ease off the gas","Brake hard to stop right away","Steer quickly onto the shoulder","Speed up to keep the car straight"],"h1":"Think about keeping control of the car before you stop.","h2":"A blowout can pull the car to one side, so you should hold the wheel firmly, ease off the gas, and brake gently only after the car is under control.","p":"Right. Hold the wheel firmly and ease off the gas."},"es":{"q":"Una llanta delantera revienta de repente mientras maneja. ¿Qué debe hacer primero?","o":["Sostener firme el volante y soltar el acelerador","Frenar fuerte para parar de inmediato","Girar rápido hacia el acotamiento","Acelerar para mantener el carro derecho"],"h1":"Piense en mantener el control del carro antes de parar.","h2":"Una llanta reventada puede jalar el carro hacia un lado, así que debe sostener firme el volante, soltar el acelerador y frenar suave solo cuando tenga el control.","p":"Correcto. Sostenga firme el volante y suelte el acelerador."},"zh":{"q":"你开车时，一个前轮突然爆胎。你首先应该做什么？","o":["紧紧握住方向盘，慢慢松开油门","用力刹车，马上停下","快速转到路肩上","加速让车保持直行"],"h1":"想一想在停车前先控制住车。","h2":"爆胎可能会把车拉向一边，所以你应该紧紧握住方向盘，慢慢松开油门，等车被控制住以后再轻轻刹车。","p":"对。紧紧握住方向盘，慢慢松开油门。"},"vi":{"q":"Một bánh xe trước đột nhiên bị nổ khi bạn đang lái. Bạn nên làm gì trước tiên?","o":["Giữ chặt tay lái và nhả ga từ từ","Phanh mạnh để dừng ngay","Lái nhanh vào lề đường","Tăng tốc để giữ xe đi thẳng"],"h1":"Hãy nghĩ đến việc giữ kiểm soát xe trước khi dừng lại.","h2":"Nổ lốp có thể kéo xe lệch sang một bên, nên bạn nên giữ chặt tay lái, nhả ga từ từ, và chỉ phanh nhẹ sau khi đã kiểm soát được xe.","p":"Đúng. Giữ chặt tay lái và nhả ga từ từ."},"tl":{"q":"Biglang pumutok ang gulong sa harap habang nagmamaneho ka. Ano ang una mong dapat gawin?","o":["Hawakan nang mahigpit ang manibela at dahan-dahang bitawan ang gas","Magpreno nang malakas para huminto agad","Mabilis na lumihis papunta sa shoulder","Bumilis para manatiling diretso ang kotse"],"h1":"Isipin ang pagkontrol sa kotse bago ka huminto.","h2":"Ang pagputok ng gulong ay puwedeng humila sa kotse sa isang tabi, kaya dapat mong hawakan nang mahigpit ang manibela, dahan-dahang bitawan ang gas, at marahang magpreno pagkatapos lang makontrol ang kotse.","p":"Tama. Hawakan nang mahigpit ang manibela at dahan-dahang bitawan ang gas."},"ar":{"q":"إطار أمامي انفجر فجأة وأنت تقود. ماذا يجب أن تفعل أولًا؟","o":["أمسك المقود بقوة وارفع قدمك عن البنزين بهدوء","اضغط على الفرامل بقوة لتتوقف فورًا","وجّه السيارة بسرعة إلى كتف الطريق","أسرع لتبقى السيارة مستقيمة"],"h1":"فكّر في السيطرة على السيارة قبل أن تتوقف.","h2":"انفجار الإطار قد يسحب السيارة إلى جهة واحدة، لذلك يجب أن تمسك المقود بقوة، وترفع قدمك عن البنزين بهدوء، وتضغط الفرامل بلطف فقط بعد أن تسيطر على السيارة.","p":"صحيح. أمسك المقود بقوة وارفع قدمك عن البنزين بهدوء."},"ht":{"q":"Yon kawotchou devan pete sanzatann pandan w ap kondi. Kisa ou ta dwe fè anvan?","o":["Kenbe volan an fèm epi leve pye ou dousman sou gaz la","Frennen fò pou kanpe touswit","Vire vit pou w ale bò wout la","Akselere pou kenbe machin nan dwat"],"h1":"Panse ak kenbe kontwòl machin nan anvan ou kanpe.","h2":"Yon kawotchou ki pete ka rale machin nan sou yon bò, kidonk ou ta dwe kenbe volan an fèm, leve pye ou dousman sou gaz la, epi frennen dousman sèlman apre ou gen kontwòl machin nan.","p":"Se sa. Kenbe volan an fèm epi leve pye ou dousman sou gaz la."},"ref":{"doc":"FL","page":80}},{"id":"safe-driving-023","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"You press the brake pedal and your brakes do not work. What should you try first?","o":["Turn off the engine right away","Open the door and drag your foot","Pump the brake pedal fast","Shift into reverse"],"h1":"Think about trying to build up brake pressure again.","h2":"Pumping the brake pedal may build up pressure again, and if that fails you can use the parking brake slowly and shift to a lower gear.","p":"Right. Pump the brake pedal first, then use the parking brake."},"es":{"q":"Usted pisa el freno y los frenos no funcionan. ¿Qué debe intentar primero?","o":["Apagar el motor de inmediato","Abrir la puerta y arrastrar el pie","Bombear el pedal del freno rápido","Poner la reversa"],"h1":"Piense en volver a crear presión en los frenos.","h2":"Bombear el pedal del freno puede volver a crear presión, y si no funciona, puede usar el freno de mano poco a poco y cambiar a una velocidad más baja.","p":"Correcto. Bombee el pedal primero y luego use el freno de mano."},"zh":{"q":"你踩刹车踏板，可是刹车不灵。你首先应该试什么？","o":["马上关掉引擎","打开车门，用脚拖地","快速地连续踩刹车踏板","挂倒挡"],"h1":"想一想怎样让刹车重新产生压力。","h2":"快速连续踩刹车踏板可能会让压力重新建立起来；如果不行，你可以慢慢拉手刹，并换到低挡。","p":"对。先连续踩刹车踏板，然后用手刹。"},"vi":{"q":"Bạn đạp bàn đạp phanh nhưng phanh không ăn. Bạn nên thử làm gì trước tiên?","o":["Tắt máy xe ngay lập tức","Mở cửa và kéo chân xuống đất","Đạp nhấp bàn đạp phanh liên tục và nhanh","Chuyển sang số lùi"],"h1":"Hãy nghĩ đến việc cố tạo lại áp lực phanh.","h2":"Đạp nhấp bàn đạp phanh có thể tạo lại áp lực, và nếu không được, bạn có thể kéo phanh tay từ từ và chuyển xuống số thấp hơn.","p":"Đúng. Đạp nhấp bàn đạp phanh trước, rồi dùng phanh tay."},"tl":{"q":"Tinapakan mo ang preno at hindi gumagana ang preno mo. Ano ang una mong dapat subukan?","o":["Patayin agad ang makina","Buksan ang pinto at ikaskas ang paa mo sa daan","Mabilis na tapak-tapakan ang preno nang paulit-ulit","Ilagay sa reverse"],"h1":"Isipin ang pagsubok na muling magkaroon ng pressure sa preno.","h2":"Ang paulit-ulit at mabilis na pagtapak sa preno ay puwedeng magbalik ng pressure, at kung hindi ito gumana, puwede mong dahan-dahang gamitin ang parking brake at ilipat sa mas mababang gear.","p":"Tama. Tapak-tapakan muna ang preno, saka gamitin ang parking brake."},"ar":{"q":"تضغط على دواسة الفرامل والفرامل لا تعمل. ماذا يجب أن تجرّب أولًا؟","o":["أطفئ المحرك فورًا","افتح الباب واسحب قدمك على الأرض","اضغط على دواسة الفرامل مرات سريعة متتالية","انقل الغيار إلى الخلف (reverse)"],"h1":"فكّر في محاولة بناء ضغط الفرامل مرة أخرى.","h2":"الضغط على دواسة الفرامل مرات متتالية قد يبني الضغط مرة أخرى، وإذا لم ينجح ذلك يمكنك استعمال فرامل اليد ببطء والنقل إلى غيار أدنى.","p":"صحيح. اضغط على دواسة الفرامل مرات متتالية أولًا، ثم استعمل فرامل اليد."},"ht":{"q":"Ou peze pedal fren an epi fren yo pa mache. Kisa ou ta dwe eseye anvan?","o":["Fèmen motè a touswit","Louvri pòt la epi trennen pye ou atè","Peze pedal fren an plizyè fwa vit","Mete machin nan an mach aryè"],"h1":"Panse ak eseye fè presyon fren an monte ankò.","h2":"Lè ou peze pedal fren an plizyè fwa vit, sa ka fè presyon an monte ankò, epi si sa pa mache, ou ka sèvi ak fren a men an dousman epi mete yon vitès ki pi ba.","p":"Se sa. Peze pedal fren an plizyè fwa anvan, epi sèvi ak fren a men an."}},{"id":"safe-driving-024","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"Your gas pedal gets stuck and the car keeps speeding up. What should you do?","o":["Pull the key out while moving","Turn the wheel hard to the side","Pump the gas pedal many times","Shift to neutral and brake"],"h1":"Think about how to stop the engine from pushing the wheels.","h2":"Shifting to neutral stops the engine from driving the wheels, so you can brake, pull off the road, and then turn off the engine.","p":"Right. Shift to neutral and brake to a safe stop."},"es":{"q":"Su pedal del acelerador se traba y el carro sigue acelerando. ¿Qué debe hacer?","o":["Sacar la llave mientras se mueve","Girar el volante fuerte hacia un lado","Bombear el acelerador muchas veces","Poner neutro y frenar"],"h1":"Piense en cómo impedir que el motor siga empujando las ruedas.","h2":"Al poner neutro el motor deja de mover las ruedas, así que puede frenar, salir de la vía y luego apagar el motor.","p":"Correcto. Ponga neutro y frene hasta parar con seguridad."},"zh":{"q":"你的油门踏板卡住了，车一直在加速。你应该怎么做？","o":["开车时把钥匙拔出来","把方向盘用力转向一边","连续踩很多次油门","换到空挡并刹车"],"h1":"想一想怎样让引擎不再推动车轮。","h2":"换到空挡后，引擎就不再带动车轮，所以你可以刹车，把车开离道路，然后关掉引擎。","p":"对。换到空挡，刹车，安全地停下来。"},"vi":{"q":"Bàn đạp ga của bạn bị kẹt và xe cứ tăng tốc. Bạn nên làm gì?","o":["Rút chìa khóa ra khi xe đang chạy","Đánh tay lái mạnh sang một bên","Đạp nhấp bàn đạp ga nhiều lần","Chuyển sang số N (số mo) và phanh"],"h1":"Hãy nghĩ cách để động cơ không đẩy bánh xe nữa.","h2":"Chuyển sang số N làm động cơ không còn đẩy bánh xe, nên bạn có thể phanh, tấp vào lề, rồi tắt máy.","p":"Đúng. Chuyển sang số N và phanh để dừng an toàn."},"tl":{"q":"Naipit ang gas pedal mo at patuloy na bumibilis ang kotse. Ano ang dapat mong gawin?","o":["Bunutin ang susi habang umaandar","Iikot nang malakas ang manibela sa gilid","Tapak-tapakan ang gas nang maraming beses","Ilagay sa neutral at magpreno"],"h1":"Isipin kung paano pipigilan ang makina sa pagtulak sa mga gulong.","h2":"Kapag inilagay sa neutral, hindi na itinutulak ng makina ang mga gulong, kaya puwede kang magpreno, tumabi sa daan, at saka patayin ang makina.","p":"Tama. Ilagay sa neutral at magpreno hanggang ligtas na huminto."},"ar":{"q":"دواسة البنزين علقت والسيارة تستمر في زيادة السرعة. ماذا يجب أن تفعل؟","o":["اسحب المفتاح والسيارة تتحرك","أدِر المقود بقوة إلى الجانب","اضغط على دواسة البنزين مرات كثيرة","انقل الغيار إلى المحايد (neutral) واضغط الفرامل"],"h1":"فكّر في كيف تمنع المحرك من دفع العجلات.","h2":"النقل إلى المحايد (neutral) يمنع المحرك من تحريك العجلات، فتستطيع أن تضغط الفرامل، وتخرج من الطريق، ثم تطفئ المحرك.","p":"صحيح. انقل الغيار إلى المحايد (neutral) واضغط الفرامل حتى تتوقف بأمان."},"ht":{"q":"Pedal gaz ou a bloke epi machin nan kontinye ap akselere. Kisa ou ta dwe fè?","o":["Rale kle a pandan machin nan ap woule","Vire volan an fò sou kote","Peze pedal gaz la anpil fwa","Mete machin nan an netral (N) epi frennen"],"h1":"Panse ak kijan pou w anpeche motè a pouse wou yo.","h2":"Lè ou mete machin nan an netral (N), motè a pa pouse wou yo ankò, kidonk ou ka frennen, soti sou bò wout la, epi apre sa fèmen motè a.","p":"Se sa. Mete machin nan an netral (N) epi frennen pou w kanpe san danje."},"ref":{"doc":"FL","page":79}},{"id":"safe-driving-025","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Your right wheels drift off the pavement onto the dirt edge. What should you do?","o":["Jerk the wheel back onto the road","Ease off the gas, slow down, then steer back gently","Brake hard right away","Speed up and steer back fast"],"h1":"Think about slowing down before you return to the road.","h2":"Turning back too fast can make you lose control, so ease off the gas, slow down, and then steer gently back onto the pavement when it is safe.","p":"Right. Slow down first, then steer back gently."},"es":{"q":"Sus ruedas derechas se salen del pavimento a la orilla de tierra. ¿Qué debe hacer?","o":["Jalar el volante de golpe hacia la vía","Soltar el acelerador, bajar la velocidad y volver suavemente","Frenar fuerte de inmediato","Acelerar y volver rápido a la vía"],"h1":"Piense en bajar la velocidad antes de volver a la vía.","h2":"Volver demasiado rápido puede hacerle perder el control, así que suelte el acelerador, baje la velocidad y vuelva suavemente al pavimento cuando sea seguro.","p":"Correcto. Primero baje la velocidad y luego vuelva suavemente."},"zh":{"q":"你右边的车轮偏出了路面，开到了泥土路边上。你应该怎么做？","o":["猛地把方向盘转回路上","慢慢松开油门，减速，然后轻轻地转回去","马上用力刹车","加速，快速转回去"],"h1":"想一想在回到路上之前先减速。","h2":"转回去太快会让你失去控制，所以要慢慢松开油门，减速，然后在安全时轻轻地把车转回路面。","p":"对。先减速，然后轻轻地转回去。"},"vi":{"q":"Bánh xe bên phải của bạn trôi ra khỏi mặt đường nhựa xuống lề đất. Bạn nên làm gì?","o":["Giật mạnh tay lái để quay lại đường","Nhả ga từ từ, giảm tốc, rồi nhẹ nhàng lái trở lại","Phanh mạnh ngay lập tức","Tăng tốc và lái trở lại thật nhanh"],"h1":"Hãy nghĩ đến việc giảm tốc trước khi quay lại đường.","h2":"Quay lại quá nhanh có thể làm bạn mất kiểm soát, nên hãy nhả ga từ từ, giảm tốc, rồi nhẹ nhàng lái trở lại mặt đường nhựa khi an toàn.","p":"Đúng. Giảm tốc trước, rồi nhẹ nhàng lái trở lại."},"tl":{"q":"Lumabas ang mga gulong mo sa kanan mula sa sementadong daan papunta sa lupang gilid. Ano ang dapat mong gawin?","o":["Biglang ibalik ang manibela papunta sa daan","Dahan-dahang bitawan ang gas, bumagal, saka marahang ibalik sa daan","Magpreno nang malakas agad","Bumilis at mabilis na ibalik sa daan"],"h1":"Isipin ang pagbagal bago ka bumalik sa daan.","h2":"Ang masyadong mabilis na pagbalik ay puwedeng magpawala ng kontrol mo, kaya dahan-dahang bitawan ang gas, bumagal, at saka marahang ibalik ang kotse sa sementadong daan kapag ligtas na.","p":"Tama. Bumagal muna, saka marahang bumalik sa daan."},"ar":{"q":"عجلاتك اليمنى خرجت عن الطريق المعبّد إلى الحافة الترابية. ماذا يجب أن تفعل؟","o":["أدِر المقود بقوة مفاجئة لتعود إلى الطريق","ارفع قدمك عن البنزين بهدوء، وخفّف السرعة، ثم عُد بلطف","اضغط على الفرامل بقوة فورًا","أسرع وعُد بسرعة"],"h1":"فكّر في تخفيف السرعة قبل أن تعود إلى الطريق.","h2":"العودة بسرعة كبيرة قد تجعلك تفقد السيطرة، لذلك ارفع قدمك عن البنزين بهدوء، وخفّف السرعة، ثم عُد بلطف إلى الطريق المعبّد عندما يكون ذلك آمنًا.","p":"صحيح. خفّف السرعة أولًا، ثم عُد بلطف."},"ht":{"q":"Wou dwat ou yo soti sou asfalt la epi yo tonbe sou bò tè a. Kisa ou ta dwe fè?","o":["Vire volan an sèk pou retounen sou wout la","Leve pye ou sou gaz la, ralanti, epi retounen dousman","Frennen fò touswit","Akselere epi retounen vit"],"h1":"Panse ak ralanti anvan ou retounen sou wout la.","h2":"Si ou retounen twò vit, ou ka pèdi kontwòl, kidonk leve pye ou sou gaz la, ralanti, epi dirije machin nan dousman pou l retounen sou asfalt la lè li an sekirite.","p":"Se sa. Ralanti anvan, epi retounen dousman."},"ref":{"doc":"FL","page":79}},{"id":"safe-driving-026","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"Your car stalls on railroad tracks and a train is coming. What should you do?","o":["Stay in the car and keep trying to start it","Get out and stand next to the car","Get everyone out and move away from the tracks toward the train at an angle","Get out and run straight down the tracks"],"h1":"Think about where pieces of the car could fly if the train hits it.","h2":"Get everyone out right away and move away from the tracks at an angle toward the train, so flying parts from the crash do not hit you.","p":"Right. Get out fast and move away at an angle toward the train."},"es":{"q":"Su carro se apaga sobre las vías del tren y viene un tren. ¿Qué debe hacer?","o":["Quedarse en el carro y tratar de encenderlo","Salir y quedarse al lado del carro","Sacar a todos y alejarse de las vías en diagonal hacia el tren","Salir y correr por encima de las vías"],"h1":"Piense en hacia dónde podrían volar las piezas del carro si el tren lo golpea.","h2":"Saque a todos de inmediato y aléjense de las vías en diagonal hacia donde viene el tren, para que las piezas que vuelen en el choque no los golpeen.","p":"Correcto. Salga rápido y aléjese en diagonal hacia el tren."},"zh":{"q":"你的车在铁轨上熄火了，有火车开过来。你应该怎么做？","o":["留在车里，一直试着发动","下车，站在车旁边","让所有人下车，朝火车来的方向斜着离开铁轨","下车，沿着铁轨直着跑"],"h1":"想一想火车撞到车时，车的碎片可能飞到哪里。","h2":"马上让所有人下车，朝火车来的方向斜着离开铁轨，这样撞击时飞出来的碎片才不会打到你。","p":"对。快点下车，朝火车来的方向斜着离开。"},"vi":{"q":"Xe của bạn bị chết máy trên đường ray xe lửa và có tàu đang tới. Bạn nên làm gì?","o":["Ở trong xe và tiếp tục cố nổ máy","Ra khỏi xe và đứng cạnh xe","Đưa mọi người ra ngoài và đi xa khỏi đường ray, chéo về phía tàu đang tới","Ra khỏi xe và chạy thẳng dọc theo đường ray"],"h1":"Hãy nghĩ xem các mảnh vỡ của xe có thể văng đi đâu nếu tàu đâm vào.","h2":"Đưa mọi người ra ngoài ngay và đi xa khỏi đường ray theo hướng chéo về phía tàu đang tới, để các mảnh vỡ văng ra từ vụ va chạm không trúng bạn.","p":"Đúng. Ra ngoài thật nhanh và đi xa theo hướng chéo về phía tàu."},"tl":{"q":"Namatay ang makina ng kotse mo sa riles ng tren at may paparating na tren. Ano ang dapat mong gawin?","o":["Manatili sa kotse at patuloy na subukang paandarin ito","Lumabas at tumayo sa tabi ng kotse","Palabasin ang lahat at lumayo sa riles nang pahilis, papunta sa direksyon ng tren","Lumabas at tumakbo nang diretso sa riles"],"h1":"Isipin kung saan puwedeng tumilapon ang mga piraso ng kotse kapag nabangga ito ng tren.","h2":"Palabasin agad ang lahat at lumayo sa riles nang pahilis papunta sa direksyon ng tren, para hindi kayo tamaan ng mga piraso na tumitilapon mula sa banggaan.","p":"Tama. Lumabas agad at lumayo nang pahilis papunta sa direksyon ng tren."},"ar":{"q":"سيارتك توقفت على سكة القطار والقطار قادم. ماذا يجب أن تفعل؟","o":["ابقَ في السيارة واستمر في محاولة تشغيلها","اخرج وقف بجانب السيارة","أخرِج الجميع وابتعدوا عن السكة بشكل مائل في اتجاه القطار","اخرج واركض على طول السكة مباشرة"],"h1":"فكّر: إلى أين قد تطير قطع السيارة إذا صدمها القطار؟","h2":"أخرِج الجميع فورًا وابتعدوا عن السكة بشكل مائل في اتجاه القطار، حتى لا تصيبكم القطع التي تطير من الاصطدام.","p":"صحيح. اخرج بسرعة وابتعد بشكل مائل في اتجاه القطار."},"ht":{"q":"Machin ou mouri sou ray tren an epi gen yon tren k ap vini. Kisa ou ta dwe fè?","o":["Rete nan machin nan epi kontinye eseye estat li","Desann epi kanpe bò kote machin nan","Fè tout moun desann epi kouri lwen ray yo an bivè, nan direksyon tren an","Desann epi kouri tou dwat sou ray yo"],"h1":"Panse ak ki kote moso machin nan ka vole si tren an frape l.","h2":"Fè tout moun desann touswit epi deplase lwen ray yo an bivè, nan direksyon tren k ap vini an, pou moso ki vole nan aksidan an pa frape w.","p":"Se sa. Desann vit epi ale lwen an bivè, nan direksyon tren an."},"ref":{"doc":"FL","page":79}},{"id":"safe-driving-027","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"Your car is stuck on railroad tracks, and no train is in sight. After everyone is out, who should you call?","o":["The number on the blue sign at the crossing, or 911","Your car insurance company","A tow truck, then wait in the car","Nobody, just keep trying to start the car"],"h1":"Think about who can warn the train before it arrives.","h2":"Get everyone out, then call the number on the blue emergency sign at the crossing or 911, so the railroad can stop or slow trains.","p":"Right. Call the number on the blue sign at the crossing, or 911."},"es":{"q":"Su carro está atascado en las vías del tren y no se ve ningún tren. Después de que todos salen, ¿a quién debe llamar?","o":["Al número del letrero azul del cruce, o al 911","A su compañía de seguros","A una grúa, y esperar dentro del carro","A nadie, solo seguir tratando de encenderlo"],"h1":"Piense en quién puede avisar al tren antes de que llegue.","h2":"Saque a todos y luego llame al número del letrero azul de emergencia del cruce o al 911, para que el ferrocarril pueda parar o frenar los trenes.","p":"Correcto. Llame al número del letrero azul del cruce, o al 911."},"zh":{"q":"你的车卡在铁轨上，看不到火车。所有人下车以后，你应该打电话给谁？","o":["道口蓝色牌子上的电话号码，或 911","你的汽车保险公司","拖车公司，然后在车里等","谁都不用打，只要一直试着发动车"],"h1":"想一想谁能在火车到来之前提醒火车。","h2":"让所有人下车，然后打道口蓝色紧急牌子上的电话号码或 911，这样铁路公司就能让火车停下或减速。","p":"对。打道口蓝色牌子上的电话号码，或 911。"},"vi":{"q":"Xe của bạn bị kẹt trên đường ray xe lửa, và chưa thấy tàu nào. Sau khi mọi người đã ra ngoài, bạn nên gọi cho ai?","o":["Số điện thoại trên biển màu xanh dương ở chỗ đường ray cắt ngang, hoặc 911","Công ty bảo hiểm xe của bạn","Xe kéo, rồi ngồi chờ trong xe","Không gọi ai, cứ tiếp tục cố nổ máy"],"h1":"Hãy nghĩ xem ai có thể báo cho tàu trước khi tàu tới.","h2":"Đưa mọi người ra ngoài, rồi gọi số điện thoại trên biển khẩn cấp màu xanh dương ở chỗ đường ray cắt ngang hoặc gọi 911, để công ty đường sắt có thể dừng hoặc làm chậm tàu.","p":"Đúng. Gọi số trên biển màu xanh dương ở chỗ đường ray cắt ngang, hoặc 911."},"tl":{"q":"Naipit ang kotse mo sa riles ng tren, at walang tren na tanaw. Pagkalabas ng lahat, sino ang dapat mong tawagan?","o":["Ang numero sa asul na karatula sa tawiran, o 911","Ang car insurance company mo","Isang tow truck, saka maghintay sa loob ng kotse","Wala, patuloy lang na subukang paandarin ang kotse"],"h1":"Isipin kung sino ang makakapagbabala sa tren bago ito dumating.","h2":"Palabasin ang lahat, saka tawagan ang numero sa asul na emergency sign sa tawiran o ang 911, para mapahinto o mapabagal ng riles ang mga tren.","p":"Tama. Tawagan ang numero sa asul na karatula sa tawiran, o 911."},"ar":{"q":"سيارتك عالقة على سكة القطار، ولا يوجد قطار في الأفق. بعد أن يخرج الجميع، بمن يجب أن تتصل؟","o":["بالرقم المكتوب على اللافتة الزرقاء عند التقاطع، أو 911","بشركة تأمين سيارتك","بشاحنة سحب، ثم انتظر في السيارة","لا أحد، فقط استمر في محاولة تشغيل السيارة"],"h1":"فكّر: من يستطيع أن يحذّر القطار قبل أن يصل؟","h2":"أخرِج الجميع، ثم اتصل بالرقم المكتوب على لافتة الطوارئ الزرقاء عند التقاطع أو بـ 911، حتى تستطيع شركة السكة الحديد أن توقف القطارات أو تخفّف سرعتها.","p":"صحيح. اتصل بالرقم المكتوب على اللافتة الزرقاء عند التقاطع، أو بـ 911."},"ht":{"q":"Machin ou bloke sou ray tren an, epi ou pa wè okenn tren. Apre tout moun fin desann, kiyès ou ta dwe rele?","o":["Nimewo ki sou pankat ble nan kwazman an, oswa 911","Konpayi asirans machin ou","Yon remòkè, epi tann nan machin nan","Pèsonn, jis kontinye eseye estat machin nan"],"h1":"Panse ak kiyès ki ka avèti tren an anvan li rive.","h2":"Fè tout moun desann, epi rele nimewo ki sou pankat ijans ble nan kwazman an oswa 911, pou konpayi tren an ka fè tren yo kanpe oswa ralanti.","p":"Se sa. Rele nimewo ki sou pankat ble nan kwazman an, oswa 911."},"ref":{"doc":"FL","page":80}},{"id":"safe-driving-028","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"Your car goes into a canal or lake. What should you do first?","o":["Call for help and wait inside","Wait until the car fills with water","Turn on the hazard lights","Unbuckle, open a window and get out"],"h1":"Think about how fast you need to leave the car.","h2":"You should act right away: unbuckle your seat belt, open or break a window, and get out before the water gets too high.","p":"Right. Unbuckle, open a window and get out fast."},"es":{"q":"Su carro cae a un canal o a un lago. ¿Qué debe hacer primero?","o":["Pedir ayuda y esperar adentro","Esperar a que el carro se llene de agua","Encender las luces de emergencia","Quitarse el cinturón, abrir una ventana y salir"],"h1":"Piense en qué tan rápido debe salir del carro.","h2":"Debe actuar de inmediato: quítese el cinturón, abra o rompa una ventana y salga antes de que el agua suba demasiado.","p":"Correcto. Quítese el cinturón, abra una ventana y salga rápido."},"zh":{"q":"你的车开进了运河或湖里。你首先应该做什么？","o":["打电话求救，在车里等","等到车里灌满水","打开危险警示灯","解开安全带，打开车窗，出去"],"h1":"想一想你需要多快离开车。","h2":"你应该马上行动：解开安全带，打开或打破车窗，在水变得太高之前出去。","p":"对。解开安全带，打开车窗，快点出去。"},"vi":{"q":"Xe của bạn lao xuống kênh hoặc hồ. Bạn nên làm gì trước tiên?","o":["Gọi cứu giúp và chờ trong xe","Chờ đến khi xe đầy nước","Bật đèn khẩn cấp","Tháo dây an toàn, mở cửa sổ và ra ngoài"],"h1":"Hãy nghĩ xem bạn cần rời xe nhanh đến mức nào.","h2":"Bạn nên hành động ngay: tháo dây an toàn, mở hoặc đập vỡ cửa sổ, và ra ngoài trước khi nước dâng quá cao.","p":"Đúng. Tháo dây an toàn, mở cửa sổ và ra ngoài thật nhanh."},"tl":{"q":"Nahulog ang kotse mo sa kanal o lawa. Ano ang una mong dapat gawin?","o":["Tumawag ng tulong at maghintay sa loob","Maghintay hanggang mapuno ng tubig ang kotse","I-on ang hazard lights","Tanggalin ang seat belt, buksan ang bintana, at lumabas"],"h1":"Isipin kung gaano ka kabilis dapat umalis sa kotse.","h2":"Dapat kang kumilos agad: tanggalin ang seat belt mo, buksan o basagin ang bintana, at lumabas bago tumaas nang husto ang tubig.","p":"Tama. Tanggalin ang seat belt, buksan ang bintana, at lumabas agad."},"ar":{"q":"سيارتك وقعت في قناة ماء أو بحيرة. ماذا يجب أن تفعل أولًا؟","o":["اطلب المساعدة وانتظر في الداخل","انتظر حتى تمتلئ السيارة بالماء","شغّل أضواء التحذير","فُك الحزام، وافتح النافذة، واخرج"],"h1":"فكّر في السرعة التي تحتاجها لتترك السيارة.","h2":"يجب أن تتصرف فورًا: فُك حزام الأمان، وافتح النافذة أو اكسرها، واخرج قبل أن يرتفع الماء كثيرًا.","p":"صحيح. فُك الحزام، وافتح النافذة، واخرج بسرعة."},"ht":{"q":"Machin ou tonbe nan yon kanal oswa nan yon lak. Kisa ou ta dwe fè anvan?","o":["Rele pou èd epi tann andedan","Tann jiskaske machin nan plen dlo","Limen limyè ijans yo","Retire senti ou, louvri yon fenèt epi soti"],"h1":"Panse ak konbyen vit ou bezwen kite machin nan.","h2":"Ou ta dwe aji touswit: retire senti sekirite ou, louvri oswa kase yon fenèt, epi soti anvan dlo a monte twò wo.","p":"Se sa. Retire senti ou, louvri yon fenèt epi soti vit."},"ref":{"doc":"FL","page":80}},{"id":"safe-driving-029","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"After a hurricane, water covers the road ahead and you cannot see how deep it is. What should you do?","o":["Drive through it slowly","Turn around and find another way","Drive through it fast","Follow the car in front of you"],"h1":"Think about how little moving water it takes to move a car.","h2":"Even shallow moving water can sweep a car away, and you cannot see what is under it, so turn around and find another way.","p":"Right. Turn around and do not drive into flooded roads."},"es":{"q":"Después de un huracán, el agua cubre la calle adelante y no puede ver qué tan profunda es. ¿Qué debe hacer?","o":["Pasar despacio por el agua","Dar la vuelta y buscar otro camino","Pasar rápido por el agua","Seguir al carro de adelante"],"h1":"Piense en qué poca agua en movimiento basta para mover un carro.","h2":"Aun el agua poco profunda en movimiento puede arrastrar un carro, y usted no ve lo que hay debajo, así que dé la vuelta y busque otro camino.","p":"Correcto. Dé la vuelta y no maneje por calles inundadas."},"zh":{"q":"飓风过后，前面的路被水淹了，你看不出水有多深。你应该怎么做？","o":["慢慢开过去","掉头，找别的路","快速开过去","跟着前面的车开"],"h1":"想一想只要很少的流动的水就能冲走一辆车。","h2":"即使是很浅的流动的水也可能把车冲走，而且你看不到水下有什么，所以要掉头找别的路。","p":"对。掉头，不要开进被水淹的路。"},"vi":{"q":"Sau một cơn bão, nước ngập đường phía trước và bạn không thấy nước sâu bao nhiêu. Bạn nên làm gì?","o":["Lái chậm qua","Quay đầu và tìm đường khác","Lái nhanh qua","Đi theo xe phía trước"],"h1":"Hãy nghĩ xem chỉ cần một ít nước chảy là có thể cuốn trôi xe.","h2":"Ngay cả nước chảy nông cũng có thể cuốn trôi xe, và bạn không thấy được bên dưới có gì, nên hãy quay đầu và tìm đường khác.","p":"Đúng. Quay đầu và đừng lái vào đường bị ngập."},"tl":{"q":"Pagkatapos ng bagyo, may tubig na tumatakip sa daan sa unahan at hindi mo makita kung gaano ito kalalim. Ano ang dapat mong gawin?","o":["Dumaan dito nang dahan-dahan","Bumalik at maghanap ng ibang daan","Dumaan dito nang mabilis","Sundan ang kotse sa harap mo"],"h1":"Isipin kung gaano kaunting umaagos na tubig ang kailangan para matangay ang kotse.","h2":"Kahit mababaw na umaagos na tubig ay puwedeng tumangay ng kotse, at hindi mo nakikita kung ano ang nasa ilalim nito, kaya bumalik at maghanap ng ibang daan.","p":"Tama. Bumalik at huwag dumaan sa bahang daan."},"ar":{"q":"بعد إعصار، الماء يغطي الطريق أمامك ولا تستطيع أن ترى عمقه. ماذا يجب أن تفعل؟","o":["اعبره ببطء","ارجع وابحث عن طريق آخر","اعبره بسرعة","اتبع السيارة التي أمامك"],"h1":"فكّر: كم قليلًا من الماء الجاري يكفي لتحريك سيارة؟","h2":"حتى الماء الجاري غير العميق يمكن أن يجرف السيارة، ولا تستطيع أن ترى ما تحته، لذلك ارجع وابحث عن طريق آخر.","p":"صحيح. ارجع ولا تدخل الطرق المغمورة بالماء."},"ht":{"q":"Apre yon siklòn, dlo kouvri wout la devan w epi ou pa ka wè ki fon li ye. Kisa ou ta dwe fè?","o":["Travèse l dousman","Vire tounen epi chèche yon lòt chemen","Travèse l vit","Swiv machin ki devan w lan"],"h1":"Panse ak jan yon ti kras dlo k ap koule ase pou deplase yon machin.","h2":"Menm yon dlo ki pa fon, si l ap koule, ka pote yon machin ale, epi ou pa ka wè sa ki anba l, kidonk vire tounen epi chèche yon lòt chemen.","p":"Se sa. Vire tounen epi pa kondi antre nan wout ki inonde."},"ref":{"doc":"FL","page":72}},{"id":"safe-driving-030","scope":"FL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Florida, after a storm, you reach an intersection where the traffic light is dark because the power is out. What should you do?","o":["Drive through without stopping","Stop only if a car is coming","Treat it like a four-way stop","Wait until the light works again"],"h1":"Think about how drivers take turns when there is no signal.","h2":"In Florida, a traffic light that is out works like a four-way stop, so you stop fully and take turns with the other drivers.","p":"Right. A dark traffic light works like a four-way stop."},"es":{"q":"En Florida, después de una tormenta, llega a un cruce donde el semáforo está apagado porque no hay luz. ¿Qué debe hacer?","o":["Pasar sin parar","Parar solo si viene un carro","Tratarlo como un pare de cuatro vías","Esperar hasta que el semáforo funcione"],"h1":"Piense en cómo se turnan los conductores cuando no hay semáforo.","h2":"En Florida, un semáforo apagado funciona como un pare de cuatro vías, así que debe parar por completo y turnarse con los otros conductores.","p":"Correcto. Un semáforo apagado funciona como un pare de cuatro vías."},"zh":{"q":"在 Florida，暴风雨过后，你到了一个路口，因为停电，红绿灯不亮了。你应该怎么做？","o":["不停车，直接开过去","只有在有车过来时才停车","把它当作四向停车路口","等到红绿灯恢复正常"],"h1":"想一想没有信号灯时，司机们怎样轮流通过。","h2":"在 Florida，不亮的红绿灯就像四向停车路口一样，所以你要完全停下，和其他司机轮流通过。","p":"对。不亮的红绿灯就像四向停车路口。"},"vi":{"q":"Ở Florida, sau một cơn bão, bạn đến một ngã tư mà đèn giao thông bị tắt vì mất điện. Bạn nên làm gì?","o":["Chạy qua mà không dừng","Chỉ dừng nếu có xe đang tới","Xem như ngã tư có biển STOP ở cả bốn hướng","Chờ đến khi đèn hoạt động lại"],"h1":"Hãy nghĩ xem các tài xế thay phiên nhau đi như thế nào khi không có đèn tín hiệu.","h2":"Ở Florida, đèn giao thông bị tắt được xem như ngã tư có biển STOP ở cả bốn hướng, nên bạn dừng hẳn lại và thay phiên đi với các tài xế khác.","p":"Đúng. Đèn giao thông bị tắt được xem như ngã tư có biển STOP ở cả bốn hướng."},"tl":{"q":"Sa Florida, pagkatapos ng bagyo, nakarating ka sa intersection kung saan patay ang traffic light dahil walang kuryente. Ano ang dapat mong gawin?","o":["Dumaan nang hindi humihinto","Huminto lang kung may paparating na kotse","Ituring itong four-way stop","Maghintay hanggang gumana ulit ang ilaw"],"h1":"Isipin kung paano nagsasalitan ang mga driver kapag walang signal.","h2":"Sa Florida, ang patay na traffic light ay gumagana na parang four-way stop, kaya huminto ka nang buo at makipagsalitan sa ibang mga driver.","p":"Tama. Ang patay na traffic light ay gumagana na parang four-way stop."},"ar":{"q":"في Florida، بعد عاصفة، وصلت إلى تقاطع إشارة المرور فيه مطفأة لأن الكهرباء مقطوعة. ماذا يجب أن تفعل؟","o":["مُرّ بدون أن تتوقف","توقف فقط إذا كانت هناك سيارة قادمة","تعامل معه مثل تقاطع فيه توقف من أربع جهات","انتظر حتى تعمل الإشارة مرة أخرى"],"h1":"فكّر في كيف يتناوب السائقون عندما لا توجد إشارة.","h2":"في Florida، إشارة المرور المطفأة تعمل مثل تقاطع فيه توقف من أربع جهات، لذلك تتوقف توقفًا كاملًا وتتناوب مع السائقين الآخرين.","p":"صحيح. إشارة المرور المطفأة تعمل مثل توقف من أربع جهات."},"ht":{"q":"Nan Florida, apre yon tanpèt, ou rive nan yon kafou kote limyè trafik la etenn paske kouran an koupe. Kisa ou ta dwe fè?","o":["Pase san ou pa kanpe","Kanpe sèlman si gen yon machin k ap vini","Fè tankou se yon kafou ki gen STOP nan kat bò","Tann jiskaske limyè a mache ankò"],"h1":"Panse ak jan chofè yo pran tou yo lè pa gen siyal.","h2":"Nan Florida, yon limyè trafik ki pa mache travay tankou yon STOP nan kat bò, kidonk ou kanpe nèt epi ou pran tou pa w ak lòt chofè yo.","p":"Se sa. Yon limyè trafik ki etenn travay tankou yon STOP nan kat bò."},"ref":{"doc":"FL","page":79}},{"id":"safe-driving-031","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"At night, a car coming toward you has very bright headlights. Where should you look?","o":["Toward the right edge of your lane","Straight into the other car's lights","At the center line","Down at your dashboard"],"h1":"Think about a guide that keeps you in your lane without looking at the glare.","h2":"Looking toward the right edge of your lane keeps you on the road while you avoid looking straight into the glare.","p":"Right. Look toward the right edge of your lane to avoid glare."},"es":{"q":"De noche, un carro que viene hacia usted tiene las luces muy fuertes. ¿Hacia dónde debe mirar?","o":["Hacia la orilla derecha de su carril","Directo a las luces del otro carro","A la línea del centro","Hacia abajo, al tablero"],"h1":"Piense en una guía que lo mantenga en su carril sin mirar el resplandor.","h2":"Mirar hacia la orilla derecha de su carril lo mantiene en la vía mientras evita mirar directo al resplandor.","p":"Correcto. Mire hacia la orilla derecha de su carril para evitar el resplandor."},"zh":{"q":"晚上，对面开来的车车灯很亮。你应该看哪里？","o":["看向你车道的右边边缘","直直看着对面车的灯","看中线","往下看仪表板"],"h1":"想一想有什么能让你留在车道上，又不用看刺眼的光。","h2":"看向你车道的右边边缘，可以让你留在路上，同时避免直接看刺眼的光。","p":"对。看向你车道的右边边缘，避开刺眼的光。"},"vi":{"q":"Ban đêm, một xe đi ngược chiều có đèn pha rất sáng. Bạn nên nhìn về đâu?","o":["Về phía mép phải làn đường của bạn","Nhìn thẳng vào đèn của xe kia","Vào vạch giữa đường","Nhìn xuống bảng đồng hồ"],"h1":"Hãy nghĩ đến một điểm giúp bạn giữ đúng làn mà không phải nhìn vào ánh chói.","h2":"Nhìn về phía mép phải làn đường giúp bạn giữ xe trên đường mà không phải nhìn thẳng vào ánh chói.","p":"Đúng. Nhìn về phía mép phải làn đường để tránh ánh chói."},"tl":{"q":"Sa gabi, napakaliwanag ng headlights ng kotseng paparating sa iyo. Saan ka dapat tumingin?","o":["Sa kanang gilid ng lane mo","Diretso sa ilaw ng kabilang kotse","Sa center line (gitnang guhit)","Pababa sa dashboard mo"],"h1":"Isipin ang gabay na nagpapanatili sa iyo sa lane mo nang hindi tumitingin sa nakasisilaw na ilaw.","h2":"Ang pagtingin sa kanang gilid ng lane mo ay nagpapanatili sa iyo sa daan habang iniiwasan mong tumingin nang diretso sa nakasisilaw na ilaw.","p":"Tama. Tumingin sa kanang gilid ng lane mo para iwasan ang silaw."},"ar":{"q":"في الليل، سيارة قادمة نحوك أضواؤها قوية جدًا. إلى أين يجب أن تنظر؟","o":["نحو الحافة اليمنى لمسارك","مباشرة إلى أضواء السيارة الأخرى","إلى الخط الأوسط","إلى الأسفل نحو لوحة العدادات"],"h1":"فكّر في دليل يُبقيك في مسارك بدون أن تنظر إلى الضوء الساطع.","h2":"النظر نحو الحافة اليمنى لمسارك يُبقيك على الطريق، وفي نفس الوقت تتجنب النظر مباشرة إلى الضوء الساطع.","p":"صحيح. انظر نحو الحافة اليمنى لمسارك لتتجنب الضوء الساطع."},"ht":{"q":"Lannwit, yon machin k ap vini sou ou gen limyè devan ki klere anpil. Ki kote ou ta dwe gade?","o":["Bò dwat liy ou a","Dirèkteman nan limyè lòt machin nan","Liy ki nan mitan wout la","Anba, sou tablodbò ou"],"h1":"Panse ak yon gid ki kenbe w nan liy ou san ou pa gade nan limyè a ki ap avegle w.","h2":"Lè ou gade bò dwat liy ou a, ou rete sou wout la pandan ou evite gade dirèkteman nan limyè ki ap avegle w la.","p":"Se sa. Gade bò dwat liy ou a pou evite limyè a avegle w."},"ref":{"doc":"FL","page":73}},{"id":"safe-driving-032","scope":"FL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Florida, you are using high beams at night. When must you switch to low beams for a car coming toward you?","o":["Within 100 feet of it","Within 200 feet of it","Only when it flashes its lights","Within 500 feet of it"],"h1":"Think about a long distance, because bright lights reach far.","h2":"In Florida you must dim your high beams when an oncoming car is within 500 feet, so its driver is not blinded.","p":"Right. Dim your high beams within 500 feet of an oncoming car."},"es":{"q":"En Florida, usted usa las luces altas de noche. ¿Cuándo debe cambiar a luces bajas por un carro que viene de frente?","o":["A 100 pies de él","A 200 pies de él","Solo cuando le haga cambio de luces","A 500 pies de él"],"h1":"Piense en una distancia larga, porque las luces altas llegan lejos.","h2":"En Florida debe bajar las luces altas cuando un carro que viene de frente está a 500 pies o menos, para no encandilar al conductor.","p":"Correcto. Baje las luces altas a 500 pies de un carro que viene de frente."},"zh":{"q":"在 Florida，你晚上开着远光灯。对面来车时，你必须在多远的距离内换成近光灯？","o":["在 100 英尺内","在 200 英尺内","只在它闪灯时","在 500 英尺内"],"h1":"想一想一个很长的距离，因为亮的灯照得很远。","h2":"在 Florida，对面来车在 500 英尺以内时，你必须把远光灯调暗，这样对面的司机才不会被照得看不见。","p":"对。对面来车在 500 英尺内时，把远光灯调暗。"},"vi":{"q":"Ở Florida, bạn đang bật đèn pha (đèn chiếu xa) vào ban đêm. Khi nào bạn phải chuyển sang đèn cốt (đèn chiếu gần) vì có xe đi ngược chiều?","o":["Khi cách xe đó trong vòng 100 feet","Khi cách xe đó trong vòng 200 feet","Chỉ khi xe đó nháy đèn","Khi cách xe đó trong vòng 500 feet"],"h1":"Hãy nghĩ đến một khoảng cách xa, vì đèn sáng chiếu được rất xa.","h2":"Ở Florida, bạn phải hạ đèn pha khi xe đi ngược chiều cách bạn trong vòng 500 feet, để tài xế kia không bị chói mắt.","p":"Đúng. Hạ đèn pha khi cách xe đi ngược chiều trong vòng 500 feet."},"tl":{"q":"Sa Florida, gumagamit ka ng high beams sa gabi. Kailan ka dapat lumipat sa low beams para sa kotseng paparating sa iyo?","o":["Sa loob ng 100 feet mula rito","Sa loob ng 200 feet mula rito","Kapag nag-flash lang ito ng ilaw","Sa loob ng 500 feet mula rito"],"h1":"Isipin ang mahabang distansya, dahil malayo ang naaabot ng maliwanag na ilaw.","h2":"Sa Florida, dapat mong ibaba ang high beams mo kapag ang paparating na kotse ay nasa loob ng 500 feet, para hindi masilaw ang driver nito.","p":"Tama. Ibaba ang high beams mo sa loob ng 500 feet mula sa paparating na kotse."},"ar":{"q":"في Florida، تستعمل الأضواء العالية في الليل. متى يجب أن تنتقل إلى الأضواء المنخفضة بسبب سيارة قادمة نحوك؟","o":["عندما تكون على بعد 100 قدم (feet) منها","عندما تكون على بعد 200 قدم (feet) منها","فقط عندما تومض بأضوائها","عندما تكون على بعد 500 قدم (feet) منها"],"h1":"فكّر في مسافة طويلة، لأن الأضواء القوية تصل بعيدًا.","h2":"في Florida يجب أن تخفّض أضواءك العالية عندما تكون السيارة القادمة على بعد 500 قدم (feet)، حتى لا يُبهَر سائقها.","p":"صحيح. خفّض أضواءك العالية على بعد 500 قدم (feet) من السيارة القادمة."},"ht":{"q":"Nan Florida, w ap sèvi ak gwo limyè (high beams) lannwit. Ki lè ou dwe mete ti limyè (low beams) pou yon machin k ap vini sou ou?","o":["Lè li nan 100 pye","Lè li nan 200 pye","Sèlman lè li limen limyè li plizyè fwa","Lè li nan 500 pye"],"h1":"Panse ak yon long distans, paske limyè ki klere fò rive lwen.","h2":"Nan Florida, ou dwe bese gwo limyè ou yo lè yon machin k ap vini sou ou nan 500 pye, pou chofè li a pa avegle.","p":"Se sa. Bese gwo limyè ou yo lè yon machin k ap vini sou ou nan 500 pye."},"ref":{"doc":"FL","page":73}},{"id":"safe-driving-033","scope":"FL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Florida, you are following another car at night. When must you use low beams?","o":["Within 100 feet of it","Within 300 feet of it","Within 1,000 feet of it","Only in the city"],"h1":"Think about your lights shining into the other driver's mirrors.","h2":"In Florida you must use low beams when you are within 300 feet behind another car, so your lights do not blind its driver in the mirrors.","p":"Right. Use low beams within 300 feet of the car ahead."},"es":{"q":"En Florida, usted va detrás de otro carro de noche. ¿Cuándo debe usar luces bajas?","o":["A 100 pies de él","A 300 pies de él","A 1,000 pies de él","Solo en la ciudad"],"h1":"Piense en sus luces brillando en los espejos del otro conductor.","h2":"En Florida debe usar luces bajas cuando está a 300 pies o menos detrás de otro carro, para que sus luces no encandilen al conductor en los espejos.","p":"Correcto. Use luces bajas a 300 pies del carro de adelante."},"zh":{"q":"在 Florida，你晚上跟在另一辆车后面。你必须在多远的距离内用近光灯？","o":["在 100 英尺内","在 300 英尺内","在 1,000 英尺内","只在城市里"],"h1":"想一想你的车灯照进前面司机的后视镜。","h2":"在 Florida，当你在另一辆车后面 300 英尺以内时，必须用近光灯，这样你的灯光才不会通过后视镜晃到那位司机的眼睛。","p":"对。离前车 300 英尺以内时用近光灯。"},"vi":{"q":"Ở Florida, bạn đang chạy sau một xe khác vào ban đêm. Khi nào bạn phải dùng đèn cốt (đèn chiếu gần)?","o":["Khi cách xe đó trong vòng 100 feet","Khi cách xe đó trong vòng 300 feet","Khi cách xe đó trong vòng 1,000 feet","Chỉ trong thành phố"],"h1":"Hãy nghĩ đến đèn của bạn chiếu vào gương của tài xế kia.","h2":"Ở Florida, bạn phải dùng đèn cốt khi chạy sau một xe khác trong vòng 300 feet, để đèn của bạn không làm tài xế đó chói mắt qua gương.","p":"Đúng. Dùng đèn cốt khi cách xe phía trước trong vòng 300 feet."},"tl":{"q":"Sa Florida, sumusunod ka sa ibang kotse sa gabi. Kailan ka dapat gumamit ng low beams?","o":["Sa loob ng 100 feet mula rito","Sa loob ng 300 feet mula rito","Sa loob ng 1,000 feet mula rito","Sa lungsod lang"],"h1":"Isipin ang ilaw mo na tumatama sa mga salamin ng kabilang driver.","h2":"Sa Florida, dapat kang gumamit ng low beams kapag nasa loob ka ng 300 feet sa likod ng ibang kotse, para hindi masilaw ang driver nito sa mga salamin.","p":"Tama. Gumamit ng low beams sa loob ng 300 feet mula sa kotse sa unahan."},"ar":{"q":"في Florida، أنت تسير خلف سيارة أخرى في الليل. متى يجب أن تستعمل الأضواء المنخفضة؟","o":["عندما تكون على بعد 100 قدم (feet) منها","عندما تكون على بعد 300 قدم (feet) منها","عندما تكون على بعد 1,000 قدم (feet) منها","في المدينة فقط"],"h1":"فكّر في أضوائك وهي تلمع في مرايا السائق الآخر.","h2":"في Florida يجب أن تستعمل الأضواء المنخفضة عندما تكون على بعد 300 قدم (feet) خلف سيارة أخرى، حتى لا تُبهر أضواؤك سائقها في المرايا.","p":"صحيح. استعمل الأضواء المنخفضة على بعد 300 قدم (feet) من السيارة التي أمامك."},"ht":{"q":"Nan Florida, w ap swiv yon lòt machin lannwit. Ki lè ou dwe sèvi ak ti limyè (low beams)?","o":["Lè ou nan 100 pye dèyè l","Lè ou nan 300 pye dèyè l","Lè ou nan 1,000 pye dèyè l","Sèlman nan vil la"],"h1":"Panse ak limyè ou k ap klere nan retwovizè lòt chofè a.","h2":"Nan Florida, ou dwe sèvi ak ti limyè lè ou nan 300 pye dèyè yon lòt machin, pou limyè ou yo pa avegle chofè a nan retwovizè li yo.","p":"Se sa. Sèvi ak ti limyè lè ou nan 300 pye dèyè machin ki devan w lan."},"ref":{"doc":"FL","page":73}},{"id":"safe-driving-034","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"What does it mean to \"overdrive your headlights\" at night?","o":["Using high beams in the city","Driving with only parking lights on","Driving too fast to stop within the area your lights show","Leaving your lights on after you park"],"h1":"Think about how far ahead you can see at night.","h2":"If you drive so fast that you cannot stop within the distance your headlights light up, you are overdriving them, so slow down at night.","p":"Right. Drive slow enough to stop within what your headlights show."},"es":{"q":"¿Qué significa manejar más rápido de lo que alcanzan sus luces de noche?","o":["Usar luces altas en la ciudad","Manejar solo con luces de estacionamiento","Ir tan rápido que no puede parar dentro de lo que alumbran sus luces","Dejar las luces encendidas al estacionar"],"h1":"Piense en qué tan lejos puede ver de noche.","h2":"Si maneja tan rápido que no puede parar dentro de la distancia que alumbran sus faros, va más rápido de lo que alcanzan sus luces, así que baje la velocidad de noche.","p":"Correcto. Maneje a una velocidad que le permita parar dentro de lo que alumbran sus luces."},"zh":{"q":"晚上“开得比车灯照得更远”是什么意思？","o":["在城市里用远光灯","只开着停车灯开车","开得太快，无法在车灯照亮的范围内停下","停车后没有关车灯"],"h1":"想一想晚上你能看到前面多远。","h2":"如果你开得太快，在车头灯照亮的距离内停不下来，你就是开得比车灯照得更远，所以晚上要减速。","p":"对。开慢一点，要能在车头灯照到的范围内停下。"},"vi":{"q":"Ban đêm, \"chạy vượt tầm đèn pha\" (overdrive your headlights) có nghĩa là gì?","o":["Bật đèn pha trong thành phố","Lái xe chỉ bật đèn đậu xe","Lái quá nhanh nên không thể dừng trong vùng đèn chiếu tới","Để đèn sáng sau khi đậu xe"],"h1":"Hãy nghĩ xem ban đêm bạn nhìn thấy được xa đến đâu.","h2":"Nếu bạn lái nhanh đến mức không thể dừng trong khoảng đèn pha chiếu sáng, bạn đang chạy vượt tầm đèn pha, nên hãy chạy chậm lại vào ban đêm.","p":"Đúng. Lái đủ chậm để dừng được trong vùng đèn pha chiếu tới."},"tl":{"q":"Ano ang ibig sabihin ng \"overdrive your headlights\" sa gabi?","o":["Paggamit ng high beams sa lungsod","Pagmamaneho na parking lights lang ang nakabukas","Pagmamaneho nang masyadong mabilis para huminto sa loob ng lugar na naiilawan ng ilaw mo","Pag-iwan na nakabukas ang ilaw pagka-park mo"],"h1":"Isipin kung gaano kalayo sa unahan ang nakikita mo sa gabi.","h2":"Kung masyado kang mabilis kaya hindi ka makahinto sa loob ng distansyang naiilawan ng headlights mo, ikaw ay nag-o-overdrive ng headlights, kaya bumagal sa gabi.","p":"Tama. Magmaneho nang sapat na bagal para makahinto sa loob ng naiilawan ng headlights mo."},"ar":{"q":"ماذا يعني أن \"تسبق أضواءك\" في الليل؟","o":["أن تستعمل الأضواء العالية في المدينة","أن تقود وأضواء الوقوف فقط مشغّلة","أن تقود بسرعة كبيرة لا تسمح لك بالتوقف داخل المسافة التي تضيئها أضواؤك","أن تترك أضواءك مشغّلة بعد أن توقف السيارة"],"h1":"فكّر: إلى أي مسافة أمامك تستطيع أن ترى في الليل؟","h2":"إذا قُدت بسرعة كبيرة لا تسمح لك بالتوقف داخل المسافة التي تضيئها أضواؤك الأمامية، فأنت تسبق أضواءك، لذلك خفّف السرعة في الليل.","p":"صحيح. قُد ببطء كافٍ لتتوقف داخل ما تُظهره أضواؤك الأمامية."},"ht":{"q":"Kisa sa vle di lè yo di w ap \"kondi pi vit pase limyè ou\" (overdrive your headlights) lannwit?","o":["Sèvi ak gwo limyè nan vil la","Kondi ak limyè pakin sèlman","Kondi twò vit pou w ka kanpe nan espas limyè ou montre w la","Kite limyè ou limen apre ou pake"],"h1":"Panse ak konbyen lwen devan ou ka wè lannwit.","h2":"Si w ap kondi tèlman vit ke ou pa ka kanpe nan distans limyè devan ou yo klere a, w ap kondi pi vit pase limyè ou, kidonk ralanti lannwit.","p":"Se sa. Kondi dousman ase pou w ka kanpe nan espas limyè devan ou yo montre w."},"ref":{"doc":"FL","page":73}},{"id":"safe-driving-035","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"You are driving in thick fog. Which lights should you use?","o":["Low beams","High beams","Parking lights only","No lights"],"h1":"Think about how bright light bounces back off fog.","h2":"High beams reflect off the fog and make it harder to see, so you should use low beams and slow down.","p":"Right. Use low beams in fog."},"es":{"q":"Usted maneja con neblina espesa. ¿Qué luces debe usar?","o":["Luces bajas","Luces altas","Solo luces de estacionamiento","Ninguna luz"],"h1":"Piense en cómo la luz fuerte rebota en la neblina.","h2":"Las luces altas rebotan en la neblina y hacen más difícil ver, así que debe usar luces bajas y bajar la velocidad.","p":"Correcto. Use luces bajas con neblina."},"zh":{"q":"你在浓雾里开车。你应该用哪种灯？","o":["近光灯","远光灯","只开停车灯","不开灯"],"h1":"想一想亮光碰到雾会怎样反射回来。","h2":"远光灯会被雾反射回来，让你更难看清，所以你应该用近光灯并减速。","p":"对。雾天用近光灯。"},"vi":{"q":"Bạn đang lái xe trong sương mù dày. Bạn nên dùng đèn nào?","o":["Đèn cốt (đèn chiếu gần)","Đèn pha (đèn chiếu xa)","Chỉ đèn đậu xe","Không bật đèn"],"h1":"Hãy nghĩ xem ánh sáng mạnh bị sương mù phản chiếu lại như thế nào.","h2":"Đèn pha phản chiếu lại từ sương mù và làm bạn khó nhìn hơn, nên bạn nên dùng đèn cốt và chạy chậm lại.","p":"Đúng. Dùng đèn cốt khi có sương mù."},"tl":{"q":"Nagmamaneho ka sa makapal na fog (hamog). Anong ilaw ang dapat mong gamitin?","o":["Low beams","High beams","Parking lights lang","Walang ilaw"],"h1":"Isipin kung paano tumatalbog pabalik ang maliwanag na ilaw mula sa fog.","h2":"Tumatalbog ang high beams sa fog at nagpapahirap makakita, kaya dapat kang gumamit ng low beams at bumagal.","p":"Tama. Gumamit ng low beams sa fog."},"ar":{"q":"أنت تقود في ضباب كثيف. أي أضواء يجب أن تستعمل؟","o":["الأضواء المنخفضة","الأضواء العالية","أضواء الوقوف فقط","بدون أضواء"],"h1":"فكّر في كيف يرتد الضوء القوي عن الضباب.","h2":"الأضواء العالية ترتد عن الضباب وتجعل الرؤية أصعب، لذلك يجب أن تستعمل الأضواء المنخفضة وتخفّف السرعة.","p":"صحيح. استعمل الأضواء المنخفضة في الضباب."},"ht":{"q":"W ap kondi nan yon bwouya ki epè. Ki limyè ou ta dwe sèvi?","o":["Ti limyè (low beams)","Gwo limyè (high beams)","Limyè pakin sèlman","Okenn limyè"],"h1":"Panse ak jan limyè ki klere fò tounen sou bwouya a.","h2":"Gwo limyè yo frape bwouya a epi tounen sou ou, sa ki fè li pi difisil pou w wè, kidonk ou ta dwe sèvi ak ti limyè epi ralanti.","p":"Se sa. Sèvi ak ti limyè nan bwouya."},"ref":{"doc":"FL","page":71}},{"id":"safe-driving-036","scope":"FL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Florida, it is raining and your wipers are on. What must you also turn on?","o":["Your hazard lights","Your high beams","Your inside dome light","Your headlights"],"h1":"Think about helping other drivers see your car in the rain.","h2":"In Florida you must turn on your headlights when you drive in rain, smoke or fog, so other drivers can see you.","p":"Right. In the rain, turn on your headlights."},"es":{"q":"En Florida, está lloviendo y tiene los limpiaparabrisas encendidos. ¿Qué más debe encender?","o":["Las luces de emergencia","Las luces altas","La luz interior del techo","Los faros delanteros"],"h1":"Piense en ayudar a otros conductores a ver su carro en la lluvia.","h2":"En Florida debe encender los faros delanteros cuando maneja con lluvia, humo o neblina, para que otros conductores lo vean.","p":"Correcto. Con lluvia, encienda los faros delanteros."},"zh":{"q":"在 Florida，正在下雨，你的雨刷开着。你还必须打开什么？","o":["你的危险警示灯","你的远光灯","车内顶灯","你的车头灯"],"h1":"想一想怎样帮助其他司机在雨中看到你的车。","h2":"在 Florida，你在雨中、烟中或雾中开车时，必须打开车头灯，这样其他司机才能看到你。","p":"对。下雨时，打开车头灯。"},"vi":{"q":"Ở Florida, trời đang mưa và cần gạt nước của bạn đang bật. Bạn còn phải bật gì nữa?","o":["Đèn khẩn cấp","Đèn pha (đèn chiếu xa)","Đèn trần trong xe","Đèn trước của xe"],"h1":"Hãy nghĩ đến việc giúp các tài xế khác nhìn thấy xe bạn trong mưa.","h2":"Ở Florida, bạn phải bật đèn trước khi lái xe trong mưa, khói hoặc sương mù, để các tài xế khác nhìn thấy bạn.","p":"Đúng. Khi trời mưa, hãy bật đèn trước."},"tl":{"q":"Sa Florida, umuulan at nakabukas ang wipers mo. Ano pa ang dapat mong i-on?","o":["Ang hazard lights mo","Ang high beams mo","Ang ilaw sa loob ng kotse","Ang headlights mo"],"h1":"Isipin ang pagtulong sa ibang driver na makita ang kotse mo sa ulan.","h2":"Sa Florida, dapat mong i-on ang headlights mo kapag nagmamaneho ka sa ulan, usok, o fog, para makita ka ng ibang mga driver.","p":"Tama. Sa ulan, i-on ang headlights mo."},"ar":{"q":"في Florida، المطر ينزل والمساحات تعمل. ماذا يجب أن تشغّل أيضًا؟","o":["أضواء التحذير","الأضواء العالية","الضوء الداخلي في السقف","الأضواء الأمامية"],"h1":"فكّر في مساعدة السائقين الآخرين على رؤية سيارتك في المطر.","h2":"في Florida يجب أن تشغّل الأضواء الأمامية عندما تقود في المطر أو الدخان أو الضباب، حتى يراك السائقون الآخرون.","p":"صحيح. في المطر، شغّل الأضواء الأمامية."},"ht":{"q":"Nan Florida, lapli ap tonbe epi wipè ou yo limen. Kisa ou dwe limen tou?","o":["Limyè ijans ou yo","Gwo limyè ou yo","Limyè andedan machin nan","Limyè devan ou yo"],"h1":"Panse ak ede lòt chofè yo wè machin ou nan lapli a.","h2":"Nan Florida, ou dwe limen limyè devan ou yo lè w ap kondi nan lapli, lafimen oswa bwouya, pou lòt chofè yo ka wè w.","p":"Se sa. Nan lapli, limen limyè devan ou yo."},"ref":{"doc":"FL","page":72}},{"id":"safe-driving-037","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"When is a road often most slippery during a rain?","o":["After it has rained for hours","In the first few minutes of rain","Only at night","Only when the sun comes out"],"h1":"Think about oil on the road mixing with the first water.","h2":"At the start of a rain, water mixes with oil on the road and makes it very slippery, so slow down as soon as it starts to rain.","p":"Right. Roads are often most slippery in the first minutes of rain."},"es":{"q":"¿Cuándo está la vía a menudo más resbalosa durante la lluvia?","o":["Después de horas de lluvia","En los primeros minutos de lluvia","Solo de noche","Solo cuando sale el sol"],"h1":"Piense en el aceite de la vía mezclándose con la primera agua.","h2":"Al comenzar la lluvia, el agua se mezcla con el aceite de la vía y la pone muy resbalosa, así que baje la velocidad en cuanto empiece a llover.","p":"Correcto. La vía suele estar más resbalosa en los primeros minutos de lluvia."},"zh":{"q":"下雨时，路面通常什么时候最滑？","o":["下了几个小时雨以后","下雨的头几分钟","只在晚上","只在太阳出来时"],"h1":"想一想路上的油和最先落下的雨水混在一起。","h2":"刚开始下雨时，雨水和路上的油混在一起，让路面非常滑，所以一开始下雨就要减速。","p":"对。路面通常在下雨的头几分钟最滑。"},"vi":{"q":"Khi trời mưa, mặt đường thường trơn nhất vào lúc nào?","o":["Sau khi mưa đã nhiều giờ","Trong vài phút đầu của cơn mưa","Chỉ vào ban đêm","Chỉ khi mặt trời ló ra"],"h1":"Hãy nghĩ đến dầu trên mặt đường trộn với lượng nước đầu tiên.","h2":"Lúc bắt đầu mưa, nước trộn với dầu trên mặt đường và làm đường rất trơn, nên hãy chạy chậm lại ngay khi trời bắt đầu mưa.","p":"Đúng. Mặt đường thường trơn nhất trong những phút đầu của cơn mưa."},"tl":{"q":"Kailan kadalasang pinakamadulas ang daan kapag umuulan?","o":["Pagkatapos umulan nang ilang oras","Sa unang ilang minuto ng ulan","Sa gabi lang","Kapag lumabas na ang araw lang"],"h1":"Isipin ang langis sa daan na humahalo sa unang tubig.","h2":"Sa simula ng ulan, humahalo ang tubig sa langis sa daan at nagiging napakadulas ito, kaya bumagal agad kapag nagsimulang umulan.","p":"Tama. Kadalasang pinakamadulas ang daan sa unang mga minuto ng ulan."},"ar":{"q":"متى يكون الطريق غالبًا أكثر انزلاقًا أثناء المطر؟","o":["بعد أن يمطر لساعات","في الدقائق الأولى من المطر","في الليل فقط","فقط عندما تخرج الشمس"],"h1":"فكّر في الزيت على الطريق عندما يختلط بأول ماء.","h2":"في بداية المطر، يختلط الماء بالزيت على الطريق ويجعله زلقًا جدًا، لذلك خفّف السرعة بمجرد أن يبدأ المطر.","p":"صحيح. الطرق غالبًا تكون أكثر انزلاقًا في الدقائق الأولى من المطر."},"ht":{"q":"Ki lè yon wout souvan pi glise pandan lapli?","o":["Apre lapli fin tonbe pandan plizyè èdtan","Nan premye minit lapli a","Sèlman lannwit","Sèlman lè solèy la parèt"],"h1":"Panse ak lwil ki sou wout la k ap melanje ak premye dlo a.","h2":"Lè lapli a kòmanse, dlo a melanje ak lwil ki sou wout la epi li fè wout la glise anpil, kidonk ralanti depi lapli a kòmanse tonbe.","p":"Se sa. Wout yo souvan pi glise nan premye minit lapli a."},"ref":{"doc":"FL","page":72}},{"id":"safe-driving-038","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"You feel very sleepy while driving. What is the best thing to do?","o":["Open the window and keep going","Turn the radio up loud","Pull off safely and rest","Drink coffee and drive faster"],"h1":"Think about what really fixes being tired.","h2":"Cold air, loud music or coffee do not cure sleepiness, so the safe choice is to pull off the road safely and rest or sleep.","p":"Right. When you are sleepy, pull off safely and rest."},"es":{"q":"Siente mucho sueño mientras maneja. ¿Qué es lo mejor que puede hacer?","o":["Abrir la ventana y seguir","Subir el volumen de la radio","Salir de la vía con seguridad y descansar","Tomar café y manejar más rápido"],"h1":"Piense en lo que de verdad quita el cansancio.","h2":"El aire frío, la música fuerte o el café no quitan el sueño, así que lo seguro es salir de la vía con cuidado y descansar o dormir.","p":"Correcto. Si tiene sueño, salga de la vía con seguridad y descanse."},"zh":{"q":"你开车时觉得非常困。最好的做法是什么？","o":["打开车窗，继续开","把收音机开得很大声","安全地把车开到路边休息","喝咖啡，开快一点"],"h1":"想一想什么才能真正解决疲劳。","h2":"冷风、大声的音乐或咖啡都不能解决困倦，所以安全的做法是把车安全地开离道路，休息或睡一觉。","p":"对。困的时候，把车安全地开到路边休息。"},"vi":{"q":"Bạn thấy rất buồn ngủ khi đang lái xe. Điều tốt nhất nên làm là gì?","o":["Mở cửa sổ và lái tiếp","Mở radio thật lớn","Tấp vào lề an toàn và nghỉ ngơi","Uống cà phê và lái nhanh hơn"],"h1":"Hãy nghĩ xem điều gì thật sự giải quyết được sự mệt mỏi.","h2":"Không khí lạnh, nhạc lớn hay cà phê không chữa được buồn ngủ, nên cách an toàn là tấp vào lề an toàn và nghỉ ngơi hoặc ngủ.","p":"Đúng. Khi buồn ngủ, hãy tấp vào lề an toàn và nghỉ ngơi."},"tl":{"q":"Inaantok ka nang husto habang nagmamaneho. Ano ang pinakamabuting gawin?","o":["Buksan ang bintana at tumuloy","Lakasan ang radyo","Tumabi nang ligtas at magpahinga","Uminom ng kape at magmaneho nang mas mabilis"],"h1":"Isipin kung ano talaga ang nakakapagpawala ng pagod.","h2":"Hindi nagagamot ng malamig na hangin, malakas na musika, o kape ang antok, kaya ang ligtas na gawin ay tumabi nang ligtas sa daan at magpahinga o matulog.","p":"Tama. Kapag inaantok ka, tumabi nang ligtas at magpahinga."},"ar":{"q":"تشعر بنعاس شديد وأنت تقود. ما أفضل شيء تفعله؟","o":["افتح النافذة وتابع السير","ارفع صوت الراديو","اخرج من الطريق بأمان واسترح","اشرب قهوة وقُد بسرعة أكبر"],"h1":"فكّر في الشيء الذي يعالج التعب حقًا.","h2":"الهواء البارد أو الموسيقى العالية أو القهوة لا تعالج النعاس، لذلك الخيار الآمن هو أن تخرج من الطريق بأمان وتستريح أو تنام.","p":"صحيح. عندما تشعر بالنعاس، اخرج من الطريق بأمان واسترح."},"ht":{"q":"Ou santi w gen anpil dòmi pandan w ap kondi. Kisa ki pi bon bagay pou w fè?","o":["Louvri fenèt la epi kontinye","Mete radyo a fò","Soti sou bò wout la san danje epi repoze w","Bwè kafe epi kondi pi vit"],"h1":"Panse ak sa ki vrèman retire fatig.","h2":"Lè frèt, mizik fò oswa kafe pa retire dòmi, kidonk bon chwa a se soti sou bò wout la san danje epi repoze w oswa dòmi.","p":"Se sa. Lè ou gen dòmi, soti sou bò wout la san danje epi repoze w."},"ref":{"doc":"FL","page":35}},{"id":"safe-driving-039","scope":"FL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Florida, what is the legal blood alcohol limit for drivers age 21 and older?","o":["0.08 percent","0.10 percent","0.05 percent","0.15 percent"],"h1":"Think about the limit used for adult drivers in Florida.","h2":"In Florida an adult driver with a blood alcohol level of 0.08 percent or more is driving under the influence.","p":"Right. For drivers 21 and older, the limit is 0.08 percent."},"es":{"q":"En Florida, ¿cuál es el límite legal de alcohol en la sangre para conductores de 21 años o más?","o":["0.08 por ciento","0.10 por ciento","0.05 por ciento","0.15 por ciento"],"h1":"Piense en el límite que se usa para conductores adultos en Florida.","h2":"En Florida un conductor adulto con 0.08 por ciento o más de alcohol en la sangre está manejando bajo la influencia.","p":"Correcto. Para conductores de 21 años o más, el límite es 0.08 por ciento."},"zh":{"q":"在 Florida，21 岁及以上司机的法定血液酒精浓度上限是多少？","o":["0.08%","0.10%","0.05%","0.15%"],"h1":"想一想 Florida 成年司机用的上限。","h2":"在 Florida，成年司机的血液酒精浓度达到 0.08% 或更高，就是酒后驾驶。","p":"对。21 岁及以上的司机，上限是 0.08%。"},"vi":{"q":"Ở Florida, giới hạn nồng độ cồn trong máu theo luật cho tài xế từ 21 tuổi trở lên là bao nhiêu?","o":["0.08 phần trăm","0.10 phần trăm","0.05 phần trăm","0.15 phần trăm"],"h1":"Hãy nghĩ đến giới hạn dùng cho tài xế người lớn ở Florida.","h2":"Ở Florida, tài xế người lớn có nồng độ cồn trong máu từ 0.08 phần trăm trở lên là đang lái xe khi bị ảnh hưởng.","p":"Đúng. Với tài xế từ 21 tuổi trở lên, giới hạn là 0.08 phần trăm."},"tl":{"q":"Sa Florida, ano ang legal na blood alcohol limit para sa mga driver na 21 taong gulang pataas?","o":["0.08 porsyento","0.10 porsyento","0.05 porsyento","0.15 porsyento"],"h1":"Isipin ang limit na ginagamit para sa mga adult na driver sa Florida.","h2":"Sa Florida, ang adult na driver na may blood alcohol level na 0.08 porsyento o higit pa ay nagmamaneho nang lasing (DUI).","p":"Tama. Para sa mga driver na 21 pataas, ang limit ay 0.08 porsyento."},"ar":{"q":"في Florida، ما الحد القانوني لنسبة الكحول في الدم للسائقين الذين عمرهم 21 سنة أو أكثر؟","o":["0.08 بالمئة","0.10 بالمئة","0.05 بالمئة","0.15 بالمئة"],"h1":"فكّر في الحد المستعمل للسائقين البالغين في Florida.","h2":"في Florida، السائق البالغ الذي نسبة الكحول في دمه 0.08 بالمئة أو أكثر يقود تحت التأثير.","p":"صحيح. للسائقين بعمر 21 وأكثر، الحد هو 0.08 بالمئة."},"ht":{"q":"Nan Florida, ki limit legal alkòl nan san pou chofè ki gen 21 an oswa plis?","o":["0.08 pousan","0.10 pousan","0.05 pousan","0.15 pousan"],"h1":"Panse ak limit yo itilize pou chofè granmoun nan Florida.","h2":"Nan Florida, yon chofè granmoun ki gen yon nivo alkòl nan san 0.08 pousan oswa plis ap kondi sou enfliyans.","p":"Se sa. Pou chofè 21 an oswa plis, limit la se 0.08 pousan."},"ref":{"doc":"FL","page":25}},{"id":"safe-driving-040","scope":"FL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Florida, a driver under age 21 has a blood alcohol level of 0.02 percent. What happens?","o":["Nothing, it is below the adult limit","Only a warning is given","The car is taken away","The driver's license is suspended"],"h1":"Think about the stricter rule for young drivers.","h2":"Florida has a zero tolerance rule for drivers under 21, so a level of 0.02 percent or more leads to a license suspension.","p":"Right. Under 21, a 0.02 percent level means a license suspension."},"es":{"q":"En Florida, un conductor menor de 21 años tiene 0.02 por ciento de alcohol en la sangre. ¿Qué pasa?","o":["Nada, está por debajo del límite de adultos","Solo recibe una advertencia","Le quitan el carro","Le suspenden la licencia de conducir"],"h1":"Piense en la regla más estricta para conductores jóvenes.","h2":"Florida tiene una regla de cero tolerancia para menores de 21 años, así que un nivel de 0.02 por ciento o más lleva a la suspensión de la licencia.","p":"Correcto. Menor de 21, un nivel de 0.02 por ciento significa suspensión de la licencia."},"zh":{"q":"在 Florida，一位 21 岁以下的司机血液酒精浓度是 0.02%。会怎么样？","o":["什么事也没有，因为低于成年人的上限","只会给一个警告","车会被拿走","司机的驾照会被暂停"],"h1":"想一想对年轻司机更严格的规定。","h2":"Florida 对 21 岁以下的司机实行零容忍规定，所以浓度达到 0.02% 或更高，驾照就会被暂停。","p":"对。21 岁以下，浓度 0.02% 就会暂停驾照。"},"vi":{"q":"Ở Florida, một tài xế dưới 21 tuổi có nồng độ cồn trong máu là 0.02 phần trăm. Điều gì xảy ra?","o":["Không có gì, vì thấp hơn giới hạn của người lớn","Chỉ bị cảnh cáo","Xe bị tịch thu","Bằng lái của tài xế bị đình chỉ"],"h1":"Hãy nghĩ đến quy định nghiêm hơn cho tài xế trẻ.","h2":"Florida có quy định không khoan nhượng với tài xế dưới 21 tuổi, nên mức 0.02 phần trăm trở lên sẽ dẫn đến bị đình chỉ bằng lái.","p":"Đúng. Dưới 21 tuổi, mức 0.02 phần trăm nghĩa là bị đình chỉ bằng lái."},"tl":{"q":"Sa Florida, ang driver na wala pang 21 taong gulang ay may blood alcohol level na 0.02 porsyento. Ano ang mangyayari?","o":["Wala, mas mababa ito sa limit ng adult","Warning lang ang ibibigay","Kukunin ang kotse","Masususpinde ang lisensya ng driver"],"h1":"Isipin ang mas mahigpit na patakaran para sa mga batang driver.","h2":"May zero tolerance rule ang Florida para sa mga driver na wala pang 21, kaya ang level na 0.02 porsyento o higit pa ay nauuwi sa suspensyon ng lisensya.","p":"Tama. Kapag wala pang 21, ang level na 0.02 porsyento ay suspensyon ng lisensya."},"ar":{"q":"في Florida، سائق عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02 بالمئة. ماذا يحدث؟","o":["لا شيء، النسبة أقل من حد البالغين","يُعطى تحذيرًا فقط","تُؤخذ منه السيارة","تُوقف رخصة السائق"],"h1":"فكّر في القاعدة الأشد للسائقين الصغار.","h2":"في Florida قاعدة عدم التسامح مطلقًا للسائقين تحت 21 سنة، لذلك نسبة 0.02 بالمئة أو أكثر تؤدي إلى إيقاف الرخصة.","p":"صحيح. تحت 21 سنة، نسبة 0.02 بالمئة تعني إيقاف الرخصة."},"ht":{"q":"Nan Florida, yon chofè ki poko gen 21 an gen yon nivo alkòl nan san 0.02 pousan. Kisa k rive?","o":["Anyen, li anba limit granmoun yo","Yo ba l yon avètisman sèlman","Yo pran machin nan","Yo sispann lisans kondi chofè a"],"h1":"Panse ak règ ki pi sevè pou jèn chofè yo.","h2":"Florida gen yon règ zewo tolerans pou chofè ki poko gen 21 an, kidonk yon nivo 0.02 pousan oswa plis mennen nan yon sispansyon lisans.","p":"Se sa. Anba 21 an, yon nivo 0.02 pousan vle di yo sispann lisans ou."},"ref":{"doc":"FL","page":26}},{"id":"safe-driving-041","scope":"FL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Florida, you are lawfully arrested for DUI and refuse a breath test for the first time. What happens to your license?","o":["Nothing happens to it","It is suspended for one year","It is suspended for one week","You get a warning letter only"],"h1":"Think about what you agreed to when you got a Florida license.","h2":"By driving in Florida you agree to be tested, so a first refusal after a lawful DUI arrest suspends your license for one year.","p":"Right. A first refusal suspends your license for one year."},"es":{"q":"En Florida, usted es arrestado legalmente por DUI y se niega por primera vez a una prueba de aliento. ¿Qué pasa con su licencia?","o":["No le pasa nada","La suspenden por un año","La suspenden por una semana","Solo recibe una carta de advertencia"],"h1":"Piense en lo que aceptó cuando recibió una licencia de Florida.","h2":"Al manejar en Florida usted acepta hacerse la prueba, así que negarse por primera vez después de un arresto legal por DUI suspende su licencia por un año.","p":"Correcto. Negarse la primera vez suspende su licencia por un año."},"zh":{"q":"在 Florida，你因酒后驾驶 (DUI) 被合法逮捕，第一次拒绝呼气检测。你的驾照会怎么样？","o":["没有任何影响","被暂停一年","被暂停一个星期","你只会收到一封警告信"],"h1":"想一想你拿到 Florida 驾照时同意了什么。","h2":"在 Florida 开车，就表示你同意接受检测，所以在因 DUI 被合法逮捕后第一次拒绝，你的驾照会被暂停一年。","p":"对。第一次拒绝，驾照暂停一年。"},"vi":{"q":"Ở Florida, bạn bị bắt hợp pháp vì lái xe khi say (DUI) và từ chối thổi nồng độ cồn lần đầu. Bằng lái của bạn bị xử lý thế nào?","o":["Không có gì xảy ra","Bị đình chỉ một năm","Bị đình chỉ một tuần","Bạn chỉ nhận một thư cảnh cáo"],"h1":"Hãy nghĩ xem bạn đã đồng ý điều gì khi nhận bằng lái Florida.","h2":"Khi lái xe ở Florida, bạn đồng ý được kiểm tra, nên từ chối lần đầu sau khi bị bắt hợp pháp vì DUI sẽ làm bằng lái của bạn bị đình chỉ một năm.","p":"Đúng. Từ chối lần đầu làm bằng lái bị đình chỉ một năm."},"tl":{"q":"Sa Florida, legal kang inaresto dahil sa DUI at tumanggi ka sa breath test sa unang beses. Ano ang mangyayari sa lisensya mo?","o":["Walang mangyayari rito","Masususpinde ito nang isang taon","Masususpinde ito nang isang linggo","Warning letter lang ang matatanggap mo"],"h1":"Isipin kung ano ang pinayagan mo nang makakuha ka ng Florida license.","h2":"Sa pagmamaneho sa Florida, pumapayag kang ma-test, kaya ang unang pagtanggi pagkatapos ng legal na pag-aresto dahil sa DUI ay magsususpinde sa lisensya mo nang isang taon.","p":"Tama. Ang unang pagtanggi ay magsususpinde sa lisensya mo nang isang taon."},"ar":{"q":"في Florida، اعتُقلت بشكل قانوني بسبب القيادة تحت التأثير (DUI) ورفضت فحص النَّفَس للمرة الأولى. ماذا يحدث لرخصتك؟","o":["لا يحدث لها شيء","تُوقف لمدة سنة واحدة","تُوقف لمدة أسبوع واحد","تحصل على رسالة تحذير فقط"],"h1":"فكّر في ما وافقت عليه عندما حصلت على رخصة Florida.","h2":"بمجرد أنك تقود في Florida أنت توافق على الفحص، لذلك الرفض الأول بعد اعتقال قانوني بسبب DUI يوقف رخصتك لمدة سنة واحدة.","p":"صحيح. الرفض الأول يوقف رخصتك لمدة سنة واحدة."},"ht":{"q":"Nan Florida, yo arete w legalman pou DUI (kondi sou enfliyans) epi ou refize yon tès souf pou premye fwa. Kisa k rive lisans ou?","o":["Anyen pa rive l","Yo sispann li pou yon ane","Yo sispann li pou yon semèn","Ou jwenn yon lèt avètisman sèlman"],"h1":"Panse ak sa ou te dakò lè ou te jwenn yon lisans Florida.","h2":"Lè ou kondi nan Florida, ou dakò pou yo teste w, kidonk yon premye refi apre yon arestasyon legal pou DUI fè yo sispann lisans ou pou yon ane.","p":"Se sa. Yon premye refi fè yo sispann lisans ou pou yon ane."},"ref":{"doc":"FL","page":25}},{"id":"safe-driving-042","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"Which is the first thing alcohol harms in a driver?","o":["Hearing","Hand strength","Judgment","Eyesight in daylight"],"h1":"Think about making good choices, like deciding whether to drive.","h2":"Alcohol affects judgment first, so a driver may feel fine and still make bad choices, like speeding or deciding to drive at all.","p":"Right. Alcohol harms judgment first."},"es":{"q":"¿Qué es lo primero que el alcohol afecta en un conductor?","o":["El oído","La fuerza de las manos","El juicio","La vista de día"],"h1":"Piense en tomar buenas decisiones, como decidir si manejar.","h2":"El alcohol afecta primero el juicio, así que un conductor puede sentirse bien y aun así tomar malas decisiones, como ir rápido o decidir manejar.","p":"Correcto. El alcohol afecta primero el juicio."},"zh":{"q":"酒精首先伤害司机的哪一方面？","o":["听力","手的力气","判断力","白天的视力"],"h1":"想一想做出好的决定，例如决定要不要开车。","h2":"酒精首先影响判断力，所以司机可能觉得自己没事，但还是会做出坏的决定，例如超速，或者决定开车。","p":"对。酒精首先伤害判断力。"},"vi":{"q":"Rượu bia ảnh hưởng đến điều gì của tài xế đầu tiên?","o":["Thính giác","Sức mạnh của tay","Khả năng phán đoán","Thị lực vào ban ngày"],"h1":"Hãy nghĩ đến việc đưa ra lựa chọn đúng, như quyết định có nên lái xe hay không.","h2":"Rượu bia ảnh hưởng đến khả năng phán đoán đầu tiên, nên tài xế có thể thấy mình vẫn ổn mà vẫn đưa ra lựa chọn sai, như chạy quá tốc độ hoặc quyết định lái xe.","p":"Đúng. Rượu bia ảnh hưởng đến khả năng phán đoán đầu tiên."},"tl":{"q":"Ano ang unang napipinsala ng alak sa isang driver?","o":["Pandinig","Lakas ng kamay","Paghuhusga (judgment)","Paningin sa araw"],"h1":"Isipin ang paggawa ng mabuting desisyon, gaya ng pagpapasya kung magmamaneho ka.","h2":"Ang paghuhusga ang unang naaapektuhan ng alak, kaya puwedeng pakiramdam ng driver ay ayos lang siya pero gumagawa pa rin siya ng maling desisyon, gaya ng pag-overspeed o ng pagpapasyang magmaneho pa.","p":"Tama. Ang paghuhusga ang unang napipinsala ng alak."},"ar":{"q":"ما أول شيء يضرّه الكحول عند السائق؟","o":["السمع","قوة اليدين","حُسن التقدير","النظر في ضوء النهار"],"h1":"فكّر في اتخاذ القرارات الجيدة، مثل أن تقرر هل تقود أم لا.","h2":"الكحول يؤثر أولًا على حُسن التقدير، لذلك قد يشعر السائق أنه بخير ومع ذلك يتخذ قرارات سيئة، مثل السرعة أو أن يقرر القيادة أصلًا.","p":"صحيح. الكحول يضرّ حُسن التقدير أولًا."},"ht":{"q":"Ki premye bagay alkòl fè mal nan yon chofè?","o":["Zòrèy li (tande)","Fòs men li","Jijman li","Je li lajounen"],"h1":"Panse ak fè bon chwa, tankou deside si pou w kondi.","h2":"Alkòl touche jijman an anvan, kidonk yon chofè ka santi l byen epi li toujou fè move chwa, tankou kouri twò vit oswa deside kondi ditou.","p":"Se sa. Alkòl fè jijman an mal anvan."},"ref":{"doc":"FL","page":35}},{"id":"safe-driving-043","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"After drinking, what is the only thing that makes you sober?","o":["Time","Black coffee","A cold shower","Fresh air"],"h1":"Think about how the body gets rid of alcohol.","h2":"Your body removes alcohol slowly on its own, so only time makes you sober; coffee, showers and fresh air do not.","p":"Right. Only time makes you sober."},"es":{"q":"Después de tomar alcohol, ¿qué es lo único que le quita la borrachera?","o":["El tiempo","El café negro","Una ducha fría","El aire fresco"],"h1":"Piense en cómo el cuerpo elimina el alcohol.","h2":"Su cuerpo elimina el alcohol poco a poco por sí solo, así que solo el tiempo le quita la borrachera; el café, la ducha y el aire fresco no.","p":"Correcto. Solo el tiempo le quita la borrachera."},"zh":{"q":"喝酒以后，唯一能让你清醒的是什么？","o":["时间","黑咖啡","冷水澡","新鲜空气"],"h1":"想一想身体怎样排出酒精。","h2":"你的身体会自己慢慢排出酒精，所以只有时间能让你清醒；咖啡、洗澡和新鲜空气都不行。","p":"对。只有时间能让你清醒。"},"vi":{"q":"Sau khi uống rượu bia, điều duy nhất làm bạn tỉnh lại là gì?","o":["Thời gian","Cà phê đen","Tắm nước lạnh","Không khí trong lành"],"h1":"Hãy nghĩ xem cơ thể loại bỏ rượu bia như thế nào.","h2":"Cơ thể bạn tự loại bỏ rượu bia một cách chậm rãi, nên chỉ có thời gian mới làm bạn tỉnh; cà phê, tắm và không khí trong lành thì không.","p":"Đúng. Chỉ có thời gian mới làm bạn tỉnh."},"tl":{"q":"Pagkatapos uminom ng alak, ano lang ang tanging nakakapagpawala ng pagkalasing?","o":["Oras","Black coffee","Malamig na paligo","Sariwang hangin"],"h1":"Isipin kung paano inaalis ng katawan ang alak.","h2":"Dahan-dahang inaalis ng katawan mo ang alak nang kusa, kaya oras lang ang nakakapagpawala ng pagkalasing; hindi ito nagagawa ng kape, paligo, o sariwang hangin.","p":"Tama. Oras lang ang nakakapagpawala ng pagkalasing."},"ar":{"q":"بعد شرب الكحول، ما الشيء الوحيد الذي يجعلك تصحو؟","o":["الوقت","القهوة السوداء","الاستحمام بماء بارد","الهواء النقي"],"h1":"فكّر في كيف يتخلص الجسم من الكحول.","h2":"جسمك يتخلص من الكحول ببطء وحده، لذلك الوقت فقط يجعلك تصحو؛ القهوة والاستحمام والهواء النقي لا تفعل ذلك.","p":"صحيح. الوقت فقط يجعلك تصحو."},"ht":{"q":"Apre ou fin bwè, ki sèl bagay ki fè w pa sou ankò?","o":["Tan","Kafe nwa","Yon douch frèt","Bon lè fre"],"h1":"Panse ak jan kò a retire alkòl la.","h2":"Kò ou retire alkòl la dousman pou kont li, kidonk se sèlman tan ki fè w pa sou ankò; kafe, douch ak bon lè fre pa fè sa.","p":"Se sa. Se sèlman tan ki fè w pa sou ankò."}},{"id":"safe-driving-044","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"You took a cold medicine you bought at the store. What should you do before you drive?","o":["Nothing, store medicines are always safe","Drive only on small streets","Drink coffee to stay awake","Read the label for warnings about drowsiness"],"h1":"Think about side effects that can make you sleepy.","h2":"Many medicines you buy without a prescription can make you sleepy or slow, so read the label and do not drive if it warns about drowsiness.","p":"Right. Read the label and do not drive if the medicine makes you drowsy."},"es":{"q":"Usted tomó una medicina para el resfriado que compró en la tienda. ¿Qué debe hacer antes de manejar?","o":["Nada, las medicinas de tienda siempre son seguras","Manejar solo por calles pequeñas","Tomar café para no dormirse","Leer la etiqueta por advertencias de sueño"],"h1":"Piense en efectos que le pueden dar sueño.","h2":"Muchas medicinas que se compran sin receta pueden darle sueño o hacerlo más lento, así que lea la etiqueta y no maneje si advierte que causa sueño.","p":"Correcto. Lea la etiqueta y no maneje si la medicina le da sueño."},"zh":{"q":"你吃了在商店买的感冒药。开车前你应该做什么？","o":["什么都不用做，商店买的药都是安全的","只在小街上开","喝咖啡保持清醒","看标签上有没有会让人犯困的警告"],"h1":"想一想可能让你犯困的副作用。","h2":"很多不用处方就能买的药会让你犯困或反应变慢，所以要看标签，如果警告会犯困，就不要开车。","p":"对。看标签，如果药会让你犯困，就不要开车。"},"vi":{"q":"Bạn đã uống thuốc cảm mua ở cửa hàng. Bạn nên làm gì trước khi lái xe?","o":["Không cần gì, thuốc mua ở cửa hàng luôn an toàn","Chỉ lái trên đường nhỏ","Uống cà phê để tỉnh táo","Đọc nhãn thuốc xem có cảnh báo gây buồn ngủ không"],"h1":"Hãy nghĩ đến tác dụng phụ có thể làm bạn buồn ngủ.","h2":"Nhiều loại thuốc mua không cần toa có thể làm bạn buồn ngủ hoặc chậm chạp, nên hãy đọc nhãn và đừng lái xe nếu nhãn cảnh báo gây buồn ngủ.","p":"Đúng. Đọc nhãn thuốc và đừng lái xe nếu thuốc làm bạn buồn ngủ."},"tl":{"q":"Uminom ka ng gamot sa sipon na binili mo sa tindahan. Ano ang dapat mong gawin bago magmaneho?","o":["Wala, laging ligtas ang mga gamot sa tindahan","Magmaneho lang sa maliliit na kalye","Uminom ng kape para manatiling gising","Basahin ang label para sa babala tungkol sa pag-aantok"],"h1":"Isipin ang mga side effect na puwedeng magpaantok sa iyo.","h2":"Maraming gamot na nabibili nang walang reseta ang puwedeng magpaantok o magpabagal sa iyo, kaya basahin ang label at huwag magmaneho kung may babala ito tungkol sa pag-aantok.","p":"Tama. Basahin ang label at huwag magmaneho kung nakakaantok ang gamot."},"ar":{"q":"أخذت دواءً للزكام اشتريته من المتجر. ماذا يجب أن تفعل قبل أن تقود؟","o":["لا شيء، أدوية المتجر آمنة دائمًا","قُد في الشوارع الصغيرة فقط","اشرب قهوة لتبقى مستيقظًا","اقرأ الملصق لترى تحذيرات عن النعاس"],"h1":"فكّر في الآثار الجانبية التي قد تجعلك نعسانًا.","h2":"أدوية كثيرة تشتريها بدون وصفة طبية قد تجعلك نعسانًا أو بطيئًا، لذلك اقرأ الملصق ولا تقُد إذا كان يحذّر من النعاس.","p":"صحيح. اقرأ الملصق ولا تقُد إذا كان الدواء يجعلك نعسانًا."},"ht":{"q":"Ou pran yon remèd pou grip ou te achte nan magazen. Kisa ou ta dwe fè anvan ou kondi?","o":["Anyen, remèd magazen toujou san danje","Kondi sèlman nan ti lari","Bwè kafe pou w rete reveye","Li etikèt la pou wè si gen avètisman sou dòmi"],"h1":"Panse ak efè segondè ki ka ba w dòmi.","h2":"Anpil remèd ou achte san preskripsyon ka ba w dòmi oswa fè w vin lan, kidonk li etikèt la epi pa kondi si li avèti w sou dòmi.","p":"Se sa. Li etikèt la epi pa kondi si remèd la ba w dòmi."},"ref":{"doc":"FL","page":36}},{"id":"safe-driving-045","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"An angry driver is tailgating you and making rude gestures. What should you do?","o":["Brake suddenly to teach a lesson","Avoid eye contact and let the driver pass","Make the same gestures back","Speed up to get away"],"h1":"Think about how to calm the situation, not make it bigger.","h2":"Reacting can make an angry driver more dangerous, so stay calm, avoid eye contact, and let the driver go by when it is safe.","p":"Right. Stay calm, avoid eye contact and let the driver pass."},"es":{"q":"Un conductor enojado lo sigue muy de cerca y le hace gestos groseros. ¿Qué debe hacer?","o":["Frenar de repente para darle una lección","Evitar mirarlo a los ojos y dejarlo pasar","Hacerle los mismos gestos","Acelerar para alejarse"],"h1":"Piense en cómo calmar la situación, no en hacerla más grande.","h2":"Responder puede hacer más peligroso a un conductor enojado, así que mantenga la calma, evite mirarlo a los ojos y déjelo pasar cuando sea seguro.","p":"Correcto. Mantenga la calma, no lo mire a los ojos y déjelo pasar."},"zh":{"q":"一个生气的司机紧跟在你后面，还做粗鲁的手势。你应该怎么做？","o":["突然刹车给他一个教训","避免和他对视，让他超过去","也对他做同样的手势","加速开走"],"h1":"想一想怎样让情况冷静下来，而不是变得更糟。","h2":"作出反应可能会让生气的司机更危险，所以要保持冷静，避免对视，在安全时让他过去。","p":"对。保持冷静，避免对视，让那位司机超过去。"},"vi":{"q":"Một tài xế đang tức giận bám sát đuôi xe bạn và làm cử chỉ thô lỗ. Bạn nên làm gì?","o":["Phanh gấp để dạy cho họ một bài học","Tránh nhìn vào mắt và để tài xế đó vượt qua","Làm lại cử chỉ giống vậy","Tăng tốc để chạy thoát"],"h1":"Hãy nghĩ cách làm tình huống dịu đi, không làm nó lớn hơn.","h2":"Phản ứng lại có thể làm tài xế đang tức giận nguy hiểm hơn, nên hãy giữ bình tĩnh, tránh nhìn vào mắt, và để tài xế đó đi qua khi an toàn.","p":"Đúng. Giữ bình tĩnh, tránh nhìn vào mắt và để tài xế đó vượt qua."},"tl":{"q":"Isang galit na driver ang dikit na dikit sa likod mo at gumagawa ng bastos na senyas. Ano ang dapat mong gawin?","o":["Biglang magpreno para turuan siya ng leksyon","Iwasang tumingin sa mata niya at hayaan siyang lumampas","Gumawa rin ng parehong senyas pabalik","Bumilis para makalayo"],"h1":"Isipin kung paano pakakalmahin ang sitwasyon, hindi palalakihin.","h2":"Ang pagpatol ay puwedeng gawing mas mapanganib ang galit na driver, kaya manatiling kalmado, iwasang tumingin sa mata niya, at hayaan siyang lumampas kapag ligtas.","p":"Tama. Manatiling kalmado, iwasang tumingin sa mata niya, at hayaan siyang lumampas."},"ar":{"q":"سائق غاضب يلتصق بك من الخلف ويقوم بحركات وقحة. ماذا يجب أن تفعل؟","o":["اضغط الفرامل فجأة لتعلّمه درسًا","تجنّب النظر في عينيه واتركه يتجاوزك","قُم بنفس الحركات له","أسرع لتبتعد عنه"],"h1":"فكّر في كيف تهدّئ الموقف، لا كيف تجعله أكبر.","h2":"الرد قد يجعل السائق الغاضب أخطر، لذلك ابقَ هادئًا، وتجنّب النظر في عينيه، واتركه يمرّ عندما يكون ذلك آمنًا.","p":"صحيح. ابقَ هادئًا، وتجنّب النظر في عينيه، واتركه يتجاوزك."},"ht":{"q":"Yon chofè ki fache ap kole dèyè w epi l ap fè move jès. Kisa ou ta dwe fè?","o":["Frennen sanzatann pou ba l yon leson","Pa gade l nan je epi kite chofè a pase","Fè l menm jès yo tou","Akselere pou w chape"],"h1":"Panse ak kijan pou w kalme sitiyasyon an, pa fè l vin pi gwo.","h2":"Si ou reyaji, yon chofè ki fache ka vin pi danjere, kidonk rete kalm, pa gade l nan je, epi kite chofè a pase lè li an sekirite.","p":"Se sa. Rete kalm, pa gade l nan je epi kite chofè a pase."},"ref":{"doc":"FL","page":36}},{"id":"safe-driving-046","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"An angry driver keeps following you. Where should you drive?","o":["Straight to your home","To a quiet dead-end street","To a police station or busy public place","Onto the shoulder to stop and talk"],"h1":"Think about a place where people can help you.","h2":"You should not lead an angry driver to your home, so drive to a police station or a busy public place and call 911 if needed.","p":"Right. Drive to a police station or a busy public place."},"es":{"q":"Un conductor enojado lo sigue y no lo deja. ¿Hacia dónde debe manejar?","o":["Directo a su casa","A una calle sin salida y tranquila","A una estación de policía o un lugar público con gente","Al acotamiento para parar y hablar"],"h1":"Piense en un lugar donde la gente pueda ayudarle.","h2":"No debe llevar a un conductor enojado hasta su casa, así que maneje a una estación de policía o a un lugar público con gente y llame al 911 si hace falta.","p":"Correcto. Maneje a una estación de policía o a un lugar público con gente."},"zh":{"q":"一个生气的司机一直跟着你。你应该开到哪里？","o":["直接开回家","开到安静的死胡同","开到警察局或人多的公共场所","开到路肩停下来和他说话"],"h1":"想一想有人能帮你的地方。","h2":"你不应该把生气的司机带到你家，所以要开到警察局或人多的公共场所，需要时打 911。","p":"对。开到警察局或人多的公共场所。"},"vi":{"q":"Một tài xế đang tức giận cứ bám theo bạn. Bạn nên lái đến đâu?","o":["Thẳng về nhà bạn","Đến một con hẻm cụt vắng vẻ","Đến đồn cảnh sát hoặc nơi công cộng đông người","Vào lề đường để dừng lại nói chuyện"],"h1":"Hãy nghĩ đến một nơi có người có thể giúp bạn.","h2":"Bạn không nên dẫn tài xế đang tức giận về nhà mình, nên hãy lái đến đồn cảnh sát hoặc nơi công cộng đông người và gọi 911 nếu cần.","p":"Đúng. Lái đến đồn cảnh sát hoặc nơi công cộng đông người."},"tl":{"q":"Patuloy kang sinusundan ng isang galit na driver. Saan ka dapat magmaneho?","o":["Diretso sa bahay mo","Sa tahimik na dead-end na kalye","Sa police station o mataong pampublikong lugar","Sa shoulder para huminto at makipag-usap"],"h1":"Isipin ang lugar kung saan may mga taong makakatulong sa iyo.","h2":"Hindi mo dapat dalhin ang galit na driver sa bahay mo, kaya magmaneho papunta sa police station o mataong pampublikong lugar at tumawag sa 911 kung kailangan.","p":"Tama. Magmaneho papunta sa police station o mataong pampublikong lugar."},"ar":{"q":"سائق غاضب يستمر في اللحاق بك. إلى أين يجب أن تقود؟","o":["مباشرة إلى بيتك","إلى شارع هادئ مسدود","إلى مركز شرطة أو مكان عام مزدحم","إلى كتف الطريق لتتوقف وتتكلم معه"],"h1":"فكّر في مكان فيه ناس يستطيعون مساعدتك.","h2":"يجب ألّا تقود السائق الغاضب إلى بيتك، لذلك قُد إلى مركز شرطة أو مكان عام مزدحم، واتصل بـ 911 إذا احتجت.","p":"صحيح. قُد إلى مركز شرطة أو مكان عام مزدحم."},"ht":{"q":"Yon chofè ki fache kontinye ap swiv ou. Ki kote ou ta dwe kondi ale?","o":["Tou dwat lakay ou","Nan yon ti lari trankil ki pa gen sòti","Nan yon estasyon polis oswa yon kote piblik ki gen anpil moun","Sou bò wout la pou kanpe pale avè l"],"h1":"Panse ak yon kote moun ka ede w.","h2":"Ou pa ta dwe mennen yon chofè ki fache lakay ou, kidonk kondi ale nan yon estasyon polis oswa yon kote piblik ki gen anpil moun, epi rele 911 si sa nesesè.","p":"Se sa. Kondi ale nan yon estasyon polis oswa yon kote piblik ki gen anpil moun."}},{"id":"safe-driving-047","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"Why is carbon monoxide from a car's exhaust so dangerous?","o":["You cannot see it or smell it","It always makes a loud sound","It only harms the engine","It turns the air black"],"h1":"Think about how you would notice a gas in the car.","h2":"Carbon monoxide has no color and no smell, so it can make you sleepy or sick without warning; never run the engine in a closed garage.","p":"Right. Carbon monoxide cannot be seen or smelled."},"es":{"q":"¿Por qué es tan peligroso el monóxido de carbono del escape del carro?","o":["No se puede ver ni oler","Siempre hace un ruido fuerte","Solo daña el motor","Pone el aire negro"],"h1":"Piense en cómo notaría un gas dentro del carro.","h2":"El monóxido de carbono no tiene color ni olor, así que puede darle sueño o enfermarlo sin aviso; nunca deje el motor encendido en un garaje cerrado.","p":"Correcto. El monóxido de carbono no se puede ver ni oler."},"zh":{"q":"为什么汽车尾气里的一氧化碳这么危险？","o":["你看不到，也闻不到","它总是发出很大的声音","它只伤害引擎","它让空气变黑"],"h1":"想一想你怎样才能发现车里有一种气体。","h2":"一氧化碳没有颜色，也没有气味，所以它可能在没有任何提醒的情况下让你犯困或生病；绝不要在关着的车库里让引擎运转。","p":"对。一氧化碳看不到，也闻不到。"},"vi":{"q":"Tại sao khí carbon monoxide từ ống xả xe lại rất nguy hiểm?","o":["Bạn không thể nhìn thấy hay ngửi thấy nó","Nó luôn phát ra tiếng động lớn","Nó chỉ làm hại động cơ","Nó làm không khí biến thành màu đen"],"h1":"Hãy nghĩ xem bạn sẽ nhận ra có khí trong xe bằng cách nào.","h2":"Carbon monoxide không màu và không mùi, nên nó có thể làm bạn buồn ngủ hoặc bị bệnh mà không có dấu hiệu báo trước; đừng bao giờ nổ máy xe trong ga-ra đóng kín.","p":"Đúng. Carbon monoxide không thể nhìn thấy hay ngửi thấy."},"tl":{"q":"Bakit napakamapanganib ng carbon monoxide mula sa usok ng tambutso ng kotse?","o":["Hindi mo ito nakikita o naaamoy","Laging may malakas itong tunog","Makina lang ang napipinsala nito","Pinaiitim nito ang hangin"],"h1":"Isipin kung paano mo mapapansin ang isang gas sa loob ng kotse.","h2":"Walang kulay at walang amoy ang carbon monoxide, kaya puwede ka nitong antukin o pasamain ang pakiramdam mo nang walang babala; huwag kailanman paandarin ang makina sa saradong garahe.","p":"Tama. Hindi nakikita o naaamoy ang carbon monoxide."},"ar":{"q":"لماذا أول أكسيد الكربون الخارج من عادم السيارة خطير جدًا؟","o":["لا تستطيع أن تراه أو تشمّه","يُصدر دائمًا صوتًا عاليًا","يضرّ المحرك فقط","يجعل الهواء أسود"],"h1":"فكّر: كيف ستلاحظ وجود غاز في السيارة؟","h2":"أول أكسيد الكربون ليس له لون ولا رائحة، لذلك قد يجعلك نعسانًا أو مريضًا بدون تحذير؛ لا تشغّل المحرك أبدًا في مرآب مغلق.","p":"صحيح. أول أكسيد الكربون لا يُرى ولا يُشمّ."},"ht":{"q":"Poukisa monoksid kabòn ki soti nan tiyo echapman yon machin danjere konsa?","o":["Ou pa ka wè l ni santi l","Li toujou fè yon gwo bri","Li fè motè a sèlman mal","Li fè lè a vin nwa"],"h1":"Panse ak kijan ou ta remake yon gaz nan machin nan.","h2":"Monoksid kabòn pa gen koulè ni odè, kidonk li ka ba w dòmi oswa rann ou malad san avètisman; pa janm kite motè a limen nan yon garaj ki fèmen.","p":"Se sa. Ou pa ka wè ni santi monoksid kabòn."}},{"id":"safe-driving-048","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"While driving, you get a headache and feel sleepy. You think it may be exhaust fumes. What should you do?","o":["Close all windows to stay warm","Turn the heater up high","Keep driving to get home fast","Open the windows and pull off safely"],"h1":"Think about getting fresh air right away.","h2":"A headache and sleepiness can be signs of carbon monoxide, so open the windows for fresh air, pull off safely, and have the exhaust checked.","p":"Right. Open the windows and pull off safely."},"es":{"q":"Mientras maneja, le da dolor de cabeza y sueño. Cree que pueden ser gases del escape. ¿Qué debe hacer?","o":["Cerrar todas las ventanas para no tener frío","Subir la calefacción al máximo","Seguir manejando para llegar rápido","Abrir las ventanas y salir de la vía con seguridad"],"h1":"Piense en conseguir aire fresco de inmediato.","h2":"El dolor de cabeza y el sueño pueden ser señales de monóxido de carbono, así que abra las ventanas, salga de la vía con seguridad y haga revisar el escape.","p":"Correcto. Abra las ventanas y salga de la vía con seguridad."},"zh":{"q":"开车时，你头痛，还觉得困。你觉得可能是尾气。你应该怎么做？","o":["关上所有车窗保暖","把暖气开得很大","继续开，快点回家","打开车窗，安全地把车开到路边"],"h1":"想一想马上得到新鲜空气。","h2":"头痛和犯困可能是一氧化碳的信号，所以要打开车窗换新鲜空气，安全地把车开到路边，并找人检查排气系统。","p":"对。打开车窗，安全地把车开到路边。"},"vi":{"q":"Khi đang lái xe, bạn bị nhức đầu và thấy buồn ngủ. Bạn nghĩ có thể là do khói ống xả. Bạn nên làm gì?","o":["Đóng hết cửa sổ để giữ ấm","Mở máy sưởi thật lớn","Lái tiếp để về nhà nhanh","Mở cửa sổ và tấp vào lề an toàn"],"h1":"Hãy nghĩ đến việc lấy không khí trong lành ngay lập tức.","h2":"Nhức đầu và buồn ngủ có thể là dấu hiệu của carbon monoxide, nên hãy mở cửa sổ để có không khí trong lành, tấp vào lề an toàn, và cho kiểm tra ống xả.","p":"Đúng. Mở cửa sổ và tấp vào lề an toàn."},"tl":{"q":"Habang nagmamaneho, sumakit ang ulo mo at inaantok ka. Sa tingin mo, baka usok ito ng tambutso. Ano ang dapat mong gawin?","o":["Isara ang lahat ng bintana para manatiling mainit","Lakasan ang heater","Tumuloy sa pagmamaneho para mabilis makauwi","Buksan ang mga bintana at tumabi nang ligtas"],"h1":"Isipin ang pagkuha agad ng sariwang hangin.","h2":"Ang sakit ng ulo at antok ay puwedeng senyales ng carbon monoxide, kaya buksan ang mga bintana para sa sariwang hangin, tumabi nang ligtas, at ipasuri ang tambutso.","p":"Tama. Buksan ang mga bintana at tumabi nang ligtas."},"ar":{"q":"وأنت تقود، تشعر بصداع ونعاس. تظن أن السبب قد يكون غازات العادم. ماذا يجب أن تفعل؟","o":["أغلق كل النوافذ لتبقى دافئًا","ارفع التدفئة إلى أعلى درجة","تابع القيادة لتصل إلى البيت بسرعة","افتح النوافذ واخرج من الطريق بأمان"],"h1":"فكّر في الحصول على هواء نقي فورًا.","h2":"الصداع والنعاس قد يكونان علامات على أول أكسيد الكربون، لذلك افتح النوافذ ليدخل هواء نقي، واخرج من الطريق بأمان، وافحص العادم.","p":"صحيح. افتح النوافذ واخرج من الطريق بأمان."},"ht":{"q":"Pandan w ap kondi, ou gen tèt fè mal epi ou santi w gen dòmi. Ou panse se ka lafimen tiyo echapman an. Kisa ou ta dwe fè?","o":["Fèmen tout fenèt yo pou w rete cho","Mete chofaj la fò","Kontinye kondi pou w rive lakay vit","Louvri fenèt yo epi soti sou bò wout la san danje"],"h1":"Panse ak jwenn bon lè fre touswit.","h2":"Tèt fè mal ak dòmi ka siy monoksid kabòn, kidonk louvri fenèt yo pou bon lè fre antre, soti sou bò wout la san danje, epi fè yo tcheke tiyo echapman an.","p":"Se sa. Louvri fenèt yo epi soti sou bò wout la san danje."}},{"id":"safe-driving-049","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Why are worn tires with little tread dangerous?","o":["They make the radio louder","They grip the road poorly, mostly when wet","They use less gas","They make the steering heavier"],"h1":"Think about what the grooves in a tire do with water.","h2":"Tire tread moves water away so the tire can grip, so worn tires slip more and are more likely to hydroplane on wet roads.","p":"Right. Worn tires grip poorly, mostly on wet roads."},"es":{"q":"¿Por qué son peligrosas las llantas gastadas con poco dibujo?","o":["Hacen que la radio suene más fuerte","Agarran mal la vía, sobre todo mojada","Gastan menos gasolina","Hacen el volante más pesado"],"h1":"Piense en lo que hacen las ranuras de la llanta con el agua.","h2":"El dibujo de la llanta saca el agua para que la llanta agarre, así que las llantas gastadas resbalan más y es más fácil que hidroplaneen en vías mojadas.","p":"Correcto. Las llantas gastadas agarran mal, sobre todo en vías mojadas."},"zh":{"q":"为什么磨损、花纹很浅的轮胎很危险？","o":["它们让收音机更大声","它们抓地力差，尤其是在湿路上","它们更省油","它们让方向盘更重"],"h1":"想一想轮胎上的沟槽对水起什么作用。","h2":"轮胎花纹会把水排开，让轮胎能抓住路面，所以磨损的轮胎更容易打滑，在湿路上也更容易发生水滑。","p":"对。磨损的轮胎抓地力差，尤其是在湿路上。"},"vi":{"q":"Tại sao lốp xe bị mòn, còn ít gai, lại nguy hiểm?","o":["Chúng làm radio kêu to hơn","Chúng bám đường kém, nhất là khi đường ướt","Chúng tốn ít xăng hơn","Chúng làm tay lái nặng hơn"],"h1":"Hãy nghĩ xem các rãnh trên lốp xe làm gì với nước.","h2":"Gai lốp đẩy nước ra để lốp bám được đường, nên lốp bị mòn dễ trượt hơn và dễ bị lướt nước hơn trên đường ướt.","p":"Đúng. Lốp bị mòn bám đường kém, nhất là trên đường ướt."},"tl":{"q":"Bakit mapanganib ang mga gasgas na gulong na kaunti na lang ang tread (ukit)?","o":["Pinalalakas nila ang radyo","Mahina ang kapit nila sa daan, lalo na kapag basa","Mas kaunti ang gas na nagagamit nila","Pinabibigat nila ang manibela"],"h1":"Isipin kung ano ang ginagawa ng mga ukit ng gulong sa tubig.","h2":"Inaalis ng tread ng gulong ang tubig para makakapit ang gulong, kaya mas dumudulas ang mga gasgas na gulong at mas malamang mag-hydroplane sa basang daan.","p":"Tama. Mahina ang kapit ng mga gasgas na gulong, lalo na sa basang daan."},"ar":{"q":"لماذا الإطارات المستهلكة التي فيها نقوش قليلة خطيرة؟","o":["تجعل صوت الراديو أعلى","تتماسك مع الطريق بشكل ضعيف، خاصة عندما يكون مبللًا","تستهلك بنزينًا أقل","تجعل المقود أثقل"],"h1":"فكّر في ما تفعله الأخاديد في الإطار مع الماء.","h2":"نقوش الإطار تُبعد الماء حتى يتماسك الإطار مع الطريق، لذلك الإطارات المستهلكة تنزلق أكثر، ومن المرجح أن يحدث معها انزلاق مائي على الطرق المبللة.","p":"صحيح. الإطارات المستهلكة تتماسك بشكل ضعيف، خاصة على الطرق المبللة."},"ht":{"q":"Poukisa kawotchou ki fin use, ki pa gen anpil kannal ankò, danjere?","o":["Yo fè radyo a pi fò","Yo pa kenbe wout la byen, sitou lè li mouye","Yo itilize mwens gaz","Yo fè volan an pi lou"],"h1":"Panse ak sa ti kannal ki nan yon kawotchou fè ak dlo.","h2":"Kannal kawotchou yo pouse dlo a ale pou kawotchou a ka kenbe wout la, kidonk kawotchou ki fin use glise plis epi yo gen plis chans glise sou dlo (hydroplaning) sou wout mouye.","p":"Se sa. Kawotchou ki fin use pa kenbe wout la byen, sitou sou wout mouye."},"ref":{"doc":"FL","page":39}},{"id":"safe-driving-050","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"When should you adjust your seat and mirrors?","o":["While driving on the highway","At the first red light","Before you start driving","Only when someone else drove your car"],"h1":"Think about when your hands and eyes are free to do it safely.","h2":"Adjusting mirrors while moving takes your attention off the road, so you should set your seat and mirrors before you start driving.","p":"Right. Adjust your seat and mirrors before you start driving."},"es":{"q":"¿Cuándo debe ajustar el asiento y los espejos?","o":["Mientras maneja en la autopista","En el primer semáforo en rojo","Antes de empezar a manejar","Solo si otra persona usó su carro"],"h1":"Piense en cuándo tiene las manos y los ojos libres para hacerlo con seguridad.","h2":"Ajustar los espejos en movimiento le quita la atención de la vía, así que debe ajustar el asiento y los espejos antes de empezar a manejar.","p":"Correcto. Ajuste el asiento y los espejos antes de empezar a manejar."},"zh":{"q":"你应该什么时候调整座椅和后视镜？","o":["在高速公路上开车时","在第一个红灯时","在你开始开车之前","只在别人开过你的车以后"],"h1":"想一想什么时候你的手和眼睛有空，可以安全地做这件事。","h2":"车在动的时候调整后视镜会让你不注意道路，所以你应该在开始开车之前调好座椅和后视镜。","p":"对。在开始开车之前调整座椅和后视镜。"},"vi":{"q":"Khi nào bạn nên chỉnh ghế ngồi và gương?","o":["Khi đang lái trên xa lộ","Ở đèn đỏ đầu tiên","Trước khi bạn bắt đầu lái xe","Chỉ khi có người khác đã lái xe của bạn"],"h1":"Hãy nghĩ xem khi nào tay và mắt bạn rảnh để làm việc này an toàn.","h2":"Chỉnh gương khi xe đang chạy làm bạn mất tập trung vào đường, nên bạn nên chỉnh ghế ngồi và gương trước khi bắt đầu lái xe.","p":"Đúng. Chỉnh ghế ngồi và gương trước khi bắt đầu lái xe."},"tl":{"q":"Kailan mo dapat ayusin ang upuan at mga salamin mo?","o":["Habang nagmamaneho sa highway","Sa unang red light","Bago ka magsimulang magmaneho","Kapag may ibang nagmaneho lang ng kotse mo"],"h1":"Isipin kung kailan malaya ang mga kamay at mata mo para gawin ito nang ligtas.","h2":"Ang pag-aayos ng salamin habang umaandar ay nag-aalis ng atensyon mo sa daan, kaya dapat mong ayusin ang upuan at mga salamin mo bago ka magsimulang magmaneho.","p":"Tama. Ayusin ang upuan at mga salamin mo bago ka magsimulang magmaneho."},"ar":{"q":"متى يجب أن تضبط مقعدك ومراياك؟","o":["وأنت تقود على الطريق السريع","عند أول إشارة حمراء","قبل أن تبدأ القيادة","فقط عندما يقود شخص آخر سيارتك"],"h1":"فكّر في الوقت الذي تكون فيه يداك وعيناك حرة لتفعل ذلك بأمان.","h2":"ضبط المرايا أثناء الحركة يُبعد انتباهك عن الطريق، لذلك يجب أن تضبط مقعدك ومراياك قبل أن تبدأ القيادة.","p":"صحيح. اضبط مقعدك ومراياك قبل أن تبدأ القيادة."},"ht":{"q":"Ki lè ou ta dwe ranje chèz ou ak retwovizè ou yo?","o":["Pandan w ap kondi sou otowout la","Nan premye limyè wouj la","Anvan ou kòmanse kondi","Sèlman lè yon lòt moun te kondi machin ou"],"h1":"Panse ak ki lè men ou ak je ou lib pou w fè l san danje.","h2":"Ranje retwovizè yo pandan machin nan ap woule retire atansyon ou sou wout la, kidonk ou ta dwe ranje chèz ou ak retwovizè ou yo anvan ou kòmanse kondi.","p":"Se sa. Ranje chèz ou ak retwovizè ou yo anvan ou kòmanse kondi."},"ref":{"doc":"FL","page":59}},{"id":"safe-driving-051","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"What is the right way to use your car horn?","o":["To warn others of danger","To show you are angry","To greet friends you pass","To make slow drivers hurry"],"h1":"Think about safety, not feelings.","h2":"The horn is a safety tool, so use it to warn others of danger and not to show anger or rush people.","p":"Right. Use the horn to warn others of danger."},"es":{"q":"¿Cuál es la forma correcta de usar la bocina?","o":["Para avisar a otros de un peligro","Para mostrar que está enojado","Para saludar a amigos que pasa","Para que los lentos se apuren"],"h1":"Piense en la seguridad, no en los sentimientos.","h2":"La bocina es una herramienta de seguridad, así que úsela para avisar a otros de un peligro y no para mostrar enojo ni apurar a la gente.","p":"Correcto. Use la bocina para avisar a otros de un peligro."},"zh":{"q":"使用汽车喇叭的正确方法是什么？","o":["提醒别人有危险","表示你很生气","和路过的朋友打招呼","让开得慢的司机快点"],"h1":"想一想安全，而不是情绪。","h2":"喇叭是一个安全工具，所以要用它提醒别人有危险，而不是用来表示生气或催促别人。","p":"对。用喇叭提醒别人有危险。"},"vi":{"q":"Cách đúng để dùng còi xe là gì?","o":["Để cảnh báo người khác về nguy hiểm","Để cho thấy bạn đang tức giận","Để chào bạn bè khi chạy ngang qua","Để giục tài xế chạy chậm đi nhanh hơn"],"h1":"Hãy nghĩ đến sự an toàn, không phải cảm xúc.","h2":"Còi xe là một công cụ an toàn, nên hãy dùng còi để cảnh báo người khác về nguy hiểm, không phải để thể hiện sự tức giận hay giục người khác.","p":"Đúng. Dùng còi để cảnh báo người khác về nguy hiểm."},"tl":{"q":"Ano ang tamang paraan ng paggamit ng busina ng kotse mo?","o":["Para bigyan ng babala ang iba tungkol sa panganib","Para ipakitang galit ka","Para batiin ang mga kaibigang nadaraanan mo","Para magmadali ang mabagal na mga driver"],"h1":"Isipin ang kaligtasan, hindi ang damdamin.","h2":"Ang busina ay kasangkapan para sa kaligtasan, kaya gamitin ito para bigyan ng babala ang iba tungkol sa panganib at hindi para ipakita ang galit o madaliin ang mga tao.","p":"Tama. Gamitin ang busina para bigyan ng babala ang iba tungkol sa panganib."},"ar":{"q":"ما الطريقة الصحيحة لاستعمال بوق السيارة؟","o":["لتحذير الآخرين من خطر","لتُظهر أنك غاضب","لتحيّي أصدقاء تمرّ بجانبهم","لتجعل السائقين البطيئين يُسرعون"],"h1":"فكّر في السلامة، وليس في المشاعر.","h2":"البوق أداة للسلامة، لذلك استعمله لتحذير الآخرين من خطر، وليس لتُظهر الغضب أو لتستعجل الناس.","p":"صحيح. استعمل البوق لتحذير الآخرين من خطر."},"ht":{"q":"Ki bon fason pou w sèvi ak klaksonn machin ou?","o":["Pou avèti lòt moun gen danje","Pou montre ou fache","Pou salye zanmi ou pase","Pou fè chofè ki dousman yo fè vit"],"h1":"Panse ak sekirite, pa ak santiman.","h2":"Klaksonn nan se yon zouti sekirite, kidonk sèvi avè l pou avèti lòt moun gen danje, epi pa pou montre ou fache oswa pou prese moun.","p":"Se sa. Sèvi ak klaksonn nan pou avèti lòt moun gen danje."}},{"id":"safe-driving-052","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"Your wiper blades leave streaks and you cannot see well in the rain. What should you do?","o":["Drive with your head out the window","Use them only on the highway","Turn on your high beams","Replace the wiper blades soon"],"h1":"Think about what you need to see clearly in the rain.","h2":"Worn wiper blades do not clear the glass, so you should replace them soon to see the road clearly in the rain.","p":"Right. Replace worn wiper blades so you can see in the rain."},"es":{"q":"Sus limpiaparabrisas dejan rayas y no ve bien en la lluvia. ¿Qué debe hacer?","o":["Manejar con la cabeza afuera de la ventana","Usarlos solo en la autopista","Encender las luces altas","Cambiar las plumas del limpiaparabrisas pronto"],"h1":"Piense en lo que necesita para ver bien en la lluvia.","h2":"Las plumas gastadas no limpian bien el vidrio, así que debe cambiarlas pronto para ver la vía con claridad en la lluvia.","p":"Correcto. Cambie las plumas gastadas para ver bien en la lluvia."},"zh":{"q":"你的雨刷片留下条纹，下雨时你看不清楚。你应该怎么做？","o":["把头伸出窗外开车","只在高速公路上用","打开远光灯","尽快更换雨刷片"],"h1":"想一想下雨时你需要什么才能看清楚。","h2":"磨损的雨刷片擦不干净玻璃，所以你应该尽快更换，这样下雨时才能看清道路。","p":"对。更换磨损的雨刷片，下雨时才能看清楚。"},"vi":{"q":"Lưỡi gạt nước để lại vệt trên kính và bạn không nhìn rõ khi trời mưa. Bạn nên làm gì?","o":["Lái xe và thò đầu ra ngoài cửa sổ","Chỉ dùng gạt nước trên xa lộ","Bật đèn pha (đèn chiếu xa)","Thay lưỡi gạt nước sớm"],"h1":"Hãy nghĩ xem bạn cần gì để nhìn rõ khi trời mưa.","h2":"Lưỡi gạt nước bị mòn không làm sạch được kính, nên bạn nên thay chúng sớm để nhìn rõ đường khi trời mưa.","p":"Đúng. Thay lưỡi gạt nước bị mòn để nhìn rõ khi trời mưa."},"tl":{"q":"Nag-iiwan ng guhit ang wiper blades mo at hindi ka makakita nang maayos sa ulan. Ano ang dapat mong gawin?","o":["Magmaneho na nakalabas ang ulo sa bintana","Gamitin lang ang mga ito sa highway","I-on ang high beams mo","Palitan agad ang wiper blades"],"h1":"Isipin kung ano ang kailangan mo para makakita nang malinaw sa ulan.","h2":"Hindi nalilinis ng gasgas na wiper blades ang salamin, kaya dapat mo itong palitan agad para malinaw mong makita ang daan sa ulan.","p":"Tama. Palitan ang gasgas na wiper blades para makakita ka sa ulan."},"ar":{"q":"شفرات المساحات تترك خطوطًا ولا تستطيع أن ترى جيدًا في المطر. ماذا يجب أن تفعل؟","o":["قُد ورأسك خارج النافذة","استعملها على الطريق السريع فقط","شغّل الأضواء العالية","غيّر شفرات المساحات قريبًا"],"h1":"فكّر في ما تحتاجه لترى بوضوح في المطر.","h2":"شفرات المساحات المستهلكة لا تنظّف الزجاج، لذلك يجب أن تغيّرها قريبًا حتى ترى الطريق بوضوح في المطر.","p":"صحيح. غيّر شفرات المساحات المستهلكة حتى ترى في المطر."},"ht":{"q":"Wipè ou yo kite tras sou vit la epi ou pa ka wè byen nan lapli a. Kisa ou ta dwe fè?","o":["Kondi ak tèt ou deyò fenèt la","Sèvi ak yo sèlman sou otowout la","Limen gwo limyè ou yo","Chanje wipè yo byento"],"h1":"Panse ak sa ou bezwen pou w wè klè nan lapli a.","h2":"Wipè ki fin use pa netwaye vit la, kidonk ou ta dwe chanje yo byento pou w ka wè wout la klè nan lapli a.","p":"Se sa. Chanje wipè ki fin use yo pou w ka wè nan lapli a."}},{"id":"safe-driving-053","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Your brake pedal feels soft and sinks close to the floor. What should you do?","o":["Keep driving and press harder","Have the brakes checked right away","Wait until the next oil change","Use only the parking brake from now on"],"h1":"Think about what a soft pedal can say about your brakes.","h2":"A soft or sinking brake pedal is a warning sign of a brake problem, so you should have the brakes checked right away.","p":"Right. A soft brake pedal means get the brakes checked now."},"es":{"q":"El pedal del freno se siente blando y baja casi hasta el piso. ¿Qué debe hacer?","o":["Seguir manejando y pisar más fuerte","Hacer revisar los frenos de inmediato","Esperar hasta el próximo cambio de aceite","Usar solo el freno de mano desde ahora"],"h1":"Piense en lo que un pedal blando puede decir de sus frenos.","h2":"Un pedal de freno blando o que se hunde es una señal de un problema en los frenos, así que debe hacerlos revisar de inmediato.","p":"Correcto. Un pedal blando significa revisar los frenos ya."},"zh":{"q":"你的刹车踏板踩起来软软的，还会沉到快碰到地板。你应该怎么做？","o":["继续开，用力踩","马上找人检查刹车","等到下次换机油时再说","从现在起只用手刹"],"h1":"想一想软的踏板可能说明你的刹车有什么问题。","h2":"刹车踏板变软或往下沉是刹车有问题的警告信号，所以你应该马上找人检查刹车。","p":"对。刹车踏板变软，就要马上检查刹车。"},"vi":{"q":"Bàn đạp phanh của bạn có cảm giác mềm và lún xuống gần sàn xe. Bạn nên làm gì?","o":["Lái tiếp và đạp mạnh hơn","Cho kiểm tra phanh ngay","Chờ đến lần thay dầu tới","Từ giờ chỉ dùng phanh tay"],"h1":"Hãy nghĩ xem bàn đạp mềm có thể cho biết điều gì về phanh của bạn.","h2":"Bàn đạp phanh mềm hoặc bị lún là dấu hiệu cảnh báo phanh có vấn đề, nên bạn nên cho kiểm tra phanh ngay.","p":"Đúng. Bàn đạp phanh mềm nghĩa là phải cho kiểm tra phanh ngay."},"tl":{"q":"Malambot ang pakiramdam ng preno mo at lumulubog ito malapit sa sahig. Ano ang dapat mong gawin?","o":["Tumuloy sa pagmamaneho at diinan pa","Ipasuri agad ang preno","Maghintay hanggang sa susunod na change oil","Parking brake na lang ang gamitin mula ngayon"],"h1":"Isipin kung ano ang puwedeng sabihin ng malambot na preno tungkol sa preno mo.","h2":"Ang malambot o lumulubog na preno ay babala ng problema sa preno, kaya dapat mong ipasuri agad ang preno.","p":"Tama. Kapag malambot ang preno, ipasuri agad ang preno."},"ar":{"q":"دواسة الفرامل تبدو لينة وتنزل قريبًا من الأرض. ماذا يجب أن تفعل؟","o":["تابع القيادة واضغط بقوة أكبر","افحص الفرامل فورًا","انتظر حتى تغيير الزيت القادم","استعمل فرامل اليد فقط من الآن"],"h1":"فكّر في ما تقوله الدواسة اللينة عن فراملك.","h2":"دواسة الفرامل اللينة أو التي تنزل كثيرًا علامة تحذير على مشكلة في الفرامل، لذلك يجب أن تفحص الفرامل فورًا.","p":"صحيح. دواسة الفرامل اللينة تعني أن تفحص الفرامل الآن."},"ht":{"q":"Pedal fren ou a mou epi li desann prèske rive atè. Kisa ou ta dwe fè?","o":["Kontinye kondi epi peze pi fò","Fè tcheke fren yo touswit","Tann pwochen fwa w ap chanje lwil","Sèvi ak fren a men an sèlman depi kounye a"],"h1":"Panse ak sa yon pedal mou ka di sou fren ou yo.","h2":"Yon pedal fren ki mou oswa ki desann se yon siy avètisman ke gen yon pwoblèm fren, kidonk ou ta dwe fè tcheke fren yo touswit.","p":"Se sa. Yon pedal fren mou vle di fè tcheke fren yo kounye a."}},{"id":"safe-driving-054","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"You are stopped behind a large truck on an uphill road. Why should you leave extra space?","o":["So you can read its license plate","So other cars can pass you","The truck may roll back a little when it starts","So the truck driver can see your lights"],"h1":"Think about what a heavy vehicle can do on a hill when it starts to move.","h2":"A heavy truck can roll back a little on a hill before it moves forward, so leave extra space in front of you.","p":"Right. Leave extra space because a truck may roll back on a hill."},"es":{"q":"Usted está parado detrás de un camión grande en una subida. ¿Por qué debe dejar más espacio?","o":["Para poder leer su placa","Para que otros carros lo rebasen","El camión puede rodar un poco hacia atrás al arrancar","Para que el chofer vea sus luces"],"h1":"Piense en lo que puede hacer un vehículo pesado en una subida al empezar a moverse.","h2":"Un camión pesado puede rodar un poco hacia atrás en una subida antes de avanzar, así que deje más espacio delante de usted.","p":"Correcto. Deje más espacio porque el camión puede rodar hacia atrás."},"zh":{"q":"你在上坡路上停在一辆大卡车后面。为什么你应该多留一些空间？","o":["这样你才能看清它的车牌","这样其他车才能超过你","卡车起步时可能会往后溜一点","这样卡车司机才能看到你的车灯"],"h1":"想一想重型车辆在坡上开始移动时可能会怎样。","h2":"重型卡车在坡上往前开之前，可能会往后溜一点，所以要在你前面多留一些空间。","p":"对。多留空间，因为卡车在坡上可能会往后溜。"},"vi":{"q":"Bạn đang dừng sau một xe tải lớn trên đường lên dốc. Tại sao bạn nên chừa thêm khoảng cách?","o":["Để bạn đọc được biển số xe của nó","Để các xe khác vượt qua bạn","Xe tải có thể bị trôi lùi một chút khi bắt đầu chạy","Để tài xế xe tải nhìn thấy đèn của bạn"],"h1":"Hãy nghĩ xem một xe nặng có thể làm gì trên dốc khi bắt đầu chạy.","h2":"Xe tải nặng có thể trôi lùi một chút trên dốc trước khi chạy tới, nên hãy chừa thêm khoảng cách phía trước bạn.","p":"Đúng. Chừa thêm khoảng cách vì xe tải có thể trôi lùi trên dốc."},"tl":{"q":"Nakahinto ka sa likod ng malaking truck sa paakyat na daan. Bakit dapat kang mag-iwan ng dagdag na espasyo?","o":["Para mabasa mo ang plate number nito","Para makalampas sa iyo ang ibang kotse","Puwedeng umatras nang kaunti ang truck kapag umandar ito","Para makita ng truck driver ang ilaw mo"],"h1":"Isipin kung ano ang puwedeng gawin ng mabigat na sasakyan sa paakyat kapag nagsisimula itong umandar.","h2":"Ang mabigat na truck ay puwedeng umatras nang kaunti sa paakyat bago ito umabante, kaya mag-iwan ng dagdag na espasyo sa harap mo.","p":"Tama. Mag-iwan ng dagdag na espasyo dahil puwedeng umatras ang truck sa paakyat."},"ar":{"q":"أنت متوقف خلف شاحنة كبيرة على طريق صاعد. لماذا يجب أن تترك مسافة إضافية؟","o":["حتى تستطيع قراءة لوحة أرقامها","حتى تستطيع السيارات الأخرى تجاوزك","الشاحنة قد ترجع إلى الخلف قليلًا عندما تبدأ بالتحرك","حتى يستطيع سائق الشاحنة رؤية أضوائك"],"h1":"فكّر في ما قد تفعله مركبة ثقيلة على طريق صاعد عندما تبدأ بالتحرك.","h2":"الشاحنة الثقيلة قد ترجع إلى الخلف قليلًا على الطريق الصاعد قبل أن تتقدم إلى الأمام، لذلك اترك مسافة إضافية أمامك.","p":"صحيح. اترك مسافة إضافية لأن الشاحنة قد ترجع إلى الخلف على الطريق الصاعد."},"ht":{"q":"Ou kanpe dèyè yon gwo kamyon sou yon wout k ap monte. Poukisa ou ta dwe kite plis espas?","o":["Pou w ka li plak li","Pou lòt machin ka pase w","Kamyon an ka fè bak yon ti kras lè l ap demare","Pou chofè kamyon an ka wè limyè ou"],"h1":"Panse ak sa yon machin lou ka fè sou yon mòn lè li kòmanse deplase.","h2":"Yon kamyon lou ka fè bak yon ti kras sou yon mòn anvan li avanse, kidonk kite plis espas devan w.","p":"Se sa. Kite plis espas paske yon kamyon ka fè bak sou yon mòn."},"ref":{"doc":"FL","page":82}},{"id":"signals-001","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"What does a steady red traffic light mean?","o":["Slow down and go if no one is coming","Stop only if a police officer is there","Stop and stay stopped until it is safe and legal to go","Speed up to clear the intersection"],"h1":"Think about the strongest color on a traffic light.","h2":"A steady red light means you must stop and stay stopped, because cross traffic has the right to go.","p":"Right. A steady red light means stop and wait."},"es":{"q":"¿Qué significa una luz roja fija en el semáforo?","o":["Baje la velocidad y siga si no viene nadie","Pare solo si hay un policía","Pare y quédese parado hasta que sea seguro y legal seguir","Acelere para salir de la intersección"],"h1":"Piense en el color más fuerte del semáforo.","h2":"Una luz roja fija significa que usted debe parar y quedarse parado, porque el tráfico que cruza tiene el derecho a pasar.","p":"Correcto. Una luz roja fija significa pare y espere."},"zh":{"q":"一直亮着的红灯是什么意思？","o":["减速，没有来车就走","只有警察在场时才停","停车，一直停到安全且合法时再走","加速，快快开过路口"],"h1":"想一想：红绿灯上最强烈的颜色。","h2":"一直亮着的红灯表示你必须停车并保持停住，因为横向的车有权通行。","p":"对。一直亮着的红灯表示停车等待。"},"vi":{"q":"Đèn đỏ sáng đứng yên (không nhấp nháy) có nghĩa là gì?","o":["Chạy chậm lại và đi nếu không có ai tới","Chỉ dừng nếu có cảnh sát ở đó","Dừng lại và đứng yên tới khi được đi an toàn và đúng luật","Tăng tốc để qua khỏi giao lộ"],"h1":"Hãy nghĩ đến màu mạnh nhất trên đèn giao thông.","h2":"Đèn đỏ sáng đứng yên nghĩa là bạn phải dừng lại và đứng yên, vì xe ở hướng cắt ngang đang được quyền đi.","p":"Đúng rồi. Đèn đỏ sáng đứng yên nghĩa là dừng lại và chờ."},"tl":{"q":"Ano ang ibig sabihin ng tuloy-tuloy na pulang ilaw trapiko?","o":["Bumagal at umandar kung walang dumarating","Huminto lang kung may pulis doon","Huminto at manatiling nakahinto hanggang ligtas at legal nang umandar","Bumilis para malampasan ang interseksyon"],"h1":"Isipin ang pinakamalakas na kulay sa ilaw trapiko.","h2":"Ang tuloy-tuloy na pulang ilaw ay nangangahulugang dapat kang huminto at manatiling nakahinto, dahil ang trapiko sa kabilang daan ang may karapatang umandar.","p":"Tama. Ang tuloy-tuloy na pulang ilaw ay nangangahulugang huminto at maghintay."},"ar":{"q":"ماذا يعني الضوء الأحمر الثابت في إشارة المرور؟","o":["خفف السرعة وانطلق إذا لم يأتِ أحد","توقف فقط إذا كان هناك شرطي","توقف وابقَ متوقفًا حتى يصبح الانطلاق آمنًا ومسموحًا","زد السرعة لتخرج من التقاطع"],"h1":"فكّر في أقوى لون في إشارة المرور.","h2":"الضوء الأحمر الثابت يعني أنه يجب أن تتوقف وتبقى متوقفًا، لأن السيارات في الاتجاه المتقاطع لها الحق في المرور.","p":"صحيح. الضوء الأحمر الثابت يعني: توقف وانتظر."},"ht":{"q":"Kisa yon limyè trafik wouj fiks vle di?","o":["Ralanti epi pase si pa gen moun k ap vini","Kanpe sèlman si gen yon polis la","Kanpe epi rete kanpe jiskaske li an sekirite epi lalwa pèmèt ou pase","Akselere pou kite kafou a"],"h1":"Panse ak koulè ki pi fò sou yon limyè trafik.","h2":"Yon limyè wouj fiks vle di ou dwe kanpe epi rete kanpe, paske machin ki sou lòt lari a gen dwa pou pase.","p":"Se sa. Yon limyè wouj fiks vle di kanpe epi tann."},"ref":{"doc":"FL","page":51}},{"id":"signals-002","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"The light turns steady yellow as you come near. What should you do?","o":["Stop if you can do it safely","Speed up to beat the red light","Stop suddenly, no matter what","Keep going at the same speed always"],"h1":"Yellow is a warning. Think about what color comes next.","h2":"A steady yellow light warns that the light will soon turn red, so you should stop if you can do it safely.","p":"Right. Steady yellow means red is coming, so stop if it is safe."},"es":{"q":"La luz cambia a amarillo fijo cuando usted se acerca. ¿Qué debe hacer?","o":["Parar si lo puede hacer con seguridad","Acelerar para pasar antes de la roja","Frenar de golpe, pase lo que pase","Seguir siempre a la misma velocidad"],"h1":"El amarillo es una advertencia. Piense qué color viene después.","h2":"Una luz amarilla fija avisa que pronto cambiará a roja, así que usted debe parar si lo puede hacer con seguridad.","p":"Correcto. Amarillo fijo significa que viene la roja, así que pare si es seguro."},"zh":{"q":"你快到路口时，灯变成一直亮着的黄灯。你应该怎么做？","o":["如果能安全停下，就停车","加速，抢在红灯前过去","不管怎样都马上急停","总是保持同样的速度继续开"],"h1":"黄灯是警告。想一想接下来是什么颜色。","h2":"一直亮着的黄灯提醒你马上要变红灯，所以如果能安全停下，你就应该停车。","p":"对。黄灯表示红灯要来了，安全的话就停车。"},"vi":{"q":"Khi bạn tới gần, đèn chuyển sang vàng sáng đứng yên. Bạn nên làm gì?","o":["Dừng lại nếu bạn có thể dừng an toàn","Tăng tốc để qua trước khi đèn đỏ","Dừng gấp, dù thế nào đi nữa","Lúc nào cũng giữ nguyên tốc độ mà chạy tiếp"],"h1":"Màu vàng là lời cảnh báo. Hãy nghĩ xem màu nào sẽ tới sau đó.","h2":"Đèn vàng sáng đứng yên cảnh báo rằng đèn sắp chuyển sang đỏ, nên bạn cần dừng lại nếu có thể dừng an toàn.","p":"Đúng rồi. Đèn vàng nghĩa là sắp đỏ, nên hãy dừng nếu an toàn."},"tl":{"q":"Naging tuloy-tuloy na dilaw ang ilaw habang papalapit ka. Ano ang dapat mong gawin?","o":["Huminto kung kaya mong gawin ito nang ligtas","Bumilis para maunahan ang pulang ilaw","Huminto nang biglaan, kahit ano pa ang mangyari","Magpatuloy sa parehong bilis palagi"],"h1":"Ang dilaw ay isang babala. Isipin kung anong kulay ang susunod.","h2":"Ang tuloy-tuloy na dilaw na ilaw ay babala na malapit nang maging pula ang ilaw, kaya dapat kang huminto kung kaya mong gawin ito nang ligtas.","p":"Tama. Ang tuloy-tuloy na dilaw ay nangangahulugang paparating na ang pula, kaya huminto kung ligtas."},"ar":{"q":"الإشارة تصبح صفراء ثابتة وأنت تقترب. ماذا يجب أن تفعل؟","o":["توقف إذا استطعت أن تفعل ذلك بأمان","زد السرعة لتسبق الضوء الأحمر","توقف فجأة مهما كان الوضع","استمر بنفس السرعة دائمًا"],"h1":"الأصفر تحذير. فكّر في اللون الذي يأتي بعده.","h2":"الضوء الأصفر الثابت يحذّر من أن الإشارة ستصبح حمراء قريبًا، لذلك يجب أن تتوقف إذا استطعت أن تفعل ذلك بأمان.","p":"صحيح. الأصفر الثابت يعني أن الأحمر قادم، لذلك توقف إذا كان ذلك آمنًا."},"ht":{"q":"Limyè a vin jòn fiks pandan w ap pwoche. Kisa ou dwe fè?","o":["Kanpe si ou ka fè l an sekirite","Akselere pou pase anvan limyè wouj la","Kanpe sèk, kèlkeswa sa k rive","Toujou kontinye ak menm vitès la"],"h1":"Jòn se yon avètisman. Panse ak ki koulè ki vini apre.","h2":"Yon limyè jòn fiks avèti ou limyè a pral vin wouj talè, kidonk ou dwe kanpe si ou ka fè l an sekirite.","p":"Se sa. Jòn fiks vle di wouj ap vini, kidonk kanpe si sa an sekirite."},"ref":{"doc":"FL","page":51}},{"id":"signals-003","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"You are already in the intersection when the light turns yellow. What should you do?","o":["Stop in the middle of the intersection","Back up to the stop line","Turn around in the intersection","Carefully finish going through the intersection"],"h1":"Think about where it is safest for your car to be when the light turns red.","h2":"If you are already in the intersection when the light turns yellow, you should carefully keep going, because stopping there would block traffic.","p":"Right. If you are already in the intersection, carefully clear it."},"es":{"q":"Usted ya está dentro de la intersección cuando la luz cambia a amarillo. ¿Qué debe hacer?","o":["Parar en medio de la intersección","Dar marcha atrás hasta la línea de pare","Dar la vuelta dentro de la intersección","Terminar de cruzar la intersección con cuidado"],"h1":"Piense dónde es más seguro estar cuando la luz cambie a roja.","h2":"Si usted ya está dentro de la intersección cuando la luz cambia a amarillo, debe seguir con cuidado, porque parar ahí bloquearía el tráfico.","p":"Correcto. Si ya está dentro de la intersección, termine de cruzar con cuidado."},"zh":{"q":"灯变黄时，你已经在路口里面了。你应该怎么做？","o":["停在路口中间","倒车回到停车线","在路口里掉头","小心地继续开出路口"],"h1":"想一想：变红灯时，你的车在哪里最安全。","h2":"如果灯变黄时你已经在路口里面，你应该小心地继续开，因为停在那里会挡住交通。","p":"对。如果你已经在路口里，就小心地开出去。"},"vi":{"q":"Bạn đã ở trong giao lộ thì đèn chuyển sang vàng. Bạn nên làm gì?","o":["Dừng lại ở giữa giao lộ","Lùi xe về vạch dừng","Quay đầu xe trong giao lộ","Cẩn thận chạy tiếp cho qua hết giao lộ"],"h1":"Hãy nghĩ xem xe bạn ở đâu là an toàn nhất khi đèn chuyển sang đỏ.","h2":"Nếu bạn đã ở trong giao lộ khi đèn chuyển sang vàng, bạn cần cẩn thận chạy tiếp, vì dừng ở đó sẽ chắn đường xe khác.","p":"Đúng rồi. Nếu bạn đã ở trong giao lộ, hãy cẩn thận chạy qua cho hết."},"tl":{"q":"Nasa loob ka na ng interseksyon nang maging dilaw ang ilaw. Ano ang dapat mong gawin?","o":["Huminto sa gitna ng interseksyon","Umatras pabalik sa stop line","Umikot pabalik sa loob ng interseksyon","Maingat na tapusin ang pagdaan sa interseksyon"],"h1":"Isipin kung saan pinakaligtas ang sasakyan mo kapag naging pula ang ilaw.","h2":"Kung nasa loob ka na ng interseksyon nang maging dilaw ang ilaw, dapat kang magpatuloy nang maingat, dahil kapag huminto ka doon ay haharangan mo ang trapiko.","p":"Tama. Kung nasa loob ka na ng interseksyon, maingat na lumabas dito."},"ar":{"q":"أنت داخل التقاطع بالفعل عندما تصبح الإشارة صفراء. ماذا يجب أن تفعل؟","o":["توقف في وسط التقاطع","ارجع إلى الخلف حتى خط التوقف","استدر عائدًا داخل التقاطع","أكمل عبور التقاطع بحذر"],"h1":"فكّر في أكثر مكان آمن لسيارتك عندما تصبح الإشارة حمراء.","h2":"إذا كنت داخل التقاطع بالفعل عندما تصبح الإشارة صفراء، يجب أن تكمل طريقك بحذر، لأن توقفك هناك سيغلق الطريق أمام السيارات.","p":"صحيح. إذا كنت داخل التقاطع بالفعل، اخرج منه بحذر."},"ht":{"q":"Ou deja nan kafou a lè limyè a vin jòn. Kisa ou dwe fè?","o":["Kanpe nan mitan kafou a","Fè bak jiska liy pou kanpe a","Vire tounen nan kafou a","Fini travèse kafou a avèk prekosyon"],"h1":"Panse ki kote li pi an sekirite pou machin ou ye lè limyè a vin wouj.","h2":"Si ou deja nan kafou a lè limyè a vin jòn, ou dwe kontinye avèk prekosyon, paske si ou kanpe la a ou ta bloke trafik la.","p":"Se sa. Si ou deja nan kafou a, fini travèse l avèk prekosyon."},"ref":{"doc":"FL","page":51}},{"id":"signals-004","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"What does a flashing red light mean?","o":["Slow down, but you do not need to stop","Stop fully, then go when the way is clear","The light is about to turn green","Only trucks must stop"],"h1":"A flashing red light works like a sign you already know.","h2":"A flashing red light works like a stop sign, so you must stop fully and then go when the way is clear.","p":"Right. A flashing red light means stop, then go when safe."},"es":{"q":"¿Qué significa una luz roja intermitente?","o":["Baje la velocidad, pero no tiene que parar","Pare por completo y luego siga cuando el camino esté libre","La luz está por cambiar a verde","Solo los camiones deben parar"],"h1":"Una luz roja intermitente funciona como una señal que usted ya conoce.","h2":"Una luz roja intermitente funciona como una señal de pare, así que usted debe parar por completo y luego seguir cuando el camino esté libre.","p":"Correcto. Luz roja intermitente significa pare y luego siga cuando sea seguro."},"zh":{"q":"闪烁的红灯是什么意思？","o":["减速，但不用停车","完全停车，没车时再走","灯马上要变绿了","只有卡车要停"],"h1":"闪烁的红灯和一个你已经知道的标志作用一样。","h2":"闪烁的红灯和停车标志作用一样，所以你必须完全停车，没车时再走。","p":"对。闪烁的红灯表示停车，安全时再走。"},"vi":{"q":"Đèn đỏ nhấp nháy có nghĩa là gì?","o":["Chạy chậm lại, nhưng không cần dừng","Dừng hẳn, rồi đi khi đường đã trống","Đèn sắp chuyển sang xanh","Chỉ xe tải phải dừng"],"h1":"Đèn đỏ nhấp nháy giống như một biển báo bạn đã biết.","h2":"Đèn đỏ nhấp nháy giống như biển “STOP” (Dừng lại), nên bạn phải dừng hẳn rồi mới đi khi đường đã trống.","p":"Đúng rồi. Đèn đỏ nhấp nháy nghĩa là dừng lại, rồi đi khi an toàn."},"tl":{"q":"Ano ang ibig sabihin ng kumikislap na pulang ilaw?","o":["Bumagal, pero hindi mo kailangang huminto","Huminto nang buo, saka umandar kapag maluwag na ang daan","Malapit nang maging berde ang ilaw","Mga trak lang ang dapat huminto"],"h1":"Ang kumikislap na pulang ilaw ay gumagana na parang karatula na kilala mo na.","h2":"Ang kumikislap na pulang ilaw ay gumagana na parang “STOP” sign, kaya dapat kang huminto nang buo at saka umandar kapag maluwag na ang daan.","p":"Tama. Ang kumikislap na pulang ilaw ay nangangahulugang huminto, saka umandar kapag ligtas."},"ar":{"q":"ماذا يعني الضوء الأحمر الوامض؟","o":["خفف السرعة، لكن لا تحتاج إلى التوقف","توقف تمامًا، ثم انطلق عندما يكون الطريق خاليًا","الإشارة ستصبح خضراء بعد قليل","الشاحنات فقط يجب أن تتوقف"],"h1":"الضوء الأحمر الوامض يعمل مثل لافتة تعرفها بالفعل.","h2":"الضوء الأحمر الوامض يعمل مثل لافتة «STOP» (قف)، لذلك يجب أن تتوقف تمامًا ثم تنطلق عندما يكون الطريق خاليًا.","p":"صحيح. الضوء الأحمر الوامض يعني: توقف، ثم انطلق عندما يكون الطريق آمنًا."},"ht":{"q":"Kisa yon limyè wouj k ap kliyote vle di?","o":["Ralanti, men ou pa bezwen kanpe","Kanpe nèt, epi pase lè wout la lib","Limyè a pral vin vèt talè","Se sèlman kamyon ki dwe kanpe"],"h1":"Yon limyè wouj k ap kliyote mache tankou yon siy ou deja konnen.","h2":"Yon limyè wouj k ap kliyote mache tankou yon siy “STOP”, kidonk ou dwe kanpe nèt epi pase lè wout la lib.","p":"Se sa. Yon limyè wouj k ap kliyote vle di kanpe, epi pase lè sa an sekirite."},"ref":{"doc":"FL","page":52}},{"id":"signals-005","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"What does a flashing yellow light mean?","o":["Slow down and go ahead with care","Stop fully and wait for green","The road is closed ahead","You must turn right"],"h1":"A flashing yellow light is a warning, not an order to stop.","h2":"A flashing yellow light means you should slow down and go ahead with care, because there may be danger ahead.","p":"Right. A flashing yellow light means slow down and be careful."},"es":{"q":"¿Qué significa una luz amarilla intermitente?","o":["Baje la velocidad y siga con cuidado","Pare por completo y espere la verde","La calle está cerrada más adelante","Usted debe girar a la derecha"],"h1":"Una luz amarilla intermitente es una advertencia, no una orden de parar.","h2":"Una luz amarilla intermitente significa que usted debe bajar la velocidad y seguir con cuidado, porque puede haber peligro más adelante.","p":"Correcto. Luz amarilla intermitente significa baje la velocidad y tenga cuidado."},"zh":{"q":"闪烁的黄灯是什么意思？","o":["减速，小心往前开","完全停车，等绿灯","前方道路封闭","你必须右转"],"h1":"闪烁的黄灯是警告，不是要你停车。","h2":"闪烁的黄灯表示你应该减速，小心往前开，因为前方可能有危险。","p":"对。闪烁的黄灯表示减速，要小心。"},"vi":{"q":"Đèn vàng nhấp nháy có nghĩa là gì?","o":["Chạy chậm lại và đi tiếp một cách cẩn thận","Dừng hẳn và chờ đèn xanh","Phía trước đường bị đóng","Bạn phải rẽ phải"],"h1":"Đèn vàng nhấp nháy là lời cảnh báo, không phải lệnh dừng.","h2":"Đèn vàng nhấp nháy nghĩa là bạn cần chạy chậm lại và đi tiếp một cách cẩn thận, vì phía trước có thể có nguy hiểm.","p":"Đúng rồi. Đèn vàng nhấp nháy nghĩa là chạy chậm và cẩn thận."},"tl":{"q":"Ano ang ibig sabihin ng kumikislap na dilaw na ilaw?","o":["Bumagal at magpatuloy nang maingat","Huminto nang buo at hintayin ang berde","Sarado ang kalsada sa unahan","Dapat kang kumanan"],"h1":"Ang kumikislap na dilaw na ilaw ay babala, hindi utos na huminto.","h2":"Ang kumikislap na dilaw na ilaw ay nangangahulugang dapat kang bumagal at magpatuloy nang maingat, dahil maaaring may panganib sa unahan.","p":"Tama. Ang kumikislap na dilaw na ilaw ay nangangahulugang bumagal at mag-ingat."},"ar":{"q":"ماذا يعني الضوء الأصفر الوامض؟","o":["خفف السرعة وتابع بحذر","توقف تمامًا وانتظر الأخضر","الطريق مغلق في الأمام","يجب أن تنعطف يمينًا"],"h1":"الضوء الأصفر الوامض تحذير، وليس أمرًا بالتوقف.","h2":"الضوء الأصفر الوامض يعني أنه يجب أن تخفف السرعة وتتابع بحذر، لأنه قد يكون هناك خطر في الأمام.","p":"صحيح. الضوء الأصفر الوامض يعني: خفف السرعة وكن حذرًا."},"ht":{"q":"Kisa yon limyè jòn k ap kliyote vle di?","o":["Ralanti epi kontinye avèk prekosyon","Kanpe nèt epi tann limyè vèt la","Wout la fèmen pi devan","Ou dwe vire adwat"],"h1":"Yon limyè jòn k ap kliyote se yon avètisman, se pa yon lòd pou kanpe.","h2":"Yon limyè jòn k ap kliyote vle di ou dwe ralanti epi kontinye avèk prekosyon, paske ka gen danje pi devan.","p":"Se sa. Yon limyè jòn k ap kliyote vle di ralanti epi fè atansyon."},"ref":{"doc":"FL","page":52}},{"id":"signals-006","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"The light is steady green. A person is still crossing in the crosswalk. What should you do?","o":["Go, because green gives you the right of way","Honk so the person moves faster","Wait and let the person finish crossing","Drive around the person"],"h1":"A green light lets you go, but think about who was there first.","h2":"A green light lets you go only when the way is clear, so you must wait for people and cars that are already in the intersection.","p":"Right. On green, you still let people finish crossing."},"es":{"q":"La luz está en verde fijo. Una persona todavía está cruzando por el paso peatonal. ¿Qué debe hacer?","o":["Seguir, porque la verde le da el derecho de paso","Tocar la bocina para que la persona se apure","Esperar y dejar que la persona termine de cruzar","Pasar por un lado de la persona"],"h1":"La luz verde le permite seguir, pero piense en quién estaba ahí primero.","h2":"La luz verde le permite seguir solo cuando el camino está libre, así que usted debe esperar a las personas y los carros que ya están en la intersección.","p":"Correcto. Con luz verde, igual deje que las personas terminen de cruzar."},"zh":{"q":"灯是一直亮着的绿灯。有一个人还在人行横道上过马路。你应该怎么做？","o":["开走，因为绿灯给你优先通行权","按喇叭让那个人走快点","等一等，让那个人走完","绕过那个人开过去"],"h1":"绿灯让你走，但想一想谁先在那里。","h2":"绿灯只有在路上没有人和车时才让你走，所以你必须等已经在路口里的行人和车辆。","p":"对。绿灯时，你仍然要让行人走完。"},"vi":{"q":"Đèn xanh sáng đứng yên. Có một người vẫn đang đi qua vạch qua đường. Bạn nên làm gì?","o":["Cứ đi, vì đèn xanh cho bạn quyền đi trước","Bấm còi để người đó đi nhanh hơn","Chờ và để người đó đi qua hết","Chạy vòng qua người đó"],"h1":"Đèn xanh cho bạn đi, nhưng hãy nghĩ xem ai đã ở đó trước.","h2":"Đèn xanh chỉ cho bạn đi khi đường đã trống, nên bạn phải chờ người đi bộ và xe đang ở trong giao lộ.","p":"Đúng rồi. Khi đèn xanh, bạn vẫn phải để người đi bộ qua hết."},"tl":{"q":"Tuloy-tuloy na berde ang ilaw. May tao pang tumatawid sa tawiran. Ano ang dapat mong gawin?","o":["Umandar, dahil ang berde ay nagbibigay sa iyo ng karapatang mauna","Bumusina para bilisan ng tao ang paglakad","Maghintay at hayaang matapos ng tao ang pagtawid","Lumihis paikot sa tao"],"h1":"Pinapayagan ka ng berdeng ilaw na umandar, pero isipin kung sino ang naunang nandoon.","h2":"Pinapayagan ka ng berdeng ilaw na umandar lang kapag maluwag na ang daan, kaya dapat mong hintayin ang mga tao at sasakyang nasa loob na ng interseksyon.","p":"Tama. Kahit berde, hayaan mo pa ring matapos tumawid ang mga tao."},"ar":{"q":"الإشارة خضراء ثابتة. شخص ما زال يعبر في ممر المشاة. ماذا يجب أن تفعل؟","o":["انطلق، لأن الأخضر يعطيك حق المرور","استخدم البوق لكي يسرع الشخص","انتظر ودع الشخص يكمل العبور","قُد حول الشخص"],"h1":"الضوء الأخضر يسمح لك بالانطلاق، لكن فكّر في من كان هناك أولًا.","h2":"الضوء الأخضر يسمح لك بالانطلاق فقط عندما يكون الطريق خاليًا، لذلك يجب أن تنتظر الأشخاص والسيارات الموجودين داخل التقاطع بالفعل.","p":"صحيح. عند الأخضر، ما زلت تترك الناس يكملون العبور."},"ht":{"q":"Limyè a vèt fiks. Gen yon moun ki toujou ap travèse nan pasaj pyeton an. Kisa ou dwe fè?","o":["Pase, paske limyè vèt la ba ou dwa pou pase","Klaksonen pou moun nan mache pi vit","Tann epi kite moun nan fini travèse","Pase bò kote moun nan"],"h1":"Yon limyè vèt kite ou pase, men panse ak kiyès ki te la anvan.","h2":"Yon limyè vèt kite ou pase sèlman lè wout la lib, kidonk ou dwe tann moun ak machin ki deja nan kafou a.","p":"Se sa. Sou limyè vèt, ou toujou kite moun yo fini travèse."},"ref":{"doc":"FL","page":51}},{"id":"signals-007","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"You see a steady green arrow pointing left. What does it mean?","o":["You may not turn left","You must yield to all oncoming cars first","Only buses may turn left","You may turn left, and oncoming traffic should be stopped"],"h1":"A green arrow gives a special turn. Think about what the other traffic sees.","h2":"A steady green arrow means you may turn in the direction of the arrow, because oncoming traffic should be facing a red light.","p":"Right. A green arrow means you may make that turn."},"es":{"q":"Usted ve una flecha verde fija que apunta a la izquierda. ¿Qué significa?","o":["No puede girar a la izquierda","Debe ceder el paso primero a todos los carros de frente","Solo los autobuses pueden girar a la izquierda","Puede girar a la izquierda, y el tráfico de frente debe estar parado"],"h1":"Una flecha verde da un giro especial. Piense qué ve el otro tráfico.","h2":"Una flecha verde fija significa que usted puede girar en la dirección de la flecha, porque el tráfico de frente debe tener luz roja.","p":"Correcto. Una flecha verde significa que puede hacer ese giro."},"zh":{"q":"你看到一个一直亮着、指向左边的绿色箭头。它是什么意思？","o":["你不能左转","你必须先让所有对面来车","只有公交车可以左转","你可以左转，对面来车应该在停着"],"h1":"绿色箭头给你一个专门的转弯时间。想一想其他车看到的是什么。","h2":"一直亮着的绿色箭头表示你可以按箭头方向转弯，因为对面来车这时应该是红灯。","p":"对。绿色箭头表示你可以这样转弯。"},"vi":{"q":"Bạn thấy mũi tên xanh sáng đứng yên chỉ sang trái. Điều đó có nghĩa là gì?","o":["Bạn không được rẽ trái","Bạn phải nhường tất cả xe ngược chiều trước","Chỉ xe buýt được rẽ trái","Bạn được rẽ trái, và xe ngược chiều lẽ ra đang phải dừng"],"h1":"Mũi tên xanh cho phép một lượt rẽ riêng. Hãy nghĩ xem xe bên kia đang thấy đèn gì.","h2":"Mũi tên xanh sáng đứng yên nghĩa là bạn được rẽ theo hướng mũi tên, vì xe ngược chiều lẽ ra đang gặp đèn đỏ.","p":"Đúng rồi. Mũi tên xanh nghĩa là bạn được rẽ theo hướng đó."},"tl":{"q":"May nakita kang tuloy-tuloy na berdeng arrow na nakaturo pakaliwa. Ano ang ibig sabihin nito?","o":["Hindi ka puwedeng kumaliwa","Dapat mo munang paunahin ang lahat ng paparating na sasakyan","Mga bus lang ang puwedeng kumaliwa","Puwede kang kumaliwa, at dapat nakahinto ang paparating na trapiko"],"h1":"Ang berdeng arrow ay nagbibigay ng espesyal na pagliko. Isipin kung ano ang nakikita ng ibang trapiko.","h2":"Ang tuloy-tuloy na berdeng arrow ay nangangahulugang puwede kang lumiko sa direksyon ng arrow, dahil dapat nakaharap sa pulang ilaw ang paparating na trapiko.","p":"Tama. Ang berdeng arrow ay nangangahulugang puwede kang lumiko sa direksyong iyon."},"ar":{"q":"ترى سهمًا أخضر ثابتًا يشير إلى اليسار. ماذا يعني؟","o":["ممنوع أن تنعطف يسارًا","يجب أن تعطي الأولوية لكل السيارات القادمة أولًا","الحافلات فقط يمكنها أن تنعطف يسارًا","يمكنك أن تنعطف يسارًا، والسيارات القادمة يجب أن تكون متوقفة"],"h1":"السهم الأخضر يعطي انعطافًا خاصًا. فكّر في ما تراه السيارات الأخرى.","h2":"السهم الأخضر الثابت يعني أنه يمكنك أن تنعطف في اتجاه السهم، لأن السيارات القادمة يجب أن تكون أمام ضوء أحمر.","p":"صحيح. السهم الأخضر يعني أنه يمكنك أن تقوم بهذا الانعطاف."},"ht":{"q":"Ou wè yon flèch vèt fiks ki montre agoch. Kisa li vle di?","o":["Ou pa ka vire agoch","Ou dwe kite tout machin k ap vin sou ou pase anvan","Se sèlman bis ki ka vire agoch","Ou ka vire agoch, epi machin k ap vin sou ou yo ta dwe kanpe"],"h1":"Yon flèch vèt bay yon vire espesyal. Panse ak sa lòt machin yo wè.","h2":"Yon flèch vèt fiks vle di ou ka vire nan direksyon flèch la, paske machin k ap vin sou ou yo ta dwe gen yon limyè wouj devan yo.","p":"Se sa. Yon flèch vèt vle di ou ka fè vire sa a."},"ref":{"doc":"FL","page":52}},{"id":"signals-008","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"What does a flashing yellow arrow pointing left mean?","o":["You may turn left, and oncoming traffic is stopped","You may turn left, but you must yield to oncoming traffic and people walking","You must stop and wait for a green arrow","Left turns are not allowed here"],"h1":"Flashing yellow is a warning. Think about whether oncoming cars can still come.","h2":"A flashing yellow arrow means you may turn left, but you must first yield to oncoming traffic and to people walking, because they may still have a green light.","p":"Right. A flashing yellow arrow means turn only after you yield."},"es":{"q":"¿Qué significa una flecha amarilla intermitente que apunta a la izquierda?","o":["Puede girar a la izquierda, y el tráfico de frente está parado","Puede girar a la izquierda, pero debe ceder el paso al tráfico de frente y a los peatones","Debe parar y esperar una flecha verde","No se permite girar a la izquierda aquí"],"h1":"El amarillo intermitente es una advertencia. Piense si los carros de frente todavía pueden venir.","h2":"Una flecha amarilla intermitente significa que usted puede girar a la izquierda, pero primero debe ceder el paso al tráfico de frente y a los peatones, porque ellos pueden tener luz verde.","p":"Correcto. Flecha amarilla intermitente significa gire solo después de ceder el paso."},"zh":{"q":"闪烁的黄色左转箭头是什么意思？","o":["你可以左转，对面来车已经停了","你可以左转，但必须让对面来车和行人先走","你必须停车，等绿色箭头","这里不准左转"],"h1":"闪烁的黄色是警告。想一想对面的车是不是还可能开过来。","h2":"闪烁的黄色箭头表示你可以左转，但必须先让对面来车和行人先走，因为他们可能还是绿灯。","p":"对。闪烁的黄色箭头表示先让行，再转弯。"},"vi":{"q":"Mũi tên vàng nhấp nháy chỉ sang trái có nghĩa là gì?","o":["Bạn được rẽ trái, và xe ngược chiều đang dừng","Bạn được rẽ trái, nhưng phải nhường xe ngược chiều và người đi bộ","Bạn phải dừng và chờ mũi tên xanh","Ở đây cấm rẽ trái"],"h1":"Màu vàng nhấp nháy là lời cảnh báo. Hãy nghĩ xem xe ngược chiều có còn chạy tới không.","h2":"Mũi tên vàng nhấp nháy nghĩa là bạn được rẽ trái, nhưng trước hết phải nhường xe ngược chiều và người đi bộ, vì họ có thể vẫn đang có đèn xanh.","p":"Đúng rồi. Mũi tên vàng nhấp nháy nghĩa là chỉ rẽ sau khi đã nhường đường."},"tl":{"q":"Ano ang ibig sabihin ng kumikislap na dilaw na arrow na nakaturo pakaliwa?","o":["Puwede kang kumaliwa, at nakahinto ang paparating na trapiko","Puwede kang kumaliwa, pero dapat mong paunahin ang paparating na trapiko at ang mga taong naglalakad","Dapat kang huminto at maghintay ng berdeng arrow","Bawal kumaliwa dito"],"h1":"Ang kumikislap na dilaw ay babala. Isipin kung puwede pa ring dumating ang mga paparating na sasakyan.","h2":"Ang kumikislap na dilaw na arrow ay nangangahulugang puwede kang kumaliwa, pero dapat mo munang paunahin ang paparating na trapiko at ang mga taong naglalakad, dahil maaaring berde pa rin ang ilaw nila.","p":"Tama. Ang kumikislap na dilaw na arrow ay nangangahulugang lumiko lang pagkatapos mong magbigay-daan."},"ar":{"q":"ماذا يعني سهم أصفر وامض يشير إلى اليسار؟","o":["يمكنك أن تنعطف يسارًا، والسيارات القادمة متوقفة","يمكنك أن تنعطف يسارًا، لكن يجب أن تعطي الأولوية للسيارات القادمة وللمشاة","يجب أن تتوقف وتنتظر سهمًا أخضر","الانعطاف يسارًا ممنوع هنا"],"h1":"الأصفر الوامض تحذير. فكّر: هل ما زالت السيارات القادمة يمكن أن تأتي؟","h2":"السهم الأصفر الوامض يعني أنه يمكنك أن تنعطف يسارًا، لكن يجب أولًا أن تعطي الأولوية للسيارات القادمة وللمشاة، لأن الإشارة قد تكون ما زالت خضراء لهم.","p":"صحيح. السهم الأصفر الوامض يعني: انعطف فقط بعد أن تعطي الأولوية."},"ht":{"q":"Kisa yon flèch jòn k ap kliyote ki montre agoch vle di?","o":["Ou ka vire agoch, epi machin k ap vin sou ou yo kanpe","Ou ka vire agoch, men ou dwe kite machin k ap vin sou ou ak moun k ap mache pase anvan","Ou dwe kanpe epi tann yon flèch vèt","Ou pa gen dwa vire agoch la a"],"h1":"Jòn k ap kliyote se yon avètisman. Panse si machin k ap vin sou ou yo ka toujou vini.","h2":"Yon flèch jòn k ap kliyote vle di ou ka vire agoch, men ou dwe kite machin k ap vin sou ou ak moun k ap mache pase anvan, paske yo ka toujou gen yon limyè vèt.","p":"Se sa. Yon flèch jòn k ap kliyote vle di vire sèlman apre ou fin bay pasaj."},"ref":{"doc":"FL","page":52}},{"id":"signals-009","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"What does a steady yellow arrow mean?","o":["The protected turn is ending, so stop if you can do it safely","You may now turn without looking","Wait for the cars behind you","The turn lane is closed for the day"],"h1":"A steady yellow arrow works like a steady yellow light, but for a turn.","h2":"A steady yellow arrow means the arrow will soon turn red, so you should stop if you can do it safely.","p":"Right. A steady yellow arrow means the turn time is ending."},"es":{"q":"¿Qué significa una flecha amarilla fija?","o":["El giro protegido está terminando, así que pare si lo puede hacer con seguridad","Ahora puede girar sin mirar","Espere a los carros que vienen detrás","El carril de giro está cerrado todo el día"],"h1":"Una flecha amarilla fija funciona como una luz amarilla fija, pero para un giro.","h2":"Una flecha amarilla fija significa que la flecha pronto cambiará a roja, así que usted debe parar si lo puede hacer con seguridad.","p":"Correcto. Una flecha amarilla fija significa que el tiempo del giro se acaba."},"zh":{"q":"一直亮着的黄色箭头是什么意思？","o":["专用转弯时间要结束了，能安全停下就停车","你现在可以不看就转弯","等你后面的车","转弯车道今天关闭"],"h1":"一直亮着的黄色箭头和一直亮着的黄灯一样，只是用于转弯。","h2":"一直亮着的黄色箭头表示箭头马上要变红，所以如果能安全停下，你就应该停车。","p":"对。一直亮着的黄色箭头表示转弯时间要结束了。"},"vi":{"q":"Mũi tên vàng sáng đứng yên có nghĩa là gì?","o":["Lượt rẽ được bảo vệ sắp hết, nên hãy dừng nếu bạn có thể dừng an toàn","Bây giờ bạn được rẽ mà không cần nhìn","Chờ các xe phía sau bạn","Làn rẽ bị đóng cả ngày"],"h1":"Mũi tên vàng sáng đứng yên giống như đèn vàng sáng đứng yên, nhưng dành cho lượt rẽ.","h2":"Mũi tên vàng sáng đứng yên nghĩa là mũi tên sắp chuyển sang đỏ, nên bạn cần dừng lại nếu có thể dừng an toàn.","p":"Đúng rồi. Mũi tên vàng sáng đứng yên nghĩa là thời gian rẽ sắp hết."},"tl":{"q":"Ano ang ibig sabihin ng tuloy-tuloy na dilaw na arrow?","o":["Matatapos na ang protektadong pagliko, kaya huminto kung kaya mong gawin ito nang ligtas","Puwede ka nang lumiko nang hindi tumitingin","Hintayin ang mga sasakyan sa likod mo","Sarado ang turn lane sa buong araw"],"h1":"Ang tuloy-tuloy na dilaw na arrow ay gumagana na parang tuloy-tuloy na dilaw na ilaw, pero para sa pagliko.","h2":"Ang tuloy-tuloy na dilaw na arrow ay nangangahulugang malapit nang maging pula ang arrow, kaya dapat kang huminto kung kaya mong gawin ito nang ligtas.","p":"Tama. Ang tuloy-tuloy na dilaw na arrow ay nangangahulugang matatapos na ang oras ng pagliko."},"ar":{"q":"ماذا يعني السهم الأصفر الثابت؟","o":["وقت الانعطاف المحمي ينتهي، لذلك توقف إذا استطعت أن تفعل ذلك بأمان","الآن يمكنك أن تنعطف بدون أن تنظر","انتظر السيارات التي خلفك","مسار الانعطاف مغلق لبقية اليوم"],"h1":"السهم الأصفر الثابت يعمل مثل الضوء الأصفر الثابت، لكن للانعطاف.","h2":"السهم الأصفر الثابت يعني أن السهم سيصبح أحمر قريبًا، لذلك يجب أن تتوقف إذا استطعت أن تفعل ذلك بأمان.","p":"صحيح. السهم الأصفر الثابت يعني أن وقت الانعطاف ينتهي."},"ht":{"q":"Kisa yon flèch jòn fiks vle di?","o":["Tan pou vire ki pwoteje a ap fini, kidonk kanpe si ou ka fè l an sekirite","Kounye a ou ka vire san ou pa gade","Tann machin ki dèyè ou yo","Koulwa pou vire a fèmen pou jounen an"],"h1":"Yon flèch jòn fiks mache tankou yon limyè jòn fiks, men pou yon vire.","h2":"Yon flèch jòn fiks vle di flèch la pral vin wouj talè, kidonk ou dwe kanpe si ou ka fè l an sekirite.","p":"Se sa. Yon flèch jòn fiks vle di tan pou vire a ap fini."},"ref":{"doc":"FL","page":52}},{"id":"signals-010","scope":"FL","cat":"signals","sign":null,"c":2,"en":{"q":"In Florida, you are on a two-way street. A steady red arrow points left. What must you do?","o":["Turn left after a full stop if no one is coming","Turn left slowly without stopping","Stop and do not turn left until the signal allows it","Use the next lane to turn left instead"],"h1":"Think about what a red signal means, even when it is shaped like an arrow.","h2":"In Florida, on a two-way street, a steady red arrow pointing left means you must stop and must not turn left until a green arrow or green light lets you.","p":"Right. A red left arrow means no left turn yet."},"es":{"q":"En Florida, usted está en una calle de doble sentido. Una flecha roja fija apunta a la izquierda. ¿Qué debe hacer?","o":["Girar a la izquierda después de parar por completo si no viene nadie","Girar a la izquierda despacio sin parar","Parar y no girar a la izquierda hasta que la señal lo permita","Usar el otro carril para girar a la izquierda"],"h1":"Piense qué significa una señal roja, aunque tenga forma de flecha.","h2":"En Florida, en una calle de doble sentido, una flecha roja fija que apunta a la izquierda significa que usted debe parar y no puede girar a la izquierda hasta que una flecha verde o luz verde se lo permita.","p":"Correcto. Una flecha roja a la izquierda significa que todavía no puede girar."},"zh":{"q":"在 Florida，你在一条双向街道上。一个一直亮着的红色箭头指向左边。你必须怎么做？","o":["完全停车后，没车就左转","不停车，慢慢左转","停车，在信号允许前不要左转","改用旁边的车道左转"],"h1":"想一想红色信号的意思，就算它是箭头的形状。","h2":"在 Florida 的双向街道上，指向左边、一直亮着的红色箭头表示你必须停车，在绿色箭头或绿灯允许之前不能左转。","p":"对。红色左转箭头表示现在还不能左转。"},"vi":{"q":"Ở Florida, bạn đang ở trên đường hai chiều. Một mũi tên đỏ sáng đứng yên chỉ sang trái. Bạn phải làm gì?","o":["Rẽ trái sau khi dừng hẳn nếu không có ai tới","Rẽ trái chậm mà không cần dừng","Dừng lại và không rẽ trái cho tới khi đèn cho phép","Dùng làn bên cạnh để rẽ trái"],"h1":"Hãy nghĩ xem tín hiệu màu đỏ có nghĩa là gì, ngay cả khi nó có hình mũi tên.","h2":"Ở Florida, trên đường hai chiều, mũi tên đỏ sáng đứng yên chỉ sang trái nghĩa là bạn phải dừng lại và không được rẽ trái cho tới khi có mũi tên xanh hoặc đèn xanh cho phép.","p":"Đúng rồi. Mũi tên đỏ chỉ trái nghĩa là chưa được rẽ trái."},"tl":{"q":"Sa Florida, nasa kalyeng dalawa ang direksyon ka. May tuloy-tuloy na pulang arrow na nakaturo pakaliwa. Ano ang dapat mong gawin?","o":["Kumaliwa pagkatapos huminto nang buo kung walang dumarating","Kumaliwa nang dahan-dahan nang hindi humihinto","Huminto at huwag kumaliwa hanggang payagan ka ng ilaw","Gamitin ang katabing linya para kumaliwa"],"h1":"Isipin kung ano ang ibig sabihin ng pulang ilaw, kahit hugis arrow pa ito.","h2":"Sa Florida, sa kalyeng dalawa ang direksyon, ang tuloy-tuloy na pulang arrow na nakaturo pakaliwa ay nangangahulugang dapat kang huminto at hindi ka puwedeng kumaliwa hanggang payagan ka ng berdeng arrow o berdeng ilaw.","p":"Tama. Ang pulang arrow pakaliwa ay nangangahulugang hindi pa puwedeng kumaliwa."},"ar":{"q":"في Florida، أنت في شارع باتجاهين. سهم أحمر ثابت يشير إلى اليسار. ماذا يجب أن تفعل؟","o":["انعطف يسارًا بعد توقف تام إذا لم يأتِ أحد","انعطف يسارًا ببطء بدون أن تتوقف","توقف ولا تنعطف يسارًا حتى تسمح لك الإشارة","استخدم المسار المجاور لتنعطف يسارًا بدلًا من ذلك"],"h1":"فكّر في معنى الإشارة الحمراء، حتى لو كانت على شكل سهم.","h2":"في Florida، في شارع باتجاهين، السهم الأحمر الثابت إلى اليسار يعني أنه يجب أن تتوقف ولا تنعطف يسارًا حتى يسمح لك سهم أخضر أو ضوء أخضر.","p":"صحيح. السهم الأحمر إلى اليسار يعني: لا تنعطف يسارًا بعد."},"ht":{"q":"Nan Florida, ou sou yon lari ki gen de direksyon. Yon flèch wouj fiks montre agoch. Kisa ou dwe fè?","o":["Vire agoch apre ou fin kanpe nèt si pa gen moun k ap vini","Vire agoch dousman san ou pa kanpe","Kanpe epi pa vire agoch jiskaske siyal la pèmèt ou","Sèvi ak lòt koulwa a pou vire agoch pito"],"h1":"Panse ak sa yon siyal wouj vle di, menm lè li gen fòm yon flèch.","h2":"Nan Florida, sou yon lari ki gen de direksyon, yon flèch wouj fiks ki montre agoch vle di ou dwe kanpe epi ou pa dwe vire agoch jiskaske yon flèch vèt oswa yon limyè vèt kite ou pase.","p":"Se sa. Yon flèch wouj agoch vle di ou pa ka vire agoch ankò."},"ref":{"doc":"FL","page":52}},{"id":"signals-011","scope":"FL","cat":"signals","sign":null,"c":1,"en":{"q":"In Florida, may you turn right on a steady red light?","o":["Yes, without stopping, if no one is coming","Yes, after a full stop, if no sign forbids it and the way is clear","No, never","Only between midnight and 6 a.m."],"h1":"Think about two things: a full stop, and any sign at the corner.","h2":"In Florida, you may turn right on a red light after you stop fully and yield, unless a sign says no turn on red.","p":"Right. Stop fully, yield, and then you may turn right on red unless a sign forbids it."},"es":{"q":"En Florida, ¿puede girar a la derecha con luz roja fija?","o":["Sí, sin parar, si no viene nadie","Sí, después de parar por completo, si ninguna señal lo prohíbe y el camino está libre","No, nunca","Solo entre la medianoche y las 6 a.m."],"h1":"Piense en dos cosas: parar por completo y cualquier señal en la esquina.","h2":"En Florida, usted puede girar a la derecha con luz roja después de parar por completo y ceder el paso, a menos que una señal prohíba girar con luz roja.","p":"Correcto. Pare por completo, ceda el paso, y luego puede girar a la derecha con roja si ninguna señal lo prohíbe."},"zh":{"q":"在 Florida，一直亮着红灯时，你可以右转吗？","o":["可以，没有来车就不用停","可以，完全停车后，没有标志禁止，而且路上没车","不可以，永远不行","只在午夜到早上 6 点之间可以"],"h1":"想两件事：完全停车，和路口有没有标志。","h2":"在 Florida，你完全停车并让行后，可以在红灯时右转，除非有标志写着红灯禁止转弯。","p":"对。完全停车，让行，然后可以红灯右转，除非有标志禁止。"},"vi":{"q":"Ở Florida, bạn có được rẽ phải khi đèn đỏ sáng đứng yên không?","o":["Có, không cần dừng, nếu không có ai tới","Có, sau khi dừng hẳn, nếu không có biển cấm và đường đã trống","Không, không bao giờ","Chỉ từ nửa đêm tới 6 giờ sáng"],"h1":"Hãy nghĩ đến hai điều: dừng hẳn, và biển báo ở góc đường.","h2":"Ở Florida, bạn được rẽ phải khi đèn đỏ sau khi đã dừng hẳn và nhường đường, trừ khi có biển “NO TURN ON RED” (Cấm rẽ khi đèn đỏ).","p":"Đúng rồi. Dừng hẳn, nhường đường, rồi bạn được rẽ phải khi đèn đỏ, trừ khi có biển cấm."},"tl":{"q":"Sa Florida, puwede ka bang kumanan kapag tuloy-tuloy na pula ang ilaw?","o":["Oo, nang hindi humihinto, kung walang dumarating","Oo, pagkatapos huminto nang buo, kung walang karatulang nagbabawal at maluwag ang daan","Hindi, kailanman","Mula hatinggabi hanggang 6 a.m. lang"],"h1":"Isipin ang dalawang bagay: ang paghinto nang buo, at kung may karatula sa kanto.","h2":"Sa Florida, puwede kang kumanan kapag pula ang ilaw pagkatapos mong huminto nang buo at magbigay-daan, maliban kung may karatulang “NO TURN ON RED”.","p":"Tama. Huminto nang buo, magbigay-daan, at saka puwede kang kumanan sa pula maliban kung may karatulang nagbabawal."},"ar":{"q":"في Florida، هل يمكنك أن تنعطف يمينًا عند ضوء أحمر ثابت؟","o":["نعم، بدون توقف، إذا لم يأتِ أحد","نعم، بعد توقف تام، إذا لم تمنع ذلك لافتة وكان الطريق خاليًا","لا، أبدًا","فقط بين منتصف الليل والساعة 6 صباحًا"],"h1":"فكّر في أمرين: التوقف التام، وأي لافتة عند الزاوية.","h2":"في Florida، يمكنك أن تنعطف يمينًا عند الضوء الأحمر بعد أن تتوقف تمامًا وتعطي الأولوية، إلا إذا كانت هناك لافتة تقول «NO TURN ON RED» (ممنوع الانعطاف عند الأحمر).","p":"صحيح. توقف تمامًا، وأعطِ الأولوية، ثم يمكنك أن تنعطف يمينًا عند الأحمر إلا إذا منعت ذلك لافتة."},"ht":{"q":"Nan Florida, èske ou ka vire adwat sou yon limyè wouj fiks?","o":["Wi, san ou pa kanpe, si pa gen moun k ap vini","Wi, apre ou fin kanpe nèt, si pa gen siy ki entèdi sa epi wout la lib","Non, pa janm","Sèlman ant minwi ak 6 è dimaten"],"h1":"Panse ak de bagay: kanpe nèt, ak nenpòt siy ki nan kwen an.","h2":"Nan Florida, ou ka vire adwat sou limyè wouj apre ou fin kanpe nèt epi bay pasaj, sof si yon siy di “NO TURN ON RED”.","p":"Se sa. Kanpe nèt, bay pasaj, epi ou ka vire adwat sou wouj sof si yon siy entèdi sa."},"ref":{"doc":"FL","page":51}},{"id":"signals-012","scope":"FL","cat":"signals","sign":null,"c":3,"en":{"q":"In Florida, when may you turn left on a red light?","o":["From any street, if no one is coming","Never, under any condition","Only when you are in a hurry","From a one-way street onto another one-way street going left, after a full stop"],"h1":"Think about which streets have no oncoming traffic.","h2":"In Florida, you may turn left on red only from a one-way street onto a one-way street that goes left, and only after a full stop when the way is clear and no sign forbids it.","p":"Right. Left on red is only from one-way to one-way, after a full stop."},"es":{"q":"En Florida, ¿cuándo puede girar a la izquierda con luz roja?","o":["Desde cualquier calle, si no viene nadie","Nunca, en ningún caso","Solo cuando tiene prisa","De una calle de un solo sentido a otra calle de un solo sentido que va a la izquierda, después de parar por completo"],"h1":"Piense en qué calles no tienen tráfico de frente.","h2":"En Florida, usted puede girar a la izquierda con luz roja solo de una calle de un solo sentido a otra de un solo sentido que va a la izquierda, y solo después de parar por completo, con el camino libre y sin una señal que lo prohíba.","p":"Correcto. Izquierda con roja solo de un solo sentido a un solo sentido, después de parar."},"zh":{"q":"在 Florida，什么时候可以在红灯时左转？","o":["从任何街道都行，只要没有来车","不行，什么情况都不行","只在你赶时间的时候","从单行道左转进入另一条往左走的单行道，并且要先完全停车"],"h1":"想一想：哪些街道没有对面来车。","h2":"在 Florida，只有从单行道左转进入往左走的单行道时，才可以在红灯时左转，而且要先完全停车，路上没车，也没有标志禁止。","p":"对。红灯左转只能从单行道到单行道，并且要先完全停车。"},"vi":{"q":"Ở Florida, khi nào bạn được rẽ trái lúc đèn đỏ?","o":["Từ bất cứ đường nào, nếu không có ai tới","Không bao giờ, trong bất cứ trường hợp nào","Chỉ khi bạn đang vội","Từ đường một chiều rẽ trái vào một đường một chiều khác, sau khi dừng hẳn"],"h1":"Hãy nghĩ xem đường nào không có xe chạy ngược chiều.","h2":"Ở Florida, bạn chỉ được rẽ trái khi đèn đỏ từ đường một chiều vào một đường một chiều chạy về phía trái, và chỉ sau khi dừng hẳn, khi đường đã trống và không có biển cấm.","p":"Đúng rồi. Rẽ trái khi đèn đỏ chỉ được từ đường một chiều sang đường một chiều, sau khi dừng hẳn."},"tl":{"q":"Sa Florida, kailan ka puwedeng kumaliwa kapag pula ang ilaw?","o":["Mula sa kahit anong kalye, kung walang dumarating","Hindi kailanman, sa anumang sitwasyon","Kapag nagmamadali ka lang","Mula sa one-way na kalye papunta sa isa pang one-way na kalye na papunta sa kaliwa, pagkatapos huminto nang buo"],"h1":"Isipin kung aling mga kalye ang walang paparating na trapiko.","h2":"Sa Florida, puwede kang kumaliwa sa pula mula lang sa one-way na kalye papunta sa one-way na kalye na papunta sa kaliwa, at pagkatapos lang huminto nang buo kapag maluwag ang daan at walang karatulang nagbabawal.","p":"Tama. Ang pagkaliwa sa pula ay mula lang sa one-way papunta sa one-way, pagkatapos huminto nang buo."},"ar":{"q":"في Florida، متى يمكنك أن تنعطف يسارًا عند ضوء أحمر؟","o":["من أي شارع، إذا لم يأتِ أحد","أبدًا، في أي حال","فقط عندما تكون مستعجلًا","من شارع باتجاه واحد إلى شارع آخر باتجاه واحد يسير نحو اليسار، بعد توقف تام"],"h1":"فكّر في الشوارع التي لا تأتي فيها سيارات من الاتجاه المقابل.","h2":"في Florida، يمكنك أن تنعطف يسارًا عند الأحمر فقط من شارع باتجاه واحد إلى شارع باتجاه واحد يسير نحو اليسار، وفقط بعد توقف تام عندما يكون الطريق خاليًا ولا تمنع ذلك لافتة.","p":"صحيح. الانعطاف يسارًا عند الأحمر مسموح فقط من اتجاه واحد إلى اتجاه واحد، بعد توقف تام."},"ht":{"q":"Nan Florida, ki lè ou ka vire agoch sou yon limyè wouj?","o":["Sou nenpòt lari, si pa gen moun k ap vini","Pa janm, nan okenn kondisyon","Sèlman lè ou prese","Soti sou yon lari yon sèl direksyon pou antre sou yon lòt lari yon sèl direksyon ki ale agoch, apre ou fin kanpe nèt"],"h1":"Panse ak ki lari ki pa gen machin k ap vin sou ou.","h2":"Nan Florida, ou ka vire agoch sou wouj sèlman soti sou yon lari yon sèl direksyon pou antre sou yon lari yon sèl direksyon ki ale agoch, epi sèlman apre ou fin kanpe nèt lè wout la lib epi pa gen siy ki entèdi sa.","p":"Se sa. Vire agoch sou wouj se sèlman soti sou yon sèl direksyon pou antre sou yon sèl direksyon, apre ou fin kanpe nèt."},"ref":{"doc":"FL","page":51}},{"id":"signals-013","scope":"FL","cat":"signals","sign":null,"c":0,"en":{"q":"In Florida, the traffic lights at an intersection are dark because the power is out. What should you do?","o":["Treat it as an all-way stop","Go through without stopping","Honk and go first","Treat it as a yield for you only"],"h1":"With no signal working, think about which sign makes every driver take turns.","h2":"In Florida, when traffic lights are not working, you treat the intersection as an all-way stop, so every driver stops and then goes in turn.","p":"Right. A dark signal means an all-way stop."},"es":{"q":"En Florida, los semáforos de una intersección están apagados porque no hay electricidad. ¿Qué debe hacer?","o":["Tratarla como una parada en todas las direcciones","Pasar sin parar","Tocar la bocina y pasar primero","Tratarla como un ceda el paso solo para usted"],"h1":"Si ninguna señal funciona, piense qué señal hace que todos los conductores tomen turnos.","h2":"En Florida, cuando los semáforos no funcionan, usted trata la intersección como una parada en todas las direcciones, así que cada conductor para y luego sigue por turno.","p":"Correcto. Un semáforo apagado significa parada en todas las direcciones."},"zh":{"q":"在 Florida，因为停电，路口的红绿灯不亮了。你应该怎么做？","o":["把它当作全向停车路口","不停车直接开过去","按喇叭，自己先走","当作只有你要让行"],"h1":"信号灯坏了时，想一想哪种标志让每个司机轮流走。","h2":"在 Florida，红绿灯不工作时，你要把路口当作全向停车路口，所以每个司机都先停车，然后轮流走。","p":"对。信号灯不亮表示全向停车。"},"vi":{"q":"Ở Florida, đèn giao thông ở một giao lộ bị tắt vì mất điện. Bạn nên làm gì?","o":["Xem đó là giao lộ mọi hướng đều phải dừng","Chạy qua mà không dừng","Bấm còi và đi trước","Xem như chỉ mình bạn phải nhường đường"],"h1":"Khi đèn không hoạt động, hãy nghĩ xem biển nào khiến mọi tài xế phải đi lần lượt.","h2":"Ở Florida, khi đèn giao thông không hoạt động, bạn xem giao lộ đó là nơi mọi hướng đều phải dừng, nên mọi tài xế đều dừng rồi đi lần lượt.","p":"Đúng rồi. Đèn tắt nghĩa là mọi hướng đều phải dừng."},"tl":{"q":"Sa Florida, patay ang mga ilaw trapiko sa isang interseksyon dahil walang kuryente. Ano ang dapat mong gawin?","o":["Ituring itong all-way stop (lahat ay hihinto)","Dumaan nang hindi humihinto","Bumusina at mauna","Ituring itong yield para sa iyo lang"],"h1":"Kapag walang gumaganang ilaw, isipin kung aling karatula ang nagpapasalitan sa lahat ng driver.","h2":"Sa Florida, kapag hindi gumagana ang mga ilaw trapiko, ituring mo ang interseksyon bilang all-way stop, kaya bawat driver ay hihinto at saka aandar nang salitan.","p":"Tama. Ang patay na ilaw trapiko ay nangangahulugang all-way stop."},"ar":{"q":"في Florida، إشارات المرور في تقاطع مطفأة لأن الكهرباء مقطوعة. ماذا يجب أن تفعل؟","o":["تعامل معه كتقاطع يتوقف فيه الجميع","اعبر بدون توقف","استخدم البوق وانطلق أولًا","تعامل معه كإعطاء أولوية لك وحدك"],"h1":"عندما لا تعمل الإشارة، فكّر في اللافتة التي تجعل كل سائق ينتظر دوره.","h2":"في Florida، عندما لا تعمل إشارات المرور، تتعامل مع التقاطع كتقاطع يتوقف فيه الجميع، لذلك كل سائق يتوقف ثم ينطلق حسب دوره.","p":"صحيح. الإشارة المطفأة تعني أن الجميع يتوقفون."},"ht":{"q":"Nan Florida, limyè trafik yo nan yon kafou etenn paske kouran an koupe. Kisa ou dwe fè?","o":["Fè l tankou yon kafou kote tout moun kanpe","Travèse san ou pa kanpe","Klaksonen epi pase anvan","Fè l tankou yon siy “YIELD” pou ou sèlman"],"h1":"Lè pa gen siyal k ap mache, panse ak ki siy ki fè chak chofè pase youn apre lòt.","h2":"Nan Florida, lè limyè trafik yo pa mache, ou fè kafou a tankou yon kafou kote tout moun kanpe, kidonk chak chofè kanpe epi pase youn apre lòt.","p":"Se sa. Yon limyè ki etenn vle di tout moun kanpe."},"ref":{"doc":"FL","page":51}},{"id":"signals-014","scope":"FL","cat":"signals","sign":null,"c":2,"en":{"q":"In Florida, your light is green, but the traffic ahead is backed up into the intersection. What should you do?","o":["Go in anyway, because the light is green","Drive into the intersection and wait there","Wait before the intersection until there is room on the other side","Drive on the shoulder around the line"],"h1":"Think about what happens to cross traffic if your car is stuck in the middle.","h2":"In Florida, you must not enter an intersection unless there is room for your car on the other side, even on green, because a stuck car blocks cross traffic.","p":"Right. Do not enter unless you can get all the way through."},"es":{"q":"En Florida, su luz está en verde, pero el tráfico de adelante está detenido hasta la intersección. ¿Qué debe hacer?","o":["Entrar de todos modos, porque la luz está en verde","Entrar a la intersección y esperar ahí","Esperar antes de la intersección hasta que haya espacio del otro lado","Manejar por el paseo para pasar la fila"],"h1":"Piense qué le pasa al tráfico que cruza si su carro queda atrapado en el medio.","h2":"En Florida, usted no debe entrar a una intersección si no hay espacio para su carro del otro lado, aunque tenga verde, porque un carro atrapado bloquea el tráfico que cruza.","p":"Correcto. No entre si no puede pasar por completo."},"zh":{"q":"在 Florida，你这边是绿灯，但前面的车已经堵到路口里了。你应该怎么做？","o":["照样开进去，因为是绿灯","开进路口，在里面等","在路口前等，等到路口另一边有空位","从路肩绕过排队的车"],"h1":"想一想：如果你的车卡在路口中间，横向的车会怎样。","h2":"在 Florida，就算是绿灯，路口另一边没有空位放你的车时，你也不能开进路口，因为卡住的车会挡住横向交通。","p":"对。除非能完全开过去，否则不要进入路口。"},"vi":{"q":"Ở Florida, đèn của bạn đang xanh, nhưng xe phía trước bị kẹt dồn vào tới giao lộ. Bạn nên làm gì?","o":["Cứ chạy vào, vì đèn đang xanh","Chạy vào giao lộ và chờ ở đó","Chờ trước giao lộ tới khi phía bên kia có chỗ trống","Chạy trên lề đường để vượt qua hàng xe"],"h1":"Hãy nghĩ xem xe ở hướng cắt ngang sẽ ra sao nếu xe bạn bị kẹt ở giữa.","h2":"Ở Florida, bạn không được chạy vào giao lộ nếu phía bên kia không có chỗ cho xe bạn, kể cả khi đèn xanh, vì xe bị kẹt sẽ chắn đường xe cắt ngang.","p":"Đúng rồi. Đừng chạy vào nếu bạn không thể qua hết giao lộ."},"tl":{"q":"Sa Florida, berde ang ilaw mo, pero ang trapiko sa unahan ay umaabot na hanggang sa interseksyon. Ano ang dapat mong gawin?","o":["Pumasok pa rin, dahil berde ang ilaw","Pumasok sa interseksyon at maghintay doon","Maghintay bago ang interseksyon hanggang may puwang sa kabilang bahagi","Magmaneho sa gilid ng kalsada para lampasan ang pila"],"h1":"Isipin kung ano ang mangyayari sa trapiko sa kabilang daan kapag naipit ang sasakyan mo sa gitna.","h2":"Sa Florida, hindi ka dapat pumasok sa interseksyon maliban kung may puwang para sa sasakyan mo sa kabilang bahagi, kahit berde, dahil ang naipit na sasakyan ay humaharang sa trapiko sa kabilang daan.","p":"Tama. Huwag pumasok maliban kung kaya mong makatawid nang buo."},"ar":{"q":"في Florida، إشارتك خضراء، لكن السيارات أمامك متكدسة حتى داخل التقاطع. ماذا يجب أن تفعل؟","o":["ادخل على أي حال، لأن الإشارة خضراء","ادخل إلى التقاطع وانتظر هناك","انتظر قبل التقاطع حتى يكون هناك مكان في الجهة الأخرى","قُد على كتف الطريق حول الطابور"],"h1":"فكّر في ما يحدث للسيارات المتقاطعة إذا علقت سيارتك في الوسط.","h2":"في Florida، يجب ألا تدخل التقاطع إلا إذا كان هناك مكان لسيارتك في الجهة الأخرى، حتى عند الأخضر، لأن السيارة العالقة تغلق الطريق أمام السيارات المتقاطعة.","p":"صحيح. لا تدخل إلا إذا كنت تستطيع أن تعبر إلى الجهة الأخرى بالكامل."},"ht":{"q":"Nan Florida, limyè ou a vèt, men machin devan yo bloke jous nan kafou a. Kisa ou dwe fè?","o":["Antre kanmèm, paske limyè a vèt","Antre nan kafou a epi tann la","Tann anvan kafou a jiskaske gen plas lòt bò a","Kondui sou arebò wout la pou pase bò kote liy machin yo"],"h1":"Panse ak sa k ap rive machin sou lòt lari a si machin ou bloke nan mitan an.","h2":"Nan Florida, ou pa dwe antre nan yon kafou sof si gen plas pou machin ou lòt bò a, menm lè limyè a vèt, paske yon machin ki bloke anpeche lòt machin yo pase.","p":"Se sa. Pa antre sof si ou ka travèse nèt."},"ref":{"doc":"FL","page":51}},{"id":"signals-015","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"A pedestrian signal shows a walking person. What does it mean for people on foot?","o":["They must not start crossing","They may start crossing the street","Only bicycles may cross","Cars may turn without looking"],"h1":"The walking person is a picture of what people may do.","h2":"A walking person signal means people on foot may start crossing, so drivers who turn must yield to them.","p":"Right. The walking person means people may cross."},"es":{"q":"Una señal para peatones muestra una persona caminando. ¿Qué significa para las personas a pie?","o":["No deben empezar a cruzar","Pueden empezar a cruzar la calle","Solo las bicicletas pueden cruzar","Los carros pueden girar sin mirar"],"h1":"La persona caminando es un dibujo de lo que la gente puede hacer.","h2":"La señal de la persona caminando significa que las personas a pie pueden empezar a cruzar, así que los conductores que giran deben cederles el paso.","p":"Correcto. La persona caminando significa que pueden cruzar."},"zh":{"q":"行人信号灯显示一个走路的人。这对行人是什么意思？","o":["他们不能开始过马路","他们可以开始过马路","只有自行车可以过","汽车可以不看就转弯"],"h1":"走路的人这个图，就是行人可以做的事。","h2":"走路的人的信号表示行人可以开始过马路，所以转弯的司机必须让他们先走。","p":"对。走路的人表示行人可以过马路。"},"vi":{"q":"Đèn cho người đi bộ hiện hình một người đang đi. Điều đó có nghĩa là gì với người đi bộ?","o":["Họ không được bắt đầu băng qua","Họ được bắt đầu băng qua đường","Chỉ xe đạp được băng qua","Xe được rẽ mà không cần nhìn"],"h1":"Hình người đang đi cho thấy điều người đi bộ được làm.","h2":"Đèn có hình người đang đi nghĩa là người đi bộ được bắt đầu băng qua, nên tài xế đang rẽ phải nhường đường cho họ.","p":"Đúng rồi. Hình người đang đi nghĩa là người đi bộ được băng qua."},"tl":{"q":"Ang ilaw para sa tumatawid ay nagpapakita ng taong naglalakad. Ano ang ibig sabihin nito para sa mga naglalakad?","o":["Hindi sila dapat magsimulang tumawid","Puwede na silang magsimulang tumawid sa kalye","Mga bisikleta lang ang puwedeng tumawid","Puwedeng lumiko ang mga sasakyan nang hindi tumitingin"],"h1":"Ang taong naglalakad ay larawan ng kung ano ang puwedeng gawin ng mga tao.","h2":"Ang ilaw na may taong naglalakad ay nangangahulugang puwede nang magsimulang tumawid ang mga naglalakad, kaya ang mga driver na lumiliko ay dapat magbigay-daan sa kanila.","p":"Tama. Ang taong naglalakad ay nangangahulugang puwedeng tumawid ang mga tao."},"ar":{"q":"إشارة المشاة تُظهر شخصًا يمشي. ماذا تعني للمشاة؟","o":["يجب ألا يبدؤوا العبور","يمكنهم أن يبدؤوا عبور الشارع","الدراجات فقط يمكنها العبور","السيارات يمكنها أن تنعطف بدون أن تنظر"],"h1":"الشخص الذي يمشي صورة لما يُسمح للناس أن يفعلوه.","h2":"إشارة الشخص الذي يمشي تعني أن المشاة يمكنهم أن يبدؤوا العبور، لذلك السائقون الذين ينعطفون يجب أن يعطوهم الأولوية.","p":"صحيح. الشخص الذي يمشي يعني أن الناس يمكنهم العبور."},"ht":{"q":"Yon siyal pou pyeton montre yon moun k ap mache. Kisa li vle di pou moun ki a pye?","o":["Yo pa dwe kòmanse travèse","Yo ka kòmanse travèse lari a","Se sèlman bisiklèt ki ka travèse","Machin yo ka vire san yo pa gade"],"h1":"Moun k ap mache a se yon foto sa moun yo ka fè.","h2":"Yon siyal ak yon moun k ap mache vle di moun ki a pye ka kòmanse travèse, kidonk chofè k ap vire dwe kite yo pase.","p":"Se sa. Moun k ap mache a vle di moun yo ka travèse."},"ref":{"doc":"FL","page":55}},{"id":"signals-016","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"A pedestrian signal shows a flashing raised hand. What does it mean?","o":["Anyone may start crossing now","People must run back to the curb","Drivers must stop for the whole cycle","Do not start crossing, but people already crossing may finish"],"h1":"Think about the difference between starting to cross and finishing.","h2":"A flashing hand means people should not start crossing, but anyone already in the street may finish crossing.","p":"Right. A flashing hand means do not start, but finish if you already started."},"es":{"q":"Una señal para peatones muestra una mano levantada intermitente. ¿Qué significa?","o":["Cualquiera puede empezar a cruzar ahora","Las personas deben correr de vuelta a la acera","Los conductores deben parar todo el ciclo","No empiece a cruzar, pero quien ya está cruzando puede terminar"],"h1":"Piense en la diferencia entre empezar a cruzar y terminar de cruzar.","h2":"Una mano intermitente significa que las personas no deben empezar a cruzar, pero quien ya está en la calle puede terminar de cruzar.","p":"Correcto. Mano intermitente significa no empiece, pero termine si ya empezó."},"zh":{"q":"行人信号灯显示一只闪烁的举起的手。它是什么意思？","o":["任何人现在都可以开始过马路","行人必须跑回路边","司机在整个周期都必须停车","不要开始过马路，但已经在过的人可以走完"],"h1":"想一想 “开始过马路” 和 “走完” 有什么不同。","h2":"闪烁的手表示行人不应该开始过马路，但已经在马路上的人可以走完。","p":"对。闪烁的手表示不要开始，已经开始的人可以走完。"},"vi":{"q":"Đèn cho người đi bộ hiện hình bàn tay giơ lên đang nhấp nháy. Điều đó có nghĩa là gì?","o":["Bây giờ ai cũng được bắt đầu băng qua","Người đi bộ phải chạy về lại lề đường","Tài xế phải dừng suốt cả chu kỳ đèn","Không được bắt đầu băng qua, nhưng ai đang băng qua thì được đi tiếp cho hết"],"h1":"Hãy nghĩ đến sự khác nhau giữa bắt đầu băng qua và đi cho hết.","h2":"Bàn tay nhấp nháy nghĩa là không ai nên bắt đầu băng qua, nhưng người đang ở giữa đường thì được đi tiếp cho hết.","p":"Đúng rồi. Bàn tay nhấp nháy nghĩa là đừng bắt đầu, nhưng đi cho hết nếu đã bắt đầu."},"tl":{"q":"Ang ilaw para sa tumatawid ay nagpapakita ng kumikislap na nakataas na kamay. Ano ang ibig sabihin nito?","o":["Puwede nang magsimulang tumawid ang kahit sino","Dapat tumakbo pabalik sa bangketa ang mga tao","Dapat huminto ang mga driver sa buong ikot ng ilaw","Huwag magsimulang tumawid, pero puwedeng tapusin ng mga tumatawid na"],"h1":"Isipin ang pagkakaiba ng pagsisimulang tumawid at pagtatapos ng pagtawid.","h2":"Ang kumikislap na kamay ay nangangahulugang hindi dapat magsimulang tumawid ang mga tao, pero ang sinumang nasa kalye na ay puwedeng tapusin ang pagtawid.","p":"Tama. Ang kumikislap na kamay ay nangangahulugang huwag magsimula, pero tapusin kung nagsimula ka na."},"ar":{"q":"إشارة المشاة تُظهر يدًا مرفوعة تومض. ماذا تعني؟","o":["أي شخص يمكنه أن يبدأ العبور الآن","يجب أن يركض الناس عائدين إلى الرصيف","يجب أن يتوقف السائقون طوال الدورة كلها","لا تبدأ العبور، لكن من يعبر بالفعل يمكنه أن يكمل"],"h1":"فكّر في الفرق بين أن تبدأ العبور وأن تكمله.","h2":"اليد الوامضة تعني أن الناس يجب ألا يبدؤوا العبور، لكن أي شخص موجود في الشارع بالفعل يمكنه أن يكمل العبور.","p":"صحيح. اليد الوامضة تعني: لا تبدأ، لكن أكمل إذا كنت قد بدأت."},"ht":{"q":"Yon siyal pou pyeton montre yon men leve k ap kliyote. Kisa li vle di?","o":["Nenpòt moun ka kòmanse travèse kounye a","Moun yo dwe kouri tounen sou twotwa a","Chofè yo dwe kanpe pandan tout sik la","Pa kòmanse travèse, men moun ki deja ap travèse ka fini"],"h1":"Panse ak diferans ant kòmanse travèse ak fini travèse.","h2":"Yon men k ap kliyote vle di moun pa dwe kòmanse travèse, men nenpòt moun ki deja nan lari a ka fini travèse.","p":"Se sa. Yon men k ap kliyote vle di pa kòmanse, men fini si ou te deja kòmanse."},"ref":{"doc":"FL","page":55}},{"id":"signals-017","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"A pedestrian signal shows a number counting down next to a hand. What does the number show?","o":["How many seconds are left to finish crossing","How many people may cross","The speed limit for the street","How many cars may turn"],"h1":"The number gets smaller every second.","h2":"The countdown number shows how many seconds are left for people to finish crossing before the signal changes.","p":"Right. The countdown shows the seconds left to cross."},"es":{"q":"Una señal para peatones muestra un número que baja al lado de una mano. ¿Qué indica el número?","o":["Cuántos segundos quedan para terminar de cruzar","Cuántas personas pueden cruzar","El límite de velocidad de la calle","Cuántos carros pueden girar"],"h1":"El número se hace más pequeño cada segundo.","h2":"El número de cuenta regresiva muestra cuántos segundos les quedan a las personas para terminar de cruzar antes de que cambie la señal.","p":"Correcto. La cuenta regresiva muestra los segundos que quedan para cruzar."},"zh":{"q":"行人信号灯在手的旁边显示一个倒数的数字。这个数字表示什么？","o":["还剩多少秒可以走完马路","可以有多少人过马路","这条街的限速","可以有多少辆车转弯"],"h1":"这个数字每秒都在变小。","h2":"倒数数字表示信号变化前，行人还剩多少秒可以走完马路。","p":"对。倒数数字表示过马路还剩几秒。"},"vi":{"q":"Đèn cho người đi bộ hiện một con số đếm ngược bên cạnh bàn tay. Con số đó cho biết gì?","o":["Còn bao nhiêu giây để đi qua hết","Bao nhiêu người được băng qua","Giới hạn tốc độ của con đường","Bao nhiêu xe được rẽ"],"h1":"Con số nhỏ đi mỗi giây.","h2":"Con số đếm ngược cho biết người đi bộ còn bao nhiêu giây để đi qua hết trước khi đèn đổi.","p":"Đúng rồi. Con số đếm ngược cho biết số giây còn lại để băng qua."},"tl":{"q":"Ang ilaw para sa tumatawid ay nagpapakita ng numerong nagbibilang pababa sa tabi ng kamay. Ano ang ipinapakita ng numero?","o":["Ilang segundo na lang ang natitira para matapos ang pagtawid","Ilang tao ang puwedeng tumawid","Ang speed limit ng kalye","Ilang sasakyan ang puwedeng lumiko"],"h1":"Lumiliit ang numero bawat segundo.","h2":"Ang numerong nagbibilang pababa ay nagpapakita kung ilang segundo na lang ang natitira para matapos tumawid ang mga tao bago magbago ang ilaw.","p":"Tama. Ipinapakita ng countdown ang natitirang segundo para tumawid."},"ar":{"q":"إشارة المشاة تُظهر رقمًا يعدّ تنازليًا بجانب يد. ماذا يُظهر الرقم؟","o":["كم ثانية بقيت لإكمال العبور","كم شخصًا يمكنه العبور","حد السرعة في الشارع","كم سيارة يمكنها أن تنعطف"],"h1":"الرقم يصغر كل ثانية.","h2":"رقم العد التنازلي يُظهر كم ثانية بقيت للناس لكي يكملوا العبور قبل أن تتغير الإشارة.","p":"صحيح. العد التنازلي يُظهر الثواني الباقية للعبور."},"ht":{"q":"Yon siyal pou pyeton montre yon nimewo k ap desann bò kote yon men. Kisa nimewo a montre?","o":["Konbyen segonn ki rete pou fini travèse","Konbyen moun ki ka travèse","Limit vitès nan lari a","Konbyen machin ki ka vire"],"h1":"Nimewo a vin pi piti chak segonn.","h2":"Nimewo k ap desann nan montre konbyen segonn ki rete pou moun yo fini travèse anvan siyal la chanje.","p":"Se sa. Nimewo k ap desann nan montre segonn ki rete pou travèse."},"ref":{"doc":"FL","page":55}},{"id":"signals-018","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"What do yellow center lines on a road tell you?","o":["All lanes go the same direction","The road is a school zone","Traffic on each side of the line moves in opposite directions","Parking is allowed on the line"],"h1":"Think about where yellow lines usually are: between the two sides of the road.","h2":"Yellow center lines separate traffic moving in opposite directions, so cars on the other side come toward you.","p":"Right. Yellow lines separate traffic going opposite ways."},"es":{"q":"¿Qué le indican las líneas amarillas en el centro de la calle?","o":["Todos los carriles van en la misma dirección","La calle es una zona escolar","El tráfico de cada lado de la línea va en direcciones opuestas","Se permite estacionar sobre la línea"],"h1":"Piense dónde suelen estar las líneas amarillas: entre los dos lados de la calle.","h2":"Las líneas amarillas del centro separan el tráfico que va en direcciones opuestas, así que los carros del otro lado vienen hacia usted.","p":"Correcto. Las líneas amarillas separan el tráfico que va en sentidos opuestos."},"zh":{"q":"道路上的黄色中心线告诉你什么？","o":["所有车道都往同一个方向","这条路是学校区","线两边的车往相反方向开","可以在线上停车"],"h1":"想一想黄线通常在哪里：在道路两边之间。","h2":"黄色中心线把相反方向的车流分开，所以线另一边的车是朝你开过来的。","p":"对。黄线把相反方向的车分开。"},"vi":{"q":"Vạch kẻ màu vàng ở giữa đường cho bạn biết điều gì?","o":["Tất cả các làn đều đi cùng một chiều","Con đường là khu vực trường học","Xe ở hai bên vạch chạy ngược chiều nhau","Được đỗ xe trên vạch"],"h1":"Hãy nghĩ xem vạch vàng thường nằm ở đâu: giữa hai bên của con đường.","h2":"Vạch vàng ở giữa đường tách xe chạy ngược chiều nhau, nên xe ở bên kia vạch đang chạy về phía bạn.","p":"Đúng rồi. Vạch vàng tách xe chạy ngược chiều nhau."},"tl":{"q":"Ano ang sinasabi sa iyo ng mga dilaw na linya sa gitna ng kalsada?","o":["Lahat ng linya ay papunta sa iisang direksyon","School zone ang kalsada","Ang trapiko sa magkabilang bahagi ng linya ay papunta sa magkasalungat na direksyon","Puwedeng pumarada sa linya"],"h1":"Isipin kung saan karaniwang nakalagay ang mga dilaw na linya: sa pagitan ng dalawang bahagi ng kalsada.","h2":"Ang mga dilaw na linya sa gitna ay naghihiwalay sa trapikong papunta sa magkasalungat na direksyon, kaya ang mga sasakyan sa kabilang bahagi ay papunta sa iyo.","p":"Tama. Ang dilaw na linya ay naghihiwalay sa trapikong magkasalungat ang direksyon."},"ar":{"q":"ماذا تخبرك الخطوط الصفراء في وسط الطريق؟","o":["كل المسارات تسير في نفس الاتجاه","الطريق منطقة مدرسة","السيارات على كل جانب من الخط تسير في اتجاهين متعاكسين","الوقوف مسموح على الخط"],"h1":"فكّر أين توجد الخطوط الصفراء عادةً: بين جانبي الطريق.","h2":"الخطوط الصفراء في الوسط تفصل بين السيارات التي تسير في اتجاهين متعاكسين، لذلك السيارات على الجانب الآخر تأتي نحوك.","p":"صحيح. الخطوط الصفراء تفصل بين السيارات التي تسير في اتجاهين متعاكسين."},"ht":{"q":"Kisa liy jòn nan mitan yon wout di ou?","o":["Tout koulwa yo ale nan menm direksyon","Wout la se yon zòn lekòl","Machin sou chak bò liy la ale nan direksyon opoze","Ou ka pake sou liy la"],"h1":"Panse ki kote liy jòn yo konn ye: ant de bò wout la.","h2":"Liy jòn nan mitan wout la separe machin k ap ale nan direksyon opoze, kidonk machin sou lòt bò a ap vin sou ou.","p":"Se sa. Liy jòn yo separe machin k ap ale nan direksyon opoze."},"ref":{"doc":"FL","page":43}},{"id":"signals-019","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"What do white lines between lanes tell you?","o":["The lanes carry traffic going opposite directions","The lanes carry traffic going the same direction","The lane is only for buses","You are near a railroad crossing"],"h1":"Compare white lines with yellow lines.","h2":"White lines between lanes show that the traffic in those lanes moves in the same direction.","p":"Right. White lines separate lanes going the same way."},"es":{"q":"¿Qué le indican las líneas blancas entre los carriles?","o":["Los carriles llevan tráfico en direcciones opuestas","Los carriles llevan tráfico en la misma dirección","El carril es solo para autobuses","Usted está cerca de un cruce de tren"],"h1":"Compare las líneas blancas con las amarillas.","h2":"Las líneas blancas entre carriles muestran que el tráfico de esos carriles va en la misma dirección.","p":"Correcto. Las líneas blancas separan carriles que van en el mismo sentido."},"zh":{"q":"车道之间的白线告诉你什么？","o":["这些车道的车往相反方向开","这些车道的车往同一个方向开","这条车道只给公交车","你在铁路道口附近"],"h1":"把白线和黄线比一比。","h2":"车道之间的白线表示这些车道的车往同一个方向开。","p":"对。白线分开同方向的车道。"},"vi":{"q":"Vạch trắng giữa các làn cho bạn biết điều gì?","o":["Các làn có xe chạy ngược chiều nhau","Các làn có xe chạy cùng một chiều","Làn này chỉ dành cho xe buýt","Bạn đang ở gần chỗ băng qua đường sắt"],"h1":"Hãy so sánh vạch trắng với vạch vàng.","h2":"Vạch trắng giữa các làn cho thấy xe trong các làn đó chạy cùng một chiều.","p":"Đúng rồi. Vạch trắng tách các làn đi cùng một chiều."},"tl":{"q":"Ano ang sinasabi sa iyo ng mga puting linya sa pagitan ng mga lane?","o":["Ang mga lane ay may trapikong papunta sa magkasalungat na direksyon","Ang mga lane ay may trapikong papunta sa iisang direksyon","Para sa bus lang ang lane","Malapit ka sa tawiran ng tren"],"h1":"Ihambing ang mga puting linya sa mga dilaw na linya.","h2":"Ang mga puting linya sa pagitan ng mga lane ay nagpapakita na ang trapiko sa mga lane na iyon ay papunta sa iisang direksyon.","p":"Tama. Ang puting linya ay naghihiwalay sa mga lane na papunta sa iisang direksyon."},"ar":{"q":"ماذا تخبرك الخطوط البيضاء بين المسارات؟","o":["المسارات فيها سيارات تسير في اتجاهين متعاكسين","المسارات فيها سيارات تسير في نفس الاتجاه","المسار للحافلات فقط","أنت قريب من تقاطع سكة حديد"],"h1":"قارن الخطوط البيضاء بالخطوط الصفراء.","h2":"الخطوط البيضاء بين المسارات تُظهر أن السيارات في هذه المسارات تسير في نفس الاتجاه.","p":"صحيح. الخطوط البيضاء تفصل بين مسارات تسير في نفس الاتجاه."},"ht":{"q":"Kisa liy blan ant koulwa yo di ou?","o":["Machin nan koulwa yo ale nan direksyon opoze","Machin nan koulwa yo ale nan menm direksyon","Koulwa a se pou bis sèlman","Ou toupre yon kote tren travèse"],"h1":"Konpare liy blan yo ak liy jòn yo.","h2":"Liy blan ant koulwa yo montre machin nan koulwa sa yo ale nan menm direksyon.","p":"Se sa. Liy blan yo separe koulwa k ap ale nan menm direksyon."},"ref":{"doc":"FL","page":43}},{"id":"signals-020","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"The yellow center line on your side is broken (dashed). What does that allow?","o":["You may never pass","You may park on the line","You may drive on the line for a long time","You may pass when it is safe"],"h1":"A broken line has gaps. Think about what gaps let you do.","h2":"A broken yellow line on your side means you may pass another car, but only when the way ahead is clear and safe.","p":"Right. A broken yellow line on your side means you may pass when safe."},"es":{"q":"La línea amarilla del centro de su lado es discontinua (con espacios). ¿Qué le permite?","o":["No puede rebasar nunca","Puede estacionar sobre la línea","Puede manejar sobre la línea por mucho rato","Puede rebasar cuando sea seguro"],"h1":"Una línea discontinua tiene espacios. Piense qué le permiten esos espacios.","h2":"Una línea amarilla discontinua de su lado significa que usted puede rebasar a otro carro, pero solo cuando el camino adelante esté libre y sea seguro.","p":"Correcto. Línea amarilla discontinua de su lado significa que puede rebasar si es seguro."},"zh":{"q":"你这一边的黄色中心线是虚线（断开的）。它允许你做什么？","o":["你永远不能超车","你可以在线上停车","你可以长时间压线开","安全时你可以超车"],"h1":"虚线有空隙。想一想空隙让你做什么。","h2":"你这一边的黄色虚线表示你可以超车，但只能在前方路上没车、安全的时候。","p":"对。你这边是黄色虚线，表示安全时可以超车。"},"vi":{"q":"Vạch vàng ở giữa đường, phía bên bạn, là vạch đứt (nét đứt). Vạch này cho phép điều gì?","o":["Bạn không bao giờ được vượt","Bạn được đỗ xe trên vạch","Bạn được chạy trên vạch trong thời gian dài","Bạn được vượt khi an toàn"],"h1":"Vạch đứt có những khoảng trống. Hãy nghĩ xem khoảng trống cho bạn làm gì.","h2":"Vạch vàng đứt ở phía bên bạn nghĩa là bạn được vượt xe khác, nhưng chỉ khi đường phía trước trống và an toàn.","p":"Đúng rồi. Vạch vàng đứt ở phía bạn nghĩa là được vượt khi an toàn."},"tl":{"q":"Putol-putol (dashed) ang dilaw na linya sa gitna sa bahagi mo. Ano ang pinapayagan nito?","o":["Hindi ka kailanman puwedeng mag-overtake","Puwede kang pumarada sa linya","Puwede kang magmaneho sa ibabaw ng linya nang matagal","Puwede kang mag-overtake kapag ligtas"],"h1":"May mga puwang ang putol-putol na linya. Isipin kung ano ang ipinapagawa sa iyo ng mga puwang.","h2":"Ang putol-putol na dilaw na linya sa bahagi mo ay nangangahulugang puwede kang lumampas sa ibang sasakyan, pero kapag maluwag at ligtas lang ang daan sa unahan.","p":"Tama. Ang putol-putol na dilaw na linya sa bahagi mo ay nangangahulugang puwede kang mag-overtake kapag ligtas."},"ar":{"q":"خط الوسط الأصفر على جانبك متقطع. بماذا يسمح ذلك؟","o":["لا يمكنك أن تتجاوز أبدًا","يمكنك أن تقف على الخط","يمكنك أن تقود على الخط وقتًا طويلًا","يمكنك أن تتجاوز عندما يكون ذلك آمنًا"],"h1":"الخط المتقطع فيه فراغات. فكّر في ما تسمح لك به الفراغات.","h2":"الخط الأصفر المتقطع على جانبك يعني أنه يمكنك أن تتجاوز سيارة أخرى، لكن فقط عندما يكون الطريق أمامك خاليًا وآمنًا.","p":"صحيح. الخط الأصفر المتقطع على جانبك يعني أنه يمكنك أن تتجاوز عندما يكون ذلك آمنًا."},"ht":{"q":"Liy jòn nan mitan an sou bò ou a koupe koupe (an tirè). Kisa sa pèmèt?","o":["Ou pa janm ka double","Ou ka pake sou liy la","Ou ka kondui sou liy la pou lontan","Ou ka double lè sa an sekirite"],"h1":"Yon liy koupe gen espas vid. Panse ak sa espas sa yo kite ou fè.","h2":"Yon liy jòn koupe sou bò ou a vle di ou ka double yon lòt machin, men sèlman lè wout la devan lib epi an sekirite.","p":"Se sa. Yon liy jòn koupe sou bò ou vle di ou ka double lè sa an sekirite."},"ref":{"doc":"FL","page":44}},{"id":"signals-021","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"You see a solid yellow line on your side and a broken yellow line on the other side. Who may pass?","o":["Only drivers on the side with the broken line","Only drivers on your side","Drivers on both sides","No one, at any time"],"h1":"Look at the line closest to your car. It is the one that counts for you.","h2":"The line closest to you is the one you follow, so a solid yellow line on your side means you may not pass, while drivers next to the broken line may pass when safe.","p":"Right. A solid line on your side means you may not pass."},"es":{"q":"Usted ve una línea amarilla continua de su lado y una línea amarilla discontinua del otro lado. ¿Quién puede rebasar?","o":["Solo los conductores del lado de la línea discontinua","Solo los conductores de su lado","Los conductores de los dos lados","Nadie, en ningún momento"],"h1":"Mire la línea más cerca de su carro. Esa es la que cuenta para usted.","h2":"Usted sigue la línea más cerca de su carro, así que una línea amarilla continua de su lado significa que no puede rebasar, mientras que los conductores junto a la línea discontinua pueden rebasar si es seguro.","p":"Correcto. Una línea continua de su lado significa que no puede rebasar."},"zh":{"q":"你这一边是黄色实线，另一边是黄色虚线。谁可以超车？","o":["只有虚线那一边的司机","只有你这一边的司机","两边的司机都可以","任何时候谁都不行"],"h1":"看离你的车最近的那条线。那条线才是给你的。","h2":"你要遵守离你最近的那条线，所以你这一边是黄色实线，表示你不能超车，而靠近虚线一边的司机在安全时可以超车。","p":"对。你这边是实线，表示你不能超车。"},"vi":{"q":"Bạn thấy vạch vàng liền ở phía bên bạn và vạch vàng đứt ở phía bên kia. Ai được vượt?","o":["Chỉ tài xế ở phía có vạch đứt","Chỉ tài xế ở phía bên bạn","Tài xế ở cả hai phía","Không ai cả, vào bất cứ lúc nào"],"h1":"Hãy nhìn vạch gần xe bạn nhất. Đó là vạch áp dụng cho bạn.","h2":"Bạn làm theo vạch gần bạn nhất, nên vạch vàng liền ở phía bạn nghĩa là bạn không được vượt, còn tài xế ở phía vạch đứt được vượt khi an toàn.","p":"Đúng rồi. Vạch liền ở phía bạn nghĩa là bạn không được vượt."},"tl":{"q":"May tuloy-tuloy na dilaw na linya sa bahagi mo at putol-putol na dilaw na linya sa kabilang bahagi. Sino ang puwedeng mag-overtake?","o":["Ang mga driver lang sa bahaging may putol-putol na linya","Ang mga driver lang sa bahagi mo","Ang mga driver sa magkabilang bahagi","Walang sinuman, kailanman"],"h1":"Tingnan ang linyang pinakamalapit sa sasakyan mo. Iyon ang linyang para sa iyo.","h2":"Ang linyang pinakamalapit sa iyo ang sinusunod mo, kaya ang tuloy-tuloy na dilaw na linya sa bahagi mo ay nangangahulugang hindi ka puwedeng mag-overtake, habang ang mga driver na katabi ng putol-putol na linya ay puwedeng mag-overtake kapag ligtas.","p":"Tama. Ang tuloy-tuloy na linya sa bahagi mo ay nangangahulugang hindi ka puwedeng mag-overtake."},"ar":{"q":"ترى خطًا أصفر متصلًا على جانبك وخطًا أصفر متقطعًا على الجانب الآخر. من يمكنه أن يتجاوز؟","o":["فقط السائقون على الجانب الذي فيه الخط المتقطع","فقط السائقون على جانبك","السائقون على الجانبين","لا أحد، في أي وقت"],"h1":"انظر إلى الخط الأقرب إلى سيارتك. هو الخط المهم بالنسبة لك.","h2":"الخط الأقرب إليك هو الذي تتبعه، لذلك الخط الأصفر المتصل على جانبك يعني أنه لا يمكنك أن تتجاوز، أما السائقون بجانب الخط المتقطع فيمكنهم أن يتجاوزوا عندما يكون ذلك آمنًا.","p":"صحيح. الخط المتصل على جانبك يعني أنه لا يمكنك أن تتجاوز."},"ht":{"q":"Ou wè yon liy jòn plen sou bò ou ak yon liy jòn koupe sou lòt bò a. Kiyès ki ka double?","o":["Sèlman chofè ki sou bò liy koupe a","Sèlman chofè ki sou bò ou a","Chofè sou toude bò yo","Pèsonn, nan okenn moman"],"h1":"Gade liy ki pi pre machin ou a. Se li ki konte pou ou.","h2":"Liy ki pi pre ou a se li ou swiv, kidonk yon liy jòn plen sou bò ou vle di ou pa ka double, men chofè ki bò liy koupe a ka double lè sa an sekirite.","p":"Se sa. Yon liy plen sou bò ou vle di ou pa ka double."},"ref":{"doc":"FL","page":44}},{"id":"signals-022","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"What do two solid yellow lines in the center of the road mean?","o":["Passing is allowed in both directions","Only trucks may pass","No one may cross them to pass, in either direction","The road ends ahead"],"h1":"Two solid lines are stronger than one. Think about both sides.","h2":"Two solid yellow lines mean drivers on both sides may not cross them to pass another car.","p":"Right. Double solid yellow means no passing for anyone."},"es":{"q":"¿Qué significan dos líneas amarillas continuas en el centro de la calle?","o":["Se permite rebasar en las dos direcciones","Solo los camiones pueden rebasar","Nadie puede cruzarlas para rebasar, en ninguna dirección","La calle se termina más adelante"],"h1":"Dos líneas continuas son más fuertes que una. Piense en los dos lados.","h2":"Dos líneas amarillas continuas significan que los conductores de los dos lados no pueden cruzarlas para rebasar a otro carro.","p":"Correcto. Doble línea amarilla continua significa que nadie puede rebasar."},"zh":{"q":"道路中间的两条黄色实线是什么意思？","o":["两个方向都可以超车","只有卡车可以超车","两个方向的车都不能越线超车","前方道路结束"],"h1":"两条实线比一条更严格。想一想两边。","h2":"两条黄色实线表示两边的司机都不能越过它们去超车。","p":"对。双黄实线表示任何人都不能超车。"},"vi":{"q":"Hai vạch vàng liền ở giữa đường có nghĩa là gì?","o":["Được vượt ở cả hai chiều","Chỉ xe tải được vượt","Không ai được lấn qua để vượt, ở cả hai chiều","Phía trước đường hết"],"h1":"Hai vạch liền mạnh hơn một vạch. Hãy nghĩ đến cả hai phía.","h2":"Hai vạch vàng liền nghĩa là tài xế ở cả hai phía đều không được lấn qua chúng để vượt xe khác.","p":"Đúng rồi. Hai vạch vàng liền nghĩa là không ai được vượt."},"tl":{"q":"Ano ang ibig sabihin ng dalawang tuloy-tuloy na dilaw na linya sa gitna ng kalsada?","o":["Puwedeng mag-overtake sa magkabilang direksyon","Mga trak lang ang puwedeng mag-overtake","Walang puwedeng tumawid sa mga ito para mag-overtake, sa alinmang direksyon","Matatapos ang kalsada sa unahan"],"h1":"Mas malakas ang dalawang tuloy-tuloy na linya kaysa sa isa. Isipin ang magkabilang bahagi.","h2":"Ang dalawang tuloy-tuloy na dilaw na linya ay nangangahulugang hindi puwedeng tumawid sa mga ito ang mga driver sa magkabilang bahagi para lumampas sa ibang sasakyan.","p":"Tama. Ang dobleng tuloy-tuloy na dilaw ay nangangahulugang bawal mag-overtake ang lahat."},"ar":{"q":"ماذا يعني خطان أصفران متصلان في وسط الطريق؟","o":["التجاوز مسموح في الاتجاهين","الشاحنات فقط يمكنها أن تتجاوز","لا أحد يمكنه أن يعبرهما ليتجاوز، في أي اتجاه","الطريق ينتهي في الأمام"],"h1":"خطان متصلان أقوى من خط واحد. فكّر في الجانبين.","h2":"الخطان الأصفران المتصلان يعنيان أن السائقين على الجانبين لا يمكنهم أن يعبروهما ليتجاوزوا سيارة أخرى.","p":"صحيح. الخط الأصفر المزدوج المتصل يعني ممنوع التجاوز على الجميع."},"ht":{"q":"Kisa de liy jòn plen nan mitan wout la vle di?","o":["Ou ka double nan toude direksyon","Se sèlman kamyon ki ka double","Pèsonn pa ka travèse yo pou double, nan okenn direksyon","Wout la fini pi devan"],"h1":"De liy plen pi fò pase youn. Panse ak toude bò yo.","h2":"De liy jòn plen vle di chofè sou toude bò yo pa ka travèse yo pou double yon lòt machin.","p":"Se sa. De liy jòn plen vle di pèsonn pa ka double."},"ref":{"doc":"FL","page":44}},{"id":"signals-023","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"What does a solid white line between two lanes going the same way mean?","o":["You must change lanes now","Stay in your lane; changing lanes is discouraged there","Traffic in the next lane comes toward you","You may park along the line"],"h1":"A solid line asks you to stay where you are.","h2":"A solid white line between lanes means you should stay in your lane and change lanes only if you really must and it is safe.","p":"Right. A solid white line means stay in your lane."},"es":{"q":"¿Qué significa una línea blanca continua entre dos carriles que van en el mismo sentido?","o":["Usted debe cambiar de carril ahora","Quédese en su carril; no se recomienda cambiar de carril ahí","El tráfico del otro carril viene hacia usted","Puede estacionar junto a la línea"],"h1":"Una línea continua le pide quedarse donde está.","h2":"Una línea blanca continua entre carriles significa que usted debe quedarse en su carril y cambiar solo si de verdad lo necesita y es seguro.","p":"Correcto. Una línea blanca continua significa quédese en su carril."},"zh":{"q":"同方向两条车道之间的白色实线是什么意思？","o":["你现在必须换车道","待在你的车道里，这里最好不要换车道","旁边车道的车朝你开过来","你可以沿着这条线停车"],"h1":"实线是要你待在原来的地方。","h2":"车道之间的白色实线表示你应该待在自己的车道里，只有真的必须换道而且安全时才换。","p":"对。白色实线表示待在你的车道里。"},"vi":{"q":"Vạch trắng liền giữa hai làn đi cùng một chiều có nghĩa là gì?","o":["Bạn phải đổi làn ngay bây giờ","Hãy ở trong làn của bạn; không nên đổi làn ở đó","Xe ở làn bên cạnh chạy ngược về phía bạn","Bạn được đỗ xe dọc theo vạch"],"h1":"Vạch liền muốn bạn ở yên chỗ của mình.","h2":"Vạch trắng liền giữa các làn nghĩa là bạn nên ở trong làn của mình, và chỉ đổi làn khi thật sự cần và an toàn.","p":"Đúng rồi. Vạch trắng liền nghĩa là ở trong làn của bạn."},"tl":{"q":"Ano ang ibig sabihin ng tuloy-tuloy na puting linya sa pagitan ng dalawang lane na papunta sa iisang direksyon?","o":["Dapat kang lumipat ng lane ngayon","Manatili sa lane mo; hindi hinihikayat ang paglipat ng lane doon","Ang trapiko sa katabing lane ay papunta sa iyo","Puwede kang pumarada sa tabi ng linya"],"h1":"Hinihiling ng tuloy-tuloy na linya na manatili ka kung nasaan ka.","h2":"Ang tuloy-tuloy na puting linya sa pagitan ng mga lane ay nangangahulugang dapat kang manatili sa lane mo at lumipat lang ng lane kung talagang kailangan at ligtas.","p":"Tama. Ang tuloy-tuloy na puting linya ay nangangahulugang manatili sa lane mo."},"ar":{"q":"ماذا يعني خط أبيض متصل بين مسارين يسيران في نفس الاتجاه؟","o":["يجب أن تغيّر المسار الآن","ابقَ في مسارك؛ تغيير المسار غير مستحب هناك","السيارات في المسار المجاور تأتي نحوك","يمكنك أن تقف على طول الخط"],"h1":"الخط المتصل يطلب منك أن تبقى حيث أنت.","h2":"الخط الأبيض المتصل بين المسارات يعني أنه يجب أن تبقى في مسارك، وتغيّر المسار فقط إذا كنت مضطرًا حقًا وكان ذلك آمنًا.","p":"صحيح. الخط الأبيض المتصل يعني: ابقَ في مسارك."},"ht":{"q":"Kisa yon liy blan plen ant de koulwa k ap ale nan menm direksyon vle di?","o":["Ou dwe chanje koulwa kounye a","Rete nan koulwa ou; yo pa konseye chanje koulwa la a","Machin nan lòt koulwa a ap vin sou ou","Ou ka pake sou kote liy la"],"h1":"Yon liy plen mande ou rete kote ou ye a.","h2":"Yon liy blan plen ant koulwa yo vle di ou dwe rete nan koulwa ou epi chanje koulwa sèlman si ou vrèman oblije epi si sa an sekirite.","p":"Se sa. Yon liy blan plen vle di rete nan koulwa ou."},"ref":{"doc":"FL","page":43}},{"id":"signals-024","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"A center lane has a solid yellow line and a broken yellow line on each side. What is this lane for?","o":["Passing slow cars","Driving long distances","Parking and loading","Left turns by drivers from both directions"],"h1":"Cars from both directions can use this lane, but only for one kind of move.","h2":"A center lane marked with solid and broken yellow lines on both sides is a two-way left-turn lane, so drivers from either direction use it only to turn left.","p":"Right. That center lane is only for left turns from both directions."},"es":{"q":"Un carril del centro tiene una línea amarilla continua y una línea amarilla discontinua en cada lado. ¿Para qué es este carril?","o":["Para rebasar a carros lentos","Para manejar distancias largas","Para estacionar y cargar","Para girar a la izquierda, para conductores de las dos direcciones"],"h1":"Carros de las dos direcciones pueden usar este carril, pero solo para un tipo de maniobra.","h2":"Un carril del centro con líneas amarillas continuas y discontinuas en los dos lados es un carril de giro a la izquierda en ambos sentidos, así que los conductores de cualquier dirección lo usan solo para girar a la izquierda.","p":"Correcto. Ese carril del centro es solo para girar a la izquierda, desde las dos direcciones."},"zh":{"q":"一条中间车道的两边各有一条黄色实线和一条黄色虚线。这条车道是做什么用的？","o":["超过慢车","开长途","停车和装卸货","两个方向的司机左转用"],"h1":"两个方向的车都能用这条车道，但只能做一种动作。","h2":"两边都画着黄色实线和黄色虚线的中间车道是双向左转车道，所以两个方向的司机都只能用它来左转。","p":"对。这条中间车道只给两个方向的车左转用。"},"vi":{"q":"Một làn ở giữa đường có vạch vàng liền và vạch vàng đứt ở mỗi bên. Làn này dùng để làm gì?","o":["Vượt xe chạy chậm","Chạy đường dài","Đỗ xe và bốc dỡ hàng","Rẽ trái cho tài xế từ cả hai chiều"],"h1":"Xe từ cả hai chiều đều được dùng làn này, nhưng chỉ cho một loại di chuyển.","h2":"Làn ở giữa có vạch vàng liền và vạch vàng đứt ở hai bên là làn rẽ trái hai chiều, nên tài xế từ chiều nào cũng chỉ dùng nó để rẽ trái.","p":"Đúng rồi. Làn giữa đó chỉ để rẽ trái, cho xe từ cả hai chiều."},"tl":{"q":"May gitnang lane na may tuloy-tuloy na dilaw na linya at putol-putol na dilaw na linya sa bawat gilid. Para saan ang lane na ito?","o":["Para lampasan ang mabagal na sasakyan","Para sa malayuang pagmamaneho","Para sa pagparada at pagkarga","Para sa pagkaliwa ng mga driver mula sa magkabilang direksyon"],"h1":"Puwedeng gamitin ng mga sasakyan mula sa magkabilang direksyon ang lane na ito, pero para lang sa isang uri ng galaw.","h2":"Ang gitnang lane na may tuloy-tuloy at putol-putol na dilaw na linya sa magkabilang gilid ay two-way left-turn lane, kaya ginagamit lang ito ng mga driver mula sa alinmang direksyon para kumaliwa.","p":"Tama. Ang gitnang lane na iyon ay para lang sa pagkaliwa mula sa magkabilang direksyon."},"ar":{"q":"مسار في الوسط له خط أصفر متصل وخط أصفر متقطع على كل جانب. ما الغرض من هذا المسار؟","o":["لتجاوز السيارات البطيئة","للقيادة لمسافات طويلة","للوقوف والتحميل","للانعطاف يسارًا للسائقين من الاتجاهين"],"h1":"السيارات من الاتجاهين يمكنها أن تستخدم هذا المسار، لكن لنوع واحد فقط من الحركة.","h2":"المسار الأوسط الذي عليه خطوط صفراء متصلة ومتقطعة على الجانبين هو مسار للانعطاف يسارًا في الاتجاهين، لذلك السائقون من أي اتجاه يستخدمونه فقط للانعطاف يسارًا.","p":"صحيح. هذا المسار الأوسط فقط للانعطاف يسارًا من الاتجاهين."},"ht":{"q":"Yon koulwa nan mitan an gen yon liy jòn plen ak yon liy jòn koupe sou chak bò. Pou kisa koulwa sa a ye?","o":["Pou double machin ki dousman","Pou kondui long distans","Pou pake ak pou chaje","Pou chofè ki soti nan toude direksyon vire agoch"],"h1":"Machin ki soti nan toude direksyon ka sèvi ak koulwa sa a, men pou yon sèl kalite mouvman.","h2":"Yon koulwa nan mitan an ki gen liy jòn plen ak liy jòn koupe sou toude bò se yon koulwa pou vire agoch nan de direksyon, kidonk chofè ki soti nan nenpòt direksyon sèvi avè l sèlman pou vire agoch.","p":"Se sa. Koulwa nan mitan sa a se sèlman pou vire agoch soti nan toude direksyon."},"ref":{"doc":"FL","page":45}},{"id":"signals-025","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"Where should you stop when there is a wide white line painted across your lane at a red light?","o":["Before the white line","On top of the white line","Past the white line, at the corner","Anywhere in the intersection"],"h1":"This line shows the place where your front bumper should stop.","h2":"A wide white line across your lane is a stop line, so you must stop before it when you need to stop.","p":"Right. Stop before the white stop line."},"es":{"q":"¿Dónde debe parar cuando hay una línea blanca ancha pintada a lo ancho de su carril en una luz roja?","o":["Antes de la línea blanca","Encima de la línea blanca","Después de la línea blanca, en la esquina","En cualquier parte de la intersección"],"h1":"Esta línea muestra el lugar donde debe quedar el frente de su carro.","h2":"Una línea blanca ancha a lo ancho de su carril es la línea de pare, así que usted debe parar antes de ella cuando tiene que parar.","p":"Correcto. Pare antes de la línea blanca de pare."},"zh":{"q":"红灯时，你的车道上画着一条横过车道的宽白线。你应该停在哪里？","o":["白线前面","压在白线上","过了白线，停在路口拐角","路口里随便哪里"],"h1":"这条线表示你的前保险杠应该停在哪里。","h2":"横过你车道的宽白线是停车线，所以需要停车时，你必须停在它前面。","p":"对。停在白色停车线前面。"},"vi":{"q":"Khi đèn đỏ, có một vạch trắng rộng sơn ngang làn của bạn. Bạn nên dừng ở đâu?","o":["Trước vạch trắng","Ngay trên vạch trắng","Qua khỏi vạch trắng, ở góc đường","Bất cứ chỗ nào trong giao lộ"],"h1":"Vạch này cho thấy chỗ cản trước của xe bạn nên dừng lại.","h2":"Vạch trắng rộng ngang làn của bạn là vạch dừng, nên khi cần dừng, bạn phải dừng trước vạch đó.","p":"Đúng rồi. Hãy dừng trước vạch dừng màu trắng."},"tl":{"q":"Saan ka dapat huminto kapag may malapad na puting linyang nakapinta sa kabila ng lane mo sa pulang ilaw?","o":["Bago ang puting linya","Sa ibabaw ng puting linya","Lampas sa puting linya, sa may kanto","Kahit saan sa interseksyon"],"h1":"Ipinapakita ng linyang ito ang lugar kung saan dapat huminto ang harapang bumper mo.","h2":"Ang malapad na puting linya sa kabila ng lane mo ay stop line, kaya dapat kang huminto bago ito kapag kailangan mong huminto.","p":"Tama. Huminto bago ang puting stop line."},"ar":{"q":"أين يجب أن تتوقف عند ضوء أحمر عندما يكون هناك خط أبيض عريض مرسوم عرض مسارك؟","o":["قبل الخط الأبيض","فوق الخط الأبيض","بعد الخط الأبيض، عند الزاوية","في أي مكان داخل التقاطع"],"h1":"هذا الخط يُظهر المكان الذي يجب أن يتوقف عنده المصد الأمامي لسيارتك.","h2":"الخط الأبيض العريض عرض مسارك هو خط التوقف، لذلك يجب أن تتوقف قبله عندما تحتاج إلى التوقف.","p":"صحيح. توقف قبل خط التوقف الأبيض."},"ht":{"q":"Ki kote ou dwe kanpe lè gen yon gwo liy blan penti atravè koulwa ou nan yon limyè wouj?","o":["Anvan liy blan an","Sou liy blan an","Apre liy blan an, nan kwen an","Nenpòt kote nan kafou a"],"h1":"Liy sa a montre kote pare-chòk devan machin ou dwe kanpe.","h2":"Yon gwo liy blan atravè koulwa ou se yon liy pou kanpe, kidonk ou dwe kanpe anvan li lè ou bezwen kanpe.","p":"Se sa. Kanpe anvan liy blan pou kanpe a."},"ref":{"doc":"FL","page":45}},{"id":"signals-026","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"You must stop at an intersection. There is a marked crosswalk but no stop line. Where do you stop?","o":["In the middle of the crosswalk","Past the crosswalk, in the intersection","Before the crosswalk","Only if a person is in the crosswalk"],"h1":"Think about keeping the path clear for people walking.","h2":"When there is no stop line, you stop before the crosswalk, so people on foot have a clear path.","p":"Right. With no stop line, stop before the crosswalk."},"es":{"q":"Usted debe parar en una intersección. Hay un paso peatonal marcado, pero no hay línea de pare. ¿Dónde para?","o":["En medio del paso peatonal","Después del paso peatonal, dentro de la intersección","Antes del paso peatonal","Solo si hay una persona en el paso peatonal"],"h1":"Piense en dejar libre el camino de las personas que caminan.","h2":"Cuando no hay línea de pare, usted para antes del paso peatonal, para que las personas a pie tengan el camino libre.","p":"Correcto. Sin línea de pare, pare antes del paso peatonal."},"zh":{"q":"你必须在路口停车。那里有画好的人行横道，但没有停车线。你停在哪里？","o":["人行横道中间","过了人行横道，停在路口里","人行横道前面","只有人行横道上有人时才停"],"h1":"想一想：要给走路的人留出畅通的路。","h2":"没有停车线时，你要停在人行横道前面，这样行人有畅通的路可以走。","p":"对。没有停车线时，停在人行横道前面。"},"vi":{"q":"Bạn phải dừng ở một giao lộ. Có vạch qua đường cho người đi bộ nhưng không có vạch dừng. Bạn dừng ở đâu?","o":["Ở giữa vạch qua đường","Qua khỏi vạch qua đường, trong giao lộ","Trước vạch qua đường","Chỉ khi có người trên vạch qua đường"],"h1":"Hãy nghĩ đến việc để trống lối đi cho người đi bộ.","h2":"Khi không có vạch dừng, bạn dừng trước vạch qua đường, để người đi bộ có lối đi trống.","p":"Đúng rồi. Khi không có vạch dừng, hãy dừng trước vạch qua đường."},"tl":{"q":"Dapat kang huminto sa isang interseksyon. May minarkahang tawiran pero walang stop line. Saan ka hihinto?","o":["Sa gitna ng tawiran","Lampas sa tawiran, sa loob ng interseksyon","Bago ang tawiran","Kung may tao lang sa tawiran"],"h1":"Isipin ang pagpapanatiling maluwag ng daanan ng mga naglalakad.","h2":"Kapag walang stop line, huminto ka bago ang tawiran, para maluwag ang daanan ng mga naglalakad.","p":"Tama. Kapag walang stop line, huminto bago ang tawiran."},"ar":{"q":"يجب أن تتوقف عند تقاطع. هناك ممر مشاة مرسوم لكن لا يوجد خط توقف. أين تتوقف؟","o":["في وسط ممر المشاة","بعد ممر المشاة، داخل التقاطع","قبل ممر المشاة","فقط إذا كان هناك شخص في ممر المشاة"],"h1":"فكّر في إبقاء الطريق خاليًا للمشاة.","h2":"عندما لا يوجد خط توقف، تتوقف قبل ممر المشاة، لكي يكون طريق المشاة خاليًا.","p":"صحيح. بدون خط توقف، توقف قبل ممر المشاة."},"ht":{"q":"Ou dwe kanpe nan yon kafou. Gen yon pasaj pyeton ki make, men pa gen liy pou kanpe. Ki kote ou kanpe?","o":["Nan mitan pasaj pyeton an","Apre pasaj pyeton an, nan kafou a","Anvan pasaj pyeton an","Sèlman si gen yon moun nan pasaj pyeton an"],"h1":"Panse ak kite chemen an lib pou moun k ap mache.","h2":"Lè pa gen liy pou kanpe, ou kanpe anvan pasaj pyeton an, pou moun ki a pye yo gen yon chemen lib.","p":"Se sa. Lè pa gen liy pou kanpe, kanpe anvan pasaj pyeton an."},"ref":{"doc":"FL","page":45}},{"id":"signals-027","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"You see a bicycle symbol with two arrow shapes (chevrons) painted in your lane. What does it mean?","o":["Only bicycles may use this lane","Bicycles and cars share this lane","Bicycles are not allowed here","This lane is for parking bicycles"],"h1":"The marking is in a regular traffic lane, not in a separate bike lane.","h2":"A bicycle with chevrons is a shared lane marking, which means bicycles and cars share the lane, so watch for riders and give them room.","p":"Right. That marking means bikes and cars share the lane."},"es":{"q":"Usted ve un dibujo de bicicleta con dos flechas en forma de ángulo pintado en su carril. ¿Qué significa?","o":["Solo las bicicletas pueden usar este carril","Las bicicletas y los carros comparten este carril","No se permiten bicicletas aquí","Este carril es para estacionar bicicletas"],"h1":"La marca está en un carril normal de tráfico, no en un carril aparte para bicicletas.","h2":"Una bicicleta con flechas en ángulo es una marca de carril compartido, lo que significa que bicicletas y carros comparten el carril, así que fíjese en los ciclistas y deles espacio.","p":"Correcto. Esa marca significa que bicicletas y carros comparten el carril."},"zh":{"q":"你看到你的车道上画着一个自行车图案和两个箭头形状（V 形符号）。它是什么意思？","o":["只有自行车可以用这条车道","自行车和汽车共用这条车道","这里不准骑自行车","这条车道是停自行车的"],"h1":"这个标记在普通车道上，不在单独的自行车道上。","h2":"自行车加 V 形符号是共用车道标记，表示自行车和汽车共用这条车道，所以要注意骑车的人，给他们留出空间。","p":"对。这个标记表示自行车和汽车共用车道。"},"vi":{"q":"Bạn thấy hình xe đạp với hai hình mũi tên (chevron) được sơn trong làn của bạn. Điều đó có nghĩa là gì?","o":["Chỉ xe đạp được dùng làn này","Xe đạp và xe hơi dùng chung làn này","Ở đây cấm xe đạp","Làn này để đỗ xe đạp"],"h1":"Dấu này nằm trong làn xe bình thường, không phải trong làn riêng cho xe đạp.","h2":"Hình xe đạp có chevron là dấu làn dùng chung, nghĩa là xe đạp và xe hơi dùng chung làn, nên bạn cần chú ý người đi xe đạp và chừa chỗ cho họ.","p":"Đúng rồi. Dấu đó nghĩa là xe đạp và xe hơi dùng chung làn."},"tl":{"q":"May nakita kang simbolo ng bisikleta na may dalawang hugis-arrow (chevron) na nakapinta sa lane mo. Ano ang ibig sabihin nito?","o":["Mga bisikleta lang ang puwedeng gumamit ng lane na ito","Magkasamang ginagamit ng bisikleta at sasakyan ang lane na ito","Bawal ang bisikleta dito","Ang lane na ito ay paradahan ng bisikleta"],"h1":"Ang marka ay nasa karaniwang lane ng trapiko, hindi sa hiwalay na bike lane.","h2":"Ang bisikletang may chevron ay marka ng shared lane, na nangangahulugang magkasamang ginagamit ng bisikleta at sasakyan ang lane, kaya mag-ingat sa mga nagbibisikleta at bigyan sila ng puwang.","p":"Tama. Ang markang iyon ay nangangahulugang magkasama sa lane ang bisikleta at sasakyan."},"ar":{"q":"ترى رمز دراجة هوائية مع شكلين على هيئة سهم مرسومين في مسارك. ماذا يعني؟","o":["الدراجات فقط يمكنها أن تستخدم هذا المسار","الدراجات والسيارات تتشارك هذا المسار","الدراجات ممنوعة هنا","هذا المسار لوقوف الدراجات"],"h1":"العلامة موجودة في مسار سير عادي، وليست في مسار منفصل للدراجات.","h2":"الدراجة مع شكلي السهم هي علامة مسار مشترك، وتعني أن الدراجات والسيارات تتشارك المسار، لذلك انتبه لراكبي الدراجات واترك لهم مسافة.","p":"صحيح. هذه العلامة تعني أن الدراجات والسيارات تتشارك المسار."},"ht":{"q":"Ou wè yon foto bisiklèt ak de flèch an fòm V (chevwon) penti nan koulwa ou. Kisa li vle di?","o":["Se sèlman bisiklèt ki ka sèvi ak koulwa sa a","Bisiklèt ak machin pataje koulwa sa a","Bisiklèt pa gen dwa la a","Koulwa sa a se pou pake bisiklèt"],"h1":"Mak la nan yon koulwa trafik nòmal, se pa nan yon koulwa bisiklèt apa.","h2":"Yon bisiklèt ak chevwon se yon mak koulwa pataje, sa vle di bisiklèt ak machin pataje koulwa a, kidonk veye moun sou bisiklèt epi ba yo plas.","p":"Se sa. Mak sa a vle di bisiklèt ak machin pataje koulwa a."},"ref":{"doc":"FL","page":45}},{"id":"signals-028","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"A white diamond is painted in a lane. What does it usually mean?","o":["The lane is a school zone","The lane ends soon","The lane is for slow trucks only","The lane is reserved for certain vehicles, like carpools or buses, at posted times"],"h1":"Look for a sign near the lane that tells who may use it.","h2":"A white diamond marks a reserved lane, such as a high-occupancy (HOV) lane for carpools, so you may use it only if you meet the rules posted on the signs.","p":"Right. The diamond marks a reserved lane, like a carpool lane."},"es":{"q":"Hay un diamante blanco pintado en un carril. ¿Qué suele significar?","o":["El carril es una zona escolar","El carril se termina pronto","El carril es solo para camiones lentos","El carril está reservado para ciertos vehículos, como carros compartidos o autobuses, en los horarios indicados"],"h1":"Busque una señal cerca del carril que diga quién puede usarlo.","h2":"Un diamante blanco marca un carril reservado, como un carril para vehículos con varios ocupantes (HOV), así que usted solo puede usarlo si cumple las reglas de las señales.","p":"Correcto. El diamante marca un carril reservado, como el de carros compartidos."},"zh":{"q":"车道上画着一个白色菱形。它通常是什么意思？","o":["这条车道是学校区","这条车道很快结束","这条车道只给慢速卡车","在标明的时间内，这条车道只给某些车辆用，比如拼车或公交车"],"h1":"找一找车道旁边说明谁可以用的标志。","h2":"白色菱形表示专用车道，比如给拼车用的多乘员车道（HOV），所以只有符合标志上的规定，你才可以用它。","p":"对。菱形表示专用车道，比如拼车车道。"},"vi":{"q":"Một hình thoi màu trắng được sơn trong làn. Điều đó thường có nghĩa là gì?","o":["Làn này là khu vực trường học","Làn này sắp hết","Làn này chỉ cho xe tải chạy chậm","Làn này dành riêng cho một số loại xe, như xe đi chung hoặc xe buýt, vào giờ được ghi trên biển"],"h1":"Hãy tìm biển báo gần làn cho biết ai được dùng nó.","h2":"Hình thoi màu trắng đánh dấu làn dành riêng, như làn HOV cho xe chở nhiều người đi chung, nên bạn chỉ được dùng nó nếu đúng với quy định ghi trên biển.","p":"Đúng rồi. Hình thoi đánh dấu làn dành riêng, như làn cho xe đi chung."},"tl":{"q":"May puting diyamanteng nakapinta sa isang lane. Ano ang karaniwang ibig sabihin nito?","o":["School zone ang lane","Matatapos na ang lane","Para sa mabagal na trak lang ang lane","Nakalaan ang lane para sa ilang sasakyan, tulad ng carpool o bus, sa mga oras na nakasulat sa karatula"],"h1":"Maghanap ng karatula malapit sa lane na nagsasabi kung sino ang puwedeng gumamit nito.","h2":"Ang puting diyamante ay nagmamarka ng nakalaang lane, tulad ng high-occupancy (HOV) lane para sa carpool, kaya puwede mo lang itong gamitin kung pasok ka sa mga patakarang nakasulat sa mga karatula.","p":"Tama. Ang diyamante ay nagmamarka ng nakalaang lane, tulad ng carpool lane."},"ar":{"q":"معيّن (ماسة) أبيض مرسوم في مسار. ماذا يعني عادةً؟","o":["المسار منطقة مدرسة","المسار ينتهي قريبًا","المسار للشاحنات البطيئة فقط","المسار مخصص لمركبات معيّنة، مثل السيارات المشتركة أو الحافلات، في الأوقات المكتوبة"],"h1":"ابحث عن لافتة قرب المسار تخبرك من يمكنه أن يستخدمه.","h2":"المعيّن الأبيض يدل على مسار مخصص، مثل مسار المركبات عالية الإشغال (HOV) للسيارات المشتركة، لذلك يمكنك أن تستخدمه فقط إذا كنت تتبع القواعد المكتوبة على اللافتات.","p":"صحيح. المعيّن يدل على مسار مخصص، مثل مسار السيارات المشتركة."},"ht":{"q":"Gen yon dyaman blan penti nan yon koulwa. Kisa li konn vle di?","o":["Koulwa a se yon zòn lekòl","Koulwa a ap fini talè","Koulwa a se pou kamyon ki dousman sèlman","Koulwa a rezève pou kèk machin, tankou machin ki pote plizyè moun oswa bis, nan lè ki make yo"],"h1":"Chèche yon siy toupre koulwa a ki di kiyès ki ka sèvi avè l.","h2":"Yon dyaman blan make yon koulwa rezève, tankou yon koulwa HOV pou machin ki pote plizyè moun, kidonk ou ka sèvi avè l sèlman si ou respekte règ ki ekri sou siy yo.","p":"Se sa. Dyaman an make yon koulwa rezève, tankou yon koulwa pou machin ki pote plizyè moun."},"ref":{"doc":"FL","page":69}},{"id":"signals-029","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"A white arrow painted in your lane points only to the right. What should you do?","o":["Turn right from this lane","Go straight from this lane","Turn left from this lane","Make a U-turn from this lane"],"h1":"Arrows in a lane show which way that lane must go.","h2":"A lane arrow that points only to the right means drivers in that lane must turn right.","p":"Right. A right arrow in your lane means turn right."},"es":{"q":"Una flecha blanca pintada en su carril apunta solo a la derecha. ¿Qué debe hacer?","o":["Girar a la derecha desde este carril","Seguir derecho desde este carril","Girar a la izquierda desde este carril","Dar una vuelta en U desde este carril"],"h1":"Las flechas en un carril muestran hacia dónde debe ir ese carril.","h2":"Una flecha en el carril que apunta solo a la derecha significa que los conductores en ese carril deben girar a la derecha.","p":"Correcto. Una flecha a la derecha en su carril significa gire a la derecha."},"zh":{"q":"你的车道上画着一个只指向右边的白色箭头。你应该怎么做？","o":["从这条车道右转","从这条车道直行","从这条车道左转","从这条车道掉头"],"h1":"车道上的箭头表示这条车道必须往哪里走。","h2":"只指向右边的车道箭头表示这条车道上的司机必须右转。","p":"对。你的车道上有右转箭头，表示要右转。"},"vi":{"q":"Một mũi tên trắng sơn trong làn của bạn chỉ chỉ sang phải. Bạn nên làm gì?","o":["Rẽ phải từ làn này","Đi thẳng từ làn này","Rẽ trái từ làn này","Quay đầu xe từ làn này"],"h1":"Mũi tên trong làn cho biết làn đó phải đi hướng nào.","h2":"Mũi tên trong làn chỉ chỉ sang phải nghĩa là tài xế trong làn đó phải rẽ phải.","p":"Đúng rồi. Mũi tên phải trong làn của bạn nghĩa là rẽ phải."},"tl":{"q":"Ang puting arrow na nakapinta sa lane mo ay nakaturo lang pakanan. Ano ang dapat mong gawin?","o":["Kumanan mula sa lane na ito","Dumiretso mula sa lane na ito","Kumaliwa mula sa lane na ito","Mag-U-turn mula sa lane na ito"],"h1":"Ipinapakita ng mga arrow sa lane kung saan dapat pumunta ang lane na iyon.","h2":"Ang arrow sa lane na nakaturo lang pakanan ay nangangahulugang dapat kumanan ang mga driver sa lane na iyon.","p":"Tama. Ang arrow pakanan sa lane mo ay nangangahulugang kumanan."},"ar":{"q":"سهم أبيض مرسوم في مسارك يشير إلى اليمين فقط. ماذا يجب أن تفعل؟","o":["انعطف يمينًا من هذا المسار","سِر مستقيمًا من هذا المسار","انعطف يسارًا من هذا المسار","استدر للخلف من هذا المسار"],"h1":"الأسهم في المسار تُظهر الاتجاه الذي يجب أن يسير فيه هذا المسار.","h2":"سهم المسار الذي يشير إلى اليمين فقط يعني أن السائقين في هذا المسار يجب أن ينعطفوا يمينًا.","p":"صحيح. سهم إلى اليمين في مسارك يعني: انعطف يمينًا."},"ht":{"q":"Yon flèch blan penti nan koulwa ou montre sèlman adwat. Kisa ou dwe fè?","o":["Vire adwat nan koulwa sa a","Ale tou dwat nan koulwa sa a","Vire agoch nan koulwa sa a","Vire tounen nan koulwa sa a"],"h1":"Flèch nan yon koulwa montre ki bò koulwa sa a dwe ale.","h2":"Yon flèch nan koulwa a ki montre sèlman adwat vle di chofè nan koulwa sa a dwe vire adwat.","p":"Se sa. Yon flèch adwat nan koulwa ou vle di vire adwat."},"ref":{"doc":"FL","page":45}},{"id":"signals-030","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"A row of white triangles is painted across your lane, pointing at you. What does it mean?","o":["Speed up to merge","The lane is for bicycles only","Yield here to traffic and people walking","You are on a one-way street the wrong way"],"h1":"The triangles look like a sign with the same shape.","h2":"A row of white triangles pointing toward you is a yield line, so you must slow down and be ready to stop there for other traffic and people walking.","p":"Right. The row of triangles is a yield line."},"es":{"q":"Una fila de triángulos blancos está pintada a lo ancho de su carril, apuntando hacia usted. ¿Qué significa?","o":["Acelere para incorporarse","El carril es solo para bicicletas","Ceda el paso aquí al tráfico y a los peatones","Usted va en contra en una calle de un solo sentido"],"h1":"Los triángulos se parecen a una señal que tiene la misma forma.","h2":"Una fila de triángulos blancos que apuntan hacia usted es una línea de ceda el paso, así que usted debe bajar la velocidad y estar listo para parar ahí por otro tráfico y por los peatones.","p":"Correcto. La fila de triángulos es una línea de ceda el paso."},"zh":{"q":"你的车道上横着画了一排白色三角形，尖角指向你。它是什么意思？","o":["加速并道","这条车道只给自行车","在这里给车辆和行人让行","你在单行道上逆行"],"h1":"这些三角形像一个形状相同的标志。","h2":"一排尖角指向你的白色三角形是让行线，所以你必须减速，准备在那里为其他车辆和行人停车。","p":"对。这排三角形是让行线。"},"vi":{"q":"Một hàng hình tam giác trắng được sơn ngang làn của bạn, mũi nhọn chỉ về phía bạn. Điều đó có nghĩa là gì?","o":["Tăng tốc để nhập làn","Làn này chỉ dành cho xe đạp","Nhường đường ở đây cho xe khác và người đi bộ","Bạn đang chạy ngược chiều trên đường một chiều"],"h1":"Các hình tam giác giống một biển báo có cùng hình dạng.","h2":"Hàng tam giác trắng chỉ về phía bạn là vạch nhường đường, nên bạn phải chạy chậm lại và sẵn sàng dừng ở đó cho xe khác và người đi bộ.","p":"Đúng rồi. Hàng tam giác đó là vạch nhường đường."},"tl":{"q":"May hanay ng mga puting tatsulok na nakapinta sa kabila ng lane mo, na nakaturo sa iyo. Ano ang ibig sabihin nito?","o":["Bumilis para makasingit","Para sa bisikleta lang ang lane","Magbigay-daan dito sa trapiko at sa mga taong naglalakad","Nasa one-way na kalye ka sa maling direksyon"],"h1":"Kamukha ng mga tatsulok ang isang karatula na may parehong hugis.","h2":"Ang hanay ng mga puting tatsulok na nakaturo sa iyo ay yield line, kaya dapat kang bumagal at maging handang huminto doon para sa ibang trapiko at sa mga taong naglalakad.","p":"Tama. Ang hanay ng mga tatsulok ay yield line."},"ar":{"q":"صف من المثلثات البيضاء مرسوم عرض مسارك، ورؤوسها تشير نحوك. ماذا يعني؟","o":["زد السرعة لتندمج","المسار للدراجات فقط","أعطِ الأولوية هنا للسيارات وللمشاة","أنت في شارع باتجاه واحد في الاتجاه الخاطئ"],"h1":"المثلثات تشبه لافتة لها نفس الشكل.","h2":"صف المثلثات البيضاء التي تشير نحوك هو خط إعطاء الأولوية، لذلك يجب أن تخفف السرعة وتكون مستعدًا للتوقف هناك من أجل السيارات الأخرى والمشاة.","p":"صحيح. صف المثلثات هو خط إعطاء الأولوية."},"ht":{"q":"Gen yon ranje ti triyang blan penti atravè koulwa ou, ak pwent yo vire sou ou. Kisa li vle di?","o":["Akselere pou antre","Koulwa a se pou bisiklèt sèlman","Bay machin ak moun k ap mache pasaj la a","Ou nan move direksyon sou yon lari yon sèl direksyon"],"h1":"Triyang yo sanble ak yon siy ki gen menm fòm nan.","h2":"Yon ranje triyang blan ki vire sou ou se yon liy pou bay pasaj, kidonk ou dwe ralanti epi pare pou kanpe la a pou lòt machin ak moun k ap mache.","p":"Se sa. Ranje triyang yo se yon liy pou bay pasaj."}},{"id":"signals-031","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"Over a reversible lane, you see a green arrow pointing down. What does it mean?","o":["You must leave this lane","You may drive in this lane","You may not drive in this lane","The lane is only for left turns"],"h1":"Green on a lane signal means the same thing as green on a traffic light.","h2":"A green arrow pointing down over a lane means you may drive in that lane.","p":"Right. A green arrow over the lane means you may use it."},"es":{"q":"Sobre un carril reversible, usted ve una flecha verde que apunta hacia abajo. ¿Qué significa?","o":["Debe salir de este carril","Puede manejar en este carril","No puede manejar en este carril","El carril es solo para girar a la izquierda"],"h1":"El verde en una señal de carril significa lo mismo que en un semáforo.","h2":"Una flecha verde que apunta hacia abajo sobre un carril significa que usted puede manejar en ese carril.","p":"Correcto. Una flecha verde sobre el carril significa que puede usarlo."},"zh":{"q":"在可变方向车道上方，你看到一个向下的绿色箭头。它是什么意思？","o":["你必须离开这条车道","你可以在这条车道上开","你不能在这条车道上开","这条车道只能左转"],"h1":"车道信号上的绿色和红绿灯上的绿色意思一样。","h2":"车道上方向下的绿色箭头表示你可以在这条车道上开。","p":"对。车道上方的绿色箭头表示你可以用这条车道。"},"vi":{"q":"Phía trên một làn đổi chiều, bạn thấy mũi tên xanh chỉ xuống. Điều đó có nghĩa là gì?","o":["Bạn phải rời khỏi làn này","Bạn được chạy trong làn này","Bạn không được chạy trong làn này","Làn này chỉ để rẽ trái"],"h1":"Màu xanh trên đèn báo làn có nghĩa giống như màu xanh trên đèn giao thông.","h2":"Mũi tên xanh chỉ xuống phía trên một làn nghĩa là bạn được chạy trong làn đó.","p":"Đúng rồi. Mũi tên xanh phía trên làn nghĩa là bạn được dùng làn đó."},"tl":{"q":"Sa itaas ng isang reversible lane, may nakita kang berdeng arrow na nakaturo pababa. Ano ang ibig sabihin nito?","o":["Dapat kang umalis sa lane na ito","Puwede kang magmaneho sa lane na ito","Hindi ka puwedeng magmaneho sa lane na ito","Para sa pagkaliwa lang ang lane"],"h1":"Pareho ang ibig sabihin ng berde sa ilaw ng lane at ng berde sa ilaw trapiko.","h2":"Ang berdeng arrow na nakaturo pababa sa itaas ng lane ay nangangahulugang puwede kang magmaneho sa lane na iyon.","p":"Tama. Ang berdeng arrow sa itaas ng lane ay nangangahulugang puwede mo itong gamitin."},"ar":{"q":"فوق مسار متغيّر الاتجاه، ترى سهمًا أخضر يشير إلى الأسفل. ماذا يعني؟","o":["يجب أن تخرج من هذا المسار","يمكنك أن تقود في هذا المسار","لا يمكنك أن تقود في هذا المسار","المسار للانعطاف يسارًا فقط"],"h1":"الأخضر في إشارة المسار يعني نفس ما يعنيه الأخضر في إشارة المرور.","h2":"السهم الأخضر الذي يشير إلى الأسفل فوق مسار يعني أنه يمكنك أن تقود في هذا المسار.","p":"صحيح. السهم الأخضر فوق المسار يعني أنه يمكنك أن تستخدمه."},"ht":{"q":"Anwo yon koulwa ki ka chanje direksyon, ou wè yon flèch vèt ki montre anba. Kisa li vle di?","o":["Ou dwe kite koulwa sa a","Ou ka kondui nan koulwa sa a","Ou pa ka kondui nan koulwa sa a","Koulwa a se pou vire agoch sèlman"],"h1":"Vèt sou yon siyal koulwa vle di menm bagay ak vèt sou yon limyè trafik.","h2":"Yon flèch vèt ki montre anba anwo yon koulwa vle di ou ka kondui nan koulwa sa a.","p":"Se sa. Yon flèch vèt anwo koulwa a vle di ou ka sèvi avè l."},"ref":{"doc":"FL","page":53}},{"id":"signals-032","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"Over a reversible lane, you see a red X. What does it mean?","o":["You may drive in this lane","You may pass in this lane","The lane is for buses only","Do not drive in this lane"],"h1":"Think about what a red X means anywhere.","h2":"A red X over a lane means you must not drive in that lane, because traffic may be coming the other way.","p":"Right. A red X means do not use that lane."},"es":{"q":"Sobre un carril reversible, usted ve una X roja. ¿Qué significa?","o":["Puede manejar en este carril","Puede rebasar en este carril","El carril es solo para autobuses","No maneje en este carril"],"h1":"Piense qué significa una X roja en cualquier lugar.","h2":"Una X roja sobre un carril significa que usted no debe manejar en ese carril, porque el tráfico puede venir en el otro sentido.","p":"Correcto. Una X roja significa no use ese carril."},"zh":{"q":"在可变方向车道上方，你看到一个红色的 X。它是什么意思？","o":["你可以在这条车道上开","你可以在这条车道上超车","这条车道只给公交车","不要在这条车道上开"],"h1":"想一想红色 X 在任何地方是什么意思。","h2":"车道上方的红色 X 表示你不能在这条车道上开，因为可能有车从对面开过来。","p":"对。红色 X 表示不要用这条车道。"},"vi":{"q":"Phía trên một làn đổi chiều, bạn thấy chữ X màu đỏ. Điều đó có nghĩa là gì?","o":["Bạn được chạy trong làn này","Bạn được vượt trong làn này","Làn này chỉ dành cho xe buýt","Không được chạy trong làn này"],"h1":"Hãy nghĩ xem chữ X màu đỏ ở đâu cũng có nghĩa là gì.","h2":"Chữ X đỏ phía trên một làn nghĩa là bạn không được chạy trong làn đó, vì có thể có xe đang chạy tới từ chiều ngược lại.","p":"Đúng rồi. Chữ X đỏ nghĩa là không được dùng làn đó."},"tl":{"q":"Sa itaas ng isang reversible lane, may nakita kang pulang X. Ano ang ibig sabihin nito?","o":["Puwede kang magmaneho sa lane na ito","Puwede kang mag-overtake sa lane na ito","Para sa bus lang ang lane","Huwag magmaneho sa lane na ito"],"h1":"Isipin kung ano ang ibig sabihin ng pulang X saanman.","h2":"Ang pulang X sa itaas ng lane ay nangangahulugang hindi ka dapat magmaneho sa lane na iyon, dahil maaaring may trapikong papunta mula sa kabilang direksyon.","p":"Tama. Ang pulang X ay nangangahulugang huwag gamitin ang lane na iyon."},"ar":{"q":"فوق مسار متغيّر الاتجاه، ترى حرف X أحمر. ماذا يعني؟","o":["يمكنك أن تقود في هذا المسار","يمكنك أن تتجاوز في هذا المسار","المسار للحافلات فقط","لا تقُد في هذا المسار"],"h1":"فكّر في معنى X الأحمر في أي مكان.","h2":"حرف X الأحمر فوق مسار يعني أنه يجب ألا تقود في هذا المسار، لأن السيارات قد تأتي من الاتجاه الآخر.","p":"صحيح. X الأحمر يعني: لا تستخدم هذا المسار."},"ht":{"q":"Anwo yon koulwa ki ka chanje direksyon, ou wè yon X wouj. Kisa li vle di?","o":["Ou ka kondui nan koulwa sa a","Ou ka double nan koulwa sa a","Koulwa a se pou bis sèlman","Pa kondui nan koulwa sa a"],"h1":"Panse ak sa yon X wouj vle di nenpòt kote.","h2":"Yon X wouj anwo yon koulwa vle di ou pa dwe kondui nan koulwa sa a, paske ka gen machin k ap vini nan lòt direksyon an.","p":"Se sa. Yon X wouj vle di pa sèvi ak koulwa sa a."},"ref":{"doc":"FL","page":53}},{"id":"signals-033","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"Over a reversible lane, you see a steady yellow X. What should you do?","o":["Move out of this lane safely, because it is about to change","Stay in the lane as long as you like","Speed up in this lane","Stop in the lane and wait"],"h1":"A steady yellow X works like a steady yellow light: something is about to change.","h2":"A steady yellow X over a lane means the lane is about to close to your direction, so you should safely move out of it.","p":"Right. A steady yellow X means leave the lane safely."},"es":{"q":"Sobre un carril reversible, usted ve una X amarilla fija. ¿Qué debe hacer?","o":["Salir del carril con seguridad, porque está por cambiar","Quedarse en el carril todo el tiempo que quiera","Acelerar en este carril","Parar en el carril y esperar"],"h1":"Una X amarilla fija funciona como una luz amarilla fija: algo está por cambiar.","h2":"Una X amarilla fija sobre un carril significa que el carril se va a cerrar para su dirección, así que usted debe salir de él con seguridad.","p":"Correcto. Una X amarilla fija significa salga del carril con seguridad."},"zh":{"q":"在可变方向车道上方，你看到一个一直亮着的黄色 X。你应该怎么做？","o":["安全地离开这条车道，因为它马上要变","想在这条车道开多久就开多久","在这条车道上加速","在车道里停车等待"],"h1":"一直亮着的黄色 X 和一直亮着的黄灯一样：马上有变化。","h2":"车道上方一直亮着的黄色 X 表示这条车道马上要对你的方向关闭，所以你应该安全地离开它。","p":"对。一直亮着的黄色 X 表示要安全地离开这条车道。"},"vi":{"q":"Phía trên một làn đổi chiều, bạn thấy chữ X màu vàng sáng đứng yên. Bạn nên làm gì?","o":["Ra khỏi làn này một cách an toàn, vì làn sắp đổi","Ở trong làn bao lâu tùy thích","Tăng tốc trong làn này","Dừng lại trong làn và chờ"],"h1":"Chữ X vàng sáng đứng yên giống như đèn vàng sáng đứng yên: sắp có điều gì đó thay đổi.","h2":"Chữ X vàng sáng đứng yên phía trên một làn nghĩa là làn đó sắp đóng với chiều xe của bạn, nên bạn cần ra khỏi làn một cách an toàn.","p":"Đúng rồi. Chữ X vàng nghĩa là hãy rời khỏi làn một cách an toàn."},"tl":{"q":"Sa itaas ng isang reversible lane, may nakita kang tuloy-tuloy na dilaw na X. Ano ang dapat mong gawin?","o":["Lumabas nang ligtas sa lane na ito, dahil malapit na itong magbago","Manatili sa lane hangga't gusto mo","Bumilis sa lane na ito","Huminto sa lane at maghintay"],"h1":"Ang tuloy-tuloy na dilaw na X ay gumagana na parang tuloy-tuloy na dilaw na ilaw: may malapit nang magbago.","h2":"Ang tuloy-tuloy na dilaw na X sa itaas ng lane ay nangangahulugang malapit nang isara ang lane para sa direksyon mo, kaya dapat kang lumabas dito nang ligtas.","p":"Tama. Ang tuloy-tuloy na dilaw na X ay nangangahulugang umalis nang ligtas sa lane."},"ar":{"q":"فوق مسار متغيّر الاتجاه، ترى حرف X أصفر ثابتًا. ماذا يجب أن تفعل؟","o":["اخرج من هذا المسار بأمان، لأنه سيتغيّر بعد قليل","ابقَ في المسار كما تريد","زد السرعة في هذا المسار","توقف في المسار وانتظر"],"h1":"X الأصفر الثابت يعمل مثل الضوء الأصفر الثابت: شيء ما سيتغيّر بعد قليل.","h2":"حرف X الأصفر الثابت فوق مسار يعني أن المسار سيُغلق قريبًا أمام اتجاهك، لذلك يجب أن تخرج منه بأمان.","p":"صحيح. X الأصفر الثابت يعني: اخرج من المسار بأمان."},"ht":{"q":"Anwo yon koulwa ki ka chanje direksyon, ou wè yon X jòn fiks. Kisa ou dwe fè?","o":["Kite koulwa sa a an sekirite, paske li pral chanje","Rete nan koulwa a otan ou vle","Akselere nan koulwa sa a","Kanpe nan koulwa a epi tann"],"h1":"Yon X jòn fiks mache tankou yon limyè jòn fiks: yon bagay pral chanje.","h2":"Yon X jòn fiks anwo yon koulwa vle di koulwa a pral fèmen pou direksyon ou a, kidonk ou dwe kite l an sekirite.","p":"Se sa. Yon X jòn fiks vle di kite koulwa a an sekirite."},"ref":{"doc":"FL","page":53}},{"id":"signals-034","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"A police officer is directing traffic at an intersection. The light is green, but the officer signals you to stop. What do you do?","o":["Go, because the light is green","Honk to get the officer to move","Stop and follow the officer","Turn right to go around the officer"],"h1":"Think about who sees the real situation at that moment.","h2":"You must follow the directions of a police officer directing traffic, even when they are different from the traffic light.","p":"Right. A police officer’s directions come before the traffic light."},"es":{"q":"Un policía está dirigiendo el tráfico en una intersección. La luz está en verde, pero el policía le indica que pare. ¿Qué hace?","o":["Seguir, porque la luz está en verde","Tocar la bocina para que el policía se mueva","Parar y seguir las indicaciones del policía","Girar a la derecha para pasar al policía"],"h1":"Piense quién ve la situación real en ese momento.","h2":"Usted debe seguir las indicaciones de un policía que dirige el tráfico, aunque sean diferentes a las del semáforo.","p":"Correcto. Las indicaciones del policía van antes que el semáforo."},"zh":{"q":"一名警察在路口指挥交通。灯是绿的，但警察示意你停车。你怎么做？","o":["开走，因为是绿灯","按喇叭让警察让开","停车，听警察的指挥","右转绕过警察"],"h1":"想一想：谁能看到当时的真实情况。","h2":"你必须服从指挥交通的警察，就算警察的指挥和红绿灯不一样也要服从。","p":"对。警察的指挥比红绿灯优先。"},"vi":{"q":"Một cảnh sát đang điều khiển giao thông ở giao lộ. Đèn đang xanh, nhưng cảnh sát ra hiệu cho bạn dừng. Bạn làm gì?","o":["Cứ đi, vì đèn đang xanh","Bấm còi để cảnh sát tránh ra","Dừng lại và làm theo cảnh sát","Rẽ phải để đi vòng qua cảnh sát"],"h1":"Hãy nghĩ xem ai đang thấy rõ tình hình thật lúc đó.","h2":"Bạn phải làm theo hướng dẫn của cảnh sát đang điều khiển giao thông, kể cả khi hướng dẫn đó khác với đèn giao thông.","p":"Đúng rồi. Hướng dẫn của cảnh sát được ưu tiên hơn đèn giao thông."},"tl":{"q":"May pulis na nagdidirekta ng trapiko sa isang interseksyon. Berde ang ilaw, pero sinesenyasan ka ng pulis na huminto. Ano ang gagawin mo?","o":["Umandar, dahil berde ang ilaw","Bumusina para umalis ang pulis","Huminto at sundin ang pulis","Kumanan para lumihis paikot sa pulis"],"h1":"Isipin kung sino ang nakakakita ng tunay na sitwasyon sa sandaling iyon.","h2":"Dapat mong sundin ang utos ng pulis na nagdidirekta ng trapiko, kahit iba ito sa sinasabi ng ilaw trapiko.","p":"Tama. Mas nauuna ang utos ng pulis kaysa sa ilaw trapiko."},"ar":{"q":"شرطي ينظّم السير في تقاطع. الإشارة خضراء، لكن الشرطي يشير لك أن تتوقف. ماذا تفعل؟","o":["انطلق، لأن الإشارة خضراء","استخدم البوق لكي يتحرك الشرطي","توقف واتبع تعليمات الشرطي","انعطف يمينًا لتمر من حول الشرطي"],"h1":"فكّر في من يرى الوضع الحقيقي في تلك اللحظة.","h2":"يجب أن تتبع تعليمات الشرطي الذي ينظّم السير، حتى عندما تكون مختلفة عن إشارة المرور.","p":"صحيح. تعليمات الشرطي تأتي قبل إشارة المرور."},"ht":{"q":"Yon polis ap dirije trafik nan yon kafou. Limyè a vèt, men polis la fè ou siy pou kanpe. Kisa ou fè?","o":["Pase, paske limyè a vèt","Klaksonen pou polis la deplase","Kanpe epi swiv polis la","Vire adwat pou pase bò kote polis la"],"h1":"Panse ak kiyès ki wè sa k ap pase vre nan moman an.","h2":"Ou dwe swiv sa yon polis k ap dirije trafik di ou, menm lè sa diferan ak limyè trafik la.","p":"Se sa. Sa polis la di pase anvan limyè trafik la."},"ref":{"doc":"FL","page":51}},{"id":"signals-035","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"In a work zone, a flagger holds up a sign that says SLOW. What should you do?","o":["Stop and wait for a police officer","Slow down and go ahead with care, watching for workers","Keep your normal speed","Turn around and find another road"],"h1":"Think about who may be working close to the road.","h2":"A flagger showing a SLOW sign means you should slow down and go ahead with care, because workers and equipment may be near the road.","p":"Right. A SLOW paddle means slow down and drive with care."},"es":{"q":"En una zona de trabajo, un abanderado levanta un letrero que dice SLOW (despacio). ¿Qué debe hacer?","o":["Parar y esperar a un policía","Bajar la velocidad y seguir con cuidado, fijándose en los trabajadores","Mantener su velocidad normal","Dar la vuelta y buscar otra calle"],"h1":"Piense en quién puede estar trabajando cerca de la calle.","h2":"Un abanderado que muestra el letrero SLOW significa que usted debe bajar la velocidad y seguir con cuidado, porque puede haber trabajadores y máquinas cerca de la calle.","p":"Correcto. El letrero SLOW significa baje la velocidad y maneje con cuidado."},"zh":{"q":"在施工区，一名旗手举起一个写着 “SLOW”（慢行）的牌子。你应该怎么做？","o":["停车，等警察来","减速，小心往前开，注意工人","保持平常的速度","掉头另找一条路"],"h1":"想一想：谁可能在路边很近的地方工作。","h2":"旗手举着 “SLOW”（慢行）牌子，表示你应该减速，小心往前开，因为路边可能有工人和机械。","p":"对。“SLOW” 牌子表示减速，小心开车。"},"vi":{"q":"Trong khu vực thi công, người cầm biển điều khiển giao thông giơ biển ghi “SLOW” (Chạy chậm). Bạn nên làm gì?","o":["Dừng lại và chờ cảnh sát","Chạy chậm lại và đi tiếp cẩn thận, chú ý công nhân","Giữ tốc độ bình thường","Quay đầu và tìm đường khác"],"h1":"Hãy nghĩ xem ai có thể đang làm việc sát bên đường.","h2":"Người cầm biển giơ biển “SLOW” nghĩa là bạn cần chạy chậm lại và đi tiếp cẩn thận, vì công nhân và máy móc có thể ở gần đường.","p":"Đúng rồi. Biển “SLOW” nghĩa là chạy chậm lại và lái cẩn thận."},"tl":{"q":"Sa work zone, may flagger na nagtataas ng karatulang nakasulat ang “SLOW” (Bumagal). Ano ang dapat mong gawin?","o":["Huminto at maghintay ng pulis","Bumagal at magpatuloy nang maingat, habang nagbabantay sa mga trabahador","Panatilihin ang karaniwan mong bilis","Umikot pabalik at maghanap ng ibang daan"],"h1":"Isipin kung sino ang maaaring nagtatrabaho malapit sa kalsada.","h2":"Ang flagger na nagpapakita ng “SLOW” na karatula ay nangangahulugang dapat kang bumagal at magpatuloy nang maingat, dahil maaaring may mga trabahador at kagamitan malapit sa kalsada.","p":"Tama. Ang “SLOW” na paddle ay nangangahulugang bumagal at magmaneho nang maingat."},"ar":{"q":"في منطقة عمل، عامل تنظيم السير يرفع لافتة مكتوب عليها «SLOW» (ببطء). ماذا يجب أن تفعل؟","o":["توقف وانتظر شرطيًا","خفف السرعة وتابع بحذر، وانتبه للعمال","حافظ على سرعتك العادية","استدر عائدًا وابحث عن طريق آخر"],"h1":"فكّر في من قد يعمل قريبًا من الطريق.","h2":"عندما يُظهر عامل تنظيم السير لافتة «SLOW»، يجب أن تخفف السرعة وتتابع بحذر، لأن العمال والمعدات قد يكونون قرب الطريق.","p":"صحيح. لوحة «SLOW» تعني: خفف السرعة وقُد بحذر."},"ht":{"q":"Nan yon zòn travay, yon travayè ki dirije trafik la leve yon pankat ki di “SLOW” (ralanti). Kisa ou dwe fè?","o":["Kanpe epi tann yon polis","Ralanti epi kontinye avèk prekosyon, pandan w ap veye travayè yo","Kenbe vitès nòmal ou","Vire tounen epi chèche yon lòt wout"],"h1":"Panse ak kiyès ki ka ap travay toupre wout la.","h2":"Yon travayè ki montre yon pankat “SLOW” vle di ou dwe ralanti epi kontinye avèk prekosyon, paske ka gen travayè ak machin travay toupre wout la.","p":"Se sa. Yon pankat “SLOW” vle di ralanti epi kondui avèk prekosyon."},"ref":{"doc":"FL","page":54}},{"id":"signals-036","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"A flagger in a work zone holds up a STOP sign, but the traffic light ahead is green. What should you do?","o":["Follow the green light and go","Slow down but keep moving","Pass the flagger on the shoulder","Stop and wait until the flagger lets you go"],"h1":"Think about who is in charge of traffic in a work zone.","h2":"You must obey a flagger in a work zone, so you stop when the flagger shows STOP, even if a traffic light is green.","p":"Right. A flagger’s STOP sign comes before a green light."},"es":{"q":"Un abanderado en una zona de trabajo levanta un letrero de STOP (pare), pero el semáforo de adelante está en verde. ¿Qué debe hacer?","o":["Seguir la luz verde y pasar","Bajar la velocidad pero seguir","Pasar al abanderado por el paseo","Parar y esperar hasta que el abanderado le deje pasar"],"h1":"Piense quién dirige el tráfico en una zona de trabajo.","h2":"Usted debe obedecer al abanderado en una zona de trabajo, así que para cuando el abanderado muestra STOP, aunque el semáforo esté en verde.","p":"Correcto. El letrero STOP del abanderado va antes que la luz verde."},"zh":{"q":"施工区的一名旗手举起 “STOP”（停）牌子，但前面的红绿灯是绿灯。你应该怎么做？","o":["按绿灯开走","减速但继续开","从路肩超过旗手","停车，等旗手让你走"],"h1":"想一想：在施工区里是谁在管交通。","h2":"在施工区你必须服从旗手，所以旗手举起 “STOP” 时你要停车，就算红绿灯是绿灯也一样。","p":"对。旗手的 “STOP” 牌子比绿灯优先。"},"vi":{"q":"Người cầm biển trong khu vực thi công giơ biển “STOP”, nhưng đèn giao thông phía trước đang xanh. Bạn nên làm gì?","o":["Làm theo đèn xanh và đi","Chạy chậm lại nhưng vẫn tiếp tục chạy","Vượt qua người cầm biển bằng lề đường","Dừng lại và chờ tới khi người cầm biển cho bạn đi"],"h1":"Hãy nghĩ xem ai là người điều khiển giao thông trong khu vực thi công.","h2":"Bạn phải làm theo người cầm biển trong khu vực thi công, nên bạn dừng lại khi người đó giơ biển “STOP”, kể cả khi đèn giao thông đang xanh.","p":"Đúng rồi. Biển “STOP” của người cầm biển được ưu tiên hơn đèn xanh."},"tl":{"q":"May flagger sa work zone na nagtataas ng “STOP” na karatula, pero berde ang ilaw trapiko sa unahan. Ano ang dapat mong gawin?","o":["Sundin ang berdeng ilaw at umandar","Bumagal pero magpatuloy sa pag-andar","Lampasan ang flagger sa gilid ng kalsada","Huminto at maghintay hanggang payagan ka ng flagger na umandar"],"h1":"Isipin kung sino ang namamahala sa trapiko sa work zone.","h2":"Dapat mong sundin ang flagger sa work zone, kaya huminto ka kapag ipinakita ng flagger ang “STOP”, kahit berde pa ang ilaw trapiko.","p":"Tama. Mas nauuna ang “STOP” na karatula ng flagger kaysa sa berdeng ilaw."},"ar":{"q":"عامل تنظيم السير في منطقة عمل يرفع لافتة «STOP» (قف)، لكن إشارة المرور أمامك خضراء. ماذا يجب أن تفعل؟","o":["اتبع الضوء الأخضر وانطلق","خفف السرعة لكن استمر في التحرك","تجاوز العامل من كتف الطريق","توقف وانتظر حتى يسمح لك العامل بالمرور"],"h1":"فكّر في من المسؤول عن السير في منطقة العمل.","h2":"يجب أن تطيع عامل تنظيم السير في منطقة العمل، لذلك تتوقف عندما يُظهر العامل «STOP»، حتى لو كانت إشارة المرور خضراء.","p":"صحيح. لافتة «STOP» التي يحملها العامل تأتي قبل الضوء الأخضر."},"ht":{"q":"Yon travayè ki dirije trafik nan yon zòn travay leve yon pankat “STOP”, men limyè trafik devan an vèt. Kisa ou dwe fè?","o":["Swiv limyè vèt la epi pase","Ralanti men kontinye avanse","Pase bò kote travayè a sou arebò wout la","Kanpe epi tann jiskaske travayè a kite ou pase"],"h1":"Panse ak kiyès ki responsab trafik la nan yon zòn travay.","h2":"Ou dwe obeyi travayè ki dirije trafik nan yon zòn travay, kidonk ou kanpe lè li montre “STOP”, menm si yon limyè trafik vèt.","p":"Se sa. Pankat “STOP” travayè a pase anvan yon limyè vèt."},"ref":{"doc":"FL","page":54}},{"id":"signals-037","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"Which should you obey first: a traffic light, a stop sign, or a police officer directing traffic?","o":["The police officer","The traffic light","The stop sign","Whichever is closest to you"],"h1":"Signs and lights are set ahead of time. Think about who can react to what is happening now.","h2":"A police officer directing traffic comes first, before any traffic light or sign, because the officer is handling what is happening right now.","p":"Right. An officer directing traffic comes before lights and signs."},"es":{"q":"¿A quién debe obedecer primero: a un semáforo, a una señal de pare o a un policía que dirige el tráfico?","o":["Al policía","Al semáforo","A la señal de pare","Al que esté más cerca de usted"],"h1":"Las señales y los semáforos se ponen con anticipación. Piense quién puede reaccionar a lo que pasa ahora.","h2":"Un policía que dirige el tráfico va primero, antes que cualquier semáforo o señal, porque el policía maneja lo que está pasando en ese momento.","p":"Correcto. Un policía que dirige el tráfico va antes que los semáforos y las señales."},"zh":{"q":"红绿灯、停车标志、指挥交通的警察，你应该先服从哪一个？","o":["警察","红绿灯","停车标志","离你最近的那一个"],"h1":"标志和灯是提前设定好的。想一想谁能对眼前发生的事做出反应。","h2":"指挥交通的警察最优先，比任何红绿灯或标志都优先，因为警察在处理眼前正在发生的情况。","p":"对。指挥交通的警察比灯和标志优先。"},"vi":{"q":"Bạn nên làm theo điều nào trước tiên: đèn giao thông, biển dừng, hay cảnh sát đang điều khiển giao thông?","o":["Cảnh sát","Đèn giao thông","Biển dừng","Cái nào gần bạn nhất"],"h1":"Biển và đèn được cài đặt từ trước. Hãy nghĩ xem ai có thể phản ứng với điều đang xảy ra ngay lúc này.","h2":"Cảnh sát đang điều khiển giao thông được ưu tiên trước, hơn mọi đèn giao thông hay biển báo, vì cảnh sát đang xử lý điều đang xảy ra ngay lúc đó.","p":"Đúng rồi. Cảnh sát điều khiển giao thông được ưu tiên hơn đèn và biển báo."},"tl":{"q":"Alin ang dapat mong unang sundin: ang ilaw trapiko, ang “STOP” sign, o ang pulis na nagdidirekta ng trapiko?","o":["Ang pulis","Ang ilaw trapiko","Ang “STOP” sign","Kung alin ang pinakamalapit sa iyo"],"h1":"Ang mga karatula at ilaw ay nakatakda na nang maaga. Isipin kung sino ang nakakatugon sa nangyayari ngayon.","h2":"Ang pulis na nagdidirekta ng trapiko ang nauuna, bago ang anumang ilaw trapiko o karatula, dahil hinaharap ng pulis ang nangyayari mismo sa sandaling iyon.","p":"Tama. Mas nauuna ang pulis na nagdidirekta ng trapiko kaysa sa mga ilaw at karatula."},"ar":{"q":"أيها يجب أن تطيع أولًا: إشارة المرور، أم لافتة «STOP» (قف)، أم شرطي ينظّم السير؟","o":["الشرطي","إشارة المرور","لافتة «STOP»","أيها أقرب إليك"],"h1":"اللافتات والإشارات مضبوطة مسبقًا. فكّر في من يستطيع أن يتصرف حسب ما يحدث الآن.","h2":"الشرطي الذي ينظّم السير يأتي أولًا، قبل أي إشارة مرور أو لافتة، لأنه يتعامل مع ما يحدث الآن.","p":"صحيح. الشرطي الذي ينظّم السير يأتي قبل الإشارات واللافتات."},"ht":{"q":"Kiyès ou dwe obeyi anvan: yon limyè trafik, yon siy “STOP”, oswa yon polis k ap dirije trafik?","o":["Polis la","Limyè trafik la","Siy “STOP” la","Sa ki pi pre ou a"],"h1":"Siy ak limyè yo regle davans. Panse ak kiyès ki ka reyaji ak sa k ap pase kounye a.","h2":"Yon polis k ap dirije trafik pase anvan, devan nenpòt limyè trafik oswa siy, paske polis la ap jere sa k ap pase kounye a menm.","p":"Se sa. Yon polis k ap dirije trafik pase anvan limyè ak siy yo."},"ref":{"doc":"FL","page":51}},{"id":"signals-038","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"On a divided highway, what color is the solid line along the left edge of your lanes?","o":["White","Blue","Yellow","Red"],"h1":"Think about which color is used for the side closest to traffic going the other way.","h2":"On a divided highway, the left edge line is yellow and the right edge line is white, which helps you see the side toward opposite traffic.","p":"Right. The left edge line is yellow; the right edge line is white."},"es":{"q":"En una autopista dividida, ¿de qué color es la línea continua del borde izquierdo de sus carriles?","o":["Blanca","Azul","Amarilla","Roja"],"h1":"Piense qué color se usa para el lado más cerca del tráfico que va en sentido contrario.","h2":"En una autopista dividida, la línea del borde izquierdo es amarilla y la del borde derecho es blanca, lo que le ayuda a ver el lado del tráfico contrario.","p":"Correcto. La línea del borde izquierdo es amarilla; la del derecho es blanca."},"zh":{"q":"在分隔公路上，你的车道左边缘的实线是什么颜色？","o":["白色","蓝色","黄色","红色"],"h1":"想一想：靠近对向车流的那一边用什么颜色。","h2":"在分隔公路上，左边缘线是黄色，右边缘线是白色，这能帮你看清哪一边靠近对向车流。","p":"对。左边缘线是黄色，右边缘线是白色。"},"vi":{"q":"Trên đường có dải phân cách, vạch liền dọc theo mép trái các làn của bạn có màu gì?","o":["Trắng","Xanh dương","Vàng","Đỏ"],"h1":"Hãy nghĩ xem màu nào được dùng cho phía gần xe chạy ngược chiều nhất.","h2":"Trên đường có dải phân cách, vạch mép trái màu vàng và vạch mép phải màu trắng, giúp bạn nhận ra phía có xe chạy ngược chiều.","p":"Đúng rồi. Vạch mép trái màu vàng; vạch mép phải màu trắng."},"tl":{"q":"Sa divided highway, anong kulay ang tuloy-tuloy na linya sa kaliwang gilid ng mga lane mo?","o":["Puti","Asul","Dilaw","Pula"],"h1":"Isipin kung aling kulay ang ginagamit para sa bahaging pinakamalapit sa trapikong papunta sa kabilang direksyon.","h2":"Sa divided highway, dilaw ang linya sa kaliwang gilid at puti ang linya sa kanang gilid, na tumutulong sa iyo na makita ang bahaging nakaharap sa kasalungat na trapiko.","p":"Tama. Dilaw ang linya sa kaliwang gilid; puti ang linya sa kanang gilid."},"ar":{"q":"في طريق سريع مقسوم، ما لون الخط المتصل على الحافة اليسرى لمساراتك؟","o":["أبيض","أزرق","أصفر","أحمر"],"h1":"فكّر في اللون الذي يُستخدم للجانب الأقرب إلى السيارات التي تسير في الاتجاه الآخر.","h2":"في الطريق السريع المقسوم، خط الحافة اليسرى أصفر وخط الحافة اليمنى أبيض، وهذا يساعدك على رؤية الجانب القريب من السيارات المعاكسة.","p":"صحيح. خط الحافة اليسرى أصفر، وخط الحافة اليمنى أبيض."},"ht":{"q":"Sou yon wout ki gen separasyon, ki koulè liy plen ki sou bò goch koulwa ou yo?","o":["Blan","Ble","Jòn","Wouj"],"h1":"Panse ak ki koulè yo sèvi pou bò ki pi pre machin k ap ale nan lòt direksyon an.","h2":"Sou yon wout ki gen separasyon, liy bò goch la jòn epi liy bò dwat la blan, sa ki ede ou wè bò ki vire sou machin k ap ale nan direksyon opoze a.","p":"Se sa. Liy bò goch la jòn; liy bò dwat la blan."},"ref":{"doc":"FL","page":43}},{"id":"signs-001","scope":"US","cat":"signs","sign":{"shape":"stop","text":"STOP"},"c":0,"en":{"q":"A red sign has eight sides. What must you do?","o":["Stop fully, then go when it is safe","Slow down, and stop only if cars come","Get ready for road work ahead","Watch for a school zone ahead"],"h1":"Think about the only sign with eight sides.","h2":"An eight-sided red sign is a stop sign, so you must come to a full stop and go only when the way is clear.","p":"Right. Eight sides means stop fully, then go when safe."},"es":{"q":"Una señal roja tiene ocho lados. ¿Qué debe hacer?","o":["Pararse por completo y seguir cuando sea seguro","Bajar la velocidad y pararse solo si vienen carros","Prepararse para obras en la vía","Estar atento a una zona escolar"],"h1":"Piense en la única señal que tiene ocho lados.","h2":"Una señal roja de ocho lados es la señal de pare, así que usted debe pararse por completo y seguir solo cuando el camino esté libre.","p":"Correcto. Ocho lados significa pararse por completo y seguir cuando sea seguro."},"zh":{"q":"一个红色标志有八条边。你必须怎么做？","o":["完全停车，安全时再走","减速，只有来车时才停","准备好，前方有道路施工","注意，前方有学校区"],"h1":"想一想：只有一种标志有八条边。","h2":"八边形的红色标志是停车标志，所以你必须完全停车，路上没有车和人时才能走。","p":"对。八条边表示完全停车，安全时再走。"},"vi":{"q":"Một biển báo màu đỏ có tám cạnh. Bạn phải làm gì?","o":["Dừng hẳn, rồi đi khi an toàn","Chạy chậm lại, và chỉ dừng nếu có xe tới","Chuẩn bị cho đoạn đường đang sửa phía trước","Chú ý khu vực trường học phía trước"],"h1":"Hãy nghĩ đến biển báo duy nhất có tám cạnh.","h2":"Biển báo đỏ có tám cạnh là biển “STOP” (Dừng lại), nên bạn phải dừng hẳn và chỉ đi khi đường đã trống.","p":"Đúng rồi. Tám cạnh nghĩa là dừng hẳn, rồi đi khi an toàn."},"tl":{"q":"May pulang karatula na may walong gilid. Ano ang dapat mong gawin?","o":["Huminto nang buo, saka umandar kapag ligtas na","Bumagal, at huminto lang kung may dumarating na sasakyan","Maghanda sa ginagawang kalsada sa unahan","Mag-ingat sa school zone sa unahan"],"h1":"Isipin ang nag-iisang karatula na may walong gilid.","h2":"Ang pulang karatula na may walong gilid ay “STOP” sign (Huminto), kaya dapat kang huminto nang buo at umandar lang kapag maluwag na ang daan.","p":"Tama. Ang walong gilid ay nangangahulugang huminto nang buo, saka umandar kapag ligtas."},"ar":{"q":"لافتة حمراء لها ثمانية أضلاع. ماذا يجب أن تفعل؟","o":["توقف تمامًا، ثم انطلق عندما يكون الطريق آمنًا","خفف السرعة، وتوقف فقط إذا جاءت سيارات","استعد لأعمال طرق في الأمام","انتبه لمنطقة مدرسة في الأمام"],"h1":"فكّر في اللافتة الوحيدة التي لها ثمانية أضلاع.","h2":"اللافتة الحمراء ذات الأضلاع الثمانية هي لافتة «STOP» (قف)، لذلك يجب أن تتوقف تمامًا ولا تنطلق إلا عندما يكون الطريق خاليًا.","p":"صحيح. ثمانية أضلاع تعني: توقف تمامًا، ثم انطلق عندما يكون الطريق آمنًا."},"ht":{"q":"Gen yon siy wouj ki gen uit kote. Kisa ou dwe fè?","o":["Kanpe nèt, epi pati lè sa an sekirite","Ralanti, epi kanpe sèlman si gen machin k ap vini","Prepare ou pou travay sou wout la pi devan","Veye yon zòn lekòl pi devan"],"h1":"Panse ak sèl siy ki gen uit kote a.","h2":"Yon siy wouj ki gen uit kote se yon siy “STOP” (kanpe), kidonk ou dwe kanpe nèt epi pati sèlman lè wout la lib.","p":"Se sa. Uit kote vle di kanpe nèt, epi pati lè sa an sekirite."},"ref":{"doc":"FL","page":47}},{"id":"signs-002","scope":"US","cat":"signs","sign":{"shape":"yield","text":"YIELD"},"c":1,"en":{"q":"What does a red and white triangle pointing down mean?","o":["Stop every time, even if the road is clear","Slow down, let others go first, stop if needed","Speed up so you can merge quickly","The road ends just ahead"],"h1":"This sign is about who goes first.","h2":"The upside-down triangle is a yield sign, so you slow down, let other traffic go first, and stop if you need to.","p":"Right. Yield means slow down and let others go first."},"es":{"q":"¿Qué significa un triángulo rojo y blanco con la punta hacia abajo?","o":["Pararse siempre, aunque la vía esté libre","Bajar la velocidad, dejar pasar a otros y parar si hace falta","Acelerar para entrar rápido al tráfico","La vía se termina más adelante"],"h1":"Esta señal trata de quién pasa primero.","h2":"El triángulo con la punta hacia abajo es la señal de ceda el paso, así que usted baja la velocidad, deja pasar a los demás y se para si hace falta.","p":"Correcto. Ceda el paso significa bajar la velocidad y dejar pasar a otros."},"zh":{"q":"一个尖角朝下的红白三角形标志是什么意思？","o":["每次都要停车，路上没车也要停","减速，让别人先走，需要时停车","加速，以便快速并道","道路就在前方结束"],"h1":"这个标志说的是谁先走。","h2":"倒三角形是让行标志，所以你要减速，让其他车先走，需要时停车。","p":"对。让行表示减速，让别人先走。"},"vi":{"q":"Biển hình tam giác đỏ trắng, mũi nhọn chỉ xuống, có nghĩa là gì?","o":["Lúc nào cũng phải dừng, dù đường trống","Chạy chậm lại, nhường người khác đi trước, dừng nếu cần","Tăng tốc để nhập làn cho nhanh","Con đường sắp hết ngay phía trước"],"h1":"Biển này nói về việc ai được đi trước.","h2":"Tam giác chỉ xuống là biển “YIELD” (Nhường đường), nên bạn chạy chậm lại, để xe khác đi trước, và dừng nếu cần.","p":"Đúng rồi. Nhường đường nghĩa là chạy chậm lại và để người khác đi trước."},"tl":{"q":"Ano ang ibig sabihin ng pula at puting tatsulok na nakaturo pababa?","o":["Huminto palagi, kahit maluwag ang daan","Bumagal, paunahin ang iba, huminto kung kailangan","Bumilis para mabilis kang makasingit","Matatapos na ang kalsada sa unahan"],"h1":"Ang karatulang ito ay tungkol sa kung sino ang mauuna.","h2":"Ang baligtad na tatsulok ay “YIELD” sign (Magbigay-daan), kaya babagal ka, paunahin mo ang ibang sasakyan, at huminto ka kung kailangan.","p":"Tama. Ang “YIELD” ay nangangahulugang bumagal at paunahin ang iba."},"ar":{"q":"ماذا يعني مثلث أحمر وأبيض رأسه إلى الأسفل؟","o":["توقف في كل مرة، حتى لو كان الطريق خاليًا","خفف السرعة، ودع الآخرين يمرون أولًا، وتوقف إذا لزم الأمر","زد السرعة لكي تندمج بسرعة","الطريق ينتهي بعد قليل"],"h1":"هذه اللافتة تتعلق بمن يمر أولًا.","h2":"المثلث المقلوب هو لافتة «YIELD» (أعطِ الأولوية)، لذلك تخفف السرعة، وتترك السيارات الأخرى تمر أولًا، وتتوقف إذا احتجت إلى ذلك.","p":"صحيح. «YIELD» تعني: خفف السرعة ودع الآخرين يمرون أولًا."},"ht":{"q":"Kisa yon triyang wouj ak blan ki gen pwent li anba vle di?","o":["Kanpe chak fwa, menm si wout la lib","Ralanti, kite lòt yo pase anvan, kanpe si sa nesesè","Akselere pou ou ka antre vit","Wout la fini touprè"],"h1":"Siy sa a pale de kiyès ki pase anvan.","h2":"Triyang ki tèt anba a se yon siy “YIELD” (bay pasaj), kidonk ou ralanti, ou kite lòt machin yo pase anvan, epi ou kanpe si ou bezwen.","p":"Se sa. “YIELD” vle di ralanti epi kite lòt yo pase anvan."},"ref":{"doc":"FL","page":47}},{"id":"signs-003","scope":"US","cat":"signs","sign":{"shape":"school","text":"SCHOOL"},"c":2,"en":{"q":"What does a sign with five sides warn you about?","o":["A railroad crossing ahead","A hospital nearby","A school zone or school crossing","A no-passing zone"],"h1":"Think about who you may see walking near this sign.","h2":"A five-sided sign marks a school zone or a school crossing, so you should slow down and watch for children.","p":"Right. Five sides means a school is near."},"es":{"q":"¿Sobre qué le avisa una señal de cinco lados?","o":["Un cruce de tren más adelante","Un hospital cerca","Una zona escolar o un cruce escolar","Una zona donde no se puede rebasar"],"h1":"Piense en quiénes podrían caminar cerca de esta señal.","h2":"Una señal de cinco lados marca una zona escolar o un cruce escolar, así que usted debe bajar la velocidad y estar atento a los niños.","p":"Correcto. Cinco lados significa que hay una escuela cerca."},"zh":{"q":"有五条边的标志提醒你注意什么？","o":["前方有铁路道口","附近有医院","学校区或学校人行横道","禁止超车区"],"h1":"想一想：你在这个标志附近可能看到谁在走路。","h2":"五边形标志表示学校区或学校人行横道，所以你要减速，注意儿童。","p":"对。五条边表示附近有学校。"},"vi":{"q":"Biển báo có năm cạnh cảnh báo bạn về điều gì?","o":["Có chỗ băng qua đường sắt phía trước","Có bệnh viện gần đây","Khu vực trường học hoặc chỗ học sinh qua đường","Khu vực cấm vượt"],"h1":"Hãy nghĩ xem ai có thể đang đi bộ gần biển này.","h2":"Biển có năm cạnh báo hiệu khu vực trường học hoặc chỗ học sinh qua đường, nên bạn cần chạy chậm lại và chú ý trẻ em.","p":"Đúng rồi. Năm cạnh nghĩa là gần trường học."},"tl":{"q":"Tungkol saan ang babala ng karatula na may limang gilid?","o":["Tawiran ng tren sa unahan","May ospital sa malapit","School zone o tawiran ng mga estudyante","Lugar na bawal mag-overtake"],"h1":"Isipin kung sino ang maaaring makita mong naglalakad malapit sa karatulang ito.","h2":"Ang karatula na may limang gilid ay nagmamarka ng school zone o tawiran ng mga estudyante, kaya dapat kang bumagal at mag-ingat sa mga bata.","p":"Tama. Ang limang gilid ay nangangahulugang may paaralan sa malapit."},"ar":{"q":"ممّ تحذّرك لافتة لها خمسة أضلاع؟","o":["من تقاطع مع سكة حديد في الأمام","من مستشفى قريب","من منطقة مدرسة أو معبر مدرسة","من منطقة ممنوع فيها التجاوز"],"h1":"فكّر في من قد تراه يمشي قرب هذه اللافتة.","h2":"اللافتة ذات الأضلاع الخمسة تدل على منطقة مدرسة أو معبر مدرسة، لذلك يجب أن تخفف السرعة وتنتبه للأطفال.","p":"صحيح. خمسة أضلاع تعني أن هناك مدرسة قريبة."},"ht":{"q":"Yon siy ki gen senk kote avèti ou pou kisa?","o":["Yon kote tren travèse pi devan","Yon lopital touprè","Yon zòn lekòl oswa yon kote timoun lekòl travèse","Yon zòn kote ou pa ka double"],"h1":"Panse ak kiyès ou ka wè k ap mache toupre siy sa a.","h2":"Yon siy ki gen senk kote make yon zòn lekòl oswa yon kote timoun lekòl travèse, kidonk ou dwe ralanti epi veye timoun yo.","p":"Se sa. Senk kote vle di gen yon lekòl toupre."},"ref":{"doc":"FL","page":57}},{"id":"signs-004","scope":"US","cat":"signs","sign":{"shape":"rr-advance","text":"RR"},"c":3,"en":{"q":"What does a round yellow sign with an X and two R letters mean?","o":["A traffic circle is ahead","A bus stop is ahead","A rest area is ahead","A railroad crossing is ahead"],"h1":"The two letters stand for a kind of track.","h2":"The round yellow sign warns that a railroad crossing is ahead, so you should slow down, look, listen, and be ready to stop.","p":"Right. The round yellow sign warns of a railroad crossing ahead."},"es":{"q":"¿Qué significa una señal amarilla y redonda con una X y dos letras R?","o":["Hay una rotonda más adelante","Hay una parada de autobús más adelante","Hay un área de descanso más adelante","Hay un cruce de tren más adelante"],"h1":"Las dos letras se refieren a un tipo de vía.","h2":"La señal amarilla y redonda avisa que hay un cruce de tren más adelante, así que usted debe bajar la velocidad, mirar, escuchar y estar listo para parar.","p":"Correcto. La señal amarilla y redonda avisa de un cruce de tren."},"zh":{"q":"一个黄色圆形标志，上面有一个 X 和两个字母 R，是什么意思？","o":["前方有环形交叉路口","前方有公交车站","前方有休息区","前方有铁路道口"],"h1":"这两个字母代表一种轨道。","h2":"黄色圆形标志提醒你前方有铁路道口，所以你要减速，看一看，听一听，准备停车。","p":"对。黄色圆形标志提醒你前方有铁路道口。"},"vi":{"q":"Biển tròn màu vàng có chữ X và hai chữ R có nghĩa là gì?","o":["Phía trước có vòng xuyến","Phía trước có trạm xe buýt","Phía trước có trạm dừng nghỉ","Phía trước có chỗ băng qua đường sắt"],"h1":"Hai chữ cái này nói về một loại đường ray.","h2":"Biển tròn màu vàng cảnh báo phía trước có chỗ băng qua đường sắt, nên bạn cần chạy chậm lại, nhìn, nghe, và sẵn sàng dừng.","p":"Đúng rồi. Biển tròn màu vàng cảnh báo phía trước có đường sắt."},"tl":{"q":"Ano ang ibig sabihin ng bilog na dilaw na karatula na may X at dalawang letrang R?","o":["May rotonda sa unahan","May hintuan ng bus sa unahan","May pahingahan sa unahan","May tawiran ng tren sa unahan"],"h1":"Ang dalawang letra ay tumutukoy sa isang uri ng riles.","h2":"Ang bilog na dilaw na karatula ay babala na may tawiran ng tren sa unahan, kaya dapat kang bumagal, tumingin, makinig, at maging handang huminto.","p":"Tama. Ang bilog na dilaw na karatula ay babala na may tawiran ng tren sa unahan."},"ar":{"q":"ماذا تعني لافتة صفراء مستديرة عليها حرف X وحرفا R؟","o":["دوّار مروري في الأمام","موقف حافلات في الأمام","استراحة في الأمام","تقاطع مع سكة حديد في الأمام"],"h1":"الحرفان يرمزان إلى نوع من القضبان.","h2":"اللافتة الصفراء المستديرة تحذّر من تقاطع مع سكة حديد في الأمام، لذلك يجب أن تخفف السرعة، وتنظر، وتستمع، وتستعد للتوقف.","p":"صحيح. اللافتة الصفراء المستديرة تحذّر من تقاطع مع سكة حديد في الأمام."},"ht":{"q":"Kisa yon siy jòn won ki gen yon X ak de lèt R vle di?","o":["Gen yon wonpwen pi devan","Gen yon arè bis pi devan","Gen yon zòn repo pi devan","Gen yon kote tren travèse pi devan"],"h1":"De lèt yo kanpe pou yon kalite ray.","h2":"Siy jòn won an avèti ou gen yon kote tren travèse pi devan, kidonk ou dwe ralanti, gade, koute, epi pare pou kanpe.","p":"Se sa. Siy jòn won an avèti ou gen yon kote tren travèse pi devan."},"ref":{"doc":"FL","page":56}},{"id":"signs-005","scope":"US","cat":"signs","sign":{"shape":"crossbuck","text":"RAILROAD CROSSING"},"c":0,"en":{"q":"At the tracks you see a white X-shaped sign. What should you do?","o":["Treat it like a yield sign and look for trains","Speed up to get across the tracks fast","Change lanes before you reach the tracks","Ignore it unless it is dark outside"],"h1":"Think about what could be coming down the tracks.","h2":"The white X sign is a railroad crossbuck, and it works like a yield sign, so you slow down, look both ways, and stop if a train is coming.","p":"Right. The crossbuck means yield to trains."},"es":{"q":"En la vía del tren ve una señal blanca en forma de X. ¿Qué debe hacer?","o":["Tratarla como un ceda el paso y buscar trenes","Acelerar para cruzar la vía rápido","Cambiar de carril antes de la vía","No hacerle caso a menos que sea de noche"],"h1":"Piense en lo que podría venir por la vía.","h2":"La señal blanca en forma de X es la cruz de ferrocarril, y funciona como un ceda el paso, así que usted baja la velocidad, mira a ambos lados y se para si viene un tren.","p":"Correcto. La cruz de ferrocarril significa ceder el paso a los trenes."},"zh":{"q":"在铁轨旁，你看到一个白色 X 形标志。你应该怎么做？","o":["把它当作让行标志，注意火车","加速，快快穿过铁轨","到铁轨前先换车道","不用管它，除非天黑"],"h1":"想一想：铁轨上可能开来什么。","h2":"白色 X 形标志是铁路交叉标志，它的作用和让行标志一样，所以你要减速，看两边，如果有火车开来就停车。","p":"对。铁路交叉标志表示给火车让行。"},"vi":{"q":"Tại đường ray, bạn thấy một biển màu trắng hình chữ X. Bạn nên làm gì?","o":["Làm như gặp biển nhường đường và nhìn xem có tàu không","Tăng tốc để qua đường ray thật nhanh","Đổi làn trước khi tới đường ray","Bỏ qua biển, trừ khi trời tối"],"h1":"Hãy nghĩ xem cái gì có thể đang chạy tới trên đường ray.","h2":"Biển chữ X màu trắng là biển báo đường sắt (crossbuck), và nó giống như biển nhường đường, nên bạn chạy chậm lại, nhìn cả hai phía, và dừng nếu có tàu đang tới.","p":"Đúng rồi. Biển chữ X nghĩa là phải nhường đường cho tàu."},"tl":{"q":"Sa may riles, may nakita kang puting karatula na hugis X. Ano ang dapat mong gawin?","o":["Ituring itong parang “YIELD” sign at tumingin kung may tren","Bumilis para mabilis na makatawid sa riles","Lumipat ng linya bago ka umabot sa riles","Huwag pansinin maliban kung madilim na"],"h1":"Isipin kung ano ang puwedeng dumaan sa riles.","h2":"Ang puting karatulang X ay tinatawag na crossbuck ng riles, at gumagana ito na parang “YIELD” sign, kaya babagal ka, titingin sa magkabilang direksyon, at hihinto kung may paparating na tren.","p":"Tama. Ang crossbuck ay nangangahulugang magbigay-daan sa tren."},"ar":{"q":"عند سكة الحديد ترى لافتة بيضاء على شكل حرف X. ماذا يجب أن تفعل؟","o":["تعامل معها مثل لافتة إعطاء الأولوية وانظر هل يأتي قطار","زد السرعة لتعبر السكة بسرعة","غيّر المسار قبل أن تصل إلى السكة","تجاهلها إلا إذا كان الجو مظلمًا"],"h1":"فكّر في ما قد يأتي على السكة.","h2":"اللافتة البيضاء على شكل X هي علامة تقاطع سكة الحديد، وهي تعمل مثل لافتة إعطاء الأولوية، لذلك تخفف السرعة، وتنظر في الاتجاهين، وتتوقف إذا كان قطار قادمًا.","p":"صحيح. علامة X عند السكة تعني: أعطِ الأولوية للقطارات."},"ht":{"q":"Bò ray tren an, ou wè yon siy blan ki gen fòm yon X. Kisa ou dwe fè?","o":["Fè l tankou yon siy “YIELD” epi gade si gen tren","Akselere pou travèse ray yo vit","Chanje koulwa anvan ou rive nan ray yo","Pa okipe l sof si fè nwa deyò"],"h1":"Panse ak sa ki ka ap vini sou ray yo.","h2":"Siy blan an fòm X la se yon kwa tren (crossbuck), e li mache tankou yon siy “YIELD”, kidonk ou ralanti, ou gade de bò yo, epi ou kanpe si gen yon tren k ap vini.","p":"Se sa. Kwa tren an vle di bay tren yo pasaj."},"ref":{"doc":"FL","page":56}},{"id":"signs-006","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow"},"c":1,"en":{"q":"What does a yellow diamond-shaped sign usually do?","o":["Gives you directions to a city","Warns you about a hazard or change ahead","Tells you the speed limit","Shows you a place to eat"],"h1":"Think about why a sign would use a bright yellow color.","h2":"A yellow diamond is a warning sign, so it tells you about a hazard or a change in the road ahead.","p":"Right. A yellow diamond warns you about something ahead."},"es":{"q":"¿Qué hace normalmente una señal amarilla en forma de rombo?","o":["Le da direcciones hacia una ciudad","Le avisa de un peligro o un cambio más adelante","Le dice el límite de velocidad","Le muestra un lugar para comer"],"h1":"Piense en por qué una señal usaría un amarillo fuerte.","h2":"Un rombo amarillo es una señal de advertencia, así que le avisa de un peligro o de un cambio en la vía más adelante.","p":"Correcto. Un rombo amarillo le avisa de algo más adelante."},"zh":{"q":"黄色菱形标志通常有什么作用？","o":["告诉你去某个城市的方向","提醒你前方有危险或变化","告诉你限速","告诉你哪里可以吃饭"],"h1":"想一想：标志为什么要用很亮的黄色。","h2":"黄色菱形标志是警告标志，它告诉你前方道路有危险或变化。","p":"对。黄色菱形标志提醒你注意前方。"},"vi":{"q":"Biển hình thoi màu vàng thường dùng để làm gì?","o":["Chỉ đường tới một thành phố","Cảnh báo nguy hiểm hoặc thay đổi phía trước","Cho biết tốc độ tối đa","Chỉ chỗ ăn uống"],"h1":"Hãy nghĩ xem vì sao một biển báo lại dùng màu vàng tươi.","h2":"Biển hình thoi màu vàng là biển cảnh báo, nên nó cho bạn biết có nguy hiểm hoặc đường thay đổi ở phía trước.","p":"Đúng rồi. Biển hình thoi màu vàng cảnh báo điều gì đó phía trước."},"tl":{"q":"Ano ang karaniwang ginagawa ng dilaw na karatula na hugis diyamante?","o":["Nagbibigay ng direksyon papunta sa isang lungsod","Nagbababala tungkol sa panganib o pagbabago sa unahan","Nagsasabi ng speed limit","Nagpapakita ng lugar na makakainan"],"h1":"Isipin kung bakit gagamit ang karatula ng matingkad na dilaw na kulay.","h2":"Ang dilaw na diyamante ay karatula ng babala, kaya sinasabi nito sa iyo na may panganib o pagbabago sa kalsada sa unahan.","p":"Tama. Ang dilaw na diyamante ay nagbababala tungkol sa isang bagay sa unahan."},"ar":{"q":"ما الذي تفعله عادةً لافتة صفراء على شكل معيّن (ماسة)؟","o":["تعطيك الاتجاه إلى مدينة","تحذّرك من خطر أو تغيير في الأمام","تخبرك بالحد الأقصى للسرعة","تدلّك على مكان للأكل"],"h1":"فكّر لماذا تستخدم اللافتة لونًا أصفر لامعًا.","h2":"المعيّن الأصفر هو لافتة تحذير، فهو يخبرك بوجود خطر أو تغيير في الطريق أمامك.","p":"صحيح. المعيّن الأصفر يحذّرك من شيء في الأمام."},"ht":{"q":"Kisa yon siy jòn ki gen fòm dyaman (lozanj) konn fè?","o":["Li ba ou direksyon pou yon vil","Li avèti ou gen yon danje oswa yon chanjman pi devan","Li di ou limit vitès la","Li montre ou yon kote pou manje"],"h1":"Panse poukisa yon siy ta sèvi ak yon koulè jòn klè.","h2":"Yon dyaman jòn se yon siy avètisman, kidonk li di ou gen yon danje oswa yon chanjman sou wout la pi devan.","p":"Se sa. Yon dyaman jòn avèti ou pou yon bagay pi devan."},"ref":{"doc":"FL","page":49}},{"id":"signs-007","scope":"US","cat":"signs","sign":{"shape":"diamond-orange","text":"ROAD WORK AHEAD"},"c":2,"en":{"q":"Orange signs tell you about what?","o":["School zones","Parks and campgrounds","Road work and work zones","Gas and food"],"h1":"Think about where you see orange cones and workers.","h2":"Orange signs are used for road work and work zones, so you should slow down and watch for workers and changes.","p":"Right. Orange signs mean road work."},"es":{"q":"¿De qué le avisan las señales anaranjadas?","o":["De zonas escolares","De parques y campamentos","De obras y zonas de trabajo en la vía","De gasolina y comida"],"h1":"Piense en dónde ve conos anaranjados y trabajadores.","h2":"Las señales anaranjadas se usan para obras y zonas de trabajo en la vía, así que usted debe bajar la velocidad y estar atento a los trabajadores y a los cambios.","p":"Correcto. Las señales anaranjadas significan obras en la vía."},"zh":{"q":"橙色标志告诉你什么？","o":["学校区","公园和露营地","道路施工和施工区","加油和吃饭"],"h1":"想一想：你在哪里会看到橙色锥桶和工人。","h2":"橙色标志用于道路施工和施工区，所以你要减速，注意工人和道路变化。","p":"对。橙色标志表示道路施工。"},"vi":{"q":"Biển báo màu cam cho bạn biết về điều gì?","o":["Khu vực trường học","Công viên và khu cắm trại","Đường đang sửa và khu vực thi công","Xăng và đồ ăn"],"h1":"Hãy nghĩ xem bạn thấy cọc màu cam và công nhân ở đâu.","h2":"Biển màu cam dùng cho đường đang sửa và khu vực thi công, nên bạn cần chạy chậm lại và chú ý công nhân cùng những thay đổi trên đường.","p":"Đúng rồi. Biển màu cam nghĩa là đường đang sửa."},"tl":{"q":"Tungkol saan ang sinasabi ng mga karatulang kulay orange?","o":["Mga school zone","Mga parke at campground","Ginagawang kalsada at work zone","Gasolina at pagkain"],"h1":"Isipin kung saan mo nakikita ang mga orange na cone at mga trabahador.","h2":"Ang mga karatulang kulay orange ay ginagamit para sa ginagawang kalsada at work zone, kaya dapat kang bumagal at mag-ingat sa mga trabahador at mga pagbabago.","p":"Tama. Ang orange na karatula ay nangangahulugang may ginagawang kalsada."},"ar":{"q":"عن أي شيء تخبرك اللافتات البرتقالية؟","o":["مناطق المدارس","الحدائق وأماكن التخييم","أعمال الطرق ومناطق العمل","الوقود والطعام"],"h1":"فكّر في المكان الذي ترى فيه الأقماع البرتقالية والعمال.","h2":"اللافتات البرتقالية تُستخدم لأعمال الطرق ومناطق العمل، لذلك يجب أن تخفف السرعة وتنتبه للعمال وللتغييرات.","p":"صحيح. اللافتات البرتقالية تعني أعمال طرق."},"ht":{"q":"Siy zoranj yo pale ou de kisa?","o":["Zòn lekòl","Pak ak kan","Travay sou wout ak zòn travay","Gaz ak manje"],"h1":"Panse kote ou wè kòn zoranj ak travayè.","h2":"Siy zoranj yo sèvi pou travay sou wout ak zòn travay, kidonk ou dwe ralanti epi veye travayè yo ak chanjman yo.","p":"Se sa. Siy zoranj yo vle di gen travay sou wout la."},"ref":{"doc":"FL","page":46}},{"id":"signs-008","scope":"US","cat":"signs","sign":{"shape":"no-passing","text":"NO PASSING ZONE"},"c":3,"en":{"q":"What does a yellow sign shaped like a long, sideways triangle mean?","o":["A merge is ahead on the right","Trucks have the right of way","The road gets narrow ahead","A no-passing zone begins here"],"h1":"This is the only sign with this flag-like shape.","h2":"The sideways yellow triangle, called a pennant, means a no-passing zone begins, so you must not pass other cars here.","p":"Right. The pennant means no passing."},"es":{"q":"¿Qué significa una señal amarilla en forma de triángulo largo y acostado?","o":["Hay una incorporación más adelante a la derecha","Los camiones tienen el derecho de paso","La vía se hace angosta más adelante","Aquí empieza una zona donde no se puede rebasar"],"h1":"Es la única señal con esta forma de banderín.","h2":"El triángulo amarillo acostado, llamado banderín, significa que empieza una zona donde no se puede rebasar, así que usted no debe rebasar a otros carros aquí.","p":"Correcto. El banderín significa que no se puede rebasar."},"zh":{"q":"一个横着放的长三角形黄色标志是什么意思？","o":["右前方有车辆并入","卡车有优先通行权","前方道路变窄","这里开始是禁止超车区"],"h1":"只有这一种标志是这种小旗子的形状。","h2":"横着的黄色三角形叫三角旗标志，表示禁止超车区开始，所以你在这里不能超车。","p":"对。三角旗标志表示禁止超车。"},"vi":{"q":"Biển màu vàng hình tam giác dài, nằm ngang có nghĩa là gì?","o":["Phía trước có làn nhập vào bên phải","Xe tải được quyền đi trước","Đường hẹp lại phía trước","Khu vực cấm vượt bắt đầu từ đây"],"h1":"Đây là biển duy nhất có hình giống lá cờ này.","h2":"Biển tam giác vàng nằm ngang, gọi là biển cờ đuôi nheo, nghĩa là khu vực cấm vượt bắt đầu, nên bạn không được vượt xe khác ở đây.","p":"Đúng rồi. Biển cờ đuôi nheo nghĩa là cấm vượt."},"tl":{"q":"Ano ang ibig sabihin ng dilaw na karatula na hugis mahabang tatsulok na nakatagilid?","o":["May sasama sa daan mula sa kanan sa unahan","Ang mga trak ang may karapatang mauna","Kikitid ang kalsada sa unahan","Dito nagsisimula ang lugar na bawal mag-overtake"],"h1":"Ito lang ang karatula na may ganitong hugis na parang bandila.","h2":"Ang nakatagilid na dilaw na tatsulok, na tinatawag na pennant, ay nangangahulugang nagsisimula ang lugar na bawal mag-overtake, kaya hindi ka dapat lumampas sa ibang sasakyan dito.","p":"Tama. Ang pennant ay nangangahulugang bawal mag-overtake."},"ar":{"q":"ماذا تعني لافتة صفراء على شكل مثلث طويل مائل إلى الجانب؟","o":["اندماج طريق في الأمام من اليمين","الشاحنات لها حق المرور","الطريق يضيق في الأمام","هنا تبدأ منطقة ممنوع فيها التجاوز"],"h1":"هذه هي اللافتة الوحيدة التي لها هذا الشكل الذي يشبه العلم.","h2":"المثلث الأصفر المائل إلى الجانب يسمى «الراية»، وهو يعني أن منطقة ممنوع فيها التجاوز تبدأ هنا، لذلك يجب ألا تتجاوز السيارات الأخرى هنا.","p":"صحيح. الراية تعني ممنوع التجاوز."},"ht":{"q":"Kisa yon siy jòn ki gen fòm yon triyang long ki kouche vle di?","o":["Gen machin k ap antre sou bò dwat pi devan","Kamyon yo gen dwa pou pase anvan","Wout la vin pi etwat pi devan","Yon zòn kote ou pa ka double kòmanse la a"],"h1":"Se sèl siy ki gen fòm sa a, tankou yon ti drapo.","h2":"Triyang jòn ki kouche a, yo rele l fanyon, vle di yon zòn kote ou pa ka double kòmanse, kidonk ou pa dwe double lòt machin la a.","p":"Se sa. Fanyon an vle di ou pa ka double."},"ref":{"doc":"FL","page":48}},{"id":"signs-009","scope":"US","cat":"signs","sign":null,"c":0,"en":{"q":"On which side of the road is the no-passing pennant sign placed?","o":["The left side","The right side","Over the middle lane","Painted on the road"],"h1":"Think about where your eyes look when you plan to pass.","h2":"The no-passing pennant is placed on the left side of the road, because that is the side you look at when you think about passing.","p":"Right. The pennant is on the left side of the road."},"es":{"q":"¿En qué lado de la vía se pone la señal de banderín de no rebasar?","o":["En el lado izquierdo","En el lado derecho","Encima del carril del medio","Pintada en el pavimento"],"h1":"Piense hacia dónde mira cuando planea rebasar.","h2":"El banderín de no rebasar se pone en el lado izquierdo de la vía, porque ese es el lado que usted mira cuando piensa rebasar.","p":"Correcto. El banderín está en el lado izquierdo de la vía."},"zh":{"q":"禁止超车的三角旗标志放在道路的哪一边？","o":["左边","右边","中间车道的上方","画在路面上"],"h1":"想一想：你打算超车时，眼睛会看向哪一边。","h2":"禁止超车的三角旗标志放在道路的左边，因为你想超车时会看那一边。","p":"对。三角旗标志在道路的左边。"},"vi":{"q":"Biển cờ đuôi nheo cấm vượt được đặt ở bên nào của đường?","o":["Bên trái","Bên phải","Phía trên làn giữa","Được sơn trên mặt đường"],"h1":"Hãy nghĩ xem mắt bạn nhìn về phía nào khi định vượt xe.","h2":"Biển cờ đuôi nheo cấm vượt được đặt ở bên trái đường, vì đó là phía bạn nhìn khi nghĩ đến việc vượt xe.","p":"Đúng rồi. Biển cờ đuôi nheo nằm ở bên trái đường."},"tl":{"q":"Sa aling bahagi ng kalsada inilalagay ang pennant na karatula ng bawal mag-overtake?","o":["Sa kaliwang bahagi","Sa kanang bahagi","Sa ibabaw ng gitnang linya","Nakapinta sa kalsada"],"h1":"Isipin kung saan tumitingin ang mata mo kapag balak mong mag-overtake.","h2":"Ang pennant ng bawal mag-overtake ay inilalagay sa kaliwang bahagi ng kalsada, dahil iyon ang bahaging tinitingnan mo kapag iniisip mong mag-overtake.","p":"Tama. Ang pennant ay nasa kaliwang bahagi ng kalsada."},"ar":{"q":"على أي جانب من الطريق توضع لافتة الراية التي تمنع التجاوز؟","o":["على الجانب الأيسر","على الجانب الأيمن","فوق المسار الأوسط","مرسومة على الطريق"],"h1":"فكّر إلى أين تنظر عيناك عندما تخطط للتجاوز.","h2":"لافتة الراية التي تمنع التجاوز توضع على الجانب الأيسر من الطريق، لأنه الجانب الذي تنظر إليه عندما تفكر في التجاوز.","p":"صحيح. الراية توضع على الجانب الأيسر من الطريق."},"ht":{"q":"Sou ki bò wout la yo mete siy fanyon ki di ou pa ka double a?","o":["Bò goch","Bò dwat","Anwo koulwa ki nan mitan an","Penti sou wout la"],"h1":"Panse ki kote je ou gade lè ou vle double.","h2":"Siy fanyon an yo mete l sou bò goch wout la, paske se bò sa a ou gade lè ou panse pou double.","p":"Se sa. Fanyon an sou bò goch wout la."}},{"id":"signs-010","scope":"US","cat":"signs","sign":{"shape":"rect-white"},"c":1,"en":{"q":"A white rectangle sign with black letters usually shows what?","o":["A warning about a curve","A traffic law you must obey","Directions to a city","A place to camp"],"h1":"Think about signs like the speed limit sign.","h2":"White rectangle signs with black letters are regulatory signs, so they show a traffic law that you must obey.","p":"Right. White rectangle signs show rules you must follow."},"es":{"q":"¿Qué muestra normalmente una señal blanca y rectangular con letras negras?","o":["Un aviso de una curva","Una ley de tránsito que debe obedecer","Direcciones hacia una ciudad","Un lugar para acampar"],"h1":"Piense en señales como la del límite de velocidad.","h2":"Las señales blancas y rectangulares con letras negras son señales reglamentarias, así que muestran una ley de tránsito que usted debe obedecer.","p":"Correcto. Las señales blancas rectangulares muestran reglas que debe seguir."},"zh":{"q":"白色长方形、黑色字的标志通常表示什么？","o":["提醒你前方有弯道","你必须遵守的交通法规","去某个城市的方向","可以露营的地方"],"h1":"想一想限速标志这样的标志。","h2":"白色长方形、黑色字的标志是禁令和指示标志，它告诉你必须遵守的交通法规。","p":"对。白色长方形标志告诉你必须遵守的规定。"},"vi":{"q":"Biển hình chữ nhật màu trắng, chữ đen thường cho biết điều gì?","o":["Cảnh báo về khúc cua","Một luật giao thông bạn phải tuân theo","Đường đi tới một thành phố","Chỗ để cắm trại"],"h1":"Hãy nghĩ đến những biển như biển giới hạn tốc độ.","h2":"Biển chữ nhật màu trắng, chữ đen là biển quy định, nên nó cho biết một luật giao thông mà bạn phải tuân theo.","p":"Đúng rồi. Biển chữ nhật màu trắng cho biết luật bạn phải theo."},"tl":{"q":"Ano ang karaniwang ipinapakita ng puting parihabang karatula na may itim na letra?","o":["Babala tungkol sa kurba","Batas trapiko na dapat mong sundin","Direksyon papunta sa isang lungsod","Lugar na puwedeng mag-camping"],"h1":"Isipin ang mga karatula tulad ng karatula ng speed limit.","h2":"Ang puting parihabang karatula na may itim na letra ay karatula ng regulasyon, kaya nagpapakita ito ng batas trapiko na dapat mong sundin.","p":"Tama. Ang puting parihabang karatula ay nagpapakita ng mga patakarang dapat sundin."},"ar":{"q":"لافتة بيضاء مستطيلة بحروف سوداء، ماذا تُظهر عادةً؟","o":["تحذيرًا من منعطف","قانون مرور يجب أن تطيعه","الاتجاه إلى مدينة","مكانًا للتخييم"],"h1":"فكّر في لافتات مثل لافتة حد السرعة.","h2":"اللافتات البيضاء المستطيلة بالحروف السوداء هي لافتات تنظيمية، فهي تُظهر قانون مرور يجب أن تطيعه.","p":"صحيح. اللافتات البيضاء المستطيلة تُظهر قواعد يجب أن تتبعها."},"ht":{"q":"Yon siy blan ki gen fòm rektang ak lèt nwa, kisa li konn montre?","o":["Yon avètisman pou yon koub","Yon lwa trafik ou dwe respekte","Direksyon pou yon vil","Yon kote pou kanpe tant"],"h1":"Panse ak siy tankou siy limit vitès la.","h2":"Siy blan an rektang ak lèt nwa yo se siy règleman, kidonk yo montre yon lwa trafik ou dwe respekte.","p":"Se sa. Siy blan an rektang yo montre règ ou dwe swiv."},"ref":{"doc":"FL","page":46}},{"id":"signs-011","scope":"US","cat":"signs","sign":{"shape":"rect-green","text":"Orlando 25"},"c":2,"en":{"q":"What do green signs show you?","o":["Where the hospital is","Where road work starts","Directions and distances","Where a school zone is"],"h1":"Think about signs that help you find your way.","h2":"Green signs are guide signs, so they show directions, exits, and how far it is to places.","p":"Right. Green signs show directions and distances."},"es":{"q":"¿Qué le muestran las señales verdes?","o":["Dónde está el hospital","Dónde empiezan las obras","Direcciones y distancias","Dónde hay una zona escolar"],"h1":"Piense en señales que le ayudan a encontrar el camino.","h2":"Las señales verdes son señales de guía, así que muestran direcciones, salidas y qué tan lejos están los lugares.","p":"Correcto. Las señales verdes muestran direcciones y distancias."},"zh":{"q":"绿色标志告诉你什么？","o":["医院在哪里","道路施工从哪里开始","方向和距离","学校区在哪里"],"h1":"想一想：哪些标志帮你找路。","h2":"绿色标志是指路标志，它告诉你方向、出口，以及到各地还有多远。","p":"对。绿色标志告诉你方向和距离。"},"vi":{"q":"Biển màu xanh lá cây cho bạn biết điều gì?","o":["Bệnh viện ở đâu","Đoạn đường sửa bắt đầu ở đâu","Hướng đi và khoảng cách","Khu vực trường học ở đâu"],"h1":"Hãy nghĩ đến những biển giúp bạn tìm đường.","h2":"Biển màu xanh lá cây là biển chỉ dẫn, nên nó cho biết hướng đi, lối ra, và còn bao xa nữa tới các nơi.","p":"Đúng rồi. Biển xanh lá cây cho biết hướng đi và khoảng cách."},"tl":{"q":"Ano ang ipinapakita sa iyo ng mga berdeng karatula?","o":["Kung nasaan ang ospital","Kung saan nagsisimula ang ginagawang kalsada","Mga direksyon at layo","Kung nasaan ang school zone"],"h1":"Isipin ang mga karatulang tumutulong sa iyo na mahanap ang daan.","h2":"Ang mga berdeng karatula ay gabay na karatula, kaya ipinapakita nito ang mga direksyon, mga exit, at kung gaano kalayo ang mga lugar.","p":"Tama. Ang berdeng karatula ay nagpapakita ng direksyon at layo."},"ar":{"q":"ماذا تُظهر لك اللافتات الخضراء؟","o":["مكان المستشفى","مكان بداية أعمال الطرق","الاتجاهات والمسافات","مكان منطقة المدرسة"],"h1":"فكّر في اللافتات التي تساعدك على معرفة طريقك.","h2":"اللافتات الخضراء هي لافتات إرشاد، فهي تُظهر الاتجاهات والمخارج وكم تبعد الأماكن.","p":"صحيح. اللافتات الخضراء تُظهر الاتجاهات والمسافات."},"ht":{"q":"Kisa siy vèt yo montre ou?","o":["Kote lopital la ye","Kote travay sou wout la kòmanse","Direksyon ak distans","Kote yon zòn lekòl ye"],"h1":"Panse ak siy ki ede ou jwenn chemen ou.","h2":"Siy vèt yo se siy gid, kidonk yo montre direksyon, sòti yo, ak konbyen distans ki genyen pou rive kèk kote.","p":"Se sa. Siy vèt yo montre direksyon ak distans."},"ref":{"doc":"FL","page":46}},{"id":"signs-012","scope":"US","cat":"signs","sign":{"shape":"rect-blue","text":"GAS FOOD LODGING"},"c":3,"en":{"q":"What do blue signs along the road show?","o":["Speed laws","Road work","Parks and lakes","Services like gas, food, and lodging"],"h1":"Think about what you need on a long trip.","h2":"Blue signs show motorist services, so they point you to things like gas, food, lodging, and hospitals.","p":"Right. Blue signs show services like gas and food."},"es":{"q":"¿Qué muestran las señales azules en la carretera?","o":["Leyes de velocidad","Obras en la vía","Parques y lagos","Servicios como gasolina, comida y hospedaje"],"h1":"Piense en lo que necesita en un viaje largo.","h2":"Las señales azules muestran servicios para conductores, así que le indican lugares como gasolineras, comida, hospedaje y hospitales.","p":"Correcto. Las señales azules muestran servicios como gasolina y comida."},"zh":{"q":"路边的蓝色标志告诉你什么？","o":["限速法规","道路施工","公园和湖泊","加油、吃饭、住宿等服务"],"h1":"想一想：长途开车时你需要什么。","h2":"蓝色标志告诉你司机服务的地点，比如加油站、餐馆、住宿和医院。","p":"对。蓝色标志告诉你加油、吃饭等服务。"},"vi":{"q":"Biển màu xanh dương bên đường cho biết điều gì?","o":["Luật về tốc độ","Đường đang sửa","Công viên và hồ","Dịch vụ như xăng, đồ ăn, và chỗ ngủ"],"h1":"Hãy nghĩ xem bạn cần gì trong một chuyến đi xa.","h2":"Biển màu xanh dương cho biết các dịch vụ cho người lái xe, nên nó chỉ bạn tới những nơi như trạm xăng, chỗ ăn, chỗ ngủ, và bệnh viện.","p":"Đúng rồi. Biển xanh dương cho biết dịch vụ như xăng và đồ ăn."},"tl":{"q":"Ano ang ipinapakita ng mga asul na karatula sa tabi ng kalsada?","o":["Mga batas sa bilis","Ginagawang kalsada","Mga parke at lawa","Mga serbisyo tulad ng gasolina, pagkain, at matutuluyan"],"h1":"Isipin kung ano ang kailangan mo sa mahabang biyahe.","h2":"Ang mga asul na karatula ay nagpapakita ng mga serbisyo para sa motorista, kaya itinuturo nito ang mga bagay tulad ng gasolina, pagkain, matutuluyan, at ospital.","p":"Tama. Ang asul na karatula ay nagpapakita ng mga serbisyo tulad ng gasolina at pagkain."},"ar":{"q":"ماذا تُظهر اللافتات الزرقاء على جانب الطريق؟","o":["قوانين السرعة","أعمال الطرق","الحدائق والبحيرات","خدمات مثل الوقود والطعام والمبيت"],"h1":"فكّر في ما تحتاجه في رحلة طويلة.","h2":"اللافتات الزرقاء تُظهر خدمات السائقين، فهي تدلّك على أشياء مثل الوقود والطعام والمبيت والمستشفيات.","p":"صحيح. اللافتات الزرقاء تُظهر خدمات مثل الوقود والطعام."},"ht":{"q":"Kisa siy ble yo sou bò wout la montre?","o":["Lwa sou vitès","Travay sou wout","Pak ak lak","Sèvis tankou gaz, manje, ak kote pou dòmi"],"h1":"Panse ak sa ou bezwen nan yon long vwayaj.","h2":"Siy ble yo montre sèvis pou chofè, kidonk yo montre ou kote ki gen gaz, manje, kote pou dòmi, ak lopital.","p":"Se sa. Siy ble yo montre sèvis tankou gaz ak manje."},"ref":{"doc":"FL","page":46}},{"id":"signs-013","scope":"US","cat":"signs","sign":{"shape":"rect-brown","text":"STATE PARK"},"c":0,"en":{"q":"What do brown signs point you to?","o":["Parks, campgrounds, and places to visit","Gas stations and hotels","Exits and city names","Road work zones"],"h1":"Think about places you go for fun or nature.","h2":"Brown signs point to recreation and cultural places, such as parks, campgrounds, and historic sites.","p":"Right. Brown signs point to parks and places to visit."},"es":{"q":"¿Hacia dónde le indican las señales color café?","o":["Parques, campamentos y lugares para visitar","Gasolineras y hoteles","Salidas y nombres de ciudades","Zonas de obras"],"h1":"Piense en lugares a los que va para divertirse o estar en la naturaleza.","h2":"Las señales color café indican lugares de recreación y cultura, como parques, campamentos y sitios históricos.","p":"Correcto. Las señales color café indican parques y lugares para visitar."},"zh":{"q":"棕色标志指向哪里？","o":["公园、露营地和游览地点","加油站和酒店","出口和城市名","道路施工区"],"h1":"想一想：你为了玩或看大自然会去的地方。","h2":"棕色标志指向休闲和文化地点，比如公园、露营地和历史古迹。","p":"对。棕色标志指向公园和游览地点。"},"vi":{"q":"Biển màu nâu chỉ bạn tới đâu?","o":["Công viên, khu cắm trại, và nơi tham quan","Trạm xăng và khách sạn","Lối ra và tên thành phố","Khu vực đường đang sửa"],"h1":"Hãy nghĩ đến những nơi bạn đi chơi hoặc đi ngắm thiên nhiên.","h2":"Biển màu nâu chỉ tới nơi giải trí và văn hóa, như công viên, khu cắm trại, và di tích lịch sử.","p":"Đúng rồi. Biển màu nâu chỉ tới công viên và nơi tham quan."},"tl":{"q":"Saan ka itinuturo ng mga brown na karatula?","o":["Mga parke, campground, at mga lugar na mapapasyalan","Mga gasolinahan at hotel","Mga exit at pangalan ng lungsod","Mga lugar na may ginagawang kalsada"],"h1":"Isipin ang mga lugar na pinupuntahan mo para maglibang o para sa kalikasan.","h2":"Ang mga brown na karatula ay nagtuturo sa mga lugar ng libangan at kultura, tulad ng mga parke, campground, at makasaysayang lugar.","p":"Tama. Ang brown na karatula ay nagtuturo sa mga parke at mga lugar na mapapasyalan."},"ar":{"q":"إلى ماذا ترشدك اللافتات البنية؟","o":["الحدائق وأماكن التخييم والأماكن التي تستحق الزيارة","محطات الوقود والفنادق","المخارج وأسماء المدن","مناطق أعمال الطرق"],"h1":"فكّر في الأماكن التي تذهب إليها للمتعة أو للطبيعة.","h2":"اللافتات البنية ترشدك إلى أماكن الترفيه والثقافة، مثل الحدائق وأماكن التخييم والمواقع التاريخية.","p":"صحيح. اللافتات البنية ترشدك إلى الحدائق والأماكن التي تستحق الزيارة."},"ht":{"q":"Siy mawon yo montre ou ki kote?","o":["Pak, kan, ak kote pou vizite","Estasyon gaz ak otèl","Sòti ak non vil","Zòn travay sou wout"],"h1":"Panse ak kote ou ale pou pran plezi oswa pou wè lanati.","h2":"Siy mawon yo montre kote pou amizman ak kilti, tankou pak, kan, ak kote istorik.","p":"Se sa. Siy mawon yo montre pak ak kote pou vizite."},"ref":{"doc":"FL","page":46}},{"id":"signs-014","scope":"US","cat":"signs","sign":{"shape":"do-not-enter","text":"DO NOT ENTER"},"c":1,"en":{"q":"What does a red circle with a white bar across it mean?","o":["Stop, then go when clear","Do not enter this road","Hospital ahead","Two-way traffic ahead"],"h1":"Think about a road where all the cars come toward you.","h2":"The red circle with a white bar means do not enter, because traffic on that road comes toward you.","p":"Right. The red circle with a white bar means do not enter."},"es":{"q":"¿Qué significa un círculo rojo con una barra blanca en el medio?","o":["Pararse y seguir cuando esté libre","No entre a esta vía","Hospital más adelante","Tráfico en dos sentidos más adelante"],"h1":"Piense en una vía donde todos los carros vienen hacia usted.","h2":"El círculo rojo con una barra blanca significa no entre, porque el tráfico en esa vía viene hacia usted.","p":"Correcto. El círculo rojo con barra blanca significa no entre."},"zh":{"q":"红色圆形中间有一条白色横杠，是什么意思？","o":["停车，没车时再走","禁止驶入这条路","前方有医院","前方是双向交通"],"h1":"想一想：一条路上所有车都朝你开过来。","h2":"红色圆形中间有白色横杠，意思是禁止驶入，因为这条路上的车是朝你开过来的。","p":"对。红色圆形加白色横杠表示禁止驶入。"},"vi":{"q":"Hình tròn màu đỏ có một vạch trắng ngang qua có nghĩa là gì?","o":["Dừng lại, rồi đi khi đường trống","Không được đi vào con đường này","Phía trước có bệnh viện","Phía trước là đường hai chiều"],"h1":"Hãy nghĩ đến con đường mà mọi xe đều chạy ngược về phía bạn.","h2":"Hình tròn đỏ có vạch trắng nghĩa là cấm đi vào (“DO NOT ENTER”), vì xe trên con đường đó đang chạy ngược về phía bạn.","p":"Đúng rồi. Hình tròn đỏ có vạch trắng nghĩa là cấm đi vào."},"tl":{"q":"Ano ang ibig sabihin ng pulang bilog na may puting guhit sa gitna?","o":["Huminto, saka umandar kapag maluwag na","Bawal pumasok sa daang ito","May ospital sa unahan","May dalawang-direksyong trapiko sa unahan"],"h1":"Isipin ang isang daan kung saan lahat ng sasakyan ay papunta sa iyo.","h2":"Ang pulang bilog na may puting guhit ay nangangahulugang “DO NOT ENTER” (Bawal pumasok), dahil ang trapiko sa daang iyon ay papunta sa iyo.","p":"Tama. Ang pulang bilog na may puting guhit ay nangangahulugang bawal pumasok."},"ar":{"q":"ماذا تعني دائرة حمراء يقطعها خط أبيض؟","o":["توقف، ثم انطلق عندما يكون الطريق خاليًا","لا تدخل هذا الطريق","مستشفى في الأمام","حركة مرور في الاتجاهين في الأمام"],"h1":"فكّر في طريق تأتي فيه كل السيارات نحوك.","h2":"الدائرة الحمراء التي يقطعها خط أبيض تعني «DO NOT ENTER» (ممنوع الدخول)، لأن السيارات في ذلك الطريق تأتي نحوك.","p":"صحيح. الدائرة الحمراء التي يقطعها خط أبيض تعني ممنوع الدخول."},"ht":{"q":"Kisa yon sèk wouj ki gen yon ba blan ki travèse l vle di?","o":["Kanpe, epi pati lè wout la lib","Pa antre nan wout sa a","Gen yon lopital pi devan","Gen machin k ap ale nan de direksyon pi devan"],"h1":"Panse ak yon wout kote tout machin yo ap vin sou ou.","h2":"Sèk wouj ki gen ba blan an vle di “DO NOT ENTER” (pa antre), paske machin sou wout sa a ap vin sou ou.","p":"Se sa. Sèk wouj ki gen ba blan an vle di pa antre."},"ref":{"doc":"FL","page":47}},{"id":"signs-015","scope":"US","cat":"signs","sign":{"shape":"wrong-way","text":"WRONG WAY"},"c":2,"en":{"q":"A red sign facing you says WRONG WAY. What should you do?","o":["Keep going with your hazard lights on","Speed up to reach the next exit","Pull over safely and turn around","Keep driving on the shoulder"],"h1":"The sign means you are going against traffic.","h2":"A WRONG WAY sign means you are driving against traffic, so you should pull over safely and turn around as soon as you can.","p":"Right. WRONG WAY means pull over safely and turn around."},"es":{"q":"Una señal roja frente a usted dice WRONG WAY (sentido contrario). ¿Qué debe hacer?","o":["Seguir con las luces de emergencia prendidas","Acelerar para llegar a la próxima salida","Orillarse con cuidado y dar la vuelta","Seguir manejando por el acotamiento"],"h1":"La señal quiere decir que usted va contra el tráfico.","h2":"Una señal de sentido contrario quiere decir que usted maneja contra el tráfico, así que debe orillarse con cuidado y dar la vuelta lo antes posible.","p":"Correcto. Sentido contrario significa orillarse con cuidado y dar la vuelta."},"zh":{"q":"一个面向你的红色标志写着 “WRONG WAY”（逆行）。你应该怎么做？","o":["打开危险警示灯，继续开","加速，开到下一个出口","安全靠边，然后掉头","继续在路肩上开"],"h1":"这个标志表示你在逆着车流开。","h2":"“WRONG WAY”（逆行）标志表示你在逆着车流开车，所以你要安全靠边，尽快掉头。","p":"对。“WRONG WAY” 表示安全靠边并掉头。"},"vi":{"q":"Một biển màu đỏ hướng về phía bạn ghi “WRONG WAY” (Đi sai chiều). Bạn nên làm gì?","o":["Cứ chạy tiếp và bật đèn khẩn cấp","Tăng tốc để tới lối ra kế tiếp","Tấp vào lề an toàn và quay đầu lại","Chạy tiếp trên lề đường"],"h1":"Biển này nghĩa là bạn đang chạy ngược chiều xe khác.","h2":"Biển “WRONG WAY” nghĩa là bạn đang chạy ngược chiều, nên bạn cần tấp vào lề an toàn và quay đầu lại càng sớm càng tốt.","p":"Đúng rồi. “WRONG WAY” nghĩa là tấp vào lề an toàn và quay đầu lại."},"tl":{"q":"May pulang karatula na nakaharap sa iyo at nakasulat ang “WRONG WAY” (Maling direksyon). Ano ang dapat mong gawin?","o":["Tuloy lang habang nakabukas ang hazard lights","Bumilis para maabot ang susunod na exit","Tumabi nang ligtas at umikot pabalik","Magpatuloy sa pagmamaneho sa gilid ng kalsada"],"h1":"Ang karatula ay nangangahulugang salungat ka sa daloy ng trapiko.","h2":"Ang “WRONG WAY” na karatula ay nangangahulugang salungat ka sa daloy ng trapiko, kaya dapat kang tumabi nang ligtas at umikot pabalik sa lalong madaling panahon.","p":"Tama. Ang “WRONG WAY” ay nangangahulugang tumabi nang ligtas at umikot pabalik."},"ar":{"q":"لافتة حمراء أمامك مكتوب عليها «WRONG WAY» (اتجاه خاطئ). ماذا يجب أن تفعل؟","o":["تابع السير مع تشغيل أضواء التحذير","زد السرعة لتصل إلى المخرج التالي","توقف على جانب الطريق بأمان واستدر عائدًا","تابع القيادة على كتف الطريق"],"h1":"اللافتة تعني أنك تسير عكس اتجاه السير.","h2":"لافتة «WRONG WAY» تعني أنك تقود عكس اتجاه السير، لذلك يجب أن تتوقف على جانب الطريق بأمان وتستدير عائدًا في أسرع وقت ممكن.","p":"صحيح. «WRONG WAY» تعني: توقف على الجانب بأمان واستدر عائدًا."},"ht":{"q":"Yon siy wouj ki fè fas ak ou di “WRONG WAY” (move direksyon). Kisa ou dwe fè?","o":["Kontinye ak limyè ijans ou limen","Akselere pou rive nan pwochen sòti a","Rale sou kote an sekirite epi vire tounen","Kontinye kondui sou arebò wout la"],"h1":"Siy la vle di w ap kondui kont trafik la.","h2":"Yon siy “WRONG WAY” vle di w ap kondui kont trafik la, kidonk ou dwe rale sou kote an sekirite epi vire tounen pi vit ou kapab.","p":"Se sa. “WRONG WAY” vle di rale sou kote an sekirite epi vire tounen."},"ref":{"doc":"FL","page":47}},{"id":"signs-016","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"SPEED LIMIT 55"},"c":3,"en":{"q":"What does this sign tell you?","o":["The lowest speed you may drive","The speed you must always drive","A suggested speed for curves","The top legal speed in good conditions"],"h1":"Think about whether you may go faster, or slower.","h2":"A speed limit sign shows the highest legal speed when conditions are good, so you may need to drive slower in rain, fog, or heavy traffic.","p":"Right. The speed limit is the top speed in good conditions."},"es":{"q":"¿Qué le dice esta señal?","o":["La velocidad más baja permitida","La velocidad a la que siempre debe ir","Una velocidad sugerida para curvas","La velocidad máxima legal en buenas condiciones"],"h1":"Piense si puede ir más rápido o más despacio.","h2":"Una señal de límite de velocidad muestra la velocidad máxima legal cuando las condiciones son buenas, así que puede tener que ir más despacio con lluvia, neblina o mucho tráfico.","p":"Correcto. El límite es la velocidad máxima en buenas condiciones."},"zh":{"q":"这个标志告诉你什么？","o":["你可以开的最低速度","你必须一直保持的速度","弯道的建议速度","在良好条件下的最高合法速度"],"h1":"想一想：你可以开得更快，还是要开得更慢。","h2":"限速标志表示在良好条件下的最高合法速度，所以下雨、有雾或车多时，你可能要开得更慢。","p":"对。限速是在良好条件下的最高速度。"},"vi":{"q":"Biển này cho bạn biết điều gì?","o":["Tốc độ thấp nhất bạn được chạy","Tốc độ bạn lúc nào cũng phải chạy","Tốc độ nên chạy ở khúc cua","Tốc độ cao nhất theo luật khi điều kiện tốt"],"h1":"Hãy nghĩ xem bạn được chạy nhanh hơn, hay chậm hơn.","h2":"Biển giới hạn tốc độ cho biết tốc độ cao nhất theo luật khi điều kiện tốt, nên bạn có thể cần chạy chậm hơn khi mưa, có sương mù, hoặc kẹt xe.","p":"Đúng rồi. Giới hạn tốc độ là tốc độ cao nhất khi điều kiện tốt."},"tl":{"q":"Ano ang sinasabi sa iyo ng karatulang ito?","o":["Ang pinakamababang bilis na puwede mong takbuhin","Ang bilis na dapat mong takbuhin palagi","Mungkahing bilis para sa mga kurba","Ang pinakamataas na legal na bilis kapag maayos ang kondisyon"],"h1":"Isipin kung puwede kang bumilis pa, o bumagal.","h2":"Ang karatula ng speed limit ay nagpapakita ng pinakamataas na legal na bilis kapag maayos ang kondisyon, kaya maaaring kailangan mong bumagal kapag umuulan, may hamog, o mabigat ang trapiko.","p":"Tama. Ang speed limit ay ang pinakamataas na bilis kapag maayos ang kondisyon."},"ar":{"q":"ماذا تخبرك هذه اللافتة؟","o":["أقل سرعة مسموح لك أن تقود بها","السرعة التي يجب أن تقود بها دائمًا","سرعة مقترحة للمنعطفات","أعلى سرعة قانونية عندما تكون الظروف جيدة"],"h1":"فكّر: هل يُسمح لك أن تسير أسرع، أم أبطأ؟","h2":"لافتة حد السرعة تُظهر أعلى سرعة قانونية عندما تكون الظروف جيدة، لذلك قد تحتاج إلى القيادة أبطأ في المطر أو الضباب أو الزحام الشديد.","p":"صحيح. حد السرعة هو أعلى سرعة عندما تكون الظروف جيدة."},"ht":{"q":"Kisa siy sa a di ou?","o":["Vitès ki pi ba ou ka kondui","Vitès ou dwe toujou kondui","Yon vitès yo konseye pou koub yo","Vitès ki pi wo lalwa pèmèt lè kondisyon yo bon"],"h1":"Panse si ou ka ale pi vit, oswa pi dousman.","h2":"Yon siy limit vitès montre vitès ki pi wo lalwa pèmèt lè kondisyon yo bon, kidonk ou ka bezwen kondui pi dousman lè gen lapli, bwouya, oswa anpil machin.","p":"Se sa. Limit vitès la se vitès ki pi wo a lè kondisyon yo bon."},"ref":{"doc":"FL","page":47}},{"id":"signs-017","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"ONE WAY"},"c":1,"en":{"q":"What does a ONE WAY sign with an arrow mean?","o":["Only one lane is open ahead","Traffic moves only in the arrow's direction","Only one car may pass at a time","You may make only one turn"],"h1":"Look at where the arrow points.","h2":"A ONE WAY sign means all traffic on that street moves only in the direction of the arrow.","p":"Right. One way means drive only in the arrow's direction."},"es":{"q":"¿Qué significa una señal ONE WAY (un solo sentido) con una flecha?","o":["Solo hay un carril abierto más adelante","El tráfico va solo en la dirección de la flecha","Solo puede pasar un carro a la vez","Solo puede dar una vuelta"],"h1":"Mire hacia dónde apunta la flecha.","h2":"Una señal de un solo sentido quiere decir que todo el tráfico en esa calle va solo en la dirección de la flecha.","p":"Correcto. Un solo sentido significa manejar solo hacia donde apunta la flecha."},"zh":{"q":"带箭头的 “ONE WAY”（单行道）标志是什么意思？","o":["前方只有一条车道开放","车辆只能按箭头方向行驶","一次只能过一辆车","你只能转一次弯"],"h1":"看看箭头指向哪里。","h2":"“ONE WAY”（单行道）标志表示这条街上所有车辆只能按箭头的方向行驶。","p":"对。单行道表示只能按箭头方向开。"},"vi":{"q":"Biển “ONE WAY” (Một chiều) có mũi tên có nghĩa là gì?","o":["Phía trước chỉ còn một làn mở","Xe chỉ được chạy theo hướng mũi tên","Mỗi lần chỉ một xe được đi qua","Bạn chỉ được rẽ một lần"],"h1":"Hãy nhìn xem mũi tên chỉ về đâu.","h2":"Biển “ONE WAY” nghĩa là mọi xe trên con đường đó chỉ được chạy theo hướng mũi tên.","p":"Đúng rồi. Một chiều nghĩa là chỉ chạy theo hướng mũi tên."},"tl":{"q":"Ano ang ibig sabihin ng “ONE WAY” na karatula na may arrow?","o":["Isang linya lang ang bukas sa unahan","Ang trapiko ay dumadaloy lang sa direksyon ng arrow","Isang sasakyan lang ang puwedeng dumaan bawat oras","Isang beses ka lang puwedeng lumiko"],"h1":"Tingnan kung saan nakaturo ang arrow.","h2":"Ang “ONE WAY” na karatula (Isang direksyon) ay nangangahulugang lahat ng trapiko sa kalyeng iyon ay dumadaloy lang sa direksyon ng arrow.","p":"Tama. Ang “ONE WAY” ay nangangahulugang magmaneho lang sa direksyon ng arrow."},"ar":{"q":"ماذا تعني لافتة «ONE WAY» (اتجاه واحد) التي عليها سهم؟","o":["مسار واحد فقط مفتوح في الأمام","السيارات تسير فقط في اتجاه السهم","سيارة واحدة فقط تمر في كل مرة","مسموح لك بمنعطف واحد فقط"],"h1":"انظر إلى أين يشير السهم.","h2":"لافتة «ONE WAY» تعني أن كل السيارات في ذلك الشارع تسير فقط في اتجاه السهم.","p":"صحيح. اتجاه واحد يعني: قُد فقط في اتجاه السهم."},"ht":{"q":"Kisa yon siy “ONE WAY” (yon sèl direksyon) ak yon flèch vle di?","o":["Se yon sèl koulwa ki louvri pi devan","Machin yo ale sèlman nan direksyon flèch la","Se yon sèl machin ki ka pase alafwa","Ou ka fè yon sèl vire sèlman"],"h1":"Gade ki bò flèch la montre.","h2":"Yon siy “ONE WAY” vle di tout machin nan lari sa a ale sèlman nan direksyon flèch la.","p":"Se sa. Yon sèl direksyon vle di kondui sèlman nan direksyon flèch la."},"ref":{"doc":"FL","page":48}},{"id":"signs-018","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"NO U-TURN"},"c":2,"en":{"q":"What does a NO U-TURN sign mean?","o":["You may not turn left here","You may not turn right here","You may not turn around here","You may not change lanes here"],"h1":"A U-turn makes the shape of the letter U.","h2":"A NO U-TURN sign means you may not turn your car around to go back the other way at that place.","p":"Right. No U-turn means you may not turn around here."},"es":{"q":"¿Qué significa una señal de NO U-TURN (prohibido dar vuelta en U)?","o":["No puede doblar a la izquierda aquí","No puede doblar a la derecha aquí","No puede dar la vuelta para regresar aquí","No puede cambiar de carril aquí"],"h1":"Una vuelta en U tiene la forma de la letra U.","h2":"Una señal de prohibido dar vuelta en U quiere decir que usted no puede dar la vuelta con su carro para regresar en ese lugar.","p":"Correcto. Prohibido vuelta en U significa que no puede dar la vuelta aquí."},"zh":{"q":"“NO U-TURN”（禁止掉头）标志是什么意思？","o":["这里不能左转","这里不能右转","这里不能掉头","这里不能换车道"],"h1":"掉头时车走的路线像字母 U。","h2":"“NO U-TURN”（禁止掉头）标志表示你在这里不能把车调过头往回开。","p":"对。禁止掉头表示这里不能掉头。"},"vi":{"q":"Biển “NO U-TURN” (Cấm quay đầu) có nghĩa là gì?","o":["Bạn không được rẽ trái ở đây","Bạn không được rẽ phải ở đây","Bạn không được quay đầu xe ở đây","Bạn không được đổi làn ở đây"],"h1":"Khi quay đầu, xe chạy theo hình chữ U.","h2":"Biển “NO U-TURN” nghĩa là ở chỗ đó bạn không được quay đầu xe để đi ngược lại.","p":"Đúng rồi. Cấm quay đầu nghĩa là bạn không được quay đầu xe ở đây."},"tl":{"q":"Ano ang ibig sabihin ng “NO U-TURN” na karatula?","o":["Hindi ka puwedeng kumaliwa dito","Hindi ka puwedeng kumanan dito","Hindi ka puwedeng umikot pabalik dito","Hindi ka puwedeng lumipat ng linya dito"],"h1":"Ang U-turn ay may hugis ng letrang U.","h2":"Ang “NO U-TURN” na karatula ay nangangahulugang hindi mo puwedeng iikot ang sasakyan mo para bumalik sa kabilang direksyon sa lugar na iyon.","p":"Tama. Ang “NO U-TURN” ay nangangahulugang hindi ka puwedeng umikot pabalik dito."},"ar":{"q":"ماذا تعني لافتة «NO U-TURN» (ممنوع الدوران للخلف)؟","o":["ممنوع أن تنعطف يسارًا هنا","ممنوع أن تنعطف يمينًا هنا","ممنوع أن تستدير عائدًا هنا","ممنوع أن تغيّر المسار هنا"],"h1":"الدوران للخلف يرسم شكل الحرف U.","h2":"لافتة «NO U-TURN» تعني أنه ممنوع أن تدير سيارتك لتعود في الاتجاه الآخر في ذلك المكان.","p":"صحيح. ممنوع الدوران للخلف يعني أنك لا تستطيع أن تستدير عائدًا هنا."},"ht":{"q":"Kisa yon siy “NO U-TURN” vle di?","o":["Ou pa ka vire agoch la a","Ou pa ka vire adwat la a","Ou pa ka vire tounen la a","Ou pa ka chanje koulwa la a"],"h1":"Yon “U-turn” fè fòm lèt U a.","h2":"Yon siy “NO U-TURN” vle di ou pa ka vire machin ou pou tounen nan lòt direksyon an kote sa a.","p":"Se sa. “NO U-TURN” vle di ou pa ka vire tounen la a."},"ref":{"doc":"FL","page":48}},{"id":"signs-019","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"NO TURN ON RED"},"c":3,"en":{"q":"What does a NO TURN ON RED sign mean?","o":["Turn right only after a full stop","Turn only when no cars are coming","Turn on red only at night","Wait for the green light before you turn"],"h1":"The sign changes what you may do while the light is red.","h2":"A NO TURN ON RED sign means you may not turn while the light is red, so you must wait for the green light.","p":"Right. No turn on red means wait for green."},"es":{"q":"¿Qué significa una señal de NO TURN ON RED (no doblar con luz roja)?","o":["Doblar a la derecha solo después de parar por completo","Doblar solo cuando no vengan carros","Doblar con luz roja solo de noche","Esperar la luz verde antes de doblar"],"h1":"La señal cambia lo que puede hacer mientras la luz está en rojo.","h2":"Una señal de no doblar con luz roja quiere decir que usted no puede doblar mientras la luz está en rojo, así que debe esperar la luz verde.","p":"Correcto. No doblar con luz roja significa esperar la luz verde."},"zh":{"q":"“NO TURN ON RED”（红灯禁止转弯）标志是什么意思？","o":["完全停车后才可以右转","没有来车时才可以转弯","只有晚上才可以红灯转弯","等绿灯亮了再转弯"],"h1":"这个标志改变了红灯时你可以做的事。","h2":"“NO TURN ON RED”（红灯禁止转弯）标志表示红灯时你不能转弯，所以你必须等绿灯。","p":"对。红灯禁止转弯表示要等绿灯。"},"vi":{"q":"Biển “NO TURN ON RED” (Cấm rẽ khi đèn đỏ) có nghĩa là gì?","o":["Chỉ rẽ phải sau khi dừng hẳn","Chỉ rẽ khi không có xe tới","Chỉ được rẽ khi đèn đỏ vào ban đêm","Chờ đèn xanh rồi mới rẽ"],"h1":"Biển này thay đổi điều bạn được làm khi đèn đang đỏ.","h2":"Biển “NO TURN ON RED” nghĩa là bạn không được rẽ khi đèn đang đỏ, nên bạn phải chờ đèn xanh.","p":"Đúng rồi. Cấm rẽ khi đèn đỏ nghĩa là chờ đèn xanh."},"tl":{"q":"Ano ang ibig sabihin ng “NO TURN ON RED” na karatula?","o":["Kumanan lang pagkatapos huminto nang buo","Lumiko lang kapag walang dumarating na sasakyan","Lumiko sa pula lang kapag gabi","Hintayin ang berdeng ilaw bago ka lumiko"],"h1":"Binabago ng karatula kung ano ang puwede mong gawin habang pula ang ilaw.","h2":"Ang “NO TURN ON RED” na karatula ay nangangahulugang hindi ka puwedeng lumiko habang pula ang ilaw, kaya dapat mong hintayin ang berdeng ilaw.","p":"Tama. Ang “NO TURN ON RED” ay nangangahulugang hintayin ang berde."},"ar":{"q":"ماذا تعني لافتة «NO TURN ON RED» (ممنوع الانعطاف عند الإشارة الحمراء)؟","o":["انعطف يمينًا فقط بعد توقف تام","انعطف فقط عندما لا تأتي سيارات","انعطف عند الإشارة الحمراء في الليل فقط","انتظر الإشارة الخضراء قبل أن تنعطف"],"h1":"اللافتة تغيّر ما يُسمح لك به عندما تكون الإشارة حمراء.","h2":"لافتة «NO TURN ON RED» تعني أنه ممنوع أن تنعطف والإشارة حمراء، لذلك يجب أن تنتظر الإشارة الخضراء.","p":"صحيح. ممنوع الانعطاف عند الأحمر يعني: انتظر الأخضر."},"ht":{"q":"Kisa yon siy “NO TURN ON RED” vle di?","o":["Vire adwat sèlman apre ou fin kanpe nèt","Vire sèlman lè pa gen machin k ap vini","Vire sou limyè wouj sèlman lannwit","Tann limyè vèt la anvan ou vire"],"h1":"Siy la chanje sa ou ka fè pandan limyè a wouj.","h2":"Yon siy “NO TURN ON RED” vle di ou pa ka vire pandan limyè a wouj, kidonk ou dwe tann limyè vèt la.","p":"Se sa. “NO TURN ON RED” vle di tann limyè vèt la."},"ref":{"doc":"FL","page":51}},{"id":"signs-020","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"KEEP RIGHT"},"c":0,"en":{"q":"A KEEP RIGHT sign stands at the front of a median. What does it mean?","o":["Stay to the right of the median or island","Move to the right lane to exit","The right lane ends ahead","Use the right lane only to pass"],"h1":"Think about which side of the median your car should go.","h2":"A KEEP RIGHT sign means you must drive on the right side of the median or island ahead.","p":"Right. Keep right means pass the median on its right side."},"es":{"q":"Una señal KEEP RIGHT (manténgase a la derecha) está al inicio de una isla. ¿Qué significa?","o":["Pasar por la derecha de la isla o el divisor","Cambiarse al carril derecho para salir","El carril derecho se termina más adelante","Usar el carril derecho solo para rebasar"],"h1":"Piense por qué lado de la isla debe pasar su carro.","h2":"Una señal de manténgase a la derecha quiere decir que usted debe pasar por el lado derecho de la isla o el divisor que está adelante.","p":"Correcto. Manténgase a la derecha significa pasar la isla por su lado derecho."},"zh":{"q":"一个 “KEEP RIGHT”（靠右行驶）标志立在中央隔离带的前端。它是什么意思？","o":["从隔离带或安全岛的右边通过","换到右车道准备出口","右车道在前方结束","只能用右车道超车"],"h1":"想一想：你的车应该走隔离带的哪一边。","h2":"“KEEP RIGHT”（靠右行驶）标志表示你必须从前方隔离带或安全岛的右边开过去。","p":"对。靠右行驶表示从隔离带的右边通过。"},"vi":{"q":"Biển “KEEP RIGHT” (Đi bên phải) đặt ở đầu một dải phân cách. Biển này có nghĩa là gì?","o":["Đi ở bên phải dải phân cách hoặc đảo giao thông","Chuyển sang làn phải để ra khỏi đường","Làn bên phải sắp hết","Chỉ dùng làn bên phải để vượt"],"h1":"Hãy nghĩ xem xe bạn nên đi ở bên nào của dải phân cách.","h2":"Biển “KEEP RIGHT” nghĩa là bạn phải chạy ở bên phải của dải phân cách hoặc đảo giao thông phía trước.","p":"Đúng rồi. Đi bên phải nghĩa là chạy qua bên phải dải phân cách."},"tl":{"q":"May “KEEP RIGHT” na karatula sa harap ng isang median. Ano ang ibig sabihin nito?","o":["Manatili sa kanan ng median o isla","Lumipat sa kanang linya para lumabas","Matatapos ang kanang linya sa unahan","Gamitin ang kanang linya para lang mag-overtake"],"h1":"Isipin kung sa aling bahagi ng median dapat dumaan ang sasakyan mo.","h2":"Ang “KEEP RIGHT” na karatula (Manatili sa kanan) ay nangangahulugang dapat kang magmaneho sa kanang bahagi ng median o isla sa unahan.","p":"Tama. Ang “KEEP RIGHT” ay nangangahulugang dumaan sa kanang bahagi ng median."},"ar":{"q":"لافتة «KEEP RIGHT» (الزم اليمين) موجودة في بداية جزيرة وسطية. ماذا تعني؟","o":["ابقَ على يمين الجزيرة الوسطية أو الجزيرة","انتقل إلى المسار الأيمن لتخرج","المسار الأيمن ينتهي في الأمام","استخدم المسار الأيمن للتجاوز فقط"],"h1":"فكّر في أي جانب من الجزيرة الوسطية يجب أن تمر سيارتك.","h2":"لافتة «KEEP RIGHT» تعني أنه يجب أن تقود على الجانب الأيمن من الجزيرة الوسطية أو الجزيرة التي أمامك.","p":"صحيح. الزم اليمين يعني: مُرّ على يمين الجزيرة الوسطية."},"ht":{"q":"Yon siy “KEEP RIGHT” (rete adwat) kanpe devan yon separasyon nan mitan wout la. Kisa li vle di?","o":["Rete sou bò dwat separasyon an oswa zile a","Ale nan koulwa dwat la pou sòti","Koulwa dwat la fini pi devan","Sèvi ak koulwa dwat la sèlman pou double"],"h1":"Panse sou ki bò separasyon an machin ou dwe pase.","h2":"Yon siy “KEEP RIGHT” vle di ou dwe kondui sou bò dwat separasyon an oswa zile ki devan an.","p":"Se sa. “KEEP RIGHT” vle di pase sou bò dwat separasyon an."},"ref":{"doc":"FL","page":48}},{"id":"signs-021","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"ONLY"},"c":1,"en":{"q":"A sign over your lane shows only a left arrow. What must you do?","o":["You may go straight or turn left","You must turn left from this lane","You may turn left or right","You must change lanes at the light"],"h1":"The arrows show what each lane is allowed to do.","h2":"When the sign over your lane shows only a left arrow, that lane is for left turns, so you must turn left.","p":"Right. A left-only arrow means you must turn left."},"es":{"q":"Una señal encima de su carril muestra solo una flecha a la izquierda. ¿Qué debe hacer?","o":["Puede seguir derecho o doblar a la izquierda","Debe doblar a la izquierda desde este carril","Puede doblar a la izquierda o a la derecha","Debe cambiar de carril en el semáforo"],"h1":"Las flechas muestran lo que se permite en cada carril.","h2":"Cuando la señal encima de su carril muestra solo una flecha a la izquierda, ese carril es para doblar a la izquierda, así que usted debe doblar a la izquierda.","p":"Correcto. Una flecha solo a la izquierda significa que debe doblar a la izquierda."},"zh":{"q":"你车道上方的标志只有一个左转箭头。你必须怎么做？","o":["你可以直行或左转","你必须从这条车道左转","你可以左转或右转","你必须在红绿灯处换车道"],"h1":"箭头告诉你每条车道可以怎么走。","h2":"当你车道上方的标志只有左转箭头时，这条车道是左转车道，所以你必须左转。","p":"对。只有左转箭头表示你必须左转。"},"vi":{"q":"Biển phía trên làn của bạn chỉ có một mũi tên rẽ trái. Bạn phải làm gì?","o":["Bạn được đi thẳng hoặc rẽ trái","Bạn phải rẽ trái từ làn này","Bạn được rẽ trái hoặc rẽ phải","Bạn phải đổi làn ở chỗ đèn"],"h1":"Các mũi tên cho biết mỗi làn được phép đi hướng nào.","h2":"Khi biển trên làn của bạn chỉ có mũi tên rẽ trái, làn đó dành cho xe rẽ trái, nên bạn phải rẽ trái.","p":"Đúng rồi. Chỉ có mũi tên trái nghĩa là bạn phải rẽ trái."},"tl":{"q":"Ang karatula sa itaas ng linya mo ay nagpapakita lang ng arrow pakaliwa. Ano ang dapat mong gawin?","o":["Puwede kang dumiretso o kumaliwa","Dapat kang kumaliwa mula sa linyang ito","Puwede kang kumaliwa o kumanan","Dapat kang lumipat ng linya sa may ilaw"],"h1":"Ipinapakita ng mga arrow kung ano ang pinapayagan sa bawat linya.","h2":"Kapag ang karatula sa itaas ng linya mo ay nagpapakita lang ng arrow pakaliwa, ang linyang iyon ay para sa pagkaliwa, kaya dapat kang kumaliwa.","p":"Tama. Ang arrow na pakaliwa lang ay nangangahulugang dapat kang kumaliwa."},"ar":{"q":"لافتة فوق مسارك تُظهر سهمًا إلى اليسار فقط. ماذا يجب أن تفعل؟","o":["يمكنك أن تسير مستقيمًا أو تنعطف يسارًا","يجب أن تنعطف يسارًا من هذا المسار","يمكنك أن تنعطف يسارًا أو يمينًا","يجب أن تغيّر المسار عند الإشارة"],"h1":"الأسهم تُظهر ما هو مسموح في كل مسار.","h2":"عندما تُظهر اللافتة فوق مسارك سهمًا إلى اليسار فقط، فهذا المسار للانعطاف يسارًا، لذلك يجب أن تنعطف يسارًا.","p":"صحيح. سهم إلى اليسار فقط يعني أنه يجب أن تنعطف يسارًا."},"ht":{"q":"Yon siy anwo koulwa ou montre sèlman yon flèch agoch. Kisa ou dwe fè?","o":["Ou ka ale tou dwat oswa vire agoch","Ou dwe vire agoch nan koulwa sa a","Ou ka vire agoch oswa adwat","Ou dwe chanje koulwa nan limyè a"],"h1":"Flèch yo montre sa chak koulwa gen dwa fè.","h2":"Lè siy anwo koulwa ou montre sèlman yon flèch agoch, koulwa sa a se pou vire agoch, kidonk ou dwe vire agoch.","p":"Se sa. Yon flèch agoch sèlman vle di ou dwe vire agoch."},"ref":{"doc":"FL","page":47}},{"id":"signs-022","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"35 MPH"},"c":2,"en":{"q":"A curve warning sign has a small yellow sign below it with a speed. What is that speed?","o":["The lowest speed you may drive","The new speed limit for the road","A safe speed for the curve","A speed for trucks only"],"h1":"It is a yellow sign, not a white one.","h2":"The small yellow speed sign under a curve sign gives a safe speed for the curve in good conditions, so slow down to that speed or less.","p":"Right. The yellow speed plate gives a safe speed for the curve."},"es":{"q":"Una señal de curva tiene abajo una señal amarilla pequeña con una velocidad. ¿Qué es esa velocidad?","o":["La velocidad más baja permitida","El nuevo límite de velocidad de la vía","Una velocidad segura para la curva","Una velocidad solo para camiones"],"h1":"Es una señal amarilla, no blanca.","h2":"La señal amarilla pequeña debajo de una señal de curva le da una velocidad segura para la curva en buenas condiciones, así que baje a esa velocidad o menos.","p":"Correcto. La placa amarilla le da una velocidad segura para la curva."},"zh":{"q":"弯道警告标志下面有一个写着速度的黄色小牌子。这个速度是什么？","o":["你可以开的最低速度","这条路的新限速","过弯道的安全速度","只给卡车的速度"],"h1":"它是黄色的牌子，不是白色的。","h2":"弯道标志下面的黄色小速度牌，给出在良好条件下过这个弯道的安全速度，所以你要减速到这个速度或更低。","p":"对。黄色速度牌给出过弯道的安全速度。"},"vi":{"q":"Dưới biển báo khúc cua có một biển nhỏ màu vàng ghi tốc độ. Tốc độ đó là gì?","o":["Tốc độ thấp nhất bạn được chạy","Giới hạn tốc độ mới của con đường","Tốc độ an toàn cho khúc cua","Tốc độ chỉ dành cho xe tải"],"h1":"Đây là biển màu vàng, không phải biển màu trắng.","h2":"Biển nhỏ màu vàng dưới biển khúc cua cho biết tốc độ an toàn để qua khúc cua khi điều kiện tốt, nên bạn cần chạy chậm lại bằng hoặc thấp hơn tốc độ đó.","p":"Đúng rồi. Biển tốc độ màu vàng cho biết tốc độ an toàn qua khúc cua."},"tl":{"q":"May maliit na dilaw na karatula na may bilis sa ilalim ng karatula ng babala sa kurba. Ano ang bilis na iyon?","o":["Ang pinakamababang bilis na puwede mong takbuhin","Ang bagong speed limit ng kalsada","Isang ligtas na bilis para sa kurba","Bilis para sa mga trak lang"],"h1":"Ito ay dilaw na karatula, hindi puti.","h2":"Ang maliit na dilaw na karatula ng bilis sa ilalim ng karatula ng kurba ay nagbibigay ng ligtas na bilis para sa kurba kapag maayos ang kondisyon, kaya bumagal ka sa bilis na iyon o mas mababa pa.","p":"Tama. Ang dilaw na plaka ng bilis ay nagbibigay ng ligtas na bilis para sa kurba."},"ar":{"q":"تحت لافتة تحذير من منعطف توجد لافتة صفراء صغيرة عليها سرعة. ما هذه السرعة؟","o":["أقل سرعة مسموح لك أن تقود بها","حد السرعة الجديد للطريق","سرعة آمنة للمنعطف","سرعة للشاحنات فقط"],"h1":"إنها لافتة صفراء، وليست بيضاء.","h2":"لافتة السرعة الصفراء الصغيرة تحت لافتة المنعطف تعطي سرعة آمنة للمنعطف عندما تكون الظروف جيدة، لذلك خفف سرعتك إلى هذه السرعة أو أقل.","p":"صحيح. لوحة السرعة الصفراء تعطي سرعة آمنة للمنعطف."},"ht":{"q":"Yon siy avètisman pou koub gen yon ti siy jòn anba l ak yon vitès. Ki vitès sa a ye?","o":["Vitès ki pi ba ou ka kondui","Nouvo limit vitès pou wout la","Yon vitès ki an sekirite pou koub la","Yon vitès pou kamyon sèlman"],"h1":"Se yon siy jòn, se pa yon siy blan.","h2":"Ti siy vitès jòn anba siy koub la bay yon vitès ki an sekirite pou koub la lè kondisyon yo bon, kidonk ralanti rive nan vitès sa a oswa mwens.","p":"Se sa. Ti siy jòn nan bay yon vitès ki an sekirite pou koub la."},"ref":{"doc":"FL","page":49}},{"id":"signs-023","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"MERGE"},"c":3,"en":{"q":"A yellow sign shows a side line joining the main road. What should you expect?","o":["A railroad crossing","A dead end","A stop sign ahead","Cars entering your road from the side"],"h1":"Think about two roads becoming one.","h2":"This merge sign warns that cars will enter your road from the side, so be ready to adjust your speed or make room.","p":"Right. The merge sign means cars will join your road."},"es":{"q":"Una señal amarilla muestra una línea lateral que se une a la vía principal. ¿Qué debe esperar?","o":["Un cruce de tren","Una calle sin salida","Una señal de pare más adelante","Carros que entran a su vía desde un lado"],"h1":"Piense en dos vías que se vuelven una.","h2":"Esta señal de incorporación avisa que entrarán carros a su vía desde un lado, así que esté listo para ajustar su velocidad o darles espacio.","p":"Correcto. La señal de incorporación significa que entrarán carros a su vía."},"zh":{"q":"一个黄色标志上画着一条旁边的线并入主路。你应该预料到什么？","o":["铁路道口","死路","前方有停车标志","有车从旁边开进你的路"],"h1":"想一想：两条路变成一条路。","h2":"这个并道标志提醒你会有车从旁边开进你的路，所以要准备调整车速或让出空间。","p":"对。并道标志表示有车会开进你的路。"},"vi":{"q":"Một biển màu vàng có hình một đường nhánh nhập vào đường chính. Bạn nên chờ đợi điều gì?","o":["Chỗ băng qua đường sắt","Đường cụt","Biển dừng phía trước","Xe từ bên hông nhập vào đường của bạn"],"h1":"Hãy nghĩ đến hai con đường nhập lại thành một.","h2":"Biển nhập làn này cảnh báo rằng xe sẽ từ bên hông đi vào đường của bạn, nên bạn cần sẵn sàng đổi tốc độ hoặc chừa chỗ cho họ.","p":"Đúng rồi. Biển nhập làn nghĩa là xe khác sẽ vào đường của bạn."},"tl":{"q":"Ang dilaw na karatula ay nagpapakita ng isang guhit sa gilid na sumasama sa pangunahing kalsada. Ano ang dapat mong asahan?","o":["Tawiran ng tren","Dulo ng daan (dead end)","May “STOP” sign sa unahan","Mga sasakyang papasok sa daan mo mula sa gilid"],"h1":"Isipin ang dalawang daan na nagiging isa.","h2":"Ang karatulang ito ng merge ay babala na may mga sasakyang papasok sa daan mo mula sa gilid, kaya maging handa na ayusin ang bilis mo o magbigay ng puwang.","p":"Tama. Ang karatula ng merge ay nangangahulugang may mga sasakyang sasama sa daan mo."},"ar":{"q":"لافتة صفراء تُظهر خطًا جانبيًا ينضم إلى الطريق الرئيسي. ماذا يجب أن تتوقع؟","o":["تقاطعًا مع سكة حديد","طريقًا مسدودًا","لافتة «STOP» (قف) في الأمام","سيارات تدخل طريقك من الجانب"],"h1":"فكّر في طريقين يصبحان طريقًا واحدًا.","h2":"لافتة الاندماج هذه تحذّر من أن سيارات ستدخل طريقك من الجانب، لذلك كن مستعدًا لتغيير سرعتك أو لترك مكان لها.","p":"صحيح. لافتة الاندماج تعني أن سيارات ستنضم إلى طريقك."},"ht":{"q":"Yon siy jòn montre yon liy sou kote k ap kole ak wout prensipal la. Kisa ou dwe atann?","o":["Yon kote tren travèse","Yon wout ki bloke","Yon siy “STOP” pi devan","Machin k ap antre sou wout ou a sou kote"],"h1":"Panse ak de wout k ap vin tounen yon sèl.","h2":"Siy sa a avèti ou gen machin ki pral antre sou wout ou a sou kote, kidonk pare pou chanje vitès ou oswa fè plas pou yo.","p":"Se sa. Siy sa a vle di gen machin ki pral antre sou wout ou a."},"ref":{"doc":"FL","page":49}},{"id":"signs-024","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"RIGHT LANE ENDS"},"c":0,"en":{"q":"You are in the right lane. A sign says RIGHT LANE ENDS. What should you do?","o":["Move left when it is safe","Speed up to stay ahead of others","Stop at the end of the lane","Drive on the shoulder"],"h1":"Your lane will soon be gone.","h2":"When the sign says your lane ends, you should signal and move into the next lane when it is safe.","p":"Right. When your lane ends, move over safely."},"es":{"q":"Usted va en el carril derecho. Una señal dice RIGHT LANE ENDS (el carril derecho termina). ¿Qué debe hacer?","o":["Pasarse a la izquierda cuando sea seguro","Acelerar para quedar delante de los demás","Pararse al final del carril","Manejar por el acotamiento"],"h1":"Su carril pronto desaparece.","h2":"Cuando la señal dice que su carril termina, usted debe poner la direccional y pasarse al otro carril cuando sea seguro.","p":"Correcto. Cuando su carril termina, cámbiese con cuidado."},"zh":{"q":"你在右车道。一个标志写着 “RIGHT LANE ENDS”（右车道结束）。你应该怎么做？","o":["安全时换到左边车道","加速，开到别的车前面","在车道尽头停车","在路肩上开"],"h1":"你的车道很快就没有了。","h2":"当标志说你的车道要结束时，你应该打转向灯，在安全时换到旁边的车道。","p":"对。你的车道结束时，要安全地换道。"},"vi":{"q":"Bạn đang ở làn bên phải. Một biển ghi “RIGHT LANE ENDS” (Làn phải sắp hết). Bạn nên làm gì?","o":["Chuyển sang trái khi an toàn","Tăng tốc để chạy trước xe khác","Dừng lại ở cuối làn","Chạy trên lề đường"],"h1":"Làn của bạn sắp không còn nữa.","h2":"Khi biển báo làn của bạn sắp hết, bạn cần bật xi-nhan và chuyển sang làn bên cạnh khi an toàn.","p":"Đúng rồi. Khi làn của bạn hết, hãy chuyển làn an toàn."},"tl":{"q":"Nasa kanang linya ka. Nakasulat sa karatula ang “RIGHT LANE ENDS” (Matatapos ang kanang linya). Ano ang dapat mong gawin?","o":["Lumipat sa kaliwa kapag ligtas na","Bumilis para mauna sa iba","Huminto sa dulo ng linya","Magmaneho sa gilid ng kalsada"],"h1":"Mawawala na sa lalong madaling panahon ang linya mo.","h2":"Kapag sinasabi ng karatula na matatapos ang linya mo, dapat kang mag-signal at lumipat sa katabing linya kapag ligtas na.","p":"Tama. Kapag natatapos ang linya mo, lumipat nang ligtas."},"ar":{"q":"أنت في المسار الأيمن. لافتة مكتوب عليها «RIGHT LANE ENDS» (المسار الأيمن ينتهي). ماذا يجب أن تفعل؟","o":["انتقل إلى اليسار عندما يكون ذلك آمنًا","زد السرعة لتبقى أمام الآخرين","توقف في نهاية المسار","قُد على كتف الطريق"],"h1":"مسارك سيختفي قريبًا.","h2":"عندما تقول اللافتة إن مسارك ينتهي، يجب أن تشغّل الإشارة وتنتقل إلى المسار المجاور عندما يكون ذلك آمنًا.","p":"صحيح. عندما ينتهي مسارك، انتقل إلى مسار آخر بأمان."},"ht":{"q":"Ou nan koulwa dwat la. Yon siy di “RIGHT LANE ENDS” (koulwa dwat la fini). Kisa ou dwe fè?","o":["Pase agoch lè sa an sekirite","Akselere pou rete devan lòt yo","Kanpe nan bout koulwa a","Kondui sou arebò wout la"],"h1":"Koulwa ou a pral disparèt talè.","h2":"Lè siy la di koulwa ou a fini, ou dwe mete siyal epi pase nan lòt koulwa a lè sa an sekirite.","p":"Se sa. Lè koulwa ou fini, chanje koulwa an sekirite."},"ref":{"doc":"FL","page":49}},{"id":"signs-025","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"DIVIDED HIGHWAY"},"c":1,"en":{"q":"A warning sign says a divided highway begins. What changes ahead?","o":["The road comes to an end","A median will separate the two directions","The speed limit goes up","Two lanes become one lane"],"h1":"Think about what divides the road.","h2":"A divided highway begins sign means a median will soon separate traffic going each way, so keep to the right of it.","p":"Right. A median will separate the two directions."},"es":{"q":"Una señal de advertencia dice que empieza una carretera dividida. ¿Qué cambia más adelante?","o":["La vía se termina","Una isla o divisor va a separar los dos sentidos","El límite de velocidad sube","Dos carriles se vuelven uno"],"h1":"Piense en qué divide la vía.","h2":"La señal de que empieza una carretera dividida significa que pronto un divisor va a separar el tráfico de cada sentido, así que manténgase a la derecha de él.","p":"Correcto. Un divisor va a separar los dos sentidos."},"zh":{"q":"一个警告标志说分隔公路开始了。前方有什么变化？","o":["道路到头了","中央隔离带会把两个方向的车分开","限速提高","两条车道变成一条"],"h1":"想一想：是什么把道路分开。","h2":"“分隔公路开始” 标志表示很快会有中央隔离带把两个方向的车流分开，所以要从隔离带右边行驶。","p":"对。中央隔离带会把两个方向的车分开。"},"vi":{"q":"Một biển cảnh báo cho biết đường có dải phân cách bắt đầu. Phía trước có gì thay đổi?","o":["Con đường sắp hết","Một dải phân cách sẽ chia hai chiều xe ra","Giới hạn tốc độ tăng lên","Hai làn nhập thành một làn"],"h1":"Hãy nghĩ xem cái gì chia con đường ra.","h2":"Biển báo đường có dải phân cách bắt đầu nghĩa là sắp có một dải phân cách tách xe chạy mỗi chiều, nên bạn cần đi ở bên phải của nó.","p":"Đúng rồi. Một dải phân cách sẽ chia hai chiều xe ra."},"tl":{"q":"Sinasabi ng isang karatula ng babala na nagsisimula ang divided highway. Ano ang magbabago sa unahan?","o":["Matatapos na ang kalsada","May median na maghihiwalay sa dalawang direksyon","Tataas ang speed limit","Ang dalawang linya ay magiging isang linya"],"h1":"Isipin kung ano ang naghahati sa kalsada.","h2":"Ang karatula na nagsisimula ang divided highway ay nangangahulugang may median na maghihiwalay sa trapikong papunta sa magkabilang direksyon, kaya manatili ka sa kanan nito.","p":"Tama. May median na maghihiwalay sa dalawang direksyon."},"ar":{"q":"لافتة تحذير تقول إن طريقًا سريعًا مقسومًا يبدأ. ما الذي يتغيّر في الأمام؟","o":["الطريق ينتهي","جزيرة وسطية ستفصل بين الاتجاهين","حد السرعة يرتفع","مساران يصبحان مسارًا واحدًا"],"h1":"فكّر في ما يقسم الطريق.","h2":"لافتة بداية الطريق السريع المقسوم تعني أن جزيرة وسطية ستفصل قريبًا بين السيارات في كل اتجاه، لذلك ابقَ على يمينها.","p":"صحيح. جزيرة وسطية ستفصل بين الاتجاهين."},"ht":{"q":"Yon siy avètisman di yon wout ki gen separasyon kòmanse. Kisa ki chanje pi devan?","o":["Wout la fini","Yon separasyon pral separe de direksyon yo","Limit vitès la monte","De koulwa vin tounen yon sèl"],"h1":"Panse ak sa ki separe wout la.","h2":"Siy sa a vle di talè gen yon separasyon nan mitan wout la k ap separe machin k ap ale nan chak direksyon, kidonk rete sou bò dwat li.","p":"Se sa. Yon separasyon pral separe de direksyon yo."},"ref":{"doc":"FL","page":49}},{"id":"signs-026","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"DIVIDED HIGHWAY ENDS"},"c":2,"en":{"q":"A sign says the divided highway ends. What should you expect?","o":["You may now pass on the right","The road becomes one-way","Cars coming toward you with no divider","A bridge is just ahead"],"h1":"Think about what happens when the median is gone.","h2":"When the divided highway ends, there is no median anymore, so cars going the other way will be right beside you and you must keep right.","p":"Right. With no divider, oncoming cars share the road with you."},"es":{"q":"Una señal dice que termina la carretera dividida. ¿Qué debe esperar?","o":["Ahora puede rebasar por la derecha","La vía se vuelve de un solo sentido","Carros que vienen de frente sin divisor","Un puente justo adelante"],"h1":"Piense en lo que pasa cuando ya no hay divisor.","h2":"Cuando termina la carretera dividida, ya no hay divisor, así que los carros que van en el otro sentido pasarán a su lado y usted debe mantenerse a la derecha.","p":"Correcto. Sin divisor, los carros de frente comparten la vía con usted."},"zh":{"q":"一个标志说分隔公路结束了。你应该预料到什么？","o":["现在可以从右边超车","道路变成单行道","对面来车，中间没有隔离","前方马上有一座桥"],"h1":"想一想：没有中央隔离带后会怎样。","h2":"分隔公路结束后就没有中央隔离带了，所以对面开来的车就在你旁边，你必须靠右行驶。","p":"对。没有隔离带，对面来车和你共用道路。"},"vi":{"q":"Một biển cho biết đường có dải phân cách kết thúc. Bạn nên chờ đợi điều gì?","o":["Bây giờ bạn được vượt bên phải","Con đường trở thành đường một chiều","Xe chạy ngược chiều về phía bạn mà không có gì ngăn cách","Ngay phía trước có cây cầu"],"h1":"Hãy nghĩ xem điều gì xảy ra khi không còn dải phân cách.","h2":"Khi đường có dải phân cách kết thúc, không còn dải phân cách nữa, nên xe chạy ngược chiều sẽ ở ngay cạnh bạn và bạn phải đi bên phải.","p":"Đúng rồi. Không có dải phân cách, xe ngược chiều chạy chung đường với bạn."},"tl":{"q":"Sinasabi ng isang karatula na matatapos na ang divided highway. Ano ang dapat mong asahan?","o":["Puwede ka nang mag-overtake sa kanan","Magiging one-way ang kalsada","Mga sasakyang paparating sa iyo na walang harang sa gitna","May tulay sa unahan"],"h1":"Isipin kung ano ang mangyayari kapag wala na ang median.","h2":"Kapag natapos ang divided highway, wala nang median, kaya ang mga sasakyang papunta sa kabilang direksyon ay nasa tabi mo na mismo at dapat kang manatili sa kanan.","p":"Tama. Kapag walang harang, kasama mo sa kalsada ang mga paparating na sasakyan."},"ar":{"q":"لافتة تقول إن الطريق السريع المقسوم ينتهي. ماذا يجب أن تتوقع؟","o":["الآن يمكنك أن تتجاوز من اليمين","الطريق يصبح باتجاه واحد","سيارات تأتي نحوك بدون فاصل","جسر قريب جدًا في الأمام"],"h1":"فكّر في ما يحدث عندما تختفي الجزيرة الوسطية.","h2":"عندما ينتهي الطريق السريع المقسوم لا توجد جزيرة وسطية بعد ذلك، لذلك ستكون السيارات القادمة من الاتجاه الآخر بجانبك مباشرة، ويجب أن تلزم اليمين.","p":"صحيح. بدون فاصل، السيارات القادمة تشاركك الطريق."},"ht":{"q":"Yon siy di wout ki gen separasyon an fini. Kisa ou dwe atann?","o":["Kounye a ou ka double sou bò dwat","Wout la vin yon sèl direksyon","Machin k ap vin sou ou san anyen pou separe nou","Gen yon pon touprè"],"h1":"Panse ak sa k ap pase lè separasyon an pa la ankò.","h2":"Lè wout ki gen separasyon an fini, pa gen separasyon ankò, kidonk machin k ap ale nan lòt direksyon an ap pase bò kote ou, e ou dwe rete adwat.","p":"Se sa. San separasyon, machin k ap vin sou ou pataje wout la avè ou."},"ref":{"doc":"FL","page":49}},{"id":"signs-027","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"SLIPPERY WHEN WET"},"c":0,"en":{"q":"A sign says SLIPPERY WHEN WET. It is raining. What should you do?","o":["Slow down and avoid sudden moves","Turn on cruise control","Speed up to get past the area","Brake hard if the car slides"],"h1":"Think about how tires grip a wet road.","h2":"A wet road can be slick, so you should slow down and avoid quick turns or hard braking.","p":"Right. On a slippery road, slow down and move smoothly."},"es":{"q":"Una señal dice SLIPPERY WHEN WET (resbaloso cuando está mojado). Está lloviendo. ¿Qué debe hacer?","o":["Bajar la velocidad y evitar movimientos bruscos","Prender el control de velocidad","Acelerar para pasar rápido esa zona","Frenar fuerte si el carro resbala"],"h1":"Piense en cómo agarran las llantas en una vía mojada.","h2":"Una vía mojada puede estar resbalosa, así que usted debe bajar la velocidad y evitar vueltas rápidas o frenazos.","p":"Correcto. En una vía resbalosa, baje la velocidad y maneje con suavidad."},"zh":{"q":"一个标志写着 “SLIPPERY WHEN WET”（路湿易滑）。现在正在下雨。你应该怎么做？","o":["减速，避免突然的动作","打开定速巡航","加速，快快开过这一段","车打滑时用力刹车"],"h1":"想一想：轮胎在湿路上抓地怎么样。","h2":"湿的路面可能很滑，所以你要减速，避免急转弯或急刹车。","p":"对。路滑时要减速，动作要平稳。"},"vi":{"q":"Một biển ghi “SLIPPERY WHEN WET” (Trơn khi ướt). Trời đang mưa. Bạn nên làm gì?","o":["Chạy chậm lại và tránh cử động đột ngột","Bật chế độ tự giữ tốc độ (cruise control)","Tăng tốc để qua khu vực này","Đạp thắng mạnh nếu xe bị trượt"],"h1":"Hãy nghĩ xem bánh xe bám đường ướt như thế nào.","h2":"Đường ướt có thể trơn, nên bạn cần chạy chậm lại và tránh rẽ gấp hoặc đạp thắng mạnh.","p":"Đúng rồi. Trên đường trơn, hãy chạy chậm và lái nhẹ nhàng."},"tl":{"q":"Nakasulat sa karatula ang “SLIPPERY WHEN WET” (Madulas kapag basa). Umuulan. Ano ang dapat mong gawin?","o":["Bumagal at iwasan ang biglang galaw","Buksan ang cruise control","Bumilis para malampasan ang lugar","Pumreno nang malakas kapag dumulas ang sasakyan"],"h1":"Isipin kung paano kumakapit ang gulong sa basang kalsada.","h2":"Ang basang kalsada ay maaaring madulas, kaya dapat kang bumagal at iwasan ang mabilis na pagliko o malakas na pagpreno.","p":"Tama. Sa madulas na kalsada, bumagal at gumalaw nang maayos at dahan-dahan."},"ar":{"q":"لافتة مكتوب عليها «SLIPPERY WHEN WET» (زلق عند البلل). المطر ينزل. ماذا يجب أن تفعل؟","o":["خفف السرعة وتجنّب الحركات المفاجئة","شغّل مثبّت السرعة","زد السرعة لتتجاوز المنطقة","اضغط الفرامل بقوة إذا انزلقت السيارة"],"h1":"فكّر في كيف تمسك الإطارات بالطريق المبلل.","h2":"الطريق المبلل قد يكون زلقًا، لذلك يجب أن تخفف السرعة وتتجنب الانعطاف السريع أو الضغط القوي على الفرامل.","p":"صحيح. على الطريق الزلق، خفف السرعة وتحرك بهدوء."},"ht":{"q":"Yon siy di “SLIPPERY WHEN WET” (glise lè l mouye). Lapli ap tonbe. Kisa ou dwe fè?","o":["Ralanti epi evite fè mouvman brid sou kou","Limen kontwòl vitès otomatik la","Akselere pou pase zòn nan vit","Frennen fò si machin nan glise"],"h1":"Panse ki jan kawotchou yo kenbe sou yon wout mouye.","h2":"Yon wout mouye ka glise, kidonk ou dwe ralanti epi evite vire vit oswa frennen fò.","p":"Se sa. Sou yon wout ki glise, ralanti epi kondui dousman."},"ref":{"doc":"FL","page":50}},{"id":"signs-028","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"SIGNAL AHEAD"},"c":1,"en":{"q":"A yellow sign shows a traffic light. What does it warn you about?","o":["A stop sign is ahead","A traffic signal is ahead","A railroad is ahead","A police checkpoint is ahead"],"h1":"Look at the picture on the sign.","h2":"This sign warns that a traffic signal is ahead, so be ready to slow down or stop.","p":"Right. The sign warns that a traffic light is ahead."},"es":{"q":"Una señal amarilla muestra un semáforo. ¿De qué le avisa?","o":["Hay una señal de pare más adelante","Hay un semáforo más adelante","Hay un tren más adelante","Hay un retén de policía más adelante"],"h1":"Mire el dibujo en la señal.","h2":"Esta señal avisa que hay un semáforo más adelante, así que esté listo para bajar la velocidad o pararse.","p":"Correcto. La señal avisa que hay un semáforo más adelante."},"zh":{"q":"一个黄色标志上画着红绿灯。它提醒你什么？","o":["前方有停车标志","前方有交通信号灯","前方有铁路","前方有警察检查站"],"h1":"看看标志上的图。","h2":"这个标志提醒你前方有交通信号灯，所以要准备减速或停车。","p":"对。这个标志提醒你前方有红绿灯。"},"vi":{"q":"Một biển màu vàng có hình đèn giao thông. Biển này cảnh báo bạn về điều gì?","o":["Phía trước có biển dừng","Phía trước có đèn giao thông","Phía trước có đường sắt","Phía trước có trạm kiểm tra của cảnh sát"],"h1":"Hãy nhìn hình vẽ trên biển.","h2":"Biển này cảnh báo phía trước có đèn giao thông, nên bạn cần sẵn sàng chạy chậm lại hoặc dừng.","p":"Đúng rồi. Biển này cảnh báo phía trước có đèn giao thông."},"tl":{"q":"Ang dilaw na karatula ay nagpapakita ng ilaw trapiko. Tungkol saan ang babala nito?","o":["May “STOP” sign sa unahan","May ilaw trapiko sa unahan","May riles ng tren sa unahan","May checkpoint ng pulis sa unahan"],"h1":"Tingnan ang larawan sa karatula.","h2":"Ang karatulang ito ay babala na may ilaw trapiko sa unahan, kaya maging handang bumagal o huminto.","p":"Tama. Ang karatula ay babala na may ilaw trapiko sa unahan."},"ar":{"q":"لافتة صفراء تُظهر إشارة مرور ضوئية. ممّ تحذّرك؟","o":["لافتة «STOP» (قف) في الأمام","إشارة مرور ضوئية في الأمام","سكة حديد في الأمام","نقطة تفتيش للشرطة في الأمام"],"h1":"انظر إلى الصورة على اللافتة.","h2":"هذه اللافتة تحذّر من أن إشارة مرور ضوئية في الأمام، لذلك كن مستعدًا لتخفيف السرعة أو للتوقف.","p":"صحيح. اللافتة تحذّر من أن إشارة ضوئية في الأمام."},"ht":{"q":"Yon siy jòn montre yon limyè trafik. Pou kisa li avèti ou?","o":["Gen yon siy “STOP” pi devan","Gen yon limyè trafik pi devan","Gen yon ray tren pi devan","Gen yon baryè polis pi devan"],"h1":"Gade foto ki sou siy la.","h2":"Siy sa a avèti ou gen yon limyè trafik pi devan, kidonk pare pou ralanti oswa kanpe.","p":"Se sa. Siy la avèti ou gen yon limyè trafik pi devan."},"ref":{"doc":"FL","page":49}},{"id":"signs-029","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"DEER CROSSING"},"c":2,"en":{"q":"A yellow sign shows a deer. What should you do?","o":["Look for a nearby zoo","Pull over and wait","Watch for deer near or on the road","Speed up through the area"],"h1":"Animals may run onto the road with no warning.","h2":"A deer crossing sign means deer often cross there, so you should slow down and watch the sides of the road, especially at dawn and dusk.","p":"Right. Watch for deer near the road."},"es":{"q":"Una señal amarilla muestra un venado. ¿Qué debe hacer?","o":["Buscar un zoológico cerca","Orillarse y esperar","Estar atento a venados cerca o en la vía","Acelerar para pasar la zona"],"h1":"Los animales pueden salir a la vía sin aviso.","h2":"Una señal de cruce de venados quiere decir que los venados cruzan seguido por ahí, así que usted debe bajar la velocidad y mirar los lados de la vía, sobre todo al amanecer y al anochecer.","p":"Correcto. Esté atento a los venados cerca de la vía."},"zh":{"q":"一个黄色标志上画着一只鹿。你应该怎么做？","o":["找找附近的动物园","靠边停车等待","注意路边或路上的鹿","加速开过这一段"],"h1":"动物可能突然跑到路上。","h2":"鹿出没标志表示鹿常在这里过马路，所以你要减速，注意路的两边，特别是在清晨和傍晚。","p":"对。注意路边的鹿。"},"vi":{"q":"Một biển màu vàng có hình con nai. Bạn nên làm gì?","o":["Tìm sở thú gần đó","Tấp vào lề và chờ","Chú ý nai ở gần hoặc trên đường","Tăng tốc qua khu vực này"],"h1":"Thú vật có thể chạy ra đường mà không báo trước.","h2":"Biển nai băng qua đường nghĩa là nai thường đi qua chỗ đó, nên bạn cần chạy chậm lại và nhìn hai bên đường, nhất là lúc bình minh và hoàng hôn.","p":"Đúng rồi. Hãy chú ý nai ở gần đường."},"tl":{"q":"Ang dilaw na karatula ay nagpapakita ng usa. Ano ang dapat mong gawin?","o":["Hanapin ang zoo sa malapit","Tumabi at maghintay","Mag-ingat sa mga usa malapit o nasa kalsada","Bumilis sa lugar na iyon"],"h1":"Maaaring tumakbo ang mga hayop papunta sa kalsada nang walang babala.","h2":"Ang karatula ng tawiran ng usa ay nangangahulugang madalas tumawid ang mga usa doon, kaya dapat kang bumagal at bantayan ang gilid ng kalsada, lalo na sa madaling-araw at takipsilim.","p":"Tama. Mag-ingat sa mga usa malapit sa kalsada."},"ar":{"q":"لافتة صفراء تُظهر غزالًا. ماذا يجب أن تفعل؟","o":["ابحث عن حديقة حيوانات قريبة","توقف على جانب الطريق وانتظر","انتبه للغزلان قرب الطريق أو عليه","زد السرعة في هذه المنطقة"],"h1":"الحيوانات قد تركض إلى الطريق بدون إنذار.","h2":"لافتة عبور الغزلان تعني أن الغزلان تعبر هناك كثيرًا، لذلك يجب أن تخفف السرعة وتراقب جانبي الطريق، خاصة عند الفجر وعند الغروب.","p":"صحيح. انتبه للغزلان قرب الطريق."},"ht":{"q":"Yon siy jòn montre yon sèf. Kisa ou dwe fè?","o":["Chèche yon zoo ki toupre","Rale sou kote epi tann","Veye si gen sèf toupre wout la oswa sou wout la","Akselere pou travèse zòn nan"],"h1":"Bèt ka kouri antre sou wout la san avètisman.","h2":"Yon siy sèf vle di sèf konn travèse la a, kidonk ou dwe ralanti epi gade de bò wout la, sitou lè solèy ap leve ak lè l ap kouche.","p":"Se sa. Veye si gen sèf toupre wout la."},"ref":{"doc":"FL","page":50}},{"id":"signs-030","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"LOW CLEARANCE"},"c":3,"en":{"q":"A sign warns of LOW CLEARANCE ahead. What does it mean?","o":["The road gets narrow","The shoulder is soft","A steep hill is ahead","A low bridge or overpass is ahead"],"h1":"Clearance is the space above your vehicle.","h2":"A low clearance sign means a bridge or overpass ahead is low, so tall vehicles may not fit under it.","p":"Right. Low clearance means a low bridge or overpass is ahead."},"es":{"q":"Una señal avisa LOW CLEARANCE (altura baja) más adelante. ¿Qué significa?","o":["La vía se hace angosta","El acotamiento está blando","Hay una cuesta empinada","Hay un puente o paso elevado bajo"],"h1":"Piense en el espacio que hay encima de su vehículo.","h2":"Una señal de altura baja quiere decir que un puente o paso elevado más adelante es bajo, así que los vehículos altos podrían no caber.","p":"Correcto. Altura baja significa que hay un puente o paso elevado bajo."},"zh":{"q":"一个标志提醒前方 “LOW CLEARANCE”（限高）。它是什么意思？","o":["道路变窄","路肩很软","前方有陡坡","前方有很低的桥或天桥"],"h1":"“Clearance” 是你的车上方的空间。","h2":"限高标志表示前方的桥或天桥很低，所以高的车辆可能过不去。","p":"对。限高表示前方有很低的桥或天桥。"},"vi":{"q":"Một biển cảnh báo “LOW CLEARANCE” (Chiều cao thấp) phía trước. Biển này có nghĩa là gì?","o":["Đường hẹp lại","Lề đường bị mềm","Phía trước có dốc cao","Phía trước có cầu hoặc cầu vượt thấp"],"h1":"Chiều cao ở đây là khoảng trống phía trên xe của bạn.","h2":"Biển chiều cao thấp nghĩa là cây cầu hoặc cầu vượt phía trước thấp, nên xe cao có thể không chui qua được.","p":"Đúng rồi. Chiều cao thấp nghĩa là phía trước có cầu hoặc cầu vượt thấp."},"tl":{"q":"May karatula na nagbababala ng “LOW CLEARANCE” (Mababang puwang sa itaas) sa unahan. Ano ang ibig sabihin nito?","o":["Kikitid ang kalsada","Malambot ang gilid ng kalsada","May matarik na burol sa unahan","May mababang tulay o overpass sa unahan"],"h1":"Ang clearance ay ang puwang sa itaas ng sasakyan mo.","h2":"Ang “LOW CLEARANCE” na karatula ay nangangahulugang mababa ang tulay o overpass sa unahan, kaya maaaring hindi kumasya sa ilalim nito ang matataas na sasakyan.","p":"Tama. Ang “LOW CLEARANCE” ay nangangahulugang may mababang tulay o overpass sa unahan."},"ar":{"q":"لافتة تحذّر من «LOW CLEARANCE» (ارتفاع منخفض) في الأمام. ماذا تعني؟","o":["الطريق يضيق","كتف الطريق طري","منحدر حاد في الأمام","جسر منخفض أو جسر علوي منخفض في الأمام"],"h1":"الارتفاع هنا هو المسافة فوق سيارتك.","h2":"لافتة الارتفاع المنخفض تعني أن جسرًا أو جسرًا علويًا في الأمام منخفض، لذلك قد لا تستطيع المركبات العالية أن تمر تحته.","p":"صحيح. الارتفاع المنخفض يعني جسرًا أو جسرًا علويًا منخفضًا في الأمام."},"ht":{"q":"Yon siy avèti “LOW CLEARANCE” (wotè ba) pi devan. Kisa li vle di?","o":["Wout la vin etwat","Arebò wout la mou","Gen yon mòn ki apik pi devan","Gen yon pon oswa yon pasaj anlè ki ba pi devan"],"h1":"Wotè a se espas ki anwo machin ou.","h2":"Yon siy “LOW CLEARANCE” vle di yon pon oswa yon pasaj anlè pi devan ba, kidonk machin ki wo yo ka pa pase anba l.","p":"Se sa. “LOW CLEARANCE” vle di gen yon pon oswa yon pasaj anlè ki ba pi devan."},"ref":{"doc":"FL","page":50}},{"id":"signs-031","scope":"US","cat":"signs","sign":{"shape":"school","text":"SCHOOL"},"c":0,"en":{"q":"You see a school crossing sign. What should you do?","o":["Slow down and watch for children","Honk to warn the children","Speed up to clear the area","Change lanes to go around"],"h1":"Children can be hard to see and may move fast.","h2":"A school crossing sign means children may be crossing, so you should slow down and be ready to stop.","p":"Right. At a school crossing, slow down and watch for children."},"es":{"q":"Usted ve una señal de cruce escolar. ¿Qué debe hacer?","o":["Bajar la velocidad y estar atento a los niños","Tocar la bocina para avisar a los niños","Acelerar para pasar la zona","Cambiar de carril para rodear"],"h1":"Los niños pueden ser difíciles de ver y moverse rápido.","h2":"Una señal de cruce escolar quiere decir que puede haber niños cruzando, así que usted debe bajar la velocidad y estar listo para parar.","p":"Correcto. En un cruce escolar, baje la velocidad y esté atento a los niños."},"zh":{"q":"你看到一个学校人行横道标志。你应该怎么做？","o":["减速，注意儿童","按喇叭提醒孩子们","加速快快开过","换车道绕过去"],"h1":"儿童不容易看到，而且可能动得很快。","h2":"学校人行横道标志表示可能有儿童过马路，所以你要减速，准备停车。","p":"对。在学校人行横道，要减速并注意儿童。"},"vi":{"q":"Bạn thấy biển báo chỗ học sinh qua đường. Bạn nên làm gì?","o":["Chạy chậm lại và chú ý trẻ em","Bấm còi để báo cho trẻ em","Tăng tốc để qua khu vực này","Đổi làn để chạy vòng qua"],"h1":"Trẻ em có thể khó thấy và có thể chạy rất nhanh.","h2":"Biển chỗ học sinh qua đường nghĩa là trẻ em có thể đang băng qua, nên bạn cần chạy chậm lại và sẵn sàng dừng.","p":"Đúng rồi. Ở chỗ học sinh qua đường, hãy chạy chậm và chú ý trẻ em."},"tl":{"q":"May nakita kang karatula ng tawiran ng mga estudyante. Ano ang dapat mong gawin?","o":["Bumagal at mag-ingat sa mga bata","Bumusina para bigyang-babala ang mga bata","Bumilis para malampasan ang lugar","Lumipat ng linya para lumihis"],"h1":"Mahirap makita ang mga bata at maaari silang gumalaw nang mabilis.","h2":"Ang karatula ng tawiran ng mga estudyante ay nangangahulugang maaaring may mga batang tumatawid, kaya dapat kang bumagal at maging handang huminto.","p":"Tama. Sa tawiran ng mga estudyante, bumagal at mag-ingat sa mga bata."},"ar":{"q":"ترى لافتة معبر مدرسة. ماذا يجب أن تفعل؟","o":["خفف السرعة وانتبه للأطفال","استخدم البوق لتحذير الأطفال","زد السرعة لتخرج من المنطقة","غيّر المسار لتمر من حولهم"],"h1":"الأطفال قد يكون من الصعب رؤيتهم، وقد يتحركون بسرعة.","h2":"لافتة معبر المدرسة تعني أن أطفالًا قد يعبرون، لذلك يجب أن تخفف السرعة وتكون مستعدًا للتوقف.","p":"صحيح. عند معبر المدرسة، خفف السرعة وانتبه للأطفال."},"ht":{"q":"Ou wè yon siy kote timoun lekòl travèse. Kisa ou dwe fè?","o":["Ralanti epi veye timoun yo","Klaksonen pou avèti timoun yo","Akselere pou kite zòn nan","Chanje koulwa pou pase bò kote yo"],"h1":"Timoun ka difisil pou wè epi yo ka deplase vit.","h2":"Yon siy kote timoun lekòl travèse vle di timoun ka ap travèse, kidonk ou dwe ralanti epi pare pou kanpe.","p":"Se sa. Kote timoun lekòl travèse, ralanti epi veye timoun yo."},"ref":{"doc":"FL","page":57}},{"id":"signs-032","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"SPEED LIMIT WHEN FLASHING"},"c":1,"en":{"q":"A school zone speed sign has yellow lights that are flashing. What does that mean?","o":["The lower speed is only a suggestion","The lower school speed limit is in effect now","School is closed today","Only school buses must slow down"],"h1":"The lights tell you when the sign applies.","h2":"When the lights on a school zone sign are flashing, the lower school speed limit is the law right now, so you must slow down to it.","p":"Right. Flashing lights mean the school speed limit applies now."},"es":{"q":"Una señal de velocidad en zona escolar tiene luces amarillas intermitentes. ¿Qué significa?","o":["La velocidad baja es solo una sugerencia","El límite escolar más bajo está vigente ahora","Hoy no hay clases","Solo los autobuses escolares deben ir más despacio"],"h1":"Las luces le dicen cuándo aplica la señal.","h2":"Cuando las luces de una señal de zona escolar están intermitentes, el límite escolar más bajo es la ley en ese momento, así que usted debe bajar a esa velocidad.","p":"Correcto. Las luces intermitentes significan que el límite escolar aplica ahora."},"zh":{"q":"学校区限速标志上的黄灯在闪。这是什么意思？","o":["较低的速度只是建议","较低的学校区限速现在生效","学校今天放假","只有校车要减速"],"h1":"灯告诉你这个标志什么时候有效。","h2":"学校区标志上的灯在闪时，较低的学校区限速现在就是法律，所以你必须减速到这个速度。","p":"对。灯在闪表示学校区限速现在生效。"},"vi":{"q":"Biển tốc độ khu vực trường học có đèn vàng đang nhấp nháy. Điều đó có nghĩa là gì?","o":["Tốc độ thấp hơn chỉ là lời khuyên","Giới hạn tốc độ thấp hơn của trường học đang có hiệu lực ngay bây giờ","Hôm nay trường nghỉ học","Chỉ xe buýt trường học phải chạy chậm"],"h1":"Đèn cho bạn biết khi nào biển có hiệu lực.","h2":"Khi đèn trên biển khu vực trường học nhấp nháy, giới hạn tốc độ thấp hơn của trường học là luật ngay lúc đó, nên bạn phải chạy chậm lại theo tốc độ đó.","p":"Đúng rồi. Đèn nhấp nháy nghĩa là giới hạn tốc độ trường học có hiệu lực ngay bây giờ."},"tl":{"q":"Ang karatula ng bilis sa school zone ay may dilaw na ilaw na kumikislap. Ano ang ibig sabihin nito?","o":["Mungkahi lang ang mas mababang bilis","Ipinapatupad na ngayon ang mas mababang speed limit sa paaralan","Sarado ang paaralan ngayong araw","Mga school bus lang ang dapat bumagal"],"h1":"Sinasabi ng mga ilaw kung kailan ipinapatupad ang karatula.","h2":"Kapag kumikislap ang mga ilaw sa karatula ng school zone, ang mas mababang speed limit sa paaralan ay batas na sa oras na iyon, kaya dapat kang bumagal sa bilis na iyon.","p":"Tama. Ang kumikislap na ilaw ay nangangahulugang ipinapatupad na ngayon ang speed limit sa paaralan."},"ar":{"q":"لافتة سرعة في منطقة مدرسة عليها أضواء صفراء تومض. ماذا يعني ذلك؟","o":["السرعة المنخفضة مجرد اقتراح","حد السرعة المنخفض للمدرسة مطبّق الآن","المدرسة مغلقة اليوم","حافلات المدارس فقط يجب أن تخفف السرعة"],"h1":"الأضواء تخبرك متى تكون اللافتة مطبّقة.","h2":"عندما تومض الأضواء على لافتة منطقة المدرسة، يكون حد السرعة المنخفض للمدرسة هو القانون الآن، لذلك يجب أن تخفف سرعتك إليه.","p":"صحيح. الأضواء الوامضة تعني أن حد سرعة المدرسة مطبّق الآن."},"ht":{"q":"Yon siy vitès zòn lekòl gen limyè jòn k ap kliyote. Kisa sa vle di?","o":["Vitès ki pi ba a se yon konsèy sèlman","Limit vitès lekòl ki pi ba a an aplikasyon kounye a","Lekòl la fèmen jodi a","Se sèlman bis lekòl ki dwe ralanti"],"h1":"Limyè yo di ou ki lè siy la an aplikasyon.","h2":"Lè limyè ki sou siy zòn lekòl la ap kliyote, limit vitès lekòl ki pi ba a se lalwa kounye a, kidonk ou dwe ralanti rive nan vitès sa a.","p":"Se sa. Limyè k ap kliyote vle di limit vitès lekòl la an aplikasyon kounye a."},"ref":{"doc":"FL","page":57}},{"id":"signs-033","scope":"US","cat":"signs","sign":{"shape":"crossbuck","text":"RAILROAD CROSSING"},"c":2,"en":{"q":"At a railroad crossing, the red lights are flashing. What must you do?","o":["Slow down and cross with care","Go if you do not see a train","Stop and wait until the lights stop","Drive around the gate"],"h1":"Flashing red lights at the tracks mean a train is coming.","h2":"Flashing red lights at a railroad crossing mean a train is near, so you must stop and wait until the lights stop flashing.","p":"Right. Flashing red lights at the tracks mean stop and wait."},"es":{"q":"En un cruce de tren, las luces rojas están intermitentes. ¿Qué debe hacer?","o":["Bajar la velocidad y cruzar con cuidado","Seguir si no ve un tren","Pararse y esperar hasta que las luces se apaguen","Rodear la barrera"],"h1":"Las luces rojas intermitentes en la vía del tren significan que viene un tren.","h2":"Las luces rojas intermitentes en un cruce de tren quieren decir que un tren está cerca, así que usted debe pararse y esperar hasta que las luces dejen de parpadear.","p":"Correcto. Luces rojas intermitentes en la vía significan parar y esperar."},"zh":{"q":"在铁路道口，红灯在闪。你必须怎么做？","o":["减速，小心通过","没看到火车就走","停车，等灯不闪了再走","绕过栏杆开过去"],"h1":"铁轨旁的红灯在闪，表示火车要来了。","h2":"铁路道口的红灯在闪，表示火车就在附近，所以你必须停车，等灯不闪了再走。","p":"对。铁轨旁红灯闪表示停车等待。"},"vi":{"q":"Tại chỗ băng qua đường sắt, đèn đỏ đang nhấp nháy. Bạn phải làm gì?","o":["Chạy chậm lại và băng qua cẩn thận","Đi nếu bạn không thấy tàu","Dừng lại và chờ tới khi đèn hết nhấp nháy","Chạy vòng qua thanh chắn"],"h1":"Đèn đỏ nhấp nháy ở đường ray nghĩa là có tàu đang tới.","h2":"Đèn đỏ nhấp nháy ở chỗ băng qua đường sắt nghĩa là tàu đang ở gần, nên bạn phải dừng lại và chờ tới khi đèn hết nhấp nháy.","p":"Đúng rồi. Đèn đỏ nhấp nháy ở đường ray nghĩa là dừng lại và chờ."},"tl":{"q":"Sa tawiran ng tren, kumikislap ang mga pulang ilaw. Ano ang dapat mong gawin?","o":["Bumagal at tumawid nang maingat","Tumawid kung wala kang nakikitang tren","Huminto at maghintay hanggang tumigil ang mga ilaw","Lumihis paikot sa harang"],"h1":"Ang kumikislap na pulang ilaw sa riles ay nangangahulugang may paparating na tren.","h2":"Ang kumikislap na pulang ilaw sa tawiran ng tren ay nangangahulugang malapit na ang tren, kaya dapat kang huminto at maghintay hanggang tumigil sa pagkislap ang mga ilaw.","p":"Tama. Ang kumikislap na pulang ilaw sa riles ay nangangahulugang huminto at maghintay."},"ar":{"q":"عند تقاطع سكة حديد، الأضواء الحمراء تومض. ماذا يجب أن تفعل؟","o":["خفف السرعة واعبر بحذر","انطلق إذا لم ترَ قطارًا","توقف وانتظر حتى تتوقف الأضواء","قُد حول الحاجز"],"h1":"الأضواء الحمراء الوامضة عند السكة تعني أن قطارًا قادم.","h2":"الأضواء الحمراء الوامضة عند تقاطع سكة الحديد تعني أن قطارًا قريب، لذلك يجب أن تتوقف وتنتظر حتى تتوقف الأضواء عن الوميض.","p":"صحيح. الأضواء الحمراء الوامضة عند السكة تعني: توقف وانتظر."},"ht":{"q":"Kote tren travèse a, limyè wouj yo ap kliyote. Kisa ou dwe fè?","o":["Ralanti epi travèse avèk prekosyon","Pase si ou pa wè tren","Kanpe epi tann jiskaske limyè yo sispann","Pase bò kote baryè a"],"h1":"Limyè wouj k ap kliyote bò ray yo vle di gen yon tren k ap vini.","h2":"Limyè wouj k ap kliyote kote tren travèse vle di gen yon tren toupre, kidonk ou dwe kanpe epi tann jiskaske limyè yo sispann kliyote.","p":"Se sa. Limyè wouj k ap kliyote bò ray yo vle di kanpe epi tann."},"ref":{"doc":"FL","page":56}},{"id":"signs-034","scope":"US","cat":"signs","sign":null,"c":3,"en":{"q":"The railroad gates are down, but you do not see a train. What should you do?","o":["Drive around the gates if it looks clear","Cross slowly with hazard lights on","Use the other lane to get past","Stay stopped until the gates go up"],"h1":"A train can be closer and faster than it looks.","h2":"When the gates are down, a train is coming even if you cannot see it, so you must stay stopped until the gates go all the way up.","p":"Right. Never go around the gates. Wait until they go up."},"es":{"q":"Las barreras del tren están abajo, pero usted no ve ningún tren. ¿Qué debe hacer?","o":["Rodear las barreras si parece libre","Cruzar despacio con las luces de emergencia","Usar el otro carril para pasar","Quedarse parado hasta que suban las barreras"],"h1":"Un tren puede estar más cerca y venir más rápido de lo que parece.","h2":"Cuando las barreras están abajo, viene un tren aunque usted no lo vea, así que debe quedarse parado hasta que las barreras suban por completo.","p":"Correcto. Nunca rodee las barreras. Espere a que suban."},"zh":{"q":"铁路道口的栏杆放下了，但你没看到火车。你应该怎么做？","o":["看起来没车就绕过栏杆","打开危险警示灯慢慢通过","用另一条车道开过去","一直停着，等栏杆升起"],"h1":"火车可能比看起来更近、更快。","h2":"栏杆放下时，就算你看不到火车，火车也正在开来，所以你必须一直停着，等栏杆完全升起。","p":"对。绝不要绕过栏杆。等栏杆升起。"},"vi":{"q":"Thanh chắn đường sắt đã hạ xuống, nhưng bạn không thấy tàu. Bạn nên làm gì?","o":["Chạy vòng qua thanh chắn nếu thấy đường trống","Băng qua chậm và bật đèn khẩn cấp","Dùng làn bên kia để đi qua","Đứng yên tới khi thanh chắn nâng lên"],"h1":"Tàu có thể ở gần hơn và chạy nhanh hơn bạn tưởng.","h2":"Khi thanh chắn đã hạ xuống, nghĩa là có tàu đang tới dù bạn không thấy, nên bạn phải đứng yên tới khi thanh chắn nâng lên hết.","p":"Đúng rồi. Không bao giờ chạy vòng qua thanh chắn. Hãy chờ tới khi nó nâng lên."},"tl":{"q":"Nakababa ang mga harang sa riles, pero wala kang nakikitang tren. Ano ang dapat mong gawin?","o":["Lumihis paikot sa mga harang kung mukhang walang tren","Tumawid nang dahan-dahan habang nakabukas ang hazard lights","Gamitin ang kabilang linya para makalampas","Manatiling nakahinto hanggang tumaas ang mga harang"],"h1":"Maaaring mas malapit at mas mabilis ang tren kaysa sa inaakala mo.","h2":"Kapag nakababa ang mga harang, may paparating na tren kahit hindi mo ito nakikita, kaya dapat kang manatiling nakahinto hanggang tuluyang tumaas ang mga harang.","p":"Tama. Huwag kailanman lumihis paikot sa mga harang. Maghintay hanggang tumaas ang mga ito."},"ar":{"q":"حواجز سكة الحديد نازلة، لكنك لا ترى قطارًا. ماذا يجب أن تفعل؟","o":["قُد حول الحواجز إذا بدا الطريق خاليًا","اعبر ببطء مع تشغيل أضواء التحذير","استخدم المسار الآخر لتمر","ابقَ متوقفًا حتى ترتفع الحواجز"],"h1":"القطار قد يكون أقرب وأسرع مما يبدو.","h2":"عندما تكون الحواجز نازلة فهناك قطار قادم حتى لو لم تره، لذلك يجب أن تبقى متوقفًا حتى ترتفع الحواجز بالكامل.","p":"صحيح. لا تمر أبدًا حول الحواجز. انتظر حتى ترتفع."},"ht":{"q":"Baryè tren yo desann, men ou pa wè okenn tren. Kisa ou dwe fè?","o":["Pase bò kote baryè yo si sanble pa gen anyen","Travèse dousman ak limyè ijans ou limen","Sèvi ak lòt koulwa a pou pase","Rete kanpe jiskaske baryè yo monte"],"h1":"Yon tren ka pi pre epi pi rapid pase jan li sanble.","h2":"Lè baryè yo desann, gen yon tren k ap vini menm si ou pa ka wè l, kidonk ou dwe rete kanpe jiskaske baryè yo monte nèt.","p":"Se sa. Pa janm pase bò kote baryè yo. Tann jiskaske yo monte."},"ref":{"doc":"FL","page":56}},{"id":"signs-035","scope":"US","cat":"signs","sign":{"shape":"crossbuck","text":"2 TRACKS"},"c":0,"en":{"q":"A small sign under the crossbuck says 2 TRACKS. What does it warn you about?","o":["After one train passes, another may come","Trains pass only two times a day","Two lanes of cars cross the tracks","You must wait two minutes to cross"],"h1":"Think about what could hide behind the first train.","h2":"The tracks sign tells you there is more than one track, so after one train passes you must look again, because a second train may be coming.","p":"Right. More than one track means another train may come."},"es":{"q":"Una señal pequeña debajo de la cruz de ferrocarril dice 2 TRACKS (2 vías). ¿De qué le avisa?","o":["Después de que pase un tren, puede venir otro","Los trenes pasan solo dos veces al día","Dos carriles de carros cruzan la vía","Debe esperar dos minutos para cruzar"],"h1":"Piense en lo que podría estar escondido detrás del primer tren.","h2":"La señal de vías le dice que hay más de una vía, así que después de que pase un tren usted debe volver a mirar, porque puede venir un segundo tren.","p":"Correcto. Más de una vía significa que puede venir otro tren."},"zh":{"q":"铁路交叉标志下面有一个小牌子写着 “2 TRACKS”（两条铁轨）。它提醒你什么？","o":["一列火车过去后，可能还有另一列","火车一天只过两次","有两条车道的车穿过铁轨","你必须等两分钟才能过"],"h1":"想一想：第一列火车后面可能藏着什么。","h2":"这个牌子告诉你这里不止一条铁轨，所以一列火车过去后，你必须再看一看，因为可能还有第二列火车开来。","p":"对。不止一条铁轨，表示可能还有另一列火车。"},"vi":{"q":"Một biển nhỏ dưới biển chữ X ghi “2 TRACKS” (2 đường ray). Biển này cảnh báo bạn về điều gì?","o":["Sau khi một tàu chạy qua, có thể có tàu khác tới","Tàu chỉ chạy qua hai lần mỗi ngày","Có hai làn xe hơi băng qua đường ray","Bạn phải chờ hai phút mới được băng qua"],"h1":"Hãy nghĩ xem cái gì có thể bị che khuất sau chiếc tàu đầu tiên.","h2":"Biển này cho biết có nhiều hơn một đường ray, nên sau khi một tàu chạy qua bạn phải nhìn lại, vì có thể có tàu thứ hai đang tới.","p":"Đúng rồi. Nhiều hơn một đường ray nghĩa là có thể có tàu khác tới."},"tl":{"q":"May maliit na karatula sa ilalim ng crossbuck na nakasulat ang “2 TRACKS” (2 riles). Tungkol saan ang babala nito?","o":["Pagkalampas ng isang tren, maaaring may dumating pang isa","Dalawang beses lang dumadaan ang tren sa isang araw","Dalawang linya ng sasakyan ang tumatawid sa riles","Dapat kang maghintay ng dalawang minuto bago tumawid"],"h1":"Isipin kung ano ang puwedeng nakatago sa likod ng unang tren.","h2":"Sinasabi ng karatulang ito na may higit sa isang riles, kaya pagkalampas ng isang tren ay dapat kang tumingin ulit, dahil maaaring may paparating na pangalawang tren.","p":"Tama. Kapag higit sa isa ang riles, maaaring may dumating pang ibang tren."},"ar":{"q":"لافتة صغيرة تحت علامة X مكتوب عليها «2 TRACKS» (سكتان). ممّ تحذّرك؟","o":["بعد أن يمر قطار، قد يأتي قطار آخر","القطارات تمر مرتين فقط في اليوم","مساران للسيارات يعبران السكة","يجب أن تنتظر دقيقتين قبل أن تعبر"],"h1":"فكّر في ما قد يكون مختبئًا خلف القطار الأول.","h2":"لافتة عدد السكك تخبرك بأن هناك أكثر من سكة واحدة، لذلك بعد أن يمر قطار يجب أن تنظر مرة أخرى، لأن قطارًا ثانيًا قد يكون قادمًا.","p":"صحيح. أكثر من سكة واحدة يعني أن قطارًا آخر قد يأتي."},"ht":{"q":"Yon ti siy anba kwa tren an di “2 TRACKS” (2 ray). Pou kisa li avèti ou?","o":["Apre yon tren fin pase, yon lòt ka vini","Tren pase sèlman de fwa pa jou","De koulwa machin travèse ray yo","Ou dwe tann de minit pou travèse"],"h1":"Panse ak sa ki ka kache dèyè premye tren an.","h2":"Siy sa a di ou gen plis pase yon ray, kidonk apre yon tren fin pase ou dwe gade ankò, paske yon dezyèm tren ka ap vini.","p":"Se sa. Plis pase yon ray vle di yon lòt tren ka vini."},"ref":{"doc":"FL","page":56}},{"id":"signs-036","scope":"FL","cat":"signs","sign":null,"c":1,"en":{"q":"In Florida, when you must stop for a train, where should you stop?","o":["Right on top of the first rail","Between 15 and 50 feet from the nearest rail","At least 100 feet from the tracks","Anywhere you like before the crossing"],"h1":"You need space between you and the train, but not too much.","h2":"In Florida, you must stop no closer than 15 feet and no farther than 50 feet from the nearest rail, so the train has room and you can still see it.","p":"Right. Stop between 15 and 50 feet from the nearest rail."},"es":{"q":"En Florida, cuando debe pararse por un tren, ¿dónde debe pararse?","o":["Justo encima del primer riel","Entre 15 y 50 pies del riel más cercano","Por lo menos a 100 pies de la vía","Donde quiera antes del cruce"],"h1":"Necesita espacio entre usted y el tren, pero no demasiado.","h2":"En Florida, usted debe pararse a no menos de 15 pies y no más de 50 pies del riel más cercano, para que el tren tenga espacio y usted todavía pueda verlo.","p":"Correcto. Párese entre 15 y 50 pies del riel más cercano."},"zh":{"q":"在 Florida，你必须为火车停车时，应该停在哪里？","o":["就停在第一条铁轨上","离最近的铁轨 15 到 50 feet（英尺）之间","离铁轨至少 100 feet（英尺）","过道口前随便哪里都行"],"h1":"你和火车之间要有空间，但不能太远。","h2":"在 Florida，你停车的位置离最近的铁轨不能少于 15 feet（英尺），也不能超过 50 feet（英尺），这样火车有空间通过，你也还能看见火车。","p":"对。停在离最近的铁轨 15 到 50 feet（英尺）之间。"},"vi":{"q":"Ở Florida, khi bạn phải dừng chờ tàu, bạn nên dừng ở đâu?","o":["Ngay trên thanh ray đầu tiên","Cách thanh ray gần nhất từ 15 tới 50 feet","Cách đường ray ít nhất 100 feet","Bất cứ chỗ nào bạn muốn trước chỗ băng qua"],"h1":"Bạn cần có khoảng cách với tàu, nhưng không quá xa.","h2":"Ở Florida, bạn phải dừng cách thanh ray gần nhất không dưới 15 feet và không quá 50 feet, để tàu có chỗ đi qua và bạn vẫn nhìn thấy tàu.","p":"Đúng rồi. Hãy dừng cách thanh ray gần nhất từ 15 tới 50 feet."},"tl":{"q":"Sa Florida, kapag kailangan mong huminto para sa tren, saan ka dapat huminto?","o":["Mismo sa ibabaw ng unang riles","Sa pagitan ng 15 at 50 feet mula sa pinakamalapit na riles","Hindi bababa sa 100 feet mula sa riles","Kahit saan mo gusto bago ang tawiran"],"h1":"Kailangan mo ng puwang sa pagitan mo at ng tren, pero hindi sobrang layo.","h2":"Sa Florida, dapat kang huminto nang hindi lalapit sa 15 feet at hindi lalayo sa 50 feet mula sa pinakamalapit na riles, para may puwang ang tren at nakikita mo pa rin ito.","p":"Tama. Huminto sa pagitan ng 15 at 50 feet mula sa pinakamalapit na riles."},"ar":{"q":"في Florida، عندما يجب أن تتوقف من أجل قطار، أين يجب أن تتوقف؟","o":["فوق القضيب الأول مباشرة","على مسافة بين 15 و50 قدمًا (feet) من أقرب قضيب","على بعد 100 قدم (feet) على الأقل من السكة","في أي مكان تريده قبل التقاطع"],"h1":"تحتاج إلى مسافة بينك وبين القطار، لكن ليست كبيرة جدًا.","h2":"في Florida، يجب أن تتوقف على مسافة لا تقل عن 15 قدمًا (feet) ولا تزيد عن 50 قدمًا من أقرب قضيب، لكي يكون للقطار مكان وتبقى قادرًا على رؤيته.","p":"صحيح. توقف على مسافة بين 15 و50 قدمًا (feet) من أقرب قضيب."},"ht":{"q":"Nan Florida, lè ou dwe kanpe pou yon tren, ki kote ou dwe kanpe?","o":["Dirèkteman sou premye ray la","Ant 15 ak 50 pye de ray ki pi pre a","Omwen 100 pye de ray yo","Nenpòt kote ou vle anvan kote tren travèse a"],"h1":"Ou bezwen espas ant ou menm ak tren an, men pa twòp.","h2":"Nan Florida, ou dwe kanpe pa pi pre pase 15 pye epi pa pi lwen pase 50 pye de ray ki pi pre a, pou tren an gen plas epi pou ou ka toujou wè l.","p":"Se sa. Kanpe ant 15 ak 50 pye de ray ki pi pre a."},"ref":{"doc":"FL","page":56}},{"id":"signs-037","scope":"US","cat":"signs","sign":{"shape":"diamond-orange","text":"ROAD WORK AHEAD"},"c":2,"en":{"q":"An orange sign says ROAD WORK AHEAD. What should you do?","o":["Find another road, this one is closed","Keep your speed, workers are done","Slow down and be ready for workers and changes","Speed up to get through the work fast"],"h1":"Think about people working near moving cars.","h2":"A road work sign means workers, equipment, or lane changes may be ahead, so you should slow down and pay close attention.","p":"Right. In road work, slow down and stay alert."},"es":{"q":"Una señal anaranjada dice ROAD WORK AHEAD (obras más adelante). ¿Qué debe hacer?","o":["Buscar otra vía, esta está cerrada","Mantener su velocidad, los trabajadores ya terminaron","Bajar la velocidad y estar listo para trabajadores y cambios","Acelerar para pasar las obras rápido"],"h1":"Piense en personas trabajando cerca de carros en movimiento.","h2":"Una señal de obras quiere decir que puede haber trabajadores, máquinas o cambios de carril más adelante, así que usted debe bajar la velocidad y poner mucha atención.","p":"Correcto. En zona de obras, baje la velocidad y esté alerta."},"zh":{"q":"一个橙色标志写着 “ROAD WORK AHEAD”（前方道路施工）。你应该怎么做？","o":["另找一条路，这条路封了","保持车速，工人已经完工了","减速，准备好面对工人和道路变化","加速，快快开过施工区"],"h1":"想一想：有人在行驶的车旁边工作。","h2":"道路施工标志表示前方可能有工人、机械或车道变化，所以你要减速，非常注意。","p":"对。在道路施工区，要减速并保持警觉。"},"vi":{"q":"Một biển màu cam ghi “ROAD WORK AHEAD” (Phía trước đang sửa đường). Bạn nên làm gì?","o":["Tìm đường khác, đường này đã đóng","Giữ nguyên tốc độ, công nhân đã làm xong","Chạy chậm lại và sẵn sàng gặp công nhân và thay đổi trên đường","Tăng tốc để qua chỗ sửa đường cho nhanh"],"h1":"Hãy nghĩ đến những người đang làm việc gần xe đang chạy.","h2":"Biển sửa đường nghĩa là phía trước có thể có công nhân, máy móc, hoặc làn đường thay đổi, nên bạn cần chạy chậm lại và chú ý kỹ.","p":"Đúng rồi. Ở chỗ sửa đường, hãy chạy chậm và luôn tỉnh táo."},"tl":{"q":"Nakasulat sa orange na karatula ang “ROAD WORK AHEAD” (May ginagawang kalsada sa unahan). Ano ang dapat mong gawin?","o":["Maghanap ng ibang daan, sarado ang daang ito","Panatilihin ang bilis mo, tapos na ang mga trabahador","Bumagal at maging handa sa mga trabahador at mga pagbabago","Bumilis para mabilis na malampasan ang ginagawa"],"h1":"Isipin ang mga taong nagtatrabaho malapit sa mga umaandar na sasakyan.","h2":"Ang karatula ng ginagawang kalsada ay nangangahulugang maaaring may mga trabahador, kagamitan, o pagbabago ng linya sa unahan, kaya dapat kang bumagal at magbigay ng buong atensyon.","p":"Tama. Kapag may ginagawang kalsada, bumagal at manatiling alerto."},"ar":{"q":"لافتة برتقالية مكتوب عليها «ROAD WORK AHEAD» (أعمال طرق في الأمام). ماذا يجب أن تفعل؟","o":["ابحث عن طريق آخر، فهذا الطريق مغلق","حافظ على سرعتك، فالعمال انتهوا","خفف السرعة واستعد للعمال وللتغييرات","زد السرعة لتعبر منطقة العمل بسرعة"],"h1":"فكّر في أشخاص يعملون قرب سيارات تتحرك.","h2":"لافتة أعمال الطرق تعني أن هناك عمالًا أو معدات أو تغييرات في المسارات في الأمام، لذلك يجب أن تخفف السرعة وتنتبه جيدًا.","p":"صحيح. في أعمال الطرق، خفف السرعة وابقَ منتبهًا."},"ht":{"q":"Yon siy zoranj di “ROAD WORK AHEAD” (travay sou wout pi devan). Kisa ou dwe fè?","o":["Chèche yon lòt wout, wout sa a fèmen","Kenbe vitès ou, travayè yo fini","Ralanti epi pare pou travayè ak chanjman","Akselere pou pase travay la vit"],"h1":"Panse ak moun k ap travay toupre machin k ap woule.","h2":"Yon siy travay sou wout vle di ka gen travayè, machin travay, oswa chanjman koulwa pi devan, kidonk ou dwe ralanti epi fè anpil atansyon.","p":"Se sa. Nan travay sou wout, ralanti epi rete vijilan."},"ref":{"doc":"FL","page":54}},{"id":"signs-038","scope":"US","cat":"signs","sign":null,"c":3,"en":{"q":"In a work zone, a flagger holds a STOP paddle toward you. What should you do?","o":["Slow down and drive around the flagger","Honk and keep going slowly","Stop only if workers are close to you","Stop and wait until the flagger lets you go"],"h1":"The flagger is directing traffic like a signal.","h2":"A flagger's STOP paddle has the same force as a stop sign, so you must stop and wait until the flagger signals you to go.","p":"Right. Obey the flagger and wait for the signal to go."},"es":{"q":"En una zona de obras, un banderero le muestra un letrero de STOP (pare). ¿Qué debe hacer?","o":["Bajar la velocidad y rodear al banderero","Tocar la bocina y seguir despacio","Pararse solo si hay trabajadores cerca","Pararse y esperar hasta que el banderero le deje pasar"],"h1":"El banderero dirige el tráfico como un semáforo.","h2":"El letrero de pare del banderero vale igual que una señal de pare, así que usted debe pararse y esperar hasta que el banderero le indique que siga.","p":"Correcto. Obedezca al banderero y espere su señal para seguir."},"zh":{"q":"在施工区，一名旗手把 “STOP”（停）牌子朝向你。你应该怎么做？","o":["减速，绕过旗手开过去","按喇叭，慢慢继续开","只有工人离你很近时才停","停车，等旗手让你走"],"h1":"旗手像信号灯一样指挥交通。","h2":"旗手的 “STOP” 牌子和停车标志有一样的效力，所以你必须停车，等旗手示意你走。","p":"对。服从旗手，等他示意你走。"},"vi":{"q":"Trong khu vực thi công, người cầm biển điều khiển giao thông giơ biển “STOP” về phía bạn. Bạn nên làm gì?","o":["Chạy chậm lại và chạy vòng qua người cầm biển","Bấm còi và tiếp tục chạy chậm","Chỉ dừng nếu công nhân ở gần bạn","Dừng lại và chờ tới khi người cầm biển cho bạn đi"],"h1":"Người cầm biển đang điều khiển giao thông giống như đèn tín hiệu.","h2":"Biển “STOP” của người cầm biển có hiệu lực giống như biển dừng, nên bạn phải dừng lại và chờ tới khi người đó ra hiệu cho bạn đi.","p":"Đúng rồi. Hãy làm theo người cầm biển và chờ hiệu lệnh cho đi."},"tl":{"q":"Sa work zone, may flagger na nakaharap sa iyo ang hawak na “STOP” na paddle. Ano ang dapat mong gawin?","o":["Bumagal at lumihis paikot sa flagger","Bumusina at magpatuloy nang dahan-dahan","Huminto lang kung malapit sa iyo ang mga trabahador","Huminto at maghintay hanggang payagan ka ng flagger na umandar"],"h1":"Ang flagger ay nagdidirekta ng trapiko na parang ilaw trapiko.","h2":"Ang “STOP” na paddle ng flagger ay may parehong bisa ng “STOP” sign, kaya dapat kang huminto at maghintay hanggang senyasan ka ng flagger na umandar.","p":"Tama. Sundin ang flagger at hintayin ang senyas na umandar."},"ar":{"q":"في منطقة عمل، عامل تنظيم السير يرفع نحوك لوحة «STOP» (قف). ماذا يجب أن تفعل؟","o":["خفف السرعة وقُد حول العامل","استخدم البوق واستمر ببطء","توقف فقط إذا كان العمال قريبين منك","توقف وانتظر حتى يسمح لك العامل بالمرور"],"h1":"عامل تنظيم السير يوجّه السيارات مثل الإشارة الضوئية.","h2":"لوحة «STOP» التي يحملها عامل تنظيم السير لها نفس قوة لافتة «STOP»، لذلك يجب أن تتوقف وتنتظر حتى يشير لك العامل بالمرور.","p":"صحيح. أطِع عامل تنظيم السير وانتظر إشارته لتمر."},"ht":{"q":"Nan yon zòn travay, yon travayè ki dirije trafik la kenbe yon pankat “STOP” bò kote ou. Kisa ou dwe fè?","o":["Ralanti epi pase bò kote travayè a","Klaksonen epi kontinye dousman","Kanpe sèlman si travayè yo toupre ou","Kanpe epi tann jiskaske travayè a kite ou pase"],"h1":"Travayè a ap dirije trafik la tankou yon limyè trafik.","h2":"Pankat “STOP” travayè a gen menm fòs ak yon siy “STOP”, kidonk ou dwe kanpe epi tann jiskaske travayè a fè ou siy pou pase.","p":"Se sa. Obeyi travayè a epi tann siyal pou pase a."},"ref":{"doc":"FL","page":54}},{"id":"signs-039","scope":"US","cat":"signs","sign":null,"c":0,"en":{"q":"An orange sign says DETOUR. What does it mean?","o":["Follow the signs on a different route","The road is closed forever","Only trucks must leave the road","Park and wait for the road to open"],"h1":"A detour is a way around something.","h2":"A detour sign means the normal road is closed for now, so you follow the detour signs on another route.","p":"Right. Detour means follow the signs on another route."},"es":{"q":"Una señal anaranjada dice DETOUR (desvío). ¿Qué significa?","o":["Seguir las señales por otra ruta","La vía está cerrada para siempre","Solo los camiones deben salir de la vía","Estacionarse y esperar a que abran la vía"],"h1":"Un desvío es un camino para rodear algo.","h2":"Una señal de desvío quiere decir que la vía normal está cerrada por ahora, así que usted sigue las señales de desvío por otra ruta.","p":"Correcto. Desvío significa seguir las señales por otra ruta."},"zh":{"q":"一个橙色标志写着 “DETOUR”（绕行）。它是什么意思？","o":["按标志走另一条路线","这条路永远封了","只有卡车要离开这条路","停车等道路开放"],"h1":"绕行就是绕过某个地方的路。","h2":"绕行标志表示平常的路暂时封闭，所以你要按绕行标志走另一条路线。","p":"对。绕行表示按标志走另一条路线。"},"vi":{"q":"Một biển màu cam ghi “DETOUR” (Đường vòng). Biển này có nghĩa là gì?","o":["Đi theo các biển chỉ dẫn sang một đường khác","Con đường bị đóng vĩnh viễn","Chỉ xe tải phải rời khỏi đường","Đỗ xe và chờ đường mở lại"],"h1":"Đường vòng là cách đi vòng qua một chỗ nào đó.","h2":"Biển đường vòng nghĩa là đường bình thường đang tạm đóng, nên bạn đi theo các biển “DETOUR” sang một đường khác.","p":"Đúng rồi. Đường vòng nghĩa là đi theo biển chỉ dẫn sang đường khác."},"tl":{"q":"Nakasulat sa orange na karatula ang “DETOUR” (Lihis na daan). Ano ang ibig sabihin nito?","o":["Sundan ang mga karatula sa ibang ruta","Sarado na ang kalsada habambuhay","Mga trak lang ang dapat umalis sa kalsada","Pumarada at hintaying magbukas ang kalsada"],"h1":"Ang detour ay isang paraan para makaiwas o makadaan paikot sa isang bagay.","h2":"Ang “DETOUR” na karatula ay nangangahulugang sarado muna ang karaniwang daan, kaya susundan mo ang mga karatula ng detour sa ibang ruta.","p":"Tama. Ang “DETOUR” ay nangangahulugang sundan ang mga karatula sa ibang ruta."},"ar":{"q":"لافتة برتقالية مكتوب عليها «DETOUR» (تحويلة). ماذا تعني؟","o":["اتبع اللافتات على طريق مختلف","الطريق مغلق إلى الأبد","الشاحنات فقط يجب أن تخرج من الطريق","أوقف السيارة وانتظر حتى يُفتح الطريق"],"h1":"التحويلة طريق يلتف حول شيء ما.","h2":"لافتة التحويلة تعني أن الطريق العادي مغلق الآن، لذلك تتبع لافتات التحويلة على طريق آخر.","p":"صحيح. التحويلة تعني: اتبع اللافتات على طريق آخر."},"ht":{"q":"Yon siy zoranj di “DETOUR” (devyasyon). Kisa li vle di?","o":["Swiv siy yo sou yon lòt wout","Wout la fèmen pou toutan","Se sèlman kamyon ki dwe kite wout la","Pake epi tann wout la louvri"],"h1":"Yon devyasyon se yon fason pou fè wonn yon bagay.","h2":"Yon siy “DETOUR” vle di wout nòmal la fèmen pou kounye a, kidonk ou swiv siy devyasyon yo sou yon lòt wout.","p":"Se sa. “DETOUR” vle di swiv siy yo sou yon lòt wout."}},{"id":"signs-040","scope":"FL","cat":"signs","sign":null,"c":1,"en":{"q":"In Florida, what happens to a speeding fine in a work zone when workers are there?","o":["It is cut in half","It is doubled","It stays the same","It becomes only a warning"],"h1":"Florida wants to protect the people working on the road.","h2":"In Florida, the fine for speeding in a work zone is doubled when workers are present, because workers near traffic are at great risk.","p":"Right. Speeding fines double in a work zone with workers present."},"es":{"q":"En Florida, ¿qué pasa con la multa por exceso de velocidad en una zona de obras cuando hay trabajadores?","o":["Se reduce a la mitad","Se duplica","Se queda igual","Se vuelve solo una advertencia"],"h1":"Florida quiere proteger a las personas que trabajan en la vía.","h2":"En Florida, la multa por exceso de velocidad en una zona de obras se duplica cuando hay trabajadores presentes, porque los trabajadores cerca del tráfico corren mucho peligro.","p":"Correcto. La multa por velocidad se duplica en zona de obras con trabajadores."},"zh":{"q":"在 Florida，有工人在场时，在施工区超速的罚款会怎样？","o":["减半","加倍","不变","只给警告"],"h1":"Florida 想保护在路上工作的人。","h2":"在 Florida，有工人在场时，在施工区超速的罚款会加倍，因为在车流旁边工作的工人非常危险。","p":"对。有工人在场时，施工区超速罚款加倍。"},"vi":{"q":"Ở Florida, tiền phạt chạy quá tốc độ trong khu vực thi công sẽ ra sao khi có công nhân ở đó?","o":["Giảm một nửa","Tăng gấp đôi","Giữ nguyên","Chỉ bị cảnh cáo"],"h1":"Florida muốn bảo vệ những người đang làm việc trên đường.","h2":"Ở Florida, tiền phạt chạy quá tốc độ trong khu vực thi công bị tăng gấp đôi khi có công nhân, vì công nhân làm việc gần xe chạy rất nguy hiểm.","p":"Đúng rồi. Tiền phạt quá tốc độ tăng gấp đôi trong khu vực thi công có công nhân."},"tl":{"q":"Sa Florida, ano ang nangyayari sa multa sa sobrang bilis sa work zone kapag may mga trabahador doon?","o":["Nababawasan ito ng kalahati","Nadodoble ito","Nananatili itong pareho","Nagiging babala lang ito"],"h1":"Gustong protektahan ng Florida ang mga taong nagtatrabaho sa kalsada.","h2":"Sa Florida, nadodoble ang multa sa sobrang bilis sa work zone kapag may mga trabahador, dahil malaki ang panganib sa mga trabahador na malapit sa trapiko.","p":"Tama. Nadodoble ang multa sa sobrang bilis sa work zone na may mga trabahador."},"ar":{"q":"في Florida، ماذا يحدث لغرامة السرعة في منطقة عمل عندما يكون العمال موجودين؟","o":["تُخفض إلى النصف","تُضاعف","تبقى كما هي","تصبح مجرد تحذير"],"h1":"Florida تريد أن تحمي الأشخاص الذين يعملون على الطريق.","h2":"في Florida، تُضاعف غرامة السرعة في منطقة العمل عندما يكون العمال موجودين، لأن العمال القريبين من السيارات في خطر كبير.","p":"صحيح. غرامات السرعة تُضاعف في منطقة العمل عندما يكون العمال موجودين."},"ht":{"q":"Nan Florida, kisa k ap pase ak amann pou vitès nan yon zòn travay lè gen travayè la?","o":["Li diminye mwatye","Li double","Li rete menm jan an","Li vin yon avètisman sèlman"],"h1":"Florida vle pwoteje moun k ap travay sou wout la.","h2":"Nan Florida, amann pou vitès nan yon zòn travay double lè gen travayè la, paske travayè ki toupre machin yo an gwo danje.","p":"Se sa. Amann pou vitès double nan yon zòn travay lè gen travayè la."},"ref":{"doc":"FL","page":29}},{"id":"signs-041","scope":"US","cat":"signs","sign":{"shape":"interstate","text":"95"},"c":2,"en":{"q":"What kind of road does a blue and red shield with a number mark?","o":["A state park road","A private toll road","An Interstate highway","A county road"],"h1":"This shield is used across the whole country.","h2":"The blue and red shield marks an Interstate highway, which is part of the national highway system.","p":"Right. The blue and red shield marks an Interstate."},"es":{"q":"¿Qué tipo de vía marca un escudo azul y rojo con un número?","o":["Una vía de parque estatal","Una vía privada de peaje","Una autopista interestatal","Una vía del condado"],"h1":"Este escudo se usa en todo el país.","h2":"El escudo azul y rojo marca una autopista interestatal, que es parte del sistema nacional de carreteras.","p":"Correcto. El escudo azul y rojo marca una interestatal."},"zh":{"q":"带数字的蓝红色盾形标志表示哪种道路？","o":["州立公园道路","私人收费公路","州际公路（Interstate）","县级公路"],"h1":"这种盾形标志在全国都用。","h2":"蓝红色盾形标志表示州际公路（Interstate），它是全国公路系统的一部分。","p":"对。蓝红色盾形标志表示州际公路。"},"vi":{"q":"Tấm khiên màu xanh dương và đỏ có ghi số đánh dấu loại đường nào?","o":["Đường trong công viên của tiểu bang","Đường thu phí tư nhân","Đường cao tốc liên bang (Interstate)","Đường của quận"],"h1":"Tấm khiên này được dùng trên khắp cả nước.","h2":"Tấm khiên xanh dương và đỏ đánh dấu đường cao tốc liên bang (Interstate), là một phần của hệ thống đường cao tốc quốc gia.","p":"Đúng rồi. Tấm khiên xanh dương và đỏ đánh dấu đường Interstate."},"tl":{"q":"Anong uri ng kalsada ang minamarkahan ng asul at pulang kalasag na may numero?","o":["Daan sa parke ng estado","Pribadong toll road","Interstate highway","Daan ng county"],"h1":"Ginagamit ang kalasag na ito sa buong bansa.","h2":"Ang asul at pulang kalasag ay nagmamarka ng Interstate highway, na bahagi ng pambansang sistema ng mga highway.","p":"Tama. Ang asul at pulang kalasag ay nagmamarka ng Interstate."},"ar":{"q":"أي نوع من الطرق يدل عليه درع أزرق وأحمر عليه رقم؟","o":["طريق حديقة تابعة للولاية","طريق خاص برسوم","طريق سريع بين الولايات (Interstate)","طريق تابع للمقاطعة"],"h1":"هذا الدرع يُستخدم في البلد كله.","h2":"الدرع الأزرق والأحمر يدل على طريق سريع بين الولايات (Interstate)، وهو جزء من شبكة الطرق السريعة الوطنية.","p":"صحيح. الدرع الأزرق والأحمر يدل على طريق Interstate."},"ht":{"q":"Ki kalite wout yon plak ble ak wouj ki gen yon nimewo make?","o":["Yon wout pak eta","Yon wout prive ki gen peyaj","Yon gran wout Interstate","Yon wout konte"],"h1":"Yo sèvi ak plak sa a nan tout peyi a.","h2":"Plak ble ak wouj la make yon gran wout Interstate, ki fè pati sistèm gran wout nasyonal la.","p":"Se sa. Plak ble ak wouj la make yon Interstate."}},{"id":"signs-042","scope":"US","cat":"signs","sign":{"shape":"interstate","text":"95"},"c":3,"en":{"q":"Interstates with odd numbers, like I-95, usually run which way?","o":["East and west","In a loop around a city","Only inside one state","North and south"],"h1":"Odd and even numbers are used for two different directions.","h2":"Interstates with odd numbers usually run north and south, like I-95 along the east coast.","p":"Right. Odd numbers usually run north and south."},"es":{"q":"Las interestatales con número impar, como la I-95, ¿hacia dónde van normalmente?","o":["De este a oeste","En círculo alrededor de una ciudad","Solo dentro de un estado","De norte a sur"],"h1":"Los números pares e impares se usan para dos direcciones diferentes.","h2":"Las interestatales con número impar normalmente van de norte a sur, como la I-95 por la costa este.","p":"Correcto. Los números impares normalmente van de norte a sur."},"zh":{"q":"编号是单数的州际公路，比如 I-95，通常是什么走向？","o":["东西走向","绕着城市一圈","只在一个州里面","南北走向"],"h1":"单数和双数用于两个不同的方向。","h2":"编号是单数的州际公路通常是南北走向，比如沿着东海岸的 I-95。","p":"对。单数编号通常是南北走向。"},"vi":{"q":"Đường Interstate có số lẻ, như I-95, thường chạy theo hướng nào?","o":["Đông và tây","Vòng quanh một thành phố","Chỉ trong một tiểu bang","Bắc và nam"],"h1":"Số lẻ và số chẵn được dùng cho hai hướng khác nhau.","h2":"Đường Interstate có số lẻ thường chạy theo hướng bắc và nam, như I-95 dọc bờ biển phía đông.","p":"Đúng rồi. Số lẻ thường chạy theo hướng bắc và nam."},"tl":{"q":"Ang mga Interstate na may odd na numero, tulad ng I-95, ay karaniwang papunta sa aling direksyon?","o":["Silangan at kanluran","Paikot sa isang lungsod","Sa loob lang ng isang estado","Hilaga at timog"],"h1":"Ginagamit ang odd at even na numero para sa dalawang magkaibang direksyon.","h2":"Ang mga Interstate na may odd na numero ay karaniwang papunta sa hilaga at timog, tulad ng I-95 sa kahabaan ng silangang baybayin.","p":"Tama. Ang odd na numero ay karaniwang papunta sa hilaga at timog."},"ar":{"q":"طرق Interstate ذات الأرقام الفردية، مثل I-95، في أي اتجاه تمتد عادةً؟","o":["من الشرق إلى الغرب","في دائرة حول مدينة","داخل ولاية واحدة فقط","من الشمال إلى الجنوب"],"h1":"الأرقام الفردية والزوجية تُستخدم لاتجاهين مختلفين.","h2":"طرق Interstate ذات الأرقام الفردية تمتد عادةً من الشمال إلى الجنوب، مثل I-95 على طول الساحل الشرقي.","p":"صحيح. الأرقام الفردية تمتد عادةً من الشمال إلى الجنوب."},"ht":{"q":"Interstate ki gen nimewo enpè, tankou I-95, nan ki direksyon yo konn ale?","o":["Lès ak lwès","An wonn alantou yon vil","Sèlman andedan yon sèl eta","Nò ak sid"],"h1":"Nimewo enpè ak nimewo pè sèvi pou de direksyon diferan.","h2":"Interstate ki gen nimewo enpè yo konn ale nò ak sid, tankou I-95 sou kòt lès la.","p":"Se sa. Nimewo enpè yo konn ale nò ak sid."},"ref":{"doc":"FL","page":46}},{"id":"signs-043","scope":"US","cat":"signs","sign":{"shape":"interstate","text":"10"},"c":0,"en":{"q":"I-10 has an even number. Which way does it usually run?","o":["East and west","North and south","Around a city","Along the coast only"],"h1":"Even and odd numbers go in different directions.","h2":"Interstates with even numbers usually run east and west, like I-10 across north Florida.","p":"Right. Even numbers usually run east and west."},"es":{"q":"La I-10 tiene un número par. ¿Hacia dónde va normalmente?","o":["De este a oeste","De norte a sur","Alrededor de una ciudad","Solo por la costa"],"h1":"Los números pares e impares van en direcciones distintas.","h2":"Las interestatales con número par normalmente van de este a oeste, como la I-10 por el norte de Florida.","p":"Correcto. Los números pares normalmente van de este a oeste."},"zh":{"q":"I-10 的编号是双数。它通常是什么走向？","o":["东西走向","南北走向","绕着城市","只沿着海岸"],"h1":"双数和单数代表不同的方向。","h2":"编号是双数的州际公路通常是东西走向，比如横穿 Florida 北部的 I-10。","p":"对。双数编号通常是东西走向。"},"vi":{"q":"I-10 có số chẵn. Đường này thường chạy theo hướng nào?","o":["Đông và tây","Bắc và nam","Vòng quanh một thành phố","Chỉ dọc theo bờ biển"],"h1":"Số chẵn và số lẻ chạy theo những hướng khác nhau.","h2":"Đường Interstate có số chẵn thường chạy theo hướng đông và tây, như I-10 băng ngang miền bắc Florida.","p":"Đúng rồi. Số chẵn thường chạy theo hướng đông và tây."},"tl":{"q":"Ang I-10 ay may even na numero. Saang direksyon ito karaniwang papunta?","o":["Silangan at kanluran","Hilaga at timog","Paikot sa isang lungsod","Sa kahabaan lang ng baybayin"],"h1":"Ang even at odd na numero ay papunta sa magkaibang direksyon.","h2":"Ang mga Interstate na may even na numero ay karaniwang papunta sa silangan at kanluran, tulad ng I-10 na tumatawid sa hilagang Florida.","p":"Tama. Ang even na numero ay karaniwang papunta sa silangan at kanluran."},"ar":{"q":"الطريق I-10 رقمه زوجي. في أي اتجاه يمتد عادةً؟","o":["من الشرق إلى الغرب","من الشمال إلى الجنوب","حول مدينة","على طول الساحل فقط"],"h1":"الأرقام الزوجية والفردية تسير في اتجاهات مختلفة.","h2":"طرق Interstate ذات الأرقام الزوجية تمتد عادةً من الشرق إلى الغرب، مثل I-10 عبر شمال Florida.","p":"صحيح. الأرقام الزوجية تمتد عادةً من الشرق إلى الغرب."},"ht":{"q":"I-10 gen yon nimewo pè. Nan ki direksyon li konn ale?","o":["Lès ak lwès","Nò ak sid","Alantou yon vil","Sèlman bò lanmè a"],"h1":"Nimewo pè ak nimewo enpè ale nan direksyon diferan.","h2":"Interstate ki gen nimewo pè yo konn ale lès ak lwès, tankou I-10 ki travèse nò Florida.","p":"Se sa. Nimewo pè yo konn ale lès ak lwès."},"ref":{"doc":"FL","page":46}},{"id":"signs-045","scope":"FL","cat":"signs","sign":{"shape":"rect-green","text":"EXIT"},"c":2,"en":{"q":"In Florida, how are exit numbers on Interstates chosen?","o":["In order, 1, 2, 3, from the state line","By the name of the nearest city","By the nearest mile marker","By the number of the crossing road"],"h1":"Think about the small green signs that count the miles.","h2":"In Florida, Interstate exit numbers match the nearest mile marker, so the exit number also tells you about how far you are along the road.","p":"Right. Florida exit numbers follow the mile markers."},"es":{"q":"En Florida, ¿cómo se escogen los números de salida en las interestatales?","o":["En orden, 1, 2, 3, desde la frontera del estado","Por el nombre de la ciudad más cercana","Por el marcador de milla más cercano","Por el número de la vía que cruza"],"h1":"Piense en las señales verdes pequeñas que cuentan las millas.","h2":"En Florida, los números de salida en las interestatales corresponden al marcador de milla más cercano, así que el número de salida también le dice más o menos qué tan lejos va en la vía.","p":"Correcto. En Florida, los números de salida siguen los marcadores de milla."},"zh":{"q":"在 Florida，州际公路的出口编号是怎么定的？","o":["从州界开始按 1、2、3 排列","按最近城市的名字","按最近的里程标","按交叉道路的编号"],"h1":"想一想计算英里数的绿色小标志。","h2":"在 Florida，州际公路的出口编号和最近的里程标一致，所以出口编号也告诉你大约在这条路上走了多远。","p":"对。Florida 的出口编号按里程标来定。"},"vi":{"q":"Ở Florida, số lối ra trên đường Interstate được đặt như thế nào?","o":["Theo thứ tự 1, 2, 3, tính từ ranh giới tiểu bang","Theo tên thành phố gần nhất","Theo cột mốc dặm gần nhất","Theo số của con đường cắt ngang"],"h1":"Hãy nghĩ đến những biển nhỏ màu xanh lá cây đếm số dặm.","h2":"Ở Florida, số lối ra trên đường Interstate trùng với cột mốc dặm gần nhất, nên số lối ra cũng cho bạn biết khoảng bao xa bạn đã đi trên con đường đó.","p":"Đúng rồi. Số lối ra ở Florida theo các cột mốc dặm."},"tl":{"q":"Sa Florida, paano pinipili ang mga numero ng exit sa mga Interstate?","o":["Sunod-sunod, 1, 2, 3, mula sa hangganan ng estado","Ayon sa pangalan ng pinakamalapit na lungsod","Ayon sa pinakamalapit na mile marker","Ayon sa numero ng kalsadang tumatawid"],"h1":"Isipin ang maliliit na berdeng karatula na nagbibilang ng milya.","h2":"Sa Florida, ang numero ng exit sa Interstate ay tugma sa pinakamalapit na mile marker, kaya sinasabi rin ng numero ng exit kung humigit-kumulang gaano na kalayo ang narating mo sa kalsada.","p":"Tama. Sinusunod ng mga numero ng exit sa Florida ang mga mile marker."},"ar":{"q":"في Florida، كيف تُختار أرقام المخارج على طرق Interstate؟","o":["بالترتيب، 1، 2، 3، من حدود الولاية","حسب اسم أقرب مدينة","حسب أقرب علامة ميل","حسب رقم الطريق الذي يتقاطع معه"],"h1":"فكّر في اللافتات الخضراء الصغيرة التي تعدّ الأميال.","h2":"في Florida، أرقام المخارج على طرق Interstate تطابق أقرب علامة ميل، لذلك رقم المخرج يخبرك أيضًا تقريبًا بالمسافة التي قطعتها على الطريق.","p":"صحيح. أرقام المخارج في Florida تتبع علامات الأميال."},"ht":{"q":"Nan Florida, ki jan yo chwazi nimewo sòti yo sou Interstate yo?","o":["Youn apre lòt, 1, 2, 3, depi fwontyè eta a","Dapre non vil ki pi pre a","Dapre ti siy mil ki pi pre a","Dapre nimewo wout ki travèse a"],"h1":"Panse ak ti siy vèt ki konte mil yo.","h2":"Nan Florida, nimewo sòti Interstate yo menm ak ti siy mil ki pi pre a, kidonk nimewo sòti a di ou apeprè ki distans ou fè sou wout la.","p":"Se sa. Nimewo sòti Florida yo swiv ti siy mil yo."},"ref":{"doc":"FL","page":46}},{"id":"signs-046","scope":"US","cat":"signs","sign":{"shape":"rect-green","text":"MILE 120"},"c":3,"en":{"q":"How do small green mile marker signs help you?","o":["They show the speed limit","They point to gas stations","They tell you where to pay tolls","They tell your location in an emergency"],"h1":"Think about what you would tell a 911 operator.","h2":"Mile markers show where you are on the highway, so you can tell emergency helpers your exact location.","p":"Right. Mile markers help you tell where you are."},"es":{"q":"¿Cómo le ayudan las señales verdes pequeñas de marcador de milla?","o":["Muestran el límite de velocidad","Indican dónde hay gasolineras","Le dicen dónde pagar el peaje","Le ayudan a decir dónde está en una emergencia"],"h1":"Piense en lo que le diría a la operadora del 911.","h2":"Los marcadores de milla muestran dónde está usted en la carretera, así que puede decirle a la ayuda de emergencia su ubicación exacta.","p":"Correcto. Los marcadores de milla le ayudan a decir dónde está."},"zh":{"q":"绿色的小里程标对你有什么帮助？","o":["它们显示限速","它们指向加油站","它们告诉你在哪里付过路费","在紧急情况下，它们告诉你在哪里"],"h1":"想一想你会告诉 911 接线员什么。","h2":"里程标显示你在公路上的位置，所以你能把准确位置告诉急救人员。","p":"对。里程标帮你说出你在哪里。"},"vi":{"q":"Những biển nhỏ màu xanh lá cây ghi cột mốc dặm giúp bạn thế nào?","o":["Cho biết giới hạn tốc độ","Chỉ tới trạm xăng","Cho biết chỗ trả phí đường","Cho biết vị trí của bạn khi có trường hợp khẩn cấp"],"h1":"Hãy nghĩ xem bạn sẽ nói gì với người trực tổng đài 911.","h2":"Cột mốc dặm cho biết bạn đang ở đâu trên đường cao tốc, nên bạn có thể nói cho người cứu hộ biết chính xác vị trí của bạn.","p":"Đúng rồi. Cột mốc dặm giúp bạn nói được mình đang ở đâu."},"tl":{"q":"Paano ka natutulungan ng maliliit na berdeng karatula ng mile marker?","o":["Ipinapakita nila ang speed limit","Itinuturo nila ang mga gasolinahan","Sinasabi nila kung saan magbabayad ng toll","Sinasabi nila ang lokasyon mo kapag may emergency"],"h1":"Isipin kung ano ang sasabihin mo sa operator ng 911.","h2":"Ipinapakita ng mga mile marker kung nasaan ka sa highway, kaya masasabi mo sa mga tagatulong sa emergency ang eksaktong lokasyon mo.","p":"Tama. Tinutulungan ka ng mga mile marker na sabihin kung nasaan ka."},"ar":{"q":"كيف تساعدك لافتات علامات الأميال الخضراء الصغيرة؟","o":["تُظهر حد السرعة","تدلّك على محطات الوقود","تخبرك أين تدفع رسوم الطريق","تخبرك بمكانك في حالة الطوارئ"],"h1":"فكّر في ما ستقوله لموظف الطوارئ على الرقم 911.","h2":"علامات الأميال تُظهر مكانك على الطريق السريع، لذلك تستطيع أن تخبر فرق الطوارئ بمكانك بالضبط.","p":"صحيح. علامات الأميال تساعدك على معرفة مكانك."},"ht":{"q":"Ki jan ti siy mil vèt yo ede ou?","o":["Yo montre limit vitès la","Yo montre kote estasyon gaz yo ye","Yo di ou ki kote pou peye peyaj","Yo di ki kote ou ye lè gen yon ijans"],"h1":"Panse ak sa ou ta di yon moun nan 911.","h2":"Ti siy mil yo montre ki kote ou ye sou gran wout la, kidonk ou ka di moun k ap vin ede ou nan yon ijans kote egzak ou ye.","p":"Se sa. Ti siy mil yo ede ou di ki kote ou ye."},"ref":{"doc":"FL","page":46}},{"id":"signs-047","scope":"US","cat":"signs","sign":{"shape":"rect-blue","text":"H"},"c":0,"en":{"q":"A blue sign shows a big white letter H. What does it mean?","o":["A hospital is nearby","A hotel is nearby","A helicopter pad is nearby","The highway ends here"],"h1":"Blue signs show services you may need.","h2":"A blue sign with a white H points to a hospital, so you can find medical help nearby.","p":"Right. The blue H sign means a hospital is near."},"es":{"q":"Una señal azul muestra una letra H grande y blanca. ¿Qué significa?","o":["Hay un hospital cerca","Hay un hotel cerca","Hay un helipuerto cerca","La autopista termina aquí"],"h1":"Las señales azules muestran servicios que podría necesitar.","h2":"Una señal azul con una H blanca indica un hospital, así que usted puede encontrar ayuda médica cerca.","p":"Correcto. La señal azul con H significa que hay un hospital cerca."},"zh":{"q":"一个蓝色标志上有一个很大的白色字母 H。它是什么意思？","o":["附近有医院","附近有酒店","附近有直升机停机坪","公路到这里结束"],"h1":"蓝色标志告诉你可能需要的服务。","h2":"有白色字母 H 的蓝色标志指向医院，所以你能在附近找到医疗帮助。","p":"对。蓝色 H 标志表示附近有医院。"},"vi":{"q":"Một biển màu xanh dương có chữ H lớn màu trắng. Biển này có nghĩa là gì?","o":["Gần đây có bệnh viện","Gần đây có khách sạn","Gần đây có bãi đáp trực thăng","Đường cao tốc kết thúc ở đây"],"h1":"Biển màu xanh dương cho biết những dịch vụ bạn có thể cần.","h2":"Biển màu xanh dương có chữ H trắng chỉ tới bệnh viện, để bạn tìm được chỗ chữa bệnh gần đó.","p":"Đúng rồi. Biển chữ H màu xanh dương nghĩa là gần đây có bệnh viện."},"tl":{"q":"Ang asul na karatula ay nagpapakita ng malaking puting letrang H. Ano ang ibig sabihin nito?","o":["May ospital sa malapit","May hotel sa malapit","May helipad sa malapit","Dito natatapos ang highway"],"h1":"Ang mga asul na karatula ay nagpapakita ng mga serbisyong maaaring kailanganin mo.","h2":"Ang asul na karatula na may puting H ay nagtuturo sa ospital, kaya makakahanap ka ng tulong medikal sa malapit.","p":"Tama. Ang asul na karatulang H ay nangangahulugang may ospital sa malapit."},"ar":{"q":"لافتة زرقاء عليها حرف H أبيض كبير. ماذا تعني؟","o":["مستشفى قريب","فندق قريب","مهبط طائرات مروحية قريب","الطريق السريع ينتهي هنا"],"h1":"اللافتات الزرقاء تُظهر خدمات قد تحتاجها.","h2":"اللافتة الزرقاء التي عليها حرف H أبيض ترشدك إلى مستشفى، لكي تجد مساعدة طبية قريبة.","p":"صحيح. لافتة H الزرقاء تعني أن هناك مستشفى قريبًا."},"ht":{"q":"Yon siy ble montre yon gwo lèt H blan. Kisa li vle di?","o":["Gen yon lopital toupre","Gen yon otèl toupre","Gen yon kote elikoptè ateri toupre","Gran wout la fini la a"],"h1":"Siy ble yo montre sèvis ou ka bezwen.","h2":"Yon siy ble ak yon H blan montre yon lopital, kidonk ou ka jwenn swen medikal toupre.","p":"Se sa. Siy ble ak H la vle di gen yon lopital toupre."},"ref":{"doc":"FL","page":46}},{"id":"signs-048","scope":"US","cat":"signs","sign":null,"c":1,"en":{"q":"On traffic signs, what does the color red usually mean?","o":["A warning about the road ahead","Stop, yield, or something is not allowed","Directions to a place","Services like gas and food"],"h1":"Think of the stop sign and the do not enter sign.","h2":"Red on a sign usually means stop, yield, or that something is not allowed, like on the stop sign and the do not enter sign.","p":"Right. Red means stop, yield, or not allowed."},"es":{"q":"En las señales de tránsito, ¿qué significa normalmente el color rojo?","o":["Un aviso sobre la vía más adelante","Pare, ceda el paso o algo no está permitido","Direcciones hacia un lugar","Servicios como gasolina y comida"],"h1":"Piense en la señal de pare y en la de no entre.","h2":"El rojo en una señal normalmente quiere decir pare, ceda el paso o que algo no está permitido, como en la señal de pare y la de no entre.","p":"Correcto. El rojo significa pare, ceda el paso o no está permitido."},"zh":{"q":"在交通标志上，红色通常表示什么？","o":["提醒前方道路的情况","停车、让行，或某件事不允许","去某个地方的方向","加油、吃饭等服务"],"h1":"想一想停车标志和禁止驶入标志。","h2":"标志上的红色通常表示停车、让行，或某件事不允许，比如停车标志和禁止驶入标志。","p":"对。红色表示停车、让行或不允许。"},"vi":{"q":"Trên biển báo giao thông, màu đỏ thường có nghĩa là gì?","o":["Cảnh báo về con đường phía trước","Dừng lại, nhường đường, hoặc có điều gì đó bị cấm","Chỉ đường tới một nơi","Dịch vụ như xăng và đồ ăn"],"h1":"Hãy nghĩ đến biển dừng và biển cấm đi vào.","h2":"Màu đỏ trên biển báo thường có nghĩa là dừng lại, nhường đường, hoặc có điều gì đó bị cấm, như trên biển “STOP” và biển “DO NOT ENTER”.","p":"Đúng rồi. Màu đỏ nghĩa là dừng lại, nhường đường, hoặc bị cấm."},"tl":{"q":"Sa mga karatula ng trapiko, ano ang karaniwang ibig sabihin ng kulay pula?","o":["Babala tungkol sa kalsada sa unahan","Huminto, magbigay-daan, o may bagay na hindi pinapayagan","Direksyon papunta sa isang lugar","Mga serbisyo tulad ng gasolina at pagkain"],"h1":"Isipin ang “STOP” sign at ang “DO NOT ENTER” sign.","h2":"Ang pula sa karatula ay karaniwang nangangahulugang huminto, magbigay-daan, o may bagay na hindi pinapayagan, tulad ng sa “STOP” sign at sa “DO NOT ENTER” sign.","p":"Tama. Ang pula ay nangangahulugang huminto, magbigay-daan, o hindi pinapayagan."},"ar":{"q":"على لافتات المرور، ماذا يعني اللون الأحمر عادةً؟","o":["تحذير من الطريق في الأمام","قف، أو أعطِ الأولوية، أو أن شيئًا ممنوع","الاتجاه إلى مكان ما","خدمات مثل الوقود والطعام"],"h1":"فكّر في لافتة «STOP» ولافتة «DO NOT ENTER».","h2":"اللون الأحمر على اللافتة يعني عادةً قف، أو أعطِ الأولوية، أو أن شيئًا ممنوع، مثل لافتة «STOP» (قف) ولافتة «DO NOT ENTER» (ممنوع الدخول).","p":"صحيح. الأحمر يعني قف، أو أعطِ الأولوية، أو ممنوع."},"ht":{"q":"Sou siy trafik yo, kisa koulè wouj la konn vle di?","o":["Yon avètisman sou wout la pi devan","Kanpe, bay pasaj, oswa yon bagay ki pa pèmèt","Direksyon pou yon kote","Sèvis tankou gaz ak manje"],"h1":"Panse ak siy “STOP” la ak siy “DO NOT ENTER” la.","h2":"Wouj sou yon siy konn vle di kanpe, bay pasaj, oswa yon bagay ki pa pèmèt, tankou sou siy “STOP” la ak siy “DO NOT ENTER” la.","p":"Se sa. Wouj vle di kanpe, bay pasaj, oswa sa pa pèmèt."},"ref":{"doc":"FL","page":46}},{"id":"signs-049","scope":"US","cat":"signs","sign":null,"c":2,"en":{"q":"A bright yellow-green sign shows a person walking. What should you watch for?","o":["People on bicycles only","Animals crossing","People crossing the road","Road workers"],"h1":"Look at the picture on the sign.","h2":"A yellow-green sign with a walking person warns that people may be crossing the road, so slow down and be ready to stop for them.","p":"Right. Watch for people crossing the road."},"es":{"q":"Una señal verde amarillenta brillante muestra a una persona caminando. ¿A qué debe estar atento?","o":["Solo a personas en bicicleta","A animales cruzando","A personas cruzando la vía","A trabajadores de la vía"],"h1":"Mire el dibujo en la señal.","h2":"Una señal verde amarillenta con una persona caminando avisa que puede haber personas cruzando la vía, así que baje la velocidad y esté listo para pararse por ellas.","p":"Correcto. Esté atento a personas cruzando la vía."},"zh":{"q":"一个亮黄绿色标志上画着一个走路的人。你应该注意什么？","o":["只注意骑自行车的人","动物过马路","行人过马路","道路工人"],"h1":"看看标志上的图。","h2":"画着走路的人的黄绿色标志提醒你可能有行人过马路，所以要减速，准备为他们停车。","p":"对。注意过马路的行人。"},"vi":{"q":"Một biển màu vàng chanh có hình người đang đi bộ. Bạn nên chú ý điều gì?","o":["Chỉ người đi xe đạp","Thú vật băng qua đường","Người đi bộ băng qua đường","Công nhân sửa đường"],"h1":"Hãy nhìn hình vẽ trên biển.","h2":"Biển màu vàng chanh có hình người đi bộ cảnh báo rằng có thể có người băng qua đường, nên bạn cần chạy chậm lại và sẵn sàng dừng cho họ.","p":"Đúng rồi. Hãy chú ý người đi bộ băng qua đường."},"tl":{"q":"Ang matingkad na dilaw-berdeng karatula ay nagpapakita ng taong naglalakad. Ano ang dapat mong bantayan?","o":["Mga taong nakabisikleta lang","Mga hayop na tumatawid","Mga taong tumatawid sa kalsada","Mga trabahador sa kalsada"],"h1":"Tingnan ang larawan sa karatula.","h2":"Ang dilaw-berdeng karatula na may taong naglalakad ay babala na maaaring may mga taong tumatawid sa kalsada, kaya bumagal at maging handang huminto para sa kanila.","p":"Tama. Mag-ingat sa mga taong tumatawid sa kalsada."},"ar":{"q":"لافتة بلون أصفر مخضر لامع تُظهر شخصًا يمشي. ما الذي يجب أن تنتبه له؟","o":["أشخاص على الدراجات فقط","حيوانات تعبر","أشخاص يعبرون الطريق","عمال الطرق"],"h1":"انظر إلى الصورة على اللافتة.","h2":"اللافتة الصفراء المخضرة التي عليها شخص يمشي تحذّر من أن أشخاصًا قد يعبرون الطريق، لذلك خفف السرعة وكن مستعدًا للتوقف من أجلهم.","p":"صحيح. انتبه للأشخاص الذين يعبرون الطريق."},"ht":{"q":"Yon siy jòn-vèt klè montre yon moun k ap mache. Kisa ou dwe veye?","o":["Moun sou bisiklèt sèlman","Bèt k ap travèse","Moun k ap travèse wout la","Travayè sou wout la"],"h1":"Gade foto ki sou siy la.","h2":"Yon siy jòn-vèt ak yon moun k ap mache avèti ou ka gen moun k ap travèse wout la, kidonk ralanti epi pare pou kanpe pou yo.","p":"Se sa. Veye moun k ap travèse wout la."},"ref":{"doc":"FL","page":46}},{"id":"speed-lanes-001","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, what is the speed limit in a business or residential area when no sign says otherwise?","o":["25 mph","35 mph","30 mph","40 mph"],"h1":"Think of streets with homes and shops, where people walk a lot.","h2":"The speed limit in a Florida business or residential area is 30 mph unless a sign shows a different limit.","p":"Right. Business and residential areas in Florida are 30 mph unless posted."},"es":{"q":"En Florida, ¿cuál es el límite de velocidad en una zona comercial o residencial si no hay letrero que diga otra cosa?","o":["25 mph","35 mph","30 mph","40 mph"],"h1":"Piense en calles con casas y tiendas, donde camina mucha gente.","h2":"El límite de velocidad en una zona comercial o residencial de Florida es 30 mph, a menos que un letrero indique otro límite.","p":"Correcto. En Florida, las zonas comerciales y residenciales son de 30 mph si no hay otro letrero."},"zh":{"q":"在 Florida，在商业区或住宅区，如果没有标志另外规定，限速是多少？","o":["25 英里/小时","35 英里/小时","30 英里/小时","40 英里/小时"],"h1":"想一想有住家和商店、很多人走路的街道。","h2":"在 Florida 的商业区或住宅区，限速是 30 英里/小时，除非有标志写着别的限速。","p":"对。Florida 的商业区和住宅区限速 30 英里/小时，除非另有标志。"},"vi":{"q":"Ở Florida, giới hạn tốc độ trong khu kinh doanh hoặc khu dân cư là bao nhiêu khi không có biển báo khác?","o":["25 mph","35 mph","30 mph","40 mph"],"h1":"Hãy nghĩ đến những con đường có nhà ở và cửa hàng, nơi có nhiều người đi bộ.","h2":"Giới hạn tốc độ trong khu kinh doanh hoặc khu dân cư ở Florida là 30 mph, trừ khi có biển báo giới hạn khác.","p":"Đúng. Khu kinh doanh và khu dân cư ở Florida là 30 mph nếu không có biển báo khác."},"tl":{"q":"Sa Florida, ano ang speed limit sa lugar ng negosyo o tirahan kapag walang karatulang nagsasabi ng iba?","o":["25 mph","35 mph","30 mph","40 mph"],"h1":"Isipin ang mga kalyeng may bahay at tindahan, kung saan maraming naglalakad.","h2":"Ang speed limit sa lugar ng negosyo o tirahan sa Florida ay 30 mph, maliban kung may karatulang nagpapakita ng ibang limit.","p":"Tama. 30 mph ang limit sa mga lugar ng negosyo at tirahan sa Florida, maliban kung may nakapaskil na iba."},"ar":{"q":"في Florida، ما حد السرعة في منطقة تجارية أو سكنية عندما لا توجد علامة تقول غير ذلك؟","o":["25 ميلًا في الساعة","35 ميلًا في الساعة","30 ميلًا في الساعة","40 ميلًا في الساعة"],"h1":"فكّر في شوارع فيها بيوت ومحلات، ويمشي فيها الناس كثيرًا.","h2":"حد السرعة في المنطقة التجارية أو السكنية في Florida هو 30 ميلًا في الساعة، إلا إذا كانت هناك علامة تُظهر حدًا آخر.","p":"صحيح. في المناطق التجارية والسكنية في Florida الحد 30 ميلًا في الساعة، إلا إذا كُتب غير ذلك."},"ht":{"q":"Nan Florida, ki limit vitès la nan yon zòn biznis oswa yon zòn kote moun rete, lè pa gen siy ki di lòt bagay?","o":["25 mph","35 mph","30 mph","40 mph"],"h1":"Panse ak lari ki gen kay ak magazen, kote anpil moun ap mache.","h2":"Limit vitès la nan yon zòn biznis oswa yon zòn kote moun rete nan Florida se 30 mph, sòf si yon siy montre yon lòt limit.","p":"Wi, se sa. Nan Florida, zòn biznis ak zòn kote moun rete se 30 mph, sòf si gen siy."},"ref":{"doc":"FL","page":68}},{"id":"speed-lanes-002","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, what is the highest speed limit allowed on a rural interstate highway?","o":["70 mph","65 mph","75 mph","60 mph"],"h1":"This is the fastest limit you will see on any Florida road.","h2":"The top speed limit on a Florida rural interstate is 70 mph, and you must still follow the posted sign.","p":"Right. Rural interstates in Florida can be posted up to 70 mph."},"es":{"q":"En Florida, ¿cuál es el límite de velocidad más alto permitido en una autopista interestatal rural?","o":["70 mph","65 mph","75 mph","60 mph"],"h1":"Es el límite más alto que verá en cualquier carretera de Florida.","h2":"El límite más alto en una interestatal rural de Florida es 70 mph, y siempre debe seguir el letrero que esté puesto.","p":"Correcto. Las interestatales rurales de Florida pueden tener un límite de hasta 70 mph."},"zh":{"q":"在 Florida，乡村州际公路上允许的最高限速是多少？","o":["70 英里/小时","65 英里/小时","75 英里/小时","60 英里/小时"],"h1":"这是你在 Florida 任何道路上会看到的最高限速。","h2":"Florida 乡村州际公路的最高限速是 70 英里/小时，而且你还是要遵守路上标出的限速。","p":"对。Florida 的乡村州际公路限速最高可以标到 70 英里/小时。"},"vi":{"q":"Ở Florida, giới hạn tốc độ cao nhất được phép trên xa lộ liên bang (interstate) ở vùng nông thôn là bao nhiêu?","o":["70 mph","65 mph","75 mph","60 mph"],"h1":"Đây là giới hạn nhanh nhất bạn sẽ thấy trên mọi con đường ở Florida.","h2":"Giới hạn tốc độ cao nhất trên xa lộ liên bang vùng nông thôn ở Florida là 70 mph, và bạn vẫn phải theo biển báo trên đường.","p":"Đúng. Xa lộ liên bang vùng nông thôn ở Florida có thể có giới hạn đến 70 mph."},"tl":{"q":"Sa Florida, ano ang pinakamataas na speed limit na pinapayagan sa rural interstate highway (interstate sa labas ng lungsod)?","o":["70 mph","65 mph","75 mph","60 mph"],"h1":"Ito ang pinakamabilis na limit na makikita mo sa anumang daan sa Florida.","h2":"Ang pinakamataas na speed limit sa rural interstate sa Florida ay 70 mph, at dapat mo pa ring sundin ang nakapaskil na karatula.","p":"Tama. Ang mga rural interstate sa Florida ay puwedeng may limit hanggang 70 mph."},"ar":{"q":"في Florida، ما أعلى حد سرعة مسموح به على طريق سريع بين الولايات (interstate) في منطقة ريفية؟","o":["70 ميلًا في الساعة","65 ميلًا في الساعة","75 ميلًا في الساعة","60 ميلًا في الساعة"],"h1":"هذا أعلى حد سرعة ستراه على أي طريق في Florida.","h2":"أعلى حد سرعة على طريق interstate ريفي في Florida هو 70 ميلًا في الساعة، ويجب أن تتبع أيضًا العلامة المكتوبة.","p":"صحيح. على طرق interstate الريفية في Florida يمكن أن يصل الحد المكتوب إلى 70 ميلًا في الساعة."},"ht":{"q":"Nan Florida, ki limit vitès ki pi wo yo pèmèt sou yon gran wout entèeta (interstate) nan zòn andeyò?","o":["70 mph","65 mph","75 mph","60 mph"],"h1":"Se limit ki pi rapid ou ap wè sou nenpòt wout nan Florida.","h2":"Limit vitès ki pi wo sou yon gran wout entèeta nan zòn andeyò nan Florida se 70 mph, epi ou dwe toujou swiv siy ki afiche a.","p":"Wi, se sa. Gran wout entèeta nan zòn andeyò nan Florida ka gen yon limit jiska 70 mph."},"ref":{"doc":"FL","page":68}},{"id":"speed-lanes-003","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, what is the speed limit on a highway outside a city when no sign is posted?","o":["45 mph","65 mph","70 mph","55 mph"],"h1":"It is lower than the interstate limit, but higher than city streets.","h2":"When no speed limit sign is posted on a Florida highway outside a city, the limit is 55 mph.","p":"Right. With no sign on other Florida highways, the limit is 55 mph."},"es":{"q":"En Florida, ¿cuál es el límite de velocidad en una carretera fuera de la ciudad cuando no hay letrero?","o":["45 mph","65 mph","70 mph","55 mph"],"h1":"Es más bajo que en la interestatal, pero más alto que en las calles de la ciudad.","h2":"Cuando no hay letrero de límite en una carretera de Florida fuera de la ciudad, el límite es 55 mph.","p":"Correcto. Sin letrero en otras carreteras de Florida, el límite es 55 mph."},"zh":{"q":"在 Florida，城市以外的公路上没有限速标志时，限速是多少？","o":["45 英里/小时","65 英里/小时","70 英里/小时","55 英里/小时"],"h1":"它比州际公路的限速低，但比城市街道高。","h2":"在 Florida 城市以外的公路上，如果没有限速标志，限速是 55 英里/小时。","p":"对。Florida 其他公路上没有标志时，限速是 55 英里/小时。"},"vi":{"q":"Ở Florida, giới hạn tốc độ trên xa lộ ngoài thành phố là bao nhiêu khi không có biển báo?","o":["45 mph","65 mph","70 mph","55 mph"],"h1":"Nó thấp hơn giới hạn trên xa lộ liên bang, nhưng cao hơn đường trong thành phố.","h2":"Khi không có biển giới hạn tốc độ trên xa lộ ngoài thành phố ở Florida, giới hạn là 55 mph.","p":"Đúng. Không có biển báo trên các xa lộ khác ở Florida thì giới hạn là 55 mph."},"tl":{"q":"Sa Florida, ano ang speed limit sa highway sa labas ng lungsod kapag walang nakapaskil na karatula?","o":["45 mph","65 mph","70 mph","55 mph"],"h1":"Mas mababa ito sa limit ng interstate, pero mas mataas sa mga kalye ng lungsod.","h2":"Kapag walang nakapaskil na speed limit sign sa highway ng Florida sa labas ng lungsod, 55 mph ang limit.","p":"Tama. Kapag walang karatula sa ibang highway sa Florida, 55 mph ang limit."},"ar":{"q":"في Florida، ما حد السرعة على طريق سريع خارج المدينة عندما لا توجد علامة؟","o":["45 ميلًا في الساعة","65 ميلًا في الساعة","70 ميلًا في الساعة","55 ميلًا في الساعة"],"h1":"هو أقل من حد طرق interstate، لكنه أعلى من حد شوارع المدينة.","h2":"عندما لا توجد علامة حد سرعة على طريق سريع خارج المدينة في Florida، يكون الحد 55 ميلًا في الساعة.","p":"صحيح. على الطرق السريعة الأخرى في Florida بدون علامة، الحد 55 ميلًا في الساعة."},"ht":{"q":"Nan Florida, ki limit vitès la sou yon gran wout deyò vil, lè pa gen okenn siy?","o":["45 mph","65 mph","70 mph","55 mph"],"h1":"Li pi ba pase limit gran wout entèeta a, men li pi wo pase lari nan vil.","h2":"Lè pa gen okenn siy limit vitès sou yon gran wout deyò vil nan Florida, limit la se 55 mph.","p":"Wi, se sa. Lè pa gen siy sou lòt gran wout nan Florida, limit la se 55 mph."},"ref":{"doc":"FL","page":68}},{"id":"speed-lanes-004","scope":"FL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Florida, on an interstate where the speed limit is 70 mph, what is the lowest speed you may drive in good conditions?","o":["40 mph","50 mph","45 mph","30 mph"],"h1":"Driving too slow on a fast road is also unsafe. There is a minimum.","h2":"On a Florida interstate posted at 70 mph, the minimum speed is 50 mph when the weather and traffic are normal.","p":"Right. The minimum speed on a 70 mph Florida interstate is 50 mph."},"es":{"q":"En Florida, en una interestatal con límite de 70 mph, ¿cuál es la velocidad más baja permitida con buenas condiciones?","o":["40 mph","50 mph","45 mph","30 mph"],"h1":"Manejar muy despacio en una vía rápida también es peligroso. Hay un mínimo.","h2":"En una interestatal de Florida con límite de 70 mph, la velocidad mínima es 50 mph cuando el clima y el tráfico son normales.","p":"Correcto. La velocidad mínima en una interestatal de Florida de 70 mph es 50 mph."},"zh":{"q":"在 Florida，在限速 70 英里/小时的州际公路上，天气和路况好的时候，你最慢可以开多快？","o":["40 英里/小时","50 英里/小时","45 英里/小时","30 英里/小时"],"h1":"在快速道路上开得太慢也不安全。有一个最低速度。","h2":"在 Florida 限速 70 英里/小时的州际公路上，天气和交通正常时，最低速度是 50 英里/小时。","p":"对。Florida 限速 70 英里/小时的州际公路，最低速度是 50 英里/小时。"},"vi":{"q":"Ở Florida, trên xa lộ liên bang có giới hạn tốc độ 70 mph, tốc độ thấp nhất bạn được chạy khi điều kiện tốt là bao nhiêu?","o":["40 mph","50 mph","45 mph","30 mph"],"h1":"Chạy quá chậm trên đường nhanh cũng không an toàn. Có một tốc độ tối thiểu.","h2":"Trên xa lộ liên bang ở Florida có giới hạn 70 mph, tốc độ tối thiểu là 50 mph khi thời tiết và giao thông bình thường.","p":"Đúng. Tốc độ tối thiểu trên xa lộ liên bang 70 mph ở Florida là 50 mph."},"tl":{"q":"Sa Florida, sa interstate na 70 mph ang speed limit, ano ang pinakamababang bilis na puwede mong takbuhin kapag maayos ang kondisyon?","o":["40 mph","50 mph","45 mph","30 mph"],"h1":"Delikado rin ang sobrang bagal sa mabilis na daan. May minimum.","h2":"Sa interstate sa Florida na 70 mph ang limit, 50 mph ang minimum na bilis kapag normal ang panahon at trapiko.","p":"Tama. 50 mph ang minimum na bilis sa interstate sa Florida na 70 mph ang limit."},"ar":{"q":"في Florida، على طريق interstate حد السرعة فيه 70 ميلًا في الساعة، ما أقل سرعة يمكنك أن تقود بها عندما تكون الظروف جيدة؟","o":["40 ميلًا في الساعة","50 ميلًا في الساعة","45 ميلًا في الساعة","30 ميلًا في الساعة"],"h1":"القيادة ببطء شديد على طريق سريع خطيرة أيضًا. هناك حد أدنى.","h2":"على طريق interstate في Florida حده المكتوب 70 ميلًا في الساعة، الحد الأدنى للسرعة هو 50 ميلًا في الساعة عندما يكون الطقس والسير عاديين.","p":"صحيح. الحد الأدنى على طريق interstate في Florida حده 70 ميلًا في الساعة هو 50 ميلًا في الساعة."},"ht":{"q":"Nan Florida, sou yon gran wout entèeta kote limit vitès la se 70 mph, ki vitès ki pi ba ou ka kondi lè kondisyon yo bon?","o":["40 mph","50 mph","45 mph","30 mph"],"h1":"Kondi twò dousman sou yon wout rapid danjere tou. Gen yon vitès minimòm.","h2":"Sou yon gran wout entèeta nan Florida ki gen limit 70 mph, vitès minimòm lan se 50 mph lè tan an ak sikilasyon an nòmal.","p":"Wi, se sa. Vitès minimòm sou yon gran wout entèeta 70 mph nan Florida se 50 mph."},"ref":{"doc":"FL","page":68}},{"id":"speed-lanes-005","scope":"FL","cat":"speed-lanes","sign":{"shape":"school","text":"SCHOOL"},"c":1,"en":{"q":"In Florida, when must you obey the lower speed limit in a school zone?","o":["Only when you see children on the road","When the lights flash or during the times shown on the sign","Only on Monday mornings","Only when a police car is nearby"],"h1":"Look at the sign. It tells you when the lower limit is active.","h2":"You must obey the school zone speed limit when its lights are flashing or during the hours shown on the sign, even if you do not see children.","p":"Right. Follow the school zone limit when the lights flash or during the posted times."},"es":{"q":"En Florida, ¿cuándo debe respetar el límite de velocidad más bajo en una zona escolar?","o":["Solo cuando ve niños en la calle","Cuando las luces parpadean o en las horas que indica el letrero","Solo los lunes por la mañana","Solo cuando hay un carro de policía cerca"],"h1":"Mire el letrero. Le dice cuándo aplica el límite más bajo.","h2":"Debe respetar el límite de la zona escolar cuando las luces parpadean o en las horas que indica el letrero, aunque no vea niños.","p":"Correcto. Respete el límite escolar cuando las luces parpadean o en las horas indicadas."},"zh":{"q":"在 Florida，什么时候必须遵守学校区较低的限速？","o":["只有看到路上有小孩时","灯在闪的时候，或标志上写的时间内","只在星期一早上","只有附近有警车时"],"h1":"看标志。它会告诉你较低的限速什么时候生效。","h2":"当学校区的灯在闪，或在标志上写的时间内，你必须遵守学校区限速，就算你没看到小孩也一样。","p":"对。灯在闪或在标出的时间内，要遵守学校区限速。"},"vi":{"q":"Ở Florida, khi nào bạn phải tuân theo giới hạn tốc độ thấp hơn trong khu vực trường học?","o":["Chỉ khi bạn thấy trẻ em trên đường","Khi đèn nháy hoặc trong khung giờ ghi trên biển báo","Chỉ vào sáng thứ Hai","Chỉ khi có xe cảnh sát gần đó"],"h1":"Hãy nhìn biển báo. Biển cho bạn biết khi nào giới hạn thấp hơn có hiệu lực.","h2":"Bạn phải tuân theo giới hạn tốc độ khu vực trường học khi đèn đang nháy hoặc trong khung giờ ghi trên biển, kể cả khi bạn không thấy trẻ em.","p":"Đúng. Hãy theo giới hạn khu vực trường học khi đèn nháy hoặc trong giờ ghi trên biển."},"tl":{"q":"Sa Florida, kailan mo dapat sundin ang mas mababang speed limit sa school zone?","o":["Kapag may nakikita ka lang na mga bata sa daan","Kapag kumikislap ang mga ilaw o sa mga oras na nakasulat sa karatula","Tuwing Lunes ng umaga lang","Kapag may kotse lang ng pulis sa malapit"],"h1":"Tingnan ang karatula. Sinasabi nito kung kailan umiiral ang mas mababang limit.","h2":"Dapat mong sundin ang speed limit sa school zone kapag kumikislap ang mga ilaw nito o sa mga oras na nakasulat sa karatula, kahit wala kang nakikitang bata.","p":"Tama. Sundin ang limit sa school zone kapag kumikislap ang ilaw o sa mga nakapaskil na oras."},"ar":{"q":"في Florida، متى يجب أن تلتزم بحد السرعة الأقل في منطقة المدرسة؟","o":["فقط عندما أرى أطفالًا في الطريق","عندما تومض الأضواء أو في الأوقات المكتوبة على العلامة","فقط صباح يوم الاثنين","فقط عندما تكون سيارة شرطة قريبة"],"h1":"انظر إلى العلامة. هي تخبرك متى يبدأ العمل بالحد الأقل.","h2":"يجب أن تلتزم بحد السرعة في منطقة المدرسة عندما تومض أضواؤها أو في الساعات المكتوبة على العلامة، حتى لو لم ترَ أطفالًا.","p":"صحيح. اتبع حد منطقة المدرسة عندما تومض الأضواء أو في الأوقات المكتوبة."},"ht":{"q":"Nan Florida, kilè ou dwe respekte limit vitès ki pi ba a nan yon zòn lekòl?","o":["Sèlman lè ou wè timoun sou wout la","Lè limyè yo ap flache oswa pandan lè ki ekri sou siy la","Sèlman lendi maten","Sèlman lè gen yon machin polis tou pre"],"h1":"Gade siy la. Li di ou kilè limit ki pi ba a an vigè.","h2":"Ou dwe respekte limit vitès zòn lekòl la lè limyè li yo ap flache oswa pandan lè ki ekri sou siy la, menm si ou pa wè timoun.","p":"Wi, se sa. Swiv limit zòn lekòl la lè limyè yo ap flache oswa pandan lè ki ekri sou siy la."},"ref":{"doc":"FL","page":57}},{"id":"speed-lanes-006","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, it is raining hard and you are on a road posted at 55 mph. How fast should you drive?","o":["Exactly 55 mph, because that is the limit","A little faster than 55 mph to get out of the rain","Any speed, because rain does not change the rules","Slower than 55 mph, at a speed that is safe for the rain"],"h1":"A speed limit is the most you may drive in good conditions.","h2":"You must never drive faster than is safe for the conditions, so in heavy rain you should drive slower than the posted 55 mph.","p":"Right. In bad weather, slow down below the limit to a safe speed."},"es":{"q":"En Florida, está lloviendo fuerte y usted va por una carretera con límite de 55 mph. ¿A qué velocidad debe manejar?","o":["Exactamente a 55 mph, porque ese es el límite","Un poco más rápido que 55 mph para salir de la lluvia","A cualquier velocidad, porque la lluvia no cambia las reglas","Más despacio que 55 mph, a una velocidad segura para la lluvia"],"h1":"El límite de velocidad es lo máximo que puede manejar con buenas condiciones.","h2":"Nunca debe manejar más rápido de lo que es seguro para las condiciones, así que con lluvia fuerte debe ir más despacio que 55 mph.","p":"Correcto. Con mal clima, baje la velocidad por debajo del límite a una velocidad segura."},"zh":{"q":"在 Florida，雨下得很大，你在一条限速 55 英里/小时的路上。你应该开多快？","o":["正好 55 英里/小时，因为那是限速","比 55 英里/小时快一点，好赶快离开大雨","什么速度都行，因为下雨不改变规则","比 55 英里/小时慢，用适合下雨的安全速度"],"h1":"限速是路况好的时候你最多可以开的速度。","h2":"你永远不能开得比路况允许的安全速度更快，所以下大雨时，你应该开得比标出的 55 英里/小时更慢。","p":"对。天气不好时，要减速到低于限速的安全速度。"},"vi":{"q":"Ở Florida, trời đang mưa to và bạn đang chạy trên đường có biển giới hạn 55 mph. Bạn nên chạy nhanh bao nhiêu?","o":["Đúng 55 mph, vì đó là giới hạn","Nhanh hơn 55 mph một chút để ra khỏi cơn mưa","Tốc độ nào cũng được, vì mưa không thay đổi luật","Chậm hơn 55 mph, ở tốc độ an toàn khi trời mưa"],"h1":"Giới hạn tốc độ là mức cao nhất bạn được chạy khi điều kiện tốt.","h2":"Bạn không bao giờ được chạy nhanh hơn mức an toàn cho điều kiện lúc đó, nên khi mưa to bạn nên chạy chậm hơn 55 mph ghi trên biển.","p":"Đúng. Khi thời tiết xấu, hãy giảm tốc xuống dưới giới hạn đến mức an toàn."},"tl":{"q":"Sa Florida, malakas ang ulan at nasa daan ka na 55 mph ang nakapaskil na limit. Gaano ka kabilis dapat magmaneho?","o":["Eksaktong 55 mph, dahil iyon ang limit","Medyo mas mabilis sa 55 mph para makaalis sa ulan","Kahit anong bilis, dahil hindi binabago ng ulan ang patakaran","Mas mabagal sa 55 mph, sa bilis na ligtas sa ulan"],"h1":"Ang speed limit ay ang pinakamabilis na puwede mong takbuhin kapag maayos ang kondisyon.","h2":"Hindi ka dapat kailanman magmaneho nang mas mabilis kaysa sa ligtas para sa kondisyon, kaya sa malakas na ulan dapat kang magmaneho nang mas mabagal sa nakapaskil na 55 mph.","p":"Tama. Kapag masama ang panahon, bumagal sa ilalim ng limit, sa ligtas na bilis."},"ar":{"q":"في Florida، المطر شديد وأنت على طريق حده المكتوب 55 ميلًا في الساعة. بأي سرعة يجب أن تقود؟","o":["55 ميلًا في الساعة بالضبط، لأن هذا هو الحد","أسرع قليلًا من 55 ميلًا في الساعة لأخرج من المطر","بأي سرعة، لأن المطر لا يغيّر القواعد","أبطأ من 55 ميلًا في الساعة، بسرعة آمنة في المطر"],"h1":"حد السرعة هو أعلى سرعة مسموحة عندما تكون الظروف جيدة.","h2":"لا يجوز أبدًا أن تقود أسرع مما هو آمن في الظروف الموجودة، لذلك في المطر الشديد يجب أن تقود أبطأ من الحد المكتوب 55 ميلًا في الساعة.","p":"صحيح. في الطقس السيئ، خفف السرعة إلى أقل من الحد، إلى سرعة آمنة."},"ht":{"q":"Nan Florida, lapli ap tonbe fò epi ou sou yon wout ki gen limit 55 mph. Ak ki vitès ou ta dwe kondi?","o":["Egzakteman 55 mph, paske se limit la","Yon ti kras pi vit pase 55 mph pou sòti anba lapli a","Nenpòt vitès, paske lapli pa chanje règ yo","Pi dousman pase 55 mph, a yon vitès ki san danje pou lapli a"],"h1":"Yon limit vitès se maksimòm ou ka kondi lè kondisyon yo bon.","h2":"Ou pa dwe janm kondi pi vit pase sa ki san danje pou kondisyon yo, kidonk lè gen gwo lapli ou ta dwe kondi pi dousman pase 55 mph ki afiche a.","p":"Wi, se sa. Lè tan an move, desann anba limit la pou yon vitès ki san danje."},"ref":{"doc":"FL","page":null}},{"id":"speed-lanes-007","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, can you get a ticket for driving too slowly?","o":["Yes, if you block the normal flow of traffic","No, driving slowly is always legal","Only if you drive slower than 10 mph","Only on dirt roads"],"h1":"Think about what happens to the cars behind a very slow driver.","h2":"Yes. In Florida you can get a ticket if you drive so slowly that you block the normal and safe flow of traffic.","p":"Right. Driving so slowly that you block traffic is against the law."},"es":{"q":"En Florida, ¿le pueden dar una multa por manejar demasiado despacio?","o":["Sí, si bloquea el flujo normal del tráfico","No, manejar despacio siempre es legal","Solo si maneja a menos de 10 mph","Solo en caminos de tierra"],"h1":"Piense en lo que les pasa a los carros que van detrás de alguien muy lento.","h2":"Sí. En Florida le pueden poner una multa si maneja tan despacio que bloquea el flujo normal y seguro del tráfico.","p":"Correcto. Manejar tan despacio que bloquea el tráfico va contra la ley."},"zh":{"q":"在 Florida，开得太慢会被开罚单吗？","o":["会，如果你挡住了正常的车流","不会，开得慢永远是合法的","只有开得比 10 英里/小时还慢时才会","只在土路上才会"],"h1":"想一想，跟在很慢的司机后面的车会怎么样。","h2":"会。在 Florida，如果你开得太慢，挡住了正常、安全的车流，你可能会被开罚单。","p":"对。开得太慢、挡住车流是违法的。"},"vi":{"q":"Ở Florida, bạn có thể bị phạt vì lái xe quá chậm không?","o":["Có, nếu bạn cản trở dòng xe bình thường","Không, lái chậm luôn hợp pháp","Chỉ khi bạn chạy chậm hơn 10 mph","Chỉ trên đường đất"],"h1":"Hãy nghĩ xem chuyện gì xảy ra với các xe phía sau một người lái rất chậm.","h2":"Có. Ở Florida bạn có thể bị phạt nếu lái chậm đến mức cản trở dòng xe bình thường và an toàn.","p":"Đúng. Lái chậm đến mức cản trở giao thông là trái luật."},"tl":{"q":"Sa Florida, puwede ka bang matiketan dahil sa sobrang bagal na pagmamaneho?","o":["Oo, kung naharangan mo ang normal na daloy ng trapiko","Hindi, laging legal ang mabagal na pagmamaneho","Kung mas mabagal ka lang sa 10 mph","Sa mga daang lupa lang"],"h1":"Isipin ang nangyayari sa mga kotse sa likod ng sobrang bagal na drayber.","h2":"Oo. Sa Florida, puwede kang matiketan kung napakabagal mong magmaneho na naharangan mo ang normal at ligtas na daloy ng trapiko.","p":"Tama. Labag sa batas ang sobrang bagal na pagmamaneho na humaharang sa trapiko."},"ar":{"q":"في Florida، هل يمكن أن تحصل على مخالفة لأنك تقود ببطء شديد؟","o":["نعم، إذا كنت أعيق حركة السير العادية","لا، القيادة البطيئة مسموحة دائمًا","فقط إذا كنت أقود أبطأ من 10 أميال في الساعة","فقط على الطرق الترابية"],"h1":"فكّر ماذا يحدث للسيارات التي خلف سائق بطيء جدًا.","h2":"نعم. في Florida يمكن أن تحصل على مخالفة إذا كنت تقود ببطء شديد حتى تعيق حركة السير العادية والآمنة.","p":"صحيح. القيادة ببطء شديد حتى تعيق السير مخالفة للقانون."},"ht":{"q":"Nan Florida, èske ou ka pran yon kontravansyon paske ou kondi twò dousman?","o":["Wi, si ou bloke sikilasyon nòmal la","Non, kondi dousman toujou legal","Sèlman si ou kondi pi dousman pase 10 mph","Sèlman sou wout tè"],"h1":"Panse ak sa k ap rive machin ki dèyè yon chofè ki kondi trè dousman.","h2":"Wi. Nan Florida ou ka pran yon kontravansyon si ou kondi tèlman dousman ou bloke sikilasyon nòmal ki san danje a.","p":"Wi, se sa. Kondi tèlman dousman ou bloke sikilasyon an se kont lalwa."},"ref":{"doc":"FL","page":68}},{"id":"speed-lanes-008","scope":"US","cat":"speed-lanes","sign":{"shape":"rect-white","text":"SPEED LIMIT 55"},"c":2,"en":{"q":"What does this white sign tell you?","o":["You must drive exactly 55 mph","The slowest speed allowed is 55 mph","The fastest speed allowed in good conditions is 55 mph","The suggested speed for a curve is 55 mph"],"h1":"White signs with black letters are rules. Is this number a top or a bottom?","h2":"A white speed limit sign shows the highest legal speed when conditions are good, so you may not drive faster than 55 mph there.","p":"Right. The speed limit sign shows the top legal speed in good conditions."},"es":{"q":"¿Qué le indica este letrero blanco?","o":["Debe manejar exactamente a 55 mph","La velocidad más baja permitida es 55 mph","La velocidad más alta permitida con buenas condiciones es 55 mph","La velocidad sugerida para una curva es 55 mph"],"h1":"Los letreros blancos con letras negras son reglas. ¿Este número es un máximo o un mínimo?","h2":"Un letrero blanco de límite de velocidad muestra la velocidad legal más alta con buenas condiciones, así que no puede manejar a más de 55 mph allí.","p":"Correcto. El letrero de límite muestra la velocidad legal más alta con buenas condiciones."},"zh":{"q":"这个白色标志告诉你什么？","o":["你必须正好开 55 英里/小时","允许的最低速度是 55 英里/小时","路况好时允许的最高速度是 55 英里/小时","弯道的建议速度是 55 英里/小时"],"h1":"白底黑字的标志是规定。这个数字是最高还是最低？","h2":"白色的限速标志显示路况好时的最高合法速度，所以在那里你不能开得比 55 英里/小时更快。","p":"对。限速标志显示路况好时的最高合法速度。"},"vi":{"q":"Biển báo màu trắng này cho bạn biết điều gì?","o":["Bạn phải chạy đúng 55 mph","Tốc độ chậm nhất được phép là 55 mph","Tốc độ nhanh nhất được phép khi điều kiện tốt là 55 mph","Tốc độ đề nghị khi vào khúc cua là 55 mph"],"h1":"Biển trắng chữ đen là luật. Con số này là mức cao nhất hay thấp nhất?","h2":"Biển trắng \"SPEED LIMIT\" (Giới hạn tốc độ) cho biết tốc độ hợp pháp cao nhất khi điều kiện tốt, nên ở đó bạn không được chạy nhanh hơn 55 mph.","p":"Đúng. Biển \"SPEED LIMIT\" cho biết tốc độ hợp pháp cao nhất khi điều kiện tốt."},"tl":{"q":"Ano ang sinasabi sa iyo ng puting karatulang ito?","o":["Dapat kang magmaneho nang eksaktong 55 mph","Ang pinakamabagal na pinapayagang bilis ay 55 mph","Ang pinakamabilis na pinapayagang bilis kapag maayos ang kondisyon ay 55 mph","Ang iminumungkahing bilis sa kurbada ay 55 mph"],"h1":"Ang mga puting karatulang may itim na letra ay mga patakaran. Pinakamataas ba o pinakamababa ang numerong ito?","h2":"Ang puting speed limit sign ay nagpapakita ng pinakamataas na legal na bilis kapag maayos ang kondisyon, kaya hindi ka puwedeng magmaneho nang mas mabilis sa 55 mph doon.","p":"Tama. Ipinapakita ng speed limit sign ang pinakamataas na legal na bilis kapag maayos ang kondisyon."},"ar":{"q":"ماذا تخبرك هذه العلامة البيضاء؟","o":["يجب أن أقود بسرعة 55 ميلًا في الساعة بالضبط","أقل سرعة مسموحة هي 55 ميلًا في الساعة","أعلى سرعة مسموحة في الظروف الجيدة هي 55 ميلًا في الساعة","السرعة المقترحة للمنعطف هي 55 ميلًا في الساعة"],"h1":"العلامات البيضاء ذات الحروف السوداء هي قواعد. هل هذا الرقم حد أعلى أم حد أدنى؟","h2":"علامة \"SPEED LIMIT\" (حد السرعة) البيضاء تُظهر أعلى سرعة قانونية عندما تكون الظروف جيدة، لذلك لا يجوز أن تقود هناك أسرع من 55 ميلًا في الساعة.","p":"صحيح. علامة حد السرعة تُظهر أعلى سرعة قانونية في الظروف الجيدة."},"ht":{"q":"Kisa siy blan sa a di ou?","o":["Ou dwe kondi egzakteman 55 mph","Vitès ki pi dousman yo pèmèt la se 55 mph","Vitès ki pi rapid yo pèmèt lè kondisyon yo bon an se 55 mph","Vitès yo konseye pou yon koub se 55 mph"],"h1":"Siy blan ak lèt nwa se règ. Èske chif sa a se yon maksimòm oswa yon minimòm?","h2":"Yon siy limit vitès blan montre vitès legal ki pi wo a lè kondisyon yo bon, kidonk ou pa ka kondi pi vit pase 55 mph la.","p":"Wi, se sa. Siy limit vitès la montre vitès legal ki pi wo a lè kondisyon yo bon."},"ref":{"doc":"FL","page":47}},{"id":"speed-lanes-009","scope":"US","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"What is a good way to check if you are following too closely?","o":["Count the car lengths in your mirror","Watch the speed of the car behind you","Count the seconds after the car ahead passes a fixed object","Check if you can read the license plate ahead"],"h1":"Pick something that does not move, like a sign or a pole.","h2":"When the car ahead passes a fixed object, count the seconds until you reach it, and if you reach it too soon, you are following too closely.","p":"Right. Counting seconds past a fixed object shows your following distance."},"es":{"q":"¿Cuál es una buena forma de saber si va demasiado cerca del carro de adelante?","o":["Contar los largos de carro en el espejo","Mirar la velocidad del carro que va detrás","Contar los segundos después de que el carro de adelante pasa un objeto fijo","Ver si puede leer la placa del carro de adelante"],"h1":"Escoja algo que no se mueva, como un letrero o un poste.","h2":"Cuando el carro de adelante pasa un objeto fijo, cuente los segundos hasta que usted llegue allí; si llega muy pronto, va demasiado cerca.","p":"Correcto. Contar segundos desde un objeto fijo muestra su distancia de seguimiento."},"zh":{"q":"用什么好方法可以检查你是不是跟车太近？","o":["在后视镜里数有几个车身长度","看你后面那辆车的速度","前车经过一个固定的东西后，数几秒","看你能不能看清前车的车牌"],"h1":"选一个不会动的东西，比如一个标志或一根柱子。","h2":"当前车经过一个固定的东西时，数一数你几秒后到达那里，如果你太快就到了，说明你跟车太近。","p":"对。数经过固定物体的秒数，就能知道你的跟车距离。"},"vi":{"q":"Cách nào tốt để kiểm tra xem bạn có đang chạy quá sát xe phía trước không?","o":["Đếm số chiều dài xe trong gương","Xem tốc độ của xe phía sau bạn","Đếm số giây sau khi xe phía trước chạy qua một vật đứng yên","Xem bạn có đọc được biển số xe phía trước không"],"h1":"Hãy chọn một vật không di chuyển, như biển báo hoặc cột điện.","h2":"Khi xe phía trước chạy qua một vật đứng yên, bạn đếm số giây cho đến khi bạn đến vật đó, và nếu bạn đến quá sớm thì bạn đang chạy quá sát.","p":"Đúng. Đếm số giây qua một vật đứng yên cho biết khoảng cách của bạn với xe trước."},"tl":{"q":"Ano ang magandang paraan para malaman kung masyado kang malapit sa sinusundan mo?","o":["Bilangin ang haba ng mga kotse sa salamin mo","Bantayan ang bilis ng kotse sa likod mo","Bilangin ang mga segundo matapos dumaan ang kotse sa unahan sa isang bagay na hindi gumagalaw","Tingnan kung nababasa mo ang plaka sa unahan"],"h1":"Pumili ng bagay na hindi gumagalaw, gaya ng karatula o poste.","h2":"Kapag dumaan ang kotse sa unahan sa isang bagay na hindi gumagalaw, bilangin ang mga segundo hanggang marating mo ito, at kung masyadong maaga mo itong narating, masyado kang malapit.","p":"Tama. Ipinapakita ng pagbilang ng segundo sa isang bagay na hindi gumagalaw ang layo mo sa sinusundan."},"ar":{"q":"ما الطريقة الجيدة لتعرف إن كنت تقترب كثيرًا من السيارة التي أمامك؟","o":["أعدّ أطوال السيارات في المرآة","أراقب سرعة السيارة التي خلفي","أعدّ الثواني بعد أن تمر السيارة التي أمامي بجانب شيء ثابت","أرى إن كنت أستطيع قراءة لوحة السيارة التي أمامي"],"h1":"اختر شيئًا لا يتحرك، مثل علامة أو عمود.","h2":"عندما تمر السيارة التي أمامك بجانب شيء ثابت، عدّ الثواني حتى تصل أنت إليه، وإذا وصلت إليه بسرعة كبيرة، فأنت قريب جدًا منها.","p":"صحيح. عدّ الثواني بعد شيء ثابت يُظهر لك مسافة الأمان خلف السيارة."},"ht":{"q":"Ki bon fason pou tcheke si w ap swiv twò pre?","o":["Konte longè machin nan retwovizè ou","Gade vitès machin ki dèyè ou a","Konte segonn yo apre machin devan an fin pase yon bagay ki pa bouje","Tcheke si ou ka li plak machin devan an"],"h1":"Chwazi yon bagay ki pa bouje, tankou yon siy oswa yon poto.","h2":"Lè machin devan an pase yon bagay ki pa bouje, konte segonn yo jiskaske ou rive la, epi si ou rive twò vit, sa vle di w ap swiv twò pre.","p":"Wi, se sa. Konte segonn apre yon bagay ki pa bouje montre distans ou kite dèyè lòt machin nan."},"ref":{"doc":"FL","page":61}},{"id":"speed-lanes-010","scope":"US","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"When should you leave more space between you and the car ahead?","o":["When the road is wet or slippery","When the road is dry and clear","When you are driving slower than usual in town","When the car ahead is a small car"],"h1":"Think about when your car needs more distance to stop.","h2":"You should leave more space when the road is wet or slippery, because your car needs a longer distance to stop.","p":"Right. On wet or slippery roads, leave extra space ahead."},"es":{"q":"¿Cuándo debe dejar más espacio entre usted y el carro de adelante?","o":["Cuando la carretera está mojada o resbalosa","Cuando la carretera está seca y despejada","Cuando maneja más despacio de lo normal en la ciudad","Cuando el carro de adelante es pequeño"],"h1":"Piense en cuándo su carro necesita más distancia para frenar.","h2":"Debe dejar más espacio cuando la carretera está mojada o resbalosa, porque su carro necesita más distancia para detenerse.","p":"Correcto. En carretera mojada o resbalosa, deje más espacio adelante."},"zh":{"q":"什么时候你应该和前车留更多距离？","o":["路面湿或滑的时候","路面干燥、视线清楚的时候","在城里开得比平时慢的时候","前车是小车的时候"],"h1":"想一想，什么时候你的车需要更长的距离才能停下。","h2":"路面湿或滑时，你应该留更多距离，因为你的车需要更长的距离才能停下。","p":"对。路面湿或滑时，和前车多留一些距离。"},"vi":{"q":"Khi nào bạn nên để khoảng cách lớn hơn giữa bạn và xe phía trước?","o":["Khi đường ướt hoặc trơn","Khi đường khô và thông thoáng","Khi bạn chạy chậm hơn thường lệ trong thành phố","Khi xe phía trước là xe nhỏ"],"h1":"Hãy nghĩ xem khi nào xe của bạn cần quãng đường dài hơn để dừng lại.","h2":"Bạn nên để khoảng cách lớn hơn khi đường ướt hoặc trơn, vì xe của bạn cần quãng đường dài hơn để dừng lại.","p":"Đúng. Khi đường ướt hoặc trơn, hãy để thêm khoảng cách phía trước."},"tl":{"q":"Kailan ka dapat mag-iwan ng mas malaking espasyo sa pagitan mo at ng kotse sa unahan?","o":["Kapag basa o madulas ang daan","Kapag tuyo at malinis ang daan","Kapag mas mabagal ka kaysa karaniwan sa bayan","Kapag maliit na kotse ang nasa unahan"],"h1":"Isipin kung kailan kailangan ng kotse mo ng mas mahabang layo para huminto.","h2":"Dapat kang mag-iwan ng mas malaking espasyo kapag basa o madulas ang daan, dahil kailangan ng kotse mo ng mas mahabang layo para huminto.","p":"Tama. Sa basa o madulas na daan, mag-iwan ng dagdag na espasyo sa unahan."},"ar":{"q":"متى يجب أن تترك مسافة أكبر بينك وبين السيارة التي أمامك؟","o":["عندما يكون الطريق مبللًا أو زلقًا","عندما يكون الطريق جافًا وواضحًا","عندما أقود في المدينة أبطأ من العادة","عندما تكون السيارة التي أمامي صغيرة"],"h1":"فكّر متى تحتاج سيارتك إلى مسافة أكبر لتتوقف.","h2":"يجب أن تترك مسافة أكبر عندما يكون الطريق مبللًا أو زلقًا، لأن سيارتك تحتاج إلى مسافة أطول لتتوقف.","p":"صحيح. على الطرق المبللة أو الزلقة، اترك مسافة إضافية أمامك."},"ht":{"q":"Kilè ou ta dwe kite plis espas ant ou ak machin ki devan ou a?","o":["Lè wout la mouye oswa li glise","Lè wout la sèk epi li klè","Lè w ap kondi pi dousman pase dabitid nan vil","Lè machin devan an se yon ti machin"],"h1":"Panse ak kilè machin ou bezwen plis distans pou l kanpe.","h2":"Ou ta dwe kite plis espas lè wout la mouye oswa li glise, paske machin ou bezwen yon distans pi long pou l kanpe.","p":"Wi, se sa. Sou wout ki mouye oswa ki glise, kite plis espas devan ou."},"ref":{"doc":"FL","page":61}},{"id":"speed-lanes-011","scope":"US","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"Your total stopping distance is made of which parts?","o":["Only the distance you travel while braking","Only the time it takes you to see the danger","The length of your car plus one car length","The distance you travel while you notice, react, and brake"],"h1":"Your car keeps moving before your foot even touches the brake.","h2":"Total stopping distance includes the distance you travel while you see the danger, while you move your foot, and while the brakes slow the car.","p":"Right. Stopping distance adds noticing, reacting, and braking."},"es":{"q":"¿De qué partes se forma la distancia total para detenerse?","o":["Solo la distancia que recorre mientras frena","Solo el tiempo que tarda en ver el peligro","El largo de su carro más el largo de otro carro","La distancia que recorre mientras nota el peligro, reacciona y frena"],"h1":"Su carro sigue avanzando antes de que su pie toque el freno.","h2":"La distancia total para detenerse incluye lo que recorre mientras ve el peligro, mientras mueve el pie y mientras los frenos paran el carro.","p":"Correcto. La distancia para detenerse suma notar, reaccionar y frenar."},"zh":{"q":"你的总停车距离由哪些部分组成？","o":["只有刹车时开过的距离","只有你看到危险所用的时间","你的车长再加一个车身长度","你注意到危险、做出反应和刹车时开过的距离"],"h1":"你的脚还没碰到刹车，车就一直在往前走。","h2":"总停车距离包括你看到危险时、你移动脚时，以及刹车让车慢下来时开过的距离。","p":"对。停车距离包括注意、反应和刹车这三部分。"},"vi":{"q":"Tổng quãng đường dừng xe của bạn gồm những phần nào?","o":["Chỉ quãng đường bạn chạy trong lúc đạp phanh","Chỉ thời gian bạn cần để thấy nguy hiểm","Chiều dài xe của bạn cộng thêm một chiều dài xe","Quãng đường bạn chạy trong lúc bạn nhận ra, phản ứng và đạp phanh"],"h1":"Xe của bạn vẫn chạy tiếp trước khi chân bạn chạm vào phanh.","h2":"Tổng quãng đường dừng xe gồm quãng đường bạn chạy trong lúc thấy nguy hiểm, trong lúc bạn di chuyển chân, và trong lúc phanh làm xe chậm lại.","p":"Đúng. Quãng đường dừng xe gồm lúc nhận ra, lúc phản ứng và lúc phanh."},"tl":{"q":"Ano-anong bahagi ang bumubuo sa kabuuang layo ng paghinto mo (total stopping distance)?","o":["Ang layong tinatakbo mo habang nagpepreno lang","Ang oras lang na kailangan mo para makita ang panganib","Ang haba ng kotse mo dagdag ang haba ng isang kotse","Ang layong tinatakbo mo habang napapansin mo, tumutugon ka, at nagpepreno"],"h1":"Umaandar pa ang kotse mo bago pa man dumampi ang paa mo sa preno.","h2":"Kasama sa kabuuang layo ng paghinto ang layong tinatakbo mo habang nakikita mo ang panganib, habang inililipat mo ang paa mo, at habang pinababagal ng preno ang kotse.","p":"Tama. Pinagsasama ng layo ng paghinto ang pagpansin, pagtugon, at pagpreno."},"ar":{"q":"من أي أجزاء تتكون مسافة التوقف الكاملة؟","o":["فقط المسافة التي تقطعها وأنت تضغط على الفرامل","فقط الوقت الذي تحتاجه لترى الخطر","طول سيارتك وطول سيارة أخرى","المسافة التي تقطعها وأنت تلاحظ الخطر، وتتفاعل، وتضغط على الفرامل"],"h1":"سيارتك تستمر في الحركة قبل أن تلمس قدمك الفرامل.","h2":"مسافة التوقف الكاملة تشمل المسافة التي تقطعها في ثلاث مراحل: وأنت ترى الخطر، ثم وأنت تحرك قدمك، ثم بينما تبطئ الفرامل السيارة.","p":"صحيح. مسافة التوقف تجمع الملاحظة والتفاعل والفرملة."},"ht":{"q":"Ak ki pati distans total pou ou kanpe a fèt?","o":["Sèlman distans ou fè pandan w ap fren","Sèlman tan ou pran pou wè danje a","Longè machin ou plis longè yon machin","Distans ou fè pandan ou remake danje a, ou reyaji epi ou fren"],"h1":"Machin ou kontinye avanse menm anvan pye ou touche fren an.","h2":"Distans total pou kanpe a gen ladan l distans ou fè pandan ou wè danje a, pandan ou deplase pye ou, ak pandan fren yo ap ralanti machin nan.","p":"Wi, se sa. Distans pou kanpe a se remake, reyaji, epi fren, tout ansanm."},"ref":{"doc":"FL","page":60}},{"id":"speed-lanes-012","scope":"US","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"If you drive twice as fast, what happens to the distance your brakes need to stop the car?","o":["It stays the same","It becomes about four times longer","It becomes about two times longer","It becomes shorter"],"h1":"Speed makes stopping harder very quickly, not just a little.","h2":"When your speed doubles, your braking distance becomes about four times longer, because the car carries much more energy.","p":"Right. Double the speed means about four times the braking distance."},"es":{"q":"Si maneja al doble de velocidad, ¿qué pasa con la distancia que necesitan los frenos para parar el carro?","o":["Se queda igual","Se vuelve unas cuatro veces más larga","Se vuelve unas dos veces más larga","Se vuelve más corta"],"h1":"La velocidad hace que frenar sea mucho más difícil, no solo un poco.","h2":"Cuando su velocidad se duplica, la distancia de frenado se vuelve unas cuatro veces más larga, porque el carro lleva mucha más energía.","p":"Correcto. El doble de velocidad significa unas cuatro veces la distancia de frenado."},"zh":{"q":"如果你的车速变成两倍，刹车停下需要的距离会怎么样？","o":["保持不变","变成大约四倍长","变成大约两倍长","变短"],"h1":"速度会让停车变得难很多，不只是难一点。","h2":"车速变成两倍时，刹车距离会变成大约四倍长，因为车带着多得多的能量。","p":"对。车速两倍，刹车距离大约是四倍。"},"vi":{"q":"Nếu bạn chạy nhanh gấp đôi, quãng đường phanh cần để dừng xe sẽ thay đổi thế nào?","o":["Vẫn như cũ","Dài hơn khoảng bốn lần","Dài hơn khoảng hai lần","Ngắn hơn"],"h1":"Tốc độ làm việc dừng xe khó hơn rất nhanh, không chỉ một chút.","h2":"Khi tốc độ tăng gấp đôi, quãng đường phanh của bạn dài hơn khoảng bốn lần, vì xe mang nhiều năng lượng hơn rất nhiều.","p":"Đúng. Tốc độ gấp đôi thì quãng đường phanh dài khoảng gấp bốn."},"tl":{"q":"Kung doble ang bilis mo, ano ang nangyayari sa layong kailangan ng preno mo para mapahinto ang kotse?","o":["Hindi ito nagbabago","Nagiging mga apat na beses itong mas mahaba","Nagiging mga dalawang beses itong mas mahaba","Umiikli ito"],"h1":"Napakabilis na pinahihirap ng bilis ang paghinto, hindi lang nang kaunti.","h2":"Kapag dumoble ang bilis mo, nagiging mga apat na beses na mas mahaba ang layo ng pagpreno, dahil mas malaki ang lakas (enerhiya) na dala ng kotse.","p":"Tama. Ang dobleng bilis ay nangangahulugang mga apat na beses ang layo ng pagpreno."},"ar":{"q":"إذا قدت بضعف السرعة، ماذا يحدث للمسافة التي تحتاجها الفرامل لتوقف السيارة؟","o":["تبقى كما هي","تصبح أطول بحوالي أربع مرات","تصبح أطول بحوالي مرتين","تصبح أقصر"],"h1":"السرعة تجعل التوقف أصعب بكثير وبسرعة، وليس قليلًا فقط.","h2":"عندما تتضاعف سرعتك، تصبح مسافة الفرملة أطول بحوالي أربع مرات، لأن السيارة تحمل طاقة أكبر بكثير.","p":"صحيح. ضعف السرعة يعني حوالي أربعة أضعاف مسافة الفرملة."},"ht":{"q":"Si ou kondi de fwa pi vit, kisa ki rive distans fren ou bezwen pou kanpe machin nan?","o":["Li rete menm jan an","Li vin apeprè kat fwa pi long","Li vin apeprè de fwa pi long","Li vin pi kout"],"h1":"Vitès fè li vin pi difisil pou kanpe trè vit, se pa yon ti kras sèlman.","h2":"Lè vitès ou double, distans fren ou vin apeprè kat fwa pi long, paske machin nan pote anpil plis enèji.","p":"Wi, se sa. De fwa vitès la vle di apeprè kat fwa distans fren an."},"ref":{"doc":"FL","page":60}},{"id":"speed-lanes-013","scope":"US","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"A driver is following very close behind you. What is the safest thing to do?","o":["Tap your brakes hard to warn the driver","Leave more space ahead of you and let the driver pass","Speed up to get away from the driver","Stop in your lane until the driver goes around"],"h1":"If you must stop suddenly, the driver behind may hit you. How can you avoid sudden stops?","h2":"The safest choice is to leave extra space ahead of you, so you can slow down gently, and to let the close driver pass.","p":"Right. Give yourself more space ahead and let a tailgater pass."},"es":{"q":"Un conductor va muy pegado detrás de usted. ¿Qué es lo más seguro?","o":["Frenar fuerte para avisarle al conductor","Dejar más espacio adelante y dejar que el conductor lo rebase","Acelerar para alejarse del conductor","Detenerse en su carril hasta que el conductor lo rodee"],"h1":"Si tiene que frenar de golpe, el de atrás puede chocarlo. ¿Cómo puede evitar frenadas de golpe?","h2":"Lo más seguro es dejar más espacio adelante para poder frenar suavemente, y dejar que el conductor que va pegado lo rebase.","p":"Correcto. Deje más espacio adelante y deje que el conductor pegado lo rebase."},"zh":{"q":"有一个司机紧紧跟在你后面。最安全的做法是什么？","o":["用力点一下刹车，警告那个司机","在你前面留更多空间，让那个司机超过去","加速，甩开那个司机","在你的车道里停车，等那个司机绕过去"],"h1":"如果你必须突然停车，后面的司机可能会撞上你。怎样才能避免突然停车？","h2":"最安全的做法是在你前面多留空间，这样你可以慢慢减速，并让跟得很近的司机超过去。","p":"对。在前面多留空间，让跟车太近的司机超过去。"},"vi":{"q":"Một người lái đang chạy rất sát phía sau bạn. Điều an toàn nhất nên làm là gì?","o":["Đạp phanh mạnh để cảnh báo người đó","Để thêm khoảng cách phía trước và để người đó vượt qua","Tăng tốc để tránh xa người đó","Dừng lại trong làn cho đến khi người đó vòng qua"],"h1":"Nếu bạn phải dừng gấp, người phía sau có thể đâm vào bạn. Làm sao để tránh phải dừng gấp?","h2":"Điều an toàn nhất là để thêm khoảng cách phía trước, để bạn có thể giảm tốc nhẹ nhàng, và để người lái bám sát vượt qua.","p":"Đúng. Hãy để thêm khoảng cách phía trước và để người bám sát vượt qua."},"tl":{"q":"May drayber na sobrang lapit sa likod mo. Ano ang pinakaligtas na gawin?","o":["Biglang tapakan ang preno para bigyan ng babala ang drayber","Mag-iwan ng mas malaking espasyo sa unahan mo at hayaang lumampas ang drayber","Bumilis para makalayo sa drayber","Huminto sa lane mo hanggang umikot ang drayber"],"h1":"Kung bigla kang hihinto, maaaring mabangga ka ng drayber sa likod. Paano mo maiiwasan ang biglang paghinto?","h2":"Ang pinakaligtas na gawin ay mag-iwan ng dagdag na espasyo sa unahan mo, para dahan-dahan kang makabagal, at hayaang lumampas ang drayber na sobrang lapit.","p":"Tama. Bigyan ang sarili ng mas malaking espasyo sa unahan at hayaang lumampas ang dumidikit sa likod mo."},"ar":{"q":"سائق يسير قريبًا جدًا خلفك. ما أكثر شيء آمن تفعله؟","o":["أضغط على الفرامل بقوة لأحذّر السائق","أترك مسافة أكبر أمامي وأترك السائق يتجاوزني","أسرع لأبتعد عن السائق","أتوقف في مساري حتى يلتف السائق حولي"],"h1":"إذا اضطررت إلى التوقف فجأة، قد يصدمك السائق الذي خلفك. كيف تتجنب التوقف المفاجئ؟","h2":"الخيار الأكثر أمانًا هو أن تترك مسافة إضافية أمامك، حتى تستطيع أن تخفف السرعة بهدوء، وأن تترك السائق القريب يتجاوزك.","p":"صحيح. اترك لنفسك مسافة أكبر أمامك واترك السائق الملاصق لك يتجاوزك."},"ht":{"q":"Yon chofè ap swiv ou trè pre dèyè. Kisa ki pi an sekirite pou ou fè?","o":["Peze fren an fò pou avèti chofè a","Kite plis espas devan ou epi kite chofè a pase","Akselere pou ale lwen chofè a","Kanpe nan liy ou jiskaske chofè a pase bò kote ou"],"h1":"Si ou oblije kanpe sou kou, chofè ki dèyè a ka frape ou. Kijan ou ka evite kanpe sou kou?","h2":"Pi bon chwa a se kite plis espas devan ou, pou ou ka ralanti dousman, epi kite chofè ki twò pre a pase.","p":"Wi, se sa. Kite plis espas devan ou epi kite chofè ki twò pre dèyè ou a pase."}},{"id":"speed-lanes-014","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, on a two-lane road, how close to an intersection or railroad crossing may you pass another car?","o":["Not within 25 feet","Not within 50 feet","Passing is allowed right up to it","Not within 100 feet"],"h1":"Cars and trains may enter the road there. You need a clear stretch.","h2":"In Florida you may not pass on a two-lane road within 100 feet of an intersection or a railroad crossing, because traffic may enter or stop there.","p":"Right. Do not pass within 100 feet of an intersection or railroad crossing."},"es":{"q":"En Florida, en una carretera de dos carriles, ¿qué tan cerca de una intersección o un cruce de tren puede rebasar a otro carro?","o":["No a menos de 25 pies","No a menos de 50 pies","Se puede rebasar hasta llegar allí","No a menos de 100 pies"],"h1":"Allí pueden entrar carros o trenes. Necesita un tramo despejado.","h2":"En Florida no puede rebasar en una carretera de dos carriles a menos de 100 pies de una intersección o de un cruce de tren, porque el tráfico puede entrar o detenerse allí.","p":"Correcto. No rebase a menos de 100 pies de una intersección o un cruce de tren."},"zh":{"q":"在 Florida，在双车道道路上，离路口或铁路道口多近时不能超车？","o":["25 英尺以内不能超车","50 英尺以内不能超车","可以一直超车到路口","100 英尺以内不能超车"],"h1":"车和火车可能在那里开进来。你需要一段畅通的路。","h2":"在 Florida，在双车道道路上，离路口或铁路道口 100 英尺以内不能超车，因为车辆可能在那里开进来或停下。","p":"对。离路口或铁路道口 100 英尺以内不要超车。"},"vi":{"q":"Ở Florida, trên đường hai làn, bạn được vượt xe khác gần giao lộ hoặc chỗ giao nhau với đường sắt đến mức nào?","o":["Không được trong vòng 25 feet","Không được trong vòng 50 feet","Được vượt sát đến tận đó","Không được trong vòng 100 feet"],"h1":"Xe hơi và tàu hỏa có thể đi vào đường ở đó. Bạn cần một đoạn đường trống.","h2":"Ở Florida, bạn không được vượt trên đường hai làn trong vòng 100 feet trước giao lộ hoặc chỗ giao nhau với đường sắt, vì xe cộ có thể đi vào hoặc dừng ở đó.","p":"Đúng. Không vượt trong vòng 100 feet trước giao lộ hoặc chỗ giao nhau với đường sắt."},"tl":{"q":"Sa Florida, sa daang may dalawang lane, gaano kalapit sa intersection o railroad crossing ka puwedeng lumampas sa ibang kotse?","o":["Hindi sa loob ng 25 feet","Hindi sa loob ng 50 feet","Puwedeng lumampas hanggang mismong doon","Hindi sa loob ng 100 feet"],"h1":"Maaaring pumasok sa daan ang mga kotse at tren doon. Kailangan mo ng malinis na bahagi ng daan.","h2":"Sa Florida, hindi ka puwedeng lumampas sa daang may dalawang lane sa loob ng 100 feet mula sa intersection o railroad crossing, dahil maaaring pumasok o huminto ang trapiko roon.","p":"Tama. Huwag lumampas sa loob ng 100 feet mula sa intersection o railroad crossing."},"ar":{"q":"في Florida، على طريق فيه مساران، كم يمكنك أن تقترب من تقاطع أو من تقاطع سكة حديد وأنت تتجاوز سيارة أخرى؟","o":["ليس في حدود 25 قدمًا","ليس في حدود 50 قدمًا","التجاوز مسموح حتى الوصول إليه","ليس في حدود 100 قدم"],"h1":"السيارات والقطارات قد تدخل الطريق هناك. تحتاج إلى مسافة فارغة.","h2":"في Florida لا يجوز أن تتجاوز على طريق فيه مساران في حدود 100 قدم من تقاطع أو من تقاطع سكة حديد، لأن السيارات قد تدخل أو تتوقف هناك.","p":"صحيح. لا تتجاوز في حدود 100 قدم من تقاطع أو من تقاطع سكة حديد."},"ht":{"q":"Nan Florida, sou yon wout ki gen de liy, a ki distans de yon kafou oswa yon kwazman tren ou ka double yon lòt machin?","o":["Pa nan mwens pase 25 pye","Pa nan mwens pase 50 pye","Ou ka double jis rive bò kote l","Pa nan mwens pase 100 pye"],"h1":"Machin ak tren ka antre sou wout la la. Ou bezwen yon bout wout ki lib.","h2":"Nan Florida ou pa ka double sou yon wout ki gen de liy nan mwens pase 100 pye de yon kafou oswa yon kwazman tren, paske machin ka antre oswa kanpe la.","p":"Wi, se sa. Pa double nan mwens pase 100 pye de yon kafou oswa yon kwazman tren."},"ref":{"doc":"FL","page":67}},{"id":"speed-lanes-015","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, when may you pass another car on the right?","o":["When the car ahead is turning left and there is a lane to pass in","When the car ahead is going a little slow on a two-lane road","When you can use the paved shoulder","Whenever the left lane is busy"],"h1":"You must stay on the road itself, not on the shoulder.","h2":"You may pass on the right when the car ahead is turning left and there is a full lane for you, but you may never drive on the shoulder to pass.","p":"Right. Pass on the right only with a real lane, like when a car is turning left."},"es":{"q":"En Florida, ¿cuándo puede rebasar a otro carro por la derecha?","o":["Cuando el carro de adelante va a girar a la izquierda y hay un carril para rebasar","Cuando el carro de adelante va un poco lento en una carretera de dos carriles","Cuando puede usar el acotamiento pavimentado","Siempre que el carril izquierdo esté ocupado"],"h1":"Debe quedarse en la vía, no en el acotamiento.","h2":"Puede rebasar por la derecha cuando el carro de adelante va a girar a la izquierda y hay un carril completo para usted, pero nunca puede usar el acotamiento para rebasar.","p":"Correcto. Rebase por la derecha solo si hay un carril de verdad, como cuando un carro gira a la izquierda."},"zh":{"q":"在 Florida，什么时候可以从右边超车？","o":["前车正在左转，而且有一条车道可以超车时","在双车道道路上，前车开得有点慢时","你可以用铺了路面的路肩时","左边车道车很多的时候"],"h1":"你必须留在道路上，不能开到路肩上。","h2":"当前车正在左转，而且有一整条车道给你时，你可以从右边超车，但你永远不能开上路肩去超车。","p":"对。只有在有真正车道时才从右边超车，比如前车正在左转时。"},"vi":{"q":"Ở Florida, khi nào bạn được vượt xe khác bên phải?","o":["Khi xe phía trước đang rẽ trái và có làn để bạn vượt","Khi xe phía trước chạy hơi chậm trên đường hai làn","Khi bạn có thể dùng lề đường tráng nhựa","Bất cứ khi nào làn trái đông xe"],"h1":"Bạn phải ở trên mặt đường, không phải trên lề.","h2":"Bạn được vượt bên phải khi xe phía trước đang rẽ trái và có một làn đầy đủ cho bạn, nhưng bạn không bao giờ được chạy trên lề để vượt.","p":"Đúng. Chỉ vượt bên phải khi có làn thật sự, như khi xe phía trước đang rẽ trái."},"tl":{"q":"Sa Florida, kailan ka puwedeng lumampas sa ibang kotse sa kanan?","o":["Kapag kumakaliwa ang kotse sa unahan at may lane na madadaanan mo","Kapag medyo mabagal ang kotse sa unahan sa daang may dalawang lane","Kapag puwede mong gamitin ang sementadong shoulder","Tuwing masikip ang kaliwang lane"],"h1":"Dapat kang manatili sa mismong daan, hindi sa shoulder.","h2":"Puwede kang lumampas sa kanan kapag kumakaliwa ang kotse sa unahan at may buong lane para sa iyo, pero hindi ka kailanman puwedeng magmaneho sa shoulder para lumampas.","p":"Tama. Lumampas sa kanan lang kapag may tunay na lane, gaya ng kapag kumakaliwa ang isang kotse."},"ar":{"q":"في Florida، متى يمكنك أن تتجاوز سيارة أخرى من اليمين؟","o":["عندما تنعطف السيارة التي أمامي يسارًا ويوجد مسار أتجاوز فيه","عندما تسير السيارة التي أمامي ببطء قليلًا على طريق فيه مساران","عندما أستطيع أن أستعمل كتف الطريق المرصوف","كلما كان المسار الأيسر مزدحمًا"],"h1":"يجب أن تبقى على الطريق نفسه، وليس على كتف الطريق.","h2":"يمكنك أن تتجاوز من اليمين عندما تنعطف السيارة التي أمامك يسارًا ويوجد مسار كامل لك، لكن لا يجوز أبدًا أن تقود على كتف الطريق لتتجاوز.","p":"صحيح. تجاوز من اليمين فقط عندما يوجد مسار حقيقي، مثل عندما تنعطف سيارة يسارًا."},"ht":{"q":"Nan Florida, kilè ou ka double yon lòt machin sou bò dwat?","o":["Lè machin devan an ap vire agòch epi gen yon liy pou ou pase","Lè machin devan an ap kondi yon ti kras dousman sou yon wout ki gen de liy","Lè ou ka sèvi ak bò wout ki asfalte a","Chak fwa liy gòch la chaje"],"h1":"Ou dwe rete sou wout la menm, pa sou bò wout la.","h2":"Ou ka double sou bò dwat lè machin devan an ap vire agòch epi gen yon liy konplè pou ou, men ou pa janm ka kondi sou bò wout la pou double.","p":"Wi, se sa. Double sou bò dwat sèlman lè gen yon vrè liy, tankou lè yon machin ap vire agòch."},"ref":{"doc":"FL","page":67}},{"id":"speed-lanes-016","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, another car is passing you. What should you do?","o":["Speed up so the other car cannot pass","Move to the left to block the other car","Stay in your lane and do not speed up","Brake hard to let the other car in"],"h1":"Make it easy and safe for the other driver to finish passing.","h2":"When another car passes you, you must stay in your lane and not speed up, so the other driver can finish passing safely.","p":"Right. When someone passes you, keep your lane and do not speed up."},"es":{"q":"En Florida, otro carro lo está rebasando. ¿Qué debe hacer?","o":["Acelerar para que el otro carro no lo rebase","Moverse a la izquierda para bloquear al otro carro","Quedarse en su carril y no acelerar","Frenar fuerte para dejar entrar al otro carro"],"h1":"Hágale fácil y seguro al otro conductor terminar de rebasar.","h2":"Cuando otro carro lo rebasa, debe quedarse en su carril y no acelerar, para que el otro conductor termine de rebasar con seguridad.","p":"Correcto. Cuando alguien lo rebasa, quédese en su carril y no acelere."},"zh":{"q":"在 Florida，另一辆车正在超你的车。你应该怎么做？","o":["加速，不让对方超过去","向左移，挡住对方","留在你的车道里，不要加速","用力刹车，让对方进来"],"h1":"让对方司机能轻松、安全地完成超车。","h2":"别的车超你时，你必须留在你的车道里，不要加速，让对方司机能安全地完成超车。","p":"对。有人超你时，保持在你的车道，不要加速。"},"vi":{"q":"Ở Florida, một xe khác đang vượt bạn. Bạn nên làm gì?","o":["Tăng tốc để xe kia không vượt được","Lấn sang trái để chặn xe kia","Ở lại trong làn của bạn và không tăng tốc","Phanh gấp để cho xe kia vào"],"h1":"Hãy giúp người lái kia vượt xong một cách dễ dàng và an toàn.","h2":"Khi có xe khác vượt bạn, bạn phải ở lại trong làn và không tăng tốc, để người lái kia vượt xong an toàn.","p":"Đúng. Khi có người vượt bạn, hãy giữ làn và không tăng tốc."},"tl":{"q":"Sa Florida, may ibang kotseng lumalampas sa iyo. Ano ang dapat mong gawin?","o":["Bumilis para hindi makalampas ang ibang kotse","Lumipat pakaliwa para harangan ang ibang kotse","Manatili sa lane mo at huwag bumilis","Biglang magpreno para makapasok ang ibang kotse"],"h1":"Gawing madali at ligtas para sa ibang drayber ang pagtatapos ng paglampas.","h2":"Kapag may kotseng lumalampas sa iyo, dapat kang manatili sa lane mo at huwag bumilis, para ligtas na matapos ng ibang drayber ang paglampas.","p":"Tama. Kapag may lumalampas sa iyo, manatili sa lane mo at huwag bumilis."},"ar":{"q":"في Florida، سيارة أخرى تتجاوزك. ماذا يجب أن تفعل؟","o":["أسرع حتى لا تستطيع السيارة الأخرى أن تتجاوزني","أتحرك إلى اليسار لأمنع السيارة الأخرى","أبقى في مساري ولا أسرع","أضغط على الفرامل بقوة لأترك السيارة الأخرى تدخل"],"h1":"اجعل إنهاء التجاوز سهلًا وآمنًا للسائق الآخر.","h2":"عندما تتجاوزك سيارة أخرى، يجب أن تبقى في مسارك ولا تسرع، حتى يستطيع السائق الآخر أن ينهي التجاوز بأمان.","p":"صحيح. عندما يتجاوزك أحد، ابقَ في مسارك ولا تسرع."},"ht":{"q":"Nan Florida, yon lòt machin ap double ou. Kisa ou ta dwe fè?","o":["Akselere pou lòt machin nan pa ka double","Deplase sou bò gòch pou bloke lòt machin nan","Rete nan liy ou epi pa akselere","Peze fren an fò pou kite lòt machin nan antre"],"h1":"Fè li fasil epi san danje pou lòt chofè a fin double.","h2":"Lè yon lòt machin ap double ou, ou dwe rete nan liy ou epi pa akselere, pou lòt chofè a ka fin double san danje.","p":"Wi, se sa. Lè yon moun ap double ou, rete nan liy ou epi pa akselere."},"ref":{"doc":"FL","page":67}},{"id":"speed-lanes-017","scope":"US","cat":"speed-lanes","sign":{"shape":"no-passing","text":"NO PASSING ZONE"},"c":2,"en":{"q":"What does this yellow pennant-shaped sign mean?","o":["A school zone starts here","The road ends ahead","A no-passing zone starts here","You may pass on the right"],"h1":"This sign is on the left side of the road, where drivers look before they pass.","h2":"The yellow pennant sign marks the start of a no-passing zone, so you may not pass other cars from that point.","p":"Right. The pennant sign shows where a no-passing zone begins."},"es":{"q":"¿Qué significa este letrero amarillo en forma de banderín?","o":["Aquí empieza una zona escolar","La carretera termina más adelante","Aquí empieza una zona donde no se puede rebasar","Puede rebasar por la derecha"],"h1":"Este letrero está al lado izquierdo de la carretera, donde miran los conductores antes de rebasar.","h2":"El letrero amarillo en forma de banderín marca el inicio de una zona donde no se puede rebasar, así que desde allí no puede rebasar a otros carros.","p":"Correcto. El banderín muestra dónde empieza la zona sin rebase."},"zh":{"q":"这个黄色三角旗形的标志是什么意思？","o":["学校区从这里开始","前面道路到头了","禁止超车区从这里开始","你可以从右边超车"],"h1":"这个标志在道路的左边，就是司机超车前会看的地方。","h2":"黄色三角旗形标志表示禁止超车区的开始，所以从那里开始你不能超车。","p":"对。三角旗形标志表示禁止超车区从哪里开始。"},"vi":{"q":"Biển báo màu vàng hình cờ đuôi nheo này có nghĩa là gì?","o":["Khu vực trường học bắt đầu ở đây","Phía trước hết đường","Khu vực cấm vượt bắt đầu ở đây","Bạn được vượt bên phải"],"h1":"Biển này nằm ở bên trái đường, nơi người lái nhìn trước khi vượt.","h2":"Biển màu vàng hình cờ đuôi nheo đánh dấu nơi bắt đầu khu vực cấm vượt, nên từ điểm đó bạn không được vượt xe khác.","p":"Đúng. Biển hình cờ đuôi nheo cho biết nơi bắt đầu khu vực cấm vượt."},"tl":{"q":"Ano ang ibig sabihin ng dilaw na karatulang hugis pennant (mahabang tatsulok na bandila) na ito?","o":["Dito nagsisimula ang school zone","Nagtatapos ang daan sa unahan","Dito nagsisimula ang no-passing zone (bawal lumampas)","Puwede kang lumampas sa kanan"],"h1":"Nasa kaliwang gilid ng daan ang karatulang ito, kung saan tumitingin ang mga drayber bago lumampas.","h2":"Ang dilaw na pennant na karatula ay nagmamarka ng simula ng no-passing zone, kaya hindi ka puwedeng lumampas sa ibang kotse mula sa puntong iyon.","p":"Tama. Ipinapakita ng pennant na karatula kung saan nagsisimula ang no-passing zone."},"ar":{"q":"ماذا تعني هذه العلامة الصفراء التي على شكل راية مثلثة؟","o":["تبدأ منطقة مدرسة هنا","الطريق ينتهي أمامك","تبدأ منطقة ممنوع فيها التجاوز هنا","يمكنك أن تتجاوز من اليمين"],"h1":"هذه العلامة على الجانب الأيسر من الطريق، حيث ينظر السائقون قبل أن يتجاوزوا.","h2":"العلامة الصفراء التي على شكل راية تدل على بداية منطقة ممنوع فيها التجاوز، لذلك لا يجوز أن تتجاوز السيارات الأخرى من تلك النقطة.","p":"صحيح. علامة الراية تُظهر أين تبدأ منطقة ممنوع فيها التجاوز."},"ht":{"q":"Kisa siy jòn sa a ki gen fòm yon drapo pwenti (pennant) vle di?","o":["Yon zòn lekòl kòmanse la","Wout la fini devan","Yon zòn kote ou pa ka double kòmanse la","Ou ka double sou bò dwat"],"h1":"Siy sa a sou bò gòch wout la, kote chofè yo gade anvan yo double.","h2":"Siy jòn ki gen fòm drapo pwenti a make kote yon zòn ou pa ka double kòmanse, kidonk ou pa ka double lòt machin depi kote sa a.","p":"Wi, se sa. Siy drapo pwenti a montre kote yon zòn ou pa ka double kòmanse."},"ref":{"doc":"FL","page":48}},{"id":"speed-lanes-018","scope":"US","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"There is a solid yellow line on your side of the center line. What does it mean?","o":["You may not pass","You may pass when it is safe","The road is one-way","You must stop ahead"],"h1":"Look closely: is the line on your side broken or solid?","h2":"A solid yellow line on your side of the center means you may not cross it to pass other cars.","p":"Right. A solid yellow line on your side means no passing."},"es":{"q":"Hay una línea amarilla continua de su lado de la línea central. ¿Qué significa?","o":["No puede rebasar","Puede rebasar cuando sea seguro","La calle es de un solo sentido","Debe detenerse más adelante"],"h1":"Mire bien: ¿la línea de su lado es cortada o continua?","h2":"Una línea amarilla continua de su lado de la línea central significa que no puede cruzarla para rebasar a otros carros.","p":"Correcto. Una línea amarilla continua de su lado significa que no puede rebasar."},"zh":{"q":"在中心线你这一边有一条黄色实线。这是什么意思？","o":["你不能超车","安全时你可以超车","这条路是单行道","你前面必须停车"],"h1":"仔细看：你这一边的线是虚线还是实线？","h2":"中心线你这一边的黄色实线表示你不能越过它去超车。","p":"对。你这一边是黄色实线，表示不能超车。"},"vi":{"q":"Có một vạch vàng liền ở phía bên bạn của vạch giữa đường. Vạch đó có nghĩa là gì?","o":["Bạn không được vượt","Bạn được vượt khi an toàn","Đường này là đường một chiều","Bạn phải dừng ở phía trước"],"h1":"Hãy nhìn kỹ: vạch ở phía bên bạn là vạch đứt hay vạch liền?","h2":"Vạch vàng liền ở phía bên bạn của vạch giữa đường có nghĩa là bạn không được vượt qua vạch đó để vượt xe khác.","p":"Đúng. Vạch vàng liền ở phía bên bạn có nghĩa là cấm vượt."},"tl":{"q":"May tuloy-tuloy na dilaw na guhit sa panig mo ng center line (guhit sa gitna). Ano ang ibig sabihin nito?","o":["Bawal kang lumampas","Puwede kang lumampas kapag ligtas","One-way ang daan","Dapat kang huminto sa unahan"],"h1":"Tingnang mabuti: putol-putol ba o tuloy-tuloy ang guhit sa panig mo?","h2":"Ang tuloy-tuloy na dilaw na guhit sa panig mo ng gitna ay nangangahulugang hindi mo ito puwedeng tawirin para lumampas sa ibang kotse.","p":"Tama. Ang tuloy-tuloy na dilaw na guhit sa panig mo ay nangangahulugang bawal lumampas."},"ar":{"q":"يوجد خط أصفر متصل في جهتك من خط الوسط. ماذا يعني؟","o":["لا يجوز أن أتجاوز","يمكنني أن أتجاوز عندما يكون آمنًا","الطريق باتجاه واحد","يجب أن أتوقف أمامي"],"h1":"انظر جيدًا: هل الخط في جهتك متقطع أم متصل؟","h2":"الخط الأصفر المتصل في جهتك من خط الوسط يعني أنه لا يجوز أن تعبره لتتجاوز السيارات الأخرى.","p":"صحيح. الخط الأصفر المتصل في جهتك يعني ممنوع التجاوز."},"ht":{"q":"Gen yon liy jòn ki pa koupe sou bò pa w la nan liy mitan an. Kisa li vle di?","o":["Ou pa ka double","Ou ka double lè li pa danjere","Wout la se yon sèl sans","Ou dwe kanpe devan"],"h1":"Gade byen: èske liy ki sou bò pa w la koupe oswa li pa koupe?","h2":"Yon liy jòn ki pa koupe sou bò pa w la nan mitan wout la vle di ou pa ka travèse l pou double lòt machin.","p":"Wi, se sa. Yon liy jòn ki pa koupe sou bò pa w la vle di ou pa ka double."},"ref":{"doc":"FL","page":44}},{"id":"speed-lanes-019","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, how far before a turn must you start using your turn signal?","o":["At least 25 feet","At least 50 feet","Only when you begin to turn","At least 100 feet"],"h1":"Give other drivers enough warning before you move.","h2":"In Florida you must turn on your signal at least 100 feet before you turn, so other drivers know what you plan to do.","p":"Right. Signal at least 100 feet before you turn."},"es":{"q":"En Florida, ¿con cuánta anticipación debe poner la direccional antes de girar?","o":["Al menos 25 pies antes","Al menos 50 pies antes","Solo cuando empieza a girar","Al menos 100 pies antes"],"h1":"Avise a los demás conductores con suficiente tiempo antes de moverse.","h2":"En Florida debe poner la direccional al menos 100 pies antes de girar, para que los demás sepan lo que va a hacer.","p":"Correcto. Ponga la direccional al menos 100 pies antes de girar."},"zh":{"q":"在 Florida，转弯前多远必须开始打转向灯？","o":["至少 25 英尺","至少 50 英尺","只在开始转弯时","至少 100 英尺"],"h1":"在你移动之前，给其他司机足够的提醒。","h2":"在 Florida，你必须在转弯前至少 100 英尺打开转向灯，让其他司机知道你要做什么。","p":"对。转弯前至少 100 英尺打转向灯。"},"vi":{"q":"Ở Florida, bạn phải bắt đầu bật xi nhan bao xa trước khi rẽ?","o":["Ít nhất 25 feet","Ít nhất 50 feet","Chỉ khi bạn bắt đầu rẽ","Ít nhất 100 feet"],"h1":"Hãy báo trước đủ cho người lái khác trước khi bạn di chuyển.","h2":"Ở Florida, bạn phải bật xi nhan ít nhất 100 feet trước khi rẽ, để người lái khác biết bạn định làm gì.","p":"Đúng. Hãy bật xi nhan ít nhất 100 feet trước khi rẽ."},"tl":{"q":"Sa Florida, gaano kalayo bago lumiko dapat mong simulang gamitin ang turn signal mo?","o":["Hindi bababa sa 25 feet","Hindi bababa sa 50 feet","Kapag nagsisimula ka lang lumiko","Hindi bababa sa 100 feet"],"h1":"Bigyan ang ibang drayber ng sapat na babala bago ka gumalaw.","h2":"Sa Florida, dapat mong buksan ang signal mo nang hindi bababa sa 100 feet bago ka lumiko, para malaman ng ibang drayber ang balak mong gawin.","p":"Tama. Mag-signal nang hindi bababa sa 100 feet bago ka lumiko."},"ar":{"q":"في Florida، قبل الانعطاف بكم مسافة يجب أن تبدأ باستعمال إشارة الانعطاف؟","o":["25 قدمًا على الأقل","50 قدمًا على الأقل","فقط عندما أبدأ الانعطاف","100 قدم على الأقل"],"h1":"أعطِ السائقين الآخرين تحذيرًا كافيًا قبل أن تتحرك.","h2":"في Florida يجب أن تشغّل الإشارة قبل الانعطاف بمسافة 100 قدم على الأقل، حتى يعرف السائقون الآخرون ماذا تنوي أن تفعل.","p":"صحيح. شغّل الإشارة قبل الانعطاف بمسافة 100 قدم على الأقل."},"ht":{"q":"Nan Florida, a ki distans anvan yon vire ou dwe kòmanse mete siyal ou?","o":["Omwen 25 pye","Omwen 50 pye","Sèlman lè ou kòmanse vire","Omwen 100 pye"],"h1":"Bay lòt chofè yo ase tan pou yo konnen anvan ou deplase.","h2":"Nan Florida ou dwe limen siyal ou omwen 100 pye anvan ou vire, pou lòt chofè yo konnen sa ou vle fè.","p":"Wi, se sa. Mete siyal omwen 100 pye anvan ou vire."},"ref":{"doc":"FL","page":69}},{"id":"speed-lanes-020","scope":"US","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"You want to change lanes. What should you do right after checking your mirrors?","o":["Change lanes right away","Turn your head and look over your shoulder","Honk your horn","Slow down to a stop"],"h1":"Your mirrors cannot show every place next to your car.","h2":"After you check your mirrors, turn your head and look over your shoulder, because a car may be hiding in your blind spot.","p":"Right. Look over your shoulder to check your blind spot."},"es":{"q":"Quiere cambiar de carril. ¿Qué debe hacer justo después de revisar los espejos?","o":["Cambiar de carril enseguida","Voltear la cabeza y mirar por encima del hombro","Tocar la bocina","Frenar hasta detenerse"],"h1":"Los espejos no muestran todos los lugares al lado de su carro.","h2":"Después de revisar los espejos, voltee la cabeza y mire por encima del hombro, porque puede haber un carro escondido en su punto ciego.","p":"Correcto. Mire por encima del hombro para revisar su punto ciego."},"zh":{"q":"你想换车道。看完后视镜以后，紧接着应该做什么？","o":["马上换道","转头，从肩膀上方往后看","按喇叭","减速停下"],"h1":"后视镜不能照到你车旁边的每个地方。","h2":"看完后视镜后，要转头从肩膀上方往后看，因为可能有车藏在你的盲区里。","p":"对。转头往后看，检查你的盲区。"},"vi":{"q":"Bạn muốn đổi làn. Ngay sau khi nhìn gương, bạn nên làm gì?","o":["Đổi làn ngay","Quay đầu và nhìn qua vai","Bấm còi","Giảm tốc cho đến khi dừng"],"h1":"Gương của bạn không thể cho thấy mọi chỗ bên cạnh xe.","h2":"Sau khi nhìn gương, bạn quay đầu và nhìn qua vai, vì có thể có xe đang khuất trong điểm mù của bạn.","p":"Đúng. Hãy nhìn qua vai để kiểm tra điểm mù."},"tl":{"q":"Gusto mong lumipat ng lane. Ano ang dapat mong gawin pagkatapos tumingin sa mga salamin mo?","o":["Lumipat agad ng lane","Ilingon ang ulo mo at tumingin sa likod ng balikat mo","Bumusina","Bumagal hanggang huminto"],"h1":"Hindi kayang ipakita ng mga salamin mo ang bawat lugar sa tabi ng kotse mo.","h2":"Pagkatapos mong tumingin sa mga salamin, ilingon ang ulo mo at tumingin sa likod ng balikat mo, dahil maaaring may kotseng nakatago sa blind spot mo.","p":"Tama. Tumingin sa likod ng balikat mo para suriin ang blind spot mo."},"ar":{"q":"تريد أن تغيّر المسار. ماذا يجب أن تفعل مباشرة بعد أن تنظر في المرايا؟","o":["أغيّر المسار فورًا","أدير رأسي وأنظر من فوق كتفي","أستعمل البوق","أخفف السرعة حتى أتوقف"],"h1":"المرايا لا تستطيع أن تُظهر كل مكان بجانب سيارتك.","h2":"بعد أن تنظر في المرايا، أدر رأسك وانظر من فوق كتفك، لأن سيارة قد تكون مختبئة في النقطة العمياء.","p":"صحيح. انظر من فوق كتفك لتفحص النقطة العمياء."},"ht":{"q":"Ou vle chanje liy. Kisa ou ta dwe fè touswit apre ou fin tcheke retwovizè ou yo?","o":["Chanje liy touswit","Vire tèt ou epi gade pa dèyè zepòl ou","Klaksonnen","Ralanti jiskaske ou kanpe"],"h1":"Retwovizè ou yo pa ka montre tout kote ki bò kote machin ou.","h2":"Apre ou fin tcheke retwovizè ou yo, vire tèt ou epi gade pa dèyè zepòl ou, paske yon machin ka kache nan kwen ou pa wè a.","p":"Wi, se sa. Gade pa dèyè zepòl ou pou tcheke kwen ou pa wè a."},"ref":{"doc":"FL","page":60}},{"id":"speed-lanes-021","scope":"US","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"You need to move over three lanes to reach your exit. How should you do it?","o":["Cross all three lanes in one move","Move one lane at a time and signal each time","Signal once and then cross all lanes","Slow down in your lane and wait for a gap in all lanes"],"h1":"Each lane may have its own traffic and its own blind spot.","h2":"You should move one lane at a time, signaling and checking your blind spot before each move, because every lane can hide a car.","p":"Right. Change one lane at a time and signal each time."},"es":{"q":"Necesita pasar tres carriles para llegar a su salida. ¿Cómo debe hacerlo?","o":["Cruzar los tres carriles de una sola vez","Cambiar un carril a la vez y poner la direccional cada vez","Poner la direccional una vez y cruzar todos los carriles","Frenar en su carril y esperar un espacio en todos los carriles"],"h1":"Cada carril puede tener su propio tráfico y su propio punto ciego.","h2":"Debe cambiar un carril a la vez, poniendo la direccional y revisando el punto ciego antes de cada cambio, porque en cada carril puede haber un carro.","p":"Correcto. Cambie un carril a la vez y ponga la direccional cada vez."},"zh":{"q":"你要跨过三条车道才能到你的出口。你应该怎么做？","o":["一次跨过全部三条车道","一次换一条车道，每次都打转向灯","打一次转向灯，然后跨过所有车道","在你的车道里减速，等所有车道都有空隙"],"h1":"每条车道都可能有自己的车，也有自己的盲区。","h2":"你应该一次换一条车道，每次换道前都打转向灯、检查盲区，因为每条车道都可能藏着一辆车。","p":"对。一次换一条车道，每次都打转向灯。"},"vi":{"q":"Bạn cần chuyển qua ba làn để đến lối ra. Bạn nên làm thế nào?","o":["Chuyển qua cả ba làn một lần","Chuyển từng làn một và bật xi nhan mỗi lần","Bật xi nhan một lần rồi chuyển qua tất cả các làn","Giảm tốc trong làn của bạn và chờ khoảng trống ở tất cả các làn"],"h1":"Mỗi làn có thể có xe riêng và điểm mù riêng.","h2":"Bạn nên chuyển từng làn một, bật xi nhan và kiểm tra điểm mù trước mỗi lần chuyển, vì làn nào cũng có thể có xe bị khuất.","p":"Đúng. Hãy đổi từng làn một và bật xi nhan mỗi lần."},"tl":{"q":"Kailangan mong lumipat nang tatlong lane para marating ang exit mo. Paano mo ito dapat gawin?","o":["Tawirin ang tatlong lane sa isang galaw","Lumipat nang isang lane sa bawat pagkakataon at mag-signal bawat beses","Mag-signal nang isang beses at saka tawirin ang lahat ng lane","Bumagal sa lane mo at maghintay ng puwang sa lahat ng lane"],"h1":"Bawat lane ay maaaring may sariling trapiko at sariling blind spot.","h2":"Dapat kang lumipat nang isang lane sa bawat pagkakataon, nagsi-signal at sumusuri sa blind spot bago ang bawat paglipat, dahil bawat lane ay maaaring may nakatagong kotse.","p":"Tama. Lumipat nang isang lane sa bawat pagkakataon at mag-signal bawat beses."},"ar":{"q":"تحتاج إلى أن تنتقل ثلاثة مسارات لتصل إلى المخرج. كيف تفعل ذلك؟","o":["أعبر المسارات الثلاثة في حركة واحدة","أنتقل مسارًا واحدًا في كل مرة وأشغّل الإشارة كل مرة","أشغّل الإشارة مرة واحدة ثم أعبر كل المسارات","أخفف السرعة في مساري وأنتظر فجوة في كل المسارات"],"h1":"كل مسار قد تكون فيه سيارات خاصة به ونقطة عمياء خاصة به.","h2":"يجب أن تنتقل مسارًا واحدًا في كل مرة، وأن تشغّل الإشارة وتفحص النقطة العمياء قبل كل انتقال، لأن كل مسار قد تختبئ فيه سيارة.","p":"صحيح. غيّر مسارًا واحدًا في كل مرة وشغّل الإشارة كل مرة."},"ht":{"q":"Ou bezwen travèse twa liy pou rive nan sòti ou a. Kijan ou ta dwe fè l?","o":["Travèse twa liy yo yon sèl kou","Chanje yon liy alafwa epi mete siyal chak fwa","Mete siyal yon sèl fwa epi travèse tout liy yo","Ralanti nan liy ou epi tann yon espas nan tout liy yo"],"h1":"Chak liy ka gen pwòp machin pa l ak pwòp kwen ou pa wè.","h2":"Ou ta dwe chanje yon liy alafwa, mete siyal epi tcheke kwen ou pa wè a anvan chak chanjman, paske chak liy ka kache yon machin.","p":"Wi, se sa. Chanje yon liy alafwa epi mete siyal chak fwa."}},{"id":"speed-lanes-022","scope":"US","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"What do broken white lines between lanes mean?","o":["They separate traffic going in opposite directions","You may never cross them","They mark the edge of the road","They separate lanes going the same way, and you may change lanes when safe"],"h1":"Broken lines allow you to do something, but only when it is safe.","h2":"Broken white lines separate lanes that go the same way, and you may cross them to change lanes when it is safe.","p":"Right. Broken white lines let you change lanes when it is safe."},"es":{"q":"¿Qué significan las líneas blancas cortadas entre carriles?","o":["Separan el tráfico que va en sentidos opuestos","Nunca las puede cruzar","Marcan la orilla de la carretera","Separan carriles que van en el mismo sentido, y puede cambiar de carril cuando sea seguro"],"h1":"Las líneas cortadas le permiten hacer algo, pero solo cuando es seguro.","h2":"Las líneas blancas cortadas separan carriles que van en el mismo sentido, y puede cruzarlas para cambiar de carril cuando sea seguro.","p":"Correcto. Las líneas blancas cortadas le permiten cambiar de carril cuando es seguro."},"zh":{"q":"车道之间的白色虚线是什么意思？","o":["它们分开相反方向行驶的车","你永远不能越过它们","它们标出道路的边缘","它们分开同方向的车道，安全时你可以换道"],"h1":"虚线允许你做某件事，但只能在安全的时候。","h2":"白色虚线分开同方向的车道，安全时你可以越过它们换道。","p":"对。白色虚线表示安全时可以换道。"},"vi":{"q":"Vạch trắng đứt quãng giữa các làn có nghĩa là gì?","o":["Chúng tách các xe đi ngược chiều nhau","Bạn không bao giờ được đi qua chúng","Chúng đánh dấu mép đường","Chúng tách các làn cùng chiều, và bạn được đổi làn khi an toàn"],"h1":"Vạch đứt cho phép bạn làm một việc, nhưng chỉ khi an toàn.","h2":"Vạch trắng đứt quãng tách các làn cùng chiều, và bạn được đi qua chúng để đổi làn khi an toàn.","p":"Đúng. Vạch trắng đứt quãng cho phép bạn đổi làn khi an toàn."},"tl":{"q":"Ano ang ibig sabihin ng putol-putol na puting guhit sa pagitan ng mga lane?","o":["Pinaghihiwalay nito ang trapikong magkasalungat ang direksiyon","Hindi mo ito kailanman puwedeng tawirin","Minamarkahan nito ang gilid ng daan","Pinaghihiwalay nito ang mga lane na pareho ang direksiyon, at puwede kang lumipat ng lane kapag ligtas"],"h1":"Pinapayagan ka ng putol-putol na guhit na gumawa ng isang bagay, pero kapag ligtas lang.","h2":"Pinaghihiwalay ng putol-putol na puting guhit ang mga lane na pareho ang direksiyon, at puwede mo itong tawirin para lumipat ng lane kapag ligtas.","p":"Tama. Pinapayagan ka ng putol-putol na puting guhit na lumipat ng lane kapag ligtas."},"ar":{"q":"ماذا تعني الخطوط البيضاء المتقطعة بين المسارات؟","o":["تفصل بين سيارات تسير في اتجاهين متعاكسين","لا يجوز أبدًا أن أعبرها","تحدد طرف الطريق","تفصل بين مسارات في الاتجاه نفسه، ويمكنني أن أغيّر المسار عندما يكون آمنًا"],"h1":"الخطوط المتقطعة تسمح لك بشيء، لكن فقط عندما يكون آمنًا.","h2":"الخطوط البيضاء المتقطعة تفصل بين مسارات تسير في الاتجاه نفسه، ويمكنك أن تعبرها لتغيّر المسار عندما يكون ذلك آمنًا.","p":"صحيح. الخطوط البيضاء المتقطعة تسمح لك بتغيير المسار عندما يكون آمنًا."},"ht":{"q":"Kisa liy blan ki koupe ant liy yo vle di?","o":["Yo separe machin k ap ale nan direksyon opoze","Ou pa janm ka travèse yo","Yo make bò wout la","Yo separe liy k ap ale nan menm direksyon, epi ou ka chanje liy lè li pa danjere"],"h1":"Liy ki koupe pèmèt ou fè yon bagay, men sèlman lè li pa danjere.","h2":"Liy blan ki koupe yo separe liy k ap ale nan menm direksyon, epi ou ka travèse yo pou chanje liy lè li pa danjere.","p":"Wi, se sa. Liy blan ki koupe yo pèmèt ou chanje liy lè li pa danjere."},"ref":{"doc":"FL","page":43}},{"id":"speed-lanes-023","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, you are on the ramp to enter an expressway. What should you do?","o":["Speed up in the merge lane to match traffic and yield to cars on the expressway","Stop at the end of the ramp and wait","Drive slowly so cars on the expressway can see you","Enter right away, because cars on the expressway must let you in"],"h1":"The merge lane is there to help you reach the speed of traffic.","h2":"Use the merge lane to speed up to the speed of traffic, and yield to the cars already on the expressway before you move in.","p":"Right. Match the traffic speed and yield to cars already on the expressway."},"es":{"q":"En Florida, usted va por la rampa para entrar a una autopista. ¿Qué debe hacer?","o":["Acelerar en el carril de incorporación hasta la velocidad del tráfico y ceder el paso a los carros de la autopista","Detenerse al final de la rampa y esperar","Manejar despacio para que los carros de la autopista lo vean","Entrar enseguida, porque los carros de la autopista deben dejarlo pasar"],"h1":"El carril de incorporación sirve para que alcance la velocidad del tráfico.","h2":"Use el carril de incorporación para acelerar hasta la velocidad del tráfico, y ceda el paso a los carros que ya van por la autopista antes de entrar.","p":"Correcto. Iguale la velocidad del tráfico y ceda el paso a los carros de la autopista."},"zh":{"q":"在 Florida，你在进入快速路的匝道上。你应该怎么做？","o":["在并道车道上加速，跟上车流速度，并让快速路上的车先走","在匝道尽头停下等","慢慢开，让快速路上的车能看到你","马上开进去，因为快速路上的车必须让你进去"],"h1":"并道车道是用来帮你达到车流速度的。","h2":"利用并道车道加速到车流的速度，并在并入之前让已经在快速路上的车先走。","p":"对。跟上车流速度，并让已经在快速路上的车先走。"},"vi":{"q":"Ở Florida, bạn đang ở trên đường dẫn để vào đường cao tốc. Bạn nên làm gì?","o":["Tăng tốc trong làn nhập để bằng tốc độ dòng xe và nhường xe trên đường cao tốc","Dừng ở cuối đường dẫn và chờ","Chạy chậm để xe trên đường cao tốc thấy bạn","Vào ngay, vì xe trên đường cao tốc phải cho bạn vào"],"h1":"Làn nhập có để giúp bạn đạt tốc độ của dòng xe.","h2":"Hãy dùng làn nhập để tăng tốc bằng tốc độ dòng xe, và nhường xe đã ở trên đường cao tốc trước khi bạn nhập vào.","p":"Đúng. Hãy chạy bằng tốc độ dòng xe và nhường xe đã ở trên đường cao tốc."},"tl":{"q":"Sa Florida, nasa ramp ka papasok sa expressway. Ano ang dapat mong gawin?","o":["Bumilis sa merge lane para tumugma sa trapiko at magbigay-daan sa mga kotse sa expressway","Huminto sa dulo ng ramp at maghintay","Magmaneho nang mabagal para makita ka ng mga kotse sa expressway","Pumasok agad, dahil dapat kang papasukin ng mga kotse sa expressway"],"h1":"Nariyan ang merge lane para tulungan kang maabot ang bilis ng trapiko.","h2":"Gamitin ang merge lane para bumilis hanggang sa bilis ng trapiko, at magbigay-daan sa mga kotseng nasa expressway na bago ka pumasok.","p":"Tama. Itugma ang bilis mo sa trapiko at magbigay-daan sa mga kotseng nasa expressway na."},"ar":{"q":"في Florida، أنت على منحدر الدخول إلى طريق سريع (expressway). ماذا يجب أن تفعل؟","o":["أسرع في مسار الاندماج لأصل إلى سرعة السير، وأعطي حق المرور للسيارات على الطريق السريع","أتوقف في آخر المنحدر وأنتظر","أقود ببطء حتى تراني السيارات على الطريق السريع","أدخل فورًا، لأن السيارات على الطريق السريع يجب أن تتركني أدخل"],"h1":"مسار الاندماج موجود ليساعدك على الوصول إلى سرعة السير.","h2":"استعمل مسار الاندماج لتزيد سرعتك حتى تصل إلى سرعة السير، وأعطِ حق المرور للسيارات الموجودة على الطريق السريع قبل أن تدخل.","p":"صحيح. اجعل سرعتك مثل سرعة السير وأعطِ حق المرور للسيارات الموجودة على الطريق السريع."},"ht":{"q":"Nan Florida, ou sou ranp lan pou antre sou yon otowout. Kisa ou ta dwe fè?","o":["Akselere nan liy pou antre a pou ou rive nan vitès machin yo epi kite machin ki sou otowout la pase anvan","Kanpe nan bout ranp lan epi tann","Kondi dousman pou machin ki sou otowout la ka wè ou","Antre touswit, paske machin ki sou otowout la dwe kite ou antre"],"h1":"Liy pou antre a la pou ede ou rive nan vitès machin yo.","h2":"Sèvi ak liy pou antre a pou ou akselere jiskaske ou rive nan vitès machin yo, epi kite machin ki deja sou otowout la pase anvan ou antre.","p":"Wi, se sa. Rive nan vitès machin yo epi kite machin ki deja sou otowout la pase anvan."},"ref":{"doc":"FL","page":63}},{"id":"speed-lanes-024","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, where should you slow down when you leave an expressway?","o":["In the main lane, before the exit","On the shoulder next to the exit","In the exit lane, after you leave the main lanes","Only after you reach the end of the ramp"],"h1":"Slowing down in the main lanes can surprise the drivers behind you.","h2":"You should move into the exit lane first and then slow down there, so you do not block fast traffic in the main lanes.","p":"Right. Slow down in the exit lane, not on the main road."},"es":{"q":"En Florida, ¿dónde debe bajar la velocidad al salir de una autopista?","o":["En el carril principal, antes de la salida","En el acotamiento junto a la salida","En el carril de salida, después de dejar los carriles principales","Solo al llegar al final de la rampa"],"h1":"Frenar en los carriles principales puede sorprender a los conductores de atrás.","h2":"Primero debe pasarse al carril de salida y luego bajar la velocidad allí, para no frenar al tráfico rápido en los carriles principales.","p":"Correcto. Baje la velocidad en el carril de salida, no en la vía principal."},"zh":{"q":"在 Florida，离开快速路时，你应该在哪里减速？","o":["在主车道上，出口之前","在出口旁边的路肩上","在出口车道上，离开主车道以后","只有到了匝道尽头以后"],"h1":"在主车道上减速可能会让后面的司机措手不及。","h2":"你应该先进入出口车道，然后在那里减速，这样就不会挡住主车道上开得快的车。","p":"对。在出口车道减速，不要在主路上减速。"},"vi":{"q":"Ở Florida, bạn nên giảm tốc ở đâu khi rời khỏi đường cao tốc?","o":["Trong làn chính, trước lối ra","Trên lề cạnh lối ra","Trong làn ra, sau khi bạn rời khỏi các làn chính","Chỉ sau khi bạn đến cuối đường dẫn"],"h1":"Giảm tốc trong các làn chính có thể làm người lái phía sau bất ngờ.","h2":"Bạn nên vào làn ra trước rồi mới giảm tốc ở đó, để không cản trở dòng xe chạy nhanh trong các làn chính.","p":"Đúng. Hãy giảm tốc trong làn ra, không phải trên đường chính."},"tl":{"q":"Sa Florida, saan ka dapat bumagal kapag lalabas ka sa expressway?","o":["Sa pangunahing lane, bago ang exit","Sa shoulder sa tabi ng exit","Sa exit lane, pagkaalis mo sa mga pangunahing lane","Pagdating mo lang sa dulo ng ramp"],"h1":"Ang pagbagal sa mga pangunahing lane ay maaaring makagulat sa mga drayber sa likod mo.","h2":"Dapat ka munang lumipat sa exit lane at saka bumagal doon, para hindi mo maharangan ang mabilis na trapiko sa mga pangunahing lane.","p":"Tama. Bumagal sa exit lane, hindi sa pangunahing daan."},"ar":{"q":"في Florida، أين يجب أن تخفف السرعة عندما تخرج من الطريق السريع (expressway)؟","o":["في المسار الرئيسي، قبل المخرج","على كتف الطريق بجانب المخرج","في مسار الخروج، بعد أن أترك المسارات الرئيسية","فقط بعد أن أصل إلى آخر المنحدر"],"h1":"إذا خففت السرعة في المسارات الرئيسية، قد تفاجئ السائقين الذين خلفك.","h2":"يجب أن تدخل مسار الخروج أولًا ثم تخفف السرعة فيه، حتى لا تعيق السيارات السريعة في المسارات الرئيسية.","p":"صحيح. خفف السرعة في مسار الخروج، وليس على الطريق الرئيسي."},"ht":{"q":"Nan Florida, ki kote ou ta dwe ralanti lè w ap sòti sou yon otowout?","o":["Nan liy prensipal la, anvan sòti a","Sou bò wout la, bò kote sòti a","Nan liy sòti a, apre ou fin kite liy prensipal yo","Sèlman apre ou rive nan bout ranp lan"],"h1":"Si ou ralanti nan liy prensipal yo, ou ka sezi chofè ki dèyè ou yo.","h2":"Ou ta dwe antre nan liy sòti a anvan, epi ralanti la, pou ou pa bloke machin k ap kouri vit nan liy prensipal yo.","p":"Wi, se sa. Ralanti nan liy sòti a, pa sou wout prensipal la."},"ref":{"doc":"FL","page":64}},{"id":"speed-lanes-025","scope":"US","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"You missed your exit on the expressway. What should you do?","o":["Back up on the shoulder to the exit","Make a U-turn across the median","Keep going to the next exit","Stop and wait for traffic to clear"],"h1":"Backing up or turning around on a fast road is very dangerous.","h2":"If you miss your exit, keep driving to the next exit, because backing up or turning around on an expressway can cause a serious crash.","p":"Right. Missed your exit? Just go on to the next one."},"es":{"q":"Se le pasó la salida en la autopista. ¿Qué debe hacer?","o":["Dar reversa por el acotamiento hasta la salida","Dar vuelta en U por la división central","Seguir hasta la próxima salida","Detenerse y esperar a que pase el tráfico"],"h1":"Dar reversa o dar la vuelta en una vía rápida es muy peligroso.","h2":"Si se le pasa la salida, siga hasta la próxima salida, porque dar reversa o dar la vuelta en una autopista puede causar un choque grave.","p":"Correcto. ¿Se le pasó la salida? Siga hasta la próxima."},"zh":{"q":"你在快速路上错过了出口。你应该怎么做？","o":["在路肩上倒车回到出口","穿过中间隔离带掉头","继续开到下一个出口","停下来，等车流过去"],"h1":"在快速道路上倒车或掉头非常危险。","h2":"如果你错过了出口，就继续开到下一个出口，因为在快速路上倒车或掉头可能会造成严重车祸。","p":"对。错过出口了？就开到下一个出口。"},"vi":{"q":"Bạn đã đi lố lối ra trên đường cao tốc. Bạn nên làm gì?","o":["Lùi xe trên lề về lối ra","Quay đầu chữ U qua dải phân cách","Chạy tiếp đến lối ra kế tiếp","Dừng lại và chờ hết xe"],"h1":"Lùi xe hoặc quay đầu trên đường chạy nhanh là rất nguy hiểm.","h2":"Nếu bạn đi lố lối ra, hãy chạy tiếp đến lối ra kế tiếp, vì lùi xe hoặc quay đầu trên đường cao tốc có thể gây tai nạn nghiêm trọng.","p":"Đúng. Đi lố lối ra? Cứ chạy đến lối ra kế tiếp."},"tl":{"q":"Nalampasan mo ang exit mo sa expressway. Ano ang dapat mong gawin?","o":["Umatras sa shoulder papunta sa exit","Mag-U-turn sa kabila ng median","Magpatuloy hanggang sa susunod na exit","Huminto at hintaying lumuwag ang trapiko"],"h1":"Napakadelikado ang pag-atras o pag-ikot pabalik sa mabilis na daan.","h2":"Kung nalampasan mo ang exit mo, magpatuloy hanggang sa susunod na exit, dahil ang pag-atras o pag-ikot pabalik sa expressway ay maaaring magdulot ng malubhang banggaan.","p":"Tama. Nalampasan ang exit? Magpatuloy lang sa susunod."},"ar":{"q":"فاتك المخرج على الطريق السريع. ماذا يجب أن تفعل؟","o":["أرجع إلى الخلف على كتف الطريق حتى المخرج","أقوم بدوران كامل للخلف (U-turn) عبر الفاصل في الوسط","أستمر حتى المخرج التالي","أتوقف وأنتظر حتى يصبح الطريق فارغًا"],"h1":"الرجوع إلى الخلف أو الدوران على طريق سريع خطير جدًا.","h2":"إذا فاتك المخرج، استمر في القيادة حتى المخرج التالي، لأن الرجوع إلى الخلف أو الدوران على الطريق السريع قد يسبب حادثًا خطيرًا.","p":"صحيح. فاتك المخرج؟ استمر ببساطة إلى المخرج التالي."},"ht":{"q":"Ou rate sòti ou a sou otowout la. Kisa ou ta dwe fè?","o":["Fè bak sou bò wout la jis rive nan sòti a","Fè demi-tou atravè separasyon ki nan mitan an","Kontinye jis rive nan pwochen sòti a","Kanpe epi tann sikilasyon an vin lib"],"h1":"Fè bak oswa fè demi-tou sou yon wout rapid trè danjere.","h2":"Si ou rate sòti ou a, kontinye kondi jis rive nan pwochen sòti a, paske fè bak oswa fè demi-tou sou yon otowout ka lakòz yon gwo aksidan.","p":"Wi, se sa. Ou rate sòti ou a? Kontinye jis nan pwochen an."},"ref":{"doc":"FL","page":64}},{"id":"speed-lanes-026","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, a ramp has a traffic signal (ramp meter) before the expressway. How do you use it?","o":["Wait for green, then one car goes on each green light","All cars in line go on one green light","Ignore it if the expressway looks empty","Go on yellow, stop on green"],"h1":"The signal lets cars onto the expressway a little at a time.","h2":"At a ramp meter, wait for the green light, and then only one car goes for each green unless a sign says otherwise.","p":"Right. At a ramp meter, one car goes on each green light."},"es":{"q":"En Florida, una rampa tiene un semáforo (medidor de rampa) antes de la autopista. ¿Cómo se usa?","o":["Espere la luz verde; pasa un carro con cada luz verde","Todos los carros de la fila pasan con una sola luz verde","Ignórelo si la autopista se ve vacía","Pase con luz amarilla y deténgase con luz verde"],"h1":"El semáforo deja entrar los carros a la autopista poco a poco.","h2":"En un medidor de rampa, espere la luz verde, y luego pasa solo un carro con cada luz verde, a menos que un letrero diga otra cosa.","p":"Correcto. En el medidor de rampa, pasa un carro con cada luz verde."},"zh":{"q":"在 Florida，一条匝道在进入快速路前有一个交通信号灯（匝道信号灯）。你该怎么用它？","o":["等绿灯，每次绿灯走一辆车","排队的所有车在一次绿灯时一起走","如果快速路看起来没车，就不用管它","黄灯走，绿灯停"],"h1":"这个信号灯让车一点一点地进入快速路。","h2":"在匝道信号灯前，要等绿灯，除非有标志另外规定，每次绿灯只走一辆车。","p":"对。在匝道信号灯前，每次绿灯走一辆车。"},"vi":{"q":"Ở Florida, một đường dẫn có đèn giao thông (đèn điều tiết) trước khi vào đường cao tốc. Bạn dùng đèn này thế nào?","o":["Chờ đèn xanh, rồi mỗi lần đèn xanh thì một xe đi","Tất cả các xe đang xếp hàng đi trong một lần đèn xanh","Bỏ qua nếu đường cao tốc trông vắng","Đi khi đèn vàng, dừng khi đèn xanh"],"h1":"Đèn này cho xe vào đường cao tốc từng chút một.","h2":"Tại đèn điều tiết, hãy chờ đèn xanh, và mỗi lần đèn xanh chỉ có một xe đi, trừ khi biển báo nói khác.","p":"Đúng. Tại đèn điều tiết, mỗi lần đèn xanh một xe đi."},"tl":{"q":"Sa Florida, may ilaw trapiko (ramp meter) ang ramp bago ang expressway. Paano mo ito gagamitin?","o":["Hintayin ang berde, at isang kotse ang aandar sa bawat berdeng ilaw","Aandar ang lahat ng kotse sa pila sa isang berdeng ilaw","Huwag pansinin kung mukhang walang laman ang expressway","Umandar sa dilaw, huminto sa berde"],"h1":"Pinapapasok ng ilaw ang mga kotse sa expressway nang paisa-isa.","h2":"Sa ramp meter, hintayin ang berdeng ilaw, at isang kotse lang ang aandar sa bawat berde maliban kung may karatulang nagsasabi ng iba.","p":"Tama. Sa ramp meter, isang kotse ang aandar sa bawat berdeng ilaw."},"ar":{"q":"في Florida، على منحدر الدخول توجد إشارة ضوئية (ramp meter) قبل الطريق السريع. كيف تستعملها؟","o":["أنتظر الضوء الأخضر، ثم تمر سيارة واحدة مع كل ضوء أخضر","كل السيارات في الطابور تمر مع ضوء أخضر واحد","أتجاهلها إذا كان الطريق السريع يبدو فارغًا","أتحرك مع الأصفر، وأتوقف مع الأخضر"],"h1":"هذه الإشارة تُدخل السيارات إلى الطريق السريع قليلًا قليلًا.","h2":"عند إشارة ramp meter، انتظر الضوء الأخضر، ثم تمر سيارة واحدة فقط مع كل ضوء أخضر، إلا إذا قالت علامة غير ذلك.","p":"صحيح. عند إشارة ramp meter، تمر سيارة واحدة مع كل ضوء أخضر."},"ht":{"q":"Nan Florida, yon ranp gen yon limyè (ramp meter) anvan otowout la. Kijan ou sèvi ak li?","o":["Tann limyè vèt la, epi yon sèl machin pase chak fwa limyè a vin vèt","Tout machin ki nan liy lan pase sou yon sèl limyè vèt","Pa okipe l si otowout la sanble vid","Pase sou limyè jòn, kanpe sou limyè vèt"],"h1":"Limyè a kite machin yo antre sou otowout la ti kras pa ti kras.","h2":"Nan yon limyè sou ranp, tann limyè vèt la, epi se yon sèl machin ki pase pou chak limyè vèt, sòf si yon siy di lòt bagay.","p":"Wi, se sa. Nan yon limyè sou ranp, yon sèl machin pase pou chak limyè vèt."},"ref":{"doc":"FL","page":53}},{"id":"speed-lanes-027","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, you are in the left lane of a multi-lane highway. A faster car comes up behind you. What must you do?","o":["Stay in the left lane at the speed limit","Speed up to stay ahead of it","Tap your brakes to slow it down","Move to the right when it is safe and let it pass"],"h1":"On a highway with several lanes, the left lane is mainly for passing.","h2":"Florida law says that if a faster car is coming up behind you in the left lane, you must move right when it is safe and let it pass.","p":"Right. In the left lane, move right for faster traffic behind you."},"es":{"q":"En Florida, usted va por el carril izquierdo de una carretera de varios carriles. Un carro más rápido se acerca por detrás. ¿Qué debe hacer?","o":["Quedarse en el carril izquierdo al límite de velocidad","Acelerar para seguir delante de él","Frenar un poco para que baje la velocidad","Pasarse a la derecha cuando sea seguro y dejarlo pasar"],"h1":"En una carretera de varios carriles, el carril izquierdo es sobre todo para rebasar.","h2":"La ley de Florida dice que si un carro más rápido se acerca por detrás en el carril izquierdo, debe pasarse a la derecha cuando sea seguro y dejarlo pasar.","p":"Correcto. En el carril izquierdo, muévase a la derecha si viene alguien más rápido."},"zh":{"q":"在 Florida，你在多车道公路的左边车道。一辆更快的车从你后面开过来。你必须怎么做？","o":["以限速留在左边车道","加速，保持在它前面","点一下刹车，让它慢下来","在安全时移到右边，让它超过去"],"h1":"在有好几条车道的公路上，左边车道主要是用来超车的。","h2":"Florida 法律规定，如果在左边车道有一辆更快的车从你后面开过来，你必须在安全时移到右边，让它超过去。","p":"对。在左边车道时，要给后面更快的车让到右边。"},"vi":{"q":"Ở Florida, bạn đang ở làn trái của xa lộ nhiều làn. Một xe nhanh hơn đến phía sau bạn. Bạn phải làm gì?","o":["Ở lại làn trái và chạy đúng giới hạn tốc độ","Tăng tốc để chạy trước xe đó","Đạp nhẹ phanh để xe đó chậm lại","Chuyển sang phải khi an toàn và để xe đó vượt"],"h1":"Trên xa lộ có nhiều làn, làn trái chủ yếu dùng để vượt.","h2":"Luật Florida nói nếu có xe nhanh hơn đến phía sau bạn ở làn trái, bạn phải chuyển sang phải khi an toàn và để xe đó vượt.","p":"Đúng. Ở làn trái, hãy chuyển sang phải cho xe nhanh hơn phía sau."},"tl":{"q":"Sa Florida, nasa kaliwang lane ka ng highway na maraming lane. May mas mabilis na kotseng paparating sa likod mo. Ano ang dapat mong gawin?","o":["Manatili sa kaliwang lane sa speed limit","Bumilis para manatiling nauuna rito","Tapik-tapikin ang preno para pabagalin ito","Lumipat pakanan kapag ligtas at hayaan itong lumampas"],"h1":"Sa highway na maraming lane, ang kaliwang lane ay pangunahing para sa paglampas.","h2":"Sinasabi ng batas ng Florida na kung may mas mabilis na kotseng paparating sa likod mo sa kaliwang lane, dapat kang lumipat pakanan kapag ligtas at hayaan itong lumampas.","p":"Tama. Sa kaliwang lane, lumipat pakanan para sa mas mabilis na trapiko sa likod mo."},"ar":{"q":"في Florida، أنت في المسار الأيسر على طريق سريع فيه عدة مسارات. سيارة أسرع تقترب من خلفك. ماذا يجب أن تفعل؟","o":["أبقى في المسار الأيسر بسرعة الحد","أسرع لأبقى أمامها","أضغط على الفرامل قليلًا لأجعلها تبطئ","أنتقل إلى اليمين عندما يكون آمنًا وأتركها تتجاوزني"],"h1":"على طريق سريع فيه عدة مسارات، المسار الأيسر هو أساسًا للتجاوز.","h2":"يقول قانون Florida إنه إذا اقتربت سيارة أسرع من خلفك في المسار الأيسر، يجب أن تنتقل إلى اليمين عندما يكون آمنًا وتتركها تتجاوزك.","p":"صحيح. في المسار الأيسر، انتقل إلى اليمين للسيارات الأسرع التي خلفك."},"ht":{"q":"Nan Florida, ou nan liy gòch yon gran wout ki gen plizyè liy. Yon machin ki pi rapid rive dèyè ou. Kisa ou dwe fè?","o":["Rete nan liy gòch la a limit vitès la","Akselere pou rete devan l","Peze fren an ti kras pou fè l ralanti","Deplase sou bò dwat lè li pa danjere epi kite l pase"],"h1":"Sou yon gran wout ki gen plizyè liy, liy gòch la se sitou pou double.","h2":"Lwa Florida di si yon machin ki pi rapid ap rive dèyè ou nan liy gòch la, ou dwe deplase sou bò dwat lè li pa danjere epi kite l pase.","p":"Wi, se sa. Nan liy gòch la, deplase sou bò dwat pou machin ki pi rapid dèyè ou."},"ref":{"doc":"FL","page":67}},{"id":"speed-lanes-029","scope":"FL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Florida, when must your headlights be on?","o":["Only after midnight","From sunset to sunrise","Only on unlit country roads","Only when another car flashes its lights"],"h1":"Think about the hours when it gets dark outside.","h2":"In Florida your headlights must be on from sunset to sunrise, so you can see and others can see you.","p":"Right. Headlights go on from sunset to sunrise."},"es":{"q":"En Florida, ¿cuándo deben estar encendidas las luces delanteras?","o":["Solo después de la medianoche","Desde la puesta del sol hasta la salida del sol","Solo en caminos rurales sin luz","Solo cuando otro carro le hace cambio de luces"],"h1":"Piense en las horas en que oscurece afuera.","h2":"En Florida sus luces delanteras deben estar encendidas desde la puesta del sol hasta la salida del sol, para que usted vea y lo vean.","p":"Correcto. Las luces van encendidas desde la puesta hasta la salida del sol."},"zh":{"q":"在 Florida，什么时候必须开大灯？","o":["只在半夜以后","从日落到日出","只在没有路灯的乡村道路上","只在别的车对你闪灯时"],"h1":"想一想外面天黑的时间。","h2":"在 Florida，从日落到日出你必须开大灯，这样你能看清路，别人也能看到你。","p":"对。从日落到日出要开大灯。"},"vi":{"q":"Ở Florida, khi nào bạn phải bật đèn pha?","o":["Chỉ sau nửa đêm","Từ lúc mặt trời lặn đến lúc mặt trời mọc","Chỉ trên đường quê không có đèn","Chỉ khi xe khác nháy đèn với bạn"],"h1":"Hãy nghĩ đến những giờ trời tối bên ngoài.","h2":"Ở Florida, đèn pha của bạn phải bật từ lúc mặt trời lặn đến lúc mặt trời mọc, để bạn nhìn thấy và người khác thấy bạn.","p":"Đúng. Bật đèn pha từ lúc mặt trời lặn đến lúc mặt trời mọc."},"tl":{"q":"Sa Florida, kailan dapat nakabukas ang headlights mo?","o":["Pagkatapos lang ng hatinggabi","Mula paglubog ng araw hanggang pagsikat ng araw","Sa madidilim na daan lang sa probinsiya","Kapag nag-flash lang ng ilaw ang ibang kotse"],"h1":"Isipin ang mga oras na dumidilim sa labas.","h2":"Sa Florida, dapat nakabukas ang headlights mo mula paglubog ng araw hanggang pagsikat ng araw, para makakita ka at makita ka ng iba.","p":"Tama. Bukas ang headlights mula paglubog hanggang pagsikat ng araw."},"ar":{"q":"في Florida، متى يجب أن تكون المصابيح الأمامية مضاءة؟","o":["فقط بعد منتصف الليل","من غروب الشمس إلى شروقها","فقط على الطرق الريفية غير المضاءة","فقط عندما تومض سيارة أخرى بأضوائها"],"h1":"فكّر في الساعات التي يصبح فيها الجو مظلمًا في الخارج.","h2":"في Florida يجب أن تكون المصابيح الأمامية مضاءة من غروب الشمس إلى شروقها، حتى ترى أنت ويراك الآخرون.","p":"صحيح. المصابيح الأمامية تُضاء من غروب الشمس إلى شروقها."},"ht":{"q":"Nan Florida, kilè limyè devan machin ou dwe limen?","o":["Sèlman apre minwi","Depi solèy kouche jiskaske solèy leve","Sèlman sou wout andeyò ki pa gen limyè","Sèlman lè yon lòt machin flache limyè l"],"h1":"Panse ak lè li fè nwa deyò.","h2":"Nan Florida limyè devan machin ou dwe limen depi solèy kouche jiskaske solèy leve, pou ou ka wè epi pou lòt moun ka wè ou.","p":"Wi, se sa. Limyè devan yo limen depi solèy kouche jiskaske solèy leve."},"ref":{"doc":"FL","page":73}},{"id":"speed-lanes-030","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, it is daytime but rain, smoke, or fog makes it hard to see. What must you do with your headlights?","o":["Leave them off because it is daytime","Turn on only your parking lights","Turn on your hazard lights and keep driving","Turn them on"],"h1":"Lights help other drivers see you, not only help you see.","h2":"In Florida you must turn on your headlights during rain, smoke, or fog, even in the daytime, so other drivers can see you.","p":"Right. Rain, smoke, or fog means headlights on, even by day."},"es":{"q":"En Florida, es de día pero la lluvia, el humo o la neblina hacen difícil ver. ¿Qué debe hacer con las luces delanteras?","o":["Dejarlas apagadas porque es de día","Encender solo las luces de estacionamiento","Encender las luces intermitentes y seguir manejando","Encenderlas"],"h1":"Las luces ayudan a que otros lo vean, no solo a que usted vea.","h2":"En Florida debe encender las luces delanteras con lluvia, humo o neblina, aunque sea de día, para que los demás conductores lo vean.","p":"Correcto. Con lluvia, humo o neblina, encienda las luces, aunque sea de día."},"zh":{"q":"在 Florida，现在是白天，但下雨、有烟或有雾，看不清楚。你的大灯必须怎么处理？","o":["关着，因为是白天","只开停车灯","开双闪灯，继续开","把大灯打开"],"h1":"车灯不只帮你看清，也帮别的司机看到你。","h2":"在 Florida，下雨、有烟或有雾时，就算是白天，你也必须打开大灯，让别的司机能看到你。","p":"对。下雨、有烟或有雾，就算白天也要开大灯。"},"vi":{"q":"Ở Florida, đang ban ngày nhưng mưa, khói hoặc sương mù làm khó nhìn. Bạn phải làm gì với đèn pha?","o":["Để tắt vì đang là ban ngày","Chỉ bật đèn đậu xe","Bật đèn khẩn cấp và tiếp tục chạy","Bật đèn pha lên"],"h1":"Đèn giúp người lái khác thấy bạn, không chỉ giúp bạn nhìn thấy.","h2":"Ở Florida, bạn phải bật đèn pha khi có mưa, khói hoặc sương mù, kể cả ban ngày, để người lái khác thấy bạn.","p":"Đúng. Mưa, khói hoặc sương mù thì phải bật đèn pha, kể cả ban ngày."},"tl":{"q":"Sa Florida, araw pa pero dahil sa ulan, usok, o fog (hamog) ay mahirap makakita. Ano ang dapat mong gawin sa headlights mo?","o":["Iwanang nakapatay dahil araw pa","Buksan lang ang parking lights mo","Buksan ang hazard lights mo at magpatuloy","Buksan ang mga ito"],"h1":"Tinutulungan ng ilaw ang ibang drayber na makita ka, hindi lang ikaw na makakita.","h2":"Sa Florida, dapat mong buksan ang headlights mo kapag may ulan, usok, o fog, kahit araw pa, para makita ka ng ibang drayber.","p":"Tama. Kapag may ulan, usok, o fog, buksan ang headlights, kahit araw."},"ar":{"q":"في Florida، الوقت نهار، لكن المطر أو الدخان أو الضباب يجعل الرؤية صعبة. ماذا يجب أن تفعل بالمصابيح الأمامية؟","o":["أتركها مطفأة لأن الوقت نهار","أشغّل أضواء الوقوف فقط","أشغّل أضواء الخطر وأستمر في القيادة","أشغّلها"],"h1":"الأضواء تساعد السائقين الآخرين على رؤيتك، وليس فقط تساعدك على الرؤية.","h2":"في Florida يجب أن تشغّل المصابيح الأمامية في المطر أو الدخان أو الضباب، حتى في النهار، حتى يراك السائقون الآخرون.","p":"صحيح. المطر أو الدخان أو الضباب يعني أن تشغّل المصابيح الأمامية، حتى في النهار."},"ht":{"q":"Nan Florida, li fè jou men lapli, lafimen oswa bwouya fè li difisil pou wè. Kisa ou dwe fè ak limyè devan ou yo?","o":["Kite yo etenn paske li fè jou","Limen sèlman ti limyè pakin yo","Limen limyè ijans ou yo (flachè) epi kontinye kondi","Limen yo"],"h1":"Limyè yo ede lòt chofè yo wè ou, se pa sèlman ede ou wè.","h2":"Nan Florida ou dwe limen limyè devan ou yo lè gen lapli, lafimen oswa bwouya, menm lajounen, pou lòt chofè yo ka wè ou.","p":"Wi, se sa. Lapli, lafimen oswa bwouya vle di limen limyè yo, menm lajounen."},"ref":{"doc":"FL","page":71}},{"id":"speed-lanes-031","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, a car is coming toward you at night. How close can it get before you must dim your high beams?","o":["500 feet","100 feet","200 feet","1,000 feet"],"h1":"Bright lights can blind the other driver from far away.","h2":"In Florida you must switch to low beams when an oncoming car is within 500 feet, so you do not blind its driver.","p":"Right. Dim your high beams within 500 feet of an oncoming car."},"es":{"q":"En Florida, de noche viene un carro de frente. ¿A qué distancia debe cambiar a luces bajas?","o":["500 pies","100 pies","200 pies","1,000 pies"],"h1":"Las luces altas pueden encandilar al otro conductor desde lejos.","h2":"En Florida debe cambiar a luces bajas cuando un carro que viene de frente está a 500 pies o menos, para no encandilar al conductor.","p":"Correcto. Cambie a luces bajas a 500 pies de un carro que viene de frente."},"zh":{"q":"在 Florida，晚上有一辆车迎面开过来。它离你多近时，你必须把远光灯换成近光灯？","o":["500 英尺","100 英尺","200 英尺","1,000 英尺"],"h1":"很亮的灯从很远的地方就能晃到对面的司机。","h2":"在 Florida，当对面来车在 500 英尺以内时，你必须换成近光灯，这样才不会晃到对方司机。","p":"对。对面来车在 500 英尺以内时，要关掉远光灯。"},"vi":{"q":"Ở Florida, ban đêm có một xe đang chạy ngược chiều về phía bạn. Xe đó đến gần bao nhiêu thì bạn phải chuyển đèn pha sang đèn cốt (đèn chiếu gần)?","o":["500 feet","100 feet","200 feet","1,000 feet"],"h1":"Đèn sáng có thể làm người lái kia bị chói từ rất xa.","h2":"Ở Florida, bạn phải chuyển sang đèn cốt khi xe ngược chiều ở trong vòng 500 feet, để không làm người lái đó bị chói mắt.","p":"Đúng. Hãy chuyển sang đèn cốt khi xe ngược chiều ở trong vòng 500 feet."},"tl":{"q":"Sa Florida, may kotseng paparating sa harap mo sa gabi. Gaano ito kalapit bago mo dapat ibaba ang high beams mo?","o":["500 feet","100 feet","200 feet","1,000 feet"],"h1":"Kayang silawin ng malakas na ilaw ang ibang drayber mula sa malayo.","h2":"Sa Florida, dapat kang lumipat sa low beams kapag ang paparating na kotse ay nasa loob ng 500 feet, para hindi mo masilaw ang drayber nito.","p":"Tama. Ibaba ang high beams mo sa loob ng 500 feet ng paparating na kotse."},"ar":{"q":"في Florida، سيارة قادمة نحوك في الليل. كم يمكن أن تقترب قبل أن يجب عليك أن تخفض الأضواء العالية؟","o":["500 قدم","100 قدم","200 قدم","1,000 قدم"],"h1":"الأضواء القوية يمكن أن تُعمي السائق الآخر من مسافة بعيدة.","h2":"في Florida يجب أن تنتقل إلى الأضواء المنخفضة عندما تكون السيارة القادمة نحوك على مسافة 500 قدم أو أقل، حتى لا تُعمي سائقها.","p":"صحيح. اخفض الأضواء العالية عندما تكون السيارة القادمة على مسافة 500 قدم أو أقل."},"ht":{"q":"Nan Florida, yon machin ap vin sou ou lannwit. A ki distans li ka rive anvan ou dwe bese gwo limyè ou yo?","o":["500 pye","100 pye","200 pye","1,000 pye"],"h1":"Gwo limyè yo ka avegle lòt chofè a depi byen lwen.","h2":"Nan Florida ou dwe pase sou ti limyè yo lè yon machin k ap vin sou ou rive nan 500 pye, pou ou pa avegle chofè a.","p":"Wi, se sa. Bese gwo limyè ou yo lè yon machin k ap vin sou ou rive nan 500 pye."},"ref":{"doc":"FL","page":73}},{"id":"speed-lanes-032","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, you are driving behind another car at night. How close can you get before you must dim your high beams?","o":["50 feet","100 feet","300 feet","700 feet"],"h1":"Your bright lights shine into the other driver's mirrors.","h2":"In Florida you must use low beams when you are within 300 feet of a car ahead of you, so your lights do not blind the driver through the mirrors.","p":"Right. Dim your lights within 300 feet of a car you are following."},"es":{"q":"En Florida, de noche usted va detrás de otro carro. ¿A qué distancia debe cambiar a luces bajas?","o":["50 pies","100 pies","300 pies","700 pies"],"h1":"Sus luces altas se reflejan en los espejos del otro conductor.","h2":"En Florida debe usar luces bajas cuando está a 300 pies o menos del carro de adelante, para no encandilar al conductor por los espejos.","p":"Correcto. Cambie a luces bajas a 300 pies del carro que va adelante."},"zh":{"q":"在 Florida，你晚上跟在另一辆车后面开。你离它多近时，必须把远光灯换成近光灯？","o":["50 英尺","100 英尺","300 英尺","700 英尺"],"h1":"你的远光灯会照进对方司机的后视镜。","h2":"在 Florida，当你离前面的车在 300 英尺以内时，你必须用近光灯，这样你的灯就不会通过后视镜晃到对方司机。","p":"对。跟车在 300 英尺以内时，要换成近光灯。"},"vi":{"q":"Ở Florida, ban đêm bạn đang chạy sau một xe khác. Bạn đến gần bao nhiêu thì phải chuyển đèn pha sang đèn cốt (đèn chiếu gần)?","o":["50 feet","100 feet","300 feet","700 feet"],"h1":"Đèn sáng của bạn chiếu vào gương của người lái kia.","h2":"Ở Florida, bạn phải dùng đèn cốt khi bạn ở trong vòng 300 feet sau một xe phía trước, để đèn của bạn không làm người lái đó bị chói qua gương.","p":"Đúng. Hãy chuyển sang đèn cốt khi ở trong vòng 300 feet sau xe bạn đang theo."},"tl":{"q":"Sa Florida, nagmamaneho ka sa likod ng ibang kotse sa gabi. Gaano ka kalapit bago mo dapat ibaba ang high beams mo?","o":["50 feet","100 feet","300 feet","700 feet"],"h1":"Tumatama ang malakas mong ilaw sa mga salamin ng ibang drayber.","h2":"Sa Florida, dapat kang gumamit ng low beams kapag nasa loob ka ng 300 feet ng kotse sa unahan mo, para hindi masilaw ang drayber dahil sa mga salamin nito.","p":"Tama. Ibaba ang ilaw mo sa loob ng 300 feet ng kotseng sinusundan mo."},"ar":{"q":"في Florida، تقود خلف سيارة أخرى في الليل. كم يمكن أن تقترب منها قبل أن يجب عليك أن تخفض الأضواء العالية؟","o":["50 قدمًا","100 قدم","300 قدم","700 قدم"],"h1":"أضواؤك القوية تلمع في مرايا السائق الآخر.","h2":"في Florida يجب أن تستعمل الأضواء المنخفضة عندما تكون على مسافة 300 قدم أو أقل من سيارة أمامك، حتى لا تُعمي أضواؤك السائق من خلال المرايا.","p":"صحيح. اخفض أضواءك عندما تكون على مسافة 300 قدم أو أقل من سيارة تسير خلفها."},"ht":{"q":"Nan Florida, w ap kondi dèyè yon lòt machin lannwit. A ki distans ou ka rive anvan ou dwe bese gwo limyè ou yo?","o":["50 pye","100 pye","300 pye","700 pye"],"h1":"Gwo limyè ou yo klere nan retwovizè lòt chofè a.","h2":"Nan Florida ou dwe sèvi ak ti limyè yo lè ou nan 300 pye dèyè yon machin ki devan ou, pou limyè ou yo pa avegle chofè a nan retwovizè l.","p":"Wi, se sa. Bese limyè ou yo lè ou nan 300 pye dèyè yon machin w ap swiv."},"ref":{"doc":"FL","page":73}},{"id":"speed-lanes-033","scope":"US","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"You are driving in thick fog. Which lights should you use?","o":["High beams","Parking lights only","Low beams","No lights"],"h1":"Fog reflects strong light back into your eyes.","h2":"In fog you should use low beams, because high beams bounce off the fog and make it harder to see.","p":"Right. Use low beams in fog."},"es":{"q":"Usted maneja con neblina espesa. ¿Qué luces debe usar?","o":["Luces altas","Solo luces de estacionamiento","Luces bajas","Ninguna luz"],"h1":"La neblina refleja la luz fuerte hacia sus ojos.","h2":"Con neblina debe usar luces bajas, porque las luces altas rebotan en la neblina y hacen más difícil ver.","p":"Correcto. Use luces bajas con neblina."},"zh":{"q":"你在浓雾里开车。你应该用哪种灯？","o":["远光灯","只开停车灯","近光灯","不开灯"],"h1":"雾会把强光反射回你的眼睛。","h2":"在雾里你应该用近光灯，因为远光灯会被雾反射回来，让你更看不清。","p":"对。有雾时用近光灯。"},"vi":{"q":"Bạn đang lái xe trong sương mù dày. Bạn nên dùng đèn nào?","o":["Đèn pha (đèn chiếu xa)","Chỉ đèn đậu xe","Đèn cốt (đèn chiếu gần)","Không bật đèn"],"h1":"Sương mù phản chiếu ánh sáng mạnh ngược lại vào mắt bạn.","h2":"Trong sương mù, bạn nên dùng đèn cốt, vì đèn chiếu xa dội lại từ sương mù và làm bạn khó nhìn hơn.","p":"Đúng. Hãy dùng đèn cốt khi có sương mù."},"tl":{"q":"Nagmamaneho ka sa makapal na fog (hamog). Anong ilaw ang dapat mong gamitin?","o":["High beams","Parking lights lang","Low beams","Walang ilaw"],"h1":"Ibinabalik ng fog ang malakas na ilaw sa mga mata mo.","h2":"Sa fog, dapat kang gumamit ng low beams, dahil tumatalbog ang high beams sa fog at lalo kang nahihirapang makakita.","p":"Tama. Gumamit ng low beams sa fog."},"ar":{"q":"تقود في ضباب كثيف. أي أضواء يجب أن تستعمل؟","o":["الأضواء العالية","أضواء الوقوف فقط","الأضواء المنخفضة","بدون أضواء"],"h1":"الضباب يعكس الضوء القوي إلى عينيك.","h2":"في الضباب يجب أن تستعمل الأضواء المنخفضة، لأن الأضواء العالية ترتد عن الضباب وتجعل الرؤية أصعب.","p":"صحيح. استعمل الأضواء المنخفضة في الضباب."},"ht":{"q":"W ap kondi nan yon bwouya ki epè. Ki limyè ou ta dwe sèvi?","o":["Gwo limyè yo","Ti limyè pakin yo sèlman","Ti limyè yo (limyè ba)","Okenn limyè"],"h1":"Bwouya voye limyè ki fò tounen nan je ou.","h2":"Nan bwouya ou ta dwe sèvi ak ti limyè yo, paske gwo limyè yo frape bwouya a epi yo fè li pi difisil pou wè.","p":"Wi, se sa. Sèvi ak ti limyè yo nan bwouya."},"ref":{"doc":"FL","page":72}},{"id":"speed-lanes-034","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, how close to a fire hydrant may you park?","o":["No closer than 15 feet","No closer than 5 feet","No closer than 10 feet","No closer than 30 feet"],"h1":"Fire trucks need room to connect their hoses.","h2":"In Florida you may not park within 15 feet of a fire hydrant, so firefighters can reach it quickly.","p":"Right. Stay at least 15 feet from a fire hydrant."},"es":{"q":"En Florida, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No a menos de 15 pies","No a menos de 5 pies","No a menos de 10 pies","No a menos de 30 pies"],"h1":"Los bomberos necesitan espacio para conectar las mangueras.","h2":"En Florida no puede estacionarse a menos de 15 pies de un hidrante, para que los bomberos lleguen rápido a él.","p":"Correcto. Estaciónese al menos a 15 pies de un hidrante."},"zh":{"q":"在 Florida，停车时离消防栓最近可以多近？","o":["不能少于 15 英尺","不能少于 5 英尺","不能少于 10 英尺","不能少于 30 英尺"],"h1":"消防车需要空间接上水管。","h2":"在 Florida，你不能停在离消防栓 15 英尺以内的地方，这样消防员才能很快用到它。","p":"对。停车时离消防栓至少 15 英尺。"},"vi":{"q":"Ở Florida, bạn được đậu xe gần trụ nước cứu hỏa đến mức nào?","o":["Không gần hơn 15 feet","Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 30 feet"],"h1":"Xe cứu hỏa cần chỗ để nối vòi nước.","h2":"Ở Florida, bạn không được đậu xe trong vòng 15 feet từ trụ nước cứu hỏa, để lính cứu hỏa có thể đến đó nhanh.","p":"Đúng. Hãy đậu cách trụ nước cứu hỏa ít nhất 15 feet."},"tl":{"q":"Sa Florida, gaano kalapit sa fire hydrant ka puwedeng pumarada?","o":["Hindi lalapit sa 15 feet","Hindi lalapit sa 5 feet","Hindi lalapit sa 10 feet","Hindi lalapit sa 30 feet"],"h1":"Kailangan ng mga trak ng bumbero ng lugar para ikabit ang kanilang hose.","h2":"Sa Florida, hindi ka puwedeng pumarada sa loob ng 15 feet mula sa fire hydrant, para mabilis itong maabot ng mga bumbero.","p":"Tama. Lumayo nang hindi bababa sa 15 feet sa fire hydrant."},"ar":{"q":"في Florida، كم يمكنك أن تقترب من حنفية إطفاء الحريق عندما تركن سيارتك؟","o":["ليس أقرب من 15 قدمًا","ليس أقرب من 5 أقدام","ليس أقرب من 10 أقدام","ليس أقرب من 30 قدمًا"],"h1":"سيارات الإطفاء تحتاج إلى مكان لتوصل خراطيمها.","h2":"في Florida لا يجوز أن تركن على مسافة أقل من 15 قدمًا من حنفية إطفاء الحريق، حتى يصل إليها رجال الإطفاء بسرعة.","p":"صحيح. ابقَ على مسافة 15 قدمًا على الأقل من حنفية إطفاء الحريق."},"ht":{"q":"Nan Florida, a ki distans de yon bouch dlo ponpye (fire hydrant) ou ka pake?","o":["Pa pi pre pase 15 pye","Pa pi pre pase 5 pye","Pa pi pre pase 10 pye","Pa pi pre pase 30 pye"],"h1":"Kamyon ponpye yo bezwen plas pou konekte tiyo yo.","h2":"Nan Florida ou pa ka pake nan mwens pase 15 pye de yon bouch dlo ponpye, pou ponpye yo ka rive ladan l vit.","p":"Wi, se sa. Rete omwen 15 pye lwen yon bouch dlo ponpye."},"ref":{"doc":"FL","page":66}},{"id":"speed-lanes-035","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, how close to a crosswalk at an intersection may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 50 feet","No closer than 20 feet"],"h1":"Drivers must be able to see people who are walking across.","h2":"In Florida you may not park within 20 feet of a crosswalk at an intersection, so drivers can see people crossing.","p":"Right. Park at least 20 feet from a crosswalk at an intersection."},"es":{"q":"En Florida, ¿qué tan cerca de un cruce peatonal en una intersección puede estacionarse?","o":["No a menos de 5 pies","No a menos de 10 pies","No a menos de 50 pies","No a menos de 20 pies"],"h1":"Los conductores deben poder ver a las personas que cruzan caminando.","h2":"En Florida no puede estacionarse a menos de 20 pies de un cruce peatonal en una intersección, para que los conductores vean a quienes cruzan.","p":"Correcto. Estaciónese al menos a 20 pies de un cruce peatonal en una intersección."},"zh":{"q":"在 Florida，停车时离路口的人行横道最近可以多近？","o":["不能少于 5 英尺","不能少于 10 英尺","不能少于 50 英尺","不能少于 20 英尺"],"h1":"司机必须能看到正在过马路的人。","h2":"在 Florida，你不能停在离路口人行横道 20 英尺以内的地方，这样司机才能看到过马路的人。","p":"对。停车时离路口的人行横道至少 20 英尺。"},"vi":{"q":"Ở Florida, bạn được đậu xe gần lối qua đường cho người đi bộ tại giao lộ đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 50 feet","Không gần hơn 20 feet"],"h1":"Người lái phải nhìn thấy được người đang đi bộ qua đường.","h2":"Ở Florida, bạn không được đậu xe trong vòng 20 feet từ lối qua đường tại giao lộ, để người lái có thể thấy người đi bộ qua đường.","p":"Đúng. Hãy đậu cách lối qua đường tại giao lộ ít nhất 20 feet."},"tl":{"q":"Sa Florida, gaano kalapit sa crosswalk sa intersection ka puwedeng pumarada?","o":["Hindi lalapit sa 5 feet","Hindi lalapit sa 10 feet","Hindi lalapit sa 50 feet","Hindi lalapit sa 20 feet"],"h1":"Dapat makita ng mga drayber ang mga taong tumatawid.","h2":"Sa Florida, hindi ka puwedeng pumarada sa loob ng 20 feet mula sa crosswalk sa intersection, para makita ng mga drayber ang mga tumatawid.","p":"Tama. Pumarada nang hindi bababa sa 20 feet ang layo sa crosswalk sa intersection."},"ar":{"q":"في Florida، كم يمكنك أن تقترب من ممر مشاة عند تقاطع عندما تركن سيارتك؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 10 أقدام","ليس أقرب من 50 قدمًا","ليس أقرب من 20 قدمًا"],"h1":"يجب أن يستطيع السائقون رؤية الناس الذين يعبرون.","h2":"في Florida لا يجوز أن تركن على مسافة أقل من 20 قدمًا من ممر مشاة عند تقاطع، حتى يرى السائقون الناس الذين يعبرون.","p":"صحيح. اركن على مسافة 20 قدمًا على الأقل من ممر المشاة عند التقاطع."},"ht":{"q":"Nan Florida, a ki distans de yon pasaj pyeton nan yon kafou ou ka pake?","o":["Pa pi pre pase 5 pye","Pa pi pre pase 10 pye","Pa pi pre pase 50 pye","Pa pi pre pase 20 pye"],"h1":"Chofè yo dwe ka wè moun k ap travèse yo.","h2":"Nan Florida ou pa ka pake nan mwens pase 20 pye de yon pasaj pyeton nan yon kafou, pou chofè yo ka wè moun k ap travèse yo.","p":"Wi, se sa. Pake omwen 20 pye lwen yon pasaj pyeton nan yon kafou."},"ref":{"doc":"FL","page":66}},{"id":"speed-lanes-036","scope":"FL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Florida, how close to a stop sign may you park?","o":["No closer than 10 feet","No closer than 30 feet","No closer than 15 feet","No closer than 100 feet"],"h1":"A parked car could hide the sign from other drivers.","h2":"In Florida you may not park within 30 feet of a stop sign, so other drivers can see the sign clearly.","p":"Right. Park at least 30 feet from a stop sign."},"es":{"q":"En Florida, ¿qué tan cerca de un letrero de PARE puede estacionarse?","o":["No a menos de 10 pies","No a menos de 30 pies","No a menos de 15 pies","No a menos de 100 pies"],"h1":"Un carro estacionado podría tapar el letrero para otros conductores.","h2":"En Florida no puede estacionarse a menos de 30 pies de un letrero de PARE, para que los demás conductores lo vean bien.","p":"Correcto. Estaciónese al menos a 30 pies de un letrero de PARE."},"zh":{"q":"在 Florida，停车时离停车标志最近可以多近？","o":["不能少于 10 英尺","不能少于 30 英尺","不能少于 15 英尺","不能少于 100 英尺"],"h1":"停着的车可能会挡住标志，让别的司机看不到。","h2":"在 Florida，你不能停在离停车标志 30 英尺以内的地方，这样别的司机才能清楚地看到标志。","p":"对。停车时离停车标志至少 30 英尺。"},"vi":{"q":"Ở Florida, bạn được đậu xe gần biển \"STOP\" đến mức nào?","o":["Không gần hơn 10 feet","Không gần hơn 30 feet","Không gần hơn 15 feet","Không gần hơn 100 feet"],"h1":"Một xe đang đậu có thể che biển báo khỏi tầm nhìn của người lái khác.","h2":"Ở Florida, bạn không được đậu xe trong vòng 30 feet từ biển \"STOP\", để người lái khác thấy rõ biển báo.","p":"Đúng. Hãy đậu cách biển \"STOP\" ít nhất 30 feet."},"tl":{"q":"Sa Florida, gaano kalapit sa stop sign ka puwedeng pumarada?","o":["Hindi lalapit sa 10 feet","Hindi lalapit sa 30 feet","Hindi lalapit sa 15 feet","Hindi lalapit sa 100 feet"],"h1":"Maaaring itago ng nakaparadang kotse ang karatula sa ibang drayber.","h2":"Sa Florida, hindi ka puwedeng pumarada sa loob ng 30 feet mula sa stop sign, para malinaw na makita ng ibang drayber ang karatula.","p":"Tama. Pumarada nang hindi bababa sa 30 feet ang layo sa stop sign."},"ar":{"q":"في Florida، كم يمكنك أن تقترب من علامة \"STOP\" (قف) عندما تركن سيارتك؟","o":["ليس أقرب من 10 أقدام","ليس أقرب من 30 قدمًا","ليس أقرب من 15 قدمًا","ليس أقرب من 100 قدم"],"h1":"السيارة المركونة قد تخفي العلامة عن السائقين الآخرين.","h2":"في Florida لا يجوز أن تركن على مسافة أقل من 30 قدمًا من علامة \"STOP\" (قف)، حتى يرى السائقون الآخرون العلامة بوضوح.","p":"صحيح. اركن على مسافة 30 قدمًا على الأقل من علامة \"STOP\" (قف)."},"ht":{"q":"Nan Florida, a ki distans de yon siy \"STOP\" ou ka pake?","o":["Pa pi pre pase 10 pye","Pa pi pre pase 30 pye","Pa pi pre pase 15 pye","Pa pi pre pase 100 pye"],"h1":"Yon machin ki pake ka kache siy la pou lòt chofè yo pa wè l.","h2":"Nan Florida ou pa ka pake nan mwens pase 30 pye de yon siy \"STOP\", pou lòt chofè yo ka wè siy la byen.","p":"Wi, se sa. Pake omwen 30 pye lwen yon siy \"STOP\"."},"ref":{"doc":"FL","page":66}},{"id":"speed-lanes-037","scope":"FL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Florida, how close to the nearest rail of a railroad crossing may you park?","o":["No closer than 15 feet","No closer than 50 feet","No closer than 25 feet","No closer than 10 feet"],"h1":"Trains are wide and drivers need a clear view of the tracks.","h2":"In Florida you may not park within 50 feet of the nearest rail of a railroad crossing.","p":"Right. Park at least 50 feet from a railroad crossing."},"es":{"q":"En Florida, ¿qué tan cerca del riel más cercano de un cruce de tren puede estacionarse?","o":["No a menos de 15 pies","No a menos de 50 pies","No a menos de 25 pies","No a menos de 10 pies"],"h1":"Los trenes son anchos y los conductores necesitan ver bien las vías.","h2":"En Florida no puede estacionarse a menos de 50 pies del riel más cercano de un cruce de tren.","p":"Correcto. Estaciónese al menos a 50 pies de un cruce de tren."},"zh":{"q":"在 Florida，停车时离铁路道口最近的铁轨最近可以多近？","o":["不能少于 15 英尺","不能少于 50 英尺","不能少于 25 英尺","不能少于 10 英尺"],"h1":"火车很宽，司机需要清楚地看到铁轨。","h2":"在 Florida，你不能停在离铁路道口最近的铁轨 50 英尺以内的地方。","p":"对。停车时离铁路道口至少 50 英尺。"},"vi":{"q":"Ở Florida, bạn được đậu xe gần thanh ray gần nhất của chỗ giao nhau với đường sắt đến mức nào?","o":["Không gần hơn 15 feet","Không gần hơn 50 feet","Không gần hơn 25 feet","Không gần hơn 10 feet"],"h1":"Tàu hỏa rất rộng và người lái cần nhìn rõ đường ray.","h2":"Ở Florida, bạn không được đậu xe trong vòng 50 feet từ thanh ray gần nhất của chỗ giao nhau với đường sắt.","p":"Đúng. Hãy đậu cách chỗ giao nhau với đường sắt ít nhất 50 feet."},"tl":{"q":"Sa Florida, gaano kalapit sa pinakamalapit na riles ng railroad crossing ka puwedeng pumarada?","o":["Hindi lalapit sa 15 feet","Hindi lalapit sa 50 feet","Hindi lalapit sa 25 feet","Hindi lalapit sa 10 feet"],"h1":"Malapad ang mga tren at kailangan ng mga drayber ng malinaw na tanaw sa riles.","h2":"Sa Florida, hindi ka puwedeng pumarada sa loob ng 50 feet mula sa pinakamalapit na riles ng railroad crossing.","p":"Tama. Pumarada nang hindi bababa sa 50 feet ang layo sa railroad crossing."},"ar":{"q":"في Florida، كم يمكنك أن تقترب من أقرب قضيب في تقاطع سكة حديد عندما تركن سيارتك؟","o":["ليس أقرب من 15 قدمًا","ليس أقرب من 50 قدمًا","ليس أقرب من 25 قدمًا","ليس أقرب من 10 أقدام"],"h1":"القطارات عريضة، والسائقون يحتاجون إلى رؤية واضحة للسكة.","h2":"في Florida لا يجوز أن تركن على مسافة أقل من 50 قدمًا من أقرب قضيب في تقاطع سكة حديد.","p":"صحيح. اركن على مسافة 50 قدمًا على الأقل من تقاطع سكة الحديد."},"ht":{"q":"Nan Florida, a ki distans de ray ki pi pre a nan yon kwazman tren ou ka pake?","o":["Pa pi pre pase 15 pye","Pa pi pre pase 50 pye","Pa pi pre pase 25 pye","Pa pi pre pase 10 pye"],"h1":"Tren yo laj epi chofè yo bezwen wè ray yo byen.","h2":"Nan Florida ou pa ka pake nan mwens pase 50 pye de ray ki pi pre a nan yon kwazman tren.","p":"Wi, se sa. Pake omwen 50 pye lwen yon kwazman tren."},"ref":{"doc":"FL","page":66}},{"id":"speed-lanes-038","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, you park facing downhill next to a curb. Which way should you turn your front wheels?","o":["Away from the curb","Straight ahead","It does not matter","Toward the curb"],"h1":"Think about where the car would roll if the brakes failed.","h2":"When you park downhill next to a curb, turn your front wheels toward the curb, so the car rolls into the curb if it moves.","p":"Right. Downhill with a curb, turn your wheels toward the curb."},"es":{"q":"En Florida, se estaciona en bajada junto a la orilla de la acera. ¿Hacia dónde debe girar las ruedas delanteras?","o":["Lejos de la acera","Rectas hacia adelante","No importa","Hacia la acera"],"h1":"Piense hacia dónde rodaría el carro si fallaran los frenos.","h2":"Cuando se estaciona en bajada junto a la acera, gire las ruedas delanteras hacia la acera, para que el carro choque con ella si se mueve.","p":"Correcto. En bajada con acera, gire las ruedas hacia la acera."},"zh":{"q":"在 Florida，你在路缘旁边停车，车头朝下坡。你的前轮应该朝哪边转？","o":["朝远离路缘的方向","朝正前方","朝哪边都没关系","朝路缘的方向"],"h1":"想一想，如果刹车失灵，车会往哪里滑。","h2":"在有路缘的下坡停车时，要把前轮转向路缘，这样车如果滑动，就会顶到路缘上。","p":"对。有路缘的下坡，前轮转向路缘。"},"vi":{"q":"Ở Florida, bạn đậu xe hướng xuống dốc, cạnh lề đường. Bạn nên quay bánh trước về hướng nào?","o":["Ra xa lề đường","Thẳng về phía trước","Hướng nào cũng được","Về phía lề đường"],"h1":"Hãy nghĩ xem xe sẽ lăn về đâu nếu phanh bị hỏng.","h2":"Khi đậu xe xuống dốc cạnh lề đường, bạn quay bánh trước về phía lề, để nếu xe lăn thì sẽ chạm vào lề.","p":"Đúng. Xuống dốc có lề đường, quay bánh xe về phía lề."},"tl":{"q":"Sa Florida, pumarada ka nang nakaharap pababa sa tabi ng curb. Saan mo dapat ipihit ang mga gulong sa harap?","o":["Palayo sa curb","Diretso","Hindi mahalaga","Papunta sa curb"],"h1":"Isipin kung saan gugulong ang kotse kung masira ang preno.","h2":"Kapag pumarada ka nang pababa sa tabi ng curb, ipihit ang mga gulong sa harap papunta sa curb, para gumulong ang kotse papunta sa curb kung gumalaw ito.","p":"Tama. Pababa at may curb, ipihit ang mga gulong papunta sa curb."},"ar":{"q":"في Florida، تركن سيارتك ووجهها إلى أسفل المنحدر بجانب رصيف. إلى أي جهة يجب أن تدير العجلات الأمامية؟","o":["بعيدًا عن الرصيف","إلى الأمام مباشرة","لا يهم","نحو الرصيف"],"h1":"فكّر إلى أين ستتدحرج السيارة إذا تعطلت الفرامل.","h2":"عندما تركن ووجه السيارة إلى أسفل المنحدر بجانب رصيف، أدر العجلات الأمامية نحو الرصيف، حتى تتدحرج السيارة إلى الرصيف إذا تحركت.","p":"صحيح. في النزول وبجانب رصيف، أدر العجلات نحو الرصيف."},"ht":{"q":"Nan Florida, ou pake nan yon desant bò kote yon rebò twotwa, devan machin nan bay sou desant lan. Nan ki direksyon ou ta dwe vire wou devan yo?","o":["Lwen rebò twotwa a","Tou dwat","Sa pa fè okenn diferans","Bò kote rebò twotwa a"],"h1":"Panse ak ki kote machin nan ta woule si fren yo pa mache.","h2":"Lè ou pake nan yon desant bò kote yon rebò twotwa, vire wou devan yo bò kote rebò twotwa a, pou si machin nan bouje, li woule frape rebò twotwa a.","p":"Wi, se sa. Nan desant ak yon rebò twotwa, vire wou yo bò kote rebò twotwa a."},"ref":{"doc":"FL","page":66}},{"id":"speed-lanes-039","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, you park facing uphill next to a curb. Which way should you turn your front wheels?","o":["Away from the curb","Toward the curb","Straight ahead","It does not matter"],"h1":"If the car rolls back, you want the back of the front tire to touch the curb.","h2":"When you park uphill next to a curb, turn your front wheels away from the curb, so the tire catches the curb if the car rolls back.","p":"Right. Uphill with a curb, turn your wheels away from the curb."},"es":{"q":"En Florida, se estaciona en subida junto a la orilla de la acera. ¿Hacia dónde debe girar las ruedas delanteras?","o":["Lejos de la acera","Hacia la acera","Rectas hacia adelante","No importa"],"h1":"Si el carro rueda hacia atrás, quiere que la llanta delantera toque la acera.","h2":"Cuando se estaciona en subida junto a la acera, gire las ruedas delanteras lejos de la acera, para que la llanta se apoye en ella si el carro rueda hacia atrás.","p":"Correcto. En subida con acera, gire las ruedas lejos de la acera."},"zh":{"q":"在 Florida，你在路缘旁边停车，车头朝上坡。你的前轮应该朝哪边转？","o":["朝远离路缘的方向","朝路缘的方向","朝正前方","朝哪边都没关系"],"h1":"如果车往后滑，你希望前轮的后部顶到路缘。","h2":"在有路缘的上坡停车时，要把前轮转离路缘，这样车如果往后滑，轮胎就会被路缘挡住。","p":"对。有路缘的上坡，前轮转离路缘。"},"vi":{"q":"Ở Florida, bạn đậu xe hướng lên dốc, cạnh lề đường. Bạn nên quay bánh trước về hướng nào?","o":["Ra xa lề đường","Về phía lề đường","Thẳng về phía trước","Hướng nào cũng được"],"h1":"Nếu xe lăn về sau, bạn muốn phần sau của bánh trước chạm vào lề.","h2":"Khi đậu xe lên dốc cạnh lề đường, bạn quay bánh trước ra xa lề, để nếu xe lăn về sau thì bánh xe sẽ chặn vào lề.","p":"Đúng. Lên dốc có lề đường, quay bánh xe ra xa lề."},"tl":{"q":"Sa Florida, pumarada ka nang nakaharap paakyat sa tabi ng curb. Saan mo dapat ipihit ang mga gulong sa harap?","o":["Palayo sa curb","Papunta sa curb","Diretso","Hindi mahalaga"],"h1":"Kung umatras ang kotse, gusto mong tumama sa curb ang likod ng gulong sa harap.","h2":"Kapag pumarada ka nang paakyat sa tabi ng curb, ipihit ang mga gulong sa harap palayo sa curb, para sumabit ang gulong sa curb kung umatras ang kotse.","p":"Tama. Paakyat at may curb, ipihit ang mga gulong palayo sa curb."},"ar":{"q":"في Florida، تركن سيارتك ووجهها إلى أعلى المنحدر بجانب رصيف. إلى أي جهة يجب أن تدير العجلات الأمامية؟","o":["بعيدًا عن الرصيف","نحو الرصيف","إلى الأمام مباشرة","لا يهم"],"h1":"إذا رجعت السيارة إلى الخلف، تريد أن يلمس الجزء الخلفي من العجلة الأمامية الرصيف.","h2":"عندما تركن ووجه السيارة إلى أعلى المنحدر بجانب رصيف، أدر العجلات الأمامية بعيدًا عن الرصيف، حتى تمسك العجلة بالرصيف إذا رجعت السيارة إلى الخلف.","p":"صحيح. في الصعود وبجانب رصيف، أدر العجلات بعيدًا عن الرصيف."},"ht":{"q":"Nan Florida, ou pake nan yon monte bò kote yon rebò twotwa, devan machin nan bay sou monte a. Nan ki direksyon ou ta dwe vire wou devan yo?","o":["Lwen rebò twotwa a","Bò kote rebò twotwa a","Tou dwat","Sa pa fè okenn diferans"],"h1":"Si machin nan woule fè bak, ou vle dèyè kawoutchou devan an touche rebò twotwa a.","h2":"Lè ou pake nan yon monte bò kote yon rebò twotwa, vire wou devan yo lwen rebò twotwa a, pou kawoutchou a kenbe sou rebò twotwa a si machin nan woule fè bak.","p":"Wi, se sa. Nan monte ak yon rebò twotwa, vire wou yo lwen rebò twotwa a."},"ref":{"doc":"FL","page":66}},{"id":"speed-lanes-040","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, when you parallel park next to a curb, how close to the curb must your wheels be?","o":["Within 24 inches","Within 36 inches","Within 12 inches","Within 6 feet"],"h1":"Your car should be close enough that it does not stick out into traffic.","h2":"In Florida your wheels must be within 12 inches of the curb when you parallel park, so your car does not block the lane.","p":"Right. Park with your wheels within 12 inches of the curb."},"es":{"q":"En Florida, al estacionarse en paralelo junto a la acera, ¿qué tan cerca de la acera deben quedar las ruedas?","o":["A 24 pulgadas o menos","A 36 pulgadas o menos","A 12 pulgadas o menos","A 6 pies o menos"],"h1":"Su carro debe quedar lo bastante cerca para no salirse hacia el tráfico.","h2":"En Florida las ruedas deben quedar a 12 pulgadas o menos de la acera al estacionarse en paralelo, para que su carro no tape el carril.","p":"Correcto. Estaciónese con las ruedas a 12 pulgadas o menos de la acera."},"zh":{"q":"在 Florida，你在路缘旁边侧方停车时，车轮离路缘必须多近？","o":["24 英寸以内","36 英寸以内","12 英寸以内","6 英尺以内"],"h1":"你的车应该停得够近，不会伸到车流里。","h2":"在 Florida，侧方停车时，你的车轮必须在离路缘 12 英寸以内，这样你的车就不会挡住车道。","p":"对。停车时车轮离路缘在 12 英寸以内。"},"vi":{"q":"Ở Florida, khi đậu xe song song cạnh lề đường, bánh xe của bạn phải cách lề bao nhiêu?","o":["Trong vòng 24 inch","Trong vòng 36 inch","Trong vòng 12 inch","Trong vòng 6 feet"],"h1":"Xe của bạn nên ở đủ gần để không lấn ra dòng xe.","h2":"Ở Florida, khi đậu xe song song, bánh xe của bạn phải cách lề trong vòng 12 inch, để xe không chắn làn đường.","p":"Đúng. Hãy đậu với bánh xe cách lề trong vòng 12 inch."},"tl":{"q":"Sa Florida, kapag nag-parallel park ka sa tabi ng curb, gaano kalapit sa curb dapat ang mga gulong mo?","o":["Sa loob ng 24 inches","Sa loob ng 36 inches","Sa loob ng 12 inches","Sa loob ng 6 feet"],"h1":"Dapat sapat ang lapit ng kotse mo para hindi ito nakausli sa trapiko.","h2":"Sa Florida, dapat nasa loob ng 12 inches mula sa curb ang mga gulong mo kapag nag-parallel park ka, para hindi maharangan ng kotse mo ang lane.","p":"Tama. Pumarada nang nasa loob ng 12 inches mula sa curb ang mga gulong mo."},"ar":{"q":"في Florida، عندما تركن موازيًا للرصيف، كم يجب أن تكون عجلاتك قريبة من الرصيف؟","o":["في حدود 24 بوصة","في حدود 36 بوصة","في حدود 12 بوصة","في حدود 6 أقدام"],"h1":"يجب أن تكون سيارتك قريبة بما يكفي حتى لا تبرز إلى طريق السيارات.","h2":"في Florida يجب أن تكون عجلاتك على مسافة 12 بوصة أو أقل من الرصيف عندما تركن موازيًا له، حتى لا تسد سيارتك المسار.","p":"صحيح. اركن وعجلاتك على مسافة 12 بوصة أو أقل من الرصيف."},"ht":{"q":"Nan Florida, lè ou pake paralèl bò kote yon rebò twotwa, a ki distans wou ou yo dwe ye de rebò twotwa a?","o":["Nan 24 pous","Nan 36 pous","Nan 12 pous","Nan 6 pye"],"h1":"Machin ou dwe pre ase pou li pa depase nan wout kote machin yo ap pase.","h2":"Nan Florida wou ou yo dwe nan 12 pous de rebò twotwa a lè ou pake paralèl, pou machin ou pa bloke liy lan.","p":"Wi, se sa. Pake ak wou ou yo nan 12 pous de rebò twotwa a."},"ref":{"doc":"FL","page":65}},{"id":"speed-lanes-041","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, who may park in a space marked for people with disabilities?","o":["Anyone, if it is only for a few minutes","Anyone, if the lot is full","A driver with a valid disabled parking permit or plate shown","Any driver over 65 years old"],"h1":"These spaces are saved for people who have official proof.","h2":"Only a vehicle showing a valid disabled parking permit or license plate may park in a disabled space, even for a short time.","p":"Right. Disabled spaces are only for vehicles with a valid permit or plate."},"es":{"q":"En Florida, ¿quién puede estacionarse en un espacio para personas con discapacidad?","o":["Cualquiera, si es solo por unos minutos","Cualquiera, si el estacionamiento está lleno","Un conductor que muestre un permiso o placa válida de discapacidad","Cualquier conductor mayor de 65 años"],"h1":"Estos espacios son para personas que tienen un comprobante oficial.","h2":"Solo un vehículo que muestre un permiso o una placa válida de discapacidad puede estacionarse en ese espacio, aunque sea por poco tiempo.","p":"Correcto. Los espacios para personas con discapacidad son solo para vehículos con permiso o placa válida."},"zh":{"q":"在 Florida，谁可以停在残疾人专用车位？","o":["任何人，只要只停几分钟","任何人，只要停车场满了","展示有效残疾人停车证或车牌的司机","任何 65 岁以上的司机"],"h1":"这些车位是留给有正式证明的人的。","h2":"只有展示有效残疾人停车证或车牌的车，才可以停在残疾人车位，就算只停很短的时间也一样。","p":"对。残疾人车位只给有有效停车证或车牌的车用。"},"vi":{"q":"Ở Florida, ai được đậu xe ở chỗ dành cho người khuyết tật?","o":["Bất kỳ ai, nếu chỉ đậu vài phút","Bất kỳ ai, nếu bãi đậu xe đã đầy","Người lái có giấy phép đậu xe hoặc biển số xe người khuyết tật còn hiệu lực đang được trưng ra","Bất kỳ người lái nào trên 65 tuổi"],"h1":"Những chỗ này được giữ cho người có giấy tờ chính thức.","h2":"Chỉ xe có trưng giấy phép đậu xe hoặc biển số xe người khuyết tật còn hiệu lực mới được đậu ở chỗ dành cho người khuyết tật, dù chỉ trong thời gian ngắn.","p":"Đúng. Chỗ đậu cho người khuyết tật chỉ dành cho xe có giấy phép hoặc biển số còn hiệu lực."},"tl":{"q":"Sa Florida, sino ang puwedeng pumarada sa espasyong nakalaan para sa mga taong may kapansanan?","o":["Kahit sino, kung ilang minuto lang","Kahit sino, kung puno na ang paradahan","Drayber na may nakapakitang balidong disabled parking permit o plaka","Kahit sinong drayber na higit 65 taong gulang"],"h1":"Nakalaan ang mga espasyong ito para sa mga taong may opisyal na patunay.","h2":"Sasakyan lang na may nakapakitang balidong disabled parking permit o plaka ang puwedeng pumarada sa espasyo para sa may kapansanan, kahit sandali lang.","p":"Tama. Ang espasyo para sa may kapansanan ay para lang sa mga sasakyang may balidong permit o plaka."},"ar":{"q":"في Florida، من يمكنه أن يركن في مكان مخصص للأشخاص ذوي الإعاقة؟","o":["أي شخص، إذا كان لبضع دقائق فقط","أي شخص، إذا كان الموقف ممتلئًا","سائق يُظهر تصريح وقوف لذوي الإعاقة أو لوحة سارية","أي سائق عمره أكثر من 65 سنة"],"h1":"هذه الأماكن محجوزة للأشخاص الذين معهم إثبات رسمي.","h2":"فقط المركبة التي تُظهر تصريح وقوف لذوي الإعاقة أو لوحة سارية يمكنها أن تركن في مكان ذوي الإعاقة، حتى لوقت قصير.","p":"صحيح. أماكن ذوي الإعاقة فقط للمركبات التي معها تصريح أو لوحة سارية."},"ht":{"q":"Nan Florida, kiyès ki ka pake nan yon plas ki make pou moun andikape?","o":["Nenpòt moun, si se pou kèk minit sèlman","Nenpòt moun, si pakin lan plen","Yon chofè ki montre yon pèmi oswa yon plak pakin pou moun andikape ki valab","Nenpòt chofè ki gen plis pase 65 an"],"h1":"Plas sa yo rezève pou moun ki gen yon prèv ofisyèl.","h2":"Se sèlman yon machin ki montre yon pèmi oswa yon plak pakin pou moun andikape ki valab ki ka pake nan yon plas pou moun andikape, menm pou yon ti tan.","p":"Wi, se sa. Plas pou moun andikape yo se sèlman pou machin ki gen yon pèmi oswa yon plak ki valab."},"ref":{"doc":"FL","page":25}},{"id":"speed-lanes-042","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, can you park on the striped lines next to a disabled parking space?","o":["No, that area must stay clear for wheelchairs and lifts","Yes, if you have a permit","Yes, for up to 15 minutes","Yes, if you stay in the car"],"h1":"Think about what a person in a wheelchair needs to get out of a van.","h2":"You may not park on the striped area next to a disabled space, because it must stay clear for wheelchairs and lifts.","p":"Right. Never park on the striped access aisle."},"es":{"q":"En Florida, ¿puede estacionarse sobre las rayas al lado de un espacio para personas con discapacidad?","o":["No, esa área debe quedar libre para sillas de ruedas y plataformas elevadoras","Sí, si tiene permiso","Sí, hasta 15 minutos","Sí, si se queda dentro del carro"],"h1":"Piense en lo que necesita una persona en silla de ruedas para bajar de una camioneta.","h2":"No puede estacionarse en el área con rayas junto a un espacio para personas con discapacidad, porque debe quedar libre para sillas de ruedas y plataformas elevadoras.","p":"Correcto. Nunca se estacione en el pasillo con rayas."},"zh":{"q":"在 Florida，你可以停在残疾人车位旁边画了斜线的地方吗？","o":["不可以，那个地方必须留空给轮椅和升降设备","可以，只要你有停车证","可以，最多 15 分钟","可以，只要你留在车里"],"h1":"想一想，坐轮椅的人从厢式车里下来需要什么。","h2":"你不能停在残疾人车位旁边画了斜线的地方，因为那里必须留空给轮椅和升降设备。","p":"对。永远不要停在画了斜线的通道上。"},"vi":{"q":"Ở Florida, bạn có được đậu xe trên khu vực kẻ sọc cạnh chỗ đậu cho người khuyết tật không?","o":["Không, khu vực đó phải để trống cho xe lăn và bệ nâng","Có, nếu bạn có giấy phép","Có, tối đa 15 phút","Có, nếu bạn ngồi trong xe"],"h1":"Hãy nghĩ xem một người ngồi xe lăn cần gì để ra khỏi xe van.","h2":"Bạn không được đậu xe trên khu vực kẻ sọc cạnh chỗ đậu cho người khuyết tật, vì khu vực đó phải để trống cho xe lăn và bệ nâng.","p":"Đúng. Không bao giờ đậu xe trên lối đi kẻ sọc dành cho xe lăn."},"tl":{"q":"Sa Florida, puwede ka bang pumarada sa mga guhit-guhit na linya sa tabi ng parking space para sa may kapansanan?","o":["Hindi, dapat manatiling bakante ang lugar na iyon para sa wheelchair at lift","Oo, kung may permit ka","Oo, hanggang 15 minuto","Oo, kung mananatili ka sa loob ng kotse"],"h1":"Isipin ang kailangan ng taong naka-wheelchair para makababa sa van.","h2":"Hindi ka puwedeng pumarada sa lugar na may guhit-guhit sa tabi ng espasyo para sa may kapansanan, dahil dapat itong manatiling bakante para sa wheelchair at lift.","p":"Tama. Huwag kailanman pumarada sa guhit-guhit na daanan (access aisle)."},"ar":{"q":"في Florida، هل يمكنك أن تركن على الخطوط المخططة بجانب مكان وقوف ذوي الإعاقة؟","o":["لا، هذه المنطقة يجب أن تبقى فارغة للكراسي المتحركة والمصاعد","نعم، إذا كان معي تصريح","نعم، حتى 15 دقيقة","نعم، إذا بقيت في السيارة"],"h1":"فكّر ماذا يحتاج شخص على كرسي متحرك لينزل من شاحنة صغيرة.","h2":"لا يجوز أن تركن على المنطقة المخططة بجانب مكان ذوي الإعاقة، لأنها يجب أن تبقى فارغة للكراسي المتحركة والمصاعد.","p":"صحيح. لا تركن أبدًا على الممر المخطط بجانب مكان ذوي الإعاقة."},"ht":{"q":"Nan Florida, èske ou ka pake sou liy bawo ki bò kote yon plas pakin pou moun andikape?","o":["Non, zòn sa a dwe rete lib pou chèz woulant ak asansè machin yo","Wi, si ou gen yon pèmi","Wi, pou jiska 15 minit","Wi, si ou rete nan machin nan"],"h1":"Panse ak sa yon moun nan chèz woulant bezwen pou l sòti nan yon kamyonèt.","h2":"Ou pa ka pake sou zòn ki gen liy bawo bò kote yon plas pou moun andikape, paske li dwe rete lib pou chèz woulant ak asansè machin yo.","p":"Wi, se sa. Pa janm pake sou zòn ki gen liy bawo a."},"ref":{"doc":"FL","page":null}},{"id":"ak-001","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, what is the youngest age to get an instruction permit?","o":["13 years old","14 years old","15 years old","16 years old"],"h1":"It is two years before the age for a provisional license.","h2":"In Alaska you can get an instruction permit when you turn 14, so you have time to practice before you can drive alone.","p":"Right. Alaska gives instruction permits starting at age 14."},"es":{"q":"En Alaska, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["13 años","14 años","15 años","16 años"],"h1":"Es dos años antes de la edad para la licencia provisional.","h2":"En Alaska usted puede obtener el permiso de instrucción al cumplir 14 años, para tener tiempo de practicar antes de manejar solo.","p":"Correcto. Alaska da permisos de instrucción desde los 14 años."},"zh":{"q":"在 Alaska，最小几岁可以拿到学习驾照（instruction permit）？","o":["13 岁","14 岁","15 岁","16 岁"],"h1":"它比过渡驾照的年龄早两年。","h2":"在 Alaska，你满 14 岁就可以拿到学习驾照，这样你在可以单独开车前有时间练习。","p":"对。Alaska 从 14 岁开始发学习驾照。"},"vi":{"q":"Ở Alaska, tuổi nhỏ nhất để được cấp giấy phép tập lái (instruction permit) là bao nhiêu?","o":["13 tuổi","14 tuổi","15 tuổi","16 tuổi"],"h1":"Đó là hai năm trước tuổi được cấp bằng lái tạm thời.","h2":"Ở Alaska, bạn có thể được cấp giấy phép tập lái khi đủ 14 tuổi, để bạn có thời gian tập trước khi được lái xe một mình.","p":"Đúng. Alaska cấp giấy phép tập lái từ 14 tuổi."},"tl":{"q":"Sa Alaska, ano ang pinakabatang edad para makakuha ng instruction permit?","o":["13 taong gulang","14 taong gulang","15 taong gulang","16 taong gulang"],"h1":"Ito ay dalawang taon bago ang edad para sa provisional license.","h2":"Sa Alaska, puwede kang kumuha ng instruction permit pagsapit mo ng 14, para may oras kang magsanay bago ka makapagmaneho nang mag-isa.","p":"Tama. Nagbibigay ang Alaska ng instruction permit simula sa edad na 14."},"ar":{"q":"في Alaska، ما أصغر عمر للحصول على تصريح التعلّم (instruction permit)؟","o":["13 سنة","14 سنة","15 سنة","16 سنة"],"h1":"إنه قبل سن الرخصة المؤقتة بسنتين.","h2":"في Alaska يمكنك الحصول على تصريح التعلّم عندما تبلغ 14 سنة، حتى يكون لديك وقت للتدرّب قبل أن تقود وحدك.","p":"صحيح. تمنح Alaska تصاريح التعلّم ابتداءً من سن 14."},"ref":{"doc":"AK","page":4}},{"id":"ak-002","scope":"AK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alaska, a driver with an instruction permit must have a licensed driver with them. How old must that driver be?","o":["At least 18 years old","At least 25 years old","At least 16 years old","At least 21 years old"],"h1":"The helper must be old enough to drink alcohol legally.","h2":"The person supervising you must be a licensed driver who is at least 21 years old, so that an experienced adult is beside you.","p":"Right. Your supervising driver must be 21 or older."},"es":{"q":"En Alaska, quien tiene permiso de instrucción debe ir con un conductor con licencia. ¿Qué edad debe tener ese conductor?","o":["Por lo menos 18 años","Por lo menos 25 años","Por lo menos 16 años","Por lo menos 21 años"],"h1":"El acompañante debe tener la edad legal para tomar alcohol.","h2":"La persona que lo supervisa debe ser un conductor con licencia de por lo menos 21 años, para que un adulto con experiencia vaya a su lado.","p":"Correcto. Su acompañante debe tener 21 años o más."},"zh":{"q":"在 Alaska，持学习驾照的司机必须有一位有驾照的司机陪同。这位司机必须几岁？","o":["至少 18 岁","至少 25 岁","至少 16 岁","至少 21 岁"],"h1":"陪同的人必须到了可以合法喝酒的年龄。","h2":"监督你的人必须是至少 21 岁、有驾照的司机，这样你旁边就有一位有经验的成年人。","p":"对。监督你的司机必须是 21 岁或以上。"},"vi":{"q":"Ở Alaska, người lái xe có giấy phép tập lái phải có một người có bằng lái đi cùng. Người đó phải bao nhiêu tuổi?","o":["Ít nhất 18 tuổi","Ít nhất 25 tuổi","Ít nhất 16 tuổi","Ít nhất 21 tuổi"],"h1":"Người đi kèm phải đủ tuổi để uống rượu hợp pháp.","h2":"Người giám sát bạn phải là người có bằng lái và ít nhất 21 tuổi, để luôn có một người lớn có kinh nghiệm ngồi bên cạnh bạn.","p":"Đúng. Người giám sát phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Alaska, ang driver na may instruction permit ay dapat may kasamang lisensiyadong driver. Ilang taon dapat ang driver na iyon?","o":["Hindi bababa sa 18 taong gulang","Hindi bababa sa 25 taong gulang","Hindi bababa sa 16 taong gulang","Hindi bababa sa 21 taong gulang"],"h1":"Ang kasama ay dapat nasa edad na puwede nang uminom ng alak ayon sa batas.","h2":"Ang taong nagbabantay sa iyo ay dapat lisensiyadong driver na hindi bababa sa 21 taong gulang, para may karanasang adult sa tabi mo.","p":"Tama. Ang nagbabantay na driver ay dapat 21 taong gulang o higit pa."},"ar":{"q":"في Alaska، يجب أن يكون مع السائق الذي يحمل تصريح التعلّم سائق مرخَّص. كم يجب أن يكون عمر هذا السائق؟","o":["18 سنة على الأقل","25 سنة على الأقل","16 سنة على الأقل","21 سنة على الأقل"],"h1":"يجب أن يكون المرافق في سن يسمح له قانونيًا بشرب الكحول.","h2":"يجب أن يكون الشخص الذي يشرف عليك سائقًا مرخَّصًا عمره 21 سنة على الأقل، حتى يكون بجانبك شخص بالغ لديه خبرة.","p":"صحيح. يجب أن يكون السائق المشرف عمره 21 سنة أو أكثر."},"ref":{"doc":"AK","page":4}},{"id":"ak-003","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, how much driving experience must the supervising driver of a permit holder have?","o":["No experience is required","At least three months","At least one year in that kind of vehicle","At least five years in any vehicle"],"h1":"It is counted in years, and the type of vehicle matters.","h2":"The supervising driver needs at least one year of driving experience in the same kind of vehicle you are driving, so they know how to guide you.","p":"Right. The supervisor needs at least one year of experience in that kind of vehicle."},"es":{"q":"En Alaska, ¿cuánta experiencia debe tener el conductor que supervisa a quien tiene permiso?","o":["No se requiere experiencia","Por lo menos tres meses","Por lo menos un año en ese tipo de vehículo","Por lo menos cinco años en cualquier vehículo"],"h1":"Se cuenta en años, y el tipo de vehículo importa.","h2":"El conductor que lo supervisa necesita por lo menos un año de experiencia manejando el mismo tipo de vehículo que usted maneja, para saber cómo guiarlo.","p":"Correcto. El supervisor necesita por lo menos un año de experiencia en ese tipo de vehículo."},"zh":{"q":"在 Alaska，监督持学习驾照的人开车的司机，必须有多少驾驶经验？","o":["不需要经验","至少三个月","开这种车至少一年","开任何车至少五年"],"h1":"它是按年算的，而且车的种类很重要。","h2":"监督的司机开你正在开的这种车，至少要有一年的驾驶经验，这样才知道怎样指导你。","p":"对。监督的人开这种车至少要有一年经验。"},"vi":{"q":"Ở Alaska, người giám sát người có giấy phép tập lái phải có bao nhiêu kinh nghiệm lái xe?","o":["Không cần kinh nghiệm","Ít nhất ba tháng","Ít nhất một năm với loại xe đó","Ít nhất năm năm với bất kỳ loại xe nào"],"h1":"Kinh nghiệm được tính bằng năm, và loại xe là quan trọng.","h2":"Người giám sát cần ít nhất một năm kinh nghiệm lái cùng loại xe mà bạn đang lái, để họ biết cách hướng dẫn bạn.","p":"Đúng. Người giám sát cần ít nhất một năm kinh nghiệm với loại xe đó."},"tl":{"q":"Sa Alaska, gaano karaming karanasan sa pagmamaneho ang dapat mayroon ang nagbabantay na driver ng may permit?","o":["Walang kailangang karanasan","Hindi bababa sa tatlong buwan","Hindi bababa sa isang taon sa ganoong uri ng sasakyan","Hindi bababa sa limang taon sa kahit anong sasakyan"],"h1":"Binibilang ito sa taon, at mahalaga ang uri ng sasakyan.","h2":"Ang nagbabantay na driver ay kailangang may hindi bababa sa isang taong karanasan sa pagmamaneho ng parehong uri ng sasakyan na minamaneho mo, para alam niya kung paano ka gagabayan.","p":"Tama. Kailangan ng nagbabantay ng hindi bababa sa isang taong karanasan sa ganoong uri ng sasakyan."},"ar":{"q":"في Alaska، كم يجب أن تكون خبرة القيادة لدى السائق المشرف على حامل التصريح؟","o":["لا تُطلب أي خبرة","ثلاثة أشهر على الأقل","سنة واحدة على الأقل في هذا النوع من المركبات","خمس سنوات على الأقل في أي مركبة"],"h1":"تُحسب بالسنوات، ونوع المركبة مهم.","h2":"يحتاج السائق المشرف إلى سنة واحدة على الأقل من الخبرة في قيادة نفس نوع المركبة التي تقودها، حتى يعرف كيف يرشدك.","p":"صحيح. يحتاج المشرف إلى سنة واحدة على الأقل من الخبرة في هذا النوع من المركبات."},"ref":{"doc":"AK","page":4}},{"id":"ak-004","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, where must the supervising driver sit when a permit holder is driving?","o":["In the front passenger seat","In any back seat","Anywhere in the vehicle","In the seat behind the driver"],"h1":"They must be able to reach you and see the road as you do.","h2":"The supervising driver must sit in the front passenger seat the whole time, so they can watch the road and help you right away.","p":"Right. The supervisor always sits in the front passenger seat."},"es":{"q":"En Alaska, ¿dónde debe sentarse el conductor supervisor cuando maneja alguien con permiso?","o":["En el asiento del pasajero de adelante","En cualquier asiento de atrás","En cualquier lugar del vehículo","En el asiento detrás del conductor"],"h1":"Debe poder alcanzarlo a usted y ver el camino como usted.","h2":"El conductor supervisor debe ir todo el tiempo en el asiento del pasajero de adelante, para mirar el camino y ayudarle enseguida.","p":"Correcto. El supervisor siempre va en el asiento del pasajero de adelante."},"zh":{"q":"在 Alaska，持学习驾照的人开车时，监督的司机必须坐在哪里？","o":["前排乘客座位","任何后排座位","车里任何地方","司机后面的座位"],"h1":"他必须能碰到你，并且和你一样看到道路。","h2":"监督的司机必须一直坐在前排乘客座位，这样才能看着道路并马上帮你。","p":"对。监督的人一直坐在前排乘客座位。"},"vi":{"q":"Ở Alaska, khi người có giấy phép tập lái đang lái xe, người giám sát phải ngồi ở đâu?","o":["Ở ghế hành khách phía trước","Ở bất kỳ ghế sau nào","Ở bất kỳ chỗ nào trong xe","Ở ghế ngay sau người lái"],"h1":"Họ phải với tới bạn được và nhìn thấy đường giống như bạn.","h2":"Người giám sát phải ngồi ở ghế hành khách phía trước suốt thời gian lái, để họ nhìn đường và giúp bạn ngay lập tức.","p":"Đúng. Người giám sát luôn ngồi ở ghế hành khách phía trước."},"tl":{"q":"Sa Alaska, saan dapat umupo ang nagbabantay na driver habang nagmamaneho ang may permit?","o":["Sa upuan ng pasahero sa harap","Sa kahit anong upuan sa likod","Kahit saan sa loob ng sasakyan","Sa upuan sa likod ng driver"],"h1":"Dapat maabot ka niya at makita niya ang daan gaya mo.","h2":"Ang nagbabantay na driver ay dapat nakaupo sa upuan ng pasahero sa harap sa buong oras, para mabantayan niya ang daan at matulungan ka agad.","p":"Tama. Laging nakaupo ang nagbabantay sa upuan ng pasahero sa harap."},"ar":{"q":"في Alaska، أين يجب أن يجلس السائق المشرف عندما يقود حامل التصريح؟","o":["في مقعد الراكب الأمامي","في أي مقعد خلفي","في أي مكان داخل المركبة","في المقعد خلف السائق"],"h1":"يجب أن يستطيع الوصول إليك وأن يرى الطريق كما تراه.","h2":"يجب أن يجلس السائق المشرف في مقعد الراكب الأمامي طوال الوقت، حتى يراقب الطريق ويساعدك فورًا.","p":"صحيح. يجلس المشرف دائمًا في مقعد الراكب الأمامي."},"ref":{"doc":"AK","page":4}},{"id":"ak-005","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, how long is an instruction permit valid?","o":["Six months, with no renewal","One year, renewable many times","Two years, renewable one time","Five years, with no renewal"],"h1":"It lasts a little longer than one year, and you get one more chance.","h2":"An Alaska instruction permit is good for two years, and you may renew it one time if you need more practice.","p":"Right. The permit lasts two years and can be renewed once."},"es":{"q":"En Alaska, ¿por cuánto tiempo es válido el permiso de instrucción?","o":["Seis meses, sin renovación","Un año, renovable muchas veces","Dos años, renovable una vez","Cinco años, sin renovación"],"h1":"Dura un poco más de un año, y usted tiene una oportunidad más.","h2":"El permiso de instrucción de Alaska es válido por dos años, y usted puede renovarlo una vez si necesita más práctica.","p":"Correcto. El permiso dura dos años y se puede renovar una vez."},"zh":{"q":"在 Alaska，学习驾照的有效期是多久？","o":["六个月，不能延期","一年，可以延期很多次","两年，可以延期一次","五年，不能延期"],"h1":"它比一年长一些，而且你还有一次机会。","h2":"Alaska 的学习驾照有效期是两年，如果你需要更多练习，可以延期一次。","p":"对。学习驾照有效两年，可以延期一次。"},"vi":{"q":"Ở Alaska, giấy phép tập lái có giá trị trong bao lâu?","o":["Sáu tháng, không được gia hạn","Một năm, được gia hạn nhiều lần","Hai năm, được gia hạn một lần","Năm năm, không được gia hạn"],"h1":"Nó lâu hơn một năm một chút, và bạn có thêm một cơ hội nữa.","h2":"Giấy phép tập lái ở Alaska có giá trị hai năm, và bạn có thể gia hạn một lần nếu cần tập thêm.","p":"Đúng. Giấy phép có giá trị hai năm và được gia hạn một lần."},"tl":{"q":"Sa Alaska, gaano katagal may bisa ang instruction permit?","o":["Anim na buwan, walang renewal","Isang taon, puwedeng i-renew nang maraming beses","Dalawang taon, puwedeng i-renew nang isang beses","Limang taon, walang renewal"],"h1":"Medyo mas mahaba ito kaysa isang taon, at may isa ka pang pagkakataon.","h2":"Ang instruction permit sa Alaska ay may bisa nang dalawang taon, at puwede mo itong i-renew nang isang beses kung kailangan mo pa ng pagsasanay.","p":"Tama. Dalawang taon ang bisa ng permit at puwedeng i-renew nang isang beses."},"ar":{"q":"في Alaska، ما مدة صلاحية تصريح التعلّم؟","o":["ستة أشهر، بدون تجديد","سنة واحدة، يمكن تجديدها مرات كثيرة","سنتان، يمكن تجديدها مرة واحدة","خمس سنوات، بدون تجديد"],"h1":"المدة أطول قليلًا من سنة، ولديك فرصة أخرى واحدة.","h2":"تصريح التعلّم في Alaska صالح لمدة سنتين، ويمكنك تجديده مرة واحدة إذا احتجت إلى مزيد من التدرّب.","p":"صحيح. التصريح صالح لسنتين ويمكن تجديده مرة واحدة."},"ref":{"doc":"AK","page":4}},{"id":"ak-006","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, what must a teen under 18 bring to apply for an instruction permit?","o":["A letter from a teacher","A consent form signed by a parent or guardian","A completed driving school course","Proof of a part-time job"],"h1":"An adult who is responsible for you has to agree.","h2":"A teen under 18 needs a consent form signed by a parent or guardian, because that adult agrees to take responsibility for the new driver.","p":"Right. A parent or guardian must sign a consent form."},"es":{"q":"En Alaska, ¿qué debe llevar un joven menor de 18 años para solicitar el permiso de instrucción?","o":["Una carta de un maestro","Un formulario de consentimiento firmado por su padre, madre o tutor","Un curso de manejo terminado","Prueba de un trabajo de medio tiempo"],"h1":"Un adulto responsable de usted tiene que estar de acuerdo.","h2":"Un joven menor de 18 años necesita un formulario de consentimiento firmado por su padre, madre o tutor, porque ese adulto acepta la responsabilidad del nuevo conductor.","p":"Correcto. Su padre, madre o tutor debe firmar un formulario de consentimiento."},"zh":{"q":"在 Alaska，18 岁以下的青少年申请学习驾照时必须带什么？","o":["老师写的信","父母或监护人签字的同意书","已完成的驾校课程","兼职工作的证明"],"h1":"一位对你负责的成年人必须同意。","h2":"18 岁以下的青少年需要一份父母或监护人签字的同意书，因为这个成年人同意为这位新司机负责。","p":"对。父母或监护人必须签同意书。"},"vi":{"q":"Ở Alaska, thiếu niên dưới 18 tuổi phải mang theo gì khi xin giấy phép tập lái?","o":["Một lá thư của giáo viên","Một mẫu đồng ý có chữ ký của cha mẹ hoặc người giám hộ","Chứng nhận đã học xong trường dạy lái xe","Giấy tờ chứng minh có việc làm bán thời gian"],"h1":"Một người lớn chịu trách nhiệm về bạn phải đồng ý.","h2":"Thiếu niên dưới 18 tuổi cần một mẫu đồng ý có chữ ký của cha mẹ hoặc người giám hộ, vì người lớn đó đồng ý chịu trách nhiệm cho người lái mới.","p":"Đúng. Cha mẹ hoặc người giám hộ phải ký mẫu đồng ý."},"tl":{"q":"Sa Alaska, ano ang dapat dalhin ng kabataang wala pang 18 taong gulang para mag-apply ng instruction permit?","o":["Sulat mula sa guro","Consent form na pinirmahan ng magulang o guardian","Natapos na kurso sa driving school","Patunay ng part-time na trabaho"],"h1":"Kailangang pumayag ang isang adult na responsable sa iyo.","h2":"Ang kabataang wala pang 18 ay kailangan ng consent form na pinirmahan ng magulang o guardian, dahil pumapayag ang adult na iyon na managot para sa bagong driver.","p":"Tama. Dapat pumirma ang magulang o guardian sa consent form."},"ar":{"q":"في Alaska، ماذا يجب أن يُحضر المراهق الذي عمره أقل من 18 سنة ليطلب تصريح التعلّم؟","o":["رسالة من معلّم","نموذج موافقة موقَّع من أحد الوالدين أو الوصي","شهادة إتمام دورة في مدرسة لتعليم القيادة","إثبات عمل بدوام جزئي"],"h1":"يجب أن يوافق شخص بالغ مسؤول عنك.","h2":"يحتاج المراهق الذي عمره أقل من 18 سنة إلى نموذج موافقة موقَّع من أحد الوالدين أو الوصي، لأن هذا الشخص البالغ يوافق على تحمّل المسؤولية عن السائق الجديد.","p":"صحيح. يجب أن يوقّع أحد الوالدين أو الوصي على نموذج الموافقة."},"ref":{"doc":"AK","page":3}},{"id":"ak-007","scope":"AK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alaska, how long must a teen hold an instruction permit before getting a provisional license?","o":["One month","Three months","One year","Six months"],"h1":"It is half of a year.","h2":"A teen must hold the instruction permit for at least six months before getting a provisional license, so there is enough time to practice.","p":"Right. You must hold the permit for at least six months."},"es":{"q":"En Alaska, ¿cuánto tiempo debe tener un joven el permiso de instrucción antes de obtener la licencia provisional?","o":["Un mes","Tres meses","Un año","Seis meses"],"h1":"Es la mitad de un año.","h2":"Un joven debe tener el permiso de instrucción por lo menos seis meses antes de obtener la licencia provisional, para tener tiempo suficiente de practicar.","p":"Correcto. Debe tener el permiso por lo menos seis meses."},"zh":{"q":"在 Alaska，青少年必须持有学习驾照多久，才能拿到过渡驾照？","o":["一个月","三个月","一年","六个月"],"h1":"它是半年。","h2":"青少年必须持有学习驾照至少六个月，才能拿到过渡驾照，这样才有足够的时间练习。","p":"对。你必须持有学习驾照至少六个月。"},"vi":{"q":"Ở Alaska, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi được cấp bằng lái tạm thời (provisional license)?","o":["Một tháng","Ba tháng","Một năm","Sáu tháng"],"h1":"Đó là nửa năm.","h2":"Thiếu niên phải giữ giấy phép tập lái ít nhất sáu tháng trước khi được cấp bằng lái tạm thời, để có đủ thời gian tập lái.","p":"Đúng. Bạn phải giữ giấy phép tập lái ít nhất sáu tháng."},"tl":{"q":"Sa Alaska, gaano katagal dapat hawak ng kabataan ang instruction permit bago makakuha ng provisional license?","o":["Isang buwan","Tatlong buwan","Isang taon","Anim na buwan"],"h1":"Ito ay kalahating taon.","h2":"Dapat hawak ng kabataan ang instruction permit nang hindi bababa sa anim na buwan bago makakuha ng provisional license, para may sapat na oras sa pagsasanay.","p":"Tama. Dapat mong hawak ang permit nang hindi bababa sa anim na buwan."},"ar":{"q":"في Alaska، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل الحصول على الرخصة المؤقتة (provisional license)؟","o":["شهر واحد","ثلاثة أشهر","سنة واحدة","ستة أشهر"],"h1":"إنها نصف سنة.","h2":"يجب أن يحمل المراهق تصريح التعلّم ستة أشهر على الأقل قبل الحصول على الرخصة المؤقتة، حتى يكون لديه وقت كافٍ للتدرّب.","p":"صحيح. يجب أن تحمل التصريح ستة أشهر على الأقل."},"ref":{"doc":"AK","page":4}},{"id":"ak-008","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, how many hours of supervised driving must a teen complete before a provisional license?","o":["40 hours","20 hours","60 hours","100 hours"],"h1":"It is more than 30 and less than 50.","h2":"A teen needs at least 40 hours of supervised driving practice before getting a provisional license, to build real experience on the road.","p":"Right. Alaska asks for at least 40 hours of supervised driving."},"es":{"q":"En Alaska, ¿cuántas horas de manejo supervisado debe completar un joven antes de la licencia provisional?","o":["40 horas","20 horas","60 horas","100 horas"],"h1":"Es más de 30 y menos de 50.","h2":"Un joven necesita por lo menos 40 horas de práctica supervisada antes de obtener la licencia provisional, para ganar experiencia real en el camino.","p":"Correcto. Alaska pide por lo menos 40 horas de manejo supervisado."},"zh":{"q":"在 Alaska，青少年拿过渡驾照前，必须完成多少小时有人监督的驾驶？","o":["40 小时","20 小时","60 小时","100 小时"],"h1":"它比 30 多，比 50 少。","h2":"青少年拿过渡驾照前，至少需要 40 小时有人监督的驾驶练习，这样才能在路上积累真正的经验。","p":"对。Alaska 要求至少 40 小时有人监督的驾驶。"},"vi":{"q":"Ở Alaska, thiếu niên phải lái xe có giám sát bao nhiêu giờ trước khi được cấp bằng lái tạm thời?","o":["40 giờ","20 giờ","60 giờ","100 giờ"],"h1":"Nhiều hơn 30 và ít hơn 50.","h2":"Thiếu niên cần ít nhất 40 giờ tập lái có giám sát trước khi được cấp bằng lái tạm thời, để có kinh nghiệm thật trên đường.","p":"Đúng. Alaska yêu cầu ít nhất 40 giờ lái xe có giám sát."},"tl":{"q":"Sa Alaska, ilang oras ng pagmamaneho na may nagbabantay ang dapat matapos ng kabataan bago ang provisional license?","o":["40 oras","20 oras","60 oras","100 oras"],"h1":"Ito ay higit sa 30 at mas kaunti sa 50.","h2":"Kailangan ng kabataan ng hindi bababa sa 40 oras ng pagsasanay sa pagmamaneho na may nagbabantay bago makakuha ng provisional license, para magkaroon ng tunay na karanasan sa daan.","p":"Tama. Humihingi ang Alaska ng hindi bababa sa 40 oras ng pagmamaneho na may nagbabantay."},"ar":{"q":"في Alaska، كم ساعة من القيادة تحت الإشراف يجب أن يُكملها المراهق قبل الرخصة المؤقتة؟","o":["40 ساعة","20 ساعة","60 ساعة","100 ساعة"],"h1":"العدد أكثر من 30 وأقل من 50.","h2":"يحتاج المراهق إلى 40 ساعة على الأقل من التدرّب على القيادة تحت الإشراف قبل الحصول على الرخصة المؤقتة، ليكتسب خبرة حقيقية على الطريق.","p":"صحيح. تطلب Alaska 40 ساعة على الأقل من القيادة تحت الإشراف."},"ref":{"doc":"AK","page":5}},{"id":"ak-009","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, how many of the required supervised hours must be in challenging conditions, such as at night or in bad weather?","o":["At least 5 hours","At least 15 hours","At least 10 hours","At least 20 hours"],"h1":"It is one quarter of the total hours.","h2":"At least 10 of the supervised hours must be in harder conditions, such as darkness or bad weather, so a new driver has practiced them with help.","p":"Right. At least 10 hours must be at night or in bad weather."},"es":{"q":"En Alaska, ¿cuántas de las horas supervisadas deben ser en condiciones difíciles, como de noche o con mal tiempo?","o":["Por lo menos 5 horas","Por lo menos 15 horas","Por lo menos 10 horas","Por lo menos 20 horas"],"h1":"Es la cuarta parte del total de horas.","h2":"Por lo menos 10 de las horas supervisadas deben ser en condiciones más difíciles, como de noche o con mal tiempo, para que el conductor nuevo las practique con ayuda.","p":"Correcto. Por lo menos 10 horas deben ser de noche o con mal tiempo."},"zh":{"q":"在 Alaska，规定的监督驾驶时间里，有多少小时必须在困难的条件下，比如晚上或天气不好时？","o":["至少 5 小时","至少 15 小时","至少 10 小时","至少 20 小时"],"h1":"它是全部时间的四分之一。","h2":"监督驾驶时间里至少 10 小时必须在比较难的条件下，比如天黑或天气不好，这样新司机已经在有人帮助时练习过。","p":"对。至少 10 小时必须在晚上或天气不好时。"},"vi":{"q":"Ở Alaska, trong số giờ lái có giám sát bắt buộc, bao nhiêu giờ phải lái trong điều kiện khó, như ban đêm hoặc thời tiết xấu?","o":["Ít nhất 5 giờ","Ít nhất 15 giờ","Ít nhất 10 giờ","Ít nhất 20 giờ"],"h1":"Đó là một phần tư tổng số giờ.","h2":"Ít nhất 10 giờ lái có giám sát phải là trong điều kiện khó hơn, như trời tối hoặc thời tiết xấu, để người lái mới đã tập những điều kiện này khi có người giúp.","p":"Đúng. Ít nhất 10 giờ phải lái vào ban đêm hoặc khi thời tiết xấu."},"tl":{"q":"Sa Alaska, ilan sa mga kailangang oras na may nagbabantay ang dapat sa mahirap na kondisyon, gaya ng gabi o masamang panahon?","o":["Hindi bababa sa 5 oras","Hindi bababa sa 15 oras","Hindi bababa sa 10 oras","Hindi bababa sa 20 oras"],"h1":"Ito ay isang-kapat ng kabuuang oras.","h2":"Hindi bababa sa 10 sa mga oras na may nagbabantay ang dapat sa mas mahirap na kondisyon, gaya ng dilim o masamang panahon, para nasanay na ang bagong driver dito nang may tumutulong.","p":"Tama. Hindi bababa sa 10 oras ang dapat sa gabi o sa masamang panahon."},"ar":{"q":"في Alaska، كم ساعة من ساعات القيادة تحت الإشراف المطلوبة يجب أن تكون في ظروف صعبة، مثل الليل أو الطقس السيئ؟","o":["5 ساعات على الأقل","15 ساعة على الأقل","10 ساعات على الأقل","20 ساعة على الأقل"],"h1":"إنها ربع مجموع الساعات.","h2":"يجب أن تكون 10 ساعات على الأقل من ساعات الإشراف في ظروف أصعب، مثل الظلام أو الطقس السيئ، حتى يكون السائق الجديد قد تدرّب عليها مع من يساعده.","p":"صحيح. يجب أن تكون 10 ساعات على الأقل في الليل أو في الطقس السيئ."},"ref":{"doc":"AK","page":5}},{"id":"ak-010","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, what is the youngest age to get a provisional license?","o":["15 years old","16 years old","17 years old","18 years old"],"h1":"It is two years after the youngest permit age.","h2":"You can get a provisional license at 16, after you have held your permit long enough and finished your practice hours.","p":"Right. The provisional license starts at age 16."},"es":{"q":"En Alaska, ¿cuál es la edad mínima para obtener una licencia provisional?","o":["15 años","16 años","17 años","18 años"],"h1":"Es dos años después de la edad mínima del permiso.","h2":"Usted puede obtener la licencia provisional a los 16 años, después de tener el permiso el tiempo necesario y terminar sus horas de práctica.","p":"Correcto. La licencia provisional empieza a los 16 años."},"zh":{"q":"在 Alaska，最小几岁可以拿到过渡驾照？","o":["15 岁","16 岁","17 岁","18 岁"],"h1":"它比拿学习驾照的最小年龄晚两年。","h2":"你在持有学习驾照够久、并完成练习时间以后，16 岁就可以拿到过渡驾照。","p":"对。过渡驾照从 16 岁开始。"},"vi":{"q":"Ở Alaska, tuổi nhỏ nhất để được cấp bằng lái tạm thời là bao nhiêu?","o":["15 tuổi","16 tuổi","17 tuổi","18 tuổi"],"h1":"Đó là hai năm sau tuổi nhỏ nhất để có giấy phép tập lái.","h2":"Bạn có thể được cấp bằng lái tạm thời khi 16 tuổi, sau khi đã giữ giấy phép tập lái đủ lâu và lái đủ số giờ tập.","p":"Đúng. Bằng lái tạm thời bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Alaska, ano ang pinakabatang edad para makakuha ng provisional license?","o":["15 taong gulang","16 taong gulang","17 taong gulang","18 taong gulang"],"h1":"Ito ay dalawang taon pagkatapos ng pinakabatang edad para sa permit.","h2":"Puwede kang kumuha ng provisional license sa edad na 16, pagkatapos mong mahawakan ang permit nang sapat na tagal at matapos ang iyong mga oras ng pagsasanay.","p":"Tama. Nagsisimula ang provisional license sa edad na 16."},"ar":{"q":"في Alaska، ما أصغر عمر للحصول على الرخصة المؤقتة؟","o":["15 سنة","16 سنة","17 سنة","18 سنة"],"h1":"إنه بعد أصغر عمر للتصريح بسنتين.","h2":"يمكنك الحصول على الرخصة المؤقتة في سن 16، بعد أن تحمل التصريح مدة كافية وتُكمل ساعات التدرّب.","p":"صحيح. تبدأ الرخصة المؤقتة في سن 16."},"ref":{"doc":"AK","page":5}},{"id":"ak-011","scope":"AK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alaska, during which hours may a provisional driver not drive alone, unless driving for work?","o":["10 p.m. to 5 a.m.","11 p.m. to 6 a.m.","Midnight to 6 a.m.","1 a.m. to 5 a.m."],"h1":"The limit starts after midnight and ends before sunrise in most seasons.","h2":"A provisional driver may not drive between 1 a.m. and 5 a.m. unless a licensed driver age 21 or older is in the car or the trip is for work.","p":"Right. Provisional drivers stay off the road from 1 a.m. to 5 a.m."},"es":{"q":"En Alaska, ¿en qué horario no puede manejar un conductor con licencia provisional, salvo por trabajo?","o":["De 10 p.m. a 5 a.m.","De 11 p.m. a 6 a.m.","De medianoche a 6 a.m.","De 1 a.m. a 5 a.m."],"h1":"El límite empieza después de la medianoche y termina antes del amanecer en casi todas las estaciones.","h2":"Un conductor con licencia provisional no puede manejar entre la 1 a.m. y las 5 a.m., salvo que vaya con un conductor con licencia de 21 años o más, o que el viaje sea por trabajo.","p":"Correcto. Los conductores provisionales no manejan de 1 a.m. a 5 a.m."},"zh":{"q":"在 Alaska，持过渡驾照的司机在哪段时间不能单独开车（为工作开车除外）？","o":["晚上 10 点到早上 5 点","晚上 11 点到早上 6 点","午夜到早上 6 点","凌晨 1 点到早上 5 点"],"h1":"这个限制在午夜以后开始，在大多数季节天亮以前结束。","h2":"持过渡驾照的司机在凌晨 1 点到早上 5 点之间不能开车，除非车里有一位 21 岁或以上、有驾照的司机，或者是为工作开车。","p":"对。持过渡驾照的司机凌晨 1 点到早上 5 点不上路。"},"vi":{"q":"Ở Alaska, người có bằng lái tạm thời không được lái xe một mình trong khoảng giờ nào, trừ khi lái xe vì công việc?","o":["10 giờ tối đến 5 giờ sáng","11 giờ tối đến 6 giờ sáng","Nửa đêm đến 6 giờ sáng","1 giờ sáng đến 5 giờ sáng"],"h1":"Giới hạn bắt đầu sau nửa đêm và kết thúc trước khi mặt trời mọc ở hầu hết các mùa.","h2":"Người có bằng lái tạm thời không được lái xe từ 1 giờ sáng đến 5 giờ sáng, trừ khi có người có bằng lái từ 21 tuổi trở lên trong xe hoặc chuyến đi là vì công việc.","p":"Đúng. Người có bằng lái tạm thời không lái xe từ 1 giờ sáng đến 5 giờ sáng."},"tl":{"q":"Sa Alaska, sa anong mga oras hindi puwedeng magmaneho nang mag-isa ang provisional driver, maliban kung para sa trabaho?","o":["10 p.m. hanggang 5 a.m.","11 p.m. hanggang 6 a.m.","Hatinggabi hanggang 6 a.m.","1 a.m. hanggang 5 a.m."],"h1":"Nagsisimula ang limitasyon pagkalipas ng hatinggabi at natatapos bago sumikat ang araw sa karamihan ng panahon.","h2":"Ang provisional driver ay hindi puwedeng magmaneho mula 1 a.m. hanggang 5 a.m. maliban kung may lisensiyadong driver na 21 taong gulang o higit pa sa sasakyan o ang biyahe ay para sa trabaho.","p":"Tama. Hindi nagmamaneho ang provisional driver mula 1 a.m. hanggang 5 a.m."},"ar":{"q":"في Alaska، في أي ساعات لا يجوز لصاحب الرخصة المؤقتة أن يقود وحده، إلا إذا كانت القيادة من أجل العمل؟","o":["من 10 مساءً إلى 5 صباحًا","من 11 مساءً إلى 6 صباحًا","من منتصف الليل إلى 6 صباحًا","من 1 صباحًا إلى 5 صباحًا"],"h1":"يبدأ المنع بعد منتصف الليل وينتهي قبل شروق الشمس في معظم الفصول.","h2":"لا يجوز لصاحب الرخصة المؤقتة أن يقود بين 1 صباحًا و5 صباحًا، إلا إذا كان في السيارة سائق مرخَّص عمره 21 سنة أو أكثر أو كانت الرحلة من أجل العمل.","p":"صحيح. لا يقود أصحاب الرخص المؤقتة من 1 صباحًا إلى 5 صباحًا."},"ref":{"doc":"AK","page":6}},{"id":"ak-012","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, which trip is allowed for a provisional driver during the restricted night hours, even with no adult in the car?","o":["Driving to or from a job","Driving to a friend’s house","Driving to a late movie","Driving to a store"],"h1":"The exception is about earning a living.","h2":"A provisional driver may drive during the restricted hours when going to or from work, or as part of a job, using the most direct route.","p":"Right. Driving to or from work is the exception."},"es":{"q":"En Alaska, ¿qué viaje se permite a un conductor provisional en las horas restringidas de la noche, aun sin un adulto en el carro?","o":["Ir o volver del trabajo","Ir a la casa de un amigo","Ir a una película tarde","Ir a una tienda"],"h1":"La excepción tiene que ver con ganarse la vida.","h2":"Un conductor provisional puede manejar en las horas restringidas cuando va o vuelve del trabajo, o como parte de su trabajo, por la ruta más directa.","p":"Correcto. Ir o volver del trabajo es la excepción."},"zh":{"q":"在 Alaska，在限制的夜间时段，即使车里没有成年人，持过渡驾照的司机可以开车去哪里？","o":["上班或下班","去朋友家","去看晚场电影","去商店"],"h1":"这个例外和赚钱养活自己有关。","h2":"持过渡驾照的司机在限制时段内，如果是上班、下班或为工作开车，可以走最直接的路线开车。","p":"对。上班或下班开车是例外。"},"vi":{"q":"Ở Alaska, chuyến đi nào được phép cho người có bằng lái tạm thời trong giờ ban đêm bị giới hạn, kể cả khi không có người lớn trong xe?","o":["Lái xe đi làm hoặc từ chỗ làm về","Lái xe đến nhà bạn","Lái xe đi xem phim khuya","Lái xe đến cửa hàng"],"h1":"Ngoại lệ này liên quan đến việc kiếm sống.","h2":"Người có bằng lái tạm thời được lái xe trong giờ bị giới hạn khi đi làm hoặc từ chỗ làm về, hoặc khi lái xe vì công việc, theo đường đi thẳng nhất.","p":"Đúng. Lái xe đi làm hoặc từ chỗ làm về là ngoại lệ."},"tl":{"q":"Sa Alaska, aling biyahe ang pinapayagan sa provisional driver sa mga oras ng gabing may limitasyon, kahit walang adult sa sasakyan?","o":["Pagmamaneho papunta o pauwi mula sa trabaho","Pagmamaneho papunta sa bahay ng kaibigan","Pagmamaneho papunta sa sine sa gabi","Pagmamaneho papunta sa tindahan"],"h1":"Ang eksepsiyon ay tungkol sa paghahanapbuhay.","h2":"Puwedeng magmaneho ang provisional driver sa mga oras na may limitasyon kapag papunta o pauwi mula sa trabaho, o bilang bahagi ng trabaho, gamit ang pinakadiretsong ruta.","p":"Tama. Ang pagmamaneho papunta o pauwi mula sa trabaho ang eksepsiyon."},"ar":{"q":"في Alaska، أي رحلة مسموحة لصاحب الرخصة المؤقتة في ساعات الليل الممنوعة، حتى بدون شخص بالغ في السيارة؟","o":["القيادة إلى العمل أو منه","القيادة إلى بيت صديق","القيادة إلى فيلم في وقت متأخر","القيادة إلى متجر"],"h1":"الاستثناء يتعلّق بكسب الرزق.","h2":"يجوز لصاحب الرخصة المؤقتة أن يقود في الساعات الممنوعة عندما يذهب إلى العمل أو يعود منه، أو كجزء من عمله، باستخدام أقصر طريق مباشر.","p":"صحيح. القيادة إلى العمل أو منه هي الاستثناء."},"ref":{"doc":"AK","page":6}},{"id":"ak-013","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, which passengers may a provisional driver carry with no adult supervisor in the car?","o":["Any friends under 18","Up to three passengers of any age","Passengers 21 or older, and siblings","Only passengers under 16"],"h1":"Young passengers are limited, but family has an exception.","h2":"Unless a parent, guardian, or another person age 21 or older is riding along, a provisional driver may not carry passengers under 21, except brothers and sisters.","p":"Right. Passengers under 21 are not allowed, except siblings."},"es":{"q":"En Alaska, ¿a qué pasajeros puede llevar un conductor provisional sin un adulto supervisor en el carro?","o":["A cualquier amigo menor de 18","Hasta tres pasajeros de cualquier edad","Pasajeros de 21 años o más, y hermanos","Solo pasajeros menores de 16"],"h1":"Los pasajeros jóvenes están limitados, pero la familia tiene una excepción.","h2":"A menos que vaya con usted su padre, madre, tutor u otra persona de 21 años o más, un conductor provisional no puede llevar pasajeros menores de 21 años, excepto a sus hermanos.","p":"Correcto. No se permiten pasajeros menores de 21, excepto hermanos."},"zh":{"q":"在 Alaska，车里没有成年人监督时，持过渡驾照的司机可以载哪些乘客？","o":["任何 18 岁以下的朋友","最多三位任何年龄的乘客","21 岁或以上的乘客，以及兄弟姐妹","只有 16 岁以下的乘客"],"h1":"年轻乘客有限制，但家人有例外。","h2":"除非有父母、监护人或另一位 21 岁或以上的人同车，持过渡驾照的司机不能载 21 岁以下的乘客，兄弟姐妹除外。","p":"对。不能载 21 岁以下的乘客，兄弟姐妹除外。"},"vi":{"q":"Ở Alaska, người có bằng lái tạm thời được chở những hành khách nào khi không có người lớn giám sát trong xe?","o":["Bất kỳ người bạn nào dưới 18 tuổi","Tối đa ba hành khách ở mọi độ tuổi","Hành khách từ 21 tuổi trở lên, và anh chị em ruột","Chỉ hành khách dưới 16 tuổi"],"h1":"Hành khách trẻ bị giới hạn, nhưng gia đình có ngoại lệ.","h2":"Trừ khi có cha mẹ, người giám hộ hoặc một người khác từ 21 tuổi trở lên đi cùng, người có bằng lái tạm thời không được chở hành khách dưới 21 tuổi, trừ anh chị em ruột.","p":"Đúng. Không được chở hành khách dưới 21 tuổi, trừ anh chị em ruột."},"tl":{"q":"Sa Alaska, aling mga pasahero ang puwedeng isakay ng provisional driver kung walang nagbabantay na adult sa sasakyan?","o":["Kahit sinong kaibigan na wala pang 18","Hanggang tatlong pasahero sa kahit anong edad","Mga pasaherong 21 taong gulang o higit pa, at mga kapatid","Mga pasaherong wala pang 16 lamang"],"h1":"Limitado ang mga batang pasahero, pero may eksepsiyon para sa pamilya.","h2":"Maliban kung may kasamang magulang, guardian, o ibang taong 21 taong gulang o higit pa, hindi puwedeng magsakay ang provisional driver ng mga pasaherong wala pang 21, maliban sa mga kapatid.","p":"Tama. Hindi pinapayagan ang mga pasaherong wala pang 21, maliban sa mga kapatid."},"ar":{"q":"في Alaska، أي ركاب يجوز لصاحب الرخصة المؤقتة أن ينقلهم بدون مشرف بالغ في السيارة؟","o":["أي أصدقاء عمرهم أقل من 18","حتى ثلاثة ركاب من أي عمر","ركاب عمرهم 21 أو أكثر، والإخوة والأخوات","ركاب عمرهم أقل من 16 فقط"],"h1":"الركاب الصغار محدودون، لكن للعائلة استثناء.","h2":"إلا إذا كان معه أحد الوالدين أو الوصي أو شخص آخر عمره 21 سنة أو أكثر، لا يجوز لصاحب الرخصة المؤقتة أن ينقل ركابًا عمرهم أقل من 21، ما عدا الإخوة والأخوات.","p":"صحيح. لا يُسمح بركاب عمرهم أقل من 21، ما عدا الإخوة والأخوات."},"ref":{"doc":"AK","page":6}},{"id":"ak-014","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, when do the provisional license limits end?","o":["After one month with no crash","At age 18, or after six months with no violations","Only at age 21","After the driver passes a second road test"],"h1":"There are two ways: an age and a clean record.","h2":"The provisional limits end when you turn 18, or after six months on the provisional license with no violations, when you ask the DMV to remove them.","p":"Right. The limits end at 18 or after six clean months."},"es":{"q":"En Alaska, ¿cuándo terminan las restricciones de la licencia provisional?","o":["Después de un mes sin choques","A los 18 años, o después de seis meses sin infracciones","Solo a los 21 años","Después de pasar un segundo examen de manejo"],"h1":"Hay dos caminos: una edad y un récord limpio.","h2":"Las restricciones provisionales terminan cuando usted cumple 18 años, o después de seis meses con la licencia provisional sin infracciones, cuando usted pide al DMV que las quite.","p":"Correcto. Terminan a los 18 o después de seis meses sin infracciones."},"zh":{"q":"在 Alaska，过渡驾照的限制什么时候结束？","o":["一个月没有车祸以后","满 18 岁，或者六个月没有违规以后","只有到 21 岁","司机通过第二次路考以后"],"h1":"有两种方法：一个年龄，和一个干净的记录。","h2":"过渡驾照的限制在你满 18 岁时结束；或者持过渡驾照六个月没有违规以后，你向 DMV 申请取消限制。","p":"对。限制在 18 岁时或六个月没有违规以后结束。"},"vi":{"q":"Ở Alaska, khi nào các giới hạn của bằng lái tạm thời kết thúc?","o":["Sau một tháng không có tai nạn","Khi 18 tuổi, hoặc sau sáu tháng không vi phạm","Chỉ khi 21 tuổi","Sau khi người lái thi đậu bài thi lái xe lần thứ hai"],"h1":"Có hai cách: một độ tuổi và một hồ sơ sạch.","h2":"Các giới hạn của bằng lái tạm thời kết thúc khi bạn 18 tuổi, hoặc sau sáu tháng có bằng lái tạm thời mà không vi phạm, khi bạn xin DMV bỏ các giới hạn đó.","p":"Đúng. Các giới hạn kết thúc khi 18 tuổi hoặc sau sáu tháng không vi phạm."},"tl":{"q":"Sa Alaska, kailan natatapos ang mga limitasyon ng provisional license?","o":["Pagkalipas ng isang buwan na walang aksidente","Sa edad na 18, o pagkalipas ng anim na buwan na walang paglabag","Sa edad na 21 lamang","Pagkatapos makapasa ang driver sa ikalawang road test"],"h1":"May dalawang paraan: isang edad at isang malinis na rekord.","h2":"Natatapos ang mga limitasyon ng provisional kapag ikaw ay 18 na, o pagkalipas ng anim na buwan sa provisional license na walang paglabag, kapag hiniling mo sa DMV na alisin ang mga ito.","p":"Tama. Natatapos ang mga limitasyon sa edad na 18 o pagkalipas ng anim na malinis na buwan."},"ar":{"q":"في Alaska، متى تنتهي قيود الرخصة المؤقتة؟","o":["بعد شهر واحد بدون حادث","في سن 18، أو بعد ستة أشهر بدون مخالفات","في سن 21 فقط","بعد أن ينجح السائق في اختبار قيادة ثانٍ"],"h1":"هناك طريقتان: عمر معيّن وسجل نظيف.","h2":"تنتهي قيود الرخصة المؤقتة عندما تبلغ 18 سنة، أو بعد ستة أشهر على الرخصة المؤقتة بدون مخالفات، عندما تطلب من DMV إزالتها.","p":"صحيح. تنتهي القيود في سن 18 أو بعد ستة أشهر نظيفة."},"ref":{"doc":"AK","page":6}},{"id":"ak-015","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, how many questions are on the general knowledge test for a driver license?","o":["10 questions","25 questions","20 questions","30 questions"],"h1":"It is a round number between 15 and 25.","h2":"The Alaska general knowledge test has 20 questions, so each one counts for a lot.","p":"Right. The Alaska knowledge test has 20 questions."},"es":{"q":"En Alaska, ¿cuántas preguntas tiene el examen de conocimientos generales para la licencia?","o":["10 preguntas","25 preguntas","20 preguntas","30 preguntas"],"h1":"Es un número redondo entre 15 y 25.","h2":"El examen de conocimientos generales de Alaska tiene 20 preguntas, así que cada una cuenta mucho.","p":"Correcto. El examen de conocimientos de Alaska tiene 20 preguntas."},"zh":{"q":"在 Alaska，驾照的普通知识笔试有多少道题？","o":["10 道题","25 道题","20 道题","30 道题"],"h1":"它是 15 和 25 之间的一个整数。","h2":"Alaska 的普通知识笔试有 20 道题，所以每一道题都很重要。","p":"对。Alaska 的笔试有 20 道题。"},"vi":{"q":"Ở Alaska, bài thi kiến thức chung để lấy bằng lái có bao nhiêu câu hỏi?","o":["10 câu hỏi","25 câu hỏi","20 câu hỏi","30 câu hỏi"],"h1":"Đó là một số tròn giữa 15 và 25.","h2":"Bài thi kiến thức chung ở Alaska có 20 câu hỏi, vì vậy mỗi câu đều rất quan trọng.","p":"Đúng. Bài thi kiến thức ở Alaska có 20 câu hỏi."},"tl":{"q":"Sa Alaska, ilang tanong ang nasa general knowledge test para sa driver license?","o":["10 tanong","25 tanong","20 tanong","30 tanong"],"h1":"Ito ay buong numero sa pagitan ng 15 at 25.","h2":"Ang general knowledge test sa Alaska ay may 20 tanong, kaya malaki ang halaga ng bawat isa.","p":"Tama. May 20 tanong ang knowledge test sa Alaska."},"ar":{"q":"في Alaska، كم سؤالًا في اختبار المعرفة العامة لرخصة القيادة؟","o":["10 أسئلة","25 سؤالًا","20 سؤالًا","30 سؤالًا"],"h1":"إنه رقم مستدير بين 15 و25.","h2":"اختبار المعرفة العامة في Alaska فيه 20 سؤالًا، لذلك كل سؤال له وزن كبير.","p":"صحيح. اختبار المعرفة في Alaska فيه 20 سؤالًا."},"ref":{"doc":"AK","page":null}},{"id":"ak-016","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, how many correct answers do you need to pass the general knowledge test?","o":["16 correct answers","14 correct answers","18 correct answers","12 correct answers"],"h1":"You need 80 percent of the questions right.","h2":"You must answer at least 16 questions correctly to pass, which is 80 percent of the test.","p":"Right. You need 16 correct answers to pass."},"es":{"q":"En Alaska, ¿cuántas respuestas correctas necesita para aprobar el examen de conocimientos generales?","o":["16 respuestas correctas","14 respuestas correctas","18 respuestas correctas","12 respuestas correctas"],"h1":"Necesita el 80 por ciento de las preguntas bien.","h2":"Usted debe contestar bien por lo menos 16 preguntas para aprobar, que es el 80 por ciento del examen.","p":"Correcto. Necesita 16 respuestas correctas para aprobar."},"zh":{"q":"在 Alaska，普通知识笔试要答对多少道题才能通过？","o":["答对 16 道","答对 14 道","答对 18 道","答对 12 道"],"h1":"你需要答对 80% 的题目。","h2":"你必须至少答对 16 道题才能通过，也就是笔试的 80%。","p":"对。你需要答对 16 道题才能通过。"},"vi":{"q":"Ở Alaska, bạn cần bao nhiêu câu trả lời đúng để đậu bài thi kiến thức chung?","o":["16 câu trả lời đúng","14 câu trả lời đúng","18 câu trả lời đúng","12 câu trả lời đúng"],"h1":"Bạn cần trả lời đúng 80 phần trăm số câu hỏi.","h2":"Bạn phải trả lời đúng ít nhất 16 câu để đậu, tức là 80 phần trăm của bài thi.","p":"Đúng. Bạn cần 16 câu trả lời đúng để đậu."},"tl":{"q":"Sa Alaska, ilang tamang sagot ang kailangan mo para pumasa sa general knowledge test?","o":["16 na tamang sagot","14 na tamang sagot","18 na tamang sagot","12 na tamang sagot"],"h1":"Kailangan mong tama ang 80 porsiyento ng mga tanong.","h2":"Dapat mong masagot nang tama ang hindi bababa sa 16 na tanong para pumasa, na 80 porsiyento ng test.","p":"Tama. Kailangan mo ng 16 na tamang sagot para pumasa."},"ar":{"q":"في Alaska، كم إجابة صحيحة تحتاج لتنجح في اختبار المعرفة العامة؟","o":["16 إجابة صحيحة","14 إجابة صحيحة","18 إجابة صحيحة","12 إجابة صحيحة"],"h1":"تحتاج إلى إجابة 80 في المئة من الأسئلة بشكل صحيح.","h2":"يجب أن تجيب على 16 سؤالًا على الأقل بشكل صحيح لتنجح، وهذا 80 في المئة من الاختبار.","p":"صحيح. تحتاج إلى 16 إجابة صحيحة لتنجح."},"ref":{"doc":"AK","page":null}},{"id":"ak-017","scope":"AK","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Alaska, if no sign shows a different limit, what is the top speed in a residential district?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"It is a little faster than in a business district.","h2":"Unless a sign says otherwise, the top legal speed in a residential district is 25 mph, because children and walkers are often near the road.","p":"Right. The default limit in a residential district is 25 mph."},"es":{"q":"En Alaska, si ninguna señal indica otro límite, ¿cuál es la velocidad máxima en una zona residencial?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Es un poco más rápido que en una zona comercial.","h2":"Salvo que una señal diga otra cosa, la velocidad máxima legal en una zona residencial es 25 mph, porque a menudo hay niños y peatones cerca del camino.","p":"Correcto. El límite normal en una zona residencial es 25 mph."},"zh":{"q":"在 Alaska，如果没有标志写着别的限速，住宅区的最高速度是多少？","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"它比商业区快一点。","h2":"除非标志另有规定，住宅区的最高合法速度是 25 mph，因为孩子和行人常常在路边。","p":"对。住宅区的默认限速是 25 mph。"},"vi":{"q":"Ở Alaska, nếu không có biển báo giới hạn khác, tốc độ tối đa trong khu dân cư là bao nhiêu?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Nó nhanh hơn một chút so với khu thương mại.","h2":"Trừ khi có biển báo khác, tốc độ tối đa hợp pháp trong khu dân cư là 25 mph, vì trẻ em và người đi bộ thường ở gần đường.","p":"Đúng. Giới hạn mặc định trong khu dân cư là 25 mph."},"tl":{"q":"Sa Alaska, kung walang karatulang nagpapakita ng ibang limitasyon, ano ang pinakamataas na bilis sa residential district?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Medyo mas mabilis ito kaysa sa business district.","h2":"Maliban kung iba ang sinasabi ng karatula, ang pinakamataas na legal na bilis sa residential district ay 25 mph, dahil madalas may mga bata at naglalakad malapit sa daan.","p":"Tama. Ang default na limitasyon sa residential district ay 25 mph."},"ar":{"q":"في Alaska، إذا لم تكن هناك لافتة تُظهر حدًا مختلفًا، ما أعلى سرعة في المنطقة السكنية؟","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"إنها أسرع قليلًا من المنطقة التجارية.","h2":"إلا إذا قالت لافتة غير ذلك، أعلى سرعة قانونية في المنطقة السكنية هي 25 mph، لأن الأطفال والمشاة يكونون غالبًا قرب الطريق.","p":"صحيح. الحد الأساسي في المنطقة السكنية هو 25 mph."},"ref":{"doc":"AK","page":29}},{"id":"ak-018","scope":"AK","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Alaska, if no sign shows a different limit, what is the top speed in a business district?","o":["20 mph","15 mph","30 mph","25 mph"],"h1":"It is slower than a residential district.","h2":"Unless a sign says otherwise, the top legal speed in a business district is 20 mph, because traffic, parking and people on foot are very close together.","p":"Right. The default limit in a business district is 20 mph."},"es":{"q":"En Alaska, si ninguna señal indica otro límite, ¿cuál es la velocidad máxima en una zona comercial?","o":["20 mph","15 mph","30 mph","25 mph"],"h1":"Es más lento que en una zona residencial.","h2":"Salvo que una señal diga otra cosa, la velocidad máxima legal en una zona comercial es 20 mph, porque el tráfico, los carros estacionados y los peatones están muy cerca.","p":"Correcto. El límite normal en una zona comercial es 20 mph."},"zh":{"q":"在 Alaska，如果没有标志写着别的限速，商业区的最高速度是多少？","o":["20 mph","15 mph","30 mph","25 mph"],"h1":"它比住宅区慢。","h2":"除非标志另有规定，商业区的最高合法速度是 20 mph，因为车流、停车和行人都离得很近。","p":"对。商业区的默认限速是 20 mph。"},"vi":{"q":"Ở Alaska, nếu không có biển báo giới hạn khác, tốc độ tối đa trong khu thương mại là bao nhiêu?","o":["20 mph","15 mph","30 mph","25 mph"],"h1":"Nó chậm hơn so với khu dân cư.","h2":"Trừ khi có biển báo khác, tốc độ tối đa hợp pháp trong khu thương mại là 20 mph, vì xe cộ, chỗ đậu xe và người đi bộ ở rất gần nhau.","p":"Đúng. Giới hạn mặc định trong khu thương mại là 20 mph."},"tl":{"q":"Sa Alaska, kung walang karatulang nagpapakita ng ibang limitasyon, ano ang pinakamataas na bilis sa business district?","o":["20 mph","15 mph","30 mph","25 mph"],"h1":"Mas mabagal ito kaysa sa residential district.","h2":"Maliban kung iba ang sinasabi ng karatula, ang pinakamataas na legal na bilis sa business district ay 20 mph, dahil magkakalapit ang trapiko, paradahan at mga taong naglalakad.","p":"Tama. Ang default na limitasyon sa business district ay 20 mph."},"ar":{"q":"في Alaska، إذا لم تكن هناك لافتة تُظهر حدًا مختلفًا، ما أعلى سرعة في المنطقة التجارية؟","o":["20 mph","15 mph","30 mph","25 mph"],"h1":"إنها أبطأ من المنطقة السكنية.","h2":"إلا إذا قالت لافتة غير ذلك، أعلى سرعة قانونية في المنطقة التجارية هي 20 mph، لأن السيارات والمواقف والمشاة قريبون جدًا من بعضهم.","p":"صحيح. الحد الأساسي في المنطقة التجارية هو 20 mph."},"ref":{"doc":"AK","page":29}},{"id":"ak-019","scope":"AK","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Alaska, if no sign shows a different limit, what is the top speed in an alley?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"It is the lowest of the default limits, but more than 10.","h2":"Unless a sign says otherwise, the top legal speed in an alley is 15 mph, because alleys are narrow and you cannot see far.","p":"Right. The default limit in an alley is 15 mph."},"es":{"q":"En Alaska, si ninguna señal indica otro límite, ¿cuál es la velocidad máxima en un callejón?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"Es el más bajo de los límites normales, pero más de 10.","h2":"Salvo que una señal diga otra cosa, la velocidad máxima legal en un callejón es 15 mph, porque los callejones son angostos y no se ve lejos.","p":"Correcto. El límite normal en un callejón es 15 mph."},"zh":{"q":"在 Alaska，如果没有标志写着别的限速，小巷里的最高速度是多少？","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"它是默认限速里最低的，但比 10 高。","h2":"除非标志另有规定，小巷里的最高合法速度是 15 mph，因为小巷很窄，你看不远。","p":"对。小巷的默认限速是 15 mph。"},"vi":{"q":"Ở Alaska, nếu không có biển báo giới hạn khác, tốc độ tối đa trong hẻm là bao nhiêu?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"Đó là giới hạn mặc định thấp nhất, nhưng cao hơn 10.","h2":"Trừ khi có biển báo khác, tốc độ tối đa hợp pháp trong hẻm là 15 mph, vì hẻm hẹp và bạn không nhìn được xa.","p":"Đúng. Giới hạn mặc định trong hẻm là 15 mph."},"tl":{"q":"Sa Alaska, kung walang karatulang nagpapakita ng ibang limitasyon, ano ang pinakamataas na bilis sa eskinita (alley)?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"Ito ang pinakamababa sa mga default na limitasyon, pero higit sa 10.","h2":"Maliban kung iba ang sinasabi ng karatula, ang pinakamataas na legal na bilis sa eskinita ay 15 mph, dahil makitid ang mga eskinita at hindi ka makakita nang malayo.","p":"Tama. Ang default na limitasyon sa eskinita ay 15 mph."},"ar":{"q":"في Alaska، إذا لم تكن هناك لافتة تُظهر حدًا مختلفًا، ما أعلى سرعة في الزقاق (alley)؟","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"إنها أقل الحدود الأساسية، لكنها أكثر من 10.","h2":"إلا إذا قالت لافتة غير ذلك، أعلى سرعة قانونية في الزقاق هي 15 mph، لأن الأزقة ضيقة ولا يمكنك أن ترى بعيدًا.","p":"صحيح. الحد الأساسي في الزقاق هو 15 mph."},"ref":{"doc":"AK","page":29}},{"id":"ak-020","scope":"AK","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Alaska, on a road outside business and residential districts with no speed sign, what is the top legal speed?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"Higher limits on some highways must be posted on signs.","h2":"When no sign shows a limit on other roads, the top legal speed is 55 mph; faster limits apply only where signs post them.","p":"Right. The default limit on other roads is 55 mph."},"es":{"q":"En Alaska, en un camino fuera de zonas comerciales y residenciales y sin señal de velocidad, ¿cuál es la velocidad máxima legal?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"Los límites más altos en algunas carreteras deben estar en señales.","h2":"Cuando ninguna señal indica el límite en otros caminos, la velocidad máxima legal es 55 mph; los límites más altos solo aplican donde hay señales.","p":"Correcto. El límite normal en otros caminos es 55 mph."},"zh":{"q":"在 Alaska，在商业区和住宅区以外、没有限速标志的道路上，最高合法速度是多少？","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"有些公路的更高限速必须用标志写出来。","h2":"在其他道路上没有标志写着限速时，最高合法速度是 55 mph；更高的限速只在有标志的地方适用。","p":"对。其他道路的默认限速是 55 mph。"},"vi":{"q":"Ở Alaska, trên đường ngoài khu thương mại và khu dân cư, không có biển báo tốc độ, tốc độ tối đa hợp pháp là bao nhiêu?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"Giới hạn cao hơn trên một số xa lộ phải được ghi trên biển báo.","h2":"Khi không có biển báo giới hạn trên các đường khác, tốc độ tối đa hợp pháp là 55 mph; giới hạn cao hơn chỉ áp dụng ở nơi có biển báo ghi rõ.","p":"Đúng. Giới hạn mặc định trên các đường khác là 55 mph."},"tl":{"q":"Sa Alaska, sa daan na nasa labas ng business at residential district na walang karatula ng bilis, ano ang pinakamataas na legal na bilis?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"Ang mas mataas na limitasyon sa ilang highway ay dapat nakasulat sa karatula.","h2":"Kapag walang karatulang nagpapakita ng limitasyon sa ibang daan, ang pinakamataas na legal na bilis ay 55 mph; ang mas mabilis na limitasyon ay para lamang sa mga lugar na may karatula nito.","p":"Tama. Ang default na limitasyon sa ibang daan ay 55 mph."},"ar":{"q":"في Alaska، على طريق خارج المناطق التجارية والسكنية بدون لافتة سرعة، ما أعلى سرعة قانونية؟","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"الحدود الأعلى على بعض الطرق السريعة يجب أن تُكتب على لافتات.","h2":"عندما لا توجد لافتة تُظهر الحد على الطرق الأخرى، أعلى سرعة قانونية هي 55 mph؛ والحدود الأسرع تنطبق فقط حيث تُظهرها اللافتات.","p":"صحيح. الحد الأساسي على الطرق الأخرى هو 55 mph."},"ref":{"doc":"AK","page":29}},{"id":"ak-021","scope":"AK","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Alaska, during which time must you have your headlights on?","o":["Only when it is fully dark outside","From half an hour after sunset to half an hour before sunrise","From one hour after sunset to sunrise","Only on highways with more than two lanes"],"h1":"The rule adds a short time around sunset and sunrise.","h2":"You must use your headlights from half an hour after sunset until half an hour before sunrise, so others can see you in low light.","p":"Right. Lights go on half an hour after sunset until half an hour before sunrise."},"es":{"q":"En Alaska, ¿en qué horario debe llevar las luces delanteras encendidas?","o":["Solo cuando está totalmente oscuro","Desde media hora después de la puesta del sol hasta media hora antes del amanecer","Desde una hora después de la puesta del sol hasta el amanecer","Solo en carreteras de más de dos carriles"],"h1":"La regla agrega un rato corto alrededor de la puesta del sol y el amanecer.","h2":"Usted debe usar las luces delanteras desde media hora después de la puesta del sol hasta media hora antes del amanecer, para que otros lo vean con poca luz.","p":"Correcto. Las luces van encendidas desde media hora después de la puesta del sol hasta media hora antes del amanecer."},"zh":{"q":"在 Alaska，你必须在什么时间打开大灯？","o":["只有外面完全黑的时候","日落后半小时到日出前半小时","日落后一小时到日出","只在超过两条车道的公路上"],"h1":"这个规定在日落和日出前后多加了一小段时间。","h2":"你必须从日落后半小时到日出前半小时打开大灯，这样在光线不好时别人能看到你。","p":"对。日落后半小时到日出前半小时要开灯。"},"vi":{"q":"Ở Alaska, bạn phải bật đèn pha trong khoảng thời gian nào?","o":["Chỉ khi bên ngoài trời tối hẳn","Từ nửa giờ sau khi mặt trời lặn đến nửa giờ trước khi mặt trời mọc","Từ một giờ sau khi mặt trời lặn đến khi mặt trời mọc","Chỉ trên xa lộ có hơn hai làn xe"],"h1":"Quy định thêm một khoảng thời gian ngắn quanh lúc mặt trời lặn và mọc.","h2":"Bạn phải bật đèn pha từ nửa giờ sau khi mặt trời lặn đến nửa giờ trước khi mặt trời mọc, để người khác nhìn thấy bạn khi trời ít sáng.","p":"Đúng. Bật đèn từ nửa giờ sau khi mặt trời lặn đến nửa giờ trước khi mặt trời mọc."},"tl":{"q":"Sa Alaska, sa anong oras dapat nakabukas ang iyong headlights?","o":["Kapag ganap na madilim lamang sa labas","Mula kalahating oras pagkalubog ng araw hanggang kalahating oras bago sumikat ang araw","Mula isang oras pagkalubog ng araw hanggang sa pagsikat ng araw","Sa mga highway lamang na may higit sa dalawang lane"],"h1":"Nagdadagdag ang patakaran ng maikling oras sa paligid ng paglubog at pagsikat ng araw.","h2":"Dapat mong gamitin ang iyong headlights mula kalahating oras pagkalubog ng araw hanggang kalahating oras bago sumikat ang araw, para makita ka ng iba kapag mahina ang liwanag.","p":"Tama. Binubuksan ang ilaw mula kalahating oras pagkalubog ng araw hanggang kalahating oras bago sumikat ang araw."},"ar":{"q":"في Alaska، في أي وقت يجب أن تكون أضواء سيارتك الأمامية مضاءة؟","o":["فقط عندما يكون الظلام كاملًا في الخارج","من نصف ساعة بعد غروب الشمس إلى نصف ساعة قبل شروقها","من ساعة بعد غروب الشمس إلى شروقها","فقط على الطرق السريعة التي فيها أكثر من مسارين"],"h1":"القاعدة تضيف وقتًا قصيرًا حول الغروب والشروق.","h2":"يجب أن تستعمل الأضواء الأمامية من نصف ساعة بعد غروب الشمس حتى نصف ساعة قبل شروقها، حتى يراك الآخرون عندما يكون الضوء ضعيفًا.","p":"صحيح. تُشعل الأضواء من نصف ساعة بعد الغروب حتى نصف ساعة قبل الشروق."},"ref":{"doc":"AK","page":55}},{"id":"ak-022","scope":"AK","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Alaska, you must also turn on your headlights when you cannot clearly see people or vehicles at what distance?","o":["500 feet","200 feet","1,500 feet","1,000 feet"],"h1":"It is a round number, about three football fields.","h2":"You must turn on your headlights any time fog, snow or low light keeps you from clearly seeing people or vehicles 1,000 feet away.","p":"Right. If you cannot see clearly at 1,000 feet, turn your lights on."},"es":{"q":"En Alaska, también debe encender las luces delanteras cuando no puede ver bien a personas o vehículos. ¿A qué distancia?","o":["500 pies","200 pies","1,500 pies","1,000 pies"],"h1":"Es un número redondo, como tres canchas de fútbol americano.","h2":"Usted debe encender las luces delanteras siempre que la niebla, la nieve o la poca luz no le dejen ver bien a personas o vehículos a 1,000 pies.","p":"Correcto. Si no ve bien a 1,000 pies, encienda las luces."},"zh":{"q":"在 Alaska，当你在多远的距离看不清人或车辆时，也必须打开大灯？","o":["500 英尺","200 英尺","1,500 英尺","1,000 英尺"],"h1":"它是一个整数，大约是三个橄榄球场那么长。","h2":"只要雾、雪或光线不好让你看不清 1,000 英尺外的人或车辆，你就必须打开大灯。","p":"对。如果在 1,000 英尺看不清，就要开灯。"},"vi":{"q":"Ở Alaska, bạn cũng phải bật đèn pha khi không nhìn rõ người hoặc xe ở khoảng cách bao xa?","o":["500 feet","200 feet","1,500 feet","1,000 feet"],"h1":"Đó là một số tròn, khoảng ba sân bóng bầu dục.","h2":"Bạn phải bật đèn pha bất cứ khi nào sương mù, tuyết hoặc trời ít sáng làm bạn không nhìn rõ người hoặc xe ở cách 1,000 feet.","p":"Đúng. Nếu không nhìn rõ ở 1,000 feet, hãy bật đèn."},"tl":{"q":"Sa Alaska, dapat mo ring buksan ang headlights kapag hindi mo malinaw na makita ang mga tao o sasakyan sa anong layo?","o":["500 feet","200 feet","1,500 feet","1,000 feet"],"h1":"Ito ay buong numero, mga tatlong football field.","h2":"Dapat mong buksan ang headlights tuwing ang fog, niyebe o mahinang liwanag ay pumipigil sa iyong malinaw na makita ang mga tao o sasakyan sa layong 1,000 feet.","p":"Tama. Kung hindi ka malinaw na makakita sa 1,000 feet, buksan ang iyong ilaw."},"ar":{"q":"في Alaska، يجب أيضًا أن تُشعل الأضواء الأمامية عندما لا تستطيع أن ترى الناس أو المركبات بوضوح على أي مسافة؟","o":["500 feet","200 feet","1,500 feet","1,000 feet"],"h1":"إنه رقم مستدير، حوالي طول ثلاثة ملاعب كرة قدم أمريكية.","h2":"يجب أن تُشعل الأضواء الأمامية في أي وقت يمنعك فيه الضباب أو الثلج أو الضوء الضعيف من رؤية الناس أو المركبات بوضوح على بُعد 1,000 feet.","p":"صحيح. إذا لم تستطع أن ترى بوضوح على بُعد 1,000 feet، أشعل الأضواء."},"ref":{"doc":"AK","page":55}},{"id":"ak-023","scope":"AK","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Alaska, you are driving slowly on a two-lane road outside a city. How many vehicles lined up behind you mean you must pull over at the first safe place?","o":["Two vehicles","Three vehicles","Five vehicles","Ten vehicles"],"h1":"It is the number of fingers on one hand.","h2":"When five or more vehicles are lined up right behind you on a two-lane road outside a city, you must pull off the road at the first safe place to let them by.","p":"Right. Five or more vehicles behind you means you pull over at the first safe place."},"es":{"q":"En Alaska, usted maneja despacio en un camino de dos carriles fuera de la ciudad. ¿Cuántos vehículos en fila detrás de usted lo obligan a orillarse en el primer lugar seguro?","o":["Dos vehículos","Tres vehículos","Cinco vehículos","Diez vehículos"],"h1":"Es el número de dedos de una mano.","h2":"Cuando cinco o más vehículos van en fila justo detrás de usted en un camino de dos carriles fuera de la ciudad, usted debe salirse del camino en el primer lugar seguro para dejarlos pasar.","p":"Correcto. Con cinco o más vehículos detrás, oríllese en el primer lugar seguro."},"zh":{"q":"在 Alaska，你在城外的双车道道路上开得很慢。你后面排了多少辆车时，你必须在第一个安全的地方靠边？","o":["两辆车","三辆车","五辆车","十辆车"],"h1":"它是一只手的手指数。","h2":"在城外的双车道道路上，当你正后面排了五辆或更多的车时，你必须在第一个安全的地方开出道路，让它们过去。","p":"对。后面有五辆或更多的车，就要在第一个安全的地方靠边。"},"vi":{"q":"Ở Alaska, bạn đang lái chậm trên đường hai làn ngoài thành phố. Có bao nhiêu xe nối đuôi sau bạn thì bạn phải tấp vào lề ở chỗ an toàn đầu tiên?","o":["Hai xe","Ba xe","Năm xe","Mười xe"],"h1":"Đó là số ngón tay trên một bàn tay.","h2":"Khi có năm xe trở lên nối đuôi ngay sau bạn trên đường hai làn ngoài thành phố, bạn phải tấp ra khỏi đường ở chỗ an toàn đầu tiên để họ đi qua.","p":"Đúng. Có năm xe trở lên sau bạn thì bạn tấp vào ở chỗ an toàn đầu tiên."},"tl":{"q":"Sa Alaska, mabagal kang nagmamaneho sa two-lane na daan sa labas ng lungsod. Ilang sasakyan na nakapila sa likod mo ang nangangahulugang dapat kang tumabi sa unang ligtas na lugar?","o":["Dalawang sasakyan","Tatlong sasakyan","Limang sasakyan","Sampung sasakyan"],"h1":"Ito ang bilang ng mga daliri sa isang kamay.","h2":"Kapag lima o higit pang sasakyan ang nakapila sa likod mo sa two-lane na daan sa labas ng lungsod, dapat kang umalis sa daan sa unang ligtas na lugar para makadaan sila.","p":"Tama. Lima o higit pang sasakyan sa likod mo ay nangangahulugang tumabi ka sa unang ligtas na lugar."},"ar":{"q":"في Alaska، أنت تقود ببطء على طريق ذي مسارين خارج المدينة. كم مركبة مصطفّة خلفك تعني أنه يجب أن تتنحّى جانبًا في أول مكان آمن؟","o":["مركبتان","ثلاث مركبات","خمس مركبات","عشر مركبات"],"h1":"إنه عدد أصابع اليد الواحدة.","h2":"عندما تصطفّ خمس مركبات أو أكثر خلفك مباشرة على طريق ذي مسارين خارج المدينة، يجب أن تخرج من الطريق في أول مكان آمن لتسمح لها بالمرور.","p":"صحيح. خمس مركبات أو أكثر خلفك تعني أن تتنحّى جانبًا في أول مكان آمن."},"ref":{"doc":"AK","page":27}},{"id":"ak-024","scope":"AK","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Alaska, a school bus ahead has stopped with its red lights flashing. How far from the bus must you stop?","o":["At least 30 feet","At least 10 feet","At least 20 feet","At least 50 feet"],"h1":"Alaska asks for more room than many states.","h2":"You must stop at least 30 feet from a school bus with flashing red lights and wait until the lights stop and the bus moves.","p":"Right. Stop at least 30 feet from the bus."},"es":{"q":"En Alaska, un autobús escolar adelante se detuvo con las luces rojas intermitentes. ¿A qué distancia del autobús debe detenerse?","o":["Por lo menos a 30 pies","Por lo menos a 10 pies","Por lo menos a 20 pies","Por lo menos a 50 pies"],"h1":"Alaska pide más espacio que muchos estados.","h2":"Usted debe detenerse por lo menos a 30 pies de un autobús escolar con luces rojas intermitentes y esperar a que se apaguen las luces y el autobús avance.","p":"Correcto. Deténgase por lo menos a 30 pies del autobús."},"zh":{"q":"在 Alaska，前面的校车停了下来，红灯在闪。你必须在离校车多远的地方停车？","o":["至少 30 英尺","至少 10 英尺","至少 20 英尺","至少 50 英尺"],"h1":"Alaska 要求的距离比很多州都大。","h2":"你必须在离红灯闪烁的校车至少 30 英尺的地方停车，等到灯停止闪烁、校车开走。","p":"对。在离校车至少 30 英尺的地方停车。"},"vi":{"q":"Ở Alaska, một xe buýt trường học phía trước đã dừng và đang nhấp nháy đèn đỏ. Bạn phải dừng cách xe buýt bao xa?","o":["Ít nhất 30 feet","Ít nhất 10 feet","Ít nhất 20 feet","Ít nhất 50 feet"],"h1":"Alaska yêu cầu khoảng cách xa hơn nhiều tiểu bang khác.","h2":"Bạn phải dừng cách xe buýt trường học đang nhấp nháy đèn đỏ ít nhất 30 feet và chờ đến khi đèn tắt và xe buýt chạy đi.","p":"Đúng. Dừng cách xe buýt ít nhất 30 feet."},"tl":{"q":"Sa Alaska, huminto ang isang school bus sa unahan na kumikislap ang pulang ilaw. Gaano kalayo mula sa bus ka dapat huminto?","o":["Hindi bababa sa 30 feet","Hindi bababa sa 10 feet","Hindi bababa sa 20 feet","Hindi bababa sa 50 feet"],"h1":"Mas malaking espasyo ang hinihingi ng Alaska kaysa sa maraming estado.","h2":"Dapat kang huminto nang hindi bababa sa 30 feet mula sa school bus na kumikislap ang pulang ilaw at maghintay hanggang tumigil ang ilaw at umandar ang bus.","p":"Tama. Huminto nang hindi bababa sa 30 feet mula sa bus."},"ar":{"q":"في Alaska، حافلة مدرسية أمامك توقفت وأضواؤها الحمراء تومض. على أي بُعد من الحافلة يجب أن تتوقف؟","o":["30 feet على الأقل","10 feet على الأقل","20 feet على الأقل","50 feet على الأقل"],"h1":"تطلب Alaska مسافة أكبر من ولايات كثيرة.","h2":"يجب أن تتوقف على بُعد 30 feet على الأقل من الحافلة المدرسية التي تومض أضواؤها الحمراء، وتنتظر حتى تتوقف الأضواء وتتحرك الحافلة.","p":"صحيح. توقّف على بُعد 30 feet على الأقل من الحافلة."},"ref":{"doc":"AK","page":null}},{"id":"ak-025","scope":"AK","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Alaska, on a road with two lanes going your way, you see a stopped police car with flashing lights. What should you do?","o":["Keep the same lane and speed","Move to the farther lane if it is safe, or else slow down","Stop next to the police car","Speed up to pass it quickly"],"h1":"Give the officer more room, or more time.","h2":"You must move away from the stopped emergency vehicle into another lane when it is safe; if you cannot, you must slow down as you pass.","p":"Right. Move over if it is safe, or slow down."},"es":{"q":"En Alaska, en un camino con dos carriles en su dirección, usted ve un carro de policía detenido con luces intermitentes. ¿Qué debe hacer?","o":["Seguir en el mismo carril y a la misma velocidad","Pasarse al carril más lejano si es seguro, o si no, bajar la velocidad","Detenerse al lado del carro de policía","Acelerar para pasarlo rápido"],"h1":"Déle al oficial más espacio, o más tiempo.","h2":"Usted debe alejarse del vehículo de emergencia detenido pasándose a otro carril cuando sea seguro; si no puede, debe bajar la velocidad al pasar.","p":"Correcto. Cámbiese de carril si es seguro, o baje la velocidad."},"zh":{"q":"在 Alaska，在你的方向有两条车道的道路上，你看到一辆停着的警车，车灯在闪。你应该怎么做？","o":["保持同一条车道和速度","如果安全就换到较远的车道，否则就减速","停在警车旁边","加速快点开过去"],"h1":"给警察更多空间，或者更多时间。","h2":"在安全时，你必须换到另一条车道，离停着的急救车辆远一点；如果做不到，开过去时必须减速。","p":"对。安全时就让开车道（move over），否则就减速。"},"vi":{"q":"Ở Alaska, trên đường có hai làn cùng chiều với bạn, bạn thấy một xe cảnh sát đang dừng và nhấp nháy đèn. Bạn nên làm gì?","o":["Giữ nguyên làn và tốc độ","Chuyển sang làn xa hơn nếu an toàn, nếu không thì chạy chậm lại","Dừng lại cạnh xe cảnh sát","Tăng tốc để vượt qua nhanh"],"h1":"Hãy cho cảnh sát thêm khoảng cách, hoặc thêm thời gian.","h2":"Bạn phải chuyển sang làn khác, tránh xa xe cấp cứu đang dừng, khi an toàn; nếu không thể, bạn phải chạy chậm lại khi đi qua.","p":"Đúng. Chuyển làn nếu an toàn, nếu không thì chạy chậm lại."},"tl":{"q":"Sa Alaska, sa daan na may dalawang lane papunta sa direksiyon mo, may nakita kang nakahintong police car na kumikislap ang ilaw. Ano ang dapat mong gawin?","o":["Manatili sa parehong lane at bilis","Lumipat sa mas malayong lane kung ligtas, o kung hindi ay bumagal","Huminto sa tabi ng police car","Bumilis para malampasan ito agad"],"h1":"Bigyan ang pulis ng mas maraming espasyo, o mas maraming oras.","h2":"Dapat kang lumayo sa nakahintong emergency vehicle at lumipat sa ibang lane kapag ligtas; kung hindi mo kaya, dapat kang bumagal habang dumadaan.","p":"Tama. Lumipat ng lane kung ligtas, o bumagal."},"ar":{"q":"في Alaska، على طريق فيه مساران في اتجاهك، ترى سيارة شرطة متوقفة وأضواؤها تومض. ماذا يجب أن تفعل؟","o":["ابقَ في نفس المسار وبنفس السرعة","انتقل إلى المسار الأبعد إذا كان ذلك آمنًا، وإلا فخفّف السرعة","توقّف بجانب سيارة الشرطة","زِد السرعة لتتجاوزها بسرعة"],"h1":"أعطِ الشرطي مسافة أكبر، أو وقتًا أكثر.","h2":"يجب أن تبتعد عن مركبة الطوارئ المتوقفة وتنتقل إلى مسار آخر عندما يكون ذلك آمنًا؛ وإذا لم تستطع، يجب أن تخفّف السرعة وأنت تمرّ.","p":"صحيح. انتقل إلى مسار آخر إذا كان آمنًا، أو خفّف السرعة."},"ref":{"doc":"AK","page":64}},{"id":"ak-026","scope":"AK","cat":"signals","sign":null,"c":2,"en":{"q":"In Alaska, you are stopped at a red light and want to turn right. There is no sign about turning. What may you do?","o":["Turn right without stopping","Wait for the light to turn green","Turn right after a full stop, yielding to people and traffic","Turn right only if a police officer waves you on"],"h1":"Alaska allows it, but only after you do one thing first.","h2":"You may turn right on red after you come to a full stop and yield to people walking and to other traffic, unless a sign forbids the turn.","p":"Right. Stop fully, yield, and then you may turn right on red."},"es":{"q":"En Alaska, usted está detenido en una luz roja y quiere doblar a la derecha. No hay señal sobre la vuelta. ¿Qué puede hacer?","o":["Doblar a la derecha sin detenerse","Esperar a que la luz cambie a verde","Doblar a la derecha después de un alto total, cediendo el paso a peatones y tráfico","Doblar a la derecha solo si un policía le hace señas"],"h1":"Alaska lo permite, pero solo después de hacer algo primero.","h2":"Usted puede doblar a la derecha con luz roja después de hacer un alto total y ceder el paso a los peatones y al tráfico, salvo que una señal lo prohíba.","p":"Correcto. Haga un alto total, ceda el paso y luego puede doblar a la derecha con luz roja."},"zh":{"q":"在 Alaska，你在红灯前停着，想右转。没有关于转弯的标志。你可以怎么做？","o":["不停车直接右转","等到绿灯","完全停车后右转，让行人和其他车先走","只有警察挥手让你走时才右转"],"h1":"Alaska 允许这样做，但你必须先做一件事。","h2":"你完全停车、让行人和其他车先走以后，可以在红灯时右转，除非有标志禁止。","p":"对。完全停车，让行，然后可以红灯右转。"},"vi":{"q":"Ở Alaska, bạn đang dừng ở đèn đỏ và muốn rẽ phải. Không có biển báo nào về việc rẽ. Bạn được làm gì?","o":["Rẽ phải mà không cần dừng","Chờ đèn chuyển sang xanh","Rẽ phải sau khi dừng hẳn, nhường đường cho người đi bộ và xe khác","Chỉ rẽ phải nếu cảnh sát ra hiệu cho bạn đi"],"h1":"Alaska cho phép, nhưng chỉ sau khi bạn làm một việc trước.","h2":"Bạn được rẽ phải khi đèn đỏ sau khi dừng hẳn và nhường đường cho người đi bộ và xe khác, trừ khi có biển báo cấm rẽ.","p":"Đúng. Dừng hẳn, nhường đường, rồi bạn được rẽ phải khi đèn đỏ."},"tl":{"q":"Sa Alaska, nakahinto ka sa pulang ilaw at gusto mong kumanan. Walang karatula tungkol sa pagliko. Ano ang puwede mong gawin?","o":["Kumanan nang hindi humihinto","Maghintay na maging berde ang ilaw","Kumanan pagkatapos ng buong paghinto, nagbibigay-daan sa mga tao at trapiko","Kumanan lamang kung kinawayan ka ng pulis"],"h1":"Pinapayagan ito ng Alaska, pero pagkatapos mo lamang gawin ang isang bagay muna.","h2":"Puwede kang kumanan sa pula pagkatapos mong huminto nang buo at magbigay-daan sa mga naglalakad at sa ibang trapiko, maliban kung may karatulang nagbabawal sa pagliko.","p":"Tama. Huminto nang buo, magbigay-daan, at saka ka puwedeng kumanan sa pula."},"ar":{"q":"في Alaska، أنت متوقف عند إشارة حمراء وتريد أن تنعطف يمينًا. لا توجد لافتة عن الانعطاف. ماذا يجوز لك أن تفعل؟","o":["انعطف يمينًا بدون توقف","انتظر حتى تصبح الإشارة خضراء","انعطف يمينًا بعد توقف كامل، مع إعطاء الأولوية للناس والمركبات","انعطف يمينًا فقط إذا أشار لك شرطي بالمرور"],"h1":"Alaska تسمح بذلك، لكن فقط بعد أن تفعل شيئًا واحدًا أولًا.","h2":"يجوز لك أن تنعطف يمينًا عند الإشارة الحمراء بعد أن تتوقف توقفًا كاملًا وتعطي الأولوية للمشاة والمركبات الأخرى، إلا إذا منعت لافتة هذا الانعطاف.","p":"صحيح. توقّف تمامًا، وأعطِ الأولوية، ثم يجوز لك أن تنعطف يمينًا عند الإشارة الحمراء."},"ref":{"doc":"AK","page":50}},{"id":"ak-027","scope":"AK","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Alaska, what is against the law for every driver while the vehicle is moving?","o":["Reading or typing a text message","Listening to the radio","Talking with a passenger","Using the heater"],"h1":"It means taking your eyes off the road to read or write.","h2":"Alaska forbids any driver from reading or typing a text or other written message on a device while the vehicle is moving, because it pulls your eyes off the road.","p":"Right. Reading or typing texts while moving is against the law."},"es":{"q":"En Alaska, ¿qué está prohibido para todo conductor mientras el vehículo está en movimiento?","o":["Leer o escribir un mensaje de texto","Escuchar la radio","Hablar con un pasajero","Usar la calefacción"],"h1":"Se trata de quitar la vista del camino para leer o escribir.","h2":"Alaska prohíbe a todo conductor leer o escribir un texto u otro mensaje escrito en un aparato mientras el vehículo se mueve, porque le quita la vista del camino.","p":"Correcto. Leer o escribir textos en movimiento va contra la ley."},"zh":{"q":"在 Alaska，车在行驶时，对所有司机来说，什么是违法的？","o":["看或打短信","听收音机","和乘客说话","用暖气"],"h1":"它的意思是眼睛离开道路去读或写。","h2":"Alaska 禁止任何司机在车行驶时用设备看或打短信或其他文字信息，因为这会让你的眼睛离开道路。","p":"对。车在行驶时看或打短信是违法的。"},"vi":{"q":"Ở Alaska, điều gì là phạm luật với mọi người lái xe khi xe đang chạy?","o":["Đọc hoặc gõ tin nhắn","Nghe radio","Nói chuyện với hành khách","Dùng máy sưởi"],"h1":"Đó là rời mắt khỏi đường để đọc hoặc viết.","h2":"Alaska cấm mọi người lái xe đọc hoặc gõ tin nhắn hay nội dung viết khác trên thiết bị khi xe đang chạy, vì việc đó làm bạn rời mắt khỏi đường.","p":"Đúng. Đọc hoặc gõ tin nhắn khi xe đang chạy là phạm luật."},"tl":{"q":"Sa Alaska, ano ang labag sa batas para sa bawat driver habang umaandar ang sasakyan?","o":["Pagbasa o pag-type ng text message","Pakikinig sa radyo","Pakikipag-usap sa pasahero","Paggamit ng heater"],"h1":"Ibig sabihin nito ay pag-alis ng tingin sa daan para magbasa o magsulat.","h2":"Ipinagbabawal ng Alaska sa sinumang driver ang pagbasa o pag-type ng text o ibang nakasulat na mensahe sa device habang umaandar ang sasakyan, dahil inaalis nito ang tingin mo sa daan.","p":"Tama. Labag sa batas ang pagbasa o pag-type ng text habang umaandar."},"ar":{"q":"في Alaska، ما الممنوع قانونيًا على كل سائق أثناء حركة المركبة؟","o":["قراءة رسالة نصية أو كتابتها","الاستماع إلى الراديو","التحدث مع راكب","استعمال المدفأة"],"h1":"يعني أن تُبعد عينيك عن الطريق لتقرأ أو تكتب.","h2":"تمنع Alaska أي سائق من قراءة أو كتابة رسالة نصية أو أي رسالة مكتوبة أخرى على جهاز أثناء حركة المركبة، لأن ذلك يُبعد عينيك عن الطريق.","p":"صحيح. قراءة الرسائل أو كتابتها أثناء الحركة مخالفة للقانون."},"ref":{"doc":"AK","page":26}},{"id":"ak-028","scope":"AK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alaska, a driver age 21 or older is legally drunk at what blood alcohol level?","o":["0.10 percent or more","0.05 percent or more","0.12 percent or more","0.08 percent or more"],"h1":"It is less than one tenth of one percent.","h2":"A driver 21 or older with a blood alcohol level of 0.08 percent or more is considered to be driving under the influence.","p":"Right. The limit for adults is 0.08 percent."},"es":{"q":"En Alaska, ¿con qué nivel de alcohol en la sangre se considera legalmente ebrio a un conductor de 21 años o más?","o":["0.10 por ciento o más","0.05 por ciento o más","0.12 por ciento o más","0.08 por ciento o más"],"h1":"Es menos de una décima de uno por ciento.","h2":"Un conductor de 21 años o más con 0.08 por ciento o más de alcohol en la sangre se considera que maneja bajo la influencia del alcohol.","p":"Correcto. El límite para adultos es 0.08 por ciento."},"zh":{"q":"在 Alaska，21 岁或以上的司机，血液酒精浓度达到多少在法律上算醉酒？","o":["0.10% 或更高","0.05% 或更高","0.12% 或更高","0.08% 或更高"],"h1":"它不到百分之一的十分之一。","h2":"21 岁或以上的司机，血液酒精浓度达到 0.08% 或更高，就算是酒后驾驶。","p":"对。成年人的限制是 0.08%。"},"vi":{"q":"Ở Alaska, người lái xe từ 21 tuổi trở lên bị xem là say rượu theo luật ở mức nồng độ cồn trong máu nào?","o":["0.10 phần trăm trở lên","0.05 phần trăm trở lên","0.12 phần trăm trở lên","0.08 phần trăm trở lên"],"h1":"Nó ít hơn một phần mười của một phần trăm.","h2":"Người lái xe từ 21 tuổi trở lên có nồng độ cồn trong máu từ 0.08 phần trăm trở lên bị xem là lái xe khi say (driving under the influence).","p":"Đúng. Giới hạn cho người lớn là 0.08 phần trăm."},"tl":{"q":"Sa Alaska, ang driver na 21 taong gulang o higit pa ay legal na lasing sa anong antas ng alak sa dugo?","o":["0.10 porsiyento o higit pa","0.05 porsiyento o higit pa","0.12 porsiyento o higit pa","0.08 porsiyento o higit pa"],"h1":"Ito ay mas mababa sa ikasampung bahagi ng isang porsiyento.","h2":"Ang driver na 21 o higit pa na may blood alcohol level na 0.08 porsiyento o higit pa ay itinuturing na nagmamaneho nang lasing (driving under the influence).","p":"Tama. Ang limitasyon para sa mga adult ay 0.08 porsiyento."},"ar":{"q":"في Alaska، يُعتبر السائق الذي عمره 21 سنة أو أكثر سكرانًا قانونيًا عند أي نسبة كحول في الدم؟","o":["0.10 في المئة أو أكثر","0.05 في المئة أو أكثر","0.12 في المئة أو أكثر","0.08 في المئة أو أكثر"],"h1":"إنها أقل من عُشر واحد في المئة.","h2":"السائق الذي عمره 21 سنة أو أكثر ونسبة الكحول في دمه 0.08 في المئة أو أكثر يُعتبر أنه يقود تحت تأثير الكحول (driving under the influence).","p":"صحيح. الحد للبالغين هو 0.08 في المئة."},"ref":{"doc":"AK","page":16}},{"id":"ak-029","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, how much alcohol may a driver under 21 have in their body?","o":["Up to 0.08 percent","None that can be detected","Up to 0.05 percent","One drink per hour"],"h1":"This is called zero tolerance.","h2":"Alaska has zero tolerance for drivers under 21, so any amount of alcohol that a test can find in their body breaks the law.","p":"Right. Drivers under 21 may have no detectable alcohol."},"es":{"q":"En Alaska, ¿cuánto alcohol puede tener en el cuerpo un conductor menor de 21 años?","o":["Hasta 0.08 por ciento","Nada que se pueda detectar","Hasta 0.05 por ciento","Un trago por hora"],"h1":"Esto se llama tolerancia cero.","h2":"Alaska tiene tolerancia cero para conductores menores de 21 años, así que cualquier cantidad de alcohol que una prueba encuentre en su cuerpo viola la ley.","p":"Correcto. Los menores de 21 no pueden tener alcohol detectable."},"zh":{"q":"在 Alaska，21 岁以下的司机体内可以有多少酒精？","o":["最多 0.08%","不能有任何可以测出的酒精","最多 0.05%","每小时一杯"],"h1":"这叫做零容忍。","h2":"Alaska 对 21 岁以下的司机零容忍，所以只要检测能在他们体内测出任何酒精，就是违法。","p":"对。21 岁以下的司机不能有可以测出的酒精。"},"vi":{"q":"Ở Alaska, người lái xe dưới 21 tuổi được có bao nhiêu cồn trong cơ thể?","o":["Tối đa 0.08 phần trăm","Không có lượng nào đo được","Tối đa 0.05 phần trăm","Một ly mỗi giờ"],"h1":"Điều này gọi là không khoan nhượng (zero tolerance).","h2":"Alaska không khoan nhượng với người lái xe dưới 21 tuổi, vì vậy bất kỳ lượng cồn nào mà xét nghiệm tìm thấy trong cơ thể họ đều là phạm luật.","p":"Đúng. Người lái xe dưới 21 tuổi không được có lượng cồn nào đo được."},"tl":{"q":"Sa Alaska, gaano karaming alak ang puwedeng nasa katawan ng driver na wala pang 21?","o":["Hanggang 0.08 porsiyento","Wala na kayang makita ng test","Hanggang 0.05 porsiyento","Isang inumin bawat oras"],"h1":"Tinatawag itong zero tolerance.","h2":"May zero tolerance ang Alaska para sa mga driver na wala pang 21, kaya ang kahit anong dami ng alak na makita ng test sa kanilang katawan ay labag sa batas.","p":"Tama. Ang mga driver na wala pang 21 ay hindi puwedeng may alak na makikita ng test."},"ar":{"q":"في Alaska، كم من الكحول يجوز أن يكون في جسم السائق الذي عمره أقل من 21 سنة؟","o":["حتى 0.08 في المئة","لا شيء يمكن أن يكشفه الاختبار","حتى 0.05 في المئة","مشروب واحد في الساعة"],"h1":"هذا يُسمّى عدم التسامح مطلقًا (zero tolerance).","h2":"عند Alaska عدم تسامح مطلق مع السائقين الذين عمرهم أقل من 21 سنة، لذلك أي كمية من الكحول يجدها الاختبار في أجسامهم مخالفة للقانون.","p":"صحيح. لا يجوز أن يكون لدى السائقين تحت 21 سنة أي كحول يمكن كشفه."},"ref":{"doc":"AK","page":16}},{"id":"ak-030","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, what happens if a driver stopped for drunk driving refuses a breath test?","o":["Refusing is a separate crime with its own penalties","Nothing, because the test is optional","The driver gets a warning only","The driver must take a written test instead"],"h1":"By driving, you already agreed to be tested.","h2":"By driving in Alaska you have already agreed to be tested, so refusing the test is a separate crime, charged on top of drunk driving.","p":"Right. Refusing the test is a crime of its own."},"es":{"q":"En Alaska, ¿qué pasa si un conductor detenido por manejar ebrio se niega a la prueba de aliento?","o":["Negarse es un delito aparte con sus propias sanciones","Nada, porque la prueba es opcional","El conductor recibe solo una advertencia","El conductor debe hacer un examen escrito en su lugar"],"h1":"Al manejar, usted ya aceptó hacerse la prueba.","h2":"Al manejar en Alaska, usted ya aceptó hacerse la prueba, así que negarse es un delito aparte, que se suma al cargo por manejar ebrio.","p":"Correcto. Negarse a la prueba es un delito aparte."},"zh":{"q":"在 Alaska，因为酒后驾驶被拦下的司机如果拒绝呼气检测，会怎么样？","o":["拒绝本身就是另一项罪，有自己的处罚","没事，因为检测是自愿的","司机只会收到警告","司机必须改考笔试"],"h1":"你开车，就表示你已经同意接受检测。","h2":"在 Alaska 开车，就表示你已经同意接受检测，所以拒绝检测是另一项罪，会在酒后驾驶之外另外起诉。","p":"对。拒绝检测本身就是一项罪。"},"vi":{"q":"Ở Alaska, điều gì xảy ra nếu người lái xe bị dừng vì lái xe khi say từ chối thử hơi thở?","o":["Từ chối là một tội riêng với hình phạt riêng","Không có gì, vì việc thử là không bắt buộc","Người lái xe chỉ bị cảnh cáo","Người lái xe phải làm bài thi viết thay thế"],"h1":"Khi lái xe, bạn đã đồng ý cho kiểm tra.","h2":"Khi lái xe ở Alaska, bạn đã đồng ý cho kiểm tra, vì vậy từ chối thử là một tội riêng, bị truy tố thêm ngoài tội lái xe khi say.","p":"Đúng. Từ chối thử là một tội riêng."},"tl":{"q":"Sa Alaska, ano ang mangyayari kung tumanggi sa breath test ang driver na pinahinto dahil sa pagmamaneho nang lasing?","o":["Ang pagtanggi ay hiwalay na krimen na may sariling parusa","Wala, dahil hindi sapilitan ang test","Babala lamang ang ibibigay sa driver","Kailangang kumuha ang driver ng written test sa halip"],"h1":"Sa pagmamaneho, pumayag ka na na ma-test.","h2":"Sa pagmamaneho sa Alaska, pumayag ka na na ma-test, kaya ang pagtanggi sa test ay hiwalay na krimen, na isinasampa bukod pa sa pagmamaneho nang lasing.","p":"Tama. Ang pagtanggi sa test ay sariling krimen."},"ar":{"q":"في Alaska، ماذا يحدث إذا رفض سائق أُوقف بسبب القيادة تحت تأثير الكحول اختبار التنفس؟","o":["الرفض جريمة منفصلة لها عقوباتها الخاصة","لا شيء، لأن الاختبار اختياري","يحصل السائق على تحذير فقط","يجب أن يقدّم السائق اختبارًا كتابيًا بدلًا منه"],"h1":"بمجرد أن تقود، أنت وافقت مسبقًا على الاختبار.","h2":"بمجرد أن تقود في Alaska فأنت وافقت مسبقًا على الاختبار، لذلك رفض الاختبار جريمة منفصلة، تُضاف إلى تهمة القيادة تحت تأثير الكحول.","p":"صحيح. رفض الاختبار جريمة قائمة بذاتها."},"ref":{"doc":"AK","page":14}},{"id":"ak-031","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, what is the minimum liability insurance a car owner must carry?","o":["$15,000 / $30,000 / $10,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $25,000","$100,000 / $300,000 / $100,000"],"h1":"Alaska asks for more than many states for injuries.","h2":"Alaska requires at least $50,000 for injury to one person, $100,000 for injuries in one crash, and $25,000 for property damage.","p":"Right. Alaska minimums are 50/100/25."},"es":{"q":"En Alaska, ¿cuál es el seguro mínimo de responsabilidad que debe tener el dueño de un carro?","o":["$15,000 / $30,000 / $10,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $25,000","$100,000 / $300,000 / $100,000"],"h1":"Alaska pide más que muchos estados para lesiones.","h2":"Alaska exige por lo menos $50,000 por lesiones a una persona, $100,000 por lesiones en un choque y $25,000 por daños a la propiedad.","p":"Correcto. Los mínimos en Alaska son 50/100/25."},"zh":{"q":"在 Alaska，车主必须买的最低责任保险是多少？","o":["$15,000 / $30,000 / $10,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $25,000","$100,000 / $300,000 / $100,000"],"h1":"在人身伤害方面，Alaska 要求的比很多州都多。","h2":"Alaska 要求一个人受伤至少 $50,000，一次车祸的人身伤害至少 $100,000，财产损失至少 $25,000。","p":"对。Alaska 的最低标准是 50/100/25。"},"vi":{"q":"Ở Alaska, chủ xe phải có bảo hiểm trách nhiệm (liability insurance) tối thiểu là bao nhiêu?","o":["$15,000 / $30,000 / $10,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $25,000","$100,000 / $300,000 / $100,000"],"h1":"Alaska yêu cầu mức bảo hiểm thương tích cao hơn nhiều tiểu bang khác.","h2":"Alaska yêu cầu ít nhất $50,000 cho thương tích của một người, $100,000 cho thương tích trong một vụ tai nạn, và $25,000 cho thiệt hại tài sản.","p":"Đúng. Mức tối thiểu ở Alaska là 50/100/25."},"tl":{"q":"Sa Alaska, ano ang pinakamababang liability insurance na dapat mayroon ang may-ari ng kotse?","o":["$15,000 / $30,000 / $10,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $25,000","$100,000 / $300,000 / $100,000"],"h1":"Mas mataas ang hinihingi ng Alaska para sa pinsala sa tao kaysa sa maraming estado.","h2":"Hinihingi ng Alaska ang hindi bababa sa $50,000 para sa pinsala sa isang tao, $100,000 para sa mga pinsala sa isang aksidente, at $25,000 para sa pinsala sa ari-arian.","p":"Tama. Ang minimum sa Alaska ay 50/100/25."},"ar":{"q":"في Alaska، ما الحد الأدنى من تأمين المسؤولية (liability insurance) الذي يجب أن يملكه صاحب السيارة؟","o":["$15,000 / $30,000 / $10,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $25,000","$100,000 / $300,000 / $100,000"],"h1":"تطلب Alaska مبلغًا للإصابات أكبر من ولايات كثيرة.","h2":"تطلب Alaska على الأقل $50,000 لإصابة شخص واحد، و$100,000 للإصابات في حادث واحد، و$25,000 لأضرار الممتلكات.","p":"صحيح. الحد الأدنى في Alaska هو 50/100/25."},"ref":{"doc":"AK","page":10}},{"id":"ak-032","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, how many points within 12 months lead to a required suspension of your license?","o":["6 points","8 points","12 points","15 points"],"h1":"Over 24 months the limit is higher than over 12 months.","h2":"In Alaska, 12 points in 12 months, or 18 points in 24 months, means your license must be suspended or revoked.","p":"Right. 12 points in 12 months brings a required suspension."},"es":{"q":"En Alaska, ¿cuántos puntos en 12 meses llevan a una suspensión obligatoria de su licencia?","o":["6 puntos","8 puntos","12 puntos","15 puntos"],"h1":"En 24 meses el límite es más alto que en 12 meses.","h2":"En Alaska, 12 puntos en 12 meses, o 18 puntos en 24 meses, significa que su licencia debe ser suspendida o revocada.","p":"Correcto. 12 puntos en 12 meses llevan a una suspensión obligatoria."},"ref":{"doc":"AK","page":11}},{"id":"ak-033","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, a driver with a provisional license gets 6 points in 12 months. What must the driver do?","o":["Complete a driver improvement course","Retake the vision test","Pay a $500 fine","Start a new instruction permit"],"h1":"The goal is to help the young driver build better habits.","h2":"In Alaska, a provisional driver with 6 or more points in 12 months, or 9 or more in 24 months, must complete a driver improvement course approved by the DMV.","p":"Right. The provisional driver must take a driver improvement course."},"es":{"q":"En Alaska, un conductor con licencia provisional acumula 6 puntos en 12 meses. ¿Qué debe hacer?","o":["Completar un curso para mejorar su manejo","Repetir el examen de la vista","Pagar una multa de $500","Empezar con un nuevo permiso de aprendizaje"],"h1":"La meta es ayudar al conductor joven a formar mejores hábitos.","h2":"En Alaska, un conductor provisional con 6 puntos o más en 12 meses, o 9 o más en 24 meses, debe completar un curso para mejorar su manejo aprobado por el DMV.","p":"Correcto. El conductor provisional debe tomar un curso para mejorar su manejo."},"ref":{"doc":"AK","page":11}},{"id":"ak-034","scope":"AK","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Alaska, how many points are added to your record for driving 10 to 19 mph over the speed limit?","o":["2 points","3 points","6 points","4 points"],"h1":"It is more than for 3 to 9 mph over, and less than for 20 mph or more over.","h2":"In Alaska, driving 10 to 19 mph over the speed limit adds 4 points to your driving record.","p":"Right. 10 to 19 mph over the limit is 4 points."},"es":{"q":"En Alaska, ¿cuántos puntos se agregan a su historial por manejar de 10 a 19 mph sobre el límite de velocidad?","o":["2 puntos","3 puntos","6 puntos","4 puntos"],"h1":"Es más que por ir de 3 a 9 mph sobre el límite, y menos que por ir 20 mph o más.","h2":"En Alaska, manejar de 10 a 19 mph sobre el límite de velocidad agrega 4 puntos a su historial de manejo.","p":"Correcto. De 10 a 19 mph sobre el límite son 4 puntos."},"ref":{"doc":"AK","page":12}},{"id":"ak-035","scope":"AK","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Alaska, no police officer investigated your crash. How soon must you report it to the DMV?","o":["Within 24 hours","Within 10 days","Within 30 days","Within 6 months"],"h1":"You can send the report online or by mail.","h2":"In Alaska, if a police officer did not investigate your crash, you must report it to the DMV within 10 days.","p":"Right. Report the crash to the DMV within 10 days."},"es":{"q":"En Alaska, ningún policía investigó su choque. ¿En cuánto tiempo debe reportarlo al DMV?","o":["En 24 horas","En 10 días","En 30 días","En 6 meses"],"h1":"Puede enviar el reporte por internet o por correo.","h2":"En Alaska, si un policía no investigó su choque, usted debe reportarlo al DMV en un plazo de 10 días.","p":"Correcto. Reporte el choque al DMV en 10 días."},"ref":{"doc":"AK","page":11}},{"id":"ak-036","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, after a crash where someone was hurt, how many days do you have to give the DMV proof of insurance?","o":["3 days","7 days","15 days","60 days"],"h1":"Every driver in the crash must send it, even the one who did not cause it.","h2":"In Alaska, after a crash with an injury, every driver involved must give the DMV proof of insurance within 15 days.","p":"Right. Every driver must send proof of insurance within 15 days."},"es":{"q":"En Alaska, después de un choque donde alguien resultó herido, ¿cuántos días tiene para dar al DMV prueba de seguro?","o":["3 días","7 días","15 días","60 días"],"h1":"Cada conductor del choque debe enviarla, aunque no haya causado el choque.","h2":"En Alaska, después de un choque con heridos, cada conductor involucrado debe dar al DMV prueba de seguro en un plazo de 15 días.","p":"Correcto. Cada conductor debe enviar prueba de seguro en 15 días."},"ref":{"doc":"AK","page":10}},{"id":"ak-037","scope":"AK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alaska, you had no insurance when you were in a crash. For a first time, how long is your license suspended?","o":["30 days","1 year","3 years","90 days"],"h1":"A second time brings a longer suspension.","h2":"In Alaska, a driver who was uninsured in a crash has the license suspended for 90 days the first time and 1 year the second time.","p":"Right. The first time, the suspension is 90 days."},"es":{"q":"En Alaska, usted no tenía seguro cuando tuvo un choque. Si es la primera vez, ¿por cuánto tiempo suspenden su licencia?","o":["30 días","1 año","3 años","90 días"],"h1":"Una segunda vez trae una suspensión más larga.","h2":"En Alaska, a un conductor sin seguro en un choque le suspenden la licencia por 90 días la primera vez y por 1 año la segunda vez.","p":"Correcto. La primera vez, la suspensión es de 90 días."},"ref":{"doc":"AK","page":10}},{"id":"ak-038","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, a driver with no past DUI is arrested and the breath test shows 0.08 or more. How long will the DMV revoke the license?","o":["90 days","30 days","3 years","5 years"],"h1":"The longer periods are for drivers with earlier DUI or refusal convictions.","h2":"In Alaska, the DMV revokes the license for 90 days for a first offense when a driver tests at 0.08 or more or refuses the test.","p":"Right. A first offense means a 90-day revocation by the DMV."},"es":{"q":"En Alaska, arrestan a un conductor sin DUI anteriores y la prueba de aliento muestra 0.08 o más. ¿Por cuánto tiempo revocará el DMV su licencia?","o":["90 días","30 días","3 años","5 años"],"h1":"Los periodos más largos son para conductores con condenas anteriores por DUI o por negarse a la prueba.","h2":"En Alaska, el DMV revoca la licencia por 90 días en una primera ofensa cuando el conductor marca 0.08 o más o se niega a la prueba.","p":"Correcto. Una primera ofensa significa que el DMV revoca la licencia por 90 días."},"ref":{"doc":"AK","page":16}},{"id":"ak-039","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, a driver under 21 is caught driving after drinking alcohol. For a first offense, how long does the DMV revoke the license?","o":["7 days","30 days","2 years","5 years"],"h1":"The period gets longer with each new offense.","h2":"In Alaska, a driver under 21 who drives after drinking any alcohol loses the license for 30 days for a first offense, even if the court case is dropped.","p":"Right. A first offense means a 30-day revocation."},"es":{"q":"En Alaska, encuentran a un conductor menor de 21 años manejando después de tomar alcohol. En una primera ofensa, ¿por cuánto tiempo revoca el DMV su licencia?","o":["7 días","30 días","2 años","5 años"],"h1":"El periodo se alarga con cada nueva ofensa.","h2":"En Alaska, un conductor menor de 21 años que maneja después de tomar cualquier cantidad de alcohol pierde la licencia por 30 días en una primera ofensa, aunque se cierre el caso en la corte.","p":"Correcto. Una primera ofensa significa una revocación de 30 días."},"ref":{"doc":"AK","page":16}},{"id":"ak-040","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, after a first DUI conviction, how long must an ignition interlock device be on any vehicle you drive?","o":["1 month","3 months","At least 6 months","10 years"],"h1":"The time grows with each extra conviction.","h2":"In Alaska, after a first DUI or refusal conviction, you must use an ignition interlock device on any vehicle you drive for at least 6 months.","p":"Right. A first conviction means at least 6 months with the device."},"es":{"q":"En Alaska, después de una primera condena por DUI, ¿por cuánto tiempo debe tener un dispositivo de bloqueo de encendido en cualquier vehículo que maneje?","o":["1 mes","3 meses","Por lo menos 6 meses","10 años"],"h1":"El tiempo aumenta con cada condena adicional.","h2":"En Alaska, después de una primera condena por DUI o por negarse a la prueba, debe usar un dispositivo de bloqueo de encendido en cualquier vehículo que maneje por lo menos 6 meses.","p":"Correcto. Una primera condena significa por lo menos 6 meses con el dispositivo."},"ref":{"doc":"AK","page":19}},{"id":"ak-041","scope":"AK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alaska, if you get your driver license before age 21, when does it expire?","o":["On your 18th birthday","One year after you get it","On your 25th birthday","90 days after your 21st birthday"],"h1":"It is tied to the age when you may legally drink.","h2":"In Alaska, a license issued to someone under 21 expires 90 days after the 21st birthday, and you must pass an alcohol awareness test to renew it.","p":"Right. It expires 90 days after your 21st birthday."},"es":{"q":"En Alaska, si obtiene su licencia de manejar antes de los 21 años, ¿cuándo vence?","o":["El día que cumple 18 años","Un año después de recibirla","El día que cumple 25 años","90 días después de cumplir 21 años"],"h1":"Está ligado a la edad en que se puede tomar alcohol legalmente.","h2":"En Alaska, una licencia dada a alguien menor de 21 años vence 90 días después de cumplir 21, y para renovarla debe pasar un examen sobre el alcohol.","p":"Correcto. Vence 90 días después de cumplir 21 años."},"ref":{"doc":"AK","page":5}},{"id":"ak-042","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, what is the minimum vision needed for a license, in each eye or with both eyes together?","o":["20/40","20/80","20/100","20/200"],"h1":"You may wear glasses or contact lenses to reach it.","h2":"In Alaska, you need at least 20/40 vision in each eye or with both eyes together, and if you need lenses to pass, you must wear them when you drive.","p":"Right. The standard is 20/40."},"es":{"q":"En Alaska, ¿cuál es la vista mínima para tener licencia, en cada ojo o con los dos ojos juntos?","o":["20/40","20/80","20/100","20/200"],"h1":"Puede usar lentes o lentes de contacto para lograrla.","h2":"En Alaska, necesita por lo menos una vista de 20/40 en cada ojo o con los dos ojos juntos, y si necesita lentes para pasar, debe usarlos al manejar.","p":"Correcto. El mínimo es 20/40."},"ref":{"doc":"AK","page":6}},{"id":"ak-043","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, you failed the written knowledge test. When may you take it again?","o":["After 30 days","The next day","After one week","After six months"],"h1":"Study the manual again first; you will not wait long.","h2":"In Alaska, if you fail the written test, you may take it again the following day.","p":"Right. You may retake it the next day."},"es":{"q":"En Alaska, usted no pasó el examen escrito de conocimientos. ¿Cuándo puede tomarlo otra vez?","o":["Después de 30 días","Al día siguiente","Después de una semana","Después de seis meses"],"h1":"Estudie el manual otra vez primero; no tendrá que esperar mucho.","h2":"En Alaska, si no pasa el examen escrito, puede tomarlo otra vez al día siguiente.","p":"Correcto. Puede repetirlo al día siguiente."},"ref":{"doc":"AK","page":7}},{"id":"ak-044","scope":"AK","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Alaska, a child is younger than 1 year old. How must the child ride in a car?","o":["In a booster seat","On an adult's lap","In a rear-facing child safety seat","With only the car's seat belt"],"h1":"Babies need a seat that protects the head and neck in a crash.","h2":"In Alaska, a child under 1 year old, or any child who weighs less than 20 pounds, must ride in a rear-facing child safety seat.","p":"Right. A baby under 1 rides in a rear-facing seat."},"es":{"q":"En Alaska, un niño tiene menos de 1 año. ¿Cómo debe viajar en el carro?","o":["En un asiento elevado (booster)","En las piernas de un adulto","En un asiento de seguridad mirando hacia atrás","Solo con el cinturón del carro"],"h1":"Los bebés necesitan un asiento que proteja la cabeza y el cuello en un choque.","h2":"En Alaska, un niño menor de 1 año, o cualquier niño que pese menos de 20 libras, debe viajar en un asiento de seguridad mirando hacia atrás.","p":"Correcto. Un bebé menor de 1 año viaja en un asiento mirando hacia atrás."},"ref":{"doc":"AK","page":21}},{"id":"ak-045","scope":"AK","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Alaska, you are driving at night with high beams on. A car is coming toward you. At what distance must you switch to low beams?","o":["100 feet","200 feet","2,000 feet","500 feet"],"h1":"The rule for a car coming toward you is longer than for a car you follow.","h2":"In Alaska, you must dim to low beams when you are 500 feet or more from an oncoming vehicle, and 300 feet from a vehicle you are following.","p":"Right. Dim your lights at 500 feet from oncoming traffic."},"es":{"q":"En Alaska, maneja de noche con las luces altas. Viene un carro de frente. ¿A qué distancia debe cambiar a luces bajas?","o":["100 pies","200 pies","2,000 pies","500 pies"],"h1":"La regla para un carro que viene de frente es más larga que para un carro que usted sigue.","h2":"En Alaska, debe cambiar a luces bajas cuando está a 500 pies o más de un vehículo que viene de frente, y a 300 pies de un vehículo que va delante de usted.","p":"Correcto. Baje las luces a 500 pies del tráfico que viene de frente."},"ref":{"doc":"AK","page":55}},{"id":"ak-046","scope":"AK","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Alaska, how far from a railroad crossing must you park, at the least?","o":["50 feet","10 feet","20 feet","5 feet"],"h1":"It is the longest of the usual parking distances, after the one for a stopped fire truck.","h2":"In Alaska, you may not park closer than 50 feet to a railroad crossing.","p":"Right. Park at least 50 feet from a railroad crossing."},"es":{"q":"En Alaska, ¿a qué distancia mínima de un cruce de tren debe estacionarse?","o":["50 pies","10 pies","20 pies","5 pies"],"h1":"Es la más larga de las distancias comunes para estacionar, después de la de un camión de bomberos detenido.","h2":"En Alaska, no puede estacionarse a menos de 50 pies de un cruce de tren.","p":"Correcto. Estaciónese por lo menos a 50 pies de un cruce de tren."},"ref":{"doc":"AK","page":62}},{"id":"ak-047","scope":"AK","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Alaska, a fire truck is going to an emergency. If you are driving behind it, how far back must you stay?","o":["100 feet","500 feet","50 feet","200 feet"],"h1":"It is the same distance as the no-parking zone near a stopped fire truck.","h2":"In Alaska, you may not follow an emergency vehicle that is responding to an emergency closer than 500 feet.","p":"Right. Stay at least 500 feet behind it."},"es":{"q":"En Alaska, un camión de bomberos va a una emergencia. Si usted maneja detrás de él, ¿a qué distancia debe mantenerse?","o":["100 pies","500 pies","50 pies","200 pies"],"h1":"Es la misma distancia de la zona donde no se puede estacionar cerca de un camión de bomberos detenido.","h2":"En Alaska, no puede seguir a un vehículo de emergencia que va a una emergencia a menos de 500 pies.","p":"Correcto. Manténgase por lo menos a 500 pies detrás."},"ref":{"doc":"AK","page":64}},{"id":"ak-048","scope":"AK","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Alaska, what happens to fines for traffic offenses inside a Traffic Safety Corridor?","o":["They are cut in half","They stay the same","They are doubled","They are tripled"],"h1":"These stretches of highway get extra protection.","h2":"In Alaska, fines for traffic offenses in a Traffic Safety Corridor are doubled.","p":"Right. Fines are doubled in a Traffic Safety Corridor."},"es":{"q":"En Alaska, ¿qué pasa con las multas por infracciones de tránsito dentro de un Traffic Safety Corridor (corredor de seguridad vial)?","o":["Se reducen a la mitad","Siguen iguales","Se duplican","Se triplican"],"h1":"Estos tramos de carretera tienen protección adicional.","h2":"En Alaska, las multas por infracciones de tránsito en un Traffic Safety Corridor se duplican.","p":"Correcto. Las multas se duplican en un Traffic Safety Corridor."},"ref":{"doc":"AK","page":29}},{"id":"ak-049","scope":"AK","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Alaska, your car hits a moose and kills or injures it. What must you do?","o":["Keep the animal for its meat","Drive on if your car still works","Call only your insurance company","Tell a State Trooper or wildlife officer soon"],"h1":"Big game animals hit on the road belong to the state.","h2":"In Alaska, if you kill or injure a big game animal with your vehicle, you must tell a State Trooper or a Fish and Wildlife officer as soon as possible.","p":"Right. Tell a State Trooper or wildlife officer as soon as you can."},"es":{"q":"En Alaska, su carro choca con un alce y lo mata o lo hiere. ¿Qué debe hacer?","o":["Quedarse con el animal por su carne","Seguir manejando si el carro funciona","Llamar solo a su compañía de seguros","Avisar pronto a un State Trooper o agente de vida silvestre"],"h1":"Los animales de caza mayor atropellados en la carretera son del estado.","h2":"En Alaska, si mata o hiere a un animal de caza mayor con su vehículo, debe avisar a un State Trooper o a un agente de Fish and Wildlife lo antes posible.","p":"Correcto. Avise a un State Trooper o agente de vida silvestre lo antes posible."},"ref":{"doc":"AK","page":60}},{"id":"ak-050","scope":"AK","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Alaska, which parts of the road usually become slippery first in freezing weather and stay slippery longer?","o":["Bridges and shaded areas","Sunny, straight stretches","Busy streets in town","Newly paved roads"],"h1":"Think of places where cold air or shade reaches the road surface more.","h2":"In Alaska, bridges, shaded spots and protected areas become slippery before the rest of the road and stay slippery longer.","p":"Right. Watch bridges and shaded areas for ice."},"es":{"q":"En Alaska, cuando hay heladas, ¿qué partes de la carretera suelen ponerse resbalosas primero y siguen así por más tiempo?","o":["Los puentes y las zonas con sombra","Los tramos rectos y soleados","Las calles con mucho tráfico en la ciudad","Las carreteras recién pavimentadas"],"h1":"Piense en lugares donde el aire frío o la sombra llegan más a la superficie.","h2":"En Alaska, los puentes, las zonas con sombra y las áreas protegidas se ponen resbalosas antes que el resto de la carretera y siguen así por más tiempo.","p":"Correcto. Tenga cuidado con el hielo en puentes y zonas con sombra."},"ref":{"doc":"AK","page":61}},{"id":"ak-051","scope":"AK","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Alaska, why does the driver manual say to keep your fuel tank full in cold weather?","o":["To make the heater work faster","To keep moisture from forming in the tank","To make the car heavier on ice","To pass the vehicle inspection"],"h1":"Cold air inside an almost empty tank can leave water behind.","h2":"In Alaska, keeping your fuel tank full in cold weather helps stop moisture from condensing inside the tank.","p":"Right. A full tank keeps moisture from forming inside."},"es":{"q":"En Alaska, ¿por qué dice el manual que mantenga lleno el tanque de gasolina cuando hace frío?","o":["Para que la calefacción funcione más rápido","Para evitar que se forme humedad en el tanque","Para que el carro pese más sobre el hielo","Para pasar la inspección del vehículo"],"h1":"El aire frío dentro de un tanque casi vacío puede dejar agua.","h2":"En Alaska, mantener lleno el tanque de gasolina cuando hace frío ayuda a evitar que se condense humedad dentro del tanque.","p":"Correcto. Un tanque lleno evita que se forme humedad adentro."},"ref":{"doc":"AK","page":59}},{"id":"al-001","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, what is the youngest age to get a Stage I learner license?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It comes one year before the age when teens can start driving alone.","h2":"In Alabama you can get a Stage I learner license at age 15, so you can practice for a year before you may drive alone at 16.","p":"Right. The Alabama learner license starts at age 15."},"es":{"q":"En Alabama, ¿cuál es la edad mínima para obtener la licencia de aprendiz Etapa I?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la edad en que los jóvenes pueden empezar a manejar solos.","h2":"En Alabama usted puede obtener la licencia de aprendiz Etapa I a los 15 años, para practicar un año antes de poder manejar solo a los 16.","p":"Correcto. La licencia de aprendiz en Alabama empieza a los 15 años."},"zh":{"q":"在 Alabama，最小几岁可以拿到 Stage I 学习驾照？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比青少年可以开始单独开车的年龄早一年。","h2":"在 Alabama，你 15 岁就可以拿到 Stage I 学习驾照，这样你可以练习一年，16 岁时才可以单独开车。","p":"对。Alabama 的学习驾照从 15 岁开始。"},"vi":{"q":"Ở Alabama, tuổi nhỏ nhất để được cấp giấy phép tập lái Giai đoạn I (Stage I learner license) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là một năm trước tuổi thanh thiếu niên được bắt đầu lái xe một mình.","h2":"Ở Alabama, bạn có thể được cấp giấy phép tập lái Giai đoạn I khi 15 tuổi, để bạn có một năm tập lái trước khi được lái một mình lúc 16 tuổi.","p":"Đúng. Giấy phép tập lái ở Alabama bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Alabama, ano ang pinakabatang edad para makakuha ng Stage I learner license?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ang edad kung kailan puwede nang magmaneho nang mag-isa ang mga kabataan.","h2":"Sa Alabama, puwede kang kumuha ng Stage I learner license sa edad na 15, kaya puwede kang magsanay nang isang taon bago ka puwedeng magmaneho nang mag-isa sa edad na 16.","p":"Tama. Nagsisimula ang learner license ng Alabama sa edad na 15."},"ar":{"q":"في Alabama، ما أصغر سن للحصول على رخصة تعلّم المرحلة الأولى (Stage I learner license)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"تأتي قبل سنة واحدة من السن التي يبدأ فيها المراهقون القيادة وحدهم.","h2":"في Alabama يمكنك الحصول على رخصة تعلّم المرحلة الأولى في سن 15، لتتدرّب سنة كاملة قبل أن يُسمح لك بالقيادة وحدك في سن 16.","p":"صحيح. رخصة التعلّم في Alabama تبدأ من سن 15."},"ref":{"doc":"AL","page":9}},{"id":"al-002","scope":"AL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alabama, who may sit beside a 15-year-old with a Stage I learner license while they drive?","o":["Any friend who has a license","Any passenger age 16 or older","A licensed driver age 18 or older","A parent, guardian, or licensed driver age 21+"],"h1":"The helper must be an experienced adult, not a young friend.","h2":"A 15-year-old Alabama learner must drive with a parent, a legal guardian, or a licensed driver who is at least 21 in the front seat, because a new driver needs an experienced adult close by.","p":"Right. The person beside you is a parent, guardian, or licensed driver age 21 or older."},"es":{"q":"En Alabama, ¿quién puede ir sentado al lado de un joven de 15 años con licencia de aprendiz Etapa I mientras maneja?","o":["Cualquier amigo que tenga licencia","Cualquier pasajero de 16 años o más","Un conductor con licencia de 18 años o más","Un padre, tutor o conductor con licencia de 21+"],"h1":"El acompañante debe ser un adulto con experiencia, no un amigo joven.","h2":"En Alabama un aprendiz de 15 años debe manejar con un padre, un tutor legal o un conductor con licencia de por lo menos 21 años en el asiento delantero, porque un conductor nuevo necesita a un adulto con experiencia a su lado.","p":"Correcto. A su lado va un padre, un tutor o un conductor con licencia de 21 años o más."},"zh":{"q":"在 Alabama，持 Stage I 学习驾照的 15 岁司机开车时，谁可以坐在他旁边？","o":["任何有驾照的朋友","任何 16 岁或以上的乘客","18 岁或以上、有驾照的司机","父母、监护人，或 21 岁或以上、有驾照的司机"],"h1":"陪同的人必须是有经验的成年人，不是年轻的朋友。","h2":"Alabama 15 岁的学习驾驶的人开车时，前排必须坐着父母、法定监护人，或至少 21 岁、有驾照的司机，因为新司机需要一位有经验的成年人在身边。","p":"对。坐在你旁边的人是父母、监护人，或 21 岁或以上、有驾照的司机。"},"vi":{"q":"Ở Alabama, ai được ngồi bên cạnh một người 15 tuổi có giấy phép tập lái Giai đoạn I khi người đó lái xe?","o":["Bất kỳ người bạn nào có bằng lái","Bất kỳ hành khách nào từ 16 tuổi trở lên","Người có bằng lái từ 18 tuổi trở lên","Cha mẹ, người giám hộ, hoặc người có bằng lái từ 21 tuổi"],"h1":"Người hướng dẫn phải là người lớn có kinh nghiệm, không phải một người bạn trẻ.","h2":"Người tập lái 15 tuổi ở Alabama phải lái xe với cha mẹ, người giám hộ hợp pháp, hoặc người có bằng lái ít nhất 21 tuổi ngồi ở ghế trước, vì người mới lái cần một người lớn có kinh nghiệm ở gần.","p":"Đúng. Người ngồi bên cạnh bạn là cha mẹ, người giám hộ, hoặc người có bằng lái từ 21 tuổi trở lên."},"tl":{"q":"Sa Alabama, sino ang puwedeng umupo sa tabi ng isang 15 taong gulang na may Stage I learner license habang siya ay nagmamaneho?","o":["Sinumang kaibigan na may lisensya","Sinumang pasahero na 16 taong gulang pataas","Isang may lisensyang drayber na 18 pataas","Magulang, tagapag-alaga, o may lisensyang drayber na 21+"],"h1":"Ang katulong ay dapat isang may karanasang adult, hindi isang batang kaibigan.","h2":"Ang 15 taong gulang na learner sa Alabama ay dapat magmaneho kasama ang magulang, legal na tagapag-alaga, o may lisensyang drayber na hindi bababa sa 21 taong gulang sa upuan sa harap, dahil kailangan ng bagong drayber ang isang may karanasang adult sa malapit.","p":"Tama. Ang katabi mo ay magulang, tagapag-alaga, o may lisensyang drayber na 21 taong gulang pataas."},"ar":{"q":"في Alabama، من يجوز له الجلوس بجانب شخص عمره 15 سنة يحمل رخصة تعلّم المرحلة الأولى أثناء قيادته؟","o":["أي صديق لديه رخصة","أي راكب عمره 16 سنة أو أكثر","سائق مرخّص عمره 18 سنة أو أكثر","أحد الوالدين أو وليّ أمر أو سائق مرخّص عمره 21+"],"h1":"يجب أن يكون المرافق شخصًا بالغًا ذا خبرة، لا صديقًا صغيرًا.","h2":"يجب على المتعلّم في Alabama الذي عمره 15 سنة أن يقود مع أحد الوالدين أو وليّ أمر قانوني أو سائق مرخّص عمره 21 سنة على الأقل في المقعد الأمامي، لأن السائق الجديد يحتاج إلى شخص بالغ ذي خبرة بالقرب منه.","p":"صحيح. الشخص بجانبك هو أحد الوالدين أو وليّ أمر أو سائق مرخّص عمره 21 سنة أو أكثر."},"ref":{"doc":"AL","page":9}},{"id":"al-003","scope":"AL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alabama, a driver under 18 must hold a Stage I learner license for how long before applying for Stage II?","o":["At least 1 month","At least 3 months","At least 6 months","At least 12 months"],"h1":"It is half a year.","h2":"In Alabama a driver under 18 must hold the Stage I license for at least six months before applying for Stage II, so there is time to practice with an adult.","p":"Right. Hold the learner license for at least six months first."},"es":{"q":"En Alabama, un conductor menor de 18 años debe tener la licencia de aprendiz Etapa I, ¿por cuánto tiempo antes de solicitar la Etapa II?","o":["Por lo menos 1 mes","Por lo menos 3 meses","Por lo menos 6 meses","Por lo menos 12 meses"],"h1":"Es medio año.","h2":"En Alabama un conductor menor de 18 años debe tener la licencia de Etapa I por lo menos seis meses antes de solicitar la Etapa II, para tener tiempo de practicar con un adulto.","p":"Correcto. Primero debe tener la licencia de aprendiz por lo menos seis meses."},"zh":{"q":"在 Alabama，18 岁以下的司机必须持有 Stage I 学习驾照多久，才能申请 Stage II？","o":["至少 1 个月","至少 3 个月","至少 6 个月","至少 12 个月"],"h1":"它是半年。","h2":"在 Alabama，18 岁以下的司机必须持有 Stage I 驾照至少六个月，才能申请 Stage II，这样才有时间和成年人一起练习。","p":"对。先持有学习驾照至少六个月。"},"vi":{"q":"Ở Alabama, người lái dưới 18 tuổi phải giữ giấy phép tập lái Giai đoạn I bao lâu trước khi xin Giai đoạn II?","o":["Ít nhất 1 tháng","Ít nhất 3 tháng","Ít nhất 6 tháng","Ít nhất 12 tháng"],"h1":"Đó là nửa năm.","h2":"Ở Alabama, người lái dưới 18 tuổi phải giữ giấy phép Giai đoạn I ít nhất sáu tháng trước khi xin Giai đoạn II, để có thời gian tập lái với người lớn.","p":"Đúng. Trước tiên hãy giữ giấy phép tập lái ít nhất sáu tháng."},"tl":{"q":"Sa Alabama, gaano katagal dapat hawak ng drayber na wala pang 18 ang Stage I learner license bago mag-apply para sa Stage II?","o":["Hindi bababa sa 1 buwan","Hindi bababa sa 3 buwan","Hindi bababa sa 6 na buwan","Hindi bababa sa 12 buwan"],"h1":"Kalahating taon ito.","h2":"Sa Alabama, ang drayber na wala pang 18 ay dapat humawak ng Stage I license nang hindi bababa sa anim na buwan bago mag-apply para sa Stage II, para may oras siyang magsanay kasama ang isang adult.","p":"Tama. Hawakan muna ang learner license nang hindi bababa sa anim na buwan."},"ar":{"q":"في Alabama، كم يجب أن يحمل السائق الذي عمره أقل من 18 سنة رخصة تعلّم المرحلة الأولى قبل أن يتقدّم للمرحلة الثانية؟","o":["شهر واحد على الأقل","3 أشهر على الأقل","6 أشهر على الأقل","12 شهرًا على الأقل"],"h1":"إنها نصف سنة.","h2":"في Alabama يجب على السائق الذي عمره أقل من 18 سنة أن يحمل رخصة المرحلة الأولى ستة أشهر على الأقل قبل أن يتقدّم للمرحلة الثانية، ليكون لديه وقت للتدرّب مع شخص بالغ.","p":"صحيح. احمل رخصة التعلّم ستة أشهر على الأقل أولًا."},"ref":{"doc":"AL","page":10}},{"id":"al-004","scope":"AL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alabama, a Stage II (restricted) driver may carry how many passengers who are not parents, guardians, or family members?","o":["No more than one","No more than two","No more than three","Any number with seat belts"],"h1":"The limit is the smallest number above zero.","h2":"An Alabama Stage II driver may not carry more than one passenger besides parents, legal guardians, or family members, because friends in the car raise the risk of a crash for new drivers.","p":"Right. Only one passenger who is not family."},"es":{"q":"En Alabama, un conductor de Etapa II (restringida), ¿cuántos pasajeros puede llevar que no sean padres, tutores ni familiares?","o":["No más de uno","No más de dos","No más de tres","Cualquier número con cinturón"],"h1":"El límite es el número más pequeño mayor que cero.","h2":"En Alabama un conductor de Etapa II no puede llevar más de un pasajero aparte de sus padres, tutores legales o familiares, porque los amigos en el carro aumentan el riesgo de choque para los conductores nuevos.","p":"Correcto. Solo un pasajero que no sea de la familia."},"zh":{"q":"在 Alabama，持 Stage II（有限制）驾照的司机，可以载多少位不是父母、监护人或家人的乘客？","o":["不超过一位","不超过两位","不超过三位","系好安全带就可以载任何人数"],"h1":"这个限制是比零大的最小数字。","h2":"Alabama 持 Stage II 驾照的司机，除了父母、法定监护人或家人以外，最多只能载一位乘客，因为车里有朋友会提高新司机出车祸的风险。","p":"对。只能载一位不是家人的乘客。"},"vi":{"q":"Ở Alabama, người lái Giai đoạn II (có giới hạn) được chở bao nhiêu hành khách không phải là cha mẹ, người giám hộ, hoặc người trong gia đình?","o":["Không quá một người","Không quá hai người","Không quá ba người","Bao nhiêu cũng được nếu thắt dây an toàn"],"h1":"Giới hạn là con số nhỏ nhất lớn hơn không.","h2":"Người lái Giai đoạn II ở Alabama không được chở quá một hành khách ngoài cha mẹ, người giám hộ hợp pháp, hoặc người trong gia đình, vì có bạn bè trong xe làm tăng nguy cơ tai nạn cho người mới lái.","p":"Đúng. Chỉ một hành khách không phải người trong gia đình."},"tl":{"q":"Sa Alabama, ilang pasahero na hindi magulang, tagapag-alaga, o kapamilya ang puwedeng isakay ng drayber na may Stage II (restricted)?","o":["Hindi hihigit sa isa","Hindi hihigit sa dalawa","Hindi hihigit sa tatlo","Kahit ilan basta naka-seat belt"],"h1":"Ang limitasyon ay ang pinakamaliit na bilang na higit sa zero.","h2":"Ang drayber na may Stage II sa Alabama ay hindi puwedeng magsakay ng higit sa isang pasahero bukod sa mga magulang, legal na tagapag-alaga, o kapamilya, dahil ang mga kaibigan sa sasakyan ay nagpapataas ng panganib ng banggaan para sa mga bagong drayber.","p":"Tama. Isang pasahero lang na hindi kapamilya."},"ar":{"q":"في Alabama، كم راكبًا من غير الوالدين أو أولياء الأمور أو أفراد العائلة يجوز لسائق المرحلة الثانية (المقيّدة) أن يحمل؟","o":["راكب واحد فقط","راكبان فقط","ثلاثة ركّاب فقط","أي عدد مع أحزمة الأمان"],"h1":"الحدّ هو أصغر عدد أكبر من الصفر.","h2":"لا يجوز لسائق المرحلة الثانية في Alabama أن يحمل أكثر من راكب واحد غير الوالدين أو أولياء الأمور القانونيين أو أفراد العائلة، لأن وجود الأصدقاء في السيارة يزيد خطر الحوادث للسائقين الجدد.","p":"صحيح. راكب واحد فقط من غير العائلة."},"ref":{"doc":"AL","page":null}},{"id":"al-005","scope":"AL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alabama, during which hours may a Stage II driver not drive unless a parent, guardian, or licensed adult 21+ is with them (outside the listed exceptions)?","o":["From 9 p.m. to 5 a.m.","From 10 p.m. to 6 a.m.","From midnight to 6 a.m.","From 1 a.m. to 5 a.m."],"h1":"It starts when the date changes and ends at dawn.","h2":"An Alabama Stage II driver may not drive between midnight and 6 a.m. unless a parent, a legal guardian, or a licensed driver age 21 or older is in the car, because late-night driving is the most dangerous for new drivers.","p":"Right. No driving from midnight to 6 a.m. without an adult."},"es":{"q":"En Alabama, ¿en qué horario un conductor de Etapa II no puede manejar si no lo acompaña un padre, tutor o adulto con licencia de 21+ (fuera de las excepciones)?","o":["De 9 p.m. a 5 a.m.","De 10 p.m. a 6 a.m.","De medianoche a 6 a.m.","De 1 a.m. a 5 a.m."],"h1":"Empieza cuando cambia la fecha y termina al amanecer.","h2":"En Alabama un conductor de Etapa II no puede manejar entre la medianoche y las 6 a.m. si no va con él un padre, un tutor legal o un conductor con licencia de 21 años o más, porque manejar de madrugada es lo más peligroso para un conductor nuevo.","p":"Correcto. No se maneja de medianoche a 6 a.m. sin un adulto."},"zh":{"q":"在 Alabama，持 Stage II 驾照的司机在哪段时间不能开车，除非有父母、监护人或 21 岁或以上、有驾照的成年人陪同（规定的例外除外）？","o":["晚上 9 点到早上 5 点","晚上 10 点到早上 6 点","午夜到早上 6 点","凌晨 1 点到早上 5 点"],"h1":"它在日期变换时开始，在天亮时结束。","h2":"Alabama 持 Stage II 驾照的司机在午夜到早上 6 点之间不能开车，除非车里有父母、法定监护人，或 21 岁或以上、有驾照的司机，因为深夜开车对新司机最危险。","p":"对。没有成年人陪同时，午夜到早上 6 点不能开车。"},"vi":{"q":"Ở Alabama, trong những giờ nào người lái Giai đoạn II không được lái xe, trừ khi có cha mẹ, người giám hộ, hoặc người lớn có bằng lái từ 21 tuổi đi cùng (ngoài các trường hợp ngoại lệ)?","o":["Từ 9 giờ tối đến 5 giờ sáng","Từ 10 giờ tối đến 6 giờ sáng","Từ nửa đêm đến 6 giờ sáng","Từ 1 giờ sáng đến 5 giờ sáng"],"h1":"Bắt đầu khi sang ngày mới và kết thúc lúc rạng sáng.","h2":"Người lái Giai đoạn II ở Alabama không được lái xe từ nửa đêm đến 6 giờ sáng trừ khi có cha mẹ, người giám hộ hợp pháp, hoặc người có bằng lái từ 21 tuổi trở lên trong xe, vì lái xe khuya là nguy hiểm nhất cho người mới lái.","p":"Đúng. Không lái xe từ nửa đêm đến 6 giờ sáng nếu không có người lớn."},"tl":{"q":"Sa Alabama, sa anong mga oras hindi puwedeng magmaneho ang drayber na may Stage II maliban kung kasama ang magulang, tagapag-alaga, o may lisensyang adult na 21+ (bukod sa mga nakalistang eksepsiyon)?","o":["Mula 9 p.m. hanggang 5 a.m.","Mula 10 p.m. hanggang 6 a.m.","Mula hatinggabi hanggang 6 a.m.","Mula 1 a.m. hanggang 5 a.m."],"h1":"Nagsisimula ito kapag nagpalit ang petsa at natatapos sa madaling-araw.","h2":"Ang drayber na may Stage II sa Alabama ay hindi puwedeng magmaneho mula hatinggabi hanggang 6 a.m. maliban kung may magulang, legal na tagapag-alaga, o may lisensyang drayber na 21 taong gulang pataas sa sasakyan, dahil ang pagmamaneho sa hatinggabi ang pinakamapanganib para sa mga bagong drayber.","p":"Tama. Bawal magmaneho mula hatinggabi hanggang 6 a.m. nang walang adult."},"ar":{"q":"في Alabama، في أي ساعات لا يجوز لسائق المرحلة الثانية أن يقود إلا إذا كان معه أحد الوالدين أو وليّ أمر أو بالغ مرخّص عمره 21+ (خارج الاستثناءات المذكورة)؟","o":["من 9 مساءً إلى 5 صباحًا","من 10 مساءً إلى 6 صباحًا","من منتصف الليل إلى 6 صباحًا","من 1 صباحًا إلى 5 صباحًا"],"h1":"تبدأ عندما يتغيّر التاريخ وتنتهي عند الفجر.","h2":"لا يجوز لسائق المرحلة الثانية في Alabama أن يقود بين منتصف الليل و6 صباحًا إلا إذا كان في السيارة أحد الوالدين أو وليّ أمر قانوني أو سائق مرخّص عمره 21 سنة أو أكثر، لأن القيادة في آخر الليل هي الأخطر على السائقين الجدد.","p":"صحيح. لا قيادة من منتصف الليل إلى 6 صباحًا بدون شخص بالغ."},"ref":{"doc":"AL","page":null}},{"id":"al-006","scope":"AL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alabama, which trip is an exception that lets a Stage II driver drive alone between midnight and 6 a.m.?","o":["Going to or from work","Going to a friend's house","Driving to a restaurant","Practicing on empty roads"],"h1":"Think of a trip that a teen must make, not one for fun.","h2":"An Alabama Stage II driver may drive alone late at night when going to or from work, because the law allows needed trips such as work, school events, religious events, and emergencies.","p":"Right. A trip to or from work is allowed."},"es":{"q":"En Alabama, ¿qué viaje es una excepción que permite a un conductor de Etapa II manejar solo entre la medianoche y las 6 a.m.?","o":["Ir al trabajo o volver de él","Ir a la casa de un amigo","Manejar a un restaurante","Practicar en calles vacías"],"h1":"Piense en un viaje necesario, no en uno por diversión.","h2":"En Alabama un conductor de Etapa II puede manejar solo de noche cuando va al trabajo o vuelve de él, porque la ley permite viajes necesarios como el trabajo, eventos de la escuela, eventos religiosos y emergencias.","p":"Correcto. Ir al trabajo o volver de él está permitido."},"zh":{"q":"在 Alabama，哪一种行程是例外，让持 Stage II 驾照的司机可以在午夜到早上 6 点之间单独开车？","o":["上班或下班","去朋友家","开车去餐馆","在没有车的路上练习"],"h1":"想一想青少年必须去的行程，不是去玩的。","h2":"Alabama 持 Stage II 驾照的司机上班或下班时可以在深夜单独开车，因为法律允许必要的行程，比如工作、学校活动、宗教活动和紧急情况。","p":"对。上班或下班的行程是允许的。"},"vi":{"q":"Ở Alabama, chuyến đi nào là trường hợp ngoại lệ cho phép người lái Giai đoạn II lái một mình từ nửa đêm đến 6 giờ sáng?","o":["Đi làm hoặc đi làm về","Đến nhà một người bạn","Lái xe đến nhà hàng","Tập lái trên đường vắng"],"h1":"Hãy nghĩ đến một chuyến đi cần thiết, không phải để vui chơi.","h2":"Người lái Giai đoạn II ở Alabama được lái một mình vào ban đêm khi đi làm hoặc đi làm về, vì luật cho phép những chuyến đi cần thiết như đi làm, sự kiện của trường, sự kiện tôn giáo, và trường hợp khẩn cấp.","p":"Đúng. Được phép đi làm hoặc đi làm về."},"tl":{"q":"Sa Alabama, aling biyahe ang eksepsiyon na nagpapahintulot sa drayber na may Stage II na magmaneho nang mag-isa mula hatinggabi hanggang 6 a.m.?","o":["Papunta o pauwi galing sa trabaho","Papunta sa bahay ng kaibigan","Pagmamaneho papunta sa restawran","Pagsasanay sa mga bakanteng kalsada"],"h1":"Isipin ang biyaheng kailangang gawin ng kabataan, hindi para sa kasiyahan.","h2":"Ang drayber na may Stage II sa Alabama ay puwedeng magmaneho nang mag-isa sa hatinggabi kapag papunta o pauwi galing sa trabaho, dahil pinapayagan ng batas ang mga kailangang biyahe gaya ng trabaho, mga event ng paaralan, mga event na panrelihiyon, at mga emergency.","p":"Tama. Pinapayagan ang biyahe papunta o pauwi galing sa trabaho."},"ar":{"q":"في Alabama، أي رحلة تُعدّ استثناءً يسمح لسائق المرحلة الثانية بالقيادة وحده بين منتصف الليل و6 صباحًا؟","o":["الذهاب إلى العمل أو العودة منه","الذهاب إلى بيت صديق","القيادة إلى مطعم","التدرّب على طرق فارغة"],"h1":"فكّر في رحلة يجب على المراهق القيام بها، لا رحلة للتسلية.","h2":"يجوز لسائق المرحلة الثانية في Alabama أن يقود وحده في آخر الليل عند الذهاب إلى العمل أو العودة منه، لأن القانون يسمح بالرحلات الضرورية مثل العمل وأنشطة المدرسة والمناسبات الدينية وحالات الطوارئ.","p":"صحيح. الرحلة إلى العمل أو منه مسموحة."},"ref":{"doc":"AL","page":null}},{"id":"al-007","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, what does the Stage II license say about handheld phones while driving?","o":["They are fine at red lights","They may not be used at all","They may be used for short calls","They are fine with one passenger"],"h1":"Stage II drivers have extra limits on phones.","h2":"An Alabama Stage II driver must not use any handheld communication device while driving, because a phone in the hand takes eyes and attention off the road.","p":"Right. No handheld phone at all while driving on a Stage II license."},"es":{"q":"En Alabama, ¿qué dice la licencia de Etapa II sobre los teléfonos en la mano al manejar?","o":["Se pueden usar en los semáforos en rojo","No se pueden usar para nada","Se pueden usar para llamadas cortas","Se pueden usar con un solo pasajero"],"h1":"Los conductores de Etapa II tienen límites extra con el teléfono.","h2":"En Alabama un conductor de Etapa II no debe usar ningún aparato de comunicación en la mano mientras maneja, porque el teléfono en la mano quita la vista y la atención del camino.","p":"Correcto. Nada de teléfono en la mano con licencia de Etapa II."},"zh":{"q":"在 Alabama，Stage II 驾照对开车时用手持电话有什么规定？","o":["等红灯时可以用","完全不能用","可以打很短的电话","有一位乘客时可以用"],"h1":"Stage II 司机在用电话方面有额外的限制。","h2":"Alabama 持 Stage II 驾照的司机开车时不能用任何手持通讯设备，因为手里拿着电话会让眼睛和注意力离开道路。","p":"对。持 Stage II 驾照开车时完全不能用手持电话。"},"vi":{"q":"Ở Alabama, giấy phép Giai đoạn II quy định gì về việc cầm điện thoại khi lái xe?","o":["Được dùng khi dừng đèn đỏ","Hoàn toàn không được dùng","Được dùng cho cuộc gọi ngắn","Được dùng nếu có một hành khách"],"h1":"Người lái Giai đoạn II có thêm giới hạn về điện thoại.","h2":"Người lái Giai đoạn II ở Alabama không được dùng bất kỳ thiết bị liên lạc cầm tay nào khi lái xe, vì cầm điện thoại làm mắt và sự chú ý rời khỏi đường.","p":"Đúng. Hoàn toàn không cầm điện thoại khi lái xe với giấy phép Giai đoạn II."},"tl":{"q":"Sa Alabama, ano ang sinasabi ng Stage II license tungkol sa paghawak ng telepono habang nagmamaneho?","o":["Puwede kapag naka-red light","Hindi talaga puwedeng gamitin","Puwede para sa maikling tawag","Puwede kung may isang pasahero"],"h1":"May dagdag na limitasyon sa telepono ang mga drayber na may Stage II.","h2":"Ang drayber na may Stage II sa Alabama ay hindi dapat gumamit ng anumang hawak-kamay na kagamitang pangkomunikasyon habang nagmamaneho, dahil ang teleponong hawak mo ay naglalayo ng iyong mata at atensyon sa kalsada.","p":"Tama. Bawal talaga ang paghawak ng telepono habang nagmamaneho na may Stage II license."},"ar":{"q":"في Alabama، ماذا تقول رخصة المرحلة الثانية عن حمل الهاتف باليد أثناء القيادة؟","o":["مسموح عند الإشارة الحمراء","ممنوع استخدامه تمامًا","مسموح للمكالمات القصيرة","مسموح مع راكب واحد"],"h1":"لسائقي المرحلة الثانية قيود إضافية على الهاتف.","h2":"يجب ألّا يستخدم سائق المرحلة الثانية في Alabama أي جهاز اتصال محمول باليد أثناء القيادة، لأن الهاتف في اليد يُبعد العينين والانتباه عن الطريق.","p":"صحيح. لا هاتف في اليد إطلاقًا أثناء القيادة برخصة المرحلة الثانية."},"ref":{"doc":"AL","page":null}},{"id":"al-008","scope":"AL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alabama, what happens when a Stage II driver breaks one of the graduated license rules?","o":["A warning letter only","A one-time $10 fee","Nothing, if no one was hurt","The restricted period is extended"],"h1":"The limits do not end as soon as planned.","h2":"In Alabama, breaking a graduated license rule extends the restricted period by six months or until the driver turns 18, so the teen keeps the limits longer.","p":"Right. The limits last longer after a violation."},"es":{"q":"En Alabama, ¿qué pasa cuando un conductor de Etapa II no cumple una regla de la licencia por etapas?","o":["Solo una carta de aviso","Un cargo único de $10","Nada, si nadie se lastimó","Se alarga el período restringido"],"h1":"Los límites no terminan cuando se pensaba.","h2":"En Alabama, si no se cumple una regla de la licencia por etapas, el período restringido se alarga seis meses o hasta que el conductor cumpla 18 años, así que el joven mantiene los límites por más tiempo.","p":"Correcto. Los límites duran más después de una infracción."},"zh":{"q":"在 Alabama，持 Stage II 驾照的司机违反了分级驾照的一项规定，会怎么样？","o":["只会收到一封警告信","一次性收费 $10","如果没有人受伤，就没事","有限制的期间会延长"],"h1":"限制不会按原来的计划结束。","h2":"在 Alabama，违反分级驾照规定会让有限制的期间延长六个月，或者延长到司机满 18 岁，所以这位青少年要更久遵守这些限制。","p":"对。违规以后，限制会持续更久。"},"vi":{"q":"Ở Alabama, chuyện gì xảy ra khi người lái Giai đoạn II vi phạm một quy định của bằng lái theo giai đoạn?","o":["Chỉ nhận thư cảnh cáo","Trả phí một lần $10","Không sao, nếu không ai bị thương","Thời gian giới hạn bị kéo dài"],"h1":"Các giới hạn không kết thúc đúng như dự định.","h2":"Ở Alabama, vi phạm quy định của bằng lái theo giai đoạn sẽ kéo dài thời gian giới hạn thêm sáu tháng hoặc đến khi người lái 18 tuổi, nên thanh thiếu niên phải giữ các giới hạn lâu hơn.","p":"Đúng. Các giới hạn kéo dài hơn sau khi vi phạm."},"tl":{"q":"Sa Alabama, ano ang mangyayari kapag lumabag ang drayber na may Stage II sa isa sa mga patakaran ng graduated license?","o":["Sulat ng babala lang","Isang beses na bayad na $10","Wala, kung walang nasaktan","Pinahahaba ang panahon ng restriksyon"],"h1":"Hindi natatapos ang mga limitasyon sa planadong oras.","h2":"Sa Alabama, ang paglabag sa patakaran ng graduated license ay nagpapahaba ng panahon ng restriksyon nang anim na buwan o hanggang mag-18 ang drayber, kaya mas matagal na mananatili ang mga limitasyon sa kabataan.","p":"Tama. Mas tumatagal ang mga limitasyon pagkatapos ng paglabag."},"ar":{"q":"في Alabama، ماذا يحدث عندما يخالف سائق المرحلة الثانية إحدى قواعد الرخصة المتدرّجة؟","o":["رسالة تحذير فقط","رسم واحد قدره $10","لا شيء، إذا لم يُصب أحد","تمديد فترة القيود"],"h1":"القيود لا تنتهي في موعدها المخطّط.","h2":"في Alabama، مخالفة إحدى قواعد الرخصة المتدرّجة تمدّد فترة القيود ستة أشهر أو حتى يبلغ السائق 18 سنة، فيبقى المراهق تحت القيود مدة أطول.","p":"صحيح. تستمر القيود مدة أطول بعد المخالفة."},"ref":{"doc":"AL","page":null}},{"id":"al-009","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, a 17-year-old can get an unrestricted Stage III license after holding Stage II for how long?","o":["At least 3 months","At least 6 months","At least 9 months","At least 12 months"],"h1":"It is the same length as the Stage I waiting time.","h2":"In Alabama a 17-year-old must hold a Stage II license for at least six months before getting the unrestricted Stage III license, so the new driver has time alone with limits first.","p":"Right. Six months on Stage II, then Stage III."},"es":{"q":"En Alabama, un joven de 17 años puede obtener la licencia sin restricciones de Etapa III después de tener la Etapa II, ¿por cuánto tiempo?","o":["Por lo menos 3 meses","Por lo menos 6 meses","Por lo menos 9 meses","Por lo menos 12 meses"],"h1":"Es el mismo tiempo de espera que en la Etapa I.","h2":"En Alabama un joven de 17 años debe tener la licencia de Etapa II por lo menos seis meses antes de obtener la licencia sin restricciones de Etapa III, para tener primero un tiempo manejando solo con límites.","p":"Correcto. Seis meses en Etapa II y luego la Etapa III."},"zh":{"q":"在 Alabama，17 岁的人持有 Stage II 驾照多久以后，可以拿到没有限制的 Stage III 驾照？","o":["至少 3 个月","至少 6 个月","至少 9 个月","至少 12 个月"],"h1":"它和 Stage I 的等待时间一样长。","h2":"在 Alabama，17 岁的人必须持有 Stage II 驾照至少六个月，才能拿到没有限制的 Stage III 驾照，这样新司机先有一段在限制下单独开车的时间。","p":"对。Stage II 持有六个月，然后是 Stage III。"},"vi":{"q":"Ở Alabama, người 17 tuổi có thể được cấp bằng lái Giai đoạn III không giới hạn sau khi giữ Giai đoạn II bao lâu?","o":["Ít nhất 3 tháng","Ít nhất 6 tháng","Ít nhất 9 tháng","Ít nhất 12 tháng"],"h1":"Bằng với thời gian chờ của Giai đoạn I.","h2":"Ở Alabama, người 17 tuổi phải giữ bằng lái Giai đoạn II ít nhất sáu tháng trước khi được cấp bằng Giai đoạn III không giới hạn, để người mới lái có thời gian lái một mình với các giới hạn trước.","p":"Đúng. Sáu tháng với Giai đoạn II, rồi đến Giai đoạn III."},"tl":{"q":"Sa Alabama, ang 17 taong gulang ay puwedeng kumuha ng Stage III license na walang restriksyon pagkatapos humawak ng Stage II nang gaano katagal?","o":["Hindi bababa sa 3 buwan","Hindi bababa sa 6 na buwan","Hindi bababa sa 9 na buwan","Hindi bababa sa 12 buwan"],"h1":"Kapareho ito ng haba ng paghihintay sa Stage I.","h2":"Sa Alabama, ang 17 taong gulang ay dapat humawak ng Stage II license nang hindi bababa sa anim na buwan bago makakuha ng Stage III license na walang restriksyon, para may oras muna ang bagong drayber na magmaneho nang mag-isa na may mga limitasyon.","p":"Tama. Anim na buwan sa Stage II, saka Stage III."},"ar":{"q":"في Alabama، يمكن لمن عمره 17 سنة الحصول على رخصة المرحلة الثالثة غير المقيّدة بعد حمل المرحلة الثانية لكم من الوقت؟","o":["3 أشهر على الأقل","6 أشهر على الأقل","9 أشهر على الأقل","12 شهرًا على الأقل"],"h1":"إنها نفس مدة الانتظار في المرحلة الأولى.","h2":"في Alabama يجب على من عمره 17 سنة أن يحمل رخصة المرحلة الثانية ستة أشهر على الأقل قبل الحصول على رخصة المرحلة الثالثة غير المقيّدة، ليقضي السائق الجديد وقتًا يقود فيه وحده مع القيود أولًا.","p":"صحيح. ستة أشهر في المرحلة الثانية، ثم المرحلة الثالثة."},"ref":{"doc":"AL","page":null}},{"id":"al-010","scope":"AL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alabama, how long is a learner license valid before it must be renewed?","o":["One year","Two years","Four years","Eight years"],"h1":"It lasts longer than a typical school year or two.","h2":"An Alabama learner license is valid for four years and can be renewed once, which gives a learner plenty of time to practice.","p":"Right. The learner license is good for four years."},"es":{"q":"En Alabama, ¿por cuánto tiempo es válida la licencia de aprendiz antes de renovarla?","o":["Un año","Dos años","Cuatro años","Ocho años"],"h1":"Dura más que uno o dos años escolares.","h2":"En Alabama la licencia de aprendiz es válida por cuatro años y se puede renovar una vez, lo que le da al aprendiz mucho tiempo para practicar.","p":"Correcto. La licencia de aprendiz dura cuatro años."},"zh":{"q":"在 Alabama，学习驾照在需要延期之前有效多久？","o":["一年","两年","四年","八年"],"h1":"它比一两个学年还长。","h2":"Alabama 的学习驾照有效期是四年，可以延期一次，这让学习驾驶的人有很多时间练习。","p":"对。学习驾照有效四年。"},"vi":{"q":"Ở Alabama, giấy phép tập lái có giá trị bao lâu trước khi phải gia hạn?","o":["Một năm","Hai năm","Bốn năm","Tám năm"],"h1":"Nó kéo dài hơn một hoặc hai năm học thông thường.","h2":"Giấy phép tập lái ở Alabama có giá trị bốn năm và được gia hạn một lần, cho người tập lái nhiều thời gian để luyện tập.","p":"Đúng. Giấy phép tập lái có giá trị bốn năm."},"tl":{"q":"Sa Alabama, gaano katagal valid ang learner license bago ito dapat i-renew?","o":["Isang taon","Dalawang taon","Apat na taon","Walong taon"],"h1":"Mas matagal ito kaysa sa karaniwang isa o dalawang taon ng pag-aaral.","h2":"Ang learner license sa Alabama ay valid nang apat na taon at puwedeng i-renew nang isang beses, kaya maraming oras ang learner para magsanay.","p":"Tama. Valid ang learner license nang apat na taon."},"ar":{"q":"في Alabama، كم تبقى رخصة التعلّم سارية قبل أن يجب تجديدها؟","o":["سنة واحدة","سنتان","أربع سنوات","ثماني سنوات"],"h1":"تدوم أطول من سنة أو سنتين دراسيتين عاديتين.","h2":"رخصة التعلّم في Alabama سارية أربع سنوات ويمكن تجديدها مرة واحدة، مما يعطي المتعلّم وقتًا كافيًا للتدرّب.","p":"صحيح. رخصة التعلّم صالحة أربع سنوات."},"ref":{"doc":"AL","page":9}},{"id":"al-011","scope":"AL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alabama, can a person take the written knowledge test in Spanish?","o":["Yes, Spanish is offered","No, it is English only","Only with a paid interpreter","Only for commercial licenses"],"h1":"Alabama offers the written test in several languages.","h2":"Alabama offers the written knowledge test in other languages, including Spanish, so people can show what they know in the language they read best.","p":"Right. The Alabama written test is available in Spanish."},"es":{"q":"En Alabama, ¿se puede tomar el examen escrito de conocimientos en español?","o":["Sí, se ofrece en español","No, solo en inglés","Solo con un intérprete pagado","Solo para licencias comerciales"],"h1":"Alabama ofrece el examen escrito en varios idiomas.","h2":"Alabama ofrece el examen escrito de conocimientos en otros idiomas, incluido el español, para que cada persona muestre lo que sabe en el idioma que lee mejor.","p":"Correcto. El examen escrito de Alabama se ofrece en español."},"zh":{"q":"在 Alabama，可以用西班牙语考笔试吗？","o":["可以，有西班牙语","不可以，只有英语","只有请付费翻译时才可以","只有商业驾照才可以"],"h1":"Alabama 的笔试有好几种语言。","h2":"Alabama 的笔试提供其他语言，包括西班牙语，所以人们可以用自己读得最好的语言来表现他们知道的东西。","p":"对。Alabama 的笔试有西班牙语。"},"vi":{"q":"Ở Alabama, có thể thi lý thuyết bằng tiếng Tây Ban Nha không?","o":["Có, có tiếng Tây Ban Nha","Không, chỉ có tiếng Anh","Chỉ khi trả tiền thông dịch viên","Chỉ cho bằng lái thương mại"],"h1":"Alabama có bài thi lý thuyết bằng nhiều ngôn ngữ.","h2":"Alabama có bài thi lý thuyết bằng các ngôn ngữ khác, kể cả tiếng Tây Ban Nha, để mọi người có thể thể hiện hiểu biết bằng ngôn ngữ họ đọc tốt nhất.","p":"Đúng. Bài thi lý thuyết ở Alabama có bằng tiếng Tây Ban Nha."},"tl":{"q":"Sa Alabama, puwede bang kumuha ng nakasulat na knowledge test sa Spanish?","o":["Oo, may Spanish","Hindi, English lang","Kung may bayad na interpreter lang","Para sa commercial license lang"],"h1":"May nakasulat na pagsusulit ang Alabama sa ilang wika.","h2":"May nakasulat na knowledge test ang Alabama sa ibang mga wika, kasama ang Spanish, para maipakita ng mga tao ang alam nila sa wikang pinakamahusay nilang nababasa.","p":"Tama. May nakasulat na pagsusulit ang Alabama sa Spanish."},"ar":{"q":"في Alabama، هل يمكن تقديم الاختبار النظري المكتوب باللغة الإسبانية؟","o":["نعم، الإسبانية متاحة","لا، بالإنجليزية فقط","فقط مع مترجم مدفوع الأجر","فقط للرخص التجارية"],"h1":"تقدّم Alabama الاختبار المكتوب بعدة لغات.","h2":"تقدّم Alabama الاختبار النظري المكتوب بلغات أخرى، منها الإسبانية، ليتمكّن الناس من إظهار ما يعرفونه باللغة التي يقرؤونها أفضل.","p":"صحيح. الاختبار المكتوب في Alabama متاح بالإسبانية."},"ref":{"doc":"AL","page":9}},{"id":"al-012","scope":"AL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Alabama, unless a sign says otherwise, what is the speed limit in an urban district?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"It is a little higher than a typical school zone speed.","h2":"The Alabama speed limit in an urban district is 30 mph unless a sign shows a different limit, because towns have many people, driveways, and crossings.","p":"Right. Urban districts in Alabama are 30 mph unless posted."},"es":{"q":"En Alabama, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad en una zona urbana?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Es un poco más alto que la velocidad típica de una zona escolar.","h2":"En Alabama el límite de velocidad en una zona urbana es de 30 mph si no hay una señal con otro límite, porque en los pueblos hay mucha gente, entradas de autos y cruces.","p":"Correcto. En zonas urbanas de Alabama son 30 mph si no hay otra señal."},"zh":{"q":"在 Alabama，除非标志另有规定，市区的限速是多少？","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"它比一般学校区的速度高一点。","h2":"除非标志写着别的限速，Alabama 市区的限速是 30 mph，因为城镇里有很多人、车道出口和路口。","p":"对。除非有标志，Alabama 市区限速是 30 mph。"},"vi":{"q":"Ở Alabama, nếu không có biển báo khác, tốc độ tối đa trong khu đô thị là bao nhiêu?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Cao hơn một chút so với tốc độ thông thường ở khu trường học.","h2":"Tốc độ tối đa trong khu đô thị ở Alabama là 30 mph trừ khi biển báo ghi khác, vì thị trấn có nhiều người, lối xe ra vào, và chỗ băng qua đường.","p":"Đúng. Khu đô thị ở Alabama là 30 mph nếu không có biển báo khác."},"tl":{"q":"Sa Alabama, maliban kung iba ang sinasabi ng karatula, ano ang speed limit sa urban district?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Medyo mas mataas ito kaysa sa karaniwang bilis sa school zone.","h2":"Ang speed limit sa urban district sa Alabama ay 30 mph maliban kung iba ang ipinapakita ng karatula, dahil maraming tao, daanan ng sasakyan, at tawiran sa mga bayan.","p":"Tama. 30 mph ang mga urban district sa Alabama maliban kung may nakapaskil."},"ar":{"q":"في Alabama، ما لم تُشر لافتة إلى غير ذلك، ما حدّ السرعة في المنطقة الحضرية؟","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"إنه أعلى قليلًا من السرعة المعتادة في منطقة المدرسة.","h2":"حدّ السرعة في المنطقة الحضرية في Alabama هو 30 mph ما لم تُظهر لافتة حدًّا مختلفًا، لأن في البلدات كثيرًا من الناس ومداخل السيارات وأماكن العبور.","p":"صحيح. المناطق الحضرية في Alabama حدّها 30 mph ما لم تُشر لافتة إلى غير ذلك."},"ref":{"doc":"AL","page":60}},{"id":"al-013","scope":"AL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Alabama, what is the highest speed limit allowed by law on an interstate highway?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Interstates have the highest limit in the state.","h2":"The highest speed limit on an Alabama interstate is 70 mph, which is higher than the limit on other four-lane highways.","p":"Right. Alabama interstates go up to 70 mph."},"es":{"q":"En Alabama, ¿cuál es el límite de velocidad más alto que permite la ley en una carretera interestatal?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Las interestatales tienen el límite más alto del estado.","h2":"En Alabama el límite de velocidad más alto en una interestatal es de 70 mph, más alto que en otras carreteras de cuatro carriles.","p":"Correcto. Las interestatales de Alabama llegan a 70 mph."},"zh":{"q":"在 Alabama，法律允许州际公路的最高限速是多少？","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"州际公路的限速是全州最高的。","h2":"Alabama 州际公路的最高限速是 70 mph，比其他四车道公路的限速高。","p":"对。Alabama 州际公路最高是 70 mph。"},"vi":{"q":"Ở Alabama, tốc độ tối đa cao nhất theo luật trên xa lộ liên bang (interstate) là bao nhiêu?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Xa lộ liên bang có tốc độ tối đa cao nhất trong tiểu bang.","h2":"Tốc độ tối đa cao nhất trên xa lộ liên bang ở Alabama là 70 mph, cao hơn tốc độ trên các xa lộ bốn làn khác.","p":"Đúng. Xa lộ liên bang ở Alabama tối đa 70 mph."},"tl":{"q":"Sa Alabama, ano ang pinakamataas na speed limit na pinapayagan ng batas sa interstate highway?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Ang mga interstate ang may pinakamataas na limit sa estado.","h2":"Ang pinakamataas na speed limit sa interstate sa Alabama ay 70 mph, na mas mataas kaysa sa limit sa ibang highway na may apat na lane.","p":"Tama. Hanggang 70 mph ang mga interstate sa Alabama."},"ar":{"q":"في Alabama، ما أعلى حدّ سرعة يسمح به القانون على الطريق السريع بين الولايات (interstate)؟","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"الطرق السريعة بين الولايات لها أعلى حدّ في الولاية.","h2":"أعلى حدّ سرعة على الطريق السريع بين الولايات في Alabama هو 70 mph، وهو أعلى من الحدّ على الطرق السريعة الأخرى ذات الأربعة مسارات.","p":"صحيح. الطرق السريعة بين الولايات في Alabama تصل إلى 70 mph."},"ref":{"doc":"AL","page":60}},{"id":"al-014","scope":"AL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Alabama, unless posted otherwise, what is the speed limit on a highway with four or more lanes that is not an interstate?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"It is 5 mph below the interstate limit.","h2":"On an Alabama highway with four or more lanes that is not an interstate, the limit is 65 mph unless posted, which is 5 mph less than on an interstate.","p":"Right. Four-lane highways that are not interstates are 65 mph."},"es":{"q":"En Alabama, si no hay otra señal, ¿cuál es el límite de velocidad en una carretera de cuatro carriles o más que no es interestatal?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Es 5 mph menos que el límite de la interestatal.","h2":"En una carretera de Alabama con cuatro carriles o más que no es interestatal, el límite es de 65 mph si no hay otra señal, o sea 5 mph menos que en una interestatal.","p":"Correcto. Las carreteras de cuatro carriles que no son interestatales tienen 65 mph."},"zh":{"q":"在 Alabama，除非标志另有规定，不是州际公路、有四条或更多车道的公路，限速是多少？","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"它比州际公路的限速低 5 mph。","h2":"在 Alabama 不是州际公路、有四条或更多车道的公路上，除非有标志，限速是 65 mph，比州际公路低 5 mph。","p":"对。不是州际公路的四车道公路限速是 65 mph。"},"vi":{"q":"Ở Alabama, nếu không có biển báo khác, tốc độ tối đa trên xa lộ có bốn làn trở lên mà không phải xa lộ liên bang là bao nhiêu?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Thấp hơn 5 mph so với xa lộ liên bang.","h2":"Trên xa lộ ở Alabama có bốn làn trở lên mà không phải xa lộ liên bang, tốc độ tối đa là 65 mph nếu không có biển báo khác, thấp hơn 5 mph so với xa lộ liên bang.","p":"Đúng. Xa lộ bốn làn không phải liên bang là 65 mph."},"tl":{"q":"Sa Alabama, maliban kung iba ang nakapaskil, ano ang speed limit sa highway na may apat o higit pang lane na hindi interstate?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"5 mph itong mas mababa sa limit ng interstate.","h2":"Sa highway sa Alabama na may apat o higit pang lane na hindi interstate, ang limit ay 65 mph maliban kung may nakapaskil, na 5 mph na mas mababa kaysa sa interstate.","p":"Tama. 65 mph ang mga highway na may apat na lane na hindi interstate."},"ar":{"q":"في Alabama، ما لم تُشر لافتة إلى غير ذلك، ما حدّ السرعة على طريق سريع له أربعة مسارات أو أكثر وليس طريقًا بين الولايات؟","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"إنه أقل بـ 5 mph من حدّ الطريق بين الولايات.","h2":"على طريق سريع في Alabama له أربعة مسارات أو أكثر وليس طريقًا بين الولايات، الحدّ هو 65 mph ما لم تُشر لافتة إلى غير ذلك، وهو أقل بـ 5 mph من الطريق بين الولايات.","p":"صحيح. الطرق ذات الأربعة مسارات التي ليست بين الولايات حدّها 65 mph."},"ref":{"doc":"AL","page":null}},{"id":"al-015","scope":"AL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Alabama, unless posted otherwise, what is the speed limit on a state highway with fewer than four lanes?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Smaller highways have a lower limit than four-lane highways.","h2":"An Alabama highway with fewer than four lanes has a 55 mph limit unless a sign says otherwise, because two-lane roads have oncoming traffic close by.","p":"Right. Smaller Alabama highways are 55 mph unless posted."},"es":{"q":"En Alabama, si no hay otra señal, ¿cuál es el límite de velocidad en una carretera estatal de menos de cuatro carriles?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Las carreteras más pequeñas tienen un límite más bajo que las de cuatro carriles.","h2":"En Alabama una carretera de menos de cuatro carriles tiene un límite de 55 mph si no hay una señal con otro límite, porque en las carreteras de dos carriles el tráfico contrario pasa muy cerca.","p":"Correcto. Las carreteras pequeñas de Alabama tienen 55 mph si no hay otra señal."},"zh":{"q":"在 Alabama，除非标志另有规定，少于四条车道的州公路限速是多少？","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"比较小的公路，限速比四车道公路低。","h2":"Alabama 少于四条车道的公路，除非标志另有规定，限速是 55 mph，因为双车道道路上对面来的车离得很近。","p":"对。除非有标志，Alabama 较小的公路限速是 55 mph。"},"vi":{"q":"Ở Alabama, nếu không có biển báo khác, tốc độ tối đa trên xa lộ tiểu bang có ít hơn bốn làn là bao nhiêu?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Xa lộ nhỏ hơn có tốc độ thấp hơn xa lộ bốn làn.","h2":"Xa lộ ở Alabama có ít hơn bốn làn có tốc độ tối đa 55 mph trừ khi biển báo ghi khác, vì đường hai làn có xe đi ngược chiều ở rất gần.","p":"Đúng. Xa lộ nhỏ ở Alabama là 55 mph nếu không có biển báo khác."},"tl":{"q":"Sa Alabama, maliban kung iba ang nakapaskil, ano ang speed limit sa state highway na may mas kaunti sa apat na lane?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Mas mababa ang limit ng maliliit na highway kaysa sa mga highway na may apat na lane.","h2":"Ang highway sa Alabama na may mas kaunti sa apat na lane ay may limit na 55 mph maliban kung iba ang sinasabi ng karatula, dahil malapit ang mga sasakyang kasalubong sa kalsadang may dalawang lane.","p":"Tama. 55 mph ang maliliit na highway sa Alabama maliban kung may nakapaskil."},"ar":{"q":"في Alabama، ما لم تُشر لافتة إلى غير ذلك، ما حدّ السرعة على طريق سريع تابع للولاية له أقل من أربعة مسارات؟","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"الطرق الأصغر لها حدّ أقل من الطرق ذات الأربعة مسارات.","h2":"الطريق السريع في Alabama الذي له أقل من أربعة مسارات حدّه 55 mph ما لم تُشر لافتة إلى غير ذلك، لأن في الطرق ذات المسارين سيارات قادمة من الاتجاه المقابل قريبة جدًّا.","p":"صحيح. الطرق الأصغر في Alabama حدّها 55 mph ما لم تُشر لافتة إلى غير ذلك."},"ref":{"doc":"AL","page":60}},{"id":"al-016","scope":"AL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Alabama, unless posted otherwise, what is the speed limit on an unpaved road?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"Dirt and gravel need more care than a paved county road.","h2":"The Alabama limit on an unpaved road is 35 mph unless a sign says otherwise, because loose dirt and gravel make it harder to stop and steer.","p":"Right. Unpaved roads in Alabama are 35 mph."},"es":{"q":"En Alabama, si no hay otra señal, ¿cuál es el límite de velocidad en un camino sin pavimentar?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"La tierra y la grava piden más cuidado que un camino pavimentado del condado.","h2":"En Alabama el límite en un camino sin pavimentar es de 35 mph si no hay otra señal, porque la tierra suelta y la grava hacen más difícil frenar y girar.","p":"Correcto. Los caminos sin pavimentar en Alabama tienen 35 mph."},"zh":{"q":"在 Alabama，除非标志另有规定，没有铺路面的道路限速是多少？","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"土路和碎石路比铺好的县道更需要小心。","h2":"Alabama 没有铺路面的道路，除非标志另有规定，限速是 35 mph，因为松散的泥土和碎石让停车和转方向盘更难。","p":"对。Alabama 没有铺路面的道路限速是 35 mph。"},"vi":{"q":"Ở Alabama, nếu không có biển báo khác, tốc độ tối đa trên đường không trải nhựa là bao nhiêu?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"Đường đất và sỏi cần cẩn thận hơn đường quận trải nhựa.","h2":"Tốc độ tối đa trên đường không trải nhựa ở Alabama là 35 mph trừ khi biển báo ghi khác, vì đất và sỏi rời làm khó dừng và khó lái hơn.","p":"Đúng. Đường không trải nhựa ở Alabama là 35 mph."},"tl":{"q":"Sa Alabama, maliban kung iba ang nakapaskil, ano ang speed limit sa kalsadang hindi sementado?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"Mas kailangan ng ingat sa lupa at graba kaysa sa sementadong county road.","h2":"Ang limit sa kalsadang hindi sementado sa Alabama ay 35 mph maliban kung iba ang sinasabi ng karatula, dahil mas mahirap huminto at magmaniobra sa maluwag na lupa at graba.","p":"Tama. 35 mph ang mga kalsadang hindi sementado sa Alabama."},"ar":{"q":"في Alabama، ما لم تُشر لافتة إلى غير ذلك، ما حدّ السرعة على طريق غير معبّد؟","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"التراب والحصى يحتاجان إلى حذر أكثر من طريق المقاطعة المعبّد.","h2":"حدّ السرعة على الطريق غير المعبّد في Alabama هو 35 mph ما لم تُشر لافتة إلى غير ذلك، لأن التراب والحصى المفكّك يجعلان التوقّف والتوجيه أصعب.","p":"صحيح. الطرق غير المعبّدة في Alabama حدّها 35 mph."},"ref":{"doc":"AL","page":60}},{"id":"al-017","scope":"AL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Alabama, unless posted otherwise, what is the speed limit on a paved county road outside a city or town?","o":["35 mph","45 mph","55 mph","65 mph"],"h1":"It is 10 mph more than on an unpaved road.","h2":"A paved county road outside a city or town in Alabama has a 45 mph limit unless posted, which is 10 mph more than on an unpaved road.","p":"Right. Paved county roads in Alabama are 45 mph unless posted."},"es":{"q":"En Alabama, si no hay otra señal, ¿cuál es el límite de velocidad en un camino pavimentado del condado fuera de una ciudad o pueblo?","o":["35 mph","45 mph","55 mph","65 mph"],"h1":"Es 10 mph más que en un camino sin pavimentar.","h2":"En Alabama un camino pavimentado del condado fuera de una ciudad o pueblo tiene un límite de 45 mph si no hay otra señal, o sea 10 mph más que en un camino sin pavimentar.","p":"Correcto. Los caminos pavimentados del condado en Alabama tienen 45 mph."},"zh":{"q":"在 Alabama，除非标志另有规定，城市或城镇以外铺好路面的县道限速是多少？","o":["35 mph","45 mph","55 mph","65 mph"],"h1":"它比没有铺路面的道路多 10 mph。","h2":"Alabama 城市或城镇以外铺好路面的县道，除非有标志，限速是 45 mph，比没有铺路面的道路多 10 mph。","p":"对。除非有标志，Alabama 铺好路面的县道限速是 45 mph。"},"vi":{"q":"Ở Alabama, nếu không có biển báo khác, tốc độ tối đa trên đường quận trải nhựa bên ngoài thành phố hoặc thị trấn là bao nhiêu?","o":["35 mph","45 mph","55 mph","65 mph"],"h1":"Cao hơn 10 mph so với đường không trải nhựa.","h2":"Đường quận trải nhựa bên ngoài thành phố hoặc thị trấn ở Alabama có tốc độ tối đa 45 mph nếu không có biển báo khác, cao hơn 10 mph so với đường không trải nhựa.","p":"Đúng. Đường quận trải nhựa ở Alabama là 45 mph nếu không có biển báo khác."},"tl":{"q":"Sa Alabama, maliban kung iba ang nakapaskil, ano ang speed limit sa sementadong county road sa labas ng lungsod o bayan?","o":["35 mph","45 mph","55 mph","65 mph"],"h1":"10 mph itong mas mataas kaysa sa kalsadang hindi sementado.","h2":"Ang sementadong county road sa labas ng lungsod o bayan sa Alabama ay may limit na 45 mph maliban kung may nakapaskil, na 10 mph na mas mataas kaysa sa kalsadang hindi sementado.","p":"Tama. 45 mph ang mga sementadong county road sa Alabama maliban kung may nakapaskil."},"ar":{"q":"في Alabama، ما لم تُشر لافتة إلى غير ذلك، ما حدّ السرعة على طريق مقاطعة معبّد خارج المدينة أو البلدة؟","o":["35 mph","45 mph","55 mph","65 mph"],"h1":"إنه أعلى بـ 10 mph من الطريق غير المعبّد.","h2":"طريق المقاطعة المعبّد خارج المدينة أو البلدة في Alabama حدّه 45 mph ما لم تُشر لافتة إلى غير ذلك، وهو أعلى بـ 10 mph من الطريق غير المعبّد.","p":"صحيح. طرق المقاطعة المعبّدة في Alabama حدّها 45 mph ما لم تُشر لافتة إلى غير ذلك."},"ref":{"doc":"AL","page":60}},{"id":"al-018","scope":"AL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Alabama, on an interstate, how far may you stay in the far-left lane without completely passing another vehicle?","o":["0.5 miles","1 mile","3 miles","1.5 miles"],"h1":"It is a short distance, between one and two miles.","h2":"On an Alabama interstate you may not stay in the far-left lane for more than 1.5 miles without completely passing a vehicle, because the left lane is for passing.","p":"Right. No more than 1.5 miles in the left lane without passing."},"es":{"q":"En Alabama, en una interestatal, ¿qué distancia puede ir por el carril de la izquierda sin terminar de rebasar a otro vehículo?","o":["0.5 millas","1 milla","3 millas","1.5 millas"],"h1":"Es una distancia corta, entre una y dos millas.","h2":"En una interestatal de Alabama usted no puede ir más de 1.5 millas por el carril de la izquierda sin terminar de rebasar a un vehículo, porque el carril izquierdo es para rebasar.","p":"Correcto. No más de 1.5 millas en el carril izquierdo sin rebasar."},"zh":{"q":"在 Alabama 的州际公路上，你在最左边车道最多可以开多远而不完全超过另一辆车？","o":["0.5 英里","1 英里","3 英里","1.5 英里"],"h1":"这是一段短距离，在一英里和两英里之间。","h2":"在 Alabama 的州际公路上，你在最左边车道开超过 1.5 英里却没有完全超过一辆车是不允许的，因为左边车道是用来超车的。","p":"对。在左边车道不超车，最多开 1.5 英里。"},"vi":{"q":"Ở Alabama, trên xa lộ liên bang, bạn được ở làn ngoài cùng bên trái bao xa mà không vượt hẳn qua xe khác?","o":["0.5 dặm","1 dặm","3 dặm","1.5 dặm"],"h1":"Một khoảng ngắn, giữa một và hai dặm.","h2":"Trên xa lộ liên bang ở Alabama, bạn không được ở làn ngoài cùng bên trái quá 1.5 dặm mà không vượt hẳn qua một xe, vì làn bên trái dùng để vượt.","p":"Đúng. Không quá 1.5 dặm ở làn trái mà không vượt."},"tl":{"q":"Sa Alabama, sa interstate, gaano kalayo ka puwedeng manatili sa pinakakaliwang lane nang hindi lubusang nag-o-overtake sa ibang sasakyan?","o":["0.5 milya","1 milya","3 milya","1.5 milya"],"h1":"Maikling distansya ito, sa pagitan ng isa at dalawang milya.","h2":"Sa interstate sa Alabama, hindi ka puwedeng manatili sa pinakakaliwang lane nang higit sa 1.5 milya nang hindi lubusang nag-o-overtake sa isang sasakyan, dahil ang kaliwang lane ay para sa pag-overtake.","p":"Tama. Hindi hihigit sa 1.5 milya sa kaliwang lane nang hindi nag-o-overtake."},"ar":{"q":"في Alabama، على الطريق السريع بين الولايات، ما المسافة التي يجوز لك البقاء فيها في المسار الأيسر الأقصى دون أن تتجاوز مركبة أخرى تمامًا؟","o":["0.5 ميل","1 ميل","3 أميال","1.5 ميل"],"h1":"إنها مسافة قصيرة، بين ميل وميلين.","h2":"على الطريق السريع بين الولايات في Alabama لا يجوز لك البقاء في المسار الأيسر الأقصى أكثر من 1.5 ميل دون أن تتجاوز مركبة تمامًا، لأن المسار الأيسر مخصّص للتجاوز.","p":"صحيح. لا أكثر من 1.5 ميل في المسار الأيسر دون تجاوز."},"ref":{"doc":"AL","page":null}},{"id":"al-019","scope":"AL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Alabama, on a road with two or more lanes in your direction, what should you do when passing a stopped police car with flashing lights?","o":["Move out of the lane next to it if safe","Stop behind it and wait","Honk and keep your speed","Speed up to pass it quickly"],"h1":"Give the stopped vehicle more room.","h2":"Under the Alabama Move Over law you must leave the lane closest to a stopped emergency vehicle when it is safe, and slow down if you cannot, to protect the people working there.","p":"Right. Move over a lane when it is safe."},"es":{"q":"En Alabama, en una vía con dos o más carriles en su dirección, ¿qué debe hacer al pasar junto a una patrulla detenida con luces encendidas?","o":["Salir del carril de al lado si es seguro","Pararse detrás y esperar","Tocar la bocina y seguir igual","Acelerar para pasar rápido"],"h1":"Dé más espacio al vehículo detenido.","h2":"Según la ley de Alabama para apartarse (Move Over), usted debe salir del carril más cercano al vehículo de emergencia detenido cuando sea seguro, y bajar la velocidad si no puede, para proteger a las personas que trabajan allí.","p":"Correcto. Cámbiese de carril cuando sea seguro."},"zh":{"q":"在 Alabama，在你的方向有两条或更多车道的道路上，经过一辆车灯在闪的停着的警车时，你应该怎么做？","o":["安全时离开它旁边的车道","停在它后面等","按喇叭并保持速度","加速快点开过去"],"h1":"给停着的车更多空间。","h2":"根据 Alabama 的 Move Over 法，安全时你必须离开最靠近停着的急救车辆的车道，做不到就要减速，来保护在那里工作的人。","p":"对。安全时换开一条车道。"},"vi":{"q":"Ở Alabama, trên đường có hai làn trở lên cùng chiều với bạn, bạn nên làm gì khi đi qua một xe cảnh sát đang dừng và nháy đèn?","o":["Rời khỏi làn sát bên nó nếu an toàn","Dừng phía sau nó và chờ","Bấm còi và giữ tốc độ","Tăng tốc để vượt qua nhanh"],"h1":"Hãy chừa thêm chỗ cho xe đang dừng.","h2":"Theo luật Nhường Làn (Move Over law) ở Alabama, bạn phải rời khỏi làn gần nhất với xe khẩn cấp đang dừng khi an toàn, và giảm tốc độ nếu không thể chuyển làn, để bảo vệ những người đang làm việc ở đó.","p":"Đúng. Chuyển sang làn khác khi an toàn."},"tl":{"q":"Sa Alabama, sa kalsadang may dalawa o higit pang lane sa iyong direksyon, ano ang dapat mong gawin kapag dumadaan sa nakahintong sasakyan ng pulis na may kumikislap na ilaw?","o":["Lumipat mula sa lane na katabi nito kung ligtas","Huminto sa likod nito at maghintay","Bumusina at panatilihin ang bilis","Bumilis para madaanan ito agad"],"h1":"Bigyan ng mas maraming espasyo ang nakahintong sasakyan.","h2":"Ayon sa Move Over law ng Alabama, dapat kang umalis sa lane na pinakamalapit sa nakahintong emergency vehicle kapag ligtas, at magbagal kung hindi ka makalipat, para protektahan ang mga taong nagtatrabaho roon.","p":"Tama. Lumipat ng isang lane kapag ligtas."},"ar":{"q":"في Alabama، على طريق فيه مساران أو أكثر في اتجاهك، ماذا يجب أن تفعل عند المرور بسيارة شرطة متوقّفة وأضواؤها تومض؟","o":["انتقل من المسار المجاور لها إن كان ذلك آمنًا","توقّف خلفها وانتظر","اضغط على البوق وحافظ على سرعتك","زِد سرعتك لتتجاوزها بسرعة"],"h1":"أعطِ المركبة المتوقّفة مساحة أكبر.","h2":"بموجب قانون الابتعاد (Move Over law) في Alabama يجب أن تغادر المسار الأقرب إلى مركبة الطوارئ المتوقّفة عندما يكون ذلك آمنًا، وأن تُبطئ إن لم تستطع، لحماية الأشخاص الذين يعملون هناك.","p":"صحيح. انتقل مسارًا واحدًا عندما يكون ذلك آمنًا."},"ref":{"doc":"AL","page":68}},{"id":"al-020","scope":"AL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Alabama, if you cannot change lanes away from a stopped emergency vehicle and the limit is 25 mph or more, how much should you slow down?","o":["5 mph below the limit","15 mph below the limit","25 mph below the limit","To exactly 20 mph"],"h1":"It is more than 10 mph but less than 20 mph.","h2":"In Alabama, when you cannot move over and the posted limit is 25 mph or more, you must slow to at least 15 mph below the limit so you can react to people near the road.","p":"Right. Slow to 15 mph below the limit."},"es":{"q":"En Alabama, si no puede cambiarse de carril al pasar un vehículo de emergencia detenido y el límite es de 25 mph o más, ¿cuánto debe bajar la velocidad?","o":["5 mph menos que el límite","15 mph menos que el límite","25 mph menos que el límite","Exactamente a 20 mph"],"h1":"Es más de 10 mph pero menos de 20 mph.","h2":"En Alabama, cuando usted no puede apartarse y el límite es de 25 mph o más, debe bajar por lo menos a 15 mph menos que el límite, para poder reaccionar ante las personas cerca del camino.","p":"Correcto. Baje a 15 mph menos que el límite."},"zh":{"q":"在 Alabama，如果你无法换道离开停着的急救车辆，而限速是 25 mph 或更高，你应该减速多少？","o":["比限速低 5 mph","比限速低 15 mph","比限速低 25 mph","刚好 20 mph"],"h1":"它比 10 mph 多，但比 20 mph 少。","h2":"在 Alabama，你无法换道而标出的限速是 25 mph 或更高时，必须减速到至少比限速低 15 mph，这样你才能对路边的人做出反应。","p":"对。减速到比限速低 15 mph。"},"vi":{"q":"Ở Alabama, nếu bạn không thể chuyển làn tránh xa xe khẩn cấp đang dừng và tốc độ tối đa là 25 mph trở lên, bạn nên giảm tốc độ bao nhiêu?","o":["Thấp hơn tốc độ tối đa 5 mph","Thấp hơn tốc độ tối đa 15 mph","Thấp hơn tốc độ tối đa 25 mph","Đúng 20 mph"],"h1":"Hơn 10 mph nhưng ít hơn 20 mph.","h2":"Ở Alabama, khi bạn không thể chuyển làn và tốc độ tối đa ghi trên biển là 25 mph trở lên, bạn phải giảm xuống ít nhất 15 mph thấp hơn tốc độ tối đa để kịp phản ứng với người ở gần đường.","p":"Đúng. Giảm xuống thấp hơn tốc độ tối đa 15 mph."},"tl":{"q":"Sa Alabama, kung hindi ka makalipat ng lane palayo sa nakahintong emergency vehicle at ang limit ay 25 mph o higit pa, gaano ka dapat magbagal?","o":["5 mph na mas mababa sa limit","15 mph na mas mababa sa limit","25 mph na mas mababa sa limit","Eksaktong 20 mph"],"h1":"Higit ito sa 10 mph pero mas mababa sa 20 mph.","h2":"Sa Alabama, kapag hindi ka makalipat at ang nakapaskil na limit ay 25 mph o higit pa, dapat kang magbagal nang hindi bababa sa 15 mph na mas mababa sa limit para makatugon ka sa mga taong malapit sa kalsada.","p":"Tama. Magbagal sa 15 mph na mas mababa sa limit."},"ar":{"q":"في Alabama، إذا لم تستطع الابتعاد بتغيير المسار عن مركبة طوارئ متوقّفة وكان الحدّ 25 mph أو أكثر، فكم يجب أن تُبطئ؟","o":["5 mph أقل من الحدّ","15 mph أقل من الحدّ","25 mph أقل من الحدّ","إلى 20 mph بالضبط"],"h1":"إنه أكثر من 10 mph وأقل من 20 mph.","h2":"في Alabama، عندما لا تستطيع الابتعاد ويكون الحدّ المكتوب 25 mph أو أكثر، يجب أن تُبطئ إلى 15 mph على الأقل تحت الحدّ لتتمكّن من التصرّف بسرعة تجاه الأشخاص القريبين من الطريق.","p":"صحيح. أبطئ إلى 15 mph تحت الحدّ."},"ref":{"doc":"AL","page":68}},{"id":"al-021","scope":"AL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Alabama, which of these stopped vehicles with flashing lights is also covered by the Move Over law?","o":["A parked delivery van","A car stopped at a red light","A garbage or recycling truck","A bus at a regular bus stop"],"h1":"The law protects many roadside workers, not only police.","h2":"The Alabama Move Over law covers garbage and recycling trucks that are collecting on the roadside, as well as police, emergency, tow, utility, and road work vehicles with flashing lights.","p":"Right. Garbage and recycling trucks are covered."},"es":{"q":"En Alabama, ¿cuál de estos vehículos detenidos con luces intermitentes también está cubierto por la ley Move Over?","o":["Una camioneta de reparto estacionada","Un carro parado en un semáforo en rojo","Un camión de basura o reciclaje","Un autobús en su parada normal"],"h1":"La ley protege a muchos trabajadores en la orilla del camino, no solo a la policía.","h2":"La ley Move Over de Alabama incluye los camiones de basura y de reciclaje que están recogiendo al lado de la calle, además de los vehículos de policía, emergencia, grúa, servicios públicos y obras con luces intermitentes.","p":"Correcto. Los camiones de basura y reciclaje están incluidos."},"zh":{"q":"在 Alabama，下面哪一种车灯在闪的停着的车辆，也受 Move Over 法保护？","o":["停着的送货车","在红灯前停着的车","垃圾车或回收车","在一般公车站停着的公车"],"h1":"这条法律保护很多在路边工作的人，不只是警察。","h2":"Alabama 的 Move Over 法保护在路边收垃圾和回收物的垃圾车和回收车，也保护车灯在闪的警车、急救车、拖车、公用事业车和道路施工车。","p":"对。垃圾车和回收车也受保护。"},"vi":{"q":"Ở Alabama, xe nào sau đây đang dừng và nháy đèn cũng được bảo vệ bởi luật Nhường Làn (Move Over law)?","o":["Xe tải giao hàng đang đậu","Xe hơi dừng ở đèn đỏ","Xe chở rác hoặc xe tái chế","Xe buýt ở trạm xe buýt thường"],"h1":"Luật bảo vệ nhiều người làm việc bên đường, không chỉ cảnh sát.","h2":"Luật Nhường Làn ở Alabama bảo vệ xe chở rác và xe tái chế đang thu gom bên đường, cũng như xe cảnh sát, xe khẩn cấp, xe kéo, xe tiện ích, và xe làm đường có đèn nháy.","p":"Đúng. Xe chở rác và xe tái chế được bảo vệ."},"tl":{"q":"Sa Alabama, alin sa mga nakahintong sasakyang ito na may kumikislap na ilaw ang sakop din ng Move Over law?","o":["Nakaparadang delivery van","Kotseng nakahinto sa red light","Trak ng basura o recycling","Bus sa karaniwang hintuan ng bus"],"h1":"Pinoprotektahan ng batas ang maraming manggagawa sa gilid ng kalsada, hindi lang ang pulis.","h2":"Sakop ng Move Over law ng Alabama ang mga trak ng basura at recycling na nangongolekta sa gilid ng kalsada, pati ang mga sasakyan ng pulis, emergency, tow, utility, at road work na may kumikislap na ilaw.","p":"Tama. Sakop ang mga trak ng basura at recycling."},"ar":{"q":"في Alabama، أي من هذه المركبات المتوقّفة ذات الأضواء الوامضة يشملها أيضًا قانون الابتعاد (Move Over law)؟","o":["شاحنة توصيل متوقّفة","سيارة متوقّفة عند إشارة حمراء","شاحنة نفايات أو إعادة تدوير","حافلة في موقف حافلات عادي"],"h1":"القانون يحمي كثيرًا من العاملين على جانب الطريق، لا الشرطة فقط.","h2":"قانون الابتعاد في Alabama يشمل شاحنات النفايات وإعادة التدوير التي تجمع على جانب الطريق، وكذلك مركبات الشرطة والطوارئ والسحب والمرافق وأعمال الطرق ذات الأضواء الوامضة.","p":"صحيح. شاحنات النفايات وإعادة التدوير مشمولة."},"ref":{"doc":"AL","page":null}},{"id":"al-022","scope":"AL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Alabama, a school bus is stopped with red lights flashing on the other side of a four-lane highway divided by a median. What must you do?","o":["Stop until the bus moves","Stop, then pass at 10 mph","Pull onto the shoulder","Continue carefully without stopping"],"h1":"A median between you and the bus changes the rule.","h2":"In Alabama, on a divided highway with a median, only traffic going the same direction as the bus must stop, so you may continue carefully while watching for children.","p":"Right. With a median, opposite traffic continues with care."},"es":{"q":"En Alabama, un autobús escolar está detenido con luces rojas al otro lado de una carretera de cuatro carriles dividida por una mediana. ¿Qué debe hacer?","o":["Parar hasta que el autobús avance","Parar y luego pasar a 10 mph","Salirse al acotamiento","Seguir con cuidado sin parar"],"h1":"Una mediana entre usted y el autobús cambia la regla.","h2":"En Alabama, en una carretera dividida por una mediana, solo debe parar el tráfico que va en la misma dirección que el autobús, así que usted puede seguir con cuidado y atento a los niños.","p":"Correcto. Con mediana, el tráfico contrario sigue con cuidado."},"zh":{"q":"在 Alabama，一辆校车停在有中间隔离带的四车道公路的对面，红灯在闪。你必须怎么做？","o":["停车，直到校车开走","停车，然后以 10 mph 开过去","开到路肩上","小心地继续开，不用停车"],"h1":"你和校车之间有隔离带，规定就不一样。","h2":"在 Alabama，在有中间隔离带的分隔公路上，只有和校车同方向的车必须停车，所以你可以小心地继续开，同时注意孩子。","p":"对。有隔离带时，对面方向的车小心地继续开。"},"vi":{"q":"Ở Alabama, một xe buýt trường học đang dừng và nháy đèn đỏ ở phía bên kia của xa lộ bốn làn có dải phân cách giữa. Bạn phải làm gì?","o":["Dừng cho đến khi xe buýt chạy","Dừng, rồi vượt qua ở 10 mph","Tấp vào lề đường","Tiếp tục đi cẩn thận mà không dừng"],"h1":"Dải phân cách giữa bạn và xe buýt làm quy định thay đổi.","h2":"Ở Alabama, trên xa lộ có dải phân cách giữa, chỉ xe đi cùng chiều với xe buýt phải dừng, nên bạn có thể tiếp tục đi cẩn thận và để ý trẻ em.","p":"Đúng. Có dải phân cách, xe ngược chiều tiếp tục đi cẩn thận."},"tl":{"q":"Sa Alabama, may school bus na nakahinto na may kumikislap na pulang ilaw sa kabilang panig ng highway na may apat na lane at may median sa gitna. Ano ang dapat mong gawin?","o":["Huminto hanggang umandar ang bus","Huminto, saka dumaan sa 10 mph","Tumabi sa shoulder","Magpatuloy nang maingat nang hindi humihinto"],"h1":"Binabago ng median sa pagitan mo at ng bus ang patakaran.","h2":"Sa Alabama, sa divided highway na may median, ang mga sasakyang papunta lang sa parehong direksyon ng bus ang dapat huminto, kaya puwede kang magpatuloy nang maingat habang nagbabantay sa mga bata.","p":"Tama. Kapag may median, nagpapatuloy nang maingat ang kasalubong na trapiko."},"ar":{"q":"في Alabama، حافلة مدرسية متوقّفة وأضواؤها الحمراء تومض على الجانب الآخر من طريق سريع بأربعة مسارات يفصله حاجز وسطي. ماذا يجب أن تفعل؟","o":["توقّف حتى تتحرّك الحافلة","توقّف، ثم تجاوز بسرعة 10 mph","انتقل إلى كتف الطريق","تابع بحذر دون أن تتوقّف"],"h1":"وجود حاجز وسطي بينك وبين الحافلة يغيّر القاعدة.","h2":"في Alabama، على طريق سريع مقسوم بحاجز وسطي، يجب أن تتوقّف فقط المركبات التي تسير في نفس اتجاه الحافلة، لذلك يمكنك أن تتابع بحذر مع الانتباه إلى الأطفال.","p":"صحيح. مع وجود حاجز وسطي، تتابع حركة الاتجاه المقابل بحذر."},"ref":{"doc":"AL","page":61}},{"id":"al-023","scope":"AL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Alabama, a school bus stops with red lights flashing on a four-lane road with no median. Who must stop?","o":["Traffic in both directions","Only traffic behind the bus","Only traffic facing the bus","Only trucks and buses"],"h1":"Without a median, children may cross every lane.","h2":"In Alabama, on a four-lane road with no median, traffic in both directions must stop for a school bus with flashing red lights, because children may cross all the lanes.","p":"Right. Without a median, everyone stops."},"es":{"q":"En Alabama, un autobús escolar se detiene con luces rojas en una vía de cuatro carriles sin mediana. ¿Quién debe parar?","o":["El tráfico en ambas direcciones","Solo el tráfico detrás del autobús","Solo el tráfico de frente","Solo camiones y autobuses"],"h1":"Sin mediana, los niños pueden cruzar todos los carriles.","h2":"En Alabama, en una vía de cuatro carriles sin mediana, el tráfico en ambas direcciones debe parar ante un autobús escolar con luces rojas intermitentes, porque los niños pueden cruzar todos los carriles.","p":"Correcto. Sin mediana, todos paran."},"zh":{"q":"在 Alabama，一辆校车停在没有中间隔离带的四车道道路上，红灯在闪。谁必须停车？","o":["两个方向的车","只有校车后面的车","只有面对校车的车","只有卡车和公车"],"h1":"没有隔离带，孩子可能会穿过每一条车道。","h2":"在 Alabama，在没有中间隔离带的四车道道路上，两个方向的车都必须为红灯闪烁的校车停车，因为孩子可能会穿过所有车道。","p":"对。没有隔离带，大家都要停车。"},"vi":{"q":"Ở Alabama, một xe buýt trường học dừng và nháy đèn đỏ trên đường bốn làn không có dải phân cách giữa. Ai phải dừng?","o":["Xe ở cả hai chiều","Chỉ xe phía sau xe buýt","Chỉ xe đối diện xe buýt","Chỉ xe tải và xe buýt"],"h1":"Không có dải phân cách, trẻ em có thể băng qua mọi làn.","h2":"Ở Alabama, trên đường bốn làn không có dải phân cách giữa, xe ở cả hai chiều phải dừng khi xe buýt trường học nháy đèn đỏ, vì trẻ em có thể băng qua tất cả các làn.","p":"Đúng. Không có dải phân cách, mọi người đều dừng."},"tl":{"q":"Sa Alabama, huminto ang school bus na may kumikislap na pulang ilaw sa kalsadang may apat na lane na walang median. Sino ang dapat huminto?","o":["Trapiko sa parehong direksyon","Trapiko lang sa likod ng bus","Trapiko lang na nakaharap sa bus","Mga trak at bus lang"],"h1":"Kapag walang median, puwedeng tumawid ang mga bata sa lahat ng lane.","h2":"Sa Alabama, sa kalsadang may apat na lane na walang median, dapat huminto ang trapiko sa parehong direksyon para sa school bus na may kumikislap na pulang ilaw, dahil puwedeng tumawid ang mga bata sa lahat ng lane.","p":"Tama. Kapag walang median, lahat ay humihinto."},"ar":{"q":"في Alabama، تتوقّف حافلة مدرسية وأضواؤها الحمراء تومض على طريق بأربعة مسارات بدون حاجز وسطي. من يجب أن يتوقّف؟","o":["الحركة في الاتجاهين","الحركة خلف الحافلة فقط","الحركة المواجهة للحافلة فقط","الشاحنات والحافلات فقط"],"h1":"بدون حاجز وسطي، قد يعبر الأطفال كل المسارات.","h2":"في Alabama، على طريق بأربعة مسارات بدون حاجز وسطي، يجب أن تتوقّف الحركة في الاتجاهين من أجل حافلة مدرسية أضواؤها الحمراء تومض، لأن الأطفال قد يعبرون كل المسارات.","p":"صحيح. بدون حاجز وسطي، يتوقّف الجميع."},"ref":{"doc":"AL","page":61}},{"id":"al-024","scope":"AL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Under Alabama's hands-free law, when is holding a phone while driving a violation?","o":["Only on interstate highways","When you also drive poorly, like swerving","Only between midnight and 6 a.m.","Never, if you hold it below the window"],"h1":"Police look at how you drive while the phone is in your hand.","h2":"Under the Alabama hands-free law, holding a phone while driving is a violation when you are also seen driving poorly, such as swerving or changing lanes without a signal, so it is safest to keep the phone out of your hand.","p":"Right. Holding a phone breaks the law when you also drive poorly, like swerving."},"es":{"q":"Según la ley de manos libres de Alabama, ¿cuándo es una infracción sostener el teléfono mientras maneja?","o":["Solo en las autopistas interestatales","Cuando además maneja mal, como zigzaguear","Solo entre la medianoche y las 6 a.m.","Nunca, si lo sostiene debajo de la ventana"],"h1":"La policía se fija en cómo maneja usted mientras tiene el teléfono en la mano.","h2":"Según la ley de manos libres de Alabama, sostener el teléfono mientras maneja es una infracción cuando además lo ven manejando mal, por ejemplo zigzagueando o cambiando de carril sin señalar, así que lo más seguro es no tener el teléfono en la mano.","p":"Correcto. Sostener el teléfono es ilegal cuando además maneja mal, como zigzaguear."},"zh":{"q":"根据 Alabama 的免持（hands-free）法，开车时手拿电话什么时候算违规？","o":["只在州际公路上","同时开得不好时，比如左右乱晃","只在午夜到早上 6 点之间","从来不算，只要拿在车窗下面"],"h1":"警察会看你手拿电话时怎样开车。","h2":"根据 Alabama 的免持法，开车时手拿电话，如果同时被看到开得不好，比如左右乱晃或不打灯就换道，就算违规，所以最安全的做法是不要把电话拿在手里。","p":"对。手拿电话又开得不好，比如左右乱晃，就违法了。"},"vi":{"q":"Theo luật rảnh tay (hands-free law) của Alabama, khi nào cầm điện thoại lúc lái xe là vi phạm?","o":["Chỉ trên xa lộ liên bang","Khi bạn cũng lái kém, như lạng lách","Chỉ từ nửa đêm đến 6 giờ sáng","Không bao giờ, nếu cầm thấp dưới cửa sổ"],"h1":"Cảnh sát xem cách bạn lái xe khi điện thoại đang ở trong tay bạn.","h2":"Theo luật rảnh tay của Alabama, cầm điện thoại khi lái xe là vi phạm khi bạn cũng bị thấy lái xe kém, như lạng lách hoặc chuyển làn không bật đèn xi nhan, nên an toàn nhất là không cầm điện thoại trong tay.","p":"Đúng. Cầm điện thoại là phạm luật khi bạn cũng lái kém, như lạng lách."},"tl":{"q":"Ayon sa hands-free law ng Alabama, kailan paglabag ang paghawak ng telepono habang nagmamaneho?","o":["Sa mga interstate highway lang","Kapag mali rin ang pagmamaneho mo, gaya ng pagpapagewang-gewang","Mula hatinggabi hanggang 6 a.m. lang","Hindi kailanman, kung hawak mo ito sa ibaba ng bintana"],"h1":"Tinitingnan ng pulis kung paano ka nagmamaneho habang hawak mo ang telepono.","h2":"Ayon sa hands-free law ng Alabama, paglabag ang paghawak ng telepono habang nagmamaneho kapag nakita ka ring nagmamaneho nang mali, gaya ng pagpapagewang-gewang o paglipat ng lane nang walang signal, kaya pinakaligtas na huwag hawakan ang telepono.","p":"Tama. Labag sa batas ang paghawak ng telepono kapag mali rin ang pagmamaneho mo, gaya ng pagpapagewang-gewang."},"ar":{"q":"بموجب قانون القيادة بدون استخدام اليدين (hands-free law) في Alabama، متى يكون حمل الهاتف أثناء القيادة مخالفة؟","o":["على الطرق السريعة بين الولايات فقط","عندما تقود أيضًا بشكل سيئ، مثل التمايل","بين منتصف الليل و6 صباحًا فقط","أبدًا، إذا أمسكته تحت مستوى النافذة"],"h1":"تنظر الشرطة إلى طريقة قيادتك والهاتف في يدك.","h2":"بموجب قانون القيادة بدون استخدام اليدين في Alabama، يكون حمل الهاتف أثناء القيادة مخالفة عندما تُرى أيضًا تقود بشكل سيئ، مثل التمايل أو تغيير المسار بدون إشارة، لذلك الأكثر أمانًا أن تُبقي الهاتف خارج يدك.","p":"صحيح. حمل الهاتف مخالف للقانون عندما تقود أيضًا بشكل سيئ، مثل التمايل."},"ref":{"doc":"AL","page":16}},{"id":"al-025","scope":"AL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Alabama, is it legal for an adult driver to read or send a text message while driving?","o":["Yes, on straight roads","Yes, if the car is slow","No, texting is banned","Yes, for short messages"],"h1":"Texting takes your eyes off the road for several seconds.","h2":"Alabama bans writing, sending, or reading text messages while driving for every driver, because texting takes your eyes and mind off the road.","p":"Right. Texting while driving is against the law in Alabama."},"es":{"q":"En Alabama, ¿es legal que un conductor adulto lea o envíe un mensaje de texto mientras maneja?","o":["Sí, en caminos rectos","Sí, si va despacio","No, está prohibido","Sí, si el mensaje es corto"],"h1":"Escribir mensajes le quita la vista del camino varios segundos.","h2":"Alabama prohíbe a todos los conductores escribir, enviar o leer mensajes de texto mientras manejan, porque eso le quita la vista y la atención del camino.","p":"Correcto. En Alabama está prohibido escribir mensajes al manejar."},"zh":{"q":"在 Alabama，成年司机开车时看或发短信合法吗？","o":["合法，在直路上","合法，如果车开得慢","不合法，禁止发短信","合法，如果是短的信息"],"h1":"发短信会让你的眼睛离开道路好几秒。","h2":"Alabama 禁止所有司机开车时写、发或看短信，因为发短信会让你的眼睛和注意力离开道路。","p":"对。在 Alabama 开车时发短信是违法的。"},"vi":{"q":"Ở Alabama, người lái xe trưởng thành có được đọc hoặc gửi tin nhắn khi lái xe không?","o":["Được, trên đường thẳng","Được, nếu xe chạy chậm","Không, nhắn tin bị cấm","Được, với tin nhắn ngắn"],"h1":"Nhắn tin làm mắt bạn rời khỏi đường trong vài giây.","h2":"Alabama cấm mọi người lái xe viết, gửi, hoặc đọc tin nhắn khi lái xe, vì nhắn tin làm mắt và tâm trí bạn rời khỏi đường.","p":"Đúng. Nhắn tin khi lái xe là phạm luật ở Alabama."},"tl":{"q":"Sa Alabama, legal ba para sa adult na drayber na magbasa o magpadala ng text message habang nagmamaneho?","o":["Oo, sa tuwid na kalsada","Oo, kung mabagal ang sasakyan","Hindi, bawal ang pag-text","Oo, para sa maikling mensahe"],"h1":"Inilalayo ng pag-text ang mata mo sa kalsada nang ilang segundo.","h2":"Ipinagbabawal ng Alabama sa lahat ng drayber ang pagsulat, pagpapadala, o pagbabasa ng text message habang nagmamaneho, dahil inilalayo ng pag-text ang iyong mata at isip sa kalsada.","p":"Tama. Labag sa batas sa Alabama ang pag-text habang nagmamaneho."},"ar":{"q":"في Alabama، هل يجوز قانونًا للسائق البالغ أن يقرأ أو يرسل رسالة نصية أثناء القيادة؟","o":["نعم، على الطرق المستقيمة","نعم، إذا كانت السيارة بطيئة","لا، الرسائل النصية ممنوعة","نعم، للرسائل القصيرة"],"h1":"الرسائل النصية تُبعد عينيك عن الطريق عدة ثوانٍ.","h2":"تمنع Alabama كل السائقين من كتابة الرسائل النصية أو إرسالها أو قراءتها أثناء القيادة، لأن الرسائل النصية تُبعد عينيك وذهنك عن الطريق.","p":"صحيح. كتابة الرسائل النصية أثناء القيادة مخالفة للقانون في Alabama."},"ref":{"doc":"AL","page":32}},{"id":"al-026","scope":"AL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Alabama, a driver under 21 can be charged with DUI at what blood alcohol level?","o":["0.02 percent or more","0.05 percent or more","0.08 percent or more","0.10 percent or more"],"h1":"The limit for young drivers is far below the adult limit.","h2":"In Alabama a driver under 21 can be charged with DUI at a blood alcohol level of 0.02 percent, which is much lower than the adult limit, because young drivers should not drink at all.","p":"Right. Under 21, the limit is 0.02 percent."},"es":{"q":"En Alabama, ¿con qué nivel de alcohol en la sangre se puede acusar de manejar ebrio a un conductor menor de 21 años?","o":["0.02 por ciento o más","0.05 por ciento o más","0.08 por ciento o más","0.10 por ciento o más"],"h1":"El límite para los jóvenes es mucho más bajo que el de los adultos.","h2":"En Alabama a un conductor menor de 21 años se le puede acusar de manejar ebrio con 0.02 por ciento de alcohol en la sangre, mucho menos que el límite de los adultos, porque los jóvenes no deben tomar nada.","p":"Correcto. Para menores de 21, el límite es 0.02 por ciento."},"zh":{"q":"在 Alabama，21 岁以下的司机血液酒精浓度达到多少，就可能被控 DUI（酒后驾驶）？","o":["0.02% 或更高","0.05% 或更高","0.08% 或更高","0.10% 或更高"],"h1":"年轻司机的限制比成年人的低很多。","h2":"在 Alabama，21 岁以下的司机血液酒精浓度达到 0.02%，就可能被控 DUI，这比成年人的限制低很多，因为年轻司机根本不应该喝酒。","p":"对。21 岁以下，限制是 0.02%。"},"vi":{"q":"Ở Alabama, người lái dưới 21 tuổi có thể bị buộc tội lái xe khi say (DUI) ở nồng độ cồn trong máu bao nhiêu?","o":["0.02 phần trăm trở lên","0.05 phần trăm trở lên","0.08 phần trăm trở lên","0.10 phần trăm trở lên"],"h1":"Giới hạn cho người lái trẻ thấp hơn nhiều so với người lớn.","h2":"Ở Alabama, người lái dưới 21 tuổi có thể bị buộc tội DUI ở nồng độ cồn trong máu 0.02 phần trăm, thấp hơn nhiều so với giới hạn của người lớn, vì người lái trẻ hoàn toàn không nên uống rượu bia.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02 phần trăm."},"tl":{"q":"Sa Alabama, sa anong blood alcohol level puwedeng kasuhan ng DUI ang drayber na wala pang 21?","o":["0.02 porsiyento o higit pa","0.05 porsiyento o higit pa","0.08 porsiyento o higit pa","0.10 porsiyento o higit pa"],"h1":"Mas mababa nang malaki ang limit para sa mga batang drayber kaysa sa limit ng adult.","h2":"Sa Alabama, ang drayber na wala pang 21 ay puwedeng kasuhan ng DUI sa blood alcohol level na 0.02 porsiyento, na mas mababa nang malaki kaysa sa limit ng adult, dahil hindi talaga dapat uminom ang mga batang drayber.","p":"Tama. Kapag wala pang 21, ang limit ay 0.02 porsiyento."},"ar":{"q":"في Alabama، عند أي نسبة كحول في الدم يمكن اتهام سائق عمره أقل من 21 سنة بالقيادة تحت التأثير (DUI)؟","o":["0.02 بالمئة أو أكثر","0.05 بالمئة أو أكثر","0.08 بالمئة أو أكثر","0.10 بالمئة أو أكثر"],"h1":"الحدّ للسائقين الصغار أقل بكثير من حدّ البالغين.","h2":"في Alabama يمكن اتهام سائق عمره أقل من 21 سنة بالقيادة تحت التأثير (DUI) عند نسبة كحول في الدم 0.02 بالمئة، وهي أقل بكثير من حدّ البالغين، لأن السائقين الصغار يجب ألّا يشربوا الكحول إطلاقًا.","p":"صحيح. تحت 21 سنة، الحدّ هو 0.02 بالمئة."},"ref":{"doc":"AL","page":33}},{"id":"al-027","scope":"AL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Alabama, a driver age 21 or older is legally under the influence at what blood alcohol level?","o":["0.02 percent or more","0.05 percent or more","0.08 percent or more","0.15 percent or more"],"h1":"It is the same adult limit used in most states.","h2":"An Alabama driver age 21 or older is legally under the influence at a blood alcohol level of 0.08 percent or more, although alcohol can affect driving at lower levels too.","p":"Right. The adult limit is 0.08 percent."},"es":{"q":"En Alabama, un conductor de 21 años o más está legalmente bajo los efectos del alcohol, ¿a partir de qué nivel?","o":["0.02 por ciento o más","0.05 por ciento o más","0.08 por ciento o más","0.15 por ciento o más"],"h1":"Es el mismo límite para adultos que usan casi todos los estados.","h2":"En Alabama un conductor de 21 años o más está legalmente bajo los efectos del alcohol con 0.08 por ciento o más, aunque el alcohol puede afectar el manejo con niveles más bajos.","p":"Correcto. El límite para adultos es 0.08 por ciento."},"zh":{"q":"在 Alabama，21 岁或以上的司机，血液酒精浓度达到多少在法律上算酒后驾驶？","o":["0.02% 或更高","0.05% 或更高","0.08% 或更高","0.15% 或更高"],"h1":"它和大多数州用的成年人限制一样。","h2":"Alabama 21 岁或以上的司机，血液酒精浓度达到 0.08% 或更高，在法律上就算酒后驾驶，不过浓度更低时酒精也会影响开车。","p":"对。成年人的限制是 0.08%。"},"vi":{"q":"Ở Alabama, người lái từ 21 tuổi trở lên bị xem là say theo luật ở nồng độ cồn trong máu bao nhiêu?","o":["0.02 phần trăm trở lên","0.05 phần trăm trở lên","0.08 phần trăm trở lên","0.15 phần trăm trở lên"],"h1":"Đây là giới hạn người lớn giống ở hầu hết các tiểu bang.","h2":"Người lái ở Alabama từ 21 tuổi trở lên bị xem là say theo luật ở nồng độ cồn trong máu 0.08 phần trăm trở lên, dù rượu bia cũng có thể ảnh hưởng đến việc lái xe ở mức thấp hơn.","p":"Đúng. Giới hạn cho người lớn là 0.08 phần trăm."},"tl":{"q":"Sa Alabama, sa anong blood alcohol level itinuturing na lasing ayon sa batas ang drayber na 21 taong gulang pataas?","o":["0.02 porsiyento o higit pa","0.05 porsiyento o higit pa","0.08 porsiyento o higit pa","0.15 porsiyento o higit pa"],"h1":"Ito ang parehong limit ng adult na ginagamit sa karamihan ng estado.","h2":"Ang drayber sa Alabama na 21 taong gulang pataas ay itinuturing na lasing ayon sa batas sa blood alcohol level na 0.08 porsiyento o higit pa, kahit puwede ring maapektuhan ng alak ang pagmamaneho sa mas mababang level.","p":"Tama. Ang limit ng adult ay 0.08 porsiyento."},"ar":{"q":"في Alabama، عند أي نسبة كحول في الدم يُعدّ السائق الذي عمره 21 سنة أو أكثر تحت التأثير قانونيًا؟","o":["0.02 بالمئة أو أكثر","0.05 بالمئة أو أكثر","0.08 بالمئة أو أكثر","0.15 بالمئة أو أكثر"],"h1":"إنه نفس حدّ البالغين المستخدم في معظم الولايات.","h2":"السائق في Alabama الذي عمره 21 سنة أو أكثر يُعدّ تحت التأثير قانونيًا عند نسبة كحول في الدم 0.08 بالمئة أو أكثر، مع أن الكحول قد يؤثّر في القيادة عند نسب أقل أيضًا.","p":"صحيح. حدّ البالغين هو 0.08 بالمئة."},"ref":{"doc":"AL","page":33}},{"id":"al-028","scope":"AL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alabama, what is the minimum liability insurance for injury to one person in a crash?","o":["$10,000","$15,000","$20,000","$25,000"],"h1":"Alabama uses the same number for one person and for property damage.","h2":"Alabama requires at least $25,000 of liability coverage for injury to one person, as part of the 25/50/25 minimum that every driver must carry.","p":"Right. The minimum is $25,000 per person."},"es":{"q":"En Alabama, ¿cuál es el seguro de responsabilidad mínimo por lesiones a una persona en un choque?","o":["$10,000","$15,000","$20,000","$25,000"],"h1":"Alabama usa el mismo número para una persona y para daños a la propiedad.","h2":"Alabama exige por lo menos $25,000 de cobertura de responsabilidad por lesiones a una persona, como parte del mínimo de 25/50/25 que todo conductor debe tener.","p":"Correcto. El mínimo es $25,000 por persona."},"zh":{"q":"在 Alabama，车祸中一个人受伤的最低责任保险是多少？","o":["$10,000","$15,000","$20,000","$25,000"],"h1":"Alabama 对一个人和对财产损失用同一个数字。","h2":"Alabama 要求一个人受伤至少要有 $25,000 的责任保险，这是每位司机都必须买的 25/50/25 最低标准的一部分。","p":"对。最低标准是每人 $25,000。"},"vi":{"q":"Ở Alabama, bảo hiểm trách nhiệm tối thiểu cho thương tích của một người trong một vụ tai nạn là bao nhiêu?","o":["$10,000","$15,000","$20,000","$25,000"],"h1":"Alabama dùng cùng một con số cho một người và cho thiệt hại tài sản.","h2":"Alabama yêu cầu ít nhất $25,000 bảo hiểm trách nhiệm cho thương tích của một người, là một phần của mức tối thiểu 25/50/25 mà mọi người lái phải có.","p":"Đúng. Mức tối thiểu là $25,000 cho mỗi người."},"tl":{"q":"Sa Alabama, ano ang minimum na liability insurance para sa pinsala sa isang tao sa banggaan?","o":["$10,000","$15,000","$20,000","$25,000"],"h1":"Pareho ang bilang na ginagamit ng Alabama para sa isang tao at para sa pinsala sa ari-arian.","h2":"Hinihingi ng Alabama ang hindi bababa sa $25,000 na liability coverage para sa pinsala sa isang tao, bilang bahagi ng 25/50/25 na minimum na dapat taglayin ng bawat drayber.","p":"Tama. Ang minimum ay $25,000 bawat tao."},"ar":{"q":"في Alabama، ما الحدّ الأدنى لتأمين المسؤولية عن إصابة شخص واحد في حادث؟","o":["$10,000","$15,000","$20,000","$25,000"],"h1":"تستخدم Alabama نفس الرقم لشخص واحد ولأضرار الممتلكات.","h2":"تشترط Alabama تغطية مسؤولية لا تقل عن $25,000 لإصابة شخص واحد، كجزء من الحدّ الأدنى 25/50/25 الذي يجب أن يحمله كل سائق.","p":"صحيح. الحدّ الأدنى هو $25,000 لكل شخص."},"ref":{"doc":"AL","page":68}},{"id":"al-029","scope":"AL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Alabama, when must your headlights be on during the day?","o":["Only on interstates","When wipers are on for rain","Only in school zones","When the radio is off"],"h1":"Think about bad weather.","h2":"In Alabama your headlights must be on when you use your windshield wipers because of rain, sleet, or snow, so other drivers can see you.","p":"Right. Wipers on for rain means headlights on."},"es":{"q":"En Alabama, ¿cuándo debe tener las luces delanteras encendidas durante el día?","o":["Solo en las interestatales","Con los limpiaparabrisas por lluvia","Solo en zonas escolares","Cuando el radio está apagado"],"h1":"Piense en el mal tiempo.","h2":"En Alabama usted debe encender las luces delanteras cuando usa los limpiaparabrisas por lluvia, aguanieve o nieve, para que los demás conductores lo vean.","p":"Correcto. Si usa los limpiaparabrisas por lluvia, encienda las luces."},"zh":{"q":"在 Alabama，白天什么时候必须打开大灯？","o":["只在州际公路上","因为下雨打开雨刷时","只在学校区","收音机关着时"],"h1":"想一想坏天气。","h2":"在 Alabama，因为下雨、冻雨或下雪而用雨刷时，你必须打开大灯，这样其他司机能看到你。","p":"对。下雨开雨刷，就要开大灯。"},"vi":{"q":"Ở Alabama, khi nào bạn phải bật đèn pha vào ban ngày?","o":["Chỉ trên xa lộ liên bang","Khi bật cần gạt nước vì mưa","Chỉ trong khu trường học","Khi tắt radio"],"h1":"Hãy nghĩ đến thời tiết xấu.","h2":"Ở Alabama, bạn phải bật đèn pha khi dùng cần gạt nước vì mưa, mưa đá nhỏ, hoặc tuyết, để các người lái khác có thể thấy bạn.","p":"Đúng. Bật cần gạt nước vì mưa thì phải bật đèn pha."},"tl":{"q":"Sa Alabama, kailan dapat nakabukas ang iyong headlights sa araw?","o":["Sa mga interstate lang","Kapag nakabukas ang wipers dahil sa ulan","Sa mga school zone lang","Kapag nakapatay ang radyo"],"h1":"Isipin ang masamang panahon.","h2":"Sa Alabama, dapat nakabukas ang iyong headlights kapag ginagamit mo ang windshield wipers dahil sa ulan, sleet, o niyebe, para makita ka ng ibang drayber.","p":"Tama. Kapag nakabukas ang wipers dahil sa ulan, buksan ang headlights."},"ar":{"q":"في Alabama، متى يجب أن تكون المصابيح الأمامية مضاءة في النهار؟","o":["على الطرق السريعة بين الولايات فقط","عند تشغيل المسّاحات بسبب المطر","في مناطق المدارس فقط","عندما يكون الراديو مطفأ"],"h1":"فكّر في الطقس السيئ.","h2":"في Alabama يجب أن تكون مصابيحك الأمامية مضاءة عندما تستخدم مسّاحات الزجاج الأمامي بسبب المطر أو المطر المتجمّد أو الثلج، ليتمكّن السائقون الآخرون من رؤيتك.","p":"صحيح. تشغيل المسّاحات بسبب المطر يعني تشغيل المصابيح الأمامية."},"ref":{"doc":"AL","page":71}},{"id":"al-030","scope":"AL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Alabama, how close to the nearest rail of a railroad crossing may you park?","o":["10 feet","25 feet","50 feet","100 feet"],"h1":"It is farther than the distance for a fire hydrant.","h2":"In Alabama you may not park within 50 feet of the nearest rail of a railroad crossing.","p":"Right. Stay at least 50 feet from the tracks when you park."},"es":{"q":"En Alabama, ¿a qué distancia del riel más cercano de un cruce de ferrocarril puede estacionarse?","o":["10 pies","25 pies","50 pies","100 pies"],"h1":"Es más lejos que la distancia para un hidrante.","h2":"En Alabama usted no puede estacionarse a menos de 50 pies del riel más cercano de un cruce de ferrocarril.","p":"Correcto. Quédese por lo menos a 50 pies de las vías al estacionarse."},"zh":{"q":"在 Alabama，停车时离铁路道口最近的铁轨至少要多远？","o":["10 英尺","25 英尺","50 英尺","100 英尺"],"h1":"这个距离比离消防栓的距离更远。","h2":"在 Alabama，你不可以在离铁路道口最近的铁轨 50 英尺以内停车。","p":"对。停车时要离铁轨至少 50 英尺。"},"vi":{"q":"Ở Alabama, bạn được đỗ xe cách đường ray gần nhất của chỗ giao với đường sắt bao xa?","o":["10 feet","25 feet","50 feet","100 feet"],"h1":"Khoảng cách này xa hơn khoảng cách với trụ nước cứu hỏa.","h2":"Ở Alabama, bạn không được đỗ xe trong vòng 50 feet tính từ đường ray gần nhất của chỗ giao với đường sắt.","p":"Đúng. Khi đỗ xe, hãy cách đường ray ít nhất 50 feet."},"tl":{"q":"Sa Alabama, gaano kalapit sa pinakamalapit na riles ng tawiran ng tren ka puwedeng pumarada?","o":["10 talampakan","25 talampakan","50 talampakan","100 talampakan"],"h1":"Mas malayo ito kaysa sa layo para sa fire hydrant.","h2":"Sa Alabama, hindi ka puwedeng pumarada sa loob ng 50 talampakan mula sa pinakamalapit na riles ng tawiran ng tren.","p":"Tama. Pumarada nang hindi bababa sa 50 talampakan mula sa riles."},"ar":{"q":"في Alabama، على أي مسافة من أقرب سكة في معبر السكة الحديدية يمكنك أن تركن سيارتك؟","o":["10 أقدام","25 قدمًا","50 قدمًا","100 قدم"],"h1":"هذه المسافة أبعد من المسافة المطلوبة عن حنفية الإطفاء.","h2":"في Alabama لا يجوز لك أن تركن سيارتك على مسافة أقل من 50 قدمًا من أقرب سكة في معبر السكة الحديدية.","p":"صحيح. ابقَ على بعد 50 قدمًا على الأقل من السكة عندما تركن."},"ref":{"doc":"AL","page":29}},{"id":"al-031","scope":"AL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Alabama, you are driving at night behind another car. Within what distance must you dim your high beams?","o":["200 feet","50 feet","1,000 feet","1 mile"],"h1":"The distance is shorter than for a car coming toward you.","h2":"In Alabama you must dim your headlights when you are within 200 feet of a vehicle you are following.","p":"Right. Use low beams within 200 feet of the car ahead."},"es":{"q":"En Alabama, usted maneja de noche detrás de otro carro. ¿A qué distancia debe bajar las luces altas?","o":["200 pies","50 pies","1,000 pies","1 milla"],"h1":"La distancia es menor que para un carro que viene de frente.","h2":"En Alabama usted debe bajar las luces cuando está a 200 pies o menos de un vehículo que va delante.","p":"Correcto. Use las luces bajas a 200 pies del carro de adelante."},"zh":{"q":"在 Alabama，你晚上开车跟在另一辆车后面。在多远的距离内你必须把远光灯调暗？","o":["200 英尺","50 英尺","1,000 英尺","1 英里"],"h1":"这个距离比迎面来车的距离短。","h2":"在 Alabama，当你离前面跟着的车辆 200 英尺以内时，你必须把车灯调暗。","p":"对。离前车 200 英尺以内要用近光灯。"},"vi":{"q":"Ở Alabama, bạn đang lái xe ban đêm phía sau một xe khác. Trong khoảng cách nào bạn phải giảm đèn pha xuống đèn cốt?","o":["200 feet","50 feet","1,000 feet","1 dặm"],"h1":"Khoảng cách này ngắn hơn so với khi có xe chạy ngược chiều về phía bạn.","h2":"Ở Alabama, bạn phải giảm đèn pha khi bạn ở trong vòng 200 feet phía sau một xe bạn đang đi theo.","p":"Đúng. Dùng đèn cốt khi cách xe phía trước trong vòng 200 feet."},"tl":{"q":"Sa Alabama, nagmamaneho ka sa gabi sa likod ng ibang kotse. Sa loob ng anong layo mo kailangang ibaba ang high beams mo?","o":["200 talampakan","50 talampakan","1,000 talampakan","1 milya"],"h1":"Mas maikli ang layo kaysa sa kotseng papalapit sa iyo.","h2":"Sa Alabama, kailangan mong ibaba ang ilaw mo kapag nasa loob ka ng 200 talampakan mula sa sasakyang sinusundan mo.","p":"Tama. Gumamit ng low beams sa loob ng 200 talampakan mula sa kotse sa unahan."},"ar":{"q":"في Alabama، أنت تقود ليلًا خلف سيارة أخرى. ضمن أي مسافة يجب أن تخفّض الأضواء العالية؟","o":["200 قدم","50 قدمًا","1,000 قدم","1 ميل"],"h1":"هذه المسافة أقصر من المسافة عندما تأتي سيارة نحوك.","h2":"في Alabama يجب أن تخفّض أضواء سيارتك عندما تكون على مسافة 200 قدم أو أقل من مركبة تسير خلفها.","p":"صحيح. استعمل الأضواء المنخفضة ضمن 200 قدم من السيارة التي أمامك."},"ref":{"doc":"AL","page":69}},{"id":"al-032","scope":"AL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alabama, how early can you renew your driver license before it expires?","o":["Up to 30 days before","Up to 90 days before","Up to 180 days before","Up to 2 years before"],"h1":"The renewal window is longer than three months but much less than a year.","h2":"In Alabama you may renew your driver license at any time within 180 days before it expires.","p":"Right. You can renew up to 180 days early."},"es":{"q":"En Alabama, ¿con cuánta anticipación puede renovar su licencia de manejar antes de que venza?","o":["Hasta 30 días antes","Hasta 90 días antes","Hasta 180 días antes","Hasta 2 años antes"],"h1":"El plazo para renovar es de más de tres meses, pero mucho menos de un año.","h2":"En Alabama usted puede renovar su licencia de manejar en cualquier momento dentro de los 180 días antes de que venza.","p":"Correcto. Puede renovar hasta 180 días antes."},"ref":{"doc":"AL","page":13}},{"id":"al-033","scope":"AL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alabama, up to how long after your license expires can you renew it without taking the tests again?","o":["6 months","1 year","2 years","3 years"],"h1":"It is more than two years.","h2":"In Alabama you can renew an expired driver license without an exam for up to 3 years after it expired.","p":"Right. You have up to 3 years to renew without a test."},"es":{"q":"En Alabama, ¿hasta cuánto tiempo después de que vence su licencia puede renovarla sin volver a tomar los exámenes?","o":["6 meses","1 año","2 años","3 años"],"h1":"Es más de dos años.","h2":"En Alabama usted puede renovar una licencia vencida sin examen hasta 3 años después de que venció.","p":"Correcto. Tiene hasta 3 años para renovar sin examen."},"ref":{"doc":"AL","page":13}},{"id":"al-034","scope":"AL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alabama, after you move to a new address in the state, how many days do you have to tell the Driver License Division?","o":["10 days","15 days","60 days","30 days"],"h1":"It is about one month.","h2":"In Alabama you must report your new address to the Driver License Division within 30 days after you move.","p":"Right. Report a new address within 30 days."},"es":{"q":"En Alabama, después de mudarse a una nueva dirección dentro del estado, ¿cuántos días tiene para avisar a la División de Licencias de Manejar?","o":["10 días","15 días","60 días","30 días"],"h1":"Es más o menos un mes.","h2":"En Alabama usted debe informar su nueva dirección a la División de Licencias de Manejar dentro de los 30 días después de mudarse.","p":"Correcto. Informe la nueva dirección dentro de 30 días."},"ref":{"doc":"AL","page":14}},{"id":"al-035","scope":"AL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alabama, how much is the fee for each written knowledge test?","o":["$5","$25","$10","$50"],"h1":"It is the smallest amount on the list.","h2":"In Alabama each knowledge test costs $5, and checks are not accepted.","p":"Right. Each knowledge test costs $5."},"es":{"q":"En Alabama, ¿cuánto cuesta cada examen escrito de conocimientos?","o":["$5","$25","$10","$50"],"h1":"Es la cantidad más pequeña de la lista.","h2":"En Alabama cada examen de conocimientos cuesta $5, y no se aceptan cheques.","p":"Correcto. Cada examen de conocimientos cuesta $5."},"ref":{"doc":"AL","page":11}},{"id":"al-036","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, who must come with a 16-year-old applicant to the road test?","o":["Any friend with a license","A parent or guardian","A driving school teacher","No one; they may come alone"],"h1":"It is the adult who is legally responsible for the teen.","h2":"In Alabama a 16-year-old must be accompanied by a parent or guardian when taking the road test.","p":"Right. A parent or guardian must come along."},"es":{"q":"En Alabama, ¿quién debe acompañar a un solicitante de 16 años al examen de manejo?","o":["Cualquier amigo con licencia","Un padre, madre o tutor","Un maestro de escuela de manejo","Nadie; puede ir solo"],"h1":"Es el adulto que es legalmente responsable del joven.","h2":"En Alabama un joven de 16 años debe ir acompañado de su padre, madre o tutor para tomar el examen de manejo.","p":"Correcto. Debe ir un padre, madre o tutor."},"ref":{"doc":"AL","page":11}},{"id":"al-037","scope":"AL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alabama, what is the penalty for a first conviction under the hands-free law?","o":["A $25 fine and no points","A $100 fine and 2 points","A $50 fine and 1 point","A $150 fine and 3 points"],"h1":"The penalty grows with each conviction, and this is the first step.","h2":"In Alabama a first hands-free law conviction brings a $50 fine and 1 point on your driving record.","p":"Right. The first conviction is $50 and 1 point."},"es":{"q":"En Alabama, ¿cuál es la sanción por una primera condena bajo la ley de manos libres?","o":["Una multa de $25 y ningún punto","Una multa de $100 y 2 puntos","Una multa de $50 y 1 punto","Una multa de $150 y 3 puntos"],"h1":"La sanción aumenta con cada condena, y este es el primer paso.","h2":"En Alabama una primera condena por la ley de manos libres trae una multa de $50 y 1 punto en su historial de manejo.","p":"Correcto. La primera condena es $50 y 1 punto."},"ref":{"doc":"AL","page":16}},{"id":"al-038","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, how many points go on your driving record for each texting-while-driving offense?","o":["1 point","2 points","4 points","6 points"],"h1":"It is the same number for the first, second, and third offense.","h2":"In Alabama each texting-while-driving offense puts 2 points on your driving record, in addition to a fine.","p":"Right. Each texting offense adds 2 points."},"es":{"q":"En Alabama, ¿cuántos puntos se ponen en su historial de manejo por cada infracción de enviar mensajes de texto mientras maneja?","o":["1 punto","2 puntos","4 puntos","6 puntos"],"h1":"Es el mismo número para la primera, la segunda y la tercera infracción.","h2":"En Alabama cada infracción por enviar mensajes de texto mientras maneja pone 2 puntos en su historial, además de una multa.","p":"Correcto. Cada infracción por textear suma 2 puntos."},"ref":{"doc":"AL","page":32}},{"id":"al-039","scope":"AL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alabama, how many points are added to your record for passing a stopped school bus?","o":["2 points","3 points","4 points","5 points"],"h1":"It is one of the highest point values for a moving violation.","h2":"In Alabama passing a stopped school bus adds 5 points to your driving record.","p":"Right. Passing a stopped school bus costs 5 points."},"es":{"q":"En Alabama, ¿cuántos puntos se agregan a su historial por pasar un autobús escolar detenido?","o":["2 puntos","3 puntos","4 puntos","5 puntos"],"h1":"Es uno de los valores de puntos más altos para una infracción de tránsito.","h2":"En Alabama pasar un autobús escolar detenido agrega 5 puntos a su historial de manejo.","p":"Correcto. Pasar un autobús escolar detenido cuesta 5 puntos."},"ref":{"doc":"AL","page":19}},{"id":"al-040","scope":"AL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alabama, how many points are added for speeding 1 to 25 mph over the limit?","o":["2 points","5 points","6 points","8 points"],"h1":"It is the lowest point value on Alabama's list.","h2":"In Alabama a speeding ticket for 1 to 25 mph over the limit adds 2 points, while 26 mph or more over adds 5 points.","p":"Right. Speeding up to 25 mph over is 2 points."},"es":{"q":"En Alabama, ¿cuántos puntos se agregan por exceder el límite de velocidad por 1 a 25 mph?","o":["2 puntos","5 puntos","6 puntos","8 puntos"],"h1":"Es el valor de puntos más bajo de la lista de Alabama.","h2":"En Alabama una multa por exceder el límite por 1 a 25 mph agrega 2 puntos, y por 26 mph o más agrega 5 puntos.","p":"Correcto. Exceder hasta 25 mph son 2 puntos."},"ref":{"doc":"AL","page":19}},{"id":"al-041","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, a driver who gets 12 to 14 points within 2 years has the license suspended for how long?","o":["30 days","60 days","6 months","1 year"],"h1":"It is the shortest suspension in the point schedule, about two months.","h2":"In Alabama a driver with 12 to 14 points in a 2-year period has the license suspended for 60 days.","p":"Right. 12 to 14 points means a 60-day suspension."},"es":{"q":"En Alabama, a un conductor que acumula de 12 a 14 puntos en 2 años, ¿por cuánto tiempo le suspenden la licencia?","o":["30 días","60 días","6 meses","1 año"],"h1":"Es la suspensión más corta de la tabla de puntos, más o menos dos meses.","h2":"En Alabama a un conductor con 12 a 14 puntos en un período de 2 años le suspenden la licencia por 60 días.","p":"Correcto. De 12 a 14 puntos significa una suspensión de 60 días."},"ref":{"doc":"AL","page":19}},{"id":"al-042","scope":"AL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Alabama, after a first DUI conviction, how long is the driver license suspended?","o":["90 days","30 days","1 year","3 years"],"h1":"It is about three months.","h2":"In Alabama a first DUI conviction brings a 90-day license suspension, in addition to a fine and possible jail time.","p":"Right. A first DUI means a 90-day suspension."},"es":{"q":"En Alabama, después de una primera condena por manejar bajo los efectos (DUI), ¿por cuánto tiempo se suspende la licencia?","o":["90 días","30 días","1 año","3 años"],"h1":"Son más o menos tres meses.","h2":"En Alabama una primera condena por DUI trae una suspensión de la licencia de 90 días, además de una multa y posible cárcel.","p":"Correcto. Un primer DUI significa una suspensión de 90 días."},"ref":{"doc":"AL","page":33}},{"id":"al-043","scope":"AL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Alabama, after a third DUI conviction, how long is the driver license revoked?","o":["6 months","1 year","3 years","Only until the fine is paid"],"h1":"It is several years, but less than the revocation for a fourth conviction.","h2":"In Alabama a third DUI conviction brings a 3-year license revocation, along with a large fine and at least 60 days in jail.","p":"Right. A third DUI means a 3-year revocation."},"es":{"q":"En Alabama, después de una tercera condena por DUI, ¿por cuánto tiempo se revoca la licencia?","o":["6 meses","1 año","3 años","Solo hasta pagar la multa"],"h1":"Son varios años, pero menos que la revocación por una cuarta condena.","h2":"En Alabama una tercera condena por DUI trae una revocación de la licencia por 3 años, además de una multa grande y por lo menos 60 días de cárcel.","p":"Correcto. Un tercer DUI significa una revocación de 3 años."},"ref":{"doc":"AL","page":34}},{"id":"al-044","scope":"AL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alabama, at least how much is the fee to reinstate a license that was suspended or revoked?","o":["$100","$20","$50","$10"],"h1":"It is the largest amount on the list.","h2":"In Alabama you must pay a reinstatement fee of at least $100, plus meet other legal requirements, to get back a suspended or revoked license.","p":"Right. Reinstatement costs at least $100."},"es":{"q":"En Alabama, ¿cuánto cuesta como mínimo la cuota para restablecer una licencia suspendida o revocada?","o":["$100","$20","$50","$10"],"h1":"Es la cantidad más grande de la lista.","h2":"En Alabama usted debe pagar una cuota de restablecimiento de por lo menos $100, y cumplir otros requisitos legales, para recuperar una licencia suspendida o revocada.","p":"Correcto. El restablecimiento cuesta por lo menos $100."},"ref":{"doc":"AL","page":17}},{"id":"al-045","scope":"AL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alabama, what is the highest fine for a first conviction of driving without the required liability insurance?","o":["$100","$250","$500","$5,000"],"h1":"A second conviction can cost up to twice this amount.","h2":"In Alabama a first conviction for not having the required liability insurance can bring a fine of up to $500.","p":"Right. The first offense fine is up to $500."},"es":{"q":"En Alabama, ¿cuál es la multa máxima por una primera condena por manejar sin el seguro de responsabilidad obligatorio?","o":["$100","$250","$500","$5,000"],"h1":"Una segunda condena puede costar hasta el doble de esta cantidad.","h2":"En Alabama una primera condena por no tener el seguro de responsabilidad obligatorio puede traer una multa de hasta $500.","p":"Correcto. La multa por la primera vez es de hasta $500."},"ref":{"doc":"AL","page":68}},{"id":"al-046","scope":"AL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Alabama, what is the least space you must leave between your car and a person on a bicycle when you pass?","o":["1 foot","18 inches","2 feet","3 feet"],"h1":"It is about one yard, the largest choice here.","h2":"In Alabama you must leave at least 3 feet between your vehicle and a person on a bicycle when you pass.","p":"Right. Give a bicycle rider at least 3 feet."},"es":{"q":"En Alabama, ¿cuál es el espacio mínimo que debe dejar entre su carro y una persona en bicicleta al pasarla?","o":["1 pie","18 pulgadas","2 pies","3 pies"],"h1":"Es más o menos una yarda, la opción más grande aquí.","h2":"En Alabama usted debe dejar por lo menos 3 pies entre su vehículo y una persona en bicicleta al pasarla.","p":"Correcto. Deje por lo menos 3 pies al ciclista."},"ref":{"doc":"AL","page":24}},{"id":"al-047","scope":"AL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Alabama, bicycle riders under what age must wear a helmet on public roads?","o":["Under 12","Under 16","Under 18","Under 21"],"h1":"It covers younger teens, but not all teenagers.","h2":"In Alabama bicycle riders under 16 must wear a fastened helmet on public roads, bike paths, and in public parks.","p":"Right. Riders under 16 must wear a helmet."},"es":{"q":"En Alabama, ¿los ciclistas menores de qué edad deben usar casco en las vías públicas?","o":["Menores de 12","Menores de 16","Menores de 18","Menores de 21"],"h1":"Incluye a los adolescentes más jóvenes, pero no a todos los adolescentes.","h2":"En Alabama los ciclistas menores de 16 años deben usar un casco abrochado en las vías públicas, las ciclovías y los parques públicos.","p":"Correcto. Los menores de 16 deben usar casco."},"ref":{"doc":"AL","page":24}},{"id":"al-048","scope":"AL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Alabama, until what age must a child ride in a booster seat?","o":["3 years old","4 years old","6 years old","10 years old"],"h1":"It is the age when many children start first grade.","h2":"In Alabama a child must use a booster seat until age 6, and then a seat belt through age 15.","p":"Right. Booster seats are required until age 6."},"es":{"q":"En Alabama, ¿hasta qué edad debe un niño viajar en un asiento elevado (booster)?","o":["3 años","4 años","6 años","10 años"],"h1":"Es la edad en que muchos niños empiezan el primer grado.","h2":"En Alabama un niño debe usar un asiento elevado hasta los 6 años, y después el cinturón de seguridad hasta los 15 años.","p":"Correcto. El asiento elevado es obligatorio hasta los 6 años."},"ref":{"doc":"AL","page":30}},{"id":"al-049","scope":"AL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Alabama, how close to a fire hydrant may you park?","o":["No closer than 10 feet","No closer than 15 feet","No closer than 30 feet","No closer than 50 feet"],"h1":"It is closer than the distance for a railroad crossing.","h2":"In Alabama you may not park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a fire hydrant."},"es":{"q":"En Alabama, ¿a qué distancia de un hidrante puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 15 pies","No más cerca de 30 pies","No más cerca de 50 pies"],"h1":"Es más cerca que la distancia para un cruce de ferrocarril.","h2":"En Alabama usted no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese por lo menos a 15 pies de un hidrante."},"ref":{"doc":"AL","page":29}},{"id":"al-050","scope":"AL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Alabama, your headlights must be on whenever you cannot see clearly for at least how far ahead?","o":["100 feet","200 feet","300 feet","500 feet"],"h1":"It is the longest distance on the list.","h2":"In Alabama headlights must be on from a half hour after sunset to a half hour before sunrise, and any time you cannot see clearly for at least 500 feet.","p":"Right. Turn on headlights when you cannot see 500 feet ahead."},"es":{"q":"En Alabama, sus luces delanteras deben estar encendidas siempre que no pueda ver claramente por lo menos ¿a qué distancia?","o":["100 pies","200 pies","300 pies","500 pies"],"h1":"Es la distancia más larga de la lista.","h2":"En Alabama las luces delanteras deben estar encendidas desde media hora después de la puesta del sol hasta media hora antes del amanecer, y siempre que no pueda ver claramente por lo menos a 500 pies.","p":"Correcto. Encienda las luces cuando no pueda ver a 500 pies."},"ref":{"doc":"AL","page":69}},{"id":"al-051","scope":"AL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Alabama, what can you dial on a cell phone to reach the State Troopers about a crash or a drunk driver?","o":["*HP (*47)","*DL (*35)","#77","*411"],"h1":"It starts with a star, then two letters that stand for the troopers' patrol.","h2":"In Alabama you can dial *HP, which is *47, on a cell phone to reach the State Troopers for highway emergencies, crashes, and drunk drivers.","p":"Right. Dial *HP (*47) to reach the State Troopers."},"es":{"q":"En Alabama, ¿qué número puede marcar en un celular para comunicarse con la Policía Estatal (State Troopers) por un choque o un conductor ebrio?","o":["*HP (*47)","*DL (*35)","#77","*411"],"h1":"Empieza con una estrella y luego dos letras que representan la patrulla de los troopers.","h2":"En Alabama usted puede marcar *HP, que es *47, en un celular para comunicarse con la Policía Estatal por emergencias en la carretera, choques y conductores ebrios.","p":"Correcto. Marque *HP (*47) para comunicarse con la Policía Estatal."},"ref":{"doc":"AL","page":76}},{"id":"ar-001","scope":"AR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arkansas, what is the youngest age to get a learner's license?","o":["14 years old","15 years old","16 years old","13 years old"],"h1":"Arkansas lets teens start earlier than many other states.","h2":"In Arkansas, the learner's license is for teens who are 14 or 15 years old, so 14 is the youngest age.","p":"Right. The Arkansas learner's license starts at age 14."},"es":{"q":"En Arkansas, ¿cuál es la edad mínima para obtener la licencia de aprendiz?","o":["14 años","15 años","16 años","13 años"],"h1":"Arkansas permite empezar antes que muchos otros estados.","h2":"En Arkansas, la licencia de aprendiz es para jóvenes de 14 o 15 años, así que 14 es la edad mínima.","p":"Correcto. La licencia de aprendiz en Arkansas empieza a los 14 años."},"zh":{"q":"在 Arkansas，最小几岁可以拿到学习驾照？","o":["14 岁","15 岁","16 岁","13 岁"],"h1":"Arkansas 让青少年比很多其他州更早开始。","h2":"在 Arkansas，学习驾照是给 14 岁或 15 岁的青少年的，所以最小年龄是 14 岁。","p":"对。Arkansas 的学习驾照从 14 岁开始。"},"vi":{"q":"Ở Arkansas, tuổi nhỏ nhất để có giấy phép học lái (learner's license) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","13 tuổi"],"h1":"Arkansas cho thanh thiếu niên bắt đầu sớm hơn nhiều tiểu bang khác.","h2":"Ở Arkansas, giấy phép học lái dành cho thanh thiếu niên 14 hoặc 15 tuổi, vì vậy 14 là tuổi nhỏ nhất.","p":"Đúng. Giấy phép học lái ở Arkansas bắt đầu từ 14 tuổi."},"tl":{"q":"Sa Arkansas, ano ang pinakabatang edad para makakuha ng learner's license?","o":["14 taong gulang","15 taong gulang","16 taong gulang","13 taong gulang"],"h1":"Mas maaga nagsisimula ang mga kabataan sa Arkansas kaysa sa maraming ibang estado.","h2":"Sa Arkansas, ang learner's license ay para sa mga kabataang 14 o 15 taong gulang, kaya 14 ang pinakabatang edad.","p":"Tama. Ang learner's license sa Arkansas ay nagsisimula sa edad na 14."},"ar":{"q":"في Arkansas، ما هو أصغر عمر للحصول على رخصة المتعلم (learner's license)؟","o":["14 سنة","15 سنة","16 سنة","13 سنة"],"h1":"تسمح Arkansas للمراهقين بالبدء أبكر من كثير من الولايات الأخرى.","h2":"في Arkansas، رخصة المتعلم مخصصة للمراهقين في عمر 14 أو 15 سنة، لذلك فإن 14 هو أصغر عمر.","p":"صحيح. رخصة المتعلم في Arkansas تبدأ من عمر 14 سنة."},"ref":{"doc":"AR","page":3}},{"id":"ar-002","scope":"AR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arkansas, a teen with a learner's license must drive with a licensed driver. How old must that driver be?","o":["At least 16 years old","At least 18 years old","At least 21 years old","At least 25 years old"],"h1":"The helper must be an adult who is old enough to buy alcohol legally.","h2":"An Arkansas learner may drive only with a licensed driver who is at least 21 years old, so an experienced adult is always there to guide them.","p":"Right. A learner drives with a licensed driver age 21 or older."},"es":{"q":"En Arkansas, un joven con licencia de aprendiz debe manejar con un conductor con licencia. ¿Qué edad debe tener ese conductor?","o":["Por lo menos 16 años","Por lo menos 18 años","Por lo menos 21 años","Por lo menos 25 años"],"h1":"El acompañante debe ser un adulto con edad suficiente para comprar alcohol legalmente.","h2":"En Arkansas, el aprendiz solo puede manejar con un conductor con licencia que tenga por lo menos 21 años, para que siempre lo guíe un adulto con experiencia.","p":"Correcto. El aprendiz maneja con un conductor con licencia de 21 años o más."},"zh":{"q":"在 Arkansas，持学习驾照的青少年必须和一位有驾照的司机一起开车。这位司机必须几岁？","o":["至少 16 岁","至少 18 岁","至少 21 岁","至少 25 岁"],"h1":"陪同的人必须是到了可以合法买酒年龄的成年人。","h2":"Arkansas 学习驾驶的人只能和至少 21 岁、有驾照的司机一起开车，这样总有一位有经验的成年人在旁边指导。","p":"对。学习驾驶的人和 21 岁或以上、有驾照的司机一起开车。"},"vi":{"q":"Ở Arkansas, thanh thiếu niên có giấy phép học lái phải lái xe cùng một người có bằng lái. Người đó phải bao nhiêu tuổi?","o":["Ít nhất 16 tuổi","Ít nhất 18 tuổi","Ít nhất 21 tuổi","Ít nhất 25 tuổi"],"h1":"Người đi kèm phải là người lớn đủ tuổi mua rượu hợp pháp.","h2":"Ở Arkansas, người học lái chỉ được lái xe cùng một người có bằng lái từ 21 tuổi trở lên, để luôn có người lớn có kinh nghiệm hướng dẫn.","p":"Đúng. Người học lái phải lái cùng người có bằng lái từ 21 tuổi trở lên."},"tl":{"q":"Sa Arkansas, ang kabataang may learner's license ay dapat magmaneho kasama ang isang drayber na may lisensiya. Ilang taon dapat ang drayber na iyon?","o":["Hindi bababa sa 16 taong gulang","Hindi bababa sa 18 taong gulang","Hindi bababa sa 21 taong gulang","Hindi bababa sa 25 taong gulang"],"h1":"Ang kasama ay dapat isang adult na nasa edad na para legal na bumili ng alak.","h2":"Sa Arkansas, ang nag-aaral magmaneho ay puwede lang magmaneho kasama ang drayber na may lisensiya na hindi bababa sa 21 taong gulang, para laging may may-karanasang adult na gagabay.","p":"Tama. Nagmamaneho ang nag-aaral kasama ang drayber na may lisensiya na 21 taong gulang o higit pa."},"ar":{"q":"في Arkansas، يجب على المراهق الذي يحمل رخصة المتعلم أن يقود مع سائق يحمل رخصة. كم يجب أن يكون عمر هذا السائق؟","o":["16 سنة على الأقل","18 سنة على الأقل","21 سنة على الأقل","25 سنة على الأقل"],"h1":"يجب أن يكون المرافق شخصًا بالغًا في عمر يسمح له بشراء الكحول قانونيًا.","h2":"في Arkansas، لا يجوز للمتعلم أن يقود إلا مع سائق يحمل رخصة وعمره 21 سنة على الأقل، حتى يكون معه دائمًا شخص بالغ له خبرة يرشده.","p":"صحيح. المتعلم يقود مع سائق يحمل رخصة وعمره 21 سنة أو أكثر."},"ref":{"doc":"AR","page":3}},{"id":"ar-003","scope":"AR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arkansas, at what age can a teen get an intermediate license?","o":["15 years old","16 years old","17 years old","18 years old"],"h1":"It comes right after the learner's license years of 14 and 15.","h2":"In Arkansas, the intermediate license is for drivers who are 16 or 17, so a teen can get it at 16.","p":"Right. The intermediate license starts at age 16."},"es":{"q":"En Arkansas, ¿a qué edad puede un joven obtener la licencia intermedia?","o":["15 años","16 años","17 años","18 años"],"h1":"Viene justo después de los años de la licencia de aprendiz, 14 y 15.","h2":"En Arkansas, la licencia intermedia es para conductores de 16 o 17 años, así que un joven puede obtenerla a los 16.","p":"Correcto. La licencia intermedia empieza a los 16 años."},"zh":{"q":"在 Arkansas，青少年几岁可以拿到中级驾照（intermediate license）？","o":["15 岁","16 岁","17 岁","18 岁"],"h1":"它紧接在学习驾照的 14 岁和 15 岁之后。","h2":"在 Arkansas，中级驾照是给 16 岁或 17 岁的司机的，所以青少年 16 岁就可以拿到。","p":"对。中级驾照从 16 岁开始。"},"vi":{"q":"Ở Arkansas, thanh thiếu niên có thể lấy bằng lái trung cấp (intermediate license) ở tuổi nào?","o":["15 tuổi","16 tuổi","17 tuổi","18 tuổi"],"h1":"Nó đến ngay sau những năm có giấy phép học lái, lúc 14 và 15 tuổi.","h2":"Ở Arkansas, bằng lái trung cấp dành cho người lái 16 hoặc 17 tuổi, vì vậy thanh thiếu niên có thể lấy bằng này lúc 16 tuổi.","p":"Đúng. Bằng lái trung cấp bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Arkansas, sa anong edad puwedeng makakuha ang kabataan ng intermediate license?","o":["15 taong gulang","16 taong gulang","17 taong gulang","18 taong gulang"],"h1":"Kasunod ito ng mga taon ng learner's license, sa edad na 14 at 15.","h2":"Sa Arkansas, ang intermediate license ay para sa mga drayber na 16 o 17 taong gulang, kaya puwede itong makuha ng kabataan sa edad na 16.","p":"Tama. Ang intermediate license ay nagsisimula sa edad na 16."},"ar":{"q":"في Arkansas، في أي عمر يمكن للمراهق الحصول على الرخصة المتوسطة (intermediate license)؟","o":["15 سنة","16 سنة","17 سنة","18 سنة"],"h1":"تأتي مباشرة بعد سنوات رخصة المتعلم في عمر 14 و15.","h2":"في Arkansas، الرخصة المتوسطة مخصصة للسائقين في عمر 16 أو 17 سنة، لذلك يمكن للمراهق الحصول عليها في عمر 16 سنة.","p":"صحيح. الرخصة المتوسطة تبدأ من عمر 16 سنة."},"ref":{"doc":"AR","page":3}},{"id":"ar-004","scope":"AR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arkansas, to get an intermediate license at 16, how long must a teen's driving record be free of a serious crash or serious traffic ticket?","o":["At least three months","At least six months","At least one year","At least two years"],"h1":"It is half of a year.","h2":"In Arkansas, a teen can get an intermediate license at 16 only if the driving record has no serious crash and no serious traffic ticket in the last six months.","p":"Right. The record must be clean for the last six months."},"es":{"q":"En Arkansas, para obtener la licencia intermedia a los 16 años, ¿cuánto tiempo debe estar el historial del joven sin un choque grave ni una multa de tránsito grave?","o":["Por lo menos tres meses","Por lo menos seis meses","Por lo menos un año","Por lo menos dos años"],"h1":"Es la mitad de un año.","h2":"En Arkansas, un joven puede obtener la licencia intermedia a los 16 años solo si su historial no tiene ningún choque grave ni ninguna multa de tránsito grave en los últimos seis meses.","p":"Correcto. El historial debe estar limpio durante los últimos seis meses."},"zh":{"q":"在 Arkansas，青少年想在 16 岁拿到中级驾照，驾驶记录必须多长时间没有严重车祸或严重交通罚单？","o":["至少三个月","至少六个月","至少一年","至少两年"],"h1":"这是半年。","h2":"在 Arkansas，青少年只有在过去六个月的驾驶记录里没有严重车祸、也没有严重交通罚单，才可以在 16 岁拿到中级驾照。","p":"对。过去六个月的记录必须是干净的。"},"vi":{"q":"Ở Arkansas, để được cấp bằng lái trung cấp lúc 16 tuổi, hồ sơ lái xe của thiếu niên phải không có tai nạn nghiêm trọng hay vé phạt giao thông nghiêm trọng trong bao lâu?","o":["Ít nhất ba tháng","Ít nhất sáu tháng","Ít nhất một năm","Ít nhất hai năm"],"h1":"Đó là nửa năm.","h2":"Ở Arkansas, thiếu niên chỉ được cấp bằng lái trung cấp lúc 16 tuổi nếu hồ sơ lái xe không có tai nạn nghiêm trọng và không có vé phạt giao thông nghiêm trọng trong sáu tháng gần nhất.","p":"Đúng. Hồ sơ phải sạch trong sáu tháng gần nhất."},"tl":{"q":"Sa Arkansas, para makakuha ng intermediate license sa edad na 16, gaano katagal dapat walang malubhang banggaan o malubhang traffic ticket ang driving record ng kabataan?","o":["Hindi bababa sa tatlong buwan","Hindi bababa sa anim na buwan","Hindi bababa sa isang taon","Hindi bababa sa dalawang taon"],"h1":"Ito ay kalahati ng isang taon.","h2":"Sa Arkansas, makakakuha lang ang kabataan ng intermediate license sa edad na 16 kung walang malubhang banggaan at walang malubhang traffic ticket ang driving record sa nakaraang anim na buwan.","p":"Tama. Dapat malinis ang record sa nakaraang anim na buwan."},"ar":{"q":"في Arkansas، للحصول على رخصة قيادة متوسطة (intermediate license) في سن 16، كم يجب أن يبقى سجل قيادة المراهق خاليًا من حادث خطير أو مخالفة مرورية خطيرة؟","o":["ثلاثة أشهر على الأقل","ستة أشهر على الأقل","سنة واحدة على الأقل","سنتان على الأقل"],"h1":"إنها نصف سنة.","h2":"في Arkansas، يمكن للمراهق أن يحصل على رخصة متوسطة في سن 16 فقط إذا كان سجل القيادة بلا حادث خطير وبلا مخالفة مرورية خطيرة في الأشهر الستة الأخيرة.","p":"صحيح. يجب أن يكون السجل نظيفًا في الأشهر الستة الأخيرة."},"ref":{"doc":"AR","page":null}},{"id":"ar-005","scope":"AR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arkansas, what must a teen's driving record show to get an intermediate license?","o":["Two minor tickets at most in the past year","A completed online safety video","A signed letter from a teacher","No serious violations or at-fault crashes in the past six months"],"h1":"Think about a clean record for a recent period of time.","h2":"To get an Arkansas intermediate license, a teen must have no serious traffic violations and no at-fault crashes during the previous six months.","p":"Right. The record must be clean of serious violations and at-fault crashes for six months."},"es":{"q":"En Arkansas, ¿qué debe mostrar el historial de manejo de un joven para obtener la licencia intermedia?","o":["Como máximo dos multas menores en el último año","Un video de seguridad completado en línea","Una carta firmada por un maestro","Ninguna infracción grave ni choque con culpa en los últimos seis meses"],"h1":"Piense en un historial limpio durante un período reciente.","h2":"Para obtener la licencia intermedia en Arkansas, el joven no debe tener infracciones graves ni choques en los que tuvo la culpa durante los seis meses anteriores.","p":"Correcto. El historial debe estar libre de infracciones graves y choques con culpa por seis meses."},"zh":{"q":"在 Arkansas，青少年的驾驶记录必须是什么样，才能拿到中级驾照？","o":["过去一年最多两张小罚单","已看完一个网上安全视频","一封老师签字的信","过去六个月没有严重违规，也没有自己有责任的车祸"],"h1":"想一想最近一段时间的干净记录。","h2":"要拿到 Arkansas 的中级驾照，青少年在过去六个月里必须没有严重的交通违规，也没有自己有责任的车祸。","p":"对。六个月里记录不能有严重违规和自己有责任的车祸。"},"vi":{"q":"Ở Arkansas, hồ sơ lái xe của thanh thiếu niên phải như thế nào để lấy bằng lái trung cấp?","o":["Nhiều nhất hai vé phạt nhẹ trong năm qua","Đã xem xong một video an toàn trên mạng","Có thư ký tên của giáo viên","Không có vi phạm nghiêm trọng hay tai nạn do lỗi của mình trong sáu tháng qua"],"h1":"Hãy nghĩ đến một hồ sơ sạch trong một thời gian gần đây.","h2":"Để lấy bằng lái trung cấp ở Arkansas, thanh thiếu niên không được có vi phạm giao thông nghiêm trọng và không có tai nạn do lỗi của mình trong sáu tháng trước đó.","p":"Đúng. Hồ sơ phải không có vi phạm nghiêm trọng và tai nạn do lỗi của mình trong sáu tháng."},"tl":{"q":"Sa Arkansas, ano ang dapat makita sa driving record ng kabataan para makakuha ng intermediate license?","o":["Hindi hihigit sa dalawang maliit na tiket sa nakaraang taon","Natapos na online na video tungkol sa kaligtasan","Pirmadong sulat mula sa isang guro","Walang malubhang paglabag o banggaan na siya ang may kasalanan sa nakaraang anim na buwan"],"h1":"Isipin ang malinis na record sa isang kamakailang panahon.","h2":"Para makakuha ng intermediate license sa Arkansas, ang kabataan ay dapat walang malubhang paglabag sa trapiko at walang banggaan na siya ang may kasalanan sa nakaraang anim na buwan.","p":"Tama. Dapat malinis ang record sa malubhang paglabag at banggaan na siya ang may kasalanan sa loob ng anim na buwan."},"ar":{"q":"في Arkansas، ماذا يجب أن يُظهر سجل القيادة للمراهق حتى يحصل على الرخصة المتوسطة؟","o":["مخالفتان بسيطتان على الأكثر في السنة الماضية","مشاهدة فيديو سلامة على الإنترنت حتى النهاية","رسالة موقعة من معلم","لا مخالفات خطيرة ولا حوادث بسبب خطئه في الأشهر الستة الماضية"],"h1":"فكّر في سجل نظيف خلال فترة قريبة.","h2":"للحصول على الرخصة المتوسطة في Arkansas، يجب ألا يكون لدى المراهق أي مخالفات مرورية خطيرة ولا حوادث بسبب خطئه خلال الأشهر الستة السابقة.","p":"صحيح. يجب أن يكون السجل خاليًا من المخالفات الخطيرة والحوادث بسبب الخطأ لمدة ستة أشهر."},"ref":{"doc":"AR","page":3}},{"id":"ar-006","scope":"AR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arkansas, at what age can a driver apply for a regular, unrestricted license?","o":["16 years old","17 years old","18 years old","21 years old"],"h1":"It is the age when most people finish high school.","h2":"In Arkansas, a driver can apply for a regular, unrestricted license at 18, as long as the driving record has been clean for the year before.","p":"Right. The unrestricted license comes at age 18."},"es":{"q":"En Arkansas, ¿a qué edad se puede solicitar la licencia regular sin restricciones?","o":["16 años","17 años","18 años","21 años"],"h1":"Es la edad en que la mayoría termina la escuela secundaria.","h2":"En Arkansas, se puede solicitar la licencia regular sin restricciones a los 18 años, siempre que el historial de manejo esté limpio durante el año anterior.","p":"Correcto. La licencia sin restricciones llega a los 18 años."},"zh":{"q":"在 Arkansas，司机几岁可以申请普通、没有限制的驾照？","o":["16 岁","17 岁","18 岁","21 岁"],"h1":"这是大多数人高中毕业的年龄。","h2":"在 Arkansas，司机 18 岁可以申请普通、没有限制的驾照，只要前一年的驾驶记录是干净的。","p":"对。没有限制的驾照从 18 岁开始。"},"vi":{"q":"Ở Arkansas, người lái xe có thể xin bằng lái thường, không hạn chế (unrestricted license) ở tuổi nào?","o":["16 tuổi","17 tuổi","18 tuổi","21 tuổi"],"h1":"Đó là tuổi mà phần lớn mọi người học xong trung học.","h2":"Ở Arkansas, người lái xe có thể xin bằng lái thường, không hạn chế lúc 18 tuổi, miễn là hồ sơ lái xe sạch trong năm trước đó.","p":"Đúng. Bằng lái không hạn chế đến lúc 18 tuổi."},"tl":{"q":"Sa Arkansas, sa anong edad puwedeng mag-apply ang drayber ng regular na lisensiya na walang limitasyon (unrestricted license)?","o":["16 taong gulang","17 taong gulang","18 taong gulang","21 taong gulang"],"h1":"Ito ang edad kung kailan karamihan ng tao ay tapos na sa high school.","h2":"Sa Arkansas, puwedeng mag-apply ang drayber ng regular na lisensiya na walang limitasyon sa edad na 18, basta malinis ang driving record sa nakaraang taon.","p":"Tama. Ang unrestricted license ay sa edad na 18."},"ar":{"q":"في Arkansas، في أي عمر يمكن للسائق أن يطلب رخصة عادية بلا قيود (unrestricted license)؟","o":["16 سنة","17 سنة","18 سنة","21 سنة"],"h1":"إنه العمر الذي ينهي فيه معظم الناس المدرسة الثانوية.","h2":"في Arkansas، يمكن للسائق أن يطلب رخصة عادية بلا قيود في عمر 18 سنة، بشرط أن يكون سجل القيادة نظيفًا في السنة السابقة.","p":"صحيح. الرخصة بلا قيود تأتي في عمر 18 سنة."},"ref":{"doc":"AR","page":4}},{"id":"ar-007","scope":"AR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arkansas, what can let a 16- or 17-year-old get an unrestricted license before turning 18?","o":["Graduating from high school or earning a GED","Passing the written test a second time","Driving 100 hours with a parent","Buying a car in their own name"],"h1":"Think about finishing school early.","h2":"Arkansas lets a 16- or 17-year-old get an unrestricted license early in some cases, such as showing a high school diploma or a GED.","p":"Right. A high school diploma or GED can allow an early unrestricted license."},"es":{"q":"En Arkansas, ¿qué puede permitir que un joven de 16 o 17 años obtenga la licencia sin restricciones antes de cumplir 18?","o":["Graduarse de la secundaria u obtener el GED","Aprobar el examen escrito por segunda vez","Manejar 100 horas con un padre","Comprar un carro a su propio nombre"],"h1":"Piense en terminar la escuela antes de tiempo.","h2":"En algunos casos, Arkansas permite que un joven de 16 o 17 años obtenga la licencia sin restricciones antes, por ejemplo si presenta el diploma de secundaria o el GED.","p":"Correcto. El diploma de secundaria o el GED puede permitir la licencia sin restricciones antes de tiempo."},"zh":{"q":"在 Arkansas，什么可以让 16 岁或 17 岁的人在满 18 岁前拿到没有限制的驾照？","o":["高中毕业或拿到 GED","第二次考过笔试","和父母一起开车 100 小时","用自己的名字买车"],"h1":"想一想提早完成学业。","h2":"Arkansas 在某些情况下让 16 岁或 17 岁的人提早拿到没有限制的驾照，比如出示高中毕业证书或 GED。","p":"对。高中毕业证书或 GED 可以让你提早拿到没有限制的驾照。"},"vi":{"q":"Ở Arkansas, điều gì có thể giúp người 16 hoặc 17 tuổi lấy bằng lái không hạn chế trước 18 tuổi?","o":["Tốt nghiệp trung học hoặc có bằng GED","Thi viết đạt lần thứ hai","Lái xe 100 giờ cùng cha mẹ","Mua xe đứng tên mình"],"h1":"Hãy nghĩ đến việc học xong sớm.","h2":"Arkansas cho người 16 hoặc 17 tuổi lấy bằng lái không hạn chế sớm trong một số trường hợp, ví dụ khi có bằng tốt nghiệp trung học hoặc bằng GED.","p":"Đúng. Bằng tốt nghiệp trung học hoặc GED có thể cho phép lấy bằng lái không hạn chế sớm."},"tl":{"q":"Sa Arkansas, ano ang puwedeng magpahintulot sa 16 o 17 taong gulang na makakuha ng unrestricted license bago mag-18?","o":["Pagtatapos ng high school o pagkakaroon ng GED","Pagpasa sa written test sa ikalawang pagkakataon","Pagmamaneho nang 100 oras kasama ang magulang","Pagbili ng kotse sa sariling pangalan"],"h1":"Isipin ang maagang pagtatapos ng pag-aaral.","h2":"Sa Arkansas, puwedeng makakuha nang maaga ng unrestricted license ang 16 o 17 taong gulang sa ilang kaso, gaya ng pagpapakita ng high school diploma o GED.","p":"Tama. Ang high school diploma o GED ay puwedeng magbigay ng maagang unrestricted license."},"ar":{"q":"في Arkansas، ما الذي يمكن أن يسمح لمن عمره 16 أو 17 سنة بالحصول على رخصة بلا قيود قبل أن يبلغ 18؟","o":["التخرج من المدرسة الثانوية أو الحصول على شهادة GED","النجاح في الامتحان الكتابي مرة ثانية","القيادة 100 ساعة مع أحد الوالدين","شراء سيارة باسمه"],"h1":"فكّر في إنهاء الدراسة مبكرًا.","h2":"تسمح Arkansas لمن عمره 16 أو 17 سنة بالحصول على رخصة بلا قيود مبكرًا في بعض الحالات، مثل تقديم شهادة المدرسة الثانوية أو شهادة GED.","p":"صحيح. شهادة المدرسة الثانوية أو GED يمكن أن تسمح برخصة بلا قيود مبكرة."},"ref":{"doc":"AR","page":null}},{"id":"ar-008","scope":"AR","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arkansas, during which hours may a driver with an intermediate license not drive, unless an exception applies?","o":["11 p.m. to 4 a.m.","9 p.m. to 6 a.m.","Midnight to 6 a.m.","10 p.m. to 5 a.m."],"h1":"The limit starts one hour before midnight.","h2":"An Arkansas intermediate license holder may not drive from 11 p.m. to 4 a.m., unless a licensed driver age 21 or older is along, or the trip is to or from work, a school or church activity, or an emergency.","p":"Right. Intermediate drivers stay off the road from 11 p.m. to 4 a.m."},"es":{"q":"En Arkansas, ¿en qué horario no puede manejar quien tiene licencia intermedia, salvo que aplique una excepción?","o":["De 11 p.m. a 4 a.m.","De 9 p.m. a 6 a.m.","De medianoche a 6 a.m.","De 10 p.m. a 5 a.m."],"h1":"El límite empieza una hora antes de la medianoche.","h2":"Una persona con licencia intermedia en Arkansas no puede manejar de 11 p. m. a 4 a. m., a menos que la acompañe un conductor con licencia de 21 años o más, o que vaya o venga del trabajo, de una actividad escolar o de la iglesia, o por una emergencia.","p":"Correcto. Los conductores con licencia intermedia no manejan de 11 p.m. a 4 a.m."},"zh":{"q":"在 Arkansas，持中级驾照的司机在哪段时间不能开车（例外情况除外）？","o":["晚上 11 点到凌晨 4 点","晚上 9 点到早上 6 点","午夜到早上 6 点","晚上 10 点到早上 5 点"],"h1":"这个限制在午夜前一小时开始。","h2":"Arkansas 持中级驾照的人在晚上 11 点到凌晨 4 点不能开车，除非有一位 21 岁或以上、有驾照的司机同车，或者是去上班或下班、去学校或教会活动，或者是紧急情况。","p":"对。持中级驾照的司机晚上 11 点到凌晨 4 点不上路。"},"vi":{"q":"Ở Arkansas, người có bằng lái trung cấp không được lái xe trong những giờ nào, trừ khi có ngoại lệ?","o":["11 giờ tối đến 4 giờ sáng","9 giờ tối đến 6 giờ sáng","Nửa đêm đến 6 giờ sáng","10 giờ tối đến 5 giờ sáng"],"h1":"Giới hạn bắt đầu một giờ trước nửa đêm.","h2":"Người có bằng lái trung cấp ở Arkansas không được lái xe từ 11 giờ tối đến 4 giờ sáng, trừ khi có người có bằng lái từ 21 tuổi trở lên đi cùng, hoặc chuyến đi là đến hay về từ chỗ làm, hoạt động của trường hoặc nhà thờ, hoặc trường hợp khẩn cấp.","p":"Đúng. Người có bằng lái trung cấp không lái xe từ 11 giờ tối đến 4 giờ sáng."},"tl":{"q":"Sa Arkansas, sa anong mga oras hindi puwedeng magmaneho ang drayber na may intermediate license, maliban kung may exception?","o":["11 p.m. hanggang 4 a.m.","9 p.m. hanggang 6 a.m.","Hatinggabi hanggang 6 a.m.","10 p.m. hanggang 5 a.m."],"h1":"Nagsisimula ang limitasyon isang oras bago maghatinggabi.","h2":"Ang may intermediate license sa Arkansas ay hindi puwedeng magmaneho mula 11 p.m. hanggang 4 a.m., maliban kung kasama ang drayber na may lisensiya na 21 taong gulang o higit pa, o ang biyahe ay papunta o galing sa trabaho, gawain ng paaralan o simbahan, o emergency.","p":"Tama. Hindi nagmamaneho ang may intermediate license mula 11 p.m. hanggang 4 a.m."},"ar":{"q":"في Arkansas، في أي ساعات لا يجوز لصاحب الرخصة المتوسطة أن يقود، إلا إذا كان هناك استثناء؟","o":["من 11 مساءً إلى 4 صباحًا","من 9 مساءً إلى 6 صباحًا","من منتصف الليل إلى 6 صباحًا","من 10 مساءً إلى 5 صباحًا"],"h1":"يبدأ المنع قبل منتصف الليل بساعة واحدة.","h2":"لا يجوز لصاحب الرخصة المتوسطة في Arkansas أن يقود من 11 مساءً إلى 4 صباحًا، إلا إذا كان معه سائق يحمل رخصة وعمره 21 سنة أو أكثر، أو كانت الرحلة إلى العمل أو منه، أو إلى نشاط مدرسي أو كنسي أو منه، أو في حالة طوارئ.","p":"صحيح. أصحاب الرخصة المتوسطة لا يقودون من 11 مساءً إلى 4 صباحًا."},"ref":{"doc":"AR","page":4}},{"id":"ar-009","scope":"AR","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arkansas, how many unrelated passengers under 18 may a driver with an intermediate license carry, when no adult driver is along?","o":["None at all","Two","Three","One"],"h1":"Family members do not count toward this limit.","h2":"An Arkansas intermediate license holder may carry only one unrelated passenger under 18, unless a licensed driver age 21 or older sits in the front seat.","p":"Right. Only one unrelated passenger under 18 is allowed."},"es":{"q":"En Arkansas, ¿cuántos pasajeros menores de 18 años, que no sean familiares, puede llevar un conductor con licencia intermedia si no lo acompaña un adulto con licencia?","o":["Ninguno","Dos","Tres","Uno"],"h1":"Los familiares no cuentan para este límite.","h2":"Una persona con licencia intermedia en Arkansas puede llevar solo un pasajero menor de 18 años que no sea familiar, a menos que un conductor con licencia de 21 años o más vaya en el asiento delantero.","p":"Correcto. Solo se permite un pasajero menor de 18 años que no sea familiar."},"zh":{"q":"在 Arkansas，没有成年司机同车时，持中级驾照的司机可以载多少位 18 岁以下、不是家人的乘客？","o":["一位都不行","两位","三位","一位"],"h1":"家人不算在这个限制里。","h2":"Arkansas 持中级驾照的人只能载一位 18 岁以下、不是家人的乘客，除非有一位 21 岁或以上、有驾照的司机坐在前排。","p":"对。只能载一位 18 岁以下、不是家人的乘客。"},"vi":{"q":"Ở Arkansas, khi không có người lớn có bằng lái đi cùng, người có bằng lái trung cấp được chở bao nhiêu hành khách dưới 18 tuổi không phải người nhà?","o":["Không ai cả","Hai","Ba","Một"],"h1":"Người trong gia đình không tính vào giới hạn này.","h2":"Người có bằng lái trung cấp ở Arkansas chỉ được chở một hành khách dưới 18 tuổi không phải người nhà, trừ khi có người có bằng lái từ 21 tuổi trở lên ngồi ghế trước.","p":"Đúng. Chỉ được chở một hành khách dưới 18 tuổi không phải người nhà."},"tl":{"q":"Sa Arkansas, ilang pasaherong wala pang 18 na hindi kamag-anak ang puwedeng isakay ng drayber na may intermediate license, kapag walang kasamang adult na drayber?","o":["Wala talaga","Dalawa","Tatlo","Isa"],"h1":"Hindi kasama sa bilang na ito ang mga kapamilya.","h2":"Ang may intermediate license sa Arkansas ay puwede lang magsakay ng isang pasaherong wala pang 18 na hindi kamag-anak, maliban kung may drayber na may lisensiya na 21 taong gulang o higit pa na nakaupo sa harap.","p":"Tama. Isang pasaherong wala pang 18 na hindi kamag-anak lang ang puwede."},"ar":{"q":"في Arkansas، كم راكبًا عمره أقل من 18 سنة وليس من العائلة يمكن أن ينقل صاحب الرخصة المتوسطة، عندما لا يكون معه سائق بالغ؟","o":["لا أحد أبدًا","اثنان","ثلاثة","واحد"],"h1":"أفراد العائلة لا يُحسبون في هذا الحد.","h2":"لا يجوز لصاحب الرخصة المتوسطة في Arkansas أن ينقل إلا راكبًا واحدًا عمره أقل من 18 سنة وليس من العائلة، إلا إذا جلس في المقعد الأمامي سائق يحمل رخصة وعمره 21 سنة أو أكثر.","p":"صحيح. يُسمح براكب واحد فقط عمره أقل من 18 سنة وليس من العائلة."},"ref":{"doc":"AR","page":4}},{"id":"ar-010","scope":"AR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arkansas, what is the rule on cell phones for drivers under 18?","o":["They may use a phone only with a hands-free device","They may not use a phone at all, except in an emergency","They may text only at a red light","They may talk only on highways"],"h1":"For the youngest drivers, even hands-free is not allowed.","h2":"In Arkansas, drivers under 18 may not use a cell phone while driving, even hands-free, except in an emergency.","p":"Right. Drivers under 18 may not use a phone, except in an emergency."},"es":{"q":"En Arkansas, ¿cuál es la regla del celular para conductores menores de 18 años?","o":["Pueden usar el teléfono solo con manos libres","No pueden usar el teléfono, salvo en una emergencia","Pueden enviar mensajes solo en un semáforo en rojo","Pueden hablar solo en las autopistas"],"h1":"Para los conductores más jóvenes, ni siquiera se permite el manos libres.","h2":"En Arkansas, los conductores menores de 18 años no pueden usar el celular mientras manejan, ni siquiera con manos libres, salvo en una emergencia.","p":"Correcto. Los menores de 18 no pueden usar el teléfono, salvo en una emergencia."},"zh":{"q":"在 Arkansas，对 18 岁以下的司机，手机的规定是什么？","o":["只能用免持设备打电话","完全不能用手机，紧急情况除外","只能在红灯时发短信","只能在公路上打电话"],"h1":"对最年轻的司机来说，连免持都不允许。","h2":"在 Arkansas，18 岁以下的司机开车时不能用手机，即使是免持也不行，紧急情况除外。","p":"对。18 岁以下的司机不能用手机，紧急情况除外。"},"vi":{"q":"Ở Arkansas, quy định về điện thoại di động cho người lái xe dưới 18 tuổi là gì?","o":["Chỉ được dùng điện thoại với thiết bị rảnh tay","Hoàn toàn không được dùng điện thoại, trừ khi khẩn cấp","Chỉ được nhắn tin khi đèn đỏ","Chỉ được nói chuyện trên xa lộ"],"h1":"Với người lái trẻ nhất, ngay cả rảnh tay cũng không được.","h2":"Ở Arkansas, người lái xe dưới 18 tuổi không được dùng điện thoại di động khi lái xe, kể cả rảnh tay, trừ khi khẩn cấp.","p":"Đúng. Người lái dưới 18 tuổi không được dùng điện thoại, trừ khi khẩn cấp."},"tl":{"q":"Sa Arkansas, ano ang patakaran sa cellphone para sa mga drayber na wala pang 18?","o":["Puwede lang gumamit ng cellphone gamit ang hands-free na device","Hindi talaga puwedeng gumamit ng cellphone, maliban sa emergency","Puwede lang mag-text kapag pula ang ilaw","Puwede lang makipag-usap sa highway"],"h1":"Para sa pinakabatang drayber, kahit hands-free ay hindi puwede.","h2":"Sa Arkansas, ang mga drayber na wala pang 18 ay hindi puwedeng gumamit ng cellphone habang nagmamaneho, kahit hands-free, maliban sa emergency.","p":"Tama. Ang mga drayber na wala pang 18 ay hindi puwedeng gumamit ng cellphone, maliban sa emergency."},"ar":{"q":"في Arkansas، ما هي القاعدة حول الهاتف المحمول للسائقين الذين عمرهم أقل من 18 سنة؟","o":["يمكنهم استخدام الهاتف فقط مع جهاز بدون استخدام اليدين","لا يجوز لهم استخدام الهاتف أبدًا، إلا في حالة طوارئ","يمكنهم كتابة الرسائل فقط عند الإشارة الحمراء","يمكنهم التحدث فقط على الطرق السريعة"],"h1":"لأصغر السائقين، حتى الاستخدام بدون اليدين غير مسموح.","h2":"في Arkansas، لا يجوز للسائقين الذين عمرهم أقل من 18 سنة استخدام الهاتف المحمول أثناء القيادة، حتى بدون استخدام اليدين، إلا في حالة طوارئ.","p":"صحيح. السائقون الذين عمرهم أقل من 18 سنة لا يستخدمون الهاتف، إلا في حالة طوارئ."},"ref":{"doc":"AR","page":46}},{"id":"ar-011","scope":"AR","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Arkansas, how may a driver who is 18 to 20 years old talk on a phone while driving?","o":["Only while holding the phone to the ear","Only on roads with no traffic lights","Only with a hands-free device","Only when a passenger holds the phone"],"h1":"The driver's hands must stay free.","h2":"In Arkansas, drivers from 18 to 20 may not use a handheld phone while driving, but they may talk with a hands-free device.","p":"Right. Drivers 18 to 20 may talk only hands-free."},"es":{"q":"En Arkansas, ¿cómo puede hablar por teléfono mientras maneja un conductor de 18 a 20 años?","o":["Solo sosteniendo el teléfono en el oído","Solo en calles sin semáforos","Solo con un dispositivo de manos libres","Solo si un pasajero sostiene el teléfono"],"h1":"Las manos del conductor deben quedar libres.","h2":"En Arkansas, los conductores de 18 a 20 años no pueden usar el teléfono en la mano mientras manejan, pero pueden hablar con un dispositivo de manos libres.","p":"Correcto. Los conductores de 18 a 20 años solo pueden hablar con manos libres."},"zh":{"q":"在 Arkansas，18 到 20 岁的司机开车时可以怎样打电话？","o":["只能把手机拿在耳边","只能在没有红绿灯的路上","只能用免持设备","只能让乘客拿着手机"],"h1":"司机的手必须空着。","h2":"在 Arkansas，18 到 20 岁的司机开车时不能用手持电话，但可以用免持设备打电话。","p":"对。18 到 20 岁的司机只能用免持打电话。"},"vi":{"q":"Ở Arkansas, người lái xe từ 18 đến 20 tuổi được nói chuyện điện thoại khi lái xe bằng cách nào?","o":["Chỉ khi cầm điện thoại áp vào tai","Chỉ trên đường không có đèn giao thông","Chỉ với thiết bị rảnh tay","Chỉ khi hành khách cầm điện thoại"],"h1":"Tay của người lái phải được rảnh.","h2":"Ở Arkansas, người lái xe từ 18 đến 20 tuổi không được cầm điện thoại trên tay khi lái xe, nhưng được nói chuyện bằng thiết bị rảnh tay.","p":"Đúng. Người lái từ 18 đến 20 tuổi chỉ được nói chuyện rảnh tay."},"tl":{"q":"Sa Arkansas, paano puwedeng makipag-usap sa cellphone habang nagmamaneho ang drayber na 18 hanggang 20 taong gulang?","o":["Habang hawak lang ang cellphone sa tainga","Sa mga daan lang na walang traffic light","Gamit lang ang hands-free na device","Kapag pasahero lang ang may hawak ng cellphone"],"h1":"Dapat malaya ang mga kamay ng drayber.","h2":"Sa Arkansas, ang mga drayber na 18 hanggang 20 taong gulang ay hindi puwedeng humawak ng cellphone habang nagmamaneho, pero puwede silang makipag-usap gamit ang hands-free na device.","p":"Tama. Ang mga drayber na 18 hanggang 20 ay puwede lang makipag-usap nang hands-free."},"ar":{"q":"في Arkansas، كيف يمكن للسائق الذي عمره من 18 إلى 20 سنة أن يتحدث في الهاتف أثناء القيادة؟","o":["فقط وهو يمسك الهاتف على أذنه","فقط على طرق بلا إشارات مرور","فقط مع جهاز بدون استخدام اليدين","فقط عندما يمسك راكب الهاتف"],"h1":"يجب أن تبقى يدا السائق حرتين.","h2":"في Arkansas، لا يجوز للسائقين من 18 إلى 20 سنة أن يمسكوا الهاتف بأيديهم أثناء القيادة، لكن يمكنهم التحدث بجهاز بدون استخدام اليدين.","p":"صحيح. السائقون من 18 إلى 20 سنة يتحدثون فقط بدون استخدام اليدين."},"ref":{"doc":"AR","page":4}},{"id":"ar-012","scope":"AR","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arkansas, which drivers are banned from texting while driving?","o":["Drivers of every age","Only drivers under 18","Only drivers under 21","Only commercial truck drivers"],"h1":"This rule does not depend on age.","h2":"Arkansas does not allow any driver, of any age, to send or read text messages while driving.","p":"Right. No driver of any age may text while driving in Arkansas."},"es":{"q":"En Arkansas, ¿a qué conductores se les prohíbe enviar mensajes de texto mientras manejan?","o":["A los conductores de todas las edades","Solo a los menores de 18 años","Solo a los menores de 21 años","Solo a los camioneros comerciales"],"h1":"Esta regla no depende de la edad.","h2":"Arkansas no permite que ningún conductor, de ninguna edad, envíe o lea mensajes de texto mientras maneja.","p":"Correcto. Ningún conductor, de ninguna edad, puede enviar mensajes mientras maneja en Arkansas."},"zh":{"q":"在 Arkansas，哪些司机开车时禁止发短信？","o":["所有年龄的司机","只有 18 岁以下的司机","只有 21 岁以下的司机","只有商业卡车司机"],"h1":"这个规定和年龄无关。","h2":"Arkansas 不允许任何年龄的司机开车时发或看短信。","p":"对。在 Arkansas，任何年龄的司机开车时都不能发短信。"},"vi":{"q":"Ở Arkansas, những người lái xe nào bị cấm nhắn tin khi lái xe?","o":["Người lái xe ở mọi lứa tuổi","Chỉ người lái dưới 18 tuổi","Chỉ người lái dưới 21 tuổi","Chỉ tài xế xe tải thương mại"],"h1":"Quy định này không phụ thuộc vào tuổi.","h2":"Arkansas không cho phép bất kỳ người lái xe nào, ở bất kỳ tuổi nào, gửi hoặc đọc tin nhắn khi lái xe.","p":"Đúng. Ở Arkansas, không người lái nào ở bất kỳ tuổi nào được nhắn tin khi lái xe."},"tl":{"q":"Sa Arkansas, sinong mga drayber ang bawal mag-text habang nagmamaneho?","o":["Mga drayber sa lahat ng edad","Mga drayber lang na wala pang 18","Mga drayber lang na wala pang 21","Mga drayber lang ng komersiyal na trak"],"h1":"Hindi nakadepende sa edad ang patakarang ito.","h2":"Sa Arkansas, walang drayber, sa anumang edad, ang puwedeng magpadala o magbasa ng text message habang nagmamaneho.","p":"Tama. Sa Arkansas, walang drayber sa anumang edad ang puwedeng mag-text habang nagmamaneho."},"ar":{"q":"في Arkansas، أي السائقين ممنوعون من كتابة الرسائل النصية أثناء القيادة؟","o":["السائقون من كل الأعمار","السائقون الذين عمرهم أقل من 18 سنة فقط","السائقون الذين عمرهم أقل من 21 سنة فقط","سائقو الشاحنات التجارية فقط"],"h1":"هذه القاعدة لا تعتمد على العمر.","h2":"لا تسمح Arkansas لأي سائق، من أي عمر، بإرسال الرسائل النصية أو قراءتها أثناء القيادة.","p":"صحيح. في Arkansas لا يجوز لأي سائق من أي عمر أن يكتب الرسائل أثناء القيادة."},"ref":{"doc":"AR","page":4}},{"id":"ar-013","scope":"AR","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arkansas, where must even an adult driver use only a hands-free device to talk on the phone?","o":["On any road after dark","In any parking lot","On any road with two lanes","In a school zone, or a work zone when workers are present"],"h1":"Think of places where children or road workers may be near.","h2":"In Arkansas, even an adult driver may not hold a phone while passing a school zone during school hours when children are outside, or while driving in a highway work zone when workers are present.","p":"Right. In school zones and active work zones, calls must be hands-free."},"es":{"q":"En Arkansas, ¿dónde debe incluso un conductor adulto usar solo manos libres para hablar por teléfono?","o":["En cualquier calle de noche","En cualquier estacionamiento","En cualquier carretera de dos carriles","En una zona escolar, o en una zona de obras cuando hay trabajadores"],"h1":"Piense en lugares donde puede haber niños o trabajadores cerca.","h2":"En Arkansas, incluso un conductor adulto no puede sostener el teléfono al pasar por una zona escolar en horario de clases cuando hay niños afuera, ni al manejar en una zona de obras en la carretera cuando hay trabajadores.","p":"Correcto. En zonas escolares y zonas de obras activas, las llamadas deben ser con manos libres."},"zh":{"q":"在 Arkansas，即使是成年司机，在哪里打电话也只能用免提设备？","o":["天黑后的任何道路上","任何停车场里","任何双车道的道路上","在学校区，或者有工人在场的施工区"],"h1":"想一想孩子或道路工人可能在附近的地方。","h2":"在 Arkansas，即使是成年司机，在上学时间有孩子在外面时经过学校区，或者在有工人在场的公路施工区开车时，也不可以用手拿着电话。","p":"对。在学校区和有工人的施工区，打电话必须用免提。"},"vi":{"q":"Ở Arkansas, ở đâu thì ngay cả tài xế người lớn cũng chỉ được dùng thiết bị rảnh tay để nói điện thoại?","o":["Trên bất kỳ con đường nào sau khi trời tối","Trong bất kỳ bãi đậu xe nào","Trên bất kỳ con đường nào có hai làn xe","Trong khu vực trường học, hoặc khu vực công trường khi có công nhân"],"h1":"Hãy nghĩ đến những nơi có thể có trẻ em hoặc công nhân làm đường ở gần.","h2":"Ở Arkansas, ngay cả tài xế người lớn cũng không được cầm điện thoại khi đi qua khu vực trường học trong giờ học lúc có trẻ em ở bên ngoài, hoặc khi lái trong khu vực công trường trên xa lộ khi có công nhân.","p":"Đúng. Trong khu vực trường học và khu vực công trường đang có công nhân, phải gọi điện bằng thiết bị rảnh tay."},"tl":{"q":"Sa Arkansas, saan dapat gumamit ng hands-free device lang kahit ang adult na driver para makipag-usap sa telepono?","o":["Sa kahit anong kalsada pagkatapos dumilim","Sa kahit anong parking lot","Sa kahit anong kalsada na may dalawang lane","Sa school zone, o sa work zone kapag may mga trabahador"],"h1":"Isipin ang mga lugar kung saan maaaring malapit ang mga bata o mga trabahador sa kalsada.","h2":"Sa Arkansas, kahit ang adult na driver ay hindi puwedeng humawak ng telepono habang dumadaan sa school zone sa oras ng klase kapag may mga bata sa labas, o habang nagmamaneho sa highway work zone kapag may mga trabahador.","p":"Tama. Sa mga school zone at aktibong work zone, dapat hands-free ang tawag."},"ar":{"q":"في Arkansas، أين يجب حتى على السائق البالغ أن يستخدم جهازًا بدون استخدام اليدين فقط للتحدث في الهاتف؟","o":["على أي طريق بعد حلول الظلام","في أي موقف سيارات","على أي طريق فيه مساران","في منطقة مدرسة، أو في منطقة عمل عندما يكون العمال موجودين"],"h1":"فكّر في الأماكن التي قد يكون فيها أطفال أو عمال طرق قريبين.","h2":"في Arkansas، لا يجوز حتى للسائق البالغ أن يمسك الهاتف بيده أثناء المرور في منطقة مدرسة خلال ساعات الدراسة عندما يكون الأطفال في الخارج، أو أثناء القيادة في منطقة عمل على الطريق السريع عندما يكون العمال موجودين.","p":"صحيح. في مناطق المدارس ومناطق العمل النشطة، يجب أن تكون المكالمات بدون استخدام اليدين."},"ref":{"doc":"AR","page":null}},{"id":"ar-014","scope":"AR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arkansas, a driver under 21 is considered under the influence at what blood alcohol level?","o":["0.00 percent","0.02 percent or higher","0.05 percent or higher","0.08 percent or higher"],"h1":"It is far lower than the limit for adults.","h2":"In Arkansas, a driver under 21 with a blood alcohol level of 0.02 percent or higher can be charged with underage DUI.","p":"Right. For drivers under 21, the limit is 0.02 percent."},"es":{"q":"En Arkansas, ¿con qué nivel de alcohol en la sangre se considera que un conductor menor de 21 años está bajo la influencia?","o":["0.00 por ciento","0.02 por ciento o más","0.05 por ciento o más","0.08 por ciento o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Arkansas, un conductor menor de 21 años con un nivel de alcohol en la sangre de 0.02 por ciento o más puede ser acusado de manejar bajo la influencia.","p":"Correcto. Para los menores de 21, el límite es 0.02 por ciento."},"zh":{"q":"在 Arkansas，21 岁以下的司机血液酒精浓度达到多少，就算酒后驾驶？","o":["0.00%","0.02% 或更高","0.05% 或更高","0.08% 或更高"],"h1":"它比成年人的限制低很多。","h2":"在 Arkansas，21 岁以下的司机血液酒精浓度达到 0.02% 或更高，就可能被控未成年酒后驾驶（underage DUI）。","p":"对。21 岁以下的司机，限制是 0.02%。"},"vi":{"q":"Ở Arkansas, người lái xe dưới 21 tuổi bị coi là bị ảnh hưởng bởi rượu ở nồng độ cồn trong máu bao nhiêu?","o":["0.00 phần trăm","0.02 phần trăm trở lên","0.05 phần trăm trở lên","0.08 phần trăm trở lên"],"h1":"Mức này thấp hơn nhiều so với giới hạn cho người lớn.","h2":"Ở Arkansas, người lái xe dưới 21 tuổi có nồng độ cồn trong máu từ 0.02 phần trăm trở lên có thể bị buộc tội lái xe say rượu khi chưa đủ tuổi (underage DUI).","p":"Đúng. Với người lái dưới 21 tuổi, giới hạn là 0.02 phần trăm."},"tl":{"q":"Sa Arkansas, sa anong blood alcohol level itinuturing na lasing ang drayber na wala pang 21?","o":["0.00 porsiyento","0.02 porsiyento o higit pa","0.05 porsiyento o higit pa","0.08 porsiyento o higit pa"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon para sa mga adult.","h2":"Sa Arkansas, ang drayber na wala pang 21 na may blood alcohol level na 0.02 porsiyento o higit pa ay puwedeng kasuhan ng underage DUI.","p":"Tama. Para sa mga drayber na wala pang 21, ang limitasyon ay 0.02 porsiyento."},"ar":{"q":"في Arkansas، عند أي نسبة كحول في الدم يُعتبر السائق الذي عمره أقل من 21 سنة تحت تأثير الكحول؟","o":["0.00 بالمئة","0.02 بالمئة أو أكثر","0.05 بالمئة أو أكثر","0.08 بالمئة أو أكثر"],"h1":"إنها أقل بكثير من الحد المسموح للبالغين.","h2":"في Arkansas، السائق الذي عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02 بالمئة أو أكثر يمكن أن يُتهم بالقيادة تحت تأثير الكحول لمن هم دون السن (underage DUI).","p":"صحيح. للسائقين الذين عمرهم أقل من 21 سنة، الحد هو 0.02 بالمئة."},"ref":{"doc":"AR","page":75}},{"id":"ar-015","scope":"AR","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Arkansas, at what blood alcohol level can a driver 21 or older be charged with DWI?","o":["0.02 percent or higher","0.05 percent or higher","0.08 percent or higher","0.10 percent or higher"],"h1":"It is the same limit most states use for adults.","h2":"In Arkansas, a driver 21 or older with a blood alcohol level of 0.08 percent or higher can be charged with driving while intoxicated.","p":"Right. For adults, the limit is 0.08 percent."},"es":{"q":"En Arkansas, ¿con qué nivel de alcohol en la sangre se puede acusar de DWI a un conductor de 21 años o más?","o":["0.02 por ciento o más","0.05 por ciento o más","0.08 por ciento o más","0.10 por ciento o más"],"h1":"Es el mismo límite que usa la mayoría de los estados para adultos.","h2":"En Arkansas, un conductor de 21 años o más con un nivel de alcohol en la sangre de 0.08 por ciento o más puede ser acusado de manejar en estado de ebriedad.","p":"Correcto. Para los adultos, el límite es 0.08 por ciento."},"zh":{"q":"在 Arkansas，21 岁或以上的司机血液酒精浓度达到多少，可能被控 DWI（醉酒驾驶）？","o":["0.02% 或更高","0.05% 或更高","0.08% 或更高","0.10% 或更高"],"h1":"它和大多数州对成年人用的限制一样。","h2":"在 Arkansas，21 岁或以上的司机血液酒精浓度达到 0.08% 或更高，就可能被控醉酒驾驶。","p":"对。成年人的限制是 0.08%。"},"vi":{"q":"Ở Arkansas, người lái xe từ 21 tuổi trở lên có thể bị buộc tội DWI ở nồng độ cồn trong máu bao nhiêu?","o":["0.02 phần trăm trở lên","0.05 phần trăm trở lên","0.08 phần trăm trở lên","0.10 phần trăm trở lên"],"h1":"Đó là giới hạn giống phần lớn các tiểu bang dùng cho người lớn.","h2":"Ở Arkansas, người lái xe từ 21 tuổi trở lên có nồng độ cồn trong máu từ 0.08 phần trăm trở lên có thể bị buộc tội lái xe khi say (DWI).","p":"Đúng. Với người lớn, giới hạn là 0.08 phần trăm."},"tl":{"q":"Sa Arkansas, sa anong blood alcohol level puwedeng kasuhan ng DWI ang drayber na 21 taong gulang o higit pa?","o":["0.02 porsiyento o higit pa","0.05 porsiyento o higit pa","0.08 porsiyento o higit pa","0.10 porsiyento o higit pa"],"h1":"Ito ang parehong limitasyon na ginagamit ng karamihan ng estado para sa mga adult.","h2":"Sa Arkansas, ang drayber na 21 taong gulang o higit pa na may blood alcohol level na 0.08 porsiyento o higit pa ay puwedeng kasuhan ng pagmamaneho nang lasing (DWI).","p":"Tama. Para sa mga adult, ang limitasyon ay 0.08 porsiyento."},"ar":{"q":"في Arkansas، عند أي نسبة كحول في الدم يمكن أن يُتهم السائق الذي عمره 21 سنة أو أكثر بـ DWI؟","o":["0.02 بالمئة أو أكثر","0.05 بالمئة أو أكثر","0.08 بالمئة أو أكثر","0.10 بالمئة أو أكثر"],"h1":"إنه نفس الحد الذي تستخدمه معظم الولايات للبالغين.","h2":"في Arkansas، السائق الذي عمره 21 سنة أو أكثر ونسبة الكحول في دمه 0.08 بالمئة أو أكثر يمكن أن يُتهم بالقيادة في حالة سُكر (DWI).","p":"صحيح. للبالغين، الحد هو 0.08 بالمئة."},"ref":{"doc":"AR","page":74}},{"id":"ar-016","scope":"AR","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Arkansas, what is the highest posted speed limit for cars on rural interstates?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"It is higher than the limit for trucks on the same road.","h2":"Arkansas allows cars to drive up to 75 mph on rural interstates where it is posted, while trucks are limited to 70 mph.","p":"Right. Cars may go up to 75 mph on posted rural interstates."},"es":{"q":"En Arkansas, ¿cuál es el límite de velocidad más alto para carros en las autopistas interestatales rurales?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"Es más alto que el límite para camiones en la misma vía.","h2":"Arkansas permite que los carros vayan hasta 75 mph en las autopistas interestatales rurales donde está señalizado, mientras que los camiones tienen un límite de 70 mph.","p":"Correcto. Los carros pueden ir hasta 75 mph en las interestatales rurales señalizadas."},"zh":{"q":"在 Arkansas，乡村州际公路上小汽车的最高标示限速是多少？","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"它比同一条路上卡车的限速高。","h2":"在有标示的乡村州际公路上，Arkansas 允许小汽车最高开到 75 mph，而卡车限速是 70 mph。","p":"对。在有标示的乡村州际公路上，小汽车最高可以开 75 mph。"},"vi":{"q":"Ở Arkansas, tốc độ tối đa được ghi trên biển cho xe hơi trên xa lộ liên bang ở vùng nông thôn là bao nhiêu?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"Nó cao hơn giới hạn cho xe tải trên cùng con đường.","h2":"Arkansas cho phép xe hơi chạy đến 75 mph trên xa lộ liên bang ở vùng nông thôn nơi có biển ghi như vậy, còn xe tải bị giới hạn ở 70 mph.","p":"Đúng. Xe hơi được chạy đến 75 mph trên xa lộ liên bang vùng nông thôn có biển ghi."},"tl":{"q":"Sa Arkansas, ano ang pinakamataas na nakapaskil na speed limit para sa mga kotse sa rural interstate?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"Mas mataas ito kaysa sa limitasyon para sa mga trak sa parehong daan.","h2":"Pinapayagan ng Arkansas ang mga kotse na tumakbo hanggang 75 mph sa rural interstate kung saan ito nakapaskil, habang ang mga trak ay limitado sa 70 mph.","p":"Tama. Puwedeng tumakbo ang mga kotse hanggang 75 mph sa rural interstate na may nakapaskil."},"ar":{"q":"في Arkansas، ما هو أعلى حد سرعة مكتوب على اللافتات للسيارات على الطرق السريعة بين الولايات في المناطق الريفية؟","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"إنه أعلى من حد السرعة للشاحنات على نفس الطريق.","h2":"تسمح Arkansas للسيارات بالسير حتى 75 mph على الطرق السريعة بين الولايات في المناطق الريفية حيث يكون ذلك مكتوبًا على اللافتات، بينما حد الشاحنات هو 70 mph.","p":"صحيح. يمكن للسيارات السير حتى 75 mph على الطرق السريعة الريفية المكتوب عليها ذلك."},"ref":{"doc":"AR","page":null}},{"id":"ar-017","scope":"AR","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Arkansas, what is the highest speed limit for large trucks on rural interstates?","o":["70 mph","60 mph","65 mph","75 mph"],"h1":"It is 5 mph lower than the top limit for cars.","h2":"On Arkansas rural interstates, large trucks are limited to 70 mph, which is 5 mph less than the 75 mph allowed for cars.","p":"Right. Trucks are limited to 70 mph on rural interstates."},"es":{"q":"En Arkansas, ¿cuál es el límite de velocidad más alto para camiones grandes en las interestatales rurales?","o":["70 mph","60 mph","65 mph","75 mph"],"h1":"Es 5 mph menos que el límite más alto para carros.","h2":"En las interestatales rurales de Arkansas, los camiones grandes tienen un límite de 70 mph, que es 5 mph menos que las 75 mph permitidas para carros.","p":"Correcto. Los camiones tienen un límite de 70 mph en las interestatales rurales."},"zh":{"q":"在 Arkansas，乡村州际公路上大卡车的最高限速是多少？","o":["70 mph","60 mph","65 mph","75 mph"],"h1":"它比小汽车的最高限速低 5 mph。","h2":"在 Arkansas 的乡村州际公路上，大卡车限速是 70 mph，比小汽车允许的 75 mph 低 5 mph。","p":"对。在乡村州际公路上，卡车限速是 70 mph。"},"vi":{"q":"Ở Arkansas, tốc độ tối đa cho xe tải lớn trên xa lộ liên bang ở vùng nông thôn là bao nhiêu?","o":["70 mph","60 mph","65 mph","75 mph"],"h1":"Nó thấp hơn 5 mph so với giới hạn cao nhất cho xe hơi.","h2":"Trên xa lộ liên bang vùng nông thôn ở Arkansas, xe tải lớn bị giới hạn ở 70 mph, tức là thấp hơn 5 mph so với 75 mph cho xe hơi.","p":"Đúng. Xe tải bị giới hạn ở 70 mph trên xa lộ liên bang vùng nông thôn."},"tl":{"q":"Sa Arkansas, ano ang pinakamataas na speed limit para sa malalaking trak sa rural interstate?","o":["70 mph","60 mph","65 mph","75 mph"],"h1":"Mas mababa ito nang 5 mph kaysa sa pinakamataas na limitasyon para sa mga kotse.","h2":"Sa rural interstate ng Arkansas, ang malalaking trak ay limitado sa 70 mph, na 5 mph na mas mababa kaysa sa 75 mph na pinapayagan sa mga kotse.","p":"Tama. Limitado sa 70 mph ang mga trak sa rural interstate."},"ar":{"q":"في Arkansas، ما هو أعلى حد سرعة للشاحنات الكبيرة على الطرق السريعة بين الولايات في المناطق الريفية؟","o":["70 mph","60 mph","65 mph","75 mph"],"h1":"إنه أقل بـ 5 mph من أعلى حد للسيارات.","h2":"على الطرق السريعة الريفية بين الولايات في Arkansas، حد الشاحنات الكبيرة هو 70 mph، أي أقل بـ 5 mph من 75 mph المسموح بها للسيارات.","p":"صحيح. حد الشاحنات هو 70 mph على الطرق السريعة الريفية."},"ref":{"doc":"AR","page":null}},{"id":"ar-018","scope":"AR","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Arkansas, the move-over law covers more than police cars and ambulances. Which other stopped vehicles does it cover?","o":["Any parked car with its hood open","Only city buses at a bus stop","Utility trucks and tow trucks with flashing lights","Only delivery vans with hazard lights"],"h1":"Think of work vehicles that stop on the side of the road.","h2":"Arkansas's move-over law also covers stopped utility vehicles, tow trucks and highway department vehicles that show flashing lights.","p":"Right. Utility trucks and tow trucks with flashing lights are covered."},"es":{"q":"En Arkansas, la ley de moverse de carril cubre más que patrullas y ambulancias. ¿Qué otros vehículos detenidos cubre?","o":["Cualquier carro estacionado con el capó abierto","Solo autobuses urbanos en la parada","Camiones de servicios públicos y grúas con luces intermitentes","Solo camionetas de reparto con luces de emergencia"],"h1":"Piense en vehículos de trabajo que se detienen al lado de la carretera.","h2":"La ley de Arkansas también cubre vehículos de servicios públicos, grúas y vehículos del departamento de carreteras que están detenidos con luces intermitentes.","p":"Correcto. Se incluyen los camiones de servicios públicos y las grúas con luces intermitentes."},"zh":{"q":"在 Arkansas，move-over 法不只保护警车和救护车。它还保护哪些停着的车辆？","o":["任何打开引擎盖停着的车","只有在公车站的市区公车","车灯在闪的公用事业车和拖车","只有开着双闪灯的送货车"],"h1":"想一想停在路边的工作车辆。","h2":"Arkansas 的 move-over 法也保护车灯在闪、停着的公用事业车、拖车和公路部门的车辆。","p":"对。车灯在闪的公用事业车和拖车也受保护。"},"vi":{"q":"Ở Arkansas, luật tránh sang làn khác (move-over law) không chỉ áp dụng cho xe cảnh sát và xe cứu thương. Luật này còn áp dụng cho những xe đang dừng nào khác?","o":["Bất kỳ xe đậu nào đang mở nắp capô","Chỉ xe buýt thành phố ở trạm xe buýt","Xe tải tiện ích và xe kéo có đèn nhấp nháy","Chỉ xe giao hàng có bật đèn khẩn cấp"],"h1":"Hãy nghĩ đến các xe làm việc dừng bên lề đường.","h2":"Luật tránh sang làn khác của Arkansas cũng áp dụng cho xe tiện ích, xe kéo và xe của sở đường bộ đang dừng và có đèn nhấp nháy.","p":"Đúng. Xe tải tiện ích và xe kéo có đèn nhấp nháy cũng được luật bảo vệ."},"tl":{"q":"Sa Arkansas, ang move-over law ay hindi lang para sa mga sasakyan ng pulis at ambulansiya. Anong iba pang nakahintong sasakyan ang sakop nito?","o":["Anumang nakaparadang kotse na bukas ang hood","Mga city bus lang sa bus stop","Mga utility truck at tow truck na may kumikislap na ilaw","Mga delivery van lang na naka-hazard light"],"h1":"Isipin ang mga sasakyang pantrabaho na humihinto sa gilid ng daan.","h2":"Sakop din ng move-over law ng Arkansas ang mga nakahintong utility vehicle, tow truck at sasakyan ng highway department na may kumikislap na ilaw.","p":"Tama. Sakop ang mga utility truck at tow truck na may kumikislap na ilaw."},"ar":{"q":"في Arkansas، قانون الابتعاد (move-over law) لا يشمل سيارات الشرطة والإسعاف فقط. ما هي المركبات المتوقفة الأخرى التي يشملها؟","o":["أي سيارة متوقفة غطاء محركها مفتوح","حافلات المدينة فقط عند محطة الحافلات","شاحنات المرافق وشاحنات السحب التي لها أضواء وامضة","شاحنات التوصيل فقط التي تشغّل أضواء التحذير"],"h1":"فكّر في مركبات العمل التي تتوقف على جانب الطريق.","h2":"يشمل قانون الابتعاد في Arkansas أيضًا مركبات المرافق وشاحنات السحب ومركبات دائرة الطرق المتوقفة التي تُظهر أضواء وامضة.","p":"صحيح. شاحنات المرافق وشاحنات السحب التي لها أضواء وامضة مشمولة."},"ref":{"doc":"AR","page":21}},{"id":"ar-019","scope":"AR","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Arkansas, you approach a stopped emergency vehicle with flashing lights, but you cannot safely move to another lane. What must you do?","o":["Keep your speed and pass quickly","Slow down and pass with caution","Stop in your lane until it leaves","Honk to warn the workers"],"h1":"If you cannot add distance, reduce your speed.","h2":"Under the Arkansas move-over law, if you cannot safely move away from the stopped vehicle, you must slow down and pass with caution.","p":"Right. When you cannot move over, you slow down and use caution."},"es":{"q":"En Arkansas, usted se acerca a un vehículo de emergencia detenido con luces intermitentes, pero no puede cambiarse de carril con seguridad. ¿Qué debe hacer?","o":["Mantener la velocidad y pasar rápido","Reducir la velocidad y pasar con precaución","Detenerse en su carril hasta que se vaya","Tocar la bocina para avisar a los trabajadores"],"h1":"Si no puede alejarse, reduzca la velocidad.","h2":"Según la ley de Arkansas, si usted no puede alejarse con seguridad del vehículo detenido, debe reducir la velocidad y pasar con precaución.","p":"Correcto. Si no puede cambiarse de carril, reduce la velocidad y maneja con cuidado."},"zh":{"q":"在 Arkansas，你接近一辆车灯在闪的停着的急救车辆，但你无法安全地换到另一条车道。你必须怎么做？","o":["保持速度，快点开过去","减速，小心地开过去","在你的车道停车，直到它离开","按喇叭提醒工作人员"],"h1":"如果你不能拉开距离，就降低速度。","h2":"根据 Arkansas 的 move-over 法，如果你无法安全地离开停着的车辆，你必须减速，小心地开过去。","p":"对。无法换道时，就减速并小心。"},"vi":{"q":"Ở Arkansas, bạn đến gần một xe khẩn cấp đang dừng có đèn nhấp nháy, nhưng bạn không thể chuyển sang làn khác một cách an toàn. Bạn phải làm gì?","o":["Giữ tốc độ và chạy qua nhanh","Giảm tốc độ và chạy qua cẩn thận","Dừng trong làn của mình cho đến khi xe đó đi","Bấm còi để báo cho công nhân"],"h1":"Nếu không thể giữ thêm khoảng cách, hãy giảm tốc độ.","h2":"Theo luật tránh sang làn khác của Arkansas, nếu bạn không thể tránh xa xe đang dừng một cách an toàn, bạn phải giảm tốc độ và chạy qua cẩn thận.","p":"Đúng. Khi không thể chuyển làn, bạn giảm tốc độ và cẩn thận."},"tl":{"q":"Sa Arkansas, papalapit ka sa nakahintong emergency vehicle na may kumikislap na ilaw, pero hindi ka ligtas na makalipat sa ibang lane. Ano ang dapat mong gawin?","o":["Panatilihin ang bilis at dumaan nang mabilis","Magdahan-dahan at dumaan nang maingat","Huminto sa iyong lane hanggang umalis ito","Bumusina para bigyan ng babala ang mga trabahador"],"h1":"Kung hindi ka makalayo, bawasan ang iyong bilis.","h2":"Ayon sa move-over law ng Arkansas, kung hindi ka ligtas na makalayo sa nakahintong sasakyan, dapat kang magdahan-dahan at dumaan nang maingat.","p":"Tama. Kapag hindi ka makalipat ng lane, magdahan-dahan at mag-ingat."},"ar":{"q":"في Arkansas، تقترب من مركبة طوارئ متوقفة ولها أضواء وامضة، لكنك لا تستطيع الانتقال إلى مسار آخر بأمان. ماذا يجب أن تفعل؟","o":["تحافظ على سرعتك وتمر بسرعة","تخفف السرعة وتمر بحذر","تتوقف في مسارك حتى تغادر","تستخدم البوق لتحذير العمال"],"h1":"إذا لم تستطع زيادة المسافة، خفّف سرعتك.","h2":"حسب قانون الابتعاد في Arkansas، إذا لم تستطع الابتعاد عن المركبة المتوقفة بأمان، يجب أن تخفف السرعة وتمر بحذر.","p":"صحيح. عندما لا تستطيع تغيير المسار، تخفف السرعة وتنتبه."},"ref":{"doc":"AR","page":21}},{"id":"ar-020","scope":"AR","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Arkansas, what fine can a driver face for breaking the move-over law?","o":["$250 to $1,000","$25 to $50","$50 to $100","$5,000 to $10,000"],"h1":"The lowest amount is a few hundred dollars.","h2":"Under Arkansas law, a driver who breaks the move-over law can be fined from $250 to $1,000, and may also face up to 90 days in jail.","p":"Right. The fine ranges from $250 to $1,000."},"es":{"q":"En Arkansas, ¿qué multa puede recibir un conductor por no cumplir la ley de moverse de carril?","o":["De $250 a $1,000","De $25 a $50","De $50 a $100","De $5,000 a $10,000"],"h1":"La cantidad más baja es de unos cientos de dólares.","h2":"Según la ley de Arkansas, quien no cumple la ley de moverse de carril puede recibir una multa de $250 a $1,000, y también hasta 90 días de cárcel.","p":"Correcto. La multa va de $250 a $1,000."},"zh":{"q":"在 Arkansas，司机违反让道法（move-over law）可能被罚多少钱？","o":["$250 到 $1,000","$25 到 $50","$50 到 $100","$5,000 到 $10,000"],"h1":"最低的金额是几百美元。","h2":"根据 Arkansas 法律，违反让道法的司机可能被罚 $250 到 $1,000，还可能被关最多 90 天。","p":"对。罚款是 $250 到 $1,000。"},"vi":{"q":"Ở Arkansas, tài xế vi phạm luật nhường làn (move-over law) có thể bị phạt bao nhiêu tiền?","o":["$250 đến $1,000","$25 đến $50","$50 đến $100","$5,000 đến $10,000"],"h1":"Số tiền thấp nhất là vài trăm đô la.","h2":"Theo luật Arkansas, tài xế vi phạm luật nhường làn có thể bị phạt từ $250 đến $1,000, và cũng có thể bị ngồi tù đến 90 ngày.","p":"Đúng. Tiền phạt từ $250 đến $1,000."},"tl":{"q":"Sa Arkansas, magkano ang multa na puwedeng harapin ng driver na lumabag sa move-over law?","o":["$250 hanggang $1,000","$25 hanggang $50","$50 hanggang $100","$5,000 hanggang $10,000"],"h1":"Ilang daang dolyar ang pinakamababang halaga.","h2":"Ayon sa batas ng Arkansas, ang driver na lumabag sa move-over law ay puwedeng multahan ng $250 hanggang $1,000, at puwede ring makulong nang hanggang 90 araw.","p":"Tama. Ang multa ay mula $250 hanggang $1,000."},"ar":{"q":"في Arkansas، ما الغرامة التي قد يواجهها السائق إذا خالف قانون الابتعاد (move-over law)؟","o":["من $250 إلى $1,000","من $25 إلى $50","من $50 إلى $100","من $5,000 إلى $10,000"],"h1":"أقل مبلغ هو بضع مئات من الدولارات.","h2":"حسب قانون Arkansas، يمكن تغريم السائق الذي يخالف قانون الابتعاد من $250 إلى $1,000، وقد يواجه أيضًا السجن حتى 90 يومًا.","p":"صحيح. الغرامة من $250 إلى $1,000."},"ref":{"doc":"AR","page":null}},{"id":"ar-021","scope":"AR","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Arkansas, how far from a stopped school bus with flashing red lights must you stop?","o":["At least 5 feet","At least 10 feet","At least 15 feet","At least 30 feet"],"h1":"It is about the length of two cars.","h2":"Arkansas law requires you to stop at least 30 feet away from a school bus that is stopped with its red lights flashing.","p":"Right. You stop at least 30 feet from the bus."},"es":{"q":"En Arkansas, ¿a qué distancia de un autobús escolar detenido con luces rojas intermitentes debe detenerse?","o":["Por lo menos 5 pies","Por lo menos 10 pies","Por lo menos 15 pies","Por lo menos 30 pies"],"h1":"Es más o menos el largo de dos carros.","h2":"La ley de Arkansas exige que usted se detenga por lo menos a 30 pies de un autobús escolar detenido con las luces rojas intermitentes.","p":"Correcto. Usted se detiene por lo menos a 30 pies del autobús."},"zh":{"q":"在 Arkansas，你必须在离红灯闪烁、停着的校车多远的地方停车？","o":["至少 5 英尺","至少 10 英尺","至少 15 英尺","至少 30 英尺"],"h1":"它大约是两辆车的长度。","h2":"Arkansas 法律要求你在离停着、红灯在闪的校车至少 30 英尺的地方停车。","p":"对。你在离校车至少 30 英尺的地方停车。"},"vi":{"q":"Ở Arkansas, bạn phải dừng cách xe buýt trường học đang dừng có đèn đỏ nhấp nháy bao xa?","o":["Ít nhất 5 feet","Ít nhất 10 feet","Ít nhất 15 feet","Ít nhất 30 feet"],"h1":"Khoảng bằng chiều dài hai chiếc xe hơi.","h2":"Luật Arkansas bắt buộc bạn dừng cách ít nhất 30 feet so với xe buýt trường học đang dừng có đèn đỏ nhấp nháy.","p":"Đúng. Bạn dừng cách xe buýt ít nhất 30 feet."},"tl":{"q":"Sa Arkansas, gaano kalayo ka dapat huminto mula sa nakahintong school bus na may kumikislap na pulang ilaw?","o":["Hindi bababa sa 5 feet","Hindi bababa sa 10 feet","Hindi bababa sa 15 feet","Hindi bababa sa 30 feet"],"h1":"Halos kasinghaba ito ng dalawang kotse.","h2":"Ayon sa batas ng Arkansas, dapat kang huminto nang hindi bababa sa 30 feet ang layo mula sa school bus na nakahinto at kumikislap ang pulang ilaw.","p":"Tama. Huminto ka nang hindi bababa sa 30 feet mula sa bus."},"ar":{"q":"في Arkansas، على أي مسافة يجب أن تتوقف من حافلة مدرسية متوقفة أضواؤها الحمراء تومض؟","o":["5 feet على الأقل","10 feet على الأقل","15 feet على الأقل","30 feet على الأقل"],"h1":"إنها تقريبًا طول سيارتين.","h2":"يفرض قانون Arkansas أن تتوقف على بعد 30 feet على الأقل من الحافلة المدرسية المتوقفة وأضواؤها الحمراء تومض.","p":"صحيح. تتوقف على بعد 30 feet على الأقل من الحافلة."},"ref":{"doc":"AR","page":null}},{"id":"ar-022","scope":"AR","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Arkansas, when may a driver going the opposite way keep moving past a stopped school bus?","o":["On any road with four lanes","On any road with a center turn lane","On a divided highway with a median at least 20 feet wide","On any road when no children are visible"],"h1":"The two sides of the road must be separated by a wide strip.","h2":"In Arkansas, a driver going the opposite way may keep going only when a median at least 20 feet wide separates them from the stopped school bus.","p":"Right. Only a wide median of at least 20 feet lets the opposite side keep going."},"es":{"q":"En Arkansas, ¿cuándo puede un conductor que va en sentido contrario seguir adelante al pasar un autobús escolar detenido?","o":["En cualquier vía de cuatro carriles","En cualquier vía con carril central para girar","En una carretera dividida con una franja central de por lo menos 20 pies","En cualquier vía si no se ven niños"],"h1":"Los dos lados de la vía deben estar separados por una franja ancha.","h2":"En Arkansas, un conductor que va en sentido contrario puede seguir solo cuando una franja divisoria de al menos 20 pies de ancho lo separa del autobús escolar detenido.","p":"Correcto. Solo una franja central de por lo menos 20 pies permite que el lado contrario siga."},"zh":{"q":"在 Arkansas，对面方向的司机什么时候可以继续开过停着的校车？","o":["在任何四车道道路上","在任何有中间转弯车道的道路上","在有至少 20 英尺宽中间隔离带的分隔公路上","在任何看不到孩子的道路上"],"h1":"道路的两边必须用一条很宽的地带分开。","h2":"在 Arkansas，只有在至少 20 英尺宽的中间隔离带把你和停着的校车分开时，对面方向的司机才可以继续开。","p":"对。只有至少 20 英尺宽的隔离带，才让对面的车可以继续开。"},"vi":{"q":"Ở Arkansas, khi nào người lái xe đi chiều ngược lại được tiếp tục chạy qua xe buýt trường học đang dừng?","o":["Trên bất kỳ con đường bốn làn nào","Trên bất kỳ con đường nào có làn rẽ ở giữa","Trên xa lộ có dải phân cách rộng ít nhất 20 feet","Trên bất kỳ con đường nào khi không thấy trẻ em"],"h1":"Hai bên đường phải được tách ra bởi một dải đất rộng.","h2":"Ở Arkansas, người lái xe đi chiều ngược lại chỉ được tiếp tục chạy khi có dải phân cách rộng ít nhất 20 feet ngăn họ với xe buýt trường học đang dừng.","p":"Đúng. Chỉ dải phân cách rộng ít nhất 20 feet mới cho phép bên ngược lại tiếp tục chạy."},"tl":{"q":"Sa Arkansas, kailan puwedeng tuloy-tuloy na dumaan ang drayber na nasa kabilang direksiyon sa nakahintong school bus?","o":["Sa anumang daan na may apat na lane","Sa anumang daan na may center turn lane","Sa divided highway na may median na hindi bababa sa 20 feet ang lapad","Sa anumang daan kapag walang nakikitang bata"],"h1":"Dapat hinihiwalay ng malapad na bahagi ang dalawang gilid ng daan.","h2":"Sa Arkansas, ang drayber na nasa kabilang direksiyon ay puwede lang tumuloy kapag may median na hindi bababa sa 20 feet ang lapad na naghihiwalay sa kanila sa nakahintong school bus.","p":"Tama. Ang malapad na median lang na hindi bababa sa 20 feet ang nagpapahintulot sa kabilang direksiyon na tumuloy."},"ar":{"q":"في Arkansas، متى يجوز للسائق القادم من الاتجاه المعاكس أن يستمر في السير بجانب حافلة مدرسية متوقفة؟","o":["على أي طريق له أربعة مسارات","على أي طريق فيه مسار للانعطاف في الوسط","على طريق سريع مقسوم بفاصل عرضه 20 feet على الأقل","على أي طريق عندما لا يُرى أي أطفال"],"h1":"يجب أن يفصل بين جانبي الطريق شريط عريض.","h2":"في Arkansas، لا يجوز للسائق القادم من الاتجاه المعاكس أن يستمر إلا عندما يفصله عن الحافلة المدرسية المتوقفة فاصل عرضه 20 feet على الأقل.","p":"صحيح. فقط الفاصل العريض الذي عرضه 20 feet على الأقل يسمح للاتجاه المعاكس بالاستمرار."},"ref":{"doc":"AR","page":12}},{"id":"ar-023","scope":"AR","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Arkansas, you are on a four-lane road with a center turn lane and no median. A school bus going the other way stops with red lights flashing. What must you do?","o":["Stop until the red lights turn off","Keep driving because you are going the other way","Slow to 20 mph and pass","Move to the far lane and keep going"],"h1":"A center turn lane is not a median.","h2":"In Arkansas, drivers on two-lane and four-lane roads, including roads with a center turn lane, must stop for a school bus that is loading or unloading children.","p":"Right. Without a wide median, traffic in both directions must stop."},"es":{"q":"En Arkansas, usted va por una vía de cuatro carriles con carril central para girar y sin franja central. Un autobús escolar que va en sentido contrario se detiene con las luces rojas intermitentes. ¿Qué debe hacer?","o":["Detenerse hasta que se apaguen las luces rojas","Seguir porque usted va en sentido contrario","Reducir a 20 mph y pasar","Pasarse al carril más lejano y seguir"],"h1":"Un carril central para girar no es una franja central.","h2":"En Arkansas, los conductores en vías de dos y cuatro carriles, incluso las que tienen carril central para girar, deben detenerse ante un autobús escolar que sube o baja niños.","p":"Correcto. Sin una franja central ancha, el tráfico en ambas direcciones debe detenerse."},"zh":{"q":"在 Arkansas，你在一条有中间转弯车道、没有隔离带的四车道道路上。一辆对面方向的校车停下来，红灯在闪。你必须怎么做？","o":["停车，直到红灯熄灭","继续开，因为你是对面方向","减速到 20 mph 开过去","换到最远的车道继续开"],"h1":"中间转弯车道不是隔离带。","h2":"在 Arkansas，在双车道和四车道道路上，包括有中间转弯车道的道路，司机都必须为正在让孩子上下车的校车停车。","p":"对。没有宽的隔离带，两个方向的车都必须停车。"},"vi":{"q":"Ở Arkansas, bạn đang đi trên con đường bốn làn có làn rẽ ở giữa và không có dải phân cách. Một xe buýt trường học đi chiều ngược lại dừng và bật đèn đỏ nhấp nháy. Bạn phải làm gì?","o":["Dừng lại cho đến khi đèn đỏ tắt","Tiếp tục lái vì bạn đi chiều ngược lại","Giảm xuống 20 mph rồi chạy qua","Chuyển sang làn xa nhất và tiếp tục chạy"],"h1":"Làn rẽ ở giữa không phải là dải phân cách.","h2":"Ở Arkansas, người lái xe trên đường hai làn và bốn làn, kể cả đường có làn rẽ ở giữa, phải dừng lại khi xe buýt trường học đang cho trẻ em lên hoặc xuống.","p":"Đúng. Khi không có dải phân cách rộng, xe ở cả hai chiều đều phải dừng."},"tl":{"q":"Sa Arkansas, nasa daan ka na may apat na lane at center turn lane, at walang median. Huminto ang school bus na nasa kabilang direksiyon at kumikislap ang pulang ilaw. Ano ang dapat mong gawin?","o":["Huminto hanggang mamatay ang pulang ilaw","Tumuloy dahil nasa kabilang direksiyon ka","Bumagal sa 20 mph at dumaan","Lumipat sa pinakamalayong lane at tumuloy"],"h1":"Ang center turn lane ay hindi median.","h2":"Sa Arkansas, ang mga drayber sa daan na may dalawa o apat na lane, kasama ang mga daan na may center turn lane, ay dapat huminto para sa school bus na nagsasakay o nagbababa ng mga bata.","p":"Tama. Kapag walang malapad na median, dapat huminto ang trapiko sa dalawang direksiyon."},"ar":{"q":"في Arkansas، أنت على طريق له أربعة مسارات مع مسار للانعطاف في الوسط وبدون فاصل. حافلة مدرسية قادمة من الاتجاه الآخر تتوقف وأضواؤها الحمراء تومض. ماذا يجب أن تفعل؟","o":["تتوقف حتى تنطفئ الأضواء الحمراء","تستمر في القيادة لأنك في الاتجاه الآخر","تخفف السرعة إلى 20 mph وتمر","تنتقل إلى المسار الأبعد وتستمر"],"h1":"مسار الانعطاف في الوسط ليس فاصلًا.","h2":"في Arkansas، يجب على السائقين على الطرق ذات المسارين والأربعة مسارات، ومنها الطرق التي فيها مسار للانعطاف في الوسط، أن يتوقفوا للحافلة المدرسية التي تُركب الأطفال أو تُنزلهم.","p":"صحيح. بدون فاصل عريض، يجب أن تتوقف السيارات في الاتجاهين."},"ref":{"doc":"AR","page":13}},{"id":"ar-024","scope":"AR","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Arkansas, what is the highest fine for illegally passing a stopped school bus?","o":["$500","$2,500","$100","$10,000"],"h1":"It is a few thousand dollars, plus court costs.","h2":"Under Arkansas law, illegally passing a stopped school bus can bring a fine of up to $2,500, plus court costs.","p":"Right. The fine can reach $2,500."},"es":{"q":"En Arkansas, ¿cuál es la multa más alta por pasar ilegalmente un autobús escolar detenido?","o":["$500","$2,500","$100","$10,000"],"h1":"Son unos miles de dólares, más los costos del tribunal.","h2":"Según la ley de Arkansas, pasar ilegalmente un autobús escolar detenido puede costar una multa de hasta $2,500, más los costos del tribunal.","p":"Correcto. La multa puede llegar a $2,500."},"zh":{"q":"在 Arkansas，非法超过停着的校车，最高罚款是多少？","o":["$500","$2,500","$100","$10,000"],"h1":"它是几千美元，另外还要付法庭费用。","h2":"根据 Arkansas 法律，非法超过停着的校车，可能被罚最高 $2,500，另外还要付法庭费用。","p":"对。罚款可能高达 $2,500。"},"vi":{"q":"Ở Arkansas, tiền phạt cao nhất cho việc vượt trái phép xe buýt trường học đang dừng là bao nhiêu?","o":["$500","$2,500","$100","$10,000"],"h1":"Đó là vài nghìn đô la, cộng thêm án phí.","h2":"Theo luật Arkansas, vượt trái phép xe buýt trường học đang dừng có thể bị phạt đến $2,500, cộng thêm án phí.","p":"Đúng. Tiền phạt có thể lên đến $2,500."},"tl":{"q":"Sa Arkansas, ano ang pinakamataas na multa sa ilegal na pag-overtake sa nakahintong school bus?","o":["$500","$2,500","$100","$10,000"],"h1":"Ilang libong dolyar ito, dagdag pa ang court costs.","h2":"Ayon sa batas ng Arkansas, ang ilegal na pag-overtake sa nakahintong school bus ay puwedeng magmulta ng hanggang $2,500, dagdag pa ang court costs.","p":"Tama. Ang multa ay puwedeng umabot sa $2,500."},"ar":{"q":"في Arkansas، ما هي أعلى غرامة لتجاوز حافلة مدرسية متوقفة بشكل غير قانوني؟","o":["$500","$2,500","$100","$10,000"],"h1":"إنها بضعة آلاف من الدولارات، بالإضافة إلى تكاليف المحكمة.","h2":"حسب قانون Arkansas، تجاوز حافلة مدرسية متوقفة بشكل غير قانوني يمكن أن يؤدي إلى غرامة تصل إلى $2,500، بالإضافة إلى تكاليف المحكمة.","p":"صحيح. يمكن أن تصل الغرامة إلى $2,500."},"ref":{"doc":"AR","page":null}},{"id":"ar-026","scope":"AR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arkansas, what is the minimum liability insurance a driver must carry?","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $50,000"],"h1":"The first and last numbers are the same.","h2":"Arkansas requires at least $25,000 for injury to one person, $50,000 for injuries in one crash, and $25,000 for property damage.","p":"Right. The Arkansas minimum is 25, 50 and 25 thousand dollars."},"es":{"q":"En Arkansas, ¿cuál es el seguro mínimo de responsabilidad civil que debe tener un conductor?","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $50,000"],"h1":"El primer número y el último son iguales.","h2":"Arkansas exige por lo menos $25,000 por lesiones a una persona, $50,000 por lesiones en un choque y $25,000 por daños a la propiedad.","p":"Correcto. El mínimo en Arkansas es de 25, 50 y 25 mil dólares."},"zh":{"q":"在 Arkansas，司机必须买的最低责任保险是多少？","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $50,000"],"h1":"第一个和最后一个数字一样。","h2":"Arkansas 要求一个人受伤至少 $25,000，一次车祸的人身伤害至少 $50,000，财产损失至少 $25,000。","p":"对。Arkansas 的最低标准是 $25,000、$50,000 和 $25,000。"},"vi":{"q":"Ở Arkansas, bảo hiểm trách nhiệm tối thiểu mà người lái xe phải có là bao nhiêu?","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $50,000"],"h1":"Số đầu tiên và số cuối cùng giống nhau.","h2":"Arkansas yêu cầu ít nhất $25,000 cho thương tích của một người, $50,000 cho thương tích trong một tai nạn, và $25,000 cho thiệt hại tài sản.","p":"Đúng. Mức tối thiểu ở Arkansas là 25, 50 và 25 nghìn đô la."},"tl":{"q":"Sa Arkansas, ano ang pinakamababang liability insurance na dapat mayroon ang drayber?","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $50,000"],"h1":"Pareho ang una at huling numero.","h2":"Hinihingi ng Arkansas ang hindi bababa sa $25,000 para sa pinsala sa isang tao, $50,000 para sa mga pinsala sa isang banggaan, at $25,000 para sa pinsala sa ari-arian.","p":"Tama. Ang minimum sa Arkansas ay 25, 50 at 25 libong dolyar."},"ar":{"q":"في Arkansas، ما هو الحد الأدنى لتأمين المسؤولية الذي يجب أن يكون لدى السائق؟","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $50,000"],"h1":"الرقم الأول والرقم الأخير متساويان.","h2":"تطلب Arkansas على الأقل $25,000 لإصابة شخص واحد، و$50,000 للإصابات في حادث واحد، و$25,000 لأضرار الممتلكات.","p":"صحيح. الحد الأدنى في Arkansas هو 25 و50 و25 ألف دولار."},"ref":{"doc":"AR","page":null}},{"id":"ar-027","scope":"AR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arkansas, how long is an instruction permit valid?","o":["6 months, and it can be renewed","2 years, and it cannot be renewed","1 year, and it can be renewed once","4 years, and it cannot be renewed"],"h1":"You cannot extend it, so finish the road test in time.","h2":"In Arkansas an instruction permit is valid for 2 years and cannot be renewed, so you must pass the skills test and buy a license before it expires.","p":"Right. The permit lasts 2 years with no renewal."},"es":{"q":"En Arkansas, ¿por cuánto tiempo es válido el permiso de aprendizaje?","o":["6 meses, y se puede renovar","2 años, y no se puede renovar","1 año, y se puede renovar una vez","4 años, y no se puede renovar"],"h1":"No se puede extender, así que termine el examen de manejo a tiempo.","h2":"En Arkansas el permiso de aprendizaje es válido por 2 años y no se puede renovar, así que debe aprobar el examen práctico y comprar la licencia antes de que venza.","p":"Correcto. El permiso dura 2 años y no se renueva."},"zh":{"q":"在 Arkansas，学习驾照（instruction permit）的有效期是多久？","o":["6 个月，可以续期","2 年，不能续期","1 年，可以续期一次","4 年，不能续期"],"h1":"它不能延长，所以要及时完成路考。","h2":"在 Arkansas，学习驾照的有效期是 2 年，而且不能续期，所以你必须在它过期之前通过路考并购买驾照。","p":"对。学习驾照有效 2 年，不能续期。"},"vi":{"q":"Ở Arkansas, giấy phép học lái (instruction permit) có giá trị trong bao lâu?","o":["6 tháng, và có thể gia hạn","2 năm, và không thể gia hạn","1 năm, và có thể gia hạn một lần","4 năm, và không thể gia hạn"],"h1":"Bạn không thể kéo dài nó, vì vậy hãy thi lái xe kịp thời.","h2":"Ở Arkansas, giấy phép học lái có giá trị trong 2 năm và không thể gia hạn, vì vậy bạn phải thi đậu bài thi kỹ năng và mua bằng lái trước khi nó hết hạn.","p":"Đúng. Giấy phép học lái có giá trị 2 năm và không được gia hạn."},"tl":{"q":"Sa Arkansas, gaano katagal valid ang instruction permit?","o":["6 na buwan, at puwede itong i-renew","2 taon, at hindi ito puwedeng i-renew","1 taon, at puwede itong i-renew nang isang beses","4 na taon, at hindi ito puwedeng i-renew"],"h1":"Hindi mo ito mapapahaba, kaya tapusin ang road test sa tamang oras.","h2":"Sa Arkansas, ang instruction permit ay valid nang 2 taon at hindi puwedeng i-renew, kaya kailangan mong pumasa sa skills test at bumili ng lisensya bago ito mag-expire.","p":"Tama. Ang permit ay tumatagal nang 2 taon at walang renewal."},"ar":{"q":"في Arkansas، ما مدة صلاحية تصريح التعلم (instruction permit)؟","o":["6 أشهر، ويمكن تجديده","سنتان (2)، ولا يمكن تجديده","سنة واحدة (1)، ويمكن تجديده مرة واحدة","4 سنوات، ولا يمكن تجديده"],"h1":"لا يمكنك تمديده، لذلك أكمل اختبار القيادة في الوقت المناسب.","h2":"في Arkansas، تصريح التعلم صالح لمدة سنتين (2) ولا يمكن تجديده، لذلك يجب أن تنجح في اختبار المهارات وتشتري الرخصة قبل انتهاء صلاحيته.","p":"صحيح. التصريح صالح لمدة سنتين (2) بدون تجديد."},"ref":{"doc":"AR","page":86}},{"id":"ar-028","scope":"AR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arkansas, after a crash with an injury or major damage, how long do you have to send a report to the Office of Driver Services?","o":["24 hours","5 days","10 days","30 days"],"h1":"It is about one month.","h2":"In Arkansas you must file the crash report with the Office of Driver Services within 30 days when there is an injury, a death, or more than $3,000 in damage to one person's property.","p":"Right. You have 30 days to file the report."},"es":{"q":"En Arkansas, después de un choque con heridos o daños grandes, ¿cuánto tiempo tiene para enviar un informe a la Oficina de Servicios al Conductor?","o":["24 horas","5 días","10 días","30 días"],"h1":"Es más o menos un mes.","h2":"En Arkansas usted debe enviar el informe del choque a la Oficina de Servicios al Conductor dentro de 30 días cuando hay heridos, una muerte o más de $3,000 en daños a la propiedad de una persona.","p":"Correcto. Tiene 30 días para enviar el informe."},"zh":{"q":"在 Arkansas，发生有人受伤或严重损坏的车祸后，你需要在多长时间内向 Office of Driver Services 提交报告？","o":["24 小时","5 天","10 天","30 天"],"h1":"大约是一个月。","h2":"在 Arkansas，如果有人受伤、有人死亡，或者一个人的财产损失超过 $3,000，你必须在 30 天内向 Office of Driver Services 提交车祸报告。","p":"对。你有 30 天时间提交报告。"},"vi":{"q":"Ở Arkansas, sau một vụ tai nạn có người bị thương hoặc hư hại lớn, bạn có bao lâu để gửi báo cáo cho Office of Driver Services?","o":["24 giờ","5 ngày","10 ngày","30 ngày"],"h1":"Khoảng một tháng.","h2":"Ở Arkansas, bạn phải nộp báo cáo tai nạn cho Office of Driver Services trong vòng 30 ngày khi có người bị thương, có người chết, hoặc tài sản của một người bị hư hại hơn $3,000.","p":"Đúng. Bạn có 30 ngày để nộp báo cáo."},"tl":{"q":"Sa Arkansas, pagkatapos ng banggaan na may nasaktan o malaking pinsala, gaano katagal ka para magpadala ng ulat sa Office of Driver Services?","o":["24 na oras","5 araw","10 araw","30 araw"],"h1":"Mga isang buwan ito.","h2":"Sa Arkansas, kailangan mong magpasa ng ulat ng banggaan sa Office of Driver Services sa loob ng 30 araw kapag may nasaktan, may namatay, o may higit sa $3,000 na pinsala sa ari-arian ng isang tao.","p":"Tama. May 30 araw ka para ipasa ang ulat."},"ar":{"q":"في Arkansas، بعد حادث فيه إصابة أو ضرر كبير، ما المدة المتاحة لك لإرسال تقرير إلى Office of Driver Services؟","o":["24 ساعة","5 أيام","10 أيام","30 يومًا"],"h1":"المدة حوالي شهر واحد.","h2":"في Arkansas، يجب أن تقدم تقرير الحادث إلى Office of Driver Services خلال 30 يومًا إذا كانت هناك إصابة أو وفاة أو ضرر بأكثر من $3,000 في ممتلكات شخص واحد.","p":"صحيح. لديك 30 يومًا لتقديم التقرير."},"ref":{"doc":"AR","page":81}},{"id":"ar-029","scope":"AR","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Arkansas, how close to a railroad crossing may you park?","o":["No closer than 50 feet","No closer than 10 feet","No closer than 20 feet","Right next to it"],"h1":"It is more than three times the distance for a fire hydrant.","h2":"In Arkansas you may not park within 50 feet of a railroad crossing.","p":"Right. Park at least 50 feet away from a railroad crossing."},"es":{"q":"En Arkansas, ¿qué tan cerca de un cruce de ferrocarril puede estacionarse?","o":["No más cerca de 50 pies","No más cerca de 10 pies","No más cerca de 20 pies","Justo al lado"],"h1":"Es más de tres veces la distancia para un hidrante.","h2":"En Arkansas usted no puede estacionarse a menos de 50 pies de un cruce de ferrocarril.","p":"Correcto. Estaciónese por lo menos a 50 pies de un cruce de ferrocarril."},"zh":{"q":"在 Arkansas，你可以在离铁路道口多近的地方停车？","o":["不能少于 50 英尺","不能少于 10 英尺","不能少于 20 英尺","紧挨着道口"],"h1":"这个距离是消防栓距离的三倍多。","h2":"在 Arkansas，你不可以在铁路道口 50 英尺以内停车。","p":"对。停车时要离铁路道口至少 50 英尺。"},"vi":{"q":"Ở Arkansas, bạn được đậu xe gần chỗ băng qua đường sắt đến mức nào?","o":["Không gần hơn 50 feet","Không gần hơn 10 feet","Không gần hơn 20 feet","Ngay sát bên cạnh"],"h1":"Khoảng cách này lớn hơn ba lần khoảng cách với trụ nước cứu hỏa.","h2":"Ở Arkansas, bạn không được đậu xe trong vòng 50 feet tính từ chỗ băng qua đường sắt.","p":"Đúng. Hãy đậu xe cách chỗ băng qua đường sắt ít nhất 50 feet."},"tl":{"q":"Sa Arkansas, gaano kalapit sa tawiran ng riles puwede kang pumarada?","o":["Hindi lalapit sa 50 talampakan","Hindi lalapit sa 10 talampakan","Hindi lalapit sa 20 talampakan","Mismong katabi nito"],"h1":"Higit ito sa tatlong beses ng layo para sa fire hydrant.","h2":"Sa Arkansas, hindi ka puwedeng pumarada sa loob ng 50 talampakan mula sa tawiran ng riles.","p":"Tama. Pumarada nang hindi bababa sa 50 talampakan ang layo mula sa tawiran ng riles."},"ar":{"q":"في Arkansas، على أي مسافة من معبر السكة الحديدية يُسمح لك بالوقوف؟","o":["ليس أقرب من 50 قدمًا","ليس أقرب من 10 أقدام","ليس أقرب من 20 قدمًا","بجانبه مباشرة"],"h1":"هذه المسافة أكثر من ثلاثة أضعاف المسافة عن صنبور الإطفاء.","h2":"في Arkansas، لا يجوز لك الوقوف على مسافة أقل من 50 قدمًا من معبر السكة الحديدية.","p":"صحيح. قف على بعد 50 قدمًا على الأقل من معبر السكة الحديدية."},"ref":{"doc":"AR","page":42}},{"id":"ar-030","scope":"AR","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Arkansas, on a highway with several lanes going your way, when may you drive in the far-left lane?","o":["Any time traffic is light","Only at night","When passing, exiting on the left, or when other lanes are closed","Whenever you drive at the speed limit"],"h1":"The left lane is mainly for getting around slower cars.","h2":"In Arkansas you may use the left lane of a multilane highway only to pass, to exit on the left, or when the other lanes are closed or unsafe.","p":"Right. The left lane is for passing, not for cruising."},"es":{"q":"En Arkansas, en una carretera con varios carriles en su dirección, ¿cuándo puede manejar en el carril de la extrema izquierda?","o":["Siempre que haya poco tráfico","Solo de noche","Al rebasar, al salir por la izquierda o si los otros carriles están cerrados","Siempre que maneje al límite de velocidad"],"h1":"El carril izquierdo es más que nada para pasar a los carros lentos.","h2":"En Arkansas usted puede usar el carril izquierdo de una carretera de varios carriles solo para rebasar, para salir por la izquierda o cuando los otros carriles están cerrados o no son seguros.","p":"Correcto. El carril izquierdo es para rebasar, no para ir de paseo."},"zh":{"q":"在 Arkansas，在同方向有多条车道的公路上，你什么时候可以在最左边的车道行驶？","o":["只要车不多就可以","只在晚上","超车、从左边出口驶出，或其他车道关闭时","只要你按限速行驶就可以"],"h1":"左车道主要用来超过开得较慢的车。","h2":"在 Arkansas，你只有在超车、从左边出口驶出，或其他车道关闭或不安全时，才可以使用多车道公路的左车道。","p":"对。左车道是用来超车的，不是用来一直行驶的。"},"vi":{"q":"Ở Arkansas, trên xa lộ có nhiều làn xe cùng chiều với bạn, khi nào bạn được chạy ở làn ngoài cùng bên trái?","o":["Bất cứ lúc nào xe cộ thưa thớt","Chỉ vào ban đêm","Khi vượt xe, khi ra lối bên trái, hoặc khi các làn khác bị đóng","Bất cứ khi nào bạn chạy đúng tốc độ giới hạn"],"h1":"Làn bên trái chủ yếu dùng để vượt qua xe chạy chậm hơn.","h2":"Ở Arkansas, bạn chỉ được dùng làn bên trái của xa lộ nhiều làn để vượt xe, để ra lối bên trái, hoặc khi các làn khác bị đóng hay không an toàn.","p":"Đúng. Làn bên trái dùng để vượt xe, không phải để chạy đều đều."},"tl":{"q":"Sa Arkansas, sa highway na may ilang lane papunta sa direksyon mo, kailan ka puwedeng magmaneho sa pinakakaliwang lane?","o":["Anumang oras na kaunti ang trapiko","Sa gabi lamang","Kapag nag-o-overtake, lalabas sa kaliwa, o sarado ang ibang lane","Tuwing nagmamaneho ka sa speed limit"],"h1":"Ang kaliwang lane ay pangunahing para lampasan ang mas mabagal na sasakyan.","h2":"Sa Arkansas, puwede mong gamitin ang kaliwang lane ng highway na maraming lane para lamang mag-overtake, lumabas sa kaliwa, o kapag sarado o hindi ligtas ang ibang lane.","p":"Tama. Ang kaliwang lane ay para sa pag-overtake, hindi para sa tuloy-tuloy na pagmamaneho."},"ar":{"q":"في Arkansas، على طريق سريع فيه عدة حارات في اتجاهك، متى يُسمح لك بالقيادة في الحارة اليسرى القصوى؟","o":["في أي وقت تكون فيه حركة المرور خفيفة","في الليل فقط","عند التجاوز، أو الخروج من اليسار، أو عندما تكون الحارات الأخرى مغلقة","كلما كنت تقود بالسرعة المحددة"],"h1":"الحارة اليسرى مخصصة أساسًا لتجاوز السيارات الأبطأ.","h2":"في Arkansas، يُسمح لك باستخدام الحارة اليسرى في الطريق السريع متعدد الحارات فقط للتجاوز، أو للخروج من اليسار، أو عندما تكون الحارات الأخرى مغلقة أو غير آمنة.","p":"صحيح. الحارة اليسرى للتجاوز، وليست للقيادة المستمرة."},"ref":{"doc":"AR","page":63}},{"id":"ar-031","scope":"AR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arkansas, which child must ride in a child safety seat?","o":["Any child under 12, at any weight","A child under 6 who weighs less than 60 pounds","Only babies under 1 year old","A child under 10 who is shorter than 5 feet"],"h1":"The rule uses both an age and a weight.","h2":"In Arkansas a child under 6 years old who weighs less than 60 pounds must ride in a child safety seat that is properly secured.","p":"Right. Under 6 and under 60 pounds means a child safety seat."},"es":{"q":"En Arkansas, ¿qué niño debe viajar en un asiento de seguridad infantil?","o":["Cualquier niño menor de 12, de cualquier peso","Un niño menor de 6 que pesa menos de 60 libras","Solo los bebés menores de 1 año","Un niño menor de 10 que mide menos de 5 pies"],"h1":"La regla usa una edad y también un peso.","h2":"En Arkansas un niño menor de 6 años que pesa menos de 60 libras debe viajar en un asiento de seguridad infantil bien sujeto.","p":"Correcto. Menor de 6 y de menos de 60 libras: asiento de seguridad."},"zh":{"q":"在 Arkansas，哪个孩子必须坐儿童安全座椅？","o":["任何 12 岁以下的孩子，不管体重多少","6 岁以下且体重不到 60 磅的孩子","只有 1 岁以下的婴儿","10 岁以下且身高不到 5 英尺的孩子"],"h1":"这条规定同时看年龄和体重。","h2":"在 Arkansas，6 岁以下并且体重不到 60 磅的孩子必须坐在固定好的儿童安全座椅里。","p":"对。6 岁以下并且不到 60 磅，就要坐儿童安全座椅。"},"vi":{"q":"Ở Arkansas, trẻ em nào phải ngồi ghế an toàn cho trẻ em?","o":["Bất kỳ trẻ nào dưới 12 tuổi, với bất kỳ cân nặng nào","Trẻ dưới 6 tuổi và nặng dưới 60 pound","Chỉ em bé dưới 1 tuổi","Trẻ dưới 10 tuổi và thấp hơn 5 feet"],"h1":"Quy định này dùng cả tuổi và cân nặng.","h2":"Ở Arkansas, trẻ dưới 6 tuổi và nặng dưới 60 pound phải ngồi trong ghế an toàn cho trẻ em được gắn chắc chắn đúng cách.","p":"Đúng. Dưới 6 tuổi và dưới 60 pound thì phải ngồi ghế an toàn cho trẻ em."},"tl":{"q":"Sa Arkansas, aling bata ang dapat nakasakay sa child safety seat?","o":["Sinumang batang wala pang 12 taong gulang, anuman ang timbang","Batang wala pang 6 taong gulang na mas magaan sa 60 pounds","Mga sanggol lamang na wala pang 1 taong gulang","Batang wala pang 10 taong gulang na mas maikli sa 5 talampakan"],"h1":"Ginagamit ng patakaran ang edad at ang timbang.","h2":"Sa Arkansas, ang batang wala pang 6 taong gulang na mas magaan sa 60 pounds ay dapat nakasakay sa child safety seat na maayos na nakakabit.","p":"Tama. Wala pang 6 na taon at wala pang 60 pounds ay kailangan ng child safety seat."},"ar":{"q":"في Arkansas، أي طفل يجب أن يجلس في مقعد أمان للأطفال؟","o":["أي طفل عمره أقل من 12 سنة، مهما كان وزنه","طفل عمره أقل من 6 سنوات ووزنه أقل من 60 رطلًا","الرضّع الذين عمرهم أقل من سنة واحدة (1) فقط","طفل عمره أقل من 10 سنوات وطوله أقل من 5 أقدام"],"h1":"القاعدة تستخدم العمر والوزن معًا.","h2":"في Arkansas، يجب أن يجلس الطفل الذي عمره أقل من 6 سنوات ووزنه أقل من 60 رطلًا في مقعد أمان للأطفال مثبّت بشكل صحيح.","p":"صحيح. أقل من 6 سنوات وأقل من 60 رطلًا يعني مقعد أمان للأطفال."},"ref":{"doc":"AR","page":9}},{"id":"ar-032","scope":"AR","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arkansas, when is it against the law to smoke tobacco in a car?","o":["Only while the car is moving fast","Only when the windows are closed","Never, it is always allowed","When a child under 14 is riding in the car"],"h1":"The law protects young passengers from smoke.","h2":"In Arkansas no one may knowingly smoke tobacco in a vehicle when a child under 14 years old is a passenger.","p":"Right. No smoking with a child under 14 in the car."},"es":{"q":"En Arkansas, ¿cuándo es ilegal fumar tabaco en un carro?","o":["Solo cuando el carro va rápido","Solo con las ventanas cerradas","Nunca, siempre está permitido","Cuando un niño menor de 14 años va en el carro"],"h1":"La ley protege del humo a los pasajeros jóvenes.","h2":"En Arkansas nadie puede fumar tabaco a sabiendas en un vehículo cuando va un pasajero menor de 14 años.","p":"Correcto. No se fuma con un niño menor de 14 en el carro."},"zh":{"q":"在 Arkansas，什么时候在车里吸烟是违法的？","o":["只有在车开得很快的时候","只有在车窗关着的时候","从来不违法，总是可以","当车里坐着 14 岁以下的孩子时"],"h1":"这条法律保护年幼的乘客不受烟雾伤害。","h2":"在 Arkansas，当车里有 14 岁以下的孩子乘坐时，任何人都不可以故意在车里吸烟。","p":"对。车里有 14 岁以下的孩子时不能吸烟。"},"vi":{"q":"Ở Arkansas, khi nào hút thuốc lá trong xe là phạm luật?","o":["Chỉ khi xe đang chạy nhanh","Chỉ khi cửa sổ đóng","Không bao giờ, lúc nào cũng được phép","Khi có trẻ em dưới 14 tuổi đang ngồi trong xe"],"h1":"Luật này bảo vệ hành khách nhỏ tuổi khỏi khói thuốc.","h2":"Ở Arkansas, không ai được cố ý hút thuốc lá trong xe khi có trẻ em dưới 14 tuổi là hành khách.","p":"Đúng. Không được hút thuốc khi có trẻ em dưới 14 tuổi trong xe."},"tl":{"q":"Sa Arkansas, kailan labag sa batas ang manigarilyo sa loob ng kotse?","o":["Kapag mabilis lang ang takbo ng kotse","Kapag nakasara lang ang mga bintana","Hindi kailanman, palaging puwede","Kapag may batang wala pang 14 taong gulang na nakasakay sa kotse"],"h1":"Pinoprotektahan ng batas ang mga batang pasahero mula sa usok.","h2":"Sa Arkansas, walang sinuman ang puwedeng sadyang manigarilyo sa loob ng sasakyan kapag may pasaherong bata na wala pang 14 taong gulang.","p":"Tama. Bawal manigarilyo kapag may batang wala pang 14 taong gulang sa kotse."},"ar":{"q":"في Arkansas، متى يكون التدخين داخل السيارة مخالفًا للقانون؟","o":["فقط عندما تسير السيارة بسرعة","فقط عندما تكون النوافذ مغلقة","أبدًا، فهو مسموح دائمًا","عندما يكون في السيارة طفل عمره أقل من 14 سنة"],"h1":"القانون يحمي الركاب الصغار من الدخان.","h2":"في Arkansas، لا يجوز لأي شخص أن يدخن عمدًا داخل مركبة إذا كان فيها راكب طفل عمره أقل من 14 سنة.","p":"صحيح. ممنوع التدخين إذا كان في السيارة طفل عمره أقل من 14 سنة."},"ref":{"doc":"AR","page":9}},{"id":"ar-033","scope":"AR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arkansas, you just moved to the state and became a resident. How soon must you get an Arkansas driver's license?","o":["Within 6 months","Within 30 days","Within 1 year","Only when your old license expires"],"h1":"It is less than two months.","h2":"A new Arkansas resident must get an Arkansas driver's license within 30 days.","p":"Right. New residents have 30 days to get an Arkansas license."},"es":{"q":"En Arkansas, usted se acaba de mudar al estado y ya es residente. ¿En cuánto tiempo debe obtener una licencia de conducir de Arkansas?","o":["Dentro de 6 meses","Dentro de 30 días","Dentro de 1 año","Solo cuando venza su licencia anterior"],"h1":"Es menos de dos meses.","h2":"Un nuevo residente de Arkansas debe obtener una licencia de conducir de Arkansas dentro de 30 días.","p":"Correcto. Los nuevos residentes tienen 30 días para obtener una licencia de Arkansas."},"ref":{"doc":"AR","page":2}},{"id":"ar-034","scope":"AR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arkansas, what is the minimum vision without glasses or contacts needed for a license with no glasses restriction?","o":["20/20","20/100","20/200","20/40"],"h1":"It is a little less than perfect vision.","h2":"In Arkansas you need at least 20/40 vision without glasses or contacts for a license with no glasses restriction.","p":"Right. 20/40 without glasses is the minimum for an unrestricted license."},"es":{"q":"En Arkansas, ¿cuál es la visión mínima sin anteojos ni lentes de contacto para una licencia sin restricción de anteojos?","o":["20/20","20/100","20/200","20/40"],"h1":"Es un poco menos que una visión perfecta.","h2":"En Arkansas usted necesita por lo menos una visión de 20/40 sin anteojos ni lentes de contacto para una licencia sin restricción de anteojos.","p":"Correcto. 20/40 sin anteojos es el mínimo para una licencia sin restricción."},"ref":{"doc":"AR","page":5}},{"id":"ar-035","scope":"AR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arkansas, a teen under 18 who was born in the United States is applying for a permit. What must the teen bring as proof of birth?","o":["An original or certified U.S. birth certificate","A U.S. passport","A hospital birth certificate","A photocopy of a birth certificate"],"h1":"The state asks minors for one specific paper from the government office that records births.","h2":"In Arkansas, a U.S.-born applicant under 18 must bring an original or certified U.S. birth certificate; a passport, a hospital certificate, or a copy is not accepted.","p":"Right. Minors born in the U.S. need an original or certified birth certificate."},"es":{"q":"En Arkansas, un adolescente menor de 18 años que nació en los Estados Unidos solicita un permiso. ¿Qué debe llevar como prueba de nacimiento?","o":["Un acta de nacimiento de EE. UU. original o certificada","Un pasaporte de EE. UU.","Un certificado de nacimiento del hospital","Una fotocopia del acta de nacimiento"],"h1":"El estado pide a los menores un documento específico de la oficina del gobierno que registra los nacimientos.","h2":"En Arkansas, un solicitante menor de 18 años nacido en EE. UU. debe llevar un acta de nacimiento de EE. UU. original o certificada; no se acepta un pasaporte, un certificado del hospital ni una copia.","p":"Correcto. Los menores nacidos en EE. UU. necesitan un acta de nacimiento original o certificada."},"ref":{"doc":"AR","page":7}},{"id":"ar-036","scope":"AR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arkansas, you finished a Motorcycle Safety Foundation RiderCourse. How long do you have to show the completion card to skip the motorcycle skills test?","o":["30 days","1 year","90 days","2 years"],"h1":"It is about three months.","h2":"In Arkansas you must show your RiderCourse completion card to a State Police examiner within 90 days to have the motorcycle skills test waived.","p":"Right. Bring the course card within 90 days to skip the skills test."},"es":{"q":"En Arkansas, usted terminó un curso RiderCourse de la Motorcycle Safety Foundation. ¿Cuánto tiempo tiene para mostrar la tarjeta del curso y no hacer la prueba práctica de motocicleta?","o":["30 días","1 año","90 días","2 años"],"h1":"Son unos tres meses.","h2":"En Arkansas usted debe mostrar la tarjeta del curso RiderCourse a un examinador de la Policía Estatal dentro de 90 días para que no le exijan la prueba práctica de motocicleta.","p":"Correcto. Lleve la tarjeta del curso dentro de 90 días para no hacer la prueba práctica."},"ref":{"doc":"AR","page":4}},{"id":"ar-037","scope":"AR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arkansas, a Motorized Bicycle Certificate lets a young rider drive a motorized bicycle or motorcycle up to what engine size?","o":["125 cc","50 cc","250 cc","500 cc"],"h1":"It is the smallest of these engine sizes.","h2":"In Arkansas, a Motorized Bicycle Certificate covers motorized bicycles and motorcycles of 50 cc or less.","p":"Right. The Motorized Bicycle Certificate is for engines of 50 cc or less."},"es":{"q":"En Arkansas, ¿hasta qué tamaño de motor permite un Certificado de Bicicleta Motorizada que un conductor joven maneje una bicicleta motorizada o motocicleta?","o":["125 cc","50 cc","250 cc","500 cc"],"h1":"Es el tamaño de motor más pequeño de estos.","h2":"En Arkansas, el Certificado de Bicicleta Motorizada cubre bicicletas motorizadas y motocicletas de 50 cc o menos.","p":"Correcto. El Certificado de Bicicleta Motorizada es para motores de 50 cc o menos."},"ref":{"doc":"AR","page":5}},{"id":"ar-038","scope":"AR","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arkansas, what is the highest fine for a driver or front-seat passenger who does not wear a seat belt, not counting court costs?","o":["$100","$250","$500","$25"],"h1":"It is the smallest amount listed.","h2":"In Arkansas, not wearing a seat belt can bring a fine of up to $25, plus court costs.","p":"Right. The seat belt fine is up to $25, plus court costs."},"es":{"q":"En Arkansas, ¿cuál es la multa más alta para un conductor o pasajero del asiento delantero que no usa el cinturón de seguridad, sin contar los costos del tribunal?","o":["$100","$250","$500","$25"],"h1":"Es la cantidad más pequeña de la lista.","h2":"En Arkansas, no usar el cinturón de seguridad puede traer una multa de hasta $25, más los costos del tribunal.","p":"Correcto. La multa por no usar el cinturón es de hasta $25, más los costos del tribunal."},"ref":{"doc":"AR","page":9}},{"id":"ar-039","scope":"AR","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Arkansas, children under what age must wear a proper safety restraint whenever the car is moving?","o":["8","12","15","18"],"h1":"It is a teen age, three years before 18.","h2":"In Arkansas, all children under 15 must wear a proper safety restraint while the vehicle is moving.","p":"Right. Every child under 15 must be buckled up while the car moves."},"es":{"q":"En Arkansas, ¿los niños menores de qué edad deben usar un sistema de seguridad adecuado siempre que el auto esté en movimiento?","o":["8","12","15","18"],"h1":"Es una edad de adolescente, tres años antes de los 18.","h2":"En Arkansas, todos los niños menores de 15 años deben usar un sistema de seguridad adecuado mientras el vehículo está en movimiento.","p":"Correcto. Todo niño menor de 15 años debe ir abrochado mientras el auto se mueve."},"ref":{"doc":"AR","page":9}},{"id":"ar-040","scope":"AR","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arkansas, what is the highest fine for a first littering offense?","o":["$1,000","$50","$250","$5,000"],"h1":"It is a four-digit amount.","h2":"In Arkansas, a first littering conviction can bring a fine of up to $1,000 and up to eight hours of community service.","p":"Right. A first littering offense can cost up to $1,000."},"es":{"q":"En Arkansas, ¿cuál es la multa más alta por tirar basura por primera vez?","o":["$1,000","$50","$250","$5,000"],"h1":"Es una cantidad de cuatro cifras.","h2":"En Arkansas, una primera condena por tirar basura puede traer una multa de hasta $1,000 y hasta ocho horas de servicio comunitario.","p":"Correcto. Tirar basura por primera vez puede costar hasta $1,000."},"ref":{"doc":"AR","page":10}},{"id":"ar-041","scope":"AR","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Arkansas, besides a fine, what can a court do to a driver who breaks the move-over law?","o":["Take away the driver's car for good","Revoke the license for life","Nothing else; only a fine is allowed","Suspend the driver's license for up to six months"],"h1":"The license can be affected for a limited time.","h2":"In Arkansas, a court can suspend the license of a driver who breaks the move-over law for up to six months, and can also order jail or community service.","p":"Right. Breaking the move-over law can cost you your license for up to six months."},"es":{"q":"En Arkansas, además de una multa, ¿qué puede hacer un tribunal a un conductor que no cumple la ley de cambiarse de carril (move over)?","o":["Quitarle el auto para siempre","Revocar la licencia de por vida","Nada más; solo se permite una multa","Suspender su licencia hasta por seis meses"],"h1":"La licencia puede verse afectada por un tiempo limitado.","h2":"En Arkansas, un tribunal puede suspender hasta por seis meses la licencia del conductor que no cumple la ley de cambiarse de carril, y también puede ordenar cárcel o servicio comunitario.","p":"Correcto. No cumplir esa ley puede costarle la licencia hasta por seis meses."},"ref":{"doc":"AR","page":11}},{"id":"ar-042","scope":"AR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arkansas, you get a ticket for a moving violation in a work zone while workers are present. What happens to the fine?","o":["It stays the same","It is doubled","It is cut in half","It is replaced by a warning"],"h1":"Work zone signs warn you about this.","h2":"In Arkansas, the fine for a moving violation in a work zone with workers present is doubled.","p":"Right. Fines double in work zones when workers are there."},"es":{"q":"En Arkansas, usted recibe una multa por una infracción en movimiento en una zona de construcción mientras hay trabajadores. ¿Qué pasa con la multa?","o":["Se queda igual","Se duplica","Se reduce a la mitad","Se cambia por una advertencia"],"h1":"Las señales de las zonas de construcción le avisan de esto.","h2":"En Arkansas, la multa por una infracción en movimiento en una zona de construcción con trabajadores presentes se duplica.","p":"Correcto. Las multas se duplican en zonas de construcción cuando hay trabajadores."},"ref":{"doc":"AR","page":19}},{"id":"ar-043","scope":"AR","cat":"signals","sign":null,"c":0,"en":{"q":"In Arkansas, you see flashing green lights on a road maintenance truck. What do they tell you?","o":["Workers are active here, so slow down and use caution","You may go faster than the speed limit","The truck is about to turn left","The road ahead is closed to all traffic"],"h1":"These lights were added to make road crews easier to see.","h2":"In Arkansas, flashing green lights on a construction or maintenance vehicle mean an active work zone, so you should slow down and be careful.","p":"Right. Flashing green lights mean an active work zone: slow down."},"es":{"q":"En Arkansas, usted ve luces verdes intermitentes en un camión de mantenimiento de carreteras. ¿Qué le indican?","o":["Hay trabajadores activos aquí, así que reduzca la velocidad y tenga cuidado","Puede ir más rápido que el límite de velocidad","El camión va a girar a la izquierda","La carretera más adelante está cerrada a todo el tráfico"],"h1":"Estas luces se agregaron para que las cuadrillas de trabajo se vean mejor.","h2":"En Arkansas, las luces verdes intermitentes en un vehículo de construcción o mantenimiento indican una zona de trabajo activa, así que usted debe reducir la velocidad y tener cuidado.","p":"Correcto. Las luces verdes intermitentes indican una zona de trabajo activa: reduzca la velocidad."},"ref":{"doc":"AR","page":18}},{"id":"ar-044","scope":"AR","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Arkansas, what is the speed limit on a county road when the county judge has not set one?","o":["25 mph","55 mph","40 mph","65 mph"],"h1":"It is between a city street speed and a highway speed.","h2":"In Arkansas, if the county judge has not set a speed limit on a county road, the limit is 40 mph.","p":"Right. An unposted county road has a 40 mph limit."},"es":{"q":"En Arkansas, ¿cuál es el límite de velocidad en un camino del condado cuando el juez del condado no ha fijado uno?","o":["25 mph","55 mph","40 mph","65 mph"],"h1":"Está entre la velocidad de una calle de ciudad y la de una carretera.","h2":"En Arkansas, si el juez del condado no ha fijado un límite de velocidad en un camino del condado, el límite es de 40 mph.","p":"Correcto. Un camino del condado sin límite fijado tiene un límite de 40 mph."},"ref":{"doc":"AR","page":26}},{"id":"ar-045","scope":"AR","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Arkansas, you turn left out of a driveway onto a road with a shared center turn lane. How may you NOT use the center lane?","o":["As a short stop to wait for a gap","As part of your left turn","As a place to wait while turning left from the road","As a lane to speed up in before merging"],"h1":"You may pause there, but not build speed there.","h2":"In Arkansas you may use a shared center turn lane as part of a left turn to merge into traffic, but never as an acceleration lane.","p":"Right. The center turn lane is never an acceleration lane."},"es":{"q":"En Arkansas, usted gira a la izquierda al salir de una entrada de autos hacia una calle con un carril central compartido para girar. ¿Cómo NO puede usar el carril central?","o":["Como una parada corta para esperar un espacio","Como parte de su giro a la izquierda","Como lugar para esperar mientras gira a la izquierda desde la calle","Como carril para acelerar antes de incorporarse"],"h1":"Puede detenerse ahí un momento, pero no tomar velocidad ahí.","h2":"En Arkansas usted puede usar un carril central compartido como parte de un giro a la izquierda para incorporarse al tráfico, pero nunca como carril de aceleración.","p":"Correcto. El carril central para girar nunca es un carril de aceleración."},"ref":{"doc":"AR","page":32}},{"id":"ar-046","scope":"AR","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Arkansas, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 15 feet","No closer than 50 feet","No closer than 100 feet"],"h1":"Firefighters need room to reach it with a hose.","h2":"In Arkansas you may not park within 15 feet of a fire hydrant.","p":"Right. Park at least 15 feet away from a fire hydrant."},"es":{"q":"En Arkansas, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 15 pies","No más cerca de 50 pies","No más cerca de 100 pies"],"h1":"Los bomberos necesitan espacio para llegar a él con una manguera.","h2":"En Arkansas usted no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Estaciónese por lo menos a 15 pies de un hidrante."},"ref":{"doc":"AR","page":42}},{"id":"ar-047","scope":"AR","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Arkansas, how close to a stop sign, yield sign, or traffic light may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 30 feet","No closer than 100 feet"],"h1":"Other drivers must be able to see the sign or light.","h2":"In Arkansas you may not park within 30 feet of a stop sign, yield sign, or traffic signal.","p":"Right. Stay at least 30 feet away from a stop sign, yield sign, or traffic light."},"es":{"q":"En Arkansas, ¿qué tan cerca de una señal de alto, una señal de ceda el paso o un semáforo puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 30 pies","No más cerca de 100 pies"],"h1":"Los demás conductores deben poder ver la señal o el semáforo.","h2":"En Arkansas usted no puede estacionarse a menos de 30 pies de una señal de alto, una señal de ceda el paso o un semáforo.","p":"Correcto. Manténgase por lo menos a 30 pies de una señal de alto, de ceda el paso o de un semáforo."},"ref":{"doc":"AR","page":42}},{"id":"ar-048","scope":"AR","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arkansas, it is raining and you need your windshield wipers. What does state law also require?","o":["Turn on your headlights","Turn on your hazard lights","Use only your parking lights","Turn on your high beams"],"h1":"Think about being seen by other drivers.","h2":"Arkansas law requires you to turn on your headlights whenever you need your windshield wipers.","p":"Right. Wipers on means headlights on in Arkansas."},"es":{"q":"En Arkansas, está lloviendo y usted necesita los limpiaparabrisas. ¿Qué más exige la ley del estado?","o":["Encender los faros delanteros","Encender las luces de emergencia","Usar solo las luces de estacionamiento","Encender las luces altas"],"h1":"Piense en que los demás conductores lo vean.","h2":"La ley de Arkansas exige encender los faros delanteros siempre que usted necesite los limpiaparabrisas.","p":"Correcto. En Arkansas, si usa los limpiaparabrisas, encienda los faros."},"ref":{"doc":"AR","page":51}},{"id":"ar-049","scope":"AR","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arkansas, you see a bicycle with a red or orange pennant flag on it. What does the flag tell you?","o":["The rider is in a race","The bicycle has an engine","The rider is about to turn left","The rider has trouble hearing, so slow down"],"h1":"The flag tells you something about the rider, not the bike.","h2":"In Arkansas, a red or orange pennant flag on a bicycle means the rider has impaired hearing, so you should slow down.","p":"Right. A red or orange flag on a bike means the rider may not hear you."},"es":{"q":"En Arkansas, usted ve una bicicleta con una bandera triangular roja o anaranjada. ¿Qué le indica la bandera?","o":["El ciclista está en una carrera","La bicicleta tiene motor","El ciclista va a girar a la izquierda","El ciclista tiene problemas de audición, así que reduzca la velocidad"],"h1":"La bandera le dice algo sobre el ciclista, no sobre la bicicleta.","h2":"En Arkansas, una bandera triangular roja o anaranjada en una bicicleta significa que el ciclista tiene problemas de audición, así que usted debe reducir la velocidad.","p":"Correcto. Una bandera roja o anaranjada en una bicicleta indica que el ciclista quizás no lo oiga."},"ref":{"doc":"AR","page":68}},{"id":"ar-050","scope":"AR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arkansas, what fine can a driver face for a first conviction of driving while intoxicated, not counting court costs?","o":["$25 to $100","$150 to $1,000","$5,000 to $10,000","No fine, only a warning"],"h1":"The top of the range is a four-digit amount.","h2":"In Arkansas, a first DWI conviction brings a fine of $150 to $1,000, plus court costs.","p":"Right. A first DWI can cost $150 to $1,000 in fines."},"es":{"q":"En Arkansas, ¿qué multa puede recibir un conductor por una primera condena por manejar en estado de ebriedad (DWI), sin contar los costos del tribunal?","o":["De $25 a $100","De $150 a $1,000","De $5,000 a $10,000","Ninguna multa, solo una advertencia"],"h1":"El máximo es una cantidad de cuatro cifras.","h2":"En Arkansas, una primera condena por DWI trae una multa de $150 a $1,000, más los costos del tribunal.","p":"Correcto. Un primer DWI puede costar de $150 a $1,000 en multas."},"ref":{"doc":"AR","page":74}},{"id":"ar-051","scope":"AR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arkansas, a police officer asks you to take an alcohol test. Who chooses which kind of test you take?","o":["You, the driver","A judge, later in court","The police officer","Your insurance company"],"h1":"It is the person who asks you to take the test.","h2":"In Arkansas, the law enforcement officer chooses which alcohol test to request, and you can lose your license if you refuse.","p":"Right. The officer picks the test, and refusing can cost you your license."},"es":{"q":"En Arkansas, un policía le pide que se haga una prueba de alcohol. ¿Quién elige qué tipo de prueba se hace?","o":["Usted, el conductor","Un juez, más tarde en el tribunal","El policía","Su compañía de seguros"],"h1":"Es la persona que le pide que se haga la prueba.","h2":"En Arkansas, el agente de la ley elige qué prueba de alcohol pedir, y usted puede perder la licencia si se niega.","p":"Correcto. El policía elige la prueba, y negarse le puede costar la licencia."},"ref":{"doc":"AR","page":74}},{"id":"ar-052","scope":"AR","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arkansas, when may a person with epilepsy drive?","o":["When under a doctor's care and seizure-free for one year","Never, for any reason","Only with another adult in the car","Only during daylight hours"],"h1":"Two things are needed: medical care and a stretch of time.","h2":"In Arkansas, a person with epilepsy may drive if they are under a doctor's care and have been seizure-free for one year.","p":"Right. With a doctor's care and one year without a seizure, a person with epilepsy may drive."},"es":{"q":"En Arkansas, ¿cuándo puede manejar una persona con epilepsia?","o":["Cuando está bajo el cuidado de un médico y lleva un año sin convulsiones","Nunca, por ninguna razón","Solo con otro adulto en el auto","Solo durante el día"],"h1":"Se necesitan dos cosas: atención médica y cierto tiempo.","h2":"En Arkansas, una persona con epilepsia puede manejar si está bajo el cuidado de un médico y lleva un año sin convulsiones.","p":"Correcto. Con atención médica y un año sin convulsiones, una persona con epilepsia puede manejar."},"ref":{"doc":"AR","page":72}},{"id":"az-001","scope":"AZ","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arizona, what is the youngest age to apply for a regular instruction permit (not one only for a school driving class)?","o":["17 years old","16 years old","15 and a half years old","14 and a half years old"],"h1":"It is half a year past a birthday, before age 16.","h2":"In Arizona you can apply for an instruction permit at 15 years and 6 months, so you can practice before you turn 16.","p":"Right. The Arizona permit starts at 15 and a half."},"es":{"q":"En Arizona, ¿cuál es la edad mínima para solicitar un permiso de aprendizaje normal (no uno solo para una clase de manejo escolar)?","o":["17 años","16 años","15 años y medio","14 años y medio"],"h1":"Es medio año después de un cumpleaños, antes de los 16.","h2":"En Arizona usted puede solicitar el permiso de aprendizaje a los 15 años y 6 meses, para practicar antes de cumplir 16.","p":"Correcto. El permiso en Arizona empieza a los 15 años y medio."},"zh":{"q":"在 Arizona，最小几岁可以申请普通的学习驾照（instruction permit，不是只用于学校驾驶课的那种）？","o":["17 岁","16 岁","15 岁半","14 岁半"],"h1":"它是某个生日后再过半年，在 16 岁之前。","h2":"在 Arizona，你 15 岁 6 个月就可以申请学习驾照，这样在 16 岁前就能练车。","p":"对。Arizona 的学习驾照从 15 岁半开始。"},"vi":{"q":"Ở Arizona, tuổi nhỏ nhất để xin giấy phép tập lái thông thường (instruction permit, không phải loại chỉ dùng cho lớp học lái ở trường) là bao nhiêu?","o":["17 tuổi","16 tuổi","15 tuổi rưỡi","14 tuổi rưỡi"],"h1":"Đó là nửa năm sau một ngày sinh nhật, trước 16 tuổi.","h2":"Ở Arizona, bạn có thể xin giấy phép tập lái khi 15 tuổi 6 tháng, để có thể tập lái trước khi đủ 16 tuổi.","p":"Đúng. Ở Arizona, giấy phép tập lái bắt đầu từ 15 tuổi rưỡi."},"tl":{"q":"Sa Arizona, ano ang pinakabatang edad para mag-apply ng regular na instruction permit (hindi ang permit na para lang sa driving class sa paaralan)?","o":["17 taong gulang","16 taong gulang","15 at kalahating taong gulang","14 at kalahating taong gulang"],"h1":"Kalahating taon ito pagkatapos ng isang kaarawan, bago mag-16.","h2":"Sa Arizona, puwede kang mag-apply ng instruction permit sa edad na 15 taon at 6 na buwan, para makapag-practice ka bago ka mag-16.","p":"Tama. Nagsisimula ang permit sa Arizona sa 15 at kalahati."},"ar":{"q":"في Arizona، ما أصغر عمر للتقدّم بطلب تصريح تعلّم عادي (instruction permit)، وليس التصريح الخاص بدروس القيادة في المدرسة فقط؟","o":["17 سنة","16 سنة","15 سنة ونصف","14 سنة ونصف"],"h1":"هو نصف سنة بعد عيد ميلاد، قبل عمر 16.","h2":"في Arizona يمكنك التقدّم بطلب تصريح التعلّم في عمر 15 سنة و6 أشهر، حتى تتدرّب قبل أن تبلغ 16.","p":"صحيح. في Arizona يبدأ التصريح في عمر 15 سنة ونصف."},"ref":{"doc":"AZ","page":10}},{"id":"az-002","scope":"AZ","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arizona, a teen who takes no driver education and no driving safety course must have supervised practice. How many hours in total?","o":["10 hours","30 hours","40 hours","50 hours"],"h1":"It is fewer hours than many other states ask for.","h2":"An Arizona teen who skips approved driver education must have a parent or guardian certify at least 30 hours of supervised driving, 10 of them at night, before getting a graduated license.","p":"Right. Arizona asks for 30 supervised hours."},"es":{"q":"En Arizona, un adolescente que no toma ningún curso de manejo ni de seguridad vial debe tener práctica supervisada. ¿Cuántas horas en total?","o":["10 horas","30 horas","40 horas","50 horas"],"h1":"Son menos horas que en muchos otros estados.","h2":"Un adolescente en Arizona que no toma un curso aprobado de educación vial necesita que su padre, madre o tutor certifique por lo menos 30 horas de manejo supervisado, 10 de ellas de noche, antes de obtener la licencia graduada.","p":"Correcto. Arizona pide 30 horas supervisadas."},"zh":{"q":"在 Arizona，没有上驾驶教育课、也没有上安全驾驶课的青少年必须有人监督练车。一共要多少小时？","o":["10 小时","30 小时","40 小时","50 小时"],"h1":"它比很多其他州要求的小时数少。","h2":"在 Arizona，没有上认可的驾驶教育课的青少年，必须由父母或监护人证明至少 30 小时有人监督的驾驶，其中 10 小时在夜间，才能拿到分级驾照。","p":"对。Arizona 要求 30 小时有人监督的驾驶。"},"vi":{"q":"Ở Arizona, thiếu niên không học lớp giáo dục lái xe và không học lớp lái xe an toàn phải tập lái có người giám sát. Tổng cộng bao nhiêu giờ?","o":["10 giờ","30 giờ","40 giờ","50 giờ"],"h1":"Số giờ này ít hơn nhiều tiểu bang khác yêu cầu.","h2":"Ở Arizona, thiếu niên không học lớp giáo dục lái xe được công nhận phải có cha mẹ hoặc người giám hộ xác nhận ít nhất 30 giờ lái xe có giám sát, trong đó 10 giờ vào ban đêm, trước khi lấy bằng lái theo cấp bậc.","p":"Đúng. Arizona yêu cầu 30 giờ lái xe có giám sát."},"tl":{"q":"Sa Arizona, ang tinedyer na hindi kumuha ng driver education at walang driving safety course ay kailangang mag-practice na may nagbabantay. Ilang oras lahat?","o":["10 oras","30 oras","40 oras","50 oras"],"h1":"Mas kaunti ito kaysa sa hinihingi ng maraming ibang estado.","h2":"Sa Arizona, ang tinedyer na hindi kumuha ng aprubadong driver education ay kailangang may magulang o guardian na magpapatunay ng hindi bababa sa 30 oras ng pagmamaneho na may nagbabantay, 10 dito sa gabi, bago makakuha ng graduated license.","p":"Tama. Humihingi ang Arizona ng 30 oras na may nagbabantay."},"ar":{"q":"في Arizona، المراهق الذي لا يأخذ دورة تعليم قيادة ولا دورة قيادة آمنة يجب أن يتدرّب تحت إشراف. كم ساعة في المجموع؟","o":["10 ساعات","30 ساعة","40 ساعة","50 ساعة"],"h1":"هي ساعات أقل مما تطلبه ولايات كثيرة أخرى.","h2":"في Arizona، المراهق الذي لا يأخذ دورة تعليم قيادة معتمدة يجب أن يشهد أحد والديه أو وليّ أمره على 30 ساعة على الأقل من القيادة تحت إشراف، منها 10 ساعات في الليل، قبل الحصول على الرخصة المتدرّجة.","p":"صحيح. Arizona تطلب 30 ساعة تحت إشراف."},"ref":{"doc":"AZ","page":11}},{"id":"az-003","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, how many of the 30 supervised practice hours must be done at night?","o":["At least 10 hours","At least 5 hours","At least 15 hours","At least 20 hours"],"h1":"It is one third of the 30 total hours.","h2":"At least 10 of the 30 supervised hours must be at night in Arizona, because driving in the dark needs its own practice.","p":"Right. At least 10 of the hours must be at night."},"es":{"q":"En Arizona, ¿cuántas de las 30 horas de práctica supervisada deben ser de noche?","o":["Por lo menos 10 horas","Por lo menos 5 horas","Por lo menos 15 horas","Por lo menos 20 horas"],"h1":"Es la tercera parte de las 30 horas en total.","h2":"En Arizona, por lo menos 10 de las 30 horas supervisadas deben ser de noche, porque manejar en la oscuridad requiere su propia práctica.","p":"Correcto. Por lo menos 10 horas deben ser de noche."},"zh":{"q":"在 Arizona，30 小时有人监督的练车中，有多少小时必须在夜间？","o":["至少 10 小时","至少 5 小时","至少 15 小时","至少 20 小时"],"h1":"它是 30 小时的三分之一。","h2":"在 Arizona，30 小时有人监督的练车中，至少 10 小时必须在夜间，因为在黑暗中开车需要专门练习。","p":"对。至少 10 小时必须在夜间。"},"vi":{"q":"Ở Arizona, trong 30 giờ tập lái có giám sát, bao nhiêu giờ phải lái vào ban đêm?","o":["Ít nhất 10 giờ","Ít nhất 5 giờ","Ít nhất 15 giờ","Ít nhất 20 giờ"],"h1":"Đó là một phần ba của tổng 30 giờ.","h2":"Ở Arizona, ít nhất 10 trong 30 giờ có giám sát phải lái vào ban đêm, vì lái xe trong bóng tối cần được tập riêng.","p":"Đúng. Ít nhất 10 giờ phải lái vào ban đêm."},"tl":{"q":"Sa Arizona, ilan sa 30 oras ng practice na may nagbabantay ang dapat gawin sa gabi?","o":["Hindi bababa sa 10 oras","Hindi bababa sa 5 oras","Hindi bababa sa 15 oras","Hindi bababa sa 20 oras"],"h1":"Ito ay isang-katlo ng kabuuang 30 oras.","h2":"Sa Arizona, hindi bababa sa 10 sa 30 oras na may nagbabantay ang dapat sa gabi, dahil ang pagmamaneho sa dilim ay kailangan ng sariling practice.","p":"Tama. Hindi bababa sa 10 oras ang dapat sa gabi."},"ar":{"q":"في Arizona، كم ساعة من الساعات الـ30 للتدريب تحت إشراف يجب أن تكون في الليل؟","o":["10 ساعات على الأقل","5 ساعات على الأقل","15 ساعة على الأقل","20 ساعة على الأقل"],"h1":"هي ثلث مجموع الساعات الـ30.","h2":"في Arizona، يجب أن تكون 10 ساعات على الأقل من الساعات الـ30 تحت إشراف في الليل، لأن القيادة في الظلام تحتاج إلى تدريب خاص بها.","p":"صحيح. 10 ساعات على الأقل يجب أن تكون في الليل."},"ref":{"doc":"AZ","page":11}},{"id":"az-004","scope":"AZ","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arizona, how long must a teen hold the instruction permit before getting a graduated license?","o":["1 month","3 months","1 year","6 months"],"h1":"It is half a year.","h2":"An Arizona teen must hold the instruction permit for at least 6 months before getting a graduated license, so there is time to practice.","p":"Right. Hold the permit for at least 6 months."},"es":{"q":"En Arizona, ¿cuánto tiempo debe tener un adolescente el permiso de aprendizaje antes de obtener la licencia graduada?","o":["1 mes","3 meses","1 año","6 meses"],"h1":"Es medio año.","h2":"Un adolescente en Arizona debe tener el permiso de aprendizaje por lo menos 6 meses antes de obtener la licencia graduada, para tener tiempo de practicar.","p":"Correcto. Debe tener el permiso por lo menos 6 meses."},"zh":{"q":"在 Arizona，青少年拿分级驾照前，必须持有学习驾照多久？","o":["1 个月","3 个月","1 年","6 个月"],"h1":"它是半年。","h2":"在 Arizona，青少年必须持有学习驾照至少 6 个月，才能拿分级驾照，这样有时间练习。","p":"对。持有学习驾照至少 6 个月。"},"vi":{"q":"Ở Arizona, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái theo cấp bậc?","o":["1 tháng","3 tháng","1 năm","6 tháng"],"h1":"Đó là nửa năm.","h2":"Ở Arizona, thiếu niên phải giữ giấy phép tập lái ít nhất 6 tháng trước khi lấy bằng lái theo cấp bậc, để có thời gian tập lái.","p":"Đúng. Giữ giấy phép tập lái ít nhất 6 tháng."},"tl":{"q":"Sa Arizona, gaano katagal dapat hawak ng tinedyer ang instruction permit bago makakuha ng graduated license?","o":["1 buwan","3 buwan","1 taon","6 na buwan"],"h1":"Kalahating taon ito.","h2":"Sa Arizona, dapat hawak ng tinedyer ang instruction permit nang hindi bababa sa 6 na buwan bago makakuha ng graduated license, para may oras mag-practice.","p":"Tama. Hawakan ang permit nang hindi bababa sa 6 na buwan."},"ar":{"q":"في Arizona، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل الحصول على الرخصة المتدرّجة؟","o":["شهر واحد","3 أشهر","سنة واحدة","6 أشهر"],"h1":"هي نصف سنة.","h2":"في Arizona، يجب أن يحمل المراهق تصريح التعلّم 6 أشهر على الأقل قبل الحصول على الرخصة المتدرّجة، حتى يكون عنده وقت للتدريب.","p":"صحيح. احمل التصريح 6 أشهر على الأقل."},"ref":{"doc":"AZ","page":11}},{"id":"az-005","scope":"AZ","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arizona, where must the licensed driver sit when a permit holder is driving?","o":["In the back seat behind the driver","In the seat beside the driver","Anywhere in the vehicle","In a second car close behind"],"h1":"The helper must be close enough to see the road and help right away.","h2":"The licensed driver must sit in the seat beside an Arizona permit holder, so they can watch the road and help at once.","p":"Right. The supervisor sits beside the permit driver."},"es":{"q":"En Arizona, ¿dónde debe sentarse el conductor con licencia cuando maneja alguien con permiso?","o":["En el asiento de atrás del conductor","En el asiento al lado del conductor","En cualquier lugar del vehículo","En otro carro que va justo detrás"],"h1":"El acompañante debe estar lo bastante cerca para ver la calle y ayudar enseguida.","h2":"El conductor con licencia debe ir sentado al lado de quien maneja con permiso en Arizona, para ver la calle y ayudar de inmediato.","p":"Correcto. El supervisor se sienta al lado del conductor con permiso."},"zh":{"q":"在 Arizona，学习驾照持有人开车时，有驾照的司机必须坐在哪里？","o":["坐在司机后面的后座","坐在司机旁边的座位","车里任何地方","坐在紧跟在后面的另一辆车里"],"h1":"帮忙的人必须离得够近，能看到路，并马上帮忙。","h2":"在 Arizona，有驾照的司机必须坐在学习驾照持有人旁边的座位，这样可以看着路并马上帮忙。","p":"对。监督人坐在学车司机旁边。"},"vi":{"q":"Ở Arizona, khi người có giấy phép tập lái đang lái xe, người có bằng lái phải ngồi ở đâu?","o":["Ở ghế sau, phía sau tài xế","Ở ghế bên cạnh tài xế","Ở bất kỳ chỗ nào trong xe","Trong một xe khác chạy sát phía sau"],"h1":"Người giúp phải ở đủ gần để nhìn thấy đường và giúp ngay.","h2":"Ở Arizona, người có bằng lái phải ngồi ở ghế bên cạnh người có giấy phép tập lái, để có thể nhìn đường và giúp ngay.","p":"Đúng. Người giám sát ngồi bên cạnh người tập lái."},"tl":{"q":"Sa Arizona, saan dapat umupo ang lisensiyadong driver kapag nagmamaneho ang may permit?","o":["Sa likurang upuan, sa likod ng driver","Sa upuan sa tabi ng driver","Kahit saan sa sasakyan","Sa ibang kotse na malapit sa likod"],"h1":"Dapat sapat na malapit ang tumutulong para makita ang daan at tumulong agad.","h2":"Sa Arizona, dapat umupo ang lisensiyadong driver sa upuan sa tabi ng may permit, para mabantayan ang daan at makatulong agad.","p":"Tama. Umuupo ang nagbabantay sa tabi ng driver na may permit."},"ar":{"q":"في Arizona، أين يجب أن يجلس السائق الذي لديه رخصة عندما يقود حامل التصريح؟","o":["في المقعد الخلفي وراء السائق","في المقعد بجانب السائق","في أي مكان في السيارة","في سيارة ثانية قريبة من الخلف"],"h1":"يجب أن يكون المساعد قريبًا بما يكفي ليرى الطريق ويساعد فورًا.","h2":"في Arizona، يجب أن يجلس السائق الذي لديه رخصة في المقعد بجانب حامل التصريح، حتى يراقب الطريق ويساعد فورًا.","p":"صحيح. المشرف يجلس بجانب سائق التصريح."},"ref":{"doc":"AZ","page":10}},{"id":"az-006","scope":"AZ","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arizona, during the first six months of a teen's graduated license, when may the teen NOT drive alone?","o":["From 10 p.m. to 6 a.m.","From 9 p.m. to 5 a.m.","From midnight to 5 a.m.","From 11 p.m. to 4 a.m."],"h1":"The limit starts at the very start of a new day.","h2":"For the first six months, an Arizona teen with a graduated license may not drive from midnight to 5 a.m. unless a parent or guardian is in the front seat, because late night driving is the most dangerous.","p":"Right. No driving from midnight to 5 a.m. at first."},"es":{"q":"En Arizona, durante los primeros seis meses de la licencia graduada, ¿en qué horario NO puede manejar solo el adolescente?","o":["De 10 p.m. a 6 a.m.","De 9 p.m. a 5 a.m.","De medianoche a 5 a.m.","De 11 p.m. a 4 a.m."],"h1":"El límite comienza justo al empezar un nuevo día.","h2":"Durante los primeros seis meses, un adolescente con licencia graduada en Arizona no puede manejar de medianoche a 5 a.m. a menos que vaya un padre o tutor en el asiento delantero, porque manejar tarde en la noche es lo más peligroso.","p":"Correcto. Al principio no se maneja de medianoche a 5 a.m."},"zh":{"q":"在 Arizona，青少年拿到分级驾照的前六个月，什么时间不可以独自开车？","o":["晚上 10 点到早上 6 点","晚上 9 点到早上 5 点","午夜 12 点到早上 5 点","晚上 11 点到早上 4 点"],"h1":"限制从新的一天刚开始时开始。","h2":"在 Arizona，青少年拿到分级驾照的前六个月，午夜 12 点到早上 5 点不可以开车，除非父母或监护人坐在前座，因为深夜开车最危险。","p":"对。一开始，午夜 12 点到早上 5 点不能开车。"},"vi":{"q":"Ở Arizona, trong sáu tháng đầu của bằng lái theo cấp bậc, khi nào thiếu niên KHÔNG được lái xe một mình?","o":["Từ 10 giờ tối đến 6 giờ sáng","Từ 9 giờ tối đến 5 giờ sáng","Từ nửa đêm đến 5 giờ sáng","Từ 11 giờ tối đến 4 giờ sáng"],"h1":"Giới hạn bắt đầu ngay lúc bắt đầu một ngày mới.","h2":"Ở Arizona, trong sáu tháng đầu, thiếu niên có bằng lái theo cấp bậc không được lái xe từ nửa đêm đến 5 giờ sáng, trừ khi cha mẹ hoặc người giám hộ ngồi ở ghế trước, vì lái xe khuya là nguy hiểm nhất.","p":"Đúng. Lúc đầu, không lái xe từ nửa đêm đến 5 giờ sáng."},"tl":{"q":"Sa Arizona, sa unang anim na buwan ng graduated license ng tinedyer, kailan HINDI siya puwedeng magmaneho nang mag-isa?","o":["Mula 10 p.m. hanggang 6 a.m.","Mula 9 p.m. hanggang 5 a.m.","Mula hatinggabi hanggang 5 a.m.","Mula 11 p.m. hanggang 4 a.m."],"h1":"Nagsisimula ang limitasyon sa pinakasimula ng bagong araw.","h2":"Sa unang anim na buwan, ang tinedyer sa Arizona na may graduated license ay hindi puwedeng magmaneho mula hatinggabi hanggang 5 a.m. maliban kung may magulang o guardian sa harapang upuan, dahil ang pagmamaneho sa hatinggabi ang pinakadelikado.","p":"Tama. Sa simula, bawal magmaneho mula hatinggabi hanggang 5 a.m."},"ar":{"q":"في Arizona، في الأشهر الستة الأولى من الرخصة المتدرّجة للمراهق، متى لا يجوز له أن يقود وحده؟","o":["من 10 مساءً إلى 6 صباحًا","من 9 مساءً إلى 5 صباحًا","من منتصف الليل إلى 5 صباحًا","من 11 مساءً إلى 4 صباحًا"],"h1":"يبدأ المنع في أول لحظة من يوم جديد.","h2":"في الأشهر الستة الأولى، لا يجوز للمراهق في Arizona الذي يحمل رخصة متدرّجة أن يقود من منتصف الليل إلى 5 صباحًا إلا إذا كان أحد والديه أو وليّ أمره في المقعد الأمامي، لأن القيادة في آخر الليل هي الأخطر.","p":"صحيح. في البداية، لا قيادة من منتصف الليل إلى 5 صباحًا."},"ref":{"doc":"AZ","page":11}},{"id":"az-007","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, a new teen driver wants to drive at 1 a.m. in the first six months. Who can make this legal by riding along?","o":["A licensed parent or guardian in the front seat","Any friend who is 18 or older","A younger brother or sister","Any passenger who has a permit"],"h1":"It must be an adult who is responsible for the teen.","h2":"In the first six months, an Arizona teen may drive between midnight and 5 a.m. when a licensed parent or guardian sits in the front passenger seat.","p":"Right. A licensed parent or guardian in front makes it legal."},"es":{"q":"En Arizona, un conductor adolescente nuevo quiere manejar a la 1 a.m. en los primeros seis meses. ¿Quién puede hacerlo legal si lo acompaña?","o":["Un padre o tutor con licencia en el asiento delantero","Cualquier amigo de 18 años o más","Un hermano o hermana menor","Cualquier pasajero que tenga permiso"],"h1":"Debe ser un adulto responsable del adolescente.","h2":"En los primeros seis meses, un adolescente en Arizona puede manejar entre medianoche y 5 a.m. si un padre o tutor con licencia va en el asiento delantero.","p":"Correcto. Un padre o tutor con licencia adelante lo hace legal."},"zh":{"q":"在 Arizona，一个新的青少年司机在前六个月想在凌晨 1 点开车。谁一起坐车可以让这样做合法？","o":["坐在前座、有驾照的父母或监护人","任何 18 岁或以上的朋友","弟弟或妹妹","任何有学习驾照的乘客"],"h1":"必须是对这个青少年负责的成年人。","h2":"在 Arizona，前六个月里，如果有驾照的父母或监护人坐在前排乘客座位，青少年可以在午夜 12 点到早上 5 点之间开车。","p":"对。有驾照的父母或监护人坐在前面，就合法。"},"vi":{"q":"Ở Arizona, một tài xế thiếu niên mới muốn lái xe lúc 1 giờ sáng trong sáu tháng đầu. Ai đi cùng thì việc này hợp pháp?","o":["Cha mẹ hoặc người giám hộ có bằng lái, ngồi ở ghế trước","Bất kỳ người bạn nào từ 18 tuổi trở lên","Một em trai hoặc em gái","Bất kỳ hành khách nào có giấy phép tập lái"],"h1":"Phải là một người lớn chịu trách nhiệm cho thiếu niên đó.","h2":"Ở Arizona, trong sáu tháng đầu, thiếu niên được lái xe từ nửa đêm đến 5 giờ sáng khi cha mẹ hoặc người giám hộ có bằng lái ngồi ở ghế hành khách phía trước.","p":"Đúng. Cha mẹ hoặc người giám hộ có bằng lái ngồi phía trước thì hợp pháp."},"tl":{"q":"Sa Arizona, gustong magmaneho ng bagong tinedyer na driver nang 1 a.m. sa unang anim na buwan. Sino ang puwedeng sumakay para maging legal ito?","o":["Lisensiyadong magulang o guardian sa harapang upuan","Kahit sinong kaibigan na 18 o mas matanda","Nakababatang kapatid","Kahit sinong pasahero na may permit"],"h1":"Dapat ito ay adult na responsable sa tinedyer.","h2":"Sa unang anim na buwan, puwedeng magmaneho ang tinedyer sa Arizona mula hatinggabi hanggang 5 a.m. kapag nakaupo sa harapang upuan ng pasahero ang lisensiyadong magulang o guardian.","p":"Tama. Legal ito kapag may lisensiyadong magulang o guardian sa harap."},"ar":{"q":"في Arizona، سائق مراهق جديد يريد أن يقود في الساعة 1 صباحًا في الأشهر الستة الأولى. من يجعل هذا قانونيًا إذا ركب معه؟","o":["أحد الوالدين أو وليّ الأمر الذي لديه رخصة، في المقعد الأمامي","أي صديق عمره 18 سنة أو أكثر","أخ أو أخت أصغر","أي راكب لديه تصريح تعلّم"],"h1":"يجب أن يكون شخصًا بالغًا مسؤولًا عن المراهق.","h2":"في الأشهر الستة الأولى، يجوز للمراهق في Arizona أن يقود بين منتصف الليل و5 صباحًا عندما يجلس أحد والديه أو وليّ أمره الذي لديه رخصة في مقعد الراكب الأمامي.","p":"صحيح. أحد الوالدين أو وليّ الأمر الذي لديه رخصة في الأمام يجعل ذلك قانونيًا."},"ref":{"doc":"AZ","page":11}},{"id":"az-008","scope":"AZ","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arizona, in the first six months of a graduated license, how many passengers under 18 may a teen carry, not counting brothers and sisters?","o":["None at all","Two","Three","One"],"h1":"It is the smallest number above zero.","h2":"In the first six months, an Arizona teen driver may carry only one passenger under 18 who is not a brother or sister, because friends in the car are a big distraction.","p":"Right. Only one passenger under 18 at first."},"es":{"q":"En Arizona, en los primeros seis meses de la licencia graduada, ¿cuántos pasajeros menores de 18 puede llevar un adolescente, sin contar a sus hermanos?","o":["Ninguno","Dos","Tres","Uno"],"h1":"Es el número más pequeño mayor que cero.","h2":"En los primeros seis meses, un conductor adolescente en Arizona puede llevar solo un pasajero menor de 18 que no sea su hermano o hermana, porque los amigos en el carro distraen mucho.","p":"Correcto. Al principio solo un pasajero menor de 18."},"zh":{"q":"在 Arizona，分级驾照的前六个月，不算兄弟姐妹，青少年可以载几个 18 岁以下的乘客？","o":["一个也不行","两个","三个","一个"],"h1":"它是比零大的最小数字。","h2":"在 Arizona，前六个月里，青少年司机只可以载一个不是兄弟姐妹的 18 岁以下乘客，因为车里有朋友会很分心。","p":"对。一开始只可以载一个 18 岁以下的乘客。"},"vi":{"q":"Ở Arizona, trong sáu tháng đầu của bằng lái theo cấp bậc, thiếu niên được chở bao nhiêu hành khách dưới 18 tuổi, không tính anh chị em ruột?","o":["Không ai cả","Hai","Ba","Một"],"h1":"Đó là số nhỏ nhất lớn hơn không.","h2":"Ở Arizona, trong sáu tháng đầu, tài xế thiếu niên chỉ được chở một hành khách dưới 18 tuổi không phải anh chị em ruột, vì bạn bè trong xe làm mất tập trung rất nhiều.","p":"Đúng. Lúc đầu chỉ được chở một hành khách dưới 18 tuổi."},"tl":{"q":"Sa Arizona, sa unang anim na buwan ng graduated license, ilang pasahero na wala pang 18 ang puwedeng isakay ng tinedyer, hindi kasama ang mga kapatid?","o":["Wala talaga","Dalawa","Tatlo","Isa"],"h1":"Ito ang pinakamaliit na numero na higit sa zero.","h2":"Sa unang anim na buwan, ang tinedyer na driver sa Arizona ay puwedeng magsakay ng isang pasahero lang na wala pang 18 na hindi niya kapatid, dahil malaking abala ang mga kaibigan sa kotse.","p":"Tama. Isang pasahero lang na wala pang 18 sa simula."},"ar":{"q":"في Arizona، في الأشهر الستة الأولى من الرخصة المتدرّجة، كم راكبًا عمره أقل من 18 سنة يجوز للمراهق أن ينقل، من غير حساب الإخوة والأخوات؟","o":["ولا أحد","اثنان","ثلاثة","واحد"],"h1":"هو أصغر رقم أكبر من الصفر.","h2":"في الأشهر الستة الأولى، يجوز للسائق المراهق في Arizona أن ينقل راكبًا واحدًا فقط عمره أقل من 18 سنة وليس أخًا أو أختًا، لأن الأصدقاء في السيارة يشتّتون الانتباه كثيرًا.","p":"صحيح. في البداية راكب واحد فقط عمره أقل من 18."},"ref":{"doc":"AZ","page":11}},{"id":"az-009","scope":"AZ","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arizona, how many questions are on the regular written test for a driver license?","o":["20 questions","30 questions","40 questions","50 questions"],"h1":"It is the same number as the supervised practice hours.","h2":"The Arizona written test for a regular license has 30 multiple choice questions about signs, laws and safe driving.","p":"Right. The Arizona written test has 30 questions."},"es":{"q":"En Arizona, ¿cuántas preguntas tiene el examen escrito normal para la licencia de manejo?","o":["20 preguntas","30 preguntas","40 preguntas","50 preguntas"],"h1":"Es el mismo número que las horas de práctica supervisada.","h2":"El examen escrito de Arizona para la licencia normal tiene 30 preguntas de opción múltiple sobre señales, leyes y manejo seguro.","p":"Correcto. El examen escrito de Arizona tiene 30 preguntas."},"zh":{"q":"在 Arizona，普通驾照的笔试有多少道题？","o":["20 道题","30 道题","40 道题","50 道题"],"h1":"它和有人监督练车的小时数一样。","h2":"Arizona 普通驾照的笔试有 30 道选择题，内容是标志、法律和安全驾驶。","p":"对。Arizona 的笔试有 30 道题。"},"vi":{"q":"Ở Arizona, bài thi viết cho bằng lái thông thường có bao nhiêu câu hỏi?","o":["20 câu","30 câu","40 câu","50 câu"],"h1":"Bằng với số giờ tập lái có giám sát.","h2":"Bài thi viết ở Arizona cho bằng lái thông thường có 30 câu hỏi trắc nghiệm về biển báo, luật và lái xe an toàn.","p":"Đúng. Bài thi viết ở Arizona có 30 câu hỏi."},"tl":{"q":"Sa Arizona, ilang tanong ang nasa regular na written test para sa driver license?","o":["20 tanong","30 tanong","40 tanong","50 tanong"],"h1":"Pareho ito ng bilang ng oras ng practice na may nagbabantay.","h2":"Ang written test sa Arizona para sa regular na lisensiya ay may 30 multiple choice na tanong tungkol sa mga karatula, batas at ligtas na pagmamaneho.","p":"Tama. May 30 tanong ang written test sa Arizona."},"ar":{"q":"في Arizona، كم سؤالًا في الاختبار الكتابي العادي لرخصة القيادة؟","o":["20 سؤالًا","30 سؤالًا","40 سؤالًا","50 سؤالًا"],"h1":"هو نفس عدد ساعات التدريب تحت إشراف.","h2":"الاختبار الكتابي في Arizona للرخصة العادية فيه 30 سؤال اختيار من متعدّد عن الإشارات والقوانين والقيادة الآمنة.","p":"صحيح. الاختبار الكتابي في Arizona فيه 30 سؤالًا."},"ref":{"doc":"AZ","page":null}},{"id":"az-010","scope":"AZ","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arizona, what score do you need to pass the written knowledge test?","o":["60 percent","70 percent","80 percent","90 percent"],"h1":"You must get four out of every five questions right.","h2":"You need at least 80 percent correct to pass the Arizona knowledge test, which is 24 of the 30 questions.","p":"Right. You need 80 percent to pass."},"es":{"q":"En Arizona, ¿qué puntaje necesita para aprobar el examen escrito de conocimientos?","o":["60 por ciento","70 por ciento","80 por ciento","90 por ciento"],"h1":"Debe contestar bien cuatro de cada cinco preguntas.","h2":"Usted necesita por lo menos 80 por ciento de respuestas correctas para aprobar el examen de Arizona, es decir 24 de las 30 preguntas.","p":"Correcto. Necesita 80 por ciento para aprobar."},"zh":{"q":"在 Arizona，笔试（知识考试）要考多少分才能通过？","o":["60%","70%","80%","90%"],"h1":"每五道题你必须答对四道。","h2":"在 Arizona，知识考试你至少要答对 80% 才能通过，也就是 30 道题答对 24 道。","p":"对。你需要 80% 才能通过。"},"vi":{"q":"Ở Arizona, bạn cần bao nhiêu điểm để đậu bài thi kiến thức viết?","o":["60 phần trăm","70 phần trăm","80 phần trăm","90 phần trăm"],"h1":"Bạn phải trả lời đúng bốn trong mỗi năm câu.","h2":"Bạn cần trả lời đúng ít nhất 80 phần trăm để đậu bài thi kiến thức ở Arizona, tức là 24 trong 30 câu.","p":"Đúng. Bạn cần 80 phần trăm để đậu."},"tl":{"q":"Sa Arizona, anong score ang kailangan para pumasa sa written knowledge test?","o":["60 porsiyento","70 porsiyento","80 porsiyento","90 porsiyento"],"h1":"Dapat tama ang apat sa bawat limang tanong.","h2":"Kailangan mo ng hindi bababa sa 80 porsiyentong tama para pumasa sa knowledge test sa Arizona, ibig sabihin 24 sa 30 tanong.","p":"Tama. Kailangan mo ng 80 porsiyento para pumasa."},"ar":{"q":"في Arizona، ما الدرجة التي تحتاجها لتنجح في الاختبار الكتابي للمعرفة؟","o":["60 بالمئة","70 بالمئة","80 بالمئة","90 بالمئة"],"h1":"يجب أن تجيب بشكل صحيح عن أربعة من كل خمسة أسئلة.","h2":"تحتاج إلى 80 بالمئة إجابات صحيحة على الأقل لتنجح في اختبار المعرفة في Arizona، أي 24 من 30 سؤالًا.","p":"صحيح. تحتاج إلى 80 بالمئة لتنجح."},"ref":{"doc":"AZ","page":null}},{"id":"az-012","scope":"AZ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arizona, may a driver with an instruction permit use a cell phone while driving?","o":["Yes, if it is in hands-free mode","No, only in an emergency where stopping is not possible","Yes, but only to read a map","Yes, when stopped at a red light"],"h1":"Permit drivers have a stricter rule than adult drivers.","h2":"An Arizona permit holder may not use a phone or other wireless device while driving, even hands-free, except in a real emergency, so that all attention stays on learning to drive.","p":"Right. Permit drivers may not use a phone except in an emergency."},"es":{"q":"En Arizona, ¿puede un conductor con permiso de aprendizaje usar el celular mientras maneja?","o":["Sí, si está en modo manos libres","No, solo en una emergencia donde no se puede parar","Sí, pero solo para leer un mapa","Sí, cuando está detenido en un semáforo en rojo"],"h1":"Los conductores con permiso tienen una regla más estricta que los adultos.","h2":"Quien tiene permiso de aprendizaje en Arizona no puede usar el celular ni otro aparato inalámbrico mientras maneja, ni siquiera con manos libres, salvo en una emergencia real, para que toda su atención esté en aprender a manejar.","p":"Correcto. Con permiso no se usa el celular, salvo en una emergencia."},"zh":{"q":"在 Arizona，持有学习驾照的司机开车时可以用手机吗？","o":["可以，如果是免提模式","不可以，只有在无法停车的紧急情况下才可以","可以，但只能看地图","可以，在红灯停车时"],"h1":"学车司机的规定比成年司机更严。","h2":"在 Arizona，学习驾照持有人开车时不可以用手机或其他无线设备，免提也不行，只有真正的紧急情况除外，这样注意力可以全部放在学开车上。","p":"对。学车司机除了紧急情况，不可以用手机。"},"vi":{"q":"Ở Arizona, tài xế có giấy phép tập lái có được dùng điện thoại di động khi lái xe không?","o":["Được, nếu dùng chế độ rảnh tay","Không, chỉ được dùng trong trường hợp khẩn cấp mà không thể dừng xe","Được, nhưng chỉ để xem bản đồ","Được, khi dừng ở đèn đỏ"],"h1":"Người tập lái có quy định nghiêm hơn tài xế người lớn.","h2":"Ở Arizona, người có giấy phép tập lái không được dùng điện thoại hay thiết bị không dây khác khi lái xe, kể cả rảnh tay, trừ khi thật sự khẩn cấp, để toàn bộ sự chú ý dành cho việc học lái xe.","p":"Đúng. Người tập lái không được dùng điện thoại, trừ khi khẩn cấp."},"tl":{"q":"Sa Arizona, puwede bang gumamit ng cell phone habang nagmamaneho ang driver na may instruction permit?","o":["Oo, kung naka-hands-free mode","Hindi, maliban sa emergency na hindi posibleng huminto","Oo, pero para lang tumingin ng mapa","Oo, kapag nakahinto sa red light"],"h1":"Mas mahigpit ang patakaran para sa may permit kaysa sa adult na driver.","h2":"Sa Arizona, ang may permit ay hindi puwedeng gumamit ng phone o ibang wireless device habang nagmamaneho, kahit hands-free, maliban sa totoong emergency, para buong atensiyon ay nasa pag-aaral magmaneho.","p":"Tama. Bawal sa may permit ang phone maliban sa emergency."},"ar":{"q":"في Arizona، هل يجوز للسائق الذي يحمل تصريح تعلّم أن يستعمل الهاتف المحمول أثناء القيادة؟","o":["نعم، إذا كان بوضع عدم استخدام اليدين","لا، إلا في حالة طارئة لا يمكن فيها التوقّف","نعم، لكن فقط لقراءة الخريطة","نعم، عند التوقّف عند الإشارة الحمراء"],"h1":"سائقو التصريح عليهم قاعدة أشدّ من السائقين البالغين.","h2":"في Arizona، لا يجوز لحامل التصريح أن يستعمل الهاتف أو أي جهاز لاسلكي آخر أثناء القيادة، حتى بدون استخدام اليدين، إلا في حالة طارئة حقيقية، حتى يبقى كل الانتباه على تعلّم القيادة.","p":"صحيح. سائقو التصريح لا يستعملون الهاتف إلا في حالة طارئة."},"ref":{"doc":"AZ","page":null}},{"id":"az-013","scope":"AZ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arizona, how may an adult driver with a full license use a cell phone while driving?","o":["Holding it in one hand","Resting it on the lap","Holding it with the shoulder","Only in hands-free mode"],"h1":"Your hands and body may not hold the phone.","h2":"Arizona's hands-free law lets drivers use a phone only in hands-free mode; you may not hold or support it with any part of your body.","p":"Right. In Arizona the phone must be hands-free."},"es":{"q":"En Arizona, ¿cómo puede un conductor adulto con licencia usar el celular mientras maneja?","o":["Sosteniéndolo con una mano","Apoyándolo en las piernas","Sosteniéndolo con el hombro","Solo en modo manos libres"],"h1":"Ni sus manos ni su cuerpo pueden sostener el teléfono.","h2":"La ley de manos libres de Arizona permite usar el teléfono solo en modo manos libres; usted no puede sostenerlo ni apoyarlo con ninguna parte del cuerpo.","p":"Correcto. En Arizona el teléfono debe ir en manos libres."},"zh":{"q":"在 Arizona，有正式驾照的成年司机开车时可以怎样用手机？","o":["用一只手拿着","放在大腿上","用肩膀夹着","只能用免提模式"],"h1":"你的手和身体都不可以拿着手机。","h2":"Arizona 的免提法律（hands-free law）规定，司机只能用免提模式用手机；你不可以用身体任何部位拿着或托着手机。","p":"对。在 Arizona，手机必须免提。"},"vi":{"q":"Ở Arizona, tài xế người lớn có bằng lái đầy đủ được dùng điện thoại di động khi lái xe như thế nào?","o":["Cầm bằng một tay","Để trên đùi","Kẹp bằng vai","Chỉ ở chế độ rảnh tay"],"h1":"Tay và cơ thể bạn không được giữ điện thoại.","h2":"Luật rảnh tay (hands-free law) của Arizona chỉ cho phép tài xế dùng điện thoại ở chế độ rảnh tay; bạn không được cầm hay đỡ điện thoại bằng bất kỳ bộ phận nào của cơ thể.","p":"Đúng. Ở Arizona, điện thoại phải ở chế độ rảnh tay."},"tl":{"q":"Sa Arizona, paano puwedeng gumamit ng cell phone habang nagmamaneho ang adult na driver na may buong lisensiya?","o":["Hawak sa isang kamay","Nakapatong sa hita","Ipit ng balikat","Sa hands-free mode lang"],"h1":"Hindi puwedeng hawakan ng kamay o katawan mo ang phone.","h2":"Ayon sa hands-free law ng Arizona, puwedeng gumamit ng phone ang driver sa hands-free mode lang; hindi mo ito puwedeng hawakan o suportahan ng anumang bahagi ng katawan.","p":"Tama. Sa Arizona, dapat hands-free ang phone."},"ar":{"q":"في Arizona، كيف يجوز للسائق البالغ الذي لديه رخصة كاملة أن يستعمل الهاتف المحمول أثناء القيادة؟","o":["يمسكه بيد واحدة","يضعه على حضنه","يمسكه بكتفه","فقط بوضع عدم استخدام اليدين"],"h1":"لا يجوز أن تمسك الهاتف بيديك أو بجسمك.","h2":"قانون عدم استخدام اليدين في Arizona (hands-free law) يسمح للسائقين باستعمال الهاتف فقط بوضع عدم استخدام اليدين؛ لا يجوز أن تمسكه أو تسنده بأي جزء من جسمك.","p":"صحيح. في Arizona يجب أن يكون الهاتف بدون استخدام اليدين."},"ref":{"doc":"AZ","page":20}},{"id":"az-014","scope":"AZ","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Arizona, you see a stopped tow truck on the shoulder with flashing lights. There are two lanes your way. What should you do?","o":["Keep your lane and speed","Stop behind the tow truck","Move to the lane not next to it, if safe","Honk and pass quickly"],"h1":"Give the people on the shoulder more room.","h2":"Arizona's move over law says to move into a lane that is not next to a stopped vehicle with flashing lights when you can do it safely, to protect people working by the road.","p":"Right. Move over to a lane that is not next to it."},"es":{"q":"En Arizona, ve una grúa detenida en el acotamiento con luces intermitentes. Hay dos carriles en su dirección. ¿Qué debe hacer?","o":["Seguir en su carril y a la misma velocidad","Detenerse detrás de la grúa","Cambiarse al carril que no está junto a ella, si es seguro","Tocar el claxon y pasar rápido"],"h1":"Deles más espacio a las personas en el acotamiento.","h2":"La ley de Arizona de cambiarse de carril dice que debe pasar a un carril que no esté junto al vehículo detenido con luces intermitentes, cuando sea seguro, para proteger a quienes trabajan junto a la vía.","p":"Correcto. Cámbiese a un carril que no esté junto a ella."},"zh":{"q":"在 Arizona，你看到路肩上停着一辆闪灯的拖车。你这个方向有两条车道。你应该怎么做？","o":["保持车道和速度","停在拖车后面","如果安全，换到不挨着它的车道","按喇叭，快速开过去"],"h1":"给路肩上的人更多空间。","h2":"Arizona 的让道法（move over law）规定，如果安全，要换到不挨着闪灯停车的车道，以保护在路边工作的人。","p":"对。换到不挨着它的车道。"},"vi":{"q":"Ở Arizona, bạn thấy một xe kéo đang dừng trên lề đường, có đèn nhấp nháy. Chiều của bạn có hai làn xe. Bạn nên làm gì?","o":["Giữ làn và tốc độ","Dừng phía sau xe kéo","Chuyển sang làn không sát bên nó, nếu an toàn","Bấm còi và chạy qua nhanh"],"h1":"Chừa thêm chỗ cho những người trên lề đường.","h2":"Luật nhường làn (move over law) của Arizona nói phải chuyển sang làn không sát bên xe đang dừng có đèn nhấp nháy khi làm được một cách an toàn, để bảo vệ những người làm việc bên đường.","p":"Đúng. Chuyển sang làn không sát bên nó."},"tl":{"q":"Sa Arizona, may nakita kang nakahintong tow truck sa gilid ng daan (shoulder) na may kumikislap na ilaw. May dalawang lane sa direksiyon mo. Ano ang dapat mong gawin?","o":["Manatili sa lane mo at sa bilis mo","Huminto sa likod ng tow truck","Lumipat sa lane na hindi katabi nito, kung ligtas","Bumusina at lumampas nang mabilis"],"h1":"Bigyan ng mas malaking espasyo ang mga tao sa gilid ng daan.","h2":"Sinasabi ng move over law ng Arizona na lumipat sa lane na hindi katabi ng nakahintong sasakyan na may kumikislap na ilaw kapag ligtas itong gawin, para protektahan ang mga taong nagtatrabaho sa tabi ng daan.","p":"Tama. Lumipat sa lane na hindi katabi nito."},"ar":{"q":"في Arizona، ترى شاحنة سحب متوقّفة على كتف الطريق وأضواؤها تومض. في اتجاهك مساران. ماذا يجب أن تفعل؟","o":["ابقَ في مسارك وبنفس سرعتك","توقّف خلف شاحنة السحب","انتقل إلى المسار غير المجاور لها، إذا كان ذلك آمنًا","اضغط على الزمور وتجاوز بسرعة"],"h1":"أعطِ الناس على كتف الطريق مساحة أكبر.","h2":"قانون الابتعاد في Arizona (move over law) يقول أن تنتقل إلى مسار غير مجاور للمركبة المتوقّفة التي أضواؤها تومض عندما تستطيع ذلك بأمان، لحماية الناس الذين يعملون بجانب الطريق.","p":"صحيح. انتقل إلى مسار غير مجاور لها."},"ref":{"doc":"AZ","page":31}},{"id":"az-015","scope":"AZ","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Arizona, you cannot safely change lanes away from a stopped vehicle with flashing lights. What must you do?","o":["Slow down and pass with caution","Keep going at the speed limit","Stop in your lane until it leaves","Drive on the shoulder to pass"],"h1":"If you cannot give more space, give more time.","h2":"When you cannot safely move over in Arizona, you must slow down and pass with care, so you have time to react if someone steps into the road.","p":"Right. If you cannot move over, slow down."},"es":{"q":"En Arizona, no puede cambiarse de carril con seguridad para alejarse de un vehículo detenido con luces intermitentes. ¿Qué debe hacer?","o":["Bajar la velocidad y pasar con cuidado","Seguir al límite de velocidad","Parar en su carril hasta que se vaya","Manejar por el acotamiento para pasar"],"h1":"Si no puede dar más espacio, dé más tiempo.","h2":"Cuando no puede cambiarse de carril con seguridad en Arizona, debe bajar la velocidad y pasar con cuidado, para tener tiempo de reaccionar si alguien entra a la vía.","p":"Correcto. Si no puede cambiarse, baje la velocidad."},"zh":{"q":"在 Arizona，你无法安全地换道离开一辆闪灯的停着的车。你必须怎么做？","o":["减速，小心开过去","按限速继续开","在你的车道停下，直到它离开","开上路肩超过去"],"h1":"如果不能给更多空间，就给更多时间。","h2":"在 Arizona，如果你不能安全地换道，就必须减速并小心开过去，这样如果有人走到路上，你有时间反应。","p":"对。如果不能换道，就减速。"},"vi":{"q":"Ở Arizona, bạn không thể đổi làn một cách an toàn để tránh xa một xe đang dừng có đèn nhấp nháy. Bạn phải làm gì?","o":["Giảm tốc độ và chạy qua cẩn thận","Tiếp tục chạy bằng tốc độ giới hạn","Dừng trong làn của bạn cho đến khi nó đi","Chạy trên lề đường để vượt qua"],"h1":"Nếu không thể chừa thêm chỗ, hãy cho thêm thời gian.","h2":"Ở Arizona, khi không thể chuyển làn an toàn, bạn phải giảm tốc độ và chạy qua cẩn thận, để có thời gian phản ứng nếu có người bước ra đường.","p":"Đúng. Nếu không thể chuyển làn, hãy giảm tốc độ."},"tl":{"q":"Sa Arizona, hindi ka ligtas na makakalipat ng lane palayo sa nakahintong sasakyan na may kumikislap na ilaw. Ano ang dapat mong gawin?","o":["Bumagal at lumampas nang maingat","Tuloy lang sa speed limit","Huminto sa lane mo hanggang umalis ito","Magmaneho sa shoulder para lumampas"],"h1":"Kung hindi ka makapagbigay ng mas malaking espasyo, magbigay ng mas mahabang oras.","h2":"Sa Arizona, kapag hindi ka ligtas na makakalipat ng lane, dapat kang bumagal at lumampas nang maingat, para may oras kang kumilos kung may taong pumasok sa daan.","p":"Tama. Kung hindi ka makalipat, bumagal."},"ar":{"q":"في Arizona، لا تستطيع أن تغيّر المسار بأمان بعيدًا عن مركبة متوقّفة أضواؤها تومض. ماذا يجب أن تفعل؟","o":["خفّف السرعة وتجاوز بحذر","استمر بالسرعة القصوى المسموحة","توقّف في مسارك حتى تذهب","قُد على كتف الطريق لتتجاوز"],"h1":"إذا لم تستطع أن تعطي مساحة أكبر، فأعطِ وقتًا أكثر.","h2":"عندما لا تستطيع أن تبتعد بأمان في Arizona، يجب أن تخفّف السرعة وتتجاوز بحذر، حتى يكون عندك وقت للتصرّف إذا دخل شخص إلى الطريق.","p":"صحيح. إذا لم تستطع أن تبتعد، خفّف السرعة."},"ref":{"doc":"AZ","page":31}},{"id":"az-016","scope":"AZ","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Arizona, which stopped vehicles does the move over law cover?","o":["Only police cars","Only ambulances and fire trucks","Only road work trucks","Any stopped vehicle with flashing lights"],"h1":"Since 2011 the law covers stranded drivers too.","h2":"Arizona's move over law covers any stationary vehicle with its flashing lights on, including a stranded driver on the shoulder, not just emergency vehicles.","p":"Right. It covers any stopped vehicle with flashing lights."},"es":{"q":"En Arizona, ¿a qué vehículos detenidos se aplica la ley de cambiarse de carril?","o":["Solo a patrullas de policía","Solo a ambulancias y bomberos","Solo a camiones de obras viales","A cualquier vehículo detenido con luces intermitentes"],"h1":"Desde 2011 la ley también protege a conductores varados.","h2":"La ley de Arizona se aplica a cualquier vehículo detenido con las luces intermitentes encendidas, incluido un conductor varado en el acotamiento, no solo a vehículos de emergencia.","p":"Correcto. Se aplica a cualquier vehículo detenido con luces intermitentes."},"zh":{"q":"在 Arizona，让道法（move over law）适用于哪些停着的车？","o":["只有警车","只有救护车和消防车","只有道路施工车","任何闪灯的停着的车"],"h1":"从 2011 年起，这个法律也包括车坏在路边的司机。","h2":"Arizona 的让道法适用于任何开着闪灯停着的车，包括车坏在路肩的司机，不只是紧急车辆。","p":"对。它适用于任何闪灯的停着的车。"},"vi":{"q":"Ở Arizona, luật nhường làn (move over law) áp dụng cho những xe đang dừng nào?","o":["Chỉ xe cảnh sát","Chỉ xe cứu thương và xe cứu hỏa","Chỉ xe làm đường","Bất kỳ xe đang dừng nào có đèn nhấp nháy"],"h1":"Từ năm 2011, luật này cũng áp dụng cho tài xế bị kẹt bên đường.","h2":"Luật nhường làn của Arizona áp dụng cho bất kỳ xe đang đứng yên nào bật đèn nhấp nháy, kể cả tài xế bị kẹt trên lề đường, không chỉ xe khẩn cấp.","p":"Đúng. Luật áp dụng cho bất kỳ xe đang dừng nào có đèn nhấp nháy."},"tl":{"q":"Sa Arizona, aling mga nakahintong sasakyan ang sakop ng move over law?","o":["Mga kotse ng pulis lang","Mga ambulansiya at fire truck lang","Mga truck ng road work lang","Anumang nakahintong sasakyan na may kumikislap na ilaw"],"h1":"Mula 2011, sakop na rin ng batas ang mga driver na na-stranded.","h2":"Sakop ng move over law ng Arizona ang anumang nakahintong sasakyan na nakabukas ang kumikislap na ilaw, kasama ang driver na na-stranded sa shoulder, hindi lang mga emergency vehicle.","p":"Tama. Sakop nito ang anumang nakahintong sasakyan na may kumikislap na ilaw."},"ar":{"q":"في Arizona، ما المركبات المتوقّفة التي يشملها قانون الابتعاد (move over law)؟","o":["سيارات الشرطة فقط","سيارات الإسعاف والإطفاء فقط","شاحنات أعمال الطرق فقط","أي مركبة متوقّفة أضواؤها تومض"],"h1":"منذ سنة 2011 يشمل القانون أيضًا السائقين العالقين.","h2":"قانون الابتعاد في Arizona يشمل أي مركبة متوقّفة أضواؤها الوامضة مشغّلة، ومنها سائق عالق على كتف الطريق، وليس مركبات الطوارئ فقط.","p":"صحيح. يشمل أي مركبة متوقّفة أضواؤها تومض."},"ref":{"doc":"AZ","page":31}},{"id":"az-017","scope":"AZ","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Arizona, unless a sign says otherwise, what is the speed limit when approaching a school crossing?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"It is the slowest limit set by state law.","h2":"Arizona law sets 15 mph when approaching a school crossing, because children may step into the street at any moment.","p":"Right. Approaching a school crossing, the limit is 15 mph."},"es":{"q":"En Arizona, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad al acercarse a un cruce escolar?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Es el límite más bajo que fija la ley estatal.","h2":"La ley de Arizona fija 15 mph al acercarse a un cruce escolar, porque los niños pueden entrar a la calle en cualquier momento.","p":"Correcto. Al acercarse a un cruce escolar, el límite es 15 mph."},"zh":{"q":"在 Arizona，除非标志另有规定，接近学校人行横道时限速是多少？","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"它是州法律规定的最低限速。","h2":"Arizona 法律规定，接近学校人行横道时限速 15 mph，因为孩子随时可能走到街上。","p":"对。接近学校人行横道，限速 15 mph。"},"vi":{"q":"Ở Arizona, trừ khi có biển báo khác, tốc độ giới hạn khi đến gần chỗ băng qua đường của trường học là bao nhiêu?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Đó là giới hạn chậm nhất do luật tiểu bang đặt ra.","h2":"Luật Arizona đặt giới hạn 15 mph khi đến gần chỗ băng qua đường của trường học, vì trẻ em có thể bước ra đường bất cứ lúc nào.","p":"Đúng. Khi đến gần chỗ băng qua đường của trường học, giới hạn là 15 mph."},"tl":{"q":"Sa Arizona, maliban kung iba ang sabi ng karatula, ano ang speed limit kapag papalapit sa tawiran ng paaralan (school crossing)?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Ito ang pinakamabagal na limit na itinakda ng batas ng estado.","h2":"Itinakda ng batas ng Arizona ang 15 mph kapag papalapit sa tawiran ng paaralan, dahil puwedeng lumabas ang mga bata sa kalye anumang oras.","p":"Tama. Papalapit sa tawiran ng paaralan, 15 mph ang limit."},"ar":{"q":"في Arizona، إلا إذا قالت لافتة غير ذلك، ما حدّ السرعة عند الاقتراب من معبر مدرسة؟","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"هو أبطأ حدّ يضعه قانون الولاية.","h2":"قانون Arizona يضع 15 mph عند الاقتراب من معبر مدرسة، لأن الأطفال قد يدخلون الشارع في أي لحظة.","p":"صحيح. عند الاقتراب من معبر مدرسة، الحدّ 15 mph."},"ref":{"doc":"AZ","page":32}},{"id":"az-018","scope":"AZ","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Arizona, unless a sign says otherwise, what is the speed limit in a business or residential district?","o":["15 mph","20 mph","25 mph","35 mph"],"h1":"It is ten more than the school crossing limit.","h2":"Arizona law sets 25 mph in business and residential districts when no other limit is posted, because people, driveways and parked cars are close to the road.","p":"Right. Business and residential districts are 25 mph."},"es":{"q":"En Arizona, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad en una zona comercial o residencial?","o":["15 mph","20 mph","25 mph","35 mph"],"h1":"Es diez más que el límite del cruce escolar.","h2":"La ley de Arizona fija 25 mph en zonas comerciales y residenciales cuando no hay otro límite indicado, porque hay personas, entradas de garaje y carros estacionados cerca de la calle.","p":"Correcto. En zonas comerciales y residenciales el límite es 25 mph."},"zh":{"q":"在 Arizona，除非标志另有规定，商业区或住宅区的限速是多少？","o":["15 mph","20 mph","25 mph","35 mph"],"h1":"它比学校人行横道的限速多 10。","h2":"Arizona 法律规定，没有其他限速标志时，商业区和住宅区限速 25 mph，因为行人、车道出入口和停着的车都离路很近。","p":"对。商业区和住宅区限速 25 mph。"},"vi":{"q":"Ở Arizona, trừ khi có biển báo khác, tốc độ giới hạn trong khu thương mại hoặc khu dân cư là bao nhiêu?","o":["15 mph","20 mph","25 mph","35 mph"],"h1":"Nhiều hơn giới hạn ở chỗ băng qua đường của trường học 10.","h2":"Luật Arizona đặt giới hạn 25 mph trong khu thương mại và khu dân cư khi không có biển báo giới hạn khác, vì người đi bộ, lối xe ra vào và xe đậu ở gần đường.","p":"Đúng. Khu thương mại và khu dân cư là 25 mph."},"tl":{"q":"Sa Arizona, maliban kung iba ang sabi ng karatula, ano ang speed limit sa business o residential district?","o":["15 mph","20 mph","25 mph","35 mph"],"h1":"Sampu itong mas mataas kaysa sa limit sa tawiran ng paaralan.","h2":"Itinakda ng batas ng Arizona ang 25 mph sa business at residential district kapag walang ibang nakapaskil na limit, dahil malapit sa daan ang mga tao, driveway at nakaparadang kotse.","p":"Tama. 25 mph sa business at residential district."},"ar":{"q":"في Arizona، إلا إذا قالت لافتة غير ذلك، ما حدّ السرعة في منطقة تجارية أو سكنية؟","o":["15 mph","20 mph","25 mph","35 mph"],"h1":"هو أكثر بعشرة من حدّ معبر المدرسة.","h2":"قانون Arizona يضع 25 mph في المناطق التجارية والسكنية عندما لا توجد لافتة بحدّ آخر، لأن الناس ومداخل البيوت والسيارات المتوقّفة قريبة من الطريق.","p":"صحيح. المناطق التجارية والسكنية 25 mph."},"ref":{"doc":"AZ","page":32}},{"id":"az-019","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, what can happen if you get 8 or more points on your record in 12 months?","o":["You may have to attend Traffic Survival School or lose your license","Nothing, points only matter after 5 years","You must buy a new vehicle registration","You must retake only the vision test"],"h1":"Points add up, and the state steps in at 8.","h2":"If you collect 8 or more points within 12 months in Arizona, the MVD can order Traffic Survival School or suspend your license.","p":"Right. 8 points in 12 months can mean Traffic Survival School or suspension."},"es":{"q":"En Arizona, ¿qué puede pasar si acumula 8 puntos o más en su historial en 12 meses?","o":["Puede tener que ir a la Escuela de Supervivencia de Tráfico o perder la licencia","Nada, los puntos solo cuentan después de 5 años","Debe comprar un registro nuevo para el vehículo","Debe repetir solo el examen de la vista"],"h1":"Los puntos se suman y el estado actúa al llegar a 8.","h2":"Si acumula 8 puntos o más en 12 meses en Arizona, la MVD puede ordenarle la Escuela de Supervivencia de Tráfico o suspender su licencia.","p":"Correcto. 8 puntos en 12 meses pueden significar escuela de tráfico o suspensión."},"zh":{"q":"在 Arizona，如果你 12 个月内记录上有 8 分或更多，会怎么样？","o":["你可能要上交通生存学校（Traffic Survival School），或失去驾照","没事，分数只在 5 年后才算","你必须买新的车辆登记","你只需要重考视力"],"h1":"分数会累加，到 8 分州政府就会管。","h2":"在 Arizona，如果你 12 个月内累积 8 分或更多，MVD（车辆管理部门）可以要求你上交通生存学校（Traffic Survival School），或暂停你的驾照。","p":"对。12 个月内 8 分，可能要上交通生存学校或被暂停驾照。"},"vi":{"q":"Ở Arizona, điều gì có thể xảy ra nếu bạn bị 8 điểm trở lên trong hồ sơ trong 12 tháng?","o":["Bạn có thể phải học Trường An toàn Giao thông (Traffic Survival School) hoặc mất bằng lái","Không có gì, điểm chỉ tính sau 5 năm","Bạn phải mua đăng ký xe mới","Bạn chỉ phải thi lại thị lực"],"h1":"Điểm được cộng dồn, và tiểu bang can thiệp khi đến 8 điểm.","h2":"Ở Arizona, nếu bạn bị 8 điểm trở lên trong 12 tháng, MVD (Sở Xe cơ giới) có thể buộc bạn học Trường An toàn Giao thông (Traffic Survival School) hoặc treo bằng lái của bạn.","p":"Đúng. 8 điểm trong 12 tháng có thể là phải học Traffic Survival School hoặc bị treo bằng."},"tl":{"q":"Sa Arizona, ano ang puwedeng mangyari kung makakuha ka ng 8 o higit pang puntos sa record mo sa loob ng 12 buwan?","o":["Baka kailangan mong pumasok sa Traffic Survival School o mawalan ng lisensiya","Wala, may epekto lang ang puntos pagkatapos ng 5 taon","Kailangan mong bumili ng bagong vehicle registration","Kailangan mo lang ulitin ang vision test"],"h1":"Nag-iipon ang puntos, at kumikilos ang estado sa 8.","h2":"Sa Arizona, kung makaipon ka ng 8 o higit pang puntos sa loob ng 12 buwan, puwedeng utusan ka ng MVD (Motor Vehicle Division) na pumasok sa Traffic Survival School o suspendihin ang lisensiya mo.","p":"Tama. Ang 8 puntos sa 12 buwan ay puwedeng mangahulugan ng Traffic Survival School o suspensiyon."},"ar":{"q":"في Arizona، ماذا يمكن أن يحدث إذا حصلت على 8 نقاط أو أكثر في سجلّك خلال 12 شهرًا؟","o":["قد يجب عليك حضور مدرسة السلامة المرورية (Traffic Survival School) أو تفقد رخصتك","لا شيء، النقاط تهمّ فقط بعد 5 سنوات","يجب أن تشتري تسجيلًا جديدًا للمركبة","يجب أن تعيد اختبار النظر فقط"],"h1":"النقاط تتجمّع، والولاية تتدخّل عند 8.","h2":"إذا جمعت 8 نقاط أو أكثر خلال 12 شهرًا في Arizona، يمكن لـ MVD (قسم المركبات) أن يأمرك بحضور مدرسة السلامة المرورية (Traffic Survival School) أو يوقف رخصتك.","p":"صحيح. 8 نقاط في 12 شهرًا قد تعني Traffic Survival School أو إيقاف الرخصة."},"ref":{"doc":"AZ","page":49}},{"id":"az-020","scope":"AZ","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arizona, which conviction always requires you to complete Traffic Survival School?","o":["A parking ticket","Running a red light","An expired registration","A broken taillight"],"h1":"It is a dangerous moving violation at an intersection.","h2":"In Arizona, a conviction for running a red light, or a flashing red light, always means you must complete Traffic Survival School, on top of paying the fine.","p":"Right. Running a red light means Traffic Survival School."},"es":{"q":"En Arizona, ¿qué infracción siempre le obliga a completar la Escuela de Supervivencia de Tráfico?","o":["Una multa de estacionamiento","Pasarse un semáforo en rojo","Un registro vencido","Una luz trasera rota"],"h1":"Es una infracción peligrosa en una intersección.","h2":"En Arizona, una condena por pasarse un semáforo en rojo, o una luz roja intermitente, siempre le obliga a completar la Escuela de Supervivencia de Tráfico, además de pagar la multa.","p":"Correcto. Pasarse un rojo lleva a la escuela de tráfico."},"zh":{"q":"在 Arizona，哪种定罪一定要你完成交通生存学校（Traffic Survival School）？","o":["停车罚单","闯红灯","车辆登记过期","尾灯坏了"],"h1":"它是在路口发生的危险的行车违规。","h2":"在 Arizona，闯红灯或闯闪烁红灯被定罪，除了交罚款，一定还要完成交通生存学校（Traffic Survival School）。","p":"对。闯红灯就要上交通生存学校。"},"vi":{"q":"Ở Arizona, bị kết tội vi phạm nào thì luôn phải hoàn thành Trường An toàn Giao thông (Traffic Survival School)?","o":["Phiếu phạt đậu xe","Vượt đèn đỏ","Đăng ký xe hết hạn","Đèn hậu bị hỏng"],"h1":"Đó là một vi phạm nguy hiểm khi đang chạy xe ở giao lộ.","h2":"Ở Arizona, bị kết tội vượt đèn đỏ, hoặc đèn đỏ nhấp nháy, thì luôn phải hoàn thành Trường An toàn Giao thông (Traffic Survival School), ngoài việc trả tiền phạt.","p":"Đúng. Vượt đèn đỏ thì phải học Traffic Survival School."},"tl":{"q":"Sa Arizona, aling conviction ang palaging nangangailangan na tapusin mo ang Traffic Survival School?","o":["Parking ticket","Paglampas sa red light","Expired na registration","Sirang taillight"],"h1":"Ito ay delikadong paglabag habang nagmamaneho sa intersection.","h2":"Sa Arizona, ang conviction sa paglampas sa red light, o sa kumikislap na red light, ay palaging nangangahulugan na dapat mong tapusin ang Traffic Survival School, bukod sa pagbabayad ng multa.","p":"Tama. Ang paglampas sa red light ay nangangahulugan ng Traffic Survival School."},"ar":{"q":"في Arizona، أي إدانة تتطلّب دائمًا أن تكمل مدرسة السلامة المرورية (Traffic Survival School)؟","o":["مخالفة وقوف","قطع الإشارة الحمراء","تسجيل منتهي الصلاحية","ضوء خلفي مكسور"],"h1":"هي مخالفة قيادة خطيرة عند تقاطع.","h2":"في Arizona، الإدانة بقطع الإشارة الحمراء، أو الإشارة الحمراء الوامضة، تعني دائمًا أنك يجب أن تكمل مدرسة السلامة المرورية (Traffic Survival School)، بالإضافة إلى دفع الغرامة.","p":"صحيح. قطع الإشارة الحمراء يعني Traffic Survival School."},"ref":{"doc":"AZ","page":30}},{"id":"az-021","scope":"AZ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arizona, at what blood alcohol level does a driver face an Extreme DUI charge?","o":["0.02 or more","0.05 or more","0.08 or more","0.15 or more"],"h1":"It is almost twice the normal adult limit.","h2":"Arizona charges Extreme DUI when a driver's blood alcohol is 0.15 or more, and the penalties are harsher than for a regular DUI.","p":"Right. Extreme DUI starts at 0.15."},"es":{"q":"En Arizona, ¿con qué nivel de alcohol en la sangre se acusa a un conductor de DUI Extremo?","o":["0.02 o más","0.05 o más","0.08 o más","0.15 o más"],"h1":"Es casi el doble del límite normal para adultos.","h2":"Arizona acusa de DUI Extremo cuando el alcohol en la sangre del conductor es 0.15 o más, y las sanciones son más duras que en un DUI normal.","p":"Correcto. El DUI Extremo empieza en 0.15."},"zh":{"q":"在 Arizona，血液酒精浓度达到多少时，司机会被控严重酒驾（Extreme DUI）？","o":["0.02 或以上","0.05 或以上","0.08 或以上","0.15 或以上"],"h1":"它差不多是成年人正常上限的两倍。","h2":"在 Arizona，司机血液酒精浓度 0.15 或以上时，会被控严重酒驾（Extreme DUI），处罚比普通酒驾更重。","p":"对。严重酒驾从 0.15 开始。"},"vi":{"q":"Ở Arizona, nồng độ cồn trong máu bao nhiêu thì tài xế bị buộc tội Lái xe say rượu nghiêm trọng (Extreme DUI)?","o":["0.02 trở lên","0.05 trở lên","0.08 trở lên","0.15 trở lên"],"h1":"Gần gấp đôi giới hạn bình thường của người lớn.","h2":"Arizona buộc tội Lái xe say rượu nghiêm trọng (Extreme DUI) khi nồng độ cồn trong máu của tài xế là 0.15 trở lên, và hình phạt nặng hơn DUI thông thường.","p":"Đúng. Extreme DUI bắt đầu từ 0.15."},"tl":{"q":"Sa Arizona, sa anong antas ng alak sa dugo haharap ang driver sa kasong Extreme DUI?","o":["0.02 o higit pa","0.05 o higit pa","0.08 o higit pa","0.15 o higit pa"],"h1":"Halos doble ito ng karaniwang limit para sa adult.","h2":"Sa Arizona, kinakasuhan ng Extreme DUI ang driver kapag 0.15 o higit pa ang alak sa dugo niya, at mas mabigat ang parusa kaysa sa regular na DUI.","p":"Tama. Nagsisimula ang Extreme DUI sa 0.15."},"ar":{"q":"في Arizona، عند أي نسبة كحول في الدم يُتّهم السائق بالقيادة تحت تأثير الكحول الشديد (Extreme DUI)؟","o":["0.02 أو أكثر","0.05 أو أكثر","0.08 أو أكثر","0.15 أو أكثر"],"h1":"هي تقريبًا ضعف الحدّ العادي للبالغين.","h2":"Arizona توجّه تهمة القيادة تحت تأثير الكحول الشديد (Extreme DUI) عندما تكون نسبة الكحول في دم السائق 0.15 أو أكثر، والعقوبات أشدّ من DUI العادي.","p":"صحيح. Extreme DUI يبدأ من 0.15."},"ref":{"doc":"AZ","page":52}},{"id":"az-022","scope":"AZ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arizona, how much alcohol may a driver under 21 have in their body?","o":["Up to 0.02","None at all","Up to 0.05","Up to 0.08"],"h1":"Arizona has zero tolerance for young drivers.","h2":"A driver under 21 in Arizona may not drive with any alcohol in the body, because the state has a zero tolerance law for young drivers.","p":"Right. Under 21 means no alcohol at all."},"es":{"q":"En Arizona, ¿cuánto alcohol puede tener en el cuerpo un conductor menor de 21 años?","o":["Hasta 0.02","Nada","Hasta 0.05","Hasta 0.08"],"h1":"Arizona tiene tolerancia cero para conductores jóvenes.","h2":"Un conductor menor de 21 años en Arizona no puede manejar con nada de alcohol en el cuerpo, porque el estado tiene una ley de tolerancia cero para conductores jóvenes.","p":"Correcto. Menor de 21 significa nada de alcohol."},"zh":{"q":"在 Arizona，21 岁以下的司机体内可以有多少酒精？","o":["最多 0.02","完全不可以有","最多 0.05","最多 0.08"],"h1":"Arizona 对年轻司机零容忍。","h2":"在 Arizona，21 岁以下的司机体内有任何酒精都不可以开车，因为这个州对年轻司机有零容忍法律。","p":"对。21 岁以下，一点酒精都不能有。"},"vi":{"q":"Ở Arizona, tài xế dưới 21 tuổi được có bao nhiêu cồn trong cơ thể?","o":["Tối đa 0.02","Hoàn toàn không có","Tối đa 0.05","Tối đa 0.08"],"h1":"Arizona không khoan nhượng với tài xế trẻ.","h2":"Ở Arizona, tài xế dưới 21 tuổi không được lái xe khi có bất kỳ chút cồn nào trong cơ thể, vì tiểu bang có luật không khoan nhượng đối với tài xế trẻ.","p":"Đúng. Dưới 21 tuổi là hoàn toàn không có cồn."},"tl":{"q":"Sa Arizona, gaano karaming alak ang puwedeng nasa katawan ng driver na wala pang 21?","o":["Hanggang 0.02","Wala talaga","Hanggang 0.05","Hanggang 0.08"],"h1":"Zero tolerance ang Arizona para sa mga batang driver.","h2":"Sa Arizona, ang driver na wala pang 21 ay hindi puwedeng magmaneho nang may kahit anong alak sa katawan, dahil may zero tolerance law ang estado para sa mga batang driver.","p":"Tama. Kung wala pang 21, walang alak talaga."},"ar":{"q":"في Arizona، كم يجوز أن يكون في جسم السائق الذي عمره أقل من 21 سنة من الكحول؟","o":["حتى 0.02","لا شيء أبدًا","حتى 0.05","حتى 0.08"],"h1":"Arizona لا تتسامح أبدًا مع السائقين الشباب.","h2":"في Arizona لا يجوز للسائق الذي عمره أقل من 21 سنة أن يقود وفي جسمه أي كمية من الكحول، لأن الولاية لديها قانون عدم التسامح مع السائقين الشباب.","p":"صحيح. أقل من 21 سنة يعني لا كحول أبدًا."},"ref":{"doc":"AZ","page":47}},{"id":"az-023","scope":"AZ","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arizona, what is the minimum liability insurance for damage to other people's property in one crash?","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"Arizona's minimum is often written as 25/50/15.","h2":"Arizona requires at least $15,000 of property damage liability for one crash, as part of the 25/50/15 minimum.","p":"Right. The property damage minimum is $15,000."},"es":{"q":"En Arizona, ¿cuál es el seguro mínimo de responsabilidad por daños a la propiedad de otros en un choque?","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"El mínimo de Arizona se escribe a menudo como 25/50/15.","h2":"Arizona exige por lo menos $15,000 de cobertura por daños a la propiedad en un choque, como parte del mínimo 25/50/15.","p":"Correcto. El mínimo por daños a la propiedad es $15,000."},"zh":{"q":"在 Arizona，一次车祸中，对别人财产损失的最低责任保险是多少？","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"Arizona 的最低标准常写成 25/50/15。","h2":"Arizona 要求一次车祸至少有 $15,000 的财产损失责任保险，这是 25/50/15 最低标准的一部分。","p":"对。财产损失最低是 $15,000。"},"vi":{"q":"Ở Arizona, bảo hiểm trách nhiệm tối thiểu cho thiệt hại tài sản của người khác trong một vụ tai nạn là bao nhiêu?","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"Mức tối thiểu của Arizona thường được viết là 25/50/15.","h2":"Arizona yêu cầu ít nhất $15,000 bảo hiểm trách nhiệm thiệt hại tài sản cho một vụ tai nạn, là một phần của mức tối thiểu 25/50/15.","p":"Đúng. Mức tối thiểu cho thiệt hại tài sản là $15,000."},"tl":{"q":"Sa Arizona, ano ang minimum na liability insurance para sa pinsala sa ari-arian ng ibang tao sa isang aksidente?","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"Madalas isulat ang minimum ng Arizona bilang 25/50/15.","h2":"Hinihingi ng Arizona ang hindi bababa sa $15,000 na property damage liability para sa isang aksidente, bilang bahagi ng 25/50/15 na minimum.","p":"Tama. $15,000 ang minimum para sa pinsala sa ari-arian."},"ar":{"q":"في Arizona، ما الحدّ الأدنى لتأمين المسؤولية عن الضرر بممتلكات الآخرين في حادث واحد؟","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"الحدّ الأدنى في Arizona يُكتب غالبًا 25/50/15.","h2":"Arizona تطلب على الأقل $15,000 من تأمين المسؤولية عن ضرر الممتلكات لحادث واحد، كجزء من الحدّ الأدنى 25/50/15.","p":"صحيح. الحدّ الأدنى لضرر الممتلكات هو $15,000."},"ref":{"doc":"AZ","page":8}},{"id":"az-024","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, what is the minimum liability insurance for injury to one person in a crash?","o":["$25,000","$15,000","$30,000","$50,000"],"h1":"It is the first number in 25/50/15.","h2":"Arizona requires at least $25,000 of bodily injury coverage for one person in a crash, the first number in the 25/50/15 minimum.","p":"Right. The minimum for one injured person is $25,000."},"es":{"q":"En Arizona, ¿cuál es el seguro mínimo de responsabilidad por lesiones a una persona en un choque?","o":["$25,000","$15,000","$30,000","$50,000"],"h1":"Es el primer número de 25/50/15.","h2":"Arizona exige por lo menos $25,000 de cobertura por lesiones a una persona en un choque, el primer número del mínimo 25/50/15.","p":"Correcto. El mínimo por una persona lesionada es $25,000."},"zh":{"q":"在 Arizona，一次车祸中，对一个人受伤的最低责任保险是多少？","o":["$25,000","$15,000","$30,000","$50,000"],"h1":"它是 25/50/15 里的第一个数字。","h2":"Arizona 要求一次车祸中对一个人至少有 $25,000 的人身伤害保险，这是 25/50/15 最低标准里的第一个数字。","p":"对。一个人受伤的最低标准是 $25,000。"},"vi":{"q":"Ở Arizona, bảo hiểm trách nhiệm tối thiểu cho thương tích của một người trong tai nạn là bao nhiêu?","o":["$25,000","$15,000","$30,000","$50,000"],"h1":"Đó là con số đầu tiên trong 25/50/15.","h2":"Arizona yêu cầu ít nhất $25,000 bảo hiểm thương tích cơ thể cho một người trong tai nạn, là con số đầu tiên trong mức tối thiểu 25/50/15.","p":"Đúng. Mức tối thiểu cho một người bị thương là $25,000."},"tl":{"q":"Sa Arizona, ano ang minimum na liability insurance para sa pinsala sa isang tao sa aksidente?","o":["$25,000","$15,000","$30,000","$50,000"],"h1":"Ito ang unang numero sa 25/50/15.","h2":"Hinihingi ng Arizona ang hindi bababa sa $25,000 na bodily injury coverage para sa isang tao sa aksidente, ang unang numero sa 25/50/15 na minimum.","p":"Tama. $25,000 ang minimum para sa isang taong nasaktan."},"ar":{"q":"في Arizona، ما الحدّ الأدنى لتأمين المسؤولية عن إصابة شخص واحد في حادث؟","o":["$25,000","$15,000","$30,000","$50,000"],"h1":"هو الرقم الأول في 25/50/15.","h2":"Arizona تطلب على الأقل $25,000 من تأمين الإصابات الجسدية لشخص واحد في حادث، وهو الرقم الأول في الحدّ الأدنى 25/50/15.","p":"صحيح. الحدّ الأدنى لشخص واحد مصاب هو $25,000."},"ref":{"doc":"AZ","page":8}},{"id":"az-025","scope":"AZ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Arizona, a child must ride in a child restraint (car seat) until what age?","o":["Until age 2","Until age 4","Until age 5","Until age 10"],"h1":"It is about the age when many children start kindergarten.","h2":"In Arizona a child under five years old must ride in a child restraint.","p":"Right. In Arizona, children under 5 must be in a child restraint."},"es":{"q":"En Arizona, ¿hasta qué edad debe ir un niño en un sistema de retención infantil (asiento de seguridad)?","o":["Hasta los 2 años","Hasta los 4 años","Hasta los 5 años","Hasta los 10 años"],"h1":"Es más o menos la edad en que muchos niños empiezan el kínder.","h2":"En Arizona un niño menor de cinco años debe ir en un sistema de retención infantil.","p":"Correcto. En Arizona, los niños menores de 5 años deben ir en un asiento de seguridad."},"zh":{"q":"在 Arizona，儿童必须坐在儿童安全座椅（child restraint）里，直到几岁？","o":["到 2 岁","到 4 岁","到 5 岁","到 10 岁"],"h1":"大约是很多孩子开始上幼儿园的年龄。","h2":"在 Arizona，不满 5 岁的儿童必须坐在儿童安全座椅里。","p":"对。在 Arizona，不满 5 岁的儿童必须坐儿童安全座椅。"},"vi":{"q":"Ở Arizona, trẻ em phải ngồi ghế an toàn cho trẻ em (child restraint) cho đến bao nhiêu tuổi?","o":["Đến 2 tuổi","Đến 4 tuổi","Đến 5 tuổi","Đến 10 tuổi"],"h1":"Đó là khoảng tuổi nhiều trẻ bắt đầu đi mẫu giáo.","h2":"Ở Arizona, trẻ em dưới 5 tuổi phải ngồi ghế an toàn cho trẻ em.","p":"Đúng. Ở Arizona, trẻ em dưới 5 tuổi phải ngồi ghế an toàn cho trẻ em."},"tl":{"q":"Sa Arizona, hanggang anong edad dapat nakaupo ang bata sa child restraint (car seat)?","o":["Hanggang edad 2","Hanggang edad 4","Hanggang edad 5","Hanggang edad 10"],"h1":"Ito ang edad kung kailan maraming bata ang nagsisimula sa kindergarten.","h2":"Sa Arizona, ang batang wala pang 5 taong gulang ay dapat nakaupo sa child restraint.","p":"Tama. Sa Arizona, ang mga batang wala pang 5 ay dapat nasa child restraint."},"ar":{"q":"في Arizona، حتى أي عمر يجب أن يجلس الطفل في مقعد أمان للأطفال (child restraint)؟","o":["حتى عمر 2","حتى عمر 4","حتى عمر 5","حتى عمر 10"],"h1":"إنه تقريبًا العمر الذي يبدأ فيه كثير من الأطفال الروضة.","h2":"في Arizona يجب أن يجلس الطفل الذي عمره أقل من 5 سنوات في مقعد أمان للأطفال.","p":"صحيح. في Arizona يجب أن يجلس الأطفال تحت عمر 5 في مقعد أمان للأطفال."},"ref":{"doc":"AZ","page":null}},{"id":"az-026","scope":"AZ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arizona, a 6-year-old is 4 feet 5 inches tall. How must the child ride?","o":["In a child restraint, such as a booster seat","With only an adult seat belt","On an adult's lap","In the front seat with an air bag"],"h1":"Children aged 5 to 7 who are 4 feet 9 inches or shorter still need extra help to fit the belt.","h2":"In Arizona a child aged 5 to 7 who is 4 feet 9 inches or shorter must ride in a child restraint, such as a booster seat.","p":"Right. This child still needs a booster seat or other child restraint in Arizona."},"es":{"q":"En Arizona, un niño de 6 años mide 4 pies 5 pulgadas. ¿Cómo debe viajar?","o":["En un sistema de retención infantil, como un asiento elevado (booster)","Solo con el cinturón de seguridad de adulto","Sentado en las piernas de un adulto","En el asiento delantero con bolsa de aire"],"h1":"Los niños de 5 a 7 años que miden 4 pies 9 pulgadas o menos todavía necesitan ayuda para que el cinturón les quede bien.","h2":"En Arizona un niño de 5 a 7 años que mide 4 pies 9 pulgadas o menos debe viajar en un sistema de retención infantil, como un asiento elevado.","p":"Correcto. En Arizona, este niño todavía necesita un asiento elevado u otro asiento infantil."},"zh":{"q":"在 Arizona，一个 6 岁的孩子身高 4 英尺 5 英寸。这个孩子必须怎样乘车？","o":["坐在儿童安全座椅里，例如加高座椅（booster seat）","只系成人安全带","坐在大人的腿上","坐在有安全气囊的前座"],"h1":"5 到 7 岁、身高 4 英尺 9 英寸或以下的孩子，仍然需要额外帮助才能系好安全带。","h2":"在 Arizona，5 到 7 岁、身高 4 英尺 9 英寸或以下的孩子，必须坐在儿童安全座椅里，例如加高座椅。","p":"对。在 Arizona，这个孩子仍然需要加高座椅或其他儿童安全座椅。"},"vi":{"q":"Ở Arizona, một em bé 6 tuổi cao 4 feet 5 inches. Em bé này phải ngồi xe như thế nào?","o":["Ngồi ghế an toàn cho trẻ em, ví dụ ghế nâng (booster seat)","Chỉ thắt dây an toàn của người lớn","Ngồi trên đùi người lớn","Ngồi ghế trước có túi khí"],"h1":"Trẻ từ 5 đến 7 tuổi cao 4 feet 9 inches hoặc thấp hơn vẫn cần thêm trợ giúp để dây an toàn vừa người.","h2":"Ở Arizona, trẻ từ 5 đến 7 tuổi cao 4 feet 9 inches hoặc thấp hơn phải ngồi ghế an toàn cho trẻ em, ví dụ ghế nâng.","p":"Đúng. Ở Arizona, em bé này vẫn cần ghế nâng hoặc ghế an toàn cho trẻ em khác."},"tl":{"q":"Sa Arizona, may batang 6 na taong gulang na 4 feet 5 inches ang taas. Paano dapat sumakay ang bata?","o":["Sa child restraint, gaya ng booster seat","Gamit lang ang seat belt ng adult","Sa kandungan ng adult","Sa front seat na may air bag"],"h1":"Ang mga batang 5 hanggang 7 taong gulang na 4 feet 9 inches o mas maliit ay kailangan pa ng tulong para tumama nang tama ang belt.","h2":"Sa Arizona, ang batang 5 hanggang 7 taong gulang na 4 feet 9 inches o mas maliit ay dapat nakaupo sa child restraint, gaya ng booster seat.","p":"Tama. Sa Arizona, kailangan pa ng batang ito ng booster seat o ibang child restraint."},"ar":{"q":"في Arizona، طفل عمره 6 سنوات وطوله 4 أقدام و5 بوصات. كيف يجب أن يركب الطفل؟","o":["في مقعد أمان للأطفال، مثل المقعد المعزِّز (booster seat)","بحزام أمان البالغين فقط","في حضن شخص بالغ","في المقعد الأمامي الذي فيه وسادة هوائية"],"h1":"الأطفال من عمر 5 إلى 7 الذين طولهم 4 أقدام و9 بوصات أو أقل ما زالوا يحتاجون إلى مساعدة إضافية ليناسبهم الحزام.","h2":"في Arizona يجب أن يجلس الطفل من عمر 5 إلى 7 الذي طوله 4 أقدام و9 بوصات أو أقل في مقعد أمان للأطفال، مثل المقعد المعزِّز.","p":"صحيح. في Arizona ما زال هذا الطفل يحتاج إلى مقعد معزِّز أو مقعد أمان آخر للأطفال."},"ref":{"doc":"AZ","page":null}},{"id":"az-027","scope":"AZ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arizona, you are arrested for DUI and refuse the alcohol test for the first time. How long will your license be suspended?","o":["30 days","90 days","6 months","12 months"],"h1":"It is a full year.","h2":"In Arizona a first refusal to take the alcohol test means your license is suspended for 12 months.","p":"Right. A first test refusal in Arizona brings a 12-month suspension."},"es":{"q":"En Arizona, usted es arrestado por manejar bajo los efectos del alcohol (DUI) y se niega a la prueba de alcohol por primera vez. ¿Por cuánto tiempo le suspenderán la licencia?","o":["30 días","90 días","6 meses","12 meses"],"h1":"Es un año completo.","h2":"En Arizona, negarse por primera vez a la prueba de alcohol significa que su licencia se suspende por 12 meses.","p":"Correcto. En Arizona, la primera negativa a la prueba trae una suspensión de 12 meses."},"zh":{"q":"在 Arizona，你因酒后驾驶（DUI）被捕，并且第一次拒绝酒精测试。你的驾照会被暂停多久？","o":["30 天","90 天","6 个月","12 个月"],"h1":"是整整一年。","h2":"在 Arizona，第一次拒绝酒精测试，你的驾照会被暂停 12 个月。","p":"对。在 Arizona，第一次拒绝测试会被暂停驾照 12 个月。"},"vi":{"q":"Ở Arizona, bạn bị bắt vì lái xe khi say (DUI) và từ chối kiểm tra nồng độ cồn lần đầu tiên. Bằng lái của bạn sẽ bị đình chỉ bao lâu?","o":["30 ngày","90 ngày","6 tháng","12 tháng"],"h1":"Đó là trọn một năm.","h2":"Ở Arizona, lần đầu từ chối kiểm tra nồng độ cồn thì bằng lái của bạn bị đình chỉ 12 tháng.","p":"Đúng. Ở Arizona, lần đầu từ chối kiểm tra sẽ bị đình chỉ bằng lái 12 tháng."},"tl":{"q":"Sa Arizona, inaresto ka dahil sa DUI at tumanggi ka sa alcohol test sa unang pagkakataon. Gaano katagal masususpinde ang lisensya mo?","o":["30 araw","90 araw","6 na buwan","12 buwan"],"h1":"Isang buong taon ito.","h2":"Sa Arizona, kapag unang beses kang tumanggi sa alcohol test, masususpinde ang lisensya mo nang 12 buwan.","p":"Tama. Sa Arizona, ang unang pagtanggi sa test ay may suspensyon na 12 buwan."},"ar":{"q":"في Arizona، تم القبض عليك بسبب القيادة تحت تأثير الكحول (DUI) ورفضت اختبار الكحول لأول مرة. كم مدة إيقاف رخصتك؟","o":["30 يومًا","90 يومًا","6 أشهر","12 شهرًا"],"h1":"إنها سنة كاملة.","h2":"في Arizona إذا رفضت اختبار الكحول لأول مرة تُوقَف رخصتك لمدة 12 شهرًا.","p":"صحيح. في Arizona يؤدي أول رفض للاختبار إلى إيقاف الرخصة لمدة 12 شهرًا."},"ref":{"doc":"AZ","page":null}},{"id":"az-028","scope":"AZ","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Arizona, what is the lowest fine for a first offense of passing a stopped school bus with its stop sign out?","o":["$100","$250","$500","$1,000"],"h1":"It is a quarter of a thousand dollars.","h2":"In Arizona the minimum penalty for a first offense of passing a stopped school bus is $250.","p":"Right. In Arizona, a first school bus passing offense costs at least $250."},"es":{"q":"En Arizona, ¿cuál es la multa mínima por una primera infracción de rebasar un autobús escolar detenido con su señal de alto extendida?","o":["$100","$250","$500","$1,000"],"h1":"Es la cuarta parte de mil dólares.","h2":"En Arizona la multa mínima por una primera infracción de rebasar un autobús escolar detenido es de $250.","p":"Correcto. En Arizona, la primera infracción por rebasar un autobús escolar cuesta por lo menos $250."},"zh":{"q":"在 Arizona，第一次超越已停下并伸出停车标志的校车，最低罚款是多少？","o":["$100","$250","$500","$1,000"],"h1":"是一千美元的四分之一。","h2":"在 Arizona，第一次超越已停下的校车，最低处罚是 $250。","p":"对。在 Arizona，第一次超越校车至少要罚 $250。"},"vi":{"q":"Ở Arizona, mức phạt thấp nhất cho lần vi phạm đầu tiên khi vượt xe buýt trường học đang dừng và đưa biển STOP ra là bao nhiêu?","o":["$100","$250","$500","$1,000"],"h1":"Đó là một phần tư của một nghìn đô la.","h2":"Ở Arizona, mức phạt tối thiểu cho lần đầu vượt xe buýt trường học đang dừng là $250.","p":"Đúng. Ở Arizona, lần đầu vượt xe buýt trường học bị phạt ít nhất $250."},"tl":{"q":"Sa Arizona, magkano ang pinakamababang multa sa unang paglabag kapag nilampasan mo ang nakahintong school bus na nakalabas ang stop sign?","o":["$100","$250","$500","$1,000"],"h1":"Isang-kapat ito ng isang libong dolyar.","h2":"Sa Arizona, ang pinakamababang parusa sa unang paglabag ng paglampas sa nakahintong school bus ay $250.","p":"Tama. Sa Arizona, ang unang paglabag ng paglampas sa school bus ay hindi bababa sa $250."},"ar":{"q":"في Arizona، ما أقل غرامة على المخالفة الأولى لتجاوز حافلة مدرسية متوقفة ولافتة التوقف فيها ممدودة؟","o":["$100","$250","$500","$1,000"],"h1":"إنها ربع ألف دولار.","h2":"في Arizona أقل عقوبة على المخالفة الأولى لتجاوز حافلة مدرسية متوقفة هي $250.","p":"صحيح. في Arizona تكلّف المخالفة الأولى لتجاوز الحافلة المدرسية $250 على الأقل."},"ref":{"doc":"AZ","page":null}},{"id":"az-029","scope":"AZ","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Arizona, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 15 feet","No closer than 30 feet"],"h1":"It is more than 10 feet.","h2":"In Arizona you may not park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet away from a fire hydrant."},"es":{"q":"En Arizona, ¿qué tan cerca de un hidrante de incendios puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 15 pies","No más cerca de 30 pies"],"h1":"Es más de 10 pies.","h2":"En Arizona usted no puede estacionarse a menos de 15 pies de un hidrante de incendios.","p":"Correcto. Manténgase por lo menos a 15 pies de un hidrante."},"zh":{"q":"在 Arizona，你可以把车停在离消防栓多近的地方？","o":["不能少于 5 英尺","不能少于 10 英尺","不能少于 15 英尺","不能少于 30 英尺"],"h1":"它比 10 英尺多。","h2":"在 Arizona，你不能把车停在离消防栓 15 英尺以内的地方。","p":"对。要离消防栓至少 15 英尺。"},"vi":{"q":"Ở Arizona, bạn được đậu xe gần trụ nước cứu hỏa đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 15 feet","Không gần hơn 30 feet"],"h1":"Khoảng cách này hơn 10 feet.","h2":"Ở Arizona, bạn không được đậu xe trong vòng 15 feet tính từ trụ nước cứu hỏa.","p":"Đúng. Hãy đậu xe cách trụ nước cứu hỏa ít nhất 15 feet."},"tl":{"q":"Sa Arizona, gaano kalapit sa fire hydrant puwede kang mag-park?","o":["Hindi lalapit sa 5 feet","Hindi lalapit sa 10 feet","Hindi lalapit sa 15 feet","Hindi lalapit sa 30 feet"],"h1":"Higit ito sa 10 feet.","h2":"Sa Arizona, hindi ka puwedeng mag-park sa loob ng 15 feet mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 15 feet mula sa fire hydrant."},"ar":{"q":"في Arizona، إلى أي مدى يمكنك أن توقف سيارتك قرب حنفية إطفاء الحريق؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 10 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 30 قدمًا"],"h1":"المسافة أكثر من 10 أقدام.","h2":"في Arizona لا يجوز لك أن توقف سيارتك على بُعد أقل من 15 قدمًا من حنفية إطفاء الحريق.","p":"صحيح. ابقَ على بُعد 15 قدمًا على الأقل من حنفية إطفاء الحريق."},"ref":{"doc":"AZ","page":null}},{"id":"az-030","scope":"AZ","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Arizona, a police car is using its siren and red or blue lights for an emergency. How far behind it must you stay?","o":["At least 300 feet","At least 50 feet","At least 100 feet","At least 1,000 feet"],"h1":"Leave a long gap, because the police car may stop or turn suddenly.","h2":"In Arizona you must stay at least 300 feet behind a police car that is using its siren and lights for an emergency.","p":"Right. Stay at least 300 feet behind a police car in an emergency."},"es":{"q":"En Arizona, una patrulla de policía usa la sirena y luces rojas o azules por una emergencia. ¿A qué distancia detrás de ella debe quedarse?","o":["Por lo menos a 300 pies","Por lo menos a 50 pies","Por lo menos a 100 pies","Por lo menos a 1,000 pies"],"h1":"Deje un espacio largo, porque la patrulla puede detenerse o dar vuelta de repente.","h2":"En Arizona usted debe quedarse por lo menos a 300 pies detrás de una patrulla que usa la sirena y las luces por una emergencia.","p":"Correcto. Quédese por lo menos a 300 pies detrás de una patrulla en una emergencia."},"zh":{"q":"在 Arizona，一辆警车正在为紧急情况鸣警笛并亮着红灯或蓝灯。你必须在它后面保持多远？","o":["至少 300 英尺","至少 50 英尺","至少 100 英尺","至少 1,000 英尺"],"h1":"要留出很长的距离，因为警车可能会突然停下或转弯。","h2":"在 Arizona，当警车为紧急情况鸣警笛并亮灯时，你必须在它后面至少保持 300 英尺。","p":"对。紧急情况下，要在警车后面至少保持 300 英尺。"},"vi":{"q":"Ở Arizona, một xe cảnh sát đang hú còi và bật đèn đỏ hoặc xanh vì có việc khẩn cấp. Bạn phải đi cách phía sau nó bao xa?","o":["Ít nhất 300 feet","Ít nhất 50 feet","Ít nhất 100 feet","Ít nhất 1,000 feet"],"h1":"Hãy để một khoảng cách dài, vì xe cảnh sát có thể dừng hoặc rẽ bất ngờ.","h2":"Ở Arizona, bạn phải đi cách phía sau xe cảnh sát ít nhất 300 feet khi xe đó đang hú còi và bật đèn vì việc khẩn cấp.","p":"Đúng. Hãy đi cách phía sau xe cảnh sát ít nhất 300 feet khi có việc khẩn cấp."},"tl":{"q":"Sa Arizona, may kotse ng pulis na gumagamit ng siren at pula o asul na ilaw dahil sa emergency. Gaano kalayo ka dapat sa likod nito?","o":["Hindi bababa sa 300 feet","Hindi bababa sa 50 feet","Hindi bababa sa 100 feet","Hindi bababa sa 1,000 feet"],"h1":"Mag-iwan ng mahabang pagitan, dahil puwedeng biglang huminto o lumiko ang kotse ng pulis.","h2":"Sa Arizona, dapat kang manatili nang hindi bababa sa 300 feet sa likod ng kotse ng pulis na gumagamit ng siren at ilaw dahil sa emergency.","p":"Tama. Manatili nang hindi bababa sa 300 feet sa likod ng kotse ng pulis kapag may emergency."},"ar":{"q":"في Arizona، سيارة شرطة تستعمل صفّارتها وأضواءها الحمراء أو الزرقاء بسبب حالة طارئة. ما المسافة التي يجب أن تبقى فيها خلفها؟","o":["300 قدم على الأقل","50 قدمًا على الأقل","100 قدم على الأقل","1,000 قدم على الأقل"],"h1":"اترك مسافة طويلة، لأن سيارة الشرطة قد تتوقف أو تنعطف فجأة.","h2":"في Arizona يجب أن تبقى على بُعد 300 قدم على الأقل خلف سيارة الشرطة التي تستعمل صفّارتها وأضواءها بسبب حالة طارئة.","p":"صحيح. ابقَ على بُعد 300 قدم على الأقل خلف سيارة الشرطة في الحالة الطارئة."},"ref":{"doc":"AZ","page":null}},{"id":"az-031","scope":"AZ","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Arizona, a fire truck is going to a fire alarm. How close may you follow it?","o":["No closer than 50 feet","No closer than 100 feet","No closer than 300 feet","No closer than 500 feet"],"h1":"Give it plenty of room, because it may stop or turn suddenly.","h2":"In Arizona you may not follow a fire truck going to an alarm any closer than 500 feet.","p":"Right. Stay at least 500 feet behind a fire truck on its way to an alarm."},"es":{"q":"En Arizona, un camión de bomberos va hacia una alarma de incendio. ¿Qué tan cerca puede seguirlo?","o":["No más cerca de 50 pies","No más cerca de 100 pies","No más cerca de 300 pies","No más cerca de 500 pies"],"h1":"Dele mucho espacio, porque puede detenerse o dar vuelta de repente.","h2":"En Arizona usted no puede seguir a un camión de bomberos que va hacia una alarma a menos de 500 pies.","p":"Correcto. Quédese por lo menos a 500 pies detrás de un camión de bomberos que va a una alarma."},"zh":{"q":"在 Arizona，一辆消防车正赶去处理火警。你跟在它后面最近可以多近？","o":["不能少于 50 英尺","不能少于 100 英尺","不能少于 300 英尺","不能少于 500 英尺"],"h1":"要给它留出足够的空间，因为它可能会突然停下或转弯。","h2":"在 Arizona，跟在赶去火警的消防车后面时，距离不能少于 500 英尺。","p":"对。消防车赶去火警时，要在它后面至少保持 500 英尺。"},"vi":{"q":"Ở Arizona, một xe cứu hỏa đang chạy đến nơi có báo động cháy. Bạn được chạy theo sau nó gần đến mức nào?","o":["Không gần hơn 50 feet","Không gần hơn 100 feet","Không gần hơn 300 feet","Không gần hơn 500 feet"],"h1":"Hãy chừa cho nó nhiều khoảng trống, vì nó có thể dừng hoặc rẽ bất ngờ.","h2":"Ở Arizona, khi chạy theo sau xe cứu hỏa đang đến nơi báo động cháy, bạn không được đi gần hơn 500 feet.","p":"Đúng. Hãy đi cách phía sau xe cứu hỏa đang đến nơi báo động cháy ít nhất 500 feet."},"tl":{"q":"Sa Arizona, may fire truck na papunta sa fire alarm. Gaano kalapit ka puwedeng sumunod dito?","o":["Hindi lalapit sa 50 feet","Hindi lalapit sa 100 feet","Hindi lalapit sa 300 feet","Hindi lalapit sa 500 feet"],"h1":"Bigyan ito ng maraming espasyo, dahil puwede itong biglang huminto o lumiko.","h2":"Sa Arizona, hindi ka puwedeng sumunod sa fire truck na papunta sa alarm nang mas malapit sa 500 feet.","p":"Tama. Manatili nang hindi bababa sa 500 feet sa likod ng fire truck na papunta sa alarm."},"ar":{"q":"في Arizona، سيارة إطفاء متجهة إلى إنذار حريق. إلى أي مدى يمكنك أن تقترب منها وأنت تسير خلفها؟","o":["ليس أقرب من 50 قدمًا","ليس أقرب من 100 قدم","ليس أقرب من 300 قدم","ليس أقرب من 500 قدم"],"h1":"اترك لها مسافة كبيرة، لأنها قد تتوقف أو تنعطف فجأة.","h2":"في Arizona لا يجوز لك أن تسير خلف سيارة إطفاء متجهة إلى إنذار حريق على مسافة أقرب من 500 قدم.","p":"صحيح. ابقَ على بُعد 500 قدم على الأقل خلف سيارة الإطفاء المتجهة إلى إنذار حريق."},"ref":{"doc":"AZ","page":null}},{"id":"az-032","scope":"AZ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arizona, you are using high beams at night. A car is coming toward you. When must you switch to low beams?","o":["When it is within 100 feet","When it is within 500 feet","When it is within 1,500 feet","Only if the other driver flashes their lights"],"h1":"Switch early, so the other driver is not blinded.","h2":"In Arizona you must switch to low beams when an oncoming vehicle is within 500 feet.","p":"Right. Use low beams when an oncoming car is within 500 feet."},"es":{"q":"En Arizona, usted lleva las luces altas de noche. Un carro viene hacia usted. ¿Cuándo debe cambiar a luces bajas?","o":["Cuando esté a menos de 100 pies","Cuando esté a menos de 500 pies","Cuando esté a menos de 1,500 pies","Solo si el otro conductor le hace cambio de luces"],"h1":"Cambie temprano, para no deslumbrar al otro conductor.","h2":"En Arizona usted debe cambiar a luces bajas cuando un vehículo que viene de frente está a menos de 500 pies.","p":"Correcto. Use las luces bajas cuando un carro de frente esté a menos de 500 pies."},"zh":{"q":"在 Arizona，你晚上开着远光灯。前面有一辆车朝你开过来。你必须在什么时候换成近光灯？","o":["当它在 100 英尺以内时","当它在 500 英尺以内时","当它在 1,500 英尺以内时","只有对方司机闪灯时"],"h1":"要早点换，这样对方司机就不会被晃得看不见。","h2":"在 Arizona，当对面来车在 500 英尺以内时，你必须换成近光灯。","p":"对。对面来车在 500 英尺以内时，要用近光灯。"},"vi":{"q":"Ở Arizona, bạn đang bật đèn pha (đèn chiếu xa) vào ban đêm. Có một xe đang chạy ngược chiều về phía bạn. Khi nào bạn phải chuyển sang đèn cốt (đèn chiếu gần)?","o":["Khi xe đó cách bạn trong vòng 100 feet","Khi xe đó cách bạn trong vòng 500 feet","Khi xe đó cách bạn trong vòng 1,500 feet","Chỉ khi tài xế kia nháy đèn"],"h1":"Hãy chuyển đèn sớm, để tài xế kia không bị chói mắt.","h2":"Ở Arizona, bạn phải chuyển sang đèn cốt khi xe chạy ngược chiều cách bạn trong vòng 500 feet.","p":"Đúng. Hãy dùng đèn cốt khi xe chạy ngược chiều cách bạn trong vòng 500 feet."},"tl":{"q":"Sa Arizona, gumagamit ka ng high beams sa gabi. May kotseng paparating papunta sa iyo. Kailan ka dapat lumipat sa low beams?","o":["Kapag nasa loob na ito ng 100 feet","Kapag nasa loob na ito ng 500 feet","Kapag nasa loob na ito ng 1,500 feet","Kapag nag-flash lang ng ilaw ang ibang driver"],"h1":"Lumipat nang maaga, para hindi masilaw ang ibang driver.","h2":"Sa Arizona, dapat kang lumipat sa low beams kapag ang paparating na sasakyan ay nasa loob ng 500 feet.","p":"Tama. Gumamit ng low beams kapag ang paparating na kotse ay nasa loob ng 500 feet."},"ar":{"q":"في Arizona، أنت تستعمل الأضواء العالية (الضوء البعيد) في الليل. هناك سيارة قادمة نحوك. متى يجب أن تنتقل إلى الأضواء المنخفضة (الضوء القريب)؟","o":["عندما تصبح على بُعد 100 قدم أو أقل","عندما تصبح على بُعد 500 قدم أو أقل","عندما تصبح على بُعد 1,500 قدم أو أقل","فقط إذا أومض السائق الآخر بأضوائه"],"h1":"انتقل مبكرًا، حتى لا تُبهر عينَي السائق الآخر.","h2":"في Arizona يجب أن تنتقل إلى الأضواء المنخفضة عندما تكون السيارة القادمة نحوك على بُعد 500 قدم أو أقل.","p":"صحيح. استعمل الأضواء المنخفضة عندما تكون السيارة القادمة على بُعد 500 قدم أو أقل."},"ref":{"doc":"AZ","page":null}},{"id":"az-033","scope":"AZ","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Arizona, you are on a one-way street at a red light. You want to turn left onto another one-way street that goes left. What may you do?","o":["Never turn left on red","Turn left without stopping","Stop first, then turn left when it is safe","Wait for a police officer to wave you on"],"h1":"It is like a right turn on red, but between two one-way streets.","h2":"In Arizona you may turn left on red from a one-way street onto a one-way street going left, after a full stop and yielding, unless a sign forbids it.","p":"Right. Stop, yield, then you may turn left onto the one-way street."},"es":{"q":"En Arizona, usted está en una calle de un solo sentido con la luz roja. Quiere dar vuelta a la izquierda hacia otra calle de un solo sentido que va a la izquierda. ¿Qué puede hacer?","o":["Nunca dar vuelta a la izquierda con luz roja","Dar vuelta a la izquierda sin detenerse","Detenerse primero y luego dar vuelta a la izquierda cuando sea seguro","Esperar a que un policía le haga una señal"],"h1":"Es como dar vuelta a la derecha con luz roja, pero entre dos calles de un solo sentido.","h2":"En Arizona usted puede dar vuelta a la izquierda con luz roja de una calle de un solo sentido a otra de un solo sentido que va a la izquierda, después de detenerse por completo y ceder el paso, a menos que un letrero lo prohíba.","p":"Correcto. Deténgase, ceda el paso y luego puede dar vuelta a la izquierda hacia la calle de un solo sentido."},"ref":{"doc":"AZ","page":null}},{"id":"az-034","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, a teen in the first six months of a graduated license breaks one of its limits for the first time. What happens to the limits?","o":["They last 30 days longer","They end right away","They become permanent","Nothing changes"],"h1":"The state gives the teen more time under the limits.","h2":"In Arizona a first violation of the graduated license limits adds 30 more days to those limits.","p":"Right. A first violation extends the limits by 30 days."},"es":{"q":"En Arizona, un adolescente en los primeros seis meses de su licencia graduada no cumple uno de sus límites por primera vez. ¿Qué pasa con los límites?","o":["Duran 30 días más","Terminan de inmediato","Se vuelven permanentes","No cambia nada"],"h1":"El estado le da al adolescente más tiempo con los límites.","h2":"En Arizona una primera infracción de los límites de la licencia graduada agrega 30 días más a esos límites.","p":"Correcto. Una primera infracción alarga los límites por 30 días."},"ref":{"doc":"AZ","page":null}},{"id":"az-035","scope":"AZ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arizona, you are in a crash and someone is hurt. When must you tell the police?","o":["Within 10 days, in writing","Right away, by the fastest way you can","Only if the other driver asks you to","Only if a car must be towed"],"h1":"An injured person needs help quickly.","h2":"In Arizona, after a crash where someone is hurt or killed, you must tell the police right away by the fastest means you have.","p":"Right. Report an injury crash to the police right away."},"es":{"q":"En Arizona, usted tiene un choque y alguien resulta herido. ¿Cuándo debe avisar a la policía?","o":["Dentro de 10 días, por escrito","De inmediato, por el medio más rápido que pueda","Solo si el otro conductor se lo pide","Solo si hay que remolcar un carro"],"h1":"Una persona herida necesita ayuda rápido.","h2":"En Arizona, después de un choque donde alguien resulta herido o muerto, usted debe avisar a la policía de inmediato por el medio más rápido que tenga.","p":"Correcto. Avise a la policía de inmediato si hay heridos."},"ref":{"doc":"AZ","page":null}},{"id":"az-036","scope":"AZ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arizona, a driver leaves the scene of a crash where someone was hurt, without stopping. What kind of crime is this?","o":["A parking violation","A civil ticket with a small fine","It is not a crime if the driver was not at fault","A felony"],"h1":"It is more serious than a misdemeanor.","h2":"In Arizona, leaving the scene of a crash where someone was hurt is a felony, and the license is revoked.","p":"Right. Leaving an injury crash is a felony."},"es":{"q":"En Arizona, un conductor se va del lugar de un choque donde alguien resultó herido, sin detenerse. ¿Qué tipo de delito es?","o":["Una infracción de estacionamiento","Una multa civil pequeña","No es delito si el conductor no tuvo la culpa","Un delito grave (felonía)"],"h1":"Es más serio que un delito menor.","h2":"En Arizona, irse del lugar de un choque donde alguien resultó herido es un delito grave (felonía), y se revoca la licencia.","p":"Correcto. Irse de un choque con heridos es un delito grave."},"ref":{"doc":"AZ","page":null}},{"id":"az-037","scope":"AZ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Arizona, after a crash with another driver, what must you give that driver?","o":["Only your phone number","Your insurance company's address only","Your name, address and vehicle registration number, and your license if asked","Nothing, until the police arrive"],"h1":"The other driver needs to know who you are and which car you were driving.","h2":"In Arizona, after a crash you must give your name, address and vehicle registration number, and show your driver license if asked.","p":"Right. Share your name, address and registration, and show your license if asked."},"es":{"q":"En Arizona, después de un choque con otro conductor, ¿qué debe darle a ese conductor?","o":["Solo su número de teléfono","Solo la dirección de su compañía de seguros","Su nombre, dirección y número de registro del vehículo, y su licencia si se la piden","Nada, hasta que llegue la policía"],"h1":"El otro conductor necesita saber quién es usted y qué carro manejaba.","h2":"En Arizona, después de un choque usted debe dar su nombre, dirección y número de registro del vehículo, y mostrar su licencia de manejo si se la piden.","p":"Correcto. Dé su nombre, dirección y registro, y muestre su licencia si se la piden."},"ref":{"doc":"AZ","page":null}},{"id":"az-038","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, a driver is convicted of aggressive driving. Which class must the driver complete?","o":["Traffic Survival School","A motorcycle safety course","A first aid class","No class is required"],"h1":"It is the same school required after running a red light.","h2":"In Arizona a driver convicted of aggressive driving must complete Traffic Survival School.","p":"Right. Aggressive driving means Traffic Survival School."},"es":{"q":"En Arizona, un conductor es declarado culpable de manejo agresivo. ¿Qué clase debe completar?","o":["La escuela de supervivencia en el tráfico (Traffic Survival School)","Un curso de seguridad en motocicleta","Una clase de primeros auxilios","No se requiere ninguna clase"],"h1":"Es la misma escuela que se requiere después de pasarse una luz roja.","h2":"En Arizona un conductor declarado culpable de manejo agresivo debe completar la escuela de supervivencia en el tráfico (Traffic Survival School).","p":"Correcto. El manejo agresivo lleva a la Traffic Survival School."},"ref":{"doc":"AZ","page":null}},{"id":"az-039","scope":"AZ","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arizona, a driver is convicted of reckless driving for the first time. For up to how long may the judge suspend the license?","o":["Up to 7 days","Up to 90 days","Up to 5 years","The judge may not suspend it"],"h1":"It is about three months.","h2":"In Arizona a judge may suspend a driver's license for up to 90 days for a first reckless driving conviction.","p":"Right. A first reckless driving conviction can bring a suspension of up to 90 days."},"es":{"q":"En Arizona, un conductor es declarado culpable de manejo imprudente por primera vez. ¿Por cuánto tiempo como máximo puede el juez suspender la licencia?","o":["Hasta 7 días","Hasta 90 días","Hasta 5 años","El juez no puede suspenderla"],"h1":"Son unos tres meses.","h2":"En Arizona un juez puede suspender la licencia hasta por 90 días por una primera condena de manejo imprudente.","p":"Correcto. Una primera condena de manejo imprudente puede traer una suspensión de hasta 90 días."},"ref":{"doc":"AZ","page":null}},{"id":"az-040","scope":"AZ","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Arizona, when does speeding become the crime of excessive speed, not just a civil ticket?","o":["At 1 mph over the posted limit","At 5 mph over the posted limit","At more than 20 mph over the posted limit","Only at more than 50 mph over the posted limit"],"h1":"It is a big number, but not as big as 50.","h2":"In Arizona, driving more than 20 mph over the posted speed limit is the crime of excessive speed.","p":"Right. More than 20 mph over the limit is a criminal offense."},"es":{"q":"En Arizona, ¿cuándo se convierte el exceso de velocidad en el delito de velocidad excesiva y no solo en una multa civil?","o":["A 1 mph sobre el límite indicado","A 5 mph sobre el límite indicado","A más de 20 mph sobre el límite indicado","Solo a más de 50 mph sobre el límite indicado"],"h1":"Es un número grande, pero no tanto como 50.","h2":"En Arizona, manejar a más de 20 mph sobre el límite de velocidad indicado es el delito de velocidad excesiva.","p":"Correcto. Más de 20 mph sobre el límite es un delito."},"ref":{"doc":"AZ","page":null}},{"id":"az-041","scope":"AZ","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Arizona, you drive slowly on a two-lane road where passing is unsafe. How many vehicles in a line behind you means you must pull into a turnout?","o":["2 or more","3 or more","5 or more","10 or more"],"h1":"It is more than a few, but fewer than ten.","h2":"In Arizona, if 5 or more vehicles are lined up behind your slow vehicle on a two-lane road, you must pull off at the nearest safe turnout to let them pass.","p":"Right. With 5 or more vehicles behind you, use a turnout."},"es":{"q":"En Arizona, usted maneja despacio en una carretera de dos carriles donde no es seguro rebasar. ¿Cuántos vehículos en fila detrás de usted lo obligan a salirse a un área de desvío?","o":["2 o más","3 o más","5 o más","10 o más"],"h1":"Son más que unos pocos, pero menos de diez.","h2":"En Arizona, si 5 o más vehículos van en fila detrás de su vehículo lento en una carretera de dos carriles, usted debe salirse en el área de desvío segura más cercana para dejarlos pasar.","p":"Correcto. Con 5 o más vehículos detrás, use un área de desvío."},"ref":{"doc":"AZ","page":null}},{"id":"az-042","scope":"AZ","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Arizona, you get a speeding ticket in a state highway work zone while workers are present. What happens to the penalty?","o":["It is cut in half","It stays the same","It is only a warning","You pay an extra amount equal to the fine, so it doubles"],"h1":"Workers' safety makes the penalty bigger.","h2":"In Arizona, speeding in a state highway work zone with workers present adds an extra charge equal to the fine, so the penalty doubles.","p":"Right. Speeding near workers doubles the penalty."},"es":{"q":"En Arizona, usted recibe una multa por exceso de velocidad en una zona de construcción de una carretera estatal mientras hay trabajadores presentes. ¿Qué pasa con la multa?","o":["Se reduce a la mitad","Queda igual","Es solo una advertencia","Paga un cargo extra igual a la multa, así que se duplica"],"h1":"La seguridad de los trabajadores hace que la multa sea mayor.","h2":"En Arizona, exceder la velocidad en una zona de construcción de una carretera estatal con trabajadores presentes agrega un cargo extra igual a la multa, así que la multa se duplica.","p":"Correcto. Exceder la velocidad cerca de trabajadores duplica la multa."},"ref":{"doc":"AZ","page":null}},{"id":"az-043","scope":"AZ","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Arizona, you are passing a bicycle going the same way. How much space must you leave?","o":["At least 1 foot","At least 3 feet","At least 10 feet","No set amount"],"h1":"It is about the length of a yardstick.","h2":"In Arizona you must leave at least 3 feet between your car and a bicycle you are passing.","p":"Right. Give a bicycle at least 3 feet when you pass."},"es":{"q":"En Arizona, usted rebasa a una bicicleta que va en la misma dirección. ¿Cuánto espacio debe dejar?","o":["Por lo menos 1 pie","Por lo menos 3 pies","Por lo menos 10 pies","No hay una cantidad fija"],"h1":"Es más o menos el largo de una regla de una yarda.","h2":"En Arizona usted debe dejar por lo menos 3 pies entre su carro y una bicicleta que está rebasando.","p":"Correcto. Deje por lo menos 3 pies al rebasar una bicicleta."},"ref":{"doc":"AZ","page":null}},{"id":"az-044","scope":"AZ","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Arizona, on a regular road with no bike path, how many bicycle riders may ride side by side?","o":["No more than two","No more than three","No more than four","As many as they want"],"h1":"Think of a pair.","h2":"In Arizona, bicycle riders on a roadway may not ride more than two side by side, except on paths set aside for bicycles.","p":"Right. Bicycle riders may ride no more than two side by side."},"es":{"q":"En Arizona, en una calle normal sin ciclovía, ¿cuántos ciclistas pueden ir uno al lado del otro?","o":["No más de dos","No más de tres","No más de cuatro","Todos los que quieran"],"h1":"Piense en una pareja.","h2":"En Arizona, los ciclistas en una calle no pueden ir más de dos uno al lado del otro, excepto en caminos reservados para bicicletas.","p":"Correcto. Los ciclistas pueden ir no más de dos uno al lado del otro."},"ref":{"doc":"AZ","page":null}},{"id":"az-045","scope":"AZ","cat":"signals","sign":null,"c":3,"en":{"q":"In Arizona, before you turn, how far ahead must you keep your turn signal on?","o":["At least 10 feet","At least 25 feet","At least 1,000 feet","At least the last 100 feet"],"h1":"It is about the length of six or seven cars.","h2":"In Arizona you must signal a turn for at least the last 100 feet before you turn.","p":"Right. Signal for at least the last 100 feet before turning."},"es":{"q":"En Arizona, antes de dar vuelta, ¿con cuánta anticipación debe tener puesta la direccional?","o":["Por lo menos 10 pies","Por lo menos 25 pies","Por lo menos 1,000 pies","Por lo menos los últimos 100 pies"],"h1":"Es más o menos el largo de seis o siete carros.","h2":"En Arizona usted debe señalar una vuelta durante por lo menos los últimos 100 pies antes de dar vuelta.","p":"Correcto. Señale por lo menos los últimos 100 pies antes de dar vuelta."},"ref":{"doc":"AZ","page":null}},{"id":"az-046","scope":"AZ","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Arizona, the lights at a railroad crossing are flashing. Where must you stop?","o":["Right on the tracks","Between 15 and 50 feet from the nearest rail","Between 100 and 200 feet from the nearest rail","Anywhere you can see the train"],"h1":"Not too close, but not too far to see.","h2":"In Arizona, when a railroad crossing signal warns of a train, you must stop between 15 and 50 feet from the nearest rail.","p":"Right. Stop 15 to 50 feet from the nearest rail."},"es":{"q":"En Arizona, las luces de un cruce de ferrocarril están parpadeando. ¿Dónde debe detenerse?","o":["Justo encima de las vías","Entre 15 y 50 pies del riel más cercano","Entre 100 y 200 pies del riel más cercano","En cualquier lugar donde pueda ver el tren"],"h1":"Ni muy cerca, ni tan lejos que no pueda ver.","h2":"En Arizona, cuando la señal de un cruce de ferrocarril avisa que viene un tren, usted debe detenerse entre 15 y 50 pies del riel más cercano.","p":"Correcto. Deténgase entre 15 y 50 pies del riel más cercano."},"ref":{"doc":"AZ","page":null}},{"id":"az-047","scope":"AZ","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Arizona, how close to a crosswalk at an intersection may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 20 feet","No closer than 100 feet"],"h1":"It is a little more than the length of a car.","h2":"In Arizona you may not park within 20 feet of a crosswalk at an intersection.","p":"Right. Park at least 20 feet from a crosswalk at an intersection."},"es":{"q":"En Arizona, ¿qué tan cerca de un cruce peatonal en una intersección puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 20 pies","No más cerca de 100 pies"],"h1":"Es un poco más que el largo de un carro.","h2":"En Arizona usted no puede estacionarse a menos de 20 pies de un cruce peatonal en una intersección.","p":"Correcto. Estaciónese por lo menos a 20 pies de un cruce peatonal en una intersección."},"ref":{"doc":"AZ","page":null}},{"id":"az-048","scope":"AZ","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Arizona, how close may you park before a stop sign at the side of the road?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 15 feet","No closer than 30 feet"],"h1":"Drivers coming up to the sign need to see it clearly.","h2":"In Arizona you may not park within 30 feet before a stop sign, yield sign, flashing beacon or traffic signal at the side of the road.","p":"Right. Park at least 30 feet before a stop sign."},"es":{"q":"En Arizona, ¿qué tan cerca puede estacionarse antes de un letrero de alto al lado del camino?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 15 pies","No más cerca de 30 pies"],"h1":"Los conductores que se acercan al letrero necesitan verlo bien.","h2":"En Arizona usted no puede estacionarse a menos de 30 pies antes de un letrero de alto, de ceda el paso, una luz intermitente o un semáforo al lado del camino.","p":"Correcto. Estaciónese por lo menos 30 pies antes de un letrero de alto."},"ref":{"doc":"AZ","page":null}},{"id":"az-049","scope":"AZ","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Arizona, how close to a railroad crossing may you park?","o":["No closer than 50 feet from the nearest rail","No closer than 10 feet from the nearest rail","No closer than 20 feet from the nearest rail","Anywhere, if you leave your flashers on"],"h1":"It is more than 20 feet.","h2":"In Arizona you may not park within 50 feet of the nearest rail of a railroad crossing.","p":"Right. Park at least 50 feet from the nearest rail."},"es":{"q":"En Arizona, ¿qué tan cerca de un cruce de ferrocarril puede estacionarse?","o":["No más cerca de 50 pies del riel más cercano","No más cerca de 10 pies del riel más cercano","No más cerca de 20 pies del riel más cercano","En cualquier lugar, si deja las luces intermitentes encendidas"],"h1":"Es más de 20 pies.","h2":"En Arizona usted no puede estacionarse a menos de 50 pies del riel más cercano de un cruce de ferrocarril.","p":"Correcto. Estaciónese por lo menos a 50 pies del riel más cercano."},"ref":{"doc":"AZ","page":null}},{"id":"az-050","scope":"AZ","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Arizona, you park along a curb. How close to the curb must your right wheels be?","o":["Within 6 feet","Within 18 inches","Within 3 feet","Touching the curb"],"h1":"It is a foot and a half.","h2":"In Arizona, when you park along a curb, your right wheels must be parallel to it and within 18 inches of it.","p":"Right. Park with your wheels within 18 inches of the curb."},"es":{"q":"En Arizona, usted se estaciona junto a la banqueta. ¿Qué tan cerca de la banqueta deben estar sus llantas derechas?","o":["A menos de 6 pies","A menos de 18 pulgadas","A menos de 3 pies","Tocando la banqueta"],"h1":"Es un pie y medio.","h2":"En Arizona, cuando se estaciona junto a la banqueta, sus llantas derechas deben estar paralelas a ella y a menos de 18 pulgadas.","p":"Correcto. Estaciónese con las llantas a menos de 18 pulgadas de la banqueta."},"ref":{"doc":"AZ","page":null}},{"id":"az-051","scope":"AZ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arizona, what is the fine for a first ticket for holding a phone while driving?","o":["$75 to $149","$10 to $25","$400 to $500","$1,000 to $2,000"],"h1":"It is under $150.","h2":"In Arizona the civil penalty for a first violation of the hands-free law is $75 to $149.","p":"Right. A first hands-free violation costs $75 to $149."},"es":{"q":"En Arizona, ¿cuál es la multa por una primera infracción por sostener el teléfono mientras maneja?","o":["De $75 a $149","De $10 a $25","De $400 a $500","De $1,000 a $2,000"],"h1":"Es menos de $150.","h2":"En Arizona la multa civil por una primera infracción de la ley de manos libres es de $75 a $149.","p":"Correcto. Una primera infracción de manos libres cuesta de $75 a $149."},"ref":{"doc":"AZ","page":null}},{"id":"az-052","scope":"AZ","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arizona, a driver is caught for the first time with no car insurance. What is the lowest penalty?","o":["A warning only","$50, with no effect on the license","$100 and one point","$500, and the license is suspended or restricted for 3 months"],"h1":"It costs hundreds of dollars and affects the license.","h2":"In Arizona a first violation for driving without insurance brings a penalty of at least $500 and a 3-month suspension or restriction of the license.","p":"Right. At least $500 and 3 months of suspension or restriction."},"es":{"q":"En Arizona, a un conductor lo detienen por primera vez sin seguro de auto. ¿Cuál es la multa más baja?","o":["Solo una advertencia","$50, sin efecto en la licencia","$100 y un punto","$500, y la licencia se suspende o se restringe por 3 meses"],"h1":"Cuesta cientos de dólares y afecta la licencia.","h2":"En Arizona una primera infracción por manejar sin seguro trae una multa de por lo menos $500 y la suspensión o restricción de la licencia por 3 meses.","p":"Correcto. Por lo menos $500 y 3 meses de suspensión o restricción."},"ref":{"doc":"AZ","page":null}},{"id":"az-053","scope":"AZ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arizona, may a passenger in a private car have an open can of beer?","o":["Yes, if the driver is sober","No, not anywhere in the passenger area","Yes, if they sit in the back seat","Yes, if the can is in a paper bag"],"h1":"The rule covers everyone in the car, not only the driver.","h2":"In Arizona no one may have an open container of alcohol in the passenger area of a car on a public road; it may go in the trunk.","p":"Right. Open alcohol may not be in the passenger area."},"es":{"q":"En Arizona, ¿puede un pasajero en un carro particular tener una lata de cerveza abierta?","o":["Sí, si el conductor está sobrio","No, en ninguna parte del área de pasajeros","Sí, si va en el asiento de atrás","Sí, si la lata está en una bolsa de papel"],"h1":"La regla aplica a todos en el carro, no solo al conductor.","h2":"En Arizona nadie puede tener un envase abierto de alcohol en el área de pasajeros de un carro en una vía pública; puede ir en la cajuela.","p":"Correcto. El alcohol abierto no puede estar en el área de pasajeros."},"ref":{"doc":"AZ","page":null}},{"id":"ca-001","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, what is the youngest age to get a provisional instruction permit?","o":["14 years old","15 years old","15 and a half years old","16 years old"],"h1":"It is half a year past a birthday, before you turn 16.","h2":"A California teen can get a provisional instruction permit at 15 and a half, so there is time to practice before the provisional license.","p":"Right. The California permit starts at 15 and a half."},"es":{"q":"En California, ¿cuál es la edad mínima para obtener un permiso de instrucción provisional?","o":["14 años","15 años","15 años y medio","16 años"],"h1":"Es medio año después de un cumpleaños, antes de cumplir 16.","h2":"En California, un adolescente puede obtener el permiso de instrucción provisional a los 15 años y medio, para tener tiempo de practicar antes de la licencia provisional.","p":"Correcto. El permiso en California empieza a los 15 años y medio."},"zh":{"q":"在 California，最小几岁可以拿到过渡学习驾照（provisional instruction permit）？","o":["14 岁","15 岁","15 岁半","16 岁"],"h1":"它是过了某个生日半年，在你满 16 岁以前。","h2":"California 的青少年 15 岁半就可以拿到过渡学习驾照，这样在拿过渡驾照前有时间练习。","p":"对。California 的学习驾照从 15 岁半开始。"},"vi":{"q":"Ở California, tuổi nhỏ nhất để có giấy phép học lái tạm thời (provisional instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","15 tuổi rưỡi","16 tuổi"],"h1":"Đó là nửa năm sau một ngày sinh nhật, trước khi bạn 16 tuổi.","h2":"Thiếu niên ở California có thể có giấy phép học lái tạm thời khi 15 tuổi rưỡi, để có thời gian tập lái trước khi có bằng lái tạm thời.","p":"Đúng. Giấy phép học lái ở California bắt đầu từ 15 tuổi rưỡi."},"tl":{"q":"Sa California, ano ang pinakabatang edad para makakuha ng provisional instruction permit?","o":["14 taong gulang","15 taong gulang","15 at kalahating taong gulang","16 taong gulang"],"h1":"Kalahating taon ito pagkatapos ng isang kaarawan, bago ka mag-16.","h2":"Ang isang tinedyer sa California ay makakakuha ng provisional instruction permit sa edad na 15 at kalahati, para may oras magsanay bago ang provisional license.","p":"Tama. Ang permit sa California ay nagsisimula sa 15 at kalahati."},"ar":{"q":"في California، ما أصغر عمر للحصول على تصريح التعلّم المؤقت (provisional instruction permit)؟","o":["14 سنة","15 سنة","15 سنة ونصف","16 سنة"],"h1":"هو نصف سنة بعد عيد ميلاد، قبل أن تبلغ 16.","h2":"يمكن للمراهق في California الحصول على تصريح التعلّم المؤقت في عمر 15 سنة ونصف، ليكون لديه وقت للتدريب قبل الرخصة المؤقتة.","p":"صحيح. يبدأ التصريح في California في عمر 15 سنة ونصف."},"ref":{"doc":"CA","page":3}},{"id":"ca-002","scope":"CA","cat":"licensing","sign":null,"c":1,"en":{"q":"In California, how many hours of supervised driving practice must a teen complete before a provisional license?","o":["30 hours","50 hours","40 hours","60 hours"],"h1":"It is a round number, more than forty.","h2":"A California teen must complete 50 hours of supervised practice before the provisional license, because new drivers need a lot of time behind the wheel.","p":"Right. California asks for 50 hours of supervised practice."},"es":{"q":"En California, ¿cuántas horas de práctica supervisada debe completar un adolescente antes de la licencia provisional?","o":["30 horas","50 horas","40 horas","60 horas"],"h1":"Es un número redondo, mayor que cuarenta.","h2":"Un adolescente en California debe completar 50 horas de práctica supervisada antes de la licencia provisional, porque un conductor nuevo necesita mucho tiempo al volante.","p":"Correcto. California pide 50 horas de práctica supervisada."},"zh":{"q":"在 California，青少年拿过渡驾照前，必须完成多少小时有人监督的驾驶练习？","o":["30 小时","50 小时","40 小时","60 小时"],"h1":"它是一个整数，比四十多。","h2":"California 的青少年拿过渡驾照前必须完成 50 小时有人监督的练习，因为新司机需要很多时间开车。","p":"对。California 要求 50 小时有人监督的练习。"},"vi":{"q":"Ở California, thiếu niên phải tập lái có người giám sát bao nhiêu giờ trước khi có bằng lái tạm thời (provisional license)?","o":["30 giờ","50 giờ","40 giờ","60 giờ"],"h1":"Đó là một số tròn, nhiều hơn bốn mươi.","h2":"Thiếu niên ở California phải tập lái có người giám sát 50 giờ trước khi có bằng lái tạm thời, vì người mới lái cần nhiều thời gian sau tay lái.","p":"Đúng. California yêu cầu 50 giờ tập lái có người giám sát."},"tl":{"q":"Sa California, ilang oras ng pagmamaneho na may gabay ang dapat tapusin ng isang tinedyer bago ang provisional license?","o":["30 oras","50 oras","40 oras","60 oras"],"h1":"Isa itong buong numero, higit sa apatnapu.","h2":"Ang isang tinedyer sa California ay dapat tumapos ng 50 oras ng pagsasanay na may gabay bago ang provisional license, dahil kailangan ng bagong drayber ng maraming oras sa manibela.","p":"Tama. Humihingi ang California ng 50 oras ng pagsasanay na may gabay."},"ar":{"q":"في California، كم ساعة من التدريب على القيادة تحت الإشراف يجب أن يكملها المراهق قبل الرخصة المؤقتة (provisional license)؟","o":["30 ساعة","50 ساعة","40 ساعة","60 ساعة"],"h1":"هو رقم مدوّر، أكثر من أربعين.","h2":"يجب على المراهق في California أن يكمل 50 ساعة من التدريب تحت الإشراف قبل الرخصة المؤقتة، لأن السائق الجديد يحتاج إلى وقت طويل خلف المقود.","p":"صحيح. تطلب California 50 ساعة من التدريب تحت الإشراف."},"ref":{"doc":"CA","page":3}},{"id":"ca-003","scope":"CA","cat":"licensing","sign":null,"c":0,"en":{"q":"In California, how many of a teen's supervised practice hours must be driven in darkness?","o":["At least 10 hours","At least 5 hours","At least 20 hours","At least 25 hours"],"h1":"It is one fifth of the total practice time.","h2":"At least 10 of the 50 practice hours must be in darkness, because night driving needs its own practice.","p":"Right. At least 10 practice hours must be at night."},"es":{"q":"En California, ¿cuántas de las horas de práctica supervisada del adolescente deben ser en la oscuridad?","o":["Por lo menos 10 horas","Por lo menos 5 horas","Por lo menos 20 horas","Por lo menos 25 horas"],"h1":"Es la quinta parte del tiempo total de práctica.","h2":"Por lo menos 10 de las 50 horas de práctica deben ser en la oscuridad, porque manejar de noche necesita su propia práctica.","p":"Correcto. Por lo menos 10 horas de práctica deben ser de noche."},"zh":{"q":"在 California，青少年有人监督的练习时间里，有多少小时必须在天黑时开？","o":["至少 10 小时","至少 5 小时","至少 20 小时","至少 25 小时"],"h1":"它是全部练习时间的五分之一。","h2":"50 小时练习里至少 10 小时必须在天黑时开，因为夜间开车需要单独练习。","p":"对。至少 10 小时练习必须在晚上。"},"vi":{"q":"Ở California, trong số giờ tập lái có người giám sát của thiếu niên, phải lái trong bóng tối bao nhiêu giờ?","o":["Ít nhất 10 giờ","Ít nhất 5 giờ","Ít nhất 20 giờ","Ít nhất 25 giờ"],"h1":"Đó là một phần năm tổng số giờ tập.","h2":"Ít nhất 10 trong 50 giờ tập lái phải là lái trong bóng tối, vì lái xe ban đêm cần được tập riêng.","p":"Đúng. Ít nhất 10 giờ tập lái phải là vào ban đêm."},"tl":{"q":"Sa California, ilan sa mga oras ng pagsasanay na may gabay ng isang tinedyer ang dapat gawin sa dilim?","o":["Hindi bababa sa 10 oras","Hindi bababa sa 5 oras","Hindi bababa sa 20 oras","Hindi bababa sa 25 oras"],"h1":"Ito ay ikalimang bahagi ng kabuuang oras ng pagsasanay.","h2":"Hindi bababa sa 10 sa 50 oras ng pagsasanay ang dapat gawin sa dilim, dahil kailangan ng sariling pagsasanay ang pagmamaneho sa gabi.","p":"Tama. Hindi bababa sa 10 oras ng pagsasanay ang dapat sa gabi."},"ar":{"q":"في California، كم ساعة من ساعات التدريب تحت الإشراف يجب أن تكون في الظلام؟","o":["10 ساعات على الأقل","5 ساعات على الأقل","20 ساعة على الأقل","25 ساعة على الأقل"],"h1":"هي خُمس مجموع ساعات التدريب.","h2":"يجب أن تكون 10 ساعات على الأقل من ساعات التدريب الـ 50 في الظلام، لأن القيادة في الليل تحتاج إلى تدريب خاص بها.","p":"صحيح. يجب أن تكون 10 ساعات تدريب على الأقل في الليل."},"ref":{"doc":"CA","page":3}},{"id":"ca-004","scope":"CA","cat":"licensing","sign":null,"c":3,"en":{"q":"In California, during the first year of a provisional license, when may the teen not drive without a qualified adult?","o":["From 9 p.m. to 6 a.m.","From 10 p.m. to 4 a.m.","From midnight to 6 a.m.","From 11 p.m. to 5 a.m."],"h1":"The limit starts one hour before midnight.","h2":"In the first year, a provisional driver may not drive between 11 p.m. and 5 a.m. without a qualified adult, unless an exception such as school or work applies.","p":"Right. The night limit runs from 11 p.m. to 5 a.m."},"es":{"q":"En California, durante el primer año de la licencia provisional, ¿en qué horario no puede manejar el adolescente sin un adulto calificado?","o":["De 9 p.m. a 6 a.m.","De 10 p.m. a 4 a.m.","De medianoche a 6 a.m.","De 11 p.m. a 5 a.m."],"h1":"El límite empieza una hora antes de la medianoche.","h2":"En el primer año, el conductor provisional no puede manejar entre las 11 p.m. y las 5 a.m. sin un adulto calificado, salvo excepciones como la escuela o el trabajo.","p":"Correcto. El límite nocturno va de las 11 p.m. a las 5 a.m."},"zh":{"q":"在 California，持过渡驾照的第一年，青少年在什么时间不能在没有合格成年人陪同时开车？","o":["晚上 9 点到早上 6 点","晚上 10 点到凌晨 4 点","午夜到早上 6 点","晚上 11 点到早上 5 点"],"h1":"这个限制在午夜前一小时开始。","h2":"在第一年，持过渡驾照的司机在晚上 11 点到早上 5 点之间，没有合格的成年人陪同不能开车，除非有上学或上班等例外情况。","p":"对。夜间限制是晚上 11 点到早上 5 点。"},"vi":{"q":"Ở California, trong năm đầu có bằng lái tạm thời, khi nào thiếu niên không được lái xe nếu không có người lớn đủ điều kiện đi cùng?","o":["Từ 9 giờ tối đến 6 giờ sáng","Từ 10 giờ tối đến 4 giờ sáng","Từ nửa đêm đến 6 giờ sáng","Từ 11 giờ tối đến 5 giờ sáng"],"h1":"Giới hạn bắt đầu một giờ trước nửa đêm.","h2":"Trong năm đầu, người có bằng lái tạm thời không được lái xe từ 11 giờ tối đến 5 giờ sáng nếu không có người lớn đủ điều kiện đi cùng, trừ khi có ngoại lệ như đi học hoặc đi làm.","p":"Đúng. Giới hạn ban đêm là từ 11 giờ tối đến 5 giờ sáng."},"tl":{"q":"Sa California, sa unang taon ng provisional license, kailan hindi puwedeng magmaneho ang tinedyer nang walang kasamang kwalipikadong adulto?","o":["Mula 9 p.m. hanggang 6 a.m.","Mula 10 p.m. hanggang 4 a.m.","Mula hatinggabi hanggang 6 a.m.","Mula 11 p.m. hanggang 5 a.m."],"h1":"Nagsisimula ang limitasyon isang oras bago maghatinggabi.","h2":"Sa unang taon, ang provisional driver ay hindi puwedeng magmaneho mula 11 p.m. hanggang 5 a.m. nang walang kwalipikadong adulto, maliban kung may eksepsiyon tulad ng paaralan o trabaho.","p":"Tama. Ang limitasyon sa gabi ay mula 11 p.m. hanggang 5 a.m."},"ar":{"q":"في California، في السنة الأولى من الرخصة المؤقتة، متى لا يجوز للمراهق أن يقود بدون شخص بالغ مؤهَّل؟","o":["من 9 مساءً إلى 6 صباحًا","من 10 مساءً إلى 4 صباحًا","من منتصف الليل إلى 6 صباحًا","من 11 مساءً إلى 5 صباحًا"],"h1":"يبدأ المنع قبل منتصف الليل بساعة.","h2":"في السنة الأولى، لا يجوز لصاحب الرخصة المؤقتة أن يقود بين 11 مساءً و5 صباحًا بدون شخص بالغ مؤهَّل، إلا في حالة استثناء مثل المدرسة أو العمل.","p":"صحيح. منع القيادة الليلية من 11 مساءً إلى 5 صباحًا."},"ref":{"doc":"CA","page":4}},{"id":"ca-005","scope":"CA","cat":"licensing","sign":null,"c":1,"en":{"q":"In California, during the first year of a provisional license, the teen may not carry passengers under what age without a qualified adult?","o":["Under 18","Under 20","Under 16","Under 25"],"h1":"The age is just below a new decade of life.","h2":"In the first year, a provisional driver may not carry passengers under 20 unless a qualified adult is in the car, because young passengers raise crash risk.","p":"Right. No passengers under 20 without a qualified adult in the first year."},"es":{"q":"En California, durante el primer año de la licencia provisional, ¿pasajeros menores de qué edad no puede llevar el adolescente sin un adulto calificado?","o":["Menores de 18","Menores de 20","Menores de 16","Menores de 25"],"h1":"La edad está justo antes de una nueva década de vida.","h2":"En el primer año, el conductor provisional no puede llevar pasajeros menores de 20 años sin un adulto calificado en el auto, porque los pasajeros jóvenes aumentan el riesgo de choque.","p":"Correcto. Nada de pasajeros menores de 20 sin un adulto calificado en el primer año."},"zh":{"q":"在 California，持过渡驾照的第一年，没有合格成年人陪同时，青少年不能载几岁以下的乘客？","o":["18 岁以下","20 岁以下","16 岁以下","25 岁以下"],"h1":"这个年龄正好在人生新的十年前面一点。","h2":"在第一年，除非车里有合格的成年人，持过渡驾照的司机不能载 20 岁以下的乘客，因为年轻乘客会提高车祸风险。","p":"对。第一年没有合格成年人陪同，不能载 20 岁以下的乘客。"},"vi":{"q":"Ở California, trong năm đầu có bằng lái tạm thời, thiếu niên không được chở hành khách dưới bao nhiêu tuổi nếu không có người lớn đủ điều kiện đi cùng?","o":["Dưới 18 tuổi","Dưới 20 tuổi","Dưới 16 tuổi","Dưới 25 tuổi"],"h1":"Số tuổi này ngay trước một thập niên mới của cuộc đời.","h2":"Trong năm đầu, người có bằng lái tạm thời không được chở hành khách dưới 20 tuổi trừ khi có người lớn đủ điều kiện trong xe, vì hành khách trẻ làm tăng nguy cơ tai nạn.","p":"Đúng. Trong năm đầu, không chở hành khách dưới 20 tuổi nếu không có người lớn đủ điều kiện."},"tl":{"q":"Sa California, sa unang taon ng provisional license, hindi puwedeng magsakay ang tinedyer ng mga pasaherong mas bata sa anong edad kung walang kwalipikadong adulto?","o":["Mas bata sa 18","Mas bata sa 20","Mas bata sa 16","Mas bata sa 25"],"h1":"Ang edad ay bago lang ng isang bagong dekada ng buhay.","h2":"Sa unang taon, ang provisional driver ay hindi puwedeng magsakay ng mga pasaherong mas bata sa 20 maliban kung may kwalipikadong adulto sa kotse, dahil pinapataas ng mga batang pasahero ang panganib ng banggaan.","p":"Tama. Walang pasaherong mas bata sa 20 nang walang kwalipikadong adulto sa unang taon."},"ar":{"q":"في California، في السنة الأولى من الرخصة المؤقتة، لا يجوز للمراهق أن ينقل ركّابًا تحت أي عمر بدون شخص بالغ مؤهَّل؟","o":["تحت 18 سنة","تحت 20 سنة","تحت 16 سنة","تحت 25 سنة"],"h1":"هذا العمر قبل بداية عقد جديد من العمر مباشرة.","h2":"في السنة الأولى، لا يجوز لصاحب الرخصة المؤقتة أن ينقل ركّابًا تحت 20 سنة إلا إذا كان معه في السيارة شخص بالغ مؤهَّل، لأن الركّاب الصغار يزيدون خطر الحوادث.","p":"صحيح. لا ركّاب تحت 20 سنة بدون شخص بالغ مؤهَّل في السنة الأولى."},"ref":{"doc":"CA","page":4}},{"id":"ca-006","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, a provisional driver in the first year may drive at night with which person?","o":["Any licensed driver age 18 or older","A friend who has had a license for one year","A licensed driver age 25 or older","Any passenger age 21 or older"],"h1":"The adult must be older than in many other states.","h2":"A provisional driver may drive at night or carry young passengers when a licensed parent or guardian, a licensed driver 25 or older, or a certified instructor is with them.","p":"Right. The adult must be a licensed driver 25 or older, a parent or guardian, or an instructor."},"es":{"q":"En California, ¿con qué persona puede manejar de noche un conductor provisional en su primer año?","o":["Cualquier conductor con licencia de 18 años o más","Un amigo que tiene licencia desde hace un año","Un conductor con licencia de 25 años o más","Cualquier pasajero de 21 años o más"],"h1":"El adulto debe ser mayor que en muchos otros estados.","h2":"Un conductor provisional puede manejar de noche o llevar pasajeros jóvenes si va con su padre, madre o tutor con licencia, un conductor con licencia de 25 años o más, o un instructor certificado.","p":"Correcto. El adulto debe ser un conductor con licencia de 25 años o más, un padre o tutor, o un instructor."},"zh":{"q":"在 California，持过渡驾照第一年的司机，和下面哪一个人一起时可以在晚上开车？","o":["任何 18 岁或以上、有驾照的司机","有驾照满一年的朋友","25 岁或以上、有驾照的司机","任何 21 岁或以上的乘客"],"h1":"这个成年人的年龄要求比很多其他州高。","h2":"当有驾照的父母或监护人、25 岁或以上有驾照的司机，或有证书的驾驶教练同车时，持过渡驾照的司机可以在晚上开车，或载年轻乘客。","p":"对。这个成年人必须是 25 岁或以上有驾照的司机、父母或监护人，或教练。"},"vi":{"q":"Ở California, người có bằng lái tạm thời trong năm đầu được lái xe ban đêm với người nào?","o":["Bất kỳ người có bằng lái nào từ 18 tuổi trở lên","Một người bạn đã có bằng lái một năm","Một người có bằng lái từ 25 tuổi trở lên","Bất kỳ hành khách nào từ 21 tuổi trở lên"],"h1":"Người lớn phải lớn tuổi hơn so với nhiều tiểu bang khác.","h2":"Người có bằng lái tạm thời được lái xe ban đêm hoặc chở hành khách trẻ khi có cha mẹ hoặc người giám hộ có bằng lái, một người có bằng lái từ 25 tuổi trở lên, hoặc một huấn luyện viên có chứng nhận đi cùng.","p":"Đúng. Người lớn phải là người có bằng lái từ 25 tuổi trở lên, cha mẹ hoặc người giám hộ, hoặc một huấn luyện viên."},"tl":{"q":"Sa California, kasama ang sinong tao puwedeng magmaneho sa gabi ang isang provisional driver sa unang taon?","o":["Sinumang may lisensya na edad 18 pataas","Isang kaibigang may lisensya nang isang taon","Isang drayber na may lisensya na edad 25 pataas","Sinumang pasahero na edad 21 pataas"],"h1":"Mas matanda ang adulto kaysa sa maraming ibang estado.","h2":"Ang provisional driver ay puwedeng magmaneho sa gabi o magsakay ng mga batang pasahero kapag kasama ang magulang o tagapag-alaga na may lisensya, isang drayber na may lisensya na edad 25 pataas, o isang sertipikadong instruktor.","p":"Tama. Ang adulto ay dapat drayber na may lisensya na 25 pataas, magulang o tagapag-alaga, o instruktor."},"ar":{"q":"في California، مع من يجوز لصاحب الرخصة المؤقتة في السنة الأولى أن يقود في الليل؟","o":["أي سائق مرخَّص عمره 18 سنة أو أكثر","صديق لديه رخصة منذ سنة واحدة","سائق مرخَّص عمره 25 سنة أو أكثر","أي راكب عمره 21 سنة أو أكثر"],"h1":"يجب أن يكون البالغ أكبر سنًّا مما في ولايات كثيرة أخرى.","h2":"يجوز لصاحب الرخصة المؤقتة أن يقود في الليل أو ينقل ركّابًا صغارًا إذا كان معه أحد الوالدين أو الوصي المرخَّص، أو سائق مرخَّص عمره 25 سنة أو أكثر، أو مدرّب معتمَد.","p":"صحيح. يجب أن يكون البالغ سائقًا مرخَّصًا عمره 25 سنة أو أكثر، أو أحد الوالدين أو الوصي، أو مدرّبًا."},"ref":{"doc":"CA","page":4}},{"id":"ca-007","scope":"CA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In California, may a driver under 18 talk on a phone with a hands-free device while driving?","o":["No, not even hands-free","Yes, if the phone is mounted","Yes, on the freeway only","Yes, if the call is short"],"h1":"The rule for young drivers is stricter than the rule for adults.","h2":"A California driver under 18 may not use a phone while driving, even hands-free, except to call for help in an emergency.","p":"Right. Drivers under 18 may not use a phone, even hands-free."},"es":{"q":"En California, ¿puede un conductor menor de 18 años hablar por teléfono con manos libres mientras maneja?","o":["No, ni siquiera con manos libres","Sí, si el teléfono está montado","Sí, solo en la autopista","Sí, si la llamada es corta"],"h1":"La regla para los conductores jóvenes es más estricta que para los adultos.","h2":"En California, un conductor menor de 18 años no puede usar el teléfono mientras maneja, ni siquiera con manos libres, salvo para pedir ayuda en una emergencia.","p":"Correcto. Los menores de 18 no pueden usar el teléfono, ni con manos libres."},"zh":{"q":"在 California，18 岁以下的司机开车时可以用免持设备打电话吗？","o":["不可以，免持也不行","可以，如果手机装在支架上","可以，只在高速公路上","可以，如果电话很短"],"h1":"对年轻司机的规定比对成年人更严。","h2":"California 18 岁以下的司机开车时不能用手机，即使是免持也不行，紧急情况下打电话求助除外。","p":"对。18 岁以下的司机不能用手机，免持也不行。"},"vi":{"q":"Ở California, người lái xe dưới 18 tuổi có được nói chuyện điện thoại bằng thiết bị rảnh tay khi lái xe không?","o":["Không, kể cả rảnh tay","Có, nếu điện thoại được gắn cố định","Có, chỉ trên xa lộ","Có, nếu cuộc gọi ngắn"],"h1":"Luật cho người lái trẻ nghiêm hơn luật cho người lớn.","h2":"Người lái xe dưới 18 tuổi ở California không được dùng điện thoại khi lái xe, kể cả rảnh tay, trừ khi gọi cấp cứu trong trường hợp khẩn cấp.","p":"Đúng. Người lái dưới 18 tuổi không được dùng điện thoại, kể cả rảnh tay."},"tl":{"q":"Sa California, puwede bang makipag-usap sa telepono gamit ang hands-free na device ang drayber na wala pang 18 habang nagmamaneho?","o":["Hindi, kahit hands-free","Oo, kung nakakabit ang telepono","Oo, sa freeway lang","Oo, kung maikli ang tawag"],"h1":"Mas mahigpit ang patakaran para sa mga batang drayber kaysa sa mga adulto.","h2":"Ang drayber sa California na wala pang 18 ay hindi puwedeng gumamit ng telepono habang nagmamaneho, kahit hands-free, maliban sa pagtawag ng tulong sa emergency.","p":"Tama. Ang mga drayber na wala pang 18 ay hindi puwedeng gumamit ng telepono, kahit hands-free."},"ar":{"q":"في California، هل يجوز للسائق تحت 18 سنة أن يتكلم في الهاتف بجهاز من غير استخدام اليدين أثناء القيادة؟","o":["لا، ولا حتى بدون استخدام اليدين","نعم، إذا كان الهاتف مثبّتًا","نعم، على الطريق السريع فقط","نعم، إذا كانت المكالمة قصيرة"],"h1":"القاعدة للسائقين الصغار أشدّ من القاعدة للبالغين.","h2":"لا يجوز للسائق في California تحت 18 سنة أن يستخدم الهاتف أثناء القيادة، ولا حتى بدون استخدام اليدين، إلا لطلب المساعدة في حالة طوارئ.","p":"صحيح. لا يجوز للسائقين تحت 18 سنة استخدام الهاتف، ولا حتى بدون استخدام اليدين."},"ref":{"doc":"CA","page":71}},{"id":"ca-008","scope":"CA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In California, when may a driver under 18 use a phone while driving?","o":["To answer a parent's call","To check a map at a red light","To send a short text","To call police, fire or a doctor in an emergency"],"h1":"Think of a call that could save a life.","h2":"A driver under 18 may use a phone only in an emergency, to reach police, the fire department or a health care provider.","p":"Right. Only an emergency call is allowed for drivers under 18."},"es":{"q":"En California, ¿cuándo puede un conductor menor de 18 años usar el teléfono mientras maneja?","o":["Para contestar una llamada de su padre","Para ver un mapa en un semáforo rojo","Para enviar un mensaje corto","Para llamar a la policía, los bomberos o un médico en una emergencia"],"h1":"Piense en una llamada que podría salvar una vida.","h2":"Un conductor menor de 18 años solo puede usar el teléfono en una emergencia, para comunicarse con la policía, los bomberos o un proveedor de salud.","p":"Correcto. Los menores de 18 solo pueden hacer llamadas de emergencia."},"zh":{"q":"在 California，18 岁以下的司机开车时什么时候可以用手机？","o":["接父母的电话","在红灯时看地图","发一条短的短信","紧急情况下打给警察、消防或医生"],"h1":"想一想可以救命的电话。","h2":"18 岁以下的司机只有在紧急情况下，为了联系警察、消防局或医疗人员，才可以用手机。","p":"对。18 岁以下的司机只可以打紧急电话。"},"vi":{"q":"Ở California, khi nào người lái xe dưới 18 tuổi được dùng điện thoại khi lái xe?","o":["Để trả lời cuộc gọi của cha mẹ","Để xem bản đồ khi dừng đèn đỏ","Để gửi một tin nhắn ngắn","Để gọi cảnh sát, cứu hỏa hoặc bác sĩ khi khẩn cấp"],"h1":"Hãy nghĩ đến một cuộc gọi có thể cứu một mạng người.","h2":"Người lái xe dưới 18 tuổi chỉ được dùng điện thoại khi khẩn cấp, để gọi cảnh sát, sở cứu hỏa hoặc nhân viên y tế.","p":"Đúng. Người lái dưới 18 tuổi chỉ được gọi khẩn cấp."},"tl":{"q":"Sa California, kailan puwedeng gumamit ng telepono ang drayber na wala pang 18 habang nagmamaneho?","o":["Para sagutin ang tawag ng magulang","Para tumingin ng mapa sa pulang ilaw","Para magpadala ng maikling text","Para tumawag sa pulis, bumbero o doktor sa emergency"],"h1":"Isipin ang tawag na puwedeng magligtas ng buhay.","h2":"Ang drayber na wala pang 18 ay puwedeng gumamit ng telepono sa emergency lang, para tumawag sa pulis, sa bumbero o sa health care provider.","p":"Tama. Tawag sa emergency lang ang puwede para sa mga drayber na wala pang 18."},"ar":{"q":"في California، متى يجوز للسائق تحت 18 سنة أن يستخدم الهاتف أثناء القيادة؟","o":["للرد على مكالمة من أحد الوالدين","للنظر في الخريطة عند الإشارة الحمراء","لإرسال رسالة قصيرة","للاتصال بالشرطة أو الإطفاء أو الطبيب في حالة طوارئ"],"h1":"فكّر في مكالمة يمكن أن تنقذ حياة.","h2":"يجوز للسائق تحت 18 سنة أن يستخدم الهاتف في حالة طوارئ فقط، للاتصال بالشرطة أو الإطفاء أو مقدّم رعاية صحية.","p":"صحيح. مكالمة الطوارئ فقط مسموحة للسائقين تحت 18 سنة."},"ref":{"doc":"CA","page":71}},{"id":"ca-009","scope":"CA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In California, a driver under 21 can lose their license with a blood alcohol level of what?","o":["0.05 percent or more","0.01 percent or more","0.08 percent or more","0.04 percent or more"],"h1":"It is the smallest amount a test can measure.","h2":"California has a zero tolerance rule: a driver under 21 with 0.01 percent or more is breaking the law and can lose the license for one year.","p":"Right. For drivers under 21, the limit is 0.01 percent."},"es":{"q":"En California, un conductor menor de 21 años puede perder la licencia con un nivel de alcohol en la sangre de, ¿cuánto?","o":["0.05 por ciento o más","0.01 por ciento o más","0.08 por ciento o más","0.04 por ciento o más"],"h1":"Es la cantidad más pequeña que una prueba puede medir.","h2":"California tiene una regla de tolerancia cero: un conductor menor de 21 años con 0.01 por ciento o más viola la ley y puede perder la licencia por un año.","p":"Correcto. Para menores de 21, el límite es 0.01 por ciento."},"zh":{"q":"在 California，21 岁以下的司机血液酒精浓度达到多少，可能会失去驾照？","o":["0.05% 或更高","0.01% 或更高","0.08% 或更高","0.04% 或更高"],"h1":"它是检测能测出的最小量。","h2":"California 有零容忍规定：21 岁以下的司机酒精浓度达到 0.01% 或更高就是违法，可能失去驾照一年。","p":"对。21 岁以下的司机，限制是 0.01%。"},"vi":{"q":"Ở California, người lái xe dưới 21 tuổi có thể bị mất bằng lái khi nồng độ cồn trong máu là bao nhiêu?","o":["0.05 phần trăm trở lên","0.01 phần trăm trở lên","0.08 phần trăm trở lên","0.04 phần trăm trở lên"],"h1":"Đó là lượng nhỏ nhất mà máy đo có thể đo được.","h2":"California có luật không khoan nhượng: người lái xe dưới 21 tuổi có nồng độ 0.01 phần trăm trở lên là vi phạm luật và có thể bị mất bằng lái một năm.","p":"Đúng. Với người lái dưới 21 tuổi, giới hạn là 0.01 phần trăm."},"tl":{"q":"Sa California, ang drayber na wala pang 21 ay puwedeng mawalan ng lisensya kung ang alkohol sa dugo ay ilan?","o":["0.05 porsiyento o higit pa","0.01 porsiyento o higit pa","0.08 porsiyento o higit pa","0.04 porsiyento o higit pa"],"h1":"Ito ang pinakamaliit na dami na kayang sukatin ng test.","h2":"May zero tolerance rule ang California: ang drayber na wala pang 21 na may 0.01 porsiyento o higit pa ay lumalabag sa batas at puwedeng mawalan ng lisensya nang isang taon.","p":"Tama. Para sa mga drayber na wala pang 21, ang limitasyon ay 0.01 porsiyento."},"ar":{"q":"في California، يمكن أن يفقد السائق تحت 21 سنة رخصته إذا كانت نسبة الكحول في الدم كم؟","o":["0.05 بالمئة أو أكثر","0.01 بالمئة أو أكثر","0.08 بالمئة أو أكثر","0.04 بالمئة أو أكثر"],"h1":"هي أصغر كمية يستطيع الفحص أن يقيسها.","h2":"في California قاعدة عدم التسامح: السائق تحت 21 سنة الذي عنده 0.01 بالمئة أو أكثر يخالف القانون ويمكن أن يفقد رخصته لمدة سنة.","p":"صحيح. للسائقين تحت 21 سنة، الحدّ هو 0.01 بالمئة."},"ref":{"doc":"CA","page":73}},{"id":"ca-010","scope":"CA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In California, a driver under 21 can be charged with a crime at what blood alcohol level, even below the adult limit?","o":["0.02 percent","0.03 percent","0.05 percent","0.07 percent"],"h1":"It is a little more than half of the adult limit of 0.08.","h2":"A California driver under 21 can be charged at 0.05 percent, which is lower than the 0.08 percent limit for adults.","p":"Right. Under 21, a charge can start at 0.05 percent."},"es":{"q":"En California, ¿con qué nivel de alcohol en la sangre se puede acusar de un delito a un conductor menor de 21 años, aunque esté por debajo del límite de adultos?","o":["0.02 por ciento","0.03 por ciento","0.05 por ciento","0.07 por ciento"],"h1":"Es un poco más de la mitad del límite de adultos de 0.08.","h2":"En California, a un conductor menor de 21 años se le puede acusar con 0.05 por ciento, que es menos que el límite de 0.08 por ciento para adultos.","p":"Correcto. Para menores de 21, la acusación puede empezar en 0.05 por ciento."},"zh":{"q":"在 California，21 岁以下的司机血液酒精浓度达到多少，即使低于成年人的限制，也可能被控犯罪？","o":["0.02%","0.03%","0.05%","0.07%"],"h1":"它比成年人 0.08 的限制的一半多一点。","h2":"California 21 岁以下的司机在 0.05% 时就可能被起诉，这比成年人 0.08% 的限制低。","p":"对。21 岁以下，0.05% 就可能被起诉。"},"vi":{"q":"Ở California, người lái xe dưới 21 tuổi có thể bị buộc tội hình sự ở nồng độ cồn trong máu nào, dù thấp hơn giới hạn của người lớn?","o":["0.02 phần trăm","0.03 phần trăm","0.05 phần trăm","0.07 phần trăm"],"h1":"Đó là hơn một nửa giới hạn 0.08 của người lớn một chút.","h2":"Người lái xe dưới 21 tuổi ở California có thể bị buộc tội ở mức 0.05 phần trăm, thấp hơn giới hạn 0.08 phần trăm của người lớn.","p":"Đúng. Dưới 21 tuổi, có thể bị buộc tội từ 0.05 phần trăm."},"tl":{"q":"Sa California, sa anong antas ng alkohol sa dugo puwedeng kasuhan ng krimen ang drayber na wala pang 21, kahit mas mababa sa limitasyon ng adulto?","o":["0.02 porsiyento","0.03 porsiyento","0.05 porsiyento","0.07 porsiyento"],"h1":"Medyo higit ito sa kalahati ng 0.08 na limitasyon ng adulto.","h2":"Ang drayber sa California na wala pang 21 ay puwedeng kasuhan sa 0.05 porsiyento, na mas mababa sa 0.08 porsiyento na limitasyon para sa mga adulto.","p":"Tama. Kung wala pang 21, puwedeng magsimula ang kaso sa 0.05 porsiyento."},"ar":{"q":"في California، عند أي نسبة كحول في الدم يمكن اتهام السائق تحت 21 سنة بجريمة، حتى لو كانت أقل من حدّ البالغين؟","o":["0.02 بالمئة","0.03 بالمئة","0.05 بالمئة","0.07 بالمئة"],"h1":"هي أكثر قليلًا من نصف حدّ البالغين 0.08.","h2":"يمكن اتهام السائق في California تحت 21 سنة عند 0.05 بالمئة، وهذا أقل من حدّ البالغين 0.08 بالمئة.","p":"صحيح. تحت 21 سنة، يمكن أن يبدأ الاتهام عند 0.05 بالمئة."},"ref":{"doc":"CA","page":75}},{"id":"ca-011","scope":"CA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In California, a school bus is stopped with red lights flashing on the other side of a highway with two or more lanes in each direction. What must you do?","o":["Stop until the lights turn off","Stop, then pass at 10 mph","Honk and pass slowly","You do not have to stop"],"h1":"The rule changes when the road is wide enough on each side.","h2":"On a divided or multiple-lane highway with two or more lanes each way, you do not have to stop for a school bus on the other side, but you should still drive with care.","p":"Right. Traffic on the other side of a multiple-lane highway does not have to stop."},"es":{"q":"En California, un autobús escolar está detenido con luces rojas intermitentes al otro lado de una carretera con dos o más carriles en cada dirección. ¿Qué debe hacer usted?","o":["Detenerse hasta que se apaguen las luces","Detenerse y luego pasar a 10 mph","Tocar la bocina y pasar despacio","No tiene que detenerse"],"h1":"La regla cambia cuando la carretera es bastante ancha de cada lado.","h2":"En una carretera dividida o de varios carriles, con dos o más carriles en cada dirección, usted no tiene que detenerse por un autobús escolar del otro lado, pero debe manejar con cuidado.","p":"Correcto. El tráfico del otro lado de una carretera de varios carriles no tiene que detenerse."},"zh":{"q":"在 California，一辆校车停在每个方向有两条或更多车道的公路对面，红灯在闪。你必须怎么做？","o":["停车，直到灯熄灭","停车，然后以 10 mph 开过去","按喇叭，慢慢开过去","你不必停车"],"h1":"当每一边的道路够宽时，规定就不一样。","h2":"在每个方向有两条或更多车道的分隔公路或多车道公路上，你不必为对面的校车停车，但仍然要小心开车。","p":"对。多车道公路对面的车不必停车。"},"vi":{"q":"Ở California, một xe buýt trường học đang dừng và nháy đèn đỏ ở phía bên kia của xa lộ có hai làn trở lên mỗi chiều. Bạn phải làm gì?","o":["Dừng lại cho đến khi đèn tắt","Dừng lại, rồi vượt qua với tốc độ 10 mph","Bấm còi và vượt qua chậm","Bạn không phải dừng lại"],"h1":"Luật thay đổi khi mỗi bên đường đủ rộng.","h2":"Trên xa lộ có dải phân cách hoặc nhiều làn với hai làn trở lên mỗi chiều, bạn không phải dừng lại cho xe buýt trường học ở phía bên kia, nhưng vẫn phải lái xe cẩn thận.","p":"Đúng. Xe ở phía bên kia của xa lộ nhiều làn không phải dừng lại."},"tl":{"q":"Sa California, may school bus na nakahinto at kumikislap ang pulang ilaw sa kabilang panig ng highway na may dalawa o higit pang lane sa bawat direksyon. Ano ang dapat mong gawin?","o":["Huminto hanggang mamatay ang mga ilaw","Huminto, saka lumampas sa 10 mph","Bumusina at lumampas nang dahan-dahan","Hindi mo kailangang huminto"],"h1":"Nagbabago ang patakaran kapag sapat ang lapad ng daan sa bawat panig.","h2":"Sa divided o multiple-lane na highway na may dalawa o higit pang lane bawat direksyon, hindi mo kailangang huminto para sa school bus sa kabilang panig, pero dapat ka pa ring magmaneho nang maingat.","p":"Tama. Ang trapiko sa kabilang panig ng multiple-lane na highway ay hindi kailangang huminto."},"ar":{"q":"في California، حافلة مدرسية متوقفة وأضواؤها الحمراء تومض على الجهة الأخرى من طريق سريع فيه حارتان أو أكثر في كل اتجاه. ماذا يجب أن تفعل؟","o":["تتوقف حتى تنطفئ الأضواء","تتوقف، ثم تمرّ بسرعة 10 mph","تطلق البوق وتمرّ ببطء","ليس عليك أن تتوقف"],"h1":"تتغير القاعدة عندما يكون الطريق عريضًا بما يكفي في كل جهة.","h2":"على طريق سريع مقسوم أو متعدد الحارات فيه حارتان أو أكثر في كل اتجاه، ليس عليك أن تتوقف لحافلة مدرسية على الجهة الأخرى، لكن يجب أن تقود بحذر.","p":"صحيح. السير على الجهة الأخرى من طريق متعدد الحارات ليس عليه أن يتوقف."},"ref":{"doc":"CA","page":51}},{"id":"ca-012","scope":"CA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In California, a school bus with flashing red lights is stopped across a two-lane road with one lane each way. You are coming toward it. What must you do?","o":["Stop and wait until the lights stop flashing","Slow down and pass with care","Keep going, since you are on the other side","Stop only if children are in the road"],"h1":"One lane each way is not wide enough for the exception.","h2":"On a road with only one lane in each direction, drivers from both directions must stop for a school bus with flashing red lights and wait until the lights turn off.","p":"Right. On a two-lane road, traffic from both directions must stop."},"es":{"q":"En California, un autobús escolar con luces rojas intermitentes está detenido en una carretera de dos carriles, uno en cada dirección. Usted viene hacia él. ¿Qué debe hacer?","o":["Detenerse y esperar hasta que las luces dejen de parpadear","Reducir la velocidad y pasar con cuidado","Seguir, porque usted está del otro lado","Detenerse solo si hay niños en la calle"],"h1":"Un carril en cada dirección no es suficiente para la excepción.","h2":"En una carretera con un solo carril en cada dirección, los conductores de ambos sentidos deben detenerse ante un autobús escolar con luces rojas intermitentes y esperar hasta que se apaguen.","p":"Correcto. En una carretera de dos carriles, el tráfico de ambos sentidos debe detenerse."},"zh":{"q":"在 California，一辆红灯在闪的校车停在每个方向只有一条车道的双车道道路对面。你正朝它开过去。你必须怎么做？","o":["停车，等到灯不再闪","减速，小心地开过去","继续开，因为你在对面","只有孩子在路上时才停车"],"h1":"每个方向一条车道，不够宽，不能用这个例外。","h2":"在每个方向只有一条车道的道路上，两个方向的司机都必须为红灯闪烁的校车停车，并等到灯熄灭。","p":"对。在双车道道路上，两个方向的车都必须停车。"},"vi":{"q":"Ở California, một xe buýt trường học nháy đèn đỏ đang dừng trên đường hai làn, mỗi chiều một làn. Bạn đang chạy về phía nó. Bạn phải làm gì?","o":["Dừng lại và chờ cho đến khi đèn ngừng nháy","Chạy chậm lại và vượt qua cẩn thận","Cứ chạy tiếp, vì bạn ở phía bên kia","Chỉ dừng lại nếu có trẻ em trên đường"],"h1":"Mỗi chiều một làn thì không đủ rộng để có ngoại lệ.","h2":"Trên đường chỉ có một làn mỗi chiều, xe từ cả hai chiều phải dừng lại khi xe buýt trường học nháy đèn đỏ và chờ cho đến khi đèn tắt.","p":"Đúng. Trên đường hai làn, xe từ cả hai chiều phải dừng lại."},"tl":{"q":"Sa California, may school bus na kumikislap ang pulang ilaw at nakahinto sa two-lane na daan na may isang lane bawat direksyon. Papalapit ka rito. Ano ang dapat mong gawin?","o":["Huminto at maghintay hanggang tumigil ang pagkislap ng mga ilaw","Bumagal at lumampas nang maingat","Tuloy lang, dahil nasa kabilang panig ka","Huminto lang kung may mga bata sa daan"],"h1":"Ang isang lane bawat direksyon ay hindi sapat ang lapad para sa eksepsiyon.","h2":"Sa daan na may isang lane lang sa bawat direksyon, ang mga drayber mula sa dalawang direksyon ay dapat huminto para sa school bus na kumikislap ang pulang ilaw at maghintay hanggang mamatay ang mga ilaw.","p":"Tama. Sa two-lane na daan, dapat huminto ang trapiko mula sa dalawang direksyon."},"ar":{"q":"في California، حافلة مدرسية أضواؤها الحمراء تومض ومتوقفة على طريق بحارتين، حارة واحدة في كل اتجاه. أنت قادم نحوها. ماذا يجب أن تفعل؟","o":["تتوقف وتنتظر حتى يتوقف وميض الأضواء","تخفّف السرعة وتمرّ بحذر","تستمر في السير لأنك على الجهة الأخرى","تتوقف فقط إذا كان هناك أطفال في الطريق"],"h1":"حارة واحدة في كل اتجاه ليست عريضة بما يكفي للاستثناء.","h2":"على طريق فيه حارة واحدة فقط في كل اتجاه، يجب على السائقين من الاتجاهين أن يتوقفوا لحافلة مدرسية أضواؤها الحمراء تومض، وأن ينتظروا حتى تنطفئ الأضواء.","p":"صحيح. على طريق بحارتين، يجب أن يتوقف السير من الاتجاهين."},"ref":{"doc":"CA","page":51}},{"id":"ca-013","scope":"CA","cat":"signals","sign":null,"c":1,"en":{"q":"In California, may you turn right at a steady red light?","o":["No, never at a red light","Yes, after a full stop, unless a sign says no","Yes, without stopping if no cars come","Only between 9 a.m. and 5 p.m."],"h1":"You must do one thing first, and a sign can forbid it.","h2":"In California you may turn right on a steady red light after a full stop, unless a sign forbids it, and you must yield to people walking and to close traffic.","p":"Right. Stop fully first, then turn right if no sign forbids it."},"es":{"q":"En California, ¿puede usted girar a la derecha con la luz roja fija?","o":["No, nunca con luz roja","Sí, después de detenerse por completo, si no hay un letrero que lo prohíba","Sí, sin detenerse si no vienen autos","Solo entre las 9 a.m. y las 5 p.m."],"h1":"Debe hacer algo primero, y un letrero puede prohibirlo.","h2":"En California usted puede girar a la derecha con la luz roja fija después de detenerse por completo, si no hay un letrero que lo prohíba, y debe ceder el paso a los peatones y al tráfico cercano.","p":"Correcto. Deténgase por completo y luego gire a la derecha si ningún letrero lo prohíbe."},"zh":{"q":"在 California，持续亮着红灯时，你可以右转吗？","o":["不可以，红灯时永远不可以","可以，完全停车后，除非有标志禁止","可以，没有车来就不用停车","只在早上 9 点到下午 5 点之间"],"h1":"你必须先做一件事，而且标志可以禁止它。","h2":"在 California，持续亮着红灯时，你完全停车后可以右转，除非有标志禁止，而且你必须让行人和很近的车先走。","p":"对。先完全停车，没有标志禁止就可以右转。"},"vi":{"q":"Ở California, bạn có được rẽ phải khi đèn đỏ sáng liên tục không?","o":["Không, không bao giờ khi đèn đỏ","Có, sau khi dừng hẳn, trừ khi có biển cấm","Có, không cần dừng nếu không có xe","Chỉ từ 9 giờ sáng đến 5 giờ chiều"],"h1":"Bạn phải làm một việc trước, và biển báo có thể cấm việc này.","h2":"Ở California bạn được rẽ phải khi đèn đỏ sáng liên tục sau khi dừng hẳn, trừ khi có biển cấm, và bạn phải nhường cho người đi bộ và xe đang đến gần.","p":"Đúng. Dừng hẳn trước, rồi rẽ phải nếu không có biển cấm."},"tl":{"q":"Sa California, puwede ka bang kumanan sa tuloy-tuloy na pulang ilaw?","o":["Hindi, hindi kailanman sa pulang ilaw","Oo, pagkatapos ng buong paghinto, maliban kung may karatulang nagbabawal","Oo, nang hindi humihinto kung walang kotse","Mula 9 a.m. hanggang 5 p.m. lang"],"h1":"May isang bagay kang dapat gawin muna, at puwede itong ipagbawal ng karatula.","h2":"Sa California puwede kang kumanan sa tuloy-tuloy na pulang ilaw pagkatapos ng buong paghinto, maliban kung may karatulang nagbabawal, at dapat kang magbigay-daan sa mga naglalakad at sa malapit na trapiko.","p":"Tama. Huminto nang buo muna, saka kumanan kung walang karatulang nagbabawal."},"ar":{"q":"في California، هل يجوز لك أن تنعطف يمينًا عند إشارة حمراء ثابتة؟","o":["لا، أبدًا عند الإشارة الحمراء","نعم، بعد توقف كامل، إلا إذا منعت ذلك لافتة","نعم، بدون توقف إذا لم تأتِ سيارات","فقط بين 9 صباحًا و5 مساءً"],"h1":"يجب أن تفعل شيئًا واحدًا أولًا، ويمكن أن تمنع ذلك لافتة.","h2":"في California يجوز لك أن تنعطف يمينًا عند إشارة حمراء ثابتة بعد توقف كامل، إلا إذا منعت ذلك لافتة، ويجب أن تعطي الأولوية للمشاة وللسيارات القريبة.","p":"صحيح. توقف توقفًا كاملًا أولًا، ثم انعطف يمينًا إذا لم تمنع ذلك لافتة."},"ref":{"doc":"CA","page":18}},{"id":"ca-014","scope":"CA","cat":"signals","sign":null,"c":2,"en":{"q":"In California, when may you turn left at a steady red light after stopping?","o":["From any street onto a two-way street","Never, left turns on red are banned","From a one-way street onto a one-way street","Only at a red arrow"],"h1":"Both streets must let traffic go only one way.","h2":"In California you may turn left on a steady red light only from a one-way street onto another one-way street, after a full stop and when no sign forbids it.","p":"Right. Left on red is allowed only from one-way to one-way."},"es":{"q":"En California, ¿cuándo puede usted girar a la izquierda con la luz roja fija después de detenerse?","o":["De cualquier calle a una calle de doble sentido","Nunca, los giros a la izquierda en rojo están prohibidos","De una calle de un solo sentido a otra de un solo sentido","Solo con una flecha roja"],"h1":"Las dos calles deben permitir el tráfico en un solo sentido.","h2":"En California usted puede girar a la izquierda con la luz roja fija solo de una calle de un solo sentido a otra de un solo sentido, después de detenerse por completo y si ningún letrero lo prohíbe.","p":"Correcto. A la izquierda en rojo solo de un sentido a un sentido."},"zh":{"q":"在 California，持续亮着红灯时，停车以后什么时候可以左转？","o":["从任何街道转进双向街道","从来不可以，禁止红灯左转","从单行道转进单行道","只在红色箭头时"],"h1":"两条街都必须只让车往一个方向开。","h2":"在 California，只有从单行道转进另一条单行道，完全停车后，而且没有标志禁止时，你才可以在持续红灯时左转。","p":"对。只有从单行道转进单行道，才可以红灯左转。"},"vi":{"q":"Ở California, khi nào bạn được rẽ trái khi đèn đỏ sáng liên tục sau khi dừng lại?","o":["Từ bất kỳ đường nào vào đường hai chiều","Không bao giờ, rẽ trái khi đèn đỏ bị cấm","Từ đường một chiều vào đường một chiều","Chỉ khi có mũi tên đỏ"],"h1":"Cả hai con đường đều chỉ cho xe đi một chiều.","h2":"Ở California bạn chỉ được rẽ trái khi đèn đỏ sáng liên tục từ đường một chiều vào một đường một chiều khác, sau khi dừng hẳn và khi không có biển cấm.","p":"Đúng. Rẽ trái khi đèn đỏ chỉ được phép từ đường một chiều vào đường một chiều."},"tl":{"q":"Sa California, kailan ka puwedeng kumaliwa sa tuloy-tuloy na pulang ilaw pagkatapos huminto?","o":["Mula sa kahit anong kalye papunta sa two-way na kalye","Hindi kailanman, bawal ang kaliwa sa pula","Mula sa one-way na kalye papunta sa one-way na kalye","Sa pulang arrow lang"],"h1":"Ang dalawang kalye ay dapat nagpapatakbo ng trapiko sa isang direksyon lang.","h2":"Sa California puwede kang kumaliwa sa tuloy-tuloy na pulang ilaw mula lang sa one-way na kalye papunta sa isa pang one-way na kalye, pagkatapos ng buong paghinto at kapag walang karatulang nagbabawal.","p":"Tama. Ang kaliwa sa pula ay puwede lang mula one-way papunta sa one-way."},"ar":{"q":"في California، متى يجوز لك أن تنعطف يسارًا عند إشارة حمراء ثابتة بعد التوقف؟","o":["من أي شارع إلى شارع باتجاهين","أبدًا، الانعطاف يسارًا عند الأحمر ممنوع","من شارع باتجاه واحد إلى شارع باتجاه واحد","فقط عند سهم أحمر"],"h1":"يجب أن يسمح الشارعان كلاهما بالسير في اتجاه واحد فقط.","h2":"في California يجوز لك أن تنعطف يسارًا عند إشارة حمراء ثابتة فقط من شارع باتجاه واحد إلى شارع آخر باتجاه واحد، بعد توقف كامل وإذا لم تمنع ذلك لافتة.","p":"صحيح. الانعطاف يسارًا عند الأحمر مسموح فقط من اتجاه واحد إلى اتجاه واحد."},"ref":{"doc":"CA","page":20}},{"id":"ca-015","scope":"CA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In California, what does a red-painted curb mean?","o":["Parking for up to 10 minutes","Loading for trucks only","Parking for people with disabilities","No stopping, standing or parking"],"h1":"Red is the strictest curb color.","h2":"A red curb in California means no stopping, standing or parking at all, except for a bus in a marked bus zone.","p":"Right. Red curb: no stopping, standing or parking."},"es":{"q":"En California, ¿qué significa una acera pintada de rojo?","o":["Estacionamiento hasta 10 minutos","Carga solo para camiones","Estacionamiento para personas con discapacidad","Prohibido detenerse, esperar o estacionarse"],"h1":"El rojo es el color de acera más estricto.","h2":"Una acera roja en California significa que no se puede detener, esperar ni estacionar, salvo un autobús en una zona marcada para autobuses.","p":"Correcto. Acera roja: prohibido detenerse, esperar o estacionarse."},"zh":{"q":"在 California，涂成红色的路缘是什么意思？","o":["最多停车 10 分钟","只给卡车装卸货","给残障人士停车","不能停车、不能临时停靠、不能泊车"],"h1":"红色是最严格的路缘颜色。","h2":"在 California，红色路缘的意思是完全不能停车、临时停靠或泊车，在标出的公车区里的公车除外。","p":"对。红色路缘：不能停车、临时停靠或泊车。"},"vi":{"q":"Ở California, lề đường sơn màu đỏ có nghĩa là gì?","o":["Đậu xe tối đa 10 phút","Chỉ dành cho xe tải bốc dỡ hàng","Chỗ đậu xe cho người khuyết tật","Không được dừng, đứng chờ hoặc đậu xe"],"h1":"Màu đỏ là màu lề đường nghiêm nhất.","h2":"Lề đường màu đỏ ở California có nghĩa là hoàn toàn không được dừng, đứng chờ hoặc đậu xe, trừ xe buýt ở trạm xe buýt có đánh dấu.","p":"Đúng. Lề đường đỏ: không dừng, không đứng chờ, không đậu xe."},"tl":{"q":"Sa California, ano ang ibig sabihin ng gilid ng daan (curb) na pininturahan ng pula?","o":["Paradahan nang hanggang 10 minuto","Para sa pagkarga ng trak lang","Paradahan para sa mga taong may kapansanan","Bawal huminto, tumigil o pumarada"],"h1":"Ang pula ang pinakamahigpit na kulay ng curb.","h2":"Ang pulang curb sa California ay nangangahulugang bawal talagang huminto, tumigil o pumarada, maliban sa bus sa may markang bus zone.","p":"Tama. Pulang curb: bawal huminto, tumigil o pumarada."},"ar":{"q":"في California، ماذا يعني حافّة الرصيف المدهونة باللون الأحمر؟","o":["الوقوف حتى 10 دقائق","لتحميل الشاحنات فقط","موقف للأشخاص ذوي الإعاقة","ممنوع التوقف أو الانتظار أو الوقوف"],"h1":"الأحمر هو أشدّ ألوان حافّة الرصيف.","h2":"حافّة الرصيف الحمراء في California تعني منع التوقف أو الانتظار أو الوقوف تمامًا، إلا للحافلة في موقف حافلات محدَّد.","p":"صحيح. الرصيف الأحمر: ممنوع التوقف أو الانتظار أو الوقوف."},"ref":{"doc":"CA","page":28}},{"id":"ca-016","scope":"CA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In California, what does a yellow-painted curb mean?","o":["Stop only to load or unload passengers or freight","Park for as long as you like","Emergency vehicles only","Parking for people with disabilities"],"h1":"Think of delivery trucks.","h2":"A yellow curb in California is a loading zone: you may stop only as long as needed to load or unload passengers or freight.","p":"Right. Yellow curb: stop only to load or unload."},"es":{"q":"En California, ¿qué significa una acera pintada de amarillo?","o":["Detenerse solo para subir o bajar pasajeros o carga","Estacionarse todo el tiempo que quiera","Solo vehículos de emergencia","Estacionamiento para personas con discapacidad"],"h1":"Piense en los camiones de reparto.","h2":"Una acera amarilla en California es una zona de carga: usted puede detenerse solo el tiempo necesario para subir o bajar pasajeros o carga.","p":"Correcto. Acera amarilla: deténgase solo para cargar o descargar."},"zh":{"q":"在 California，涂成黄色的路缘是什么意思？","o":["只能停下来上下乘客或装卸货物","想停多久就停多久","只给急救车辆","给残障人士停车"],"h1":"想一想送货卡车。","h2":"在 California，黄色路缘是装卸区：你只能停留上下乘客或装卸货物需要的时间。","p":"对。黄色路缘：只能停下来上下客或装卸货。"},"vi":{"q":"Ở California, lề đường sơn màu vàng có nghĩa là gì?","o":["Chỉ dừng để cho hành khách hoặc hàng hóa lên xuống","Đậu xe bao lâu cũng được","Chỉ dành cho xe khẩn cấp","Chỗ đậu xe cho người khuyết tật"],"h1":"Hãy nghĩ đến xe tải giao hàng.","h2":"Lề đường màu vàng ở California là khu bốc dỡ: bạn chỉ được dừng trong thời gian cần để cho hành khách hoặc hàng hóa lên xuống.","p":"Đúng. Lề đường vàng: chỉ dừng để bốc dỡ."},"tl":{"q":"Sa California, ano ang ibig sabihin ng curb na pininturahan ng dilaw?","o":["Huminto lang para magbaba o magsakay ng pasahero o kargamento","Pumarada nang gaano katagal mo gusto","Para sa mga sasakyang pang-emergency lang","Paradahan para sa mga taong may kapansanan"],"h1":"Isipin ang mga delivery truck.","h2":"Ang dilaw na curb sa California ay loading zone: puwede kang huminto lang hangga't kailangan para magsakay o magbaba ng pasahero o kargamento.","p":"Tama. Dilaw na curb: huminto lang para magkarga o magbaba."},"ar":{"q":"في California، ماذا يعني حافّة الرصيف المدهونة باللون الأصفر؟","o":["التوقف فقط لإنزال أو تحميل الركّاب أو البضائع","الوقوف طالما تريد","لسيارات الطوارئ فقط","موقف للأشخاص ذوي الإعاقة"],"h1":"فكّر في شاحنات التوصيل.","h2":"حافّة الرصيف الصفراء في California هي منطقة تحميل: يجوز لك أن تتوقف فقط الوقت اللازم لتحميل أو إنزال الركّاب أو البضائع.","p":"صحيح. الرصيف الأصفر: التوقف فقط للتحميل أو الإنزال."},"ref":{"doc":"CA","page":28}},{"id":"ca-017","scope":"CA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In California, what does a white-painted curb mean?","o":["Parking for people with disabilities","Stop only long enough to pick up or drop off passengers","Parking for a posted time limit","No stopping at any time"],"h1":"It is for very short stops with people, not cargo.","h2":"A white curb in California allows a stop only long enough to pick up or drop off passengers.","p":"Right. White curb: a short stop for passengers."},"es":{"q":"En California, ¿qué significa una acera pintada de blanco?","o":["Estacionamiento para personas con discapacidad","Detenerse solo para recoger o dejar pasajeros","Estacionamiento con límite de tiempo indicado","Prohibido detenerse en todo momento"],"h1":"Es para paradas muy cortas con personas, no con carga.","h2":"Una acera blanca en California permite detenerse solo el tiempo necesario para recoger o dejar pasajeros.","p":"Correcto. Acera blanca: parada corta para pasajeros."},"zh":{"q":"在 California，涂成白色的路缘是什么意思？","o":["给残障人士停车","只能停一下，接送乘客上下车","按标示的时间限制停车","任何时候都不能停车"],"h1":"它是给接送人的很短的停留，不是给货物的。","h2":"在 California，白色路缘只允许停留接送乘客上下车所需的时间。","p":"对。白色路缘：为乘客短暂停留。"},"vi":{"q":"Ở California, lề đường sơn màu trắng có nghĩa là gì?","o":["Chỗ đậu xe cho người khuyết tật","Chỉ dừng đủ lâu để đón hoặc trả hành khách","Đậu xe theo thời gian ghi trên biển","Không được dừng bất cứ lúc nào"],"h1":"Đó là để dừng rất ngắn với người, không phải hàng hóa.","h2":"Lề đường màu trắng ở California chỉ cho phép dừng đủ lâu để đón hoặc trả hành khách.","p":"Đúng. Lề đường trắng: dừng ngắn cho hành khách."},"tl":{"q":"Sa California, ano ang ibig sabihin ng curb na pininturahan ng puti?","o":["Paradahan para sa mga taong may kapansanan","Huminto lang nang sapat para magsundo o magbaba ng pasahero","Paradahan ayon sa nakasulat na oras","Bawal huminto kahit kailan"],"h1":"Para ito sa napakaikling paghinto na may tao, hindi kargamento.","h2":"Ang puting curb sa California ay pinapayagan lang ang paghinto nang sapat para magsundo o magbaba ng pasahero.","p":"Tama. Puting curb: maikling paghinto para sa pasahero."},"ar":{"q":"في California، ماذا يعني حافّة الرصيف المدهونة باللون الأبيض؟","o":["موقف للأشخاص ذوي الإعاقة","التوقف فقط وقتًا يكفي لأخذ الركّاب أو إنزالهم","الوقوف لمدة مكتوبة على لافتة","ممنوع التوقف في أي وقت"],"h1":"هو لتوقف قصير جدًا مع أشخاص، وليس بضائع.","h2":"حافّة الرصيف البيضاء في California تسمح بالتوقف فقط وقتًا يكفي لأخذ الركّاب أو إنزالهم.","p":"صحيح. الرصيف الأبيض: توقف قصير للركّاب."},"ref":{"doc":"CA","page":28}},{"id":"ca-018","scope":"CA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In California, what does a green-painted curb mean?","o":["No parking at any time","Loading for trucks only","Parking for a limited time shown on a sign or the curb","Parking for people with disabilities"],"h1":"Green lets you park, but not forever.","h2":"A green curb in California allows parking only for a limited time, which is posted on a nearby sign or painted on the curb.","p":"Right. Green curb: parking for a limited time."},"es":{"q":"En California, ¿qué significa una acera pintada de verde?","o":["Prohibido estacionarse en todo momento","Carga solo para camiones","Estacionamiento por tiempo limitado, indicado en un letrero o en la acera","Estacionamiento para personas con discapacidad"],"h1":"El verde le permite estacionarse, pero no para siempre.","h2":"Una acera verde en California permite estacionarse solo por un tiempo limitado, que aparece en un letrero cercano o pintado en la acera.","p":"Correcto. Acera verde: estacionamiento por tiempo limitado."},"zh":{"q":"在 California，涂成绿色的路缘是什么意思？","o":["任何时候都不能停车","只给卡车装卸货","在标志或路缘上写的有限时间内停车","给残障人士停车"],"h1":"绿色让你停车，但不能一直停。","h2":"在 California，绿色路缘只允许停车一段有限的时间，时间写在附近的标志上或涂在路缘上。","p":"对。绿色路缘：限时停车。"},"vi":{"q":"Ở California, lề đường sơn màu xanh lá có nghĩa là gì?","o":["Không được đậu xe bất cứ lúc nào","Chỉ dành cho xe tải bốc dỡ hàng","Đậu xe trong thời gian giới hạn ghi trên biển hoặc trên lề đường","Chỗ đậu xe cho người khuyết tật"],"h1":"Màu xanh lá cho bạn đậu xe, nhưng không phải mãi mãi.","h2":"Lề đường màu xanh lá ở California chỉ cho đậu xe trong thời gian giới hạn, được ghi trên biển gần đó hoặc sơn trên lề đường.","p":"Đúng. Lề đường xanh lá: đậu xe trong thời gian giới hạn."},"tl":{"q":"Sa California, ano ang ibig sabihin ng curb na pininturahan ng berde?","o":["Bawal pumarada kahit kailan","Para sa pagkarga ng trak lang","Paradahan sa limitadong oras na nakasulat sa karatula o sa curb","Paradahan para sa mga taong may kapansanan"],"h1":"Pinapayagan ka ng berde na pumarada, pero hindi habambuhay.","h2":"Ang berdeng curb sa California ay pinapayagan ang pagparada sa limitadong oras lang, na nakasulat sa malapit na karatula o nakapinta sa curb.","p":"Tama. Berdeng curb: paradahan sa limitadong oras."},"ar":{"q":"في California، ماذا يعني حافّة الرصيف المدهونة باللون الأخضر؟","o":["ممنوع الوقوف في أي وقت","لتحميل الشاحنات فقط","الوقوف لوقت محدود مكتوب على لافتة أو على الرصيف","موقف للأشخاص ذوي الإعاقة"],"h1":"الأخضر يسمح لك بالوقوف، لكن ليس إلى الأبد.","h2":"حافّة الرصيف الخضراء في California تسمح بالوقوف لوقت محدود فقط، مكتوب على لافتة قريبة أو مدهون على الرصيف.","p":"صحيح. الرصيف الأخضر: الوقوف لوقت محدود."},"ref":{"doc":"CA","page":28}},{"id":"ca-019","scope":"CA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In California, what does a blue-painted curb mean?","o":["Parking for electric cars only","Taxi stand only","Short stop to drop off mail","Parking only for people with a disability placard or plate"],"h1":"This color matches a well-known access symbol.","h2":"A blue curb in California is for people with disabilities, and the vehicle must show a disability placard or special license plate.","p":"Right. Blue curb: disability parking with a placard or plate."},"es":{"q":"En California, ¿qué significa una acera pintada de azul?","o":["Estacionamiento solo para autos eléctricos","Solo parada de taxis","Parada corta para dejar correo","Estacionamiento solo para personas con placa o letrero de discapacidad"],"h1":"Este color coincide con un símbolo conocido de accesibilidad.","h2":"Una acera azul en California es para personas con discapacidad, y el vehículo debe mostrar un letrero o una placa especial de discapacidad.","p":"Correcto. Acera azul: estacionamiento para personas con discapacidad, con letrero o placa."},"zh":{"q":"在 California，涂成蓝色的路缘是什么意思？","o":["只给电动车停车","只给出租车停靠","短暂停下来投寄邮件","只给有残障停车证或残障车牌的人停车"],"h1":"这个颜色和一个大家都知道的无障碍标志一样。","h2":"在 California，蓝色路缘是给残障人士的，车辆必须挂残障停车证或特殊车牌。","p":"对。蓝色路缘：有停车证或车牌的残障停车位。"},"vi":{"q":"Ở California, lề đường sơn màu xanh dương có nghĩa là gì?","o":["Chỉ cho xe điện đậu","Chỉ dành cho xe taxi","Dừng ngắn để gửi thư","Chỉ cho người có thẻ hoặc biển số xe người khuyết tật đậu"],"h1":"Màu này giống màu của một biểu tượng tiếp cận rất quen thuộc.","h2":"Lề đường màu xanh dương ở California dành cho người khuyết tật, và xe phải có thẻ người khuyết tật (disability placard) hoặc biển số đặc biệt.","p":"Đúng. Lề đường xanh dương: chỗ đậu cho người khuyết tật có thẻ hoặc biển số."},"tl":{"q":"Sa California, ano ang ibig sabihin ng curb na pininturahan ng asul?","o":["Paradahan para sa electric car lang","Para sa taxi lang","Maikling paghinto para maghulog ng sulat","Paradahan lang para sa may disability placard o plaka"],"h1":"Kapareho ng kulay na ito ang kilalang simbolo ng accessibility.","h2":"Ang asul na curb sa California ay para sa mga taong may kapansanan, at dapat magpakita ang sasakyan ng disability placard o espesyal na plaka.","p":"Tama. Asul na curb: paradahan para sa may kapansanan na may placard o plaka."},"ar":{"q":"في California، ماذا يعني حافّة الرصيف المدهونة باللون الأزرق؟","o":["موقف للسيارات الكهربائية فقط","موقف سيارات الأجرة فقط","توقف قصير لوضع البريد","موقف فقط لمن لديه بطاقة أو لوحة إعاقة"],"h1":"هذا اللون يطابق رمزًا معروفًا لتسهيل الوصول.","h2":"حافّة الرصيف الزرقاء في California هي للأشخاص ذوي الإعاقة، ويجب أن تُظهر السيارة بطاقة إعاقة (disability placard) أو لوحة أرقام خاصة.","p":"صحيح. الرصيف الأزرق: موقف ذوي الإعاقة مع بطاقة أو لوحة."},"ref":{"doc":"CA","page":28}},{"id":"ca-020","scope":"CA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In California, when must you turn on your headlights during the day?","o":["Only in tunnels","When your wipers are on all the time because of rain, snow or fog","Only on freeways","Only after 6 p.m."],"h1":"Think about what your windshield needs in bad weather.","h2":"California requires your low-beam headlights whenever rain, snow or fog makes you use your wipers.","p":"Right. Wipers on all the time means headlights on."},"es":{"q":"En California, ¿cuándo debe encender las luces delanteras durante el día?","o":["Solo en túneles","Cuando usa los limpiaparabrisas todo el tiempo por lluvia, nieve o niebla","Solo en autopistas","Solo después de las 6 p.m."],"h1":"Piense en lo que necesita su parabrisas con mal tiempo.","h2":"California exige las luces bajas cada vez que la lluvia, la nieve o la niebla le obligan a usar los limpiaparabrisas.","p":"Correcto. Limpiaparabrisas todo el tiempo significa luces encendidas."},"zh":{"q":"在 California，白天什么时候必须打开大灯？","o":["只在隧道里","因为下雨、下雪或有雾而一直开着雨刷时","只在高速公路上","只在下午 6 点以后"],"h1":"想一想坏天气时你的挡风玻璃需要什么。","h2":"只要雨、雪或雾让你需要用雨刷，California 就要求你打开近光灯。","p":"对。雨刷一直开着，就要开大灯。"},"vi":{"q":"Ở California, khi nào bạn phải bật đèn pha vào ban ngày?","o":["Chỉ trong đường hầm","Khi bạn phải bật cần gạt nước liên tục vì mưa, tuyết hoặc sương mù","Chỉ trên xa lộ","Chỉ sau 6 giờ chiều"],"h1":"Hãy nghĩ đến những gì kính chắn gió cần khi thời tiết xấu.","h2":"California yêu cầu bạn bật đèn pha chiếu gần bất cứ khi nào mưa, tuyết hoặc sương mù làm bạn phải dùng cần gạt nước.","p":"Đúng. Cần gạt nước bật liên tục thì đèn pha phải bật."},"tl":{"q":"Sa California, kailan mo dapat buksan ang headlights sa araw?","o":["Sa mga tunnel lang","Kapag laging nakabukas ang wipers dahil sa ulan, niyebe o hamog","Sa mga freeway lang","Pagkatapos ng 6 p.m. lang"],"h1":"Isipin kung ano ang kailangan ng windshield mo sa masamang panahon.","h2":"Hinihingi ng California na nakabukas ang low-beam headlights mo tuwing pinapagamit ka ng wipers dahil sa ulan, niyebe o hamog.","p":"Tama. Kapag laging nakabukas ang wipers, dapat nakabukas ang headlights."},"ar":{"q":"في California، متى يجب أن تشغّل المصابيح الأمامية في النهار؟","o":["في الأنفاق فقط","عندما تكون المسّاحات تعمل طوال الوقت بسبب المطر أو الثلج أو الضباب","على الطرق السريعة فقط","بعد 6 مساءً فقط"],"h1":"فكّر فيما يحتاجه زجاجك الأمامي في الطقس السيئ.","h2":"تطلب California تشغيل المصابيح الأمامية المنخفضة كلما جعلك المطر أو الثلج أو الضباب تستخدم المسّاحات.","p":"صحيح. المسّاحات تعمل طوال الوقت تعني أن المصابيح يجب أن تعمل."},"ref":{"doc":"CA","page":11}},{"id":"ca-021","scope":"CA","cat":"licensing","sign":null,"c":0,"en":{"q":"In California, since 2025, what is the minimum liability insurance for injury to one person?","o":["$30,000","$15,000","$50,000","$25,000"],"h1":"The old amount was doubled in 2025.","h2":"Since January 1, 2025, California requires at least $30,000 for injury to one person, $60,000 per crash, and $15,000 for property damage.","p":"Right. The minimum is now $30,000 per injured person."},"es":{"q":"En California, desde 2025, ¿cuál es el seguro de responsabilidad mínimo por lesiones a una persona?","o":["$30,000","$15,000","$50,000","$25,000"],"h1":"La cantidad anterior se duplicó en 2025.","h2":"Desde el 1 de enero de 2025, California exige por lo menos $30,000 por lesiones a una persona, $60,000 por choque y $15,000 por daños a la propiedad.","p":"Correcto. El mínimo ahora es $30,000 por persona lesionada."},"zh":{"q":"在 California，从 2025 年起，一个人受伤的最低责任保险是多少？","o":["$30,000","$15,000","$50,000","$25,000"],"h1":"原来的金额在 2025 年提高了一倍。","h2":"从 2025 年 1 月 1 日起，California 要求一个人受伤至少 $30,000，每次车祸至少 $60,000，财产损失至少 $15,000。","p":"对。现在每个受伤的人最低是 $30,000。"},"vi":{"q":"Ở California, từ năm 2025, mức bảo hiểm trách nhiệm tối thiểu cho thương tích của một người là bao nhiêu?","o":["$30,000","$15,000","$50,000","$25,000"],"h1":"Mức cũ được tăng gấp đôi vào năm 2025.","h2":"Từ ngày 1 tháng 1 năm 2025, California yêu cầu ít nhất $30,000 cho thương tích của một người, $60,000 cho mỗi tai nạn, và $15,000 cho thiệt hại tài sản.","p":"Đúng. Mức tối thiểu hiện nay là $30,000 cho mỗi người bị thương."},"tl":{"q":"Sa California, mula 2025, ano ang pinakamababang liability insurance para sa pinsala sa isang tao?","o":["$30,000","$15,000","$50,000","$25,000"],"h1":"Dinoble ang lumang halaga noong 2025.","h2":"Mula Enero 1, 2025, hinihingi ng California ang hindi bababa sa $30,000 para sa pinsala sa isang tao, $60,000 bawat banggaan, at $15,000 para sa pinsala sa ari-arian.","p":"Tama. Ang pinakamababa ngayon ay $30,000 bawat taong nasaktan."},"ar":{"q":"في California، منذ 2025، ما الحدّ الأدنى لتأمين المسؤولية عن إصابة شخص واحد؟","o":["$30,000","$15,000","$50,000","$25,000"],"h1":"تمّت مضاعفة المبلغ القديم في 2025.","h2":"منذ 1 يناير 2025، تطلب California على الأقل $30,000 لإصابة شخص واحد، و$60,000 لكل حادث، و$15,000 للأضرار بالممتلكات.","p":"صحيح. الحدّ الأدنى الآن $30,000 لكل شخص مصاب."},"ref":{"doc":"CA","page":76}},{"id":"ca-022","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, since 2025, what is the minimum liability insurance for property damage?","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"It is half of the amount required for injury to one person.","h2":"California requires at least $15,000 of coverage for damage to other people's property.","p":"Right. Property damage coverage must be at least $15,000."},"es":{"q":"En California, desde 2025, ¿cuál es el seguro de responsabilidad mínimo por daños a la propiedad?","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"Es la mitad de la cantidad exigida por lesiones a una persona.","h2":"California exige por lo menos $15,000 de cobertura por daños a la propiedad de otras personas.","p":"Correcto. La cobertura por daños a la propiedad debe ser de por lo menos $15,000."},"zh":{"q":"在 California，从 2025 年起，财产损失的最低责任保险是多少？","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"它是一个人受伤所需金额的一半。","h2":"California 要求对别人财产的损失至少要有 $15,000 的保险。","p":"对。财产损失保险至少要 $15,000。"},"vi":{"q":"Ở California, từ năm 2025, mức bảo hiểm trách nhiệm tối thiểu cho thiệt hại tài sản là bao nhiêu?","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"Đó là một nửa mức yêu cầu cho thương tích của một người.","h2":"California yêu cầu bảo hiểm ít nhất $15,000 cho thiệt hại tài sản của người khác.","p":"Đúng. Bảo hiểm thiệt hại tài sản phải ít nhất $15,000."},"tl":{"q":"Sa California, mula 2025, ano ang pinakamababang liability insurance para sa pinsala sa ari-arian?","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"Kalahati ito ng halagang kailangan para sa pinsala sa isang tao.","h2":"Hinihingi ng California ang hindi bababa sa $15,000 na coverage para sa pinsala sa ari-arian ng ibang tao.","p":"Tama. Ang coverage sa pinsala sa ari-arian ay dapat hindi bababa sa $15,000."},"ar":{"q":"في California، منذ 2025، ما الحدّ الأدنى لتأمين المسؤولية عن الأضرار بالممتلكات؟","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"هو نصف المبلغ المطلوب لإصابة شخص واحد.","h2":"تطلب California تغطية لا تقل عن $15,000 للأضرار بممتلكات الآخرين.","p":"صحيح. تغطية الأضرار بالممتلكات يجب ألا تقل عن $15,000."},"ref":{"doc":"CA","page":76}},{"id":"ca-023","scope":"CA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In California, how close to a fire hydrant may you park when the curb is not painted?","o":["No closer than 5 feet","No closer than 15 feet","No closer than 30 feet","No closer than 10 feet"],"h1":"Firefighters need room for their hoses and truck.","h2":"In California you must stay 15 feet away from a fire hydrant on either side, even when the curb is not painted red.","p":"Right. Park at least 15 feet from a hydrant."},"es":{"q":"En California, ¿a qué distancia de un hidrante puede estacionarse cuando la acera no está pintada?","o":["A no menos de 5 pies","A no menos de 15 pies","A no menos de 30 pies","A no menos de 10 pies"],"h1":"Los bomberos necesitan espacio para sus mangueras y su camión.","h2":"En California usted debe quedarse a 15 pies de un hidrante por cada lado, aunque la acera no esté pintada de rojo.","p":"Correcto. Estaciónese por lo menos a 15 pies de un hidrante."},"zh":{"q":"在 California，路缘没有涂颜色时，你可以在离消防栓多近的地方停车？","o":["不能少于 5 英尺","不能少于 15 英尺","不能少于 30 英尺","不能少于 10 英尺"],"h1":"消防员需要空间放水管和消防车。","h2":"在 California，即使路缘没有涂红色，你也必须在消防栓两边都离开 15 英尺。","p":"对。在离消防栓至少 15 英尺的地方停车。"},"vi":{"q":"Ở California, bạn được đậu xe gần trụ nước cứu hỏa đến mức nào khi lề đường không được sơn màu?","o":["Không gần hơn 5 feet","Không gần hơn 15 feet","Không gần hơn 30 feet","Không gần hơn 10 feet"],"h1":"Lính cứu hỏa cần chỗ cho vòi nước và xe cứu hỏa.","h2":"Ở California bạn phải cách trụ nước cứu hỏa 15 feet ở mỗi bên, kể cả khi lề đường không sơn màu đỏ.","p":"Đúng. Đậu xe cách trụ nước ít nhất 15 feet."},"tl":{"q":"Sa California, gaano kalapit sa fire hydrant ka puwedeng pumarada kapag walang pintura ang curb?","o":["Hindi mas malapit sa 5 feet","Hindi mas malapit sa 15 feet","Hindi mas malapit sa 30 feet","Hindi mas malapit sa 10 feet"],"h1":"Kailangan ng mga bumbero ng lugar para sa kanilang hose at trak.","h2":"Sa California dapat kang lumayo nang 15 feet sa fire hydrant sa magkabilang panig, kahit hindi pula ang pintura ng curb.","p":"Tama. Pumarada nang hindi bababa sa 15 feet mula sa hydrant."},"ar":{"q":"في California، كم يمكنك أن تقترب من صنبور إطفاء الحريق عند الوقوف إذا كانت حافّة الرصيف غير مدهونة؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 30 قدمًا","ليس أقرب من 10 أقدام"],"h1":"يحتاج رجال الإطفاء إلى مكان لخراطيمهم وشاحنتهم.","h2":"في California يجب أن تبتعد 15 قدمًا عن صنبور إطفاء الحريق من كل جهة، حتى لو لم تكن حافّة الرصيف مدهونة بالأحمر.","p":"صحيح. قف على بعد 15 قدمًا على الأقل من صنبور الإطفاء."},"ref":{"doc":"CA","page":28}},{"id":"ca-024","scope":"CA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In California, what is the highest speed limit on most highways, unless a sign shows a different limit?","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"Higher limits apply only where signs say so.","h2":"In California the general maximum is 65 mph; some freeways are posted at 70 mph, and you must follow the signs.","p":"Right. The general maximum is 65 mph unless a sign says 70."},"es":{"q":"En California, ¿cuál es el límite de velocidad más alto en la mayoría de las carreteras, si un letrero no indica otro?","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"Los límites más altos solo valen donde los letreros lo indican.","h2":"En California el máximo general es 65 mph; algunas autopistas tienen un letrero de 70 mph, y usted debe seguir los letreros.","p":"Correcto. El máximo general es 65 mph, salvo que un letrero diga 70."},"zh":{"q":"在 California，除非标志写着别的限速，大多数公路的最高限速是多少？","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"更高的限速只在有标志的地方适用。","h2":"在 California，一般的最高限速是 65 mph；有些高速公路标示为 70 mph，你必须按照标志开。","p":"对。除非标志写着 70，一般最高限速是 65 mph。"},"vi":{"q":"Ở California, tốc độ tối đa cao nhất trên hầu hết các xa lộ là bao nhiêu, trừ khi biển báo ghi tốc độ khác?","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"Tốc độ cao hơn chỉ áp dụng ở nơi có biển báo.","h2":"Ở California tốc độ tối đa chung là 65 mph; một số xa lộ có biển 70 mph, và bạn phải theo biển báo.","p":"Đúng. Tốc độ tối đa chung là 65 mph trừ khi biển báo ghi 70."},"tl":{"q":"Sa California, ano ang pinakamataas na speed limit sa karamihan ng mga highway, maliban kung iba ang nakasulat sa karatula?","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"Ang mas mataas na limitasyon ay may bisa lang kung saan may karatula.","h2":"Sa California ang pangkalahatang pinakamataas ay 65 mph; may ilang freeway na nakasulat na 70 mph, at dapat mong sundin ang mga karatula.","p":"Tama. Ang pangkalahatang pinakamataas ay 65 mph maliban kung 70 ang nasa karatula."},"ar":{"q":"في California، ما أعلى حدّ للسرعة على معظم الطرق السريعة، إلا إذا أظهرت لافتة حدًّا مختلفًا؟","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"الحدود الأعلى تُطبَّق فقط حيث تقول اللافتات ذلك.","h2":"في California الحدّ الأقصى العام هو 65 mph؛ بعض الطرق السريعة عليها لافتة 70 mph، ويجب أن تتبع اللافتات.","p":"صحيح. الحدّ الأقصى العام 65 mph إلا إذا قالت لافتة 70."},"ref":{"doc":"CA","page":67}},{"id":"ca-025","scope":"CA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In California, what is the speed limit on a two-lane undivided highway unless signs show otherwise?","o":["55 mph","45 mph","65 mph","50 mph"],"h1":"It is ten less than the general highway maximum.","h2":"On a two-lane undivided highway in California, the limit is 55 mph unless signs post a higher speed.","p":"Right. Two-lane undivided highways are 55 mph unless posted."},"es":{"q":"En California, ¿cuál es el límite de velocidad en una carretera de dos carriles sin división, si los letreros no indican otro?","o":["55 mph","45 mph","65 mph","50 mph"],"h1":"Es diez menos que el máximo general en carretera.","h2":"En una carretera de dos carriles sin división en California, el límite es 55 mph, salvo que los letreros indiquen una velocidad mayor.","p":"Correcto. En carreteras de dos carriles sin división el límite es 55 mph si no hay letrero."},"zh":{"q":"在 California，除非标志另有规定，没有分隔的双车道公路限速是多少？","o":["55 mph","45 mph","65 mph","50 mph"],"h1":"它比一般公路最高限速少十。","h2":"在 California 没有分隔的双车道公路上，除非标志标示更高的速度，限速是 55 mph。","p":"对。除非有标志，没有分隔的双车道公路限速是 55 mph。"},"vi":{"q":"Ở California, tốc độ tối đa trên xa lộ hai làn không có dải phân cách là bao nhiêu, trừ khi biển báo ghi khác?","o":["55 mph","45 mph","65 mph","50 mph"],"h1":"Nó thấp hơn mức tối đa chung của xa lộ mười đơn vị.","h2":"Trên xa lộ hai làn không có dải phân cách ở California, tốc độ tối đa là 55 mph trừ khi biển báo ghi tốc độ cao hơn.","p":"Đúng. Xa lộ hai làn không có dải phân cách là 55 mph trừ khi có biển báo."},"tl":{"q":"Sa California, ano ang speed limit sa two-lane na highway na walang divider, maliban kung iba ang nasa karatula?","o":["55 mph","45 mph","65 mph","50 mph"],"h1":"Sampu itong mas mababa sa pangkalahatang pinakamataas sa highway.","h2":"Sa two-lane na highway na walang divider sa California, ang limitasyon ay 55 mph maliban kung may karatulang nagsasabi ng mas mataas na bilis.","p":"Tama. Ang two-lane na highway na walang divider ay 55 mph maliban kung may karatula."},"ar":{"q":"في California، ما حدّ السرعة على طريق سريع بحارتين بدون فاصل في الوسط، إلا إذا أظهرت اللافتات غير ذلك؟","o":["55 mph","45 mph","65 mph","50 mph"],"h1":"هو أقل بعشرة من الحدّ الأقصى العام للطرق السريعة.","h2":"على طريق سريع بحارتين بدون فاصل في California، الحدّ هو 55 mph إلا إذا أظهرت اللافتات سرعة أعلى.","p":"صحيح. الطرق بحارتين بدون فاصل 55 mph إلا إذا وُجدت لافتة."},"ref":{"doc":"CA","page":67}},{"id":"ca-026","scope":"CA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In California, what is the speed limit in a residential district when no sign is posted?","o":["15 mph","35 mph","25 mph","30 mph"],"h1":"It is the same as the usual school zone limit.","h2":"Unless a sign shows another limit, the speed limit in a California residential or business district is 25 mph.","p":"Right. Residential districts are 25 mph unless posted."},"es":{"q":"En California, ¿cuál es el límite de velocidad en una zona residencial cuando no hay letrero?","o":["15 mph","35 mph","25 mph","30 mph"],"h1":"Es igual al límite usual de una zona escolar.","h2":"Si no hay un letrero con otro límite, la velocidad máxima en una zona residencial o comercial de California es 25 mph.","p":"Correcto. En zonas residenciales el límite es 25 mph si no hay letrero."},"zh":{"q":"在 California，没有标志时，住宅区的限速是多少？","o":["15 mph","35 mph","25 mph","30 mph"],"h1":"它和一般学校区的限速一样。","h2":"除非标志写着别的限速，California 住宅区或商业区的限速是 25 mph。","p":"对。除非有标志，住宅区限速是 25 mph。"},"vi":{"q":"Ở California, tốc độ tối đa trong khu dân cư là bao nhiêu khi không có biển báo?","o":["15 mph","35 mph","25 mph","30 mph"],"h1":"Nó bằng tốc độ thường gặp ở khu vực trường học.","h2":"Trừ khi biển báo ghi tốc độ khác, tốc độ tối đa trong khu dân cư hoặc khu thương mại ở California là 25 mph.","p":"Đúng. Khu dân cư là 25 mph trừ khi có biển báo."},"tl":{"q":"Sa California, ano ang speed limit sa residential na lugar kapag walang karatula?","o":["15 mph","35 mph","25 mph","30 mph"],"h1":"Pareho ito sa karaniwang limitasyon sa school zone.","h2":"Maliban kung iba ang nasa karatula, ang speed limit sa residential o business na lugar sa California ay 25 mph.","p":"Tama. Ang residential na lugar ay 25 mph maliban kung may karatula."},"ar":{"q":"في California، ما حدّ السرعة في منطقة سكنية عندما لا توجد لافتة؟","o":["15 mph","35 mph","25 mph","30 mph"],"h1":"هو نفس الحدّ المعتاد في منطقة المدرسة.","h2":"إلا إذا أظهرت لافتة حدًّا آخر، فحدّ السرعة في منطقة سكنية أو تجارية في California هو 25 mph.","p":"صحيح. المناطق السكنية 25 mph إلا إذا وُجدت لافتة."},"ref":{"doc":"CA","page":52}},{"id":"ca-027","scope":"CA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In California, what is the speed limit in an alley?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Alleys are narrow, so the limit is lower than in a neighborhood.","h2":"The speed limit in a California alley is 15 mph, because alleys are narrow and people and cars can appear suddenly.","p":"Right. Alleys have a 15 mph limit."},"es":{"q":"En California, ¿cuál es el límite de velocidad en un callejón?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Los callejones son angostos, así que el límite es menor que en un vecindario.","h2":"El límite de velocidad en un callejón de California es 15 mph, porque los callejones son angostos y pueden aparecer personas o autos de repente.","p":"Correcto. En los callejones el límite es 15 mph."},"zh":{"q":"在 California，小巷里的限速是多少？","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"小巷很窄，所以限速比住宅区低。","h2":"California 小巷的限速是 15 mph，因为小巷很窄，人和车可能会突然出现。","p":"对。小巷限速是 15 mph。"},"vi":{"q":"Ở California, tốc độ tối đa trong hẻm là bao nhiêu?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Hẻm thì hẹp, nên tốc độ thấp hơn trong khu dân cư.","h2":"Tốc độ tối đa trong hẻm ở California là 15 mph, vì hẻm hẹp và người hoặc xe có thể xuất hiện bất ngờ.","p":"Đúng. Trong hẻm, tốc độ tối đa là 15 mph."},"tl":{"q":"Sa California, ano ang speed limit sa eskinita (alley)?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Makitid ang mga eskinita, kaya mas mababa ang limitasyon kaysa sa kapitbahayan.","h2":"Ang speed limit sa eskinita sa California ay 15 mph, dahil makitid ang mga eskinita at biglang puwedeng sumulpot ang mga tao at kotse.","p":"Tama. Ang mga eskinita ay may 15 mph na limitasyon."},"ar":{"q":"في California، ما حدّ السرعة في الزقاق (alley)؟","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"الأزقّة ضيّقة، لذلك الحدّ أقل منه في الحيّ السكني.","h2":"حدّ السرعة في الزقاق في California هو 15 mph، لأن الأزقّة ضيّقة ويمكن أن يظهر الناس والسيارات فجأة.","p":"صحيح. حدّ السرعة في الأزقّة 15 mph."},"ref":{"doc":"CA","page":51}},{"id":"ca-028","scope":"CA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In California, the \"basic speed law\" means what?","o":["You may always drive at the posted limit","You may go 5 mph over the limit to pass","Only trucks must slow down in rain","You must never drive faster than is safe for conditions"],"h1":"Weather, traffic and the road all matter.","h2":"California's basic speed law says you must never drive faster than is safe for the weather, traffic and road, so you can get a ticket even below the posted limit.","p":"Right. Never drive faster than is safe for conditions."},"es":{"q":"En California, ¿qué significa la \"ley básica de velocidad\"?","o":["Que siempre puede manejar al límite indicado","Que puede ir 5 mph sobre el límite para rebasar","Que solo los camiones deben bajar la velocidad con lluvia","Que nunca debe manejar más rápido de lo seguro para las condiciones"],"h1":"El clima, el tráfico y el camino importan.","h2":"La ley básica de velocidad de California dice que nunca debe manejar más rápido de lo seguro para el clima, el tráfico y el camino, así que le pueden multar aunque vaya por debajo del límite indicado.","p":"Correcto. Nunca maneje más rápido de lo seguro para las condiciones."},"zh":{"q":"在 California，“基本速度法”（basic speed law）是什么意思？","o":["你总是可以按标示的限速开","超车时可以超速 5 mph","只有卡车下雨时要减速","你开车绝对不能快过当时条件下安全的速度"],"h1":"天气、车流和道路都有关系。","h2":"California 的基本速度法说，你开车绝对不能快过天气、车流和道路条件下安全的速度，所以即使低于标示的限速，你也可能被开罚单。","p":"对。绝对不要开得比当时条件下安全的速度快。"},"vi":{"q":"Ở California, \"luật tốc độ cơ bản\" (basic speed law) có nghĩa là gì?","o":["Bạn luôn được lái theo tốc độ ghi trên biển","Bạn được chạy quá tốc độ 5 mph để vượt","Chỉ xe tải phải chạy chậm khi trời mưa","Bạn không bao giờ được lái nhanh hơn mức an toàn theo hoàn cảnh"],"h1":"Thời tiết, giao thông và mặt đường đều quan trọng.","h2":"Luật tốc độ cơ bản của California nói rằng bạn không bao giờ được lái nhanh hơn mức an toàn theo thời tiết, giao thông và mặt đường, nên bạn có thể bị phạt dù chạy dưới tốc độ ghi trên biển.","p":"Đúng. Không bao giờ lái nhanh hơn mức an toàn theo hoàn cảnh."},"tl":{"q":"Sa California, ano ang ibig sabihin ng \"basic speed law\"?","o":["Puwede kang laging magmaneho sa nakasulat na limitasyon","Puwede kang lumampas nang 5 mph para mag-overtake","Ang mga trak lang ang dapat bumagal sa ulan","Hindi ka dapat magmaneho nang mas mabilis kaysa ligtas para sa kalagayan"],"h1":"Mahalaga ang panahon, trapiko at kalsada.","h2":"Sinasabi ng basic speed law ng California na hindi ka dapat magmaneho nang mas mabilis kaysa ligtas para sa panahon, trapiko at kalsada, kaya puwede kang ma-tiket kahit mas mababa sa nakasulat na limitasyon.","p":"Tama. Huwag magmaneho nang mas mabilis kaysa ligtas para sa kalagayan."},"ar":{"q":"في California، ماذا يعني \"قانون السرعة الأساسي\" (basic speed law)؟","o":["يجوز لك دائمًا أن تقود بالحدّ المكتوب","يجوز لك أن تزيد 5 mph عن الحدّ لتتجاوز","الشاحنات فقط يجب أن تخفّف السرعة في المطر","يجب ألا تقود أبدًا أسرع مما هو آمن حسب الظروف"],"h1":"الطقس وحركة السير والطريق كلها مهمة.","h2":"قانون السرعة الأساسي في California يقول إنه يجب ألا تقود أبدًا أسرع مما هو آمن حسب الطقس وحركة السير والطريق، لذلك يمكن أن تحصل على مخالفة حتى تحت الحدّ المكتوب.","p":"صحيح. لا تقد أبدًا أسرع مما هو آمن حسب الظروف."},"ref":{"doc":"CA","page":67}},{"id":"ca-029","scope":"CA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In California, since 2026, you approach any vehicle stopped on the side of the road with hazard lights on. What must you do?","o":["Move to a lane not next to it, or slow down if you cannot","Honk to warn the driver","Stop behind it until it leaves","Keep the same lane and speed"],"h1":"The rule now protects more than police cars and tow trucks.","h2":"Since January 1, 2026, California's move over law covers any stopped vehicle with hazard lights, so you must move away from its lane or slow down if you cannot change lanes safely.","p":"Right. Move over, or slow down if you cannot."},"es":{"q":"En California, desde 2026, usted se acerca a cualquier vehículo detenido al lado del camino con las luces de emergencia encendidas. ¿Qué debe hacer?","o":["Cambiarse a un carril que no esté junto a él, o reducir la velocidad si no puede","Tocar la bocina para avisar al conductor","Detenerse detrás hasta que se vaya","Seguir en el mismo carril y a la misma velocidad"],"h1":"La regla ahora protege a más que patrullas y grúas.","h2":"Desde el 1 de enero de 2026, la ley de California de cambiarse de carril cubre cualquier vehículo detenido con luces de emergencia, así que usted debe alejarse de su carril o reducir la velocidad si no puede cambiarse con seguridad.","p":"Correcto. Cámbiese de carril, o reduzca la velocidad si no puede."},"zh":{"q":"在 California，从 2026 年起，你接近任何停在路边、开着双闪灯的车辆。你必须怎么做？","o":["换到不在它旁边的车道，做不到就减速","按喇叭提醒司机","停在它后面，直到它离开","保持同一条车道和速度"],"h1":"这个规定现在保护的不只是警车和拖车。","h2":"从 2026 年 1 月 1 日起，California 的 move over 法保护任何开着双闪灯停着的车辆，所以你必须离开它旁边的车道，如果无法安全换道就要减速。","p":"对。换开一条车道，做不到就减速。"},"vi":{"q":"Ở California, từ năm 2026, bạn đến gần bất kỳ xe nào đang dừng bên lề đường và bật đèn khẩn cấp. Bạn phải làm gì?","o":["Chuyển sang làn không sát xe đó, hoặc chạy chậm lại nếu không chuyển được","Bấm còi để báo cho tài xế","Dừng phía sau xe đó cho đến khi nó đi","Giữ nguyên làn và tốc độ"],"h1":"Luật bây giờ bảo vệ nhiều hơn chỉ xe cảnh sát và xe kéo.","h2":"Từ ngày 1 tháng 1 năm 2026, luật nhường làn (move over law) của California áp dụng cho mọi xe đang dừng có bật đèn khẩn cấp, nên bạn phải chuyển ra xa làn của xe đó hoặc chạy chậm lại nếu không thể chuyển làn an toàn.","p":"Đúng. Chuyển làn, hoặc chạy chậm lại nếu không chuyển được."},"tl":{"q":"Sa California, mula 2026, papalapit ka sa kahit anong sasakyang nakahinto sa gilid ng daan na nakabukas ang hazard lights. Ano ang dapat mong gawin?","o":["Lumipat sa lane na hindi katabi nito, o bumagal kung hindi mo kaya","Bumusina para balaan ang drayber","Huminto sa likod nito hanggang umalis ito","Manatili sa parehong lane at bilis"],"h1":"Mas marami na ngayon ang pinoprotektahan ng patakaran kaysa sa mga kotse ng pulis at tow truck.","h2":"Mula Enero 1, 2026, sakop ng move over law ng California ang kahit anong nakahintong sasakyan na may hazard lights, kaya dapat kang lumayo sa lane nito o bumagal kung hindi ka ligtas na makalipat ng lane.","p":"Tama. Lumipat ng lane, o bumagal kung hindi mo kaya."},"ar":{"q":"في California، منذ 2026، تقترب من أي سيارة متوقفة على جانب الطريق وأضواء الخطر فيها تعمل. ماذا يجب أن تفعل؟","o":["انتقل إلى حارة غير ملاصقة لها، أو خفّف السرعة إذا لم تستطع","أطلق البوق لتنبيه السائق","توقف خلفها حتى تذهب","ابقَ في نفس الحارة وبنفس السرعة"],"h1":"القاعدة الآن تحمي أكثر من سيارات الشرطة وشاحنات السحب.","h2":"منذ 1 يناير 2026، يشمل قانون الابتعاد (move over law) في California أي سيارة متوقفة وأضواء الخطر فيها تعمل، لذلك يجب أن تبتعد عن حارتها أو تخفّف السرعة إذا لم تستطع تغيير الحارة بأمان.","p":"صحيح. ابتعد بتغيير الحارة، أو خفّف السرعة إذا لم تستطع."},"ref":{"doc":"CA","page":null}},{"id":"ca-030","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, how many tries do you get to pass the knowledge test before you must apply again?","o":["One try","Two tries","Three tries","Five tries"],"h1":"It is more than two and fewer than four.","h2":"California gives you three tries at the knowledge test on one application; after that you must apply and pay again.","p":"Right. You get three tries per application."},"es":{"q":"En California, ¿cuántos intentos tiene para aprobar el examen de conocimientos antes de tener que solicitar de nuevo?","o":["Un intento","Dos intentos","Tres intentos","Cinco intentos"],"h1":"Son más de dos y menos de cuatro.","h2":"California le da tres intentos para el examen de conocimientos con una solicitud; después tiene que solicitar y pagar de nuevo.","p":"Correcto. Tiene tres intentos por solicitud."},"zh":{"q":"在 California，笔试你有几次机会，用完以后必须重新申请？","o":["一次","两次","三次","五次"],"h1":"它比两次多，比四次少。","h2":"California 一次申请给你三次笔试机会；用完以后你必须重新申请并再付费。","p":"对。每次申请有三次机会。"},"vi":{"q":"Ở California, bạn có bao nhiêu lần thi để đậu bài thi lý thuyết trước khi phải nộp đơn lại?","o":["Một lần","Hai lần","Ba lần","Năm lần"],"h1":"Nhiều hơn hai và ít hơn bốn.","h2":"California cho bạn ba lần thi lý thuyết cho mỗi đơn; sau đó bạn phải nộp đơn và trả phí lại.","p":"Đúng. Bạn có ba lần thi cho mỗi đơn."},"tl":{"q":"Sa California, ilang subok ang mayroon ka para pumasa sa knowledge test bago ka dapat mag-apply ulit?","o":["Isang subok","Dalawang subok","Tatlong subok","Limang subok"],"h1":"Higit ito sa dalawa at kulang sa apat.","h2":"Binibigyan ka ng California ng tatlong subok sa knowledge test sa isang application; pagkatapos noon, dapat kang mag-apply at magbayad ulit.","p":"Tama. May tatlong subok ka bawat application."},"ar":{"q":"في California، كم محاولة لديك لتنجح في الامتحان النظري قبل أن تقدّم طلبًا جديدًا؟","o":["محاولة واحدة","محاولتان","ثلاث محاولات","خمس محاولات"],"h1":"هو أكثر من اثنتين وأقل من أربع.","h2":"تعطيك California ثلاث محاولات في الامتحان النظري لكل طلب؛ بعد ذلك يجب أن تقدّم طلبًا جديدًا وتدفع مرة أخرى.","p":"صحيح. لديك ثلاث محاولات لكل طلب."},"ref":{"doc":"CA","page":5}},{"id":"ca-031","scope":"CA","cat":"licensing","sign":null,"c":0,"en":{"q":"In California, you move to a new home. How soon must you tell the DMV your new address?","o":["Within 10 days","Within 30 days","Within 60 days","At your next renewal"],"h1":"It is less than two weeks.","h2":"In California, you must give the DMV your new address within 10 days after you move.","p":"Right. Tell the DMV within 10 days of moving."},"es":{"q":"En California, usted se muda a una nueva casa. ¿En cuánto tiempo debe darle su nueva dirección al DMV?","o":["En 10 días","En 30 días","En 60 días","En su próxima renovación"],"h1":"Es menos de dos semanas.","h2":"En California, usted debe darle su nueva dirección al DMV dentro de los 10 días después de mudarse.","p":"Correcto. Avise al DMV dentro de 10 días después de mudarse."},"ref":{"doc":"CA","page":8}},{"id":"ca-032","scope":"CA","cat":"licensing","sign":null,"c":1,"en":{"q":"In California, what is the lowest number of points in 12 months that can get an adult's license suspended?","o":["1 point","4 points","8 points","12 points"],"h1":"It is less than the 6-point total used for a 24-month period.","h2":"In California, an adult with 4 points on their record in 12 months may have their license suspended.","p":"Right. 4 points in 12 months can lead to a suspension."},"es":{"q":"En California, ¿cuál es el número más bajo de puntos en 12 meses que puede causar la suspensión de la licencia de un adulto?","o":["1 punto","4 puntos","8 puntos","12 puntos"],"h1":"Es menos que el total de 6 puntos que se usa para un período de 24 meses.","h2":"En California, un adulto con 4 puntos en su historial en 12 meses puede perder su licencia por suspensión.","p":"Correcto. 4 puntos en 12 meses pueden causar una suspensión."},"ref":{"doc":"CA","page":54}},{"id":"ca-033","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, a teen in the first year of a provisional license gets two tickets or at-fault crashes. What happens?","o":["Nothing until age 18","The license is taken away for one year","For 30 days, the teen may drive only with a licensed adult 25 or older","The teen must retake only the vision test"],"h1":"The teen can still drive, but not alone.","h2":"In California, two tickets or at-fault crashes in the first year mean the teen may drive for 30 days only with a licensed adult age 25 or older.","p":"Right. For 30 days, a licensed adult 25 or older must ride along."},"es":{"q":"En California, un joven en el primer año de su licencia provisional recibe dos multas o tiene dos choques por su culpa. ¿Qué pasa?","o":["Nada hasta los 18 años","Le quitan la licencia por un año","Por 30 días solo puede manejar con un adulto con licencia de 25 años o más","Solo debe repetir el examen de la vista"],"h1":"El joven todavía puede manejar, pero no solo.","h2":"En California, dos multas o choques por su culpa en el primer año significan que el joven puede manejar por 30 días solo con un adulto con licencia de 25 años o más.","p":"Correcto. Por 30 días debe ir con un adulto con licencia de 25 años o más."},"ref":{"doc":"CA","page":55}},{"id":"ca-034","scope":"CA","cat":"licensing","sign":null,"c":3,"en":{"q":"In California, a provisional driver has three tickets or at-fault crashes in the first year. What happens to the license?","o":["A warning letter only","A 30-day limit on night driving","A one-week suspension","A six-month suspension and one year of probation"],"h1":"It is the strictest of these choices.","h2":"In California, three tickets or at-fault crashes in a provisional driver's first year bring a six-month suspension and one year of probation.","p":"Right. Six months of suspension, then one year of probation."},"es":{"q":"En California, un conductor provisional tiene tres multas o choques por su culpa en el primer año. ¿Qué pasa con la licencia?","o":["Solo una carta de advertencia","Un límite de 30 días para manejar de noche","Una suspensión de una semana","Una suspensión de seis meses y un año de libertad condicional"],"h1":"Es la opción más estricta.","h2":"En California, tres multas o choques por su culpa en el primer año de un conductor provisional causan una suspensión de seis meses y un año de libertad condicional.","p":"Correcto. Seis meses de suspensión y luego un año de libertad condicional."},"ref":{"doc":"CA","page":55}},{"id":"ca-035","scope":"CA","cat":"licensing","sign":null,"c":0,"en":{"q":"In California, an officer thinks you are driving under the influence and you refuse a blood or urine test. What does the DMV do?","o":["Suspends or revokes your license for one year","Gives you a warning the first time","Suspends your license for one week","Nothing, because the test is optional"],"h1":"Refusing the test is treated very seriously.","h2":"In California, if you refuse a chemical test when an officer suspects DUI, the DMV suspends or revokes your license for one year.","p":"Right. Refusing the test costs you your license for one year."},"es":{"q":"En California, un oficial cree que usted maneja bajo la influencia y usted se niega a una prueba de sangre u orina. ¿Qué hace el DMV?","o":["Suspende o revoca su licencia por un año","Le da una advertencia la primera vez","Suspende su licencia por una semana","Nada, porque la prueba es opcional"],"h1":"Negarse a la prueba es algo muy serio.","h2":"En California, si usted se niega a una prueba química cuando un oficial sospecha que maneja bajo la influencia, el DMV suspende o revoca su licencia por un año.","p":"Correcto. Negarse a la prueba le quita la licencia por un año."},"ref":{"doc":"CA","page":72}},{"id":"ca-036","scope":"CA","cat":"licensing","sign":null,"c":1,"en":{"q":"In California, after a DUI arrest, how soon must you ask for a DMV hearing?","o":["Within 24 hours","Within 10 days of the arrest","Within 6 months","Only after a court trial"],"h1":"It is a short window, well under a month.","h2":"In California, you may ask for a DMV administrative hearing within 10 days from the date of a DUI arrest.","p":"Right. Ask for the hearing within 10 days of the arrest."},"es":{"q":"En California, después de un arresto por manejar bajo la influencia, ¿en cuánto tiempo debe pedir una audiencia del DMV?","o":["En 24 horas","En 10 días desde el arresto","En 6 meses","Solo después de un juicio"],"h1":"Es un plazo corto, mucho menos de un mes.","h2":"En California, usted puede pedir una audiencia administrativa del DMV dentro de los 10 días desde la fecha del arresto por manejar bajo la influencia.","p":"Correcto. Pida la audiencia dentro de 10 días después del arresto."},"ref":{"doc":"CA","page":74}},{"id":"ca-037","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, you are in a crash and you do not have the required insurance. What can happen to your license?","o":["Nothing, if the crash was not your fault","A 10-day suspension","Suspension for up to four years","A fine only, with no suspension"],"h1":"It does not matter who caused the crash.","h2":"In California, driving without proper insurance and being in a crash can get your license suspended for up to four years, no matter who was at fault.","p":"Right. Up to four years of suspension, even if you were not at fault."},"es":{"q":"En California, usted tiene un choque y no tiene el seguro requerido. ¿Qué le puede pasar a su licencia?","o":["Nada, si el choque no fue su culpa","Una suspensión de 10 días","Una suspensión de hasta cuatro años","Solo una multa, sin suspensión"],"h1":"No importa quién causó el choque.","h2":"En California, manejar sin el seguro correcto y tener un choque puede causar la suspensión de su licencia hasta por cuatro años, sin importar quién tuvo la culpa.","p":"Correcto. Hasta cuatro años de suspensión, aunque no haya sido su culpa."},"ref":{"doc":"CA","page":76}},{"id":"ca-038","scope":"CA","cat":"licensing","sign":null,"c":3,"en":{"q":"In California, a crash causes more than $1,000 in damage. What must each driver do?","o":["Nothing, if police came to the scene","Call the DMV within one hour","Report it only to their insurance company","File a report (SR 1) with the DMV within 10 days"],"h1":"The police report does not count for you.","h2":"In California, each driver must file an SR 1 report with the DMV within 10 days when a crash causes more than $1,000 in damage or anyone is hurt.","p":"Right. File the SR 1 with the DMV within 10 days."},"es":{"q":"En California, un choque causa más de $1,000 en daños. ¿Qué debe hacer cada conductor?","o":["Nada, si la policía llegó al lugar","Llamar al DMV dentro de una hora","Avisar solo a su compañía de seguros","Enviar un reporte (SR 1) al DMV dentro de 10 días"],"h1":"El reporte de la policía no cuenta por usted.","h2":"En California, cada conductor debe enviar un reporte SR 1 al DMV dentro de 10 días cuando un choque causa más de $1,000 en daños o alguien sale herido.","p":"Correcto. Envíe el SR 1 al DMV dentro de 10 días."},"ref":{"doc":"CA","page":78}},{"id":"ca-039","scope":"CA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In California, a child is 6 years old and 4 feet tall. How must the child ride?","o":["In a child safety seat in the back seat","With a regular seat belt in the front seat","On an adult's lap with a seat belt","With a lap belt only, in any seat"],"h1":"Children under 8 or shorter than 4 feet 9 inches need more than a seat belt.","h2":"In California, a child under 8 years old, or shorter than 4 feet 9 inches, must ride in a child safety seat in the back seat.","p":"Right. Under 8 or under 4 feet 9 inches means a child seat in the back."},"es":{"q":"En California, un niño tiene 6 años y mide 4 pies. ¿Cómo debe viajar?","o":["En un asiento de seguridad para niños en el asiento trasero","Con un cinturón normal en el asiento delantero","En las piernas de un adulto con cinturón","Solo con el cinturón de cadera, en cualquier asiento"],"h1":"Los niños menores de 8 años o de menos de 4 pies 9 pulgadas necesitan más que un cinturón.","h2":"En California, un niño menor de 8 años, o que mide menos de 4 pies 9 pulgadas, debe viajar en un asiento de seguridad para niños en el asiento trasero.","p":"Correcto. Menor de 8 años o de menos de 4 pies 9 pulgadas: asiento para niños atrás."},"ref":{"doc":"CA","page":66}},{"id":"ca-040","scope":"CA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In California, a child is under 2 years old, under 40 pounds and under 3 feet 4 inches tall. How must the child ride?","o":["In a forward-facing booster seat","In a rear-facing child seat","With a regular seat belt","In a front seat with an airbag"],"h1":"The child faces the back of the car.","h2":"In California, a child under 2 who is under 40 pounds and under 3 feet 4 inches tall must ride in a rear-facing child seat.","p":"Right. Babies and toddlers this small ride rear-facing."},"es":{"q":"En California, un niño tiene menos de 2 años, pesa menos de 40 libras y mide menos de 3 pies 4 pulgadas. ¿Cómo debe viajar?","o":["En un asiento elevado mirando hacia adelante","En un asiento para niños mirando hacia atrás","Con un cinturón de seguridad normal","En un asiento delantero con bolsa de aire"],"h1":"El niño mira hacia la parte de atrás del carro.","h2":"En California, un niño menor de 2 años que pesa menos de 40 libras y mide menos de 3 pies 4 pulgadas debe viajar en un asiento para niños mirando hacia atrás.","p":"Correcto. Los niños tan pequeños viajan mirando hacia atrás."},"ref":{"doc":"CA","page":66}},{"id":"ca-041","scope":"CA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In California, a child of what age may not be left alone in a car?","o":["Only a baby under 1","Only a child under 3","A child 6 years old or younger","A child 10 years old or younger"],"h1":"The child may stay with someone age 12 or older.","h2":"In California, it is illegal to leave a child 6 years old or younger alone in a vehicle unless a person at least 12 years old is watching the child.","p":"Right. Never leave a child 6 or younger alone in the car."},"es":{"q":"En California, ¿a un niño de qué edad no se le puede dejar solo en un carro?","o":["Solo a un bebé menor de 1 año","Solo a un niño menor de 3 años","A un niño de 6 años o menos","A un niño de 10 años o menos"],"h1":"El niño puede quedarse con alguien de 12 años o más.","h2":"En California, es ilegal dejar solo en un vehículo a un niño de 6 años o menos, a menos que lo cuide una persona de por lo menos 12 años.","p":"Correcto. Nunca deje solo en el carro a un niño de 6 años o menos."},"ref":{"doc":"CA","page":67}},{"id":"ca-042","scope":"CA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In California, what is the rule about headsets or earplugs while driving?","o":["You may wear them in both ears at low volume","You may wear them only on the freeway","You may wear them only during the day","You may not wear them in both ears"],"h1":"You must be able to hear sirens and horns.","h2":"In California, it is illegal to drive while wearing a headset or earplugs in both ears.","p":"Right. Never cover both ears while you drive."},"es":{"q":"En California, ¿cuál es la regla sobre audífonos o tapones para los oídos al manejar?","o":["Puede usarlos en los dos oídos con volumen bajo","Puede usarlos solo en la autopista","Puede usarlos solo durante el día","No puede usarlos en los dos oídos"],"h1":"Usted debe poder oír sirenas y bocinas.","h2":"En California, es ilegal manejar con audífonos o tapones en los dos oídos.","p":"Correcto. Nunca se tape los dos oídos mientras maneja."},"ref":{"doc":"CA","page":9}},{"id":"ca-043","scope":"CA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In California, how close may you follow a fire engine or ambulance that has its siren or flashing lights on?","o":["No closer than 300 feet","No closer than 50 feet","No closer than 100 feet","As close as you like if traffic is light"],"h1":"It is about the length of a football field.","h2":"In California, it is against the law to follow within 300 feet of an emergency vehicle that has its siren or flashing lights on.","p":"Right. Stay at least 300 feet behind it."},"es":{"q":"En California, ¿qué tan cerca puede seguir a un camión de bomberos o una ambulancia con la sirena o las luces encendidas?","o":["A no menos de 300 pies","A no menos de 50 pies","A no menos de 100 pies","Tan cerca como quiera si hay poco tráfico"],"h1":"Es más o menos el largo de una cancha de fútbol americano.","h2":"En California, es ilegal seguir a menos de 300 pies a un vehículo de emergencia que tiene la sirena o las luces encendidas.","p":"Correcto. Quédese por lo menos a 300 pies detrás."},"ref":{"doc":"CA","page":45}},{"id":"ca-044","scope":"CA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In California, how far may you drive in a center left turn lane?","o":["Up to 50 feet","Up to 200 feet","Up to half a mile","As far as you need"],"h1":"It is not a lane for traveling or passing.","h2":"In California, you may drive no more than 200 feet in a center left turn lane before you turn.","p":"Right. Use it for at most 200 feet."},"es":{"q":"En California, ¿qué distancia puede manejar en un carril central para dar vuelta a la izquierda?","o":["Hasta 50 pies","Hasta 200 pies","Hasta media milla","Toda la que necesite"],"h1":"No es un carril para viajar ni para rebasar.","h2":"En California, usted puede manejar no más de 200 pies en un carril central para dar vuelta a la izquierda antes de dar la vuelta.","p":"Correcto. Úselo por 200 pies como máximo."},"ref":{"doc":"CA","page":16}},{"id":"ca-045","scope":"CA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In California, you are driving slowly on a two-lane road where passing is unsafe. When must you use a turnout to let cars pass?","o":["Whenever one car is behind you","Only at night","When five or more vehicles are following you","Only when a police officer tells you"],"h1":"Count the line of cars behind you.","h2":"In California, a slow driver on a two-lane road where passing is unsafe must use a turnout when five or more vehicles are following.","p":"Right. Five or more cars behind you means use the turnout."},"es":{"q":"En California, usted maneja despacio en una carretera de dos carriles donde no es seguro rebasar. ¿Cuándo debe usar un área de salida (turnout) para dejar pasar a otros?","o":["Siempre que haya un carro detrás","Solo de noche","Cuando lo siguen cinco vehículos o más","Solo cuando un policía se lo pide"],"h1":"Cuente la fila de carros detrás de usted.","h2":"En California, un conductor lento en una carretera de dos carriles donde no es seguro rebasar debe usar un área de salida cuando lo siguen cinco vehículos o más.","p":"Correcto. Con cinco carros o más detrás, use el área de salida."},"ref":{"doc":"CA","page":16}},{"id":"ca-046","scope":"CA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In California, you cannot change lanes to pass a bicycle. How much space must you leave?","o":["At least 1 foot","At least 18 inches","At least 2 feet","At least 3 feet"],"h1":"It is about one long step.","h2":"In California, when you pass a bicycle in the same lane, you must leave at least 3 feet, and you must wait if you cannot.","p":"Right. Give the bicycle at least 3 feet."},"es":{"q":"En California, usted no puede cambiar de carril para rebasar a una bicicleta. ¿Cuánto espacio debe dejar?","o":["Por lo menos 1 pie","Por lo menos 18 pulgadas","Por lo menos 2 pies","Por lo menos 3 pies"],"h1":"Es más o menos un paso largo.","h2":"En California, cuando rebasa a una bicicleta en el mismo carril, debe dejar por lo menos 3 pies, y si no puede, debe esperar.","p":"Correcto. Deje por lo menos 3 pies a la bicicleta."},"ref":{"doc":"CA","page":48}},{"id":"ca-047","scope":"CA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In California, how close to a crosswalk may you park, when there is no curb extension?","o":["No closer than 20 feet","No closer than 5 feet","No closer than 10 feet","Right up to the crosswalk lines"],"h1":"It is a few car lengths away, so people on foot can be seen.","h2":"In California, you may not park within 20 feet of a marked or unmarked crosswalk, or within 15 feet where there is a curb extension.","p":"Right. Park at least 20 feet from a crosswalk."},"es":{"q":"En California, ¿a qué distancia de un cruce peatonal puede estacionarse, cuando no hay una extensión de la acera?","o":["A no menos de 20 pies","A no menos de 5 pies","A no menos de 10 pies","Justo hasta las líneas del cruce"],"h1":"Son algunos largos de carro, para que se vea a los peatones.","h2":"En California, no puede estacionarse a menos de 20 pies de un cruce peatonal, marcado o no, ni a menos de 15 pies donde hay una extensión de la acera.","p":"Correcto. Estaciónese por lo menos a 20 pies de un cruce peatonal."},"ref":{"doc":"CA","page":28}},{"id":"ca-048","scope":"CA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In California, the signals at a railroad crossing warn that a train is coming. Where must you stop?","o":["Right on the edge of the tracks","At least 15 feet from the nearest track","At least 100 feet from the nearest track","Anywhere, as long as the gate is not down"],"h1":"Leave room so the train cannot hit your car.","h2":"In California, when a crossing warns of a train, you must stop at least 15 feet from the nearest track.","p":"Right. Stop at least 15 feet from the nearest track."},"es":{"q":"En California, las señales de un cruce de tren avisan que viene un tren. ¿Dónde debe detenerse?","o":["Justo en el borde de las vías","Por lo menos a 15 pies de la vía más cercana","Por lo menos a 100 pies de la vía más cercana","En cualquier lugar, si la barrera no está abajo"],"h1":"Deje espacio para que el tren no golpee su carro.","h2":"En California, cuando un cruce avisa que viene un tren, usted debe detenerse por lo menos a 15 pies de la vía más cercana.","p":"Correcto. Deténgase por lo menos a 15 pies de la vía más cercana."},"ref":{"doc":"CA","page":51}},{"id":"ca-049","scope":"CA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In California, what is the speed limit within 500 feet of a school while children are outside or crossing?","o":["15 mph in all cases","35 mph","25 mph, unless a lower limit is posted","45 mph"],"h1":"It is the same as the limit in a residential district.","h2":"In California, the speed limit is 25 mph within 500 feet of a school while children are outside or crossing, and some school zones post 15 mph.","p":"Right. 25 mph near a school when children are around."},"es":{"q":"En California, ¿cuál es el límite de velocidad a menos de 500 pies de una escuela cuando hay niños afuera o cruzando?","o":["15 mph en todos los casos","35 mph","25 mph, a menos que se indique un límite más bajo","45 mph"],"h1":"Es igual que el límite en una zona residencial.","h2":"En California, el límite es de 25 mph a menos de 500 pies de una escuela cuando hay niños afuera o cruzando, y en algunas zonas escolares el límite es de 15 mph.","p":"Correcto. 25 mph cerca de una escuela cuando hay niños."},"ref":{"doc":"CA","page":50}},{"id":"ca-050","scope":"CA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In California, what can happen if you do not stop for a school bus with flashing red lights?","o":["Only a warning","A $25 fine","A 30-day limit on passengers","A fine of up to $1,000 and a one-year suspension"],"h1":"The penalty is one of the largest on this list.","h2":"In California, failing to stop for a school bus with flashing red lights can bring a fine of up to $1,000 and a one-year suspension of your driving privilege.","p":"Right. Up to $1,000 and a one-year suspension."},"es":{"q":"En California, ¿qué puede pasar si no se detiene ante un autobús escolar con luces rojas intermitentes?","o":["Solo una advertencia","Una multa de $25","Un límite de pasajeros por 30 días","Una multa de hasta $1,000 y una suspensión de un año"],"h1":"Es uno de los castigos más grandes de esta lista.","h2":"En California, no detenerse ante un autobús escolar con luces rojas intermitentes puede costarle una multa de hasta $1,000 y la suspensión de su privilegio de manejar por un año.","p":"Correcto. Hasta $1,000 y una suspensión de un año."},"ref":{"doc":"CA","page":51}},{"id":"ca-051","scope":"CA","cat":"licensing","sign":null,"c":0,"en":{"q":"In California, a driver is 70 or older when the license expires. How must they renew it?","o":["In person, with a vision test","Online, with no tests","By mail, with a doctor's letter","They may not renew after age 70"],"h1":"They must visit the DMV and have their eyes checked.","h2":"In California, a driver who is 70 or older when the license expires must renew in person and pass a vision test.","p":"Right. Age 70 and up renews in person with a vision test."},"es":{"q":"En California, un conductor tiene 70 años o más cuando vence su licencia. ¿Cómo debe renovarla?","o":["En persona, con un examen de la vista","En línea, sin exámenes","Por correo, con una carta del médico","No puede renovarla después de los 70 años"],"h1":"Debe ir al DMV y hacerse revisar la vista.","h2":"En California, un conductor que tiene 70 años o más cuando vence su licencia debe renovarla en persona y pasar un examen de la vista.","p":"Correcto. A partir de los 70 años se renueva en persona con examen de la vista."},"ref":{"doc":"CA","page":82}},{"id":"co-001","scope":"CO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Colorado, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"You must first finish a 30-hour driver education course to start this early.","h2":"In Colorado you can get an instruction permit at 15 if you have completed an approved 30-hour driver education course.","p":"Right. A Colorado permit can start at 15, after driver education."},"es":{"q":"En Colorado, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["14 años","15 años","16 años","17 años"],"h1":"Primero debe terminar un curso de educación vial de 30 horas para empezar tan temprano.","h2":"En Colorado usted puede obtener un permiso de instrucción a los 15 años si completó un curso aprobado de educación vial de 30 horas.","p":"Correcto. El permiso en Colorado puede empezar a los 15, después de la educación vial."},"zh":{"q":"在 Colorado，最小几岁可以拿到学习驾照（instruction permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"要这么早开始，你必须先完成 30 小时的驾驶教育课程。","h2":"在 Colorado，如果你完成了认可的 30 小时驾驶教育课程，15 岁就可以拿到学习驾照。","p":"对。上完驾驶教育课以后，Colorado 的学习驾照可以从 15 岁开始。"},"vi":{"q":"Ở Colorado, tuổi nhỏ nhất để lấy giấy phép tập lái (instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Bạn phải học xong một khóa giáo dục lái xe 30 giờ trước thì mới được bắt đầu sớm như vậy.","h2":"Ở Colorado, bạn có thể lấy giấy phép tập lái khi 15 tuổi nếu đã học xong một khóa giáo dục lái xe 30 giờ được chấp thuận.","p":"Đúng. Ở Colorado, giấy phép tập lái có thể bắt đầu từ 15 tuổi, sau khóa giáo dục lái xe."},"tl":{"q":"Sa Colorado, ano ang pinakabatang edad para makakuha ng instruction permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Kailangan mo munang tapusin ang 30-oras na kurso sa driver education para makapagsimula nang ganito kaaga.","h2":"Sa Colorado, puwede kang kumuha ng instruction permit sa edad na 15 kung natapos mo na ang aprubadong 30-oras na kurso sa driver education.","p":"Tama. Puwedeng magsimula ang permit sa Colorado sa 15, pagkatapos ng driver education."},"ar":{"q":"في Colorado، ما أصغر عمر للحصول على تصريح التعلّم (instruction permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"يجب أن تُنهي أولًا دورة تعليم القيادة لمدة 30 ساعة لتبدأ بهذا العمر المبكر.","h2":"في Colorado يمكنك الحصول على تصريح التعلّم في عمر 15 سنة إذا أنهيت دورة معتمدة لتعليم القيادة مدتها 30 ساعة.","p":"صحيح. في Colorado يمكن أن يبدأ التصريح في عمر 15 سنة، بعد دورة تعليم القيادة."},"ref":{"doc":"CO","page":null}},{"id":"co-002","scope":"CO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Colorado, starting January 1, 2027, what must a new permit applicant aged 15 to 17 complete first?","o":["A 4-hour driver awareness class","A first aid course","Ten hours with a tutor","A 30-hour driver education course"],"h1":"It is the longer of the two courses that used to be allowed.","h2":"From January 1, 2027, Colorado requires applicants aged 15 to 17 to finish an approved 30-hour driver education course, online or in person, before they get a permit.","p":"Right. From 2027, teens need the 30-hour driver education course first."},"es":{"q":"En Colorado, a partir del 1 de enero de 2027, ¿qué debe completar primero quien solicita un permiso entre los 15 y los 17 años?","o":["Una clase de conciencia vial de 4 horas","Un curso de primeros auxilios","Diez horas con un tutor","Un curso de educación vial de 30 horas"],"h1":"Es el más largo de los dos cursos que antes se permitían.","h2":"Desde el 1 de enero de 2027, Colorado exige que los solicitantes de 15 a 17 años terminen un curso aprobado de educación vial de 30 horas, en línea o en persona, antes de recibir el permiso.","p":"Correcto. Desde 2027, los adolescentes necesitan primero el curso de 30 horas."},"zh":{"q":"在 Colorado，从 2027 年 1 月 1 日起，15 到 17 岁的新学习驾照申请人必须先完成什么？","o":["4 小时的驾驶意识课","急救课程","和家教上十小时课","30 小时的驾驶教育课程"],"h1":"它是以前允许的两种课程里比较长的那个。","h2":"从 2027 年 1 月 1 日起，Colorado 要求 15 到 17 岁的申请人在拿学习驾照前，先完成认可的 30 小时驾驶教育课程，网上或面授都可以。","p":"对。从 2027 年起，青少年要先上 30 小时的驾驶教育课程。"},"vi":{"q":"Ở Colorado, từ ngày 1 tháng 1 năm 2027, người xin giấy phép tập lái mới từ 15 đến 17 tuổi phải học xong gì trước?","o":["Một lớp nhận thức lái xe 4 giờ","Một khóa sơ cứu","Mười giờ học với gia sư","Một khóa giáo dục lái xe 30 giờ (driver education)"],"h1":"Đó là khóa dài hơn trong hai khóa trước đây được chấp nhận.","h2":"Từ ngày 1 tháng 1 năm 2027, Colorado yêu cầu người xin từ 15 đến 17 tuổi phải học xong một khóa giáo dục lái xe 30 giờ được chấp thuận, học trực tuyến hoặc trực tiếp, trước khi lấy giấy phép tập lái.","p":"Đúng. Từ năm 2027, thanh thiếu niên phải học khóa giáo dục lái xe 30 giờ trước."},"tl":{"q":"Sa Colorado, simula Enero 1, 2027, ano ang kailangang tapusin muna ng bagong aplikante para sa permit na 15 hanggang 17 taong gulang?","o":["Isang 4-oras na klase sa driver awareness","Isang kurso sa first aid","Sampung oras kasama ang isang tutor","Isang 30-oras na kurso sa driver education"],"h1":"Ito ang mas mahaba sa dalawang kursong dating pinapayagan.","h2":"Mula Enero 1, 2027, hinihingi ng Colorado na tapusin ng mga aplikanteng 15 hanggang 17 taong gulang ang aprubadong 30-oras na kurso sa driver education, online o personal, bago sila makakuha ng permit.","p":"Tama. Mula 2027, kailangan muna ng mga tinedyer ang 30-oras na kurso sa driver education."},"ar":{"q":"في Colorado، ابتداءً من 1 يناير 2027، ماذا يجب أن يُنهي أولًا المتقدّم الجديد للتصريح الذي عمره من 15 إلى 17 سنة؟","o":["درس توعية بالقيادة لمدة 4 ساعات","دورة إسعافات أولية","عشر ساعات مع مدرّس خاص","دورة تعليم القيادة لمدة 30 ساعة (driver education)"],"h1":"هي الأطول بين الدورتين اللتين كانتا مسموحتين من قبل.","h2":"ابتداءً من 1 يناير 2027، تطلب Colorado من المتقدّمين الذين أعمارهم من 15 إلى 17 سنة أن يُنهوا دورة معتمدة لتعليم القيادة مدتها 30 ساعة، عبر الإنترنت أو حضوريًا، قبل أن يحصلوا على التصريح.","p":"صحيح. ابتداءً من 2027، يحتاج المراهقون أولًا إلى دورة تعليم القيادة لمدة 30 ساعة."},"ref":{"doc":"CO","page":null}},{"id":"co-003","scope":"CO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Colorado, how long must a driver under 18 hold an instruction permit before getting a license?","o":["3 months","6 months","9 months","12 months"],"h1":"Think of one full year of practice.","h2":"A Colorado driver under 18 must hold the instruction permit for at least 12 months before getting a driver license, so there is a full year of practice.","p":"Right. Under 18, the permit must be held for 12 months."},"es":{"q":"En Colorado, ¿cuánto tiempo debe tener el permiso de instrucción un conductor menor de 18 años antes de obtener la licencia?","o":["3 meses","6 meses","9 meses","12 meses"],"h1":"Piense en un año completo de práctica.","h2":"En Colorado, un conductor menor de 18 años debe tener el permiso de instrucción por lo menos 12 meses antes de obtener la licencia, para tener un año completo de práctica.","p":"Correcto. Si es menor de 18, debe tener el permiso 12 meses."},"zh":{"q":"在 Colorado，18 岁以下的司机必须持有学习驾照多久，才能拿到驾照？","o":["3 个月","6 个月","9 个月","12 个月"],"h1":"想一想整整一年的练习。","h2":"Colorado 18 岁以下的司机必须持有学习驾照至少 12 个月才能拿到驾照，这样就有整整一年的练习。","p":"对。18 岁以下，学习驾照必须持有 12 个月。"},"vi":{"q":"Ở Colorado, người lái dưới 18 tuổi phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái?","o":["3 tháng","6 tháng","9 tháng","12 tháng"],"h1":"Hãy nghĩ đến một năm tập lái trọn vẹn.","h2":"Ở Colorado, người lái dưới 18 tuổi phải giữ giấy phép tập lái ít nhất 12 tháng trước khi lấy bằng lái, để có trọn một năm tập lái.","p":"Đúng. Dưới 18 tuổi, phải giữ giấy phép tập lái 12 tháng."},"tl":{"q":"Sa Colorado, gaano katagal dapat hawak ng driver na wala pang 18 ang instruction permit bago makakuha ng lisensya?","o":["3 buwan","6 na buwan","9 na buwan","12 buwan"],"h1":"Isipin ang isang buong taon ng pagsasanay.","h2":"Ang driver sa Colorado na wala pang 18 ay dapat humawak ng instruction permit nang hindi bababa sa 12 buwan bago makakuha ng driver license, para may isang buong taon ng pagsasanay.","p":"Tama. Kapag wala pang 18, dapat hawak ang permit nang 12 buwan."},"ar":{"q":"في Colorado، كم مدة يجب أن يحمل السائق الذي عمره أقل من 18 سنة تصريح التعلّم قبل الحصول على الرخصة؟","o":["3 أشهر","6 أشهر","9 أشهر","12 شهرًا"],"h1":"فكّر في سنة كاملة من التدريب.","h2":"يجب على السائق في Colorado الذي عمره أقل من 18 سنة أن يحمل تصريح التعلّم 12 شهرًا على الأقل قبل الحصول على رخصة القيادة، ليكون عنده سنة كاملة من التدريب.","p":"صحيح. تحت 18 سنة، يجب حمل التصريح 12 شهرًا."},"ref":{"doc":"CO","page":2}},{"id":"co-004","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, how many hours of supervised driving must a teen log before getting a license?","o":["20 hours","30 hours","50 hours","70 hours"],"h1":"The log sheet asks for more than 40 hours.","h2":"A Colorado teen must log at least 50 hours of supervised driving before getting a license, so the new driver has real practice on the road.","p":"Right. Colorado asks for 50 logged hours."},"es":{"q":"En Colorado, ¿cuántas horas de manejo supervisado debe registrar un adolescente antes de obtener la licencia?","o":["20 horas","30 horas","50 horas","70 horas"],"h1":"El registro pide más de 40 horas.","h2":"En Colorado, un adolescente debe registrar por lo menos 50 horas de manejo supervisado antes de obtener la licencia, para tener práctica real en la calle.","p":"Correcto. Colorado pide 50 horas registradas."},"zh":{"q":"在 Colorado，青少年拿驾照前必须记录多少小时有人监督的驾驶？","o":["20 小时","30 小时","50 小时","70 小时"],"h1":"记录表要求超过 40 小时。","h2":"Colorado 的青少年拿驾照前必须记录至少 50 小时有人监督的驾驶，这样新司机在路上有真正的练习。","p":"对。Colorado 要求记录 50 小时。"},"vi":{"q":"Ở Colorado, thanh thiếu niên phải ghi lại bao nhiêu giờ lái xe có người giám sát trước khi lấy bằng lái?","o":["20 giờ","30 giờ","50 giờ","70 giờ"],"h1":"Tờ ghi chép yêu cầu nhiều hơn 40 giờ.","h2":"Ở Colorado, thanh thiếu niên phải ghi lại ít nhất 50 giờ lái xe có người giám sát trước khi lấy bằng lái, để người mới lái có thực hành thật trên đường.","p":"Đúng. Colorado yêu cầu ghi lại 50 giờ."},"tl":{"q":"Sa Colorado, ilang oras ng pagmamaneho na may gumagabay ang dapat itala ng tinedyer bago makakuha ng lisensya?","o":["20 oras","30 oras","50 oras","70 oras"],"h1":"Humihingi ang talaan ng higit sa 40 oras.","h2":"Ang tinedyer sa Colorado ay dapat magtala ng hindi bababa sa 50 oras ng pagmamaneho na may gumagabay bago makakuha ng lisensya, para may tunay na pagsasanay sa kalsada ang bagong driver.","p":"Tama. Humihingi ang Colorado ng 50 nakatalang oras."},"ar":{"q":"في Colorado، كم ساعة من القيادة تحت الإشراف يجب أن يسجّل المراهق قبل الحصول على الرخصة؟","o":["20 ساعة","30 ساعة","50 ساعة","70 ساعة"],"h1":"ورقة التسجيل تطلب أكثر من 40 ساعة.","h2":"يجب على المراهق في Colorado أن يسجّل 50 ساعة على الأقل من القيادة تحت الإشراف قبل الحصول على الرخصة، ليكون عند السائق الجديد تدريب حقيقي على الطريق.","p":"صحيح. تطلب Colorado تسجيل 50 ساعة."},"ref":{"doc":"CO","page":2}},{"id":"co-005","scope":"CO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Colorado, how many of the teen's logged driving hours must be at night?","o":["10 hours","5 hours","15 hours","20 hours"],"h1":"It is one fifth of the total hours.","h2":"Of the 50 logged hours in Colorado, at least 10 must be driven at night, because driving in the dark is harder and needs practice.","p":"Right. 10 of the 50 hours must be at night."},"es":{"q":"En Colorado, ¿cuántas de las horas registradas por el adolescente deben ser de noche?","o":["10 horas","5 horas","15 horas","20 horas"],"h1":"Es una quinta parte del total de horas.","h2":"De las 50 horas registradas en Colorado, por lo menos 10 deben ser de noche, porque manejar en la oscuridad es más difícil y necesita práctica.","p":"Correcto. 10 de las 50 horas deben ser de noche."},"zh":{"q":"在 Colorado，青少年记录的驾驶时间里，有多少小时必须在晚上？","o":["10 小时","5 小时","15 小时","20 小时"],"h1":"它是全部时间的五分之一。","h2":"在 Colorado 记录的 50 小时里，至少 10 小时必须在晚上开，因为天黑开车更难，需要练习。","p":"对。50 小时里 10 小时必须在晚上。"},"vi":{"q":"Ở Colorado, trong số giờ lái xe đã ghi lại của thanh thiếu niên, bao nhiêu giờ phải lái vào ban đêm?","o":["10 giờ","5 giờ","15 giờ","20 giờ"],"h1":"Đó là một phần năm tổng số giờ.","h2":"Trong 50 giờ đã ghi lại ở Colorado, ít nhất 10 giờ phải lái vào ban đêm, vì lái xe trong bóng tối khó hơn và cần tập luyện.","p":"Đúng. 10 trong 50 giờ phải lái vào ban đêm."},"tl":{"q":"Sa Colorado, ilan sa mga nakatalang oras ng pagmamaneho ng tinedyer ang dapat sa gabi?","o":["10 oras","5 oras","15 oras","20 oras"],"h1":"Ito ay one-fifth (ikalima) ng kabuuang oras.","h2":"Sa 50 nakatalang oras sa Colorado, hindi bababa sa 10 ang dapat imaneho sa gabi, dahil mas mahirap magmaneho sa dilim at kailangan itong sanayin.","p":"Tama. 10 sa 50 oras ay dapat sa gabi."},"ar":{"q":"في Colorado، كم ساعة من ساعات القيادة المسجّلة للمراهق يجب أن تكون في الليل؟","o":["10 ساعات","5 ساعات","15 ساعة","20 ساعة"],"h1":"هي خُمس مجموع الساعات.","h2":"من الـ 50 ساعة المسجّلة في Colorado، يجب أن تكون 10 ساعات على الأقل قيادة في الليل، لأن القيادة في الظلام أصعب وتحتاج إلى تدريب.","p":"صحيح. 10 من الـ 50 ساعة يجب أن تكون في الليل."},"ref":{"doc":"CO","page":2}},{"id":"co-006","scope":"CO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Colorado, who must ride with a minor who drives on an instruction permit?","o":["Any licensed driver age 18 or older","A licensed driver age 21 or older in the front seat","Any adult sitting in the back seat","A driving instructor only"],"h1":"The person must be old enough to drink alcohol legally and sit close to the driver.","h2":"A Colorado minor with a permit must drive with a licensed driver who is at least 21 and sits in the front passenger seat, so help is always within reach.","p":"Right. The supervisor is licensed, 21 or older, and in the front seat."},"es":{"q":"En Colorado, ¿quién debe acompañar a un menor que maneja con permiso de instrucción?","o":["Cualquier conductor con licencia de 18 años o más","Un conductor con licencia de 21 años o más en el asiento delantero","Cualquier adulto en el asiento trasero","Solamente un instructor de manejo"],"h1":"La persona debe tener edad legal para tomar alcohol y sentarse cerca del conductor.","h2":"En Colorado, un menor con permiso debe manejar con un conductor con licencia que tenga por lo menos 21 años y vaya en el asiento del pasajero delantero, para que la ayuda esté siempre a la mano.","p":"Correcto. El supervisor tiene licencia, 21 años o más, y va adelante."},"zh":{"q":"在 Colorado，未成年人用学习驾照开车时，谁必须同车？","o":["任何 18 岁或以上、有驾照的司机","坐在前排、21 岁或以上、有驾照的司机","任何坐在后排的成年人","只有驾驶教练"],"h1":"这个人必须到了可以合法喝酒的年龄，并且坐在司机旁边。","h2":"Colorado 持学习驾照的未成年人必须和至少 21 岁、有驾照、坐在前排乘客座位的司机一起开车，这样随时都有人可以帮忙。","p":"对。监督的人有驾照、21 岁或以上，并坐在前排。"},"vi":{"q":"Ở Colorado, ai phải ngồi cùng xe khi người chưa đủ 18 tuổi lái xe bằng giấy phép tập lái?","o":["Bất kỳ người có bằng lái nào từ 18 tuổi trở lên","Một người có bằng lái từ 21 tuổi trở lên, ngồi ghế trước","Bất kỳ người lớn nào ngồi ghế sau","Chỉ giáo viên dạy lái xe"],"h1":"Người này phải đủ tuổi uống rượu hợp pháp và ngồi gần người lái.","h2":"Ở Colorado, người chưa đủ 18 tuổi có giấy phép tập lái phải lái cùng một người có bằng lái, ít nhất 21 tuổi, ngồi ở ghế hành khách phía trước, để luôn có người giúp ngay bên cạnh.","p":"Đúng. Người giám sát có bằng lái, từ 21 tuổi trở lên, và ngồi ghế trước."},"tl":{"q":"Sa Colorado, sino ang dapat kasama ng menor de edad na nagmamaneho gamit ang instruction permit?","o":["Sinumang may lisensya na 18 taong gulang pataas","Isang may lisensyang driver na 21 taong gulang pataas, nakaupo sa harap","Sinumang adult na nakaupo sa likod","Driving instructor lamang"],"h1":"Ang tao ay dapat nasa legal na edad para uminom ng alak at nakaupo malapit sa driver.","h2":"Ang menor de edad sa Colorado na may permit ay dapat magmaneho kasama ang isang may lisensyang driver na hindi bababa sa 21 taong gulang at nakaupo sa harap na upuan ng pasahero, para laging malapit ang tulong.","p":"Tama. Ang gumagabay ay may lisensya, 21 pataas, at nasa harap na upuan."},"ar":{"q":"في Colorado، من يجب أن يركب مع القاصر الذي يقود بتصريح التعلّم؟","o":["أي سائق مرخّص عمره 18 سنة أو أكثر","سائق مرخّص عمره 21 سنة أو أكثر في المقعد الأمامي","أي شخص بالغ يجلس في المقعد الخلفي","مدرّب القيادة فقط"],"h1":"يجب أن يكون الشخص في العمر القانوني لشرب الكحول وأن يجلس قريبًا من السائق.","h2":"يجب على القاصر في Colorado الذي معه تصريح أن يقود مع سائق مرخّص عمره 21 سنة على الأقل ويجلس في مقعد الراكب الأمامي، لتكون المساعدة دائمًا قريبة.","p":"صحيح. المشرف مرخّص، وعمره 21 سنة أو أكثر، ويجلس في المقعد الأمامي."},"ref":{"doc":"CO","page":1}},{"id":"co-007","scope":"CO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Colorado, who usually signs the affidavit of liability for a driver under 18?","o":["A parent or legal guardian","A school principal","A driving school teacher","A police officer"],"h1":"It is the adult who takes financial responsibility for the teen.","h2":"In Colorado the affidavit of liability is usually signed by a parent or legal guardian, and that adult accepts legal responsibility for the teen's driving.","p":"Right. A parent or legal guardian signs it."},"es":{"q":"En Colorado, ¿quién firma normalmente la declaración de responsabilidad de un conductor menor de 18 años?","o":["Un padre, madre o tutor legal","El director de la escuela","Un maestro de manejo","Un agente de policía"],"h1":"Es el adulto que asume la responsabilidad económica del adolescente.","h2":"En Colorado, la declaración jurada de responsabilidad normalmente la firma uno de los padres o el tutor legal, y ese adulto acepta la responsabilidad legal por la manera de manejar del joven.","p":"Correcto. La firma un padre, madre o tutor legal."},"zh":{"q":"在 Colorado，18 岁以下司机的责任声明书（affidavit of liability）通常由谁签字？","o":["父母或法定监护人","学校校长","驾校老师","警察"],"h1":"它是为这个青少年承担经济责任的成年人。","h2":"在 Colorado，责任声明书通常由父母或法定监护人签字，这个成年人为青少年的驾驶承担法律责任。","p":"对。由父母或法定监护人签字。"},"vi":{"q":"Ở Colorado, ai thường ký bản cam kết trách nhiệm (affidavit of liability) cho người lái dưới 18 tuổi?","o":["Cha mẹ hoặc người giám hộ hợp pháp","Hiệu trưởng trường học","Giáo viên trường dạy lái xe","Cảnh sát"],"h1":"Đó là người lớn chịu trách nhiệm tài chính cho thanh thiếu niên.","h2":"Ở Colorado, bản cam kết trách nhiệm thường do cha mẹ hoặc người giám hộ hợp pháp ký, và người lớn đó nhận trách nhiệm pháp lý về việc lái xe của thanh thiếu niên.","p":"Đúng. Cha mẹ hoặc người giám hộ hợp pháp ký bản này."},"tl":{"q":"Sa Colorado, sino ang karaniwang pumipirma sa affidavit of liability para sa driver na wala pang 18?","o":["Magulang o legal na tagapag-alaga","Punong-guro ng paaralan","Guro sa driving school","Pulis"],"h1":"Ito ang adult na umaako ng pinansyal na pananagutan para sa tinedyer.","h2":"Sa Colorado, ang affidavit of liability ay karaniwang pinipirmahan ng magulang o legal na tagapag-alaga, at ang adult na iyon ang umaako ng legal na pananagutan sa pagmamaneho ng tinedyer.","p":"Tama. Magulang o legal na tagapag-alaga ang pumipirma."},"ar":{"q":"في Colorado، من يوقّع عادةً إقرار المسؤولية (affidavit of liability) للسائق الذي عمره أقل من 18 سنة؟","o":["أحد الوالدين أو الوصي القانوني","مدير المدرسة","معلّم في مدرسة القيادة","شرطي"],"h1":"هو الشخص البالغ الذي يتحمّل المسؤولية المالية عن المراهق.","h2":"في Colorado يوقّع إقرار المسؤولية عادةً أحد الوالدين أو الوصي القانوني، وهذا الشخص البالغ يقبل المسؤولية القانونية عن قيادة المراهق.","p":"صحيح. يوقّعه أحد الوالدين أو الوصي القانوني."},"ref":{"doc":"CO","page":2}},{"id":"co-008","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, during the first year with a license, when may a teen driver not drive?","o":["From 10 p.m. to 5 a.m.","From 11 p.m. to 6 a.m.","From midnight to 5 a.m.","From 1 a.m. to 6 a.m."],"h1":"The limit begins exactly when the date changes.","h2":"A Colorado driver under 18 in the first year of a license may not drive from midnight to 5 a.m., except for allowed reasons such as work, school or a medical emergency.","p":"Right. No driving from midnight to 5 a.m. in the first year."},"es":{"q":"En Colorado, durante el primer año con licencia, ¿cuándo no puede manejar un conductor adolescente?","o":["De 10 p.m. a 5 a.m.","De 11 p.m. a 6 a.m.","De medianoche a 5 a.m.","De 1 a.m. a 6 a.m."],"h1":"El límite empieza justo cuando cambia la fecha.","h2":"En Colorado, un conductor menor de 18 años en su primer año con licencia no puede manejar de medianoche a 5 a.m., salvo por razones permitidas como trabajo, escuela o una emergencia médica.","p":"Correcto. No se maneja de medianoche a 5 a.m. el primer año."},"zh":{"q":"在 Colorado，拿到驾照的第一年，青少年司机什么时候不能开车？","o":["晚上 10 点到早上 5 点","晚上 11 点到早上 6 点","午夜到早上 5 点","凌晨 1 点到早上 6 点"],"h1":"这个限制正好在日期变换时开始。","h2":"Colorado 18 岁以下的司机在拿到驾照的第一年，午夜到早上 5 点不能开车，工作、上学或医疗紧急情况等允许的理由除外。","p":"对。第一年午夜到早上 5 点不能开车。"},"vi":{"q":"Ở Colorado, trong năm đầu tiên có bằng lái, thanh thiếu niên không được lái xe vào giờ nào?","o":["Từ 10 giờ tối đến 5 giờ sáng","Từ 11 giờ tối đến 6 giờ sáng","Từ nửa đêm đến 5 giờ sáng","Từ 1 giờ sáng đến 6 giờ sáng"],"h1":"Giới hạn bắt đầu đúng lúc sang ngày mới.","h2":"Ở Colorado, người lái dưới 18 tuổi trong năm đầu có bằng lái không được lái xe từ nửa đêm đến 5 giờ sáng, trừ các lý do được phép như đi làm, đi học hoặc cấp cứu y tế.","p":"Đúng. Trong năm đầu, không lái xe từ nửa đêm đến 5 giờ sáng."},"tl":{"q":"Sa Colorado, sa unang taon na may lisensya, kailan bawal magmaneho ang tinedyer na driver?","o":["Mula 10 p.m. hanggang 5 a.m.","Mula 11 p.m. hanggang 6 a.m.","Mula hatinggabi hanggang 5 a.m.","Mula 1 a.m. hanggang 6 a.m."],"h1":"Nagsisimula ang limitasyon eksakto kapag nagpalit ang petsa.","h2":"Ang driver sa Colorado na wala pang 18 at nasa unang taon ng lisensya ay bawal magmaneho mula hatinggabi hanggang 5 a.m., maliban sa mga pinapayagang dahilan gaya ng trabaho, paaralan o medical emergency.","p":"Tama. Bawal magmaneho mula hatinggabi hanggang 5 a.m. sa unang taon."},"ar":{"q":"في Colorado، خلال السنة الأولى مع الرخصة، متى لا يجوز للسائق المراهق أن يقود؟","o":["من 10 مساءً إلى 5 صباحًا","من 11 مساءً إلى 6 صباحًا","من منتصف الليل إلى 5 صباحًا","من 1 صباحًا إلى 6 صباحًا"],"h1":"يبدأ المنع بالضبط عندما يتغيّر التاريخ.","h2":"السائق في Colorado الذي عمره أقل من 18 سنة وفي سنته الأولى مع الرخصة لا يجوز له أن يقود من منتصف الليل إلى 5 صباحًا، إلا لأسباب مسموحة مثل العمل أو المدرسة أو حالة طوارئ طبية.","p":"صحيح. لا قيادة من منتصف الليل إلى 5 صباحًا في السنة الأولى."},"ref":{"doc":"CO","page":2}},{"id":"co-009","scope":"CO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Colorado, during the first six months with a license, which passengers may a teen driver carry?","o":["Up to two friends of any age","One passenger under 21","Up to three passengers under 21","Only passengers 21 or older"],"h1":"Siblings and medical emergencies are the only exceptions to this strict rule.","h2":"For the first six months with a Colorado license, a teen may carry only passengers who are 21 or older, except brothers and sisters or in a medical emergency.","p":"Right. In the first six months, only passengers 21 or older."},"es":{"q":"En Colorado, durante los primeros seis meses con licencia, ¿qué pasajeros puede llevar un conductor adolescente?","o":["Hasta dos amigos de cualquier edad","Un pasajero menor de 21 años","Hasta tres pasajeros menores de 21 años","Solamente pasajeros de 21 años o más"],"h1":"Los hermanos y las emergencias médicas son las únicas excepciones a esta regla estricta.","h2":"Durante los primeros seis meses con licencia en Colorado, un adolescente solo puede llevar pasajeros de 21 años o más, salvo sus hermanos o en una emergencia médica.","p":"Correcto. Los primeros seis meses, solo pasajeros de 21 años o más."},"zh":{"q":"在 Colorado，拿到驾照的前六个月，青少年司机可以载哪些乘客？","o":["最多两位任何年龄的朋友","一位 21 岁以下的乘客","最多三位 21 岁以下的乘客","只有 21 岁或以上的乘客"],"h1":"兄弟姐妹和医疗紧急情况是这个严格规定仅有的例外。","h2":"拿到 Colorado 驾照的前六个月，青少年只能载 21 岁或以上的乘客，兄弟姐妹或医疗紧急情况除外。","p":"对。前六个月只能载 21 岁或以上的乘客。"},"vi":{"q":"Ở Colorado, trong sáu tháng đầu có bằng lái, thanh thiếu niên được chở những hành khách nào?","o":["Tối đa hai người bạn ở bất kỳ tuổi nào","Một hành khách dưới 21 tuổi","Tối đa ba hành khách dưới 21 tuổi","Chỉ hành khách từ 21 tuổi trở lên"],"h1":"Anh chị em ruột và trường hợp cấp cứu y tế là ngoại lệ duy nhất của quy định nghiêm ngặt này.","h2":"Trong sáu tháng đầu có bằng lái Colorado, thanh thiếu niên chỉ được chở hành khách từ 21 tuổi trở lên, trừ anh chị em ruột hoặc khi có cấp cứu y tế.","p":"Đúng. Trong sáu tháng đầu, chỉ chở hành khách từ 21 tuổi trở lên."},"tl":{"q":"Sa Colorado, sa unang anim na buwan na may lisensya, aling mga pasahero ang puwedeng isakay ng tinedyer na driver?","o":["Hanggang dalawang kaibigan ng anumang edad","Isang pasahero na wala pang 21","Hanggang tatlong pasahero na wala pang 21","Mga pasahero lamang na 21 pataas"],"h1":"Ang mga kapatid at medical emergency lamang ang eksepsiyon sa mahigpit na patakarang ito.","h2":"Sa unang anim na buwan na may lisensya sa Colorado, puwedeng magsakay ang tinedyer ng mga pasahero lamang na 21 pataas, maliban sa mga kapatid o kapag may medical emergency.","p":"Tama. Sa unang anim na buwan, mga pasahero lamang na 21 pataas."},"ar":{"q":"في Colorado، خلال الأشهر الستة الأولى مع الرخصة، أي ركّاب يجوز للسائق المراهق أن يحملهم؟","o":["حتى صديقين من أي عمر","راكب واحد عمره أقل من 21 سنة","حتى ثلاثة ركّاب أعمارهم أقل من 21 سنة","الركّاب الذين عمرهم 21 سنة أو أكثر فقط"],"h1":"الإخوة والأخوات وحالات الطوارئ الطبية هي الاستثناءات الوحيدة لهذه القاعدة الصارمة.","h2":"في الأشهر الستة الأولى مع رخصة Colorado، يجوز للمراهق أن يحمل فقط ركّابًا عمرهم 21 سنة أو أكثر، إلا الإخوة والأخوات أو في حالة طوارئ طبية.","p":"صحيح. في الأشهر الستة الأولى، فقط الركّاب الذين عمرهم 21 سنة أو أكثر."},"ref":{"doc":"CO","page":2}},{"id":"co-010","scope":"CO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Colorado, during the second six months with a license, how many passengers under 21 may a teen driver carry?","o":["None at all","One","Two","Three"],"h1":"The limit loosens a little after the first six months.","h2":"In the second six months with a Colorado license, a teen may carry one passenger under 21, which is a small step up from the first six months.","p":"Right. One passenger under 21 is allowed in the second six months."},"es":{"q":"En Colorado, durante los segundos seis meses con licencia, ¿cuántos pasajeros menores de 21 años puede llevar un conductor adolescente?","o":["Ninguno","Uno","Dos","Tres"],"h1":"El límite se relaja un poco después de los primeros seis meses.","h2":"En los segundos seis meses con licencia en Colorado, un adolescente puede llevar un pasajero menor de 21 años, un pequeño paso más que en los primeros seis meses.","p":"Correcto. En los segundos seis meses se permite un pasajero menor de 21."},"zh":{"q":"在 Colorado，拿到驾照的第二个六个月，青少年司机可以载多少位 21 岁以下的乘客？","o":["一位都不行","一位","两位","三位"],"h1":"过了前六个月，限制放松一点。","h2":"拿到 Colorado 驾照的第二个六个月，青少年可以载一位 21 岁以下的乘客，比前六个月放宽了一小步。","p":"对。第二个六个月可以载一位 21 岁以下的乘客。"},"vi":{"q":"Ở Colorado, trong sáu tháng thứ hai có bằng lái, thanh thiếu niên được chở bao nhiêu hành khách dưới 21 tuổi?","o":["Không ai cả","Một","Hai","Ba"],"h1":"Giới hạn được nới lỏng một chút sau sáu tháng đầu.","h2":"Trong sáu tháng thứ hai có bằng lái Colorado, thanh thiếu niên được chở một hành khách dưới 21 tuổi, nhiều hơn một chút so với sáu tháng đầu.","p":"Đúng. Trong sáu tháng thứ hai, được chở một hành khách dưới 21 tuổi."},"tl":{"q":"Sa Colorado, sa ikalawang anim na buwan na may lisensya, ilang pasahero na wala pang 21 ang puwedeng isakay ng tinedyer na driver?","o":["Wala talaga","Isa","Dalawa","Tatlo"],"h1":"Lumuluwag nang kaunti ang limitasyon pagkatapos ng unang anim na buwan.","h2":"Sa ikalawang anim na buwan na may lisensya sa Colorado, puwedeng magsakay ang tinedyer ng isang pasahero na wala pang 21, na maliit na hakbang pataas mula sa unang anim na buwan.","p":"Tama. Isang pasahero na wala pang 21 ang pinapayagan sa ikalawang anim na buwan."},"ar":{"q":"في Colorado، خلال الأشهر الستة الثانية مع الرخصة، كم راكبًا عمره أقل من 21 سنة يجوز للسائق المراهق أن يحمل؟","o":["لا أحد أبدًا","واحد","اثنان","ثلاثة"],"h1":"يخفّ المنع قليلًا بعد الأشهر الستة الأولى.","h2":"في الأشهر الستة الثانية مع رخصة Colorado، يجوز للمراهق أن يحمل راكبًا واحدًا عمره أقل من 21 سنة، وهذه خطوة صغيرة أكثر من الأشهر الستة الأولى.","p":"صحيح. يُسمح براكب واحد عمره أقل من 21 سنة في الأشهر الستة الثانية."},"ref":{"doc":"CO","page":2}},{"id":"co-011","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, which young passengers may ride with a new teen driver at any time?","o":["Classmates","Teammates","The driver's brothers and sisters","Neighbors' children"],"h1":"Think of family who live in the same home.","h2":"Colorado lets a new teen driver carry brothers and sisters at any time, even while other passengers under 21 are limited.","p":"Right. Siblings may ride at any time."},"es":{"q":"En Colorado, ¿qué pasajeros jóvenes pueden viajar con un conductor adolescente nuevo en cualquier momento?","o":["Compañeros de clase","Compañeros de equipo","Los hermanos y hermanas del conductor","Los hijos de los vecinos"],"h1":"Piense en la familia que vive en la misma casa.","h2":"Colorado permite que un conductor adolescente nuevo lleve a sus hermanos y hermanas en cualquier momento, aunque otros pasajeros menores de 21 años estén limitados.","p":"Correcto. Los hermanos pueden ir en cualquier momento."},"zh":{"q":"在 Colorado，哪些年轻乘客任何时候都可以坐新的青少年司机的车？","o":["同学","队友","司机的兄弟姐妹","邻居的孩子"],"h1":"想一想住在同一个家里的家人。","h2":"Colorado 允许新的青少年司机任何时候载兄弟姐妹，即使其他 21 岁以下的乘客有限制。","p":"对。兄弟姐妹任何时候都可以坐车。"},"vi":{"q":"Ở Colorado, những hành khách trẻ nào được đi cùng thanh thiếu niên mới lái xe vào bất kỳ lúc nào?","o":["Bạn cùng lớp","Bạn cùng đội","Anh chị em ruột của người lái","Con của hàng xóm"],"h1":"Hãy nghĩ đến người trong gia đình sống cùng nhà.","h2":"Colorado cho phép thanh thiếu niên mới lái xe chở anh chị em ruột vào bất kỳ lúc nào, ngay cả khi các hành khách khác dưới 21 tuổi bị giới hạn.","p":"Đúng. Anh chị em ruột được đi cùng bất kỳ lúc nào."},"tl":{"q":"Sa Colorado, aling mga batang pasahero ang puwedeng sumakay kasama ng bagong tinedyer na driver anumang oras?","o":["Mga kaklase","Mga kakampi sa team","Mga kapatid ng driver","Mga anak ng kapitbahay"],"h1":"Isipin ang pamilyang nakatira sa iisang bahay.","h2":"Pinapayagan ng Colorado ang bagong tinedyer na driver na magsakay ng mga kapatid anumang oras, kahit limitado ang ibang pasahero na wala pang 21.","p":"Tama. Puwedeng sumakay ang mga kapatid anumang oras."},"ar":{"q":"في Colorado، أي ركّاب صغار يجوز لهم الركوب مع السائق المراهق الجديد في أي وقت؟","o":["زملاء الصف","زملاء الفريق","إخوة السائق وأخواته","أطفال الجيران"],"h1":"فكّر في العائلة التي تعيش في البيت نفسه.","h2":"تسمح Colorado للسائق المراهق الجديد أن يحمل إخوته وأخواته في أي وقت، حتى عندما يكون عدد الركّاب الآخرين الذين أعمارهم أقل من 21 سنة محدودًا.","p":"صحيح. يجوز للإخوة والأخوات الركوب في أي وقت."},"ref":{"doc":"CO","page":2}},{"id":"co-012","scope":"CO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Colorado, how many passengers may sit in the front seat when a new teen driver is driving?","o":["Only one","Two, if they are small","As many as fit","None at all"],"h1":"Each front-seat rider needs a seat belt of their own.","h2":"Colorado allows only one passenger in the front seat with a new teen driver, and everyone in the car must wear a seat belt.","p":"Right. Only one passenger may sit in the front."},"es":{"q":"En Colorado, ¿cuántos pasajeros pueden ir en el asiento delantero cuando maneja un adolescente nuevo?","o":["Solamente uno","Dos, si son pequeños","Todos los que quepan","Ninguno"],"h1":"Cada pasajero de adelante necesita su propio cinturón.","h2":"Colorado permite solo un pasajero en el asiento delantero con un conductor adolescente nuevo, y todos en el carro deben usar el cinturón de seguridad.","p":"Correcto. Solo un pasajero puede ir adelante."},"zh":{"q":"在 Colorado，新的青少年司机开车时，前排可以坐几位乘客？","o":["只有一位","两位，如果他们个子小","坐得下几位就几位","一位都不行"],"h1":"每位坐前排的人都需要自己的安全带。","h2":"Colorado 只允许一位乘客和新的青少年司机坐在前排，车里每个人都必须系安全带。","p":"对。前排只能坐一位乘客。"},"vi":{"q":"Ở Colorado, khi thanh thiếu niên mới lái xe, bao nhiêu hành khách được ngồi ở ghế trước?","o":["Chỉ một người","Hai người, nếu họ nhỏ","Bao nhiêu người cũng được nếu vừa chỗ","Không ai cả"],"h1":"Mỗi người ngồi ghế trước cần dây an toàn riêng.","h2":"Colorado chỉ cho phép một hành khách ngồi ghế trước với thanh thiếu niên mới lái xe, và mọi người trong xe phải thắt dây an toàn.","p":"Đúng. Chỉ một hành khách được ngồi ghế trước."},"tl":{"q":"Sa Colorado, ilang pasahero ang puwedeng umupo sa harap kapag nagmamaneho ang bagong tinedyer na driver?","o":["Isa lamang","Dalawa, kung maliliit sila","Kahit ilan basta kasya","Wala talaga"],"h1":"Bawat nakaupo sa harap ay kailangan ng sariling seat belt.","h2":"Isang pasahero lamang sa harap na upuan ang pinapayagan ng Colorado kasama ng bagong tinedyer na driver, at lahat ng nasa sasakyan ay dapat naka-seat belt.","p":"Tama. Isang pasahero lamang ang puwedeng umupo sa harap."},"ar":{"q":"في Colorado، كم راكبًا يجوز أن يجلس في المقعد الأمامي عندما يقود سائق مراهق جديد؟","o":["واحد فقط","اثنان، إذا كانا صغيرين","أي عدد يتّسع له المكان","لا أحد أبدًا"],"h1":"كل من يجلس في الأمام يحتاج إلى حزام أمان خاص به.","h2":"تسمح Colorado براكب واحد فقط في المقعد الأمامي مع السائق المراهق الجديد، ويجب على كل من في السيارة أن يضع حزام الأمان.","p":"صحيح. راكب واحد فقط يجوز أن يجلس في الأمام."},"ref":{"doc":"CO","page":null}},{"id":"co-013","scope":"CO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Colorado, since January 1, 2025, when may a driver hold a phone to talk or text while driving?","o":["Only to call for help in an emergency","When stopped at a red light","When the call is short","When traffic is light"],"h1":"Holding the phone is allowed only when help is needed.","h2":"Since January 1, 2025, a Colorado driver may not hold a phone to talk or text while driving, except to call police, fire or other help in an emergency.","p":"Right. Hold the phone only to call for help in an emergency."},"es":{"q":"En Colorado, desde el 1 de enero de 2025, ¿cuándo puede un conductor sostener el teléfono en la mano para hablar o enviar mensajes mientras maneja?","o":["Solo para pedir ayuda en una emergencia","Cuando está detenido en un semáforo en rojo","Cuando la llamada es corta","Cuando hay poco tráfico"],"h1":"Sostener el teléfono solo se permite cuando se necesita ayuda.","h2":"Desde el 1 de enero de 2025, un conductor en Colorado no puede sostener el teléfono para hablar o enviar mensajes mientras maneja, excepto para llamar a la policía, a los bomberos u otra ayuda en una emergencia.","p":"Correcto. Sostenga el teléfono solo para pedir ayuda en una emergencia."},"zh":{"q":"在 Colorado，从 2025 年 1 月 1 日起，司机开车时什么时候可以手拿手机打电话或发短信？","o":["只有在紧急情况下打电话求助","在红灯停车时","电话很短时","车不多时"],"h1":"只有需要帮助时才可以拿着手机。","h2":"从 2025 年 1 月 1 日起，Colorado 的司机开车时不能手拿手机打电话或发短信，紧急情况下打给警察、消防或其他求助除外。","p":"对。只有在紧急情况下求助时才可以拿手机。"},"vi":{"q":"Ở Colorado, từ ngày 1 tháng 1 năm 2025, khi nào người lái được cầm điện thoại để nói chuyện hoặc nhắn tin trong lúc lái xe?","o":["Chỉ khi gọi cấp cứu trong trường hợp khẩn cấp","Khi dừng ở đèn đỏ","Khi cuộc gọi ngắn","Khi đường vắng xe"],"h1":"Chỉ được cầm điện thoại khi cần người giúp.","h2":"Từ ngày 1 tháng 1 năm 2025, người lái ở Colorado không được cầm điện thoại để nói chuyện hoặc nhắn tin khi lái xe, trừ khi gọi cảnh sát, cứu hỏa hoặc sự giúp đỡ khác trong trường hợp khẩn cấp.","p":"Đúng. Chỉ cầm điện thoại để gọi cấp cứu khi khẩn cấp."},"tl":{"q":"Sa Colorado, mula Enero 1, 2025, kailan puwedeng hawakan ng driver ang telepono para tumawag o mag-text habang nagmamaneho?","o":["Para lamang humingi ng tulong sa emergency","Kapag nakahinto sa pulang ilaw","Kapag maikli ang tawag","Kapag kaunti ang trapiko"],"h1":"Pinapayagan lamang hawakan ang telepono kapag kailangan ng tulong.","h2":"Mula Enero 1, 2025, bawal sa driver sa Colorado na hawakan ang telepono para tumawag o mag-text habang nagmamaneho, maliban kung tatawag sa pulis, bumbero o ibang tulong sa emergency.","p":"Tama. Hawakan lamang ang telepono para humingi ng tulong sa emergency."},"ar":{"q":"في Colorado، منذ 1 يناير 2025، متى يجوز للسائق أن يمسك الهاتف ليتكلّم أو يرسل رسالة أثناء القيادة؟","o":["فقط ليطلب المساعدة في حالة طوارئ","عندما يتوقّف عند الإشارة الحمراء","عندما تكون المكالمة قصيرة","عندما تكون حركة المرور خفيفة"],"h1":"إمساك الهاتف مسموح فقط عندما تحتاج إلى مساعدة.","h2":"منذ 1 يناير 2025، لا يجوز للسائق في Colorado أن يمسك الهاتف ليتكلّم أو يرسل رسالة أثناء القيادة، إلا ليتّصل بالشرطة أو الإطفاء أو مساعدة أخرى في حالة طوارئ.","p":"صحيح. أمسك الهاتف فقط لتطلب المساعدة في حالة طوارئ."},"ref":{"doc":"CO","page":null}},{"id":"co-014","scope":"CO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Colorado, since January 1, 2025, how may a driver age 18 or older use a phone while driving?","o":["Holding it at any time","Holding it only on highways","Only with a hands-free accessory","Not at all, even hands-free"],"h1":"The adult's hands must stay free.","h2":"Since January 1, 2025, Colorado drivers 18 and older may not hold or handle a phone while driving; they may use it only with a hands-free accessory.","p":"Right. Adults must use hands-free."},"es":{"q":"En Colorado, desde el 1 de enero de 2025, ¿cómo puede usar el teléfono al manejar un conductor de 18 años o más?","o":["Sosteniéndolo en cualquier momento","Sosteniéndolo solo en las autopistas","Solo con un accesorio de manos libres","De ninguna manera, ni con manos libres"],"h1":"Las manos del adulto deben quedar libres.","h2":"Desde el 1 de enero de 2025, los conductores de 18 años o más en Colorado no pueden sostener ni manipular el teléfono al manejar; solo pueden usarlo con un accesorio de manos libres.","p":"Correcto. Los adultos deben usar manos libres."},"zh":{"q":"在 Colorado，从 2025 年 1 月 1 日起，18 岁或以上的司机开车时可以怎样用手机？","o":["任何时候都可以拿着","只在公路上可以拿着","只能用免持配件","完全不能用，免持也不行"],"h1":"成年人的手必须空着。","h2":"从 2025 年 1 月 1 日起，Colorado 18 岁或以上的司机开车时不能拿着或操作手机；只能用免持配件来用手机。","p":"对。成年人必须用免持。"},"vi":{"q":"Ở Colorado, từ ngày 1 tháng 1 năm 2025, người lái từ 18 tuổi trở lên được dùng điện thoại khi lái xe như thế nào?","o":["Cầm trên tay bất kỳ lúc nào","Chỉ cầm trên tay khi đi xa lộ","Chỉ với thiết bị rảnh tay (hands-free)","Hoàn toàn không, kể cả rảnh tay"],"h1":"Tay của người lớn phải được để trống.","h2":"Từ ngày 1 tháng 1 năm 2025, người lái ở Colorado từ 18 tuổi trở lên không được cầm hoặc thao tác điện thoại khi lái xe; họ chỉ được dùng với thiết bị rảnh tay.","p":"Đúng. Người lớn phải dùng thiết bị rảnh tay."},"tl":{"q":"Sa Colorado, mula Enero 1, 2025, paano puwedeng gamitin ng driver na 18 pataas ang telepono habang nagmamaneho?","o":["Hawak ito anumang oras","Hawak ito sa highway lamang","Gamit lamang ang hands-free na accessory","Hindi talaga, kahit hands-free"],"h1":"Dapat malaya ang mga kamay ng adult.","h2":"Mula Enero 1, 2025, bawal sa mga driver sa Colorado na 18 pataas na hawakan o galawin ang telepono habang nagmamaneho; puwede lamang nila itong gamitin sa hands-free na accessory.","p":"Tama. Dapat gumamit ng hands-free ang mga adult."},"ar":{"q":"في Colorado، منذ 1 يناير 2025، كيف يجوز للسائق الذي عمره 18 سنة أو أكثر أن يستعمل الهاتف أثناء القيادة؟","o":["يمسكه في أي وقت","يمسكه على الطرق السريعة فقط","فقط مع جهاز بدون استعمال اليدين (hands-free)","لا يجوز أبدًا، حتى بدون استعمال اليدين"],"h1":"يجب أن تبقى يدا البالغ حرّتين.","h2":"منذ 1 يناير 2025، لا يجوز للسائقين في Colorado الذين عمرهم 18 سنة أو أكثر أن يمسكوا الهاتف أو يستعملوه بأيديهم أثناء القيادة؛ يجوز لهم استعماله فقط مع جهاز بدون استعمال اليدين.","p":"صحيح. يجب على البالغين استعمال الهاتف بدون اليدين."},"ref":{"doc":"CO","page":null}},{"id":"co-015","scope":"CO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Colorado, what is the penalty for a first offense of holding a phone while driving?","o":["A warning only","A $75 fine and 2 points","A $500 fine and 6 points","A 30-day suspension"],"h1":"The fine is under one hundred dollars.","h2":"A first offense under Colorado's hands-free law brings a $75 fine and 2 points on the license, and the penalties grow for repeat offenses.","p":"Right. The first offense is $75 and 2 points."},"es":{"q":"En Colorado, ¿cuál es la sanción por la primera vez que se sostiene el teléfono al manejar?","o":["Solo una advertencia","Una multa de $75 y 2 puntos","Una multa de $500 y 6 puntos","Una suspensión de 30 días"],"h1":"La multa es de menos de cien dólares.","h2":"La primera infracción de la ley de manos libres de Colorado tiene una multa de $75 y 2 puntos en la licencia, y las sanciones aumentan si se repite.","p":"Correcto. La primera vez son $75 y 2 puntos."},"zh":{"q":"在 Colorado，第一次开车时手拿手机，处罚是什么？","o":["只有警告","罚款 $75 并记 2 分","罚款 $500 并记 6 分","暂停驾照 30 天"],"h1":"罚款不到一百美元。","h2":"根据 Colorado 的免持法，第一次违规罚款 $75，驾照记 2 分，再犯处罚会加重。","p":"对。第一次违规是 $75 和 2 分。"},"vi":{"q":"Ở Colorado, hình phạt cho lần vi phạm đầu tiên vì cầm điện thoại khi lái xe là gì?","o":["Chỉ bị cảnh cáo","Phạt $75 và 2 điểm","Phạt $500 và 6 điểm","Bị treo bằng 30 ngày"],"h1":"Tiền phạt dưới một trăm đô la.","h2":"Lần vi phạm đầu tiên theo luật rảnh tay của Colorado bị phạt $75 và 2 điểm vào bằng lái, và hình phạt tăng lên nếu vi phạm lại.","p":"Đúng. Lần đầu bị phạt $75 và 2 điểm."},"tl":{"q":"Sa Colorado, ano ang parusa sa unang paglabag sa paghawak ng telepono habang nagmamaneho?","o":["Babala lamang","$75 na multa at 2 puntos","$500 na multa at 6 na puntos","30 araw na suspensyon"],"h1":"Mas mababa sa isang daang dolyar ang multa.","h2":"Ang unang paglabag sa hands-free na batas ng Colorado ay may $75 na multa at 2 puntos sa lisensya, at lumalaki ang parusa sa mga susunod na paglabag.","p":"Tama. Ang unang paglabag ay $75 at 2 puntos."},"ar":{"q":"في Colorado، ما عقوبة المخالفة الأولى لإمساك الهاتف أثناء القيادة؟","o":["إنذار فقط","غرامة $75 ونقطتان","غرامة $500 و6 نقاط","إيقاف لمدة 30 يومًا"],"h1":"الغرامة أقل من مئة دولار.","h2":"المخالفة الأولى لقانون استعمال الهاتف بدون اليدين في Colorado عقوبتها غرامة $75 ونقطتان على الرخصة، وتزيد العقوبات إذا تكرّرت المخالفة.","p":"صحيح. المخالفة الأولى $75 ونقطتان."},"ref":{"doc":"CO","page":null}},{"id":"co-016","scope":"CO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Colorado, a driver under 21 can be charged with underage drinking and driving starting at what blood alcohol level?","o":["0.08 percent","0.05 percent","0.10 percent","0.02 percent"],"h1":"It is the lowest number on the list.","h2":"In Colorado a driver under 21 can be charged with underage drinking and driving at a blood alcohol level of 0.02 percent, far below the adult limit.","p":"Right. Under 21, the limit starts at 0.02."},"es":{"q":"En Colorado, ¿a partir de qué nivel de alcohol en la sangre se puede acusar a un conductor menor de 21 años de manejar después de beber?","o":["0.08 por ciento","0.05 por ciento","0.10 por ciento","0.02 por ciento"],"h1":"Es el número más bajo de la lista.","h2":"En Colorado, a un conductor menor de 21 años se le puede acusar de manejar después de beber con un nivel de alcohol de 0.02 por ciento, muy por debajo del límite para adultos.","p":"Correcto. Para menores de 21, el límite empieza en 0.02."},"zh":{"q":"在 Colorado，21 岁以下的司机血液酒精浓度从多少开始，可能被控未成年饮酒驾驶？","o":["0.08%","0.05%","0.10%","0.02%"],"h1":"它是选项里最低的数字。","h2":"在 Colorado，21 岁以下的司机血液酒精浓度达到 0.02%，就可能被控未成年饮酒驾驶，比成年人的限制低很多。","p":"对。21 岁以下，限制从 0.02 开始。"},"vi":{"q":"Ở Colorado, người lái dưới 21 tuổi có thể bị buộc tội uống rượu khi lái xe ở tuổi vị thành niên bắt đầu từ nồng độ cồn trong máu nào?","o":["0.08 phần trăm","0.05 phần trăm","0.10 phần trăm","0.02 phần trăm"],"h1":"Đó là con số thấp nhất trong danh sách.","h2":"Ở Colorado, người lái dưới 21 tuổi có thể bị buộc tội uống rượu khi lái xe ở tuổi vị thành niên khi nồng độ cồn trong máu là 0.02 phần trăm, thấp hơn nhiều so với giới hạn của người lớn.","p":"Đúng. Dưới 21 tuổi, giới hạn bắt đầu từ 0.02."},"tl":{"q":"Sa Colorado, ang driver na wala pang 21 ay puwedeng kasuhan ng underage drinking and driving simula sa anong blood alcohol level?","o":["0.08 porsiyento","0.05 porsiyento","0.10 porsiyento","0.02 porsiyento"],"h1":"Ito ang pinakamababang numero sa listahan.","h2":"Sa Colorado, ang driver na wala pang 21 ay puwedeng kasuhan ng underage drinking and driving sa blood alcohol level na 0.02 porsiyento, malayong mas mababa sa limitasyon para sa adult.","p":"Tama. Kapag wala pang 21, nagsisimula ang limitasyon sa 0.02."},"ar":{"q":"في Colorado، يمكن اتّهام السائق الذي عمره أقل من 21 سنة بالشرب والقيادة تحت السن القانونية ابتداءً من أي نسبة كحول في الدم؟","o":["0.08 بالمئة","0.05 بالمئة","0.10 بالمئة","0.02 بالمئة"],"h1":"هي أصغر رقم في القائمة.","h2":"في Colorado يمكن اتّهام السائق الذي عمره أقل من 21 سنة بالشرب والقيادة تحت السن القانونية عند نسبة كحول في الدم 0.02 بالمئة، وهي أقل بكثير من حدّ البالغين.","p":"صحيح. تحت 21 سنة، يبدأ الحدّ من 0.02."},"ref":{"doc":"CO","page":3}},{"id":"co-017","scope":"CO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Colorado, driving while ability impaired (DWAI) can be charged at about what blood alcohol level?","o":["0.02 percent","0.05 percent","0.12 percent","0.15 percent"],"h1":"It is lower than the 0.08 DUI level.","h2":"Colorado can charge driving while ability impaired at a blood alcohol level of about 0.05 percent, so you can be in trouble before you reach the 0.08 DUI level.","p":"Right. DWAI starts at about 0.05."},"es":{"q":"En Colorado, ¿con qué nivel aproximado de alcohol en la sangre se puede acusar de manejar con la capacidad disminuida (DWAI)?","o":["0.02 por ciento","0.05 por ciento","0.12 por ciento","0.15 por ciento"],"h1":"Es menor que el nivel de 0.08 de DUI.","h2":"Colorado puede acusar de manejar con la capacidad disminuida con un nivel de alcohol de aproximadamente 0.05 por ciento, así que puede tener problemas antes de llegar al nivel de 0.08 de DUI.","p":"Correcto. El DWAI empieza alrededor de 0.05."},"zh":{"q":"在 Colorado，血液酒精浓度大约多少时，可能被控能力受损驾驶（DWAI）？","o":["0.02%","0.05%","0.12%","0.15%"],"h1":"它比 0.08 的 DUI 标准低。","h2":"Colorado 在血液酒精浓度大约 0.05% 时就可以控告能力受损驾驶，所以你还没到 0.08 的 DUI 标准就可能惹上麻烦。","p":"对。DWAI 大约从 0.05 开始。"},"vi":{"q":"Ở Colorado, tội lái xe khi khả năng bị suy giảm (DWAI) có thể bị buộc ở nồng độ cồn trong máu khoảng bao nhiêu?","o":["0.02 phần trăm","0.05 phần trăm","0.12 phần trăm","0.15 phần trăm"],"h1":"Nó thấp hơn mức DUI 0.08.","h2":"Colorado có thể buộc tội lái xe khi khả năng bị suy giảm ở nồng độ cồn trong máu khoảng 0.05 phần trăm, nên bạn có thể gặp rắc rối trước khi đến mức DUI 0.08.","p":"Đúng. DWAI bắt đầu từ khoảng 0.05."},"tl":{"q":"Sa Colorado, ang driving while ability impaired (DWAI) ay puwedeng ikaso sa mga anong blood alcohol level?","o":["0.02 porsiyento","0.05 porsiyento","0.12 porsiyento","0.15 porsiyento"],"h1":"Mas mababa ito sa 0.08 na antas ng DUI.","h2":"Puwedeng magkaso ang Colorado ng driving while ability impaired sa blood alcohol level na mga 0.05 porsiyento, kaya puwede kang magkaproblema bago ka umabot sa 0.08 na antas ng DUI.","p":"Tama. Nagsisimula ang DWAI sa mga 0.05."},"ar":{"q":"في Colorado، يمكن الاتّهام بالقيادة مع ضعف القدرة (DWAI) عند نسبة كحول في الدم تقارب كم؟","o":["0.02 بالمئة","0.05 بالمئة","0.12 بالمئة","0.15 بالمئة"],"h1":"هي أقل من مستوى DUI وهو 0.08.","h2":"يمكن في Colorado الاتّهام بالقيادة مع ضعف القدرة عند نسبة كحول في الدم تقارب 0.05 بالمئة، فقد تقع في مشكلة قبل أن تصل إلى مستوى DUI وهو 0.08.","p":"صحيح. يبدأ DWAI من حوالي 0.05."},"ref":{"doc":"CO","page":4}},{"id":"co-018","scope":"CO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Colorado, at what blood alcohol level is a driver 21 or older automatically considered driving under the influence (DUI)?","o":["0.08 percent","0.02 percent","0.05 percent","0.10 percent"],"h1":"It is the most common adult limit in the United States.","h2":"In Colorado a driver 21 or older is automatically considered DUI at a blood alcohol level of 0.08 percent or higher.","p":"Right. The adult DUI level is 0.08."},"es":{"q":"En Colorado, ¿con qué nivel de alcohol en la sangre se considera automáticamente que un conductor de 21 años o más maneja bajo la influencia (DUI)?","o":["0.08 por ciento","0.02 por ciento","0.05 por ciento","0.10 por ciento"],"h1":"Es el límite para adultos más común en Estados Unidos.","h2":"En Colorado, se considera automáticamente DUI a un conductor de 21 años o más con un nivel de alcohol de 0.08 por ciento o más.","p":"Correcto. El nivel de DUI para adultos es 0.08."},"zh":{"q":"在 Colorado，21 岁或以上的司机血液酒精浓度达到多少，自动算作酒后驾驶（DUI）？","o":["0.08%","0.02%","0.05%","0.10%"],"h1":"它是美国最常见的成年人限制。","h2":"在 Colorado，21 岁或以上的司机血液酒精浓度达到 0.08% 或更高，自动算作 DUI。","p":"对。成年人的 DUI 标准是 0.08。"},"vi":{"q":"Ở Colorado, người lái từ 21 tuổi trở lên tự động bị coi là lái xe khi say (DUI) ở nồng độ cồn trong máu nào?","o":["0.08 phần trăm","0.02 phần trăm","0.05 phần trăm","0.10 phần trăm"],"h1":"Đó là giới hạn phổ biến nhất cho người lớn ở Hoa Kỳ.","h2":"Ở Colorado, người lái từ 21 tuổi trở lên tự động bị coi là DUI khi nồng độ cồn trong máu là 0.08 phần trăm trở lên.","p":"Đúng. Mức DUI cho người lớn là 0.08."},"tl":{"q":"Sa Colorado, sa anong blood alcohol level awtomatikong itinuturing na nagmamaneho nang lasing (DUI) ang driver na 21 pataas?","o":["0.08 porsiyento","0.02 porsiyento","0.05 porsiyento","0.10 porsiyento"],"h1":"Ito ang pinakakaraniwang limitasyon para sa adult sa United States.","h2":"Sa Colorado, ang driver na 21 pataas ay awtomatikong itinuturing na DUI sa blood alcohol level na 0.08 porsiyento o higit pa.","p":"Tama. Ang antas ng DUI para sa adult ay 0.08."},"ar":{"q":"في Colorado، عند أي نسبة كحول في الدم يُعتبر السائق الذي عمره 21 سنة أو أكثر تلقائيًا يقود تحت تأثير الكحول (DUI)؟","o":["0.08 بالمئة","0.02 بالمئة","0.05 بالمئة","0.10 بالمئة"],"h1":"هو الحدّ الأكثر شيوعًا للبالغين في الولايات المتحدة.","h2":"في Colorado يُعتبر السائق الذي عمره 21 سنة أو أكثر تلقائيًا DUI عند نسبة كحول في الدم 0.08 بالمئة أو أكثر.","p":"صحيح. مستوى DUI للبالغين هو 0.08."},"ref":{"doc":"CO","page":3}},{"id":"co-019","scope":"CO","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Colorado, you approach a stopped car on the roadside with its hazard lights flashing. What must you do?","o":["Honk and keep your speed","Stop behind it and wait","Move over one lane if safe; if not, slow down","Slow down only if police are there"],"h1":"The law protects any stopped vehicle that shows hazard lights.","h2":"In Colorado, when you pass a stopped vehicle with flashing hazard lights, you must move over one lane if you safely can; if you cannot, you must slow down to a safe speed.","p":"Right. Move over a lane, or slow down if you cannot."},"es":{"q":"En Colorado, usted se acerca a un carro detenido al lado del camino con las luces de emergencia encendidas. ¿Qué debe hacer?","o":["Tocar la bocina y seguir igual","Pararse detrás y esperar","Cambiarse un carril si es seguro; si no, bajar la velocidad","Bajar la velocidad solo si hay policía"],"h1":"La ley protege a cualquier vehículo detenido con luces de emergencia.","h2":"En Colorado, cuando usted pasa un vehículo detenido con las luces de emergencia encendidas, debe cambiarse un carril si puede hacerlo con seguridad; si no puede, debe bajar a una velocidad segura.","p":"Correcto. Cámbiese de carril, o baje la velocidad si no puede."},"zh":{"q":"在 Colorado，你接近一辆停在路边、双闪灯在闪的车。你必须怎么做？","o":["按喇叭并保持速度","停在它后面等","如果安全就换开一条车道；做不到就减速","只有警察在场时才减速"],"h1":"这条法律保护任何开着双闪灯停着的车辆。","h2":"在 Colorado，经过一辆双闪灯在闪的停着的车时，如果可以安全换道，你必须换开一条车道；做不到的话，必须减速到安全的速度。","p":"对。换开一条车道，做不到就减速。"},"vi":{"q":"Ở Colorado, bạn đến gần một chiếc xe đang dừng bên đường với đèn cảnh báo nguy hiểm đang nhấp nháy. Bạn phải làm gì?","o":["Bấm còi và giữ nguyên tốc độ","Dừng phía sau nó và chờ","Chuyển sang một làn khác nếu an toàn; nếu không, hãy giảm tốc độ","Chỉ giảm tốc độ nếu có cảnh sát ở đó"],"h1":"Luật bảo vệ bất kỳ xe nào đang dừng có bật đèn cảnh báo nguy hiểm.","h2":"Ở Colorado, khi bạn đi qua một xe đang dừng có đèn cảnh báo nguy hiểm nhấp nháy, bạn phải chuyển sang một làn khác nếu làm được một cách an toàn; nếu không thể, bạn phải giảm xuống tốc độ an toàn.","p":"Đúng. Chuyển sang một làn khác, hoặc giảm tốc độ nếu không thể."},"tl":{"q":"Sa Colorado, papalapit ka sa nakahintong sasakyan sa gilid ng daan na kumikislap ang hazard lights. Ano ang dapat mong gawin?","o":["Bumusina at panatilihin ang bilis","Huminto sa likod nito at maghintay","Lumipat ng isang lane kung ligtas; kung hindi, magbagal","Magbagal lamang kung may pulis doon"],"h1":"Pinoprotektahan ng batas ang anumang nakahintong sasakyan na may hazard lights.","h2":"Sa Colorado, kapag dumaraan ka sa nakahintong sasakyan na kumikislap ang hazard lights, dapat kang lumipat ng isang lane kung kaya mo nang ligtas; kung hindi mo kaya, dapat kang magbagal sa ligtas na bilis.","p":"Tama. Lumipat ng isang lane, o magbagal kung hindi mo kaya."},"ar":{"q":"في Colorado، تقترب من سيارة متوقّفة على جانب الطريق وأضواء الخطر فيها تومض. ماذا يجب أن تفعل؟","o":["تستعمل البوق وتحافظ على سرعتك","تتوقّف خلفها وتنتظر","تنتقل مسارًا واحدًا إذا كان ذلك آمنًا؛ وإلا تخفّف السرعة","تخفّف السرعة فقط إذا كانت الشرطة هناك"],"h1":"القانون يحمي أي مركبة متوقّفة تُظهر أضواء الخطر.","h2":"في Colorado، عندما تمرّ بمركبة متوقّفة أضواء الخطر فيها تومض، يجب أن تنتقل مسارًا واحدًا إذا استطعت ذلك بأمان؛ وإذا لم تستطع، يجب أن تخفّف إلى سرعة آمنة.","p":"صحيح. انتقل مسارًا واحدًا، أو خفّف السرعة إذا لم تستطع."},"ref":{"doc":"CO","page":null}},{"id":"co-020","scope":"CO","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Colorado, since August 2023, which stopped vehicles does the move-over law protect?","o":["Only police cars","Only tow trucks and ambulances","Only road crew trucks","Any stopped vehicle with hazard lights on"],"h1":"The 2023 change made the rule much wider.","h2":"Since August 2023, Colorado's move-over law covers any stopped vehicle with flashing hazard lights, not only emergency and service vehicles.","p":"Right. It covers any stopped vehicle with hazard lights."},"es":{"q":"En Colorado, desde agosto de 2023, ¿qué vehículos detenidos protege la ley de cambiarse de carril?","o":["Solo los carros de policía","Solo las grúas y ambulancias","Solo los camiones de obras viales","Cualquier vehículo detenido con luces de emergencia"],"h1":"El cambio de 2023 amplió mucho la regla.","h2":"Desde agosto de 2023, la ley de Colorado de cambiarse de carril protege a cualquier vehículo detenido con luces de emergencia, no solo a vehículos de emergencia y de servicio.","p":"Correcto. Protege a cualquier vehículo detenido con luces de emergencia."},"zh":{"q":"在 Colorado，从 2023 年 8 月起，move-over 法保护哪些停着的车辆？","o":["只有警车","只有拖车和救护车","只有道路施工车","任何开着双闪灯停着的车辆"],"h1":"2023 年的修改让这个规定的范围大了很多。","h2":"从 2023 年 8 月起，Colorado 的 move-over 法保护任何开着双闪灯停着的车辆，不只是急救车辆和服务车辆。","p":"对。它保护任何开着双闪灯停着的车辆。"},"vi":{"q":"Ở Colorado, từ tháng 8 năm 2023, luật nhường làn (move-over law) bảo vệ những xe đang dừng nào?","o":["Chỉ xe cảnh sát","Chỉ xe kéo và xe cứu thương","Chỉ xe của đội sửa đường","Bất kỳ xe nào đang dừng có bật đèn cảnh báo nguy hiểm"],"h1":"Thay đổi năm 2023 làm cho quy định rộng hơn nhiều.","h2":"Từ tháng 8 năm 2023, luật nhường làn của Colorado áp dụng cho bất kỳ xe nào đang dừng có đèn cảnh báo nguy hiểm nhấp nháy, không chỉ xe cấp cứu và xe dịch vụ.","p":"Đúng. Luật áp dụng cho bất kỳ xe nào đang dừng có bật đèn cảnh báo nguy hiểm."},"tl":{"q":"Sa Colorado, mula Agosto 2023, aling mga nakahintong sasakyan ang pinoprotektahan ng move-over law?","o":["Mga sasakyan ng pulis lamang","Mga tow truck at ambulansya lamang","Mga trak ng road crew lamang","Anumang nakahintong sasakyan na naka-on ang hazard lights"],"h1":"Pinalawak nang husto ng pagbabago noong 2023 ang patakaran.","h2":"Mula Agosto 2023, sakop ng move-over law ng Colorado ang anumang nakahintong sasakyan na kumikislap ang hazard lights, hindi lamang mga emergency at service vehicle.","p":"Tama. Sakop nito ang anumang nakahintong sasakyan na may hazard lights."},"ar":{"q":"في Colorado، منذ أغسطس 2023، أي مركبات متوقّفة يحميها قانون الابتعاد (move-over law)؟","o":["سيارات الشرطة فقط","شاحنات السحب وسيارات الإسعاف فقط","شاحنات عمّال الطرق فقط","أي مركبة متوقّفة أضواء الخطر فيها مُشغّلة"],"h1":"تغيير عام 2023 جعل القاعدة أوسع بكثير.","h2":"منذ أغسطس 2023، يشمل قانون الابتعاد في Colorado أي مركبة متوقّفة أضواء الخطر فيها تومض، وليس فقط مركبات الطوارئ والخدمة.","p":"صحيح. يشمل أي مركبة متوقّفة أضواء الخطر فيها مُشغّلة."},"ref":{"doc":"CO","page":null}},{"id":"co-021","scope":"CO","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Colorado, if no sign says otherwise, what is the speed limit in a residence district?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"It is a little faster than the business district limit.","h2":"Colorado law sets 30 mph as the lawful speed in a residence district when no other limit is posted.","p":"Right. A residence district is 30 mph."},"es":{"q":"En Colorado, si no hay letrero que diga otra cosa, ¿cuál es el límite de velocidad en una zona residencial?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Es un poco más rápido que el límite de la zona comercial.","h2":"La ley de Colorado fija 30 mph como velocidad legal en una zona residencial cuando no hay otro límite indicado.","p":"Correcto. Una zona residencial es de 30 mph."},"zh":{"q":"在 Colorado，如果没有标志另有规定，住宅区的限速是多少？","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"它比商业区的限速快一点。","h2":"在没有标示其他限速时，Colorado 法律规定住宅区的合法速度是 30 mph。","p":"对。住宅区是 30 mph。"},"vi":{"q":"Ở Colorado, nếu không có biển báo khác, giới hạn tốc độ trong khu dân cư (residence district) là bao nhiêu?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Nó nhanh hơn một chút so với giới hạn trong khu thương mại.","h2":"Luật Colorado quy định 30 mph là tốc độ hợp pháp trong khu dân cư khi không có giới hạn nào khác được ghi trên biển báo.","p":"Đúng. Khu dân cư là 30 mph."},"tl":{"q":"Sa Colorado, kung walang ibang sinasabi ang karatula, ano ang speed limit sa residence district (lugar ng mga tirahan)?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Medyo mas mabilis ito kaysa sa limitasyon sa business district.","h2":"Itinatakda ng batas ng Colorado ang 30 mph bilang legal na bilis sa residence district kapag walang ibang nakapaskil na limitasyon.","p":"Tama. 30 mph sa residence district."},"ar":{"q":"في Colorado، إذا لم تقل لافتة غير ذلك، ما حدّ السرعة في المنطقة السكنية (residence district)؟","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"هو أسرع قليلًا من حدّ المنطقة التجارية.","h2":"قانون Colorado يحدّد 30 mph كسرعة قانونية في المنطقة السكنية عندما لا يكون هناك حدّ آخر مكتوب على لافتة.","p":"صحيح. المنطقة السكنية 30 mph."},"ref":{"doc":"CO","page":12}},{"id":"co-022","scope":"CO","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Colorado, if no sign says otherwise, what is the speed limit in a business district?","o":["25 mph","30 mph","35 mph","20 mph"],"h1":"It is slower than the residence district limit.","h2":"Colorado law sets 25 mph as the lawful speed in a business district when no other limit is posted, because shops bring many people and cars together.","p":"Right. A business district is 25 mph."},"es":{"q":"En Colorado, si no hay letrero que diga otra cosa, ¿cuál es el límite de velocidad en una zona comercial?","o":["25 mph","30 mph","35 mph","20 mph"],"h1":"Es más lento que el límite de la zona residencial.","h2":"La ley de Colorado fija 25 mph como velocidad legal en una zona comercial cuando no hay otro límite indicado, porque las tiendas reúnen a mucha gente y muchos carros.","p":"Correcto. Una zona comercial es de 25 mph."},"zh":{"q":"在 Colorado，如果没有标志另有规定，商业区的限速是多少？","o":["25 mph","30 mph","35 mph","20 mph"],"h1":"它比住宅区的限速慢。","h2":"在没有标示其他限速时，Colorado 法律规定商业区的合法速度是 25 mph，因为商店让很多人和车聚在一起。","p":"对。商业区是 25 mph。"},"vi":{"q":"Ở Colorado, nếu không có biển báo khác, giới hạn tốc độ trong khu thương mại (business district) là bao nhiêu?","o":["25 mph","30 mph","35 mph","20 mph"],"h1":"Nó chậm hơn giới hạn trong khu dân cư.","h2":"Luật Colorado quy định 25 mph là tốc độ hợp pháp trong khu thương mại khi không có giới hạn nào khác được ghi trên biển báo, vì cửa hàng thu hút nhiều người và xe cùng một chỗ.","p":"Đúng. Khu thương mại là 25 mph."},"tl":{"q":"Sa Colorado, kung walang ibang sinasabi ang karatula, ano ang speed limit sa business district (lugar ng negosyo)?","o":["25 mph","30 mph","35 mph","20 mph"],"h1":"Mas mabagal ito kaysa sa limitasyon sa residence district.","h2":"Itinatakda ng batas ng Colorado ang 25 mph bilang legal na bilis sa business district kapag walang ibang nakapaskil na limitasyon, dahil maraming tao at sasakyan ang nagtitipon sa mga tindahan.","p":"Tama. 25 mph sa business district."},"ar":{"q":"في Colorado، إذا لم تقل لافتة غير ذلك، ما حدّ السرعة في المنطقة التجارية (business district)؟","o":["25 mph","30 mph","35 mph","20 mph"],"h1":"هو أبطأ من حدّ المنطقة السكنية.","h2":"قانون Colorado يحدّد 25 mph كسرعة قانونية في المنطقة التجارية عندما لا يكون هناك حدّ آخر مكتوب على لافتة، لأن المحلات تجمع كثيرًا من الناس والسيارات معًا.","p":"صحيح. المنطقة التجارية 25 mph."},"ref":{"doc":"CO","page":11}},{"id":"co-023","scope":"CO","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Colorado, what is the lawful speed on a narrow, winding mountain highway or a blind curve, if no sign says otherwise?","o":["40 mph","30 mph","20 mph","55 mph"],"h1":"It is the lowest number in Colorado's speed law.","h2":"Colorado law sets 20 mph on narrow, winding mountain highways and blind curves when no other limit is posted, because you cannot see far ahead.","p":"Right. Narrow mountain roads and blind curves are 20 mph."},"es":{"q":"En Colorado, ¿cuál es la velocidad legal en una carretera de montaña estrecha y con curvas, o en una curva ciega, si no hay letrero?","o":["40 mph","30 mph","20 mph","55 mph"],"h1":"Es el número más bajo de la ley de velocidad de Colorado.","h2":"La ley de Colorado fija 20 mph en carreteras de montaña estrechas y con curvas, y en curvas ciegas, cuando no hay otro límite indicado, porque no se ve lejos.","p":"Correcto. Las carreteras de montaña estrechas y las curvas ciegas son de 20 mph."},"zh":{"q":"在 Colorado，如果没有标志另有规定，在狭窄弯曲的山区公路或看不到前方的弯道上，合法速度是多少？","o":["40 mph","30 mph","20 mph","55 mph"],"h1":"它是 Colorado 速度法里最低的数字。","h2":"在没有标示其他限速时，Colorado 法律规定狭窄弯曲的山区公路和看不到前方的弯道限速 20 mph，因为你看不远。","p":"对。狭窄的山路和看不到前方的弯道是 20 mph。"},"vi":{"q":"Ở Colorado, tốc độ hợp pháp trên đường núi hẹp, quanh co hoặc ở khúc cua khuất tầm nhìn là bao nhiêu, nếu không có biển báo khác?","o":["40 mph","30 mph","20 mph","55 mph"],"h1":"Đó là con số thấp nhất trong luật tốc độ của Colorado.","h2":"Luật Colorado quy định 20 mph trên đường núi hẹp, quanh co và ở khúc cua khuất tầm nhìn khi không có giới hạn nào khác được ghi trên biển báo, vì bạn không thể nhìn xa phía trước.","p":"Đúng. Đường núi hẹp và khúc cua khuất tầm nhìn là 20 mph."},"tl":{"q":"Sa Colorado, ano ang legal na bilis sa makitid at paliko-likong highway sa bundok o sa blind curve, kung walang ibang sinasabi ang karatula?","o":["40 mph","30 mph","20 mph","55 mph"],"h1":"Ito ang pinakamababang numero sa batas ng bilis ng Colorado.","h2":"Itinatakda ng batas ng Colorado ang 20 mph sa makikitid at paliko-likong highway sa bundok at sa mga blind curve kapag walang ibang nakapaskil na limitasyon, dahil hindi mo matanaw nang malayo ang nasa unahan.","p":"Tama. 20 mph sa makikitid na daan sa bundok at mga blind curve."},"ar":{"q":"في Colorado، ما السرعة القانونية على طريق جبلي ضيّق كثير المنعطفات أو عند منعطف لا ترى ما بعده، إذا لم تقل لافتة غير ذلك؟","o":["40 mph","30 mph","20 mph","55 mph"],"h1":"هو أصغر رقم في قانون السرعة في Colorado.","h2":"قانون Colorado يحدّد 20 mph على الطرق الجبلية الضيّقة الكثيرة المنعطفات وعند المنعطفات التي لا ترى ما بعدها عندما لا يكون هناك حدّ آخر مكتوب على لافتة، لأنك لا تستطيع أن ترى بعيدًا أمامك.","p":"صحيح. الطرق الجبلية الضيّقة والمنعطفات التي لا ترى ما بعدها 20 mph."},"ref":{"doc":"CO","page":11}},{"id":"co-024","scope":"CO","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Colorado, what is the highest speed limit that may be set on any highway?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"Only some rural interstate highways are posted this high.","h2":"Colorado law does not allow any highway speed limit above 75 mph, and only some rural interstate stretches are posted that high.","p":"Right. The highest limit in Colorado is 75 mph."},"es":{"q":"En Colorado, ¿cuál es el límite de velocidad más alto que se puede fijar en una carretera?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"Solo algunas autopistas interestatales rurales tienen este límite.","h2":"La ley de Colorado no permite un límite de velocidad mayor de 75 mph en ninguna carretera, y solo algunos tramos rurales de autopista interestatal lo tienen.","p":"Correcto. El límite más alto en Colorado es de 75 mph."},"zh":{"q":"在 Colorado，任何公路最高可以定多少限速？","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"只有一些乡村州际公路标示这么高。","h2":"Colorado 法律不允许任何公路的限速高于 75 mph，而且只有一些乡村州际公路路段标示这么高。","p":"对。Colorado 最高限速是 75 mph。"},"vi":{"q":"Ở Colorado, giới hạn tốc độ cao nhất có thể đặt trên bất kỳ xa lộ nào là bao nhiêu?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"Chỉ một số xa lộ liên bang ở vùng nông thôn được ghi cao như vậy.","h2":"Luật Colorado không cho phép giới hạn tốc độ trên xa lộ nào cao hơn 75 mph, và chỉ một số đoạn xa lộ liên bang ở nông thôn được ghi cao như vậy.","p":"Đúng. Giới hạn cao nhất ở Colorado là 75 mph."},"tl":{"q":"Sa Colorado, ano ang pinakamataas na speed limit na puwedeng itakda sa anumang highway?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"Ilang interstate highway lamang sa probinsya ang may ganito kataas na nakapaskil.","h2":"Hindi pinapayagan ng batas ng Colorado ang anumang speed limit sa highway na higit sa 75 mph, at ilang bahagi lamang ng interstate sa probinsya ang may ganito kataas.","p":"Tama. Ang pinakamataas na limitasyon sa Colorado ay 75 mph."},"ar":{"q":"في Colorado، ما أعلى حدّ سرعة يجوز وضعه على أي طريق سريع؟","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"بعض الطرق السريعة بين الولايات (interstate) في الأرياف فقط مكتوب عليها هذا الحدّ.","h2":"قانون Colorado لا يسمح بأي حدّ سرعة على الطرق السريعة أعلى من 75 mph، وبعض أجزاء الطرق السريعة بين الولايات في الأرياف فقط مكتوب عليها هذا الحدّ.","p":"صحيح. أعلى حدّ في Colorado هو 75 mph."},"ref":{"doc":"CO","page":12}},{"id":"co-025","scope":"CO","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Colorado, on a highway with a speed limit of 65 mph or more, when may you drive in the far left lane?","o":["Only to pass or to turn left","Any time traffic is light","Whenever you drive the speed limit","Only at night"],"h1":"This lane has one main job.","h2":"On Colorado highways with a limit of 65 mph or more, the far left lane is for passing or turning left, unless heavy traffic makes it unsafe to move right.","p":"Right. The far left lane is for passing or turning left."},"es":{"q":"En Colorado, en una carretera con límite de 65 mph o más, ¿cuándo puede manejar en el carril del extremo izquierdo?","o":["Solo para rebasar o para girar a la izquierda","Siempre que haya poco tráfico","Siempre que vaya al límite de velocidad","Solo de noche"],"h1":"Este carril tiene una función principal.","h2":"En las carreteras de Colorado con límite de 65 mph o más, el carril del extremo izquierdo es para rebasar o girar a la izquierda, salvo que el tráfico pesado impida pasarse a la derecha con seguridad.","p":"Correcto. El carril del extremo izquierdo es para rebasar o girar a la izquierda."},"zh":{"q":"在 Colorado，在限速 65 mph 或更高的公路上，你什么时候可以在最左边车道开？","o":["只有超车或左转时","车不多的任何时候","只要你按限速开","只在晚上"],"h1":"这条车道有一个主要用途。","h2":"在限速 65 mph 或更高的 Colorado 公路上，最左边车道是用来超车或左转的，除非车太多，往右换道不安全。","p":"对。最左边车道是用来超车或左转的。"},"vi":{"q":"Ở Colorado, trên xa lộ có giới hạn tốc độ từ 65 mph trở lên, khi nào bạn được lái ở làn ngoài cùng bên trái?","o":["Chỉ để vượt hoặc để rẽ trái","Bất kỳ lúc nào đường vắng xe","Bất cứ khi nào bạn lái đúng giới hạn tốc độ","Chỉ vào ban đêm"],"h1":"Làn này có một nhiệm vụ chính.","h2":"Trên xa lộ ở Colorado có giới hạn từ 65 mph trở lên, làn ngoài cùng bên trái dùng để vượt hoặc rẽ trái, trừ khi xe đông khiến việc chuyển sang phải không an toàn.","p":"Đúng. Làn ngoài cùng bên trái dùng để vượt hoặc rẽ trái."},"tl":{"q":"Sa Colorado, sa highway na may speed limit na 65 mph pataas, kailan ka puwedeng magmaneho sa pinakakaliwang lane?","o":["Para lamang mag-overtake o kumaliwa","Anumang oras na kaunti ang trapiko","Tuwing nagmamaneho ka sa speed limit","Sa gabi lamang"],"h1":"May isang pangunahing gamit ang lane na ito.","h2":"Sa mga highway sa Colorado na may limitasyon na 65 mph pataas, ang pinakakaliwang lane ay para sa pag-overtake o pagkaliwa, maliban kung dahil sa mabigat na trapiko ay hindi ligtas lumipat sa kanan.","p":"Tama. Ang pinakakaliwang lane ay para sa pag-overtake o pagkaliwa."},"ar":{"q":"في Colorado، على طريق سريع حدّ السرعة فيه 65 mph أو أكثر، متى يجوز لك أن تقود في المسار الأيسر الأقصى؟","o":["فقط للتجاوز أو للانعطاف يسارًا","في أي وقت تكون فيه حركة المرور خفيفة","كلما قدت بحدّ السرعة","في الليل فقط"],"h1":"لهذا المسار مهمّة رئيسية واحدة.","h2":"على الطرق السريعة في Colorado التي حدّها 65 mph أو أكثر، المسار الأيسر الأقصى للتجاوز أو للانعطاف يسارًا، إلا إذا كانت حركة المرور كثيفة تجعل الانتقال إلى اليمين غير آمن.","p":"صحيح. المسار الأيسر الأقصى للتجاوز أو للانعطاف يسارًا."},"ref":{"doc":"CO","page":null}},{"id":"co-026","scope":"CO","cat":"signals","sign":null,"c":0,"en":{"q":"In Colorado, when may you turn left on a red light after a full stop?","o":["From a one-way street onto another one-way street","From any street onto a two-way street","Only when a police officer waves you on","Never, under any conditions"],"h1":"Both streets must have traffic moving in only one direction.","h2":"Colorado allows a left turn on red after a full stop only from a one-way street onto another one-way street, when no sign forbids it and after yielding.","p":"Right. Left on red is only from one-way onto one-way."},"es":{"q":"En Colorado, ¿cuándo puede girar a la izquierda con luz roja después de parar por completo?","o":["De una calle de un solo sentido a otra de un solo sentido","De cualquier calle a una calle de doble sentido","Solo cuando un policía le indica que pase","Nunca, bajo ninguna condición"],"h1":"Las dos calles deben tener tráfico en una sola dirección.","h2":"Colorado permite girar a la izquierda con luz roja, después de parar por completo, solo de una calle de un solo sentido a otra de un solo sentido, si no hay letrero que lo prohíba y después de ceder el paso.","p":"Correcto. Se gira a la izquierda en rojo solo de un sentido a un sentido."},"zh":{"q":"在 Colorado，什么时候可以在完全停车后红灯左转？","o":["从单行道转进另一条单行道","从任何街道转进双向街道","只有警察挥手让你走时","从来不可以，任何情况都不行"],"h1":"两条街都必须只有一个方向的车。","h2":"Colorado 只允许从单行道转进另一条单行道时，在完全停车、没有标志禁止并让行以后红灯左转。","p":"对。只有从单行道转进单行道才可以红灯左转。"},"vi":{"q":"Ở Colorado, khi nào bạn được rẽ trái khi đèn đỏ sau khi đã dừng hẳn?","o":["Từ đường một chiều vào một đường một chiều khác","Từ bất kỳ đường nào vào đường hai chiều","Chỉ khi cảnh sát vẫy tay cho bạn đi","Không bao giờ, trong mọi trường hợp"],"h1":"Cả hai đường đều phải có xe chạy theo một hướng duy nhất.","h2":"Colorado chỉ cho phép rẽ trái khi đèn đỏ, sau khi đã dừng hẳn, từ đường một chiều vào một đường một chiều khác, khi không có biển báo cấm và sau khi đã nhường đường.","p":"Đúng. Rẽ trái khi đèn đỏ chỉ từ đường một chiều vào đường một chiều."},"tl":{"q":"Sa Colorado, kailan ka puwedeng kumaliwa sa pulang ilaw pagkatapos ng buong paghinto?","o":["Mula sa one-way na kalye papunta sa isa pang one-way na kalye","Mula sa anumang kalye papunta sa two-way na kalye","Kapag kinawayan ka lamang ng pulis","Hindi kailanman, sa anumang kondisyon"],"h1":"Ang dalawang kalye ay dapat may trapikong papunta sa iisang direksyon lamang.","h2":"Pinapayagan ng Colorado ang pagkaliwa sa pulang ilaw pagkatapos ng buong paghinto mula lamang sa one-way na kalye papunta sa isa pang one-way na kalye, kapag walang karatulang nagbabawal at pagkatapos magbigay-daan.","p":"Tama. Ang pagkaliwa sa pula ay mula lamang sa one-way papunta sa one-way."},"ar":{"q":"في Colorado، متى يجوز لك أن تنعطف يسارًا عند الإشارة الحمراء بعد التوقّف الكامل؟","o":["من شارع باتجاه واحد إلى شارع آخر باتجاه واحد","من أي شارع إلى شارع باتجاهين","فقط عندما يشير لك شرطي بالمرور","أبدًا، في أي حال"],"h1":"يجب أن تكون حركة المرور في الشارعين في اتجاه واحد فقط.","h2":"تسمح Colorado بالانعطاف يسارًا عند الإشارة الحمراء بعد التوقّف الكامل فقط من شارع باتجاه واحد إلى شارع آخر باتجاه واحد، عندما لا توجد لافتة تمنع ذلك وبعد إعطاء الأولوية.","p":"صحيح. الانعطاف يسارًا عند الأحمر فقط من اتجاه واحد إلى اتجاه واحد."},"ref":{"doc":"CO","page":7}},{"id":"co-027","scope":"CO","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Colorado, when a school bus has its red lights flashing and stop arm out, how far away must you stop?","o":["At least 5 feet","At least 20 feet","At least 50 feet","At least 100 feet"],"h1":"The distance is about the length of a large car and a half.","h2":"In Colorado you must stop at least 20 feet from a school bus that shows flashing red lights and its stop arm, so children have room to cross.","p":"Right. Stop at least 20 feet from the bus."},"es":{"q":"En Colorado, cuando un autobús escolar tiene las luces rojas intermitentes y el brazo de alto extendido, ¿a qué distancia debe parar?","o":["Por lo menos a 5 pies","Por lo menos a 20 pies","Por lo menos a 50 pies","Por lo menos a 100 pies"],"h1":"La distancia es como el largo de un carro grande y medio.","h2":"En Colorado usted debe parar por lo menos a 20 pies de un autobús escolar con luces rojas intermitentes y el brazo de alto, para que los niños tengan espacio para cruzar.","p":"Correcto. Pare por lo menos a 20 pies del autobús."},"zh":{"q":"在 Colorado，当校车红灯在闪、伸出停车臂时，你必须在离它多远的地方停车？","o":["至少 5 英尺","至少 20 英尺","至少 50 英尺","至少 100 英尺"],"h1":"这个距离大约是一辆半大车的长度。","h2":"在 Colorado，你必须在离红灯闪烁、伸出停车臂的校车至少 20 英尺的地方停车，这样孩子有空间过马路。","p":"对。在离校车至少 20 英尺的地方停车。"},"vi":{"q":"Ở Colorado, khi xe buýt trường học bật đèn đỏ nhấp nháy và giơ cần báo dừng (stop arm), bạn phải dừng cách xe bao xa?","o":["Ít nhất 5 feet","Ít nhất 20 feet","Ít nhất 50 feet","Ít nhất 100 feet"],"h1":"Khoảng cách này bằng khoảng một chiếc xe hơi lớn rưỡi.","h2":"Ở Colorado, bạn phải dừng cách ít nhất 20 feet khi xe buýt trường học bật đèn đỏ nhấp nháy và giơ cần báo dừng, để trẻ em có chỗ đi qua đường.","p":"Đúng. Dừng cách xe buýt ít nhất 20 feet."},"tl":{"q":"Sa Colorado, kapag kumikislap ang pulang ilaw ng school bus at nakalabas ang stop arm nito, gaano kalayo ka dapat huminto?","o":["Hindi bababa sa 5 talampakan (feet)","Hindi bababa sa 20 talampakan (feet)","Hindi bababa sa 50 talampakan (feet)","Hindi bababa sa 100 talampakan (feet)"],"h1":"Ang layo ay mga isa't kalahating haba ng malaking kotse.","h2":"Sa Colorado, dapat kang huminto nang hindi bababa sa 20 talampakan mula sa school bus na kumikislap ang pulang ilaw at nakalabas ang stop arm, para may lugar ang mga bata sa pagtawid.","p":"Tama. Huminto nang hindi bababa sa 20 talampakan mula sa bus."},"ar":{"q":"في Colorado، عندما تكون أضواء الحافلة المدرسية الحمراء تومض وذراع التوقّف (stop arm) ممدودة، على أي مسافة يجب أن تتوقّف؟","o":["5 أقدام على الأقل","20 قدمًا على الأقل","50 قدمًا على الأقل","100 قدم على الأقل"],"h1":"المسافة تقارب طول سيارة كبيرة ونصف.","h2":"في Colorado يجب أن تتوقّف على بُعد 20 قدمًا على الأقل من الحافلة المدرسية التي تُظهر أضواء حمراء تومض وذراع التوقّف، ليكون عند الأطفال مكان لعبور الطريق.","p":"صحيح. توقّف على بُعد 20 قدمًا على الأقل من الحافلة."},"ref":{"doc":"CO","page":11}},{"id":"co-028","scope":"CO","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Colorado, on a two-lane road, you meet a school bus from the opposite direction with red lights flashing. What must you do?","o":["Slow down and pass with care","Honk and continue","Stop until the lights turn off","Stop only if children are visible"],"h1":"On a road this narrow, children may cross into your lane.","h2":"On a Colorado two-lane road, drivers coming from either direction must stop for a school bus with flashing red lights and wait until the lights turn off.","p":"Right. On a two-lane road, both directions stop."},"es":{"q":"En Colorado, en un camino de dos carriles, usted encuentra de frente un autobús escolar con luces rojas intermitentes. ¿Qué debe hacer?","o":["Bajar la velocidad y pasar con cuidado","Tocar la bocina y seguir","Parar hasta que se apaguen las luces","Parar solo si ve niños"],"h1":"En un camino tan angosto, los niños pueden cruzar a su carril.","h2":"En un camino de dos carriles en Colorado, los conductores de ambas direcciones deben parar ante un autobús escolar con luces rojas intermitentes y esperar hasta que se apaguen.","p":"Correcto. En un camino de dos carriles, paran las dos direcciones."},"zh":{"q":"在 Colorado，在双车道道路上，你遇到一辆从对面方向来、红灯在闪的校车。你必须怎么做？","o":["减速，小心地开过去","按喇叭，继续开","停车，直到灯熄灭","只有看到孩子时才停车"],"h1":"在这么窄的路上，孩子可能会走到你的车道。","h2":"在 Colorado 的双车道道路上，两个方向来的司机都必须为红灯闪烁的校车停车，并等到灯熄灭。","p":"对。在双车道道路上，两个方向都要停车。"},"vi":{"q":"Ở Colorado, trên đường hai làn, bạn gặp một xe buýt trường học đi ngược chiều đang bật đèn đỏ nhấp nháy. Bạn phải làm gì?","o":["Giảm tốc độ và đi qua cẩn thận","Bấm còi và đi tiếp","Dừng lại cho đến khi đèn tắt","Chỉ dừng nếu thấy trẻ em"],"h1":"Trên đường hẹp như vậy, trẻ em có thể đi qua làn của bạn.","h2":"Trên đường hai làn ở Colorado, người lái từ cả hai hướng phải dừng lại khi xe buýt trường học bật đèn đỏ nhấp nháy và chờ cho đến khi đèn tắt.","p":"Đúng. Trên đường hai làn, cả hai hướng đều phải dừng."},"tl":{"q":"Sa Colorado, sa daang may dalawang lane, nakasalubong mo ang school bus mula sa kabilang direksyon na kumikislap ang pulang ilaw. Ano ang dapat mong gawin?","o":["Magbagal at dumaan nang maingat","Bumusina at magpatuloy","Huminto hanggang mamatay ang mga ilaw","Huminto lamang kung may nakikitang bata"],"h1":"Sa ganito kakitid na daan, puwedeng tumawid ang mga bata sa lane mo.","h2":"Sa daang may dalawang lane sa Colorado, ang mga driver mula sa alinmang direksyon ay dapat huminto para sa school bus na kumikislap ang pulang ilaw at maghintay hanggang mamatay ang mga ilaw.","p":"Tama. Sa daang may dalawang lane, humihinto ang dalawang direksyon."},"ar":{"q":"في Colorado، على طريق بمسارين، تقابل حافلة مدرسية آتية من الاتجاه المعاكس وأضواؤها الحمراء تومض. ماذا يجب أن تفعل؟","o":["تخفّف السرعة وتمرّ بحذر","تستعمل البوق وتستمرّ","تتوقّف حتى تنطفئ الأضواء","تتوقّف فقط إذا رأيت أطفالًا"],"h1":"على طريق بهذا الضيق، قد يعبر الأطفال إلى مسارك.","h2":"على طريق بمسارين في Colorado، يجب على السائقين الآتين من أي من الاتجاهين أن يتوقّفوا للحافلة المدرسية التي أضواؤها الحمراء تومض وأن ينتظروا حتى تنطفئ الأضواء.","p":"صحيح. على طريق بمسارين، يتوقّف الاتجاهان."},"ref":{"doc":"CO","page":20}},{"id":"co-029","scope":"CO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Colorado, how many points within 12 months can lead to suspension for a driver age 17 or younger?","o":["4 points","6 points","9 points","12 points"],"h1":"Young drivers get far fewer points than adults before trouble starts.","h2":"A Colorado driver age 17 or younger can be suspended with 6 or more points in any 12 months, or 7 or more points at any time before turning 18.","p":"Right. Under 18, 6 points in 12 months can mean suspension."},"es":{"q":"En Colorado, ¿cuántos puntos en 12 meses pueden causar la suspensión de un conductor de 17 años o menos?","o":["4 puntos","6 puntos","9 puntos","12 puntos"],"h1":"Los conductores jóvenes acumulan muchos menos puntos que los adultos antes de tener problemas.","h2":"En Colorado, a un conductor de 17 años o menos se le puede suspender con 6 puntos o más en 12 meses, o con 7 puntos o más en cualquier momento antes de cumplir 18.","p":"Correcto. Menores de 18: 6 puntos en 12 meses pueden causar suspensión."},"zh":{"q":"在 Colorado，17 岁或以下的司机在 12 个月内被记多少分，可能被暂停驾照？","o":["4 分","6 分","9 分","12 分"],"h1":"年轻司机比成年人少很多分就会有麻烦。","h2":"Colorado 17 岁或以下的司机，在任何 12 个月内被记 6 分或更多，或在满 18 岁前任何时候被记 7 分或更多，就可能被暂停驾照。","p":"对。18 岁以下，12 个月内 6 分就可能被暂停驾照。"},"vi":{"q":"Ở Colorado, người lái từ 17 tuổi trở xuống bị bao nhiêu điểm trong 12 tháng thì có thể bị treo bằng lái?","o":["4 điểm","6 điểm","9 điểm","12 điểm"],"h1":"Người lái trẻ bị giới hạn ít điểm hơn nhiều so với người lớn trước khi gặp rắc rối.","h2":"Ở Colorado, người lái từ 17 tuổi trở xuống có thể bị treo bằng lái khi có từ 6 điểm trở lên trong 12 tháng bất kỳ, hoặc từ 7 điểm trở lên vào bất kỳ lúc nào trước khi đủ 18 tuổi.","p":"Đúng. Dưới 18 tuổi, 6 điểm trong 12 tháng có thể bị treo bằng lái."},"tl":{"q":"Sa Colorado, ilang puntos sa loob ng 12 buwan ang puwedeng magdulot ng suspensyon para sa driver na 17 taong gulang pababa?","o":["4 na puntos","6 na puntos","9 na puntos","12 puntos"],"h1":"Mas kaunting puntos ang pinapayagan sa mga batang driver kaysa sa mga adult bago magkaproblema.","h2":"Ang driver sa Colorado na 17 taong gulang pababa ay puwedeng masuspinde kapag may 6 o higit pang puntos sa anumang 12 buwan, o 7 o higit pang puntos anumang oras bago mag-18.","p":"Tama. Kapag wala pang 18, ang 6 na puntos sa 12 buwan ay puwedeng mauwi sa suspensyon."},"ar":{"q":"في Colorado، كم نقطة خلال 12 شهرًا يمكن أن تؤدّي إلى إيقاف رخصة السائق الذي عمره 17 سنة أو أقل؟","o":["4 نقاط","6 نقاط","9 نقاط","12 نقطة"],"h1":"السائقون الصغار يُسمح لهم بنقاط أقل بكثير من البالغين قبل أن تبدأ المشكلة.","h2":"يمكن إيقاف رخصة السائق في Colorado الذي عمره 17 سنة أو أقل إذا حصل على 6 نقاط أو أكثر في أي 12 شهرًا، أو 7 نقاط أو أكثر في أي وقت قبل أن يبلغ 18 سنة.","p":"صحيح. تحت 18 سنة، 6 نقاط في 12 شهرًا قد تعني الإيقاف."},"ref":{"doc":"CO","page":null}},{"id":"co-030","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, how many points within 12 months can lead to suspension for a driver age 18 to 21?","o":["4 points","6 points","9 points","14 points"],"h1":"It is more than the under-18 limit but less than a dozen.","h2":"A Colorado driver age 18 to 21 can be suspended with 9 or more points in any 12 months, 12 in any 24 months, or 14 at any time between 18 and 21.","p":"Right. Ages 18 to 21: 9 points in 12 months."},"es":{"q":"En Colorado, ¿cuántos puntos en 12 meses pueden causar la suspensión de un conductor de 18 a 21 años?","o":["4 puntos","6 puntos","9 puntos","14 puntos"],"h1":"Es más que el límite para menores de 18, pero menos de una docena.","h2":"En Colorado, a un conductor de 18 a 21 años se le puede suspender con 9 puntos o más en 12 meses, 12 en 24 meses, o 14 en cualquier momento entre los 18 y los 21.","p":"Correcto. De 18 a 21 años: 9 puntos en 12 meses."},"zh":{"q":"在 Colorado，18 到 21 岁的司机在 12 个月内被记多少分，可能被暂停驾照？","o":["4 分","6 分","9 分","14 分"],"h1":"它比 18 岁以下的限制多，但比一打少。","h2":"Colorado 18 到 21 岁的司机，在任何 12 个月内被记 9 分或更多、任何 24 个月内 12 分，或在 18 到 21 岁之间任何时候 14 分，就可能被暂停驾照。","p":"对。18 到 21 岁：12 个月内 9 分。"},"vi":{"q":"Ở Colorado, người lái từ 18 đến 21 tuổi bị bao nhiêu điểm trong 12 tháng thì có thể bị treo bằng lái?","o":["4 điểm","6 điểm","9 điểm","14 điểm"],"h1":"Nhiều hơn giới hạn cho người dưới 18 tuổi nhưng ít hơn một tá.","h2":"Ở Colorado, người lái từ 18 đến 21 tuổi có thể bị treo bằng lái khi có từ 9 điểm trở lên trong 12 tháng bất kỳ, 12 điểm trong 24 tháng bất kỳ, hoặc 14 điểm vào bất kỳ lúc nào từ 18 đến 21 tuổi.","p":"Đúng. Từ 18 đến 21 tuổi: 9 điểm trong 12 tháng."},"tl":{"q":"Sa Colorado, ilang puntos sa loob ng 12 buwan ang puwedeng magdulot ng suspensyon para sa driver na 18 hanggang 21 taong gulang?","o":["4 na puntos","6 na puntos","9 na puntos","14 na puntos"],"h1":"Mas marami ito kaysa sa limitasyon para sa wala pang 18 pero mas kaunti sa isang dosena.","h2":"Ang driver sa Colorado na 18 hanggang 21 taong gulang ay puwedeng masuspinde kapag may 9 o higit pang puntos sa anumang 12 buwan, 12 sa anumang 24 na buwan, o 14 anumang oras mula 18 hanggang 21.","p":"Tama. Edad 18 hanggang 21: 9 na puntos sa 12 buwan."},"ar":{"q":"في Colorado، كم نقطة خلال 12 شهرًا يمكن أن تؤدّي إلى إيقاف رخصة السائق الذي عمره من 18 إلى 21 سنة؟","o":["4 نقاط","6 نقاط","9 نقاط","14 نقطة"],"h1":"هي أكثر من حدّ من هم تحت 18 سنة لكن أقل من دزينة.","h2":"يمكن إيقاف رخصة السائق في Colorado الذي عمره من 18 إلى 21 سنة إذا حصل على 9 نقاط أو أكثر في أي 12 شهرًا، أو 12 في أي 24 شهرًا، أو 14 في أي وقت بين 18 و21 سنة.","p":"صحيح. من 18 إلى 21 سنة: 9 نقاط في 12 شهرًا."},"ref":{"doc":"CO","page":null}},{"id":"co-031","scope":"CO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Colorado, what is the minimum liability insurance a driver must carry?","o":["$25,000 / $50,000 / $15,000","$10,000 / $20,000 / $10,000","$50,000 / $100,000 / $25,000","$30,000 / $60,000 / $25,000"],"h1":"The property damage part is $15,000.","h2":"Colorado requires at least $25,000 for injury to one person, $50,000 for injuries in one crash, and $15,000 for property damage.","p":"Right. Colorado's minimum is 25/50/15."},"es":{"q":"En Colorado, ¿cuál es el seguro de responsabilidad mínimo que debe tener un conductor?","o":["$25,000 / $50,000 / $15,000","$10,000 / $20,000 / $10,000","$50,000 / $100,000 / $25,000","$30,000 / $60,000 / $25,000"],"h1":"La parte de daños a la propiedad es de $15,000.","h2":"Colorado exige por lo menos $25,000 por lesiones a una persona, $50,000 por lesiones en un mismo choque y $15,000 por daños a la propiedad.","p":"Correcto. El mínimo en Colorado es 25/50/15."},"zh":{"q":"在 Colorado，司机必须买的最低责任保险是多少？","o":["$25,000 / $50,000 / $15,000","$10,000 / $20,000 / $10,000","$50,000 / $100,000 / $25,000","$30,000 / $60,000 / $25,000"],"h1":"财产损失的部分是 $15,000。","h2":"Colorado 要求一个人受伤至少 $25,000，一次车祸的人身伤害至少 $50,000，财产损失至少 $15,000。","p":"对。Colorado 的最低标准是 25/50/15。"},"vi":{"q":"Ở Colorado, mức bảo hiểm trách nhiệm (liability insurance) tối thiểu người lái phải có là bao nhiêu?","o":["$25,000 / $50,000 / $15,000","$10,000 / $20,000 / $10,000","$50,000 / $100,000 / $25,000","$30,000 / $60,000 / $25,000"],"h1":"Phần thiệt hại tài sản là $15,000.","h2":"Colorado yêu cầu ít nhất $25,000 cho thương tích của một người, $50,000 cho thương tích trong một vụ tai nạn, và $15,000 cho thiệt hại tài sản.","p":"Đúng. Mức tối thiểu ở Colorado là 25/50/15."},"tl":{"q":"Sa Colorado, ano ang pinakamababang liability insurance na dapat mayroon ang driver?","o":["$25,000 / $50,000 / $15,000","$10,000 / $20,000 / $10,000","$50,000 / $100,000 / $25,000","$30,000 / $60,000 / $25,000"],"h1":"Ang bahagi para sa pinsala sa ari-arian ay $15,000.","h2":"Hinihingi ng Colorado ang hindi bababa sa $25,000 para sa pinsala sa isang tao, $50,000 para sa mga pinsala sa isang aksidente, at $15,000 para sa pinsala sa ari-arian.","p":"Tama. Ang minimum sa Colorado ay 25/50/15."},"ar":{"q":"في Colorado، ما الحدّ الأدنى لتأمين المسؤولية (liability insurance) الذي يجب أن يكون عند السائق؟","o":["$25,000 / $50,000 / $15,000","$10,000 / $20,000 / $10,000","$50,000 / $100,000 / $25,000","$30,000 / $60,000 / $25,000"],"h1":"جزء الأضرار بالممتلكات هو $15,000.","h2":"تطلب Colorado على الأقل $25,000 لإصابة شخص واحد، و$50,000 للإصابات في حادث واحد، و$15,000 للأضرار بالممتلكات.","p":"صحيح. الحدّ الأدنى في Colorado هو 25/50/15."},"ref":{"doc":"CO","page":null}},{"id":"co-032","scope":"CO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Colorado, when the passenger vehicle chain law is active, which vehicles need chains or another approved traction device?","o":["Only two-wheel-drive cars","Only trucks over 16,000 pounds","Only cars with worn tires","All vehicles, including four-wheel drive"],"h1":"It is the last step before a highway closes.","h2":"When Colorado's passenger vehicle chain law is active, every vehicle needs chains or an approved alternative traction device, even all-wheel and four-wheel drive.","p":"Right. Under the chain law, all vehicles need chains or a traction device."},"es":{"q":"En Colorado, cuando está activa la ley de cadenas para vehículos de pasajeros, ¿qué vehículos necesitan cadenas u otro dispositivo de tracción aprobado?","o":["Solo los carros de tracción en dos ruedas","Solo los camiones de más de 16,000 libras","Solo los carros con llantas gastadas","Todos los vehículos, incluso los de doble tracción"],"h1":"Es el último paso antes de cerrar una carretera.","h2":"Cuando está activa la ley de cadenas en Colorado, todo vehículo necesita cadenas o un dispositivo de tracción aprobado, incluso los de tracción total o doble tracción.","p":"Correcto. Con la ley de cadenas, todos los vehículos necesitan cadenas o tracción."},"zh":{"q":"在 Colorado，客车防滑链法（chain law）生效时，哪些车辆需要防滑链或其他认可的防滑装置？","o":["只有两轮驱动的车","只有超过 16,000 磅的卡车","只有轮胎磨损的车","所有车辆，包括四轮驱动"],"h1":"它是公路封闭前的最后一步。","h2":"Colorado 的客车防滑链法生效时，每一辆车都需要防滑链或认可的其他防滑装置，即使是全轮驱动和四轮驱动也一样。","p":"对。防滑链法生效时，所有车辆都需要防滑链或防滑装置。"},"vi":{"q":"Ở Colorado, khi luật xích bánh xe cho xe chở khách (passenger vehicle chain law) có hiệu lực, những xe nào cần xích hoặc thiết bị bám đường khác được chấp thuận?","o":["Chỉ xe dẫn động hai bánh","Chỉ xe tải nặng hơn 16,000 pound","Chỉ xe có lốp mòn","Tất cả các xe, kể cả xe dẫn động bốn bánh"],"h1":"Đó là bước cuối cùng trước khi xa lộ bị đóng.","h2":"Khi luật xích bánh xe cho xe chở khách của Colorado có hiệu lực, mọi xe đều cần xích hoặc thiết bị bám đường thay thế được chấp thuận, kể cả xe dẫn động mọi bánh và bốn bánh.","p":"Đúng. Theo luật xích bánh xe, mọi xe đều cần xích hoặc thiết bị bám đường."},"tl":{"q":"Sa Colorado, kapag aktibo ang passenger vehicle chain law, aling mga sasakyan ang kailangan ng kadena o ibang aprubadong traction device?","o":["Mga kotseng two-wheel drive lamang","Mga trak na higit sa 16,000 libra lamang","Mga kotseng may pudpod na gulong lamang","Lahat ng sasakyan, kasama ang four-wheel drive"],"h1":"Ito ang huling hakbang bago isara ang highway.","h2":"Kapag aktibo ang passenger vehicle chain law ng Colorado, bawat sasakyan ay kailangan ng kadena o aprubadong alternatibong traction device, kahit all-wheel at four-wheel drive.","p":"Tama. Sa ilalim ng chain law, lahat ng sasakyan ay kailangan ng kadena o traction device."},"ar":{"q":"في Colorado، عندما يكون قانون السلاسل لمركبات الركّاب (passenger vehicle chain law) مُفعّلًا، أي مركبات تحتاج إلى سلاسل أو جهاز تماسك آخر معتمد؟","o":["السيارات ذات الدفع الثنائي فقط","الشاحنات التي وزنها أكثر من 16,000 رطل فقط","السيارات ذات الإطارات البالية فقط","كل المركبات، ومنها ذات الدفع الرباعي"],"h1":"هي الخطوة الأخيرة قبل إغلاق الطريق السريع.","h2":"عندما يكون قانون السلاسل لمركبات الركّاب في Colorado مُفعّلًا، تحتاج كل مركبة إلى سلاسل أو جهاز تماسك بديل معتمد، حتى المركبات ذات الدفع الكلّي والدفع الرباعي.","p":"صحيح. بموجب قانون السلاسل، كل المركبات تحتاج إلى سلاسل أو جهاز تماسك."},"ref":{"doc":"CO","page":null}},{"id":"co-033","scope":"CO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Colorado, during which months must passenger vehicles on I-70 between Dotsero and Morrison be ready to follow the traction law?","o":["December 1 to February 28","November 1 to March 31","September 1 to May 31","All year round"],"h1":"The season covers most of the school year.","h2":"From September 1 to May 31, passenger vehicles on I-70 between Dotsero and Morrison must be ready to meet the traction law whenever the signs turn on.","p":"Right. The I-70 traction season is September 1 to May 31."},"es":{"q":"En Colorado, ¿en qué meses deben estar listos los vehículos de pasajeros en la I-70, entre Dotsero y Morrison, para cumplir la ley de tracción?","o":["Del 1 de diciembre al 28 de febrero","Del 1 de noviembre al 31 de marzo","Del 1 de septiembre al 31 de mayo","Todo el año"],"h1":"La temporada abarca casi todo el año escolar.","h2":"Del 1 de septiembre al 31 de mayo, los vehículos de pasajeros en la I-70 entre Dotsero y Morrison deben estar listos para cumplir la ley de tracción cuando se enciendan los letreros.","p":"Correcto. La temporada de tracción en la I-70 es del 1 de septiembre al 31 de mayo."},"zh":{"q":"在 Colorado，在哪几个月，Dotsero 和 Morrison 之间 I-70 上的客车必须准备好遵守牵引力法（traction law）？","o":["十二月 1 日到二月 28 日","十一月 1 日到三月 31 日","九月 1 日到五月 31 日","全年"],"h1":"这个季节包括学年的大部分时间。","h2":"从九月 1 日到五月 31 日，Dotsero 和 Morrison 之间 I-70 上的客车必须准备好，只要标志一亮就能符合牵引力法。","p":"对。I-70 的牵引力季节是九月 1 日到五月 31 日。"},"vi":{"q":"Ở Colorado, trong những tháng nào xe chở khách trên I-70 giữa Dotsero và Morrison phải sẵn sàng tuân theo luật bám đường (traction law)?","o":["Từ 1 tháng 12 đến 28 tháng 2","Từ 1 tháng 11 đến 31 tháng 3","Từ 1 tháng 9 đến 31 tháng 5","Quanh năm"],"h1":"Mùa này gồm phần lớn năm học.","h2":"Từ ngày 1 tháng 9 đến ngày 31 tháng 5, xe chở khách trên I-70 giữa Dotsero và Morrison phải sẵn sàng đáp ứng luật bám đường mỗi khi biển báo được bật.","p":"Đúng. Mùa luật bám đường trên I-70 là từ 1 tháng 9 đến 31 tháng 5."},"tl":{"q":"Sa Colorado, sa anong mga buwan dapat handang sumunod sa traction law ang mga pampasaherong sasakyan sa I-70 sa pagitan ng Dotsero at Morrison?","o":["Disyembre 1 hanggang Pebrero 28","Nobyembre 1 hanggang Marso 31","Setyembre 1 hanggang Mayo 31","Buong taon"],"h1":"Sakop ng panahong ito ang malaking bahagi ng school year.","h2":"Mula Setyembre 1 hanggang Mayo 31, ang mga pampasaherong sasakyan sa I-70 sa pagitan ng Dotsero at Morrison ay dapat handang sumunod sa traction law tuwing bubukas ang mga karatula.","p":"Tama. Ang traction season sa I-70 ay Setyembre 1 hanggang Mayo 31."},"ar":{"q":"في Colorado، في أي أشهر يجب أن تكون مركبات الركّاب على I-70 بين Dotsero وMorrison مستعدّة لاتّباع قانون التماسك (traction law)؟","o":["من 1 ديسمبر إلى 28 فبراير","من 1 نوفمبر إلى 31 مارس","من 1 سبتمبر إلى 31 مايو","طوال السنة"],"h1":"هذا الموسم يشمل معظم السنة الدراسية.","h2":"من 1 سبتمبر إلى 31 مايو، يجب أن تكون مركبات الركّاب على I-70 بين Dotsero وMorrison مستعدّة لتلبية قانون التماسك كلما أُضيئت اللافتات.","p":"صحيح. موسم قانون التماسك على I-70 من 1 سبتمبر إلى 31 مايو."},"ref":{"doc":"CO","page":null}},{"id":"co-034","scope":"CO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Colorado, when a driver under 18 is driving, who must wear a seat belt?","o":["Only the driver","Only front-seat riders","Only passengers under 18","The driver and every passenger"],"h1":"Age of the passenger does not matter here.","h2":"When a Colorado driver is under 18, the driver and every passenger, of any age, must wear a seat belt or ride in the right child seat.","p":"Right. The teen driver and every passenger must buckle up."},"es":{"q":"En Colorado, cuando maneja un conductor menor de 18 años, ¿quién debe usar el cinturón de seguridad?","o":["Solo el conductor","Solo los que van adelante","Solo los pasajeros menores de 18","El conductor y todos los pasajeros"],"h1":"Aquí no importa la edad del pasajero.","h2":"Cuando un conductor en Colorado es menor de 18 años, el conductor y todos los pasajeros, de cualquier edad, deben usar el cinturón de seguridad o ir en el asiento infantil adecuado.","p":"Correcto. El conductor joven y todos los pasajeros deben abrocharse."},"zh":{"q":"在 Colorado，18 岁以下的司机开车时，谁必须系安全带？","o":["只有司机","只有坐前排的人","只有 18 岁以下的乘客","司机和每一位乘客"],"h1":"这里乘客的年龄没有关系。","h2":"当 Colorado 的司机未满 18 岁时，司机和每一位任何年龄的乘客都必须系安全带，或坐在合适的儿童座椅里。","p":"对。青少年司机和每一位乘客都必须系好安全带。"},"vi":{"q":"Ở Colorado, khi người lái dưới 18 tuổi đang lái xe, ai phải thắt dây an toàn?","o":["Chỉ người lái","Chỉ người ngồi ghế trước","Chỉ hành khách dưới 18 tuổi","Người lái và mọi hành khách"],"h1":"Tuổi của hành khách không quan trọng ở đây.","h2":"Khi người lái ở Colorado dưới 18 tuổi, người lái và mọi hành khách, ở bất kỳ tuổi nào, phải thắt dây an toàn hoặc ngồi đúng ghế an toàn cho trẻ em.","p":"Đúng. Người lái tuổi teen và mọi hành khách đều phải thắt dây an toàn."},"tl":{"q":"Sa Colorado, kapag nagmamaneho ang driver na wala pang 18, sino ang dapat naka-seat belt?","o":["Ang driver lamang","Ang mga nakaupo sa harap lamang","Ang mga pasahero na wala pang 18 lamang","Ang driver at bawat pasahero"],"h1":"Hindi mahalaga dito ang edad ng pasahero.","h2":"Kapag wala pang 18 ang driver sa Colorado, ang driver at bawat pasahero, anuman ang edad, ay dapat naka-seat belt o nakaupo sa tamang child seat.","p":"Tama. Ang tinedyer na driver at bawat pasahero ay dapat mag-seat belt."},"ar":{"q":"في Colorado، عندما يقود سائق عمره أقل من 18 سنة، من يجب أن يضع حزام الأمان؟","o":["السائق فقط","من يجلسون في الأمام فقط","الركّاب الذين عمرهم أقل من 18 سنة فقط","السائق وكل راكب"],"h1":"عمر الراكب لا يهمّ هنا.","h2":"عندما يكون السائق في Colorado عمره أقل من 18 سنة، يجب على السائق وكل راكب، من أي عمر، أن يضع حزام الأمان أو يجلس في مقعد الطفل المناسب.","p":"صحيح. السائق المراهق وكل راكب يجب أن يضعوا حزام الأمان."},"ref":{"doc":"CO","page":3}},{"id":"co-035","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, in which languages does the DMV offer the driving knowledge test?","o":["English only","English, Spanish and French","English and Spanish","Any language you choose"],"h1":"The online test uses the same two languages as the office test.","h2":"The Colorado DMV offers the driving knowledge test in English and Spanish, both in the office and online.","p":"Right. The test is offered in English and Spanish."},"es":{"q":"En Colorado, ¿en qué idiomas ofrece el DMV el examen de conocimientos de manejo?","o":["Solo en inglés","En inglés, español y francés","En inglés y español","En el idioma que usted elija"],"h1":"El examen en línea usa los mismos dos idiomas que el examen en la oficina.","h2":"El DMV de Colorado ofrece el examen de conocimientos de manejo en inglés y en español, tanto en la oficina como en línea.","p":"Correcto. El examen se ofrece en inglés y en español."},"zh":{"q":"在 Colorado，DMV 用哪些语言进行驾驶知识考试？","o":["只有英语","英语、西班牙语和法语","英语和西班牙语","你选择的任何语言"],"h1":"网上考试和办公室考试用的是同样的两种语言。","h2":"Colorado DMV 的驾驶知识考试用英语和西班牙语，在办公室考和在网上考都一样。","p":"对。考试用英语和西班牙语。"},"vi":{"q":"Ở Colorado, DMV cho thi kiến thức lái xe bằng những ngôn ngữ nào?","o":["Chỉ tiếng Anh","Tiếng Anh, tiếng Tây Ban Nha và tiếng Pháp","Tiếng Anh và tiếng Tây Ban Nha","Bất kỳ ngôn ngữ nào bạn chọn"],"h1":"Bài thi trực tuyến dùng cùng hai ngôn ngữ như bài thi tại văn phòng.","h2":"Colorado DMV cho thi kiến thức lái xe bằng tiếng Anh và tiếng Tây Ban Nha, cả tại văn phòng và trực tuyến.","p":"Đúng. Bài thi có bằng tiếng Anh và tiếng Tây Ban Nha."},"tl":{"q":"Sa Colorado, sa anong mga wika inaalok ng DMV ang driving knowledge test?","o":["Ingles lang","Ingles, Espanyol at Pranses","Ingles at Espanyol","Kahit anong wika na piliin mo"],"h1":"Ang online test ay gumagamit ng parehong dalawang wika gaya ng test sa opisina.","h2":"Inaalok ng Colorado DMV ang driving knowledge test sa Ingles at Espanyol, sa opisina man o online.","p":"Tama. Inaalok ang test sa Ingles at Espanyol."},"ar":{"q":"في Colorado، بأي لغات يقدّم DMV اختبار المعرفة للقيادة؟","o":["الإنجليزية فقط","الإنجليزية والإسبانية والفرنسية","الإنجليزية والإسبانية","أي لغة تختارها"],"h1":"يستخدم الاختبار عبر الإنترنت نفس اللغتين المستخدمتين في اختبار المكتب.","h2":"يقدّم Colorado DMV اختبار المعرفة للقيادة بالإنجليزية والإسبانية، في المكتب وعبر الإنترنت.","p":"صحيح. الاختبار متاح بالإنجليزية والإسبانية."},"ref":{"doc":"CO","page":null}},{"id":"co-036","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, what happens to your license if you refuse a chemical test when an officer suspects impaired driving?","o":["You get a warning the first time","It is suspended for 30 days","It is revoked for one year","Nothing, if you pass a field test"],"h1":"Colorado's express consent law treats refusal very seriously.","h2":"In Colorado, if you refuse a chemical test of your blood, breath, saliva or urine, your license is revoked for one year, and you must also use an ignition interlock for two years.","p":"Right. Refusing the test means a one-year revocation."},"es":{"q":"En Colorado, ¿qué pasa con su licencia si usted se niega a una prueba química cuando un agente sospecha que maneja bajo los efectos?","o":["Recibe una advertencia la primera vez","Se suspende por 30 días","Se revoca por un año","Nada, si pasa una prueba de campo"],"h1":"La ley de consentimiento expreso de Colorado trata la negativa con mucha seriedad.","h2":"En Colorado, si usted se niega a una prueba química de sangre, aliento, saliva u orina, su licencia se revoca por un año y además debe usar un dispositivo de bloqueo de encendido por dos años.","p":"Correcto. Negarse a la prueba significa un año de revocación."},"ref":{"doc":"CO","page":5}},{"id":"co-037","scope":"CO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Colorado, how many points go on your record for a first conviction of driving while ability impaired (DWAI)?","o":["8 points","2 points","4 points","12 points"],"h1":"It is a large number, close to a full suspension for some drivers.","h2":"In Colorado, a first conviction for driving while ability impaired adds 8 points to your driving record.","p":"Right. A first DWAI brings 8 points."},"es":{"q":"En Colorado, ¿cuántos puntos se agregan a su historial por una primera condena por manejar con la capacidad disminuida (DWAI)?","o":["8 puntos","2 puntos","4 puntos","12 puntos"],"h1":"Es un número alto, cerca de una suspensión para algunos conductores.","h2":"En Colorado, una primera condena por manejar con la capacidad disminuida agrega 8 puntos a su historial de manejo.","p":"Correcto. Un primer DWAI suma 8 puntos."},"ref":{"doc":"CO","page":4}},{"id":"co-038","scope":"CO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Colorado, at what level of THC (from marijuana) in the blood may a court infer that a driver was under the influence?","o":["Any amount at all","1 nanogram per milliliter","10 nanograms per milliliter","5 nanograms per milliliter"],"h1":"The number is measured in nanograms per milliliter of blood.","h2":"In Colorado, a blood level of 5 nanograms of THC per milliliter allows a court to infer that the driver was driving under the influence.","p":"Right. The THC inference level is 5 nanograms per milliliter."},"es":{"q":"En Colorado, ¿con qué nivel de THC (de la marihuana) en la sangre puede un tribunal suponer que el conductor manejaba bajo los efectos?","o":["Cualquier cantidad","1 nanogramo por mililitro","10 nanogramos por mililitro","5 nanogramos por mililitro"],"h1":"El número se mide en nanogramos por mililitro de sangre.","h2":"En Colorado, un nivel de 5 nanogramos de THC por mililitro de sangre permite a un tribunal suponer que el conductor manejaba bajo los efectos.","p":"Correcto. El nivel para el THC es de 5 nanogramos por mililitro."},"ref":{"doc":"CO","page":5}},{"id":"co-039","scope":"CO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Colorado, which open containers are not allowed in the passenger area of a vehicle on a public road?","o":["Only open bottles of liquor","Open containers of alcohol or marijuana","Only open beer cans","Open containers only if the driver drank"],"h1":"The rule covers more than one substance.","h2":"In Colorado, it is against the law to have an open container of alcohol or an open container of marijuana in the passenger area of a vehicle on a public road.","p":"Right. No open alcohol or marijuana in the passenger area."},"es":{"q":"En Colorado, ¿qué envases abiertos no se permiten en el área de pasajeros de un vehículo en una vía pública?","o":["Solo botellas de licor abiertas","Envases abiertos de alcohol o de marihuana","Solo latas de cerveza abiertas","Solo si el conductor bebió"],"h1":"La regla cubre más de una sustancia.","h2":"En Colorado, es ilegal tener un envase abierto de alcohol o de marihuana en el área de pasajeros de un vehículo en una vía pública.","p":"Correcto. Nada de alcohol ni marihuana abiertos en el área de pasajeros."},"ref":{"doc":"CO","page":3}},{"id":"co-040","scope":"CO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Colorado, how soon must a new resident get a Colorado driver license?","o":["Within 10 days","Within 30 days","Within 90 days","Within one year"],"h1":"It is about one month.","h2":"In Colorado, a new resident must get a Colorado driver license within 30 days of becoming a resident, with a few exceptions such as active-duty military.","p":"Right. New residents have 30 days."},"es":{"q":"En Colorado, ¿en cuánto tiempo debe un nuevo residente obtener una licencia de Colorado?","o":["En 10 días","En 30 días","En 90 días","En un año"],"h1":"Es más o menos un mes.","h2":"En Colorado, un nuevo residente debe obtener una licencia de manejo de Colorado dentro de los 30 días de hacerse residente, con algunas excepciones como el personal militar en servicio activo.","p":"Correcto. Los nuevos residentes tienen 30 días."},"ref":{"doc":"CO","page":1}},{"id":"co-041","scope":"CO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Colorado, a teen applies for a license before age 16 and a half. What training must the teen also complete?","o":["A first aid class","A night driving class only","Nothing more than the driving log","6 hours behind the wheel with a driving instructor"],"h1":"It is time in the car with a professional teacher.","h2":"In Colorado, a teen younger than 16 and a half must also complete 6 hours of behind-the-wheel training with an approved driver education instructor.","p":"Right. Under 16 and a half, 6 hours with an instructor are needed."},"es":{"q":"En Colorado, un adolescente pide la licencia antes de cumplir 16 años y medio. ¿Qué entrenamiento debe completar además?","o":["Una clase de primeros auxilios","Solo una clase de manejo nocturno","Nada más que el registro de manejo","6 horas al volante con un instructor de manejo"],"h1":"Es tiempo en el carro con un maestro profesional.","h2":"En Colorado, un adolescente menor de 16 años y medio también debe completar 6 horas de práctica al volante con un instructor de educación vial aprobado.","p":"Correcto. Antes de los 16 años y medio, se necesitan 6 horas con un instructor."},"ref":{"doc":"CO","page":2}},{"id":"co-042","scope":"CO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Colorado, when must your headlights be on, besides from sunset to sunrise?","o":["When you cannot see clearly for 1,000 feet","Only when it is snowing","Only on the interstate","When you drive faster than 55 mph"],"h1":"Think about how far ahead you can see.","h2":"Colorado law requires headlights from sunset to sunrise and any time you cannot see clearly for 1,000 feet.","p":"Right. Lights on when you cannot see 1,000 feet."},"es":{"q":"En Colorado, además de la puesta a la salida del sol, ¿cuándo deben estar encendidas sus luces delanteras?","o":["Cuando no puede ver bien a 1,000 pies","Solo cuando está nevando","Solo en la autopista interestatal","Cuando maneja a más de 55 mph"],"h1":"Piense en qué tan lejos puede ver.","h2":"La ley de Colorado exige las luces delanteras desde la puesta hasta la salida del sol y siempre que usted no pueda ver bien a 1,000 pies.","p":"Correcto. Luces encendidas cuando no ve a 1,000 pies."},"ref":{"doc":"CO","page":16}},{"id":"co-043","scope":"CO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Colorado, you are using high beams at night. How close may an oncoming vehicle get before you must dim them?","o":["100 feet","1,000 feet","500 feet","50 feet"],"h1":"It is farther than the distance for a car you are following.","h2":"In Colorado, you must dim your high beams before you come within 500 feet of an oncoming vehicle.","p":"Right. Dim your lights within 500 feet of oncoming traffic."},"es":{"q":"En Colorado, usted usa las luces altas de noche. ¿A qué distancia de un vehículo que viene de frente debe bajarlas?","o":["100 pies","1,000 pies","500 pies","50 pies"],"h1":"Es más lejos que la distancia para un carro que usted sigue.","h2":"En Colorado, usted debe bajar las luces altas antes de acercarse a 500 pies de un vehículo que viene de frente.","p":"Correcto. Baje las luces a 500 pies del tráfico de frente."},"ref":{"doc":"CO","page":16}},{"id":"co-044","scope":"CO","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Colorado, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 15 feet","No closer than 30 feet","No closer than 50 feet"],"h1":"It is less than the distance for a stop sign.","h2":"In Colorado, you may not park within 15 feet of a fire hydrant.","p":"Right. Stay 15 feet from a fire hydrant."},"es":{"q":"En Colorado, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 15 pies","No más cerca de 30 pies","No más cerca de 50 pies"],"h1":"Es menos que la distancia para un letrero de alto.","h2":"En Colorado, no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese a 15 pies de un hidrante."},"ref":{"doc":"CO","page":13}},{"id":"co-045","scope":"CO","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Colorado, you may not park within how many feet before a stop sign or a traffic signal at the side of the road?","o":["10 feet","15 feet","20 feet","30 feet"],"h1":"It is double the fire hydrant distance.","h2":"In Colorado, you may not park within 30 feet before a stop sign or a traffic signal at the side of the road (near a railroad crossing the limit is 50 feet).","p":"Right. Keep 30 feet back from a stop sign or traffic signal."},"es":{"q":"En Colorado, ¿a menos de cuántos pies antes de un letrero de alto o un semáforo al lado de la calle no puede estacionarse?","o":["10 pies","15 pies","20 pies","30 pies"],"h1":"Es el doble de la distancia del hidrante.","h2":"En Colorado, no puede estacionarse a menos de 30 pies antes de un letrero de alto o un semáforo al lado de la calle (cerca de un cruce de tren el límite es de 50 pies).","p":"Correcto. Manténgase a 30 pies de un letrero de alto o un semáforo."},"ref":{"doc":"CO","page":13}},{"id":"co-046","scope":"CO","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Colorado, two cars meet on a steep mountain road too narrow for both. Who must usually yield?","o":["The car going downhill","The car going uphill","The smaller car","The car that honks last"],"h1":"Starting again on a steep hill is harder going up.","h2":"In Colorado, on a steep, narrow road, the vehicle going downhill must yield by backing up to a wider spot or stopping to let the uphill vehicle pass.","p":"Right. The downhill car yields to the uphill car."},"es":{"q":"En Colorado, dos carros se encuentran en un camino de montaña empinado y demasiado angosto para ambos. ¿Quién debe ceder el paso, por lo general?","o":["El carro que va cuesta abajo","El carro que va cuesta arriba","El carro más pequeño","El último que toca la bocina"],"h1":"Volver a arrancar en una cuesta es más difícil subiendo.","h2":"En Colorado, en un camino empinado y angosto, el vehículo que baja debe ceder el paso retrocediendo a un lugar más ancho o deteniéndose para dejar pasar al que sube.","p":"Correcto. El que baja cede el paso al que sube."},"ref":{"doc":"CO","page":11}},{"id":"co-047","scope":"CO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Colorado, several snow plows are clearing the highway together in a staggered, diagonal line. What does the law say?","o":["You may pass them on the right","You may pass after you honk","You may not pass them","You may pass if the road is dry"],"h1":"The plows make a wall of blowing snow across the lanes.","h2":"In Colorado, it is illegal to pass snow plows that are working together in a staggered formation, so you must stay behind them.","p":"Right. Do not pass plows working in formation."},"es":{"q":"En Colorado, varios quitanieves limpian la carretera juntos en una fila diagonal escalonada. ¿Qué dice la ley?","o":["Puede rebasarlos por la derecha","Puede rebasarlos después de tocar la bocina","No puede rebasarlos","Puede rebasarlos si el camino está seco"],"h1":"Los quitanieves forman una pared de nieve en los carriles.","h2":"En Colorado, es ilegal rebasar a quitanieves que trabajan juntos en formación escalonada, así que usted debe quedarse detrás de ellos.","p":"Correcto. No rebase a quitanieves que trabajan en formación."},"ref":{"doc":"CO","page":11}},{"id":"co-048","scope":"CO","cat":"signals","sign":null,"c":1,"en":{"q":"In Colorado, on a four-lane highway with a speed limit above 40 mph, how far ahead must you signal before turning or changing lanes?","o":["50 feet","200 feet","100 feet","500 feet"],"h1":"It is twice the distance used on city streets.","h2":"In Colorado, on a four-lane highway with a limit above 40 mph, you must signal for 200 feet before you turn or change lanes.","p":"Right. Signal for 200 feet on faster four-lane highways."},"es":{"q":"En Colorado, en una carretera de cuatro carriles con límite de más de 40 mph, ¿con cuánta anticipación debe poner la direccional antes de girar o cambiar de carril?","o":["50 pies","200 pies","100 pies","500 pies"],"h1":"Es el doble de la distancia que se usa en las calles de la ciudad.","h2":"En Colorado, en una carretera de cuatro carriles con límite de más de 40 mph, debe poner la direccional durante 200 pies antes de girar o cambiar de carril.","p":"Correcto. Direccional por 200 pies en carreteras rápidas de cuatro carriles."},"ref":{"doc":"CO","page":12}},{"id":"co-049","scope":"CO","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Colorado, what is the least space you must leave when you pass a bicyclist?","o":["1 foot","2 feet","10 feet","3 feet"],"h1":"Count from the outer edge of your car, including the mirrors.","h2":"In Colorado, you must leave at least 3 feet between the bicyclist and the outermost part of your vehicle, and you may briefly cross a solid yellow line to do it when no traffic is coming.","p":"Right. Give a bicyclist at least 3 feet."},"es":{"q":"En Colorado, ¿cuál es el espacio mínimo que debe dejar al rebasar a un ciclista?","o":["1 pie","2 pies","10 pies","3 pies"],"h1":"Cuente desde la parte más exterior de su carro, incluidos los espejos.","h2":"En Colorado, debe dejar por lo menos 3 pies entre el ciclista y la parte más exterior de su vehículo, y puede cruzar brevemente una línea amarilla continua para lograrlo si no viene tráfico.","p":"Correcto. Deje al ciclista por lo menos 3 pies."},"ref":{"doc":"CO","page":15}},{"id":"co-050","scope":"CO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Colorado, you have a minor crash on a divided highway. No one is hurt, no alcohol or drugs are involved, and the cars can be driven. What must you do?","o":["Move the cars off the highway","Leave the cars where they stopped","Wait in the cars for police","Drive home and call later"],"h1":"Colorado has a law named for what you should do with the cars.","h2":"Under Colorado's Move It law, after a minor crash on a divided highway with no injuries, no alcohol or drugs, and drivable cars, you must move the vehicles off the highway, then exchange information and notify police.","p":"Right. Move it off the highway, then share information."},"es":{"q":"En Colorado, usted tiene un choque menor en una carretera dividida. Nadie está herido, no hay alcohol ni drogas, y los carros se pueden manejar. ¿Qué debe hacer?","o":["Sacar los carros de la carretera","Dejar los carros donde quedaron","Esperar en los carros a la policía","Irse a casa y llamar después"],"h1":"Colorado tiene una ley con el nombre de lo que debe hacer con los carros.","h2":"Según la ley Move It de Colorado, después de un choque menor en una carretera dividida, sin heridos, sin alcohol ni drogas y con carros que se pueden manejar, usted debe sacar los vehículos de la carretera y luego intercambiar datos y avisar a la policía.","p":"Correcto. Saque los carros de la carretera y luego intercambie datos."},"ref":{"doc":"CO","page":25}},{"id":"co-051","scope":"CO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Colorado, when the traction law is active, how much tread must the tires on an all-wheel or four-wheel drive vehicle have?","o":["1/16 inch","2/32 inch","3/16 inch","Any tread is enough"],"h1":"Snow driving needs deep grooves, much more than the bare legal minimum.","h2":"In Colorado, when the traction law is active, an all-wheel or four-wheel drive vehicle without chains needs snow-rated or all-weather tires with at least 3/16 inch of tread.","p":"Right. The traction law needs 3/16 inch of tread."},"es":{"q":"En Colorado, cuando la ley de tracción está activa, ¿cuánta profundidad de dibujo deben tener las llantas de un vehículo con tracción integral o en las cuatro ruedas?","o":["1/16 de pulgada","2/32 de pulgada","3/16 de pulgada","Cualquier dibujo es suficiente"],"h1":"Manejar en nieve necesita surcos profundos, mucho más que el mínimo legal.","h2":"En Colorado, cuando la ley de tracción está activa, un vehículo con tracción integral o en las cuatro ruedas sin cadenas necesita llantas para nieve o para todo clima con al menos 3/16 de pulgada de dibujo.","p":"Correcto. La ley de tracción exige 3/16 de pulgada de dibujo."},"ref":{"doc":"CO","page":null}},{"id":"ct-001","scope":"CT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Connecticut, what is the youngest age to get a learner's permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is the age when many teens in other states can already get a license.","h2":"In Connecticut you must be at least 16 years old to get a learner's permit.","p":"Right. The Connecticut learner's permit starts at 16."},"es":{"q":"En Connecticut, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es la edad en que muchos jóvenes de otros estados ya pueden obtener la licencia.","h2":"En Connecticut usted debe tener por lo menos 16 años para obtener un permiso de aprendiz.","p":"Correcto. El permiso de aprendiz en Connecticut empieza a los 16."},"zh":{"q":"在 Connecticut，最小几岁可以拿到学习驾照？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"在其他很多州，青少年到这个年龄已经可以拿正式驾照了。","h2":"在 Connecticut，你必须至少 16 岁才能拿到学习驾照。","p":"对。Connecticut 的学习驾照从 16 岁开始。"},"vi":{"q":"Ở Connecticut, tuổi nhỏ nhất để lấy giấy phép tập lái (learner's permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là tuổi mà nhiều thiếu niên ở các tiểu bang khác đã có thể lấy bằng lái.","h2":"Ở Connecticut, bạn phải ít nhất 16 tuổi để lấy giấy phép tập lái.","p":"Đúng. Giấy phép tập lái ở Connecticut bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Connecticut, ano ang pinakabatang edad para makakuha ng learner's permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Ito ang edad kung kailan maraming teenager sa ibang estado ay puwede nang kumuha ng lisensya.","h2":"Sa Connecticut, dapat ay hindi bababa sa 16 taong gulang ka para makakuha ng learner's permit.","p":"Tama. Nagsisimula ang learner's permit sa Connecticut sa edad na 16."},"ar":{"q":"في Connecticut، ما أصغر عمر للحصول على تصريح التعلّم (learner's permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هو العمر الذي يستطيع فيه كثير من المراهقين في ولايات أخرى الحصول على رخصة القيادة.","h2":"في Connecticut يجب أن يكون عمرك 16 سنة على الأقل للحصول على تصريح التعلّم.","p":"صحيح. يبدأ تصريح التعلّم في Connecticut في عمر 16 سنة."},"ref":{"doc":"CT","page":5}},{"id":"ct-002","scope":"CT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Connecticut, who may ride with a driver who holds a learner's permit?","o":["Only the qualified trainer, and parents or others with a driving instructor","Any friend who has a license","Up to three passengers of any age","Anyone, as long as all wear seat belts"],"h1":"The permit is only for practice with a teacher.","h2":"A Connecticut permit holder may carry only the person giving instruction, plus parents or others riding with a licensed driving instructor.","p":"Right. A permit driver rides only with the trainer and the few people the law allows."},"es":{"q":"En Connecticut, ¿quién puede viajar con un conductor que tiene permiso de aprendiz?","o":["Solo el instructor calificado, y los padres u otras personas con un instructor de manejo","Cualquier amigo que tenga licencia","Hasta tres pasajeros de cualquier edad","Cualquier persona, si todos usan el cinturón"],"h1":"El permiso es solo para practicar con un maestro.","h2":"En Connecticut, quien tiene permiso de aprendiz solo puede llevar a la persona que le enseña, y a los padres u otras personas que viajan con un instructor de manejo con licencia.","p":"Correcto. El aprendiz solo viaja con su instructor y las pocas personas que permite la ley."},"zh":{"q":"在 Connecticut，谁可以坐持学习驾照的司机的车？","o":["只有合格的指导人，以及有驾驶教练同车时的父母或其他人","任何有驾照的朋友","最多三位任何年龄的乘客","任何人，只要都系好安全带"],"h1":"学习驾照只是用来和老师一起练习的。","h2":"Connecticut 持学习驾照的人只能载正在指导他的人，以及和有执照的驾驶教练同车的父母或其他人。","p":"对。持学习驾照的司机只能载指导人和法律允许的少数几个人。"},"vi":{"q":"Ở Connecticut, ai được phép đi cùng xe với người lái có giấy phép tập lái (learner's permit)?","o":["Chỉ người hướng dẫn đủ điều kiện, và cha mẹ hoặc người khác khi có giáo viên dạy lái xe","Bất kỳ người bạn nào có bằng lái","Tối đa ba hành khách ở mọi lứa tuổi","Bất kỳ ai, miễn là mọi người đều thắt dây an toàn"],"h1":"Giấy phép này chỉ dùng để tập lái với người dạy.","h2":"Ở Connecticut, người có giấy phép tập lái chỉ được chở người đang hướng dẫn lái, cùng với cha mẹ hoặc người khác khi đi với giáo viên dạy lái xe có giấy phép.","p":"Đúng. Người tập lái chỉ đi cùng người hướng dẫn và vài người mà luật cho phép."},"tl":{"q":"Sa Connecticut, sino ang puwedeng sumakay kasama ng driver na may learner's permit?","o":["Ang qualified trainer lang, at ang mga magulang o iba pa kapag may kasamang driving instructor","Kahit sinong kaibigan na may lisensya","Hanggang tatlong pasahero kahit anong edad","Kahit sino, basta lahat ay naka-seat belt"],"h1":"Ang permit ay para lang sa pagsasanay kasama ang isang guro.","h2":"Sa Connecticut, ang may permit ay puwede lang magsakay ng taong nagtuturo sa kanya, pati ang mga magulang o iba pa kapag kasama ang isang lisensyadong driving instructor.","p":"Tama. Ang driver na may permit ay sumasakay lang kasama ang trainer at ang ilang taong pinapayagan ng batas."},"ar":{"q":"في Connecticut، من يُسمح له بالركوب مع سائق يحمل تصريح التعلّم (learner's permit)؟","o":["المدرّب المؤهَّل فقط، والوالدان أو غيرهم عند وجود مدرّب قيادة","أي صديق لديه رخصة","حتى ثلاثة ركاب من أي عمر","أي شخص، ما دام الجميع يربطون حزام الأمان"],"h1":"التصريح هو للتدريب مع معلّم فقط.","h2":"في Connecticut لا يجوز لحامل تصريح التعلّم أن يُركب معه إلا الشخص الذي يعلّمه، بالإضافة إلى الوالدين أو غيرهم عند الركوب مع مدرّب قيادة مرخَّص.","p":"صحيح. سائق التصريح يركب فقط مع المدرّب ومع عدد قليل من الأشخاص الذين يسمح بهم القانون."},"ref":{"doc":"CT","page":6}},{"id":"ct-003","scope":"CT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Connecticut, how old must a non-professional person be to give driving instruction to a permit holder?","o":["At least 18","At least 25","At least 21","At least 20"],"h1":"It is a little younger than the age most states ask for.","h2":"In Connecticut the person who gives instruction must be at least 20 years old, unless it is a licensed driving instructor.","p":"Right. A Connecticut trainer must be 20 or older."},"es":{"q":"En Connecticut, ¿qué edad debe tener una persona que no es instructor profesional para enseñar a manejar a quien tiene permiso?","o":["Por lo menos 18","Por lo menos 25","Por lo menos 21","Por lo menos 20"],"h1":"Es un poco menos que la edad que piden la mayoría de los estados.","h2":"En Connecticut, la persona que enseña debe tener por lo menos 20 años, salvo que sea un instructor de manejo con licencia.","p":"Correcto. En Connecticut el instructor debe tener 20 años o más."},"zh":{"q":"在 Connecticut，不是专业教练的人要几岁才能指导持学习驾照的人开车？","o":["至少 18 岁","至少 25 岁","至少 21 岁","至少 20 岁"],"h1":"它比大多数州要求的年龄小一点。","h2":"在 Connecticut，指导开车的人必须至少 20 岁，有执照的驾驶教练除外。","p":"对。Connecticut 的指导人必须 20 岁或以上。"},"vi":{"q":"Ở Connecticut, một người không phải giáo viên chuyên nghiệp phải bao nhiêu tuổi để được dạy lái xe cho người có giấy phép tập lái?","o":["Ít nhất 18 tuổi","Ít nhất 25 tuổi","Ít nhất 21 tuổi","Ít nhất 20 tuổi"],"h1":"Tuổi này trẻ hơn một chút so với tuổi mà phần lớn các tiểu bang yêu cầu.","h2":"Ở Connecticut, người hướng dẫn lái xe phải ít nhất 20 tuổi, trừ khi đó là giáo viên dạy lái xe có giấy phép.","p":"Đúng. Người hướng dẫn ở Connecticut phải từ 20 tuổi trở lên."},"tl":{"q":"Sa Connecticut, ilang taon dapat ang isang taong hindi propesyonal para makapagturo ng pagmamaneho sa may permit?","o":["Hindi bababa sa 18","Hindi bababa sa 25","Hindi bababa sa 21","Hindi bababa sa 20"],"h1":"Medyo mas bata ito kaysa sa edad na hinihingi ng karamihan ng estado.","h2":"Sa Connecticut, ang taong nagtuturo ay dapat hindi bababa sa 20 taong gulang, maliban kung siya ay lisensyadong driving instructor.","p":"Tama. Ang trainer sa Connecticut ay dapat 20 taong gulang o higit pa."},"ar":{"q":"في Connecticut، كم يجب أن يكون عمر الشخص غير المحترف حتى يعلّم القيادة لحامل التصريح؟","o":["18 سنة على الأقل","25 سنة على الأقل","21 سنة على الأقل","20 سنة على الأقل"],"h1":"هو أصغر قليلًا من العمر الذي تطلبه معظم الولايات.","h2":"في Connecticut يجب أن يكون عمر الشخص الذي يعلّم القيادة 20 سنة على الأقل، إلا إذا كان مدرّب قيادة مرخَّصًا.","p":"صحيح. يجب أن يكون المدرّب في Connecticut في عمر 20 سنة أو أكثر."},"ref":{"doc":"CT","page":6}},{"id":"ct-004","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, for how long must the person teaching a permit holder have held a driver's license?","o":["At least one year","At least four years in a row","At least ten years","Any amount of time"],"h1":"It is more than a few years, with no suspension in that time.","h2":"In Connecticut the trainer must have held a license for at least four years in a row, with no suspension in those four years.","p":"Right. Four clean years of licensing are required."},"es":{"q":"En Connecticut, ¿por cuánto tiempo debe haber tenido licencia la persona que enseña a quien tiene permiso?","o":["Por lo menos un año","Por lo menos cuatro años seguidos","Por lo menos diez años","Cualquier tiempo"],"h1":"Son varios años, sin ninguna suspensión en ese tiempo.","h2":"En Connecticut el instructor debe haber tenido licencia por lo menos cuatro años seguidos, sin suspensión en esos cuatro años.","p":"Correcto. Se requieren cuatro años de licencia sin suspensión."},"zh":{"q":"在 Connecticut，指导持学习驾照的人开车的人，必须持有驾照多久？","o":["至少一年","连续至少四年","至少十年","多久都可以"],"h1":"它不止几年，而且这段时间里驾照没有被暂停过。","h2":"在 Connecticut，指导人必须连续持有驾照至少四年，而且这四年里驾照没有被暂停过。","p":"对。需要四年没有问题的驾照记录。"},"vi":{"q":"Ở Connecticut, người dạy lái cho người có giấy phép tập lái phải có bằng lái trong bao lâu?","o":["Ít nhất một năm","Ít nhất bốn năm liên tục","Ít nhất mười năm","Bao lâu cũng được"],"h1":"Đó là hơn vài năm, và không bị treo bằng trong thời gian đó.","h2":"Ở Connecticut, người hướng dẫn phải có bằng lái ít nhất bốn năm liên tục và không bị treo bằng trong bốn năm đó.","p":"Đúng. Cần có bằng lái bốn năm không vi phạm."},"tl":{"q":"Sa Connecticut, gaano katagal dapat may lisensya ang taong nagtuturo sa may permit?","o":["Hindi bababa sa isang taon","Hindi bababa sa apat na taon nang tuloy-tuloy","Hindi bababa sa sampung taon","Kahit gaano katagal"],"h1":"Higit ito sa ilang taon, at walang suspensyon sa panahong iyon.","h2":"Sa Connecticut, ang trainer ay dapat may lisensya nang hindi bababa sa apat na taon nang tuloy-tuloy, at walang suspensyon sa apat na taong iyon.","p":"Tama. Kailangan ang apat na taon ng malinis na lisensya."},"ar":{"q":"في Connecticut، كم مدة يجب أن يكون الشخص الذي يعلّم حامل التصريح قد حمل رخصة قيادة؟","o":["سنة واحدة على الأقل","أربع سنوات متتالية على الأقل","عشر سنوات على الأقل","أي مدة"],"h1":"هي أكثر من بضع سنوات، دون إيقاف للرخصة في تلك المدة.","h2":"في Connecticut يجب أن يكون المدرّب قد حمل رخصة القيادة أربع سنوات متتالية على الأقل، دون إيقاف للرخصة في تلك السنوات الأربع.","p":"صحيح. يجب أن تكون هناك أربع سنوات من الرخصة دون مخالفات."},"ref":{"doc":"CT","page":6}},{"id":"ct-005","scope":"CT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Connecticut, may a 17-year-old driver talk on a phone with a hands-free device?","o":["Yes, hands-free is always allowed","Yes, but only on highways","No, drivers under 18 may not use a phone at all while driving","Yes, if a parent is in the car"],"h1":"Young drivers have a stricter rule than adults.","h2":"In Connecticut a driver under 18 may not use a cell phone or other mobile electronic device while driving, even with a hands-free accessory.","p":"Right. Under 18, no phone at all while driving."},"es":{"q":"En Connecticut, ¿puede un conductor de 17 años hablar por teléfono con un dispositivo de manos libres?","o":["Sí, manos libres siempre está permitido","Sí, pero solo en carreteras","No, los menores de 18 no pueden usar el teléfono mientras manejan","Sí, si uno de sus padres va en el carro"],"h1":"Los conductores jóvenes tienen una regla más estricta que los adultos.","h2":"En Connecticut un conductor menor de 18 años no puede usar un celular ni otro aparato electrónico móvil mientras maneja, aunque sea con manos libres.","p":"Correcto. Antes de los 18, nada de teléfono al manejar."},"zh":{"q":"在 Connecticut，17 岁的司机可以用免持设备打电话吗？","o":["可以，免持总是允许的","可以，但只在公路上","不可以，18 岁以下的司机开车时完全不能用手机","可以，如果父母在车里"],"h1":"年轻司机的规定比成年人更严。","h2":"在 Connecticut，18 岁以下的司机开车时不能用手机或其他移动电子设备，即使用免持配件也不行。","p":"对。18 岁以下，开车时完全不能用手机。"},"vi":{"q":"Ở Connecticut, người lái xe 17 tuổi có được nói chuyện điện thoại bằng thiết bị rảnh tay (hands-free) không?","o":["Có, rảnh tay thì luôn được phép","Có, nhưng chỉ trên xa lộ","Không, người lái dưới 18 tuổi hoàn toàn không được dùng điện thoại khi lái xe","Có, nếu có cha mẹ trong xe"],"h1":"Người lái trẻ có luật nghiêm hơn người lớn.","h2":"Ở Connecticut, người lái dưới 18 tuổi không được dùng điện thoại di động hay thiết bị điện tử di động khác khi lái xe, kể cả khi có thiết bị rảnh tay.","p":"Đúng. Dưới 18 tuổi thì hoàn toàn không dùng điện thoại khi lái xe."},"tl":{"q":"Sa Connecticut, puwede bang makipag-usap sa telepono ang 17 taong gulang na driver gamit ang hands-free na device?","o":["Oo, laging pinapayagan ang hands-free","Oo, pero sa highway lang","Hindi, ang mga driver na wala pang 18 ay bawal gumamit ng telepono habang nagmamaneho","Oo, kung may magulang sa kotse"],"h1":"Mas mahigpit ang patakaran para sa mga batang driver kaysa sa matatanda.","h2":"Sa Connecticut, ang driver na wala pang 18 taong gulang ay bawal gumamit ng cell phone o ibang mobile electronic device habang nagmamaneho, kahit may hands-free na gamit.","p":"Tama. Kapag wala pang 18, walang telepono habang nagmamaneho."},"ar":{"q":"في Connecticut، هل يجوز لسائق عمره 17 سنة أن يتحدث في الهاتف بجهاز لا يحتاج إلى اليدين (hands-free)؟","o":["نعم، الجهاز الذي لا يحتاج إلى اليدين مسموح دائمًا","نعم، ولكن على الطرق السريعة فقط","لا، السائقون تحت 18 سنة لا يجوز لهم استخدام الهاتف أبدًا أثناء القيادة","نعم، إذا كان أحد الوالدين في السيارة"],"h1":"للسائقين الصغار قاعدة أشدّ من الكبار.","h2":"في Connecticut لا يجوز للسائق تحت 18 سنة أن يستخدم الهاتف المحمول أو أي جهاز إلكتروني محمول آخر أثناء القيادة، حتى مع ملحق لا يحتاج إلى اليدين.","p":"صحيح. تحت 18 سنة، لا هاتف أبدًا أثناء القيادة."},"ref":{"doc":"CT","page":8}},{"id":"ct-006","scope":"CT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Connecticut, what does the law say about adult drivers and hand-held phones?","o":["Using a hand-held phone or device while driving is not allowed","Hand-held phones are allowed at red lights","Hand-held phones are allowed below 30 mph","There is no rule for adults"],"h1":"Adults may still talk, but not with the device in hand.","h2":"In Connecticut no driver may use a hand-held mobile electronic device while driving.","p":"Right. Put the phone down while you drive."},"es":{"q":"En Connecticut, ¿qué dice la ley sobre los conductores adultos y los teléfonos en la mano?","o":["No se permite usar un teléfono o aparato en la mano mientras maneja","Se permite en los semáforos en rojo","Se permite por debajo de 30 mph","No hay ninguna regla para adultos"],"h1":"Los adultos pueden hablar, pero sin tener el aparato en la mano.","h2":"En Connecticut ningún conductor puede usar un aparato electrónico móvil en la mano mientras maneja.","p":"Correcto. Deje el teléfono mientras maneja."},"zh":{"q":"在 Connecticut，法律对成年司机和手持电话有什么规定？","o":["开车时不能用手持电话或设备","红灯时可以用手持电话","低于 30 mph 时可以用手持电话","对成年人没有规定"],"h1":"成年人还是可以打电话，但设备不能拿在手里。","h2":"在 Connecticut，任何司机开车时都不能用手持移动电子设备。","p":"对。开车时把手机放下。"},"vi":{"q":"Ở Connecticut, luật nói gì về người lái xe trưởng thành và điện thoại cầm tay?","o":["Không được dùng điện thoại hoặc thiết bị cầm tay khi lái xe","Được dùng điện thoại cầm tay khi dừng đèn đỏ","Được dùng điện thoại cầm tay khi chạy dưới 30 mph","Không có luật nào cho người lớn"],"h1":"Người lớn vẫn có thể nói chuyện, nhưng không được cầm thiết bị trên tay.","h2":"Ở Connecticut, không người lái xe nào được dùng thiết bị điện tử di động cầm tay khi đang lái xe.","p":"Đúng. Hãy để điện thoại xuống khi bạn lái xe."},"tl":{"q":"Sa Connecticut, ano ang sinasabi ng batas tungkol sa mga adult na driver at hand-held na telepono?","o":["Bawal gumamit ng hand-held na telepono o device habang nagmamaneho","Pinapayagan ang hand-held na telepono sa pulang ilaw","Pinapayagan ang hand-held na telepono kapag mas mababa sa 30 mph","Walang patakaran para sa mga adult"],"h1":"Puwede pa ring makipag-usap ang mga adult, pero hindi hawak ang device.","h2":"Sa Connecticut, walang driver ang puwedeng gumamit ng hand-held na mobile electronic device habang nagmamaneho.","p":"Tama. Ibaba ang telepono habang nagmamaneho."},"ar":{"q":"في Connecticut، ماذا يقول القانون عن السائقين البالغين والهواتف المحمولة باليد؟","o":["لا يجوز استخدام هاتف أو جهاز محمول باليد أثناء القيادة","الهواتف المحمولة باليد مسموحة عند الإشارة الحمراء","الهواتف المحمولة باليد مسموحة تحت 30 mph","لا توجد قاعدة للبالغين"],"h1":"يمكن للبالغين أن يتحدثوا، لكن دون أن يمسكوا الجهاز بأيديهم.","h2":"في Connecticut لا يجوز لأي سائق أن يستخدم جهازًا إلكترونيًا محمولًا باليد أثناء القيادة.","p":"صحيح. ضع الهاتف جانبًا أثناء القيادة."},"ref":{"doc":"CT","page":11}},{"id":"ct-007","scope":"CT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Connecticut, what is the fine for a first offense of using a hand-held phone while driving?","o":["$50","$200","$625","$1,000"],"h1":"The fine goes up to $375 and then $625 for later offenses.","h2":"In Connecticut a first hand-held phone offense costs $200, and the fine is higher for each later offense.","p":"Right. The first offense is $200."},"es":{"q":"En Connecticut, ¿cuál es la multa por la primera vez que se usa un teléfono en la mano mientras se maneja?","o":["$50","$200","$625","$1,000"],"h1":"La multa sube a $375 y después a $625 en las siguientes infracciones.","h2":"En Connecticut la primera infracción por usar el teléfono en la mano cuesta $200, y la multa es más alta en cada infracción siguiente.","p":"Correcto. La primera infracción cuesta $200."},"zh":{"q":"在 Connecticut，第一次开车时用手持电话，罚款是多少？","o":["$50","$200","$625","$1,000"],"h1":"以后再犯，罚款会提高到 $375，然后是 $625。","h2":"在 Connecticut，第一次用手持电话违规罚 $200，以后每次再犯罚款都更高。","p":"对。第一次违规是 $200。"},"vi":{"q":"Ở Connecticut, tiền phạt cho lần vi phạm đầu tiên vì dùng điện thoại cầm tay khi lái xe là bao nhiêu?","o":["$50","$200","$625","$1,000"],"h1":"Tiền phạt tăng lên $375 rồi $625 cho các lần vi phạm sau.","h2":"Ở Connecticut, lần vi phạm đầu tiên vì dùng điện thoại cầm tay bị phạt $200, và tiền phạt cao hơn cho mỗi lần vi phạm sau.","p":"Đúng. Lần vi phạm đầu tiên bị phạt $200."},"tl":{"q":"Sa Connecticut, magkano ang multa sa unang paglabag sa paggamit ng hand-held na telepono habang nagmamaneho?","o":["$50","$200","$625","$1,000"],"h1":"Tumataas ang multa sa $375 at pagkatapos ay $625 sa mga susunod na paglabag.","h2":"Sa Connecticut, ang unang paglabag sa paggamit ng hand-held na telepono ay $200, at mas mataas ang multa sa bawat susunod na paglabag.","p":"Tama. $200 ang unang paglabag."},"ar":{"q":"في Connecticut، ما الغرامة على المخالفة الأولى لاستخدام هاتف محمول باليد أثناء القيادة؟","o":["$50","$200","$625","$1,000"],"h1":"ترتفع الغرامة إلى $375 ثم إلى $625 في المخالفات التالية.","h2":"في Connecticut تكون غرامة المخالفة الأولى لاستخدام الهاتف المحمول باليد $200، وتزيد الغرامة في كل مخالفة بعدها.","p":"صحيح. غرامة المخالفة الأولى $200."},"ref":{"doc":"CT","page":null}},{"id":"ct-008","scope":"CT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Connecticut, during the first six months with a license, who may a 16- or 17-year-old driver carry as passengers?","o":["Up to two friends","Any family member or friend","Anyone over 16","Only a driving instructor, a parent or guardian, or one qualified trainer age 20 or older"],"h1":"It is the same short list as during the permit.","h2":"In Connecticut, for the first six months, a newly licensed 16- or 17-year-old may carry only a driving instructor, a parent or guardian, or one qualified trainer age 20 or older.","p":"Right. The first six months are almost passenger-free."},"es":{"q":"En Connecticut, durante los primeros seis meses con licencia, ¿a quién puede llevar como pasajero un conductor de 16 o 17 años?","o":["Hasta dos amigos","Cualquier familiar o amigo","Cualquier persona mayor de 16","Solo un instructor de manejo, sus padres o tutor, o un instructor calificado de 20 años o más"],"h1":"Es la misma lista corta que durante el permiso.","h2":"En Connecticut, durante los primeros seis meses, un conductor de 16 o 17 años con licencia nueva solo puede llevar a un instructor de manejo, a sus padres o tutor, o a un instructor calificado de 20 años o más.","p":"Correcto. Los primeros seis meses son casi sin pasajeros."},"zh":{"q":"在 Connecticut，拿到驾照的前六个月，16 岁或 17 岁的司机可以载谁？","o":["最多两位朋友","任何家人或朋友","任何 16 岁以上的人","只有驾驶教练、父母或监护人，或一位 20 岁或以上的合格指导人"],"h1":"它和持学习驾照时的短名单一样。","h2":"在 Connecticut，前六个月，刚拿到驾照的 16 岁或 17 岁司机只能载驾驶教练、父母或监护人，或一位 20 岁或以上的合格指导人。","p":"对。前六个月几乎不能载乘客。"},"vi":{"q":"Ở Connecticut, trong sáu tháng đầu có bằng lái, người lái 16 hoặc 17 tuổi được chở ai?","o":["Tối đa hai người bạn","Bất kỳ người nhà hay bạn bè nào","Bất kỳ ai trên 16 tuổi","Chỉ giáo viên dạy lái xe, cha mẹ hoặc người giám hộ, hoặc một người hướng dẫn đủ điều kiện từ 20 tuổi trở lên"],"h1":"Đó là cùng một danh sách ngắn như khi còn giấy phép tập lái.","h2":"Ở Connecticut, trong sáu tháng đầu, người mới có bằng lái 16 hoặc 17 tuổi chỉ được chở giáo viên dạy lái xe, cha mẹ hoặc người giám hộ, hoặc một người hướng dẫn đủ điều kiện từ 20 tuổi trở lên.","p":"Đúng. Sáu tháng đầu gần như không được chở hành khách."},"tl":{"q":"Sa Connecticut, sa unang anim na buwan na may lisensya, sino ang puwedeng isakay ng 16 o 17 taong gulang na driver?","o":["Hanggang dalawang kaibigan","Kahit sinong kapamilya o kaibigan","Kahit sinong lampas 16","Driving instructor lang, magulang o guardian, o isang qualified trainer na 20 taong gulang o higit pa"],"h1":"Ito rin ang maikling listahan noong may permit pa.","h2":"Sa Connecticut, sa unang anim na buwan, ang bagong may lisensya na 16 o 17 taong gulang ay puwede lang magsakay ng driving instructor, magulang o guardian, o isang qualified trainer na 20 taong gulang o higit pa.","p":"Tama. Halos walang pasahero sa unang anim na buwan."},"ar":{"q":"في Connecticut، خلال الأشهر الستة الأولى بعد الحصول على الرخصة، من يجوز للسائق الذي عمره 16 أو 17 سنة أن يُركبه معه؟","o":["حتى صديقين","أي فرد من العائلة أو صديق","أي شخص فوق 16 سنة","مدرّب القيادة فقط، أو أحد الوالدين أو الوصي، أو مدرّب مؤهَّل واحد عمره 20 سنة أو أكثر"],"h1":"هي نفس القائمة القصيرة التي كانت في فترة التصريح.","h2":"في Connecticut، خلال الأشهر الستة الأولى، لا يجوز للسائق الجديد الذي عمره 16 أو 17 سنة أن يُركب معه إلا مدرّب القيادة، أو أحد الوالدين أو الوصي، أو مدرّبًا مؤهَّلًا واحدًا عمره 20 سنة أو أكثر.","p":"صحيح. الأشهر الستة الأولى تكون تقريبًا بلا ركاب."},"ref":{"doc":"CT","page":8}},{"id":"ct-009","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, in the second six months with a license, who else may a 16- or 17-year-old driver carry?","o":["Up to three friends","Members of the driver's immediate family","Any classmate","No one at all"],"h1":"The rule opens a little, but only for people at home.","h2":"In Connecticut, in the second six months, a 16- or 17-year-old driver may also carry members of their immediate family.","p":"Right. Immediate family may ride in the second six months."},"es":{"q":"En Connecticut, en los segundos seis meses con licencia, ¿a quién más puede llevar un conductor de 16 o 17 años?","o":["Hasta tres amigos","A miembros de su familia inmediata","A cualquier compañero de clase","A nadie"],"h1":"La regla se abre un poco, pero solo para la gente de su casa.","h2":"En Connecticut, en los segundos seis meses, un conductor de 16 o 17 años también puede llevar a miembros de su familia inmediata.","p":"Correcto. La familia inmediata puede viajar en los segundos seis meses."},"zh":{"q":"在 Connecticut，拿到驾照的第二个六个月，16 岁或 17 岁的司机还可以载谁？","o":["最多三位朋友","司机的直系家人","任何同学","谁都不行"],"h1":"规定放宽一点，但只限家里的人。","h2":"在 Connecticut，第二个六个月，16 岁或 17 岁的司机也可以载自己的直系家人。","p":"对。第二个六个月可以载直系家人。"},"vi":{"q":"Ở Connecticut, trong sáu tháng thứ hai có bằng lái, người lái 16 hoặc 17 tuổi được chở thêm ai?","o":["Tối đa ba người bạn","Người trong gia đình ruột thịt của người lái","Bất kỳ bạn cùng lớp nào","Không ai cả"],"h1":"Luật nới ra một chút, nhưng chỉ cho người trong nhà.","h2":"Ở Connecticut, trong sáu tháng thứ hai, người lái 16 hoặc 17 tuổi cũng được chở người trong gia đình ruột thịt của mình.","p":"Đúng. Gia đình ruột thịt được đi cùng trong sáu tháng thứ hai."},"tl":{"q":"Sa Connecticut, sa ikalawang anim na buwan na may lisensya, sino pa ang puwedeng isakay ng 16 o 17 taong gulang na driver?","o":["Hanggang tatlong kaibigan","Mga miyembro ng malapit na pamilya (immediate family) ng driver","Kahit sinong kaklase","Wala talaga"],"h1":"Lumuluwag nang kaunti ang patakaran, pero para lang sa mga taong kasama sa bahay.","h2":"Sa Connecticut, sa ikalawang anim na buwan, puwede ring isakay ng 16 o 17 taong gulang na driver ang mga miyembro ng kanyang malapit na pamilya.","p":"Tama. Puwedeng sumakay ang malapit na pamilya sa ikalawang anim na buwan."},"ar":{"q":"في Connecticut، في الأشهر الستة الثانية بعد الحصول على الرخصة، من يجوز أيضًا للسائق الذي عمره 16 أو 17 سنة أن يُركبه معه؟","o":["حتى ثلاثة أصدقاء","أفراد العائلة المباشرة للسائق","أي زميل في الصف","لا أحد أبدًا"],"h1":"تصبح القاعدة أسهل قليلًا، ولكن فقط لأهل البيت.","h2":"في Connecticut، في الأشهر الستة الثانية، يجوز للسائق الذي عمره 16 أو 17 سنة أن يُركب معه أيضًا أفراد عائلته المباشرة.","p":"صحيح. يمكن للعائلة المباشرة أن تركب في الأشهر الستة الثانية."},"ref":{"doc":"CT","page":8}},{"id":"ct-010","scope":"CT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Connecticut, during which hours may a licensed 16- or 17-year-old not drive, except for reasons such as work, school or a medical emergency?","o":["9 p.m. to 6 a.m.","Midnight to 6 a.m.","11 p.m. to 5 a.m.","1 a.m. to 5 a.m."],"h1":"It starts one hour before midnight.","h2":"In Connecticut a licensed 16- or 17-year-old may not drive from 11 p.m. to 5 a.m., except for work, school, religious activities or a medical emergency.","p":"Right. The teen curfew is 11 p.m. to 5 a.m."},"es":{"q":"En Connecticut, ¿en qué horario no puede manejar un joven de 16 o 17 años con licencia, salvo por trabajo, escuela o una emergencia médica?","o":["De 9 p.m. a 6 a.m.","De medianoche a 6 a.m.","De 11 p.m. a 5 a.m.","De 1 a.m. a 5 a.m."],"h1":"Empieza una hora antes de la medianoche.","h2":"En Connecticut un joven de 16 o 17 años con licencia no puede manejar de 11 p.m. a 5 a.m., salvo por trabajo, escuela, actividades religiosas o una emergencia médica.","p":"Correcto. El horario restringido es de 11 p.m. a 5 a.m."},"zh":{"q":"在 Connecticut，有驾照的 16 岁或 17 岁司机在哪段时间不能开车（工作、上学或医疗紧急情况等理由除外）？","o":["晚上 9 点到早上 6 点","午夜到早上 6 点","晚上 11 点到早上 5 点","凌晨 1 点到早上 5 点"],"h1":"它在午夜前一小时开始。","h2":"在 Connecticut，有驾照的 16 岁或 17 岁司机在晚上 11 点到早上 5 点不能开车，工作、上学、宗教活动或医疗紧急情况除外。","p":"对。青少年的宵禁是晚上 11 点到早上 5 点。"},"vi":{"q":"Ở Connecticut, người lái có bằng 16 hoặc 17 tuổi không được lái xe trong khung giờ nào, trừ các lý do như đi làm, đi học hoặc cấp cứu y tế?","o":["9 giờ tối đến 6 giờ sáng","Nửa đêm đến 6 giờ sáng","11 giờ tối đến 5 giờ sáng","1 giờ sáng đến 5 giờ sáng"],"h1":"Nó bắt đầu một giờ trước nửa đêm.","h2":"Ở Connecticut, người lái có bằng 16 hoặc 17 tuổi không được lái xe từ 11 giờ tối đến 5 giờ sáng, trừ khi đi làm, đi học, sinh hoạt tôn giáo hoặc cấp cứu y tế.","p":"Đúng. Giờ giới nghiêm cho thiếu niên là 11 giờ tối đến 5 giờ sáng."},"tl":{"q":"Sa Connecticut, sa anong oras bawal magmaneho ang 16 o 17 taong gulang na may lisensya, maliban sa mga dahilan tulad ng trabaho, paaralan o medical emergency?","o":["9 p.m. hanggang 6 a.m.","Hatinggabi hanggang 6 a.m.","11 p.m. hanggang 5 a.m.","1 a.m. hanggang 5 a.m."],"h1":"Nagsisimula ito isang oras bago maghatinggabi.","h2":"Sa Connecticut, ang 16 o 17 taong gulang na may lisensya ay bawal magmaneho mula 11 p.m. hanggang 5 a.m., maliban kung para sa trabaho, paaralan, gawaing panrelihiyon o medical emergency.","p":"Tama. Ang curfew para sa teenager ay 11 p.m. hanggang 5 a.m."},"ar":{"q":"في Connecticut، في أي ساعات لا يجوز للسائق المرخَّص الذي عمره 16 أو 17 سنة أن يقود، إلا لأسباب مثل العمل أو المدرسة أو حالة طبية طارئة؟","o":["من 9 مساءً إلى 6 صباحًا","من منتصف الليل إلى 6 صباحًا","من 11 مساءً إلى 5 صباحًا","من 1 صباحًا إلى 5 صباحًا"],"h1":"تبدأ قبل منتصف الليل بساعة واحدة.","h2":"في Connecticut لا يجوز للسائق المرخَّص الذي عمره 16 أو 17 سنة أن يقود من 11 مساءً إلى 5 صباحًا، إلا للعمل أو المدرسة أو نشاط ديني أو حالة طبية طارئة.","p":"صحيح. حظر التجول للمراهقين من 11 مساءً إلى 5 صباحًا."},"ref":{"doc":"CT","page":8}},{"id":"ct-011","scope":"CT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Connecticut, what can police do on the spot when a 16- or 17-year-old driver commits certain serious violations?","o":["Take the license for 48 hours and remove the car","Only give a warning","Take away the car for one year","Nothing until a court date"],"h1":"It happens right away, at the side of the road.","h2":"In Connecticut police can take a 16- or 17-year-old driver's license on the spot for 48 hours for certain violations, and they may also remove the car.","p":"Right. The license is taken for 48 hours, and the car can be removed."},"es":{"q":"En Connecticut, ¿qué puede hacer la policía en el momento si un conductor de 16 o 17 años comete ciertas infracciones graves?","o":["Quitarle la licencia por 48 horas y retirar el carro","Solo darle una advertencia","Quitarle el carro por un año","Nada hasta la fecha de la corte"],"h1":"Ocurre de inmediato, al lado de la carretera.","h2":"En Connecticut la policía puede quitarle la licencia en el momento por 48 horas a un conductor de 16 o 17 años por ciertas infracciones, y también puede retirar el carro.","p":"Correcto. Le quitan la licencia por 48 horas y pueden retirar el carro."},"zh":{"q":"在 Connecticut，16 岁或 17 岁的司机有某些严重违规时，警察可以当场怎么做？","o":["收走驾照 48 小时，并把车移走","只给警告","把车收走一年","开庭前什么都不做"],"h1":"它马上发生，就在路边。","h2":"在 Connecticut，16 岁或 17 岁的司机有某些违规时，警察可以当场收走驾照 48 小时，也可以把车移走。","p":"对。驾照被收走 48 小时，车也可能被移走。"},"vi":{"q":"Ở Connecticut, cảnh sát có thể làm gì ngay tại chỗ khi người lái 16 hoặc 17 tuổi phạm một số lỗi nghiêm trọng?","o":["Lấy bằng lái trong 48 giờ và mang xe đi","Chỉ cảnh cáo","Lấy xe trong một năm","Không làm gì cho đến ngày ra tòa"],"h1":"Việc này xảy ra ngay lập tức, bên lề đường.","h2":"Ở Connecticut, cảnh sát có thể lấy bằng lái của người lái 16 hoặc 17 tuổi ngay tại chỗ trong 48 giờ vì một số lỗi, và cũng có thể mang xe đi.","p":"Đúng. Bằng lái bị lấy trong 48 giờ, và xe có thể bị mang đi."},"tl":{"q":"Sa Connecticut, ano ang puwedeng gawin agad ng pulis kapag ang 16 o 17 taong gulang na driver ay gumawa ng ilang seryosong paglabag?","o":["Kunin ang lisensya nang 48 oras at alisin ang kotse","Magbigay lang ng babala","Kunin ang kotse nang isang taon","Wala hanggang sa araw ng korte"],"h1":"Nangyayari ito agad, sa gilid ng kalsada.","h2":"Sa Connecticut, puwedeng kunin agad ng pulis ang lisensya ng 16 o 17 taong gulang na driver nang 48 oras dahil sa ilang paglabag, at puwede rin nilang alisin ang kotse.","p":"Tama. Kinukuha ang lisensya nang 48 oras, at puwedeng alisin ang kotse."},"ar":{"q":"في Connecticut، ماذا يمكن للشرطة أن تفعل في الحال عندما يرتكب سائق عمره 16 أو 17 سنة بعض المخالفات الخطيرة؟","o":["أخذ الرخصة لمدة 48 ساعة وإبعاد السيارة","إعطاء تحذير فقط","أخذ السيارة لمدة سنة واحدة","لا شيء حتى موعد المحكمة"],"h1":"يحدث ذلك في الحال، على جانب الطريق.","h2":"في Connecticut يمكن للشرطة أن تأخذ رخصة السائق الذي عمره 16 أو 17 سنة في الحال لمدة 48 ساعة بسبب بعض المخالفات، ويمكنها أيضًا إبعاد السيارة.","p":"صحيح. تؤخذ الرخصة لمدة 48 ساعة، ويمكن إبعاد السيارة."},"ref":{"doc":"CT","page":null}},{"id":"ct-012","scope":"CT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Connecticut, at what blood alcohol level is a driver under 21 considered to be driving illegally?","o":["0.08 percent","0.02 percent","0.05 percent","0.10 percent"],"h1":"It is much lower than the adult limit of 0.08.","h2":"In Connecticut a driver under 21 is driving illegally with a blood alcohol level of 0.02 percent or more.","p":"Right. For drivers under 21 the limit is 0.02."},"es":{"q":"En Connecticut, ¿con qué nivel de alcohol en la sangre se considera que un conductor menor de 21 maneja ilegalmente?","o":["0.08 por ciento","0.02 por ciento","0.05 por ciento","0.10 por ciento"],"h1":"Es mucho más bajo que el límite de 0.08 para adultos.","h2":"En Connecticut un conductor menor de 21 años maneja ilegalmente con un nivel de alcohol en la sangre de 0.02 por ciento o más.","p":"Correcto. Para menores de 21 el límite es 0.02."},"zh":{"q":"在 Connecticut，21 岁以下的司机血液酒精浓度达到多少，就算违法驾驶？","o":["0.08%","0.02%","0.05%","0.10%"],"h1":"它比成年人 0.08 的限制低很多。","h2":"在 Connecticut，21 岁以下的司机血液酒精浓度达到 0.02% 或更高，就是违法驾驶。","p":"对。21 岁以下的司机，限制是 0.02。"},"vi":{"q":"Ở Connecticut, người lái dưới 21 tuổi bị coi là lái xe bất hợp pháp ở nồng độ cồn trong máu bao nhiêu?","o":["0.08 phần trăm","0.02 phần trăm","0.05 phần trăm","0.10 phần trăm"],"h1":"Nó thấp hơn nhiều so với giới hạn 0.08 của người lớn.","h2":"Ở Connecticut, người lái dưới 21 tuổi lái xe bất hợp pháp khi nồng độ cồn trong máu từ 0.02 phần trăm trở lên.","p":"Đúng. Với người lái dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa Connecticut, sa anong blood alcohol level itinuturing na ilegal ang pagmamaneho ng driver na wala pang 21?","o":["0.08 porsiyento","0.02 porsiyento","0.05 porsiyento","0.10 porsiyento"],"h1":"Mas mababa ito nang malaki kaysa sa 0.08 na limit para sa mga adult.","h2":"Sa Connecticut, ilegal ang pagmamaneho ng driver na wala pang 21 kapag ang blood alcohol level niya ay 0.02 porsiyento o higit pa.","p":"Tama. Para sa mga driver na wala pang 21, ang limit ay 0.02."},"ar":{"q":"في Connecticut، عند أي نسبة من الكحول في الدم يُعتبر السائق تحت 21 سنة يقود بشكل غير قانوني؟","o":["0.08 بالمئة","0.02 بالمئة","0.05 بالمئة","0.10 بالمئة"],"h1":"هي أقل بكثير من حد البالغين وهو 0.08.","h2":"في Connecticut يقود السائق تحت 21 سنة بشكل غير قانوني إذا كانت نسبة الكحول في دمه 0.02 بالمئة أو أكثر.","p":"صحيح. للسائقين تحت 21 سنة الحد هو 0.02."},"ref":{"doc":"CT","page":31}},{"id":"ct-013","scope":"CT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Connecticut, what must you do when you approach an emergency vehicle stopped on the shoulder and you are in the lane next to it?","o":["Keep the same speed and lane","Stop in your lane until it leaves","Speed up to pass it quickly","Slow down below the speed limit and move over one lane if it is safe"],"h1":"There are two steps: one with your speed, one with your lane.","h2":"In Connecticut you must slow to a safe speed below the posted limit and, if you are in the next lane, move over one lane when it is safe.","p":"Right. Slow down and move over."},"es":{"q":"En Connecticut, ¿qué debe hacer al acercarse a un vehículo de emergencia detenido en el acotamiento si usted va en el carril de al lado?","o":["Seguir a la misma velocidad y en el mismo carril","Detenerse en su carril hasta que se vaya","Acelerar para pasarlo rápido","Bajar la velocidad por debajo del límite y cambiarse un carril si es seguro"],"h1":"Son dos pasos: uno con su velocidad y otro con su carril.","h2":"En Connecticut usted debe bajar a una velocidad segura por debajo del límite y, si va en el carril de al lado, cambiarse un carril cuando sea seguro.","p":"Correcto. Baje la velocidad y cámbiese de carril."},"zh":{"q":"在 Connecticut，你接近一辆停在路肩上的急救车辆，而你在它旁边的车道上。你必须怎么做？","o":["保持同样的速度和车道","在你的车道停车，直到它离开","加速快点开过去","减速到低于限速，如果安全就换开一条车道"],"h1":"有两个步骤：一个和速度有关，一个和车道有关。","h2":"在 Connecticut，你必须减速到低于标示限速的安全速度；如果你在旁边的车道，安全时要换开一条车道。","p":"对。减速并换道（move over）。"},"vi":{"q":"Ở Connecticut, bạn phải làm gì khi đến gần xe cấp cứu đang dừng bên lề đường và bạn đang ở làn kế bên nó?","o":["Giữ nguyên tốc độ và làn đường","Dừng lại trong làn của bạn cho đến khi xe đó đi","Tăng tốc để vượt qua nhanh","Chạy chậm lại dưới tốc độ giới hạn và chuyển sang một làn khác nếu an toàn"],"h1":"Có hai bước: một về tốc độ, một về làn đường.","h2":"Ở Connecticut, bạn phải chạy chậm lại đến tốc độ an toàn dưới mức giới hạn đã ghi và, nếu bạn ở làn kế bên, chuyển sang một làn khác khi an toàn.","p":"Đúng. Chạy chậm lại và chuyển làn."},"tl":{"q":"Sa Connecticut, ano ang dapat mong gawin kapag papalapit ka sa emergency vehicle na nakahinto sa gilid ng kalsada at nasa katabing lane ka?","o":["Panatilihin ang parehong bilis at lane","Huminto sa lane mo hanggang umalis ito","Bilisan para malampasan ito agad","Bagalan nang mas mababa sa speed limit at lumipat ng isang lane kung ligtas"],"h1":"May dalawang hakbang: isa sa bilis mo, isa sa lane mo.","h2":"Sa Connecticut, dapat kang bumagal sa ligtas na bilis na mas mababa sa nakapaskil na limit at, kung nasa katabing lane ka, lumipat ng isang lane kapag ligtas.","p":"Tama. Bumagal at lumipat ng lane."},"ar":{"q":"في Connecticut، ماذا يجب أن تفعل عندما تقترب من سيارة طوارئ متوقفة على جانب الطريق وأنت في الحارة المجاورة لها؟","o":["ابقَ على نفس السرعة ونفس الحارة","توقف في حارتك حتى تغادر","زِد سرعتك لتتجاوزها بسرعة","خفّف السرعة إلى أقل من الحد المسموح وانتقل حارة واحدة إذا كان ذلك آمنًا"],"h1":"هناك خطوتان: واحدة لسرعتك، وواحدة لحارتك.","h2":"في Connecticut يجب أن تخفّف السرعة إلى سرعة آمنة أقل من الحد المكتوب، وإذا كنت في الحارة المجاورة، يجب أن تنتقل حارة واحدة عندما يكون ذلك آمنًا.","p":"صحيح. خفّف السرعة وابتعد بحارة."},"ref":{"doc":"CT","page":14}},{"id":"ct-014","scope":"CT","cat":"signals","sign":null,"c":0,"en":{"q":"In Connecticut, when may you turn right on a red light?","o":["After a full stop, when it is safe and no sign forbids it","Never","Without stopping, if no one is coming","Only between midnight and 6 a.m."],"h1":"Some intersections have a sign that says you may not.","h2":"In Connecticut you may turn right on red only after a complete stop, when it is safe, and where no sign says \"No Turn on Red.\"","p":"Right. Stop first, then turn if it is safe and allowed."},"es":{"q":"En Connecticut, ¿cuándo puede girar a la derecha con la luz roja?","o":["Después de detenerse por completo, si es seguro y ninguna señal lo prohíbe","Nunca","Sin detenerse, si no viene nadie","Solo de medianoche a 6 a.m."],"h1":"Algunas intersecciones tienen una señal que lo prohíbe.","h2":"En Connecticut usted puede girar a la derecha con luz roja solo después de detenerse por completo, si es seguro y donde ninguna señal diga \"No Turn on Red\".","p":"Correcto. Primero se detiene, y luego gira si es seguro y está permitido."},"zh":{"q":"在 Connecticut，什么时候可以红灯右转？","o":["完全停车后，安全而且没有标志禁止时","从来不可以","没人来时不用停车","只在午夜到早上 6 点之间"],"h1":"有些路口有标志说你不可以。","h2":"在 Connecticut，只有完全停车以后、安全时，而且没有写着 \"No Turn on Red\"（红灯禁止转弯）的标志，你才可以红灯右转。","p":"对。先停车，安全又允许时再转弯。"},"vi":{"q":"Ở Connecticut, khi nào bạn được rẽ phải khi đèn đỏ?","o":["Sau khi dừng hẳn, khi an toàn và không có biển cấm","Không bao giờ","Không cần dừng, nếu không có ai đến","Chỉ từ nửa đêm đến 6 giờ sáng"],"h1":"Một số giao lộ có biển báo nói rằng bạn không được rẽ.","h2":"Ở Connecticut, bạn chỉ được rẽ phải khi đèn đỏ sau khi dừng hẳn, khi an toàn, và ở nơi không có biển \"No Turn on Red\" (cấm rẽ khi đèn đỏ).","p":"Đúng. Dừng trước, rồi rẽ nếu an toàn và được phép."},"tl":{"q":"Sa Connecticut, kailan ka puwedeng kumanan kapag pula ang ilaw?","o":["Pagkatapos huminto nang buo, kapag ligtas at walang karatulang nagbabawal","Hindi kailanman","Nang hindi humihinto, kung walang paparating","Mula hatinggabi hanggang 6 a.m. lang"],"h1":"May ilang interseksyon na may karatulang nagsasabing bawal.","h2":"Sa Connecticut, puwede kang kumanan sa pulang ilaw pagkatapos lang ng buong paghinto, kapag ligtas, at kung walang karatulang \"No Turn on Red.\"","p":"Tama. Huminto muna, saka kumanan kung ligtas at pinapayagan."},"ar":{"q":"في Connecticut، متى يجوز لك أن تنعطف يمينًا عند الإشارة الحمراء؟","o":["بعد التوقف الكامل، عندما يكون الأمر آمنًا ولا توجد لافتة تمنع ذلك","أبدًا","دون توقف، إذا لم يكن أحد قادمًا","فقط بين منتصف الليل و6 صباحًا"],"h1":"بعض التقاطعات فيها لافتة تقول إنه لا يجوز لك ذلك.","h2":"في Connecticut يجوز لك أن تنعطف يمينًا عند الإشارة الحمراء فقط بعد التوقف الكامل، وعندما يكون ذلك آمنًا، وحيث لا توجد لافتة \"No Turn on Red\" (ممنوع الانعطاف عند الأحمر).","p":"صحيح. توقف أولًا، ثم انعطف إذا كان ذلك آمنًا ومسموحًا."},"ref":{"doc":"CT","page":13}},{"id":"ct-015","scope":"CT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Connecticut, how long must a 16- or 17-year-old who took a commercial or school driver education course wait after getting a permit before applying for a license?","o":["30 days","60 days","120 days","One year"],"h1":"It is about four months.","h2":"In Connecticut a 16- or 17-year-old who took a commercial or high school driver education course must wait at least 120 days after the permit before applying for a license.","p":"Right. The wait is 120 days with a course."},"es":{"q":"En Connecticut, ¿cuánto debe esperar después de recibir el permiso un joven de 16 o 17 años que tomó un curso de manejo comercial o escolar antes de pedir la licencia?","o":["30 días","60 días","120 días","Un año"],"h1":"Son unos cuatro meses.","h2":"En Connecticut un joven de 16 o 17 años que tomó un curso de manejo comercial o de la escuela debe esperar por lo menos 120 días después del permiso para pedir la licencia.","p":"Correcto. La espera es de 120 días con un curso."},"zh":{"q":"在 Connecticut，上过商业驾校或学校驾驶教育课程的 16 岁或 17 岁的人，拿到学习驾照后要等多久才能申请驾照？","o":["30 天","60 天","120 天","一年"],"h1":"它大约是四个月。","h2":"在 Connecticut，上过商业驾校或高中驾驶教育课程的 16 岁或 17 岁的人，拿到学习驾照后至少要等 120 天才能申请驾照。","p":"对。上过课程要等 120 天。"},"vi":{"q":"Ở Connecticut, người 16 hoặc 17 tuổi đã học khóa giáo dục lái xe ở trường lái hoặc trường học phải chờ bao lâu sau khi có giấy phép tập lái mới được nộp đơn xin bằng lái?","o":["30 ngày","60 ngày","120 ngày","Một năm"],"h1":"Khoảng bốn tháng.","h2":"Ở Connecticut, người 16 hoặc 17 tuổi đã học khóa giáo dục lái xe ở trường lái hoặc trường trung học phải chờ ít nhất 120 ngày sau khi có giấy phép tập lái mới được nộp đơn xin bằng lái.","p":"Đúng. Nếu có học khóa lái xe thì phải chờ 120 ngày."},"tl":{"q":"Sa Connecticut, gaano katagal dapat maghintay pagkatapos makakuha ng permit ang 16 o 17 taong gulang na kumuha ng driver education course sa driving school o paaralan bago mag-apply ng lisensya?","o":["30 araw","60 araw","120 araw","Isang taon"],"h1":"Mga apat na buwan ito.","h2":"Sa Connecticut, ang 16 o 17 taong gulang na kumuha ng driver education course sa driving school o high school ay dapat maghintay nang hindi bababa sa 120 araw pagkatapos ng permit bago mag-apply ng lisensya.","p":"Tama. 120 araw ang paghihintay kapag may course."},"ar":{"q":"في Connecticut، كم يجب أن ينتظر من عمره 16 أو 17 سنة وأخذ دورة تعليم قيادة في مدرسة قيادة أو في المدرسة بعد الحصول على التصريح قبل أن يتقدّم بطلب رخصة؟","o":["30 يومًا","60 يومًا","120 يومًا","سنة واحدة"],"h1":"هي حوالي أربعة أشهر.","h2":"في Connecticut يجب على من عمره 16 أو 17 سنة وأخذ دورة تعليم قيادة في مدرسة قيادة أو في المدرسة الثانوية أن ينتظر 120 يومًا على الأقل بعد التصريح قبل أن يتقدّم بطلب رخصة.","p":"صحيح. الانتظار 120 يومًا مع الدورة."},"ref":{"doc":"CT","page":6}},{"id":"ct-016","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, how long must a 16- or 17-year-old who chose home training wait after getting a permit before applying for a license?","o":["90 days","180 days","120 days","365 days"],"h1":"It is longer than the wait after a driving school course.","h2":"In Connecticut a 16- or 17-year-old who learns through home training must wait at least 180 days after the permit before applying for a license.","p":"Right. Home training means a 180-day wait."},"es":{"q":"En Connecticut, ¿cuánto debe esperar después de recibir el permiso un joven de 16 o 17 años que eligió aprender en casa antes de pedir la licencia?","o":["90 días","180 días","120 días","365 días"],"h1":"Es más tiempo que después de un curso en una escuela de manejo.","h2":"En Connecticut un joven de 16 o 17 años que aprende en casa debe esperar por lo menos 180 días después del permiso para pedir la licencia.","p":"Correcto. Aprender en casa significa esperar 180 días."},"zh":{"q":"在 Connecticut，选择在家训练的 16 岁或 17 岁的人，拿到学习驾照后要等多久才能申请驾照？","o":["90 天","180 天","120 天","365 天"],"h1":"它比上驾校课程后的等待时间长。","h2":"在 Connecticut，通过在家训练学开车的 16 岁或 17 岁的人，拿到学习驾照后至少要等 180 天才能申请驾照。","p":"对。在家训练要等 180 天。"},"vi":{"q":"Ở Connecticut, người 16 hoặc 17 tuổi chọn tập lái tại nhà (home training) phải chờ bao lâu sau khi có giấy phép tập lái mới được nộp đơn xin bằng lái?","o":["90 ngày","180 ngày","120 ngày","365 ngày"],"h1":"Thời gian này dài hơn thời gian chờ sau khóa học ở trường lái.","h2":"Ở Connecticut, người 16 hoặc 17 tuổi tập lái tại nhà phải chờ ít nhất 180 ngày sau khi có giấy phép tập lái mới được nộp đơn xin bằng lái.","p":"Đúng. Tập lái tại nhà thì phải chờ 180 ngày."},"tl":{"q":"Sa Connecticut, gaano katagal dapat maghintay pagkatapos makakuha ng permit ang 16 o 17 taong gulang na pumili ng home training bago mag-apply ng lisensya?","o":["90 araw","180 araw","120 araw","365 araw"],"h1":"Mas matagal ito kaysa sa paghihintay pagkatapos ng course sa driving school.","h2":"Sa Connecticut, ang 16 o 17 taong gulang na natuto sa home training ay dapat maghintay nang hindi bababa sa 180 araw pagkatapos ng permit bago mag-apply ng lisensya.","p":"Tama. Sa home training, 180 araw ang paghihintay."},"ar":{"q":"في Connecticut، كم يجب أن ينتظر من عمره 16 أو 17 سنة واختار التدريب المنزلي (home training) بعد الحصول على التصريح قبل أن يتقدّم بطلب رخصة؟","o":["90 يومًا","180 يومًا","120 يومًا","365 يومًا"],"h1":"هو أطول من الانتظار بعد دورة مدرسة القيادة.","h2":"في Connecticut يجب على من عمره 16 أو 17 سنة ويتعلّم بالتدريب المنزلي أن ينتظر 180 يومًا على الأقل بعد التصريح قبل أن يتقدّم بطلب رخصة.","p":"صحيح. التدريب المنزلي يعني انتظار 180 يومًا."},"ref":{"doc":"CT","page":6}},{"id":"ct-017","scope":"CT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Connecticut, how many hours of behind-the-wheel training must a 16- or 17-year-old complete?","o":["10 hours","20 hours","30 hours","40 hours"],"h1":"It is more than the 30 hours of classroom study.","h2":"In Connecticut a 16- or 17-year-old must complete 40 hours of behind-the-wheel training, along with 30 hours of classroom study.","p":"Right. 40 hours behind the wheel."},"es":{"q":"En Connecticut, ¿cuántas horas de práctica al volante debe completar un joven de 16 o 17 años?","o":["10 horas","20 horas","30 horas","40 horas"],"h1":"Son más que las 30 horas de estudio en clase.","h2":"En Connecticut un joven de 16 o 17 años debe completar 40 horas de práctica al volante, además de 30 horas de estudio en clase.","p":"Correcto. 40 horas al volante."},"zh":{"q":"在 Connecticut，16 岁或 17 岁的人必须完成多少小时的实际上车驾驶训练？","o":["10 小时","20 小时","30 小时","40 小时"],"h1":"它比 30 小时的课堂学习多。","h2":"在 Connecticut，16 岁或 17 岁的人必须完成 40 小时的实际上车驾驶训练，另外还有 30 小时的课堂学习。","p":"对。实际开车 40 小时。"},"vi":{"q":"Ở Connecticut, người 16 hoặc 17 tuổi phải hoàn thành bao nhiêu giờ tập lái thực tế sau tay lái?","o":["10 giờ","20 giờ","30 giờ","40 giờ"],"h1":"Nhiều hơn 30 giờ học lý thuyết trong lớp.","h2":"Ở Connecticut, người 16 hoặc 17 tuổi phải hoàn thành 40 giờ tập lái thực tế sau tay lái, cùng với 30 giờ học lý thuyết trong lớp.","p":"Đúng. 40 giờ sau tay lái."},"tl":{"q":"Sa Connecticut, ilang oras ng behind-the-wheel training (aktwal na pagmamaneho) ang dapat tapusin ng 16 o 17 taong gulang?","o":["10 oras","20 oras","30 oras","40 oras"],"h1":"Mas marami ito kaysa sa 30 oras ng pag-aaral sa klase.","h2":"Sa Connecticut, ang 16 o 17 taong gulang ay dapat tumapos ng 40 oras ng behind-the-wheel training, kasama ang 30 oras ng pag-aaral sa klase.","p":"Tama. 40 oras sa likod ng manibela."},"ar":{"q":"في Connecticut، كم ساعة من التدريب العملي خلف المقود يجب أن يُكمل من عمره 16 أو 17 سنة؟","o":["10 ساعات","20 ساعة","30 ساعة","40 ساعة"],"h1":"هي أكثر من 30 ساعة الدراسة في الصف.","h2":"في Connecticut يجب على من عمره 16 أو 17 سنة أن يُكمل 40 ساعة من التدريب العملي خلف المقود، بالإضافة إلى 30 ساعة من الدراسة في الصف.","p":"صحيح. 40 ساعة خلف المقود."},"ref":{"doc":"CT","page":6}},{"id":"ct-018","scope":"CT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Connecticut, how many hours of driver education study must a 16- or 17-year-old complete?","o":["30 hours","10 hours","15 hours","50 hours"],"h1":"It is ten hours less than the behind-the-wheel training.","h2":"In Connecticut a 16- or 17-year-old must complete 30 hours of driver education study, which includes the 8-hour safe driving course.","p":"Right. 30 hours of study."},"es":{"q":"En Connecticut, ¿cuántas horas de estudio de manejo debe completar un joven de 16 o 17 años?","o":["30 horas","10 horas","15 horas","50 horas"],"h1":"Son diez horas menos que la práctica al volante.","h2":"En Connecticut un joven de 16 o 17 años debe completar 30 horas de estudio de manejo, que incluyen el curso de manejo seguro de 8 horas.","p":"Correcto. 30 horas de estudio."},"zh":{"q":"在 Connecticut，16 岁或 17 岁的人必须完成多少小时的驾驶教育学习？","o":["30 小时","10 小时","15 小时","50 小时"],"h1":"它比实际上车驾驶训练少十小时。","h2":"在 Connecticut，16 岁或 17 岁的人必须完成 30 小时的驾驶教育学习，其中包括 8 小时的安全驾驶课。","p":"对。学习 30 小时。"},"vi":{"q":"Ở Connecticut, người 16 hoặc 17 tuổi phải hoàn thành bao nhiêu giờ học giáo dục lái xe?","o":["30 giờ","10 giờ","15 giờ","50 giờ"],"h1":"Ít hơn mười giờ so với số giờ tập lái thực tế sau tay lái.","h2":"Ở Connecticut, người 16 hoặc 17 tuổi phải hoàn thành 30 giờ học giáo dục lái xe, bao gồm khóa học lái xe an toàn 8 giờ.","p":"Đúng. 30 giờ học."},"tl":{"q":"Sa Connecticut, ilang oras ng pag-aaral ng driver education ang dapat tapusin ng 16 o 17 taong gulang?","o":["30 oras","10 oras","15 oras","50 oras"],"h1":"Sampung oras itong mas kaunti kaysa sa behind-the-wheel training.","h2":"Sa Connecticut, ang 16 o 17 taong gulang ay dapat tumapos ng 30 oras ng pag-aaral ng driver education, kasama na ang 8 oras na safe driving course.","p":"Tama. 30 oras ng pag-aaral."},"ar":{"q":"في Connecticut، كم ساعة من دراسة تعليم القيادة يجب أن يُكمل من عمره 16 أو 17 سنة؟","o":["30 ساعة","10 ساعات","15 ساعة","50 ساعة"],"h1":"هي أقل بعشر ساعات من التدريب العملي خلف المقود.","h2":"في Connecticut يجب على من عمره 16 أو 17 سنة أن يُكمل 30 ساعة من دراسة تعليم القيادة، وتشمل دورة القيادة الآمنة لمدة 8 ساعات.","p":"صحيح. 30 ساعة من الدراسة."},"ref":{"doc":"CT","page":6}},{"id":"ct-019","scope":"CT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Connecticut, is there a night curfew for a driver with a learner's permit?","o":["Yes, from 9 p.m. to 6 a.m.","Yes, from 11 p.m. to 5 a.m.","No curfew, but a qualified trainer must always be in the car","No curfew, and the permit driver may drive alone"],"h1":"The permit rule is about who is beside you, not the clock.","h2":"In Connecticut a permit holder has no curfew, but must always drive with a qualified trainer.","p":"Right. No curfew, but never alone."},"es":{"q":"En Connecticut, ¿hay horario de restricción nocturna para quien tiene permiso de aprendiz?","o":["Sí, de 9 p.m. a 6 a.m.","Sí, de 11 p.m. a 5 a.m.","No hay horario, pero siempre debe ir un instructor calificado en el carro","No hay horario, y puede manejar solo"],"h1":"La regla del permiso es sobre quién va a su lado, no sobre la hora.","h2":"En Connecticut quien tiene permiso de aprendiz no tiene horario restringido, pero siempre debe manejar con un instructor calificado.","p":"Correcto. Sin horario, pero nunca solo."},"zh":{"q":"在 Connecticut，持学习驾照的司机有夜间宵禁吗？","o":["有，晚上 9 点到早上 6 点","有，晚上 11 点到早上 5 点","没有宵禁，但车里一定要有合格的指导人","没有宵禁，持学习驾照的司机可以单独开车"],"h1":"学习驾照的规定和谁坐在你旁边有关，和时间无关。","h2":"在 Connecticut，持学习驾照的人没有宵禁，但必须一直和合格的指导人一起开车。","p":"对。没有宵禁，但永远不能单独开车。"},"vi":{"q":"Ở Connecticut, người lái có giấy phép tập lái (learner's permit) có bị giới nghiêm ban đêm không?","o":["Có, từ 9 giờ tối đến 6 giờ sáng","Có, từ 11 giờ tối đến 5 giờ sáng","Không có giới nghiêm, nhưng luôn phải có người hướng dẫn đủ điều kiện trong xe","Không có giới nghiêm, và người tập lái được lái một mình"],"h1":"Luật của giấy phép tập lái là về người ngồi bên cạnh bạn, không phải về giờ giấc.","h2":"Ở Connecticut, người có giấy phép tập lái không bị giới nghiêm, nhưng luôn phải lái xe cùng người hướng dẫn đủ điều kiện.","p":"Đúng. Không có giới nghiêm, nhưng không bao giờ lái một mình."},"tl":{"q":"Sa Connecticut, may curfew ba sa gabi para sa driver na may learner's permit?","o":["Oo, mula 9 p.m. hanggang 6 a.m.","Oo, mula 11 p.m. hanggang 5 a.m.","Walang curfew, pero dapat laging may qualified trainer sa kotse","Walang curfew, at puwedeng magmaneho nang mag-isa ang may permit"],"h1":"Ang patakaran sa permit ay tungkol sa kung sino ang katabi mo, hindi sa oras.","h2":"Sa Connecticut, walang curfew ang may permit, pero dapat lagi siyang nagmamaneho kasama ang qualified trainer.","p":"Tama. Walang curfew, pero hindi kailanman nag-iisa."},"ar":{"q":"في Connecticut، هل يوجد حظر تجول ليلي لسائق يحمل تصريح التعلّم (learner's permit)؟","o":["نعم، من 9 مساءً إلى 6 صباحًا","نعم، من 11 مساءً إلى 5 صباحًا","لا يوجد حظر تجول، لكن يجب أن يكون مدرّب مؤهَّل في السيارة دائمًا","لا يوجد حظر تجول، ويمكن لسائق التصريح أن يقود وحده"],"h1":"قاعدة التصريح تتعلق بمن يجلس بجانبك، لا بالساعة.","h2":"في Connecticut لا يوجد حظر تجول على حامل التصريح، لكن يجب أن يقود دائمًا مع مدرّب مؤهَّل.","p":"صحيح. لا حظر تجول، لكن لا قيادة وحدك أبدًا."},"ref":{"doc":"CT","page":null}},{"id":"ct-020","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, who must be with a 16- or 17-year-old when taking the knowledge test, if they do not send a signed consent form?","o":["A teacher","A parent or guardian","A driving instructor","No one"],"h1":"It is the adult responsible for the teen.","h2":"In Connecticut a parent or guardian must come to the knowledge test with an applicant under 18, or fill out a consent form.","p":"Right. A parent or guardian gives consent."},"es":{"q":"En Connecticut, ¿quién debe acompañar a un joven de 16 o 17 años al examen teórico, si no envía un formulario de consentimiento firmado?","o":["Un maestro","Su padre, madre o tutor","Un instructor de manejo","Nadie"],"h1":"Es el adulto responsable del joven.","h2":"En Connecticut el padre, la madre o el tutor debe ir al examen teórico con un solicitante menor de 18, o llenar un formulario de consentimiento.","p":"Correcto. El padre, la madre o el tutor da su consentimiento."},"zh":{"q":"在 Connecticut，16 岁或 17 岁的人如果没有交签字的同意书，考笔试时谁必须陪同？","o":["老师","父母或监护人","驾驶教练","不需要任何人"],"h1":"它是对这个青少年负责的成年人。","h2":"在 Connecticut，18 岁以下的申请人考笔试时，父母或监护人必须一起来，或者填写同意书。","p":"对。由父母或监护人表示同意。"},"vi":{"q":"Ở Connecticut, ai phải đi cùng người 16 hoặc 17 tuổi khi thi lý thuyết, nếu họ không gửi mẫu đơn đồng ý có chữ ký?","o":["Một giáo viên","Cha mẹ hoặc người giám hộ","Một giáo viên dạy lái xe","Không ai cả"],"h1":"Đó là người lớn chịu trách nhiệm cho thiếu niên.","h2":"Ở Connecticut, cha mẹ hoặc người giám hộ phải đến buổi thi lý thuyết cùng người dưới 18 tuổi, hoặc điền mẫu đơn đồng ý.","p":"Đúng. Cha mẹ hoặc người giám hộ cho phép."},"tl":{"q":"Sa Connecticut, sino ang dapat kasama ng 16 o 17 taong gulang sa pagkuha ng knowledge test, kung hindi sila nagpadala ng pinirmahang consent form?","o":["Isang guro","Magulang o guardian","Isang driving instructor","Wala"],"h1":"Ito ang adult na responsable sa teenager.","h2":"Sa Connecticut, ang magulang o guardian ay dapat sumama sa knowledge test ng aplikanteng wala pang 18, o sumagot ng consent form.","p":"Tama. Ang magulang o guardian ang nagbibigay ng pahintulot."},"ar":{"q":"في Connecticut، من يجب أن يكون مع من عمره 16 أو 17 سنة عند أداء الاختبار النظري، إذا لم يرسل نموذج موافقة موقَّعًا؟","o":["معلّم","أحد الوالدين أو الوصي","مدرّب قيادة","لا أحد"],"h1":"هو الشخص البالغ المسؤول عن المراهق.","h2":"في Connecticut يجب أن يأتي أحد الوالدين أو الوصي إلى الاختبار النظري مع المتقدّم الذي عمره أقل من 18 سنة، أو أن يملأ نموذج موافقة.","p":"صحيح. أحد الوالدين أو الوصي يعطي الموافقة."},"ref":{"doc":"CT","page":null}},{"id":"ct-021","scope":"CT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Connecticut, how long is a learner's permit valid if you do not get a license first?","o":["6 months","1 year","18 months","2 years"],"h1":"It lasts longer than one year.","h2":"In Connecticut a learner's permit is valid for 2 years, or until you get your driver's license, whichever comes first.","p":"Right. The permit lasts up to 2 years."},"es":{"q":"En Connecticut, ¿por cuánto tiempo es válido un permiso de aprendizaje si usted no obtiene la licencia antes?","o":["6 meses","1 año","18 meses","2 años"],"h1":"Dura más de un año.","h2":"En Connecticut un permiso de aprendizaje es válido por 2 años, o hasta que usted obtenga su licencia de manejo, lo que ocurra primero.","p":"Correcto. El permiso dura hasta 2 años."},"zh":{"q":"在 Connecticut，如果你还没拿到驾照，学习驾照的有效期是多久？","o":["6 个月","1 年","18 个月","2 年"],"h1":"它的有效期比一年更长。","h2":"在 Connecticut，学习驾照的有效期是 2 年，或者到你拿到驾照为止，以先到者为准。","p":"对。学习驾照最长有效 2 年。"},"vi":{"q":"Ở Connecticut, giấy phép tập lái (learner's permit) có hiệu lực bao lâu nếu bạn chưa lấy bằng lái trước đó?","o":["6 tháng","1 năm","18 tháng","2 năm"],"h1":"Nó kéo dài hơn một năm.","h2":"Ở Connecticut, giấy phép tập lái có hiệu lực 2 năm, hoặc cho đến khi bạn lấy được bằng lái, tùy điều nào đến trước.","p":"Đúng. Giấy phép tập lái có hiệu lực tối đa 2 năm."},"tl":{"q":"Sa Connecticut, gaano katagal valid ang learner's permit kung hindi ka muna nakakuha ng lisensya?","o":["6 buwan","1 taon","18 buwan","2 taon"],"h1":"Mas matagal ito kaysa isang taon.","h2":"Sa Connecticut, valid ang learner's permit nang 2 taon, o hanggang makuha mo ang iyong driver's license, alinman ang mauna.","p":"Tama. Tumatagal ang permit nang hanggang 2 taon."},"ar":{"q":"في Connecticut، كم مدة صلاحية تصريح التعلّم (learner's permit) إذا لم تحصل على رخصة القيادة قبل ذلك؟","o":["6 أشهر","سنة واحدة (1)","18 شهرًا","سنتان (2)"],"h1":"مدته أطول من سنة واحدة.","h2":"في Connecticut يكون تصريح التعلّم صالحًا لمدة 2 سنة، أو حتى تحصل على رخصة القيادة، أيهما يأتي أولًا.","p":"صحيح. يبقى التصريح صالحًا حتى 2 سنة."},"ref":{"doc":"CT","page":5}},{"id":"ct-022","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, how many questions must you answer correctly to pass the 25-question knowledge test?","o":["15","20","22","25"],"h1":"You may miss a few questions, but not many.","h2":"In Connecticut you must answer 20 of the 25 knowledge test questions correctly to pass.","p":"Right. You need 20 correct answers out of 25."},"es":{"q":"En Connecticut, ¿cuántas preguntas debe contestar bien para aprobar el examen teórico de 25 preguntas?","o":["15","20","22","25"],"h1":"Puede fallar algunas preguntas, pero no muchas.","h2":"En Connecticut usted debe contestar bien 20 de las 25 preguntas del examen teórico para aprobar.","p":"Correcto. Necesita 20 respuestas correctas de 25."},"zh":{"q":"在 Connecticut，25 道题的笔试要答对几道题才能通过？","o":["15","20","22","25"],"h1":"你可以答错几道题，但不能错太多。","h2":"在 Connecticut，笔试 25 道题中你必须答对 20 道才能通过。","p":"对。25 道题中要答对 20 道。"},"vi":{"q":"Ở Connecticut, bạn phải trả lời đúng bao nhiêu câu để đậu bài thi lý thuyết 25 câu?","o":["15","20","22","25"],"h1":"Bạn có thể sai vài câu, nhưng không được sai nhiều.","h2":"Ở Connecticut, bạn phải trả lời đúng 20 trên 25 câu của bài thi lý thuyết để đậu.","p":"Đúng. Bạn cần 20 câu đúng trên 25 câu."},"tl":{"q":"Sa Connecticut, ilang tanong ang dapat mong masagot nang tama para pumasa sa 25-tanong na knowledge test?","o":["15","20","22","25"],"h1":"Puwede kang magkamali sa ilang tanong, pero hindi sa marami.","h2":"Sa Connecticut, dapat mong masagot nang tama ang 20 sa 25 tanong ng knowledge test para pumasa.","p":"Tama. Kailangan mo ng 20 tamang sagot sa 25."},"ar":{"q":"في Connecticut، كم سؤالًا يجب أن تجيب عنه إجابة صحيحة لتنجح في الاختبار النظري الذي فيه 25 سؤالًا؟","o":["15","20","22","25"],"h1":"يمكنك أن تخطئ في بعض الأسئلة، لكن ليس في كثير منها.","h2":"في Connecticut يجب أن تجيب إجابة صحيحة عن 20 من أسئلة الاختبار النظري الـ 25 حتى تنجح.","p":"صحيح. تحتاج إلى 20 إجابة صحيحة من 25."},"ref":{"doc":"CT","page":5}},{"id":"ct-023","scope":"CT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Connecticut, what can happen if a driver and a passenger are both not wearing seat belts?","o":["Only the driver can get a ticket","Only the passenger can get a ticket","Each of them can get a $75 ticket","They get a warning only"],"h1":"The law applies to everyone in the car.","h2":"In Connecticut the driver and each passenger without a seat belt can each be fined $75.","p":"Right. Each person without a belt can be fined $75."},"es":{"q":"En Connecticut, ¿qué puede pasar si ni el conductor ni un pasajero llevan puesto el cinturón de seguridad?","o":["Solo el conductor puede recibir una multa","Solo el pasajero puede recibir una multa","Cada uno puede recibir una multa de $75","Solo reciben una advertencia"],"h1":"La ley se aplica a todos en el carro.","h2":"En Connecticut el conductor y cada pasajero sin cinturón pueden recibir cada uno una multa de $75.","p":"Correcto. Cada persona sin cinturón puede recibir una multa de $75."},"zh":{"q":"在 Connecticut，如果司机和一名乘客都没有系安全带，会怎么样？","o":["只有司机会被开罚单","只有乘客会被开罚单","他们每个人都可能被开 $75 的罚单","他们只会收到警告"],"h1":"法律适用于车里的每一个人。","h2":"在 Connecticut，司机和每一位没系安全带的乘客都可能各被罚款 $75。","p":"对。每个没系安全带的人都可能被罚 $75。"},"vi":{"q":"Ở Connecticut, điều gì có thể xảy ra nếu cả người lái và một hành khách đều không thắt dây an toàn?","o":["Chỉ người lái có thể bị phạt","Chỉ hành khách có thể bị phạt","Mỗi người đều có thể bị phạt $75","Họ chỉ bị cảnh cáo"],"h1":"Luật áp dụng cho mọi người trong xe.","h2":"Ở Connecticut, người lái và mỗi hành khách không thắt dây an toàn đều có thể bị phạt $75 mỗi người.","p":"Đúng. Mỗi người không thắt dây an toàn có thể bị phạt $75."},"tl":{"q":"Sa Connecticut, ano ang puwedeng mangyari kung ang driver at ang isang pasahero ay parehong walang suot na seat belt?","o":["Ang driver lang ang puwedeng ma-ticket","Ang pasahero lang ang puwedeng ma-ticket","Bawat isa sa kanila ay puwedeng ma-ticket ng $75","Babala lang ang makukuha nila"],"h1":"Ang batas ay para sa lahat ng nasa kotse.","h2":"Sa Connecticut, ang driver at bawat pasaherong walang seat belt ay puwedeng pagmultahin ng $75 bawat isa.","p":"Tama. Bawat taong walang seat belt ay puwedeng pagmultahin ng $75."},"ar":{"q":"في Connecticut، ماذا يمكن أن يحدث إذا كان السائق وأحد الركاب كلاهما لا يضعان حزام الأمان؟","o":["السائق وحده يمكن أن يحصل على مخالفة","الراكب وحده يمكن أن يحصل على مخالفة","كل واحد منهما يمكن أن يحصل على مخالفة بقيمة $75","يحصلان على تحذير فقط"],"h1":"القانون يشمل كل من في السيارة.","h2":"في Connecticut يمكن أن يُغرَّم السائق وكل راكب لا يضع حزام الأمان بمبلغ $75 لكل واحد منهم.","p":"صحيح. كل شخص بلا حزام أمان يمكن أن يُغرَّم $75."},"ref":{"doc":"CT","page":12}},{"id":"ct-024","scope":"CT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Connecticut, how must a child under age 2, or under 30 pounds, ride in a car?","o":["In a rear-facing car seat with a 5-point harness","In a booster seat","In a forward-facing seat with a lap belt","With an adult seat belt"],"h1":"The smallest children face the back of the car.","h2":"In Connecticut a child under age 2, or under 30 pounds, must ride in a rear-facing car seat with a 5-point harness.","p":"Right. Babies and small toddlers ride rear-facing."},"es":{"q":"En Connecticut, ¿cómo debe viajar en el carro un niño menor de 2 años o que pese menos de 30 libras?","o":["En un asiento mirando hacia atrás con arnés de 5 puntos","En un asiento elevador","En un asiento mirando hacia adelante con cinturón de cadera","Con un cinturón de seguridad de adulto"],"h1":"Los niños más pequeños miran hacia la parte de atrás del carro.","h2":"En Connecticut un niño menor de 2 años, o que pese menos de 30 libras, debe viajar en un asiento mirando hacia atrás con arnés de 5 puntos.","p":"Correcto. Los bebés y niños pequeños viajan mirando hacia atrás."},"zh":{"q":"在 Connecticut，2 岁以下或体重不到 30 磅的孩子坐车时必须怎么坐？","o":["坐在后向的儿童安全座椅里，用 5 点式安全带","坐在增高座椅里","坐在前向座椅里，用腰部安全带","用大人的安全带"],"h1":"最小的孩子要面向车的后面。","h2":"在 Connecticut，2 岁以下或体重不到 30 磅的孩子必须坐在后向的儿童安全座椅里，并用 5 点式安全带。","p":"对。婴儿和小幼儿要面向后坐。"},"vi":{"q":"Ở Connecticut, trẻ dưới 2 tuổi, hoặc nặng dưới 30 pound, phải ngồi trên xe như thế nào?","o":["Trong ghế xe quay mặt về phía sau, có dây đai 5 điểm","Trong ghế nâng (booster seat)","Trong ghế quay mặt về phía trước, có dây an toàn ngang hông","Với dây an toàn của người lớn"],"h1":"Những trẻ nhỏ nhất ngồi quay mặt về phía sau xe.","h2":"Ở Connecticut, trẻ dưới 2 tuổi, hoặc nặng dưới 30 pound, phải ngồi trong ghế xe quay mặt về phía sau, có dây đai 5 điểm.","p":"Đúng. Em bé và trẻ nhỏ ngồi quay mặt về phía sau."},"tl":{"q":"Sa Connecticut, paano dapat sumakay sa kotse ang batang wala pang 2 taong gulang, o wala pang 30 pounds?","o":["Sa rear-facing na car seat na may 5-point harness","Sa booster seat","Sa forward-facing na upuan na may lap belt","Gamit ang seat belt ng adult"],"h1":"Ang pinakamaliliit na bata ay nakaharap sa likod ng kotse.","h2":"Sa Connecticut, ang batang wala pang 2 taong gulang, o wala pang 30 pounds, ay dapat sumakay sa rear-facing na car seat na may 5-point harness.","p":"Tama. Ang mga baby at maliliit na bata ay nakaharap sa likod."},"ar":{"q":"في Connecticut، كيف يجب أن يركب في السيارة طفل عمره أقل من 2 سنة، أو وزنه أقل من 30 رطلًا؟","o":["في مقعد سيارة مواجه للخلف مع حزام من 5 نقاط","في مقعد رافع (booster seat)","في مقعد مواجه للأمام مع حزام حول الخصر","بحزام أمان الكبار"],"h1":"أصغر الأطفال يكون وجههم نحو مؤخرة السيارة.","h2":"في Connecticut يجب أن يركب الطفل الذي عمره أقل من 2 سنة، أو وزنه أقل من 30 رطلًا، في مقعد سيارة مواجه للخلف مع حزام من 5 نقاط.","p":"صحيح. الرضّع والأطفال الصغار يركبون ووجههم نحو الخلف."},"ref":{"doc":"CT","page":12}},{"id":"ct-025","scope":"CT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Connecticut, what happens to your license if you refuse a blood, breath or urine test after a DUI arrest?","o":["Nothing, if you pass a walking test","It is suspended for at least 45 days, and you need an ignition interlock device","You get a warning letter","It is suspended for 7 days"],"h1":"The penalty applies at any age, and it is serious.","h2":"In Connecticut refusing the test means your license is suspended for at least 45 days, and you must use an ignition interlock device to get it back.","p":"Right. Refusing brings at least a 45-day suspension and an interlock device."},"es":{"q":"En Connecticut, ¿qué pasa con su licencia si se niega a una prueba de sangre, aliento u orina después de un arresto por manejar bajo la influencia?","o":["Nada, si pasa una prueba de caminar","Se suspende por al menos 45 días y necesita un dispositivo de bloqueo de encendido","Recibe una carta de advertencia","Se suspende por 7 días"],"h1":"La sanción se aplica a cualquier edad, y es seria.","h2":"En Connecticut negarse a la prueba significa que su licencia se suspende por al menos 45 días, y debe usar un dispositivo de bloqueo de encendido para recuperarla.","p":"Correcto. Negarse trae una suspensión de al menos 45 días y un dispositivo de bloqueo."},"zh":{"q":"在 Connecticut，因酒驾或药驾被逮捕后，如果你拒绝验血、呼气或验尿，你的驾照会怎么样？","o":["如果你通过走路测试，就没事","至少被吊销 45 天，而且你需要安装点火联锁装置","你会收到一封警告信","被吊销 7 天"],"h1":"不管几岁都会受罚，而且处罚很重。","h2":"在 Connecticut，拒绝检测意味着你的驾照至少被吊销 45 天，而且你必须使用点火联锁装置才能拿回驾照。","p":"对。拒绝检测会被吊销至少 45 天，还要装联锁装置。"},"vi":{"q":"Ở Connecticut, điều gì xảy ra với bằng lái của bạn nếu bạn từ chối xét nghiệm máu, hơi thở hoặc nước tiểu sau khi bị bắt vì lái xe khi say (DUI)?","o":["Không có gì, nếu bạn qua được bài kiểm tra đi bộ","Bị treo ít nhất 45 ngày, và bạn cần thiết bị khóa khởi động xe (ignition interlock)","Bạn nhận một thư cảnh cáo","Bị treo 7 ngày"],"h1":"Hình phạt áp dụng cho mọi lứa tuổi, và nó rất nặng.","h2":"Ở Connecticut, từ chối xét nghiệm nghĩa là bằng lái của bạn bị treo ít nhất 45 ngày, và bạn phải dùng thiết bị khóa khởi động xe để lấy lại bằng.","p":"Đúng. Từ chối xét nghiệm sẽ bị treo bằng ít nhất 45 ngày và phải dùng thiết bị khóa khởi động."},"tl":{"q":"Sa Connecticut, ano ang mangyayari sa lisensya mo kung tatanggi ka sa blood, breath o urine test pagkatapos kang arestuhin dahil sa DUI?","o":["Wala, kung papasa ka sa walking test","Masususpinde ito nang hindi bababa sa 45 araw, at kailangan mo ng ignition interlock device","Makakatanggap ka ng warning letter","Masususpinde ito nang 7 araw"],"h1":"Ang parusa ay para sa kahit anong edad, at mabigat ito.","h2":"Sa Connecticut, kapag tumanggi ka sa test, masususpinde ang lisensya mo nang hindi bababa sa 45 araw, at dapat kang gumamit ng ignition interlock device para maibalik ito.","p":"Tama. Ang pagtanggi ay may suspensyon na hindi bababa sa 45 araw at interlock device."},"ar":{"q":"في Connecticut، ماذا يحدث لرخصتك إذا رفضت فحص الدم أو النَّفَس أو البول بعد القبض عليك بسبب القيادة تحت تأثير الكحول أو المخدرات (DUI)؟","o":["لا شيء، إذا نجحت في اختبار المشي","تُوقَف لمدة 45 يومًا على الأقل، وتحتاج إلى جهاز قفل التشغيل (ignition interlock)","تحصل على رسالة تحذير","تُوقَف لمدة 7 أيام"],"h1":"العقوبة تنطبق على كل الأعمار، وهي شديدة.","h2":"في Connecticut رفض الفحص يعني أن رخصتك تُوقَف لمدة 45 يومًا على الأقل، ويجب أن تستخدم جهاز قفل التشغيل حتى تستعيدها.","p":"صحيح. الرفض يؤدي إلى إيقاف لمدة 45 يومًا على الأقل وجهاز قفل التشغيل."},"ref":{"doc":"CT","page":33}},{"id":"ct-026","scope":"CT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Connecticut, what must you do when an ice cream truck has its lights flashing and its stop arm out?","o":["Honk and pass slowly","Pass only on the left side","Keep going if no children are in the road","Stop at least 10 feet away, then pass at 5 mph or less"],"h1":"Children may run out to the truck, so you must stop first.","h2":"In Connecticut you must stop at least 10 feet from the ice cream truck, then you may pass at no more than 5 mph while yielding to people crossing.","p":"Right. Stop 10 feet away, then pass at 5 mph or less."},"es":{"q":"En Connecticut, ¿qué debe hacer cuando un camión de helados tiene las luces intermitentes encendidas y el brazo de parada afuera?","o":["Tocar la bocina y pasar despacio","Pasar solo por el lado izquierdo","Seguir si no hay niños en la calle","Parar al menos a 10 pies y luego pasar a 5 mph o menos"],"h1":"Los niños pueden correr hacia el camión, así que primero debe parar.","h2":"En Connecticut usted debe parar al menos a 10 pies del camión de helados, y luego puede pasar a no más de 5 mph, cediendo el paso a las personas que cruzan.","p":"Correcto. Pare a 10 pies y luego pase a 5 mph o menos."},"zh":{"q":"在 Connecticut，当冰淇淋车的灯在闪、停车臂伸出来时，你必须怎么做？","o":["按喇叭，慢慢开过去","只能从左边开过去","如果路上没有孩子，就继续开","在至少 10 英尺外停车，然后以 5 mph 或更慢的速度开过去"],"h1":"孩子可能会跑向冰淇淋车，所以你必须先停车。","h2":"在 Connecticut，你必须在离冰淇淋车至少 10 英尺的地方停车，然后才可以用不超过 5 mph 的速度开过去，同时让过路的人先走。","p":"对。在 10 英尺外停车，然后以 5 mph 或更慢开过去。"},"vi":{"q":"Ở Connecticut, bạn phải làm gì khi xe bán kem đang nháy đèn và đưa cần báo dừng ra ngoài?","o":["Bấm còi và chạy qua chậm","Chỉ chạy qua ở bên trái","Cứ chạy tiếp nếu không có trẻ em trên đường","Dừng cách xa ít nhất 10 feet, rồi chạy qua với tốc độ 5 mph hoặc thấp hơn"],"h1":"Trẻ em có thể chạy ra xe kem, nên bạn phải dừng trước.","h2":"Ở Connecticut, bạn phải dừng cách xe bán kem ít nhất 10 feet, rồi mới được chạy qua với tốc độ không quá 5 mph và nhường đường cho người đang băng qua.","p":"Đúng. Dừng cách 10 feet, rồi chạy qua với tốc độ 5 mph hoặc thấp hơn."},"tl":{"q":"Sa Connecticut, ano ang dapat mong gawin kapag ang ice cream truck ay may kumikislap na ilaw at nakalabas ang stop arm nito?","o":["Bumusina at lumampas nang dahan-dahan","Lumampas lang sa kaliwang gilid","Tumuloy kung walang bata sa kalsada","Huminto nang hindi bababa sa 10 feet ang layo, saka lumampas sa 5 mph o mas mabagal"],"h1":"Puwedeng tumakbo ang mga bata papunta sa truck, kaya dapat huminto ka muna.","h2":"Sa Connecticut, dapat kang huminto nang hindi bababa sa 10 feet mula sa ice cream truck, saka ka puwedeng lumampas nang hindi hihigit sa 5 mph habang pinauuna ang mga taong tumatawid.","p":"Tama. Huminto nang 10 feet ang layo, saka lumampas sa 5 mph o mas mabagal."},"ar":{"q":"في Connecticut، ماذا يجب أن تفعل عندما تكون أضواء شاحنة المثلجات (الآيس كريم) تومض وذراع التوقف خارجًا منها؟","o":["أطلق البوق وتجاوزها ببطء","تجاوزها من الجهة اليسرى فقط","استمر إذا لم يكن هناك أطفال في الطريق","توقف على بُعد 10 أقدام على الأقل، ثم تجاوزها بسرعة 5 mph أو أقل"],"h1":"قد يركض الأطفال نحو الشاحنة، لذلك يجب أن تتوقف أولًا.","h2":"في Connecticut يجب أن تتوقف على بُعد 10 أقدام على الأقل من شاحنة المثلجات، ثم يجوز لك أن تتجاوزها بسرعة لا تزيد على 5 mph مع إعطاء حق المرور للناس الذين يعبرون.","p":"صحيح. توقف على بُعد 10 أقدام، ثم تجاوز بسرعة 5 mph أو أقل."},"ref":{"doc":"CT","page":18}},{"id":"ct-027","scope":"CT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Connecticut, how high can the fine be for speeding or endangering a worker in a highway work zone?","o":["Up to $100","Up to $1,000","Up to $250","Up to $500"],"h1":"Work zone fines are very high to protect workers.","h2":"In Connecticut speeding or endangering a highway worker in a work zone can bring a fine of up to $1,000, plus points on your license.","p":"Right. The fine can be as high as $1,000."},"es":{"q":"En Connecticut, ¿hasta cuánto puede ser la multa por exceso de velocidad o por poner en peligro a un trabajador en una zona de obras en la carretera?","o":["Hasta $100","Hasta $1,000","Hasta $250","Hasta $500"],"h1":"Las multas en zonas de obras son muy altas para proteger a los trabajadores.","h2":"En Connecticut el exceso de velocidad o poner en peligro a un trabajador en una zona de obras puede traer una multa de hasta $1,000, además de puntos en su licencia.","p":"Correcto. La multa puede llegar a $1,000."},"zh":{"q":"在 Connecticut，在公路施工区超速或危及工人安全，罚款最高可以是多少？","o":["最高 $100","最高 $1,000","最高 $250","最高 $500"],"h1":"为了保护工人，施工区的罚款非常高。","h2":"在 Connecticut，在施工区超速或危及公路工人安全，最高可罚款 $1,000，驾照还会被记分。","p":"对。罚款最高可达 $1,000。"},"vi":{"q":"Ở Connecticut, tiền phạt cao nhất là bao nhiêu khi chạy quá tốc độ hoặc gây nguy hiểm cho công nhân trong khu vực công trường trên xa lộ?","o":["Tối đa $100","Tối đa $1,000","Tối đa $250","Tối đa $500"],"h1":"Tiền phạt ở khu vực công trường rất cao để bảo vệ công nhân.","h2":"Ở Connecticut, chạy quá tốc độ hoặc gây nguy hiểm cho công nhân xa lộ trong khu vực công trường có thể bị phạt tối đa $1,000, cộng thêm điểm vào bằng lái.","p":"Đúng. Tiền phạt có thể lên đến $1,000."},"tl":{"q":"Sa Connecticut, gaano kalaki ang puwedeng multa sa sobrang bilis o sa paglalagay sa panganib ng isang trabahador sa highway work zone?","o":["Hanggang $100","Hanggang $1,000","Hanggang $250","Hanggang $500"],"h1":"Napakalaki ng multa sa work zone para protektahan ang mga trabahador.","h2":"Sa Connecticut, ang sobrang bilis o paglalagay sa panganib ng trabahador sa highway work zone ay puwedeng magresulta sa multang hanggang $1,000, at may dagdag na points sa lisensya mo.","p":"Tama. Puwedeng umabot sa $1,000 ang multa."},"ar":{"q":"في Connecticut، إلى كم يمكن أن تصل الغرامة على السرعة الزائدة أو تعريض عامل للخطر في منطقة أعمال على الطريق السريع؟","o":["حتى $100","حتى $1,000","حتى $250","حتى $500"],"h1":"غرامات مناطق الأعمال عالية جدًا لحماية العمال.","h2":"في Connecticut يمكن أن تؤدي السرعة الزائدة أو تعريض عامل الطريق للخطر في منطقة أعمال إلى غرامة تصل إلى $1,000، بالإضافة إلى نقاط على رخصتك.","p":"صحيح. يمكن أن تصل الغرامة إلى $1,000."},"ref":{"doc":"CT","page":15}},{"id":"ct-028","scope":"CT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Connecticut, how much space must you leave between your car and a bicycle when you pass it?","o":["At least 1 foot","At least 2 feet","At least 3 feet","At least 10 feet"],"h1":"Think of about one long step to the side.","h2":"In Connecticut, you must leave at least three feet of space when you pass a bicycle.","p":"Right. Give a bicycle at least three feet when you pass."},"es":{"q":"En Connecticut, ¿cuánto espacio debe dejar entre su auto y una bicicleta al rebasarla?","o":["Al menos 1 pie","Al menos 2 pies","Al menos 3 pies","Al menos 10 pies"],"h1":"Piense en un paso largo hacia un lado.","h2":"En Connecticut, debe dejar al menos tres pies de espacio al rebasar una bicicleta.","p":"Correcto. Deje al menos tres pies al rebasar una bicicleta."},"zh":{"q":"在 Connecticut，超过自行车时，你的车和自行车之间必须留出多少空间？","o":["至少 1 英尺","至少 2 英尺","至少 3 英尺","至少 10 英尺"],"h1":"想一想大约向旁边跨出一大步的距离。","h2":"在 Connecticut，超过自行车时，你必须留出至少 3 英尺的空间。","p":"对。超过自行车时，要留出至少 3 英尺。"},"vi":{"q":"Ở Connecticut, khi vượt xe đạp, bạn phải chừa khoảng cách bao nhiêu giữa xe của bạn và xe đạp?","o":["Ít nhất 1 foot","Ít nhất 2 feet","Ít nhất 3 feet","Ít nhất 10 feet"],"h1":"Hãy nghĩ đến khoảng một bước dài sang một bên.","h2":"Ở Connecticut, khi vượt xe đạp, bạn phải chừa khoảng cách ít nhất 3 feet.","p":"Đúng. Khi vượt xe đạp, hãy chừa ít nhất 3 feet."},"tl":{"q":"Sa Connecticut, gaano kalaking espasyo ang dapat mong iwan sa pagitan ng kotse mo at ng bisikleta kapag nilalampasan mo ito?","o":["Hindi bababa sa 1 foot","Hindi bababa sa 2 feet","Hindi bababa sa 3 feet","Hindi bababa sa 10 feet"],"h1":"Isipin ang mga isang mahabang hakbang patagilid.","h2":"Sa Connecticut, dapat kang mag-iwan ng hindi bababa sa 3 feet na espasyo kapag nilalampasan mo ang bisikleta.","p":"Tama. Bigyan ang bisikleta ng hindi bababa sa 3 feet kapag nilalampasan mo ito."},"ar":{"q":"في Connecticut، ما المسافة التي يجب أن تتركها بين سيارتك والدراجة عندما تتجاوزها؟","o":["1 قدم على الأقل","2 قدم على الأقل","3 أقدام على الأقل","10 أقدام على الأقل"],"h1":"فكّر في خطوة طويلة واحدة تقريبًا إلى الجانب.","h2":"في Connecticut، يجب أن تترك مسافة 3 أقدام على الأقل عندما تتجاوز دراجة.","p":"صحيح. اترك للدراجة 3 أقدام على الأقل عندما تتجاوزها."},"ref":{"doc":"CT","page":22}},{"id":"ct-029","scope":"CT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Connecticut, how close to a fire hydrant may you not park?","o":["Within 10 feet","Within 5 feet","Within 25 feet","Within 50 feet"],"h1":"Fire crews need room to reach the hydrant. The distance is short.","h2":"In Connecticut, you may not park within 10 feet of a fire hydrant.","p":"Right. Stay at least 10 feet away from a fire hydrant when you park."},"es":{"q":"En Connecticut, ¿a qué distancia de un hidrante no puede estacionarse?","o":["A menos de 10 pies","A menos de 5 pies","A menos de 25 pies","A menos de 50 pies"],"h1":"Los bomberos necesitan espacio para llegar al hidrante. La distancia es corta.","h2":"En Connecticut, no puede estacionarse a menos de 10 pies de un hidrante.","p":"Correcto. Quédese al menos a 10 pies de un hidrante al estacionarse."},"zh":{"q":"在 Connecticut，离消防栓多近的地方不可以停车？","o":["10 英尺以内","5 英尺以内","25 英尺以内","50 英尺以内"],"h1":"消防员需要空间接近消防栓。这个距离不长。","h2":"在 Connecticut，你不可以在离消防栓 10 英尺以内的地方停车。","p":"对。停车时要离消防栓至少 10 英尺。"},"vi":{"q":"Ở Connecticut, bạn không được đậu xe gần trụ nước cứu hỏa trong khoảng cách bao nhiêu?","o":["Trong vòng 10 feet","Trong vòng 5 feet","Trong vòng 25 feet","Trong vòng 50 feet"],"h1":"Lính cứu hỏa cần chỗ để đến được trụ nước. Khoảng cách này ngắn.","h2":"Ở Connecticut, bạn không được đậu xe trong vòng 10 feet tính từ trụ nước cứu hỏa.","p":"Đúng. Khi đậu xe, hãy cách trụ nước cứu hỏa ít nhất 10 feet."},"tl":{"q":"Sa Connecticut, gaano kalapit sa fire hydrant ang bawal kang pumarada?","o":["Sa loob ng 10 feet","Sa loob ng 5 feet","Sa loob ng 25 feet","Sa loob ng 50 feet"],"h1":"Kailangan ng mga bumbero ng espasyo para maabot ang hydrant. Maikli ang layo.","h2":"Sa Connecticut, bawal kang pumarada sa loob ng 10 feet mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 10 feet sa fire hydrant kapag pumaparada ka."},"ar":{"q":"في Connecticut، على أي مسافة من صنبور إطفاء الحريق يُمنع عليك الوقوف بسيارتك؟","o":["ضمن 10 أقدام","ضمن 5 أقدام","ضمن 25 قدمًا","ضمن 50 قدمًا"],"h1":"يحتاج رجال الإطفاء إلى مساحة للوصول إلى الصنبور. المسافة قصيرة.","h2":"في Connecticut، لا يجوز لك أن توقف سيارتك ضمن 10 أقدام من صنبور إطفاء الحريق.","p":"صحيح. ابتعد 10 أقدام على الأقل عن صنبور إطفاء الحريق عندما توقف سيارتك."},"ref":{"doc":"CT","page":37}},{"id":"ct-030","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, what is the minimum vision needed for a driver's license, with or without glasses?","o":["20/20","20/40","20/70","20/100"],"h1":"It is the same for all license classes, and glasses or contacts may be used.","h2":"In Connecticut, you need at least 20/40 vision, with or without glasses or contact lenses.","p":"Right. The minimum is 20/40, and glasses or contacts are allowed."},"es":{"q":"En Connecticut, ¿cuál es la visión mínima para una licencia de conducir, con o sin lentes?","o":["20/20","20/40","20/70","20/100"],"h1":"Es igual para todas las clases de licencia, y se pueden usar lentes o lentes de contacto.","h2":"En Connecticut, necesita una visión de al menos 20/40, con o sin lentes o lentes de contacto.","p":"Correcto. El mínimo es 20/40, y se permiten lentes o lentes de contacto."},"zh":{"q":"在 Connecticut，戴或不戴眼镜，申请驾照所需的最低视力是多少？","o":["20/20","20/40","20/70","20/100"],"h1":"所有驾照类别的要求都一样，可以戴眼镜或隐形眼镜。","h2":"在 Connecticut，你的视力至少要达到 20/40，戴不戴眼镜或隐形眼镜都可以。","p":"对。最低视力是 20/40，可以戴眼镜或隐形眼镜。"},"vi":{"q":"Ở Connecticut, thị lực tối thiểu để có bằng lái là bao nhiêu, có hoặc không đeo kính?","o":["20/20","20/40","20/70","20/100"],"h1":"Yêu cầu giống nhau cho mọi hạng bằng lái, và được phép đeo kính hoặc kính áp tròng.","h2":"Ở Connecticut, bạn cần thị lực ít nhất 20/40, có hoặc không đeo kính hay kính áp tròng.","p":"Đúng. Mức tối thiểu là 20/40, và được phép đeo kính hoặc kính áp tròng."},"tl":{"q":"Sa Connecticut, ano ang pinakamababang paningin na kailangan para sa driver's license, may salamin man o wala?","o":["20/20","20/40","20/70","20/100"],"h1":"Pareho ito para sa lahat ng klase ng lisensya, at puwedeng gumamit ng salamin o contact lens.","h2":"Sa Connecticut, kailangan mo ng paningin na hindi bababa sa 20/40, may salamin o contact lens man o wala.","p":"Tama. Ang pinakamababa ay 20/40, at puwede ang salamin o contact lens."},"ar":{"q":"في Connecticut، ما الحد الأدنى للنظر المطلوب لرخصة القيادة، بالنظارة أو بدونها؟","o":["20/20","20/40","20/70","20/100"],"h1":"الشرط نفسه لكل فئات الرخص، ويُسمح باستخدام النظارة أو العدسات اللاصقة.","h2":"في Connecticut، تحتاج إلى نظر 20/40 على الأقل، بالنظارة أو العدسات اللاصقة أو بدونها.","p":"صحيح. الحد الأدنى هو 20/40، ويُسمح بالنظارة أو العدسات اللاصقة."},"ref":{"doc":"CT","page":5}},{"id":"ct-031","scope":"CT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Connecticut, you turn on your windshield wipers because of rain. What does the law say you must also turn on?","o":["Your hazard lights","Your parking lights only","Your high beams","Your headlights"],"h1":"Other drivers need to see you better in the rain.","h2":"In Connecticut, the law says that when your wipers are on, your headlights must be on too.","p":"Right. Wipers on means headlights on."},"es":{"q":"En Connecticut, usted enciende los limpiaparabrisas porque llueve. ¿Qué más debe encender según la ley?","o":["Las luces de emergencia","Solo las luces de estacionamiento","Las luces altas","Los faros delanteros"],"h1":"Los demás conductores necesitan verlo mejor bajo la lluvia.","h2":"En Connecticut, la ley dice que si los limpiaparabrisas están encendidos, los faros delanteros también deben estarlo.","p":"Correcto. Con limpiaparabrisas encendidos, faros encendidos."},"zh":{"q":"在 Connecticut，你因为下雨打开了雨刷。法律规定你还必须打开什么？","o":["危险警示灯","只开停车灯","远光灯","前大灯"],"h1":"下雨时，其他司机需要更清楚地看到你。","h2":"在 Connecticut，法律规定，当你打开雨刷时，也必须打开前大灯。","p":"对。开雨刷，就要开前大灯。"},"vi":{"q":"Ở Connecticut, bạn bật cần gạt nước vì trời mưa. Luật nói bạn cũng phải bật gì?","o":["Đèn cảnh báo nguy hiểm","Chỉ đèn đậu xe","Đèn pha chiếu xa","Đèn pha"],"h1":"Những tài xế khác cần nhìn thấy bạn rõ hơn khi trời mưa.","h2":"Ở Connecticut, luật nói rằng khi cần gạt nước đang bật, bạn cũng phải bật đèn pha.","p":"Đúng. Bật cần gạt nước thì phải bật đèn pha."},"tl":{"q":"Sa Connecticut, binuksan mo ang windshield wipers mo dahil umuulan. Ano ang sinasabi ng batas na dapat mo ring buksan?","o":["Ang hazard lights mo","Ang parking lights mo lang","Ang high beams mo","Ang headlights mo"],"h1":"Kailangan kang makita nang mas mabuti ng ibang driver kapag umuulan.","h2":"Sa Connecticut, sinasabi ng batas na kapag nakabukas ang wipers mo, dapat nakabukas din ang headlights mo.","p":"Tama. Kapag bukas ang wipers, bukas din ang headlights."},"ar":{"q":"في Connecticut، شغّلت مسّاحات الزجاج الأمامي بسبب المطر. ماذا يقول القانون إنه يجب عليك أن تشغّل أيضًا؟","o":["أضواء التحذير","أضواء الوقوف فقط","الأضواء العالية","المصابيح الأمامية"],"h1":"يحتاج السائقون الآخرون إلى رؤيتك بشكل أفضل في المطر.","h2":"في Connecticut، يقول القانون إنه عندما تكون المسّاحات مشغّلة، يجب أن تكون المصابيح الأمامية مشغّلة أيضًا.","p":"صحيح. المسّاحات تعمل يعني أن المصابيح الأمامية تعمل."},"ref":{"doc":"CT","page":38}},{"id":"ct-032","scope":"CT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Connecticut, how long must a learner aged 18 or older hold a permit before taking the road test?","o":["30 days","60 days","90 days","180 days"],"h1":"Adults wait less time than teens who train at home.","h2":"In Connecticut, a learner aged 18 or older must hold the permit for at least 90 days before the road test.","p":"Right. Adults must hold the permit for at least 90 days."},"es":{"q":"En Connecticut, ¿cuánto tiempo debe tener el permiso un aprendiz de 18 años o más antes del examen de manejo?","o":["30 días","60 días","90 días","180 días"],"h1":"Los adultos esperan menos que los adolescentes que practican en casa.","h2":"En Connecticut, un aprendiz de 18 años o más debe tener el permiso al menos 90 días antes del examen de manejo.","p":"Correcto. Los adultos deben tener el permiso al menos 90 días."},"ref":{"doc":"CT","page":7}},{"id":"ct-033","scope":"CT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Connecticut, what is the regular (non-commercial) driver's license for passenger cars called?","o":["Class D","Class A","Class B","Class C"],"h1":"It is the class for everyday drivers, not trucks or buses.","h2":"In Connecticut, the regular non-commercial driver's license is called a Class D license.","p":"Right. The regular license is Class D."},"es":{"q":"En Connecticut, ¿cómo se llama la licencia de conducir común (no comercial) para autos de pasajeros?","o":["Clase D","Clase A","Clase B","Clase C"],"h1":"Es la clase para los conductores de todos los días, no para camiones ni autobuses.","h2":"En Connecticut, la licencia de conducir común no comercial se llama licencia Clase D.","p":"Correcto. La licencia común es Clase D."},"ref":{"doc":"CT","page":4}},{"id":"ct-034","scope":"CT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Connecticut, what is the most passengers a permit holder or a 16- or 17-year-old driver may ever carry?","o":["Two people","The number of doors on the car","Four people","The number of seat belts in the car"],"h1":"Think about what every passenger needs in order to buckle up.","h2":"In Connecticut, permit holders and 16- and 17-year-old drivers may not carry more passengers than the car has seat belts.","p":"Right. Never more passengers than seat belts."},"es":{"q":"En Connecticut, ¿cuál es el número máximo de pasajeros que puede llevar un conductor con permiso o un conductor de 16 o 17 años?","o":["Dos personas","El número de puertas del auto","Cuatro personas","El número de cinturones de seguridad del auto"],"h1":"Piense en lo que necesita cada pasajero para abrocharse.","h2":"En Connecticut, los conductores con permiso y los de 16 y 17 años no pueden llevar más pasajeros que cinturones de seguridad tenga el auto.","p":"Correcto. Nunca más pasajeros que cinturones."},"ref":{"doc":"CT","page":8}},{"id":"ct-035","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, a 17-year-old just got a motorcycle endorsement. How long must they wait before carrying a passenger on the motorcycle?","o":["30 days","Six months","One year","Until age 21"],"h1":"It is the same length as the first stage of the teen passenger limits for cars.","h2":"In Connecticut, a 16- or 17-year-old may not carry a passenger on a motorcycle for six months after getting a motorcycle endorsement.","p":"Right. No motorcycle passengers for the first six months."},"es":{"q":"En Connecticut, un joven de 17 años acaba de obtener el endoso de motocicleta. ¿Cuánto tiempo debe esperar antes de llevar a un pasajero en la motocicleta?","o":["30 días","Seis meses","Un año","Hasta los 21 años"],"h1":"Es el mismo tiempo que la primera etapa de los límites de pasajeros para adolescentes en auto.","h2":"En Connecticut, un joven de 16 o 17 años no puede llevar pasajeros en motocicleta durante seis meses después de obtener el endoso de motocicleta.","p":"Correcto. Nada de pasajeros en motocicleta los primeros seis meses."},"ref":{"doc":"CT","page":8}},{"id":"ct-036","scope":"CT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Connecticut, a 17-year-old driver is convicted for the first time of breaking the curfew or passenger rules. What happens to the license?","o":["It is suspended for 30 days","Only a written warning is given","It is suspended for one year","It is taken away until age 21"],"h1":"The first time, the suspension is counted in days.","h2":"In Connecticut, a first conviction for breaking a teen driving rule, such as the curfew or passenger limits, brings a 30-day license suspension.","p":"Right. A first teen-rule violation means a 30-day suspension."},"es":{"q":"En Connecticut, un conductor de 17 años es declarado culpable por primera vez de no respetar el horario nocturno o las reglas de pasajeros. ¿Qué pasa con su licencia?","o":["Se suspende por 30 días","Solo recibe una advertencia por escrito","Se suspende por un año","Se le quita hasta los 21 años"],"h1":"La primera vez, la suspensión se cuenta en días.","h2":"En Connecticut, la primera condena por no cumplir una regla para conductores adolescentes, como el horario nocturno o los límites de pasajeros, trae una suspensión de licencia de 30 días.","p":"Correcto. La primera falta a las reglas para adolescentes significa 30 días de suspensión."},"ref":{"doc":"CT","page":34}},{"id":"ct-037","scope":"CT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Connecticut, a 16-year-old is convicted for the first time of driving 20 mph or more over the speed limit. How long is the license suspended?","o":["7 days","30 days","60 days","Two years"],"h1":"It is longer than the suspension for a first curfew violation.","h2":"In Connecticut, a 16- or 17-year-old convicted for the first time of speeding 20 mph or more over the limit loses the license for 60 days.","p":"Right. A first offense means a 60-day suspension."},"es":{"q":"En Connecticut, un joven de 16 años es declarado culpable por primera vez de manejar 20 mph o más por encima del límite de velocidad. ¿Por cuánto tiempo se suspende su licencia?","o":["7 días","30 días","60 días","Dos años"],"h1":"Es más tiempo que la suspensión por una primera falta al horario nocturno.","h2":"En Connecticut, un joven de 16 o 17 años declarado culpable por primera vez de exceder el límite por 20 mph o más pierde la licencia por 60 días.","p":"Correcto. Una primera falta significa 60 días de suspensión."},"ref":{"doc":"CT","page":34}},{"id":"ct-038","scope":"CT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Connecticut, how long is the license of a 16- or 17-year-old suspended after a first conviction for reckless driving?","o":["10 days","30 days","60 days","Six months"],"h1":"Reckless driving is punished much more harshly than a curfew violation.","h2":"In Connecticut, a 16- or 17-year-old convicted of reckless driving for the first time has the license suspended for six months.","p":"Right. A first reckless driving conviction means a six-month suspension."},"es":{"q":"En Connecticut, ¿por cuánto tiempo se suspende la licencia de un joven de 16 o 17 años después de una primera condena por manejo imprudente?","o":["10 días","30 días","60 días","Seis meses"],"h1":"El manejo imprudente se castiga mucho más que una falta al horario nocturno.","h2":"En Connecticut, a un joven de 16 o 17 años declarado culpable de manejo imprudente por primera vez se le suspende la licencia por seis meses.","p":"Correcto. Una primera condena por manejo imprudente significa seis meses de suspensión."},"ref":{"doc":"CT","page":34}},{"id":"ct-039","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, the DMV warns you that the insurance on your registered car has lapsed. What happens if you do not respond?","o":["Nothing, as long as you do not drive the car","The car's registration is suspended","You get one extra point on your license","Your insurance company pays a fine for you"],"h1":"Think about what makes it legal to drive the car on a public road.","h2":"In Connecticut, if you do not respond to the DMV's warning about lapsed insurance, the car's registration is suspended.","p":"Right. Ignoring the warning leads to a suspended registration."},"es":{"q":"En Connecticut, el DMV le avisa que el seguro de su auto registrado se canceló. ¿Qué pasa si usted no responde?","o":["Nada, si no maneja el auto","Se suspende el registro del auto","Recibe un punto más en su licencia","Su compañía de seguros paga una multa por usted"],"h1":"Piense en lo que permite manejar el auto legalmente en una vía pública.","h2":"En Connecticut, si usted no responde al aviso del DMV sobre el seguro cancelado, se suspende el registro del auto.","p":"Correcto. Si ignora el aviso, se suspende el registro."},"ref":{"doc":"CT","page":13}},{"id":"ct-040","scope":"CT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Connecticut, a 22-year-old driver is convicted of two moving violations. What must the driver do?","o":["Complete the DMV operator retraining program","Take the knowledge test again","Get a new learner's permit","Nothing until a third violation"],"h1":"Drivers 24 and younger get fewer chances than older drivers.","h2":"In Connecticut, a driver aged 24 or younger with two or more moving violations must complete the DMV operator retraining program.","p":"Right. Two violations at 24 or younger means operator retraining."},"es":{"q":"En Connecticut, un conductor de 22 años es declarado culpable de dos infracciones de tránsito en movimiento. ¿Qué debe hacer?","o":["Completar el programa de reentrenamiento de conductores del DMV","Tomar el examen escrito otra vez","Sacar un nuevo permiso de aprendizaje","Nada hasta una tercera infracción"],"h1":"Los conductores de 24 años o menos tienen menos oportunidades que los mayores.","h2":"En Connecticut, un conductor de 24 años o menos con dos o más infracciones en movimiento debe completar el programa de reentrenamiento de conductores del DMV.","p":"Correcto. Dos infracciones a los 24 años o menos significan reentrenamiento."},"ref":{"doc":"CT","page":35}},{"id":"ct-041","scope":"CT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Connecticut, an adult driver fails a blood alcohol test after a DUI arrest. To get the license back, for at least how long must an ignition interlock device be used?","o":["One week","One month","Six months","Ten years"],"h1":"The device stays in the car for months, not days.","h2":"In Connecticut, a driver who fails the alcohol test must use an ignition interlock device for at least six months to get the license back.","p":"Right. At least six months with an ignition interlock device."},"es":{"q":"En Connecticut, un conductor adulto no pasa una prueba de alcohol en la sangre después de un arresto por manejar ebrio. Para recuperar la licencia, ¿por cuánto tiempo como mínimo debe usar un dispositivo de bloqueo de encendido?","o":["Una semana","Un mes","Seis meses","Diez años"],"h1":"El dispositivo se queda en el auto por meses, no por días.","h2":"En Connecticut, un conductor que no pasa la prueba de alcohol debe usar un dispositivo de bloqueo de encendido por al menos seis meses para recuperar la licencia.","p":"Correcto. Al menos seis meses con el dispositivo de bloqueo de encendido."},"ref":{"doc":"CT","page":33}},{"id":"ct-042","scope":"CT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Connecticut, where does the 0.02 percent alcohol limit for drivers under 21 apply?","o":["Only on highways","On public roads and on private property","Only on public roads at night","Only in school zones"],"h1":"The rule follows the young driver wherever they drive.","h2":"In Connecticut, the 0.02 percent limit for drivers under 21 applies on public roads and on private property.","p":"Right. It applies on public roads and private property alike."},"es":{"q":"En Connecticut, ¿dónde se aplica el límite de alcohol de 0.02 por ciento para conductores menores de 21 años?","o":["Solo en las autopistas","En las vías públicas y en propiedad privada","Solo en las vías públicas de noche","Solo en zonas escolares"],"h1":"La regla acompaña al conductor joven dondequiera que maneje.","h2":"En Connecticut, el límite de 0.02 por ciento para menores de 21 años se aplica en las vías públicas y en propiedad privada.","p":"Correcto. Se aplica igual en vías públicas y en propiedad privada."},"ref":{"doc":"CT","page":33}},{"id":"ct-043","scope":"CT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Connecticut, what happens to the fine for using a hand-held phone while driving through a work zone?","o":["It is cut in half","It stays the same","It is replaced by a warning","It is doubled"],"h1":"Work zones bring tougher penalties, not lighter ones.","h2":"In Connecticut, the fine for illegally using a hand-held phone or device is doubled in a work zone.","p":"Right. Hand-held phone fines are doubled in work zones."},"es":{"q":"En Connecticut, ¿qué pasa con la multa por usar un teléfono en la mano mientras maneja por una zona de construcción?","o":["Se reduce a la mitad","Sigue igual","Se cambia por una advertencia","Se duplica"],"h1":"Las zonas de construcción traen castigos más fuertes, no más leves.","h2":"En Connecticut, la multa por usar ilegalmente un teléfono o aparato en la mano se duplica en una zona de construcción.","p":"Correcto. Las multas por usar el teléfono en la mano se duplican en zonas de construcción."},"ref":{"doc":"CT","page":15}},{"id":"ct-044","scope":"CT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Connecticut, what is special about the fine for failing to yield the right-of-way to a bicyclist?","o":["It is doubled","It applies only at night","It is paid by the bicyclist","It is lower than for a car"],"h1":"The law gives bicyclists extra protection.","h2":"In Connecticut, fines are doubled for drivers who fail to yield the right-of-way to a bicyclist.","p":"Right. Failing to yield to a bicyclist means a doubled fine."},"es":{"q":"En Connecticut, ¿qué tiene de especial la multa por no ceder el paso a un ciclista?","o":["Se duplica","Solo se aplica de noche","La paga el ciclista","Es más baja que la de un auto"],"h1":"La ley da protección adicional a los ciclistas.","h2":"En Connecticut, las multas se duplican para los conductores que no ceden el paso a un ciclista.","p":"Correcto. No ceder el paso a un ciclista significa una multa doble."},"ref":{"doc":"CT","page":17}},{"id":"ct-045","scope":"CT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Connecticut, who must wear a helmet when riding a bicycle?","o":["Only riders on highways","Every rider of any age","Riders under 16 years old","Riders under 10 years old"],"h1":"The rule covers children and young teens.","h2":"In Connecticut, bicycle riders under 16 years old must wear a helmet.","p":"Right. Riders under 16 must wear a helmet."},"es":{"q":"En Connecticut, ¿quién debe usar casco al andar en bicicleta?","o":["Solo quienes van por autopistas","Todos los ciclistas de cualquier edad","Los ciclistas menores de 16 años","Los ciclistas menores de 10 años"],"h1":"La regla cubre a los niños y a los adolescentes más jóvenes.","h2":"En Connecticut, los ciclistas menores de 16 años deben usar casco.","p":"Correcto. Los menores de 16 años deben usar casco."},"ref":{"doc":"CT","page":17}},{"id":"ct-046","scope":"CT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Connecticut, you are on a road with two lanes going your way. Where does the law say you must drive?","o":["In the left lane","In the right lane, except when passing","In either lane, as you like","On the shoulder when traffic is slow"],"h1":"The left lane is meant for passing.","h2":"In Connecticut, when there are fewer than three lanes in your direction, you must drive in the right lane except when passing.","p":"Right. Keep right unless you are passing."},"es":{"q":"En Connecticut, usted va por una vía con dos carriles en su dirección. ¿Por dónde dice la ley que debe manejar?","o":["Por el carril izquierdo","Por el carril derecho, salvo para rebasar","Por cualquier carril, como prefiera","Por el acotamiento cuando el tránsito va lento"],"h1":"El carril izquierdo es para rebasar.","h2":"En Connecticut, cuando hay menos de tres carriles en su dirección, debe manejar por el carril derecho, salvo para rebasar.","p":"Correcto. Manténgase a la derecha, salvo para rebasar."},"ref":{"doc":"CT","page":23}},{"id":"ct-047","scope":"CT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Connecticut, during which dates are studded snow tires allowed?","o":["All year","October 1 to March 31","December 1 to February 28","November 15 to April 30"],"h1":"The season covers late fall, all of winter, and much of spring.","h2":"In Connecticut, studded tires are allowed from November 15 through April 30.","p":"Right. Studded tires are allowed from November 15 to April 30."},"es":{"q":"En Connecticut, ¿en qué fechas se permiten las llantas con clavos para nieve?","o":["Todo el año","Del 1 de octubre al 31 de marzo","Del 1 de diciembre al 28 de febrero","Del 15 de noviembre al 30 de abril"],"h1":"La temporada cubre el final del otoño, todo el invierno y buena parte de la primavera.","h2":"En Connecticut, las llantas con clavos se permiten del 15 de noviembre al 30 de abril.","p":"Correcto. Se permiten del 15 de noviembre al 30 de abril."},"ref":{"doc":"CT","page":25}},{"id":"ct-048","scope":"CT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Connecticut, how close to a stop sign may you not park?","o":["Within 25 feet","Within 5 feet","Within 50 feet","Within 100 feet"],"h1":"Other drivers must be able to see the sign clearly from a distance.","h2":"In Connecticut, you may not park within 25 feet of a stop sign.","p":"Right. Stay at least 25 feet from a stop sign."},"es":{"q":"En Connecticut, ¿a qué distancia de una señal de alto no se puede estacionar?","o":["A menos de 25 pies","A menos de 5 pies","A menos de 50 pies","A menos de 100 pies"],"h1":"Los demás conductores deben poder ver bien la señal desde lejos.","h2":"En Connecticut, no se puede estacionar a menos de 25 pies de una señal de alto.","p":"Correcto. Quédese al menos a 25 pies de una señal de alto."},"ref":{"doc":"CT","page":37}},{"id":"ct-049","scope":"CT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Connecticut, when you park next to a curb, what is the farthest your car may be from it?","o":["Three feet","Two feet","One foot","Six feet"],"h1":"Park as close to the curb as you can.","h2":"In Connecticut, you may not park more than one foot from the curb.","p":"Right. Park no more than one foot from the curb."},"es":{"q":"En Connecticut, cuando se estaciona junto a la acera, ¿a qué distancia máxima de ella puede quedar su auto?","o":["Tres pies","Dos pies","Un pie","Seis pies"],"h1":"Estaciónese tan cerca de la acera como pueda.","h2":"En Connecticut, no se puede estacionar a más de un pie de la acera.","p":"Correcto. Estaciónese a no más de un pie de la acera."},"ref":{"doc":"CT","page":37}},{"id":"ct-050","scope":"CT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Connecticut, a person stands at the curb at a crosswalk and raises a hand toward traffic. What must you do?","o":["Honk so the person waits","Slow or stop and let the person cross","Keep going, since the person is not in the road yet","Stop only if there is a traffic light"],"h1":"Showing the intent to cross counts, even before stepping into the road.","h2":"In Connecticut, you must slow or stop and yield when a person at the curb raises a hand to show they want to cross at a crosswalk.","p":"Right. A raised hand at the curb means you must yield."},"es":{"q":"En Connecticut, una persona está en la acera junto a un cruce peatonal y levanta la mano hacia el tránsito. ¿Qué debe hacer usted?","o":["Tocar la bocina para que espere","Reducir la velocidad o parar y dejarla cruzar","Seguir, porque todavía no está en la calle","Parar solo si hay semáforo"],"h1":"Mostrar la intención de cruzar cuenta, aun antes de bajar a la calle.","h2":"En Connecticut, usted debe reducir la velocidad o parar y ceder el paso cuando una persona en la acera levanta la mano para mostrar que quiere cruzar por un cruce peatonal.","p":"Correcto. Una mano levantada en la acera significa que debe ceder el paso."},"ref":{"doc":"CT","page":16}},{"id":"ct-051","scope":"CT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Connecticut, you come up behind a bicycle in a no-passing zone with a double yellow line. What does state law allow?","o":["You must stay behind it until the zone ends","You may pass only after you honk","You may pass it on the right shoulder","You may cross the line to pass it when it is safe"],"h1":"The law makes an exception for slow road users like bicycles.","h2":"In Connecticut, you may cross a double yellow line in a no-passing zone to pass a bicycle or other slow traffic, but only when you can see far enough ahead to pass safely.","p":"Right. You may pass it when it is safe to do so."},"es":{"q":"En Connecticut, usted va detrás de una bicicleta en una zona de no rebasar con doble línea amarilla. ¿Qué permite la ley del estado?","o":["Debe quedarse detrás hasta que termine la zona","Puede rebasar solo después de tocar la bocina","Puede rebasarla por el acotamiento derecho","Puede cruzar la línea para rebasarla cuando sea seguro"],"h1":"La ley hace una excepción para usuarios lentos de la vía, como las bicicletas.","h2":"En Connecticut, usted puede cruzar la doble línea amarilla en una zona de no rebasar para pasar a una bicicleta u otro tránsito lento, pero solo cuando pueda ver lo bastante adelante para hacerlo con seguridad.","p":"Correcto. Puede rebasarla cuando sea seguro hacerlo."},"ref":{"doc":"CT","page":18}},{"id":"dc-001","scope":"DC","cat":"licensing","sign":null,"c":2,"en":{"q":"In the District of Columbia, what is the youngest age to get a learner permit?","o":["14 years old","15 years old","16 years old","18 years old"],"h1":"It is the same age at which many teens get their first job.","h2":"In the District of Columbia, you must be at least 16 years old to get a learner permit.","p":"Right. In DC the learner permit starts at 16."},"es":{"q":"En el Distrito de Columbia, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["14 años","15 años","16 años","18 años"],"h1":"Es la misma edad en que muchos jóvenes consiguen su primer trabajo.","h2":"En el Distrito de Columbia, usted debe tener por lo menos 16 años para obtener un permiso de aprendiz.","p":"Correcto. En DC el permiso de aprendiz empieza a los 16."},"zh":{"q":"在 District of Columbia，最小几岁可以拿到学习驾照？","o":["14 岁","15 岁","16 岁","18 岁"],"h1":"它和很多青少年找到第一份工作的年龄一样。","h2":"在 District of Columbia，你必须至少 16 岁才能拿到学习驾照。","p":"对。在 DC，学习驾照从 16 岁开始。"},"vi":{"q":"Ở District of Columbia (DC), tuổi nhỏ nhất để lấy giấy phép tập lái (learner permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","18 tuổi"],"h1":"Đó là tuổi mà nhiều thiếu niên có việc làm đầu tiên.","h2":"Ở District of Columbia, bạn phải ít nhất 16 tuổi để lấy giấy phép tập lái.","p":"Đúng. Ở DC, giấy phép tập lái bắt đầu từ 16 tuổi."},"tl":{"q":"Sa District of Columbia (DC), ano ang pinakabatang edad para makakuha ng learner permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","18 taong gulang"],"h1":"Ito ang edad kung kailan maraming kabataan ang nagkakaroon ng unang trabaho.","h2":"Sa District of Columbia, dapat ay hindi bababa sa 16 taong gulang ka para makakuha ng learner permit.","p":"Tama. Sa DC, nagsisimula ang learner permit sa 16."},"ar":{"q":"في District of Columbia (DC)، ما أصغر عمر للحصول على تصريح التعلّم (learner permit)؟","o":["14 سنة","15 سنة","16 سنة","18 سنة"],"h1":"هو العمر الذي يحصل فيه كثير من المراهقين على أول عمل لهم.","h2":"في District of Columbia يجب أن يكون عمرك 16 سنة على الأقل للحصول على تصريح التعلّم.","p":"صحيح. في DC يبدأ تصريح التعلّم من عمر 16 سنة."},"ref":{"doc":"DC","page":14}},{"id":"dc-002","scope":"DC","cat":"licensing","sign":null,"c":0,"en":{"q":"In the District of Columbia, during which hours may a learner permit holder drive?","o":["6:00 a.m. to 9:00 p.m.","5:00 a.m. to midnight","Any time of day","8:00 a.m. to 6:00 p.m."],"h1":"The window starts early in the morning and ends in the evening, before late night.","h2":"In the District of Columbia, a learner permit holder may drive only between 6:00 in the morning and 9:00 at night.","p":"Right. With a DC learner permit you drive from 6 a.m. to 9 p.m."},"es":{"q":"En el Distrito de Columbia, ¿en qué horario puede manejar una persona con permiso de aprendiz?","o":["De 6:00 a.m. a 9:00 p.m.","De 5:00 a.m. a medianoche","A cualquier hora","De 8:00 a.m. a 6:00 p.m."],"h1":"El horario empieza temprano en la mañana y termina en la noche, antes de que sea muy tarde.","h2":"En el Distrito de Columbia, quien tiene permiso de aprendiz solo puede manejar entre las 6:00 de la mañana y las 9:00 de la noche.","p":"Correcto. Con permiso de aprendiz en DC se maneja de 6 a.m. a 9 p.m."},"zh":{"q":"在 District of Columbia，持学习驾照的人在什么时间可以开车？","o":["早上 6:00 到晚上 9:00","早上 5:00 到午夜","任何时间","早上 8:00 到下午 6:00"],"h1":"这段时间在清早开始，在晚上深夜以前结束。","h2":"在 District of Columbia，持学习驾照的人只能在早上 6:00 到晚上 9:00 之间开车。","p":"对。持 DC 学习驾照，你可以在早上 6 点到晚上 9 点开车。"},"vi":{"q":"Ở District of Columbia, người có giấy phép tập lái được lái xe trong những giờ nào?","o":["Từ 6:00 sáng đến 9:00 tối","Từ 5:00 sáng đến nửa đêm","Bất cứ giờ nào trong ngày","Từ 8:00 sáng đến 6:00 chiều"],"h1":"Khoảng thời gian bắt đầu từ sáng sớm và kết thúc vào buổi tối, trước khi khuya.","h2":"Ở District of Columbia, người có giấy phép tập lái chỉ được lái xe từ 6:00 sáng đến 9:00 tối.","p":"Đúng. Với giấy phép tập lái ở DC, bạn lái từ 6 giờ sáng đến 9 giờ tối."},"tl":{"q":"Sa District of Columbia, anong oras puwedeng magmaneho ang may hawak ng learner permit?","o":["6:00 a.m. hanggang 9:00 p.m.","5:00 a.m. hanggang hatinggabi","Kahit anong oras","8:00 a.m. hanggang 6:00 p.m."],"h1":"Nagsisimula ito nang maaga sa umaga at natatapos sa gabi, bago maghatinggabi.","h2":"Sa District of Columbia, ang may hawak ng learner permit ay puwedeng magmaneho lang mula 6:00 ng umaga hanggang 9:00 ng gabi.","p":"Tama. May learner permit sa DC, nagmamaneho ka mula 6 a.m. hanggang 9 p.m."},"ar":{"q":"في District of Columbia، في أي ساعات يجوز لحامل تصريح التعلّم أن يقود؟","o":["من 6:00 صباحًا إلى 9:00 مساءً","من 5:00 صباحًا إلى منتصف الليل","في أي وقت من اليوم","من 8:00 صباحًا إلى 6:00 مساءً"],"h1":"تبدأ الفترة في الصباح الباكر وتنتهي في المساء، قبل آخر الليل.","h2":"في District of Columbia يجوز لحامل تصريح التعلّم أن يقود فقط بين الساعة 6:00 صباحًا والساعة 9:00 مساءً.","p":"صحيح. بتصريح التعلّم في DC تقود من 6 صباحًا إلى 9 مساءً."},"ref":{"doc":"DC","page":14}},{"id":"dc-003","scope":"DC","cat":"licensing","sign":null,"c":3,"en":{"q":"In the District of Columbia, how many hours of supervised driving must a teen complete before getting a provisional license?","o":["10 hours","20 hours","60 hours","40 hours"],"h1":"It is the same number as a full work week.","h2":"In the District of Columbia, a teen must complete at least 40 hours of supervised driving before moving to a provisional license.","p":"Right. DC asks for 40 supervised hours first."},"es":{"q":"En el Distrito de Columbia, ¿cuántas horas de manejo supervisado debe completar un joven antes de obtener una licencia provisional?","o":["10 horas","20 horas","60 horas","40 horas"],"h1":"Es el mismo número que una semana completa de trabajo.","h2":"En el Distrito de Columbia, un joven debe completar por lo menos 40 horas de manejo supervisado antes de pasar a la licencia provisional.","p":"Correcto. DC pide primero 40 horas supervisadas."},"zh":{"q":"在 District of Columbia，青少年拿过渡驾照前，必须完成多少小时有人监督的驾驶？","o":["10 小时","20 小时","60 小时","40 小时"],"h1":"它和一个完整工作周的小时数一样。","h2":"在 District of Columbia，青少年升到过渡驾照前，必须完成至少 40 小时有人监督的驾驶。","p":"对。DC 先要求 40 小时有人监督的驾驶。"},"vi":{"q":"Ở District of Columbia, thiếu niên phải lái xe có người giám sát bao nhiêu giờ trước khi lấy bằng lái tạm thời (provisional license)?","o":["10 giờ","20 giờ","60 giờ","40 giờ"],"h1":"Đó là số giờ của một tuần làm việc đầy đủ.","h2":"Ở District of Columbia, thiếu niên phải lái xe có người giám sát ít nhất 40 giờ trước khi chuyển sang bằng lái tạm thời.","p":"Đúng. DC yêu cầu 40 giờ lái có người giám sát trước."},"tl":{"q":"Sa District of Columbia, ilang oras ng pagmamaneho na may gumagabay ang dapat tapusin ng kabataan bago makakuha ng provisional license?","o":["10 oras","20 oras","60 oras","40 oras"],"h1":"Ito ang bilang ng oras sa isang buong linggo ng trabaho.","h2":"Sa District of Columbia, dapat tapusin ng kabataan ang hindi bababa sa 40 oras ng pagmamaneho na may gumagabay bago lumipat sa provisional license.","p":"Tama. Humihingi muna ang DC ng 40 oras na may gumagabay."},"ar":{"q":"في District of Columbia، كم ساعة من القيادة تحت الإشراف يجب أن يكملها المراهق قبل الحصول على الرخصة المؤقتة (provisional license)؟","o":["10 ساعات","20 ساعة","60 ساعة","40 ساعة"],"h1":"هو عدد ساعات أسبوع عمل كامل.","h2":"في District of Columbia يجب أن يكمل المراهق 40 ساعة على الأقل من القيادة تحت الإشراف قبل الانتقال إلى الرخصة المؤقتة.","p":"صحيح. تطلب DC أولًا 40 ساعة تحت الإشراف."},"ref":{"doc":"DC","page":14}},{"id":"dc-004","scope":"DC","cat":"licensing","sign":null,"c":1,"en":{"q":"In the District of Columbia, how many hours of supervised night driving must a provisional driver complete before the next license stage?","o":["5 hours","10 hours","30 hours","50 hours"],"h1":"It is a small, round number.","h2":"In the District of Columbia, a provisional driver must complete at least 10 hours of supervised night driving before moving to the full license with conditions.","p":"Right. DC asks for 10 hours of night practice."},"es":{"q":"En el Distrito de Columbia, ¿cuántas horas de manejo nocturno supervisado debe completar un conductor provisional antes de la siguiente etapa de licencia?","o":["5 horas","10 horas","30 horas","50 horas"],"h1":"Es un número pequeño y redondo.","h2":"En el Distrito de Columbia, un conductor provisional debe completar por lo menos 10 horas de manejo nocturno supervisado antes de pasar a la licencia completa con condiciones.","p":"Correcto. DC pide 10 horas de práctica de noche."},"zh":{"q":"在 District of Columbia，持过渡驾照的司机升到下一个驾照阶段前，必须完成多少小时有人监督的夜间驾驶？","o":["5 小时","10 小时","30 小时","50 小时"],"h1":"它是一个小的整数。","h2":"在 District of Columbia，持过渡驾照的司机升到有条件的正式驾照前，必须完成至少 10 小时有人监督的夜间驾驶。","p":"对。DC 要求 10 小时夜间练习。"},"vi":{"q":"Ở District of Columbia, người có bằng lái tạm thời phải lái xe ban đêm có người giám sát bao nhiêu giờ trước giai đoạn bằng lái tiếp theo?","o":["5 giờ","10 giờ","30 giờ","50 giờ"],"h1":"Đó là một số nhỏ và tròn.","h2":"Ở District of Columbia, người có bằng lái tạm thời phải lái xe ban đêm có người giám sát ít nhất 10 giờ trước khi chuyển sang bằng lái đầy đủ có điều kiện.","p":"Đúng. DC yêu cầu 10 giờ tập lái ban đêm."},"tl":{"q":"Sa District of Columbia, ilang oras ng pagmamaneho sa gabi na may gumagabay ang dapat tapusin ng provisional driver bago ang susunod na yugto ng lisensya?","o":["5 oras","10 oras","30 oras","50 oras"],"h1":"Maliit at buong numero ito.","h2":"Sa District of Columbia, dapat tapusin ng provisional driver ang hindi bababa sa 10 oras ng pagmamaneho sa gabi na may gumagabay bago lumipat sa buong lisensya na may mga kondisyon.","p":"Tama. Humihingi ang DC ng 10 oras na pagsasanay sa gabi."},"ar":{"q":"في District of Columbia، كم ساعة من القيادة الليلية تحت الإشراف يجب أن يكملها حامل الرخصة المؤقتة قبل المرحلة التالية من الرخصة؟","o":["5 ساعات","10 ساعات","30 ساعة","50 ساعة"],"h1":"هو عدد صغير ومستدير.","h2":"في District of Columbia يجب أن يكمل حامل الرخصة المؤقتة 10 ساعات على الأقل من القيادة الليلية تحت الإشراف قبل الانتقال إلى الرخصة الكاملة بشروط.","p":"صحيح. تطلب DC عشر ساعات من التدريب الليلي."},"ref":{"doc":"DC","page":14}},{"id":"dc-005","scope":"DC","cat":"licensing","sign":null,"c":2,"en":{"q":"In the District of Columbia, how long must a teen hold a learner permit before moving to the next stage?","o":["1 month","3 months","6 months","2 years"],"h1":"It is half a year.","h2":"In the District of Columbia, a teen must hold the learner permit for at least 6 months before moving to a provisional license.","p":"Right. Six months with the permit first."},"es":{"q":"En el Distrito de Columbia, ¿cuánto tiempo debe tener un joven el permiso de aprendiz antes de pasar a la siguiente etapa?","o":["1 mes","3 meses","6 meses","2 años"],"h1":"Es medio año.","h2":"En el Distrito de Columbia, un joven debe tener el permiso de aprendiz por lo menos 6 meses antes de pasar a la licencia provisional.","p":"Correcto. Primero seis meses con el permiso."},"zh":{"q":"在 District of Columbia，青少年必须持有学习驾照多久，才能升到下一个阶段？","o":["1 个月","3 个月","6 个月","2 年"],"h1":"它是半年。","h2":"在 District of Columbia，青少年必须持有学习驾照至少 6 个月，才能升到过渡驾照。","p":"对。先持有学习驾照六个月。"},"vi":{"q":"Ở District of Columbia, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi chuyển sang giai đoạn tiếp theo?","o":["1 tháng","3 tháng","6 tháng","2 năm"],"h1":"Đó là nửa năm.","h2":"Ở District of Columbia, thiếu niên phải giữ giấy phép tập lái ít nhất 6 tháng trước khi chuyển sang bằng lái tạm thời.","p":"Đúng. Giữ giấy phép tập lái sáu tháng trước."},"tl":{"q":"Sa District of Columbia, gaano katagal dapat hawak ng kabataan ang learner permit bago lumipat sa susunod na yugto?","o":["1 buwan","3 buwan","6 na buwan","2 taon"],"h1":"Kalahating taon ito.","h2":"Sa District of Columbia, dapat hawak ng kabataan ang learner permit nang hindi bababa sa 6 na buwan bago lumipat sa provisional license.","p":"Tama. Anim na buwan muna na may permit."},"ar":{"q":"في District of Columbia، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل الانتقال إلى المرحلة التالية؟","o":["شهر واحد","3 أشهر","6 أشهر","سنتان"],"h1":"هي نصف سنة.","h2":"في District of Columbia يجب أن يحمل المراهق تصريح التعلّم 6 أشهر على الأقل قبل الانتقال إلى الرخصة المؤقتة.","p":"صحيح. ستة أشهر مع التصريح أولًا."},"ref":{"doc":"DC","page":14}},{"id":"dc-006","scope":"DC","cat":"licensing","sign":null,"c":0,"en":{"q":"In the District of Columbia, what can you do if you turn 21 while you hold a learner permit?","o":["Schedule the road test right away, without waiting out the six months","Drive alone with the permit","Skip the road test","Nothing changes; you still wait six months"],"h1":"Being an adult removes the waiting period, not the test.","h2":"In the District of Columbia, if you turn 21 while holding a learner permit, you may schedule the road test right away, without the driving certification form or the six-month wait.","p":"Right. At 21 the wait is gone, but you still take the road test."},"es":{"q":"En el Distrito de Columbia, ¿qué puede hacer si cumple 21 años mientras tiene un permiso de aprendiz?","o":["Programar el examen de manejo de inmediato, sin esperar los seis meses","Manejar solo con el permiso","No tomar el examen de manejo","Nada cambia; todavía espera seis meses"],"h1":"Ser adulto quita el tiempo de espera, no el examen.","h2":"En el Distrito de Columbia, si usted cumple 21 años con permiso de aprendiz, puede programar el examen de manejo de inmediato, sin el formulario de certificación de manejo ni la espera de seis meses.","p":"Correcto. A los 21 ya no espera, pero sí toma el examen de manejo."},"zh":{"q":"在 District of Columbia，如果你持有学习驾照时满了 21 岁，你可以怎么做？","o":["马上预约路考，不用等满六个月","用学习驾照单独开车","不用路考","什么都不变，还是要等六个月"],"h1":"成年会取消等待期，但不会取消考试。","h2":"在 District of Columbia，如果你持有学习驾照时满了 21 岁，你可以马上预约路考，不需要驾驶证明表，也不用等六个月。","p":"对。21 岁时不用再等，但还是要路考。"},"vi":{"q":"Ở District of Columbia, bạn có thể làm gì nếu bạn tròn 21 tuổi khi đang có giấy phép tập lái?","o":["Đặt lịch thi lái xe ngay, không cần chờ hết sáu tháng","Lái xe một mình với giấy phép tập lái","Bỏ qua bài thi lái xe","Không có gì thay đổi; bạn vẫn chờ sáu tháng"],"h1":"Là người lớn thì bỏ được thời gian chờ, nhưng không bỏ được bài thi.","h2":"Ở District of Columbia, nếu bạn tròn 21 tuổi khi đang có giấy phép tập lái, bạn có thể đặt lịch thi lái xe ngay, không cần mẫu xác nhận giờ lái và không cần chờ sáu tháng.","p":"Đúng. Đến 21 tuổi thì không phải chờ, nhưng bạn vẫn phải thi lái xe."},"tl":{"q":"Sa District of Columbia, ano ang puwede mong gawin kung mag-21 ka habang may hawak kang learner permit?","o":["Mag-iskedyul agad ng road test, nang hindi hinihintay ang anim na buwan","Magmaneho nang mag-isa gamit ang permit","Laktawan ang road test","Walang nagbabago; maghihintay ka pa rin ng anim na buwan"],"h1":"Ang pagiging adulto ay nag-aalis ng paghihintay, hindi ng test.","h2":"Sa District of Columbia, kung mag-21 ka habang may hawak na learner permit, puwede kang mag-iskedyul agad ng road test, nang walang driving certification form at walang anim na buwang paghihintay.","p":"Tama. Sa 21, wala nang paghihintay, pero kukuha ka pa rin ng road test."},"ar":{"q":"في District of Columbia، ماذا يمكنك أن تفعل إذا بلغت 21 سنة وأنت تحمل تصريح التعلّم؟","o":["تحجز اختبار القيادة على الطريق فورًا، دون انتظار الأشهر الستة","تقود وحدك بالتصريح","تتخطى اختبار القيادة على الطريق","لا يتغير شيء؛ ما زلت تنتظر ستة أشهر"],"h1":"كونك بالغًا يلغي فترة الانتظار، لا الاختبار.","h2":"في District of Columbia إذا بلغت 21 سنة وأنت تحمل تصريح التعلّم، يمكنك حجز اختبار القيادة على الطريق فورًا، دون استمارة إثبات ساعات القيادة ودون انتظار ستة أشهر.","p":"صحيح. في عمر 21 يزول الانتظار، لكنك ما زلت تخضع لاختبار القيادة على الطريق."},"ref":{"doc":"DC","page":15}},{"id":"dc-007","scope":"DC","cat":"licensing","sign":null,"c":1,"en":{"q":"In the District of Columbia, from September to June, until what time may a provisional driver drive on a Monday through Thursday night?","o":["9:00 p.m.","10:59 p.m.","11:59 p.m.","1:00 a.m."],"h1":"It is one minute before 11 at night.","h2":"In the District of Columbia, from September to June, a provisional driver may drive on Monday through Thursday only until 10:59 at night.","p":"Right. From Monday to Thursday the limit is 10:59 p.m."},"es":{"q":"En el Distrito de Columbia, de septiembre a junio, ¿hasta qué hora puede manejar un conductor provisional de lunes a jueves en la noche?","o":["9:00 p.m.","10:59 p.m.","11:59 p.m.","1:00 a.m."],"h1":"Es un minuto antes de las 11 de la noche.","h2":"En el Distrito de Columbia, de septiembre a junio, un conductor provisional puede manejar de lunes a jueves solo hasta las 10:59 de la noche.","p":"Correcto. De lunes a jueves el límite es 10:59 p.m."},"zh":{"q":"在 District of Columbia，从九月到六月，持过渡驾照的司机星期一到星期四晚上可以开车到几点？","o":["晚上 9:00","晚上 10:59","晚上 11:59","凌晨 1:00"],"h1":"它是晚上 11 点前一分钟。","h2":"在 District of Columbia，从九月到六月，持过渡驾照的司机星期一到星期四只能开车到晚上 10:59。","p":"对。星期一到星期四的限制是晚上 10:59。"},"vi":{"q":"Ở District of Columbia, từ tháng Chín đến tháng Sáu, người có bằng lái tạm thời được lái xe đến mấy giờ vào tối thứ Hai đến thứ Năm?","o":["9:00 tối","10:59 tối","11:59 tối","1:00 sáng"],"h1":"Đó là một phút trước 11 giờ đêm.","h2":"Ở District of Columbia, từ tháng Chín đến tháng Sáu, người có bằng lái tạm thời chỉ được lái xe vào thứ Hai đến thứ Năm cho đến 10:59 tối.","p":"Đúng. Từ thứ Hai đến thứ Năm, giới hạn là 10:59 tối."},"tl":{"q":"Sa District of Columbia, mula Setyembre hanggang Hunyo, hanggang anong oras puwedeng magmaneho ang provisional driver sa gabi ng Lunes hanggang Huwebes?","o":["9:00 p.m.","10:59 p.m.","11:59 p.m.","1:00 a.m."],"h1":"Isang minuto ito bago mag-11 ng gabi.","h2":"Sa District of Columbia, mula Setyembre hanggang Hunyo, ang provisional driver ay puwedeng magmaneho sa Lunes hanggang Huwebes hanggang 10:59 ng gabi lang.","p":"Tama. Mula Lunes hanggang Huwebes, ang limitasyon ay 10:59 p.m."},"ar":{"q":"في District of Columbia، من سبتمبر إلى يونيو، حتى أي ساعة يجوز لحامل الرخصة المؤقتة أن يقود في ليالي الاثنين إلى الخميس؟","o":["9:00 مساءً","10:59 مساءً","11:59 مساءً","1:00 صباحًا"],"h1":"هي دقيقة واحدة قبل الساعة 11 ليلًا.","h2":"في District of Columbia، من سبتمبر إلى يونيو، يجوز لحامل الرخصة المؤقتة أن يقود من الاثنين إلى الخميس حتى الساعة 10:59 مساءً فقط.","p":"صحيح. من الاثنين إلى الخميس الحد هو 10:59 مساءً."},"ref":{"doc":"DC","page":14}},{"id":"dc-008","scope":"DC","cat":"licensing","sign":null,"c":3,"en":{"q":"In the District of Columbia, in July and August, until what time may a provisional driver drive alone?","o":["9:00 p.m. every day","10:59 p.m. every day","There is no limit in summer","11:59 p.m. every day"],"h1":"In summer the latest time is the same every day, just before midnight.","h2":"In the District of Columbia, in July and August, a provisional driver may drive alone every day until 11:59 at night.","p":"Right. Summer nights end at 11:59 p.m."},"es":{"q":"En el Distrito de Columbia, en julio y agosto, ¿hasta qué hora puede manejar solo un conductor provisional?","o":["9:00 p.m. todos los días","10:59 p.m. todos los días","No hay límite en verano","11:59 p.m. todos los días"],"h1":"En verano la hora límite es igual todos los días, justo antes de medianoche.","h2":"En el Distrito de Columbia, en julio y agosto, un conductor provisional puede manejar solo todos los días hasta las 11:59 de la noche.","p":"Correcto. En verano el límite es 11:59 p.m."},"zh":{"q":"在 District of Columbia，在七月和八月，持过渡驾照的司机可以单独开车到几点？","o":["每天晚上 9:00","每天晚上 10:59","夏天没有限制","每天晚上 11:59"],"h1":"夏天每天最晚的时间都一样，就在午夜之前。","h2":"在 District of Columbia，在七月和八月，持过渡驾照的司机每天可以单独开车到晚上 11:59。","p":"对。夏天晚上到 11:59 为止。"},"vi":{"q":"Ở District of Columbia, vào tháng Bảy và tháng Tám, người có bằng lái tạm thời được lái xe một mình đến mấy giờ?","o":["9:00 tối mỗi ngày","10:59 tối mỗi ngày","Mùa hè không có giới hạn","11:59 tối mỗi ngày"],"h1":"Vào mùa hè, giờ muộn nhất giống nhau mỗi ngày, ngay trước nửa đêm.","h2":"Ở District of Columbia, vào tháng Bảy và tháng Tám, người có bằng lái tạm thời được lái xe một mình mỗi ngày đến 11:59 tối.","p":"Đúng. Tối mùa hè kết thúc lúc 11:59 tối."},"tl":{"q":"Sa District of Columbia, sa Hulyo at Agosto, hanggang anong oras puwedeng magmaneho nang mag-isa ang provisional driver?","o":["9:00 p.m. araw-araw","10:59 p.m. araw-araw","Walang limitasyon sa tag-init","11:59 p.m. araw-araw"],"h1":"Sa tag-init, pareho ang pinakahuling oras araw-araw, bago maghatinggabi.","h2":"Sa District of Columbia, sa Hulyo at Agosto, ang provisional driver ay puwedeng magmaneho nang mag-isa araw-araw hanggang 11:59 ng gabi.","p":"Tama. Natatapos ang gabi sa tag-init sa 11:59 p.m."},"ar":{"q":"في District of Columbia، في يوليو وأغسطس، حتى أي ساعة يجوز لحامل الرخصة المؤقتة أن يقود وحده؟","o":["9:00 مساءً كل يوم","10:59 مساءً كل يوم","لا يوجد حد في الصيف","11:59 مساءً كل يوم"],"h1":"في الصيف آخر وقت هو نفسه كل يوم، قبل منتصف الليل مباشرة.","h2":"في District of Columbia، في يوليو وأغسطس، يجوز لحامل الرخصة المؤقتة أن يقود وحده كل يوم حتى الساعة 11:59 مساءً.","p":"صحيح. ليالي الصيف تنتهي عند 11:59 مساءً."},"ref":{"doc":"DC","page":14}},{"id":"dc-009","scope":"DC","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In the District of Columbia, what is the speed limit on a street with no speed limit sign?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"It is lower than in most states, and it has been since 2020.","h2":"In the District of Columbia, the speed limit is 20 miles per hour on any street where no other limit is posted.","p":"Right. The DC default is 20 mph."},"es":{"q":"En el Distrito de Columbia, ¿cuál es el límite de velocidad en una calle que no tiene letrero de límite?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Es más bajo que en la mayoría de los estados, y así es desde 2020.","h2":"En el Distrito de Columbia, el límite de velocidad es de 20 millas por hora en cualquier calle donde no haya otro límite indicado.","p":"Correcto. En DC el límite general es 20 mph."},"zh":{"q":"在 District of Columbia，没有限速标志的街道限速是多少？","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"它比大多数州低，从 2020 年起就是这样。","h2":"在 District of Columbia，任何没有标示其他限速的街道，限速是每小时 20 英里。","p":"对。DC 的默认限速是 20 mph。"},"vi":{"q":"Ở District of Columbia, tốc độ tối đa trên đường không có biển báo tốc độ là bao nhiêu?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Nó thấp hơn ở hầu hết các tiểu bang, và như vậy từ năm 2020.","h2":"Ở District of Columbia, tốc độ tối đa là 20 dặm một giờ (mph) trên mọi con đường không có biển báo giới hạn khác.","p":"Đúng. Tốc độ mặc định ở DC là 20 mph."},"tl":{"q":"Sa District of Columbia, ano ang speed limit sa kalyeng walang karatula ng speed limit?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Mas mababa ito kaysa sa karamihan ng estado, at ganito na mula 2020.","h2":"Sa District of Columbia, ang speed limit ay 20 milya bawat oras (mph) sa anumang kalye na walang ibang nakapaskil na limitasyon.","p":"Tama. Ang default sa DC ay 20 mph."},"ar":{"q":"في District of Columbia، ما حد السرعة في شارع لا توجد فيه لافتة حد السرعة؟","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"هو أقل مما في معظم الولايات، وهو كذلك منذ 2020.","h2":"في District of Columbia حد السرعة هو 20 ميلًا في الساعة (mph) في أي شارع لا يوجد فيه حد آخر مكتوب.","p":"صحيح. الحد العادي في DC هو 20 mph."},"ref":{"doc":"DC","page":46}},{"id":"dc-010","scope":"DC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In the District of Columbia, what is the speed limit next to a school at the times shown on the signs?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"It is lower than the city's usual 20 mph.","h2":"In the District of Columbia, the speed limit on streets next to schools is 15 miles per hour at the times shown on the signs.","p":"Right. 15 mph near schools."},"es":{"q":"En el Distrito de Columbia, ¿cuál es el límite de velocidad junto a una escuela en los horarios indicados en los letreros?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Es más bajo que el límite general de 20 mph de la ciudad.","h2":"En el Distrito de Columbia, el límite de velocidad en las calles junto a las escuelas es de 15 millas por hora en los horarios indicados en los letreros.","p":"Correcto. 15 mph cerca de las escuelas."},"zh":{"q":"在 District of Columbia，在标志写的时间内，学校旁边的限速是多少？","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"它比城市一般的 20 mph 低。","h2":"在 District of Columbia，在标志写的时间内，学校旁边街道的限速是每小时 15 英里。","p":"对。学校附近 15 mph。"},"vi":{"q":"Ở District of Columbia, tốc độ tối đa gần trường học vào những giờ ghi trên biển báo là bao nhiêu?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Nó thấp hơn mức 20 mph thông thường của thành phố.","h2":"Ở District of Columbia, tốc độ tối đa trên đường gần trường học là 15 dặm một giờ (mph) vào những giờ ghi trên biển báo.","p":"Đúng. 15 mph gần trường học."},"tl":{"q":"Sa District of Columbia, ano ang speed limit malapit sa paaralan sa mga oras na nakasulat sa karatula?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Mas mababa ito kaysa sa karaniwang 20 mph ng lungsod.","h2":"Sa District of Columbia, ang speed limit sa mga kalyeng malapit sa paaralan ay 15 milya bawat oras (mph) sa mga oras na nakasulat sa karatula.","p":"Tama. 15 mph malapit sa paaralan."},"ar":{"q":"في District of Columbia، ما حد السرعة بجانب مدرسة في الأوقات المكتوبة على اللافتات؟","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"هو أقل من حد المدينة المعتاد 20 mph.","h2":"في District of Columbia حد السرعة في الشوارع بجانب المدارس هو 15 ميلًا في الساعة (mph) في الأوقات المكتوبة على اللافتات.","p":"صحيح. 15 mph قرب المدارس."},"ref":{"doc":"DC","page":46}},{"id":"dc-011","scope":"DC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In the District of Columbia, how may an adult driver talk on a cell phone while the car is moving?","o":["Holding the phone at the ear","Only while stopped at a red light, holding the phone","Only with a hands-free device","Never, not even hands-free"],"h1":"Both hands must be able to stay on the wheel.","h2":"In the District of Columbia, an adult driver may use a cell phone while moving only with a hands-free device.","p":"Right. In DC, adults must use hands-free."},"es":{"q":"En el Distrito de Columbia, ¿cómo puede un conductor adulto hablar por celular mientras el auto está en movimiento?","o":["Sosteniendo el teléfono en el oído","Solo en un semáforo en rojo, sosteniendo el teléfono","Solo con un dispositivo de manos libres","Nunca, ni con manos libres"],"h1":"Las dos manos deben poder quedarse en el volante.","h2":"En el Distrito de Columbia, un conductor adulto solo puede usar el celular en movimiento con un dispositivo de manos libres.","p":"Correcto. En DC los adultos deben usar manos libres."},"zh":{"q":"在 District of Columbia，车在行驶时，成年司机可以怎样用手机打电话？","o":["把手机拿在耳边","只在红灯停车时，拿着手机","只能用免持设备","从来不可以，免持也不行"],"h1":"两只手都必须能一直放在方向盘上。","h2":"在 District of Columbia，成年司机在车行驶时只能用免持设备用手机。","p":"对。在 DC，成年人必须用免持。"},"vi":{"q":"Ở District of Columbia, người lái xe trưởng thành được nói chuyện điện thoại di động như thế nào khi xe đang chạy?","o":["Cầm điện thoại áp vào tai","Chỉ khi dừng đèn đỏ, cầm điện thoại","Chỉ với thiết bị rảnh tay (hands-free)","Không bao giờ, kể cả rảnh tay"],"h1":"Cả hai tay phải có thể giữ trên vô lăng.","h2":"Ở District of Columbia, người lái xe trưởng thành chỉ được dùng điện thoại di động khi xe đang chạy nếu dùng thiết bị rảnh tay.","p":"Đúng. Ở DC, người lớn phải dùng thiết bị rảnh tay."},"tl":{"q":"Sa District of Columbia, paano puwedeng makipag-usap sa cell phone ang adultong driver habang umaandar ang sasakyan?","o":["Hawak ang phone sa tainga","Habang nakahinto lang sa pulang ilaw, hawak ang phone","Gamit lang ang hands-free na device","Hindi kailanman, kahit hands-free"],"h1":"Dapat manatili sa manibela ang dalawang kamay.","h2":"Sa District of Columbia, ang adultong driver ay puwedeng gumamit ng cell phone habang umaandar lang kung may hands-free na device.","p":"Tama. Sa DC, dapat hands-free ang mga adulto."},"ar":{"q":"في District of Columbia، كيف يجوز للسائق البالغ أن يتكلم في الهاتف المحمول والسيارة تسير؟","o":["يمسك الهاتف على أذنه","فقط عند التوقف عند الإشارة الحمراء، ممسكًا الهاتف","فقط بجهاز بدون استخدام اليدين (hands-free)","أبدًا، ولا حتى بدون استخدام اليدين"],"h1":"يجب أن تبقى اليدان كلتاهما على المقود.","h2":"في District of Columbia يجوز للسائق البالغ أن يستعمل الهاتف المحمول والسيارة تسير فقط بجهاز بدون استخدام اليدين.","p":"صحيح. في DC يجب على البالغين استخدام جهاز بدون يدين."},"ref":{"doc":"DC","page":26}},{"id":"dc-012","scope":"DC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In the District of Columbia, may a learner permit holder use a hands-free phone while driving?","o":["Yes, hands-free is always allowed","Yes, but only on highways","Yes, if the supervisor agrees","No, only to call for an emergency"],"h1":"The rule for learners is stricter than the rule for adults.","h2":"In the District of Columbia, a learner permit holder may not use a cell phone at all while driving, even hands-free, except to make an emergency call.","p":"Right. Learners in DC put the phone away, hands-free included."},"es":{"q":"En el Distrito de Columbia, ¿puede una persona con permiso de aprendiz usar un teléfono de manos libres mientras maneja?","o":["Sí, manos libres siempre está permitido","Sí, pero solo en autopistas","Sí, si el acompañante está de acuerdo","No, solo para llamar en una emergencia"],"h1":"La regla para aprendices es más estricta que la regla para adultos.","h2":"En el Distrito de Columbia, quien tiene permiso de aprendiz no puede usar el celular mientras maneja, ni con manos libres, excepto para hacer una llamada de emergencia.","p":"Correcto. En DC los aprendices guardan el teléfono, incluso el de manos libres."},"zh":{"q":"在 District of Columbia，持学习驾照的人开车时可以用免持电话吗？","o":["可以，免持总是允许的","可以，但只在公路上","可以，如果监督的人同意","不可以，只能打紧急电话"],"h1":"对学习驾驶的人的规定比对成年人更严。","h2":"在 District of Columbia，持学习驾照的人开车时完全不能用手机，即使是免持也不行，打紧急电话除外。","p":"对。在 DC 学习驾驶的人要把手机收起来，免持也一样。"},"vi":{"q":"Ở District of Columbia, người có giấy phép tập lái có được dùng điện thoại rảnh tay khi lái xe không?","o":["Có, rảnh tay thì luôn được phép","Có, nhưng chỉ trên đường cao tốc","Có, nếu người giám sát đồng ý","Không, chỉ được gọi khi khẩn cấp"],"h1":"Quy định cho người tập lái nghiêm hơn quy định cho người lớn.","h2":"Ở District of Columbia, người có giấy phép tập lái hoàn toàn không được dùng điện thoại di động khi lái xe, kể cả rảnh tay, trừ khi gọi khẩn cấp.","p":"Đúng. Người tập lái ở DC phải cất điện thoại, kể cả rảnh tay."},"tl":{"q":"Sa District of Columbia, puwede bang gumamit ng hands-free na phone habang nagmamaneho ang may hawak ng learner permit?","o":["Oo, laging puwede ang hands-free","Oo, pero sa highway lang","Oo, kung papayag ang gumagabay","Hindi, maliban sa pagtawag kapag may emergency"],"h1":"Mas mahigpit ang patakaran para sa nag-aaral kaysa sa mga adulto.","h2":"Sa District of Columbia, ang may hawak ng learner permit ay hindi puwedeng gumamit ng cell phone habang nagmamaneho, kahit hands-free, maliban sa pagtawag kapag may emergency.","p":"Tama. Sa DC, itinatabi ng nag-aaral ang phone, kahit hands-free."},"ar":{"q":"في District of Columbia، هل يجوز لحامل تصريح التعلّم أن يستعمل هاتفًا بدون استخدام اليدين (hands-free) أثناء القيادة؟","o":["نعم، بدون اليدين مسموح دائمًا","نعم، لكن على الطرق السريعة فقط","نعم، إذا وافق المشرف","لا، إلا للاتصال في حالة طوارئ"],"h1":"القاعدة للمتعلمين أشد من القاعدة للبالغين.","h2":"في District of Columbia لا يجوز لحامل تصريح التعلّم أن يستعمل الهاتف المحمول أبدًا أثناء القيادة، ولا حتى بدون استخدام اليدين، إلا للاتصال في حالة طوارئ.","p":"صحيح. المتعلمون في DC يبعدون الهاتف، حتى بدون استخدام اليدين."},"ref":{"doc":"DC","page":15}},{"id":"dc-013","scope":"DC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In the District of Columbia, how much alcohol may a driver under 21 have in the body?","o":["None; any measurable amount is against the law","Up to 0.02","Up to 0.05","Up to 0.08"],"h1":"Think of the lowest possible amount.","h2":"In the District of Columbia, a driver under 21 may not have any measurable amount of alcohol, and can be arrested for driving while intoxicated.","p":"Right. Under 21 in DC, the limit is zero."},"es":{"q":"En el Distrito de Columbia, ¿cuánto alcohol puede tener en el cuerpo un conductor menor de 21 años?","o":["Nada; cualquier cantidad que se pueda medir es ilegal","Hasta 0.02","Hasta 0.05","Hasta 0.08"],"h1":"Piense en la cantidad más baja posible.","h2":"En el Distrito de Columbia, un conductor menor de 21 años no puede tener ninguna cantidad medible de alcohol, y lo pueden arrestar por manejar intoxicado.","p":"Correcto. Para menores de 21 en DC, el límite es cero."},"zh":{"q":"在 District of Columbia，21 岁以下的司机体内可以有多少酒精？","o":["一点都不能有；任何可以测出的量都是违法的","最多 0.02","最多 0.05","最多 0.08"],"h1":"想一想最低可能的量。","h2":"在 District of Columbia，21 岁以下的司机体内不能有任何可以测出的酒精，否则可能因醉酒驾驶被逮捕。","p":"对。在 DC，21 岁以下的限制是零。"},"vi":{"q":"Ở District of Columbia, người lái xe dưới 21 tuổi được có bao nhiêu rượu bia trong cơ thể?","o":["Không có; bất kỳ lượng nào đo được đều phạm luật","Tối đa 0.02","Tối đa 0.05","Tối đa 0.08"],"h1":"Hãy nghĩ đến mức thấp nhất có thể.","h2":"Ở District of Columbia, người lái xe dưới 21 tuổi không được có bất kỳ lượng rượu bia nào đo được, và có thể bị bắt vì lái xe khi say.","p":"Đúng. Dưới 21 tuổi ở DC, giới hạn là không."},"tl":{"q":"Sa District of Columbia, gaano karaming alak ang puwedeng nasa katawan ng driver na wala pang 21?","o":["Wala; labag sa batas ang anumang dami na nasusukat","Hanggang 0.02","Hanggang 0.05","Hanggang 0.08"],"h1":"Isipin ang pinakamababang posibleng dami.","h2":"Sa District of Columbia, ang driver na wala pang 21 ay hindi puwedeng magkaroon ng anumang dami ng alak na nasusukat, at puwede siyang arestuhin dahil sa pagmamaneho nang lasing.","p":"Tama. Wala pang 21 sa DC, zero ang limitasyon."},"ar":{"q":"في District of Columbia، كم كحولًا يجوز أن يكون في جسم السائق الذي عمره أقل من 21 سنة؟","o":["لا شيء؛ أي كمية يمكن قياسها مخالفة للقانون","حتى 0.02","حتى 0.05","حتى 0.08"],"h1":"فكّر في أقل كمية ممكنة.","h2":"في District of Columbia لا يجوز أن يكون لدى السائق الذي عمره أقل من 21 سنة أي كمية كحول يمكن قياسها، ويمكن القبض عليه بتهمة القيادة تحت تأثير الكحول.","p":"صحيح. تحت 21 سنة في DC الحد هو صفر."},"ref":{"doc":"DC","page":null}},{"id":"dc-014","scope":"DC","cat":"licensing","sign":null,"c":1,"en":{"q":"In the District of Columbia, how long is a learner permit valid for a US citizen?","o":["6 months","2 years","4 years","8 years"],"h1":"It is longer than one year, but you cannot renew it.","h2":"In the District of Columbia, a learner permit is valid for two years for a US citizen and cannot be renewed; after that you must pass the knowledge test again.","p":"Right. The permit lasts two years and cannot be renewed."},"es":{"q":"En el Distrito de Columbia, ¿por cuánto tiempo es válido el permiso de aprendiz para un ciudadano de EE. UU.?","o":["6 meses","2 años","4 años","8 años"],"h1":"Es más de un año, pero no se puede renovar.","h2":"En el Distrito de Columbia, el permiso de aprendiz es válido por dos años para un ciudadano de EE. UU. y no se puede renovar; después usted debe aprobar otra vez el examen de conocimientos.","p":"Correcto. El permiso dura dos años y no se puede renovar."},"zh":{"q":"在 District of Columbia，美国公民的学习驾照有效期是多久？","o":["6 个月","2 年","4 年","8 年"],"h1":"它比一年长，但是不能续期。","h2":"在 District of Columbia，美国公民的学习驾照有效期是两年，而且不能续期；过期后你必须再考一次笔试。","p":"对。学习驾照有效两年，不能续期。"},"vi":{"q":"Ở District of Columbia, giấy phép tập lái có giá trị bao lâu đối với công dân Mỹ?","o":["6 tháng","2 năm","4 năm","8 năm"],"h1":"Nó dài hơn một năm, nhưng bạn không thể gia hạn.","h2":"Ở District of Columbia, giấy phép tập lái có giá trị hai năm đối với công dân Mỹ và không thể gia hạn; sau đó bạn phải thi lại bài thi lý thuyết.","p":"Đúng. Giấy phép tập lái có giá trị hai năm và không thể gia hạn."},"tl":{"q":"Sa District of Columbia, gaano katagal valid ang learner permit para sa US citizen?","o":["6 na buwan","2 taon","4 na taon","8 taon"],"h1":"Mas mahaba ito sa isang taon, pero hindi mo ito puwedeng i-renew.","h2":"Sa District of Columbia, valid ang learner permit nang dalawang taon para sa US citizen at hindi ito puwedeng i-renew; pagkatapos nito, dapat kang pumasa ulit sa knowledge test.","p":"Tama. Tumatagal ang permit nang dalawang taon at hindi puwedeng i-renew."},"ar":{"q":"في District of Columbia، ما مدة صلاحية تصريح التعلّم للمواطن الأمريكي؟","o":["6 أشهر","سنتان","4 سنوات","8 سنوات"],"h1":"هي أطول من سنة واحدة، لكن لا يمكنك تجديده.","h2":"في District of Columbia يكون تصريح التعلّم صالحًا لمدة سنتين للمواطن الأمريكي ولا يمكن تجديده؛ بعد ذلك يجب أن تنجح في الاختبار النظري مرة أخرى.","p":"صحيح. التصريح صالح لمدة سنتين ولا يمكن تجديده."},"ref":{"doc":"DC","page":14}},{"id":"dc-015","scope":"DC","cat":"licensing","sign":null,"c":3,"en":{"q":"In the District of Columbia, what is the youngest age to get a provisional license?","o":["16 years old","17 years old","18 years old","16 and a half years old"],"h1":"It is six months after the youngest age for a learner permit.","h2":"In the District of Columbia, you must be at least 16 and a half years old to get a provisional license.","p":"Right. The provisional license starts at 16 and a half."},"es":{"q":"En el Distrito de Columbia, ¿cuál es la edad mínima para obtener una licencia provisional?","o":["16 años","17 años","18 años","16 años y medio"],"h1":"Es seis meses después de la edad mínima para el permiso de aprendiz.","h2":"En el Distrito de Columbia, usted debe tener por lo menos 16 años y medio para obtener una licencia provisional.","p":"Correcto. La licencia provisional empieza a los 16 años y medio."},"zh":{"q":"在 District of Columbia，最小几岁可以拿到过渡驾照？","o":["16 岁","17 岁","18 岁","16 岁半"],"h1":"它比拿学习驾照的最小年龄晚六个月。","h2":"在 District of Columbia，你必须至少 16 岁半才能拿到过渡驾照。","p":"对。过渡驾照从 16 岁半开始。"},"vi":{"q":"Ở District of Columbia, tuổi nhỏ nhất để lấy bằng lái tạm thời (provisional license) là bao nhiêu?","o":["16 tuổi","17 tuổi","18 tuổi","16 tuổi rưỡi"],"h1":"Đó là sáu tháng sau tuổi nhỏ nhất để lấy giấy phép tập lái.","h2":"Ở District of Columbia, bạn phải ít nhất 16 tuổi rưỡi để lấy bằng lái tạm thời.","p":"Đúng. Bằng lái tạm thời bắt đầu từ 16 tuổi rưỡi."},"tl":{"q":"Sa District of Columbia, ano ang pinakabatang edad para makakuha ng provisional license?","o":["16 taong gulang","17 taong gulang","18 taong gulang","16 at kalahating taong gulang"],"h1":"Anim na buwan ito pagkatapos ng pinakabatang edad para sa learner permit.","h2":"Sa District of Columbia, dapat ay hindi bababa sa 16 at kalahating taong gulang ka para makakuha ng provisional license.","p":"Tama. Nagsisimula ang provisional license sa 16 at kalahati."},"ar":{"q":"في District of Columbia، ما أصغر عمر للحصول على الرخصة المؤقتة (provisional license)؟","o":["16 سنة","17 سنة","18 سنة","16 سنة ونصف"],"h1":"هو بعد ستة أشهر من أصغر عمر للحصول على تصريح التعلّم.","h2":"في District of Columbia يجب أن يكون عمرك 16 سنة ونصفًا على الأقل للحصول على الرخصة المؤقتة.","p":"صحيح. تبدأ الرخصة المؤقتة من عمر 16 سنة ونصف."},"ref":{"doc":"DC","page":14}},{"id":"dc-016","scope":"DC","cat":"licensing","sign":null,"c":0,"en":{"q":"In the District of Columbia, you fail the knowledge test. How long must you wait before you try again?","o":["3 calendar days","1 week","30 days","6 months"],"h1":"It is only a few days.","h2":"In the District of Columbia, after you fail the knowledge test you must wait 3 calendar days before you can take it again.","p":"Right. Wait 3 calendar days, then try again."},"es":{"q":"En el Distrito de Columbia, usted no aprueba el examen de conocimientos. ¿Cuánto tiempo debe esperar para intentarlo otra vez?","o":["3 días naturales","1 semana","30 días","6 meses"],"h1":"Son solo unos pocos días.","h2":"En el Distrito de Columbia, si usted no aprueba el examen de conocimientos, debe esperar 3 días naturales para volver a tomarlo.","p":"Correcto. Espere 3 días naturales y vuelva a intentarlo."},"zh":{"q":"在 District of Columbia，你笔试没有通过。你必须等多久才能再考？","o":["3 个日历日","1 个星期","30 天","6 个月"],"h1":"只有几天。","h2":"在 District of Columbia，笔试没有通过后，你必须等 3 个日历日才能再考。","p":"对。等 3 个日历日，然后再考。"},"vi":{"q":"Ở District of Columbia, bạn thi trượt bài thi lý thuyết. Bạn phải chờ bao lâu trước khi thi lại?","o":["3 ngày theo lịch","1 tuần","30 ngày","6 tháng"],"h1":"Chỉ vài ngày thôi.","h2":"Ở District of Columbia, sau khi thi trượt bài thi lý thuyết, bạn phải chờ 3 ngày theo lịch trước khi được thi lại.","p":"Đúng. Chờ 3 ngày theo lịch, rồi thi lại."},"tl":{"q":"Sa District of Columbia, bumagsak ka sa knowledge test. Gaano katagal ka dapat maghintay bago sumubok ulit?","o":["3 araw sa kalendaryo","1 linggo","30 araw","6 na buwan"],"h1":"Ilang araw lang ito.","h2":"Sa District of Columbia, pagkatapos mong bumagsak sa knowledge test, dapat kang maghintay ng 3 araw sa kalendaryo bago ka puwedeng kumuha ulit nito.","p":"Tama. Maghintay ng 3 araw sa kalendaryo, saka sumubok ulit."},"ar":{"q":"في District of Columbia، رسبت في الاختبار النظري. كم يجب أن تنتظر قبل أن تحاول مرة أخرى؟","o":["3 أيام تقويمية","أسبوع واحد","30 يومًا","6 أشهر"],"h1":"هي أيام قليلة فقط.","h2":"في District of Columbia بعد أن ترسب في الاختبار النظري يجب أن تنتظر 3 أيام تقويمية قبل أن تتمكن من إعادته.","p":"صحيح. انتظر 3 أيام تقويمية، ثم حاول مرة أخرى."},"ref":{"doc":"DC","page":12}},{"id":"dc-017","scope":"DC","cat":"licensing","sign":null,"c":2,"en":{"q":"In the District of Columbia, who may ride in the car while a learner permit holder is driving?","o":["Any friends, if they wear seat belts","Up to two passengers under 21","Only the supervising driver, who is 21 or older","Only family members"],"h1":"Think of the one person the learner needs next to them.","h2":"In the District of Columbia, a learner permit holder may not carry any passengers other than the fully licensed supervising driver, who is 21 or older and sits in the front seat.","p":"Right. With a learner permit, only the supervisor rides along."},"es":{"q":"En el Distrito de Columbia, ¿quién puede ir en el carro mientras maneja una persona con permiso de aprendiz?","o":["Cualquier amigo, si usa el cinturón","Hasta dos pasajeros menores de 21 años","Solo el conductor que supervisa, de 21 años o más","Solo familiares"],"h1":"Piense en la única persona que el aprendiz necesita a su lado.","h2":"En el Distrito de Columbia, una persona con permiso de aprendiz no puede llevar más pasajeros que el conductor supervisor con licencia completa, de 21 años o más, sentado en el asiento delantero.","p":"Correcto. Con permiso de aprendiz, solo va el supervisor."},"zh":{"q":"在 District of Columbia，持学习驾照的人开车时，谁可以坐在车里？","o":["任何朋友，只要他们系安全带","最多两个 21 岁以下的乘客","只有监督的司机，他必须 21 岁或以上","只有家人"],"h1":"想一想学习驾驶的人身边需要的那一个人。","h2":"在 District of Columbia，持学习驾照的人除了有正式驾照的监督司机以外，不能载任何乘客；监督司机必须 21 岁或以上，并且坐在前座。","p":"对。持学习驾照时，只有监督的人可以一起坐车。"},"vi":{"q":"Ở District of Columbia, ai được ngồi trong xe khi người có giấy phép tập lái đang lái?","o":["Bất kỳ người bạn nào, nếu họ thắt dây an toàn","Tối đa hai hành khách dưới 21 tuổi","Chỉ người lái xe giám sát, từ 21 tuổi trở lên","Chỉ người trong gia đình"],"h1":"Hãy nghĩ đến một người mà người tập lái cần ngồi bên cạnh.","h2":"Ở District of Columbia, người có giấy phép tập lái không được chở hành khách nào khác ngoài người lái xe giám sát có bằng lái đầy đủ, từ 21 tuổi trở lên và ngồi ở ghế trước.","p":"Đúng. Với giấy phép tập lái, chỉ người giám sát được đi cùng."},"tl":{"q":"Sa District of Columbia, sino ang puwedeng sumakay sa kotse habang nagmamaneho ang may hawak ng learner permit?","o":["Kahit sinong kaibigan, kung naka-seat belt sila","Hanggang dalawang pasaherong wala pang 21","Ang gumagabay na driver lang, na 21 o mas matanda","Mga kapamilya lang"],"h1":"Isipin ang isang taong kailangan ng nag-aaral sa tabi niya.","h2":"Sa District of Columbia, ang may hawak ng learner permit ay hindi puwedeng magsakay ng ibang pasahero maliban sa gumagabay na driver na may buong lisensya, na 21 o mas matanda at nakaupo sa harap.","p":"Tama. Kapag may learner permit, ang gumagabay lang ang kasama sa sasakyan."},"ar":{"q":"في District of Columbia، من يجوز له أن يركب في السيارة بينما يقود حامل تصريح التعلّم؟","o":["أي أصدقاء، إذا وضعوا أحزمة الأمان","حتى راكبين اثنين عمرهما أقل من 21 سنة","السائق المشرف فقط، وعمره 21 سنة أو أكثر","أفراد العائلة فقط"],"h1":"فكّر في الشخص الوحيد الذي يحتاجه المتعلم بجانبه.","h2":"في District of Columbia لا يجوز لحامل تصريح التعلّم أن يحمل أي ركاب غير السائق المشرف الذي يحمل رخصة كاملة، وعمره 21 سنة أو أكثر ويجلس في المقعد الأمامي.","p":"صحيح. مع تصريح التعلّم، يركب المشرف فقط معك."},"ref":{"doc":"DC","page":15}},{"id":"dc-018","scope":"DC","cat":"licensing","sign":null,"c":1,"en":{"q":"In the District of Columbia, a driver under 18 has a full license with conditions. How many passengers under 21 may they carry, not counting siblings or their own child?","o":["None","No more than 2","No more than 3","No more than 4"],"h1":"It is a small number, but more than one.","h2":"In the District of Columbia, a driver under 18 with a full license with conditions may carry no more than two passengers under 21, not counting their brothers, sisters or own child.","p":"Right. No more than two passengers under 21."},"es":{"q":"En el Distrito de Columbia, un conductor menor de 18 años tiene licencia completa con condiciones. ¿Cuántos pasajeros menores de 21 años puede llevar, sin contar a sus hermanos ni a su propio hijo?","o":["Ninguno","No más de 2","No más de 3","No más de 4"],"h1":"Es un número pequeño, pero más de uno.","h2":"En el Distrito de Columbia, un conductor menor de 18 años con licencia completa con condiciones puede llevar no más de dos pasajeros menores de 21 años, sin contar a sus hermanos ni a su propio hijo.","p":"Correcto. No más de dos pasajeros menores de 21 años."},"zh":{"q":"在 District of Columbia，一个 18 岁以下的司机有有条件的正式驾照。不算兄弟姐妹或自己的孩子，他可以载多少个 21 岁以下的乘客？","o":["一个都不行","不超过 2 个","不超过 3 个","不超过 4 个"],"h1":"它是一个小的数字，但比一多。","h2":"在 District of Columbia，有有条件的正式驾照、18 岁以下的司机，最多只能载两个 21 岁以下的乘客，不算他的兄弟姐妹或自己的孩子。","p":"对。21 岁以下的乘客不超过两个。"},"vi":{"q":"Ở District of Columbia, một người lái xe dưới 18 tuổi có bằng lái đầy đủ có điều kiện. Họ được chở bao nhiêu hành khách dưới 21 tuổi, không tính anh chị em hoặc con của họ?","o":["Không ai","Không quá 2","Không quá 3","Không quá 4"],"h1":"Đó là một số nhỏ, nhưng nhiều hơn một.","h2":"Ở District of Columbia, người lái xe dưới 18 tuổi có bằng lái đầy đủ có điều kiện được chở không quá hai hành khách dưới 21 tuổi, không tính anh chị em hoặc con của họ.","p":"Đúng. Không quá hai hành khách dưới 21 tuổi."},"tl":{"q":"Sa District of Columbia, may buong lisensya na may mga kondisyon ang driver na wala pang 18. Ilang pasaherong wala pang 21 ang puwede niyang isakay, hindi kasama ang mga kapatid o sariling anak?","o":["Wala","Hindi hihigit sa 2","Hindi hihigit sa 3","Hindi hihigit sa 4"],"h1":"Maliit na numero ito, pero higit sa isa.","h2":"Sa District of Columbia, ang driver na wala pang 18 na may buong lisensya na may mga kondisyon ay puwedeng magsakay ng hindi hihigit sa dalawang pasaherong wala pang 21, hindi kasama ang kanyang mga kapatid o sariling anak.","p":"Tama. Hindi hihigit sa dalawang pasaherong wala pang 21."},"ar":{"q":"في District of Columbia، سائق عمره أقل من 18 سنة يحمل الرخصة الكاملة بشروط. كم راكبًا عمره أقل من 21 سنة يجوز له أن يحمل، دون حساب إخوته وأخواته أو طفله؟","o":["لا أحد","ليس أكثر من 2","ليس أكثر من 3","ليس أكثر من 4"],"h1":"هو عدد صغير، لكنه أكثر من واحد.","h2":"في District of Columbia يجوز للسائق الذي عمره أقل من 18 سنة ويحمل الرخصة الكاملة بشروط أن يحمل راكبين اثنين على الأكثر عمرهما أقل من 21 سنة، دون حساب إخوته وأخواته أو طفله.","p":"صحيح. ليس أكثر من راكبين اثنين عمرهما أقل من 21 سنة."},"ref":{"doc":"DC","page":15}},{"id":"dc-019","scope":"DC","cat":"licensing","sign":null,"c":2,"en":{"q":"In the District of Columbia, what happens when a driver reaches 10 or 11 points?","o":["A warning letter only","A required safety class only","The license is suspended for 90 days","The license is revoked for 2 years"],"h1":"You lose your driving privileges for about three months.","h2":"In the District of Columbia, a driver who reaches 10 or 11 points has the license suspended for 90 days.","p":"Right. 10 or 11 points means a 90-day suspension."},"es":{"q":"En el Distrito de Columbia, ¿qué pasa cuando un conductor llega a 10 u 11 puntos?","o":["Solo recibe una carta de advertencia","Solo debe tomar una clase de seguridad","Le suspenden la licencia por 90 días","Le revocan la licencia por 2 años"],"h1":"Usted pierde el derecho a manejar por unos tres meses.","h2":"En el Distrito de Columbia, a un conductor que llega a 10 u 11 puntos le suspenden la licencia por 90 días.","p":"Correcto. 10 u 11 puntos significan una suspensión de 90 días."},"zh":{"q":"在 District of Columbia，司机累计到 10 或 11 分时，会怎么样？","o":["只收到一封警告信","只需要上一门安全课","驾照被暂停 90 天","驾照被吊销 2 年"],"h1":"你会失去开车的权利大约三个月。","h2":"在 District of Columbia，累计到 10 或 11 分的司机，驾照会被暂停 90 天。","p":"对。10 或 11 分就是暂停 90 天。"},"vi":{"q":"Ở District of Columbia, điều gì xảy ra khi người lái xe bị 10 hoặc 11 điểm?","o":["Chỉ nhận thư cảnh cáo","Chỉ phải học một lớp an toàn","Bằng lái bị tạm đình chỉ 90 ngày","Bằng lái bị thu hồi 2 năm"],"h1":"Bạn mất quyền lái xe khoảng ba tháng.","h2":"Ở District of Columbia, người lái xe bị 10 hoặc 11 điểm sẽ bị tạm đình chỉ bằng lái 90 ngày.","p":"Đúng. 10 hoặc 11 điểm nghĩa là bị tạm đình chỉ 90 ngày."},"tl":{"q":"Sa District of Columbia, ano ang mangyayari kapag umabot sa 10 o 11 puntos ang driver?","o":["Isang sulat ng babala lang","Isang required na safety class lang","Masususpinde ang lisensya nang 90 araw","Babawiin ang lisensya nang 2 taon"],"h1":"Mawawala ang karapatan mong magmaneho nang mga tatlong buwan.","h2":"Sa District of Columbia, ang driver na umabot sa 10 o 11 puntos ay masususpinde ang lisensya nang 90 araw.","p":"Tama. Ang 10 o 11 puntos ay 90 araw na suspensyon."},"ar":{"q":"في District of Columbia، ماذا يحدث عندما يصل السائق إلى 10 أو 11 نقطة؟","o":["رسالة تحذير فقط","دورة سلامة إلزامية فقط","تُوقَف الرخصة لمدة 90 يومًا","تُلغى الرخصة لمدة سنتين"],"h1":"تفقد حقك في القيادة لمدة ثلاثة أشهر تقريبًا.","h2":"في District of Columbia السائق الذي يصل إلى 10 أو 11 نقطة تُوقَف رخصته لمدة 90 يومًا.","p":"صحيح. 10 أو 11 نقطة تعني إيقاف الرخصة 90 يومًا."},"ref":{"doc":"DC","page":19}},{"id":"dc-020","scope":"DC","cat":"licensing","sign":null,"c":0,"en":{"q":"In the District of Columbia, what happens when a driver reaches 12 or more points?","o":["The license is revoked for at least 6 months","The license is suspended for 30 days","The driver pays a fine and keeps driving","The points are removed after a class"],"h1":"This is more serious than a suspension.","h2":"In the District of Columbia, a driver who reaches 12 or more points has the license revoked and cannot get it back for at least six months.","p":"Right. 12 points or more means revocation for at least six months."},"es":{"q":"En el Distrito de Columbia, ¿qué pasa cuando un conductor llega a 12 puntos o más?","o":["Le revocan la licencia por lo menos 6 meses","Le suspenden la licencia por 30 días","Paga una multa y sigue manejando","Le quitan los puntos después de una clase"],"h1":"Es más grave que una suspensión.","h2":"En el Distrito de Columbia, a un conductor que llega a 12 puntos o más le revocan la licencia y no la puede recuperar por lo menos en seis meses.","p":"Correcto. 12 puntos o más significan revocación por lo menos por seis meses."},"zh":{"q":"在 District of Columbia，司机累计到 12 分或更多时，会怎么样？","o":["驾照被吊销至少 6 个月","驾照被暂停 30 天","司机交罚款，可以继续开车","上一门课以后，分数就被取消"],"h1":"这比暂停驾照更严重。","h2":"在 District of Columbia，累计到 12 分或更多的司机，驾照会被吊销，至少六个月不能拿回来。","p":"对。12 分或更多就是吊销驾照至少六个月。"},"vi":{"q":"Ở District of Columbia, điều gì xảy ra khi người lái xe bị 12 điểm trở lên?","o":["Bằng lái bị thu hồi ít nhất 6 tháng","Bằng lái bị tạm đình chỉ 30 ngày","Người lái xe nộp phạt và tiếp tục lái","Điểm bị xóa sau khi học một lớp"],"h1":"Điều này nghiêm trọng hơn tạm đình chỉ.","h2":"Ở District of Columbia, người lái xe bị 12 điểm trở lên sẽ bị thu hồi bằng lái và không thể lấy lại trong ít nhất sáu tháng.","p":"Đúng. 12 điểm trở lên nghĩa là bị thu hồi bằng lái ít nhất sáu tháng."},"tl":{"q":"Sa District of Columbia, ano ang mangyayari kapag umabot sa 12 puntos o higit pa ang driver?","o":["Babawiin ang lisensya nang hindi bababa sa 6 na buwan","Masususpinde ang lisensya nang 30 araw","Magbabayad ng multa ang driver at patuloy na magmamaneho","Matatanggal ang mga puntos pagkatapos ng isang klase"],"h1":"Mas mabigat ito kaysa sa suspensyon.","h2":"Sa District of Columbia, ang driver na umabot sa 12 puntos o higit pa ay babawian ng lisensya at hindi ito makukuha ulit nang hindi bababa sa anim na buwan.","p":"Tama. Ang 12 puntos o higit pa ay pagbawi ng lisensya nang hindi bababa sa anim na buwan."},"ar":{"q":"في District of Columbia، ماذا يحدث عندما يصل السائق إلى 12 نقطة أو أكثر؟","o":["تُلغى الرخصة لمدة 6 أشهر على الأقل","تُوقَف الرخصة لمدة 30 يومًا","يدفع السائق غرامة ويستمر في القيادة","تُحذف النقاط بعد دورة"],"h1":"هذا أشد من إيقاف الرخصة.","h2":"في District of Columbia السائق الذي يصل إلى 12 نقطة أو أكثر تُلغى رخصته ولا يستطيع استعادتها قبل ستة أشهر على الأقل.","p":"صحيح. 12 نقطة أو أكثر تعني إلغاء الرخصة لمدة ستة أشهر على الأقل."},"ref":{"doc":"DC","page":19}},{"id":"dc-021","scope":"DC","cat":"licensing","sign":null,"c":3,"en":{"q":"In the District of Columbia, how long do points stay active on your driving record?","o":["6 months","1 year","5 years","2 years"],"h1":"It is more than one year, but less than three.","h2":"In the District of Columbia, points stay active on your driving record for two years.","p":"Right. Points stay active for two years."},"es":{"q":"En el Distrito de Columbia, ¿por cuánto tiempo siguen activos los puntos en su historial de manejo?","o":["6 meses","1 año","5 años","2 años"],"h1":"Es más de un año, pero menos de tres.","h2":"En el Distrito de Columbia, los puntos siguen activos en su historial de manejo por dos años.","p":"Correcto. Los puntos siguen activos por dos años."},"zh":{"q":"在 District of Columbia，扣分在你的驾驶记录上有效多久？","o":["6 个月","1 年","5 年","2 年"],"h1":"它比一年长，但比三年短。","h2":"在 District of Columbia，扣分在你的驾驶记录上有效两年。","p":"对。扣分有效两年。"},"vi":{"q":"Ở District of Columbia, điểm phạt còn hiệu lực trong hồ sơ lái xe của bạn bao lâu?","o":["6 tháng","1 năm","5 năm","2 năm"],"h1":"Nó nhiều hơn một năm, nhưng ít hơn ba năm.","h2":"Ở District of Columbia, điểm phạt còn hiệu lực trong hồ sơ lái xe của bạn hai năm.","p":"Đúng. Điểm phạt còn hiệu lực hai năm."},"tl":{"q":"Sa District of Columbia, gaano katagal aktibo ang mga puntos sa iyong driving record?","o":["6 na buwan","1 taon","5 taon","2 taon"],"h1":"Higit ito sa isang taon, pero kulang sa tatlo.","h2":"Sa District of Columbia, aktibo ang mga puntos sa iyong driving record nang dalawang taon.","p":"Tama. Aktibo ang mga puntos nang dalawang taon."},"ar":{"q":"في District of Columbia، كم مدة بقاء النقاط سارية في سجل القيادة الخاص بك؟","o":["6 أشهر","سنة واحدة","5 سنوات","سنتان"],"h1":"هي أكثر من سنة واحدة، لكن أقل من ثلاث سنوات.","h2":"في District of Columbia تبقى النقاط سارية في سجل القيادة الخاص بك لمدة سنتين.","p":"صحيح. تبقى النقاط سارية لمدة سنتين."},"ref":{"doc":"DC","page":19}},{"id":"dc-022","scope":"DC","cat":"licensing","sign":null,"c":1,"en":{"q":"In the District of Columbia, a learner permit holder gets 8 points or breaks a GRAD rule. What happens?","o":["Nothing, if no one was hurt","The permit is suspended for 90 days","The permit is extended by one week","The supervisor gets the points instead"],"h1":"The learner loses the permit for about three months.","h2":"In the District of Columbia, a learner permit holder who gets 8 or more points or breaks a GRAD rule has the permit suspended for 90 days and must pay a fee to get it back.","p":"Right. That means a 90-day suspension of the permit."},"es":{"q":"En el Distrito de Columbia, una persona con permiso de aprendiz recibe 8 puntos o no cumple una regla del programa GRAD. ¿Qué pasa?","o":["Nada, si nadie salió herido","Le suspenden el permiso por 90 días","Le alargan el permiso una semana","El supervisor recibe los puntos"],"h1":"El aprendiz pierde el permiso por unos tres meses.","h2":"En el Distrito de Columbia, a una persona con permiso de aprendiz que recibe 8 puntos o más, o que no cumple una regla del programa GRAD, le suspenden el permiso por 90 días y debe pagar una cuota para recuperarlo.","p":"Correcto. Eso significa una suspensión del permiso por 90 días."},"zh":{"q":"在 District of Columbia，持学习驾照的人被扣了 8 分，或者违反了一条 GRAD 规定。会怎么样？","o":["如果没有人受伤，就没事","学习驾照被暂停 90 天","学习驾照延长一个星期","改由监督的人被扣分"],"h1":"学习驾驶的人会失去学习驾照大约三个月。","h2":"在 District of Columbia，持学习驾照的人如果被扣 8 分或更多，或者违反 GRAD 规定，学习驾照会被暂停 90 天，而且要交费才能拿回来。","p":"对。这表示学习驾照被暂停 90 天。"},"vi":{"q":"Ở District of Columbia, người có giấy phép tập lái bị 8 điểm hoặc vi phạm một quy định GRAD. Điều gì xảy ra?","o":["Không có gì, nếu không ai bị thương","Giấy phép tập lái bị tạm đình chỉ 90 ngày","Giấy phép tập lái được gia hạn thêm một tuần","Người giám sát bị trừ điểm thay"],"h1":"Người tập lái mất giấy phép khoảng ba tháng.","h2":"Ở District of Columbia, người có giấy phép tập lái bị 8 điểm trở lên hoặc vi phạm quy định GRAD sẽ bị tạm đình chỉ giấy phép 90 ngày và phải trả phí để lấy lại.","p":"Đúng. Điều đó nghĩa là giấy phép tập lái bị tạm đình chỉ 90 ngày."},"tl":{"q":"Sa District of Columbia, nakakuha ng 8 puntos o lumabag sa isang patakaran ng GRAD ang may hawak ng learner permit. Ano ang mangyayari?","o":["Wala, kung walang nasaktan","Masususpinde ang permit nang 90 araw","Hahabaan ang permit nang isang linggo","Ang gumagabay ang makakakuha ng mga puntos"],"h1":"Mawawala sa nag-aaral ang permit nang mga tatlong buwan.","h2":"Sa District of Columbia, ang may hawak ng learner permit na nakakuha ng 8 puntos o higit pa o lumabag sa patakaran ng GRAD ay masususpinde ang permit nang 90 araw at dapat magbayad ng fee para makuha ito ulit.","p":"Tama. Ibig sabihin nito, 90 araw na suspensyon ng permit."},"ar":{"q":"في District of Columbia، حامل تصريح التعلّم حصل على 8 نقاط أو خالف قاعدة من قواعد GRAD. ماذا يحدث؟","o":["لا شيء، إذا لم يُصَب أحد","يُوقَف التصريح لمدة 90 يومًا","يُمدَّد التصريح أسبوعًا واحدًا","يحصل المشرف على النقاط بدلًا منه"],"h1":"يفقد المتعلم التصريح لمدة ثلاثة أشهر تقريبًا.","h2":"في District of Columbia حامل تصريح التعلّم الذي يحصل على 8 نقاط أو أكثر أو يخالف قاعدة من قواعد GRAD يُوقَف تصريحه لمدة 90 يومًا ويجب أن يدفع رسومًا لاستعادته.","p":"صحيح. هذا يعني إيقاف التصريح لمدة 90 يومًا."},"ref":{"doc":"DC","page":16}},{"id":"dc-023","scope":"DC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In the District of Columbia, what is the penalty when someone in the car is not wearing a seat belt?","o":["A warning only","A $10 fine and no points","A $50 fine and 2 points","A $500 fine and 6 points"],"h1":"There is a fine and also points on the driver's record.","h2":"In the District of Columbia, the penalty for not wearing a seat belt is a $50 fine and 2 points, and the driver is responsible for every passenger.","p":"Right. A $50 fine and 2 points."},"es":{"q":"En el Distrito de Columbia, ¿cuál es la sanción cuando alguien en el carro no usa el cinturón de seguridad?","o":["Solo una advertencia","Una multa de $10 y ningún punto","Una multa de $50 y 2 puntos","Una multa de $500 y 6 puntos"],"h1":"Hay una multa y también puntos en el historial del conductor.","h2":"En el Distrito de Columbia, la sanción por no usar el cinturón de seguridad es una multa de $50 y 2 puntos, y el conductor es responsable de todos los pasajeros.","p":"Correcto. Una multa de $50 y 2 puntos."},"zh":{"q":"在 District of Columbia，车里有人没有系安全带，会受到什么处罚？","o":["只有警告","罚款 $10，不扣分","罚款 $50，扣 2 分","罚款 $500，扣 6 分"],"h1":"会有罚款，司机的记录上也会被扣分。","h2":"在 District of Columbia，不系安全带的处罚是罚款 $50 并扣 2 分，而且司机要为每一位乘客负责。","p":"对。罚款 $50，扣 2 分。"},"vi":{"q":"Ở District of Columbia, hình phạt là gì khi có người trong xe không thắt dây an toàn?","o":["Chỉ cảnh cáo","Phạt $10 và không bị điểm","Phạt $50 và 2 điểm","Phạt $500 và 6 điểm"],"h1":"Có tiền phạt và cũng có điểm trong hồ sơ của người lái xe.","h2":"Ở District of Columbia, hình phạt cho việc không thắt dây an toàn là phạt $50 và 2 điểm, và người lái xe chịu trách nhiệm cho mọi hành khách.","p":"Đúng. Phạt $50 và 2 điểm."},"tl":{"q":"Sa District of Columbia, ano ang parusa kapag may tao sa kotse na hindi naka-seat belt?","o":["Babala lang","Multang $10 at walang puntos","Multang $50 at 2 puntos","Multang $500 at 6 na puntos"],"h1":"May multa at may puntos din sa record ng driver.","h2":"Sa District of Columbia, ang parusa sa hindi pagsusuot ng seat belt ay multang $50 at 2 puntos, at ang driver ang responsable sa bawat pasahero.","p":"Tama. Multang $50 at 2 puntos."},"ar":{"q":"في District of Columbia، ما العقوبة عندما لا يضع شخص في السيارة حزام الأمان؟","o":["تحذير فقط","غرامة $10 بدون نقاط","غرامة $50 ونقطتان (2)","غرامة $500 و6 نقاط"],"h1":"هناك غرامة وأيضًا نقاط في سجل السائق.","h2":"في District of Columbia عقوبة عدم وضع حزام الأمان هي غرامة $50 ونقطتان (2)، والسائق مسؤول عن كل راكب.","p":"صحيح. غرامة $50 ونقطتان (2)."},"ref":{"doc":"DC","page":48}},{"id":"dc-024","scope":"DC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In the District of Columbia, what is true about wearing headphones while you drive?","o":["Headphones for music are not allowed; a phone earpiece or hearing aid is allowed","Headphones are allowed if the volume is low","Headphones are allowed only on the highway","Headphones are allowed in both ears at any time"],"h1":"Think about what could stop you from hearing a siren.","h2":"In the District of Columbia, you may not wear headphones or earplugs connected to a radio or other audio player while driving, but a cell phone earpiece or a hearing aid is allowed.","p":"Right. No music headphones; a phone earpiece or hearing aid is fine."},"es":{"q":"En el Distrito de Columbia, ¿qué es cierto sobre usar audífonos mientras maneja?","o":["Los audífonos para música no se permiten; el audífono del celular o un aparato auditivo sí","Se permiten audífonos si el volumen está bajo","Se permiten audífonos solo en la autopista","Se permiten audífonos en los dos oídos en todo momento"],"h1":"Piense en lo que le podría impedir oír una sirena.","h2":"En el Distrito de Columbia, usted no puede usar audífonos ni tapones conectados a un radio u otro aparato de audio mientras maneja, pero sí puede usar el audífono del celular o un aparato auditivo.","p":"Correcto. Nada de audífonos para música; el del celular o un aparato auditivo sí."},"zh":{"q":"在 District of Columbia，关于开车时戴耳机，哪一项是对的？","o":["不可以戴听音乐的耳机；可以用手机耳塞或助听器","音量小的话可以戴耳机","只有在公路上可以戴耳机","任何时候都可以两只耳朵戴耳机"],"h1":"想一想什么会让你听不到警笛声。","h2":"在 District of Columbia，开车时不可以戴连接收音机或其他播放器的耳机或耳塞，但可以用手机耳塞或助听器。","p":"对。不能戴听音乐的耳机；手机耳塞或助听器可以。"},"vi":{"q":"Ở District of Columbia, điều nào đúng về việc đeo tai nghe khi lái xe?","o":["Không được đeo tai nghe nghe nhạc; được dùng tai nghe điện thoại hoặc máy trợ thính","Được đeo tai nghe nếu âm lượng nhỏ","Chỉ được đeo tai nghe trên đường cao tốc","Được đeo tai nghe cả hai tai bất cứ lúc nào"],"h1":"Hãy nghĩ đến điều gì có thể làm bạn không nghe thấy còi hụ.","h2":"Ở District of Columbia, bạn không được đeo tai nghe hoặc nút tai nối với radio hay máy phát âm thanh khác khi lái xe, nhưng được dùng tai nghe điện thoại di động hoặc máy trợ thính.","p":"Đúng. Không đeo tai nghe nghe nhạc; tai nghe điện thoại hoặc máy trợ thính thì được."},"tl":{"q":"Sa District of Columbia, ano ang totoo tungkol sa pagsusuot ng headphones habang nagmamaneho?","o":["Bawal ang headphones para sa musika; puwede ang earpiece ng phone o hearing aid","Puwede ang headphones kung mahina ang volume","Puwede ang headphones sa highway lang","Puwede ang headphones sa dalawang tainga kahit kailan"],"h1":"Isipin kung ano ang puwedeng pumigil sa iyo na marinig ang sirena.","h2":"Sa District of Columbia, hindi ka puwedeng magsuot ng headphones o earplugs na nakakonekta sa radyo o ibang audio player habang nagmamaneho, pero puwede ang earpiece ng cell phone o hearing aid.","p":"Tama. Bawal ang headphones para sa musika; puwede ang earpiece ng phone o hearing aid."},"ar":{"q":"في District of Columbia، ما الصحيح عن وضع سماعات الرأس أثناء القيادة؟","o":["سماعات الموسيقى غير مسموحة؛ سماعة الهاتف أو جهاز السمع مسموح","السماعات مسموحة إذا كان الصوت منخفضًا","السماعات مسموحة على الطريق السريع فقط","السماعات مسموحة في الأذنين في أي وقت"],"h1":"فكّر في ما قد يمنعك من سماع صفارة الإنذار.","h2":"في District of Columbia لا يجوز لك أثناء القيادة أن تضع سماعات أو سدادات أذن متصلة بالراديو أو بجهاز صوت آخر، لكن سماعة الهاتف المحمول أو جهاز السمع مسموح.","p":"صحيح. لا سماعات للموسيقى؛ سماعة الهاتف أو جهاز السمع لا بأس بهما."},"ref":{"doc":"DC","page":47}},{"id":"dc-025","scope":"DC","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In the District of Columbia, may you turn left on a red light?","o":["Yes, after a full stop","Yes, from a one-way street onto another one-way street","Yes, if no cars are coming","No, a left turn on red is against the law"],"h1":"DC is stricter than many states about this.","h2":"In the District of Columbia, it is against the law to make a left turn on a red light.","p":"Right. In DC you never turn left on red."},"es":{"q":"En el Distrito de Columbia, ¿puede usted girar a la izquierda con la luz roja?","o":["Sí, después de parar por completo","Sí, de una calle de un solo sentido a otra de un solo sentido","Sí, si no vienen carros","No, girar a la izquierda con luz roja es ilegal"],"h1":"DC es más estricto que muchos estados en esto.","h2":"En el Distrito de Columbia, es ilegal girar a la izquierda con la luz roja.","p":"Correcto. En DC nunca se gira a la izquierda con luz roja."},"zh":{"q":"在 District of Columbia，红灯时可以左转吗？","o":["可以，在完全停车以后","可以，从单行道转到另一条单行道","可以，如果没有车来","不可以，红灯左转是违法的"],"h1":"在这一点上，DC 比很多州更严。","h2":"在 District of Columbia，红灯时左转是违法的。","p":"对。在 DC，红灯时永远不能左转。"},"vi":{"q":"Ở District of Columbia, bạn có được rẽ trái khi đèn đỏ không?","o":["Có, sau khi dừng hẳn","Có, từ đường một chiều sang một đường một chiều khác","Có, nếu không có xe đang tới","Không, rẽ trái khi đèn đỏ là phạm luật"],"h1":"Về điều này, DC nghiêm hơn nhiều tiểu bang.","h2":"Ở District of Columbia, rẽ trái khi đèn đỏ là phạm luật.","p":"Đúng. Ở DC, bạn không bao giờ rẽ trái khi đèn đỏ."},"tl":{"q":"Sa District of Columbia, puwede ka bang kumaliwa kapag pula ang ilaw?","o":["Oo, pagkatapos ng buong paghinto","Oo, mula sa one-way na kalye papunta sa isa pang one-way na kalye","Oo, kung walang paparating na sasakyan","Hindi, labag sa batas ang pagkaliwa kapag pula ang ilaw"],"h1":"Mas mahigpit ang DC dito kaysa sa maraming estado.","h2":"Sa District of Columbia, labag sa batas ang kumaliwa kapag pula ang ilaw.","p":"Tama. Sa DC, hindi ka kailanman kumakaliwa kapag pula ang ilaw."},"ar":{"q":"في District of Columbia، هل يجوز لك الانعطاف يسارًا عند الإشارة الحمراء؟","o":["نعم، بعد التوقف التام","نعم، من شارع باتجاه واحد إلى شارع آخر باتجاه واحد","نعم، إذا لم تكن هناك سيارات قادمة","لا، الانعطاف يسارًا عند الإشارة الحمراء مخالف للقانون"],"h1":"DC أشد من ولايات كثيرة في هذا.","h2":"في District of Columbia الانعطاف يسارًا عند الإشارة الحمراء مخالف للقانون.","p":"صحيح. في DC لا تنعطف يسارًا عند الإشارة الحمراء أبدًا."},"ref":{"doc":"DC","page":42}},{"id":"dc-026","scope":"DC","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In the District of Columbia, where is a U-turn against the law?","o":["On any one-way street","At an intersection with traffic lights","On any street with two lanes","Anywhere after dark"],"h1":"Think of intersections controlled by signals.","h2":"In the District of Columbia, U-turns are not allowed at intersections controlled by traffic lights, or on a crosswalk next to one.","p":"Right. No U-turns at intersections with traffic lights."},"es":{"q":"En el Distrito de Columbia, ¿dónde es ilegal dar una vuelta en U?","o":["En cualquier calle de un solo sentido","En una intersección con semáforo","En cualquier calle de dos carriles","En cualquier lugar de noche"],"h1":"Piense en las intersecciones controladas por señales.","h2":"En el Distrito de Columbia, no se permiten las vueltas en U en intersecciones controladas por semáforos, ni en el cruce peatonal junto a ellas.","p":"Correcto. Nada de vueltas en U en intersecciones con semáforo."},"zh":{"q":"在 District of Columbia，在哪里掉头是违法的？","o":["在任何单行道上","在有红绿灯的路口","在任何有两条车道的街道上","天黑以后在任何地方"],"h1":"想一想由信号灯控制的路口。","h2":"在 District of Columbia，不可以在由红绿灯控制的路口掉头，也不可以在这种路口旁边的人行横道上掉头。","p":"对。有红绿灯的路口不能掉头。"},"vi":{"q":"Ở District of Columbia, quay đầu xe (U-turn) ở đâu là phạm luật?","o":["Trên bất kỳ đường một chiều nào","Tại giao lộ có đèn giao thông","Trên bất kỳ đường nào có hai làn","Ở bất cứ đâu sau khi trời tối"],"h1":"Hãy nghĩ đến các giao lộ được điều khiển bằng đèn tín hiệu.","h2":"Ở District of Columbia, không được quay đầu xe tại giao lộ có đèn giao thông điều khiển, hoặc trên vạch qua đường dành cho người đi bộ bên cạnh giao lộ đó.","p":"Đúng. Không quay đầu xe tại giao lộ có đèn giao thông."},"tl":{"q":"Sa District of Columbia, saan labag sa batas ang U-turn?","o":["Sa anumang one-way na kalye","Sa interseksyon na may traffic light","Sa anumang kalye na may dalawang lane","Kahit saan pagkagabi"],"h1":"Isipin ang mga interseksyon na kontrolado ng mga signal.","h2":"Sa District of Columbia, bawal ang U-turn sa mga interseksyon na kontrolado ng traffic light, o sa tawiran ng tao na katabi nito.","p":"Tama. Bawal ang U-turn sa mga interseksyon na may traffic light."},"ar":{"q":"في District of Columbia، أين يكون الدوران للخلف (U-turn) مخالفًا للقانون؟","o":["في أي شارع باتجاه واحد","عند تقاطع فيه إشارات مرور","في أي شارع فيه مساران","في أي مكان بعد حلول الظلام"],"h1":"فكّر في التقاطعات التي تنظمها الإشارات.","h2":"في District of Columbia لا يجوز الدوران للخلف عند التقاطعات التي تنظمها إشارات المرور، ولا على ممر المشاة الذي بجانب تقاطع كهذا.","p":"صحيح. لا دوران للخلف عند التقاطعات التي فيها إشارات مرور."},"ref":{"doc":"DC","page":47}},{"id":"dc-027","scope":"DC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In the District of Columbia, how close to a fire hydrant may you stand or park?","o":["Up to 5 feet away","No closer than 10 feet","No closer than 25 feet","No closer than 50 feet"],"h1":"The District uses a shorter distance than many states.","h2":"In the District of Columbia, you may not stand or park within 10 feet of a fire hydrant.","p":"Right. Stay at least 10 feet from a hydrant."},"es":{"q":"En el Distrito de Columbia, ¿a qué distancia de un hidrante puede detenerse o estacionarse?","o":["Hasta 5 pies de distancia","No más cerca de 10 pies","No más cerca de 25 pies","No más cerca de 50 pies"],"h1":"El Distrito usa una distancia más corta que muchos estados.","h2":"En el Distrito de Columbia, usted no puede detenerse ni estacionarse a menos de 10 pies de un hidrante.","p":"Correcto. Quédese por lo menos a 10 pies de un hidrante."},"zh":{"q":"在 District of Columbia，你可以在离消防栓多近的地方停车或临时停靠？","o":["最近 5 英尺","不能少于 10 英尺","不能少于 25 英尺","不能少于 50 英尺"],"h1":"DC 用的距离比很多州短。","h2":"在 District of Columbia，你不能在离消防栓 10 英尺以内的地方停车或临时停靠。","p":"对。离消防栓至少 10 英尺。"},"vi":{"q":"Ở District of Columbia (DC), bạn được dừng hoặc đỗ xe gần trụ cứu hỏa đến mức nào?","o":["Cách tối đa 5 feet","Không gần hơn 10 feet","Không gần hơn 25 feet","Không gần hơn 50 feet"],"h1":"DC dùng khoảng cách ngắn hơn nhiều tiểu bang khác.","h2":"Ở District of Columbia, bạn không được dừng hoặc đỗ xe trong vòng 10 feet tính từ trụ cứu hỏa.","p":"Đúng. Hãy cách trụ cứu hỏa ít nhất 10 feet."},"tl":{"q":"Sa District of Columbia (DC), gaano kalapit sa fire hydrant ka puwedeng huminto o pumarada?","o":["Hanggang 5 talampakan ang layo","Hindi lalapit sa 10 talampakan","Hindi lalapit sa 25 talampakan","Hindi lalapit sa 50 talampakan"],"h1":"Mas maikli ang layong ginagamit ng DC kaysa sa maraming estado.","h2":"Sa District of Columbia, hindi ka puwedeng huminto o pumarada sa loob ng 10 talampakan mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 10 talampakan sa hydrant."},"ar":{"q":"في District of Columbia (DC)، كم يمكنك أن تقترب من صنبور إطفاء الحريق عند التوقف أو الركن؟","o":["حتى 5 أقدام","ليس أقرب من 10 أقدام","ليس أقرب من 25 قدمًا","ليس أقرب من 50 قدمًا"],"h1":"تستخدم DC مسافة أقصر من ولايات كثيرة.","h2":"في District of Columbia لا يجوز لك التوقف أو الركن على بُعد أقل من 10 أقدام من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بُعد 10 أقدام على الأقل من صنبور الإطفاء."},"ref":{"doc":"DC","page":44}},{"id":"dc-028","scope":"DC","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In the District of Columbia, what is the rule when you pass a bicyclist?","o":["Honk first so the rider knows you are there","Leave at least 1 foot of space","Leave at least 3 feet and do not use your horn","Pass only on the right"],"h1":"A loud noise can startle a rider.","h2":"In the District of Columbia, you must leave at least three feet of space when passing a bicyclist, and you should not use your horn.","p":"Right. Leave 3 feet and do not honk."},"es":{"q":"En el Distrito de Columbia, ¿cuál es la regla al rebasar a un ciclista?","o":["Tocar la bocina primero para avisarle","Dejar por lo menos 1 pie de espacio","Dejar por lo menos 3 pies y no tocar la bocina","Rebasar solo por la derecha"],"h1":"Un ruido fuerte puede asustar al ciclista.","h2":"En el Distrito de Columbia, debe dejar por lo menos tres pies de espacio al rebasar a un ciclista, y no debe tocar la bocina.","p":"Correcto. Deje 3 pies y no toque la bocina."},"zh":{"q":"在 District of Columbia，超过骑自行车的人时，规定是什么？","o":["先按喇叭，让骑车人知道你在那里","至少留出 1 英尺的空间","至少留出 3 英尺，而且不要按喇叭","只能从右边超车"],"h1":"很大的声音会吓到骑车人。","h2":"在 District of Columbia，超过骑自行车的人时，你必须至少留出 3 英尺的空间，而且不应该按喇叭。","p":"对。留出 3 英尺，不要按喇叭。"},"vi":{"q":"Ở District of Columbia (DC), quy định là gì khi bạn vượt người đi xe đạp?","o":["Bấm còi trước để người đạp xe biết bạn ở đó","Chừa ít nhất 1 foot khoảng trống","Chừa ít nhất 3 feet và không bấm còi","Chỉ vượt bên phải"],"h1":"Tiếng động lớn có thể làm người đạp xe giật mình.","h2":"Ở District of Columbia, khi vượt người đi xe đạp, bạn phải chừa ít nhất 3 feet khoảng trống và không nên bấm còi.","p":"Đúng. Chừa 3 feet và không bấm còi."},"tl":{"q":"Sa District of Columbia (DC), ano ang patakaran kapag nilalampasan mo ang nagbibisikleta?","o":["Bumusina muna para malaman ng siklista na nandiyan ka","Mag-iwan ng hindi bababa sa 1 talampakang espasyo","Mag-iwan ng hindi bababa sa 3 talampakan at huwag bumusina","Lumampas lang sa kanan"],"h1":"Puwedeng magulat ang siklista sa malakas na ingay.","h2":"Sa District of Columbia, kapag nilalampasan mo ang nagbibisikleta, dapat kang mag-iwan ng hindi bababa sa 3 talampakang espasyo, at hindi ka dapat bumusina.","p":"Tama. Mag-iwan ng 3 talampakan at huwag bumusina."},"ar":{"q":"في District of Columbia (DC)، ما القاعدة عندما تتجاوز راكب دراجة هوائية؟","o":["اضغط على البوق أولًا ليعرف الراكب أنك هناك","اترك مسافة قدم واحدة (1) على الأقل","اترك 3 أقدام على الأقل ولا تستخدم البوق","تجاوز من اليمين فقط"],"h1":"الصوت العالي قد يُفزع راكب الدراجة.","h2":"في District of Columbia يجب أن تترك مسافة 3 أقدام على الأقل عندما تتجاوز راكب دراجة هوائية، ولا ينبغي أن تستخدم البوق.","p":"صحيح. اترك 3 أقدام ولا تستخدم البوق."},"ref":{"doc":"DC","page":41}},{"id":"dc-029","scope":"DC","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In the District of Columbia, how close to the curb must you be when you parallel park?","o":["Within 12 inches","Within 24 inches","Within 3 feet","Touching the curb"],"h1":"The distance is about one foot.","h2":"In the District of Columbia, when you parallel park you must be parallel to the curb and within 12 inches of it.","p":"Right. Park within 12 inches of the curb."},"es":{"q":"En el Distrito de Columbia, ¿qué tan cerca de la acera debe quedar al estacionarse en paralelo?","o":["A 12 pulgadas o menos","A 24 pulgadas o menos","A 3 pies o menos","Tocando la acera"],"h1":"La distancia es de más o menos un pie.","h2":"En el Distrito de Columbia, al estacionarse en paralelo debe quedar paralelo a la acera y a no más de 12 pulgadas de ella.","p":"Correcto. Estaciónese a 12 pulgadas o menos de la acera."},"zh":{"q":"在 District of Columbia，平行停车时，你必须离路缘多近？","o":["12 英寸以内","24 英寸以内","3 英尺以内","贴着路缘"],"h1":"这个距离大约是 1 英尺。","h2":"在 District of Columbia，平行停车时，你必须和路缘平行，并且离路缘 12 英寸以内。","p":"对。停车时离路缘 12 英寸以内。"},"vi":{"q":"Ở District of Columbia (DC), khi đỗ xe song song, bạn phải cách lề đường bao xa?","o":["Trong vòng 12 inch","Trong vòng 24 inch","Trong vòng 3 feet","Chạm vào lề đường"],"h1":"Khoảng cách này khoảng 1 foot.","h2":"Ở District of Columbia, khi đỗ xe song song, bạn phải đỗ song song với lề đường và cách lề đường trong vòng 12 inch.","p":"Đúng. Đỗ xe cách lề đường trong vòng 12 inch."},"tl":{"q":"Sa District of Columbia (DC), gaano kalapit sa gilid ng bangketa (curb) ka dapat kapag nag-parallel park ka?","o":["Sa loob ng 12 pulgada","Sa loob ng 24 pulgada","Sa loob ng 3 talampakan","Nakadikit sa curb"],"h1":"Mga isang talampakan ang layo.","h2":"Sa District of Columbia, kapag nag-parallel park ka, dapat ay kahanay ka ng curb at nasa loob ng 12 pulgada mula rito.","p":"Tama. Pumarada sa loob ng 12 pulgada mula sa curb."},"ar":{"q":"في District of Columbia (DC)، كم يجب أن تكون قريبًا من الرصيف عند الركن الموازي؟","o":["في حدود 12 بوصة","في حدود 24 بوصة","في حدود 3 أقدام","ملامسًا للرصيف"],"h1":"المسافة نحو قدم واحدة تقريبًا.","h2":"في District of Columbia يجب عند الركن الموازي أن تكون موازيًا للرصيف وعلى بُعد 12 بوصة منه أو أقل.","p":"صحيح. اركن على بُعد 12 بوصة أو أقل من الرصيف."},"ref":{"doc":"DC","page":43}},{"id":"dc-030","scope":"DC","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In the District of Columbia, where is it legal to pass another vehicle on the right?","o":["On any two-lane road","On the shoulder of any road","Only at night","On a one-way road with room for more than one line of traffic"],"h1":"Think of roads where all traffic goes the same way.","h2":"In the District of Columbia, you may pass on the left or right on a one-way road with room for more than one line of traffic, and on highways with four or more lanes.","p":"Right. One-way roads with more than one lane allow passing on either side."},"es":{"q":"En el Distrito de Columbia, ¿dónde es legal rebasar a otro vehículo por la derecha?","o":["En cualquier vía de dos carriles","Por el acotamiento de cualquier vía","Solo de noche","En una vía de un solo sentido con espacio para más de una fila de tráfico"],"h1":"Piense en las vías donde todo el tráfico va en la misma dirección.","h2":"En el Distrito de Columbia, puede rebasar por la izquierda o por la derecha en una vía de un solo sentido con espacio para más de una fila de tráfico, y en carreteras de cuatro carriles o más.","p":"Correcto. En vías de un solo sentido con más de un carril se puede rebasar por cualquier lado."},"zh":{"q":"在 District of Columbia，在哪里从右边超车是合法的？","o":["在任何双车道道路上","在任何道路的路肩上","只在晚上","在有足够空间容纳多于一列车流的单行道上"],"h1":"想一想所有车都往同一个方向开的道路。","h2":"在 District of Columbia，在有足够空间容纳多于一列车流的单行道上，以及在有 4 条或更多车道的公路上，你可以从左边或右边超车。","p":"对。有多于一条车道的单行道，可以从任一边超车。"},"vi":{"q":"Ở District of Columbia (DC), ở đâu thì được phép vượt xe khác bên phải?","o":["Trên bất kỳ đường hai làn nào","Trên lề của bất kỳ con đường nào","Chỉ vào ban đêm","Trên đường một chiều có đủ chỗ cho hơn một hàng xe"],"h1":"Hãy nghĩ đến những con đường mà mọi xe đều đi cùng một hướng.","h2":"Ở District of Columbia, bạn được vượt bên trái hoặc bên phải trên đường một chiều có đủ chỗ cho hơn một hàng xe, và trên xa lộ có 4 làn trở lên.","p":"Đúng. Đường một chiều có hơn một làn cho phép vượt ở cả hai bên."},"tl":{"q":"Sa District of Columbia (DC), saan legal na lampasan ang ibang sasakyan sa kanan?","o":["Sa kahit anong kalsadang may dalawang lane","Sa shoulder ng kahit anong kalsada","Sa gabi lang","Sa one-way na kalsadang may espasyo para sa higit sa isang hanay ng sasakyan"],"h1":"Isipin ang mga kalsada kung saan iisang direksyon ang takbo ng lahat ng sasakyan.","h2":"Sa District of Columbia, puwede kang lumampas sa kaliwa o sa kanan sa one-way na kalsadang may espasyo para sa higit sa isang hanay ng sasakyan, at sa mga highway na may 4 o higit pang lane.","p":"Tama. Sa one-way na kalsadang may higit sa isang lane, puwedeng lumampas sa alinmang gilid."},"ar":{"q":"في District of Columbia (DC)، أين يجوز قانونًا أن تتجاوز مركبة أخرى من اليمين؟","o":["على أي طريق بمسارين","على كتف أي طريق","في الليل فقط","على طريق باتجاه واحد فيه مكان لأكثر من صف واحد من السيارات"],"h1":"فكّر في الطرق التي تسير فيها كل السيارات في الاتجاه نفسه.","h2":"في District of Columbia يجوز لك التجاوز من اليسار أو من اليمين على طريق باتجاه واحد فيه مكان لأكثر من صف واحد من السيارات، وعلى الطرق السريعة التي فيها 4 مسارات أو أكثر.","p":"صحيح. على الطرق ذات الاتجاه الواحد وأكثر من مسار يجوز التجاوز من أي جانب."},"ref":{"doc":"DC","page":41}},{"id":"dc-031","scope":"DC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In the District of Columbia, when must you turn on your headlights?","o":["Only after midnight","Whenever your windshield wipers are on","Only on highways","Only when it snows"],"h1":"Think about rain.","h2":"In the District of Columbia, you must turn on your headlights whenever your windshield wipers are on, and also in tunnels and from half an hour after sunset to half an hour before sunrise.","p":"Right. Wipers on means headlights on."},"es":{"q":"En el Distrito de Columbia, ¿cuándo debe encender los faros?","o":["Solo después de medianoche","Siempre que tenga los limpiaparabrisas encendidos","Solo en las carreteras","Solo cuando nieva"],"h1":"Piense en la lluvia.","h2":"En el Distrito de Columbia, debe encender los faros siempre que tenga los limpiaparabrisas encendidos, y también en los túneles y desde media hora después de la puesta del sol hasta media hora antes del amanecer.","p":"Correcto. Limpiaparabrisas encendidos significa faros encendidos."},"zh":{"q":"在 District of Columbia，你什么时候必须打开车头灯？","o":["只在半夜以后","每次打开雨刷的时候","只在公路上","只在下雪的时候"],"h1":"想一想下雨的时候。","h2":"在 District of Columbia，每次打开雨刷时你都必须打开车头灯；在隧道里，以及从日落后半小时到日出前半小时，也必须打开车头灯。","p":"对。开雨刷就要开车头灯。"},"vi":{"q":"Ở District of Columbia (DC), khi nào bạn phải bật đèn pha?","o":["Chỉ sau nửa đêm","Bất cứ khi nào cần gạt nước đang bật","Chỉ trên xa lộ","Chỉ khi có tuyết"],"h1":"Hãy nghĩ đến lúc trời mưa.","h2":"Ở District of Columbia, bạn phải bật đèn pha bất cứ khi nào cần gạt nước đang bật, và cũng phải bật trong đường hầm và từ nửa giờ sau khi mặt trời lặn đến nửa giờ trước khi mặt trời mọc.","p":"Đúng. Bật cần gạt nước thì phải bật đèn pha."},"tl":{"q":"Sa District of Columbia (DC), kailan mo dapat buksan ang headlights mo?","o":["Pagkalipas lang ng hatinggabi","Tuwing nakabukas ang windshield wipers mo","Sa mga highway lang","Kapag umuulan lang ng niyebe"],"h1":"Isipin ang ulan.","h2":"Sa District of Columbia, dapat mong buksan ang headlights mo tuwing nakabukas ang windshield wipers mo, at gayundin sa mga tunnel at mula kalahating oras pagkalubog ng araw hanggang kalahating oras bago sumikat ang araw.","p":"Tama. Kapag nakabukas ang wipers, nakabukas din ang headlights."},"ar":{"q":"في District of Columbia (DC)، متى يجب أن تشغّل المصابيح الأمامية؟","o":["بعد منتصف الليل فقط","كلما كانت مسّاحات الزجاج الأمامي تعمل","على الطرق السريعة فقط","عندما يتساقط الثلج فقط"],"h1":"فكّر في المطر.","h2":"في District of Columbia يجب أن تشغّل المصابيح الأمامية كلما كانت مسّاحات الزجاج الأمامي تعمل، وكذلك في الأنفاق، ومن نصف ساعة بعد غروب الشمس إلى نصف ساعة قبل شروقها.","p":"صحيح. إذا عملت المسّاحات فشغّل المصابيح الأمامية."},"ref":{"doc":"DC","page":42}},{"id":"dc-032","scope":"DC","cat":"licensing","sign":null,"c":1,"en":{"q":"In the District of Columbia, you move to the District with a license from another place. How soon must you get a DC driver license?","o":["Within 10 days","Within 60 days","Within 6 months","Within 1 year"],"h1":"It is about two months.","h2":"In the District of Columbia, a new resident must get a DC driver license within 60 days of moving there.","p":"Right. New residents have 60 days to get a DC license."},"es":{"q":"En el Distrito de Columbia, usted se muda al Distrito con una licencia de otro lugar. ¿En cuánto tiempo debe sacar una licencia de DC?","o":["En 10 días","En 60 días","En 6 meses","En 1 año"],"h1":"Son unos dos meses.","h2":"En el Distrito de Columbia, un nuevo residente debe sacar una licencia de conducir de DC dentro de los 60 días después de mudarse.","p":"Correcto. Los nuevos residentes tienen 60 días para sacar una licencia de DC."},"ref":{"doc":"DC","page":11}},{"id":"dc-033","scope":"DC","cat":"licensing","sign":null,"c":3,"en":{"q":"In the District of Columbia, you move to a new home. How soon must you tell the DMV your new address?","o":["Within 5 days","Within 10 days","Within 1 year","Within 60 days"],"h1":"It is the same length of time a new resident has to get a license.","h2":"In the District of Columbia, residents must update their address with the DMV within 60 days.","p":"Right. Update your address within 60 days."},"es":{"q":"En el Distrito de Columbia, usted se muda a una casa nueva. ¿En cuánto tiempo debe darle su nueva dirección al DMV?","o":["En 5 días","En 10 días","En 1 año","En 60 días"],"h1":"Es el mismo tiempo que tiene un nuevo residente para sacar la licencia.","h2":"En el Distrito de Columbia, los residentes deben actualizar su dirección con el DMV dentro de los 60 días.","p":"Correcto. Actualice su dirección dentro de los 60 días."},"ref":{"doc":"DC","page":19}},{"id":"dc-034","scope":"DC","cat":"licensing","sign":null,"c":0,"en":{"q":"In the District of Columbia, your driver license has been expired for more than 545 days. What must you do to get it back?","o":["Pass both the knowledge test and the road skills test","Only pay a late fee","Only pass a vision screening","Only take an online traffic school course"],"h1":"After this long, the DMV wants to see both what you know and how you drive.","h2":"In the District of Columbia, if your license has been expired for more than 545 days, you must pass both the knowledge test and the road skills test.","p":"Right. After 545 days, you take both tests again."},"es":{"q":"En el Distrito de Columbia, su licencia lleva más de 545 días vencida. ¿Qué debe hacer para recuperarla?","o":["Aprobar el examen de conocimientos y el examen de manejo","Solo pagar un recargo","Solo pasar el examen de la vista","Solo tomar un curso de manejo en línea"],"h1":"Después de tanto tiempo, el DMV quiere ver lo que usted sabe y cómo maneja.","h2":"En el Distrito de Columbia, si su licencia lleva más de 545 días vencida, debe aprobar el examen de conocimientos y el examen de manejo.","p":"Correcto. Después de 545 días, se toman los dos exámenes otra vez."},"ref":{"doc":"DC","page":12}},{"id":"dc-035","scope":"DC","cat":"licensing","sign":null,"c":2,"en":{"q":"In the District of Columbia, you will be 70 or older when your license expires. What extra step do you need to renew it?","o":["Retake the road skills test every year","Drive only in daylight","Have your doctor fill out the Mature Driver section of the application","Get a new learner permit first"],"h1":"A medical professional must say you can still drive safely.","h2":"In the District of Columbia, a driver who is 70 or older when the license expires must have a doctor complete the Mature Driver section of the application.","p":"Right. At 70 and up, your doctor signs the Mature Driver section."},"es":{"q":"En el Distrito de Columbia, usted tendrá 70 años o más cuando venza su licencia. ¿Qué paso adicional necesita para renovarla?","o":["Repetir el examen de manejo cada año","Manejar solo de día","Pedirle a su médico que llene la sección de Conductor Mayor de la solicitud","Sacar primero un nuevo permiso de aprendiz"],"h1":"Un profesional de la salud debe decir que usted todavía puede manejar con seguridad.","h2":"En el Distrito de Columbia, un conductor que tenga 70 años o más cuando venza su licencia debe pedirle a un médico que llene la sección de Conductor Mayor de la solicitud.","p":"Correcto. A partir de los 70, su médico firma la sección de Conductor Mayor."},"ref":{"doc":"DC","page":12}},{"id":"dc-036","scope":"DC","cat":"licensing","sign":null,"c":3,"en":{"q":"In the District of Columbia, you fail the road skills test. How long must you wait before you take it again?","o":["You may retake it the same day","24 hours","30 days","72 hours"],"h1":"It is three days, counted in hours.","h2":"In the District of Columbia, after you fail the road skills test, you must wait 72 hours before you may take it again.","p":"Right. Wait 72 hours before the next road test."},"es":{"q":"En el Distrito de Columbia, usted no aprueba el examen de manejo. ¿Cuánto tiempo debe esperar para tomarlo otra vez?","o":["Puede repetirlo el mismo día","24 horas","30 días","72 horas"],"h1":"Son tres días, contados en horas.","h2":"En el Distrito de Columbia, si no aprueba el examen de manejo, debe esperar 72 horas antes de tomarlo otra vez.","p":"Correcto. Espere 72 horas antes del próximo examen de manejo."},"ref":{"doc":"DC","page":13}},{"id":"dc-037","scope":"DC","cat":"licensing","sign":null,"c":1,"en":{"q":"In the District of Columbia, what happens if you do not cancel your road skills test at least two business days ahead?","o":["You lose your learner permit","You pay a $30 cancellation fee","You must wait one year to test","Nothing happens"],"h1":"It costs you money.","h2":"In the District of Columbia, if you do not cancel a road skills test at least two business days ahead, you are charged a $30 cancellation fee.","p":"Right. A late cancel costs $30."},"es":{"q":"En el Distrito de Columbia, ¿qué pasa si no cancela su examen de manejo con por lo menos dos días hábiles de anticipación?","o":["Pierde su permiso de aprendiz","Paga un cargo de cancelación de $30","Debe esperar un año para el examen","No pasa nada"],"h1":"Le cuesta dinero.","h2":"En el Distrito de Columbia, si no cancela el examen de manejo con por lo menos dos días hábiles de anticipación, se le cobra un cargo de cancelación de $30.","p":"Correcto. Cancelar tarde cuesta $30."},"ref":{"doc":"DC","page":12}},{"id":"dc-038","scope":"DC","cat":"licensing","sign":null,"c":0,"en":{"q":"In the District of Columbia, how long is a provisional driver license valid?","o":["1 year, and it can be renewed","6 months, and it cannot be renewed","2 years, and it cannot be renewed","8 years, like a full license"],"h1":"It is shorter than the learner permit.","h2":"In the District of Columbia, a provisional driver license is valid for one year and can be renewed.","p":"Right. A provisional license lasts one year and can be renewed."},"es":{"q":"En el Distrito de Columbia, ¿por cuánto tiempo es válida una licencia provisional?","o":["1 año, y se puede renovar","6 meses, y no se puede renovar","2 años, y no se puede renovar","8 años, como una licencia completa"],"h1":"Es más corto que el permiso de aprendiz.","h2":"En el Distrito de Columbia, una licencia provisional es válida por un año y se puede renovar.","p":"Correcto. La licencia provisional dura un año y se puede renovar."},"ref":{"doc":"DC","page":14}},{"id":"dc-039","scope":"DC","cat":"licensing","sign":null,"c":2,"en":{"q":"In the District of Columbia, a provisional driver breaks a GRAD rule for the first time. How long is the license suspended?","o":["7 days","1 year","30 days","It is never suspended for a first time"],"h1":"The suspension grows to 60 and then 90 days for later violations.","h2":"In the District of Columbia, a provisional license is suspended for 30 days for a first GRAD violation, 60 days for a second, and 90 days for a third or more.","p":"Right. A first GRAD violation means a 30-day suspension."},"es":{"q":"En el Distrito de Columbia, un conductor con licencia provisional rompe una regla del programa GRAD por primera vez. ¿Por cuánto tiempo se suspende la licencia?","o":["7 días","1 año","30 días","Nunca se suspende la primera vez"],"h1":"La suspensión sube a 60 y luego a 90 días en las siguientes infracciones.","h2":"En el Distrito de Columbia, la licencia provisional se suspende 30 días por la primera infracción del programa GRAD, 60 días por la segunda y 90 días por la tercera o más.","p":"Correcto. La primera infracción del GRAD significa 30 días de suspensión."},"ref":{"doc":"DC","page":16}},{"id":"dc-040","scope":"DC","cat":"licensing","sign":null,"c":1,"en":{"q":"In the District of Columbia, what is the shortest license revocation for a first conviction of driving under the influence?","o":["30 days","6 months","5 years","There is no revocation for a first offense"],"h1":"It grows to 1 year for a second offense and 2 years for a third.","h2":"In the District of Columbia, the minimum revocation for a first driving-under-the-influence offense is 6 months.","p":"Right. A first DUI means at least 6 months of revocation."},"es":{"q":"En el Distrito de Columbia, ¿cuál es la revocación más corta de la licencia por una primera condena por manejar bajo la influencia?","o":["30 días","6 meses","5 años","No hay revocación por una primera infracción"],"h1":"Sube a 1 año por una segunda infracción y a 2 años por una tercera.","h2":"En el Distrito de Columbia, la revocación mínima por una primera infracción de manejar bajo la influencia es de 6 meses.","p":"Correcto. Una primera condena por DUI significa por lo menos 6 meses de revocación."},"ref":{"doc":"DC","page":19}},{"id":"dc-041","scope":"DC","cat":"licensing","sign":null,"c":3,"en":{"q":"In the District of Columbia, a driver is convicted of driving under the influence. Which program must they join?","o":["A defensive driving video class","A free bus pass program","A volunteer road clean-up program","The Ignition Interlock Device (IID) Program"],"h1":"It puts a breath-testing device in the car.","h2":"In the District of Columbia, a driver convicted of an alcohol-related offense such as driving under the influence must enroll in the Ignition Interlock Device (IID) Program.","p":"Right. A DUI conviction means joining the IID Program."},"es":{"q":"En el Distrito de Columbia, un conductor es condenado por manejar bajo la influencia. ¿En qué programa debe inscribirse?","o":["Una clase de manejo defensivo en video","Un programa de pase gratis de autobús","Un programa voluntario de limpieza de calles","El Programa de Dispositivo de Bloqueo de Encendido (IID)"],"h1":"Pone en el carro un aparato que mide el aliento.","h2":"En el Distrito de Columbia, un conductor condenado por una infracción relacionada con el alcohol, como manejar bajo la influencia, debe inscribirse en el Programa de Dispositivo de Bloqueo de Encendido (IID).","p":"Correcto. Una condena por DUI significa entrar al Programa IID."},"ref":{"doc":"DC","page":19}},{"id":"dc-042","scope":"DC","cat":"licensing","sign":null,"c":0,"en":{"q":"In the District of Columbia, how can a driver earn a Good Point on their driving record?","o":["Keep a valid DC license for a full calendar year with no pointable moving violations","Take a free safety video online","Pay every parking ticket on time","Drive under the speed limit for one month"],"h1":"It takes a clean year of driving.","h2":"In the District of Columbia, a driver who keeps a valid DC license for a full calendar year without any pointable moving violations may earn a Good Point.","p":"Right. A clean calendar year can earn a Good Point."},"es":{"q":"En el Distrito de Columbia, ¿cómo puede un conductor ganar un Punto Bueno (Good Point) en su historial de manejo?","o":["Mantener una licencia válida de DC un año calendario completo sin infracciones de tránsito con puntos","Ver un video de seguridad gratis en línea","Pagar a tiempo todas las multas de estacionamiento","Manejar por debajo del límite de velocidad durante un mes"],"h1":"Hace falta un año limpio de manejo.","h2":"En el Distrito de Columbia, un conductor que mantiene una licencia válida de DC durante un año calendario completo sin infracciones de tránsito con puntos puede ganar un Punto Bueno.","p":"Correcto. Un año calendario limpio puede darle un Punto Bueno."},"ref":{"doc":"DC","page":19}},{"id":"dc-043","scope":"DC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In the District of Columbia, what is the rule about hanging things from your rear-view mirror?","o":["Small items are allowed if they are under 3 inches","Only parking permits may hang there","Nothing may be attached to or hang from it while you drive","Anything is allowed if you can still see"],"h1":"Think about what blocks your view of the road.","h2":"In the District of Columbia, having anything attached to or hanging from the rear-view mirror while driving is against the regulations.","p":"Right. Keep the rear-view mirror clear of hanging items."},"es":{"q":"En el Distrito de Columbia, ¿cuál es la regla sobre colgar cosas del espejo retrovisor?","o":["Se permiten objetos pequeños de menos de 3 pulgadas","Solo se pueden colgar permisos de estacionamiento","No se puede colgar ni sujetar nada en él mientras maneja","Se permite cualquier cosa si todavía puede ver"],"h1":"Piense en lo que le tapa la vista del camino.","h2":"En el Distrito de Columbia, tener algo sujeto o colgado del espejo retrovisor mientras maneja va en contra de las normas.","p":"Correcto. No cuelgue nada del espejo retrovisor."},"ref":{"doc":"DC","page":19}},{"id":"dc-044","scope":"DC","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In the District of Columbia, a fire truck is answering an emergency. How close may you follow it?","o":["No closer than 50 feet","No closer than 100 feet","As close as you like if you are careful","No closer than 500 feet"],"h1":"It is about the length of one and a half football fields.","h2":"In the District of Columbia, you must not follow a fire truck closer than 500 feet when it is answering an emergency.","p":"Right. Stay at least 500 feet behind a fire truck on a call."},"es":{"q":"En el Distrito de Columbia, un camión de bomberos va a una emergencia. ¿A qué distancia lo puede seguir?","o":["No más cerca de 50 pies","No más cerca de 100 pies","Tan cerca como quiera si tiene cuidado","No más cerca de 500 pies"],"h1":"Es como una cancha de fútbol americano y media.","h2":"En el Distrito de Columbia, no debe seguir a un camión de bomberos a menos de 500 pies cuando va a una emergencia.","p":"Correcto. Quédese por lo menos a 500 pies detrás de un camión de bomberos en emergencia."},"ref":{"doc":"DC","page":35}},{"id":"dc-045","scope":"DC","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In the District of Columbia, you come to a block where fire engines or emergency vehicles are stopped. What should you do?","o":["Drive slowly through the block","Turn right or left instead of driving into the block","Honk and drive around them","Park in the block and wait"],"h1":"Driving into that block is against the traffic rules.","h2":"In the District of Columbia, you should not drive into a block where fire engines or emergency vehicles are stopped; turn right or left instead.","p":"Right. Turn away and do not enter that block."},"es":{"q":"En el Distrito de Columbia, usted llega a una cuadra donde hay camiones de bomberos o vehículos de emergencia detenidos. ¿Qué debe hacer?","o":["Pasar despacio por la cuadra","Doblar a la derecha o a la izquierda en vez de entrar a la cuadra","Tocar la bocina y rodearlos","Estacionarse en la cuadra y esperar"],"h1":"Entrar a esa cuadra va contra las reglas de tránsito.","h2":"En el Distrito de Columbia, no debe entrar a una cuadra donde hay camiones de bomberos o vehículos de emergencia detenidos; doble a la derecha o a la izquierda.","p":"Correcto. Doble y no entre a esa cuadra."},"ref":{"doc":"DC","page":35}},{"id":"dc-046","scope":"DC","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In the District of Columbia, a school vehicle is stopped with its red lights flashing. How far away must you stop?","o":["At least 20 feet from its front or rear","At least 5 feet from its front or rear","At least 100 feet from its front or rear","You only need to slow down"],"h1":"Leave a bit more than one car length.","h2":"In the District of Columbia, when a school vehicle is stopped with its red lights flashing, you must stop at least 20 feet from its front or rear.","p":"Right. Stop at least 20 feet from a stopped school vehicle."},"es":{"q":"En el Distrito de Columbia, un vehículo escolar está detenido con sus luces rojas intermitentes. ¿A qué distancia debe detenerse usted?","o":["Por lo menos a 20 pies de su parte delantera o trasera","Por lo menos a 5 pies de su parte delantera o trasera","Por lo menos a 100 pies de su parte delantera o trasera","Solo necesita bajar la velocidad"],"h1":"Deje un poco más que el largo de un carro.","h2":"En el Distrito de Columbia, cuando un vehículo escolar está detenido con sus luces rojas intermitentes, debe detenerse por lo menos a 20 pies de su parte delantera o trasera.","p":"Correcto. Deténgase por lo menos a 20 pies de un vehículo escolar detenido."},"ref":{"doc":"DC","page":38}},{"id":"dc-047","scope":"DC","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In the District of Columbia, a bus is stopped at an intersection to let riders on and off. May you turn right in front of it?","o":["Yes, if you signal first","Yes, if no riders are in the street","No; stay or merge behind the bus, or face a fine of at least $200","No, unless the light is green"],"h1":"District law protects people getting on and off the bus.","h2":"In the District of Columbia, it is illegal to turn right in front of a bus stopped at an intersection to load or unload riders, and the fine is at least $200.","p":"Right. Stay behind the bus; the fine is at least $200."},"es":{"q":"En el Distrito de Columbia, un autobús está detenido en una intersección para que suban y bajen pasajeros. ¿Puede doblar a la derecha delante de él?","o":["Sí, si pone la direccional primero","Sí, si no hay pasajeros en la calle","No; quédese o incorpórese detrás del autobús, o la multa es de por lo menos $200","No, a menos que el semáforo esté en verde"],"h1":"La ley del Distrito protege a las personas que suben y bajan del autobús.","h2":"En el Distrito de Columbia, es ilegal doblar a la derecha delante de un autobús detenido en una intersección para subir o bajar pasajeros, y la multa es de por lo menos $200.","p":"Correcto. Quédese detrás del autobús; la multa es de por lo menos $200."},"ref":{"doc":"DC","page":39}},{"id":"dc-048","scope":"DC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In the District of Columbia, there is no sign about turning across a bus lane. Where may you cross it to make a turn?","o":["Anywhere along the block","Within 40 feet of the intersection","Only after 9 p.m.","Never; you must turn from the bus lane's left side only"],"h1":"Enter the lane only close to the corner.","h2":"In the District of Columbia, when no sign says otherwise, you may cross a bus lane to turn within 40 feet of the intersection, after yielding to bicycles and buses in the lane.","p":"Right. Cross a bus lane to turn only within 40 feet of the intersection."},"es":{"q":"En el Distrito de Columbia, no hay ningún letrero sobre cruzar un carril de autobús para doblar. ¿Dónde puede cruzarlo para doblar?","o":["En cualquier parte de la cuadra","Dentro de los 40 pies antes de la intersección","Solo después de las 9 p.m.","Nunca; debe doblar solo desde el lado izquierdo del carril de autobús"],"h1":"Entre al carril solo cerca de la esquina.","h2":"En el Distrito de Columbia, si ningún letrero dice otra cosa, puede cruzar un carril de autobús para doblar dentro de los 40 pies antes de la intersección, después de ceder el paso a bicicletas y autobuses en el carril.","p":"Correcto. Cruce el carril de autobús para doblar solo dentro de los 40 pies antes de la intersección."},"ref":{"doc":"DC","page":39}},{"id":"dc-049","scope":"DC","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In the District of Columbia, a streetcar going your way has stopped. How should you pass it?","o":["On the right side, quickly","Between the streetcar and the curb","By driving on the tracks","With great care, on the left side, when it is safe"],"h1":"Riders may be getting on or off at the curb side.","h2":"In the District of Columbia, you pass a stopped streetcar going your way on its left side, with extreme care and only when it is safe.","p":"Right. Pass a stopped streetcar carefully on the left."},"es":{"q":"En el Distrito de Columbia, un tranvía que va en su misma dirección está detenido. ¿Cómo debe rebasarlo?","o":["Por el lado derecho, rápido","Entre el tranvía y la acera","Manejando sobre los rieles","Con mucho cuidado, por el lado izquierdo, cuando sea seguro"],"h1":"Puede haber pasajeros subiendo o bajando por el lado de la acera.","h2":"En el Distrito de Columbia, un tranvía detenido que va en su misma dirección se rebasa por su lado izquierdo, con muchísimo cuidado y solo cuando sea seguro.","p":"Correcto. Rebase un tranvía detenido con cuidado por la izquierda."},"ref":{"doc":"DC","page":40}},{"id":"dc-050","scope":"DC","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In the District of Columbia, how far ahead should you signal before you change lanes?","o":["At least 300 feet","At least 20 feet","At least 1 mile","Only as you start to move over"],"h1":"It is three times the distance used before a turn.","h2":"In the District of Columbia, you should signal at least 300 feet before you change lanes, and sooner is better.","p":"Right. Signal at least 300 feet before a lane change."},"es":{"q":"En el Distrito de Columbia, ¿con cuánta anticipación debe poner la direccional antes de cambiar de carril?","o":["Por lo menos 300 pies antes","Por lo menos 20 pies antes","Por lo menos 1 milla antes","Solo cuando empieza a cambiarse"],"h1":"Es tres veces la distancia que se usa antes de doblar.","h2":"En el Distrito de Columbia, debe poner la direccional por lo menos 300 pies antes de cambiar de carril, y es mejor hacerlo antes.","p":"Correcto. Ponga la direccional por lo menos 300 pies antes de cambiar de carril."},"ref":{"doc":"DC","page":42}},{"id":"dc-051","scope":"DC","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In the District of Columbia, how close to a driveway or alley may you stand or park?","o":["Right up to the edge","No closer than 1 foot","No closer than 5 feet, and never in front of it","No closer than 50 feet"],"h1":"It is a short distance, but you may not block it.","h2":"In the District of Columbia, you may not stand or park in front of a driveway or alley, or within 5 feet of one.","p":"Right. Stay 5 feet from a driveway or alley."},"es":{"q":"En el Distrito de Columbia, ¿a qué distancia de una entrada de garaje o un callejón puede detenerse o estacionarse?","o":["Justo hasta el borde","No más cerca de 1 pie","No más cerca de 5 pies, y nunca enfrente","No más cerca de 50 pies"],"h1":"Es una distancia corta, pero no puede bloquearla.","h2":"En el Distrito de Columbia, no puede detenerse ni estacionarse enfrente de una entrada de garaje o un callejón, ni a menos de 5 pies de uno.","p":"Correcto. Quédese a 5 pies de una entrada de garaje o un callejón."},"ref":{"doc":"DC","page":44}},{"id":"de-001","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, what is the youngest age to get a Level 1 learner's permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is a later age than in many other states.","h2":"In Delaware you can get a Level 1 learner's permit at 16, after you finish an approved driver education course.","p":"Right. Delaware starts the learner's permit at 16."},"es":{"q":"En Delaware, ¿cuál es la edad mínima para obtener el permiso de aprendiz de Nivel 1?","o":["14 años","15 años","16 años","17 años"],"h1":"Es una edad mayor que en muchos otros estados.","h2":"En Delaware usted puede obtener el permiso de aprendiz de Nivel 1 a los 16 años, después de terminar un curso aprobado de educación vial.","p":"Correcto. En Delaware el permiso de aprendiz empieza a los 16."},"zh":{"q":"在 Delaware，最小几岁可以拿到 Level 1 学习驾照？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比很多其他州的年龄大。","h2":"在 Delaware，你完成认可的驾驶教育课程以后，16 岁可以拿到 Level 1 学习驾照。","p":"对。Delaware 的学习驾照从 16 岁开始。"},"vi":{"q":"Ở Delaware, tuổi nhỏ nhất để được cấp giấy phép tập lái Level 1 (Level 1 learner's permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Tuổi này muộn hơn so với nhiều tiểu bang khác.","h2":"Ở Delaware, bạn có thể được cấp giấy phép tập lái Level 1 khi 16 tuổi, sau khi học xong một khóa giáo dục lái xe được chấp thuận.","p":"Đúng. Delaware bắt đầu giấy phép tập lái từ 16 tuổi."},"tl":{"q":"Sa Delaware, ilang taon ang pinakabatang edad para makakuha ng Level 1 learner's permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Mas matanda ang edad na ito kaysa sa maraming ibang estado.","h2":"Sa Delaware, puwede kang kumuha ng Level 1 learner's permit sa edad na 16, pagkatapos mong matapos ang isang aprubadong kurso sa driver education.","p":"Tama. Nagsisimula ang learner's permit sa Delaware sa edad na 16."},"ar":{"q":"في Delaware، ما أصغر عمر للحصول على رخصة متعلم من المستوى الأول (Level 1 learner's permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هذا العمر أكبر منه في كثير من الولايات الأخرى.","h2":"في Delaware يمكنك الحصول على رخصة متعلم من المستوى الأول في عمر 16 سنة، بعد أن تنهي دورة معتمدة لتعليم القيادة.","p":"صحيح. تبدأ رخصة المتعلم في Delaware في عمر 16 سنة."},"ref":{"doc":"DE","page":28}},{"id":"de-002","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, what must a teen finish before getting a Level 1 learner's permit?","o":["An approved driver education course","A road test","A year of driving on a farm","A first aid course"],"h1":"Think of the classes that teach driving.","h2":"A Delaware teen must finish an approved driver education course before getting the Level 1 learner's permit.","p":"Right. Driver education comes first in Delaware."},"es":{"q":"En Delaware, ¿qué debe terminar un adolescente antes de obtener el permiso de aprendiz de Nivel 1?","o":["Un curso aprobado de educación vial","Un examen de manejo en la calle","Un año de manejo en una granja","Un curso de primeros auxilios"],"h1":"Piense en las clases que enseñan a manejar.","h2":"Un adolescente en Delaware debe terminar un curso aprobado de educación vial antes de obtener el permiso de aprendiz de Nivel 1.","p":"Correcto. En Delaware la educación vial va primero."},"zh":{"q":"在 Delaware，青少年拿 Level 1 学习驾照前必须完成什么？","o":["认可的驾驶教育课程","路考","在农场开车一年","急救课程"],"h1":"想一想教开车的课。","h2":"Delaware 的青少年拿 Level 1 学习驾照前，必须完成认可的驾驶教育课程。","p":"对。在 Delaware，先上驾驶教育课。"},"vi":{"q":"Ở Delaware, thiếu niên phải hoàn thành điều gì trước khi được cấp giấy phép tập lái Level 1?","o":["Một khóa giáo dục lái xe được chấp thuận (driver education)","Một bài thi lái xe trên đường","Một năm lái xe ở nông trại","Một khóa sơ cứu"],"h1":"Hãy nghĩ đến các lớp học dạy lái xe.","h2":"Thiếu niên ở Delaware phải học xong một khóa giáo dục lái xe được chấp thuận trước khi được cấp giấy phép tập lái Level 1.","p":"Đúng. Ở Delaware, giáo dục lái xe phải có trước."},"tl":{"q":"Sa Delaware, ano ang dapat tapusin ng isang teen bago makakuha ng Level 1 learner's permit?","o":["Isang aprubadong kurso sa driver education","Isang road test","Isang taon ng pagmamaneho sa bukid","Isang kurso sa first aid"],"h1":"Isipin ang mga klase na nagtuturo ng pagmamaneho.","h2":"Dapat tapusin ng isang teen sa Delaware ang isang aprubadong kurso sa driver education bago makakuha ng Level 1 learner's permit.","p":"Tama. Driver education muna sa Delaware."},"ar":{"q":"في Delaware، ماذا يجب أن ينهي المراهق قبل الحصول على رخصة متعلم من المستوى الأول؟","o":["دورة معتمدة لتعليم القيادة (driver education)","اختبار قيادة على الطريق","سنة من القيادة في مزرعة","دورة إسعافات أولية"],"h1":"فكّر في الدروس التي تعلّم القيادة.","h2":"يجب على المراهق في Delaware أن ينهي دورة معتمدة لتعليم القيادة قبل الحصول على رخصة متعلم من المستوى الأول.","p":"صحيح. تعليم القيادة يأتي أولًا في Delaware."},"ref":{"doc":"DE","page":28}},{"id":"de-003","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, for how long does a Level 1 learner's permit let a teen drive?","o":["6 months","12 months","18 months","24 months"],"h1":"It is one full year.","h2":"A Delaware Level 1 learner's permit lets a teen drive under its rules for 12 months.","p":"Right. The Delaware permit lasts 12 months."},"es":{"q":"En Delaware, ¿por cuánto tiempo permite manejar el permiso de aprendiz de Nivel 1?","o":["6 meses","12 meses","18 meses","24 meses"],"h1":"Es un año completo.","h2":"El permiso de aprendiz de Nivel 1 de Delaware permite manejar bajo sus reglas durante 12 meses.","p":"Correcto. El permiso de Delaware dura 12 meses."},"zh":{"q":"在 Delaware，Level 1 学习驾照让青少年开车多久？","o":["6 个月","12 个月","18 个月","24 个月"],"h1":"它是整整一年。","h2":"Delaware 的 Level 1 学习驾照让青少年按它的规定开车 12 个月。","p":"对。Delaware 的学习驾照有效 12 个月。"},"vi":{"q":"Ở Delaware, giấy phép tập lái Level 1 cho phép thiếu niên lái xe trong bao lâu?","o":["6 tháng","12 tháng","18 tháng","24 tháng"],"h1":"Đó là trọn một năm.","h2":"Giấy phép tập lái Level 1 ở Delaware cho phép thiếu niên lái xe theo các quy định của nó trong 12 tháng.","p":"Đúng. Giấy phép ở Delaware có hiệu lực 12 tháng."},"tl":{"q":"Sa Delaware, gaano katagal puwedeng magmaneho ang isang teen gamit ang Level 1 learner's permit?","o":["6 na buwan","12 buwan","18 buwan","24 na buwan"],"h1":"Isang buong taon ito.","h2":"Pinapayagan ng Level 1 learner's permit sa Delaware ang isang teen na magmaneho ayon sa mga patakaran nito nang 12 buwan.","p":"Tama. Tumatagal nang 12 buwan ang permit sa Delaware."},"ar":{"q":"في Delaware، كم من الوقت تسمح رخصة المتعلم من المستوى الأول للمراهق بالقيادة؟","o":["6 أشهر","12 شهرًا","18 شهرًا","24 شهرًا"],"h1":"إنها سنة كاملة.","h2":"تسمح رخصة المتعلم من المستوى الأول في Delaware للمراهق بالقيادة حسب قواعدها لمدة 12 شهرًا.","p":"صحيح. رخصة Delaware تستمر 12 شهرًا."},"ref":{"doc":"DE","page":30}},{"id":"de-004","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, a supervisor who is not the teen's parent or guardian must be at least how old?","o":["18","20","21","25"],"h1":"It is older than the age to buy alcohol.","h2":"In Delaware, a supervisor who is not a parent or guardian must be a licensed driver who is at least 25 years old.","p":"Right. The supervisor must be 25 or older."},"es":{"q":"En Delaware, un supervisor que no es el padre, la madre ni el tutor del adolescente debe tener por lo menos ¿qué edad?","o":["18","20","21","25"],"h1":"Es mayor que la edad para comprar alcohol.","h2":"En Delaware, un supervisor que no es padre, madre ni tutor debe ser un conductor con licencia de por lo menos 25 años.","p":"Correcto. El supervisor debe tener 25 años o más."},"zh":{"q":"在 Delaware，不是青少年父母或监护人的监督者，最少要几岁？","o":["18 岁","20 岁","21 岁","25 岁"],"h1":"它比可以买酒的年龄大。","h2":"在 Delaware，不是父母或监护人的监督者，必须是至少 25 岁、有驾照的司机。","p":"对。监督者必须 25 岁或以上。"},"vi":{"q":"Ở Delaware, người giám sát không phải là cha mẹ hoặc người giám hộ của thiếu niên phải ít nhất bao nhiêu tuổi?","o":["18","20","21","25"],"h1":"Tuổi này lớn hơn tuổi được mua rượu.","h2":"Ở Delaware, người giám sát không phải là cha mẹ hoặc người giám hộ phải là người có bằng lái và ít nhất 25 tuổi.","p":"Đúng. Người giám sát phải từ 25 tuổi trở lên."},"tl":{"q":"Sa Delaware, ilang taon dapat ang supervisor na hindi magulang o guardian ng teen?","o":["18","20","21","25"],"h1":"Mas matanda ito kaysa sa edad para bumili ng alak.","h2":"Sa Delaware, ang supervisor na hindi magulang o guardian ay dapat lisensyadong driver na hindi bababa sa 25 taong gulang.","p":"Tama. Dapat 25 taong gulang o higit pa ang supervisor."},"ar":{"q":"في Delaware، كم يجب أن يكون عمر المشرف الذي ليس أحد والدي المراهق أو وليّ أمره على الأقل؟","o":["18","20","21","25"],"h1":"إنه أكبر من عمر شراء الكحول.","h2":"في Delaware، يجب أن يكون المشرف الذي ليس أحد الوالدين أو وليّ الأمر سائقًا مرخّصًا عمره 25 سنة على الأقل.","p":"صحيح. يجب أن يكون عمر المشرف 25 سنة أو أكثر."},"ref":{"doc":"DE","page":29}},{"id":"de-005","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, how long must a supervisor who is not a parent or guardian have held a driver license?","o":["1 year","3 years","5 years","10 years"],"h1":"It is half of ten years.","h2":"In Delaware, a supervisor who is not a parent or guardian must have held a Class D license for at least 5 years.","p":"Right. Five years of license experience is required."},"es":{"q":"En Delaware, ¿cuánto tiempo debe tener su licencia un supervisor que no es padre, madre ni tutor?","o":["1 año","3 años","5 años","10 años"],"h1":"Es la mitad de diez años.","h2":"En Delaware, un supervisor que no es padre, madre ni tutor debe haber tenido una licencia Clase D por lo menos 5 años.","p":"Correcto. Se requieren cinco años con licencia."},"zh":{"q":"在 Delaware，不是父母或监护人的监督者，必须持有驾照多久？","o":["1 年","3 年","5 年","10 年"],"h1":"它是十年的一半。","h2":"在 Delaware，不是父母或监护人的监督者，必须持有 Class D 驾照至少 5 年。","p":"对。需要五年的驾照经验。"},"vi":{"q":"Ở Delaware, người giám sát không phải là cha mẹ hoặc người giám hộ phải có bằng lái trong bao lâu?","o":["1 năm","3 năm","5 năm","10 năm"],"h1":"Đó là một nửa của mười năm.","h2":"Ở Delaware, người giám sát không phải là cha mẹ hoặc người giám hộ phải có bằng lái Class D ít nhất 5 năm.","p":"Đúng. Cần có bằng lái ít nhất năm năm."},"tl":{"q":"Sa Delaware, gaano katagal dapat may driver license ang supervisor na hindi magulang o guardian?","o":["1 taon","3 taon","5 taon","10 taon"],"h1":"Kalahati ito ng sampung taon.","h2":"Sa Delaware, ang supervisor na hindi magulang o guardian ay dapat may Class D license nang hindi bababa sa 5 taon.","p":"Tama. Kailangan ang limang taon ng pagkakaroon ng lisensya."},"ar":{"q":"في Delaware، منذ كم من الوقت يجب أن يحمل المشرف الذي ليس أحد الوالدين أو وليّ الأمر رخصة قيادة؟","o":["سنة واحدة","3 سنوات","5 سنوات","10 سنوات"],"h1":"إنها نصف عشر سنوات.","h2":"في Delaware، يجب أن يكون المشرف الذي ليس أحد الوالدين أو وليّ الأمر قد حمل رخصة Class D لمدة 5 سنوات على الأقل.","p":"صحيح. يلزم خمس سنوات من حمل الرخصة."},"ref":{"doc":"DE","page":29}},{"id":"de-006","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, how many hours of supervised driving must a permit holder log before driving alone?","o":["30 hours","50 hours","70 hours","100 hours"],"h1":"It is half of one hundred.","h2":"A Delaware permit holder must log at least 50 hours of supervised driving before driving without a supervisor.","p":"Right. Delaware asks for 50 supervised hours."},"es":{"q":"En Delaware, ¿cuántas horas de manejo supervisado debe registrar un aprendiz antes de manejar solo?","o":["30 horas","50 horas","70 horas","100 horas"],"h1":"Es la mitad de cien.","h2":"Un aprendiz en Delaware debe registrar por lo menos 50 horas de manejo supervisado antes de manejar sin supervisor.","p":"Correcto. Delaware pide 50 horas supervisadas."},"zh":{"q":"在 Delaware，持学习驾照的人单独开车前，必须记录多少小时有人监督的驾驶？","o":["30 小时","50 小时","70 小时","100 小时"],"h1":"它是一百的一半。","h2":"Delaware 持学习驾照的人在没有监督者陪同开车前，必须记录至少 50 小时有人监督的驾驶。","p":"对。Delaware 要求 50 小时有人监督的驾驶。"},"vi":{"q":"Ở Delaware, người có giấy phép tập lái phải ghi lại bao nhiêu giờ lái xe có giám sát trước khi được lái một mình?","o":["30 giờ","50 giờ","70 giờ","100 giờ"],"h1":"Đó là một nửa của một trăm.","h2":"Người có giấy phép tập lái ở Delaware phải ghi lại ít nhất 50 giờ lái xe có giám sát trước khi được lái mà không có người giám sát.","p":"Đúng. Delaware yêu cầu 50 giờ có giám sát."},"tl":{"q":"Sa Delaware, ilang oras ng supervised na pagmamaneho ang dapat itala ng may permit bago magmaneho nang mag-isa?","o":["30 oras","50 oras","70 oras","100 oras"],"h1":"Kalahati ito ng isang daan.","h2":"Ang may permit sa Delaware ay dapat magtala ng hindi bababa sa 50 oras ng supervised na pagmamaneho bago magmaneho nang walang supervisor.","p":"Tama. 50 supervised na oras ang hinihingi ng Delaware."},"ar":{"q":"في Delaware، كم ساعة من القيادة تحت الإشراف يجب أن يسجّل حامل رخصة المتعلم قبل أن يقود وحده؟","o":["30 ساعة","50 ساعة","70 ساعة","100 ساعة"],"h1":"إنها نصف المئة.","h2":"يجب على حامل رخصة المتعلم في Delaware أن يسجّل 50 ساعة على الأقل من القيادة تحت الإشراف قبل أن يقود بدون مشرف.","p":"صحيح. تطلب Delaware 50 ساعة تحت الإشراف."},"ref":{"doc":"DE","page":29}},{"id":"de-007","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, how many of the supervised practice hours must be at night?","o":["At least 10 hours","At least 2 hours","At least 25 hours","None"],"h1":"It is a round number, a small part of the total.","h2":"In Delaware, at least 10 of the 50 supervised practice hours must be driven at night.","p":"Right. Ten of the hours must be at night."},"es":{"q":"En Delaware, ¿cuántas de las horas de práctica supervisada deben ser de noche?","o":["Por lo menos 10 horas","Por lo menos 2 horas","Por lo menos 25 horas","Ninguna"],"h1":"Es un número redondo, una parte pequeña del total.","h2":"En Delaware, por lo menos 10 de las 50 horas de práctica supervisada deben ser de noche.","p":"Correcto. Diez de las horas deben ser de noche."},"zh":{"q":"在 Delaware，有人监督的练习时间里，有多少小时必须在晚上？","o":["至少 10 小时","至少 2 小时","至少 25 小时","不需要"],"h1":"它是一个整数，是全部时间的一小部分。","h2":"在 Delaware，50 小时有人监督的练习里，至少 10 小时必须在晚上开。","p":"对。其中十小时必须在晚上。"},"vi":{"q":"Ở Delaware, bao nhiêu giờ trong số giờ tập lái có giám sát phải lái vào ban đêm?","o":["Ít nhất 10 giờ","Ít nhất 2 giờ","Ít nhất 25 giờ","Không giờ nào"],"h1":"Đó là một số tròn, một phần nhỏ của tổng số giờ.","h2":"Ở Delaware, ít nhất 10 trong số 50 giờ tập lái có giám sát phải được lái vào ban đêm.","p":"Đúng. Mười giờ phải lái vào ban đêm."},"tl":{"q":"Sa Delaware, ilan sa mga oras ng supervised na pagsasanay ang dapat sa gabi?","o":["Hindi bababa sa 10 oras","Hindi bababa sa 2 oras","Hindi bababa sa 25 oras","Wala"],"h1":"Isa itong buong numero, maliit na bahagi ng kabuuan.","h2":"Sa Delaware, hindi bababa sa 10 sa 50 oras ng supervised na pagsasanay ang dapat imaneho sa gabi.","p":"Tama. Sampu sa mga oras ang dapat sa gabi."},"ar":{"q":"في Delaware، كم ساعة من ساعات التدريب تحت الإشراف يجب أن تكون في الليل؟","o":["10 ساعات على الأقل","ساعتان على الأقل","25 ساعة على الأقل","لا شيء"],"h1":"إنه رقم مستدير، وجزء صغير من المجموع.","h2":"في Delaware، يجب أن تكون 10 ساعات على الأقل من الـ 50 ساعة من التدريب تحت الإشراف قيادةً في الليل.","p":"صحيح. عشر ساعات يجب أن تكون في الليل."},"ref":{"doc":"DE","page":29}},{"id":"de-008","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, for how long at the start of the learner's permit may a teen drive only with a supervisor?","o":["The first month","The first 6 months","The first 9 months","The whole 12 months"],"h1":"It is half of the permit time.","h2":"During the first 6 months of a Delaware learner's permit, the teen may drive only with a qualified supervisor.","p":"Right. The first six months are fully supervised."},"es":{"q":"En Delaware, ¿durante cuánto tiempo al comienzo del permiso de aprendiz puede manejar el adolescente solo con un supervisor?","o":["El primer mes","Los primeros 6 meses","Los primeros 9 meses","Los 12 meses completos"],"h1":"Es la mitad del tiempo del permiso.","h2":"Durante los primeros 6 meses del permiso de aprendiz de Delaware, el adolescente puede manejar solamente con un supervisor calificado.","p":"Correcto. Los primeros seis meses son con supervisión."},"zh":{"q":"在 Delaware，学习驾照开始后的多长时间内，青少年只能和监督者一起开车？","o":["第一个月","前 6 个月","前 9 个月","整整 12 个月"],"h1":"它是学习驾照期间的一半。","h2":"在 Delaware 学习驾照的前 6 个月，青少年只能和合格的监督者一起开车。","p":"对。前六个月要全程有人监督。"},"vi":{"q":"Ở Delaware, trong bao lâu đầu tiên của giấy phép tập lái, thiếu niên chỉ được lái xe khi có người giám sát?","o":["Tháng đầu tiên","6 tháng đầu tiên","9 tháng đầu tiên","Cả 12 tháng"],"h1":"Đó là một nửa thời gian của giấy phép.","h2":"Trong 6 tháng đầu tiên của giấy phép tập lái ở Delaware, thiếu niên chỉ được lái xe khi có người giám sát đủ điều kiện.","p":"Đúng. Sáu tháng đầu tiên phải luôn có giám sát."},"tl":{"q":"Sa Delaware, gaano katagal sa simula ng learner's permit puwedeng magmaneho ang teen kasama lang ang supervisor?","o":["Ang unang buwan","Ang unang 6 na buwan","Ang unang 9 na buwan","Ang buong 12 buwan"],"h1":"Kalahati ito ng panahon ng permit.","h2":"Sa unang 6 na buwan ng learner's permit sa Delaware, puwedeng magmaneho ang teen kasama lang ang isang kwalipikadong supervisor.","p":"Tama. Buong supervised ang unang anim na buwan."},"ar":{"q":"في Delaware، في أي مدة من بداية رخصة المتعلم يجوز للمراهق أن يقود فقط مع مشرف؟","o":["الشهر الأول","أول 6 أشهر","أول 9 أشهر","كل الـ 12 شهرًا"],"h1":"إنها نصف مدة الرخصة.","h2":"خلال أول 6 أشهر من رخصة المتعلم في Delaware، يجوز للمراهق أن يقود فقط مع مشرف مؤهَّل.","p":"صحيح. أول ستة أشهر تكون كلها تحت الإشراف."},"ref":{"doc":"DE","page":29}},{"id":"de-009","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, after the supervised period, during which hours may a permit holder drive alone?","o":["Any time of day or night","From 5 a.m. to midnight","From 8 a.m. to 8 p.m.","From 6 a.m. to 10 p.m."],"h1":"Driving alone ends at ten at night.","h2":"After the supervised period, a Delaware permit holder may drive alone from 6 a.m. to 10 p.m.","p":"Right. Alone only from 6 a.m. to 10 p.m."},"es":{"q":"En Delaware, después del período supervisado, ¿en qué horario puede manejar solo el aprendiz?","o":["A cualquier hora del día o de la noche","De 5 a.m. a medianoche","De 8 a.m. a 8 p.m.","De 6 a.m. a 10 p.m."],"h1":"Manejar solo termina a las diez de la noche.","h2":"Después del período supervisado, un aprendiz en Delaware puede manejar solo de 6 a.m. a 10 p.m.","p":"Correcto. Solo de 6 a.m. a 10 p.m."},"zh":{"q":"在 Delaware，监督期过了以后，持学习驾照的人在什么时间可以单独开车？","o":["白天晚上任何时间","早上 5 点到午夜","早上 8 点到晚上 8 点","早上 6 点到晚上 10 点"],"h1":"单独开车在晚上十点结束。","h2":"监督期过了以后，Delaware 持学习驾照的人可以在早上 6 点到晚上 10 点单独开车。","p":"对。只在早上 6 点到晚上 10 点单独开车。"},"vi":{"q":"Ở Delaware, sau giai đoạn có giám sát, người có giấy phép tập lái được lái một mình vào những giờ nào?","o":["Bất cứ lúc nào, ngày hay đêm","Từ 5 a.m. đến nửa đêm","Từ 8 a.m. đến 8 p.m.","Từ 6 a.m. đến 10 p.m."],"h1":"Việc lái một mình kết thúc lúc mười giờ tối.","h2":"Sau giai đoạn có giám sát, người có giấy phép tập lái ở Delaware được lái một mình từ 6 a.m. đến 10 p.m.","p":"Đúng. Chỉ được lái một mình từ 6 a.m. đến 10 p.m."},"tl":{"q":"Sa Delaware, pagkatapos ng supervised na panahon, anong oras puwedeng magmaneho nang mag-isa ang may permit?","o":["Kahit anong oras, araw o gabi","Mula 5 a.m. hanggang hatinggabi","Mula 8 a.m. hanggang 8 p.m.","Mula 6 a.m. hanggang 10 p.m."],"h1":"Natatapos ang pagmamaneho nang mag-isa sa alas-diyes ng gabi.","h2":"Pagkatapos ng supervised na panahon, puwedeng magmaneho nang mag-isa ang may permit sa Delaware mula 6 a.m. hanggang 10 p.m.","p":"Tama. Mag-isa lang mula 6 a.m. hanggang 10 p.m."},"ar":{"q":"في Delaware، بعد فترة الإشراف، في أي ساعات يجوز لحامل رخصة المتعلم أن يقود وحده؟","o":["في أي وقت من النهار أو الليل","من 5 a.m. إلى منتصف الليل","من 8 a.m. إلى 8 p.m.","من 6 a.m. إلى 10 p.m."],"h1":"القيادة وحدك تنتهي في الساعة العاشرة ليلًا.","h2":"بعد فترة الإشراف، يجوز لحامل رخصة المتعلم في Delaware أن يقود وحده من 6 a.m. إلى 10 p.m.","p":"صحيح. القيادة وحدك فقط من 6 a.m. إلى 10 p.m."},"ref":{"doc":"DE","page":30}},{"id":"de-010","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, a permit holder in the unsupervised stage wants to drive alone at 11 p.m. Which trip is allowed?","o":["Going to a friend's party","Driving around for fun","Going home from work","Going to the mall"],"h1":"Think of a job.","h2":"In Delaware, a permit holder may drive alone between 10 p.m. and 6 a.m. only for trips to and from work, church or school activities.","p":"Right. Work trips are an exception at night."},"es":{"q":"En Delaware, un aprendiz en la etapa sin supervisión quiere manejar solo a las 11 p.m. ¿Qué viaje está permitido?","o":["Ir a la fiesta de un amigo","Pasear en carro por diversión","Volver a casa del trabajo","Ir al centro comercial"],"h1":"Piense en un empleo.","h2":"En Delaware, un aprendiz puede manejar solo entre las 10 p.m. y las 6 a.m. solamente para ir o volver del trabajo, de la iglesia o de actividades escolares.","p":"Correcto. Los viajes del trabajo son una excepción de noche."},"zh":{"q":"在 Delaware，处于不需监督阶段的持学习驾照的人想在晚上 11 点单独开车。哪一种行程是允许的？","o":["去朋友的派对","开车兜风","下班回家","去购物中心"],"h1":"想一想工作。","h2":"在 Delaware，持学习驾照的人只有在上下班、去教会或学校活动及回来时，才可以在晚上 10 点到早上 6 点之间单独开车。","p":"对。工作的行程是夜间的例外。"},"vi":{"q":"Ở Delaware, một người có giấy phép tập lái đang ở giai đoạn không giám sát muốn lái một mình lúc 11 p.m. Chuyến đi nào được phép?","o":["Đi dự tiệc của bạn","Lái xe dạo chơi","Đi làm về nhà","Đi đến trung tâm mua sắm"],"h1":"Hãy nghĩ đến một công việc.","h2":"Ở Delaware, người có giấy phép tập lái chỉ được lái một mình từ 10 p.m. đến 6 a.m. khi đi đến hoặc về từ nơi làm việc, nhà thờ hoặc hoạt động của trường.","p":"Đúng. Đi làm là một ngoại lệ vào ban đêm."},"tl":{"q":"Sa Delaware, gustong magmaneho nang mag-isa sa 11 p.m. ang isang may permit na nasa unsupervised na yugto. Aling biyahe ang pinapayagan?","o":["Pagpunta sa party ng kaibigan","Pagmamaneho-maneho para magsaya","Pag-uwi mula sa trabaho","Pagpunta sa mall"],"h1":"Isipin ang trabaho.","h2":"Sa Delaware, puwedeng magmaneho nang mag-isa ang may permit mula 10 p.m. hanggang 6 a.m. para lang sa biyahe papunta at pauwi mula sa trabaho, simbahan o mga aktibidad ng paaralan.","p":"Tama. Exception sa gabi ang biyahe para sa trabaho."},"ar":{"q":"في Delaware، حامل رخصة متعلم في مرحلة القيادة بدون إشراف يريد أن يقود وحده في الساعة 11 p.m. أي رحلة مسموح بها؟","o":["الذهاب إلى حفلة صديق","القيادة في الأنحاء للتسلية","العودة إلى البيت من العمل","الذهاب إلى المركز التجاري"],"h1":"فكّر في الوظيفة.","h2":"في Delaware، يجوز لحامل رخصة المتعلم أن يقود وحده بين 10 p.m. و 6 a.m. فقط للذهاب إلى العمل أو الكنيسة أو أنشطة المدرسة أو العودة منها.","p":"صحيح. رحلات العمل استثناء في الليل."},"ref":{"doc":"DE","page":30}},{"id":"de-011","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, how many passengers may ride with a permit holder, besides the adult supervisor?","o":["One passenger","No passengers","Two passengers","As many as there are seat belts"],"h1":"The number is very small, but not zero.","h2":"A Delaware permit holder may carry no more than one passenger besides the adult supervisor. Immediate family members are the only exception, and only when the adult supervisor is in the car.","p":"Right. Only one other passenger is allowed."},"es":{"q":"En Delaware, ¿cuántos pasajeros pueden viajar con un aprendiz, además del supervisor adulto?","o":["Un pasajero","Ningún pasajero","Dos pasajeros","Tantos como cinturones haya"],"h1":"El número es muy pequeño, pero no es cero.","h2":"Un aprendiz en Delaware puede llevar como máximo un pasajero además del supervisor adulto. Solo los familiares directos son la excepción, y solo cuando el supervisor adulto está en el auto.","p":"Correcto. Solo se permite un pasajero más."},"zh":{"q":"在 Delaware，除了成年监督者以外，持学习驾照的人可以载多少位乘客？","o":["一位乘客","不能载乘客","两位乘客","有几条安全带就载几位"],"h1":"这个数字很小，但不是零。","h2":"Delaware 持学习驾照的人，除了成年监督者以外，最多只能载一位乘客。直系家人是唯一的例外，而且只有成年监督者在车里时才可以。","p":"对。只能再载一位乘客。"},"vi":{"q":"Ở Delaware, ngoài người lớn giám sát, người có giấy phép tập lái được chở bao nhiêu hành khách?","o":["Một hành khách","Không hành khách nào","Hai hành khách","Bằng số dây an toàn trong xe"],"h1":"Con số rất nhỏ, nhưng không phải là không.","h2":"Người có giấy phép tập lái ở Delaware được chở không quá một hành khách ngoài người lớn giám sát. Chỉ người trong gia đình trực hệ là ngoại lệ, và chỉ khi người lớn giám sát có mặt trong xe.","p":"Đúng. Chỉ được chở thêm một hành khách."},"tl":{"q":"Sa Delaware, ilang pasahero ang puwedeng isakay ng may permit, bukod sa adult na supervisor?","o":["Isang pasahero","Walang pasahero","Dalawang pasahero","Kasindami ng seat belt"],"h1":"Napakaliit ng numero, pero hindi zero.","h2":"Ang may permit sa Delaware ay puwedeng magsakay ng hindi hihigit sa isang pasahero bukod sa adult na supervisor. Ang malalapit na miyembro ng pamilya lang ang exception, at kapag nasa sasakyan lang ang adult na supervisor.","p":"Tama. Isang ibang pasahero lang ang pinapayagan."},"ar":{"q":"في Delaware، كم راكبًا يجوز أن يركب مع حامل رخصة المتعلم، غير المشرف البالغ؟","o":["راكب واحد","لا ركاب","راكبان","بعدد أحزمة الأمان"],"h1":"العدد صغير جدًا، لكنه ليس صفرًا.","h2":"يجوز لحامل رخصة المتعلم في Delaware أن يحمل راكبًا واحدًا فقط غير المشرف البالغ. أفراد العائلة المباشرون هم الاستثناء الوحيد، وفقط عندما يكون المشرف البالغ في السيارة.","p":"صحيح. يُسمح براكب آخر واحد فقط."},"ref":{"doc":"DE","page":29}},{"id":"de-012","scope":"DE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Delaware, how may an adult driver talk on a phone while driving?","o":["Holding the phone to the ear","Only with a hands-free device","Only at red lights, holding the phone","Only on highways"],"h1":"Your hands stay off the phone.","h2":"In Delaware, an adult driver may talk on the phone while driving only with a hands-free device.","p":"Right. Delaware bans holding the phone while driving."},"es":{"q":"En Delaware, ¿cómo puede un conductor adulto hablar por teléfono mientras maneja?","o":["Sosteniendo el teléfono en el oído","Solo con un dispositivo de manos libres","Solo en los semáforos en rojo, sosteniendo el teléfono","Solo en las autopistas"],"h1":"Sus manos no tocan el teléfono.","h2":"En Delaware, un conductor adulto puede hablar por teléfono mientras maneja solamente con un dispositivo de manos libres.","p":"Correcto. Delaware prohíbe sostener el teléfono al manejar."},"zh":{"q":"在 Delaware，成年司机开车时可以怎样打电话？","o":["把手机拿在耳边","只能用免持设备","只在红灯时，拿着手机","只在公路上"],"h1":"你的手不碰手机。","h2":"在 Delaware，成年司机开车时只能用免持设备打电话。","p":"对。Delaware 禁止开车时手拿手机。"},"vi":{"q":"Ở Delaware, tài xế người lớn được nói chuyện điện thoại khi lái xe bằng cách nào?","o":["Cầm điện thoại áp vào tai","Chỉ dùng thiết bị rảnh tay (hands-free)","Chỉ khi đèn đỏ, cầm điện thoại","Chỉ trên xa lộ"],"h1":"Tay bạn không cầm điện thoại.","h2":"Ở Delaware, tài xế người lớn chỉ được nói chuyện điện thoại khi lái xe nếu dùng thiết bị rảnh tay.","p":"Đúng. Delaware cấm cầm điện thoại khi lái xe."},"tl":{"q":"Sa Delaware, paano puwedeng makipag-usap sa telepono ang adult na driver habang nagmamaneho?","o":["Hawak ang telepono sa tainga","Gamit lang ang hands-free na device","Sa red light lang, hawak ang telepono","Sa highway lang"],"h1":"Hindi hawak ng iyong kamay ang telepono.","h2":"Sa Delaware, puwedeng makipag-usap sa telepono ang adult na driver habang nagmamaneho gamit lang ang hands-free na device.","p":"Tama. Bawal sa Delaware ang paghawak ng telepono habang nagmamaneho."},"ar":{"q":"في Delaware، كيف يجوز للسائق البالغ أن يتكلم في الهاتف أثناء القيادة؟","o":["وهو يمسك الهاتف على أذنه","فقط بجهاز لا يحتاج إلى اليدين (hands-free)","فقط عند الإشارة الحمراء، وهو يمسك الهاتف","فقط على الطرق السريعة"],"h1":"يداك لا تمسكان الهاتف.","h2":"في Delaware، يجوز للسائق البالغ أن يتكلم في الهاتف أثناء القيادة فقط بجهاز لا يحتاج إلى اليدين.","p":"صحيح. تمنع Delaware إمساك الهاتف أثناء القيادة."},"ref":{"doc":"DE","page":81}},{"id":"de-013","scope":"DE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Delaware, what blood alcohol level is illegal for a driver under 21?","o":["0.08 percent or more","0.02 percent or more","0.05 percent or more","0.10 percent or more"],"h1":"It is much lower than the adult limit.","h2":"In Delaware, a driver under 21 with a blood alcohol level of 0.02 percent or more loses the license under the zero tolerance law.","p":"Right. The limit under 21 is 0.02 percent."},"es":{"q":"En Delaware, ¿qué nivel de alcohol en la sangre es ilegal para un conductor menor de 21 años?","o":["0.08 por ciento o más","0.02 por ciento o más","0.05 por ciento o más","0.10 por ciento o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Delaware, un conductor menor de 21 años con un nivel de alcohol en la sangre de 0.02 por ciento o más pierde la licencia por la ley de tolerancia cero.","p":"Correcto. El límite para menores de 21 es 0.02 por ciento."},"zh":{"q":"在 Delaware，21 岁以下的司机血液酒精浓度达到多少是违法的？","o":["0.08% 或更高","0.02% 或更高","0.05% 或更高","0.10% 或更高"],"h1":"它比成年人的限制低很多。","h2":"在 Delaware，根据零容忍法，21 岁以下的司机血液酒精浓度达到 0.02% 或更高，就会失去驾照。","p":"对。21 岁以下的限制是 0.02%。"},"vi":{"q":"Ở Delaware, nồng độ cồn trong máu bao nhiêu là bất hợp pháp đối với tài xế dưới 21 tuổi?","o":["0.08 phần trăm trở lên","0.02 phần trăm trở lên","0.05 phần trăm trở lên","0.10 phần trăm trở lên"],"h1":"Nó thấp hơn nhiều so với giới hạn của người lớn.","h2":"Ở Delaware, tài xế dưới 21 tuổi có nồng độ cồn trong máu từ 0.02 phần trăm trở lên sẽ bị mất bằng lái theo luật không khoan nhượng (zero tolerance).","p":"Đúng. Giới hạn cho người dưới 21 tuổi là 0.02 phần trăm."},"tl":{"q":"Sa Delaware, anong blood alcohol level ang ilegal para sa driver na wala pang 21 taong gulang?","o":["0.08 porsiyento o higit pa","0.02 porsiyento o higit pa","0.05 porsiyento o higit pa","0.10 porsiyento o higit pa"],"h1":"Mas mababa ito nang malaki kaysa sa limit para sa adult.","h2":"Sa Delaware, mawawalan ng lisensya ang driver na wala pang 21 taong gulang na may blood alcohol level na 0.02 porsiyento o higit pa, ayon sa zero tolerance law.","p":"Tama. 0.02 porsiyento ang limit para sa wala pang 21."},"ar":{"q":"في Delaware، ما نسبة الكحول في الدم غير القانونية للسائق الذي عمره أقل من 21 سنة؟","o":["0.08 في المئة أو أكثر","0.02 في المئة أو أكثر","0.05 في المئة أو أكثر","0.10 في المئة أو أكثر"],"h1":"إنها أقل بكثير من الحد المسموح للبالغين.","h2":"في Delaware، السائق الذي عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02 في المئة أو أكثر يفقد رخصته حسب قانون عدم التسامح (zero tolerance).","p":"صحيح. الحد لمن هم أقل من 21 سنة هو 0.02 في المئة."},"ref":{"doc":"DE","page":50}},{"id":"de-014","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, how soon after passing the knowledge test can you take the car road test?","o":["The same day","30 days later","6 months later","1 year later"],"h1":"You need some time to practice first, about one month.","h2":"In Delaware you can take the Class D road test 30 days after you pass the knowledge test.","p":"Right. Delaware makes you wait 30 days before the road test."},"es":{"q":"En Delaware, ¿cuánto tiempo después de aprobar el examen teórico puede tomar el examen de manejo en carro?","o":["El mismo día","30 días después","6 meses después","1 año después"],"h1":"Usted necesita tiempo para practicar primero, más o menos un mes.","h2":"En Delaware usted puede tomar el examen de manejo de Clase D 30 días después de aprobar el examen teórico.","p":"Correcto. En Delaware hay que esperar 30 días antes del examen de manejo."},"zh":{"q":"在 Delaware，通过笔试以后，最快多久可以参加汽车路考？","o":["同一天","30 天以后","6 个月以后","1 年以后"],"h1":"你需要先练习一段时间，大约一个月。","h2":"在 Delaware，你通过笔试 30 天以后，可以参加 Class D 路考。","p":"对。Delaware 要你等 30 天才能路考。"},"vi":{"q":"Ở Delaware, sau khi đậu bài thi kiến thức bao lâu thì bạn có thể thi lái xe trên đường?","o":["Ngay trong ngày","30 ngày sau","6 tháng sau","1 năm sau"],"h1":"Bạn cần thời gian để tập trước, khoảng một tháng.","h2":"Ở Delaware, bạn có thể thi lái xe Class D trên đường 30 ngày sau khi đậu bài thi kiến thức.","p":"Đúng. Delaware bắt bạn chờ 30 ngày trước khi thi lái trên đường."},"tl":{"q":"Sa Delaware, gaano kabilis pagkatapos pumasa sa knowledge test puwede kang kumuha ng road test sa kotse?","o":["Sa parehong araw","30 araw pagkatapos","6 na buwan pagkatapos","1 taon pagkatapos"],"h1":"Kailangan mo munang magsanay nang ilang panahon, mga isang buwan.","h2":"Sa Delaware, puwede kang kumuha ng Class D road test 30 araw pagkatapos mong pumasa sa knowledge test.","p":"Tama. Pinaghihintay ka ng Delaware nang 30 araw bago ang road test."},"ar":{"q":"في Delaware، بعد كم من الوقت من نجاحك في الاختبار النظري يمكنك أن تأخذ اختبار القيادة على الطريق بالسيارة؟","o":["في اليوم نفسه","بعد 30 يومًا","بعد 6 أشهر","بعد سنة واحدة"],"h1":"تحتاج إلى بعض الوقت للتدريب أولًا، حوالي شهر.","h2":"في Delaware يمكنك أن تأخذ اختبار القيادة على الطريق لرخصة Class D بعد 30 يومًا من نجاحك في الاختبار النظري.","p":"صحيح. تجعلك Delaware تنتظر 30 يومًا قبل اختبار الطريق."},"ref":{"doc":"DE","page":41}},{"id":"de-015","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, what does the DMV do when a driver reaches 8 points within two years?","o":["Takes away the license for a year","Sends the driver to jail","Takes away the car","Sends the driver a warning letter"],"h1":"At 8 points the first step is gentle.","h2":"In Delaware, when a driver reaches 8 points within two years, the DMV sends the driver an advisory letter as a warning.","p":"Right. At 8 points Delaware sends a warning letter first."},"es":{"q":"En Delaware, ¿qué hace el DMV cuando un conductor llega a 8 puntos en dos años?","o":["Le quita la licencia por un año","Manda al conductor a la cárcel","Le quita el carro","Le envía al conductor una carta de advertencia"],"h1":"Con 8 puntos, el primer paso es suave.","h2":"En Delaware, cuando un conductor llega a 8 puntos en dos años, el DMV le envía una carta de advertencia.","p":"Correcto. Con 8 puntos, Delaware primero envía una carta de advertencia."},"zh":{"q":"在 Delaware，司机在两年内累积到 8 分时，DMV 会怎么做？","o":["吊销驾照一年","把司机送进监狱","没收汽车","寄给司机一封警告信"],"h1":"到 8 分时，第一步是温和的。","h2":"在 Delaware，司机在两年内累积到 8 分时，DMV 会寄给司机一封提醒信作为警告。","p":"对。到 8 分时，Delaware 先寄警告信。"},"vi":{"q":"Ở Delaware, DMV làm gì khi một tài xế bị 8 điểm trong vòng hai năm?","o":["Lấy bằng lái trong một năm","Đưa tài xế vào tù","Lấy xe đi","Gửi cho tài xế một thư cảnh cáo"],"h1":"Ở mức 8 điểm, bước đầu tiên là nhẹ nhàng.","h2":"Ở Delaware, khi một tài xế bị 8 điểm trong vòng hai năm, DMV gửi cho tài xế một thư nhắc nhở để cảnh cáo.","p":"Đúng. Ở mức 8 điểm, Delaware gửi thư cảnh cáo trước."},"tl":{"q":"Sa Delaware, ano ang ginagawa ng DMV kapag umabot sa 8 puntos ang isang driver sa loob ng dalawang taon?","o":["Kinukuha ang lisensya nang isang taon","Ipinapakulong ang driver","Kinukuha ang kotse","Pinapadalhan ang driver ng sulat ng babala"],"h1":"Sa 8 puntos, banayad ang unang hakbang.","h2":"Sa Delaware, kapag umabot sa 8 puntos ang isang driver sa loob ng dalawang taon, pinapadalhan siya ng DMV ng advisory letter bilang babala.","p":"Tama. Sa 8 puntos, sulat ng babala muna ang ipinapadala ng Delaware."},"ar":{"q":"في Delaware، ماذا تفعل DMV عندما يصل السائق إلى 8 نقاط خلال سنتين؟","o":["تسحب الرخصة لمدة سنة","ترسل السائق إلى السجن","تأخذ السيارة","ترسل إلى السائق رسالة تحذير"],"h1":"عند 8 نقاط تكون الخطوة الأولى خفيفة.","h2":"في Delaware، عندما يصل السائق إلى 8 نقاط خلال سنتين، ترسل DMV إلى السائق رسالة تنبيه كتحذير.","p":"صحيح. عند 8 نقاط ترسل Delaware رسالة تحذير أولًا."},"ref":{"doc":"DE","page":47}},{"id":"de-016","scope":"DE","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Delaware, a school bus is stopped with red lights flashing on the other side of a road with four or more lanes. What do you do?","o":["Stop and wait until the lights go off","Speed up to pass quickly","You do not have to stop, but go slowly","Honk and keep driving at the same speed"],"h1":"On a wide road, the rule is different for traffic going the other way.","h2":"In Delaware, if you are on the opposite side of a road with four or more lanes, you do not have to stop for the school bus, but you must go slowly.","p":"Right. On a road with four or more lanes, oncoming traffic may pass slowly."},"es":{"q":"En Delaware, un autobús escolar está detenido con luces rojas intermitentes al otro lado de una carretera de cuatro carriles o más. ¿Qué hace usted?","o":["Se detiene y espera a que se apaguen las luces","Acelera para pasar rápido","No tiene que detenerse, pero pasa despacio","Toca la bocina y sigue a la misma velocidad"],"h1":"En una carretera ancha, la regla es diferente para el tráfico que va en sentido contrario.","h2":"En Delaware, si usted está del lado opuesto de una carretera de cuatro carriles o más, no tiene que detenerse por el autobús escolar, pero debe pasar despacio.","p":"Correcto. En una carretera de cuatro carriles o más, el tráfico en sentido contrario puede pasar despacio."},"zh":{"q":"在 Delaware，一辆校车在四车道或更多车道道路的另一边停着，红灯在闪。你该怎么做？","o":["停车，等到灯熄灭","加速快点开过去","你不必停车，但要慢慢开","按喇叭，用同样速度继续开"],"h1":"在宽的道路上，对向车辆的规定不一样。","h2":"在 Delaware，如果你在四车道或更多车道道路的对面，你不必为校车停车，但必须慢慢开。","p":"对。在四车道或更多车道的道路上，对向车辆可以慢慢开过去。"},"vi":{"q":"Ở Delaware, một xe buýt trường học đang dừng và nháy đèn đỏ ở phía bên kia của con đường có bốn làn xe trở lên. Bạn làm gì?","o":["Dừng lại và chờ đến khi đèn tắt","Tăng tốc để vượt qua nhanh","Bạn không phải dừng, nhưng phải chạy chậm","Bấm còi và tiếp tục chạy cùng tốc độ"],"h1":"Trên đường rộng, quy định khác đối với xe chạy ngược chiều.","h2":"Ở Delaware, nếu bạn ở phía bên kia của con đường có bốn làn xe trở lên, bạn không phải dừng lại vì xe buýt trường học, nhưng bạn phải chạy chậm.","p":"Đúng. Trên đường có bốn làn xe trở lên, xe chạy ngược chiều có thể chạy chậm qua."},"tl":{"q":"Sa Delaware, may school bus na nakahinto at kumikislap ang pulang ilaw sa kabilang panig ng kalsadang may apat o higit pang lane. Ano ang gagawin mo?","o":["Huminto at maghintay hanggang mamatay ang mga ilaw","Bilisan para makalampas agad","Hindi mo kailangang huminto, pero dahan-dahan ka","Bumusina at magpatuloy sa parehong bilis"],"h1":"Sa malapad na kalsada, iba ang patakaran para sa trapikong papunta sa kabilang direksyon.","h2":"Sa Delaware, kung nasa kabilang panig ka ng kalsadang may apat o higit pang lane, hindi mo kailangang huminto para sa school bus, pero dapat kang magdahan-dahan.","p":"Tama. Sa kalsadang may apat o higit pang lane, puwedeng dumaan nang dahan-dahan ang paparating na trapiko."},"ar":{"q":"في Delaware، حافلة مدرسية متوقفة وأضواؤها الحمراء تومض على الجانب الآخر من طريق فيه أربعة مسارات أو أكثر. ماذا تفعل؟","o":["تتوقف وتنتظر حتى تنطفئ الأضواء","تسرع لتمر بسرعة","ليس عليك أن تتوقف، لكن سِر ببطء","تطلق البوق وتستمر بالسرعة نفسها"],"h1":"على الطريق العريض، القاعدة مختلفة للسيارات القادمة من الاتجاه الآخر.","h2":"في Delaware، إذا كنت على الجانب المقابل من طريق فيه أربعة مسارات أو أكثر، فليس عليك أن تتوقف للحافلة المدرسية، لكن يجب أن تسير ببطء.","p":"صحيح. على طريق فيه أربعة مسارات أو أكثر، يجوز للسيارات القادمة من الاتجاه المقابل أن تمر ببطء."},"ref":{"doc":"DE","page":89}},{"id":"de-017","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, for how long is your license suspended the first time you are convicted of passing a stopped school bus?","o":["1 month","1 week","3 years","It is never suspended"],"h1":"It is a short time, but you cannot drive at all during it.","h2":"In Delaware, the first conviction for passing a stopped school bus brings a one-month license suspension. A fine, jail time, or both may also apply.","p":"Right. A first offense means one month without a license."},"es":{"q":"En Delaware, ¿por cuánto tiempo se suspende su licencia la primera vez que lo condenan por pasar un autobús escolar detenido?","o":["1 mes","1 semana","3 años","Nunca se suspende"],"h1":"Es poco tiempo, pero usted no puede manejar nada durante ese tiempo.","h2":"En Delaware, la primera condena por pasar un autobús escolar detenido trae una suspensión de la licencia de un mes. También puede haber una multa, cárcel o ambas.","p":"Correcto. La primera vez, usted pierde la licencia por un mes."},"zh":{"q":"在 Delaware，你第一次因为超过停着的校车被定罪，驾照会被暂停多久？","o":["1 个月","1 个星期","3 年","永远不会被暂停"],"h1":"时间不长，但在这段时间里你完全不能开车。","h2":"在 Delaware，第一次因为超过停着的校车被定罪，驾照会被暂停一个月。也可能会被罚款、坐牢，或两者都有。","p":"对。第一次违规就是一个月没有驾照。"},"vi":{"q":"Ở Delaware, lần đầu tiên bạn bị kết án vì vượt qua xe buýt trường học đang dừng, bằng lái của bạn bị treo trong bao lâu?","o":["1 tháng","1 tuần","3 năm","Không bao giờ bị treo"],"h1":"Đó là một thời gian ngắn, nhưng trong thời gian đó bạn hoàn toàn không được lái xe.","h2":"Ở Delaware, lần đầu tiên bị kết án vì vượt qua xe buýt trường học đang dừng, bằng lái của bạn bị treo một tháng. Bạn cũng có thể bị phạt tiền, bị ở tù, hoặc cả hai.","p":"Đúng. Vi phạm lần đầu nghĩa là một tháng không có bằng lái."},"tl":{"q":"Sa Delaware, gaano katagal masususpinde ang lisensiya mo sa unang beses na ma-convict ka sa paglampas sa nakahintong school bus?","o":["1 buwan","1 linggo","3 taon","Hindi ito sinususpinde kailanman"],"h1":"Maikling panahon ito, pero hindi ka talaga puwedeng magmaneho habang tumatagal ito.","h2":"Sa Delaware, ang unang conviction sa paglampas sa nakahintong school bus ay may isang buwang suspensiyon ng lisensiya. Puwede ring may multa, kulong, o pareho.","p":"Tama. Sa unang paglabag, isang buwan kang walang lisensiya."},"ar":{"q":"في Delaware، كم مدة إيقاف رخصتك في أول مرة تُدان فيها بتجاوز حافلة مدرسية متوقفة؟","o":["شهر واحد","أسبوع واحد","3 سنوات","لا يتم إيقافها أبدًا"],"h1":"إنها مدة قصيرة، لكنك لا تستطيع القيادة أبدًا خلالها.","h2":"في Delaware، أول إدانة بتجاوز حافلة مدرسية متوقفة تؤدي إلى إيقاف الرخصة لمدة شهر واحد. وقد تكون هناك أيضًا غرامة أو سجن أو كلاهما.","p":"صحيح. المخالفة الأولى تعني شهرًا واحدًا بدون رخصة."},"ref":{"doc":"DE","page":90}},{"id":"de-018","scope":"DE","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Delaware, when must your headlights be on during the day?","o":["Only when you drive on a highway","Only when you drive over 55 mph","Any time your windshield wipers are on","Only when the radio says it is cloudy"],"h1":"Think about rain.","h2":"In Delaware, your headlights must be on any time you use your windshield wipers, even during the day.","p":"Right. Wipers on means headlights on in Delaware."},"es":{"q":"En Delaware, ¿cuándo debe tener las luces delanteras encendidas durante el día?","o":["Solo cuando maneja en la autopista","Solo cuando maneja a más de 55 mph","Cada vez que usa los limpiaparabrisas","Solo cuando la radio dice que está nublado"],"h1":"Piense en la lluvia.","h2":"En Delaware, sus luces delanteras deben estar encendidas cada vez que usa los limpiaparabrisas, aunque sea de día.","p":"Correcto. En Delaware, si usa los limpiaparabrisas, enciende las luces."},"zh":{"q":"在 Delaware，白天什么时候必须开大灯？","o":["只有在公路上开车时","只有车速超过 55 mph 时","只要开着雨刷的时候","只有收音机说是阴天时"],"h1":"想一想下雨。","h2":"在 Delaware，只要你用雨刷，即使是白天，也必须开大灯。","p":"对。在 Delaware，开雨刷就要开大灯。"},"vi":{"q":"Ở Delaware, khi nào bạn phải bật đèn pha vào ban ngày?","o":["Chỉ khi bạn lái trên xa lộ","Chỉ khi bạn lái nhanh hơn 55 mph","Bất cứ khi nào cần gạt nước đang bật","Chỉ khi radio nói trời nhiều mây"],"h1":"Hãy nghĩ đến trời mưa.","h2":"Ở Delaware, bạn phải bật đèn pha bất cứ khi nào bạn dùng cần gạt nước, kể cả vào ban ngày.","p":"Đúng. Ở Delaware, bật cần gạt nước thì phải bật đèn pha."},"tl":{"q":"Sa Delaware, kailan dapat nakabukas ang headlights mo sa araw?","o":["Kapag nagmamaneho ka lang sa highway","Kapag lampas 55 mph lang ang takbo mo","Tuwing nakabukas ang windshield wipers mo","Kapag sinabi lang ng radyo na maulap"],"h1":"Isipin ang ulan.","h2":"Sa Delaware, dapat nakabukas ang headlights mo tuwing ginagamit mo ang windshield wipers, kahit sa araw.","p":"Tama. Sa Delaware, kapag bukas ang wipers, dapat bukas din ang headlights."},"ar":{"q":"في Delaware، متى يجب أن تكون أضواء سيارتك الأمامية مضاءة أثناء النهار؟","o":["فقط عندما تقود على طريق سريع","فقط عندما تقود بسرعة أكثر من 55 mph","في أي وقت تكون فيه مسّاحات الزجاج الأمامي شغّالة","فقط عندما يقول الراديو إن الجو غائم"],"h1":"فكّر في المطر.","h2":"في Delaware، يجب أن تكون أضواؤك الأمامية مضاءة في أي وقت تستعمل فيه مسّاحات الزجاج الأمامي، حتى أثناء النهار.","p":"صحيح. في Delaware، تشغيل المسّاحات يعني تشغيل الأضواء الأمامية."},"ref":{"doc":"DE","page":62}},{"id":"de-019","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, what is the least Personal Injury Protection (PIP) insurance a car must have for one person?","o":["$5,000","$15,000","$50,000","$100,000"],"h1":"It is less than $25,000.","h2":"In Delaware, car insurance must include at least $15,000 of Personal Injury Protection (PIP) for one person, and $30,000 for everyone hurt in one crash.","p":"Right. Delaware requires at least $15,000 of PIP for each person."},"es":{"q":"En Delaware, ¿cuál es el mínimo de seguro de Protección contra Lesiones Personales (PIP) que debe tener un carro por cada persona?","o":["$5,000","$15,000","$50,000","$100,000"],"h1":"Es menos de $25,000.","h2":"En Delaware, el seguro del carro debe incluir por lo menos $15,000 de Protección contra Lesiones Personales (PIP) por persona, y $30,000 para todos los heridos en un choque.","p":"Correcto. Delaware exige por lo menos $15,000 de PIP por persona."},"zh":{"q":"在 Delaware，一辆车对每个人最少要有多少人身伤害保护（PIP）保险？","o":["$5,000","$15,000","$50,000","$100,000"],"h1":"它少于 $25,000。","h2":"在 Delaware，汽车保险必须包括每人至少 $15,000 的人身伤害保护（PIP），以及一次车祸中所有受伤的人合计 $30,000。","p":"对。Delaware 要求每人至少 $15,000 的 PIP。"},"vi":{"q":"Ở Delaware, mỗi xe phải có bảo hiểm Bảo vệ Thương tích Cá nhân (PIP) ít nhất bao nhiêu cho một người?","o":["$5,000","$15,000","$50,000","$100,000"],"h1":"Số tiền này ít hơn $25,000.","h2":"Ở Delaware, bảo hiểm xe phải có ít nhất $15,000 Bảo vệ Thương tích Cá nhân (PIP) cho một người, và $30,000 cho tất cả những người bị thương trong một vụ tai nạn.","p":"Đúng. Delaware yêu cầu ít nhất $15,000 PIP cho mỗi người."},"tl":{"q":"Sa Delaware, ano ang pinakamababang Personal Injury Protection (PIP) insurance na dapat mayroon ang kotse para sa isang tao?","o":["$5,000","$15,000","$50,000","$100,000"],"h1":"Mas mababa ito sa $25,000.","h2":"Sa Delaware, dapat may hindi bababa sa $15,000 na Personal Injury Protection (PIP) ang car insurance para sa isang tao, at $30,000 para sa lahat ng nasaktan sa isang aksidente.","p":"Tama. Hinihingi ng Delaware ang hindi bababa sa $15,000 na PIP para sa bawat tao."},"ar":{"q":"في Delaware، ما أقل تأمين حماية من الإصابات الشخصية (PIP) يجب أن يكون للسيارة لشخص واحد؟","o":["$5,000","$15,000","$50,000","$100,000"],"h1":"إنه أقل من $25,000.","h2":"في Delaware، يجب أن يشمل تأمين السيارة $15,000 على الأقل من الحماية من الإصابات الشخصية (PIP) لشخص واحد، و $30,000 لكل المصابين في حادث واحد.","p":"صحيح. تطلب Delaware ما لا يقل عن $15,000 من PIP لكل شخص."},"ref":{"doc":"DE","page":63}},{"id":"de-020","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, what is the smallest fine for driving a car with no insurance the first time?","o":["$50","$100","$500","$1,500"],"h1":"The fine is very high, more than $1,000.","h2":"In Delaware, the fine for driving an uninsured car is at least $1,500 for a first offense, and up to $2,000.","p":"Right. Driving without insurance costs at least $1,500 in Delaware."},"es":{"q":"En Delaware, ¿cuál es la multa más baja por manejar un carro sin seguro la primera vez?","o":["$50","$100","$500","$1,500"],"h1":"La multa es muy alta, más de $1,000.","h2":"En Delaware, la multa por manejar un carro sin seguro es de por lo menos $1,500 la primera vez, y puede llegar a $2,000.","p":"Correcto. Manejar sin seguro cuesta por lo menos $1,500 en Delaware."},"zh":{"q":"在 Delaware，第一次开没有保险的车，最低罚款是多少？","o":["$50","$100","$500","$1,500"],"h1":"罚款很高，超过 $1,000。","h2":"在 Delaware，第一次开没有保险的车，罚款至少 $1,500，最高 $2,000。","p":"对。在 Delaware，开没有保险的车至少要罚 $1,500。"},"vi":{"q":"Ở Delaware, tiền phạt thấp nhất khi lái xe không có bảo hiểm lần đầu là bao nhiêu?","o":["$50","$100","$500","$1,500"],"h1":"Tiền phạt rất cao, hơn $1,000.","h2":"Ở Delaware, tiền phạt khi lái xe không có bảo hiểm lần đầu là ít nhất $1,500, và có thể lên đến $2,000.","p":"Đúng. Ở Delaware, lái xe không có bảo hiểm bị phạt ít nhất $1,500."},"tl":{"q":"Sa Delaware, ano ang pinakamababang multa sa unang beses na pagmamaneho ng kotseng walang insurance?","o":["$50","$100","$500","$1,500"],"h1":"Napakataas ng multa, higit sa $1,000.","h2":"Sa Delaware, ang multa sa pagmamaneho ng kotseng walang insurance ay hindi bababa sa $1,500 sa unang paglabag, at hanggang $2,000.","p":"Tama. Sa Delaware, hindi bababa sa $1,500 ang multa sa pagmamaneho nang walang insurance."},"ar":{"q":"في Delaware، ما أقل غرامة لقيادة سيارة بدون تأمين في المرة الأولى؟","o":["$50","$100","$500","$1,500"],"h1":"الغرامة عالية جدًا، أكثر من $1,000.","h2":"في Delaware، غرامة قيادة سيارة بدون تأمين هي $1,500 على الأقل في المخالفة الأولى، وقد تصل إلى $2,000.","p":"صحيح. القيادة بدون تأمين تكلّف $1,500 على الأقل في Delaware."},"ref":{"doc":"DE","page":63}},{"id":"de-021","scope":"DE","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Delaware, if no other limit is posted, what is the speed limit on a two-lane road?","o":["50 mph","35 mph","60 mph","70 mph"],"h1":"It is lower than the limit on divided roads, which is 55 mph.","h2":"In Delaware, the speed limit on a two-lane road is 50 mph unless a sign shows a different limit.","p":"Right. Two-lane roads in Delaware have a 50 mph limit."},"es":{"q":"En Delaware, si no hay otro límite señalado, ¿cuál es el límite de velocidad en una carretera de dos carriles?","o":["50 mph","35 mph","60 mph","70 mph"],"h1":"Es menor que el límite en carreteras divididas, que es de 55 mph.","h2":"En Delaware, el límite de velocidad en una carretera de dos carriles es de 50 mph, a menos que una señal indique otro límite.","p":"Correcto. En Delaware las carreteras de dos carriles tienen un límite de 50 mph."},"zh":{"q":"在 Delaware，如果没有标示其他限速，双车道道路的限速是多少？","o":["50 mph","35 mph","60 mph","70 mph"],"h1":"它比有中间分隔的道路的限速 55 mph 低。","h2":"在 Delaware，除非标志显示别的限速，双车道道路的限速是 50 mph。","p":"对。Delaware 双车道道路的限速是 50 mph。"},"vi":{"q":"Ở Delaware, nếu không có biển báo giới hạn khác, giới hạn tốc độ trên đường hai làn là bao nhiêu?","o":["50 mph","35 mph","60 mph","70 mph"],"h1":"Nó thấp hơn giới hạn trên đường có dải phân cách, là 55 mph.","h2":"Ở Delaware, giới hạn tốc độ trên đường hai làn là 50 mph, trừ khi có biển báo cho thấy giới hạn khác.","p":"Đúng. Đường hai làn ở Delaware có giới hạn 50 mph."},"tl":{"q":"Sa Delaware, kung walang ibang limit na nakapaskil, ano ang speed limit sa kalsadang may dalawang lane?","o":["50 mph","35 mph","60 mph","70 mph"],"h1":"Mas mababa ito kaysa sa limit sa mga divided road, na 55 mph.","h2":"Sa Delaware, 50 mph ang speed limit sa kalsadang may dalawang lane, maliban kung may karatulang nagpapakita ng ibang limit.","p":"Tama. 50 mph ang limit sa mga kalsadang may dalawang lane sa Delaware."},"ar":{"q":"في Delaware، إذا لم يُكتب حد آخر، ما حد السرعة على طريق فيه مساران؟","o":["50 mph","35 mph","60 mph","70 mph"],"h1":"إنه أقل من الحد على الطرق المقسومة، وهو 55 mph.","h2":"في Delaware، حد السرعة على طريق فيه مساران هو 50 mph، إلا إذا كانت هناك لافتة تُظهر حدًا مختلفًا.","p":"صحيح. الطرق ذات المسارين في Delaware حدها 50 mph."},"ref":{"doc":"DE","page":93}},{"id":"de-022","scope":"DE","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Delaware, what is the speed limit in a school zone when children are present?","o":["10 mph","15 mph","20 mph","30 mph"],"h1":"It is a little lower than the 25 mph limit in neighborhoods.","h2":"In Delaware, the speed limit in a school zone when children are present is 20 mph.","p":"Right. Slow to 20 mph in a Delaware school zone."},"es":{"q":"En Delaware, ¿cuál es el límite de velocidad en una zona escolar cuando hay niños presentes?","o":["10 mph","15 mph","20 mph","30 mph"],"h1":"Es un poco menos que el límite de 25 mph en los vecindarios.","h2":"En Delaware, el límite de velocidad en una zona escolar cuando hay niños presentes es de 20 mph.","p":"Correcto. En una zona escolar de Delaware, baje a 20 mph."},"zh":{"q":"在 Delaware，有孩子在场时，学校区域的限速是多少？","o":["10 mph","15 mph","20 mph","30 mph"],"h1":"它比住宅区的 25 mph 限速低一点。","h2":"在 Delaware，有孩子在场时，学校区域的限速是 20 mph。","p":"对。在 Delaware 的学校区域要减速到 20 mph。"},"vi":{"q":"Ở Delaware, giới hạn tốc độ trong khu vực trường học khi có trẻ em là bao nhiêu?","o":["10 mph","15 mph","20 mph","30 mph"],"h1":"Nó thấp hơn một chút so với giới hạn 25 mph trong khu dân cư.","h2":"Ở Delaware, giới hạn tốc độ trong khu vực trường học khi có trẻ em là 20 mph.","p":"Đúng. Giảm xuống 20 mph trong khu vực trường học ở Delaware."},"tl":{"q":"Sa Delaware, ano ang speed limit sa school zone kapag may mga bata?","o":["10 mph","15 mph","20 mph","30 mph"],"h1":"Medyo mas mababa ito kaysa sa 25 mph na limit sa mga neighborhood.","h2":"Sa Delaware, 20 mph ang speed limit sa school zone kapag may mga bata.","p":"Tama. Bagalan sa 20 mph sa school zone sa Delaware."},"ar":{"q":"في Delaware، ما حد السرعة في منطقة المدرسة عندما يكون الأطفال موجودين؟","o":["10 mph","15 mph","20 mph","30 mph"],"h1":"إنه أقل قليلًا من حد 25 mph في الأحياء السكنية.","h2":"في Delaware، حد السرعة في منطقة المدرسة عندما يكون الأطفال موجودين هو 20 mph.","p":"صحيح. خفّف سرعتك إلى 20 mph في منطقة المدرسة في Delaware."},"ref":{"doc":"DE","page":93}},{"id":"de-023","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, a driver under 21 is caught driving after drinking alcohol. For a first offense, how long is the license revoked?","o":["1 week","2 months","5 years","It is not revoked"],"h1":"It is more than a few weeks but less than half a year.","h2":"Under Delaware's zero tolerance law, a driver under 21 who drives after drinking loses the license for two months for a first offense.","p":"Right. A first zero tolerance offense means two months without a license."},"es":{"q":"En Delaware, descubren a un conductor menor de 21 años manejando después de tomar alcohol. Si es la primera vez, ¿por cuánto tiempo le revocan la licencia?","o":["1 semana","2 meses","5 años","No se la revocan"],"h1":"Es más de unas semanas, pero menos de medio año.","h2":"Según la ley de tolerancia cero de Delaware, un conductor menor de 21 años que maneja después de tomar alcohol pierde la licencia por dos meses la primera vez.","p":"Correcto. La primera vez, la tolerancia cero significa dos meses sin licencia."},"zh":{"q":"在 Delaware，一个 21 岁以下的司机被发现喝酒后开车。第一次违规，驾照会被吊销多久？","o":["1 个星期","2 个月","5 年","不会被吊销"],"h1":"它比几个星期长，但比半年短。","h2":"根据 Delaware 的零容忍法，21 岁以下的司机喝酒后开车，第一次违规会失去驾照两个月。","p":"对。第一次零容忍违规就是两个月没有驾照。"},"vi":{"q":"Ở Delaware, một tài xế dưới 21 tuổi bị bắt khi lái xe sau khi uống rượu. Với vi phạm lần đầu, bằng lái bị thu hồi trong bao lâu?","o":["1 tuần","2 tháng","5 năm","Không bị thu hồi"],"h1":"Nó dài hơn vài tuần nhưng ngắn hơn nửa năm.","h2":"Theo luật không khoan nhượng (zero tolerance) của Delaware, tài xế dưới 21 tuổi lái xe sau khi uống rượu sẽ bị mất bằng lái hai tháng cho vi phạm lần đầu.","p":"Đúng. Vi phạm zero tolerance lần đầu nghĩa là hai tháng không có bằng lái."},"tl":{"q":"Sa Delaware, nahuli ang isang driver na wala pang 21 taong gulang na nagmamaneho pagkatapos uminom ng alak. Sa unang paglabag, gaano katagal binabawi ang lisensya?","o":["1 linggo","2 buwan","5 taon","Hindi ito binabawi"],"h1":"Mas mahaba ito sa ilang linggo pero mas maikli sa kalahating taon.","h2":"Ayon sa zero tolerance law ng Delaware, ang driver na wala pang 21 taong gulang na nagmaneho pagkatapos uminom ay mawawalan ng lisensya nang dalawang buwan sa unang paglabag.","p":"Tama. Sa unang zero tolerance na paglabag, dalawang buwan kang walang lisensya."},"ar":{"q":"في Delaware، تم ضبط سائق عمره أقل من 21 سنة يقود بعد شرب الكحول. في المخالفة الأولى، كم مدة سحب الرخصة؟","o":["أسبوع واحد","شهران","5 سنوات","لا تُسحب"],"h1":"إنها أكثر من بضعة أسابيع لكن أقل من نصف سنة.","h2":"حسب قانون عدم التسامح (zero tolerance) في Delaware، السائق الذي عمره أقل من 21 سنة ويقود بعد الشرب يفقد رخصته لمدة شهرين في المخالفة الأولى.","p":"صحيح. المخالفة الأولى لقانون عدم التسامح تعني شهرين بدون رخصة."},"ref":{"doc":"DE","page":54}},{"id":"de-024","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, a crash on a public road causes property damage but no injuries. At what amount of damage must you report it to the police?","o":["$50 or more","$100 or more","$5,000 or more","$500 or more"],"h1":"It is a few hundred dollars.","h2":"In Delaware, you must report a crash on a public road to the police when the property damage looks like $500 or more.","p":"Right. Report crashes with $500 or more in damage in Delaware."},"es":{"q":"En Delaware, un choque en una vía pública causa daños materiales pero no hay heridos. ¿A partir de qué cantidad de daños debe reportarlo a la policía?","o":["$50 o más","$100 o más","$5,000 o más","$500 o más"],"h1":"Son unos cientos de dólares.","h2":"En Delaware, usted debe reportar a la policía un choque en una vía pública cuando los daños parecen ser de $500 o más.","p":"Correcto. En Delaware se reportan los choques con daños de $500 o más."},"zh":{"q":"在 Delaware，公共道路上发生车祸，造成财产损失但没有人受伤。损失达到多少时，你必须向警察报告？","o":["$50 或以上","$100 或以上","$5,000 或以上","$500 或以上"],"h1":"它是几百美元。","h2":"在 Delaware，公共道路上的车祸，如果财产损失看起来有 $500 或以上，你必须向警察报告。","p":"对。在 Delaware，损失 $500 或以上的车祸要报告。"},"vi":{"q":"Ở Delaware, một vụ tai nạn trên đường công cộng gây hư hại tài sản nhưng không ai bị thương. Thiệt hại bao nhiêu thì bạn phải báo cảnh sát?","o":["$50 trở lên","$100 trở lên","$5,000 trở lên","$500 trở lên"],"h1":"Đó là vài trăm đô la.","h2":"Ở Delaware, bạn phải báo cảnh sát về vụ tai nạn trên đường công cộng khi thiệt hại tài sản có vẻ từ $500 trở lên.","p":"Đúng. Ở Delaware, hãy báo các vụ tai nạn có thiệt hại từ $500 trở lên."},"tl":{"q":"Sa Delaware, may aksidente sa pampublikong kalsada na may sira sa ari-arian pero walang nasaktan. Sa anong halaga ng sira dapat mo itong i-report sa pulis?","o":["$50 o higit pa","$100 o higit pa","$5,000 o higit pa","$500 o higit pa"],"h1":"Ilang daang dolyar ito.","h2":"Sa Delaware, dapat mong i-report sa pulis ang aksidente sa pampublikong kalsada kapag mukhang $500 o higit pa ang sira sa ari-arian.","p":"Tama. Sa Delaware, i-report ang mga aksidenteng may sira na $500 o higit pa."},"ar":{"q":"في Delaware، حادث على طريق عام سبّب ضررًا في الممتلكات لكن بدون إصابات. عند أي قيمة للضرر يجب أن تبلّغ الشرطة؟","o":["$50 أو أكثر","$100 أو أكثر","$5,000 أو أكثر","$500 أو أكثر"],"h1":"إنها بضع مئات من الدولارات.","h2":"في Delaware، يجب أن تبلّغ الشرطة عن حادث على طريق عام عندما يبدو أن الضرر في الممتلكات $500 أو أكثر.","p":"صحيح. في Delaware، بلّغ عن الحوادث التي فيها ضرر $500 أو أكثر."},"ref":{"doc":"DE","page":141}},{"id":"de-025","scope":"DE","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Delaware, you are on a two-lane road and see a stopped police car with flashing lights. You cannot change lanes. What must you do?","o":["Slow down below the speed limit until you pass","Keep your speed and pass quickly","Stop behind the police car and wait","Drive on the shoulder to go around"],"h1":"If you cannot move away from it, change how fast you go.","h2":"In Delaware, on a two-lane road where you cannot move over, you must slow down below the posted speed limit until you have passed the stopped emergency vehicle.","p":"Right. If you cannot move over, slow down below the limit."},"es":{"q":"En Delaware, usted va por una carretera de dos carriles y ve un carro de policía detenido con luces intermitentes. No puede cambiar de carril. ¿Qué debe hacer?","o":["Bajar la velocidad por debajo del límite hasta pasarlo","Mantener su velocidad y pasar rápido","Detenerse detrás del carro de policía y esperar","Manejar por el acotamiento para rodearlo"],"h1":"Si no puede alejarse, cambie qué tan rápido va.","h2":"En Delaware, en una carretera de dos carriles donde no puede cambiar de carril, usted debe bajar la velocidad por debajo del límite señalado hasta pasar el vehículo de emergencia detenido.","p":"Correcto. Si no puede cambiar de carril, baje la velocidad por debajo del límite."},"zh":{"q":"在 Delaware，你在双车道道路上，看到一辆停着、闪着灯的警车。你不能换车道。你必须怎么做？","o":["减速到低于限速，直到开过去","保持速度，快点开过去","停在警车后面等","开到路肩上绕过去"],"h1":"如果你不能离它远一点，就改变你的速度。","h2":"在 Delaware，在不能换车道的双车道道路上，你必须减速到低于标示的限速，直到开过停着的紧急车辆。","p":"对。如果不能换车道，就减速到低于限速。"},"vi":{"q":"Ở Delaware, bạn đang ở trên đường hai làn và thấy một xe cảnh sát đang dừng, nháy đèn. Bạn không thể đổi làn. Bạn phải làm gì?","o":["Chạy chậm dưới giới hạn tốc độ cho đến khi bạn đi qua","Giữ tốc độ và vượt qua nhanh","Dừng sau xe cảnh sát và chờ","Chạy lên lề đường để đi vòng qua"],"h1":"Nếu bạn không thể tránh xa nó, hãy thay đổi tốc độ của bạn.","h2":"Ở Delaware, trên đường hai làn mà bạn không thể tránh sang làn khác, bạn phải chạy chậm dưới giới hạn tốc độ đã ghi cho đến khi bạn đã đi qua xe khẩn cấp đang dừng.","p":"Đúng. Nếu bạn không thể tránh sang làn khác, hãy chạy chậm dưới giới hạn."},"tl":{"q":"Sa Delaware, nasa kalsadang may dalawang lane ka at may nakita kang nakahintong police car na may kumikislap na ilaw. Hindi ka makalipat ng lane. Ano ang dapat mong gawin?","o":["Magdahan-dahan nang mas mababa sa speed limit hanggang makalampas ka","Panatilihin ang bilis at lumampas agad","Huminto sa likod ng police car at maghintay","Magmaneho sa shoulder para umikot"],"h1":"Kung hindi ka makalayo rito, baguhin ang bilis mo.","h2":"Sa Delaware, sa kalsadang may dalawang lane kung saan hindi ka makalipat, dapat kang magdahan-dahan nang mas mababa sa nakapaskil na speed limit hanggang malampasan mo ang nakahintong emergency vehicle.","p":"Tama. Kung hindi ka makalipat, magdahan-dahan nang mas mababa sa limit."},"ar":{"q":"في Delaware، أنت على طريق فيه مساران وترى سيارة شرطة متوقفة وأضواؤها تومض. لا تستطيع تغيير المسار. ماذا يجب أن تفعل؟","o":["تخفّف سرعتك إلى أقل من حد السرعة حتى تتجاوزها","تحافظ على سرعتك وتمر بسرعة","تتوقف خلف سيارة الشرطة وتنتظر","تقود على كتف الطريق لتلتفّ حولها"],"h1":"إذا لم تستطع الابتعاد عنها، غيّر سرعتك.","h2":"في Delaware، على طريق فيه مساران لا تستطيع فيه الابتعاد، يجب أن تخفّف سرعتك إلى أقل من حد السرعة المكتوب حتى تتجاوز سيارة الطوارئ المتوقفة.","p":"صحيح. إذا لم تستطع الابتعاد، خفّف سرعتك إلى أقل من الحد."},"ref":{"doc":"DE","page":82}},{"id":"de-026","scope":"DE","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Delaware, which child should not ride in the front passenger seat?","o":["A child who is 14 and 5 feet 8 inches tall","Any child who is wearing a seat belt","A child under 12 or shorter than 5 feet 5 inches","No child; any child may sit in front"],"h1":"The rule uses both an age and a height.","h2":"In Delaware, a child who is under 12 years old or shorter than 5 feet 5 inches should not ride in the front passenger seat.","p":"Right. Children under 12 or under 5 feet 5 inches ride in the back."},"es":{"q":"En Delaware, ¿qué niño no debe ir en el asiento delantero del pasajero?","o":["Un niño de 14 años que mide 5 pies 8 pulgadas","Cualquier niño que lleve el cinturón puesto","Un niño menor de 12 años o que mide menos de 5 pies 5 pulgadas","Ninguno; cualquier niño puede ir adelante"],"h1":"La regla usa una edad y una estatura.","h2":"En Delaware, un niño menor de 12 años o que mide menos de 5 pies 5 pulgadas no debe ir en el asiento delantero del pasajero.","p":"Correcto. Los niños menores de 12 años o de menos de 5 pies 5 pulgadas van atrás."},"zh":{"q":"在 Delaware，哪种孩子不应该坐在前排乘客座位？","o":["14 岁、身高 5 英尺 8 英寸的孩子","任何系着安全带的孩子","不到 12 岁或身高不到 5 英尺 5 英寸的孩子","没有；任何孩子都可以坐前面"],"h1":"这个规定同时看年龄和身高。","h2":"在 Delaware，不到 12 岁或身高不到 5 英尺 5 英寸的孩子不应该坐在前排乘客座位。","p":"对。不到 12 岁或不到 5 英尺 5 英寸的孩子坐后面。"},"vi":{"q":"Ở Delaware, trẻ em nào không nên ngồi ở ghế hành khách phía trước?","o":["Trẻ 14 tuổi và cao 5 feet 8 inches","Bất kỳ trẻ nào đang thắt dây an toàn","Trẻ dưới 12 tuổi hoặc thấp hơn 5 feet 5 inches","Không có; trẻ nào cũng có thể ngồi phía trước"],"h1":"Quy định dùng cả tuổi và chiều cao.","h2":"Ở Delaware, trẻ dưới 12 tuổi hoặc thấp hơn 5 feet 5 inches không nên ngồi ở ghế hành khách phía trước.","p":"Đúng. Trẻ dưới 12 tuổi hoặc thấp hơn 5 feet 5 inches ngồi ở phía sau."},"tl":{"q":"Sa Delaware, aling bata ang hindi dapat umupo sa front passenger seat?","o":["Batang 14 taong gulang at 5 feet 8 inches ang taas","Kahit sinong batang nakasuot ng seat belt","Batang wala pang 12 taong gulang o mas maliit sa 5 feet 5 inches","Wala; puwedeng umupo sa harap ang kahit sinong bata"],"h1":"Gumagamit ang patakaran ng edad at ng taas.","h2":"Sa Delaware, ang batang wala pang 12 taong gulang o mas maliit sa 5 feet 5 inches ay hindi dapat umupo sa front passenger seat.","p":"Tama. Sa likod umuupo ang mga batang wala pang 12 o mas maliit sa 5 feet 5 inches."},"ar":{"q":"في Delaware، أي طفل يجب ألّا يجلس في مقعد الراكب الأمامي؟","o":["طفل عمره 14 سنة وطوله 5 feet 8 inches","أي طفل يضع حزام الأمان","طفل عمره أقل من 12 سنة أو طوله أقل من 5 feet 5 inches","لا أحد؛ يمكن لأي طفل أن يجلس في الأمام"],"h1":"القاعدة تستعمل العمر والطول معًا.","h2":"في Delaware، الطفل الذي عمره أقل من 12 سنة أو طوله أقل من 5 feet 5 inches يجب ألّا يجلس في مقعد الراكب الأمامي.","p":"صحيح. الأطفال الذين عمرهم أقل من 12 سنة أو طولهم أقل من 5 feet 5 inches يجلسون في الخلف."},"ref":{"doc":"DE","page":109}},{"id":"de-027","scope":"DE","cat":"signals","sign":null,"c":2,"en":{"q":"In Delaware, how far ahead must you signal before you turn?","o":["50 feet","100 feet","300 feet","1,000 feet"],"h1":"Delaware asks for a longer distance than many states.","h2":"In Delaware, you must signal for at least 300 feet before you turn, stop or change lanes.","p":"Right. Signal 300 feet ahead."},"es":{"q":"En Delaware, ¿con cuánta anticipación debe poner la direccional antes de dar vuelta?","o":["50 pies","100 pies","300 pies","1,000 pies"],"h1":"Delaware pide una distancia más larga que muchos estados.","h2":"En Delaware, debe poner la direccional por lo menos 300 pies antes de dar vuelta, detenerse o cambiar de carril.","p":"Correcto. Ponga la direccional 300 pies antes."},"zh":{"q":"在 Delaware，转弯前要提前多远打转向灯？","o":["50 英尺","100 英尺","300 英尺","1,000 英尺"],"h1":"Delaware 要求的距离比很多州长。","h2":"在 Delaware，你在转弯、停车或换车道之前，至少要提前 300 英尺打转向灯。","p":"对。提前 300 英尺打转向灯。"},"vi":{"q":"Ở Delaware, bạn phải bật đèn xi nhan trước khi rẽ bao xa?","o":["50 feet","100 feet","300 feet","1,000 feet"],"h1":"Delaware yêu cầu khoảng cách dài hơn nhiều tiểu bang.","h2":"Ở Delaware, bạn phải bật đèn xi nhan ít nhất 300 feet trước khi rẽ, dừng lại hoặc đổi làn.","p":"Đúng. Bật xi nhan trước 300 feet."},"tl":{"q":"Sa Delaware, gaano kalayo bago ka lumiko dapat kang mag-signal?","o":["50 feet","100 feet","300 feet","1,000 feet"],"h1":"Mas mahabang distansya ang hinihingi ng Delaware kaysa sa maraming estado.","h2":"Sa Delaware, dapat kang mag-signal nang hindi bababa sa 300 feet bago ka lumiko, huminto o lumipat ng lane.","p":"Tama. Mag-signal 300 feet bago lumiko."},"ar":{"q":"في Delaware، على أي مسافة قبل المنعطف يجب أن تشغّل إشارة الانعطاف؟","o":["50 feet","100 feet","300 feet","1,000 feet"],"h1":"تطلب Delaware مسافة أطول من كثير من الولايات.","h2":"في Delaware يجب أن تشغّل إشارة الانعطاف قبل 300 feet على الأقل من الانعطاف أو التوقف أو تغيير المسار.","p":"صحيح. شغّل الإشارة قبل 300 feet."},"ref":{"doc":"DE","page":81}},{"id":"de-028","scope":"DE","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Delaware, you are passing a bicyclist on a road with two lanes in your direction. What does the law say?","o":["Leave at least 3 feet and move to the other lane if you can","Leave at least 1 foot and stay in your lane","Honk and pass close to the bike","Pass on the right side of the bike"],"h1":"There is a minimum distance, and an extra step on bigger roads.","h2":"In Delaware, you must leave at least three feet when passing a bicyclist, and on roads with more than one lane in your direction you should move to the next lane whenever possible.","p":"Right. At least 3 feet, and change lanes when you can."},"es":{"q":"En Delaware, va a rebasar a un ciclista en una vía con dos carriles en su dirección. ¿Qué dice la ley?","o":["Dejar por lo menos 3 pies y pasarse al otro carril si puede","Dejar por lo menos 1 pie y quedarse en su carril","Tocar la bocina y pasar cerca de la bicicleta","Rebasar por el lado derecho de la bicicleta"],"h1":"Hay una distancia mínima, y un paso más en vías grandes.","h2":"En Delaware, debe dejar por lo menos tres pies al rebasar a un ciclista, y en vías con más de un carril en su dirección debe pasarse al carril de al lado siempre que pueda.","p":"Correcto. Por lo menos 3 pies, y cámbiese de carril cuando pueda."},"zh":{"q":"在 Delaware，你在一条同方向有两条车道的路上超过一个骑自行车的人。法律怎么规定？","o":["至少留出 3 英尺，能换到另一条车道就换过去","至少留出 1 英尺，并留在自己的车道里","按喇叭，然后贴近自行车超过去","从自行车的右边超过去"],"h1":"有一个最小距离，在大一点的路上还要多做一步。","h2":"在 Delaware，超过骑自行车的人时至少要留出三英尺；如果你这个方向有不止一条车道，只要可以，就应该换到旁边的车道。","p":"对。至少 3 英尺，能换车道就换车道。"},"vi":{"q":"Ở Delaware, bạn đang vượt một người đi xe đạp trên con đường có hai làn cùng chiều với bạn. Luật nói gì?","o":["Chừa ít nhất 3 feet và chuyển sang làn kia nếu có thể","Chừa ít nhất 1 foot và ở trong làn của bạn","Bấm còi và vượt sát xe đạp","Vượt bên phải xe đạp"],"h1":"Có một khoảng cách tối thiểu, và thêm một bước trên đường lớn hơn.","h2":"Ở Delaware, khi vượt người đi xe đạp, bạn phải chừa ít nhất ba feet, và trên đường có hơn một làn cùng chiều, bạn nên chuyển sang làn bên cạnh bất cứ khi nào có thể.","p":"Đúng. Ít nhất 3 feet, và đổi làn khi có thể."},"tl":{"q":"Sa Delaware, nilalampasan mo ang isang nagbibisikleta sa daan na may dalawang lane sa direksyon mo. Ano ang sabi ng batas?","o":["Mag-iwan ng hindi bababa sa 3 feet at lumipat sa kabilang lane kung kaya mo","Mag-iwan ng hindi bababa sa 1 foot at manatili sa lane mo","Bumusina at lumampas nang malapit sa bisikleta","Lumampas sa kanang bahagi ng bisikleta"],"h1":"May pinakamaliit na distansya, at may dagdag na hakbang sa mas malalaking daan.","h2":"Sa Delaware, dapat kang mag-iwan ng hindi bababa sa tatlong feet kapag nilalampasan mo ang isang nagbibisikleta, at sa daan na may higit sa isang lane sa direksyon mo, dapat kang lumipat sa katabing lane kapag kaya.","p":"Tama. Hindi bababa sa 3 feet, at lumipat ng lane kapag kaya mo."},"ar":{"q":"في Delaware، أنت تتجاوز راكب دراجة هوائية على طريق فيه مساران في اتجاهك. ماذا يقول القانون؟","o":["اترك 3 feet على الأقل وانتقل إلى المسار الآخر إذا استطعت","اترك 1 foot على الأقل وابقَ في مسارك","اضغط على البوق وتجاوز قريبًا من الدراجة","تجاوز من الجهة اليمنى للدراجة"],"h1":"هناك مسافة دنيا، وخطوة إضافية على الطرق الأكبر.","h2":"في Delaware يجب أن تترك ثلاثة feet على الأقل عندما تتجاوز راكب دراجة هوائية، وعلى الطرق التي فيها أكثر من مسار في اتجاهك يجب أن تنتقل إلى المسار المجاور كلما أمكن ذلك.","p":"صحيح. 3 feet على الأقل، وغيّر المسار عندما تستطيع."},"ref":{"doc":"DE","page":81}},{"id":"de-029","scope":"DE","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Delaware, how close to a fire hydrant may you stop or park?","o":["Up to 5 feet away","No closer than 15 feet","No closer than 30 feet","No closer than 50 feet"],"h1":"Firefighters need room to reach the hydrant.","h2":"In Delaware, you may not stop or park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a fire hydrant."},"es":{"q":"En Delaware, ¿a qué distancia de un hidrante puede detenerse o estacionarse?","o":["Hasta 5 pies de distancia","No más cerca de 15 pies","No más cerca de 30 pies","No más cerca de 50 pies"],"h1":"Los bomberos necesitan espacio para llegar al hidrante.","h2":"En Delaware, usted no puede detenerse ni estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese por lo menos a 15 pies de un hidrante."},"zh":{"q":"在 Delaware，你可以在离消防栓多近的地方停车或泊车？","o":["最近可以到 5 英尺","不能近于 15 英尺","不能近于 30 英尺","不能近于 50 英尺"],"h1":"消防员需要空间去用消防栓。","h2":"在 Delaware，你不可以在离消防栓 15 英尺以内的地方停车或泊车。","p":"对。离消防栓至少 15 英尺。"},"vi":{"q":"Ở Delaware, bạn được dừng hoặc đỗ xe gần trụ cứu hỏa đến mức nào?","o":["Cách đến 5 feet","Không gần hơn 15 feet","Không gần hơn 30 feet","Không gần hơn 50 feet"],"h1":"Lính cứu hỏa cần chỗ để tới được trụ cứu hỏa.","h2":"Ở Delaware, bạn không được dừng hoặc đỗ xe trong vòng 15 feet cách trụ cứu hỏa.","p":"Đúng. Cách trụ cứu hỏa ít nhất 15 feet."},"tl":{"q":"Sa Delaware, gaano kalapit sa fire hydrant puwede kang huminto o pumarada?","o":["Hanggang 5 feet ang layo","Hindi lalapit sa 15 feet","Hindi lalapit sa 30 feet","Hindi lalapit sa 50 feet"],"h1":"Kailangan ng mga bumbero ng espasyo para maabot ang hydrant.","h2":"Sa Delaware, hindi ka puwedeng huminto o pumarada sa loob ng 15 feet mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 15 feet mula sa fire hydrant."},"ar":{"q":"في Delaware، كم يمكنك أن تقترب من صنبور إطفاء الحريق عندما تتوقف أو تركن سيارتك؟","o":["حتى مسافة 5 feet","ليس أقرب من 15 feet","ليس أقرب من 30 feet","ليس أقرب من 50 feet"],"h1":"يحتاج رجال الإطفاء إلى مكان للوصول إلى الصنبور.","h2":"في Delaware لا يجوز لك أن تتوقف أو تركن سيارتك على مسافة أقل من 15 feet من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بعد 15 feet على الأقل من صنبور إطفاء الحريق."},"ref":{"doc":"DE","page":92}},{"id":"de-030","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, what is the minimum vision needed for a driver license, with or without glasses?","o":["20/100","20/70","20/20","20/40"],"h1":"It is the same standard many states use.","h2":"In Delaware, you need at least 20/40 vision, with or without glasses or contact lenses, to get a driver license.","p":"Right. The minimum is 20/40."},"es":{"q":"En Delaware, ¿cuál es la visión mínima para una licencia de conducir, con o sin anteojos?","o":["20/100","20/70","20/20","20/40"],"h1":"Es el mismo estándar que usan muchos estados.","h2":"En Delaware, necesita por lo menos una visión de 20/40, con o sin anteojos o lentes de contacto, para obtener una licencia de conducir.","p":"Correcto. El mínimo es 20/40."},"zh":{"q":"在 Delaware，戴或不戴眼镜，拿驾照最低需要多好的视力？","o":["20/100","20/70","20/20","20/40"],"h1":"这和很多州用的标准一样。","h2":"在 Delaware，不管戴不戴眼镜或隐形眼镜，你的视力至少要达到 20/40 才能拿到驾照。","p":"对。最低是 20/40。"},"vi":{"q":"Ở Delaware, thị lực tối thiểu để có bằng lái xe là bao nhiêu, có hoặc không có kính?","o":["20/100","20/70","20/20","20/40"],"h1":"Đây là cùng tiêu chuẩn mà nhiều tiểu bang dùng.","h2":"Ở Delaware, bạn cần thị lực ít nhất 20/40, có hoặc không có kính đeo hay kính áp tròng, để được cấp bằng lái xe.","p":"Đúng. Mức tối thiểu là 20/40."},"tl":{"q":"Sa Delaware, ano ang pinakamababang linaw ng paningin na kailangan para sa driver license, may salamin man o wala?","o":["20/100","20/70","20/20","20/40"],"h1":"Ito ang parehong pamantayan na ginagamit ng maraming estado.","h2":"Sa Delaware, kailangan mo ng paningin na hindi bababa sa 20/40, may salamin o contact lenses man o wala, para makakuha ng driver license.","p":"Tama. Ang pinakamababa ay 20/40."},"ar":{"q":"في Delaware، ما أدنى قوة نظر مطلوبة لرخصة القيادة، مع النظارات أو بدونها؟","o":["20/100","20/70","20/20","20/40"],"h1":"إنه المعيار نفسه الذي تستخدمه ولايات كثيرة.","h2":"في Delaware تحتاج إلى قوة نظر 20/40 على الأقل، مع النظارات أو العدسات اللاصقة أو بدونها، لتحصل على رخصة القيادة.","p":"صحيح. الحد الأدنى هو 20/40."},"ref":{"doc":"DE","page":40}},{"id":"de-031","scope":"DE","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Delaware, if no other limit is posted, what is the speed limit in a business or residential district?","o":["15 mph","35 mph","25 mph","45 mph"],"h1":"It is a common town speed.","h2":"In Delaware, the speed limit in business and residential districts is 25 mph unless a different limit is posted.","p":"Right. It is 25 mph."},"es":{"q":"En Delaware, si no hay otro límite señalado, ¿cuál es el límite de velocidad en una zona comercial o residencial?","o":["15 mph","35 mph","25 mph","45 mph"],"h1":"Es una velocidad común en los pueblos.","h2":"En Delaware, el límite de velocidad en zonas comerciales y residenciales es de 25 mph, salvo que haya otro límite señalado.","p":"Correcto. Es de 25 mph."},"zh":{"q":"在 Delaware，如果没有标出别的限速，商业区或住宅区的限速是多少？","o":["15 mph","35 mph","25 mph","45 mph"],"h1":"这是城镇里常见的速度。","h2":"在 Delaware，除非标出了不同的限速，商业区和住宅区的限速是 25 mph。","p":"对。是 25 mph。"},"vi":{"q":"Ở Delaware, nếu không có biển báo tốc độ khác, tốc độ tối đa trong khu thương mại hoặc khu dân cư là bao nhiêu?","o":["15 mph","35 mph","25 mph","45 mph"],"h1":"Đây là tốc độ thường gặp trong thị trấn.","h2":"Ở Delaware, tốc độ tối đa trong khu thương mại và khu dân cư là 25 mph, trừ khi có biển báo tốc độ khác.","p":"Đúng. Là 25 mph."},"tl":{"q":"Sa Delaware, kung walang ibang nakapaskil na limit, ano ang speed limit sa business o residential district?","o":["15 mph","35 mph","25 mph","45 mph"],"h1":"Karaniwang bilis ito sa bayan.","h2":"Sa Delaware, 25 mph ang speed limit sa business at residential districts maliban kung may ibang limit na nakapaskil.","p":"Tama. 25 mph ito."},"ar":{"q":"في Delaware، إذا لم يكن هناك حد سرعة آخر مكتوب، ما حد السرعة في المنطقة التجارية أو السكنية؟","o":["15 mph","35 mph","25 mph","45 mph"],"h1":"إنها سرعة شائعة في البلدات.","h2":"في Delaware حد السرعة في المناطق التجارية والسكنية هو 25 mph ما لم يكن هناك حد مختلف مكتوب.","p":"صحيح. إنه 25 mph."},"ref":{"doc":"DE","page":93}},{"id":"de-032","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, you just moved here from another state. How soon must you get a Delaware driver license?","o":["Within 30 days","Within 60 days","Within 90 days","Within 1 year"],"h1":"It is about two months.","h2":"In Delaware, a new resident must apply for a Delaware driver license within 60 days of moving here.","p":"Right. You have 60 days."},"es":{"q":"En Delaware, usted acaba de mudarse desde otro estado. ¿En cuánto tiempo debe obtener una licencia de conducir de Delaware?","o":["Dentro de 30 días","Dentro de 60 días","Dentro de 90 días","Dentro de 1 año"],"h1":"Son unos dos meses.","h2":"En Delaware, un nuevo residente debe solicitar una licencia de conducir de Delaware dentro de los 60 días después de mudarse.","p":"Correcto. Tiene 60 días."},"ref":{"doc":"DE","page":31}},{"id":"de-033","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, how long is a regular Class D driver license valid?","o":["2 years","4 years","6 years","8 years"],"h1":"It lasts longer than in many states.","h2":"In Delaware, a regular Class D driver license is issued for 8 years.","p":"Right. It is valid for 8 years."},"es":{"q":"En Delaware, ¿por cuánto tiempo es válida una licencia de conducir Clase D normal?","o":["2 años","4 años","6 años","8 años"],"h1":"Dura más que en muchos estados.","h2":"En Delaware, una licencia de conducir Clase D normal se emite por 8 años.","p":"Correcto. Es válida por 8 años."},"ref":{"doc":"DE","page":32}},{"id":"de-034","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, a teen breaks the rules of the Level One learner's permit for the first time. What happens?","o":["A 2-month suspension","A warning letter only","A 1-year suspension","A small fine only"],"h1":"It is treated like driving without a license.","h2":"In Delaware, breaking the Level One permit rules counts as driving without a license, and the first offense brings a 2-month suspension.","p":"Right. The first time, it is a 2-month suspension."},"es":{"q":"En Delaware, un joven no cumple las reglas del permiso de aprendizaje de Nivel Uno por primera vez. ¿Qué pasa?","o":["Una suspensión de 2 meses","Solo una carta de advertencia","Una suspensión de 1 año","Solo una multa pequeña"],"h1":"Se trata como manejar sin licencia.","h2":"En Delaware, no cumplir las reglas del permiso de Nivel Uno cuenta como manejar sin licencia, y la primera vez trae una suspensión de 2 meses.","p":"Correcto. La primera vez es una suspensión de 2 meses."},"ref":{"doc":"DE","page":30}},{"id":"de-035","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, you fail the road test. How long must you wait before you take it again?","o":["Until the next day","At least 7 days","At least 30 days","At least 6 months"],"h1":"It gives you about a month to practice.","h2":"In Delaware, if you fail the road test, you must wait at least 30 days before you try again.","p":"Right. You wait at least 30 days."},"es":{"q":"En Delaware, usted no aprueba el examen de manejo. ¿Cuánto tiempo debe esperar para tomarlo otra vez?","o":["Hasta el día siguiente","Por lo menos 7 días","Por lo menos 30 días","Por lo menos 6 meses"],"h1":"Le da como un mes para practicar.","h2":"En Delaware, si no aprueba el examen de manejo, debe esperar por lo menos 30 días antes de intentarlo otra vez.","p":"Correcto. Debe esperar por lo menos 30 días."},"ref":{"doc":"DE","page":43}},{"id":"de-036","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, how much is the fee to reinstate a revoked driver license?","o":["$25","$50","$100","$200"],"h1":"A revoked license costs more to get back than a suspended one.","h2":"In Delaware, it costs $200 to reinstate a revoked license, while a suspended license costs $50.","p":"Right. The fee is $200."},"es":{"q":"En Delaware, ¿cuánto cuesta restablecer una licencia de conducir revocada?","o":["$25","$50","$100","$200"],"h1":"Recuperar una licencia revocada cuesta más que una suspendida.","h2":"En Delaware, cuesta $200 restablecer una licencia revocada, mientras que una licencia suspendida cuesta $50.","p":"Correcto. El cargo es de $200."},"ref":{"doc":"DE","page":44}},{"id":"de-037","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, how many points do you get for driving 10 to 14 mph over the speed limit?","o":["4 points","2 points","6 points","8 points"],"h1":"It is more than for going just a little over the limit.","h2":"In Delaware, speeding 10 to 14 mph over the posted limit adds 4 points to your record.","p":"Right. It is 4 points."},"es":{"q":"En Delaware, ¿cuántos puntos recibe por manejar de 10 a 14 mph sobre el límite de velocidad?","o":["4 puntos","2 puntos","6 puntos","8 puntos"],"h1":"Es más que por pasarse solo un poco del límite.","h2":"En Delaware, manejar de 10 a 14 mph sobre el límite señalado agrega 4 puntos a su historial.","p":"Correcto. Son 4 puntos."},"ref":{"doc":"DE","page":47}},{"id":"de-038","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, what must a driver do after reaching 12 points?","o":["Nothing, it is only a warning","Finish a behavior modification driving course within 90 days","Lose the license for 1 year","Retake the vision test only"],"h1":"It is a class, with a deadline.","h2":"In Delaware, a driver who reaches 12 points must complete a behavior modification driving course within 90 days, or face a 2-month suspension.","p":"Right. At 12 points you must take the course within 90 days."},"es":{"q":"En Delaware, ¿qué debe hacer un conductor al llegar a 12 puntos?","o":["Nada, es solo una advertencia","Terminar un curso de modificación de conducta al volante dentro de 90 días","Perder la licencia por 1 año","Solo repetir el examen de la vista"],"h1":"Es una clase, con una fecha límite.","h2":"En Delaware, un conductor que llega a 12 puntos debe completar un curso de modificación de conducta al volante dentro de 90 días, o tendrá una suspensión de 2 meses.","p":"Correcto. Con 12 puntos debe tomar el curso dentro de 90 días."},"ref":{"doc":"DE","page":47}},{"id":"de-039","scope":"DE","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Delaware, a driver is convicted of going 25 mph over the speed limit. What happens to the license?","o":["Nothing happens to it","It is revoked for life","It is suspended for 1 month","It is suspended for 5 years"],"h1":"It is a short suspension, and it grows with more speed.","h2":"In Delaware, driving 25 mph over the limit brings a 1-month license suspension, and it gets longer for each extra 5 mph.","p":"Right. It is a 1-month suspension."},"es":{"q":"En Delaware, un conductor es declarado culpable de manejar 25 mph sobre el límite de velocidad. ¿Qué pasa con su licencia?","o":["No le pasa nada","Se revoca de por vida","Se suspende por 1 mes","Se suspende por 5 años"],"h1":"Es una suspensión corta, y aumenta con más velocidad.","h2":"En Delaware, manejar 25 mph sobre el límite trae una suspensión de la licencia de 1 mes, y es más larga por cada 5 mph adicionales.","p":"Correcto. Es una suspensión de 1 mes."},"ref":{"doc":"DE","page":48}},{"id":"de-040","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, what can an approved defensive driving course give you?","o":["A 3-point credit","A free license renewal","All your points erased","A higher speed limit"],"h1":"It helps with future penalties, not with points you already have.","h2":"In Delaware, finishing an approved defensive driving course can give you a 3-point credit toward future DMV penalties.","p":"Right. It gives a 3-point credit."},"es":{"q":"En Delaware, ¿qué le puede dar un curso aprobado de manejo defensivo?","o":["Un crédito de 3 puntos","Una renovación de licencia gratis","Que se borren todos sus puntos","Un límite de velocidad más alto"],"h1":"Ayuda con sanciones futuras, no con los puntos que ya tiene.","h2":"En Delaware, terminar un curso aprobado de manejo defensivo le puede dar un crédito de 3 puntos para sanciones futuras del DMV.","p":"Correcto. Da un crédito de 3 puntos."},"ref":{"doc":"DE","page":49}},{"id":"de-041","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, after an arrest for driving under the influence, how many days do you have to ask for a DMV hearing?","o":["5 days","15 days","30 days","60 days"],"h1":"It matches the length of the temporary license the officer gives you.","h2":"In Delaware, after a DUI arrest you get a 15-day temporary license and have 15 days to ask for an administrative hearing.","p":"Right. You have 15 days."},"es":{"q":"En Delaware, después de un arresto por manejar bajo la influencia, ¿cuántos días tiene para pedir una audiencia del DMV?","o":["5 días","15 días","30 días","60 días"],"h1":"Es igual al tiempo de la licencia temporal que le da el oficial.","h2":"En Delaware, después de un arresto por DUI usted recibe una licencia temporal de 15 días y tiene 15 días para pedir una audiencia administrativa.","p":"Correcto. Tiene 15 días."},"ref":{"doc":"DE","page":55}},{"id":"de-042","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, a driver is convicted of a first DUI with a blood alcohol level under 0.15. How long does the DMV take away the license?","o":["1 month","6 months","5 years","12 months"],"h1":"It is a full year.","h2":"In Delaware, a first DUI conviction with a blood alcohol level under 0.15 means the DMV takes the license for 12 months.","p":"Right. It is 12 months."},"es":{"q":"En Delaware, un conductor es declarado culpable de un primer DUI con un nivel de alcohol en la sangre menor de 0.15. ¿Por cuánto tiempo le quita la licencia el DMV?","o":["1 mes","6 meses","5 años","12 meses"],"h1":"Es un año completo.","h2":"En Delaware, una primera condena por DUI con un nivel de alcohol en la sangre menor de 0.15 significa que el DMV le quita la licencia por 12 meses.","p":"Correcto. Son 12 meses."},"ref":{"doc":"DE","page":56}},{"id":"de-043","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, a person under 21 is caught with alcohol for the first time. What is the fine?","o":["$25","$100","$500","$1,000"],"h1":"It goes up for a second offense.","h2":"In Delaware, a person under 21 who has or drinks alcohol is fined $100 for the first offense.","p":"Right. The first fine is $100."},"es":{"q":"En Delaware, a una persona menor de 21 años la encuentran con alcohol por primera vez. ¿Cuál es la multa?","o":["$25","$100","$500","$1,000"],"h1":"Sube en una segunda ofensa.","h2":"En Delaware, una persona menor de 21 años que tiene o toma alcohol recibe una multa de $100 la primera vez.","p":"Correcto. La primera multa es de $100."},"ref":{"doc":"DE","page":54}},{"id":"de-044","scope":"DE","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Delaware, besides at night, when must your headlights be on?","o":["Only on the highway","Only when it is snowing","Any time you cannot see beyond 1,000 feet","Any time you have passengers"],"h1":"Think about how far ahead you can see.","h2":"In Delaware, your headlights must be on any time you cannot see clearly beyond 1,000 feet.","p":"Right. Use them when you cannot see past 1,000 feet."},"es":{"q":"En Delaware, además de la noche, ¿cuándo debe tener las luces delanteras encendidas?","o":["Solo en la autopista","Solo cuando está nevando","Siempre que no pueda ver más allá de 1,000 pies","Siempre que lleve pasajeros"],"h1":"Piense en qué tan lejos puede ver.","h2":"En Delaware, sus luces delanteras deben estar encendidas siempre que no pueda ver bien más allá de 1,000 pies.","p":"Correcto. Úselas cuando no pueda ver más allá de 1,000 pies."},"ref":{"doc":"DE","page":62}},{"id":"de-045","scope":"DE","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Delaware, you are following another car at night. Within what distance must you switch to low beams?","o":["200 feet","50 feet","500 feet","1,000 feet"],"h1":"It is shorter than the distance for a car coming toward you.","h2":"In Delaware, you must switch to low beams when you are within 200 feet of the car you are following.","p":"Right. Dim your lights within 200 feet."},"es":{"q":"En Delaware, usted va detrás de otro carro de noche. ¿A qué distancia debe cambiar a luces bajas?","o":["200 pies","50 pies","500 pies","1,000 pies"],"h1":"Es menos que la distancia para un carro que viene de frente.","h2":"En Delaware, debe cambiar a luces bajas cuando esté a 200 pies o menos del carro que va adelante.","p":"Correcto. Baje las luces a 200 pies."},"ref":{"doc":"DE","page":62}},{"id":"de-046","scope":"DE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Delaware, when may you use studded tires?","o":["All year","November 1 to March 31","December 1 to February 28","October 15 to April 15"],"h1":"The season starts in the middle of October.","h2":"In Delaware, studded tires are legal from October 15 to April 15 and not allowed the rest of the year.","p":"Right. October 15 to April 15."},"es":{"q":"En Delaware, ¿cuándo puede usar llantas con clavos?","o":["Todo el año","Del 1 de noviembre al 31 de marzo","Del 1 de diciembre al 28 de febrero","Del 15 de octubre al 15 de abril"],"h1":"La temporada empieza a mediados de octubre.","h2":"En Delaware, las llantas con clavos son legales del 15 de octubre al 15 de abril y no se permiten el resto del año.","p":"Correcto. Del 15 de octubre al 15 de abril."},"ref":{"doc":"DE","page":62}},{"id":"de-047","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, what is the least liability insurance a car must have for injury or death of one person in a crash?","o":["$5,000","$100,000","$25,000","$250,000"],"h1":"It is half of the amount for two or more people.","h2":"In Delaware, a car must have at least $25,000 of coverage for injury or death of one person in any one crash.","p":"Right. The minimum is $25,000."},"es":{"q":"En Delaware, ¿cuál es el seguro de responsabilidad mínimo que debe tener un carro por lesiones o muerte de una persona en un choque?","o":["$5,000","$100,000","$25,000","$250,000"],"h1":"Es la mitad de la cantidad para dos o más personas.","h2":"En Delaware, un carro debe tener por lo menos $25,000 de cobertura por lesiones o muerte de una persona en un choque.","p":"Correcto. El mínimo es de $25,000."},"ref":{"doc":"DE","page":63}},{"id":"de-048","scope":"DE","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Delaware, what speed limit does state law set for Route 1 and Interstate 495?","o":["60 mph","65 mph","70 mph","75 mph"],"h1":"It is the highest limit in the state speed table.","h2":"In Delaware, the speed limit on Route 1 and Interstate 495 is 65 mph.","p":"Right. It is 65 mph."},"es":{"q":"En Delaware, ¿qué límite de velocidad fija la ley estatal para la Ruta 1 y la Interestatal 495?","o":["60 mph","65 mph","70 mph","75 mph"],"h1":"Es el límite más alto de la tabla de velocidades del estado.","h2":"En Delaware, el límite de velocidad en la Ruta 1 y la Interestatal 495 es de 65 mph.","p":"Correcto. Es de 65 mph."},"ref":{"doc":"DE","page":93}},{"id":"de-049","scope":"DE","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Delaware, if no other limit is posted, what is the speed limit on a divided road or a road with four or more lanes?","o":["55 mph","45 mph","50 mph","65 mph"],"h1":"It is a little faster than on a two-lane road.","h2":"In Delaware, the speed limit on divided roads and roads with four or more lanes is 55 mph unless another limit is posted.","p":"Right. It is 55 mph."},"es":{"q":"En Delaware, si no hay otro límite señalado, ¿cuál es el límite de velocidad en una carretera dividida o con cuatro carriles o más?","o":["55 mph","45 mph","50 mph","65 mph"],"h1":"Es un poco más rápido que en una carretera de dos carriles.","h2":"En Delaware, el límite de velocidad en carreteras divididas y carreteras con cuatro carriles o más es de 55 mph, salvo que haya otro límite señalado.","p":"Correcto. Es de 55 mph."},"ref":{"doc":"DE","page":93}},{"id":"de-050","scope":"DE","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Delaware, you are following a motorcycle at more than 40 mph. How much following distance should you keep?","o":["1 second","2 seconds","4 seconds","10 seconds"],"h1":"It doubles the distance used at lower speeds.","h2":"In Delaware, keep at least 4 seconds behind a motorcycle above 40 mph, and 2 seconds below 40 mph.","p":"Right. Keep 4 seconds behind."},"es":{"q":"En Delaware, usted va detrás de una motocicleta a más de 40 mph. ¿Qué distancia debe mantener?","o":["1 segundo","2 segundos","4 segundos","10 segundos"],"h1":"Es el doble de la distancia que se usa a velocidades más bajas.","h2":"En Delaware, mantenga por lo menos 4 segundos detrás de una motocicleta a más de 40 mph, y 2 segundos a menos de 40 mph.","p":"Correcto. Mantenga 4 segundos de distancia."},"ref":{"doc":"DE","page":100}},{"id":"de-051","scope":"DE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Delaware, may you drive with headphones or earbuds in both ears?","o":["Yes, if the volume is low","Yes, but only in the daytime","Yes, if you are 21 or older","No, it is against the law"],"h1":"You need to hear horns and sirens.","h2":"In Delaware, it is illegal to drive with headphones or earphones that cover or go in both ears.","p":"Right. It is against the law."},"es":{"q":"En Delaware, ¿puede manejar con audífonos en los dos oídos?","o":["Sí, si el volumen está bajo","Sí, pero solo de día","Sí, si tiene 21 años o más","No, es contra la ley"],"h1":"Usted necesita oír bocinas y sirenas.","h2":"En Delaware, es ilegal manejar con audífonos que cubran o entren en los dos oídos.","p":"Correcto. Es contra la ley."},"ref":{"doc":"DE","page":116}},{"id":"ga-001","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, what is the youngest age to get a learner's permit (Class CP)?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It comes one year before you can take the road test for a Class D license.","h2":"In Georgia you can get a Class CP learner's permit at 15, after you pass the vision and knowledge tests.","p":"Right. The Georgia learner's permit starts at 15."},"es":{"q":"En Georgia, ¿cuál es la edad mínima para obtener el permiso de aprendiz (Clase CP)?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de poder hacer el examen de manejo para la licencia Clase D.","h2":"En Georgia usted puede obtener el permiso de aprendiz Clase CP a los 15 años, después de aprobar los exámenes de la vista y de conocimientos.","p":"Correcto. El permiso de aprendiz en Georgia empieza a los 15."},"zh":{"q":"在 Georgia，最小几岁可以拿到学习驾照（Class CP）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比你可以参加 Class D 驾照路考的年龄早一年。","h2":"在 Georgia，你通过视力和笔试以后，15 岁就可以拿到 Class CP 学习驾照。","p":"对。Georgia 的学习驾照从 15 岁开始。"},"vi":{"q":"Ở Georgia, tuổi nhỏ nhất để được cấp giấy phép tập lái (learner's permit, Class CP) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Nó sớm hơn một năm so với tuổi được thi lái xe trên đường để lấy bằng Class D.","h2":"Ở Georgia, bạn có thể lấy giấy phép tập lái Class CP lúc 15 tuổi, sau khi đậu bài kiểm tra mắt và bài thi kiến thức.","p":"Đúng. Ở Georgia, giấy phép tập lái bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Georgia, ano ang pinakabatang edad para makakuha ng learner's permit (Class CP)?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ka puwedeng kumuha ng road test para sa Class D license.","h2":"Sa Georgia, puwede kang kumuha ng Class CP learner's permit sa edad na 15, pagkatapos mong pumasa sa vision test at knowledge test.","p":"Tama. Sa Georgia, nagsisimula ang learner's permit sa edad na 15."},"ar":{"q":"في Georgia، ما أصغر عمر للحصول على تصريح تعلّم القيادة (learner's permit, Class CP)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"يأتي قبل سنة واحدة من العمر الذي يمكنك فيه أداء اختبار القيادة على الطريق لرخصة Class D.","h2":"في Georgia يمكنك الحصول على تصريح تعلّم القيادة Class CP في عمر 15 سنة، بعد أن تنجح في اختبار النظر واختبار المعرفة.","p":"صحيح. في Georgia يبدأ تصريح التعلّم من عمر 15 سنة."},"ref":{"doc":"GA","page":8}},{"id":"ga-002","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, how old must the licensed person beside a learner's permit driver be?","o":["At least 16","At least 18","At least 25","At least 21"],"h1":"The helper must be old enough to buy alcohol legally.","h2":"A Georgia permit driver must have a licensed person who is at least 21 years old in the car.","p":"Right. The person with you must be 21 or older."},"es":{"q":"En Georgia, ¿qué edad debe tener la persona con licencia que acompaña a un conductor con permiso de aprendiz?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 25","Por lo menos 21"],"h1":"El acompañante debe tener edad para comprar alcohol legalmente.","h2":"Un conductor con permiso en Georgia debe llevar en el carro a una persona con licencia de por lo menos 21 años.","p":"Correcto. Su acompañante debe tener 21 años o más."},"zh":{"q":"在 Georgia，坐在持学习驾照司机旁边、有驾照的人必须几岁？","o":["至少 16 岁","至少 18 岁","至少 25 岁","至少 21 岁"],"h1":"陪同的人必须到了可以合法买酒的年龄。","h2":"Georgia 持学习驾照的司机，车里必须有一位至少 21 岁、有驾照的人。","p":"对。陪你的人必须 21 岁或以上。"},"vi":{"q":"Ở Georgia, người có bằng lái ngồi cạnh người lái có giấy phép tập lái phải bao nhiêu tuổi?","o":["Ít nhất 16 tuổi","Ít nhất 18 tuổi","Ít nhất 25 tuổi","Ít nhất 21 tuổi"],"h1":"Người đi kèm phải đủ tuổi để mua rượu hợp pháp.","h2":"Người lái có giấy phép tập lái ở Georgia phải có một người có bằng lái, ít nhất 21 tuổi, ngồi trong xe.","p":"Đúng. Người đi cùng bạn phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Georgia, ilang taon dapat ang may lisensyang tao na katabi ng nagmamaneho na may learner's permit?","o":["Hindi bababa sa 16","Hindi bababa sa 18","Hindi bababa sa 25","Hindi bababa sa 21"],"h1":"Dapat sapat ang edad ng kasama para legal na makabili ng alak.","h2":"Ang nagmamaneho na may permit sa Georgia ay dapat may kasamang may lisensya na hindi bababa sa 21 taong gulang sa loob ng kotse.","p":"Tama. Ang kasama mo ay dapat 21 taong gulang o higit pa."},"ar":{"q":"في Georgia، كم يجب أن يكون عمر الشخص الذي يحمل رخصة ويجلس بجانب سائق لديه تصريح تعلّم؟","o":["16 سنة على الأقل","18 سنة على الأقل","25 سنة على الأقل","21 سنة على الأقل"],"h1":"يجب أن يكون المرافق كبيرًا بما يكفي لشراء الكحول بشكل قانوني.","h2":"يجب أن يكون مع سائق تصريح التعلّم في Georgia شخص يحمل رخصة ولا يقل عمره عن 21 سنة داخل السيارة.","p":"صحيح. يجب أن يكون الشخص الذي معك عمره 21 سنة أو أكثر."},"ref":{"doc":"GA","page":8}},{"id":"ga-003","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, where must the supervising adult sit when a learner's permit holder drives?","o":["In the seat next to the driver","In the back seat","Anywhere in the car","In a car following behind"],"h1":"The adult must be close enough to take control of the car.","h2":"In Georgia the supervising adult must sit in the seat next to the driver, ready to take control if needed.","p":"Right. The adult sits next to you."},"es":{"q":"En Georgia, ¿dónde debe sentarse el adulto que supervisa a un conductor con permiso de aprendiz?","o":["En el asiento al lado del conductor","En el asiento de atrás","En cualquier lugar del carro","En otro carro que va detrás"],"h1":"El adulto debe estar lo bastante cerca para tomar el control del carro.","h2":"En Georgia el adulto que supervisa debe sentarse en el asiento al lado del conductor, listo para tomar el control si hace falta.","p":"Correcto. El adulto va sentado a su lado."},"zh":{"q":"在 Georgia，持学习驾照的人开车时，监督的成年人必须坐在哪里？","o":["司机旁边的座位","后排座位","车里任何地方","跟在后面的另一辆车里"],"h1":"这个成年人必须离得够近，可以控制这辆车。","h2":"在 Georgia，监督的成年人必须坐在司机旁边的座位，需要时随时可以控制车辆。","p":"对。成年人坐在你旁边。"},"vi":{"q":"Ở Georgia, khi người có giấy phép tập lái đang lái xe, người lớn giám sát phải ngồi ở đâu?","o":["Ở ghế ngồi cạnh người lái","Ở ghế sau","Bất kỳ chỗ nào trong xe","Trong một xe khác chạy phía sau"],"h1":"Người lớn phải ngồi đủ gần để điều khiển xe khi cần.","h2":"Ở Georgia, người lớn giám sát phải ngồi ở ghế cạnh người lái, sẵn sàng điều khiển xe nếu cần.","p":"Đúng. Người lớn ngồi cạnh bạn."},"tl":{"q":"Sa Georgia, saan dapat umupo ang nagbabantay na adult kapag nagmamaneho ang may learner's permit?","o":["Sa upuang katabi ng driver","Sa likod na upuan","Kahit saan sa kotse","Sa ibang kotse na sumusunod sa likod"],"h1":"Dapat sapat na malapit ang adult para makontrol ang kotse.","h2":"Sa Georgia, ang nagbabantay na adult ay dapat umupo sa upuang katabi ng driver, handang kontrolin ang kotse kung kailangan.","p":"Tama. Ang adult ay nakaupo sa tabi mo."},"ar":{"q":"في Georgia، أين يجب أن يجلس الشخص البالغ المشرف عندما يقود صاحب تصريح التعلّم؟","o":["في المقعد الذي بجانب السائق","في المقعد الخلفي","في أي مكان في السيارة","في سيارة أخرى تسير خلفه"],"h1":"يجب أن يكون البالغ قريبًا بما يكفي ليتحكم في السيارة.","h2":"في Georgia يجب أن يجلس البالغ المشرف في المقعد الذي بجانب السائق، مستعدًا للتحكم في السيارة عند الحاجة.","p":"صحيح. البالغ يجلس بجانبك."},"ref":{"doc":"GA","page":8}},{"id":"ga-004","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, how long must a teen hold the learner's permit before taking the road test for a Class D license?","o":["3 months","6 months","One year and one day","Two years"],"h1":"It is a little more than one full year.","h2":"A Georgia teen must hold the learner's permit for one year and one day before taking the Class D road test.","p":"Right. One year and one day."},"es":{"q":"En Georgia, ¿cuánto tiempo debe tener un adolescente el permiso de aprendiz antes del examen de manejo para la licencia Clase D?","o":["3 meses","6 meses","Un año y un día","Dos años"],"h1":"Es un poco más de un año completo.","h2":"Un adolescente en Georgia debe tener el permiso de aprendiz durante un año y un día antes del examen de manejo para la licencia Clase D.","p":"Correcto. Un año y un día."},"zh":{"q":"在 Georgia，青少年必须持有学习驾照多久，才能参加 Class D 驾照路考？","o":["3 个月","6 个月","一年零一天","两年"],"h1":"它比整整一年多一点。","h2":"Georgia 的青少年必须持有学习驾照一年零一天，才能参加 Class D 路考。","p":"对。一年零一天。"},"vi":{"q":"Ở Georgia, thanh thiếu niên phải giữ giấy phép tập lái bao lâu trước khi thi lái xe trên đường để lấy bằng Class D?","o":["3 tháng","6 tháng","Một năm và một ngày","Hai năm"],"h1":"Nó dài hơn một năm tròn một chút.","h2":"Thanh thiếu niên ở Georgia phải giữ giấy phép tập lái một năm và một ngày trước khi thi lái xe trên đường để lấy bằng Class D.","p":"Đúng. Một năm và một ngày."},"tl":{"q":"Sa Georgia, gaano katagal dapat hawak ng teen ang learner's permit bago kumuha ng road test para sa Class D license?","o":["3 buwan","6 na buwan","Isang taon at isang araw","Dalawang taon"],"h1":"Medyo mahigit ito sa isang buong taon.","h2":"Ang teen sa Georgia ay dapat may hawak na learner's permit nang isang taon at isang araw bago kumuha ng road test para sa Class D.","p":"Tama. Isang taon at isang araw."},"ar":{"q":"في Georgia، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل أداء اختبار القيادة على الطريق لرخصة Class D؟","o":["3 أشهر","6 أشهر","سنة واحدة ويوم واحد","سنتان"],"h1":"المدة أكثر قليلًا من سنة كاملة.","h2":"يجب على المراهق في Georgia أن يحمل تصريح التعلّم سنة واحدة ويومًا واحدًا قبل أداء اختبار القيادة على الطريق لرخصة Class D.","p":"صحيح. سنة واحدة ويوم واحد."},"ref":{"doc":"GA","page":8}},{"id":"ga-005","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, what is the youngest age to take the road test for a Class D license?","o":["15 years old","16 years old","17 years old","18 years old"],"h1":"It is one year after the youngest age for a learner's permit.","h2":"In Georgia you can take the road test for a Class D license once you turn 16 and have held your permit long enough.","p":"Right. The Class D road test starts at 16."},"es":{"q":"En Georgia, ¿cuál es la edad mínima para hacer el examen de manejo para la licencia Clase D?","o":["15 años","16 años","17 años","18 años"],"h1":"Es un año después de la edad mínima para el permiso de aprendiz.","h2":"En Georgia usted puede hacer el examen de manejo para la licencia Clase D cuando cumple 16 años y ha tenido el permiso el tiempo necesario.","p":"Correcto. El examen para la Clase D empieza a los 16."},"zh":{"q":"在 Georgia，最小几岁可以参加 Class D 驾照路考？","o":["15 岁","16 岁","17 岁","18 岁"],"h1":"它比拿学习驾照的最小年龄晚一年。","h2":"在 Georgia，你满 16 岁、而且持有学习驾照够久以后，就可以参加 Class D 驾照路考。","p":"对。Class D 路考从 16 岁开始。"},"vi":{"q":"Ở Georgia, tuổi nhỏ nhất để thi lái xe trên đường lấy bằng Class D là bao nhiêu?","o":["15 tuổi","16 tuổi","17 tuổi","18 tuổi"],"h1":"Nó là một năm sau tuổi nhỏ nhất để lấy giấy phép tập lái.","h2":"Ở Georgia, bạn có thể thi lái xe trên đường để lấy bằng Class D khi bạn đủ 16 tuổi và đã giữ giấy phép tập lái đủ lâu.","p":"Đúng. Thi lái xe Class D bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Georgia, ano ang pinakabatang edad para kumuha ng road test para sa Class D license?","o":["15 taong gulang","16 taong gulang","17 taong gulang","18 taong gulang"],"h1":"Isang taon ito pagkatapos ng pinakabatang edad para sa learner's permit.","h2":"Sa Georgia, puwede kang kumuha ng road test para sa Class D license kapag 16 ka na at sapat na ang tagal ng paghawak mo ng permit.","p":"Tama. Ang road test para sa Class D ay nagsisimula sa 16."},"ar":{"q":"في Georgia، ما أصغر عمر لأداء اختبار القيادة على الطريق لرخصة Class D؟","o":["15 سنة","16 سنة","17 سنة","18 سنة"],"h1":"يأتي بعد سنة واحدة من أصغر عمر لتصريح التعلّم.","h2":"في Georgia يمكنك أداء اختبار القيادة على الطريق لرخصة Class D عندما يصبح عمرك 16 سنة وتكون قد حملت التصريح مدة كافية.","p":"صحيح. اختبار القيادة لرخصة Class D يبدأ من عمر 16 سنة."},"ref":{"doc":"GA","page":8}},{"id":"ga-006","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, how many hours of supervised driving must a 16- or 17-year-old complete for a Class D license?","o":["20 hours","30 hours","40 hours","65 hours"],"h1":"It is more than 30 and less than 50.","h2":"Under Joshua's Law, a Georgia teen needs at least 40 hours of supervised driving before getting a Class D license.","p":"Right. Georgia asks for 40 hours of supervised driving."},"es":{"q":"En Georgia, ¿cuántas horas de manejo supervisado debe completar un joven de 16 o 17 años para la licencia Clase D?","o":["20 horas","30 horas","40 horas","65 horas"],"h1":"Son más de 30 y menos de 50.","h2":"Según la Ley de Joshua, un adolescente en Georgia necesita por lo menos 40 horas de manejo supervisado antes de obtener la licencia Clase D.","p":"Correcto. Georgia pide 40 horas de manejo supervisado."},"zh":{"q":"在 Georgia，16 岁或 17 岁的人拿 Class D 驾照，必须完成多少小时有人监督的驾驶？","o":["20 小时","30 小时","40 小时","65 小时"],"h1":"它比 30 多，比 50 少。","h2":"根据 Joshua's Law，Georgia 的青少年拿 Class D 驾照前，至少需要 40 小时有人监督的驾驶。","p":"对。Georgia 要求 40 小时有人监督的驾驶。"},"vi":{"q":"Ở Georgia, người 16 hoặc 17 tuổi phải lái xe có người giám sát bao nhiêu giờ để lấy bằng Class D?","o":["20 giờ","30 giờ","40 giờ","65 giờ"],"h1":"Nó nhiều hơn 30 và ít hơn 50.","h2":"Theo Luật Joshua (Joshua's Law), thanh thiếu niên ở Georgia cần ít nhất 40 giờ lái xe có người giám sát trước khi lấy bằng Class D.","p":"Đúng. Georgia yêu cầu 40 giờ lái xe có người giám sát."},"tl":{"q":"Sa Georgia, ilang oras ng pagmamaneho na may nagbabantay ang dapat tapusin ng 16 o 17 taong gulang para sa Class D license?","o":["20 oras","30 oras","40 oras","65 oras"],"h1":"Higit ito sa 30 at kulang sa 50.","h2":"Ayon sa Joshua's Law, ang teen sa Georgia ay kailangan ng hindi bababa sa 40 oras ng pagmamaneho na may nagbabantay bago makakuha ng Class D license.","p":"Tama. Humihingi ang Georgia ng 40 oras ng pagmamaneho na may nagbabantay."},"ar":{"q":"في Georgia، كم ساعة من القيادة تحت الإشراف يجب أن يكملها من عمره 16 أو 17 سنة للحصول على رخصة Class D؟","o":["20 ساعة","30 ساعة","40 ساعة","65 ساعة"],"h1":"العدد أكثر من 30 وأقل من 50.","h2":"حسب قانون جوشوا (Joshua's Law)، يحتاج المراهق في Georgia إلى 40 ساعة على الأقل من القيادة تحت الإشراف قبل الحصول على رخصة Class D.","p":"صحيح. تطلب Georgia 40 ساعة من القيادة تحت الإشراف."},"ref":{"doc":"GA","page":8}},{"id":"ga-007","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, how many of the required supervised driving hours must be at night?","o":["6 hours","2 hours","10 hours","20 hours"],"h1":"It is a small part of the total, less than 10.","h2":"Of the 40 supervised hours a Georgia teen needs, at least 6 hours must be driven at night.","p":"Right. At least 6 of the hours are at night."},"es":{"q":"En Georgia, ¿cuántas de las horas de manejo supervisado deben ser de noche?","o":["6 horas","2 horas","10 horas","20 horas"],"h1":"Es una parte pequeña del total, menos de 10.","h2":"De las 40 horas supervisadas que necesita un adolescente en Georgia, por lo menos 6 horas deben ser de noche.","p":"Correcto. Por lo menos 6 horas son de noche."},"zh":{"q":"在 Georgia，规定的有人监督驾驶时间里，有多少小时必须在晚上？","o":["6 小时","2 小时","10 小时","20 小时"],"h1":"它是全部时间的一小部分，少于 10。","h2":"在 Georgia 青少年需要的 40 小时有人监督的驾驶里，至少 6 小时必须在晚上开。","p":"对。至少 6 小时在晚上。"},"vi":{"q":"Ở Georgia, trong số giờ lái xe có người giám sát bắt buộc, bao nhiêu giờ phải lái vào ban đêm?","o":["6 giờ","2 giờ","10 giờ","20 giờ"],"h1":"Nó là một phần nhỏ của tổng số, ít hơn 10.","h2":"Trong 40 giờ lái xe có người giám sát mà thanh thiếu niên ở Georgia cần, ít nhất 6 giờ phải lái vào ban đêm.","p":"Đúng. Ít nhất 6 giờ là vào ban đêm."},"tl":{"q":"Sa Georgia, ilan sa mga kailangang oras ng pagmamaneho na may nagbabantay ang dapat sa gabi?","o":["6 na oras","2 oras","10 oras","20 oras"],"h1":"Maliit na bahagi ito ng kabuuan, kulang sa 10.","h2":"Sa 40 oras na may nagbabantay na kailangan ng teen sa Georgia, hindi bababa sa 6 na oras ang dapat sa gabi.","p":"Tama. Hindi bababa sa 6 na oras ang sa gabi."},"ar":{"q":"في Georgia، كم ساعة من ساعات القيادة تحت الإشراف المطلوبة يجب أن تكون في الليل؟","o":["6 ساعات","ساعتان (2)","10 ساعات","20 ساعة"],"h1":"هي جزء صغير من المجموع، أقل من 10.","h2":"من بين الـ 40 ساعة تحت الإشراف التي يحتاجها المراهق في Georgia، يجب أن تكون 6 ساعات على الأقل في الليل.","p":"صحيح. 6 ساعات على الأقل تكون في الليل."},"ref":{"doc":"GA","page":8}},{"id":"ga-008","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, how long is the approved driver education course (classroom or online) that Joshua's Law requires?","o":["5 hours","10 hours","20 hours","30 hours"],"h1":"It is the largest number in the list.","h2":"Joshua's Law requires Georgia teens to complete a 30-hour approved driver education course, in a classroom or online.","p":"Right. The course is 30 hours."},"es":{"q":"En Georgia, ¿cuántas horas dura el curso aprobado de educación vial (en clase o en línea) que exige la Ley de Joshua?","o":["5 horas","10 horas","20 horas","30 horas"],"h1":"Es el número más grande de la lista.","h2":"La Ley de Joshua exige que los adolescentes en Georgia completen un curso aprobado de educación vial de 30 horas, en clase o en línea.","p":"Correcto. El curso es de 30 horas."},"zh":{"q":"在 Georgia，Joshua's Law 要求的认可驾驶教育课程（课堂或网上）有多长？","o":["5 小时","10 小时","20 小时","30 小时"],"h1":"它是选项里最大的数字。","h2":"Joshua's Law 要求 Georgia 的青少年完成 30 小时认可的驾驶教育课程，在课堂或网上都可以。","p":"对。课程是 30 小时。"},"vi":{"q":"Ở Georgia, khóa học lái xe được chấp thuận (học trên lớp hoặc trực tuyến) mà Luật Joshua yêu cầu dài bao lâu?","o":["5 giờ","10 giờ","20 giờ","30 giờ"],"h1":"Nó là số lớn nhất trong danh sách.","h2":"Luật Joshua (Joshua's Law) yêu cầu thanh thiếu niên ở Georgia học xong một khóa học lái xe được chấp thuận dài 30 giờ, trên lớp hoặc trực tuyến.","p":"Đúng. Khóa học dài 30 giờ."},"tl":{"q":"Sa Georgia, gaano kahaba ang aprubadong driver education course (sa klase o online) na hinihingi ng Joshua's Law?","o":["5 oras","10 oras","20 oras","30 oras"],"h1":"Ito ang pinakamalaking numero sa listahan.","h2":"Hinihingi ng Joshua's Law na tapusin ng mga teen sa Georgia ang 30 oras na aprubadong driver education course, sa klase o online.","p":"Tama. 30 oras ang course."},"ar":{"q":"في Georgia، كم طول دورة تعليم القيادة المعتمدة (في الصف أو عبر الإنترنت) التي يطلبها قانون جوشوا؟","o":["5 ساعات","10 ساعات","20 ساعة","30 ساعة"],"h1":"هو أكبر رقم في القائمة.","h2":"يطلب قانون جوشوا (Joshua's Law) من المراهقين في Georgia إكمال دورة معتمدة لتعليم القيادة مدتها 30 ساعة، في الصف أو عبر الإنترنت.","p":"صحيح. الدورة مدتها 30 ساعة."},"ref":{"doc":"GA","page":8}},{"id":"ga-009","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, besides the driver education course, what behind-the-wheel training does Joshua's Law accept?","o":["1 hour with any adult","6 hours with a certified instructor, or the DDS parent-teen driving guide","A video course only","No behind-the-wheel training is needed"],"h1":"There are two ways to do it: one with a professional, one with a parent.","h2":"Joshua's Law accepts 6 hours of driving with a certified instructor, or completing the DDS parent-teen driving guide.","p":"Right. Six hours with an instructor, or the parent-teen guide."},"es":{"q":"En Georgia, además del curso de educación vial, ¿qué práctica al volante acepta la Ley de Joshua?","o":["1 hora con cualquier adulto","6 horas con un instructor certificado, o la guía de manejo para padres e hijos del DDS","Solo un curso en video","No hace falta práctica al volante"],"h1":"Hay dos maneras: una con un profesional y otra con un padre o madre.","h2":"La Ley de Joshua acepta 6 horas de manejo con un instructor certificado, o completar la guía de manejo para padres e hijos del DDS.","p":"Correcto. Seis horas con instructor, o la guía para padres e hijos."},"zh":{"q":"在 Georgia，除了驾驶教育课程，Joshua's Law 接受哪一种实际上车驾驶训练？","o":["和任何成年人开 1 小时","和有证书的教练开 6 小时，或完成 DDS 的家长与青少年驾驶指南","只有视频课程","不需要实际上车训练"],"h1":"有两种方法：一种和专业人员，一种和父母。","h2":"Joshua's Law 接受和有证书的教练开车 6 小时，或完成 DDS 的家长与青少年驾驶指南（parent-teen driving guide）。","p":"对。和教练开六小时，或完成家长与青少年指南。"},"vi":{"q":"Ở Georgia, ngoài khóa học lái xe, Luật Joshua chấp nhận cách tập lái thực tế nào?","o":["1 giờ với bất kỳ người lớn nào","6 giờ với huấn luyện viên có chứng chỉ, hoặc sách hướng dẫn lái xe cho cha mẹ và con của DDS","Chỉ một khóa học bằng video","Không cần tập lái thực tế"],"h1":"Có hai cách: một cách với người chuyên nghiệp, một cách với cha hoặc mẹ.","h2":"Luật Joshua chấp nhận 6 giờ lái xe với huấn luyện viên có chứng chỉ, hoặc hoàn thành sách hướng dẫn lái xe cho cha mẹ và con của DDS (parent-teen driving guide).","p":"Đúng. Sáu giờ với huấn luyện viên, hoặc sách hướng dẫn cho cha mẹ và con."},"tl":{"q":"Sa Georgia, bukod sa driver education course, anong behind-the-wheel training ang tinatanggap ng Joshua's Law?","o":["1 oras kasama ang kahit sinong adult","6 na oras kasama ang certified instructor, o ang DDS parent-teen driving guide","Video course lang","Hindi kailangan ng behind-the-wheel training"],"h1":"May dalawang paraan: isa kasama ang propesyonal, isa kasama ang magulang.","h2":"Tinatanggap ng Joshua's Law ang 6 na oras ng pagmamaneho kasama ang certified instructor, o ang pagtapos ng DDS parent-teen driving guide.","p":"Tama. Anim na oras kasama ang instructor, o ang parent-teen guide."},"ar":{"q":"في Georgia، إلى جانب دورة تعليم القيادة، ما التدريب العملي خلف المقود الذي يقبله قانون جوشوا؟","o":["ساعة واحدة مع أي شخص بالغ","6 ساعات مع مدرب معتمد، أو دليل القيادة للوالدين والمراهق من DDS","دورة فيديو فقط","لا حاجة إلى تدريب عملي"],"h1":"هناك طريقتان: واحدة مع شخص محترف، وواحدة مع أحد الوالدين.","h2":"يقبل قانون جوشوا 6 ساعات من القيادة مع مدرب معتمد، أو إكمال دليل القيادة للوالدين والمراهق من DDS (parent-teen driving guide).","p":"صحيح. ست ساعات مع مدرب، أو دليل الوالدين والمراهق."},"ref":{"doc":"GA","page":8}},{"id":"ga-010","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, how does a teen show that the 40 hours of supervised driving were completed?","o":["The teen sends photos of the drives","A police officer rides along","A parent or guardian confirms it in writing at DDS","Nothing is needed"],"h1":"An adult who knows the teen gives their word in writing.","h2":"In Georgia no driving log is needed: a parent or guardian confirms in writing at DDS that the teen drove the 40 hours, including 6 at night.","p":"Right. A parent or guardian confirms the hours in writing."},"es":{"q":"En Georgia, ¿cómo demuestra un adolescente que completó las 40 horas de manejo supervisado?","o":["El adolescente envía fotos de los viajes","Un policía lo acompaña","Un padre o tutor lo confirma por escrito en el DDS","No hace falta nada"],"h1":"Un adulto que conoce al adolescente lo confirma por escrito.","h2":"En Georgia no se necesita un registro de manejo: un padre o tutor confirma por escrito en el DDS que el adolescente manejó las 40 horas, incluidas 6 de noche.","p":"Correcto. Un padre o tutor confirma las horas por escrito."},"zh":{"q":"在 Georgia，青少年怎样证明完成了 40 小时有人监督的驾驶？","o":["青少年寄开车的照片","警察同车","父母或监护人在 DDS 用书面方式确认","什么都不需要"],"h1":"一位了解这个青少年的成年人用书面方式保证。","h2":"在 Georgia 不需要驾驶记录本：父母或监护人在 DDS 用书面方式确认青少年开了 40 小时，其中 6 小时在晚上。","p":"对。父母或监护人用书面方式确认驾驶时间。"},"vi":{"q":"Ở Georgia, thanh thiếu niên chứng minh đã lái đủ 40 giờ có người giám sát bằng cách nào?","o":["Thanh thiếu niên gửi ảnh các lần lái xe","Một cảnh sát đi cùng xe","Cha mẹ hoặc người giám hộ xác nhận bằng văn bản tại DDS","Không cần gì cả"],"h1":"Một người lớn biết rõ thanh thiếu niên đó cam kết bằng văn bản.","h2":"Ở Georgia không cần sổ ghi chép lái xe: cha mẹ hoặc người giám hộ xác nhận bằng văn bản tại DDS rằng thanh thiếu niên đã lái 40 giờ, gồm 6 giờ ban đêm.","p":"Đúng. Cha mẹ hoặc người giám hộ xác nhận số giờ bằng văn bản."},"tl":{"q":"Sa Georgia, paano ipinapakita ng teen na natapos ang 40 oras ng pagmamaneho na may nagbabantay?","o":["Nagpapadala ang teen ng mga litrato ng pagmamaneho","Sumasakay ang isang pulis","Kinukumpirma ito nang nakasulat ng magulang o guardian sa DDS","Walang kailangan"],"h1":"Isang adult na kilala ang teen ang nagbibigay ng nakasulat na pangako.","h2":"Sa Georgia, hindi kailangan ng driving log: kinukumpirma nang nakasulat ng magulang o guardian sa DDS na nakapagmaneho ang teen ng 40 oras, kasama ang 6 sa gabi.","p":"Tama. Kinukumpirma ng magulang o guardian ang mga oras nang nakasulat."},"ar":{"q":"في Georgia، كيف يُثبت المراهق أنه أكمل الـ 40 ساعة من القيادة تحت الإشراف؟","o":["يرسل المراهق صورًا للرحلات","يركب معه شرطي","يؤكد أحد الوالدين أو الوصي ذلك كتابةً في DDS","لا يلزم شيء"],"h1":"شخص بالغ يعرف المراهق يتعهّد بذلك كتابةً.","h2":"في Georgia لا يلزم سجل للقيادة: يؤكد أحد الوالدين أو الوصي كتابةً في DDS أن المراهق قاد 40 ساعة، منها 6 ساعات في الليل.","p":"صحيح. أحد الوالدين أو الوصي يؤكد الساعات كتابةً."},"ref":{"doc":"GA","page":8}},{"id":"ga-011","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, what license must the adult who supervises practice driving hold?","o":["A valid license to drive a regular car (Class C)","A learner's permit","Any license from any country, even expired","No license is needed"],"h1":"It is the full adult license, and it must not be expired.","h2":"In Georgia the adult who supervises practice driving must be at least 21 and hold a valid license to drive a Class C vehicle, a regular car.","p":"Right. The supervisor needs a valid Class C license."},"es":{"q":"En Georgia, ¿qué licencia debe tener el adulto que supervisa la práctica de manejo?","o":["Una licencia vigente para manejar un carro normal (Clase C)","Un permiso de aprendiz","Cualquier licencia de cualquier país, aunque esté vencida","No necesita licencia"],"h1":"Es la licencia completa de adulto, y no puede estar vencida.","h2":"En Georgia el adulto que supervisa la práctica debe tener por lo menos 21 años y una licencia vigente para manejar un vehículo Clase C, un carro normal.","p":"Correcto. El supervisor necesita una licencia Clase C vigente."},"zh":{"q":"在 Georgia，监督练习开车的成年人必须持有什么驾照？","o":["可以开普通小汽车的有效驾照（Class C）","学习驾照","任何国家的任何驾照，过期的也可以","不需要驾照"],"h1":"它是成年人的正式驾照，而且不能过期。","h2":"在 Georgia，监督练习开车的成年人必须至少 21 岁，并持有可以开 Class C 车辆（普通小汽车）的有效驾照。","p":"对。监督的人需要有效的 Class C 驾照。"},"vi":{"q":"Ở Georgia, người lớn giám sát việc tập lái phải có bằng lái gì?","o":["Bằng lái còn hạn để lái xe hơi thường (Class C)","Một giấy phép tập lái","Bất kỳ bằng lái nào của nước nào, kể cả hết hạn","Không cần bằng lái"],"h1":"Đó là bằng lái đầy đủ của người lớn, và không được hết hạn.","h2":"Ở Georgia, người lớn giám sát việc tập lái phải ít nhất 21 tuổi và có bằng lái còn hạn để lái xe Class C, tức là xe hơi thường.","p":"Đúng. Người giám sát cần bằng lái Class C còn hạn."},"tl":{"q":"Sa Georgia, anong lisensya ang dapat hawak ng adult na nagbabantay sa praktis na pagmamaneho?","o":["Valid na lisensya para magmaneho ng karaniwang kotse (Class C)","Learner's permit","Kahit anong lisensya mula sa kahit anong bansa, kahit expired","Hindi kailangan ng lisensya"],"h1":"Ito ang buong lisensya ng adult, at hindi ito dapat expired.","h2":"Sa Georgia, ang adult na nagbabantay sa praktis na pagmamaneho ay dapat hindi bababa sa 21 taong gulang at may valid na lisensya para magmaneho ng Class C na sasakyan, isang karaniwang kotse.","p":"Tama. Kailangan ng nagbabantay ang valid na Class C license."},"ar":{"q":"في Georgia، ما الرخصة التي يجب أن يحملها البالغ الذي يشرف على التدريب على القيادة؟","o":["رخصة سارية لقيادة سيارة عادية (Class C)","تصريح تعلّم القيادة","أي رخصة من أي بلد، حتى لو كانت منتهية","لا حاجة إلى رخصة"],"h1":"هي رخصة البالغين الكاملة، ويجب ألا تكون منتهية.","h2":"في Georgia يجب أن يكون البالغ الذي يشرف على التدريب على القيادة عمره 21 سنة على الأقل ويحمل رخصة سارية لقيادة مركبة Class C، أي سيارة عادية.","p":"صحيح. المشرف يحتاج إلى رخصة Class C سارية."},"ref":{"doc":"GA","page":8}},{"id":"ga-012","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, during the first six months with a Class D license, who may ride with the teen driver?","o":["Up to three friends","One friend under 21","Anyone, with no limit","Only immediate family members"],"h1":"At the start, the rule is the strictest it will ever be.","h2":"During the first six months with a Georgia Class D license, the only passengers allowed are immediate family members.","p":"Right. Only immediate family at first."},"es":{"q":"En Georgia, durante los primeros seis meses con licencia Clase D, ¿quién puede ir con el conductor adolescente?","o":["Hasta tres amigos","Un amigo menor de 21 años","Cualquier persona, sin límite","Solo familiares inmediatos"],"h1":"Al principio, la regla es la más estricta de todas.","h2":"Durante los primeros seis meses con licencia Clase D en Georgia, solo pueden ir como pasajeros los familiares inmediatos.","p":"Correcto. Al principio, solo familiares inmediatos."},"zh":{"q":"在 Georgia，拿到 Class D 驾照的前六个月，谁可以坐青少年司机的车？","o":["最多三位朋友","一位 21 岁以下的朋友","任何人，没有限制","只有直系家人"],"h1":"一开始的规定是最严格的。","h2":"拿到 Georgia Class D 驾照的前六个月，只允许直系家人坐车。","p":"对。一开始只能载直系家人。"},"vi":{"q":"Ở Georgia, trong sáu tháng đầu có bằng Class D, ai được ngồi cùng xe với người lái tuổi thiếu niên?","o":["Tối đa ba người bạn","Một người bạn dưới 21 tuổi","Bất kỳ ai, không giới hạn","Chỉ người thân trong gia đình gần (immediate family)"],"h1":"Lúc mới bắt đầu, quy định là nghiêm nhất.","h2":"Trong sáu tháng đầu có bằng Class D ở Georgia, chỉ người thân trong gia đình gần được ngồi cùng xe.","p":"Đúng. Lúc đầu chỉ có người thân trong gia đình gần."},"tl":{"q":"Sa Georgia, sa unang anim na buwan na may Class D license, sino ang puwedeng sumakay kasama ng teen na driver?","o":["Hanggang tatlong kaibigan","Isang kaibigan na wala pang 21","Kahit sino, walang limitasyon","Mga malapit na kapamilya lang (immediate family)"],"h1":"Sa simula, pinakamahigpit ang patakaran.","h2":"Sa unang anim na buwan na may Georgia Class D license, mga malapit na kapamilya lang ang puwedeng pasahero.","p":"Tama. Malapit na kapamilya lang sa simula."},"ar":{"q":"في Georgia، خلال الأشهر الستة الأولى برخصة Class D، من يمكنه الركوب مع السائق المراهق؟","o":["حتى ثلاثة أصدقاء","صديق واحد عمره أقل من 21 سنة","أي شخص، بلا حدود","أفراد العائلة المباشرة فقط (immediate family)"],"h1":"في البداية، تكون القاعدة في أشد حالاتها.","h2":"خلال الأشهر الستة الأولى برخصة Class D في Georgia، الركاب المسموح بهم هم أفراد العائلة المباشرة فقط.","p":"صحيح. أفراد العائلة المباشرة فقط في البداية."},"ref":{"doc":"GA","page":8}},{"id":"ga-013","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, during the second six months with a Class D license, how many passengers under 21 who are not family may ride with the teen?","o":["None","One","Two","Five"],"h1":"The limit opens up a little, but only a little.","h2":"In the second six months with a Georgia Class D license, the teen may carry no more than one passenger under 21 who is not family.","p":"Right. One non-family passenger under 21."},"es":{"q":"En Georgia, durante el segundo semestre con licencia Clase D, ¿cuántos pasajeros menores de 21 años que no son familia pueden ir con el adolescente?","o":["Ninguno","Uno","Dos","Cinco"],"h1":"El límite se abre un poco, pero muy poco.","h2":"En el segundo semestre con licencia Clase D en Georgia, el adolescente puede llevar como máximo un pasajero menor de 21 años que no sea familia.","p":"Correcto. Un pasajero menor de 21 que no es familia."},"zh":{"q":"在 Georgia，拿到 Class D 驾照的第二个六个月，青少年可以载多少位 21 岁以下、不是家人的乘客？","o":["一位都不行","一位","两位","五位"],"h1":"限制放宽了，但只放宽一点点。","h2":"拿到 Georgia Class D 驾照的第二个六个月，青少年最多只能载一位 21 岁以下、不是家人的乘客。","p":"对。一位 21 岁以下、不是家人的乘客。"},"vi":{"q":"Ở Georgia, trong sáu tháng thứ hai có bằng Class D, bao nhiêu hành khách dưới 21 tuổi không phải người nhà được ngồi cùng xe với thanh thiếu niên?","o":["Không ai","Một","Hai","Năm"],"h1":"Giới hạn được nới ra một chút, nhưng chỉ một chút.","h2":"Trong sáu tháng thứ hai có bằng Class D ở Georgia, thanh thiếu niên chỉ được chở tối đa một hành khách dưới 21 tuổi không phải người nhà.","p":"Đúng. Một hành khách dưới 21 tuổi không phải người nhà."},"tl":{"q":"Sa Georgia, sa ikalawang anim na buwan na may Class D license, ilang pasahero na wala pang 21 at hindi kapamilya ang puwedeng sumakay kasama ng teen?","o":["Wala","Isa","Dalawa","Lima"],"h1":"Lumuluwag nang kaunti ang limitasyon, pero kaunti lang.","h2":"Sa ikalawang anim na buwan na may Georgia Class D license, hindi hihigit sa isang pasahero na wala pang 21 at hindi kapamilya ang puwedeng isakay ng teen.","p":"Tama. Isang pasahero na wala pang 21 at hindi kapamilya."},"ar":{"q":"في Georgia، خلال الأشهر الستة الثانية برخصة Class D، كم راكبًا عمره أقل من 21 سنة وليس من العائلة يمكنه الركوب مع المراهق؟","o":["لا أحد","واحد","اثنان","خمسة"],"h1":"الحد يتّسع قليلًا، ولكن قليلًا فقط.","h2":"في الأشهر الستة الثانية برخصة Class D في Georgia، لا يجوز للمراهق أن يحمل أكثر من راكب واحد عمره أقل من 21 سنة وليس من العائلة.","p":"صحيح. راكب واحد عمره أقل من 21 سنة وليس من العائلة."},"ref":{"doc":"GA","page":8}},{"id":"ga-014","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, after one year with a Class D license, how many passengers under 21 who are not family may ride with the teen?","o":["One","Two","Three","Any number"],"h1":"It is more than in the second six months, but there is still a limit.","h2":"After the first year with a Georgia Class D license, the teen may carry up to three passengers under 21 who are not family.","p":"Right. Up to three after the first year."},"es":{"q":"En Georgia, después de un año con licencia Clase D, ¿cuántos pasajeros menores de 21 años que no son familia pueden ir con el adolescente?","o":["Uno","Dos","Tres","Cualquier cantidad"],"h1":"Son más que en el segundo semestre, pero todavía hay un límite.","h2":"Después del primer año con licencia Clase D en Georgia, el adolescente puede llevar hasta tres pasajeros menores de 21 años que no sean familia.","p":"Correcto. Hasta tres después del primer año."},"zh":{"q":"在 Georgia，拿到 Class D 驾照一年以后，青少年可以载多少位 21 岁以下、不是家人的乘客？","o":["一位","两位","三位","任何人数"],"h1":"它比第二个六个月多，但还是有限制。","h2":"拿到 Georgia Class D 驾照一年以后，青少年最多可以载三位 21 岁以下、不是家人的乘客。","p":"对。第一年以后最多三位。"},"vi":{"q":"Ở Georgia, sau một năm có bằng Class D, bao nhiêu hành khách dưới 21 tuổi không phải người nhà được ngồi cùng xe với thanh thiếu niên?","o":["Một","Hai","Ba","Bao nhiêu cũng được"],"h1":"Nhiều hơn trong sáu tháng thứ hai, nhưng vẫn có giới hạn.","h2":"Sau năm đầu tiên có bằng Class D ở Georgia, thanh thiếu niên được chở tối đa ba hành khách dưới 21 tuổi không phải người nhà.","p":"Đúng. Tối đa ba người sau năm đầu tiên."},"tl":{"q":"Sa Georgia, pagkatapos ng isang taon na may Class D license, ilang pasahero na wala pang 21 at hindi kapamilya ang puwedeng sumakay kasama ng teen?","o":["Isa","Dalawa","Tatlo","Kahit ilan"],"h1":"Mas marami ito kaysa sa ikalawang anim na buwan, pero may limitasyon pa rin.","h2":"Pagkatapos ng unang taon na may Georgia Class D license, puwedeng magsakay ang teen ng hanggang tatlong pasahero na wala pang 21 at hindi kapamilya.","p":"Tama. Hanggang tatlo pagkatapos ng unang taon."},"ar":{"q":"في Georgia، بعد سنة واحدة برخصة Class D، كم راكبًا عمره أقل من 21 سنة وليس من العائلة يمكنه الركوب مع المراهق؟","o":["واحد","اثنان","ثلاثة","أي عدد"],"h1":"العدد أكثر مما في الأشهر الستة الثانية، لكن ما زال هناك حد.","h2":"بعد السنة الأولى برخصة Class D في Georgia، يمكن للمراهق أن يحمل حتى ثلاثة ركاب أعمارهم أقل من 21 سنة وليسوا من العائلة.","p":"صحيح. حتى ثلاثة بعد السنة الأولى."},"ref":{"doc":"GA","page":8}},{"id":"ga-015","scope":"GA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Georgia, what does the hands-free law say about holding a phone while driving?","o":["You may not hold the phone or support it with any part of your body","You may hold it if you drive slowly","You may hold it on city streets only","You may hold it if you are over 21"],"h1":"The law is named after what your hands must be.","h2":"Georgia's hands-free law makes it illegal for any driver to hold a phone or support it with any part of the body while driving.","p":"Right. In Georgia the phone stays out of your hands."},"es":{"q":"En Georgia, ¿qué dice la ley de manos libres sobre sostener el teléfono mientras maneja?","o":["No puede sostener el teléfono ni apoyarlo con ninguna parte del cuerpo","Puede sostenerlo si maneja despacio","Puede sostenerlo solo en calles de la ciudad","Puede sostenerlo si tiene más de 21 años"],"h1":"El nombre de la ley dice cómo deben estar sus manos.","h2":"La ley de manos libres de Georgia prohíbe que cualquier conductor sostenga el teléfono o lo apoye con alguna parte del cuerpo mientras maneja.","p":"Correcto. En Georgia el teléfono no va en la mano."},"zh":{"q":"在 Georgia，免持（hands-free）法对开车时拿手机有什么规定？","o":["你不能拿着手机，也不能用身体任何部位撑着它","如果开得慢就可以拿着","只在市区街道可以拿着","如果你超过 21 岁就可以拿着"],"h1":"这条法律的名字说明了你的手必须怎样。","h2":"Georgia 的免持法规定，任何司机开车时用手拿着手机，或用身体任何部位撑着手机，都是违法的。","p":"对。在 Georgia，手机不能拿在手里。"},"vi":{"q":"Ở Georgia, luật rảnh tay (hands-free law) nói gì về việc cầm điện thoại khi lái xe?","o":["Bạn không được cầm điện thoại hay đỡ nó bằng bất kỳ phần nào của cơ thể","Bạn được cầm nếu lái chậm","Bạn được cầm chỉ trên đường trong thành phố","Bạn được cầm nếu trên 21 tuổi"],"h1":"Tên của luật nói về việc tay của bạn phải như thế nào.","h2":"Luật rảnh tay của Georgia cấm mọi người lái xe cầm điện thoại hoặc đỡ nó bằng bất kỳ phần nào của cơ thể khi đang lái.","p":"Đúng. Ở Georgia, điện thoại không được nằm trong tay bạn."},"tl":{"q":"Sa Georgia, ano ang sinasabi ng hands-free law tungkol sa paghawak ng telepono habang nagmamaneho?","o":["Hindi mo puwedeng hawakan ang telepono o suportahan ito ng kahit anong bahagi ng katawan mo","Puwede mo itong hawakan kung mabagal kang magmaneho","Puwede mo itong hawakan sa mga kalye sa lungsod lang","Puwede mo itong hawakan kung lampas 21 ka na"],"h1":"Ang pangalan ng batas ay tungkol sa kung paano dapat ang mga kamay mo.","h2":"Ayon sa hands-free law ng Georgia, bawal sa kahit sinong driver na hawakan ang telepono o suportahan ito ng kahit anong bahagi ng katawan habang nagmamaneho.","p":"Tama. Sa Georgia, hindi dapat nasa kamay mo ang telepono."},"ar":{"q":"في Georgia، ماذا يقول قانون القيادة بدون استخدام اليدين (hands-free law) عن حمل الهاتف أثناء القيادة؟","o":["لا يجوز لك أن تحمل الهاتف أو تسنده بأي جزء من جسمك","يجوز لك حمله إذا كنت تقود ببطء","يجوز لك حمله في شوارع المدينة فقط","يجوز لك حمله إذا كان عمرك أكثر من 21 سنة"],"h1":"اسم القانون يتحدث عن الحالة التي يجب أن تكون عليها يداك.","h2":"قانون hands-free في Georgia يمنع أي سائق من حمل الهاتف أو إسناده بأي جزء من الجسم أثناء القيادة.","p":"صحيح. في Georgia يبقى الهاتف خارج يديك."},"ref":{"doc":"GA","page":25}},{"id":"ga-016","scope":"GA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Georgia, you use your phone for map directions while driving. Which way is allowed under the hands-free law?","o":["Holding it in your lap","Holding it in one hand","Resting it on your shoulder","In a phone holder or mount, without holding it"],"h1":"The phone must stay put without you holding it.","h2":"Georgia's hands-free law lets you use a phone for directions only when it sits in a holder or mount, not in your hand or on your body.","p":"Right. Put the phone in a holder or mount."},"es":{"q":"En Georgia, usted usa su teléfono para ver el mapa mientras maneja. ¿Qué manera permite la ley de manos libres?","o":["Sostenerlo en las piernas","Sostenerlo en una mano","Apoyarlo en el hombro","En un soporte o base, sin sostenerlo"],"h1":"El teléfono debe quedarse fijo sin que usted lo sostenga.","h2":"La ley de manos libres de Georgia le permite usar el teléfono para direcciones solo si está en un soporte o base, no en su mano ni sobre su cuerpo.","p":"Correcto. Ponga el teléfono en un soporte o base."},"zh":{"q":"在 Georgia，你开车时用手机看地图导航。根据免持法，哪一种方式是允许的？","o":["放在大腿上","用一只手拿着","靠在肩膀上","放在手机架或支架上，不用手拿"],"h1":"手机必须固定好，不用你拿着。","h2":"Georgia 的免持法只允许手机放在手机架或支架上时用来导航，不能拿在手里或放在身上。","p":"对。把手机放在手机架或支架上。"},"vi":{"q":"Ở Georgia, bạn dùng điện thoại để xem bản đồ chỉ đường khi lái xe. Cách nào được phép theo luật rảnh tay?","o":["Để nó trên đùi","Cầm nó bằng một tay","Kẹp nó trên vai","Đặt trong giá đỡ điện thoại, không cầm"],"h1":"Điện thoại phải nằm yên mà bạn không cần cầm.","h2":"Luật rảnh tay của Georgia chỉ cho phép dùng điện thoại để chỉ đường khi nó nằm trong giá đỡ, không ở trong tay hay trên người bạn.","p":"Đúng. Đặt điện thoại vào giá đỡ."},"tl":{"q":"Sa Georgia, ginagamit mo ang telepono para sa mapa at direksyon habang nagmamaneho. Aling paraan ang pinapayagan ng hands-free law?","o":["Nakapatong sa kandungan mo","Hawak ng isang kamay","Nakaipit sa balikat mo","Nasa phone holder o mount, hindi hawak"],"h1":"Dapat nakapirmi ang telepono nang hindi mo hinahawakan.","h2":"Pinapayagan ng hands-free law ng Georgia na gamitin ang telepono para sa direksyon kapag nasa holder o mount lang ito, hindi sa kamay o sa katawan mo.","p":"Tama. Ilagay ang telepono sa holder o mount."},"ar":{"q":"في Georgia، تستخدم هاتفك للخرائط والاتجاهات أثناء القيادة. ما الطريقة المسموح بها حسب قانون hands-free؟","o":["أن تضعه في حضنك","أن تحمله بيد واحدة","أن تسنده على كتفك","في حامل أو مثبّت للهاتف، دون أن تحمله"],"h1":"يجب أن يبقى الهاتف ثابتًا دون أن تحمله.","h2":"قانون hands-free في Georgia يسمح لك باستخدام الهاتف للاتجاهات فقط عندما يكون في حامل أو مثبّت، وليس في يدك أو على جسمك.","p":"صحيح. ضع الهاتف في حامل أو مثبّت."},"ref":{"doc":"GA","page":25}},{"id":"ga-017","scope":"GA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Georgia, you are driving the opposite way from a stopped school bus with flashing lights and stop signs out, on a divided highway. What must you do?","o":["Stop until the bus moves","Continue with caution; you do not have to stop","Speed up to pass quickly","Turn around"],"h1":"The divided highway is the only exception to the stopping rule.","h2":"In Georgia, drivers going the opposite way on a divided highway do not have to stop for a school bus, but they must drive with caution.","p":"Right. On a divided highway, oncoming traffic continues with caution."},"es":{"q":"En Georgia, usted va en dirección contraria a un autobús escolar detenido con luces intermitentes y señales de alto extendidas, en una carretera dividida. ¿Qué debe hacer?","o":["Detenerse hasta que el autobús avance","Seguir con precaución; no tiene que detenerse","Acelerar para pasar rápido","Dar la vuelta"],"h1":"La carretera dividida es la única excepción a la regla de detenerse.","h2":"En Georgia, los conductores que van en dirección contraria en una carretera dividida no tienen que detenerse por un autobús escolar, pero deben manejar con precaución.","p":"Correcto. En carretera dividida, el tráfico contrario sigue con precaución."},"zh":{"q":"在 Georgia，在分隔公路上，你和一辆停着、灯在闪、伸出停车牌的校车方向相反。你必须怎么做？","o":["停车，直到校车开走","小心地继续开；你不必停车","加速快点开过去","掉头"],"h1":"分隔公路是停车规定唯一的例外。","h2":"在 Georgia，在分隔公路上方向相反的司机不必为校车停车，但必须小心开车。","p":"对。在分隔公路上，对面来的车小心地继续开。"},"vi":{"q":"Ở Georgia, bạn đang lái ngược chiều với một xe buýt trường học đang dừng, đèn nhấp nháy và biển STOP bật ra, trên đường cao tốc có dải phân cách. Bạn phải làm gì?","o":["Dừng lại cho đến khi xe buýt chạy","Tiếp tục đi một cách cẩn thận; bạn không phải dừng","Tăng tốc để vượt qua nhanh","Quay đầu xe"],"h1":"Đường có dải phân cách là trường hợp ngoại lệ duy nhất của quy định phải dừng.","h2":"Ở Georgia, xe chạy ngược chiều trên đường có dải phân cách không phải dừng lại vì xe buýt trường học, nhưng phải lái thật cẩn thận.","p":"Đúng. Trên đường có dải phân cách, xe chạy ngược chiều tiếp tục đi một cách cẩn thận."},"tl":{"q":"Sa Georgia, nagmamaneho ka sa kabilang direksyon ng isang nakahintong school bus na may kumikislap na ilaw at nakalabas na STOP sign, sa divided highway. Ano ang dapat mong gawin?","o":["Huminto hanggang umandar ang bus","Magpatuloy nang maingat; hindi mo kailangang huminto","Bumilis para mabilis na makalampas","Umikot pabalik"],"h1":"Ang divided highway lang ang eksepsyon sa patakaran ng paghinto.","h2":"Sa Georgia, ang mga driver na nasa kabilang direksyon sa divided highway ay hindi kailangang huminto para sa school bus, pero dapat silang magmaneho nang maingat.","p":"Tama. Sa divided highway, ang paparating na trapiko ay nagpapatuloy nang maingat."},"ar":{"q":"في Georgia، أنت تقود في الاتجاه المعاكس لحافلة مدرسية متوقفة أضواؤها تومض ولافتات STOP مفتوحة، على طريق سريع مقسوم بفاصل. ماذا يجب أن تفعل؟","o":["تتوقف حتى تتحرك الحافلة","تستمر بحذر؛ لا يلزمك التوقف","تسرع لتتجاوز بسرعة","تستدير وترجع"],"h1":"الطريق المقسوم بفاصل هو الاستثناء الوحيد من قاعدة التوقف.","h2":"في Georgia، السائقون الذين يسيرون في الاتجاه المعاكس على طريق مقسوم بفاصل لا يلزمهم التوقف للحافلة المدرسية، لكن يجب أن يقودوا بحذر.","p":"صحيح. على الطريق المقسوم بفاصل، تستمر حركة السير القادمة بحذر."},"ref":{"doc":"GA","page":44}},{"id":"ga-018","scope":"GA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Georgia, on a road that is not divided, a school bus stops with flashing lights and stop signs out. Who must stop?","o":["Traffic in both directions","Only traffic behind the bus","Only traffic coming toward the bus","No one, if no children are seen"],"h1":"On a road with no division, nobody may pass the bus.","h2":"In Georgia, on a road that is not divided, vehicles going in either direction must stop and may not pass a stopped school bus.","p":"Right. Both directions stop."},"es":{"q":"En Georgia, en una calle que no está dividida, un autobús escolar se detiene con luces intermitentes y señales de alto extendidas. ¿Quién debe detenerse?","o":["El tráfico en ambas direcciones","Solo el tráfico detrás del autobús","Solo el tráfico que viene hacia el autobús","Nadie, si no se ven niños"],"h1":"En una calle sin división, nadie puede pasar al autobús.","h2":"En Georgia, en una calle que no está dividida, los vehículos que van en cualquier dirección deben detenerse y no pueden pasar a un autobús escolar detenido.","p":"Correcto. Ambas direcciones se detienen."},"zh":{"q":"在 Georgia，在没有分隔的道路上，一辆校车停下来，灯在闪，伸出停车牌。谁必须停车？","o":["两个方向的车","只有校车后面的车","只有朝校车开过来的车","没人，如果看不到孩子"],"h1":"在没有分隔的道路上，谁都不能超过校车。","h2":"在 Georgia，在没有分隔的道路上，两个方向的车都必须停车，不能超过停着的校车。","p":"对。两个方向都要停车。"},"vi":{"q":"Ở Georgia, trên đường không có dải phân cách, một xe buýt trường học dừng lại với đèn nhấp nháy và biển STOP bật ra. Ai phải dừng?","o":["Xe ở cả hai chiều","Chỉ xe phía sau xe buýt","Chỉ xe chạy về phía xe buýt","Không ai, nếu không thấy trẻ em"],"h1":"Trên đường không có dải phân cách, không ai được vượt xe buýt.","h2":"Ở Georgia, trên đường không có dải phân cách, xe chạy ở cả hai chiều phải dừng lại và không được vượt xe buýt trường học đang dừng.","p":"Đúng. Cả hai chiều đều dừng."},"tl":{"q":"Sa Georgia, sa kalsadang walang divider, huminto ang school bus na may kumikislap na ilaw at nakalabas na STOP sign. Sino ang dapat huminto?","o":["Trapiko sa parehong direksyon","Trapiko lang sa likod ng bus","Trapiko lang na papunta sa bus","Wala, kung walang nakikitang bata"],"h1":"Sa kalsadang walang divider, walang puwedeng lumampas sa bus.","h2":"Sa Georgia, sa kalsadang walang divider, ang mga sasakyan sa parehong direksyon ay dapat huminto at hindi puwedeng lumampas sa nakahintong school bus.","p":"Tama. Parehong direksyon ay humihinto."},"ar":{"q":"في Georgia، على طريق غير مقسوم بفاصل، تتوقف حافلة مدرسية أضواؤها تومض ولافتات STOP مفتوحة. من يجب أن يتوقف؟","o":["السيارات في الاتجاهين","السيارات خلف الحافلة فقط","السيارات القادمة نحو الحافلة فقط","لا أحد، إذا لم يُرَ أطفال"],"h1":"على طريق بلا فاصل، لا يجوز لأحد أن يتجاوز الحافلة.","h2":"في Georgia، على طريق غير مقسوم بفاصل، يجب على السيارات في الاتجاهين أن تتوقف ولا يجوز لها تجاوز حافلة مدرسية متوقفة.","p":"صحيح. الاتجاهان يتوقفان."},"ref":{"doc":"GA","page":44}},{"id":"ga-019","scope":"GA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Georgia, an emergency vehicle with flashing lights is parked on the shoulder. What does the Move Over Law require first, if it is safe?","o":["Honk to warn the workers","Stop in your lane","Move over one lane, away from the vehicle","Drive on the shoulder"],"h1":"The law's name tells you what to do.","h2":"Georgia's Move Over Law requires you to move over one lane, away from the stopped emergency vehicle, when it is safe to do so.","p":"Right. Move over one lane."},"es":{"q":"En Georgia, un vehículo de emergencia con luces intermitentes está estacionado en el acotamiento. ¿Qué exige primero la Ley de Cambio de Carril (Move Over), si es seguro?","o":["Tocar la bocina para avisar a los trabajadores","Detenerse en su carril","Cambiarse un carril, lejos del vehículo","Manejar por el acotamiento"],"h1":"El nombre de la ley le dice qué hacer.","h2":"La Ley de Cambio de Carril de Georgia exige que usted se cambie un carril, lejos del vehículo de emergencia detenido, cuando sea seguro hacerlo.","p":"Correcto. Cámbiese un carril."},"zh":{"q":"在 Georgia，一辆灯在闪的急救车辆停在路肩上。如果安全，Move Over Law 首先要求你做什么？","o":["按喇叭提醒工作人员","在你的车道停车","换开一条车道，离开那辆车","开到路肩上"],"h1":"这条法律的名字告诉你该怎么做。","h2":"Georgia 的 Move Over Law 要求你在安全时换开一条车道，离开停着的急救车辆。","p":"对。换开一条车道。"},"vi":{"q":"Ở Georgia, một xe cấp cứu hoặc xe khẩn cấp có đèn nhấp nháy đang đậu bên lề đường. Luật Tránh Sang Làn (Move Over Law) yêu cầu bạn làm gì trước tiên, nếu an toàn?","o":["Bấm còi để báo cho người làm việc","Dừng lại trong làn của bạn","Chuyển sang một làn, tránh xa xe đó","Lái trên lề đường"],"h1":"Tên của luật cho bạn biết phải làm gì.","h2":"Luật Move Over của Georgia yêu cầu bạn chuyển sang một làn, tránh xa xe khẩn cấp đang dừng, khi làm vậy là an toàn.","p":"Đúng. Chuyển sang một làn."},"tl":{"q":"Sa Georgia, may emergency vehicle na may kumikislap na ilaw na nakaparada sa gilid ng daan (shoulder). Ano ang unang hinihingi ng Move Over Law, kung ligtas?","o":["Bumusina para balaan ang mga trabahador","Huminto sa lane mo","Lumipat ng isang lane, palayo sa sasakyan","Magmaneho sa shoulder"],"h1":"Sinasabi ng pangalan ng batas kung ano ang gagawin.","h2":"Hinihingi ng Move Over Law ng Georgia na lumipat ka ng isang lane, palayo sa nakahintong emergency vehicle, kapag ligtas itong gawin.","p":"Tama. Lumipat ng isang lane."},"ar":{"q":"في Georgia، مركبة طوارئ أضواؤها تومض متوقفة على كتف الطريق (shoulder). ماذا يطلب قانون الابتعاد (Move Over Law) أولًا، إذا كان ذلك آمنًا؟","o":["أن تستخدم البوق لتحذير العاملين","أن تتوقف في مسارك","أن تنتقل مسارًا واحدًا بعيدًا عن المركبة","أن تقود على كتف الطريق"],"h1":"اسم القانون يخبرك بما يجب أن تفعل.","h2":"قانون Move Over في Georgia يطلب منك أن تنتقل مسارًا واحدًا بعيدًا عن مركبة الطوارئ المتوقفة، عندما يكون ذلك آمنًا.","p":"صحيح. انتقل مسارًا واحدًا."},"ref":{"doc":"GA","page":18}},{"id":"ga-020","scope":"GA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Georgia, traffic is too heavy to move over for a stopped emergency vehicle. What must you do?","o":["Keep your speed","Stop completely on the highway","Change lanes anyway","Slow down below the speed limit and be ready to stop"],"h1":"If you cannot get away from it, pass it gently.","h2":"When you cannot safely move over in Georgia, you must slow down below the posted speed limit and be prepared to stop.","p":"Right. Slow down and be ready to stop."},"es":{"q":"En Georgia, hay demasiado tráfico para cambiarse de carril por un vehículo de emergencia detenido. ¿Qué debe hacer?","o":["Mantener su velocidad","Detenerse por completo en la carretera","Cambiarse de carril de todos modos","Bajar la velocidad por debajo del límite y estar listo para detenerse"],"h1":"Si no puede alejarse, pase con suavidad.","h2":"Cuando no puede cambiarse de carril con seguridad en Georgia, usted debe bajar la velocidad por debajo del límite indicado y estar listo para detenerse.","p":"Correcto. Baje la velocidad y esté listo para detenerse."},"zh":{"q":"在 Georgia，车太多，无法为停着的急救车辆换道。你必须怎么做？","o":["保持速度","在公路上完全停车","还是硬要换道","减速到低于限速，并准备好停车"],"h1":"如果你无法离开它，就慢慢地开过去。","h2":"在 Georgia，当你无法安全换道时，你必须减速到低于标示的限速，并准备好停车。","p":"对。减速，准备好停车。"},"vi":{"q":"Ở Georgia, xe cộ quá đông nên bạn không thể chuyển làn để tránh một xe khẩn cấp đang dừng. Bạn phải làm gì?","o":["Giữ nguyên tốc độ","Dừng hẳn trên đường cao tốc","Vẫn cứ chuyển làn","Giảm tốc độ xuống dưới mức giới hạn và sẵn sàng dừng"],"h1":"Nếu bạn không thể tránh xa nó, hãy đi qua nó thật nhẹ nhàng.","h2":"Ở Georgia, khi bạn không thể chuyển làn một cách an toàn, bạn phải giảm tốc độ xuống dưới mức giới hạn ghi trên biển và sẵn sàng dừng lại.","p":"Đúng. Giảm tốc độ và sẵn sàng dừng."},"tl":{"q":"Sa Georgia, sobrang dami ng trapiko kaya hindi ka makalipat ng lane palayo sa nakahintong emergency vehicle. Ano ang dapat mong gawin?","o":["Panatilihin ang bilis mo","Huminto nang tuluyan sa highway","Lumipat pa rin ng lane","Bumagal nang mas mababa sa speed limit at maging handang huminto"],"h1":"Kung hindi ka makalayo dito, dumaan nang dahan-dahan.","h2":"Kapag hindi ka ligtas na makalipat ng lane sa Georgia, dapat kang bumagal nang mas mababa sa nakapaskil na speed limit at maging handang huminto.","p":"Tama. Bumagal at maging handang huminto."},"ar":{"q":"في Georgia، الزحام شديد ولا يمكنك الانتقال بعيدًا عن مركبة طوارئ متوقفة. ماذا يجب أن تفعل؟","o":["تحافظ على سرعتك","تتوقف تمامًا على الطريق السريع","تغيّر المسار على أي حال","تخفف السرعة إلى أقل من الحد المسموح وتكون مستعدًا للتوقف"],"h1":"إذا لم تستطع الابتعاد عنها، فمرّ بجانبها بهدوء.","h2":"عندما لا تستطيع الانتقال بأمان في Georgia، يجب أن تخفف السرعة إلى أقل من الحد المكتوب على اللافتة وتكون مستعدًا للتوقف.","p":"صحيح. خفّف السرعة وكن مستعدًا للتوقف."},"ref":{"doc":"GA","page":18}},{"id":"ga-021","scope":"GA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Georgia, what is the legal blood alcohol limit for drivers under 21?","o":["0.00 percent","0.02 percent","0.05 percent","0.08 percent"],"h1":"It is much lower than the adult limit, but it is not zero.","h2":"In Georgia a driver under 21 is over the limit at a blood alcohol level of 0.02 percent, much lower than the 0.08 limit for adults.","p":"Right. Under 21, the limit is 0.02 percent."},"es":{"q":"En Georgia, ¿cuál es el límite legal de alcohol en la sangre para conductores menores de 21 años?","o":["0.00 por ciento","0.02 por ciento","0.05 por ciento","0.08 por ciento"],"h1":"Es mucho más bajo que el límite para adultos, pero no es cero.","h2":"En Georgia un conductor menor de 21 años pasa el límite con un nivel de alcohol en la sangre de 0.02 por ciento, mucho más bajo que el límite de 0.08 para adultos.","p":"Correcto. Para menores de 21, el límite es 0.02 por ciento."},"zh":{"q":"在 Georgia，21 岁以下司机的法定血液酒精浓度限制是多少？","o":["0.00%","0.02%","0.05%","0.08%"],"h1":"它比成年人的限制低很多，但不是零。","h2":"在 Georgia，21 岁以下的司机血液酒精浓度达到 0.02% 就超标了，这比成年人 0.08 的限制低很多。","p":"对。21 岁以下，限制是 0.02%。"},"vi":{"q":"Ở Georgia, giới hạn nồng độ cồn trong máu hợp pháp cho người lái dưới 21 tuổi là bao nhiêu?","o":["0.00 phần trăm","0.02 phần trăm","0.05 phần trăm","0.08 phần trăm"],"h1":"Nó thấp hơn nhiều so với giới hạn của người lớn, nhưng không phải là số không.","h2":"Ở Georgia, người lái dưới 21 tuổi bị coi là vượt giới hạn khi nồng độ cồn trong máu là 0.02 phần trăm, thấp hơn nhiều so với giới hạn 0.08 của người lớn.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02 phần trăm."},"tl":{"q":"Sa Georgia, ano ang legal na limit ng alak sa dugo para sa mga driver na wala pang 21?","o":["0.00 porsyento","0.02 porsyento","0.05 porsyento","0.08 porsyento"],"h1":"Mas mababa ito nang malaki kaysa sa limit ng adult, pero hindi ito zero.","h2":"Sa Georgia, ang driver na wala pang 21 ay lampas sa limit kapag 0.02 porsyento ang alak sa dugo niya, mas mababa nang malaki kaysa sa 0.08 na limit para sa adult.","p":"Tama. Para sa wala pang 21, ang limit ay 0.02 porsyento."},"ar":{"q":"في Georgia، ما الحد القانوني لنسبة الكحول في الدم للسائقين الذين أعمارهم أقل من 21 سنة؟","o":["0.00 بالمئة","0.02 بالمئة","0.05 بالمئة","0.08 بالمئة"],"h1":"هو أقل بكثير من حد البالغين، لكنه ليس صفرًا.","h2":"في Georgia يكون السائق الذي عمره أقل من 21 سنة فوق الحد عندما تكون نسبة الكحول في دمه 0.02 بالمئة، وهي أقل بكثير من حد 0.08 للبالغين.","p":"صحيح. لمن عمره أقل من 21 سنة، الحد هو 0.02 بالمئة."},"ref":{"doc":"GA","page":23}},{"id":"ga-022","scope":"GA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Georgia, a driver is convicted of going 85 mph or more on any road. What extra cost does the Super Speeder law add?","o":["No extra cost","A $20 state fee","A $200 state fee","A $2,000 state fee"],"h1":"It is added on top of the local fine, and it is a few hundred dollars.","h2":"In Georgia a Super Speeder pays a $200 state fee on top of any local fine.","p":"Right. Super Speeders pay an extra $200 state fee."},"es":{"q":"En Georgia, un conductor es condenado por ir a 85 mph o más en cualquier camino. ¿Qué costo adicional agrega la ley Super Speeder?","o":["Ningún costo adicional","Una tarifa estatal de $20","Una tarifa estatal de $200","Una tarifa estatal de $2,000"],"h1":"Se suma a la multa local, y son unos cientos de dólares.","h2":"En Georgia un Super Speeder paga una tarifa estatal de $200 además de cualquier multa local.","p":"Correcto. Los Super Speeders pagan una tarifa estatal adicional de $200."},"zh":{"q":"在 Georgia，一位司机因在任何道路上开到 85 mph 或以上被定罪。Super Speeder 法律会增加什么额外费用？","o":["没有额外费用","$20 的州费用","$200 的州费用","$2,000 的州费用"],"h1":"它是在地方罚款之外另加的，金额是几百美元。","h2":"在 Georgia，Super Speeder 除了地方罚款以外，还要付 $200 的州费用。","p":"对。Super Speeder 要多付 $200 的州费用。"},"vi":{"q":"Ở Georgia, một người lái bị kết tội chạy 85 mph trở lên trên bất kỳ con đường nào. Luật Super Speeder cộng thêm chi phí gì?","o":["Không có chi phí thêm","Một khoản phí tiểu bang $20","Một khoản phí tiểu bang $200","Một khoản phí tiểu bang $2,000"],"h1":"Nó được cộng thêm vào tiền phạt địa phương, và là vài trăm đô la.","h2":"Ở Georgia, một Super Speeder phải trả khoản phí tiểu bang $200, cộng thêm vào bất kỳ tiền phạt địa phương nào.","p":"Đúng. Super Speeder phải trả thêm khoản phí tiểu bang $200."},"tl":{"q":"Sa Georgia, nahatulan ang isang driver dahil tumakbo siya nang 85 mph o higit pa sa kahit anong kalsada. Anong dagdag na bayad ang idinadagdag ng batas na Super Speeder?","o":["Walang dagdag na bayad","Isang $20 na bayad sa estado","Isang $200 na bayad sa estado","Isang $2,000 na bayad sa estado"],"h1":"Idinadagdag ito sa lokal na multa, at ilang daang dolyar ito.","h2":"Sa Georgia, ang isang Super Speeder ay nagbabayad ng $200 na bayad sa estado bukod pa sa kahit anong lokal na multa.","p":"Tama. Ang mga Super Speeder ay nagbabayad ng dagdag na $200 na bayad sa estado."},"ar":{"q":"في Georgia، أُدين سائق لأنه قاد بسرعة 85 mph أو أكثر على أي طريق. ما التكلفة الإضافية التي يضيفها قانون Super Speeder؟","o":["لا توجد تكلفة إضافية","رسوم ولاية قدرها $20","رسوم ولاية قدرها $200","رسوم ولاية قدرها $2,000"],"h1":"تُضاف فوق الغرامة المحلية، وهي بضع مئات من الدولارات.","h2":"في Georgia يدفع الـ Super Speeder رسوم ولاية قدرها $200 فوق أي غرامة محلية.","p":"صحيح. يدفع الـ Super Speeder رسوم ولاية إضافية قدرها $200."},"ref":{"doc":"GA","page":21}},{"id":"ga-023","scope":"GA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Georgia, on a two-lane road, what speed makes a driver a Super Speeder?","o":["75 mph or more","60 mph or more","65 mph or more","90 mph or more"],"h1":"It is lower than the 85 mph that counts on any road.","h2":"In Georgia, driving 75 mph or more on a two-lane road makes you a Super Speeder.","p":"Right. On a two-lane road, 75 mph or more is Super Speeder territory."},"es":{"q":"En Georgia, en una carretera de dos carriles, ¿a qué velocidad un conductor se considera Super Speeder?","o":["75 mph o más","60 mph o más","65 mph o más","90 mph o más"],"h1":"Es menos que las 85 mph que cuentan en cualquier camino.","h2":"En Georgia, manejar a 75 mph o más en una carretera de dos carriles lo convierte en Super Speeder.","p":"Correcto. En una carretera de dos carriles, 75 mph o más es velocidad de Super Speeder."},"zh":{"q":"在 Georgia，在双车道道路上，开到什么速度会让司机成为 Super Speeder？","o":["75 mph 或以上","60 mph 或以上","65 mph 或以上","90 mph 或以上"],"h1":"它比在任何道路上都算数的 85 mph 低。","h2":"在 Georgia，在双车道道路上开到 75 mph 或以上，你就是 Super Speeder。","p":"对。在双车道道路上，75 mph 或以上就算 Super Speeder。"},"vi":{"q":"Ở Georgia, trên đường hai làn xe, chạy tốc độ nào thì người lái bị coi là Super Speeder?","o":["75 mph trở lên","60 mph trở lên","65 mph trở lên","90 mph trở lên"],"h1":"Nó thấp hơn mức 85 mph áp dụng trên mọi con đường.","h2":"Ở Georgia, chạy 75 mph trở lên trên đường hai làn xe thì bạn là Super Speeder.","p":"Đúng. Trên đường hai làn xe, 75 mph trở lên là mức Super Speeder."},"tl":{"q":"Sa Georgia, sa kalsadang may dalawang lane, anong bilis ang gumagawa sa isang driver na Super Speeder?","o":["75 mph o higit pa","60 mph o higit pa","65 mph o higit pa","90 mph o higit pa"],"h1":"Mas mababa ito kaysa sa 85 mph na binibilang sa kahit anong kalsada.","h2":"Sa Georgia, kapag nagmaneho ka nang 75 mph o higit pa sa kalsadang may dalawang lane, Super Speeder ka.","p":"Tama. Sa kalsadang may dalawang lane, ang 75 mph o higit pa ay bilis ng Super Speeder."},"ar":{"q":"في Georgia، على طريق بمسارين، ما السرعة التي تجعل السائق Super Speeder؟","o":["75 mph أو أكثر","60 mph أو أكثر","65 mph أو أكثر","90 mph أو أكثر"],"h1":"هي أقل من سرعة 85 mph التي تُحسب على أي طريق.","h2":"في Georgia، القيادة بسرعة 75 mph أو أكثر على طريق بمسارين تجعلك Super Speeder.","p":"صحيح. على طريق بمسارين، سرعة 75 mph أو أكثر هي سرعة Super Speeder."},"ref":{"doc":"GA","page":21}},{"id":"ga-024","scope":"GA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Georgia, what is the speed limit on a rural interstate when no other limit is posted?","o":["55 mph","70 mph","65 mph","80 mph"],"h1":"It is higher than the limit on an urban interstate.","h2":"In Georgia the speed limit on a rural interstate is 70 mph unless a sign shows another limit.","p":"Right. Rural interstates in Georgia are 70 mph unless posted otherwise."},"es":{"q":"En Georgia, ¿cuál es el límite de velocidad en una autopista interestatal rural cuando no hay otro límite indicado?","o":["55 mph","70 mph","65 mph","80 mph"],"h1":"Es más alto que el límite en una interestatal urbana.","h2":"En Georgia el límite de velocidad en una interestatal rural es 70 mph, a menos que una señal indique otro límite.","p":"Correcto. Las interestatales rurales de Georgia son de 70 mph si no se indica otra cosa."},"zh":{"q":"在 Georgia，如果没有标示其他限速，乡村州际公路的限速是多少？","o":["55 mph","70 mph","65 mph","80 mph"],"h1":"它比城市州际公路的限速高。","h2":"在 Georgia，乡村州际公路的限速是 70 mph，除非标志显示其他限速。","p":"对。在 Georgia，乡村州际公路限速 70 mph，除非另有标示。"},"vi":{"q":"Ở Georgia, tốc độ tối đa trên xa lộ liên tiểu bang ở vùng nông thôn là bao nhiêu khi không có biển báo giới hạn khác?","o":["55 mph","70 mph","65 mph","80 mph"],"h1":"Nó cao hơn giới hạn trên xa lộ liên tiểu bang trong thành phố.","h2":"Ở Georgia, tốc độ tối đa trên xa lộ liên tiểu bang ở vùng nông thôn là 70 mph, trừ khi có biển báo giới hạn khác.","p":"Đúng. Xa lộ liên tiểu bang ở vùng nông thôn tại Georgia là 70 mph, trừ khi có biển báo khác."},"tl":{"q":"Sa Georgia, ano ang speed limit sa rural na interstate kapag walang ibang limit na nakapaskil?","o":["55 mph","70 mph","65 mph","80 mph"],"h1":"Mas mataas ito kaysa sa limit sa urban na interstate.","h2":"Sa Georgia, ang speed limit sa rural na interstate ay 70 mph maliban kung may karatula na nagpapakita ng ibang limit.","p":"Tama. Ang mga rural na interstate sa Georgia ay 70 mph maliban kung iba ang nakapaskil."},"ar":{"q":"في Georgia، ما حد السرعة على طريق سريع بين الولايات (interstate) في منطقة ريفية عندما لا توجد لافتة بحد آخر؟","o":["55 mph","70 mph","65 mph","80 mph"],"h1":"هو أعلى من الحد على الطريق السريع بين الولايات داخل المدينة.","h2":"في Georgia حد السرعة على الطريق السريع بين الولايات في منطقة ريفية هو 70 mph، إلا إذا أظهرت لافتة حدًا آخر.","p":"صحيح. الطرق السريعة بين الولايات في المناطق الريفية في Georgia حدها 70 mph إلا إذا كُتب غير ذلك."},"ref":{"doc":"GA","page":21}},{"id":"ga-025","scope":"GA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Georgia, a child under what age must ride in a child safety seat that fits the child's height and weight?","o":["Under 4","Under 6","Under 12","Under 8"],"h1":"It is older than a preschool child, but younger than ten.","h2":"In Georgia a child under 8 years old must ride in a child safety seat that fits the child's height and weight.","p":"Right. Children under 8 need a proper child safety seat."},"es":{"q":"En Georgia, ¿un niño menor de qué edad debe viajar en un asiento de seguridad adecuado a su estatura y peso?","o":["Menor de 4 años","Menor de 6 años","Menor de 12 años","Menor de 8 años"],"h1":"Es mayor que un niño de preescolar, pero menor de diez años.","h2":"En Georgia un niño menor de 8 años debe viajar en un asiento de seguridad adecuado a su estatura y peso.","p":"Correcto. Los niños menores de 8 años necesitan un asiento de seguridad adecuado."},"zh":{"q":"在 Georgia，几岁以下的儿童必须坐在适合其身高和体重的儿童安全座椅里？","o":["4 岁以下","6 岁以下","12 岁以下","8 岁以下"],"h1":"这个年龄比学龄前儿童大，但比十岁小。","h2":"在 Georgia，8 岁以下的儿童必须坐在适合其身高和体重的儿童安全座椅里。","p":"对。8 岁以下的儿童需要合适的儿童安全座椅。"},"vi":{"q":"Ở Georgia, trẻ em dưới bao nhiêu tuổi phải ngồi ghế an toàn cho trẻ em phù hợp với chiều cao và cân nặng của trẻ?","o":["Dưới 4 tuổi","Dưới 6 tuổi","Dưới 12 tuổi","Dưới 8 tuổi"],"h1":"Tuổi này lớn hơn trẻ mẫu giáo, nhưng nhỏ hơn mười tuổi.","h2":"Ở Georgia, trẻ em dưới 8 tuổi phải ngồi ghế an toàn cho trẻ em phù hợp với chiều cao và cân nặng của trẻ.","p":"Đúng. Trẻ em dưới 8 tuổi cần ghế an toàn cho trẻ em phù hợp."},"tl":{"q":"Sa Georgia, ang batang wala pang ilang taon ang dapat nakaupo sa child safety seat na akma sa taas at timbang ng bata?","o":["Wala pang 4","Wala pang 6","Wala pang 12","Wala pang 8"],"h1":"Mas matanda ito kaysa sa batang preschool, pero mas bata sa sampu.","h2":"Sa Georgia, ang batang wala pang 8 taong gulang ay dapat nakaupo sa child safety seat na akma sa taas at timbang ng bata.","p":"Tama. Ang mga batang wala pang 8 ay kailangan ng tamang child safety seat."},"ar":{"q":"في Georgia، الطفل الذي عمره أقل من كم سنة يجب أن يجلس في مقعد أمان للأطفال يناسب طوله ووزنه؟","o":["أقل من 4","أقل من 6","أقل من 12","أقل من 8"],"h1":"هو أكبر من طفل ما قبل المدرسة، لكنه أصغر من عشر سنوات.","h2":"في Georgia يجب أن يجلس الطفل الذي عمره أقل من 8 سنوات في مقعد أمان للأطفال يناسب طوله ووزنه.","p":"صحيح. الأطفال الذين أعمارهم أقل من 8 سنوات يحتاجون إلى مقعد أمان مناسب للأطفال."},"ref":{"doc":"GA","page":24}},{"id":"ga-026","scope":"GA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Georgia, who must wear a seat belt in any seat of a passenger vehicle, front or back?","o":["Only the driver","Only passengers over 65","Everyone under 18","Only people in the front seat"],"h1":"In the front seat everyone buckles up. For the back seat, think about age.","h2":"In Georgia everyone under 18 must wear a seat belt in any seat, and everyone in the front seat must wear one too.","p":"Right. Under 18, you buckle up in every seat."},"es":{"q":"En Georgia, ¿quién debe usar el cinturón de seguridad en cualquier asiento de un vehículo de pasajeros, adelante o atrás?","o":["Solo el conductor","Solo los pasajeros mayores de 65 años","Todos los menores de 18 años","Solo las personas del asiento delantero"],"h1":"En el asiento delantero todos se abrochan. Para el asiento trasero, piense en la edad.","h2":"En Georgia todos los menores de 18 años deben usar el cinturón en cualquier asiento, y todos en el asiento delantero también deben usarlo.","p":"Correcto. Si tiene menos de 18 años, se abrocha en cualquier asiento."},"zh":{"q":"在 Georgia，谁在乘用车的任何座位上（前座或后座）都必须系安全带？","o":["只有司机","只有 65 岁以上的乘客","所有 18 岁以下的人","只有坐在前座的人"],"h1":"前座的每个人都要系安全带。后座的话，想想年龄。","h2":"在 Georgia，所有 18 岁以下的人在任何座位上都必须系安全带，前座的每个人也都必须系。","p":"对。18 岁以下，每个座位都要系安全带。"},"vi":{"q":"Ở Georgia, ai phải thắt dây an toàn ở bất kỳ ghế nào trong xe chở khách, ghế trước hay ghế sau?","o":["Chỉ người lái","Chỉ hành khách trên 65 tuổi","Mọi người dưới 18 tuổi","Chỉ người ngồi ghế trước"],"h1":"Ở ghế trước ai cũng phải thắt dây. Còn ghế sau, hãy nghĩ đến tuổi.","h2":"Ở Georgia, mọi người dưới 18 tuổi phải thắt dây an toàn ở bất kỳ ghế nào, và mọi người ngồi ghế trước cũng phải thắt.","p":"Đúng. Dưới 18 tuổi, bạn thắt dây an toàn ở mọi ghế."},"tl":{"q":"Sa Georgia, sino ang dapat magsuot ng seat belt sa kahit anong upuan ng pampasaherong sasakyan, sa harap man o sa likod?","o":["Ang driver lang","Ang mga pasaherong lampas 65 lang","Lahat ng wala pang 18","Ang mga nasa harap na upuan lang"],"h1":"Sa harap na upuan, lahat ay nagsusuot ng seat belt. Para sa likod na upuan, isipin ang edad.","h2":"Sa Georgia, lahat ng wala pang 18 ay dapat magsuot ng seat belt sa kahit anong upuan, at lahat ng nasa harap na upuan ay dapat ding magsuot nito.","p":"Tama. Kapag wala ka pang 18, nagsusuot ka ng seat belt sa bawat upuan."},"ar":{"q":"في Georgia، من يجب أن يربط حزام الأمان في أي مقعد في سيارة الركاب، في الأمام أو في الخلف؟","o":["السائق فقط","الركاب الذين أعمارهم أكثر من 65 فقط","كل من عمره أقل من 18","من يجلسون في المقعد الأمامي فقط"],"h1":"في المقعد الأمامي يربط الجميع الحزام. أما المقعد الخلفي، ففكّر في العمر.","h2":"في Georgia يجب على كل من عمره أقل من 18 سنة أن يربط حزام الأمان في أي مقعد، ويجب على كل من في المقعد الأمامي أن يربطه أيضًا.","p":"صحيح. إذا كان عمرك أقل من 18، تربط الحزام في كل مقعد."},"ref":{"doc":"GA","page":24}},{"id":"ga-027","scope":"GA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Georgia, a driver under 21 is convicted of reckless driving. What happens to their driving privileges?","o":["Nothing, if it is a first offense","They are suspended","They get a warning only","They must retake the vision test"],"h1":"Young drivers face a stricter result for this offense.","h2":"In Georgia, a reckless driving conviction for a driver under 21 means all driving privileges are suspended.","p":"Right. Under 21, a reckless driving conviction leads to a suspension."},"es":{"q":"En Georgia, un conductor menor de 21 años es condenado por manejo imprudente. ¿Qué pasa con sus privilegios de manejo?","o":["Nada, si es la primera vez","Se suspenden","Solo recibe una advertencia","Debe repetir el examen de la vista"],"h1":"Los conductores jóvenes reciben un resultado más estricto por esta falta.","h2":"En Georgia, una condena por manejo imprudente para un conductor menor de 21 años significa que se suspenden todos sus privilegios de manejo.","p":"Correcto. Para menores de 21 años, una condena por manejo imprudente lleva a una suspensión."},"zh":{"q":"在 Georgia，一位 21 岁以下的司机因鲁莽驾驶被定罪。他的驾驶权利会怎样？","o":["如果是第一次违规，就没事","会被暂停","只会收到警告","必须重新做视力测试"],"h1":"年轻司机犯这种违规，结果会更严格。","h2":"在 Georgia，21 岁以下的司机如果被判鲁莽驾驶，所有驾驶权利都会被暂停。","p":"对。21 岁以下，鲁莽驾驶被定罪会导致驾照被暂停。"},"vi":{"q":"Ở Georgia, một người lái dưới 21 tuổi bị kết tội lái xe liều lĩnh. Quyền lái xe của người đó sẽ ra sao?","o":["Không sao, nếu là lần vi phạm đầu tiên","Bị đình chỉ","Chỉ bị cảnh cáo","Phải thi lại bài kiểm tra mắt"],"h1":"Người lái trẻ bị xử nặng hơn cho lỗi này.","h2":"Ở Georgia, nếu người lái dưới 21 tuổi bị kết tội lái xe liều lĩnh thì tất cả quyền lái xe sẽ bị đình chỉ.","p":"Đúng. Dưới 21 tuổi, bị kết tội lái xe liều lĩnh sẽ dẫn đến bị đình chỉ."},"tl":{"q":"Sa Georgia, nahatulan ng reckless driving ang isang driver na wala pang 21. Ano ang mangyayari sa kanyang karapatang magmaneho?","o":["Wala, kung ito ang unang paglabag","Sinususpinde ito","Babala lang ang makukuha niya","Kailangan niyang ulitin ang vision test"],"h1":"Mas mahigpit ang resulta para sa mga batang driver sa paglabag na ito.","h2":"Sa Georgia, kapag nahatulan ng reckless driving ang driver na wala pang 21, sinususpinde ang lahat ng karapatan niyang magmaneho.","p":"Tama. Kapag wala pang 21, ang hatol sa reckless driving ay nauuwi sa suspensyon."},"ar":{"q":"في Georgia، أُدين سائق عمره أقل من 21 سنة بالقيادة المتهورة. ماذا يحدث لحقه في القيادة؟","o":["لا شيء، إذا كانت أول مخالفة","يتم إيقافه","يحصل على تحذير فقط","يجب أن يعيد اختبار النظر"],"h1":"السائقون الصغار يواجهون نتيجة أشد لهذه المخالفة.","h2":"في Georgia، إذا أُدين سائق عمره أقل من 21 سنة بالقيادة المتهورة، يتم إيقاف كل حقوقه في القيادة.","p":"صحيح. لمن عمره أقل من 21 سنة، الإدانة بالقيادة المتهورة تؤدي إلى إيقاف الرخصة."},"ref":{"doc":"GA","page":23}},{"id":"ga-028","scope":"GA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Georgia, when you pass a bicycle in the same lane, how much space must you keep between your car and the bicycle?","o":["At least 1 foot","At least 3 feet","At least 6 feet","At least 10 feet"],"h1":"Think of about one long step to the side, the whole time you pass.","h2":"In Georgia, you must keep at least three feet between your car and a bicycle the whole time you pass it.","p":"Right. Keep at least three feet from a bicycle while passing."},"es":{"q":"En Georgia, al rebasar una bicicleta en el mismo carril, ¿cuánto espacio debe mantener entre su auto y la bicicleta?","o":["Al menos 1 pie","Al menos 3 pies","Al menos 6 pies","Al menos 10 pies"],"h1":"Piense en un paso largo hacia un lado, durante todo el rebase.","h2":"En Georgia, debe mantener al menos tres pies entre su auto y la bicicleta durante todo el rebase.","p":"Correcto. Mantenga al menos tres pies de la bicicleta al rebasarla."},"zh":{"q":"在 Georgia，当你在同一条车道上超过自行车时，你的车和自行车之间必须保持多少距离？","o":["至少 1 英尺","至少 3 英尺","至少 6 英尺","至少 10 英尺"],"h1":"想一想向旁边迈一大步的距离，而且超车的整个过程都要保持。","h2":"在 Georgia，你超过自行车的整个过程中，你的车和自行车之间必须保持至少 3 英尺的距离。","p":"对。超过自行车时，要和它保持至少 3 英尺的距离。"},"vi":{"q":"Ở Georgia, khi bạn vượt một xe đạp trong cùng làn đường, bạn phải giữ khoảng cách bao nhiêu giữa xe của bạn và xe đạp?","o":["Ít nhất 1 foot","Ít nhất 3 feet","Ít nhất 6 feet","Ít nhất 10 feet"],"h1":"Hãy nghĩ đến khoảng một bước dài sang bên, trong suốt lúc bạn vượt.","h2":"Ở Georgia, bạn phải giữ ít nhất 3 feet giữa xe của bạn và xe đạp trong suốt lúc bạn vượt nó.","p":"Đúng. Giữ ít nhất 3 feet với xe đạp khi vượt."},"tl":{"q":"Sa Georgia, kapag nilalampasan mo ang bisikleta sa parehong lane, gaano kalayo ang dapat mong panatilihin sa pagitan ng kotse mo at ng bisikleta?","o":["Hindi bababa sa 1 talampakan","Hindi bababa sa 3 talampakan","Hindi bababa sa 6 na talampakan","Hindi bababa sa 10 talampakan"],"h1":"Isipin ang isang mahabang hakbang patagilid, sa buong oras ng paglampas mo.","h2":"Sa Georgia, dapat kang mag-iwan ng hindi bababa sa 3 talampakan sa pagitan ng kotse mo at ng bisikleta sa buong oras na nilalampasan mo ito.","p":"Tama. Mag-iwan ng hindi bababa sa 3 talampakan mula sa bisikleta habang lumalampas."},"ar":{"q":"في Georgia، عندما تتجاوز درّاجة هوائية في نفس المسار، ما المسافة التي يجب أن تتركها بين سيارتك والدرّاجة؟","o":["قدم واحد (1 foot) على الأقل","3 أقدام على الأقل","6 أقدام على الأقل","10 أقدام على الأقل"],"h1":"فكّر في خطوة طويلة واحدة إلى الجانب، طوال وقت التجاوز.","h2":"في Georgia يجب أن تترك 3 أقدام على الأقل بين سيارتك والدرّاجة الهوائية طوال وقت تجاوزها.","p":"صحيح. اترك 3 أقدام على الأقل بينك وبين الدرّاجة عند التجاوز."},"ref":{"doc":"GA","page":19}},{"id":"ga-029","scope":"GA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Georgia, how close to a fire hydrant may you not park?","o":["Within 5 feet","Within 10 feet","Within 15 feet","Within 30 feet"],"h1":"Fire crews need room to reach the hydrant and connect a hose.","h2":"In Georgia, you may not park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a fire hydrant when you park."},"es":{"q":"En Georgia, ¿a qué distancia de un hidrante no puede estacionarse?","o":["A menos de 5 pies","A menos de 10 pies","A menos de 15 pies","A menos de 30 pies"],"h1":"Los bomberos necesitan espacio para llegar al hidrante y conectar la manguera.","h2":"En Georgia, no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese al menos a 15 pies de un hidrante al estacionarse."},"zh":{"q":"在 Georgia，你不可以在离消防栓多近的地方停车？","o":["5 英尺以内","10 英尺以内","15 英尺以内","30 英尺以内"],"h1":"消防员需要空间走到消防栓旁边并接上水管。","h2":"在 Georgia，你不可以在离消防栓 15 英尺以内的地方停车。","p":"对。停车时要离消防栓至少 15 英尺。"},"vi":{"q":"Ở Georgia, bạn không được đậu xe gần trụ nước cứu hỏa trong khoảng bao nhiêu?","o":["Trong vòng 5 feet","Trong vòng 10 feet","Trong vòng 15 feet","Trong vòng 30 feet"],"h1":"Lính cứu hỏa cần chỗ để đến trụ nước và nối ống nước.","h2":"Ở Georgia, bạn không được đậu xe trong vòng 15 feet tính từ trụ nước cứu hỏa.","p":"Đúng. Khi đậu xe, hãy cách trụ nước cứu hỏa ít nhất 15 feet."},"tl":{"q":"Sa Georgia, gaano kalapit sa fire hydrant ang bawal kang pumarada?","o":["Sa loob ng 5 talampakan","Sa loob ng 10 talampakan","Sa loob ng 15 talampakan","Sa loob ng 30 talampakan"],"h1":"Kailangan ng mga bumbero ng espasyo para malapitan ang hydrant at maikabit ang hose.","h2":"Sa Georgia, bawal kang pumarada sa loob ng 15 talampakan mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 15 talampakan mula sa fire hydrant kapag pumaparada."},"ar":{"q":"في Georgia، ما المسافة من صنبور إطفاء الحريق (fire hydrant) التي لا يجوز لك أن توقف سيارتك داخلها؟","o":["ضمن 5 أقدام","ضمن 10 أقدام","ضمن 15 قدمًا","ضمن 30 قدمًا"],"h1":"يحتاج رجال الإطفاء إلى مساحة للوصول إلى الصنبور وتوصيل الخرطوم.","h2":"في Georgia لا يجوز لك أن توقف سيارتك ضمن 15 قدمًا من صنبور إطفاء الحريق.","p":"صحيح. ابتعد 15 قدمًا على الأقل عن صنبور إطفاء الحريق عندما توقف سيارتك."},"ref":{"doc":"GA","page":20}},{"id":"ga-030","scope":"GA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Georgia, you are driving in the left passing lane and faster traffic comes up behind you. What does the \"Slow Poke\" law say?","o":["Move to the right so the faster traffic can go by","Stay in the lane if you are at the speed limit","Speed up to match the faster traffic","Flash your brake lights to warn the driver"],"h1":"The left lane is meant for passing, no matter how fast you are going.","h2":"In Georgia, you must move out of the passing lane to let faster traffic go by, even if you are driving at the speed limit.","p":"Right. Move over to the right for faster traffic in the passing lane."},"es":{"q":"En Georgia, usted maneja en el carril izquierdo de rebase y viene tráfico más rápido detrás. ¿Qué dice la ley \"Slow Poke\"?","o":["Muévase a la derecha para que pase el tráfico más rápido","Quédese en el carril si va al límite de velocidad","Acelere para ir al ritmo del tráfico más rápido","Toque los frenos para avisar al conductor"],"h1":"El carril izquierdo es para rebasar, sin importar a qué velocidad vaya.","h2":"En Georgia, debe salir del carril de rebase para dejar pasar al tráfico más rápido, aunque vaya al límite de velocidad.","p":"Correcto. Muévase a la derecha para el tráfico más rápido en el carril de rebase."},"zh":{"q":"在 Georgia，你在左边的超车道上开车，后面有开得更快的车过来。\"Slow Poke\" 法律是怎么说的？","o":["向右边移，让更快的车过去","如果你在限速内，就留在这条车道上","加速，跟上更快的车","闪刹车灯提醒那个司机"],"h1":"不管你开多快，左边的车道都是用来超车的。","h2":"在 Georgia，你必须离开超车道，让更快的车过去，即使你正在按限速开车。","p":"对。在超车道上，要向右边移，让更快的车过去。"},"vi":{"q":"Ở Georgia, bạn đang lái trong làn vượt bên trái và xe chạy nhanh hơn đến phía sau bạn. Luật \"Slow Poke\" nói gì?","o":["Chuyển sang bên phải để xe nhanh hơn đi qua","Ở lại trong làn nếu bạn đang chạy đúng tốc độ giới hạn","Tăng tốc để theo kịp xe nhanh hơn","Nháy đèn phanh để cảnh báo tài xế đó"],"h1":"Làn bên trái là để vượt, dù bạn chạy nhanh đến đâu.","h2":"Ở Georgia, bạn phải ra khỏi làn vượt để xe nhanh hơn đi qua, ngay cả khi bạn đang chạy đúng tốc độ giới hạn.","p":"Đúng. Chuyển sang bên phải cho xe nhanh hơn trong làn vượt."},"tl":{"q":"Sa Georgia, nagmamaneho ka sa kaliwang passing lane at may mas mabilis na sasakyan na dumarating sa likod mo. Ano ang sinasabi ng batas na \"Slow Poke\"?","o":["Lumipat sa kanan para makadaan ang mas mabilis na sasakyan","Manatili sa lane kung nasa speed limit ka","Bumilis para makasabay sa mas mabilis na sasakyan","Pakislapin ang brake lights mo para bigyan ng babala ang driver"],"h1":"Ang kaliwang lane ay para sa paglampas, gaano man kabilis ang takbo mo.","h2":"Sa Georgia, dapat kang umalis sa passing lane para makadaan ang mas mabilis na sasakyan, kahit nasa speed limit ka.","p":"Tama. Lumipat sa kanan para sa mas mabilis na sasakyan sa passing lane."},"ar":{"q":"في Georgia، أنت تقود في مسار التجاوز الأيسر وتقترب منك من الخلف سيارات أسرع. ماذا يقول قانون \"Slow Poke\"؟","o":["انتقل إلى اليمين حتى تمرّ السيارات الأسرع","ابقَ في المسار إذا كنت تسير بالسرعة القصوى المسموحة","زِد سرعتك لتجاري السيارات الأسرع","اجعل أضواء الفرامل تومض لتحذير السائق"],"h1":"المسار الأيسر مخصّص للتجاوز، مهما كانت سرعتك.","h2":"في Georgia يجب أن تخرج من مسار التجاوز لتسمح للسيارات الأسرع بالمرور، حتى لو كنت تسير بالسرعة القصوى المسموحة.","p":"صحيح. انتقل إلى اليمين للسيارات الأسرع في مسار التجاوز."},"ref":{"doc":"GA","page":20}},{"id":"ga-031","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, you fail the knowledge test for the second time. How long must you wait before you try that test again?","o":["Until the next day","30 days","3 days","7 days"],"h1":"After a first failure the wait is short. After the second, it is longer.","h2":"In Georgia, after a second or later failure, you must wait 7 days before taking that test again.","p":"Right. After a second failure, wait 7 days to retake the test."},"es":{"q":"En Georgia, usted reprueba el examen de conocimientos por segunda vez. ¿Cuánto debe esperar para volver a tomarlo?","o":["Hasta el día siguiente","30 días","3 días","7 días"],"h1":"Después del primer fracaso la espera es corta. Después del segundo, es más larga.","h2":"En Georgia, después de reprobar por segunda vez o más, debe esperar 7 días para volver a tomar ese examen.","p":"Correcto. Después de reprobar por segunda vez, espere 7 días para repetirlo."},"zh":{"q":"在 Georgia，你第二次没有通过笔试。你要等多久才能再考这个考试？","o":["等到第二天","30 天","3 天","7 天"],"h1":"第一次没通过，等的时间很短。第二次没通过，等的时间更长。","h2":"在 Georgia，第二次或以后没通过，你必须等 7 天才能再考这个考试。","p":"对。第二次没通过，要等 7 天再考。"},"vi":{"q":"Ở Georgia, bạn thi rớt bài thi kiến thức lần thứ hai. Bạn phải chờ bao lâu mới được thi lại bài đó?","o":["Đến ngày hôm sau","30 ngày","3 ngày","7 ngày"],"h1":"Sau lần rớt đầu tiên, thời gian chờ ngắn. Sau lần thứ hai, thời gian chờ dài hơn.","h2":"Ở Georgia, sau lần rớt thứ hai hoặc các lần sau, bạn phải chờ 7 ngày mới được thi lại bài đó.","p":"Đúng. Sau lần rớt thứ hai, chờ 7 ngày để thi lại."},"tl":{"q":"Sa Georgia, bumagsak ka sa knowledge test sa ikalawang beses. Gaano katagal ka dapat maghintay bago mo subukan ulit ang test na iyon?","o":["Hanggang sa susunod na araw","30 araw","3 araw","7 araw"],"h1":"Pagkatapos ng unang pagbagsak, maikli ang paghihintay. Pagkatapos ng ikalawa, mas matagal.","h2":"Sa Georgia, pagkatapos ng ikalawa o mas huling pagbagsak, dapat kang maghintay ng 7 araw bago kumuha ulit ng test na iyon.","p":"Tama. Pagkatapos ng ikalawang pagbagsak, maghintay ng 7 araw bago kumuha ulit."},"ar":{"q":"في Georgia، رسبت في اختبار المعرفة للمرة الثانية. كم يجب أن تنتظر قبل أن تحاول هذا الاختبار مرة أخرى؟","o":["حتى اليوم التالي","30 يومًا","3 أيام","7 أيام"],"h1":"بعد الرسوب الأول يكون الانتظار قصيرًا. وبعد الثاني يكون أطول.","h2":"في Georgia، بعد الرسوب للمرة الثانية أو أكثر، يجب أن تنتظر 7 أيام قبل أن تأخذ هذا الاختبار مرة أخرى.","p":"صحيح. بعد الرسوب الثاني، انتظر 7 أيام لتعيد الاختبار."},"ref":{"doc":"GA","page":13}},{"id":"ga-032","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, how long is a Class C instructional permit (CP) valid?","o":["Up to 6 months","Up to 1 year","Up to 2 years","Up to 5 years"],"h1":"It lasts longer than the one year and one day a teen must hold it.","h2":"In Georgia, a Class C instructional permit is valid for up to 2 years.","p":"Right. The learner's permit is good for up to 2 years."},"es":{"q":"En Georgia, ¿por cuánto tiempo es válido el permiso de aprendizaje Clase C (CP)?","o":["Hasta 6 meses","Hasta 1 año","Hasta 2 años","Hasta 5 años"],"h1":"Dura más que el año y un día que un adolescente debe tenerlo.","h2":"En Georgia, el permiso de aprendizaje Clase C es válido hasta por 2 años.","p":"Correcto. El permiso de aprendizaje es válido hasta por 2 años."},"ref":{"doc":"GA","page":8}},{"id":"ga-033","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, when you are issued a Class C driver's license, for how many years is it issued?","o":["4 years","8 years","5 years","10 years"],"h1":"It is a long term, more than five years.","h2":"In Georgia, a Class C driver's license is issued for 8 years.","p":"Right. A Class C license is issued for 8 years."},"es":{"q":"En Georgia, cuando le dan una licencia de conducir Clase C, ¿por cuántos años se la dan?","o":["4 años","8 años","5 años","10 años"],"h1":"Es un plazo largo, de más de cinco años.","h2":"En Georgia, la licencia de conducir Clase C se emite por 8 años.","p":"Correcto. La licencia Clase C se emite por 8 años."},"ref":{"doc":"GA","page":9}},{"id":"ga-034","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, you just became a resident and want to drive. How soon must you get a Georgia license or permit?","o":["Within 30 days","Within 90 days","Within 6 months","Within 1 year"],"h1":"The deadline is about one month.","h2":"In Georgia, a new resident must get a Georgia license or permit within 30 days.","p":"Right. New residents have 30 days to get a Georgia license or permit."},"es":{"q":"En Georgia, usted acaba de hacerse residente y quiere manejar. ¿En cuánto tiempo debe sacar una licencia o permiso de Georgia?","o":["En 30 días","En 90 días","En 6 meses","En 1 año"],"h1":"El plazo es de más o menos un mes.","h2":"En Georgia, un nuevo residente debe sacar una licencia o permiso de Georgia en 30 días.","p":"Correcto. Los nuevos residentes tienen 30 días para sacar una licencia o permiso de Georgia."},"ref":{"doc":"GA","page":4}},{"id":"ga-035","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, what is the minimum vision needed for a regular (non-commercial) license?","o":["20/20 in both eyes","20/40 in both eyes","20/100 in one eye","20/60 in at least one eye"],"h1":"Only one eye has to meet the standard, and glasses or contacts may be used.","h2":"In Georgia, you need at least 20/60 vision in one eye, with or without glasses, for a regular license.","p":"Right. The minimum is 20/60 in one eye, with or without glasses."},"es":{"q":"En Georgia, ¿cuál es la visión mínima para una licencia regular (no comercial)?","o":["20/20 en ambos ojos","20/40 en ambos ojos","20/100 en un ojo","20/60 en al menos un ojo"],"h1":"Solo un ojo tiene que cumplir la norma, y se pueden usar lentes o lentes de contacto.","h2":"En Georgia, necesita por lo menos 20/60 de visión en un ojo, con o sin lentes, para una licencia regular.","p":"Correcto. El mínimo es 20/60 en un ojo, con o sin lentes."},"ref":{"doc":"GA","page":4}},{"id":"ga-036","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, your driver's license has been expired for more than two years. What must you do to renew it?","o":["Pay a late fee only","Pass a vision test only","Pass vision, knowledge and road tests","Wait one year, then reapply"],"h1":"After that long, you must show again that you can see, know the rules and drive.","h2":"In Georgia, a license expired more than two years needs a vision test, a knowledge exam and a driving test to renew.","p":"Right. After more than two years, you take the vision, knowledge and road tests again."},"es":{"q":"En Georgia, su licencia de conducir lleva más de dos años vencida. ¿Qué debe hacer para renovarla?","o":["Pagar solo un recargo","Pasar solo un examen de la vista","Pasar los exámenes de la vista, de conocimientos y de manejo","Esperar un año y volver a solicitarla"],"h1":"Después de tanto tiempo, debe demostrar otra vez que ve bien, conoce las reglas y sabe manejar.","h2":"En Georgia, una licencia vencida por más de dos años requiere un examen de la vista, uno de conocimientos y uno de manejo para renovarla.","p":"Correcto. Después de más de dos años, vuelve a tomar los exámenes de la vista, de conocimientos y de manejo."},"ref":{"doc":"GA","page":6}},{"id":"ga-037","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, you move to a new home. How soon must you update your address with DDS?","o":["Within 60 days","Within 10 days","Within 6 months","At your next renewal"],"h1":"You have about two months.","h2":"In Georgia, you must update your address with DDS within 60 days of moving.","p":"Right. Update your address with DDS within 60 days."},"es":{"q":"En Georgia, usted se muda a una casa nueva. ¿En cuánto tiempo debe actualizar su dirección con DDS?","o":["En 60 días","En 10 días","En 6 meses","En su próxima renovación"],"h1":"Tiene unos dos meses.","h2":"En Georgia, debe actualizar su dirección con DDS en un plazo de 60 días después de mudarse.","p":"Correcto. Actualice su dirección con DDS en 60 días."},"ref":{"doc":"GA","page":16}},{"id":"ga-038","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, what is the minimum score needed to pass the Class C or D road test?","o":["50 percent","60 percent","70 percent","75 percent"],"h1":"It is the same share needed on each part of the knowledge test: 15 out of 20.","h2":"In Georgia, you need a score of at least 75 percent to pass the Class C or D road test.","p":"Right. You need at least 75 percent on the road test."},"es":{"q":"En Georgia, ¿cuál es la calificación mínima para aprobar el examen de manejo Clase C o D?","o":["50 por ciento","60 por ciento","70 por ciento","75 por ciento"],"h1":"Es la misma proporción que se pide en cada parte del examen de conocimientos: 15 de 20.","h2":"En Georgia, necesita por lo menos 75 por ciento para aprobar el examen de manejo Clase C o D.","p":"Correcto. Necesita por lo menos 75 por ciento en el examen de manejo."},"ref":{"doc":"GA","page":13}},{"id":"ga-039","scope":"GA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Georgia, what is the penalty for a first conviction under the hands-free phone law?","o":["A warning only, with no points","1 point and a fine of up to $50","3 points and a fine of up to $150","6 points and a fine of up to $1,000"],"h1":"The penalty is small the first time and grows with each conviction.","h2":"In Georgia, a first hands-free law conviction brings 1 point and a fine of up to $50.","p":"Right. The first conviction is 1 point and up to $50."},"es":{"q":"En Georgia, ¿cuál es la sanción por una primera condena bajo la ley de manos libres?","o":["Solo una advertencia, sin puntos","1 punto y una multa de hasta $50","3 puntos y una multa de hasta $150","6 puntos y una multa de hasta $1,000"],"h1":"La sanción es pequeña la primera vez y aumenta con cada condena.","h2":"En Georgia, una primera condena por la ley de manos libres trae 1 punto y una multa de hasta $50.","p":"Correcto. La primera condena es 1 punto y hasta $50."},"ref":{"doc":"GA","page":25}},{"id":"ga-040","scope":"GA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Georgia, what is the highest fine for a first violation of the Move Over Law?","o":["$100","$250","$500","$5,000"],"h1":"It is a few hundred dollars.","h2":"In Georgia, a first Move Over Law violation can bring a fine of up to $500.","p":"Right. A first offense can cost up to $500."},"es":{"q":"En Georgia, ¿cuál es la multa más alta por una primera infracción de la Ley de Cambio de Carril (Move Over)?","o":["$100","$250","$500","$5,000"],"h1":"Son unos cientos de dólares.","h2":"En Georgia, una primera infracción de la Ley Move Over puede traer una multa de hasta $500.","p":"Correcto. Una primera infracción puede costar hasta $500."},"ref":{"doc":"GA","page":18}},{"id":"ga-041","scope":"GA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Georgia, on a two-lane road, how close to a railroad crossing may you not pass another vehicle?","o":["Within 100 feet","Within 25 feet","Within 50 feet","Within 500 feet"],"h1":"The same distance applies near a bridge or tunnel.","h2":"In Georgia, you may not pass on a two-lane road within 100 feet of a railroad crossing.","p":"Right. No passing within 100 feet of a railroad crossing."},"es":{"q":"En Georgia, en una carretera de dos carriles, ¿a qué distancia de un cruce de ferrocarril no puede rebasar a otro vehículo?","o":["A menos de 100 pies","A menos de 25 pies","A menos de 50 pies","A menos de 500 pies"],"h1":"La misma distancia se aplica cerca de un puente o un túnel.","h2":"En Georgia, no puede rebasar en una carretera de dos carriles a menos de 100 pies de un cruce de ferrocarril.","p":"Correcto. No se rebasa a menos de 100 pies de un cruce de ferrocarril."},"ref":{"doc":"GA","page":18}},{"id":"ga-042","scope":"GA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Georgia, you want to pass a bicycle but cannot safely change lanes. How slow must you go while passing?","o":["5 mph under the posted limit","Exactly 15 mph","Half of the posted limit","At least 10 mph under the limit, or 25 mph if that is higher"],"h1":"There is a set number of miles per hour below the limit, with a lowest speed of its own.","h2":"In Georgia, if you cannot change lanes, you must slow to at least 10 mph under the limit, or 25 mph if that is higher, and keep 3 feet away.","p":"Right. Slow to at least 10 mph under the limit, or 25 mph if that is higher."},"es":{"q":"En Georgia, quiere rebasar a una bicicleta pero no puede cambiar de carril con seguridad. ¿Qué tan despacio debe ir al rebasar?","o":["5 mph menos que el límite","Exactamente 15 mph","La mitad del límite","Al menos 10 mph menos que el límite, o 25 mph si eso es más alto"],"h1":"Hay un número fijo de millas por hora por debajo del límite, con una velocidad mínima propia.","h2":"En Georgia, si no puede cambiar de carril, debe bajar al menos 10 mph del límite, o a 25 mph si eso es más alto, y mantener 3 pies de distancia.","p":"Correcto. Baje al menos 10 mph del límite, o a 25 mph si eso es más alto."},"ref":{"doc":"GA","page":19}},{"id":"ga-043","scope":"GA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Georgia, how close to a stop sign may you not park?","o":["Within 10 feet","Within 30 feet","Within 50 feet","Within 100 feet"],"h1":"The same distance applies to a yield sign or a traffic light.","h2":"In Georgia, you may not park within 30 feet of a stop sign, yield sign or traffic light.","p":"Right. Stay at least 30 feet from a stop sign when you park."},"es":{"q":"En Georgia, ¿a qué distancia de una señal de alto no puede estacionarse?","o":["A menos de 10 pies","A menos de 30 pies","A menos de 50 pies","A menos de 100 pies"],"h1":"La misma distancia se aplica a una señal de ceda el paso o un semáforo.","h2":"En Georgia, no puede estacionarse a menos de 30 pies de una señal de alto, de ceda el paso o de un semáforo.","p":"Correcto. Quédese al menos a 30 pies de una señal de alto al estacionarse."},"ref":{"doc":"GA","page":20}},{"id":"ga-044","scope":"GA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Georgia, what fine can a driver get for disobeying the posted speed limit in a work zone?","o":["$10 to $100","$25 to $500","$100 to $2,000","$5,000 to $10,000"],"h1":"It is a serious misdemeanor, and the fine can reach a few thousand dollars.","h2":"In Georgia, speeding against a posted work zone limit can bring a fine of $100 to $2,000, jail of up to 12 months, or both.","p":"Right. The fine is $100 to $2,000."},"es":{"q":"En Georgia, ¿qué multa puede recibir un conductor por no respetar el límite de velocidad en una zona de trabajo?","o":["De $10 a $100","De $25 a $500","De $100 a $2,000","De $5,000 a $10,000"],"h1":"Es un delito menor grave, y la multa puede llegar a unos miles de dólares.","h2":"En Georgia, exceder el límite indicado en una zona de trabajo puede traer una multa de $100 a $2,000, cárcel de hasta 12 meses, o ambas.","p":"Correcto. La multa es de $100 a $2,000."},"ref":{"doc":"GA","page":22}},{"id":"ga-045","scope":"GA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Georgia, a fire truck is going to a fire alarm. How close behind it may you follow?","o":["No closer than 200 feet","No closer than 50 feet","No closer than 100 feet","No closer than 20 feet"],"h1":"Keep a long gap, about two-thirds of a football field.","h2":"In Georgia, you may not follow a fire truck answering an alarm closer than 200 feet.","p":"Right. Stay at least 200 feet behind a fire truck on a call."},"es":{"q":"En Georgia, un camión de bomberos va a atender una alarma de incendio. ¿A qué distancia detrás de él puede seguirlo?","o":["A no menos de 200 pies","A no menos de 50 pies","A no menos de 100 pies","A no menos de 20 pies"],"h1":"Deje un espacio largo, unos dos tercios de una cancha de fútbol americano.","h2":"En Georgia, no puede seguir a un camión de bomberos que atiende una alarma a menos de 200 pies.","p":"Correcto. Quédese al menos a 200 pies detrás de un camión de bomberos en servicio."},"ref":{"doc":"GA","page":24}},{"id":"ga-046","scope":"GA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Georgia, how far before your left turn may you enter the center turn lane?","o":["No more than 50 feet","No more than 100 feet","No more than 1,000 feet","No more than 300 feet"],"h1":"The lane is only for turning, so you may not use it as a long travel lane.","h2":"In Georgia, you may enter a center left-turn lane no more than 300 feet before your turn.","p":"Right. Enter the center turn lane no more than 300 feet before you turn."},"es":{"q":"En Georgia, ¿con cuánta anticipación a su vuelta a la izquierda puede entrar al carril central de vuelta?","o":["No más de 50 pies","No más de 100 pies","No más de 1,000 pies","No más de 300 pies"],"h1":"El carril es solo para dar vuelta, así que no se puede usar como carril para viajar.","h2":"En Georgia, puede entrar al carril central de vuelta a la izquierda no más de 300 pies antes de su vuelta.","p":"Correcto. Entre al carril central no más de 300 pies antes de dar vuelta."},"ref":{"doc":"GA","page":37}},{"id":"ga-047","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, how many points within 24 months will get a driver's license suspended?","o":["10 points","15 points","20 points","25 points"],"h1":"It is more than 10, and the period is two years.","h2":"In Georgia, a license is suspended when the driver gets 15 or more points within 24 months.","p":"Right. 15 points in 24 months means a suspension."},"es":{"q":"En Georgia, ¿cuántos puntos en 24 meses hacen que se suspenda la licencia de un conductor?","o":["10 puntos","15 puntos","20 puntos","25 puntos"],"h1":"Son más de 10, y el período es de dos años.","h2":"En Georgia, se suspende la licencia cuando el conductor acumula 15 puntos o más en 24 meses.","p":"Correcto. 15 puntos en 24 meses significan una suspensión."},"ref":{"doc":"GA","page":48}},{"id":"ga-048","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, finishing a certified 6-hour defensive driving course can lower the points on your license. By how much, and how often?","o":["Up to 3 points, once a year","Up to 5 points, once every 2 years","Up to 7 points, once every 5 years","All points, as often as you like"],"h1":"You can use it only once in several years.","h2":"In Georgia, a certified 6-hour defensive driving course can remove up to 7 points, once every 5 years.","p":"Right. Up to 7 points, once every 5 years."},"es":{"q":"En Georgia, terminar un curso certificado de manejo defensivo de 6 horas puede bajar los puntos de su licencia. ¿Cuántos y cada cuánto?","o":["Hasta 3 puntos, una vez al año","Hasta 5 puntos, una vez cada 2 años","Hasta 7 puntos, una vez cada 5 años","Todos los puntos, cuantas veces quiera"],"h1":"Solo se puede usar una vez en varios años.","h2":"En Georgia, un curso certificado de manejo defensivo de 6 horas puede quitar hasta 7 puntos, una vez cada 5 años.","p":"Correcto. Hasta 7 puntos, una vez cada 5 años."},"ref":{"doc":"GA","page":48}},{"id":"ga-049","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, how many points does a conviction for speeding 24 to 33 mph over the limit add to your record?","o":["4 points","1 point","2 points","6 points"],"h1":"It is fewer than for speeding 34 mph or more over the limit.","h2":"In Georgia, speeding 24 to 33 mph over the posted limit adds 4 points to your record.","p":"Right. Speeding 24 to 33 mph over the limit is 4 points."},"es":{"q":"En Georgia, ¿cuántos puntos agrega a su historial una condena por exceder el límite de 24 a 33 mph?","o":["4 puntos","1 punto","2 puntos","6 puntos"],"h1":"Son menos que por exceder el límite por 34 mph o más.","h2":"En Georgia, exceder el límite por 24 a 33 mph agrega 4 puntos a su historial.","p":"Correcto. Exceder el límite por 24 a 33 mph son 4 puntos."},"ref":{"doc":"GA","page":47}},{"id":"ga-050","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, a driver refuses the state's test for alcohol or drugs. What happens to the license?","o":["Nothing, if the driver was not arrested","A $50 fine and no suspension","A 30-day suspension","A suspension of at least one year"],"h1":"Under implied consent, refusing has a long penalty.","h2":"In Georgia, refusing the state's chemical test brings a license suspension of at least one year.","p":"Right. Refusing the test means a suspension of at least one year."},"es":{"q":"En Georgia, un conductor se niega a la prueba estatal de alcohol o drogas. ¿Qué le pasa a la licencia?","o":["Nada, si no lo arrestaron","Una multa de $50 sin suspensión","Una suspensión de 30 días","Una suspensión de al menos un año"],"h1":"Bajo el consentimiento implícito, negarse tiene una sanción larga.","h2":"En Georgia, negarse a la prueba química del estado trae una suspensión de la licencia de al menos un año.","p":"Correcto. Negarse a la prueba significa una suspensión de al menos un año."},"ref":{"doc":"GA","page":47}},{"id":"ga-051","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, you have a crash and no one is hurt. When must you report it to the police right away?","o":["Only if a car must be towed","When the damage is more than $500","Only if the other driver asks you to","When the damage is more than $5,000"],"h1":"It depends on the dollar amount of the damage.","h2":"In Georgia, you must notify the police right away when anyone is hurt or killed, or when property damage is more than $500.","p":"Right. Report it when damage is more than $500."},"es":{"q":"En Georgia, tiene un choque y nadie está herido. ¿Cuándo debe reportarlo a la policía de inmediato?","o":["Solo si hay que remolcar un auto","Cuando el daño es de más de $500","Solo si el otro conductor se lo pide","Cuando el daño es de más de $5,000"],"h1":"Depende de cuánto dinero cuesta el daño.","h2":"En Georgia, debe avisar a la policía de inmediato cuando alguien resulta herido o muerto, o cuando el daño a la propiedad es de más de $500.","p":"Correcto. Repórtelo cuando el daño sea de más de $500."},"ref":{"doc":"GA","page":50}},{"id":"hi-001","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","15 and a half years old","16 years old"],"h1":"It is half a year past a birthday.","h2":"In Hawaii you can get an instruction permit at 15 and a half years old.","p":"Right. The Hawaii permit starts at 15 and a half."},"es":{"q":"En Hawái, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["14 años","15 años","15 años y medio","16 años"],"h1":"Es medio año después de un cumpleaños.","h2":"En Hawái usted puede obtener el permiso de instrucción a los 15 años y medio.","p":"Correcto. El permiso en Hawái empieza a los 15 años y medio."},"zh":{"q":"在 Hawaii，最小几岁可以拿到学习驾照（instruction permit）？","o":["14 岁","15 岁","15 岁半","16 岁"],"h1":"它是过了生日以后再加半年。","h2":"在 Hawaii，你 15 岁半就可以拿到学习驾照。","p":"对。Hawaii 的学习驾照从 15 岁半开始。"},"vi":{"q":"Ở Hawaii, tuổi nhỏ nhất để có giấy phép tập lái (instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","15 tuổi rưỡi","16 tuổi"],"h1":"Đó là nửa năm sau một ngày sinh nhật.","h2":"Ở Hawaii, bạn có thể có giấy phép tập lái khi được 15 tuổi rưỡi.","p":"Đúng. Ở Hawaii, giấy phép tập lái bắt đầu từ 15 tuổi rưỡi."},"tl":{"q":"Sa Hawaii, ano ang pinakabatang edad para makakuha ng instruction permit?","o":["14 taong gulang","15 taong gulang","15 at kalahating taong gulang","16 taong gulang"],"h1":"Kalahating taon ito pagkatapos ng isang kaarawan.","h2":"Sa Hawaii, puwede kang kumuha ng instruction permit sa edad na 15 at kalahati.","p":"Tama. Sa Hawaii, nagsisimula ang permit sa 15 at kalahati."},"ar":{"q":"في Hawaii، ما أصغر عمر للحصول على تصريح تعلّم القيادة (instruction permit)؟","o":["14 سنة","15 سنة","15 سنة ونصف","16 سنة"],"h1":"هو نصف سنة بعد عيد ميلاد.","h2":"في Hawaii يمكنك الحصول على تصريح تعلّم القيادة في عمر 15 سنة ونصف.","p":"صحيح. في Hawaii يبدأ التصريح في عمر 15 سنة ونصف."},"ref":{"doc":"HI","page":13}},{"id":"hi-002","scope":"HI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Hawaii, how old must the licensed driver with a permit holder be?","o":["At least 18","At least 21","At least 25","At least 30"],"h1":"The helper must be old enough to drink alcohol legally.","h2":"A Hawaii permit holder may drive only with a licensed driver who is at least 21 years old.","p":"Right. The adult with you must be 21 or older."},"es":{"q":"En Hawái, ¿qué edad debe tener el conductor con licencia que acompaña a quien tiene permiso?","o":["Por lo menos 18","Por lo menos 21","Por lo menos 25","Por lo menos 30"],"h1":"El acompañante debe tener edad para tomar alcohol legalmente.","h2":"Quien tiene un permiso en Hawái solo puede manejar con un conductor con licencia de por lo menos 21 años.","p":"Correcto. El adulto que lo acompaña debe tener 21 años o más."},"zh":{"q":"在 Hawaii，陪同持学习驾照的人开车、有驾照的司机必须几岁？","o":["至少 18 岁","至少 21 岁","至少 25 岁","至少 30 岁"],"h1":"陪同的人必须到了可以合法喝酒的年龄。","h2":"在 Hawaii，持学习驾照的人只能和一位至少 21 岁、有驾照的司机一起开车。","p":"对。陪你的成年人必须 21 岁或以上。"},"vi":{"q":"Ở Hawaii, người có bằng lái đi cùng người có giấy phép tập lái phải bao nhiêu tuổi?","o":["Ít nhất 18 tuổi","Ít nhất 21 tuổi","Ít nhất 25 tuổi","Ít nhất 30 tuổi"],"h1":"Người hướng dẫn phải đủ tuổi để được uống rượu hợp pháp.","h2":"Người có giấy phép tập lái ở Hawaii chỉ được lái xe cùng một người có bằng lái từ 21 tuổi trở lên.","p":"Đúng. Người lớn đi cùng bạn phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Hawaii, ilang taon dapat ang lisensyadong driver na kasama ng may permit?","o":["Hindi bababa sa 18","Hindi bababa sa 21","Hindi bababa sa 25","Hindi bababa sa 30"],"h1":"Dapat sapat ang edad ng kasama para legal na uminom ng alak.","h2":"Ang may permit sa Hawaii ay puwedeng magmaneho lang kasama ang lisensyadong driver na hindi bababa sa 21 taong gulang.","p":"Tama. Dapat 21 o higit pa ang edad ng kasama mong adult."},"ar":{"q":"في Hawaii، كم يجب أن يكون عمر السائق المرخَّص الذي يرافق حامل التصريح؟","o":["18 سنة على الأقل","21 سنة على الأقل","25 سنة على الأقل","30 سنة على الأقل"],"h1":"يجب أن يكون المرافق كبيرًا بما يكفي لشرب الكحول قانونيًا.","h2":"لا يجوز لحامل التصريح في Hawaii أن يقود إلا مع سائق مرخَّص عمره 21 سنة على الأقل.","p":"صحيح. يجب أن يكون البالغ الذي معك عمره 21 سنة أو أكثر."},"ref":{"doc":"HI","page":11}},{"id":"hi-003","scope":"HI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Hawaii, where must the supervising driver sit when a permit holder drives?","o":["In the front passenger seat","In the back seat behind the driver","Anywhere in the car","In the back seat on the right"],"h1":"The helper needs to see the road and reach the driver quickly.","h2":"The supervising driver must sit in the front passenger seat, beside the Hawaii permit holder.","p":"Right. The helper sits right beside you."},"es":{"q":"En Hawái, ¿dónde debe sentarse el conductor supervisor cuando maneja alguien con permiso?","o":["En el asiento del pasajero delantero","En el asiento trasero detrás del conductor","En cualquier lugar del carro","En el asiento trasero a la derecha"],"h1":"El acompañante necesita ver la vía y alcanzar al conductor rápido.","h2":"El conductor supervisor debe sentarse en el asiento del pasajero delantero, al lado de quien tiene el permiso en Hawái.","p":"Correcto. El acompañante va a su lado."},"zh":{"q":"在 Hawaii，持学习驾照的人开车时，陪同的司机必须坐在哪里？","o":["前排乘客座位","司机后面的后排座位","车里任何地方","右边的后排座位"],"h1":"陪同的人需要看到道路，并能很快够到司机。","h2":"陪同的司机必须坐在前排乘客座位，在 Hawaii 持学习驾照的人旁边。","p":"对。陪同的人就坐在你旁边。"},"vi":{"q":"Ở Hawaii, khi người có giấy phép tập lái lái xe, người giám sát phải ngồi ở đâu?","o":["Ở ghế hành khách phía trước","Ở ghế sau, phía sau tài xế","Ở bất cứ chỗ nào trong xe","Ở ghế sau, bên phải"],"h1":"Người hướng dẫn cần nhìn thấy đường và giúp tài xế nhanh chóng.","h2":"Người giám sát phải ngồi ở ghế hành khách phía trước, bên cạnh người có giấy phép tập lái ở Hawaii.","p":"Đúng. Người hướng dẫn ngồi ngay bên cạnh bạn."},"tl":{"q":"Sa Hawaii, saan dapat umupo ang nagbabantay na driver kapag nagmamaneho ang may permit?","o":["Sa upuan ng pasahero sa harap","Sa likod, sa likuran ng driver","Kahit saan sa kotse","Sa likod, sa kanan"],"h1":"Kailangang makita ng kasama ang daan at maabot agad ang driver.","h2":"Dapat umupo ang nagbabantay na driver sa upuan ng pasahero sa harap, katabi ng may permit sa Hawaii.","p":"Tama. Katabi mo mismo ang kasama mo."},"ar":{"q":"في Hawaii، أين يجب أن يجلس السائق المشرف عندما يقود حامل التصريح؟","o":["في مقعد الراكب الأمامي","في المقعد الخلفي خلف السائق","في أي مكان في السيارة","في المقعد الخلفي على اليمين"],"h1":"يحتاج المرافق أن يرى الطريق وأن يصل إلى السائق بسرعة.","h2":"يجب أن يجلس السائق المشرف في مقعد الراكب الأمامي، بجانب حامل التصريح في Hawaii.","p":"صحيح. يجلس المرافق بجانبك مباشرة."},"ref":{"doc":"HI","page":11}},{"id":"hi-004","scope":"HI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Hawaii, how long must you hold an instruction permit before the road test?","o":["30 days","90 days","1 year","180 days"],"h1":"It is about half a year.","h2":"In Hawaii you must hold your instruction permit for at least 180 days before you take the road test.","p":"Right. You practice for at least 180 days first."},"es":{"q":"En Hawái, ¿cuánto tiempo debe tener el permiso de instrucción antes del examen de manejo?","o":["30 días","90 días","1 año","180 días"],"h1":"Es más o menos medio año.","h2":"En Hawái usted debe tener el permiso de instrucción por lo menos 180 días antes de presentar el examen de manejo.","p":"Correcto. Primero practica por lo menos 180 días."},"zh":{"q":"在 Hawaii，你必须持有学习驾照多久，才能参加路考？","o":["30 天","90 天","1 年","180 天"],"h1":"大约是半年。","h2":"在 Hawaii，你必须持有学习驾照至少 180 天，才能参加路考。","p":"对。你要先练习至少 180 天。"},"vi":{"q":"Ở Hawaii, bạn phải giữ giấy phép tập lái bao lâu trước khi thi lái xe trên đường?","o":["30 ngày","90 ngày","1 năm","180 ngày"],"h1":"Khoảng nửa năm.","h2":"Ở Hawaii, bạn phải giữ giấy phép tập lái ít nhất 180 ngày trước khi thi lái xe trên đường.","p":"Đúng. Bạn tập lái ít nhất 180 ngày trước."},"tl":{"q":"Sa Hawaii, gaano katagal mo dapat hawak ang instruction permit bago ang road test?","o":["30 araw","90 araw","1 taon","180 araw"],"h1":"Mga kalahating taon ito.","h2":"Sa Hawaii, dapat hawak mo ang iyong instruction permit nang hindi bababa sa 180 araw bago ka kumuha ng road test.","p":"Tama. Magsasanay ka muna nang hindi bababa sa 180 araw."},"ar":{"q":"في Hawaii، كم مدة يجب أن تحمل تصريح تعلّم القيادة قبل اختبار القيادة على الطريق؟","o":["30 يومًا","90 يومًا","سنة واحدة (1)","180 يومًا"],"h1":"هي حوالي نصف سنة.","h2":"في Hawaii يجب أن تحمل تصريح تعلّم القيادة 180 يومًا على الأقل قبل أن تأخذ اختبار القيادة على الطريق.","p":"صحيح. تتدرّب 180 يومًا على الأقل أولًا."},"ref":{"doc":"HI","page":13}},{"id":"hi-005","scope":"HI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Hawaii, what is the youngest age to get a provisional license?","o":["15 years old","16 years old","17 years old","18 years old"],"h1":"It comes after a half year of practice with a permit from age 15 and a half.","h2":"In Hawaii the provisional license is available from age 16.","p":"Right. The provisional license starts at 16."},"es":{"q":"En Hawái, ¿cuál es la edad mínima para obtener una licencia provisional?","o":["15 años","16 años","17 años","18 años"],"h1":"Llega después de medio año de práctica con un permiso desde los 15 años y medio.","h2":"En Hawái la licencia provisional se puede obtener desde los 16 años.","p":"Correcto. La licencia provisional empieza a los 16."},"zh":{"q":"在 Hawaii，最小几岁可以拿到过渡驾照（provisional license）？","o":["15 岁","16 岁","17 岁","18 岁"],"h1":"它是在 15 岁半拿到学习驾照、练习半年以后。","h2":"在 Hawaii，16 岁起就可以拿到过渡驾照。","p":"对。过渡驾照从 16 岁开始。"},"vi":{"q":"Ở Hawaii, tuổi nhỏ nhất để có bằng lái tạm thời (provisional license) là bao nhiêu?","o":["15 tuổi","16 tuổi","17 tuổi","18 tuổi"],"h1":"Đó là sau nửa năm tập lái với giấy phép có từ lúc 15 tuổi rưỡi.","h2":"Ở Hawaii, bằng lái tạm thời có thể được cấp từ 16 tuổi.","p":"Đúng. Bằng lái tạm thời bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Hawaii, ano ang pinakabatang edad para makakuha ng provisional license?","o":["15 taong gulang","16 taong gulang","17 taong gulang","18 taong gulang"],"h1":"Darating ito pagkatapos ng kalahating taon ng pagsasanay gamit ang permit mula edad 15 at kalahati.","h2":"Sa Hawaii, makukuha ang provisional license mula edad 16.","p":"Tama. Nagsisimula ang provisional license sa 16."},"ar":{"q":"في Hawaii، ما أصغر عمر للحصول على رخصة القيادة المؤقتة (provisional license)؟","o":["15 سنة","16 سنة","17 سنة","18 سنة"],"h1":"تأتي بعد نصف سنة من التدريب بتصريح من عمر 15 سنة ونصف.","h2":"في Hawaii يمكن الحصول على رخصة القيادة المؤقتة من عمر 16 سنة.","p":"صحيح. تبدأ الرخصة المؤقتة في عمر 16 سنة."},"ref":{"doc":"HI","page":13}},{"id":"hi-006","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, during which hours does a provisional licensee need a parent or guardian in the car?","o":["9 p.m. to 5 a.m.","Midnight to 6 a.m.","11 p.m. to 5 a.m.","10 p.m. to 6 a.m."],"h1":"It starts one hour before midnight.","h2":"A Hawaii provisional licensee who drives between 11 p.m. and 5 a.m. must have a licensed parent or guardian in the seat beside them, unless an exception applies.","p":"Right. The night limit is 11 p.m. to 5 a.m."},"es":{"q":"En Hawái, ¿en qué horas necesita un conductor con licencia provisional a su padre, madre o tutor en el carro?","o":["De 9 p.m. a 5 a.m.","De medianoche a 6 a.m.","De 11 p.m. a 5 a.m.","De 10 p.m. a 6 a.m."],"h1":"Empieza una hora antes de la medianoche.","h2":"Un conductor con licencia provisional en Hawái que maneja entre las 11 p.m. y las 5 a.m. debe llevar al lado a su padre, madre o tutor con licencia, salvo que aplique una excepción.","p":"Correcto. El límite de noche es de 11 p.m. a 5 a.m."},"zh":{"q":"在 Hawaii，持过渡驾照的人在哪些时间开车，车里必须有父母或监护人？","o":["晚上 9 点到早上 5 点","午夜到早上 6 点","晚上 11 点到早上 5 点","晚上 10 点到早上 6 点"],"h1":"它从午夜前一个小时开始。","h2":"在 Hawaii，持过渡驾照的人在晚上 11 点到早上 5 点之间开车时，旁边的座位必须坐着一位有驾照的父母或监护人，除非符合例外情况。","p":"对。夜间限制是晚上 11 点到早上 5 点。"},"vi":{"q":"Ở Hawaii, trong những giờ nào người có bằng lái tạm thời cần cha mẹ hoặc người giám hộ ngồi trong xe?","o":["9 giờ tối đến 5 giờ sáng","Nửa đêm đến 6 giờ sáng","11 giờ tối đến 5 giờ sáng","10 giờ tối đến 6 giờ sáng"],"h1":"Bắt đầu một giờ trước nửa đêm.","h2":"Ở Hawaii, người có bằng lái tạm thời lái xe từ 11 giờ tối đến 5 giờ sáng phải có cha mẹ hoặc người giám hộ có bằng lái ngồi ở ghế bên cạnh, trừ khi có trường hợp ngoại lệ.","p":"Đúng. Giới hạn ban đêm là từ 11 giờ tối đến 5 giờ sáng."},"tl":{"q":"Sa Hawaii, sa anong mga oras kailangan ng may provisional license ang magulang o guardian sa kotse?","o":["9 p.m. hanggang 5 a.m.","Hatinggabi hanggang 6 a.m.","11 p.m. hanggang 5 a.m.","10 p.m. hanggang 6 a.m."],"h1":"Nagsisimula ito isang oras bago ang hatinggabi.","h2":"Ang may provisional license sa Hawaii na nagmamaneho mula 11 p.m. hanggang 5 a.m. ay dapat may katabing lisensyadong magulang o guardian, maliban kung may exception.","p":"Tama. Ang limitasyon sa gabi ay 11 p.m. hanggang 5 a.m."},"ar":{"q":"في Hawaii، في أي ساعات يحتاج حامل الرخصة المؤقتة إلى أحد الوالدين أو الوصي في السيارة؟","o":["من 9 مساءً إلى 5 صباحًا","من منتصف الليل إلى 6 صباحًا","من 11 مساءً إلى 5 صباحًا","من 10 مساءً إلى 6 صباحًا"],"h1":"تبدأ قبل منتصف الليل بساعة واحدة.","h2":"حامل الرخصة المؤقتة في Hawaii الذي يقود بين 11 مساءً و5 صباحًا يجب أن يكون بجانبه أحد الوالدين أو وصي يحمل رخصة قيادة، إلا إذا انطبق استثناء.","p":"صحيح. حدّ الليل من 11 مساءً إلى 5 صباحًا."},"ref":{"doc":"HI","page":14}},{"id":"hi-007","scope":"HI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Hawaii, who must ride beside a provisional licensee driving late at night?","o":["A licensed parent or guardian","Any passenger over 16","Any licensed friend","A driving school teacher only"],"h1":"It is a family adult who is responsible for the teen.","h2":"In Hawaii, a provisional licensee driving between 11 p.m. and 5 a.m. must have a licensed parent or guardian in the seat beside them.","p":"Right. A licensed parent or guardian rides along."},"es":{"q":"En Hawái, ¿quién debe ir al lado de un conductor con licencia provisional que maneja tarde en la noche?","o":["Su padre, madre o tutor con licencia","Cualquier pasajero mayor de 16","Cualquier amigo con licencia","Solo un instructor de manejo"],"h1":"Es un adulto de la familia que responde por el adolescente.","h2":"En Hawái, un conductor con licencia provisional que maneja entre las 11 p.m. y las 5 a.m. debe llevar al lado a su padre, madre o tutor con licencia.","p":"Correcto. Lo acompaña su padre, madre o tutor con licencia."},"zh":{"q":"在 Hawaii，持过渡驾照的人深夜开车时，谁必须坐在旁边？","o":["有驾照的父母或监护人","任何 16 岁以上的乘客","任何有驾照的朋友","只能是驾校老师"],"h1":"是对这个青少年负责的家里的成年人。","h2":"在 Hawaii，持过渡驾照的人在晚上 11 点到早上 5 点之间开车时，旁边的座位必须坐着一位有驾照的父母或监护人。","p":"对。要有一位有驾照的父母或监护人一起坐车。"},"vi":{"q":"Ở Hawaii, ai phải ngồi bên cạnh người có bằng lái tạm thời khi lái xe khuya?","o":["Cha mẹ hoặc người giám hộ có bằng lái","Bất kỳ hành khách nào trên 16 tuổi","Bất kỳ người bạn nào có bằng lái","Chỉ giáo viên trường dạy lái xe"],"h1":"Đó là người lớn trong gia đình chịu trách nhiệm về thiếu niên.","h2":"Ở Hawaii, người có bằng lái tạm thời lái xe từ 11 giờ tối đến 5 giờ sáng phải có cha mẹ hoặc người giám hộ có bằng lái ngồi ở ghế bên cạnh.","p":"Đúng. Cha mẹ hoặc người giám hộ có bằng lái đi cùng."},"tl":{"q":"Sa Hawaii, sino ang dapat katabi ng may provisional license na nagmamaneho nang hatinggabi?","o":["Isang lisensyadong magulang o guardian","Kahit sinong pasahero na higit sa 16","Kahit sinong kaibigang may lisensya","Guro lang ng driving school"],"h1":"Isa itong adult sa pamilya na responsable sa teenager.","h2":"Sa Hawaii, ang may provisional license na nagmamaneho mula 11 p.m. hanggang 5 a.m. ay dapat may katabing lisensyadong magulang o guardian.","p":"Tama. Kasama ang lisensyadong magulang o guardian."},"ar":{"q":"في Hawaii، من يجب أن يجلس بجانب حامل الرخصة المؤقتة الذي يقود في وقت متأخر من الليل؟","o":["أحد الوالدين أو وصي يحمل رخصة قيادة","أي راكب عمره فوق 16 سنة","أي صديق يحمل رخصة قيادة","معلّم مدرسة قيادة فقط"],"h1":"هو شخص بالغ من العائلة مسؤول عن المراهق.","h2":"في Hawaii، حامل الرخصة المؤقتة الذي يقود بين 11 مساءً و5 صباحًا يجب أن يكون بجانبه أحد الوالدين أو وصي يحمل رخصة قيادة.","p":"صحيح. يرافقك أحد الوالدين أو وصي يحمل رخصة."},"ref":{"doc":"HI","page":14}},{"id":"hi-008","scope":"HI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Hawaii, when may a provisional licensee drive alone after 11 p.m.?","o":["Any time they feel awake","When going to a friend's house","When the roads are empty","Going straight to or from work, with a note from the employer in the car"],"h1":"Think of a trip that has paperwork behind it.","h2":"A Hawaii provisional licensee may drive alone at night when going directly to or from work, with documentation from the employer kept in the vehicle.","p":"Right. Work trips with a note are allowed."},"es":{"q":"En Hawái, ¿cuándo puede un conductor con licencia provisional manejar solo después de las 11 p.m.?","o":["Cuando se sienta despierto","Cuando va a la casa de un amigo","Cuando las calles están vacías","Directo al trabajo o de regreso, con una nota del empleador en el carro"],"h1":"Piense en un viaje que tiene un papel que lo respalda.","h2":"Un conductor con licencia provisional en Hawái puede manejar solo de noche cuando va directo al trabajo o regresa de él, con un documento del empleador dentro del vehículo.","p":"Correcto. Los viajes al trabajo con una nota están permitidos."},"zh":{"q":"在 Hawaii，持过渡驾照的人什么时候可以在晚上 11 点以后一个人开车？","o":["只要觉得不困，任何时候都可以","去朋友家的时候","路上没车的时候","直接去上班或下班回家，车里放着雇主写的证明"],"h1":"想一想哪种出行有书面文件支持。","h2":"在 Hawaii，持过渡驾照的人直接去上班或下班回家时，可以在夜里一个人开车，但车里要放着雇主开的证明文件。","p":"对。带着证明去上下班是可以的。"},"vi":{"q":"Ở Hawaii, khi nào người có bằng lái tạm thời được lái xe một mình sau 11 giờ tối?","o":["Bất cứ lúc nào họ thấy tỉnh táo","Khi đi đến nhà bạn","Khi đường vắng","Khi đi thẳng đến hoặc về từ chỗ làm, có giấy của chủ lao động trong xe"],"h1":"Hãy nghĩ đến một chuyến đi có giấy tờ chứng minh.","h2":"Ở Hawaii, người có bằng lái tạm thời được lái xe một mình vào ban đêm khi đi thẳng đến hoặc về từ chỗ làm, có giấy tờ của chủ lao động để trong xe.","p":"Đúng. Đi làm có giấy chứng nhận thì được phép."},"tl":{"q":"Sa Hawaii, kailan puwedeng magmaneho nang mag-isa ang may provisional license pagkalipas ng 11 p.m.?","o":["Kahit kailan basta gising pa sila","Kapag pupunta sa bahay ng kaibigan","Kapag walang laman ang daan","Diretso papunta o pauwi galing trabaho, may sulat mula sa employer sa kotse"],"h1":"Isipin ang biyahe na may papeles na patunay.","h2":"Ang may provisional license sa Hawaii ay puwedeng magmaneho nang mag-isa sa gabi kapag diretso papunta o pauwi galing trabaho, may dokumento mula sa employer na nasa sasakyan.","p":"Tama. Puwede ang biyahe sa trabaho kung may sulat."},"ar":{"q":"في Hawaii، متى يجوز لحامل الرخصة المؤقتة أن يقود وحده بعد 11 مساءً؟","o":["في أي وقت يشعر فيه أنه مستيقظ","عند الذهاب إلى بيت صديق","عندما تكون الطرق فارغة","عند الذهاب مباشرة إلى العمل أو العودة منه، مع ورقة من صاحب العمل في السيارة"],"h1":"فكّر في رحلة وراءها أوراق رسمية.","h2":"يجوز لحامل الرخصة المؤقتة في Hawaii أن يقود وحده في الليل عند الذهاب مباشرة إلى العمل أو العودة منه، مع وثيقة من صاحب العمل محفوظة في السيارة.","p":"صحيح. رحلات العمل مع ورقة مسموح بها."},"ref":{"doc":"HI","page":14}},{"id":"hi-009","scope":"HI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Hawaii, how many passengers under 18 may a provisional licensee carry without a parent or guardian?","o":["None at all","One, unless the others live in the same household","Two","Three"],"h1":"Count on one hand, and use just one finger.","h2":"Without a parent or guardian along, a Hawaii provisional licensee may carry no more than one person under 18, unless the others are household members.","p":"Right. Only one young passenger from outside the home."},"es":{"q":"En Hawái, ¿cuántos pasajeros menores de 18 puede llevar un conductor con licencia provisional sin su padre, madre o tutor?","o":["Ninguno","Uno, salvo que los demás vivan en la misma casa","Dos","Tres"],"h1":"Cuente con una mano, y use solo un dedo.","h2":"Sin su padre, madre o tutor en el carro, un conductor con licencia provisional en Hawái puede llevar como máximo a una persona menor de 18, salvo que los demás vivan en su misma casa.","p":"Correcto. Solo un pasajero joven de fuera de la casa."},"zh":{"q":"在 Hawaii，没有父母或监护人在车上时，持过渡驾照的人可以载几个 18 岁以下的乘客？","o":["一个都不可以","一个，除非其他人和司机住在同一个家里","两个","三个"],"h1":"数一数，只用一根手指。","h2":"在 Hawaii，没有父母或监护人陪同时，持过渡驾照的人最多只能载一个 18 岁以下的人，除非其他人是同一个家里的成员。","p":"对。家以外的年轻乘客只能载一个。"},"vi":{"q":"Ở Hawaii, người có bằng lái tạm thời được chở bao nhiêu hành khách dưới 18 tuổi khi không có cha mẹ hoặc người giám hộ?","o":["Không ai cả","Một người, trừ khi những người khác sống cùng nhà","Hai người","Ba người"],"h1":"Đếm trên một bàn tay, và chỉ dùng một ngón.","h2":"Khi không có cha mẹ hoặc người giám hộ đi cùng, người có bằng lái tạm thời ở Hawaii chỉ được chở tối đa một người dưới 18 tuổi, trừ khi những người khác sống cùng nhà.","p":"Đúng. Chỉ một hành khách trẻ không sống cùng nhà."},"tl":{"q":"Sa Hawaii, ilang pasaherong wala pang 18 ang puwedeng isakay ng may provisional license kung walang magulang o guardian?","o":["Wala talaga","Isa, maliban kung nakatira sa parehong bahay ang iba","Dalawa","Tatlo"],"h1":"Bumilang sa isang kamay, at isang daliri lang ang gamitin.","h2":"Kung walang kasamang magulang o guardian, ang may provisional license sa Hawaii ay puwedeng magsakay ng hindi hihigit sa isang taong wala pang 18, maliban kung kasama sa bahay ang iba.","p":"Tama. Isang batang pasahero lang mula sa labas ng bahay."},"ar":{"q":"في Hawaii، كم راكبًا عمره أقل من 18 سنة يجوز لحامل الرخصة المؤقتة أن ينقل دون أحد الوالدين أو الوصي؟","o":["لا أحد أبدًا","واحد، إلا إذا كان الآخرون يسكنون في نفس البيت","اثنان","ثلاثة"],"h1":"عُدّ على يد واحدة، واستخدم إصبعًا واحدًا فقط.","h2":"دون مرافقة أحد الوالدين أو الوصي، لا يجوز لحامل الرخصة المؤقتة في Hawaii أن ينقل أكثر من شخص واحد عمره أقل من 18 سنة، إلا إذا كان الآخرون من أهل البيت.","p":"صحيح. راكب صغير واحد فقط من خارج البيت."},"ref":{"doc":"HI","page":13}},{"id":"hi-010","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, which young passengers do not count toward a provisional licensee's passenger limit?","o":["Classmates","Teammates","Members of the driver's household","Neighbors"],"h1":"Think of the people who live under the same roof.","h2":"In Hawaii, passengers under 18 who are members of the provisional licensee's household do not count toward the one-passenger limit.","p":"Right. People from your own home do not count."},"es":{"q":"En Hawái, ¿qué pasajeros jóvenes no cuentan en el límite de pasajeros de un conductor con licencia provisional?","o":["Compañeros de clase","Compañeros de equipo","Personas que viven en la casa del conductor","Vecinos"],"h1":"Piense en las personas que viven bajo el mismo techo.","h2":"En Hawái, los pasajeros menores de 18 que viven en la casa del conductor con licencia provisional no cuentan en el límite de un pasajero.","p":"Correcto. Las personas de su propia casa no cuentan."},"zh":{"q":"在 Hawaii，哪些年轻乘客不算在持过渡驾照的人的乘客人数限制里？","o":["同班同学","队友","和司机住在同一个家里的人","邻居"],"h1":"想一想住在同一个屋顶下的人。","h2":"在 Hawaii，和持过渡驾照的人住在同一个家里、18 岁以下的乘客，不算在一名乘客的限制里。","p":"对。你自己家里的人不算。"},"vi":{"q":"Ở Hawaii, những hành khách trẻ nào không bị tính vào giới hạn hành khách của người có bằng lái tạm thời?","o":["Bạn cùng lớp","Bạn cùng đội","Người sống cùng nhà với tài xế","Hàng xóm"],"h1":"Hãy nghĩ đến những người sống dưới cùng một mái nhà.","h2":"Ở Hawaii, hành khách dưới 18 tuổi sống cùng nhà với người có bằng lái tạm thời không bị tính vào giới hạn một hành khách.","p":"Đúng. Người trong nhà bạn không bị tính."},"tl":{"q":"Sa Hawaii, aling mga batang pasahero ang hindi binibilang sa limitasyon ng pasahero ng may provisional license?","o":["Mga kaklase","Mga kasama sa team","Mga kasama sa bahay ng driver","Mga kapitbahay"],"h1":"Isipin ang mga taong nakatira sa iisang bubong.","h2":"Sa Hawaii, ang mga pasaherong wala pang 18 na kasama sa bahay ng may provisional license ay hindi binibilang sa limitasyong isang pasahero.","p":"Tama. Hindi binibilang ang mga tao mula sa sarili mong bahay."},"ar":{"q":"في Hawaii، أي الركاب الصغار لا يُحسبون ضمن حدّ الركاب لحامل الرخصة المؤقتة؟","o":["زملاء الصف","زملاء الفريق","أفراد بيت السائق","الجيران"],"h1":"فكّر في الناس الذين يعيشون تحت سقف واحد.","h2":"في Hawaii، الركاب الذين عمرهم أقل من 18 سنة ومن أفراد بيت حامل الرخصة المؤقتة لا يُحسبون ضمن حدّ الراكب الواحد.","p":"صحيح. الناس من بيتك لا يُحسبون."},"ref":{"doc":"HI","page":13}},{"id":"hi-011","scope":"HI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Hawaii, may an adult driver hold a phone and use it while driving?","o":["No, using a mobile electronic device while driving is banned","Yes, at any speed","Yes, but only on the highway","Yes, if no police are around"],"h1":"The rule covers every driver, not only teens.","h2":"Hawaii law says no person may drive a motor vehicle while using a mobile electronic device, so you must not hold and use your phone while driving.","p":"Right. Put the phone down while you drive."},"es":{"q":"En Hawái, ¿puede un conductor adulto sostener y usar un teléfono mientras maneja?","o":["No, usar un aparato electrónico móvil mientras maneja está prohibido","Sí, a cualquier velocidad","Sí, pero solo en la autopista","Sí, si no hay policía cerca"],"h1":"La regla es para todos los conductores, no solo los jóvenes.","h2":"La ley de Hawái dice que nadie puede manejar un vehículo mientras usa un aparato electrónico móvil, así que usted no debe sostener ni usar su teléfono al manejar.","p":"Correcto. Deje el teléfono mientras maneja."},"zh":{"q":"在 Hawaii，成年司机开车时可以手拿手机使用吗？","o":["不可以，开车时禁止使用移动电子设备","可以，什么速度都可以","可以，但只能在高速公路上","可以，只要附近没有警察"],"h1":"这个规定适用于所有司机，不只是青少年。","h2":"Hawaii 法律规定，任何人开车时都不能使用移动电子设备，所以你开车时不能手拿手机使用。","p":"对。开车时把手机放下。"},"vi":{"q":"Ở Hawaii, tài xế người lớn có được cầm điện thoại và dùng nó khi lái xe không?","o":["Không, cấm dùng thiết bị điện tử di động khi lái xe","Có, ở bất kỳ tốc độ nào","Có, nhưng chỉ trên xa lộ","Có, nếu không có cảnh sát gần đó"],"h1":"Luật này áp dụng cho mọi tài xế, không chỉ thiếu niên.","h2":"Luật Hawaii nói không ai được lái xe cơ giới trong khi dùng thiết bị điện tử di động, nên bạn không được cầm và dùng điện thoại khi lái xe.","p":"Đúng. Hãy bỏ điện thoại xuống khi lái xe."},"tl":{"q":"Sa Hawaii, puwede bang hawakan at gamitin ng adult na driver ang telepono habang nagmamaneho?","o":["Hindi, bawal gumamit ng mobile electronic device habang nagmamaneho","Oo, sa kahit anong bilis","Oo, pero sa highway lang","Oo, kung walang pulis sa paligid"],"h1":"Para sa lahat ng driver ang patakaran, hindi lang sa mga teenager.","h2":"Sinasabi ng batas ng Hawaii na walang taong puwedeng magmaneho ng sasakyan habang gumagamit ng mobile electronic device, kaya hindi mo dapat hawakan at gamitin ang telepono habang nagmamaneho.","p":"Tama. Ibaba ang telepono habang nagmamaneho."},"ar":{"q":"في Hawaii، هل يجوز للسائق البالغ أن يمسك الهاتف ويستخدمه أثناء القيادة؟","o":["لا، استخدام جهاز إلكتروني محمول أثناء القيادة ممنوع","نعم، بأي سرعة","نعم، لكن على الطريق السريع فقط","نعم، إذا لم تكن الشرطة قريبة"],"h1":"القاعدة تشمل كل السائقين، وليس المراهقين فقط.","h2":"يقول قانون Hawaii إنه لا يجوز لأي شخص أن يقود مركبة وهو يستخدم جهازًا إلكترونيًا محمولًا، لذلك يجب ألا تمسك هاتفك وتستخدمه أثناء القيادة.","p":"صحيح. ضع الهاتف جانبًا وأنت تقود."},"ref":{"doc":"HI","page":null}},{"id":"hi-012","scope":"HI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Hawaii, may a 17-year-old driver use a hands-free phone while driving?","o":["Yes, any time","Yes, but only for music","Yes, if a parent is in the car","No, drivers under 18 may not use even a hands-free device"],"h1":"The rule for teens is stricter than the rule for adults.","h2":"In Hawaii, a driver under 18 may not use a hands-free mobile electronic device while driving, except to call 911.","p":"Right. Under 18, no phone at all while driving."},"es":{"q":"En Hawái, ¿puede un conductor de 17 años usar un teléfono de manos libres mientras maneja?","o":["Sí, en cualquier momento","Sí, pero solo para música","Sí, si va un padre en el carro","No, los menores de 18 no pueden usar ni siquiera un aparato de manos libres"],"h1":"La regla para jóvenes es más estricta que para adultos.","h2":"En Hawái, un conductor menor de 18 no puede usar un aparato electrónico móvil de manos libres mientras maneja, salvo para llamar al 911.","p":"Correcto. Menor de 18, nada de teléfono al manejar."},"zh":{"q":"在 Hawaii，17 岁的司机开车时可以用免提手机吗？","o":["可以，任何时候都可以","可以，但只能听音乐","可以，只要父母在车上","不可以，18 岁以下的司机连免提设备也不能用"],"h1":"对青少年的规定比对成年人更严格。","h2":"在 Hawaii，18 岁以下的司机开车时不能使用免提移动电子设备，只有打 911 除外。","p":"对。18 岁以下，开车时完全不能用手机。"},"vi":{"q":"Ở Hawaii, tài xế 17 tuổi có được dùng điện thoại rảnh tay (hands-free) khi lái xe không?","o":["Có, bất cứ lúc nào","Có, nhưng chỉ để nghe nhạc","Có, nếu cha mẹ ngồi trong xe","Không, tài xế dưới 18 tuổi không được dùng cả thiết bị rảnh tay"],"h1":"Luật cho thiếu niên nghiêm hơn luật cho người lớn.","h2":"Ở Hawaii, tài xế dưới 18 tuổi không được dùng thiết bị điện tử di động rảnh tay khi lái xe, trừ khi gọi 911.","p":"Đúng. Dưới 18 tuổi, không dùng điện thoại chút nào khi lái xe."},"tl":{"q":"Sa Hawaii, puwede bang gumamit ng hands-free na telepono ang 17 taong gulang na driver habang nagmamaneho?","o":["Oo, kahit kailan","Oo, pero para sa musika lang","Oo, kung may magulang sa kotse","Hindi, ang mga driver na wala pang 18 ay hindi puwedeng gumamit kahit ng hands-free device"],"h1":"Mas mahigpit ang patakaran para sa teenager kaysa sa adult.","h2":"Sa Hawaii, ang driver na wala pang 18 ay hindi puwedeng gumamit ng hands-free mobile electronic device habang nagmamaneho, maliban sa pagtawag sa 911.","p":"Tama. Kung wala pang 18, bawal ang telepono habang nagmamaneho."},"ar":{"q":"في Hawaii، هل يجوز لسائق عمره 17 سنة أن يستخدم هاتفًا دون استخدام اليدين (hands-free) أثناء القيادة؟","o":["نعم، في أي وقت","نعم، لكن للموسيقى فقط","نعم، إذا كان أحد الوالدين في السيارة","لا، السائقون تحت 18 سنة لا يجوز لهم استخدام حتى جهاز دون استخدام اليدين"],"h1":"القاعدة للمراهقين أشدّ من القاعدة للبالغين.","h2":"في Hawaii، لا يجوز للسائق الذي عمره أقل من 18 سنة أن يستخدم جهازًا إلكترونيًا محمولًا دون استخدام اليدين أثناء القيادة، إلا للاتصال بالرقم 911.","p":"صحيح. تحت 18 سنة، لا هاتف أبدًا أثناء القيادة."},"ref":{"doc":"HI","page":null}},{"id":"hi-013","scope":"HI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Hawaii, for what reason may a driver under 18 use a hands-free phone while driving?","o":["To answer a parent's text","To call 911 in an emergency","To check a map","To talk with a friend"],"h1":"It is the number you call when someone needs help right away.","h2":"A Hawaii driver under 18 may use a hands-free device while driving only to make a 911 emergency call.","p":"Right. Only a 911 emergency call."},"es":{"q":"En Hawái, ¿por qué razón puede un conductor menor de 18 usar un teléfono de manos libres al manejar?","o":["Para contestar un mensaje de sus padres","Para llamar al 911 en una emergencia","Para ver un mapa","Para hablar con un amigo"],"h1":"Es el número al que se llama cuando alguien necesita ayuda de inmediato.","h2":"Un conductor menor de 18 en Hawái solo puede usar un aparato de manos libres al manejar para hacer una llamada de emergencia al 911.","p":"Correcto. Solo una llamada de emergencia al 911."},"zh":{"q":"在 Hawaii，18 岁以下的司机开车时，因为什么原因可以用免提手机？","o":["回复父母的短信","在紧急情况下打 911","看地图","和朋友聊天"],"h1":"这是有人马上需要帮助时要打的号码。","h2":"在 Hawaii，18 岁以下的司机开车时只能用免提设备打 911 紧急电话。","p":"对。只能打 911 紧急电话。"},"vi":{"q":"Ở Hawaii, tài xế dưới 18 tuổi được dùng điện thoại rảnh tay khi lái xe vì lý do nào?","o":["Để trả lời tin nhắn của cha mẹ","Để gọi 911 khi khẩn cấp","Để xem bản đồ","Để nói chuyện với bạn"],"h1":"Đó là số bạn gọi khi có người cần giúp ngay.","h2":"Ở Hawaii, tài xế dưới 18 tuổi chỉ được dùng thiết bị rảnh tay khi lái xe để gọi 911 khẩn cấp.","p":"Đúng. Chỉ được gọi 911 khi khẩn cấp."},"tl":{"q":"Sa Hawaii, sa anong dahilan puwedeng gumamit ng hands-free na telepono ang driver na wala pang 18 habang nagmamaneho?","o":["Para sagutin ang text ng magulang","Para tumawag sa 911 sa emergency","Para tumingin ng mapa","Para makipag-usap sa kaibigan"],"h1":"Ito ang numerong tinatawagan kapag may nangangailangan agad ng tulong.","h2":"Ang driver sa Hawaii na wala pang 18 ay puwedeng gumamit ng hands-free device habang nagmamaneho para lang sa emergency na tawag sa 911.","p":"Tama. Emergency na tawag sa 911 lang."},"ar":{"q":"في Hawaii، لأي سبب يجوز للسائق تحت 18 سنة أن يستخدم هاتفًا دون استخدام اليدين أثناء القيادة؟","o":["للردّ على رسالة من أحد الوالدين","للاتصال بالرقم 911 في حالة طوارئ","للنظر في خريطة","للتحدث مع صديق"],"h1":"هو الرقم الذي تتصل به عندما يحتاج أحد إلى مساعدة فورًا.","h2":"يجوز للسائق في Hawaii الذي عمره أقل من 18 سنة أن يستخدم جهازًا دون استخدام اليدين أثناء القيادة فقط لإجراء اتصال طوارئ بالرقم 911.","p":"صحيح. فقط اتصال طوارئ بالرقم 911."},"ref":{"doc":"HI","page":null}},{"id":"hi-014","scope":"HI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Hawaii, where is the fine for using a phone while driving higher?","o":["On rural roads","In parking lots","In a school zone or a construction area","On the freeway at night"],"h1":"Think of places where children or road workers are close by.","h2":"In Hawaii, the fine for using a mobile device while driving is higher in a school zone or a construction area.","p":"Right. School zones and work zones cost more."},"es":{"q":"En Hawái, ¿dónde es más alta la multa por usar el teléfono mientras maneja?","o":["En caminos rurales","En estacionamientos","En una zona escolar o una zona de construcción","En la autopista de noche"],"h1":"Piense en lugares donde hay niños o trabajadores cerca.","h2":"En Hawái, la multa por usar un aparato móvil mientras maneja es más alta en una zona escolar o una zona de construcción.","p":"Correcto. Las zonas escolares y de obras cuestan más."},"zh":{"q":"在 Hawaii，在哪里开车用手机罚款更高？","o":["在乡村道路上","在停车场","在学校区域或施工区","晚上在高速公路上"],"h1":"想一想附近有小孩或道路工人的地方。","h2":"在 Hawaii，在学校区域或施工区开车时使用移动设备，罚款更高。","p":"对。学校区域和施工区罚得更多。"},"vi":{"q":"Ở Hawaii, tiền phạt dùng điện thoại khi lái xe cao hơn ở đâu?","o":["Trên đường nông thôn","Trong bãi đậu xe","Trong khu vực trường học hoặc khu công trường","Trên xa lộ vào ban đêm"],"h1":"Hãy nghĩ đến những nơi có trẻ em hoặc công nhân làm đường ở gần.","h2":"Ở Hawaii, tiền phạt dùng thiết bị di động khi lái xe cao hơn trong khu vực trường học hoặc khu công trường.","p":"Đúng. Khu vực trường học và khu công trường bị phạt nặng hơn."},"tl":{"q":"Sa Hawaii, saan mas mataas ang multa sa paggamit ng telepono habang nagmamaneho?","o":["Sa mga daan sa probinsya","Sa mga parking lot","Sa school zone o construction area","Sa freeway sa gabi"],"h1":"Isipin ang mga lugar na malapit ang mga bata o mga trabahador sa daan.","h2":"Sa Hawaii, mas mataas ang multa sa paggamit ng mobile device habang nagmamaneho sa school zone o construction area.","p":"Tama. Mas mahal ang multa sa school zone at work zone."},"ar":{"q":"في Hawaii، أين تكون غرامة استخدام الهاتف أثناء القيادة أعلى؟","o":["على الطرق الريفية","في مواقف السيارات","في منطقة مدرسة أو منطقة أعمال بناء","على الطريق السريع في الليل"],"h1":"فكّر في أماكن يكون فيها أطفال أو عمّال طرق قريبين.","h2":"في Hawaii، غرامة استخدام جهاز محمول أثناء القيادة أعلى في منطقة مدرسة أو منطقة أعمال بناء.","p":"صحيح. مناطق المدارس ومناطق الأعمال غرامتها أعلى."},"ref":{"doc":"HI","page":null}},{"id":"hi-015","scope":"HI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Hawaii, what is the usual fine for using a mobile device while driving?","o":["$300","$25","$50","$1,000"],"h1":"It is a few hundred dollars.","h2":"In Hawaii the usual fine for using a mobile electronic device while driving is $300.","p":"Right. The usual fine is $300."},"es":{"q":"En Hawái, ¿cuál es la multa normal por usar un aparato móvil mientras maneja?","o":["$300","$25","$50","$1,000"],"h1":"Son unos cientos de dólares.","h2":"En Hawái la multa normal por usar un aparato electrónico móvil mientras maneja es de $300.","p":"Correcto. La multa normal es de $300."},"zh":{"q":"在 Hawaii，开车时使用移动设备，一般罚款多少？","o":["$300","$25","$50","$1,000"],"h1":"是几百美元。","h2":"在 Hawaii，开车时使用移动电子设备，一般罚款 $300。","p":"对。一般罚款是 $300。"},"vi":{"q":"Ở Hawaii, tiền phạt thông thường khi dùng thiết bị di động lúc lái xe là bao nhiêu?","o":["$300","$25","$50","$1,000"],"h1":"Đó là vài trăm đô la.","h2":"Ở Hawaii, tiền phạt thông thường khi dùng thiết bị điện tử di động lúc lái xe là $300.","p":"Đúng. Tiền phạt thông thường là $300."},"tl":{"q":"Sa Hawaii, magkano ang karaniwang multa sa paggamit ng mobile device habang nagmamaneho?","o":["$300","$25","$50","$1,000"],"h1":"Ilang daang dolyar ito.","h2":"Sa Hawaii, ang karaniwang multa sa paggamit ng mobile electronic device habang nagmamaneho ay $300.","p":"Tama. Ang karaniwang multa ay $300."},"ar":{"q":"في Hawaii، ما الغرامة المعتادة لاستخدام جهاز محمول أثناء القيادة؟","o":["$300","$25","$50","$1,000"],"h1":"هي بضع مئات من الدولارات.","h2":"في Hawaii، الغرامة المعتادة لاستخدام جهاز إلكتروني محمول أثناء القيادة هي $300.","p":"صحيح. الغرامة المعتادة هي $300."},"ref":{"doc":"HI","page":null}},{"id":"hi-016","scope":"HI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Hawaii, what must you do when you approach a stopped emergency vehicle with flashing lights?","o":["Keep your speed and honk","Flash your high beams at it","Speed up to pass it fast","Slow to a safe speed and move to the next lane if it is safe"],"h1":"Give the workers more space and more time.","h2":"Hawaii's move over law says to slow down to a safe and prudent speed and, when it is safe, move into the next lane away from the stopped emergency vehicle.","p":"Right. Slow down and move over."},"es":{"q":"En Hawái, ¿qué debe hacer al acercarse a un vehículo de emergencia detenido con luces intermitentes?","o":["Mantener la velocidad y tocar la bocina","Hacerle cambio de luces altas","Acelerar para pasarlo rápido","Bajar a una velocidad segura y cambiarse al carril de al lado si es seguro"],"h1":"Dé a los trabajadores más espacio y más tiempo.","h2":"La ley de Hawái para moverse de carril dice que debe bajar a una velocidad segura y prudente y, cuando sea seguro, cambiarse al carril de al lado, lejos del vehículo de emergencia detenido.","p":"Correcto. Baje la velocidad y cámbiese de carril."},"zh":{"q":"在 Hawaii，当你靠近一辆停着、闪着灯的急救车辆时，你必须做什么？","o":["保持速度并按喇叭","对它闪远光灯","加速快点开过去","减速到安全速度，安全的话换到旁边的车道"],"h1":"给工作人员更多空间和更多时间。","h2":"Hawaii 的 move over 法规定，你要减速到安全、谨慎的速度，并在安全时换到离停着的急救车辆远一点的旁边车道。","p":"对。减速并换道让开。"},"vi":{"q":"Ở Hawaii, bạn phải làm gì khi đến gần một xe cấp cứu đang dừng và có đèn nhấp nháy?","o":["Giữ nguyên tốc độ và bấm còi","Nháy đèn pha vào xe đó","Tăng tốc để vượt qua nhanh","Giảm xuống tốc độ an toàn và chuyển sang làn bên cạnh nếu an toàn"],"h1":"Hãy cho nhân viên thêm khoảng cách và thêm thời gian.","h2":"Luật nhường làn (move over law) của Hawaii nói phải giảm xuống tốc độ an toàn và hợp lý, và khi an toàn thì chuyển sang làn bên cạnh, xa xe cấp cứu đang dừng.","p":"Đúng. Giảm tốc độ và chuyển làn."},"tl":{"q":"Sa Hawaii, ano ang dapat mong gawin kapag papalapit ka sa nakahintong emergency vehicle na may kumikislap na ilaw?","o":["Panatilihin ang bilis at bumusina","I-flash ang high beams mo rito","Bumilis para mabilis itong malampasan","Bumagal sa ligtas na bilis at lumipat sa katabing lane kung ligtas"],"h1":"Bigyan ng mas maraming espasyo at oras ang mga trabahador.","h2":"Sinasabi ng move over law ng Hawaii na bumagal sa ligtas at maingat na bilis at, kapag ligtas, lumipat sa katabing lane palayo sa nakahintong emergency vehicle.","p":"Tama. Bumagal at lumipat ng lane."},"ar":{"q":"في Hawaii، ماذا يجب أن تفعل عندما تقترب من مركبة طوارئ متوقفة وأضواؤها تومض؟","o":["حافظ على سرعتك واضغط على البوق","ومّض لها بالأضواء العالية","زِد السرعة لتتجاوزها بسرعة","خفّف إلى سرعة آمنة وانتقل إلى المسار المجاور إذا كان ذلك آمنًا"],"h1":"أعطِ العمّال مسافة أكبر ووقتًا أكثر.","h2":"يقول قانون الابتعاد (move over law) في Hawaii أن تخفّف السرعة إلى سرعة آمنة وحذرة، وأن تنتقل إلى المسار المجاور بعيدًا عن مركبة الطوارئ المتوقفة عندما يكون ذلك آمنًا.","p":"صحيح. خفّف السرعة وابتعد إلى مسار آخر."},"ref":{"doc":"HI","page":29}},{"id":"hi-017","scope":"HI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Hawaii, which of these stopped vehicles with flashing lights is also covered by the move over law?","o":["A parked delivery van with no lights","A tow truck","A bus at a bus stop","A taxi waiting for a rider"],"h1":"Think of a truck that helps cars that break down.","h2":"Hawaii's move over law covers tow trucks as well as police, fire, ambulance and ocean safety vehicles.","p":"Right. Tow trucks are covered too."},"es":{"q":"En Hawái, ¿cuál de estos vehículos detenidos con luces intermitentes también está cubierto por la ley para moverse de carril?","o":["Una camioneta de reparto estacionada sin luces","Una grúa","Un autobús en la parada","Un taxi esperando a un pasajero"],"h1":"Piense en un camión que ayuda a los carros que se descomponen.","h2":"La ley de Hawái para moverse de carril cubre las grúas, además de los vehículos de policía, bomberos, ambulancia y seguridad en el océano.","p":"Correcto. Las grúas también están cubiertas."},"zh":{"q":"在 Hawaii，下面哪种停着、闪着灯的车辆也受 move over 法保护？","o":["一辆没开灯、停着的送货车","拖车","停在公交车站的公交车","等乘客的出租车"],"h1":"想一想帮助故障车的那种卡车。","h2":"Hawaii 的 move over 法保护拖车，也保护警车、消防车、救护车和海上救援车辆。","p":"对。拖车也受保护。"},"vi":{"q":"Ở Hawaii, xe nào dưới đây đang dừng và có đèn nhấp nháy cũng thuộc luật nhường làn (move over law)?","o":["Xe tải giao hàng đang đậu, không có đèn","Xe kéo (tow truck)","Xe buýt ở trạm xe buýt","Taxi đang chờ khách"],"h1":"Hãy nghĩ đến loại xe tải giúp những xe bị hư.","h2":"Luật nhường làn của Hawaii áp dụng cho xe kéo, cũng như xe cảnh sát, xe cứu hỏa, xe cứu thương và xe cứu hộ biển (ocean safety).","p":"Đúng. Xe kéo cũng được bảo vệ."},"tl":{"q":"Sa Hawaii, alin sa mga nakahintong sasakyang ito na may kumikislap na ilaw ang sakop din ng move over law?","o":["Nakaparadang delivery van na walang ilaw","Tow truck","Bus sa bus stop","Taxi na naghihintay ng pasahero"],"h1":"Isipin ang trak na tumutulong sa mga sasakyang nasira.","h2":"Sakop ng move over law ng Hawaii ang mga tow truck, pati ang mga sasakyan ng pulis, bumbero, ambulansya at ocean safety.","p":"Tama. Sakop din ang mga tow truck."},"ar":{"q":"في Hawaii، أي من هذه المركبات المتوقفة وأضواؤها تومض يشملها أيضًا قانون الابتعاد (move over law)؟","o":["شاحنة توصيل متوقفة بلا أضواء","شاحنة سحب (tow truck)","حافلة في موقف الحافلات","سيارة أجرة تنتظر راكبًا"],"h1":"فكّر في شاحنة تساعد السيارات المعطّلة.","h2":"قانون الابتعاد في Hawaii يشمل شاحنات السحب، وكذلك مركبات الشرطة والإطفاء والإسعاف والسلامة البحرية (ocean safety).","p":"صحيح. شاحنات السحب مشمولة أيضًا."},"ref":{"doc":"HI","page":null}},{"id":"hi-018","scope":"HI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Hawaii, what is the lowest blood alcohol level that is against the law for a driver under 21?","o":["0.08 percent","0.05 percent","0.02 percent","0.10 percent"],"h1":"Hawaii calls this rule zero tolerance.","h2":"In Hawaii it is against the law for a driver under 21 to drive with a blood alcohol level of 0.02 percent or more.","p":"Right. Under 21, the limit is 0.02 percent."},"es":{"q":"En Hawái, ¿cuál es el nivel más bajo de alcohol en la sangre que es ilegal para un conductor menor de 21 años?","o":["0.08 por ciento","0.05 por ciento","0.02 por ciento","0.10 por ciento"],"h1":"En Hawái esta regla se llama tolerancia cero.","h2":"En Hawái es ilegal que un conductor menor de 21 años maneje con un nivel de alcohol en la sangre de 0.02 por ciento o más.","p":"Correcto. Para menores de 21, el límite es 0.02 por ciento."},"zh":{"q":"在 Hawaii，对 21 岁以下的司机来说，血液酒精浓度最低到多少就违法？","o":["0.08%","0.05%","0.02%","0.10%"],"h1":"Hawaii 把这个规定叫做零容忍。","h2":"在 Hawaii，21 岁以下的司机血液酒精浓度达到 0.02% 或更高时开车就是违法的。","p":"对。21 岁以下，上限是 0.02%。"},"vi":{"q":"Ở Hawaii, nồng độ cồn trong máu thấp nhất là phạm luật đối với tài xế dưới 21 tuổi là bao nhiêu?","o":["0.08 phần trăm","0.05 phần trăm","0.02 phần trăm","0.10 phần trăm"],"h1":"Hawaii gọi luật này là không khoan nhượng (zero tolerance).","h2":"Ở Hawaii, tài xế dưới 21 tuổi lái xe với nồng độ cồn trong máu từ 0.02 phần trăm trở lên là phạm luật.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02 phần trăm."},"tl":{"q":"Sa Hawaii, ano ang pinakamababang blood alcohol level na labag sa batas para sa driver na wala pang 21?","o":["0.08 porsiyento","0.05 porsiyento","0.02 porsiyento","0.10 porsiyento"],"h1":"Tinatawag ito ng Hawaii na zero tolerance.","h2":"Sa Hawaii, labag sa batas para sa driver na wala pang 21 ang magmaneho nang may blood alcohol level na 0.02 porsiyento o higit pa.","p":"Tama. Kung wala pang 21, ang limitasyon ay 0.02 porsiyento."},"ar":{"q":"في Hawaii، ما أقل نسبة كحول في الدم تكون مخالفة للقانون للسائق تحت 21 سنة؟","o":["0.08 بالمئة","0.05 بالمئة","0.02 بالمئة","0.10 بالمئة"],"h1":"تسمّي Hawaii هذه القاعدة عدم التسامح (zero tolerance).","h2":"في Hawaii، من المخالف للقانون أن يقود سائق عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02 بالمئة أو أكثر.","p":"صحيح. تحت 21 سنة، الحدّ هو 0.02 بالمئة."},"ref":{"doc":"HI","page":56}},{"id":"hi-020","scope":"HI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Hawaii, on a road split by a barrier, which drivers must stop for a school bus with flashing red lights?","o":["Only the driver right behind the bus","No one, because the road is divided","Only drivers in the left lane","Drivers in all lanes on the same side as the bus"],"h1":"The barrier protects the other side, not your side.","h2":"In Hawaii, when a road is divided by a barrier, drivers in every lane on the same side as the stopped school bus must stop.","p":"Right. Every lane on the bus's side stops."},"es":{"q":"En Hawái, en una vía dividida por una barrera, ¿qué conductores deben detenerse ante un autobús escolar con luces rojas intermitentes?","o":["Solo el conductor justo detrás del autobús","Nadie, porque la vía está dividida","Solo los del carril izquierdo","Los de todos los carriles del mismo lado del autobús"],"h1":"La barrera protege el otro lado, no su lado.","h2":"En Hawái, cuando una vía está dividida por una barrera, los conductores de todos los carriles del mismo lado del autobús escolar detenido deben detenerse.","p":"Correcto. Todos los carriles del lado del autobús se detienen."},"zh":{"q":"在 Hawaii，道路被隔离墩分开时，哪些司机必须为闪着红灯的校车停车？","o":["只有紧跟在校车后面的司机","没有人，因为道路被分开了","只有左车道的司机","和校车在同一边的所有车道上的司机"],"h1":"隔离墩保护的是另一边，不是你这一边。","h2":"在 Hawaii，道路被隔离墩分开时，和停着的校车在同一边的每条车道上的司机都必须停车。","p":"对。校车那一边的每条车道都要停。"},"vi":{"q":"Ở Hawaii, trên con đường có dải phân cách, những tài xế nào phải dừng lại cho xe buýt trường học có đèn đỏ nhấp nháy?","o":["Chỉ tài xế ngay phía sau xe buýt","Không ai cả, vì đường có dải phân cách","Chỉ tài xế ở làn bên trái","Tài xế ở mọi làn cùng phía với xe buýt"],"h1":"Dải phân cách bảo vệ phía bên kia, không phải phía của bạn.","h2":"Ở Hawaii, khi đường có dải phân cách, tài xế ở mọi làn cùng phía với xe buýt trường học đang dừng phải dừng lại.","p":"Đúng. Mọi làn ở phía xe buýt đều phải dừng."},"tl":{"q":"Sa Hawaii, sa daan na hinati ng harang, aling mga driver ang dapat huminto para sa school bus na may kumikislap na pulang ilaw?","o":["Ang driver lang na nasa likod mismo ng bus","Wala, dahil hinati ang daan","Ang mga driver lang sa kaliwang lane","Ang mga driver sa lahat ng lane sa parehong panig ng bus"],"h1":"Pinoprotektahan ng harang ang kabilang panig, hindi ang panig mo.","h2":"Sa Hawaii, kapag hinati ng harang ang daan, dapat huminto ang mga driver sa bawat lane sa parehong panig ng nakahintong school bus.","p":"Tama. Humihinto ang bawat lane sa panig ng bus."},"ar":{"q":"في Hawaii، على طريق يفصله حاجز، أي السائقين يجب أن يتوقفوا لحافلة مدرسية أضواؤها الحمراء تومض؟","o":["فقط السائق الذي خلف الحافلة مباشرة","لا أحد، لأن الطريق مقسوم","فقط السائقون في المسار الأيسر","السائقون في كل المسارات على نفس جهة الحافلة"],"h1":"الحاجز يحمي الجهة الأخرى، وليس جهتك.","h2":"في Hawaii، عندما يكون الطريق مقسومًا بحاجز، يجب أن يتوقف السائقون في كل مسار على نفس جهة الحافلة المدرسية المتوقفة.","p":"صحيح. كل مسار على جهة الحافلة يتوقف."},"ref":{"doc":"HI","page":null}},{"id":"hi-021","scope":"HI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Hawaii, a crash causes property damage but no injuries. At what amount of damage must it be reported to the police right away?","o":["$1,000 or more","$3,000 or more","$5,000 or more","$10,000 or more"],"h1":"It is more than one thousand and less than five thousand dollars.","h2":"In Hawaii you must report a crash to the police right away if it causes $3,000 or more in property damage.","p":"Right. In Hawaii, $3,000 or more in damage must be reported to the police."},"es":{"q":"En Hawái, un choque causa daños a la propiedad pero no hay heridos. ¿A partir de qué cantidad de daños debe reportarlo de inmediato a la policía?","o":["$1,000 o más","$3,000 o más","$5,000 o más","$10,000 o más"],"h1":"Es más de mil y menos de cinco mil dólares.","h2":"En Hawái usted debe reportar un choque a la policía de inmediato si causa $3,000 o más en daños a la propiedad.","p":"Correcto. En Hawái, los daños de $3,000 o más se deben reportar a la policía."},"zh":{"q":"在 Hawaii，一场车祸造成财产损失，但没有人受伤。损失达到多少时必须马上报警？","o":["$1,000 或以上","$3,000 或以上","$5,000 或以上","$10,000 或以上"],"h1":"它比一千美元多，比五千美元少。","h2":"在 Hawaii，如果车祸造成 $3,000 或以上的财产损失，你必须马上报警。","p":"对。在 Hawaii，$3,000 或以上的损失必须报警。"},"vi":{"q":"Ở Hawaii, một vụ tai nạn làm hư hại tài sản nhưng không ai bị thương. Thiệt hại bao nhiêu thì phải báo cảnh sát ngay?","o":["$1,000 trở lên","$3,000 trở lên","$5,000 trở lên","$10,000 trở lên"],"h1":"Số tiền này nhiều hơn một nghìn và ít hơn năm nghìn đô la.","h2":"Ở Hawaii, bạn phải báo cảnh sát ngay nếu tai nạn gây thiệt hại tài sản từ $3,000 trở lên.","p":"Đúng. Ở Hawaii, thiệt hại từ $3,000 trở lên phải được báo cho cảnh sát."},"tl":{"q":"Sa Hawaii, may banggaan na sumira ng ari-arian pero walang nasaktan. Sa anong halaga ng pinsala dapat itong i-report agad sa pulis?","o":["$1,000 o higit pa","$3,000 o higit pa","$5,000 o higit pa","$10,000 o higit pa"],"h1":"Higit ito sa isang libo at kulang sa limang libong dolyar.","h2":"Sa Hawaii, dapat mong i-report agad sa pulis ang banggaan kung $3,000 o higit pa ang pinsala sa ari-arian.","p":"Tama. Sa Hawaii, dapat i-report sa pulis ang pinsalang $3,000 o higit pa."},"ar":{"q":"في Hawaii، تسبّب حادث في أضرار بالممتلكات دون إصابات. عند أي قيمة للأضرار يجب إبلاغ الشرطة فورًا؟","o":["$1,000 أو أكثر","$3,000 أو أكثر","$5,000 أو أكثر","$10,000 أو أكثر"],"h1":"هي أكثر من ألف دولار وأقل من خمسة آلاف دولار.","h2":"في Hawaii يجب أن تبلّغ الشرطة فورًا عن الحادث إذا سبّب أضرارًا بالممتلكات قيمتها $3,000 أو أكثر.","p":"صحيح. في Hawaii يجب إبلاغ الشرطة عن أضرار قيمتها $3,000 أو أكثر."},"ref":{"doc":"HI","page":52}},{"id":"hi-022","scope":"HI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Hawaii, what is the minimum liability insurance for injury to one person in a crash?","o":["$10,000","$15,000","$25,000","$20,000"],"h1":"The limit for the whole crash is twice this amount, $40,000.","h2":"In Hawaii the minimum liability insurance for injury to one person is $20,000, with $40,000 for the whole crash.","p":"Right. Hawaii requires at least $20,000 for injury to one person."},"es":{"q":"En Hawái, ¿cuál es el seguro mínimo de responsabilidad civil por lesiones a una persona en un choque?","o":["$10,000","$15,000","$25,000","$20,000"],"h1":"El límite para todo el choque es el doble de esta cantidad, $40,000.","h2":"En Hawái el seguro mínimo de responsabilidad civil por lesiones a una persona es de $20,000, con $40,000 para todo el choque.","p":"Correcto. Hawái exige al menos $20,000 por lesiones a una persona."},"zh":{"q":"在 Hawaii，车祸中一个人受伤的最低责任保险是多少？","o":["$10,000","$15,000","$25,000","$20,000"],"h1":"整场车祸的上限是这个金额的两倍，也就是 $40,000。","h2":"在 Hawaii，一个人受伤的最低责任保险是 $20,000，整场车祸是 $40,000。","p":"对。Hawaii 要求一个人受伤至少保 $20,000。"},"vi":{"q":"Ở Hawaii, bảo hiểm trách nhiệm tối thiểu cho thương tích của một người trong tai nạn là bao nhiêu?","o":["$10,000","$15,000","$25,000","$20,000"],"h1":"Mức cho cả vụ tai nạn gấp đôi số tiền này, là $40,000.","h2":"Ở Hawaii, bảo hiểm trách nhiệm tối thiểu cho thương tích của một người là $20,000, và $40,000 cho cả vụ tai nạn.","p":"Đúng. Hawaii yêu cầu ít nhất $20,000 cho thương tích của một người."},"tl":{"q":"Sa Hawaii, magkano ang pinakamababang liability insurance para sa pinsala sa katawan ng isang tao sa banggaan?","o":["$10,000","$15,000","$25,000","$20,000"],"h1":"Ang limit para sa buong banggaan ay doble nito, $40,000.","h2":"Sa Hawaii, ang pinakamababang liability insurance para sa pinsala sa isang tao ay $20,000, at $40,000 para sa buong banggaan.","p":"Tama. Sa Hawaii, kailangan ng hindi bababa sa $20,000 para sa pinsala sa isang tao."},"ar":{"q":"في Hawaii، ما الحد الأدنى لتأمين المسؤولية عن إصابة شخص واحد في حادث؟","o":["$10,000","$15,000","$25,000","$20,000"],"h1":"الحد للحادث كله ضعف هذا المبلغ، أي $40,000.","h2":"في Hawaii الحد الأدنى لتأمين المسؤولية عن إصابة شخص واحد هو $20,000، و$40,000 للحادث كله.","p":"صحيح. تشترط Hawaii مبلغ $20,000 على الأقل عن إصابة شخص واحد."},"ref":{"doc":"HI","page":54}},{"id":"hi-023","scope":"HI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Hawaii, what is the minimum liability insurance for damage to other people's property in one crash?","o":["$10,000","$20,000","$25,000","$40,000"],"h1":"It is the smallest of these amounts.","h2":"In Hawaii the minimum liability insurance for property damage is $10,000 per crash.","p":"Right. Hawaii requires at least $10,000 for property damage."},"es":{"q":"En Hawái, ¿cuál es el seguro mínimo de responsabilidad civil por daños a la propiedad de otras personas en un choque?","o":["$10,000","$20,000","$25,000","$40,000"],"h1":"Es la cantidad más pequeña de estas.","h2":"En Hawái el seguro mínimo de responsabilidad civil por daños a la propiedad es de $10,000 por choque.","p":"Correcto. Hawái exige al menos $10,000 por daños a la propiedad."},"zh":{"q":"在 Hawaii，一场车祸中对他人财产损失的最低责任保险是多少？","o":["$10,000","$20,000","$25,000","$40,000"],"h1":"它是这些金额中最小的。","h2":"在 Hawaii，财产损失的最低责任保险是每场车祸 $10,000。","p":"对。Hawaii 要求财产损失至少保 $10,000。"},"vi":{"q":"Ở Hawaii, bảo hiểm trách nhiệm tối thiểu cho thiệt hại tài sản của người khác trong một vụ tai nạn là bao nhiêu?","o":["$10,000","$20,000","$25,000","$40,000"],"h1":"Đó là số tiền nhỏ nhất trong các số này.","h2":"Ở Hawaii, bảo hiểm trách nhiệm tối thiểu cho thiệt hại tài sản là $10,000 cho mỗi vụ tai nạn.","p":"Đúng. Hawaii yêu cầu ít nhất $10,000 cho thiệt hại tài sản."},"tl":{"q":"Sa Hawaii, magkano ang pinakamababang liability insurance para sa pinsala sa ari-arian ng ibang tao sa isang banggaan?","o":["$10,000","$20,000","$25,000","$40,000"],"h1":"Ito ang pinakamaliit sa mga halagang ito.","h2":"Sa Hawaii, ang pinakamababang liability insurance para sa pinsala sa ari-arian ay $10,000 bawat banggaan.","p":"Tama. Sa Hawaii, kailangan ng hindi bababa sa $10,000 para sa pinsala sa ari-arian."},"ar":{"q":"في Hawaii، ما الحد الأدنى لتأمين المسؤولية عن أضرار ممتلكات الآخرين في حادث واحد؟","o":["$10,000","$20,000","$25,000","$40,000"],"h1":"هو أصغر هذه المبالغ.","h2":"في Hawaii الحد الأدنى لتأمين المسؤولية عن أضرار الممتلكات هو $10,000 لكل حادث.","p":"صحيح. تشترط Hawaii مبلغ $10,000 على الأقل عن أضرار الممتلكات."},"ref":{"doc":"HI","page":54}},{"id":"hi-024","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, how often must a regular car pass a safety inspection?","o":["Only when it is sold","Every two years","At least once a year","Every six months"],"h1":"Only ambulances need it more often than this.","h2":"In Hawaii a car must pass a safety inspection at least once a year, though a brand-new car gets a longer first period.","p":"Right. Hawaii cars need a safety inspection at least once a year."},"es":{"q":"En Hawái, ¿cada cuánto tiempo debe pasar un auto común una inspección de seguridad?","o":["Solo cuando se vende","Cada dos años","Por lo menos una vez al año","Cada seis meses"],"h1":"Solo las ambulancias la necesitan con más frecuencia.","h2":"En Hawái un auto debe pasar una inspección de seguridad por lo menos una vez al año, aunque un auto nuevo tiene un primer plazo más largo.","p":"Correcto. En Hawái los autos necesitan una inspección de seguridad por lo menos una vez al año."},"zh":{"q":"在 Hawaii，一般汽车多久必须通过一次安全检查？","o":["只在卖车时","每两年一次","至少每年一次","每六个月一次"],"h1":"只有救护车需要比这更常检查。","h2":"在 Hawaii，汽车至少每年必须通过一次安全检查，不过全新的车第一次可以隔更久。","p":"对。Hawaii 的汽车至少每年要做一次安全检查。"},"vi":{"q":"Ở Hawaii, một chiếc xe hơi thông thường phải qua kiểm tra an toàn bao lâu một lần?","o":["Chỉ khi bán xe","Hai năm một lần","Ít nhất mỗi năm một lần","Sáu tháng một lần"],"h1":"Chỉ xe cứu thương cần kiểm tra thường xuyên hơn mức này.","h2":"Ở Hawaii, xe hơi phải qua kiểm tra an toàn ít nhất mỗi năm một lần, nhưng xe mới hoàn toàn được thời hạn đầu tiên dài hơn.","p":"Đúng. Ở Hawaii, xe hơi cần kiểm tra an toàn ít nhất mỗi năm một lần."},"tl":{"q":"Sa Hawaii, gaano kadalas dapat pumasa sa safety inspection ang isang karaniwang kotse?","o":["Kapag ibinebenta lang ito","Tuwing dalawang taon","Hindi bababa sa isang beses bawat taon","Tuwing anim na buwan"],"h1":"Mga ambulansya lang ang kailangang mas madalas dito.","h2":"Sa Hawaii, dapat pumasa ang kotse sa safety inspection nang hindi bababa sa isang beses bawat taon, pero mas mahaba ang unang panahon para sa bagong-bagong kotse.","p":"Tama. Sa Hawaii, kailangan ng kotse ang safety inspection nang hindi bababa sa isang beses bawat taon."},"ar":{"q":"في Hawaii، كم مرة يجب أن تجتاز السيارة العادية فحص السلامة؟","o":["فقط عند بيعها","كل سنتين","مرة واحدة في السنة على الأقل","كل ستة أشهر"],"h1":"سيارات الإسعاف فقط تحتاجه أكثر من ذلك.","h2":"في Hawaii يجب أن تجتاز السيارة فحص السلامة مرة واحدة في السنة على الأقل، لكن السيارة الجديدة تمامًا تحصل على مدة أولى أطول.","p":"صحيح. في Hawaii تحتاج السيارات إلى فحص السلامة مرة واحدة في السنة على الأقل."},"ref":{"doc":"HI","page":18}},{"id":"hi-025","scope":"HI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Hawaii, your driver's license expired yesterday. May you still drive on it?","o":["Yes, for a 30-day grace period","No, it is not valid after it expires","Yes, until you get a renewal notice","Yes, if you renew within one year"],"h1":"Hawaii gives no extra time to drive after the date on the license.","h2":"In Hawaii a driver's license is not valid after its expiration date, because there is no grace period.","p":"Right. Hawaii has no grace period, so an expired license is not valid."},"es":{"q":"En Hawái, su licencia de conducir venció ayer. ¿Puede seguir manejando con ella?","o":["Sí, durante un periodo de gracia de 30 días","No, no es válida después de vencer","Sí, hasta que reciba un aviso de renovación","Sí, si la renueva dentro de un año"],"h1":"Hawái no da tiempo extra para manejar después de la fecha de la licencia.","h2":"En Hawái una licencia de conducir no es válida después de su fecha de vencimiento, porque no hay periodo de gracia.","p":"Correcto. Hawái no tiene periodo de gracia, así que una licencia vencida no es válida."},"zh":{"q":"在 Hawaii，你的驾照昨天过期了。你还可以用它开车吗？","o":["可以，有 30 天的宽限期","不可以，过期后就无效了","可以，直到你收到续期通知","可以，只要你在一年内续期"],"h1":"驾照上的日期过了以后，Hawaii 不给你额外的开车时间。","h2":"在 Hawaii，驾照过了到期日就无效，因为没有宽限期。","p":"对。Hawaii 没有宽限期，所以过期的驾照无效。"},"vi":{"q":"Ở Hawaii, bằng lái của bạn hết hạn hôm qua. Bạn còn được dùng nó để lái xe không?","o":["Được, có thời gian gia hạn 30 ngày","Không, bằng lái không còn hiệu lực sau khi hết hạn","Được, cho đến khi bạn nhận thông báo gia hạn","Được, nếu bạn gia hạn trong vòng một năm"],"h1":"Hawaii không cho thêm thời gian lái xe sau ngày ghi trên bằng lái.","h2":"Ở Hawaii, bằng lái không còn hiệu lực sau ngày hết hạn, vì không có thời gian ân hạn.","p":"Đúng. Hawaii không có thời gian ân hạn, nên bằng lái hết hạn không còn hiệu lực."},"tl":{"q":"Sa Hawaii, nag-expire kahapon ang driver's license mo. Puwede ka pa bang magmaneho gamit ito?","o":["Oo, may 30 araw na palugit","Hindi, wala na itong bisa pagkatapos mag-expire","Oo, hanggang makatanggap ka ng renewal notice","Oo, kung magre-renew ka sa loob ng isang taon"],"h1":"Walang dagdag na oras ang Hawaii para magmaneho pagkatapos ng petsa sa license.","h2":"Sa Hawaii, wala nang bisa ang driver's license pagkatapos ng expiration date nito, dahil walang palugit.","p":"Tama. Walang palugit sa Hawaii, kaya walang bisa ang expired na license."},"ar":{"q":"في Hawaii، انتهت رخصة قيادتك أمس. هل يمكنك أن تقود بها بعد؟","o":["نعم، توجد مهلة 30 يومًا","لا، لا تكون صالحة بعد انتهائها","نعم، حتى يصلك إشعار التجديد","نعم، إذا جدّدتها خلال سنة واحدة"],"h1":"لا تعطي Hawaii وقتًا إضافيًا للقيادة بعد التاريخ المكتوب على الرخصة.","h2":"في Hawaii لا تكون رخصة القيادة صالحة بعد تاريخ انتهائها، لأنه لا توجد مهلة.","p":"صحيح. لا توجد مهلة في Hawaii، لذلك الرخصة المنتهية غير صالحة."},"ref":{"doc":"HI","page":15}},{"id":"hi-026","scope":"HI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Hawaii, up to what age must a child ride in a car seat with a harness?","o":["Under 1","Under 13","Under 16","Under 4"],"h1":"It is a very young age, before most children start school.","h2":"In Hawaii, a child under 4 must ride in a car seat with a harness. From 4 to under 10, state law requires a harness seat or a booster seat.","p":"Right. Children under 4 ride in a car seat with a harness."},"es":{"q":"En Hawái, ¿hasta qué edad debe un niño ir en un asiento de seguridad con arnés?","o":["Menores de 1","Menores de 13","Menores de 16","Menores de 4"],"h1":"Es una edad muy temprana, antes de que la mayoría de los niños empiecen la escuela.","h2":"En Hawái, un niño menor de 4 años debe ir en un asiento de seguridad con arnés. De 4 a menos de 10 años, la ley estatal exige un asiento con arnés o un asiento elevador.","p":"Correcto. Los niños menores de 4 años van en un asiento de seguridad con arnés."},"zh":{"q":"在 Hawaii，几岁以下的孩子必须坐在带安全带束带（harness）的儿童座椅里？","o":["1 岁以下","13 岁以下","16 岁以下","4 岁以下"],"h1":"这是很小的年龄，大多数孩子还没上学。","h2":"在 Hawaii，4 岁以下的孩子必须坐在带束带的儿童座椅里。4 岁到 10 岁以下，州法律要求坐带束带的座椅或增高座椅。","p":"对。4 岁以下的孩子要坐带束带的儿童座椅。"},"vi":{"q":"Ở Hawaii, trẻ em dưới bao nhiêu tuổi phải ngồi ghế an toàn có dây đai (harness)?","o":["Dưới 1 tuổi","Dưới 13 tuổi","Dưới 16 tuổi","Dưới 4 tuổi"],"h1":"Đó là tuổi rất nhỏ, trước khi hầu hết trẻ em đi học.","h2":"Ở Hawaii, trẻ em dưới 4 tuổi phải ngồi ghế an toàn có dây đai. Từ 4 đến dưới 10 tuổi, luật của tiểu bang yêu cầu ghế có dây đai hoặc ghế nâng (booster seat).","p":"Đúng. Trẻ em dưới 4 tuổi ngồi ghế an toàn có dây đai."},"tl":{"q":"Sa Hawaii, hanggang anong edad dapat sumakay ang bata sa car seat na may harness?","o":["Wala pang 1","Wala pang 13","Wala pang 16","Wala pang 4"],"h1":"Napakabatang edad ito, bago pumasok sa paaralan ang karamihan ng bata.","h2":"Sa Hawaii, ang batang wala pang 4 na taon ay dapat sumakay sa car seat na may harness. Mula 4 hanggang wala pang 10, hinihingi ng batas ng estado ang seat na may harness o booster seat.","p":"Tama. Ang mga batang wala pang 4 ay sumasakay sa car seat na may harness."},"ar":{"q":"في Hawaii، حتى أي عمر يجب أن يجلس الطفل في مقعد سيارة بحزام أمان خاص (harness)؟","o":["أقل من 1","أقل من 13","أقل من 16","أقل من 4"],"h1":"هو عمر صغير جدًا، قبل أن يبدأ معظم الأطفال المدرسة.","h2":"في Hawaii، يجب أن يجلس الطفل الذي عمره أقل من 4 سنوات في مقعد سيارة بحزام خاص. ومن 4 إلى أقل من 10 سنوات، يطلب قانون الولاية مقعدًا بحزام خاص أو مقعدًا رافعًا (booster seat).","p":"صحيح. الأطفال الذين عمرهم أقل من 4 سنوات يجلسون في مقعد سيارة بحزام خاص."},"ref":{"doc":"HI","page":20}},{"id":"hi-027","scope":"HI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Hawaii, what happens right away if you refuse an alcohol test or test at 0.08 or more?","o":["Your license is taken and you get a 30-day temporary permit","You get a warning and may keep driving","You must pay a $50 fine on the spot","Your car is inspected for safety"],"h1":"You get a short paper permit while your case goes forward.","h2":"In Hawaii, if you refuse an alcohol test or test at 0.08 or more, your license is taken away and you get a 30-day temporary driving permit.","p":"Right. Hawaii takes the license and gives a 30-day temporary permit."},"es":{"q":"En Hawái, ¿qué pasa de inmediato si usted se niega a una prueba de alcohol o su resultado es 0.08 o más?","o":["Le quitan la licencia y le dan un permiso temporal de 30 días","Le dan una advertencia y puede seguir manejando","Debe pagar una multa de $50 en el momento","Le hacen una inspección de seguridad al auto"],"h1":"Le dan un permiso corto en papel mientras sigue su caso.","h2":"En Hawái, si usted se niega a una prueba de alcohol o su resultado es 0.08 o más, le quitan la licencia y le dan un permiso temporal para manejar de 30 días.","p":"Correcto. Hawái quita la licencia y da un permiso temporal de 30 días."},"zh":{"q":"在 Hawaii，如果你拒绝酒精测试，或测试结果是 0.08 或以上，马上会发生什么？","o":["你的驾照被收走，你会拿到 30 天的临时驾驶许可","你会收到警告，可以继续开车","你必须当场付 $50 罚款","你的车会接受安全检查"],"h1":"你的案子进行时，你会拿到一张短期的纸质许可。","h2":"在 Hawaii，如果你拒绝酒精测试或测试结果是 0.08 或以上，你的驾照会被收走，你会拿到 30 天的临时驾驶许可。","p":"对。Hawaii 会收走驾照，并给你 30 天的临时许可。"},"vi":{"q":"Ở Hawaii, điều gì xảy ra ngay nếu bạn từ chối thử nồng độ cồn hoặc kết quả là 0.08 trở lên?","o":["Bằng lái của bạn bị thu và bạn nhận giấy phép lái xe tạm thời 30 ngày","Bạn bị cảnh cáo và được tiếp tục lái xe","Bạn phải nộp phạt $50 tại chỗ","Xe của bạn bị kiểm tra an toàn"],"h1":"Bạn nhận một giấy phép giấy ngắn hạn trong khi vụ việc của bạn được xử lý.","h2":"Ở Hawaii, nếu bạn từ chối thử nồng độ cồn hoặc kết quả là 0.08 trở lên, bằng lái của bạn bị thu và bạn nhận giấy phép lái xe tạm thời 30 ngày.","p":"Đúng. Hawaii thu bằng lái và cho giấy phép tạm thời 30 ngày."},"tl":{"q":"Sa Hawaii, ano ang mangyayari agad kung tatanggi ka sa alcohol test o 0.08 o higit pa ang resulta mo?","o":["Kukunin ang license mo at bibigyan ka ng 30 araw na temporary permit","Bibigyan ka ng babala at puwede kang magpatuloy sa pagmamaneho","Dapat kang magbayad ng $50 na multa sa mismong lugar","Iinspeksyunin ang kotse mo para sa kaligtasan"],"h1":"Bibigyan ka ng maikling papel na permit habang tumatakbo ang kaso mo.","h2":"Sa Hawaii, kung tatanggi ka sa alcohol test o 0.08 o higit pa ang resulta mo, kukunin ang license mo at bibigyan ka ng 30 araw na temporary driving permit.","p":"Tama. Kinukuha ng Hawaii ang license at nagbibigay ng 30 araw na temporary permit."},"ar":{"q":"في Hawaii، ماذا يحدث فورًا إذا رفضت فحص الكحول أو كانت النتيجة 0.08 أو أكثر؟","o":["تُسحب رخصتك وتحصل على تصريح قيادة مؤقت لمدة 30 يومًا","تحصل على تحذير ويمكنك الاستمرار في القيادة","يجب أن تدفع غرامة $50 في المكان","تُفحص سيارتك من أجل السلامة"],"h1":"تحصل على تصريح ورقي قصير بينما تسير قضيتك.","h2":"في Hawaii، إذا رفضت فحص الكحول أو كانت النتيجة 0.08 أو أكثر، تُسحب رخصتك وتحصل على تصريح قيادة مؤقت لمدة 30 يومًا.","p":"صحيح. تسحب Hawaii الرخصة وتعطي تصريحًا مؤقتًا لمدة 30 يومًا."},"ref":{"doc":"HI","page":55}},{"id":"hi-028","scope":"HI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Hawaii, who in a car must wear a seat belt?","o":["Only the driver","Only people in the front seat","Everyone in the front and back seats","Only passengers under 18"],"h1":"Where you sit in the car does not matter.","h2":"In Hawaii everyone in the front and back seats must wear a seat belt or ride in a child restraint.","p":"Right. In Hawaii, every person in the car must be buckled up."},"es":{"q":"En Hawái, ¿quién debe usar el cinturón de seguridad en un auto?","o":["Solo el conductor","Solo las personas del asiento delantero","Todas las personas de los asientos delanteros y traseros","Solo los pasajeros menores de 18 años"],"h1":"No importa en qué parte del auto se siente.","h2":"En Hawái todas las personas de los asientos delanteros y traseros deben usar el cinturón de seguridad o ir en un asiento infantil.","p":"Correcto. En Hawái, todas las personas del auto deben abrocharse el cinturón."},"zh":{"q":"在 Hawaii，车里的哪些人必须系安全带？","o":["只有司机","只有前座的人","前座和后座的每个人","只有 18 岁以下的乘客"],"h1":"你坐在车里的哪个位置都一样。","h2":"在 Hawaii，前座和后座的每个人都必须系安全带，或坐儿童安全座椅。","p":"对。在 Hawaii，车里的每个人都必须系好安全带。"},"vi":{"q":"Ở Hawaii, ai trong xe phải thắt dây an toàn?","o":["Chỉ người lái xe","Chỉ người ngồi ghế trước","Mọi người ở ghế trước và ghế sau","Chỉ hành khách dưới 18 tuổi"],"h1":"Bạn ngồi ở chỗ nào trong xe cũng như nhau.","h2":"Ở Hawaii, mọi người ở ghế trước và ghế sau phải thắt dây an toàn hoặc ngồi ghế an toàn cho trẻ em.","p":"Đúng. Ở Hawaii, mọi người trong xe đều phải thắt dây an toàn."},"tl":{"q":"Sa Hawaii, sino sa kotse ang dapat magsuot ng seat belt?","o":["Ang driver lang","Ang mga nasa harapang upuan lang","Lahat ng nasa harap at likod na upuan","Ang mga pasaherong wala pang 18 lang"],"h1":"Hindi mahalaga kung saan ka nakaupo sa kotse.","h2":"Sa Hawaii, dapat magsuot ng seat belt o umupo sa child restraint ang lahat ng nasa harap at likod na upuan.","p":"Tama. Sa Hawaii, dapat naka-seat belt ang bawat tao sa kotse."},"ar":{"q":"في Hawaii، من في السيارة يجب أن يربط حزام الأمان؟","o":["السائق فقط","من في المقعد الأمامي فقط","كل من في المقاعد الأمامية والخلفية","الركاب تحت 18 سنة فقط"],"h1":"لا يهم أين تجلس في السيارة.","h2":"في Hawaii يجب على كل من في المقاعد الأمامية والخلفية أن يربط حزام الأمان أو يجلس في مقعد أمان للأطفال.","p":"صحيح. في Hawaii يجب أن يربط كل شخص في السيارة حزام الأمان."},"ref":{"doc":"HI","page":20}},{"id":"hi-029","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, how early may you renew your driver's license before it expires?","o":["Up to 30 days before","Up to 60 days before","Up to six months before","Up to two years before"],"h1":"It is more than two months.","h2":"In Hawaii you may renew your driver's license up to six months before the expiration date.","p":"Right. You can renew up to six months before your license expires."},"es":{"q":"En Hawái, ¿con cuánta anticipación puede renovar su licencia de manejar antes de que venza?","o":["Hasta 30 días antes","Hasta 60 días antes","Hasta seis meses antes","Hasta dos años antes"],"h1":"Es más de dos meses.","h2":"En Hawái usted puede renovar su licencia de manejar hasta seis meses antes de la fecha de vencimiento.","p":"Correcto. Puede renovarla hasta seis meses antes de que venza."},"zh":{"q":"在 Hawaii，驾照到期前最早多久可以续期？","o":["最多提前 30 天","最多提前 60 天","最多提前六个月","最多提前两年"],"h1":"它比两个月还长。","h2":"在 Hawaii，你最早可以在驾照到期前六个月续期。","p":"对。驾照到期前六个月内都可以续期。"},"vi":{"q":"Ở Hawaii, bạn có thể gia hạn bằng lái sớm nhất bao lâu trước khi bằng hết hạn?","o":["Tối đa 30 ngày trước","Tối đa 60 ngày trước","Tối đa sáu tháng trước","Tối đa hai năm trước"],"h1":"Thời gian này dài hơn hai tháng.","h2":"Ở Hawaii, bạn có thể gia hạn bằng lái sớm nhất sáu tháng trước ngày hết hạn.","p":"Đúng. Bạn có thể gia hạn tối đa sáu tháng trước khi bằng lái hết hạn."},"tl":{"q":"Sa Hawaii, gaano kaaga puwede mong i-renew ang driver's license mo bago ito mag-expire?","o":["Hanggang 30 araw bago","Hanggang 60 araw bago","Hanggang anim na buwan bago","Hanggang dalawang taon bago"],"h1":"Mas mahaba ito sa dalawang buwan.","h2":"Sa Hawaii, puwede mong i-renew ang driver's license mo hanggang anim na buwan bago ang petsa ng expiration.","p":"Tama. Puwede kang mag-renew hanggang anim na buwan bago mag-expire ang license mo."},"ar":{"q":"في Hawaii، كم مبكرًا يمكنك تجديد رخصة القيادة قبل انتهائها؟","o":["حتى 30 يومًا قبل الانتهاء","حتى 60 يومًا قبل الانتهاء","حتى ستة أشهر قبل الانتهاء","حتى سنتين قبل الانتهاء"],"h1":"المدة أطول من شهرين.","h2":"في Hawaii يمكنك تجديد رخصة القيادة حتى ستة أشهر قبل تاريخ انتهائها.","p":"صحيح. يمكنك التجديد حتى ستة أشهر قبل انتهاء رخصتك."},"ref":{"doc":"HI","page":15}},{"id":"hi-030","scope":"HI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Hawaii, a railroad crossing signal is flashing because a train is coming. How far from the nearest rail must you stop?","o":["At least 15 feet","At least 3 feet","At least 5 feet","At least 100 feet"],"h1":"Leave room so a train cannot hit the front of your car.","h2":"In Hawaii, when a railroad signal warns of a train, you must stop at least 15 feet from the nearest rail.","p":"Right. Stop at least 15 feet from the nearest rail."},"es":{"q":"En Hawái, la señal de un cruce de ferrocarril está prendida porque viene un tren. ¿A qué distancia del riel más cercano debe detenerse?","o":["Por lo menos a 15 pies","Por lo menos a 3 pies","Por lo menos a 5 pies","Por lo menos a 100 pies"],"h1":"Deje espacio para que el tren no golpee el frente de su carro.","h2":"En Hawái, cuando la señal del ferrocarril avisa que viene un tren, usted debe detenerse por lo menos a 15 pies del riel más cercano.","p":"Correcto. Deténgase por lo menos a 15 pies del riel más cercano."},"zh":{"q":"在 Hawaii，铁路道口的信号灯在闪，因为有火车要来。你必须停在离最近的铁轨多远的地方？","o":["至少 15 英尺","至少 3 英尺","至少 5 英尺","至少 100 英尺"],"h1":"留出空间，让火车撞不到你的车头。","h2":"在 Hawaii，铁路信号警告有火车来时，你必须停在离最近的铁轨至少 15 英尺的地方。","p":"对。停在离最近的铁轨至少 15 英尺的地方。"},"vi":{"q":"Ở Hawaii, đèn báo ở chỗ giao với đường sắt đang nhấp nháy vì có tàu hỏa đang đến. Bạn phải dừng cách đường ray gần nhất bao xa?","o":["Ít nhất 15 feet","Ít nhất 3 feet","Ít nhất 5 feet","Ít nhất 100 feet"],"h1":"Chừa khoảng trống để tàu hỏa không đụng vào đầu xe của bạn.","h2":"Ở Hawaii, khi đèn báo đường sắt cảnh báo có tàu hỏa, bạn phải dừng cách đường ray gần nhất ít nhất 15 feet.","p":"Đúng. Dừng cách đường ray gần nhất ít nhất 15 feet."},"tl":{"q":"Sa Hawaii, kumikislap ang signal sa tawiran ng tren dahil may paparating na tren. Gaano kalayo sa pinakamalapit na riles ka dapat huminto?","o":["Hindi bababa sa 15 feet","Hindi bababa sa 3 feet","Hindi bababa sa 5 feet","Hindi bababa sa 100 feet"],"h1":"Mag-iwan ng espasyo para hindi matamaan ng tren ang harap ng kotse mo.","h2":"Sa Hawaii, kapag nagbababala ang signal ng riles na may tren, dapat kang huminto nang hindi bababa sa 15 feet mula sa pinakamalapit na riles.","p":"Tama. Huminto nang hindi bababa sa 15 feet mula sa pinakamalapit na riles."},"ar":{"q":"في Hawaii، إشارة معبر السكة الحديدية تومض لأن قطارًا قادم. على أي مسافة من أقرب سكة يجب أن تتوقف؟","o":["15 feet على الأقل","3 feet على الأقل","5 feet على الأقل","100 feet على الأقل"],"h1":"اترك مسافة حتى لا يصطدم القطار بمقدمة سيارتك.","h2":"في Hawaii، عندما تحذّر إشارة السكة الحديدية من قطار، يجب أن تتوقف على بعد 15 feet على الأقل من أقرب سكة.","p":"صحيح. توقف على بعد 15 feet على الأقل من أقرب سكة."},"ref":{"doc":"HI","page":27}},{"id":"hi-031","scope":"HI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Hawaii, how much space should you leave between your car and a bicycle rider when you pass?","o":["At least 1 foot","At least 3 feet","At least 10 feet","At least 20 feet"],"h1":"It is about the length of one long step.","h2":"In Hawaii you should leave at least 3 feet of space between your car and a bicycle rider until you have safely passed.","p":"Right. Leave at least 3 feet when you pass a bicycle rider."},"es":{"q":"En Hawái, ¿cuánto espacio debe dejar entre su carro y un ciclista cuando lo rebasa?","o":["Por lo menos 1 pie","Por lo menos 3 pies","Por lo menos 10 pies","Por lo menos 20 pies"],"h1":"Es más o menos el largo de un paso largo.","h2":"En Hawái usted debe dejar por lo menos 3 pies de espacio entre su carro y un ciclista hasta que lo haya rebasado con seguridad.","p":"Correcto. Deje por lo menos 3 pies cuando rebase a un ciclista."},"zh":{"q":"在 Hawaii，你超过骑自行车的人时，车子和他之间应该留多少空间？","o":["至少 1 英尺","至少 3 英尺","至少 10 英尺","至少 20 英尺"],"h1":"大约是迈一大步的长度。","h2":"在 Hawaii，你应该在车子和骑自行车的人之间留至少 3 英尺的空间，直到你安全超过他。","p":"对。超过骑自行车的人时，要留至少 3 英尺。"},"vi":{"q":"Ở Hawaii, khi vượt người đi xe đạp, bạn nên chừa bao nhiêu khoảng cách giữa xe của bạn và người đó?","o":["Ít nhất 1 feet","Ít nhất 3 feet","Ít nhất 10 feet","Ít nhất 20 feet"],"h1":"Khoảng bằng một bước chân dài.","h2":"Ở Hawaii, bạn nên chừa ít nhất 3 feet giữa xe của bạn và người đi xe đạp cho đến khi bạn vượt qua an toàn.","p":"Đúng. Chừa ít nhất 3 feet khi vượt người đi xe đạp."},"tl":{"q":"Sa Hawaii, gaano kalaking espasyo ang dapat mong iwan sa pagitan ng kotse mo at ng nagbibisikleta kapag lumalampas ka?","o":["Hindi bababa sa 1 foot","Hindi bababa sa 3 feet","Hindi bababa sa 10 feet","Hindi bababa sa 20 feet"],"h1":"Mga isang mahabang hakbang ito.","h2":"Sa Hawaii, dapat kang mag-iwan ng hindi bababa sa 3 feet na espasyo sa pagitan ng kotse mo at ng nagbibisikleta hanggang ligtas kang makalampas.","p":"Tama. Mag-iwan ng hindi bababa sa 3 feet kapag lumalampas sa nagbibisikleta."},"ar":{"q":"في Hawaii، كم مسافة يجب أن تتركها بين سيارتك وراكب الدراجة عندما تتجاوزه؟","o":["1 foot على الأقل","3 feet على الأقل","10 feet على الأقل","20 feet على الأقل"],"h1":"إنها تقريبًا طول خطوة واحدة طويلة.","h2":"في Hawaii يجب أن تترك مسافة 3 feet على الأقل بين سيارتك وراكب الدراجة حتى تتجاوزه بأمان.","p":"صحيح. اترك 3 feet على الأقل عندما تتجاوز راكب دراجة."},"ref":{"doc":"HI","page":97}},{"id":"hi-032","scope":"HI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Hawaii, you want to pass on the left half of a two-lane road. How close to an intersection or railroad crossing may you do this?","o":["No closer than 25 feet","No closer than 50 feet","No closer than 75 feet","No closer than 100 feet"],"h1":"You need room to finish passing well before the crossing.","h2":"In Hawaii you must not drive on the left half of the road within 100 feet of an intersection or a railroad crossing.","p":"Right. Do not use the left half of the road within 100 feet of an intersection or railroad crossing."},"es":{"q":"En Hawái, usted quiere rebasar por la mitad izquierda de un camino de dos carriles. ¿Qué tan cerca de una intersección o de un cruce de ferrocarril puede hacerlo?","o":["No más cerca de 25 pies","No más cerca de 50 pies","No más cerca de 75 pies","No más cerca de 100 pies"],"h1":"Necesita espacio para terminar de rebasar mucho antes del cruce.","h2":"En Hawái usted no debe manejar por la mitad izquierda del camino a menos de 100 pies de una intersección o de un cruce de ferrocarril.","p":"Correcto. No use la mitad izquierda del camino a menos de 100 pies de una intersección o de un cruce de ferrocarril."},"zh":{"q":"在 Hawaii，你想在双车道道路的左半边超车。离路口或铁路道口多近就不能这样做？","o":["不能少于 25 英尺","不能少于 50 英尺","不能少于 75 英尺","不能少于 100 英尺"],"h1":"你需要在到达道口之前很早就完成超车。","h2":"在 Hawaii，离路口或铁路道口 100 英尺以内，你不可以开在道路的左半边。","p":"对。离路口或铁路道口 100 英尺以内，不要使用道路的左半边。"},"vi":{"q":"Ở Hawaii, bạn muốn vượt xe bằng cách đi vào nửa bên trái của đường hai làn. Bạn được làm vậy khi cách giao lộ hoặc chỗ giao với đường sắt gần nhất là bao nhiêu?","o":["Không gần hơn 25 feet","Không gần hơn 50 feet","Không gần hơn 75 feet","Không gần hơn 100 feet"],"h1":"Bạn cần đủ chỗ để vượt xong từ sớm, trước chỗ giao nhau.","h2":"Ở Hawaii, bạn không được lái ở nửa bên trái của đường trong vòng 100 feet trước giao lộ hoặc chỗ giao với đường sắt.","p":"Đúng. Không đi vào nửa bên trái của đường trong vòng 100 feet trước giao lộ hoặc chỗ giao với đường sắt."},"tl":{"q":"Sa Hawaii, gusto mong lumampas gamit ang kaliwang kalahati ng kalsadang may dalawang lane. Gaano kalapit sa intersection o tawiran ng tren ka puwedeng gumawa nito?","o":["Hindi lalapit sa 25 feet","Hindi lalapit sa 50 feet","Hindi lalapit sa 75 feet","Hindi lalapit sa 100 feet"],"h1":"Kailangan mo ng espasyo para matapos ang paglampas bago pa ang tawiran.","h2":"Sa Hawaii, hindi ka puwedeng magmaneho sa kaliwang kalahati ng kalsada sa loob ng 100 feet mula sa intersection o tawiran ng tren.","p":"Tama. Huwag gamitin ang kaliwang kalahati ng kalsada sa loob ng 100 feet mula sa intersection o tawiran ng tren."},"ar":{"q":"في Hawaii، تريد أن تتجاوز باستخدام النصف الأيسر من طريق ذي مسارين. ما أقرب مسافة من تقاطع أو معبر سكة حديدية يمكنك فيها فعل ذلك؟","o":["ليس أقرب من 25 feet","ليس أقرب من 50 feet","ليس أقرب من 75 feet","ليس أقرب من 100 feet"],"h1":"تحتاج إلى مسافة كافية لتنهي التجاوز قبل المعبر بوقت كافٍ.","h2":"في Hawaii لا يجوز لك القيادة في النصف الأيسر من الطريق على بعد 100 feet أو أقل من تقاطع أو معبر سكة حديدية.","p":"صحيح. لا تستخدم النصف الأيسر من الطريق على بعد 100 feet أو أقل من تقاطع أو معبر سكة حديدية."},"ref":{"doc":"HI","page":26}},{"id":"hi-033","scope":"HI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Hawaii, what is the youngest age to get a regular class 3 driver's license?","o":["17 years old","16 years old","18 years old","21 years old"],"h1":"It is one year older than the youngest age for a provisional license.","h2":"In Hawaii you must be at least 17 years old to get a class 3 driver's license.","p":"Right. A class 3 driver's license starts at age 17."},"es":{"q":"En Hawái, ¿cuál es la edad mínima para obtener una licencia de manejar regular de clase 3?","o":["17 años","16 años","18 años","21 años"],"h1":"Es un año más que la edad mínima para la licencia provisional.","h2":"En Hawái usted debe tener al menos 17 años para obtener una licencia de manejar de clase 3.","p":"Correcto. La licencia de clase 3 empieza a los 17 años."},"ref":{"doc":"HI","page":12}},{"id":"hi-034","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, how long must you hold a provisional license before you can apply for a full driver's license?","o":["30 days","90 days","Six months","Two years"],"h1":"It is half a year.","h2":"In Hawaii you must hold a provisional license for six months before you can apply for a driver's license.","p":"Right. You keep the provisional license for six months first."},"es":{"q":"En Hawái, ¿cuánto tiempo debe tener una licencia provisional antes de solicitar la licencia de manejar completa?","o":["30 días","90 días","Seis meses","Dos años"],"h1":"Es medio año.","h2":"En Hawái usted debe tener la licencia provisional durante seis meses antes de solicitar la licencia de manejar.","p":"Correcto. Primero tiene la licencia provisional durante seis meses."},"ref":{"doc":"HI","page":14}},{"id":"hi-035","scope":"HI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Hawaii, which test must you pass every time before your driver's license is renewed?","o":["A road test","A vision test","A written test","A parallel parking test"],"h1":"It checks how well you see.","h2":"In Hawaii you must pass a vision test before your driver's license is renewed.","p":"Right. A vision test comes before every renewal."},"es":{"q":"En Hawái, ¿qué examen debe aprobar cada vez antes de que se renueve su licencia de manejar?","o":["Un examen de manejo","Un examen de la vista","Un examen escrito","Un examen de estacionamiento en paralelo"],"h1":"Revisa qué tan bien ve usted.","h2":"En Hawái usted debe aprobar un examen de la vista antes de que se renueve su licencia de manejar.","p":"Correcto. Antes de cada renovación hay un examen de la vista."},"ref":{"doc":"HI","page":15}},{"id":"hi-036","scope":"HI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Hawaii, how many documents proving your home address in Hawaii must you bring for a REAL ID license or permit?","o":["None","One","Three","Two"],"h1":"A utility bill and a bank statement would be enough.","h2":"In Hawaii you must bring two documents that show your name and your home address in Hawaii.","p":"Right. You need two proofs of your Hawaii address."},"es":{"q":"En Hawái, ¿cuántos documentos que prueben su domicilio en Hawái debe llevar para una licencia o permiso REAL ID?","o":["Ninguno","Uno","Tres","Dos"],"h1":"Una factura de luz y un estado de cuenta del banco serían suficientes.","h2":"En Hawái usted debe llevar dos documentos que muestren su nombre y su domicilio en Hawái.","p":"Correcto. Necesita dos pruebas de su domicilio en Hawái."},"ref":{"doc":"HI","page":11}},{"id":"hi-037","scope":"HI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Hawaii, your license has expired. How long after the expiration date can you still renew it instead of applying as a new driver?","o":["Up to one year","Up to 10 days","Up to 30 days","Up to five years"],"h1":"It is twelve months.","h2":"In Hawaii you may renew an expired license within one year after the expiration date; after that you must apply as for an original license.","p":"Right. You have one year after it expires to renew it."},"es":{"q":"En Hawái, su licencia venció. ¿Cuánto tiempo después de la fecha de vencimiento todavía puede renovarla en lugar de solicitarla como conductor nuevo?","o":["Hasta un año","Hasta 10 días","Hasta 30 días","Hasta cinco años"],"h1":"Son doce meses.","h2":"En Hawái usted puede renovar una licencia vencida dentro de un año después de la fecha de vencimiento; después de eso debe solicitarla como una licencia nueva.","p":"Correcto. Tiene un año después del vencimiento para renovarla."},"ref":{"doc":"HI","page":15}},{"id":"hi-038","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, a visitor has a foreign driver's license and an International Driving Permit. How long may they drive with them?","o":["30 days after arrival","Six months after arrival","One year after arrival in the U.S.","As long as the foreign license is valid"],"h1":"Count from the day they first entered the United States.","h2":"In Hawaii a foreign license with an International Driving Permit is valid for one year after arrival in the United States.","p":"Right. They may drive with them for one year after arriving in the U.S."},"es":{"q":"En Hawái, un visitante tiene una licencia extranjera y un Permiso Internacional de Conducir. ¿Por cuánto tiempo puede manejar con ellos?","o":["30 días después de llegar","Seis meses después de llegar","Un año después de llegar a EE. UU.","Mientras la licencia extranjera esté vigente"],"h1":"Cuente desde el día en que entró por primera vez a Estados Unidos.","h2":"En Hawái una licencia extranjera con un Permiso Internacional de Conducir es válida por un año después de llegar a Estados Unidos.","p":"Correcto. Puede manejar con ellos por un año después de llegar a EE. UU."},"ref":{"doc":"HI","page":10}},{"id":"hi-039","scope":"HI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Hawaii, which of these can stop you from getting a driver's license?","o":["Owning more than one car","Having traffic tickets you have not taken care of","Living on a different island from the office","Wearing glasses"],"h1":"Think of something you still owe the court.","h2":"In Hawaii you cannot be licensed while you have outstanding traffic citations.","p":"Right. Unresolved traffic tickets can block your license."},"es":{"q":"En Hawái, ¿cuál de estas cosas puede impedirle obtener una licencia de manejar?","o":["Tener más de un carro","Tener multas de tránsito sin resolver","Vivir en otra isla que la oficina","Usar lentes"],"h1":"Piense en algo que todavía le debe a la corte.","h2":"En Hawái usted no puede obtener una licencia mientras tenga multas de tránsito pendientes.","p":"Correcto. Las multas de tránsito sin resolver pueden impedir su licencia."},"ref":{"doc":"HI","page":10}},{"id":"hi-040","scope":"HI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Hawaii, what is true about a limited purpose driver's license, given to people who do not provide a Social Security number?","o":["It lets you drive only at night","It is valid only on Oahu","It can be used to board a plane","It is good for driving only, not as federal ID"],"h1":"Its name says it has a limited use.","h2":"In Hawaii a limited purpose license is only a license to drive and cannot be used as ID for federal purposes such as boarding a plane.","p":"Right. It is for driving only, not for federal ID."},"es":{"q":"En Hawái, ¿qué es cierto sobre la licencia de propósito limitado, que se da a quienes no presentan un número de Seguro Social?","o":["Solo permite manejar de noche","Solo es válida en Oahu","Sirve para abordar un avión","Solo sirve para manejar, no como identificación federal"],"h1":"Su nombre dice que tiene un uso limitado.","h2":"En Hawái la licencia de propósito limitado solo es una licencia para manejar y no sirve como identificación federal, por ejemplo para abordar un avión.","p":"Correcto. Solo sirve para manejar, no como identificación federal."},"ref":{"doc":"HI","page":11}},{"id":"hi-041","scope":"HI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Hawaii, who may ride in the car with you during your road test?","o":["Only the examiner; passengers are not allowed","One friend in the back seat","Your parent in the back seat","Anyone with a valid license"],"h1":"The test is just you and the person grading you.","h2":"In Hawaii passengers are not permitted during the road test, so only the examiner rides with you.","p":"Right. No passengers are allowed during the road test."},"es":{"q":"En Hawái, ¿quién puede ir en el carro con usted durante su examen de manejo?","o":["Solo el examinador; no se permiten pasajeros","Un amigo en el asiento de atrás","Su padre o madre en el asiento de atrás","Cualquier persona con licencia vigente"],"h1":"En el examen solo van usted y la persona que lo califica.","h2":"En Hawái no se permiten pasajeros durante el examen de manejo, así que solo el examinador va con usted.","p":"Correcto. No se permiten pasajeros durante el examen de manejo."},"ref":{"doc":"HI","page":15}},{"id":"hi-042","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, car insurance must include basic benefits for medical and rehabilitation costs. Up to how much per person?","o":["$1,000","$5,000","$10,000","$100,000"],"h1":"It is the same amount as the minimum for property damage.","h2":"In Hawaii the basic insurance benefits cover up to $10,000 per person for medical and rehabilitation costs.","p":"Right. Basic benefits cover up to $10,000 per person."},"es":{"q":"En Hawái, el seguro del carro debe incluir beneficios básicos para gastos médicos y de rehabilitación. ¿Hasta cuánto por persona?","o":["$1,000","$5,000","$10,000","$100,000"],"h1":"Es la misma cantidad que el mínimo por daños a la propiedad.","h2":"En Hawái los beneficios básicos del seguro cubren hasta $10,000 por persona en gastos médicos y de rehabilitación.","p":"Correcto. Los beneficios básicos cubren hasta $10,000 por persona."},"ref":{"doc":"HI","page":54}},{"id":"hi-043","scope":"HI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Hawaii, what is the largest fine for each violation of the motor vehicle insurance law?","o":["$100","$5,000","$500","$50,000"],"h1":"It is a four-digit amount.","h2":"In Hawaii each violation of the motor vehicle insurance law can bring a fine of up to $5,000.","p":"Right. The fine can be as high as $5,000 for each violation."},"es":{"q":"En Hawái, ¿cuál es la multa más alta por cada infracción de la ley de seguro de vehículos?","o":["$100","$5,000","$500","$50,000"],"h1":"Es una cantidad de cuatro cifras.","h2":"En Hawái cada infracción de la ley de seguro de vehículos puede tener una multa de hasta $5,000.","p":"Correcto. La multa puede llegar a $5,000 por cada infracción."},"ref":{"doc":"HI","page":54}},{"id":"hi-044","scope":"HI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Hawaii, after you are convicted of certain driving offenses, how long must you keep proof of insurance (form SR-22) on file?","o":["30 days","Six months","One year","Three years"],"h1":"It is more than two years.","h2":"In Hawaii, after a conviction for certain offenses, you must file and keep proof of financial responsibility for three years.","p":"Right. You must keep the SR-22 proof on file for three years."},"es":{"q":"En Hawái, después de ser declarado culpable de ciertas infracciones de tránsito, ¿por cuánto tiempo debe mantener registrada la prueba de seguro (formulario SR-22)?","o":["30 días","Seis meses","Un año","Tres años"],"h1":"Es más de dos años.","h2":"En Hawái, después de una condena por ciertas infracciones, usted debe presentar y mantener la prueba de responsabilidad financiera durante tres años.","p":"Correcto. Debe mantener la prueba SR-22 durante tres años."},"ref":{"doc":"HI","page":53}},{"id":"hi-045","scope":"HI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Hawaii, a driver's blood alcohol level is above 0.05 but below 0.08 percent. How may the driver be considered?","o":["Impaired","Completely sober","Legally safe to drive","Under the influence only if under 18"],"h1":"It is below the level for being under the influence, but it is not safe.","h2":"In Hawaii a driver with a blood alcohol level above 0.05 and below 0.08 percent may be considered impaired.","p":"Right. Between 0.05 and 0.08 a driver may be considered impaired."},"es":{"q":"En Hawái, el nivel de alcohol en la sangre de un conductor es mayor de 0.05 pero menor de 0.08 por ciento. ¿Cómo se puede considerar al conductor?","o":["Con capacidad disminuida","Totalmente sobrio","Legalmente seguro para manejar","Bajo la influencia solo si tiene menos de 18 años"],"h1":"Está por debajo del nivel de estar bajo la influencia, pero no es seguro.","h2":"En Hawái un conductor con un nivel de alcohol en la sangre mayor de 0.05 y menor de 0.08 por ciento puede considerarse con capacidad disminuida.","p":"Correcto. Entre 0.05 y 0.08 se puede considerar que el conductor tiene la capacidad disminuida."},"ref":{"doc":"HI","page":56}},{"id":"hi-046","scope":"HI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Hawaii, where is it against the law to drink or have an alcoholic drink in your possession?","o":["Only inside a moving car after midnight","Only within 100 feet of a school","On any public highway or public sidewalk","Only on freeways"],"h1":"It covers every public road and the walkways beside them.","h2":"In Hawaii it is against the law to drink or possess an alcoholic drink on any public highway or public sidewalk.","p":"Right. No drinking or possessing alcohol on public highways or sidewalks."},"es":{"q":"En Hawái, ¿dónde es ilegal tomar o tener en su poder una bebida alcohólica?","o":["Solo dentro de un carro en movimiento después de la medianoche","Solo a menos de 100 pies de una escuela","En cualquier carretera pública o acera pública","Solo en las autopistas"],"h1":"Incluye todas las vías públicas y las aceras a su lado.","h2":"En Hawái es ilegal tomar o tener una bebida alcohólica en cualquier carretera pública o acera pública.","p":"Correcto. No se puede tomar ni tener alcohol en carreteras ni aceras públicas."},"ref":{"doc":"HI","page":56}},{"id":"hi-047","scope":"HI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Hawaii, it is against the law to leave a child alone in a car for five minutes or longer. Children under what age does this law protect?","o":["Under 4","Under 9","Under 13","Under 16"],"h1":"It is the age just before ten.","h2":"In Hawaii you may not leave a child under nine years old unattended in a car for five minutes or longer.","p":"Right. Never leave a child under nine alone in a car for five minutes or more."},"es":{"q":"En Hawái, es ilegal dejar a un niño solo en un carro por cinco minutos o más. ¿A los niños menores de qué edad protege esta ley?","o":["Menores de 4 años","Menores de 9 años","Menores de 13 años","Menores de 16 años"],"h1":"Es la edad justo antes de los diez.","h2":"En Hawái no se puede dejar a un niño menor de nueve años solo en un carro por cinco minutos o más.","p":"Correcto. Nunca deje a un niño menor de nueve años solo en un carro por cinco minutos o más."},"ref":{"doc":"HI","page":64}},{"id":"hi-048","scope":"HI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Hawaii, how much can it cost you if you do not stop for a school bus with flashing red lights when the law requires it?","o":["$50","$150","$250","$1,000"],"h1":"It is a four-digit amount.","h2":"In Hawaii failing to stop for a school bus with flashing red lights when required can cost you $1,000.","p":"Right. Not stopping for a school bus can cost $1,000."},"es":{"q":"En Hawái, ¿cuánto le puede costar no detenerse ante un autobús escolar con luces rojas intermitentes cuando la ley lo exige?","o":["$50","$150","$250","$1,000"],"h1":"Es una cantidad de cuatro cifras.","h2":"En Hawái no detenerse ante un autobús escolar con luces rojas intermitentes cuando se debe le puede costar $1,000.","p":"Correcto. No detenerse ante un autobús escolar puede costar $1,000."},"ref":{"doc":"HI","page":96}},{"id":"hi-049","scope":"HI","cat":"signals","sign":null,"c":0,"en":{"q":"In Hawaii, when may you turn left on a red light after stopping?","o":["From a one-way street onto another one-way street going left","From a two-way street when no cars are coming","Never; a left turn on red is always illegal","Only when a police officer is standing nearby"],"h1":"Both streets must carry traffic in only one direction.","h2":"In Hawaii, after stopping, you may turn left on red from a one-way street onto a one-way street where traffic moves to the left, unless a sign prohibits it.","p":"Right. Left on red is allowed only from one one-way street onto another going left."},"es":{"q":"En Hawái, ¿cuándo puede dar vuelta a la izquierda con la luz roja después de detenerse?","o":["De una calle de un solo sentido a otra de un solo sentido que va a la izquierda","Desde una calle de doble sentido si no vienen carros","Nunca; la vuelta a la izquierda con luz roja siempre es ilegal","Solo cuando hay un policía parado cerca"],"h1":"Las dos calles deben tener tráfico en un solo sentido.","h2":"En Hawái, después de detenerse, usted puede dar vuelta a la izquierda con luz roja de una calle de un solo sentido a otra de un solo sentido donde el tráfico va hacia la izquierda, si no hay un letrero que lo prohíba.","p":"Correcto. La vuelta a la izquierda con luz roja solo se permite de una calle de un solo sentido a otra que va a la izquierda."},"ref":{"doc":"HI","page":39}},{"id":"hi-050","scope":"HI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Hawaii, when you park along a curb, what is the farthest your car may be from the curb?","o":["24 inches","18 inches","12 inches","3 feet"],"h1":"It is one foot.","h2":"In Hawaii you may not park more than 12 inches from the curb.","p":"Right. Park no more than 12 inches from the curb."},"es":{"q":"En Hawái, cuando se estaciona junto a la acera, ¿a qué distancia máxima de la acera puede quedar su carro?","o":["24 pulgadas","18 pulgadas","12 pulgadas","3 pies"],"h1":"Es un pie.","h2":"En Hawái no se puede estacionar a más de 12 pulgadas de la acera.","p":"Correcto. Estaciónese a no más de 12 pulgadas de la acera."},"ref":{"doc":"HI","page":28}},{"id":"hi-051","scope":"HI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Hawaii, how long may you leave your car parked in one spot on a public street without moving it?","o":["No more than 8 hours","No more than 24 hours","No more than 72 hours","As long as you like"],"h1":"It is one full day.","h2":"In Hawaii you may not park on a public street or highway for more than 24 hours in a row.","p":"Right. Parking on a public street is limited to 24 hours in a row."},"es":{"q":"En Hawái, ¿cuánto tiempo puede dejar su carro estacionado en el mismo lugar de una calle pública sin moverlo?","o":["No más de 8 horas","No más de 24 horas","No más de 72 horas","El tiempo que quiera"],"h1":"Es un día completo.","h2":"En Hawái no se puede estacionar en una calle o carretera pública por más de 24 horas seguidas.","p":"Correcto. Estacionarse en una calle pública está limitado a 24 horas seguidas."},"ref":{"doc":"HI","page":29}},{"id":"hi-052","scope":"HI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Hawaii, outside business districts, how fast may a bicyclist ride on a sidewalk?","o":["15 mph or less","20 mph or less","Any speed, if the sidewalk is empty","10 mph or less, yielding to pedestrians"],"h1":"It is a slow speed, and people walking come first.","h2":"In Hawaii, outside business districts, a bicyclist may ride on a sidewalk at 10 mph or less and must yield to pedestrians.","p":"Right. On sidewalks outside business districts, bicycles go 10 mph or less and yield to people walking."},"es":{"q":"En Hawái, fuera de los distritos comerciales, ¿a qué velocidad puede ir un ciclista por la acera?","o":["15 mph o menos","20 mph o menos","A cualquier velocidad, si la acera está vacía","10 mph o menos, cediendo el paso a los peatones"],"h1":"Es una velocidad baja, y las personas que caminan van primero.","h2":"En Hawái, fuera de los distritos comerciales, un ciclista puede ir por la acera a 10 mph o menos y debe ceder el paso a los peatones.","p":"Correcto. En las aceras fuera de los distritos comerciales, las bicicletas van a 10 mph o menos y ceden el paso a los peatones."},"ref":{"doc":"HI","page":98}},{"id":"ia-001","scope":"IA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Iowa, what is the youngest age to get an instruction permit?","o":["13 years old","14 years old","15 years old","16 years old"],"h1":"Iowa lets teens start practicing earlier than many states.","h2":"In Iowa you can get an instruction permit at 14 years old, with a parent or guardian's consent.","p":"Right. Iowa instruction permits start at 14."},"es":{"q":"En Iowa, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["13 años","14 años","15 años","16 años"],"h1":"Iowa permite empezar a practicar antes que muchos estados.","h2":"En Iowa usted puede obtener un permiso de instrucción a los 14 años, con el consentimiento de su padre, madre o tutor.","p":"Correcto. En Iowa el permiso de instrucción empieza a los 14."},"zh":{"q":"在 Iowa，最小几岁可以拿到学习驾照（instruction permit）？","o":["13 岁","14 岁","15 岁","16 岁"],"h1":"Iowa 让青少年比很多州更早开始练习。","h2":"在 Iowa，经父母或监护人同意，你 14 岁就可以拿到学习驾照。","p":"对。Iowa 的学习驾照从 14 岁开始。"},"vi":{"q":"Ở Iowa, tuổi nhỏ nhất để lấy giấy phép tập lái (instruction permit) là bao nhiêu?","o":["13 tuổi","14 tuổi","15 tuổi","16 tuổi"],"h1":"Iowa cho thiếu niên bắt đầu tập lái sớm hơn nhiều tiểu bang khác.","h2":"Ở Iowa, bạn có thể lấy giấy phép tập lái khi 14 tuổi, với sự đồng ý của cha mẹ hoặc người giám hộ.","p":"Đúng. Ở Iowa, giấy phép tập lái bắt đầu từ 14 tuổi."},"tl":{"q":"Sa Iowa, ano ang pinakabatang edad para makakuha ng instruction permit?","o":["13 taong gulang","14 taong gulang","15 taong gulang","16 taong gulang"],"h1":"Pinapayagan ng Iowa ang mga kabataan na magsimulang mag-ensayo nang mas maaga kaysa sa maraming estado.","h2":"Sa Iowa, maaari kang makakuha ng instruction permit sa edad na 14, nang may pahintulot ng magulang o tagapag-alaga.","p":"Tama. Sa Iowa, nagsisimula ang instruction permit sa edad na 14."},"ar":{"q":"في ولاية Iowa، ما أصغر عمر للحصول على تصريح تعلّم القيادة (instruction permit)؟","o":["13 سنة","14 سنة","15 سنة","16 سنة"],"h1":"تسمح Iowa للمراهقين ببدء التدريب في وقت أبكر من كثير من الولايات.","h2":"في Iowa يمكنك الحصول على تصريح تعلّم القيادة في سن 14 سنة، بموافقة أحد الوالدين أو الوصي.","p":"صحيح. تصريح تعلّم القيادة في Iowa يبدأ من سن 14."},"ref":{"doc":"IA","page":null}},{"id":"ia-002","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, how many hours of supervised driving must a teen complete before an intermediate license?","o":["10 hours","50 hours","20 hours","40 hours"],"h1":"It is a smaller number than in most states.","h2":"An Iowa teen must complete 20 hours of supervised driving before getting an intermediate license, and driver education driving counts toward them.","p":"Right. Iowa asks for 20 supervised hours."},"es":{"q":"En Iowa, ¿cuántas horas de manejo supervisado debe completar un adolescente antes de la licencia intermedia?","o":["10 horas","50 horas","20 horas","40 horas"],"h1":"Es un número más bajo que en la mayoría de los estados.","h2":"Un adolescente en Iowa debe completar 20 horas de manejo supervisado antes de obtener la licencia intermedia, y el manejo en el curso de educación vial cuenta.","p":"Correcto. Iowa pide 20 horas supervisadas."},"zh":{"q":"在 Iowa，青少年拿中级驾照（intermediate license）前，必须完成多少小时有人陪同的驾驶？","o":["10 小时","50 小时","20 小时","40 小时"],"h1":"这个数字比大多数州少。","h2":"Iowa 的青少年拿中级驾照前，必须完成 20 小时有人陪同的驾驶，驾驶课上的驾驶时间也算在里面。","p":"对。Iowa 要求 20 小时有人陪同的驾驶。"},"vi":{"q":"Ở Iowa, thiếu niên phải lái xe có người giám sát bao nhiêu giờ trước khi lấy bằng lái trung gian (intermediate license)?","o":["10 giờ","50 giờ","20 giờ","40 giờ"],"h1":"Con số này nhỏ hơn so với hầu hết các tiểu bang.","h2":"Ở Iowa, thiếu niên phải lái xe có người giám sát 20 giờ trước khi lấy bằng lái trung gian, và giờ lái trong lớp học lái xe cũng được tính.","p":"Đúng. Iowa yêu cầu 20 giờ lái có người giám sát."},"tl":{"q":"Sa Iowa, ilang oras ng pagmamaneho na may gumagabay ang kailangang tapusin ng isang kabataan bago makakuha ng intermediate license?","o":["10 oras","50 oras","20 oras","40 oras"],"h1":"Mas maliit ang bilang na ito kaysa sa karamihan ng mga estado.","h2":"Kailangang tapusin ng isang kabataan sa Iowa ang 20 oras ng pagmamaneho na may gumagabay bago makakuha ng intermediate license, at kasama sa bilang ang pagmamaneho sa driver education.","p":"Tama. Humihingi ang Iowa ng 20 oras na may gumagabay."},"ar":{"q":"في Iowa، كم ساعة من القيادة تحت الإشراف يجب أن يكملها المراهق قبل الحصول على الرخصة المتوسطة (intermediate license)؟","o":["10 ساعات","50 ساعة","20 ساعة","40 ساعة"],"h1":"هذا العدد أقل مما في معظم الولايات.","h2":"يجب على المراهق في Iowa أن يكمل 20 ساعة من القيادة تحت الإشراف قبل الحصول على الرخصة المتوسطة، وساعات القيادة في دورة تعليم القيادة تُحسب منها.","p":"صحيح. تطلب Iowa عشرين ساعة تحت الإشراف."},"ref":{"doc":"IA","page":null}},{"id":"ia-003","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, how many of the supervised practice hours must be between sunset and sunrise?","o":["At least 2 hours","At least 5 hours","At least 10 hours","None are required"],"h1":"It is a small part of the total.","h2":"At least 2 of the 20 supervised hours in Iowa must be driven between sunset and sunrise.","p":"Right. Two hours must be after dark."},"es":{"q":"En Iowa, ¿cuántas de las horas de práctica supervisada deben ser entre la puesta y la salida del sol?","o":["Por lo menos 2 horas","Por lo menos 5 horas","Por lo menos 10 horas","No se exige ninguna"],"h1":"Es una parte pequeña del total.","h2":"Por lo menos 2 de las 20 horas supervisadas en Iowa deben manejarse entre la puesta y la salida del sol.","p":"Correcto. Dos horas deben ser de noche."},"zh":{"q":"在 Iowa，有人陪同的练习时间里，必须有多少小时是在日落到日出之间？","o":["至少 2 小时","至少 5 小时","至少 10 小时","不要求"],"h1":"这是总时间里的一小部分。","h2":"在 Iowa，20 小时有人陪同的驾驶中，至少 2 小时必须在日落到日出之间。","p":"对。必须有两个小时是在天黑以后开的。"},"vi":{"q":"Ở Iowa, trong số giờ tập lái có người giám sát, bao nhiêu giờ phải lái từ lúc mặt trời lặn đến lúc mặt trời mọc?","o":["Ít nhất 2 giờ","Ít nhất 5 giờ","Ít nhất 10 giờ","Không bắt buộc"],"h1":"Đó là một phần nhỏ của tổng số giờ.","h2":"Ở Iowa, ít nhất 2 trong 20 giờ lái có người giám sát phải lái từ lúc mặt trời lặn đến lúc mặt trời mọc.","p":"Đúng. Phải lái hai giờ khi trời tối."},"tl":{"q":"Sa Iowa, ilan sa mga oras ng pag-eensayo na may gumagabay ang dapat gawin mula paglubog hanggang pagsikat ng araw?","o":["Hindi bababa sa 2 oras","Hindi bababa sa 5 oras","Hindi bababa sa 10 oras","Walang kailangan"],"h1":"Maliit na bahagi ito ng kabuuan.","h2":"Hindi bababa sa 2 sa 20 oras na may gumagabay sa Iowa ang dapat imaneho mula paglubog hanggang pagsikat ng araw.","p":"Tama. Dalawang oras ang dapat sa gabi."},"ar":{"q":"في Iowa، كم ساعة من ساعات التدريب تحت الإشراف يجب أن تكون بين غروب الشمس وشروقها؟","o":["ساعتان على الأقل","5 ساعات على الأقل","10 ساعات على الأقل","لا يُشترط شيء"],"h1":"هي جزء صغير من المجموع.","h2":"يجب أن تكون ساعتان على الأقل من الساعات العشرين تحت الإشراف في Iowa بين غروب الشمس وشروقها.","p":"صحيح. يجب قيادة ساعتين بعد حلول الظلام."},"ref":{"doc":"IA","page":null}},{"id":"ia-004","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, how long must a teen hold an instruction permit before getting an intermediate license?","o":["3 months","6 months","9 months","12 months"],"h1":"It is a full year of practice.","h2":"An Iowa teen must hold a valid instruction permit for a total of 12 months before applying for an intermediate license.","p":"Right. Twelve months with the permit."},"es":{"q":"En Iowa, ¿cuánto tiempo debe tener un adolescente el permiso de instrucción antes de obtener la licencia intermedia?","o":["3 meses","6 meses","9 meses","12 meses"],"h1":"Es un año completo de práctica.","h2":"Un adolescente en Iowa debe tener un permiso de instrucción válido por un total de 12 meses antes de solicitar la licencia intermedia.","p":"Correcto. Doce meses con el permiso."},"zh":{"q":"在 Iowa，青少年必须持有学习驾照多久，才能拿到中级驾照？","o":["3 个月","6 个月","9 个月","12 个月"],"h1":"是整整一年的练习。","h2":"Iowa 的青少年必须总共持有有效的学习驾照 12 个月，才能申请中级驾照。","p":"对。持学习驾照十二个月。"},"vi":{"q":"Ở Iowa, thiếu niên phải giữ giấy phép tập lái (instruction permit) bao lâu trước khi lấy bằng lái trung gian (intermediate license)?","o":["3 tháng","6 tháng","9 tháng","12 tháng"],"h1":"Đó là một năm tập lái đầy đủ.","h2":"Ở Iowa, thiếu niên phải giữ giấy phép tập lái còn hiệu lực tổng cộng 12 tháng trước khi nộp đơn xin bằng lái trung gian.","p":"Đúng. Giữ giấy phép tập lái 12 tháng."},"tl":{"q":"Sa Iowa, gaano katagal dapat hawak ng isang kabataan ang instruction permit bago makakuha ng intermediate license?","o":["3 buwan","6 na buwan","9 na buwan","12 buwan"],"h1":"Isang buong taon ito ng pag-eensayo.","h2":"Ang isang kabataan sa Iowa ay dapat may hawak na balidong instruction permit nang kabuuang 12 buwan bago mag-apply para sa intermediate license.","p":"Tama. Labindalawang buwan na may permit."},"ar":{"q":"في Iowa، كم مدة يجب أن يحمل المراهق تصريح تعلّم القيادة (instruction permit) قبل الحصول على الرخصة المتوسطة (intermediate license)؟","o":["3 أشهر","6 أشهر","9 أشهر","12 شهرًا"],"h1":"هي سنة كاملة من التدريب.","h2":"يجب على المراهق في Iowa أن يحمل تصريح تعلّم قيادة ساريًا لمدة 12 شهرًا في المجموع قبل التقدم بطلب الرخصة المتوسطة.","p":"صحيح. اثنا عشر شهرًا مع التصريح."},"ref":{"doc":"IA","page":null}},{"id":"ia-005","scope":"IA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Iowa, what driving record does a teen need right before applying for an intermediate license?","o":["No record is checked","A clean record for at least 6 months in a row","A clean record for at least 1 month","No more than three tickets"],"h1":"The state looks at the last half year.","h2":"An Iowa teen needs a clean driving record for at least 6 months in a row right before applying for an intermediate license.","p":"Right. Six clean months in a row."},"es":{"q":"En Iowa, ¿qué historial de manejo necesita un adolescente justo antes de solicitar la licencia intermedia?","o":["No se revisa el historial","Un historial limpio por lo menos 6 meses seguidos","Un historial limpio por lo menos 1 mes","No más de tres multas"],"h1":"El estado revisa el último medio año.","h2":"Un adolescente en Iowa necesita un historial de manejo limpio por lo menos 6 meses seguidos justo antes de solicitar la licencia intermedia.","p":"Correcto. Seis meses seguidos sin problemas."},"zh":{"q":"在 Iowa，青少年在申请中级驾照之前，需要什么样的驾驶记录？","o":["不检查记录","连续至少 6 个月没有违规记录","至少 1 个月没有违规记录","罚单不超过三张"],"h1":"州政府看的是最近半年。","h2":"Iowa 的青少年在申请中级驾照之前，需要连续至少 6 个月没有违规的驾驶记录。","p":"对。连续六个月没有违规。"},"vi":{"q":"Ở Iowa, thiếu niên cần hồ sơ lái xe như thế nào ngay trước khi nộp đơn xin bằng lái trung gian (intermediate license)?","o":["Không kiểm tra hồ sơ","Hồ sơ sạch ít nhất 6 tháng liên tục","Hồ sơ sạch ít nhất 1 tháng","Không quá ba vé phạt"],"h1":"Tiểu bang xem xét nửa năm gần nhất.","h2":"Ở Iowa, thiếu niên cần hồ sơ lái xe sạch ít nhất 6 tháng liên tục ngay trước khi nộp đơn xin bằng lái trung gian.","p":"Đúng. Sáu tháng sạch liên tục."},"tl":{"q":"Sa Iowa, anong rekord sa pagmamaneho ang kailangan ng isang kabataan bago mismo mag-apply para sa intermediate license?","o":["Walang tinitingnang rekord","Malinis na rekord nang hindi bababa sa 6 na buwan nang sunod-sunod","Malinis na rekord nang hindi bababa sa 1 buwan","Hindi hihigit sa tatlong tiket"],"h1":"Tinitingnan ng estado ang huling kalahating taon.","h2":"Kailangan ng isang kabataan sa Iowa ng malinis na rekord sa pagmamaneho nang hindi bababa sa 6 na buwan nang sunod-sunod bago mismo mag-apply para sa intermediate license.","p":"Tama. Anim na malinis na buwan nang sunod-sunod."},"ar":{"q":"في Iowa، ما سجل القيادة الذي يحتاجه المراهق مباشرة قبل التقدم بطلب الرخصة المتوسطة (intermediate license)؟","o":["لا يتم فحص أي سجل","سجل نظيف لمدة 6 أشهر متتالية على الأقل","سجل نظيف لمدة شهر واحد على الأقل","ثلاث مخالفات كحد أقصى"],"h1":"تنظر الولاية إلى نصف السنة الأخير.","h2":"يحتاج المراهق في Iowa إلى سجل قيادة نظيف لمدة 6 أشهر متتالية على الأقل مباشرة قبل التقدم بطلب الرخصة المتوسطة.","p":"صحيح. ستة أشهر نظيفة متتالية."},"ref":{"doc":"IA","page":null}},{"id":"ia-006","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, what is the youngest age for an intermediate license?","o":["15 years old","15 and a half","16 years old","17 years old"],"h1":"It comes two years after the first permit.","h2":"You must be at least 16 years old to get an intermediate license in Iowa.","p":"Right. The intermediate license starts at 16."},"es":{"q":"En Iowa, ¿cuál es la edad mínima para la licencia intermedia?","o":["15 años","15 años y medio","16 años","17 años"],"h1":"Llega dos años después del primer permiso.","h2":"Usted debe tener por lo menos 16 años para obtener la licencia intermedia en Iowa.","p":"Correcto. La licencia intermedia empieza a los 16."},"zh":{"q":"在 Iowa，最小几岁可以拿到中级驾照？","o":["15 岁","15 岁半","16 岁","17 岁"],"h1":"它是在第一次拿学习驾照的两年以后。","h2":"在 Iowa，你必须至少 16 岁才能拿到中级驾照。","p":"对。中级驾照从 16 岁开始。"},"vi":{"q":"Ở Iowa, tuổi nhỏ nhất để lấy bằng lái trung gian (intermediate license) là bao nhiêu?","o":["15 tuổi","15 tuổi rưỡi","16 tuổi","17 tuổi"],"h1":"Đó là hai năm sau giấy phép đầu tiên.","h2":"Bạn phải ít nhất 16 tuổi để lấy bằng lái trung gian ở Iowa.","p":"Đúng. Bằng lái trung gian bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Iowa, ano ang pinakabatang edad para sa intermediate license?","o":["15 taong gulang","15 at kalahati","16 taong gulang","17 taong gulang"],"h1":"Dalawang taon ito pagkatapos ng unang permit.","h2":"Dapat ay hindi bababa sa 16 taong gulang ka para makakuha ng intermediate license sa Iowa.","p":"Tama. Nagsisimula ang intermediate license sa 16."},"ar":{"q":"في Iowa، ما أصغر عمر للحصول على الرخصة المتوسطة (intermediate license)؟","o":["15 سنة","15 سنة ونصف","16 سنة","17 سنة"],"h1":"يأتي بعد سنتين من التصريح الأول.","h2":"يجب أن يكون عمرك 16 سنة على الأقل للحصول على الرخصة المتوسطة في Iowa.","p":"صحيح. الرخصة المتوسطة تبدأ من سن 16."},"ref":{"doc":"IA","page":null}},{"id":"ia-007","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, during which hours may an intermediate license holder not drive without adult supervision?","o":["12:30 a.m. to 5 a.m.","11 p.m. to 5 a.m.","Midnight to 6 a.m.","9 p.m. to 6 a.m."],"h1":"The limit starts a little after midnight.","h2":"An Iowa intermediate license holder may not drive without adult supervision between 12:30 a.m. and 5 a.m., unless a waiver allows it.","p":"Right. 12:30 to 5 in the morning."},"es":{"q":"En Iowa, ¿en qué horario no puede manejar sin supervisión de un adulto quien tiene licencia intermedia?","o":["De 12:30 a.m. a 5 a.m.","De 11 p.m. a 5 a.m.","De medianoche a 6 a.m.","De 9 p.m. a 6 a.m."],"h1":"El límite empieza un poco después de la medianoche.","h2":"Quien tiene licencia intermedia en Iowa no puede manejar sin supervisión de un adulto entre las 12:30 a.m. y las 5 a.m., salvo que tenga una exención.","p":"Correcto. De 12:30 a 5 de la mañana."},"zh":{"q":"在 Iowa，持中级驾照的人在哪些时间不能在没有成年人陪同的情况下开车？","o":["凌晨 12:30 到早上 5 点","晚上 11 点到早上 5 点","午夜到早上 6 点","晚上 9 点到早上 6 点"],"h1":"这个限制在午夜过后不久开始。","h2":"在 Iowa，持中级驾照的人在凌晨 12:30 到早上 5 点之间不能在没有成年人陪同的情况下开车，除非有豁免书允许。","p":"对。凌晨 12:30 到早上 5 点。"},"vi":{"q":"Ở Iowa, người có bằng lái trung gian (intermediate license) không được lái xe mà không có người lớn giám sát trong những giờ nào?","o":["12:30 sáng đến 5 giờ sáng","11 giờ tối đến 5 giờ sáng","Nửa đêm đến 6 giờ sáng","9 giờ tối đến 6 giờ sáng"],"h1":"Giới hạn bắt đầu sau nửa đêm một chút.","h2":"Ở Iowa, người có bằng lái trung gian không được lái xe mà không có người lớn giám sát từ 12:30 sáng đến 5 giờ sáng, trừ khi có giấy miễn trừ cho phép.","p":"Đúng. Từ 12:30 đến 5 giờ sáng."},"tl":{"q":"Sa Iowa, sa anong mga oras hindi maaaring magmaneho ang may intermediate license nang walang gumagabay na adulto?","o":["12:30 a.m. hanggang 5 a.m.","11 p.m. hanggang 5 a.m.","Hatinggabi hanggang 6 a.m.","9 p.m. hanggang 6 a.m."],"h1":"Nagsisimula ang limitasyon nang kaunti pagkalipas ng hatinggabi.","h2":"Ang may intermediate license sa Iowa ay hindi maaaring magmaneho nang walang gumagabay na adulto mula 12:30 a.m. hanggang 5 a.m., maliban kung may waiver na nagpapahintulot.","p":"Tama. 12:30 hanggang 5 ng umaga."},"ar":{"q":"في Iowa، في أي ساعات لا يجوز لحامل الرخصة المتوسطة (intermediate license) أن يقود دون إشراف شخص بالغ؟","o":["من 12:30 بعد منتصف الليل إلى 5 صباحًا","من 11 مساءً إلى 5 صباحًا","من منتصف الليل إلى 6 صباحًا","من 9 مساءً إلى 6 صباحًا"],"h1":"يبدأ المنع بعد منتصف الليل بقليل.","h2":"لا يجوز لحامل الرخصة المتوسطة في Iowa أن يقود دون إشراف شخص بالغ من 12:30 بعد منتصف الليل إلى 5 صباحًا، إلا إذا سمح له بذلك إعفاء موقّع.","p":"صحيح. من 12:30 إلى 5 صباحًا."},"ref":{"doc":"IA","page":null}},{"id":"ia-008","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, how can an intermediate license holder legally drive alone after 12:30 a.m. for school or work?","o":["Show a school ID","Call a parent before driving","Drive only on city streets","Carry a waiver signed by a parent or guardian"],"h1":"A parent fills out a form for this.","h2":"A parent, guardian or custodian can sign a waiver for school or work driving, and the teen must carry it in the vehicle.","p":"Right. A signed waiver in the vehicle."},"es":{"q":"En Iowa, ¿cómo puede quien tiene licencia intermedia manejar solo después de las 12:30 a.m. por la escuela o el trabajo?","o":["Mostrar su credencial escolar","Llamar a un padre antes de manejar","Manejar solo por calles de la ciudad","Llevar una exención firmada por un padre o tutor"],"h1":"Un padre llena un formulario para esto.","h2":"Un padre, tutor o custodio puede firmar una exención para manejar por la escuela o el trabajo, y el adolescente debe llevarla en el vehículo.","p":"Correcto. Una exención firmada dentro del vehículo."},"zh":{"q":"在 Iowa，持中级驾照的人怎样才能合法地在凌晨 12:30 以后为上学或上班一个人开车？","o":["出示学生证","开车前给父母打电话","只在市区街道上开","带着父母或监护人签字的豁免书"],"h1":"这需要父母填一张表格。","h2":"父母、监护人或看护人可以为上学或上班开车签一份豁免书，青少年必须把它带在车里。","p":"对。车里要有签了字的豁免书。"},"vi":{"q":"Ở Iowa, người có bằng lái trung gian (intermediate license) có thể lái xe một mình một cách hợp pháp sau 12:30 sáng để đi học hoặc đi làm bằng cách nào?","o":["Xuất trình thẻ học sinh","Gọi cho cha mẹ trước khi lái","Chỉ lái trên đường trong thành phố","Mang theo giấy miễn trừ (waiver) có chữ ký của cha mẹ hoặc người giám hộ"],"h1":"Cha mẹ điền một mẫu đơn cho việc này.","h2":"Cha mẹ, người giám hộ hoặc người trông nom có thể ký giấy miễn trừ để lái xe đi học hoặc đi làm, và thiếu niên phải mang giấy này trong xe.","p":"Đúng. Mang giấy miễn trừ có chữ ký trong xe."},"tl":{"q":"Sa Iowa, paano legal na makakapagmaneho nang mag-isa ang may intermediate license pagkalipas ng 12:30 a.m. para sa paaralan o trabaho?","o":["Ipakita ang school ID","Tawagan ang magulang bago magmaneho","Magmaneho lamang sa mga kalye ng lungsod","Magdala ng waiver na pinirmahan ng magulang o tagapag-alaga"],"h1":"May form na pinupunan ang magulang para dito.","h2":"Maaaring pumirma ang magulang, tagapag-alaga o custodian ng waiver para sa pagmamaneho papunta sa paaralan o trabaho, at dapat itong dala ng kabataan sa sasakyan.","p":"Tama. Isang pinirmahang waiver sa sasakyan."},"ar":{"q":"في Iowa، كيف يمكن لحامل الرخصة المتوسطة (intermediate license) أن يقود وحده بشكل قانوني بعد 12:30 بعد منتصف الليل من أجل المدرسة أو العمل؟","o":["إظهار بطاقة المدرسة","الاتصال بأحد الوالدين قبل القيادة","القيادة في شوارع المدينة فقط","حمل إعفاء (waiver) موقّع من أحد الوالدين أو الوصي"],"h1":"يملأ أحد الوالدين نموذجًا لهذا الغرض.","h2":"يمكن لأحد الوالدين أو الوصي أو الكفيل أن يوقّع إعفاءً للقيادة من أجل المدرسة أو العمل، ويجب على المراهق أن يحمله في السيارة.","p":"صحيح. إعفاء موقّع في السيارة."},"ref":{"doc":"IA","page":null}},{"id":"ia-009","scope":"IA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Iowa, during the first 6 months with an intermediate license, how many unrelated passengers under 18 may ride along when no adult supervises?","o":["None","One","Two","Three"],"h1":"Brothers, sisters and household children do not count.","h2":"During the first 6 months, an Iowa intermediate license holder may carry only one unrelated passenger under 18, unless a parent allows more.","p":"Right. Only one unrelated minor."},"es":{"q":"En Iowa, durante los primeros 6 meses con licencia intermedia, ¿cuántos pasajeros menores de 18 años que no son familiares pueden ir con usted sin un adulto supervisando?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Los hermanos y los niños que viven en su casa no cuentan.","h2":"Durante los primeros 6 meses, quien tiene licencia intermedia en Iowa puede llevar solo un pasajero menor de 18 años que no sea familiar, salvo que un padre permita más.","p":"Correcto. Solo un menor que no es familiar."},"zh":{"q":"在 Iowa，拿到中级驾照的头 6 个月里，没有成年人陪同时，可以载几个不是亲属、18 岁以下的乘客？","o":["一个都不可以","一个","两个","三个"],"h1":"兄弟姐妹和家里的孩子不算。","h2":"在头 6 个月里，Iowa 持中级驾照的人只能载一个不是亲属、18 岁以下的乘客，除非父母允许载更多。","p":"对。只能载一个不是亲属的未成年人。"},"vi":{"q":"Ở Iowa, trong 6 tháng đầu có bằng lái trung gian (intermediate license), khi không có người lớn giám sát, được chở bao nhiêu hành khách dưới 18 tuổi không phải người thân?","o":["Không ai","Một người","Hai người","Ba người"],"h1":"Anh chị em và trẻ em trong cùng nhà không được tính.","h2":"Trong 6 tháng đầu, người có bằng lái trung gian ở Iowa chỉ được chở một hành khách dưới 18 tuổi không phải người thân, trừ khi cha mẹ cho phép nhiều hơn.","p":"Đúng. Chỉ một trẻ vị thành niên không phải người thân."},"tl":{"q":"Sa Iowa, sa unang 6 na buwan na may intermediate license, ilang pasaherong wala pang 18 na hindi kamag-anak ang maaaring isakay kapag walang gumagabay na adulto?","o":["Wala","Isa","Dalawa","Tatlo"],"h1":"Hindi binibilang ang mga kapatid at mga batang kasama sa bahay.","h2":"Sa unang 6 na buwan, ang may intermediate license sa Iowa ay maaaring magsakay ng isang pasaherong wala pang 18 na hindi kamag-anak lamang, maliban kung pinapayagan ng magulang ang higit pa.","p":"Tama. Isang menor de edad lamang na hindi kamag-anak."},"ar":{"q":"في Iowa، خلال أول 6 أشهر مع الرخصة المتوسطة (intermediate license)، كم راكبًا دون 18 سنة من غير الأقارب يمكن أن يركب معك عندما لا يشرف شخص بالغ؟","o":["لا أحد","واحد","اثنان","ثلاثة"],"h1":"الإخوة والأخوات والأطفال الذين يعيشون في البيت نفسه لا يُحسبون.","h2":"خلال أول 6 أشهر، يمكن لحامل الرخصة المتوسطة في Iowa أن يحمل راكبًا واحدًا فقط دون 18 سنة من غير الأقارب، إلا إذا سمح أحد الوالدين بأكثر.","p":"صحيح. قاصر واحد فقط من غير الأقارب."},"ref":{"doc":"IA","page":null}},{"id":"ia-010","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, what is the youngest age for a minor school license?","o":["14 years old","15 years old","14 and a half","16 years old"],"h1":"It is halfway between two birthdays.","h2":"You can get an Iowa minor school license at 14 and a half, after driver education and six clean months with a permit.","p":"Right. Fourteen and a half."},"es":{"q":"En Iowa, ¿cuál es la edad mínima para la licencia escolar de menor?","o":["14 años","15 años","14 años y medio","16 años"],"h1":"Está a la mitad entre dos cumpleaños.","h2":"Usted puede obtener la licencia escolar de menor en Iowa a los 14 años y medio, después de la educación vial y seis meses limpios con el permiso.","p":"Correcto. Catorce años y medio."},"zh":{"q":"在 Iowa，最小几岁可以拿到未成年人上学驾照（minor school license）？","o":["14 岁","15 岁","14 岁半","16 岁"],"h1":"它在两个生日的正中间。","h2":"在 Iowa，上完驾驶课、并持学习驾照六个月没有违规以后，你 14 岁半就可以拿到未成年人上学驾照。","p":"对。十四岁半。"},"vi":{"q":"Ở Iowa, tuổi nhỏ nhất để lấy bằng lái đi học cho trẻ vị thành niên (minor school license) là bao nhiêu?","o":["14 tuổi","15 tuổi","14 tuổi rưỡi","16 tuổi"],"h1":"Đó là ở giữa hai ngày sinh nhật.","h2":"Bạn có thể lấy bằng lái đi học cho trẻ vị thành niên ở Iowa khi 14 tuổi rưỡi, sau khi học lái xe và có sáu tháng sạch với giấy phép tập lái.","p":"Đúng. Mười bốn tuổi rưỡi."},"tl":{"q":"Sa Iowa, ano ang pinakabatang edad para sa minor school license?","o":["14 taong gulang","15 taong gulang","14 at kalahati","16 taong gulang"],"h1":"Nasa gitna ito ng dalawang kaarawan.","h2":"Maaari kang makakuha ng minor school license sa Iowa sa edad na 14 at kalahati, pagkatapos ng driver education at anim na malinis na buwan na may permit.","p":"Tama. Labing-apat at kalahati."},"ar":{"q":"في Iowa، ما أصغر عمر للحصول على رخصة المدرسة للقاصرين (minor school license)؟","o":["14 سنة","15 سنة","14 سنة ونصف","16 سنة"],"h1":"هو في منتصف المسافة بين عيدَي ميلاد.","h2":"يمكنك الحصول على رخصة المدرسة للقاصرين في Iowa في سن 14 سنة ونصف، بعد دورة تعليم القيادة وستة أشهر نظيفة مع التصريح.","p":"صحيح. أربع عشرة سنة ونصف."},"ref":{"doc":"IA","page":null}},{"id":"ia-011","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, with a minor school license (special minor's restricted license), how far may a teen drive alone to work?","o":["25 miles or less","Any distance","5 miles or less","100 miles or less"],"h1":"The trip to work has a distance limit.","h2":"With an Iowa special minor's restricted license, a teen may drive alone to work only when the trip is 25 miles or less.","p":"Right. The drive to work must be 25 miles or less."},"es":{"q":"En Iowa, con una licencia escolar para menores (licencia restringida especial para menores), ¿qué distancia puede manejar solo un adolescente para ir al trabajo?","o":["25 millas o menos","Cualquier distancia","5 millas o menos","100 millas o menos"],"h1":"El viaje al trabajo tiene un límite de distancia.","h2":"Con una licencia restringida especial para menores de Iowa, un adolescente puede manejar solo al trabajo únicamente si el viaje es de 25 millas o menos.","p":"Correcto. El viaje al trabajo debe ser de 25 millas o menos."},"zh":{"q":"在 Iowa，持未成年人上学驾照（special minor's restricted license）的青少年，最远可以一个人开车去多远的地方上班？","o":["25 英里或以内","多远都可以","5 英里或以内","100 英里或以内"],"h1":"开车去上班有距离限制。","h2":"在 Iowa，持 special minor's restricted license 的青少年，只有在上班路程是 25 英里或以内时，才可以一个人开车去上班。","p":"对。开车去上班的路程必须是 25 英里或以内。"},"vi":{"q":"Ở Iowa, với bằng lái đi học cho trẻ vị thành niên (special minor's restricted license), thiếu niên được lái xe một mình đi làm xa bao nhiêu?","o":["25 dặm trở xuống","Bất kỳ khoảng cách nào","5 dặm trở xuống","100 dặm trở xuống"],"h1":"Chuyến đi làm có giới hạn khoảng cách.","h2":"Với bằng lái đặc biệt có giới hạn cho trẻ vị thành niên ở Iowa, thiếu niên chỉ được lái xe một mình đi làm khi quãng đường là 25 dặm trở xuống.","p":"Đúng. Quãng đường đi làm phải từ 25 dặm trở xuống."},"tl":{"q":"Sa Iowa, gamit ang minor school license (special minor's restricted license), gaano kalayo maaaring magmaneho nang mag-isa ang isang kabataan papunta sa trabaho?","o":["25 milya o mas kaunti","Kahit anong layo","5 milya o mas kaunti","100 milya o mas kaunti"],"h1":"May limitasyon sa layo ang biyahe papunta sa trabaho.","h2":"Gamit ang special minor's restricted license sa Iowa, maaaring magmaneho nang mag-isa ang kabataan papunta sa trabaho kung 25 milya o mas kaunti lamang ang biyahe.","p":"Tama. Dapat 25 milya o mas kaunti ang biyahe papunta sa trabaho."},"ar":{"q":"في Iowa، مع رخصة المدرسة للقاصرين (special minor's restricted license)، ما المسافة التي يمكن للمراهق أن يقودها وحده إلى العمل؟","o":["25 ميلًا أو أقل","أي مسافة","5 أميال أو أقل","100 ميل أو أقل"],"h1":"للرحلة إلى العمل حد للمسافة.","h2":"مع رخصة القاصر الخاصة المقيّدة في Iowa، يمكن للمراهق أن يقود وحده إلى العمل فقط عندما تكون الرحلة 25 ميلًا أو أقل.","p":"صحيح. يجب أن تكون الرحلة إلى العمل 25 ميلًا أو أقل."},"ref":{"doc":"IA","page":null}},{"id":"ia-012","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, how old must a family member be to supervise a teen with an instruction permit?","o":["16 or older","18 or older","25 or older","21 or older"],"h1":"The same age as the legal drinking age.","h2":"In Iowa, an immediate family member who supervises a permit driver must be licensed and at least 21 years old.","p":"Right. A family member must be 21 or older."},"es":{"q":"En Iowa, ¿qué edad debe tener un familiar para supervisar a un adolescente con permiso de instrucción?","o":["16 años o más","18 años o más","25 años o más","21 años o más"],"h1":"Es la misma edad para tomar alcohol legalmente.","h2":"En Iowa, un familiar directo que supervisa a un conductor con permiso debe tener licencia y por lo menos 21 años.","p":"Correcto. El familiar debe tener 21 años o más."},"zh":{"q":"在 Iowa，陪同持学习驾照的青少年开车的家人必须几岁？","o":["16 岁或以上","18 岁或以上","25 岁或以上","21 岁或以上"],"h1":"和法定可以喝酒的年龄一样。","h2":"在 Iowa，陪同持学习驾照的人开车的直系亲属必须有驾照，而且至少 21 岁。","p":"对。家人必须 21 岁或以上。"},"vi":{"q":"Ở Iowa, người thân trong gia đình phải bao nhiêu tuổi để giám sát thiếu niên có giấy phép tập lái (instruction permit)?","o":["16 tuổi trở lên","18 tuổi trở lên","25 tuổi trở lên","21 tuổi trở lên"],"h1":"Bằng với tuổi được phép uống rượu hợp pháp.","h2":"Ở Iowa, người thân trong gia đình giám sát người tập lái phải có bằng lái và ít nhất 21 tuổi.","p":"Đúng. Người thân phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Iowa, ilang taon dapat ang isang kapamilya para gumabay sa kabataang may instruction permit?","o":["16 o mas matanda","18 o mas matanda","25 o mas matanda","21 o mas matanda"],"h1":"Kapareho ng legal na edad para uminom ng alak.","h2":"Sa Iowa, ang malapit na kapamilya na gumagabay sa nagmamanehong may permit ay dapat may lisensya at hindi bababa sa 21 taong gulang.","p":"Tama. Dapat 21 o mas matanda ang kapamilya."},"ar":{"q":"في Iowa، كم يجب أن يكون عمر فرد العائلة الذي يشرف على مراهق يحمل تصريح تعلّم القيادة (instruction permit)؟","o":["16 سنة أو أكثر","18 سنة أو أكثر","25 سنة أو أكثر","21 سنة أو أكثر"],"h1":"هو نفس السن القانونية لشرب الكحول.","h2":"في Iowa، يجب أن يكون فرد العائلة المباشر الذي يشرف على سائق يحمل تصريحًا حاملًا لرخصة قيادة وعمره 21 سنة على الأقل.","p":"صحيح. يجب أن يكون فرد العائلة 21 سنة أو أكثر."},"ref":{"doc":"IA","page":null}},{"id":"ia-013","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, a supervisor who is not family needs the parent's written permission. How old must that person be?","o":["18 or older","21 or older","25 or older","30 or older"],"h1":"It is older than for a family member.","h2":"In Iowa, a supervisor who is not family must be licensed, at least 25 years old and have written permission from the parent or guardian.","p":"Right. A non-family supervisor must be 25 or older."},"es":{"q":"En Iowa, un supervisor que no es familiar necesita permiso escrito del padre. ¿Qué edad debe tener esa persona?","o":["18 años o más","21 años o más","25 años o más","30 años o más"],"h1":"Es mayor que para un familiar.","h2":"En Iowa, un supervisor que no es familiar debe tener licencia, por lo menos 25 años y permiso escrito del padre o tutor.","p":"Correcto. Un supervisor que no es familiar debe tener 25 años o más."},"zh":{"q":"在 Iowa，不是家人的陪同者需要父母的书面许可。这个人必须几岁？","o":["18 岁或以上","21 岁或以上","25 岁或以上","30 岁或以上"],"h1":"比家人的年龄要求更大。","h2":"在 Iowa，不是家人的陪同者必须有驾照、至少 25 岁，并且有父母或监护人的书面许可。","p":"对。不是家人的陪同者必须 25 岁或以上。"},"vi":{"q":"Ở Iowa, người giám sát không phải người thân cần sự cho phép bằng văn bản của cha mẹ. Người đó phải bao nhiêu tuổi?","o":["18 tuổi trở lên","21 tuổi trở lên","25 tuổi trở lên","30 tuổi trở lên"],"h1":"Lớn tuổi hơn so với người thân trong gia đình.","h2":"Ở Iowa, người giám sát không phải người thân phải có bằng lái, ít nhất 25 tuổi và có sự cho phép bằng văn bản của cha mẹ hoặc người giám hộ.","p":"Đúng. Người giám sát không phải người thân phải từ 25 tuổi trở lên."},"tl":{"q":"Sa Iowa, ang gumagabay na hindi kapamilya ay kailangan ng nakasulat na pahintulot ng magulang. Ilang taon dapat ang taong iyon?","o":["18 o mas matanda","21 o mas matanda","25 o mas matanda","30 o mas matanda"],"h1":"Mas matanda ito kaysa sa kapamilya.","h2":"Sa Iowa, ang gumagabay na hindi kapamilya ay dapat may lisensya, hindi bababa sa 25 taong gulang, at may nakasulat na pahintulot ng magulang o tagapag-alaga.","p":"Tama. Dapat 25 o mas matanda ang gumagabay na hindi kapamilya."},"ar":{"q":"في Iowa، المشرف الذي ليس من العائلة يحتاج إلى إذن مكتوب من أحد الوالدين. كم يجب أن يكون عمر هذا الشخص؟","o":["18 سنة أو أكثر","21 سنة أو أكثر","25 سنة أو أكثر","30 سنة أو أكثر"],"h1":"هو أكبر من عمر فرد العائلة.","h2":"في Iowa، يجب أن يكون المشرف الذي ليس من العائلة حاملًا لرخصة قيادة، وعمره 25 سنة على الأقل، ومعه إذن مكتوب من أحد الوالدين أو الوصي.","p":"صحيح. يجب أن يكون المشرف من خارج العائلة 25 سنة أو أكثر."},"ref":{"doc":"IA","page":null}},{"id":"ia-014","scope":"IA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Iowa, what blood alcohol level is illegal for a driver under 21?","o":["0.08 or more","0.02 or more","0.05 or more","0.10 or more"],"h1":"It is much lower than the adult limit.","h2":"In Iowa a driver under 21 breaks the law with a blood alcohol level of 0.02 or more, and can lose their license.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Iowa, ¿qué nivel de alcohol en la sangre es ilegal para un conductor menor de 21 años?","o":["0.08 o más","0.02 o más","0.05 o más","0.10 o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Iowa un conductor menor de 21 años viola la ley con un nivel de alcohol en la sangre de 0.02 o más, y puede perder su licencia.","p":"Correcto. Para menores de 21, el límite es 0.02."},"zh":{"q":"在 Iowa，对 21 岁以下的司机来说，血液酒精浓度多少是违法的？","o":["0.08 或更高","0.02 或更高","0.05 或更高","0.10 或更高"],"h1":"这比成年人的上限低很多。","h2":"在 Iowa，21 岁以下的司机血液酒精浓度达到 0.02 或更高就是违法，而且可能会失去驾照。","p":"对。21 岁以下，上限是 0.02。"},"vi":{"q":"Ở Iowa, nồng độ cồn trong máu bao nhiêu là phạm luật đối với người lái xe dưới 21 tuổi?","o":["0.08 trở lên","0.02 trở lên","0.05 trở lên","0.10 trở lên"],"h1":"Thấp hơn nhiều so với giới hạn của người lớn.","h2":"Ở Iowa, người lái xe dưới 21 tuổi phạm luật khi nồng độ cồn trong máu từ 0.02 trở lên, và có thể bị mất bằng lái.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa Iowa, anong antas ng alak sa dugo ang ilegal para sa drayber na wala pang 21?","o":["0.08 o higit pa","0.02 o higit pa","0.05 o higit pa","0.10 o higit pa"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon para sa adulto.","h2":"Sa Iowa, lumalabag sa batas ang drayber na wala pang 21 kapag ang antas ng alak sa dugo ay 0.02 o higit pa, at maaari siyang mawalan ng lisensya.","p":"Tama. Kung wala pang 21, ang limitasyon ay 0.02."},"ar":{"q":"في Iowa، ما نسبة الكحول في الدم التي تُعد مخالفة للقانون لسائق عمره أقل من 21 سنة؟","o":["0.08 أو أكثر","0.02 أو أكثر","0.05 أو أكثر","0.10 أو أكثر"],"h1":"هي أقل بكثير من حد البالغين.","h2":"في Iowa، يخالف السائق الذي عمره أقل من 21 سنة القانون إذا كانت نسبة الكحول في دمه 0.02 أو أكثر، ويمكن أن يفقد رخصته.","p":"صحيح. لمن هم دون 21 سنة، الحد هو 0.02."},"ref":{"doc":"IA","page":37}},{"id":"ia-015","scope":"IA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Iowa, since July 1, 2025, how may an adult driver use a phone while driving?","o":["Any way, if driving slowly","Holding it, for calls only","Texting at red lights only","Only hands-free or by voice"],"h1":"The law is called the hands-free law.","h2":"Since July 1, 2025, Iowa drivers may not hold a phone while driving, and may use it only hands-free or by voice.","p":"Right. Hands-free only."},"es":{"q":"En Iowa, desde el 1 de julio de 2025, ¿cómo puede un conductor adulto usar el teléfono mientras maneja?","o":["De cualquier forma, si maneja despacio","Sosteniéndolo, solo para llamadas","Escribiendo mensajes solo en luz roja","Solo con manos libres o por voz"],"h1":"La ley se llama ley de manos libres.","h2":"Desde el 1 de julio de 2025, en Iowa los conductores no pueden sostener el teléfono mientras manejan, y solo pueden usarlo con manos libres o por voz.","p":"Correcto. Solo manos libres."},"zh":{"q":"在 Iowa，从 2025 年 7 月 1 日起，成年司机开车时可以怎样使用手机？","o":["怎样都可以，只要开得慢","可以手拿，但只能打电话","只能在红灯时发短信","只能用免提或语音"],"h1":"这个法律叫做免提法。","h2":"从 2025 年 7 月 1 日起，Iowa 的司机开车时不能手拿手机，只能用免提或语音来使用。","p":"对。只能用免提。"},"vi":{"q":"Ở Iowa, từ ngày 1 tháng 7 năm 2025, người lái xe trưởng thành được dùng điện thoại khi lái xe như thế nào?","o":["Bất kỳ cách nào, nếu lái chậm","Cầm trên tay, chỉ để gọi","Chỉ nhắn tin khi đèn đỏ","Chỉ rảnh tay hoặc bằng giọng nói"],"h1":"Luật này được gọi là luật rảnh tay (hands-free).","h2":"Từ ngày 1 tháng 7 năm 2025, người lái xe ở Iowa không được cầm điện thoại khi lái xe, và chỉ được dùng điện thoại ở chế độ rảnh tay hoặc bằng giọng nói.","p":"Đúng. Chỉ được rảnh tay."},"tl":{"q":"Sa Iowa, mula Hulyo 1, 2025, paano maaaring gumamit ng telepono ang adultong drayber habang nagmamaneho?","o":["Kahit paano, kung mabagal ang takbo","Hawak ito, para sa tawag lamang","Pag-text sa pulang ilaw lamang","Hands-free o gamit ang boses lamang"],"h1":"Tinatawag ang batas na hands-free law.","h2":"Mula Hulyo 1, 2025, hindi maaaring hawakan ng mga drayber sa Iowa ang telepono habang nagmamaneho, at maaari lamang itong gamitin nang hands-free o gamit ang boses.","p":"Tama. Hands-free lamang."},"ar":{"q":"في Iowa، منذ 1 يوليو 2025، كيف يمكن للسائق البالغ أن يستخدم الهاتف أثناء القيادة؟","o":["بأي طريقة، إذا كان يقود ببطء","يمسكه بيده، للمكالمات فقط","إرسال الرسائل عند الإشارة الحمراء فقط","بدون استخدام اليدين أو بالصوت فقط"],"h1":"يسمى هذا القانون قانون عدم استخدام اليدين (hands-free).","h2":"منذ 1 يوليو 2025، لا يجوز للسائقين في Iowa أن يمسكوا الهاتف أثناء القيادة، ويمكنهم استخدامه فقط بدون اليدين أو بالصوت.","p":"صحيح. بدون استخدام اليدين فقط."},"ref":{"doc":"IA","page":36}},{"id":"ia-016","scope":"IA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Iowa, may a teen with an intermediate license use a phone or tablet while driving?","o":["No, only equipment built into the vehicle is allowed","Yes, if it is hands-free","Yes, for music only","Yes, at red lights"],"h1":"Even hands-free devices are not allowed for this license.","h2":"An Iowa intermediate license holder may not use a phone, tablet or other electronic device while driving; only equipment permanently installed in the vehicle is allowed.","p":"Right. No phones or tablets for teen drivers."},"es":{"q":"En Iowa, ¿puede un adolescente con licencia intermedia usar un teléfono o tableta mientras maneja?","o":["No, solo el equipo instalado en el vehículo","Sí, si es manos libres","Sí, solo para música","Sí, en luz roja"],"h1":"Ni siquiera los aparatos de manos libres están permitidos con esta licencia.","h2":"Quien tiene licencia intermedia en Iowa no puede usar teléfono, tableta ni otro aparato electrónico mientras maneja; solo se permite el equipo instalado de forma permanente en el vehículo.","p":"Correcto. Nada de teléfonos ni tabletas para conductores adolescentes."},"zh":{"q":"在 Iowa，持中级驾照的青少年开车时可以用手机或平板电脑吗？","o":["不可以，只能用车上自带的设备","可以，只要是免提","可以，但只能听音乐","可以，在红灯时"],"h1":"持这种驾照，连免提设备也不允许。","h2":"在 Iowa，持中级驾照的人开车时不能用手机、平板电脑或其他电子设备，只能用固定安装在车上的设备。","p":"对。青少年司机不能用手机或平板电脑。"},"vi":{"q":"Ở Iowa, thiếu niên có bằng lái trung gian (intermediate license) có được dùng điện thoại hoặc máy tính bảng khi lái xe không?","o":["Không, chỉ được dùng thiết bị gắn sẵn trong xe","Có, nếu rảnh tay","Có, chỉ để nghe nhạc","Có, khi đèn đỏ"],"h1":"Ngay cả thiết bị rảnh tay cũng không được phép với loại bằng lái này.","h2":"Ở Iowa, người có bằng lái trung gian không được dùng điện thoại, máy tính bảng hay thiết bị điện tử khác khi lái xe; chỉ được dùng thiết bị gắn cố định trong xe.","p":"Đúng. Người lái xe tuổi thiếu niên không được dùng điện thoại hay máy tính bảng."},"tl":{"q":"Sa Iowa, maaari bang gumamit ng telepono o tablet habang nagmamaneho ang kabataang may intermediate license?","o":["Hindi, kagamitang nakakabit sa sasakyan lamang ang pinapayagan","Oo, kung hands-free","Oo, para sa musika lamang","Oo, sa pulang ilaw"],"h1":"Kahit ang mga hands-free na device ay hindi pinapayagan para sa lisensyang ito.","h2":"Ang may intermediate license sa Iowa ay hindi maaaring gumamit ng telepono, tablet o ibang electronic device habang nagmamaneho; kagamitang permanenteng nakakabit sa sasakyan lamang ang pinapayagan.","p":"Tama. Walang telepono o tablet para sa mga kabataang drayber."},"ar":{"q":"في Iowa، هل يجوز للمراهق الذي يحمل الرخصة المتوسطة (intermediate license) أن يستخدم هاتفًا أو جهازًا لوحيًا أثناء القيادة؟","o":["لا، يُسمح فقط بالأجهزة المركّبة في السيارة","نعم، إذا كان بدون استخدام اليدين","نعم، للموسيقى فقط","نعم، عند الإشارة الحمراء"],"h1":"حتى الأجهزة التي تعمل بدون اليدين غير مسموح بها مع هذه الرخصة.","h2":"لا يجوز لحامل الرخصة المتوسطة في Iowa أن يستخدم هاتفًا أو جهازًا لوحيًا أو أي جهاز إلكتروني آخر أثناء القيادة؛ يُسمح فقط بالأجهزة المركّبة بشكل دائم في السيارة.","p":"صحيح. لا هواتف ولا أجهزة لوحية للسائقين المراهقين."},"ref":{"doc":"IA","page":36}},{"id":"ia-017","scope":"IA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Iowa, what must you do when you approach any stopped vehicle on the roadside with its hazard lights on?","o":["Honk and keep your speed","Stop behind it","Change lanes or slow down","Nothing; the law covers only police cars"],"h1":"Iowa's law is named for these two actions.","h2":"In Iowa you must change lanes or slow down when you approach any stopped vehicle with its hazard lights flashing, not only emergency vehicles.","p":"Right. Move over or slow down."},"es":{"q":"En Iowa, ¿qué debe hacer al acercarse a cualquier vehículo detenido al lado del camino con las luces intermitentes de emergencia encendidas?","o":["Tocar la bocina y seguir a la misma velocidad","Detenerse detrás de él","Cambiar de carril o reducir la velocidad","Nada; la ley solo aplica a patrullas"],"h1":"La ley de Iowa lleva el nombre de estas dos acciones.","h2":"En Iowa usted debe cambiar de carril o reducir la velocidad al acercarse a cualquier vehículo detenido con las luces intermitentes encendidas, no solo a vehículos de emergencia.","p":"Correcto. Cambiar de carril o bajar la velocidad."},"zh":{"q":"在 Iowa，当你靠近任何一辆停在路边、开着双闪灯的车辆时，你必须做什么？","o":["按喇叭并保持速度","停在它后面","换道或减速","什么都不用做，法律只保护警车"],"h1":"Iowa 的这条法律就是用这两个动作命名的。","h2":"在 Iowa，当你靠近任何一辆停着、闪着双闪灯的车辆时，你必须换道或减速，不只是遇到急救车辆时才这样。","p":"对。换道让开或减速。"},"vi":{"q":"Ở Iowa, bạn phải làm gì khi đến gần bất kỳ xe nào đang dừng bên đường và bật đèn khẩn cấp?","o":["Bấm còi và giữ tốc độ","Dừng lại phía sau xe đó","Đổi làn hoặc chạy chậm lại","Không làm gì; luật chỉ áp dụng cho xe cảnh sát"],"h1":"Luật của Iowa được đặt tên theo hai hành động này.","h2":"Ở Iowa, bạn phải đổi làn hoặc chạy chậm lại khi đến gần bất kỳ xe nào đang dừng và nhấp nháy đèn khẩn cấp, không chỉ xe cấp cứu.","p":"Đúng. Tránh sang làn khác hoặc chạy chậm lại."},"tl":{"q":"Sa Iowa, ano ang dapat mong gawin kapag papalapit ka sa anumang nakahintong sasakyan sa gilid ng daan na nakabukas ang hazard lights?","o":["Bumusina at panatilihin ang bilis","Huminto sa likod nito","Lumipat ng lane o magdahan-dahan","Wala; para lamang sa sasakyan ng pulis ang batas"],"h1":"Ipinangalan ang batas ng Iowa sa dalawang aksyong ito.","h2":"Sa Iowa, dapat kang lumipat ng lane o magdahan-dahan kapag papalapit ka sa anumang nakahintong sasakyan na kumikislap ang hazard lights, hindi lamang sa mga emergency vehicle.","p":"Tama. Lumipat ng lane o magdahan-dahan."},"ar":{"q":"في Iowa، ماذا يجب أن تفعل عندما تقترب من أي سيارة متوقفة على جانب الطريق وأضواء التحذير فيها مشتعلة؟","o":["استخدم البوق وحافظ على سرعتك","توقف خلفها","غيّر المسار أو خفّف السرعة","لا شيء؛ القانون يشمل سيارات الشرطة فقط"],"h1":"قانون Iowa مسمّى باسم هذين الفعلين.","h2":"في Iowa يجب أن تغيّر المسار أو تخفّف السرعة عندما تقترب من أي سيارة متوقفة وأضواء التحذير فيها تومض، وليس فقط سيارات الطوارئ.","p":"صحيح. ابتعد إلى مسار آخر أو خفّف السرعة."},"ref":{"doc":"IA","page":22}},{"id":"ia-018","scope":"IA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Iowa, a school bus stops with its stop arm out on a road with two or more lanes in each direction. You come from the opposite direction. What must you do?","o":["Stop until the arm is pulled in","You do not have to stop, but watch for children","Stop only if children are crossing","Stop and wait for the driver's signal"],"h1":"The road is wide enough to separate the two directions.","h2":"On an Iowa road with two or more lanes in each direction, traffic coming from the opposite direction does not have to stop for a school bus, but should still watch for children.","p":"Right. Oncoming traffic on a wide road may pass with care."},"es":{"q":"En Iowa, un autobús escolar se detiene con el brazo de alto extendido en un camino con dos o más carriles en cada sentido. Usted viene en sentido contrario. ¿Qué debe hacer?","o":["Detenerse hasta que recojan el brazo","No tiene que detenerse, pero esté atento a los niños","Detenerse solo si hay niños cruzando","Detenerse y esperar la señal del chofer"],"h1":"El camino es lo bastante ancho para separar los dos sentidos.","h2":"En un camino de Iowa con dos o más carriles en cada sentido, el tráfico que viene en sentido contrario no tiene que detenerse por un autobús escolar, pero debe estar atento a los niños.","p":"Correcto. En un camino ancho, el tráfico contrario puede pasar con cuidado."},"zh":{"q":"在 Iowa，一辆校车在每个方向有两条或更多车道的路上停下，伸出了停车臂。你从对面方向开过来。你必须做什么？","o":["停车，直到停车臂收回","你不用停车，但要注意小孩","只有在小孩过马路时才停车","停车并等司机的手势"],"h1":"这条路够宽，可以把两个方向分开。","h2":"在 Iowa 每个方向有两条或更多车道的路上，从对面方向来的车不用为校车停车，但仍然要注意小孩。","p":"对。在宽的路上，对面来的车可以小心地开过去。"},"vi":{"q":"Ở Iowa, một xe buýt trường học dừng lại và giơ tay báo dừng (stop arm) trên đường có hai làn trở lên mỗi chiều. Bạn đi từ chiều ngược lại. Bạn phải làm gì?","o":["Dừng lại cho đến khi tay báo dừng thu vào","Bạn không phải dừng, nhưng hãy để ý trẻ em","Chỉ dừng nếu trẻ em đang băng qua đường","Dừng lại và chờ tài xế ra hiệu"],"h1":"Con đường đủ rộng để tách hai chiều xe.","h2":"Trên đường ở Iowa có hai làn trở lên mỗi chiều, xe đi từ chiều ngược lại không phải dừng cho xe buýt trường học, nhưng vẫn phải để ý trẻ em.","p":"Đúng. Xe chiều ngược lại trên đường rộng có thể đi qua cẩn thận."},"tl":{"q":"Sa Iowa, huminto ang isang school bus na nakalabas ang stop arm sa daang may dalawa o higit pang lane sa bawat direksyon. Galing ka sa kabilang direksyon. Ano ang dapat mong gawin?","o":["Huminto hanggang maibalik ang stop arm","Hindi mo kailangang huminto, pero mag-ingat sa mga bata","Huminto lamang kung may mga batang tumatawid","Huminto at hintayin ang senyas ng drayber"],"h1":"Sapat ang lapad ng daan para paghiwalayin ang dalawang direksyon.","h2":"Sa daan sa Iowa na may dalawa o higit pang lane sa bawat direksyon, ang trapikong galing sa kabilang direksyon ay hindi kailangang huminto para sa school bus, pero dapat pa ring mag-ingat sa mga bata.","p":"Tama. Ang trapiko mula sa kabilang direksyon sa malapad na daan ay maaaring dumaan nang maingat."},"ar":{"q":"في Iowa، توقفت حافلة مدرسية وذراع التوقف (stop arm) ممدودة على طريق فيه مساران أو أكثر في كل اتجاه. أنت قادم من الاتجاه المعاكس. ماذا يجب أن تفعل؟","o":["توقف حتى تُسحب الذراع","ليس عليك أن تتوقف، لكن انتبه للأطفال","توقف فقط إذا كان الأطفال يعبرون","توقف وانتظر إشارة السائق"],"h1":"الطريق واسع بما يكفي ليفصل بين الاتجاهين.","h2":"على طريق في Iowa فيه مساران أو أكثر في كل اتجاه، ليس على السيارات القادمة من الاتجاه المعاكس أن تتوقف للحافلة المدرسية، لكن يجب أن تنتبه للأطفال.","p":"صحيح. السيارات القادمة من الاتجاه المعاكس على طريق واسع يمكنها المرور بحذر."},"ref":{"doc":"IA","page":20}},{"id":"ia-019","scope":"IA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Iowa, on a road with three lanes or fewer, who must stop for a school bus with flashing red lights?","o":["Only drivers behind the bus","Only drivers facing the bus","Only drivers in the turning lane","Every vehicle, from both directions"],"h1":"On a narrow road, nobody gets past.","h2":"On an Iowa road with three lanes or fewer, every vehicle from both directions, including turning lanes, must stop for a school bus with flashing red lights.","p":"Right. Everyone stops on a narrow road."},"es":{"q":"En Iowa, en un camino de tres carriles o menos, ¿quién debe detenerse ante un autobús escolar con luces rojas intermitentes?","o":["Solo los conductores detrás del autobús","Solo los conductores de frente al autobús","Solo los conductores en el carril de giro","Todos los vehículos, de los dos sentidos"],"h1":"En un camino angosto, nadie pasa.","h2":"En un camino de Iowa de tres carriles o menos, todos los vehículos de los dos sentidos, incluso los del carril de giro, deben detenerse ante un autobús escolar con luces rojas intermitentes.","p":"Correcto. En un camino angosto todos se detienen."},"zh":{"q":"在 Iowa，在三条车道或更少的路上，谁必须为闪着红灯的校车停车？","o":["只有校车后面的司机","只有面对校车的司机","只有转弯车道上的司机","两个方向的所有车辆"],"h1":"在窄的路上，谁都不能开过去。","h2":"在 Iowa 三条车道或更少的路上，两个方向的所有车辆，包括转弯车道上的车，都必须为闪着红灯的校车停车。","p":"对。在窄的路上，所有人都要停。"},"vi":{"q":"Ở Iowa, trên đường có ba làn trở xuống, ai phải dừng lại cho xe buýt trường học đang nhấp nháy đèn đỏ?","o":["Chỉ xe ở phía sau xe buýt","Chỉ xe đối diện xe buýt","Chỉ xe ở làn rẽ","Mọi xe, từ cả hai chiều"],"h1":"Trên đường hẹp, không ai được đi qua.","h2":"Trên đường ở Iowa có ba làn trở xuống, mọi xe từ cả hai chiều, kể cả làn rẽ, phải dừng lại cho xe buýt trường học đang nhấp nháy đèn đỏ.","p":"Đúng. Trên đường hẹp, mọi người đều dừng."},"tl":{"q":"Sa Iowa, sa daang may tatlong lane o mas kaunti, sino ang dapat huminto para sa school bus na kumikislap ang pulang ilaw?","o":["Mga drayber lamang sa likod ng bus","Mga drayber lamang na nakaharap sa bus","Mga drayber lamang sa turning lane","Bawat sasakyan, mula sa dalawang direksyon"],"h1":"Sa makitid na daan, walang makakalampas.","h2":"Sa daan sa Iowa na may tatlong lane o mas kaunti, bawat sasakyan mula sa dalawang direksyon, kasama ang mga turning lane, ay dapat huminto para sa school bus na kumikislap ang pulang ilaw.","p":"Tama. Lahat ay humihinto sa makitid na daan."},"ar":{"q":"في Iowa، على طريق فيه ثلاثة مسارات أو أقل، من يجب أن يتوقف لحافلة مدرسية أضواؤها الحمراء تومض؟","o":["السائقون خلف الحافلة فقط","السائقون المقابلون للحافلة فقط","السائقون في مسار الانعطاف فقط","كل السيارات، من الاتجاهين"],"h1":"على الطريق الضيق، لا أحد يمر.","h2":"على طريق في Iowa فيه ثلاثة مسارات أو أقل، يجب على كل السيارات من الاتجاهين، بما فيها مسارات الانعطاف، أن تتوقف لحافلة مدرسية أضواؤها الحمراء تومض.","p":"صحيح. الجميع يتوقف على الطريق الضيق."},"ref":{"doc":"IA","page":20}},{"id":"ia-020","scope":"IA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Iowa, failing to stop for a school bus when required can cost you your license for up to how long?","o":["180 days","7 days","30 days","5 years"],"h1":"It is about half a year.","h2":"In Iowa, not stopping for a school bus when the law requires it can lead to a license suspension of up to 180 days.","p":"Right. Up to 180 days."},"es":{"q":"En Iowa, ¿hasta por cuánto tiempo le pueden suspender la licencia por no detenerse ante un autobús escolar cuando la ley lo exige?","o":["180 días","7 días","30 días","5 años"],"h1":"Es más o menos medio año.","h2":"En Iowa, no detenerse ante un autobús escolar cuando la ley lo exige puede causar una suspensión de la licencia de hasta 180 días.","p":"Correcto. Hasta 180 días."},"zh":{"q":"在 Iowa，按规定应该为校车停车却没有停，最长可能会被暂停驾照多久？","o":["180 天","7 天","30 天","5 年"],"h1":"大约是半年。","h2":"在 Iowa，法律要求停车时没有为校车停车，驾照最长可能被暂停 180 天。","p":"对。最长 180 天。"},"vi":{"q":"Ở Iowa, không dừng lại cho xe buýt trường học khi luật yêu cầu có thể khiến bạn mất bằng lái tối đa bao lâu?","o":["180 ngày","7 ngày","30 ngày","5 năm"],"h1":"Khoảng nửa năm.","h2":"Ở Iowa, không dừng lại cho xe buýt trường học khi luật yêu cầu có thể bị treo bằng lái tối đa 180 ngày.","p":"Đúng. Tối đa 180 ngày."},"tl":{"q":"Sa Iowa, ang hindi paghinto para sa school bus kapag kinakailangan ay maaaring magdulot ng pagkawala ng lisensya mo nang hanggang gaano katagal?","o":["180 araw","7 araw","30 araw","5 taon"],"h1":"Mga kalahating taon ito.","h2":"Sa Iowa, ang hindi paghinto para sa school bus kapag hinihingi ng batas ay maaaring magresulta sa suspensyon ng lisensya nang hanggang 180 araw.","p":"Tama. Hanggang 180 araw."},"ar":{"q":"في Iowa، عدم التوقف لحافلة مدرسية عندما يجب ذلك يمكن أن يُفقدك رخصتك لمدة تصل إلى كم؟","o":["180 يومًا","7 أيام","30 يومًا","5 سنوات"],"h1":"هي حوالي نصف سنة.","h2":"في Iowa، عدم التوقف لحافلة مدرسية عندما يطلب القانون ذلك يمكن أن يؤدي إلى إيقاف الرخصة لمدة تصل إلى 180 يومًا.","p":"صحيح. حتى 180 يومًا."},"ref":{"doc":"IA","page":20}},{"id":"ia-021","scope":"IA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Iowa, what is the highest posted speed limit on rural interstate highways?","o":["60 mph","65 mph","70 mph","75 mph"],"h1":"Iowa's rural interstates are lower than some western states.","h2":"The highest posted speed limit in Iowa is 70 mph, on rural interstate highways.","p":"Right. 70 mph on rural interstates."},"es":{"q":"En Iowa, ¿cuál es el límite de velocidad más alto en las autopistas interestatales rurales?","o":["60 mph","65 mph","70 mph","75 mph"],"h1":"Las interestatales rurales de Iowa tienen un límite más bajo que algunos estados del oeste.","h2":"El límite de velocidad más alto en Iowa es de 70 millas por hora, en las autopistas interestatales rurales.","p":"Correcto. 70 mph en interestatales rurales."},"zh":{"q":"在 Iowa，乡村州际高速公路上标示的最高限速是多少？","o":["60 mph","65 mph","70 mph","75 mph"],"h1":"Iowa 乡村州际公路的限速比一些西部州低。","h2":"Iowa 标示的最高限速是 70 mph，在乡村州际高速公路上。","p":"对。乡村州际公路是 70 mph。"},"vi":{"q":"Ở Iowa, tốc độ tối đa cao nhất được ghi trên biển ở xa lộ liên tiểu bang vùng nông thôn là bao nhiêu?","o":["60 mph","65 mph","70 mph","75 mph"],"h1":"Xa lộ liên tiểu bang vùng nông thôn ở Iowa có tốc độ thấp hơn một số tiểu bang miền tây.","h2":"Tốc độ tối đa cao nhất được ghi trên biển ở Iowa là 70 mph, trên xa lộ liên tiểu bang vùng nông thôn.","p":"Đúng. 70 mph trên xa lộ liên tiểu bang vùng nông thôn."},"tl":{"q":"Sa Iowa, ano ang pinakamataas na nakapaskil na speed limit sa mga rural interstate highway?","o":["60 mph","65 mph","70 mph","75 mph"],"h1":"Mas mababa ang mga rural interstate ng Iowa kaysa sa ilang estado sa kanluran.","h2":"Ang pinakamataas na nakapaskil na speed limit sa Iowa ay 70 mph, sa mga rural interstate highway.","p":"Tama. 70 mph sa mga rural interstate."},"ar":{"q":"في Iowa، ما أعلى حد سرعة مكتوب على اللافتات على الطرق السريعة بين الولايات في المناطق الريفية؟","o":["60 mph","65 mph","70 mph","75 mph"],"h1":"الطرق السريعة الريفية في Iowa أقل من بعض الولايات الغربية.","h2":"أعلى حد سرعة مكتوب على اللافتات في Iowa هو 70 mph، على الطرق السريعة بين الولايات في المناطق الريفية.","p":"صحيح. 70 mph على الطرق السريعة الريفية."},"ref":{"doc":"IA","page":42}},{"id":"ia-022","scope":"IA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Iowa, unless a sign says otherwise, what is the speed limit in a business district?","o":["15 mph","20 mph","30 mph","35 mph"],"h1":"Business districts are busy with people on foot.","h2":"Unless a sign shows a different limit, the speed limit in an Iowa business district is 20 mph.","p":"Right. 20 mph in a business district."},"es":{"q":"En Iowa, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad en una zona comercial?","o":["15 mph","20 mph","30 mph","35 mph"],"h1":"Las zonas comerciales tienen mucha gente a pie.","h2":"Si no hay una señal con otro límite, el límite de velocidad en una zona comercial de Iowa es de 20 millas por hora.","p":"Correcto. 20 mph en zona comercial."},"zh":{"q":"在 Iowa，如果没有标志另外说明，商业区的限速是多少？","o":["15 mph","20 mph","30 mph","35 mph"],"h1":"商业区有很多走路的人。","h2":"在 Iowa，如果没有标志标示不同的限速，商业区的限速是 20 mph。","p":"对。商业区是 20 mph。"},"vi":{"q":"Ở Iowa, nếu không có biển báo khác, tốc độ tối đa trong khu thương mại là bao nhiêu?","o":["15 mph","20 mph","30 mph","35 mph"],"h1":"Khu thương mại có nhiều người đi bộ.","h2":"Nếu không có biển báo ghi tốc độ khác, tốc độ tối đa trong khu thương mại ở Iowa là 20 mph.","p":"Đúng. 20 mph trong khu thương mại."},"tl":{"q":"Sa Iowa, maliban kung iba ang sinasabi ng karatula, ano ang speed limit sa business district?","o":["15 mph","20 mph","30 mph","35 mph"],"h1":"Maraming taong naglalakad sa mga business district.","h2":"Maliban kung iba ang limitasyong ipinapakita ng karatula, ang speed limit sa business district sa Iowa ay 20 mph.","p":"Tama. 20 mph sa business district."},"ar":{"q":"في Iowa، ما لم تقل لافتة غير ذلك، ما حد السرعة في المنطقة التجارية؟","o":["15 mph","20 mph","30 mph","35 mph"],"h1":"المناطق التجارية مزدحمة بالمشاة.","h2":"ما لم تُظهر لافتة حدًا مختلفًا، فإن حد السرعة في المنطقة التجارية في Iowa هو 20 mph.","p":"صحيح. 20 mph في المنطقة التجارية."},"ref":{"doc":"IA","page":42}},{"id":"ia-023","scope":"IA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Iowa, how must a child under 6 years old ride in a car?","o":["With an adult seat belt only","On an adult's lap","In a child safety seat or booster seat","In the front seat with a seat belt"],"h1":"A seat belt alone is not enough for a child this young.","h2":"In Iowa a child under 6 years old must ride in a child safety seat or a booster seat, not just a seat belt.","p":"Right. Under 6, a safety seat or booster seat."},"es":{"q":"En Iowa, ¿cómo debe viajar en un auto un niño menor de 6 años?","o":["Solo con el cinturón de seguridad de adulto","En las piernas de un adulto","En un asiento de seguridad infantil o un asiento elevado","En el asiento delantero con cinturón"],"h1":"Para un niño tan pequeño, el cinturón solo no es suficiente.","h2":"En Iowa un niño menor de 6 años debe viajar en un asiento de seguridad infantil o en un asiento elevado, no solo con el cinturón de seguridad.","p":"Correcto. Menores de 6, asiento de seguridad o asiento elevado."},"zh":{"q":"在 Iowa，6 岁以下的儿童坐车时必须怎样乘坐？","o":["只系成人安全带","坐在大人腿上","坐在儿童安全座椅或增高座椅里","坐在前排并系安全带"],"h1":"对这么小的孩子来说，只系安全带是不够的。","h2":"在 Iowa，6 岁以下的儿童必须坐在儿童安全座椅或增高座椅里，不能只系安全带。","p":"对。6 岁以下要用安全座椅或增高座椅。"},"vi":{"q":"Ở Iowa, trẻ em dưới 6 tuổi phải ngồi trên xe như thế nào?","o":["Chỉ thắt dây an toàn của người lớn","Ngồi trên đùi người lớn","Ngồi trong ghế an toàn cho trẻ em hoặc ghế nâng","Ngồi ghế trước và thắt dây an toàn"],"h1":"Chỉ thắt dây an toàn thì không đủ cho trẻ nhỏ như vậy.","h2":"Ở Iowa, trẻ em dưới 6 tuổi phải ngồi trong ghế an toàn cho trẻ em hoặc ghế nâng, không chỉ thắt dây an toàn.","p":"Đúng. Dưới 6 tuổi phải ngồi ghế an toàn hoặc ghế nâng."},"tl":{"q":"Sa Iowa, paano dapat sumakay sa kotse ang batang wala pang 6 na taong gulang?","o":["Naka-seat belt na pang-adulto lamang","Nakakandong sa isang adulto","Nasa child safety seat o booster seat","Nasa upuan sa harap na naka-seat belt"],"h1":"Hindi sapat ang seat belt lamang para sa ganito kabatang bata.","h2":"Sa Iowa, ang batang wala pang 6 na taong gulang ay dapat nakasakay sa child safety seat o booster seat, hindi lang naka-seat belt.","p":"Tama. Kapag wala pang 6, safety seat o booster seat."},"ar":{"q":"في ولاية Iowa، كيف يجب أن يركب الطفل الذي عمره أقل من 6 سنوات في السيارة؟","o":["بحزام أمان الكبار فقط","في حضن شخص بالغ","في مقعد أمان للأطفال أو مقعد رافع","في المقعد الأمامي مع حزام الأمان"],"h1":"حزام الأمان وحده لا يكفي لطفل بهذا العمر الصغير.","h2":"في Iowa يجب أن يركب الطفل الذي عمره أقل من 6 سنوات في مقعد أمان للأطفال أو مقعد رافع، وليس بحزام الأمان فقط.","p":"صحيح. أقل من 6 سنوات: مقعد أمان أو مقعد رافع."},"ref":{"doc":"IA","page":35}},{"id":"ia-024","scope":"IA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Iowa, what happens if you refuse a breath test when a police officer asks?","o":["Your license is revoked for one year and you pay at least $1,250","Nothing, if you were not drinking","You get a warning the first time","Your license is suspended for one week"],"h1":"Refusing is treated more harshly than failing the test.","h2":"In Iowa, refusing a breath test means your license is revoked for one year and you must pay a fine of at least $1,250.","p":"Right. One year without a license and a fine of at least $1,250."},"es":{"q":"En Iowa, ¿qué pasa si usted se niega a una prueba de aliento cuando un policía se la pide?","o":["Le revocan la licencia por un año y paga al menos $1,250","Nada, si usted no había bebido","Recibe una advertencia la primera vez","Le suspenden la licencia por una semana"],"h1":"Negarse se castiga más fuerte que no pasar la prueba.","h2":"En Iowa, negarse a una prueba de aliento significa que le revocan la licencia por un año y debe pagar una multa de al menos $1,250.","p":"Correcto. Un año sin licencia y una multa de al menos $1,250."},"zh":{"q":"在 Iowa，如果警察要求你做呼气测试而你拒绝，会怎样？","o":["你的驾照被吊销一年，并且至少要付 $1,250","如果你没喝酒，就没事","第一次只会得到警告","你的驾照被暂停一周"],"h1":"拒绝测试的处罚比测试没通过还要重。","h2":"在 Iowa，拒绝做呼气测试，你的驾照会被吊销一年，并且至少要付 $1,250 的罚款。","p":"对。一年不能有驾照，罚款至少 $1,250。"},"vi":{"q":"Ở Iowa, điều gì xảy ra nếu bạn từ chối kiểm tra hơi thở khi cảnh sát yêu cầu?","o":["Bằng lái của bạn bị thu hồi một năm và bạn trả ít nhất $1,250","Không sao cả, nếu bạn không uống rượu","Lần đầu bạn chỉ bị cảnh cáo","Bằng lái của bạn bị đình chỉ một tuần"],"h1":"Từ chối bị xử phạt nặng hơn là không đạt bài kiểm tra.","h2":"Ở Iowa, từ chối kiểm tra hơi thở nghĩa là bằng lái của bạn bị thu hồi một năm và bạn phải trả tiền phạt ít nhất $1,250.","p":"Đúng. Một năm không có bằng lái và tiền phạt ít nhất $1,250."},"tl":{"q":"Sa Iowa, ano ang mangyayari kung tumanggi ka sa breath test kapag hiniling ng pulis?","o":["Babawiin ang iyong lisensya nang isang taon at magbabayad ka ng hindi bababa sa $1,250","Wala, kung hindi ka uminom","Babala lang sa unang pagkakataon","Masususpinde ang iyong lisensya nang isang linggo"],"h1":"Mas mabigat ang parusa sa pagtanggi kaysa sa pagbagsak sa test.","h2":"Sa Iowa, kapag tumanggi ka sa breath test, babawiin ang iyong lisensya nang isang taon at magbabayad ka ng multa na hindi bababa sa $1,250.","p":"Tama. Isang taon na walang lisensya at multa na hindi bababa sa $1,250."},"ar":{"q":"في ولاية Iowa، ماذا يحدث إذا رفضت اختبار التنفس عندما يطلبه منك ضابط الشرطة؟","o":["تُلغى رخصتك لمدة سنة وتدفع $1,250 على الأقل","لا شيء، إذا لم تكن قد شربت","تحصل على إنذار في المرة الأولى","تُعلَّق رخصتك لمدة أسبوع"],"h1":"الرفض يُعاقَب عليه أشد من الرسوب في الاختبار.","h2":"في Iowa، رفض اختبار التنفس يعني أن رخصتك تُلغى لمدة سنة ويجب أن تدفع غرامة لا تقل عن $1,250.","p":"صحيح. سنة بلا رخصة وغرامة لا تقل عن $1,250."},"ref":{"doc":"IA","page":37}},{"id":"ia-025","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, a crash causes injury or more than $1,500 in damage. How soon must it be reported to the police?","o":["Within 30 days","Within 10 days","Only if your insurance asks","Within 72 hours"],"h1":"The deadline is counted in hours, not days.","h2":"In Iowa a crash with injury, death or more than $1,500 in property damage must be reported to the police within 72 hours, or you can lose your license.","p":"Right. Report it within 72 hours."},"es":{"q":"En Iowa, un choque causa heridos o más de $1,500 en daños. ¿En cuánto tiempo hay que reportarlo a la policía?","o":["En 30 días","En 10 días","Solo si su seguro lo pide","En 72 horas"],"h1":"El plazo se cuenta en horas, no en días.","h2":"En Iowa un choque con heridos, muertos o más de $1,500 en daños a la propiedad se debe reportar a la policía en 72 horas, o usted puede perder su licencia.","p":"Correcto. Hay que reportarlo en 72 horas."},"zh":{"q":"在 Iowa，一起车祸造成了人员受伤或超过 $1,500 的损失。必须在多长时间内向警察报告？","o":["30 天内","10 天内","只有保险公司要求时才报告","72 小时内"],"h1":"期限是按小时算的，不是按天算。","h2":"在 Iowa，造成受伤、死亡或超过 $1,500 财产损失的车祸，必须在 72 小时内向警察报告，否则你可能失去驾照。","p":"对。要在 72 小时内报告。"},"vi":{"q":"Ở Iowa, một vụ tai nạn gây thương tích hoặc thiệt hại hơn $1,500. Phải báo cho cảnh sát trong bao lâu?","o":["Trong vòng 30 ngày","Trong vòng 10 ngày","Chỉ khi công ty bảo hiểm yêu cầu","Trong vòng 72 giờ"],"h1":"Thời hạn được tính bằng giờ, không phải bằng ngày.","h2":"Ở Iowa, tai nạn gây thương tích, tử vong hoặc thiệt hại tài sản hơn $1,500 phải được báo cho cảnh sát trong vòng 72 giờ, nếu không bạn có thể bị mất bằng lái.","p":"Đúng. Báo cáo trong vòng 72 giờ."},"tl":{"q":"Sa Iowa, may banggaan na nagdulot ng pinsala sa tao o higit sa $1,500 na sira. Gaano kabilis ito dapat i-report sa pulis?","o":["Sa loob ng 30 araw","Sa loob ng 10 araw","Kung hihilingin lang ng iyong insurance","Sa loob ng 72 oras"],"h1":"Binibilang ang deadline sa oras, hindi sa araw.","h2":"Sa Iowa, ang banggaan na may nasaktan, namatay o higit sa $1,500 na sira sa ari-arian ay dapat i-report sa pulis sa loob ng 72 oras, o maaaring mawala ang iyong lisensya.","p":"Tama. I-report ito sa loob ng 72 oras."},"ar":{"q":"في ولاية Iowa، تسبب حادث في إصابة أو في أضرار تزيد على $1,500. خلال كم من الوقت يجب إبلاغ الشرطة عنه؟","o":["خلال 30 يومًا","خلال 10 أيام","فقط إذا طلبت شركة التأمين","خلال 72 ساعة"],"h1":"المهلة تُحسب بالساعات، لا بالأيام.","h2":"في Iowa يجب إبلاغ الشرطة عن أي حادث فيه إصابة أو وفاة أو أضرار في الممتلكات تزيد على $1,500 خلال 72 ساعة، وإلا قد تفقد رخصتك.","p":"صحيح. أبلغ عنه خلال 72 ساعة."},"ref":{"doc":"IA","page":63}},{"id":"ia-026","scope":"IA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Iowa, what is the minimum speed on the interstate system?","o":["30 mph","40 mph","50 mph","55 mph"],"h1":"Vehicles that cannot keep up with this speed are not allowed on the interstate.","h2":"On Iowa's interstate system the minimum speed is 40 mph, and vehicles that cannot go that fast are not allowed there.","p":"Right. The interstate minimum is 40 mph."},"es":{"q":"En Iowa, ¿cuál es la velocidad mínima en las autopistas interestatales?","o":["30 mph","40 mph","50 mph","55 mph"],"h1":"Los vehículos que no pueden mantener esta velocidad no pueden usar la interestatal.","h2":"En las autopistas interestatales de Iowa la velocidad mínima es de 40 millas por hora, y los vehículos que no pueden ir así de rápido no pueden usarlas.","p":"Correcto. La mínima en la interestatal es 40 mph."},"zh":{"q":"在 Iowa，州际公路系统上的最低速度是多少？","o":["30 mph","40 mph","50 mph","55 mph"],"h1":"达不到这个速度的车辆不准上州际公路。","h2":"在 Iowa 的州际公路系统上，最低速度是 40 mph，开不到这么快的车辆不准在那里行驶。","p":"对。州际公路最低速度是 40 mph。"},"vi":{"q":"Ở Iowa, tốc độ tối thiểu trên hệ thống xa lộ liên bang (interstate) là bao nhiêu?","o":["30 mph","40 mph","50 mph","55 mph"],"h1":"Xe không chạy kịp tốc độ này thì không được đi trên xa lộ liên bang.","h2":"Trên hệ thống xa lộ liên bang ở Iowa, tốc độ tối thiểu là 40 mph, và xe không thể chạy nhanh như vậy thì không được đi ở đó.","p":"Đúng. Tốc độ tối thiểu trên xa lộ liên bang là 40 mph."},"tl":{"q":"Sa Iowa, ano ang pinakamababang bilis sa interstate system?","o":["30 mph","40 mph","50 mph","55 mph"],"h1":"Hindi pinapayagan sa interstate ang mga sasakyang hindi makaabot sa bilis na ito.","h2":"Sa interstate system ng Iowa, ang pinakamababang bilis ay 40 mph, at hindi pinapayagan doon ang mga sasakyang hindi makatakbo nang ganoon kabilis.","p":"Tama. Ang pinakamababang bilis sa interstate ay 40 mph."},"ar":{"q":"في ولاية Iowa، ما الحد الأدنى للسرعة على شبكة الطرق السريعة بين الولايات (interstate)؟","o":["30 mph","40 mph","50 mph","55 mph"],"h1":"المركبات التي لا تستطيع السير بهذه السرعة غير مسموح لها على الطريق السريع بين الولايات.","h2":"على شبكة الطرق السريعة بين الولايات في Iowa الحد الأدنى للسرعة هو 40 mph، والمركبات التي لا تستطيع السير بهذه السرعة غير مسموح لها هناك.","p":"صحيح. الحد الأدنى على الطريق السريع بين الولايات هو 40 mph."},"ref":{"doc":"IA","page":42}},{"id":"ia-027","scope":"IA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Iowa, besides from sunset to sunrise, when does the law require your headlights to be on?","o":["Only on the interstate","Only when it is raining","When you can see 500 feet or less","When you drive more than 50 miles"],"h1":"Think of fog, heavy rain or snow.","h2":"Iowa law requires both headlights from sunset to sunrise and whenever you can see only 500 feet or less, such as in fog, heavy rain or snow.","p":"Right. Headlights on when visibility is 500 feet or less."},"es":{"q":"En Iowa, además de desde la puesta hasta la salida del sol, ¿cuándo exige la ley tener las luces delanteras encendidas?","o":["Solo en la interestatal","Solo cuando llueve","Cuando puede ver a 500 pies o menos","Cuando maneja más de 50 millas"],"h1":"Piense en niebla, lluvia fuerte o nieve.","h2":"La ley de Iowa exige las dos luces delanteras desde la puesta hasta la salida del sol y siempre que solo pueda ver a 500 pies o menos, por ejemplo con niebla, lluvia fuerte o nieve.","p":"Correcto. Luces encendidas cuando la visibilidad es de 500 pies o menos."},"zh":{"q":"在 Iowa，除了从日落到日出以外，法律还要求你在什么时候打开车头灯？","o":["只在州际公路上","只在下雨时","当你只能看清 500 英尺或更近时","当你开车超过 50 英里时"],"h1":"想一想大雾、大雨或下雪的时候。","h2":"Iowa 法律要求从日落到日出要打开两个车头灯，而且只要你只能看清 500 英尺或更近（比如大雾、大雨或下雪时）也要打开。","p":"对。能见度在 500 英尺或更近时要开车头灯。"},"vi":{"q":"Ở Iowa, ngoài thời gian từ lúc mặt trời lặn đến lúc mặt trời mọc, luật còn bắt bạn bật đèn pha khi nào?","o":["Chỉ khi đi trên xa lộ liên bang","Chỉ khi trời mưa","Khi bạn chỉ nhìn thấy được 500 feet hoặc ít hơn","Khi bạn lái xe hơn 50 dặm"],"h1":"Hãy nghĩ đến sương mù, mưa lớn hoặc tuyết.","h2":"Luật Iowa bắt bật cả hai đèn pha từ lúc mặt trời lặn đến lúc mặt trời mọc, và bất cứ khi nào bạn chỉ nhìn thấy được 500 feet hoặc ít hơn, như khi có sương mù, mưa lớn hoặc tuyết.","p":"Đúng. Bật đèn pha khi tầm nhìn từ 500 feet trở xuống."},"tl":{"q":"Sa Iowa, bukod sa mula paglubog hanggang pagsikat ng araw, kailan pa iniuutos ng batas na nakabukas ang iyong headlights?","o":["Sa interstate lamang","Kapag umuulan lamang","Kapag 500 talampakan o mas maikli lang ang kaya mong makita","Kapag nagmamaneho ka nang higit sa 50 milya"],"h1":"Isipin ang hamog, malakas na ulan o niyebe.","h2":"Iniuutos ng batas ng Iowa na nakabukas ang dalawang headlights mula paglubog hanggang pagsikat ng araw at tuwing 500 talampakan o mas maikli lang ang kaya mong makita, gaya ng sa hamog, malakas na ulan o niyebe.","p":"Tama. Buksan ang headlights kapag 500 talampakan o mas maikli ang nakikita."},"ar":{"q":"في ولاية Iowa، إلى جانب الفترة من غروب الشمس إلى شروقها، متى يُلزمك القانون بتشغيل المصابيح الأمامية؟","o":["على الطريق السريع بين الولايات فقط","عندما تمطر فقط","عندما لا تستطيع الرؤية إلا لمسافة 500 قدم أو أقل","عندما تقود أكثر من 50 ميلًا"],"h1":"فكّر في الضباب أو المطر الغزير أو الثلج.","h2":"قانون Iowa يُلزمك بتشغيل المصباحين الأماميين من غروب الشمس إلى شروقها، وكلما كانت رؤيتك 500 قدم أو أقل، مثل وقت الضباب أو المطر الغزير أو الثلج.","p":"صحيح. شغّل المصابيح الأمامية عندما تكون الرؤية 500 قدم أو أقل."},"ref":{"doc":"IA","page":49}},{"id":"ia-028","scope":"IA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Iowa, how close to a fire hydrant may you not park?","o":["Closer than 15 feet","Closer than 5 feet","Closer than 20 feet","Closer than 50 feet"],"h1":"In Iowa this distance is shorter than in many other states.","h2":"In Iowa, you may not park closer than five feet from a fire hydrant, or in a marked hydrant red zone.","p":"Right. In Iowa, stay at least five feet from a fire hydrant."},"es":{"q":"En Iowa, ¿a qué distancia de un hidrante no puede estacionarse?","o":["A menos de 15 pies","A menos de 5 pies","A menos de 20 pies","A menos de 50 pies"],"h1":"En Iowa esta distancia es más corta que en muchos otros estados.","h2":"En Iowa, no puede estacionarse a menos de cinco pies de un hidrante, ni en una zona roja marcada para hidrantes.","p":"Correcto. En Iowa, quédese al menos a cinco pies de un hidrante."},"zh":{"q":"在 Iowa，离消防栓多近的地方不能停车？","o":["少于 15 英尺","少于 5 英尺","少于 20 英尺","少于 50 英尺"],"h1":"在 Iowa，这个距离比很多其他州短。","h2":"在 Iowa，你不能在离消防栓不到 5 英尺的地方停车，也不能停在标出的消防栓红色区域内。","p":"对。在 Iowa，要离消防栓至少 5 英尺。"},"vi":{"q":"Ở Iowa, bạn không được đậu xe gần trụ nước cứu hỏa hơn bao nhiêu?","o":["Gần hơn 15 feet","Gần hơn 5 feet","Gần hơn 20 feet","Gần hơn 50 feet"],"h1":"Ở Iowa, khoảng cách này ngắn hơn ở nhiều tiểu bang khác.","h2":"Ở Iowa, bạn không được đậu xe gần trụ nước cứu hỏa hơn 5 feet, hoặc trong vùng sơn đỏ có đánh dấu quanh trụ nước.","p":"Đúng. Ở Iowa, hãy đậu cách trụ nước cứu hỏa ít nhất 5 feet."},"tl":{"q":"Sa Iowa, gaano kalapit sa fire hydrant ang hindi ka puwedeng pumarada?","o":["Mas malapit sa 15 talampakan","Mas malapit sa 5 talampakan","Mas malapit sa 20 talampakan","Mas malapit sa 50 talampakan"],"h1":"Sa Iowa, mas maikli ang layong ito kaysa sa maraming ibang estado.","h2":"Sa Iowa, hindi ka puwedeng pumarada nang mas malapit sa 5 talampakan mula sa fire hydrant, o sa may markang pulang zone ng hydrant.","p":"Tama. Sa Iowa, lumayo nang hindi bababa sa 5 talampakan mula sa fire hydrant."},"ar":{"q":"في Iowa، ما المسافة من صنبور إطفاء الحريق التي لا يجوز أن تركن أقرب منها؟","o":["أقرب من 15 قدمًا","أقرب من 5 أقدام","أقرب من 20 قدمًا","أقرب من 50 قدمًا"],"h1":"في Iowa هذه المسافة أقصر مما هي عليه في كثير من الولايات الأخرى.","h2":"في Iowa لا يجوز لك أن تركن على مسافة أقل من 5 أقدام من صنبور إطفاء الحريق، ولا في المنطقة الحمراء المحددة حول الصنبور.","p":"صحيح. في Iowa ابقَ على بعد 5 أقدام على الأقل من صنبور إطفاء الحريق."},"ref":{"doc":"IA","page":21}},{"id":"ia-029","scope":"IA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Iowa, you must park on a street with a curb. How close to the curb should your car be?","o":["Within 3 feet","Within 24 inches","Within 30 inches","Within 18 inches"],"h1":"It is less than half a yard.","h2":"In Iowa, when you park on a street with a curb, your car should be within 18 inches of the curb.","p":"Right. Park within 18 inches of the curb."},"es":{"q":"En Iowa, debe estacionarse en una calle con bordillo. ¿Qué tan cerca del bordillo debe quedar su auto?","o":["A no más de 3 pies","A no más de 24 pulgadas","A no más de 30 pulgadas","A no más de 18 pulgadas"],"h1":"Es menos de media yarda.","h2":"En Iowa, al estacionarse en una calle con bordillo, su auto debe quedar a no más de 18 pulgadas del bordillo.","p":"Correcto. Estaciónese a no más de 18 pulgadas del bordillo."},"zh":{"q":"在 Iowa，你要在有路缘的街上停车。你的车应该离路缘多近？","o":["3 英尺以内","24 英寸以内","30 英寸以内","18 英寸以内"],"h1":"这个距离不到半码。","h2":"在 Iowa，在有路缘的街上停车时，你的车应该在离路缘 18 英寸以内。","p":"对。停车时要在离路缘 18 英寸以内。"},"vi":{"q":"Ở Iowa, bạn phải đậu xe trên một con đường có lề. Xe của bạn nên cách lề bao xa?","o":["Trong vòng 3 feet","Trong vòng 24 inch","Trong vòng 30 inch","Trong vòng 18 inch"],"h1":"Khoảng cách này chưa tới nửa yard.","h2":"Ở Iowa, khi bạn đậu xe trên con đường có lề, xe của bạn nên cách lề không quá 18 inch.","p":"Đúng. Hãy đậu xe cách lề không quá 18 inch."},"tl":{"q":"Sa Iowa, kailangan mong pumarada sa kalyeng may gilid (curb). Gaano dapat kalapit ang kotse mo sa curb?","o":["Sa loob ng 3 talampakan","Sa loob ng 24 pulgada","Sa loob ng 30 pulgada","Sa loob ng 18 pulgada"],"h1":"Kulang ito sa kalahating yarda.","h2":"Sa Iowa, kapag pumarada ka sa kalyeng may curb, dapat nasa loob ng 18 pulgada mula sa curb ang kotse mo.","p":"Tama. Pumarada sa loob ng 18 pulgada mula sa curb."},"ar":{"q":"في Iowa، عليك أن تركن في شارع له رصيف. كم يجب أن تكون سيارتك قريبة من الرصيف؟","o":["في حدود 3 أقدام","في حدود 24 بوصة","في حدود 30 بوصة","في حدود 18 بوصة"],"h1":"المسافة أقل من نصف ياردة.","h2":"في Iowa، عندما تركن في شارع له رصيف، يجب أن تكون سيارتك على بعد 18 بوصة أو أقل من الرصيف.","p":"صحيح. اركن على بعد 18 بوصة أو أقل من الرصيف."},"ref":{"doc":"IA","page":21}},{"id":"ia-030","scope":"IA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Iowa, a passenger has an open can of beer in the car. What can happen?","o":["The driver and each passenger can be fined up to $200","Only the driver can be fined, up to $50","Nothing, if the driver is not drinking","The car is towed, but there is no fine"],"h1":"The open container law applies to everyone in the car, not only the driver.","h2":"In Iowa, an open container of alcohol in a car is a simple misdemeanor, with a fine of up to $200 for the driver and for each passenger.","p":"Right. The driver and every passenger can each be fined up to $200."},"es":{"q":"En Iowa, un pasajero tiene una lata de cerveza abierta en el auto. ¿Qué puede pasar?","o":["El conductor y cada pasajero pueden recibir una multa de hasta $200","Solo el conductor puede recibir una multa, de hasta $50","Nada, si el conductor no está bebiendo","Se remolca el auto, pero no hay multa"],"h1":"La ley de envases abiertos se aplica a todos en el auto, no solo al conductor.","h2":"En Iowa, llevar un envase abierto de alcohol en un auto es un delito menor, con una multa de hasta $200 para el conductor y para cada pasajero.","p":"Correcto. El conductor y cada pasajero pueden recibir una multa de hasta $200."},"zh":{"q":"在 Iowa，车上一名乘客拿着一罐已打开的啤酒。会发生什么？","o":["司机和每名乘客都可能被罚款，最多 $200","只有司机会被罚款，最多 $50","如果司机没有喝酒，就没事","车会被拖走，但不会罚款"],"h1":"开口容器法适用于车上的每个人，不只是司机。","h2":"在 Iowa，车里有打开的酒类容器属于轻罪，司机和每名乘客都可能被罚款，最多 $200。","p":"对。司机和每名乘客都可能各被罚款最多 $200。"},"vi":{"q":"Ở Iowa, một hành khách có một lon bia đã mở trong xe. Điều gì có thể xảy ra?","o":["Tài xế và mỗi hành khách có thể bị phạt đến $200","Chỉ tài xế bị phạt, đến $50","Không sao cả, nếu tài xế không uống","Xe bị kéo đi, nhưng không bị phạt tiền"],"h1":"Luật về đồ chứa rượu đã mở áp dụng cho mọi người trong xe, không chỉ tài xế.","h2":"Ở Iowa, có đồ chứa rượu đã mở trong xe là một tội nhẹ, với tiền phạt đến $200 cho tài xế và cho mỗi hành khách.","p":"Đúng. Tài xế và mỗi hành khách đều có thể bị phạt đến $200."},"tl":{"q":"Sa Iowa, may bukas na lata ng beer ang isang pasahero sa kotse. Ano ang puwedeng mangyari?","o":["Puwedeng pagmultahin ang driver at bawat pasahero nang hanggang $200","Ang driver lang ang puwedeng pagmultahin, hanggang $50","Wala, kung hindi umiinom ang driver","Hihilahin ang kotse, pero walang multa"],"h1":"Ang batas sa bukas na lalagyan ng alak ay para sa lahat ng nasa kotse, hindi lang sa driver.","h2":"Sa Iowa, ang bukas na lalagyan ng alak sa kotse ay isang simple misdemeanor, na may multang hanggang $200 para sa driver at para sa bawat pasahero.","p":"Tama. Puwedeng pagmultahin ang driver at bawat pasahero nang hanggang $200 bawat isa."},"ar":{"q":"في Iowa، مع أحد الركاب علبة بيرة مفتوحة في السيارة. ماذا يمكن أن يحدث؟","o":["يمكن تغريم السائق وكل راكب حتى $200","يمكن تغريم السائق فقط، حتى $50","لا شيء، إذا كان السائق لا يشرب","تُسحب السيارة، لكن بلا غرامة"],"h1":"قانون الحاوية المفتوحة ينطبق على كل من في السيارة، وليس على السائق فقط.","h2":"في Iowa، وجود حاوية كحول مفتوحة في السيارة مخالفة بسيطة (simple misdemeanor)، وغرامتها تصل إلى $200 للسائق ولكل راكب.","p":"صحيح. يمكن تغريم السائق وكل راكب حتى $200 لكل واحد."},"ref":{"doc":"IA","page":37}},{"id":"ia-031","scope":"IA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Iowa, you may not pass another vehicle within how many feet of an intersection or a railroad crossing?","o":["25 feet","50 feet","100 feet","500 feet"],"h1":"It is about the length of six or seven cars.","h2":"In Iowa, you may not pass another vehicle within 100 feet of an intersection or a railroad crossing.","p":"Right. No passing within 100 feet of an intersection or railroad crossing."},"es":{"q":"En Iowa, ¿a cuántos pies de una intersección o de un cruce de ferrocarril no puede rebasar a otro vehículo?","o":["25 pies","50 pies","100 pies","500 pies"],"h1":"Es más o menos el largo de seis o siete autos.","h2":"En Iowa, no puede rebasar a otro vehículo a menos de 100 pies de una intersección o de un cruce de ferrocarril.","p":"Correcto. No se rebasa a menos de 100 pies de una intersección o cruce de ferrocarril."},"zh":{"q":"在 Iowa，在离路口或铁路道口多少英尺以内，你不能超车？","o":["25 英尺","50 英尺","100 英尺","500 英尺"],"h1":"大约是六七辆车的长度。","h2":"在 Iowa，在离路口或铁路道口 100 英尺以内，你不能超越其他车辆。","p":"对。在离路口或铁路道口 100 英尺以内不能超车。"},"vi":{"q":"Ở Iowa, bạn không được vượt xe khác trong vòng bao nhiêu feet tính từ giao lộ hoặc chỗ băng qua đường sắt?","o":["25 feet","50 feet","100 feet","500 feet"],"h1":"Khoảng bằng chiều dài của sáu hoặc bảy chiếc xe.","h2":"Ở Iowa, bạn không được vượt xe khác trong vòng 100 feet tính từ giao lộ hoặc chỗ băng qua đường sắt.","p":"Đúng. Không được vượt xe trong vòng 100 feet tính từ giao lộ hoặc chỗ băng qua đường sắt."},"tl":{"q":"Sa Iowa, hindi ka puwedeng mag-overtake sa ibang sasakyan sa loob ng ilang talampakan mula sa intersection o tawiran ng riles?","o":["25 talampakan","50 talampakan","100 talampakan","500 talampakan"],"h1":"Halos kasinghaba ito ng anim o pitong kotse.","h2":"Sa Iowa, hindi ka puwedeng mag-overtake sa ibang sasakyan sa loob ng 100 talampakan mula sa intersection o tawiran ng riles.","p":"Tama. Bawal mag-overtake sa loob ng 100 talampakan mula sa intersection o tawiran ng riles."},"ar":{"q":"في Iowa، لا يجوز لك تجاوز مركبة أخرى ضمن كم قدمًا من تقاطع أو معبر سكة حديدية؟","o":["25 قدمًا","50 قدمًا","100 قدم","500 قدم"],"h1":"إنها تقريبًا طول ست أو سبع سيارات.","h2":"في Iowa لا يجوز لك تجاوز مركبة أخرى ضمن 100 قدم من تقاطع أو معبر سكة حديدية.","p":"صحيح. لا تجاوز ضمن 100 قدم من تقاطع أو معبر سكة حديدية."},"ref":{"doc":"IA","page":46}},{"id":"ia-032","scope":"IA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Iowa, the speed limit is 55 mph. At least how far before a turn must you start signaling?","o":["50 feet","100 feet","300 feet","1,000 feet"],"h1":"On faster roads, Iowa asks for a longer warning than on slow streets.","h2":"In Iowa you must signal at least 300 feet before a turn when the speed limit is over 45 mph, and at least 100 feet when it is 45 mph or less.","p":"Right. Over 45 mph, signal at least 300 feet ahead."},"es":{"q":"En Iowa, el límite de velocidad es de 55 mph. ¿Con cuánta anticipación como mínimo debe empezar a señalizar antes de girar?","o":["50 pies","100 pies","300 pies","1,000 pies"],"h1":"En caminos más rápidos, Iowa pide un aviso más largo que en calles lentas.","h2":"En Iowa usted debe señalizar por lo menos 300 pies antes de girar cuando el límite es de más de 45 mph, y por lo menos 100 pies cuando es de 45 mph o menos.","p":"Correcto. Con más de 45 mph, señalice por lo menos 300 pies antes."},"ref":{"doc":"IA","page":43}},{"id":"ia-033","scope":"IA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Iowa, how far behind an emergency vehicle using its lights and siren must you stay?","o":["At least 500 feet","At least 50 feet","At least 100 feet","At least one car length"],"h1":"The distance is much longer than a city block is wide.","h2":"In Iowa you must stay at least 500 feet behind any emergency vehicle that is using its lights and siren.","p":"Right. Stay at least 500 feet back."},"es":{"q":"En Iowa, ¿a qué distancia detrás de un vehículo de emergencia con luces y sirena encendidas debe mantenerse?","o":["Por lo menos 500 pies","Por lo menos 50 pies","Por lo menos 100 pies","Por lo menos el largo de un auto"],"h1":"La distancia es mucho mayor que el ancho de una cuadra.","h2":"En Iowa usted debe mantenerse por lo menos a 500 pies detrás de cualquier vehículo de emergencia que use sus luces y sirena.","p":"Correcto. Manténgase por lo menos a 500 pies."},"ref":{"doc":"IA","page":19}},{"id":"ia-034","scope":"IA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Iowa, how close to a railroad crossing may you not park?","o":["Closer than 5 feet","Closer than 10 feet","Closer than 20 feet","Closer than 50 feet"],"h1":"It is the longest of Iowa's no-parking distances.","h2":"In Iowa you may not park closer than 50 feet to a railroad crossing.","p":"Right. Park at least 50 feet from a railroad crossing."},"es":{"q":"En Iowa, ¿a qué distancia de un cruce de ferrocarril no se puede estacionar?","o":["A menos de 5 pies","A menos de 10 pies","A menos de 20 pies","A menos de 50 pies"],"h1":"Es la más larga de las distancias para no estacionar en Iowa.","h2":"En Iowa no se puede estacionar a menos de 50 pies de un cruce de ferrocarril.","p":"Correcto. Estacione por lo menos a 50 pies de un cruce de ferrocarril."},"ref":{"doc":"IA","page":21}},{"id":"ia-035","scope":"IA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Iowa, how close to the entrance of a fire station may you not park?","o":["Closer than 5 feet","Closer than 20 feet","Closer than 100 feet","Closer than 500 feet"],"h1":"Fire trucks need room to get out fast.","h2":"In Iowa you may not park closer than 20 feet to the entrance of a fire station.","p":"Right. Keep 20 feet away from a fire station entrance."},"es":{"q":"En Iowa, ¿a qué distancia de la entrada de una estación de bomberos no se puede estacionar?","o":["A menos de 5 pies","A menos de 20 pies","A menos de 100 pies","A menos de 500 pies"],"h1":"Los camiones de bomberos necesitan espacio para salir rápido.","h2":"En Iowa no se puede estacionar a menos de 20 pies de la entrada de una estación de bomberos.","p":"Correcto. Manténgase a 20 pies de la entrada de una estación de bomberos."},"ref":{"doc":"IA","page":21}},{"id":"ia-036","scope":"IA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Iowa, how close to a stop sign may you not park?","o":["Closer than 10 feet","Closer than 30 feet","Closer than 50 feet","Closer than 100 feet"],"h1":"It is a short distance, but drivers still need to see the sign.","h2":"In Iowa you may not park closer than 10 feet to a stop sign.","p":"Right. Park at least 10 feet from a stop sign."},"es":{"q":"En Iowa, ¿a qué distancia de una señal de alto (stop) no se puede estacionar?","o":["A menos de 10 pies","A menos de 30 pies","A menos de 50 pies","A menos de 100 pies"],"h1":"Es una distancia corta, pero los conductores necesitan ver la señal.","h2":"En Iowa no se puede estacionar a menos de 10 pies de una señal de alto.","p":"Correcto. Estacione por lo menos a 10 pies de una señal de alto."},"ref":{"doc":"IA","page":21}},{"id":"ia-037","scope":"IA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Iowa, you have a small crash. No one is hurt and your car still runs safely. What does the law say to do with your car?","o":["Leave it exactly where it stopped","Leave it until the insurance company sees it","Move it out of the traffic lanes","Drive it home before you call anyone"],"h1":"Iowa calls this law \"Steer It, Clear It.\"","h2":"In Iowa, after a crash with no injuries, you must move your car out of the traffic lanes if it can be driven and moved safely.","p":"Right. Steer it and clear it out of the traffic lanes."},"es":{"q":"En Iowa, usted tiene un choque pequeño. Nadie está herido y su auto todavía funciona bien. ¿Qué dice la ley que haga con su auto?","o":["Dejarlo exactamente donde quedó","Dejarlo hasta que lo vea la compañía de seguros","Sacarlo de los carriles de tráfico","Manejarlo a su casa antes de llamar a alguien"],"h1":"Iowa llama a esta ley \"Steer It, Clear It\" (muévalo, despeje el camino).","h2":"En Iowa, después de un choque sin heridos, usted debe sacar su auto de los carriles de tráfico si se puede manejar y mover con seguridad.","p":"Correcto. Saque el auto de los carriles de tráfico."},"ref":{"doc":"IA","page":22}},{"id":"ia-038","scope":"IA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Iowa, how much light must the windshield and the windows next to the driver let through?","o":["At least 20 percent","At least 35 percent","At least 50 percent","At least 70 percent"],"h1":"Iowa allows only light tint on these windows.","h2":"In Iowa the windshield and the windows to the driver's right and left must let at least 70 percent of the light through.","p":"Right. They must let at least 70 percent of the light through."},"es":{"q":"En Iowa, ¿cuánta luz deben dejar pasar el parabrisas y las ventanas al lado del conductor?","o":["Por lo menos el 20 por ciento","Por lo menos el 35 por ciento","Por lo menos el 50 por ciento","Por lo menos el 70 por ciento"],"h1":"Iowa solo permite un polarizado claro en estas ventanas.","h2":"En Iowa el parabrisas y las ventanas a la derecha y a la izquierda del conductor deben dejar pasar por lo menos el 70 por ciento de la luz.","p":"Correcto. Deben dejar pasar por lo menos el 70 por ciento de la luz."},"ref":{"doc":"IA","page":24}},{"id":"ia-039","scope":"IA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Iowa, at least how far behind you must you be able to see in your rearview mirror?","o":["50 feet","200 feet","1,000 feet","One mile"],"h1":"If a load blocks this view, you need an outside mirror.","h2":"In Iowa you must be able to see at least 200 feet behind you in your rearview mirror, or have an outside mirror if a load blocks the view.","p":"Right. You must see at least 200 feet behind you."},"es":{"q":"En Iowa, ¿por lo menos a qué distancia detrás de usted debe poder ver por el espejo retrovisor?","o":["50 pies","200 pies","1,000 pies","Una milla"],"h1":"Si una carga tapa esta vista, usted necesita un espejo exterior.","h2":"En Iowa usted debe poder ver por lo menos 200 pies detrás de usted por el espejo retrovisor, o tener un espejo exterior si una carga tapa la vista.","p":"Correcto. Debe ver por lo menos 200 pies hacia atrás."},"ref":{"doc":"IA","page":25}},{"id":"ia-040","scope":"IA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Iowa, which back-seat passengers must wear a seat belt or ride in a child seat?","o":["Everyone under 18","Only children under 6","Only adults over 65","No one in the back seat"],"h1":"Front-seat riders always buckle up. In the back, the rule depends on age.","h2":"In Iowa every passenger under 18 must be buckled up or in a child restraint, in the back seat as well as the front.","p":"Right. Everyone under 18 must be buckled up, front and back."},"es":{"q":"En Iowa, ¿qué pasajeros del asiento trasero deben usar cinturón de seguridad o ir en un asiento para niños?","o":["Todos los menores de 18 años","Solo los niños menores de 6 años","Solo los adultos mayores de 65 años","Nadie en el asiento trasero"],"h1":"Los que van adelante siempre usan cinturón. Atrás, la regla depende de la edad.","h2":"En Iowa todo pasajero menor de 18 años debe llevar el cinturón puesto o ir en un sistema de seguridad para niños, tanto atrás como adelante.","p":"Correcto. Todos los menores de 18 deben ir abrochados, adelante y atrás."},"ref":{"doc":"IA","page":34}},{"id":"ia-041","scope":"IA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Iowa, a passenger under 18 is not wearing a seat belt. What is the fine for that passenger?","o":["A warning only","Up to $10","Up to $25","Up to $100"],"h1":"The fine for an unbuckled teen is twice the fine for an unbuckled adult.","h2":"In Iowa the seat belt fine is up to $50 for each passenger, and up to $100 for each passenger under 18.","p":"Right. Up to $100 for each unbuckled passenger under 18."},"es":{"q":"En Iowa, un pasajero menor de 18 años no lleva puesto el cinturón de seguridad. ¿Cuál es la multa por ese pasajero?","o":["Solo una advertencia","Hasta $10","Hasta $25","Hasta $100"],"h1":"La multa por un menor sin cinturón es el doble que la de un adulto sin cinturón.","h2":"En Iowa la multa por no usar el cinturón es de hasta $50 por cada pasajero, y de hasta $100 por cada pasajero menor de 18 años.","p":"Correcto. Hasta $100 por cada pasajero menor de 18 sin cinturón."},"ref":{"doc":"IA","page":34}},{"id":"ia-042","scope":"IA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Iowa, a baby is under one year old and weighs less than 20 pounds. How must the baby ride?","o":["On an adult's lap with a seat belt","In a booster seat","In a rear-facing child seat","In a forward-facing seat belt"],"h1":"The baby's seat faces the back of the car.","h2":"In Iowa a child under one year old who weighs less than 20 pounds must ride in a rear-facing child restraint.","p":"Right. The baby must ride in a rear-facing seat."},"es":{"q":"En Iowa, un bebé tiene menos de un año y pesa menos de 20 libras. ¿Cómo debe viajar el bebé?","o":["En las piernas de un adulto con cinturón","En un asiento elevado (booster)","En un asiento para niños mirando hacia atrás","Con el cinturón del auto mirando hacia adelante"],"h1":"El asiento del bebé mira hacia la parte de atrás del auto.","h2":"En Iowa un niño menor de un año que pesa menos de 20 libras debe viajar en un asiento de seguridad mirando hacia atrás.","p":"Correcto. El bebé debe viajar en un asiento que mira hacia atrás."},"ref":{"doc":"IA","page":35}},{"id":"ia-043","scope":"IA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Iowa, a driver under 21 is caught with a blood alcohol level of 0.02 or more. At least how long is the license revoked?","o":["7 days","60 days","2 years","5 years"],"h1":"It is about two months. It becomes 180 days at 0.08 or more.","h2":"In Iowa a driver under 21 with a blood alcohol level of 0.02 or more loses the license for at least 60 days, and for at least 180 days at 0.08 or more.","p":"Right. At least 60 days."},"es":{"q":"En Iowa, un conductor menor de 21 años tiene un nivel de alcohol en la sangre de 0.02 o más. ¿Por lo menos cuánto tiempo le revocan la licencia?","o":["7 días","60 días","2 años","5 años"],"h1":"Son unos dos meses. Sube a 180 días con 0.08 o más.","h2":"En Iowa un conductor menor de 21 años con un nivel de alcohol en la sangre de 0.02 o más pierde la licencia por lo menos 60 días, y por lo menos 180 días con 0.08 o más.","p":"Correcto. Por lo menos 60 días."},"ref":{"doc":"IA","page":37}},{"id":"ia-044","scope":"IA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Iowa, an adult drives while intoxicated but is not found guilty in criminal court. What happens to the license?","o":["Nothing, because there was no conviction","It is suspended for 7 days","The driver only gets a warning letter","It is still revoked for at least 180 days"],"h1":"The license penalty does not wait for the court case.","h2":"In Iowa, even without a criminal conviction, driving while intoxicated leads to a license revocation of at least 180 days.","p":"Right. The license is still revoked for at least 180 days."},"es":{"q":"En Iowa, un adulto maneja intoxicado pero no lo declaran culpable en la corte penal. ¿Qué pasa con la licencia?","o":["Nada, porque no hubo condena","La suspenden por 7 días","Solo recibe una carta de advertencia","Igual se la revocan por lo menos 180 días"],"h1":"La sanción a la licencia no espera el caso en la corte.","h2":"En Iowa, aun sin una condena penal, manejar intoxicado lleva a la revocación de la licencia por lo menos 180 días.","p":"Correcto. Igual le revocan la licencia por lo menos 180 días."},"ref":{"doc":"IA","page":37}},{"id":"ia-045","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, a driver under 18 loses the license for drunk driving (OWI). May the teen get a temporary restricted license?","o":["No, drivers under 18 cannot get one","Yes, after 7 days","Yes, to drive to school only","Yes, if a parent signs a form"],"h1":"Iowa is stricter with the youngest drivers here.","h2":"In Iowa a driver under 18 whose license is revoked for OWI cannot get a temporary restricted license.","p":"Right. Under 18, there is no temporary restricted license after an OWI."},"es":{"q":"En Iowa, a un conductor menor de 18 años le quitan la licencia por manejar ebrio (OWI). ¿Puede recibir una licencia temporal restringida?","o":["No, los menores de 18 no pueden recibirla","Sí, después de 7 días","Sí, solo para ir a la escuela","Sí, si un padre firma un formulario"],"h1":"Aquí Iowa es más estricto con los conductores más jóvenes.","h2":"En Iowa un conductor menor de 18 años a quien le revocan la licencia por OWI no puede recibir una licencia temporal restringida.","p":"Correcto. Los menores de 18 no reciben licencia temporal restringida después de un OWI."},"ref":{"doc":"IA","page":37}},{"id":"ia-046","scope":"IA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Iowa, you see an orange reflective triangle on the back of a vehicle. How fast does that vehicle usually go?","o":["At least 55 mph","Exactly 45 mph","35 mph or less","Only 5 mph"],"h1":"You often see this sign on farm vehicles and horse-drawn wagons.","h2":"In Iowa an orange reflective triangle on the back of a vehicle means it travels at 35 mph or less.","p":"Right. It moves at 35 mph or less."},"es":{"q":"En Iowa, usted ve un triángulo anaranjado reflectante en la parte de atrás de un vehículo. ¿A qué velocidad suele ir ese vehículo?","o":["Por lo menos 55 mph","Exactamente 45 mph","35 mph o menos","Solo 5 mph"],"h1":"Esta señal se ve a menudo en vehículos agrícolas y carretas tiradas por caballos.","h2":"En Iowa un triángulo anaranjado reflectante en la parte de atrás de un vehículo significa que va a 35 millas por hora o menos.","p":"Correcto. Va a 35 mph o menos."},"ref":{"doc":"IA","page":11}},{"id":"ia-047","scope":"IA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Iowa, how should you pass a person riding a bicycle?","o":["Stay in your lane and pass close by","Change lanes completely, as you would for a car","Honk and pass on the right","Drive on the shoulder to go around"],"h1":"Give the bicyclist the whole lane.","h2":"In Iowa, when you pass a bicyclist, you must change lanes completely and give the rider the whole lane, as you would for any other vehicle.","p":"Right. Change lanes completely to pass a bicycle."},"es":{"q":"En Iowa, ¿cómo debe rebasar a una persona que va en bicicleta?","o":["Quedarse en su carril y pasar muy cerca","Cambiar de carril por completo, como lo haría con un auto","Tocar la bocina y rebasar por la derecha","Manejar por el acotamiento para pasar"],"h1":"Déle al ciclista todo el carril.","h2":"En Iowa, cuando rebasa a un ciclista, usted debe cambiar de carril por completo y darle todo el carril, igual que con cualquier otro vehículo.","p":"Correcto. Cambie de carril por completo para rebasar una bicicleta."},"ref":{"doc":"IA","page":58}},{"id":"ia-048","scope":"IA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Iowa, how fast do snowplows usually go while they work?","o":["25 to 35 mph","5 to 10 mph","45 to 55 mph","60 to 70 mph"],"h1":"Many drivers hit plows from behind because plows are slower than they expect.","h2":"In Iowa snowplows usually work at 25 to 35 mph, so approach them with care.","p":"Right. Snowplows usually go 25 to 35 mph."},"es":{"q":"En Iowa, ¿a qué velocidad suelen ir las máquinas quitanieves mientras trabajan?","o":["De 25 a 35 mph","De 5 a 10 mph","De 45 a 55 mph","De 60 a 70 mph"],"h1":"Muchos conductores chocan por detrás con las quitanieves porque van más lento de lo que esperan.","h2":"En Iowa las máquinas quitanieves suelen trabajar a 25 a 35 millas por hora, así que acérquese con cuidado.","p":"Correcto. Las quitanieves suelen ir de 25 a 35 mph."},"ref":{"doc":"IA","page":61}},{"id":"ia-049","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, one way to count as a resident for a driver's license is to live in the state without a break. For how long?","o":["1 year","6 months","90 days","30 days"],"h1":"It is about one month.","h2":"For an Iowa driver's license, living in Iowa for 30 days in a row is one of the ways to count as a resident.","p":"Right. 30 days in a row makes you a resident."},"es":{"q":"En Iowa, una forma de contar como residente para la licencia de manejar es vivir en el estado sin interrupción. ¿Por cuánto tiempo?","o":["1 año","6 meses","90 días","30 días"],"h1":"Es más o menos un mes.","h2":"Para la licencia de manejar de Iowa, vivir en Iowa 30 días seguidos es una de las formas de contar como residente.","p":"Correcto. Con 30 días seguidos usted es residente."},"ref":{"doc":"IA","page":4}},{"id":"ia-050","scope":"IA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Iowa, you are pulling a trailer and no speed limit is posted. What is the general speed limit for a vehicle pulling another vehicle?","o":["35 mph","45 mph","60 mph","70 mph"],"h1":"It matches the limit for a suburban district.","h2":"In Iowa, when no limit is posted, a vehicle pulling another vehicle may go no faster than 45 mph.","p":"Right. The general limit when towing is 45 mph."},"es":{"q":"En Iowa, usted jala un remolque y no hay un límite de velocidad señalizado. ¿Cuál es el límite general para un vehículo que jala otro vehículo?","o":["35 mph","45 mph","60 mph","70 mph"],"h1":"Es el mismo límite que en una zona suburbana.","h2":"En Iowa, cuando no hay un límite señalizado, un vehículo que jala otro vehículo no puede ir a más de 45 millas por hora.","p":"Correcto. El límite general al remolcar es de 45 mph."},"ref":{"doc":"IA","page":42}},{"id":"ia-051","scope":"IA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Iowa, a rideshare driver (such as Uber or Lyft) is carrying a passenger toward railroad tracks. What must the driver do?","o":["Speed up to cross quickly","Stop only if a train is in sight","Stop 15 to 50 feet from the tracks before crossing","Stop right on the tracks to look"],"h1":"Iowa treats paid drivers like school buses here.","h2":"In Iowa drivers carrying passengers for hire, like school buses, must stop 15 to 50 feet from the railroad tracks before crossing, unless an officer or an EXEMPT sign says otherwise.","p":"Right. Stop 15 to 50 feet from the tracks, then cross."},"es":{"q":"En Iowa, un conductor de viajes compartidos (como Uber o Lyft) lleva a un pasajero y se acerca a unas vías del tren. ¿Qué debe hacer el conductor?","o":["Acelerar para cruzar rápido","Parar solo si se ve un tren","Parar a entre 15 y 50 pies de las vías antes de cruzar","Parar sobre las vías para mirar"],"h1":"Aquí Iowa trata a los conductores que cobran igual que a los autobuses escolares.","h2":"En Iowa los conductores que llevan pasajeros por pago, igual que los autobuses escolares, deben parar a entre 15 y 50 pies de las vías antes de cruzar, salvo que un policía o una señal EXEMPT indique otra cosa.","p":"Correcto. Pare a entre 15 y 50 pies de las vías y luego cruce."},"ref":{"doc":"IA","page":12}},{"id":"id-001","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, how many questions are on the written knowledge test?","o":["20 questions","25 questions","40 questions","50 questions"],"h1":"It is more than 25 and fewer than 50.","h2":"The Idaho knowledge test has 40 questions, all taken from the driver's handbook.","p":"Right. The Idaho test has 40 questions."},"es":{"q":"En Idaho, ¿cuántas preguntas tiene el examen escrito de conocimientos?","o":["20 preguntas","25 preguntas","40 preguntas","50 preguntas"],"h1":"Son más de 25 y menos de 50.","h2":"El examen de conocimientos de Idaho tiene 40 preguntas, todas tomadas del manual del conductor.","p":"Correcto. El examen de Idaho tiene 40 preguntas."},"zh":{"q":"在 Idaho，驾照笔试有多少道题？","o":["20 道题","25 道题","40 道题","50 道题"],"h1":"比 25 多，比 50 少。","h2":"Idaho 的驾照笔试有 40 道题，都来自驾驶手册。","p":"对。Idaho 的笔试有 40 道题。"},"vi":{"q":"Ở Idaho, bài thi kiến thức viết có bao nhiêu câu hỏi?","o":["20 câu hỏi","25 câu hỏi","40 câu hỏi","50 câu hỏi"],"h1":"Nhiều hơn 25 và ít hơn 50.","h2":"Bài thi kiến thức của Idaho có 40 câu hỏi, tất cả đều lấy từ sổ tay lái xe.","p":"Đúng. Bài thi của Idaho có 40 câu hỏi."},"tl":{"q":"Sa Idaho, ilang tanong ang nasa nakasulat na knowledge test?","o":["20 tanong","25 tanong","40 tanong","50 tanong"],"h1":"Higit ito sa 25 at kulang sa 50.","h2":"Ang knowledge test ng Idaho ay may 40 tanong, lahat ay kinuha mula sa driver's handbook.","p":"Tama. Ang test ng Idaho ay may 40 tanong."},"ar":{"q":"في Idaho، كم عدد الأسئلة في اختبار المعرفة الكتابي؟","o":["20 سؤالًا","25 سؤالًا","40 سؤالًا","50 سؤالًا"],"h1":"العدد أكثر من 25 وأقل من 50.","h2":"اختبار المعرفة في Idaho فيه 40 سؤالًا، وكلها مأخوذة من دليل السائق.","p":"صحيح. اختبار Idaho فيه 40 سؤالًا."},"ref":{"doc":"ID","page":32}},{"id":"id-002","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, how many questions can you miss on the knowledge test and still pass?","o":["Up to 6","Up to 2","Up to 10","Up to 12"],"h1":"You need a high score, about 85 percent.","h2":"On the Idaho knowledge test you can miss up to 6 of the 40 questions, so you need 34 right answers to pass.","p":"Well done. You can miss up to 6 questions."},"es":{"q":"En Idaho, ¿cuántas preguntas puede fallar en el examen de conocimientos y aun así aprobar?","o":["Hasta 6","Hasta 2","Hasta 10","Hasta 12"],"h1":"Se necesita una nota alta, de alrededor del 85 por ciento.","h2":"En el examen de conocimientos de Idaho usted puede fallar hasta 6 de las 40 preguntas, así que necesita 34 respuestas correctas para aprobar.","p":"Muy bien. Puede fallar hasta 6 preguntas."},"zh":{"q":"在 Idaho，驾照笔试最多可以答错几道题还能通过？","o":["最多 6 道","最多 2 道","最多 10 道","最多 12 道"],"h1":"你需要很高的分数，大约 85%。","h2":"在 Idaho 的驾照笔试中，40 道题你最多可以答错 6 道，所以你需要答对 34 道才能通过。","p":"很好。你最多可以答错 6 道题。"},"vi":{"q":"Ở Idaho, bạn có thể trả lời sai bao nhiêu câu trong bài thi kiến thức mà vẫn đậu?","o":["Tối đa 6 câu","Tối đa 2 câu","Tối đa 10 câu","Tối đa 12 câu"],"h1":"Bạn cần điểm cao, khoảng 85 phần trăm.","h2":"Trong bài thi kiến thức của Idaho, bạn có thể sai tối đa 6 trên 40 câu, nên bạn cần 34 câu đúng để đậu.","p":"Giỏi lắm. Bạn có thể sai tối đa 6 câu."},"tl":{"q":"Sa Idaho, ilang tanong ang puwede mong mamali sa knowledge test at pumasa pa rin?","o":["Hanggang 6","Hanggang 2","Hanggang 10","Hanggang 12"],"h1":"Kailangan mo ng mataas na score, mga 85 porsiyento.","h2":"Sa knowledge test ng Idaho, puwede kang magkamali sa hanggang 6 sa 40 tanong, kaya kailangan mo ng 34 na tamang sagot para pumasa.","p":"Magaling. Puwede kang magkamali sa hanggang 6 na tanong."},"ar":{"q":"في Idaho، كم سؤالًا يمكن أن تخطئ فيه في اختبار المعرفة وتنجح مع ذلك؟","o":["حتى 6","حتى 2","حتى 10","حتى 12"],"h1":"تحتاج إلى درجة عالية، حوالي 85 بالمئة.","h2":"في اختبار المعرفة في Idaho يمكنك أن تخطئ في 6 أسئلة على الأكثر من 40، لذلك تحتاج إلى 34 إجابة صحيحة لتنجح.","p":"أحسنت. يمكنك أن تخطئ في 6 أسئلة على الأكثر."},"ref":{"doc":"ID","page":32}},{"id":"id-003","scope":"ID","cat":"licensing","sign":null,"c":1,"en":{"q":"In Idaho, how long must a teen hold the supervised instruction permit, at a minimum?","o":["3 months","6 months","9 months","12 months"],"h1":"It is half of a year.","h2":"An Idaho teen must hold the supervised instruction permit for at least six months without any violation.","p":"Right. The minimum is six months."},"es":{"q":"En Idaho, ¿por cuánto tiempo como mínimo debe un joven tener el permiso de instrucción supervisada?","o":["3 meses","6 meses","9 meses","12 meses"],"h1":"Es la mitad de un año.","h2":"Un joven en Idaho debe tener el permiso de instrucción supervisada por lo menos seis meses sin ninguna infracción.","p":"Correcto. El mínimo es de seis meses."},"zh":{"q":"在 Idaho，青少年必须持有有人陪同的学习驾照（supervised instruction permit）最少多久？","o":["3 个月","6 个月","9 个月","12 个月"],"h1":"是半年。","h2":"Idaho 的青少年必须持有有人陪同的学习驾照至少六个月，而且没有任何违规。","p":"对。最少是六个月。"},"vi":{"q":"Ở Idaho, thiếu niên phải giữ giấy phép tập lái có giám sát (supervised instruction permit) ít nhất bao lâu?","o":["3 tháng","6 tháng","9 tháng","12 tháng"],"h1":"Đó là nửa năm.","h2":"Ở Idaho, thiếu niên phải giữ giấy phép tập lái có giám sát ít nhất sáu tháng mà không có vi phạm nào.","p":"Đúng. Tối thiểu là sáu tháng."},"tl":{"q":"Sa Idaho, gaano katagal, hindi bababa, dapat hawak ng isang teen ang supervised instruction permit?","o":["3 buwan","6 na buwan","9 na buwan","12 buwan"],"h1":"Kalahating taon ito.","h2":"Ang isang teen sa Idaho ay dapat humawak ng supervised instruction permit nang hindi bababa sa anim na buwan nang walang anumang paglabag.","p":"Tama. Ang pinakamababa ay anim na buwan."},"ar":{"q":"في Idaho، ما أقل مدة يجب أن يحتفظ فيها المراهق بتصريح التعلّم تحت الإشراف (supervised instruction permit)؟","o":["3 أشهر","6 أشهر","9 أشهر","12 شهرًا"],"h1":"هي نصف سنة.","h2":"يجب على المراهق في Idaho أن يحتفظ بتصريح التعلّم تحت الإشراف ستة أشهر على الأقل دون أي مخالفة.","p":"صحيح. أقل مدة هي ستة أشهر."},"ref":{"doc":"ID","page":19}},{"id":"id-004","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, how old must the licensed driver beside a permit holder be?","o":["At least 16","At least 18","At least 25","At least 21"],"h1":"The helper must be old enough to buy alcohol legally.","h2":"In Idaho the supervising driver must hold a valid license, be at least 21 years old, and sit in the seat beside the permit holder.","p":"Correct. The supervisor must be 21 or older."},"es":{"q":"En Idaho, ¿qué edad debe tener el conductor con licencia que va al lado de quien tiene el permiso?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 25","Por lo menos 21"],"h1":"El acompañante debe tener la edad para comprar alcohol legalmente.","h2":"En Idaho el conductor que supervisa debe tener licencia válida, por lo menos 21 años, y sentarse al lado de quien tiene el permiso.","p":"Correcto. El supervisor debe tener 21 años o más."},"zh":{"q":"在 Idaho，坐在持学习驾照的人旁边、有驾照的司机必须几岁？","o":["至少 16 岁","至少 18 岁","至少 25 岁","至少 21 岁"],"h1":"陪同的人必须到了可以合法买酒的年龄。","h2":"在 Idaho，陪同的司机必须有有效驾照、至少 21 岁，并坐在持学习驾照的人旁边的座位上。","p":"正确。陪同的人必须 21 岁或以上。"},"vi":{"q":"Ở Idaho, người có bằng lái ngồi bên cạnh người có giấy phép tập lái phải bao nhiêu tuổi?","o":["Ít nhất 16 tuổi","Ít nhất 18 tuổi","Ít nhất 25 tuổi","Ít nhất 21 tuổi"],"h1":"Người hướng dẫn phải đủ tuổi để mua rượu hợp pháp.","h2":"Ở Idaho, người giám sát phải có bằng lái hợp lệ, ít nhất 21 tuổi, và ngồi ở ghế bên cạnh người có giấy phép tập lái.","p":"Chính xác. Người giám sát phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Idaho, ilang taon dapat ang lisensyadong driver na katabi ng may hawak ng permit?","o":["Hindi bababa sa 16","Hindi bababa sa 18","Hindi bababa sa 25","Hindi bababa sa 21"],"h1":"Dapat sapat ang edad ng katuwang para legal na makabili ng alak.","h2":"Sa Idaho, ang nagbabantay na driver ay dapat may valid na lisensya, hindi bababa sa 21 taong gulang, at nakaupo sa upuang katabi ng may hawak ng permit.","p":"Tama. Ang nagbabantay ay dapat 21 taong gulang o higit pa."},"ar":{"q":"في Idaho، كم يجب أن يكون عمر السائق المرخّص الذي يجلس بجانب حامل التصريح؟","o":["16 سنة على الأقل","18 سنة على الأقل","25 سنة على الأقل","21 سنة على الأقل"],"h1":"يجب أن يكون المرافق في سنّ تسمح له بشراء الكحول قانونيًا.","h2":"في Idaho يجب أن يحمل السائق المشرف رخصة سارية، وأن يكون عمره 21 سنة على الأقل، وأن يجلس في المقعد المجاور لحامل التصريح.","p":"صحيح. يجب أن يكون المشرف عمره 21 سنة أو أكثر."},"ref":{"doc":"ID","page":19}},{"id":"id-005","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, how many hours of supervised driving must a teen complete with the instruction permit?","o":["20 hours","30 hours","50 hours","100 hours"],"h1":"It is more than 30 hours.","h2":"An Idaho teen must complete at least 50 hours of supervised driving while holding the instruction permit.","p":"Right. Idaho requires 50 supervised hours."},"es":{"q":"En Idaho, ¿cuántas horas de manejo supervisado debe completar un joven con el permiso de instrucción?","o":["20 horas","30 horas","50 horas","100 horas"],"h1":"Son más de 30 horas.","h2":"Un joven en Idaho debe completar por lo menos 50 horas de manejo supervisado mientras tiene el permiso de instrucción.","p":"Correcto. Idaho exige 50 horas supervisadas."},"zh":{"q":"在 Idaho，青少年持学习驾照期间，必须完成多少小时有人陪同的驾驶？","o":["20 小时","30 小时","50 小时","100 小时"],"h1":"比 30 小时多。","h2":"Idaho 的青少年持学习驾照期间，必须完成至少 50 小时有人陪同的驾驶。","p":"对。Idaho 要求 50 小时有人陪同的驾驶。"},"vi":{"q":"Ở Idaho, thiếu niên phải lái xe có giám sát bao nhiêu giờ khi có giấy phép tập lái?","o":["20 giờ","30 giờ","50 giờ","100 giờ"],"h1":"Nhiều hơn 30 giờ.","h2":"Ở Idaho, thiếu niên phải lái xe có giám sát ít nhất 50 giờ khi đang giữ giấy phép tập lái.","p":"Đúng. Idaho yêu cầu 50 giờ lái có giám sát."},"tl":{"q":"Sa Idaho, ilang oras ng supervised driving ang dapat tapusin ng isang teen habang may instruction permit?","o":["20 oras","30 oras","50 oras","100 oras"],"h1":"Higit ito sa 30 oras.","h2":"Ang isang teen sa Idaho ay dapat makatapos ng hindi bababa sa 50 oras ng supervised driving habang hawak ang instruction permit.","p":"Tama. Ang Idaho ay nangangailangan ng 50 oras na may bantay."},"ar":{"q":"في Idaho، كم ساعة من القيادة تحت الإشراف يجب أن يُكملها المراهق وهو يحمل تصريح التعلّم؟","o":["20 ساعة","30 ساعة","50 ساعة","100 ساعة"],"h1":"العدد أكثر من 30 ساعة.","h2":"يجب على المراهق في Idaho أن يُكمل 50 ساعة على الأقل من القيادة تحت الإشراف وهو يحمل تصريح التعلّم.","p":"صحيح. Idaho تطلب 50 ساعة تحت الإشراف."},"ref":{"doc":"ID","page":19}},{"id":"id-006","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, how many of the supervised practice hours must be at night?","o":["10 hours","2 hours","5 hours","25 hours"],"h1":"It is a round number, smaller than 20.","h2":"At least 10 of the 50 supervised hours in Idaho must be driven at night.","p":"Correct. Ten of the hours must be at night."},"es":{"q":"En Idaho, ¿cuántas de las horas de práctica supervisada deben ser de noche?","o":["10 horas","2 horas","5 horas","25 horas"],"h1":"Es un número redondo, menor que 20.","h2":"En Idaho, por lo menos 10 de las 50 horas supervisadas deben ser de noche.","p":"Correcto. Diez de las horas deben ser de noche."},"zh":{"q":"在 Idaho，有人陪同的练习时间里，必须有多少小时是在夜间？","o":["10 小时","2 小时","5 小时","25 小时"],"h1":"这是一个整数，比 20 小。","h2":"在 Idaho，50 小时有人陪同的驾驶中，至少 10 小时必须在夜间开。","p":"正确。其中十个小时必须在夜间。"},"vi":{"q":"Ở Idaho, bao nhiêu giờ tập lái có giám sát phải là vào ban đêm?","o":["10 giờ","2 giờ","5 giờ","25 giờ"],"h1":"Đó là một số tròn, nhỏ hơn 20.","h2":"Ở Idaho, ít nhất 10 trong 50 giờ lái có giám sát phải là lái vào ban đêm.","p":"Chính xác. Mười giờ phải là vào ban đêm."},"tl":{"q":"Sa Idaho, ilan sa mga oras ng supervised practice ang dapat gawin sa gabi?","o":["10 oras","2 oras","5 oras","25 oras"],"h1":"Buong numero ito, mas maliit sa 20.","h2":"Hindi bababa sa 10 sa 50 oras ng supervised driving sa Idaho ay dapat gawin sa gabi.","p":"Tama. Sampu sa mga oras ay dapat sa gabi."},"ar":{"q":"في Idaho، كم ساعة من ساعات التدريب تحت الإشراف يجب أن تكون في الليل؟","o":["10 ساعات","ساعتان (2)","5 ساعات","25 ساعة"],"h1":"هو عدد مُدوَّر، أقل من 20.","h2":"يجب أن تكون 10 ساعات على الأقل من الخمسين ساعة تحت الإشراف في Idaho قيادةً في الليل.","p":"صحيح. عشر ساعات يجب أن تكون في الليل."},"ref":{"doc":"ID","page":19}},{"id":"id-007","scope":"ID","cat":"licensing","sign":null,"c":1,"en":{"q":"In Idaho, what happens if a teen with a supervised instruction permit gets a traffic conviction?","o":["Nothing changes","The permit is canceled and the six months start over","The teen pays a fine and keeps the same permit","The teen gets the license sooner"],"h1":"The violation-free period has to be earned again.","h2":"In Idaho a traffic conviction cancels the supervised instruction permit, and the six-month period starts over with a new permit.","p":"Right. The six months start again."},"es":{"q":"En Idaho, ¿qué pasa si un joven con permiso de instrucción supervisada recibe una condena de tránsito?","o":["No cambia nada","Se cancela el permiso y los seis meses empiezan de nuevo","El joven paga una multa y conserva el mismo permiso","El joven obtiene la licencia antes"],"h1":"El período sin infracciones se tiene que ganar otra vez.","h2":"En Idaho una condena de tránsito cancela el permiso de instrucción supervisada, y el período de seis meses empieza de nuevo con un permiso nuevo.","p":"Correcto. Los seis meses empiezan otra vez."},"zh":{"q":"在 Idaho，持有人陪同学习驾照的青少年如果被判交通违规，会怎么样？","o":["什么都不变","学习驾照被取消，六个月重新开始算","青少年交罚款，保留原来的学习驾照","青少年可以更早拿到驾照"],"h1":"没有违规的那段时间必须重新挣回来。","h2":"在 Idaho，被判交通违规会让有人陪同的学习驾照被取消，换新的学习驾照后，六个月重新开始算。","p":"对。六个月重新开始算。"},"vi":{"q":"Ở Idaho, điều gì xảy ra nếu thiếu niên có giấy phép tập lái có giám sát bị kết tội vi phạm giao thông?","o":["Không có gì thay đổi","Giấy phép bị hủy và sáu tháng bắt đầu lại từ đầu","Thiếu niên đóng tiền phạt và giữ giấy phép cũ","Thiếu niên được lấy bằng lái sớm hơn"],"h1":"Thời gian không vi phạm phải được tính lại.","h2":"Ở Idaho, khi bị kết tội vi phạm giao thông thì giấy phép tập lái có giám sát bị hủy, và thời gian sáu tháng bắt đầu lại với giấy phép mới.","p":"Đúng. Sáu tháng bắt đầu lại."},"tl":{"q":"Sa Idaho, ano ang mangyayari kung ang teen na may supervised instruction permit ay ma-convict sa isang traffic violation?","o":["Walang magbabago","Kakanselahin ang permit at magsisimula ulit ang anim na buwan","Magbabayad ng multa ang teen at mananatili ang parehong permit","Mas maagang makakakuha ng lisensya ang teen"],"h1":"Kailangang kitain ulit ang panahong walang paglabag.","h2":"Sa Idaho, kinakansela ng traffic conviction ang supervised instruction permit, at magsisimula ulit ang anim na buwan sa bagong permit.","p":"Tama. Magsisimula ulit ang anim na buwan."},"ar":{"q":"في Idaho، ماذا يحدث إذا أُدين مراهق يحمل تصريح التعلّم تحت الإشراف بمخالفة مرورية؟","o":["لا يتغير شيء","يُلغى التصريح وتبدأ الأشهر الستة من جديد","يدفع المراهق غرامة ويحتفظ بنفس التصريح","يحصل المراهق على الرخصة أسرع"],"h1":"يجب كسب فترة بدون مخالفات من جديد.","h2":"في Idaho تؤدي الإدانة بمخالفة مرورية إلى إلغاء تصريح التعلّم تحت الإشراف، وتبدأ فترة الأشهر الستة من جديد مع تصريح جديد.","p":"صحيح. تبدأ الأشهر الستة من جديد."},"ref":{"doc":"ID","page":19}},{"id":"id-008","scope":"ID","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Idaho, who must wear a seat belt while a teen drives with a supervised instruction permit?","o":["Only the driver","Only people in the front seat","Only children","Everyone in the vehicle"],"h1":"Think about every seat in the car.","h2":"While an Idaho teen drives on a supervised instruction permit, everyone in the vehicle must wear a seat belt.","p":"Correct. Everyone must be buckled."},"es":{"q":"En Idaho, ¿quién debe usar cinturón de seguridad mientras un joven maneja con permiso de instrucción supervisada?","o":["Solo el conductor","Solo las personas del asiento delantero","Solo los niños","Todas las personas en el vehículo"],"h1":"Piense en cada asiento del carro.","h2":"Mientras un joven en Idaho maneja con permiso de instrucción supervisada, todas las personas en el vehículo deben usar cinturón de seguridad.","p":"Correcto. Todos deben ir abrochados."},"zh":{"q":"在 Idaho，青少年持有人陪同的学习驾照开车时，谁必须系安全带？","o":["只有司机","只有前排的人","只有小孩","车里的每一个人"],"h1":"想一想车里的每个座位。","h2":"Idaho 的青少年持有人陪同的学习驾照开车时，车里的每一个人都必须系安全带。","p":"正确。每个人都必须系好安全带。"},"vi":{"q":"Ở Idaho, ai phải thắt dây an toàn khi thiếu niên lái xe với giấy phép tập lái có giám sát?","o":["Chỉ người lái","Chỉ người ngồi ghế trước","Chỉ trẻ em","Mọi người trong xe"],"h1":"Hãy nghĩ đến mọi ghế trong xe.","h2":"Khi thiếu niên ở Idaho lái xe với giấy phép tập lái có giám sát, mọi người trong xe đều phải thắt dây an toàn.","p":"Chính xác. Mọi người đều phải thắt dây."},"tl":{"q":"Sa Idaho, sino ang dapat magsuot ng seat belt habang nagmamaneho ang isang teen na may supervised instruction permit?","o":["Ang driver lang","Ang mga nasa harapang upuan lang","Ang mga bata lang","Lahat ng nasa sasakyan"],"h1":"Isipin ang bawat upuan sa kotse.","h2":"Habang nagmamaneho ang isang teen sa Idaho na may supervised instruction permit, lahat ng nasa sasakyan ay dapat magsuot ng seat belt.","p":"Tama. Lahat ay dapat naka-seat belt."},"ar":{"q":"في Idaho، مَن يجب أن يربط حزام الأمان عندما يقود مراهق بتصريح التعلّم تحت الإشراف؟","o":["السائق فقط","الجالسون في المقعد الأمامي فقط","الأطفال فقط","كل مَن في السيارة"],"h1":"فكّر في كل مقعد في السيارة.","h2":"عندما يقود مراهق في Idaho بتصريح التعلّم تحت الإشراف، يجب على كل مَن في السيارة أن يربط حزام الأمان.","p":"صحيح. يجب أن يربط الجميع الحزام."},"ref":{"doc":"ID","page":19}},{"id":"id-009","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, what must a teen have with them while driving on a supervised instruction permit?","o":["A school ID","A passport","The permit itself","A letter from a teacher"],"h1":"It is the document that allows the practice driving.","h2":"An Idaho teen must carry the supervised instruction permit while driving.","p":"Right. Keep the permit with you."},"es":{"q":"En Idaho, ¿qué debe llevar consigo un joven mientras maneja con permiso de instrucción supervisada?","o":["Su identificación escolar","Su pasaporte","El permiso mismo","Una carta de un maestro"],"h1":"Es el documento que le permite practicar.","h2":"Un joven en Idaho debe llevar consigo el permiso de instrucción supervisada mientras maneja.","p":"Correcto. Lleve el permiso con usted."},"zh":{"q":"在 Idaho，青少年持有人陪同的学习驾照开车时，必须随身带着什么？","o":["学生证","护照","学习驾照本身","老师写的信"],"h1":"就是允许你练习开车的那份证件。","h2":"Idaho 的青少年开车时必须随身带着有人陪同的学习驾照。","p":"对。把学习驾照带在身上。"},"vi":{"q":"Ở Idaho, thiếu niên phải mang theo gì khi lái xe với giấy phép tập lái có giám sát?","o":["Thẻ học sinh","Hộ chiếu","Chính giấy phép tập lái","Thư của giáo viên"],"h1":"Đó là giấy tờ cho phép tập lái xe.","h2":"Thiếu niên ở Idaho phải mang theo giấy phép tập lái có giám sát khi lái xe.","p":"Đúng. Hãy mang giấy phép theo bên mình."},"tl":{"q":"Sa Idaho, ano ang dapat dala ng isang teen habang nagmamaneho na may supervised instruction permit?","o":["School ID","Pasaporte","Ang permit mismo","Sulat mula sa guro"],"h1":"Ito ang dokumentong nagpapahintulot sa pagsasanay sa pagmamaneho.","h2":"Ang isang teen sa Idaho ay dapat magdala ng supervised instruction permit habang nagmamaneho.","p":"Tama. Dalhin mo palagi ang permit."},"ar":{"q":"في Idaho، ماذا يجب أن يحمل المراهق معه عندما يقود بتصريح التعلّم تحت الإشراف؟","o":["بطاقة المدرسة","جواز السفر","التصريح نفسه","رسالة من معلّم"],"h1":"هو المستند الذي يسمح بالتدرّب على القيادة.","h2":"يجب على المراهق في Idaho أن يحمل تصريح التعلّم تحت الإشراف معه أثناء القيادة.","p":"صحيح. احمل التصريح معك."},"ref":{"doc":"ID","page":null}},{"id":"id-010","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, when may a licensed driver under 16 drive alone?","o":["Only during daylight hours","Only after sunset","Any time of day","Only on weekends"],"h1":"Night driving needs an adult in the front seat.","h2":"In Idaho a licensed driver under 16 may drive only in daylight hours, 5 a.m. to 10 p.m., unless a licensed person 21 or older sits in the front seat.","p":"Correct. Under 16 means daylight only."},"es":{"q":"En Idaho, ¿cuándo puede manejar solo un conductor con licencia menor de 16 años?","o":["Solo durante las horas de luz del día","Solo después de la puesta del sol","A cualquier hora","Solo los fines de semana"],"h1":"Para manejar de noche se necesita un adulto en el asiento delantero.","h2":"En Idaho un conductor con licencia menor de 16 años solo puede manejar en horas de luz del día, de 5 a.m. a 10 p.m., a menos que una persona con licencia de 21 años o más vaya en el asiento delantero.","p":"Correcto. Menor de 16 significa solo de día."},"zh":{"q":"在 Idaho，16 岁以下、有驾照的司机什么时候可以一个人开车？","o":["只能在白天时段","只能在日落以后","一天中任何时间，白天或夜间都可以","只能在周末"],"h1":"夜间开车需要一个成年人坐在前排。","h2":"在 Idaho，16 岁以下、有驾照的司机只能在白天时段开车，也就是早上 5 点到晚上 10 点，除非有一位 21 岁或以上、有驾照的人坐在前排。","p":"正确。16 岁以下只能在白天开车。"},"vi":{"q":"Ở Idaho, khi nào người có bằng lái dưới 16 tuổi được lái xe một mình?","o":["Chỉ vào giờ ban ngày","Chỉ sau khi mặt trời lặn","Bất cứ giờ nào trong ngày","Chỉ vào cuối tuần"],"h1":"Lái xe ban đêm cần một người lớn ở ghế trước.","h2":"Ở Idaho, người có bằng lái dưới 16 tuổi chỉ được lái vào giờ ban ngày, từ 5 a.m. đến 10 p.m., trừ khi có người có bằng lái từ 21 tuổi trở lên ngồi ở ghế trước.","p":"Chính xác. Dưới 16 tuổi thì chỉ lái ban ngày."},"tl":{"q":"Sa Idaho, kailan puwedeng magmaneho nang mag-isa ang lisensyadong driver na wala pang 16?","o":["Sa oras ng araw (daylight hours) lang","Pagkalubog lang ng araw","Anumang oras, araw man o gabi","Tuwing weekend lang"],"h1":"Ang pagmamaneho sa gabi ay nangangailangan ng adult sa harapang upuan.","h2":"Sa Idaho, ang lisensyadong driver na wala pang 16 ay puwedeng magmaneho lang sa daylight hours, 5 a.m. hanggang 10 p.m., maliban kung may lisensyadong tao na 21 o higit pa sa harapang upuan.","p":"Tama. Kapag wala pang 16, sa araw lang."},"ar":{"q":"في Idaho، متى يُسمح لسائق مرخّص عمره أقل من 16 سنة أن يقود وحده؟","o":["في ساعات النهار فقط","بعد غروب الشمس فقط","في أي وقت من اليوم","في عطلة نهاية الأسبوع فقط"],"h1":"القيادة في الليل تحتاج إلى شخص بالغ في المقعد الأمامي.","h2":"في Idaho يُسمح للسائق المرخّص الذي عمره أقل من 16 سنة أن يقود في ساعات النهار فقط، من 5 a.m. إلى 10 p.m.، إلا إذا جلس في المقعد الأمامي شخص مرخّص عمره 21 سنة أو أكثر.","p":"صحيح. أقل من 16 سنة يعني النهار فقط."},"ref":{"doc":"ID","page":16}},{"id":"id-011","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, how are daylight hours defined for drivers under 16?","o":["From sunrise to sunset","From half an hour before sunrise to half an hour after sunset","From 6 a.m. to 6 p.m.","From 5 a.m. to 10 p.m."],"h1":"Idaho law sets clock times, not sunrise and sunset.","h2":"In Idaho, daylight hours for a licensed driver under 16 run from 5 a.m. to 10 p.m. local time.","p":"Right. Daylight hours are 5 a.m. to 10 p.m."},"es":{"q":"En Idaho, ¿cómo se definen las horas de luz del día para conductores menores de 16 años?","o":["Desde la salida hasta la puesta del sol","Desde media hora antes de la salida del sol hasta media hora después de la puesta del sol","De 6 a.m. a 6 p.m.","De 5 a.m. a 10 p.m."],"h1":"La ley de Idaho usa horas del reloj, no la salida y la puesta del sol.","h2":"En Idaho, las horas de luz del día para un conductor con licencia menor de 16 años van de 5 a.m. a 10 p.m., hora local.","p":"Correcto. Las horas de luz del día son de 5 a.m. a 10 p.m."},"zh":{"q":"在 Idaho，对 16 岁以下的司机来说，“白天时段”是怎样规定的？","o":["从日出到日落","从日出前半小时到日落后半小时","从早上 6 点到晚上 6 点","从早上 5 点到晚上 10 点"],"h1":"Idaho 法律规定的是钟点，不是日出和日落。","h2":"在 Idaho，16 岁以下、有驾照的司机的白天时段，是当地时间早上 5 点到晚上 10 点。","p":"对。白天时段是早上 5 点到晚上 10 点。"},"vi":{"q":"Ở Idaho, giờ ban ngày được tính thế nào cho người lái dưới 16 tuổi?","o":["Từ lúc mặt trời mọc đến lúc mặt trời lặn","Từ nửa giờ trước khi mặt trời mọc đến nửa giờ sau khi mặt trời lặn","Từ 6 a.m. đến 6 p.m.","Từ 5 a.m. đến 10 p.m."],"h1":"Luật Idaho dùng giờ đồng hồ, không dùng lúc mặt trời mọc và lặn.","h2":"Ở Idaho, giờ ban ngày cho người có bằng lái dưới 16 tuổi là từ 5 a.m. đến 10 p.m. theo giờ địa phương.","p":"Đúng. Giờ ban ngày là từ 5 a.m. đến 10 p.m."},"tl":{"q":"Sa Idaho, paano itinatakda ang daylight hours para sa mga driver na wala pang 16?","o":["Mula pagsikat hanggang paglubog ng araw","Mula kalahating oras bago sumikat ang araw hanggang kalahating oras pagkalubog ng araw","Mula 6 a.m. hanggang 6 p.m.","Mula 5 a.m. hanggang 10 p.m."],"h1":"Oras sa orasan ang itinatakda ng batas ng Idaho, hindi ang pagsikat at paglubog ng araw.","h2":"Sa Idaho, ang daylight hours para sa lisensyadong driver na wala pang 16 ay mula 5 a.m. hanggang 10 p.m. sa lokal na oras.","p":"Tama. Ang daylight hours ay 5 a.m. hanggang 10 p.m."},"ar":{"q":"في Idaho، كيف تُحدَّد ساعات النهار للسائقين الذين أعمارهم أقل من 16 سنة؟","o":["من شروق الشمس إلى غروبها","من نصف ساعة قبل الشروق إلى نصف ساعة بعد الغروب","من 6 a.m. إلى 6 p.m.","من 5 a.m. إلى 10 p.m."],"h1":"قانون Idaho يحدد ساعات على الساعة، لا شروق الشمس وغروبها.","h2":"في Idaho، ساعات النهار للسائق المرخّص الذي عمره أقل من 16 سنة هي من 5 a.m. إلى 10 p.m. بالتوقيت المحلي.","p":"صحيح. ساعات النهار من 5 a.m. إلى 10 p.m."},"ref":{"doc":"ID","page":16}},{"id":"id-012","scope":"ID","cat":"licensing","sign":null,"c":1,"en":{"q":"In Idaho, during the first six months of a license, how many passengers under 17 may a driver under 17 carry?","o":["None","One","Two","Three"],"h1":"The limit is the smallest number that is more than zero.","h2":"During the first six months, an Idaho driver under 17 may carry no more than one passenger under 17, not counting relatives.","p":"Correct. Only one passenger under 17."},"es":{"q":"En Idaho, durante los primeros seis meses de la licencia, ¿cuántos pasajeros menores de 17 años puede llevar un conductor menor de 17?","o":["Ninguno","Uno","Dos","Tres"],"h1":"El límite es el número más pequeño que es mayor que cero.","h2":"Durante los primeros seis meses, un conductor menor de 17 años en Idaho no puede llevar más de un pasajero menor de 17, sin contar a sus familiares.","p":"Correcto. Solo un pasajero menor de 17."},"zh":{"q":"在 Idaho，拿到驾照的头六个月里，17 岁以下的司机可以载几个 17 岁以下的乘客？","o":["一个都不可以","一个","两个","三个"],"h1":"这个限制是比零大的最小的数。","h2":"在头六个月里，Idaho 17 岁以下的司机最多只能载一个 17 岁以下的乘客，亲属不算在内。","p":"正确。只能载一个 17 岁以下的乘客。"},"vi":{"q":"Ở Idaho, trong sáu tháng đầu có bằng lái, người lái dưới 17 tuổi được chở bao nhiêu hành khách dưới 17 tuổi?","o":["Không ai","Một","Hai","Ba"],"h1":"Giới hạn là số nhỏ nhất lớn hơn không.","h2":"Trong sáu tháng đầu, người lái dưới 17 tuổi ở Idaho chỉ được chở tối đa một hành khách dưới 17 tuổi, không tính người thân.","p":"Chính xác. Chỉ một hành khách dưới 17 tuổi."},"tl":{"q":"Sa Idaho, sa unang anim na buwan ng lisensya, ilang pasaherong wala pang 17 ang puwedeng isakay ng driver na wala pang 17?","o":["Wala","Isa","Dalawa","Tatlo"],"h1":"Ang limitasyon ay ang pinakamaliit na numerong higit sa zero.","h2":"Sa unang anim na buwan, ang driver sa Idaho na wala pang 17 ay puwedeng magsakay ng hindi hihigit sa isang pasaherong wala pang 17, hindi kasama ang mga kamag-anak.","p":"Tama. Isang pasahero lang na wala pang 17."},"ar":{"q":"في Idaho، خلال الأشهر الستة الأولى من الرخصة، كم راكبًا عمره أقل من 17 سنة يمكن أن ينقل السائق الذي عمره أقل من 17 سنة؟","o":["ولا واحد","واحد","اثنان","ثلاثة"],"h1":"الحد هو أصغر عدد أكبر من صفر.","h2":"خلال الأشهر الستة الأولى، لا يجوز للسائق في Idaho الذي عمره أقل من 17 سنة أن ينقل أكثر من راكب واحد عمره أقل من 17 سنة، دون حساب الأقارب.","p":"صحيح. راكب واحد فقط عمره أقل من 17 سنة."},"ref":{"doc":"ID","page":16}},{"id":"id-013","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, which passenger does not count toward the one-passenger limit for a new driver under 17?","o":["A classmate","A teammate","A neighbor","The driver's brother or sister"],"h1":"The rule makes an exception for family.","h2":"In Idaho the one-passenger limit does not apply to passengers related to the driver by blood, adoption or marriage, such as a brother or sister.","p":"Right. Family members do not count."},"es":{"q":"En Idaho, ¿qué pasajero no cuenta para el límite de un pasajero de un conductor nuevo menor de 17 años?","o":["Un compañero de clase","Un compañero de equipo","Un vecino","El hermano o la hermana del conductor"],"h1":"La regla hace una excepción para la familia.","h2":"En Idaho el límite de un pasajero no se aplica a los pasajeros que son familiares del conductor por sangre, adopción o matrimonio, como un hermano o una hermana.","p":"Correcto. Los familiares no cuentan."},"zh":{"q":"在 Idaho，对 17 岁以下的新司机来说，哪个乘客不算在一名乘客的限制里？","o":["同班同学","队友","邻居","司机的兄弟或姐妹"],"h1":"这个规定对家人有例外。","h2":"在 Idaho，一名乘客的限制不适用于和司机有血缘、收养或婚姻关系的乘客，例如兄弟或姐妹。","p":"对。家人不算。"},"vi":{"q":"Ở Idaho, hành khách nào không bị tính vào giới hạn một hành khách đối với người mới lái dưới 17 tuổi?","o":["Một bạn cùng lớp","Một đồng đội","Một người hàng xóm","Anh chị em của người lái"],"h1":"Luật có ngoại lệ cho gia đình.","h2":"Ở Idaho, giới hạn một hành khách không áp dụng cho hành khách là người thân của người lái theo huyết thống, nhận nuôi hoặc hôn nhân, chẳng hạn anh chị em.","p":"Đúng. Người trong gia đình không bị tính."},"tl":{"q":"Sa Idaho, aling pasahero ang hindi binibilang sa limitasyong isang pasahero para sa bagong driver na wala pang 17?","o":["Isang kaklase","Isang kasama sa team","Isang kapitbahay","Ang kapatid ng driver"],"h1":"May exception ang patakaran para sa pamilya.","h2":"Sa Idaho, ang limitasyong isang pasahero ay hindi para sa mga pasaherong kamag-anak ng driver sa dugo, pag-aampon o kasal, gaya ng kapatid.","p":"Tama. Hindi binibilang ang mga kapamilya."},"ar":{"q":"في Idaho، أيّ راكب لا يُحسب ضمن حد الراكب الواحد للسائق الجديد الذي عمره أقل من 17 سنة؟","o":["زميل في الصف","زميل في الفريق","جار","أخو السائق أو أخته"],"h1":"القاعدة فيها استثناء للعائلة.","h2":"في Idaho لا ينطبق حد الراكب الواحد على الركاب الأقارب للسائق بالدم أو التبنّي أو الزواج، مثل الأخ أو الأخت.","p":"صحيح. أفراد العائلة لا يُحسبون."},"ref":{"doc":"ID","page":16}},{"id":"id-014","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, who must complete a driver training program to get a driver's license?","o":["Everyone, at any age","Only drivers over 65","Anyone under 17","Only drivers from another state"],"h1":"It depends on how young the applicant is.","h2":"In Idaho anyone under 17 must complete and pass an approved driver training program to get a driver's license.","p":"Correct. Under 17 needs driver training."},"es":{"q":"En Idaho, ¿quién debe completar un programa de educación vial para obtener la licencia de manejo?","o":["Todos, a cualquier edad","Solo los mayores de 65","Cualquier persona menor de 17 años","Solo los conductores de otro estado"],"h1":"Depende de qué tan joven sea la persona.","h2":"En Idaho toda persona menor de 17 años debe completar y aprobar un programa de educación vial aprobado para obtener la licencia de manejo.","p":"Correcto. Menor de 17 necesita educación vial."},"zh":{"q":"在 Idaho，谁必须完成驾驶培训课程才能拿到驾照？","o":["所有人，不管几岁","只有 65 岁以上的司机","任何 17 岁以下的人","只有从别的州来的司机"],"h1":"这要看申请人有多年轻。","h2":"在 Idaho，任何 17 岁以下的人都必须完成并通过经过批准的驾驶培训课程，才能拿到驾照。","p":"正确。17 岁以下需要驾驶培训。"},"vi":{"q":"Ở Idaho, ai phải hoàn thành khóa đào tạo lái xe (driver training program) để có bằng lái?","o":["Mọi người, ở mọi lứa tuổi","Chỉ người lái trên 65 tuổi","Bất cứ ai dưới 17 tuổi","Chỉ người lái từ tiểu bang khác"],"h1":"Điều này tùy vào người nộp đơn trẻ đến mức nào.","h2":"Ở Idaho, bất cứ ai dưới 17 tuổi đều phải hoàn thành và đậu một khóa đào tạo lái xe được chấp thuận để có bằng lái.","p":"Chính xác. Dưới 17 tuổi cần học lái xe."},"tl":{"q":"Sa Idaho, sino ang dapat makatapos ng driver training program para makakuha ng driver's license?","o":["Lahat, anumang edad","Mga driver na higit sa 65 lang","Sinumang wala pang 17","Mga driver mula sa ibang estado lang"],"h1":"Depende ito sa kung gaano kabata ang aplikante.","h2":"Sa Idaho, sinumang wala pang 17 ay dapat makatapos at pumasa sa isang aprubadong driver training program para makakuha ng driver's license.","p":"Tama. Ang wala pang 17 ay kailangan ng driver training."},"ar":{"q":"في Idaho، مَن يجب أن يُكمل برنامج تدريب على القيادة (driver training program) للحصول على رخصة القيادة؟","o":["الجميع، في أي عمر","السائقون فوق 65 سنة فقط","أي شخص عمره أقل من 17 سنة","السائقون من ولاية أخرى فقط"],"h1":"الأمر يعتمد على صغر سنّ المتقدّم.","h2":"في Idaho يجب على كل مَن عمره أقل من 17 سنة أن يُكمل برنامج تدريب على القيادة معتمدًا وينجح فيه للحصول على رخصة القيادة.","p":"صحيح. مَن عمره أقل من 17 سنة يحتاج إلى تدريب على القيادة."},"ref":{"doc":"ID","page":19}},{"id":"id-015","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, how many hours of classroom instruction are in an approved driver training program?","o":["30 hours","6 hours","12 hours","50 hours"],"h1":"It is five times the hours of behind-the-wheel driving, which are 6.","h2":"An approved Idaho driver training program has 30 hours of classroom instruction, plus 6 hours of observation and 6 hours behind the wheel.","p":"Right. Thirty hours in the classroom."},"es":{"q":"En Idaho, ¿cuántas horas de clase en el aula tiene un programa de educación vial aprobado?","o":["30 horas","6 horas","12 horas","50 horas"],"h1":"Es cinco veces las horas de manejo con el instructor, que son 6.","h2":"Un programa de educación vial aprobado en Idaho tiene 30 horas de clase en el aula, además de 6 horas de observación y 6 horas al volante.","p":"Correcto. Treinta horas en el aula."},"zh":{"q":"在 Idaho，经过批准的驾驶培训课程有多少小时课堂教学？","o":["30 小时","6 小时","12 小时","50 小时"],"h1":"它是实际上车驾驶时间（6 小时）的五倍。","h2":"Idaho 经过批准的驾驶培训课程有 30 小时课堂教学，另外还有 6 小时观察和 6 小时实际驾驶。","p":"对。课堂里三十个小时。"},"vi":{"q":"Ở Idaho, một khóa đào tạo lái xe được chấp thuận có bao nhiêu giờ học trên lớp?","o":["30 giờ","6 giờ","12 giờ","50 giờ"],"h1":"Gấp năm lần số giờ lái thực tế, là 6 giờ.","h2":"Một khóa đào tạo lái xe được chấp thuận ở Idaho có 30 giờ học trên lớp, cộng thêm 6 giờ quan sát và 6 giờ lái thực tế.","p":"Đúng. Ba mươi giờ học trên lớp."},"tl":{"q":"Sa Idaho, ilang oras ng pag-aaral sa classroom ang nasa isang aprubadong driver training program?","o":["30 oras","6 na oras","12 oras","50 oras"],"h1":"Limang beses ito ng oras ng aktuwal na pagmamaneho, na 6.","h2":"Ang isang aprubadong driver training program sa Idaho ay may 30 oras ng pag-aaral sa classroom, dagdag ang 6 na oras ng pagmamasid at 6 na oras ng aktuwal na pagmamaneho.","p":"Tama. Tatlumpung oras sa classroom."},"ar":{"q":"في Idaho، كم ساعة من الدروس في الصف يتضمن برنامج التدريب على القيادة المعتمد؟","o":["30 ساعة","6 ساعات","12 ساعة","50 ساعة"],"h1":"هي خمسة أضعاف ساعات القيادة الفعلية خلف المقود، وهي 6.","h2":"برنامج التدريب على القيادة المعتمد في Idaho فيه 30 ساعة من الدروس في الصف، بالإضافة إلى 6 ساعات من المراقبة و6 ساعات من القيادة الفعلية خلف المقود.","p":"صحيح. ثلاثون ساعة في الصف."},"ref":{"doc":"ID","page":19}},{"id":"id-016","scope":"ID","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Idaho, when may a driver hold a phone in their hand to use it?","o":["While stopped at a red light","While stopped at a stop sign","When parked out of the travel lanes","While driving slowly"],"h1":"Being stopped in traffic is not enough.","h2":"Idaho's hands-free law covers you even at a red light or stop sign; you may hold the phone only when the vehicle is stopped outside the travel lanes, or in an emergency.","p":"Correct. Park out of traffic first."},"es":{"q":"En Idaho, ¿cuándo puede un conductor tener el teléfono en la mano para usarlo?","o":["Cuando está detenido en un semáforo en rojo","Cuando está detenido en una señal de alto","Cuando está estacionado fuera de los carriles de circulación","Cuando maneja despacio"],"h1":"Estar detenido en el tráfico no es suficiente.","h2":"La ley de manos libres de Idaho se aplica incluso en un semáforo en rojo o en una señal de alto; usted solo puede tener el teléfono en la mano cuando el vehículo está detenido fuera de los carriles de circulación, o en una emergencia.","p":"Correcto. Primero estaciónese fuera del tráfico."},"zh":{"q":"在 Idaho，司机什么时候可以手拿手机使用？","o":["在红灯前停着的时候","在停车标志前停着的时候","车停在行车道以外的时候","开得很慢的时候"],"h1":"在车流里停下来还不够。","h2":"Idaho 的免提法就算在红灯或停车标志前也适用；只有车停在行车道以外，或者有紧急情况时，你才可以手拿手机。","p":"正确。先把车停到车流以外。"},"vi":{"q":"Ở Idaho, khi nào người lái được cầm điện thoại trên tay để sử dụng?","o":["Khi dừng ở đèn đỏ","Khi dừng ở biển báo STOP","Khi đậu xe bên ngoài làn đường lưu thông","Khi đang lái chậm"],"h1":"Dừng lại giữa dòng xe thì chưa đủ.","h2":"Luật rảnh tay (hands-free law) của Idaho áp dụng cả khi bạn dừng ở đèn đỏ hoặc biển báo STOP; bạn chỉ được cầm điện thoại khi xe dừng bên ngoài làn đường lưu thông, hoặc trong trường hợp khẩn cấp.","p":"Chính xác. Hãy đậu xe ra khỏi dòng xe trước."},"tl":{"q":"Sa Idaho, kailan puwedeng hawakan ng driver ang telepono sa kamay para gamitin ito?","o":["Habang nakahinto sa pulang ilaw","Habang nakahinto sa stop sign","Kapag naka-park sa labas ng mga travel lane","Habang mabagal na nagmamaneho"],"h1":"Hindi sapat ang nakahinto sa trapiko.","h2":"Saklaw ka ng hands-free law ng Idaho kahit nasa pulang ilaw o stop sign; puwede mo lang hawakan ang telepono kapag nakahinto ang sasakyan sa labas ng mga travel lane, o sa emergency.","p":"Tama. Mag-park muna sa labas ng trapiko."},"ar":{"q":"في Idaho، متى يجوز للسائق أن يمسك الهاتف بيده لاستخدامه؟","o":["عند التوقف عند إشارة حمراء","عند التوقف عند علامة STOP","عند الوقوف خارج مسارات السير","أثناء القيادة ببطء"],"h1":"التوقف وسط حركة المرور لا يكفي.","h2":"قانون عدم استخدام اليدين (hands-free law) في Idaho يشملك حتى عند الإشارة الحمراء أو علامة STOP؛ يجوز لك أن تمسك الهاتف فقط عندما تكون السيارة متوقفة خارج مسارات السير، أو في حالة طارئة.","p":"صحيح. قِف خارج حركة المرور أولًا."},"ref":{"doc":"ID","page":null}},{"id":"id-017","scope":"ID","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Idaho, how may a driver start a phone call while driving?","o":["By typing the full number","With one touch or a voice command","By holding the phone to the ear","Calls are never allowed"],"h1":"The law allows the smallest possible action.","h2":"Idaho's hands-free law lets a driver start or answer a call with one touch or a voice command.","p":"Right. One touch or your voice."},"es":{"q":"En Idaho, ¿cómo puede un conductor hacer una llamada mientras maneja?","o":["Marcando el número completo","Con un solo toque o un comando de voz","Sosteniendo el teléfono junto al oído","Las llamadas nunca se permiten"],"h1":"La ley permite la acción más pequeña posible.","h2":"La ley de manos libres de Idaho permite hacer o contestar una llamada con un solo toque o con un comando de voz.","p":"Correcto. Un toque o su voz."},"zh":{"q":"在 Idaho，司机开车时可以怎样开始打电话？","o":["输入完整的号码","按一下或用语音命令","把手机拿到耳朵旁边","任何时候都不能打电话"],"h1":"法律只允许最小的动作。","h2":"Idaho 的免提法允许司机按一下或用语音命令来打电话或接电话。","p":"对。按一下或用你的声音。"},"vi":{"q":"Ở Idaho, người lái có thể bắt đầu cuộc gọi điện thoại khi đang lái xe bằng cách nào?","o":["Bằng cách bấm toàn bộ số điện thoại","Bằng một lần chạm hoặc lệnh giọng nói","Bằng cách cầm điện thoại áp vào tai","Không bao giờ được gọi điện"],"h1":"Luật cho phép thao tác nhỏ nhất có thể.","h2":"Luật rảnh tay của Idaho cho phép người lái bắt đầu hoặc trả lời cuộc gọi bằng một lần chạm hoặc lệnh giọng nói.","p":"Đúng. Một lần chạm hoặc giọng nói của bạn."},"tl":{"q":"Sa Idaho, paano puwedeng magsimula ng tawag ang driver habang nagmamaneho?","o":["Sa pag-type ng buong numero","Sa isang pindot o voice command","Sa paghawak ng telepono sa tainga","Hindi kailanman pinapayagan ang tawag"],"h1":"Pinapayagan ng batas ang pinakamaliit na posibleng kilos.","h2":"Pinapayagan ng hands-free law ng Idaho ang driver na magsimula o sumagot ng tawag sa isang pindot o voice command.","p":"Tama. Isang pindot o ang boses mo."},"ar":{"q":"في Idaho، كيف يمكن للسائق أن يبدأ مكالمة هاتفية أثناء القيادة؟","o":["بكتابة الرقم كاملًا","بلمسة واحدة أو بأمر صوتي","بإمساك الهاتف على الأذن","المكالمات غير مسموحة أبدًا"],"h1":"القانون يسمح بأصغر حركة ممكنة.","h2":"قانون عدم استخدام اليدين في Idaho يسمح للسائق أن يبدأ مكالمة أو يرد عليها بلمسة واحدة أو بأمر صوتي.","p":"صحيح. لمسة واحدة أو صوتك."},"ref":{"doc":"ID","page":null}},{"id":"id-018","scope":"ID","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Idaho, what is the fine for a first hands-free law violation, before court costs?","o":["$75","$25","$300","$1,000"],"h1":"The fine doubles for a second offense, to $150.","h2":"A first violation of Idaho's hands-free law is a $75 fine, plus court costs.","p":"Correct. The first fine is $75."},"es":{"q":"En Idaho, ¿cuál es la multa por una primera infracción de la ley de manos libres, sin contar los costos del tribunal?","o":["$75","$25","$300","$1,000"],"h1":"La multa se duplica en la segunda infracción, a $150.","h2":"Una primera infracción de la ley de manos libres en Idaho tiene una multa de $75, más los costos del tribunal.","p":"Correcto. La primera multa es de $75."},"zh":{"q":"在 Idaho，第一次违反免提法，不算法庭费用，罚款多少？","o":["$75","$25","$300","$1,000"],"h1":"第二次违规时罚款加倍，变成 $150。","h2":"第一次违反 Idaho 的免提法，罚款 $75，另外还要付法庭费用。","p":"正确。第一次罚款是 $75。"},"vi":{"q":"Ở Idaho, tiền phạt cho lần đầu vi phạm luật rảnh tay là bao nhiêu, chưa tính án phí?","o":["$75","$25","$300","$1,000"],"h1":"Tiền phạt tăng gấp đôi ở lần vi phạm thứ hai, thành $150.","h2":"Lần đầu vi phạm luật rảnh tay của Idaho bị phạt $75, cộng thêm án phí.","p":"Chính xác. Tiền phạt lần đầu là $75."},"tl":{"q":"Sa Idaho, magkano ang multa sa unang paglabag sa hands-free law, bago ang court costs?","o":["$75","$25","$300","$1,000"],"h1":"Dumodoble ang multa sa ikalawang paglabag, hanggang $150.","h2":"Ang unang paglabag sa hands-free law ng Idaho ay may multang $75, dagdag ang court costs.","p":"Tama. Ang unang multa ay $75."},"ar":{"q":"في Idaho، ما غرامة المخالفة الأولى لقانون عدم استخدام اليدين، قبل رسوم المحكمة؟","o":["$75","$25","$300","$1,000"],"h1":"الغرامة تتضاعف في المخالفة الثانية، فتصبح $150.","h2":"المخالفة الأولى لقانون عدم استخدام اليدين في Idaho غرامتها $75، بالإضافة إلى رسوم المحكمة.","p":"صحيح. الغرامة الأولى $75."},"ref":{"doc":"ID","page":null}},{"id":"id-019","scope":"ID","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Idaho, which stopped vehicle with flashing lights is covered by the Move Over law?","o":["Only police cars","Only ambulances","Only fire trucks","Tow trucks and highway incident response vehicles too"],"h1":"Since 2019 the law protects more than just emergency vehicles.","h2":"Idaho's Move Over law covers police and emergency vehicles, and since 2019 also tow trucks and highway incident response vehicles.","p":"Right. Tow trucks are covered too."},"es":{"q":"En Idaho, ¿qué vehículo detenido con luces intermitentes está cubierto por la ley Move Over?","o":["Solo los carros de policía","Solo las ambulancias","Solo los camiones de bomberos","También las grúas y los vehículos de respuesta a incidentes en la carretera"],"h1":"Desde 2019 la ley protege a más que solo los vehículos de emergencia.","h2":"La ley Move Over de Idaho cubre a la policía y los vehículos de emergencia, y desde 2019 también a las grúas y los vehículos de respuesta a incidentes en la carretera.","p":"Correcto. Las grúas también están cubiertas."},"zh":{"q":"在 Idaho，哪种停着、闪着灯的车辆受 Move Over 法保护？","o":["只有警车","只有救护车","只有消防车","也包括拖车和公路事故处理车辆"],"h1":"从 2019 年起，这条法律保护的不只是急救车辆。","h2":"Idaho 的 Move Over 法保护警车和急救车辆，从 2019 年起也保护拖车和公路事故处理车辆。","p":"对。拖车也受保护。"},"vi":{"q":"Ở Idaho, xe nào đang dừng và có đèn nhấp nháy được bảo vệ bởi luật Move Over (luật tránh sang làn khác)?","o":["Chỉ xe cảnh sát","Chỉ xe cứu thương","Chỉ xe cứu hỏa","Cả xe kéo và xe ứng phó sự cố trên xa lộ"],"h1":"Từ năm 2019, luật bảo vệ nhiều hơn chỉ xe khẩn cấp.","h2":"Luật Move Over của Idaho áp dụng cho xe cảnh sát và xe khẩn cấp, và từ năm 2019 cũng áp dụng cho xe kéo và xe ứng phó sự cố trên xa lộ.","p":"Đúng. Xe kéo cũng được bảo vệ."},"tl":{"q":"Sa Idaho, aling nakahintong sasakyan na may kumikislap na ilaw ang saklaw ng Move Over law?","o":["Mga sasakyan ng pulis lang","Mga ambulansya lang","Mga trak ng bumbero lang","Pati mga tow truck at highway incident response vehicle"],"h1":"Mula 2019, higit pa sa mga emergency vehicle ang pinoprotektahan ng batas.","h2":"Saklaw ng Move Over law ng Idaho ang mga sasakyan ng pulis at emergency vehicle, at mula 2019 pati ang mga tow truck at highway incident response vehicle.","p":"Tama. Saklaw din ang mga tow truck."},"ar":{"q":"في Idaho، أيّ مركبة متوقفة وأضواؤها تومض يشملها قانون الابتعاد (Move Over law)؟","o":["سيارات الشرطة فقط","سيارات الإسعاف فقط","سيارات الإطفاء فقط","شاحنات السحب ومركبات الاستجابة لحوادث الطرق السريعة أيضًا"],"h1":"منذ 2019 يحمي القانون أكثر من مركبات الطوارئ فقط.","h2":"قانون Move Over في Idaho يشمل سيارات الشرطة ومركبات الطوارئ، ومنذ 2019 يشمل أيضًا شاحنات السحب ومركبات الاستجابة لحوادث الطرق السريعة.","p":"صحيح. شاحنات السحب مشمولة أيضًا."},"ref":{"doc":"ID","page":95}},{"id":"id-020","scope":"ID","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Idaho, what blood alcohol level is illegal for a driver under 21?","o":["0.08 or more","0.02 or more","0.05 or more","0.10 or more"],"h1":"It is far lower than the adult limit of 0.08.","h2":"In Idaho a driver under 21 breaks the law with a blood alcohol level of 0.02 or more.","p":"Correct. The limit under 21 is 0.02."},"es":{"q":"En Idaho, ¿qué nivel de alcohol en la sangre es ilegal para un conductor menor de 21 años?","o":["0.08 o más","0.02 o más","0.05 o más","0.10 o más"],"h1":"Es mucho más bajo que el límite para adultos, que es 0.08.","h2":"En Idaho un conductor menor de 21 años viola la ley con un nivel de alcohol en la sangre de 0.02 o más.","p":"Correcto. El límite para menores de 21 es 0.02."},"zh":{"q":"在 Idaho，对 21 岁以下的司机来说，血液酒精浓度多少是违法的？","o":["0.08 或更高","0.02 或更高","0.05 或更高","0.10 或更高"],"h1":"这比成年人的上限 0.08 低很多。","h2":"在 Idaho，21 岁以下的司机血液酒精浓度达到 0.02 或更高就是违法。","p":"正确。21 岁以下的上限是 0.02。"},"vi":{"q":"Ở Idaho, nồng độ cồn trong máu bao nhiêu là phạm luật đối với người lái dưới 21 tuổi?","o":["0.08 trở lên","0.02 trở lên","0.05 trở lên","0.10 trở lên"],"h1":"Thấp hơn nhiều so với giới hạn 0.08 của người lớn.","h2":"Ở Idaho, người lái dưới 21 tuổi phạm luật khi có nồng độ cồn trong máu từ 0.02 trở lên.","p":"Chính xác. Giới hạn cho người dưới 21 tuổi là 0.02."},"tl":{"q":"Sa Idaho, anong blood alcohol level ang ilegal para sa driver na wala pang 21?","o":["0.08 o higit pa","0.02 o higit pa","0.05 o higit pa","0.10 o higit pa"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon ng adult na 0.08.","h2":"Sa Idaho, lumalabag sa batas ang driver na wala pang 21 kapag ang blood alcohol level ay 0.02 o higit pa.","p":"Tama. Ang limitasyon para sa wala pang 21 ay 0.02."},"ar":{"q":"في Idaho، ما نسبة الكحول في الدم غير القانونية للسائق الذي عمره أقل من 21 سنة؟","o":["0.08 أو أكثر","0.02 أو أكثر","0.05 أو أكثر","0.10 أو أكثر"],"h1":"هي أقل بكثير من حد البالغين وهو 0.08.","h2":"في Idaho يخالف السائق الذي عمره أقل من 21 سنة القانون إذا كانت نسبة الكحول في دمه 0.02 أو أكثر.","p":"صحيح. الحد لمن عمره أقل من 21 سنة هو 0.02."},"ref":{"doc":"ID","page":131}},{"id":"id-021","scope":"ID","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Idaho, a driver under 21 is convicted for the first time of driving with an alcohol level of 0.02 or more but under 0.08. How long does the court suspend the license?","o":["A warning only","30 days","One year","Two weeks"],"h1":"It is a long time, a full twelve months.","h2":"In Idaho a first conviction for a driver under 21 with an alcohol level from 0.02 to under 0.08 brings a one-year license suspension, and the first 90 days allow no driving at all.","p":"Right. The suspension is one year."},"es":{"q":"En Idaho, un conductor menor de 21 años es condenado por primera vez por manejar con un nivel de alcohol de 0.02 o más, pero menor de 0.08. ¿Por cuánto tiempo suspende la licencia el tribunal?","o":["Solo una advertencia","30 días","Un año","Dos semanas"],"h1":"Es mucho tiempo, doce meses completos.","h2":"En Idaho, una primera condena de un conductor menor de 21 años con un nivel de alcohol de 0.02 a menos de 0.08 trae una suspensión de licencia de un año, y en los primeros 90 días no puede manejar de ninguna manera.","p":"Correcto. La suspensión es de un año."},"zh":{"q":"在 Idaho，一个 21 岁以下的司机第一次被判酒精浓度在 0.02 或以上、但低于 0.08 时开车。法庭会暂停驾照多久？","o":["只是警告","30 天","一年","两个星期"],"h1":"这是很长的时间，整整十二个月。","h2":"在 Idaho，21 岁以下的司机第一次被判酒精浓度在 0.02 到 0.08 以下时开车，驾照会被暂停一年，而且前 90 天完全不能开车。","p":"对。暂停一年。"},"vi":{"q":"Ở Idaho, một người lái dưới 21 tuổi bị kết tội lần đầu vì lái xe với nồng độ cồn từ 0.02 trở lên nhưng dưới 0.08. Tòa án đình chỉ bằng lái bao lâu?","o":["Chỉ cảnh cáo","30 ngày","Một năm","Hai tuần"],"h1":"Đó là thời gian dài, trọn mười hai tháng.","h2":"Ở Idaho, lần đầu bị kết tội đối với người lái dưới 21 tuổi có nồng độ cồn từ 0.02 đến dưới 0.08 sẽ bị đình chỉ bằng lái một năm, và trong 90 ngày đầu hoàn toàn không được lái xe.","p":"Đúng. Thời gian đình chỉ là một năm."},"tl":{"q":"Sa Idaho, ang driver na wala pang 21 ay na-convict sa unang pagkakataon dahil nagmaneho na may alcohol level na 0.02 o higit pa pero mas mababa sa 0.08. Gaano katagal sususpendihin ng korte ang lisensya?","o":["Babala lang","30 araw","Isang taon","Dalawang linggo"],"h1":"Mahabang panahon ito, buong labindalawang buwan.","h2":"Sa Idaho, ang unang conviction para sa driver na wala pang 21 na may alcohol level mula 0.02 hanggang mas mababa sa 0.08 ay may isang taong suspensyon ng lisensya, at sa unang 90 araw ay bawal talagang magmaneho.","p":"Tama. Isang taon ang suspensyon."},"ar":{"q":"في Idaho، أُدين سائق عمره أقل من 21 سنة لأول مرة بالقيادة بنسبة كحول 0.02 أو أكثر لكن أقل من 0.08. كم مدة توقيف الرخصة التي تحكم بها المحكمة؟","o":["إنذار فقط","30 يومًا","سنة واحدة","أسبوعان"],"h1":"هي مدة طويلة، اثنا عشر شهرًا كاملة.","h2":"في Idaho تؤدي الإدانة الأولى لسائق عمره أقل من 21 سنة بنسبة كحول من 0.02 إلى أقل من 0.08 إلى توقيف الرخصة سنة واحدة، وفي أول 90 يومًا لا يُسمح بالقيادة أبدًا.","p":"صحيح. مدة التوقيف سنة واحدة."},"ref":{"doc":"ID","page":null}},{"id":"id-022","scope":"ID","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Idaho, when must you report a crash to the police?","o":["Only when someone is killed","Only when a car must be towed","When someone is hurt or damage is more than $1,500","Only when damage is more than $5,000"],"h1":"Think of both people and property. The dollar amount is fairly low.","h2":"In Idaho, you must report a crash to the police when someone is hurt or the property damage is more than $1,500.","p":"Right. Injury or more than $1,500 in damage means a police report."},"es":{"q":"En Idaho, ¿cuándo debe usted reportar un choque a la policía?","o":["Solo cuando alguien muere","Solo cuando hay que remolcar un carro","Cuando alguien sale herido o el daño es de más de $1,500","Solo cuando el daño es de más de $5,000"],"h1":"Piense en las personas y en los bienes. La cantidad de dinero es bastante baja.","h2":"En Idaho, usted debe reportar un choque a la policía cuando alguien sale herido o el daño a la propiedad es de más de $1,500.","p":"Correcto. Una lesión o un daño de más de $1,500 significa un reporte a la policía."},"zh":{"q":"在 Idaho，什么时候必须向警察报告车祸？","o":["只有在有人死亡时","只有在车子需要拖走时","有人受伤或损失超过 $1,500 时","只有在损失超过 $5,000 时"],"h1":"想一想人，也想一想财物。这个金额相当低。","h2":"在 Idaho，当有人受伤或财物损失超过 $1,500 时，你必须向警察报告车祸。","p":"对。有人受伤或损失超过 $1,500，就要向警察报告。"},"vi":{"q":"Ở Idaho, khi nào bạn phải báo cáo tai nạn cho cảnh sát?","o":["Chỉ khi có người chết","Chỉ khi phải kéo xe đi","Khi có người bị thương hoặc thiệt hại hơn $1,500","Chỉ khi thiệt hại hơn $5,000"],"h1":"Hãy nghĩ đến cả con người lẫn tài sản. Số tiền khá thấp.","h2":"Ở Idaho, bạn phải báo cáo tai nạn cho cảnh sát khi có người bị thương hoặc thiệt hại tài sản hơn $1,500.","p":"Đúng. Có người bị thương hoặc thiệt hại hơn $1,500 thì phải báo cảnh sát."},"tl":{"q":"Sa Idaho, kailan mo dapat i-report sa pulis ang isang banggaan?","o":["Kapag may namatay lang","Kapag kailangang i-tow ang sasakyan lang","Kapag may nasaktan o ang pinsala ay higit sa $1,500","Kapag ang pinsala ay higit sa $5,000 lang"],"h1":"Isipin ang mga tao at ang mga ari-arian. Medyo mababa ang halaga ng pera.","h2":"Sa Idaho, dapat mong i-report sa pulis ang banggaan kapag may nasaktan o ang pinsala sa ari-arian ay higit sa $1,500.","p":"Tama. Kapag may nasaktan o higit sa $1,500 ang pinsala, kailangan ng police report."},"ar":{"q":"في Idaho، متى يجب أن تبلّغ الشرطة عن حادث؟","o":["فقط عندما يموت شخص","فقط عندما يجب سحب السيارة","عندما يُصاب شخص أو يكون الضرر أكثر من $1,500","فقط عندما يكون الضرر أكثر من $5,000"],"h1":"فكّر في الناس وفي الممتلكات معًا. المبلغ منخفض نوعًا ما.","h2":"في Idaho، يجب أن تبلّغ الشرطة عن الحادث عندما يُصاب شخص أو يكون الضرر في الممتلكات أكثر من $1,500.","p":"صحيح. الإصابة أو الضرر الذي يزيد على $1,500 يعني تقريرًا للشرطة."},"ref":{"doc":"ID","page":121}},{"id":"id-023","scope":"ID","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Idaho, you have a minor crash on an interstate and no one is hurt. What does the Quick Clearance law say to do with your car?","o":["Move it safely to the shoulder, median or emergency lane","Leave it exactly where it stopped until police arrive","Leave it in the lane with the hazard lights on","Drive away and call the police from home"],"h1":"The goal is to keep traffic moving and prevent a second crash.","h2":"In Idaho, if a crash on an interstate or major divided highway causes no injury or death, you must safely move your car to the shoulder, median or emergency lane.","p":"Right. Clear the lane when no one is hurt."},"es":{"q":"En Idaho, usted tiene un choque leve en una autopista interestatal y nadie sale herido. ¿Qué dice la ley Quick Clearance que debe hacer con su carro?","o":["Moverlo con cuidado al acotamiento, la mediana o el carril de emergencia","Dejarlo exactamente donde se detuvo hasta que llegue la policía","Dejarlo en el carril con las luces de emergencia encendidas","Irse y llamar a la policía desde su casa"],"h1":"El objetivo es que el tráfico siga avanzando y evitar otro choque.","h2":"En Idaho, si un choque en una autopista interestatal o una carretera dividida principal no causa heridos ni muertes, usted debe mover su carro con cuidado al acotamiento, la mediana o el carril de emergencia.","p":"Correcto. Despeje el carril cuando nadie está herido."},"zh":{"q":"在 Idaho，你在州际公路上发生了小车祸，没有人受伤。Quick Clearance 法律说你应该怎么处理你的车？","o":["安全地把车移到路肩、中央隔离带或紧急车道","在警察到来之前，把车留在停下的地方不动","打开危险警示灯，把车留在车道上","开车离开，回家后再打电话给警察"],"h1":"目的是让交通保持畅通，防止发生第二次车祸。","h2":"在 Idaho，如果在州际公路或主要分隔公路上发生的车祸没有造成受伤或死亡，你必须把车安全地移到路肩、中央隔离带或紧急车道。","p":"对。没有人受伤时，要把车道让出来。"},"vi":{"q":"Ở Idaho, bạn gặp một tai nạn nhỏ trên xa lộ liên bang và không ai bị thương. Luật Quick Clearance nói bạn phải làm gì với xe của mình?","o":["Di chuyển xe an toàn vào lề đường, dải phân cách hoặc làn khẩn cấp","Để xe đúng chỗ nó dừng cho đến khi cảnh sát đến","Để xe trong làn đường và bật đèn cảnh báo","Lái xe đi và gọi cảnh sát từ nhà"],"h1":"Mục đích là giữ cho xe cộ tiếp tục di chuyển và tránh tai nạn thứ hai.","h2":"Ở Idaho, nếu tai nạn trên xa lộ liên bang hoặc đường lớn có dải phân cách không làm ai bị thương hay chết, bạn phải di chuyển xe an toàn vào lề đường, dải phân cách hoặc làn khẩn cấp.","p":"Đúng. Khi không ai bị thương, hãy dọn xe khỏi làn đường."},"tl":{"q":"Sa Idaho, nagkaroon ka ng maliit na banggaan sa interstate at walang nasaktan. Ano ang sinasabi ng Quick Clearance law na gawin mo sa iyong kotse?","o":["Ilipat ito nang ligtas sa shoulder, median o emergency lane","Iwan ito kung saan mismo ito huminto hanggang dumating ang pulis","Iwan ito sa lane nang nakabukas ang hazard lights","Umalis at tawagan ang pulis mula sa bahay"],"h1":"Ang layunin ay panatilihing umaandar ang trapiko at maiwasan ang ikalawang banggaan.","h2":"Sa Idaho, kung ang banggaan sa interstate o malaking divided highway ay walang nasaktan o namatay, dapat mong ilipat nang ligtas ang iyong kotse sa shoulder, median o emergency lane.","p":"Tama. Alisin ang kotse sa lane kapag walang nasaktan."},"ar":{"q":"في Idaho، وقع لك حادث بسيط على طريق سريع بين الولايات ولم يُصب أحد. ماذا يقول قانون Quick Clearance أن تفعل بسيارتك؟","o":["انقلها بأمان إلى كتف الطريق أو الجزيرة الوسطى أو حارة الطوارئ","اتركها في مكانها تمامًا حتى تصل الشرطة","اتركها في الحارة مع تشغيل أضواء التحذير","ابتعد بالسيارة واتصل بالشرطة من البيت"],"h1":"الهدف هو أن تستمر حركة المرور وأن تمنع حادثًا ثانيًا.","h2":"في Idaho، إذا وقع حادث على طريق سريع بين الولايات أو طريق رئيسي مقسوم ولم يسبب إصابة أو وفاة، يجب أن تنقل سيارتك بأمان إلى كتف الطريق أو الجزيرة الوسطى أو حارة الطوارئ.","p":"صحيح. أخلِ الحارة عندما لا يُصاب أحد."},"ref":{"doc":"ID","page":121}},{"id":"id-024","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, what happens to a driver who gets 12 to 17 points in 12 months?","o":["Only a warning letter","A 6-month suspension","A 90-day suspension","A 30-day suspension"],"h1":"A warning letter comes at 8 points. This is the next step up.","h2":"In Idaho, a driver who gets 12 to 17 points in any 12 months has the license suspended for 30 days.","p":"Right. 12 to 17 points in a year means a 30-day suspension."},"es":{"q":"En Idaho, ¿qué le pasa a un conductor que acumula de 12 a 17 puntos en 12 meses?","o":["Solo una carta de advertencia","Una suspensión de 6 meses","Una suspensión de 90 días","Una suspensión de 30 días"],"h1":"La carta de advertencia llega con 8 puntos. Este es el siguiente paso.","h2":"En Idaho, a un conductor que acumula de 12 a 17 puntos en cualquier período de 12 meses le suspenden la licencia por 30 días.","p":"Correcto. De 12 a 17 puntos en un año significa una suspensión de 30 días."},"zh":{"q":"在 Idaho，司机在 12 个月内得到 12 到 17 分，会怎么样？","o":["只收到一封警告信","吊销驾照 6 个月","吊销驾照 90 天","吊销驾照 30 天"],"h1":"8 分时会收到警告信。这是下一步。","h2":"在 Idaho，司机在任何 12 个月内得到 12 到 17 分，驾照会被吊销 30 天。","p":"对。一年内 12 到 17 分，就是吊销驾照 30 天。"},"vi":{"q":"Ở Idaho, điều gì xảy ra với tài xế bị 12 đến 17 điểm trong 12 tháng?","o":["Chỉ nhận một thư cảnh cáo","Bị treo bằng 6 tháng","Bị treo bằng 90 ngày","Bị treo bằng 30 ngày"],"h1":"Thư cảnh cáo đến khi có 8 điểm. Đây là bước tiếp theo.","h2":"Ở Idaho, tài xế bị 12 đến 17 điểm trong bất kỳ 12 tháng nào sẽ bị treo bằng lái 30 ngày.","p":"Đúng. 12 đến 17 điểm trong một năm là bị treo bằng 30 ngày."},"tl":{"q":"Sa Idaho, ano ang mangyayari sa driver na nakakuha ng 12 hanggang 17 points sa loob ng 12 buwan?","o":["Isang warning letter lang","6 na buwang suspension","90 araw na suspension","30 araw na suspension"],"h1":"Ang warning letter ay dumarating sa 8 points. Ito ang susunod na hakbang.","h2":"Sa Idaho, ang driver na nakakuha ng 12 hanggang 17 points sa anumang 12 buwan ay masususpinde ang lisensya nang 30 araw.","p":"Tama. 12 hanggang 17 points sa isang taon ay 30 araw na suspension."},"ar":{"q":"في Idaho، ماذا يحدث للسائق الذي يحصل على 12 إلى 17 نقطة خلال 12 شهرًا؟","o":["رسالة تحذير فقط","إيقاف الرخصة 6 أشهر","إيقاف الرخصة 90 يومًا","إيقاف الرخصة 30 يومًا"],"h1":"رسالة التحذير تأتي عند 8 نقاط. هذه هي الخطوة التالية.","h2":"في Idaho، السائق الذي يحصل على 12 إلى 17 نقطة خلال أي 12 شهرًا تُوقف رخصته 30 يومًا.","p":"صحيح. من 12 إلى 17 نقطة في سنة تعني إيقاف الرخصة 30 يومًا."},"ref":{"doc":"ID","page":123}},{"id":"id-025","scope":"ID","cat":"licensing","sign":null,"c":1,"en":{"q":"In Idaho, how many points can an approved defensive driving course remove from your record?","o":["All of them","Up to 3 points","Up to 6 points","None, it only lowers the fine"],"h1":"The course helps, but only a little.","h2":"In Idaho, finishing an approved defensive driving course can remove up to 3 points from your record, once every three years.","p":"Right. The course removes up to 3 points."},"es":{"q":"En Idaho, ¿cuántos puntos puede quitar de su historial un curso de manejo defensivo aprobado?","o":["Todos","Hasta 3 puntos","Hasta 6 puntos","Ninguno, solo baja la multa"],"h1":"El curso ayuda, pero solo un poco.","h2":"En Idaho, terminar un curso de manejo defensivo aprobado puede quitar hasta 3 puntos de su historial, una vez cada tres años.","p":"Correcto. El curso quita hasta 3 puntos."},"zh":{"q":"在 Idaho，完成认可的防御性驾驶课程可以从你的记录中去掉多少分？","o":["全部","最多 3 分","最多 6 分","一分也不能，只能减少罚款"],"h1":"这个课程有帮助，但只是一点点。","h2":"在 Idaho，完成认可的防御性驾驶课程可以从你的记录中去掉最多 3 分，每三年一次。","p":"对。这个课程最多去掉 3 分。"},"vi":{"q":"Ở Idaho, một khóa học lái xe phòng vệ được chấp thuận có thể xóa bao nhiêu điểm khỏi hồ sơ của bạn?","o":["Tất cả","Tối đa 3 điểm","Tối đa 6 điểm","Không điểm nào, nó chỉ giảm tiền phạt"],"h1":"Khóa học có giúp, nhưng chỉ một chút.","h2":"Ở Idaho, hoàn thành một khóa học lái xe phòng vệ được chấp thuận có thể xóa tối đa 3 điểm khỏi hồ sơ của bạn, ba năm một lần.","p":"Đúng. Khóa học xóa tối đa 3 điểm."},"tl":{"q":"Sa Idaho, ilang points ang maaaring alisin sa iyong record ng isang aprubadong defensive driving course?","o":["Lahat","Hanggang 3 points","Hanggang 6 points","Wala, binababa lang nito ang multa"],"h1":"Nakakatulong ang course, pero kaunti lang.","h2":"Sa Idaho, ang pagtatapos ng aprubadong defensive driving course ay maaaring mag-alis ng hanggang 3 points sa iyong record, isang beses bawat tatlong taon.","p":"Tama. Nag-aalis ang course ng hanggang 3 points."},"ar":{"q":"في Idaho، كم نقطة يمكن أن تحذفها دورة قيادة دفاعية معتمدة من سجلك؟","o":["كل النقاط","حتى 3 نقاط","حتى 6 نقاط","لا شيء، فهي تخفض الغرامة فقط"],"h1":"الدورة تساعد، لكن قليلًا فقط.","h2":"في Idaho، إتمام دورة قيادة دفاعية معتمدة يمكن أن يحذف حتى 3 نقاط من سجلك، مرة واحدة كل ثلاث سنوات.","p":"صحيح. الدورة تحذف حتى 3 نقاط."},"ref":{"doc":"ID","page":123}},{"id":"id-026","scope":"ID","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Idaho, children up to what age must ride in an approved child safety seat?","o":["2 years or younger","4 years or younger","6 years or younger","10 years or younger"],"h1":"It covers children until they are about in first grade.","h2":"In Idaho, children 6 years old or younger must ride in an approved child safety seat.","p":"Right. Age 6 and under means a child safety seat."},"es":{"q":"En Idaho, ¿hasta qué edad los niños deben viajar en un asiento de seguridad infantil aprobado?","o":["2 años o menos","4 años o menos","6 años o menos","10 años o menos"],"h1":"Cubre a los niños hasta más o menos el primer grado.","h2":"En Idaho, los niños de 6 años o menos deben viajar en un asiento de seguridad infantil aprobado.","p":"Correcto. Los niños de 6 años o menos van en un asiento de seguridad."},"zh":{"q":"在 Idaho，多大以下的儿童必须坐在认可的儿童安全座椅里？","o":["2 岁或以下","4 岁或以下","6 岁或以下","10 岁或以下"],"h1":"大约到孩子上一年级的时候。","h2":"在 Idaho，6 岁或以下的儿童必须坐在认可的儿童安全座椅里。","p":"对。6 岁及以下要坐儿童安全座椅。"},"vi":{"q":"Ở Idaho, trẻ em đến bao nhiêu tuổi phải ngồi ghế an toàn trẻ em được chấp thuận?","o":["2 tuổi trở xuống","4 tuổi trở xuống","6 tuổi trở xuống","10 tuổi trở xuống"],"h1":"Luật áp dụng cho trẻ em đến khoảng lúc vào lớp một.","h2":"Ở Idaho, trẻ em 6 tuổi trở xuống phải ngồi ghế an toàn trẻ em được chấp thuận.","p":"Đúng. Từ 6 tuổi trở xuống phải ngồi ghế an toàn trẻ em."},"tl":{"q":"Sa Idaho, hanggang anong edad dapat sumakay ang mga bata sa aprubadong child safety seat?","o":["2 taon o mas bata","4 na taon o mas bata","6 na taon o mas bata","10 taon o mas bata"],"h1":"Saklaw nito ang mga bata hanggang mga nasa unang baitang sila.","h2":"Sa Idaho, ang mga batang 6 na taon o mas bata ay dapat sumakay sa aprubadong child safety seat.","p":"Tama. Edad 6 pababa ay kailangan ng child safety seat."},"ar":{"q":"في Idaho، حتى أي عمر يجب أن يجلس الأطفال في مقعد أمان معتمد للأطفال؟","o":["سنتان أو أقل","4 سنوات أو أقل","6 سنوات أو أقل","10 سنوات أو أقل"],"h1":"يشمل الأطفال حتى يصلوا تقريبًا إلى الصف الأول.","h2":"في Idaho، يجب أن يجلس الأطفال الذين عمرهم 6 سنوات أو أقل في مقعد أمان معتمد للأطفال.","p":"صحيح. عمر 6 سنوات أو أقل يعني مقعد أمان للأطفال."},"ref":{"doc":"ID","page":41}},{"id":"id-027","scope":"ID","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Idaho, when must you turn on your headlights during the day?","o":["When you can see only 500 feet or less ahead","Only after 6 p.m.","Only on the interstate","Only when it is snowing"],"h1":"It depends on how far you can see, not on the clock.","h2":"In Idaho, you must turn on your headlights in the daytime when you can see only 500 feet or less, such as in fog, smoke, dust or rain.","p":"Right. 500 feet or less means headlights on."},"es":{"q":"En Idaho, ¿cuándo debe encender los faros durante el día?","o":["Cuando solo puede ver 500 pies o menos hacia adelante","Solo después de las 6 p.m.","Solo en la autopista interestatal","Solo cuando está nevando"],"h1":"Depende de qué tan lejos puede ver, no de la hora.","h2":"En Idaho, usted debe encender los faros de día cuando solo puede ver 500 pies o menos, por ejemplo con niebla, humo, polvo o lluvia.","p":"Correcto. Con 500 pies o menos de visibilidad, encienda los faros."},"zh":{"q":"在 Idaho，白天什么时候必须打开前灯？","o":["当你只能看到前方 500 英尺或更近时","只在下午 6 点以后","只在州际公路上","只在下雪时"],"h1":"这要看你能看多远，不是看时间。","h2":"在 Idaho，白天当你只能看到 500 英尺或更近时，例如在雾、烟、灰尘或雨中，你必须打开前灯。","p":"对。只能看到 500 英尺或更近时，就要开前灯。"},"vi":{"q":"Ở Idaho, khi nào bạn phải bật đèn pha vào ban ngày?","o":["Khi bạn chỉ nhìn thấy phía trước 500 feet hoặc ít hơn","Chỉ sau 6 giờ chiều","Chỉ trên xa lộ liên bang","Chỉ khi trời có tuyết"],"h1":"Điều này tùy vào việc bạn nhìn thấy xa bao nhiêu, không phải giờ giấc.","h2":"Ở Idaho, bạn phải bật đèn pha vào ban ngày khi bạn chỉ nhìn thấy 500 feet hoặc ít hơn, ví dụ khi có sương mù, khói, bụi hoặc mưa.","p":"Đúng. Nhìn thấy 500 feet hoặc ít hơn thì phải bật đèn pha."},"tl":{"q":"Sa Idaho, kailan mo dapat buksan ang headlights sa araw?","o":["Kapag 500 feet o mas malapit lang ang nakikita mo sa unahan","Pagkatapos lang ng 6 p.m.","Sa interstate lang","Kapag umuulan lang ng niyebe"],"h1":"Nakadepende ito sa kung gaano kalayo ang nakikita mo, hindi sa oras.","h2":"Sa Idaho, dapat mong buksan ang headlights sa araw kapag 500 feet o mas malapit lang ang nakikita mo, gaya ng sa hamog, usok, alikabok o ulan.","p":"Tama. 500 feet o mas malapit ay ibig sabihing bukas ang headlights."},"ar":{"q":"في Idaho، متى يجب أن تشغّل المصابيح الأمامية أثناء النهار؟","o":["عندما لا ترى أمامك إلا 500 قدم أو أقل","فقط بعد الساعة 6 مساءً","فقط على الطريق السريع بين الولايات","فقط عندما يتساقط الثلج"],"h1":"الأمر يعتمد على المسافة التي تراها، لا على الساعة.","h2":"في Idaho، يجب أن تشغّل المصابيح الأمامية في النهار عندما لا ترى إلا 500 قدم أو أقل، مثل وقت الضباب أو الدخان أو الغبار أو المطر.","p":"صحيح. 500 قدم أو أقل تعني تشغيل المصابيح الأمامية."},"ref":{"doc":"ID","page":110}},{"id":"id-028","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, what is the minimum vision needed to get a driver's license?","o":["20/20 in both eyes","20/30 in both eyes","20/40 in at least one eye","20/100 in at least one eye"],"h1":"Glasses or contact lenses may be used, and only one eye has to meet it.","h2":"In Idaho, you need at least 20/40 vision in at least one eye, with or without glasses or contact lenses.","p":"Right. The minimum is 20/40 in at least one eye."},"es":{"q":"En Idaho, ¿cuál es la visión mínima para obtener una licencia de conducir?","o":["20/20 en ambos ojos","20/30 en ambos ojos","20/40 en al menos un ojo","20/100 en al menos un ojo"],"h1":"Se pueden usar lentes o lentes de contacto, y solo un ojo tiene que cumplirlo.","h2":"En Idaho, necesita una visión de al menos 20/40 en al menos un ojo, con o sin lentes o lentes de contacto.","p":"Correcto. El mínimo es 20/40 en al menos un ojo."},"zh":{"q":"在 Idaho，考驾照最低需要什么视力？","o":["双眼都是 20/20","双眼都是 20/30","至少一只眼睛 20/40","至少一只眼睛 20/100"],"h1":"可以戴眼镜或隐形眼镜，只要一只眼睛达到要求就可以。","h2":"在 Idaho，你至少一只眼睛的视力需要达到 20/40，戴不戴眼镜或隐形眼镜都可以。","p":"对。最低要求是至少一只眼睛 20/40。"},"vi":{"q":"Ở Idaho, thị lực tối thiểu cần có để lấy bằng lái xe là bao nhiêu?","o":["20/20 ở cả hai mắt","20/30 ở cả hai mắt","20/40 ở ít nhất một mắt","20/100 ở ít nhất một mắt"],"h1":"Bạn có thể đeo kính hoặc kính áp tròng, và chỉ cần một mắt đạt yêu cầu.","h2":"Ở Idaho, bạn cần thị lực ít nhất 20/40 ở ít nhất một mắt, có hoặc không đeo kính hay kính áp tròng.","p":"Đúng. Mức tối thiểu là 20/40 ở ít nhất một mắt."},"tl":{"q":"Sa Idaho, ano ang pinakamababang paningin na kailangan para makakuha ng driver's license?","o":["20/20 sa dalawang mata","20/30 sa dalawang mata","20/40 sa kahit isang mata","20/100 sa kahit isang mata"],"h1":"Puwedeng gumamit ng salamin o contact lenses, at isang mata lang ang kailangang umabot dito.","h2":"Sa Idaho, kailangan mo ng hindi bababa sa 20/40 na paningin sa kahit isang mata, may salamin o contact lenses man o wala.","p":"Tama. Ang pinakamababa ay 20/40 sa kahit isang mata."},"ar":{"q":"في Idaho، ما أقل درجة نظر مطلوبة للحصول على رخصة القيادة؟","o":["20/20 في العينين كلتيهما","20/30 في العينين كلتيهما","20/40 في عين واحدة على الأقل","20/100 في عين واحدة على الأقل"],"h1":"يمكن استخدام النظارات أو العدسات اللاصقة، ويكفي أن تحقق عين واحدة الشرط.","h2":"في Idaho، تحتاج إلى نظر 20/40 على الأقل في عين واحدة على الأقل، بالنظارات أو العدسات اللاصقة أو بدونها.","p":"صحيح. الحد الأدنى هو 20/40 في عين واحدة على الأقل."},"ref":{"doc":"ID","page":32}},{"id":"id-029","scope":"ID","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Idaho, how close to a fire hydrant may you not park?","o":["Within 5 feet","Within 15 feet","Within 30 feet","Within 50 feet"],"h1":"Fire crews need room to reach the hydrant and connect a hose.","h2":"In Idaho, you may not park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a fire hydrant when you park."},"es":{"q":"En Idaho, ¿a qué distancia de un hidrante no puede estacionarse?","o":["A menos de 5 pies","A menos de 15 pies","A menos de 30 pies","A menos de 50 pies"],"h1":"Los bomberos necesitan espacio para llegar al hidrante y conectar la manguera.","h2":"En Idaho, no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese al menos a 15 pies de un hidrante al estacionarse."},"zh":{"q":"在 Idaho，在离消防栓多近的地方不可以停车？","o":["5 英尺以内","15 英尺以内","30 英尺以内","50 英尺以内"],"h1":"消防员需要空间走到消防栓并接上水管。","h2":"在 Idaho，你不可以在离消防栓 15 英尺以内的地方停车。","p":"对。停车时要离消防栓至少 15 英尺。"},"vi":{"q":"Ở Idaho, bạn không được đậu xe cách trụ nước chữa cháy gần bao nhiêu?","o":["Trong vòng 5 feet","Trong vòng 15 feet","Trong vòng 30 feet","Trong vòng 50 feet"],"h1":"Lính cứu hỏa cần chỗ để đến trụ nước và nối ống nước.","h2":"Ở Idaho, bạn không được đậu xe trong vòng 15 feet cách trụ nước chữa cháy.","p":"Đúng. Khi đậu xe, hãy cách trụ nước chữa cháy ít nhất 15 feet."},"tl":{"q":"Sa Idaho, gaano kalapit sa fire hydrant ka hindi puwedeng pumarada?","o":["Sa loob ng 5 feet","Sa loob ng 15 feet","Sa loob ng 30 feet","Sa loob ng 50 feet"],"h1":"Kailangan ng mga bumbero ng espasyo para malapitan ang hydrant at maikabit ang hose.","h2":"Sa Idaho, hindi ka puwedeng pumarada sa loob ng 15 feet mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 15 feet mula sa fire hydrant kapag pumarada ka."},"ar":{"q":"في Idaho، ما المسافة من صنبور إطفاء الحريق التي لا يجوز أن تركن سيارتك ضمنها؟","o":["ضمن 5 أقدام","ضمن 15 قدمًا","ضمن 30 قدمًا","ضمن 50 قدمًا"],"h1":"يحتاج رجال الإطفاء إلى مساحة للوصول إلى الصنبور وتوصيل الخرطوم.","h2":"في Idaho، لا يجوز أن تركن سيارتك ضمن 15 قدمًا من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بعد 15 قدمًا على الأقل من صنبور إطفاء الحريق عندما تركن سيارتك."},"ref":{"doc":"ID","page":81}},{"id":"id-030","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, a 35-year-old renews a regular Class D license. How long can the renewal last?","o":["Two or six years","Only one year","Only two years","Four or eight years"],"h1":"Drivers from 21 to 62 get to choose between two lengths.","h2":"In Idaho, a renewal lasts four or eight years, and drivers from 21 to 62 may choose the eight-year renewal.","p":"Right. A renewal lasts four or eight years."},"es":{"q":"En Idaho, una persona de 35 años renueva una licencia regular Clase D. ¿Cuánto tiempo puede durar la renovación?","o":["Dos o seis años","Solo un año","Solo dos años","Cuatro u ocho años"],"h1":"Los conductores de 21 a 62 años pueden elegir entre dos duraciones.","h2":"En Idaho, una renovación dura cuatro u ocho años, y los conductores de 21 a 62 años pueden elegir la renovación de ocho años.","p":"Correcto. Una renovación dura cuatro u ocho años."},"zh":{"q":"在 Idaho，一位 35 岁的人更新普通 Class D 驾照。更新后的驾照可以用多久？","o":["两年或六年","只有一年","只有两年","四年或八年"],"h1":"21 到 62 岁的司机可以在两种期限中选择。","h2":"在 Idaho，更新后的驾照有效期是四年或八年，21 到 62 岁的司机可以选择八年。","p":"对。更新后的驾照有效期是四年或八年。"},"vi":{"q":"Ở Idaho, một người 35 tuổi gia hạn bằng lái Class D thông thường. Bằng gia hạn có thể có hiệu lực bao lâu?","o":["Hai hoặc sáu năm","Chỉ một năm","Chỉ hai năm","Bốn hoặc tám năm"],"h1":"Tài xế từ 21 đến 62 tuổi được chọn giữa hai thời hạn.","h2":"Ở Idaho, bằng gia hạn có hiệu lực bốn hoặc tám năm, và tài xế từ 21 đến 62 tuổi có thể chọn gia hạn tám năm.","p":"Đúng. Bằng gia hạn có hiệu lực bốn hoặc tám năm."},"tl":{"q":"Sa Idaho, nagre-renew ng regular na Class D license ang isang 35 taong gulang. Gaano katagal puwedeng tumagal ang renewal?","o":["Dalawa o anim na taon","Isang taon lang","Dalawang taon lang","Apat o walong taon"],"h1":"Ang mga driver na 21 hanggang 62 taong gulang ay puwedeng pumili sa pagitan ng dalawang haba.","h2":"Sa Idaho, ang renewal ay tumatagal nang apat o walong taon, at ang mga driver na 21 hanggang 62 taong gulang ay puwedeng pumili ng walong taong renewal.","p":"Tama. Ang renewal ay tumatagal nang apat o walong taon."},"ar":{"q":"في Idaho، شخص عمره 35 عامًا يجدّد رخصة قيادة عادية من فئة Class D. كم يمكن أن تدوم الرخصة بعد التجديد؟","o":["سنتين أو ست سنوات","سنة واحدة فقط","سنتين فقط","أربع سنوات أو ثماني سنوات"],"h1":"السائقون من عمر 21 إلى 62 يمكنهم الاختيار بين مدتين.","h2":"في Idaho، يدوم التجديد أربع سنوات أو ثماني سنوات، ويمكن للسائقين من عمر 21 إلى 62 اختيار التجديد لثماني سنوات.","p":"صحيح. يدوم التجديد أربع سنوات أو ثماني سنوات."},"ref":{"doc":"ID","page":30}},{"id":"id-031","scope":"ID","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Idaho, you are taking an opened bottle of wine home in your car. Where must it be?","o":["In the trunk, or behind the last upright seat if there is no trunk","On the floor behind the driver's seat","In the glove box with the door closed","On the front seat, if the cork is pushed back in"],"h1":"It must be in a place no one in the seats can reach.","h2":"In Idaho, an open container of alcohol must be carried in the trunk, or behind the last upright seat if the vehicle has no trunk.","p":"Right. An open container goes in the trunk, or behind the last upright seat."},"es":{"q":"En Idaho, usted lleva a casa una botella de vino abierta en su auto. ¿Dónde debe ir?","o":["En la cajuela, o detrás del último asiento vertical si no hay cajuela","En el piso detrás del asiento del conductor","En la guantera con la puerta cerrada","En el asiento delantero, si se vuelve a poner el corcho"],"h1":"Debe ir en un lugar que nadie en los asientos pueda alcanzar.","h2":"En Idaho, un envase abierto de alcohol debe ir en la cajuela, o detrás del último asiento vertical si el vehículo no tiene cajuela.","p":"Correcto. Un envase abierto va en la cajuela, o detrás del último asiento vertical."},"zh":{"q":"在 Idaho，你开车把一瓶已经打开的葡萄酒带回家。它必须放在哪里？","o":["放在后备箱里；如果没有后备箱，就放在最后一排直立座椅的后面","放在驾驶座后面的地板上","放在手套箱里，并关上箱门","放在前座上，只要把软木塞塞回去"],"h1":"它必须放在座位上的人都拿不到的地方。","h2":"在 Idaho，打开的酒精饮料容器必须放在后备箱里；如果车辆没有后备箱，就必须放在最后一排直立座椅的后面。","p":"对。打开的酒要放在后备箱里，或放在最后一排直立座椅的后面。"},"vi":{"q":"Ở Idaho, bạn đang chở một chai rượu vang đã mở về nhà trong xe. Chai rượu phải được để ở đâu?","o":["Trong cốp xe, hoặc phía sau hàng ghế dựng thẳng cuối cùng nếu xe không có cốp","Trên sàn xe phía sau ghế tài xế","Trong hộc đựng găng tay với nắp đóng lại","Trên ghế trước, nếu nút chai đã được đẩy lại vào"],"h1":"Nó phải ở chỗ mà không ai ngồi trên ghế có thể với tới.","h2":"Ở Idaho, đồ uống có cồn đã mở phải được để trong cốp xe, hoặc phía sau hàng ghế dựng thẳng cuối cùng nếu xe không có cốp.","p":"Đúng. Đồ uống có cồn đã mở phải để trong cốp xe, hoặc phía sau hàng ghế dựng thẳng cuối cùng."},"tl":{"q":"Sa Idaho, nag-uuwi ka ng bukas na bote ng alak sa iyong kotse. Saan ito dapat nakalagay?","o":["Sa trunk, o sa likod ng huling nakatayong upuan kung walang trunk","Sa sahig sa likod ng upuan ng driver","Sa glove box na nakasara ang pinto","Sa upuan sa harap, kung naibalik na ang tapon"],"h1":"Dapat itong nasa lugar na hindi maaabot ng sinumang nakaupo.","h2":"Sa Idaho, ang bukas na lalagyan ng alak ay dapat dalhin sa trunk, o sa likod ng huling nakatayong upuan kung walang trunk ang sasakyan.","p":"Tama. Ang bukas na alak ay inilalagay sa trunk, o sa likod ng huling nakatayong upuan."},"ar":{"q":"في Idaho، أنت تنقل إلى البيت في سيارتك زجاجة نبيذ مفتوحة. أين يجب أن تكون؟","o":["في صندوق السيارة الخلفي، أو خلف آخر مقعد قائم إذا لم يكن هناك صندوق","على الأرض خلف مقعد السائق","في درج القفازات وبابه مغلق","على المقعد الأمامي، إذا أعيدت السدادة إلى مكانها"],"h1":"يجب أن تكون في مكان لا يستطيع أي شخص جالس في المقاعد الوصول إليه.","h2":"في Idaho، يجب نقل وعاء الكحول المفتوح في صندوق السيارة الخلفي، أو خلف آخر مقعد قائم إذا لم يكن للسيارة صندوق.","p":"صحيح. الوعاء المفتوح يوضع في صندوق السيارة الخلفي، أو خلف آخر مقعد قائم."},"ref":{"doc":"ID","page":130}},{"id":"id-032","scope":"ID","cat":"licensing","sign":null,"c":1,"en":{"q":"In Idaho, you fail the knowledge test. How long must you wait before you can take it again?","o":["You can retake it the same day","Three days","Two weeks","30 days"],"h1":"The wait is short, less than one week.","h2":"In Idaho, after failing the knowledge test you must wait three days to retest, and you pay the test fee again.","p":"Right. You wait three days and pay the fee again."},"es":{"q":"En Idaho, usted no aprueba el examen de conocimientos. ¿Cuánto debe esperar para volver a tomarlo?","o":["Puede repetirlo el mismo día","Tres días","Dos semanas","30 días"],"h1":"La espera es corta, menos de una semana.","h2":"En Idaho, si no aprueba el examen de conocimientos, debe esperar tres días para repetirlo y pagar otra vez la tarifa.","p":"Correcto. Espera tres días y paga la tarifa otra vez."},"ref":{"doc":"ID","page":32}},{"id":"id-033","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, you just moved to the state with a valid license from another state. How soon must you apply for an Idaho license?","o":["Within 7 days","Within 90 days","Only when your old license expires","Within 30 days"],"h1":"It is about one month.","h2":"New Idaho residents must apply for an Idaho driver's license within 30 days, even if the old license has not expired.","p":"Right. New residents have 30 days."},"es":{"q":"En Idaho, usted acaba de mudarse al estado con una licencia válida de otro estado. ¿En cuánto tiempo debe solicitar una licencia de Idaho?","o":["Dentro de 7 días","Dentro de 90 días","Solo cuando venza su licencia anterior","Dentro de 30 días"],"h1":"Es más o menos un mes.","h2":"Los nuevos residentes de Idaho deben solicitar una licencia de Idaho dentro de 30 días, aunque su licencia anterior no haya vencido.","p":"Correcto. Los nuevos residentes tienen 30 días."},"ref":{"doc":"ID","page":4}},{"id":"id-034","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, a 17-year-old practices with a Class D Instruction Permit. How old must the licensed driver with them be?","o":["At least 18","At least 16","At least 25","At least 30"],"h1":"The person must be an adult.","h2":"With a Class D Instruction Permit, the learner must drive with a licensed adult who is at least 18 years old.","p":"Right. The licensed driver must be at least 18."},"es":{"q":"En Idaho, un joven de 17 años practica con un permiso de instrucción Clase D. ¿Qué edad debe tener el conductor con licencia que lo acompaña?","o":["Al menos 18 años","Al menos 16 años","Al menos 25 años","Al menos 30 años"],"h1":"La persona debe ser adulta.","h2":"Con un permiso de instrucción Clase D, el aprendiz debe manejar con un adulto con licencia que tenga al menos 18 años.","p":"Correcto. El conductor con licencia debe tener al menos 18 años."},"ref":{"doc":"ID","page":16}},{"id":"id-035","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, a driver is 19 years old. When does their driver's license expire?","o":["On their 20th birthday","Ten years after it was issued","Five days after their 21st birthday","On their 25th birthday"],"h1":"Look for the license that says \"Under 21.\"","h2":"In Idaho, a license for a driver aged 18 to 20 says \"Under 21\" and expires five days after the 21st birthday.","p":"Right. It expires five days after the 21st birthday."},"es":{"q":"En Idaho, un conductor tiene 19 años. ¿Cuándo vence su licencia de manejo?","o":["En su cumpleaños número 20","Diez años después de emitirse","Cinco días después de cumplir 21 años","En su cumpleaños número 25"],"h1":"Piense en la licencia que dice \"Under 21\" (menor de 21).","h2":"En Idaho, la licencia de un conductor de 18 a 20 años dice \"Under 21\" y vence cinco días después de cumplir 21 años.","p":"Correcto. Vence cinco días después de cumplir 21 años."},"ref":{"doc":"ID","page":17}},{"id":"id-036","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, you will be out of state for a while when your license expires. How long can one extension last?","o":["Up to 30 days","Up to 3 months","Up to 5 years","Up to 12 months"],"h1":"Think of one full year.","h2":"An Idaho driver who is temporarily out of state can get an extension of up to 12 months for a $10 fee.","p":"Right. One extension lasts up to 12 months."},"es":{"q":"En Idaho, usted estará fuera del estado cuando venza su licencia. ¿Cuánto puede durar una prórroga?","o":["Hasta 30 días","Hasta 3 meses","Hasta 5 años","Hasta 12 meses"],"h1":"Piense en un año completo.","h2":"Un conductor de Idaho que está fuera del estado por un tiempo puede obtener una prórroga de hasta 12 meses por una tarifa de $10.","p":"Correcto. Una prórroga dura hasta 12 meses."},"ref":{"doc":"ID","page":31}},{"id":"id-037","scope":"ID","cat":"licensing","sign":null,"c":1,"en":{"q":"In Idaho, a licensed driver under 17 is convicted of a second moving violation. What happens?","o":["A warning letter","A 30-day suspension","A one-year suspension","A $50 fine and nothing more"],"h1":"The first conviction brings only a warning letter. The second is stronger.","h2":"Under Idaho's graduated license rules, a driver under 17 gets a 30-day suspension for a second moving violation conviction.","p":"Right. A second conviction means a 30-day suspension."},"es":{"q":"En Idaho, un conductor con licencia menor de 17 años recibe una segunda condena por una infracción de tránsito en movimiento. ¿Qué pasa?","o":["Una carta de advertencia","Una suspensión de 30 días","Una suspensión de un año","Una multa de $50 y nada más"],"h1":"La primera condena trae solo una carta de advertencia. La segunda es más fuerte.","h2":"Según las reglas de licencia gradual de Idaho, un conductor menor de 17 años recibe una suspensión de 30 días por una segunda condena por infracción en movimiento.","p":"Correcto. Una segunda condena significa una suspensión de 30 días."},"ref":{"doc":"ID","page":125}},{"id":"id-038","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, an adult fails a breath test for alcohol for the first time. How long is the administrative license suspension?","o":["90 days","7 days","Two years","Five years"],"h1":"It is about three months.","h2":"In Idaho, a first failed alcohol test brings a 90-day administrative suspension, with no driving at all for the first 30 days.","p":"Right. The suspension is 90 days."},"es":{"q":"En Idaho, un adulto no pasa una prueba de aliento de alcohol por primera vez. ¿Cuánto dura la suspensión administrativa de la licencia?","o":["90 días","7 días","Dos años","Cinco años"],"h1":"Son unos tres meses.","h2":"En Idaho, la primera prueba de alcohol no aprobada trae una suspensión administrativa de 90 días, sin poder manejar nada durante los primeros 30 días.","p":"Correcto. La suspensión es de 90 días."},"ref":{"doc":"ID","page":126}},{"id":"id-039","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, you get a Notice of Suspension after failing an alcohol test. How long do you have to ask for a hearing?","o":["24 hours","60 days","7 days","One year"],"h1":"It is about one week.","h2":"In Idaho, you may ask for an administrative hearing within 7 days of the date on the Notice of Suspension.","p":"Right. You have 7 days to ask for a hearing."},"es":{"q":"En Idaho, usted recibe un Aviso de Suspensión después de no pasar una prueba de alcohol. ¿Cuánto tiempo tiene para pedir una audiencia?","o":["24 horas","60 días","7 días","Un año"],"h1":"Es más o menos una semana.","h2":"En Idaho, usted puede pedir una audiencia administrativa dentro de 7 días a partir de la fecha del Aviso de Suspensión.","p":"Correcto. Tiene 7 días para pedir una audiencia."},"ref":{"doc":"ID","page":125}},{"id":"id-040","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, a driver refuses an officer's request for an alcohol or drug test. What civil penalty can they face, besides a suspension?","o":["$25","$100","$5,000","$250"],"h1":"It is more than $100 and less than $500.","h2":"Under Idaho's implied consent law, refusing the test can bring a license suspension and a civil penalty of $250.","p":"Right. The civil penalty is $250."},"es":{"q":"En Idaho, un conductor se niega a hacer la prueba de alcohol o drogas que pide un oficial. ¿Qué multa civil puede recibir, además de una suspensión?","o":["$25","$100","$5,000","$250"],"h1":"Es más de $100 y menos de $500.","h2":"Según la ley de consentimiento implícito de Idaho, negarse a la prueba puede traer una suspensión de la licencia y una multa civil de $250.","p":"Correcto. La multa civil es de $250."},"ref":{"doc":"ID","page":126}},{"id":"id-041","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, a driver refuses an alcohol test for the first time, and the court upholds the officer. How long is the license suspended?","o":["One year, with no driving at all","30 days, with work driving allowed","90 days","There is no suspension for a first refusal"],"h1":"A refusal is treated more harshly than failing the test.","h2":"In Idaho, a first test refusal brings a one-year suspension with absolutely no driving privileges.","p":"Right. A first refusal means one year with no driving."},"es":{"q":"En Idaho, un conductor se niega por primera vez a una prueba de alcohol, y el tribunal confirma lo que dijo el oficial. ¿Por cuánto tiempo se suspende la licencia?","o":["Un año, sin poder manejar nada","30 días, con permiso para manejar al trabajo","90 días","No hay suspensión por la primera negativa"],"h1":"Negarse se castiga más que no pasar la prueba.","h2":"En Idaho, la primera negativa a la prueba trae una suspensión de un año sin ningún privilegio de manejo.","p":"Correcto. La primera negativa significa un año sin manejar."},"ref":{"doc":"ID","page":126}},{"id":"id-042","scope":"ID","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Idaho, what is the speed limit for cars on an interstate when no other limit is posted?","o":["55 mph","65 mph","75 mph","85 mph"],"h1":"Some stretches may be posted even higher, at 80.","h2":"In Idaho, the speed limit on interstates is 75 mph unless a different limit is posted, and 80 mph may be allowed where posted.","p":"Right. It is 75 mph unless posted otherwise."},"es":{"q":"En Idaho, ¿cuál es el límite de velocidad para autos en una autopista interestatal cuando no hay otro límite señalado?","o":["55 mph","65 mph","75 mph","85 mph"],"h1":"Algunos tramos pueden tener un límite aún más alto, de 80.","h2":"En Idaho, el límite en las autopistas interestatales es de 75 mph, a menos que se indique otro, y puede ser de 80 mph donde esté señalado.","p":"Correcto. Es de 75 mph a menos que se indique otro."},"ref":{"doc":"ID","page":68}},{"id":"id-043","scope":"ID","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Idaho, what is the top speed in a residential, business or urban district when no sign says otherwise?","o":["25 mph","35 mph","45 mph","55 mph"],"h1":"It is less than 45 mph.","h2":"In Idaho, the maximum speed in any residential, business or urban district is 35 mph unless a different limit is posted.","p":"Right. It is 35 mph unless posted otherwise."},"es":{"q":"En Idaho, ¿cuál es la velocidad máxima en una zona residencial, comercial o urbana cuando ninguna señal indica otra?","o":["25 mph","35 mph","45 mph","55 mph"],"h1":"Es menos de 45 mph.","h2":"En Idaho, la velocidad máxima en cualquier zona residencial, comercial o urbana es de 35 mph, a menos que se indique otro límite.","p":"Correcto. Es de 35 mph a menos que se indique otra."},"ref":{"doc":"ID","page":69}},{"id":"id-044","scope":"ID","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Idaho, you are passing a slower car on a two-lane road posted at 55 mph or more. How much over the limit may you go while passing?","o":["Not at all","Up to 5 mph","Up to 25 mph","Up to 15 mph"],"h1":"It applies only while passing, and never in work zones.","h2":"In Idaho, a car not towing anything may go up to 15 mph over the limit to pass a slower vehicle on a two-lane road posted at 55 mph or more, then slow back down.","p":"Right. You may go up to 15 mph over while passing."},"es":{"q":"En Idaho, usted rebasa a un auto más lento en una carretera de dos carriles con límite de 55 mph o más. ¿Cuánto puede pasar del límite mientras rebasa?","o":["Nada","Hasta 5 mph","Hasta 25 mph","Hasta 15 mph"],"h1":"Se permite solo al rebasar, y nunca en zonas de obras.","h2":"En Idaho, un auto que no remolca nada puede ir hasta 15 mph sobre el límite para rebasar a un vehículo más lento en una carretera de dos carriles con límite de 55 mph o más, y luego debe volver a bajar la velocidad.","p":"Correcto. Puede ir hasta 15 mph sobre el límite al rebasar."},"ref":{"doc":"ID","page":77}},{"id":"id-045","scope":"ID","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Idaho, how close to an intersection or a railroad crossing is passing not allowed, unless signs or markings say otherwise?","o":["Within 100 feet","Within 10 feet","Within 1,000 feet","Within one mile"],"h1":"It is about the length of six or seven cars.","h2":"In Idaho, you may not pass within 100 feet of an intersection or a railroad crossing, unless traffic control devices allow it.","p":"Right. No passing within 100 feet."},"es":{"q":"En Idaho, ¿a qué distancia de una intersección o de un cruce de ferrocarril no se permite rebasar, salvo que las señales o marcas indiquen otra cosa?","o":["A menos de 100 pies","A menos de 10 pies","A menos de 1,000 pies","A menos de una milla"],"h1":"Es más o menos el largo de seis o siete autos.","h2":"En Idaho, no puede rebasar a menos de 100 pies de una intersección o de un cruce de ferrocarril, salvo que los dispositivos de control de tránsito lo permitan.","p":"Correcto. No se rebasa a menos de 100 pies."},"ref":{"doc":"ID","page":76}},{"id":"id-046","scope":"ID","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Idaho, a school bus is stopped with red lights flashing on the other side of the road. When do you NOT have to stop?","o":["When you are in a hurry","When the bus is on a two-lane road","When the highway has four or more lanes, with two going each way","When no children are in sight"],"h1":"It depends on how many lanes the highway has.","h2":"In Idaho, you do not have to stop for a school bus on the other side if the highway has four or more lanes, with two lanes going in each direction.","p":"Right. On a highway with two lanes each way, the other side does not stop."},"es":{"q":"En Idaho, un autobús escolar está detenido con las luces rojas encendidas al otro lado de la carretera. ¿Cuándo NO tiene que detenerse?","o":["Cuando usted tiene prisa","Cuando el autobús está en una carretera de dos carriles","Cuando la carretera tiene cuatro carriles o más, con dos en cada sentido","Cuando no se ven niños"],"h1":"Depende de cuántos carriles tiene la carretera.","h2":"En Idaho, no tiene que detenerse por un autobús escolar al otro lado si la carretera tiene cuatro carriles o más, con dos carriles en cada sentido.","p":"Correcto. En una carretera con dos carriles en cada sentido, el otro lado no se detiene."},"ref":{"doc":"ID","page":70}},{"id":"id-047","scope":"ID","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Idaho, what must a bicyclist do at a stop sign?","o":["Get off and walk the bike across","Slow down and yield, without a full stop","Stop fully and wait for a car to wave them on","Use the sidewalk to get around it"],"h1":"Idaho has a special stop sign rule for bicycles.","h2":"In Idaho, a bicyclist does not need to come to a complete stop at a stop sign, but must yield to vehicles at or near the intersection and then go on with care.","p":"Right. A bicyclist may yield at a stop sign without a full stop."},"es":{"q":"En Idaho, ¿qué debe hacer un ciclista en una señal de alto?","o":["Bajarse y cruzar caminando con la bicicleta","Bajar la velocidad y ceder el paso, sin detenerse por completo","Detenerse por completo y esperar que un auto le haga señas","Usar la acera para rodearla"],"h1":"Idaho tiene una regla especial de alto para bicicletas.","h2":"En Idaho, un ciclista no tiene que detenerse por completo en una señal de alto, pero debe ceder el paso a los vehículos en la intersección o cerca de ella y luego seguir con cuidado.","p":"Correcto. Un ciclista puede ceder el paso en una señal de alto sin detenerse por completo."},"ref":{"doc":"ID","page":98}},{"id":"id-048","scope":"ID","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Idaho, you are passing a bicyclist and cannot change lanes. What is the safe space to leave, at a minimum?","o":["6 inches","1 foot","2 feet","3 feet"],"h1":"Think of about one big step.","h2":"The Idaho handbook says to leave at least 3 feet when passing a bicyclist, and more space at higher speeds.","p":"Right. Leave at least 3 feet."},"es":{"q":"En Idaho, usted rebasa a un ciclista y no puede cambiar de carril. ¿Cuál es el espacio mínimo seguro que debe dejar?","o":["6 pulgadas","1 pie","2 pies","3 pies"],"h1":"Piense en un paso largo.","h2":"El manual de Idaho dice que debe dejar al menos 3 pies al rebasar a un ciclista, y más espacio a mayor velocidad.","p":"Correcto. Deje al menos 3 pies."},"ref":{"doc":"ID","page":98}},{"id":"id-049","scope":"ID","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Idaho, a car is coming toward you at night. When must you dim your high beams?","o":["Within 500 feet of the car","Within 50 feet of the car","Only when the car is beside you","Only if the other driver flashes their lights"],"h1":"Think of the length of more than one and a half football fields.","h2":"In Idaho, you must dim your headlights within 500 feet of an oncoming vehicle, and within 200 feet of a vehicle you follow.","p":"Right. Dim them within 500 feet of an oncoming car."},"es":{"q":"En Idaho, un auto viene hacia usted de noche. ¿Cuándo debe bajar las luces altas?","o":["A menos de 500 pies del auto","A menos de 50 pies del auto","Solo cuando el auto está a su lado","Solo si el otro conductor le hace cambio de luces"],"h1":"Piense en más de una cancha y media de fútbol americano.","h2":"En Idaho, debe bajar las luces a menos de 500 pies de un vehículo que viene de frente, y a menos de 200 pies de un vehículo que va delante de usted.","p":"Correcto. Bájelas a menos de 500 pies de un auto que viene de frente."},"ref":{"doc":"ID","page":43}},{"id":"id-050","scope":"ID","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Idaho, when may you use studded snow tires, unless ITD changes the dates?","o":["All year","Only in January and February","From October 1 to April 30","From May 1 to September 30"],"h1":"They are for the cold part of the year.","h2":"In Idaho, studded snow tires may be used from October 1 to April 30, and ITD sometimes adjusts the dates for weather.","p":"Right. Studded tires are allowed October 1 to April 30."},"es":{"q":"En Idaho, ¿cuándo puede usar llantas de nieve con clavos, si ITD no cambia las fechas?","o":["Todo el año","Solo en enero y febrero","Del 1 de octubre al 30 de abril","Del 1 de mayo al 30 de septiembre"],"h1":"Son para la parte fría del año.","h2":"En Idaho, las llantas de nieve con clavos se pueden usar del 1 de octubre al 30 de abril, y a veces ITD ajusta las fechas por el clima.","p":"Correcto. Las llantas con clavos se permiten del 1 de octubre al 30 de abril."},"ref":{"doc":"ID","page":42}},{"id":"id-051","scope":"ID","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Idaho, you hit a cow on open range outside city limits and your car is damaged. Who pays for your car?","o":["The cow's owner must pay","The cow's owner is not liable for your damage","The county pays for all repairs","The state road department pays"],"h1":"On open range, livestock are allowed to roam free.","h2":"In Idaho, if you hit livestock on open range, the animal's owner is not liable for damage to you or your car, and you may owe for the animal if you were careless.","p":"Right. On open range, the owner does not pay for your damage."},"es":{"q":"En Idaho, usted choca con una vaca en campo abierto (open range) fuera de la ciudad y su auto se daña. ¿Quién paga por su auto?","o":["El dueño de la vaca debe pagar","El dueño de la vaca no es responsable de sus daños","El condado paga todas las reparaciones","El departamento de carreteras del estado paga"],"h1":"En campo abierto, el ganado puede andar suelto.","h2":"En Idaho, si choca con ganado en campo abierto, el dueño del animal no es responsable de los daños a usted o a su auto, y usted puede tener que pagar por el animal si fue descuidado.","p":"Correcto. En campo abierto, el dueño no paga por sus daños."},"ref":{"doc":"ID","page":108}},{"id":"il-001","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, how many questions are on the written knowledge test?","o":["20 questions","25 questions","35 questions","50 questions"],"h1":"It is more than 30 but fewer than 40.","h2":"Illinois rules say the written test for a regular driver's license has at least 35 questions.","p":"Right. The Illinois test has 35 questions."},"es":{"q":"En Illinois, ¿cuántas preguntas tiene el examen escrito de conocimientos?","o":["20 preguntas","25 preguntas","35 preguntas","50 preguntas"],"h1":"Son más de 30 pero menos de 40.","h2":"Las reglas de Illinois dicen que el examen escrito para una licencia de conducir regular tiene al menos 35 preguntas.","p":"Correcto. El examen de Illinois tiene 35 preguntas."},"zh":{"q":"在 Illinois，笔试有多少道题？","o":["20 道题","25 道题","35 道题","50 道题"],"h1":"比 30 多，但比 40 少。","h2":"Illinois 的规定说，普通驾照的笔试至少有 35 道题。","p":"对。Illinois 的考试有 35 道题。"},"vi":{"q":"Ở Illinois, bài thi kiến thức viết có bao nhiêu câu hỏi?","o":["20 câu hỏi","25 câu hỏi","35 câu hỏi","50 câu hỏi"],"h1":"Nhiều hơn 30 nhưng ít hơn 40.","h2":"Quy định của Illinois nói rằng bài thi viết để lấy bằng lái thông thường có ít nhất 35 câu hỏi.","p":"Đúng. Bài thi ở Illinois có 35 câu hỏi."},"tl":{"q":"Sa Illinois, ilang tanong ang nasa written knowledge test?","o":["20 tanong","25 tanong","35 tanong","50 tanong"],"h1":"Higit ito sa 30 pero mas kaunti sa 40.","h2":"Sinasabi ng mga patakaran ng Illinois na ang written test para sa regular na driver's license ay may hindi bababa sa 35 tanong.","p":"Tama. May 35 tanong ang test sa Illinois."},"ar":{"q":"في Illinois، كم سؤالًا في اختبار المعرفة الكتابي؟","o":["20 سؤالًا","25 سؤالًا","35 سؤالًا","50 سؤالًا"],"h1":"إنه أكثر من 30 وأقل من 40.","h2":"تقول قواعد Illinois إن الاختبار الكتابي لرخصة القيادة العادية فيه 35 سؤالًا على الأقل.","p":"صحيح. في اختبار Illinois يوجد 35 سؤالًا."},"ref":{"doc":"IL","page":null}},{"id":"il-002","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, how many of the written test questions must you answer correctly to pass?","o":["28","21","30","35"],"h1":"You need 80 percent of the questions right.","h2":"You must answer at least 28 of the 35 Illinois test questions correctly, which is 80 percent.","p":"Right. You need 28 correct answers to pass."},"es":{"q":"En Illinois, ¿cuántas preguntas del examen escrito debe contestar bien para aprobar?","o":["28","21","30","35"],"h1":"Necesita contestar bien el 80 por ciento de las preguntas.","h2":"Usted debe contestar bien por lo menos 28 de las 35 preguntas del examen de Illinois, que es el 80 por ciento.","p":"Correcto. Necesita 28 respuestas correctas para aprobar."},"zh":{"q":"在 Illinois，笔试必须答对多少道题才能通过？","o":["28","21","30","35"],"h1":"你需要答对 80% 的题。","h2":"35 道 Illinois 笔试题里，你必须至少答对 28 道，也就是 80%。","p":"对。你需要答对 28 道才能通过。"},"vi":{"q":"Ở Illinois, bạn phải trả lời đúng bao nhiêu câu trong bài thi viết để đậu?","o":["28","21","30","35"],"h1":"Bạn cần trả lời đúng 80 phần trăm số câu hỏi.","h2":"Bạn phải trả lời đúng ít nhất 28 trong 35 câu hỏi của bài thi Illinois, tức là 80 phần trăm.","p":"Đúng. Bạn cần 28 câu đúng để đậu."},"tl":{"q":"Sa Illinois, ilan sa mga tanong sa nakasulat na test ang dapat mong masagot nang tama para pumasa?","o":["28","21","30","35"],"h1":"Kailangan mong masagot nang tama ang 80 porsiyento ng mga tanong.","h2":"Dapat mong masagot nang tama ang hindi bababa sa 28 sa 35 tanong ng test sa Illinois, na 80 porsiyento.","p":"Tama. Kailangan mo ng 28 tamang sagot para pumasa."},"ar":{"q":"في Illinois، كم سؤالًا من أسئلة الاختبار الكتابي يجب أن تجيب عنه إجابة صحيحة لتنجح؟","o":["28","21","30","35"],"h1":"تحتاج إلى إجابة 80 بالمئة من الأسئلة إجابة صحيحة.","h2":"يجب أن تجيب إجابة صحيحة عن 28 سؤالًا على الأقل من أسئلة اختبار Illinois الـ35، وهذا يساوي 80 بالمئة.","p":"صحيح. تحتاج إلى 28 إجابة صحيحة لتنجح."},"ref":{"doc":"IL","page":null}},{"id":"il-003","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, what is the youngest age to take the written test for an instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before the usual age for a first license.","h2":"In Illinois you can take the written test for an instruction permit at 15 years old.","p":"Right. In Illinois you can start at 15."},"es":{"q":"En Illinois, ¿cuál es la edad mínima para presentar el examen escrito del permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la edad habitual para la primera licencia.","h2":"En Illinois usted puede presentar el examen escrito del permiso de aprendiz a los 15 años.","p":"Correcto. En Illinois puede empezar a los 15."},"zh":{"q":"在 Illinois，最小几岁可以参加学习驾照（instruction permit）的笔试？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"比一般第一次拿驾照的年龄早一年。","h2":"在 Illinois，你 15 岁就可以参加学习驾照的笔试。","p":"对。在 Illinois，你可以从 15 岁开始。"},"vi":{"q":"Ở Illinois, tuổi nhỏ nhất để thi viết lấy giấy phép tập lái (instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là một năm trước tuổi thường được lấy bằng lái đầu tiên.","h2":"Ở Illinois, bạn có thể thi viết để lấy giấy phép tập lái khi 15 tuổi.","p":"Đúng. Ở Illinois bạn có thể bắt đầu khi 15 tuổi."},"tl":{"q":"Sa Illinois, ano ang pinakabatang edad para kumuha ng nakasulat na test para sa instruction permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ang karaniwang edad para sa unang lisensya.","h2":"Sa Illinois, puwede kang kumuha ng nakasulat na test para sa instruction permit sa edad na 15.","p":"Tama. Sa Illinois, puwede kang magsimula sa 15."},"ar":{"q":"في Illinois، ما أصغر عمر لأداء الاختبار الكتابي للحصول على تصريح التعلّم (instruction permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هو سنة واحدة قبل العمر المعتاد لأول رخصة.","h2":"في Illinois يمكنك أداء الاختبار الكتابي للحصول على تصريح التعلّم في عمر 15 سنة.","p":"صحيح. في Illinois يمكنك أن تبدأ في عمر 15 سنة."},"ref":{"doc":"IL","page":16}},{"id":"il-004","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, how long must a driver under 18 hold the instruction permit before getting a license?","o":["3 months","6 months","12 months","9 months"],"h1":"It is longer than half a year but less than a full year.","h2":"An Illinois driver under 18 must hold the instruction permit for at least nine months before moving to a license.","p":"Right. The Illinois permit must be held for nine months."},"es":{"q":"En Illinois, ¿cuánto tiempo debe tener el permiso de aprendiz un conductor menor de 18 años antes de obtener la licencia?","o":["3 meses","6 meses","12 meses","9 meses"],"h1":"Es más de medio año pero menos de un año completo.","h2":"Un conductor de Illinois menor de 18 años debe tener el permiso de aprendiz por lo menos nueve meses antes de pasar a la licencia.","p":"Correcto. En Illinois el permiso se debe tener nueve meses."},"zh":{"q":"在 Illinois，18 岁以下的司机必须持有学习驾照多久，才能拿到驾照？","o":["3 个月","6 个月","12 个月","9 个月"],"h1":"比半年长，但不到一整年。","h2":"在 Illinois，18 岁以下的司机必须持有学习驾照至少九个月，才能换成驾照。","p":"对。Illinois 的学习驾照必须持有九个月。"},"vi":{"q":"Ở Illinois, người lái dưới 18 tuổi phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái?","o":["3 tháng","6 tháng","12 tháng","9 tháng"],"h1":"Lâu hơn nửa năm nhưng ít hơn một năm.","h2":"Người lái dưới 18 tuổi ở Illinois phải giữ giấy phép tập lái ít nhất chín tháng trước khi lấy bằng lái.","p":"Đúng. Ở Illinois phải giữ giấy phép tập lái chín tháng."},"tl":{"q":"Sa Illinois, gaano katagal dapat hawak ng driver na wala pang 18 ang instruction permit bago makakuha ng lisensya?","o":["3 buwan","6 na buwan","12 buwan","9 na buwan"],"h1":"Mas matagal ito sa kalahating taon pero kulang sa isang buong taon.","h2":"Ang driver sa Illinois na wala pang 18 ay dapat humawak ng instruction permit nang hindi bababa sa siyam na buwan bago lumipat sa lisensya.","p":"Tama. Dapat hawak ang permit sa Illinois nang siyam na buwan."},"ar":{"q":"في Illinois، كم مدة يجب أن يحمل السائق الذي عمره أقل من 18 سنة تصريح التعلّم قبل الحصول على رخصة؟","o":["3 أشهر","6 أشهر","12 شهرًا","9 أشهر"],"h1":"هي أطول من نصف سنة لكنها أقل من سنة كاملة.","h2":"يجب على السائق في Illinois الذي عمره أقل من 18 سنة أن يحمل تصريح التعلّم تسعة أشهر على الأقل قبل الانتقال إلى الرخصة.","p":"صحيح. يجب حمل التصريح في Illinois تسعة أشهر."},"ref":{"doc":"IL","page":16}},{"id":"il-005","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, what happens to the nine-month permit period if the permit holder gets a moving violation?","o":["Nothing changes","The permit becomes a license early","A new nine-month wait begins","The holder only pays a fine"],"h1":"The violation sets you back, not forward.","h2":"In Illinois, a moving violation conviction during the permit phase means a new nine-month wait before you can apply for a license.","p":"Right. A violation means a new nine-month wait."},"es":{"q":"En Illinois, ¿qué pasa con el periodo de nueve meses del permiso si el titular recibe una infracción de tránsito en movimiento?","o":["No cambia nada","El permiso se convierte antes en licencia","Empieza una nueva espera de nueve meses","El titular solo paga una multa"],"h1":"La infracción lo hace retroceder, no avanzar.","h2":"En Illinois, una condena por infracción en movimiento durante la etapa del permiso significa una nueva espera de nueve meses antes de poder solicitar la licencia.","p":"Correcto. Una infracción significa una nueva espera de nueve meses."},"zh":{"q":"在 Illinois，如果持学习驾照的人有行车违规，九个月的学习驾照期会怎么样？","o":["什么都不变","学习驾照提前变成驾照","重新开始等九个月","持有人只交罚款"],"h1":"违规会让你后退，不会让你前进。","h2":"在 Illinois，学习驾照阶段被判行车违规，就要重新等九个月才能申请驾照。","p":"对。违规就要重新等九个月。"},"vi":{"q":"Ở Illinois, điều gì xảy ra với thời gian chín tháng giữ giấy phép nếu người có giấy phép tập lái bị phạt vi phạm khi đang lái xe?","o":["Không có gì thay đổi","Giấy phép trở thành bằng lái sớm hơn","Bắt đầu một thời gian chờ chín tháng mới","Người đó chỉ phải trả tiền phạt"],"h1":"Vi phạm làm bạn lùi lại, không phải tiến lên.","h2":"Ở Illinois, nếu bị kết tội vi phạm khi lái xe trong thời gian tập lái, bạn phải chờ lại chín tháng mới trước khi xin bằng lái.","p":"Đúng. Một lần vi phạm nghĩa là phải chờ lại chín tháng mới."},"tl":{"q":"Sa Illinois, ano ang mangyayari sa siyam na buwang panahon ng permit kung magkaroon ng moving violation ang may hawak ng permit?","o":["Walang magbabago","Magiging lisensya nang maaga ang permit","Magsisimula ang bagong siyam na buwang paghihintay","Multa lang ang babayaran ng may hawak"],"h1":"Pinauurong ka ng violation, hindi pinauusad.","h2":"Sa Illinois, kapag nahatulan ka ng moving violation habang nasa permit phase, magsisimula ang bagong siyam na buwang paghihintay bago ka makapag-apply ng lisensya.","p":"Tama. Ang isang violation ay nangangahulugan ng bagong siyam na buwang paghihintay."},"ar":{"q":"في Illinois، ماذا يحدث لمدة التصريح البالغة تسعة أشهر إذا ارتكب حامل التصريح مخالفة أثناء القيادة (moving violation)؟","o":["لا يتغير شيء","يصبح التصريح رخصة في وقت أبكر","تبدأ مدة انتظار جديدة من تسعة أشهر","يدفع حامل التصريح غرامة فقط"],"h1":"المخالفة تعيدك إلى الوراء، لا إلى الأمام.","h2":"في Illinois، إذا أُدنت بمخالفة أثناء القيادة في مرحلة التصريح، تبدأ مدة انتظار جديدة من تسعة أشهر قبل أن تتقدم بطلب للرخصة.","p":"صحيح. المخالفة تعني انتظارًا جديدًا من تسعة أشهر."},"ref":{"doc":"IL","page":null}},{"id":"il-006","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, how many hours of supervised practice must a driver under 18 complete with the permit?","o":["30 hours","50 hours","40 hours","100 hours"],"h1":"It is half of one hundred.","h2":"An Illinois driver under 18 must complete at least 50 hours of supervised practice, including 10 hours at night.","p":"Right. Illinois requires 50 practice hours."},"es":{"q":"En Illinois, ¿cuántas horas de práctica supervisada debe completar con el permiso un conductor menor de 18 años?","o":["30 horas","50 horas","40 horas","100 horas"],"h1":"Es la mitad de cien.","h2":"Un conductor de Illinois menor de 18 años debe completar por lo menos 50 horas de práctica supervisada, de las cuales 10 son de noche.","p":"Correcto. Illinois exige 50 horas de práctica."},"zh":{"q":"在 Illinois，18 岁以下的司机持学习驾照期间，必须完成多少小时有人陪同的练习？","o":["30 小时","50 小时","40 小时","100 小时"],"h1":"是一百的一半。","h2":"在 Illinois，18 岁以下的司机必须完成至少 50 小时有人陪同的练习，其中包括 10 小时夜间驾驶。","p":"对。Illinois 要求 50 小时练习。"},"vi":{"q":"Ở Illinois, người lái dưới 18 tuổi phải tập lái có người giám sát bao nhiêu giờ khi có giấy phép tập lái?","o":["30 giờ","50 giờ","40 giờ","100 giờ"],"h1":"Đó là một nửa của một trăm.","h2":"Người lái dưới 18 tuổi ở Illinois phải tập lái có người giám sát ít nhất 50 giờ, trong đó có 10 giờ vào ban đêm.","p":"Đúng. Illinois yêu cầu 50 giờ tập lái."},"tl":{"q":"Sa Illinois, ilang oras ng supervised practice ang dapat tapusin ng driver na wala pang 18 habang may permit?","o":["30 oras","50 oras","40 oras","100 oras"],"h1":"Kalahati ito ng isandaan.","h2":"Ang driver sa Illinois na wala pang 18 ay dapat makatapos ng hindi bababa sa 50 oras ng supervised practice, kasama ang 10 oras sa gabi.","p":"Tama. Kailangan ng Illinois ng 50 oras ng pagsasanay."},"ar":{"q":"في Illinois، كم ساعة من التدريب تحت الإشراف يجب أن يكملها السائق الذي عمره أقل من 18 سنة مع التصريح؟","o":["30 ساعة","50 ساعة","40 ساعة","100 ساعة"],"h1":"هو نصف المئة.","h2":"يجب على السائق في Illinois الذي عمره أقل من 18 سنة أن يكمل 50 ساعة على الأقل من التدريب تحت الإشراف، منها 10 ساعات في الليل.","p":"صحيح. تطلب Illinois خمسين ساعة تدريب."},"ref":{"doc":"IL","page":16}},{"id":"il-007","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, how many of the 50 supervised practice hours must be at night?","o":["10 hours","5 hours","20 hours","25 hours"],"h1":"It is one fifth of the total.","h2":"At least 10 of the 50 supervised practice hours in Illinois must be done at night.","p":"Right. Ten hours must be at night."},"es":{"q":"En Illinois, ¿cuántas de las 50 horas de práctica supervisada deben ser de noche?","o":["10 horas","5 horas","20 horas","25 horas"],"h1":"Es la quinta parte del total.","h2":"Por lo menos 10 de las 50 horas de práctica supervisada en Illinois deben hacerse de noche.","p":"Correcto. Diez horas deben ser de noche."},"zh":{"q":"在 Illinois，50 小时有人陪同的练习中，必须有多少小时是在夜间？","o":["10 小时","5 小时","20 小时","25 小时"],"h1":"是总数的五分之一。","h2":"在 Illinois，50 小时有人陪同的练习中，至少 10 小时必须在夜间完成。","p":"对。十个小时必须在夜间。"},"vi":{"q":"Ở Illinois, trong 50 giờ tập lái có người giám sát, bao nhiêu giờ phải là vào ban đêm?","o":["10 giờ","5 giờ","20 giờ","25 giờ"],"h1":"Đó là một phần năm của tổng số giờ.","h2":"Ở Illinois, ít nhất 10 trong 50 giờ tập lái có người giám sát phải là vào ban đêm.","p":"Đúng. Mười giờ phải là vào ban đêm."},"tl":{"q":"Sa Illinois, ilan sa 50 oras ng supervised practice ang dapat gawin sa gabi?","o":["10 oras","5 oras","20 oras","25 oras"],"h1":"Isang ikalima ito ng kabuuan.","h2":"Hindi bababa sa 10 sa 50 oras ng supervised practice sa Illinois ang dapat gawin sa gabi.","p":"Tama. Sampung oras ang dapat sa gabi."},"ar":{"q":"في Illinois، كم ساعة من ساعات التدريب الخمسين تحت الإشراف يجب أن تكون في الليل؟","o":["10 ساعات","5 ساعات","20 ساعة","25 ساعة"],"h1":"هي خُمس المجموع.","h2":"يجب أن تكون 10 ساعات على الأقل من ساعات التدريب الخمسين تحت الإشراف في Illinois في الليل.","p":"صحيح. يجب أن تكون عشر ساعات في الليل."},"ref":{"doc":"IL","page":16}},{"id":"il-008","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, who may supervise a permit holder during practice?","o":["Any licensed driver 16 or older","Any licensed driver 18 or older","Only a driving instructor","A parent or a licensed adult 21 or older"],"h1":"The supervisor must be old enough to drink legally.","h2":"In Illinois a permit holder must practice with a parent or a licensed adult who is at least 21 years old.","p":"Right. The supervisor must be a parent or a licensed adult 21 or older."},"es":{"q":"En Illinois, ¿quién puede supervisar a un conductor con permiso durante la práctica?","o":["Cualquier conductor con licencia de 16 años o más","Cualquier conductor con licencia de 18 años o más","Solo un instructor de manejo","Un padre o un adulto con licencia de 21 años o más"],"h1":"El supervisor debe tener edad para tomar alcohol legalmente.","h2":"En Illinois un conductor con permiso debe practicar con un padre o con un adulto con licencia que tenga por lo menos 21 años.","p":"Correcto. El supervisor debe ser un padre o un adulto con licencia de 21 años o más."},"zh":{"q":"在 Illinois，谁可以在练习时陪同持学习驾照的人？","o":["任何 16 岁或以上、有驾照的司机","任何 18 岁或以上、有驾照的司机","只有驾驶教练","父母，或 21 岁或以上、有驾照的成年人"],"h1":"陪同的人必须到了可以合法喝酒的年龄。","h2":"在 Illinois，持学习驾照的人必须和父母，或一位至少 21 岁、有驾照的成年人一起练习。","p":"对。陪同的人必须是父母，或 21 岁或以上、有驾照的成年人。"},"vi":{"q":"Ở Illinois, ai được phép giám sát người có giấy phép tập lái khi tập lái?","o":["Bất kỳ người có bằng lái nào từ 16 tuổi trở lên","Bất kỳ người có bằng lái nào từ 18 tuổi trở lên","Chỉ thầy dạy lái xe","Cha mẹ hoặc một người lớn có bằng lái từ 21 tuổi trở lên"],"h1":"Người giám sát phải đủ tuổi để được uống rượu hợp pháp.","h2":"Ở Illinois, người có giấy phép tập lái phải tập với cha mẹ hoặc một người lớn có bằng lái ít nhất 21 tuổi.","p":"Đúng. Người giám sát phải là cha mẹ hoặc người lớn có bằng lái từ 21 tuổi trở lên."},"tl":{"q":"Sa Illinois, sino ang puwedeng magbantay sa may hawak ng permit habang nagsasanay?","o":["Sinumang may lisensya na 16 pataas","Sinumang may lisensya na 18 pataas","Isang driving instructor lang","Isang magulang o isang adult na may lisensya na 21 pataas"],"h1":"Dapat sapat ang edad ng nagbabantay para legal na uminom ng alak.","h2":"Sa Illinois, dapat magsanay ang may hawak ng permit kasama ang isang magulang o isang adult na may lisensya na hindi bababa sa 21 taong gulang.","p":"Tama. Dapat magulang o adult na may lisensya na 21 pataas ang nagbabantay."},"ar":{"q":"في Illinois، من يجوز له الإشراف على حامل التصريح أثناء التدريب؟","o":["أي سائق مرخّص عمره 16 سنة أو أكثر","أي سائق مرخّص عمره 18 سنة أو أكثر","مدرّب القيادة فقط","أحد الوالدين أو شخص بالغ مرخّص عمره 21 سنة أو أكثر"],"h1":"يجب أن يكون المشرف في العمر الذي يُسمح فيه قانونيًا بشرب الكحول.","h2":"في Illinois يجب أن يتدرب حامل التصريح مع أحد الوالدين أو مع شخص بالغ مرخّص عمره 21 سنة على الأقل.","p":"صحيح. يجب أن يكون المشرف أحد الوالدين أو شخصًا بالغًا مرخّصًا عمره 21 سنة أو أكثر."},"ref":{"doc":"IL","page":16}},{"id":"il-009","scope":"IL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Illinois, may a driver under 19 with a permit or graduated license use a hands-free phone while driving?","o":["Yes, hands-free is always allowed","Yes, but only on highways","No, except to call for help in an emergency","Yes, if a parent is in the car"],"h1":"The rule for young drivers is stricter than for adults.","h2":"An Illinois driver under 19 with a permit or graduated license may not use any phone while driving, hands-free included, except to report an emergency.","p":"Right. Young drivers may use a phone only in an emergency."},"es":{"q":"En Illinois, ¿puede un conductor menor de 19 años con permiso o licencia gradual usar un teléfono manos libres mientras maneja?","o":["Sí, el manos libres siempre está permitido","Sí, pero solo en autopistas","No, excepto para pedir ayuda en una emergencia","Sí, si va un padre en el carro"],"h1":"La regla para conductores jóvenes es más estricta que para los adultos.","h2":"Un conductor de Illinois menor de 19 años con permiso o licencia gradual no puede usar ningún teléfono mientras maneja, ni siquiera manos libres, excepto para reportar una emergencia.","p":"Correcto. Los conductores jóvenes solo pueden usar el teléfono en una emergencia."},"zh":{"q":"在 Illinois，19 岁以下、持学习驾照或分级驾照的司机，开车时可以用免提手机吗？","o":["可以，免提任何时候都允许","可以，但只能在高速公路上","不可以，除非在紧急情况下打电话求助","可以，只要父母在车上"],"h1":"对年轻司机的规定比对成年人更严格。","h2":"在 Illinois，19 岁以下、持学习驾照或分级驾照的司机开车时不能用任何手机，包括免提，只有报告紧急情况除外。","p":"对。年轻司机只有在紧急情况下才能用手机。"},"vi":{"q":"Ở Illinois, người lái dưới 19 tuổi có giấy phép tập lái hoặc bằng lái theo cấp (graduated license) có được dùng điện thoại rảnh tay khi lái xe không?","o":["Có, rảnh tay thì luôn được phép","Có, nhưng chỉ trên xa lộ","Không, trừ khi gọi xin giúp đỡ trong trường hợp khẩn cấp","Có, nếu có cha mẹ ngồi trong xe"],"h1":"Luật cho người lái trẻ nghiêm hơn luật cho người lớn.","h2":"Ở Illinois, người lái dưới 19 tuổi có giấy phép tập lái hoặc bằng lái theo cấp không được dùng bất kỳ điện thoại nào khi lái xe, kể cả rảnh tay, trừ khi báo trường hợp khẩn cấp.","p":"Đúng. Người lái trẻ chỉ được dùng điện thoại khi khẩn cấp."},"tl":{"q":"Sa Illinois, puwede bang gumamit ng hands-free na telepono habang nagmamaneho ang driver na wala pang 19 na may permit o graduated license?","o":["Oo, laging pinapayagan ang hands-free","Oo, pero sa highway lang","Hindi, maliban kung tatawag para humingi ng tulong sa emergency","Oo, kung may magulang sa sasakyan"],"h1":"Mas mahigpit ang patakaran para sa mga batang driver kaysa sa mga adult.","h2":"Sa Illinois, ang driver na wala pang 19 na may permit o graduated license ay hindi puwedeng gumamit ng anumang telepono habang nagmamaneho, kasama ang hands-free, maliban kung mag-uulat ng emergency.","p":"Tama. Puwedeng gumamit ng telepono ang mga batang driver sa emergency lang."},"ar":{"q":"في Illinois، هل يجوز للسائق الذي عمره أقل من 19 سنة ويحمل تصريحًا أو رخصة متدرجة (graduated license) أن يستخدم هاتفًا بدون استخدام اليدين (hands-free) أثناء القيادة؟","o":["نعم، الهاتف بدون اليدين مسموح دائمًا","نعم، لكن على الطرق السريعة فقط","لا، إلا للاتصال لطلب المساعدة في حالة طوارئ","نعم، إذا كان أحد الوالدين في السيارة"],"h1":"القاعدة للسائقين الصغار أشد من القاعدة للبالغين.","h2":"في Illinois، لا يجوز للسائق الذي عمره أقل من 19 سنة ويحمل تصريحًا أو رخصة متدرجة أن يستخدم أي هاتف أثناء القيادة، حتى بدون اليدين، إلا للإبلاغ عن حالة طوارئ.","p":"صحيح. يستخدم السائقون الصغار الهاتف في حالة الطوارئ فقط."},"ref":{"doc":"IL","page":18}},{"id":"il-010","scope":"IL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Illinois, what kind of phone use is banned for all drivers while driving?","o":["Hands-free calls","Holding the phone in your hand","Voice commands","Listening to music through the car"],"h1":"Think about where the phone is.","h2":"Illinois bans all drivers from using a hand-held phone while driving. Drivers 19 and older may still use a hands-free phone.","p":"Right. Hand-held phone use is banned for every Illinois driver."},"es":{"q":"En Illinois, ¿qué uso del teléfono está prohibido para todos los conductores mientras manejan?","o":["Llamadas con manos libres","Sostener el teléfono en la mano","Comandos de voz","Escuchar música por el sistema del carro"],"h1":"Piense en dónde está el teléfono.","h2":"Illinois prohíbe a todos los conductores usar el teléfono en la mano mientras manejan. Los conductores de 19 años o más todavía pueden usar un teléfono manos libres.","p":"Correcto. Usar el teléfono en la mano está prohibido para todos en Illinois."},"zh":{"q":"在 Illinois，开车时哪种用手机的方式对所有司机都是禁止的？","o":["用免提打电话","手里拿着手机","语音命令","通过车上的音响听音乐"],"h1":"想一想手机在哪里。","h2":"Illinois 禁止所有司机开车时使用手持手机。19 岁及以上的司机仍然可以用免提手机。","p":"对。Illinois 的每一位司机都不能手持手机。"},"vi":{"q":"Ở Illinois, cách dùng điện thoại nào bị cấm đối với tất cả người lái khi đang lái xe?","o":["Gọi điện rảnh tay","Cầm điện thoại trên tay","Ra lệnh bằng giọng nói","Nghe nhạc qua loa xe"],"h1":"Hãy nghĩ xem điện thoại đang ở đâu.","h2":"Illinois cấm tất cả người lái dùng điện thoại cầm tay khi lái xe. Người lái từ 19 tuổi trở lên vẫn được dùng điện thoại rảnh tay.","p":"Đúng. Mọi người lái ở Illinois đều bị cấm dùng điện thoại cầm tay."},"tl":{"q":"Sa Illinois, anong uri ng paggamit ng telepono ang bawal sa lahat ng driver habang nagmamaneho?","o":["Mga hands-free na tawag","Paghawak ng telepono sa kamay","Mga voice command","Pakikinig ng musika sa sasakyan"],"h1":"Isipin kung nasaan ang telepono.","h2":"Ipinagbabawal ng Illinois sa lahat ng driver ang paggamit ng hand-held na telepono habang nagmamaneho. Puwede pa ring gumamit ng hands-free na telepono ang mga driver na 19 pataas.","p":"Tama. Bawal sa bawat driver sa Illinois ang hand-held na telepono."},"ar":{"q":"في Illinois، أي نوع من استخدام الهاتف ممنوع على كل السائقين أثناء القيادة؟","o":["المكالمات بدون استخدام اليدين","حمل الهاتف في يدك","الأوامر الصوتية","الاستماع إلى الموسيقى من خلال السيارة"],"h1":"فكّر أين يكون الهاتف.","h2":"تمنع Illinois كل السائقين من استخدام الهاتف المحمول باليد أثناء القيادة. ويجوز للسائقين الذين عمرهم 19 سنة أو أكثر أن يستخدموا هاتفًا بدون اليدين.","p":"صحيح. استخدام الهاتف باليد ممنوع على كل سائق في Illinois."},"ref":{"doc":"IL","page":22}},{"id":"il-011","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, during the first 12 months with a license, how many passengers under 20 may a driver under 18 carry?","o":["None at all","Two","Three","One, not counting brothers, sisters or the driver's children"],"h1":"Family members such as brothers and sisters do not count.","h2":"For the first 12 months of an Illinois license, a driver under 18 may carry only one passenger under 20, not counting siblings or the driver's own children.","p":"Right. Only one young passenger who is not family."},"es":{"q":"En Illinois, durante los primeros 12 meses con licencia, ¿cuántos pasajeros menores de 20 años puede llevar un conductor menor de 18?","o":["Ninguno","Dos","Tres","Uno, sin contar hermanos ni hijos del conductor"],"h1":"Los familiares como hermanos y hermanas no cuentan.","h2":"Durante los primeros 12 meses de licencia en Illinois, un conductor menor de 18 años solo puede llevar un pasajero menor de 20, sin contar hermanos ni sus propios hijos.","p":"Correcto. Solo un pasajero joven que no sea familiar."},"zh":{"q":"在 Illinois，拿到驾照的头 12 个月里，18 岁以下的司机可以载几个 20 岁以下的乘客？","o":["一个都不可以","两个","三个","一个，兄弟姐妹或司机自己的孩子不算"],"h1":"兄弟姐妹这样的家人不算。","h2":"在 Illinois 拿到驾照的头 12 个月里，18 岁以下的司机只能载一个 20 岁以下的乘客，兄弟姐妹或司机自己的孩子不算。","p":"对。只能载一个不是家人的年轻乘客。"},"vi":{"q":"Ở Illinois, trong 12 tháng đầu có bằng lái, người lái dưới 18 tuổi được chở bao nhiêu hành khách dưới 20 tuổi?","o":["Không ai cả","Hai người","Ba người","Một người, không tính anh chị em hoặc con của người lái"],"h1":"Người trong gia đình như anh chị em không được tính.","h2":"Trong 12 tháng đầu có bằng lái ở Illinois, người lái dưới 18 tuổi chỉ được chở một hành khách dưới 20 tuổi, không tính anh chị em hoặc con của chính người lái.","p":"Đúng. Chỉ được chở một hành khách trẻ không phải người trong gia đình."},"tl":{"q":"Sa Illinois, sa unang 12 buwan na may lisensya, ilang pasaherong wala pang 20 ang puwedeng isakay ng driver na wala pang 18?","o":["Wala talaga","Dalawa","Tatlo","Isa, hindi kasama ang mga kapatid o mga anak ng driver"],"h1":"Hindi kasama sa bilang ang mga kapamilya gaya ng mga kapatid.","h2":"Sa unang 12 buwan ng lisensya sa Illinois, ang driver na wala pang 18 ay puwedeng magsakay ng isang pasaherong wala pang 20 lang, hindi kasama ang mga kapatid o ang sariling mga anak ng driver.","p":"Tama. Isang batang pasahero lang na hindi kapamilya."},"ar":{"q":"في Illinois، خلال أول 12 شهرًا مع الرخصة، كم راكبًا عمره أقل من 20 سنة يجوز للسائق الذي عمره أقل من 18 سنة أن ينقل؟","o":["لا أحد أبدًا","اثنان","ثلاثة","واحد، دون حساب الإخوة والأخوات أو أولاد السائق"],"h1":"أفراد العائلة مثل الإخوة والأخوات لا يُحسبون.","h2":"خلال أول 12 شهرًا من رخصة Illinois، يجوز للسائق الذي عمره أقل من 18 سنة أن ينقل راكبًا واحدًا فقط عمره أقل من 20 سنة، دون حساب الإخوة والأخوات أو أولاد السائق نفسه.","p":"صحيح. راكب صغير واحد فقط ليس من العائلة."},"ref":{"doc":"IL","page":18}},{"id":"il-012","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, from Sunday to Thursday, when may a driver under 18 not drive, apart from the allowed exceptions?","o":["From 10 p.m. to 6 a.m.","From 8 p.m. to 6 a.m.","From midnight to 4 a.m.","From 1 a.m. to 5 a.m."],"h1":"It starts at ten at night on school nights.","h2":"In Illinois, a driver under 18 may not drive from 10 p.m. to 6 a.m., Sunday through Thursday, unless an exception applies, such as driving to or from work.","p":"Right. On weeknights the limit starts at 10 p.m."},"es":{"q":"En Illinois, de domingo a jueves, ¿en qué horario no puede manejar un conductor menor de 18 años, fuera de las excepciones permitidas?","o":["De 10 p.m. a 6 a.m.","De 8 p.m. a 6 a.m.","De medianoche a 4 a.m.","De 1 a.m. a 5 a.m."],"h1":"Empieza a las diez de la noche en días de escuela.","h2":"En Illinois un conductor menor de 18 años no puede manejar de 10 p.m. a 6 a.m., de domingo a jueves, salvo una excepción, como ir o volver del trabajo.","p":"Correcto. Entre semana el límite empieza a las 10 p.m."},"zh":{"q":"在 Illinois，星期天到星期四，除了允许的例外情况，18 岁以下的司机什么时间不能开车？","o":["晚上 10 点到早上 6 点","晚上 8 点到早上 6 点","午夜到凌晨 4 点","凌晨 1 点到早上 5 点"],"h1":"在第二天要上学的晚上，从晚上十点开始。","h2":"在 Illinois，星期天到星期四，18 岁以下的司机晚上 10 点到早上 6 点不能开车，除非符合例外情况，例如开车上班或下班。","p":"对。平日晚上的限制从晚上 10 点开始。"},"vi":{"q":"Ở Illinois, từ Chủ Nhật đến thứ Năm, người lái dưới 18 tuổi không được lái xe vào giờ nào, ngoài các trường hợp ngoại lệ được phép?","o":["Từ 10 giờ tối đến 6 giờ sáng","Từ 8 giờ tối đến 6 giờ sáng","Từ nửa đêm đến 4 giờ sáng","Từ 1 giờ sáng đến 5 giờ sáng"],"h1":"Bắt đầu lúc mười giờ tối vào những đêm trước ngày đi học.","h2":"Ở Illinois, người lái dưới 18 tuổi không được lái xe từ 10 giờ tối đến 6 giờ sáng, từ Chủ Nhật đến thứ Năm, trừ khi có ngoại lệ, ví dụ như lái xe đi làm hoặc đi làm về.","p":"Đúng. Vào các đêm trong tuần, giới hạn bắt đầu lúc 10 giờ tối."},"tl":{"q":"Sa Illinois, mula Linggo hanggang Huwebes, kailan hindi puwedeng magmaneho ang driver na wala pang 18, maliban sa mga pinapayagang exception?","o":["Mula 10 p.m. hanggang 6 a.m.","Mula 8 p.m. hanggang 6 a.m.","Mula hatinggabi hanggang 4 a.m.","Mula 1 a.m. hanggang 5 a.m."],"h1":"Nagsisimula ito sa alas-diyes ng gabi sa mga gabing may pasok kinabukasan.","h2":"Sa Illinois, ang driver na wala pang 18 ay hindi puwedeng magmaneho mula 10 p.m. hanggang 6 a.m., Linggo hanggang Huwebes, maliban kung may exception, gaya ng pagmamaneho papunta o pauwi mula sa trabaho.","p":"Tama. Sa mga gabi ng weekday, nagsisimula ang limitasyon sa 10 p.m."},"ar":{"q":"في Illinois، من الأحد إلى الخميس، متى لا يجوز للسائق الذي عمره أقل من 18 سنة أن يقود، باستثناء الحالات المسموح بها؟","o":["من 10 مساءً إلى 6 صباحًا","من 8 مساءً إلى 6 صباحًا","من منتصف الليل إلى 4 صباحًا","من 1 صباحًا إلى 5 صباحًا"],"h1":"يبدأ في الساعة العاشرة ليلًا في ليالي أيام الدراسة.","h2":"في Illinois، لا يجوز للسائق الذي عمره أقل من 18 سنة أن يقود من 10 مساءً إلى 6 صباحًا، من الأحد إلى الخميس، إلا إذا انطبق استثناء، مثل القيادة إلى العمل أو منه.","p":"صحيح. في ليالي أيام الأسبوع يبدأ الحد في 10 مساءً."},"ref":{"doc":"IL","page":18}},{"id":"il-013","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, on Friday and Saturday nights, when does the night driving limit for drivers under 18 begin?","o":["9 p.m.","10 p.m.","11 p.m.","1 a.m."],"h1":"It is one hour later than on school nights.","h2":"In Illinois the weekend night limit for drivers under 18 runs from 11 p.m. to 6 a.m. on Friday and Saturday nights.","p":"Right. On weekends the limit starts at 11 p.m."},"es":{"q":"En Illinois, los viernes y sábados por la noche, ¿a qué hora empieza el límite de manejo nocturno para menores de 18 años?","o":["9 p.m.","10 p.m.","11 p.m.","1 a.m."],"h1":"Es una hora más tarde que en días de escuela.","h2":"En Illinois el límite nocturno de fin de semana para menores de 18 años va de 11 p.m. a 6 a.m. los viernes y sábados.","p":"Correcto. El fin de semana el límite empieza a las 11 p.m."},"zh":{"q":"在 Illinois，星期五和星期六晚上，18 岁以下司机的夜间驾驶限制从几点开始？","o":["晚上 9 点","晚上 10 点","晚上 11 点","凌晨 1 点"],"h1":"比第二天要上学的晚上晚一个小时。","h2":"在 Illinois，星期五和星期六晚上，18 岁以下司机的周末夜间限制是晚上 11 点到早上 6 点。","p":"对。周末的限制从晚上 11 点开始。"},"vi":{"q":"Ở Illinois, vào tối thứ Sáu và thứ Bảy, giới hạn lái xe ban đêm cho người dưới 18 tuổi bắt đầu lúc mấy giờ?","o":["9 giờ tối","10 giờ tối","11 giờ tối","1 giờ sáng"],"h1":"Trễ hơn một giờ so với những đêm trước ngày đi học.","h2":"Ở Illinois, giới hạn ban đêm cuối tuần cho người lái dưới 18 tuổi là từ 11 giờ tối đến 6 giờ sáng vào tối thứ Sáu và thứ Bảy.","p":"Đúng. Vào cuối tuần, giới hạn bắt đầu lúc 11 giờ tối."},"tl":{"q":"Sa Illinois, sa gabi ng Biyernes at Sabado, kailan nagsisimula ang limitasyon sa pagmamaneho sa gabi para sa mga driver na wala pang 18?","o":["9 p.m.","10 p.m.","11 p.m.","1 a.m."],"h1":"Isang oras itong mas huli kaysa sa mga gabing may pasok kinabukasan.","h2":"Sa Illinois, ang limitasyon sa gabi tuwing weekend para sa mga driver na wala pang 18 ay mula 11 p.m. hanggang 6 a.m. sa gabi ng Biyernes at Sabado.","p":"Tama. Tuwing weekend, nagsisimula ang limitasyon sa 11 p.m."},"ar":{"q":"في Illinois، في ليلتي الجمعة والسبت، متى يبدأ حد القيادة الليلية للسائقين الذين عمرهم أقل من 18 سنة؟","o":["9 مساءً","10 مساءً","11 مساءً","1 صباحًا"],"h1":"هو متأخر بساعة واحدة عن ليالي أيام الدراسة.","h2":"في Illinois يمتد حد الليل في نهاية الأسبوع للسائقين الذين عمرهم أقل من 18 سنة من 11 مساءً إلى 6 صباحًا في ليلتي الجمعة والسبت.","p":"صحيح. في نهاية الأسبوع يبدأ الحد في 11 مساءً."},"ref":{"doc":"IL","page":18}},{"id":"il-014","scope":"IL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Illinois, what does Scott's Law tell you to do when you approach a stopped vehicle with flashing emergency or hazard lights?","o":["Speed up to pass quickly","Slow down and change lanes if you safely can","Stop in your lane until it leaves","Honk to warn the people there"],"h1":"This law is also called the Move Over law.","h2":"Scott's Law in Illinois tells you to slow down, change lanes if possible, and pass with caution when a stopped vehicle shows flashing emergency or hazard lights.","p":"Right. Slow down and move over when you safely can."},"es":{"q":"En Illinois, ¿qué le indica la Ley de Scott cuando se acerca a un vehículo detenido con luces de emergencia o intermitentes encendidas?","o":["Acelerar para pasar rápido","Bajar la velocidad y cambiar de carril si puede hacerlo con seguridad","Detenerse en su carril hasta que se vaya","Tocar el claxon para avisar a las personas"],"h1":"Esta ley también se llama ley de \"Move Over\" (cambie de carril).","h2":"La Ley de Scott en Illinois le indica bajar la velocidad, cambiar de carril si es posible y pasar con cuidado cuando un vehículo detenido tiene luces de emergencia o intermitentes.","p":"Correcto. Baje la velocidad y cámbiese de carril si puede hacerlo con seguridad."},"zh":{"q":"在 Illinois，当你靠近一辆闪着紧急灯或双闪灯的停着的车辆时，Scott's Law 要你做什么？","o":["加速快点开过去","减速，如果能安全换道就换道","在你的车道停下，直到它离开","按喇叭提醒那里的人"],"h1":"这条法律也叫做 Move Over 法。","h2":"Illinois 的 Scott's Law 要求，当停着的车辆闪着紧急灯或双闪灯时，你要减速，能换道就换道，并小心地开过去。","p":"对。能安全换道时，减速并换道让开。"},"vi":{"q":"Ở Illinois, Luật Scott (Scott's Law) bảo bạn làm gì khi đến gần một xe đang dừng có bật đèn khẩn cấp hoặc đèn cảnh báo nhấp nháy?","o":["Tăng tốc để vượt qua nhanh","Giảm tốc độ và đổi làn nếu có thể làm một cách an toàn","Dừng lại trong làn của bạn cho đến khi xe đó đi","Bóp còi để cảnh báo những người ở đó"],"h1":"Luật này cũng được gọi là luật Tránh Sang (Move Over).","h2":"Luật Scott ở Illinois bảo bạn giảm tốc độ, đổi làn nếu có thể, và đi qua cẩn thận khi một xe đang dừng bật đèn khẩn cấp hoặc đèn cảnh báo nhấp nháy.","p":"Đúng. Giảm tốc độ và tránh sang làn khác khi có thể làm an toàn."},"tl":{"q":"Sa Illinois, ano ang sinasabi ng Scott's Law na gawin mo kapag papalapit ka sa nakahintong sasakyan na may kumikislap na emergency o hazard lights?","o":["Bumilis para makalampas agad","Bumagal at lumipat ng lane kung ligtas mong magagawa","Huminto sa lane mo hanggang umalis ito","Bumusina para balaan ang mga tao roon"],"h1":"Tinatawag din ang batas na ito na Move Over law.","h2":"Sinasabi ng Scott's Law sa Illinois na bumagal ka, lumipat ng lane kung kaya, at dumaan nang maingat kapag may nakahintong sasakyan na may kumikislap na emergency o hazard lights.","p":"Tama. Bumagal at lumipat ng lane kapag ligtas mong magagawa."},"ar":{"q":"في Illinois، ماذا يطلب منك قانون سكوت (Scott's Law) أن تفعل عندما تقترب من مركبة متوقفة أضواء الطوارئ أو أضواء التحذير فيها تومض؟","o":["أسرع لتتجاوزها بسرعة","خفف السرعة وغيّر المسار إذا استطعت ذلك بأمان","توقف في مسارك حتى تغادر","استخدم البوق لتحذير الناس هناك"],"h1":"يُسمى هذا القانون أيضًا قانون الابتعاد (Move Over).","h2":"يطلب منك قانون سكوت في Illinois أن تخفف السرعة، وأن تغيّر المسار إذا أمكن، وأن تمر بحذر عندما تكون هناك مركبة متوقفة أضواء الطوارئ أو التحذير فيها تومض.","p":"صحيح. خفف السرعة وابتعد إلى مسار آخر عندما تستطيع ذلك بأمان."},"ref":{"doc":"IL","page":25}},{"id":"il-015","scope":"IL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Illinois, besides police and fire vehicles, which stopped vehicles does Scott's Law cover?","o":["Only tow trucks","Only buses","No other vehicles","Any vehicle with its hazard or warning lights flashing"],"h1":"Think of any car that has its flashers on.","h2":"In Illinois, the move-over rule also covers any stopped vehicle with its hazard or warning lights flashing, including ordinary cars and trucks.","p":"Right. Any stopped vehicle with flashing lights is covered."},"es":{"q":"En Illinois, además de policía y bomberos, ¿qué vehículos detenidos cubre la Ley de Scott?","o":["Solo grúas","Solo autobuses","Ningún otro vehículo","Cualquier vehículo con las luces intermitentes o de advertencia encendidas"],"h1":"Piense en cualquier carro con las luces intermitentes encendidas.","h2":"En Illinois, la regla de moverse a otro carril también cubre cualquier vehículo detenido con las luces intermitentes o de advertencia encendidas, incluidos carros y camiones comunes.","p":"Correcto. Cualquier vehículo detenido con luces intermitentes está cubierto."},"zh":{"q":"在 Illinois，除了警车和消防车，Scott's Law 还保护哪些停着的车辆？","o":["只有拖车","只有公交车","没有其他车辆","任何闪着双闪灯或警示灯的车辆"],"h1":"想一想任何开着闪灯的车。","h2":"在 Illinois，换道让开的规定也保护任何停着、闪着双闪灯或警示灯的车辆，包括普通的汽车和卡车。","p":"对。任何停着、闪着灯的车辆都受保护。"},"vi":{"q":"Ở Illinois, ngoài xe cảnh sát và xe cứu hỏa, Luật Scott còn áp dụng cho những xe đang dừng nào?","o":["Chỉ xe kéo","Chỉ xe buýt","Không có xe nào khác","Bất kỳ xe nào đang bật đèn cảnh báo nhấp nháy"],"h1":"Hãy nghĩ đến bất kỳ xe nào đang bật đèn nháy.","h2":"Ở Illinois, luật tránh sang cũng áp dụng cho bất kỳ xe nào đang dừng và bật đèn cảnh báo nhấp nháy, kể cả xe hơi và xe tải bình thường.","p":"Đúng. Bất kỳ xe đang dừng nào có đèn nhấp nháy đều được áp dụng."},"tl":{"q":"Sa Illinois, bukod sa mga sasakyan ng pulis at bumbero, aling mga nakahintong sasakyan ang sakop ng Scott's Law?","o":["Mga tow truck lang","Mga bus lang","Walang ibang sasakyan","Anumang sasakyan na kumikislap ang hazard o warning lights"],"h1":"Isipin ang anumang kotse na nakabukas ang flashers.","h2":"Sa Illinois, sakop din ng move-over rule ang anumang nakahintong sasakyan na kumikislap ang hazard o warning lights, kasama ang mga karaniwang kotse at truck.","p":"Tama. Sakop ang anumang nakahintong sasakyan na may kumikislap na ilaw."},"ar":{"q":"في Illinois، إلى جانب مركبات الشرطة والإطفاء، ما المركبات المتوقفة الأخرى التي يشملها قانون سكوت (Scott's Law)؟","o":["شاحنات السحب فقط","الحافلات فقط","لا توجد مركبات أخرى","أي مركبة أضواء التحذير فيها تومض"],"h1":"فكّر في أي سيارة أضواؤها الوامضة مشغّلة.","h2":"في Illinois، تشمل قاعدة الابتعاد أيضًا أي مركبة متوقفة أضواء التحذير فيها تومض، بما في ذلك السيارات والشاحنات العادية.","p":"صحيح. أي مركبة متوقفة أضواؤها تومض يشملها القانون."},"ref":{"doc":"IL","page":45}},{"id":"il-016","scope":"IL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Illinois, how far from a stopped school bus with its stop arm out must you stop?","o":["At least 20 feet","At least 5 feet","At least 50 feet","At least 100 feet"],"h1":"It is about the length of a large car and a half.","h2":"In Illinois you must stop at least 20 feet before a school bus that has its red lights flashing and stop arm out.","p":"Right. Stop at least 20 feet away."},"es":{"q":"En Illinois, ¿a qué distancia de un autobús escolar detenido con el brazo de alto extendido debe detenerse?","o":["Por lo menos 20 pies","Por lo menos 5 pies","Por lo menos 50 pies","Por lo menos 100 pies"],"h1":"Es más o menos el largo de un carro grande y medio.","h2":"En Illinois usted debe detenerse por lo menos a 20 pies de un autobús escolar que tiene las luces rojas encendidas y el brazo de alto extendido.","p":"Correcto. Deténgase por lo menos a 20 pies."},"zh":{"q":"在 Illinois，你必须在离伸出停车臂的停着的校车多远的地方停车？","o":["至少 20 英尺","至少 5 英尺","至少 50 英尺","至少 100 英尺"],"h1":"大约是一辆半大汽车的长度。","h2":"在 Illinois，你必须在闪着红灯、伸出停车臂的校车前面至少 20 英尺的地方停车。","p":"对。至少在 20 英尺外停车。"},"vi":{"q":"Ở Illinois, bạn phải dừng lại cách xe buýt trường học đang dừng và giơ biển dừng (stop arm) bao xa?","o":["Ít nhất 20 feet","Ít nhất 5 feet","Ít nhất 50 feet","Ít nhất 100 feet"],"h1":"Khoảng chiều dài của một chiếc xe hơi lớn rưỡi.","h2":"Ở Illinois, bạn phải dừng lại cách ít nhất 20 feet trước xe buýt trường học đang bật đèn đỏ nhấp nháy và giơ biển dừng.","p":"Đúng. Dừng lại cách ít nhất 20 feet."},"tl":{"q":"Sa Illinois, gaano kalayo ka dapat huminto mula sa nakahintong school bus na nakalabas ang stop arm?","o":["Hindi bababa sa 20 feet","Hindi bababa sa 5 feet","Hindi bababa sa 50 feet","Hindi bababa sa 100 feet"],"h1":"Mga isa't kalahating haba ito ng malaking kotse.","h2":"Sa Illinois, dapat kang huminto nang hindi bababa sa 20 feet bago ang school bus na kumikislap ang pulang ilaw at nakalabas ang stop arm.","p":"Tama. Huminto nang hindi bababa sa 20 feet ang layo."},"ar":{"q":"في Illinois، على أي مسافة يجب أن تتوقف من حافلة مدرسية متوقفة وذراع التوقف (stop arm) فيها ممدودة؟","o":["20 قدمًا على الأقل","5 أقدام على الأقل","50 قدمًا على الأقل","100 قدم على الأقل"],"h1":"هي تقريبًا طول سيارة كبيرة ونصف.","h2":"في Illinois يجب أن تتوقف على بعد 20 قدمًا على الأقل قبل الحافلة المدرسية التي أضواؤها الحمراء تومض وذراع التوقف فيها ممدودة.","p":"صحيح. توقف على بعد 20 قدمًا على الأقل."},"ref":{"doc":"IL","page":null}},{"id":"il-017","scope":"IL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Illinois, a school bus stops on a road with four or more lanes, two going each way. Who must stop?","o":["Everyone in both directions","Only drivers in the lane next to the bus","Only drivers going the same direction as the bus","No one, if the bus is on the shoulder"],"h1":"On a road this wide, the other side of the road is treated differently.","h2":"In Illinois, on a road with at least two lanes going each way, only drivers traveling in the same direction as the school bus must stop.","p":"Right. Only traffic going the same way as the bus must stop."},"es":{"q":"En Illinois, un autobús escolar se detiene en una vía de cuatro carriles o más, con dos en cada sentido. ¿Quién debe detenerse?","o":["Todos, en ambos sentidos","Solo los conductores en el carril junto al autobús","Solo los conductores que van en el mismo sentido que el autobús","Nadie, si el autobús está en el acotamiento"],"h1":"En una vía tan ancha, el otro lado del camino se trata de otra forma.","h2":"En Illinois, en una vía con por lo menos dos carriles en cada sentido, solo los conductores que van en el mismo sentido que el autobús escolar deben detenerse.","p":"Correcto. Solo el tráfico que va en el mismo sentido que el autobús debe detenerse."},"zh":{"q":"在 Illinois，一辆校车停在有四条或更多车道、每个方向两条车道的路上。谁必须停车？","o":["两个方向的所有人","只有校车旁边车道上的司机","只有和校车同方向行驶的司机","没有人，如果校车停在路肩上"],"h1":"在这么宽的路上，道路另一边的规定不一样。","h2":"在 Illinois，在每个方向至少有两条车道的路上，只有和校车同方向行驶的司机必须停车。","p":"对。只有和校车同方向的车必须停。"},"vi":{"q":"Ở Illinois, một xe buýt trường học dừng trên đường có bốn làn trở lên, mỗi chiều hai làn. Ai phải dừng lại?","o":["Mọi người ở cả hai chiều","Chỉ người lái ở làn sát xe buýt","Chỉ người lái đi cùng chiều với xe buýt","Không ai cả, nếu xe buýt đậu ở lề đường"],"h1":"Trên đường rộng như vậy, phía bên kia đường được đối xử khác.","h2":"Ở Illinois, trên đường có ít nhất hai làn mỗi chiều, chỉ người lái đi cùng chiều với xe buýt trường học mới phải dừng lại.","p":"Đúng. Chỉ xe đi cùng chiều với xe buýt mới phải dừng."},"tl":{"q":"Sa Illinois, huminto ang isang school bus sa kalsadang may apat o higit pang lane, dalawa sa bawat direksyon. Sino ang dapat huminto?","o":["Lahat sa dalawang direksyon","Ang mga driver lang sa lane na katabi ng bus","Ang mga driver lang na papunta sa parehong direksyon ng bus","Wala, kung nasa gilid ng daan ang bus"],"h1":"Sa ganito kalapad na kalsada, iba ang turing sa kabilang panig ng daan.","h2":"Sa Illinois, sa kalsadang may hindi bababa sa dalawang lane sa bawat direksyon, ang mga driver lang na papunta sa parehong direksyon ng school bus ang dapat huminto.","p":"Tama. Ang trapikong papunta lang sa parehong direksyon ng bus ang dapat huminto."},"ar":{"q":"في Illinois، توقفت حافلة مدرسية على طريق فيه أربعة مسارات أو أكثر، مساران في كل اتجاه. من يجب أن يتوقف؟","o":["الجميع في الاتجاهين","السائقون في المسار المجاور للحافلة فقط","السائقون الذين يسيرون في نفس اتجاه الحافلة فقط","لا أحد، إذا كانت الحافلة على كتف الطريق"],"h1":"في طريق بهذا العرض، يُعامَل الجانب الآخر من الطريق بشكل مختلف.","h2":"في Illinois، على طريق فيه مساران على الأقل في كل اتجاه، يجب أن يتوقف فقط السائقون الذين يسيرون في نفس اتجاه الحافلة المدرسية.","p":"صحيح. فقط السيارات التي تسير في نفس اتجاه الحافلة يجب أن تتوقف."},"ref":{"doc":"IL","page":32}},{"id":"il-018","scope":"IL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Illinois, unless a sign says otherwise, what is the speed limit in an urban district?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"It is a round number between 25 and 35.","h2":"Unless a sign says otherwise, the speed limit in an Illinois urban district is 30 miles per hour.","p":"Right. The Illinois urban limit is 30 mph."},"es":{"q":"En Illinois, si no hay un letrero que diga otra cosa, ¿cuál es el límite de velocidad en una zona urbana?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"Es un número redondo entre 25 y 35.","h2":"Si no hay un letrero que diga otra cosa, el límite de velocidad en una zona urbana de Illinois es de 30 millas por hora.","p":"Correcto. El límite urbano en Illinois es de 30 mph."},"zh":{"q":"在 Illinois，如果没有标志另外说明，市区的限速是多少？","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"是 25 和 35 之间的一个整数。","h2":"如果没有标志另外说明，Illinois 市区的限速是 30 mph。","p":"对。Illinois 市区的限速是 30 mph。"},"vi":{"q":"Ở Illinois, nếu không có biển báo nào khác, tốc độ giới hạn trong khu đô thị là bao nhiêu?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"Đó là một số tròn giữa 25 và 35.","h2":"Nếu không có biển báo nào khác, tốc độ giới hạn trong khu đô thị ở Illinois là 30 dặm một giờ.","p":"Đúng. Giới hạn trong đô thị ở Illinois là 30 mph."},"tl":{"q":"Sa Illinois, maliban kung iba ang sinasabi ng karatula, ano ang speed limit sa urban district?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"Isa itong buong numero sa pagitan ng 25 at 35.","h2":"Maliban kung iba ang sinasabi ng karatula, ang speed limit sa urban district sa Illinois ay 30 milya bawat oras.","p":"Tama. Ang limit sa urban na lugar sa Illinois ay 30 mph."},"ar":{"q":"في Illinois، ما لم تقل لافتة غير ذلك، ما حد السرعة في المنطقة الحضرية (urban district)؟","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"هو رقم مستدير بين 25 و35.","h2":"ما لم تقل لافتة غير ذلك، حد السرعة في المنطقة الحضرية في Illinois هو 30 ميلًا في الساعة.","p":"صحيح. الحد في المدن في Illinois هو 30 mph."},"ref":{"doc":"IL","page":24}},{"id":"il-019","scope":"IL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Illinois, what is the speed limit in an alley?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"It is half of the urban limit.","h2":"The speed limit in an Illinois alley is 15 miles per hour.","p":"Right. Alleys in Illinois are 15 mph."},"es":{"q":"En Illinois, ¿cuál es el límite de velocidad en un callejón?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"Es la mitad del límite urbano.","h2":"El límite de velocidad en un callejón de Illinois es de 15 millas por hora.","p":"Correcto. En Illinois los callejones son de 15 mph."},"zh":{"q":"在 Illinois，小巷里的限速是多少？","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"是市区限速的一半。","h2":"Illinois 小巷里的限速是 15 mph。","p":"对。Illinois 的小巷是 15 mph。"},"vi":{"q":"Ở Illinois, tốc độ giới hạn trong hẻm là bao nhiêu?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"Đó là một nửa giới hạn trong đô thị.","h2":"Tốc độ giới hạn trong hẻm ở Illinois là 15 dặm một giờ.","p":"Đúng. Hẻm ở Illinois là 15 mph."},"tl":{"q":"Sa Illinois, ano ang speed limit sa eskinita (alley)?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"Kalahati ito ng limit sa urban na lugar.","h2":"Ang speed limit sa eskinita sa Illinois ay 15 milya bawat oras.","p":"Tama. 15 mph ang mga eskinita sa Illinois."},"ar":{"q":"في Illinois، ما حد السرعة في الزقاق (alley)؟","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"هو نصف حد السرعة في المدينة.","h2":"حد السرعة في الزقاق في Illinois هو 15 ميلًا في الساعة.","p":"صحيح. الأزقة في Illinois حدها 15 mph."},"ref":{"doc":"IL","page":24}},{"id":"il-020","scope":"IL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Illinois, outside urban districts, what is the general speed limit on roads that are not designated highways or interstates?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"It is ten less than the limit on designated four-lane divided highways.","h2":"Outside urban districts in Illinois, the general limit on ordinary roads that are not designated highways or interstates is 55 miles per hour.","p":"Right. Most rural Illinois roads are 55 mph."},"es":{"q":"En Illinois, fuera de las zonas urbanas, ¿cuál es el límite general en caminos que no son carreteras designadas ni interestatales?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"Es diez menos que el límite en carreteras divididas de cuatro carriles designadas.","h2":"Fuera de las zonas urbanas de Illinois, el límite general en caminos comunes que no son carreteras designadas ni interestatales es de 55 millas por hora.","p":"Correcto. La mayoría de los caminos rurales de Illinois son de 55 mph."},"zh":{"q":"在 Illinois，在市区以外，不是指定公路或州际公路的道路，一般限速是多少？","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"比指定的四车道分隔公路的限速少十。","h2":"在 Illinois 市区以外，不是指定公路或州际公路的普通道路，一般限速是 55 mph。","p":"对。Illinois 大多数乡村道路是 55 mph。"},"vi":{"q":"Ở Illinois, bên ngoài khu đô thị, tốc độ giới hạn chung trên những con đường không phải xa lộ được chỉ định hoặc xa lộ liên bang (interstate) là bao nhiêu?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"Ít hơn mười so với giới hạn trên xa lộ bốn làn có dải phân cách được chỉ định.","h2":"Bên ngoài khu đô thị ở Illinois, giới hạn chung trên đường bình thường không phải xa lộ được chỉ định hoặc xa lộ liên bang là 55 dặm một giờ.","p":"Đúng. Phần lớn đường ở vùng nông thôn Illinois là 55 mph."},"tl":{"q":"Sa Illinois, sa labas ng mga urban district, ano ang pangkalahatang speed limit sa mga kalsadang hindi designated highway o interstate?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"Sampu itong mas mababa kaysa sa limit sa mga designated na four-lane divided highway.","h2":"Sa labas ng mga urban district sa Illinois, ang pangkalahatang limit sa mga karaniwang kalsadang hindi designated highway o interstate ay 55 milya bawat oras.","p":"Tama. 55 mph ang karamihan ng mga kalsada sa probinsya ng Illinois."},"ar":{"q":"في Illinois، خارج المناطق الحضرية، ما حد السرعة العام على الطرق التي ليست طرقًا سريعة محددة أو طرقًا سريعة بين الولايات (interstate)؟","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"هو أقل بعشرة من الحد على الطرق السريعة المحددة ذات الأربعة مسارات والمقسومة.","h2":"خارج المناطق الحضرية في Illinois، الحد العام على الطرق العادية التي ليست طرقًا سريعة محددة أو طرقًا بين الولايات هو 55 ميلًا في الساعة.","p":"صحيح. معظم الطرق الريفية في Illinois حدها 55 mph."},"ref":{"doc":"IL","page":24}},{"id":"il-021","scope":"IL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Illinois, unless a sign says otherwise, what is the speed limit on interstates and tollways?","o":["70 mph","55 mph","65 mph","75 mph"],"h1":"It is five more than the limit on four-lane highways.","h2":"Unless a sign says otherwise, the speed limit on Illinois interstates and tollways is 70 miles per hour.","p":"Right. Illinois interstates and tollways are 70 mph."},"es":{"q":"En Illinois, a menos que una señal indique otra cosa, ¿cuál es el límite de velocidad en las autopistas interestatales y de peaje?","o":["70 mph","55 mph","65 mph","75 mph"],"h1":"Es cinco más que el límite en las carreteras de cuatro carriles.","h2":"A menos que una señal indique otra cosa, el límite de velocidad en las autopistas interestatales y de peaje de Illinois es de 70 millas por hora.","p":"Correcto. Las interestatales y autopistas de peaje de Illinois son de 70 mph."},"zh":{"q":"在 Illinois，如果没有标志另外说明，州际公路和收费公路的限速是多少？","o":["70 mph","55 mph","65 mph","75 mph"],"h1":"比四车道公路的限速多五。","h2":"如果没有标志另外说明，Illinois 州际公路和收费公路的限速是 70 mph。","p":"对。Illinois 的州际公路和收费公路是 70 mph。"},"vi":{"q":"Ở Illinois, nếu không có biển báo nào khác, tốc độ giới hạn trên xa lộ liên bang (interstate) và đường thu phí (tollway) là bao nhiêu?","o":["70 mph","55 mph","65 mph","75 mph"],"h1":"Nhiều hơn năm so với giới hạn trên xa lộ bốn làn.","h2":"Nếu không có biển báo nào khác, tốc độ giới hạn trên xa lộ liên bang và đường thu phí ở Illinois là 70 dặm một giờ.","p":"Đúng. Xa lộ liên bang và đường thu phí ở Illinois là 70 mph."},"tl":{"q":"Sa Illinois, maliban kung iba ang sinasabi ng karatula, ano ang speed limit sa mga interstate at tollway?","o":["70 mph","55 mph","65 mph","75 mph"],"h1":"Lima itong mas mataas kaysa sa limit sa mga four-lane highway.","h2":"Maliban kung iba ang sinasabi ng karatula, ang speed limit sa mga interstate at tollway sa Illinois ay 70 milya bawat oras.","p":"Tama. 70 mph ang mga interstate at tollway sa Illinois."},"ar":{"q":"في Illinois، ما لم تقل لافتة غير ذلك، ما حد السرعة على الطرق السريعة بين الولايات (interstate) والطرق ذات الرسوم (tollway)؟","o":["70 mph","55 mph","65 mph","75 mph"],"h1":"هو أكثر بخمسة من الحد على الطرق السريعة ذات الأربعة مسارات.","h2":"ما لم تقل لافتة غير ذلك، حد السرعة على الطرق السريعة بين الولايات والطرق ذات الرسوم في Illinois هو 70 ميلًا في الساعة.","p":"صحيح. الطرق بين الولايات والطرق ذات الرسوم في Illinois حدها 70 mph."},"ref":{"doc":"IL","page":24}},{"id":"il-022","scope":"IL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Illinois, how much alcohol may a driver under 21 have in the blood?","o":["Up to 0.08","Up to 0.05","Up to 0.02","None at all"],"h1":"Illinois calls this zero tolerance.","h2":"Under the Illinois zero tolerance law, a driver under 21 may not drive with any alcohol in the blood.","p":"Right. Under 21, no alcohol at all."},"es":{"q":"En Illinois, ¿cuánto alcohol puede tener en la sangre un conductor menor de 21 años?","o":["Hasta 0.08","Hasta 0.05","Hasta 0.02","Nada de alcohol"],"h1":"Illinois llama a esto tolerancia cero.","h2":"Según la ley de tolerancia cero de Illinois, un conductor menor de 21 años no puede manejar con nada de alcohol en la sangre.","p":"Correcto. Menor de 21, nada de alcohol."},"zh":{"q":"在 Illinois，21 岁以下的司机血液里可以有多少酒精？","o":["最多 0.08","最多 0.05","最多 0.02","一点都不可以"],"h1":"Illinois 把这个规定叫做零容忍。","h2":"根据 Illinois 的零容忍法，21 岁以下的司机血液里有任何酒精都不能开车。","p":"对。21 岁以下，一点酒精都不可以。"},"vi":{"q":"Ở Illinois, người lái dưới 21 tuổi được có bao nhiêu cồn trong máu?","o":["Tối đa 0.08","Tối đa 0.05","Tối đa 0.02","Không có chút nào"],"h1":"Illinois gọi điều này là không khoan nhượng (zero tolerance).","h2":"Theo luật không khoan nhượng của Illinois, người lái dưới 21 tuổi không được lái xe khi có bất kỳ chút cồn nào trong máu.","p":"Đúng. Dưới 21 tuổi, không được có chút cồn nào."},"tl":{"q":"Sa Illinois, gaano karaming alak ang puwedeng nasa dugo ng driver na wala pang 21?","o":["Hanggang 0.08","Hanggang 0.05","Hanggang 0.02","Wala talaga"],"h1":"Tinatawag ito ng Illinois na zero tolerance.","h2":"Ayon sa zero tolerance law ng Illinois, ang driver na wala pang 21 ay hindi puwedeng magmaneho nang may kahit anong alak sa dugo.","p":"Tama. Kapag wala pang 21, bawal ang kahit kaunting alak."},"ar":{"q":"في Illinois، كم من الكحول يجوز أن يكون في دم السائق الذي عمره أقل من 21 سنة؟","o":["حتى 0.08","حتى 0.05","حتى 0.02","لا شيء أبدًا"],"h1":"تسمي Illinois هذا عدم التسامح (zero tolerance).","h2":"بموجب قانون عدم التسامح في Illinois، لا يجوز للسائق الذي عمره أقل من 21 سنة أن يقود وفي دمه أي كمية من الكحول.","p":"صحيح. تحت 21 سنة، لا كحول أبدًا."},"ref":{"doc":"IL","page":52}},{"id":"il-023","scope":"IL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Illinois, what is the license suspension for a first zero tolerance violation by a driver under 21?","o":["One week","3 months","2 years","No suspension, only a warning"],"h1":"It is one quarter of a year.","h2":"In Illinois, a driver under 21 found with any alcohol while driving loses the license for at least three months.","p":"Right. A first violation means at least a three-month suspension."},"es":{"q":"En Illinois, ¿cuál es la suspensión de licencia por una primera violación de tolerancia cero de un conductor menor de 21?","o":["Una semana","3 meses","2 años","Ninguna, solo una advertencia"],"h1":"Es la cuarta parte de un año.","h2":"En Illinois, un conductor menor de 21 años que maneja con cualquier cantidad de alcohol pierde la licencia por al menos tres meses.","p":"Correcto. Una primera violación significa al menos tres meses de suspensión."},"zh":{"q":"在 Illinois，21 岁以下的司机第一次违反零容忍规定，驾照会被暂停多久？","o":["一个星期","3 个月","2 年","不暂停，只是警告"],"h1":"是四分之一年。","h2":"在 Illinois，21 岁以下的司机开车时被发现有任何酒精，驾照会被暂停至少三个月。","p":"对。第一次违规，驾照至少暂停三个月。"},"vi":{"q":"Ở Illinois, người lái dưới 21 tuổi vi phạm luật không khoan nhượng (zero tolerance) lần đầu bị treo bằng lái bao lâu?","o":["Một tuần","3 tháng","2 năm","Không bị treo, chỉ bị cảnh cáo"],"h1":"Đó là một phần tư của một năm.","h2":"Ở Illinois, người lái dưới 21 tuổi bị phát hiện có bất kỳ chút cồn nào khi lái xe sẽ bị mất bằng lái ít nhất ba tháng.","p":"Đúng. Vi phạm lần đầu nghĩa là bị treo bằng ít nhất ba tháng."},"tl":{"q":"Sa Illinois, gaano katagal ang suspensyon ng lisensya sa unang zero tolerance violation ng driver na wala pang 21?","o":["Isang linggo","3 buwan","2 taon","Walang suspensyon, babala lang"],"h1":"Isang-kapat ito ng isang taon.","h2":"Sa Illinois, ang driver na wala pang 21 na nahulihan ng kahit anong alak habang nagmamaneho ay mawawalan ng lisensya nang hindi bababa sa tatlong buwan.","p":"Tama. Ang unang violation ay nangangahulugan ng suspensyon na hindi bababa sa tatlong buwan."},"ar":{"q":"في Illinois، ما مدة إيقاف الرخصة في أول مخالفة لقانون عدم التسامح (zero tolerance) من سائق عمره أقل من 21 سنة؟","o":["أسبوع واحد","3 أشهر","سنتان","لا إيقاف، تحذير فقط"],"h1":"هي ربع سنة.","h2":"في Illinois، السائق الذي عمره أقل من 21 سنة ويوجد في دمه أي كحول أثناء القيادة يفقد رخصته ثلاثة أشهر على الأقل.","p":"صحيح. أول مخالفة تعني إيقاف الرخصة ثلاثة أشهر على الأقل."},"ref":{"doc":"IL","page":52}},{"id":"il-024","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, when all cars are insured and no one is hurt, above what amount of property damage must the driver file a crash report?","o":["$250","$500","$1,500","$5,000"],"h1":"It is between one thousand and two thousand dollars.","h2":"In Illinois, a driver must file a crash report when no one is hurt but the property damage is more than $1,500.","p":"Right. Damage over $1,500 means you must file a report."},"es":{"q":"En Illinois, cuando todos los autos tienen seguro y nadie está herido, ¿a partir de qué cantidad de daños a la propiedad debe el conductor presentar un informe del choque?","o":["$250","$500","$1,500","$5,000"],"h1":"Está entre mil y dos mil dólares.","h2":"En Illinois, el conductor debe presentar un informe del choque cuando nadie está herido pero los daños a la propiedad pasan de $1,500.","p":"Correcto. Con daños de más de $1,500 usted debe presentar un informe."},"zh":{"q":"在 Illinois，如果所有车辆都有保险，而且没有人受伤，财产损失超过多少钱时，司机必须提交事故报告？","o":["$250","$500","$1,500","$5,000"],"h1":"它在一千美元和两千美元之间。","h2":"在 Illinois，如果没有人受伤，但财产损失超过 $1,500，司机必须提交事故报告。","p":"对。损失超过 $1,500，你就必须提交报告。"},"vi":{"q":"Ở Illinois, khi tất cả xe đều có bảo hiểm và không ai bị thương, thiệt hại tài sản trên bao nhiêu thì tài xế phải nộp báo cáo tai nạn?","o":["$250","$500","$1,500","$5,000"],"h1":"Số tiền nằm trong khoảng từ một nghìn đến hai nghìn đô la.","h2":"Ở Illinois, tài xế phải nộp báo cáo tai nạn khi không ai bị thương nhưng thiệt hại tài sản trên $1,500.","p":"Đúng. Thiệt hại trên $1,500 thì bạn phải nộp báo cáo."},"tl":{"q":"Sa Illinois, kapag may insurance ang lahat ng sasakyan at walang nasaktan, lampas sa anong halaga ng pinsala sa ari-arian dapat mag-file ng crash report ang driver?","o":["$250","$500","$1,500","$5,000"],"h1":"Nasa pagitan ito ng isang libo at dalawang libong dolyar.","h2":"Sa Illinois, dapat mag-file ng crash report ang driver kapag walang nasaktan pero lampas sa $1,500 ang pinsala sa ari-arian.","p":"Tama. Kapag lampas sa $1,500 ang pinsala, dapat kang mag-file ng report."},"ar":{"q":"في Illinois، عندما تكون كل السيارات مؤمَّنة ولا يُصاب أحد، فوق أي مبلغ من الأضرار في الممتلكات يجب على السائق تقديم تقرير عن الحادث؟","o":["$250","$500","$1,500","$5,000"],"h1":"المبلغ بين ألف وألفي دولار.","h2":"في Illinois، يجب على السائق تقديم تقرير عن الحادث عندما لا يُصاب أحد ولكن الأضرار في الممتلكات أكثر من $1,500.","p":"صحيح. إذا كانت الأضرار أكثر من $1,500 فيجب أن تقدّم تقريرًا."},"ref":{"doc":"IL","page":54}},{"id":"il-025","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, what is the minimum liability insurance a vehicle must carry?","o":["$25,000 / $50,000 / $20,000","$10,000 / $20,000 / $5,000","$15,000 / $30,000 / $10,000","$100,000 / $300,000 / $50,000"],"h1":"Injury to one person is covered for twenty-five thousand dollars.","h2":"In Illinois, the minimum is $25,000 for one person hurt or killed, $50,000 for more than one person, and $20,000 for damage to property.","p":"Right. Illinois requires at least $25,000, $50,000 and $20,000 of coverage."},"es":{"q":"En Illinois, ¿cuál es el seguro de responsabilidad civil mínimo que debe tener un vehículo?","o":["$25,000 / $50,000 / $20,000","$10,000 / $20,000 / $5,000","$15,000 / $30,000 / $10,000","$100,000 / $300,000 / $50,000"],"h1":"Las lesiones de una persona están cubiertas por veinticinco mil dólares.","h2":"En Illinois, el mínimo es $25,000 por una persona herida o muerta, $50,000 por más de una persona y $20,000 por daños a la propiedad.","p":"Correcto. Illinois exige al menos $25,000, $50,000 y $20,000 de cobertura."},"zh":{"q":"在 Illinois，车辆必须有的最低责任保险是多少？","o":["$25,000 / $50,000 / $20,000","$10,000 / $20,000 / $5,000","$15,000 / $30,000 / $10,000","$100,000 / $300,000 / $50,000"],"h1":"一个人受伤的赔偿额是两万五千美元。","h2":"在 Illinois，最低保险是：一人受伤或死亡 $25,000，多于一人 $50,000，财产损失 $20,000。","p":"对。Illinois 要求至少 $25,000、$50,000 和 $20,000 的保险。"},"vi":{"q":"Ở Illinois, xe phải có bảo hiểm trách nhiệm tối thiểu là bao nhiêu?","o":["$25,000 / $50,000 / $20,000","$10,000 / $20,000 / $5,000","$15,000 / $30,000 / $10,000","$100,000 / $300,000 / $50,000"],"h1":"Thương tích cho một người được bảo hiểm hai mươi lăm nghìn đô la.","h2":"Ở Illinois, mức tối thiểu là $25,000 khi một người bị thương hoặc chết, $50,000 khi nhiều hơn một người, và $20,000 cho thiệt hại tài sản.","p":"Đúng. Illinois yêu cầu bảo hiểm ít nhất $25,000, $50,000 và $20,000."},"tl":{"q":"Sa Illinois, ano ang pinakamababang liability insurance na dapat mayroon ang sasakyan?","o":["$25,000 / $50,000 / $20,000","$10,000 / $20,000 / $5,000","$15,000 / $30,000 / $10,000","$100,000 / $300,000 / $50,000"],"h1":"Dalawampu't limang libong dolyar ang sakop para sa pinsala sa isang tao.","h2":"Sa Illinois, ang pinakamababa ay $25,000 para sa isang taong nasaktan o namatay, $50,000 para sa higit sa isang tao, at $20,000 para sa pinsala sa ari-arian.","p":"Tama. Hinihingi ng Illinois ang hindi bababa sa $25,000, $50,000 at $20,000 na coverage."},"ar":{"q":"في Illinois، ما الحد الأدنى من تأمين المسؤولية الذي يجب أن يكون للسيارة؟","o":["$25,000 / $50,000 / $20,000","$10,000 / $20,000 / $5,000","$15,000 / $30,000 / $10,000","$100,000 / $300,000 / $50,000"],"h1":"إصابة شخص واحد مغطاة بخمسة وعشرين ألف دولار.","h2":"في Illinois، الحد الأدنى هو $25,000 لإصابة أو وفاة شخص واحد، و$50,000 لأكثر من شخص، و$20,000 للأضرار في الممتلكات.","p":"صحيح. تطلب Illinois تأمينًا لا يقل عن $25,000 و$50,000 و$20,000."},"ref":{"doc":"IL","page":98}},{"id":"il-026","scope":"IL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Illinois, children under what age must ride in a child safety seat or booster seat?","o":["Under 2","Under 4","Under 12","Under 8"],"h1":"From this age on, the regular seat belt law applies.","h2":"In Illinois, all children under age 8 must be secured in a child safety seat or booster seat that fits them.","p":"Right. Children under 8 need a child safety seat or booster seat."},"es":{"q":"En Illinois, ¿los niños menores de qué edad deben ir en un asiento de seguridad infantil o un asiento elevado?","o":["Menores de 2","Menores de 4","Menores de 12","Menores de 8"],"h1":"A partir de esa edad se aplica la ley normal del cinturón de seguridad.","h2":"En Illinois, todos los niños menores de 8 años deben ir sujetos en un asiento de seguridad infantil o asiento elevado adecuado para ellos.","p":"Correcto. Los niños menores de 8 años necesitan un asiento de seguridad infantil o asiento elevado."},"zh":{"q":"在 Illinois，多大年龄以下的儿童必须坐儿童安全座椅或增高座椅？","o":["2 岁以下","4 岁以下","12 岁以下","8 岁以下"],"h1":"从这个年龄开始，适用普通的安全带法律。","h2":"在 Illinois，所有 8 岁以下的儿童都必须坐在适合他们的儿童安全座椅或增高座椅里，并固定好。","p":"对。8 岁以下的儿童需要儿童安全座椅或增高座椅。"},"vi":{"q":"Ở Illinois, trẻ em dưới bao nhiêu tuổi phải ngồi ghế an toàn cho trẻ em hoặc ghế nâng?","o":["Dưới 2 tuổi","Dưới 4 tuổi","Dưới 12 tuổi","Dưới 8 tuổi"],"h1":"Từ tuổi này trở đi, luật dây an toàn thông thường được áp dụng.","h2":"Ở Illinois, tất cả trẻ em dưới 8 tuổi phải được giữ chặt trong ghế an toàn cho trẻ em hoặc ghế nâng vừa với các em.","p":"Đúng. Trẻ em dưới 8 tuổi cần ghế an toàn cho trẻ em hoặc ghế nâng."},"tl":{"q":"Sa Illinois, ang mga batang wala pa sa anong edad ang dapat nakaupo sa child safety seat o booster seat?","o":["Wala pang 2","Wala pang 4","Wala pang 12","Wala pang 8"],"h1":"Mula sa edad na ito, ang karaniwang batas sa seat belt na ang sinusunod.","h2":"Sa Illinois, lahat ng batang wala pang 8 taong gulang ay dapat nakakabit sa child safety seat o booster seat na akma sa kanila.","p":"Tama. Kailangan ng child safety seat o booster seat ang mga batang wala pang 8."},"ar":{"q":"في Illinois، الأطفال تحت أي عمر يجب أن يجلسوا في مقعد أمان للأطفال أو مقعد رافع؟","o":["تحت 2","تحت 4","تحت 12","تحت 8"],"h1":"من هذا العمر فما فوق، يُطبَّق قانون حزام الأمان العادي.","h2":"في Illinois، يجب تثبيت كل الأطفال تحت عمر 8 سنوات في مقعد أمان للأطفال أو مقعد رافع مناسب لهم.","p":"صحيح. الأطفال تحت 8 سنوات يحتاجون إلى مقعد أمان للأطفال أو مقعد رافع."},"ref":{"doc":"IL","page":23}},{"id":"il-027","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, how many tries do you get to pass each exam after you pay the application fee?","o":["Two tries within six months","Three tries within one year","Five tries within one year","As many tries as you want"],"h1":"The time limit is one year from the day you paid.","h2":"In Illinois, you get three tries to pass each exam within one year from the date you paid the application fee.","p":"Right. You have three tries within one year."},"es":{"q":"En Illinois, ¿cuántos intentos tiene para aprobar cada examen después de pagar la tarifa de solicitud?","o":["Dos intentos en seis meses","Tres intentos en un año","Cinco intentos en un año","Todos los intentos que quiera"],"h1":"El plazo es de un año desde el día en que pagó.","h2":"En Illinois, usted tiene tres intentos para aprobar cada examen dentro de un año desde la fecha en que pagó la tarifa de solicitud.","p":"Correcto. Tiene tres intentos dentro de un año."},"zh":{"q":"在 Illinois，交了申请费以后，每项考试你有几次机会通过？","o":["六个月内两次","一年内三次","一年内五次","想考几次都可以"],"h1":"期限是从你交费那天起一年。","h2":"在 Illinois，从你交申请费那天起一年内，每项考试你有三次机会通过。","p":"对。你在一年内有三次机会。"},"vi":{"q":"Ở Illinois, sau khi trả phí nộp đơn, bạn có bao nhiêu lần thi để đậu mỗi bài thi?","o":["Hai lần trong vòng sáu tháng","Ba lần trong vòng một năm","Năm lần trong vòng một năm","Bao nhiêu lần cũng được"],"h1":"Thời hạn là một năm kể từ ngày bạn trả tiền.","h2":"Ở Illinois, bạn có ba lần thi để đậu mỗi bài thi trong vòng một năm kể từ ngày bạn trả phí nộp đơn.","p":"Đúng. Bạn có ba lần thi trong vòng một năm."},"tl":{"q":"Sa Illinois, ilang pagkakataon ang mayroon ka para pumasa sa bawat exam pagkatapos mong bayaran ang application fee?","o":["Dalawang pagkakataon sa loob ng anim na buwan","Tatlong pagkakataon sa loob ng isang taon","Limang pagkakataon sa loob ng isang taon","Kahit ilang beses mo gusto"],"h1":"Ang takdang panahon ay isang taon mula sa araw na nagbayad ka.","h2":"Sa Illinois, may tatlong pagkakataon ka para pumasa sa bawat exam sa loob ng isang taon mula sa petsa na binayaran mo ang application fee.","p":"Tama. May tatlong pagkakataon ka sa loob ng isang taon."},"ar":{"q":"في Illinois، كم محاولة لديك لتنجح في كل اختبار بعد أن تدفع رسوم الطلب؟","o":["محاولتان خلال ستة أشهر","ثلاث محاولات خلال سنة واحدة","خمس محاولات خلال سنة واحدة","عدد المحاولات الذي تريده"],"h1":"المهلة سنة واحدة من يوم الدفع.","h2":"في Illinois، لديك ثلاث محاولات لتنجح في كل اختبار خلال سنة واحدة من تاريخ دفع رسوم الطلب.","p":"صحيح. لديك ثلاث محاولات خلال سنة واحدة."},"ref":{"doc":"IL","page":13}},{"id":"il-028","scope":"IL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Illinois, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 15 feet","No closer than 30 feet","No closer than 50 feet"],"h1":"Fire trucks need room to hook up their hoses.","h2":"In Illinois, you may not park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a hydrant."},"es":{"q":"En Illinois, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 15 pies","No más cerca de 30 pies","No más cerca de 50 pies"],"h1":"Los bomberos necesitan espacio para conectar sus mangueras.","h2":"En Illinois, usted no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese al menos a 15 pies de un hidrante."},"zh":{"q":"在 Illinois，你可以把车停在离消防栓多近的地方？","o":["不能近于 5 英尺","不能近于 15 英尺","不能近于 30 英尺","不能近于 50 英尺"],"h1":"消防车需要地方接上水管。","h2":"在 Illinois，你不能把车停在离消防栓 15 英尺以内的地方。","p":"对。离消防栓至少 15 英尺。"},"vi":{"q":"Ở Illinois, bạn được đỗ xe gần trụ nước cứu hỏa đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 15 feet","Không gần hơn 30 feet","Không gần hơn 50 feet"],"h1":"Xe cứu hỏa cần chỗ để nối ống nước.","h2":"Ở Illinois, bạn không được đỗ xe trong vòng 15 feet tính từ trụ nước cứu hỏa.","p":"Đúng. Hãy cách trụ nước cứu hỏa ít nhất 15 feet."},"tl":{"q":"Sa Illinois, gaano kalapit sa fire hydrant ka puwedeng pumarada?","o":["Hindi mas malapit sa 5 feet","Hindi mas malapit sa 15 feet","Hindi mas malapit sa 30 feet","Hindi mas malapit sa 50 feet"],"h1":"Kailangan ng mga fire truck ng espasyo para ikabit ang kanilang mga hose.","h2":"Sa Illinois, hindi ka puwedeng pumarada sa loob ng 15 feet mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 15 feet mula sa hydrant."},"ar":{"q":"في Illinois، إلى أي مدى يمكنك أن تركن سيارتك قرب حنفية إطفاء الحريق؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 30 قدمًا","ليس أقرب من 50 قدمًا"],"h1":"تحتاج سيارات الإطفاء إلى مكان لتوصيل خراطيمها.","h2":"في Illinois لا يجوز لك أن تركن سيارتك على بعد أقل من 15 قدمًا من حنفية إطفاء الحريق.","p":"صحيح. ابقَ على بعد 15 قدمًا على الأقل من حنفية الإطفاء."},"ref":{"doc":"IL","page":35}},{"id":"il-030","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, what happens if your vision tests between 20/41 and 20/70?","o":["You may drive only in daylight","You may not get a license at all","You may drive only on interstates","You get no limit on your license"],"h1":"The limit is about the time of day you may drive.","h2":"In Illinois, a driver whose vision is between 20/41 and 20/70 may drive only during daylight.","p":"Right. With that vision you may drive only in daylight."},"es":{"q":"En Illinois, ¿qué pasa si su prueba de la vista da entre 20/41 y 20/70?","o":["Solo puede manejar de día","No puede obtener licencia","Solo puede manejar en autopistas interestatales","Su licencia no tiene ningún límite"],"h1":"El límite tiene que ver con la hora del día en que puede manejar.","h2":"En Illinois, un conductor con una vista entre 20/41 y 20/70 solo puede manejar durante el día.","p":"Correcto. Con esa vista solo puede manejar de día."},"zh":{"q":"在 Illinois，如果你的视力检查结果在 20/41 到 20/70 之间，会怎么样？","o":["你只能在白天开车","你完全不能拿驾照","你只能在州际公路上开车","你的驾照没有任何限制"],"h1":"这个限制和你可以开车的时间有关。","h2":"在 Illinois，视力在 20/41 到 20/70 之间的司机只能在白天开车。","p":"对。这样的视力只能在白天开车。"},"vi":{"q":"Ở Illinois, điều gì xảy ra nếu kết quả kiểm tra thị lực của bạn nằm trong khoảng 20/41 đến 20/70?","o":["Bạn chỉ được lái xe vào ban ngày","Bạn hoàn toàn không được cấp bằng lái","Bạn chỉ được lái xe trên xa lộ liên bang","Bằng lái của bạn không có giới hạn nào"],"h1":"Giới hạn này liên quan đến thời gian trong ngày bạn được lái xe.","h2":"Ở Illinois, người lái xe có thị lực trong khoảng 20/41 đến 20/70 chỉ được lái xe vào ban ngày.","p":"Đúng. Với thị lực đó, bạn chỉ được lái xe vào ban ngày."},"tl":{"q":"Sa Illinois, ano ang mangyayari kung ang resulta ng vision test mo ay nasa pagitan ng 20/41 at 20/70?","o":["Puwede ka lang magmaneho kapag may liwanag ng araw","Hindi ka talaga makakakuha ng lisensya","Puwede ka lang magmaneho sa mga interstate","Walang limitasyon ang lisensya mo"],"h1":"Ang limitasyon ay tungkol sa oras ng araw na puwede kang magmaneho.","h2":"Sa Illinois, ang driver na may paningin na nasa pagitan ng 20/41 at 20/70 ay puwede lang magmaneho kapag may liwanag ng araw.","p":"Tama. Sa ganyang paningin, puwede ka lang magmaneho kapag may liwanag ng araw."},"ar":{"q":"في Illinois، ماذا يحدث إذا كانت نتيجة فحص نظرك بين 20/41 و 20/70؟","o":["يمكنك القيادة في النهار فقط","لا يمكنك الحصول على رخصة أبدًا","يمكنك القيادة على الطرق السريعة بين الولايات فقط","لا يوجد أي قيد على رخصتك"],"h1":"القيد له علاقة بالوقت من اليوم الذي يمكنك القيادة فيه.","h2":"في Illinois، السائق الذي نظره بين 20/41 و 20/70 يمكنه القيادة في النهار فقط.","p":"صحيح. مع هذا النظر يمكنك القيادة في النهار فقط."},"ref":{"doc":"IL","page":13}},{"id":"il-031","scope":"IL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Illinois, when you pass on a two-lane road, how far from an oncoming vehicle must you be back in your lane?","o":["At least 50 feet","At least 100 feet","At least 200 feet","At least 500 feet"],"h1":"The distance is more than half a football field.","h2":"In Illinois, you must be back in your own lane before you get within 200 feet of an oncoming vehicle.","p":"Right. Be back in your lane at least 200 feet before an oncoming vehicle."},"es":{"q":"En Illinois, al rebasar en un camino de dos carriles, ¿a qué distancia de un vehículo que viene de frente debe estar ya en su carril?","o":["Al menos 50 pies","Al menos 100 pies","Al menos 200 pies","Al menos 500 pies"],"h1":"La distancia es más de la mitad de un campo de fútbol americano.","h2":"En Illinois, usted debe volver a su carril antes de quedar a menos de 200 pies de un vehículo que viene de frente.","p":"Correcto. Vuelva a su carril al menos 200 pies antes del vehículo que viene."},"zh":{"q":"在 Illinois，你在双车道道路上超车时，必须在离对面来车多远之前回到自己的车道？","o":["至少 50 英尺","至少 100 英尺","至少 200 英尺","至少 500 英尺"],"h1":"这个距离比半个美式足球场还长。","h2":"在 Illinois，你必须在离对面来车 200 英尺以前回到自己的车道。","p":"对。在离对面来车至少 200 英尺时回到自己的车道。"},"vi":{"q":"Ở Illinois, khi vượt xe trên đường hai làn, bạn phải trở về làn của mình khi còn cách xe đi ngược chiều bao xa?","o":["Ít nhất 50 feet","Ít nhất 100 feet","Ít nhất 200 feet","Ít nhất 500 feet"],"h1":"Khoảng cách này dài hơn nửa sân bóng bầu dục.","h2":"Ở Illinois, bạn phải trở về làn của mình trước khi đến gần xe đi ngược chiều trong vòng 200 feet.","p":"Đúng. Hãy trở về làn của mình khi còn cách xe đi ngược chiều ít nhất 200 feet."},"tl":{"q":"Sa Illinois, kapag nag-overtake ka sa kalsadang may dalawang lane, gaano kalayo sa paparating na sasakyan ka dapat nakabalik na sa lane mo?","o":["Hindi bababa sa 50 feet","Hindi bababa sa 100 feet","Hindi bababa sa 200 feet","Hindi bababa sa 500 feet"],"h1":"Mas mahaba ang layo kaysa sa kalahati ng football field.","h2":"Sa Illinois, dapat nakabalik ka na sa sarili mong lane bago ka umabot sa loob ng 200 feet mula sa paparating na sasakyan.","p":"Tama. Bumalik sa lane mo nang hindi bababa sa 200 feet bago ang paparating na sasakyan."},"ar":{"q":"في Illinois، عندما تتجاوز على طريق له مساران، على أي مسافة من السيارة القادمة من الاتجاه المقابل يجب أن تكون قد رجعت إلى مسارك؟","o":["50 قدمًا على الأقل","100 قدم على الأقل","200 قدم على الأقل","500 قدم على الأقل"],"h1":"المسافة أكثر من نصف ملعب كرة القدم الأمريكية.","h2":"في Illinois يجب أن ترجع إلى مسارك قبل أن تصبح على بعد أقل من 200 قدم من السيارة القادمة من الاتجاه المقابل.","p":"صحيح. ارجع إلى مسارك قبل السيارة القادمة بـ 200 قدم على الأقل."},"ref":{"doc":"IL","page":28}},{"id":"il-032","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, you move here with a valid license from another state. How soon must you get an Illinois license?","o":["Within 10 days","Within 30 days","Within 90 days","Within 1 year"],"h1":"You get about three months, unless your old license runs out first.","h2":"A new Illinois resident must get an Illinois license within 90 days, or sooner if the old license expires first.","p":"Right. New residents have 90 days."},"es":{"q":"En Illinois, usted se muda aquí con una licencia válida de otro estado. ¿En cuánto tiempo debe sacar una licencia de Illinois?","o":["En 10 días","En 30 días","En 90 días","En 1 año"],"h1":"Tiene unos tres meses, a menos que su licencia anterior venza antes.","h2":"Un nuevo residente de Illinois debe sacar una licencia de Illinois en 90 días, o antes si la licencia anterior vence primero.","p":"Correcto. Los nuevos residentes tienen 90 días."},"ref":{"doc":"IL","page":5}},{"id":"il-033","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, after you move to a new address, how soon must you tell the Secretary of State?","o":["Within 10 days","Within 30 days","Within 60 days","Within 6 months"],"h1":"It is a short time, less than two weeks.","h2":"In Illinois, you must report a change of address to the Secretary of State within 10 days of moving.","p":"Right. Report a new address within 10 days."},"es":{"q":"En Illinois, después de mudarse a una nueva dirección, ¿en cuánto tiempo debe avisar a la Secretaría de Estado?","o":["En 10 días","En 30 días","En 60 días","En 6 meses"],"h1":"Es poco tiempo, menos de dos semanas.","h2":"En Illinois, usted debe informar un cambio de dirección a la Secretaría de Estado en 10 días después de mudarse.","p":"Correcto. Informe su nueva dirección en 10 días."},"ref":{"doc":"IL","page":6}},{"id":"il-034","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, for most adult drivers, how long is a driver's license valid?","o":["2 years","4 years","6 years","8 years"],"h1":"Drivers over 80 renew more often than most adults.","h2":"For most adult drivers in Illinois, a driver's license is valid for four years and expires on the driver's birthday.","p":"Right. Most Illinois licenses last four years."},"es":{"q":"En Illinois, para la mayoría de los conductores adultos, ¿por cuánto tiempo es válida la licencia de conducir?","o":["2 años","4 años","6 años","8 años"],"h1":"Los conductores mayores de 80 años renuevan más seguido que la mayoría de los adultos.","h2":"Para la mayoría de los conductores adultos en Illinois, la licencia de conducir es válida por cuatro años y vence el día del cumpleaños del conductor.","p":"Correcto. La mayoría de las licencias de Illinois duran cuatro años."},"ref":{"doc":"IL","page":8}},{"id":"il-035","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, when does a license issued to a driver under 21 expire?","o":["3 months after the 21st birthday","On the 21st birthday","On the 18th birthday","1 year after the 21st birthday"],"h1":"It is a little while after the driver turns 21.","h2":"In Illinois, a license issued to a driver under 21 expires three months after the driver's 21st birthday.","p":"Right. It expires three months after turning 21."},"es":{"q":"En Illinois, ¿cuándo vence la licencia de un conductor menor de 21 años?","o":["3 meses después de cumplir 21 años","El día que cumple 21 años","El día que cumple 18 años","1 año después de cumplir 21 años"],"h1":"Es un poco después de que el conductor cumple 21 años.","h2":"En Illinois, la licencia de un conductor menor de 21 años vence tres meses después de que cumple 21 años.","p":"Correcto. Vence tres meses después de cumplir 21."},"ref":{"doc":"IL","page":8}},{"id":"il-036","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, how long is an instruction permit valid?","o":["6 months","12 months","18 months","24 months"],"h1":"It lasts longer than the nine months a teen must hold it.","h2":"In Illinois, an instruction permit is valid for 24 months.","p":"Right. The permit is good for 24 months."},"es":{"q":"En Illinois, ¿por cuánto tiempo es válido el permiso de aprendizaje?","o":["6 meses","12 meses","18 meses","24 meses"],"h1":"Dura más que los nueve meses que un adolescente debe tenerlo.","h2":"En Illinois, el permiso de aprendizaje es válido por 24 meses.","p":"Correcto. El permiso es válido por 24 meses."},"ref":{"doc":"IL","page":16}},{"id":"il-037","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, an 18-year-old has never been licensed and never took driver education. What must they finish before getting a license?","o":["A 30-hour classroom course","A 6-hour adult driver education course","A short online safety video","Nothing, because they are 18"],"h1":"There is a special course for new drivers ages 18 to 20.","h2":"In Illinois, a first-time applicant age 18, 19 or 20 who never took driver education must complete a six-hour Adult Driver Education Course.","p":"Right. They need the 6-hour adult course."},"es":{"q":"En Illinois, una persona de 18 años nunca ha tenido licencia ni tomó educación vial. ¿Qué debe completar antes de obtener una licencia?","o":["Un curso de 30 horas en el aula","Un curso de educación vial para adultos de 6 horas","Un video corto de seguridad en línea","Nada, porque tiene 18 años"],"h1":"Hay un curso especial para conductores nuevos de 18 a 20 años.","h2":"En Illinois, una persona de 18, 19 o 20 años que solicita su primera licencia y nunca tomó educación vial debe completar un curso de educación vial para adultos de seis horas.","p":"Correcto. Necesita el curso para adultos de 6 horas."},"ref":{"doc":"IL","page":18}},{"id":"il-038","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, a driver under 21 is convicted of two moving violations within 24 months. What happens?","o":["Only a warning letter","A fine, but no effect on the license","The license is revoked for life","A license suspension of at least 30 days"],"h1":"Young drivers lose their license sooner than adults do.","h2":"In Illinois, a driver under 21 with two or more moving violation convictions within 24 months faces a suspension of at least 30 days.","p":"Right. At least a 30-day suspension."},"es":{"q":"En Illinois, un conductor menor de 21 años es declarado culpable de dos infracciones de tránsito en 24 meses. ¿Qué pasa?","o":["Solo recibe una carta de advertencia","Paga una multa, sin efecto en la licencia","Le revocan la licencia de por vida","Le suspenden la licencia por al menos 30 días"],"h1":"Los conductores jóvenes pierden la licencia más pronto que los adultos.","h2":"En Illinois, un conductor menor de 21 años con dos o más condenas por infracciones de tránsito en 24 meses recibe una suspensión de al menos 30 días.","p":"Correcto. Una suspensión de al menos 30 días."},"ref":{"doc":"IL","page":20}},{"id":"il-039","scope":"IL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Illinois, unless a sign says otherwise, what is the speed limit on a highway with four lanes?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"It is lower than on interstates but higher than on other rural roads.","h2":"Unless a sign says otherwise, the speed limit on an Illinois highway with four lanes is 65 miles per hour.","p":"Right. Four-lane highways are 65 mph."},"es":{"q":"En Illinois, si no hay un letrero que diga otra cosa, ¿cuál es el límite de velocidad en una carretera de cuatro carriles?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Es menor que en las interestatales, pero mayor que en otras carreteras rurales.","h2":"Si no hay un letrero que diga otra cosa, el límite de velocidad en una carretera de cuatro carriles de Illinois es de 65 millas por hora.","p":"Correcto. Las carreteras de cuatro carriles son de 65 mph."},"ref":{"doc":"IL","page":24}},{"id":"il-040","scope":"IL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Illinois, what is the speed limit in a posted school zone on a school day when children are present?","o":["15 mph","20 mph","25 mph","30 mph"],"h1":"It is slower than the usual city limit of 30 mph.","h2":"In Illinois, you must slow to 20 miles per hour in a posted school zone on school days when children are present.","p":"Right. School zones are 20 mph."},"es":{"q":"En Illinois, ¿cuál es el límite de velocidad en una zona escolar señalizada, en un día de clases, cuando hay niños presentes?","o":["15 mph","20 mph","25 mph","30 mph"],"h1":"Es más lento que el límite normal de la ciudad, que es de 30 mph.","h2":"En Illinois, usted debe bajar a 20 millas por hora en una zona escolar señalizada los días de clases cuando hay niños presentes.","p":"Correcto. Las zonas escolares son de 20 mph."},"ref":{"doc":"IL","page":24}},{"id":"il-041","scope":"IL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Illinois, when must you obey the posted speed limit in a construction zone?","o":["At all times, day and night","Only when workers are present","Only during daylight hours","Only on weekdays"],"h1":"Road work dangers do not go away when the workers go home.","h2":"In Illinois, you must obey the posted construction zone speed limit 24 hours a day, seven days a week, even when no workers are there.","p":"Right. The work zone limit applies all the time."},"es":{"q":"En Illinois, ¿cuándo debe obedecer el límite de velocidad señalizado en una zona de construcción?","o":["Siempre, de día y de noche","Solo cuando hay trabajadores","Solo durante el día","Solo de lunes a viernes"],"h1":"Los peligros de la obra no desaparecen cuando los trabajadores se van a casa.","h2":"En Illinois, usted debe obedecer el límite de velocidad señalizado en una zona de construcción las 24 horas del día, los siete días de la semana, aunque no haya trabajadores.","p":"Correcto. El límite de la zona de obras se aplica siempre."},"ref":{"doc":"IL","page":25}},{"id":"il-042","scope":"IL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Illinois, may you pass another vehicle on a two-lane road inside a construction zone?","o":["Yes, if the road ahead is clear","Yes, but only in daylight","Only if no workers are present","No, every construction zone is a no-passing zone"],"h1":"Think about narrow lanes and workers close to traffic.","h2":"In Illinois, all construction zones are no-passing zones, so you may not pass there.","p":"Right. No passing in any construction zone."},"es":{"q":"En Illinois, ¿puede rebasar a otro vehículo en una carretera de dos carriles dentro de una zona de construcción?","o":["Sí, si el camino adelante está libre","Sí, pero solo durante el día","Solo si no hay trabajadores","No, todas las zonas de construcción son zonas de no rebasar"],"h1":"Piense en los carriles angostos y en los trabajadores cerca del tráfico.","h2":"En Illinois, todas las zonas de construcción son zonas de no rebasar, así que usted no puede rebasar allí.","p":"Correcto. No se rebasa en ninguna zona de construcción."},"ref":{"doc":"IL","page":29}},{"id":"il-043","scope":"IL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Illinois, on an interstate, when should you drive in the left lane?","o":["Whenever you like","When you are passing another vehicle","Only at night","When you are going below the speed limit"],"h1":"The left lane is not for cruising.","h2":"On an Illinois interstate, you may not drive in the left lane except to pass, apart from a few exceptions such as heavy traffic, bad weather or a hazard in the right lane.","p":"Right. The left lane is for passing."},"es":{"q":"En Illinois, en una carretera interestatal, ¿cuándo debe manejar en el carril izquierdo?","o":["Cuando usted quiera","Cuando está rebasando a otro vehículo","Solo de noche","Cuando va más despacio que el límite"],"h1":"El carril izquierdo no es para ir de paseo.","h2":"En una interestatal de Illinois, usted no puede manejar en el carril izquierdo excepto para rebasar, salvo algunas excepciones como tráfico pesado, mal tiempo o un peligro en el carril derecho.","p":"Correcto. El carril izquierdo es para rebasar."},"ref":{"doc":"IL","page":29}},{"id":"il-044","scope":"IL","cat":"signals","sign":null,"c":2,"en":{"q":"In Illinois, outside business and residential areas, how far before a turn must you start your turn signal?","o":["At least 50 feet","At least 100 feet","At least 200 feet","At least 500 feet"],"h1":"It is twice the distance required in town.","h2":"In Illinois, outside business and residential areas, you must signal for at least 200 feet before turning.","p":"Right. Signal at least 200 feet ahead outside town."},"es":{"q":"En Illinois, fuera de las zonas comerciales y residenciales, ¿a qué distancia antes de una vuelta debe poner la direccional?","o":["Al menos 50 pies","Al menos 100 pies","Al menos 200 pies","Al menos 500 pies"],"h1":"Es el doble de la distancia que se pide en la ciudad.","h2":"En Illinois, fuera de las zonas comerciales y residenciales, usted debe poner la direccional al menos 200 pies antes de dar vuelta.","p":"Correcto. Fuera de la ciudad, señale al menos 200 pies antes."},"ref":{"doc":"IL","page":30}},{"id":"il-045","scope":"IL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Illinois, what is the penalty for being convicted of passing a stopped school bus with its stop arm out?","o":["A $300 fine and a license suspension","A $50 fine and nothing more","A warning for the first time","Traffic school, with no fine"],"h1":"It costs money and also affects your license.","h2":"In Illinois, a conviction for passing a stopped school bus brings a mandatory $300 fine and a suspension of your driver's license.","p":"Right. A $300 fine and a suspension."},"es":{"q":"En Illinois, ¿cuál es la sanción por ser declarado culpable de rebasar un autobús escolar detenido con el brazo de alto extendido?","o":["Una multa de $300 y la suspensión de la licencia","Una multa de $50 y nada más","Una advertencia la primera vez","Escuela de tránsito, sin multa"],"h1":"Cuesta dinero y también afecta su licencia.","h2":"En Illinois, una condena por rebasar un autobús escolar detenido trae una multa obligatoria de $300 y la suspensión de su licencia de conducir.","p":"Correcto. Una multa de $300 y una suspensión."},"ref":{"doc":"IL","page":33}},{"id":"il-046","scope":"IL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Illinois, how close to a STOP sign may you park?","o":["No closer than 10 feet","No closer than 20 feet","No closer than 30 feet","No closer than 50 feet"],"h1":"Other drivers need to see the sign clearly.","h2":"In Illinois, you may not park within 30 feet of a STOP sign, a YIELD sign or a traffic signal.","p":"Right. Stay at least 30 feet from a STOP sign."},"es":{"q":"En Illinois, ¿qué tan cerca de un letrero de ALTO puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 20 pies","No más cerca de 30 pies","No más cerca de 50 pies"],"h1":"Los demás conductores necesitan ver bien el letrero.","h2":"En Illinois, usted no puede estacionarse a menos de 30 pies de un letrero de ALTO, un letrero de CEDA EL PASO o un semáforo.","p":"Correcto. Quédese al menos a 30 pies de un letrero de ALTO."},"ref":{"doc":"IL","page":36}},{"id":"il-047","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, what happens to your driving privileges if you are convicted of driving without the required insurance?","o":["Nothing, you only pay a fine","They are suspended for at least 3 months","They are suspended for 1 week","They are revoked for 10 years"],"h1":"You lose your license for a few months, and no driving permit is offered.","h2":"In Illinois, a conviction for driving without the required insurance means losing your driving privileges for at least three months.","p":"Right. At least a 3-month suspension."},"es":{"q":"En Illinois, ¿qué pasa con su privilegio de manejar si lo declaran culpable de manejar sin el seguro obligatorio?","o":["Nada, solo paga una multa","Se lo suspenden por al menos 3 meses","Se lo suspenden por 1 semana","Se lo revocan por 10 años"],"h1":"Pierde la licencia por unos meses y no le dan un permiso para manejar.","h2":"En Illinois, una condena por manejar sin el seguro obligatorio significa perder el privilegio de manejar por al menos tres meses.","p":"Correcto. Una suspensión de al menos 3 meses."},"ref":{"doc":"IL","page":55}},{"id":"il-048","scope":"IL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Illinois, a first offender arrested for DUI has a test result of 0.08 or more. How long is the statutory summary suspension?","o":["1 month","3 months","6 months","2 years"],"h1":"It is half a year.","h2":"In Illinois, a first offender whose test shows 0.08 or more gets a statutory summary suspension of six months.","p":"Right. Six months for a failed test."},"es":{"q":"En Illinois, una persona arrestada por primera vez por manejar bajo los efectos (DUI) tiene un resultado de 0.08 o más. ¿Cuánto dura la suspensión sumaria (statutory summary suspension)?","o":["1 mes","3 meses","6 meses","2 años"],"h1":"Es medio año.","h2":"En Illinois, una persona arrestada por primera vez cuyo examen muestra 0.08 o más recibe una suspensión sumaria de seis meses.","p":"Correcto. Seis meses por no pasar el examen."},"ref":{"doc":"IL","page":49}},{"id":"il-049","scope":"IL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Illinois, a first offender arrested for DUI refuses the chemical test. How long is the license suspended?","o":["1 year","6 months","3 months","30 days"],"h1":"Refusing costs you more than failing the test.","h2":"In Illinois, a first offender who refuses chemical testing after a DUI arrest has driving privileges suspended for one year.","p":"Right. Refusing means a one-year suspension."},"es":{"q":"En Illinois, una persona arrestada por primera vez por DUI se niega a hacer la prueba química. ¿Por cuánto tiempo le suspenden la licencia?","o":["1 año","6 meses","3 meses","30 días"],"h1":"Negarse le cuesta más que no pasar la prueba.","h2":"En Illinois, una persona arrestada por primera vez por DUI que se niega a la prueba química pierde el privilegio de manejar por un año.","p":"Correcto. Negarse significa una suspensión de un año."},"ref":{"doc":"IL","page":49}},{"id":"il-050","scope":"IL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Illinois, what is the least a driver loses for a first DUI conviction?","o":["A 30-day suspension","A 3-month suspension","A lifetime revocation","A revocation of at least 1 year"],"h1":"A DUI conviction takes the license away, not just for a few weeks.","h2":"In Illinois, a first DUI conviction brings a revocation of driving privileges for at least one year.","p":"Right. At least a one-year revocation."},"es":{"q":"En Illinois, ¿qué es lo mínimo que pierde un conductor por su primera condena por DUI?","o":["Una suspensión de 30 días","Una suspensión de 3 meses","Una revocación de por vida","Una revocación de al menos 1 año"],"h1":"Una condena por DUI le quita la licencia, y no solo por unas semanas.","h2":"En Illinois, una primera condena por DUI trae la revocación del privilegio de manejar por al menos un año.","p":"Correcto. Una revocación de al menos un año."},"ref":{"doc":"IL","page":50}},{"id":"il-051","scope":"IL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Illinois, a driver under 21 is convicted of DUI for the first time. What is the minimum revocation?","o":["2 years","1 year","6 months","3 months"],"h1":"It is longer than the minimum for an adult.","h2":"In Illinois, a driver under 21 convicted of DUI for the first time loses driving privileges for at least two years.","p":"Right. At least two years for a driver under 21."},"es":{"q":"En Illinois, un conductor menor de 21 años es declarado culpable de DUI por primera vez. ¿Cuál es la revocación mínima?","o":["2 años","1 año","6 meses","3 meses"],"h1":"Es más larga que el mínimo para un adulto.","h2":"En Illinois, un conductor menor de 21 años declarado culpable de DUI por primera vez pierde el privilegio de manejar por al menos dos años.","p":"Correcto. Al menos dos años para un conductor menor de 21."},"ref":{"doc":"IL","page":52}},{"id":"il-052","scope":"IL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Illinois, how must cannabis be carried in a vehicle?","o":["In an open bag on the back seat","In a closed paper bag in the glove box","Anywhere, as long as no one uses it","In a sealed, odor-proof, child-resistant container"],"h1":"The container must keep in the smell and keep out small children.","h2":"In Illinois, cannabis may be carried in a vehicle only in a sealed, odor-proof, child-resistant container.","p":"Right. Sealed, odor-proof and child-resistant."},"es":{"q":"En Illinois, ¿cómo se debe llevar el cannabis en un vehículo?","o":["En una bolsa abierta en el asiento de atrás","En una bolsa de papel cerrada en la guantera","En cualquier lugar, si nadie lo usa","En un envase sellado, a prueba de olores y a prueba de niños"],"h1":"El envase debe guardar el olor y no dejar que los niños pequeños lo abran.","h2":"En Illinois, el cannabis solo se puede llevar en un vehículo en un envase sellado, a prueba de olores y a prueba de niños.","p":"Correcto. Sellado, a prueba de olores y a prueba de niños."},"ref":{"doc":"IL","page":48}},{"id":"in-001","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, what is the youngest age to get a learner's permit if you are enrolled in driver education?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"Driver education lets you start one year before the usual age.","h2":"In Indiana you can get a learner's permit at 15 if you are enrolled in an approved driver education course.","p":"Right. With driver education, the permit starts at 15."},"es":{"q":"En Indiana, ¿cuál es la edad mínima para obtener un permiso de aprendiz si usted está inscrito en educación vial?","o":["14 años","15 años","16 años","17 años"],"h1":"La educación vial le permite empezar un año antes de la edad normal.","h2":"En Indiana usted puede obtener el permiso de aprendiz a los 15 años si está inscrito en un curso aprobado de educación vial.","p":"Correcto. Con educación vial, el permiso empieza a los 15."},"zh":{"q":"在 Indiana，如果你报名了驾驶课，最小几岁可以拿到学习驾照（learner's permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"上驾驶课可以让你比一般年龄早一年开始。","h2":"在 Indiana，如果你报名了经过批准的驾驶课，15 岁就可以拿到学习驾照。","p":"对。上驾驶课的话，学习驾照从 15 岁开始。"},"vi":{"q":"Ở Indiana, tuổi nhỏ nhất để lấy giấy phép tập lái (learner's permit) là bao nhiêu nếu bạn đang học lớp giáo dục lái xe (driver education)?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Lớp giáo dục lái xe cho phép bạn bắt đầu sớm hơn tuổi thông thường một năm.","h2":"Ở Indiana, bạn có thể lấy giấy phép tập lái khi 15 tuổi nếu bạn đã ghi danh vào một khóa giáo dục lái xe được chấp thuận.","p":"Đúng. Có học giáo dục lái xe, giấy phép bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Indiana, ano ang pinakabatang edad para makakuha ng learner's permit kung naka-enroll ka sa driver education?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Sa driver education, puwede kang magsimula nang isang taon bago ang karaniwang edad.","h2":"Sa Indiana, puwede kang kumuha ng learner's permit sa edad na 15 kung naka-enroll ka sa isang aprubadong driver education course.","p":"Tama. Kapag may driver education, nagsisimula ang permit sa 15."},"ar":{"q":"في Indiana، ما أصغر عمر للحصول على تصريح التعلّم (learner's permit) إذا كنت مسجّلًا في دورة تعليم القيادة (driver education)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"دورة تعليم القيادة تسمح لك بالبدء قبل العمر المعتاد بسنة واحدة.","h2":"في Indiana يمكنك الحصول على تصريح التعلّم في عمر 15 سنة إذا كنت مسجّلًا في دورة معتمدة لتعليم القيادة.","p":"صحيح. مع دورة تعليم القيادة يبدأ التصريح في عمر 15 سنة."},"ref":{"doc":"IN","page":3}},{"id":"in-002","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, how old must you be to get a learner's permit without taking driver education?","o":["14 years old","15 years old","16 years old","18 years old"],"h1":"It is one year later than with driver education.","h2":"In Indiana you must be at least 16 to get a learner's permit without a driver education course.","p":"Correct. Without driver education, you wait until 16."},"es":{"q":"En Indiana, ¿qué edad debe tener para obtener un permiso de aprendiz sin tomar educación vial?","o":["14 años","15 años","16 años","18 años"],"h1":"Es un año más tarde que con educación vial.","h2":"En Indiana usted debe tener por lo menos 16 años para obtener el permiso de aprendiz sin un curso de educación vial.","p":"Correcto. Sin educación vial, hay que esperar hasta los 16."},"zh":{"q":"在 Indiana，不上驾驶课的话，你必须几岁才能拿到学习驾照？","o":["14 岁","15 岁","16 岁","18 岁"],"h1":"比上驾驶课晚一年。","h2":"在 Indiana，不上驾驶课的话，你必须至少 16 岁才能拿到学习驾照。","p":"正确。不上驾驶课，就要等到 16 岁。"},"vi":{"q":"Ở Indiana, bạn phải bao nhiêu tuổi để lấy giấy phép tập lái mà không học giáo dục lái xe?","o":["14 tuổi","15 tuổi","16 tuổi","18 tuổi"],"h1":"Đó là muộn hơn một năm so với khi có học giáo dục lái xe.","h2":"Ở Indiana, bạn phải ít nhất 16 tuổi để lấy giấy phép tập lái nếu không học khóa giáo dục lái xe.","p":"Đúng. Không học giáo dục lái xe thì bạn phải chờ đến 16 tuổi."},"tl":{"q":"Sa Indiana, ilang taon ka dapat para makakuha ng learner's permit nang walang driver education?","o":["14 taong gulang","15 taong gulang","16 taong gulang","18 taong gulang"],"h1":"Isang taon itong mas huli kaysa kapag may driver education.","h2":"Sa Indiana, dapat ay hindi bababa sa 16 ka para makakuha ng learner's permit nang walang driver education course.","p":"Tama. Kapag walang driver education, maghihintay ka hanggang 16."},"ar":{"q":"في Indiana، كم يجب أن يكون عمرك للحصول على تصريح التعلّم دون دورة تعليم القيادة؟","o":["14 سنة","15 سنة","16 سنة","18 سنة"],"h1":"هو متأخر بسنة واحدة عن العمر مع دورة تعليم القيادة.","h2":"في Indiana يجب أن يكون عمرك 16 سنة على الأقل للحصول على تصريح التعلّم دون دورة تعليم القيادة.","p":"صحيح. دون دورة تعليم القيادة تنتظر حتى عمر 16 سنة."},"ref":{"doc":"IN","page":3}},{"id":"in-003","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, how old must a relative be to supervise a learner under 18?","o":["At least 18","At least 19","At least 21","At least 25"],"h1":"Indiana asks for an older supervisor than many states do.","h2":"In Indiana a relative who supervises a learner under 18 must be a licensed driver who is at least 25 years old.","p":"Right. The relative must be 25 or older."},"es":{"q":"En Indiana, ¿qué edad debe tener un familiar para supervisar a un aprendiz menor de 18 años?","o":["Por lo menos 18","Por lo menos 19","Por lo menos 21","Por lo menos 25"],"h1":"Indiana pide un supervisor de más edad que muchos otros estados.","h2":"En Indiana, un familiar que supervisa a un aprendiz menor de 18 años debe ser un conductor con licencia de por lo menos 25 años.","p":"Correcto. El familiar debe tener 25 años o más."},"zh":{"q":"在 Indiana，陪同 18 岁以下学习驾驶的人练车的亲属必须几岁？","o":["至少 18 岁","至少 19 岁","至少 21 岁","至少 25 岁"],"h1":"Indiana 要求的陪同者年龄比很多州都大。","h2":"在 Indiana，陪同 18 岁以下学习驾驶的人练车的亲属，必须是至少 25 岁、有驾照的司机。","p":"对。亲属必须 25 岁或以上。"},"vi":{"q":"Ở Indiana, người thân phải bao nhiêu tuổi để giám sát một người tập lái dưới 18 tuổi?","o":["Ít nhất 18 tuổi","Ít nhất 19 tuổi","Ít nhất 21 tuổi","Ít nhất 25 tuổi"],"h1":"Indiana yêu cầu người giám sát lớn tuổi hơn so với nhiều tiểu bang khác.","h2":"Ở Indiana, người thân giám sát một người tập lái dưới 18 tuổi phải là người có bằng lái và ít nhất 25 tuổi.","p":"Đúng. Người thân phải từ 25 tuổi trở lên."},"tl":{"q":"Sa Indiana, ilang taon dapat ang isang kamag-anak para magbantay sa isang learner na wala pang 18?","o":["Hindi bababa sa 18","Hindi bababa sa 19","Hindi bababa sa 21","Hindi bababa sa 25"],"h1":"Mas matandang tagabantay ang hinihingi ng Indiana kaysa sa maraming ibang estado.","h2":"Sa Indiana, ang kamag-anak na nagbabantay sa learner na wala pang 18 ay dapat may lisensya at hindi bababa sa 25 taong gulang.","p":"Tama. Dapat 25 o mas matanda ang kamag-anak."},"ar":{"q":"في Indiana، كم يجب أن يكون عمر القريب الذي يشرف على متعلّم عمره أقل من 18 سنة؟","o":["18 سنة على الأقل","19 سنة على الأقل","21 سنة على الأقل","25 سنة على الأقل"],"h1":"تطلب Indiana مشرفًا أكبر سنًّا مما تطلبه ولايات كثيرة.","h2":"في Indiana يجب أن يكون القريب الذي يشرف على متعلّم عمره أقل من 18 سنة سائقًا مرخّصًا وعمره 25 سنة على الأقل.","p":"صحيح. يجب أن يكون عمر القريب 25 سنة أو أكثر."},"ref":{"doc":"IN","page":4}},{"id":"in-004","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, a learner's spouse may supervise practice driving. How old must the spouse be?","o":["At least 21","At least 25","At least 18","At least 30"],"h1":"It is younger than the age for other relatives.","h2":"In Indiana a licensed spouse who is at least 21 may supervise a learner, while other relatives must be at least 25.","p":"Correct. A spouse must be 21 or older."},"es":{"q":"En Indiana, el cónyuge de un aprendiz puede supervisar la práctica. ¿Qué edad debe tener el cónyuge?","o":["Por lo menos 21","Por lo menos 25","Por lo menos 18","Por lo menos 30"],"h1":"Es menor que la edad pedida a otros familiares.","h2":"En Indiana, un cónyuge con licencia de por lo menos 21 años puede supervisar a un aprendiz; otros familiares deben tener por lo menos 25.","p":"Correcto. El cónyuge debe tener 21 años o más."},"zh":{"q":"在 Indiana，学习驾驶的人的配偶可以陪同练车。配偶必须几岁？","o":["至少 21 岁","至少 25 岁","至少 18 岁","至少 30 岁"],"h1":"比其他亲属的年龄要求小。","h2":"在 Indiana，至少 21 岁、有驾照的配偶可以陪同学习驾驶的人，其他亲属则必须至少 25 岁。","p":"正确。配偶必须 21 岁或以上。"},"vi":{"q":"Ở Indiana, vợ hoặc chồng của người tập lái có thể giám sát việc tập lái. Người vợ hoặc chồng đó phải bao nhiêu tuổi?","o":["Ít nhất 21 tuổi","Ít nhất 25 tuổi","Ít nhất 18 tuổi","Ít nhất 30 tuổi"],"h1":"Tuổi này nhỏ hơn tuổi yêu cầu cho những người thân khác.","h2":"Ở Indiana, vợ hoặc chồng có bằng lái và ít nhất 21 tuổi có thể giám sát người tập lái, còn những người thân khác phải ít nhất 25 tuổi.","p":"Đúng. Vợ hoặc chồng phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Indiana, puwedeng magbantay sa pag-eensayo ng pagmamaneho ang asawa ng learner. Ilang taon dapat ang asawa?","o":["Hindi bababa sa 21","Hindi bababa sa 25","Hindi bababa sa 18","Hindi bababa sa 30"],"h1":"Mas bata ito kaysa sa edad para sa ibang kamag-anak.","h2":"Sa Indiana, ang asawang may lisensya at hindi bababa sa 21 ay puwedeng magbantay sa learner, pero ang ibang kamag-anak ay dapat hindi bababa sa 25.","p":"Tama. Dapat 21 o mas matanda ang asawa."},"ar":{"q":"في Indiana، يمكن لزوج المتعلّم أو زوجته الإشراف على التدريب على القيادة. كم يجب أن يكون عمر الزوج أو الزوجة؟","o":["21 سنة على الأقل","25 سنة على الأقل","18 سنة على الأقل","30 سنة على الأقل"],"h1":"هو أصغر من العمر المطلوب للأقارب الآخرين.","h2":"في Indiana يمكن للزوج أو الزوجة المرخّص الذي عمره 21 سنة على الأقل أن يشرف على المتعلّم، أما الأقارب الآخرون فيجب أن يكون عمرهم 25 سنة على الأقل.","p":"صحيح. يجب أن يكون عمر الزوج أو الزوجة 21 سنة أو أكثر."},"ref":{"doc":"IN","page":4}},{"id":"in-005","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, how many hours of supervised driving must a new driver log before getting a license?","o":["20 hours","50 hours","40 hours","100 hours"],"h1":"It is a round number between 40 and 100.","h2":"In Indiana a new driver must log at least 50 hours of supervised driving practice before applying for a license.","p":"Right. Indiana asks for 50 logged hours."},"es":{"q":"En Indiana, ¿cuántas horas de manejo supervisado debe registrar un conductor nuevo antes de obtener la licencia?","o":["20 horas","50 horas","40 horas","100 horas"],"h1":"Es un número redondo entre 40 y 100.","h2":"En Indiana, un conductor nuevo debe registrar por lo menos 50 horas de práctica supervisada antes de solicitar la licencia.","p":"Correcto. Indiana pide 50 horas registradas."},"zh":{"q":"在 Indiana，新司机拿驾照前，必须记录多少小时有人陪同的驾驶？","o":["20 小时","50 小时","40 小时","100 小时"],"h1":"是 40 和 100 之间的一个整数。","h2":"在 Indiana，新司机申请驾照前，必须记录至少 50 小时有人陪同的驾驶练习。","p":"对。Indiana 要求记录 50 小时。"},"vi":{"q":"Ở Indiana, người lái mới phải ghi lại bao nhiêu giờ lái xe có người giám sát trước khi lấy bằng lái?","o":["20 giờ","50 giờ","40 giờ","100 giờ"],"h1":"Đó là một số tròn ở giữa 40 và 100.","h2":"Ở Indiana, người lái mới phải ghi lại ít nhất 50 giờ tập lái có người giám sát trước khi nộp đơn xin bằng lái.","p":"Đúng. Indiana yêu cầu ghi lại 50 giờ."},"tl":{"q":"Sa Indiana, ilang oras ng binabantayang pagmamaneho ang dapat itala ng bagong driver bago kumuha ng lisensya?","o":["20 oras","50 oras","40 oras","100 oras"],"h1":"Isa itong buong numero sa pagitan ng 40 at 100.","h2":"Sa Indiana, ang bagong driver ay dapat magtala ng hindi bababa sa 50 oras ng binabantayang pag-eensayo bago mag-apply para sa lisensya.","p":"Tama. 50 oras na nakatala ang hinihingi ng Indiana."},"ar":{"q":"في Indiana، كم ساعة من القيادة تحت الإشراف يجب أن يسجّل السائق الجديد قبل الحصول على الرخصة؟","o":["20 ساعة","50 ساعة","40 ساعة","100 ساعة"],"h1":"هو رقم مدوَّر بين 40 و100.","h2":"في Indiana يجب أن يسجّل السائق الجديد 50 ساعة على الأقل من التدريب على القيادة تحت الإشراف قبل التقديم على الرخصة.","p":"صحيح. تطلب Indiana تسجيل 50 ساعة."},"ref":{"doc":"IN","page":9}},{"id":"in-006","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, how many of the logged supervised hours must be driven at night?","o":["At least 2 hours","At least 5 hours","At least 10 hours","At least 25 hours"],"h1":"It is one fifth of the total hours.","h2":"In Indiana at least 10 of the 50 supervised practice hours must be driven at night.","p":"Correct. Ten of the hours are at night."},"es":{"q":"En Indiana, ¿cuántas de las horas supervisadas registradas deben ser de noche?","o":["Por lo menos 2 horas","Por lo menos 5 horas","Por lo menos 10 horas","Por lo menos 25 horas"],"h1":"Es la quinta parte del total de horas.","h2":"En Indiana, por lo menos 10 de las 50 horas de práctica supervisada deben ser de noche.","p":"Correcto. Diez de las horas son de noche."},"zh":{"q":"在 Indiana，记录的有人陪同驾驶时间中，必须有多少小时是在夜间开的？","o":["至少 2 小时","至少 5 小时","至少 10 小时","至少 25 小时"],"h1":"是总时间的五分之一。","h2":"在 Indiana，50 小时有人陪同的练习中，至少 10 小时必须在夜间开。","p":"正确。其中十个小时是在夜间。"},"vi":{"q":"Ở Indiana, trong số giờ lái có người giám sát được ghi lại, bao nhiêu giờ phải lái vào ban đêm?","o":["Ít nhất 2 giờ","Ít nhất 5 giờ","Ít nhất 10 giờ","Ít nhất 25 giờ"],"h1":"Đó là một phần năm tổng số giờ.","h2":"Ở Indiana, ít nhất 10 trong 50 giờ tập lái có người giám sát phải lái vào ban đêm.","p":"Đúng. Mười giờ phải lái vào ban đêm."},"tl":{"q":"Sa Indiana, ilan sa mga nakatalang oras ng binabantayang pagmamaneho ang dapat gawin sa gabi?","o":["Hindi bababa sa 2 oras","Hindi bababa sa 5 oras","Hindi bababa sa 10 oras","Hindi bababa sa 25 oras"],"h1":"Isang-ikalima ito ng kabuuang oras.","h2":"Sa Indiana, hindi bababa sa 10 sa 50 oras ng binabantayang pag-eensayo ang dapat gawin sa gabi.","p":"Tama. Sampu sa mga oras ay sa gabi."},"ar":{"q":"في Indiana، كم من ساعات القيادة المسجّلة تحت الإشراف يجب أن تكون في الليل؟","o":["ساعتان (2) على الأقل","5 ساعات على الأقل","10 ساعات على الأقل","25 ساعة على الأقل"],"h1":"هي خُمس مجموع الساعات.","h2":"في Indiana يجب أن تكون 10 ساعات على الأقل من الـ 50 ساعة من التدريب تحت الإشراف في الليل.","p":"صحيح. عشر ساعات تكون في الليل."},"ref":{"doc":"IN","page":9}},{"id":"in-007","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, how long must you hold a learner's permit before you can get a probationary license?","o":["30 days","60 days","90 days","180 days"],"h1":"It is about six months.","h2":"In Indiana you must hold your learner's permit for 180 days, about six months, before getting a probationary license.","p":"Right. You hold the permit for 180 days."},"es":{"q":"En Indiana, ¿cuánto tiempo debe tener el permiso de aprendiz antes de obtener una licencia probatoria?","o":["30 días","60 días","90 días","180 días"],"h1":"Son unos seis meses.","h2":"En Indiana usted debe tener el permiso de aprendiz durante 180 días, unos seis meses, antes de obtener la licencia probatoria.","p":"Correcto. Se tiene el permiso por 180 días."},"zh":{"q":"在 Indiana，你必须持有学习驾照多久，才能拿到试用驾照（probationary license）？","o":["30 天","60 天","90 天","180 天"],"h1":"大约是六个月。","h2":"在 Indiana，你必须持有学习驾照 180 天，大约六个月，才能拿到试用驾照。","p":"对。你要持有学习驾照 180 天。"},"vi":{"q":"Ở Indiana, bạn phải giữ giấy phép tập lái bao lâu trước khi có thể lấy bằng lái thử thách (probationary license)?","o":["30 ngày","60 ngày","90 ngày","180 ngày"],"h1":"Đó là khoảng sáu tháng.","h2":"Ở Indiana, bạn phải giữ giấy phép tập lái 180 ngày, khoảng sáu tháng, trước khi lấy bằng lái thử thách.","p":"Đúng. Bạn giữ giấy phép tập lái 180 ngày."},"tl":{"q":"Sa Indiana, gaano katagal mo dapat hawak ang learner's permit bago ka makakuha ng probationary license?","o":["30 araw","60 araw","90 araw","180 araw"],"h1":"Mga anim na buwan ito.","h2":"Sa Indiana, dapat hawak mo ang learner's permit nang 180 araw, mga anim na buwan, bago kumuha ng probationary license.","p":"Tama. Hawak mo ang permit nang 180 araw."},"ar":{"q":"في Indiana، كم مدة يجب أن تحمل تصريح التعلّم قبل أن تحصل على الرخصة التجريبية (probationary license)؟","o":["30 يومًا","60 يومًا","90 يومًا","180 يومًا"],"h1":"هي حوالي ستة أشهر.","h2":"في Indiana يجب أن تحمل تصريح التعلّم 180 يومًا، أي حوالي ستة أشهر، قبل الحصول على الرخصة التجريبية.","p":"صحيح. تحمل التصريح 180 يومًا."},"ref":{"doc":"IN","page":9}},{"id":"in-008","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, how old must you be to get a probationary license if you did not complete driver education?","o":["16 years and 270 days","16 years exactly","15 years and 180 days","18 years exactly"],"h1":"It is later than 16, but well before 17 and a half.","h2":"In Indiana a driver who did not finish driver education must be at least 16 years and 270 days old for a probationary license.","p":"Correct. Without driver education, it is 16 years and 270 days."},"es":{"q":"En Indiana, ¿qué edad debe tener para obtener una licencia probatoria si no completó educación vial?","o":["16 años y 270 días","16 años exactos","15 años y 180 días","18 años exactos"],"h1":"Es después de los 16, pero bastante antes de los 17 y medio.","h2":"En Indiana, un conductor que no terminó educación vial debe tener por lo menos 16 años y 270 días para la licencia probatoria.","p":"Correcto. Sin educación vial, son 16 años y 270 días."},"zh":{"q":"在 Indiana，如果你没有完成驾驶课，必须几岁才能拿到试用驾照？","o":["16 岁又 270 天","正好 16 岁","15 岁又 180 天","正好 18 岁"],"h1":"比 16 岁晚，但比 17 岁半早很多。","h2":"在 Indiana，没有完成驾驶课的司机，必须至少 16 岁又 270 天才能拿到试用驾照。","p":"正确。不上驾驶课，就是 16 岁又 270 天。"},"vi":{"q":"Ở Indiana, bạn phải bao nhiêu tuổi để lấy bằng lái thử thách nếu bạn không hoàn thành giáo dục lái xe?","o":["16 tuổi và 270 ngày","Đúng 16 tuổi","15 tuổi và 180 ngày","Đúng 18 tuổi"],"h1":"Đó là sau 16 tuổi, nhưng còn khá xa mới đến 17 tuổi rưỡi.","h2":"Ở Indiana, người lái không hoàn thành giáo dục lái xe phải ít nhất 16 tuổi và 270 ngày để lấy bằng lái thử thách.","p":"Đúng. Không học giáo dục lái xe thì phải 16 tuổi và 270 ngày."},"tl":{"q":"Sa Indiana, ilang taon ka dapat para makakuha ng probationary license kung hindi mo natapos ang driver education?","o":["16 na taon at 270 araw","Eksaktong 16 na taon","15 taon at 180 araw","Eksaktong 18 taon"],"h1":"Mas huli ito sa 16, pero malayo pa sa 17 at kalahati.","h2":"Sa Indiana, ang driver na hindi nakatapos ng driver education ay dapat hindi bababa sa 16 na taon at 270 araw para sa probationary license.","p":"Tama. Kapag walang driver education, 16 na taon at 270 araw."},"ar":{"q":"في Indiana، كم يجب أن يكون عمرك للحصول على الرخصة التجريبية إذا لم تُكمل دورة تعليم القيادة؟","o":["16 سنة و270 يومًا","16 سنة بالضبط","15 سنة و180 يومًا","18 سنة بالضبط"],"h1":"هو بعد 16 سنة، لكنه قبل 17 سنة ونصف بوقت طويل.","h2":"في Indiana يجب أن يكون عمر السائق الذي لم يُكمل دورة تعليم القيادة 16 سنة و270 يومًا على الأقل للحصول على الرخصة التجريبية.","p":"صحيح. دون دورة تعليم القيادة يكون العمر 16 سنة و270 يومًا."},"ref":{"doc":"IN","page":9}},{"id":"in-009","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, during the first 180 days of a probationary license, when may you not drive?","o":["From midnight to 5 a.m.","From 10 p.m. to 5 a.m.","From 9 p.m. to 6 a.m.","From 1 a.m. to 5 a.m."],"h1":"The limit starts at a late evening hour, before midnight.","h2":"In Indiana, for the first 180 days of a probationary license, you may not drive between 10 p.m. and 5 a.m.","p":"Right. No driving from 10 p.m. to 5 a.m. at first."},"es":{"q":"En Indiana, durante los primeros 180 días de la licencia probatoria, ¿cuándo no puede manejar?","o":["De medianoche a 5 a.m.","De 10 p.m. a 5 a.m.","De 9 p.m. a 6 a.m.","De 1 a.m. a 5 a.m."],"h1":"El límite empieza en la noche, antes de la medianoche.","h2":"En Indiana, durante los primeros 180 días de la licencia probatoria, usted no puede manejar entre las 10 p.m. y las 5 a.m.","p":"Correcto. Al principio no se maneja de 10 p.m. a 5 a.m."},"zh":{"q":"在 Indiana，拿到试用驾照的头 180 天里，什么时间不能开车？","o":["午夜到早上 5 点","晚上 10 点到早上 5 点","晚上 9 点到早上 6 点","凌晨 1 点到早上 5 点"],"h1":"这个限制从晚上比较晚的时候开始，在午夜之前。","h2":"在 Indiana，拿到试用驾照的头 180 天里，你不能在晚上 10 点到早上 5 点之间开车。","p":"对。一开始，晚上 10 点到早上 5 点不能开车。"},"vi":{"q":"Ở Indiana, trong 180 ngày đầu tiên của bằng lái thử thách, khi nào bạn không được lái xe?","o":["Từ nửa đêm đến 5 giờ sáng","Từ 10 giờ tối đến 5 giờ sáng","Từ 9 giờ tối đến 6 giờ sáng","Từ 1 giờ sáng đến 5 giờ sáng"],"h1":"Giới hạn bắt đầu vào một giờ muộn buổi tối, trước nửa đêm.","h2":"Ở Indiana, trong 180 ngày đầu tiên của bằng lái thử thách, bạn không được lái xe từ 10 giờ tối đến 5 giờ sáng.","p":"Đúng. Lúc đầu không được lái từ 10 giờ tối đến 5 giờ sáng."},"tl":{"q":"Sa Indiana, sa unang 180 araw ng probationary license, kailan ka hindi puwedeng magmaneho?","o":["Mula hatinggabi hanggang 5 a.m.","Mula 10 p.m. hanggang 5 a.m.","Mula 9 p.m. hanggang 6 a.m.","Mula 1 a.m. hanggang 5 a.m."],"h1":"Nagsisimula ang limitasyon sa isang huling oras ng gabi, bago mag-hatinggabi.","h2":"Sa Indiana, sa unang 180 araw ng probationary license, hindi ka puwedeng magmaneho mula 10 p.m. hanggang 5 a.m.","p":"Tama. Sa simula, bawal magmaneho mula 10 p.m. hanggang 5 a.m."},"ar":{"q":"في Indiana، خلال أول 180 يومًا من الرخصة التجريبية، متى لا يُسمح لك بالقيادة؟","o":["من منتصف الليل حتى 5 صباحًا","من 10 مساءً حتى 5 صباحًا","من 9 مساءً حتى 6 صباحًا","من 1 صباحًا حتى 5 صباحًا"],"h1":"يبدأ المنع في ساعة متأخرة من المساء، قبل منتصف الليل.","h2":"في Indiana، خلال أول 180 يومًا من الرخصة التجريبية، لا يُسمح لك بالقيادة من 10 مساءً حتى 5 صباحًا.","p":"صحيح. في البداية لا قيادة من 10 مساءً حتى 5 صباحًا."},"ref":{"doc":"IN","page":10}},{"id":"in-010","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, after the first 180 days of a probationary license and until 18, when may you not drive on Saturday and Sunday mornings?","o":["From 10 p.m. to 5 a.m.","From 11 p.m. to 5 a.m.","From 1 a.m. to 5 a.m.","From midnight to 6 a.m."],"h1":"On weekend mornings, the limit starts after midnight.","h2":"In Indiana, after the first 180 days and until 18, a probationary driver may not drive from 1 a.m. to 5 a.m. on Saturday and Sunday mornings.","p":"Correct. On weekend mornings, no driving from 1 a.m. to 5 a.m."},"es":{"q":"En Indiana, después de los primeros 180 días de la licencia probatoria y hasta los 18, ¿cuándo no puede manejar los sábados y domingos en la madrugada?","o":["De 10 p.m. a 5 a.m.","De 11 p.m. a 5 a.m.","De 1 a.m. a 5 a.m.","De medianoche a 6 a.m."],"h1":"Los fines de semana, el límite empieza después de la medianoche.","h2":"En Indiana, después de los primeros 180 días y hasta los 18, un conductor probatorio no puede manejar de 1 a.m. a 5 a.m. los sábados y domingos en la madrugada.","p":"Correcto. Los fines de semana, no puede manejar de 1 a.m. a 5 a.m."},"zh":{"q":"在 Indiana，拿到试用驾照满 180 天以后、到 18 岁之前，星期六和星期天早上什么时间不能开车？","o":["晚上 10 点到早上 5 点","晚上 11 点到早上 5 点","凌晨 1 点到早上 5 点","午夜到早上 6 点"],"h1":"在周末的早上，这个限制在午夜以后才开始。","h2":"在 Indiana，满 180 天以后、到 18 岁之前，持试用驾照的司机在星期六和星期天早上的凌晨 1 点到早上 5 点不能开车。","p":"正确。周末早上，凌晨 1 点到早上 5 点不能开车。"},"vi":{"q":"Ở Indiana, sau 180 ngày đầu tiên của bằng lái thử thách và cho đến 18 tuổi, khi nào bạn không được lái xe vào sáng thứ Bảy và Chủ nhật?","o":["Từ 10 giờ tối đến 5 giờ sáng","Từ 11 giờ tối đến 5 giờ sáng","Từ 1 giờ sáng đến 5 giờ sáng","Từ nửa đêm đến 6 giờ sáng"],"h1":"Vào sáng cuối tuần, giới hạn bắt đầu sau nửa đêm.","h2":"Ở Indiana, sau 180 ngày đầu tiên và cho đến 18 tuổi, người lái có bằng thử thách không được lái xe từ 1 giờ sáng đến 5 giờ sáng vào sáng thứ Bảy và Chủ nhật.","p":"Đúng. Vào sáng cuối tuần, không được lái từ 1 giờ sáng đến 5 giờ sáng."},"tl":{"q":"Sa Indiana, pagkatapos ng unang 180 araw ng probationary license at hanggang 18, kailan ka hindi puwedeng magmaneho sa umaga ng Sabado at Linggo?","o":["Mula 10 p.m. hanggang 5 a.m.","Mula 11 p.m. hanggang 5 a.m.","Mula 1 a.m. hanggang 5 a.m.","Mula hatinggabi hanggang 6 a.m."],"h1":"Sa umaga ng weekend, nagsisimula ang limitasyon pagkatapos ng hatinggabi.","h2":"Sa Indiana, pagkatapos ng unang 180 araw at hanggang 18, ang probationary driver ay hindi puwedeng magmaneho mula 1 a.m. hanggang 5 a.m. sa umaga ng Sabado at Linggo.","p":"Tama. Sa umaga ng weekend, bawal magmaneho mula 1 a.m. hanggang 5 a.m."},"ar":{"q":"في Indiana، بعد أول 180 يومًا من الرخصة التجريبية وحتى عمر 18 سنة، متى لا يُسمح لك بالقيادة صباح يومي السبت والأحد؟","o":["من 10 مساءً حتى 5 صباحًا","من 11 مساءً حتى 5 صباحًا","من 1 صباحًا حتى 5 صباحًا","من منتصف الليل حتى 6 صباحًا"],"h1":"في صباح عطلة نهاية الأسبوع يبدأ المنع بعد منتصف الليل.","h2":"في Indiana، بعد أول 180 يومًا وحتى عمر 18 سنة، لا يُسمح لسائق الرخصة التجريبية بالقيادة من 1 صباحًا حتى 5 صباحًا صباح يومي السبت والأحد.","p":"صحيح. في صباح عطلة نهاية الأسبوع لا قيادة من 1 صباحًا حتى 5 صباحًا."},"ref":{"doc":"IN","page":10}},{"id":"in-011","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, after the first 180 days of a probationary license and until 18, when does the limit start on Sunday through Thursday nights?","o":["After 9 p.m.","After 10 p.m.","After 1 a.m.","After 11 p.m."],"h1":"It is one hour later than the limit in the first 180 days.","h2":"In Indiana, after the first 180 days and until 18, a probationary driver may not drive after 11 p.m. on Sunday through Thursday nights.","p":"Right. On school nights, the limit is 11 p.m."},"es":{"q":"En Indiana, después de los primeros 180 días de la licencia probatoria y hasta los 18, ¿a qué hora empieza el límite las noches de domingo a jueves?","o":["Después de las 9 p.m.","Después de las 10 p.m.","Después de la 1 a.m.","Después de las 11 p.m."],"h1":"Es una hora más tarde que el límite de los primeros 180 días.","h2":"En Indiana, después de los primeros 180 días y hasta los 18, un conductor probatorio no puede manejar después de las 11 p.m. de domingo a jueves.","p":"Correcto. Entre semana, el límite es a las 11 p.m."},"zh":{"q":"在 Indiana，拿到试用驾照满 180 天以后、到 18 岁之前，星期天到星期四晚上的限制从几点开始？","o":["晚上 9 点以后","晚上 10 点以后","凌晨 1 点以后","晚上 11 点以后"],"h1":"比头 180 天的限制晚一个小时。","h2":"在 Indiana，满 180 天以后、到 18 岁之前，持试用驾照的司机在星期天到星期四晚上 11 点以后不能开车。","p":"对。第二天要上学的晚上，限制是晚上 11 点。"},"vi":{"q":"Ở Indiana, sau 180 ngày đầu tiên của bằng lái thử thách và cho đến 18 tuổi, giới hạn bắt đầu lúc nào vào các đêm từ Chủ nhật đến thứ Năm?","o":["Sau 9 giờ tối","Sau 10 giờ tối","Sau 1 giờ sáng","Sau 11 giờ tối"],"h1":"Đó là muộn hơn một giờ so với giới hạn trong 180 ngày đầu tiên.","h2":"Ở Indiana, sau 180 ngày đầu tiên và cho đến 18 tuổi, người lái có bằng thử thách không được lái xe sau 11 giờ tối vào các đêm từ Chủ nhật đến thứ Năm.","p":"Đúng. Vào các đêm trước ngày đi học, giới hạn là 11 giờ tối."},"tl":{"q":"Sa Indiana, pagkatapos ng unang 180 araw ng probationary license at hanggang 18, kailan nagsisimula ang limitasyon sa gabi ng Linggo hanggang Huwebes?","o":["Pagkalipas ng 9 p.m.","Pagkalipas ng 10 p.m.","Pagkalipas ng 1 a.m.","Pagkalipas ng 11 p.m."],"h1":"Isang oras itong mas huli kaysa sa limitasyon sa unang 180 araw.","h2":"Sa Indiana, pagkatapos ng unang 180 araw at hanggang 18, ang probationary driver ay hindi puwedeng magmaneho pagkalipas ng 11 p.m. sa gabi ng Linggo hanggang Huwebes.","p":"Tama. Sa mga gabi bago ang araw ng pasok, 11 p.m. ang limitasyon."},"ar":{"q":"في Indiana، بعد أول 180 يومًا من الرخصة التجريبية وحتى عمر 18 سنة، متى يبدأ المنع في ليالي الأحد حتى الخميس؟","o":["بعد 9 مساءً","بعد 10 مساءً","بعد 1 صباحًا","بعد 11 مساءً"],"h1":"هو متأخر بساعة واحدة عن المنع في أول 180 يومًا.","h2":"في Indiana، بعد أول 180 يومًا وحتى عمر 18 سنة، لا يُسمح لسائق الرخصة التجريبية بالقيادة بعد 11 مساءً في ليالي الأحد حتى الخميس.","p":"صحيح. في ليالي أيام الدراسة يبدأ المنع الساعة 11 مساءً."},"ref":{"doc":"IN","page":10}},{"id":"in-012","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, which trip is allowed during the probationary night limits?","o":["Driving to or from work","Driving to a friend's party","Driving to buy snacks","Driving around for fun"],"h1":"The exceptions are for duties, not for fun.","h2":"In Indiana a probationary driver may drive during the night limits to or from work, a school-sanctioned activity or a religious event.","p":"Correct. Work trips are an exception."},"es":{"q":"En Indiana, ¿qué viaje está permitido durante el límite nocturno de la licencia probatoria?","o":["Ir o volver del trabajo","Ir a la fiesta de un amigo","Ir a comprar algo de comer","Dar una vuelta por diversión"],"h1":"Las excepciones son para obligaciones, no para diversión.","h2":"En Indiana, un conductor probatorio puede manejar durante el límite nocturno para ir o volver del trabajo, de una actividad aprobada por la escuela o de un evento religioso.","p":"Correcto. Ir al trabajo es una excepción."},"zh":{"q":"在 Indiana，在试用驾照的夜间限制时间里，哪种出行是允许的？","o":["开车去上班或下班回家","开车去朋友的派对","开车去买零食","开车到处玩"],"h1":"例外是为了必须做的事，不是为了玩。","h2":"在 Indiana，持试用驾照的司机可以在夜间限制时间里开车去上班或下班回家，或者去参加学校批准的活动或宗教活动。","p":"正确。上下班是一个例外。"},"vi":{"q":"Ở Indiana, chuyến đi nào được phép trong giờ giới hạn ban đêm của bằng lái thử thách?","o":["Lái xe đi làm hoặc đi làm về","Lái xe đến tiệc của bạn bè","Lái xe đi mua đồ ăn vặt","Lái xe đi vòng vòng cho vui"],"h1":"Các ngoại lệ là cho bổn phận, không phải để vui chơi.","h2":"Ở Indiana, người lái có bằng thử thách được lái xe trong giờ giới hạn ban đêm để đi làm hoặc đi làm về, đi một hoạt động do trường cho phép, hoặc đi một sự kiện tôn giáo.","p":"Đúng. Chuyến đi làm là một ngoại lệ."},"tl":{"q":"Sa Indiana, aling biyahe ang pinapayagan sa oras ng limitasyon sa gabi para sa probationary driver?","o":["Pagmamaneho papunta o pauwi galing sa trabaho","Pagmamaneho papunta sa party ng kaibigan","Pagmamaneho para bumili ng meryenda","Pag-iikot-ikot para lang magsaya"],"h1":"Ang mga eksepsiyon ay para sa mga tungkulin, hindi para sa kasiyahan.","h2":"Sa Indiana, ang probationary driver ay puwedeng magmaneho sa oras ng limitasyon sa gabi papunta o pauwi galing sa trabaho, sa aktibidad na aprubado ng paaralan, o sa isang relihiyosong okasyon.","p":"Tama. Eksepsiyon ang biyahe para sa trabaho."},"ar":{"q":"في Indiana، أيّ رحلة مسموحة خلال ساعات المنع الليلي للرخصة التجريبية؟","o":["القيادة إلى العمل أو منه","القيادة إلى حفلة صديق","القيادة لشراء وجبات خفيفة","القيادة في جولة للتسلية"],"h1":"الاستثناءات للواجبات، لا للتسلية.","h2":"في Indiana يُسمح لسائق الرخصة التجريبية بالقيادة خلال ساعات المنع الليلي إلى العمل أو منه، أو إلى نشاط توافق عليه المدرسة، أو إلى مناسبة دينية.","p":"صحيح. رحلات العمل استثناء."},"ref":{"doc":"IN","page":10}},{"id":"in-013","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, during the first 180 days of a probationary license, when may you carry a friend as a passenger?","o":["Any time during the day","Only when a qualified adult, such as a licensed driver 25 or older, is in the front seat","Only on weekends","Only if the friend has a license"],"h1":"Think of the same adult who could supervise a learner.","h2":"In Indiana, for the first 180 days, a probationary driver may carry passengers only when a qualified adult, such as a licensed driver at least 25 or a spouse at least 21, is in the front seat; some close family members are allowed.","p":"Right. A qualified adult must be in the front seat."},"es":{"q":"En Indiana, durante los primeros 180 días de la licencia probatoria, ¿cuándo puede llevar a un amigo como pasajero?","o":["En cualquier momento de día","Solo cuando un adulto autorizado, como un conductor con licencia de 25 años o más, va en el asiento delantero","Solo los fines de semana","Solo si el amigo tiene licencia"],"h1":"Piense en el mismo adulto que puede supervisar a un aprendiz.","h2":"En Indiana, durante los primeros 180 días, un conductor probatorio solo puede llevar pasajeros si va en el asiento delantero un adulto autorizado, como un conductor con licencia de por lo menos 25 años o un cónyuge de por lo menos 21; algunos familiares cercanos sí están permitidos.","p":"Correcto. Un adulto autorizado debe ir adelante."},"zh":{"q":"在 Indiana，拿到试用驾照的头 180 天里，什么时候可以载朋友当乘客？","o":["白天任何时间","只有当一位合格的成年人（例如 25 岁或以上、有驾照的司机）坐在前排时","只能在周末","只有当朋友有驾照时"],"h1":"想一想可以陪同学习驾驶的那位成年人。","h2":"在 Indiana，头 180 天里，持试用驾照的司机只有在一位合格的成年人坐在前排时才能载乘客，例如至少 25 岁、有驾照的司机，或至少 21 岁的配偶；有些近亲也可以坐车。","p":"对。前排必须坐着一位合格的成年人。"},"vi":{"q":"Ở Indiana, trong 180 ngày đầu tiên của bằng lái thử thách, khi nào bạn được chở một người bạn?","o":["Bất cứ lúc nào vào ban ngày","Chỉ khi có một người lớn đủ điều kiện, như người có bằng lái từ 25 tuổi trở lên, ngồi ở ghế trước","Chỉ vào cuối tuần","Chỉ khi người bạn có bằng lái"],"h1":"Hãy nghĩ đến chính người lớn có thể giám sát người tập lái.","h2":"Ở Indiana, trong 180 ngày đầu tiên, người lái có bằng thử thách chỉ được chở hành khách khi có một người lớn đủ điều kiện, như người có bằng lái ít nhất 25 tuổi hoặc vợ hay chồng ít nhất 21 tuổi, ngồi ở ghế trước; một số người thân trong gia đình gần gũi được phép.","p":"Đúng. Một người lớn đủ điều kiện phải ngồi ở ghế trước."},"tl":{"q":"Sa Indiana, sa unang 180 araw ng probationary license, kailan ka puwedeng magsakay ng kaibigan bilang pasahero?","o":["Kahit anong oras sa araw","Kapag may kuwalipikadong adult lang, gaya ng driver na may lisensya na 25 o mas matanda, sa upuan sa harap","Tuwing weekend lang","Kung may lisensya lang ang kaibigan"],"h1":"Isipin ang parehong adult na puwedeng magbantay sa isang learner.","h2":"Sa Indiana, sa unang 180 araw, ang probationary driver ay puwedeng magsakay ng pasahero kapag may kuwalipikadong adult lang, gaya ng driver na may lisensya na hindi bababa sa 25 o asawang hindi bababa sa 21, sa upuan sa harap; pinapayagan ang ilang malapit na kapamilya.","p":"Tama. Dapat may kuwalipikadong adult sa upuan sa harap."},"ar":{"q":"في Indiana، خلال أول 180 يومًا من الرخصة التجريبية، متى يُسمح لك بأن تُركب صديقًا معك كراكب؟","o":["في أي وقت خلال النهار","فقط عندما يجلس في المقعد الأمامي شخص بالغ مؤهَّل، مثل سائق مرخّص عمره 25 سنة أو أكثر","في عطلة نهاية الأسبوع فقط","فقط إذا كان الصديق يحمل رخصة"],"h1":"فكّر في الشخص البالغ نفسه الذي يمكنه الإشراف على المتعلّم.","h2":"في Indiana، خلال أول 180 يومًا، يمكن لسائق الرخصة التجريبية أن يُركب ركابًا فقط عندما يجلس في المقعد الأمامي شخص بالغ مؤهَّل، مثل سائق مرخّص عمره 25 سنة على الأقل أو زوج أو زوجة عمره 21 سنة على الأقل؛ ويُسمح ببعض أفراد العائلة المقرّبين.","p":"صحيح. يجب أن يجلس شخص بالغ مؤهَّل في المقعد الأمامي."},"ref":{"doc":"IN","page":10}},{"id":"in-014","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, when does a probationary driver's license expire?","o":["On your 18th birthday","One year after it is issued","30 days after your 21st birthday","On your 25th birthday"],"h1":"It lasts until a little after you can legally drink.","h2":"In Indiana a probationary driver's license expires 30 days after your 21st birthday, and the renewed license has no probationary limits.","p":"Correct. It ends 30 days after you turn 21."},"es":{"q":"En Indiana, ¿cuándo vence la licencia probatoria?","o":["Al cumplir 18 años","Un año después de recibirla","30 días después de cumplir 21 años","Al cumplir 25 años"],"h1":"Dura hasta poco después de la edad legal para tomar alcohol.","h2":"En Indiana la licencia probatoria vence 30 días después de que usted cumple 21 años, y la licencia renovada ya no tiene límites probatorios.","p":"Correcto. Vence 30 días después de cumplir 21."},"zh":{"q":"在 Indiana，试用驾照什么时候到期？","o":["在你 18 岁生日那天","发证一年以后","在你 21 岁生日后 30 天","在你 25 岁生日那天"],"h1":"它一直有效到你可以合法喝酒以后不久。","h2":"在 Indiana，试用驾照在你 21 岁生日后 30 天到期，换新的驾照就没有试用期的限制了。","p":"正确。它在你满 21 岁后 30 天结束。"},"vi":{"q":"Ở Indiana, bằng lái thử thách hết hạn khi nào?","o":["Vào sinh nhật 18 tuổi của bạn","Một năm sau khi được cấp","30 ngày sau sinh nhật 21 tuổi của bạn","Vào sinh nhật 25 tuổi của bạn"],"h1":"Nó kéo dài đến sau tuổi được phép uống rượu một chút.","h2":"Ở Indiana, bằng lái thử thách hết hạn 30 ngày sau sinh nhật 21 tuổi của bạn, và bằng lái được gia hạn không còn giới hạn thử thách.","p":"Đúng. Nó hết hạn 30 ngày sau khi bạn tròn 21 tuổi."},"tl":{"q":"Sa Indiana, kailan mag-e-expire ang probationary driver's license?","o":["Sa ika-18 kaarawan mo","Isang taon pagkatapos itong ibigay","30 araw pagkatapos ng ika-21 kaarawan mo","Sa ika-25 kaarawan mo"],"h1":"Tumatagal ito nang kaunti pagkatapos ng edad na legal nang uminom ng alak.","h2":"Sa Indiana, mag-e-expire ang probationary driver's license 30 araw pagkatapos ng ika-21 kaarawan mo, at ang nire-renew na lisensya ay wala nang probationary na limitasyon.","p":"Tama. Natatapos ito 30 araw pagkatapos mong mag-21."},"ar":{"q":"في Indiana، متى تنتهي صلاحية رخصة القيادة التجريبية؟","o":["في عيد ميلادك الـ 18","بعد سنة من إصدارها","بعد 30 يومًا من عيد ميلادك الـ 21","في عيد ميلادك الـ 25"],"h1":"تستمر حتى ما بعد العمر الذي يُسمح فيه قانونيًا بشرب الكحول بقليل.","h2":"في Indiana تنتهي صلاحية رخصة القيادة التجريبية بعد 30 يومًا من عيد ميلادك الـ 21، والرخصة المجدَّدة ليس فيها قيود تجريبية.","p":"صحيح. تنتهي بعد 30 يومًا من بلوغك 21 سنة."},"ref":{"doc":"IN","page":10}},{"id":"in-015","scope":"IN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Indiana, when may a probationary driver use a phone or other device while driving?","o":["Any time, if it is hands-free","Only at red lights","Only to use a map app","Only to call 911 in an emergency"],"h1":"There is only one exception, and it is for emergencies.","h2":"In Indiana a probationary driver may not use any telecommunication device while driving, even hands-free, except to call 911 in an emergency.","p":"Right. Only an emergency 911 call is allowed."},"es":{"q":"En Indiana, ¿cuándo puede un conductor probatorio usar un teléfono u otro aparato mientras maneja?","o":["En cualquier momento, si es manos libres","Solo en los semáforos en rojo","Solo para usar un mapa","Solo para llamar al 911 en una emergencia"],"h1":"Hay una sola excepción, y es para emergencias.","h2":"En Indiana, un conductor probatorio no puede usar ningún aparato de telecomunicación mientras maneja, ni siquiera manos libres, salvo para llamar al 911 en una emergencia.","p":"Correcto. Solo se permite una llamada de emergencia al 911."},"zh":{"q":"在 Indiana，持试用驾照的司机开车时什么时候可以用手机或其他设备？","o":["任何时候，只要是免提","只能在红灯时","只能用地图软件","只能在紧急情况下打 911"],"h1":"只有一个例外，而且是为了紧急情况。","h2":"在 Indiana，持试用驾照的司机开车时不能使用任何通讯设备，免提也不行，只有在紧急情况下打 911 除外。","p":"对。只允许在紧急情况下打 911。"},"vi":{"q":"Ở Indiana, khi nào người lái có bằng thử thách được dùng điện thoại hoặc thiết bị khác trong lúc lái xe?","o":["Bất cứ lúc nào, nếu không cầm tay (hands-free)","Chỉ khi dừng đèn đỏ","Chỉ để dùng ứng dụng bản đồ","Chỉ để gọi 911 khi khẩn cấp"],"h1":"Chỉ có một ngoại lệ, và đó là cho trường hợp khẩn cấp.","h2":"Ở Indiana, người lái có bằng thử thách không được dùng bất kỳ thiết bị viễn thông nào khi lái xe, kể cả không cầm tay, trừ khi gọi 911 trong trường hợp khẩn cấp.","p":"Đúng. Chỉ được gọi 911 khi khẩn cấp."},"tl":{"q":"Sa Indiana, kailan puwedeng gumamit ng telepono o ibang device ang probationary driver habang nagmamaneho?","o":["Kahit kailan, kung hands-free","Sa red light lang","Para lang gumamit ng map app","Para lang tumawag sa 911 kapag emergency"],"h1":"Iisa lang ang eksepsiyon, at para ito sa emergency.","h2":"Sa Indiana, ang probationary driver ay hindi puwedeng gumamit ng kahit anong telecommunication device habang nagmamaneho, kahit hands-free, maliban kung tatawag sa 911 kapag emergency.","p":"Tama. Ang tawag lang sa 911 kapag emergency ang pinapayagan."},"ar":{"q":"في Indiana، متى يُسمح لسائق الرخصة التجريبية باستخدام الهاتف أو جهاز آخر أثناء القيادة؟","o":["في أي وقت، إذا كان دون استخدام اليدين (hands-free)","عند الإشارة الحمراء فقط","لاستخدام تطبيق الخرائط فقط","للاتصال بـ 911 في حالة الطوارئ فقط"],"h1":"هناك استثناء واحد فقط، وهو لحالات الطوارئ.","h2":"في Indiana لا يُسمح لسائق الرخصة التجريبية باستخدام أي جهاز اتصال أثناء القيادة، حتى دون استخدام اليدين، إلا للاتصال بـ 911 في حالة الطوارئ.","p":"صحيح. يُسمح فقط بالاتصال بـ 911 في الطوارئ."},"ref":{"doc":"IN","page":10}},{"id":"in-016","scope":"IN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Indiana, what does the hands-free law say about all drivers and their phones?","o":["You may not hold a phone in your hand while driving","You may hold a phone below the window","You may text at speeds under 25 mph","Only drivers under 18 must be hands-free"],"h1":"The law's name tells you where your hands should be.","h2":"In Indiana no driver may hold a phone or tablet in their hand while driving; hands-free use such as Bluetooth or a speakerphone is allowed.","p":"Correct. Indiana drivers must stay hands-free."},"es":{"q":"En Indiana, ¿qué dice la ley de manos libres sobre todos los conductores y sus teléfonos?","o":["No puede tener el teléfono en la mano mientras maneja","Puede tener el teléfono debajo de la ventana","Puede enviar mensajes a menos de 25 mph","Solo los menores de 18 deben usar manos libres"],"h1":"El nombre de la ley le dice dónde deben estar sus manos.","h2":"En Indiana ningún conductor puede tener un teléfono o tableta en la mano mientras maneja; se permite el uso manos libres, como Bluetooth o altavoz.","p":"Correcto. En Indiana se maneja con manos libres."},"zh":{"q":"在 Indiana，免提法对所有司机和他们的手机有什么规定？","o":["开车时你不能手里拿着手机","你可以把手机拿在车窗下面","速度低于 25 mph 时你可以发短信","只有 18 岁以下的司机必须用免提"],"h1":"这条法律的名字告诉你，你的手应该在哪里。","h2":"在 Indiana，任何司机开车时都不能手里拿着手机或平板电脑；可以用免提方式，例如蓝牙或扬声器。","p":"正确。Indiana 的司机必须用免提。"},"vi":{"q":"Ở Indiana, luật không cầm tay (hands-free law) nói gì về tất cả người lái xe và điện thoại của họ?","o":["Bạn không được cầm điện thoại trong tay khi lái xe","Bạn được cầm điện thoại thấp hơn cửa sổ","Bạn được nhắn tin khi chạy dưới 25 mph","Chỉ người lái dưới 18 tuổi mới phải không cầm tay"],"h1":"Tên của luật cho bạn biết tay bạn nên ở đâu.","h2":"Ở Indiana, không người lái nào được cầm điện thoại hoặc máy tính bảng trong tay khi lái xe; được phép dùng không cầm tay như Bluetooth hoặc loa ngoài.","p":"Đúng. Người lái ở Indiana phải dùng không cầm tay."},"tl":{"q":"Sa Indiana, ano ang sinasabi ng hands-free law tungkol sa lahat ng driver at sa kanilang telepono?","o":["Hindi mo puwedeng hawakan ang telepono sa kamay habang nagmamaneho","Puwede mong hawakan ang telepono sa ibaba ng bintana","Puwede kang mag-text kapag mas mabagal sa 25 mph","Ang mga driver lang na wala pang 18 ang dapat hands-free"],"h1":"Sinasabi ng pangalan ng batas kung nasaan dapat ang mga kamay mo.","h2":"Sa Indiana, walang driver na puwedeng humawak ng telepono o tablet sa kamay habang nagmamaneho; pinapayagan ang hands-free na paggamit gaya ng Bluetooth o speakerphone.","p":"Tama. Dapat hands-free ang mga driver sa Indiana."},"ar":{"q":"في Indiana، ماذا يقول قانون عدم استخدام اليدين (hands-free law) عن جميع السائقين وهواتفهم؟","o":["لا يُسمح لك بحمل الهاتف بيدك أثناء القيادة","يُسمح لك بحمل الهاتف تحت مستوى النافذة","يُسمح لك بكتابة الرسائل عندما تكون سرعتك أقل من 25 mph","السائقون الذين عمرهم أقل من 18 سنة فقط يجب ألا يستخدموا اليدين"],"h1":"اسم القانون يخبرك أين يجب أن تكون يداك.","h2":"في Indiana لا يُسمح لأي سائق بحمل هاتف أو جهاز لوحي بيده أثناء القيادة؛ ويُسمح بالاستخدام دون اليدين مثل Bluetooth أو مكبّر الصوت.","p":"صحيح. يجب أن يقود السائقون في Indiana دون استخدام اليدين للهاتف."},"ref":{"doc":"IN","page":45}},{"id":"in-017","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, what score do you need on the knowledge exam?","o":["70 percent on the whole test","80 percent or higher on each section","60 percent on each section","100 percent on the signs section"],"h1":"There are two sections, and each must be passed on its own.","h2":"In Indiana you must answer at least 80 percent correctly on each section of the knowledge exam to pass.","p":"Right. You need 80 percent on each section."},"es":{"q":"En Indiana, ¿qué calificación necesita en el examen de conocimientos?","o":["70 por ciento en todo el examen","80 por ciento o más en cada sección","60 por ciento en cada sección","100 por ciento en la sección de señales"],"h1":"Hay dos secciones, y cada una se aprueba por separado.","h2":"En Indiana usted debe contestar bien por lo menos el 80 por ciento de cada sección del examen de conocimientos para aprobar.","p":"Correcto. Se necesita 80 por ciento en cada sección."},"zh":{"q":"在 Indiana，笔试需要考多少分？","o":["整个考试 70%","每个部分 80% 或更高","每个部分 60%","标志部分 100%"],"h1":"考试有两个部分，每个部分都要分别通过。","h2":"在 Indiana，笔试的每个部分你都必须答对至少 80% 才能通过。","p":"对。每个部分都需要 80%。"},"vi":{"q":"Ở Indiana, bạn cần bao nhiêu điểm trong bài thi kiến thức?","o":["70 phần trăm trên toàn bài thi","80 phần trăm trở lên ở mỗi phần","60 phần trăm ở mỗi phần","100 phần trăm ở phần biển báo"],"h1":"Có hai phần, và mỗi phần phải đậu riêng.","h2":"Ở Indiana, bạn phải trả lời đúng ít nhất 80 phần trăm ở mỗi phần của bài thi kiến thức để đậu.","p":"Đúng. Bạn cần 80 phần trăm ở mỗi phần."},"tl":{"q":"Sa Indiana, anong score ang kailangan mo sa knowledge exam?","o":["70 porsiyento sa buong test","80 porsiyento o higit pa sa bawat bahagi","60 porsiyento sa bawat bahagi","100 porsiyento sa bahagi ng mga karatula"],"h1":"May dalawang bahagi, at dapat maipasa ang bawat isa nang hiwalay.","h2":"Sa Indiana, dapat tama ang hindi bababa sa 80 porsiyento ng sagot mo sa bawat bahagi ng knowledge exam para pumasa.","p":"Tama. Kailangan mo ng 80 porsiyento sa bawat bahagi."},"ar":{"q":"في Indiana، ما الدرجة التي تحتاجها في امتحان المعرفة (knowledge exam)؟","o":["70 بالمئة في الامتحان كله","80 بالمئة أو أكثر في كل قسم","60 بالمئة في كل قسم","100 بالمئة في قسم الإشارات"],"h1":"هناك قسمان، ويجب النجاح في كل واحد منهما وحده.","h2":"في Indiana يجب أن تجيب إجابة صحيحة عن 80 بالمئة على الأقل في كل قسم من امتحان المعرفة لكي تنجح.","p":"صحيح. تحتاج إلى 80 بالمئة في كل قسم."},"ref":{"doc":"IN","page":63}},{"id":"in-018","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, what two sections make up the knowledge exam?","o":["Vehicle repair and first aid","Parking and car insurance","Traffic rules and traffic signs","Night driving and map reading"],"h1":"One part is about what to do, the other about what you see beside the road.","h2":"In Indiana the knowledge exam has one section on traffic rules and driving maneuvers and one section on traffic signs.","p":"Correct. Rules and signs are the two sections."},"es":{"q":"En Indiana, ¿cuáles son las dos secciones del examen de conocimientos?","o":["Reparación de vehículos y primeros auxilios","Estacionamiento y seguro de auto","Reglas de tránsito y señales de tránsito","Manejo nocturno y lectura de mapas"],"h1":"Una parte trata de qué hacer, y la otra de lo que ve al lado del camino.","h2":"En Indiana el examen de conocimientos tiene una sección sobre reglas de tránsito y maniobras, y otra sobre señales de tránsito.","p":"Correcto. Reglas y señales son las dos secciones."},"zh":{"q":"在 Indiana，笔试由哪两个部分组成？","o":["汽车维修和急救","停车和汽车保险","交通规则和交通标志","夜间驾驶和看地图"],"h1":"一部分是关于要怎么做，另一部分是关于你在路边看到的东西。","h2":"在 Indiana，笔试有一个部分考交通规则和驾驶操作，另一个部分考交通标志。","p":"正确。规则和标志是两个部分。"},"vi":{"q":"Ở Indiana, bài thi kiến thức gồm hai phần nào?","o":["Sửa xe và sơ cứu","Đậu xe và bảo hiểm xe","Luật giao thông và biển báo giao thông","Lái xe ban đêm và đọc bản đồ"],"h1":"Một phần nói về việc phải làm gì, phần kia nói về những gì bạn thấy bên đường.","h2":"Ở Indiana, bài thi kiến thức có một phần về luật giao thông và cách lái xe, và một phần về biển báo giao thông.","p":"Đúng. Luật và biển báo là hai phần."},"tl":{"q":"Sa Indiana, anong dalawang bahagi ang bumubuo sa knowledge exam?","o":["Pagkumpuni ng sasakyan at first aid","Pagparada at insurance ng sasakyan","Mga patakaran sa trapiko at mga karatula sa trapiko","Pagmamaneho sa gabi at pagbasa ng mapa"],"h1":"Ang isang bahagi ay tungkol sa dapat gawin, ang isa naman ay tungkol sa nakikita mo sa tabi ng daan.","h2":"Sa Indiana, ang knowledge exam ay may isang bahagi tungkol sa mga patakaran sa trapiko at paraan ng pagmamaneho, at isang bahagi tungkol sa mga karatula sa trapiko.","p":"Tama. Patakaran at karatula ang dalawang bahagi."},"ar":{"q":"في Indiana، ما القسمان اللذان يتكوّن منهما امتحان المعرفة؟","o":["إصلاح السيارات والإسعافات الأولية","ركن السيارة وتأمين السيارة","قواعد المرور وإشارات المرور","القيادة الليلية وقراءة الخرائط"],"h1":"قسم عمّا يجب أن تفعله، والآخر عمّا تراه بجانب الطريق.","h2":"في Indiana يتكوّن امتحان المعرفة من قسم عن قواعد المرور وطرق القيادة، وقسم عن إشارات المرور.","p":"صحيح. القواعد والإشارات هما القسمان."},"ref":{"doc":"IN","page":63}},{"id":"in-019","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, a 15-year-old in driver education may practice with a parent only after finishing how much of the classroom or online part?","o":["5 hours","10 hours","50 hours","30 hours"],"h1":"It is the same number as the days in most months.","h2":"In Indiana a 15-year-old in driver education must finish 30 hours of the classroom or online part before practicing with a parent or other supervisor.","p":"Right. Thirty hours of classroom or online work come first."},"es":{"q":"En Indiana, un joven de 15 años en educación vial puede practicar con un padre solo después de terminar ¿cuánto de la parte en clase o en línea?","o":["5 horas","10 horas","50 horas","30 horas"],"h1":"Es el mismo número que los días de casi todos los meses.","h2":"En Indiana, un joven de 15 años en educación vial debe terminar 30 horas de la parte en clase o en línea antes de practicar con un padre u otro supervisor.","p":"Correcto. Primero vienen 30 horas de clase o en línea."},"zh":{"q":"在 Indiana，上驾驶课的 15 岁学生，要完成课堂或网上部分的多少，才能和父母一起练车？","o":["5 小时","10 小时","50 小时","30 小时"],"h1":"和大多数月份的天数一样。","h2":"在 Indiana，上驾驶课的 15 岁学生必须先完成 30 小时课堂或网上部分，才能和父母或其他陪同者练车。","p":"对。先完成三十个小时的课堂或网上学习。"},"vi":{"q":"Ở Indiana, một người 15 tuổi đang học giáo dục lái xe chỉ được tập lái với cha mẹ sau khi học xong bao nhiêu giờ phần lớp học hoặc phần trực tuyến?","o":["5 giờ","10 giờ","50 giờ","30 giờ"],"h1":"Đó là bằng số ngày trong hầu hết các tháng.","h2":"Ở Indiana, một người 15 tuổi đang học giáo dục lái xe phải học xong 30 giờ phần lớp học hoặc trực tuyến trước khi tập lái với cha mẹ hoặc người giám sát khác.","p":"Đúng. Phải học xong 30 giờ lớp học hoặc trực tuyến trước."},"tl":{"q":"Sa Indiana, ang 15 taong gulang na nasa driver education ay puwedeng mag-ensayo kasama ang magulang pagkatapos lang matapos ang ilang oras ng bahagi sa classroom o online?","o":["5 oras","10 oras","50 oras","30 oras"],"h1":"Kapareho ito ng bilang ng araw sa karamihan ng buwan.","h2":"Sa Indiana, ang 15 taong gulang na nasa driver education ay dapat matapos ang 30 oras ng bahagi sa classroom o online bago mag-ensayo kasama ang magulang o ibang tagabantay.","p":"Tama. Unang tatapusin ang 30 oras sa classroom o online."},"ar":{"q":"في Indiana، يمكن لشخص عمره 15 سنة في دورة تعليم القيادة أن يتدرّب مع أحد الوالدين فقط بعد إنهاء كم من الجزء الصفّي أو الجزء عبر الإنترنت؟","o":["5 ساعات","10 ساعات","50 ساعة","30 ساعة"],"h1":"هو نفس عدد الأيام في معظم الشهور.","h2":"في Indiana يجب على من عمره 15 سنة في دورة تعليم القيادة أن يُنهي 30 ساعة من الجزء الصفّي أو الجزء عبر الإنترنت قبل التدرّب مع أحد الوالدين أو مشرف آخر.","p":"صحيح. تأتي أولًا 30 ساعة من الدراسة في الصف أو عبر الإنترنت."},"ref":{"doc":"IN","page":null}},{"id":"in-020","scope":"IN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Indiana, you approach a stopped tow truck with amber flashing lights and you cannot safely change lanes. What must you do?","o":["Slow to 10 mph below the speed limit","Keep your speed and honk","Slow to 5 mph below the speed limit","Stop completely in your lane"],"h1":"Indiana sets a number below the posted limit.","h2":"In Indiana, if you cannot move away from a stopped vehicle with flashing lights, you must slow to 10 mph below the speed limit and drive with caution.","p":"Correct. Slow down by 10 mph."},"es":{"q":"En Indiana, se acerca a una grúa detenida con luces ámbar intermitentes y no puede cambiar de carril con seguridad. ¿Qué debe hacer?","o":["Bajar a 10 mph menos que el límite de velocidad","Mantener la velocidad y tocar la bocina","Bajar a 5 mph menos que el límite","Detenerse por completo en su carril"],"h1":"Indiana fija un número por debajo del límite.","h2":"En Indiana, si no puede alejarse de un vehículo detenido con luces intermitentes, debe bajar a 10 mph menos que el límite de velocidad y manejar con cuidado.","p":"Correcto. Baje 10 mph."},"zh":{"q":"在 Indiana，你靠近一辆停着、闪着琥珀色灯的拖车，而且你不能安全换道。你必须做什么？","o":["减速到比限速低 10 mph","保持速度并按喇叭","减速到比限速低 5 mph","在你的车道上完全停下"],"h1":"Indiana 规定了比标示限速低的一个数字。","h2":"在 Indiana，如果你不能离开停着、闪着灯的车辆，就必须减速到比限速低 10 mph，并小心驾驶。","p":"正确。减速 10 mph。"},"vi":{"q":"Ở Indiana, bạn đến gần một xe kéo đang dừng có đèn nhấp nháy màu vàng cam và bạn không thể đổi làn an toàn. Bạn phải làm gì?","o":["Giảm tốc độ xuống thấp hơn tốc độ giới hạn 10 mph","Giữ nguyên tốc độ và bấm còi","Giảm tốc độ xuống thấp hơn tốc độ giới hạn 5 mph","Dừng hẳn trong làn của bạn"],"h1":"Indiana quy định một con số thấp hơn tốc độ giới hạn được ghi trên biển.","h2":"Ở Indiana, nếu bạn không thể tránh xa một xe đang dừng có đèn nhấp nháy, bạn phải giảm tốc độ xuống thấp hơn tốc độ giới hạn 10 mph và lái xe cẩn thận.","p":"Đúng. Giảm tốc độ 10 mph."},"tl":{"q":"Sa Indiana, papalapit ka sa nakahintong tow truck na may kumikislap na amber na ilaw at hindi ka ligtas na makalipat ng lane. Ano ang dapat mong gawin?","o":["Bumagal hanggang 10 mph na mas mababa sa speed limit","Panatilihin ang bilis at bumusina","Bumagal hanggang 5 mph na mas mababa sa speed limit","Huminto nang tuluyan sa lane mo"],"h1":"May itinakdang numero ang Indiana na mas mababa sa nakapaskil na limit.","h2":"Sa Indiana, kung hindi ka makakalayo sa nakahintong sasakyan na may kumikislap na ilaw, dapat kang bumagal hanggang 10 mph na mas mababa sa speed limit at magmaneho nang maingat.","p":"Tama. Bumagal nang 10 mph."},"ar":{"q":"في Indiana، تقترب من شاحنة سحب متوقفة أضواؤها الكهرمانية تومض، ولا يمكنك تغيير المسار بأمان. ماذا يجب أن تفعل؟","o":["خفّف السرعة إلى 10 mph أقل من الحد الأقصى للسرعة","حافظ على سرعتك واستخدم البوق","خفّف السرعة إلى 5 mph أقل من الحد الأقصى للسرعة","توقّف تمامًا في مسارك"],"h1":"تحدّد Indiana رقمًا أقل من الحد المكتوب على اللافتة.","h2":"في Indiana، إذا لم تستطع الابتعاد عن مركبة متوقفة أضواؤها تومض، يجب أن تخفّف السرعة إلى 10 mph أقل من الحد الأقصى للسرعة وتقود بحذر.","p":"صحيح. خفّف السرعة بمقدار 10 mph."},"ref":{"doc":"IN","page":51}},{"id":"in-021","scope":"IN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Indiana, a school bus is stopped with its stop arm out on the other side of a road divided by a barrier or an unpaved median. What must you do?","o":["Stop and wait until the bus moves","You do not have to stop, but you must drive with care","Stop only if children are visible","Stop and then pass at 10 mph"],"h1":"The median or barrier separates you from the bus.","h2":"In Indiana you do not need to stop for a school bus on the other side of a road divided by a barrier or an unpaved median, but you must drive with care.","p":"Right. The divided highway lets you continue carefully."},"es":{"q":"En Indiana, un autobús escolar está detenido con el brazo de alto extendido al otro lado de una carretera dividida por una barrera o una mediana sin pavimentar. ¿Qué debe hacer?","o":["Detenerse y esperar a que el autobús avance","No tiene que detenerse, pero debe manejar con cuidado","Detenerse solo si ve niños","Detenerse y luego pasar a 10 mph"],"h1":"La mediana o barrera lo separa del autobús.","h2":"En Indiana usted no tiene que detenerse por un autobús escolar al otro lado de una carretera dividida por una barrera o una mediana sin pavimentar, pero debe manejar con cuidado.","p":"Correcto. La carretera dividida le permite seguir con cuidado."},"zh":{"q":"在 Indiana，一辆校车伸出停车臂，停在被隔离墩或没铺路面的隔离带分开的道路另一边。你必须做什么？","o":["停车，等到校车开走","你不用停车，但必须小心驾驶","只有看到小孩时才停车","停车，然后以 10 mph 开过去"],"h1":"隔离带或隔离墩把你和校车分开了。","h2":"在 Indiana，校车在被隔离墩或没铺路面的隔离带分开的道路另一边时，你不用停车，但必须小心驾驶。","p":"对。在分隔公路上，你可以小心地继续开。"},"vi":{"q":"Ở Indiana, một xe buýt trường học đang dừng và giơ cần báo dừng (stop arm) ở phía bên kia của một con đường được ngăn cách bằng rào chắn hoặc dải phân cách không trải nhựa. Bạn phải làm gì?","o":["Dừng lại và chờ đến khi xe buýt chạy","Bạn không phải dừng, nhưng phải lái xe cẩn thận","Chỉ dừng nếu thấy trẻ em","Dừng lại rồi vượt qua với tốc độ 10 mph"],"h1":"Dải phân cách hoặc rào chắn ngăn cách bạn với xe buýt.","h2":"Ở Indiana, bạn không cần dừng lại cho xe buýt trường học ở phía bên kia của con đường được ngăn cách bằng rào chắn hoặc dải phân cách không trải nhựa, nhưng bạn phải lái xe cẩn thận.","p":"Đúng. Đường có phân cách cho phép bạn tiếp tục chạy một cách cẩn thận."},"tl":{"q":"Sa Indiana, may school bus na nakahinto at nakalabas ang stop arm sa kabilang panig ng daan na hinahati ng harang o ng median na hindi sementado. Ano ang dapat mong gawin?","o":["Huminto at maghintay hanggang umandar ang bus","Hindi mo kailangang huminto, pero dapat kang magmaneho nang maingat","Huminto lang kung may nakikitang mga bata","Huminto at saka lumampas sa 10 mph"],"h1":"Hinihiwalay ka ng median o harang mula sa bus.","h2":"Sa Indiana, hindi mo kailangang huminto para sa school bus sa kabilang panig ng daan na hinahati ng harang o ng median na hindi sementado, pero dapat kang magmaneho nang maingat.","p":"Tama. Sa hinating daan, puwede kang magpatuloy nang maingat."},"ar":{"q":"في Indiana، حافلة مدرسية متوقفة وذراع التوقف (stop arm) ممدود، على الجهة الأخرى من طريق مقسوم بحاجز أو بجزيرة وسطية غير معبّدة. ماذا يجب أن تفعل؟","o":["توقّف وانتظر حتى تتحرك الحافلة","ليس عليك أن تتوقف، لكن يجب أن تقود بحذر","توقّف فقط إذا رأيت أطفالًا","توقّف ثم تجاوز بسرعة 10 mph"],"h1":"الجزيرة الوسطية أو الحاجز يفصلك عن الحافلة.","h2":"في Indiana لا تحتاج إلى التوقف لحافلة مدرسية على الجهة الأخرى من طريق مقسوم بحاجز أو بجزيرة وسطية غير معبّدة، لكن يجب أن تقود بحذر.","p":"صحيح. الطريق المقسوم يسمح لك بالمتابعة بحذر."},"ref":{"doc":"IN","page":52}},{"id":"in-022","scope":"IN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Indiana, what blood alcohol level breaks the law for a driver under 21?","o":["0.08 or more","0.05 or more","0.02 or more","0.10 or more"],"h1":"It is much lower than the adult limit.","h2":"In Indiana a driver under 21 breaks the law with a blood alcohol level of 0.02 or more.","p":"Correct. For drivers under 21 the limit is 0.02."},"es":{"q":"En Indiana, ¿qué nivel de alcohol en la sangre viola la ley para un conductor menor de 21 años?","o":["0.08 o más","0.05 o más","0.02 o más","0.10 o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Indiana, un conductor menor de 21 años viola la ley con un nivel de alcohol en la sangre de 0.02 o más.","p":"Correcto. Para menores de 21 el límite es 0.02."},"zh":{"q":"在 Indiana，对 21 岁以下的司机来说，血液酒精浓度多少就违法？","o":["0.08 或更高","0.05 或更高","0.02 或更高","0.10 或更高"],"h1":"这比成年人的上限低很多。","h2":"在 Indiana，21 岁以下的司机血液酒精浓度达到 0.02 或更高就是违法。","p":"正确。21 岁以下的司机，上限是 0.02。"},"vi":{"q":"Ở Indiana, nồng độ cồn trong máu bao nhiêu là phạm luật đối với người lái dưới 21 tuổi?","o":["0.08 trở lên","0.05 trở lên","0.02 trở lên","0.10 trở lên"],"h1":"Nó thấp hơn nhiều so với giới hạn của người lớn.","h2":"Ở Indiana, người lái dưới 21 tuổi phạm luật nếu nồng độ cồn trong máu là 0.02 trở lên.","p":"Đúng. Với người lái dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa Indiana, anong antas ng alak sa dugo ang labag sa batas para sa driver na wala pang 21?","o":["0.08 o higit pa","0.05 o higit pa","0.02 o higit pa","0.10 o higit pa"],"h1":"Mas mababa ito nang malaki kaysa sa limit para sa adult.","h2":"Sa Indiana, lumalabag sa batas ang driver na wala pang 21 kapag ang antas ng alak sa dugo niya ay 0.02 o higit pa.","p":"Tama. Para sa mga driver na wala pang 21, 0.02 ang limit."},"ar":{"q":"في Indiana، ما نسبة الكحول في الدم التي تُعدّ مخالفة للقانون للسائق الذي عمره أقل من 21 سنة؟","o":["0.08 أو أكثر","0.05 أو أكثر","0.02 أو أكثر","0.10 أو أكثر"],"h1":"هي أقل بكثير من الحد المسموح للبالغين.","h2":"في Indiana يخالف السائق الذي عمره أقل من 21 سنة القانون إذا كانت نسبة الكحول في دمه 0.02 أو أكثر.","p":"صحيح. للسائقين الذين أعمارهم أقل من 21 سنة الحد هو 0.02."},"ref":{"doc":"IN","page":null}},{"id":"in-023","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, how long is a learner's permit valid?","o":["6 months","Two years","One year","Until you turn 18"],"h1":"It lasts longer than the time you must hold it before a license.","h2":"In Indiana a learner's permit is valid for two years from the day it is issued.","p":"Right. A learner's permit lasts two years."},"es":{"q":"En Indiana, ¿por cuánto tiempo es válido el permiso de aprendizaje?","o":["6 meses","Dos años","Un año","Hasta que cumpla 18 años"],"h1":"Dura más que el tiempo que debe tenerlo antes de la licencia.","h2":"En Indiana el permiso de aprendizaje es válido por dos años desde el día en que se emite.","p":"Correcto. El permiso de aprendizaje dura dos años."},"zh":{"q":"在 Indiana，学习驾照（learner's permit）的有效期是多久？","o":["6 个月","两年","一年","到你满 18 岁为止"],"h1":"它比你拿驾照前必须持有它的时间更长。","h2":"在 Indiana，学习驾照从发放那天起有效两年。","p":"对。学习驾照有效两年。"},"vi":{"q":"Ở Indiana, giấy phép tập lái (learner's permit) có giá trị trong bao lâu?","o":["6 tháng","Hai năm","Một năm","Cho đến khi bạn 18 tuổi"],"h1":"Nó lâu hơn thời gian bạn phải giữ nó trước khi lấy bằng lái.","h2":"Ở Indiana, giấy phép tập lái có giá trị hai năm kể từ ngày được cấp.","p":"Đúng. Giấy phép tập lái có giá trị hai năm."},"tl":{"q":"Sa Indiana, gaano katagal valid ang learner's permit?","o":["6 na buwan","Dalawang taon","Isang taon","Hanggang mag-18 ka"],"h1":"Mas matagal ito kaysa sa panahong dapat mo itong hawak bago magka-lisensya.","h2":"Sa Indiana, valid ang learner's permit nang dalawang taon mula sa araw na ibinigay ito.","p":"Tama. Dalawang taon ang tagal ng learner's permit."},"ar":{"q":"في Indiana، كم مدة صلاحية تصريح التعلّم (learner's permit)؟","o":["6 أشهر","سنتان","سنة واحدة","حتى تبلغ 18 سنة"],"h1":"مدتها أطول من المدة التي يجب أن تحمله فيها قبل الرخصة.","h2":"في Indiana يكون تصريح التعلّم صالحًا لمدة سنتين من يوم إصداره.","p":"صحيح. تصريح التعلّم صالح لمدة سنتين."},"ref":{"doc":"IN","page":4}},{"id":"in-024","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, you move to a new home. How soon must you tell the BMV and get an updated license?","o":["Within 1 year","At your next renewal","Within 7 days","Within 30 days"],"h1":"You have about one month.","h2":"In Indiana you must tell the BMV about a new legal address and get an updated license within 30 days of moving.","p":"Right. Update your address within 30 days."},"es":{"q":"En Indiana, usted se muda a una casa nueva. ¿En cuánto tiempo debe avisar al BMV y obtener una licencia actualizada?","o":["En 1 año","En su próxima renovación","En 7 días","En 30 días"],"h1":"Tiene más o menos un mes.","h2":"En Indiana usted debe avisar al BMV de su nueva dirección legal y obtener una licencia actualizada en los 30 días siguientes a la mudanza.","p":"Correcto. Actualice su dirección en 30 días."},"zh":{"q":"在 Indiana，你搬了新家。你必须在多久之内通知 BMV 并更新驾照？","o":["1 年之内","下次续期的时候","7 天之内","30 天之内"],"h1":"你大约有一个月的时间。","h2":"在 Indiana，搬家后你必须在 30 天之内把新的法定地址告诉 BMV，并拿到更新后的驾照。","p":"对。在 30 天之内更新你的地址。"},"vi":{"q":"Ở Indiana, bạn dọn đến nhà mới. Bạn phải báo cho BMV và lấy bằng lái cập nhật trong bao lâu?","o":["Trong vòng 1 năm","Vào lần gia hạn tới","Trong vòng 7 ngày","Trong vòng 30 ngày"],"h1":"Bạn có khoảng một tháng.","h2":"Ở Indiana, bạn phải báo cho BMV địa chỉ hợp pháp mới và lấy bằng lái cập nhật trong vòng 30 ngày sau khi dọn nhà.","p":"Đúng. Hãy cập nhật địa chỉ trong vòng 30 ngày."},"tl":{"q":"Sa Indiana, lumipat ka sa bagong bahay. Gaano kabilis mo dapat sabihan ang BMV at kumuha ng updated na lisensya?","o":["Sa loob ng 1 taon","Sa susunod mong renewal","Sa loob ng 7 araw","Sa loob ng 30 araw"],"h1":"Mayroon kang mga isang buwan.","h2":"Sa Indiana, dapat mong sabihan ang BMV tungkol sa bago mong legal na address at kumuha ng updated na lisensya sa loob ng 30 araw mula nang lumipat ka.","p":"Tama. I-update ang address mo sa loob ng 30 araw."},"ar":{"q":"في Indiana، انتقلت إلى بيت جديد. خلال كم من الوقت يجب أن تُبلغ BMV وتحصل على رخصة محدّثة؟","o":["خلال سنة واحدة (1)","عند التجديد القادم","خلال 7 أيام","خلال 30 يومًا"],"h1":"لديك شهر تقريبًا.","h2":"في Indiana يجب أن تُبلغ BMV بعنوانك القانوني الجديد وتحصل على رخصة محدّثة خلال 30 يومًا من الانتقال.","p":"صحيح. حدّث عنوانك خلال 30 يومًا."},"ref":{"doc":"IN","page":20}},{"id":"in-025","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, how long do points for a traffic violation stay active on your driving record?","o":["Two years from the conviction date","Six months","Ten years","For the rest of your life"],"h1":"It is more than one year but less than five.","h2":"In Indiana, points stay active on your driving record for two years from the date you were convicted.","p":"Right. Points stay active for two years."},"es":{"q":"En Indiana, ¿por cuánto tiempo siguen activos en su historial de manejo los puntos por una infracción de tránsito?","o":["Dos años desde la fecha de la condena","Seis meses","Diez años","Para toda la vida"],"h1":"Es más de un año, pero menos de cinco.","h2":"En Indiana los puntos siguen activos en su historial de manejo por dos años desde la fecha de la condena.","p":"Correcto. Los puntos siguen activos por dos años."},"zh":{"q":"在 Indiana，交通违规的扣分在你的驾驶记录上有效多久？","o":["从定罪那天起两年","六个月","十年","一辈子"],"h1":"比一年长，但比五年短。","h2":"在 Indiana，扣分从你被定罪那天起在驾驶记录上有效两年。","p":"对。扣分有效两年。"},"vi":{"q":"Ở Indiana, điểm phạt vì vi phạm giao thông còn hiệu lực trong hồ sơ lái xe của bạn bao lâu?","o":["Hai năm kể từ ngày bị kết tội","Sáu tháng","Mười năm","Suốt đời"],"h1":"Lâu hơn một năm nhưng ít hơn năm năm.","h2":"Ở Indiana, điểm phạt còn hiệu lực trong hồ sơ lái xe của bạn hai năm kể từ ngày bạn bị kết tội.","p":"Đúng. Điểm phạt còn hiệu lực hai năm."},"tl":{"q":"Sa Indiana, gaano katagal aktibo sa driving record mo ang mga point para sa isang traffic violation?","o":["Dalawang taon mula sa petsa ng conviction","Anim na buwan","Sampung taon","Habambuhay"],"h1":"Higit ito sa isang taon pero kulang sa lima.","h2":"Sa Indiana, aktibo ang mga point sa driving record mo nang dalawang taon mula sa petsa na na-convict ka.","p":"Tama. Aktibo ang mga point nang dalawang taon."},"ar":{"q":"في Indiana، كم تبقى نقاط المخالفة المرورية فعّالة في سجل قيادتك؟","o":["سنتان من تاريخ الإدانة","ستة أشهر","عشر سنوات","طوال حياتك"],"h1":"أكثر من سنة واحدة لكن أقل من خمس سنوات.","h2":"في Indiana تبقى النقاط فعّالة في سجل قيادتك لمدة سنتين من تاريخ إدانتك.","p":"صحيح. تبقى النقاط فعّالة لمدة سنتين."},"ref":{"doc":"IN","page":21}},{"id":"in-026","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, what is the minimum liability insurance a driver must carry?","o":["10/20/10","50/100/50","25/50/25","15/30/5"],"h1":"The first and last numbers are the same: $25,000.","h2":"Indiana's minimum liability insurance is 25/50/25: $25,000 for one person hurt, $50,000 for two or more people, and $25,000 for property damage.","p":"Right. The minimum is 25/50/25."},"es":{"q":"En Indiana, ¿cuál es el seguro de responsabilidad mínimo que debe tener un conductor?","o":["10/20/10","50/100/50","25/50/25","15/30/5"],"h1":"El primer y el último número son iguales: $25,000.","h2":"El seguro de responsabilidad mínimo en Indiana es 25/50/25: $25,000 por una persona herida, $50,000 por dos o más personas y $25,000 por daños a la propiedad.","p":"Correcto. El mínimo es 25/50/25."},"zh":{"q":"在 Indiana，司机必须买的最低责任保险是多少？","o":["10/20/10","50/100/50","25/50/25","15/30/5"],"h1":"第一个和最后一个数字相同：$25,000。","h2":"Indiana 的最低责任保险是 25/50/25：一人受伤 $25,000，两人或更多人受伤 $50,000，财产损失 $25,000。","p":"对。最低是 25/50/25。"},"vi":{"q":"Ở Indiana, bảo hiểm trách nhiệm tối thiểu mà người lái phải có là bao nhiêu?","o":["10/20/10","50/100/50","25/50/25","15/30/5"],"h1":"Số đầu và số cuối giống nhau: $25,000.","h2":"Bảo hiểm trách nhiệm tối thiểu ở Indiana là 25/50/25: $25,000 cho một người bị thương, $50,000 cho hai người trở lên, và $25,000 cho thiệt hại tài sản.","p":"Đúng. Mức tối thiểu là 25/50/25."},"tl":{"q":"Sa Indiana, ano ang pinakamababang liability insurance na dapat mayroon ang driver?","o":["10/20/10","50/100/50","25/50/25","15/30/5"],"h1":"Pareho ang una at huling numero: $25,000.","h2":"Ang pinakamababang liability insurance sa Indiana ay 25/50/25: $25,000 para sa isang taong nasaktan, $50,000 para sa dalawa o higit pang tao, at $25,000 para sa pinsala sa ari-arian.","p":"Tama. Ang pinakamababa ay 25/50/25."},"ar":{"q":"في Indiana، ما الحد الأدنى من تأمين المسؤولية الذي يجب أن يكون لدى السائق؟","o":["10/20/10","50/100/50","25/50/25","15/30/5"],"h1":"الرقم الأول والرقم الأخير متساويان: $25,000.","h2":"الحد الأدنى لتأمين المسؤولية في Indiana هو 25/50/25: $25,000 لإصابة شخص واحد، و$50,000 لشخصين أو أكثر، و$25,000 لأضرار الممتلكات.","p":"صحيح. الحد الأدنى هو 25/50/25."},"ref":{"doc":"IN","page":22}},{"id":"in-027","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, how many points do you get for driving 26 mph or more over the speed limit?","o":["2 points","6 points","4 points","1 point"],"h1":"The faster you go over the limit, the more points you get.","h2":"In Indiana, driving 26 mph or more over the speed limit puts 6 points on your driving record.","p":"Right. 26 mph or more over the limit is 6 points."},"es":{"q":"En Indiana, ¿cuántos puntos recibe por manejar 26 mph o más por encima del límite de velocidad?","o":["2 puntos","6 puntos","4 puntos","1 punto"],"h1":"Mientras más rápido vaya sobre el límite, más puntos recibe.","h2":"En Indiana, manejar 26 millas por hora o más por encima del límite de velocidad le pone 6 puntos en su historial de manejo.","p":"Correcto. 26 mph o más sobre el límite son 6 puntos."},"zh":{"q":"在 Indiana，超速 26 mph 或更多，会被记几分？","o":["2 分","6 分","4 分","1 分"],"h1":"超速越多，记的分就越多。","h2":"在 Indiana，超过限速 26 mph 或更多，会在你的驾驶记录上记 6 分。","p":"对。超速 26 mph 或更多记 6 分。"},"vi":{"q":"Ở Indiana, bạn bị bao nhiêu điểm phạt khi lái nhanh hơn tốc độ giới hạn 26 mph trở lên?","o":["2 điểm","6 điểm","4 điểm","1 điểm"],"h1":"Bạn càng chạy quá tốc độ nhiều thì càng bị nhiều điểm.","h2":"Ở Indiana, lái nhanh hơn tốc độ giới hạn 26 mph trở lên sẽ bị ghi 6 điểm vào hồ sơ lái xe của bạn.","p":"Đúng. Quá tốc độ 26 mph trở lên là 6 điểm."},"tl":{"q":"Sa Indiana, ilang point ang makukuha mo kapag nagmaneho ka nang 26 mph o higit pa sa speed limit?","o":["2 point","6 point","4 point","1 point"],"h1":"Habang mas bumibilis ka lampas sa limit, mas maraming point ang makukuha mo.","h2":"Sa Indiana, ang pagmamaneho nang 26 mph o higit pa sa speed limit ay naglalagay ng 6 point sa driving record mo.","p":"Tama. Ang 26 mph o higit pa sa limit ay 6 point."},"ar":{"q":"في Indiana، كم نقطة تحصل عليها إذا قدت بسرعة تزيد على حد السرعة بمقدار 26 mph أو أكثر؟","o":["نقطتان (2)","6 نقاط","4 نقاط","نقطة واحدة (1)"],"h1":"كلما زادت سرعتك فوق الحد، زادت النقاط التي تحصل عليها.","h2":"في Indiana، القيادة بسرعة تزيد على حد السرعة بمقدار 26 mph أو أكثر تضع 6 نقاط في سجل قيادتك.","p":"صحيح. الزيادة 26 mph أو أكثر فوق الحد تساوي 6 نقاط."},"ref":{"doc":"IN","page":21}},{"id":"in-028","scope":"IN","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Indiana, when you pass another vehicle, how far from an oncoming vehicle must you be back on the right side of the road?","o":["At least 25 feet","At least 50 feet","At least 100 feet","At least 1,000 feet"],"h1":"The distance is about one third of a football field.","h2":"In Indiana, you must return to the right side of the road at least 100 feet before any oncoming vehicle.","p":"Right. Be back on the right at least 100 feet before an oncoming vehicle."},"es":{"q":"En Indiana, al rebasar a otro vehículo, ¿a qué distancia de un vehículo que viene de frente debe estar ya en el lado derecho del camino?","o":["Al menos 25 pies","Al menos 50 pies","Al menos 100 pies","Al menos 1,000 pies"],"h1":"La distancia es como un tercio de un campo de fútbol americano.","h2":"En Indiana, usted debe volver al lado derecho del camino al menos 100 pies antes de cualquier vehículo que viene de frente.","p":"Correcto. Vuelva a la derecha al menos 100 pies antes del vehículo que viene."},"zh":{"q":"在 Indiana，超过另一辆车时，你必须在离对面来车多远的地方回到道路右侧？","o":["至少 25 英尺","至少 50 英尺","至少 100 英尺","至少 1,000 英尺"],"h1":"这个距离大约是一个美式足球场长度的三分之一。","h2":"在 Indiana，你必须在离任何对面来车至少 100 英尺的地方回到道路右侧。","p":"对。在离对面来车至少 100 英尺时回到右侧。"},"vi":{"q":"Ở Indiana, khi vượt một xe khác, bạn phải trở về bên phải đường khi còn cách xe đi ngược chiều bao xa?","o":["Ít nhất 25 feet","Ít nhất 50 feet","Ít nhất 100 feet","Ít nhất 1,000 feet"],"h1":"Khoảng cách này bằng khoảng một phần ba sân bóng bầu dục Mỹ.","h2":"Ở Indiana, bạn phải trở về bên phải đường khi còn cách bất kỳ xe đi ngược chiều nào ít nhất 100 feet.","p":"Đúng. Trở về bên phải khi còn cách xe ngược chiều ít nhất 100 feet."},"tl":{"q":"Sa Indiana, kapag nag-overtake ka ng ibang sasakyan, gaano kalayo dapat sa paparating na sasakyan ka nakabalik na sa kanang bahagi ng daan?","o":["Hindi bababa sa 25 feet","Hindi bababa sa 50 feet","Hindi bababa sa 100 feet","Hindi bababa sa 1,000 feet"],"h1":"Ang layo ay mga isang katlo ng isang football field.","h2":"Sa Indiana, dapat nakabalik ka na sa kanang bahagi ng daan nang hindi bababa sa 100 feet bago ang anumang paparating na sasakyan.","p":"Tama. Bumalik sa kanan nang hindi bababa sa 100 feet bago ang paparating na sasakyan."},"ar":{"q":"في Indiana، عندما تتجاوز مركبة أخرى، على أي مسافة من المركبة القادمة من الاتجاه المعاكس يجب أن تكون قد عدت إلى الجانب الأيمن من الطريق؟","o":["25 feet على الأقل","50 feet على الأقل","100 feet على الأقل","1,000 feet على الأقل"],"h1":"هذه المسافة تساوي تقريبًا ثلث طول ملعب كرة قدم أمريكية.","h2":"في Indiana يجب أن تعود إلى الجانب الأيمن من الطريق قبل أي مركبة قادمة من الاتجاه المعاكس بمسافة 100 feet على الأقل.","p":"صحيح. عُد إلى اليمين قبل المركبة القادمة بمسافة 100 feet على الأقل."},"ref":{"doc":"IN","page":38}},{"id":"in-029","scope":"IN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Indiana, how does the speed limit in a highway work site compare with the usual limit for that area?","o":["It is at least 10 mph lower","It is exactly 5 mph lower","It is the same as the usual limit","It is always 25 mph"],"h1":"Work site limits are always lower by a set minimum amount.","h2":"In Indiana, a work site speed limit is always at least 10 mph below the usual maximum limit for that area.","p":"Right. Work site limits are at least 10 mph lower."},"es":{"q":"En Indiana, ¿cómo es el límite de velocidad en una zona de trabajo en la carretera comparado con el límite normal de esa área?","o":["Es al menos 10 mph más bajo","Es exactamente 5 mph más bajo","Es igual al límite normal","Siempre es de 25 mph"],"h1":"El límite en zonas de trabajo siempre es más bajo por una cantidad mínima fija.","h2":"En Indiana, el límite de velocidad en una zona de trabajo siempre es al menos 10 mph más bajo que el límite máximo normal de esa área.","p":"Correcto. En zonas de trabajo el límite es al menos 10 mph más bajo."},"zh":{"q":"在 Indiana，公路施工区的限速和这个地区平时的限速相比怎么样？","o":["至少低 10 mph","正好低 5 mph","和平时的限速一样","永远是 25 mph"],"h1":"施工区的限速总是比平时低，而且有一个最少要低的数。","h2":"在 Indiana，施工区的限速总是比这个地区平时的最高限速至少低 10 mph。","p":"对。施工区的限速至少低 10 mph。"},"vi":{"q":"Ở Indiana, tốc độ giới hạn trong khu công trường trên xa lộ so với tốc độ giới hạn thông thường của khu vực đó thì thế nào?","o":["Thấp hơn ít nhất 10 mph","Thấp hơn đúng 5 mph","Bằng tốc độ giới hạn thông thường","Luôn luôn là 25 mph"],"h1":"Tốc độ giới hạn ở khu công trường luôn thấp hơn ít nhất một mức nhất định.","h2":"Ở Indiana, tốc độ giới hạn ở khu công trường luôn thấp hơn tốc độ tối đa thông thường của khu vực đó ít nhất 10 mph.","p":"Đúng. Tốc độ giới hạn ở khu công trường thấp hơn ít nhất 10 mph."},"tl":{"q":"Sa Indiana, paano ikinukumpara ang speed limit sa work site sa highway sa karaniwang speed limit sa lugar na iyon?","o":["Mas mababa ito nang hindi bababa sa 10 mph","Mas mababa ito nang eksaktong 5 mph","Pareho ito sa karaniwang speed limit","Palagi itong 25 mph"],"h1":"Ang speed limit sa work site ay palaging mas mababa nang may takdang pinakamaliit na halaga.","h2":"Sa Indiana, ang speed limit sa work site ay palaging mas mababa nang hindi bababa sa 10 mph kaysa sa karaniwang maximum na speed limit sa lugar na iyon.","p":"Tama. Ang speed limit sa work site ay mas mababa nang hindi bababa sa 10 mph."},"ar":{"q":"في Indiana، كيف يُقارَن حد السرعة في منطقة أعمال على الطريق السريع بالحد المعتاد في تلك المنطقة؟","o":["أقل بمقدار 10 mph على الأقل","أقل بمقدار 5 mph بالضبط","هو نفس الحد المعتاد","هو دائمًا 25 mph"],"h1":"حد السرعة في منطقة الأعمال أقل دائمًا بمقدار أدنى محدّد.","h2":"في Indiana يكون حد السرعة في منطقة الأعمال دائمًا أقل بمقدار 10 mph على الأقل من الحد الأقصى المعتاد في تلك المنطقة.","p":"صحيح. حد السرعة في منطقة الأعمال أقل بمقدار 10 mph على الأقل."},"ref":{"doc":"IN","page":41}},{"id":"in-030","scope":"IN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Indiana, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 30 feet","No closer than 50 feet","No closer than 15 feet"],"h1":"Fire trucks need room to reach the hydrant.","h2":"In Indiana, you may not park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a hydrant."},"es":{"q":"En Indiana, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 30 pies","No más cerca de 50 pies","No más cerca de 15 pies"],"h1":"Los bomberos necesitan espacio para llegar al hidrante.","h2":"En Indiana, usted no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese al menos a 15 pies de un hidrante."},"zh":{"q":"在 Indiana，你可以把车停在离消防栓多近的地方？","o":["不能少于 5 英尺","不能少于 30 英尺","不能少于 50 英尺","不能少于 15 英尺"],"h1":"消防车需要空间才能用到消防栓。","h2":"在 Indiana，你不可以把车停在离消防栓 15 英尺以内的地方。","p":"对。离消防栓至少 15 英尺。"},"vi":{"q":"Ở Indiana, bạn được đậu xe gần trụ nước chữa cháy đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 30 feet","Không gần hơn 50 feet","Không gần hơn 15 feet"],"h1":"Xe cứu hỏa cần chỗ để tới được trụ nước.","h2":"Ở Indiana, bạn không được đậu xe trong vòng 15 feet tính từ trụ nước chữa cháy.","p":"Đúng. Hãy cách trụ nước ít nhất 15 feet."},"tl":{"q":"Sa Indiana, gaano kalapit sa fire hydrant ka puwedeng mag-park?","o":["Hindi lalapit sa 5 feet","Hindi lalapit sa 30 feet","Hindi lalapit sa 50 feet","Hindi lalapit sa 15 feet"],"h1":"Kailangan ng mga fire truck ng espasyo para maabot ang hydrant.","h2":"Sa Indiana, hindi ka puwedeng mag-park sa loob ng 15 feet mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 15 feet mula sa hydrant."},"ar":{"q":"في Indiana، إلى أي مدى يمكنك أن تركن قريبًا من صنبور إطفاء الحريق؟","o":["ليس أقرب من 5 feet","ليس أقرب من 30 feet","ليس أقرب من 50 feet","ليس أقرب من 15 feet"],"h1":"سيارات الإطفاء تحتاج إلى مساحة لتصل إلى الصنبور.","h2":"في Indiana لا يجوز لك أن تركن على بُعد أقل من 15 feet من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بُعد 15 feet على الأقل من الصنبور."},"ref":{"doc":"IN","page":54}},{"id":"in-031","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, your license has been expired for 200 days. What must you do to renew it?","o":["Pay only the usual renewal fee online","Pay a penalty, pass a knowledge exam and a vision test","Pay a penalty and pass only a driving skills test","Wait one year, then retake driver education"],"h1":"After about six months, the BMV wants to check what you know and how you see.","h2":"In Indiana, if your license has been expired for at least 180 days but less than five years, you must pay a penalty and pass a knowledge exam and a vision screening.","p":"Right. Pay the penalty and pass the knowledge exam and vision screening."},"es":{"q":"En Indiana, su licencia lleva 200 días vencida. ¿Qué debe hacer para renovarla?","o":["Pagar solo la tarifa normal de renovación en línea","Pagar una multa, aprobar un examen de conocimientos y una prueba de la vista","Pagar una multa y aprobar solo un examen práctico de manejo","Esperar un año y tomar otra vez el curso de manejo"],"h1":"Después de unos seis meses, el BMV quiere revisar lo que usted sabe y cómo ve.","h2":"En Indiana, si su licencia lleva vencida al menos 180 días pero menos de cinco años, usted debe pagar una multa y aprobar un examen de conocimientos y una prueba de la vista.","p":"Correcto. Pague la multa y apruebe el examen de conocimientos y la prueba de la vista."},"zh":{"q":"在 Indiana，你的驾照已经过期 200 天了。你要怎样才能更新它？","o":["只要在网上付平常的更新费","付罚款，并通过知识考试和视力检查","付罚款，并只通过驾驶技能考试","等一年，然后重新上驾驶课"],"h1":"过了大约六个月，BMV 想检查你懂多少、看得清不清楚。","h2":"在 Indiana，如果你的驾照已经过期至少 180 天但不到五年，你必须付罚款，并通过知识考试和视力检查。","p":"对。付罚款，并通过知识考试和视力检查。"},"vi":{"q":"Ở Indiana, bằng lái của bạn đã hết hạn 200 ngày. Bạn phải làm gì để gia hạn?","o":["Chỉ trả phí gia hạn thông thường trên mạng","Trả tiền phạt, thi đậu bài thi kiến thức và kiểm tra thị lực","Trả tiền phạt và chỉ thi đậu bài thi kỹ năng lái xe","Chờ một năm, rồi học lại giáo dục lái xe"],"h1":"Sau khoảng sáu tháng, BMV muốn kiểm tra những gì bạn biết và mắt bạn nhìn ra sao.","h2":"Ở Indiana, nếu bằng lái của bạn đã hết hạn ít nhất 180 ngày nhưng chưa tới năm năm, bạn phải trả tiền phạt và thi đậu bài thi kiến thức và kiểm tra thị lực.","p":"Đúng. Trả tiền phạt và thi đậu bài thi kiến thức và kiểm tra thị lực."},"tl":{"q":"Sa Indiana, 200 araw nang expired ang lisensya mo. Ano ang dapat mong gawin para ma-renew ito?","o":["Bayaran lang ang karaniwang renewal fee online","Magbayad ng multa, pumasa sa knowledge exam at sa vision test","Magbayad ng multa at pumasa lang sa driving skills test","Maghintay ng isang taon, saka ulitin ang driver education"],"h1":"Pagkalipas ng mga anim na buwan, gusto ng BMV na suriin ang alam mo at kung gaano ka kalinaw makakita.","h2":"Sa Indiana, kung expired na ang lisensya mo nang hindi bababa sa 180 araw pero wala pang limang taon, dapat kang magbayad ng multa at pumasa sa knowledge exam at sa vision screening.","p":"Tama. Magbayad ng multa at pumasa sa knowledge exam at vision screening."},"ar":{"q":"في Indiana، انتهت صلاحية رخصتك منذ 200 يوم. ماذا يجب أن تفعل لتجديدها؟","o":["تدفع رسوم التجديد المعتادة فقط عبر الإنترنت","تدفع غرامة وتنجح في اختبار المعرفة وفحص النظر","تدفع غرامة وتنجح فقط في اختبار مهارات القيادة","تنتظر سنة واحدة ثم تعيد دورة تعليم القيادة"],"h1":"بعد نحو ستة أشهر، يريد BMV أن يتحقق مما تعرفه ومن قدرتك على الرؤية.","h2":"في Indiana، إذا انتهت صلاحية رخصتك منذ 180 يومًا على الأقل ولكن أقل من خمس سنوات، يجب أن تدفع غرامة وتنجح في اختبار المعرفة وفحص النظر.","p":"صحيح. ادفع الغرامة وانجح في اختبار المعرفة وفحص النظر."},"ref":{"doc":"IN","page":19}},{"id":"in-032","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, you just moved here and became a resident. How long do you have to get an Indiana driver's license?","o":["30 days","10 days","60 days","One year"],"h1":"It is about two months.","h2":"In Indiana, a new resident has 60 days to get an Indiana driver's license.","p":"Right. New residents have 60 days."},"es":{"q":"En Indiana, usted acaba de mudarse y ahora es residente. ¿Cuánto tiempo tiene para sacar una licencia de manejar de Indiana?","o":["30 días","10 días","60 días","Un año"],"h1":"Son unos dos meses.","h2":"En Indiana, un nuevo residente tiene 60 días para sacar una licencia de manejar de Indiana.","p":"Correcto. Los nuevos residentes tienen 60 días."},"ref":{"doc":"IN","page":2}},{"id":"in-033","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, how long is a regular driver's license valid for a driver younger than 75?","o":["Six years","Two years","Ten years","Four years"],"h1":"Older drivers renew more often than this.","h2":"In Indiana, a driver's license is valid for six years if you are younger than 75.","p":"Right. Under 75, a license lasts six years."},"es":{"q":"En Indiana, ¿por cuánto tiempo es válida una licencia de manejar normal para un conductor menor de 75 años?","o":["Seis años","Dos años","Diez años","Cuatro años"],"h1":"Los conductores mayores la renuevan más seguido.","h2":"En Indiana, una licencia de manejar es válida por seis años si usted tiene menos de 75 años.","p":"Correcto. Antes de los 75, la licencia dura seis años."},"ref":{"doc":"IN","page":9}},{"id":"in-034","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, you fail the knowledge exam. When may you take it again?","o":["After 30 days","After seven days","After six months","The next business day"],"h1":"The wait is very short.","h2":"In Indiana, if you fail the knowledge exam, you may take it again on the next business day.","p":"Right. You can retake it the next business day."},"es":{"q":"En Indiana, usted no aprueba el examen de conocimientos. ¿Cuándo puede tomarlo otra vez?","o":["Después de 30 días","Después de siete días","Después de seis meses","El siguiente día hábil"],"h1":"La espera es muy corta.","h2":"En Indiana, si no aprueba el examen de conocimientos, puede tomarlo otra vez el siguiente día hábil.","p":"Correcto. Puede repetirlo el siguiente día hábil."},"ref":{"doc":"IN","page":5}},{"id":"in-035","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, you fail the driving skills exam. How long must you wait before you take it again?","o":["Until the next day","Seven days","Six months","One year"],"h1":"It is about one week.","h2":"In Indiana, after you fail a driving skills exam, you must wait seven days before you take it again.","p":"Right. You wait seven days to retake the skills exam."},"es":{"q":"En Indiana, usted no aprueba el examen práctico de manejo. ¿Cuánto tiempo debe esperar para tomarlo otra vez?","o":["Hasta el día siguiente","Siete días","Seis meses","Un año"],"h1":"Es como una semana.","h2":"En Indiana, si no aprueba un examen práctico de manejo, debe esperar siete días para tomarlo otra vez.","p":"Correcto. Espera siete días para repetir el examen práctico."},"ref":{"doc":"IN","page":7}},{"id":"in-036","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, how many points do you get for a hand-held phone violation while driving?","o":["2 points","8 points","4 points","10 points"],"h1":"It is the same number of points as running a stop sign.","h2":"In Indiana, a violation for using a hand-held device while driving puts 4 points on your record.","p":"Right. A hand-held device violation is 4 points."},"es":{"q":"En Indiana, ¿cuántos puntos recibe por una infracción de usar el teléfono en la mano mientras maneja?","o":["2 puntos","8 puntos","4 puntos","10 puntos"],"h1":"Son los mismos puntos que por no respetar una señal de alto.","h2":"En Indiana, una infracción por usar un aparato en la mano mientras maneja le pone 4 puntos en su historial.","p":"Correcto. Usar un aparato en la mano son 4 puntos."},"ref":{"doc":"IN","page":21}},{"id":"in-037","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, any driver may finish a BMV-approved Driver Safety Program course. What does it give you?","o":["A four-point credit on your record","A free license renewal","All points erased forever","A lower insurance minimum"],"h1":"It helps your point total.","h2":"In Indiana, finishing a BMV-approved Driver Safety Program course gives you a four-point credit, once every three years.","p":"Right. The course gives a four-point credit."},"es":{"q":"En Indiana, cualquier conductor puede terminar un curso del Programa de Seguridad del Conductor aprobado por el BMV. ¿Qué le da?","o":["Un crédito de cuatro puntos en su historial","Una renovación de licencia gratis","Borrar todos los puntos para siempre","Un mínimo de seguro más bajo"],"h1":"Ayuda con su total de puntos.","h2":"En Indiana, terminar un curso del Programa de Seguridad del Conductor aprobado por el BMV le da un crédito de cuatro puntos, una vez cada tres años.","p":"Correcto. El curso da un crédito de cuatro puntos."},"ref":{"doc":"IN","page":21}},{"id":"in-038","scope":"IN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Indiana, a driver fails a chemical test for alcohol. How long will the driver's license be suspended?","o":["30 days","180 days","5 years","10 years"],"h1":"It is about half a year.","h2":"In Indiana, a driver who fails a chemical test faces a 180-day suspension of driving privileges.","p":"Right. Failing a chemical test means a 180-day suspension."},"es":{"q":"En Indiana, un conductor no pasa una prueba química de alcohol. ¿Por cuánto tiempo le suspenden la licencia?","o":["30 días","180 días","5 años","10 años"],"h1":"Es como medio año.","h2":"En Indiana, un conductor que no pasa una prueba química enfrenta una suspensión de 180 días de su privilegio de manejar.","p":"Correcto. No pasar la prueba química significa 180 días de suspensión."},"ref":{"doc":"IN","page":24}},{"id":"in-039","scope":"IN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Indiana, a driver with an earlier drunk driving (OWI) conviction refuses a chemical test. How long is the suspension?","o":["90 days","1 year","180 days","2 years"],"h1":"The earlier conviction makes it longer than a first refusal.","h2":"In Indiana, a driver with a previous OWI conviction who refuses a chemical test faces a two-year suspension.","p":"Right. A refusal after an earlier OWI conviction means two years."},"es":{"q":"En Indiana, un conductor que ya tiene una condena anterior por manejar intoxicado (OWI) se niega a una prueba química. ¿Cuánto dura la suspensión?","o":["90 días","1 año","180 días","2 años"],"h1":"La condena anterior la hace más larga que una primera negativa.","h2":"En Indiana, un conductor con una condena anterior por OWI que se niega a una prueba química enfrenta una suspensión de dos años.","p":"Correcto. Negarse después de una condena por OWI significa dos años."},"ref":{"doc":"IN","page":24}},{"id":"in-040","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, your license was suspended for the first time for driving without insurance. What is the reinstatement fee?","o":["$250","$1,000","$50","$500"],"h1":"The fee goes up with each new suspension.","h2":"In Indiana, the reinstatement fee for a first no-insurance suspension is $250.","p":"Right. A first no-insurance suspension costs $250 to reinstate."},"es":{"q":"En Indiana, le suspendieron la licencia por primera vez por manejar sin seguro. ¿Cuánto cuesta la cuota para restablecerla?","o":["$250","$1,000","$50","$500"],"h1":"La cuota sube con cada nueva suspensión.","h2":"En Indiana, la cuota para restablecer la licencia después de una primera suspensión por no tener seguro es de $250.","p":"Correcto. La primera suspensión por no tener seguro cuesta $250."},"ref":{"doc":"IN","page":23}},{"id":"in-041","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, you are 30 years old and have 6 active points on your record. What must you do to renew your license?","o":["Take a driving skills exam","Wait one year before renewing","Take the knowledge exam","Nothing extra; just pay the fee"],"h1":"It is a written test, not a road test.","h2":"In Indiana, a driver 21 or older with six or more active points must take the knowledge exam to renew a license.","p":"Right. Six or more active points means taking the knowledge exam."},"es":{"q":"En Indiana, usted tiene 30 años y 6 puntos activos en su historial. ¿Qué debe hacer para renovar su licencia?","o":["Tomar un examen práctico de manejo","Esperar un año antes de renovar","Tomar el examen de conocimientos","Nada más; solo pagar la cuota"],"h1":"Es un examen escrito, no de manejo.","h2":"En Indiana, un conductor de 21 años o más con seis o más puntos activos debe tomar el examen de conocimientos para renovar la licencia.","p":"Correcto. Seis o más puntos activos significa tomar el examen de conocimientos."},"ref":{"doc":"IN","page":19}},{"id":"in-042","scope":"IN","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Indiana, what is the speed limit on a rural state divided highway when no other limit is posted?","o":["45 mph","60 mph","70 mph","50 mph"],"h1":"It is lower than the rural interstate limit.","h2":"In Indiana, the speed limit on a rural state divided highway is 60 mph unless another limit is posted.","p":"Right. A rural state divided highway is 60 mph."},"es":{"q":"En Indiana, ¿cuál es el límite de velocidad en una carretera estatal dividida en zona rural cuando no hay otro límite indicado?","o":["45 mph","60 mph","70 mph","50 mph"],"h1":"Es más bajo que el límite de una interestatal rural.","h2":"En Indiana, el límite de velocidad en una carretera estatal dividida en zona rural es de 60 millas por hora, a menos que haya otro límite indicado.","p":"Correcto. Una carretera estatal dividida rural es de 60 mph."},"ref":{"doc":"IN","page":40}},{"id":"in-043","scope":"IN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Indiana, what is the speed limit in an alley when no other limit is posted?","o":["30 mph","25 mph","20 mph","15 mph"],"h1":"It is the lowest of these choices.","h2":"In Indiana, the speed limit in an alley is 15 mph unless another limit is posted.","p":"Right. The alley limit is 15 mph."},"es":{"q":"En Indiana, ¿cuál es el límite de velocidad en un callejón cuando no hay otro límite indicado?","o":["30 mph","25 mph","20 mph","15 mph"],"h1":"Es el más bajo de estas opciones.","h2":"En Indiana, el límite de velocidad en un callejón es de 15 millas por hora, a menos que haya otro límite indicado.","p":"Correcto. En un callejón el límite es 15 mph."},"ref":{"doc":"IN","page":41}},{"id":"in-044","scope":"IN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Indiana, you are driving behind another vehicle at night with high beams on. How close may you get before you must switch to low beams?","o":["Within 200 feet","Within 50 feet","Within 1,000 feet","Within 500 feet"],"h1":"The distance for a car ahead is shorter than for an oncoming car.","h2":"In Indiana, you must use low beams when you are following within 200 feet of another vehicle.","p":"Right. Dim your lights within 200 feet of the car ahead."},"es":{"q":"En Indiana, de noche usted maneja detrás de otro vehículo con las luces altas. ¿A qué distancia debe cambiar a luces bajas?","o":["A 200 pies o menos","A 50 pies o menos","A 1,000 pies o menos","A 500 pies o menos"],"h1":"La distancia para un auto adelante es menor que para uno que viene de frente.","h2":"En Indiana, debe usar luces bajas cuando va a 200 pies o menos detrás de otro vehículo.","p":"Correcto. Baje las luces a 200 pies del auto de adelante."},"ref":{"doc":"IN","page":44}},{"id":"in-045","scope":"IN","cat":"signals","sign":null,"c":2,"en":{"q":"In Indiana, a motorcycle rider is stuck at a red light that does not turn green. What may the rider do?","o":["Wait for green, no matter how long","Go after a 10-second stop","Go with care after stopping for at least two minutes","Turn on hazard lights and go at once"],"h1":"The rider must stop fully and wait a set time first.","h2":"In Indiana, a motorcycle rider at a red light that does not change may go with care after a complete stop of at least two minutes.","p":"Right. After a full stop of at least two minutes, the rider may go with care."},"es":{"q":"En Indiana, un motociclista está detenido en un semáforo en rojo que no cambia a verde. ¿Qué puede hacer?","o":["Esperar la luz verde, sin importar cuánto tarde","Avanzar después de parar 10 segundos","Avanzar con cuidado después de parar al menos dos minutos","Prender las luces de emergencia y avanzar enseguida"],"h1":"Primero debe parar por completo y esperar un tiempo fijo.","h2":"En Indiana, un motociclista en un semáforo en rojo que no cambia puede avanzar con cuidado después de parar por completo al menos dos minutos.","p":"Correcto. Después de parar al menos dos minutos, puede avanzar con cuidado."},"ref":{"doc":"IN","page":35}},{"id":"in-046","scope":"IN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Indiana, a driver commits aggressive driving when, in one trip, the driver does at least how many acts such as tailgating, honking for no reason, or flashing headlights again and again?","o":["One","Three","Two","Five"],"h1":"It takes more than a pair of these acts.","h2":"In Indiana, a driver commits aggressive driving by doing at least three of the listed unsafe acts during one episode of driving.","p":"Right. Three or more of these acts in one trip is aggressive driving."},"es":{"q":"En Indiana, ¿cuántos actos como seguir muy de cerca, tocar la bocina sin razón o hacer cambio de luces una y otra vez debe hacer un conductor, como mínimo, en un mismo viaje para que sea manejo agresivo?","o":["Uno","Tres","Dos","Cinco"],"h1":"Se necesita más de un par de estos actos.","h2":"En Indiana, un conductor maneja de forma agresiva cuando hace al menos tres de los actos peligrosos de la lista en un mismo viaje.","p":"Correcto. Tres o más de estos actos en un viaje es manejo agresivo."},"ref":{"doc":"IN","page":46}},{"id":"in-047","scope":"IN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Indiana, a driver recklessly passes a stopped school bus with its stop arm out, and no one is hurt. What kind of offense is this?","o":["A warning only","A parking ticket","A Class C infraction","A Class A misdemeanor"],"h1":"It is a crime, not just a ticket.","h2":"In Indiana, recklessly passing a school bus with its stop arm out is a Class A misdemeanor, and it becomes a felony if someone is hurt or killed.","p":"Right. Reckless passing of a stopped school bus is a Class A misdemeanor."},"es":{"q":"En Indiana, un conductor rebasa de forma imprudente un autobús escolar detenido con el brazo de alto extendido, y nadie sale herido. ¿Qué tipo de delito es?","o":["Solo una advertencia","Una multa de estacionamiento","Una infracción Clase C","Un delito menor Clase A"],"h1":"Es un delito, no solo una multa.","h2":"En Indiana, rebasar de forma imprudente un autobús escolar con el brazo de alto extendido es un delito menor Clase A, y pasa a ser un delito grave si alguien sale herido o muere.","p":"Correcto. Rebasar de forma imprudente un autobús escolar detenido es un delito menor Clase A."},"ref":{"doc":"IN","page":52}},{"id":"in-048","scope":"IN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Indiana, on a regular road with no bike path, how many bicyclists may ride side by side?","o":["No more than two","Only one; never side by side","Up to four","Any number"],"h1":"Think of a pair.","h2":"In Indiana, bicyclists may not ride more than two side by side, except on paths or lanes set aside for bicycles.","p":"Right. No more than two side by side."},"es":{"q":"En Indiana, en un camino normal sin ciclovía, ¿cuántos ciclistas pueden ir uno al lado del otro?","o":["No más de dos","Solo uno; nunca lado a lado","Hasta cuatro","Cualquier número"],"h1":"Piense en una pareja.","h2":"En Indiana, los ciclistas no pueden ir más de dos lado a lado, excepto en caminos o carriles solo para bicicletas.","p":"Correcto. No más de dos lado a lado."},"ref":{"doc":"IN","page":52}},{"id":"in-049","scope":"IN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Indiana, how much following time should you leave behind a motorcycle?","o":["About one second","Half a second","At least three or four seconds","No set gap; stay close so the rider sees you"],"h1":"Give more time than you might behind a car.","h2":"In Indiana, you should leave at least three or four seconds when following a motorcycle.","p":"Right. Leave at least three or four seconds behind a motorcycle."},"es":{"q":"En Indiana, ¿cuánto tiempo de distancia debe dejar detrás de una motocicleta?","o":["Como un segundo","Medio segundo","Al menos tres o cuatro segundos","Ninguno fijo; vaya cerca para que el motociclista lo vea"],"h1":"Deje más tiempo del que dejaría detrás de un auto.","h2":"En Indiana, debe dejar al menos tres o cuatro segundos cuando sigue a una motocicleta.","p":"Correcto. Deje al menos tres o cuatro segundos detrás de una motocicleta."},"ref":{"doc":"IN","page":52}},{"id":"in-050","scope":"IN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Indiana, children younger than what age must ride in a child car seat or booster seat?","o":["Younger than 2","Younger than 4","Younger than 5","Younger than 8"],"h1":"The age is in the early school years.","h2":"In Indiana, passengers younger than eight must be secured in a child restraint, such as a car seat or booster seat.","p":"Right. Children under 8 need a car seat or booster seat."},"es":{"q":"En Indiana, ¿los niños menores de qué edad deben ir en un asiento de seguridad o asiento elevado?","o":["Menores de 2","Menores de 4","Menores de 5","Menores de 8"],"h1":"La edad está en los primeros años de escuela.","h2":"En Indiana, los pasajeros menores de ocho años deben ir asegurados en un sistema para niños, como un asiento de seguridad o un asiento elevado.","p":"Correcto. Los niños menores de 8 necesitan asiento de seguridad o elevado."},"ref":{"doc":"IN","page":56}},{"id":"in-051","scope":"IN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Indiana, a police car signals you to pull over. What does the driver's manual suggest you do first to show the officer you see them?","o":["Get out and walk to the police car","Turn on your right turn signal","Stop at once in the center median","Call the officer on your phone"],"h1":"Use something already in your car that other drivers can see.","h2":"In Indiana, the manual suggests you turn on your right turn signal to show the officer you know they are there, then pull onto the right shoulder.","p":"Right. Turn on your right turn signal, then pull to the right."},"es":{"q":"En Indiana, una patrulla le indica que se orille. ¿Qué sugiere el manual que haga primero para mostrar al policía que lo vio?","o":["Bajarse y caminar hacia la patrulla","Prender la direccional derecha","Parar enseguida en el camellón central","Llamar al policía por teléfono"],"h1":"Use algo de su auto que los demás puedan ver.","h2":"En Indiana, el manual sugiere prender la direccional derecha para mostrar al policía que sabe que está ahí, y luego orillarse al acotamiento derecho.","p":"Correcto. Prenda la direccional derecha y luego oríllese a la derecha."},"ref":{"doc":"IN","page":60}},{"id":"ks-001","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, what is the youngest age to get an instruction permit?","o":["13 years old","14 years old","15 years old","16 years old"],"h1":"Kansas lets teens start earlier than most states.","h2":"In Kansas you can get an instruction permit at 14, one of the youngest permit ages in the country.","p":"Right. The Kansas permit starts at 14."},"es":{"q":"En Kansas, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["13 años","14 años","15 años","16 años"],"h1":"Kansas permite empezar más temprano que la mayoría de los estados.","h2":"En Kansas usted puede obtener el permiso de instrucción a los 14 años, una de las edades más bajas del país.","p":"Correcto. El permiso en Kansas empieza a los 14."},"zh":{"q":"在 Kansas，最小几岁可以拿到学习驾照（instruction permit）？","o":["13 岁","14 岁","15 岁","16 岁"],"h1":"Kansas 让青少年比大多数州更早开始。","h2":"在 Kansas，你 14 岁就可以拿到学习驾照，这是全国最小的学习驾照年龄之一。","p":"对。Kansas 的学习驾照从 14 岁开始。"},"vi":{"q":"Ở Kansas, tuổi nhỏ nhất để lấy giấy phép tập lái (instruction permit) là bao nhiêu?","o":["13 tuổi","14 tuổi","15 tuổi","16 tuổi"],"h1":"Kansas cho thanh thiếu niên bắt đầu sớm hơn hầu hết các tiểu bang khác.","h2":"Ở Kansas, bạn có thể lấy giấy phép tập lái khi 14 tuổi, là một trong những tuổi nhỏ nhất cả nước.","p":"Đúng. Giấy phép tập lái ở Kansas bắt đầu từ 14 tuổi."},"tl":{"q":"Sa Kansas, ano ang pinakabatang edad para makakuha ng instruction permit?","o":["13 taong gulang","14 taong gulang","15 taong gulang","16 taong gulang"],"h1":"Mas maagang pinapayagan ng Kansas ang mga kabataan kaysa sa karamihan ng estado.","h2":"Sa Kansas, puwede kang kumuha ng instruction permit sa edad na 14, isa sa pinakabatang edad para sa permit sa buong bansa.","p":"Tama. Nagsisimula ang permit sa Kansas sa 14."},"ar":{"q":"في Kansas، ما أصغر عمر للحصول على تصريح التعلّم (instruction permit)؟","o":["13 سنة","14 سنة","15 سنة","16 سنة"],"h1":"تسمح Kansas للمراهقين بالبدء أبكر من معظم الولايات.","h2":"في Kansas يمكنك الحصول على تصريح التعلّم في عمر 14 سنة، وهو من أصغر أعمار التصريح في البلاد.","p":"صحيح. يبدأ التصريح في Kansas من عمر 14 سنة."},"ref":{"doc":"KS","page":12}},{"id":"ks-002","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kansas, how old must the licensed adult supervising a permit driver be?","o":["At least 16","At least 18","At least 25","At least 21"],"h1":"The helper must be old enough to drink legally.","h2":"A Kansas permit driver must be supervised by a licensed adult who is at least 21 years old.","p":"Right. The supervising adult must be 21 or older."},"es":{"q":"En Kansas, ¿qué edad debe tener el adulto con licencia que supervisa a un conductor con permiso?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 25","Por lo menos 21"],"h1":"El acompañante debe tener edad para tomar alcohol legalmente.","h2":"En Kansas, un conductor con permiso debe ir supervisado por un adulto con licencia de por lo menos 21 años.","p":"Correcto. El adulto que supervisa debe tener 21 años o más."},"zh":{"q":"在 Kansas，陪同持学习驾照的人开车、有驾照的成年人必须几岁？","o":["至少 16 岁","至少 18 岁","至少 25 岁","至少 21 岁"],"h1":"陪同的人必须到了可以合法喝酒的年龄。","h2":"在 Kansas，持学习驾照的人必须由一位至少 21 岁、有驾照的成年人陪同。","p":"对。陪同的成年人必须 21 岁或以上。"},"vi":{"q":"Ở Kansas, người lớn có bằng lái đi kèm người tập lái phải bao nhiêu tuổi?","o":["Ít nhất 16 tuổi","Ít nhất 18 tuổi","Ít nhất 25 tuổi","Ít nhất 21 tuổi"],"h1":"Người kèm phải đủ tuổi để uống rượu hợp pháp.","h2":"Ở Kansas, người tập lái phải có một người lớn có bằng lái, ít nhất 21 tuổi, đi kèm.","p":"Đúng. Người lớn đi kèm phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Kansas, ilang taon dapat ang may-lisensyang adult na nagbabantay sa nagmamaneho na may permit?","o":["Hindi bababa sa 16","Hindi bababa sa 18","Hindi bababa sa 25","Hindi bababa sa 21"],"h1":"Dapat sapat ang edad ng kasama para legal na uminom ng alak.","h2":"Sa Kansas, ang nagmamaneho na may permit ay dapat bantayan ng may-lisensyang adult na hindi bababa sa 21 taong gulang.","p":"Tama. Dapat 21 o higit pa ang adult na nagbabantay."},"ar":{"q":"في Kansas، كم يجب أن يكون عمر الشخص البالغ صاحب الرخصة الذي يرافق السائق المتعلّم؟","o":["16 سنة على الأقل","18 سنة على الأقل","25 سنة على الأقل","21 سنة على الأقل"],"h1":"يجب أن يكون المرافق في عمر يسمح له قانونيًا بشرب الكحول.","h2":"في Kansas يجب أن يرافق السائقَ المتعلّم شخصٌ بالغ يحمل رخصة وعمره 21 سنة على الأقل.","p":"صحيح. يجب أن يكون المرافق البالغ في عمر 21 سنة أو أكثر."},"ref":{"doc":"KS","page":12}},{"id":"ks-003","scope":"KS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kansas, who may sit in the front seat while a permit driver is at the wheel?","o":["Only the supervising driver","Any passenger over 12","Any licensed friend","Nobody, the front seat must be empty"],"h1":"The front seat is for the person who is teaching you.","h2":"In Kansas, no one except the supervising driver may sit in the front seat while a permit holder drives.","p":"Right. Only the supervising driver sits up front."},"es":{"q":"En Kansas, ¿quién puede ir en el asiento delantero mientras maneja un conductor con permiso?","o":["Solo el conductor que supervisa","Cualquier pasajero mayor de 12 años","Cualquier amigo con licencia","Nadie, el asiento delantero debe ir vacío"],"h1":"El asiento delantero es para la persona que le está enseñando.","h2":"En Kansas, nadie más que el conductor que supervisa puede ir en el asiento delantero mientras maneja quien tiene permiso.","p":"Correcto. Solo el supervisor va adelante."},"zh":{"q":"在 Kansas，持学习驾照的人开车时，谁可以坐在前排？","o":["只有陪同的司机","任何 12 岁以上的乘客","任何有驾照的朋友","没有人，前排必须空着"],"h1":"前排是给教你开车的人坐的。","h2":"在 Kansas，持学习驾照的人开车时，除了陪同的司机，任何人都不能坐在前排。","p":"对。只有陪同的司机坐在前排。"},"vi":{"q":"Ở Kansas, ai được ngồi ghế trước khi người có giấy phép tập lái đang lái xe?","o":["Chỉ người lái kèm","Bất kỳ hành khách nào trên 12 tuổi","Bất kỳ người bạn nào có bằng lái","Không ai cả, ghế trước phải để trống"],"h1":"Ghế trước dành cho người đang dạy bạn.","h2":"Ở Kansas, khi người có giấy phép tập lái đang lái, không ai được ngồi ghế trước ngoài người lái kèm.","p":"Đúng. Chỉ người lái kèm ngồi ghế trước."},"tl":{"q":"Sa Kansas, sino ang puwedeng umupo sa harapang upuan habang nagmamaneho ang may permit?","o":["Ang nagbabantay na driver lamang","Sinumang pasaherong higit 12 taong gulang","Sinumang kaibigang may lisensya","Wala, dapat walang tao sa harapang upuan"],"h1":"Ang harapang upuan ay para sa taong nagtuturo sa iyo.","h2":"Sa Kansas, walang ibang puwedeng umupo sa harapang upuan habang nagmamaneho ang may permit, maliban sa nagbabantay na driver.","p":"Tama. Ang nagbabantay na driver lamang ang nasa harap."},"ar":{"q":"في Kansas، من يمكنه الجلوس في المقعد الأمامي أثناء قيادة صاحب تصريح التعلّم؟","o":["السائق المرافق فقط","أي راكب عمره أكثر من 12 سنة","أي صديق يحمل رخصة","لا أحد، يجب أن يبقى المقعد الأمامي فارغًا"],"h1":"المقعد الأمامي للشخص الذي يعلّمك.","h2":"في Kansas لا يجوز لأحد غير السائق المرافق أن يجلس في المقعد الأمامي أثناء قيادة صاحب تصريح التعلّم.","p":"صحيح. السائق المرافق فقط يجلس في الأمام."},"ref":{"doc":"KS","page":12}},{"id":"ks-004","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kansas, how long must you hold an instruction permit before you can get a restricted license?","o":["10 days","6 months","One year","Two years"],"h1":"It is a full trip around the calendar.","h2":"In Kansas you must hold your instruction permit for at least one year before you can apply for a restricted license.","p":"Right. Kansas requires a full year on the permit."},"es":{"q":"En Kansas, ¿cuánto tiempo debe tener el permiso de instrucción antes de obtener una licencia restringida?","o":["10 días","6 meses","Un año","Dos años"],"h1":"Es una vuelta completa al calendario.","h2":"En Kansas usted debe tener el permiso de instrucción por lo menos un año antes de solicitar una licencia restringida.","p":"Correcto. Kansas exige un año completo con permiso."},"zh":{"q":"在 Kansas，你必须持有学习驾照多久，才能拿到限制驾照（restricted license）？","o":["10 天","6 个月","一年","两年"],"h1":"是日历上完整的一圈。","h2":"在 Kansas，你必须持有学习驾照至少一年，才能申请限制驾照。","p":"对。Kansas 要求持有学习驾照满一年。"},"vi":{"q":"Ở Kansas, bạn phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái hạn chế (restricted license)?","o":["10 ngày","6 tháng","Một năm","Hai năm"],"h1":"Đó là trọn một vòng lịch.","h2":"Ở Kansas, bạn phải giữ giấy phép tập lái ít nhất một năm trước khi xin bằng lái hạn chế.","p":"Đúng. Kansas yêu cầu giữ giấy phép tập lái trọn một năm."},"tl":{"q":"Sa Kansas, gaano katagal mo dapat hawak ang instruction permit bago ka makakuha ng restricted license?","o":["10 araw","6 na buwan","Isang taon","Dalawang taon"],"h1":"Isang buong ikot ito ng kalendaryo.","h2":"Sa Kansas, dapat hawak mo ang instruction permit nang hindi bababa sa isang taon bago ka makapag-apply ng restricted license.","p":"Tama. Isang buong taon sa permit ang hinihingi ng Kansas."},"ar":{"q":"في Kansas، كم مدة يجب أن تحمل تصريح التعلّم قبل أن تحصل على الرخصة المقيّدة (restricted license)؟","o":["10 أيام","6 أشهر","سنة واحدة","سنتان"],"h1":"إنها دورة كاملة من التقويم.","h2":"في Kansas يجب أن تحمل تصريح التعلّم سنة واحدة على الأقل قبل أن تتقدّم بطلب الرخصة المقيّدة.","p":"صحيح. تطلب Kansas سنة كاملة على التصريح."},"ref":{"doc":"KS","page":12}},{"id":"ks-005","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, how many hours of adult-supervised driving does a 15-year-old need before getting a restricted license?","o":["10 hours","25 hours","50 hours","100 hours"],"h1":"It is half of the full amount needed later.","h2":"A 15-year-old in Kansas needs at least 25 hours of adult-supervised driving before getting a restricted license.","p":"Right. At 15, the first step is 25 hours."},"es":{"q":"En Kansas, ¿cuántas horas de manejo supervisado por un adulto necesita una persona de 15 años antes de obtener la licencia restringida?","o":["10 horas","25 horas","50 horas","100 horas"],"h1":"Es la mitad del total que se pide después.","h2":"En Kansas, una persona de 15 años necesita por lo menos 25 horas de manejo supervisado por un adulto antes de obtener la licencia restringida.","p":"Correcto. A los 15, el primer paso son 25 horas."},"zh":{"q":"在 Kansas，15 岁的人拿限制驾照前，需要多少小时有成年人陪同的驾驶？","o":["10 小时","25 小时","50 小时","100 小时"],"h1":"是以后需要的全部时间的一半。","h2":"在 Kansas，15 岁的人拿限制驾照前，需要至少 25 小时有成年人陪同的驾驶。","p":"对。15 岁时，第一步是 25 小时。"},"vi":{"q":"Ở Kansas, người 15 tuổi cần bao nhiêu giờ lái xe có người lớn đi kèm trước khi lấy bằng lái hạn chế?","o":["10 giờ","25 giờ","50 giờ","100 giờ"],"h1":"Đó là một nửa số giờ cần sau này.","h2":"Ở Kansas, người 15 tuổi cần ít nhất 25 giờ lái xe có người lớn đi kèm trước khi lấy bằng lái hạn chế.","p":"Đúng. Ở tuổi 15, bước đầu là 25 giờ."},"tl":{"q":"Sa Kansas, ilang oras ng pagmamaneho na may bantay na adult ang kailangan ng 15 taong gulang bago makakuha ng restricted license?","o":["10 oras","25 oras","50 oras","100 oras"],"h1":"Kalahati ito ng buong bilang na kailangan sa susunod.","h2":"Sa Kansas, ang 15 taong gulang ay kailangan ng hindi bababa sa 25 oras ng pagmamaneho na may bantay na adult bago makakuha ng restricted license.","p":"Tama. Sa edad na 15, 25 oras ang unang hakbang."},"ar":{"q":"في Kansas، كم ساعة من القيادة بمرافقة شخص بالغ يحتاجها من عمره 15 سنة قبل الحصول على الرخصة المقيّدة؟","o":["10 ساعات","25 ساعة","50 ساعة","100 ساعة"],"h1":"إنها نصف العدد الكامل المطلوب لاحقًا.","h2":"في Kansas يحتاج من عمره 15 سنة إلى 25 ساعة على الأقل من القيادة بمرافقة شخص بالغ قبل الحصول على الرخصة المقيّدة.","p":"صحيح. في عمر 15، الخطوة الأولى هي 25 ساعة."},"ref":{"doc":"KS","page":12}},{"id":"ks-006","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kansas, how many supervised driving hours does a teen need in total, and how many at night?","o":["25 hours, 5 at night","40 hours, 8 at night","50 hours, 10 at night","60 hours, 20 at night"],"h1":"The night hours are one fifth of the total.","h2":"A Kansas teen needs 50 hours of adult-supervised driving in total, and at least 10 of those hours must be at night.","p":"Right. Fifty hours, with ten at night."},"es":{"q":"En Kansas, ¿cuántas horas de manejo supervisado necesita un adolescente en total, y cuántas de noche?","o":["25 horas, 5 de noche","40 horas, 8 de noche","50 horas, 10 de noche","60 horas, 20 de noche"],"h1":"Las horas de noche son una quinta parte del total.","h2":"En Kansas, un adolescente necesita 50 horas de manejo supervisado en total, y por lo menos 10 de ellas deben ser de noche.","p":"Correcto. Cincuenta horas, con diez de noche."},"zh":{"q":"在 Kansas，青少年总共需要多少小时有人陪同的驾驶，其中多少小时在夜间？","o":["25 小时，其中 5 小时在夜间","40 小时，其中 8 小时在夜间","50 小时，其中 10 小时在夜间","60 小时，其中 20 小时在夜间"],"h1":"夜间时间是总时间的五分之一。","h2":"Kansas 的青少年总共需要 50 小时有成年人陪同的驾驶，其中至少 10 小时必须在夜间。","p":"对。五十个小时，其中十个小时在夜间。"},"vi":{"q":"Ở Kansas, thanh thiếu niên cần tổng cộng bao nhiêu giờ lái xe có người kèm, và bao nhiêu giờ vào ban đêm?","o":["25 giờ, 5 giờ ban đêm","40 giờ, 8 giờ ban đêm","50 giờ, 10 giờ ban đêm","60 giờ, 20 giờ ban đêm"],"h1":"Số giờ ban đêm là một phần năm tổng số giờ.","h2":"Ở Kansas, thanh thiếu niên cần tổng cộng 50 giờ lái xe có người lớn đi kèm, trong đó ít nhất 10 giờ phải vào ban đêm.","p":"Đúng. Năm mươi giờ, mười giờ ban đêm."},"tl":{"q":"Sa Kansas, ilang oras ng pagmamaneho na may bantay ang kailangan ng kabataan sa kabuuan, at ilan dito sa gabi?","o":["25 oras, 5 sa gabi","40 oras, 8 sa gabi","50 oras, 10 sa gabi","60 oras, 20 sa gabi"],"h1":"Ang oras sa gabi ay ikalimang bahagi ng kabuuan.","h2":"Sa Kansas, kailangan ng kabataan ang 50 oras ng pagmamaneho na may bantay na adult sa kabuuan, at hindi bababa sa 10 oras dito ay dapat sa gabi.","p":"Tama. Limampung oras, sampu sa gabi."},"ar":{"q":"في Kansas، كم ساعة قيادة بمرافقة يحتاجها المراهق في المجموع، وكم منها في الليل؟","o":["25 ساعة، منها 5 في الليل","40 ساعة، منها 8 في الليل","50 ساعة، منها 10 في الليل","60 ساعة، منها 20 في الليل"],"h1":"ساعات الليل هي خُمس المجموع.","h2":"في Kansas يحتاج المراهق إلى 50 ساعة قيادة بمرافقة شخص بالغ في المجموع، ويجب أن تكون 10 ساعات منها على الأقل في الليل.","p":"صحيح. خمسون ساعة، منها عشر في الليل."},"ref":{"doc":"KS","page":12}},{"id":"ks-007","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kansas, do hours driven in a driver education course count toward the 50 supervised hours?","o":["Yes, all course time counts, even watching others drive","Only the night hours count","Only if a parent rides along","Yes, time behind the wheel counts if the instructor is 21 or older"],"h1":"Only real driving time with an adult of the right age counts.","h2":"In Kansas, time you spend behind the wheel in driver education counts toward the 50 hours when the instructor is at least 21, but time spent only watching does not count.","p":"Right. Behind-the-wheel time with an instructor 21 or older counts."},"es":{"q":"En Kansas, ¿cuentan las horas manejadas en un curso de educación vial para las 50 horas supervisadas?","o":["Sí, todo el tiempo del curso cuenta, incluso mirar a otros manejar","Solo cuentan las horas de noche","Solo si el padre va en el carro","Sí, el tiempo al volante cuenta si el instructor tiene 21 años o más"],"h1":"Solo cuenta el tiempo real manejando con un adulto de la edad correcta.","h2":"En Kansas, el tiempo que usted pasa al volante en educación vial cuenta para las 50 horas cuando el instructor tiene por lo menos 21 años, pero el tiempo que solo pasa mirando no cuenta.","p":"Correcto. El tiempo al volante con un instructor de 21 años o más sí cuenta."},"zh":{"q":"在 Kansas，驾驶课上开车的时间算在 50 小时有人陪同的驾驶里吗？","o":["算，所有上课时间都算，连看别人开车也算","只有夜间的时间算","只有父母一起坐车时才算","算，只要教练 21 岁或以上，实际开车的时间就算"],"h1":"只有和年龄合格的成年人一起真正开车的时间才算。","h2":"在 Kansas，如果教练至少 21 岁，你在驾驶课上实际开车的时间算在 50 小时里，但只是看别人开车的时间不算。","p":"对。和 21 岁或以上的教练一起实际开车的时间算。"},"vi":{"q":"Ở Kansas, giờ lái xe trong khóa học lái xe (driver education) có được tính vào 50 giờ có người kèm không?","o":["Có, mọi thời gian của khóa học đều được tính, kể cả khi xem người khác lái","Chỉ giờ ban đêm được tính","Chỉ khi có cha mẹ đi cùng","Có, thời gian bạn cầm lái được tính nếu người hướng dẫn từ 21 tuổi trở lên"],"h1":"Chỉ thời gian thật sự lái xe với người lớn đủ tuổi mới được tính.","h2":"Ở Kansas, thời gian bạn cầm lái trong khóa học lái xe được tính vào 50 giờ khi người hướng dẫn ít nhất 21 tuổi, nhưng thời gian chỉ ngồi xem thì không được tính.","p":"Đúng. Thời gian cầm lái với người hướng dẫn từ 21 tuổi trở lên được tính."},"tl":{"q":"Sa Kansas, binibilang ba ang mga oras ng pagmamaneho sa driver education course sa 50 oras na may bantay?","o":["Oo, binibilang ang lahat ng oras sa kurso, pati ang panonood sa ibang nagmamaneho","Ang mga oras sa gabi lang ang binibilang","Kung may kasamang magulang lang","Oo, binibilang ang oras na ikaw ang nagmamaneho kung 21 o higit pa ang instructor"],"h1":"Ang tunay na oras ng pagmamaneho kasama ang adult na tamang edad lang ang binibilang.","h2":"Sa Kansas, ang oras na ikaw ang nagmamaneho sa driver education ay binibilang sa 50 oras kung hindi bababa sa 21 ang instructor, pero hindi binibilang ang oras na nanonood ka lang.","p":"Tama. Binibilang ang oras sa manibela kasama ang instructor na 21 o higit pa."},"ar":{"q":"في Kansas، هل تُحسب ساعات القيادة في دورة تعليم القيادة (driver education) ضمن الخمسين ساعة بمرافقة؟","o":["نعم، يُحسب كل وقت الدورة، حتى مشاهدة الآخرين وهم يقودون","تُحسب ساعات الليل فقط","فقط إذا كان أحد الوالدين في السيارة","نعم، يُحسب وقت قيادتك أنت إذا كان عمر المدرّب 21 سنة أو أكثر"],"h1":"يُحسب فقط وقت القيادة الحقيقي مع شخص بالغ في العمر المناسب.","h2":"في Kansas يُحسب الوقت الذي تقود فيه أنت في دورة تعليم القيادة ضمن الخمسين ساعة إذا كان عمر المدرّب 21 سنة على الأقل، أما وقت المشاهدة فقط فلا يُحسب.","p":"صحيح. يُحسب وقت القيادة مع مدرّب عمره 21 سنة أو أكثر."},"ref":{"doc":"KS","page":null}},{"id":"ks-008","scope":"KS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kansas, what happens if a teen never turns in the 50-hour affidavit?","o":["The license restrictions continue until age 17","The license is canceled","The teen must retake the knowledge test","Nothing changes"],"h1":"The limits stay in place for a while longer.","h2":"If a Kansas teen does not turn in the 50-hour affidavit, the restrictions on the license stay in place until age 17.","p":"Right. Without the affidavit, the limits last until 17."},"es":{"q":"En Kansas, ¿qué pasa si un adolescente nunca entrega la declaración jurada de las 50 horas?","o":["Las restricciones de la licencia siguen hasta los 17 años","Le cancelan la licencia","Debe repetir el examen de conocimientos","No cambia nada"],"h1":"Los límites siguen por más tiempo.","h2":"Si un adolescente en Kansas no entrega la declaración jurada de las 50 horas, las restricciones de su licencia siguen hasta los 17 años.","p":"Correcto. Sin la declaración, los límites duran hasta los 17."},"zh":{"q":"在 Kansas，如果青少年一直没有交 50 小时的宣誓书（affidavit），会怎么样？","o":["驾照的限制一直持续到 17 岁","驾照被取消","青少年必须重考笔试","什么都不变"],"h1":"这些限制会再保留一段时间。","h2":"如果 Kansas 的青少年没有交 50 小时的宣誓书，驾照上的限制会一直保留到 17 岁。","p":"对。没有宣誓书，限制会持续到 17 岁。"},"vi":{"q":"Ở Kansas, điều gì xảy ra nếu thanh thiếu niên không bao giờ nộp bản khai 50 giờ (50-hour affidavit)?","o":["Các hạn chế của bằng lái tiếp tục đến 17 tuổi","Bằng lái bị hủy","Phải thi lại phần lý thuyết","Không có gì thay đổi"],"h1":"Các giới hạn sẽ còn giữ thêm một thời gian.","h2":"Ở Kansas, nếu thanh thiếu niên không nộp bản khai 50 giờ, các hạn chế trên bằng lái sẽ tiếp tục đến 17 tuổi.","p":"Đúng. Không có bản khai, các giới hạn kéo dài đến 17 tuổi."},"tl":{"q":"Sa Kansas, ano ang mangyayari kung hindi kailanman ipapasa ng kabataan ang 50-hour affidavit?","o":["Tuloy ang mga restriksyon ng lisensya hanggang edad 17","Kakanselahin ang lisensya","Dapat ulitin ng kabataan ang knowledge test","Walang magbabago"],"h1":"Mananatili pa ang mga limitasyon nang mas matagal.","h2":"Sa Kansas, kung hindi ipapasa ng kabataan ang 50-hour affidavit, mananatili ang mga restriksyon ng lisensya hanggang edad 17.","p":"Tama. Kung walang affidavit, tatagal ang mga limitasyon hanggang 17."},"ar":{"q":"في Kansas، ماذا يحدث إذا لم يسلّم المراهق إقرار الخمسين ساعة (50-hour affidavit) أبدًا؟","o":["تستمر قيود الرخصة حتى عمر 17 سنة","تُلغى الرخصة","يجب على المراهق إعادة الامتحان النظري","لا يتغيّر شيء"],"h1":"تبقى القيود مدة أطول.","h2":"في Kansas إذا لم يسلّم المراهق إقرار الخمسين ساعة، تبقى القيود على الرخصة حتى عمر 17 سنة.","p":"صحيح. بدون الإقرار تستمر القيود حتى عمر 17."},"ref":{"doc":"KS","page":null}},{"id":"ks-009","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, what must a 15-year-old complete, besides the permit year, to get a restricted license?","o":["A first aid course","An approved driver education course","A motorcycle course","Nothing else"],"h1":"It is a class about driving.","h2":"A 15-year-old in Kansas must complete an approved driver education course to get a restricted license.","p":"Right. Driver education is required at 15."},"es":{"q":"En Kansas, ¿qué debe completar una persona de 15 años, además del año con permiso, para obtener la licencia restringida?","o":["Un curso de primeros auxilios","Un curso aprobado de educación vial","Un curso de motocicleta","Nada más"],"h1":"Es una clase sobre manejo.","h2":"En Kansas, una persona de 15 años debe completar un curso aprobado de educación vial para obtener la licencia restringida.","p":"Correcto. A los 15 se exige educación vial."},"zh":{"q":"在 Kansas，15 岁的人除了持有学习驾照一年，还必须完成什么才能拿到限制驾照？","o":["急救课程","经过批准的驾驶课","摩托车课程","不需要别的"],"h1":"是一门关于开车的课。","h2":"在 Kansas，15 岁的人必须完成经过批准的驾驶课，才能拿到限制驾照。","p":"对。15 岁必须上驾驶课。"},"vi":{"q":"Ở Kansas, ngoài năm giữ giấy phép tập lái, người 15 tuổi phải hoàn thành gì để lấy bằng lái hạn chế?","o":["Một khóa sơ cứu","Một khóa học lái xe (driver education) được chấp thuận","Một khóa học xe máy","Không cần gì khác"],"h1":"Đó là một lớp học về lái xe.","h2":"Ở Kansas, người 15 tuổi phải hoàn thành một khóa học lái xe được chấp thuận để lấy bằng lái hạn chế.","p":"Đúng. Ở tuổi 15, phải học khóa lái xe."},"tl":{"q":"Sa Kansas, bukod sa isang taon sa permit, ano pa ang dapat tapusin ng 15 taong gulang para makakuha ng restricted license?","o":["Isang kurso sa first aid","Isang aprubadong driver education course","Isang kurso sa motorsiklo","Wala nang iba"],"h1":"Isa itong klase tungkol sa pagmamaneho.","h2":"Sa Kansas, dapat tapusin ng 15 taong gulang ang isang aprubadong driver education course para makakuha ng restricted license.","p":"Tama. Kailangan ang driver education sa edad na 15."},"ar":{"q":"في Kansas، ماذا يجب أن يُكمل من عمره 15 سنة، إلى جانب سنة التصريح، للحصول على الرخصة المقيّدة؟","o":["دورة إسعافات أولية","دورة معتمدة لتعليم القيادة (driver education)","دورة دراجة نارية","لا شيء آخر"],"h1":"إنها دروس عن القيادة.","h2":"في Kansas يجب على من عمره 15 سنة أن يُكمل دورة معتمدة لتعليم القيادة للحصول على الرخصة المقيّدة.","p":"صحيح. تعليم القيادة مطلوب في عمر 15."},"ref":{"doc":"KS","page":12}},{"id":"ks-010","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kansas, a 15-year-old with a restricted license may drive alone to school how?","o":["Any route, any day","Only on weekends","By the most direct route on school days","Only with a sibling"],"h1":"Think of the shortest way between home and school.","h2":"A 15-year-old in Kansas with a restricted license may drive alone to school on school days, using the most direct route between home and school.","p":"Right. The direct route, on school days."},"es":{"q":"En Kansas, ¿cómo puede manejar sola a la escuela una persona de 15 años con licencia restringida?","o":["Por cualquier ruta, cualquier día","Solo los fines de semana","Por la ruta más directa en días de clase","Solo con un hermano"],"h1":"Piense en el camino más corto entre la casa y la escuela.","h2":"En Kansas, una persona de 15 años con licencia restringida puede manejar sola a la escuela en días de clase, por la ruta más directa entre la casa y la escuela.","p":"Correcto. La ruta directa, en días de clase."},"zh":{"q":"在 Kansas，持限制驾照的 15 岁青少年可以怎样一个人开车去上学？","o":["任何路线，任何一天","只能在周末","在上学的日子走最直接的路线","只能和兄弟姐妹一起"],"h1":"想一想家和学校之间最短的路。","h2":"在 Kansas，持限制驾照的 15 岁青少年可以在上学的日子一个人开车去上学，走家和学校之间最直接的路线。","p":"对。上学的日子，走最直接的路线。"},"vi":{"q":"Ở Kansas, người 15 tuổi có bằng lái hạn chế được lái xe một mình đến trường như thế nào?","o":["Bất kỳ đường nào, bất kỳ ngày nào","Chỉ vào cuối tuần","Đi đường thẳng nhất vào những ngày đi học","Chỉ khi có anh chị em đi cùng"],"h1":"Hãy nghĩ đến đường ngắn nhất giữa nhà và trường.","h2":"Ở Kansas, người 15 tuổi có bằng lái hạn chế được lái xe một mình đến trường vào những ngày đi học, theo đường thẳng nhất giữa nhà và trường.","p":"Đúng. Đường thẳng nhất, vào ngày đi học."},"tl":{"q":"Sa Kansas, paano puwedeng magmaneho nang mag-isa papunta sa paaralan ang 15 taong gulang na may restricted license?","o":["Kahit anong ruta, kahit anong araw","Tuwing weekend lang","Sa pinakadiretsong ruta tuwing may pasok","Kung may kasamang kapatid lang"],"h1":"Isipin ang pinakamaikling daan mula bahay papuntang paaralan.","h2":"Sa Kansas, ang 15 taong gulang na may restricted license ay puwedeng magmaneho nang mag-isa papunta sa paaralan tuwing may pasok, sa pinakadiretsong ruta mula bahay papuntang paaralan.","p":"Tama. Ang diretsong ruta, tuwing may pasok."},"ar":{"q":"في Kansas، كيف يمكن لمن عمره 15 سنة ويحمل رخصة مقيّدة أن يقود وحده إلى المدرسة؟","o":["أي طريق، في أي يوم","في عطلة نهاية الأسبوع فقط","بأقصر طريق مباشر في أيام الدراسة","فقط مع أخ أو أخت"],"h1":"فكّر في أقصر طريق بين البيت والمدرسة.","h2":"في Kansas يمكن لمن عمره 15 سنة ويحمل رخصة مقيّدة أن يقود وحده إلى المدرسة في أيام الدراسة، بأقصر طريق مباشر بين البيت والمدرسة.","p":"صحيح. الطريق المباشر، في أيام الدراسة."},"ref":{"doc":"KS","page":13}},{"id":"ks-011","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kansas, may a restricted driver under 16 carry friends who are minors?","o":["Yes, up to three","Yes, one friend","Yes, if the windows are closed","No, only siblings may ride as minor passengers"],"h1":"Brothers and sisters are the exception.","h2":"In Kansas, a restricted driver under 16 may not carry minor passengers who are not brothers or sisters.","p":"Right. Under 16, only sibling minors may ride."},"es":{"q":"En Kansas, ¿puede un conductor con licencia restringida menor de 16 años llevar amigos menores de edad?","o":["Sí, hasta tres","Sí, un amigo","Sí, si las ventanas van cerradas","No, solo hermanos pueden ir como pasajeros menores"],"h1":"Los hermanos son la excepción.","h2":"En Kansas, un conductor con licencia restringida menor de 16 años no puede llevar pasajeros menores de edad que no sean sus hermanos.","p":"Correcto. Antes de los 16, solo hermanos menores."},"zh":{"q":"在 Kansas，16 岁以下、持限制驾照的司机可以载未成年的朋友吗？","o":["可以，最多三个","可以，一个朋友","可以，只要车窗关着","不可以，只有兄弟姐妹可以作为未成年乘客坐车"],"h1":"兄弟姐妹是例外。","h2":"在 Kansas，16 岁以下、持限制驾照的司机不能载不是兄弟姐妹的未成年乘客。","p":"对。16 岁以下，只有未成年的兄弟姐妹可以坐车。"},"vi":{"q":"Ở Kansas, người có bằng lái hạn chế dưới 16 tuổi có được chở bạn bè chưa thành niên không?","o":["Có, tối đa ba người","Có, một người bạn","Có, nếu đóng cửa sổ","Không, chỉ anh chị em ruột được đi cùng làm hành khách chưa thành niên"],"h1":"Anh chị em là ngoại lệ.","h2":"Ở Kansas, người có bằng lái hạn chế dưới 16 tuổi không được chở hành khách chưa thành niên nếu đó không phải là anh chị em.","p":"Đúng. Dưới 16 tuổi, chỉ anh chị em chưa thành niên được đi cùng."},"tl":{"q":"Sa Kansas, puwede bang magsakay ng mga kaibigang menor de edad ang restricted driver na wala pang 16?","o":["Oo, hanggang tatlo","Oo, isang kaibigan","Oo, kung nakasara ang mga bintana","Hindi, mga kapatid lang ang puwedeng isakay na menor de edad"],"h1":"Ang mga kapatid ang eksepsiyon.","h2":"Sa Kansas, ang restricted driver na wala pang 16 ay hindi puwedeng magsakay ng menor de edad na pasahero na hindi niya kapatid.","p":"Tama. Kung wala pang 16, mga kapatid na menor de edad lang ang puwedeng isakay."},"ar":{"q":"في Kansas، هل يجوز لسائق برخصة مقيّدة عمره أقل من 16 سنة أن يركب معه أصدقاء قاصرين؟","o":["نعم، حتى ثلاثة","نعم، صديق واحد","نعم، إذا كانت النوافذ مغلقة","لا، فقط الإخوة والأخوات يمكنهم الركوب كركاب قاصرين"],"h1":"الإخوة والأخوات هم الاستثناء.","h2":"في Kansas لا يجوز لسائق برخصة مقيّدة عمره أقل من 16 سنة أن يُركب معه ركابًا قاصرين ليسوا إخوته أو أخواته.","p":"صحيح. تحت 16 سنة، فقط الإخوة القاصرون يمكنهم الركوب."},"ref":{"doc":"KS","page":13}},{"id":"ks-012","scope":"KS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kansas, a 16-year-old with a restricted license may drive alone during which hours?","o":["5 a.m. to 9 p.m.","6 a.m. to 10 p.m.","Midnight to 5 a.m.","Any time at all"],"h1":"The window closes early in the evening.","h2":"A 16-year-old in Kansas with a restricted license may drive alone from 5 a.m. to 9 p.m., plus trips for work, school activities and religious services.","p":"Right. Five in the morning to nine at night."},"es":{"q":"En Kansas, ¿en qué horario puede manejar solo un joven de 16 años con licencia restringida?","o":["De 5 a.m. a 9 p.m.","De 6 a.m. a 10 p.m.","De medianoche a 5 a.m.","A cualquier hora"],"h1":"El horario termina temprano en la noche.","h2":"En Kansas, un joven de 16 años con licencia restringida puede manejar solo de 5 a.m. a 9 p.m., además de viajes de trabajo, actividades escolares y servicios religiosos.","p":"Correcto. De cinco de la mañana a nueve de la noche."},"zh":{"q":"在 Kansas，持限制驾照的 16 岁青少年可以在什么时间一个人开车？","o":["早上 5 点到晚上 9 点","早上 6 点到晚上 10 点","午夜到早上 5 点","任何时间都可以"],"h1":"这个时间段在晚上很早就结束了。","h2":"在 Kansas，持限制驾照的 16 岁青少年可以在早上 5 点到晚上 9 点一个人开车，另外也可以为上班、学校活动和宗教活动开车。","p":"对。早上五点到晚上九点。"},"vi":{"q":"Ở Kansas, người 16 tuổi có bằng lái hạn chế được lái xe một mình trong khoảng giờ nào?","o":["5 giờ sáng đến 9 giờ tối","6 giờ sáng đến 10 giờ tối","Nửa đêm đến 5 giờ sáng","Bất cứ lúc nào"],"h1":"Khung giờ kết thúc sớm vào buổi tối.","h2":"Ở Kansas, người 16 tuổi có bằng lái hạn chế được lái xe một mình từ 5 giờ sáng đến 9 giờ tối, cộng thêm các chuyến đi làm, đi sinh hoạt ở trường và đi lễ tôn giáo.","p":"Đúng. Từ năm giờ sáng đến chín giờ tối."},"tl":{"q":"Sa Kansas, anong oras puwedeng magmaneho nang mag-isa ang 16 taong gulang na may restricted license?","o":["5 a.m. hanggang 9 p.m.","6 a.m. hanggang 10 p.m.","Hatinggabi hanggang 5 a.m.","Kahit anong oras"],"h1":"Maaga sa gabi nagsasara ang oras.","h2":"Sa Kansas, ang 16 taong gulang na may restricted license ay puwedeng magmaneho nang mag-isa mula 5 a.m. hanggang 9 p.m., pati mga biyahe para sa trabaho, gawain sa paaralan at pagsamba.","p":"Tama. Mula alas-singko ng umaga hanggang alas-nuwebe ng gabi."},"ar":{"q":"في Kansas، في أي ساعات يمكن لمن عمره 16 سنة ويحمل رخصة مقيّدة أن يقود وحده؟","o":["من 5 صباحًا إلى 9 مساءً","من 6 صباحًا إلى 10 مساءً","من منتصف الليل إلى 5 صباحًا","في أي وقت"],"h1":"تنتهي الفترة مبكرًا في المساء.","h2":"في Kansas يمكن لمن عمره 16 سنة ويحمل رخصة مقيّدة أن يقود وحده من 5 صباحًا إلى 9 مساءً، بالإضافة إلى الرحلات إلى العمل وأنشطة المدرسة والشعائر الدينية.","p":"صحيح. من الخامسة صباحًا إلى التاسعة مساءً."},"ref":{"doc":"KS","page":13}},{"id":"ks-013","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, how many passengers under 18 who are not family may a newly restricted 16-year-old carry?","o":["None","One","Two","Three"],"h1":"It is the smallest number that is more than zero.","h2":"For the first six months, a 16-year-old in Kansas with a restricted license may carry no more than one passenger under 18 who is not an immediate family member.","p":"Right. Only one non-family passenger under 18."},"es":{"q":"En Kansas, ¿cuántos pasajeros menores de 18 años que no son familia puede llevar un joven de 16 años con licencia restringida reciente?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Es el número más pequeño mayor que cero.","h2":"Durante los primeros seis meses, un joven de 16 años en Kansas con licencia restringida puede llevar como máximo un pasajero menor de 18 años que no sea familiar directo.","p":"Correcto. Solo un pasajero menor de 18 que no sea familia."},"zh":{"q":"在 Kansas，刚拿到限制驾照的 16 岁青少年可以载几个不是家人、18 岁以下的乘客？","o":["一个都不可以","一个","两个","三个"],"h1":"是比零大的最小的数。","h2":"在头六个月里，Kansas 持限制驾照的 16 岁青少年最多只能载一个不是直系亲属、18 岁以下的乘客。","p":"对。只能载一个不是家人、18 岁以下的乘客。"},"vi":{"q":"Ở Kansas, người 16 tuổi mới có bằng lái hạn chế được chở bao nhiêu hành khách dưới 18 tuổi không phải người trong gia đình?","o":["Không ai","Một","Hai","Ba"],"h1":"Đó là số nhỏ nhất lớn hơn không.","h2":"Ở Kansas, trong sáu tháng đầu, người 16 tuổi có bằng lái hạn chế được chở không quá một hành khách dưới 18 tuổi không phải người trong gia đình gần.","p":"Đúng. Chỉ một hành khách dưới 18 tuổi không phải người nhà."},"tl":{"q":"Sa Kansas, ilang pasaherong wala pang 18 na hindi kapamilya ang puwedeng isakay ng bagong restricted na 16 taong gulang?","o":["Wala","Isa","Dalawa","Tatlo"],"h1":"Ito ang pinakamaliit na bilang na higit sa zero.","h2":"Sa Kansas, sa unang anim na buwan, ang 16 taong gulang na may restricted license ay puwedeng magsakay ng hindi hihigit sa isang pasaherong wala pang 18 na hindi malapit na kapamilya.","p":"Tama. Isa lang na pasaherong wala pang 18 na hindi kapamilya."},"ar":{"q":"في Kansas، كم راكبًا عمره أقل من 18 سنة وليس من العائلة يمكن أن يُركب معه سائق عمره 16 سنة حصل حديثًا على رخصة مقيّدة؟","o":["لا أحد","واحد","اثنان","ثلاثة"],"h1":"إنه أصغر عدد أكبر من الصفر.","h2":"في Kansas، خلال الأشهر الستة الأولى، لا يجوز لمن عمره 16 سنة ويحمل رخصة مقيّدة أن يُركب معه أكثر من راكب واحد عمره أقل من 18 سنة وليس من أفراد العائلة المباشرة.","p":"صحيح. راكب واحد فقط تحت 18 سنة من خارج العائلة."},"ref":{"doc":"KS","page":12}},{"id":"ks-014","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kansas, when may a 15-year-old restricted driver drive at any time of day?","o":["On holidays","When another teen with a permit rides along","When a licensed adult sits in the front seat beside them","Never"],"h1":"An experienced adult must be right beside you.","h2":"A 15-year-old in Kansas with a restricted license may drive at any time when a licensed adult sits in the front seat beside them.","p":"Right. Any time, with a licensed adult beside you."},"es":{"q":"En Kansas, ¿cuándo puede manejar a cualquier hora una persona de 15 años con licencia restringida?","o":["En días festivos","Cuando va con otro joven que tiene permiso","Cuando un adulto con licencia va a su lado en el asiento delantero","Nunca"],"h1":"Un adulto con experiencia debe ir a su lado.","h2":"En Kansas, una persona de 15 años con licencia restringida puede manejar a cualquier hora si un adulto con licencia va a su lado en el asiento delantero.","p":"Correcto. A cualquier hora, con un adulto con licencia a su lado."},"zh":{"q":"在 Kansas，持限制驾照的 15 岁司机什么时候可以在一天中任何时间开车？","o":["在节假日","当另一个持学习驾照的青少年一起坐车时","当一位有驾照的成年人坐在旁边的前排座位时","任何时候都不可以"],"h1":"必须有一位有经验的成年人就在你旁边。","h2":"在 Kansas，持限制驾照的 15 岁青少年，在一位有驾照的成年人坐在旁边的前排座位时，可以在任何时间开车。","p":"对。有一位有驾照的成年人在你旁边时，任何时间都可以。"},"vi":{"q":"Ở Kansas, khi nào người 15 tuổi có bằng lái hạn chế được lái xe vào bất kỳ giờ nào trong ngày?","o":["Vào ngày lễ","Khi có một thanh thiếu niên khác có giấy phép tập lái đi cùng","Khi có một người lớn có bằng lái ngồi ghế trước bên cạnh","Không bao giờ"],"h1":"Một người lớn có kinh nghiệm phải ngồi ngay bên cạnh bạn.","h2":"Ở Kansas, người 15 tuổi có bằng lái hạn chế được lái xe bất cứ lúc nào khi có một người lớn có bằng lái ngồi ghế trước bên cạnh.","p":"Đúng. Bất cứ lúc nào, nếu có người lớn có bằng lái ngồi bên cạnh."},"tl":{"q":"Sa Kansas, kailan puwedeng magmaneho kahit anong oras ang 15 taong gulang na restricted driver?","o":["Tuwing holiday","Kung may kasamang ibang kabataan na may permit","Kung may may-lisensyang adult na nakaupo sa harapang upuan sa tabi niya","Hindi kailanman"],"h1":"Dapat may adult na may karanasan sa mismong tabi mo.","h2":"Sa Kansas, ang 15 taong gulang na may restricted license ay puwedeng magmaneho kahit anong oras kung may may-lisensyang adult na nakaupo sa harapang upuan sa tabi niya.","p":"Tama. Kahit anong oras, basta may may-lisensyang adult sa tabi mo."},"ar":{"q":"في Kansas، متى يمكن لسائق عمره 15 سنة ويحمل رخصة مقيّدة أن يقود في أي وقت من اليوم؟","o":["في أيام العطل","عندما يركب معه مراهق آخر يحمل تصريح تعلّم","عندما يجلس بجانبه في المقعد الأمامي شخص بالغ يحمل رخصة","أبدًا"],"h1":"يجب أن يكون شخص بالغ صاحب خبرة بجانبك مباشرة.","h2":"في Kansas يمكن لمن عمره 15 سنة ويحمل رخصة مقيّدة أن يقود في أي وقت عندما يجلس بجانبه في المقعد الأمامي شخص بالغ يحمل رخصة.","p":"صحيح. في أي وقت، مع شخص بالغ يحمل رخصة بجانبك."},"ref":{"doc":"KS","page":13}},{"id":"ks-015","scope":"KS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Kansas, when may a teen with a permit or restricted license use a phone while driving?","o":["At red lights","For short texts","With a hands-free device","Only to report illegal activity or call for emergency help"],"h1":"Only a true emergency or a crime is an exception.","h2":"A Kansas teen with a permit or restricted license may not use a wireless device while driving, except to report illegal activity or call for medical or emergency help.","p":"Right. Only for emergencies or to report a crime."},"es":{"q":"En Kansas, ¿cuándo puede usar el teléfono mientras maneja un adolescente con permiso o licencia restringida?","o":["En los semáforos en rojo","Para mensajes cortos","Con un dispositivo manos libres","Solo para reportar un delito o pedir ayuda de emergencia"],"h1":"Solo una emergencia real o un delito son la excepción.","h2":"En Kansas, un adolescente con permiso o licencia restringida no puede usar un dispositivo inalámbrico mientras maneja, salvo para reportar un delito o pedir ayuda médica o de emergencia.","p":"Correcto. Solo para emergencias o para reportar un delito."},"zh":{"q":"在 Kansas，持学习驾照或限制驾照的青少年开车时什么时候可以用手机？","o":["在红灯时","发短的短信","用免提设备","只能报告违法活动或打电话求救"],"h1":"只有真正的紧急情况或犯罪才是例外。","h2":"在 Kansas，持学习驾照或限制驾照的青少年开车时不能使用无线设备，除非是报告违法活动，或打电话寻求医疗或紧急帮助。","p":"对。只能在紧急情况下或报告犯罪时用。"},"vi":{"q":"Ở Kansas, khi nào thanh thiếu niên có giấy phép tập lái hoặc bằng lái hạn chế được dùng điện thoại khi lái xe?","o":["Khi dừng đèn đỏ","Để nhắn tin ngắn","Khi dùng thiết bị rảnh tay","Chỉ để báo hành vi phạm pháp hoặc gọi cấp cứu"],"h1":"Chỉ trường hợp khẩn cấp thật sự hoặc tội phạm mới là ngoại lệ.","h2":"Ở Kansas, thanh thiếu niên có giấy phép tập lái hoặc bằng lái hạn chế không được dùng thiết bị không dây khi lái xe, trừ khi để báo hành vi phạm pháp hoặc gọi trợ giúp y tế hay cấp cứu.","p":"Đúng. Chỉ khi khẩn cấp hoặc để báo tội phạm."},"tl":{"q":"Sa Kansas, kailan puwedeng gumamit ng telepono habang nagmamaneho ang kabataan na may permit o restricted license?","o":["Sa red light","Para sa maiikling text","Gamit ang hands-free na device","Para lang mag-report ng ilegal na gawain o tumawag para sa emergency"],"h1":"Tunay na emergency o krimen lang ang eksepsiyon.","h2":"Sa Kansas, ang kabataan na may permit o restricted license ay hindi puwedeng gumamit ng wireless device habang nagmamaneho, maliban kung magre-report ng ilegal na gawain o tatawag para sa medikal o emergency na tulong.","p":"Tama. Para lang sa emergency o pag-report ng krimen."},"ar":{"q":"في Kansas، متى يمكن لمراهق يحمل تصريح تعلّم أو رخصة مقيّدة أن يستخدم الهاتف أثناء القيادة؟","o":["عند الإشارة الحمراء","لرسائل قصيرة","مع جهاز بدون استخدام اليدين (hands-free)","فقط للإبلاغ عن نشاط غير قانوني أو لطلب مساعدة طارئة"],"h1":"الاستثناء فقط لحالة طارئة حقيقية أو جريمة.","h2":"في Kansas لا يجوز لمراهق يحمل تصريح تعلّم أو رخصة مقيّدة أن يستخدم جهازًا لاسلكيًا أثناء القيادة، إلا للإبلاغ عن نشاط غير قانوني أو لطلب مساعدة طبية أو طارئة.","p":"صحيح. فقط في حالات الطوارئ أو للإبلاغ عن جريمة."},"ref":{"doc":"KS","page":12}},{"id":"ks-016","scope":"KS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kansas, a driver under 21 breaks the law at what blood alcohol level?","o":[".02 or higher",".05 or higher",".08 or higher",".10 or higher"],"h1":"It is a very small amount, far below the adult limit.","h2":"In Kansas it is illegal for a driver under 21 to drive with a blood or breath alcohol level of .02 or higher.","p":"Right. Under 21, the limit is .02."},"es":{"q":"En Kansas, ¿con qué nivel de alcohol en la sangre comete una infracción un conductor menor de 21 años?","o":[".02 o más",".05 o más",".08 o más",".10 o más"],"h1":"Es una cantidad muy pequeña, muy por debajo del límite para adultos.","h2":"En Kansas es ilegal que un conductor menor de 21 años maneje con un nivel de alcohol en la sangre o el aliento de .02 o más.","p":"Correcto. Para menores de 21, el límite es .02."},"zh":{"q":"在 Kansas，21 岁以下的司机血液酒精浓度达到多少就违法？","o":[".02 或更高",".05 或更高",".08 或更高",".10 或更高"],"h1":"这是很少的量，远低于成年人的上限。","h2":"在 Kansas，21 岁以下的司机血液或呼气酒精浓度达到 .02 或更高时开车是违法的。","p":"对。21 岁以下，上限是 .02。"},"vi":{"q":"Ở Kansas, người lái xe dưới 21 tuổi phạm luật khi nồng độ cồn trong máu ở mức nào?","o":[".02 trở lên",".05 trở lên",".08 trở lên",".10 trở lên"],"h1":"Đó là một lượng rất nhỏ, thấp hơn nhiều so với giới hạn của người lớn.","h2":"Ở Kansas, người dưới 21 tuổi lái xe với nồng độ cồn trong máu hoặc hơi thở từ .02 trở lên là phạm luật.","p":"Đúng. Dưới 21 tuổi, giới hạn là .02."},"tl":{"q":"Sa Kansas, sa anong blood alcohol level lumalabag sa batas ang driver na wala pang 21?","o":[".02 o higit pa",".05 o higit pa",".08 o higit pa",".10 o higit pa"],"h1":"Napakaliit na dami ito, mas mababa kaysa sa limitasyon ng adult.","h2":"Sa Kansas, bawal sa driver na wala pang 21 ang magmaneho na may alcohol level sa dugo o hininga na .02 o higit pa.","p":"Tama. Kung wala pang 21, ang limitasyon ay .02."},"ar":{"q":"في Kansas، عند أي نسبة كحول في الدم يخالف السائق الذي عمره أقل من 21 سنة القانون؟","o":[".02 أو أكثر",".05 أو أكثر",".08 أو أكثر",".10 أو أكثر"],"h1":"إنها كمية صغيرة جدًا، أقل بكثير من حدّ البالغين.","h2":"في Kansas يُمنع على السائق الذي عمره أقل من 21 سنة أن يقود ونسبة الكحول في دمه أو نَفَسه .02 أو أكثر.","p":"صحيح. تحت 21 سنة، الحدّ هو .02."},"ref":{"doc":"KS","page":23}},{"id":"ks-017","scope":"KS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Kansas, how long is the license suspension for a first time a driver under 21 tests between .02 and .08?","o":["7 days","14 days","30 days","One year"],"h1":"It is about one month.","h2":"In Kansas, a first offense by a driver under 21 with a result from .02 up to .08 brings a 30-day suspension.","p":"Right. The first suspension lasts 30 days."},"es":{"q":"En Kansas, ¿cuánto dura la suspensión la primera vez que un conductor menor de 21 años da entre .02 y .08?","o":["7 días","14 días","30 días","Un año"],"h1":"Es más o menos un mes.","h2":"En Kansas, la primera vez que un conductor menor de 21 años da entre .02 y .08, se le suspende la licencia por 30 días.","p":"Correcto. La primera suspensión dura 30 días."},"zh":{"q":"在 Kansas，21 岁以下的司机第一次被测出酒精浓度在 .02 到 .08 之间，驾照会被暂停多久？","o":["7 天","14 天","30 天","一年"],"h1":"大约是一个月。","h2":"在 Kansas，21 岁以下的司机第一次被测出酒精浓度在 .02 到 .08 以下，驾照会被暂停 30 天。","p":"对。第一次暂停 30 天。"},"vi":{"q":"Ở Kansas, lần đầu người lái xe dưới 21 tuổi có kết quả từ .02 đến .08 thì bị treo bằng lái bao lâu?","o":["7 ngày","14 ngày","30 ngày","Một năm"],"h1":"Khoảng một tháng.","h2":"Ở Kansas, lần vi phạm đầu tiên của người lái dưới 21 tuổi với kết quả từ .02 đến dưới .08 sẽ bị treo bằng lái 30 ngày.","p":"Đúng. Lần treo bằng đầu tiên kéo dài 30 ngày."},"tl":{"q":"Sa Kansas, gaano katagal ang suspensyon ng lisensya sa unang beses na ang driver na wala pang 21 ay may resultang mula .02 hanggang .08?","o":["7 araw","14 na araw","30 araw","Isang taon"],"h1":"Mga isang buwan ito.","h2":"Sa Kansas, ang unang paglabag ng driver na wala pang 21 na may resultang mula .02 hanggang .08 ay may 30 araw na suspensyon.","p":"Tama. 30 araw ang unang suspensyon."},"ar":{"q":"في Kansas، كم مدة إيقاف الرخصة في المرة الأولى التي تكون فيها نتيجة سائق عمره أقل من 21 سنة بين .02 و .08؟","o":["7 أيام","14 يومًا","30 يومًا","سنة واحدة"],"h1":"إنها حوالي شهر واحد.","h2":"في Kansas، المخالفة الأولى لسائق عمره أقل من 21 سنة بنتيجة من .02 إلى أقل من .08 تؤدي إلى إيقاف الرخصة 30 يومًا.","p":"صحيح. الإيقاف الأول مدته 30 يومًا."},"ref":{"doc":"KS","page":null}},{"id":"ks-018","scope":"KS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Kansas, what is the speed limit on a county or township road when no other limit is posted?","o":["45 mph","55 mph","65 mph","75 mph"],"h1":"It is ten less than the limit on other open highways.","h2":"In Kansas the speed limit on a county or township road is 55 mph unless a different limit is posted.","p":"Right. County and township roads are 55 mph."},"es":{"q":"En Kansas, ¿cuál es el límite de velocidad en un camino de condado o municipio cuando no hay otro límite indicado?","o":["45 mph","55 mph","65 mph","75 mph"],"h1":"Es diez menos que el límite de otras carreteras abiertas.","h2":"En Kansas el límite de velocidad en un camino de condado o municipio es de 55 mph, a menos que haya otro límite indicado.","p":"Correcto. Los caminos de condado y municipio son de 55 mph."},"zh":{"q":"在 Kansas，如果没有标示其他限速，县道或乡镇道路的限速是多少？","o":["45 mph","55 mph","65 mph","75 mph"],"h1":"比其他开阔公路的限速少十。","h2":"在 Kansas，县道或乡镇道路的限速是 55 mph，除非标示了不同的限速。","p":"对。县道和乡镇道路是 55 mph。"},"vi":{"q":"Ở Kansas, tốc độ tối đa trên đường quận hoặc đường thị trấn (county or township road) là bao nhiêu khi không có biển báo khác?","o":["45 mph","55 mph","65 mph","75 mph"],"h1":"Nó thấp hơn mười so với giới hạn trên các xa lộ thông thoáng khác.","h2":"Ở Kansas, tốc độ tối đa trên đường quận hoặc đường thị trấn là 55 mph, trừ khi có biển báo giới hạn khác.","p":"Đúng. Đường quận và đường thị trấn là 55 mph."},"tl":{"q":"Sa Kansas, ano ang speed limit sa county o township road kapag walang ibang nakapaskil na limitasyon?","o":["45 mph","55 mph","65 mph","75 mph"],"h1":"Sampu ang baba nito kaysa sa limitasyon sa ibang bukas na highway.","h2":"Sa Kansas, ang speed limit sa county o township road ay 55 mph maliban kung may ibang nakapaskil na limitasyon.","p":"Tama. 55 mph sa county at township road."},"ar":{"q":"في Kansas، ما حدّ السرعة على طريق المقاطعة أو البلدة (county or township road) إذا لم توجد لافتة بحدّ آخر؟","o":["45 mph","55 mph","65 mph","75 mph"],"h1":"إنه أقل بعشرة من الحدّ على الطرق السريعة المفتوحة الأخرى.","h2":"في Kansas حدّ السرعة على طريق المقاطعة أو البلدة هو 55 mph، إلا إذا كانت هناك لافتة بحدّ مختلف.","p":"صحيح. طرق المقاطعة والبلدة 55 mph."},"ref":{"doc":"KS","page":62}},{"id":"ks-019","scope":"KS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Kansas, where is 75 mph the speed limit?","o":["On every highway","On all county roads","In school zones at night","On divided multilane highways where it is posted"],"h1":"The highest limit only applies where a sign says so.","h2":"In Kansas, 75 mph is the limit only on divided multilane highways that the state has marked with that limit.","p":"Right. 75 mph only where it is posted."},"es":{"q":"En Kansas, ¿dónde es 75 mph el límite de velocidad?","o":["En todas las carreteras","En todos los caminos de condado","En zonas escolares de noche","En carreteras divididas de varios carriles donde esté indicado"],"h1":"El límite más alto solo aplica donde un letrero lo indica.","h2":"En Kansas, 75 mph es el límite solo en carreteras divididas de varios carriles donde el estado lo ha señalado.","p":"Correcto. 75 mph solo donde esté indicado."},"zh":{"q":"在 Kansas，在哪里限速是 75 mph？","o":["在每一条公路上","在所有县道上","晚上在学校区域","在标示了这个限速的多车道分隔公路上"],"h1":"最高的限速只在有标志说明的地方适用。","h2":"在 Kansas，75 mph 的限速只适用于州政府标示了这个限速的多车道分隔公路。","p":"对。只有标示的地方才是 75 mph。"},"vi":{"q":"Ở Kansas, tốc độ tối đa 75 mph áp dụng ở đâu?","o":["Trên mọi xa lộ","Trên mọi đường quận","Trong khu trường học vào ban đêm","Trên xa lộ nhiều làn có dải phân cách, nơi có biển báo"],"h1":"Giới hạn cao nhất chỉ áp dụng nơi có biển báo.","h2":"Ở Kansas, 75 mph chỉ là giới hạn trên các xa lộ nhiều làn có dải phân cách mà tiểu bang đã gắn biển báo giới hạn đó.","p":"Đúng. 75 mph chỉ nơi có biển báo."},"tl":{"q":"Sa Kansas, saan 75 mph ang speed limit?","o":["Sa bawat highway","Sa lahat ng county road","Sa school zone sa gabi","Sa divided multilane highway kung saan ito nakapaskil"],"h1":"Ang pinakamataas na limitasyon ay para lang kung saan may karatula.","h2":"Sa Kansas, 75 mph ang limitasyon lang sa mga divided multilane highway na nilagyan ng estado ng karatulang may ganitong limitasyon.","p":"Tama. 75 mph kung saan lang ito nakapaskil."},"ar":{"q":"في Kansas، أين يكون حدّ السرعة 75 mph؟","o":["على كل طريق سريع","على كل طرق المقاطعة","في مناطق المدارس ليلًا","على الطرق السريعة متعددة المسارات المقسومة بفاصل، حيث توجد لافتة بذلك"],"h1":"أعلى حدّ ينطبق فقط حيث تقول اللافتة ذلك.","h2":"في Kansas يكون حدّ 75 mph فقط على الطرق السريعة متعددة المسارات المقسومة بفاصل التي وضعت عليها الولاية لافتة بهذا الحدّ.","p":"صحيح. 75 mph فقط حيث توجد لافتة."},"ref":{"doc":"KS","page":62}},{"id":"ks-020","scope":"KS","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Kansas, which stopped buses with their stop signals on require you to stop?","o":["School buses only","City transit buses","School buses, church buses and day care buses","Tour buses"],"h1":"It is more than just the yellow school bus.","h2":"In Kansas you must stop for a school bus, church bus or day care bus that is stopped to load or unload children.","p":"Right. School, church and day care buses."},"es":{"q":"En Kansas, ¿por cuáles autobuses detenidos con sus señales de parada encendidas debe usted detenerse?","o":["Solo autobuses escolares","Autobuses urbanos","Autobuses escolares, de iglesia y de guardería","Autobuses de turismo"],"h1":"Es más que solo el autobús escolar amarillo.","h2":"En Kansas usted debe detenerse ante un autobús escolar, de iglesia o de guardería que está detenido para subir o bajar niños.","p":"Correcto. Escolares, de iglesia y de guardería."},"zh":{"q":"在 Kansas，哪些停着并亮出停车信号的公交车要求你停车？","o":["只有校车","城市公交车","校车、教会巴士和托儿所巴士","旅游巴士"],"h1":"不只是黄色的校车。","h2":"在 Kansas，校车、教会巴士或托儿所巴士停下来让小孩上下车时，你必须停车。","p":"对。校车、教会巴士和托儿所巴士。"},"vi":{"q":"Ở Kansas, bạn phải dừng lại khi xe buýt nào đang dừng và bật đèn báo dừng?","o":["Chỉ xe buýt trường học","Xe buýt công cộng của thành phố","Xe buýt trường học, xe buýt nhà thờ và xe buýt nhà trẻ","Xe buýt du lịch"],"h1":"Không chỉ có xe buýt trường học màu vàng.","h2":"Ở Kansas, bạn phải dừng lại khi xe buýt trường học, xe buýt nhà thờ hoặc xe buýt nhà trẻ đang dừng để đón hoặc trả trẻ em.","p":"Đúng. Xe buýt trường học, nhà thờ và nhà trẻ."},"tl":{"q":"Sa Kansas, aling mga nakahintong bus na nakabukas ang stop signal ang kailangan mong hintuan?","o":["School bus lang","Mga city transit bus","School bus, church bus at day care bus","Mga tour bus"],"h1":"Hindi lang ang dilaw na school bus.","h2":"Sa Kansas, dapat kang huminto para sa school bus, church bus o day care bus na nakahinto para magsakay o magbaba ng mga bata.","p":"Tama. School, church at day care bus."},"ar":{"q":"في Kansas، أي حافلات متوقفة وإشارات التوقف فيها مضاءة يجب أن تتوقف لها؟","o":["الحافلات المدرسية فقط","حافلات النقل العام في المدينة","الحافلات المدرسية وحافلات الكنائس وحافلات دور الحضانة","الحافلات السياحية"],"h1":"الأمر لا يقتصر على الحافلة المدرسية الصفراء.","h2":"في Kansas يجب أن تتوقف للحافلة المدرسية أو حافلة الكنيسة أو حافلة دار الحضانة عندما تكون متوقفة لإركاب الأطفال أو إنزالهم.","p":"صحيح. حافلات المدارس والكنائس ودور الحضانة."},"ref":{"doc":"KS","page":18}},{"id":"ks-021","scope":"KS","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Kansas, a school bus is stopped on the other side of a divided highway. What must you do?","o":["You do not have to stop, but drive with care","Stop and wait until it moves","Honk and pass quickly","Stop only if children are visible"],"h1":"The divided road separates you from the bus.","h2":"In Kansas, if a school bus is stopped on the opposite roadway of a divided highway, you are not required to stop, though you should watch for children.","p":"Right. On a divided highway, oncoming traffic need not stop."},"es":{"q":"En Kansas, un autobús escolar está detenido al otro lado de una carretera dividida. ¿Qué debe hacer usted?","o":["No tiene que detenerse, pero maneje con cuidado","Detenerse y esperar hasta que avance","Tocar la bocina y pasar rápido","Detenerse solo si ve niños"],"h1":"La carretera dividida lo separa del autobús.","h2":"En Kansas, si un autobús escolar está detenido en el lado opuesto de una carretera dividida, usted no tiene que detenerse, aunque debe estar atento a los niños.","p":"Correcto. En carretera dividida, el tráfico contrario no se detiene."},"zh":{"q":"在 Kansas，一辆校车停在分隔公路的另一边。你必须做什么？","o":["你不用停车，但要小心驾驶","停车，等到它开走","按喇叭，快点开过去","只有看到小孩时才停车"],"h1":"分隔的道路把你和校车分开了。","h2":"在 Kansas，如果校车停在分隔公路对面的车道上，你不用停车，但应该注意小孩。","p":"对。在分隔公路上，对面来的车不用停车。"},"vi":{"q":"Ở Kansas, một xe buýt trường học đang dừng ở phía bên kia của xa lộ có dải phân cách. Bạn phải làm gì?","o":["Bạn không phải dừng, nhưng hãy lái cẩn thận","Dừng lại và chờ đến khi xe buýt chạy","Bấm còi và vượt nhanh","Chỉ dừng nếu thấy trẻ em"],"h1":"Dải phân cách ngăn bạn với xe buýt.","h2":"Ở Kansas, nếu xe buýt trường học dừng ở phía đường ngược chiều của xa lộ có dải phân cách, bạn không bắt buộc phải dừng, nhưng nên để ý trẻ em.","p":"Đúng. Trên xa lộ có dải phân cách, xe chạy ngược chiều không cần dừng."},"tl":{"q":"Sa Kansas, may school bus na nakahinto sa kabilang panig ng divided highway. Ano ang dapat mong gawin?","o":["Hindi mo kailangang huminto, pero magmaneho nang maingat","Huminto at maghintay hanggang umandar ito","Bumusina at lumampas nang mabilis","Huminto lang kung may nakikitang mga bata"],"h1":"Ang divider ng daan ang naghihiwalay sa iyo at sa bus.","h2":"Sa Kansas, kung nakahinto ang school bus sa kabilang daan ng divided highway, hindi mo kailangang huminto, pero bantayan mo ang mga bata.","p":"Tama. Sa divided highway, hindi kailangang huminto ang mga sasakyang kasalubong."},"ar":{"q":"في Kansas، حافلة مدرسية متوقفة على الجهة الأخرى من طريق سريع مقسوم بفاصل. ماذا يجب أن تفعل؟","o":["ليس عليك أن تتوقف، لكن قُد بحذر","توقف وانتظر حتى تتحرك","استخدم البوق وتجاوز بسرعة","توقف فقط إذا رأيت أطفالًا"],"h1":"الفاصل في الطريق يفصلك عن الحافلة.","h2":"في Kansas، إذا توقفت حافلة مدرسية على الجهة المقابلة من طريق سريع مقسوم بفاصل، فليس عليك أن تتوقف، لكن انتبه للأطفال.","p":"صحيح. على الطريق المقسوم بفاصل، ليس على السيارات القادمة من الاتجاه المعاكس أن تتوقف."},"ref":{"doc":"KS","page":18}},{"id":"ks-022","scope":"KS","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Kansas, since July 2025, the move-over law covers which stopped vehicles?","o":["Only police cars","Any stopped vehicle with hazard lights on","Only tow trucks","Only school buses"],"h1":"The 2025 change widened the law to every kind of vehicle.","h2":"Since July 1, 2025, the Kansas move-over law covers any stopped vehicle showing hazard warning lights, so you must change lanes or slow down.","p":"Right. Any stopped vehicle with hazard lights."},"es":{"q":"En Kansas, desde julio de 2025, ¿a qué vehículos detenidos aplica la ley de cambiarse de carril?","o":["Solo a patrullas","A cualquier vehículo detenido con luces intermitentes","Solo a grúas","Solo a autobuses escolares"],"h1":"El cambio de 2025 amplió la ley a todo tipo de vehículo.","h2":"Desde el 1 de julio de 2025, la ley de Kansas aplica a cualquier vehículo detenido con luces intermitentes de emergencia, y usted debe cambiarse de carril o bajar la velocidad.","p":"Correcto. Cualquier vehículo detenido con intermitentes."},"zh":{"q":"在 Kansas，从 2025 年 7 月起，move-over 法保护哪些停着的车辆？","o":["只有警车","任何开着双闪灯、停着的车辆","只有拖车","只有校车"],"h1":"2025 年的修改把这条法律扩大到各种车辆。","h2":"从 2025 年 7 月 1 日起，Kansas 的 move-over 法保护任何开着双闪警示灯、停着的车辆，所以你必须换道或减速。","p":"对。任何开着双闪灯、停着的车辆。"},"vi":{"q":"Ở Kansas, từ tháng 7 năm 2025, luật nhường làn (move-over law) áp dụng cho những xe đang dừng nào?","o":["Chỉ xe cảnh sát","Bất kỳ xe nào đang dừng và bật đèn cảnh báo","Chỉ xe kéo","Chỉ xe buýt trường học"],"h1":"Thay đổi năm 2025 mở rộng luật cho mọi loại xe.","h2":"Từ ngày 1 tháng 7 năm 2025, luật nhường làn của Kansas áp dụng cho bất kỳ xe nào đang dừng và bật đèn cảnh báo, nên bạn phải chuyển làn hoặc giảm tốc độ.","p":"Đúng. Bất kỳ xe nào đang dừng và bật đèn cảnh báo."},"tl":{"q":"Sa Kansas, mula Hulyo 2025, aling mga nakahintong sasakyan ang sakop ng move-over law?","o":["Mga sasakyan ng pulis lang","Anumang nakahintong sasakyan na nakabukas ang hazard lights","Mga tow truck lang","Mga school bus lang"],"h1":"Pinalawak ng pagbabago noong 2025 ang batas para sa lahat ng uri ng sasakyan.","h2":"Mula Hulyo 1, 2025, sakop ng move-over law ng Kansas ang anumang nakahintong sasakyan na nakabukas ang hazard warning lights, kaya dapat kang lumipat ng lane o bumagal.","p":"Tama. Anumang nakahintong sasakyan na nakabukas ang hazard lights."},"ar":{"q":"في Kansas، منذ يوليو 2025، أي مركبات متوقفة يشملها قانون الابتعاد (move-over law)؟","o":["سيارات الشرطة فقط","أي مركبة متوقفة وأضواء التحذير فيها مضاءة","شاحنات السحب فقط","الحافلات المدرسية فقط"],"h1":"تغيير 2025 وسّع القانون ليشمل كل أنواع المركبات.","h2":"منذ 1 يوليو 2025، يشمل قانون الابتعاد في Kansas أي مركبة متوقفة تُظهر أضواء التحذير، لذلك يجب أن تغيّر المسار أو تخفّف السرعة.","p":"صحيح. أي مركبة متوقفة وأضواء التحذير فيها مضاءة."},"ref":{"doc":"KS","page":null}},{"id":"ks-023","scope":"KS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Kansas, can police stop a car only because the driver or front-seat passenger is not wearing a seat belt?","o":["No, never","Only at night","Only on interstates","Yes, it is a primary offense"],"h1":"Kansas made this rule stronger in 2010.","h2":"In Kansas, police may stop a car just because the driver or front-seat passenger is not wearing a seat belt.","p":"Right. In the front seat, it is a primary offense."},"es":{"q":"En Kansas, ¿puede la policía detener un carro solo porque el conductor o el pasajero de adelante no lleva el cinturón?","o":["No, nunca","Solo de noche","Solo en autopistas","Sí, es una infracción primaria"],"h1":"Kansas hizo esta regla más estricta en 2010.","h2":"En Kansas, la policía puede detener un carro solo porque el conductor o el pasajero de adelante no lleva puesto el cinturón de seguridad.","p":"Correcto. En el asiento delantero es una infracción primaria."},"zh":{"q":"在 Kansas，警察可以只因为司机或前排乘客没系安全带就让车停下吗？","o":["不可以，任何时候都不行","只在晚上","只在州际公路上","可以，这是主要违规（primary offense）"],"h1":"Kansas 在 2010 年把这个规定加强了。","h2":"在 Kansas，警察可以只因为司机或前排乘客没系安全带，就让车停下。","p":"对。在前排，这是主要违规。"},"vi":{"q":"Ở Kansas, cảnh sát có được chặn xe chỉ vì người lái hoặc hành khách ghế trước không thắt dây an toàn không?","o":["Không, không bao giờ","Chỉ vào ban đêm","Chỉ trên xa lộ liên bang","Có, đó là vi phạm chính (primary offense)"],"h1":"Kansas đã làm luật này chặt hơn vào năm 2010.","h2":"Ở Kansas, cảnh sát có thể chặn xe chỉ vì người lái hoặc hành khách ghế trước không thắt dây an toàn.","p":"Đúng. Ở ghế trước, đó là vi phạm chính."},"tl":{"q":"Sa Kansas, puwede bang patigilin ng pulis ang sasakyan dahil lang hindi naka-seat belt ang driver o ang pasahero sa harap?","o":["Hindi, hindi kailanman","Sa gabi lang","Sa interstate lang","Oo, ito ay primary offense"],"h1":"Pinatibay ng Kansas ang patakarang ito noong 2010.","h2":"Sa Kansas, puwedeng patigilin ng pulis ang sasakyan dahil lang hindi naka-seat belt ang driver o ang pasahero sa harap.","p":"Tama. Sa harapang upuan, ito ay primary offense."},"ar":{"q":"في Kansas، هل يمكن للشرطة إيقاف سيارة فقط لأن السائق أو الراكب الأمامي لا يضع حزام الأمان؟","o":["لا، أبدًا","في الليل فقط","على الطرق السريعة بين الولايات فقط","نعم، إنها مخالفة أساسية (primary offense)"],"h1":"جعلت Kansas هذه القاعدة أقوى في 2010.","h2":"في Kansas يمكن للشرطة إيقاف سيارة فقط لأن السائق أو الراكب في المقعد الأمامي لا يضع حزام الأمان.","p":"صحيح. في المقعد الأمامي، إنها مخالفة أساسية."},"ref":{"doc":"KS","page":null}},{"id":"ks-024","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, how many questions are on the knowledge test?","o":["20 questions","25 questions","40 questions","50 questions"],"h1":"It is a quarter of one hundred.","h2":"In Kansas, the knowledge test has 25 questions about traffic laws and road signs.","p":"Right. The Kansas knowledge test has 25 questions."},"es":{"q":"En Kansas, ¿cuántas preguntas tiene el examen de conocimientos?","o":["20 preguntas","25 preguntas","40 preguntas","50 preguntas"],"h1":"Es la cuarta parte de cien.","h2":"En Kansas, el examen de conocimientos tiene 25 preguntas sobre leyes de tránsito y señales de tránsito.","p":"Correcto. El examen de conocimientos de Kansas tiene 25 preguntas."},"zh":{"q":"在 Kansas，笔试（knowledge test）有多少道题？","o":["20 道题","25 道题","40 道题","50 道题"],"h1":"它是一百的四分之一。","h2":"在 Kansas，笔试有 25 道题，内容是交通法规和道路标志。","p":"对。Kansas 的笔试有 25 道题。"},"vi":{"q":"Ở Kansas, bài thi kiến thức (knowledge test) có bao nhiêu câu hỏi?","o":["20 câu hỏi","25 câu hỏi","40 câu hỏi","50 câu hỏi"],"h1":"Đó là một phần tư của một trăm.","h2":"Ở Kansas, bài thi kiến thức có 25 câu hỏi về luật giao thông và biển báo đường bộ.","p":"Đúng. Bài thi kiến thức ở Kansas có 25 câu hỏi."},"tl":{"q":"Sa Kansas, ilang tanong ang nasa knowledge test?","o":["20 tanong","25 tanong","40 tanong","50 tanong"],"h1":"Ito ay isang-kapat ng isang daan.","h2":"Sa Kansas, may 25 tanong ang knowledge test tungkol sa mga batas trapiko at mga karatula sa daan.","p":"Tama. May 25 tanong ang knowledge test sa Kansas."},"ar":{"q":"في Kansas، كم سؤالًا في اختبار المعرفة (knowledge test)؟","o":["20 سؤالًا","25 سؤالًا","40 سؤالًا","50 سؤالًا"],"h1":"العدد هو ربع المئة.","h2":"في Kansas، يحتوي اختبار المعرفة على 25 سؤالًا عن قوانين المرور وإشارات الطريق.","p":"صحيح. اختبار المعرفة في Kansas فيه 25 سؤالًا."},"ref":{"doc":"KS","page":13}},{"id":"ks-025","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kansas, what happens after you fail the written test for the fourth time?","o":["You may try again the next working day","You must wait 30 days","You must take a driver education course first","You must wait at least six months"],"h1":"The wait is half a year.","h2":"In Kansas, after a fourth failed written test you must wait at least six months before you test again.","p":"Right. After four failures, you wait at least six months."},"es":{"q":"En Kansas, ¿qué pasa si reprueba el examen escrito por cuarta vez?","o":["Puede intentarlo de nuevo el siguiente día hábil","Debe esperar 30 días","Primero debe tomar un curso de educación vial","Debe esperar al menos seis meses"],"h1":"La espera es de medio año.","h2":"En Kansas, después de reprobar el examen escrito por cuarta vez, usted debe esperar al menos seis meses antes de volver a presentarlo.","p":"Correcto. Después de cuatro intentos fallidos, espera al menos seis meses."},"zh":{"q":"在 Kansas，笔试第四次没通过以后会怎样？","o":["你可以在下一个工作日再考","你必须等 30 天","你必须先上驾驶教育课","你必须至少等六个月"],"h1":"要等半年。","h2":"在 Kansas，笔试第四次没通过以后，你必须至少等六个月才能再考。","p":"对。考了四次没通过，要至少等六个月。"},"vi":{"q":"Ở Kansas, điều gì xảy ra sau khi bạn thi viết trượt lần thứ tư?","o":["Bạn có thể thi lại vào ngày làm việc kế tiếp","Bạn phải đợi 30 ngày","Bạn phải học một khóa giáo dục lái xe trước","Bạn phải đợi ít nhất sáu tháng"],"h1":"Thời gian chờ là nửa năm.","h2":"Ở Kansas, sau khi thi viết trượt lần thứ tư, bạn phải đợi ít nhất sáu tháng mới được thi lại.","p":"Đúng. Sau bốn lần trượt, bạn phải đợi ít nhất sáu tháng."},"tl":{"q":"Sa Kansas, ano ang mangyayari kapag bumagsak ka sa written test sa ikaapat na beses?","o":["Puwede kang sumubok ulit sa susunod na araw ng trabaho","Kailangan mong maghintay ng 30 araw","Kailangan mo munang kumuha ng driver education course","Kailangan mong maghintay nang hindi bababa sa anim na buwan"],"h1":"Kalahating taon ang paghihintay.","h2":"Sa Kansas, pagkatapos bumagsak sa written test sa ikaapat na beses, kailangan mong maghintay nang hindi bababa sa anim na buwan bago ka kumuha ulit ng test.","p":"Tama. Pagkatapos ng apat na pagbagsak, maghihintay ka nang hindi bababa sa anim na buwan."},"ar":{"q":"في Kansas، ماذا يحدث بعد أن ترسب في الاختبار الكتابي للمرة الرابعة؟","o":["يمكنك المحاولة مرة أخرى في يوم العمل التالي","يجب أن تنتظر 30 يومًا","يجب أن تأخذ دورة تعليم القيادة أولًا","يجب أن تنتظر ستة أشهر على الأقل"],"h1":"مدة الانتظار نصف سنة.","h2":"في Kansas، بعد الرسوب في الاختبار الكتابي للمرة الرابعة يجب أن تنتظر ستة أشهر على الأقل قبل أن تختبر مرة أخرى.","p":"صحيح. بعد أربع مرات رسوب، تنتظر ستة أشهر على الأقل."},"ref":{"doc":"KS","page":14}},{"id":"ks-026","scope":"KS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kansas, what happens the first time a driver refuses a test for alcohol or drugs?","o":["The license is suspended for 1 year","The driver gets a warning only","The license is suspended for 30 days","The license is taken away for life"],"h1":"It is a long suspension, but not for life.","h2":"In Kansas, refusing a test for alcohol or drugs the first time means a mandatory one-year license suspension.","p":"Right. A first refusal brings a one-year suspension."},"es":{"q":"En Kansas, ¿qué pasa la primera vez que un conductor se niega a hacerse una prueba de alcohol o drogas?","o":["La licencia se suspende por 1 año","El conductor solo recibe una advertencia","La licencia se suspende por 30 días","Le quitan la licencia de por vida"],"h1":"Es una suspensión larga, pero no de por vida.","h2":"En Kansas, negarse por primera vez a una prueba de alcohol o drogas significa una suspensión obligatoria de la licencia por un año.","p":"Correcto. Una primera negativa trae una suspensión de un año."},"zh":{"q":"在 Kansas，司机第一次拒绝做酒精或毒品检测会怎样？","o":["驾照被吊销 1 年","司机只会收到警告","驾照被吊销 30 天","驾照被终身取消"],"h1":"吊销时间很长，但不是终身。","h2":"在 Kansas，第一次拒绝做酒精或毒品检测，驾照必须被吊销一年。","p":"对。第一次拒绝检测，驾照会被吊销一年。"},"vi":{"q":"Ở Kansas, điều gì xảy ra khi tài xế từ chối kiểm tra rượu hoặc ma túy lần đầu tiên?","o":["Bằng lái bị đình chỉ 1 năm","Tài xế chỉ bị cảnh cáo","Bằng lái bị đình chỉ 30 ngày","Bằng lái bị thu hồi suốt đời"],"h1":"Đó là một thời gian đình chỉ dài, nhưng không phải suốt đời.","h2":"Ở Kansas, từ chối kiểm tra rượu hoặc ma túy lần đầu tiên thì bằng lái bắt buộc bị đình chỉ một năm.","p":"Đúng. Từ chối lần đầu thì bị đình chỉ bằng lái một năm."},"tl":{"q":"Sa Kansas, ano ang mangyayari sa unang beses na tumanggi ang driver sa test para sa alak o droga?","o":["Masususpinde ang lisensya nang 1 taon","Babala lang ang matatanggap ng driver","Masususpinde ang lisensya nang 30 araw","Babawiin ang lisensya habambuhay"],"h1":"Mahabang suspensyon ito, pero hindi habambuhay.","h2":"Sa Kansas, kapag tumanggi ka sa test para sa alak o droga sa unang beses, sapilitang masususpinde ang lisensya mo nang isang taon.","p":"Tama. Ang unang pagtanggi ay may suspensyon na isang taon."},"ar":{"q":"في Kansas، ماذا يحدث في المرة الأولى التي يرفض فيها السائق فحص الكحول أو المخدرات؟","o":["تُعلَّق الرخصة لمدة سنة واحدة","يحصل السائق على إنذار فقط","تُعلَّق الرخصة لمدة 30 يومًا","تُسحب الرخصة مدى الحياة"],"h1":"إنه تعليق طويل، لكنه ليس مدى الحياة.","h2":"في Kansas، رفض فحص الكحول أو المخدرات للمرة الأولى يعني تعليقًا إلزاميًا للرخصة لمدة سنة واحدة.","p":"صحيح. الرفض الأول يؤدي إلى تعليق الرخصة لمدة سنة."},"ref":{"doc":"KS","page":14}},{"id":"ks-027","scope":"KS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Kansas, a child aged 4 to 8 may use a seat belt instead of a booster seat in which case?","o":["When riding in the back seat","When the trip is short","When the child is taller than 4 feet 9 inches or weighs over 80 pounds","When a parent gives permission"],"h1":"It depends on the child's size, not on the trip.","h2":"In Kansas, a child aged 4 to 8 must use a child safety seat or booster seat unless the child is taller than 4 feet 9 inches or weighs more than 80 pounds.","p":"Right. Only a child over 4 feet 9 inches or 80 pounds may skip the booster."},"es":{"q":"En Kansas, ¿en qué caso un niño de 4 a 8 años puede usar el cinturón de seguridad en lugar de un asiento elevado?","o":["Cuando va en el asiento trasero","Cuando el viaje es corto","Cuando el niño mide más de 4 pies 9 pulgadas o pesa más de 80 libras","Cuando un padre le da permiso"],"h1":"Depende del tamaño del niño, no del viaje.","h2":"En Kansas, un niño de 4 a 8 años debe usar un asiento de seguridad infantil o asiento elevado, a menos que mida más de 4 pies 9 pulgadas o pese más de 80 libras.","p":"Correcto. Solo un niño de más de 4 pies 9 pulgadas o de 80 libras puede dejar el asiento elevado."},"zh":{"q":"在 Kansas，4 到 8 岁的孩子在哪种情况下可以用安全带代替增高座椅（booster seat）？","o":["坐在后座的时候","路程很短的时候","孩子身高超过 4 英尺 9 英寸或体重超过 80 磅的时候","家长同意的时候"],"h1":"要看孩子的身材，不看路程。","h2":"在 Kansas，4 到 8 岁的孩子必须使用儿童安全座椅或增高座椅，除非孩子身高超过 4 英尺 9 英寸或体重超过 80 磅。","p":"对。只有身高超过 4 英尺 9 英寸或体重超过 80 磅的孩子才可以不用增高座椅。"},"vi":{"q":"Ở Kansas, trẻ từ 4 đến 8 tuổi được dùng dây an toàn thay cho ghế nâng (booster seat) trong trường hợp nào?","o":["Khi ngồi ở ghế sau","Khi chuyến đi ngắn","Khi trẻ cao hơn 4 feet 9 inch hoặc nặng hơn 80 pound","Khi cha mẹ cho phép"],"h1":"Điều này tùy vào vóc dáng của trẻ, không phải chuyến đi.","h2":"Ở Kansas, trẻ từ 4 đến 8 tuổi phải dùng ghế an toàn trẻ em hoặc ghế nâng, trừ khi trẻ cao hơn 4 feet 9 inch hoặc nặng hơn 80 pound.","p":"Đúng. Chỉ trẻ cao hơn 4 feet 9 inch hoặc nặng hơn 80 pound mới được không dùng ghế nâng."},"tl":{"q":"Sa Kansas, kailan puwedeng gumamit ng seat belt sa halip na booster seat ang batang edad 4 hanggang 8?","o":["Kapag nakaupo sa likurang upuan","Kapag maikli ang biyahe","Kapag mas matangkad ang bata sa 4 feet 9 inches o mas mabigat sa 80 pounds","Kapag pumayag ang magulang"],"h1":"Nakadepende ito sa laki ng bata, hindi sa biyahe.","h2":"Sa Kansas, ang batang edad 4 hanggang 8 ay dapat gumamit ng child safety seat o booster seat, maliban kung mas matangkad siya sa 4 feet 9 inches o mas mabigat sa 80 pounds.","p":"Tama. Ang batang lampas 4 feet 9 inches o 80 pounds lang ang puwedeng hindi gumamit ng booster."},"ar":{"q":"في Kansas، متى يجوز لطفل عمره من 4 إلى 8 سنوات أن يستخدم حزام الأمان بدلًا من المقعد الرافع (booster seat)؟","o":["عند الجلوس في المقعد الخلفي","عندما تكون الرحلة قصيرة","عندما يكون طول الطفل أكثر من 4 أقدام و9 بوصات أو وزنه أكثر من 80 رطلًا","عندما يعطي أحد الوالدين الإذن"],"h1":"الأمر يعتمد على حجم الطفل، لا على الرحلة.","h2":"في Kansas، يجب على الطفل الذي عمره من 4 إلى 8 سنوات أن يستخدم مقعد أمان للأطفال أو مقعدًا رافعًا، إلا إذا كان طوله أكثر من 4 أقدام و9 بوصات أو وزنه أكثر من 80 رطلًا.","p":"صحيح. فقط الطفل الذي طوله أكثر من 4 أقدام و9 بوصات أو وزنه أكثر من 80 رطلًا يمكنه ألا يستخدم المقعد الرافع."},"ref":{"doc":"KS","page":16}},{"id":"ks-028","scope":"KS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Kansas, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 15 feet","No closer than 50 feet"],"h1":"Fire trucks need room to hook up to the hydrant.","h2":"In Kansas, you may not park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a hydrant."},"es":{"q":"En Kansas, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 15 pies","No más cerca de 50 pies"],"h1":"Los bomberos necesitan espacio para conectarse al hidrante.","h2":"En Kansas, usted no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese al menos a 15 pies de un hidrante."},"zh":{"q":"在 Kansas，停车时离消防栓最近可以多近？","o":["不能近于 5 英尺","不能近于 10 英尺","不能近于 15 英尺","不能近于 50 英尺"],"h1":"消防车需要空间连接消防栓。","h2":"在 Kansas，你不能在离消防栓 15 英尺以内的地方停车。","p":"对。离消防栓至少 15 英尺。"},"vi":{"q":"Ở Kansas, bạn được đỗ xe gần trụ nước cứu hỏa đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 15 feet","Không gần hơn 50 feet"],"h1":"Xe cứu hỏa cần chỗ để nối vào trụ nước.","h2":"Ở Kansas, bạn không được đỗ xe trong vòng 15 feet tính từ trụ nước cứu hỏa.","p":"Đúng. Hãy cách trụ nước ít nhất 15 feet."},"tl":{"q":"Sa Kansas, gaano kalapit sa fire hydrant ka puwedeng pumarada?","o":["Hindi lalapit sa 5 talampakan","Hindi lalapit sa 10 talampakan","Hindi lalapit sa 15 talampakan","Hindi lalapit sa 50 talampakan"],"h1":"Kailangan ng mga fire truck ng puwang para makakabit sa hydrant.","h2":"Sa Kansas, hindi ka puwedeng pumarada sa loob ng 15 talampakan mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 15 talampakan mula sa hydrant."},"ar":{"q":"في Kansas، ما أقرب مسافة يمكنك أن تركن فيها سيارتك من صنبور إطفاء الحريق؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 10 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 50 قدمًا"],"h1":"تحتاج سيارات الإطفاء إلى مساحة لتوصيل الخراطيم بالصنبور.","h2":"في Kansas لا يجوز لك أن تركن سيارتك على بُعد أقل من 15 قدمًا من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بُعد 15 قدمًا على الأقل من الصنبور."},"ref":{"doc":"KS","page":19}},{"id":"ks-029","scope":"KS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kansas, what following distance does the handbook advise in bad weather or other poor conditions?","o":["Four seconds","One second","Two seconds","Three car lengths"],"h1":"It is double the time used in good conditions.","h2":"In Kansas, the handbook advises a two-second following distance in good conditions and four seconds in poor conditions.","p":"Right. Use four seconds when conditions are poor."},"es":{"q":"En Kansas, ¿qué distancia de seguimiento recomienda el manual con mal tiempo u otras malas condiciones?","o":["Cuatro segundos","Un segundo","Dos segundos","Tres largos de carro"],"h1":"Es el doble del tiempo que se usa con buenas condiciones.","h2":"En Kansas, el manual recomienda dos segundos de distancia con buenas condiciones y cuatro segundos con malas condiciones.","p":"Correcto. Use cuatro segundos cuando las condiciones son malas."},"zh":{"q":"在 Kansas，驾驶手册建议在坏天气或其他不良条件下保持多大的跟车距离？","o":["四秒","一秒","两秒","三个车身长度"],"h1":"这是良好条件下所用时间的两倍。","h2":"在 Kansas，驾驶手册建议在良好条件下保持两秒的跟车距离，在不良条件下保持四秒。","p":"对。条件不好时，保持四秒。"},"vi":{"q":"Ở Kansas, sổ tay lái xe khuyên giữ khoảng cách bao xa với xe phía trước khi thời tiết xấu hoặc điều kiện kém?","o":["Bốn giây","Một giây","Hai giây","Ba thân xe"],"h1":"Đó là gấp đôi thời gian dùng khi điều kiện tốt.","h2":"Ở Kansas, sổ tay khuyên giữ khoảng cách hai giây khi điều kiện tốt và bốn giây khi điều kiện kém.","p":"Đúng. Hãy giữ bốn giây khi điều kiện kém."},"tl":{"q":"Sa Kansas, anong layo sa sinusundang sasakyan ang ipinapayo ng handbook kapag masama ang panahon o iba pang mahirap na kondisyon?","o":["Apat na segundo","Isang segundo","Dalawang segundo","Tatlong haba ng kotse"],"h1":"Doble ito ng oras na ginagamit kapag maganda ang kondisyon.","h2":"Sa Kansas, ipinapayo ng handbook ang dalawang segundong layo kapag maganda ang kondisyon at apat na segundo kapag mahirap ang kondisyon.","p":"Tama. Gumamit ng apat na segundo kapag mahirap ang kondisyon."},"ar":{"q":"في Kansas، ما مسافة المتابعة التي ينصح بها دليل القيادة في الطقس السيئ أو الظروف الصعبة الأخرى؟","o":["أربع ثوانٍ","ثانية واحدة","ثانيتان","طول ثلاث سيارات"],"h1":"إنها ضعف الوقت المستخدم في الظروف الجيدة.","h2":"في Kansas ينصح دليل القيادة بمسافة متابعة ثانيتين في الظروف الجيدة وأربع ثوانٍ في الظروف الصعبة.","p":"صحيح. استخدم أربع ثوانٍ عندما تكون الظروف صعبة."},"ref":{"doc":"KS","page":17}},{"id":"ks-030","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kansas, what vision do you need to pass the screening for a license?","o":["20/20 in both eyes","20/40 in both eyes","20/70 in one eye","20/40 in at least one eye"],"h1":"Only one eye needs to meet the standard, with or without glasses.","h2":"In Kansas, you need vision of at least 20/40 in one eye, with or without glasses or contacts.","p":"Right. You need at least 20/40 in one eye."},"es":{"q":"En Kansas, ¿qué vista necesita para aprobar la prueba de la vista para la licencia?","o":["20/20 en los dos ojos","20/40 en los dos ojos","20/70 en un ojo","20/40 en al menos un ojo"],"h1":"Solo un ojo necesita cumplir el requisito, con o sin lentes.","h2":"En Kansas, usted necesita una vista de al menos 20/40 en un ojo, con o sin lentes o lentes de contacto.","p":"Correcto. Necesita al menos 20/40 en un ojo."},"zh":{"q":"在 Kansas，要通过驾照的视力检查，你需要什么样的视力？","o":["双眼 20/20","双眼 20/40","一只眼 20/70","至少一只眼 20/40"],"h1":"只需要一只眼睛达到标准，戴不戴眼镜都可以。","h2":"在 Kansas，你至少一只眼睛的视力需要达到 20/40，戴不戴眼镜或隐形眼镜都可以。","p":"对。你至少一只眼睛需要达到 20/40。"},"vi":{"q":"Ở Kansas, bạn cần thị lực như thế nào để qua bài kiểm tra mắt khi lấy bằng lái?","o":["20/20 ở cả hai mắt","20/40 ở cả hai mắt","20/70 ở một mắt","20/40 ở ít nhất một mắt"],"h1":"Chỉ cần một mắt đạt tiêu chuẩn, có hoặc không có kính.","h2":"Ở Kansas, bạn cần thị lực ít nhất 20/40 ở một mắt, có hoặc không có kính đeo hay kính áp tròng.","p":"Đúng. Bạn cần ít nhất 20/40 ở một mắt."},"tl":{"q":"Sa Kansas, anong paningin ang kailangan mo para pumasa sa vision screening para sa lisensya?","o":["20/20 sa dalawang mata","20/40 sa dalawang mata","20/70 sa isang mata","20/40 sa kahit isang mata"],"h1":"Isang mata lang ang kailangang umabot sa pamantayan, may salamin man o wala.","h2":"Sa Kansas, kailangan mo ng paningin na hindi bababa sa 20/40 sa isang mata, may salamin o contact lens man o wala.","p":"Tama. Kailangan mo ng hindi bababa sa 20/40 sa isang mata."},"ar":{"q":"في Kansas، ما قوة النظر التي تحتاجها لتنجح في فحص النظر للحصول على رخصة؟","o":["20/20 في العينين","20/40 في العينين","20/70 في عين واحدة","20/40 في عين واحدة على الأقل"],"h1":"يكفي أن تبلغ عين واحدة المعيار، بالنظارة أو بدونها.","h2":"في Kansas تحتاج إلى نظر لا يقل عن 20/40 في عين واحدة، بالنظارة أو العدسات اللاصقة أو بدونها.","p":"صحيح. تحتاج إلى 20/40 على الأقل في عين واحدة."},"ref":{"doc":"KS","page":13}},{"id":"ks-031","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, your driver's license has been expired for more than one year. What must you do to get it back?","o":["Pay only the $1 late penalty","Pass the vision, written, and driving tests","Pass only the vision test","Take a driver education course"],"h1":"After a long time, you must show everything again, as a new driver would.","h2":"In Kansas, if your license has been expired for more than one year, you must pass full testing: the vision, written, and driving tests.","p":"Right. After more than a year, you take all three tests."},"es":{"q":"En Kansas, su licencia de manejar lleva más de un año vencida. ¿Qué debe hacer para recuperarla?","o":["Pagar solo la multa de $1 por atraso","Aprobar las pruebas de la vista, escrita y de manejo","Aprobar solo la prueba de la vista","Tomar un curso de educación vial"],"h1":"Después de mucho tiempo, debe demostrar todo otra vez, como un conductor nuevo.","h2":"En Kansas, si su licencia lleva más de un año vencida, usted debe aprobar todas las pruebas: la de la vista, la escrita y la de manejo.","p":"Correcto. Después de más de un año, toma las tres pruebas."},"zh":{"q":"在 Kansas，你的驾照已经过期超过一年。要恢复驾照，你必须做什么？","o":["只交 $1 的逾期罚款","通过视力、笔试和路考","只通过视力检查","参加驾驶教育课程"],"h1":"过了很长时间后，你必须像新司机一样重新证明一切。","h2":"在 Kansas，如果你的驾照过期超过一年，你必须通过全部考试：视力、笔试和路考。","p":"对。过期超过一年，三项考试都要考。"},"vi":{"q":"Ở Kansas, bằng lái của bạn đã hết hạn hơn một năm. Bạn phải làm gì để lấy lại?","o":["Chỉ trả tiền phạt trễ hạn $1","Đậu bài kiểm tra mắt, thi viết và thi lái","Chỉ đậu bài kiểm tra mắt","Học một khóa giáo dục lái xe"],"h1":"Sau một thời gian dài, bạn phải chứng minh lại mọi thứ như một tài xế mới.","h2":"Ở Kansas, nếu bằng lái của bạn đã hết hạn hơn một năm, bạn phải thi đầy đủ: kiểm tra mắt, thi viết và thi lái.","p":"Đúng. Sau hơn một năm, bạn phải thi cả ba bài."},"tl":{"q":"Sa Kansas, mahigit isang taon nang expired ang lisensya mo. Ano ang dapat mong gawin para makuha itong muli?","o":["Bayaran lang ang $1 na multa sa pagkahuli","Pumasa sa vision, written, at driving test","Pumasa lang sa vision test","Kumuha ng driver education course"],"h1":"Pagkatapos ng mahabang panahon, kailangan mong ipakita muli ang lahat, gaya ng bagong driver.","h2":"Sa Kansas, kung mahigit isang taon nang expired ang lisensya mo, kailangan mong pumasa sa buong pagsusulit: ang vision, written, at driving test.","p":"Tama. Pagkalipas ng mahigit isang taon, kukunin mo ang tatlong test."},"ar":{"q":"في Kansas، انتهت صلاحية رخصة قيادتك منذ أكثر من سنة. ماذا يجب أن تفعل لاستعادتها؟","o":["دفع غرامة التأخير $1 فقط","النجاح في فحص النظر والاختبار الكتابي واختبار القيادة","النجاح في فحص النظر فقط","حضور دورة تعليم القيادة"],"h1":"بعد مدة طويلة، يجب أن تُثبت كل شيء من جديد، كما يفعل السائق الجديد.","h2":"في Kansas، إذا انتهت صلاحية رخصتك منذ أكثر من سنة، يجب أن تنجح في الاختبارات كاملة: فحص النظر والاختبار الكتابي واختبار القيادة.","p":"صحيح. بعد أكثر من سنة، تخضع للاختبارات الثلاثة."},"ref":{"doc":"KS","page":14}},{"id":"ks-032","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kansas, how soon after moving to the state must a new resident get a Kansas driver's license?","o":["Within 10 days","Within 1 year","Within 90 days","Only when the old license expires"],"h1":"It is about three months.","h2":"In Kansas, a new resident must get a Kansas driver's license within 90 days of moving to the state.","p":"Right. New residents have 90 days."},"es":{"q":"En Kansas, ¿en cuánto tiempo después de mudarse al estado debe un nuevo residente obtener una licencia de Kansas?","o":["En un plazo de 10 días","En un plazo de 1 año","En un plazo de 90 días","Solo cuando venza la licencia anterior"],"h1":"Son unos tres meses.","h2":"En Kansas, un nuevo residente debe obtener una licencia de conducir de Kansas en un plazo de 90 días después de mudarse al estado.","p":"Correcto. Los nuevos residentes tienen 90 días."},"ref":{"doc":"KS","page":11}},{"id":"ks-033","scope":"KS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kansas, how long is a Class C instruction permit valid?","o":["One year from the day it is issued","Six months from the day it is issued","Two years from the day it is issued","Until your 18th birthday"],"h1":"You renew it by passing the written test again.","h2":"In Kansas, a Class C instruction permit is valid for one year from the day it is issued.","p":"Right. The permit lasts one year."},"es":{"q":"En Kansas, ¿por cuánto tiempo es válido un permiso de aprendizaje Clase C?","o":["Un año desde el día en que se emite","Seis meses desde el día en que se emite","Dos años desde el día en que se emite","Hasta que usted cumpla 18 años"],"h1":"Se renueva aprobando otra vez el examen escrito.","h2":"En Kansas, un permiso de aprendizaje Clase C es válido por un año desde el día en que se emite.","p":"Correcto. El permiso dura un año."},"ref":{"doc":"KS","page":14}},{"id":"ks-034","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kansas, you fail the written test for the first time. When may you take it again?","o":["Only after waiting 30 days","Only after waiting six months","Only after taking a driving class","The next working day, after paying a small re-exam fee"],"h1":"Kansas lets you try again very soon.","h2":"In Kansas, you may retake a failed test as soon as the next working day, after paying a $1.50 re-exam fee.","p":"Right. You can try again the next working day."},"es":{"q":"En Kansas, usted no aprueba el examen escrito por primera vez. ¿Cuándo puede volver a tomarlo?","o":["Solo después de esperar 30 días","Solo después de esperar seis meses","Solo después de tomar una clase de manejo","El siguiente día hábil, después de pagar una pequeña tarifa"],"h1":"Kansas le permite intentarlo de nuevo muy pronto.","h2":"En Kansas, usted puede repetir un examen no aprobado desde el siguiente día hábil, después de pagar una tarifa de $1.50.","p":"Correcto. Puede intentarlo otra vez el siguiente día hábil."},"ref":{"doc":"KS","page":14}},{"id":"ks-035","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, what score do you need to pass the knowledge test?","o":["70 percent","80 percent","75 percent","90 percent"],"h1":"On a 25-question test, that is 20 right answers.","h2":"In Kansas, you must score 80 percent to pass the knowledge test.","p":"Right. You need 80 percent."},"es":{"q":"En Kansas, ¿qué puntaje necesita para aprobar el examen de conocimientos?","o":["70 por ciento","80 por ciento","75 por ciento","90 por ciento"],"h1":"En un examen de 25 preguntas, son 20 respuestas correctas.","h2":"En Kansas, usted debe obtener un 80 por ciento para aprobar el examen de conocimientos.","p":"Correcto. Necesita un 80 por ciento."},"ref":{"doc":"KS","page":94}},{"id":"ks-036","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kansas, does a driver education course taken over the internet count for a license?","o":["Yes, any online course is accepted","Yes, if the course lasts at least 6 hours","No, internet courses are not accepted","Yes, but only for drivers 16 or older"],"h1":"Approved courses include time in a classroom and behind the wheel.","h2":"In Kansas, internet driver education courses are not accepted; only courses from approved school districts or approved private schools count.","p":"Right. Online driver education does not count in Kansas."},"es":{"q":"En Kansas, ¿cuenta para la licencia un curso de educación vial tomado por internet?","o":["Sí, se acepta cualquier curso en línea","Sí, si el curso dura al menos 6 horas","No, los cursos por internet no se aceptan","Sí, pero solo para conductores de 16 años o más"],"h1":"Los cursos aprobados incluyen tiempo en el salón y al volante.","h2":"En Kansas, los cursos de educación vial por internet no se aceptan; solo cuentan los cursos de distritos escolares aprobados o de escuelas privadas aprobadas.","p":"Correcto. La educación vial en línea no cuenta en Kansas."},"ref":{"doc":"KS","page":9}},{"id":"ks-037","scope":"KS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kansas, how many moving violations within 12 months can lead to a license suspension?","o":["Three","Five","Seven","Ten"],"h1":"It is a small number.","h2":"In Kansas, three moving violation convictions within 12 months can get your license suspended.","p":"Right. Three moving violations in a year can cost you your license."},"es":{"q":"En Kansas, ¿cuántas infracciones de tránsito en movimiento en 12 meses pueden causar la suspensión de la licencia?","o":["Tres","Cinco","Siete","Diez"],"h1":"Es un número pequeño.","h2":"En Kansas, tres condenas por infracciones en movimiento en 12 meses pueden causar la suspensión de su licencia.","p":"Correcto. Tres infracciones en un año pueden costarle la licencia."},"ref":{"doc":"KS","page":14}},{"id":"ks-038","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kansas, what happens if you do not keep liability insurance on your vehicle at all times?","o":["Nothing, as long as you drive carefully","You only get a warning","You must take the written test again","Your license is suspended with no set end date"],"h1":"Kansas treats a gap in insurance very seriously.","h2":"In Kansas, failing to keep continuous liability insurance on your vehicle leads to a mandatory suspension with no set end date.","p":"Right. A gap in insurance means an indefinite suspension."},"es":{"q":"En Kansas, ¿qué pasa si usted no mantiene siempre un seguro de responsabilidad civil en su vehículo?","o":["Nada, siempre que maneje con cuidado","Solo recibe una advertencia","Debe tomar otra vez el examen escrito","Su licencia se suspende sin fecha de fin"],"h1":"Kansas toma muy en serio una falta de seguro.","h2":"En Kansas, no mantener un seguro de responsabilidad civil continuo en su vehículo causa una suspensión obligatoria sin fecha de fin.","p":"Correcto. Una falta de seguro causa una suspensión indefinida."},"ref":{"doc":"KS","page":14}},{"id":"ks-039","scope":"KS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Kansas, what happens after a fifth test result of .08 or more, or a fifth refusal to be tested?","o":["A 90-day suspension","The license is revoked for life","A fine only","A 1-year suspension"],"h1":"This is the most serious result possible.","h2":"In Kansas, a fifth test result of .08 or higher, or a fifth test refusal, means permanent loss of your license.","p":"Right. The fifth time, the license is revoked for good."},"es":{"q":"En Kansas, ¿qué pasa después de un quinto resultado de prueba de .08 o más, o una quinta negativa a hacerse la prueba?","o":["Una suspensión de 90 días","La licencia se revoca de por vida","Solo una multa","Una suspensión de 1 año"],"h1":"Es el resultado más grave posible.","h2":"En Kansas, un quinto resultado de .08 o más, o una quinta negativa a la prueba, significa la pérdida permanente de su licencia.","p":"Correcto. La quinta vez, la licencia se revoca para siempre."},"ref":{"doc":"KS","page":15}},{"id":"ks-040","scope":"KS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Kansas, what is the fine for a first conviction of driving under the influence?","o":["$100 to $250","$300 to $500","$750 to $1,000","$2,500 to $5,000"],"h1":"Court costs are added on top of this fine.","h2":"In Kansas, a first DUI conviction carries a fine of $750 to $1,000, plus court costs.","p":"Right. A first DUI costs $750 to $1,000 in fines."},"es":{"q":"En Kansas, ¿cuál es la multa por una primera condena por manejar bajo los efectos del alcohol o las drogas?","o":["De $100 a $250","De $300 a $500","De $750 a $1,000","De $2,500 a $5,000"],"h1":"A esta multa se le suman los costos del tribunal.","h2":"En Kansas, una primera condena por DUI tiene una multa de $750 a $1,000, más los costos del tribunal.","p":"Correcto. Un primer DUI cuesta de $750 a $1,000 de multa."},"ref":{"doc":"KS","page":24}},{"id":"ks-041","scope":"KS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Kansas, what is the speed limit in an urban district when no other limit is posted?","o":["30 mph","20 mph","40 mph","45 mph"],"h1":"It is the default limit for streets in towns and cities.","h2":"In Kansas, the speed limit in any urban district is 30 mph unless another limit is posted.","p":"Right. In town, the limit is 30 mph unless posted otherwise."},"es":{"q":"En Kansas, ¿cuál es el límite de velocidad en una zona urbana cuando no hay otro límite indicado?","o":["30 mph","20 mph","40 mph","45 mph"],"h1":"Es el límite normal para las calles de pueblos y ciudades.","h2":"En Kansas, el límite de velocidad en cualquier zona urbana es de 30 mph, a menos que se indique otro límite.","p":"Correcto. En la ciudad, el límite es de 30 mph si no se indica otro."},"ref":{"doc":"KS","page":16}},{"id":"ks-042","scope":"KS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Kansas, what is the speed limit on a state or federal highway when no other limit is posted?","o":["55 mph","60 mph","70 mph","65 mph"],"h1":"It is higher than on county roads but lower than on posted divided highways.","h2":"In Kansas, the speed limit on a state or federal highway is 65 mph unless another limit is posted.","p":"Right. State and federal highways are 65 mph."},"es":{"q":"En Kansas, ¿cuál es el límite de velocidad en una carretera estatal o federal cuando no hay otro límite indicado?","o":["55 mph","60 mph","70 mph","65 mph"],"h1":"Es más alto que en los caminos del condado, pero más bajo que en las autopistas divididas señalizadas.","h2":"En Kansas, el límite de velocidad en una carretera estatal o federal es de 65 mph, a menos que se indique otro límite.","p":"Correcto. Las carreteras estatales y federales son de 65 mph."},"ref":{"doc":"KS","page":16}},{"id":"ks-043","scope":"KS","cat":"signals","sign":null,"c":1,"en":{"q":"In Kansas, at least how far before a turn must you start to signal?","o":["25 feet","100 feet","50 feet","500 feet"],"h1":"It is about the length of six or seven cars.","h2":"In Kansas, you must give your signal at least 100 feet before you turn.","p":"Right. Signal at least 100 feet ahead."},"es":{"q":"En Kansas, ¿al menos a qué distancia antes de girar debe empezar a señalar?","o":["25 pies","100 pies","50 pies","500 pies"],"h1":"Es más o menos el largo de seis o siete carros.","h2":"En Kansas, usted debe hacer la señal al menos 100 pies antes de girar.","p":"Correcto. Señale al menos 100 pies antes."},"ref":{"doc":"KS","page":17}},{"id":"ks-044","scope":"KS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Kansas, you may not make a U-turn where other drivers cannot see you from how far away?","o":["100 feet","200 feet","500 feet","50 feet"],"h1":"Think of a distance longer than a football field.","h2":"In Kansas, do not make a U-turn anywhere other drivers cannot see you from at least 500 feet away.","p":"Right. You need to be visible for 500 feet to make a U-turn."},"es":{"q":"En Kansas, no puede dar una vuelta en U donde los otros conductores no puedan verlo desde ¿qué distancia?","o":["100 pies","200 pies","500 pies","50 pies"],"h1":"Piense en una distancia más larga que un campo de fútbol americano.","h2":"En Kansas, no dé una vuelta en U en un lugar donde los otros conductores no puedan verlo desde al menos 500 pies.","p":"Correcto. Deben poder verlo a 500 pies para dar una vuelta en U."},"ref":{"doc":"KS","page":17}},{"id":"ks-045","scope":"KS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Kansas, on a two-lane road, you may not pass within how many feet of an intersection or railroad crossing?","o":["100 feet","25 feet","50 feet","1,000 feet"],"h1":"The same distance applies near a bridge or tunnel when your view is blocked.","h2":"In Kansas, you may not pass within 100 feet of an intersection or a railroad crossing.","p":"Right. No passing within 100 feet of an intersection or railroad crossing."},"es":{"q":"En Kansas, en un camino de dos carriles, ¿a cuántos pies de una intersección o un cruce de ferrocarril no puede rebasar?","o":["100 pies","25 pies","50 pies","1,000 pies"],"h1":"La misma distancia se aplica cerca de un puente o túnel cuando no se ve bien.","h2":"En Kansas, usted no puede rebasar a menos de 100 pies de una intersección o de un cruce de ferrocarril.","p":"Correcto. No rebase a menos de 100 pies de una intersección o un cruce de tren."},"ref":{"doc":"KS","page":17}},{"id":"ks-046","scope":"KS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Kansas, when you pass on a two-lane road, you must be back in your lane before you come within what distance of an oncoming vehicle?","o":["50 feet","100 feet","1,000 feet","200 feet"],"h1":"It is twice the distance you signal before a turn.","h2":"In Kansas, you must return to your own lane before you come within 200 feet of a vehicle coming toward you.","p":"Right. Be back in your lane before you are 200 feet from oncoming traffic."},"es":{"q":"En Kansas, cuando rebasa en un camino de dos carriles, ¿antes de qué distancia de un vehículo que viene de frente debe volver a su carril?","o":["50 pies","100 pies","1,000 pies","200 pies"],"h1":"Es el doble de la distancia a la que señala antes de girar.","h2":"En Kansas, usted debe volver a su carril antes de llegar a 200 pies de un vehículo que viene de frente.","p":"Correcto. Vuelva a su carril antes de estar a 200 pies del tráfico que viene de frente."},"ref":{"doc":"KS","page":17}},{"id":"ks-047","scope":"KS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Kansas, how must a child under 4 years old ride in a car?","o":["In a regular seat belt","In a federally approved child safety seat","On an adult's lap in the back seat","In a booster seat with a lap belt only"],"h1":"The youngest children need the most protection.","h2":"In Kansas, every child under 4 must ride in a federally approved child safety seat.","p":"Right. Children under 4 ride in an approved child safety seat."},"es":{"q":"En Kansas, ¿cómo debe viajar en el carro un niño menor de 4 años?","o":["Con un cinturón de seguridad normal","En un asiento de seguridad infantil aprobado por el gobierno federal","En las piernas de un adulto en el asiento trasero","En un asiento elevado solo con cinturón de cadera"],"h1":"Los niños más pequeños necesitan la mayor protección.","h2":"En Kansas, todo niño menor de 4 años debe viajar en un asiento de seguridad infantil aprobado por el gobierno federal.","p":"Correcto. Los menores de 4 años viajan en un asiento infantil aprobado."},"ref":{"doc":"KS","page":16}},{"id":"ks-048","scope":"KS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Kansas, how close to the nearest rail of a railroad crossing may you park?","o":["No closer than 10 feet","No closer than 25 feet","No closer than 50 feet","No closer than 15 feet"],"h1":"It is more than three times the distance you keep from a fire hydrant.","h2":"In Kansas, you may not park within 50 feet of the nearest rail at a railroad crossing.","p":"Right. Park at least 50 feet from the tracks."},"es":{"q":"En Kansas, ¿qué tan cerca del riel más cercano de un cruce de ferrocarril puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 25 pies","No más cerca de 50 pies","No más cerca de 15 pies"],"h1":"Es más de tres veces la distancia que debe dejar de un hidrante.","h2":"En Kansas, usted no puede estacionarse a menos de 50 pies del riel más cercano en un cruce de ferrocarril.","p":"Correcto. Estaciónese al menos a 50 pies de las vías."},"ref":{"doc":"KS","page":19}},{"id":"ks-049","scope":"KS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kansas, what does the law forbid every driver to do with a phone while driving?","o":["Write, send or read texts or emails","Use a GPS map","Listen to a weather report","Have a phone in the car"],"h1":"The law is about written messages.","h2":"In Kansas, no driver may use a phone or other device to write, send or read texts, emails or other written messages while driving.","p":"Right. Texting and email are against the law while driving."},"es":{"q":"En Kansas, ¿qué prohíbe la ley a todos los conductores hacer con el teléfono mientras manejan?","o":["Escribir, enviar o leer mensajes de texto o correos","Usar un mapa GPS","Escuchar un reporte del clima","Tener un teléfono en el carro"],"h1":"La ley trata de los mensajes escritos.","h2":"En Kansas, ningún conductor puede usar un teléfono u otro aparato para escribir, enviar o leer mensajes de texto, correos u otros mensajes escritos mientras maneja.","p":"Correcto. Mandar textos y correos está prohibido mientras maneja."},"ref":{"doc":"KS","page":19}},{"id":"ks-050","scope":"KS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Kansas, when must you turn on your headlights during the day?","o":["Only on Interstate highways","Only when you drive faster than 55 mph","Only inside tunnels","Whenever your windshield wipers are in use"],"h1":"Think about rain, sleet and snow.","h2":"In Kansas, you must turn on your headlights whenever you use your windshield wipers.","p":"Right. Wipers on means headlights on."},"es":{"q":"En Kansas, ¿cuándo debe encender los faros durante el día?","o":["Solo en las autopistas interestatales","Solo cuando maneje a más de 55 mph","Solo dentro de los túneles","Siempre que use los limpiaparabrisas"],"h1":"Piense en la lluvia, el aguanieve y la nieve.","h2":"En Kansas, usted debe encender los faros siempre que use los limpiaparabrisas.","p":"Correcto. Si usa los limpiaparabrisas, encienda los faros."},"ref":{"doc":"KS","page":67}},{"id":"ks-051","scope":"KS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Kansas, during which months may vehicles use studded snow tires?","o":["From September 1 to May 1","From November 1 to April 1","From December 1 to March 1","All year round"],"h1":"The season starts in late fall and ends in early spring.","h2":"In Kansas, vehicles may use studded snow tires from November 1 to April 1 each year.","p":"Right. Studded tires are allowed from November 1 to April 1."},"es":{"q":"En Kansas, ¿en qué meses pueden los vehículos usar llantas de nieve con clavos?","o":["Del 1 de septiembre al 1 de mayo","Del 1 de noviembre al 1 de abril","Del 1 de diciembre al 1 de marzo","Todo el año"],"h1":"La temporada empieza a fines del otoño y termina a principios de la primavera.","h2":"En Kansas, los vehículos pueden usar llantas de nieve con clavos del 1 de noviembre al 1 de abril de cada año.","p":"Correcto. Las llantas con clavos se permiten del 1 de noviembre al 1 de abril."},"ref":{"doc":"KS","page":59}},{"id":"ky-001","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"A 2025 law lowered the age by one year, from 16.","h2":"You can get a Kentucky instruction permit at 15, because a 2025 law lowered the age from 16.","p":"Right. In Kentucky the permit starts at 15."},"es":{"q":"En Kentucky, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["14 años","15 años","16 años","17 años"],"h1":"Una ley de 2025 bajó la edad un año, desde los 16.","h2":"Usted puede obtener un permiso de instrucción en Kentucky a los 15 años, porque una ley de 2025 bajó la edad desde los 16.","p":"Correcto. En Kentucky el permiso empieza a los 15."},"zh":{"q":"在 Kentucky，最小几岁可以拿到学习驾照（instruction permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"2025 年的一条法律把年龄从 16 岁降低了一年。","h2":"你 15 岁就可以拿到 Kentucky 的学习驾照，因为 2025 年的一条法律把年龄从 16 岁降低了。","p":"对。在 Kentucky，学习驾照从 15 岁开始。"},"vi":{"q":"Ở Kentucky, tuổi nhỏ nhất để được cấp giấy phép tập lái (instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Một luật năm 2025 đã hạ tuổi này xuống một năm, từ 16 tuổi.","h2":"Bạn có thể được cấp giấy phép tập lái ở Kentucky khi 15 tuổi, vì một luật năm 2025 đã hạ tuổi này từ 16 xuống.","p":"Đúng. Ở Kentucky, giấy phép tập lái bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Kentucky, ano ang pinakabatang edad para makakuha ng instruction permit (permit sa pag-aaral magmaneho)?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang batas noong 2025 ang nagbaba ng edad nang isang taon, mula 16.","h2":"Makakakuha ka ng Kentucky instruction permit sa edad na 15, dahil ibinaba ng isang batas noong 2025 ang edad mula 16.","p":"Tama. Sa Kentucky, nagsisimula ang permit sa edad na 15."},"ar":{"q":"في Kentucky، ما أصغر عمر للحصول على تصريح تعلّم القيادة (instruction permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"قانون صدر في 2025 خفّض العمر سنة واحدة، من 16.","h2":"يمكنك الحصول على تصريح تعلّم القيادة في Kentucky في عمر 15 سنة، لأن قانونًا صدر في 2025 خفّض العمر من 16.","p":"صحيح. في Kentucky يبدأ تصريح التعلّم من عمر 15 سنة."},"ref":{"doc":"KY","page":5}},{"id":"ky-002","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, how long must a driver under 21 hold the instruction permit before applying for a license?","o":["At least 30 days","At least 60 days","At least one year","At least 180 days"],"h1":"It is about six months.","h2":"A Kentucky driver under 21 must hold the instruction permit for at least 180 days, about six months, before applying for a license.","p":"Right. Under 21, you hold the permit at least 180 days."},"es":{"q":"En Kentucky, ¿cuánto tiempo debe tener el permiso de instrucción un conductor menor de 21 años antes de solicitar la licencia?","o":["Por lo menos 30 días","Por lo menos 60 días","Por lo menos un año","Por lo menos 180 días"],"h1":"Son unos seis meses.","h2":"En Kentucky, un conductor menor de 21 años debe tener el permiso de instrucción por lo menos 180 días, unos seis meses, antes de solicitar la licencia.","p":"Correcto. Si es menor de 21, debe tener el permiso por lo menos 180 días."},"zh":{"q":"在 Kentucky，21 岁以下的司机必须持有学习驾照多久，才能申请驾照？","o":["至少 30 天","至少 60 天","至少一年","至少 180 天"],"h1":"大约是六个月。","h2":"在 Kentucky，21 岁以下的司机必须持有学习驾照至少 180 天，大约六个月，才能申请驾照。","p":"对。21 岁以下，学习驾照至少要持有 180 天。"},"vi":{"q":"Ở Kentucky, người lái dưới 21 tuổi phải giữ giấy phép tập lái bao lâu trước khi xin bằng lái?","o":["Ít nhất 30 ngày","Ít nhất 60 ngày","Ít nhất một năm","Ít nhất 180 ngày"],"h1":"Khoảng sáu tháng.","h2":"Ở Kentucky, người lái dưới 21 tuổi phải giữ giấy phép tập lái ít nhất 180 ngày, khoảng sáu tháng, trước khi xin bằng lái.","p":"Đúng. Dưới 21 tuổi, bạn giữ giấy phép tập lái ít nhất 180 ngày."},"tl":{"q":"Sa Kentucky, gaano katagal dapat hawak ng drayber na wala pang 21 ang instruction permit bago mag-apply ng lisensya?","o":["Hindi bababa sa 30 araw","Hindi bababa sa 60 araw","Hindi bababa sa isang taon","Hindi bababa sa 180 araw"],"h1":"Mga anim na buwan ito.","h2":"Sa Kentucky, ang drayber na wala pang 21 ay dapat humawak ng instruction permit nang hindi bababa sa 180 araw, mga anim na buwan, bago mag-apply ng lisensya.","p":"Tama. Kung wala ka pang 21, hawak mo ang permit nang hindi bababa sa 180 araw."},"ar":{"q":"في Kentucky، كم مدة يجب أن يحمل السائق الذي عمره أقل من 21 سنة تصريح التعلّم قبل أن يطلب رخصة القيادة؟","o":["30 يومًا على الأقل","60 يومًا على الأقل","سنة واحدة على الأقل","180 يومًا على الأقل"],"h1":"المدة حوالي ستة أشهر.","h2":"في Kentucky يجب أن يحمل السائق الذي عمره أقل من 21 سنة تصريح التعلّم 180 يومًا على الأقل، أي حوالي ستة أشهر، قبل أن يطلب رخصة القيادة.","p":"صحيح. إذا كان عمرك أقل من 21 سنة، تحمل التصريح 180 يومًا على الأقل."},"ref":{"doc":"KY","page":5}},{"id":"ky-003","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, how long must a permit holder who is 21 or older hold the permit before the road test?","o":["At least 30 days","At least 180 days","At least 7 days","At least one year"],"h1":"Adults wait much less than teens. It is about one month.","h2":"A Kentucky permit holder who is 21 or older must hold the permit for at least 30 days, much less than the 180 days for younger drivers.","p":"Right. Drivers 21 and older wait at least 30 days."},"es":{"q":"En Kentucky, ¿cuánto tiempo debe tener el permiso una persona de 21 años o más antes del examen de manejo?","o":["Por lo menos 30 días","Por lo menos 180 días","Por lo menos 7 días","Por lo menos un año"],"h1":"Los adultos esperan mucho menos que los jóvenes. Es como un mes.","h2":"En Kentucky, una persona de 21 años o más debe tener el permiso por lo menos 30 días, mucho menos que los 180 días de los conductores más jóvenes.","p":"Correcto. Las personas de 21 años o más esperan por lo menos 30 días."},"zh":{"q":"在 Kentucky，21 岁或以上持学习驾照的人，必须持有学习驾照多久才能参加路考？","o":["至少 30 天","至少 180 天","至少 7 天","至少一年"],"h1":"成年人要等的时间比青少年短很多。大约是一个月。","h2":"在 Kentucky，21 岁或以上持学习驾照的人，必须持有学习驾照至少 30 天，比年轻司机的 180 天短很多。","p":"对。21 岁及以上的司机至少要等 30 天。"},"vi":{"q":"Ở Kentucky, người có giấy phép tập lái từ 21 tuổi trở lên phải giữ giấy phép bao lâu trước khi thi lái xe?","o":["Ít nhất 30 ngày","Ít nhất 180 ngày","Ít nhất 7 ngày","Ít nhất một năm"],"h1":"Người lớn chờ ít hơn nhiều so với thiếu niên. Khoảng một tháng.","h2":"Ở Kentucky, người có giấy phép tập lái từ 21 tuổi trở lên phải giữ giấy phép ít nhất 30 ngày, ít hơn nhiều so với 180 ngày của người lái trẻ hơn.","p":"Đúng. Người lái từ 21 tuổi trở lên chờ ít nhất 30 ngày."},"tl":{"q":"Sa Kentucky, gaano katagal dapat hawak ng may permit na 21 taong gulang pataas ang permit bago ang road test?","o":["Hindi bababa sa 30 araw","Hindi bababa sa 180 araw","Hindi bababa sa 7 araw","Hindi bababa sa isang taon"],"h1":"Mas maikli ang hinihintay ng matatanda kaysa sa mga tinedyer. Mga isang buwan ito.","h2":"Sa Kentucky, ang may permit na 21 taong gulang pataas ay dapat humawak ng permit nang hindi bababa sa 30 araw, mas maikli kaysa sa 180 araw para sa mas batang drayber.","p":"Tama. Ang mga drayber na 21 pataas ay naghihintay nang hindi bababa sa 30 araw."},"ar":{"q":"في Kentucky، كم مدة يجب أن يحمل صاحب التصريح الذي عمره 21 سنة أو أكثر التصريح قبل اختبار القيادة على الطريق؟","o":["30 يومًا على الأقل","180 يومًا على الأقل","7 أيام على الأقل","سنة واحدة على الأقل"],"h1":"الكبار ينتظرون أقل بكثير من المراهقين. المدة حوالي شهر.","h2":"في Kentucky يجب أن يحمل صاحب التصريح الذي عمره 21 سنة أو أكثر التصريح 30 يومًا على الأقل، وهذا أقل بكثير من 180 يومًا للسائقين الأصغر سنًا.","p":"صحيح. السائقون بعمر 21 سنة أو أكثر ينتظرون 30 يومًا على الأقل."},"ref":{"doc":"KY","page":9}},{"id":"ky-004","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, what is the youngest age to get an intermediate license?","o":["15 years old","17 years old","16 years old","18 years old"],"h1":"It is one year after the youngest permit age.","h2":"You must be at least 16 to get a Kentucky intermediate license, even if you got your permit at 15.","p":"Right. The intermediate license starts at 16."},"es":{"q":"En Kentucky, ¿cuál es la edad mínima para obtener una licencia intermedia?","o":["15 años","17 años","16 años","18 años"],"h1":"Es un año después de la edad mínima del permiso.","h2":"Usted debe tener por lo menos 16 años para obtener una licencia intermedia en Kentucky, aunque haya sacado el permiso a los 15.","p":"Correcto. La licencia intermedia empieza a los 16."},"zh":{"q":"在 Kentucky，最小几岁可以拿到中级驾照（intermediate license）？","o":["15 岁","17 岁","16 岁","18 岁"],"h1":"比拿学习驾照的最小年龄晚一年。","h2":"在 Kentucky，你必须至少 16 岁才能拿到中级驾照，就算你 15 岁就拿到了学习驾照也一样。","p":"对。中级驾照从 16 岁开始。"},"vi":{"q":"Ở Kentucky, tuổi nhỏ nhất để được cấp bằng lái trung cấp (intermediate license) là bao nhiêu?","o":["15 tuổi","17 tuổi","16 tuổi","18 tuổi"],"h1":"Một năm sau tuổi nhỏ nhất để có giấy phép tập lái.","h2":"Bạn phải ít nhất 16 tuổi để được cấp bằng lái trung cấp ở Kentucky, dù bạn đã có giấy phép tập lái từ 15 tuổi.","p":"Đúng. Bằng lái trung cấp bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Kentucky, ano ang pinakabatang edad para makakuha ng intermediate license (pansamantalang lisensya)?","o":["15 taong gulang","17 taong gulang","16 taong gulang","18 taong gulang"],"h1":"Isang taon ito pagkatapos ng pinakabatang edad para sa permit.","h2":"Dapat ay hindi bababa sa 16 taong gulang ka para makakuha ng Kentucky intermediate license, kahit nakuha mo ang permit sa edad na 15.","p":"Tama. Nagsisimula ang intermediate license sa edad na 16."},"ar":{"q":"في Kentucky، ما أصغر عمر للحصول على الرخصة المتوسطة (intermediate license)؟","o":["15 سنة","17 سنة","16 سنة","18 سنة"],"h1":"العمر بعد سنة واحدة من أصغر عمر للحصول على التصريح.","h2":"يجب أن يكون عمرك 16 سنة على الأقل للحصول على الرخصة المتوسطة في Kentucky، حتى لو حصلت على التصريح في عمر 15 سنة.","p":"صحيح. الرخصة المتوسطة تبدأ من عمر 16 سنة."},"ref":{"doc":"KY","page":null}},{"id":"ky-005","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, how many hours of supervised driving must a teen complete before the road test?","o":["30 hours","60 hours","40 hours","100 hours"],"h1":"It is more than 50 and less than 70.","h2":"A Kentucky teen must complete 60 hours of supervised driving before the road test.","p":"Right. Kentucky asks for 60 supervised hours."},"es":{"q":"En Kentucky, ¿cuántas horas de manejo supervisado debe completar un joven antes del examen de manejo?","o":["30 horas","60 horas","40 horas","100 horas"],"h1":"Son más de 50 y menos de 70.","h2":"En Kentucky, un joven debe completar 60 horas de manejo supervisado antes del examen de manejo.","p":"Correcto. Kentucky pide 60 horas supervisadas."},"zh":{"q":"在 Kentucky，青少年在路考前必须完成多少小时有人陪同的驾驶？","o":["30 小时","60 小时","40 小时","100 小时"],"h1":"比 50 多，比 70 少。","h2":"Kentucky 的青少年在路考前必须完成 60 小时有人陪同的驾驶。","p":"对。Kentucky 要求 60 小时有人陪同的驾驶。"},"vi":{"q":"Ở Kentucky, thiếu niên phải lái xe có người giám sát bao nhiêu giờ trước khi thi lái xe?","o":["30 giờ","60 giờ","40 giờ","100 giờ"],"h1":"Nhiều hơn 50 và ít hơn 70.","h2":"Ở Kentucky, thiếu niên phải hoàn thành 60 giờ lái xe có người giám sát trước khi thi lái xe.","p":"Đúng. Kentucky yêu cầu 60 giờ có người giám sát."},"tl":{"q":"Sa Kentucky, ilang oras ng pagmamaneho na may gumagabay ang dapat tapusin ng tinedyer bago ang road test?","o":["30 oras","60 oras","40 oras","100 oras"],"h1":"Higit sa 50 at mas mababa sa 70.","h2":"Sa Kentucky, dapat tapusin ng tinedyer ang 60 oras ng pagmamaneho na may gumagabay bago ang road test.","p":"Tama. Humihingi ang Kentucky ng 60 oras na may gumagabay."},"ar":{"q":"في Kentucky، كم ساعة من القيادة تحت الإشراف يجب أن يكملها المراهق قبل اختبار القيادة على الطريق؟","o":["30 ساعة","60 ساعة","40 ساعة","100 ساعة"],"h1":"العدد أكثر من 50 وأقل من 70.","h2":"في Kentucky يجب أن يكمل المراهق 60 ساعة من القيادة تحت الإشراف قبل اختبار القيادة على الطريق.","p":"صحيح. تطلب Kentucky 60 ساعة تحت الإشراف."},"ref":{"doc":"KY","page":5}},{"id":"ky-006","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, how many of the supervised practice hours must be at night?","o":["5 hours","15 hours","20 hours","10 hours"],"h1":"It is one sixth of the 60 hours.","h2":"At least 10 of the 60 supervised hours in Kentucky must be driven at night.","p":"Right. Ten of the hours are at night."},"es":{"q":"En Kentucky, ¿cuántas de las horas de práctica supervisada deben ser de noche?","o":["5 horas","15 horas","20 horas","10 horas"],"h1":"Es la sexta parte de las 60 horas.","h2":"En Kentucky, por lo menos 10 de las 60 horas supervisadas deben ser de noche.","p":"Correcto. Diez de las horas son de noche."},"zh":{"q":"在 Kentucky，有人陪同的练习时间中，必须有多少小时是在夜间？","o":["5 小时","15 小时","20 小时","10 小时"],"h1":"是 60 小时的六分之一。","h2":"在 Kentucky，60 小时有人陪同的驾驶中，至少 10 小时必须在夜间开。","p":"对。其中十个小时是在夜间。"},"vi":{"q":"Ở Kentucky, bao nhiêu giờ trong số giờ tập lái có người giám sát phải là vào ban đêm?","o":["5 giờ","15 giờ","20 giờ","10 giờ"],"h1":"Đó là một phần sáu của 60 giờ.","h2":"Ở Kentucky, ít nhất 10 trong số 60 giờ lái xe có người giám sát phải là vào ban đêm.","p":"Đúng. Mười giờ phải là vào ban đêm."},"tl":{"q":"Sa Kentucky, ilan sa mga oras ng pagsasanay na may gumagabay ang dapat sa gabi?","o":["5 oras","15 oras","20 oras","10 oras"],"h1":"Isang-ikaanim ito ng 60 oras.","h2":"Sa Kentucky, hindi bababa sa 10 sa 60 oras na may gumagabay ang dapat imaneho sa gabi.","p":"Tama. Sampu sa mga oras ay sa gabi."},"ar":{"q":"في Kentucky، كم ساعة من ساعات التدريب تحت الإشراف يجب أن تكون في الليل؟","o":["5 ساعات","15 ساعة","20 ساعة","10 ساعات"],"h1":"العدد هو سُدس الـ 60 ساعة.","h2":"في Kentucky يجب أن تكون 10 ساعات على الأقل من الـ 60 ساعة تحت الإشراف قيادةً في الليل.","p":"صحيح. عشر ساعات تكون في الليل."},"ref":{"doc":"KY","page":5}},{"id":"ky-007","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, how old must the licensed driver beside a permit holder be?","o":["At least 21","At least 16","At least 18","At least 25"],"h1":"The helper must be old enough to drink alcohol legally.","h2":"A Kentucky permit holder must drive with a licensed person who is at least 21, sitting in the seat beside them.","p":"Right. The person beside you must be 21 or older."},"es":{"q":"En Kentucky, ¿qué edad debe tener el conductor con licencia que va al lado de quien tiene permiso?","o":["Por lo menos 21","Por lo menos 16","Por lo menos 18","Por lo menos 25"],"h1":"El acompañante debe tener edad para tomar alcohol legalmente.","h2":"En Kentucky, quien tiene permiso debe manejar con una persona con licencia de por lo menos 21 años, sentada a su lado.","p":"Correcto. Su acompañante debe tener 21 años o más."},"zh":{"q":"在 Kentucky，坐在持学习驾照的人旁边、有驾照的司机必须几岁？","o":["至少 21 岁","至少 16 岁","至少 18 岁","至少 25 岁"],"h1":"陪同的人必须到了可以合法喝酒的年龄。","h2":"在 Kentucky，持学习驾照的人必须和一位至少 21 岁、有驾照的人一起开车，这个人坐在旁边的座位上。","p":"对。坐在你旁边的人必须 21 岁或以上。"},"vi":{"q":"Ở Kentucky, người có bằng lái ngồi bên cạnh người có giấy phép tập lái phải bao nhiêu tuổi?","o":["Ít nhất 21 tuổi","Ít nhất 16 tuổi","Ít nhất 18 tuổi","Ít nhất 25 tuổi"],"h1":"Người hướng dẫn phải đủ tuổi để uống rượu bia hợp pháp.","h2":"Ở Kentucky, người có giấy phép tập lái phải lái cùng một người có bằng lái ít nhất 21 tuổi, ngồi ở ghế bên cạnh.","p":"Đúng. Người ngồi bên cạnh bạn phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Kentucky, ilang taon dapat ang may lisensyang drayber na katabi ng may permit?","o":["Hindi bababa sa 21","Hindi bababa sa 16","Hindi bababa sa 18","Hindi bababa sa 25"],"h1":"Dapat ay nasa legal na edad ang katulong para uminom ng alak.","h2":"Sa Kentucky, ang may permit ay dapat magmaneho kasama ang isang may lisensya na hindi bababa sa 21 taong gulang, na nakaupo sa upuang katabi niya.","p":"Tama. Ang katabi mo ay dapat 21 taong gulang pataas."},"ar":{"q":"في Kentucky، كم يجب أن يكون عمر السائق المرخَّص الذي يجلس بجانب صاحب التصريح؟","o":["21 سنة على الأقل","16 سنة على الأقل","18 سنة على الأقل","25 سنة على الأقل"],"h1":"يجب أن يكون المرافق في عمر يسمح له قانونيًا بشرب الكحول.","h2":"في Kentucky يجب أن يقود صاحب التصريح مع شخص مرخَّص عمره 21 سنة على الأقل، يجلس في المقعد الذي بجانبه.","p":"صحيح. الشخص الذي بجانبك يجب أن يكون عمره 21 سنة أو أكثر."},"ref":{"doc":"KY","page":5}},{"id":"ky-008","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, how does a teen show that the supervised practice hours were completed?","o":["With a note from a friend","With photos from a phone","With a practice driving log signed by a parent or guardian","Nothing is needed"],"h1":"It is a written record that a parent signs.","h2":"In Kentucky a parent or guardian signs a practice driving log that lists the 60 hours, and it is needed before the road test.","p":"Right. A practice driving log signed by a parent is needed."},"es":{"q":"En Kentucky, ¿cómo demuestra un joven que completó las horas de práctica supervisada?","o":["Con una nota de un amigo","Con fotos del teléfono","Con un registro de práctica firmado por un padre, madre o tutor","No se necesita nada"],"h1":"Es un registro escrito que firma un padre o una madre.","h2":"En Kentucky, un padre, madre o tutor firma un registro de práctica de manejo con las 60 horas, y se necesita antes del examen de manejo.","p":"Correcto. Se necesita un registro de práctica firmado por un padre o tutor."},"zh":{"q":"在 Kentucky，青少年怎样证明已经完成了有人陪同的练习时间？","o":["用朋友写的字条","用手机里的照片","用父母或监护人签字的练车记录","什么都不需要"],"h1":"这是父母签字的书面记录。","h2":"在 Kentucky，父母或监护人要在列出 60 小时的练车记录上签字，路考前需要这份记录。","p":"对。需要一份父母签字的练车记录。"},"vi":{"q":"Ở Kentucky, thiếu niên chứng minh đã hoàn thành số giờ tập lái có người giám sát bằng cách nào?","o":["Bằng một tờ giấy của bạn bè","Bằng ảnh chụp trên điện thoại","Bằng sổ ghi giờ tập lái có chữ ký của cha mẹ hoặc người giám hộ","Không cần gì cả"],"h1":"Đó là một bản ghi chép mà cha mẹ ký tên.","h2":"Ở Kentucky, cha mẹ hoặc người giám hộ ký vào sổ ghi giờ tập lái liệt kê 60 giờ, và sổ này cần có trước khi thi lái xe.","p":"Đúng. Cần có sổ ghi giờ tập lái có chữ ký của cha mẹ."},"tl":{"q":"Sa Kentucky, paano ipinapakita ng tinedyer na natapos niya ang mga oras ng pagsasanay na may gumagabay?","o":["Sa sulat mula sa isang kaibigan","Sa mga litrato mula sa telepono","Sa practice driving log (talaan ng pagsasanay) na pinirmahan ng magulang o tagapag-alaga","Walang kailangan"],"h1":"Isa itong nakasulat na talaan na pinipirmahan ng magulang.","h2":"Sa Kentucky, pumipirma ang magulang o tagapag-alaga sa practice driving log na naglilista ng 60 oras, at kailangan ito bago ang road test.","p":"Tama. Kailangan ang practice driving log na pinirmahan ng magulang."},"ar":{"q":"في Kentucky، كيف يُثبت المراهق أنه أكمل ساعات التدريب تحت الإشراف؟","o":["بورقة من صديق","بصور من الهاتف","بسجل تدريب على القيادة (practice driving log) موقَّع من أحد الوالدين أو الوصي","لا يلزم أي شيء"],"h1":"هو سجل مكتوب يوقّعه أحد الوالدين.","h2":"في Kentucky يوقّع أحد الوالدين أو الوصي على سجل تدريب على القيادة يذكر الـ 60 ساعة، وهذا السجل مطلوب قبل اختبار القيادة على الطريق.","p":"صحيح. سجل التدريب الموقَّع من أحد الوالدين مطلوب."},"ref":{"doc":"KY","page":6}},{"id":"ky-009","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, when may a driver under 18 with an intermediate license not drive without good cause?","o":["Between 9 p.m. and 5 a.m.","Between midnight and 6 a.m.","Between 10 p.m. and 6 a.m.","Between 11 p.m. and 5 a.m."],"h1":"It starts at midnight.","h2":"A Kentucky intermediate license holder under 18 may not drive between midnight and 6 a.m. unless there is good cause, such as school, work or an emergency.","p":"Right. No driving from midnight to 6 a.m. without good cause."},"es":{"q":"En Kentucky, ¿en qué horario no puede manejar sin un buen motivo un menor de 18 años con licencia intermedia?","o":["Entre las 9 p.m. y las 5 a.m.","Entre la medianoche y las 6 a.m.","Entre las 10 p.m. y las 6 a.m.","Entre las 11 p.m. y las 5 a.m."],"h1":"Empieza a la medianoche.","h2":"En Kentucky, quien tiene licencia intermedia y es menor de 18 años no puede manejar entre la medianoche y las 6 a.m., salvo por un buen motivo como la escuela, el trabajo o una emergencia.","p":"Correcto. No se maneja de medianoche a 6 a.m. sin un buen motivo."},"zh":{"q":"在 Kentucky，18 岁以下、持中级驾照的司机，在没有正当理由时，什么时间不能开车？","o":["晚上 9 点到早上 5 点之间","午夜到早上 6 点之间","晚上 10 点到早上 6 点之间","晚上 11 点到早上 5 点之间"],"h1":"它从午夜开始。","h2":"在 Kentucky，18 岁以下、持中级驾照的人，在午夜到早上 6 点之间不能开车，除非有正当理由，例如上学、上班或紧急情况。","p":"对。没有正当理由，午夜到早上 6 点不能开车。"},"vi":{"q":"Ở Kentucky, người lái dưới 18 tuổi có bằng lái trung cấp không được lái xe vào giờ nào nếu không có lý do chính đáng?","o":["Từ 9 giờ tối đến 5 giờ sáng","Từ nửa đêm đến 6 giờ sáng","Từ 10 giờ tối đến 6 giờ sáng","Từ 11 giờ tối đến 5 giờ sáng"],"h1":"Bắt đầu từ nửa đêm.","h2":"Ở Kentucky, người có bằng lái trung cấp dưới 18 tuổi không được lái xe từ nửa đêm đến 6 giờ sáng, trừ khi có lý do chính đáng như đi học, đi làm hoặc trường hợp khẩn cấp.","p":"Đúng. Không lái xe từ nửa đêm đến 6 giờ sáng nếu không có lý do chính đáng."},"tl":{"q":"Sa Kentucky, kailan hindi maaaring magmaneho nang walang mabuting dahilan ang drayber na wala pang 18 na may intermediate license?","o":["Mula 9 p.m. hanggang 5 a.m.","Mula hatinggabi hanggang 6 a.m.","Mula 10 p.m. hanggang 6 a.m.","Mula 11 p.m. hanggang 5 a.m."],"h1":"Nagsisimula ito sa hatinggabi.","h2":"Sa Kentucky, ang may intermediate license na wala pang 18 ay hindi maaaring magmaneho mula hatinggabi hanggang 6 a.m. maliban kung may mabuting dahilan, gaya ng paaralan, trabaho o emergency.","p":"Tama. Walang pagmamaneho mula hatinggabi hanggang 6 a.m. nang walang mabuting dahilan."},"ar":{"q":"في Kentucky، متى لا يجوز للسائق الذي عمره أقل من 18 سنة ويحمل رخصة متوسطة أن يقود بدون سبب وجيه؟","o":["من 9 مساءً إلى 5 صباحًا","من منتصف الليل إلى 6 صباحًا","من 10 مساءً إلى 6 صباحًا","من 11 مساءً إلى 5 صباحًا"],"h1":"يبدأ من منتصف الليل.","h2":"في Kentucky لا يجوز لحامل الرخصة المتوسطة الذي عمره أقل من 18 سنة أن يقود من منتصف الليل إلى 6 صباحًا إلا بسبب وجيه، مثل المدرسة أو العمل أو حالة طارئة.","p":"صحيح. لا قيادة من منتصف الليل إلى 6 صباحًا بدون سبب وجيه."},"ref":{"doc":"KY","page":6}},{"id":"ky-010","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, how many unrelated passengers under 20 may an intermediate license holder carry?","o":["None at all","No more than two","No more than three","No more than one"],"h1":"It is the smallest number that is not zero.","h2":"A Kentucky intermediate license holder may carry no more than one unrelated passenger under 20, unless a driving instructor is in the car.","p":"Right. Only one unrelated passenger under 20."},"es":{"q":"En Kentucky, ¿cuántos pasajeros menores de 20 años que no son familiares puede llevar quien tiene licencia intermedia?","o":["Ninguno","No más de dos","No más de tres","No más de uno"],"h1":"Es el número más pequeño que no es cero.","h2":"En Kentucky, quien tiene licencia intermedia puede llevar no más de un pasajero menor de 20 años que no sea familiar, salvo que vaya un instructor de manejo en el auto.","p":"Correcto. Solo un pasajero menor de 20 que no sea familiar."},"zh":{"q":"在 Kentucky，持中级驾照的人可以载几个不是亲属、20 岁以下的乘客？","o":["一个都不可以","最多两个","最多三个","最多一个"],"h1":"是不等于零的最小的数。","h2":"在 Kentucky，持中级驾照的人最多只能载一个不是亲属、20 岁以下的乘客，除非车上有驾驶教练。","p":"对。只能载一个不是亲属、20 岁以下的乘客。"},"vi":{"q":"Ở Kentucky, người có bằng lái trung cấp được chở bao nhiêu hành khách dưới 20 tuổi không phải người thân?","o":["Không được chở ai","Không quá hai người","Không quá ba người","Không quá một người"],"h1":"Đó là số nhỏ nhất mà không phải là số không.","h2":"Ở Kentucky, người có bằng lái trung cấp được chở không quá một hành khách dưới 20 tuổi không phải người thân, trừ khi có giáo viên dạy lái xe trong xe.","p":"Đúng. Chỉ một hành khách dưới 20 tuổi không phải người thân."},"tl":{"q":"Sa Kentucky, ilang pasaherong wala pang 20 na hindi kamag-anak ang maaaring isakay ng may intermediate license?","o":["Wala talaga","Hindi hihigit sa dalawa","Hindi hihigit sa tatlo","Hindi hihigit sa isa"],"h1":"Ito ang pinakamaliit na bilang na hindi zero.","h2":"Sa Kentucky, ang may intermediate license ay maaaring magsakay ng hindi hihigit sa isang pasaherong wala pang 20 na hindi kamag-anak, maliban kung may driving instructor sa sasakyan.","p":"Tama. Isang pasahero lang na wala pang 20 na hindi kamag-anak."},"ar":{"q":"في Kentucky، كم راكبًا عمره أقل من 20 سنة وليس من الأقارب يجوز لحامل الرخصة المتوسطة أن ينقله؟","o":["لا أحد أبدًا","ليس أكثر من اثنين","ليس أكثر من ثلاثة","ليس أكثر من واحد"],"h1":"هو أصغر عدد ليس صفرًا.","h2":"في Kentucky يجوز لحامل الرخصة المتوسطة أن ينقل راكبًا واحدًا فقط عمره أقل من 20 سنة وليس من الأقارب، إلا إذا كان مدرّب القيادة في السيارة.","p":"صحيح. راكب واحد فقط عمره أقل من 20 سنة وليس من الأقارب."},"ref":{"doc":"KY","page":7}},{"id":"ky-011","scope":"KY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kentucky, when may a driver under 18 use a phone while the car is moving?","o":["Only to report an emergency","When using a hands-free device","When stopped at a red light only","Any time on a highway"],"h1":"The law has no hands-free exception for this age group.","h2":"A Kentucky driver under 18 may not use a phone at all while the car is moving, hands-free included, except to report an emergency.","p":"Right. Under 18, the phone is only for emergencies."},"es":{"q":"En Kentucky, ¿cuándo puede usar el teléfono un conductor menor de 18 años mientras el auto está en movimiento?","o":["Solo para reportar una emergencia","Cuando usa un dispositivo de manos libres","Solo cuando está parado en un semáforo en rojo","En cualquier momento en la autopista"],"h1":"La ley no hace excepción para el manos libres a esta edad.","h2":"En Kentucky, un conductor menor de 18 años no puede usar el teléfono mientras el auto está en movimiento, ni siquiera con manos libres, salvo para reportar una emergencia.","p":"Correcto. Si es menor de 18, el teléfono es solo para emergencias."},"zh":{"q":"在 Kentucky，18 岁以下的司机在车子行驶时，什么时候可以用手机？","o":["只能报告紧急情况","用免提设备时","只有在红灯前停着时","在高速公路上任何时候"],"h1":"对这个年龄的人，法律没有免提的例外。","h2":"在 Kentucky，18 岁以下的司机在车子行驶时完全不能用手机，包括免提，只有报告紧急情况除外。","p":"对。18 岁以下，手机只能用在紧急情况。"},"vi":{"q":"Ở Kentucky, khi nào người lái dưới 18 tuổi được dùng điện thoại lúc xe đang chạy?","o":["Chỉ để báo trường hợp khẩn cấp","Khi dùng thiết bị rảnh tay","Chỉ khi dừng ở đèn đỏ","Bất cứ lúc nào trên xa lộ"],"h1":"Luật không cho phép dùng thiết bị rảnh tay ở độ tuổi này.","h2":"Ở Kentucky, người lái dưới 18 tuổi hoàn toàn không được dùng điện thoại khi xe đang chạy, kể cả rảnh tay, trừ khi để báo trường hợp khẩn cấp.","p":"Đúng. Dưới 18 tuổi, điện thoại chỉ dùng cho trường hợp khẩn cấp."},"tl":{"q":"Sa Kentucky, kailan maaaring gumamit ng telepono ang drayber na wala pang 18 habang umaandar ang sasakyan?","o":["Para lang mag-ulat ng emergency","Kapag gumagamit ng hands-free na device","Kapag nakahinto lang sa pulang ilaw","Anumang oras sa highway"],"h1":"Walang eksepsiyon para sa hands-free sa batas para sa edad na ito.","h2":"Sa Kentucky, ang drayber na wala pang 18 ay hindi maaaring gumamit ng telepono habang umaandar ang sasakyan, kasama ang hands-free, maliban para mag-ulat ng emergency.","p":"Tama. Kung wala ka pang 18, para lang sa emergency ang telepono."},"ar":{"q":"في Kentucky، متى يجوز للسائق الذي عمره أقل من 18 سنة أن يستخدم الهاتف أثناء سير السيارة؟","o":["فقط للإبلاغ عن حالة طارئة","عند استخدام جهاز بدون يدين (hands-free)","فقط عند التوقف عند الإشارة الحمراء","في أي وقت على الطريق السريع"],"h1":"القانون لا يستثني الأجهزة بدون يدين لهذه الفئة العمرية.","h2":"في Kentucky لا يجوز للسائق الذي عمره أقل من 18 سنة أن يستخدم الهاتف أبدًا أثناء سير السيارة، حتى بدون يدين، إلا للإبلاغ عن حالة طارئة.","p":"صحيح. إذا كان عمرك أقل من 18 سنة، الهاتف للحالات الطارئة فقط."},"ref":{"doc":"KY","page":null}},{"id":"ky-012","scope":"KY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Kentucky, at what blood alcohol level is a driver under 21 breaking the law?","o":["0.05 percent","0.08 percent","0.02 percent","0.10 percent"],"h1":"Kentucky calls this zero tolerance. It is the smallest number here.","h2":"A Kentucky driver under 21 breaks the zero tolerance law with a blood alcohol level of 0.02 percent.","p":"Right. Under 21, the limit is 0.02 percent."},"es":{"q":"En Kentucky, ¿con qué nivel de alcohol en la sangre viola la ley un conductor menor de 21 años?","o":["0.05 por ciento","0.08 por ciento","0.02 por ciento","0.10 por ciento"],"h1":"Kentucky lo llama tolerancia cero. Es el número más pequeño.","h2":"En Kentucky, un conductor menor de 21 años viola la ley de tolerancia cero con un nivel de alcohol en la sangre de 0.02 por ciento.","p":"Correcto. Si es menor de 21, el límite es 0.02 por ciento."},"zh":{"q":"在 Kentucky，21 岁以下的司机血液酒精浓度达到多少就违法？","o":["0.05%","0.08%","0.02%","0.10%"],"h1":"Kentucky 把这个叫做零容忍。它是这里最小的数字。","h2":"在 Kentucky，21 岁以下的司机血液酒精浓度达到 0.02%，就违反了零容忍法。","p":"对。21 岁以下，上限是 0.02%。"},"vi":{"q":"Ở Kentucky, người lái dưới 21 tuổi vi phạm luật khi nồng độ cồn trong máu ở mức nào?","o":["0.05 phần trăm","0.08 phần trăm","0.02 phần trăm","0.10 phần trăm"],"h1":"Kentucky gọi đây là không khoan nhượng (zero tolerance). Đó là con số nhỏ nhất ở đây.","h2":"Ở Kentucky, người lái dưới 21 tuổi vi phạm luật không khoan nhượng (zero tolerance) khi nồng độ cồn trong máu là 0.02 phần trăm.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02 phần trăm."},"tl":{"q":"Sa Kentucky, sa anong antas ng alak sa dugo lumalabag sa batas ang drayber na wala pang 21?","o":["0.05 porsiyento","0.08 porsiyento","0.02 porsiyento","0.10 porsiyento"],"h1":"Tinatawag ito ng Kentucky na zero tolerance. Ito ang pinakamaliit na bilang dito.","h2":"Sa Kentucky, ang drayber na wala pang 21 ay lumalabag sa zero tolerance law kapag 0.02 porsiyento ang antas ng alak sa dugo.","p":"Tama. Kung wala ka pang 21, ang hangganan ay 0.02 porsiyento."},"ar":{"q":"في Kentucky، عند أي نسبة كحول في الدم يخالف السائق الذي عمره أقل من 21 سنة القانون؟","o":["0.05 بالمئة","0.08 بالمئة","0.02 بالمئة","0.10 بالمئة"],"h1":"تسمّي Kentucky هذا عدم التسامح مطلقًا (zero tolerance). إنه أصغر رقم هنا.","h2":"في Kentucky يخالف السائق الذي عمره أقل من 21 سنة قانون عدم التسامح مطلقًا (zero tolerance) عندما تكون نسبة الكحول في دمه 0.02 بالمئة.","p":"صحيح. إذا كان عمرك أقل من 21 سنة، الحد هو 0.02 بالمئة."},"ref":{"doc":"KY","page":26}},{"id":"ky-013","scope":"KY","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Kentucky, what must you do when you approach a stopped emergency vehicle with flashing lights on the side of the road?","o":["Keep the same lane and speed","Move to the next lane away from it, or slow down if you cannot change lanes safely","Stop in your lane until it leaves","Honk to warn the workers"],"h1":"Give the workers more room, or go slower.","h2":"Kentucky law says to move to the lane away from a stopped emergency vehicle with flashing lights, and if that is not safe, to slow down and use caution.","p":"Right. Move over, or slow down."},"es":{"q":"En Kentucky, ¿qué debe hacer al acercarse a un vehículo de emergencia detenido al lado del camino con luces intermitentes?","o":["Seguir en el mismo carril y a la misma velocidad","Pasarse al carril de al lado, lejos de él, o bajar la velocidad si no puede cambiar de carril con seguridad","Detenerse en su carril hasta que se vaya","Tocar la bocina para avisar a los trabajadores"],"h1":"Dele más espacio a los trabajadores, o vaya más despacio.","h2":"La ley de Kentucky dice que debe pasarse al carril más lejano de un vehículo de emergencia detenido con luces intermitentes y, si no es seguro, bajar la velocidad con cuidado.","p":"Correcto. Cámbiese de carril o baje la velocidad."},"zh":{"q":"在 Kentucky，当你靠近一辆停在路边、闪着灯的急救车辆时，你必须做什么？","o":["保持原来的车道和速度","换到离它远一点的旁边车道，如果不能安全换道就减速","在你的车道停下，直到它离开","按喇叭提醒工作人员"],"h1":"给工作人员更多空间，或者开慢一点。","h2":"Kentucky 法律规定，要换到离停着、闪着灯的急救车辆远一点的车道；如果这样不安全，就要减速并小心驾驶。","p":"对。换道让开，或者减速。"},"vi":{"q":"Ở Kentucky, bạn phải làm gì khi đến gần một xe cấp cứu đang dừng bên đường và có đèn nhấp nháy?","o":["Giữ nguyên làn và tốc độ","Chuyển sang làn bên cạnh, xa xe đó, hoặc chạy chậm lại nếu không thể đổi làn an toàn","Dừng lại trong làn của bạn cho đến khi xe đó đi","Bấm còi để báo cho nhân viên"],"h1":"Chừa thêm chỗ cho nhân viên, hoặc chạy chậm hơn.","h2":"Luật Kentucky nói phải chuyển sang làn xa xe cấp cứu đang dừng có đèn nhấp nháy, và nếu không an toàn thì phải chạy chậm lại và cẩn thận.","p":"Đúng. Chuyển làn, hoặc chạy chậm lại."},"tl":{"q":"Sa Kentucky, ano ang dapat mong gawin kapag papalapit ka sa nakahintong emergency vehicle na may kumikislap na ilaw sa gilid ng kalsada?","o":["Manatili sa parehong lane at bilis","Lumipat sa katabing lane na malayo rito, o bumagal kung hindi ligtas lumipat ng lane","Huminto sa lane mo hanggang umalis ito","Bumusina para bigyan ng babala ang mga manggagawa"],"h1":"Bigyan ng mas maraming espasyo ang mga manggagawa, o bumagal.","h2":"Sinasabi ng batas ng Kentucky na lumipat sa lane na malayo sa nakahintong emergency vehicle na may kumikislap na ilaw, at kung hindi ligtas, bumagal at mag-ingat.","p":"Tama. Lumipat ng lane, o bumagal."},"ar":{"q":"في Kentucky، ماذا يجب أن تفعل عندما تقترب من مركبة طوارئ متوقفة على جانب الطريق وأضواؤها تومض؟","o":["ابقَ في نفس المسار وبنفس السرعة","انتقل إلى المسار المجاور البعيد عنها، أو خفّف السرعة إذا لم تستطع تغيير المسار بأمان","توقّف في مسارك حتى تغادر","استخدم البوق لتحذير العاملين"],"h1":"أعطِ العاملين مساحة أكبر، أو خفّف السرعة.","h2":"قانون Kentucky يقول أن تنتقل إلى المسار البعيد عن مركبة الطوارئ المتوقفة التي تومض أضواؤها، وإذا لم يكن ذلك آمنًا، أن تخفّف السرعة وتنتبه.","p":"صحيح. انتقل إلى مسار آخر، أو خفّف السرعة."},"ref":{"doc":"KY","page":66}},{"id":"ky-014","scope":"KY","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Kentucky, since July 2026, a school bus is stopped with its stop arm out on the other side of a four-lane road with no median. What must you do?","o":["Keep driving, because the road has four lanes","Slow down and pass with care","Honk and pass","Stop, even though you are going the other way"],"h1":"The old four-lane exception was narrowed in 2026.","h2":"Since a 2026 Kentucky law, you must stop for a stopped school bus even on a four-lane road, unless a raised barrier or an unpaved median separates you from it.","p":"Right. A four-lane road alone is no longer an exception."},"es":{"q":"En Kentucky, desde julio de 2026, un autobús escolar está detenido con el brazo de alto extendido al otro lado de un camino de cuatro carriles sin camellón. ¿Qué debe hacer?","o":["Seguir manejando, porque el camino tiene cuatro carriles","Bajar la velocidad y pasar con cuidado","Tocar la bocina y pasar","Detenerse, aunque usted vaya en la dirección contraria"],"h1":"La antigua excepción de los cuatro carriles se redujo en 2026.","h2":"Desde una ley de Kentucky de 2026, usted debe detenerse ante un autobús escolar detenido aun en un camino de cuatro carriles, salvo que lo separe una barrera elevada o un camellón sin pavimentar.","p":"Correcto. Que el camino tenga cuatro carriles ya no es una excepción."},"zh":{"q":"在 Kentucky，从 2026 年 7 月起，一辆校车伸出停车臂，停在没有隔离带的四车道道路的另一边。你必须做什么？","o":["继续开，因为这条路有四条车道","减速并小心地开过去","按喇叭然后开过去","停车，就算你是往另一个方向开"],"h1":"原来四车道的例外在 2026 年被缩小了。","h2":"根据 2026 年的 Kentucky 法律，就算在四车道的路上，你也必须为停着的校车停车，除非有凸起的隔离墩或没铺路面的隔离带把你和校车分开。","p":"对。只是四车道的路已经不再是例外了。"},"vi":{"q":"Ở Kentucky, từ tháng 7 năm 2026, một xe buýt trường học đang dừng và đưa biển STOP ra ở phía bên kia của đường bốn làn không có dải phân cách. Bạn phải làm gì?","o":["Tiếp tục chạy, vì đường có bốn làn","Chạy chậm lại và vượt qua cẩn thận","Bấm còi và vượt qua","Dừng lại, dù bạn đang đi theo hướng ngược lại"],"h1":"Ngoại lệ cũ cho đường bốn làn đã bị thu hẹp vào năm 2026.","h2":"Theo một luật năm 2026 của Kentucky, bạn phải dừng lại khi xe buýt trường học dừng, kể cả trên đường bốn làn, trừ khi có rào chắn nổi hoặc dải phân cách không trải nhựa ngăn cách bạn với xe buýt.","p":"Đúng. Chỉ đường bốn làn thôi thì không còn là ngoại lệ."},"tl":{"q":"Sa Kentucky, mula Hulyo 2026, may nakahintong school bus na nakalabas ang stop arm sa kabilang panig ng kalsadang may apat na lane at walang median. Ano ang dapat mong gawin?","o":["Magpatuloy sa pagmamaneho, dahil apat ang lane ng kalsada","Bumagal at dumaan nang maingat","Bumusina at dumaan","Huminto, kahit pasalungat ang direksyon mo"],"h1":"Pinakitid noong 2026 ang lumang eksepsiyon para sa kalsadang may apat na lane.","h2":"Dahil sa isang batas ng Kentucky noong 2026, dapat kang huminto para sa nakahintong school bus kahit sa kalsadang may apat na lane, maliban kung may nakaangat na harang o hindi sementadong median na naghihiwalay sa iyo rito.","p":"Tama. Ang kalsadang may apat na lane lang ay hindi na eksepsiyon."},"ar":{"q":"في Kentucky، منذ يوليو 2026، حافلة مدرسية متوقفة وذراع التوقف (stop arm) مفتوح على الجهة الأخرى من طريق بأربعة مسارات بدون فاصل في الوسط. ماذا يجب أن تفعل؟","o":["استمر في القيادة، لأن الطريق فيه أربعة مسارات","خفّف السرعة ومُرّ بحذر","استخدم البوق ومُرّ","توقّف، حتى لو كنت تسير في الاتجاه المعاكس"],"h1":"الاستثناء القديم للطرق ذات الأربعة مسارات أصبح أضيق في 2026.","h2":"منذ قانون Kentucky في 2026، يجب أن تتوقف للحافلة المدرسية المتوقفة حتى على طريق بأربعة مسارات، إلا إذا كان بينك وبينها حاجز مرتفع أو فاصل في الوسط غير معبَّد.","p":"صحيح. الطريق ذو الأربعة مسارات وحده لم يعد استثناءً."},"ref":{"doc":"KY","page":44}},{"id":"ky-015","scope":"KY","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Kentucky, when may traffic going the other way pass a stopped school bus without stopping?","o":["When a raised barrier or an unpaved median separates the two sides of the road","When the road has four lanes or more","When the bus has no children in sight","When the driver is in a hurry"],"h1":"Something physical must separate the two directions.","h2":"In Kentucky, traffic going the other way may pass a stopped school bus only when a raised barrier or an unpaved median separates the two sides of the road.","p":"Right. Only a barrier or an unpaved median makes it an exception."},"es":{"q":"En Kentucky, ¿cuándo puede el tráfico que va en dirección contraria pasar un autobús escolar detenido sin detenerse?","o":["Cuando una barrera elevada o un camellón sin pavimentar separa los dos lados del camino","Cuando el camino tiene cuatro carriles o más","Cuando no se ven niños cerca del autobús","Cuando el conductor tiene prisa"],"h1":"Algo físico debe separar las dos direcciones.","h2":"En Kentucky, el tráfico en dirección contraria puede pasar un autobús escolar detenido solo cuando una barrera elevada o un camellón sin pavimentar separa los dos lados del camino.","p":"Correcto. Solo una barrera o un camellón sin pavimentar es una excepción."},"zh":{"q":"在 Kentucky，对面方向的车什么时候可以不停车，开过停着的校车？","o":["当凸起的隔离墩或没铺路面的隔离带把道路两边分开时","当道路有四条或更多车道时","当看不到校车有小孩时","当司机赶时间时"],"h1":"必须有实际的东西把两个方向分开。","h2":"在 Kentucky，只有当凸起的隔离墩或没铺路面的隔离带把道路两边分开时，对面方向的车才可以开过停着的校车。","p":"对。只有隔离墩或没铺路面的隔离带才算例外。"},"vi":{"q":"Ở Kentucky, khi nào xe đi theo hướng ngược lại được vượt qua xe buýt trường học đang dừng mà không cần dừng lại?","o":["Khi có rào chắn nổi hoặc dải phân cách không trải nhựa ngăn cách hai bên đường","Khi đường có bốn làn trở lên","Khi không thấy trẻ em nào","Khi người lái đang vội"],"h1":"Phải có một vật cụ thể ngăn cách hai chiều xe chạy.","h2":"Ở Kentucky, xe đi theo hướng ngược lại chỉ được vượt qua xe buýt trường học đang dừng khi có rào chắn nổi hoặc dải phân cách không trải nhựa ngăn cách hai bên đường.","p":"Đúng. Chỉ rào chắn hoặc dải phân cách không trải nhựa mới là ngoại lệ."},"tl":{"q":"Sa Kentucky, kailan maaaring lampasan ng mga sasakyang pasalungat ang direksyon ang nakahintong school bus nang hindi humihinto?","o":["Kapag may nakaangat na harang o hindi sementadong median na naghihiwalay sa dalawang panig ng kalsada","Kapag may apat o higit pang lane ang kalsada","Kapag walang batang nakikita malapit sa bus","Kapag nagmamadali ang drayber"],"h1":"Dapat may pisikal na bagay na naghihiwalay sa dalawang direksyon.","h2":"Sa Kentucky, ang mga sasakyang pasalungat ang direksyon ay maaaring lumampas sa nakahintong school bus lamang kapag may nakaangat na harang o hindi sementadong median na naghihiwalay sa dalawang panig ng kalsada.","p":"Tama. Harang o hindi sementadong median lang ang eksepsiyon."},"ar":{"q":"في Kentucky، متى يجوز للسيارات القادمة من الاتجاه المعاكس أن تمرّ بجانب حافلة مدرسية متوقفة بدون أن تتوقف؟","o":["عندما يفصل حاجز مرتفع أو فاصل غير معبَّد في الوسط بين جهتي الطريق","عندما يكون في الطريق أربعة مسارات أو أكثر","عندما لا يُرى أي طفل قرب الحافلة","عندما يكون السائق مستعجلًا"],"h1":"يجب أن يفصل شيء مادي بين الاتجاهين.","h2":"في Kentucky يجوز للسيارات القادمة من الاتجاه المعاكس أن تمرّ بجانب حافلة مدرسية متوقفة فقط عندما يفصل حاجز مرتفع أو فاصل غير معبَّد في الوسط بين جهتي الطريق.","p":"صحيح. الحاجز أو الفاصل غير المعبَّد فقط هو الاستثناء."},"ref":{"doc":"KY","page":44}},{"id":"ky-016","scope":"KY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Kentucky, what is the usual speed limit on interstates when no other limit is posted for that section?","o":["55 mph","75 mph","65 mph","80 mph"],"h1":"Some rural sections are raised by 5 mph above this number.","h2":"Kentucky interstates are usually 65 mph, and some rural sections are posted at 70 mph after a safety study.","p":"Right. The usual interstate limit is 65 mph."},"es":{"q":"En Kentucky, ¿cuál es el límite de velocidad habitual en las autopistas interestatales cuando no hay otro límite para ese tramo?","o":["55 mph","75 mph","65 mph","80 mph"],"h1":"En algunos tramos rurales se sube 5 mph sobre este número.","h2":"Las autopistas interestatales de Kentucky suelen tener un límite de 65 mph, y algunos tramos rurales tienen 70 mph después de un estudio de seguridad.","p":"Correcto. El límite habitual en la interestatal es 65 mph."},"zh":{"q":"在 Kentucky，如果那一段路没有标示其他限速，州际公路一般的限速是多少？","o":["55 mph","75 mph","65 mph","80 mph"],"h1":"有些乡村路段比这个数字高 5 mph。","h2":"Kentucky 的州际公路一般限速是 65 mph，有些乡村路段经过安全研究后标示为 70 mph。","p":"对。州际公路一般限速是 65 mph。"},"vi":{"q":"Ở Kentucky, tốc độ tối đa thông thường trên xa lộ liên bang (interstate) là bao nhiêu khi không có biển báo tốc độ khác cho đoạn đường đó?","o":["55 mph","75 mph","65 mph","80 mph"],"h1":"Một số đoạn ở vùng nông thôn được tăng thêm 5 mph so với con số này.","h2":"Xa lộ liên bang ở Kentucky thường là 65 mph, và một số đoạn ở vùng nông thôn có biển báo 70 mph sau khi nghiên cứu an toàn.","p":"Đúng. Tốc độ tối đa thông thường trên xa lộ liên bang là 65 mph."},"tl":{"q":"Sa Kentucky, ano ang karaniwang speed limit sa mga interstate kapag walang ibang limit na nakapaskil para sa bahaging iyon?","o":["55 mph","75 mph","65 mph","80 mph"],"h1":"May ilang bahagi sa probinsya na itinaas nang 5 mph mula sa bilang na ito.","h2":"Karaniwang 65 mph ang mga interstate sa Kentucky, at may ilang bahagi sa probinsya na nakapaskil na 70 mph pagkatapos ng safety study.","p":"Tama. Ang karaniwang limit sa interstate ay 65 mph."},"ar":{"q":"في Kentucky، ما حد السرعة المعتاد على الطرق السريعة بين الولايات (interstate) عندما لا توجد لافتة بحد آخر لذلك الجزء؟","o":["55 mph","75 mph","65 mph","80 mph"],"h1":"بعض الأجزاء الريفية رُفع حدها 5 mph فوق هذا الرقم.","h2":"حد السرعة المعتاد على الطرق السريعة بين الولايات في Kentucky هو 65 mph، وبعض الأجزاء الريفية لها لافتات بـ 70 mph بعد دراسة للسلامة.","p":"صحيح. الحد المعتاد على الطرق السريعة بين الولايات هو 65 mph."},"ref":{"doc":"KY","page":49}},{"id":"ky-017","scope":"KY","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Kentucky, what is the highest speed limit posted on some rural interstate sections?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"It is 5 mph above the usual interstate limit.","h2":"Some rural interstate sections in Kentucky are posted at 70 mph, 5 mph above the usual 65 mph.","p":"Right. Some rural sections allow 70 mph."},"es":{"q":"En Kentucky, ¿cuál es el límite de velocidad más alto en algunos tramos rurales de autopistas interestatales?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Son 5 mph más que el límite habitual de la interestatal.","h2":"Algunos tramos rurales de autopistas interestatales en Kentucky tienen un límite de 70 mph, 5 mph más que el habitual de 65 mph.","p":"Correcto. Algunos tramos rurales permiten 70 mph."},"zh":{"q":"在 Kentucky，有些乡村州际公路路段标示的最高限速是多少？","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"比州际公路一般限速高 5 mph。","h2":"Kentucky 有些乡村州际公路路段标示为 70 mph，比一般的 65 mph 高 5 mph。","p":"对。有些乡村路段允许 70 mph。"},"vi":{"q":"Ở Kentucky, tốc độ tối đa cao nhất được ghi trên biển ở một số đoạn xa lộ liên bang vùng nông thôn là bao nhiêu?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Cao hơn 5 mph so với tốc độ tối đa thông thường trên xa lộ liên bang.","h2":"Một số đoạn xa lộ liên bang vùng nông thôn ở Kentucky có biển báo 70 mph, cao hơn 5 mph so với mức thông thường 65 mph.","p":"Đúng. Một số đoạn vùng nông thôn cho phép 70 mph."},"tl":{"q":"Sa Kentucky, ano ang pinakamataas na speed limit na nakapaskil sa ilang bahagi ng interstate sa probinsya?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Mas mataas ito nang 5 mph kaysa sa karaniwang limit sa interstate.","h2":"May ilang bahagi ng interstate sa probinsya ng Kentucky na nakapaskil na 70 mph, 5 mph na mas mataas sa karaniwang 65 mph.","p":"Tama. May ilang bahagi sa probinsya na pinapayagan ang 70 mph."},"ar":{"q":"في Kentucky، ما أعلى حد سرعة مكتوب على لافتات بعض أجزاء الطرق السريعة بين الولايات في المناطق الريفية؟","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"هو أعلى بـ 5 mph من الحد المعتاد على الطرق السريعة بين الولايات.","h2":"بعض أجزاء الطرق السريعة بين الولايات في المناطق الريفية في Kentucky لها لافتات بـ 70 mph، أي أعلى بـ 5 mph من الحد المعتاد 65 mph.","p":"صحيح. بعض الأجزاء الريفية تسمح بـ 70 mph."},"ref":{"doc":"KY","page":49}},{"id":"ky-018","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, how long is an instruction permit valid since the 2025 law?","o":["One year","Two years","Three years","Four years"],"h1":"The 2025 law added one year to the old three years.","h2":"Since the 2025 law, a Kentucky instruction permit is valid for four years instead of three.","p":"Right. The permit is now valid for four years."},"es":{"q":"En Kentucky, ¿por cuánto tiempo es válido el permiso de instrucción desde la ley de 2025?","o":["Un año","Dos años","Tres años","Cuatro años"],"h1":"La ley de 2025 sumó un año a los tres años de antes.","h2":"Desde la ley de 2025, el permiso de instrucción de Kentucky es válido por cuatro años en lugar de tres.","p":"Correcto. Ahora el permiso es válido por cuatro años."},"zh":{"q":"在 Kentucky，按照 2025 年的法律，学习驾照有效期是多久？","o":["一年","两年","三年","四年"],"h1":"2025 年的法律在原来的三年上加了一年。","h2":"按照 2025 年的法律，Kentucky 的学习驾照有效期是四年，不再是三年。","p":"对。学习驾照现在有效四年。"},"vi":{"q":"Ở Kentucky, theo luật năm 2025, giấy phép tập lái có giá trị bao lâu?","o":["Một năm","Hai năm","Ba năm","Bốn năm"],"h1":"Luật năm 2025 đã thêm một năm vào ba năm cũ.","h2":"Theo luật năm 2025, giấy phép tập lái ở Kentucky có giá trị bốn năm thay vì ba năm.","p":"Đúng. Giấy phép tập lái bây giờ có giá trị bốn năm."},"tl":{"q":"Sa Kentucky, gaano katagal may bisa ang instruction permit mula sa batas noong 2025?","o":["Isang taon","Dalawang taon","Tatlong taon","Apat na taon"],"h1":"Nagdagdag ang batas noong 2025 ng isang taon sa dating tatlong taon.","h2":"Mula sa batas noong 2025, may bisa ang Kentucky instruction permit nang apat na taon sa halip na tatlo.","p":"Tama. May bisa na ngayon ang permit nang apat na taon."},"ar":{"q":"في Kentucky، كم مدة صلاحية تصريح تعلّم القيادة منذ قانون 2025؟","o":["سنة واحدة","سنتان","ثلاث سنوات","أربع سنوات"],"h1":"قانون 2025 أضاف سنة واحدة إلى السنوات الثلاث القديمة.","h2":"منذ قانون 2025، أصبح تصريح تعلّم القيادة في Kentucky صالحًا لمدة أربع سنوات بدلًا من ثلاث.","p":"صحيح. التصريح الآن صالح لمدة أربع سنوات."},"ref":{"doc":"KY","page":null}},{"id":"ky-019","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, what score do you need to pass the written permit test?","o":["At least 80 percent","At least 60 percent","At least 70 percent","At least 90 percent"],"h1":"It is four out of every five answers.","h2":"You need at least 80 percent correct to pass the Kentucky written permit test.","p":"Right. The passing score is 80 percent."},"es":{"q":"En Kentucky, ¿qué puntaje necesita para aprobar el examen escrito del permiso?","o":["Por lo menos 80 por ciento","Por lo menos 60 por ciento","Por lo menos 70 por ciento","Por lo menos 90 por ciento"],"h1":"Son cuatro de cada cinco respuestas.","h2":"Usted necesita por lo menos 80 por ciento de respuestas correctas para aprobar el examen escrito del permiso en Kentucky.","p":"Correcto. Se aprueba con 80 por ciento."},"zh":{"q":"在 Kentucky，学习驾照笔试要考多少分才能通过？","o":["至少 80%","至少 60%","至少 70%","至少 90%"],"h1":"每五题要答对四题。","h2":"你需要答对至少 80%，才能通过 Kentucky 的学习驾照笔试。","p":"对。及格分数是 80%。"},"vi":{"q":"Ở Kentucky, bạn cần bao nhiêu điểm để đậu bài thi viết lấy giấy phép tập lái?","o":["Ít nhất 80 phần trăm","Ít nhất 60 phần trăm","Ít nhất 70 phần trăm","Ít nhất 90 phần trăm"],"h1":"Đúng bốn trong mỗi năm câu trả lời.","h2":"Bạn cần trả lời đúng ít nhất 80 phần trăm để đậu bài thi viết lấy giấy phép tập lái ở Kentucky.","p":"Đúng. Điểm đậu là 80 phần trăm."},"tl":{"q":"Sa Kentucky, anong score ang kailangan mo para pumasa sa nakasulat na permit test?","o":["Hindi bababa sa 80 porsiyento","Hindi bababa sa 60 porsiyento","Hindi bababa sa 70 porsiyento","Hindi bababa sa 90 porsiyento"],"h1":"Apat ito sa bawat limang sagot.","h2":"Kailangan mo ng hindi bababa sa 80 porsiyentong tamang sagot para pumasa sa nakasulat na permit test ng Kentucky.","p":"Tama. Ang passing score ay 80 porsiyento."},"ar":{"q":"في Kentucky، ما الدرجة التي تحتاجها لتنجح في الاختبار الكتابي للتصريح؟","o":["80 بالمئة على الأقل","60 بالمئة على الأقل","70 بالمئة على الأقل","90 بالمئة على الأقل"],"h1":"أربع إجابات صحيحة من كل خمس.","h2":"تحتاج إلى 80 بالمئة على الأقل من الإجابات الصحيحة لتنجح في الاختبار الكتابي للتصريح في Kentucky.","p":"صحيح. درجة النجاح هي 80 بالمئة."},"ref":{"doc":"KY","page":11}},{"id":"ky-020","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, which agency gives the written and road tests for a driver license?","o":["The county sheriff","The local school district","The Kentucky State Police","A private insurance company"],"h1":"It is a statewide police agency.","h2":"In Kentucky, the Kentucky State Police give the written and road tests for a driver license.","p":"Right. The State Police run driver testing."},"es":{"q":"En Kentucky, ¿qué agencia toma los exámenes escrito y de manejo para la licencia?","o":["El alguacil del condado","El distrito escolar local","La Policía Estatal de Kentucky","Una compañía de seguros privada"],"h1":"Es una policía de todo el estado.","h2":"En Kentucky, la Policía Estatal de Kentucky toma los exámenes escrito y de manejo para la licencia.","p":"Correcto. La Policía Estatal se encarga de los exámenes."},"zh":{"q":"在 Kentucky，哪个机构负责驾照的笔试和路考？","o":["县警长（county sheriff）","当地学区","Kentucky State Police","私人保险公司"],"h1":"这是一个全州的警察机构。","h2":"在 Kentucky，驾照的笔试和路考是由 Kentucky State Police（州警察）负责的。","p":"对。州警察负责驾照考试。"},"vi":{"q":"Ở Kentucky, cơ quan nào tổ chức bài thi viết và thi lái xe để lấy bằng lái?","o":["Cảnh sát trưởng quận (county sheriff)","Học khu địa phương","Cảnh sát Tiểu bang Kentucky (Kentucky State Police)","Một công ty bảo hiểm tư nhân"],"h1":"Đó là một cơ quan cảnh sát của cả tiểu bang.","h2":"Ở Kentucky, Cảnh sát Tiểu bang Kentucky (Kentucky State Police) tổ chức bài thi viết và thi lái xe để lấy bằng lái.","p":"Đúng. Cảnh sát Tiểu bang phụ trách các bài thi lái xe."},"tl":{"q":"Sa Kentucky, aling ahensya ang nagbibigay ng nakasulat na test at road test para sa driver license?","o":["Ang county sheriff","Ang lokal na school district","Ang Kentucky State Police","Isang pribadong kompanya ng insurance"],"h1":"Isa itong ahensya ng pulis para sa buong estado.","h2":"Sa Kentucky, ang Kentucky State Police ang nagbibigay ng nakasulat na test at road test para sa driver license.","p":"Tama. Ang State Police ang nangangasiwa sa pagsusulit ng mga drayber."},"ar":{"q":"في Kentucky، أي جهة تُجري الاختبار الكتابي واختبار القيادة على الطريق لرخصة القيادة؟","o":["شريف المقاطعة (county sheriff)","المنطقة التعليمية المحلية","شرطة ولاية Kentucky (Kentucky State Police)","شركة تأمين خاصة"],"h1":"هي جهة شرطة للولاية كلها.","h2":"في Kentucky، شرطة ولاية Kentucky (Kentucky State Police) هي التي تُجري الاختبار الكتابي واختبار القيادة على الطريق لرخصة القيادة.","p":"صحيح. شرطة الولاية هي المسؤولة عن اختبارات السائقين."},"ref":{"doc":"KY","page":4}},{"id":"ky-021","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, can you take the standard written driver test in Spanish?","o":["No, only in English","Yes, it is offered in Spanish","Only with a paid interpreter","Only after failing in English"],"h1":"Kentucky State Police list Spanish among the test languages.","h2":"Yes, the Kentucky State Police offer the standard written driver test in Spanish, and a Spanish driver manual is available too.","p":"Right. The standard test is offered in Spanish."},"es":{"q":"En Kentucky, ¿puede tomar en español el examen escrito estándar de manejo?","o":["No, solo en inglés","Sí, se ofrece en español","Solo con un intérprete pagado","Solo después de reprobar en inglés"],"h1":"La Policía Estatal de Kentucky incluye el español entre los idiomas del examen.","h2":"Sí, la Policía Estatal de Kentucky ofrece el examen escrito estándar de manejo en español, y también hay un manual del conductor en español.","p":"Correcto. El examen estándar se ofrece en español."},"zh":{"q":"在 Kentucky，你可以用西班牙语参加普通的驾照笔试吗？","o":["不可以，只能用英语","可以，有西班牙语考试","只能请付费的翻译","只能在英语考试不及格以后"],"h1":"Kentucky State Police 把西班牙语列为考试语言之一。","h2":"可以，Kentucky State Police 提供西班牙语的普通驾照笔试，也有西班牙语的驾驶手册。","p":"对。普通笔试有西班牙语版本。"},"vi":{"q":"Ở Kentucky, bạn có thể làm bài thi viết lái xe tiêu chuẩn bằng tiếng Tây Ban Nha không?","o":["Không, chỉ bằng tiếng Anh","Có, có bài thi bằng tiếng Tây Ban Nha","Chỉ khi có thông dịch viên trả tiền","Chỉ sau khi thi rớt bằng tiếng Anh"],"h1":"Cảnh sát Tiểu bang Kentucky (Kentucky State Police) có liệt kê tiếng Tây Ban Nha trong các ngôn ngữ thi.","h2":"Có, Cảnh sát Tiểu bang Kentucky (Kentucky State Police) có bài thi viết lái xe tiêu chuẩn bằng tiếng Tây Ban Nha, và cũng có sách hướng dẫn lái xe bằng tiếng Tây Ban Nha.","p":"Đúng. Bài thi tiêu chuẩn có bằng tiếng Tây Ban Nha."},"tl":{"q":"Sa Kentucky, maaari mo bang kunin sa Spanish ang karaniwang nakasulat na driver test?","o":["Hindi, sa English lang","Oo, inaalok ito sa Spanish","Kung may bayad na interpreter lang","Pagkatapos lang bumagsak sa English"],"h1":"Kasama ang Spanish sa listahan ng Kentucky State Police ng mga wika ng test.","h2":"Oo, inaalok ng Kentucky State Police ang karaniwang nakasulat na driver test sa Spanish, at may driver manual din sa Spanish.","p":"Tama. Inaalok sa Spanish ang karaniwang test."},"ar":{"q":"في Kentucky، هل يمكنك أن تُجري الاختبار الكتابي العادي للقيادة باللغة الإسبانية؟","o":["لا، بالإنجليزية فقط","نعم، الاختبار متوفر بالإسبانية","فقط مع مترجم مدفوع الأجر","فقط بعد الرسوب بالإنجليزية"],"h1":"شرطة ولاية Kentucky (Kentucky State Police) تذكر الإسبانية ضمن لغات الاختبار.","h2":"نعم، شرطة ولاية Kentucky (Kentucky State Police) تقدّم الاختبار الكتابي العادي للقيادة بالإسبانية، ويوجد أيضًا دليل للسائقين بالإسبانية.","p":"صحيح. الاختبار العادي متوفر بالإسبانية."},"ref":{"doc":"KY","page":11}},{"id":"ky-022","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, how many points in two years can lead to a suspension for a driver 18 or older?","o":["6 points","12 points","18 points","24 points"],"h1":"Think of a dozen.","h2":"In Kentucky, a driver 18 or older who gets 12 points within two years may have the license suspended.","p":"Right. 12 points in two years can mean a suspension."},"es":{"q":"En Kentucky, ¿cuántos puntos en dos años pueden llevar a una suspensión para un conductor de 18 años o más?","o":["6 puntos","12 puntos","18 puntos","24 puntos"],"h1":"Piense en una docena.","h2":"En Kentucky, a un conductor de 18 años o más que acumula 12 puntos en dos años le pueden suspender la licencia.","p":"Correcto. 12 puntos en dos años pueden significar una suspensión."},"zh":{"q":"在 Kentucky，18 岁或以上的司机在两年内被记多少分，可能会被暂停驾照？","o":["6 分","12 分","18 分","24 分"],"h1":"想一想“一打”是多少。","h2":"在 Kentucky，18 岁或以上的司机如果在两年内被记 12 分，驾照可能会被暂停。","p":"对。两年内 12 分可能会导致驾照被暂停。"},"vi":{"q":"Ở Kentucky, tài xế từ 18 tuổi trở lên bị bao nhiêu điểm trong hai năm thì có thể bị đình chỉ bằng lái?","o":["6 điểm","12 điểm","18 điểm","24 điểm"],"h1":"Hãy nghĩ đến một tá.","h2":"Ở Kentucky, tài xế từ 18 tuổi trở lên bị 12 điểm trong vòng hai năm có thể bị đình chỉ bằng lái.","p":"Đúng. 12 điểm trong hai năm có thể dẫn đến đình chỉ bằng lái."},"tl":{"q":"Sa Kentucky, ilang puntos sa loob ng dalawang taon ang maaaring humantong sa suspensyon para sa drayber na 18 taong gulang pataas?","o":["6 na puntos","12 puntos","18 puntos","24 na puntos"],"h1":"Isipin ang isang dosena.","h2":"Sa Kentucky, ang drayber na 18 taong gulang pataas na makakuha ng 12 puntos sa loob ng dalawang taon ay maaaring masuspinde ang lisensya.","p":"Tama. Ang 12 puntos sa loob ng dalawang taon ay maaaring mangahulugan ng suspensyon."},"ar":{"q":"في Kentucky، كم نقطة خلال سنتين قد تؤدي إلى إيقاف رخصة سائق عمره 18 سنة أو أكثر؟","o":["6 نقاط","12 نقطة","18 نقطة","24 نقطة"],"h1":"فكّر في الدزينة.","h2":"في Kentucky، السائق الذي عمره 18 سنة أو أكثر ويحصل على 12 نقطة خلال سنتين قد تُوقَف رخصته.","p":"صحيح. 12 نقطة خلال سنتين قد تعني إيقاف الرخصة."},"ref":{"doc":"KY","page":17}},{"id":"ky-023","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, a driver under 18 can face a suspension after how many points in two years?","o":["3 points","12 points","10 points","7 points"],"h1":"Young drivers have a lower limit than adults.","h2":"In Kentucky, a driver under 18 who gets 7 points within two years can lose the license, while adults have a limit of 12.","p":"Right. Under 18, the limit is 7 points."},"es":{"q":"En Kentucky, ¿con cuántos puntos en dos años puede un conductor menor de 18 años enfrentar una suspensión?","o":["3 puntos","12 puntos","10 puntos","7 puntos"],"h1":"Los conductores jóvenes tienen un límite más bajo que los adultos.","h2":"En Kentucky, un conductor menor de 18 años que acumula 7 puntos en dos años puede perder la licencia, mientras que el límite para los adultos es 12.","p":"Correcto. Para menores de 18, el límite es 7 puntos."},"zh":{"q":"在 Kentucky，未满 18 岁的司机在两年内被记多少分，可能会被暂停驾照？","o":["3 分","12 分","10 分","7 分"],"h1":"年轻司机的分数上限比成年人低。","h2":"在 Kentucky，未满 18 岁的司机如果在两年内被记 7 分，可能会失去驾照，而成年人的上限是 12 分。","p":"对。未满 18 岁，上限是 7 分。"},"vi":{"q":"Ở Kentucky, tài xế dưới 18 tuổi có thể bị đình chỉ bằng lái sau bao nhiêu điểm trong hai năm?","o":["3 điểm","12 điểm","10 điểm","7 điểm"],"h1":"Tài xế trẻ có giới hạn thấp hơn người lớn.","h2":"Ở Kentucky, tài xế dưới 18 tuổi bị 7 điểm trong vòng hai năm có thể mất bằng lái, còn người lớn có giới hạn là 12 điểm.","p":"Đúng. Dưới 18 tuổi, giới hạn là 7 điểm."},"tl":{"q":"Sa Kentucky, ang drayber na wala pang 18 ay maaaring masuspinde pagkatapos ng ilang puntos sa loob ng dalawang taon?","o":["3 puntos","12 puntos","10 puntos","7 puntos"],"h1":"Mas mababa ang limitasyon ng mga batang drayber kaysa sa mga nasa hustong gulang.","h2":"Sa Kentucky, ang drayber na wala pang 18 na makakuha ng 7 puntos sa loob ng dalawang taon ay maaaring mawalan ng lisensya, habang 12 ang limitasyon ng mga nasa hustong gulang.","p":"Tama. Kapag wala pang 18, ang limitasyon ay 7 puntos."},"ar":{"q":"في Kentucky، بعد كم نقطة خلال سنتين قد تُوقَف رخصة سائق عمره أقل من 18 سنة؟","o":["3 نقاط","12 نقطة","10 نقاط","7 نقاط"],"h1":"حدّ السائقين الصغار أقل من حدّ البالغين.","h2":"في Kentucky، السائق الذي عمره أقل من 18 سنة ويحصل على 7 نقاط خلال سنتين قد يفقد رخصته، بينما حدّ البالغين هو 12 نقطة.","p":"صحيح. تحت 18 سنة، الحدّ هو 7 نقاط."},"ref":{"doc":"KY","page":17}},{"id":"ky-024","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, how long do points stay active after a traffic conviction?","o":["Two years","Six months","Five years","Ten years"],"h1":"It is the same length of time the point system looks back.","h2":"In Kentucky, points expire two years after the conviction, but the conviction stays on your record for five years.","p":"Right. Points last two years."},"es":{"q":"En Kentucky, ¿cuánto tiempo siguen activos los puntos después de una condena de tránsito?","o":["Dos años","Seis meses","Cinco años","Diez años"],"h1":"Es el mismo tiempo que revisa el sistema de puntos.","h2":"En Kentucky, los puntos vencen dos años después de la condena, pero la condena se queda en su historial por cinco años.","p":"Correcto. Los puntos duran dos años."},"zh":{"q":"在 Kentucky，交通违法定罪后，分数会保留多长时间？","o":["两年","六个月","五年","十年"],"h1":"这和计分制度往回看的时间一样长。","h2":"在 Kentucky，分数在定罪两年后失效，但定罪记录会在你的记录上保留五年。","p":"对。分数保留两年。"},"vi":{"q":"Ở Kentucky, điểm phạt còn hiệu lực bao lâu sau khi bị kết tội vi phạm giao thông?","o":["Hai năm","Sáu tháng","Năm năm","Mười năm"],"h1":"Đó là cùng khoảng thời gian mà hệ thống điểm xem xét lại.","h2":"Ở Kentucky, điểm phạt hết hiệu lực hai năm sau khi bị kết tội, nhưng bản án vẫn ở trong hồ sơ của bạn trong năm năm.","p":"Đúng. Điểm phạt kéo dài hai năm."},"tl":{"q":"Sa Kentucky, gaano katagal nananatiling aktibo ang mga puntos pagkatapos ng isang traffic conviction (pagkahatol sa paglabag sa trapiko)?","o":["Dalawang taon","Anim na buwan","Limang taon","Sampung taon"],"h1":"Pareho ito sa haba ng panahong tinitingnan ng point system.","h2":"Sa Kentucky, nawawalan ng bisa ang mga puntos dalawang taon pagkatapos ng conviction, pero nananatili ang conviction sa iyong record nang limang taon.","p":"Tama. Tumatagal ang mga puntos nang dalawang taon."},"ar":{"q":"في Kentucky، كم تبقى النقاط سارية بعد الإدانة بمخالفة مرورية؟","o":["سنتان","ستة أشهر","خمس سنوات","عشر سنوات"],"h1":"إنها نفس المدة التي ينظر إليها نظام النقاط إلى الوراء.","h2":"في Kentucky، تنتهي النقاط بعد سنتين من الإدانة، لكن الإدانة تبقى في سجلّك خمس سنوات.","p":"صحيح. النقاط تبقى سنتين."},"ref":{"doc":"KY","page":17}},{"id":"ky-025","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, what is the minimum liability insurance for injury to one person in a crash?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"The same amount is also the minimum for property damage.","h2":"In Kentucky, liability insurance must cover at least $25,000 for injury to one person, $50,000 for all injuries in one crash, and $25,000 for property damage.","p":"Right. $25,000 for one person is the minimum."},"es":{"q":"En Kentucky, ¿cuál es el seguro de responsabilidad mínimo por lesiones a una persona en un choque?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"La misma cantidad es también el mínimo para daños a la propiedad.","h2":"En Kentucky, el seguro de responsabilidad debe cubrir al menos $25,000 por lesiones a una persona, $50,000 por todas las lesiones en un choque y $25,000 por daños a la propiedad.","p":"Correcto. $25,000 por una persona es el mínimo."},"zh":{"q":"在 Kentucky，车祸中一个人受伤的最低责任保险金额是多少？","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"财产损失的最低金额也是这个数。","h2":"在 Kentucky，责任保险必须至少赔付一个人受伤 $25,000，一次车祸所有受伤 $50,000，以及财产损失 $25,000。","p":"对。一个人的最低金额是 $25,000。"},"vi":{"q":"Ở Kentucky, bảo hiểm trách nhiệm tối thiểu cho thương tích của một người trong một vụ tai nạn là bao nhiêu?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"Số tiền này cũng là mức tối thiểu cho thiệt hại tài sản.","h2":"Ở Kentucky, bảo hiểm trách nhiệm phải chi trả ít nhất $25,000 cho thương tích của một người, $50,000 cho tất cả thương tích trong một vụ tai nạn, và $25,000 cho thiệt hại tài sản.","p":"Đúng. $25,000 cho một người là mức tối thiểu."},"tl":{"q":"Sa Kentucky, ano ang pinakamababang liability insurance para sa pinsala sa isang tao sa isang aksidente?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"Ang parehong halaga ay ang pinakamababa rin para sa pinsala sa ari-arian.","h2":"Sa Kentucky, ang liability insurance ay dapat sumaklaw ng hindi bababa sa $25,000 para sa pinsala sa isang tao, $50,000 para sa lahat ng pinsala sa isang aksidente, at $25,000 para sa pinsala sa ari-arian.","p":"Tama. $25,000 para sa isang tao ang pinakamababa."},"ar":{"q":"في Kentucky، ما الحدّ الأدنى لتأمين المسؤولية عن إصابة شخص واحد في حادث؟","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"المبلغ نفسه هو أيضًا الحدّ الأدنى لأضرار الممتلكات.","h2":"في Kentucky، يجب أن يغطي تأمين المسؤولية على الأقل $25,000 لإصابة شخص واحد، و$50,000 لكل الإصابات في حادث واحد، و$25,000 لأضرار الممتلكات.","p":"صحيح. $25,000 لشخص واحد هو الحدّ الأدنى."},"ref":{"doc":"KY","page":19}},{"id":"ky-026","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, what can happen to an owner or driver of a vehicle with no insurance?","o":["Only a written warning","A fine of $500 to $1,000, up to 90 days in jail, or both","A $50 fine and nothing more","Only a 7-day wait to register the car"],"h1":"Driving without insurance is a crime in Kentucky.","h2":"In Kentucky, the owner and driver of an uninsured vehicle can be fined $500 to $1,000, jailed for up to 90 days, or both, and the registration is revoked.","p":"Right. No insurance can mean a big fine or jail."},"es":{"q":"En Kentucky, ¿qué le puede pasar al dueño o al conductor de un vehículo sin seguro?","o":["Solo una advertencia por escrito","Una multa de $500 a $1,000, hasta 90 días de cárcel, o ambas","Una multa de $50 y nada más","Solo una espera de 7 días para registrar el carro"],"h1":"Manejar sin seguro es un delito en Kentucky.","h2":"En Kentucky, el dueño y el conductor de un vehículo sin seguro pueden recibir una multa de $500 a $1,000, hasta 90 días de cárcel, o ambas, y se revoca el registro.","p":"Correcto. No tener seguro puede significar una multa grande o cárcel."},"zh":{"q":"在 Kentucky，没有保险的车辆的车主或司机可能会怎样？","o":["只有书面警告","罚款 $500 到 $1,000，最多坐牢 90 天，或两者都有","罚款 $50，没有别的","只需等 7 天才能给车登记"],"h1":"在 Kentucky，没有保险开车是犯罪。","h2":"在 Kentucky，没有保险的车辆的车主和司机可能被罚款 $500 到 $1,000，最多坐牢 90 天，或两者都有，而且车辆登记会被吊销。","p":"对。没有保险可能意味着高额罚款或坐牢。"},"vi":{"q":"Ở Kentucky, chủ xe hoặc tài xế của xe không có bảo hiểm có thể bị gì?","o":["Chỉ bị cảnh cáo bằng văn bản","Bị phạt $500 đến $1,000, ngồi tù tới 90 ngày, hoặc cả hai","Bị phạt $50 và không gì khác","Chỉ phải chờ 7 ngày để đăng ký xe"],"h1":"Lái xe không có bảo hiểm là một tội ở Kentucky.","h2":"Ở Kentucky, chủ xe và tài xế của xe không có bảo hiểm có thể bị phạt $500 đến $1,000, ngồi tù tới 90 ngày, hoặc cả hai, và giấy đăng ký xe bị thu hồi.","p":"Đúng. Không có bảo hiểm có thể bị phạt nặng hoặc ngồi tù."},"tl":{"q":"Sa Kentucky, ano ang maaaring mangyari sa may-ari o drayber ng sasakyang walang insurance?","o":["Isang nakasulat na babala lamang","Multang $500 hanggang $1,000, hanggang 90 araw na pagkakakulong, o pareho","Multang $50 at wala nang iba","Paghihintay lamang nang 7 araw para mairehistro ang kotse"],"h1":"Krimen sa Kentucky ang pagmamaneho nang walang insurance.","h2":"Sa Kentucky, ang may-ari at drayber ng sasakyang walang insurance ay maaaring pagmultahin ng $500 hanggang $1,000, makulong nang hanggang 90 araw, o pareho, at binabawi ang rehistro.","p":"Tama. Ang walang insurance ay maaaring mangahulugan ng malaking multa o kulong."},"ar":{"q":"في Kentucky، ماذا قد يحدث لمالك أو سائق مركبة بلا تأمين؟","o":["إنذار مكتوب فقط","غرامة من $500 إلى $1,000، أو سجن حتى 90 يومًا، أو الاثنان معًا","غرامة $50 فقط ولا شيء آخر","انتظار 7 أيام فقط لتسجيل السيارة"],"h1":"القيادة بلا تأمين جريمة في Kentucky.","h2":"في Kentucky، يمكن تغريم مالك وسائق مركبة بلا تأمين من $500 إلى $1,000، أو سجنه حتى 90 يومًا، أو الاثنين معًا، ويُلغى تسجيل المركبة.","p":"صحيح. عدم وجود تأمين قد يعني غرامة كبيرة أو سجنًا."},"ref":{"doc":"KY","page":19}},{"id":"ky-027","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, if you fail the road skills test, how long must you wait before trying again?","o":["You may retry the same day","At least 30 days","At least one week","At least six months"],"h1":"The wait is short, just enough time to practice.","h2":"In Kentucky, after failing the road skills test you must wait at least one week before you try again.","p":"Right. Wait one week and practice."},"es":{"q":"En Kentucky, si no pasa el examen práctico de manejo, ¿cuánto tiempo debe esperar para intentarlo de nuevo?","o":["Puede intentarlo el mismo día","Al menos 30 días","Al menos una semana","Al menos seis meses"],"h1":"La espera es corta, justo el tiempo para practicar.","h2":"En Kentucky, después de no pasar el examen práctico de manejo, usted debe esperar al menos una semana antes de intentarlo de nuevo.","p":"Correcto. Espere una semana y practique."},"zh":{"q":"在 Kentucky，如果你没有通过路考（road skills test），要等多久才能再考？","o":["当天就可以再考","至少 30 天","至少一个星期","至少六个月"],"h1":"等待时间很短，刚好够你练习。","h2":"在 Kentucky，路考没通过后，你必须至少等一个星期才能再考。","p":"对。等一个星期，好好练习。"},"vi":{"q":"Ở Kentucky, nếu bạn thi trượt bài thi kỹ năng lái xe trên đường (road skills test), bạn phải chờ bao lâu mới được thi lại?","o":["Bạn có thể thi lại ngay trong ngày","Ít nhất 30 ngày","Ít nhất một tuần","Ít nhất sáu tháng"],"h1":"Thời gian chờ ngắn, vừa đủ để luyện tập.","h2":"Ở Kentucky, sau khi thi trượt bài thi kỹ năng lái xe trên đường, bạn phải chờ ít nhất một tuần mới được thi lại.","p":"Đúng. Chờ một tuần và luyện tập."},"tl":{"q":"Sa Kentucky, kung bumagsak ka sa road skills test (pagsusulit sa pagmamaneho sa kalsada), gaano katagal ka dapat maghintay bago sumubok ulit?","o":["Puwede kang sumubok ulit sa parehong araw","Hindi bababa sa 30 araw","Hindi bababa sa isang linggo","Hindi bababa sa anim na buwan"],"h1":"Maikli ang paghihintay, sapat lang para makapag-ensayo.","h2":"Sa Kentucky, pagkatapos bumagsak sa road skills test, kailangan mong maghintay nang hindi bababa sa isang linggo bago sumubok ulit.","p":"Tama. Maghintay nang isang linggo at mag-ensayo."},"ar":{"q":"في Kentucky، إذا رسبت في اختبار مهارات القيادة على الطريق (road skills test)، كم يجب أن تنتظر قبل المحاولة مرة أخرى؟","o":["يمكنك المحاولة مرة أخرى في اليوم نفسه","30 يومًا على الأقل","أسبوعًا واحدًا على الأقل","ستة أشهر على الأقل"],"h1":"الانتظار قصير، يكفي فقط للتدرّب.","h2":"في Kentucky، بعد الرسوب في اختبار مهارات القيادة على الطريق يجب أن تنتظر أسبوعًا واحدًا على الأقل قبل أن تحاول مرة أخرى.","p":"صحيح. انتظر أسبوعًا وتدرّب."},"ref":{"doc":"KY","page":6}},{"id":"ky-028","scope":"KY","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Kentucky, when you pass another vehicle, how far from an oncoming vehicle must the pass be finished?","o":["At least 50 feet","At least 200 feet","At least 100 feet","At least 1,000 feet"],"h1":"The distance is more than half a football field.","h2":"In Kentucky, you must finish a pass before you come within 200 feet of an oncoming vehicle.","p":"Right. Finish the pass at least 200 feet before an oncoming vehicle."},"es":{"q":"En Kentucky, al rebasar a otro vehículo, ¿a qué distancia de un vehículo que viene de frente debe terminar de rebasar?","o":["Al menos 50 pies","Al menos 200 pies","Al menos 100 pies","Al menos 1,000 pies"],"h1":"La distancia es más de la mitad de un campo de fútbol americano.","h2":"En Kentucky, usted debe terminar de rebasar antes de quedar a menos de 200 pies de un vehículo que viene de frente.","p":"Correcto. Termine de rebasar al menos 200 pies antes del vehículo que viene."},"zh":{"q":"在 Kentucky，超车时，你必须在离对面来车多远之前完成超车？","o":["至少 50 英尺","至少 200 英尺","至少 100 英尺","至少 1,000 英尺"],"h1":"这个距离比半个美式足球场还长。","h2":"在 Kentucky，你必须在离对面来车 200 英尺之前完成超车。","p":"对。在对面来车前至少 200 英尺完成超车。"},"vi":{"q":"Ở Kentucky, khi vượt xe khác, bạn phải vượt xong khi còn cách xe chạy ngược chiều bao xa?","o":["Ít nhất 50 feet","Ít nhất 200 feet","Ít nhất 100 feet","Ít nhất 1,000 feet"],"h1":"Khoảng cách này dài hơn nửa sân bóng bầu dục Mỹ.","h2":"Ở Kentucky, bạn phải vượt xong trước khi đến gần xe chạy ngược chiều trong vòng 200 feet.","p":"Đúng. Hãy vượt xong khi còn cách xe ngược chiều ít nhất 200 feet."},"tl":{"q":"Sa Kentucky, kapag nag-o-overtake ka sa ibang sasakyan, gaano kalayo dapat sa paparating na sasakyan mo matapos ang pag-overtake?","o":["Hindi bababa sa 50 talampakan","Hindi bababa sa 200 talampakan","Hindi bababa sa 100 talampakan","Hindi bababa sa 1,000 talampakan"],"h1":"Mas mahaba ang layo kaysa kalahati ng isang football field.","h2":"Sa Kentucky, dapat mong tapusin ang pag-overtake bago ka umabot sa loob ng 200 talampakan mula sa paparating na sasakyan.","p":"Tama. Tapusin ang pag-overtake nang hindi bababa sa 200 talampakan bago ang paparating na sasakyan."},"ar":{"q":"في Kentucky، عندما تتجاوز سيارة أخرى، على أي مسافة من السيارة القادمة من الاتجاه المقابل يجب أن تُنهي التجاوز؟","o":["50 قدمًا على الأقل","200 قدم على الأقل","100 قدم على الأقل","1,000 قدم على الأقل"],"h1":"المسافة أكثر من نصف ملعب كرة قدم أمريكية.","h2":"في Kentucky، يجب أن تُنهي التجاوز قبل أن تصبح على بُعد 200 قدم من السيارة القادمة من الاتجاه المقابل.","p":"صحيح. أنهِ التجاوز قبل السيارة القادمة بمسافة 200 قدم على الأقل."},"ref":{"doc":"KY","page":47}},{"id":"ky-029","scope":"KY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Kentucky, on a road with one lane each way, how much space must you leave when you pass a bicycle?","o":["At least 1 foot","At least 2 feet","At least 6 feet","At least 3 feet"],"h1":"It is about the length of a yardstick.","h2":"In Kentucky, when there is only one lane in your direction, you must pass a bicycle on the left and keep at least 3 feet away.","p":"Right. Give a bicycle at least 3 feet."},"es":{"q":"En Kentucky, en un camino con un carril en cada sentido, ¿cuánto espacio debe dejar al pasar a una bicicleta?","o":["Al menos 1 pie","Al menos 2 pies","Al menos 6 pies","Al menos 3 pies"],"h1":"Es más o menos el largo de una regla de una yarda.","h2":"En Kentucky, cuando hay un solo carril en su sentido, usted debe pasar a la bicicleta por la izquierda y dejar al menos 3 pies.","p":"Correcto. Deje al menos 3 pies a la bicicleta."},"zh":{"q":"在 Kentucky，在每个方向只有一条车道的路上，你超过自行车时必须留出多少空间？","o":["至少 1 英尺","至少 2 英尺","至少 6 英尺","至少 3 英尺"],"h1":"大约是一把码尺的长度。","h2":"在 Kentucky，当你的方向只有一条车道时，你必须从左边超过自行车，并保持至少 3 英尺的距离。","p":"对。给自行车留出至少 3 英尺。"},"vi":{"q":"Ở Kentucky, trên đường mỗi chiều chỉ có một làn, bạn phải chừa bao nhiêu khoảng trống khi vượt xe đạp?","o":["Ít nhất 1 foot","Ít nhất 2 feet","Ít nhất 6 feet","Ít nhất 3 feet"],"h1":"Khoảng bằng chiều dài một cây thước một yard.","h2":"Ở Kentucky, khi chiều của bạn chỉ có một làn, bạn phải vượt xe đạp bên trái và giữ cách ít nhất 3 feet.","p":"Đúng. Hãy chừa cho xe đạp ít nhất 3 feet."},"tl":{"q":"Sa Kentucky, sa daan na may isang lane bawat direksyon, gaano kalaking espasyo ang dapat mong iwan kapag nilalampasan mo ang bisikleta?","o":["Hindi bababa sa 1 talampakan","Hindi bababa sa 2 talampakan","Hindi bababa sa 6 na talampakan","Hindi bababa sa 3 talampakan"],"h1":"Halos kasinghaba ito ng isang yardstick (panukat na isang yarda).","h2":"Sa Kentucky, kapag iisa lang ang lane sa direksyon mo, dapat mong lampasan ang bisikleta sa kaliwa at lumayo nang hindi bababa sa 3 talampakan.","p":"Tama. Bigyan ang bisikleta ng hindi bababa sa 3 talampakan."},"ar":{"q":"في Kentucky، على طريق فيه مسار واحد في كل اتجاه، كم مسافة يجب أن تترك عندما تتجاوز دراجة هوائية؟","o":["قدم واحد على الأقل","قدمان على الأقل","6 أقدام على الأقل","3 أقدام على الأقل"],"h1":"إنها تقريبًا طول مسطرة طولها ياردة واحدة.","h2":"في Kentucky، عندما يكون في اتجاهك مسار واحد فقط، يجب أن تتجاوز الدراجة الهوائية من اليسار وتبتعد عنها 3 أقدام على الأقل.","p":"صحيح. اترك للدراجة الهوائية 3 أقدام على الأقل."},"ref":{"doc":"KY","page":48}},{"id":"ky-030","scope":"KY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Kentucky, what is the smallest following distance the manual tells you to keep behind the vehicle ahead?","o":["One second","Two seconds","Four seconds","Ten seconds"],"h1":"It is longer than the two seconds many people use.","h2":"In Kentucky, the manual says to keep a following distance of at least 4 seconds behind the vehicle ahead.","p":"Right. Keep at least 4 seconds behind."},"es":{"q":"En Kentucky, ¿cuál es la distancia de seguimiento mínima que el manual le dice mantener detrás del vehículo de adelante?","o":["Un segundo","Dos segundos","Cuatro segundos","Diez segundos"],"h1":"Es más que los dos segundos que mucha gente usa.","h2":"En Kentucky, el manual dice que debe mantener una distancia de seguimiento de al menos 4 segundos detrás del vehículo de adelante.","p":"Correcto. Mantenga al menos 4 segundos de distancia."},"zh":{"q":"在 Kentucky，驾驶手册要求你和前车保持的最小跟车距离是多少？","o":["一秒","两秒","四秒","十秒"],"h1":"它比很多人用的两秒更长。","h2":"在 Kentucky，驾驶手册说你要和前车保持至少 4 秒的跟车距离。","p":"对。和前车保持至少 4 秒的距离。"},"vi":{"q":"Ở Kentucky, sổ tay lái xe bảo bạn giữ khoảng cách tối thiểu bao nhiêu với xe phía trước?","o":["Một giây","Hai giây","Bốn giây","Mười giây"],"h1":"Nó dài hơn hai giây mà nhiều người vẫn dùng.","h2":"Ở Kentucky, sổ tay lái xe nói bạn phải giữ khoảng cách ít nhất 4 giây với xe phía trước.","p":"Đúng. Hãy giữ cách xe phía trước ít nhất 4 giây."},"tl":{"q":"Sa Kentucky, ano ang pinakamaikling layo sa likod ng sasakyan sa unahan na sinasabi ng manual na panatilihin mo?","o":["Isang segundo","Dalawang segundo","Apat na segundo","Sampung segundo"],"h1":"Mas mahaba ito kaysa sa dalawang segundo na ginagamit ng maraming tao.","h2":"Sa Kentucky, sinasabi ng manual na panatilihin ang layong hindi bababa sa 4 na segundo sa likod ng sasakyan sa unahan.","p":"Tama. Manatili nang hindi bababa sa 4 na segundo sa likod."},"ar":{"q":"في Kentucky، ما أقل مسافة متابعة يطلب منك الدليل أن تتركها خلف السيارة التي أمامك؟","o":["ثانية واحدة","ثانيتان","أربع ثوانٍ","عشر ثوانٍ"],"h1":"إنها أطول من الثانيتين اللتين يستخدمهما كثير من الناس.","h2":"في Kentucky، يقول الدليل أن تترك مسافة متابعة لا تقل عن 4 ثوانٍ خلف السيارة التي أمامك.","p":"صحيح. ابقَ خلف السيارة 4 ثوانٍ على الأقل."},"ref":{"doc":"KY","page":51}},{"id":"ky-031","scope":"KY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kentucky, when can traffic fines be doubled in a highway work zone?","o":["When signs say fines are doubled and at least one worker is present","Only at night, even when no signs are posted","Any time, even after all the work is finished","Only when a police car is parked in the work zone"],"h1":"Two things must be true: the signs and the people.","h2":"In Kentucky, fines may be doubled in a highway work zone when signs say so and at least one worker is present.","p":"Right. Signs posted and a worker present means double fines."},"es":{"q":"En Kentucky, ¿cuándo se pueden duplicar las multas en una zona de trabajo en la carretera?","o":["Cuando hay letreros de multas dobles y al menos un trabajador presente","Solo de noche, aunque no haya ningún letrero","En cualquier momento, aunque el trabajo ya haya terminado","Solo cuando hay un carro de policía estacionado en la zona de trabajo"],"h1":"Dos cosas deben cumplirse: los letreros y las personas.","h2":"En Kentucky, las multas se pueden duplicar en una zona de trabajo en la carretera cuando hay letreros que lo indican y al menos un trabajador presente.","p":"Correcto. Con letreros y un trabajador presente, las multas son dobles."},"zh":{"q":"在 Kentucky，在公路施工区，什么时候交通罚款可以加倍？","o":["有标志写着罚款加倍，并且至少有一名工人在场时","只在晚上，即使没有任何标志","任何时候，即使施工已经全部结束","只有当施工区里停着一辆警车时"],"h1":"两件事必须同时成立：标志和人。","h2":"在 Kentucky，当公路施工区有标志写明罚款加倍，并且至少有一名工人在场时，罚款可以加倍。","p":"对。有标志并且有工人在场，罚款就加倍。"},"vi":{"q":"Ở Kentucky, khi nào tiền phạt giao thông có thể bị tăng gấp đôi trong khu vực thi công trên đường cao tốc?","o":["Khi có biển báo phạt gấp đôi và có ít nhất một công nhân đang làm việc","Chỉ vào ban đêm, kể cả khi không có biển báo","Bất cứ lúc nào, kể cả khi công việc đã xong hết","Chỉ khi có xe cảnh sát đỗ trong khu vực thi công"],"h1":"Phải có đủ hai điều: biển báo và con người.","h2":"Ở Kentucky, tiền phạt có thể bị tăng gấp đôi trong khu vực thi công trên đường cao tốc khi có biển báo như vậy và có ít nhất một công nhân đang làm việc.","p":"Đúng. Có biển báo và có công nhân thì tiền phạt tăng gấp đôi."},"tl":{"q":"Sa Kentucky, kailan puwedeng dobleng multa sa trapiko sa isang work zone sa highway?","o":["Kapag may karatulang nagsasabing doble ang multa at may kahit isang manggagawa roon","Sa gabi lang, kahit walang anumang karatula","Kahit kailan, kahit tapos na ang lahat ng trabaho","Kapag may nakaparadang sasakyan ng pulis sa work zone lang"],"h1":"Dalawang bagay ang dapat totoo: ang mga karatula at ang mga tao.","h2":"Sa Kentucky, puwedeng dobleng multa sa isang work zone sa highway kapag may karatulang nagsasabi nito at may kahit isang manggagawa roon.","p":"Tama. May karatula at may manggagawa roon ay nangangahulugang doble ang multa."},"ar":{"q":"في Kentucky، متى يمكن مضاعفة غرامات المرور في منطقة أعمال على الطريق السريع؟","o":["عندما توجد لافتات تقول إن الغرامات مضاعفة ويوجد عامل واحد على الأقل","في الليل فقط، حتى عندما لا توجد أي لافتات","في أي وقت، حتى بعد انتهاء كل الأعمال","فقط عندما تكون سيارة شرطة متوقفة في منطقة الأعمال"],"h1":"يجب أن يتحقق أمران: اللافتات والأشخاص.","h2":"في Kentucky، يمكن مضاعفة الغرامات في منطقة أعمال على الطريق السريع عندما توجد لافتات تقول ذلك ويوجد عامل واحد على الأقل.","p":"صحيح. وجود اللافتات ووجود عامل يعني غرامات مضاعفة."},"ref":{"doc":"KY","page":69}},{"id":"ky-032","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, what eyesight do you need before you can take the written test?","o":["20/80, with or without glasses","20/20, without glasses","20/40, with or without glasses","20/200, with glasses"],"h1":"Glasses or contacts are allowed for the eye test.","h2":"In Kentucky, you need vision of at least 20/40, with or without glasses or contacts, before you can move on to the written test.","p":"Right. You need 20/40 vision, and glasses are allowed."},"es":{"q":"En Kentucky, ¿qué visión necesita antes de poder tomar el examen escrito?","o":["20/80, con o sin lentes","20/20, sin lentes","20/40, con o sin lentes","20/200, con lentes"],"h1":"Se permiten lentes o lentes de contacto en el examen de la vista.","h2":"En Kentucky, usted necesita una visión de al menos 20/40, con o sin lentes o lentes de contacto, antes de pasar al examen escrito.","p":"Correcto. Necesita una visión de 20/40, y se permiten lentes."},"ref":{"doc":"KY","page":10}},{"id":"ky-033","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, you just moved here and became a resident. How soon must you get a Kentucky driver's license?","o":["Within 30 days","Within 6 months","Within 1 year","When your old license expires"],"h1":"It is about one month.","h2":"In Kentucky, a new resident must get a Kentucky driver's license within 30 days of moving here.","p":"Right. New residents have 30 days to get a Kentucky license."},"es":{"q":"En Kentucky, usted acaba de mudarse y ahora es residente. ¿En cuánto tiempo debe obtener una licencia de manejo de Kentucky?","o":["En un plazo de 30 días","En un plazo de 6 meses","En un plazo de 1 año","Cuando venza su licencia anterior"],"h1":"Es más o menos un mes.","h2":"En Kentucky, un nuevo residente debe obtener una licencia de manejo de Kentucky en un plazo de 30 días después de mudarse.","p":"Correcto. Los nuevos residentes tienen 30 días para obtener una licencia de Kentucky."},"ref":{"doc":"KY","page":13}},{"id":"ky-034","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, after you change your address or name, how soon must you get a duplicate license?","o":["Within 1 year","At your next renewal","Within 60 days","Within 10 days"],"h1":"It is a short time, less than two weeks.","h2":"In Kentucky, you must get a duplicate license within 10 days after you change your address or name, or you can get a ticket.","p":"Right. Update your license within 10 days."},"es":{"q":"En Kentucky, después de cambiar su dirección o su nombre, ¿en cuánto tiempo debe obtener un duplicado de la licencia?","o":["En un plazo de 1 año","En su próxima renovación","En un plazo de 60 días","En un plazo de 10 días"],"h1":"Es poco tiempo, menos de dos semanas.","h2":"En Kentucky, usted debe obtener un duplicado de la licencia en un plazo de 10 días después de cambiar su dirección o su nombre, o le pueden dar una multa.","p":"Correcto. Actualice su licencia en un plazo de 10 días."},"ref":{"doc":"KY","page":16}},{"id":"ky-035","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, when does a driver's license issued to someone under 21 expire?","o":["On the driver's 18th birthday","90 days after the driver's 21st birthday","On the driver's 25th birthday","One year after it is issued"],"h1":"It lasts a little past a big birthday.","h2":"In Kentucky, a license for a driver under 21 expires 90 days after the driver's 21st birthday.","p":"Right. It expires 90 days after you turn 21."},"es":{"q":"En Kentucky, ¿cuándo vence una licencia de manejo emitida a una persona menor de 21 años?","o":["El día que el conductor cumple 18 años","90 días después de que el conductor cumple 21 años","El día que el conductor cumple 25 años","Un año después de emitida"],"h1":"Dura un poco más allá de un cumpleaños importante.","h2":"En Kentucky, la licencia de un conductor menor de 21 años vence 90 días después de que el conductor cumple 21 años.","p":"Correcto. Vence 90 días después de cumplir 21 años."},"ref":{"doc":"KY","page":16}},{"id":"ky-036","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, a permit holder under 18 is convicted of a moving violation. What happens?","o":["Nothing changes once the fine is paid","The permit is extended by one year","They must wait at least 180 days from the violation to get an intermediate license","They only have to retake the vision test"],"h1":"A violation delays the next step of the teen license program.","h2":"In Kentucky, a moving violation by a permit holder under 18 adds at least 180 days, counted from the violation date, before the teen can apply for an intermediate license.","p":"Right. A violation adds at least 180 more days to the permit stage."},"es":{"q":"En Kentucky, un menor de 18 años con permiso es declarado culpable de una infracción de tránsito en movimiento. ¿Qué pasa?","o":["Nada cambia una vez que paga la multa","El permiso se extiende por un año","Debe esperar al menos 180 días desde la infracción para obtener una licencia intermedia","Solo tiene que repetir el examen de la vista"],"h1":"Una infracción retrasa el siguiente paso del programa de licencias para adolescentes.","h2":"En Kentucky, una infracción en movimiento de un menor de 18 años con permiso agrega al menos 180 días, contados desde la fecha de la infracción, antes de poder solicitar una licencia intermedia.","p":"Correcto. Una infracción agrega al menos 180 días más a la etapa del permiso."},"ref":{"doc":"KY","page":6}},{"id":"ky-037","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, the parent who signed a 16-year-old's license application withdraws responsibility. What happens?","o":["The license is canceled until a new application is signed or the teen turns 18","The teen may keep driving with a written warning","The teen pays a fee and keeps the license","The license becomes a permit for 30 days"],"h1":"The parent's signature is what allows the teen to drive.","h2":"In Kentucky, when the signing parent or guardian withdraws responsibility, the teen's permit or license is canceled until another application is signed or the teen turns 18.","p":"Right. Without the parent's signature, the license is canceled."},"es":{"q":"En Kentucky, el padre que firmó la solicitud de licencia de un joven de 16 años retira su responsabilidad. ¿Qué pasa?","o":["La licencia se cancela hasta que se firme una nueva solicitud o el joven cumpla 18 años","El joven puede seguir manejando con una advertencia por escrito","El joven paga una cuota y conserva la licencia","La licencia se convierte en un permiso por 30 días"],"h1":"La firma del padre es lo que permite manejar al joven.","h2":"En Kentucky, cuando el padre o tutor que firmó retira su responsabilidad, el permiso o la licencia del joven se cancela hasta que se firme otra solicitud o el joven cumpla 18 años.","p":"Correcto. Sin la firma del padre, la licencia se cancela."},"ref":{"doc":"KY","page":17}},{"id":"ky-038","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, police did not investigate your crash, and the damage is over $500. What must you do?","o":["Nothing, if no one was hurt","Call your insurance company only","Report it to the county clerk within 30 days","Send a written report to the Kentucky State Police within 10 days"],"h1":"The report goes to a state agency, and the deadline is short.","h2":"In Kentucky, if a crash causes more than $500 in damage and no officer investigates it, you must send a written report to the Kentucky State Police within 10 days.","p":"Right. File a written report with the State Police within 10 days."},"es":{"q":"En Kentucky, la policía no investigó su choque y los daños pasan de $500. ¿Qué debe hacer?","o":["Nada, si nadie resultó herido","Solo llamar a su compañía de seguros","Reportarlo al secretario del condado en un plazo de 30 días","Enviar un reporte por escrito a la Policía Estatal de Kentucky en un plazo de 10 días"],"h1":"El reporte va a una agencia del estado y el plazo es corto.","h2":"En Kentucky, si un choque causa más de $500 en daños y ningún oficial lo investiga, usted debe enviar un reporte por escrito a la Policía Estatal de Kentucky en un plazo de 10 días.","p":"Correcto. Envíe un reporte por escrito a la Policía Estatal en un plazo de 10 días."},"ref":{"doc":"KY","page":56}},{"id":"ky-039","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, what is the fine for a first DUI conviction within 10 years?","o":["$50 to $100","$200 to $500","$1,000 to $2,000","$5,000 to $10,000"],"h1":"Court costs are added on top of this fine.","h2":"In Kentucky, a first DUI conviction within 10 years carries a fine of $200 to $500, plus court costs, and jail time is also possible.","p":"Right. A first DUI means a fine of $200 to $500."},"es":{"q":"En Kentucky, ¿cuál es la multa por una primera condena por manejar bajo los efectos del alcohol (DUI) en 10 años?","o":["De $50 a $100","De $200 a $500","De $1,000 a $2,000","De $5,000 a $10,000"],"h1":"Los costos del tribunal se suman a esta multa.","h2":"En Kentucky, una primera condena por DUI en 10 años tiene una multa de $200 a $500, más los costos del tribunal, y también puede haber cárcel.","p":"Correcto. Un primer DUI significa una multa de $200 a $500."},"ref":{"doc":"KY","page":27}},{"id":"ky-040","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, before you take a breath, blood, or urine test after a DUI stop, how long do you get to try to call a lawyer?","o":["No time at all","Up to 2 hours","10 to 15 minutes","24 hours"],"h1":"It is a short time, but it is more than a few seconds.","h2":"In Kentucky, you get at least 10 and no more than 15 minutes to try to contact a lawyer before the test.","p":"Right. You get 10 to 15 minutes to try to reach a lawyer."},"es":{"q":"En Kentucky, antes de hacerse una prueba de aliento, sangre u orina después de una parada por DUI, ¿cuánto tiempo tiene para intentar llamar a un abogado?","o":["Nada de tiempo","Hasta 2 horas","De 10 a 15 minutos","24 horas"],"h1":"Es poco tiempo, pero más que unos segundos.","h2":"En Kentucky, usted tiene al menos 10 y no más de 15 minutos para intentar comunicarse con un abogado antes de la prueba.","p":"Correcto. Tiene de 10 a 15 minutos para intentar hablar con un abogado."},"ref":{"doc":"KY","page":27}},{"id":"ky-041","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, which passenger makes a DUI an aggravating case with mandatory jail time?","o":["A passenger under 12 years old","Any adult passenger","A passenger in the back seat","A passenger who also has a license"],"h1":"The law protects young children riding with an impaired driver.","h2":"In Kentucky, driving under the influence with a passenger under 12 years old is an aggravating circumstance that brings mandatory jail time.","p":"Right. A child under 12 in the car makes a DUI much more serious."},"es":{"q":"En Kentucky, ¿qué pasajero convierte un DUI en un caso agravado con cárcel obligatoria?","o":["Un pasajero menor de 12 años","Cualquier pasajero adulto","Un pasajero en el asiento de atrás","Un pasajero que también tiene licencia"],"h1":"La ley protege a los niños pequeños que viajan con un conductor bajo los efectos del alcohol.","h2":"En Kentucky, manejar bajo los efectos del alcohol con un pasajero menor de 12 años es una circunstancia agravante que trae cárcel obligatoria.","p":"Correcto. Un niño menor de 12 años en el carro hace que un DUI sea mucho más grave."},"ref":{"doc":"KY","page":27}},{"id":"ky-042","scope":"KY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Kentucky, a child is 40 inches tall or shorter. How must the child ride?","o":["With an adult seat belt only","On an adult's lap","In the front seat with the air bag on","In a child safety seat that meets federal standards"],"h1":"Small children need special equipment made for their size.","h2":"In Kentucky, a child 40 inches tall or shorter must be secured in a child restraint system that meets federal safety standards.","p":"Right. Children 40 inches or shorter ride in a child safety seat."},"es":{"q":"En Kentucky, un niño mide 40 pulgadas o menos. ¿Cómo debe viajar?","o":["Solo con el cinturón de seguridad de adulto","En las piernas de un adulto","En el asiento delantero con la bolsa de aire activada","En un asiento de seguridad para niños que cumpla las normas federales"],"h1":"Los niños pequeños necesitan un equipo especial hecho para su tamaño.","h2":"En Kentucky, un niño que mide 40 pulgadas o menos debe ir asegurado en un sistema de retención infantil que cumpla las normas federales de seguridad.","p":"Correcto. Los niños de 40 pulgadas o menos viajan en un asiento de seguridad para niños."},"ref":{"doc":"KY","page":31}},{"id":"ky-043","scope":"KY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Kentucky, a child taller than what height no longer has to use a booster seat?","o":["48 inches","57 inches","40 inches","66 inches"],"h1":"It is a little under 5 feet.","h2":"In Kentucky, a child of any age who is taller than 57 inches does not have to use a booster seat; children under 8 who are 40 to 57 inches tall must use one.","p":"Right. Over 57 inches, a booster seat is not required."},"es":{"q":"En Kentucky, ¿a partir de qué estatura un niño ya no tiene que usar un asiento elevado (booster)?","o":["48 pulgadas","57 pulgadas","40 pulgadas","66 pulgadas"],"h1":"Es un poco menos de 5 pies.","h2":"En Kentucky, un niño de cualquier edad que mide más de 57 pulgadas no tiene que usar asiento elevado; los menores de 8 años que miden de 40 a 57 pulgadas deben usarlo.","p":"Correcto. Con más de 57 pulgadas, no se requiere asiento elevado."},"ref":{"doc":"KY","page":31}},{"id":"ky-044","scope":"KY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Kentucky, can a police officer stop you just for not wearing a seat belt?","o":["No, only after another traffic offense","No, seat belts are only a suggestion","Yes, the seat belt law is a primary law","Yes, but only on interstates"],"h1":"Think about whether the officer needs a second reason.","h2":"In Kentucky, the seat belt law is a primary law, so an officer can stop you only because you are not wearing a seat belt.","p":"Right. You can be stopped just for not buckling up."},"es":{"q":"En Kentucky, ¿puede un policía detenerlo solo por no usar el cinturón de seguridad?","o":["No, solo después de otra infracción de tránsito","No, el cinturón es solo una sugerencia","Sí, la ley del cinturón es una ley primaria","Sí, pero solo en las autopistas interestatales"],"h1":"Piense si el oficial necesita otra razón.","h2":"En Kentucky, la ley del cinturón de seguridad es una ley primaria, así que un oficial puede detenerlo solo porque no lleva puesto el cinturón.","p":"Correcto. Lo pueden detener solo por no abrocharse el cinturón."},"ref":{"doc":"KY","page":30}},{"id":"ky-045","scope":"KY","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Kentucky, when may you turn left on a red light after you stop?","o":["Only from a one-way street onto another one-way street","At any intersection when no cars are coming","Only from a two-way street with a turn lane","Never, a left turn on red is always banned"],"h1":"Traffic on both streets must be moving in only one direction.","h2":"In Kentucky, after a full stop, you may turn left on red only from a one-way street onto another one-way street, when the way is clear.","p":"Right. Left on red is only from one one-way street onto another."},"es":{"q":"En Kentucky, ¿cuándo puede dar vuelta a la izquierda con la luz roja después de detenerse?","o":["Solo de una calle de un sentido a otra calle de un sentido","En cualquier intersección si no vienen carros","Solo desde una calle de doble sentido con carril de vuelta","Nunca, la vuelta a la izquierda en rojo siempre está prohibida"],"h1":"El tráfico en las dos calles debe ir en un solo sentido.","h2":"En Kentucky, después de detenerse por completo, puede dar vuelta a la izquierda en rojo solo de una calle de un sentido a otra calle de un sentido, cuando el camino esté libre.","p":"Correcto. La vuelta a la izquierda en rojo es solo de una calle de un sentido a otra."},"ref":{"doc":"KY","page":35}},{"id":"ky-046","scope":"KY","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Kentucky, how close may you follow an emergency vehicle?","o":["No closer than 100 feet","No closer than 500 feet","No closer than 50 feet","No closer than 1 mile"],"h1":"It is longer than a football field.","h2":"In Kentucky, it is against the law to follow an emergency vehicle closer than 500 feet.","p":"Right. Stay at least 500 feet behind an emergency vehicle."},"es":{"q":"En Kentucky, ¿qué tan cerca puede seguir a un vehículo de emergencia?","o":["No más cerca de 100 pies","No más cerca de 500 pies","No más cerca de 50 pies","No más cerca de 1 milla"],"h1":"Es más largo que un campo de fútbol americano.","h2":"En Kentucky, es ilegal seguir a un vehículo de emergencia a menos de 500 pies.","p":"Correcto. Manténgase al menos a 500 pies detrás de un vehículo de emergencia."},"ref":{"doc":"KY","page":65}},{"id":"ky-047","scope":"KY","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Kentucky, when does a funeral procession have the right-of-way at an intersection?","o":["Only when the light is green for it","Never, it must stop like other traffic","Only on interstate highways","When an escort vehicle with flashing yellow, red, or blue lights leads it"],"h1":"Look for the vehicle at the front of the procession.","h2":"In Kentucky, a funeral procession has the right-of-way at an intersection when it is led by an escort vehicle showing flashing yellow, red, or blue lights.","p":"Right. An escorted funeral procession may go through the intersection."},"es":{"q":"En Kentucky, ¿cuándo tiene el derecho de paso un cortejo fúnebre en una intersección?","o":["Solo cuando la luz está verde para el cortejo","Nunca, debe detenerse como el resto del tráfico","Solo en las autopistas interestatales","Cuando lo guía un vehículo de escolta con luces intermitentes amarillas, rojas o azules"],"h1":"Fíjese en el vehículo que va al frente del cortejo.","h2":"En Kentucky, un cortejo fúnebre tiene el derecho de paso en una intersección cuando lo guía un vehículo de escolta con luces intermitentes amarillas, rojas o azules.","p":"Correcto. Un cortejo fúnebre con escolta puede pasar por la intersección."},"ref":{"doc":"KY","page":68}},{"id":"ky-048","scope":"KY","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Kentucky, what is the speed limit in a business or residential district when no limit is posted?","o":["35 mph","25 mph","45 mph","55 mph"],"h1":"It is lower than the limit on state highways.","h2":"In Kentucky, the speed limit in a business or residential district is 35 mph when no other limit is posted.","p":"Right. It is 35 mph in business and residential districts."},"es":{"q":"En Kentucky, ¿cuál es el límite de velocidad en una zona comercial o residencial cuando no hay un límite indicado?","o":["35 mph","25 mph","45 mph","55 mph"],"h1":"Es menor que el límite en las carreteras estatales.","h2":"En Kentucky, el límite de velocidad en una zona comercial o residencial es de 35 mph cuando no hay otro límite indicado.","p":"Correcto. Es de 35 mph en zonas comerciales y residenciales."},"ref":{"doc":"KY","page":49}},{"id":"ky-049","scope":"KY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Kentucky, what is the speed limit in a parking lot that is open to the public?","o":["5 mph","25 mph","15 mph","35 mph"],"h1":"It is less than half the limit in a residential district.","h2":"In Kentucky, the speed limit in an off-street parking lot open to the public is 15 mph, whether it is owned by the public or a private owner.","p":"Right. Keep it at 15 mph in public parking lots."},"es":{"q":"En Kentucky, ¿cuál es el límite de velocidad en un estacionamiento abierto al público?","o":["5 mph","25 mph","15 mph","35 mph"],"h1":"Es menos de la mitad del límite en una zona residencial.","h2":"En Kentucky, el límite de velocidad en un estacionamiento fuera de la calle abierto al público es de 15 mph, sea de propiedad pública o privada.","p":"Correcto. Vaya a 15 mph en los estacionamientos públicos."},"ref":{"doc":"KY","page":49}},{"id":"ky-050","scope":"KY","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Kentucky, heavy rain, snow, or fog lets you see no more than 100 feet ahead. What is the fastest you can safely drive?","o":["15 mph","25 mph","45 mph","35 mph"],"h1":"It is the same as many school zone limits.","h2":"In Kentucky, when you cannot see more than 100 feet ahead, you cannot safely drive faster than 25 mph, and you should use low beams.","p":"Right. With 100 feet of view or less, stay at 25 mph or slower."},"es":{"q":"En Kentucky, por lluvia fuerte, nieve o neblina, usted no puede ver más de 100 pies adelante. ¿Cuál es la velocidad máxima segura?","o":["15 mph","25 mph","45 mph","35 mph"],"h1":"Es igual que el límite de muchas zonas escolares.","h2":"En Kentucky, cuando no puede ver más de 100 pies adelante, no puede manejar con seguridad a más de 25 mph, y debe usar las luces bajas.","p":"Correcto. Si ve 100 pies o menos, vaya a 25 mph o menos."},"ref":{"doc":"KY","page":50}},{"id":"ky-051","scope":"KY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Kentucky, during which hours must your headlights be on?","o":["Only after 9 p.m.","From one hour after sunset to one hour before sunrise","Only when there are no street lights","From half an hour after sunset to half an hour before sunrise"],"h1":"The time is measured from sunset and sunrise.","h2":"In Kentucky, headlights must be on from half an hour after sunset until half an hour before sunrise.","p":"Right. Lights on from 30 minutes after sunset to 30 minutes before sunrise."},"es":{"q":"En Kentucky, ¿durante qué horas deben estar encendidas sus luces delanteras?","o":["Solo después de las 9 p.m.","Desde una hora después de la puesta del sol hasta una hora antes del amanecer","Solo cuando no hay alumbrado público","Desde media hora después de la puesta del sol hasta media hora antes del amanecer"],"h1":"El tiempo se cuenta desde la puesta del sol y el amanecer.","h2":"En Kentucky, las luces delanteras deben estar encendidas desde media hora después de la puesta del sol hasta media hora antes del amanecer.","p":"Correcto. Luces encendidas desde 30 minutos después de la puesta del sol hasta 30 minutos antes del amanecer."},"ref":{"doc":"KY","page":54}},{"id":"ky-052","scope":"KY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kentucky, when must you dim your high beams for an oncoming vehicle?","o":["When it is within 500 feet","When it is within 100 feet","When it is within 1 mile","Only when it flashes its lights at you"],"h1":"The distance is longer than a football field.","h2":"In Kentucky, you must dim your high beams within 500 feet of an oncoming vehicle, and within 300 feet of a vehicle you are following.","p":"Right. Dim your lights within 500 feet of oncoming traffic."},"es":{"q":"En Kentucky, ¿cuándo debe bajar las luces altas por un vehículo que viene de frente?","o":["Cuando está a menos de 500 pies","Cuando está a menos de 100 pies","Cuando está a menos de 1 milla","Solo cuando le hace cambio de luces"],"h1":"La distancia es más larga que un campo de fútbol americano.","h2":"En Kentucky, debe bajar las luces altas a menos de 500 pies de un vehículo que viene de frente, y a menos de 300 pies de un vehículo que va siguiendo.","p":"Correcto. Baje las luces a menos de 500 pies del tráfico que viene de frente."},"ref":{"doc":"KY","page":68}},{"id":"la-001","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, what is the youngest age to get a learner's permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before the intermediate license.","h2":"In Louisiana you can get a learner's permit at 15, after a driver education course and the knowledge and vision tests.","p":"Right. The Louisiana learner's permit starts at 15."},"es":{"q":"En Luisiana, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la licencia intermedia.","h2":"En Luisiana usted puede obtener el permiso de aprendiz a los 15 años, después de un curso de manejo y los exámenes teórico y de la vista.","p":"Correcto. El permiso de aprendiz en Luisiana empieza a los 15."},"zh":{"q":"在 Louisiana，最小几岁可以拿到学习驾照（learner's permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"比中级驾照早一年。","h2":"在 Louisiana，上完驾驶课并通过笔试和视力检查后，你 15 岁就可以拿到学习驾照。","p":"对。Louisiana 的学习驾照从 15 岁开始。"},"vi":{"q":"Ở Louisiana, tuổi nhỏ nhất để có giấy phép học lái (learner's permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là một năm trước bằng lái trung gian.","h2":"Ở Louisiana, bạn có thể có giấy phép học lái lúc 15 tuổi, sau khi học khóa giáo dục lái xe và thi kiến thức và thị lực.","p":"Đúng. Giấy phép học lái ở Louisiana bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Louisiana, ano ang pinakabatang edad para makakuha ng learner's permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ang intermediate license.","h2":"Sa Louisiana, puwede kang kumuha ng learner's permit sa edad na 15, pagkatapos ng kurso sa driver education at ng knowledge test at vision test.","p":"Tama. Nagsisimula ang learner's permit ng Louisiana sa edad na 15."},"ar":{"q":"في Louisiana، ما أصغر عمر للحصول على تصريح تعلّم القيادة (learner's permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هو قبل الرخصة المتوسطة بسنة واحدة.","h2":"في Louisiana يمكنك الحصول على تصريح تعلّم القيادة في سن 15، بعد دورة تعليم القيادة واختبار المعرفة واختبار النظر.","p":"صحيح. يبدأ تصريح تعلّم القيادة في Louisiana في سن 15."},"ref":{"doc":"LA","page":7}},{"id":"la-002","scope":"LA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Louisiana, how long is the approved driver education course a teen must finish before the learner's permit?","o":["8 hours","16 hours","24 hours","38 hours"],"h1":"It is a little under 40 hours.","h2":"In Louisiana a teen must finish a 38-hour driver education course before the learner's permit: 30 hours in class and 8 hours behind the wheel.","p":"Right. The course is 38 hours."},"es":{"q":"En Luisiana, ¿cuántas horas dura el curso de manejo aprobado que un joven debe terminar antes del permiso de aprendiz?","o":["8 horas","16 horas","24 horas","38 horas"],"h1":"Son un poco menos de 40 horas.","h2":"En Luisiana un adolescente debe terminar un curso de manejo de 38 horas antes del permiso de aprendiz: 30 horas en clase y 8 horas al volante.","p":"Correcto. El curso es de 38 horas."},"zh":{"q":"在 Louisiana，青少年拿学习驾照前必须完成的、经过批准的驾驶课有多长？","o":["8 小时","16 小时","24 小时","38 小时"],"h1":"比 40 小时少一点。","h2":"在 Louisiana，青少年拿学习驾照前必须完成 38 小时的驾驶课：30 小时课堂学习，8 小时实际开车。","p":"对。这门课是 38 小时。"},"vi":{"q":"Ở Louisiana, khóa giáo dục lái xe được chấp thuận mà thiếu niên phải học xong trước khi có giấy phép học lái dài bao nhiêu giờ?","o":["8 giờ","16 giờ","24 giờ","38 giờ"],"h1":"Nó ít hơn 40 giờ một chút.","h2":"Ở Louisiana, thiếu niên phải học xong khóa giáo dục lái xe 38 giờ trước khi có giấy phép học lái: 30 giờ trong lớp và 8 giờ lái xe thật.","p":"Đúng. Khóa học dài 38 giờ."},"tl":{"q":"Sa Louisiana, gaano katagal ang aprubadong kurso sa driver education na dapat tapusin ng isang tinedyer bago ang learner's permit?","o":["8 oras","16 oras","24 oras","38 oras"],"h1":"Kaunti itong kulang sa 40 oras.","h2":"Sa Louisiana, dapat tapusin ng tinedyer ang 38 oras na kurso sa driver education bago ang learner's permit: 30 oras sa klase at 8 oras sa pagmamaneho.","p":"Tama. 38 oras ang kurso."},"ar":{"q":"في Louisiana، كم ساعة مدة دورة تعليم القيادة المعتمدة التي يجب أن يكملها المراهق قبل تصريح تعلّم القيادة؟","o":["8 ساعات","16 ساعة","24 ساعة","38 ساعة"],"h1":"هي أقل قليلًا من 40 ساعة.","h2":"في Louisiana يجب أن يكمل المراهق دورة تعليم قيادة مدتها 38 ساعة قبل تصريح تعلّم القيادة: 30 ساعة في الصف و8 ساعات خلف المقود.","p":"صحيح. مدة الدورة 38 ساعة."},"ref":{"doc":"LA","page":7}},{"id":"la-003","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, how long must you hold a learner's permit before you can get an intermediate license?","o":["At least 180 days","At least 30 days","At least 90 days","At least two years"],"h1":"It is about six months.","h2":"In Louisiana you must hold the learner's permit for at least 180 days before you can get an intermediate license.","p":"Right. Hold the permit at least 180 days."},"es":{"q":"En Luisiana, ¿cuánto tiempo debe tener el permiso de aprendiz antes de obtener la licencia intermedia?","o":["Por lo menos 180 días","Por lo menos 30 días","Por lo menos 90 días","Por lo menos dos años"],"h1":"Son unos seis meses.","h2":"En Luisiana usted debe tener el permiso de aprendiz por lo menos 180 días antes de obtener la licencia intermedia.","p":"Correcto. Debe tener el permiso por lo menos 180 días."},"zh":{"q":"在 Louisiana，你必须持有学习驾照多久，才能拿到中级驾照（intermediate license）？","o":["至少 180 天","至少 30 天","至少 90 天","至少两年"],"h1":"大约是六个月。","h2":"在 Louisiana，你必须持有学习驾照至少 180 天，才能拿到中级驾照。","p":"对。学习驾照至少持有 180 天。"},"vi":{"q":"Ở Louisiana, bạn phải giữ giấy phép học lái bao lâu trước khi có thể có bằng lái trung gian (intermediate license)?","o":["Ít nhất 180 ngày","Ít nhất 30 ngày","Ít nhất 90 ngày","Ít nhất hai năm"],"h1":"Khoảng sáu tháng.","h2":"Ở Louisiana, bạn phải giữ giấy phép học lái ít nhất 180 ngày trước khi có thể có bằng lái trung gian.","p":"Đúng. Giữ giấy phép ít nhất 180 ngày."},"tl":{"q":"Sa Louisiana, gaano katagal mo dapat hawak ang learner's permit bago ka makakuha ng intermediate license?","o":["Hindi bababa sa 180 araw","Hindi bababa sa 30 araw","Hindi bababa sa 90 araw","Hindi bababa sa dalawang taon"],"h1":"Mga anim na buwan ito.","h2":"Sa Louisiana, dapat mong hawak ang learner's permit nang hindi bababa sa 180 araw bago ka makakuha ng intermediate license.","p":"Tama. Hawakan ang permit nang hindi bababa sa 180 araw."},"ar":{"q":"في Louisiana، كم مدة يجب أن تحمل تصريح تعلّم القيادة قبل أن تحصل على الرخصة المتوسطة (intermediate license)؟","o":["180 يومًا على الأقل","30 يومًا على الأقل","90 يومًا على الأقل","سنتان على الأقل"],"h1":"هي حوالي ستة أشهر.","h2":"في Louisiana يجب أن تحمل تصريح تعلّم القيادة 180 يومًا على الأقل قبل أن تحصل على الرخصة المتوسطة.","p":"صحيح. احمل التصريح 180 يومًا على الأقل."},"ref":{"doc":"LA","page":7}},{"id":"la-004","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, how old must a licensed adult be to supervise a driver with a learner's permit?","o":["At least 18","At least 25","At least 21","At least 30"],"h1":"It is the legal drinking age.","h2":"In Louisiana a learner must drive with a licensed adult who is at least 21, or with a licensed brother or sister who is at least 18.","p":"Right. A supervising adult must be 21 or older."},"es":{"q":"En Luisiana, ¿qué edad debe tener un adulto con licencia para supervisar a un conductor con permiso de aprendiz?","o":["Por lo menos 18","Por lo menos 25","Por lo menos 21","Por lo menos 30"],"h1":"Es la edad legal para tomar alcohol.","h2":"En Luisiana un aprendiz debe manejar con un adulto con licencia de por lo menos 21 años, o con un hermano o hermana con licencia de por lo menos 18.","p":"Correcto. El adulto que supervisa debe tener 21 años o más."},"zh":{"q":"在 Louisiana，陪同持学习驾照的司机开车、有驾照的成年人必须几岁？","o":["至少 18 岁","至少 25 岁","至少 21 岁","至少 30 岁"],"h1":"是法定可以喝酒的年龄。","h2":"在 Louisiana，学习驾驶的人必须和一位至少 21 岁、有驾照的成年人一起开车，或者和一位至少 18 岁、有驾照的兄弟姐妹一起开车。","p":"对。陪同的成年人必须 21 岁或以上。"},"vi":{"q":"Ở Louisiana, người lớn có bằng lái phải bao nhiêu tuổi để giám sát người lái có giấy phép học lái?","o":["Ít nhất 18","Ít nhất 25","Ít nhất 21","Ít nhất 30"],"h1":"Đó là tuổi được phép uống rượu theo luật.","h2":"Ở Louisiana, người học lái phải lái cùng một người lớn có bằng lái từ 21 tuổi trở lên, hoặc cùng anh chị em có bằng lái từ 18 tuổi trở lên.","p":"Đúng. Người lớn giám sát phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Louisiana, ilang taon dapat ang isang adult na may lisensya para bantayan ang driver na may learner's permit?","o":["Hindi bababa sa 18","Hindi bababa sa 25","Hindi bababa sa 21","Hindi bababa sa 30"],"h1":"Ito ang legal na edad para uminom ng alak.","h2":"Sa Louisiana, dapat magmaneho ang learner kasama ang adult na may lisensya na hindi bababa sa 21 taong gulang, o kasama ang kapatid na may lisensya na hindi bababa sa 18 taong gulang.","p":"Tama. Dapat 21 o mas matanda ang adult na nagbabantay."},"ar":{"q":"في Louisiana، كم يجب أن يكون عمر الشخص البالغ الذي يحمل رخصة ليشرف على سائق يحمل تصريح تعلّم القيادة؟","o":["18 على الأقل","25 على الأقل","21 على الأقل","30 على الأقل"],"h1":"هو السن القانوني لشرب الكحول.","h2":"في Louisiana يجب أن يقود المتعلّم مع شخص بالغ يحمل رخصة وعمره 21 سنة على الأقل، أو مع أخ أو أخت يحمل رخصة وعمره 18 سنة على الأقل.","p":"صحيح. يجب أن يكون عمر البالغ المشرف 21 سنة أو أكثر."},"ref":{"doc":"LA","page":7}},{"id":"la-005","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, which family member may supervise a learner even though he or she is younger than 21?","o":["A licensed cousin who is 16","A licensed brother or sister who is at least 18","A grandparent without a license","Any sibling of any age"],"h1":"This person has a license and is an adult, but is not yet 21.","h2":"In Louisiana a licensed brother or sister who is at least 18 may supervise a learner's permit driver.","p":"Right. A licensed sibling 18 or older may ride with you."},"es":{"q":"En Luisiana, ¿qué familiar puede supervisar a un aprendiz aunque tenga menos de 21 años?","o":["Un primo con licencia de 16 años","Un hermano o hermana con licencia de por lo menos 18 años","Un abuelo sin licencia","Cualquier hermano de cualquier edad"],"h1":"Esta persona tiene licencia y es adulta, pero todavía no tiene 21.","h2":"En Luisiana un hermano o hermana con licencia de por lo menos 18 años puede supervisar a un conductor con permiso de aprendiz.","p":"Correcto. Un hermano con licencia de 18 años o más puede acompañarle."},"zh":{"q":"在 Louisiana，哪位家人虽然不到 21 岁，也可以陪同学习驾驶的人？","o":["16 岁、有驾照的表兄弟姐妹","至少 18 岁、有驾照的兄弟姐妹","没有驾照的祖父母","任何年龄的兄弟姐妹"],"h1":"这个人有驾照，也是成年人，但还不到 21 岁。","h2":"在 Louisiana，至少 18 岁、有驾照的兄弟姐妹可以陪同持学习驾照的司机。","p":"对。18 岁或以上、有驾照的兄弟姐妹可以和你一起坐车。"},"vi":{"q":"Ở Louisiana, người thân nào trong gia đình được giám sát người học lái dù chưa đủ 21 tuổi?","o":["Anh chị em họ 16 tuổi có bằng lái","Anh chị em ruột có bằng lái, ít nhất 18 tuổi","Ông bà không có bằng lái","Bất kỳ anh chị em nào ở bất kỳ tuổi nào"],"h1":"Người này có bằng lái và là người lớn, nhưng chưa đủ 21 tuổi.","h2":"Ở Louisiana, anh chị em ruột có bằng lái và ít nhất 18 tuổi được giám sát người lái có giấy phép học lái.","p":"Đúng. Anh chị em có bằng lái từ 18 tuổi trở lên có thể ngồi cùng bạn."},"tl":{"q":"Sa Louisiana, sinong kapamilya ang puwedeng magbantay sa learner kahit wala pa siyang 21 taong gulang?","o":["Pinsan na may lisensya na 16 taong gulang","Kapatid na may lisensya na hindi bababa sa 18 taong gulang","Lolo o lola na walang lisensya","Kahit sinong kapatid sa kahit anong edad"],"h1":"May lisensya ang taong ito at adult na, pero wala pang 21.","h2":"Sa Louisiana, puwedeng magbantay sa driver na may learner's permit ang kapatid na may lisensya at hindi bababa sa 18 taong gulang.","p":"Tama. Puwedeng sumama sa iyo ang kapatid na may lisensya na 18 o mas matanda."},"ar":{"q":"في Louisiana، أي فرد من العائلة يمكنه الإشراف على المتعلّم مع أن عمره أقل من 21 سنة؟","o":["ابن عم أو خال يحمل رخصة وعمره 16","أخ أو أخت يحمل رخصة وعمره 18 سنة على الأقل","جد أو جدة بلا رخصة","أي أخ أو أخت بأي عمر"],"h1":"هذا الشخص يحمل رخصة وهو بالغ، لكنه لم يبلغ 21 بعد.","h2":"في Louisiana يمكن للأخ أو الأخت الذي يحمل رخصة وعمره 18 سنة على الأقل أن يشرف على سائق يحمل تصريح تعلّم القيادة.","p":"صحيح. يمكن لأخ أو أخت يحمل رخصة وعمره 18 أو أكثر أن يركب معك."},"ref":{"doc":"LA","page":7}},{"id":"la-006","scope":"LA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Louisiana, how many hours of supervised driving must a learner log before the intermediate license?","o":["20 hours","30 hours","40 hours","50 hours"],"h1":"It is the same total many states use, half of one hundred.","h2":"In Louisiana a learner must log 50 hours of supervised driving before getting an intermediate license.","p":"Right. 50 supervised hours."},"es":{"q":"En Luisiana, ¿cuántas horas de manejo supervisado debe registrar un aprendiz antes de la licencia intermedia?","o":["20 horas","30 horas","40 horas","50 horas"],"h1":"Es el mismo total que usan muchos estados, la mitad de cien.","h2":"En Luisiana un aprendiz debe registrar 50 horas de manejo supervisado antes de obtener la licencia intermedia.","p":"Correcto. 50 horas supervisadas."},"zh":{"q":"在 Louisiana，学习驾驶的人拿中级驾照前，必须记录多少小时有人陪同的驾驶？","o":["20 小时","30 小时","40 小时","50 小时"],"h1":"和很多州用的总数一样，是一百的一半。","h2":"在 Louisiana，学习驾驶的人拿中级驾照前，必须记录 50 小时有人陪同的驾驶。","p":"对。50 小时有人陪同的驾驶。"},"vi":{"q":"Ở Louisiana, người học lái phải ghi lại bao nhiêu giờ lái xe có giám sát trước khi có bằng lái trung gian?","o":["20 giờ","30 giờ","40 giờ","50 giờ"],"h1":"Đó là con số nhiều tiểu bang dùng, một nửa của một trăm.","h2":"Ở Louisiana, người học lái phải ghi lại 50 giờ lái xe có giám sát trước khi có bằng lái trung gian.","p":"Đúng. 50 giờ có giám sát."},"tl":{"q":"Sa Louisiana, ilang oras ng binabantayang pagmamaneho ang dapat itala ng learner bago ang intermediate license?","o":["20 oras","30 oras","40 oras","50 oras"],"h1":"Ito ang parehong kabuuan na ginagamit ng maraming estado, kalahati ng isandaan.","h2":"Sa Louisiana, dapat magtala ang learner ng 50 oras ng binabantayang pagmamaneho bago makakuha ng intermediate license.","p":"Tama. 50 oras na may bantay."},"ar":{"q":"في Louisiana، كم ساعة من القيادة تحت الإشراف يجب أن يسجّلها المتعلّم قبل الرخصة المتوسطة؟","o":["20 ساعة","30 ساعة","40 ساعة","50 ساعة"],"h1":"هو نفس المجموع الذي تستخدمه ولايات كثيرة، نصف المئة.","h2":"في Louisiana يجب أن يسجّل المتعلّم 50 ساعة من القيادة تحت الإشراف قبل الحصول على الرخصة المتوسطة.","p":"صحيح. 50 ساعة تحت الإشراف."},"ref":{"doc":"LA","page":7}},{"id":"la-007","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, how many of the supervised practice hours must be at night?","o":["15 hours","5 hours","10 hours","25 hours"],"h1":"It is a little less than one third of the 50 hours.","h2":"In Louisiana 15 of the 50 supervised practice hours must be driven at night.","p":"Right. 15 of the hours are at night."},"es":{"q":"En Luisiana, ¿cuántas de las horas de práctica supervisada deben ser de noche?","o":["15 horas","5 horas","10 horas","25 horas"],"h1":"Es un poco menos de un tercio de las 50 horas.","h2":"En Luisiana 15 de las 50 horas de práctica supervisada deben ser de noche.","p":"Correcto. 15 de las horas son de noche."},"zh":{"q":"在 Louisiana，有人陪同的练习时间中，必须有多少小时是在夜间？","o":["15 小时","5 小时","10 小时","25 小时"],"h1":"比 50 小时的三分之一少一点。","h2":"在 Louisiana，50 小时有人陪同的练习中，有 15 小时必须在夜间开。","p":"对。其中 15 小时是在夜间。"},"vi":{"q":"Ở Louisiana, bao nhiêu giờ trong số giờ tập lái có giám sát phải lái vào ban đêm?","o":["15 giờ","5 giờ","10 giờ","25 giờ"],"h1":"Nó ít hơn một phần ba của 50 giờ một chút.","h2":"Ở Louisiana, 15 giờ trong 50 giờ tập lái có giám sát phải lái vào ban đêm.","p":"Đúng. 15 giờ là vào ban đêm."},"tl":{"q":"Sa Louisiana, ilan sa mga oras ng binabantayang pagsasanay ang dapat sa gabi?","o":["15 oras","5 oras","10 oras","25 oras"],"h1":"Kaunti itong kulang sa isang katlo ng 50 oras.","h2":"Sa Louisiana, 15 sa 50 oras ng binabantayang pagsasanay ang dapat imaneho sa gabi.","p":"Tama. 15 sa mga oras ay sa gabi."},"ar":{"q":"في Louisiana، كم ساعة من ساعات التدريب تحت الإشراف يجب أن تكون في الليل؟","o":["15 ساعة","5 ساعات","10 ساعات","25 ساعة"],"h1":"هي أقل قليلًا من ثلث الـ 50 ساعة.","h2":"في Louisiana يجب أن تكون 15 ساعة من الـ 50 ساعة من التدريب تحت الإشراف قيادة في الليل.","p":"صحيح. 15 ساعة منها في الليل."},"ref":{"doc":"LA","page":7}},{"id":"la-008","scope":"LA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Louisiana, who may send or read a text message while driving?","o":["Drivers 18 and older","Drivers on a highway only","No driver, of any age","Drivers stopped at a red light"],"h1":"The rule is the same for every age.","h2":"In Louisiana no driver of any age may write, send or read a text message while driving.","p":"Right. No driver may text while driving."},"es":{"q":"En Luisiana, ¿quién puede enviar o leer un mensaje de texto mientras maneja?","o":["Los conductores de 18 años o más","Solo los conductores en la carretera","Ningún conductor, de ninguna edad","Los conductores detenidos en un semáforo en rojo"],"h1":"La regla es igual para todas las edades.","h2":"En Luisiana ningún conductor, de ninguna edad, puede escribir, enviar ni leer un mensaje de texto mientras maneja.","p":"Correcto. Ningún conductor puede enviar textos mientras maneja."},"zh":{"q":"在 Louisiana，谁可以在开车时发送或阅读短信？","o":["18 岁及以上的司机","只有在高速公路上的司机","任何年龄的司机都不可以","在红灯前停着的司机"],"h1":"这个规定对所有年龄都一样。","h2":"在 Louisiana，任何年龄的司机开车时都不能写、发送或阅读短信。","p":"对。任何司机开车时都不能发短信。"},"vi":{"q":"Ở Louisiana, ai được gửi hoặc đọc tin nhắn khi đang lái xe?","o":["Người lái từ 18 tuổi trở lên","Chỉ người lái trên xa lộ","Không người lái nào, ở bất kỳ tuổi nào","Người lái đang dừng ở đèn đỏ"],"h1":"Quy định giống nhau cho mọi lứa tuổi.","h2":"Ở Louisiana, không người lái nào, ở bất kỳ tuổi nào, được viết, gửi hoặc đọc tin nhắn khi đang lái xe.","p":"Đúng. Không người lái nào được nhắn tin khi lái xe."},"tl":{"q":"Sa Louisiana, sino ang puwedeng magpadala o magbasa ng text message habang nagmamaneho?","o":["Mga driver na 18 pataas","Mga driver sa highway lang","Walang driver, sa kahit anong edad","Mga driver na nakahinto sa red light"],"h1":"Pareho ang patakaran sa lahat ng edad.","h2":"Sa Louisiana, walang driver sa kahit anong edad ang puwedeng sumulat, magpadala o magbasa ng text message habang nagmamaneho.","p":"Tama. Walang driver ang puwedeng mag-text habang nagmamaneho."},"ar":{"q":"في Louisiana، من يُسمح له بإرسال رسالة نصية أو قراءتها أثناء القيادة؟","o":["السائقون بعمر 18 وأكثر","السائقون على الطريق السريع فقط","لا أحد من السائقين، بأي عمر","السائقون المتوقفون عند الإشارة الحمراء"],"h1":"القاعدة نفسها لكل الأعمار.","h2":"في Louisiana لا يُسمح لأي سائق بأي عمر أن يكتب رسالة نصية أو يرسلها أو يقرأها أثناء القيادة.","p":"صحيح. لا يُسمح لأي سائق بالمراسلة أثناء القيادة."},"ref":{"doc":"LA","page":78}},{"id":"la-009","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, during which hours may an intermediate license holder not drive without a qualified adult?","o":["9 p.m. to 6 a.m.","11 p.m. to 5 a.m.","Midnight to 6 a.m.","1 a.m. to 5 a.m."],"h1":"It starts one hour before midnight.","h2":"In Louisiana an intermediate license holder may not drive from 11 p.m. to 5 a.m. unless a qualified licensed adult is in the car.","p":"Right. The restricted hours are 11 p.m. to 5 a.m."},"es":{"q":"En Luisiana, ¿en qué horario no puede manejar sin un adulto calificado quien tiene licencia intermedia?","o":["De 9 p.m. a 6 a.m.","De 11 p.m. a 5 a.m.","De medianoche a 6 a.m.","De 1 a.m. a 5 a.m."],"h1":"Empieza una hora antes de la medianoche.","h2":"En Luisiana quien tiene licencia intermedia no puede manejar de 11 p.m. a 5 a.m. salvo que vaya en el carro un adulto con licencia calificado.","p":"Correcto. El horario restringido es de 11 p.m. a 5 a.m."},"zh":{"q":"在 Louisiana，持中级驾照的人在哪些时间，没有合格的成年人陪同就不能开车？","o":["晚上 9 点到早上 6 点","晚上 11 点到早上 5 点","午夜到早上 6 点","凌晨 1 点到早上 5 点"],"h1":"它从午夜前一个小时开始。","h2":"在 Louisiana，持中级驾照的人在晚上 11 点到早上 5 点不能开车，除非车上有一位合格、有驾照的成年人。","p":"对。限制时间是晚上 11 点到早上 5 点。"},"vi":{"q":"Ở Louisiana, người có bằng lái trung gian không được lái xe mà không có người lớn đủ điều kiện trong những giờ nào?","o":["9 giờ tối đến 6 giờ sáng","11 giờ tối đến 5 giờ sáng","Nửa đêm đến 6 giờ sáng","1 giờ sáng đến 5 giờ sáng"],"h1":"Nó bắt đầu một giờ trước nửa đêm.","h2":"Ở Louisiana, người có bằng lái trung gian không được lái xe từ 11 giờ tối đến 5 giờ sáng, trừ khi có một người lớn đủ điều kiện có bằng lái ngồi trong xe.","p":"Đúng. Giờ bị hạn chế là 11 giờ tối đến 5 giờ sáng."},"tl":{"q":"Sa Louisiana, sa anong mga oras hindi puwedeng magmaneho ang may intermediate license nang walang kwalipikadong adult?","o":["9 p.m. hanggang 6 a.m.","11 p.m. hanggang 5 a.m.","Hatinggabi hanggang 6 a.m.","1 a.m. hanggang 5 a.m."],"h1":"Nagsisimula ito isang oras bago maghatinggabi.","h2":"Sa Louisiana, hindi puwedeng magmaneho ang may intermediate license mula 11 p.m. hanggang 5 a.m. maliban kung may kwalipikadong adult na may lisensya sa loob ng sasakyan.","p":"Tama. Ang bawal na oras ay 11 p.m. hanggang 5 a.m."},"ar":{"q":"في Louisiana، في أي ساعات لا يُسمح لحامل الرخصة المتوسطة بالقيادة دون شخص بالغ مؤهّل؟","o":["من 9 مساءً إلى 6 صباحًا","من 11 مساءً إلى 5 صباحًا","من منتصف الليل إلى 6 صباحًا","من 1 صباحًا إلى 5 صباحًا"],"h1":"تبدأ قبل منتصف الليل بساعة.","h2":"في Louisiana لا يُسمح لحامل الرخصة المتوسطة بالقيادة من 11 مساءً إلى 5 صباحًا إلا إذا كان في السيارة شخص بالغ مؤهّل يحمل رخصة.","p":"صحيح. الساعات الممنوعة من 11 مساءً إلى 5 صباحًا."},"ref":{"doc":"LA","page":7}},{"id":"la-010","scope":"LA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Louisiana, who may ride with an intermediate license holder so the teen may drive between 11 p.m. and 5 a.m.?","o":["Any friend over 16","A passenger with a permit","No one; driving at those hours is never allowed","A licensed parent or guardian, a licensed adult 21 or older, or a licensed sibling 18 or older"],"h1":"It is the same kind of person who may supervise a learner.","h2":"In Louisiana an intermediate driver may drive between 11 p.m. and 5 a.m. with a licensed parent or guardian, a licensed adult 21 or older, or a licensed sibling 18 or older.","p":"Right. A qualified licensed adult makes night driving allowed."},"es":{"q":"En Luisiana, ¿quién debe ir con un conductor con licencia intermedia para que pueda manejar entre 11 p.m. y 5 a.m.?","o":["Cualquier amigo mayor de 16","Un pasajero con permiso","Nadie; nunca se permite manejar a esas horas","Su padre, madre o tutor con licencia, un adulto con licencia de 21 años o más, o un hermano con licencia de 18 años o más"],"h1":"Es el mismo tipo de persona que puede supervisar a un aprendiz.","h2":"En Luisiana un conductor con licencia intermedia puede manejar entre 11 p.m. y 5 a.m. con su padre, madre o tutor con licencia, un adulto con licencia de 21 años o más, o un hermano con licencia de 18 años o más.","p":"Correcto. Un adulto calificado con licencia permite manejar de noche."},"zh":{"q":"在 Louisiana，谁和持中级驾照的青少年一起坐车，青少年就可以在晚上 11 点到早上 5 点之间开车？","o":["任何 16 岁以上的朋友","持学习驾照的乘客","没有人；这些时间永远不能开车","有驾照的父母或监护人、21 岁或以上有驾照的成年人，或 18 岁或以上有驾照的兄弟姐妹"],"h1":"和可以陪同学习驾驶的人是同一类人。","h2":"在 Louisiana，持中级驾照的司机可以在晚上 11 点到早上 5 点之间开车，只要和有驾照的父母或监护人、21 岁或以上有驾照的成年人，或 18 岁或以上有驾照的兄弟姐妹一起。","p":"对。有合格、有驾照的成年人在车上，就可以在夜间开车。"},"vi":{"q":"Ở Louisiana, ai có thể ngồi cùng người có bằng lái trung gian để thiếu niên được lái xe từ 11 giờ tối đến 5 giờ sáng?","o":["Bất kỳ người bạn nào trên 16 tuổi","Một hành khách có giấy phép học lái","Không ai; lái vào những giờ đó không bao giờ được phép","Cha mẹ hoặc người giám hộ có bằng lái, người lớn có bằng lái từ 21 tuổi trở lên, hoặc anh chị em có bằng lái từ 18 tuổi trở lên"],"h1":"Đó là cùng loại người có thể giám sát người học lái.","h2":"Ở Louisiana, người lái có bằng trung gian được lái từ 11 giờ tối đến 5 giờ sáng nếu có cha mẹ hoặc người giám hộ có bằng lái, người lớn có bằng lái từ 21 tuổi trở lên, hoặc anh chị em có bằng lái từ 18 tuổi trở lên.","p":"Đúng. Có người lớn đủ điều kiện có bằng lái thì được lái ban đêm."},"tl":{"q":"Sa Louisiana, sino ang puwedeng sumakay kasama ng may intermediate license para makapagmaneho ang tinedyer sa pagitan ng 11 p.m. at 5 a.m.?","o":["Kahit sinong kaibigan na lampas 16","Pasaherong may permit","Wala; hindi kailanman puwedeng magmaneho sa mga oras na iyon","Magulang o tagapag-alaga na may lisensya, adult na may lisensya na 21 pataas, o kapatid na may lisensya na 18 pataas"],"h1":"Ito ang parehong uri ng tao na puwedeng magbantay sa learner.","h2":"Sa Louisiana, puwedeng magmaneho ang intermediate driver sa pagitan ng 11 p.m. at 5 a.m. kung kasama ang magulang o tagapag-alaga na may lisensya, adult na may lisensya na 21 pataas, o kapatid na may lisensya na 18 pataas.","p":"Tama. Kapag may kwalipikadong adult na may lisensya, puwede ang pagmamaneho sa gabi."},"ar":{"q":"في Louisiana، من يمكنه أن يركب مع حامل الرخصة المتوسطة ليُسمح للمراهق بالقيادة بين 11 مساءً و5 صباحًا؟","o":["أي صديق عمره فوق 16","راكب يحمل تصريحًا","لا أحد؛ القيادة في هذه الساعات ممنوعة دائمًا","أحد الوالدين أو وليّ أمر يحمل رخصة، أو بالغ يحمل رخصة وعمره 21 أو أكثر، أو أخ أو أخت يحمل رخصة وعمره 18 أو أكثر"],"h1":"هو نفس نوع الشخص الذي يمكنه الإشراف على المتعلّم.","h2":"في Louisiana يُسمح لسائق الرخصة المتوسطة بالقيادة بين 11 مساءً و5 صباحًا مع أحد الوالدين أو وليّ أمر يحمل رخصة، أو بالغ يحمل رخصة وعمره 21 أو أكثر، أو أخ أو أخت يحمل رخصة وعمره 18 أو أكثر.","p":"صحيح. وجود بالغ مؤهّل يحمل رخصة يجعل القيادة الليلية مسموحة."},"ref":{"doc":"LA","page":7}},{"id":"la-011","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, between 6 p.m. and 5 a.m., how many passengers under 21 who are not immediate family may an intermediate driver carry?","o":["No more than one","No more than three","Any number","No more than two"],"h1":"The limit applies in the evening and at night.","h2":"In Louisiana an intermediate driver may carry no more than one passenger under 21, not counting immediate family, between 6 p.m. and 5 a.m.","p":"Right. Only one young passenger in the evening and at night."},"es":{"q":"En Luisiana, entre las 6 p.m. y las 5 a.m., ¿cuántos pasajeros menores de 21 que no son familia inmediata puede llevar un conductor con licencia intermedia?","o":["No más de uno","No más de tres","Cualquier cantidad","No más de dos"],"h1":"El límite se aplica en la tarde y de noche.","h2":"En Luisiana un conductor con licencia intermedia no puede llevar más de un pasajero menor de 21, sin contar la familia inmediata, entre las 6 p.m. y las 5 a.m.","p":"Correcto. Solo un pasajero joven en la tarde y de noche."},"zh":{"q":"在 Louisiana，在晚上 6 点到早上 5 点之间，持中级驾照的司机可以载几个不是直系亲属、21 岁以下的乘客？","o":["最多一个","最多三个","多少个都可以","最多两个"],"h1":"这个限制适用于傍晚和夜间。","h2":"在 Louisiana，在晚上 6 点到早上 5 点之间，持中级驾照的司机最多只能载一个 21 岁以下的乘客，直系亲属不算在内。","p":"对。傍晚和夜间只能载一个年轻乘客。"},"vi":{"q":"Ở Louisiana, từ 6 giờ tối đến 5 giờ sáng, người lái có bằng trung gian được chở bao nhiêu hành khách dưới 21 tuổi không phải người nhà trực hệ?","o":["Không quá một người","Không quá ba người","Bao nhiêu cũng được","Không quá hai người"],"h1":"Giới hạn này áp dụng vào buổi tối và ban đêm.","h2":"Ở Louisiana, từ 6 giờ tối đến 5 giờ sáng, người lái có bằng trung gian được chở không quá một hành khách dưới 21 tuổi, không tính người nhà trực hệ.","p":"Đúng. Chỉ một hành khách trẻ vào buổi tối và ban đêm."},"tl":{"q":"Sa Louisiana, mula 6 p.m. hanggang 5 a.m., ilang pasaherong wala pang 21 na hindi malapit na kapamilya ang puwedeng isakay ng intermediate driver?","o":["Hindi hihigit sa isa","Hindi hihigit sa tatlo","Kahit ilan","Hindi hihigit sa dalawa"],"h1":"Ang limitasyon ay para sa gabi at hatinggabi.","h2":"Sa Louisiana, mula 6 p.m. hanggang 5 a.m., puwedeng magsakay ang intermediate driver ng hindi hihigit sa isang pasaherong wala pang 21, hindi kasama ang malapit na kapamilya.","p":"Tama. Isang batang pasahero lang sa gabi."},"ar":{"q":"في Louisiana، بين 6 مساءً و5 صباحًا، كم راكبًا عمره أقل من 21 وليس من العائلة المباشرة يمكن لسائق الرخصة المتوسطة أن ينقله؟","o":["راكب واحد على الأكثر","ثلاثة ركاب على الأكثر","أي عدد","راكبان على الأكثر"],"h1":"الحد يُطبّق في المساء وفي الليل.","h2":"في Louisiana يمكن لسائق الرخصة المتوسطة أن ينقل راكبًا واحدًا على الأكثر عمره أقل من 21، دون حساب العائلة المباشرة، بين 6 مساءً و5 صباحًا.","p":"صحيح. راكب صغير واحد فقط في المساء وفي الليل."},"ref":{"doc":"LA","page":7}},{"id":"la-012","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, at what age can a driver move up to a full Class E license?","o":["16","18","17","21"],"h1":"It is one year after the intermediate license.","h2":"In Louisiana a driver can get a full Class E license at 17.","p":"Right. The full Class E license comes at 17."},"es":{"q":"En Luisiana, ¿a qué edad puede un conductor pasar a la licencia completa Clase E?","o":["16","18","17","21"],"h1":"Es un año después de la licencia intermedia.","h2":"En Luisiana un conductor puede obtener la licencia completa Clase E a los 17 años.","p":"Correcto. La licencia completa Clase E llega a los 17."},"zh":{"q":"在 Louisiana，司机几岁可以升级到正式的 Class E 驾照？","o":["16 岁","18 岁","17 岁","21 岁"],"h1":"是在拿到中级驾照一年以后。","h2":"在 Louisiana，司机 17 岁就可以拿到正式的 Class E 驾照。","p":"对。正式的 Class E 驾照在 17 岁。"},"vi":{"q":"Ở Louisiana, người lái được lên bằng lái đầy đủ hạng E (Class E) lúc mấy tuổi?","o":["16","18","17","21"],"h1":"Đó là một năm sau bằng lái trung gian.","h2":"Ở Louisiana, người lái có thể có bằng lái đầy đủ hạng E lúc 17 tuổi.","p":"Đúng. Bằng lái đầy đủ hạng E có lúc 17 tuổi."},"tl":{"q":"Sa Louisiana, sa anong edad puwedeng umakyat ang driver sa buong Class E license?","o":["16","18","17","21"],"h1":"Isang taon ito pagkatapos ng intermediate license.","h2":"Sa Louisiana, puwedeng makakuha ang driver ng buong Class E license sa edad na 17.","p":"Tama. Ang buong Class E license ay sa edad na 17."},"ar":{"q":"في Louisiana، في أي عمر يمكن للسائق أن ينتقل إلى رخصة كاملة من الفئة E (Class E)؟","o":["16","18","17","21"],"h1":"هو بعد الرخصة المتوسطة بسنة واحدة.","h2":"في Louisiana يمكن للسائق أن يحصل على رخصة كاملة من الفئة E في سن 17.","p":"صحيح. الرخصة الكاملة من الفئة E تأتي في سن 17."},"ref":{"doc":"LA","page":7}},{"id":"la-013","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, which record must a learner have to move up to an intermediate license?","o":["At least one safe-driving award","No at-fault crashes and no moving violations while on the permit","A perfect score on the knowledge test","At least two years with the permit"],"h1":"Think about what happened on the road during the permit.","h2":"In Louisiana a learner needs no at-fault crashes and no moving violations on the permit to get an intermediate license.","p":"Right. A clean permit record is required."},"es":{"q":"En Luisiana, ¿qué historial debe tener un aprendiz para pasar a la licencia intermedia?","o":["Por lo menos un premio de manejo seguro","Ningún choque por su culpa y ninguna infracción de tránsito con el permiso","Una calificación perfecta en el examen teórico","Por lo menos dos años con el permiso"],"h1":"Piense en lo que pasó en la carretera durante el permiso.","h2":"En Luisiana un aprendiz no debe tener choques por su culpa ni infracciones de tránsito con el permiso para obtener la licencia intermedia.","p":"Correcto. Se requiere un historial limpio con el permiso."},"zh":{"q":"在 Louisiana，学习驾驶的人必须有什么样的记录，才能升级到中级驾照？","o":["至少一个安全驾驶奖","持学习驾照期间没有自己有责任的车祸，也没有行车违规","笔试满分","持学习驾照至少两年"],"h1":"想一想持学习驾照期间在路上发生过什么。","h2":"在 Louisiana，学习驾驶的人持学习驾照期间不能有自己有责任的车祸，也不能有行车违规，才能拿到中级驾照。","p":"对。学习驾照期间的记录必须干净。"},"vi":{"q":"Ở Louisiana, người học lái phải có hồ sơ lái xe như thế nào để lên bằng lái trung gian?","o":["Ít nhất một giải thưởng lái xe an toàn","Không có tai nạn do lỗi của mình và không vi phạm luật khi đang lái trong thời gian có giấy phép học lái","Điểm tuyệt đối trong bài thi kiến thức","Có giấy phép học lái ít nhất hai năm"],"h1":"Hãy nghĩ đến những gì đã xảy ra trên đường trong thời gian có giấy phép.","h2":"Ở Louisiana, người học lái cần không có tai nạn do lỗi của mình và không vi phạm luật khi đang lái trong thời gian có giấy phép, để có bằng lái trung gian.","p":"Đúng. Cần hồ sơ sạch trong thời gian có giấy phép học lái."},"tl":{"q":"Sa Louisiana, anong record ang dapat mayroon ang learner para umakyat sa intermediate license?","o":["Hindi bababa sa isang parangal sa ligtas na pagmamaneho","Walang aksidenteng siya ang may sala at walang paglabag sa pagmamaneho habang may permit","Perpektong iskor sa knowledge test","Hindi bababa sa dalawang taon na may permit"],"h1":"Isipin kung ano ang nangyari sa kalsada habang may permit.","h2":"Sa Louisiana, kailangan ng learner na walang aksidenteng siya ang may sala at walang paglabag sa pagmamaneho habang may permit para makakuha ng intermediate license.","p":"Tama. Kailangan ang malinis na record habang may permit."},"ar":{"q":"في Louisiana، ما السجل الذي يجب أن يكون لدى المتعلّم لينتقل إلى الرخصة المتوسطة؟","o":["جائزة واحدة على الأقل للقيادة الآمنة","لا حوادث يكون هو المخطئ فيها ولا مخالفات قيادة خلال فترة التصريح","درجة كاملة في اختبار المعرفة","سنتان على الأقل مع التصريح"],"h1":"فكّر فيما حدث على الطريق خلال فترة التصريح.","h2":"في Louisiana يحتاج المتعلّم إلى ألا تكون لديه حوادث هو المخطئ فيها ولا مخالفات قيادة خلال فترة التصريح ليحصل على الرخصة المتوسطة.","p":"صحيح. يجب أن يكون سجل التصريح نظيفًا."},"ref":{"doc":"LA","page":null}},{"id":"la-014","scope":"LA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Louisiana, at what blood alcohol level is it illegal for a driver under 21 to drive?","o":["0.08 percent","0.10 percent","0.05 percent","0.02 percent"],"h1":"It is much lower than the adult limit of 0.08.","h2":"In Louisiana it is illegal for a driver under 21 to drive with a blood alcohol level of 0.02 percent or more.","p":"Right. For drivers under 21 the limit is 0.02."},"es":{"q":"En Luisiana, ¿con qué nivel de alcohol en la sangre es ilegal que maneje un conductor menor de 21?","o":["0.08 por ciento","0.10 por ciento","0.05 por ciento","0.02 por ciento"],"h1":"Es mucho más bajo que el límite de 0.08 para adultos.","h2":"En Luisiana es ilegal que un conductor menor de 21 maneje con un nivel de alcohol en la sangre de 0.02 por ciento o más.","p":"Correcto. Para menores de 21 el límite es 0.02."},"zh":{"q":"在 Louisiana，21 岁以下的司机血液酒精浓度达到多少时开车是违法的？","o":["0.08%","0.10%","0.05%","0.02%"],"h1":"这比成年人的上限 0.08 低很多。","h2":"在 Louisiana，21 岁以下的司机血液酒精浓度达到 0.02% 或更高时开车是违法的。","p":"对。21 岁以下的司机，上限是 0.02。"},"vi":{"q":"Ở Louisiana, người lái dưới 21 tuổi lái xe với nồng độ cồn trong máu từ mức nào là phạm pháp?","o":["0.08 phần trăm","0.10 phần trăm","0.05 phần trăm","0.02 phần trăm"],"h1":"Nó thấp hơn nhiều so với giới hạn 0.08 của người lớn.","h2":"Ở Louisiana, người lái dưới 21 tuổi lái xe với nồng độ cồn trong máu từ 0.02 phần trăm trở lên là phạm pháp.","p":"Đúng. Với người lái dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa Louisiana, sa anong antas ng alak sa dugo bawal magmaneho ang driver na wala pang 21?","o":["0.08 porsiyento","0.10 porsiyento","0.05 porsiyento","0.02 porsiyento"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon ng adult na 0.08.","h2":"Sa Louisiana, bawal magmaneho ang driver na wala pang 21 kung ang antas ng alak sa dugo ay 0.02 porsiyento o higit pa.","p":"Tama. Para sa mga driver na wala pang 21, ang limitasyon ay 0.02."},"ar":{"q":"في Louisiana، عند أي نسبة كحول في الدم تكون القيادة ممنوعة قانونًا على السائق الذي عمره أقل من 21؟","o":["0.08 بالمئة","0.10 بالمئة","0.05 بالمئة","0.02 بالمئة"],"h1":"هي أقل بكثير من حد البالغين وهو 0.08.","h2":"في Louisiana القيادة ممنوعة قانونًا على السائق الذي عمره أقل من 21 إذا كانت نسبة الكحول في دمه 0.02 بالمئة أو أكثر.","p":"صحيح. للسائقين الذين أعمارهم أقل من 21 الحد هو 0.02."},"ref":{"doc":"LA","page":123}},{"id":"la-015","scope":"LA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Louisiana, what does the law say about adult drivers and phones?","o":["Most phone use is banned while driving, but hands-free calls and navigation are allowed","All phone use is allowed","Texting is allowed below 25 mph","Phones are allowed only on interstates"],"h1":"Your hands should stay off the phone.","h2":"In Louisiana most phone use while driving is banned, but hands-free calls and navigation are still allowed.","p":"Right. Hands off the phone; hands-free is allowed."},"es":{"q":"En Luisiana, ¿qué dice la ley sobre los conductores adultos y los teléfonos?","o":["Se prohíbe casi todo uso del teléfono al manejar, pero se permiten llamadas con manos libres y la navegación","Se permite todo uso del teléfono","Se permite enviar mensajes por debajo de 25 mph","Solo se permite en las autopistas interestatales"],"h1":"Sus manos no deben tocar el teléfono.","h2":"En Luisiana se prohíbe casi todo uso del teléfono mientras maneja, pero todavía se permiten las llamadas con manos libres y la navegación.","p":"Correcto. Sin el teléfono en la mano; manos libres sí está permitido."},"zh":{"q":"在 Louisiana，法律对成年司机和手机有什么规定？","o":["开车时大多数手机用法都被禁止，但可以用免提打电话和导航","所有手机用法都可以","速度低于 25 mph 时可以发短信","只有在州际公路上可以用手机"],"h1":"你的手应该离开手机。","h2":"在 Louisiana，开车时大多数手机用法都被禁止，但仍然可以用免提打电话和导航。","p":"对。手不要碰手机；可以用免提。"},"vi":{"q":"Ở Louisiana, luật nói gì về người lái xe trưởng thành và điện thoại?","o":["Hầu hết việc dùng điện thoại bị cấm khi lái xe, nhưng gọi rảnh tay và chỉ đường thì được phép","Mọi việc dùng điện thoại đều được phép","Nhắn tin được phép khi chạy dưới 25 mph","Chỉ được dùng điện thoại trên xa lộ liên bang"],"h1":"Tay bạn không nên cầm điện thoại.","h2":"Ở Louisiana, hầu hết việc dùng điện thoại khi lái xe bị cấm, nhưng gọi rảnh tay và chỉ đường vẫn được phép.","p":"Đúng. Không cầm điện thoại; rảnh tay thì được phép."},"tl":{"q":"Sa Louisiana, ano ang sinasabi ng batas tungkol sa mga adult na driver at telepono?","o":["Bawal ang karamihan ng paggamit ng telepono habang nagmamaneho, pero puwede ang hands-free na tawag at navigation","Puwede ang lahat ng paggamit ng telepono","Puwedeng mag-text kapag mas mabagal sa 25 mph","Puwede lang ang telepono sa interstate"],"h1":"Dapat hindi hawak ng kamay mo ang telepono.","h2":"Sa Louisiana, bawal ang karamihan ng paggamit ng telepono habang nagmamaneho, pero puwede pa rin ang hands-free na tawag at navigation.","p":"Tama. Huwag hawakan ang telepono; puwede ang hands-free."},"ar":{"q":"في Louisiana، ماذا يقول القانون عن السائقين البالغين والهواتف؟","o":["معظم استخدام الهاتف ممنوع أثناء القيادة، لكن المكالمات دون استخدام اليدين والملاحة مسموحة","كل استخدام للهاتف مسموح","المراسلة مسموحة تحت 25 mph","الهواتف مسموحة على الطرق السريعة بين الولايات فقط"],"h1":"يجب أن تبقى يداك بعيدتين عن الهاتف.","h2":"في Louisiana معظم استخدام الهاتف أثناء القيادة ممنوع، لكن المكالمات دون استخدام اليدين والملاحة ما زالت مسموحة.","p":"صحيح. لا تمسك الهاتف بيدك؛ الاستخدام دون اليدين مسموح."},"ref":{"doc":"LA","page":78}},{"id":"la-016","scope":"LA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Louisiana, what is the fine for using a hand-held phone while driving outside a school or construction zone, when there is no crash?","o":["$25","$500","$100","$1,000"],"h1":"In a school or construction zone the fine is $250.","h2":"In Louisiana the fine for using a hand-held phone while driving outside a school or construction zone is $100, and it doubles if there is a crash.","p":"Right. The fine is $100 outside those zones."},"es":{"q":"En Luisiana, ¿cuál es la multa por usar un teléfono en la mano mientras maneja fuera de una zona escolar o de construcción, si no hay choque?","o":["$25","$500","$100","$1,000"],"h1":"En una zona escolar o de construcción la multa es de $250.","h2":"En Luisiana la multa por usar un teléfono en la mano mientras maneja fuera de una zona escolar o de construcción es de $100, y se duplica si hay un choque.","p":"Correcto. La multa es de $100 fuera de esas zonas."},"zh":{"q":"在 Louisiana，在学校区域或施工区以外开车时手持手机，没有发生车祸，罚款多少？","o":["$25","$500","$100","$1,000"],"h1":"在学校区域或施工区，罚款是 $250。","h2":"在 Louisiana，在学校区域或施工区以外开车时手持手机，罚款是 $100，如果发生车祸，罚款加倍。","p":"对。在这些区域以外，罚款是 $100。"},"vi":{"q":"Ở Louisiana, tiền phạt cho việc cầm điện thoại khi lái xe bên ngoài khu trường học hoặc khu công trường, khi không có tai nạn, là bao nhiêu?","o":["$25","$500","$100","$1,000"],"h1":"Trong khu trường học hoặc khu công trường, tiền phạt là $250.","h2":"Ở Louisiana, tiền phạt cho việc cầm điện thoại khi lái xe bên ngoài khu trường học hoặc khu công trường là $100, và gấp đôi nếu có tai nạn.","p":"Đúng. Tiền phạt là $100 bên ngoài những khu đó."},"tl":{"q":"Sa Louisiana, magkano ang multa sa paggamit ng hawak na telepono habang nagmamaneho sa labas ng school zone o construction zone, kapag walang aksidente?","o":["$25","$500","$100","$1,000"],"h1":"Sa school zone o construction zone, $250 ang multa.","h2":"Sa Louisiana, $100 ang multa sa paggamit ng hawak na telepono habang nagmamaneho sa labas ng school zone o construction zone, at doble ito kapag may aksidente.","p":"Tama. $100 ang multa sa labas ng mga zone na iyon."},"ar":{"q":"في Louisiana، كم غرامة استخدام هاتف باليد أثناء القيادة خارج منطقة مدرسة أو منطقة أعمال بناء، عندما لا يكون هناك حادث؟","o":["$25","$500","$100","$1,000"],"h1":"في منطقة المدرسة أو منطقة أعمال البناء الغرامة $250.","h2":"في Louisiana غرامة استخدام هاتف باليد أثناء القيادة خارج منطقة مدرسة أو منطقة أعمال بناء هي $100، وتتضاعف إذا كان هناك حادث.","p":"صحيح. الغرامة $100 خارج هذه المناطق."},"ref":{"doc":"LA","page":null}},{"id":"la-017","scope":"LA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Louisiana, what is the fine for using a hand-held phone while driving in a school or construction zone, when there is no crash?","o":["$75","$250","$50","$2,000"],"h1":"It is more than twice the $100 fine outside those zones.","h2":"In Louisiana the fine for using a hand-held phone while driving in a school or construction zone is $250.","p":"Right. The fine is $250 in a school or work zone."},"es":{"q":"En Luisiana, ¿cuál es la multa por usar un teléfono en la mano mientras maneja en una zona escolar o de construcción, si no hay choque?","o":["$75","$250","$50","$2,000"],"h1":"Es más del doble de la multa de $100 fuera de esas zonas.","h2":"En Luisiana la multa por usar un teléfono en la mano mientras maneja en una zona escolar o de construcción es de $250.","p":"Correcto. La multa es de $250 en una zona escolar o de obras."},"zh":{"q":"在 Louisiana，在学校区域或施工区开车时手持手机，没有发生车祸，罚款多少？","o":["$75","$250","$50","$2,000"],"h1":"比这些区域以外的 $100 罚款的两倍还多。","h2":"在 Louisiana，在学校区域或施工区开车时手持手机，罚款是 $250。","p":"对。在学校区域或施工区，罚款是 $250。"},"vi":{"q":"Ở Louisiana, tiền phạt cho việc cầm điện thoại khi lái xe trong khu trường học hoặc khu công trường, khi không có tai nạn, là bao nhiêu?","o":["$75","$250","$50","$2,000"],"h1":"Nó nhiều hơn gấp đôi tiền phạt $100 bên ngoài những khu đó.","h2":"Ở Louisiana, tiền phạt cho việc cầm điện thoại khi lái xe trong khu trường học hoặc khu công trường là $250.","p":"Đúng. Tiền phạt là $250 trong khu trường học hoặc khu công trường."},"tl":{"q":"Sa Louisiana, magkano ang multa sa paggamit ng hawak na telepono habang nagmamaneho sa school zone o construction zone, kapag walang aksidente?","o":["$75","$250","$50","$2,000"],"h1":"Higit ito sa doble ng $100 na multa sa labas ng mga zone na iyon.","h2":"Sa Louisiana, $250 ang multa sa paggamit ng hawak na telepono habang nagmamaneho sa school zone o construction zone.","p":"Tama. $250 ang multa sa school zone o work zone."},"ar":{"q":"في Louisiana، كم غرامة استخدام هاتف باليد أثناء القيادة في منطقة مدرسة أو منطقة أعمال بناء، عندما لا يكون هناك حادث؟","o":["$75","$250","$50","$2,000"],"h1":"هي أكثر من ضعف غرامة $100 خارج هذه المناطق.","h2":"في Louisiana غرامة استخدام هاتف باليد أثناء القيادة في منطقة مدرسة أو منطقة أعمال بناء هي $250.","p":"صحيح. الغرامة $250 في منطقة مدرسة أو منطقة عمل."},"ref":{"doc":"LA","page":null}},{"id":"la-018","scope":"LA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Louisiana, which stopped vehicles does the expanded Move Over law cover, in addition to emergency vehicles?","o":["Only police cars","Only school buses","Only tow trucks","Disabled vehicles showing hazard lights, flashing lights or another warning device"],"h1":"Think of any car broken down at the side of the road with its warning lights on.","h2":"In Louisiana the expanded Move Over law also covers disabled or stopped vehicles that show hazard lights, flashing lights or another emergency warning device.","p":"Right. Move over for any stopped vehicle showing warning lights."},"es":{"q":"En Luisiana, ¿qué vehículos detenidos cubre la ley ampliada \"Move Over\", además de los vehículos de emergencia?","o":["Solo las patrullas de policía","Solo los autobuses escolares","Solo las grúas","Vehículos descompuestos con luces de emergencia, luces intermitentes u otro aviso de peligro"],"h1":"Piense en cualquier carro descompuesto al lado de la carretera con sus luces de aviso encendidas.","h2":"En Luisiana la ley ampliada \"Move Over\" también cubre los vehículos descompuestos o detenidos que muestran luces de emergencia, luces intermitentes u otro aviso de peligro.","p":"Correcto. Cámbiese de carril ante cualquier vehículo detenido con luces de aviso."},"zh":{"q":"在 Louisiana，扩大后的 Move Over 法除了急救车辆以外，还保护哪些停着的车辆？","o":["只有警车","只有校车","只有拖车","开着双闪灯、闪灯或其他警示装置的故障车辆"],"h1":"想一想任何在路边坏了、开着警示灯的车。","h2":"在 Louisiana，扩大后的 Move Over 法也保护开着双闪灯、闪灯或其他紧急警示装置的故障车辆或停着的车辆。","p":"对。遇到任何开着警示灯、停着的车辆都要换道让开。"},"vi":{"q":"Ở Louisiana, luật Tránh Sang Làn Khác (Move Over law) mở rộng áp dụng cho những xe đang dừng nào, ngoài xe khẩn cấp?","o":["Chỉ xe cảnh sát","Chỉ xe buýt trường học","Chỉ xe kéo","Xe bị hỏng đang bật đèn cảnh báo, đèn nhấp nháy hoặc thiết bị cảnh báo khác"],"h1":"Hãy nghĩ đến bất kỳ xe nào bị hỏng bên lề đường và đang bật đèn cảnh báo.","h2":"Ở Louisiana, luật Tránh Sang Làn Khác mở rộng cũng áp dụng cho xe bị hỏng hoặc đang dừng có bật đèn cảnh báo, đèn nhấp nháy hoặc thiết bị cảnh báo khẩn cấp khác.","p":"Đúng. Tránh sang làn khác khi gặp bất kỳ xe đang dừng nào bật đèn cảnh báo."},"tl":{"q":"Sa Louisiana, aling mga nakahintong sasakyan ang sakop ng pinalawak na Move Over law, bukod sa mga emergency vehicle?","o":["Mga sasakyan ng pulis lang","Mga school bus lang","Mga tow truck lang","Mga sirang sasakyan na may hazard lights, kumikislap na ilaw o ibang babalang gamit"],"h1":"Isipin ang kahit anong sirang kotse sa gilid ng kalsada na nakabukas ang babalang ilaw.","h2":"Sa Louisiana, sakop din ng pinalawak na Move Over law ang mga sira o nakahintong sasakyan na may hazard lights, kumikislap na ilaw o ibang babalang gamit para sa emergency.","p":"Tama. Lumipat ng lane para sa kahit anong nakahintong sasakyan na may babalang ilaw."},"ar":{"q":"في Louisiana، ما المركبات المتوقفة التي يشملها قانون الابتعاد (Move Over law) الموسّع، إضافة إلى مركبات الطوارئ؟","o":["سيارات الشرطة فقط","الحافلات المدرسية فقط","شاحنات السحب فقط","المركبات المعطّلة التي تشغّل أضواء التحذير أو أضواء وامضة أو أداة تحذير أخرى"],"h1":"فكّر في أي سيارة معطّلة على جانب الطريق وأضواء التحذير فيها مشغّلة.","h2":"في Louisiana يشمل قانون الابتعاد الموسّع أيضًا المركبات المعطّلة أو المتوقفة التي تشغّل أضواء التحذير أو أضواء وامضة أو أداة تحذير طوارئ أخرى.","p":"صحيح. ابتعد عن أي مركبة متوقفة تشغّل أضواء التحذير."},"ref":{"doc":"LA","page":null}},{"id":"la-019","scope":"LA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Louisiana, what should you do under the Move Over law on a two-lane road where you cannot change lanes?","o":["Slow down","Keep the same speed","Honk your horn","Stop in your lane"],"h1":"If you cannot move away, change something else.","h2":"In Louisiana, when you cannot change lanes, such as on a two-lane road, you must slow down as you pass the stopped vehicle.","p":"Right. If you cannot move over, slow down."},"es":{"q":"En Luisiana, según la ley \"Move Over\", ¿qué debe hacer en una carretera de dos carriles donde no puede cambiarse de carril?","o":["Bajar la velocidad","Seguir a la misma velocidad","Tocar la bocina","Detenerse en su carril"],"h1":"Si no puede alejarse, cambie otra cosa.","h2":"En Luisiana, cuando no puede cambiarse de carril, por ejemplo en una carretera de dos carriles, debe bajar la velocidad al pasar el vehículo detenido.","p":"Correcto. Si no puede cambiarse de carril, baje la velocidad."},"zh":{"q":"在 Louisiana，在不能换道的双车道道路上，按照 Move Over 法你应该做什么？","o":["减速","保持原来的速度","按喇叭","在你的车道停下"],"h1":"如果你不能离开，就改变别的东西。","h2":"在 Louisiana，当你不能换道时，例如在双车道道路上，你开过停着的车辆时必须减速。","p":"对。如果不能换道让开，就减速。"},"vi":{"q":"Ở Louisiana, theo luật Tránh Sang Làn Khác, bạn nên làm gì trên đường hai làn khi không thể đổi làn?","o":["Chạy chậm lại","Giữ nguyên tốc độ","Bóp còi","Dừng lại trong làn của mình"],"h1":"Nếu không thể tránh ra xa, hãy thay đổi điều khác.","h2":"Ở Louisiana, khi bạn không thể đổi làn, ví dụ trên đường hai làn, bạn phải chạy chậm lại khi đi qua xe đang dừng.","p":"Đúng. Nếu không thể tránh sang làn khác, hãy chạy chậm lại."},"tl":{"q":"Sa Louisiana, ano ang dapat mong gawin ayon sa Move Over law sa kalsadang may dalawang lane kung saan hindi ka makalipat ng lane?","o":["Bagalan ang takbo","Panatilihin ang parehong bilis","Bumusina","Huminto sa iyong lane"],"h1":"Kung hindi ka makalayo, baguhin ang ibang bagay.","h2":"Sa Louisiana, kapag hindi ka makalipat ng lane, gaya sa kalsadang may dalawang lane, dapat mong bagalan ang takbo habang dumadaan sa nakahintong sasakyan.","p":"Tama. Kung hindi ka makalipat ng lane, bagalan ang takbo."},"ar":{"q":"في Louisiana، ماذا يجب أن تفعل حسب قانون الابتعاد على طريق بمسارين لا يمكنك فيه تغيير المسار؟","o":["خفّف السرعة","حافظ على السرعة نفسها","استخدم البوق","توقّف في مسارك"],"h1":"إذا لم تستطع الابتعاد، غيّر شيئًا آخر.","h2":"في Louisiana، عندما لا تستطيع تغيير المسار، مثل طريق بمسارين، يجب أن تخفّف السرعة وأنت تمر بجانب المركبة المتوقفة.","p":"صحيح. إذا لم تستطع الابتعاد، خفّف السرعة."},"ref":{"doc":"LA","page":30}},{"id":"la-020","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, what is the youngest age to get an intermediate license?","o":["15","17","16","18"],"h1":"It is one year after the earliest learner's permit.","h2":"In Louisiana you can get an intermediate license at 16, after holding the learner's permit for at least 180 days.","p":"Right. The intermediate license starts at 16."},"es":{"q":"En Luisiana, ¿cuál es la edad mínima para obtener la licencia intermedia?","o":["15","17","16","18"],"h1":"Es un año después de la edad mínima para el permiso de aprendiz.","h2":"En Luisiana usted puede obtener la licencia intermedia a los 16 años, después de tener el permiso de aprendiz por lo menos 180 días.","p":"Correcto. La licencia intermedia empieza a los 16."},"zh":{"q":"在 Louisiana，最小几岁可以拿到中级驾照？","o":["15 岁","17 岁","16 岁","18 岁"],"h1":"比最早拿学习驾照的年龄晚一年。","h2":"在 Louisiana，持有学习驾照至少 180 天后，你 16 岁就可以拿到中级驾照。","p":"对。中级驾照从 16 岁开始。"},"vi":{"q":"Ở Louisiana, tuổi nhỏ nhất để có bằng lái trung gian là bao nhiêu?","o":["15","17","16","18"],"h1":"Đó là một năm sau tuổi sớm nhất để có giấy phép học lái.","h2":"Ở Louisiana, bạn có thể có bằng lái trung gian lúc 16 tuổi, sau khi giữ giấy phép học lái ít nhất 180 ngày.","p":"Đúng. Bằng lái trung gian bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Louisiana, ano ang pinakabatang edad para makakuha ng intermediate license?","o":["15","17","16","18"],"h1":"Isang taon ito pagkatapos ng pinakamaagang learner's permit.","h2":"Sa Louisiana, puwede kang kumuha ng intermediate license sa edad na 16, pagkatapos mong hawakan ang learner's permit nang hindi bababa sa 180 araw.","p":"Tama. Nagsisimula ang intermediate license sa edad na 16."},"ar":{"q":"في Louisiana، ما أصغر عمر للحصول على الرخصة المتوسطة؟","o":["15","17","16","18"],"h1":"هو بعد أبكر عمر لتصريح تعلّم القيادة بسنة واحدة.","h2":"في Louisiana يمكنك الحصول على الرخصة المتوسطة في سن 16، بعد أن تحمل تصريح تعلّم القيادة 180 يومًا على الأقل.","p":"صحيح. تبدأ الرخصة المتوسطة في سن 16."},"ref":{"doc":"LA","page":7}},{"id":"la-021","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, what score do you need to pass the knowledge test?","o":["60 percent","70 percent","80 percent","90 percent"],"h1":"You must get most of the questions right, but not nearly all.","h2":"In Louisiana you must answer at least 80 percent of the knowledge test questions correctly to pass.","p":"Right. The passing score is 80 percent."},"es":{"q":"En Luisiana, ¿qué puntaje necesita para aprobar el examen teórico?","o":["60 por ciento","70 por ciento","80 por ciento","90 por ciento"],"h1":"Debe contestar bien la mayoría de las preguntas, pero no casi todas.","h2":"En Luisiana usted debe contestar bien al menos el 80 por ciento de las preguntas del examen teórico para aprobar.","p":"Correcto. El puntaje para aprobar es 80 por ciento."},"zh":{"q":"在 Louisiana，笔试（knowledge test）要考多少分才能通过？","o":["60%","70%","80%","90%"],"h1":"大部分题目要答对，但不用几乎全对。","h2":"在 Louisiana，笔试至少要答对 80% 的题目才能通过。","p":"对。及格分数是 80%。"},"vi":{"q":"Ở Louisiana, bạn cần bao nhiêu điểm để đậu bài thi kiến thức (knowledge test)?","o":["60 phần trăm","70 phần trăm","80 phần trăm","90 phần trăm"],"h1":"Bạn phải trả lời đúng phần lớn câu hỏi, nhưng không cần gần như tất cả.","h2":"Ở Louisiana, bạn phải trả lời đúng ít nhất 80 phần trăm câu hỏi của bài thi kiến thức để đậu.","p":"Đúng. Điểm đậu là 80 phần trăm."},"tl":{"q":"Sa Louisiana, anong iskor ang kailangan mo para pumasa sa knowledge test?","o":["60 porsiyento","70 porsiyento","80 porsiyento","90 porsiyento"],"h1":"Dapat tama ang karamihan ng tanong, pero hindi halos lahat.","h2":"Sa Louisiana, dapat tama ang sagot mo sa hindi bababa sa 80 porsiyento ng mga tanong sa knowledge test para pumasa.","p":"Tama. Ang passing score ay 80 porsiyento."},"ar":{"q":"في Louisiana، ما الدرجة التي تحتاجها لتنجح في اختبار المعرفة (knowledge test)؟","o":["60 بالمئة","70 بالمئة","80 بالمئة","90 بالمئة"],"h1":"يجب أن تجيب عن معظم الأسئلة بشكل صحيح، لكن ليس عن كلها تقريبًا.","h2":"في Louisiana يجب أن تجيب بشكل صحيح عن 80 بالمئة على الأقل من أسئلة اختبار المعرفة لتنجح.","p":"صحيح. درجة النجاح هي 80 بالمئة."},"ref":{"doc":"LA","page":8}},{"id":"la-022","scope":"LA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Louisiana, until what age should a child ride in a rear-facing car seat?","o":["At least age 2","At least 6 months","At least age 4","At least age 1"],"h1":"It is longer than the first year of life.","h2":"In Louisiana a child rides in a rear-facing car seat from birth until at least age 2.","p":"Right. Rear-facing until at least age 2."},"es":{"q":"En Luisiana, ¿hasta qué edad debe viajar un niño en un asiento de seguridad mirando hacia atrás?","o":["Al menos hasta los 2 años","Al menos hasta los 6 meses","Al menos hasta los 4 años","Al menos hasta 1 año"],"h1":"Es más que el primer año de vida.","h2":"En Luisiana un niño viaja en un asiento de seguridad mirando hacia atrás desde que nace hasta al menos los 2 años.","p":"Correcto. Mirando hacia atrás hasta al menos los 2 años."},"zh":{"q":"在 Louisiana，孩子应该坐后向式儿童安全座椅坐到几岁？","o":["至少 2 岁","至少 6 个月","至少 4 岁","至少 1 岁"],"h1":"比出生后的第一年更久。","h2":"在 Louisiana，孩子从出生起就坐后向式儿童安全座椅，至少坐到 2 岁。","p":"对。后向式座椅至少坐到 2 岁。"},"vi":{"q":"Ở Louisiana, trẻ em nên ngồi ghế ô tô quay về phía sau đến bao nhiêu tuổi?","o":["Ít nhất 2 tuổi","Ít nhất 6 tháng","Ít nhất 4 tuổi","Ít nhất 1 tuổi"],"h1":"Lâu hơn năm đầu tiên của cuộc đời.","h2":"Ở Louisiana, trẻ em ngồi ghế ô tô quay về phía sau từ lúc mới sinh đến ít nhất 2 tuổi.","p":"Đúng. Quay về phía sau đến ít nhất 2 tuổi."},"tl":{"q":"Sa Louisiana, hanggang anong edad dapat nakaupo ang bata sa car seat na nakaharap sa likod?","o":["Hanggang edad 2 man lang","Hanggang 6 na buwan man lang","Hanggang edad 4 man lang","Hanggang edad 1 man lang"],"h1":"Mas matagal ito kaysa sa unang taon ng buhay.","h2":"Sa Louisiana, nakaupo ang bata sa car seat na nakaharap sa likod mula pagkapanganak hanggang edad 2 man lang.","p":"Tama. Nakaharap sa likod hanggang edad 2 man lang."},"ar":{"q":"في Louisiana، حتى أي عمر يجب أن يجلس الطفل في مقعد سيارة مواجه للخلف؟","o":["سن 2 على الأقل","6 أشهر على الأقل","سن 4 على الأقل","سن 1 على الأقل"],"h1":"هو أطول من السنة الأولى من العمر.","h2":"في Louisiana يجلس الطفل في مقعد سيارة مواجه للخلف من الولادة حتى سن 2 على الأقل.","p":"صحيح. المقعد المواجه للخلف حتى سن 2 على الأقل."},"ref":{"doc":"LA","page":40}},{"id":"la-023","scope":"LA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Louisiana, children younger than what age should ride in the back seat when one is available?","o":["8","10","16","13"],"h1":"It is a teen age, but a young one.","h2":"In Louisiana children younger than 13 must ride in the back seat, buckled in, when a back seat is available.","p":"Right. Under 13 rides in the back seat."},"es":{"q":"En Luisiana, ¿los niños menores de qué edad deben viajar en el asiento de atrás cuando hay uno disponible?","o":["8","10","16","13"],"h1":"Es una edad de adolescente, pero joven.","h2":"En Luisiana los niños menores de 13 años deben viajar en el asiento de atrás, con el cinturón puesto, cuando hay asiento de atrás disponible.","p":"Correcto. Los menores de 13 van en el asiento de atrás."},"zh":{"q":"在 Louisiana，有后座时，几岁以下的孩子应该坐在后座？","o":["8","10","16","13"],"h1":"是青少年的年龄，但比较小。","h2":"在 Louisiana，有后座时，13 岁以下的孩子必须坐在后座并系好安全带。","p":"对。13 岁以下坐后座。"},"vi":{"q":"Ở Louisiana, trẻ em dưới bao nhiêu tuổi nên ngồi ở ghế sau khi có ghế sau?","o":["8","10","16","13"],"h1":"Đó là tuổi thiếu niên, nhưng còn nhỏ.","h2":"Ở Louisiana, trẻ em dưới 13 tuổi phải ngồi ở ghế sau và thắt dây an toàn khi có ghế sau.","p":"Đúng. Dưới 13 tuổi ngồi ghế sau."},"tl":{"q":"Sa Louisiana, ang mga batang mas bata sa anong edad ang dapat umupo sa likurang upuan kapag mayroon nito?","o":["8","10","16","13"],"h1":"Edad ito ng teenager, pero bata pa.","h2":"Sa Louisiana, ang mga batang mas bata sa 13 ay dapat umupo sa likurang upuan, nakasuot ng seat belt, kapag may likurang upuan.","p":"Tama. Ang mas bata sa 13 ay umuupo sa likod."},"ar":{"q":"في Louisiana، الأطفال الأصغر من أي عمر يجب أن يجلسوا في المقعد الخلفي عندما يكون متاحًا؟","o":["8","10","16","13"],"h1":"هو عمر مراهق، لكنه صغير.","h2":"في Louisiana يجب على الأطفال الأصغر من 13 سنة الجلوس في المقعد الخلفي مع ربط الحزام، عندما يكون هناك مقعد خلفي.","p":"صحيح. من هو أصغر من 13 يجلس في المقعد الخلفي."},"ref":{"doc":"LA","page":40}},{"id":"la-024","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, where must your proof of insurance be kept?","o":["At home in a safe place","In the vehicle at all times","Only with your insurance agent","At the Office of Motor Vehicles"],"h1":"An officer may ask to see it during a stop.","h2":"In Louisiana the law says your insurance card must be in the vehicle at all times.","p":"Right. Keep the insurance card in the vehicle."},"es":{"q":"En Luisiana, ¿dónde debe guardar su comprobante de seguro?","o":["En casa, en un lugar seguro","En el vehículo en todo momento","Solo con su agente de seguros","En la Oficina de Vehículos Motorizados"],"h1":"Un policía puede pedir verlo cuando lo detiene.","h2":"En Luisiana la ley dice que su tarjeta de seguro debe estar en el vehículo en todo momento.","p":"Correcto. Guarde la tarjeta de seguro en el vehículo."},"zh":{"q":"在 Louisiana，你的保险证明必须放在哪里？","o":["放在家里安全的地方","一直放在车里","只放在保险经纪人那里","放在机动车辆办公室（Office of Motor Vehicles）"],"h1":"警察拦车时可能会要求看。","h2":"在 Louisiana，法律规定你的保险卡必须一直放在车里。","p":"对。把保险卡放在车里。"},"vi":{"q":"Ở Louisiana, giấy chứng nhận bảo hiểm của bạn phải được để ở đâu?","o":["Ở nhà, tại một nơi an toàn","Trong xe mọi lúc","Chỉ ở chỗ đại lý bảo hiểm của bạn","Tại Văn phòng Xe cơ giới (Office of Motor Vehicles)"],"h1":"Cảnh sát có thể yêu cầu xem khi chặn xe.","h2":"Ở Louisiana, luật quy định thẻ bảo hiểm của bạn phải luôn ở trong xe.","p":"Đúng. Hãy để thẻ bảo hiểm trong xe."},"tl":{"q":"Sa Louisiana, saan dapat nakalagay ang patunay ng iyong insurance?","o":["Sa bahay, sa ligtas na lugar","Sa sasakyan sa lahat ng oras","Sa insurance agent mo lang","Sa Office of Motor Vehicles"],"h1":"Puwede itong hingin ng pulis kapag pinara ka.","h2":"Sa Louisiana, sinasabi ng batas na dapat nasa sasakyan ang insurance card mo sa lahat ng oras.","p":"Tama. Itago ang insurance card sa sasakyan."},"ar":{"q":"في Louisiana، أين يجب أن تحتفظ بإثبات التأمين؟","o":["في البيت في مكان آمن","في السيارة طوال الوقت","مع وكيل التأمين فقط","في مكتب المركبات (Office of Motor Vehicles)"],"h1":"قد يطلب الشرطي رؤيته عندما يوقفك.","h2":"في Louisiana يقول القانون إن بطاقة التأمين يجب أن تكون في السيارة طوال الوقت.","p":"صحيح. احتفظ ببطاقة التأمين في السيارة."},"ref":{"doc":"LA","page":7}},{"id":"la-025","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, which shorter course may a new driver age 18 or older take instead of the 38-hour driver education course?","o":["A 2-hour online video","A 4-hour defensive driving class","A 6-hour pre-licensing course plus 8 hours behind the wheel","No course is needed at all"],"h1":"Adults still need some classroom time and some time driving.","h2":"In Louisiana a new driver age 18 or older may take a 6-hour pre-licensing course and an 8-hour behind-the-wheel course instead of the 38-hour course.","p":"Right. Adults may take 6 hours of class plus 8 hours of driving."},"es":{"q":"En Luisiana, ¿qué curso más corto puede tomar un conductor nuevo de 18 años o más en lugar del curso de educación vial de 38 horas?","o":["Un video en línea de 2 horas","Una clase de manejo defensivo de 4 horas","Un curso previo a la licencia de 6 horas más 8 horas al volante","No necesita ningún curso"],"h1":"Los adultos también necesitan algo de clase y algo de práctica manejando.","h2":"En Luisiana un conductor nuevo de 18 años o más puede tomar un curso previo a la licencia de 6 horas y un curso al volante de 8 horas en lugar del curso de 38 horas.","p":"Correcto. Los adultos pueden tomar 6 horas de clase más 8 horas manejando."},"zh":{"q":"在 Louisiana，18 岁或以上的新司机可以上哪种较短的课程，来代替 38 小时的驾驶教育课程？","o":["2 小时的网上视频","4 小时的防御性驾驶课","6 小时的考照前课程，加上 8 小时的实际驾驶","完全不需要上课"],"h1":"成年人仍然需要一些课堂时间和一些开车时间。","h2":"在 Louisiana，18 岁或以上的新司机可以上 6 小时的考照前课程和 8 小时的实际驾驶课程，来代替 38 小时的课程。","p":"对。成年人可以上 6 小时的课，再加 8 小时的开车。"},"vi":{"q":"Ở Louisiana, người mới lái xe từ 18 tuổi trở lên có thể học khóa ngắn hơn nào thay cho khóa giáo dục lái xe 38 giờ?","o":["Một video trực tuyến 2 giờ","Một lớp lái xe phòng thủ 4 giờ","Một khóa trước khi cấp bằng 6 giờ cộng 8 giờ lái xe thực tế","Không cần học khóa nào cả"],"h1":"Người lớn vẫn cần một ít thời gian học trên lớp và một ít thời gian lái xe.","h2":"Ở Louisiana, người mới lái xe từ 18 tuổi trở lên có thể học khóa trước khi cấp bằng 6 giờ và khóa lái xe thực tế 8 giờ thay cho khóa 38 giờ.","p":"Đúng. Người lớn có thể học 6 giờ trên lớp cộng 8 giờ lái xe."},"tl":{"q":"Sa Louisiana, anong mas maikling kurso ang puwedeng kunin ng bagong driver na edad 18 pataas sa halip na ang 38-oras na kurso sa driver education?","o":["Isang 2-oras na online video","Isang 4-oras na klase sa defensive driving","Isang 6-oras na pre-licensing course at 8 oras ng aktuwal na pagmamaneho","Hindi na kailangan ng anumang kurso"],"h1":"Kailangan pa rin ng mga adult ng kaunting oras sa klase at kaunting oras sa pagmamaneho.","h2":"Sa Louisiana, puwedeng kumuha ang bagong driver na edad 18 pataas ng 6-oras na pre-licensing course at 8-oras na behind-the-wheel course sa halip na ang 38-oras na kurso.","p":"Tama. Puwedeng kumuha ang mga adult ng 6 na oras ng klase at 8 oras ng pagmamaneho."},"ar":{"q":"في Louisiana، ما الدورة الأقصر التي يمكن للسائق الجديد البالغ 18 سنة أو أكثر أن يأخذها بدل دورة تعليم القيادة التي مدتها 38 ساعة؟","o":["فيديو على الإنترنت مدته ساعتان (2)","درس قيادة دفاعية مدته 4 ساعات","دورة ما قبل الرخصة مدتها 6 ساعات، مع 8 ساعات قيادة فعلية","لا حاجة لأي دورة"],"h1":"البالغون ما زالوا يحتاجون بعض الوقت في الصف وبعض الوقت في القيادة.","h2":"في Louisiana يمكن للسائق الجديد البالغ 18 سنة أو أكثر أن يأخذ دورة ما قبل الرخصة مدتها 6 ساعات ودورة قيادة فعلية مدتها 8 ساعات، بدل دورة الـ 38 ساعة.","p":"صحيح. يمكن للبالغين أخذ 6 ساعات من الدروس مع 8 ساعات من القيادة."},"ref":{"doc":"LA","page":7}},{"id":"la-026","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, what can happen to the driving privilege of a 16-year-old who drops out of school before graduating?","o":["It can be taken away","Nothing happens","The teen must retake the vision test","The teen pays a small fee"],"h1":"The state links staying in school with keeping a license.","h2":"In Louisiana a driver age 15 to 17 who leaves school before graduating, or is often absent or late, can lose the driving privilege.","p":"Right. Dropping out can cost a teen the license."},"es":{"q":"En Luisiana, ¿qué le puede pasar al privilegio de manejar de un joven de 16 años que deja la escuela antes de graduarse?","o":["Se lo pueden quitar","No pasa nada","El joven debe repetir el examen de la vista","El joven paga una cuota pequeña"],"h1":"El estado relaciona seguir en la escuela con conservar la licencia.","h2":"En Luisiana un conductor de 15 a 17 años que deja la escuela antes de graduarse, o que falta o llega tarde con frecuencia, puede perder el privilegio de manejar.","p":"Correcto. Dejar la escuela le puede costar la licencia a un joven."},"zh":{"q":"在 Louisiana，16 岁的人如果没毕业就退学，他的驾驶权可能会怎样？","o":["可能被取消","什么都不会发生","必须重新做视力检查","交一小笔费用"],"h1":"州政府把继续上学和保留驾照联系在一起。","h2":"在 Louisiana，15 到 17 岁的司机如果没毕业就离开学校，或者经常缺课或迟到，可能会失去驾驶权。","p":"对。退学可能让青少年失去驾照。"},"vi":{"q":"Ở Louisiana, điều gì có thể xảy ra với quyền lái xe của một thiếu niên 16 tuổi bỏ học trước khi tốt nghiệp?","o":["Có thể bị tước","Không có gì xảy ra","Thiếu niên phải thi lại thị lực","Thiếu niên trả một khoản phí nhỏ"],"h1":"Tiểu bang gắn việc tiếp tục đi học với việc giữ bằng lái.","h2":"Ở Louisiana, người lái xe từ 15 đến 17 tuổi bỏ học trước khi tốt nghiệp, hoặc thường xuyên vắng mặt hay đi trễ, có thể mất quyền lái xe.","p":"Đúng. Bỏ học có thể làm thiếu niên mất bằng lái."},"tl":{"q":"Sa Louisiana, ano ang puwedeng mangyari sa pribilehiyong magmaneho ng isang 16 na taong gulang na huminto sa pag-aaral bago magtapos?","o":["Puwede itong bawiin","Walang mangyayari","Kailangang ulitin ng teen ang vision test","Magbabayad ang teen ng maliit na bayad"],"h1":"Iniuugnay ng estado ang pananatili sa paaralan sa pagpapanatili ng lisensya.","h2":"Sa Louisiana, ang driver na edad 15 hanggang 17 na umalis sa paaralan bago magtapos, o madalas lumiban o mahuli, ay puwedeng mawalan ng pribilehiyong magmaneho.","p":"Tama. Ang paghinto sa pag-aaral ay puwedeng magpawala ng lisensya ng teen."},"ar":{"q":"في Louisiana، ماذا يمكن أن يحدث لحق القيادة لشاب عمره 16 سنة يترك المدرسة قبل التخرج؟","o":["يمكن أن يُسحب منه","لا يحدث شيء","يجب أن يعيد اختبار النظر","يدفع رسومًا صغيرة"],"h1":"الولاية تربط البقاء في المدرسة بالاحتفاظ بالرخصة.","h2":"في Louisiana السائق الذي عمره من 15 إلى 17 سنة ويترك المدرسة قبل التخرج، أو يغيب أو يتأخر كثيرًا، يمكن أن يفقد حق القيادة.","p":"صحيح. ترك المدرسة قد يكلّف الشاب رخصته."},"ref":{"doc":"LA","page":12}},{"id":"la-027","scope":"LA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Louisiana, what is the penalty for a first offense of simple littering?","o":["A $25 fine","A $150 fine or 8 hours of community service","A $900 fine or 20 hours of community service","A written warning only"],"h1":"The second offense costs much more than the first.","h2":"In Louisiana a first offense of simple littering brings a $150 fine or 8 hours of community service.","p":"Right. A first offense is $150 or 8 hours of service."},"es":{"q":"En Luisiana, ¿cuál es la sanción por una primera infracción de tirar basura?","o":["Una multa de $25","Una multa de $150 u 8 horas de servicio comunitario","Una multa de $900 o 20 horas de servicio comunitario","Solo una advertencia por escrito"],"h1":"La segunda infracción cuesta mucho más que la primera.","h2":"En Luisiana una primera infracción de tirar basura trae una multa de $150 u 8 horas de servicio comunitario.","p":"Correcto. Una primera infracción es $150 u 8 horas de servicio."},"zh":{"q":"在 Louisiana，第一次乱扔垃圾（simple littering）会受到什么处罚？","o":["罚款 $25","罚款 $150 或 8 小时社区服务","罚款 $900 或 20 小时社区服务","只有书面警告"],"h1":"第二次违规的处罚比第一次重很多。","h2":"在 Louisiana，第一次乱扔垃圾会被罚款 $150 或做 8 小时社区服务。","p":"对。第一次是 $150 或 8 小时服务。"},"vi":{"q":"Ở Louisiana, hình phạt cho lần đầu xả rác thông thường (simple littering) là gì?","o":["Phạt $25","Phạt $150 hoặc 8 giờ lao động công ích","Phạt $900 hoặc 20 giờ lao động công ích","Chỉ cảnh cáo bằng văn bản"],"h1":"Lần vi phạm thứ hai bị phạt nặng hơn nhiều so với lần đầu.","h2":"Ở Louisiana, lần đầu xả rác thông thường bị phạt $150 hoặc 8 giờ lao động công ích.","p":"Đúng. Lần đầu là $150 hoặc 8 giờ lao động công ích."},"tl":{"q":"Sa Louisiana, ano ang parusa sa unang paglabag ng simpleng pagkakalat (simple littering)?","o":["Multang $25","Multang $150 o 8 oras ng community service","Multang $900 o 20 oras ng community service","Nakasulat na babala lang"],"h1":"Mas mahal nang malaki ang ikalawang paglabag kaysa sa una.","h2":"Sa Louisiana, ang unang paglabag ng simpleng pagkakalat ay may multang $150 o 8 oras ng community service.","p":"Tama. Ang unang paglabag ay $150 o 8 oras ng serbisyo."},"ar":{"q":"في Louisiana، ما عقوبة المخالفة الأولى لرمي النفايات البسيط (simple littering)؟","o":["غرامة $25","غرامة $150 أو 8 ساعات من خدمة المجتمع","غرامة $900 أو 20 ساعة من خدمة المجتمع","إنذار مكتوب فقط"],"h1":"المخالفة الثانية تكلّف أكثر بكثير من الأولى.","h2":"في Louisiana عقوبة المخالفة الأولى لرمي النفايات البسيط هي غرامة $150 أو 8 ساعات من خدمة المجتمع.","p":"صحيح. المخالفة الأولى $150 أو 8 ساعات من الخدمة."},"ref":{"doc":"LA","page":14}},{"id":"la-028","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, what is the minimum vision standard on the eye screening?","o":["20/20","20/40","20/70","20/100"],"h1":"You do not need perfect vision, but you need fairly good vision.","h2":"In Louisiana, the eye screening checks that your vision meets the minimum standard of 20/40.","p":"Right. The minimum is 20/40."},"es":{"q":"En Luisiana, ¿cuál es la visión mínima que se exige en el examen de la vista?","o":["20/20","20/40","20/70","20/100"],"h1":"No necesita una visión perfecta, pero sí bastante buena.","h2":"En Luisiana, el examen de la vista comprueba que su visión cumpla el mínimo de 20/40.","p":"Correcto. El mínimo es 20/40."},"zh":{"q":"在 Louisiana，视力检查的最低标准是多少？","o":["20/20","20/40","20/70","20/100"],"h1":"你不需要完美的视力，但视力要相当好。","h2":"在 Louisiana，视力检查要求你的视力达到最低标准 20/40。","p":"对。最低标准是 20/40。"},"vi":{"q":"Ở Louisiana, tiêu chuẩn thị lực tối thiểu trong bài kiểm tra mắt là bao nhiêu?","o":["20/20","20/40","20/70","20/100"],"h1":"Bạn không cần thị lực hoàn hảo, nhưng cần thị lực khá tốt.","h2":"Ở Louisiana, bài kiểm tra mắt xem thị lực của bạn có đạt tiêu chuẩn tối thiểu là 20/40 hay không.","p":"Đúng. Mức tối thiểu là 20/40."},"tl":{"q":"Sa Louisiana, ano ang pinakamababang pamantayan ng paningin sa pagsusuri ng mata?","o":["20/20","20/40","20/70","20/100"],"h1":"Hindi mo kailangan ng perpektong paningin, pero kailangan mo ng medyo malinaw na paningin.","h2":"Sa Louisiana, sinusuri ng eye screening kung umaabot ang paningin mo sa pinakamababang pamantayan na 20/40.","p":"Tama. Ang pinakamababa ay 20/40."},"ar":{"q":"في Louisiana، ما الحد الأدنى المطلوب للنظر في فحص العين؟","o":["20/20","20/40","20/70","20/100"],"h1":"لا تحتاج إلى نظر كامل، لكنك تحتاج إلى نظر جيد إلى حد ما.","h2":"في Louisiana يتأكد فحص العين من أن نظرك يبلغ الحد الأدنى المطلوب وهو 20/40.","p":"صحيح. الحد الأدنى هو 20/40."},"ref":{"doc":"LA","page":8}},{"id":"la-029","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, how long is a driver's license good for before it expires?","o":["Two years","Four years","Six years","Ten years"],"h1":"It lasts more than four years.","h2":"In Louisiana, a driver's license expires six years from your nearest birthday, and you may renew it up to 180 days early.","p":"Right. A license lasts six years."},"es":{"q":"En Luisiana, ¿por cuánto tiempo es válida una licencia de conducir antes de vencer?","o":["Dos años","Cuatro años","Seis años","Diez años"],"h1":"Dura más de cuatro años.","h2":"En Luisiana, la licencia de conducir vence seis años después de su cumpleaños más cercano, y puede renovarla hasta 180 días antes.","p":"Correcto. La licencia dura seis años."},"zh":{"q":"在 Louisiana，驾照有效期多久才会过期？","o":["两年","四年","六年","十年"],"h1":"它的有效期超过四年。","h2":"在 Louisiana，驾照从你最近的生日起六年后过期，你最早可以提前 180 天续期。","p":"对。驾照有效期是六年。"},"vi":{"q":"Ở Louisiana, bằng lái xe có giá trị bao lâu trước khi hết hạn?","o":["Hai năm","Bốn năm","Sáu năm","Mười năm"],"h1":"Nó có giá trị lâu hơn bốn năm.","h2":"Ở Louisiana, bằng lái xe hết hạn sau sáu năm tính từ ngày sinh nhật gần nhất của bạn, và bạn có thể gia hạn sớm tới 180 ngày.","p":"Đúng. Bằng lái có giá trị sáu năm."},"tl":{"q":"Sa Louisiana, gaano katagal may bisa ang driver's license bago ito mag-expire?","o":["Dalawang taon","Apat na taon","Anim na taon","Sampung taon"],"h1":"Mas matagal ito kaysa apat na taon.","h2":"Sa Louisiana, nag-e-expire ang driver's license anim na taon mula sa pinakamalapit mong kaarawan, at puwede mo itong i-renew hanggang 180 araw nang mas maaga.","p":"Tama. Anim na taon ang bisa ng lisensya."},"ar":{"q":"في Louisiana، كم مدة صلاحية رخصة القيادة قبل أن تنتهي؟","o":["سنتان","أربع سنوات","ست سنوات","عشر سنوات"],"h1":"مدتها أطول من أربع سنوات.","h2":"في Louisiana تنتهي رخصة القيادة بعد ست سنوات من أقرب يوم ميلاد لك، ويمكنك تجديدها قبل موعدها بما يصل إلى 180 يومًا.","p":"صحيح. الرخصة صالحة لمدة ست سنوات."},"ref":{"doc":"LA","page":10}},{"id":"la-030","scope":"LA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Louisiana, how close to a railroad crossing may you park?","o":["No closer than 50 feet","No closer than 15 feet","No closer than 25 feet","No closer than 100 feet"],"h1":"It is farther than the distance for a fire hydrant.","h2":"In Louisiana, you may not park within 50 feet of a railroad crossing.","p":"Right. Stay at least 50 feet away from the tracks."},"es":{"q":"En Luisiana, ¿qué tan cerca de un cruce de ferrocarril puede estacionarse?","o":["No a menos de 50 pies","No a menos de 15 pies","No a menos de 25 pies","No a menos de 100 pies"],"h1":"Es más lejos que la distancia para un hidrante.","h2":"En Luisiana, no puede estacionarse a menos de 50 pies de un cruce de ferrocarril.","p":"Correcto. Quédese al menos a 50 pies de las vías."},"zh":{"q":"在 Louisiana，你可以在离铁路道口多近的地方停车？","o":["不少于 50 英尺","不少于 15 英尺","不少于 25 英尺","不少于 100 英尺"],"h1":"这个距离比消防栓的距离更远。","h2":"在 Louisiana，你不可以在铁路道口 50 英尺以内停车。","p":"对。离铁轨至少要 50 英尺。"},"vi":{"q":"Ở Louisiana, bạn được đậu xe gần đường ray xe lửa tới mức nào?","o":["Không gần hơn 50 feet","Không gần hơn 15 feet","Không gần hơn 25 feet","Không gần hơn 100 feet"],"h1":"Khoảng cách này xa hơn khoảng cách với vòi nước chữa cháy.","h2":"Ở Louisiana, bạn không được đậu xe trong vòng 50 feet tính từ chỗ băng qua đường ray xe lửa.","p":"Đúng. Hãy cách đường ray ít nhất 50 feet."},"tl":{"q":"Sa Louisiana, gaano kalapit sa tawiran ng riles ng tren ka puwedeng pumarada?","o":["Hindi lalapit sa 50 talampakan","Hindi lalapit sa 15 talampakan","Hindi lalapit sa 25 talampakan","Hindi lalapit sa 100 talampakan"],"h1":"Mas malayo ito kaysa sa layo para sa fire hydrant.","h2":"Sa Louisiana, bawal pumarada sa loob ng 50 talampakan mula sa tawiran ng riles ng tren.","p":"Tama. Lumayo nang hindi bababa sa 50 talampakan mula sa riles."},"ar":{"q":"في Louisiana، ما أقرب مسافة يُسمح لك فيها بالوقوف من معبر سكة الحديد؟","o":["ليس أقرب من 50 قدمًا","ليس أقرب من 15 قدمًا","ليس أقرب من 25 قدمًا","ليس أقرب من 100 قدم"],"h1":"هذه المسافة أبعد من المسافة المطلوبة عن صنبور الإطفاء.","h2":"في Louisiana لا يجوز لك الوقوف على بعد أقل من 50 قدمًا من معبر سكة الحديد.","p":"صحيح. ابقَ على بعد 50 قدمًا على الأقل من السكة."},"ref":{"doc":"LA","page":70}},{"id":"la-031","scope":"LA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Louisiana, a car is coming toward you at night. Within what distance must you switch to low beams?","o":["100 feet","200 feet","300 feet","500 feet"],"h1":"It is a longer distance than the one for following a car.","h2":"In Louisiana, you must use low beams when an oncoming vehicle is within 500 feet, or when you follow a vehicle within 200 feet.","p":"Right. Dim your lights within 500 feet of an oncoming car."},"es":{"q":"En Luisiana, de noche viene un carro de frente. ¿A qué distancia debe cambiar a luces bajas?","o":["100 pies","200 pies","300 pies","500 pies"],"h1":"Es una distancia mayor que la que se usa al seguir a otro carro.","h2":"En Luisiana, debe usar luces bajas cuando un vehículo que viene de frente está a menos de 500 pies, o cuando sigue a un vehículo a menos de 200 pies.","p":"Correcto. Baje las luces a 500 pies de un carro que viene de frente."},"zh":{"q":"在 Louisiana，晚上有车迎面开来。在多远距离内你必须换成近光灯？","o":["100 英尺","200 英尺","300 英尺","500 英尺"],"h1":"这个距离比跟车时的距离更长。","h2":"在 Louisiana，迎面来车在 500 英尺以内时，或者你在前车后面 200 英尺以内跟车时，你必须使用近光灯。","p":"对。迎面来车在 500 英尺以内时要调暗车灯。"},"vi":{"q":"Ở Louisiana, ban đêm có xe chạy ngược chiều về phía bạn. Trong khoảng cách nào bạn phải chuyển sang đèn cốt (đèn chiếu gần)?","o":["100 feet","200 feet","300 feet","500 feet"],"h1":"Khoảng cách này dài hơn khoảng cách khi chạy theo sau một xe.","h2":"Ở Louisiana, bạn phải dùng đèn cốt khi xe ngược chiều ở trong vòng 500 feet, hoặc khi bạn chạy theo sau một xe trong vòng 200 feet.","p":"Đúng. Hạ đèn khi xe ngược chiều ở trong vòng 500 feet."},"tl":{"q":"Sa Louisiana, may sasakyang paparating sa iyo sa gabi. Sa loob ng anong layo ka dapat lumipat sa low beams?","o":["100 talampakan","200 talampakan","300 talampakan","500 talampakan"],"h1":"Mas mahaba ang layong ito kaysa sa layo kapag sumusunod sa isang sasakyan.","h2":"Sa Louisiana, dapat kang gumamit ng low beams kapag ang paparating na sasakyan ay nasa loob ng 500 talampakan, o kapag sumusunod ka sa isang sasakyan sa loob ng 200 talampakan.","p":"Tama. Hinaan ang ilaw kapag ang paparating na sasakyan ay nasa loob ng 500 talampakan."},"ar":{"q":"في Louisiana، تقترب منك سيارة من الاتجاه المقابل في الليل. ضمن أي مسافة يجب أن تنتقل إلى الأضواء المنخفضة؟","o":["100 قدم","200 قدم","300 قدم","500 قدم"],"h1":"هذه المسافة أطول من المسافة عند السير خلف سيارة.","h2":"في Louisiana يجب أن تستخدم الأضواء المنخفضة عندما تكون السيارة المقابلة على بعد 500 قدم أو أقل، أو عندما تسير خلف سيارة على بعد 200 قدم أو أقل.","p":"صحيح. خفّض الأضواء عندما تكون السيارة المقابلة على بعد 500 قدم."},"ref":{"doc":"LA","page":75}},{"id":"la-032","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, you just moved here from another state. How long do you have to get a Louisiana driver's license?","o":["10 days","30 days","60 days","90 days"],"h1":"It is about one month.","h2":"In Louisiana, new residents have 30 days after moving in to get a Louisiana driver's license.","p":"Right. New residents have 30 days."},"es":{"q":"En Luisiana, usted acaba de mudarse desde otro estado. ¿Cuánto tiempo tiene para obtener una licencia de conducir de Luisiana?","o":["10 días","30 días","60 días","90 días"],"h1":"Es más o menos un mes.","h2":"En Luisiana, los nuevos residentes tienen 30 días después de mudarse para obtener una licencia de conducir de Luisiana.","p":"Correcto. Los nuevos residentes tienen 30 días."},"ref":{"doc":"LA","page":1}},{"id":"la-033","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, you move to a new home. How soon must you change the address on your license?","o":["Within 10 days","Within 30 days","Within 60 days","At your next renewal"],"h1":"It is less than two weeks.","h2":"In Louisiana, you must change the address on your license within 10 days after you move.","p":"Right. Update your address within 10 days."},"es":{"q":"En Luisiana, usted se muda a una casa nueva. ¿En cuánto tiempo debe cambiar la dirección en su licencia?","o":["En 10 días","En 30 días","En 60 días","En su próxima renovación"],"h1":"Es menos de dos semanas.","h2":"En Luisiana, debe cambiar la dirección en su licencia dentro de los 10 días después de mudarse.","p":"Correcto. Actualice su dirección en 10 días."},"ref":{"doc":"LA","page":10}},{"id":"la-034","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, how long does a DWI conviction stay on your public driving record?","o":["2 years","5 years","10 years","For life"],"h1":"It stays twice as long as other traffic convictions.","h2":"In Louisiana, a DWI conviction stays on your driving record for 10 years; most other convictions stay for 5 years.","p":"Right. A DWI stays on your record for 10 years."},"es":{"q":"En Luisiana, ¿cuánto tiempo queda una condena por DWI (manejar en estado de ebriedad) en su historial de manejo público?","o":["2 años","5 años","10 años","Toda la vida"],"h1":"Queda el doble de tiempo que otras condenas de tránsito.","h2":"En Luisiana, una condena por DWI queda en su historial de manejo por 10 años; la mayoría de las otras condenas quedan por 5 años.","p":"Correcto. Un DWI queda en su historial por 10 años."},"ref":{"doc":"LA","page":11}},{"id":"la-035","scope":"LA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Louisiana, how many reckless driving convictions within 12 months can make you lose your license?","o":["One","Five","Four","Three"],"h1":"It is fewer than four.","h2":"In Louisiana, three reckless driving convictions within 12 months can cost you your driver's license.","p":"Right. Three reckless driving convictions in 12 months can cost you your license."},"es":{"q":"En Luisiana, ¿cuántas condenas por manejo imprudente en 12 meses pueden hacerle perder su licencia?","o":["Una","Cinco","Cuatro","Tres"],"h1":"Son menos de cuatro.","h2":"En Luisiana, tres condenas por manejo imprudente en 12 meses pueden hacerle perder su licencia de conducir.","p":"Correcto. Tres condenas por manejo imprudente en 12 meses pueden costarle la licencia."},"ref":{"doc":"LA","page":12}},{"id":"la-036","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, an officer arrests you for drunk driving and you refuse the alcohol test. This is your first refusal. How long is your license suspended?","o":["90 days","365 days","30 days","730 days"],"h1":"It is a full year.","h2":"In Louisiana, refusing the alcohol test the first time suspends your driving privileges for 365 days.","p":"Right. A first refusal means a 365-day suspension."},"es":{"q":"En Luisiana, un oficial lo arresta por manejar ebrio y usted se niega a la prueba de alcohol. Es la primera vez que se niega. ¿Por cuánto tiempo suspenden su licencia?","o":["90 días","365 días","30 días","730 días"],"h1":"Es un año completo.","h2":"En Luisiana, negarse a la prueba de alcohol por primera vez suspende su privilegio de manejar por 365 días.","p":"Correcto. La primera negativa significa una suspensión de 365 días."},"ref":{"doc":"LA","page":126}},{"id":"la-037","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, you are 21 or older and take the alcohol test. It shows 0.08 to 0.149 percent. How long is your license suspended?","o":["180 days","30 days","730 days","10 days"],"h1":"It is about six months.","h2":"In Louisiana, a driver 21 or older whose test shows 0.08 to 0.149 percent has driving privileges suspended for 180 days.","p":"Right. That result means a 180-day suspension."},"es":{"q":"En Luisiana, usted tiene 21 años o más y se hace la prueba de alcohol. El resultado es de 0.08 a 0.149 por ciento. ¿Por cuánto tiempo suspenden su licencia?","o":["180 días","30 días","730 días","10 días"],"h1":"Son unos seis meses.","h2":"En Luisiana, a un conductor de 21 años o más con un resultado de 0.08 a 0.149 por ciento le suspenden el privilegio de manejar por 180 días.","p":"Correcto. Ese resultado significa una suspensión de 180 días."},"ref":{"doc":"LA","page":126}},{"id":"la-038","scope":"LA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Louisiana, what does the law say about wearing headphones while you drive?","o":["They are allowed in both ears at low volume","They are banned only at night","You may not wear them in both ears","They are allowed if you are over 21"],"h1":"One ear is allowed.","h2":"In Louisiana, you may not wear headphones in both ears while driving, but one ear alone is allowed.","p":"Right. Never cover both ears while driving."},"es":{"q":"En Luisiana, ¿qué dice la ley sobre usar audífonos mientras maneja?","o":["Se permiten en los dos oídos con volumen bajo","Están prohibidos solo de noche","No puede usarlos en los dos oídos","Se permiten si tiene más de 21 años"],"h1":"Se permite en un oído.","h2":"En Luisiana, no puede usar audífonos en los dos oídos mientras maneja, pero sí se permite en un solo oído.","p":"Correcto. Nunca se cubra los dos oídos al manejar."},"ref":{"doc":"LA","page":97}},{"id":"la-039","scope":"LA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Louisiana, what happens each time you are convicted of driving while your license is suspended?","o":["You get a warning only","Your suspension ends sooner","You must retake the vision test","Your suspension is extended by one year"],"h1":"It makes the suspension longer.","h2":"In Louisiana, each conviction for driving under suspension adds one more year to your suspension.","p":"Right. Each conviction adds one year."},"es":{"q":"En Luisiana, ¿qué pasa cada vez que lo condenan por manejar con la licencia suspendida?","o":["Solo recibe una advertencia","Su suspensión termina antes","Debe repetir el examen de la vista","Su suspensión se alarga un año"],"h1":"Hace que la suspensión dure más.","h2":"En Luisiana, cada condena por manejar con la licencia suspendida le agrega un año más a su suspensión.","p":"Correcto. Cada condena agrega un año."},"ref":{"doc":"LA","page":127}},{"id":"la-040","scope":"LA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Louisiana, what happens to traffic fines in a construction zone?","o":["They are cut in half","They are doubled","They stay the same","They are tripled"],"h1":"Work zones carry a bigger penalty.","h2":"In Louisiana, traffic fines are doubled in construction zones.","p":"Right. Fines are doubled in work zones."},"es":{"q":"En Luisiana, ¿qué pasa con las multas de tránsito en una zona de construcción?","o":["Se reducen a la mitad","Se duplican","Siguen iguales","Se triplican"],"h1":"Las zonas de trabajo tienen una pena mayor.","h2":"En Luisiana, las multas de tránsito se duplican en las zonas de construcción.","p":"Correcto. Las multas se duplican en zonas de trabajo."},"ref":{"doc":"LA","page":31}},{"id":"la-041","scope":"LA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Louisiana, if no sign shows a different limit, what is the highest speed allowed on an interstate?","o":["55 mph","65 mph","70 mph","80 mph"],"h1":"It is between 65 and 75.","h2":"In Louisiana, the highest speed allowed on an interstate is 70 mph unless a sign shows a different limit.","p":"Right. The interstate limit is 70 mph unless posted otherwise."},"es":{"q":"En Luisiana, si ningún letrero indica otro límite, ¿cuál es la velocidad más alta permitida en una autopista interestatal?","o":["55 mph","65 mph","70 mph","80 mph"],"h1":"Está entre 65 y 75.","h2":"En Luisiana, la velocidad más alta permitida en una autopista interestatal es de 70 mph, a menos que un letrero indique otro límite.","p":"Correcto. El límite en la interestatal es de 70 mph, salvo que se indique otro."},"ref":{"doc":"LA","page":100}},{"id":"la-042","scope":"LA","cat":"signals","sign":null,"c":0,"en":{"q":"In Louisiana, how far before a turn must you start giving your turn signal?","o":["At least 100 feet","At least 25 feet","At least 50 feet","At least 300 feet"],"h1":"It is about the length of a few houses.","h2":"In Louisiana, you must signal for at least 100 feet before you turn.","p":"Right. Signal for at least 100 feet before a turn."},"es":{"q":"En Luisiana, ¿a qué distancia antes de dar vuelta debe empezar a usar la direccional?","o":["Por lo menos 100 pies","Por lo menos 25 pies","Por lo menos 50 pies","Por lo menos 300 pies"],"h1":"Es más o menos el largo de unas cuantas casas.","h2":"En Luisiana, debe usar la direccional por lo menos 100 pies antes de dar vuelta.","p":"Correcto. Use la direccional por lo menos 100 pies antes de dar vuelta."},"ref":{"doc":"LA","page":92}},{"id":"la-043","scope":"LA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Louisiana, how far may you drive in a shared center left-turn lane?","o":["Up to half a mile","Up to 1,000 feet","As far as you like","No more than 200 feet"],"h1":"It is a short distance, only enough to get ready to turn.","h2":"In Louisiana, you may not drive more than 200 feet in a shared center left-turn lane.","p":"Right. Use no more than 200 feet of the center turn lane."},"es":{"q":"En Luisiana, ¿qué distancia puede recorrer en un carril central compartido para dar vuelta a la izquierda?","o":["Hasta media milla","Hasta 1,000 pies","Toda la que quiera","No más de 200 pies"],"h1":"Es una distancia corta, solo para prepararse para la vuelta.","h2":"En Luisiana, no puede recorrer más de 200 pies en un carril central compartido para dar vuelta a la izquierda.","p":"Correcto. No use más de 200 pies del carril central."},"ref":{"doc":"LA","page":91}},{"id":"la-044","scope":"LA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Louisiana, a school bus is stopped to load or unload children. How far from the bus must you stop?","o":["At least 5 feet","At least 10 feet","At least 30 feet","At least 100 feet"],"h1":"It is more than 20 feet.","h2":"In Louisiana, you must stop at least 30 feet from a school bus that is stopped to load or unload children.","p":"Right. Stop at least 30 feet from the bus."},"es":{"q":"En Luisiana, un autobús escolar está detenido para subir o bajar niños. ¿A qué distancia del autobús debe detenerse?","o":["Por lo menos a 5 pies","Por lo menos a 10 pies","Por lo menos a 30 pies","Por lo menos a 100 pies"],"h1":"Es más de 20 pies.","h2":"En Luisiana, debe detenerse por lo menos a 30 pies de un autobús escolar detenido para subir o bajar niños.","p":"Correcto. Deténgase por lo menos a 30 pies del autobús."},"ref":{"doc":"LA","page":88}},{"id":"la-045","scope":"LA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Louisiana, the lights are flashing at a railroad crossing and a train is coming. Where must you stop?","o":["Right at the first rail","Between 15 and 50 feet from the nearest rail","Between 50 and 100 feet from the nearest rail","Anywhere you can see the train"],"h1":"Not too close and not too far.","h2":"In Louisiana, you must stop no closer than 15 feet and no farther than 50 feet from the nearest rail.","p":"Right. Stop between 15 and 50 feet from the nearest rail."},"es":{"q":"En Luisiana, las luces de un cruce de ferrocarril están destellando y viene un tren. ¿Dónde debe detenerse?","o":["Justo en el primer riel","Entre 15 y 50 pies del riel más cercano","Entre 50 y 100 pies del riel más cercano","En cualquier lugar donde vea el tren"],"h1":"Ni muy cerca ni muy lejos.","h2":"En Luisiana, debe detenerse a no menos de 15 pies y a no más de 50 pies del riel más cercano.","p":"Correcto. Deténgase entre 15 y 50 pies del riel más cercano."},"ref":{"doc":"LA","page":94}},{"id":"la-046","scope":"LA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Louisiana, how close to an intersection, railroad crossing, bridge or tunnel may you pass another vehicle?","o":["No closer than 100 feet","No closer than 25 feet","No closer than 50 feet","Any distance, if the road is clear"],"h1":"It is more than 50 feet.","h2":"In Louisiana, you may not pass another vehicle within 100 feet of an intersection, railroad crossing, bridge or tunnel.","p":"Right. Do not pass within 100 feet of those places."},"es":{"q":"En Luisiana, ¿qué tan cerca de una intersección, un cruce de ferrocarril, un puente o un túnel puede rebasar a otro vehículo?","o":["No a menos de 100 pies","No a menos de 25 pies","No a menos de 50 pies","A cualquier distancia, si el camino está libre"],"h1":"Es más de 50 pies.","h2":"En Luisiana, no puede rebasar a otro vehículo a menos de 100 pies de una intersección, un cruce de ferrocarril, un puente o un túnel.","p":"Correcto. No rebase a menos de 100 pies de esos lugares."},"ref":{"doc":"LA","page":71}},{"id":"la-047","scope":"LA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Louisiana, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 30 feet","No closer than 15 feet"],"h1":"It is less than the distance for a railroad crossing.","h2":"In Louisiana, you may not park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a hydrant."},"es":{"q":"En Luisiana, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No a menos de 5 pies","No a menos de 10 pies","No a menos de 30 pies","No a menos de 15 pies"],"h1":"Es menos que la distancia para un cruce de ferrocarril.","h2":"En Luisiana, no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese al menos a 15 pies de un hidrante."},"ref":{"doc":"LA","page":70}},{"id":"la-048","scope":"LA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Louisiana, how much space must you leave when you pass a bicycle?","o":["At least 1 foot","At least 2 feet","At least 3 feet","At least 10 feet"],"h1":"It is about the length of a yardstick.","h2":"In Louisiana, you must leave at least 3 feet between your car and a bicycle you are passing.","p":"Right. Give a bicycle at least 3 feet."},"es":{"q":"En Luisiana, ¿cuánto espacio debe dejar cuando rebasa a una bicicleta?","o":["Por lo menos 1 pie","Por lo menos 2 pies","Por lo menos 3 pies","Por lo menos 10 pies"],"h1":"Es más o menos el largo de una regla de una yarda.","h2":"En Luisiana, debe dejar por lo menos 3 pies entre su carro y la bicicleta que está rebasando.","p":"Correcto. Deje a la bicicleta por lo menos 3 pies."},"ref":{"doc":"LA","page":80}},{"id":"la-049","scope":"LA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Louisiana, children under what age must wear an approved helmet when they ride a bicycle?","o":["12","8","16","18"],"h1":"It is the age just before becoming a teenager.","h2":"In Louisiana, children under age 12 must wear an approved helmet when riding a bicycle or riding on one as a passenger.","p":"Right. Children under 12 must wear a bicycle helmet."},"es":{"q":"En Luisiana, ¿los niños menores de qué edad deben usar un casco aprobado cuando andan en bicicleta?","o":["12","8","16","18"],"h1":"Es la edad justo antes de ser adolescente.","h2":"En Luisiana, los niños menores de 12 años deben usar un casco aprobado cuando manejan una bicicleta o van en ella como pasajeros.","p":"Correcto. Los niños menores de 12 años deben usar casco de bicicleta."},"ref":{"doc":"LA","page":81}},{"id":"la-050","scope":"LA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Louisiana, who may ride in the open bed of a pickup truck on an interstate highway?","o":["Anyone 12 or older","Anyone 18 or older","Adults wearing a seat belt","No one, of any age"],"h1":"The interstate rule has no age exception.","h2":"In Louisiana, no one of any age may ride in the open bed of a truck on an interstate highway.","p":"Right. No one may ride in an open truck bed on the interstate."},"es":{"q":"En Luisiana, ¿quién puede ir en la caja abierta de una camioneta pickup en una autopista interestatal?","o":["Cualquier persona de 12 años o más","Cualquier persona de 18 años o más","Los adultos con cinturón de seguridad","Nadie, de ninguna edad"],"h1":"La regla de la interestatal no tiene excepción de edad.","h2":"En Luisiana, nadie, de ninguna edad, puede ir en la caja abierta de un camión en una autopista interestatal.","p":"Correcto. Nadie puede ir en la caja abierta en la interestatal."},"ref":{"doc":"LA","page":96}},{"id":"la-051","scope":"LA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Louisiana, how close may you follow a fire truck or other emergency vehicle that is answering a call?","o":["No closer than 100 feet","No closer than 500 feet","No closer than 50 feet","Any distance, if you keep up"],"h1":"It is much farther than a few car lengths.","h2":"In Louisiana, it is against the law to follow an emergency vehicle answering a call closer than 500 feet.","p":"Right. Stay at least 500 feet behind."},"es":{"q":"En Luisiana, ¿qué tan cerca puede seguir a un camión de bomberos u otro vehículo de emergencia que atiende una llamada?","o":["No a menos de 100 pies","No a menos de 500 pies","No a menos de 50 pies","A cualquier distancia, si mantiene la velocidad"],"h1":"Es mucho más que unos cuantos largos de carro.","h2":"En Luisiana, es ilegal seguir a menos de 500 pies a un vehículo de emergencia que atiende una llamada.","p":"Correcto. Quédese al menos a 500 pies detrás."},"ref":{"doc":"LA","page":97}},{"id":"ma-001","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, what is the youngest age to apply for a learner's permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is later than in many other states.","h2":"In Massachusetts you can apply for a learner's permit at age 16, which is later than in many other states.","p":"Right. The Massachusetts learner's permit starts at age 16."},"es":{"q":"En Massachusetts, ¿cuál es la edad mínima para solicitar el permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es más tarde que en muchos otros estados.","h2":"En Massachusetts usted puede solicitar el permiso de aprendiz a los 16 años, más tarde que en muchos otros estados.","p":"Correcto. El permiso de aprendiz en Massachusetts empieza a los 16 años."},"zh":{"q":"在 Massachusetts，最小几岁可以申请学习驾照（learner's permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"比很多其他州晚。","h2":"在 Massachusetts，你 16 岁才可以申请学习驾照，比很多其他州晚。","p":"对。Massachusetts 的学习驾照从 16 岁开始。"},"vi":{"q":"Ở Massachusetts, tuổi nhỏ nhất để nộp đơn xin giấy phép tập lái (learner's permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Tuổi này muộn hơn so với nhiều tiểu bang khác.","h2":"Ở Massachusetts, bạn có thể nộp đơn xin giấy phép tập lái khi 16 tuổi, muộn hơn so với nhiều tiểu bang khác.","p":"Đúng. Giấy phép tập lái ở Massachusetts bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Massachusetts, ano ang pinakabatang edad para mag-apply ng learner's permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Mas huli ito kaysa sa maraming ibang estado.","h2":"Sa Massachusetts, puwede kang mag-apply ng learner's permit sa edad na 16, na mas huli kaysa sa maraming ibang estado.","p":"Tama. Nagsisimula ang learner's permit sa Massachusetts sa edad na 16."},"ar":{"q":"في Massachusetts، ما أصغر عمر للتقدّم بطلب تصريح تعلّم القيادة (learner's permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هذا العمر متأخر مقارنة بولايات كثيرة أخرى.","h2":"في Massachusetts يمكنك التقدّم بطلب تصريح تعلّم القيادة في عمر 16 سنة، وهذا متأخر مقارنة بولايات كثيرة أخرى.","p":"صحيح. يبدأ تصريح تعلّم القيادة في Massachusetts في عمر 16 سنة."},"ref":{"doc":"MA","page":15}},{"id":"ma-002","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, who must sit beside a learner's permit holder while driving?","o":["A licensed driver 21+ with 1 year of experience","Any licensed driver age 18 or older","Any adult, licensed or not","A licensed driver 25+ with 5 years of experience"],"h1":"The helper must be over 21 and must have driven for some time.","h2":"A Massachusetts permit holder must drive with a licensed driver who is at least 21 and has at least one year of driving experience in the seat beside them, so an experienced adult can help.","p":"Right. The helper is 21 or older with a year of experience."},"es":{"q":"En Massachusetts, ¿quién debe ir sentado al lado de quien tiene permiso de aprendiz?","o":["Un conductor con licencia de 21+ y 1 año de experiencia","Cualquier conductor con licencia de 18 años o más","Cualquier adulto, con o sin licencia","Un conductor con licencia de 25+ y 5 años de experiencia"],"h1":"El acompañante debe tener más de 21 años y haber manejado un tiempo.","h2":"En Massachusetts quien tiene permiso de aprendiz debe manejar con un conductor con licencia de por lo menos 21 años y un año de experiencia en el asiento de al lado, para que un adulto con experiencia lo ayude.","p":"Correcto. El acompañante tiene 21 años o más y un año de experiencia."},"zh":{"q":"在 Massachusetts，持学习驾照的人开车时，谁必须坐在旁边？","o":["21 岁以上、有 1 年驾驶经验的有驾照司机","任何 18 岁或以上、有驾照的司机","任何成年人，有没有驾照都可以","25 岁以上、有 5 年驾驶经验的有驾照司机"],"h1":"陪同的人必须超过 21 岁，而且必须开车开了一段时间。","h2":"在 Massachusetts，持学习驾照的人必须和一位至少 21 岁、至少有一年驾驶经验、有驾照的司机一起开车，这个人坐在旁边的座位上，这样有经验的成年人可以帮忙。","p":"对。陪同的人 21 岁或以上，有一年驾驶经验。"},"vi":{"q":"Ở Massachusetts, ai phải ngồi bên cạnh người có giấy phép tập lái khi lái xe?","o":["Người có bằng lái, từ 21 tuổi trở lên, có 1 năm kinh nghiệm","Bất kỳ người có bằng lái nào từ 18 tuổi trở lên","Bất kỳ người lớn nào, có bằng lái hay không","Người có bằng lái, từ 25 tuổi trở lên, có 5 năm kinh nghiệm"],"h1":"Người hướng dẫn phải trên 21 tuổi và đã lái xe được một thời gian.","h2":"Người có giấy phép tập lái ở Massachusetts phải lái xe với một người có bằng lái, ít nhất 21 tuổi và có ít nhất một năm kinh nghiệm lái xe, ngồi ở ghế bên cạnh, để một người lớn có kinh nghiệm có thể giúp đỡ.","p":"Đúng. Người hướng dẫn từ 21 tuổi trở lên và có một năm kinh nghiệm."},"tl":{"q":"Sa Massachusetts, sino ang dapat umupo sa tabi ng may hawak ng learner's permit habang nagmamaneho?","o":["Isang may lisensyang driver na 21 pataas na may 1 taong karanasan","Kahit sinong may lisensyang driver na 18 pataas","Kahit sinong adult, may lisensya man o wala","Isang may lisensyang driver na 25 pataas na may 5 taong karanasan"],"h1":"Ang kasama ay dapat lampas 21 at matagal-tagal nang nagmamaneho.","h2":"Ang may hawak ng permit sa Massachusetts ay dapat magmaneho kasama ang isang may lisensyang driver na hindi bababa sa 21 taong gulang at may hindi bababa sa isang taong karanasan sa pagmamaneho, na nakaupo sa tabi niya, para may makatulong na adult na may karanasan.","p":"Tama. Ang kasama ay 21 pataas at may isang taong karanasan."},"ar":{"q":"في Massachusetts، من يجب أن يجلس بجانب حامل تصريح تعلّم القيادة أثناء القيادة؟","o":["سائق مرخّص عمره 21 سنة أو أكثر ولديه خبرة سنة واحدة","أي سائق مرخّص عمره 18 سنة أو أكثر","أي شخص بالغ، مرخّص أو غير مرخّص","سائق مرخّص عمره 25 سنة أو أكثر ولديه خبرة 5 سنوات"],"h1":"يجب أن يكون المرافق فوق 21 سنة وأن يكون قد قاد السيارة لبعض الوقت.","h2":"يجب على حامل التصريح في Massachusetts أن يقود مع سائق مرخّص عمره 21 سنة على الأقل ولديه خبرة قيادة سنة واحدة على الأقل، يجلس في المقعد المجاور، حتى يساعده شخص بالغ ذو خبرة.","p":"صحيح. المرافق عمره 21 سنة أو أكثر ولديه خبرة سنة."},"ref":{"doc":"MA","page":18}},{"id":"ma-003","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, a permit holder under 18 may not drive during which hours unless a parent or guardian is in the car?","o":["From 9 p.m. to 5 a.m.","From 10 p.m. to 6 a.m.","From 11 p.m. to 6 a.m.","From midnight to 5 a.m."],"h1":"It starts when the date changes.","h2":"A Massachusetts permit holder under 18 may not drive between midnight and 5 a.m. unless a parent or guardian is with them, because late-night driving is the riskiest for new drivers.","p":"Right. No driving from midnight to 5 a.m. without a parent or guardian."},"es":{"q":"En Massachusetts, ¿en qué horario no puede manejar un aprendiz menor de 18 años si no va con él un padre o tutor?","o":["De 9 p.m. a 5 a.m.","De 10 p.m. a 6 a.m.","De 11 p.m. a 6 a.m.","De medianoche a 5 a.m."],"h1":"Empieza cuando cambia la fecha.","h2":"En Massachusetts un aprendiz menor de 18 años no puede manejar entre la medianoche y las 5 a.m. si no va con él un padre o tutor, porque manejar de madrugada es lo más riesgoso para un conductor nuevo.","p":"Correcto. No se maneja de medianoche a 5 a.m. sin un padre o tutor."},"zh":{"q":"在 Massachusetts，18 岁以下持学习驾照的人，除非父母或监护人在车上，哪些时间不能开车？","o":["晚上 9 点到早上 5 点","晚上 10 点到早上 6 点","晚上 11 点到早上 6 点","午夜到早上 5 点"],"h1":"它从日期改变的时候开始。","h2":"在 Massachusetts，18 岁以下持学习驾照的人，在午夜到早上 5 点之间不能开车，除非父母或监护人一起，因为深夜开车对新司机最危险。","p":"对。没有父母或监护人，午夜到早上 5 点不能开车。"},"vi":{"q":"Ở Massachusetts, người có giấy phép tập lái dưới 18 tuổi không được lái xe trong những giờ nào, trừ khi có cha mẹ hoặc người giám hộ trong xe?","o":["Từ 9 giờ tối đến 5 giờ sáng","Từ 10 giờ tối đến 6 giờ sáng","Từ 11 giờ tối đến 6 giờ sáng","Từ nửa đêm đến 5 giờ sáng"],"h1":"Thời gian này bắt đầu khi sang ngày mới.","h2":"Người có giấy phép tập lái ở Massachusetts dưới 18 tuổi không được lái xe từ nửa đêm đến 5 giờ sáng, trừ khi có cha mẹ hoặc người giám hộ đi cùng, vì lái xe khuya là nguy hiểm nhất đối với người mới lái.","p":"Đúng. Không lái xe từ nửa đêm đến 5 giờ sáng nếu không có cha mẹ hoặc người giám hộ."},"tl":{"q":"Sa Massachusetts, sa anong oras hindi puwedeng magmaneho ang may hawak ng permit na wala pang 18, maliban kung may magulang o guardian sa sasakyan?","o":["Mula 9 p.m. hanggang 5 a.m.","Mula 10 p.m. hanggang 6 a.m.","Mula 11 p.m. hanggang 6 a.m.","Mula hatinggabi hanggang 5 a.m."],"h1":"Nagsisimula ito kapag nagpalit ang petsa.","h2":"Ang may hawak ng permit sa Massachusetts na wala pang 18 ay hindi puwedeng magmaneho mula hatinggabi hanggang 5 a.m. maliban kung kasama ang magulang o guardian, dahil pinakadelikado ang pagmamaneho sa hatinggabi para sa mga bagong driver.","p":"Tama. Bawal magmaneho mula hatinggabi hanggang 5 a.m. kung walang magulang o guardian."},"ar":{"q":"في Massachusetts، في أي ساعات لا يجوز لحامل التصريح الذي عمره أقل من 18 سنة أن يقود، إلا إذا كان أحد الوالدين أو الوصي في السيارة؟","o":["من 9 مساءً إلى 5 صباحًا","من 10 مساءً إلى 6 صباحًا","من 11 مساءً إلى 6 صباحًا","من منتصف الليل إلى 5 صباحًا"],"h1":"تبدأ عندما يتغيّر التاريخ.","h2":"لا يجوز لحامل التصريح في Massachusetts الذي عمره أقل من 18 سنة أن يقود بين منتصف الليل و5 صباحًا إلا إذا كان معه أحد الوالدين أو الوصي، لأن القيادة في آخر الليل هي الأخطر على السائقين الجدد.","p":"صحيح. ممنوع القيادة من منتصف الليل إلى 5 صباحًا بدون أحد الوالدين أو الوصي."},"ref":{"doc":"MA","page":18}},{"id":"ma-004","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, how long is a learner's permit valid?","o":["Up to one year","Up to two years","Up to four years","Up to five years"],"h1":"It lasts longer than one year.","h2":"A Massachusetts learner's permit is valid for up to two years, which gives enough time to finish driver education and practice.","p":"Right. The permit is valid for up to two years."},"es":{"q":"En Massachusetts, ¿por cuánto tiempo es válido el permiso de aprendiz?","o":["Hasta un año","Hasta dos años","Hasta cuatro años","Hasta cinco años"],"h1":"Dura más de un año.","h2":"En Massachusetts el permiso de aprendiz es válido hasta por dos años, lo que da tiempo suficiente para terminar la educación vial y practicar.","p":"Correcto. El permiso es válido hasta por dos años."},"zh":{"q":"在 Massachusetts，学习驾照有效期是多久？","o":["最多一年","最多两年","最多四年","最多五年"],"h1":"它比一年长。","h2":"Massachusetts 的学习驾照有效期最多两年，这样有足够的时间完成驾驶课和练习。","p":"对。学习驾照有效期最多两年。"},"vi":{"q":"Ở Massachusetts, giấy phép tập lái có hiệu lực trong bao lâu?","o":["Tối đa một năm","Tối đa hai năm","Tối đa bốn năm","Tối đa năm năm"],"h1":"Thời hạn dài hơn một năm.","h2":"Giấy phép tập lái ở Massachusetts có hiệu lực tối đa hai năm, đủ thời gian để học xong khóa giáo dục lái xe và tập lái.","p":"Đúng. Giấy phép có hiệu lực tối đa hai năm."},"tl":{"q":"Sa Massachusetts, gaano katagal valid ang learner's permit?","o":["Hanggang isang taon","Hanggang dalawang taon","Hanggang apat na taon","Hanggang limang taon"],"h1":"Mas matagal ito sa isang taon.","h2":"Ang learner's permit sa Massachusetts ay valid nang hanggang dalawang taon, kaya may sapat na oras para tapusin ang driver education at mag-practice.","p":"Tama. Valid ang permit nang hanggang dalawang taon."},"ar":{"q":"في Massachusetts، ما مدة صلاحية تصريح تعلّم القيادة؟","o":["حتى سنة واحدة","حتى سنتين","حتى أربع سنوات","حتى خمس سنوات"],"h1":"المدة أطول من سنة واحدة.","h2":"تصريح تعلّم القيادة في Massachusetts صالح حتى سنتين، وهذا وقت كافٍ لإنهاء دروس تعليم القيادة والتدرّب.","p":"صحيح. التصريح صالح حتى سنتين."},"ref":{"doc":"MA","page":15}},{"id":"ma-005","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, how many questions must you answer correctly to pass the 25-question learner's permit exam?","o":["15 questions","16 questions","18 questions","20 questions"],"h1":"It is fewer than 20.","h2":"To pass the Massachusetts learner's permit exam you must answer at least 18 of the 25 questions correctly within the time allowed.","p":"Right. You need 18 correct answers out of 25."},"es":{"q":"En Massachusetts, ¿cuántas preguntas debe contestar bien para aprobar el examen de permiso de aprendiz de 25 preguntas?","o":["15 preguntas","16 preguntas","18 preguntas","20 preguntas"],"h1":"Son menos de 20.","h2":"Para aprobar el examen de permiso de aprendiz de Massachusetts usted debe contestar bien por lo menos 18 de las 25 preguntas dentro del tiempo permitido.","p":"Correcto. Necesita 18 respuestas correctas de 25."},"zh":{"q":"在 Massachusetts，25 道题的学习驾照考试，必须答对几道题才能通过？","o":["15 道题","16 道题","18 道题","20 道题"],"h1":"比 20 少。","h2":"要通过 Massachusetts 的学习驾照考试，你必须在规定时间内答对 25 道题中的至少 18 道。","p":"对。25 道题你需要答对 18 道。"},"vi":{"q":"Ở Massachusetts, bạn phải trả lời đúng bao nhiêu câu để đậu bài thi giấy phép tập lái có 25 câu hỏi?","o":["15 câu","16 câu","18 câu","20 câu"],"h1":"Số câu ít hơn 20.","h2":"Để đậu bài thi giấy phép tập lái ở Massachusetts, bạn phải trả lời đúng ít nhất 18 trong 25 câu trong thời gian cho phép.","p":"Đúng. Bạn cần trả lời đúng 18 trên 25 câu."},"tl":{"q":"Sa Massachusetts, ilang tanong ang dapat mong masagot nang tama para pumasa sa 25-tanong na learner's permit exam?","o":["15 tanong","16 tanong","18 tanong","20 tanong"],"h1":"Mas kaunti ito sa 20.","h2":"Para pumasa sa learner's permit exam ng Massachusetts, dapat mong masagot nang tama ang hindi bababa sa 18 sa 25 tanong sa loob ng ibinigay na oras.","p":"Tama. Kailangan mo ng 18 tamang sagot sa 25."},"ar":{"q":"في Massachusetts، كم سؤالًا يجب أن تجيب عنه إجابة صحيحة لتنجح في امتحان تصريح تعلّم القيادة المكوّن من 25 سؤالًا؟","o":["15 سؤالًا","16 سؤالًا","18 سؤالًا","20 سؤالًا"],"h1":"العدد أقل من 20.","h2":"لتنجح في امتحان تصريح تعلّم القيادة في Massachusetts يجب أن تجيب إجابة صحيحة عن 18 سؤالًا على الأقل من 25 خلال الوقت المسموح.","p":"صحيح. تحتاج إلى 18 إجابة صحيحة من 25."},"ref":{"doc":"MA","page":16}},{"id":"ma-006","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, can you take the learner's permit exam in Spanish?","o":["Yes, Spanish is offered","No, it is English only","Only after failing in English","Only with a private tutor"],"h1":"The RMV offers the exam in many languages.","h2":"The Massachusetts learner's permit exam is offered in Spanish and many other languages, so you can take it in the language you read best.","p":"Right. You can take the Massachusetts permit exam in Spanish."},"es":{"q":"En Massachusetts, ¿se puede tomar el examen de permiso de aprendiz en español?","o":["Sí, se ofrece en español","No, solo en inglés","Solo si reprueba en inglés","Solo con un tutor privado"],"h1":"El RMV ofrece el examen en muchos idiomas.","h2":"En Massachusetts el examen de permiso de aprendiz se ofrece en español y en muchos otros idiomas, así que usted puede tomarlo en el idioma que lee mejor.","p":"Correcto. Puede tomar el examen de permiso de Massachusetts en español."},"zh":{"q":"在 Massachusetts，你可以用西班牙语参加学习驾照考试吗？","o":["可以，有西班牙语","不可以，只有英语","只能在英语考试不及格以后","只能请私人老师陪同"],"h1":"RMV 提供很多种语言的考试。","h2":"Massachusetts 的学习驾照考试有西班牙语和很多其他语言，所以你可以用你读得最好的语言参加考试。","p":"对。你可以用西班牙语参加 Massachusetts 的学习驾照考试。"},"vi":{"q":"Ở Massachusetts, bạn có thể thi giấy phép tập lái bằng tiếng Tây Ban Nha không?","o":["Có, có bài thi tiếng Tây Ban Nha","Không, chỉ có tiếng Anh","Chỉ sau khi thi rớt bằng tiếng Anh","Chỉ khi có gia sư riêng"],"h1":"RMV có bài thi bằng nhiều ngôn ngữ.","h2":"Bài thi giấy phép tập lái ở Massachusetts có bằng tiếng Tây Ban Nha và nhiều ngôn ngữ khác, nên bạn có thể thi bằng ngôn ngữ bạn đọc tốt nhất.","p":"Đúng. Bạn có thể thi giấy phép tập lái ở Massachusetts bằng tiếng Tây Ban Nha."},"tl":{"q":"Sa Massachusetts, puwede mo bang kunin ang learner's permit exam sa Spanish?","o":["Oo, may Spanish","Hindi, English lang","Pagkatapos lang bumagsak sa English","Kung may private tutor lang"],"h1":"Nag-aalok ang RMV ng exam sa maraming wika.","h2":"Ang learner's permit exam ng Massachusetts ay inaalok sa Spanish at sa maraming ibang wika, kaya puwede mo itong kunin sa wikang pinakamahusay mong nababasa.","p":"Tama. Puwede mong kunin ang permit exam ng Massachusetts sa Spanish."},"ar":{"q":"في Massachusetts، هل يمكنك أن تؤدي امتحان تصريح تعلّم القيادة باللغة الإسبانية؟","o":["نعم، الإسبانية متاحة","لا، بالإنجليزية فقط","فقط بعد الرسوب بالإنجليزية","فقط مع مدرّس خاص"],"h1":"تقدّم RMV الامتحان بلغات كثيرة.","h2":"امتحان تصريح تعلّم القيادة في Massachusetts متاح بالإسبانية وبلغات كثيرة أخرى، فيمكنك أن تؤديه باللغة التي تقرؤها أفضل.","p":"صحيح. يمكنك أن تؤدي امتحان التصريح في Massachusetts بالإسبانية."},"ref":{"doc":"MA","page":17}},{"id":"ma-007","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, how long must you hold a learner's permit before the road test for a Junior Operator License?","o":["At least 1 month","At least 3 months","At least 12 months","At least 6 months"],"h1":"It is half a year, without a break.","h2":"In Massachusetts you must hold a valid learner's permit for at least six months in a row before the Junior Operator road test, and a suspension starts that time over.","p":"Right. Six months in a row with the permit."},"es":{"q":"En Massachusetts, ¿cuánto tiempo debe tener el permiso de aprendiz antes del examen de manejo para la licencia de operador joven (JOL)?","o":["Por lo menos 1 mes","Por lo menos 3 meses","Por lo menos 12 meses","Por lo menos 6 meses"],"h1":"Es medio año, sin interrupción.","h2":"En Massachusetts usted debe tener un permiso de aprendiz válido por lo menos seis meses seguidos antes del examen de manejo para la JOL, y una suspensión hace que ese tiempo empiece de nuevo.","p":"Correcto. Seis meses seguidos con el permiso."},"zh":{"q":"在 Massachusetts，你必须持有学习驾照多久，才能参加 Junior Operator License 的路考？","o":["至少 1 个月","至少 3 个月","至少 12 个月","至少 6 个月"],"h1":"是半年，中间不能中断。","h2":"在 Massachusetts，你必须连续持有有效的学习驾照至少六个月，才能参加 Junior Operator 路考；如果驾照被暂停，时间要重新算。","p":"对。连续持有学习驾照六个月。"},"vi":{"q":"Ở Massachusetts, bạn phải có giấy phép tập lái bao lâu trước khi thi lái thực hành để lấy bằng lái cho người trẻ (Junior Operator License)?","o":["Ít nhất 1 tháng","Ít nhất 3 tháng","Ít nhất 12 tháng","Ít nhất 6 tháng"],"h1":"Đó là nửa năm, không gián đoạn.","h2":"Ở Massachusetts, bạn phải có giấy phép tập lái hợp lệ ít nhất sáu tháng liên tục trước khi thi lái thực hành cho Junior Operator, và nếu bị treo giấy phép thì phải tính lại từ đầu.","p":"Đúng. Sáu tháng liên tục với giấy phép tập lái."},"tl":{"q":"Sa Massachusetts, gaano katagal mo dapat hawak ang learner's permit bago ang road test para sa Junior Operator License?","o":["Hindi bababa sa 1 buwan","Hindi bababa sa 3 buwan","Hindi bababa sa 12 buwan","Hindi bababa sa 6 na buwan"],"h1":"Kalahating taon ito, nang walang patlang.","h2":"Sa Massachusetts, dapat hawak mo ang valid na learner's permit nang hindi bababa sa anim na magkakasunod na buwan bago ang Junior Operator road test, at kapag na-suspend ito, magsisimula ulit ang bilang.","p":"Tama. Anim na magkakasunod na buwan na may permit."},"ar":{"q":"في Massachusetts، كم مدة يجب أن تحمل تصريح تعلّم القيادة قبل اختبار القيادة العملي لرخصة السائق الصغير (Junior Operator License)؟","o":["شهر واحد على الأقل","3 أشهر على الأقل","12 شهرًا على الأقل","6 أشهر على الأقل"],"h1":"نصف سنة، بدون انقطاع.","h2":"في Massachusetts يجب أن تحمل تصريح تعلّم قيادة صالحًا لمدة ستة أشهر متتالية على الأقل قبل اختبار القيادة العملي لـ Junior Operator، وإذا أُوقف التصريح تبدأ المدة من جديد.","p":"صحيح. ستة أشهر متتالية مع التصريح."},"ref":{"doc":"MA","page":9}},{"id":"ma-008","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, how many hours of supervised driving must a parent or guardian certify for a Junior Operator License?","o":["20 hours","40 hours","50 hours","60 hours"],"h1":"It is fewer than 50 hours.","h2":"A Massachusetts Junior Operator applicant needs at least 40 hours of supervised driving, certified by a parent or guardian, in addition to driver education.","p":"Right. Forty hours of supervised driving."},"es":{"q":"En Massachusetts, ¿cuántas horas de manejo supervisado debe certificar un padre o tutor para la licencia de operador joven (JOL)?","o":["20 horas","40 horas","50 horas","60 horas"],"h1":"Son menos de 50 horas.","h2":"En Massachusetts quien solicita la JOL necesita por lo menos 40 horas de manejo supervisado, certificadas por un padre o tutor, además de la educación vial.","p":"Correcto. Cuarenta horas de manejo supervisado."},"zh":{"q":"在 Massachusetts，申请 Junior Operator License，父母或监护人必须证明完成了多少小时有人陪同的驾驶？","o":["20 小时","40 小时","50 小时","60 小时"],"h1":"比 50 小时少。","h2":"在 Massachusetts，申请 Junior Operator 的人除了上驾驶课，还需要至少 40 小时有人陪同的驾驶，由父母或监护人证明。","p":"对。四十个小时有人陪同的驾驶。"},"vi":{"q":"Ở Massachusetts, cha mẹ hoặc người giám hộ phải xác nhận bao nhiêu giờ lái xe có người giám sát để lấy Junior Operator License?","o":["20 giờ","40 giờ","50 giờ","60 giờ"],"h1":"Số giờ ít hơn 50.","h2":"Người xin Junior Operator License ở Massachusetts cần ít nhất 40 giờ lái xe có người giám sát, được cha mẹ hoặc người giám hộ xác nhận, ngoài khóa giáo dục lái xe.","p":"Đúng. Bốn mươi giờ lái xe có người giám sát."},"tl":{"q":"Sa Massachusetts, ilang oras ng supervised driving ang dapat patunayan ng magulang o guardian para sa Junior Operator License?","o":["20 oras","40 oras","50 oras","60 oras"],"h1":"Mas kaunti ito sa 50 oras.","h2":"Ang nag-a-apply ng Junior Operator License sa Massachusetts ay kailangan ng hindi bababa sa 40 oras ng supervised driving, na pinatunayan ng magulang o guardian, bukod pa sa driver education.","p":"Tama. Apatnapung oras ng supervised driving."},"ar":{"q":"في Massachusetts، كم ساعة من القيادة تحت الإشراف يجب أن يشهد بها أحد الوالدين أو الوصي للحصول على Junior Operator License؟","o":["20 ساعة","40 ساعة","50 ساعة","60 ساعة"],"h1":"العدد أقل من 50 ساعة.","h2":"يحتاج المتقدّم لـ Junior Operator License في Massachusetts إلى 40 ساعة على الأقل من القيادة تحت الإشراف، يشهد بها أحد الوالدين أو الوصي، بالإضافة إلى دروس تعليم القيادة.","p":"صحيح. أربعون ساعة من القيادة تحت الإشراف."},"ref":{"doc":"MA","page":10}},{"id":"ma-009","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, the supervised driving hours drop to how many if the teen completes a driver skills development program?","o":["10 hours","20 hours","30 hours","35 hours"],"h1":"It is 10 hours less than the usual amount.","h2":"In Massachusetts a teen who completes a driver skills development program needs 30 supervised hours instead of 40.","p":"Right. Thirty hours after a driver skills program."},"es":{"q":"En Massachusetts, si el joven completa un programa de desarrollo de destrezas de manejo, ¿a cuántas horas baja el manejo supervisado?","o":["10 horas","20 horas","30 horas","35 horas"],"h1":"Son 10 horas menos de lo normal.","h2":"En Massachusetts un joven que completa un programa de desarrollo de destrezas de manejo necesita 30 horas supervisadas en lugar de 40.","p":"Correcto. Treinta horas después de un programa de destrezas."},"zh":{"q":"在 Massachusetts，如果青少年完成了驾驶技能培训课程，有人陪同的驾驶时间会减少到多少小时？","o":["10 小时","20 小时","30 小时","35 小时"],"h1":"比一般要求少 10 小时。","h2":"在 Massachusetts，完成驾驶技能培训课程的青少年，需要 30 小时有人陪同的驾驶，而不是 40 小时。","p":"对。上完驾驶技能课程后是三十个小时。"},"vi":{"q":"Ở Massachusetts, nếu thanh thiếu niên học xong một chương trình phát triển kỹ năng lái xe (driver skills development program), số giờ lái xe có người giám sát giảm xuống còn bao nhiêu?","o":["10 giờ","20 giờ","30 giờ","35 giờ"],"h1":"Ít hơn số giờ thông thường 10 giờ.","h2":"Ở Massachusetts, thanh thiếu niên học xong một chương trình phát triển kỹ năng lái xe cần 30 giờ có người giám sát thay vì 40 giờ.","p":"Đúng. Ba mươi giờ sau khi học xong chương trình kỹ năng lái xe."},"tl":{"q":"Sa Massachusetts, ilan na lang ang oras ng supervised driving kung natapos ng teen ang isang driver skills development program?","o":["10 oras","20 oras","30 oras","35 oras"],"h1":"Mas kaunti ito nang 10 oras kaysa sa karaniwan.","h2":"Sa Massachusetts, ang teen na nakatapos ng driver skills development program ay kailangan ng 30 supervised na oras sa halip na 40.","p":"Tama. Tatlumpung oras pagkatapos ng driver skills program."},"ar":{"q":"في Massachusetts، إلى كم تنخفض ساعات القيادة تحت الإشراف إذا أنهى المراهق برنامجًا لتطوير مهارات القيادة (driver skills development program)؟","o":["10 ساعات","20 ساعة","30 ساعة","35 ساعة"],"h1":"أقل من العدد المعتاد بـ 10 ساعات.","h2":"في Massachusetts يحتاج المراهق الذي أنهى برنامجًا لتطوير مهارات القيادة إلى 30 ساعة تحت الإشراف بدلًا من 40.","p":"صحيح. ثلاثون ساعة بعد برنامج مهارات القيادة."},"ref":{"doc":"MA","page":10}},{"id":"ma-010","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, how many hours of classroom instruction does driver education include for teens?","o":["20 hours","30 hours","40 hours","12 hours"],"h1":"It is the same number as the reduced supervised hours.","h2":"Massachusetts driver education for teens includes 30 hours of classroom instruction on state traffic law and safe driving.","p":"Right. Thirty hours in the classroom."},"es":{"q":"En Massachusetts, ¿cuántas horas de clase en el aula incluye la educación vial para jóvenes?","o":["20 horas","30 horas","40 horas","12 horas"],"h1":"Es el mismo número que las horas supervisadas reducidas.","h2":"En Massachusetts la educación vial para jóvenes incluye 30 horas de clase en el aula sobre las leyes de tránsito del estado y el manejo seguro.","p":"Correcto. Treinta horas en el aula."},"zh":{"q":"在 Massachusetts，青少年的驾驶课包括多少小时课堂教学？","o":["20 小时","30 小时","40 小时","12 小时"],"h1":"和减少后的有人陪同时间一样。","h2":"在 Massachusetts，青少年的驾驶课包括 30 小时课堂教学，讲州交通法和安全驾驶。","p":"对。课堂里三十个小时。"},"vi":{"q":"Ở Massachusetts, khóa giáo dục lái xe cho thanh thiếu niên có bao nhiêu giờ học trên lớp?","o":["20 giờ","30 giờ","40 giờ","12 giờ"],"h1":"Bằng với số giờ có người giám sát đã được giảm.","h2":"Khóa giáo dục lái xe cho thanh thiếu niên ở Massachusetts có 30 giờ học trên lớp về luật giao thông của tiểu bang và cách lái xe an toàn.","p":"Đúng. Ba mươi giờ học trên lớp."},"tl":{"q":"Sa Massachusetts, ilang oras ng pag-aaral sa classroom ang kasama sa driver education para sa mga teen?","o":["20 oras","30 oras","40 oras","12 oras"],"h1":"Pareho ito sa nabawasang bilang ng supervised na oras.","h2":"Ang driver education para sa mga teen sa Massachusetts ay may 30 oras ng pag-aaral sa classroom tungkol sa batas trapiko ng estado at ligtas na pagmamaneho.","p":"Tama. Tatlumpung oras sa classroom."},"ar":{"q":"في Massachusetts، كم ساعة من الدروس في الصف تشمل دروس تعليم القيادة للمراهقين؟","o":["20 ساعة","30 ساعة","40 ساعة","12 ساعة"],"h1":"هو نفس عدد ساعات القيادة تحت الإشراف بعد تخفيضها.","h2":"تشمل دروس تعليم القيادة للمراهقين في Massachusetts 30 ساعة من الدروس في الصف عن قوانين المرور في الولاية والقيادة الآمنة.","p":"صحيح. ثلاثون ساعة في الصف."},"ref":{"doc":"MA","page":10}},{"id":"ma-011","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, how many hours of behind-the-wheel training with a driving school are required in teen driver education?","o":["12 hours","6 hours","18 hours","30 hours"],"h1":"The on-road part is 18 hours in all, and 6 of those are watching another student.","h2":"Massachusetts teen driver education requires at least 12 hours of behind-the-wheel training, plus 6 hours of watching another student drive.","p":"Right. Twelve hours behind the wheel."},"es":{"q":"En Massachusetts, ¿cuántas horas de práctica al volante con una escuela de manejo exige la educación vial para jóvenes?","o":["12 horas","6 horas","18 horas","30 horas"],"h1":"La parte en la calle suma 18 horas, y 6 de ellas son para observar a otro estudiante.","h2":"En Massachusetts la educación vial para jóvenes exige por lo menos 12 horas al volante, más 6 horas observando a otro estudiante manejar.","p":"Correcto. Doce horas al volante."},"zh":{"q":"在 Massachusetts，青少年驾驶课要求在驾校实际开车培训多少小时？","o":["12 小时","6 小时","18 小时","30 小时"],"h1":"上路部分一共是 18 小时，其中 6 小时是看另一个学生开车。","h2":"在 Massachusetts，青少年驾驶课要求至少 12 小时实际开车培训，另外还有 6 小时看另一个学生开车。","p":"对。实际开车十二个小时。"},"vi":{"q":"Ở Massachusetts, khóa giáo dục lái xe cho thanh thiếu niên yêu cầu bao nhiêu giờ tập lái thực tế với trường dạy lái xe?","o":["12 giờ","6 giờ","18 giờ","30 giờ"],"h1":"Phần trên đường tổng cộng 18 giờ, trong đó 6 giờ là ngồi xem học viên khác lái.","h2":"Khóa giáo dục lái xe cho thanh thiếu niên ở Massachusetts yêu cầu ít nhất 12 giờ tập lái thực tế, cộng thêm 6 giờ ngồi xem học viên khác lái.","p":"Đúng. Mười hai giờ tự cầm lái."},"tl":{"q":"Sa Massachusetts, ilang oras ng behind-the-wheel training kasama ang driving school ang kailangan sa teen driver education?","o":["12 oras","6 na oras","18 oras","30 oras"],"h1":"Ang bahagi sa kalsada ay 18 oras lahat, at 6 doon ay panonood sa ibang estudyante.","h2":"Ang teen driver education sa Massachusetts ay nangangailangan ng hindi bababa sa 12 oras ng behind-the-wheel training, dagdag ang 6 na oras ng panonood sa ibang estudyanteng nagmamaneho.","p":"Tama. Labindalawang oras sa manibela."},"ar":{"q":"في Massachusetts، كم ساعة من التدريب العملي خلف المقود مع مدرسة قيادة مطلوبة في دروس تعليم القيادة للمراهقين؟","o":["12 ساعة","6 ساعات","18 ساعة","30 ساعة"],"h1":"الجزء على الطريق 18 ساعة في المجموع، منها 6 ساعات لمشاهدة طالب آخر.","h2":"تتطلّب دروس تعليم القيادة للمراهقين في Massachusetts 12 ساعة على الأقل من التدريب العملي خلف المقود، بالإضافة إلى 6 ساعات لمشاهدة طالب آخر يقود.","p":"صحيح. اثنتا عشرة ساعة خلف المقود."},"ref":{"doc":"MA","page":10}},{"id":"ma-012","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, what must a parent or guardian of a teen in driver education usually complete?","o":["A written road test","A 10-hour driving course","A first-aid class","A 2-hour parent class"],"h1":"It is a short class about the driver education course.","h2":"In Massachusetts a parent or guardian must take a 2-hour class about the driver education course, unless they took one in the past five years.","p":"Right. Parents take a 2-hour class."},"es":{"q":"En Massachusetts, ¿qué debe completar normalmente el padre o tutor de un joven en educación vial?","o":["Un examen escrito de manejo","Un curso de manejo de 10 horas","Una clase de primeros auxilios","Una clase para padres de 2 horas"],"h1":"Es una clase corta sobre el curso de educación vial.","h2":"En Massachusetts el padre o tutor debe tomar una clase de 2 horas sobre el curso de educación vial, a menos que haya tomado una en los últimos cinco años.","p":"Correcto. Los padres toman una clase de 2 horas."},"zh":{"q":"在 Massachusetts，上驾驶课的青少年的父母或监护人，一般必须完成什么？","o":["路考笔试","10 小时的驾驶课","急救课","2 小时的家长课"],"h1":"这是一门关于驾驶课的短课。","h2":"在 Massachusetts，父母或监护人必须上一门关于驾驶课的 2 小时课程，除非他们在过去五年里上过。","p":"对。父母要上 2 小时的课。"},"vi":{"q":"Ở Massachusetts, cha mẹ hoặc người giám hộ của thanh thiếu niên đang học lái xe thường phải hoàn thành điều gì?","o":["Một bài thi viết về lái xe","Một khóa lái xe 10 giờ","Một lớp sơ cứu","Một lớp 2 giờ dành cho phụ huynh"],"h1":"Đó là một lớp ngắn về khóa giáo dục lái xe.","h2":"Ở Massachusetts, cha mẹ hoặc người giám hộ phải học một lớp 2 giờ về khóa giáo dục lái xe, trừ khi họ đã học lớp này trong năm năm qua.","p":"Đúng. Phụ huynh học một lớp 2 giờ."},"tl":{"q":"Sa Massachusetts, ano ang karaniwang dapat tapusin ng magulang o guardian ng teen na nasa driver education?","o":["Isang written road test","Isang 10-oras na driving course","Isang first-aid class","Isang 2-oras na parent class"],"h1":"Isa itong maikling klase tungkol sa driver education course.","h2":"Sa Massachusetts, dapat kumuha ang magulang o guardian ng 2-oras na klase tungkol sa driver education course, maliban kung kumuha na sila nito sa nakaraang limang taon.","p":"Tama. Kumukuha ang mga magulang ng 2-oras na klase."},"ar":{"q":"في Massachusetts، ماذا يجب عادةً على أحد الوالدين أو الوصي لمراهق يدرس تعليم القيادة أن يُنهي؟","o":["اختبار طريق كتابي","دورة قيادة مدتها 10 ساعات","درس في الإسعافات الأولية","درس للوالدين مدته ساعتان"],"h1":"هو درس قصير عن دورة تعليم القيادة.","h2":"في Massachusetts يجب على أحد الوالدين أو الوصي أن يحضر درسًا مدته ساعتان عن دورة تعليم القيادة، إلا إذا حضر درسًا مثله في السنوات الخمس الماضية.","p":"صحيح. يحضر الوالدان درسًا مدته ساعتان."},"ref":{"doc":"MA","page":10}},{"id":"ma-013","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, a Junior Operator License holder may not drive during which hours unless a parent or guardian is in the car?","o":["From midnight to 6 a.m.","From 11 p.m. to 5 a.m.","From 12:30 a.m. to 5 a.m.","From 1 a.m. to 6 a.m."],"h1":"It starts half an hour after midnight.","h2":"A Massachusetts Junior Operator may not drive between 12:30 a.m. and 5 a.m. unless a parent or legal guardian is with them.","p":"Right. No driving from 12:30 to 5 a.m. without a parent or guardian."},"es":{"q":"En Massachusetts, ¿en qué horario no puede manejar quien tiene licencia de operador joven (JOL) si no va con él un padre o tutor?","o":["De medianoche a 6 a.m.","De 11 p.m. a 5 a.m.","De 12:30 a.m. a 5 a.m.","De 1 a.m. a 6 a.m."],"h1":"Empieza media hora después de la medianoche.","h2":"En Massachusetts un operador joven no puede manejar entre las 12:30 a.m. y las 5 a.m. si no va con él un padre o tutor legal.","p":"Correcto. No se maneja de 12:30 a 5 a.m. sin un padre o tutor."},"zh":{"q":"在 Massachusetts，持 Junior Operator License 的人，除非父母或监护人在车上，哪些时间不能开车？","o":["午夜到早上 6 点","晚上 11 点到早上 5 点","凌晨 12:30 到早上 5 点","凌晨 1 点到早上 6 点"],"h1":"它从午夜后半小时开始。","h2":"在 Massachusetts，持 Junior Operator License 的人在凌晨 12:30 到早上 5 点之间不能开车，除非父母或法定监护人一起。","p":"对。没有父母或监护人，凌晨 12:30 到 5 点不能开车。"},"vi":{"q":"Ở Massachusetts, người có Junior Operator License không được lái xe trong những giờ nào, trừ khi có cha mẹ hoặc người giám hộ trong xe?","o":["Từ nửa đêm đến 6 giờ sáng","Từ 11 giờ tối đến 5 giờ sáng","Từ 12:30 sáng đến 5 giờ sáng","Từ 1 giờ sáng đến 6 giờ sáng"],"h1":"Thời gian này bắt đầu nửa tiếng sau nửa đêm.","h2":"Người có Junior Operator License ở Massachusetts không được lái xe từ 12:30 sáng đến 5 giờ sáng, trừ khi có cha mẹ hoặc người giám hộ hợp pháp đi cùng.","p":"Đúng. Không lái xe từ 12:30 đến 5 giờ sáng nếu không có cha mẹ hoặc người giám hộ."},"tl":{"q":"Sa Massachusetts, sa anong oras hindi puwedeng magmaneho ang may Junior Operator License, maliban kung may magulang o guardian sa sasakyan?","o":["Mula hatinggabi hanggang 6 a.m.","Mula 11 p.m. hanggang 5 a.m.","Mula 12:30 a.m. hanggang 5 a.m.","Mula 1 a.m. hanggang 6 a.m."],"h1":"Nagsisimula ito kalahating oras pagkatapos ng hatinggabi.","h2":"Ang Junior Operator sa Massachusetts ay hindi puwedeng magmaneho mula 12:30 a.m. hanggang 5 a.m. maliban kung kasama ang magulang o legal guardian.","p":"Tama. Bawal magmaneho mula 12:30 hanggang 5 a.m. kung walang magulang o guardian."},"ar":{"q":"في Massachusetts، في أي ساعات لا يجوز لحامل Junior Operator License أن يقود، إلا إذا كان أحد الوالدين أو الوصي في السيارة؟","o":["من منتصف الليل إلى 6 صباحًا","من 11 مساءً إلى 5 صباحًا","من 12:30 بعد منتصف الليل إلى 5 صباحًا","من 1 صباحًا إلى 6 صباحًا"],"h1":"تبدأ بعد منتصف الليل بنصف ساعة.","h2":"لا يجوز لحامل Junior Operator License في Massachusetts أن يقود بين 12:30 بعد منتصف الليل و5 صباحًا إلا إذا كان معه أحد الوالدين أو الوصي القانوني.","p":"صحيح. ممنوع القيادة من 12:30 إلى 5 صباحًا بدون أحد الوالدين أو الوصي."},"ref":{"doc":"MA","page":10}},{"id":"ma-014","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, during the first six months with a Junior Operator License, who may not ride with you unless an adult 21+ is beside you?","o":["Passengers under 18 who are not family","Any passenger over age 65","Your brothers and sisters","Any passenger at all"],"h1":"The rule is about young friends, not family.","h2":"For the first six months, a Massachusetts Junior Operator may not carry passengers under 18 who are not immediate family unless a licensed adult age 21 or older is beside them.","p":"Right. No young non-family passengers in the first six months."},"es":{"q":"En Massachusetts, durante los primeros seis meses con licencia de operador joven, ¿quién no puede ir con usted si no hay un adulto de 21+ a su lado?","o":["Pasajeros menores de 18 que no son familia","Cualquier pasajero mayor de 65 años","Sus hermanos y hermanas","Ningún pasajero en absoluto"],"h1":"La regla es sobre amigos jóvenes, no sobre la familia.","h2":"Durante los primeros seis meses, un operador joven en Massachusetts no puede llevar pasajeros menores de 18 que no sean familia directa, a menos que vaya a su lado un adulto con licencia de 21 años o más.","p":"Correcto. Nada de pasajeros jóvenes que no son familia los primeros seis meses."},"zh":{"q":"在 Massachusetts，拿到 Junior Operator License 的头六个月里，除非有一位 21 岁以上的成年人坐在你旁边，谁不能和你一起坐车？","o":["不是家人、18 岁以下的乘客","任何 65 岁以上的乘客","你的兄弟姐妹","任何乘客都不行"],"h1":"这个规定是关于年轻朋友的，不是家人。","h2":"在头六个月里，Massachusetts 持 Junior Operator License 的人不能载不是直系亲属、18 岁以下的乘客，除非一位 21 岁或以上、有驾照的成年人坐在旁边。","p":"对。头六个月不能载不是家人的年轻乘客。"},"vi":{"q":"Ở Massachusetts, trong sáu tháng đầu có Junior Operator License, ai không được đi xe với bạn, trừ khi có một người lớn từ 21 tuổi trở lên ngồi bên cạnh?","o":["Hành khách dưới 18 tuổi không phải người trong gia đình","Bất kỳ hành khách nào trên 65 tuổi","Anh chị em của bạn","Bất kỳ hành khách nào"],"h1":"Quy định này nói về bạn bè trẻ tuổi, không phải gia đình.","h2":"Trong sáu tháng đầu, người có Junior Operator License ở Massachusetts không được chở hành khách dưới 18 tuổi không phải người thân trong gia đình, trừ khi có một người lớn có bằng lái từ 21 tuổi trở lên ngồi bên cạnh.","p":"Đúng. Không chở hành khách trẻ tuổi không phải người nhà trong sáu tháng đầu."},"tl":{"q":"Sa Massachusetts, sa unang anim na buwan na may Junior Operator License, sino ang hindi puwedeng sumakay sa iyo maliban kung may adult na 21 pataas sa tabi mo?","o":["Mga pasaherong wala pang 18 na hindi kapamilya","Kahit sinong pasaherong lampas 65","Ang iyong mga kapatid","Kahit sinong pasahero"],"h1":"Tungkol ang patakaran sa mga batang kaibigan, hindi sa pamilya.","h2":"Sa unang anim na buwan, ang Junior Operator sa Massachusetts ay hindi puwedeng magsakay ng mga pasaherong wala pang 18 na hindi kasapi ng malapit na pamilya, maliban kung may may lisensyang adult na 21 pataas sa tabi niya.","p":"Tama. Bawal ang batang pasaherong hindi kapamilya sa unang anim na buwan."},"ar":{"q":"في Massachusetts، في الأشهر الستة الأولى مع Junior Operator License، من لا يجوز أن يركب معك إلا إذا كان بجانبك شخص بالغ عمره 21 سنة أو أكثر؟","o":["الركاب الذين عمرهم أقل من 18 سنة وليسوا من العائلة","أي راكب عمره أكثر من 65 سنة","إخوتك وأخواتك","أي راكب على الإطلاق"],"h1":"القاعدة عن الأصدقاء الصغار، وليست عن العائلة.","h2":"في الأشهر الستة الأولى، لا يجوز لحامل Junior Operator License في Massachusetts أن يحمل ركابًا عمرهم أقل من 18 سنة وليسوا من العائلة المباشرة، إلا إذا كان بجانبه شخص بالغ مرخّص عمره 21 سنة أو أكثر.","p":"صحيح. ممنوع الركاب الصغار من غير العائلة في الأشهر الستة الأولى."},"ref":{"doc":"MA","page":10}},{"id":"ma-015","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, what is the license suspension for a Junior Operator's first speeding offense?","o":["30 days","60 days","1 year","90 days"],"h1":"It is about three months.","h2":"In Massachusetts a Junior Operator's first speeding offense brings a 90-day license suspension, and a second offense brings one year.","p":"Right. A first speeding offense means 90 days without a license."},"es":{"q":"En Massachusetts, ¿cuánto dura la suspensión de la licencia de un operador joven por su primera multa por exceso de velocidad?","o":["30 días","60 días","1 año","90 días"],"h1":"Son unos tres meses.","h2":"En Massachusetts la primera infracción por exceso de velocidad de un operador joven trae una suspensión de 90 días, y la segunda trae un año.","p":"Correcto. La primera multa por velocidad significa 90 días sin licencia."},"zh":{"q":"在 Massachusetts，持 Junior Operator License 的人第一次超速，驾照会被暂停多久？","o":["30 天","60 天","1 年","90 天"],"h1":"大约是三个月。","h2":"在 Massachusetts，持 Junior Operator License 的人第一次超速，驾照会被暂停 90 天，第二次会被暂停一年。","p":"对。第一次超速，90 天没有驾照。"},"vi":{"q":"Ở Massachusetts, người có Junior Operator License vi phạm chạy quá tốc độ lần đầu sẽ bị treo bằng lái bao lâu?","o":["30 ngày","60 ngày","1 năm","90 ngày"],"h1":"Khoảng ba tháng.","h2":"Ở Massachusetts, người có Junior Operator License vi phạm chạy quá tốc độ lần đầu bị treo bằng lái 90 ngày, và lần thứ hai bị treo một năm.","p":"Đúng. Chạy quá tốc độ lần đầu là 90 ngày không có bằng lái."},"tl":{"q":"Sa Massachusetts, gaano katagal ang suspensyon ng lisensya para sa unang speeding offense ng Junior Operator?","o":["30 araw","60 araw","1 taon","90 araw"],"h1":"Mga tatlong buwan ito.","h2":"Sa Massachusetts, ang unang speeding offense ng Junior Operator ay may 90-araw na suspensyon ng lisensya, at ang ikalawa ay isang taon.","p":"Tama. Ang unang speeding offense ay 90 araw na walang lisensya."},"ar":{"q":"في Massachusetts، ما مدة إيقاف الرخصة لأول مخالفة سرعة لحامل Junior Operator License؟","o":["30 يومًا","60 يومًا","سنة واحدة","90 يومًا"],"h1":"حوالي ثلاثة أشهر.","h2":"في Massachusetts تؤدي أول مخالفة سرعة لحامل Junior Operator License إلى إيقاف الرخصة 90 يومًا، والمخالفة الثانية تؤدي إلى إيقافها سنة واحدة.","p":"صحيح. أول مخالفة سرعة تعني 90 يومًا بدون رخصة."},"ref":{"doc":"MA","page":11}},{"id":"ma-016","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, what is the suspension for a Junior Operator's first passenger or night-time violation?","o":["30 days","60 days","90 days","180 days"],"h1":"It is two months.","h2":"A Massachusetts Junior Operator who breaks the passenger or night-time rule for the first time loses the license for 60 days.","p":"Right. Sixty days for a first passenger or night violation."},"es":{"q":"En Massachusetts, ¿cuál es la suspensión por la primera infracción de pasajeros o de horario nocturno de un operador joven?","o":["30 días","60 días","90 días","180 días"],"h1":"Son dos meses.","h2":"En Massachusetts un operador joven que no cumple por primera vez la regla de pasajeros o de horario nocturno pierde la licencia por 60 días.","p":"Correcto. Sesenta días por la primera infracción de pasajeros o de noche."},"zh":{"q":"在 Massachusetts，持 Junior Operator License 的人第一次违反乘客或夜间规定，驾照会被暂停多久？","o":["30 天","60 天","90 天","180 天"],"h1":"是两个月。","h2":"在 Massachusetts，持 Junior Operator License 的人第一次违反乘客或夜间规定，会失去驾照 60 天。","p":"对。第一次违反乘客或夜间规定，暂停六十天。"},"vi":{"q":"Ở Massachusetts, người có Junior Operator License vi phạm quy định về hành khách hoặc lái xe ban đêm lần đầu sẽ bị treo bằng lái bao lâu?","o":["30 ngày","60 ngày","90 ngày","180 ngày"],"h1":"Đó là hai tháng.","h2":"Người có Junior Operator License ở Massachusetts vi phạm quy định về hành khách hoặc lái xe ban đêm lần đầu sẽ bị mất bằng lái 60 ngày.","p":"Đúng. Sáu mươi ngày cho lần đầu vi phạm quy định về hành khách hoặc ban đêm."},"tl":{"q":"Sa Massachusetts, gaano katagal ang suspensyon para sa unang paglabag ng Junior Operator sa patakaran sa pasahero o sa gabi?","o":["30 araw","60 araw","90 araw","180 araw"],"h1":"Dalawang buwan ito.","h2":"Ang Junior Operator sa Massachusetts na unang lumabag sa patakaran sa pasahero o sa gabi ay mawawalan ng lisensya nang 60 araw.","p":"Tama. Animnapung araw para sa unang paglabag sa pasahero o sa gabi."},"ar":{"q":"في Massachusetts، ما مدة الإيقاف لأول مخالفة لقاعدة الركاب أو القيادة الليلية لحامل Junior Operator License؟","o":["30 يومًا","60 يومًا","90 يومًا","180 يومًا"],"h1":"شهران.","h2":"حامل Junior Operator License في Massachusetts الذي يخالف قاعدة الركاب أو القيادة الليلية لأول مرة يفقد الرخصة لمدة 60 يومًا.","p":"صحيح. ستون يومًا لأول مخالفة للركاب أو الليل."},"ref":{"doc":"MA","page":11}},{"id":"ma-017","scope":"MA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Massachusetts, may a driver under 18 talk on a phone in hands-free mode while driving?","o":["Yes, with a headset only","Yes, on the highway only","No, except to report an emergency","Yes, if a parent calls"],"h1":"Drivers under 18 have a stricter rule than adults.","h2":"In Massachusetts a driver under 18 may not use any phone or mobile device while driving, even hands-free, except to report an emergency.","p":"Right. Drivers under 18 may not use a phone at all, except for emergencies."},"es":{"q":"En Massachusetts, ¿puede un conductor menor de 18 años hablar por teléfono en modo manos libres mientras maneja?","o":["Sí, solo con auriculares","Sí, solo en la autopista","No, salvo para reportar una emergencia","Sí, si llaman sus padres"],"h1":"Los menores de 18 tienen una regla más estricta que los adultos.","h2":"En Massachusetts un conductor menor de 18 años no puede usar ningún teléfono ni aparato móvil mientras maneja, ni siquiera con manos libres, salvo para reportar una emergencia.","p":"Correcto. Los menores de 18 no usan el teléfono, salvo en emergencias."},"zh":{"q":"在 Massachusetts，18 岁以下的司机开车时可以用免提模式打电话吗？","o":["可以，但只能用耳机","可以，但只能在高速公路上","不可以，除非报告紧急情况","可以，如果是父母打来的"],"h1":"18 岁以下的司机，规定比成年人更严格。","h2":"在 Massachusetts，18 岁以下的司机开车时不能使用任何手机或移动设备，免提也不行，只有报告紧急情况除外。","p":"对。18 岁以下的司机完全不能用手机，紧急情况除外。"},"vi":{"q":"Ở Massachusetts, người lái xe dưới 18 tuổi có được nói chuyện điện thoại ở chế độ rảnh tay khi lái xe không?","o":["Có, chỉ khi dùng tai nghe","Có, chỉ trên xa lộ","Không, trừ khi để báo trường hợp khẩn cấp","Có, nếu cha mẹ gọi"],"h1":"Người lái xe dưới 18 tuổi có quy định nghiêm hơn người lớn.","h2":"Ở Massachusetts, người lái xe dưới 18 tuổi không được dùng bất kỳ điện thoại hoặc thiết bị di động nào khi lái xe, kể cả chế độ rảnh tay, trừ khi để báo trường hợp khẩn cấp.","p":"Đúng. Người lái xe dưới 18 tuổi hoàn toàn không được dùng điện thoại, trừ trường hợp khẩn cấp."},"tl":{"q":"Sa Massachusetts, puwede bang makipag-usap sa phone nang hands-free ang driver na wala pang 18 habang nagmamaneho?","o":["Oo, gamit lang ang headset","Oo, sa highway lang","Hindi, maliban para mag-report ng emergency","Oo, kung magulang ang tumawag"],"h1":"Mas mahigpit ang patakaran para sa mga driver na wala pang 18 kaysa sa mga adult.","h2":"Sa Massachusetts, ang driver na wala pang 18 ay hindi puwedeng gumamit ng anumang phone o mobile device habang nagmamaneho, kahit hands-free, maliban para mag-report ng emergency.","p":"Tama. Bawal talaga sa phone ang mga driver na wala pang 18, maliban sa emergency."},"ar":{"q":"في Massachusetts، هل يجوز للسائق الذي عمره أقل من 18 سنة أن يتحدث في الهاتف بوضع عدم استخدام اليدين (hands-free) أثناء القيادة؟","o":["نعم، مع سماعة رأس فقط","نعم، على الطريق السريع فقط","لا، إلا للإبلاغ عن حالة طوارئ","نعم، إذا اتصل أحد الوالدين"],"h1":"للسائقين تحت 18 سنة قاعدة أشد من البالغين.","h2":"في Massachusetts لا يجوز للسائق الذي عمره أقل من 18 سنة أن يستخدم أي هاتف أو جهاز محمول أثناء القيادة، حتى بوضع hands-free، إلا للإبلاغ عن حالة طوارئ.","p":"صحيح. السائقون تحت 18 سنة لا يستخدمون الهاتف أبدًا، إلا في حالات الطوارئ."},"ref":{"doc":"MA","page":40}},{"id":"ma-018","scope":"MA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Massachusetts, how may an adult driver use a phone while driving?","o":["Only in hands-free mode","Holding it at red lights","Holding it on quiet streets","Holding it for short calls"],"h1":"Your hands stay on the wheel.","h2":"Massachusetts law lets adult drivers use a phone only in hands-free mode, with the phone mounted, and allows a single touch to start hands-free mode.","p":"Right. Adults may use a phone only hands-free."},"es":{"q":"En Massachusetts, ¿cómo puede un conductor adulto usar el teléfono mientras maneja?","o":["Solo en modo manos libres","Sosteniéndolo en los semáforos","Sosteniéndolo en calles tranquilas","Sosteniéndolo en llamadas cortas"],"h1":"Sus manos se quedan en el volante.","h2":"La ley de Massachusetts permite a los adultos usar el teléfono solo en modo manos libres, con el teléfono sujeto en un soporte, y permite tocarlo una vez para activar ese modo.","p":"Correcto. Los adultos usan el teléfono solo con manos libres."},"zh":{"q":"在 Massachusetts，成年司机开车时可以怎样使用手机？","o":["只能用免提模式","红灯时拿在手里","在安静的街道上拿在手里","短时间通话时拿在手里"],"h1":"你的手要一直放在方向盘上。","h2":"Massachusetts 法律只允许成年司机用免提模式使用手机，手机要固定在支架上，可以按一下来开启免提模式。","p":"对。成年人只能用免提使用手机。"},"vi":{"q":"Ở Massachusetts, người lái xe trưởng thành được dùng điện thoại khi lái xe như thế nào?","o":["Chỉ ở chế độ rảnh tay","Cầm trên tay khi gặp đèn đỏ","Cầm trên tay trên đường vắng","Cầm trên tay cho cuộc gọi ngắn"],"h1":"Tay bạn luôn ở trên vô lăng.","h2":"Luật Massachusetts chỉ cho phép người lái xe trưởng thành dùng điện thoại ở chế độ rảnh tay, với điện thoại được gắn cố định, và cho phép chạm một lần để bật chế độ rảnh tay.","p":"Đúng. Người lớn chỉ được dùng điện thoại ở chế độ rảnh tay."},"tl":{"q":"Sa Massachusetts, paano puwedeng gumamit ng phone ang adult na driver habang nagmamaneho?","o":["Sa hands-free mode lang","Hawak ito sa red light","Hawak ito sa tahimik na kalye","Hawak ito para sa maikling tawag"],"h1":"Nananatili ang mga kamay mo sa manibela.","h2":"Pinapayagan ng batas ng Massachusetts ang mga adult na driver na gumamit ng phone sa hands-free mode lang, na nakakabit ang phone, at pinapayagan ang isang pindot para buksan ang hands-free mode.","p":"Tama. Puwedeng gumamit ng phone ang mga adult nang hands-free lang."},"ar":{"q":"في Massachusetts، كيف يجوز للسائق البالغ أن يستخدم الهاتف أثناء القيادة؟","o":["بوضع عدم استخدام اليدين (hands-free) فقط","يمسكه في يده عند الإشارة الحمراء","يمسكه في يده في الشوارع الهادئة","يمسكه في يده للمكالمات القصيرة"],"h1":"يداك تبقيان على المقود.","h2":"يسمح قانون Massachusetts للسائقين البالغين باستخدام الهاتف بوضع عدم استخدام اليدين (hands-free) فقط، مع تثبيت الهاتف في حامل، ويسمح بلمسة واحدة لتشغيل هذا الوضع.","p":"صحيح. البالغون يستخدمون الهاتف بوضع عدم استخدام اليدين (hands-free) فقط."},"ref":{"doc":"MA","page":39}},{"id":"ma-019","scope":"MA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Massachusetts, a blood alcohol level of what amount or more is a violation for a driver under 21?","o":["0.01 percent","0.02 percent","0.05 percent","0.08 percent"],"h1":"It is far below the adult limit.","h2":"In Massachusetts a driver under 21 with a blood alcohol level of 0.02 percent or more faces a license suspension, because young drivers should not drink at all.","p":"Right. Under 21, the limit is 0.02 percent."},"es":{"q":"En Massachusetts, ¿a partir de qué nivel de alcohol en la sangre comete una infracción un conductor menor de 21 años?","o":["0.01 por ciento","0.02 por ciento","0.05 por ciento","0.08 por ciento"],"h1":"Es mucho más bajo que el límite de los adultos.","h2":"En Massachusetts un conductor menor de 21 años con 0.02 por ciento de alcohol en la sangre o más recibe una suspensión de licencia, porque los jóvenes no deben tomar nada.","p":"Correcto. Para menores de 21, el límite es 0.02 por ciento."},"zh":{"q":"在 Massachusetts，21 岁以下的司机血液酒精浓度达到多少或以上就是违规？","o":["0.01%","0.02%","0.05%","0.08%"],"h1":"这远低于成年人的上限。","h2":"在 Massachusetts，21 岁以下的司机血液酒精浓度达到 0.02% 或更高，驾照会被暂停，因为年轻司机完全不应该喝酒。","p":"对。21 岁以下，上限是 0.02%。"},"vi":{"q":"Ở Massachusetts, nồng độ cồn trong máu từ mức nào trở lên là vi phạm đối với người lái xe dưới 21 tuổi?","o":["0.01 phần trăm","0.02 phần trăm","0.05 phần trăm","0.08 phần trăm"],"h1":"Mức này thấp hơn nhiều so với giới hạn cho người lớn.","h2":"Ở Massachusetts, người lái xe dưới 21 tuổi có nồng độ cồn trong máu từ 0.02 phần trăm trở lên sẽ bị treo bằng lái, vì người lái xe trẻ hoàn toàn không nên uống rượu bia.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02 phần trăm."},"tl":{"q":"Sa Massachusetts, anong blood alcohol level o higit pa ang paglabag para sa driver na wala pang 21?","o":["0.01 porsiyento","0.02 porsiyento","0.05 porsiyento","0.08 porsiyento"],"h1":"Mas mababa ito nang malayo sa limit para sa adult.","h2":"Sa Massachusetts, ang driver na wala pang 21 na may blood alcohol level na 0.02 porsiyento o higit pa ay masu-suspend ang lisensya, dahil hindi dapat uminom ng alak ang mga batang driver.","p":"Tama. Kapag wala pang 21, ang limit ay 0.02 porsiyento."},"ar":{"q":"في Massachusetts، أي نسبة كحول في الدم أو أكثر تُعتبر مخالفة للسائق الذي عمره أقل من 21 سنة؟","o":["0.01 بالمئة","0.02 بالمئة","0.05 بالمئة","0.08 بالمئة"],"h1":"هي أقل بكثير من الحد المسموح للبالغين.","h2":"في Massachusetts يواجه السائق الذي عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02 بالمئة أو أكثر إيقاف رخصته، لأن السائقين الصغار يجب ألّا يشربوا الكحول أبدًا.","p":"صحيح. تحت 21 سنة، الحد هو 0.02 بالمئة."},"ref":{"doc":"MA","page":73}},{"id":"ma-020","scope":"MA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Massachusetts, unless a sign says otherwise, what is the speed limit in a thickly settled or business district?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Some towns choose a lower limit, but the state default is a little higher.","h2":"The Massachusetts default limit in a thickly settled or business district is 30 mph, although some cities and towns lower it to 25 mph on local roads.","p":"Right. The default in thickly settled areas is 30 mph."},"es":{"q":"En Massachusetts, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad en una zona densamente poblada o comercial?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Algunos pueblos ponen un límite más bajo, pero el del estado es un poco más alto.","h2":"En Massachusetts el límite normal en una zona densamente poblada o comercial es de 30 mph, aunque algunas ciudades y pueblos lo bajan a 25 mph en calles locales.","p":"Correcto. En zonas densamente pobladas el límite normal es 30 mph."},"zh":{"q":"在 Massachusetts，如果没有标志另外说明，人口稠密区或商业区的限速是多少？","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"有些城镇选择更低的限速，但州的默认限速高一点。","h2":"Massachusetts 人口稠密区或商业区的默认限速是 30 mph，不过有些城镇在当地道路上把它降到 25 mph。","p":"对。人口稠密区的默认限速是 30 mph。"},"vi":{"q":"Ở Massachusetts, nếu không có biển báo khác, tốc độ tối đa trong khu dân cư đông đúc (thickly settled) hoặc khu thương mại là bao nhiêu?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Một số thị trấn chọn giới hạn thấp hơn, nhưng mức mặc định của tiểu bang cao hơn một chút.","h2":"Tốc độ tối đa mặc định ở Massachusetts trong khu dân cư đông đúc hoặc khu thương mại là 30 mph, mặc dù một số thành phố và thị trấn giảm xuống 25 mph trên đường địa phương.","p":"Đúng. Mức mặc định trong khu dân cư đông đúc là 30 mph."},"tl":{"q":"Sa Massachusetts, maliban kung iba ang sinasabi ng sign, ano ang speed limit sa thickly settled (masikip sa bahay) o business district?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"May mga bayan na pumipili ng mas mababang limit, pero medyo mas mataas ang default ng estado.","h2":"Ang default na limit sa Massachusetts sa thickly settled o business district ay 30 mph, bagaman may mga lungsod at bayan na ibinababa ito sa 25 mph sa mga lokal na kalsada.","p":"Tama. Ang default sa thickly settled na lugar ay 30 mph."},"ar":{"q":"في Massachusetts، إذا لم تقل لافتة غير ذلك، ما الحد الأقصى للسرعة في منطقة سكنية مكتظة (thickly settled) أو منطقة تجارية؟","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"بعض البلدات تختار حدًا أقل، لكن الحد العام للولاية أعلى قليلًا.","h2":"الحد العام للسرعة في Massachusetts في منطقة سكنية مكتظة أو منطقة تجارية هو 30 mph، مع أن بعض المدن والبلدات تخفّضه إلى 25 mph على الطرق المحلية.","p":"صحيح. الحد العام في المناطق السكنية المكتظة هو 30 mph."},"ref":{"doc":"MA","page":79}},{"id":"ma-021","scope":"MA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Massachusetts, unless a sign says otherwise, what is the speed limit in a school zone?","o":["15 mph","25 mph","30 mph","20 mph"],"h1":"It is lower than the limit in a thickly settled district.","h2":"In Massachusetts the speed limit in a school zone is 20 mph, so slow down and watch for children.","p":"Right. School zones are 20 mph."},"es":{"q":"En Massachusetts, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad en una zona escolar?","o":["15 mph","25 mph","30 mph","20 mph"],"h1":"Es más bajo que el límite de una zona densamente poblada.","h2":"En Massachusetts el límite de velocidad en una zona escolar es de 20 mph, así que baje la velocidad y esté atento a los niños.","p":"Correcto. Las zonas escolares tienen 20 mph."},"zh":{"q":"在 Massachusetts，如果没有标志另外说明，学校区域的限速是多少？","o":["15 mph","25 mph","30 mph","20 mph"],"h1":"比人口稠密区的限速低。","h2":"在 Massachusetts，学校区域的限速是 20 mph，所以要减速并注意小孩。","p":"对。学校区域是 20 mph。"},"vi":{"q":"Ở Massachusetts, nếu không có biển báo khác, tốc độ tối đa trong khu vực trường học là bao nhiêu?","o":["15 mph","25 mph","30 mph","20 mph"],"h1":"Thấp hơn giới hạn trong khu dân cư đông đúc.","h2":"Ở Massachusetts, tốc độ tối đa trong khu vực trường học là 20 mph, vì vậy hãy chạy chậm lại và chú ý trẻ em.","p":"Đúng. Khu vực trường học là 20 mph."},"tl":{"q":"Sa Massachusetts, maliban kung iba ang sinasabi ng sign, ano ang speed limit sa school zone?","o":["15 mph","25 mph","30 mph","20 mph"],"h1":"Mas mababa ito kaysa sa limit sa thickly settled district.","h2":"Sa Massachusetts, ang speed limit sa school zone ay 20 mph, kaya bagalan at bantayan ang mga bata.","p":"Tama. Ang school zone ay 20 mph."},"ar":{"q":"في Massachusetts، إذا لم تقل لافتة غير ذلك، ما الحد الأقصى للسرعة في منطقة المدرسة؟","o":["15 mph","25 mph","30 mph","20 mph"],"h1":"هو أقل من الحد في المنطقة السكنية المكتظة.","h2":"في Massachusetts الحد الأقصى للسرعة في منطقة المدرسة هو 20 mph، لذلك خفّف سرعتك وانتبه للأطفال.","p":"صحيح. مناطق المدارس 20 mph."},"ref":{"doc":"MA","page":80}},{"id":"ma-022","scope":"MA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Massachusetts, unless posted otherwise, what is the speed limit on a divided highway outside a thickly settled or business district?","o":["40 mph","45 mph","50 mph","55 mph"],"h1":"It is 10 mph more than on an undivided highway in the same kind of area.","h2":"The Massachusetts default limit on a divided highway outside a thickly settled or business district is 50 mph unless a sign shows a different limit.","p":"Right. Divided highways outside town centers default to 50 mph."},"es":{"q":"En Massachusetts, si no hay otra señal, ¿cuál es el límite de velocidad en una carretera dividida fuera de una zona densamente poblada o comercial?","o":["40 mph","45 mph","50 mph","55 mph"],"h1":"Es 10 mph más que en una carretera sin división en el mismo tipo de zona.","h2":"En Massachusetts el límite normal en una carretera dividida fuera de una zona densamente poblada o comercial es de 50 mph si no hay una señal con otro límite.","p":"Correcto. Las carreteras divididas fuera de los centros tienen 50 mph."},"zh":{"q":"在 Massachusetts，如果没有其他标示，人口稠密区或商业区以外的分隔公路限速是多少？","o":["40 mph","45 mph","50 mph","55 mph"],"h1":"比同类地区没有分隔的公路高 10 mph。","h2":"在 Massachusetts，人口稠密区或商业区以外的分隔公路，默认限速是 50 mph，除非标志标示了不同的限速。","p":"对。城镇中心以外的分隔公路默认是 50 mph。"},"vi":{"q":"Ở Massachusetts, nếu không có biển báo khác, tốc độ tối đa trên xa lộ có dải phân cách bên ngoài khu dân cư đông đúc hoặc khu thương mại là bao nhiêu?","o":["40 mph","45 mph","50 mph","55 mph"],"h1":"Cao hơn 10 mph so với xa lộ không có dải phân cách trong cùng loại khu vực.","h2":"Tốc độ tối đa mặc định ở Massachusetts trên xa lộ có dải phân cách bên ngoài khu dân cư đông đúc hoặc khu thương mại là 50 mph, trừ khi biển báo ghi giới hạn khác.","p":"Đúng. Xa lộ có dải phân cách bên ngoài trung tâm thị trấn mặc định là 50 mph."},"tl":{"q":"Sa Massachusetts, maliban kung iba ang nakapaskil, ano ang speed limit sa divided highway sa labas ng thickly settled o business district?","o":["40 mph","45 mph","50 mph","55 mph"],"h1":"Mas mataas ito nang 10 mph kaysa sa undivided highway sa parehong uri ng lugar.","h2":"Ang default na limit sa Massachusetts sa divided highway sa labas ng thickly settled o business district ay 50 mph, maliban kung may sign na nagpapakita ng ibang limit.","p":"Tama. Ang divided highway sa labas ng sentro ng bayan ay default na 50 mph."},"ar":{"q":"في Massachusetts، إذا لم تُنشر لافتة غير ذلك، ما الحد الأقصى للسرعة على طريق سريع مقسوم خارج منطقة سكنية مكتظة أو منطقة تجارية؟","o":["40 mph","45 mph","50 mph","55 mph"],"h1":"هو أعلى بـ 10 mph من الطريق السريع غير المقسوم في نفس نوع المنطقة.","h2":"الحد العام للسرعة في Massachusetts على طريق سريع مقسوم خارج منطقة سكنية مكتظة أو منطقة تجارية هو 50 mph، إلا إذا أظهرت لافتة حدًا مختلفًا.","p":"صحيح. الطرق السريعة المقسومة خارج وسط البلدات حدها العام 50 mph."},"ref":{"doc":"MA","page":79}},{"id":"ma-023","scope":"MA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Massachusetts, unless posted otherwise, what is the speed limit on an undivided highway outside a thickly settled or business district?","o":["40 mph","45 mph","50 mph","35 mph"],"h1":"It is 10 mph less than on a divided highway in the same kind of area.","h2":"The Massachusetts default limit on an undivided highway outside a thickly settled or business district is 40 mph, because there is nothing between you and oncoming traffic.","p":"Right. Undivided highways outside town centers default to 40 mph."},"es":{"q":"En Massachusetts, si no hay otra señal, ¿cuál es el límite de velocidad en una carretera sin división fuera de una zona densamente poblada o comercial?","o":["40 mph","45 mph","50 mph","35 mph"],"h1":"Es 10 mph menos que en una carretera dividida en el mismo tipo de zona.","h2":"En Massachusetts el límite normal en una carretera sin división fuera de una zona densamente poblada o comercial es de 40 mph, porque no hay nada entre usted y el tráfico contrario.","p":"Correcto. Las carreteras sin división fuera de los centros tienen 40 mph."},"zh":{"q":"在 Massachusetts，如果没有其他标示，人口稠密区或商业区以外没有分隔的公路限速是多少？","o":["40 mph","45 mph","50 mph","35 mph"],"h1":"比同类地区的分隔公路低 10 mph。","h2":"在 Massachusetts，人口稠密区或商业区以外没有分隔的公路，默认限速是 40 mph，因为你和对面来的车之间没有任何东西隔开。","p":"对。城镇中心以外没有分隔的公路默认是 40 mph。"},"vi":{"q":"Ở Massachusetts, nếu không có biển báo khác, tốc độ tối đa trên xa lộ không có dải phân cách bên ngoài khu dân cư đông đúc hoặc khu thương mại là bao nhiêu?","o":["40 mph","45 mph","50 mph","35 mph"],"h1":"Thấp hơn 10 mph so với xa lộ có dải phân cách trong cùng loại khu vực.","h2":"Tốc độ tối đa mặc định ở Massachusetts trên xa lộ không có dải phân cách bên ngoài khu dân cư đông đúc hoặc khu thương mại là 40 mph, vì không có gì ngăn giữa bạn và xe chạy ngược chiều.","p":"Đúng. Xa lộ không có dải phân cách bên ngoài trung tâm thị trấn mặc định là 40 mph."},"tl":{"q":"Sa Massachusetts, maliban kung iba ang nakapaskil, ano ang speed limit sa undivided highway sa labas ng thickly settled o business district?","o":["40 mph","45 mph","50 mph","35 mph"],"h1":"Mas mababa ito nang 10 mph kaysa sa divided highway sa parehong uri ng lugar.","h2":"Ang default na limit sa Massachusetts sa undivided highway sa labas ng thickly settled o business district ay 40 mph, dahil walang nakapagitan sa iyo at sa paparating na trapiko.","p":"Tama. Ang undivided highway sa labas ng sentro ng bayan ay default na 40 mph."},"ar":{"q":"في Massachusetts، إذا لم تُنشر لافتة غير ذلك، ما الحد الأقصى للسرعة على طريق سريع غير مقسوم خارج منطقة سكنية مكتظة أو منطقة تجارية؟","o":["40 mph","45 mph","50 mph","35 mph"],"h1":"هو أقل بـ 10 mph من الطريق السريع المقسوم في نفس نوع المنطقة.","h2":"الحد العام للسرعة في Massachusetts على طريق سريع غير مقسوم خارج منطقة سكنية مكتظة أو منطقة تجارية هو 40 mph، لأنه لا يوجد شيء بينك وبين السيارات القادمة من الاتجاه المعاكس.","p":"صحيح. الطرق السريعة غير المقسومة خارج وسط البلدات حدها العام 40 mph."},"ref":{"doc":"MA","page":79}},{"id":"ma-024","scope":"MA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Massachusetts, when you enter a rotary, who has the right-of-way?","o":["You, because you are entering","Vehicles already in the rotary","The larger vehicle","The vehicle on your left only if it honks"],"h1":"Think about who is already moving around the circle.","h2":"Massachusetts law says a driver entering a rotary must yield to vehicles already in the rotary, so traffic inside keeps moving safely.","p":"Right. Yield to vehicles already in the rotary."},"es":{"q":"En Massachusetts, al entrar a una rotonda (rotary), ¿quién tiene el derecho de paso?","o":["Usted, porque está entrando","Los vehículos que ya están en la rotonda","El vehículo más grande","El de su izquierda solo si toca la bocina"],"h1":"Piense en quién ya va dando la vuelta.","h2":"La ley de Massachusetts dice que quien entra a una rotonda debe ceder el paso a los vehículos que ya están dentro, para que el tráfico de adentro siga con seguridad.","p":"Correcto. Ceda el paso a los vehículos que ya están en la rotonda."},"zh":{"q":"在 Massachusetts，你进入环岛（rotary）时，谁有优先通行权？","o":["你，因为你正在进入","已经在环岛里的车辆","比较大的车辆","左边的车，但只有它按喇叭时"],"h1":"想一想谁已经在环岛里绕着走。","h2":"Massachusetts 法律规定，进入环岛的司机必须让已经在环岛里的车辆先走，这样里面的车可以安全地继续走。","p":"对。让已经在环岛里的车辆先走。"},"vi":{"q":"Ở Massachusetts, khi bạn chạy vào vòng xoay (rotary), ai được quyền ưu tiên?","o":["Bạn, vì bạn đang chạy vào","Các xe đã ở trong vòng xoay","Xe lớn hơn","Xe bên trái bạn, chỉ khi nó bấm còi"],"h1":"Hãy nghĩ xem ai đang chạy vòng quanh rồi.","h2":"Luật Massachusetts nói rằng người lái xe chạy vào vòng xoay phải nhường đường cho các xe đã ở trong vòng xoay, để xe bên trong tiếp tục chạy an toàn.","p":"Đúng. Nhường đường cho các xe đã ở trong vòng xoay."},"tl":{"q":"Sa Massachusetts, kapag pumapasok ka sa rotary, sino ang may right-of-way?","o":["Ikaw, dahil pumapasok ka","Ang mga sasakyang nasa loob na ng rotary","Ang mas malaking sasakyan","Ang sasakyan sa kaliwa mo, kung bumusina lang ito"],"h1":"Isipin kung sino na ang umiikot sa bilog.","h2":"Sinasabi ng batas ng Massachusetts na ang driver na pumapasok sa rotary ay dapat magbigay-daan sa mga sasakyang nasa loob na ng rotary, para ligtas na tuloy-tuloy ang trapiko sa loob.","p":"Tama. Magbigay-daan sa mga sasakyang nasa loob na ng rotary."},"ar":{"q":"في Massachusetts، عندما تدخل دوّارًا (rotary)، من له حق الأولوية؟","o":["أنت، لأنك تدخل","السيارات الموجودة داخل الدوّار","السيارة الأكبر","السيارة على يسارك، فقط إذا أطلقت البوق"],"h1":"فكّر في من يدور حول الدائرة بالفعل.","h2":"يقول قانون Massachusetts إن السائق الذي يدخل الدوّار يجب أن يعطي الأولوية للسيارات الموجودة داخل الدوّار، حتى تستمر حركة المرور في الداخل بأمان.","p":"صحيح. أعطِ الأولوية للسيارات الموجودة داخل الدوّار."},"ref":{"doc":"MA","page":101}},{"id":"ma-025","scope":"MA","cat":"signals","sign":null,"c":3,"en":{"q":"In Massachusetts, after a full stop at a red light, which turn is allowed if no sign forbids it and you yield?","o":["A left turn onto a two-way street","A U-turn","A left turn from any street","A right turn"],"h1":"Most states allow this same turn on red.","h2":"In Massachusetts you may turn right on a red light after stopping and yielding to people and traffic, unless a sign says no turn on red.","p":"Right. A right turn on red is allowed after a stop, unless a sign forbids it."},"es":{"q":"En Massachusetts, después de parar por completo en un semáforo en rojo, ¿qué giro se permite si ninguna señal lo prohíbe y usted cede el paso?","o":["Girar a la izquierda a una calle de doble sentido","Dar vuelta en U","Girar a la izquierda desde cualquier calle","Girar a la derecha"],"h1":"Casi todos los estados permiten este mismo giro en rojo.","h2":"En Massachusetts usted puede girar a la derecha con la luz roja después de parar y ceder el paso a las personas y al tráfico, a menos que una señal lo prohíba.","p":"Correcto. Se permite girar a la derecha en rojo después de parar, si no hay señal que lo prohíba."},"zh":{"q":"在 Massachusetts，在红灯前完全停下以后，如果没有标志禁止并且你让行，可以怎样转弯？","o":["左转进入双向街道","掉头","从任何街道左转","右转"],"h1":"大多数州都允许红灯时这样转弯。","h2":"在 Massachusetts，你在红灯前停车并让行人和车辆先走后，可以右转，除非有标志写着红灯不能转弯。","p":"对。停车后可以红灯右转，除非有标志禁止。"},"vi":{"q":"Ở Massachusetts, sau khi dừng hẳn ở đèn đỏ, bạn được rẽ hướng nào nếu không có biển báo cấm và bạn nhường đường?","o":["Rẽ trái vào đường hai chiều","Quay đầu xe (U-turn)","Rẽ trái từ bất kỳ đường nào","Rẽ phải"],"h1":"Hầu hết các tiểu bang cho phép rẽ hướng này khi đèn đỏ.","h2":"Ở Massachusetts, bạn được rẽ phải khi đèn đỏ sau khi dừng lại và nhường đường cho người đi bộ và xe cộ, trừ khi có biển báo cấm rẽ khi đèn đỏ.","p":"Đúng. Được rẽ phải khi đèn đỏ sau khi dừng lại, trừ khi có biển báo cấm."},"tl":{"q":"Sa Massachusetts, pagkatapos ng full stop sa red light, anong liko ang puwede kung walang sign na nagbabawal at nagbigay-daan ka?","o":["Kaliwang liko papunta sa two-way street","U-turn","Kaliwang liko mula sa kahit anong kalye","Kanang liko"],"h1":"Pinapayagan ng karamihan ng estado ang ganitong liko sa red.","h2":"Sa Massachusetts, puwede kang kumanan sa red light pagkatapos huminto at magbigay-daan sa mga tao at trapiko, maliban kung may sign na nagsasabing bawal lumiko sa red.","p":"Tama. Puwede ang kanang liko sa red pagkatapos huminto, maliban kung may sign na nagbabawal."},"ar":{"q":"في Massachusetts، بعد توقف كامل عند الإشارة الحمراء، أي انعطاف مسموح إذا لم تمنعه لافتة وأعطيت الأولوية؟","o":["انعطاف إلى اليسار نحو شارع باتجاهين","الدوران للخلف (U-turn)","انعطاف إلى اليسار من أي شارع","انعطاف إلى اليمين"],"h1":"معظم الولايات تسمح بنفس هذا الانعطاف عند الإشارة الحمراء.","h2":"في Massachusetts يمكنك الانعطاف إلى اليمين عند الإشارة الحمراء بعد التوقف وإعطاء الأولوية للمشاة والسيارات، إلا إذا قالت لافتة إن الانعطاف عند الإشارة الحمراء ممنوع.","p":"صحيح. الانعطاف إلى اليمين عند الإشارة الحمراء مسموح بعد التوقف، إلا إذا منعته لافتة."},"ref":{"doc":"MA","page":81}},{"id":"ma-026","scope":"MA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Massachusetts, when must your headlights be on?","o":["Only on highways","Only after 10 p.m.","Whenever your wipers are needed","Only in tunnels"],"h1":"Think about rain and snow.","h2":"Massachusetts law says your headlights must be on whenever you need your windshield wipers, and daytime running lights do not count.","p":"Right. Wipers on means headlights on."},"es":{"q":"En Massachusetts, ¿cuándo debe tener las luces delanteras encendidas?","o":["Solo en las autopistas","Solo después de las 10 p.m.","Siempre que necesite los limpiaparabrisas","Solo en los túneles"],"h1":"Piense en la lluvia y la nieve.","h2":"La ley de Massachusetts dice que debe encender las luces delanteras siempre que necesite los limpiaparabrisas, y las luces de circulación diurna no cuentan.","p":"Correcto. Si usa los limpiaparabrisas, encienda las luces."},"zh":{"q":"在 Massachusetts，什么时候必须打开车头灯？","o":["只在高速公路上","只在晚上 10 点以后","每当需要用雨刷的时候","只在隧道里"],"h1":"想一想下雨和下雪。","h2":"Massachusetts 法律规定，每当你需要用挡风玻璃雨刷时，就必须打开车头灯，日间行车灯不算。","p":"对。开雨刷就要开车头灯。"},"vi":{"q":"Ở Massachusetts, khi nào bạn phải bật đèn pha?","o":["Chỉ trên xa lộ","Chỉ sau 10 giờ tối","Bất cứ khi nào cần dùng cần gạt nước","Chỉ trong đường hầm"],"h1":"Hãy nghĩ đến mưa và tuyết.","h2":"Luật Massachusetts nói rằng bạn phải bật đèn pha bất cứ khi nào cần dùng cần gạt nước kính chắn gió, và đèn chạy ban ngày không được tính.","p":"Đúng. Bật cần gạt nước thì phải bật đèn pha."},"tl":{"q":"Sa Massachusetts, kailan dapat nakabukas ang iyong headlights?","o":["Sa highway lang","Pagkalipas lang ng 10 p.m.","Tuwing kailangan mo ang wipers","Sa tunnel lang"],"h1":"Isipin ang ulan at niyebe.","h2":"Sinasabi ng batas ng Massachusetts na dapat nakabukas ang headlights mo tuwing kailangan mo ang windshield wipers, at hindi binibilang ang daytime running lights.","p":"Tama. Kapag bukas ang wipers, bukas din ang headlights."},"ar":{"q":"في Massachusetts، متى يجب أن تكون المصابيح الأمامية مضاءة؟","o":["على الطرق السريعة فقط","بعد 10 مساءً فقط","كلما احتجت إلى مسّاحات الزجاج","في الأنفاق فقط"],"h1":"فكّر في المطر والثلج.","h2":"يقول قانون Massachusetts إن المصابيح الأمامية يجب أن تكون مضاءة كلما احتجت إلى مسّاحات الزجاج الأمامي، وأضواء النهار لا تُحسب.","p":"صحيح. المسّاحات تعمل يعني المصابيح الأمامية مضاءة."},"ref":{"doc":"MA","page":45}},{"id":"ma-027","scope":"MA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Massachusetts, when may you drive past a school bus that is stopped with red lights flashing?","o":["When you are going the opposite way on a highway divided by a barrier","When you are going the opposite way on any two-lane road","When no children can be seen","When you honk first"],"h1":"There is only one exception, and it needs something between you and the bus.","h2":"In Massachusetts drivers from both directions must stop for a school bus with flashing red lights, and the only exception is opposite traffic on a highway divided by a physical barrier.","p":"Right. Only a divided highway with a barrier lets opposite traffic continue."},"es":{"q":"En Massachusetts, ¿cuándo puede pasar junto a un autobús escolar detenido con luces rojas intermitentes?","o":["Cuando va en sentido contrario en una carretera dividida por una barrera","Cuando va en sentido contrario en cualquier camino de dos carriles","Cuando no se ve a ningún niño","Cuando toca la bocina antes"],"h1":"Hay una sola excepción, y necesita algo entre usted y el autobús.","h2":"En Massachusetts los conductores de ambas direcciones deben parar ante un autobús escolar con luces rojas intermitentes, y la única excepción es el tráfico contrario en una carretera dividida por una barrera física.","p":"Correcto. Solo en una carretera dividida por una barrera sigue el tráfico contrario."},"zh":{"q":"在 Massachusetts，什么时候你可以开过一辆闪着红灯停着的校车？","o":["当你在有隔离墩的分隔公路上往相反方向开时","当你在任何双车道道路上往相反方向开时","当看不到小孩时","当你先按了喇叭时"],"h1":"只有一个例外，而且你和校车之间要有东西隔开。","h2":"在 Massachusetts，两个方向的司机都必须为闪着红灯的校车停车，唯一的例外是在有实体隔离墩的分隔公路上往相反方向开的车。","p":"对。只有在有隔离墩的分隔公路上，对面的车才可以继续开。"},"vi":{"q":"Ở Massachusetts, khi nào bạn được chạy qua một xe buýt trường học đang dừng với đèn đỏ nhấp nháy?","o":["Khi bạn chạy ngược chiều trên xa lộ có rào chắn ngăn cách","Khi bạn chạy ngược chiều trên bất kỳ đường hai làn nào","Khi không thấy trẻ em nào","Khi bạn bấm còi trước"],"h1":"Chỉ có một trường hợp ngoại lệ, và cần có thứ gì đó ngăn giữa bạn và xe buýt.","h2":"Ở Massachusetts, xe từ cả hai hướng phải dừng lại khi xe buýt trường học có đèn đỏ nhấp nháy, và ngoại lệ duy nhất là xe chạy ngược chiều trên xa lộ có rào chắn ngăn cách.","p":"Đúng. Chỉ xa lộ có rào chắn ngăn cách mới cho xe ngược chiều tiếp tục chạy."},"tl":{"q":"Sa Massachusetts, kailan ka puwedeng dumaan sa school bus na nakahinto na may kumikislap na pulang ilaw?","o":["Kapag pasalungat ka sa highway na hinahati ng barrier","Kapag pasalungat ka sa kahit anong two-lane na kalsada","Kapag walang batang nakikita","Kapag bumusina ka muna"],"h1":"Iisa lang ang exception, at kailangan nito ng nakapagitan sa iyo at sa bus.","h2":"Sa Massachusetts, dapat huminto ang mga driver mula sa dalawang direksyon para sa school bus na may kumikislap na pulang ilaw, at ang tanging exception ay ang pasalungat na trapiko sa highway na hinahati ng pisikal na barrier.","p":"Tama. Ang divided highway lang na may barrier ang nagpapatuloy sa pasalungat na trapiko."},"ar":{"q":"في Massachusetts، متى يجوز لك أن تمر بجانب حافلة مدرسية متوقفة وأضواؤها الحمراء تومض؟","o":["عندما تسير في الاتجاه المعاكس على طريق سريع يفصله حاجز","عندما تسير في الاتجاه المعاكس على أي طريق بمسارين","عندما لا ترى أي أطفال","عندما تطلق البوق أولًا"],"h1":"يوجد استثناء واحد فقط، ويحتاج إلى شيء يفصل بينك وبين الحافلة.","h2":"في Massachusetts يجب على السائقين من الاتجاهين التوقف أمام حافلة مدرسية أضواؤها الحمراء تومض، والاستثناء الوحيد هو السيارات في الاتجاه المعاكس على طريق سريع يفصله حاجز مادي.","p":"صحيح. فقط الطريق السريع الذي يفصله حاجز يسمح للسيارات في الاتجاه المعاكس بالاستمرار."},"ref":{"doc":"MA","page":105}},{"id":"ma-028","scope":"MA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Massachusetts, how close may you drive behind a school bus?","o":["No closer than 25 feet","No closer than 50 feet","No closer than 200 feet","No closer than 100 feet"],"h1":"It is about the length of six or seven cars.","h2":"Massachusetts law says you may not drive within 100 feet behind a school bus, so you have room to stop when it stops for children.","p":"Right. Stay at least 100 feet behind a school bus."},"es":{"q":"En Massachusetts, ¿qué tan cerca puede manejar detrás de un autobús escolar?","o":["No más cerca de 25 pies","No más cerca de 50 pies","No más cerca de 200 pies","No más cerca de 100 pies"],"h1":"Es más o menos el largo de seis o siete carros.","h2":"La ley de Massachusetts dice que usted no puede manejar a menos de 100 pies detrás de un autobús escolar, para tener espacio para parar cuando se detenga por los niños.","p":"Correcto. Manténgase por lo menos a 100 pies detrás de un autobús escolar."},"zh":{"q":"在 Massachusetts，你在校车后面开车，最近可以离多近？","o":["不能少于 25 英尺","不能少于 50 英尺","不能少于 200 英尺","不能少于 100 英尺"],"h1":"大约是六、七辆车的长度。","h2":"Massachusetts 法律规定，你不能在校车后面 100 英尺以内开车，这样校车为小孩停车时，你有空间停下来。","p":"对。在校车后面至少保持 100 英尺。"},"vi":{"q":"Ở Massachusetts, bạn được chạy gần phía sau xe buýt trường học đến mức nào?","o":["Không gần hơn 25 feet","Không gần hơn 50 feet","Không gần hơn 200 feet","Không gần hơn 100 feet"],"h1":"Khoảng bằng chiều dài của sáu hoặc bảy chiếc xe hơi.","h2":"Luật Massachusetts nói rằng bạn không được chạy trong vòng 100 feet phía sau xe buýt trường học, để bạn có đủ chỗ dừng lại khi xe buýt dừng đón trả trẻ em.","p":"Đúng. Giữ khoảng cách ít nhất 100 feet phía sau xe buýt trường học."},"tl":{"q":"Sa Massachusetts, gaano kalapit ka puwedeng magmaneho sa likod ng school bus?","o":["Hindi lalapit sa 25 feet","Hindi lalapit sa 50 feet","Hindi lalapit sa 200 feet","Hindi lalapit sa 100 feet"],"h1":"Mga kasinghaba ito ng anim o pitong kotse.","h2":"Sinasabi ng batas ng Massachusetts na hindi ka puwedeng magmaneho sa loob ng 100 feet sa likod ng school bus, para may lugar kang huminto kapag huminto ito para sa mga bata.","p":"Tama. Manatili nang hindi bababa sa 100 feet sa likod ng school bus."},"ar":{"q":"في Massachusetts، إلى أي مدى يجوز لك أن تقترب أثناء القيادة خلف حافلة مدرسية؟","o":["ليس أقرب من 25 قدمًا (feet)","ليس أقرب من 50 قدمًا (feet)","ليس أقرب من 200 قدم (feet)","ليس أقرب من 100 قدم (feet)"],"h1":"المسافة تقارب طول ست أو سبع سيارات.","h2":"يقول قانون Massachusetts إنه لا يجوز لك أن تقود على مسافة أقل من 100 قدم (feet) خلف حافلة مدرسية، حتى يكون لديك مكان للتوقف عندما تتوقف للأطفال.","p":"صحيح. ابقَ على بعد 100 قدم (feet) على الأقل خلف الحافلة المدرسية."},"ref":{"doc":"MA","page":null}},{"id":"ma-029","scope":"MA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Massachusetts, what does the Move Over law ask you to do near a stopped emergency vehicle with flashing lights?","o":["Stop in your lane until it leaves","Move to a lane not next to it, or slow down","Flash your lights and keep your speed","Drive on the shoulder past it"],"h1":"You give the vehicle more room, or less speed.","h2":"The Massachusetts Move Over law asks you to change to a lane that is not next to a stopped emergency, maintenance, or tow vehicle, or to slow down if you cannot change lanes safely.","p":"Right. Move over a lane, or slow down if you cannot."},"es":{"q":"En Massachusetts, ¿qué le pide la ley Move Over cerca de un vehículo de emergencia detenido con luces intermitentes?","o":["Parar en su carril hasta que se vaya","Pasar a un carril que no esté al lado, o bajar la velocidad","Hacer cambio de luces y seguir igual","Pasar por el acotamiento"],"h1":"Usted le da más espacio al vehículo, o pasa más despacio.","h2":"La ley Move Over de Massachusetts le pide pasar a un carril que no esté junto a un vehículo de emergencia, de mantenimiento o grúa detenido, o bajar la velocidad si no puede cambiarse de carril con seguridad.","p":"Correcto. Cámbiese de carril, o baje la velocidad si no puede."},"zh":{"q":"在 Massachusetts，在闪着灯停着的急救车辆附近，Move Over 法要你做什么？","o":["在你的车道停下，直到它离开","换到不紧挨着它的车道，或者减速","闪车灯并保持速度","从路肩开过去"],"h1":"你给这辆车更多空间，或者开得更慢。","h2":"Massachusetts 的 Move Over 法要求你换到不紧挨着停着的急救车、维修车或拖车的车道，如果不能安全换道，就要减速。","p":"对。换一条车道让开，如果不能就减速。"},"vi":{"q":"Ở Massachusetts, luật Nhường Làn (Move Over law) yêu cầu bạn làm gì khi đến gần một xe khẩn cấp đang dừng với đèn nhấp nháy?","o":["Dừng lại trong làn của bạn cho đến khi xe đó rời đi","Chuyển sang làn không sát bên xe đó, hoặc chạy chậm lại","Nháy đèn và giữ nguyên tốc độ","Chạy trên lề đường để vượt qua xe đó"],"h1":"Bạn cho xe đó thêm khoảng trống, hoặc giảm tốc độ.","h2":"Luật Move Over của Massachusetts yêu cầu bạn chuyển sang làn không sát bên xe khẩn cấp, xe bảo trì hoặc xe kéo đang dừng, hoặc chạy chậm lại nếu bạn không thể đổi làn an toàn.","p":"Đúng. Chuyển sang một làn khác, hoặc chạy chậm lại nếu không thể."},"tl":{"q":"Sa Massachusetts, ano ang ipinagagawa sa iyo ng Move Over law malapit sa nakahintong emergency vehicle na may kumikislap na ilaw?","o":["Huminto sa lane mo hanggang umalis ito","Lumipat sa lane na hindi katabi nito, o bumagal","I-flash ang ilaw mo at panatilihin ang bilis","Magmaneho sa shoulder para lampasan ito"],"h1":"Binibigyan mo ang sasakyan ng mas maraming espasyo, o binabawasan mo ang bilis.","h2":"Ipinagagawa ng Move Over law ng Massachusetts na lumipat ka sa lane na hindi katabi ng nakahintong emergency, maintenance, o tow vehicle, o bumagal kung hindi ka ligtas na makalipat ng lane.","p":"Tama. Lumipat ng isang lane, o bumagal kung hindi puwede."},"ar":{"q":"في Massachusetts، ماذا يطلب منك قانون الابتعاد (Move Over law) قرب سيارة طوارئ متوقفة وأضواؤها تومض؟","o":["أن تتوقف في مسارك حتى تغادر","أن تنتقل إلى مسار غير مجاور لها، أو تخفّف سرعتك","أن تومض بأضوائك وتحافظ على سرعتك","أن تقود على كتف الطريق لتتجاوزها"],"h1":"تعطي السيارة مساحة أكبر، أو تخفّف سرعتك.","h2":"يطلب منك قانون Move Over في Massachusetts أن تنتقل إلى مسار غير مجاور لسيارة طوارئ أو صيانة أو سحب متوقفة، أو أن تخفّف سرعتك إذا لم تستطع تغيير المسار بأمان.","p":"صحيح. انتقل مسارًا واحدًا، أو خفّف سرعتك إذا لم تستطع."},"ref":{"doc":"MA","page":104}},{"id":"ma-030","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, which coverage is one of the required parts of every auto insurance policy?","o":["Collision coverage","Comprehensive coverage","Personal injury protection (PIP)","Rental car coverage"],"h1":"Massachusetts is a no-fault state for this coverage.","h2":"Personal injury protection (PIP) is required on every Massachusetts auto policy and pays certain injury costs no matter who caused the crash, while collision and comprehensive are optional.","p":"Right. PIP is required in Massachusetts."},"es":{"q":"En Massachusetts, ¿qué cobertura es una de las partes obligatorias de toda póliza de seguro de auto?","o":["Cobertura de choque (collision)","Cobertura amplia (comprehensive)","Protección por lesiones personales (PIP)","Cobertura de auto de alquiler"],"h1":"Massachusetts es un estado “sin culpa” para esta cobertura.","h2":"La protección por lesiones personales (PIP) es obligatoria en toda póliza de auto de Massachusetts y paga ciertos gastos por lesiones sin importar quién causó el choque, mientras que la de choque y la amplia son opcionales.","p":"Correcto. La PIP es obligatoria en Massachusetts."},"zh":{"q":"在 Massachusetts，哪种保险是每份汽车保险单必须有的部分之一？","o":["碰撞险（collision）","综合险（comprehensive）","人身伤害保障（PIP）","租车险"],"h1":"在这种保险上，Massachusetts 是不论过错（no-fault）的州。","h2":"在 Massachusetts，每份汽车保险单都必须有人身伤害保障（PIP），不管是谁造成车祸，它都会支付某些受伤费用；碰撞险和综合险则是可选的。","p":"对。在 Massachusetts，PIP 是必须有的。"},"vi":{"q":"Ở Massachusetts, loại bảo hiểm nào là một phần bắt buộc của mọi hợp đồng bảo hiểm xe?","o":["Bảo hiểm va chạm (collision)","Bảo hiểm toàn diện (comprehensive)","Bảo hiểm thương tích cá nhân (personal injury protection, PIP)","Bảo hiểm xe thuê"],"h1":"Massachusetts là tiểu bang không xét lỗi (no-fault) đối với loại bảo hiểm này.","h2":"Bảo hiểm thương tích cá nhân (PIP) là bắt buộc trong mọi hợp đồng bảo hiểm xe ở Massachusetts và trả một số chi phí thương tích bất kể ai gây ra tai nạn, còn bảo hiểm va chạm và toàn diện thì không bắt buộc.","p":"Đúng. PIP là bắt buộc ở Massachusetts."},"tl":{"q":"Sa Massachusetts, anong coverage ang isa sa mga kailangang bahagi ng bawat auto insurance policy?","o":["Collision coverage","Comprehensive coverage","Personal injury protection (PIP)","Rental car coverage"],"h1":"Ang Massachusetts ay no-fault state para sa coverage na ito.","h2":"Ang personal injury protection (PIP) ay kailangan sa bawat auto policy sa Massachusetts at nagbabayad ng ilang gastos sa pinsala kahit sino ang nagsanhi ng banggaan, habang optional ang collision at comprehensive.","p":"Tama. Kailangan ang PIP sa Massachusetts."},"ar":{"q":"في Massachusetts، أي تغطية هي جزء إلزامي من كل وثيقة تأمين سيارة؟","o":["تغطية الاصطدام (collision)","التغطية الشاملة (comprehensive)","تغطية الحماية من الإصابات الشخصية (personal injury protection, PIP)","تغطية السيارة المستأجرة"],"h1":"Massachusetts ولاية بدون تحديد خطأ (no-fault) لهذه التغطية.","h2":"تغطية الحماية من الإصابات الشخصية (PIP) إلزامية في كل وثيقة تأمين سيارة في Massachusetts، وتدفع بعض تكاليف الإصابات بغض النظر عمّن تسبّب في الحادث، أما تغطية الاصطدام والتغطية الشاملة فهي اختيارية.","p":"صحيح. PIP إلزامية في Massachusetts."},"ref":{"doc":"MA","page":null}},{"id":"ma-031","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, what is the fewest surchargeable events within 2 years that means you must take a Driver Retraining course?","o":["3 events","2 events","5 events","7 events"],"h1":"It is a small number, more than two.","h2":"In Massachusetts, 3 surchargeable events within 2 years, such as at-fault crashes or traffic violations, mean you must finish a Driver Retraining course within 90 days or lose your license.","p":"Right. Three surchargeable events in 2 years mean a retraining course, or a suspension."},"es":{"q":"En Massachusetts, ¿cuál es el menor número de incidentes con recargo en 2 años que lo obliga a tomar un curso de reentrenamiento para conductores?","o":["3 incidentes","2 incidentes","5 incidentes","7 incidentes"],"h1":"Es un número pequeño, mayor que dos.","h2":"En Massachusetts, 3 incidentes con recargo en 2 años, como choques con culpa o infracciones de tránsito, lo obligan a terminar un curso de reentrenamiento para conductores en 90 días o perderá su licencia.","p":"Correcto. Tres incidentes con recargo en 2 años significan un curso de reentrenamiento, o una suspensión."},"zh":{"q":"在 Massachusetts，2 年内最少有多少次会加收保费的事件（surchargeable events），你就必须上 Driver Retraining 课程？","o":["3 次","2 次","5 次","7 次"],"h1":"这是一个小数字，比两多。","h2":"在 Massachusetts，2 年内有 3 次会加收保费的事件，例如自己有责任的车祸或交通违规，你就必须在 90 天内完成 Driver Retraining 课程，否则会失去驾照。","p":"对。2 年内有三次加收保费的事件，就要上再培训课程，否则驾照会被暂停。"},"vi":{"q":"Ở Massachusetts, số lần vi phạm bị tính phụ phí (surchargeable events) ít nhất trong vòng 2 năm là bao nhiêu thì bạn phải học khóa Đào tạo lại người lái xe (Driver Retraining)?","o":["3 lần","2 lần","5 lần","7 lần"],"h1":"Đó là một số nhỏ, nhiều hơn hai.","h2":"Ở Massachusetts, 3 lần vi phạm bị tính phụ phí trong vòng 2 năm, như tai nạn do lỗi của bạn hoặc vi phạm luật giao thông, nghĩa là bạn phải học xong khóa Driver Retraining trong vòng 90 ngày, nếu không sẽ mất bằng lái.","p":"Đúng. Ba lần vi phạm bị tính phụ phí trong 2 năm nghĩa là phải học khóa đào tạo lại, nếu không sẽ bị treo bằng lái."},"tl":{"q":"Sa Massachusetts, ano ang pinakakaunting surchargeable events sa loob ng 2 taon na nangangahulugang dapat kang kumuha ng Driver Retraining course?","o":["3 events","2 events","5 events","7 events"],"h1":"Maliit na bilang ito, higit sa dalawa.","h2":"Sa Massachusetts, ang 3 surchargeable events sa loob ng 2 taon, gaya ng banggaang ikaw ang may sala o mga traffic violation, ay nangangahulugang dapat mong tapusin ang Driver Retraining course sa loob ng 90 araw o mawawala ang lisensya mo.","p":"Tama. Ang tatlong surchargeable events sa 2 taon ay nangangahulugang retraining course, o suspensyon."},"ar":{"q":"في Massachusetts، ما أقل عدد من المخالفات التي تستوجب رسومًا إضافية (surchargeable events) خلال سنتين يعني أنك يجب أن تأخذ دورة إعادة تدريب السائق (Driver Retraining)؟","o":["3 مخالفات","مخالفتان (2)","5 مخالفات","7 مخالفات"],"h1":"عدد صغير، أكثر من اثنين.","h2":"في Massachusetts، 3 مخالفات تستوجب رسومًا إضافية خلال سنتين، مثل حوادث تكون أنت المخطئ فيها أو مخالفات مرورية، تعني أنك يجب أن تُنهي دورة Driver Retraining خلال 90 يومًا وإلا تفقد رخصتك.","p":"صحيح. ثلاث مخالفات تستوجب رسومًا إضافية خلال سنتين تعني دورة إعادة تدريب، أو إيقاف الرخصة."},"ref":{"doc":"MA","page":59}},{"id":"ma-032","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, what is the longest time a driver's license is valid before it must be renewed?","o":["Two years","Five years","Eight years","Ten years"],"h1":"It is more than a few years, but less than ten.","h2":"In Massachusetts, a driver's license is valid for up to five years and usually expires on your birthday.","p":"Right. A Massachusetts license lasts up to five years."},"es":{"q":"En Massachusetts, ¿cuánto tiempo como máximo es válida una licencia de conducir antes de renovarla?","o":["Dos años","Cinco años","Ocho años","Diez años"],"h1":"Son más de unos pocos años, pero menos de diez.","h2":"En Massachusetts, una licencia de conducir es válida hasta por cinco años y por lo general vence el día de su cumpleaños.","p":"Correcto. Una licencia de Massachusetts dura hasta cinco años."},"ref":{"doc":"MA","page":7}},{"id":"ma-033","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, what vision is needed in your better eye, with glasses if you wear them, for a full Class D license?","o":["20/100","20/70","20/60","20/40"],"h1":"It is the best of these four numbers.","h2":"In Massachusetts, a full Class D license needs at least 20/40 vision in your better eye, with glasses or contacts if you use them.","p":"Right. You need at least 20/40 in your better eye."},"es":{"q":"En Massachusetts, ¿qué visión necesita en su mejor ojo, con lentes si los usa, para una licencia Clase D completa?","o":["20/100","20/70","20/60","20/40"],"h1":"Es el mejor de estos cuatro números.","h2":"En Massachusetts, una licencia Clase D completa requiere al menos una visión de 20/40 en su mejor ojo, con lentes o lentes de contacto si los usa.","p":"Correcto. Necesita al menos 20/40 en su mejor ojo."},"ref":{"doc":"MA","page":5}},{"id":"ma-034","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, if you fail the road test, how long must you wait before you can take it again?","o":["At least 14 days","At least 3 days","At least 90 days","At least 6 months"],"h1":"It is about two weeks.","h2":"In Massachusetts, if you fail the road test or miss your appointment, you must wait at least 14 days before you test again.","p":"Right. You wait at least 14 days to retake the road test."},"es":{"q":"En Massachusetts, si no aprueba el examen de manejo, ¿cuánto tiempo debe esperar para tomarlo otra vez?","o":["Al menos 14 días","Al menos 3 días","Al menos 90 días","Al menos 6 meses"],"h1":"Son unas dos semanas.","h2":"En Massachusetts, si no aprueba el examen de manejo o no se presenta a su cita, debe esperar al menos 14 días para volver a tomarlo.","p":"Correcto. Debe esperar al menos 14 días para repetir el examen de manejo."},"ref":{"doc":"MA","page":20}},{"id":"ma-035","scope":"MA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Massachusetts, what is the fine for a first offense of using a hand-held phone while driving?","o":["$25","$50","$100","$500"],"h1":"The fine goes up for a second and third offense. The first is the lowest of those.","h2":"In Massachusetts, a first offense for using a hand-held phone while driving is a $100 fine; it rises to $250 and then $500.","p":"Right. The first hand-held phone offense costs $100."},"es":{"q":"En Massachusetts, ¿cuál es la multa por una primera infracción de usar un teléfono en la mano mientras maneja?","o":["$25","$50","$100","$500"],"h1":"La multa sube en la segunda y la tercera infracción. La primera es la más baja de ellas.","h2":"En Massachusetts, la primera infracción por usar un teléfono en la mano mientras maneja tiene una multa de $100; luego sube a $250 y después a $500.","p":"Correcto. La primera infracción por usar el teléfono en la mano cuesta $100."},"ref":{"doc":"MA","page":40}},{"id":"ma-036","scope":"MA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Massachusetts, what is the fine for a driver who is not wearing a seat belt?","o":["$10","$25","$150","$300"],"h1":"It is a small fine, less than $50.","h2":"In Massachusetts, a driver who is not wearing a seat belt can be fined $25, and the same fine applies to passengers 16 and older.","p":"Right. Not wearing a seat belt can cost $25."},"es":{"q":"En Massachusetts, ¿cuál es la multa para un conductor que no usa el cinturón de seguridad?","o":["$10","$25","$150","$300"],"h1":"Es una multa pequeña, menos de $50.","h2":"En Massachusetts, un conductor que no usa el cinturón de seguridad puede recibir una multa de $25, y la misma multa se aplica a los pasajeros de 16 años o más.","p":"Correcto. No usar el cinturón de seguridad puede costar $25."},"ref":{"doc":"MA","page":35}},{"id":"ma-037","scope":"MA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Massachusetts, a child must ride in an approved child safety seat until which point?","o":["Age 8 or 57 inches tall","Age 4 or 40 inches tall","Age 6 or 48 inches tall","Age 12 or 60 inches tall"],"h1":"Think of a child in the second or third grade, a little under five feet tall.","h2":"In Massachusetts, a child must ride in an approved child safety seat until the child is at least 8 years old or at least 57 inches tall.","p":"Right. A child seat is needed until age 8 or 57 inches."},"es":{"q":"En Massachusetts, ¿hasta cuándo debe viajar un niño en un asiento de seguridad infantil aprobado?","o":["Hasta los 8 años o 57 pulgadas de estatura","Hasta los 4 años o 40 pulgadas de estatura","Hasta los 6 años o 48 pulgadas de estatura","Hasta los 12 años o 60 pulgadas de estatura"],"h1":"Piense en un niño de segundo o tercer grado, de un poco menos de cinco pies de estatura.","h2":"En Massachusetts, un niño debe viajar en un asiento de seguridad infantil aprobado hasta que tenga al menos 8 años o mida al menos 57 pulgadas.","p":"Correcto. Se necesita un asiento infantil hasta los 8 años o 57 pulgadas."},"ref":{"doc":"MA","page":36}},{"id":"ma-038","scope":"MA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Massachusetts, when you pass a bicyclist, a pedestrian or a road worker, how much space must you leave?","o":["At least 1 foot","At least 2 feet","At least 3 feet","At least 4 feet"],"h1":"It is the largest of these choices.","h2":"In Massachusetts, when you pass a vulnerable road user, such as a bicyclist, pedestrian or road worker, you must leave at least four feet of space.","p":"Right. Leave at least four feet when you pass."},"es":{"q":"En Massachusetts, cuando rebasa a un ciclista, un peatón o un trabajador de la vía, ¿cuánto espacio debe dejar?","o":["Al menos 1 pie","Al menos 2 pies","Al menos 3 pies","Al menos 4 pies"],"h1":"Es la mayor de estas opciones.","h2":"En Massachusetts, cuando rebasa a un usuario vulnerable de la vía, como un ciclista, un peatón o un trabajador de la vía, debe dejar al menos cuatro pies de espacio.","p":"Correcto. Deje al menos cuatro pies al rebasar."},"ref":{"doc":"MA","page":49}},{"id":"ma-039","scope":"MA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Massachusetts, what happens to the fine if you are caught speeding in a posted work zone?","o":["It stays the same","It goes up by $10","It is doubled","It is cut in half"],"h1":"Work zones protect people on foot, so the penalty is much higher.","h2":"In Massachusetts, the speeding fine is doubled when you are caught speeding in a posted work zone.","p":"Right. Speeding fines are doubled in work zones."},"es":{"q":"En Massachusetts, ¿qué pasa con la multa si lo detienen por exceso de velocidad en una zona de obras señalizada?","o":["Sigue igual","Sube $10","Se duplica","Se reduce a la mitad"],"h1":"Las zonas de obras protegen a personas a pie, así que la sanción es mucho mayor.","h2":"En Massachusetts, la multa por exceso de velocidad se duplica cuando lo detienen en una zona de obras señalizada.","p":"Correcto. Las multas por velocidad se duplican en las zonas de obras."},"ref":{"doc":"MA","page":57}},{"id":"ma-040","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, what happens if you are found guilty of three speeding violations within 12 months?","o":["Your license is suspended for 30 days","You get a written warning only","Your license is suspended for 5 years","You must retake the permit exam only"],"h1":"Your license is taken away for about a month.","h2":"In Massachusetts, three speeding violations within a 12-month period mean your license is automatically suspended for 30 days.","p":"Right. Three speeding violations in 12 months bring a 30-day suspension."},"es":{"q":"En Massachusetts, ¿qué pasa si lo declaran culpable de tres infracciones por exceso de velocidad en 12 meses?","o":["Le suspenden la licencia por 30 días","Solo recibe una advertencia escrita","Le suspenden la licencia por 5 años","Solo debe repetir el examen del permiso"],"h1":"Le quitan la licencia por más o menos un mes.","h2":"En Massachusetts, tres infracciones por exceso de velocidad en un período de 12 meses hacen que le suspendan la licencia automáticamente por 30 días.","p":"Correcto. Tres infracciones por velocidad en 12 meses traen una suspensión de 30 días."},"ref":{"doc":"MA","page":59}},{"id":"ma-041","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, how long is your license suspended if you have seven surchargeable events within three years?","o":["7 days","60 days","3 years","For life"],"h1":"It is about two months.","h2":"In Massachusetts, seven surchargeable events, such as at-fault crashes and moving violations, within three years mean an automatic 60-day license suspension.","p":"Right. Seven surchargeable events in three years bring a 60-day suspension."},"es":{"q":"En Massachusetts, ¿por cuánto tiempo le suspenden la licencia si tiene siete incidentes con recargo en tres años?","o":["7 días","60 días","3 años","De por vida"],"h1":"Son unos dos meses.","h2":"En Massachusetts, siete incidentes con recargo, como choques con culpa e infracciones de tránsito, en tres años causan una suspensión automática de la licencia por 60 días.","p":"Correcto. Siete incidentes con recargo en tres años traen una suspensión de 60 días."},"ref":{"doc":"MA","page":59}},{"id":"ma-042","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, how long is the license suspension for a first conviction of operating under the influence (OUI)?","o":["30 days","90 days","Five years","One year"],"h1":"It is longer than a few months, but much less than five years.","h2":"In Massachusetts, a first OUI conviction brings a one-year license suspension, although the court may allow an alcohol education program to shorten it.","p":"Right. A first OUI conviction means a one-year suspension."},"es":{"q":"En Massachusetts, ¿cuánto dura la suspensión de la licencia por una primera condena por manejar bajo la influencia (OUI)?","o":["30 días","90 días","Cinco años","Un año"],"h1":"Es más de unos pocos meses, pero mucho menos de cinco años.","h2":"En Massachusetts, una primera condena por OUI trae una suspensión de la licencia por un año, aunque el tribunal puede permitir un programa de educación sobre el alcohol para acortarla.","p":"Correcto. Una primera condena por OUI significa una suspensión de un año."},"ref":{"doc":"MA","page":68}},{"id":"ma-043","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, a driver over 21 with no earlier OUI offense refuses a breath or blood test. How long is the license suspended?","o":["7 days","30 days","180 days","10 years"],"h1":"It is about six months.","h2":"In Massachusetts, a driver over 21 with no prior OUI offense who refuses a chemical test loses the license for 180 days.","p":"Right. Refusing the test brings a 180-day suspension for a first-time adult driver."},"es":{"q":"En Massachusetts, un conductor mayor de 21 años sin infracciones previas de OUI se niega a una prueba de aliento o de sangre. ¿Por cuánto tiempo le suspenden la licencia?","o":["7 días","30 días","180 días","10 años"],"h1":"Son unos seis meses.","h2":"En Massachusetts, un conductor mayor de 21 años sin infracciones previas de OUI que se niega a una prueba química pierde la licencia por 180 días.","p":"Correcto. Negarse a la prueba trae una suspensión de 180 días para un adulto sin infracciones previas."},"ref":{"doc":"MA","page":70}},{"id":"ma-044","scope":"MA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Massachusetts, after a crash with an injury or $1,000 or more in damage, how soon must you file a written crash report with the RMV?","o":["Within 5 days","Within 30 days","Within 60 days","Within 6 months"],"h1":"It is less than one week.","h2":"In Massachusetts, you must file a written crash report with the RMV within five days of a crash that hurt or killed someone or caused $1,000 or more in damage.","p":"Right. The crash report is due within five days."},"es":{"q":"En Massachusetts, después de un choque con heridos o con daños de $1,000 o más, ¿en qué plazo debe presentar un informe escrito del choque al RMV?","o":["En 5 días","En 30 días","En 60 días","En 6 meses"],"h1":"Es menos de una semana.","h2":"En Massachusetts, debe presentar un informe escrito al RMV en un plazo de cinco días después de un choque que hirió o mató a alguien o que causó daños de $1,000 o más.","p":"Correcto. El informe del choque se debe presentar en cinco días."},"ref":{"doc":"MA","page":131}},{"id":"ma-045","scope":"MA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Massachusetts, you must switch from high beams to low beams when an oncoming vehicle is within what distance?","o":["100 feet","500 feet","50 feet","2,000 feet"],"h1":"It is more than the length of a football field.","h2":"In Massachusetts, you must dim your high beams when you are within 500 feet of an oncoming vehicle.","p":"Right. Dim your high beams within 500 feet of oncoming traffic."},"es":{"q":"En Massachusetts, ¿a qué distancia de un vehículo que viene de frente debe cambiar de luces altas a luces bajas?","o":["100 pies","500 pies","50 pies","2,000 pies"],"h1":"Es más que el largo de un campo de fútbol americano.","h2":"En Massachusetts, debe bajar las luces altas cuando está a 500 pies o menos de un vehículo que viene de frente.","p":"Correcto. Baje las luces altas a 500 pies del tráfico que viene de frente."},"ref":{"doc":"MA","page":46}},{"id":"ma-046","scope":"MA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Massachusetts, how close may you follow an emergency vehicle that is answering an alarm?","o":["No closer than 50 feet","No closer than 100 feet","No closer than 150 feet","No closer than 300 feet"],"h1":"It is the farthest of these choices.","h2":"In Massachusetts, it is illegal to follow closer than 300 feet behind an emergency vehicle that is responding to an alarm.","p":"Right. Stay at least 300 feet behind an emergency vehicle on a call."},"es":{"q":"En Massachusetts, ¿qué tan cerca puede seguir a un vehículo de emergencia que responde a una alarma?","o":["No a menos de 50 pies","No a menos de 100 pies","No a menos de 150 pies","No a menos de 300 pies"],"h1":"Es la mayor de estas opciones.","h2":"En Massachusetts, es ilegal seguir a menos de 300 pies detrás de un vehículo de emergencia que responde a una alarma.","p":"Correcto. Manténgase al menos a 300 pies detrás de un vehículo de emergencia que atiende una llamada."},"ref":{"doc":"MA","page":120}},{"id":"ma-047","scope":"MA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Massachusetts, how close to an intersection may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 20 feet","No closer than 100 feet"],"h1":"It is about the length of one large car.","h2":"In Massachusetts, you may not park within 20 feet of an intersection.","p":"Right. Park at least 20 feet from an intersection."},"es":{"q":"En Massachusetts, ¿qué tan cerca de una intersección puede estacionarse?","o":["No a menos de 5 pies","No a menos de 10 pies","No a menos de 20 pies","No a menos de 100 pies"],"h1":"Es más o menos el largo de un carro grande.","h2":"En Massachusetts, no puede estacionarse a menos de 20 pies de una intersección.","p":"Correcto. Estaciónese al menos a 20 pies de una intersección."},"ref":{"doc":"MA","page":110}},{"id":"ma-048","scope":"MA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Massachusetts, when the lights flash at a railroad crossing, where must you stop?","o":["At least 15 feet before the gate or light post","Right on the first rail","At least 2 feet before the gate","Anywhere you can see the train"],"h1":"Stop well back from the gate, about one car length away.","h2":"In Massachusetts, when the lights flash at a railroad crossing, you must stop at least 15 feet before the gate or light post and stay stopped until the gate goes up and the lights stop.","p":"Right. Stop at least 15 feet before the gate or light post."},"es":{"q":"En Massachusetts, cuando las luces destellan en un cruce de ferrocarril, ¿dónde debe detenerse?","o":["Al menos a 15 pies antes de la barrera o del poste de luces","Justo sobre el primer riel","Al menos a 2 pies antes de la barrera","En cualquier lugar donde vea el tren"],"h1":"Deténgase bien atrás de la barrera, a más o menos el largo de un carro.","h2":"En Massachusetts, cuando las luces destellan en un cruce de ferrocarril, debe detenerse al menos a 15 pies antes de la barrera o del poste de luces y quedarse detenido hasta que la barrera suba y las luces se apaguen.","p":"Correcto. Deténgase al menos a 15 pies antes de la barrera o del poste de luces."},"ref":{"doc":"MA","page":87}},{"id":"ma-049","scope":"MA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Massachusetts, how long does state law let a stopped vehicle's engine idle?","o":["No more than 30 minutes","No more than 5 minutes","No more than 1 hour","As long as you want"],"h1":"It is only a few minutes.","h2":"In Massachusetts, state law does not allow a vehicle to idle for more than five minutes.","p":"Right. Idling is limited to five minutes."},"es":{"q":"En Massachusetts, ¿cuánto tiempo permite la ley estatal que el motor de un vehículo detenido quede encendido en marcha mínima?","o":["No más de 30 minutos","No más de 5 minutos","No más de 1 hora","Todo el tiempo que quiera"],"h1":"Son solo unos pocos minutos.","h2":"En Massachusetts, la ley estatal no permite dejar un vehículo encendido en marcha mínima por más de cinco minutos.","p":"Correcto. El motor encendido sin moverse se limita a cinco minutos."},"ref":{"doc":"MA","page":132}},{"id":"ma-050","scope":"MA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Massachusetts, to pass by crossing a broken yellow line, how far ahead must you be able to see clearly?","o":["At least 50 feet","At least 100 feet","At least 200 feet","At least 400 feet"],"h1":"It is the longest of these distances.","h2":"In Massachusetts, you must be able to see clearly at least 400 feet ahead before you cross a broken yellow line to pass.","p":"Right. You need a clear view of at least 400 feet to pass."},"es":{"q":"En Massachusetts, para rebasar cruzando una línea amarilla discontinua, ¿hasta qué distancia adelante debe poder ver con claridad?","o":["Al menos 50 pies","Al menos 100 pies","Al menos 200 pies","Al menos 400 pies"],"h1":"Es la mayor de estas distancias.","h2":"En Massachusetts, debe poder ver con claridad al menos 400 pies adelante antes de cruzar una línea amarilla discontinua para rebasar.","p":"Correcto. Necesita ver con claridad al menos 400 pies para rebasar."},"ref":{"doc":"MA","page":103}},{"id":"ma-051","scope":"MA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Massachusetts, what fine can you get for having an open alcoholic drink in your vehicle?","o":["$5 to $20","$25 to $50","$100 to $500","$10,000 or more"],"h1":"It starts at about one hundred dollars.","h2":"In Massachusetts, having an open alcoholic drink in your vehicle, even if someone else holds it, can bring a fine of $100 to $500.","p":"Right. An open container can cost $100 to $500."},"es":{"q":"En Massachusetts, ¿qué multa puede recibir por tener una bebida alcohólica abierta en su vehículo?","o":["De $5 a $20","De $25 a $50","De $100 a $500","$10,000 o más"],"h1":"Empieza en unos cien dólares.","h2":"En Massachusetts, tener una bebida alcohólica abierta en su vehículo, aunque la sostenga otra persona, puede traer una multa de $100 a $500.","p":"Correcto. Un envase abierto puede costar de $100 a $500."},"ref":{"doc":"MA","page":74}},{"id":"md-001","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, what is the youngest age to get a learner's permit?","o":["15 years old","15 years and 6 months","15 years and 9 months","16 years old"],"h1":"It is three months before the 16th birthday.","h2":"In Maryland, you must be at least 15 years and 9 months old to get a learner's permit.","p":"Right. Maryland starts at 15 years and 9 months."},"es":{"q":"En Maryland, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["15 años","15 años y 6 meses","15 años y 9 meses","16 años"],"h1":"Es tres meses antes de cumplir 16.","h2":"En Maryland, usted debe tener por lo menos 15 años y 9 meses para obtener un permiso de aprendiz.","p":"Correcto. Maryland empieza a los 15 años y 9 meses."},"zh":{"q":"在 Maryland，最小几岁可以拿到学习驾照（learner's permit）？","o":["15 岁","15 岁又 6 个月","15 岁又 9 个月","16 岁"],"h1":"是 16 岁生日前三个月。","h2":"在 Maryland，你必须至少 15 岁又 9 个月，才能拿到学习驾照。","p":"对。Maryland 从 15 岁又 9 个月开始。"},"vi":{"q":"Ở Maryland, tuổi nhỏ nhất để lấy giấy phép tập lái (learner's permit) là bao nhiêu?","o":["15 tuổi","15 tuổi 6 tháng","15 tuổi 9 tháng","16 tuổi"],"h1":"Đó là ba tháng trước sinh nhật 16 tuổi.","h2":"Ở Maryland, bạn phải ít nhất 15 tuổi 9 tháng để lấy giấy phép tập lái.","p":"Đúng. Ở Maryland, bắt đầu từ 15 tuổi 9 tháng."},"tl":{"q":"Sa Maryland, ano ang pinakabatang edad para makakuha ng learner's permit?","o":["15 taong gulang","15 taon at 6 na buwan","15 taon at 9 na buwan","16 taong gulang"],"h1":"Tatlong buwan ito bago ang ika-16 na kaarawan.","h2":"Sa Maryland, dapat ay hindi bababa sa 15 taon at 9 na buwan ang edad mo para makakuha ng learner's permit.","p":"Tama. Nagsisimula ang Maryland sa 15 taon at 9 na buwan."},"ar":{"q":"في Maryland، ما أصغر عمر للحصول على تصريح التعلّم (learner's permit)؟","o":["15 سنة","15 سنة و6 أشهر","15 سنة و9 أشهر","16 سنة"],"h1":"هو ثلاثة أشهر قبل عيد الميلاد السادس عشر.","h2":"في Maryland يجب أن يكون عمرك 15 سنة و9 أشهر على الأقل للحصول على تصريح التعلّم.","p":"صحيح. في Maryland يبدأ التصريح من عمر 15 سنة و9 أشهر."},"ref":{"doc":"MD","page":9}},{"id":"md-002","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, how many of the 25 knowledge test questions must you answer correctly to pass?","o":["18","22","20","25"],"h1":"You may miss no more than three.","h2":"In Maryland, you must answer at least 22 of the 25 knowledge test questions correctly to pass.","p":"Right. 22 out of 25 passes in Maryland."},"es":{"q":"En Maryland, ¿cuántas de las 25 preguntas del examen de conocimientos debe contestar bien para aprobar?","o":["18","22","20","25"],"h1":"Puede fallar como máximo tres.","h2":"En Maryland, usted debe contestar bien por lo menos 22 de las 25 preguntas del examen de conocimientos para aprobar.","p":"Correcto. En Maryland se aprueba con 22 de 25."},"zh":{"q":"在 Maryland，25 道笔试题中，必须答对几道才能通过？","o":["18","22","20","25"],"h1":"你最多只能答错三道。","h2":"在 Maryland，25 道笔试题中你必须至少答对 22 道才能通过。","p":"对。在 Maryland，25 道答对 22 道就通过。"},"vi":{"q":"Ở Maryland, bạn phải trả lời đúng bao nhiêu câu trong 25 câu của bài thi kiến thức để đậu?","o":["18","22","20","25"],"h1":"Bạn được sai không quá ba câu.","h2":"Ở Maryland, bạn phải trả lời đúng ít nhất 22 trong 25 câu của bài thi kiến thức để đậu.","p":"Đúng. Ở Maryland, đúng 22 trên 25 câu là đậu."},"tl":{"q":"Sa Maryland, ilan sa 25 tanong ng knowledge test ang dapat mong masagot nang tama para pumasa?","o":["18","22","20","25"],"h1":"Hindi ka puwedeng magkamali nang higit sa tatlo.","h2":"Sa Maryland, dapat mong masagot nang tama ang hindi bababa sa 22 sa 25 tanong ng knowledge test para pumasa.","p":"Tama. Pasado ang 22 sa 25 sa Maryland."},"ar":{"q":"في Maryland، كم سؤالًا من أسئلة اختبار المعرفة الـ25 يجب أن تجيب عنها إجابة صحيحة لتنجح؟","o":["18","22","20","25"],"h1":"لا يمكنك أن تخطئ في أكثر من ثلاثة أسئلة.","h2":"في Maryland يجب أن تجيب إجابة صحيحة عن 22 سؤالًا على الأقل من أسئلة اختبار المعرفة الـ25 لتنجح.","p":"صحيح. في Maryland تنجح بـ22 من 25."},"ref":{"doc":"MD","page":null}},{"id":"md-003","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maryland, who may supervise a driver with a learner's permit?","o":["Any licensed driver 18 or older","Any adult, licensed or not","A licensed driver 25 or older","A driver 21 or older who has held a license for at least 3 years"],"h1":"Both an age and a number of years with a license matter.","h2":"In Maryland, the supervising driver must be at least 21 years old and must have held a valid license for at least 3 years.","p":"Right. 21 or older, with at least 3 years licensed."},"es":{"q":"En Maryland, ¿quién puede supervisar a un conductor con permiso de aprendiz?","o":["Cualquier conductor con licencia de 18 años o más","Cualquier adulto, con o sin licencia","Un conductor con licencia de 25 años o más","Un conductor de 21 años o más que ha tenido licencia por lo menos 3 años"],"h1":"Importan la edad y también los años con licencia.","h2":"En Maryland, el conductor que supervisa debe tener por lo menos 21 años y haber tenido una licencia válida por lo menos 3 años.","p":"Correcto. 21 años o más, con por lo menos 3 años de licencia."},"zh":{"q":"在 Maryland，谁可以陪同持学习驾照的司机？","o":["任何 18 岁或以上、有驾照的司机","任何成年人，有没有驾照都可以","25 岁或以上、有驾照的司机","21 岁或以上、持有驾照至少 3 年的司机"],"h1":"年龄和持有驾照的年数都很重要。","h2":"在 Maryland，陪同的司机必须至少 21 岁，而且必须持有有效驾照至少 3 年。","p":"对。21 岁或以上，至少持有驾照 3 年。"},"vi":{"q":"Ở Maryland, ai được phép giám sát người lái có giấy phép tập lái?","o":["Bất kỳ người có bằng lái nào từ 18 tuổi trở lên","Bất kỳ người lớn nào, có bằng lái hay không","Người có bằng lái từ 25 tuổi trở lên","Người từ 21 tuổi trở lên đã có bằng lái ít nhất 3 năm"],"h1":"Cả tuổi và số năm có bằng lái đều quan trọng.","h2":"Ở Maryland, người giám sát phải ít nhất 21 tuổi và đã có bằng lái hợp lệ ít nhất 3 năm.","p":"Đúng. Từ 21 tuổi trở lên, và có bằng lái ít nhất 3 năm."},"tl":{"q":"Sa Maryland, sino ang puwedeng magbantay sa driver na may learner's permit?","o":["Kahit sinong may lisensya na 18 taong gulang pataas","Kahit sinong adulto, may lisensya man o wala","Driver na may lisensya na 25 taong gulang pataas","Driver na 21 taong gulang pataas na may lisensya nang hindi bababa sa 3 taon"],"h1":"Mahalaga ang edad at ang bilang ng taon na may lisensya.","h2":"Sa Maryland, ang nagbabantay na driver ay dapat hindi bababa sa 21 taong gulang at may valid na lisensya nang hindi bababa sa 3 taon.","p":"Tama. 21 pataas, at may lisensya nang hindi bababa sa 3 taon."},"ar":{"q":"في Maryland، من يمكنه أن يرافق ويشرف على سائق يحمل تصريح التعلّم؟","o":["أي سائق لديه رخصة عمره 18 سنة أو أكثر","أي شخص بالغ، لديه رخصة أو ليس لديه","سائق لديه رخصة عمره 25 سنة أو أكثر","سائق عمره 21 سنة أو أكثر ولديه رخصة منذ 3 سنوات على الأقل"],"h1":"العمر وعدد سنوات حمل الرخصة كلاهما مهم.","h2":"في Maryland يجب أن يكون السائق المشرف عمره 21 سنة على الأقل ولديه رخصة سارية منذ 3 سنوات على الأقل.","p":"صحيح. 21 سنة أو أكثر، ولديه رخصة منذ 3 سنوات على الأقل."},"ref":{"doc":"MD","page":51}},{"id":"md-004","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, where must the supervising driver sit when a learner is driving?","o":["In the front passenger seat, with no one else in the front","In any back seat","Anywhere in the car","Behind the driver"],"h1":"The supervisor needs to be right beside the learner.","h2":"In Maryland, the supervising driver must sit in the front passenger seat, and no one else may sit in the front.","p":"Right. The supervisor sits up front, beside you."},"es":{"q":"En Maryland, ¿dónde debe sentarse el conductor que supervisa cuando maneja un aprendiz?","o":["En el asiento del pasajero delantero, sin nadie más adelante","En cualquier asiento de atrás","En cualquier lugar del auto","Detrás del conductor"],"h1":"El supervisor debe estar justo al lado del aprendiz.","h2":"En Maryland, el conductor que supervisa debe sentarse en el asiento del pasajero delantero, y nadie más puede ir adelante.","p":"Correcto. El supervisor va adelante, a su lado."},"zh":{"q":"在 Maryland，学习驾驶的人开车时，陪同的司机必须坐在哪里？","o":["前排乘客座位，前排不能坐其他人","任何后排座位","车里任何地方","司机后面"],"h1":"陪同的人需要就在学习驾驶的人旁边。","h2":"在 Maryland，陪同的司机必须坐在前排乘客座位，前排不能坐其他人。","p":"对。陪同的人坐在前排，在你旁边。"},"vi":{"q":"Ở Maryland, người giám sát phải ngồi ở đâu khi người tập lái đang lái xe?","o":["Ở ghế hành khách phía trước, và không ai khác ngồi phía trước","Ở bất kỳ ghế sau nào","Ở bất kỳ chỗ nào trong xe","Phía sau người lái"],"h1":"Người giám sát cần ngồi ngay bên cạnh người tập lái.","h2":"Ở Maryland, người giám sát phải ngồi ở ghế hành khách phía trước, và không ai khác được ngồi phía trước.","p":"Đúng. Người giám sát ngồi phía trước, bên cạnh bạn."},"tl":{"q":"Sa Maryland, saan dapat umupo ang nagbabantay na driver habang nagmamaneho ang learner?","o":["Sa upuan ng pasahero sa harap, at walang ibang nasa harap","Sa kahit anong upuan sa likod","Kahit saan sa kotse","Sa likod ng driver"],"h1":"Kailangang nasa tabi mismo ng learner ang nagbabantay.","h2":"Sa Maryland, dapat umupo ang nagbabantay na driver sa upuan ng pasahero sa harap, at walang ibang puwedeng umupo sa harap.","p":"Tama. Sa harap umuupo ang nagbabantay, sa tabi mo."},"ar":{"q":"في Maryland، أين يجب أن يجلس السائق المشرف عندما يقود المتعلّم؟","o":["في مقعد الراكب الأمامي، ولا يجلس أحد غيره في الأمام","في أي مقعد خلفي","في أي مكان في السيارة","خلف السائق"],"h1":"يجب أن يكون المشرف بجانب المتعلّم مباشرة.","h2":"في Maryland يجب أن يجلس السائق المشرف في مقعد الراكب الأمامي، ولا يجوز أن يجلس أحد غيره في الأمام.","p":"صحيح. المشرف يجلس في الأمام بجانبك."},"ref":{"doc":"MD","page":51}},{"id":"md-005","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, how many hours of supervised practice must a new driver log with a learner's permit?","o":["30 hours, including 5 at night","40 hours, including 10 at night","60 hours, including 10 at night","100 hours, including 20 at night"],"h1":"It is the highest of the usual numbers, with 10 of them at night.","h2":"In Maryland, a learner must log 60 hours of supervised practice, and 10 of those hours must be at night.","p":"Right. 60 hours, 10 at night."},"es":{"q":"En Maryland, ¿cuántas horas de práctica supervisada debe registrar un conductor nuevo con permiso de aprendiz?","o":["30 horas, 5 de ellas de noche","40 horas, 10 de ellas de noche","60 horas, 10 de ellas de noche","100 horas, 20 de ellas de noche"],"h1":"Es el número más alto de los habituales, con 10 de ellas de noche.","h2":"En Maryland, un aprendiz debe registrar 60 horas de práctica supervisada, y 10 de esas horas deben ser de noche.","p":"Correcto. 60 horas, 10 de noche."},"zh":{"q":"在 Maryland，新司机持学习驾照期间，必须记录多少小时有人陪同的练习？","o":["30 小时，其中 5 小时在夜间","40 小时，其中 10 小时在夜间","60 小时，其中 10 小时在夜间","100 小时，其中 20 小时在夜间"],"h1":"这是常见数字里最高的，其中 10 小时在夜间。","h2":"在 Maryland，学习驾驶的人必须记录 60 小时有人陪同的练习，其中 10 小时必须在夜间。","p":"对。60 小时，其中 10 小时在夜间。"},"vi":{"q":"Ở Maryland, người lái mới có giấy phép tập lái phải ghi lại bao nhiêu giờ tập lái có giám sát?","o":["30 giờ, trong đó 5 giờ vào ban đêm","40 giờ, trong đó 10 giờ vào ban đêm","60 giờ, trong đó 10 giờ vào ban đêm","100 giờ, trong đó 20 giờ vào ban đêm"],"h1":"Đó là con số cao nhất trong các con số thường gặp, với 10 giờ vào ban đêm.","h2":"Ở Maryland, người tập lái phải ghi lại 60 giờ tập lái có giám sát, và 10 giờ trong số đó phải vào ban đêm.","p":"Đúng. 60 giờ, 10 giờ vào ban đêm."},"tl":{"q":"Sa Maryland, ilang oras ng praktis na may bantay ang dapat itala ng bagong driver na may learner's permit?","o":["30 oras, kasama ang 5 sa gabi","40 oras, kasama ang 10 sa gabi","60 oras, kasama ang 10 sa gabi","100 oras, kasama ang 20 sa gabi"],"h1":"Ito ang pinakamataas sa mga karaniwang bilang, at 10 dito ay sa gabi.","h2":"Sa Maryland, dapat magtala ang learner ng 60 oras ng praktis na may bantay, at 10 sa mga oras na iyon ay dapat sa gabi.","p":"Tama. 60 oras, 10 sa gabi."},"ar":{"q":"في Maryland، كم ساعة من التدريب تحت الإشراف يجب أن يسجّلها السائق الجديد الذي يحمل تصريح التعلّم؟","o":["30 ساعة، منها 5 في الليل","40 ساعة، منها 10 في الليل","60 ساعة، منها 10 في الليل","100 ساعة، منها 20 في الليل"],"h1":"هو أعلى رقم بين الأرقام المعتادة، و10 ساعات منه في الليل.","h2":"في Maryland يجب أن يسجّل المتعلّم 60 ساعة من التدريب تحت الإشراف، ويجب أن تكون 10 ساعات منها في الليل.","p":"صحيح. 60 ساعة، منها 10 في الليل."},"ref":{"doc":"MD","page":10}},{"id":"md-006","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, which practice hours count as night driving?","o":["From 9:00 p.m. to 6:00 a.m.","From 30 minutes before sunset to 30 minutes after sunrise","From midnight to 5:00 a.m.","Any time the headlights are on"],"h1":"The answer follows the sun, not the clock.","h2":"In Maryland, night practice is driving from 30 minutes before sunset until 30 minutes after sunrise.","p":"Right. Night practice follows sunset and sunrise."},"es":{"q":"En Maryland, ¿qué horas de práctica cuentan como manejo nocturno?","o":["De 9:00 p.m. a 6:00 a.m.","Desde 30 minutos antes de la puesta del sol hasta 30 minutos después del amanecer","De medianoche a 5:00 a.m.","Cualquier momento con las luces encendidas"],"h1":"La respuesta sigue al sol, no al reloj.","h2":"En Maryland, la práctica nocturna es manejar desde 30 minutos antes de la puesta del sol hasta 30 minutos después del amanecer.","p":"Correcto. La práctica nocturna sigue la puesta del sol y el amanecer."},"zh":{"q":"在 Maryland，哪些练习时间算是夜间驾驶？","o":["晚上 9:00 到早上 6:00","日落前 30 分钟到日出后 30 分钟","午夜到早上 5:00","任何开着车头灯的时候"],"h1":"答案跟着太阳走，不是跟着时钟。","h2":"在 Maryland，夜间练习是指从日落前 30 分钟到日出后 30 分钟之间的驾驶。","p":"对。夜间练习按日落和日出来算。"},"vi":{"q":"Ở Maryland, những giờ tập lái nào được tính là lái xe ban đêm?","o":["Từ 9:00 tối đến 6:00 sáng","Từ 30 phút trước khi mặt trời lặn đến 30 phút sau khi mặt trời mọc","Từ nửa đêm đến 5:00 sáng","Bất cứ lúc nào bật đèn pha"],"h1":"Câu trả lời theo mặt trời, không theo đồng hồ.","h2":"Ở Maryland, tập lái ban đêm là lái xe từ 30 phút trước khi mặt trời lặn đến 30 phút sau khi mặt trời mọc.","p":"Đúng. Tập lái ban đêm tính theo lúc mặt trời lặn và mọc."},"tl":{"q":"Sa Maryland, aling mga oras ng praktis ang binibilang na pagmamaneho sa gabi?","o":["Mula 9:00 p.m. hanggang 6:00 a.m.","Mula 30 minuto bago lumubog ang araw hanggang 30 minuto pagkasikat ng araw","Mula hatinggabi hanggang 5:00 a.m.","Anumang oras na nakabukas ang headlights"],"h1":"Sumusunod ang sagot sa araw, hindi sa orasan.","h2":"Sa Maryland, ang praktis sa gabi ay pagmamaneho mula 30 minuto bago lumubog ang araw hanggang 30 minuto pagkasikat ng araw.","p":"Tama. Sumusunod ang praktis sa gabi sa paglubog at pagsikat ng araw."},"ar":{"q":"في Maryland، أي ساعات التدريب تُحسب قيادةً ليلية؟","o":["من 9:00 مساءً إلى 6:00 صباحًا","من 30 دقيقة قبل غروب الشمس إلى 30 دقيقة بعد شروق الشمس","من منتصف الليل إلى 5:00 صباحًا","أي وقت تكون فيه الأضواء الأمامية مضاءة"],"h1":"الجواب يتبع الشمس، لا الساعة.","h2":"في Maryland التدريب الليلي هو القيادة من 30 دقيقة قبل غروب الشمس حتى 30 دقيقة بعد شروق الشمس.","p":"صحيح. التدريب الليلي يتبع الغروب والشروق."},"ref":{"doc":"MD","page":10}},{"id":"md-007","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maryland, how long must a driver under 18 hold a learner's permit before getting a provisional license?","o":["45 days","3 months","6 months","9 months"],"h1":"It is the longest of the choices, three quarters of a year.","h2":"In Maryland, a driver under 18 must hold the learner's permit for at least 9 months before getting a provisional license.","p":"Right. Nine months for teens in Maryland."},"es":{"q":"En Maryland, ¿cuánto tiempo debe tener un conductor menor de 18 años el permiso de aprendiz antes de obtener una licencia provisional?","o":["45 días","3 meses","6 meses","9 meses"],"h1":"Es la opción más larga, tres cuartos de año.","h2":"En Maryland, un conductor menor de 18 años debe tener el permiso de aprendiz por lo menos 9 meses antes de obtener una licencia provisional.","p":"Correcto. Nueve meses para los jóvenes en Maryland."},"zh":{"q":"在 Maryland，18 岁以下的司机必须持有学习驾照多久，才能拿到过渡驾照（provisional license）？","o":["45 天","3 个月","6 个月","9 个月"],"h1":"这是选项里最长的，是四分之三年。","h2":"在 Maryland，18 岁以下的司机必须持有学习驾照至少 9 个月，才能拿到过渡驾照。","p":"对。Maryland 的青少年要九个月。"},"vi":{"q":"Ở Maryland, người lái dưới 18 tuổi phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái tạm thời (provisional license)?","o":["45 ngày","3 tháng","6 tháng","9 tháng"],"h1":"Đó là lựa chọn dài nhất, ba phần tư năm.","h2":"Ở Maryland, người lái dưới 18 tuổi phải giữ giấy phép tập lái ít nhất 9 tháng trước khi lấy bằng lái tạm thời.","p":"Đúng. Ở Maryland, thanh thiếu niên phải chờ chín tháng."},"tl":{"q":"Sa Maryland, gaano katagal dapat hawak ng driver na wala pang 18 ang learner's permit bago makakuha ng provisional license?","o":["45 araw","3 buwan","6 na buwan","9 na buwan"],"h1":"Ito ang pinakamahaba sa mga pagpipilian, tatlong-kapat ng isang taon.","h2":"Sa Maryland, dapat hawak ng driver na wala pang 18 ang learner's permit nang hindi bababa sa 9 na buwan bago makakuha ng provisional license.","p":"Tama. Siyam na buwan para sa mga kabataan sa Maryland."},"ar":{"q":"في Maryland، كم يجب أن يحتفظ السائق الذي عمره أقل من 18 سنة بتصريح التعلّم قبل الحصول على الرخصة المؤقتة (provisional license)؟","o":["45 يومًا","3 أشهر","6 أشهر","9 أشهر"],"h1":"هو أطول خيار، ثلاثة أرباع السنة.","h2":"في Maryland يجب أن يحتفظ السائق الذي عمره أقل من 18 سنة بتصريح التعلّم 9 أشهر على الأقل قبل الحصول على الرخصة المؤقتة.","p":"صحيح. تسعة أشهر للمراهقين في Maryland."},"ref":{"doc":"MD","page":10}},{"id":"md-008","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, how long must a new driver aged 25 or older hold a learner's permit before getting a provisional license?","o":["45 days","9 months","1 year","No waiting period"],"h1":"Older drivers wait much less than teens, but there is still a wait.","h2":"In Maryland, a new driver aged 25 or older must hold the learner's permit for at least 45 days.","p":"Right. 45 days for drivers 25 and older."},"es":{"q":"En Maryland, ¿cuánto tiempo debe tener el permiso de aprendiz un conductor nuevo de 25 años o más antes de obtener una licencia provisional?","o":["45 días","9 meses","1 año","No hay tiempo de espera"],"h1":"Los mayores esperan mucho menos que los jóvenes, pero sí hay una espera.","h2":"En Maryland, un conductor nuevo de 25 años o más debe tener el permiso de aprendiz por lo menos 45 días.","p":"Correcto. 45 días para conductores de 25 años o más."},"zh":{"q":"在 Maryland，25 岁或以上的新司机必须持有学习驾照多久，才能拿到过渡驾照？","o":["45 天","9 个月","1 年","不用等"],"h1":"年纪大的司机等的时间比青少年短很多，但还是要等。","h2":"在 Maryland，25 岁或以上的新司机必须持有学习驾照至少 45 天。","p":"对。25 岁及以上的司机要 45 天。"},"vi":{"q":"Ở Maryland, người lái mới từ 25 tuổi trở lên phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái tạm thời (provisional license)?","o":["45 ngày","9 tháng","1 năm","Không phải chờ"],"h1":"Người lớn tuổi chờ ít hơn nhiều so với thanh thiếu niên, nhưng vẫn phải chờ.","h2":"Ở Maryland, người lái mới từ 25 tuổi trở lên phải giữ giấy phép tập lái ít nhất 45 ngày.","p":"Đúng. 45 ngày cho người lái từ 25 tuổi trở lên."},"tl":{"q":"Sa Maryland, gaano katagal dapat hawak ng bagong driver na 25 taong gulang pataas ang learner's permit bago makakuha ng provisional license?","o":["45 araw","9 na buwan","1 taon","Walang hihintayin"],"h1":"Mas maikli ang hinihintay ng mas matatandang driver kaysa sa kabataan, pero may hinihintay pa rin.","h2":"Sa Maryland, dapat hawak ng bagong driver na 25 taong gulang pataas ang learner's permit nang hindi bababa sa 45 araw.","p":"Tama. 45 araw para sa mga driver na 25 pataas."},"ar":{"q":"في Maryland، كم يجب أن يحتفظ السائق الجديد الذي عمره 25 سنة أو أكثر بتصريح التعلّم قبل الحصول على الرخصة المؤقتة (provisional license)؟","o":["45 يومًا","9 أشهر","سنة واحدة","لا توجد مدة انتظار"],"h1":"السائقون الأكبر سنًا ينتظرون أقل بكثير من المراهقين، لكن ما زال هناك انتظار.","h2":"في Maryland يجب أن يحتفظ السائق الجديد الذي عمره 25 سنة أو أكثر بتصريح التعلّم 45 يومًا على الأقل.","p":"صحيح. 45 يومًا للسائقين الذين عمرهم 25 سنة أو أكثر."},"ref":{"doc":"MD","page":10}},{"id":"md-009","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, what happens if a learner is convicted of a moving violation while holding the permit?","o":["Nothing changes","The permit is upgraded early","The waiting time restarts, with at least 9 months from the conviction","Only a fine is paid"],"h1":"The clock does not keep running as before.","h2":"In Maryland, a moving violation conviction restarts the waiting time, so the learner must wait at least 9 months from the date of the conviction.","p":"Right. A violation resets the clock to 9 months."},"es":{"q":"En Maryland, ¿qué pasa si un aprendiz es condenado por una infracción de tránsito en movimiento mientras tiene el permiso?","o":["Nada cambia","El permiso se mejora antes de tiempo","El tiempo de espera vuelve a empezar, con por lo menos 9 meses desde la condena","Solo se paga una multa"],"h1":"El reloj no sigue corriendo como antes.","h2":"En Maryland, una condena por infracción en movimiento reinicia la espera, y el aprendiz debe esperar por lo menos 9 meses desde la fecha de la condena.","p":"Correcto. Una infracción reinicia la cuenta a 9 meses."},"zh":{"q":"在 Maryland，学习驾驶的人持学习驾照期间被判行车违规，会怎么样？","o":["什么都不变","学习驾照提前升级","等待时间重新开始，从被判那天起至少 9 个月","只交罚款"],"h1":"时间不会像以前那样继续算下去。","h2":"在 Maryland，被判行车违规会让等待时间重新开始，所以学习驾驶的人必须从被判那天起至少再等 9 个月。","p":"对。违规会让时间重新回到 9 个月。"},"vi":{"q":"Ở Maryland, điều gì xảy ra nếu người tập lái bị kết tội vi phạm khi đang lái xe trong thời gian có giấy phép tập lái?","o":["Không có gì thay đổi","Giấy phép được nâng cấp sớm","Thời gian chờ bắt đầu lại, ít nhất 9 tháng kể từ ngày bị kết tội","Chỉ phải nộp tiền phạt"],"h1":"Thời gian không tiếp tục tính như trước.","h2":"Ở Maryland, bị kết tội vi phạm khi đang lái xe sẽ làm thời gian chờ bắt đầu lại, nên người tập lái phải chờ ít nhất 9 tháng kể từ ngày bị kết tội.","p":"Đúng. Một vi phạm đưa thời gian chờ về lại 9 tháng."},"tl":{"q":"Sa Maryland, ano ang mangyayari kung mahatulan ang learner ng moving violation habang hawak ang permit?","o":["Walang magbabago","Maagang maa-upgrade ang permit","Magsisimula ulit ang paghihintay, hindi bababa sa 9 na buwan mula sa hatol","Multa lang ang babayaran"],"h1":"Hindi na tuloy-tuloy ang bilang ng oras gaya ng dati.","h2":"Sa Maryland, kapag nahatulan ng moving violation, magsisimula ulit ang paghihintay, kaya dapat maghintay ang learner nang hindi bababa sa 9 na buwan mula sa petsa ng hatol.","p":"Tama. Ibinabalik ng violation ang bilang sa 9 na buwan."},"ar":{"q":"في Maryland، ماذا يحدث إذا أُدين المتعلّم بمخالفة أثناء القيادة (moving violation) وهو يحمل التصريح؟","o":["لا يتغيّر شيء","تتم ترقية التصريح مبكرًا","تبدأ مدة الانتظار من جديد، 9 أشهر على الأقل من تاريخ الإدانة","يدفع غرامة فقط"],"h1":"العدّ لا يستمر كما كان من قبل.","h2":"في Maryland الإدانة بمخالفة أثناء القيادة تجعل مدة الانتظار تبدأ من جديد، فيجب أن ينتظر المتعلّم 9 أشهر على الأقل من تاريخ الإدانة.","p":"صحيح. المخالفة تعيد العدّ إلى 9 أشهر."},"ref":{"doc":"MD","page":10}},{"id":"md-010","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, how much driver education must a new driver complete?","o":["10 hours in class and 2 hours behind the wheel","30 hours in class and 6 hours behind the wheel","No driver education is required","6 hours in class and 30 hours behind the wheel"],"h1":"The classroom part is much longer than the time behind the wheel.","h2":"In Maryland, the certified driver education program requires at least 30 hours of classroom instruction and 6 hours of behind-the-wheel training.","p":"Right. 30 hours in class and 6 behind the wheel."},"es":{"q":"En Maryland, ¿cuánta educación vial debe completar un conductor nuevo?","o":["10 horas en clase y 2 horas al volante","30 horas en clase y 6 horas al volante","No se requiere educación vial","6 horas en clase y 30 horas al volante"],"h1":"La parte en clase es mucho más larga que el tiempo al volante.","h2":"En Maryland, el programa certificado de educación vial exige por lo menos 30 horas de clase y 6 horas de práctica al volante.","p":"Correcto. 30 horas en clase y 6 al volante."},"zh":{"q":"在 Maryland，新司机必须完成多少驾驶课？","o":["课堂 10 小时，实际开车 2 小时","课堂 30 小时，实际开车 6 小时","不需要上驾驶课","课堂 6 小时，实际开车 30 小时"],"h1":"课堂部分比实际开车的时间长很多。","h2":"在 Maryland，经过认证的驾驶课要求至少 30 小时课堂教学和 6 小时实际开车培训。","p":"对。课堂 30 小时，实际开车 6 小时。"},"vi":{"q":"Ở Maryland, người lái mới phải hoàn thành bao nhiêu giờ học lái xe (driver education)?","o":["10 giờ trong lớp và 2 giờ lái xe thực tế","30 giờ trong lớp và 6 giờ lái xe thực tế","Không bắt buộc học lái xe","6 giờ trong lớp và 30 giờ lái xe thực tế"],"h1":"Phần học trong lớp dài hơn nhiều so với thời gian lái xe thực tế.","h2":"Ở Maryland, chương trình học lái xe được chứng nhận đòi hỏi ít nhất 30 giờ học trong lớp và 6 giờ lái xe thực tế.","p":"Đúng. 30 giờ trong lớp và 6 giờ lái xe thực tế."},"tl":{"q":"Sa Maryland, gaano karaming driver education ang dapat tapusin ng bagong driver?","o":["10 oras sa klase at 2 oras sa manibela","30 oras sa klase at 6 na oras sa manibela","Hindi kailangan ang driver education","6 na oras sa klase at 30 oras sa manibela"],"h1":"Mas mahaba ang bahagi sa klase kaysa sa oras sa manibela.","h2":"Sa Maryland, ang certified na driver education program ay nangangailangan ng hindi bababa sa 30 oras ng pag-aaral sa klase at 6 na oras ng pagsasanay sa manibela.","p":"Tama. 30 oras sa klase at 6 sa manibela."},"ar":{"q":"في Maryland، كم من تعليم القيادة (driver education) يجب أن يُكمل السائق الجديد؟","o":["10 ساعات في الصف وساعتان خلف المقود","30 ساعة في الصف و6 ساعات خلف المقود","تعليم القيادة غير مطلوب","6 ساعات في الصف و30 ساعة خلف المقود"],"h1":"جزء الصف أطول بكثير من الوقت خلف المقود.","h2":"في Maryland يتطلب برنامج تعليم القيادة المعتمد 30 ساعة على الأقل من الدروس في الصف و6 ساعات من التدريب خلف المقود.","p":"صحيح. 30 ساعة في الصف و6 خلف المقود."},"ref":{"doc":"MD","page":null}},{"id":"md-011","scope":"MD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maryland, may a learner's permit holder use a phone with Bluetooth while driving?","o":["Yes, hands-free is allowed","Yes, for short calls","Yes, if the supervisor allows it","No, only to call 911 in an emergency"],"h1":"The rule for learners covers every kind of phone use.","h2":"In Maryland, a learner's permit holder may not use a phone while driving, even with Bluetooth or hands-free, except to call 911 in an emergency.","p":"Right. Learners in Maryland do not use the phone at all."},"es":{"q":"En Maryland, ¿puede una persona con permiso de aprendiz usar un teléfono con Bluetooth mientras maneja?","o":["Sí, manos libres está permitido","Sí, para llamadas cortas","Sí, si el supervisor lo permite","No, solo para llamar al 911 en una emergencia"],"h1":"La regla para aprendices cubre todo uso del teléfono.","h2":"En Maryland, quien tiene permiso de aprendiz no puede usar el teléfono mientras maneja, ni con Bluetooth ni manos libres, excepto para llamar al 911 en una emergencia.","p":"Correcto. Los aprendices en Maryland no usan el teléfono para nada."},"zh":{"q":"在 Maryland，持学习驾照的人开车时可以用蓝牙打电话吗？","o":["可以，免提是允许的","可以，短时间通话可以","可以，只要陪同的人同意","不可以，只能在紧急情况下打 911"],"h1":"对学习驾驶的人的规定包括所有手机用法。","h2":"在 Maryland，持学习驾照的人开车时不能用手机，用蓝牙或免提也不行，只有在紧急情况下打 911 除外。","p":"对。Maryland 学习驾驶的人完全不用手机。"},"vi":{"q":"Ở Maryland, người có giấy phép tập lái có được dùng điện thoại với Bluetooth khi đang lái xe không?","o":["Có, được dùng rảnh tay","Có, cho các cuộc gọi ngắn","Có, nếu người giám sát cho phép","Không, chỉ được gọi 911 khi khẩn cấp"],"h1":"Quy định cho người tập lái áp dụng cho mọi cách dùng điện thoại.","h2":"Ở Maryland, người có giấy phép tập lái không được dùng điện thoại khi lái xe, kể cả với Bluetooth hay rảnh tay, trừ khi gọi 911 lúc khẩn cấp.","p":"Đúng. Ở Maryland, người tập lái hoàn toàn không dùng điện thoại."},"tl":{"q":"Sa Maryland, puwede bang gumamit ng phone na may Bluetooth habang nagmamaneho ang may hawak ng learner's permit?","o":["Oo, puwede ang hands-free","Oo, para sa maiikling tawag","Oo, kung papayag ang nagbabantay","Hindi, maliban sa pagtawag sa 911 sa emergency"],"h1":"Sakop ng patakaran para sa learners ang lahat ng uri ng paggamit ng phone.","h2":"Sa Maryland, hindi puwedeng gumamit ng phone habang nagmamaneho ang may hawak ng learner's permit, kahit Bluetooth o hands-free, maliban sa pagtawag sa 911 sa emergency.","p":"Tama. Hindi talaga gumagamit ng phone ang learners sa Maryland."},"ar":{"q":"في Maryland، هل يجوز لحامل تصريح التعلّم أن يستعمل الهاتف عبر Bluetooth أثناء القيادة؟","o":["نعم، بدون استعمال اليدين مسموح","نعم، للمكالمات القصيرة","نعم، إذا سمح المشرف بذلك","لا، إلا للاتصال بـ911 في حالة طوارئ"],"h1":"القاعدة الخاصة بالمتعلّمين تشمل كل أنواع استعمال الهاتف.","h2":"في Maryland لا يجوز لحامل تصريح التعلّم أن يستعمل الهاتف أثناء القيادة، حتى عبر Bluetooth أو بدون استعمال اليدين، إلا للاتصال بـ911 في حالة طوارئ.","p":"صحيح. المتعلّمون في Maryland لا يستعملون الهاتف أبدًا."},"ref":{"doc":"MD","page":47}},{"id":"md-012","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, during which hours may a provisional driver under 18 not drive without a supervising driver?","o":["Midnight to 5:00 a.m.","9:00 p.m. to 6:00 a.m.","10:00 p.m. to 5:00 a.m.","There is no night limit"],"h1":"The limit starts at the very start of a new day.","h2":"In Maryland, a provisional driver under 18 may not drive between midnight and 5:00 in the morning without a supervising driver, unless going to or from work, school activities, volunteer programs or sports.","p":"Right. Midnight to 5 a.m. is off limits."},"es":{"q":"En Maryland, ¿en qué horario no puede manejar sin supervisor un conductor provisional menor de 18 años?","o":["De medianoche a 5:00 a.m.","De 9:00 p.m. a 6:00 a.m.","De 10:00 p.m. a 5:00 a.m.","No hay límite de noche"],"h1":"El límite empieza justo al comenzar un nuevo día.","h2":"En Maryland, un conductor provisional menor de 18 años no puede manejar entre la medianoche y las 5:00 de la mañana sin supervisor, salvo para ir o volver del trabajo, actividades escolares, voluntariado o deportes.","p":"Correcto. De medianoche a 5 a.m. no se maneja."},"zh":{"q":"在 Maryland，18 岁以下持过渡驾照的司机，在哪些时间没有陪同的司机就不能开车？","o":["午夜到早上 5:00","晚上 9:00 到早上 6:00","晚上 10:00 到早上 5:00","没有夜间限制"],"h1":"这个限制从新的一天刚开始时开始。","h2":"在 Maryland，18 岁以下持过渡驾照的司机，没有陪同的司机时，不能在午夜到早上 5:00 之间开车，除非是去上班或下班、去学校活动、志愿活动或体育活动，或者从那里回来。","p":"对。午夜到早上 5 点不能开车。"},"vi":{"q":"Ở Maryland, người lái có bằng lái tạm thời dưới 18 tuổi không được lái xe mà không có người giám sát trong những giờ nào?","o":["Từ nửa đêm đến 5:00 sáng","Từ 9:00 tối đến 6:00 sáng","Từ 10:00 tối đến 5:00 sáng","Không có giới hạn ban đêm"],"h1":"Giới hạn bắt đầu ngay đầu một ngày mới.","h2":"Ở Maryland, người lái có bằng lái tạm thời dưới 18 tuổi không được lái xe từ nửa đêm đến 5:00 sáng mà không có người giám sát, trừ khi đi làm hoặc về, đi hoặc về từ hoạt động của trường, chương trình tình nguyện hoặc thể thao.","p":"Đúng. Từ nửa đêm đến 5 giờ sáng thì không được lái."},"tl":{"q":"Sa Maryland, sa anong mga oras hindi puwedeng magmaneho nang walang nagbabantay ang provisional driver na wala pang 18?","o":["Hatinggabi hanggang 5:00 a.m.","9:00 p.m. hanggang 6:00 a.m.","10:00 p.m. hanggang 5:00 a.m.","Walang limitasyon sa gabi"],"h1":"Nagsisimula ang limitasyon sa mismong simula ng bagong araw.","h2":"Sa Maryland, hindi puwedeng magmaneho ang provisional driver na wala pang 18 mula hatinggabi hanggang 5:00 ng umaga nang walang nagbabantay, maliban kung papunta o pauwi sa trabaho, gawain sa paaralan, volunteer program o sports.","p":"Tama. Bawal ang hatinggabi hanggang 5 a.m."},"ar":{"q":"في Maryland، في أي ساعات لا يجوز للسائق صاحب الرخصة المؤقتة الذي عمره أقل من 18 سنة أن يقود بدون سائق مشرف؟","o":["من منتصف الليل إلى 5:00 صباحًا","من 9:00 مساءً إلى 6:00 صباحًا","من 10:00 مساءً إلى 5:00 صباحًا","لا يوجد حدّ ليلي"],"h1":"الحدّ يبدأ في أول لحظة من يوم جديد.","h2":"في Maryland لا يجوز للسائق صاحب الرخصة المؤقتة الذي عمره أقل من 18 سنة أن يقود بين منتصف الليل و5:00 صباحًا بدون سائق مشرف، إلا إذا كان ذاهبًا إلى العمل أو أنشطة المدرسة أو برامج التطوع أو الرياضة، أو عائدًا منها.","p":"صحيح. من منتصف الليل إلى 5 صباحًا ممنوع."},"ref":{"doc":"MD","page":47}},{"id":"md-013","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, for how long may a provisional driver under 18 not carry passengers under 18 who are not immediate family, without a supervising driver?","o":["The first 30 days","The first 151 days","The first year","Until age 21"],"h1":"It is about five months.","h2":"In Maryland, for the first 151 days, a provisional driver under 18 may not carry passengers under 18 other than immediate family unless a supervising driver is present.","p":"Right. The first 151 days, about five months."},"es":{"q":"En Maryland, ¿durante cuánto tiempo un conductor provisional menor de 18 años no puede llevar pasajeros menores de 18 que no sean familia inmediata, sin un supervisor?","o":["Los primeros 30 días","Los primeros 151 días","El primer año","Hasta los 21 años"],"h1":"Son unos cinco meses.","h2":"En Maryland, durante los primeros 151 días, un conductor provisional menor de 18 años no puede llevar pasajeros menores de 18 que no sean familia inmediata, salvo que vaya un supervisor.","p":"Correcto. Los primeros 151 días, unos cinco meses."},"zh":{"q":"在 Maryland，18 岁以下持过渡驾照的司机，在没有陪同司机时，多久之内不能载不是直系亲属、18 岁以下的乘客？","o":["头 30 天","头 151 天","头一年","到 21 岁为止"],"h1":"大约是五个月。","h2":"在 Maryland，头 151 天里，18 岁以下持过渡驾照的司机不能载直系亲属以外、18 岁以下的乘客，除非有陪同的司机在车上。","p":"对。头 151 天，大约五个月。"},"vi":{"q":"Ở Maryland, trong bao lâu người lái có bằng lái tạm thời dưới 18 tuổi không được chở hành khách dưới 18 tuổi không phải người thân trong gia đình, khi không có người giám sát?","o":["30 ngày đầu tiên","151 ngày đầu tiên","Năm đầu tiên","Cho đến 21 tuổi"],"h1":"Khoảng năm tháng.","h2":"Ở Maryland, trong 151 ngày đầu tiên, người lái có bằng lái tạm thời dưới 18 tuổi không được chở hành khách dưới 18 tuổi, trừ người thân trong gia đình, nếu không có người giám sát.","p":"Đúng. 151 ngày đầu tiên, khoảng năm tháng."},"tl":{"q":"Sa Maryland, gaano katagal hindi puwedeng magsakay ang provisional driver na wala pang 18 ng mga pasaherong wala pang 18 na hindi malapit na kapamilya, nang walang nagbabantay?","o":["Unang 30 araw","Unang 151 araw","Unang taon","Hanggang edad 21"],"h1":"Mga limang buwan ito.","h2":"Sa Maryland, sa unang 151 araw, hindi puwedeng magsakay ang provisional driver na wala pang 18 ng mga pasaherong wala pang 18 maliban sa malapit na kapamilya, kung walang nagbabantay.","p":"Tama. Ang unang 151 araw, mga limang buwan."},"ar":{"q":"في Maryland، لأي مدة لا يجوز للسائق صاحب الرخصة المؤقتة الذي عمره أقل من 18 سنة أن ينقل ركّابًا أعمارهم أقل من 18 سنة ليسوا من العائلة القريبة، بدون سائق مشرف؟","o":["أول 30 يومًا","أول 151 يومًا","السنة الأولى","حتى عمر 21 سنة"],"h1":"هي حوالي خمسة أشهر.","h2":"في Maryland، خلال أول 151 يومًا، لا يجوز للسائق صاحب الرخصة المؤقتة الذي عمره أقل من 18 سنة أن ينقل ركّابًا أعمارهم أقل من 18 سنة غير العائلة القريبة إلا بوجود سائق مشرف.","p":"صحيح. أول 151 يومًا، حوالي خمسة أشهر."},"ref":{"doc":"MD","page":47}},{"id":"md-014","scope":"MD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maryland, how much alcohol may a driver under 21 have in the blood while driving?","o":["Up to 0.08","Up to 0.05","None at all","Up to 0.10"],"h1":"People under 21 may not drink alcohol at all.","h2":"In Maryland, a driver under 21 may not drive with any alcohol in the blood.","p":"Right. Under 21, the limit is zero."},"es":{"q":"En Maryland, ¿cuánto alcohol puede tener en la sangre un conductor menor de 21 años mientras maneja?","o":["Hasta 0.08","Hasta 0.05","Nada","Hasta 0.10"],"h1":"Las personas menores de 21 años no pueden tomar nada de alcohol.","h2":"En Maryland, un conductor menor de 21 años no puede manejar con nada de alcohol en la sangre.","p":"Correcto. Si es menor de 21 años, el límite es cero."},"zh":{"q":"在 Maryland，21 岁以下的司机开车时血液里可以有多少酒精？","o":["最多 0.08","最多 0.05","一点都不可以","最多 0.10"],"h1":"21 岁以下的人完全不能喝酒。","h2":"在 Maryland，21 岁以下的司机血液里有任何酒精都不能开车。","p":"对。21 岁以下，上限是零。"},"vi":{"q":"Ở Maryland, người lái dưới 21 tuổi được có bao nhiêu cồn trong máu khi lái xe?","o":["Tối đa 0.08","Tối đa 0.05","Hoàn toàn không có","Tối đa 0.10"],"h1":"Người dưới 21 tuổi hoàn toàn không được uống rượu bia.","h2":"Ở Maryland, người lái dưới 21 tuổi không được lái xe khi có bất kỳ chút cồn nào trong máu.","p":"Đúng. Dưới 21 tuổi, giới hạn là không."},"tl":{"q":"Sa Maryland, gaano karaming alak ang puwedeng nasa dugo ng driver na wala pang 21 habang nagmamaneho?","o":["Hanggang 0.08","Hanggang 0.05","Wala talaga","Hanggang 0.10"],"h1":"Hindi puwedeng uminom ng alak ang mga wala pang 21.","h2":"Sa Maryland, hindi puwedeng magmaneho ang driver na wala pang 21 kung may kahit kaunting alak sa dugo.","p":"Tama. Para sa wala pang 21, zero ang limitasyon."},"ar":{"q":"في Maryland، كم من الكحول يجوز أن يكون في دم السائق الذي عمره أقل من 21 سنة أثناء القيادة؟","o":["حتى 0.08","حتى 0.05","لا شيء أبدًا","حتى 0.10"],"h1":"من عمرهم أقل من 21 سنة لا يجوز لهم شرب الكحول أبدًا.","h2":"في Maryland لا يجوز للسائق الذي عمره أقل من 21 سنة أن يقود وفي دمه أي كمية من الكحول.","p":"صحيح. أقل من 21 سنة، الحدّ هو صفر."},"ref":{"doc":"MD","page":33}},{"id":"md-015","scope":"MD","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Maryland, which stopped vehicles does the Move Over law cover?","o":["Only police cars","Only ambulances and fire trucks","Only tow trucks","Any stopped vehicle showing hazard lights, flares or cones"],"h1":"The law covers more than emergency vehicles.","h2":"In Maryland, you must move over, or slow down if you cannot, for any stopped vehicle showing hazard lights, road flares or traffic cones.","p":"Right. Any stopped vehicle with warning signals."},"es":{"q":"En Maryland, ¿qué vehículos detenidos cubre la ley Move Over (cámbiese de carril)?","o":["Solo patrullas de policía","Solo ambulancias y bomberos","Solo grúas","Cualquier vehículo detenido con luces intermitentes, bengalas o conos"],"h1":"La ley cubre más que los vehículos de emergencia.","h2":"En Maryland, usted debe cambiarse de carril, o bajar la velocidad si no puede, ante cualquier vehículo detenido con luces de emergencia, bengalas o conos.","p":"Correcto. Cualquier vehículo detenido con señales de advertencia."},"zh":{"q":"在 Maryland，Move Over 法保护哪些停着的车辆？","o":["只有警车","只有救护车和消防车","只有拖车","任何开着双闪灯、摆着照明弹或锥形路标的停着的车辆"],"h1":"这条法律保护的不只是急救车辆。","h2":"在 Maryland，遇到任何开着双闪灯、摆着道路照明弹或交通锥的停着的车辆，你都必须换道让开，如果不能换道就要减速。","p":"对。任何有警示信号、停着的车辆。"},"vi":{"q":"Ở Maryland, luật Tránh Sang Làn Khác (Move Over law) áp dụng cho những xe đang dừng nào?","o":["Chỉ xe cảnh sát","Chỉ xe cứu thương và xe cứu hỏa","Chỉ xe kéo","Bất kỳ xe đang dừng nào bật đèn cảnh báo, đặt pháo sáng hoặc cọc nón giao thông"],"h1":"Luật này áp dụng cho nhiều hơn xe khẩn cấp.","h2":"Ở Maryland, bạn phải tránh sang làn khác, hoặc chạy chậm lại nếu không thể tránh, khi gặp bất kỳ xe đang dừng nào bật đèn cảnh báo, đặt pháo sáng hoặc cọc nón giao thông.","p":"Đúng. Bất kỳ xe đang dừng nào có tín hiệu cảnh báo."},"tl":{"q":"Sa Maryland, aling mga nakahintong sasakyan ang sakop ng Move Over law?","o":["Mga sasakyan lang ng pulis","Mga ambulansya at trak ng bumbero lang","Mga tow truck lang","Kahit anong nakahintong sasakyan na may hazard lights, flares o cones"],"h1":"Sakop ng batas ang higit pa sa mga emergency vehicle.","h2":"Sa Maryland, dapat kang lumipat ng lane, o bumagal kung hindi ka makalipat, para sa kahit anong nakahintong sasakyan na may hazard lights, road flares o traffic cones.","p":"Tama. Kahit anong nakahintong sasakyan na may babalang senyas."},"ar":{"q":"في Maryland، ما المركبات المتوقفة التي يشملها قانون الابتعاد (Move Over law)؟","o":["سيارات الشرطة فقط","سيارات الإسعاف والإطفاء فقط","شاحنات السحب فقط","أي مركبة متوقفة تُظهر أضواء التحذير أو مشاعل الطريق أو أقماع المرور"],"h1":"القانون يشمل أكثر من مركبات الطوارئ.","h2":"في Maryland يجب أن تنتقل إلى مسار آخر، أو تخفّف السرعة إذا لم تستطع، عند أي مركبة متوقفة تُظهر أضواء التحذير أو مشاعل الطريق أو أقماع المرور.","p":"صحيح. أي مركبة متوقفة عليها إشارات تحذير."},"ref":{"doc":"MD","page":45}},{"id":"md-016","scope":"MD","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Maryland, a school bus stops with red lights flashing on a road split by a physical barrier. Who must stop?","o":["Traffic on the same side of the barrier as the bus","Traffic on both sides of the barrier","Only traffic on the other side of the barrier","No one, because of the barrier"],"h1":"Traffic on the far side of the barrier keeps going.","h2":"In Maryland, on a road divided by a physical barrier, traffic on the bus's side must stop, and traffic on the other side does not stop.","p":"Right. Only traffic on the bus's side of the barrier stops."},"es":{"q":"En Maryland, un autobús escolar se detiene con las luces rojas intermitentes en una carretera dividida por una barrera física. ¿Quién debe detenerse?","o":["El tráfico del mismo lado de la barrera que el autobús","El tráfico de ambos lados de la barrera","Solo el tráfico del otro lado de la barrera","Nadie, por la barrera"],"h1":"El tráfico del otro lado de la barrera sigue su camino.","h2":"En Maryland, en una carretera dividida por una barrera física, el tráfico del lado del autobús debe detenerse, y el tráfico del otro lado no se detiene.","p":"Correcto. Solo se detiene el tráfico del lado del autobús."},"zh":{"q":"在 Maryland，一辆校车在被实体隔离墩分开的道路上闪着红灯停下。谁必须停车？","o":["和校车在隔离墩同一边的车","隔离墩两边的车","只有隔离墩另一边的车","没有人，因为有隔离墩"],"h1":"隔离墩远的那一边的车可以继续开。","h2":"在 Maryland，在被实体隔离墩分开的道路上，校车那一边的车必须停车，另一边的车不用停。","p":"对。只有隔离墩校车那一边的车要停。"},"vi":{"q":"Ở Maryland, một xe buýt trường học dừng lại và nháy đèn đỏ trên con đường được chia đôi bằng dải phân cách cứng. Ai phải dừng lại?","o":["Xe cùng phía dải phân cách với xe buýt","Xe ở cả hai phía dải phân cách","Chỉ xe ở phía bên kia dải phân cách","Không ai cả, vì có dải phân cách"],"h1":"Xe ở phía bên kia dải phân cách tiếp tục đi.","h2":"Ở Maryland, trên con đường có dải phân cách cứng, xe cùng phía với xe buýt phải dừng lại, còn xe ở phía bên kia không cần dừng.","p":"Đúng. Chỉ xe cùng phía dải phân cách với xe buýt phải dừng."},"tl":{"q":"Sa Maryland, huminto ang school bus na kumikislap ang pulang ilaw sa daang hinati ng pisikal na harang. Sino ang dapat huminto?","o":["Ang mga sasakyan sa parehong panig ng harang kung nasaan ang bus","Ang mga sasakyan sa magkabilang panig ng harang","Ang mga sasakyan lang sa kabilang panig ng harang","Wala, dahil sa harang"],"h1":"Tuloy ang mga sasakyan sa kabilang panig ng harang.","h2":"Sa Maryland, sa daang hinati ng pisikal na harang, dapat huminto ang mga sasakyan sa panig ng bus, at hindi humihinto ang mga sasakyan sa kabilang panig.","p":"Tama. Ang mga sasakyan lang sa panig ng bus ang humihinto."},"ar":{"q":"في Maryland، توقفت حافلة مدرسية وأضواؤها الحمراء تومض على طريق مقسوم بحاجز مادي. من يجب أن يتوقف؟","o":["المركبات في نفس جهة الحاجز التي فيها الحافلة","المركبات في جهتي الحاجز","المركبات في الجهة الأخرى من الحاجز فقط","لا أحد، بسبب الحاجز"],"h1":"المركبات في الجهة البعيدة من الحاجز تستمر في السير.","h2":"في Maryland، على طريق مقسوم بحاجز مادي، يجب أن تتوقف المركبات في جهة الحافلة، ولا تتوقف المركبات في الجهة الأخرى.","p":"صحيح. تتوقف فقط المركبات في جهة الحافلة من الحاجز."},"ref":{"doc":"MD","page":39}},{"id":"md-017","scope":"MD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maryland, may an adult driver hold a cell phone to talk while driving?","o":["Yes, at any time","No, a hands-free device is required","Yes, but only on local streets","Yes, if driving under 30 mph"],"h1":"Your hands should stay on the wheel.","h2":"In Maryland, an adult driver may not hold a cell phone to talk while driving and must use a hands-free device, except to call 911.","p":"Right. Adults in Maryland must go hands-free."},"es":{"q":"En Maryland, ¿puede un conductor adulto sostener el celular para hablar mientras maneja?","o":["Sí, en cualquier momento","No, se requiere un dispositivo de manos libres","Sí, pero solo en calles locales","Sí, si va a menos de 30 mph"],"h1":"Sus manos deben quedarse en el volante.","h2":"En Maryland, un conductor adulto no puede sostener el celular para hablar mientras maneja y debe usar manos libres, excepto para llamar al 911.","p":"Correcto. Los adultos en Maryland deben usar manos libres."},"zh":{"q":"在 Maryland，成年司机开车时可以手拿手机通话吗？","o":["可以，任何时候都可以","不可以，必须用免提设备","可以，但只能在当地街道上","可以，只要车速低于 30 mph"],"h1":"你的手应该一直放在方向盘上。","h2":"在 Maryland，成年司机开车时不能手拿手机通话，必须用免提设备，打 911 除外。","p":"对。Maryland 的成年人必须用免提。"},"vi":{"q":"Ở Maryland, người lái trưởng thành có được cầm điện thoại để nói chuyện khi đang lái xe không?","o":["Có, bất cứ lúc nào","Không, phải dùng thiết bị rảnh tay","Có, nhưng chỉ trên đường trong khu vực","Có, nếu lái dưới 30 mph"],"h1":"Tay bạn nên giữ trên vô lăng.","h2":"Ở Maryland, người lái trưởng thành không được cầm điện thoại để nói chuyện khi lái xe và phải dùng thiết bị rảnh tay, trừ khi gọi 911.","p":"Đúng. Ở Maryland, người lớn phải dùng rảnh tay."},"tl":{"q":"Sa Maryland, puwede bang hawakan ng adultong driver ang cell phone para makipag-usap habang nagmamaneho?","o":["Oo, kahit kailan","Hindi, kailangan ng hands-free device","Oo, pero sa mga lokal na kalye lang","Oo, kung wala pang 30 mph ang takbo"],"h1":"Dapat nasa manibela ang mga kamay mo.","h2":"Sa Maryland, hindi puwedeng hawakan ng adultong driver ang cell phone para makipag-usap habang nagmamaneho at dapat gumamit ng hands-free device, maliban sa pagtawag sa 911.","p":"Tama. Dapat hands-free ang mga adulto sa Maryland."},"ar":{"q":"في Maryland، هل يجوز للسائق البالغ أن يمسك الهاتف المحمول بيده ليتكلم أثناء القيادة؟","o":["نعم، في أي وقت","لا، يجب استعمال جهاز بدون استعمال اليدين","نعم، ولكن في الشوارع المحلية فقط","نعم، إذا كانت السرعة أقل من 30 mph"],"h1":"يجب أن تبقى يداك على المقود.","h2":"في Maryland لا يجوز للسائق البالغ أن يمسك الهاتف المحمول بيده ليتكلم أثناء القيادة، ويجب أن يستعمل جهازًا بدون استعمال اليدين، إلا للاتصال بـ911.","p":"صحيح. البالغون في Maryland يجب أن يتكلموا بدون استعمال اليدين."},"ref":{"doc":"MD","page":35}},{"id":"md-018","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, how long must you hold a provisional license before you can get a full driver's license?","o":["6 months","12 months","18 months","24 months"],"h1":"It is longer than one year.","h2":"In Maryland, you must hold a provisional license for at least 18 months before you can get a full driver's license.","p":"Right. The provisional stage lasts at least 18 months."},"es":{"q":"En Maryland, ¿cuánto tiempo debe tener una licencia provisional antes de obtener una licencia de conducir completa?","o":["6 meses","12 meses","18 meses","24 meses"],"h1":"Es más de un año.","h2":"En Maryland, debe tener una licencia provisional por lo menos 18 meses antes de obtener una licencia de conducir completa.","p":"Correcto. La etapa provisional dura por lo menos 18 meses."},"zh":{"q":"在 Maryland，必须持有过渡驾照（provisional license）多久，才能拿到正式驾照？","o":["6 个月","12 个月","18 个月","24 个月"],"h1":"比一年更长。","h2":"在 Maryland，你必须持有过渡驾照至少 18 个月，才能拿到正式驾照。","p":"对。过渡阶段至少 18 个月。"},"vi":{"q":"Ở Maryland, bạn phải giữ bằng lái tạm thời (provisional license) bao lâu trước khi lấy bằng lái chính thức?","o":["6 tháng","12 tháng","18 tháng","24 tháng"],"h1":"Lâu hơn một năm.","h2":"Ở Maryland, bạn phải giữ bằng lái tạm thời ít nhất 18 tháng trước khi lấy bằng lái chính thức.","p":"Đúng. Giai đoạn bằng lái tạm thời kéo dài ít nhất 18 tháng."},"tl":{"q":"Sa Maryland, gaano katagal mo dapat hawak ang provisional license bago ka makakuha ng buong driver's license?","o":["6 na buwan","12 buwan","18 buwan","24 na buwan"],"h1":"Mas matagal ito sa isang taon.","h2":"Sa Maryland, dapat mong hawak ang provisional license nang hindi bababa sa 18 buwan bago ka makakuha ng buong driver's license.","p":"Tama. Tumatagal nang hindi bababa sa 18 buwan ang provisional na yugto."},"ar":{"q":"في Maryland، كم يجب أن تحتفظ بالرخصة المؤقتة (provisional license) قبل أن تحصل على رخصة قيادة كاملة؟","o":["6 أشهر","12 شهرًا","18 شهرًا","24 شهرًا"],"h1":"المدة أطول من سنة واحدة.","h2":"في Maryland يجب أن تحتفظ بالرخصة المؤقتة 18 شهرًا على الأقل قبل أن تحصل على رخصة قيادة كاملة.","p":"صحيح. مرحلة الرخصة المؤقتة تستمر 18 شهرًا على الأقل."},"ref":{"doc":"MD","page":10}},{"id":"md-019","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, how long is a Type 1 learner's permit valid?","o":["Up to 2 years","Up to 6 months","Up to 1 year","Up to 5 years"],"h1":"It gives you plenty of time to practice.","h2":"In Maryland, a Type 1 learner's permit is valid for up to 2 years.","p":"Right. The learner's permit lasts up to 2 years."},"es":{"q":"En Maryland, ¿por cuánto tiempo es válido un permiso de aprendizaje Tipo 1?","o":["Hasta 2 años","Hasta 6 meses","Hasta 1 año","Hasta 5 años"],"h1":"Le da bastante tiempo para practicar.","h2":"En Maryland, un permiso de aprendizaje Tipo 1 es válido por hasta 2 años.","p":"Correcto. El permiso de aprendizaje dura hasta 2 años."},"zh":{"q":"在 Maryland，Type 1 学习驾照（learner's permit）的有效期是多久？","o":["最多 2 年","最多 6 个月","最多 1 年","最多 5 年"],"h1":"它给你足够的时间练习。","h2":"在 Maryland，Type 1 学习驾照的有效期最多 2 年。","p":"对。学习驾照最多有效 2 年。"},"vi":{"q":"Ở Maryland, giấy phép tập lái Type 1 (learner's permit) có hiệu lực bao lâu?","o":["Tối đa 2 năm","Tối đa 6 tháng","Tối đa 1 năm","Tối đa 5 năm"],"h1":"Nó cho bạn nhiều thời gian để tập.","h2":"Ở Maryland, giấy phép tập lái Type 1 có hiệu lực tối đa 2 năm.","p":"Đúng. Giấy phép tập lái có hiệu lực tối đa 2 năm."},"tl":{"q":"Sa Maryland, gaano katagal may bisa ang Type 1 learner's permit?","o":["Hanggang 2 taon","Hanggang 6 na buwan","Hanggang 1 taon","Hanggang 5 taon"],"h1":"Binibigyan ka nito ng maraming oras para magsanay.","h2":"Sa Maryland, may bisa ang Type 1 learner's permit nang hanggang 2 taon.","p":"Tama. May bisa ang learner's permit nang hanggang 2 taon."},"ar":{"q":"في Maryland، ما مدة صلاحية تصريح التعلّم من النوع Type 1 (learner's permit)؟","o":["حتى سنتين (2)","حتى 6 أشهر","حتى سنة واحدة (1)","حتى 5 سنوات"],"h1":"يعطيك وقتًا كافيًا للتدرّب.","h2":"في Maryland يكون تصريح التعلّم من النوع Type 1 صالحًا لمدة تصل إلى سنتين (2).","p":"صحيح. تصريح التعلّم صالح حتى سنتين (2)."},"ref":{"doc":"MD","page":9}},{"id":"md-020","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maryland, how much time do you have to finish the 25-question knowledge test?","o":["10 minutes","45 minutes","1 hour","20 minutes"],"h1":"It is less than half an hour.","h2":"In Maryland, you have 20 minutes to finish the 25-question knowledge test.","p":"Right. You get 20 minutes for the test."},"es":{"q":"En Maryland, ¿cuánto tiempo tiene para terminar el examen de conocimientos de 25 preguntas?","o":["10 minutos","45 minutos","1 hora","20 minutos"],"h1":"Es menos de media hora.","h2":"En Maryland, tiene 20 minutos para terminar el examen de conocimientos de 25 preguntas.","p":"Correcto. Tiene 20 minutos para el examen."},"zh":{"q":"在 Maryland，完成 25 道题的笔试有多少时间？","o":["10 分钟","45 分钟","1 小时","20 分钟"],"h1":"不到半小时。","h2":"在 Maryland，你有 20 分钟完成 25 道题的笔试。","p":"对。笔试有 20 分钟。"},"vi":{"q":"Ở Maryland, bạn có bao nhiêu thời gian để làm xong bài thi kiến thức 25 câu?","o":["10 phút","45 phút","1 giờ","20 phút"],"h1":"Ít hơn nửa giờ.","h2":"Ở Maryland, bạn có 20 phút để làm xong bài thi kiến thức 25 câu.","p":"Đúng. Bạn có 20 phút để làm bài thi."},"tl":{"q":"Sa Maryland, gaano karaming oras ang mayroon ka para tapusin ang knowledge test na may 25 tanong?","o":["10 minuto","45 minuto","1 oras","20 minuto"],"h1":"Mas maikli ito sa kalahating oras.","h2":"Sa Maryland, mayroon kang 20 minuto para tapusin ang knowledge test na may 25 tanong.","p":"Tama. May 20 minuto ka para sa test."},"ar":{"q":"في Maryland، كم من الوقت لديك لإنهاء اختبار المعرفة المكوّن من 25 سؤالًا؟","o":["10 دقائق","45 دقيقة","ساعة واحدة (1)","20 دقيقة"],"h1":"أقل من نصف ساعة.","h2":"في Maryland لديك 20 دقيقة لإنهاء اختبار المعرفة المكوّن من 25 سؤالًا.","p":"صحيح. لديك 20 دقيقة للاختبار."},"ref":{"doc":"MD","page":7}},{"id":"md-021","scope":"MD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maryland, it is raining and you turn on your windshield wipers. What must you also turn on?","o":["Your hazard lights","Your headlights","Your high beams","Your interior lights"],"h1":"Other drivers need to see you in bad weather.","h2":"In Maryland, the law says you must turn on your headlights when you use your windshield wipers in bad weather.","p":"Right. Wipers on means headlights on."},"es":{"q":"En Maryland, está lloviendo y usted enciende los limpiaparabrisas. ¿Qué más debe encender?","o":["Las luces de emergencia","Los faros delanteros","Las luces altas","Las luces interiores"],"h1":"Los demás conductores necesitan verlo con mal tiempo.","h2":"En Maryland, la ley dice que debe encender los faros delanteros cuando usa los limpiaparabrisas con mal tiempo.","p":"Correcto. Si usa los limpiaparabrisas, encienda los faros."},"zh":{"q":"在 Maryland，下雨时你打开了雨刷。你还必须打开什么？","o":["危险警示灯","大灯","远光灯","车内灯"],"h1":"天气不好时，其他司机需要看到你。","h2":"在 Maryland，法律规定，天气不好使用雨刷时，你必须打开大灯。","p":"对。开雨刷，就要开大灯。"},"vi":{"q":"Ở Maryland, trời đang mưa và bạn bật cần gạt nước. Bạn cũng phải bật gì?","o":["Đèn báo nguy hiểm","Đèn pha","Đèn chiếu xa","Đèn trong xe"],"h1":"Người lái khác cần thấy bạn khi thời tiết xấu.","h2":"Ở Maryland, luật nói rằng bạn phải bật đèn pha khi dùng cần gạt nước lúc thời tiết xấu.","p":"Đúng. Bật cần gạt nước thì bật đèn pha."},"tl":{"q":"Sa Maryland, umuulan at binuksan mo ang windshield wipers. Ano pa ang dapat mong buksan?","o":["Ang hazard lights mo","Ang headlights mo","Ang high beams mo","Ang mga ilaw sa loob ng sasakyan"],"h1":"Kailangan kang makita ng ibang driver kapag masama ang panahon.","h2":"Sa Maryland, sinasabi ng batas na dapat mong buksan ang headlights kapag gumagamit ka ng windshield wipers sa masamang panahon.","p":"Tama. Kapag bukas ang wipers, bukas din ang headlights."},"ar":{"q":"في Maryland، الجو ممطر وشغّلت ماسحات الزجاج الأمامي. ماذا يجب أن تشغّل أيضًا؟","o":["أضواء التحذير (الطوارئ)","المصابيح الأمامية","الأضواء العالية","أضواء داخل السيارة"],"h1":"يحتاج السائقون الآخرون إلى رؤيتك في الطقس السيئ.","h2":"في Maryland يقول القانون إنه يجب أن تشغّل المصابيح الأمامية عندما تستخدم ماسحات الزجاج في الطقس السيئ.","p":"صحيح. إذا شغّلت الماسحات فشغّل المصابيح الأمامية."},"ref":{"doc":"MD","page":27}},{"id":"md-022","scope":"MD","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Maryland, you must turn on your headlights when you cannot clearly see how far ahead?","o":["200 feet","500 feet","1,000 feet","2,000 feet"],"h1":"It is a long distance, about three football fields.","h2":"In Maryland, you must turn on your headlights whenever there is not enough light to see clearly at least 1,000 feet ahead.","p":"Right. If you cannot see 1,000 feet ahead, use your headlights."},"es":{"q":"En Maryland, debe encender los faros si no puede ver claramente hasta cierta distancia hacia adelante. ¿Cuál es esa distancia?","o":["200 pies","500 pies","1,000 pies","2,000 pies"],"h1":"Es una distancia larga, como tres campos de fútbol americano.","h2":"En Maryland, debe encender los faros siempre que no haya luz suficiente para ver claramente por lo menos 1,000 pies hacia adelante.","p":"Correcto. Si no puede ver 1,000 pies hacia adelante, use los faros."},"zh":{"q":"在 Maryland，当你看不清前方多远时，必须打开大灯？","o":["200 英尺","500 英尺","1,000 英尺","2,000 英尺"],"h1":"这是很长的距离，大约三个橄榄球场。","h2":"在 Maryland，只要光线不够，看不清前方至少 1,000 英尺，你就必须打开大灯。","p":"对。看不清前方 1,000 英尺，就要开大灯。"},"vi":{"q":"Ở Maryland, bạn phải bật đèn pha khi không thể nhìn rõ phía trước bao xa?","o":["200 feet","500 feet","1,000 feet","2,000 feet"],"h1":"Đó là một khoảng cách dài, khoảng ba sân bóng bầu dục.","h2":"Ở Maryland, bạn phải bật đèn pha bất cứ khi nào không đủ ánh sáng để nhìn rõ ít nhất 1,000 feet phía trước.","p":"Đúng. Nếu không thể nhìn thấy 1,000 feet phía trước, hãy bật đèn pha."},"tl":{"q":"Sa Maryland, dapat mong buksan ang headlights kapag hindi mo malinaw na makita ang daan hanggang gaano kalayo?","o":["200 talampakan","500 talampakan","1,000 talampakan","2,000 talampakan"],"h1":"Malayo ito, mga tatlong football field.","h2":"Sa Maryland, dapat mong buksan ang headlights tuwing kulang ang liwanag para malinaw na makita ang hindi bababa sa 1,000 talampakan sa unahan.","p":"Tama. Kung hindi mo makita ang 1,000 talampakan sa unahan, gamitin ang headlights."},"ar":{"q":"في Maryland، يجب أن تشغّل المصابيح الأمامية عندما لا تستطيع أن ترى بوضوح إلى أي مسافة أمامك؟","o":["200 قدم","500 قدم","1,000 قدم","2,000 قدم"],"h1":"إنها مسافة طويلة، نحو ثلاثة ملاعب كرة قدم أمريكية.","h2":"في Maryland يجب أن تشغّل المصابيح الأمامية كلما لم يكن الضوء كافيًا لترى بوضوح 1,000 قدم على الأقل أمامك.","p":"صحيح. إذا لم تستطع أن ترى 1,000 قدم أمامك فشغّل المصابيح الأمامية."},"ref":{"doc":"MD","page":27}},{"id":"md-023","scope":"MD","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Maryland, what is the penalty for breaking the Move Over law when no crash happens?","o":["A $110 fine and 1 point","A $50 fine and no points","A $500 fine and 5 points","A warning only"],"h1":"Points are added to your driving record.","h2":"In Maryland, breaking the Move Over law without causing a crash brings a $110 fine and 1 point on your license.","p":"Right. It is a $110 fine and 1 point."},"es":{"q":"En Maryland, ¿cuál es la multa por no cumplir la ley Move Over (moverse de carril) si no hay choque?","o":["Una multa de $110 y 1 punto","Una multa de $50 y ningún punto","Una multa de $500 y 5 puntos","Solo una advertencia"],"h1":"Se agregan puntos a su historial de manejo.","h2":"En Maryland, no cumplir la ley Move Over sin causar un choque trae una multa de $110 y 1 punto en su licencia.","p":"Correcto. Es una multa de $110 y 1 punto."},"zh":{"q":"在 Maryland，违反 Move Over 法但没有发生车祸，会受到什么处罚？","o":["罚款 $110，扣 1 分","罚款 $50，不扣分","罚款 $500，扣 5 分","只有警告"],"h1":"你的驾驶记录上会被记分。","h2":"在 Maryland，违反 Move Over 法但没有造成车祸，会被罚款 $110，并在驾照上记 1 分。","p":"对。罚款 $110，记 1 分。"},"vi":{"q":"Ở Maryland, hình phạt cho việc vi phạm luật Tránh Sang Làn Khác (Move Over law) khi không xảy ra tai nạn là gì?","o":["Phạt $110 và 1 điểm","Phạt $50 và không bị điểm","Phạt $500 và 5 điểm","Chỉ bị cảnh cáo"],"h1":"Điểm bị ghi vào hồ sơ lái xe của bạn.","h2":"Ở Maryland, vi phạm luật Tránh Sang Làn Khác mà không gây tai nạn sẽ bị phạt $110 và bị ghi 1 điểm vào bằng lái.","p":"Đúng. Phạt $110 và 1 điểm."},"tl":{"q":"Sa Maryland, ano ang parusa sa paglabag sa Move Over law kapag walang nangyaring banggaan?","o":["Multang $110 at 1 puntos","Multang $50 at walang puntos","Multang $500 at 5 puntos","Babala lang"],"h1":"Nadaragdagan ng mga puntos ang driving record mo.","h2":"Sa Maryland, ang paglabag sa Move Over law nang walang banggaan ay may multang $110 at 1 puntos sa lisensya mo.","p":"Tama. Multang $110 at 1 puntos ito."},"ar":{"q":"في Maryland، ما عقوبة مخالفة قانون الابتعاد (Move Over law) عندما لا يقع حادث؟","o":["غرامة $110 ونقطة واحدة (1)","غرامة $50 بدون نقاط","غرامة $500 و5 نقاط","إنذار فقط"],"h1":"تُضاف نقاط إلى سجل قيادتك.","h2":"في Maryland تؤدي مخالفة قانون الابتعاد بدون التسبب في حادث إلى غرامة $110 ونقطة واحدة (1) على رخصتك.","p":"صحيح. العقوبة غرامة $110 ونقطة واحدة (1)."},"ref":{"doc":"MD","page":45}},{"id":"md-024","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, a provisional driver under 18 is convicted of a second moving violation. What happens?","o":["Only a warning letter is sent","A 30-day suspension, then 90 days of driving only for work or school","The license is revoked for 5 years","A $25 fine and nothing else"],"h1":"The penalty grows with each offense.","h2":"In Maryland, a second moving violation for a provisional driver under 18 brings a 30-day suspension, followed by 90 days of driving only for work or school.","p":"Right. A second offense means a 30-day suspension and a 90-day work-or-school limit."},"es":{"q":"En Maryland, un conductor provisional menor de 18 años recibe una condena por una segunda infracción de tránsito. ¿Qué pasa?","o":["Solo se envía una carta de advertencia","Una suspensión de 30 días, luego 90 días de manejar solo para trabajo o escuela","La licencia se revoca por 5 años","Una multa de $25 y nada más"],"h1":"La pena aumenta con cada infracción.","h2":"En Maryland, una segunda infracción de tránsito de un conductor provisional menor de 18 años trae una suspensión de 30 días, seguida de 90 días de manejar solo para trabajo o escuela.","p":"Correcto. Una segunda infracción significa 30 días de suspensión y 90 días con límite de trabajo o escuela."},"zh":{"q":"在 Maryland，18 岁以下持过渡驾照的司机第二次因行驶违章被定罪。会发生什么？","o":["只会寄一封警告信","吊销驾照 30 天，然后 90 天只能为上班或上学开车","驾照被撤销 5 年","罚款 $25，没有别的"],"h1":"每次违规，处罚都会更重。","h2":"在 Maryland，18 岁以下持过渡驾照的司机第二次行驶违章，会被吊销驾照 30 天，之后 90 天只能为上班或上学开车。","p":"对。第二次违规是吊销 30 天，再加 90 天只能上班或上学开车。"},"vi":{"q":"Ở Maryland, người lái có bằng lái tạm thời dưới 18 tuổi bị kết tội vi phạm giao thông lần thứ hai. Điều gì xảy ra?","o":["Chỉ bị gửi thư cảnh cáo","Bị treo bằng 30 ngày, sau đó 90 ngày chỉ được lái xe để đi làm hoặc đi học","Bị thu hồi bằng lái 5 năm","Phạt $25 và không có gì khác"],"h1":"Hình phạt tăng lên với mỗi lần vi phạm.","h2":"Ở Maryland, người lái có bằng lái tạm thời dưới 18 tuổi vi phạm giao thông lần thứ hai sẽ bị treo bằng 30 ngày, sau đó 90 ngày chỉ được lái xe để đi làm hoặc đi học.","p":"Đúng. Vi phạm lần thứ hai là treo bằng 30 ngày và 90 ngày chỉ lái để đi làm hoặc đi học."},"tl":{"q":"Sa Maryland, nahatulan ang isang provisional driver na wala pang 18 sa ikalawang moving violation. Ano ang mangyayari?","o":["Padadalhan lang ng sulat ng babala","Suspensyon nang 30 araw, pagkatapos ay 90 araw na pagmamaneho para lang sa trabaho o paaralan","Babawiin ang lisensya nang 5 taon","Multang $25 at wala nang iba"],"h1":"Lumalaki ang parusa sa bawat paglabag.","h2":"Sa Maryland, ang ikalawang moving violation ng provisional driver na wala pang 18 ay may suspensyon nang 30 araw, at pagkatapos ay 90 araw na pagmamaneho para lang sa trabaho o paaralan.","p":"Tama. Ang ikalawang paglabag ay suspensyon nang 30 araw at 90 araw na limitasyon sa trabaho o paaralan."},"ar":{"q":"في Maryland، أُدين سائق صاحب رخصة مؤقتة عمره أقل من 18 سنة بمخالفة مرورية ثانية أثناء القيادة. ماذا يحدث؟","o":["تُرسل رسالة تحذير فقط","إيقاف الرخصة 30 يومًا، ثم 90 يومًا من القيادة للعمل أو المدرسة فقط","تُلغى الرخصة لمدة 5 سنوات","غرامة $25 ولا شيء غيرها"],"h1":"تزيد العقوبة مع كل مخالفة.","h2":"في Maryland تؤدي المخالفة المرورية الثانية لسائق صاحب رخصة مؤقتة عمره أقل من 18 سنة إلى إيقاف الرخصة 30 يومًا، ثم 90 يومًا من القيادة للعمل أو المدرسة فقط.","p":"صحيح. المخالفة الثانية تعني إيقافًا لمدة 30 يومًا، ثم 90 يومًا للعمل أو المدرسة فقط."},"ref":{"doc":"MD","page":49}},{"id":"md-025","scope":"MD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maryland, which children must ride in a child safety seat?","o":["Only children under 2","Only children under 4","Children under 12 who weigh under 100 pounds","Children under 8, unless they are 4 feet 9 inches or taller"],"h1":"Think of both age and height.","h2":"In Maryland, children under 8 must ride in a child safety seat, unless they are 4 feet 9 inches or taller.","p":"Right. Under 8 means a safety seat, unless the child is 4 feet 9 inches or taller."},"es":{"q":"En Maryland, ¿qué niños deben viajar en un asiento de seguridad para niños?","o":["Solo los menores de 2 años","Solo los menores de 4 años","Los menores de 12 años que pesan menos de 100 libras","Los menores de 8 años, a menos que midan 4 pies 9 pulgadas o más"],"h1":"Piense en la edad y en la estatura.","h2":"En Maryland, los niños menores de 8 años deben viajar en un asiento de seguridad, a menos que midan 4 pies 9 pulgadas o más.","p":"Correcto. Los menores de 8 años usan asiento de seguridad, a menos que midan 4 pies 9 pulgadas o más."},"zh":{"q":"在 Maryland，哪些孩子必须坐儿童安全座椅？","o":["只有 2 岁以下的孩子","只有 4 岁以下的孩子","12 岁以下、体重不到 100 磅的孩子","8 岁以下的孩子，除非身高达到 4 英尺 9 英寸或以上"],"h1":"同时想想年龄和身高。","h2":"在 Maryland，8 岁以下的孩子必须坐儿童安全座椅，除非身高达到 4 英尺 9 英寸或以上。","p":"对。8 岁以下要坐安全座椅，除非孩子身高达到 4 英尺 9 英寸或以上。"},"vi":{"q":"Ở Maryland, những trẻ em nào phải ngồi ghế an toàn cho trẻ em?","o":["Chỉ trẻ dưới 2 tuổi","Chỉ trẻ dưới 4 tuổi","Trẻ dưới 12 tuổi nặng dưới 100 pound","Trẻ dưới 8 tuổi, trừ khi cao từ 4 feet 9 inch trở lên"],"h1":"Hãy nghĩ đến cả tuổi và chiều cao.","h2":"Ở Maryland, trẻ dưới 8 tuổi phải ngồi ghế an toàn cho trẻ em, trừ khi cao từ 4 feet 9 inch trở lên.","p":"Đúng. Dưới 8 tuổi thì ngồi ghế an toàn, trừ khi trẻ cao từ 4 feet 9 inch trở lên."},"tl":{"q":"Sa Maryland, aling mga bata ang dapat nakaupo sa child safety seat?","o":["Mga batang wala pang 2 lang","Mga batang wala pang 4 lang","Mga batang wala pang 12 na wala pang 100 libra ang timbang","Mga batang wala pang 8, maliban kung 4 na talampakan at 9 na pulgada o mas matangkad sila"],"h1":"Isipin ang edad at ang taas.","h2":"Sa Maryland, dapat nakaupo sa child safety seat ang mga batang wala pang 8, maliban kung 4 na talampakan at 9 na pulgada o mas matangkad sila.","p":"Tama. Kapag wala pang 8, safety seat, maliban kung 4 na talampakan at 9 na pulgada o mas matangkad ang bata."},"ar":{"q":"في Maryland، أي الأطفال يجب أن يجلسوا في مقعد أمان للأطفال؟","o":["الأطفال الذين أعمارهم أقل من سنتين (2) فقط","الأطفال الذين أعمارهم أقل من 4 سنوات فقط","الأطفال الذين أعمارهم أقل من 12 سنة ووزنهم أقل من 100 رطل","الأطفال الذين أعمارهم أقل من 8 سنوات، إلا إذا كان طولهم 4 أقدام و9 بوصات أو أكثر"],"h1":"فكّر في العمر والطول معًا.","h2":"في Maryland يجب أن يجلس الأطفال الذين أعمارهم أقل من 8 سنوات في مقعد أمان للأطفال، إلا إذا كان طولهم 4 أقدام و9 بوصات أو أكثر.","p":"صحيح. أقل من 8 سنوات يعني مقعد أمان، إلا إذا كان طول الطفل 4 أقدام و9 بوصات أو أكثر."},"ref":{"doc":"MD","page":52}},{"id":"md-026","scope":"MD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maryland, what is the rule about earphones while driving?","o":["You may wear them in both ears at low volume","They are allowed only on highways","You may not wear them in both ears","They are allowed only for drivers over 21"],"h1":"You need to hear sirens and horns around you.","h2":"In Maryland, covering both ears with earphones, a headset or earplugs while driving is not allowed. Hearing aids are fine.","p":"Right. Never cover both ears while driving."},"es":{"q":"En Maryland, ¿cuál es la regla sobre los audífonos al manejar?","o":["Puede usarlos en ambos oídos a bajo volumen","Solo se permiten en las autopistas","No puede usarlos en ambos oídos","Solo se permiten a conductores mayores de 21 años"],"h1":"Necesita oír las sirenas y bocinas a su alrededor.","h2":"En Maryland, no se permite manejar con los dos oídos tapados por audífonos, auriculares o tapones. Los aparatos auditivos sí se permiten.","p":"Correcto. Nunca se tape ambos oídos al manejar."},"zh":{"q":"在 Maryland，开车时戴耳机有什么规定？","o":["音量小的话，两只耳朵都可以戴","只在高速公路上可以戴","两只耳朵不能都戴","只有 21 岁以上的司机可以戴"],"h1":"你需要听到周围的警笛声和喇叭声。","h2":"在 Maryland，开车时不可以用耳机、头戴式耳机或耳塞把两只耳朵都盖住。助听器可以戴。","p":"对。开车时绝不要把两只耳朵都盖住。"},"vi":{"q":"Ở Maryland, quy định về tai nghe khi lái xe là gì?","o":["Bạn có thể đeo ở cả hai tai nếu để âm lượng nhỏ","Chỉ được phép trên xa lộ","Bạn không được đeo ở cả hai tai","Chỉ được phép cho tài xế trên 21 tuổi"],"h1":"Bạn cần nghe được còi hụ và tiếng còi xe xung quanh.","h2":"Ở Maryland, không được che cả hai tai bằng tai nghe, headset hoặc nút bịt tai khi lái xe. Máy trợ thính thì được phép.","p":"Đúng. Không bao giờ che cả hai tai khi lái xe."},"tl":{"q":"Sa Maryland, ano ang patakaran tungkol sa earphones habang nagmamaneho?","o":["Puwede mong isuot sa dalawang tainga kung mahina ang volume","Pinapayagan lang sa mga highway","Hindi mo puwedeng isuot sa dalawang tainga","Pinapayagan lang sa mga driver na lampas 21"],"h1":"Kailangan mong marinig ang mga sirena at busina sa paligid mo.","h2":"Sa Maryland, hindi pinapayagang takpan ang dalawang tainga ng earphones, headset o earplugs habang nagmamaneho. Puwede ang hearing aids.","p":"Tama. Huwag kailanman takpan ang dalawang tainga habang nagmamaneho."},"ar":{"q":"في Maryland، ما القاعدة بخصوص سماعات الأذن أثناء القيادة؟","o":["يمكنك وضعها في الأذنين بصوت منخفض","مسموح بها على الطرق السريعة فقط","لا يُسمح لك بوضعها في الأذنين معًا","مسموح بها فقط للسائقين فوق 21 سنة"],"h1":"تحتاج أن تسمع صفارات الإنذار وأبواق السيارات حولك.","h2":"في Maryland، لا يُسمح بتغطية الأذنين معًا بسماعات أذن أو سماعة رأس أو سدادات أذن أثناء القيادة. أما أجهزة السمع فمسموح بها.","p":"صحيح. لا تغطِّ أذنيك الاثنتين أبدًا أثناء القيادة."},"ref":{"doc":"MD","page":53}},{"id":"md-027","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, what visual acuity do you need in each eye to qualify for a driver's license?","o":["At least 20/100","At least 20/40","At least 20/10","At least 20/200"],"h1":"Glasses or contact lenses may be used to reach it.","h2":"In Maryland, you need visual acuity of at least 20/40 in each eye, with glasses or contacts if needed, to qualify for a driver's license.","p":"Right. You need at least 20/40 in each eye."},"es":{"q":"En Maryland, ¿qué agudeza visual necesita en cada ojo para calificar para una licencia de conducir?","o":["Por lo menos 20/100","Por lo menos 20/40","Por lo menos 20/10","Por lo menos 20/200"],"h1":"Puede usar anteojos o lentes de contacto para lograrla.","h2":"En Maryland, usted necesita una agudeza visual de por lo menos 20/40 en cada ojo, con anteojos o lentes de contacto si hace falta, para calificar para una licencia de conducir.","p":"Correcto. Necesita por lo menos 20/40 en cada ojo."},"zh":{"q":"在 Maryland，每只眼睛的视力至少要达到多少，才能拿到驾照？","o":["至少 20/100","至少 20/40","至少 20/10","至少 20/200"],"h1":"可以戴眼镜或隐形眼镜来达到这个标准。","h2":"在 Maryland，每只眼睛的视力必须至少达到 20/40（需要时可以戴眼镜或隐形眼镜），才能拿到驾照。","p":"对。每只眼睛至少要 20/40。"},"vi":{"q":"Ở Maryland, mỗi mắt cần thị lực ít nhất bao nhiêu để được cấp bằng lái xe?","o":["Ít nhất 20/100","Ít nhất 20/40","Ít nhất 20/10","Ít nhất 20/200"],"h1":"Bạn có thể đeo kính hoặc kính áp tròng để đạt mức này.","h2":"Ở Maryland, mỗi mắt của bạn phải có thị lực ít nhất 20/40, có thể đeo kính hoặc kính áp tròng nếu cần, để được cấp bằng lái xe.","p":"Đúng. Mỗi mắt cần ít nhất 20/40."},"tl":{"q":"Sa Maryland, gaano kalinaw ang paningin na kailangan sa bawat mata para makakuha ng driver's license?","o":["Hindi bababa sa 20/100","Hindi bababa sa 20/40","Hindi bababa sa 20/10","Hindi bababa sa 20/200"],"h1":"Puwedeng gumamit ng salamin sa mata o contact lens para maabot ito.","h2":"Sa Maryland, kailangan mo ng paningin na hindi bababa sa 20/40 sa bawat mata, gamit ang salamin o contact lens kung kailangan, para makakuha ng driver's license.","p":"Tama. Kailangan ng hindi bababa sa 20/40 sa bawat mata."},"ar":{"q":"في Maryland، ما حدّة البصر التي تحتاجها في كل عين للحصول على رخصة القيادة؟","o":["20/100 على الأقل","20/40 على الأقل","20/10 على الأقل","20/200 على الأقل"],"h1":"يمكنك استخدام النظارات أو العدسات اللاصقة للوصول إليها.","h2":"في Maryland تحتاج إلى حدّة بصر 20/40 على الأقل في كل عين، مع النظارات أو العدسات اللاصقة إذا لزم الأمر، للحصول على رخصة القيادة.","p":"صحيح. تحتاج إلى 20/40 على الأقل في كل عين."},"ref":{"doc":"MD","page":7}},{"id":"md-028","scope":"MD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maryland, how much space must you leave between your vehicle and a bicycle when you pass it?","o":["At least 1 foot","At least 10 feet","At least 2 feet","At least 3 feet"],"h1":"Think of about one long step.","h2":"In Maryland, you must leave at least 3 feet between your vehicle and a bicycle when you pass it, even in a bike lane or on the shoulder.","p":"Right. Leave at least 3 feet."},"es":{"q":"En Maryland, ¿cuánto espacio debe dejar entre su vehículo y una bicicleta al pasarla?","o":["Por lo menos 1 pie","Por lo menos 10 pies","Por lo menos 2 pies","Por lo menos 3 pies"],"h1":"Piense en un paso largo.","h2":"En Maryland, usted debe dejar por lo menos 3 pies entre su vehículo y una bicicleta al pasarla, también en un carril para bicicletas o en el acotamiento.","p":"Correcto. Deje por lo menos 3 pies."},"zh":{"q":"在 Maryland，超过一辆自行车时，你的车和自行车之间必须留多少距离？","o":["至少 1 英尺","至少 10 英尺","至少 2 英尺","至少 3 英尺"],"h1":"大约是一大步的长度。","h2":"在 Maryland，超过自行车时，你的车和自行车之间必须至少留 3 英尺，即使自行车在自行车道或路肩上也一样。","p":"对。至少留 3 英尺。"},"vi":{"q":"Ở Maryland, khi vượt một xe đạp, bạn phải chừa khoảng cách bao nhiêu giữa xe của bạn và xe đạp?","o":["Ít nhất 1 foot","Ít nhất 10 feet","Ít nhất 2 feet","Ít nhất 3 feet"],"h1":"Hãy nghĩ đến khoảng một bước dài.","h2":"Ở Maryland, khi vượt xe đạp, bạn phải chừa ít nhất 3 feet giữa xe của bạn và xe đạp, kể cả khi xe đạp ở trong làn xe đạp hoặc trên lề đường.","p":"Đúng. Chừa ít nhất 3 feet."},"tl":{"q":"Sa Maryland, gaano kalaking espasyo ang dapat mong iwan sa pagitan ng sasakyan mo at ng bisikleta kapag inuunahan mo ito?","o":["Hindi bababa sa 1 talampakan","Hindi bababa sa 10 talampakan","Hindi bababa sa 2 talampakan","Hindi bababa sa 3 talampakan"],"h1":"Isipin ang mga isang mahabang hakbang.","h2":"Sa Maryland, dapat kang mag-iwan ng hindi bababa sa 3 talampakan sa pagitan ng sasakyan mo at ng bisikleta kapag inuunahan mo ito, kahit nasa bike lane o nasa gilid ng daan ito.","p":"Tama. Mag-iwan ng hindi bababa sa 3 talampakan."},"ar":{"q":"في Maryland، ما المسافة التي يجب أن تتركها بين سيارتك والدراجة الهوائية عندما تتجاوزها؟","o":["قدم واحدة (1) على الأقل","10 أقدام على الأقل","قدمان (2) على الأقل","3 أقدام على الأقل"],"h1":"فكّر في خطوة واحدة طويلة تقريبًا.","h2":"في Maryland يجب أن تترك 3 أقدام على الأقل بين سيارتك والدراجة الهوائية عندما تتجاوزها، حتى لو كانت في مسار الدراجات أو على كتف الطريق.","p":"صحيح. اترك 3 أقدام على الأقل."},"ref":{"doc":"MD","page":40}},{"id":"md-029","scope":"MD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maryland, you are using high beams at night. A car is coming toward you. When must you switch to low beams?","o":["At least 500 feet before you reach it","When it is 50 feet away","Only after it passes you","At least 2 miles before you reach it"],"h1":"It is the length of more than one football field.","h2":"In Maryland, you must switch to low beams at least 500 feet before you reach a vehicle coming toward you.","p":"Right. Switch at least 500 feet before it."},"es":{"q":"En Maryland, usted usa las luces altas de noche. Un carro viene hacia usted. ¿Cuándo debe cambiar a luces bajas?","o":["Por lo menos 500 pies antes de llegar a él","Cuando esté a 50 pies","Solo después de que le pase","Por lo menos 2 millas antes de llegar a él"],"h1":"Es más que el largo de una cancha de fútbol americano.","h2":"En Maryland, usted debe cambiar a luces bajas por lo menos 500 pies antes de llegar a un vehículo que viene de frente.","p":"Correcto. Cambie por lo menos 500 pies antes."},"zh":{"q":"在 Maryland，你晚上开着远光灯，有一辆车迎面开来。你必须在什么时候换成近光灯？","o":["在离它至少 500 英尺之前","在它离你 50 英尺时","只在它开过你之后","在离它至少 2 英里之前"],"h1":"这比一个橄榄球场还长。","h2":"在 Maryland，你必须在离迎面来车至少 500 英尺之前换成近光灯。","p":"对。至少在 500 英尺之前换灯。"},"vi":{"q":"Ở Maryland, bạn đang bật đèn pha (đèn chiếu xa) vào ban đêm. Có một xe đang chạy về phía bạn. Khi nào bạn phải chuyển sang đèn cốt (đèn chiếu gần)?","o":["Ít nhất 500 feet trước khi gặp xe đó","Khi xe đó cách 50 feet","Chỉ sau khi xe đó đã chạy qua","Ít nhất 2 dặm trước khi gặp xe đó"],"h1":"Khoảng cách này dài hơn một sân bóng bầu dục.","h2":"Ở Maryland, bạn phải chuyển sang đèn cốt ít nhất 500 feet trước khi gặp xe đang chạy về phía bạn.","p":"Đúng. Chuyển đèn ít nhất 500 feet trước khi gặp xe."},"tl":{"q":"Sa Maryland, gumagamit ka ng high beam sa gabi. May sasakyang paparating sa iyo. Kailan mo dapat ilipat sa low beam?","o":["Hindi bababa sa 500 talampakan bago mo ito marating","Kapag 50 talampakan na lang ang layo nito","Pagkatapos lang itong makalampas sa iyo","Hindi bababa sa 2 milya bago mo ito marating"],"h1":"Mas mahaba ito kaysa sa isang football field.","h2":"Sa Maryland, dapat kang lumipat sa low beam nang hindi bababa sa 500 talampakan bago mo marating ang sasakyang paparating sa iyo.","p":"Tama. Lumipat nang hindi bababa sa 500 talampakan bago ito."},"ar":{"q":"في Maryland، أنت تستخدم الأضواء العالية في الليل، وهناك سيارة قادمة نحوك. متى يجب أن تنتقل إلى الأضواء المنخفضة؟","o":["قبل الوصول إليها بـ 500 قدم على الأقل","عندما تكون على بعد 50 قدمًا","فقط بعد أن تتجاوزك","قبل الوصول إليها بميلين (2) على الأقل"],"h1":"هي أطول من ملعب كرة قدم أمريكية واحد.","h2":"في Maryland يجب أن تنتقل إلى الأضواء المنخفضة قبل الوصول إلى السيارة القادمة نحوك بـ 500 قدم على الأقل.","p":"صحيح. انتقل إلى الأضواء المنخفضة قبلها بـ 500 قدم على الأقل."},"ref":{"doc":"MD","page":27}},{"id":"md-030","scope":"MD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maryland, which of these counts as an open container of alcohol in the passenger area?","o":["A sealed bottle in the trunk","A closed case of soda","A six-pack with some cans missing or empty","An empty water bottle in a cup holder"],"h1":"Think about a package that has already been opened.","h2":"In Maryland, a six-pack with open, empty or missing cans or bottles can count as an open container, and it is illegal in the passenger area.","p":"Right. A six-pack with missing or empty cans can count as open."},"es":{"q":"En Maryland, ¿cuál de estos cuenta como un envase abierto de alcohol en el área de pasajeros?","o":["Una botella sellada en el maletero","Una caja cerrada de refrescos","Un paquete de seis con algunas latas que faltan o están vacías","Una botella de agua vacía en un portavasos"],"h1":"Piense en un paquete que ya se abrió.","h2":"En Maryland, un paquete de seis con latas o botellas abiertas, vacías o que faltan puede contar como un envase abierto, y es ilegal en el área de pasajeros.","p":"Correcto. Un paquete de seis con latas que faltan o vacías puede contar como abierto."},"zh":{"q":"在 Maryland，下面哪一种在乘客区里算是打开的酒类容器？","o":["后备箱里一瓶密封的酒","一箱没打开的汽水","一组六罐装，里面有的罐子不见了或是空的","杯架上一个空水瓶"],"h1":"想想已经被打开过的包装。","h2":"在 Maryland，一组六罐装里如果有打开、空的或不见了的罐子或瓶子，就可能算是打开的酒类容器，放在乘客区是违法的。","p":"对。少了罐子或有空罐的六罐装可能算是打开的容器。"},"vi":{"q":"Ở Maryland, vật nào sau đây được tính là đồ chứa rượu bia đã mở trong khu vực hành khách?","o":["Một chai còn niêm phong trong cốp xe","Một thùng nước ngọt còn đóng","Một lốc sáu lon bị thiếu lon hoặc có lon rỗng","Một chai nước rỗng trong chỗ để ly"],"h1":"Hãy nghĩ đến một gói hàng đã bị mở ra.","h2":"Ở Maryland, một lốc sáu lon có lon hoặc chai đã mở, rỗng hoặc bị thiếu có thể được tính là đồ chứa đã mở, và để nó trong khu vực hành khách là phạm luật.","p":"Đúng. Một lốc sáu lon bị thiếu lon hoặc có lon rỗng có thể được tính là đã mở."},"tl":{"q":"Sa Maryland, alin dito ang itinuturing na bukas na lalagyan ng alak sa bahagi ng mga pasahero?","o":["Isang selyadong bote sa trunk","Isang saradong kahon ng soda","Isang six-pack na may nawawala o walang lamang lata","Isang walang lamang bote ng tubig sa lalagyan ng baso"],"h1":"Isipin ang isang pakete na nabuksan na.","h2":"Sa Maryland, ang isang six-pack na may bukas, walang laman, o nawawalang lata o bote ay puwedeng ituring na bukas na lalagyan, at bawal ito sa bahagi ng mga pasahero.","p":"Tama. Ang six-pack na may nawawala o walang lamang lata ay puwedeng ituring na bukas."},"ar":{"q":"في Maryland، أيّ مما يلي يُعتبر وعاءً مفتوحًا للكحول في مكان الركّاب؟","o":["زجاجة مغلقة بإحكام في صندوق السيارة","صندوق مغلق من المشروبات الغازية","علبة من ست عبوات فيها عبوات ناقصة أو فارغة","زجاجة ماء فارغة في حامل الأكواب"],"h1":"فكّر في عبوة تم فتحها من قبل.","h2":"في Maryland يمكن أن تُعتبر علبة الست عبوات التي فيها عبوات أو زجاجات مفتوحة أو فارغة أو ناقصة وعاءً مفتوحًا، ووجودها في مكان الركّاب مخالف للقانون.","p":"صحيح. علبة الست عبوات التي فيها عبوات ناقصة أو فارغة يمكن أن تُعتبر مفتوحة."},"ref":{"doc":"MD","page":33}},{"id":"md-031","scope":"MD","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Maryland, how close to an intersection or railroad crossing may you be when you pass another vehicle?","o":["Within 10 feet","Not within 100 feet","Within 50 feet","Any distance, if you signal"],"h1":"It is about the length of six or seven cars.","h2":"In Maryland, you may not pass when you are crossing or within 100 feet of an intersection or a railroad crossing.","p":"Right. Do not pass within 100 feet of them."},"es":{"q":"En Maryland, ¿qué tan cerca de una intersección o un cruce de ferrocarril puede estar al pasar a otro vehículo?","o":["A 10 pies","No a menos de 100 pies","A 50 pies","A cualquier distancia, si usa la señal"],"h1":"Es como el largo de seis o siete carros.","h2":"En Maryland, no puede pasar a otro vehículo al cruzar una intersección o un cruce de ferrocarril, ni a menos de 100 pies de ellos.","p":"Correcto. No pase a menos de 100 pies de ellos."},"zh":{"q":"在 Maryland，超车时你离路口或铁路道口可以有多近？","o":["10 英尺以内","不可以在 100 英尺以内","50 英尺以内","只要打灯，多近都可以"],"h1":"大约是六七辆车的长度。","h2":"在 Maryland，正在通过路口或铁路道口时，或离它们 100 英尺以内时，你不可以超车。","p":"对。离它们 100 英尺以内不要超车。"},"vi":{"q":"Ở Maryland, khi vượt xe khác, bạn được phép ở gần giao lộ hoặc chỗ băng qua đường sắt đến mức nào?","o":["Trong vòng 10 feet","Không được trong vòng 100 feet","Trong vòng 50 feet","Khoảng cách nào cũng được, nếu bạn bật đèn xi nhan"],"h1":"Khoảng cách đó dài bằng khoảng sáu hoặc bảy chiếc xe.","h2":"Ở Maryland, bạn không được vượt xe khi đang băng qua hoặc ở trong vòng 100 feet của một giao lộ hoặc chỗ băng qua đường sắt.","p":"Đúng. Không vượt xe trong vòng 100 feet của những chỗ đó."},"tl":{"q":"Sa Maryland, gaano ka kalapit sa intersection o tawiran ng tren kapag nag-oovertake ka sa ibang sasakyan?","o":["Sa loob ng 10 talampakan","Hindi sa loob ng 100 talampakan","Sa loob ng 50 talampakan","Kahit anong layo, kung magsesenyas ka"],"h1":"Mga haba ito ng anim o pitong kotse.","h2":"Sa Maryland, hindi ka puwedeng mag-overtake habang tumatawid ka o nasa loob ng 100 talampakan ng isang intersection o tawiran ng tren.","p":"Tama. Huwag mag-overtake sa loob ng 100 talampakan ng mga ito."},"ar":{"q":"في Maryland، ما مدى قربك من التقاطع أو من معبر السكة الحديدية عندما تتجاوز سيارة أخرى؟","o":["في حدود 10 أقدام","ليس في حدود 100 قدم","في حدود 50 قدمًا","أي مسافة، إذا أعطيت إشارة"],"h1":"هي تقريبًا طول ست أو سبع سيارات.","h2":"في Maryland لا يجوز لك أن تتجاوز وأنت تعبر تقاطعًا أو معبر سكة حديدية، أو وأنت في حدود 100 قدم منهما.","p":"صحيح. لا تتجاوز في حدود 100 قدم منهما."},"ref":{"doc":"MD","page":16}},{"id":"md-032","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, a licensed driver gets a Type 2 learner's permit for a different class of license. How long must they hold it before taking the driving test?","o":["At least 14 days","At least 9 months","At least 45 days","At least 6 months"],"h1":"It is a short wait, because this person can already drive.","h2":"In Maryland, you may take the driving test once you have held a Type 2 learner's permit for at least 14 days.","p":"Right. A Type 2 permit must be held at least 14 days before the driving test."},"es":{"q":"En Maryland, un conductor con licencia obtiene un permiso de aprendizaje Tipo 2 para otra clase de licencia. ¿Cuánto tiempo debe tenerlo antes del examen de manejo?","o":["Al menos 14 días","Al menos 9 meses","Al menos 45 días","Al menos 6 meses"],"h1":"Es una espera corta, porque esta persona ya sabe manejar.","h2":"En Maryland, puede tomar el examen de manejo cuando haya tenido el permiso de aprendizaje Tipo 2 por al menos 14 días.","p":"Correcto. El permiso Tipo 2 se debe tener al menos 14 días antes del examen de manejo."},"ref":{"doc":"MD","page":9}},{"id":"md-033","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, how many documents proving that you live in Maryland must you bring when you apply for a license?","o":["One","Two","Three","None, if you have a passport"],"h1":"It is more than one.","h2":"In Maryland, you must bring two documents that prove you live in Maryland when you apply.","p":"Right. Bring two proofs that you live in Maryland."},"es":{"q":"En Maryland, ¿cuántos documentos que prueben que vive en Maryland debe traer cuando solicita una licencia?","o":["Uno","Dos","Tres","Ninguno, si tiene pasaporte"],"h1":"Es más de uno.","h2":"En Maryland, debe traer dos documentos que prueben que vive en Maryland cuando hace la solicitud.","p":"Correcto. Traiga dos pruebas de que vive en Maryland."},"ref":{"doc":"MD","page":9}},{"id":"md-034","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, a new driver is 25 or older. How many hours of supervised practice must they log with a learner's permit?","o":["60 hours, including 10 at night","40 hours, including 5 at night","14 hours, including 3 at night","No practice hours at all"],"h1":"Older beginners need far fewer hours than teens.","h2":"In Maryland, a new driver 25 or older must log at least 14 hours of supervised practice, with at least 3 of them at night.","p":"Right. Drivers 25 or older need 14 hours, including 3 at night."},"es":{"q":"En Maryland, un conductor nuevo tiene 25 años o más. ¿Cuántas horas de práctica supervisada debe registrar con el permiso de aprendizaje?","o":["60 horas, incluidas 10 de noche","40 horas, incluidas 5 de noche","14 horas, incluidas 3 de noche","Ninguna hora de práctica"],"h1":"Los principiantes mayores necesitan muchas menos horas que los adolescentes.","h2":"En Maryland, un conductor nuevo de 25 años o más debe registrar al menos 14 horas de práctica supervisada, y al menos 3 de ellas de noche.","p":"Correcto. Los conductores de 25 años o más necesitan 14 horas, incluidas 3 de noche."},"ref":{"doc":"MD","page":10}},{"id":"md-035","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maryland, a new driver is 20 years old. How long must they hold a learner's permit, with no violations, before getting a provisional license?","o":["45 days","9 months","1 year","3 months"],"h1":"It is shorter than for teens under 18, but longer than for drivers 25 or older.","h2":"In Maryland, a new driver aged 19 to 24, or 18 with a high school diploma or GED, must hold the permit for at least 3 months without a violation.","p":"Right. From 19 to 24, the permit must be held at least 3 months."},"es":{"q":"En Maryland, un conductor nuevo tiene 20 años. ¿Cuánto tiempo debe tener el permiso de aprendizaje, sin infracciones, antes de obtener una licencia provisional?","o":["45 días","9 meses","1 año","3 meses"],"h1":"Es menos que para los menores de 18, pero más que para los de 25 años o más.","h2":"En Maryland, un conductor nuevo de 19 a 24 años, o de 18 con diploma de secundaria o GED, debe tener el permiso al menos 3 meses sin infracciones.","p":"Correcto. De 19 a 24 años, el permiso se debe tener al menos 3 meses."},"ref":{"doc":"MD","page":10}},{"id":"md-036","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, how much gas must be in the car you bring to the driving skills test?","o":["Any amount","At least half a tank","A full tank","At least a quarter tank"],"h1":"The tank cannot be close to empty.","h2":"In Maryland, the car you use for the driving skills test must have at least half a tank of gas.","p":"Right. Bring the car with at least half a tank of gas."},"es":{"q":"En Maryland, ¿cuánta gasolina debe tener el carro que lleva al examen de manejo?","o":["Cualquier cantidad","Al menos medio tanque","El tanque lleno","Al menos un cuarto de tanque"],"h1":"El tanque no puede estar casi vacío.","h2":"En Maryland, el carro que usa para el examen de manejo debe tener al menos medio tanque de gasolina.","p":"Correcto. Lleve el carro con al menos medio tanque de gasolina."},"ref":{"doc":"MD","page":8}},{"id":"md-037","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maryland, which of these must you do during the driving skills test?","o":["Parallel park between two cars","Drive on an interstate highway","Change a flat tire","Pull-in parking, back-in parking and a three-point turn"],"h1":"Parallel parking is no longer part of the test.","h2":"In Maryland, the driving test checks pull-in parking, back-in parking and a three-point turn; parallel parking is no longer required.","p":"Right. You will do pull-in parking, back-in parking and a three-point turn."},"es":{"q":"En Maryland, ¿cuál de estas cosas debe hacer durante el examen de manejo?","o":["Estacionarse en paralelo entre dos carros","Manejar en una autopista interestatal","Cambiar una llanta ponchada","Estacionarse de frente, estacionarse en reversa y dar una vuelta en tres puntos"],"h1":"El estacionamiento en paralelo ya no es parte del examen.","h2":"En Maryland, el examen de manejo revisa estacionarse de frente, estacionarse en reversa y la vuelta en tres puntos; ya no se exige el estacionamiento en paralelo.","p":"Correcto. Se estacionará de frente y en reversa, y dará una vuelta en tres puntos."},"ref":{"doc":"MD","page":53}},{"id":"md-038","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, the knowledge test is offered in your language. How many times must you take it before you may use an interpreter?","o":["At least 5 times","At least 2 times","At least 10 times","You may use an interpreter the first time"],"h1":"You must try on your own several times first.","h2":"In Maryland, if the knowledge test is offered in your language, you must take it at least 5 times before you may use an interpreter.","p":"Right. Take it at least 5 times in your language before using an interpreter."},"es":{"q":"En Maryland, el examen de conocimientos se ofrece en su idioma. ¿Cuántas veces debe tomarlo antes de poder usar un intérprete?","o":["Al menos 5 veces","Al menos 2 veces","Al menos 10 veces","Puede usar un intérprete desde la primera vez"],"h1":"Primero debe intentarlo usted solo varias veces.","h2":"En Maryland, si el examen de conocimientos se ofrece en su idioma, debe tomarlo al menos 5 veces antes de poder usar un intérprete.","p":"Correcto. Tómelo al menos 5 veces en su idioma antes de usar un intérprete."},"ref":{"doc":"MD","page":12}},{"id":"md-039","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, a provisional license holder who is 18 or older is convicted of a first moving violation. What penalty does the MVA add?","o":["The license is revoked","A 30-day suspension","A driver improvement program","No added penalty"],"h1":"The first time, it is a class, not a suspension.","h2":"In Maryland, a provisional driver 18 or older with a first moving violation must complete a driver improvement program.","p":"Right. A first offense means a driver improvement program."},"es":{"q":"En Maryland, un conductor con licencia provisional de 18 años o más es condenado por una primera infracción de tránsito en movimiento. ¿Qué sanción agrega la MVA?","o":["Le revocan la licencia","Una suspensión de 30 días","Un programa de mejoramiento para conductores","Ninguna sanción adicional"],"h1":"La primera vez es una clase, no una suspensión.","h2":"En Maryland, un conductor provisional de 18 años o más con una primera infracción en movimiento debe completar un programa de mejoramiento para conductores.","p":"Correcto. Una primera infracción significa un programa de mejoramiento para conductores."},"ref":{"doc":"MD","page":49}},{"id":"md-040","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, a provisional driver under 18 is convicted of a fourth moving violation. What happens?","o":["A warning letter only","The license is revoked, and all licensing tests must be passed again","A 30-day suspension","A $50 fine only"],"h1":"It is the most serious step for a young driver.","h2":"In Maryland, a fourth moving violation by a provisional driver under 18 means the license is revoked, and all licensing tests must be passed again to get it back.","p":"Right. The license is revoked and every licensing test must be retaken."},"es":{"q":"En Maryland, un conductor provisional menor de 18 años es condenado por una cuarta infracción en movimiento. ¿Qué pasa?","o":["Solo una carta de advertencia","Le revocan la licencia y debe aprobar otra vez todos los exámenes","Una suspensión de 30 días","Solo una multa de $50"],"h1":"Es el paso más serio para un conductor joven.","h2":"En Maryland, con una cuarta infracción en movimiento, a un conductor provisional menor de 18 años le revocan la licencia, y debe aprobar otra vez todos los exámenes para recuperarla.","p":"Correcto. Le revocan la licencia y debe repetir todos los exámenes."},"ref":{"doc":"MD","page":49}},{"id":"md-041","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maryland, what fine can you face if you do not keep insurance on a vehicle?","o":["Up to $100 one time","Up to $500 one time","Only a warning the first time","Up to $2,500 per vehicle each year"],"h1":"The fine is counted for each vehicle and each year.","h2":"In Maryland, if you do not keep insurance on your vehicles, you can be fined up to $2,500 per vehicle each year.","p":"Right. It can cost up to $2,500 per vehicle each year."},"es":{"q":"En Maryland, ¿qué multa puede recibir si no mantiene un seguro en un vehículo?","o":["Hasta $100 una sola vez","Hasta $500 una sola vez","Solo una advertencia la primera vez","Hasta $2,500 por vehículo cada año"],"h1":"La multa se cuenta por cada vehículo y por cada año.","h2":"En Maryland, si no mantiene seguro en sus vehículos, le pueden multar con hasta $2,500 por vehículo cada año.","p":"Correcto. Puede costar hasta $2,500 por vehículo cada año."},"ref":{"doc":"MD","page":53}},{"id":"md-042","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, a driver is convicted of leaving the scene of a crash that caused a serious injury. What can happen?","o":["License revoked, up to 5 years in prison and up to a $5,000 fine","A $110 fine and 1 point","A warning and a safety class","A 30-day suspension only"],"h1":"The penalties are severe: the license is taken away and prison is possible.","h2":"In Maryland, leaving the scene of a crash with a serious injury means your license is revoked, and you could get up to 5 years in prison and a fine up to $5,000.","p":"Right. Revocation, up to 5 years in prison and up to $5,000."},"es":{"q":"En Maryland, un conductor es condenado por huir del lugar de un choque que causó una lesión grave. ¿Qué puede pasar?","o":["Le revocan la licencia, hasta 5 años de cárcel y una multa de hasta $5,000","Una multa de $110 y 1 punto","Una advertencia y una clase de seguridad","Solo una suspensión de 30 días"],"h1":"Las sanciones son graves: le quitan la licencia y puede ir a la cárcel.","h2":"En Maryland, huir del lugar de un choque con una lesión grave significa que le revocan la licencia, y puede recibir hasta 5 años de cárcel y una multa de hasta $5,000.","p":"Correcto. Revocación, hasta 5 años de cárcel y hasta $5,000."},"ref":{"doc":"MD","page":43}},{"id":"md-043","scope":"MD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maryland, a driver is convicted of drunk or drugged driving with a child in the vehicle. What can the judge do?","o":["Lower the fine, because no one was hurt","Only give a warning","Double the fine and jail time","Take away 1 point"],"h1":"Having a child in the car makes it worse, not better.","h2":"In Maryland, if you are convicted of drunk or drugged driving with a child in the vehicle, the judge can double your fine and jail time.","p":"Right. The judge can double the fine and the jail time."},"es":{"q":"En Maryland, un conductor es condenado por manejar borracho o drogado con un niño en el vehículo. ¿Qué puede hacer el juez?","o":["Bajar la multa, porque nadie se lastimó","Solo dar una advertencia","Duplicar la multa y el tiempo de cárcel","Quitar 1 punto"],"h1":"Llevar a un niño en el carro lo hace peor, no mejor.","h2":"En Maryland, si lo condenan por manejar borracho o drogado con un niño en el vehículo, el juez puede duplicar su multa y su tiempo de cárcel.","p":"Correcto. El juez puede duplicar la multa y el tiempo de cárcel."},"ref":{"doc":"MD","page":34}},{"id":"md-044","scope":"MD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maryland, you hit and injure a dog with your car. What must you do?","o":["Drive on if the dog runs away","Wait until the next day to report it","Call only your insurance company","Call the police right away"],"h1":"Dogs, cats, horses and cows count as domestic animals.","h2":"In Maryland, if you hit and injure a domestic animal such as a dog, you must call the police right away.","p":"Right. Call the police right away."},"es":{"q":"En Maryland, usted atropella y lastima a un perro con su carro. ¿Qué debe hacer?","o":["Seguir manejando si el perro se va corriendo","Esperar hasta el día siguiente para reportarlo","Llamar solo a su compañía de seguros","Llamar a la policía de inmediato"],"h1":"Los perros, gatos, caballos y vacas son animales domésticos.","h2":"En Maryland, si atropella y lastima a un animal doméstico, como un perro, debe llamar a la policía de inmediato.","p":"Correcto. Llame a la policía de inmediato."},"ref":{"doc":"MD","page":44}},{"id":"md-045","scope":"MD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maryland, what do flashing blue lights in a work zone mean?","o":["A police officer wants you to pull over","Speed cameras are active","The work zone has ended","Highway maintenance vehicles are ahead"],"h1":"Flashing green lights are for maintenance vehicles. Blue is about your speed.","h2":"In Maryland, flashing blue lights in a work zone mean the speed cameras are active.","p":"Right. Blue lights mean the speed cameras are on."},"es":{"q":"En Maryland, ¿qué significan las luces azules intermitentes en una zona de trabajo?","o":["Un policía quiere que usted se detenga","Las cámaras de velocidad están activas","La zona de trabajo terminó","Hay vehículos de mantenimiento de carreteras más adelante"],"h1":"Las luces verdes intermitentes son de vehículos de mantenimiento. Las azules tienen que ver con su velocidad.","h2":"En Maryland, las luces azules intermitentes en una zona de trabajo significan que las cámaras de velocidad están activas.","p":"Correcto. Las luces azules significan que las cámaras de velocidad están encendidas."},"ref":{"doc":"MD","page":31}},{"id":"md-046","scope":"MD","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Maryland, what is the smallest following distance the MVA recommends in ideal conditions?","o":["3 to 4 seconds","1 second","1 to 2 seconds","10 seconds"],"h1":"Count \"one thousand\" from the moment the car ahead passes a fixed object.","h2":"In Maryland, the MVA recommends following at least 3 to 4 seconds behind the car ahead in ideal conditions.","p":"Right. Stay at least 3 to 4 seconds behind."},"es":{"q":"En Maryland, ¿cuál es la distancia mínima de seguimiento que recomienda la MVA en condiciones ideales?","o":["De 3 a 4 segundos","1 segundo","De 1 a 2 segundos","10 segundos"],"h1":"Cuente \"mil uno\" desde que el carro de adelante pasa un objeto fijo.","h2":"En Maryland, la MVA recomienda ir al menos de 3 a 4 segundos detrás del carro de adelante en condiciones ideales.","p":"Correcto. Manténgase al menos de 3 a 4 segundos detrás."},"ref":{"doc":"MD","page":15}},{"id":"md-047","scope":"MD","cat":"signals","sign":null,"c":2,"en":{"q":"In Maryland, when may you turn left on a steady red light after a complete stop?","o":["Never","From any street, if no cars are coming","From a one-way street onto another one-way street","Only when a police officer is present"],"h1":"Both streets must carry traffic in only one direction.","h2":"In Maryland, unless a sign forbids it, you may turn left on red after a full stop only from a one-way street onto another one-way street.","p":"Right. Left on red is only from one one-way street onto another."},"es":{"q":"En Maryland, ¿cuándo puede girar a la izquierda con la luz roja fija después de detenerse por completo?","o":["Nunca","Desde cualquier calle, si no vienen carros","De una calle de un solo sentido a otra calle de un solo sentido","Solo cuando hay un policía presente"],"h1":"Las dos calles deben tener tráfico en un solo sentido.","h2":"En Maryland, si no hay una señal que lo prohíba, puede girar a la izquierda con luz roja después de detenerse por completo solo de una calle de un solo sentido a otra de un solo sentido.","p":"Correcto. A la izquierda con luz roja solo de una calle de un solo sentido a otra."},"ref":{"doc":"MD","page":17}},{"id":"md-048","scope":"MD","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Maryland, you are driving in a funeral procession with your headlights and hazard lights on. What may you do at a red light?","o":["You must stop and let the procession split up","You may go only after honking","You must stop and wait for a green light","You may go through it with the procession"],"h1":"Other drivers must yield to the procession, even on green.","h2":"In Maryland, a car in a funeral procession with its lights on may go through a red light with the procession.","p":"Right. With your lights on, you may follow the procession through the red light."},"es":{"q":"En Maryland, usted maneja en un cortejo fúnebre con las luces delanteras y las luces de emergencia encendidas. ¿Qué puede hacer en un semáforo en rojo?","o":["Debe detenerse y dejar que el cortejo se divida","Puede pasar solo después de tocar la bocina","Debe detenerse y esperar la luz verde","Puede pasar el semáforo junto con el cortejo"],"h1":"Los demás conductores deben ceder el paso al cortejo, aun con luz verde.","h2":"En Maryland, un carro en un cortejo fúnebre con las luces encendidas puede pasar un semáforo en rojo junto con el cortejo.","p":"Correcto. Con las luces encendidas, puede seguir al cortejo con la luz roja."},"ref":{"doc":"MD","page":32}},{"id":"md-049","scope":"MD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maryland, which vehicles must stop before every railroad crossing, even when no train is coming?","o":["Buses, school buses and trucks carrying hazardous materials","Motorcycles and mopeds","All cars with passengers","Only vehicles towing a trailer"],"h1":"These vehicles carry many people or dangerous loads.","h2":"In Maryland, buses, school buses and trucks carrying hazardous materials must stop before every railroad crossing, so be ready for them to stop.","p":"Right. Buses, school buses and hazardous-materials trucks stop at every crossing."},"es":{"q":"En Maryland, ¿qué vehículos deben detenerse antes de cada cruce de ferrocarril, aunque no venga un tren?","o":["Los autobuses, los autobuses escolares y los camiones que llevan materiales peligrosos","Las motocicletas y los ciclomotores","Todos los carros con pasajeros","Solo los vehículos que remolcan un tráiler"],"h1":"Estos vehículos llevan a muchas personas o cargas peligrosas.","h2":"En Maryland, los autobuses, los autobuses escolares y los camiones que llevan materiales peligrosos deben detenerse antes de cada cruce de ferrocarril, así que esté listo para que se detengan.","p":"Correcto. Los autobuses, los autobuses escolares y los camiones con materiales peligrosos se detienen en cada cruce."},"ref":{"doc":"MD","page":30}},{"id":"md-050","scope":"MD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maryland, how must a child younger than 2 ride in a car?","o":["In a booster seat facing forward","In a rear-facing child safety seat","On an adult's lap with a seat belt","In the front seat with the air bag on"],"h1":"The youngest children face the back of the car.","h2":"In Maryland, a child younger than 2 must ride in a rear-facing child safety seat until reaching the height or weight the seat maker sets.","p":"Right. Children under 2 ride in a rear-facing seat."},"es":{"q":"En Maryland, ¿cómo debe viajar en un carro un niño menor de 2 años?","o":["En un asiento elevado mirando hacia adelante","En un asiento de seguridad para niños mirando hacia atrás","En las piernas de un adulto con el cinturón","En el asiento delantero con la bolsa de aire activada"],"h1":"Los niños más pequeños miran hacia la parte de atrás del carro.","h2":"En Maryland, un niño menor de 2 años debe viajar en un asiento de seguridad mirando hacia atrás hasta llegar a la estatura o el peso que indica el fabricante del asiento.","p":"Correcto. Los niños menores de 2 años viajan en un asiento mirando hacia atrás."},"ref":{"doc":"MD","page":52}},{"id":"md-051","scope":"MD","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Maryland, on which roads may mopeds and motor scooters be ridden?","o":["Only on sidewalks and bike paths","On any road, including interstates","On roads with a posted speed limit of 50 mph or less","Only on roads with a speed limit of 25 mph or less"],"h1":"They are kept off the fastest roads.","h2":"In Maryland, mopeds and motor scooters may be ridden on any road with a posted speed limit of 50 mph or less.","p":"Right. Mopeds and scooters may use roads posted at 50 mph or less."},"es":{"q":"En Maryland, ¿en qué carreteras se pueden manejar los ciclomotores y las motonetas?","o":["Solo en las aceras y los caminos para bicicletas","En cualquier carretera, incluso las interestatales","En carreteras con un límite de velocidad de 50 mph o menos","Solo en carreteras con un límite de 25 mph o menos"],"h1":"Se mantienen fuera de las carreteras más rápidas.","h2":"En Maryland, los ciclomotores y las motonetas se pueden manejar en cualquier carretera con un límite de velocidad de 50 mph o menos.","p":"Correcto. Los ciclomotores y las motonetas pueden usar carreteras con límite de 50 mph o menos."},"ref":{"doc":"MD","page":41}},{"id":"me-001","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, what is the youngest age to get a learner's permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before the intermediate license.","h2":"In Maine you can get a learner's permit at 15. If you are under 18, you must also take an approved driver education course.","p":"Right. The Maine learner's permit starts at 15."},"es":{"q":"En Maine, ¿cuál es la edad mínima para obtener el permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la licencia intermedia.","h2":"En Maine usted puede obtener el permiso de aprendiz a los 15 años. Si tiene menos de 18 años, también debe tomar un curso aprobado de educación vial.","p":"Correcto. El permiso de aprendiz en Maine empieza a los 15."},"zh":{"q":"在 Maine，最小几岁可以拿到学习驾照（learner's permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比中级驾照早一年。","h2":"在 Maine，你 15 岁就可以拿到学习驾照。如果你未满 18 岁，还必须上一门批准的驾驶教育课程。","p":"对。Maine 的学习驾照从 15 岁开始。"},"vi":{"q":"Ở Maine, tuổi nhỏ nhất để có giấy phép tập lái (learner's permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Tuổi này sớm hơn một năm so với bằng lái trung gian.","h2":"Ở Maine, bạn có thể có giấy phép tập lái khi 15 tuổi. Nếu bạn dưới 18 tuổi, bạn cũng phải học một khóa giáo dục lái xe (driver education) được chấp thuận.","p":"Đúng. Giấy phép tập lái ở Maine bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Maine, ano ang pinakabatang edad para makakuha ng learner's permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ang intermediate license.","h2":"Sa Maine, puwede kang makakuha ng learner's permit sa edad na 15. Kung wala ka pang 18, dapat ka ring kumuha ng aprubadong kurso sa driver education.","p":"Tama. Nagsisimula ang learner's permit sa Maine sa edad na 15."},"ar":{"q":"في Maine، ما أصغر عمر للحصول على تصريح تعلّم القيادة (learner's permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هذا العمر قبل الرخصة المتوسطة بسنة واحدة.","h2":"في Maine يمكنك الحصول على تصريح تعلّم القيادة في عمر 15 سنة. وإذا كان عمرك أقل من 18 سنة، يجب أيضًا أن تأخذ دورة تعليم قيادة (driver education) معتمدة.","p":"صحيح. يبدأ تصريح تعلّم القيادة في Maine في عمر 15 سنة."},"ref":{"doc":"ME","page":"1-2"}},{"id":"me-002","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, how many hours of practice driving must a permit holder under 21 log?","o":["30 hours","50 hours","70 hours","100 hours"],"h1":"It is more than in many states, but less than one hundred.","h2":"A Maine permit holder under 21 must log 70 hours of practice driving.","p":"Right. Maine asks for 70 hours."},"es":{"q":"En Maine, ¿cuántas horas de práctica de manejo debe registrar un aprendiz menor de 21 años?","o":["30 horas","50 horas","70 horas","100 horas"],"h1":"Es más que en muchos estados, pero menos de cien.","h2":"Un aprendiz en Maine menor de 21 años debe registrar 70 horas de práctica de manejo.","p":"Correcto. Maine pide 70 horas."},"zh":{"q":"在 Maine，21 岁以下持学习驾照的人必须记录多少小时的练习驾驶？","o":["30 小时","50 小时","70 小时","100 小时"],"h1":"它比很多州多，但不到一百。","h2":"在 Maine，21 岁以下持学习驾照的人必须记录 70 小时的练习驾驶。","p":"对。Maine 要求 70 小时。"},"vi":{"q":"Ở Maine, người có giấy phép tập lái dưới 21 tuổi phải ghi lại bao nhiêu giờ tập lái?","o":["30 giờ","50 giờ","70 giờ","100 giờ"],"h1":"Số này nhiều hơn ở nhiều tiểu bang, nhưng ít hơn một trăm.","h2":"Ở Maine, người có giấy phép tập lái dưới 21 tuổi phải ghi lại 70 giờ tập lái.","p":"Đúng. Maine yêu cầu 70 giờ."},"tl":{"q":"Sa Maine, ilang oras ng praktis sa pagmamaneho ang dapat itala ng may hawak ng permit na wala pang 21?","o":["30 oras","50 oras","70 oras","100 oras"],"h1":"Mas marami ito kaysa sa maraming estado, pero mas kaunti sa isang daan.","h2":"Sa Maine, ang may hawak ng permit na wala pang 21 ay dapat magtala ng 70 oras ng praktis sa pagmamaneho.","p":"Tama. Humihingi ang Maine ng 70 oras."},"ar":{"q":"في Maine، كم ساعة من التدريب على القيادة يجب أن يسجّلها حامل التصريح الذي عمره أقل من 21 سنة؟","o":["30 ساعة","50 ساعة","70 ساعة","100 ساعة"],"h1":"هذا أكثر من ولايات كثيرة، لكنه أقل من مئة.","h2":"في Maine يجب على حامل التصريح الذي عمره أقل من 21 سنة أن يسجّل 70 ساعة من التدريب على القيادة.","p":"صحيح. تطلب Maine سبعين ساعة."},"ref":{"doc":"ME","page":"1-3"}},{"id":"me-003","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, how many of the 70 practice hours must be driven after dark?","o":["10 hours","5 hours","20 hours","35 hours"],"h1":"It is a round number, a small part of the total.","h2":"In Maine, 10 of the 70 practice hours must be driven after dark.","p":"Right. Ten of the hours must be after dark."},"es":{"q":"En Maine, ¿cuántas de las 70 horas de práctica deben ser después del anochecer?","o":["10 horas","5 horas","20 horas","35 horas"],"h1":"Es un número redondo, una parte pequeña del total.","h2":"En Maine, 10 de las 70 horas de práctica deben ser después del anochecer.","p":"Correcto. Diez de las horas deben ser de noche."},"zh":{"q":"在 Maine，70 小时练习中有多少小时必须在天黑以后开？","o":["10 小时","5 小时","20 小时","35 小时"],"h1":"这是一个整数，只占总数的一小部分。","h2":"在 Maine，70 小时练习中有 10 小时必须在天黑以后开。","p":"对。其中 10 小时必须在天黑以后。"},"vi":{"q":"Ở Maine, trong 70 giờ tập lái, bao nhiêu giờ phải lái sau khi trời tối?","o":["10 giờ","5 giờ","20 giờ","35 giờ"],"h1":"Đây là một số tròn, một phần nhỏ của tổng số giờ.","h2":"Ở Maine, 10 trong 70 giờ tập lái phải được lái sau khi trời tối.","p":"Đúng. Mười giờ phải lái sau khi trời tối."},"tl":{"q":"Sa Maine, ilan sa 70 oras ng praktis ang dapat gawin pagkatapos dumilim?","o":["10 oras","5 oras","20 oras","35 oras"],"h1":"Isa itong buong numero, maliit na bahagi ng kabuuan.","h2":"Sa Maine, 10 sa 70 oras ng praktis ang dapat gawin pagkatapos dumilim.","p":"Tama. Sampu sa mga oras ang dapat pagkatapos dumilim."},"ar":{"q":"في Maine، كم ساعة من ساعات التدريب السبعين يجب أن تكون بعد حلول الظلام؟","o":["10 ساعات","5 ساعات","20 ساعة","35 ساعة"],"h1":"هو رقم مستدير، وجزء صغير من المجموع.","h2":"في Maine يجب أن تكون 10 ساعات من ساعات التدريب السبعين بعد حلول الظلام.","p":"صحيح. عشر ساعات يجب أن تكون بعد حلول الظلام."},"ref":{"doc":"ME","page":"1-3"}},{"id":"me-004","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, when may the 70 practice hours start to count?","o":["At age 14","After the road test","After the first year of high school","After the learner's permit is issued"],"h1":"You need a permit to drive on the road.","h2":"In Maine, the 70 practice hours must begin after the learner's permit is issued.","p":"Right. Hours count only once you have the permit."},"es":{"q":"En Maine, ¿cuándo empiezan a contar las 70 horas de práctica?","o":["A los 14 años","Después del examen de manejo","Después del primer año de secundaria","Después de recibir el permiso de aprendiz"],"h1":"Usted necesita un permiso para manejar en la calle.","h2":"En Maine, las 70 horas de práctica deben empezar después de recibir el permiso de aprendiz.","p":"Correcto. Las horas cuentan solo cuando ya tiene el permiso."},"zh":{"q":"在 Maine，70 小时的练习从什么时候开始算？","o":["从 14 岁开始","路考以后","高中第一年以后","拿到学习驾照以后"],"h1":"你需要有学习驾照才能在路上开车。","h2":"在 Maine，70 小时的练习必须在拿到学习驾照以后才开始算。","p":"对。只有拿到学习驾照以后，练习时间才算数。"},"vi":{"q":"Ở Maine, khi nào 70 giờ tập lái bắt đầu được tính?","o":["Khi 14 tuổi","Sau bài thi lái xe trên đường","Sau năm học đầu tiên ở trung học","Sau khi được cấp giấy phép tập lái"],"h1":"Bạn cần có giấy phép mới được lái xe trên đường.","h2":"Ở Maine, 70 giờ tập lái phải bắt đầu sau khi được cấp giấy phép tập lái.","p":"Đúng. Số giờ chỉ được tính khi bạn đã có giấy phép."},"tl":{"q":"Sa Maine, kailan nagsisimulang mabilang ang 70 oras ng praktis?","o":["Sa edad na 14","Pagkatapos ng road test","Pagkatapos ng unang taon sa high school","Pagkatapos maibigay ang learner's permit"],"h1":"Kailangan mo ng permit para magmaneho sa kalsada.","h2":"Sa Maine, ang 70 oras ng praktis ay dapat magsimula pagkatapos maibigay ang learner's permit.","p":"Tama. Nabibilang lang ang mga oras kapag may permit ka na."},"ar":{"q":"في Maine، متى تبدأ ساعات التدريب السبعون في الاحتساب؟","o":["في عمر 14 سنة","بعد اختبار القيادة على الطريق","بعد السنة الأولى في المدرسة الثانوية","بعد إصدار تصريح تعلّم القيادة"],"h1":"تحتاج إلى تصريح لتقود على الطريق.","h2":"في Maine يجب أن تبدأ ساعات التدريب السبعون بعد إصدار تصريح تعلّم القيادة.","p":"صحيح. لا تُحتسب الساعات إلا بعد حصولك على التصريح."},"ref":{"doc":"ME","page":"1-3"}},{"id":"me-005","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, how long must a permit holder under 21 hold the permit before the road test?","o":["3 months","6 months","9 months","12 months"],"h1":"It is half a year.","h2":"In Maine, a permit holder under 21 must hold the permit for 6 months before applying for the road test.","p":"Right. Six months with the permit first."},"es":{"q":"En Maine, ¿cuánto tiempo debe tener el permiso un aprendiz menor de 21 años antes del examen de manejo?","o":["3 meses","6 meses","9 meses","12 meses"],"h1":"Es medio año.","h2":"En Maine, un aprendiz menor de 21 años debe tener el permiso 6 meses antes de solicitar el examen de manejo.","p":"Correcto. Primero, seis meses con el permiso."},"zh":{"q":"在 Maine，21 岁以下持学习驾照的人，路考前必须持有学习驾照多久？","o":["3 个月","6 个月","9 个月","12 个月"],"h1":"是半年。","h2":"在 Maine，21 岁以下持学习驾照的人必须先持有学习驾照 6 个月，才能申请路考。","p":"对。先持有学习驾照六个月。"},"vi":{"q":"Ở Maine, người có giấy phép tập lái dưới 21 tuổi phải giữ giấy phép bao lâu trước bài thi lái xe trên đường?","o":["3 tháng","6 tháng","9 tháng","12 tháng"],"h1":"Đó là nửa năm.","h2":"Ở Maine, người có giấy phép tập lái dưới 21 tuổi phải giữ giấy phép 6 tháng trước khi đăng ký thi lái xe trên đường.","p":"Đúng. Phải giữ giấy phép sáu tháng trước."},"tl":{"q":"Sa Maine, gaano katagal dapat hawak ng may permit na wala pang 21 ang permit bago ang road test?","o":["3 buwan","6 na buwan","9 na buwan","12 buwan"],"h1":"Kalahating taon ito.","h2":"Sa Maine, ang may hawak ng permit na wala pang 21 ay dapat hawak ang permit nang 6 na buwan bago mag-apply para sa road test.","p":"Tama. Anim na buwan muna na may permit."},"ar":{"q":"في Maine، كم مدة يجب أن يحمل صاحب التصريح الذي عمره أقل من 21 سنة التصريحَ قبل اختبار القيادة على الطريق؟","o":["3 أشهر","6 أشهر","9 أشهر","12 شهرًا"],"h1":"إنها نصف سنة.","h2":"في Maine يجب على حامل التصريح الذي عمره أقل من 21 سنة أن يحمل التصريح 6 أشهر قبل التقدّم لاختبار القيادة على الطريق.","p":"صحيح. ستة أشهر مع التصريح أولًا."},"ref":{"doc":"ME","page":"1-3"}},{"id":"me-006","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, how old must the supervising driver of a permit holder be?","o":["At least 16","At least 18","At least 20","At least 25"],"h1":"It is younger than in many other states.","h2":"In Maine, the supervising driver must be at least 20 years old and have held a license for at least 2 years.","p":"Right. The supervisor must be 20 or older."},"es":{"q":"En Maine, ¿qué edad debe tener el conductor que supervisa a un aprendiz?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 20","Por lo menos 25"],"h1":"Es menor que en muchos otros estados.","h2":"En Maine, el conductor que supervisa debe tener por lo menos 20 años y haber tenido licencia por lo menos 2 años.","p":"Correcto. El supervisor debe tener 20 años o más."},"zh":{"q":"在 Maine，陪同持学习驾照的人开车的司机必须几岁？","o":["至少 16 岁","至少 18 岁","至少 20 岁","至少 25 岁"],"h1":"它比很多其他州的要求年轻。","h2":"在 Maine，陪同的司机必须至少 20 岁，而且持有驾照至少 2 年。","p":"对。陪同的人必须 20 岁或以上。"},"vi":{"q":"Ở Maine, người lái xe giám sát người có giấy phép tập lái phải bao nhiêu tuổi?","o":["Ít nhất 16 tuổi","Ít nhất 18 tuổi","Ít nhất 20 tuổi","Ít nhất 25 tuổi"],"h1":"Tuổi này trẻ hơn so với nhiều tiểu bang khác.","h2":"Ở Maine, người lái xe giám sát phải ít nhất 20 tuổi và đã có bằng lái ít nhất 2 năm.","p":"Đúng. Người giám sát phải từ 20 tuổi trở lên."},"tl":{"q":"Sa Maine, ilang taon dapat ang driver na nagbabantay sa may hawak ng permit?","o":["Hindi bababa sa 16","Hindi bababa sa 18","Hindi bababa sa 20","Hindi bababa sa 25"],"h1":"Mas bata ito kaysa sa maraming ibang estado.","h2":"Sa Maine, ang nagbabantay na driver ay dapat hindi bababa sa 20 taong gulang at may lisensya nang hindi bababa sa 2 taon.","p":"Tama. Ang nagbabantay ay dapat 20 pataas."},"ar":{"q":"في Maine، كم يجب أن يكون عمر السائق المشرف على حامل التصريح؟","o":["16 سنة على الأقل","18 سنة على الأقل","20 سنة على الأقل","25 سنة على الأقل"],"h1":"هذا العمر أصغر مما في ولايات كثيرة أخرى.","h2":"في Maine يجب أن يكون عمر السائق المشرف 20 سنة على الأقل، وأن يكون معه رخصة منذ سنتين (2) على الأقل.","p":"صحيح. يجب أن يكون عمر المشرف 20 سنة أو أكثر."},"ref":{"doc":"ME","page":"1-2"}},{"id":"me-007","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, how long must the supervising driver of a permit holder have held a license?","o":["At least 2 years","At least 6 months","At least 5 years","At least 10 years"],"h1":"It is a short number of years.","h2":"In Maine, the supervising driver must have held a license for at least 2 years.","p":"Right. Two years of license experience is required."},"es":{"q":"En Maine, ¿cuánto tiempo debe haber tenido licencia el conductor que supervisa a un aprendiz?","o":["Por lo menos 2 años","Por lo menos 6 meses","Por lo menos 5 años","Por lo menos 10 años"],"h1":"Es un número pequeño de años.","h2":"En Maine, el conductor que supervisa debe haber tenido licencia por lo menos 2 años.","p":"Correcto. Se requieren dos años con licencia."},"zh":{"q":"在 Maine，陪同持学习驾照的人开车的司机必须持有驾照多久？","o":["至少 2 年","至少 6 个月","至少 5 年","至少 10 年"],"h1":"只要短短几年。","h2":"在 Maine，陪同的司机必须持有驾照至少 2 年。","p":"对。需要有两年的驾照经验。"},"vi":{"q":"Ở Maine, người lái xe giám sát người có giấy phép tập lái phải có bằng lái bao lâu?","o":["Ít nhất 2 năm","Ít nhất 6 tháng","Ít nhất 5 năm","Ít nhất 10 năm"],"h1":"Đó là một số năm ít.","h2":"Ở Maine, người lái xe giám sát phải có bằng lái ít nhất 2 năm.","p":"Đúng. Cần có bằng lái ít nhất hai năm."},"tl":{"q":"Sa Maine, gaano katagal dapat may lisensya ang driver na nagbabantay sa may hawak ng permit?","o":["Hindi bababa sa 2 taon","Hindi bababa sa 6 na buwan","Hindi bababa sa 5 taon","Hindi bababa sa 10 taon"],"h1":"Kaunting taon lang ito.","h2":"Sa Maine, ang nagbabantay na driver ay dapat may lisensya nang hindi bababa sa 2 taon.","p":"Tama. Kailangan ang dalawang taon na may lisensya."},"ar":{"q":"في Maine، منذ كم مدة يجب أن يحمل السائق المشرف على حامل التصريح رخصة قيادة؟","o":["سنتان (2) على الأقل","6 أشهر على الأقل","5 سنوات على الأقل","10 سنوات على الأقل"],"h1":"إنه عدد قليل من السنوات.","h2":"في Maine يجب أن يكون السائق المشرف حاملًا لرخصة قيادة منذ سنتين (2) على الأقل.","p":"صحيح. يلزم سنتان من الخبرة برخصة القيادة."},"ref":{"doc":"ME","page":"1-2"}},{"id":"me-008","scope":"ME","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maine, may a driver with a learner's permit use a cell phone while driving?","o":["Yes, if it is hands-free","No, a cell phone may not be used","Yes, at red lights","Yes, if the supervisor allows it"],"h1":"Permit holders have a stricter rule than adult drivers.","h2":"In Maine, a driver with a learner's permit may not use a cell phone while driving, not even hands-free.","p":"Right. No cell phone at all while driving on a permit."},"es":{"q":"En Maine, ¿puede un conductor con permiso de aprendiz usar el celular mientras maneja?","o":["Sí, si es de manos libres","No, no puede usar el celular","Sí, en los semáforos en rojo","Sí, si el supervisor lo permite"],"h1":"Los aprendices tienen una regla más estricta que los conductores adultos.","h2":"En Maine, un conductor con permiso de aprendiz no puede usar el celular mientras maneja, ni siquiera con manos libres.","p":"Correcto. Nada de celular al manejar con permiso de aprendiz."},"zh":{"q":"在 Maine，持学习驾照的司机开车时可以用手机吗？","o":["可以，如果是免提","不可以，不能用手机","可以，在红灯时","可以，如果陪同的人允许"],"h1":"持学习驾照的人比成年司机的规定更严格。","h2":"在 Maine，持学习驾照的司机开车时不能用手机，免提也不行。","p":"对。持学习驾照开车时，完全不能用手机。"},"vi":{"q":"Ở Maine, người có giấy phép tập lái có được dùng điện thoại di động khi lái xe không?","o":["Có, nếu không cầm tay (hands-free)","Không, không được dùng điện thoại di động","Có, khi dừng đèn đỏ","Có, nếu người giám sát cho phép"],"h1":"Người có giấy phép tập lái có quy định nghiêm hơn người lớn.","h2":"Ở Maine, người có giấy phép tập lái không được dùng điện thoại di động khi lái xe, kể cả không cầm tay (hands-free).","p":"Đúng. Không dùng điện thoại di động khi lái xe với giấy phép tập lái."},"tl":{"q":"Sa Maine, puwede bang gumamit ng cell phone habang nagmamaneho ang driver na may learner's permit?","o":["Oo, kung hands-free","Hindi, bawal gumamit ng cell phone","Oo, kapag nasa red light","Oo, kung papayag ang nagbabantay"],"h1":"Mas mahigpit ang patakaran para sa may permit kaysa sa mga adult na driver.","h2":"Sa Maine, ang driver na may learner's permit ay bawal gumamit ng cell phone habang nagmamaneho, kahit hands-free.","p":"Tama. Walang cell phone habang nagmamaneho na may permit."},"ar":{"q":"في Maine، هل يجوز للسائق الذي يحمل تصريح تعلّم القيادة استخدام الهاتف المحمول أثناء القيادة؟","o":["نعم، إذا كان بدون استخدام اليدين (hands-free)","لا، لا يجوز استخدام الهاتف المحمول","نعم، عند الإشارة الحمراء","نعم، إذا سمح المشرف بذلك"],"h1":"لحاملي التصريح قاعدة أشد من السائقين البالغين.","h2":"في Maine لا يجوز للسائق الذي يحمل تصريح تعلّم القيادة استخدام الهاتف المحمول أثناء القيادة، ولا حتى بدون استخدام اليدين (hands-free).","p":"صحيح. لا هاتف محمول أبدًا أثناء القيادة بالتصريح."},"ref":{"doc":"ME","page":"1-2"}},{"id":"me-009","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, for how long do the intermediate license restrictions last?","o":["90 days","180 days","365 days","270 days"],"h1":"It is about nine months.","h2":"In Maine, the intermediate license restrictions last 270 days from the day the license is issued.","p":"Right. The restrictions last 270 days."},"es":{"q":"En Maine, ¿cuánto duran las restricciones de la licencia intermedia?","o":["90 días","180 días","365 días","270 días"],"h1":"Son unos nueve meses.","h2":"En Maine, las restricciones de la licencia intermedia duran 270 días desde el día en que se emite la licencia.","p":"Correcto. Las restricciones duran 270 días."},"zh":{"q":"在 Maine，中级驾照的限制会持续多久？","o":["90 天","180 天","365 天","270 天"],"h1":"大约九个月。","h2":"在 Maine，中级驾照的限制从拿到驾照那天起持续 270 天。","p":"对。限制持续 270 天。"},"vi":{"q":"Ở Maine, các hạn chế của bằng lái trung gian (intermediate license) kéo dài bao lâu?","o":["90 ngày","180 ngày","365 ngày","270 ngày"],"h1":"Khoảng chín tháng.","h2":"Ở Maine, các hạn chế của bằng lái trung gian kéo dài 270 ngày kể từ ngày được cấp bằng.","p":"Đúng. Các hạn chế kéo dài 270 ngày."},"tl":{"q":"Sa Maine, gaano katagal ang mga paghihigpit ng intermediate license?","o":["90 araw","180 araw","365 araw","270 araw"],"h1":"Mga siyam na buwan ito.","h2":"Sa Maine, ang mga paghihigpit ng intermediate license ay tumatagal nang 270 araw mula sa araw na ibinigay ang lisensya.","p":"Tama. Tumatagal ang mga paghihigpit nang 270 araw."},"ar":{"q":"في Maine، كم تستمر قيود الرخصة المتوسطة (intermediate license)؟","o":["90 يومًا","180 يومًا","365 يومًا","270 يومًا"],"h1":"إنها حوالي تسعة أشهر.","h2":"في Maine تستمر قيود الرخصة المتوسطة 270 يومًا من يوم إصدار الرخصة.","p":"صحيح. تستمر القيود 270 يومًا."},"ref":{"doc":"ME","page":"1-4"}},{"id":"me-010","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, who may ride as a passenger with an intermediate license holder when no qualified adult driver is along?","o":["Any friends","Up to two friends","Only immediate family members","Only people over 18"],"h1":"Think of the people in your family.","h2":"In Maine, an intermediate license holder may carry only immediate family members as passengers unless a qualified licensed driver is along.","p":"Right. Only family, unless a qualified driver is along."},"es":{"q":"En Maine, ¿quién puede viajar como pasajero con el titular de una licencia intermedia cuando no va un conductor adulto calificado?","o":["Cualquier amigo","Hasta dos amigos","Solo familiares directos","Solo personas mayores de 18"],"h1":"Piense en las personas de su familia.","h2":"En Maine, el titular de una licencia intermedia puede llevar solo a familiares directos como pasajeros, salvo que vaya un conductor con licencia calificado.","p":"Correcto. Solo familiares, salvo que vaya un conductor calificado."},"zh":{"q":"在 Maine，没有合格的成年司机同车时，谁可以坐持中级驾照的人开的车？","o":["任何朋友","最多两个朋友","只有直系家人","只有 18 岁以上的人"],"h1":"想一想你家里的人。","h2":"在 Maine，持中级驾照的人只能载直系家人，除非有合格的、有驾照的司机同车。","p":"对。只能载家人，除非有合格的司机同车。"},"vi":{"q":"Ở Maine, ai được ngồi xe với người có bằng lái trung gian khi không có người lớn có bằng lái đủ điều kiện đi cùng?","o":["Bạn bè nào cũng được","Tối đa hai người bạn","Chỉ người thân trong gia đình gần","Chỉ người trên 18 tuổi"],"h1":"Hãy nghĩ đến những người trong gia đình bạn.","h2":"Ở Maine, người có bằng lái trung gian chỉ được chở người thân trong gia đình gần, trừ khi có người lái xe có bằng lái đủ điều kiện đi cùng.","p":"Đúng. Chỉ chở gia đình, trừ khi có người lái xe đủ điều kiện đi cùng."},"tl":{"q":"Sa Maine, sino ang puwedeng sumakay bilang pasahero kasama ang may intermediate license kapag walang kasamang kwalipikadong adult na driver?","o":["Kahit sinong kaibigan","Hanggang dalawang kaibigan","Mga malapit na kapamilya lang","Mga taong lampas 18 lang"],"h1":"Isipin ang mga tao sa iyong pamilya.","h2":"Sa Maine, ang may intermediate license ay puwedeng magsakay ng malalapit na kapamilya lang, maliban kung may kasamang kwalipikadong may lisensyang driver.","p":"Tama. Pamilya lang, maliban kung may kasamang kwalipikadong driver."},"ar":{"q":"في Maine، من يجوز له الركوب كراكب مع حامل الرخصة المتوسطة عندما لا يكون معه سائق بالغ مؤهَّل؟","o":["أي أصدقاء","صديقان على الأكثر","أفراد العائلة المقرّبون فقط","الأشخاص فوق 18 سنة فقط"],"h1":"فكّر في الأشخاص في عائلتك.","h2":"في Maine لا يجوز لحامل الرخصة المتوسطة أن ينقل ركّابًا إلا أفراد العائلة المقرّبين، إلا إذا كان معه سائق مؤهَّل يحمل رخصة.","p":"صحيح. العائلة فقط، إلا إذا كان معك سائق مؤهَّل."},"ref":{"doc":"ME","page":"1-4"}},{"id":"me-011","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, what happens to intermediate license restrictions after a violation of those rules?","o":["Nothing changes","They are extended by another 270 days","They end right away","They become a fine only"],"h1":"Breaking the rules makes them last longer.","h2":"In Maine, a driver who breaks the intermediate license rules has the restrictions extended by another 270 days.","p":"Right. A violation adds 270 more days."},"es":{"q":"En Maine, ¿qué pasa con las restricciones de la licencia intermedia después de violar esas reglas?","o":["No cambia nada","Se extienden por otros 270 días","Terminan de inmediato","Se convierten solo en una multa"],"h1":"Violar las reglas hace que duren más.","h2":"En Maine, a un conductor que viola las reglas de la licencia intermedia se le extienden las restricciones por otros 270 días.","p":"Correcto. Una violación agrega 270 días más."},"zh":{"q":"在 Maine，违反中级驾照的规定以后，这些限制会怎样？","o":["什么都不变","再延长 270 天","马上结束","只要罚款"],"h1":"违反规定会让限制持续更久。","h2":"在 Maine，违反中级驾照规定的司机，限制会再延长 270 天。","p":"对。违规会再加 270 天。"},"vi":{"q":"Ở Maine, điều gì xảy ra với các hạn chế của bằng lái trung gian khi vi phạm các quy định đó?","o":["Không có gì thay đổi","Bị kéo dài thêm 270 ngày","Kết thúc ngay lập tức","Chỉ còn là tiền phạt"],"h1":"Vi phạm quy định làm các hạn chế kéo dài lâu hơn.","h2":"Ở Maine, người lái xe vi phạm quy định của bằng lái trung gian sẽ bị kéo dài các hạn chế thêm 270 ngày.","p":"Đúng. Một lần vi phạm thêm 270 ngày nữa."},"tl":{"q":"Sa Maine, ano ang nangyayari sa mga paghihigpit ng intermediate license kapag nilabag ang mga patakarang iyon?","o":["Walang nagbabago","Pinahahaba pa nang 270 araw","Natatapos agad","Multa na lang"],"h1":"Kapag lumabag ka, mas tatagal ang mga ito.","h2":"Sa Maine, ang driver na lumabag sa mga patakaran ng intermediate license ay pinahahaba ang mga paghihigpit nang 270 araw pa.","p":"Tama. Isang paglabag ay nagdadagdag ng 270 araw."},"ar":{"q":"في Maine، ماذا يحدث لقيود الرخصة المتوسطة بعد مخالفة تلك القواعد؟","o":["لا يتغيّر شيء","تُمدَّد 270 يومًا أخرى","تنتهي فورًا","تصبح غرامة فقط"],"h1":"مخالفة القواعد تجعلها تستمر مدة أطول.","h2":"في Maine السائق الذي يخالف قواعد الرخصة المتوسطة تُمدَّد قيوده 270 يومًا أخرى.","p":"صحيح. المخالفة تضيف 270 يومًا أخرى."},"ref":{"doc":"ME","page":"1-4"}},{"id":"me-012","scope":"ME","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maine, how may an adult driver make a phone call while driving?","o":["Hands-free, without holding the phone","Holding the phone to the ear","Only by texting","Holding the phone at a stop sign"],"h1":"Your hands stay off the device.","h2":"In Maine, a driver 18 or older with a full license may not hold a phone while driving, but may make calls hands-free.","p":"Right. Maine bans holding the phone while driving."},"es":{"q":"En Maine, ¿cómo puede un conductor adulto hacer una llamada mientras maneja?","o":["Con manos libres, sin sostener el teléfono","Sosteniendo el teléfono en el oído","Solo con mensajes de texto","Sosteniendo el teléfono en una señal de alto"],"h1":"Sus manos no tocan el aparato.","h2":"En Maine, un conductor de 18 años o más con licencia completa no puede sostener el teléfono mientras maneja, pero puede hacer llamadas con manos libres.","p":"Correcto. Maine prohíbe sostener el teléfono al manejar."},"zh":{"q":"在 Maine，成年司机开车时可以怎样打电话？","o":["用免提，不拿着手机","把手机拿到耳边","只能发短信","在停车标志前拿着手机"],"h1":"你的手不碰这个设备。","h2":"在 Maine，18 岁或以上、持正式驾照的司机开车时不能手拿手机，但可以用免提打电话。","p":"对。Maine 禁止开车时手拿手机。"},"vi":{"q":"Ở Maine, người lớn có thể gọi điện thoại khi lái xe bằng cách nào?","o":["Không cầm tay (hands-free), không cầm điện thoại","Cầm điện thoại áp vào tai","Chỉ bằng cách nhắn tin","Cầm điện thoại khi dừng ở biển STOP"],"h1":"Tay bạn không chạm vào thiết bị.","h2":"Ở Maine, người lái xe từ 18 tuổi trở lên có bằng lái đầy đủ không được cầm điện thoại khi lái xe, nhưng có thể gọi điện không cầm tay (hands-free).","p":"Đúng. Maine cấm cầm điện thoại khi lái xe."},"tl":{"q":"Sa Maine, paano puwedeng tumawag sa telepono ang adult na driver habang nagmamaneho?","o":["Hands-free, nang hindi hawak ang telepono","Hawak ang telepono sa tainga","Sa pag-text lang","Hawak ang telepono sa STOP sign"],"h1":"Hindi hawak ng iyong mga kamay ang device.","h2":"Sa Maine, ang driver na 18 pataas na may buong lisensya ay bawal humawak ng telepono habang nagmamaneho, pero puwedeng tumawag nang hands-free.","p":"Tama. Bawal sa Maine ang paghawak ng telepono habang nagmamaneho."},"ar":{"q":"في Maine، كيف يمكن للسائق البالغ أن يجري مكالمة هاتفية أثناء القيادة؟","o":["بدون استخدام اليدين (hands-free)، دون حمل الهاتف","بحمل الهاتف على الأذن","بالرسائل النصية فقط","بحمل الهاتف عند علامة STOP"],"h1":"يداك تبقيان بعيدتين عن الجهاز.","h2":"في Maine لا يجوز للسائق الذي عمره 18 سنة أو أكثر ويحمل رخصة كاملة أن يمسك الهاتف أثناء القيادة، لكن يمكنه إجراء المكالمات بدون استخدام اليدين (hands-free).","p":"صحيح. تمنع Maine إمساك الهاتف أثناء القيادة."},"ref":{"doc":"ME","page":null}},{"id":"me-013","scope":"ME","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maine, what happens to a driver under 21 found driving with any measurable amount of alcohol?","o":["Only a warning","A 30-day suspension","Nothing, if below 0.08 percent","The license is suspended for at least one year"],"h1":"Maine has zero tolerance for young drivers.","h2":"In Maine, a driver under 21 with any amount of alcohol loses the license for at least one year.","p":"Right. Under 21, any alcohol means losing the license for at least a year."},"es":{"q":"En Maine, ¿qué le pasa a un conductor menor de 21 años que maneja con cualquier cantidad medible de alcohol?","o":["Solo una advertencia","Una suspensión de 30 días","Nada, si está por debajo de 0.08 por ciento","Se le suspende la licencia por al menos un año"],"h1":"Maine tiene tolerancia cero para los conductores jóvenes.","h2":"En Maine, un conductor menor de 21 años con cualquier cantidad de alcohol pierde la licencia por al menos un año.","p":"Correcto. Menor de 21, cualquier alcohol significa perder la licencia por al menos un año."},"zh":{"q":"在 Maine，21 岁以下的司机开车时被查出体内有任何可测量的酒精，会怎样？","o":["只是警告","暂停驾照 30 天","如果低于 0.08% 就没事","驾照被暂停至少一年"],"h1":"Maine 对年轻司机实行零容忍。","h2":"在 Maine，21 岁以下的司机只要体内有任何酒精，就会失去驾照至少一年。","p":"对。21 岁以下，只要有酒精，就会失去驾照至少一年。"},"vi":{"q":"Ở Maine, điều gì xảy ra với người lái xe dưới 21 tuổi bị phát hiện lái xe có bất kỳ lượng cồn nào đo được?","o":["Chỉ bị cảnh cáo","Bị đình chỉ 30 ngày","Không có gì, nếu dưới 0.08 phần trăm","Bằng lái bị đình chỉ ít nhất một năm"],"h1":"Maine không khoan nhượng (zero tolerance) với tài xế trẻ.","h2":"Ở Maine, người lái xe dưới 21 tuổi có bất kỳ lượng cồn nào sẽ mất bằng lái ít nhất một năm.","p":"Đúng. Dưới 21 tuổi, có chút cồn nào cũng mất bằng lái ít nhất một năm."},"tl":{"q":"Sa Maine, ano ang mangyayari sa driver na wala pang 21 na nahuling nagmamaneho na may kahit kaunting alak na nasusukat?","o":["Babala lang","30 araw na suspensyon","Wala, kung mas mababa sa 0.08 porsyento","Masususpinde ang lisensya nang hindi bababa sa isang taon"],"h1":"Zero tolerance ang Maine para sa mga batang driver.","h2":"Sa Maine, ang driver na wala pang 21 na may kahit anong dami ng alak ay mawawalan ng lisensya nang hindi bababa sa isang taon.","p":"Tama. Wala pang 21, kahit kaunting alak ay pagkawala ng lisensya nang hindi bababa sa isang taon."},"ar":{"q":"في Maine، ماذا يحدث للسائق الذي عمره أقل من 21 سنة إذا وُجد يقود مع أي كمية كحول يمكن قياسها؟","o":["تحذير فقط","إيقاف الرخصة 30 يومًا","لا شيء، إذا كانت أقل من 0.08 بالمئة","تُوقف الرخصة سنة واحدة على الأقل"],"h1":"Maine لا تتسامح أبدًا (zero tolerance) مع السائقين الشباب.","h2":"في Maine السائق الذي عمره أقل من 21 سنة ومعه أي كمية من الكحول يفقد رخصته سنة واحدة على الأقل.","p":"صحيح. تحت 21 سنة، أي كمية كحول تعني فقدان الرخصة سنة على الأقل."},"ref":{"doc":"ME","page":"3-14"}},{"id":"me-014","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, during which hours may a newly licensed driver under 18 not drive?","o":["From 9 p.m. to 5 a.m.","From 10 p.m. to 6 a.m.","From 12 a.m. to 5 a.m.","From 1 a.m. to 6 a.m."],"h1":"The limit starts at midnight.","h2":"In Maine, a licensed driver under 18 may not drive between 12 a.m. and 5 a.m. during the first 270 days.","p":"Right. No driving from midnight to 5 a.m."},"es":{"q":"En Maine, ¿en qué horario no puede manejar un conductor menor de 18 años con licencia nueva?","o":["De 9 p.m. a 5 a.m.","De 10 p.m. a 6 a.m.","De 12 a.m. a 5 a.m.","De 1 a.m. a 6 a.m."],"h1":"El límite empieza a la medianoche.","h2":"En Maine, un conductor con licencia menor de 18 años no puede manejar entre las 12 a.m. y las 5 a.m. durante los primeros 270 días.","p":"Correcto. No se maneja de la medianoche a las 5 a.m."},"zh":{"q":"在 Maine，18 岁以下刚拿到驾照的司机在哪些时间不能开车？","o":["晚上 9 点到早上 5 点","晚上 10 点到早上 6 点","午夜 12 点到早上 5 点","凌晨 1 点到早上 6 点"],"h1":"这个限制从午夜开始。","h2":"在 Maine，18 岁以下有驾照的司机在头 270 天里，午夜 12 点到早上 5 点之间不能开车。","p":"对。午夜到早上 5 点不能开车。"},"vi":{"q":"Ở Maine, người lái xe dưới 18 tuổi mới có bằng lái không được lái xe vào những giờ nào?","o":["Từ 9 giờ tối đến 5 giờ sáng","Từ 10 giờ tối đến 6 giờ sáng","Từ 12 giờ đêm đến 5 giờ sáng","Từ 1 giờ sáng đến 6 giờ sáng"],"h1":"Giới hạn bắt đầu lúc nửa đêm.","h2":"Ở Maine, người lái xe dưới 18 tuổi có bằng lái không được lái xe từ 12 giờ đêm đến 5 giờ sáng trong 270 ngày đầu tiên.","p":"Đúng. Không được lái xe từ nửa đêm đến 5 giờ sáng."},"tl":{"q":"Sa Maine, anong oras bawal magmaneho ang bagong lisensyadong driver na wala pang 18?","o":["Mula 9 p.m. hanggang 5 a.m.","Mula 10 p.m. hanggang 6 a.m.","Mula 12 a.m. hanggang 5 a.m.","Mula 1 a.m. hanggang 6 a.m."],"h1":"Nagsisimula ang limitasyon sa hatinggabi.","h2":"Sa Maine, ang lisensyadong driver na wala pang 18 ay bawal magmaneho mula 12 a.m. hanggang 5 a.m. sa unang 270 araw.","p":"Tama. Bawal magmaneho mula hatinggabi hanggang 5 a.m."},"ar":{"q":"في Maine، في أي ساعات لا يجوز للسائق الجديد الذي عمره أقل من 18 سنة أن يقود؟","o":["من 9 مساءً إلى 5 صباحًا","من 10 مساءً إلى 6 صباحًا","من 12 منتصف الليل إلى 5 صباحًا","من 1 صباحًا إلى 6 صباحًا"],"h1":"يبدأ المنع عند منتصف الليل.","h2":"في Maine لا يجوز للسائق الذي يحمل رخصة وعمره أقل من 18 سنة أن يقود بين 12 منتصف الليل و5 صباحًا خلال أول 270 يومًا.","p":"صحيح. لا قيادة من منتصف الليل إلى 5 صباحًا."},"ref":{"doc":"ME","page":"1-4"}},{"id":"me-015","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, how long is the first license of a new driver under 21 provisional?","o":["2 years","6 months","1 year","3 years"],"h1":"It is longer than for a new driver who is 21 or older.","h2":"In Maine, the first license of a new driver under 21 is provisional for 2 years. For a new driver 21 or older, it is 1 year.","p":"Right. The provisional period is 2 years for drivers under 21."},"es":{"q":"En Maine, ¿por cuánto tiempo es provisional la primera licencia de un conductor nuevo menor de 21 años?","o":["2 años","6 meses","1 año","3 años"],"h1":"Es más tiempo que para un conductor nuevo de 21 años o más.","h2":"En Maine, la primera licencia de un conductor nuevo menor de 21 años es provisional por 2 años. Para un conductor nuevo de 21 años o más, es 1 año.","p":"Correcto. El periodo provisional es de 2 años para menores de 21."},"zh":{"q":"在 Maine，21 岁以下新司机的第一张驾照是临时驾照（provisional）多久？","o":["2 年","6 个月","1 年","3 年"],"h1":"它比 21 岁或以上的新司机更长。","h2":"在 Maine，21 岁以下新司机的第一张驾照有 2 年是临时驾照。21 岁或以上的新司机是 1 年。","p":"对。21 岁以下的司机，临时期是 2 年。"},"vi":{"q":"Ở Maine, bằng lái đầu tiên của người lái xe mới dưới 21 tuổi là bằng tạm thời (provisional) trong bao lâu?","o":["2 năm","6 tháng","1 năm","3 năm"],"h1":"Thời gian này dài hơn so với người lái xe mới từ 21 tuổi trở lên.","h2":"Ở Maine, bằng lái đầu tiên của người lái xe mới dưới 21 tuổi là bằng tạm thời trong 2 năm. Với người lái xe mới từ 21 tuổi trở lên, thời gian là 1 năm.","p":"Đúng. Thời gian tạm thời là 2 năm cho người lái xe dưới 21 tuổi."},"tl":{"q":"Sa Maine, gaano katagal provisional ang unang lisensya ng bagong driver na wala pang 21?","o":["2 taon","6 na buwan","1 taon","3 taon"],"h1":"Mas matagal ito kaysa sa bagong driver na 21 pataas.","h2":"Sa Maine, ang unang lisensya ng bagong driver na wala pang 21 ay provisional nang 2 taon. Para sa bagong driver na 21 pataas, 1 taon ito.","p":"Tama. 2 taon ang provisional na panahon para sa mga driver na wala pang 21."},"ar":{"q":"في Maine، كم مدة تكون الرخصة الأولى للسائق الجديد الذي عمره أقل من 21 سنة رخصة مؤقتة (provisional)؟","o":["سنتان (2)","6 أشهر","سنة واحدة (1)","3 سنوات"],"h1":"هذه المدة أطول منها للسائق الجديد الذي عمره 21 سنة أو أكثر.","h2":"في Maine تكون الرخصة الأولى للسائق الجديد الذي عمره أقل من 21 سنة رخصة مؤقتة لمدة سنتين (2). أما للسائق الجديد الذي عمره 21 سنة أو أكثر فالمدة سنة واحدة (1).","p":"صحيح. المدة المؤقتة سنتان (2) للسائقين الذين أعمارهم أقل من 21 سنة."},"ref":{"doc":"ME","page":"1-4"}},{"id":"me-016","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, what happens the first time a driver with a provisional license is convicted of a moving violation?","o":["Only a written warning","A 10-day suspension","A 1-year suspension","A 30-day suspension"],"h1":"It is about one month without driving.","h2":"In Maine, a first moving violation on a provisional license leads to a 30-day license suspension. Later offenses bring tougher penalties.","p":"Right. The license is suspended for 30 days."},"es":{"q":"En Maine, ¿qué pasa la primera vez que un conductor con licencia provisional es condenado por una infracción de tránsito en movimiento?","o":["Solo una advertencia escrita","Una suspensión de 10 días","Una suspensión de 1 año","Una suspensión de 30 días"],"h1":"Es como un mes sin manejar.","h2":"En Maine, una primera infracción en movimiento con licencia provisional lleva a una suspensión de la licencia por 30 días. Las siguientes infracciones tienen castigos más duros.","p":"Correcto. La licencia se suspende por 30 días."},"zh":{"q":"在 Maine，持临时驾照的司机第一次因行车违规被定罪，会怎样？","o":["只有书面警告","暂停驾照 10 天","暂停驾照 1 年","暂停驾照 30 天"],"h1":"大约一个月不能开车。","h2":"在 Maine，持临时驾照的人第一次行车违规，驾照会被暂停 30 天。以后再违规，处罚会更重。","p":"对。驾照被暂停 30 天。"},"vi":{"q":"Ở Maine, điều gì xảy ra khi người có bằng lái tạm thời (provisional) bị kết tội vi phạm khi đang lái xe lần đầu tiên?","o":["Chỉ bị cảnh cáo bằng văn bản","Bị đình chỉ 10 ngày","Bị đình chỉ 1 năm","Bị đình chỉ 30 ngày"],"h1":"Khoảng một tháng không được lái xe.","h2":"Ở Maine, vi phạm khi đang lái xe lần đầu với bằng lái tạm thời sẽ bị đình chỉ bằng lái 30 ngày. Các lần vi phạm sau sẽ bị phạt nặng hơn.","p":"Đúng. Bằng lái bị đình chỉ 30 ngày."},"tl":{"q":"Sa Maine, ano ang mangyayari sa unang beses na mahatulan ang driver na may provisional license ng moving violation?","o":["Nakasulat na babala lang","10 araw na suspensyon","1 taon na suspensyon","30 araw na suspensyon"],"h1":"Mga isang buwan ito na walang pagmamaneho.","h2":"Sa Maine, ang unang moving violation sa provisional license ay nagdudulot ng 30 araw na suspensyon ng lisensya. Mas mabigat ang parusa sa mga susunod na paglabag.","p":"Tama. Masususpinde ang lisensya nang 30 araw."},"ar":{"q":"في Maine، ماذا يحدث في المرة الأولى التي يُدان فيها سائق يحمل رخصة مؤقتة (provisional) بمخالفة أثناء القيادة؟","o":["تحذير مكتوب فقط","إيقاف الرخصة 10 أيام","إيقاف الرخصة سنة واحدة (1)","إيقاف الرخصة 30 يومًا"],"h1":"إنها حوالي شهر واحد بدون قيادة.","h2":"في Maine تؤدي أول مخالفة أثناء القيادة برخصة مؤقتة إلى إيقاف الرخصة 30 يومًا. والمخالفات التالية عقوبتها أشد.","p":"صحيح. تُوقف الرخصة 30 يومًا."},"ref":{"doc":"ME","page":"1-4"}},{"id":"me-017","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, how many demerit points lead to a license suspension?","o":["6 points","12 points","18 points","24 points"],"h1":"A warning comes at half this number.","h2":"In Maine, a driver whose record reaches 12 or more demerit points has the license suspended. A warning is sent at 6 points.","p":"Right. 12 points means a suspension."},"es":{"q":"En Maine, ¿cuántos puntos de demérito llevan a la suspensión de la licencia?","o":["6 puntos","12 puntos","18 puntos","24 puntos"],"h1":"Se envía una advertencia a la mitad de este número.","h2":"En Maine, si el récord de un conductor llega a 12 puntos de demérito o más, su licencia se suspende. Se envía una advertencia a los 6 puntos.","p":"Correcto. 12 puntos significan una suspensión."},"zh":{"q":"在 Maine，多少扣分（demerit points）会导致驾照被暂停？","o":["6 分","12 分","18 分","24 分"],"h1":"到这个数字的一半时会收到警告。","h2":"在 Maine，司机的记录达到 12 分或更多，驾照就会被暂停。到 6 分时会寄来警告。","p":"对。12 分就会被暂停驾照。"},"vi":{"q":"Ở Maine, bao nhiêu điểm phạt (demerit points) thì bị đình chỉ bằng lái?","o":["6 điểm","12 điểm","18 điểm","24 điểm"],"h1":"Bạn bị cảnh cáo khi có một nửa số điểm này.","h2":"Ở Maine, người lái xe có hồ sơ từ 12 điểm phạt trở lên sẽ bị đình chỉ bằng lái. Thư cảnh cáo được gửi khi có 6 điểm.","p":"Đúng. 12 điểm thì bị đình chỉ."},"tl":{"q":"Sa Maine, ilang demerit point ang nagdudulot ng suspensyon ng lisensya?","o":["6 na puntos","12 puntos","18 puntos","24 na puntos"],"h1":"May babala sa kalahati ng numerong ito.","h2":"Sa Maine, ang driver na umabot sa 12 o higit pang demerit point sa record ay masususpinde ang lisensya. May babalang ipinapadala sa 6 na puntos.","p":"Tama. Ang 12 puntos ay suspensyon."},"ar":{"q":"في Maine، كم نقطة مخالفة (demerit points) تؤدي إلى إيقاف الرخصة؟","o":["6 نقاط","12 نقطة","18 نقطة","24 نقطة"],"h1":"يأتي التحذير عند نصف هذا العدد.","h2":"في Maine السائق الذي يصل سجله إلى 12 نقطة مخالفة أو أكثر تُوقف رخصته. ويُرسَل تحذير عند 6 نقاط.","p":"صحيح. 12 نقطة تعني إيقاف الرخصة."},"ref":{"doc":"ME","page":"1-9"}},{"id":"me-018","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, when are demerit points removed from a driver's record?","o":["After 6 months","Never","When they are one year old","After 5 years"],"h1":"Points in Maine do not last long.","h2":"In Maine, demerit points are removed from a driver's record when they are one year old.","p":"Right. Points drop off after one year."},"es":{"q":"En Maine, ¿cuándo se borran los puntos de demérito del récord de un conductor?","o":["Después de 6 meses","Nunca","Cuando cumplen un año","Después de 5 años"],"h1":"En Maine los puntos no duran mucho.","h2":"En Maine, los puntos de demérito se borran del récord del conductor cuando cumplen un año.","p":"Correcto. Los puntos se borran después de un año."},"zh":{"q":"在 Maine，扣分什么时候会从司机的记录中删除？","o":["6 个月以后","永远不会","满一年的时候","5 年以后"],"h1":"Maine 的扣分不会保留很久。","h2":"在 Maine，扣分满一年时就会从司机的记录中删除。","p":"对。扣分一年后就会删除。"},"vi":{"q":"Ở Maine, khi nào điểm phạt được xóa khỏi hồ sơ của người lái xe?","o":["Sau 6 tháng","Không bao giờ","Khi điểm đã được một năm","Sau 5 năm"],"h1":"Điểm phạt ở Maine không giữ lâu.","h2":"Ở Maine, điểm phạt được xóa khỏi hồ sơ của người lái xe khi điểm đã được một năm.","p":"Đúng. Điểm phạt được xóa sau một năm."},"tl":{"q":"Sa Maine, kailan inaalis ang demerit point sa record ng driver?","o":["Pagkatapos ng 6 na buwan","Hindi kailanman","Kapag isang taon na ang mga ito","Pagkatapos ng 5 taon"],"h1":"Hindi nagtatagal ang mga puntos sa Maine.","h2":"Sa Maine, inaalis ang demerit point sa record ng driver kapag isang taon na ang mga ito.","p":"Tama. Nawawala ang mga puntos pagkatapos ng isang taon."},"ar":{"q":"في Maine، متى تُحذف نقاط المخالفة من سجل السائق؟","o":["بعد 6 أشهر","لا تُحذف أبدًا","عندما يمر عليها سنة واحدة","بعد 5 سنوات"],"h1":"النقاط في Maine لا تبقى مدة طويلة.","h2":"في Maine تُحذف نقاط المخالفة من سجل السائق عندما يمر عليها سنة واحدة.","p":"صحيح. تُحذف النقاط بعد سنة واحدة."},"ref":{"doc":"ME","page":"1-9"}},{"id":"me-019","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, how many points are taken off a driver's record for finishing an approved driver improvement course?","o":["3 points","1 point","6 points","All points"],"h1":"It is a small number, and it can happen only once in 12 months.","h2":"In Maine, finishing the Maine Driving Dynamics Course or another approved driver improvement course takes 3 points off your total, once in any 12 months.","p":"Right. The course removes 3 points."},"es":{"q":"En Maine, ¿cuántos puntos se quitan del récord por terminar un curso aprobado de mejoramiento para conductores?","o":["3 puntos","1 punto","6 puntos","Todos los puntos"],"h1":"Es un número pequeño y solo se puede hacer una vez cada 12 meses.","h2":"En Maine, terminar el curso Maine Driving Dynamics u otro curso aprobado de mejoramiento le quita 3 puntos de su total, una vez en cualquier periodo de 12 meses.","p":"Correcto. El curso quita 3 puntos."},"zh":{"q":"在 Maine，完成一门批准的驾驶改进课程，可以从司机的记录中减掉几分？","o":["3 分","1 分","6 分","全部的分"],"h1":"这是一个小数字，而且 12 个月里只能有一次。","h2":"在 Maine，完成 Maine Driving Dynamics Course 或其他批准的驾驶改进课程，可以从总分中减掉 3 分，任何 12 个月内只能一次。","p":"对。这门课程可以减掉 3 分。"},"vi":{"q":"Ở Maine, hoàn thành một khóa cải thiện kỹ năng lái xe được chấp thuận sẽ được trừ bao nhiêu điểm trong hồ sơ của người lái xe?","o":["3 điểm","1 điểm","6 điểm","Tất cả các điểm"],"h1":"Đó là một số nhỏ, và chỉ được một lần trong 12 tháng.","h2":"Ở Maine, hoàn thành Maine Driving Dynamics Course hoặc một khóa cải thiện kỹ năng lái xe khác được chấp thuận sẽ trừ 3 điểm trong tổng số điểm của bạn, một lần trong bất kỳ 12 tháng nào.","p":"Đúng. Khóa học trừ 3 điểm."},"tl":{"q":"Sa Maine, ilang puntos ang inaalis sa record ng driver kapag natapos ang aprubadong driver improvement course?","o":["3 puntos","1 punto","6 na puntos","Lahat ng puntos"],"h1":"Maliit na numero ito, at isang beses lang puwede sa loob ng 12 buwan.","h2":"Sa Maine, ang pagtatapos ng Maine Driving Dynamics Course o ibang aprubadong driver improvement course ay nag-aalis ng 3 puntos sa iyong kabuuan, isang beses sa anumang 12 buwan.","p":"Tama. Nag-aalis ang kurso ng 3 puntos."},"ar":{"q":"في Maine، كم نقطة تُحذف من سجل السائق عند إنهاء دورة معتمدة لتحسين القيادة؟","o":["3 نقاط","نقطة واحدة (1)","6 نقاط","كل النقاط"],"h1":"إنه عدد صغير، ولا يمكن أن يحدث إلا مرة واحدة في 12 شهرًا.","h2":"في Maine إنهاء دورة Maine Driving Dynamics Course أو دورة أخرى معتمدة لتحسين القيادة يحذف 3 نقاط من مجموع نقاطك، مرة واحدة في أي 12 شهرًا.","p":"صحيح. الدورة تحذف 3 نقاط."},"ref":{"doc":"ME","page":"1-9"}},{"id":"me-020","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, how soon must you tell the Bureau of Motor Vehicles that your name or address has changed?","o":["Within 7 days","Within 10 days","Within 90 days","Within 30 days"],"h1":"You have about one month.","h2":"In Maine, you must tell the Bureau of Motor Vehicles within 30 days after your name or address changes.","p":"Right. You have 30 days to report the change."},"es":{"q":"En Maine, ¿en cuánto tiempo debe avisar a la Oficina de Vehículos Motorizados (BMV) si cambió su nombre o dirección?","o":["En 7 días","En 10 días","En 90 días","En 30 días"],"h1":"Tiene más o menos un mes.","h2":"En Maine, usted debe avisar a la Oficina de Vehículos Motorizados (BMV) dentro de los 30 días después de cambiar su nombre o dirección.","p":"Correcto. Tiene 30 días para avisar del cambio."},"zh":{"q":"在 Maine，你的名字或地址改变后，必须在多久内告诉 Bureau of Motor Vehicles（机动车管理局）？","o":["7 天内","10 天内","90 天内","30 天内"],"h1":"你大约有一个月的时间。","h2":"在 Maine，你的名字或地址改变后，必须在 30 天内告诉 Bureau of Motor Vehicles。","p":"对。你有 30 天的时间报告这个改变。"},"vi":{"q":"Ở Maine, bạn phải báo cho Bureau of Motor Vehicles (Sở Xe Cơ Giới) trong bao lâu khi bạn đổi tên hoặc địa chỉ?","o":["Trong vòng 7 ngày","Trong vòng 10 ngày","Trong vòng 90 ngày","Trong vòng 30 ngày"],"h1":"Bạn có khoảng một tháng.","h2":"Ở Maine, bạn phải báo cho Bureau of Motor Vehicles trong vòng 30 ngày sau khi bạn đổi tên hoặc địa chỉ.","p":"Đúng. Bạn có 30 ngày để báo thay đổi."},"tl":{"q":"Sa Maine, gaano kabilis mo dapat sabihin sa Bureau of Motor Vehicles na nagbago ang pangalan o address mo?","o":["Sa loob ng 7 araw","Sa loob ng 10 araw","Sa loob ng 90 araw","Sa loob ng 30 araw"],"h1":"Mga isang buwan ang mayroon ka.","h2":"Sa Maine, dapat mong sabihin sa Bureau of Motor Vehicles sa loob ng 30 araw pagkatapos magbago ang pangalan o address mo.","p":"Tama. May 30 araw ka para iulat ang pagbabago."},"ar":{"q":"في Maine، خلال كم من الوقت يجب أن تُبلغ Bureau of Motor Vehicles (مكتب المركبات) بأن اسمك أو عنوانك قد تغيّر؟","o":["خلال 7 أيام","خلال 10 أيام","خلال 90 يومًا","خلال 30 يومًا"],"h1":"لديك حوالي شهر واحد.","h2":"في Maine يجب أن تُبلغ Bureau of Motor Vehicles خلال 30 يومًا بعد تغيّر اسمك أو عنوانك.","p":"صحيح. لديك 30 يومًا للإبلاغ عن التغيير."},"ref":{"doc":"ME","page":"1-6"}},{"id":"me-021","scope":"ME","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maine, an adult is convicted of OUI for the first time with an alcohol level of 0.08 to 0.14. How long is the license lost?","o":["At least 30 days","At least 150 days","At least 2 years","At least 5 years"],"h1":"It is about five months.","h2":"In Maine, a first OUI conviction with an alcohol level of 0.08 to 0.14 means losing the license for at least 150 days, plus a fine of at least $500.","p":"Right. The license is lost for at least 150 days."},"es":{"q":"En Maine, un adulto es condenado por primera vez por manejar bajo la influencia (OUI) con un nivel de alcohol de 0.08 a 0.14. ¿Por cuánto tiempo pierde la licencia?","o":["Por lo menos 30 días","Por lo menos 150 días","Por lo menos 2 años","Por lo menos 5 años"],"h1":"Son como cinco meses.","h2":"En Maine, una primera condena por OUI con un nivel de alcohol de 0.08 a 0.14 significa perder la licencia por lo menos 150 días, además de una multa de por lo menos $500.","p":"Correcto. Se pierde la licencia por lo menos 150 días."},"zh":{"q":"在 Maine，一个成年人第一次因酒后或药后驾驶（OUI）被定罪，酒精浓度是 0.08 到 0.14。会失去驾照多久？","o":["至少 30 天","至少 150 天","至少 2 年","至少 5 年"],"h1":"大约五个月。","h2":"在 Maine，第一次 OUI 定罪、酒精浓度 0.08 到 0.14，会失去驾照至少 150 天，还要罚款至少 $500。","p":"对。驾照会失去至少 150 天。"},"vi":{"q":"Ở Maine, một người lớn bị kết tội lái xe khi say rượu hoặc dùng chất kích thích (OUI) lần đầu với nồng độ cồn từ 0.08 đến 0.14. Bằng lái bị mất bao lâu?","o":["Ít nhất 30 ngày","Ít nhất 150 ngày","Ít nhất 2 năm","Ít nhất 5 năm"],"h1":"Khoảng năm tháng.","h2":"Ở Maine, bị kết tội OUI lần đầu với nồng độ cồn từ 0.08 đến 0.14 sẽ mất bằng lái ít nhất 150 ngày, cộng với tiền phạt ít nhất $500.","p":"Đúng. Bằng lái bị mất ít nhất 150 ngày."},"tl":{"q":"Sa Maine, nahatulan ang isang adult ng OUI (pagmamaneho nang lasing o lango) sa unang pagkakataon na may alcohol level na 0.08 hanggang 0.14. Gaano katagal mawawala ang lisensya?","o":["Hindi bababa sa 30 araw","Hindi bababa sa 150 araw","Hindi bababa sa 2 taon","Hindi bababa sa 5 taon"],"h1":"Mga limang buwan ito.","h2":"Sa Maine, ang unang hatol ng OUI na may alcohol level na 0.08 hanggang 0.14 ay nangangahulugang mawawala ang lisensya nang hindi bababa sa 150 araw, at multang hindi bababa sa $500.","p":"Tama. Mawawala ang lisensya nang hindi bababa sa 150 araw."},"ar":{"q":"في Maine، أُدين شخص بالغ لأول مرة بالقيادة تحت تأثير الكحول أو المخدرات (OUI) ونسبة الكحول عنده من 0.08 إلى 0.14. كم مدة يفقد الرخصة؟","o":["30 يومًا على الأقل","150 يومًا على الأقل","سنتان (2) على الأقل","5 سنوات على الأقل"],"h1":"إنها حوالي خمسة أشهر.","h2":"في Maine أول إدانة بـ OUI مع نسبة كحول من 0.08 إلى 0.14 تعني فقدان الرخصة 150 يومًا على الأقل، بالإضافة إلى غرامة لا تقل عن $500.","p":"صحيح. يفقد الرخصة 150 يومًا على الأقل."},"ref":{"doc":"ME","page":"3-10"}},{"id":"me-022","scope":"ME","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maine, when must the drivers in a crash report it to the police or sheriff?","o":["Only if a car must be towed","Only if a driver gets a ticket","If anyone is hurt or damage is $2,000 or more","If damage is $500 or more"],"h1":"Think about injuries and the cost of the damage.","h2":"In Maine, a crash must be reported to the police or sheriff if anyone is hurt or if the property damage is $2,000 or more.","p":"Right. Injury or $2,000 in damage means you must report it."},"es":{"q":"En Maine, ¿cuándo deben los conductores de un choque reportarlo a la policía o al sheriff?","o":["Solo si hay que remolcar un carro","Solo si un conductor recibe una multa","Si alguien sale herido o el daño es de $2,000 o más","Si el daño es de $500 o más"],"h1":"Piense en los heridos y en el costo del daño.","h2":"En Maine, un choque se debe reportar a la policía o al sheriff si alguien sale herido o si el daño a la propiedad es de $2,000 o más.","p":"Correcto. Con heridos o $2,000 de daño, hay que reportarlo."},"zh":{"q":"在 Maine，发生车祸后，司机在什么情况下必须向警察或警长（sheriff）报告？","o":["只有车子必须被拖走时","只有司机拿到罚单时","有人受伤，或损失达到 $2,000 或更多时","损失达到 $500 或更多时"],"h1":"想一想受伤和损失的费用。","h2":"在 Maine，如果有人受伤，或者财产损失达到 $2,000 或更多，就必须向警察或警长报告车祸。","p":"对。有人受伤或损失达到 $2,000，就必须报告。"},"vi":{"q":"Ở Maine, khi nào những người lái xe trong một vụ tai nạn phải báo cho cảnh sát hoặc cảnh sát quận (sheriff)?","o":["Chỉ khi xe phải bị kéo đi","Chỉ khi một người lái xe bị phạt","Nếu có người bị thương hoặc thiệt hại từ $2,000 trở lên","Nếu thiệt hại từ $500 trở lên"],"h1":"Hãy nghĩ đến người bị thương và chi phí thiệt hại.","h2":"Ở Maine, phải báo vụ tai nạn cho cảnh sát hoặc cảnh sát quận nếu có người bị thương hoặc nếu thiệt hại tài sản từ $2,000 trở lên.","p":"Đúng. Có người bị thương hoặc thiệt hại $2,000 thì bạn phải báo."},"tl":{"q":"Sa Maine, kailan dapat iulat ng mga driver sa isang banggaan ito sa pulis o sheriff?","o":["Kung kailangang i-tow ang kotse lang","Kung may driver na na-ticket lang","Kung may nasaktan o ang pinsala ay $2,000 o higit pa","Kung ang pinsala ay $500 o higit pa"],"h1":"Isipin ang mga pinsala sa tao at ang halaga ng sira.","h2":"Sa Maine, dapat iulat sa pulis o sheriff ang banggaan kung may nasaktan o kung ang pinsala sa ari-arian ay $2,000 o higit pa.","p":"Tama. Kapag may nasaktan o $2,000 ang pinsala, dapat mo itong iulat."},"ar":{"q":"في Maine، متى يجب على السائقين في حادث أن يبلّغوا الشرطة أو الشريف (sheriff)؟","o":["فقط إذا كان يجب سحب سيارة","فقط إذا حصل سائق على مخالفة","إذا أُصيب أحد أو كان الضرر $2,000 أو أكثر","إذا كان الضرر $500 أو أكثر"],"h1":"فكّر في الإصابات وفي تكلفة الضرر.","h2":"في Maine يجب إبلاغ الشرطة أو الشريف عن الحادث إذا أُصيب أحد أو إذا كان الضرر في الممتلكات $2,000 أو أكثر.","p":"صحيح. إصابة أو ضرر بقيمة $2,000 يعني أنه يجب عليك الإبلاغ."},"ref":{"doc":"ME","page":"9-3"}},{"id":"me-023","scope":"ME","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maine, when must you turn on your headlights during the day?","o":["When your wipers are on all the time","Only on the highway","Only when it is snowing","Only after 4 p.m."],"h1":"Think about rainy, gray days.","h2":"In Maine, you must turn on your headlights whenever your windshield wipers are in constant use, or when you cannot see 1,000 feet ahead.","p":"Right. Wipers on means headlights on."},"es":{"q":"En Maine, ¿cuándo debe encender las luces delanteras durante el día?","o":["Cuando los limpiaparabrisas están siempre prendidos","Solo en la autopista","Solo cuando está nevando","Solo después de las 4 p.m."],"h1":"Piense en los días grises y de lluvia.","h2":"En Maine, usted debe encender las luces delanteras cada vez que use los limpiaparabrisas sin parar, o cuando no pueda ver a 1,000 pies adelante.","p":"Correcto. Limpiaparabrisas prendidos, luces prendidas."},"zh":{"q":"在 Maine，白天什么时候必须开大灯？","o":["雨刷一直开着的时候","只在高速公路上","只在下雪的时候","只在下午 4 点以后"],"h1":"想一想下雨、阴暗的日子。","h2":"在 Maine，只要挡风玻璃的雨刷一直在用，或者你看不清前方 1,000 英尺，就必须开大灯。","p":"对。开雨刷就要开大灯。"},"vi":{"q":"Ở Maine, khi nào bạn phải bật đèn pha vào ban ngày?","o":["Khi cần gạt nước của bạn bật liên tục","Chỉ trên xa lộ","Chỉ khi trời có tuyết","Chỉ sau 4 giờ chiều"],"h1":"Hãy nghĩ đến những ngày mưa, trời xám.","h2":"Ở Maine, bạn phải bật đèn pha bất cứ khi nào cần gạt nước kính chắn gió được dùng liên tục, hoặc khi bạn không thể nhìn thấy 1,000 feet phía trước.","p":"Đúng. Bật cần gạt nước thì bật đèn pha."},"tl":{"q":"Sa Maine, kailan mo dapat buksan ang headlights sa araw?","o":["Kapag tuloy-tuloy na nakabukas ang wipers mo","Sa highway lang","Kapag umuulan ng niyebe lang","Pagkatapos ng 4 p.m. lang"],"h1":"Isipin ang maulan at makulimlim na mga araw.","h2":"Sa Maine, dapat mong buksan ang headlights tuwing tuloy-tuloy na ginagamit ang windshield wipers, o kapag hindi mo makita ang 1,000 feet sa unahan.","p":"Tama. Kapag bukas ang wipers, bukas din ang headlights."},"ar":{"q":"في Maine، متى يجب أن تشغّل المصابيح الأمامية أثناء النهار؟","o":["عندما تكون المسّاحات تعمل طوال الوقت","على الطريق السريع فقط","عندما يتساقط الثلج فقط","بعد 4 مساءً فقط"],"h1":"فكّر في الأيام الماطرة والرمادية.","h2":"في Maine يجب أن تشغّل المصابيح الأمامية كلما كانت مسّاحات الزجاج الأمامي تعمل بشكل مستمر، أو عندما لا تستطيع أن ترى 1,000 قدم أمامك.","p":"صحيح. المسّاحات تعمل يعني المصابيح الأمامية تعمل."},"ref":{"doc":"ME","page":"8-16"}},{"id":"me-024","scope":"ME","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Maine, what is the top speed outside a business, residential or built-up area when no speed limit is posted?","o":["35 mph","55 mph","65 mph","45 mph"],"h1":"It is 20 mph more than the limit in town.","h2":"In Maine, unless a sign says otherwise, the top speed outside business, residential and built-up areas is 45 mph.","p":"Right. The unposted limit outside town is 45 mph."},"es":{"q":"En Maine, ¿cuál es la velocidad máxima fuera de una zona comercial, residencial o poblada cuando no hay un límite señalado?","o":["35 mph","55 mph","65 mph","45 mph"],"h1":"Son 20 mph más que el límite en el pueblo.","h2":"En Maine, a menos que una señal diga otra cosa, la velocidad máxima fuera de zonas comerciales, residenciales y pobladas es de 45 mph.","p":"Correcto. Sin señal, el límite fuera del pueblo es de 45 mph."},"zh":{"q":"在 Maine，在商业区、住宅区或建成区以外，没有限速标志时，最高车速是多少？","o":["35 mph","55 mph","65 mph","45 mph"],"h1":"它比镇上的限速多 20 mph。","h2":"在 Maine，除非标志另有规定，在商业区、住宅区和建成区以外，最高车速是 45 mph。","p":"对。镇外没有标志时，限速是 45 mph。"},"vi":{"q":"Ở Maine, tốc độ tối đa bên ngoài khu thương mại, khu dân cư hoặc khu đông nhà cửa là bao nhiêu khi không có biển giới hạn tốc độ?","o":["35 mph","55 mph","65 mph","45 mph"],"h1":"Nhiều hơn giới hạn trong thị trấn 20 mph.","h2":"Ở Maine, trừ khi có biển báo khác, tốc độ tối đa bên ngoài khu thương mại, khu dân cư và khu đông nhà cửa là 45 mph.","p":"Đúng. Giới hạn khi không có biển báo bên ngoài thị trấn là 45 mph."},"tl":{"q":"Sa Maine, ano ang pinakamataas na bilis sa labas ng business, residential o built-up area kapag walang nakapaskil na speed limit?","o":["35 mph","55 mph","65 mph","45 mph"],"h1":"Mas mataas ito nang 20 mph kaysa sa limit sa bayan.","h2":"Sa Maine, maliban kung iba ang sinasabi ng karatula, ang pinakamataas na bilis sa labas ng business, residential at built-up area ay 45 mph.","p":"Tama. 45 mph ang limit sa labas ng bayan kapag walang karatula."},"ar":{"q":"في Maine، ما أقصى سرعة خارج المناطق التجارية أو السكنية أو المبنية عندما لا تكون هناك لافتة لحد السرعة؟","o":["35 mph","55 mph","65 mph","45 mph"],"h1":"إنها أكثر من الحد داخل البلدة بـ 20 mph.","h2":"في Maine، إلا إذا قالت لافتة غير ذلك، أقصى سرعة خارج المناطق التجارية والسكنية والمبنية هي 45 mph.","p":"صحيح. الحد بدون لافتة خارج البلدة هو 45 mph."},"ref":{"doc":"ME","page":"8-7"}},{"id":"me-025","scope":"ME","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maine, a child must ride in a child safety seat if the child weighs less than how much?","o":["40 pounds","55 pounds","80 pounds","100 pounds"],"h1":"It is a little more than 50 pounds.","h2":"In Maine, a child who weighs less than 55 pounds must be buckled into a child safety seat.","p":"Right. Under 55 pounds means a child safety seat."},"es":{"q":"En Maine, ¿por debajo de qué peso debe ir un niño en un asiento de seguridad infantil?","o":["40 libras","55 libras","80 libras","100 libras"],"h1":"Es un poco más de 50 libras.","h2":"En Maine, un niño que pesa menos de 55 libras debe ir abrochado en un asiento de seguridad infantil.","p":"Correcto. Menos de 55 libras significa asiento de seguridad infantil."},"zh":{"q":"在 Maine，孩子的体重低于多少时必须坐儿童安全座椅？","o":["40 磅","55 磅","80 磅","100 磅"],"h1":"比 50 磅多一点。","h2":"在 Maine，体重低于 55 磅的孩子必须系好坐在儿童安全座椅里。","p":"对。低于 55 磅就要坐儿童安全座椅。"},"vi":{"q":"Ở Maine, trẻ em phải ngồi ghế an toàn cho trẻ em nếu trẻ nặng dưới bao nhiêu?","o":["40 pound","55 pound","80 pound","100 pound"],"h1":"Hơn 50 pound một chút.","h2":"Ở Maine, trẻ em nặng dưới 55 pound phải được thắt dây trong ghế an toàn cho trẻ em.","p":"Đúng. Dưới 55 pound thì phải ngồi ghế an toàn cho trẻ em."},"tl":{"q":"Sa Maine, dapat sumakay ang bata sa child safety seat kung ang timbang niya ay mas mababa sa ilan?","o":["40 pounds","55 pounds","80 pounds","100 pounds"],"h1":"Medyo higit ito sa 50 pounds.","h2":"Sa Maine, ang batang mas mababa sa 55 pounds ang timbang ay dapat nakakabit sa child safety seat.","p":"Tama. Kapag mas mababa sa 55 pounds, child safety seat."},"ar":{"q":"في Maine، يجب أن يركب الطفل في مقعد أمان للأطفال إذا كان وزنه أقل من كم؟","o":["40 رطلًا","55 رطلًا","80 رطلًا","100 رطل"],"h1":"إنه أكثر قليلًا من 50 رطلًا.","h2":"في Maine يجب ربط الطفل الذي وزنه أقل من 55 رطلًا في مقعد أمان للأطفال.","p":"صحيح. أقل من 55 رطلًا يعني مقعد أمان للأطفال."},"ref":{"doc":"ME","page":"4-4"}},{"id":"me-026","scope":"ME","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Maine, a driver is convicted of passing a stopped school bus with its red lights flashing. How long may the license be suspended?","o":["7 days","1 year","30 days","6 months"],"h1":"It is about one month.","h2":"In Maine, a driver convicted of passing a stopped school bus with flashing red lights may have the license suspended for 30 days.","p":"Right. The suspension can be 30 days."},"es":{"q":"En Maine, un conductor es condenado por pasar un autobús escolar detenido con las luces rojas intermitentes. ¿Por cuánto tiempo se le puede suspender la licencia?","o":["7 días","1 año","30 días","6 meses"],"h1":"Es como un mes.","h2":"En Maine, a un conductor condenado por pasar un autobús escolar detenido con luces rojas intermitentes se le puede suspender la licencia por 30 días.","p":"Correcto. La suspensión puede ser de 30 días."},"zh":{"q":"在 Maine，一个司机因超过停着、红灯在闪的校车而被定罪。驾照可能被暂停多久？","o":["7 天","1 年","30 天","6 个月"],"h1":"大约一个月。","h2":"在 Maine，因超过停着、红灯在闪的校车而被定罪的司机，驾照可能被暂停 30 天。","p":"对。暂停可能是 30 天。"},"vi":{"q":"Ở Maine, một người lái xe bị kết tội vượt qua xe buýt trường học đang dừng và nhấp nháy đèn đỏ. Bằng lái có thể bị đình chỉ bao lâu?","o":["7 ngày","1 năm","30 ngày","6 tháng"],"h1":"Khoảng một tháng.","h2":"Ở Maine, người lái xe bị kết tội vượt qua xe buýt trường học đang dừng và nhấp nháy đèn đỏ có thể bị đình chỉ bằng lái 30 ngày.","p":"Đúng. Thời gian đình chỉ có thể là 30 ngày."},"tl":{"q":"Sa Maine, nahatulan ang isang driver ng paglampas sa nakahintong school bus na kumikislap ang pulang ilaw. Gaano katagal puwedeng masuspinde ang lisensya?","o":["7 araw","1 taon","30 araw","6 na buwan"],"h1":"Mga isang buwan ito.","h2":"Sa Maine, ang driver na nahatulan ng paglampas sa nakahintong school bus na kumikislap ang pulang ilaw ay puwedeng masuspinde ang lisensya nang 30 araw.","p":"Tama. Puwedeng 30 araw ang suspensyon."},"ar":{"q":"في Maine، أُدين سائق بتجاوز حافلة مدرسية متوقفة وأضواؤها الحمراء تومض. كم مدة يمكن أن تُوقف رخصته؟","o":["7 أيام","سنة واحدة (1)","30 يومًا","6 أشهر"],"h1":"إنها حوالي شهر واحد.","h2":"في Maine السائق الذي يُدان بتجاوز حافلة مدرسية متوقفة وأضواؤها الحمراء تومض يمكن أن تُوقف رخصته 30 يومًا.","p":"صحيح. يمكن أن يكون الإيقاف 30 يومًا."},"ref":{"doc":"ME","page":"1-8"}},{"id":"me-027","scope":"ME","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maine, how much space must you leave between your car and a bicycle when you pass it?","o":["1 foot","2 feet","3 feet","6 feet"],"h1":"Think of about one long step.","h2":"In Maine, you must leave at least 3 feet between the right side of your car and the bicycle when you pass it.","p":"Right. Leave at least 3 feet."},"es":{"q":"En Maine, ¿cuánto espacio debe dejar entre su carro y una bicicleta al pasarla?","o":["1 pie","2 pies","3 pies","6 pies"],"h1":"Piense en un paso largo.","h2":"En Maine, usted debe dejar por lo menos 3 pies entre el lado derecho de su carro y la bicicleta al pasarla.","p":"Correcto. Deje por lo menos 3 pies."},"zh":{"q":"在 Maine，超过自行车时，你的车和自行车之间必须留多少空间？","o":["1 英尺","2 英尺","3 英尺","6 英尺"],"h1":"大约是一大步的长度。","h2":"在 Maine，超过自行车时，你的车右侧和自行车之间必须至少留 3 英尺。","p":"对。至少留 3 英尺。"},"vi":{"q":"Ở Maine, khi vượt một xe đạp, bạn phải chừa bao nhiêu khoảng cách giữa xe của bạn và xe đạp?","o":["1 foot","2 feet","3 feet","6 feet"],"h1":"Hãy nghĩ đến khoảng một bước dài.","h2":"Ở Maine, khi vượt một xe đạp, bạn phải chừa ít nhất 3 feet giữa bên phải xe của bạn và xe đạp.","p":"Đúng. Hãy chừa ít nhất 3 feet."},"tl":{"q":"Sa Maine, gaano kalaking espasyo ang dapat mong iwan sa pagitan ng kotse mo at ng bisikleta kapag nilalampasan mo ito?","o":["1 talampakan","2 talampakan","3 talampakan","6 talampakan"],"h1":"Isipin ang isang mahabang hakbang.","h2":"Sa Maine, dapat kang mag-iwan ng hindi bababa sa 3 talampakan sa pagitan ng kanang gilid ng kotse mo at ng bisikleta kapag nilalampasan mo ito.","p":"Tama. Mag-iwan ng hindi bababa sa 3 talampakan."},"ar":{"q":"في Maine، كم مسافة يجب أن تتركها بين سيارتك والدراجة عندما تتجاوزها؟","o":["1 قدم","2 قدم","3 أقدام","6 أقدام"],"h1":"فكّر في خطوة واحدة طويلة تقريبًا.","h2":"في Maine، يجب أن تترك 3 أقدام على الأقل بين الجانب الأيمن لسيارتك والدراجة عندما تتجاوزها.","p":"صحيح. اترك 3 أقدام على الأقل."},"ref":{"doc":"ME","page":"7-8"}},{"id":"me-028","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, a driver under 65 gets a new picture license. Until when is it valid?","o":["Until the sixth birthday after it is issued","Until the second birthday after it is issued","Until the tenth birthday after it is issued","Until the end of the same year"],"h1":"It lasts several years, but less than ten.","h2":"In Maine, a picture license for a driver under 65 is valid until the sixth birthday after the date it is issued.","p":"Right. It lasts until the sixth birthday after it is issued."},"es":{"q":"En Maine, un conductor menor de 65 años recibe una licencia nueva con foto. ¿Hasta cuándo es válida?","o":["Hasta el sexto cumpleaños después de emitirla","Hasta el segundo cumpleaños después de emitirla","Hasta el décimo cumpleaños después de emitirla","Hasta el final del mismo año"],"h1":"Dura varios años, pero menos de diez.","h2":"En Maine, la licencia con foto de un conductor menor de 65 años es válida hasta el sexto cumpleaños después de la fecha en que se emite.","p":"Correcto. Dura hasta el sexto cumpleaños después de emitirla."},"zh":{"q":"在 Maine，一位未满 65 岁的司机拿到一张新的带照片的驾照。它有效到什么时候？","o":["到发证后的第六个生日","到发证后的第二个生日","到发证后的第十个生日","到同一年年底"],"h1":"它能用好几年，但不到十年。","h2":"在 Maine，未满 65 岁司机的带照片驾照，有效期到发证日期后的第六个生日。","p":"对。它有效到发证后的第六个生日。"},"vi":{"q":"Ở Maine, một người lái xe dưới 65 tuổi nhận bằng lái mới có ảnh. Bằng này có giá trị đến khi nào?","o":["Đến sinh nhật thứ sáu sau ngày cấp","Đến sinh nhật thứ hai sau ngày cấp","Đến sinh nhật thứ mười sau ngày cấp","Đến cuối cùng năm đó"],"h1":"Bằng dùng được vài năm, nhưng ít hơn mười năm.","h2":"Ở Maine, bằng lái có ảnh của người lái xe dưới 65 tuổi có giá trị đến sinh nhật thứ sáu sau ngày cấp.","p":"Đúng. Bằng có giá trị đến sinh nhật thứ sáu sau ngày cấp."},"tl":{"q":"Sa Maine, may driver na wala pang 65 na nakakuha ng bagong lisensya na may litrato. Hanggang kailan ito valid?","o":["Hanggang sa ikaanim na kaarawan matapos itong ibigay","Hanggang sa ikalawang kaarawan matapos itong ibigay","Hanggang sa ikasampung kaarawan matapos itong ibigay","Hanggang sa katapusan ng parehong taon"],"h1":"Tumatagal ito nang ilang taon, pero kulang sa sampu.","h2":"Sa Maine, ang lisensyang may litrato ng driver na wala pang 65 ay valid hanggang sa ikaanim na kaarawan matapos ang petsa ng pagbibigay nito.","p":"Tama. Tumatagal ito hanggang sa ikaanim na kaarawan matapos itong ibigay."},"ar":{"q":"في Maine، حصل سائق عمره أقل من 65 سنة على رخصة جديدة بصورة. حتى متى تكون صالحة؟","o":["حتى عيد الميلاد السادس بعد إصدارها","حتى عيد الميلاد الثاني بعد إصدارها","حتى عيد الميلاد العاشر بعد إصدارها","حتى نهاية السنة نفسها"],"h1":"تدوم عدة سنوات، لكن أقل من عشر.","h2":"في Maine، رخصة القيادة بصورة للسائق الذي عمره أقل من 65 سنة صالحة حتى عيد الميلاد السادس بعد تاريخ إصدارها.","p":"صحيح. تبقى صالحة حتى عيد الميلاد السادس بعد إصدارها."},"ref":{"doc":"ME","page":"1-6"}},{"id":"me-029","scope":"ME","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Maine, a person with a white cane or a guide dog is in the road. How far away must you stop?","o":["At least 2 feet","At least 5 feet","At least 50 feet","At least 10 feet"],"h1":"It is about the length of two adult people lying down.","h2":"In Maine, you must stop at least 10 feet away from a person with a white cane or guide dog and wait until the person is safe.","p":"Right. Stop at least 10 feet away and wait."},"es":{"q":"En Maine, una persona con bastón blanco o perro guía está en la calle. ¿A qué distancia debe detenerse usted?","o":["Por lo menos a 2 pies","Por lo menos a 5 pies","Por lo menos a 50 pies","Por lo menos a 10 pies"],"h1":"Es como el largo de dos adultos acostados.","h2":"En Maine, usted debe detenerse por lo menos a 10 pies de una persona con bastón blanco o perro guía y esperar hasta que esté a salvo.","p":"Correcto. Deténgase por lo menos a 10 pies y espere."},"zh":{"q":"在 Maine，一个拿白色手杖或带导盲犬的人在路上。你必须在多远的地方停车？","o":["至少 2 英尺","至少 5 英尺","至少 50 英尺","至少 10 英尺"],"h1":"大约是两个成年人躺下的长度。","h2":"在 Maine，你必须在离拿白色手杖或带导盲犬的人至少 10 英尺的地方停车，并等到这个人安全为止。","p":"对。在至少 10 英尺外停车并等待。"},"vi":{"q":"Ở Maine, một người cầm gậy trắng hoặc đi cùng chó dẫn đường đang ở trên đường. Bạn phải dừng xe cách bao xa?","o":["Ít nhất 2 feet","Ít nhất 5 feet","Ít nhất 50 feet","Ít nhất 10 feet"],"h1":"Khoảng bằng chiều dài của hai người lớn nằm xuống.","h2":"Ở Maine, bạn phải dừng xe cách người cầm gậy trắng hoặc đi cùng chó dẫn đường ít nhất 10 feet và chờ đến khi người đó an toàn.","p":"Đúng. Dừng cách ít nhất 10 feet và chờ."},"tl":{"q":"Sa Maine, may taong may puting tungkod o may guide dog na nasa kalsada. Gaano kalayo ka dapat huminto?","o":["Hindi bababa sa 2 talampakan","Hindi bababa sa 5 talampakan","Hindi bababa sa 50 talampakan","Hindi bababa sa 10 talampakan"],"h1":"Halos kasinghaba ito ng dalawang taong nasa hustong gulang na nakahiga.","h2":"Sa Maine, dapat kang huminto nang hindi bababa sa 10 talampakan ang layo mula sa taong may puting tungkod o guide dog, at maghintay hanggang ligtas na ang tao.","p":"Tama. Huminto nang hindi bababa sa 10 talampakan ang layo at maghintay."},"ar":{"q":"في Maine، شخص يحمل عصا بيضاء أو معه كلب مرشد موجود في الطريق. على أي بُعد يجب أن تتوقف؟","o":["2 قدم على الأقل","5 أقدام على الأقل","50 قدمًا على الأقل","10 أقدام على الأقل"],"h1":"المسافة تقريبًا بطول شخصين بالغين مستلقيين.","h2":"في Maine، يجب أن تتوقف على بُعد 10 أقدام على الأقل من الشخص الذي يحمل عصا بيضاء أو معه كلب مرشد، وأن تنتظر حتى يصبح في أمان.","p":"صحيح. توقّف على بُعد 10 أقدام على الأقل وانتظر."},"ref":{"doc":"ME","page":"6-12"}},{"id":"me-030","scope":"ME","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maine, a passenger in the front seat opens a can of beer while you drive on a public road. What is true?","o":["It is legal because the driver is not drinking","It breaks the law for the driver","It is legal if the passenger is 21 or older","It is only illegal at night"],"h1":"The open container law covers the whole passenger area.","h2":"In Maine, the driver breaks the law if the driver or a passenger drinks alcohol or has an open alcohol container in the passenger area.","p":"Right. An open container in the passenger area breaks the law."},"es":{"q":"En Maine, un pasajero en el asiento delantero abre una lata de cerveza mientras usted maneja en una vía pública. ¿Qué es cierto?","o":["Es legal porque el conductor no está tomando","El conductor está violando la ley","Es legal si el pasajero tiene 21 años o más","Solo es ilegal de noche"],"h1":"La ley de envases abiertos cubre toda el área de pasajeros.","h2":"En Maine, el conductor viola la ley si él o un pasajero toma alcohol o tiene un envase abierto de alcohol en el área de pasajeros.","p":"Correcto. Un envase abierto en el área de pasajeros viola la ley."},"zh":{"q":"在 Maine，你在公共道路上开车时，前座的乘客打开了一罐啤酒。哪一项是对的？","o":["这是合法的，因为司机没有喝酒","这让司机违法","如果乘客 21 岁或以上，这是合法的","只有在晚上才违法"],"h1":"开口容器法适用于整个乘客区域。","h2":"在 Maine，如果司机或乘客在乘客区域喝酒，或者有打开的酒类容器，司机就违法。","p":"对。乘客区域里有打开的酒类容器就是违法。"},"vi":{"q":"Ở Maine, một hành khách ngồi ghế trước mở một lon bia trong khi bạn lái xe trên đường công cộng. Điều nào đúng?","o":["Hợp pháp vì người lái xe không uống","Người lái xe đang vi phạm luật","Hợp pháp nếu hành khách từ 21 tuổi trở lên","Chỉ bất hợp pháp vào ban đêm"],"h1":"Luật về đồ chứa rượu đã mở áp dụng cho toàn bộ khu vực hành khách.","h2":"Ở Maine, người lái xe vi phạm luật nếu người lái hoặc hành khách uống rượu bia hoặc có đồ chứa rượu bia đã mở trong khu vực hành khách.","p":"Đúng. Đồ chứa rượu bia đã mở trong khu vực hành khách là vi phạm luật."},"tl":{"q":"Sa Maine, binuksan ng pasahero sa upuan sa harap ang isang lata ng beer habang nagmamaneho ka sa pampublikong kalsada. Ano ang totoo?","o":["Legal ito dahil hindi umiinom ang driver","Lumalabag sa batas ang driver","Legal ito kung ang pasahero ay 21 taong gulang o higit pa","Ilegal lang ito sa gabi"],"h1":"Saklaw ng open container law ang buong lugar ng mga pasahero.","h2":"Sa Maine, lumalabag sa batas ang driver kung ang driver o isang pasahero ay umiinom ng alak o may bukas na lalagyan ng alak sa lugar ng mga pasahero.","p":"Tama. Labag sa batas ang bukas na lalagyan ng alak sa lugar ng mga pasahero."},"ar":{"q":"في Maine، فتح راكب في المقعد الأمامي علبة بيرة وأنت تقود على طريق عام. ما الصحيح؟","o":["هذا قانوني لأن السائق لا يشرب","السائق يخالف القانون","هذا قانوني إذا كان عمر الراكب 21 سنة أو أكثر","هذا غير قانوني في الليل فقط"],"h1":"قانون الحاويات المفتوحة يشمل كل منطقة الركاب.","h2":"في Maine، يخالف السائق القانون إذا شرب هو أو أحد الركاب الكحول، أو إذا كانت في منطقة الركاب حاوية كحول مفتوحة.","p":"صحيح. حاوية الكحول المفتوحة في منطقة الركاب مخالفة للقانون."},"ref":{"doc":"ME","page":"3-13"}},{"id":"me-031","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, what is the lowest fine for parking in the striped access aisle next to a disability parking space?","o":["$25","$50","$200","$75"],"h1":"It is more than $100.","h2":"In Maine, parking in the access aisle next to a disability parking space is a traffic infraction with a fine of at least $200.","p":"Right. The fine is at least $200."},"es":{"q":"En Maine, ¿cuál es la multa más baja por estacionarse en el pasillo de acceso con rayas junto a un espacio para personas con discapacidad?","o":["$25","$50","$200","$75"],"h1":"Es más de $100.","h2":"En Maine, estacionarse en el pasillo de acceso junto a un espacio para personas con discapacidad es una infracción de tránsito con una multa de por lo menos $200.","p":"Correcto. La multa es de por lo menos $200."},"zh":{"q":"在 Maine，把车停在残障停车位旁边画斜线的通道上，最低罚款是多少？","o":["$25","$50","$200","$75"],"h1":"它超过 $100。","h2":"在 Maine，把车停在残障停车位旁边的通道上是交通违规，罚款至少 $200。","p":"对。罚款至少 $200。"},"vi":{"q":"Ở Maine, tiền phạt thấp nhất khi đậu xe trong lối đi có vạch kẻ bên cạnh chỗ đậu xe cho người khuyết tật là bao nhiêu?","o":["$25","$50","$200","$75"],"h1":"Số tiền này nhiều hơn $100.","h2":"Ở Maine, đậu xe trong lối đi bên cạnh chỗ đậu xe cho người khuyết tật là vi phạm giao thông, với tiền phạt ít nhất $200.","p":"Đúng. Tiền phạt ít nhất là $200."},"tl":{"q":"Sa Maine, magkano ang pinakamababang multa sa pagparada sa may guhit na access aisle sa tabi ng parking space para sa may kapansanan?","o":["$25","$50","$200","$75"],"h1":"Higit ito sa $100.","h2":"Sa Maine, ang pagparada sa access aisle sa tabi ng parking space para sa may kapansanan ay isang traffic infraction na may multang hindi bababa sa $200.","p":"Tama. Ang multa ay hindi bababa sa $200."},"ar":{"q":"في Maine، ما أقل غرامة لركن السيارة في الممر المخطّط بجانب موقف ذوي الإعاقة؟","o":["$25","$50","$200","$75"],"h1":"المبلغ أكثر من $100.","h2":"في Maine، ركن السيارة في الممر بجانب موقف ذوي الإعاقة مخالفة مرورية غرامتها $200 على الأقل.","p":"صحيح. الغرامة $200 على الأقل."},"ref":{"doc":"ME","page":"7-10"}},{"id":"me-032","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, how long is a learner's permit usually valid?","o":["6 months","1 year","2 years","5 years"],"h1":"It lasts much longer than the 6 months you must hold it before the road test.","h2":"In Maine, a learner's permit is usually valid for 2 years.","p":"Right. A permit usually lasts 2 years."},"es":{"q":"En Maine, ¿por cuánto tiempo suele ser válido un permiso de aprendizaje?","o":["6 meses","1 año","2 años","5 años"],"h1":"Dura mucho más que los 6 meses que debe tenerlo antes del examen de manejo.","h2":"En Maine, un permiso de aprendizaje suele ser válido por 2 años.","p":"Correcto. Un permiso suele durar 2 años."},"ref":{"doc":"ME","page":"1-2"}},{"id":"me-033","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, a new resident has a valid driver's license from another state. How soon must they apply for a Maine license?","o":["Within 30 days","Within 6 months","Within 1 year","When the old license expires"],"h1":"It is about one month.","h2":"In Maine, a new resident must give up the out-of-state license and apply for a Maine license within 30 days of moving here.","p":"Right. New residents have 30 days."},"es":{"q":"En Maine, un nuevo residente tiene una licencia de manejo válida de otro estado. ¿En cuánto tiempo debe solicitar una licencia de Maine?","o":["Dentro de 30 días","Dentro de 6 meses","Dentro de 1 año","Cuando venza la licencia anterior"],"h1":"Es más o menos un mes.","h2":"En Maine, un nuevo residente debe entregar la licencia de otro estado y solicitar una licencia de Maine dentro de los 30 días después de mudarse.","p":"Correcto. Los nuevos residentes tienen 30 días."},"ref":{"doc":"ME","page":"1-2"}},{"id":"me-034","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, a person did not take an approved driver education course. What is the youngest age at which they can get a driver's license?","o":["15","16","17","18"],"h1":"With driver education, the youngest age is 16. Without it, you must wait longer.","h2":"In Maine, a person who has not finished an approved driver education course must be at least 18 to get a driver's license.","p":"Right. Without driver education, you must be 18."},"es":{"q":"En Maine, una persona no tomó un curso aprobado de educación vial. ¿Cuál es la edad mínima para que obtenga una licencia de manejo?","o":["15","16","17","18"],"h1":"Con educación vial, la edad mínima es 16. Sin ella, debe esperar más.","h2":"En Maine, una persona que no ha terminado un curso aprobado de educación vial debe tener por lo menos 18 años para obtener una licencia de manejo.","p":"Correcto. Sin educación vial, debe tener 18 años."},"ref":{"doc":"ME","page":"1-3"}},{"id":"me-035","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, a driver is convicted of going 30 mph or more over the speed limit. How long may the license be suspended?","o":["7 days","30 days","1 year","3 years"],"h1":"It is about one month.","h2":"In Maine, a conviction for speeding 30 mph or more over the limit may bring a 30-day license suspension.","p":"Right. It may mean a 30-day suspension."},"es":{"q":"En Maine, un conductor es declarado culpable de manejar a 30 mph o más por encima del límite de velocidad. ¿Por cuánto tiempo pueden suspenderle la licencia?","o":["7 días","30 días","1 año","3 años"],"h1":"Es más o menos un mes.","h2":"En Maine, una condena por manejar a 30 mph o más por encima del límite puede causar una suspensión de la licencia de 30 días.","p":"Correcto. Puede causar una suspensión de 30 días."},"ref":{"doc":"ME","page":"1-8"}},{"id":"me-036","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, at how many demerit points does the Secretary of State send a driver a warning?","o":["3 points","6 points","9 points","12 points"],"h1":"It is half of the number that leads to a suspension.","h2":"In Maine, a driver gets a warning at 6 demerit points, and the license is suspended at 12 points.","p":"Right. The warning comes at 6 points."},"es":{"q":"En Maine, ¿con cuántos puntos de demérito le envía la Secretaría de Estado una advertencia al conductor?","o":["3 puntos","6 puntos","9 puntos","12 puntos"],"h1":"Es la mitad del número que causa una suspensión.","h2":"En Maine, el conductor recibe una advertencia con 6 puntos de demérito, y la licencia se suspende con 12 puntos.","p":"Correcto. La advertencia llega con 6 puntos."},"ref":{"doc":"ME","page":"1-9"}},{"id":"me-037","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, a driver earns one violation-free credit point for each calendar year with no convictions or suspensions. What is the most a driver can build up?","o":["1 point","2 points","3 points","4 points"],"h1":"It is more than 3.","h2":"In Maine, a driver can build up to 4 violation-free credit points, one for each calendar year with no convictions or suspensions.","p":"Right. The most is 4 credit points."},"es":{"q":"En Maine, un conductor gana un punto de crédito por cada año calendario sin condenas ni suspensiones. ¿Cuál es el máximo que puede acumular?","o":["1 punto","2 puntos","3 puntos","4 puntos"],"h1":"Es más de 3.","h2":"En Maine, un conductor puede acumular hasta 4 puntos de crédito, uno por cada año calendario sin condenas ni suspensiones.","p":"Correcto. El máximo es 4 puntos de crédito."},"ref":{"doc":"ME","page":"1-9"}},{"id":"me-038","scope":"ME","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maine, an adult is convicted of OUI for the first time with an alcohol level of 0.15 or higher. What is the shortest jail time?","o":["48 hours","No jail time","12 hours","24 hours"],"h1":"It is two full days.","h2":"In Maine, a first OUI conviction with an alcohol level of 0.15 or higher means at least 48 hours in jail.","p":"Right. The minimum is 48 hours in jail."},"es":{"q":"En Maine, un adulto es declarado culpable de OUI (manejar bajo la influencia) por primera vez con un nivel de alcohol de 0.15 o más. ¿Cuál es el tiempo mínimo en la cárcel?","o":["48 horas","Nada de cárcel","12 horas","24 horas"],"h1":"Son dos días completos.","h2":"En Maine, una primera condena por OUI con un nivel de alcohol de 0.15 o más significa por lo menos 48 horas en la cárcel.","p":"Correcto. El mínimo es 48 horas en la cárcel."},"ref":{"doc":"ME","page":"3-10"}},{"id":"me-039","scope":"ME","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maine, what is the lowest fine for a first OUI conviction with an alcohol level of 0.08 to 0.14 and no test refusal?","o":["$50","$250","$500","$100"],"h1":"It is several hundred dollars.","h2":"In Maine, a first OUI conviction with an alcohol level of 0.08 to 0.14 brings a fine of at least $500.","p":"Right. The fine is at least $500."},"es":{"q":"En Maine, ¿cuál es la multa más baja por una primera condena por OUI con un nivel de alcohol de 0.08 a 0.14, sin negarse a la prueba?","o":["$50","$250","$500","$100"],"h1":"Son varios cientos de dólares.","h2":"En Maine, una primera condena por OUI con un nivel de alcohol de 0.08 a 0.14 trae una multa de por lo menos $500.","p":"Correcto. La multa es de por lo menos $500."},"ref":{"doc":"ME","page":"3-10"}},{"id":"me-040","scope":"ME","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maine, after a first OUI conviction, the driver gets back a conditional license that allows no alcohol at all while driving. How long does that condition last?","o":["30 days","6 months","10 years","1 year"],"h1":"The much longer period is for a second conviction.","h2":"In Maine, after a first OUI conviction, the reinstated license is conditional for one year.","p":"Right. The condition lasts one year."},"es":{"q":"En Maine, después de una primera condena por OUI, el conductor recupera una licencia condicional que no permite nada de alcohol al manejar. ¿Cuánto dura esa condición?","o":["30 días","6 meses","10 años","1 año"],"h1":"El período mucho más largo es para una segunda condena.","h2":"En Maine, después de una primera condena por OUI, la licencia restablecida es condicional por un año.","p":"Correcto. La condición dura un año."},"ref":{"doc":"ME","page":"3-11"}},{"id":"me-041","scope":"ME","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maine, a 6-year-old child weighs 65 pounds. How must the child ride in the car?","o":["In a regular seat belt only","In a federally approved booster seat","In a rear-facing infant seat","On an adult's lap with a belt"],"h1":"The child is under 8 and weighs between 55 and 80 pounds.","h2":"In Maine, a child under 8 who weighs at least 55 but less than 80 pounds must ride in a federally approved child restraint system, such as a booster seat.","p":"Right. This child needs a booster seat."},"es":{"q":"En Maine, un niño de 6 años pesa 65 libras. ¿Cómo debe viajar en el carro?","o":["Solo con el cinturón de seguridad normal","En un asiento elevador aprobado por el gobierno federal","En un asiento para bebé mirando hacia atrás","En las piernas de un adulto con cinturón"],"h1":"El niño tiene menos de 8 años y pesa entre 55 y 80 libras.","h2":"En Maine, un niño menor de 8 años que pesa por lo menos 55 pero menos de 80 libras debe viajar en un sistema de retención infantil aprobado por el gobierno federal, como un asiento elevador.","p":"Correcto. Este niño necesita un asiento elevador."},"ref":{"doc":"ME","page":"4-5"}},{"id":"me-042","scope":"ME","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Maine, what is the speed limit when passing a school during recess or when children are going to or from school?","o":["15 mph","20 mph","25 mph","10 mph"],"h1":"It is lower than the 25 mph limit in town.","h2":"In Maine, the speed limit near a school during recess or school arrival and dismissal times is 15 mph.","p":"Right. It is 15 mph."},"es":{"q":"En Maine, ¿cuál es el límite de velocidad al pasar por una escuela durante el recreo o cuando los niños van o vienen de la escuela?","o":["15 mph","20 mph","25 mph","10 mph"],"h1":"Es más bajo que el límite de 25 mph en la ciudad.","h2":"En Maine, el límite de velocidad cerca de una escuela durante el recreo o en las horas de entrada y salida es de 15 mph.","p":"Correcto. Es de 15 mph."},"ref":{"doc":"ME","page":"8-7"}},{"id":"me-043","scope":"ME","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Maine, what is the top speed in a business or residential area when no speed limit is posted?","o":["15 mph","35 mph","25 mph","30 mph"],"h1":"It is lower than 30 mph.","h2":"In Maine, the top speed in a business district, residential district or built-up area is 25 mph unless a sign says otherwise.","p":"Right. It is 25 mph."},"es":{"q":"En Maine, ¿cuál es la velocidad máxima en una zona comercial o residencial cuando no hay un límite de velocidad señalado?","o":["15 mph","35 mph","25 mph","30 mph"],"h1":"Es menos de 30 mph.","h2":"En Maine, la velocidad máxima en una zona comercial, residencial o urbanizada es de 25 mph, a menos que una señal indique otra cosa.","p":"Correcto. Es de 25 mph."},"ref":{"doc":"ME","page":"8-7"}},{"id":"me-044","scope":"ME","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Maine, what following distance does the driver manual tell you to keep behind the vehicle ahead?","o":["1 second","2 seconds","At least 4 seconds","At least 10 seconds"],"h1":"Count \"one-thousand-one\" and keep going past three.","h2":"In Maine, the driver manual says to keep at least 4 seconds between your car and the vehicle in front.","p":"Right. Keep at least 4 seconds."},"es":{"q":"En Maine, ¿qué distancia de seguimiento le indica el manual del conductor que mantenga detrás del vehículo de adelante?","o":["1 segundo","2 segundos","Por lo menos 4 segundos","Por lo menos 10 segundos"],"h1":"Cuente \"mil uno\" y siga después del tres.","h2":"En Maine, el manual del conductor dice que debe mantener por lo menos 4 segundos entre su carro y el vehículo de adelante.","p":"Correcto. Mantenga por lo menos 4 segundos."},"ref":{"doc":"ME","page":"8-11"}},{"id":"me-045","scope":"ME","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Maine, you must turn on your headlights when it is too dark, foggy or snowy to see how far ahead?","o":["1,000 feet","100 feet","300 feet","5,000 feet"],"h1":"It is more than 500 feet.","h2":"In Maine, you must turn on your headlights whenever you cannot see 1,000 feet ahead.","p":"Right. If you cannot see 1,000 feet ahead, turn on your headlights."},"es":{"q":"En Maine, si por oscuridad, neblina o nieve no puede ver hasta cierta distancia hacia adelante, debe encender las luces delanteras. ¿Cuál es esa distancia?","o":["1,000 pies","100 pies","300 pies","5,000 pies"],"h1":"Es más de 500 pies.","h2":"En Maine, debe encender las luces delanteras siempre que no pueda ver 1,000 pies hacia adelante.","p":"Correcto. Si no puede ver 1,000 pies hacia adelante, encienda las luces."},"ref":{"doc":"ME","page":"8-16"}},{"id":"me-046","scope":"ME","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Maine, when you park next to a curb, what is the farthest your car may be from the curb?","o":["6 feet","3 feet","30 inches","18 inches"],"h1":"It is less than two feet.","h2":"In Maine, when you park next to a curb, park as close to it as you can and no more than 18 inches away.","p":"Right. Park no more than 18 inches from the curb."},"es":{"q":"En Maine, cuando se estaciona junto a la acera, ¿cuál es la distancia máxima a la que puede quedar su carro de la acera?","o":["6 pies","3 pies","30 pulgadas","18 pulgadas"],"h1":"Es menos de dos pies.","h2":"En Maine, cuando se estaciona junto a la acera, debe quedar lo más cerca posible y a no más de 18 pulgadas.","p":"Correcto. Estaciónese a no más de 18 pulgadas de la acera."},"ref":{"doc":"ME","page":"7-9"}},{"id":"me-047","scope":"ME","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Maine, a fire truck is going to a fire alarm. How close behind it may you follow?","o":["No closer than 100 feet","No closer than 500 feet","No closer than 50 feet","As close as you like if you are careful"],"h1":"It is several hundred feet.","h2":"In Maine, it is against the law to follow within 500 feet of a fire truck that is going to a fire alarm.","p":"Right. Stay at least 500 feet back."},"es":{"q":"En Maine, un camión de bomberos va a atender una alarma de incendio. ¿Qué tan cerca puede seguirlo?","o":["No a menos de 100 pies","No a menos de 500 pies","No a menos de 50 pies","Tan cerca como quiera si tiene cuidado"],"h1":"Son varios cientos de pies.","h2":"En Maine, es ilegal seguir a menos de 500 pies a un camión de bomberos que va a atender una alarma de incendio.","p":"Correcto. Manténgase por lo menos a 500 pies."},"ref":{"doc":"ME","page":"10-9"}},{"id":"me-048","scope":"ME","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Maine, the red lights are flashing at a railroad crossing. Where must you stop?","o":["At least 15 feet from the crossing","Right at the edge of the first rail","At least 5 feet from the crossing","Nowhere, if you slow down and look"],"h1":"Leave room between your car and the tracks.","h2":"In Maine, when the red lights flash at a railroad crossing, you must stop at least 15 feet from the crossing and wait.","p":"Right. Stop at least 15 feet away."},"es":{"q":"En Maine, las luces rojas están intermitentes en un cruce de ferrocarril. ¿Dónde debe detenerse?","o":["Por lo menos a 15 pies del cruce","Justo en el borde del primer riel","Por lo menos a 5 pies del cruce","En ningún lugar, si baja la velocidad y mira"],"h1":"Deje espacio entre su carro y las vías.","h2":"En Maine, cuando las luces rojas están intermitentes en un cruce de ferrocarril, debe detenerse por lo menos a 15 pies del cruce y esperar.","p":"Correcto. Deténgase por lo menos a 15 pies."},"ref":{"doc":"ME","page":"8-3"}},{"id":"me-049","scope":"ME","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Maine, you are passing a car on a two-lane road. By when must you finish the pass?","o":["Before the next intersection only","Within 30 seconds","After the no passing zone ends","Before you reach the start of a no passing zone"],"h1":"Think about where the solid line on your side begins.","h2":"In Maine, the law says you must finish a pass before you reach the beginning of a no passing zone.","p":"Right. Finish passing before the no passing zone begins."},"es":{"q":"En Maine, usted está rebasando a un carro en una carretera de dos carriles. ¿Para cuándo debe terminar de rebasar?","o":["Solo antes de la próxima intersección","Dentro de 30 segundos","Después de que termine la zona de no rebasar","Antes de llegar al comienzo de una zona de no rebasar"],"h1":"Piense en dónde empieza la línea continua de su lado.","h2":"En Maine, la ley dice que debe terminar de rebasar antes de llegar al comienzo de una zona de no rebasar.","p":"Correcto. Termine de rebasar antes de que empiece la zona de no rebasar."},"ref":{"doc":"ME","page":"7-8"}},{"id":"me-050","scope":"ME","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maine, a 16-year-old rides in a pickup truck to go shopping. Where must the teen ride?","o":["In the open cargo bed","Inside the passenger compartment","Anywhere, if the truck goes slowly","In the bed, if an adult rides there too"],"h1":"The rule covers passengers under 19.","h2":"In Maine, a passenger under 19 in a pickup truck must ride inside the passenger compartment, except in a few cases such as work or a parade.","p":"Right. The teen must ride inside the cab."},"es":{"q":"En Maine, un joven de 16 años va en una camioneta pickup de compras. ¿Dónde debe viajar?","o":["En la caja de carga abierta","Dentro de la cabina de pasajeros","En cualquier lugar, si la camioneta va despacio","En la caja, si un adulto también va allí"],"h1":"La regla cubre a los pasajeros menores de 19 años.","h2":"En Maine, un pasajero menor de 19 años en una camioneta pickup debe viajar dentro de la cabina de pasajeros, salvo en algunos casos como el trabajo o un desfile.","p":"Correcto. El joven debe viajar dentro de la cabina."},"ref":{"doc":"ME","page":"11-8"}},{"id":"me-051","scope":"ME","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maine, in which months do crashes with moose increase the most?","o":["January and February","December and March","May and June","July and August"],"h1":"It is late spring.","h2":"In Maine, crashes with moose rise sharply in May and June, though they can happen in any month.","p":"Right. May and June are the peak months for moose crashes."},"es":{"q":"En Maine, ¿en qué meses aumentan más los choques con alces (moose)?","o":["Enero y febrero","Diciembre y marzo","Mayo y junio","Julio y agosto"],"h1":"Es a finales de la primavera.","h2":"En Maine, los choques con alces aumentan mucho en mayo y junio, aunque pueden ocurrir en cualquier mes.","p":"Correcto. Mayo y junio son los meses con más choques con alces."},"ref":{"doc":"ME","page":"11-7"}},{"id":"mi-001","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, what is the youngest age to get a Level 1 Learner’s License?","o":["14 years old","14 years and 3 months","14 years and 9 months","15 years and 6 months"],"h1":"It is a few months before the 15th birthday.","h2":"You can get a Michigan Level 1 Learner’s License at 14 years and 9 months, after finishing the first part of driver education.","p":"Right. Level 1 starts at 14 years and 9 months."},"es":{"q":"En Michigan, ¿cuál es la edad mínima para obtener la licencia de aprendiz de Nivel 1?","o":["14 años","14 años y 3 meses","14 años y 9 meses","15 años y 6 meses"],"h1":"Es unos meses antes de cumplir 15 años.","h2":"Usted puede obtener la licencia de aprendiz de Nivel 1 en Michigan a los 14 años y 9 meses, después de terminar la primera parte de la educación vial.","p":"Correcto. El Nivel 1 empieza a los 14 años y 9 meses."},"zh":{"q":"在 Michigan，最小几岁可以拿到 Level 1 学习驾照（Learner’s License）？","o":["14 岁","14 岁又 3 个月","14 岁又 9 个月","15 岁又 6 个月"],"h1":"是 15 岁生日前几个月。","h2":"你在 14 岁又 9 个月、完成驾驶教育的第一部分以后，就可以拿到 Michigan 的 Level 1 学习驾照。","p":"对。Level 1 从 14 岁又 9 个月开始。"},"vi":{"q":"Ở Michigan, tuổi nhỏ nhất để lấy Giấy phép Học lái Cấp 1 (Level 1 Learner’s License) là bao nhiêu?","o":["14 tuổi","14 tuổi 3 tháng","14 tuổi 9 tháng","15 tuổi 6 tháng"],"h1":"Đó là vài tháng trước sinh nhật 15 tuổi.","h2":"Bạn có thể lấy Giấy phép Học lái Cấp 1 ở Michigan khi 14 tuổi 9 tháng, sau khi học xong phần đầu tiên của khóa học lái xe.","p":"Đúng. Cấp 1 bắt đầu khi 14 tuổi 9 tháng."},"tl":{"q":"Sa Michigan, ano ang pinakabatang edad para makakuha ng Level 1 Learner’s License?","o":["14 taong gulang","14 taon at 3 buwan","14 taon at 9 na buwan","15 taon at 6 na buwan"],"h1":"Ilang buwan ito bago ang ika-15 na kaarawan.","h2":"Makakakuha ka ng Michigan Level 1 Learner’s License sa edad na 14 taon at 9 na buwan, pagkatapos tapusin ang unang bahagi ng driver education.","p":"Tama. Nagsisimula ang Level 1 sa 14 taon at 9 na buwan."},"ar":{"q":"في Michigan، ما أصغر عمر للحصول على رخصة التعلّم من المستوى 1 (Level 1 Learner’s License)؟","o":["14 سنة","14 سنة و3 أشهر","14 سنة و9 أشهر","15 سنة و6 أشهر"],"h1":"هو قبل عيد الميلاد الخامس عشر ببضعة أشهر.","h2":"يمكنك الحصول على رخصة التعلّم من المستوى 1 في Michigan في عمر 14 سنة و9 أشهر، بعد إنهاء الجزء الأول من تعليم القيادة.","p":"صحيح. يبدأ المستوى 1 في عمر 14 سنة و9 أشهر."},"ref":{"doc":"MI","page":4}},{"id":"mi-002","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, what must a teen finish before getting a Level 1 Learner’s License?","o":["Segment 1 of an approved driver education course","A road skills test","50 hours of supervised driving","Six months of a part-time job"],"h1":"Michigan splits driver education into parts; this is the first one.","h2":"A teen must finish Segment 1 of an approved driver education course before getting a Level 1 license, so they learn the basics in class first.","p":"Right. Segment 1 of driver education comes first."},"es":{"q":"En Michigan, ¿qué debe terminar un joven antes de obtener la licencia de aprendiz de Nivel 1?","o":["El Segmento 1 de un curso aprobado de educación vial","Un examen práctico de manejo","50 horas de manejo supervisado","Seis meses de un trabajo de medio tiempo"],"h1":"Michigan divide la educación vial en partes; esta es la primera.","h2":"Un joven debe terminar el Segmento 1 de un curso aprobado de educación vial antes de obtener la licencia de Nivel 1, para aprender lo básico en clase primero.","p":"Correcto. Primero va el Segmento 1 de la educación vial."},"zh":{"q":"在 Michigan，青少年拿 Level 1 学习驾照前必须完成什么？","o":["批准的驾驶教育课程的 Segment 1","路考","50 小时有人监督的驾驶","六个月的兼职工作"],"h1":"Michigan 把驾驶教育分成几部分；这是第一部分。","h2":"青少年拿 Level 1 驾照前，必须完成批准的驾驶教育课程的 Segment 1，这样他们先在课堂上学会基础知识。","p":"对。先完成驾驶教育的 Segment 1。"},"vi":{"q":"Ở Michigan, thiếu niên phải học xong điều gì trước khi lấy Giấy phép Học lái Cấp 1 (Level 1 Learner’s License)?","o":["Phần 1 (Segment 1) của một khóa học lái xe được chấp thuận","Một bài thi kỹ năng lái trên đường","50 giờ lái xe có người giám sát","Sáu tháng làm việc bán thời gian"],"h1":"Michigan chia khóa học lái xe thành nhiều phần; đây là phần đầu tiên.","h2":"Thiếu niên phải học xong Phần 1 (Segment 1) của một khóa học lái xe được chấp thuận trước khi lấy giấy phép Cấp 1, để học điều cơ bản trong lớp trước.","p":"Đúng. Phần 1 của khóa học lái xe là bước đầu tiên."},"tl":{"q":"Sa Michigan, ano ang dapat tapusin ng isang teenager bago makakuha ng Level 1 Learner’s License?","o":["Segment 1 ng isang aprubadong kurso ng driver education","Isang pagsusulit sa kasanayan sa pagmamaneho sa kalsada","50 oras ng pagmamaneho na may bantay","Anim na buwan ng part-time na trabaho"],"h1":"Hinahati ng Michigan ang driver education sa mga bahagi; ito ang una.","h2":"Dapat tapusin ng teenager ang Segment 1 ng isang aprubadong kurso ng driver education bago makakuha ng Level 1 license, para matutunan muna ang mga batayan sa klase.","p":"Tama. Segment 1 ng driver education ang nauuna."},"ar":{"q":"في Michigan، ماذا يجب أن يُنهي المراهق قبل الحصول على رخصة التعلّم من المستوى 1 (Level 1 Learner’s License)؟","o":["الجزء 1 (Segment 1) من دورة تعليم قيادة معتمدة","اختبار مهارات القيادة على الطريق","50 ساعة من القيادة تحت الإشراف","ستة أشهر من عمل بدوام جزئي"],"h1":"تقسم Michigan تعليم القيادة إلى أجزاء؛ وهذا هو الجزء الأول.","h2":"يجب أن يُنهي المراهق الجزء 1 (Segment 1) من دورة تعليم قيادة معتمدة قبل الحصول على رخصة المستوى 1، حتى يتعلّم الأساسيات في الصف أولًا.","p":"صحيح. الجزء 1 من تعليم القيادة يأتي أولًا."},"ref":{"doc":"MI","page":4}},{"id":"mi-003","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, who may ride with a Level 1 driver as the supervisor?","o":["Any passenger age 16 or older","Only a certified driving instructor","Any licensed driver age 18 or older","A licensed parent or guardian, or a licensed adult 21 or older they approve"],"h1":"The supervisor must be family, or an older adult the family chose.","h2":"A Level 1 driver may drive only with a licensed parent or guardian, or with a licensed driver 21 or older whom the parent or guardian has approved.","p":"Right. A licensed parent, guardian, or approved adult 21 or older must ride along."},"es":{"q":"En Michigan, ¿quién puede ir como supervisor con un conductor de Nivel 1?","o":["Cualquier pasajero de 16 años o más","Solo un instructor de manejo certificado","Cualquier conductor con licencia de 18 años o más","Su padre, madre o tutor con licencia, o un adulto con licencia de 21 años o más aprobado por ellos"],"h1":"El supervisor debe ser de la familia, o un adulto mayor que la familia eligió.","h2":"Un conductor de Nivel 1 solo puede manejar con su padre, madre o tutor con licencia, o con un conductor con licencia de 21 años o más que ellos hayan aprobado.","p":"Correcto. Debe ir su padre, madre, tutor o un adulto aprobado de 21 años o más con licencia."},"zh":{"q":"在 Michigan，谁可以作为陪同的人坐 Level 1 司机的车？","o":["任何 16 岁或以上的乘客","只有有执照的驾驶教练","任何 18 岁或以上、有驾照的司机","有驾照的父母或监护人，或他们同意的 21 岁或以上、有驾照的成年人"],"h1":"陪同的人必须是家人，或家人选的年纪较大的成年人。","h2":"Level 1 司机只能和有驾照的父母或监护人一起开车，或者和父母或监护人同意的 21 岁或以上、有驾照的司机一起开车。","p":"对。必须有有驾照的父母、监护人，或同意的 21 岁或以上的成年人同车。"},"vi":{"q":"Ở Michigan, ai được ngồi cùng người lái Cấp 1 để giám sát?","o":["Bất kỳ hành khách nào từ 16 tuổi trở lên","Chỉ thầy dạy lái xe có chứng nhận","Bất kỳ người có bằng lái nào từ 18 tuổi trở lên","Cha mẹ hoặc người giám hộ có bằng lái, hoặc người lớn có bằng lái từ 21 tuổi trở lên được họ đồng ý"],"h1":"Người giám sát phải là người trong gia đình, hoặc một người lớn tuổi hơn mà gia đình đã chọn.","h2":"Người lái Cấp 1 chỉ được lái khi có cha mẹ hoặc người giám hộ có bằng lái, hoặc một người có bằng lái từ 21 tuổi trở lên được cha mẹ hoặc người giám hộ đồng ý.","p":"Đúng. Phải có cha mẹ, người giám hộ có bằng lái, hoặc người lớn từ 21 tuổi trở lên được đồng ý ngồi cùng."},"tl":{"q":"Sa Michigan, sino ang puwedeng sumakay kasama ng Level 1 driver bilang tagabantay (supervisor)?","o":["Sinumang pasahero na 16 taong gulang pataas","Isang sertipikadong instruktor sa pagmamaneho lamang","Sinumang may lisensya na 18 taong gulang pataas","Isang magulang o guardian na may lisensya, o isang adult na may lisensya na 21 pataas na pinayagan nila"],"h1":"Ang tagabantay ay dapat kapamilya, o isang mas matandang adult na pinili ng pamilya.","h2":"Ang Level 1 driver ay puwedeng magmaneho lamang kasama ang magulang o guardian na may lisensya, o isang driver na may lisensya na 21 taong gulang pataas na pinayagan ng magulang o guardian.","p":"Tama. Dapat kasama ang magulang, guardian na may lisensya, o aprubadong adult na 21 pataas."},"ar":{"q":"في Michigan، مَن يجوز له أن يركب مع سائق المستوى 1 كمشرف؟","o":["أي راكب عمره 16 سنة أو أكثر","مدرّب قيادة معتمد فقط","أي سائق مرخّص عمره 18 سنة أو أكثر","أحد الوالدين أو الوصي المرخّص، أو شخص بالغ مرخّص عمره 21 سنة أو أكثر يوافقون عليه"],"h1":"يجب أن يكون المشرف من العائلة، أو شخصًا بالغًا أكبر سنًا اختارته العائلة.","h2":"لا يجوز لسائق المستوى 1 أن يقود إلا مع أحد الوالدين أو الوصي المرخّص، أو مع سائق مرخّص عمره 21 سنة أو أكثر وافق عليه أحد الوالدين أو الوصي.","p":"صحيح. يجب أن يركب معه أحد الوالدين أو الوصي المرخّص، أو شخص بالغ موافَق عليه عمره 21 سنة أو أكثر."},"ref":{"doc":"MI","page":5}},{"id":"mi-004","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, how long must a teen hold a Level 1 license before moving to Level 2?","o":["Three months","Six months","One year","Two years"],"h1":"It is half of a year.","h2":"A teen must drive with a Level 1 license for at least six months before moving to Level 2, to gain supervised experience.","p":"Right. Level 1 lasts at least six months."},"es":{"q":"En Michigan, ¿cuánto tiempo debe tener un joven la licencia de Nivel 1 antes de pasar al Nivel 2?","o":["Tres meses","Seis meses","Un año","Dos años"],"h1":"Es la mitad de un año.","h2":"Un joven debe manejar con licencia de Nivel 1 por lo menos seis meses antes de pasar al Nivel 2, para ganar experiencia supervisada.","p":"Correcto. El Nivel 1 dura por lo menos seis meses."},"zh":{"q":"在 Michigan，青少年必须持有 Level 1 驾照多久，才能升到 Level 2？","o":["三个月","六个月","一年","两年"],"h1":"是半年。","h2":"青少年必须持 Level 1 驾照开车至少六个月，才能升到 Level 2，这样可以积累有人监督的经验。","p":"对。Level 1 至少要六个月。"},"vi":{"q":"Ở Michigan, thiếu niên phải giữ giấy phép Cấp 1 bao lâu trước khi lên Cấp 2?","o":["Ba tháng","Sáu tháng","Một năm","Hai năm"],"h1":"Đó là nửa năm.","h2":"Thiếu niên phải lái xe với giấy phép Cấp 1 ít nhất sáu tháng trước khi lên Cấp 2, để có kinh nghiệm khi có người giám sát.","p":"Đúng. Cấp 1 kéo dài ít nhất sáu tháng."},"tl":{"q":"Sa Michigan, gaano katagal dapat hawak ng teenager ang Level 1 license bago lumipat sa Level 2?","o":["Tatlong buwan","Anim na buwan","Isang taon","Dalawang taon"],"h1":"Ito ay kalahati ng isang taon.","h2":"Dapat magmaneho ang teenager gamit ang Level 1 license nang hindi bababa sa anim na buwan bago lumipat sa Level 2, para magkaroon ng karanasan na may bantay.","p":"Tama. Tumatagal ang Level 1 nang hindi bababa sa anim na buwan."},"ar":{"q":"في Michigan، كم مدة يجب أن يحمل المراهق رخصة المستوى 1 قبل الانتقال إلى المستوى 2؟","o":["ثلاثة أشهر","ستة أشهر","سنة واحدة","سنتان"],"h1":"هي نصف سنة.","h2":"يجب أن يقود المراهق برخصة المستوى 1 لمدة ستة أشهر على الأقل قبل الانتقال إلى المستوى 2، ليكتسب خبرة تحت الإشراف.","p":"صحيح. يستمر المستوى 1 ستة أشهر على الأقل."},"ref":{"doc":"MI","page":5}},{"id":"mi-005","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, how many hours of supervised driving must a teen log before Level 2?","o":["30 hours","40 hours","60 hours","50 hours"],"h1":"It is half of one hundred.","h2":"A teen must log at least 50 hours of supervised driving before a Level 2 license, to build steady skills with an adult beside them.","p":"Right. Michigan asks for at least 50 supervised hours."},"es":{"q":"En Michigan, ¿cuántas horas de manejo supervisado debe registrar un joven antes del Nivel 2?","o":["30 horas","40 horas","60 horas","50 horas"],"h1":"Es la mitad de cien.","h2":"Un joven debe registrar por lo menos 50 horas de manejo supervisado antes de la licencia de Nivel 2, para ganar habilidad con un adulto a su lado.","p":"Correcto. Michigan pide por lo menos 50 horas supervisadas."},"zh":{"q":"在 Michigan，青少年升到 Level 2 前必须记录多少小时有人监督的驾驶？","o":["30 小时","40 小时","60 小时","50 小时"],"h1":"是一百的一半。","h2":"青少年拿 Level 2 驾照前，必须记录至少 50 小时有人监督的驾驶，在成年人陪同下练好稳定的技能。","p":"对。Michigan 要求至少 50 小时有人监督的驾驶。"},"vi":{"q":"Ở Michigan, thiếu niên phải ghi lại bao nhiêu giờ lái xe có người giám sát trước Cấp 2?","o":["30 giờ","40 giờ","60 giờ","50 giờ"],"h1":"Đó là một nửa của một trăm.","h2":"Thiếu niên phải ghi lại ít nhất 50 giờ lái xe có người giám sát trước khi lấy giấy phép Cấp 2, để có kỹ năng vững vàng khi có người lớn ngồi bên cạnh.","p":"Đúng. Michigan yêu cầu ít nhất 50 giờ có người giám sát."},"tl":{"q":"Sa Michigan, ilang oras ng pagmamaneho na may bantay ang dapat itala ng teenager bago ang Level 2?","o":["30 oras","40 oras","60 oras","50 oras"],"h1":"Ito ay kalahati ng isandaan.","h2":"Dapat magtala ang teenager ng hindi bababa sa 50 oras ng pagmamaneho na may bantay bago ang Level 2 license, para maging matatag ang kasanayan habang may adult sa tabi.","p":"Tama. Humihingi ang Michigan ng hindi bababa sa 50 oras na may bantay."},"ar":{"q":"في Michigan، كم ساعة من القيادة تحت الإشراف يجب أن يسجّلها المراهق قبل المستوى 2؟","o":["30 ساعة","40 ساعة","60 ساعة","50 ساعة"],"h1":"هي نصف المئة.","h2":"يجب أن يسجّل المراهق 50 ساعة على الأقل من القيادة تحت الإشراف قبل رخصة المستوى 2، ليبني مهارات ثابتة وبجانبه شخص بالغ.","p":"صحيح. تطلب Michigan ما لا يقل عن 50 ساعة تحت الإشراف."},"ref":{"doc":"MI","page":5}},{"id":"mi-006","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, how many of the supervised hours before Level 2 must be at night?","o":["At least 10 hours","At least 2 hours","At least 20 hours","At least 25 hours"],"h1":"It is one fifth of the total hours.","h2":"At least 10 of the 50 supervised hours must be driven at night, because darkness makes driving harder.","p":"Right. At least 10 of the hours must be at night."},"es":{"q":"En Michigan, ¿cuántas de las horas supervisadas antes del Nivel 2 deben ser de noche?","o":["Por lo menos 10 horas","Por lo menos 2 horas","Por lo menos 20 horas","Por lo menos 25 horas"],"h1":"Es la quinta parte del total de horas.","h2":"Por lo menos 10 de las 50 horas supervisadas deben ser de noche, porque la oscuridad hace más difícil manejar.","p":"Correcto. Por lo menos 10 horas deben ser de noche."},"zh":{"q":"在 Michigan，升到 Level 2 前有人监督的驾驶时间中，有多少小时必须在晚上？","o":["至少 10 小时","至少 2 小时","至少 20 小时","至少 25 小时"],"h1":"是总时间的五分之一。","h2":"50 小时有人监督的驾驶中，至少 10 小时必须在晚上开，因为天黑让开车更难。","p":"对。至少 10 小时必须在晚上。"},"vi":{"q":"Ở Michigan, trong số giờ có người giám sát trước Cấp 2, bao nhiêu giờ phải lái vào ban đêm?","o":["Ít nhất 10 giờ","Ít nhất 2 giờ","Ít nhất 20 giờ","Ít nhất 25 giờ"],"h1":"Đó là một phần năm của tổng số giờ.","h2":"Ít nhất 10 trong 50 giờ có người giám sát phải lái vào ban đêm, vì trời tối làm việc lái xe khó hơn.","p":"Đúng. Ít nhất 10 giờ phải lái vào ban đêm."},"tl":{"q":"Sa Michigan, ilan sa mga oras na may bantay bago ang Level 2 ang dapat sa gabi?","o":["Hindi bababa sa 10 oras","Hindi bababa sa 2 oras","Hindi bababa sa 20 oras","Hindi bababa sa 25 oras"],"h1":"Ito ay ikalimang bahagi ng kabuuang oras.","h2":"Hindi bababa sa 10 sa 50 oras na may bantay ang dapat imaneho sa gabi, dahil mas mahirap magmaneho kapag madilim.","p":"Tama. Hindi bababa sa 10 oras ang dapat sa gabi."},"ar":{"q":"في Michigan، كم من ساعات الإشراف قبل المستوى 2 يجب أن تكون في الليل؟","o":["10 ساعات على الأقل","ساعتان على الأقل (2)","20 ساعة على الأقل","25 ساعة على الأقل"],"h1":"هي خُمس مجموع الساعات.","h2":"يجب أن تكون 10 ساعات على الأقل من الـ50 ساعة تحت الإشراف قيادةً في الليل، لأن الظلام يجعل القيادة أصعب.","p":"صحيح. يجب أن تكون 10 ساعات على الأقل في الليل."},"ref":{"doc":"MI","page":5}},{"id":"mi-007","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, what is the youngest age for a Level 2 Intermediate License?","o":["15 years old","15 and a half years old","16 years old","17 years old"],"h1":"It is the same age many states use for a first license.","h2":"You can get a Michigan Level 2 Intermediate License at 16, after finishing Segment 2 and passing a driving skills test.","p":"Right. Level 2 starts at age 16."},"es":{"q":"En Michigan, ¿cuál es la edad mínima para la licencia intermedia de Nivel 2?","o":["15 años","15 años y medio","16 años","17 años"],"h1":"Es la misma edad que muchos estados usan para la primera licencia.","h2":"Usted puede obtener la licencia intermedia de Nivel 2 en Michigan a los 16 años, después de terminar el Segmento 2 y aprobar el examen práctico de manejo.","p":"Correcto. El Nivel 2 empieza a los 16 años."},"zh":{"q":"在 Michigan，最小几岁可以拿到 Level 2 中级驾照（Intermediate License）？","o":["15 岁","15 岁半","16 岁","17 岁"],"h1":"很多州第一张驾照也是这个年龄。","h2":"你在 16 岁、完成 Segment 2 并通过驾驶技能考试以后，就可以拿到 Michigan 的 Level 2 中级驾照。","p":"对。Level 2 从 16 岁开始。"},"vi":{"q":"Ở Michigan, tuổi nhỏ nhất để lấy Giấy phép Trung cấp Cấp 2 (Level 2 Intermediate License) là bao nhiêu?","o":["15 tuổi","15 tuổi rưỡi","16 tuổi","17 tuổi"],"h1":"Đó là cùng tuổi mà nhiều tiểu bang dùng cho bằng lái đầu tiên.","h2":"Bạn có thể lấy Giấy phép Trung cấp Cấp 2 ở Michigan khi 16 tuổi, sau khi học xong Phần 2 (Segment 2) và đậu bài thi kỹ năng lái xe.","p":"Đúng. Cấp 2 bắt đầu khi 16 tuổi."},"tl":{"q":"Sa Michigan, ano ang pinakabatang edad para sa Level 2 Intermediate License?","o":["15 taong gulang","15 at kalahating taong gulang","16 taong gulang","17 taong gulang"],"h1":"Ito ang parehong edad na ginagamit ng maraming estado para sa unang lisensya.","h2":"Makakakuha ka ng Michigan Level 2 Intermediate License sa edad na 16, pagkatapos tapusin ang Segment 2 at pumasa sa driving skills test.","p":"Tama. Nagsisimula ang Level 2 sa edad na 16."},"ar":{"q":"في Michigan، ما أصغر عمر للحصول على الرخصة المتوسطة من المستوى 2 (Level 2 Intermediate License)؟","o":["15 سنة","15 سنة ونصف","16 سنة","17 سنة"],"h1":"هو نفس العمر الذي تستخدمه ولايات كثيرة لأول رخصة.","h2":"يمكنك الحصول على الرخصة المتوسطة من المستوى 2 في Michigan في عمر 16 سنة، بعد إنهاء الجزء 2 (Segment 2) والنجاح في اختبار مهارات القيادة.","p":"صحيح. يبدأ المستوى 2 في عمر 16 سنة."},"ref":{"doc":"MI","page":5}},{"id":"mi-008","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, how long must a teen go with no tickets, suspensions or at-fault crashes right before applying for Level 2?","o":["30 days","90 days","180 days","One year"],"h1":"It is about three months.","h2":"A teen needs a clean record for the 90 days just before applying for Level 2, showing they can drive safely.","p":"Right. You need 90 days with a clean record."},"es":{"q":"En Michigan, ¿cuánto tiempo debe pasar un joven sin multas, suspensiones ni choques de los que sea culpable justo antes de solicitar el Nivel 2?","o":["30 días","90 días","180 días","Un año"],"h1":"Son unos tres meses.","h2":"Un joven necesita un récord limpio durante los 90 días justo antes de solicitar el Nivel 2, para mostrar que maneja con seguridad.","p":"Correcto. Necesita 90 días con récord limpio."},"zh":{"q":"在 Michigan，申请 Level 2 之前，青少年必须连续多久没有罚单、没有被暂停驾照、也没有自己有责任的车祸？","o":["30 天","90 天","180 天","一年"],"h1":"大约三个月。","h2":"青少年在申请 Level 2 之前的 90 天里必须记录干净，这表示他们能安全开车。","p":"对。你需要 90 天的干净记录。"},"vi":{"q":"Ở Michigan, ngay trước khi nộp đơn lên Cấp 2, thiếu niên phải không có vé phạt, không bị treo bằng và không gây tai nạn trong bao lâu?","o":["30 ngày","90 ngày","180 ngày","Một năm"],"h1":"Đó là khoảng ba tháng.","h2":"Thiếu niên cần có hồ sơ sạch trong 90 ngày ngay trước khi nộp đơn lên Cấp 2, để cho thấy họ có thể lái xe an toàn.","p":"Đúng. Bạn cần 90 ngày với hồ sơ sạch."},"tl":{"q":"Sa Michigan, gaano katagal dapat walang tiket, suspensyon o banggaan na kasalanan niya ang teenager bago mismo mag-apply para sa Level 2?","o":["30 araw","90 araw","180 araw","Isang taon"],"h1":"Ito ay mga tatlong buwan.","h2":"Kailangan ng teenager ng malinis na record sa 90 araw bago mismo mag-apply para sa Level 2, para ipakita na kaya niyang magmaneho nang ligtas.","p":"Tama. Kailangan mo ng 90 araw na malinis na record."},"ar":{"q":"في Michigan، كم مدة يجب أن يبقى المراهق بلا مخالفات ولا تعليق للرخصة ولا حوادث هو المخطئ فيها، مباشرةً قبل التقدّم للمستوى 2؟","o":["30 يومًا","90 يومًا","180 يومًا","سنة واحدة"],"h1":"هي نحو ثلاثة أشهر.","h2":"يحتاج المراهق إلى سجلّ نظيف خلال الـ90 يومًا التي تسبق التقدّم للمستوى 2 مباشرةً، ليُظهر أنه يستطيع القيادة بأمان.","p":"صحيح. تحتاج إلى 90 يومًا بسجلّ نظيف."},"ref":{"doc":"MI","page":5}},{"id":"mi-009","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, during which hours may a Level 2 driver not drive without an adult, unless an exception applies?","o":["10 p.m. to 5 a.m.","Midnight to 5 a.m.","11 p.m. to 6 a.m.","9 p.m. to 6 a.m."],"h1":"It starts two hours before midnight.","h2":"A Level 2 driver may not drive between 10 p.m. and 5 a.m. unless going to or from work or an approved activity, or with a parent, guardian or approved adult 21 or older.","p":"Right. Level 2 drivers stay off the road from 10 p.m. to 5 a.m."},"es":{"q":"En Michigan, ¿en qué horario no puede manejar un conductor de Nivel 2 sin un adulto, salvo una excepción?","o":["De 10 p.m. a 5 a.m.","De medianoche a 5 a.m.","De 11 p.m. a 6 a.m.","De 9 p.m. a 6 a.m."],"h1":"Empieza dos horas antes de la medianoche.","h2":"Un conductor de Nivel 2 no puede manejar entre las 10 p.m. y las 5 a.m., salvo que vaya o vuelva del trabajo o de una actividad autorizada, o con su padre, madre, tutor o un adulto aprobado de 21 años o más.","p":"Correcto. Los conductores de Nivel 2 no manejan de 10 p.m. a 5 a.m."},"zh":{"q":"在 Michigan，除非有例外情况，Level 2 司机在哪段时间不能在没有成年人陪同时开车？","o":["晚上 10 点到早上 5 点","午夜到早上 5 点","晚上 11 点到早上 6 点","晚上 9 点到早上 6 点"],"h1":"它从午夜前两个小时开始。","h2":"Level 2 司机在晚上 10 点到早上 5 点之间不能开车，除非是去上班或下班、去或离开批准的活动，或者有父母、监护人或同意的 21 岁或以上的成年人陪同。","p":"对。Level 2 司机在晚上 10 点到早上 5 点不上路。"},"vi":{"q":"Ở Michigan, người lái Cấp 2 không được lái xe mà không có người lớn trong những giờ nào, trừ khi có trường hợp ngoại lệ?","o":["10 giờ tối đến 5 giờ sáng","Nửa đêm đến 5 giờ sáng","11 giờ tối đến 6 giờ sáng","9 giờ tối đến 6 giờ sáng"],"h1":"Nó bắt đầu hai giờ trước nửa đêm.","h2":"Người lái Cấp 2 không được lái từ 10 giờ tối đến 5 giờ sáng, trừ khi đi làm hoặc đi làm về, đi đến hoặc về từ một hoạt động được chấp thuận, hoặc đi cùng cha mẹ, người giám hộ hoặc người lớn từ 21 tuổi trở lên được đồng ý.","p":"Đúng. Người lái Cấp 2 không lái xe từ 10 giờ tối đến 5 giờ sáng."},"tl":{"q":"Sa Michigan, sa anong mga oras hindi puwedeng magmaneho ang Level 2 driver nang walang kasamang adult, maliban kung may exception?","o":["10 p.m. hanggang 5 a.m.","Hatinggabi hanggang 5 a.m.","11 p.m. hanggang 6 a.m.","9 p.m. hanggang 6 a.m."],"h1":"Nagsisimula ito dalawang oras bago maghatinggabi.","h2":"Hindi puwedeng magmaneho ang Level 2 driver mula 10 p.m. hanggang 5 a.m., maliban kung papunta o pauwi mula sa trabaho o sa aprubadong aktibidad, o kasama ang magulang, guardian o aprubadong adult na 21 pataas.","p":"Tama. Wala sa kalsada ang Level 2 drivers mula 10 p.m. hanggang 5 a.m."},"ar":{"q":"في Michigan، في أي ساعات لا يجوز لسائق المستوى 2 أن يقود بدون شخص بالغ، إلا في حالة استثناء؟","o":["من 10 مساءً إلى 5 صباحًا","من منتصف الليل إلى 5 صباحًا","من 11 مساءً إلى 6 صباحًا","من 9 مساءً إلى 6 صباحًا"],"h1":"تبدأ قبل منتصف الليل بساعتين.","h2":"لا يجوز لسائق المستوى 2 أن يقود بين 10 مساءً و5 صباحًا، إلا إذا كان ذاهبًا إلى العمل أو عائدًا منه أو من نشاط معتمد، أو كان معه أحد الوالدين أو الوصي أو شخص بالغ موافَق عليه عمره 21 سنة أو أكثر.","p":"صحيح. سائقو المستوى 2 لا يقودون من 10 مساءً إلى 5 صباحًا."},"ref":{"doc":"MI","page":5}},{"id":"mi-010","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, which trip may a Level 2 driver make alone during the night limit hours?","o":["Driving friends home from a party","Driving to a late restaurant","Driving to or from a job","Driving around to practice"],"h1":"The exception is about earning a living.","h2":"A Level 2 driver may drive during the night limit hours when going to or from work, or while working.","p":"Right. Driving to or from work is an exception."},"es":{"q":"En Michigan, ¿qué viaje puede hacer solo un conductor de Nivel 2 en las horas de límite nocturno?","o":["Llevar a amigos a casa después de una fiesta","Ir a un restaurante tarde","Ir o volver del trabajo","Manejar por ahí para practicar"],"h1":"La excepción tiene que ver con ganarse la vida.","h2":"Un conductor de Nivel 2 puede manejar en las horas de límite nocturno cuando va o vuelve del trabajo, o mientras trabaja.","p":"Correcto. Ir o volver del trabajo es una excepción."},"zh":{"q":"在 Michigan，在夜间限制的时间里，Level 2 司机可以单独开车去做哪件事？","o":["送朋友从派对回家","开车去很晚才关门的餐厅","开车去上班或下班","开车到处转来练习"],"h1":"这个例外和赚钱养活自己有关。","h2":"Level 2 司机在夜间限制的时间里，去上班或下班、或者在工作时，可以开车。","p":"对。上班或下班是一个例外。"},"vi":{"q":"Ở Michigan, người lái Cấp 2 được lái một mình chuyến đi nào trong giờ giới hạn ban đêm?","o":["Chở bạn bè về nhà sau bữa tiệc","Lái đến một nhà hàng mở khuya","Lái xe đi làm hoặc đi làm về","Lái vòng quanh để tập"],"h1":"Trường hợp ngoại lệ là về việc kiếm sống.","h2":"Người lái Cấp 2 được lái trong giờ giới hạn ban đêm khi đi làm, đi làm về, hoặc khi đang làm việc.","p":"Đúng. Lái xe đi làm hoặc đi làm về là trường hợp ngoại lệ."},"tl":{"q":"Sa Michigan, anong biyahe ang puwedeng gawin nang mag-isa ng Level 2 driver sa mga oras ng limitasyon sa gabi?","o":["Paghatid sa mga kaibigan pauwi mula sa party","Pagmamaneho papunta sa restawran na bukas hanggang gabi","Pagmamaneho papunta o pauwi mula sa trabaho","Pag-ikot-ikot para magpraktis"],"h1":"Ang exception ay tungkol sa paghahanapbuhay.","h2":"Puwedeng magmaneho ang Level 2 driver sa mga oras ng limitasyon sa gabi kapag papunta o pauwi mula sa trabaho, o habang nagtatrabaho.","p":"Tama. Ang pagmamaneho papunta o pauwi mula sa trabaho ay exception."},"ar":{"q":"في Michigan، أي رحلة يجوز لسائق المستوى 2 أن يقوم بها وحده خلال ساعات القيد الليلي؟","o":["توصيل الأصدقاء إلى البيت بعد حفلة","القيادة إلى مطعم يفتح حتى وقت متأخر","القيادة إلى العمل أو العودة منه","التجوّل بالسيارة للتدرّب"],"h1":"الاستثناء يتعلّق بكسب الرزق.","h2":"يجوز لسائق المستوى 2 أن يقود خلال ساعات القيد الليلي عند الذهاب إلى العمل أو العودة منه، أو أثناء العمل.","p":"صحيح. القيادة إلى العمل أو العودة منه استثناء."},"ref":{"doc":"MI","page":5}},{"id":"mi-011","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, how many passengers under 21 may a Level 2 driver carry, not counting family?","o":["None at all","Two","Three","One"],"h1":"More than zero, but fewer than two.","h2":"A Level 2 driver may carry no more than one passenger under 21, except for members of their own family, because young passengers raise crash risk.","p":"Right. Only one passenger under 21, besides family."},"es":{"q":"En Michigan, ¿cuántos pasajeros menores de 21 años puede llevar un conductor de Nivel 2, sin contar a la familia?","o":["Ninguno","Dos","Tres","Uno"],"h1":"Más que cero, pero menos que dos.","h2":"Un conductor de Nivel 2 no puede llevar más de un pasajero menor de 21 años, sin contar a su familia, porque los pasajeros jóvenes aumentan el riesgo de choque.","p":"Correcto. Solo un pasajero menor de 21, además de la familia."},"zh":{"q":"在 Michigan，不算家人，Level 2 司机可以载多少位 21 岁以下的乘客？","o":["一个都不行","两位","三位","一位"],"h1":"多于零，但少于二。","h2":"除了自己的家人，Level 2 司机最多只能载一位 21 岁以下的乘客，因为年轻乘客会增加车祸风险。","p":"对。除了家人，只能载一位 21 岁以下的乘客。"},"vi":{"q":"Ở Michigan, người lái Cấp 2 được chở bao nhiêu hành khách dưới 21 tuổi, không tính người trong gia đình?","o":["Không ai cả","Hai","Ba","Một"],"h1":"Nhiều hơn không, nhưng ít hơn hai.","h2":"Người lái Cấp 2 được chở không quá một hành khách dưới 21 tuổi, trừ người trong gia đình mình, vì hành khách trẻ làm tăng nguy cơ tai nạn.","p":"Đúng. Chỉ một hành khách dưới 21 tuổi, ngoài người trong gia đình."},"tl":{"q":"Sa Michigan, ilang pasaherong wala pang 21 ang puwedeng isakay ng Level 2 driver, hindi kasama ang pamilya?","o":["Wala talaga","Dalawa","Tatlo","Isa"],"h1":"Higit sa zero, pero kulang sa dalawa.","h2":"Ang Level 2 driver ay puwedeng magsakay ng hindi hihigit sa isang pasaherong wala pang 21, maliban sa sarili niyang pamilya, dahil pinapataas ng mga batang pasahero ang panganib ng banggaan.","p":"Tama. Isang pasahero lang na wala pang 21, bukod sa pamilya."},"ar":{"q":"في Michigan، كم راكبًا عمره أقل من 21 سنة يجوز لسائق المستوى 2 أن يحمل، بدون حساب أفراد العائلة؟","o":["لا أحد أبدًا","اثنان","ثلاثة","واحد"],"h1":"أكثر من صفر، لكن أقل من اثنين.","h2":"لا يجوز لسائق المستوى 2 أن يحمل أكثر من راكب واحد عمره أقل من 21 سنة، ما عدا أفراد عائلته، لأن الركاب الصغار يزيدون خطر الحوادث.","p":"صحيح. راكب واحد فقط أقل من 21 سنة، غير أفراد العائلة."},"ref":{"doc":"MI","page":5}},{"id":"mi-012","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, what is the youngest age to move to a Level 3 full license?","o":["16 years old","17 years old","18 years old","21 years old"],"h1":"It is one year after the youngest Level 2 age.","h2":"A teen can move up to a Level 3 license at 17 at the earliest, if all requirements are met and a parent agrees.","p":"Right. Level 3 can start at age 17."},"es":{"q":"En Michigan, ¿cuál es la edad mínima para pasar a la licencia completa de Nivel 3?","o":["16 años","17 años","18 años","21 años"],"h1":"Es un año después de la edad mínima del Nivel 2.","h2":"Un joven puede pasar a la licencia de Nivel 3 a los 17 años como mínimo, si cumple todos los requisitos y uno de sus padres está de acuerdo.","p":"Correcto. El Nivel 3 puede empezar a los 17 años."},"zh":{"q":"在 Michigan，最小几岁可以升到 Level 3 正式驾照？","o":["16 岁","17 岁","18 岁","21 岁"],"h1":"比 Level 2 的最小年龄晚一年。","h2":"如果满足所有要求，而且父母同意，青少年最早 17 岁可以升到 Level 3 驾照。","p":"对。Level 3 最早从 17 岁开始。"},"vi":{"q":"Ở Michigan, tuổi nhỏ nhất để lên bằng lái đầy đủ Cấp 3 (Level 3) là bao nhiêu?","o":["16 tuổi","17 tuổi","18 tuổi","21 tuổi"],"h1":"Đó là một năm sau tuổi nhỏ nhất của Cấp 2.","h2":"Thiếu niên có thể lên giấy phép Cấp 3 sớm nhất khi 17 tuổi, nếu đáp ứng mọi yêu cầu và cha mẹ đồng ý.","p":"Đúng. Cấp 3 có thể bắt đầu khi 17 tuổi."},"tl":{"q":"Sa Michigan, ano ang pinakabatang edad para lumipat sa Level 3 na buong lisensya?","o":["16 taong gulang","17 taong gulang","18 taong gulang","21 taong gulang"],"h1":"Ito ay isang taon pagkatapos ng pinakabatang edad para sa Level 2.","h2":"Puwedeng lumipat ang teenager sa Level 3 license sa edad na 17 sa pinakamaaga, kung natugunan ang lahat ng kailangan at pumayag ang magulang.","p":"Tama. Puwedeng magsimula ang Level 3 sa edad na 17."},"ar":{"q":"في Michigan، ما أصغر عمر للانتقال إلى الرخصة الكاملة من المستوى 3 (Level 3)؟","o":["16 سنة","17 سنة","18 سنة","21 سنة"],"h1":"هو بعد أصغر عمر للمستوى 2 بسنة واحدة.","h2":"يمكن للمراهق الانتقال إلى رخصة المستوى 3 في عمر 17 سنة على أقرب تقدير، إذا استوفى كل الشروط ووافق أحد الوالدين.","p":"صحيح. يمكن أن يبدأ المستوى 3 في عمر 17 سنة."},"ref":{"doc":"MI","page":5}},{"id":"mi-013","scope":"MI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Michigan, Kelsey’s Law limits cell phone use for which drivers?","o":["All drivers over 65","Drivers of school buses only","Drivers with a Level 1 or Level 2 license","Only drivers with a past crash"],"h1":"It is about the newest drivers.","h2":"Kelsey’s Law limits phone use by drivers who hold a Level 1 or Level 2 license, because new drivers are easily distracted; calls for emergencies are allowed.","p":"Right. Kelsey’s Law covers Level 1 and Level 2 drivers."},"es":{"q":"En Michigan, ¿a qué conductores les limita el uso del celular la Ley de Kelsey?","o":["A todos los conductores mayores de 65","Solo a choferes de autobús escolar","A conductores con licencia de Nivel 1 o Nivel 2","Solo a conductores que ya tuvieron un choque"],"h1":"Se trata de los conductores más nuevos.","h2":"La Ley de Kelsey limita el uso del teléfono a quienes tienen licencia de Nivel 1 o Nivel 2, porque los conductores nuevos se distraen fácilmente; las llamadas de emergencia se permiten.","p":"Correcto. La Ley de Kelsey aplica a conductores de Nivel 1 y Nivel 2."},"zh":{"q":"在 Michigan，Kelsey’s Law 限制哪些司机使用手机？","o":["所有 65 岁以上的司机","只有校车司机","持 Level 1 或 Level 2 驾照的司机","只有以前出过车祸的司机"],"h1":"它和最新的司机有关。","h2":"Kelsey’s Law 限制持 Level 1 或 Level 2 驾照的司机使用手机，因为新司机很容易分心；紧急情况可以打电话。","p":"对。Kelsey’s Law 适用于 Level 1 和 Level 2 司机。"},"vi":{"q":"Ở Michigan, Luật Kelsey (Kelsey’s Law) giới hạn việc dùng điện thoại di động đối với những người lái nào?","o":["Tất cả người lái trên 65 tuổi","Chỉ tài xế xe buýt trường học","Người lái có giấy phép Cấp 1 hoặc Cấp 2","Chỉ người lái đã từng gây tai nạn"],"h1":"Nó nói về những người lái mới nhất.","h2":"Luật Kelsey giới hạn việc dùng điện thoại của người lái có giấy phép Cấp 1 hoặc Cấp 2, vì người lái mới dễ bị phân tâm; vẫn được gọi khi có trường hợp khẩn cấp.","p":"Đúng. Luật Kelsey áp dụng cho người lái Cấp 1 và Cấp 2."},"tl":{"q":"Sa Michigan, nililimitahan ng Kelsey’s Law ang paggamit ng cell phone ng aling mga driver?","o":["Lahat ng driver na lampas 65","Mga driver ng school bus lamang","Mga driver na may Level 1 o Level 2 license","Mga driver lamang na nagkaroon na ng banggaan"],"h1":"Tungkol ito sa pinakabagong mga driver.","h2":"Nililimitahan ng Kelsey’s Law ang paggamit ng phone ng mga driver na may Level 1 o Level 2 license, dahil madaling ma-distract ang mga bagong driver; pinapayagan ang tawag para sa emergency.","p":"Tama. Saklaw ng Kelsey’s Law ang Level 1 at Level 2 drivers."},"ar":{"q":"في Michigan، قانون كيلسي (Kelsey’s Law) يقيّد استخدام الهاتف المحمول لأي سائقين؟","o":["كل السائقين فوق 65 سنة","سائقو الحافلات المدرسية فقط","السائقون الذين يحملون رخصة المستوى 1 أو المستوى 2","السائقون الذين وقع لهم حادث سابق فقط"],"h1":"يتعلّق بأحدث السائقين.","h2":"قانون كيلسي (Kelsey’s Law) يقيّد استخدام الهاتف للسائقين الذين يحملون رخصة المستوى 1 أو المستوى 2، لأن السائقين الجدد يتشتّت انتباههم بسهولة؛ والمكالمات في حالات الطوارئ مسموحة.","p":"صحيح. قانون كيلسي يشمل سائقي المستوى 1 والمستوى 2."},"ref":{"doc":"MI","page":24}},{"id":"mi-014","scope":"MI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Michigan, you are stopped at a red light. May you hold your phone in your hand?","o":["No, holding a phone is not allowed even while stopped in traffic","Yes, because the car is not moving","Yes, if you only read messages","Yes, if the light is long"],"h1":"Michigan’s hands-free law does not stop at red lights.","h2":"Michigan law does not let you hold a phone while driving, and that includes waiting at a red light or in stopped traffic.","p":"Right. No holding the phone, even at a red light."},"es":{"q":"En Michigan, usted está detenido en una luz roja. ¿Puede tener el teléfono en la mano?","o":["No, no se permite tener el teléfono en la mano ni detenido en el tráfico","Sí, porque el carro no se mueve","Sí, si solo lee mensajes","Sí, si la luz es larga"],"h1":"La ley de manos libres de Michigan no se detiene en las luces rojas.","h2":"La ley de Michigan no le permite tener el teléfono en la mano mientras maneja, y eso incluye esperar en una luz roja o en tráfico detenido.","p":"Correcto. No puede tener el teléfono en la mano, ni en una luz roja."},"zh":{"q":"在 Michigan，你停在红灯前。你可以把手机拿在手里吗？","o":["不可以，即使在车流中停着，也不能拿手机","可以，因为车没有在动","可以，如果你只是看短信","可以，如果红灯很长"],"h1":"Michigan 的免提法在红灯时也适用。","h2":"Michigan 法律不让你开车时手拿手机，这也包括在红灯前或在停住的车流中等待的时候。","p":"对。即使在红灯前，也不能手拿手机。"},"vi":{"q":"Ở Michigan, bạn đang dừng ở đèn đỏ. Bạn có được cầm điện thoại trên tay không?","o":["Không, không được cầm điện thoại ngay cả khi đang dừng trong dòng xe","Có, vì xe không chạy","Có, nếu bạn chỉ đọc tin nhắn","Có, nếu đèn đỏ lâu"],"h1":"Luật rảnh tay của Michigan vẫn áp dụng ở đèn đỏ.","h2":"Luật Michigan không cho phép bạn cầm điện thoại khi lái xe, kể cả khi đang chờ đèn đỏ hoặc dừng trong dòng xe.","p":"Đúng. Không được cầm điện thoại, kể cả ở đèn đỏ."},"tl":{"q":"Sa Michigan, nakahinto ka sa pulang ilaw. Puwede mo bang hawakan ang phone mo?","o":["Hindi, bawal humawak ng phone kahit nakahinto sa trapiko","Oo, dahil hindi gumagalaw ang kotse","Oo, kung nagbabasa ka lang ng mga mensahe","Oo, kung matagal ang pulang ilaw"],"h1":"Hindi tumitigil sa pulang ilaw ang hands-free law ng Michigan.","h2":"Hindi ka pinapayagan ng batas ng Michigan na humawak ng phone habang nagmamaneho, kasama na ang paghihintay sa pulang ilaw o sa nakahintong trapiko.","p":"Tama. Bawal humawak ng phone, kahit sa pulang ilaw."},"ar":{"q":"في Michigan، أنت متوقّف عند إشارة حمراء. هل يجوز لك أن تمسك هاتفك بيدك؟","o":["لا، لا يجوز مسك الهاتف حتى وأنت متوقّف في حركة السير","نعم، لأن السيارة لا تتحرّك","نعم، إذا كنت تقرأ الرسائل فقط","نعم، إذا كانت الإشارة طويلة"],"h1":"قانون عدم استخدام اليدين (hands-free) في Michigan لا يتوقّف عند الإشارة الحمراء.","h2":"قانون Michigan لا يسمح لك بمسك الهاتف أثناء القيادة، وهذا يشمل الانتظار عند إشارة حمراء أو في حركة سير متوقّفة.","p":"صحيح. لا تمسك الهاتف، حتى عند الإشارة الحمراء."},"ref":{"doc":"MI","page":null}},{"id":"mi-015","scope":"MI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Michigan, you pass a stopped emergency vehicle with its lights on and cannot move over. How much must you slow down?","o":["To 5 mph below the speed limit","To at least 10 mph below the speed limit","To 15 mph below the speed limit","To exactly 20 mph"],"h1":"It is a round number, and it is the least you must slow.","h2":"If you cannot move over safely, you must slow to at least 10 mph below the posted speed limit and pass with care.","p":"Right. Slow to at least 10 mph below the limit."},"es":{"q":"En Michigan, usted pasa junto a un vehículo de emergencia detenido con las luces encendidas y no puede cambiarse de carril. ¿Cuánto debe bajar la velocidad?","o":["A 5 mph menos del límite","A por lo menos 10 mph menos del límite","A 15 mph menos del límite","Exactamente a 20 mph"],"h1":"Es un número redondo, y es lo mínimo que debe bajar.","h2":"Si no puede cambiarse de carril con seguridad, debe bajar a por lo menos 10 mph menos del límite indicado y pasar con cuidado.","p":"Correcto. Baje a por lo menos 10 mph menos del límite."},"zh":{"q":"在 Michigan，你经过一辆停着、开着灯的急救车辆，但你没办法换道让开。你必须减速多少？","o":["减到比限速低 5 英里/小时","减到比限速至少低 10 英里/小时","减到比限速低 15 英里/小时","减到正好 20 英里/小时"],"h1":"这是一个整数，而且是你最少要减的速度。","h2":"如果你不能安全地换道让开，你必须把速度减到比标出的限速至少低 10 英里/小时，然后小心地开过去。","p":"对。减到比限速至少低 10 英里/小时。"},"vi":{"q":"Ở Michigan, bạn đi qua một xe khẩn cấp đang dừng và bật đèn, nhưng bạn không thể chuyển làn. Bạn phải giảm tốc độ bao nhiêu?","o":["Xuống 5 mph dưới tốc độ giới hạn","Xuống ít nhất 10 mph dưới tốc độ giới hạn","Xuống 15 mph dưới tốc độ giới hạn","Xuống đúng 20 mph"],"h1":"Đó là một số tròn, và là mức ít nhất bạn phải giảm.","h2":"Nếu bạn không thể chuyển làn an toàn, bạn phải giảm xuống ít nhất 10 mph dưới tốc độ giới hạn có biển báo và đi qua cẩn thận.","p":"Đúng. Giảm xuống ít nhất 10 mph dưới tốc độ giới hạn."},"tl":{"q":"Sa Michigan, dumadaan ka sa isang nakahintong emergency vehicle na nakabukas ang ilaw at hindi ka makalipat ng lane. Gaano ka dapat bumagal?","o":["Hanggang 5 mph mas mababa sa speed limit","Hanggang hindi bababa sa 10 mph mas mababa sa speed limit","Hanggang 15 mph mas mababa sa speed limit","Hanggang eksaktong 20 mph"],"h1":"Ito ay buong numero, at ito ang pinakamaliit na dapat mong ibagal.","h2":"Kung hindi ka ligtas na makalipat ng lane, dapat kang bumagal nang hindi bababa sa 10 mph mas mababa sa nakapaskil na speed limit at dumaan nang maingat.","p":"Tama. Bumagal nang hindi bababa sa 10 mph mas mababa sa limit."},"ar":{"q":"في Michigan، تمرّ بجانب سيارة طوارئ متوقّفة وأضواؤها مضاءة ولا تستطيع الانتقال إلى مسار آخر. كم يجب أن تخفّف سرعتك؟","o":["إلى 5 mph أقل من حد السرعة","إلى 10 mph على الأقل أقل من حد السرعة","إلى 15 mph أقل من حد السرعة","إلى 20 mph بالضبط"],"h1":"هو رقم مستدير، وهو أقل ما يجب أن تخفّفه.","h2":"إذا لم تستطع الانتقال إلى مسار آخر بأمان، يجب أن تخفّف سرعتك إلى 10 mph على الأقل أقل من حد السرعة المكتوب وأن تمرّ بحذر.","p":"صحيح. خفّف إلى 10 mph على الأقل أقل من الحد."},"ref":{"doc":"MI","page":28}},{"id":"mi-016","scope":"MI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Michigan, besides police, fire and ambulance vehicles, which stopped vehicle with flashing lights must you move over for?","o":["A parked delivery van","A car with a flat tire and no lights","A school bus with no lights on","A garbage truck or utility truck with its lights on"],"h1":"It is a work vehicle using warning lights.","h2":"Michigan’s move-over law also covers tow trucks, road crews, utility trucks and garbage trucks that are stopped with their lights flashing.","p":"Right. Move over for work trucks with flashing lights, too."},"es":{"q":"En Michigan, además de policía, bomberos y ambulancias, ¿por qué vehículo detenido con luces intermitentes debe cambiarse de carril?","o":["Una camioneta de reparto estacionada","Un carro con una llanta ponchada y sin luces","Un autobús escolar sin luces encendidas","Un camión de basura o de servicios públicos con las luces encendidas"],"h1":"Es un vehículo de trabajo que usa luces de aviso.","h2":"La ley de Michigan también cubre grúas, cuadrillas de carreteras, camiones de servicios públicos y camiones de basura detenidos con luces intermitentes.","p":"Correcto. También cámbiese de carril por camiones de trabajo con luces intermitentes."},"zh":{"q":"在 Michigan，除了警车、消防车和救护车以外，你还必须为哪种停着、闪着灯的车让出车道？","o":["一辆停着的送货车","一辆爆胎、没有开灯的汽车","一辆没有开灯的校车","一辆开着灯的垃圾车或公用事业工程车"],"h1":"这是一辆开着警示灯的工作车辆。","h2":"Michigan 的 move over 法也包括停着、闪着灯的拖车、道路施工车、公用事业工程车和垃圾车。","p":"对。对闪着灯的工作卡车也要让出车道。"},"vi":{"q":"Ở Michigan, ngoài xe cảnh sát, xe cứu hỏa và xe cứu thương, bạn phải chuyển làn để tránh xe nào đang dừng và bật đèn nhấp nháy?","o":["Một xe giao hàng đang đậu","Một xe bị xẹp lốp và không bật đèn","Một xe buýt trường học không bật đèn","Một xe rác hoặc xe tiện ích (utility truck) đang bật đèn"],"h1":"Đó là một xe làm việc đang bật đèn cảnh báo.","h2":"Luật chuyển làn (move-over law) của Michigan cũng áp dụng cho xe kéo, đội sửa đường, xe tiện ích và xe rác đang dừng và bật đèn nhấp nháy.","p":"Đúng. Cũng phải chuyển làn để tránh xe làm việc có đèn nhấp nháy."},"tl":{"q":"Sa Michigan, bukod sa sasakyan ng pulis, bumbero at ambulansya, para sa aling nakahintong sasakyan na may kumikislap na ilaw ka dapat lumipat ng lane?","o":["Isang nakaparadang delivery van","Isang kotseng flat ang gulong at walang ilaw","Isang school bus na walang nakabukas na ilaw","Isang trak ng basura o utility truck na nakabukas ang ilaw"],"h1":"Ito ay sasakyang pantrabaho na gumagamit ng warning lights.","h2":"Saklaw din ng move-over law ng Michigan ang mga tow truck, road crew, utility truck at trak ng basura na nakahinto at kumikislap ang ilaw.","p":"Tama. Lumipat din ng lane para sa mga trak na pantrabaho na may kumikislap na ilaw."},"ar":{"q":"في Michigan، بالإضافة إلى سيارات الشرطة والإطفاء والإسعاف، لأي مركبة متوقّفة بأضواء وامضة يجب أن تنتقل إلى مسار آخر؟","o":["شاحنة توصيل متوقّفة","سيارة بإطار مثقوب وبدون أضواء","حافلة مدرسية بدون أضواء مضاءة","شاحنة نفايات أو شاحنة خدمات (utility truck) وأضواؤها مضاءة"],"h1":"هي مركبة عمل تستخدم أضواء تحذير.","h2":"قانون الانتقال إلى مسار آخر (move-over law) في Michigan يشمل أيضًا شاحنات السحب وطواقم الطرق وشاحنات الخدمات وشاحنات النفايات المتوقّفة وأضواؤها تومض.","p":"صحيح. انتقل إلى مسار آخر أيضًا لشاحنات العمل ذات الأضواء الوامضة."},"ref":{"doc":"MI","page":28}},{"id":"mi-017","scope":"MI","cat":"signals","sign":null,"c":2,"en":{"q":"In Michigan, when may you turn left on a red light?","o":["Never, under any condition","Whenever no cars are coming","After a full stop, onto a one-way street going left, unless a sign forbids it","Only when a green arrow is also shown"],"h1":"The street you turn into must carry traffic only in the direction of your turn.","h2":"You may turn left on red onto a one-way street whose traffic moves to the left, after a full stop and after yielding, unless a sign forbids it.","p":"Right. Left on red is allowed onto a one-way street, after a full stop."},"es":{"q":"En Michigan, ¿cuándo puede doblar a la izquierda con luz roja?","o":["Nunca, en ninguna situación","Siempre que no vengan carros","Después de un alto total, hacia una calle de un solo sentido que va a la izquierda, salvo que una señal lo prohíba","Solo cuando también hay una flecha verde"],"h1":"La calle a la que entra debe llevar tráfico solo en la dirección de su vuelta.","h2":"Usted puede doblar a la izquierda con luz roja hacia una calle de un solo sentido cuyo tráfico va a la izquierda, después de un alto total y de ceder el paso, salvo que una señal lo prohíba.","p":"Correcto. Se permite a la izquierda con luz roja hacia una calle de un solo sentido, después de un alto total."},"zh":{"q":"在 Michigan，什么时候可以红灯左转？","o":["任何情况下都不可以","只要没有车来就可以","完全停车后，转进往左行驶的单行道，除非有标志禁止","只有同时亮绿色箭头时"],"h1":"你转进去的街道，车只能朝你转弯的方向行驶。","h2":"完全停车并让行以后，你可以在红灯时左转进车流往左走的单行道，除非有标志禁止。","p":"对。完全停车后，可以红灯左转进单行道。"},"vi":{"q":"Ở Michigan, khi nào bạn được rẽ trái khi đèn đỏ?","o":["Không bao giờ, trong mọi trường hợp","Bất cứ khi nào không có xe tới","Sau khi dừng hẳn, vào đường một chiều chạy về bên trái, trừ khi có biển cấm","Chỉ khi cũng có mũi tên xanh"],"h1":"Con đường bạn rẽ vào chỉ được có xe chạy theo hướng bạn rẽ.","h2":"Bạn được rẽ trái khi đèn đỏ vào đường một chiều có xe chạy về bên trái, sau khi dừng hẳn và nhường đường, trừ khi có biển cấm.","p":"Đúng. Được rẽ trái khi đèn đỏ vào đường một chiều, sau khi dừng hẳn."},"tl":{"q":"Sa Michigan, kailan ka puwedeng kumaliwa sa pulang ilaw?","o":["Hindi kailanman, sa anumang sitwasyon","Kapag walang paparating na kotse","Pagkatapos ng buong paghinto, papasok sa one-way street na papuntang kaliwa, maliban kung may karatulang nagbabawal","Kapag may nakikita ring berdeng arrow lamang"],"h1":"Ang kalsadang papasukan mo ay dapat may trapiko lamang sa direksyon ng liko mo.","h2":"Puwede kang kumaliwa sa pulang ilaw papasok sa one-way street na ang trapiko ay papuntang kaliwa, pagkatapos ng buong paghinto at pagbibigay-daan, maliban kung may karatulang nagbabawal.","p":"Tama. Puwedeng kumaliwa sa pula papasok sa one-way street, pagkatapos ng buong paghinto."},"ar":{"q":"في Michigan، متى يجوز لك أن تنعطف يسارًا عند الإشارة الحمراء؟","o":["أبدًا، في أي حال","كلما لم تكن هناك سيارات قادمة","بعد التوقّف التام، إلى شارع باتجاه واحد يسير نحو اليسار، إلا إذا منعت ذلك لافتة","فقط عندما يظهر أيضًا سهم أخضر"],"h1":"الشارع الذي تدخله يجب أن تسير فيه السيارات فقط في اتجاه انعطافك.","h2":"يجوز لك أن تنعطف يسارًا عند الإشارة الحمراء إلى شارع باتجاه واحد تسير فيه السيارات نحو اليسار، بعد التوقّف التام وإعطاء الأولوية، إلا إذا منعت ذلك لافتة.","p":"صحيح. الانعطاف يسارًا عند الأحمر مسموح إلى شارع باتجاه واحد، بعد التوقّف التام."},"ref":{"doc":"MI","page":30}},{"id":"mi-018","scope":"MI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Michigan, a school bus stops with flashing red lights on the other side of a highway divided by a median or barrier. Who must stop?","o":["Only traffic going the same direction as the bus","Traffic going both directions","No one, because it is a highway","Only trucks and buses"],"h1":"The divider protects the far side.","h2":"On a highway divided by a median or barrier, only traffic going the same way as the bus must stop; traffic on the other side should still drive with care.","p":"Right. On a divided highway, only traffic going the bus’s way stops."},"es":{"q":"En Michigan, un autobús escolar se detiene con luces rojas intermitentes en el otro lado de una carretera dividida por una mediana o barrera. ¿Quién debe detenerse?","o":["Solo el tráfico que va en la misma dirección que el autobús","El tráfico en ambas direcciones","Nadie, porque es una carretera","Solo camiones y autobuses"],"h1":"La división protege el lado de enfrente.","h2":"En una carretera dividida por una mediana o barrera, solo el tráfico que va en la misma dirección que el autobús debe detenerse; el tráfico del otro lado igual debe manejar con cuidado.","p":"Correcto. En una carretera dividida, solo se detiene el tráfico que va en la dirección del autobús."},"zh":{"q":"在 Michigan，一辆校车在有中央隔离带或护栏分隔的公路另一边停下，闪着红灯。谁必须停车？","o":["只有和校车同方向的车","两个方向的车","没有人，因为这是公路","只有卡车和公共汽车"],"h1":"隔离带保护着另一边。","h2":"在有中央隔离带或护栏分隔的公路上，只有和校车同方向的车必须停车；另一边的车仍然要小心开。","p":"对。在分隔公路上，只有和校车同方向的车要停。"},"vi":{"q":"Ở Michigan, một xe buýt trường học dừng và bật đèn đỏ nhấp nháy ở phía bên kia của xa lộ có dải phân cách hoặc rào chắn. Ai phải dừng lại?","o":["Chỉ xe chạy cùng hướng với xe buýt","Xe chạy cả hai hướng","Không ai cả, vì đó là xa lộ","Chỉ xe tải và xe buýt"],"h1":"Dải phân cách bảo vệ phía bên kia.","h2":"Trên xa lộ có dải phân cách hoặc rào chắn, chỉ xe chạy cùng hướng với xe buýt phải dừng; xe ở phía bên kia vẫn nên lái cẩn thận.","p":"Đúng. Trên xa lộ có dải phân cách, chỉ xe chạy cùng hướng với xe buýt phải dừng."},"tl":{"q":"Sa Michigan, huminto ang isang school bus na may kumikislap na pulang ilaw sa kabilang panig ng highway na hinahati ng median o harang. Sino ang dapat huminto?","o":["Ang trapiko lamang na papunta sa parehong direksyon ng bus","Ang trapiko sa magkabilang direksyon","Walang dapat huminto, dahil highway ito","Mga trak at bus lamang"],"h1":"Pinoprotektahan ng harang ang kabilang panig.","h2":"Sa highway na hinahati ng median o harang, ang trapiko lamang na papunta sa parehong direksyon ng bus ang dapat huminto; ang trapiko sa kabilang panig ay dapat pa ring magmaneho nang maingat.","p":"Tama. Sa hinating highway, ang trapiko lamang sa direksyon ng bus ang humihinto."},"ar":{"q":"في Michigan، توقّفت حافلة مدرسية بأضواء حمراء وامضة على الجانب الآخر من طريق سريع يفصله حاجز وسطي أو حاجز. مَن يجب أن يتوقّف؟","o":["فقط السيارات التي تسير في نفس اتجاه الحافلة","السيارات في الاتجاهين","لا أحد، لأنه طريق سريع","الشاحنات والحافلات فقط"],"h1":"الحاجز يحمي الجانب البعيد.","h2":"على طريق سريع يفصله حاجز وسطي أو حاجز، فقط السيارات التي تسير في نفس اتجاه الحافلة يجب أن تتوقّف؛ والسيارات على الجانب الآخر يجب أن تقود بحذر مع ذلك.","p":"صحيح. على طريق سريع مقسوم، تتوقّف فقط السيارات التي تسير في اتجاه الحافلة."},"ref":{"doc":"MI","page":28}},{"id":"mi-019","scope":"MI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Michigan, how far from a stopped school bus with flashing red lights must you stop?","o":["At least 10 feet","At least 20 feet","At least 30 feet","At least 50 feet"],"h1":"It is a bit longer than one car.","h2":"You must stop at least 20 feet from a school bus with flashing red lights and wait until it moves or the lights stop.","p":"Right. Stop at least 20 feet from the bus."},"es":{"q":"En Michigan, ¿a qué distancia de un autobús escolar detenido con luces rojas intermitentes debe detenerse?","o":["Por lo menos a 10 pies","Por lo menos a 20 pies","Por lo menos a 30 pies","Por lo menos a 50 pies"],"h1":"Es un poco más largo que un carro.","h2":"Usted debe detenerse por lo menos a 20 pies de un autobús escolar con luces rojas intermitentes y esperar a que avance o se apaguen las luces.","p":"Correcto. Deténgase por lo menos a 20 pies del autobús."},"zh":{"q":"在 Michigan，你必须在离闪着红灯、停着的校车多远的地方停车？","o":["至少 10 英尺","至少 20 英尺","至少 30 英尺","至少 50 英尺"],"h1":"比一辆汽车稍微长一点。","h2":"你必须在离闪着红灯的校车至少 20 英尺的地方停车，等到校车开走或红灯停止闪。","p":"对。在离校车至少 20 英尺的地方停车。"},"vi":{"q":"Ở Michigan, bạn phải dừng cách xe buýt trường học đang dừng và bật đèn đỏ nhấp nháy bao xa?","o":["Ít nhất 10 feet","Ít nhất 20 feet","Ít nhất 30 feet","Ít nhất 50 feet"],"h1":"Đó là dài hơn một chiếc xe hơi một chút.","h2":"Bạn phải dừng cách xe buýt trường học có đèn đỏ nhấp nháy ít nhất 20 feet và chờ đến khi xe buýt chạy hoặc đèn tắt.","p":"Đúng. Dừng cách xe buýt ít nhất 20 feet."},"tl":{"q":"Sa Michigan, gaano kalayo dapat kang huminto mula sa nakahintong school bus na may kumikislap na pulang ilaw?","o":["Hindi bababa sa 10 feet","Hindi bababa sa 20 feet","Hindi bababa sa 30 feet","Hindi bababa sa 50 feet"],"h1":"Medyo mas mahaba ito kaysa isang kotse.","h2":"Dapat kang huminto nang hindi bababa sa 20 feet mula sa school bus na may kumikislap na pulang ilaw at maghintay hanggang umandar ito o tumigil ang ilaw.","p":"Tama. Huminto nang hindi bababa sa 20 feet mula sa bus."},"ar":{"q":"في Michigan، على أي مسافة من حافلة مدرسية متوقّفة بأضواء حمراء وامضة يجب أن تتوقّف؟","o":["10 أقدام (feet) على الأقل","20 قدمًا (feet) على الأقل","30 قدمًا (feet) على الأقل","50 قدمًا (feet) على الأقل"],"h1":"هي أطول قليلًا من طول سيارة واحدة.","h2":"يجب أن تتوقّف على بُعد 20 قدمًا على الأقل من حافلة مدرسية بأضواء حمراء وامضة، وأن تنتظر حتى تتحرّك أو تنطفئ الأضواء.","p":"صحيح. توقّف على بُعد 20 قدمًا على الأقل من الحافلة."},"ref":{"doc":"MI","page":28}},{"id":"mi-020","scope":"MI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Michigan, on a limited-access freeway with no posted speed limit, what is the top legal speed?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"It is higher than the limit for ordinary highways with no sign.","h2":"On a limited-access freeway with no posted limit, the top legal speed is 70 mph; some rural freeways are posted higher.","p":"Right. The default freeway limit is 70 mph."},"es":{"q":"En Michigan, en una autopista de acceso limitado sin límite indicado, ¿cuál es la velocidad máxima legal?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Es más alta que el límite de carreteras comunes sin señal.","h2":"En una autopista de acceso limitado sin límite indicado, la velocidad máxima legal es 70 mph; algunas autopistas rurales tienen señales con un límite más alto.","p":"Correcto. El límite normal en autopista es 70 mph."},"zh":{"q":"在 Michigan，在没有标出限速的封闭式高速公路（limited-access freeway）上，最高合法速度是多少？","o":["55 英里/小时","60 英里/小时","65 英里/小时","70 英里/小时"],"h1":"它比没有标志的普通公路的限速高。","h2":"在没有标出限速的封闭式高速公路上，最高合法速度是 70 英里/小时；有些乡村高速公路标出的限速更高。","p":"对。高速公路默认限速是 70 英里/小时。"},"vi":{"q":"Ở Michigan, trên xa lộ cao tốc hạn chế lối vào (limited-access freeway) không có biển giới hạn tốc độ, tốc độ tối đa hợp pháp là bao nhiêu?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Nó cao hơn giới hạn của xa lộ thông thường không có biển báo.","h2":"Trên xa lộ cao tốc hạn chế lối vào không có biển giới hạn, tốc độ tối đa hợp pháp là 70 mph; một số xa lộ cao tốc ở vùng nông thôn có biển báo cao hơn.","p":"Đúng. Giới hạn mặc định trên xa lộ cao tốc là 70 mph."},"tl":{"q":"Sa Michigan, sa limited-access freeway na walang nakapaskil na speed limit, ano ang pinakamataas na legal na bilis?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Mas mataas ito kaysa sa limit ng karaniwang highway na walang karatula.","h2":"Sa limited-access freeway na walang nakapaskil na limit, ang pinakamataas na legal na bilis ay 70 mph; may ilang rural freeway na mas mataas ang nakapaskil.","p":"Tama. Ang default na limit sa freeway ay 70 mph."},"ar":{"q":"في Michigan، على طريق سريع محدود المداخل (limited-access freeway) بدون حد سرعة مكتوب، ما أعلى سرعة قانونية؟","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"هي أعلى من حد الطرق العادية التي ليس عليها لافتة.","h2":"على طريق سريع محدود المداخل بدون حد مكتوب، أعلى سرعة قانونية هي 70 mph؛ وبعض الطرق السريعة الريفية عليها حد مكتوب أعلى.","p":"صحيح. الحد الافتراضي على الطريق السريع هو 70 mph."},"ref":{"doc":"MI","page":26}},{"id":"mi-021","scope":"MI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Michigan, on a state or county highway with no posted speed limit, what is the top legal speed?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"It is lower than the freeway default.","h2":"On a state trunkline or county highway with no posted limit, the top legal speed is 55 mph.","p":"Right. The default on these highways is 55 mph."},"es":{"q":"En Michigan, en una carretera estatal o del condado sin límite indicado, ¿cuál es la velocidad máxima legal?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Es más bajo que el límite normal de autopista.","h2":"En una carretera troncal estatal o del condado sin límite indicado, la velocidad máxima legal es 55 mph.","p":"Correcto. El límite normal en estas carreteras es 55 mph."},"zh":{"q":"在 Michigan，在没有标出限速的州公路或县公路上，最高合法速度是多少？","o":["55 英里/小时","45 英里/小时","65 英里/小时","70 英里/小时"],"h1":"它比高速公路的默认限速低。","h2":"在没有标出限速的州干线公路或县公路上，最高合法速度是 55 英里/小时。","p":"对。这些公路的默认限速是 55 英里/小时。"},"vi":{"q":"Ở Michigan, trên xa lộ của tiểu bang hoặc của quận không có biển giới hạn tốc độ, tốc độ tối đa hợp pháp là bao nhiêu?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Nó thấp hơn mức mặc định trên xa lộ cao tốc.","h2":"Trên đường chính của tiểu bang (state trunkline) hoặc xa lộ của quận không có biển giới hạn, tốc độ tối đa hợp pháp là 55 mph.","p":"Đúng. Mức mặc định trên những xa lộ này là 55 mph."},"tl":{"q":"Sa Michigan, sa state o county highway na walang nakapaskil na speed limit, ano ang pinakamataas na legal na bilis?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Mas mababa ito kaysa sa default ng freeway.","h2":"Sa state trunkline o county highway na walang nakapaskil na limit, ang pinakamataas na legal na bilis ay 55 mph.","p":"Tama. Ang default sa mga highway na ito ay 55 mph."},"ar":{"q":"في Michigan، على طريق تابع للولاية أو للمقاطعة بدون حد سرعة مكتوب، ما أعلى سرعة قانونية؟","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"هي أقل من الحد الافتراضي للطريق السريع.","h2":"على طريق رئيسي للولاية (state trunkline) أو طريق للمقاطعة بدون حد مكتوب، أعلى سرعة قانونية هي 55 mph.","p":"صحيح. الحد الافتراضي على هذه الطرق هو 55 mph."},"ref":{"doc":"MI","page":26}},{"id":"mi-022","scope":"MI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Michigan, what is the highest speed limit posted on some rural freeways?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"It is 5 mph above the freeway default.","h2":"Michigan posts a 75 mph limit on some rural freeways; you may go that fast only where the signs say so.","p":"Right. Some rural freeways are posted at 75 mph."},"es":{"q":"En Michigan, ¿cuál es el límite de velocidad más alto indicado en algunas autopistas rurales?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Es 5 mph más que el límite normal de autopista.","h2":"Michigan indica un límite de 75 mph en algunas autopistas rurales; usted solo puede ir tan rápido donde las señales lo dicen.","p":"Correcto. Algunas autopistas rurales tienen límite de 75 mph."},"zh":{"q":"在 Michigan，有些乡村高速公路标出的最高限速是多少？","o":["65 英里/小时","70 英里/小时","75 英里/小时","80 英里/小时"],"h1":"比高速公路的默认限速高 5 英里/小时。","h2":"Michigan 在一些乡村高速公路上标出 75 英里/小时的限速；只有在标志这样写的地方，你才可以开这么快。","p":"对。有些乡村高速公路限速 75 英里/小时。"},"vi":{"q":"Ở Michigan, giới hạn tốc độ cao nhất được ghi trên biển ở một số xa lộ cao tốc vùng nông thôn là bao nhiêu?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Nó cao hơn mức mặc định trên xa lộ cao tốc 5 mph.","h2":"Michigan đặt giới hạn 75 mph trên một số xa lộ cao tốc vùng nông thôn; bạn chỉ được chạy nhanh như vậy ở nơi có biển báo cho phép.","p":"Đúng. Một số xa lộ cao tốc vùng nông thôn có biển 75 mph."},"tl":{"q":"Sa Michigan, ano ang pinakamataas na speed limit na nakapaskil sa ilang rural freeway?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Ito ay 5 mph na mas mataas sa default ng freeway.","h2":"Naglalagay ang Michigan ng 75 mph na limit sa ilang rural freeway; puwede kang tumakbo nang ganoon kabilis lamang kung saan sinasabi ng mga karatula.","p":"Tama. May ilang rural freeway na nakapaskil sa 75 mph."},"ar":{"q":"في Michigan، ما أعلى حد سرعة مكتوب على بعض الطرق السريعة الريفية؟","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"هو أعلى من الحد الافتراضي للطريق السريع بـ5 mph.","h2":"تضع Michigan حدًا قدره 75 mph على بعض الطرق السريعة الريفية؛ ولا يجوز لك أن تسير بهذه السرعة إلا حيث تقول اللافتات ذلك.","p":"صحيح. بعض الطرق السريعة الريفية عليها حد 75 mph."},"ref":{"doc":"MI","page":null}},{"id":"mi-023","scope":"MI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Michigan, what is the speed limit in a residential subdivision?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"It is the same number many states use near homes.","h2":"The speed limit in a residential subdivision is 25 mph, because children and people walking are often near the street.","p":"Right. Residential subdivisions are 25 mph."},"es":{"q":"En Michigan, ¿cuál es el límite de velocidad en un fraccionamiento residencial?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Es el mismo número que muchos estados usan cerca de las casas.","h2":"El límite de velocidad en un fraccionamiento residencial es 25 mph, porque a menudo hay niños y peatones cerca de la calle.","p":"Correcto. En fraccionamientos residenciales el límite es 25 mph."},"zh":{"q":"在 Michigan，住宅小区里的限速是多少？","o":["20 英里/小时","25 英里/小时","30 英里/小时","35 英里/小时"],"h1":"很多州在住家附近也用这个数字。","h2":"住宅小区里的限速是 25 英里/小时，因为街边常常有孩子和走路的人。","p":"对。住宅小区限速 25 英里/小时。"},"vi":{"q":"Ở Michigan, giới hạn tốc độ trong khu dân cư (residential subdivision) là bao nhiêu?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Đó là cùng con số mà nhiều tiểu bang dùng gần nhà ở.","h2":"Giới hạn tốc độ trong khu dân cư là 25 mph, vì trẻ em và người đi bộ thường ở gần đường.","p":"Đúng. Khu dân cư là 25 mph."},"tl":{"q":"Sa Michigan, ano ang speed limit sa isang residential subdivision?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Ito ang parehong numero na ginagamit ng maraming estado malapit sa mga bahay.","h2":"Ang speed limit sa residential subdivision ay 25 mph, dahil madalas may mga bata at naglalakad malapit sa kalsada.","p":"Tama. 25 mph sa residential subdivision."},"ar":{"q":"في Michigan، ما حد السرعة في حي سكني (residential subdivision)؟","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"هو نفس الرقم الذي تستخدمه ولايات كثيرة قرب البيوت.","h2":"حد السرعة في الحي السكني هو 25 mph، لأن الأطفال والمشاة يكونون غالبًا قريبين من الشارع.","p":"صحيح. الأحياء السكنية 25 mph."},"ref":{"doc":"MI","page":26}},{"id":"mi-024","scope":"MI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Michigan, what is the speed limit inside a mobile home park?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"It is lower than a residential subdivision, but more than 10.","h2":"The speed limit inside a mobile home park is 15 mph, because homes and people are very close to the road.","p":"Right. Mobile home parks are 15 mph."},"es":{"q":"En Michigan, ¿cuál es el límite de velocidad dentro de un parque de casas móviles?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"Es más bajo que en un fraccionamiento residencial, pero más de 10.","h2":"El límite de velocidad dentro de un parque de casas móviles es 15 mph, porque las casas y las personas están muy cerca del camino.","p":"Correcto. En parques de casas móviles el límite es 15 mph."},"zh":{"q":"在 Michigan，移动房屋社区（mobile home park）里的限速是多少？","o":["5 英里/小时","10 英里/小时","20 英里/小时","15 英里/小时"],"h1":"它比住宅小区低，但比 10 高。","h2":"移动房屋社区里的限速是 15 英里/小时，因为房子和人离路很近。","p":"对。移动房屋社区限速 15 英里/小时。"},"vi":{"q":"Ở Michigan, giới hạn tốc độ bên trong khu nhà di động (mobile home park) là bao nhiêu?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"Nó thấp hơn khu dân cư, nhưng cao hơn 10.","h2":"Giới hạn tốc độ bên trong khu nhà di động là 15 mph, vì nhà cửa và người đi bộ ở rất gần đường.","p":"Đúng. Khu nhà di động là 15 mph."},"tl":{"q":"Sa Michigan, ano ang speed limit sa loob ng mobile home park?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"Mas mababa ito kaysa sa residential subdivision, pero higit sa 10.","h2":"Ang speed limit sa loob ng mobile home park ay 15 mph, dahil napakalapit ng mga bahay at tao sa kalsada.","p":"Tama. 15 mph sa mobile home park."},"ar":{"q":"في Michigan، ما حد السرعة داخل مجمّع البيوت المتنقلة (mobile home park)؟","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"هو أقل من الحي السكني، لكنه أكثر من 10.","h2":"حد السرعة داخل مجمّع البيوت المتنقلة هو 15 mph، لأن البيوت والناس قريبون جدًا من الطريق.","p":"صحيح. مجمّعات البيوت المتنقلة 15 mph."},"ref":{"doc":"MI","page":26}},{"id":"mi-025","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, at what blood alcohol level does the stricter high-BAC drunk driving law apply?","o":["0.10 percent or more","0.12 percent or more","0.17 percent or more","0.20 percent or more"],"h1":"It is about twice the regular adult limit.","h2":"Michigan’s high-BAC law, sometimes called the super drunk law, applies at 0.17 percent or more and carries harsher penalties than a regular drunk driving charge.","p":"Right. The high-BAC law starts at 0.17 percent."},"es":{"q":"En Michigan, ¿a partir de qué nivel de alcohol en la sangre se aplica la ley más estricta de alto nivel de alcohol?","o":["0.10 por ciento o más","0.12 por ciento o más","0.17 por ciento o más","0.20 por ciento o más"],"h1":"Es casi el doble del límite normal para adultos.","h2":"La ley de alto nivel de alcohol de Michigan, a veces llamada ley de súper ebrio, aplica desde 0.17 por ciento y trae castigos más duros que un cargo normal por manejar ebrio.","p":"Correcto. La ley de alto nivel empieza en 0.17 por ciento."},"zh":{"q":"在 Michigan，血液酒精浓度达到多少时，适用更严格的高酒精浓度（high-BAC）醉驾法？","o":["0.10% 或更高","0.12% 或更高","0.17% 或更高","0.20% 或更高"],"h1":"大约是一般成年人限值的两倍。","h2":"Michigan 的高酒精浓度法，有时叫做 super drunk 法，在 0.17% 或更高时适用，处罚比一般醉驾罪更重。","p":"对。高酒精浓度法从 0.17% 开始。"},"vi":{"q":"Ở Michigan, luật lái xe say rượu nghiêm khắc hơn cho nồng độ cồn cao (high-BAC) áp dụng từ mức nồng độ cồn trong máu nào?","o":["0.10 phần trăm trở lên","0.12 phần trăm trở lên","0.17 phần trăm trở lên","0.20 phần trăm trở lên"],"h1":"Nó khoảng gấp đôi giới hạn thông thường của người lớn.","h2":"Luật nồng độ cồn cao (high-BAC) của Michigan, đôi khi gọi là luật say xỉn nặng (super drunk law), áp dụng từ 0.17 phần trăm trở lên và có hình phạt nặng hơn tội lái xe say rượu thông thường.","p":"Đúng. Luật high-BAC bắt đầu từ 0.17 phần trăm."},"tl":{"q":"Sa Michigan, sa anong antas ng alak sa dugo (blood alcohol) nalalapat ang mas mahigpit na high-BAC drunk driving law?","o":["0.10 porsiyento o higit pa","0.12 porsiyento o higit pa","0.17 porsiyento o higit pa","0.20 porsiyento o higit pa"],"h1":"Halos doble ito ng karaniwang limit para sa adult.","h2":"Ang high-BAC law ng Michigan, na minsang tinatawag na super drunk law, ay nalalapat sa 0.17 porsiyento o higit pa at may mas mabigat na parusa kaysa sa karaniwang kaso ng drunk driving.","p":"Tama. Nagsisimula ang high-BAC law sa 0.17 porsiyento."},"ar":{"q":"في Michigan، عند أي نسبة كحول في الدم يُطبَّق قانون القيادة تحت تأثير الكحول الأشدّ للنسبة العالية (high-BAC)؟","o":["0.10 بالمئة أو أكثر","0.12 بالمئة أو أكثر","0.17 بالمئة أو أكثر","0.20 بالمئة أو أكثر"],"h1":"هي نحو ضعف الحد العادي للبالغين.","h2":"قانون النسبة العالية (high-BAC) في Michigan، الذي يُسمّى أحيانًا قانون السُّكر الشديد (super drunk law)، يُطبَّق عند 0.17 بالمئة أو أكثر وعقوباته أشدّ من تهمة القيادة تحت تأثير الكحول العادية.","p":"صحيح. يبدأ قانون high-BAC عند 0.17 بالمئة."},"ref":{"doc":"MI","page":null}},{"id":"mi-026","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, a driver 21 or older is legally drunk at what blood alcohol level?","o":["0.08 percent or more","0.05 percent or more","0.10 percent or more","0.15 percent or more"],"h1":"It is less than one tenth of one percent.","h2":"A driver 21 or older breaks Michigan’s drunk driving law at a blood alcohol level of 0.08 percent or more.","p":"Right. The adult limit is 0.08 percent."},"es":{"q":"En Michigan, ¿con qué nivel de alcohol en la sangre se considera legalmente ebrio a un conductor de 21 años o más?","o":["0.08 por ciento o más","0.05 por ciento o más","0.10 por ciento o más","0.15 por ciento o más"],"h1":"Es menos de una décima de uno por ciento.","h2":"Un conductor de 21 años o más viola la ley de Michigan sobre manejar ebrio con 0.08 por ciento o más de alcohol en la sangre.","p":"Correcto. El límite para adultos es 0.08 por ciento."},"zh":{"q":"在 Michigan，21 岁或以上的司机，血液酒精浓度达到多少在法律上就算醉驾？","o":["0.08% 或更高","0.05% 或更高","0.10% 或更高","0.15% 或更高"],"h1":"它不到百分之零点一。","h2":"21 岁或以上的司机，血液酒精浓度达到 0.08% 或更高，就违反了 Michigan 的醉驾法。","p":"对。成年人的限值是 0.08%。"},"vi":{"q":"Ở Michigan, người lái từ 21 tuổi trở lên bị xem là say rượu theo luật ở mức nồng độ cồn trong máu nào?","o":["0.08 phần trăm trở lên","0.05 phần trăm trở lên","0.10 phần trăm trở lên","0.15 phần trăm trở lên"],"h1":"Nó nhỏ hơn một phần mười của một phần trăm.","h2":"Người lái từ 21 tuổi trở lên vi phạm luật lái xe say rượu của Michigan khi nồng độ cồn trong máu từ 0.08 phần trăm trở lên.","p":"Đúng. Giới hạn cho người lớn là 0.08 phần trăm."},"tl":{"q":"Sa Michigan, ang driver na 21 taong gulang pataas ay legal na lasing sa anong antas ng alak sa dugo?","o":["0.08 porsiyento o higit pa","0.05 porsiyento o higit pa","0.10 porsiyento o higit pa","0.15 porsiyento o higit pa"],"h1":"Mas mababa ito sa ikasampung bahagi ng isang porsiyento.","h2":"Ang driver na 21 taong gulang pataas ay lumalabag sa drunk driving law ng Michigan kapag ang alak sa dugo ay 0.08 porsiyento o higit pa.","p":"Tama. Ang limit para sa adult ay 0.08 porsiyento."},"ar":{"q":"في Michigan، السائق الذي عمره 21 سنة أو أكثر يُعتبر قانونيًا في حالة سُكر عند أي نسبة كحول في الدم؟","o":["0.08 بالمئة أو أكثر","0.05 بالمئة أو أكثر","0.10 بالمئة أو أكثر","0.15 بالمئة أو أكثر"],"h1":"هي أقل من عُشر واحد بالمئة.","h2":"السائق الذي عمره 21 سنة أو أكثر يخالف قانون القيادة تحت تأثير الكحول في Michigan عندما تكون نسبة الكحول في دمه 0.08 بالمئة أو أكثر.","p":"صحيح. حد البالغين هو 0.08 بالمئة."},"ref":{"doc":"MI","page":null}},{"id":"mi-027","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, how much alcohol may a driver under 21 have in their body?","o":["Up to 0.08 percent","No alcohol from drinking at all","Up to 0.05 percent","Up to 0.10 percent at night"],"h1":"This is called zero tolerance.","h2":"Michigan has zero tolerance for drivers under 21: a level of 0.02 percent, or any alcohol from drinking, breaks the law.","p":"Right. Drivers under 21 may not drive with alcohol from drinking."},"es":{"q":"En Michigan, ¿cuánto alcohol puede tener en el cuerpo un conductor menor de 21 años?","o":["Hasta 0.08 por ciento","Nada de alcohol por haber tomado","Hasta 0.05 por ciento","Hasta 0.10 por ciento de noche"],"h1":"Esto se llama tolerancia cero.","h2":"Michigan tiene tolerancia cero para conductores menores de 21 años: un nivel de 0.02 por ciento, o cualquier alcohol por haber tomado, viola la ley.","p":"Correcto. Los menores de 21 no pueden manejar con alcohol por haber tomado."},"zh":{"q":"在 Michigan，21 岁以下的司机体内可以有多少酒精？","o":["最多 0.08%","完全不能有喝酒带来的酒精","最多 0.05%","晚上最多 0.10%"],"h1":"这叫做零容忍。","h2":"Michigan 对 21 岁以下的司机实行零容忍：浓度达到 0.02%，或者体内有任何喝酒带来的酒精，就违法。","p":"对。21 岁以下的司机不能在喝酒后开车。"},"vi":{"q":"Ở Michigan, người lái dưới 21 tuổi được có bao nhiêu cồn trong cơ thể?","o":["Tối đa 0.08 phần trăm","Hoàn toàn không có cồn do uống rượu","Tối đa 0.05 phần trăm","Tối đa 0.10 phần trăm vào ban đêm"],"h1":"Điều này gọi là không khoan nhượng (zero tolerance).","h2":"Michigan không khoan nhượng (zero tolerance) với người lái dưới 21 tuổi: mức 0.02 phần trăm, hoặc bất kỳ lượng cồn nào do uống rượu, là vi phạm luật.","p":"Đúng. Người lái dưới 21 tuổi không được lái xe khi có cồn do uống rượu."},"tl":{"q":"Sa Michigan, gaano karaming alak ang puwedeng nasa katawan ng driver na wala pang 21?","o":["Hanggang 0.08 porsiyento","Walang alak mula sa pag-inom kahit kaunti","Hanggang 0.05 porsiyento","Hanggang 0.10 porsiyento sa gabi"],"h1":"Ito ay tinatawag na zero tolerance.","h2":"May zero tolerance ang Michigan para sa mga driver na wala pang 21: ang antas na 0.02 porsiyento, o anumang alak mula sa pag-inom, ay labag sa batas.","p":"Tama. Hindi puwedeng magmaneho ang driver na wala pang 21 na may alak mula sa pag-inom."},"ar":{"q":"في Michigan، كم من الكحول يجوز أن يكون في جسم سائق عمره أقل من 21 سنة؟","o":["حتى 0.08 بالمئة","لا كحول من الشرب أبدًا","حتى 0.05 بالمئة","حتى 0.10 بالمئة في الليل"],"h1":"هذا يُسمّى عدم التسامح المطلق (zero tolerance).","h2":"في Michigan عدم تسامح مطلق (zero tolerance) مع السائقين الذين أعمارهم أقل من 21 سنة: نسبة 0.02 بالمئة، أو أي كحول من الشرب، مخالفة للقانون.","p":"صحيح. السائقون تحت 21 سنة لا يجوز لهم القيادة وفي أجسامهم كحول من الشرب."},"ref":{"doc":"MI","page":14}},{"id":"mi-028","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, what kind of car insurance must every vehicle owner carry?","o":["Only collision coverage","Only coverage for the other driver’s car","No insurance is required","No-fault insurance that includes personal injury protection"],"h1":"Michigan is known as a no-fault state.","h2":"Michigan is a no-fault state, so every owner must carry no-fault insurance with personal injury protection, which pays your own medical costs after a crash.","p":"Right. Michigan requires no-fault insurance with personal injury protection."},"es":{"q":"En Michigan, ¿qué tipo de seguro de carro debe tener todo dueño de vehículo?","o":["Solo cobertura de choque","Solo cobertura para el carro del otro conductor","No se requiere seguro","Seguro sin culpa que incluye protección por lesiones personales"],"h1":"Michigan es conocido como un estado sin culpa.","h2":"Michigan es un estado sin culpa, así que todo dueño debe tener seguro sin culpa con protección por lesiones personales, que paga sus propios gastos médicos después de un choque.","p":"Correcto. Michigan exige seguro sin culpa con protección por lesiones personales."},"zh":{"q":"在 Michigan，每位车主都必须买哪种汽车保险？","o":["只买碰撞险","只买赔偿对方汽车的保险","不需要任何保险","包括个人伤害保障的无过失保险"],"h1":"Michigan 被称为无过失州（no-fault state）。","h2":"Michigan 是无过失州，所以每位车主都必须买包括个人伤害保障的无过失保险，它在车祸后支付你自己的医疗费用。","p":"对。Michigan 要求包括个人伤害保障的无过失保险。"},"vi":{"q":"Ở Michigan, mọi chủ xe phải mua loại bảo hiểm xe nào?","o":["Chỉ bảo hiểm va chạm","Chỉ bảo hiểm cho xe của người lái kia","Không cần bảo hiểm","Bảo hiểm không phân lỗi (no-fault) có bảo vệ thương tích cá nhân (personal injury protection)"],"h1":"Michigan được biết là một tiểu bang không phân lỗi (no-fault).","h2":"Michigan là tiểu bang không phân lỗi (no-fault), nên mọi chủ xe phải mua bảo hiểm không phân lỗi có bảo vệ thương tích cá nhân, loại trả chi phí y tế của chính bạn sau tai nạn.","p":"Đúng. Michigan yêu cầu bảo hiểm không phân lỗi có bảo vệ thương tích cá nhân."},"tl":{"q":"Sa Michigan, anong uri ng car insurance ang dapat mayroon ang bawat may-ari ng sasakyan?","o":["Collision coverage lamang","Coverage lamang para sa kotse ng ibang driver","Hindi kailangan ng insurance","No-fault insurance na may kasamang personal injury protection"],"h1":"Kilala ang Michigan bilang isang no-fault state.","h2":"Ang Michigan ay no-fault state, kaya dapat may no-fault insurance na may personal injury protection ang bawat may-ari, na nagbabayad ng sarili mong gastos sa pagpapagamot pagkatapos ng banggaan.","p":"Tama. Hinihingi ng Michigan ang no-fault insurance na may personal injury protection."},"ar":{"q":"في Michigan، ما نوع تأمين السيارة الذي يجب أن يحمله كل مالك مركبة؟","o":["تأمين التصادم فقط","تأمين لسيارة السائق الآخر فقط","لا يُطلب أي تأمين","تأمين بدون تحديد خطأ (no-fault) يشمل حماية الإصابات الشخصية (personal injury protection)"],"h1":"تُعرف Michigan بأنها ولاية بدون تحديد خطأ (no-fault).","h2":"Michigan ولاية بدون تحديد خطأ (no-fault)، لذلك يجب أن يحمل كل مالك تأمين no-fault يشمل حماية الإصابات الشخصية، الذي يدفع تكاليف علاجك أنت بعد الحادث.","p":"صحيح. تطلب Michigan تأمين no-fault يشمل حماية الإصابات الشخصية."},"ref":{"doc":"MI","page":null}},{"id":"mi-029","scope":"MI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Michigan, how much space must you leave between your car and a bicycle when you pass it?","o":["1 foot","At least 3 feet","At least 10 feet","One full lane always"],"h1":"It is about the length of a yardstick.","h2":"In Michigan you must leave at least 3 feet of space between your vehicle and a bicyclist when you pass.","p":"Right. Give a bicycle at least 3 feet."},"es":{"q":"En Michigan, ¿cuánto espacio debe dejar entre su carro y una bicicleta al rebasarla?","o":["1 pie","Por lo menos 3 pies","Por lo menos 10 pies","Siempre un carril completo"],"h1":"Es más o menos el largo de una regla de una yarda.","h2":"En Michigan usted debe dejar por lo menos 3 pies de espacio entre su vehículo y un ciclista al rebasarlo.","p":"Correcto. Deje por lo menos 3 pies a una bicicleta."},"zh":{"q":"在 Michigan，超过自行车时，你的车和自行车之间必须留多少空间？","o":["1 英尺","至少 3 英尺","至少 10 英尺","总是留出整整一条车道"],"h1":"大约是一把码尺（yardstick）的长度。","h2":"在 Michigan，超过骑自行车的人时，你的车和骑车人之间必须至少留 3 英尺的空间。","p":"对。给自行车至少留 3 英尺。"},"vi":{"q":"Ở Michigan, khi vượt xe đạp, bạn phải chừa bao nhiêu khoảng cách giữa xe của bạn và xe đạp?","o":["1 foot","Ít nhất 3 feet","Ít nhất 10 feet","Luôn luôn một làn đường trọn vẹn"],"h1":"Khoảng bằng chiều dài một cây thước yard (yardstick).","h2":"Ở Michigan, khi vượt người đi xe đạp, bạn phải chừa ít nhất 3 feet khoảng cách giữa xe của bạn và người đi xe đạp.","p":"Đúng. Chừa cho xe đạp ít nhất 3 feet."},"tl":{"q":"Sa Michigan, gaano kalaking espasyo ang dapat mong iwan sa pagitan ng kotse mo at ng bisikleta kapag nilalampasan mo ito?","o":["1 foot","Hindi bababa sa 3 feet","Hindi bababa sa 10 feet","Laging isang buong lane"],"h1":"Halos kasinghaba ito ng isang yardstick.","h2":"Sa Michigan, dapat kang mag-iwan ng hindi bababa sa 3 feet na espasyo sa pagitan ng sasakyan mo at ng nagbibisikleta kapag nilalampasan mo siya.","p":"Tama. Bigyan ang bisikleta ng hindi bababa sa 3 feet."},"ar":{"q":"في Michigan، ما المسافة التي يجب أن تتركها بين سيارتك والدراجة عندما تتجاوزها؟","o":["قدم واحد (1 foot)","3 أقدام على الأقل","10 أقدام على الأقل","حارة كاملة دائمًا"],"h1":"إنها تقريبًا بطول مسطرة الياردة (yardstick).","h2":"في Michigan يجب أن تترك مسافة 3 أقدام على الأقل بين مركبتك وراكب الدراجة عندما تتجاوزه.","p":"صحيح. اترك للدراجة 3 أقدام على الأقل."},"ref":{"doc":"MI","page":57}},{"id":"mi-030","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, when does the driver's license of a person under 21 expire?","o":["On their 18th birthday","Exactly one year after it is issued","On their 21st birthday","After eight years"],"h1":"Other drivers usually get four years, but young drivers have a special date.","h2":"In Michigan, a license issued to a driver under 21 expires on the driver's 21st birthday.","p":"Right. Under 21, the license ends on the 21st birthday."},"es":{"q":"En Michigan, ¿cuándo vence la licencia de manejar de una persona menor de 21 años?","o":["En su cumpleaños número 18","Un año exacto después de emitida","En su cumpleaños número 21","Después de ocho años"],"h1":"Los demás conductores suelen tener cuatro años, pero los jóvenes tienen una fecha especial.","h2":"En Michigan, la licencia de un conductor menor de 21 años vence en su cumpleaños número 21.","p":"Correcto. Si es menor de 21, la licencia vence al cumplir 21."},"zh":{"q":"在 Michigan，未满 21 岁的人的驾照什么时候到期？","o":["在他们 18 岁生日那天","发放后正好一年","在他们 21 岁生日那天","八年以后"],"h1":"其他司机通常可以用四年，但年轻司机有一个特别的日期。","h2":"在 Michigan，发给未满 21 岁司机的驾照在司机 21 岁生日那天到期。","p":"对。未满 21 岁，驾照在 21 岁生日那天到期。"},"vi":{"q":"Ở Michigan, bằng lái của người dưới 21 tuổi hết hạn khi nào?","o":["Vào sinh nhật thứ 18 của họ","Đúng một năm sau khi được cấp","Vào sinh nhật thứ 21 của họ","Sau tám năm"],"h1":"Những người lái khác thường được bốn năm, nhưng người lái trẻ có một ngày đặc biệt.","h2":"Ở Michigan, bằng lái cấp cho người lái dưới 21 tuổi hết hạn vào sinh nhật thứ 21 của người lái.","p":"Đúng. Dưới 21 tuổi, bằng lái hết hạn vào sinh nhật thứ 21."},"tl":{"q":"Sa Michigan, kailan mag-e-expire ang driver's license ng taong wala pang 21 taong gulang?","o":["Sa kanilang ika-18 kaarawan","Eksaktong isang taon matapos itong ibigay","Sa kanilang ika-21 kaarawan","Pagkalipas ng walong taon"],"h1":"Karaniwang apat na taon ang ibang driver, pero may espesyal na petsa ang mga batang driver.","h2":"Sa Michigan, ang license na ibinigay sa driver na wala pang 21 taong gulang ay mag-e-expire sa ika-21 kaarawan ng driver.","p":"Tama. Kapag wala pang 21, matatapos ang license sa ika-21 kaarawan."},"ar":{"q":"في Michigan، متى تنتهي رخصة القيادة لشخص عمره أقل من 21 سنة؟","o":["في عيد ميلاده الـ 18","بعد سنة واحدة بالضبط من إصدارها","في عيد ميلاده الـ 21","بعد ثماني سنوات"],"h1":"السائقون الآخرون يحصلون عادةً على أربع سنوات، لكن للسائقين الشباب تاريخ خاص.","h2":"في Michigan، تنتهي الرخصة الصادرة لسائق عمره أقل من 21 سنة في عيد ميلاد السائق الـ 21.","p":"صحيح. إذا كان العمر أقل من 21، تنتهي الرخصة في عيد الميلاد الـ 21."},"ref":{"doc":"MI","page":10}},{"id":"mi-031","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, how long do points stay on your driving record?","o":["Two years from the date of conviction","Six months","Ten years","For life"],"h1":"It is less than the seven years most convictions stay on the record.","h2":"In Michigan, points stay on your driving record for two years from the date you are convicted.","p":"Right. Points stay for two years."},"es":{"q":"En Michigan, ¿cuánto tiempo se quedan los puntos en su historial de manejo?","o":["Dos años desde la fecha de la condena","Seis meses","Diez años","Toda la vida"],"h1":"Es menos que los siete años que se quedan la mayoría de las condenas.","h2":"En Michigan, los puntos se quedan en su historial de manejo por dos años desde la fecha de la condena.","p":"Correcto. Los puntos se quedan dos años."},"zh":{"q":"在 Michigan，扣分会在你的驾驶记录上保留多久？","o":["从定罪之日起两年","六个月","十年","终身"],"h1":"它比大多数定罪在记录上保留的七年要短。","h2":"在 Michigan，扣分从你被定罪之日起在你的驾驶记录上保留两年。","p":"对。扣分保留两年。"},"vi":{"q":"Ở Michigan, điểm phạt ở lại trong hồ sơ lái xe của bạn bao lâu?","o":["Hai năm kể từ ngày bị kết tội","Sáu tháng","Mười năm","Suốt đời"],"h1":"Thời gian này ngắn hơn bảy năm mà hầu hết các bản án ở lại trong hồ sơ.","h2":"Ở Michigan, điểm phạt ở lại trong hồ sơ lái xe của bạn trong hai năm kể từ ngày bạn bị kết tội.","p":"Đúng. Điểm phạt ở lại hai năm."},"tl":{"q":"Sa Michigan, gaano katagal mananatili ang points sa iyong driving record?","o":["Dalawang taon mula sa petsa ng conviction","Anim na buwan","Sampung taon","Habambuhay"],"h1":"Mas maikli ito kaysa sa pitong taon na nananatili sa record ang karamihan ng conviction.","h2":"Sa Michigan, mananatili ang points sa iyong driving record nang dalawang taon mula sa petsa na ikaw ay na-convict.","p":"Tama. Mananatili ang points nang dalawang taon."},"ar":{"q":"في Michigan، كم من الوقت تبقى النقاط في سجل قيادتك؟","o":["سنتان من تاريخ الإدانة","ستة أشهر","عشر سنوات","مدى الحياة"],"h1":"إنها أقل من السنوات السبع التي تبقى فيها معظم الإدانات في السجل.","h2":"في Michigan، تبقى النقاط في سجل قيادتك لمدة سنتين من تاريخ إدانتك.","p":"صحيح. تبقى النقاط لمدة سنتين."},"ref":{"doc":"MI","page":13}},{"id":"mi-032","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, how long is a temporary instruction permit (TIP) valid?","o":["30 days","90 days","180 days","Two years"],"h1":"It lasts about half a year.","h2":"In Michigan, a temporary instruction permit is valid for 180 days.","p":"Right. A TIP is good for 180 days."},"es":{"q":"En Michigan, ¿por cuánto tiempo es válido un permiso temporal de instrucción (TIP)?","o":["30 días","90 días","180 días","Dos años"],"h1":"Dura más o menos medio año.","h2":"En Michigan, un permiso temporal de instrucción es válido por 180 días.","p":"Correcto. Un TIP es válido por 180 días."},"ref":{"doc":"MI","page":7}},{"id":"mi-033","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, an adult has a temporary instruction permit (TIP). How long must they practice before the driving skills test?","o":["At least 30 days","At least 7 days","At least 6 months","At least one year"],"h1":"It is about one month.","h2":"In Michigan, a driver with a TIP must practice for at least 30 days before taking the driving skills test.","p":"Right. At least 30 days of practice come first."},"es":{"q":"En Michigan, un adulto tiene un permiso temporal de instrucción (TIP). ¿Cuánto tiempo debe practicar antes del examen de manejo?","o":["Por lo menos 30 días","Por lo menos 7 días","Por lo menos 6 meses","Por lo menos un año"],"h1":"Es más o menos un mes.","h2":"En Michigan, un conductor con TIP debe practicar por lo menos 30 días antes de tomar el examen de manejo.","p":"Correcto. Primero se practican por lo menos 30 días."},"ref":{"doc":"MI","page":7}},{"id":"mi-034","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, how many hours of supervised driving must a teen log before starting Segment 2 of driver education?","o":["10 hours","30 hours","50 hours","100 hours"],"h1":"It is less than the total needed for the driving skills test.","h2":"In Michigan, a teen must log at least 30 hours of supervised driving, including 2 at night, before starting Segment 2.","p":"Right. Segment 2 needs a log of at least 30 hours."},"es":{"q":"En Michigan, ¿cuántas horas de manejo supervisado debe anotar un adolescente antes de empezar el Segmento 2 de educación vial?","o":["10 horas","30 horas","50 horas","100 horas"],"h1":"Es menos que el total que se necesita para el examen de manejo.","h2":"En Michigan, un adolescente debe anotar por lo menos 30 horas de manejo supervisado, incluidas 2 de noche, antes de empezar el Segmento 2.","p":"Correcto. El Segmento 2 pide un registro de por lo menos 30 horas."},"ref":{"doc":"MI","page":5}},{"id":"mi-035","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, how long are new drivers placed on probation?","o":["Six months","One year","Until age 18","At least three years"],"h1":"It lasts longer than the graduated license levels.","h2":"In Michigan, new drivers, including teens, are on probation for at least three years.","p":"Right. Probation lasts at least three years."},"es":{"q":"En Michigan, ¿por cuánto tiempo quedan a prueba (probation) los conductores nuevos?","o":["Seis meses","Un año","Hasta los 18 años","Por lo menos tres años"],"h1":"Dura más que los niveles de la licencia gradual.","h2":"En Michigan, los conductores nuevos, incluidos los adolescentes, quedan a prueba por lo menos tres años.","p":"Correcto. El periodo de prueba dura por lo menos tres años."},"ref":{"doc":"MI","page":9}},{"id":"mi-036","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, how often must you renew your driver's license in person at a Secretary of State office?","o":["Every 4 years","Every 12 years","Every 20 years","Only once, at age 65"],"h1":"You can renew online or by mail in between, but not forever.","h2":"In Michigan, you must renew your license at a Secretary of State office every 12 years, for a vision check and a new photo.","p":"Right. Every 12 years you go in person."},"es":{"q":"En Michigan, ¿cada cuánto debe renovar su licencia en persona en una oficina del Secretario de Estado?","o":["Cada 4 años","Cada 12 años","Cada 20 años","Solo una vez, a los 65 años"],"h1":"Entre una visita y otra puede renovar por internet o por correo, pero no para siempre.","h2":"En Michigan, debe renovar su licencia en una oficina del Secretario de Estado cada 12 años, para un examen de la vista y una foto nueva.","p":"Correcto. Cada 12 años debe ir en persona."},"ref":{"doc":"MI","page":10}},{"id":"mi-037","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, how many points within two years lead to a driver assessment reexamination?","o":["12 or more points","4 or more points","6 or more points","20 or more points"],"h1":"It is twice as many as six.","h2":"In Michigan, a driver with 12 or more points within two years must go to a driver assessment reexamination.","p":"Right. Twelve points in two years means a reexamination."},"es":{"q":"En Michigan, ¿cuántos puntos en dos años llevan a una reevaluación del conductor?","o":["12 puntos o más","4 puntos o más","6 puntos o más","20 puntos o más"],"h1":"Es el doble de seis.","h2":"En Michigan, un conductor con 12 puntos o más en dos años debe ir a una reevaluación del conductor.","p":"Correcto. Doce puntos en dos años llevan a una reevaluación."},"ref":{"doc":"MI","page":13}},{"id":"mi-038","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, how many points go on your record if you refuse a chemical alcohol test?","o":["Two points","Three points","Four points","Six points"],"h1":"It is the highest point level in the Michigan list.","h2":"In Michigan, refusing a chemical alcohol test puts six points on your driving record.","p":"Right. A refusal costs six points."},"es":{"q":"En Michigan, ¿cuántos puntos se ponen en su historial si se niega a una prueba química de alcohol?","o":["Dos puntos","Tres puntos","Cuatro puntos","Seis puntos"],"h1":"Es el nivel de puntos más alto de la lista de Michigan.","h2":"En Michigan, negarse a una prueba química de alcohol pone seis puntos en su historial de manejo.","p":"Correcto. Negarse cuesta seis puntos."},"ref":{"doc":"MI","page":14}},{"id":"mi-039","scope":"MI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Michigan, what happens to the fine for a moving violation in a work zone?","o":["It stays the same","It is cut in half","It is doubled","It becomes a warning only"],"h1":"Work zones protect workers, so the penalty goes up.","h2":"In Michigan, fines for all moving violations are doubled in work zones.","p":"Right. Work zone fines are doubled."},"es":{"q":"En Michigan, ¿qué pasa con la multa por una infracción de tránsito en una zona de obras?","o":["Sigue igual","Se reduce a la mitad","Se duplica","Solo se da una advertencia"],"h1":"Las zonas de obras protegen a los trabajadores, así que la sanción sube.","h2":"En Michigan, las multas por todas las infracciones de tránsito se duplican en las zonas de obras.","p":"Correcto. En zonas de obras las multas se duplican."},"ref":{"doc":"MI","page":27}},{"id":"mi-040","scope":"MI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Michigan, what is the fine for a first offense of using a hand-held phone while driving?","o":["$100","$25","$500","$1,000"],"h1":"A second offense costs $250, so the first is less than that.","h2":"In Michigan, the fine for a first hand-held phone offense is $100, and later offenses cost $250.","p":"Right. The first offense is $100."},"es":{"q":"En Michigan, ¿cuál es la multa por una primera falta por usar un teléfono en la mano mientras maneja?","o":["$100","$25","$500","$1,000"],"h1":"Una segunda falta cuesta $250, así que la primera es menos.","h2":"En Michigan, la multa por una primera falta por usar el teléfono en la mano es de $100, y las siguientes cuestan $250.","p":"Correcto. La primera falta cuesta $100."},"ref":{"doc":"MI","page":23}},{"id":"mi-041","scope":"MI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Michigan, which passengers must wear a seat belt in every seat, including the back seat?","o":["Only passengers under 8","Only passengers over 65","All passengers under 16","Only the driver's own children"],"h1":"Adults must buckle up in the front; younger riders must buckle up everywhere.","h2":"In Michigan, all passengers under age 16 must be buckled up in every seating position.","p":"Right. Everyone under 16 buckles up in any seat."},"es":{"q":"En Michigan, ¿qué pasajeros deben usar el cinturón de seguridad en cualquier asiento, incluso atrás?","o":["Solo los menores de 8 años","Solo los mayores de 65 años","Todos los menores de 16 años","Solo los hijos del conductor"],"h1":"Los adultos deben abrocharse adelante; los más jóvenes, en todos los asientos.","h2":"En Michigan, todos los pasajeros menores de 16 años deben llevar el cinturón abrochado en cualquier asiento.","p":"Correcto. Todo menor de 16 se abrocha en cualquier asiento."},"ref":{"doc":"MI","page":25}},{"id":"mi-042","scope":"MI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Michigan, until when must a child ride in a car seat or booster seat?","o":["Until age 4 or 40 pounds","Until age 8 or 4 feet 9 inches tall","Until age 12 or 5 feet tall","Until the child can sit up alone"],"h1":"There is an age limit and a height limit; whichever comes first ends it.","h2":"In Michigan, a child must ride in a car seat or booster seat until age 8 or until 4 feet 9 inches tall, whichever comes first.","p":"Right. Age 8 or 4 feet 9 inches, whichever comes first."},"es":{"q":"En Michigan, ¿hasta cuándo debe ir un niño en un asiento de seguridad o asiento elevado (booster)?","o":["Hasta los 4 años o 40 libras","Hasta los 8 años o 4 pies 9 pulgadas de estatura","Hasta los 12 años o 5 pies de estatura","Hasta que pueda sentarse solo"],"h1":"Hay un límite de edad y uno de estatura; lo que llegue primero.","h2":"En Michigan, un niño debe ir en un asiento de seguridad o elevado hasta los 8 años o hasta medir 4 pies 9 pulgadas, lo que ocurra primero.","p":"Correcto. Hasta los 8 años o 4 pies 9 pulgadas, lo que llegue primero."},"ref":{"doc":"MI","page":25}},{"id":"mi-043","scope":"MI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Michigan, when may a person under 18 not ride in the open bed of a pickup truck?","o":["Only on freeways","Only at night","Only when the truck is parked","When the truck goes faster than 15 mph"],"h1":"The rule is about the truck's speed.","h2":"In Michigan, a person under 18 may not ride in the open bed of a pickup truck going more than 15 mph, with a few work and parade exceptions.","p":"Right. Above 15 mph, no riders under 18 in the open bed."},"es":{"q":"En Michigan, ¿cuándo no puede una persona menor de 18 años ir en la caja abierta de una camioneta pickup?","o":["Solo en autopistas","Solo de noche","Solo cuando la camioneta está estacionada","Cuando la camioneta va a más de 15 mph"],"h1":"La regla tiene que ver con la velocidad de la camioneta.","h2":"En Michigan, una persona menor de 18 años no puede ir en la caja abierta de una pickup que va a más de 15 mph, salvo algunas excepciones de trabajo y desfiles.","p":"Correcto. A más de 15 mph, ningún menor de 18 en la caja abierta."},"ref":{"doc":"MI","page":25}},{"id":"mi-044","scope":"MI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Michigan, how far behind a moving emergency vehicle with lights and siren on must you stay?","o":["At least 100 feet","At least 500 feet","At least 50 feet","At least one mile"],"h1":"It is more than the length of a football field.","h2":"In Michigan, you must stay at least 500 feet behind a moving emergency vehicle that has its warning lights and siren on.","p":"Right. Stay at least 500 feet back."},"es":{"q":"En Michigan, ¿a qué distancia debe mantenerse detrás de un vehículo de emergencia en movimiento con luces y sirena encendidas?","o":["Por lo menos 100 pies","Por lo menos 500 pies","Por lo menos 50 pies","Por lo menos una milla"],"h1":"Es más que el largo de una cancha de fútbol americano.","h2":"En Michigan, debe mantenerse por lo menos a 500 pies detrás de un vehículo de emergencia en movimiento con luces de advertencia y sirena encendidas.","p":"Correcto. Manténgase por lo menos a 500 pies."},"ref":{"doc":"MI","page":28}},{"id":"mi-045","scope":"MI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Michigan, when passing on a two-lane road, you must be back in your lane before you come within what distance of an oncoming vehicle?","o":["50 feet","100 feet","200 feet","1,000 feet"],"h1":"It is a few hundred feet, not just a car length.","h2":"In Michigan, you must return to your own lane before you get within 200 feet of any oncoming vehicle.","p":"Right. Be back in your lane before 200 feet."},"es":{"q":"En Michigan, al rebasar en un camino de dos carriles, ¿antes de qué distancia de un vehículo que viene de frente debe volver a su carril?","o":["50 pies","100 pies","200 pies","1,000 pies"],"h1":"Son unos cientos de pies, no solo el largo de un auto.","h2":"En Michigan, debe volver a su carril antes de quedar a 200 pies de cualquier vehículo que viene de frente.","p":"Correcto. Vuelva a su carril antes de los 200 pies."},"ref":{"doc":"MI","page":32}},{"id":"mi-046","scope":"MI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Michigan, you may not pass another vehicle when you are within what distance of an intersection or railroad crossing?","o":["100 feet","25 feet","500 feet","One mile"],"h1":"It is the same distance as for a bridge or tunnel when your view is blocked.","h2":"In Michigan, you may not pass within 100 feet of an intersection or a railroad crossing.","p":"Right. No passing within 100 feet of an intersection or railroad crossing."},"es":{"q":"En Michigan, ¿a qué distancia de un cruce de calles o de un cruce de ferrocarril no puede rebasar a otro vehículo?","o":["100 pies","25 pies","500 pies","Una milla"],"h1":"Es la misma distancia que para un puente o túnel cuando no puede ver bien.","h2":"En Michigan, no puede rebasar a menos de 100 pies de un cruce de calles o de un cruce de ferrocarril.","p":"Correcto. No se rebasa a menos de 100 pies de un cruce o de las vías."},"ref":{"doc":"MI","page":32}},{"id":"mi-047","scope":"MI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Michigan, a train is coming to a railroad crossing. Where must you stop?","o":["Right on the first rail","At least 100 feet from the tracks","Anywhere, as long as you can see the train","No more than 50 feet and no less than 15 feet from the tracks"],"h1":"Trains stick out past the rails, so you cannot stop too close.","h2":"In Michigan, when a train is coming you must stop no more than 50 feet and no less than 15 feet from the tracks.","p":"Right. Stop between 15 and 50 feet from the tracks."},"es":{"q":"En Michigan, viene un tren a un cruce de ferrocarril. ¿Dónde debe detenerse?","o":["Justo sobre el primer riel","Por lo menos a 100 pies de las vías","Donde sea, si puede ver el tren","A no más de 50 pies y no menos de 15 pies de las vías"],"h1":"Los trenes sobresalen de los rieles, así que no puede detenerse muy cerca.","h2":"En Michigan, cuando viene un tren debe detenerse a no más de 50 pies y no menos de 15 pies de las vías.","p":"Correcto. Deténgase entre 15 y 50 pies de las vías."},"ref":{"doc":"MI","page":35}},{"id":"mi-048","scope":"MI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Michigan, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 15 feet","No closer than 50 feet","Right next to it if you stay in the car"],"h1":"Think of about three car widths, so fire trucks can reach it.","h2":"In Michigan, you may not park within 15 feet of a fire hydrant.","p":"Right. Keep at least 15 feet from a hydrant."},"es":{"q":"En Michigan, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No a menos de 5 pies","No a menos de 15 pies","No a menos de 50 pies","Justo al lado si se queda en el auto"],"h1":"Piense en unos tres anchos de auto, para que los bomberos lleguen.","h2":"En Michigan, no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Deje por lo menos 15 pies desde un hidrante."},"ref":{"doc":"MI","page":38}},{"id":"mi-049","scope":"MI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Michigan, within what distance of an oncoming vehicle is it illegal to use or flash your high beams?","o":["500 feet","100 feet","50 feet","2,000 feet"],"h1":"It is the same distance used for the headlight visibility rule.","h2":"In Michigan, it is illegal to use or even flash your high beams within 500 feet of an oncoming vehicle.","p":"Right. Dim your lights within 500 feet of oncoming traffic."},"es":{"q":"En Michigan, ¿a qué distancia de un vehículo que viene de frente es ilegal usar las luces altas o hacer destellos con ellas?","o":["500 pies","100 pies","50 pies","2,000 pies"],"h1":"Es la misma distancia que se usa en la regla de visibilidad de los faros.","h2":"En Michigan, es ilegal usar o incluso hacer destellos con las luces altas a menos de 500 pies de un vehículo que viene de frente.","p":"Correcto. Baje las luces a 500 pies del tráfico que viene de frente."},"ref":{"doc":"MI","page":64}},{"id":"mi-050","scope":"MI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Michigan, after a crash, when must you notify the police?","o":["Only if a car must be towed","Only if someone dies","Only if the other driver asks","If anyone is hurt or property damage is over $1,000"],"h1":"There is a dollar amount, and injuries always count.","h2":"In Michigan, you must notify the police after a crash if anyone is injured or property damage is more than $1,000.","p":"Right. Injuries or more than $1,000 in damage mean you call the police."},"es":{"q":"En Michigan, después de un choque, ¿cuándo debe avisar a la policía?","o":["Solo si hay que remolcar un auto","Solo si alguien muere","Solo si el otro conductor lo pide","Si alguien está herido o los daños pasan de $1,000"],"h1":"Hay una cantidad de dinero, y las lesiones siempre cuentan.","h2":"En Michigan, debe avisar a la policía después de un choque si alguien está herido o si los daños a la propiedad pasan de $1,000.","p":"Correcto. Con heridos o más de $1,000 en daños, llame a la policía."},"ref":{"doc":"MI","page":65}},{"id":"mi-051","scope":"MI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Michigan, at an intersection with a \"Michigan Left,\" how do you turn left?","o":["Turn left directly from the left lane","Turn left from the right lane after the light","Go straight or turn right, then make a U-turn at a median crossover","Back up and turn when traffic clears"],"h1":"A direct left turn is not allowed at these intersections.","h2":"In Michigan, at a Michigan Left you drive straight through or turn right, then use a median crossover to make a U-turn.","p":"Right. A Michigan Left uses a median crossover instead of a direct left turn."},"es":{"q":"En Michigan, en un cruce con \"Michigan Left\", ¿cómo se da vuelta a la izquierda?","o":["Se da vuelta a la izquierda directamente desde el carril izquierdo","Se da vuelta a la izquierda desde el carril derecho después del semáforo","Se sigue derecho o se da vuelta a la derecha, y luego se hace una vuelta en U en un cruce del camellón","Se da reversa y se da vuelta cuando no hay tráfico"],"h1":"En estos cruces no se permite dar vuelta a la izquierda directamente.","h2":"En Michigan, en un Michigan Left usted sigue derecho o da vuelta a la derecha, y luego usa un cruce del camellón para dar una vuelta en U.","p":"Correcto. Un Michigan Left usa un cruce del camellón en vez de una vuelta directa a la izquierda."},"ref":{"doc":"MI","page":48}},{"id":"mn-001","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before the provisional license.","h2":"You can get a Minnesota instruction permit at 15 after starting driver education, so you can practice before the provisional license at 16.","p":"Right. The Minnesota permit starts at 15."},"es":{"q":"En Minnesota, ¿cuál es la edad mínima para obtener un permiso de aprendizaje?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la licencia provisional.","h2":"Usted puede obtener el permiso de aprendizaje en Minnesota a los 15 años después de empezar la educación vial, para practicar antes de la licencia provisional a los 16.","p":"Correcto. El permiso en Minnesota empieza a los 15."},"zh":{"q":"在 Minnesota，最小几岁可以拿到学习驾照（instruction permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比临时驾照早一年。","h2":"你在 15 岁开始上驾驶教育课以后，就可以拿到 Minnesota 的学习驾照，这样你在 16 岁拿临时驾照前可以先练习。","p":"对。Minnesota 的学习驾照从 15 岁开始。"},"vi":{"q":"Ở Minnesota, tuổi nhỏ nhất để lấy giấy phép tập lái (instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là một năm trước khi lấy bằng lái tạm thời.","h2":"Bạn có thể lấy giấy phép tập lái ở Minnesota khi 15 tuổi, sau khi bắt đầu học lái xe, để tập lái trước khi lấy bằng lái tạm thời lúc 16 tuổi.","p":"Đúng. Giấy phép tập lái ở Minnesota bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Minnesota, ano ang pinakabatang edad para makakuha ng instruction permit (permit sa pag-aaral magmaneho)?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ang provisional license.","h2":"Puwede kang kumuha ng instruction permit sa Minnesota sa edad na 15 pagkatapos magsimula ng driver education, para makapagsanay ka bago ang provisional license sa edad na 16.","p":"Tama. Ang permit sa Minnesota ay nagsisimula sa 15."},"ar":{"q":"في Minnesota، ما أصغر عمر للحصول على تصريح التعلّم (instruction permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"إنه قبل الرخصة المؤقتة بسنة واحدة.","h2":"يمكنك الحصول على تصريح التعلّم في Minnesota في سن 15 بعد بدء دروس تعليم القيادة، حتى تتدرّب قبل الرخصة المؤقتة في سن 16.","p":"صحيح. يبدأ تصريح التعلّم في Minnesota في سن 15."},"ref":{"doc":"MN","page":13}},{"id":"mn-002","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, how old must the licensed driver be who supervises a permit holder under 18?","o":["At least 16","At least 18","At least 21","At least 25"],"h1":"The helper must be an adult who can legally drink.","h2":"A Minnesota permit holder under 18 must drive with a licensed driver who is at least 21, so an experienced adult is guiding them.","p":"Right. The supervisor must be 21 or older."},"es":{"q":"En Minnesota, ¿qué edad debe tener el conductor con licencia que supervisa a alguien con permiso menor de 18?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 21","Por lo menos 25"],"h1":"El acompañante debe ser un adulto que ya puede tomar alcohol legalmente.","h2":"Quien tiene permiso en Minnesota y es menor de 18 debe manejar con un conductor con licencia de por lo menos 21 años, para que lo guíe un adulto con experiencia.","p":"Correcto. El supervisor debe tener 21 años o más."},"zh":{"q":"在 Minnesota，陪同 18 岁以下持学习驾照的人开车的有驾照司机必须几岁？","o":["至少 16 岁","至少 18 岁","至少 21 岁","至少 25 岁"],"h1":"陪同的人必须是在法律上可以喝酒的成年人。","h2":"在 Minnesota，18 岁以下持学习驾照的人必须和至少 21 岁、有驾照的司机一起开车，这样有一位有经验的成年人指导他们。","p":"对。陪同的人必须 21 岁或以上。"},"vi":{"q":"Ở Minnesota, người lái xe có bằng đi kèm người giữ giấy phép tập lái dưới 18 tuổi phải bao nhiêu tuổi?","o":["Ít nhất 16","Ít nhất 18","Ít nhất 21","Ít nhất 25"],"h1":"Người đi kèm phải là người lớn được phép uống rượu theo luật.","h2":"Người giữ giấy phép tập lái ở Minnesota dưới 18 tuổi phải lái cùng một người có bằng lái từ 21 tuổi trở lên, để có người lớn có kinh nghiệm hướng dẫn.","p":"Đúng. Người giám sát phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Minnesota, ilang taon dapat ang lisensyadong driver na nagbabantay sa may permit na wala pang 18?","o":["Hindi bababa sa 16","Hindi bababa sa 18","Hindi bababa sa 21","Hindi bababa sa 25"],"h1":"Ang katulong ay dapat adult na legal nang uminom ng alak.","h2":"Ang may permit sa Minnesota na wala pang 18 ay dapat magmaneho kasama ang lisensyadong driver na hindi bababa sa 21 taong gulang, para may bihasang adult na gumagabay sa kanya.","p":"Tama. Ang nagbabantay ay dapat 21 o mas matanda."},"ar":{"q":"في Minnesota، كم يجب أن يكون عمر السائق المرخَّص الذي يرافق حامل تصريح التعلّم الذي عمره أقل من 18 سنة؟","o":["16 سنة على الأقل","18 سنة على الأقل","21 سنة على الأقل","25 سنة على الأقل"],"h1":"يجب أن يكون المرافق بالغًا يسمح له القانون بشرب الكحول.","h2":"يجب على حامل تصريح التعلّم في Minnesota الذي عمره أقل من 18 سنة أن يقود مع سائق مرخَّص عمره 21 سنة على الأقل، حتى يرشده شخص بالغ ذو خبرة.","p":"صحيح. يجب أن يكون المرافق عمره 21 سنة أو أكثر."},"ref":{"doc":"MN","page":13}},{"id":"mn-003","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, where must the supervising driver sit when a permit holder is driving?","o":["In the front passenger seat","In the back seat","Anywhere in the vehicle","Behind the driver"],"h1":"They must be close enough to help at once.","h2":"The supervising driver must sit in the front passenger seat when a Minnesota permit holder drives, so they can see the road and help quickly.","p":"Right. The supervisor sits in the front passenger seat."},"es":{"q":"En Minnesota, ¿dónde debe sentarse el conductor supervisor cuando maneja alguien con permiso?","o":["En el asiento del pasajero delantero","En el asiento de atrás","En cualquier lugar del vehículo","Detrás del conductor"],"h1":"Debe estar lo bastante cerca para ayudar enseguida.","h2":"El conductor supervisor debe sentarse en el asiento del pasajero delantero cuando maneja alguien con permiso en Minnesota, para ver la vía y ayudar rápido.","p":"Correcto. El supervisor va en el asiento delantero."},"zh":{"q":"在 Minnesota，持学习驾照的人开车时，陪同的司机必须坐在哪里？","o":["前排乘客座位","后排座位","车里任何地方","司机后面"],"h1":"他们必须离得够近，能马上帮忙。","h2":"Minnesota 持学习驾照的人开车时，陪同的司机必须坐在前排乘客座位，这样他们能看到道路并很快帮忙。","p":"对。陪同的人坐在前排乘客座位。"},"vi":{"q":"Ở Minnesota, người lái xe giám sát phải ngồi ở đâu khi người giữ giấy phép tập lái đang lái?","o":["Ở ghế hành khách phía trước","Ở ghế sau","Ở bất cứ chỗ nào trong xe","Phía sau người lái"],"h1":"Họ phải ngồi đủ gần để giúp ngay.","h2":"Người lái xe giám sát phải ngồi ở ghế hành khách phía trước khi người giữ giấy phép tập lái ở Minnesota lái xe, để họ thấy đường và giúp nhanh.","p":"Đúng. Người giám sát ngồi ở ghế hành khách phía trước."},"tl":{"q":"Sa Minnesota, saan dapat umupo ang nagbabantay na driver kapag nagmamaneho ang may permit?","o":["Sa upuan ng pasahero sa harap","Sa likod na upuan","Kahit saan sa sasakyan","Sa likod ng driver"],"h1":"Dapat malapit sila para makatulong agad.","h2":"Ang nagbabantay na driver ay dapat umupo sa upuan ng pasahero sa harap kapag nagmamaneho ang may permit sa Minnesota, para makita nila ang daan at makatulong agad.","p":"Tama. Ang nagbabantay ay umuupo sa upuan ng pasahero sa harap."},"ar":{"q":"في Minnesota، أين يجب أن يجلس السائق المرافق عندما يقود حامل تصريح التعلّم؟","o":["في مقعد الراكب الأمامي","في المقعد الخلفي","في أي مكان في السيارة","خلف السائق"],"h1":"يجب أن يكون قريبًا بما يكفي ليساعد فورًا.","h2":"يجب أن يجلس السائق المرافق في مقعد الراكب الأمامي عندما يقود حامل تصريح التعلّم في Minnesota، حتى يرى الطريق ويساعد بسرعة.","p":"صحيح. يجلس المرافق في مقعد الراكب الأمامي."},"ref":{"doc":"MN","page":13}},{"id":"mn-004","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, how long must a teen hold an instruction permit before applying for a provisional license?","o":["1 month","3 months","1 year","6 months"],"h1":"It is half a year.","h2":"A Minnesota teen must hold the instruction permit for the six months right before applying, with no serious traffic convictions.","p":"Right. Hold the permit for six months."},"es":{"q":"En Minnesota, ¿cuánto tiempo debe tener un adolescente el permiso de aprendizaje antes de solicitar la licencia provisional?","o":["1 mes","3 meses","1 año","6 meses"],"h1":"Es medio año.","h2":"Un adolescente en Minnesota debe tener el permiso de aprendizaje durante los seis meses justo antes de solicitar, sin condenas graves de tránsito.","p":"Correcto. Debe tener el permiso seis meses."},"zh":{"q":"在 Minnesota，青少年必须持有学习驾照多久，才能申请临时驾照？","o":["1 个月","3 个月","1 年","6 个月"],"h1":"是半年。","h2":"Minnesota 的青少年在申请前的六个月里必须一直持有学习驾照，而且没有严重的交通违法定罪。","p":"对。持有学习驾照六个月。"},"vi":{"q":"Ở Minnesota, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi xin bằng lái tạm thời (provisional license)?","o":["1 tháng","3 tháng","1 năm","6 tháng"],"h1":"Đó là nửa năm.","h2":"Thiếu niên ở Minnesota phải giữ giấy phép tập lái trong sáu tháng ngay trước khi nộp đơn, và không bị kết tội vi phạm giao thông nghiêm trọng.","p":"Đúng. Giữ giấy phép tập lái sáu tháng."},"tl":{"q":"Sa Minnesota, gaano katagal dapat hawak ng teen ang instruction permit bago mag-apply para sa provisional license (pansamantalang lisensya)?","o":["1 buwan","3 buwan","1 taon","6 na buwan"],"h1":"Kalahating taon ito.","h2":"Ang teen sa Minnesota ay dapat may hawak ng instruction permit sa loob ng anim na buwan bago mismo mag-apply, nang walang mabigat na traffic conviction.","p":"Tama. Hawakan ang permit nang anim na buwan."},"ar":{"q":"في Minnesota، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل أن يتقدّم بطلب الرخصة المؤقتة (provisional license)؟","o":["شهر واحد","3 أشهر","سنة واحدة","6 أشهر"],"h1":"إنها نصف سنة.","h2":"يجب على المراهق في Minnesota أن يحمل تصريح التعلّم لمدة ستة أشهر قبل التقديم مباشرة، دون إدانات مرورية خطيرة.","p":"صحيح. احمل التصريح لمدة ستة أشهر."},"ref":{"doc":"MN","page":14}},{"id":"mn-005","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, which of these can stop a teen from getting a provisional license after six months on a permit?","o":["Getting a parking ticket","A moving violation conviction","Having a passenger in the car","Driving at night with a parent"],"h1":"The six months must be clean of driving offenses.","h2":"A Minnesota teen must have no convictions for moving violations or alcohol and drug offenses during the six months on the permit.","p":"Right. A moving violation conviction can delay the provisional license."},"es":{"q":"En Minnesota, ¿cuál de estas cosas puede impedir que un adolescente obtenga la licencia provisional después de seis meses con permiso?","o":["Recibir una multa de estacionamiento","Una condena por una infracción en movimiento","Llevar un pasajero en el carro","Manejar de noche con un padre"],"h1":"Los seis meses deben estar limpios de infracciones al manejar.","h2":"Un adolescente en Minnesota no debe tener condenas por infracciones de tránsito en movimiento ni por alcohol o drogas durante los seis meses con el permiso.","p":"Correcto. Una infracción en movimiento puede retrasar la licencia provisional."},"zh":{"q":"在 Minnesota，持学习驾照六个月以后，下面哪一项会让青少年拿不到临时驾照？","o":["收到一张停车罚单","一次行车违规定罪","车里有乘客","和父母一起在晚上开车"],"h1":"这六个月里不能有驾驶违法记录。","h2":"Minnesota 的青少年在持学习驾照的六个月里，不能有行车违规定罪，也不能有酒精或毒品违法定罪。","p":"对。行车违规定罪会推迟拿临时驾照。"},"vi":{"q":"Ở Minnesota, điều nào sau đây có thể làm thiếu niên không lấy được bằng lái tạm thời sau sáu tháng giữ giấy phép tập lái?","o":["Bị phạt vì đậu xe sai","Bị kết tội vi phạm khi đang lái (moving violation)","Có hành khách trong xe","Lái xe ban đêm với cha mẹ"],"h1":"Sáu tháng đó phải không có lỗi khi lái xe.","h2":"Thiếu niên ở Minnesota không được bị kết tội vi phạm khi đang lái, hoặc tội liên quan đến rượu và ma túy, trong sáu tháng giữ giấy phép tập lái.","p":"Đúng. Bị kết tội vi phạm khi đang lái có thể làm chậm việc lấy bằng lái tạm thời."},"tl":{"q":"Sa Minnesota, alin dito ang puwedeng pumigil sa teen na makakuha ng provisional license pagkatapos ng anim na buwan na may permit?","o":["Pagkakaroon ng parking ticket","Conviction sa moving violation (paglabag habang nagmamaneho)","Pagkakaroon ng pasahero sa kotse","Pagmamaneho sa gabi kasama ang magulang"],"h1":"Ang anim na buwan ay dapat malinis sa paglabag sa pagmamaneho.","h2":"Ang teen sa Minnesota ay dapat walang conviction sa moving violation o sa paglabag tungkol sa alak at droga sa loob ng anim na buwan na may permit.","p":"Tama. Ang conviction sa moving violation ay puwedeng magpaantala sa provisional license."},"ar":{"q":"في Minnesota، أيّ مما يلي قد يمنع المراهق من الحصول على الرخصة المؤقتة بعد ستة أشهر مع تصريح التعلّم؟","o":["الحصول على مخالفة وقوف","إدانة بمخالفة أثناء القيادة (moving violation)","وجود راكب في السيارة","القيادة ليلًا مع أحد الوالدين"],"h1":"يجب أن تكون الأشهر الستة خالية من مخالفات القيادة.","h2":"يجب ألا يكون لدى المراهق في Minnesota أي إدانة بمخالفات أثناء القيادة أو بمخالفات الكحول والمخدرات خلال الأشهر الستة مع تصريح التعلّم.","p":"صحيح. الإدانة بمخالفة أثناء القيادة قد تؤخّر الرخصة المؤقتة."},"ref":{"doc":"MN","page":14}},{"id":"mn-006","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, what is the youngest age to get a provisional license?","o":["16 years old","15 years old","17 years old","18 years old"],"h1":"It comes one year after the instruction permit.","h2":"A Minnesota teen can get a provisional license at 16 after holding an instruction permit for six months.","p":"Right. The provisional license starts at 16."},"es":{"q":"En Minnesota, ¿cuál es la edad mínima para obtener la licencia provisional?","o":["16 años","15 años","17 años","18 años"],"h1":"Viene un año después del permiso de aprendizaje.","h2":"Un adolescente en Minnesota puede obtener la licencia provisional a los 16 años después de tener el permiso de aprendizaje seis meses.","p":"Correcto. La licencia provisional empieza a los 16."},"zh":{"q":"在 Minnesota，最小几岁可以拿到临时驾照（provisional license）？","o":["16 岁","15 岁","17 岁","18 岁"],"h1":"它在学习驾照以后一年。","h2":"Minnesota 的青少年持有学习驾照六个月以后，16 岁就可以拿到临时驾照。","p":"对。临时驾照从 16 岁开始。"},"vi":{"q":"Ở Minnesota, tuổi nhỏ nhất để lấy bằng lái tạm thời (provisional license) là bao nhiêu?","o":["16 tuổi","15 tuổi","17 tuổi","18 tuổi"],"h1":"Đó là một năm sau khi lấy giấy phép tập lái.","h2":"Thiếu niên ở Minnesota có thể lấy bằng lái tạm thời khi 16 tuổi, sau khi giữ giấy phép tập lái sáu tháng.","p":"Đúng. Bằng lái tạm thời bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Minnesota, ano ang pinakabatang edad para makakuha ng provisional license?","o":["16 taong gulang","15 taong gulang","17 taong gulang","18 taong gulang"],"h1":"Isang taon ito pagkatapos ng instruction permit.","h2":"Ang teen sa Minnesota ay puwedeng makakuha ng provisional license sa edad na 16 pagkatapos hawakan ang instruction permit nang anim na buwan.","p":"Tama. Ang provisional license ay nagsisimula sa 16."},"ar":{"q":"في Minnesota، ما أصغر عمر للحصول على الرخصة المؤقتة (provisional license)؟","o":["16 سنة","15 سنة","17 سنة","18 سنة"],"h1":"إنه بعد تصريح التعلّم بسنة واحدة.","h2":"يمكن للمراهق في Minnesota الحصول على الرخصة المؤقتة في سن 16 بعد حمل تصريح التعلّم لمدة ستة أشهر.","p":"صحيح. تبدأ الرخصة المؤقتة في سن 16."},"ref":{"doc":"MN","page":14}},{"id":"mn-007","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, if the parent does not take the supplemental parent class, how many supervised hours must a teen log?","o":["30 hours","40 hours","60 hours","50 hours"],"h1":"The parent class lowers this number by ten.","h2":"Without the supplemental parent class, a Minnesota teen must log at least 50 hours of supervised driving, with at least 15 at night.","p":"Right. Without the parent class, the teen logs 50 hours."},"es":{"q":"En Minnesota, si el padre no toma la clase complementaria para padres, ¿cuántas horas supervisadas debe registrar el adolescente?","o":["30 horas","40 horas","60 horas","50 horas"],"h1":"La clase para padres baja este número en diez.","h2":"Sin la clase complementaria para padres, un adolescente en Minnesota debe registrar por lo menos 50 horas de manejo supervisado, con por lo menos 15 de noche.","p":"Correcto. Sin la clase para padres, el adolescente registra 50 horas."},"zh":{"q":"在 Minnesota，如果父母没有上家长补充课，青少年必须记录多少小时有人监督的驾驶？","o":["30 小时","40 小时","60 小时","50 小时"],"h1":"家长课会让这个数字减少十。","h2":"父母没有上家长补充课时，Minnesota 的青少年必须记录至少 50 小时有人监督的驾驶，其中至少 15 小时在晚上。","p":"对。父母没上课，青少年要记录 50 小时。"},"vi":{"q":"Ở Minnesota, nếu cha mẹ không học lớp bổ sung cho cha mẹ (supplemental parent class), thiếu niên phải ghi lại bao nhiêu giờ lái có giám sát?","o":["30 giờ","40 giờ","60 giờ","50 giờ"],"h1":"Lớp học cho cha mẹ làm con số này giảm đi mười.","h2":"Nếu cha mẹ không học lớp bổ sung, thiếu niên ở Minnesota phải ghi lại ít nhất 50 giờ lái có giám sát, trong đó ít nhất 15 giờ vào ban đêm.","p":"Đúng. Không có lớp học cho cha mẹ, thiếu niên ghi lại 50 giờ."},"tl":{"q":"Sa Minnesota, kung hindi kukunin ng magulang ang supplemental parent class (dagdag na klase para sa magulang), ilang oras ng binantayang pagmamaneho ang dapat itala ng teen?","o":["30 oras","40 oras","60 oras","50 oras"],"h1":"Binabawasan ng klase para sa magulang ang bilang na ito ng sampu.","h2":"Kung walang supplemental parent class, ang teen sa Minnesota ay dapat magtala ng hindi bababa sa 50 oras ng binantayang pagmamaneho, at hindi bababa sa 15 dito ay sa gabi.","p":"Tama. Kung walang klase para sa magulang, 50 oras ang itatala ng teen."},"ar":{"q":"في Minnesota، إذا لم يحضر أحد الوالدين الدرس الإضافي للوالدين (supplemental parent class)، كم ساعة من القيادة تحت الإشراف يجب أن يسجّل المراهق؟","o":["30 ساعة","40 ساعة","60 ساعة","50 ساعة"],"h1":"الدرس الخاص بالوالدين يُنقص هذا العدد بعشر.","h2":"دون الدرس الإضافي للوالدين، يجب على المراهق في Minnesota أن يسجّل 50 ساعة على الأقل من القيادة تحت الإشراف، منها 15 ساعة على الأقل في الليل.","p":"صحيح. دون درس الوالدين، يسجّل المراهق 50 ساعة."},"ref":{"doc":"MN","page":14}},{"id":"mn-008","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, if a parent completes the supplemental parent class, how many supervised hours must the teen log?","o":["30 hours","40 hours","50 hours","60 hours"],"h1":"It is ten fewer than without the class.","h2":"When a parent completes the supplemental parent class, a Minnesota teen must log at least 40 hours of supervised driving, with at least 15 at night.","p":"Right. With the parent class, the teen logs 40 hours."},"es":{"q":"En Minnesota, si un padre completa la clase complementaria para padres, ¿cuántas horas supervisadas debe registrar el adolescente?","o":["30 horas","40 horas","50 horas","60 horas"],"h1":"Son diez menos que sin la clase.","h2":"Cuando un padre completa la clase complementaria para padres, un adolescente en Minnesota debe registrar por lo menos 40 horas de manejo supervisado, con por lo menos 15 de noche.","p":"Correcto. Con la clase para padres, el adolescente registra 40 horas."},"zh":{"q":"在 Minnesota，如果父母上完了家长补充课，青少年必须记录多少小时有人监督的驾驶？","o":["30 小时","40 小时","50 小时","60 小时"],"h1":"比没有上课时少十小时。","h2":"父母上完家长补充课时，Minnesota 的青少年必须记录至少 40 小时有人监督的驾驶，其中至少 15 小时在晚上。","p":"对。父母上了课，青少年要记录 40 小时。"},"vi":{"q":"Ở Minnesota, nếu cha mẹ học xong lớp bổ sung cho cha mẹ (supplemental parent class), thiếu niên phải ghi lại bao nhiêu giờ lái có giám sát?","o":["30 giờ","40 giờ","50 giờ","60 giờ"],"h1":"Ít hơn mười giờ so với khi không học lớp này.","h2":"Khi cha mẹ học xong lớp bổ sung, thiếu niên ở Minnesota phải ghi lại ít nhất 40 giờ lái có giám sát, trong đó ít nhất 15 giờ vào ban đêm.","p":"Đúng. Có lớp học cho cha mẹ, thiếu niên ghi lại 40 giờ."},"tl":{"q":"Sa Minnesota, kung natapos ng magulang ang supplemental parent class (dagdag na klase para sa magulang), ilang oras ng binantayang pagmamaneho ang dapat itala ng teen?","o":["30 oras","40 oras","50 oras","60 oras"],"h1":"Sampung oras itong mas kaunti kaysa kung walang klase.","h2":"Kapag natapos ng magulang ang supplemental parent class, ang teen sa Minnesota ay dapat magtala ng hindi bababa sa 40 oras ng binantayang pagmamaneho, at hindi bababa sa 15 dito ay sa gabi.","p":"Tama. Kung may klase para sa magulang, 40 oras ang itatala ng teen."},"ar":{"q":"في Minnesota، إذا أكمل أحد الوالدين الدرس الإضافي للوالدين (supplemental parent class)، كم ساعة من القيادة تحت الإشراف يجب أن يسجّل المراهق؟","o":["30 ساعة","40 ساعة","50 ساعة","60 ساعة"],"h1":"إنها أقل بعشر ساعات مما يلزم دون الدرس.","h2":"عندما يكمل أحد الوالدين الدرس الإضافي، يجب على المراهق في Minnesota أن يسجّل 40 ساعة على الأقل من القيادة تحت الإشراف، منها 15 ساعة على الأقل في الليل.","p":"صحيح. مع درس الوالدين، يسجّل المراهق 40 ساعة."},"ref":{"doc":"MN","page":14}},{"id":"mn-009","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, how many of the supervised practice hours must be at night?","o":["5 hours","10 hours","15 hours","20 hours"],"h1":"The number is the same with or without the parent class.","h2":"A Minnesota teen must log at least 15 hours of supervised driving at night, whether or not a parent took the supplemental class.","p":"Right. At least 15 hours must be at night."},"es":{"q":"En Minnesota, ¿cuántas de las horas de práctica supervisada deben ser de noche?","o":["5 horas","10 horas","15 horas","20 horas"],"h1":"El número es el mismo con o sin la clase para padres.","h2":"Un adolescente en Minnesota debe registrar por lo menos 15 horas de manejo supervisado de noche, haya tomado o no un padre la clase complementaria.","p":"Correcto. Por lo menos 15 horas deben ser de noche."},"zh":{"q":"在 Minnesota，有人监督的练习时间中，有多少小时必须在晚上？","o":["5 小时","10 小时","15 小时","20 小时"],"h1":"不管父母有没有上家长课，这个数字都一样。","h2":"不管父母有没有上补充课，Minnesota 的青少年都必须记录至少 15 小时在晚上有人监督的驾驶。","p":"对。至少 15 小时必须在晚上。"},"vi":{"q":"Ở Minnesota, bao nhiêu giờ tập lái có giám sát phải là vào ban đêm?","o":["5 giờ","10 giờ","15 giờ","20 giờ"],"h1":"Con số này giống nhau dù có hay không có lớp học cho cha mẹ.","h2":"Thiếu niên ở Minnesota phải ghi lại ít nhất 15 giờ lái có giám sát vào ban đêm, dù cha mẹ có học lớp bổ sung hay không.","p":"Đúng. Ít nhất 15 giờ phải là vào ban đêm."},"tl":{"q":"Sa Minnesota, ilan sa mga oras ng binantayang pagsasanay ang dapat sa gabi?","o":["5 oras","10 oras","15 oras","20 oras"],"h1":"Pareho ang bilang, may klase man o wala para sa magulang.","h2":"Ang teen sa Minnesota ay dapat magtala ng hindi bababa sa 15 oras ng binantayang pagmamaneho sa gabi, kumuha man o hindi ng dagdag na klase ang magulang.","p":"Tama. Hindi bababa sa 15 oras ang dapat sa gabi."},"ar":{"q":"في Minnesota، كم ساعة من ساعات التدريب تحت الإشراف يجب أن تكون في الليل؟","o":["5 ساعات","10 ساعات","15 ساعة","20 ساعة"],"h1":"العدد نفسه مع درس الوالدين أو بدونه.","h2":"يجب على المراهق في Minnesota أن يسجّل 15 ساعة على الأقل من القيادة الليلية تحت الإشراف، سواء حضر أحد الوالدين الدرس الإضافي أم لا.","p":"صحيح. 15 ساعة على الأقل يجب أن تكون في الليل."},"ref":{"doc":"MN","page":14}},{"id":"mn-010","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, during the first six months of a provisional license, when may a teen NOT drive alone?","o":["Midnight to 5 a.m.","10 p.m. to 6 a.m.","9 p.m. to 5 a.m.","11 p.m. to 4 a.m."],"h1":"The limit begins when a new day starts.","h2":"For the first six months of a Minnesota provisional license, a teen may not drive from midnight to 5 a.m., unless a licensed driver 25 or older is along or the trip is for work or a school event.","p":"Right. No driving from midnight to 5 a.m. at first."},"es":{"q":"En Minnesota, durante los primeros seis meses de la licencia provisional, ¿en qué horario NO puede manejar solo el adolescente?","o":["De medianoche a 5 a.m.","De 10 p.m. a 6 a.m.","De 9 p.m. a 5 a.m.","De 11 p.m. a 4 a.m."],"h1":"El límite empieza cuando comienza un nuevo día.","h2":"Durante los primeros seis meses de la licencia provisional en Minnesota, el adolescente no puede manejar de medianoche a las 5 a.m., salvo que lo acompañe un conductor con licencia de 25 años o más o que el viaje sea por trabajo o por un evento escolar.","p":"Correcto. Al principio no se maneja de medianoche a 5 a.m."},"zh":{"q":"在 Minnesota，持临时驾照的前六个月，青少年在什么时间不能单独开车？","o":["午夜到早上 5 点","晚上 10 点到早上 6 点","晚上 9 点到早上 5 点","晚上 11 点到凌晨 4 点"],"h1":"限制从新的一天开始时开始。","h2":"持 Minnesota 临时驾照的前六个月，青少年在午夜到早上 5 点不能开车，除非有 25 岁或以上、有驾照的司机同车，或者是为了工作或学校活动。","p":"对。一开始，午夜到早上 5 点不能开车。"},"vi":{"q":"Ở Minnesota, trong sáu tháng đầu có bằng lái tạm thời, thiếu niên KHÔNG được lái một mình vào lúc nào?","o":["Từ nửa đêm đến 5 giờ sáng","Từ 10 giờ tối đến 6 giờ sáng","Từ 9 giờ tối đến 5 giờ sáng","Từ 11 giờ tối đến 4 giờ sáng"],"h1":"Giới hạn bắt đầu khi một ngày mới bắt đầu.","h2":"Trong sáu tháng đầu có bằng lái tạm thời ở Minnesota, thiếu niên không được lái xe từ nửa đêm đến 5 giờ sáng, trừ khi có người có bằng lái từ 25 tuổi trở lên đi cùng, hoặc chuyến đi là để đi làm hay đi sự kiện của trường.","p":"Đúng. Lúc đầu không được lái từ nửa đêm đến 5 giờ sáng."},"tl":{"q":"Sa Minnesota, sa unang anim na buwan ng provisional license, kailan HINDI puwedeng magmaneho nang mag-isa ang teen?","o":["Hatinggabi hanggang 5 a.m.","10 p.m. hanggang 6 a.m.","9 p.m. hanggang 5 a.m.","11 p.m. hanggang 4 a.m."],"h1":"Nagsisimula ang limitasyon kapag nagsimula ang bagong araw.","h2":"Sa unang anim na buwan ng provisional license sa Minnesota, hindi puwedeng magmaneho ang teen mula hatinggabi hanggang 5 a.m., maliban kung may kasamang lisensyadong driver na 25 o mas matanda, o ang biyahe ay para sa trabaho o sa event ng paaralan.","p":"Tama. Bawal magmaneho mula hatinggabi hanggang 5 a.m. sa simula."},"ar":{"q":"في Minnesota، خلال الأشهر الستة الأولى من الرخصة المؤقتة، متى لا يجوز للمراهق أن يقود وحده؟","o":["من منتصف الليل حتى 5 صباحًا","من 10 مساءً حتى 6 صباحًا","من 9 مساءً حتى 5 صباحًا","من 11 مساءً حتى 4 صباحًا"],"h1":"يبدأ المنع عندما يبدأ يوم جديد.","h2":"خلال الأشهر الستة الأولى من الرخصة المؤقتة في Minnesota، لا يجوز للمراهق أن يقود من منتصف الليل حتى 5 صباحًا، إلا إذا كان معه سائق مرخَّص عمره 25 سنة أو أكثر، أو كانت الرحلة للعمل أو لنشاط مدرسي.","p":"صحيح. لا قيادة من منتصف الليل حتى 5 صباحًا في البداية."},"ref":{"doc":"MN","page":14}},{"id":"mn-011","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, in the first six months of a provisional license, who can ride along so the teen may drive at 2 a.m.?","o":["Any friend who is 18","A brother who has a permit","A licensed driver age 25 or older","Any adult passenger"],"h1":"The person must be licensed and older than most college students.","h2":"A Minnesota provisional driver may drive between midnight and 5 a.m. in the first six months when a licensed driver who is at least 25 rides along.","p":"Right. A licensed driver 25 or older makes it legal."},"es":{"q":"En Minnesota, en los primeros seis meses de la licencia provisional, ¿quién puede acompañar al adolescente para que maneje a las 2 a.m.?","o":["Cualquier amigo de 18 años","Un hermano que tiene permiso","Un conductor con licencia de 25 años o más","Cualquier pasajero adulto"],"h1":"La persona debe tener licencia y ser mayor que la mayoría de los universitarios.","h2":"Un conductor provisional en Minnesota puede manejar entre medianoche y 5 a.m. en los primeros seis meses si lo acompaña un conductor con licencia de por lo menos 25 años.","p":"Correcto. Un conductor con licencia de 25 años o más lo hace legal."},"zh":{"q":"在 Minnesota，持临时驾照的前六个月，谁同车时青少年可以在凌晨 2 点开车？","o":["任何 18 岁的朋友","一个持学习驾照的哥哥或弟弟","25 岁或以上、有驾照的司机","任何成年乘客"],"h1":"这个人必须有驾照，而且比大多数大学生年纪大。","h2":"持 Minnesota 临时驾照的前六个月，有至少 25 岁、有驾照的司机同车时，可以在午夜到早上 5 点之间开车。","p":"对。有 25 岁或以上、有驾照的司机同车就合法。"},"vi":{"q":"Ở Minnesota, trong sáu tháng đầu có bằng lái tạm thời, ai có thể đi cùng để thiếu niên được lái xe lúc 2 giờ sáng?","o":["Bất kỳ người bạn nào 18 tuổi","Anh trai có giấy phép tập lái","Người có bằng lái từ 25 tuổi trở lên","Bất kỳ hành khách người lớn nào"],"h1":"Người đó phải có bằng lái và lớn tuổi hơn hầu hết sinh viên đại học.","h2":"Người có bằng lái tạm thời ở Minnesota được lái xe từ nửa đêm đến 5 giờ sáng trong sáu tháng đầu khi có một người có bằng lái từ 25 tuổi trở lên đi cùng.","p":"Đúng. Người có bằng lái từ 25 tuổi trở lên làm cho việc này hợp pháp."},"tl":{"q":"Sa Minnesota, sa unang anim na buwan ng provisional license, sino ang puwedeng sumama para makapagmaneho ang teen nang 2 a.m.?","o":["Kahit sinong kaibigan na 18","Kapatid na lalaki na may permit","Lisensyadong driver na 25 o mas matanda","Kahit sinong adult na pasahero"],"h1":"Ang tao ay dapat may lisensya at mas matanda kaysa sa karamihan ng estudyante sa kolehiyo.","h2":"Ang may provisional license sa Minnesota ay puwedeng magmaneho mula hatinggabi hanggang 5 a.m. sa unang anim na buwan kapag may kasamang lisensyadong driver na hindi bababa sa 25 taong gulang.","p":"Tama. Ang lisensyadong driver na 25 o mas matanda ang nagpapalegal dito."},"ar":{"q":"في Minnesota، خلال الأشهر الستة الأولى من الرخصة المؤقتة، من يمكنه أن يرافق المراهق حتى يقود في الساعة 2 صباحًا؟","o":["أي صديق عمره 18 سنة","أخ لديه تصريح تعلّم","سائق مرخَّص عمره 25 سنة أو أكثر","أي راكب بالغ"],"h1":"يجب أن يكون الشخص مرخَّصًا وأكبر من معظم طلاب الجامعة.","h2":"يجوز لحامل الرخصة المؤقتة في Minnesota أن يقود بين منتصف الليل و5 صباحًا في الأشهر الستة الأولى عندما يرافقه سائق مرخَّص عمره 25 سنة على الأقل.","p":"صحيح. وجود سائق مرخَّص عمره 25 سنة أو أكثر يجعل ذلك قانونيًا."},"ref":{"doc":"MN","page":14}},{"id":"mn-012","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, in the first six months of a provisional license, how many passengers under 20 who are not family may the teen carry?","o":["None","One","Two","Three"],"h1":"It is the smallest number above zero.","h2":"For the first six months, a Minnesota provisional driver may carry only one passenger under 20 who is not immediate family, because young passengers distract new drivers.","p":"Right. Only one young passenger who is not family at first."},"es":{"q":"En Minnesota, en los primeros seis meses de la licencia provisional, ¿cuántos pasajeros menores de 20 que no son familia puede llevar el adolescente?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Es el número más pequeño mayor que cero.","h2":"Durante los primeros seis meses, un conductor provisional en Minnesota puede llevar solo un pasajero menor de 20 que no sea familia directa, porque los pasajeros jóvenes distraen a los conductores nuevos.","p":"Correcto. Al principio solo un pasajero joven que no sea familia."},"zh":{"q":"在 Minnesota，持临时驾照的前六个月，青少年可以载多少位不是家人、20 岁以下的乘客？","o":["一个都不行","一位","两位","三位"],"h1":"这是大于零的最小数字。","h2":"在前六个月，Minnesota 持临时驾照的司机只能载一位不是直系家人、20 岁以下的乘客，因为年轻乘客会让新司机分心。","p":"对。一开始只能载一位不是家人的年轻乘客。"},"vi":{"q":"Ở Minnesota, trong sáu tháng đầu có bằng lái tạm thời, thiếu niên được chở bao nhiêu hành khách dưới 20 tuổi không phải người trong gia đình?","o":["Không ai","Một","Hai","Ba"],"h1":"Đó là số nhỏ nhất lớn hơn không.","h2":"Trong sáu tháng đầu, người có bằng lái tạm thời ở Minnesota chỉ được chở một hành khách dưới 20 tuổi không phải người trong gia đình gần, vì hành khách trẻ làm người mới lái bị phân tâm.","p":"Đúng. Lúc đầu chỉ được chở một hành khách trẻ không phải người nhà."},"tl":{"q":"Sa Minnesota, sa unang anim na buwan ng provisional license, ilang pasaherong wala pang 20 na hindi kapamilya ang puwedeng isakay ng teen?","o":["Wala","Isa","Dalawa","Tatlo"],"h1":"Ito ang pinakamaliit na bilang na higit sa zero.","h2":"Sa unang anim na buwan, ang may provisional license sa Minnesota ay puwedeng magsakay ng isang pasahero lang na wala pang 20 na hindi malapit na kapamilya, dahil nakakaabala ang mga batang pasahero sa bagong driver.","p":"Tama. Isang batang pasahero lang na hindi kapamilya sa simula."},"ar":{"q":"في Minnesota، خلال الأشهر الستة الأولى من الرخصة المؤقتة، كم راكبًا عمره أقل من 20 سنة وليس من العائلة يجوز للمراهق أن ينقل؟","o":["لا أحد","واحد","اثنان","ثلاثة"],"h1":"إنه أصغر عدد أكبر من صفر.","h2":"خلال الأشهر الستة الأولى، يجوز لحامل الرخصة المؤقتة في Minnesota أن ينقل راكبًا واحدًا فقط عمره أقل من 20 سنة وليس من العائلة المباشرة، لأن الركاب الصغار يشتّتون انتباه السائقين الجدد.","p":"صحيح. راكب صغير واحد فقط ليس من العائلة في البداية."},"ref":{"doc":"MN","page":15}},{"id":"mn-013","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, in months 7 to 12 of a provisional license, how many passengers under 20 who are not family may the teen carry?","o":["One","Two","Four","Three"],"h1":"The limit grows after the first six months.","h2":"In months 7 to 12, a Minnesota provisional driver may carry up to three passengers under 20 who are not immediate family; after 12 months the limit ends.","p":"Right. Up to three young passengers in months 7 to 12."},"es":{"q":"En Minnesota, en los meses 7 a 12 de la licencia provisional, ¿cuántos pasajeros menores de 20 que no son familia puede llevar el adolescente?","o":["Uno","Dos","Cuatro","Tres"],"h1":"El límite crece después de los primeros seis meses.","h2":"En los meses 7 a 12, un conductor provisional en Minnesota puede llevar hasta tres pasajeros menores de 20 que no sean familia directa; después de 12 meses el límite termina.","p":"Correcto. Hasta tres pasajeros jóvenes en los meses 7 a 12."},"zh":{"q":"在 Minnesota，持临时驾照的第 7 到第 12 个月，青少年可以载多少位不是家人、20 岁以下的乘客？","o":["一位","两位","四位","三位"],"h1":"前六个月以后，限制放宽了。","h2":"在第 7 到第 12 个月，Minnesota 持临时驾照的司机最多可以载三位不是直系家人、20 岁以下的乘客；12 个月以后，这个限制就结束了。","p":"对。第 7 到第 12 个月，最多三位年轻乘客。"},"vi":{"q":"Ở Minnesota, từ tháng thứ 7 đến tháng thứ 12 có bằng lái tạm thời, thiếu niên được chở bao nhiêu hành khách dưới 20 tuổi không phải người trong gia đình?","o":["Một","Hai","Bốn","Ba"],"h1":"Giới hạn tăng lên sau sáu tháng đầu.","h2":"Từ tháng thứ 7 đến tháng thứ 12, người có bằng lái tạm thời ở Minnesota được chở tối đa ba hành khách dưới 20 tuổi không phải người trong gia đình gần; sau 12 tháng thì không còn giới hạn này.","p":"Đúng. Tối đa ba hành khách trẻ từ tháng thứ 7 đến tháng thứ 12."},"tl":{"q":"Sa Minnesota, sa ika-7 hanggang ika-12 buwan ng provisional license, ilang pasaherong wala pang 20 na hindi kapamilya ang puwedeng isakay ng teen?","o":["Isa","Dalawa","Apat","Tatlo"],"h1":"Lumalaki ang limitasyon pagkatapos ng unang anim na buwan.","h2":"Sa ika-7 hanggang ika-12 buwan, ang may provisional license sa Minnesota ay puwedeng magsakay ng hanggang tatlong pasaherong wala pang 20 na hindi malapit na kapamilya; pagkatapos ng 12 buwan, wala na ang limitasyon.","p":"Tama. Hanggang tatlong batang pasahero sa ika-7 hanggang ika-12 buwan."},"ar":{"q":"في Minnesota، في الأشهر من 7 إلى 12 من الرخصة المؤقتة، كم راكبًا عمره أقل من 20 سنة وليس من العائلة يجوز للمراهق أن ينقل؟","o":["واحد","اثنان","أربعة","ثلاثة"],"h1":"يزيد الحد بعد الأشهر الستة الأولى.","h2":"في الأشهر من 7 إلى 12، يجوز لحامل الرخصة المؤقتة في Minnesota أن ينقل حتى ثلاثة ركاب أعمارهم أقل من 20 سنة وليسوا من العائلة المباشرة؛ وبعد 12 شهرًا ينتهي هذا الحد.","p":"صحيح. حتى ثلاثة ركاب صغار في الأشهر من 7 إلى 12."},"ref":{"doc":"MN","page":15}},{"id":"mn-014","scope":"MN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Minnesota, may a 16-year-old with a provisional license use a hands-free phone while driving?","o":["Yes, hands-free is always allowed","Yes, but only on freeways","No, not even hands-free","Yes, for calls under one minute"],"h1":"Teen drivers have a stricter rule than adults.","h2":"A Minnesota driver under 18 with a permit or provisional license may not use a phone while the car is moving, hand-held or hands-free.","p":"Right. Under 18, no phone at all while moving."},"es":{"q":"En Minnesota, ¿puede un joven de 16 años con licencia provisional usar el teléfono con manos libres mientras maneja?","o":["Sí, manos libres siempre está permitido","Sí, pero solo en autopistas","No, ni siquiera con manos libres","Sí, para llamadas de menos de un minuto"],"h1":"Los conductores adolescentes tienen una regla más estricta que los adultos.","h2":"Un conductor menor de 18 en Minnesota con permiso o licencia provisional no puede usar el teléfono mientras el carro se mueve, ni en la mano ni con manos libres.","p":"Correcto. Menor de 18, nada de teléfono en movimiento."},"zh":{"q":"在 Minnesota，持临时驾照的 16 岁司机开车时可以用免提手机吗？","o":["可以，免提一直都可以","可以，但只能在高速公路上","不可以，免提也不行","可以，打一分钟以内的电话"],"h1":"青少年司机的规定比成年人更严格。","h2":"在 Minnesota，持学习驾照或临时驾照、18 岁以下的司机，在车开动时不能用手机，手拿或免提都不行。","p":"对。18 岁以下，车在开时完全不能用手机。"},"vi":{"q":"Ở Minnesota, người 16 tuổi có bằng lái tạm thời có được dùng điện thoại rảnh tay (hands-free) khi lái xe không?","o":["Có, rảnh tay thì luôn được phép","Có, nhưng chỉ trên xa lộ","Không, kể cả rảnh tay cũng không","Có, cho cuộc gọi dưới một phút"],"h1":"Người lái xe tuổi thiếu niên có luật nghiêm hơn người lớn.","h2":"Người lái xe ở Minnesota dưới 18 tuổi có giấy phép tập lái hoặc bằng lái tạm thời không được dùng điện thoại khi xe đang chạy, dù cầm tay hay rảnh tay.","p":"Đúng. Dưới 18 tuổi, hoàn toàn không dùng điện thoại khi xe đang chạy."},"tl":{"q":"Sa Minnesota, puwede bang gumamit ng hands-free na telepono habang nagmamaneho ang 16 taong gulang na may provisional license?","o":["Oo, laging puwede ang hands-free","Oo, pero sa freeway lang","Hindi, kahit hands-free","Oo, para sa tawag na wala pang isang minuto"],"h1":"Mas mahigpit ang patakaran para sa teen na driver kaysa sa mga adult.","h2":"Ang driver sa Minnesota na wala pang 18 na may permit o provisional license ay hindi puwedeng gumamit ng telepono habang umaandar ang kotse, hawak man o hands-free.","p":"Tama. Kung wala pang 18, bawal ang telepono habang umaandar."},"ar":{"q":"في Minnesota، هل يجوز لشخص عمره 16 سنة ولديه رخصة مؤقتة أن يستخدم الهاتف بدون يدين (hands-free) أثناء القيادة؟","o":["نعم، الاستخدام بدون يدين مسموح دائمًا","نعم، ولكن على الطرق السريعة فقط","لا، ولا حتى بدون يدين","نعم، للمكالمات الأقل من دقيقة"],"h1":"للسائقين المراهقين قاعدة أشد من البالغين.","h2":"لا يجوز للسائق في Minnesota الذي عمره أقل من 18 سنة ولديه تصريح تعلّم أو رخصة مؤقتة أن يستخدم الهاتف أثناء سير السيارة، سواء باليد أو بدون يدين.","p":"صحيح. تحت 18 سنة، لا هاتف أبدًا أثناء سير السيارة."},"ref":{"doc":"MN","page":14}},{"id":"mn-015","scope":"MN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Minnesota, how may an adult driver use a cell phone to make a call while driving?","o":["By voice command or one touch, without holding it","Holding it at the ear","Holding it on the steering wheel","Holding it only at stop signs"],"h1":"Minnesota's law is called Hands-Free.","h2":"Minnesota adults may use a phone while driving only by voice command or hands-free mode, never holding it in their hand.","p":"Right. Voice or one touch, never holding the phone."},"es":{"q":"En Minnesota, ¿cómo puede un conductor adulto usar el celular para hacer una llamada mientras maneja?","o":["Con comando de voz o un solo toque, sin sostenerlo","Sosteniéndolo junto al oído","Sosteniéndolo sobre el volante","Sosteniéndolo solo en las señales de alto"],"h1":"La ley de Minnesota se llama Manos Libres.","h2":"En Minnesota, los adultos pueden usar el teléfono al manejar solo con comandos de voz o en modo manos libres, nunca sosteniéndolo en la mano.","p":"Correcto. Con voz o un toque, nunca sosteniendo el teléfono."},"zh":{"q":"在 Minnesota，成年司机开车时可以怎样用手机打电话？","o":["用语音命令或按一下，不拿着手机","拿到耳边","拿在方向盘上","只在停车标志前拿着"],"h1":"Minnesota 的这条法律叫做 Hands-Free（免提）。","h2":"Minnesota 的成年人开车时只能用语音命令或免提模式使用手机，绝不能拿在手里。","p":"对。用语音或按一下，绝不拿着手机。"},"vi":{"q":"Ở Minnesota, người lớn lái xe được dùng điện thoại di động để gọi như thế nào khi đang lái?","o":["Bằng giọng nói hoặc một lần chạm, không cầm điện thoại","Cầm điện thoại áp vào tai","Cầm điện thoại trên vô lăng","Chỉ cầm điện thoại khi dừng ở biển Stop"],"h1":"Luật của Minnesota có tên là Hands-Free (rảnh tay).","h2":"Người lớn ở Minnesota chỉ được dùng điện thoại khi lái xe bằng lệnh giọng nói hoặc chế độ rảnh tay, không bao giờ cầm điện thoại trong tay.","p":"Đúng. Dùng giọng nói hoặc một lần chạm, không bao giờ cầm điện thoại."},"tl":{"q":"Sa Minnesota, paano puwedeng gumamit ng cell phone ang adult na driver para tumawag habang nagmamaneho?","o":["Sa voice command o isang pindot, nang hindi ito hawak","Hawak ito sa tainga","Hawak ito sa manibela","Hawak ito sa stop sign lang"],"h1":"Ang batas ng Minnesota ay tinatawag na Hands-Free.","h2":"Ang mga adult sa Minnesota ay puwedeng gumamit ng telepono habang nagmamaneho sa voice command o hands-free mode lang, at hindi kailanman hawak sa kamay.","p":"Tama. Boses o isang pindot, hindi kailanman hawak ang telepono."},"ar":{"q":"في Minnesota، كيف يجوز للسائق البالغ أن يستخدم الهاتف المحمول لإجراء مكالمة أثناء القيادة؟","o":["بالأمر الصوتي أو بلمسة واحدة، دون أن يمسكه","بإمساكه عند الأذن","بإمساكه على عجلة القيادة","بإمساكه عند إشارات Stop فقط"],"h1":"قانون Minnesota اسمه Hands-Free (بدون يدين).","h2":"يجوز للبالغين في Minnesota استخدام الهاتف أثناء القيادة بالأمر الصوتي أو بوضع بدون يدين فقط، ولا يمسكونه في أيديهم أبدًا.","p":"صحيح. بالصوت أو بلمسة واحدة، ولا تمسك الهاتف أبدًا."},"ref":{"doc":"MN","page":null}},{"id":"mn-016","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, what score do you need to pass the knowledge test?","o":["60 percent","70 percent","75 percent","80 percent"],"h1":"You must answer four out of every five questions right.","h2":"Minnesota requires at least 80 percent correct to pass the driver knowledge test.","p":"Right. You need 80 percent to pass."},"es":{"q":"En Minnesota, ¿qué puntaje necesita para aprobar el examen de conocimientos?","o":["60 por ciento","70 por ciento","75 por ciento","80 por ciento"],"h1":"Debe contestar bien cuatro de cada cinco preguntas.","h2":"Minnesota exige por lo menos 80 por ciento de respuestas correctas para aprobar el examen de conocimientos.","p":"Correcto. Necesita 80 por ciento para aprobar."},"zh":{"q":"在 Minnesota，笔试要得多少分才能通过？","o":["60%","70%","75%","80%"],"h1":"每五道题你必须答对四道。","h2":"Minnesota 要求驾驶笔试至少答对 80% 才能通过。","p":"对。你需要 80% 才能通过。"},"vi":{"q":"Ở Minnesota, bạn cần bao nhiêu điểm để đậu bài thi kiến thức?","o":["60 phần trăm","70 phần trăm","75 phần trăm","80 phần trăm"],"h1":"Bạn phải trả lời đúng bốn trên mỗi năm câu hỏi.","h2":"Minnesota yêu cầu trả lời đúng ít nhất 80 phần trăm để đậu bài thi kiến thức lái xe.","p":"Đúng. Bạn cần 80 phần trăm để đậu."},"tl":{"q":"Sa Minnesota, anong iskor ang kailangan mo para pumasa sa knowledge test?","o":["60 porsiyento","70 porsiyento","75 porsiyento","80 porsiyento"],"h1":"Dapat tama ang sagot mo sa apat sa bawat limang tanong.","h2":"Kailangan sa Minnesota ang hindi bababa sa 80 porsiyentong tama para pumasa sa driver knowledge test.","p":"Tama. Kailangan mo ng 80 porsiyento para pumasa."},"ar":{"q":"في Minnesota، ما الدرجة التي تحتاجها للنجاح في اختبار المعرفة؟","o":["60 بالمئة","70 بالمئة","75 بالمئة","80 بالمئة"],"h1":"يجب أن تجيب صحيحًا عن أربعة من كل خمسة أسئلة.","h2":"تشترط Minnesota إجابات صحيحة بنسبة 80 بالمئة على الأقل للنجاح في اختبار المعرفة للسائقين.","p":"صحيح. تحتاج 80 بالمئة للنجاح."},"ref":{"doc":"MN","page":10}},{"id":"mn-017","scope":"MN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Minnesota, on a road with two lanes your way, you approach a stopped ambulance with flashing lights on the shoulder. What does the law require?","o":["Stay in your lane and keep your speed","Move one full lane away, if safe","Stop on the shoulder behind it","Speed up to pass it quickly"],"h1":"Leave an empty lane between you and the workers.","h2":"Minnesota's Ted Foss Move Over law requires you to move one full lane away from a stopped emergency vehicle with flashing lights; if that is not safe, slow down.","p":"Right. Move one full lane away."},"es":{"q":"En Minnesota, en una vía con dos carriles en su dirección, se acerca a una ambulancia detenida en el acotamiento con luces intermitentes. ¿Qué exige la ley?","o":["Seguir en su carril a la misma velocidad","Alejarse un carril completo, si es seguro","Parar en el acotamiento detrás de ella","Acelerar para pasarla rápido"],"h1":"Deje un carril vacío entre usted y los trabajadores.","h2":"La ley Ted Foss de Minnesota le exige alejarse un carril completo de un vehículo de emergencia detenido con luces intermitentes; si no es seguro, baje la velocidad.","p":"Correcto. Aléjese un carril completo."},"zh":{"q":"在 Minnesota，在你的方向有两条车道的路上，你接近一辆停在路肩上、闪着灯的救护车。法律要求你怎么做？","o":["留在你的车道，保持速度","如果安全，离开一整条车道","在它后面的路肩上停车","加速很快开过去"],"h1":"在你和工作人员之间留出一条空车道。","h2":"Minnesota 的 Ted Foss Move Over 法要求你离停着、闪着灯的急救车辆一整条车道；如果换道不安全，就要减速。","p":"对。离开一整条车道。"},"vi":{"q":"Ở Minnesota, trên đường có hai làn đi cùng chiều với bạn, bạn đến gần một xe cứu thương đang dừng bên lề đường với đèn nhấp nháy. Luật yêu cầu gì?","o":["Ở trong làn của bạn và giữ nguyên tốc độ","Chuyển sang cách xa một làn đầy đủ, nếu an toàn","Dừng trên lề đường phía sau xe đó","Tăng tốc để vượt qua nhanh"],"h1":"Để trống một làn giữa bạn và những người đang làm việc.","h2":"Luật Ted Foss Move Over (luật nhường làn) của Minnesota yêu cầu bạn chuyển sang cách xa một làn đầy đủ khỏi xe khẩn cấp đang dừng có đèn nhấp nháy; nếu việc đó không an toàn, hãy giảm tốc độ.","p":"Đúng. Chuyển sang cách xa một làn đầy đủ."},"tl":{"q":"Sa Minnesota, sa daan na may dalawang lane sa direksyon mo, papalapit ka sa nakahintong ambulansya na may kumikislap na ilaw sa gilid ng daan (shoulder). Ano ang hinihingi ng batas?","o":["Manatili sa lane mo at panatilihin ang bilis","Lumipat nang isang buong lane palayo, kung ligtas","Huminto sa shoulder sa likod nito","Bumilis para malampasan ito agad"],"h1":"Mag-iwan ng bakanteng lane sa pagitan mo at ng mga nagtatrabaho.","h2":"Ang Ted Foss Move Over law ng Minnesota ay nag-uutos na lumipat ka nang isang buong lane palayo sa nakahintong emergency vehicle na may kumikislap na ilaw; kung hindi ito ligtas, magdahan-dahan.","p":"Tama. Lumipat nang isang buong lane palayo."},"ar":{"q":"في Minnesota، على طريق فيه حارتان في اتجاهك، تقترب من سيارة إسعاف متوقفة على كتف الطريق وأضواؤها تومض. ماذا يشترط القانون؟","o":["ابقَ في حارتك وحافظ على سرعتك","ابتعد حارة كاملة واحدة، إذا كان ذلك آمنًا","توقف على كتف الطريق خلفها","زِد سرعتك لتتجاوزها بسرعة"],"h1":"اترك حارة فارغة بينك وبين العاملين.","h2":"قانون Ted Foss Move Over (قانون الابتعاد) في Minnesota يشترط أن تبتعد حارة كاملة واحدة عن مركبة الطوارئ المتوقفة وأضواؤها تومض؛ وإذا لم يكن ذلك آمنًا، فخفّف سرعتك.","p":"صحيح. ابتعد حارة كاملة واحدة."},"ref":{"doc":"MN","page":44}},{"id":"mn-018","scope":"MN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Minnesota, the move over law also protects which of these?","o":["A stalled car with its hazard lights on","A parked car in a driveway","A bus at a bus stop","A car waiting at a red light"],"h1":"Think of a driver stuck on the shoulder.","h2":"Minnesota's move over law also covers stalled or disabled vehicles with their warning lights on, so stranded drivers get the same protection.","p":"Right. Stalled cars with hazards on are covered too."},"es":{"q":"En Minnesota, ¿a cuál de estos también protege la ley de cambiarse de carril (Move Over)?","o":["Un carro descompuesto con las luces de emergencia encendidas","Un carro estacionado en una entrada de casa","Un autobús en una parada","Un carro esperando en un semáforo en rojo"],"h1":"Piense en un conductor varado en el acotamiento.","h2":"La ley de cambiarse de carril de Minnesota también protege a los vehículos averiados o detenidos con las luces de advertencia encendidas, para que los conductores varados tengan la misma protección.","p":"Correcto. Los carros descompuestos con luces de emergencia también están protegidos."},"zh":{"q":"在 Minnesota，move over 法也保护下面哪一个？","o":["一辆开着危险警示灯、抛锚的车","一辆停在车道（driveway）上的车","一辆在公交站的公共汽车","一辆在红灯前等的车"],"h1":"想一想困在路肩上的司机。","h2":"Minnesota 的 move over 法也包括开着警示灯、抛锚或坏掉的车，这样被困的司机也得到同样的保护。","p":"对。开着危险警示灯的抛锚车也包括在内。"},"vi":{"q":"Ở Minnesota, luật nhường làn (move over law) cũng bảo vệ đối tượng nào sau đây?","o":["Xe bị hỏng đang bật đèn cảnh báo","Xe đậu trong lối vào nhà","Xe buýt ở trạm xe buýt","Xe đang chờ đèn đỏ"],"h1":"Hãy nghĩ đến người lái xe bị kẹt bên lề đường.","h2":"Luật nhường làn của Minnesota cũng áp dụng cho xe bị hỏng hoặc chết máy đang bật đèn cảnh báo, để người lái xe bị kẹt cũng được bảo vệ như vậy.","p":"Đúng. Xe bị hỏng đang bật đèn cảnh báo cũng được bảo vệ."},"tl":{"q":"Sa Minnesota, alin dito ang pinoprotektahan din ng move over law?","o":["Sirang kotse na nakabukas ang hazard lights","Kotseng nakaparada sa driveway","Bus sa bus stop","Kotseng naghihintay sa red light"],"h1":"Isipin ang driver na naiwan sa gilid ng daan.","h2":"Sakop din ng move over law ng Minnesota ang sira o tumirik na sasakyan na nakabukas ang warning lights, para pareho ang proteksyon ng mga naiwang driver.","p":"Tama. Sakop din ang sirang kotse na nakabukas ang hazard lights."},"ar":{"q":"في Minnesota، قانون الابتعاد (move over law) يحمي أيضًا أيًّا مما يلي؟","o":["سيارة معطّلة أضواء التحذير فيها مضاءة","سيارة واقفة في ممر بيت","حافلة عند موقف الحافلات","سيارة تنتظر عند الإشارة الحمراء"],"h1":"فكّر في سائق عالق على كتف الطريق.","h2":"قانون الابتعاد في Minnesota يشمل أيضًا المركبات المتوقفة أو المعطّلة وأضواء التحذير فيها مضاءة، حتى يحصل السائقون العالقون على الحماية نفسها.","p":"صحيح. السيارات المعطّلة وأضواء التحذير فيها مضاءة مشمولة أيضًا."},"ref":{"doc":"MN","page":44}},{"id":"mn-019","scope":"MN","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Minnesota, how far from a school bus with its stop arm out and red lights flashing must you stop?","o":["At least 5 feet","At least 10 feet","At least 20 feet","At least 50 feet"],"h1":"It is about the length of one car and a half.","h2":"In Minnesota you must stop at least 20 feet from a school bus with its stop arm out and red lights flashing, to give children room to cross.","p":"Right. Stop at least 20 feet away."},"es":{"q":"En Minnesota, ¿a qué distancia de un autobús escolar con el brazo de alto extendido y luces rojas intermitentes debe parar?","o":["Por lo menos 5 pies","Por lo menos 10 pies","Por lo menos 20 pies","Por lo menos 50 pies"],"h1":"Es como el largo de un carro y medio.","h2":"En Minnesota usted debe parar por lo menos a 20 pies de un autobús escolar con el brazo de alto extendido y luces rojas intermitentes, para dar espacio a los niños que cruzan.","p":"Correcto. Pare por lo menos a 20 pies."},"zh":{"q":"在 Minnesota，你必须在离伸出停车臂、闪着红灯的校车多远的地方停车？","o":["至少 5 英尺","至少 10 英尺","至少 20 英尺","至少 50 英尺"],"h1":"大约是一辆半汽车的长度。","h2":"在 Minnesota，你必须在离伸出停车臂、闪着红灯的校车至少 20 英尺的地方停车，给孩子留出过马路的空间。","p":"对。在至少 20 英尺外停车。"},"vi":{"q":"Ở Minnesota, bạn phải dừng cách xe buýt trường học đang giơ cần báo dừng và nhấp nháy đèn đỏ bao xa?","o":["Ít nhất 5 feet","Ít nhất 10 feet","Ít nhất 20 feet","Ít nhất 50 feet"],"h1":"Khoảng chiều dài của một chiếc xe rưỡi.","h2":"Ở Minnesota, bạn phải dừng cách ít nhất 20 feet khỏi xe buýt trường học đang giơ cần báo dừng và nhấp nháy đèn đỏ, để trẻ em có chỗ băng qua đường.","p":"Đúng. Dừng cách ít nhất 20 feet."},"tl":{"q":"Sa Minnesota, gaano kalayo ka dapat huminto mula sa school bus na nakalabas ang stop arm at kumikislap ang pulang ilaw?","o":["Hindi bababa sa 5 feet","Hindi bababa sa 10 feet","Hindi bababa sa 20 feet","Hindi bababa sa 50 feet"],"h1":"Mga isa't kalahating haba ng kotse ito.","h2":"Sa Minnesota, dapat kang huminto nang hindi bababa sa 20 feet mula sa school bus na nakalabas ang stop arm at kumikislap ang pulang ilaw, para may lugar ang mga bata na tumawid.","p":"Tama. Huminto nang hindi bababa sa 20 feet ang layo."},"ar":{"q":"في Minnesota، على أي مسافة يجب أن تتوقف من حافلة مدرسية ذراع التوقف فيها ممدودة وأضواؤها الحمراء تومض؟","o":["5 feet على الأقل","10 feet على الأقل","20 feet على الأقل","50 feet على الأقل"],"h1":"إنها تقريبًا طول سيارة ونصف.","h2":"في Minnesota يجب أن تتوقف على بعد 20 feet على الأقل من الحافلة المدرسية التي ذراع التوقف فيها ممدودة وأضواؤها الحمراء تومض، لتعطي الأطفال مكانًا للعبور.","p":"صحيح. توقف على بعد 20 feet على الأقل."},"ref":{"doc":"MN","page":42}},{"id":"mn-020","scope":"MN","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Minnesota, when may oncoming traffic keep going past a school bus with its stop arm out?","o":["When the bus is on a two-lane road","When no children are visible","When the road has four lanes but no median","When a raised or depressed median separates the roads"],"h1":"The roads must be truly separated by something built.","h2":"In Minnesota, oncoming drivers need not stop only on a divided road, where a physical barrier or a raised or depressed median separates the two sides.","p":"Right. Only a real median or barrier lets oncoming traffic keep going."},"es":{"q":"En Minnesota, ¿cuándo puede seguir el tránsito que viene en sentido contrario ante un autobús escolar con el brazo de alto extendido?","o":["Cuando el autobús está en una vía de dos carriles","Cuando no se ven niños","Cuando la carretera tiene cuatro carriles pero no tiene división","Cuando un camellón elevado o hundido separa las vías"],"h1":"Las vías deben estar separadas de verdad por algo construido.","h2":"En Minnesota, los conductores que vienen en sentido contrario no tienen que detenerse solo en una carretera dividida, donde una barrera física o una división elevada o hundida separa los dos lados.","p":"Correcto. Solo un camellón o barrera real permite seguir."},"zh":{"q":"在 Minnesota，对面开来的车什么时候可以继续开过伸出停车臂的校车？","o":["校车在双车道的路上时","看不到孩子时","路有四条车道但没有中央隔离带时","有凸起或下沉的中央隔离带把两边的路分开时"],"h1":"两边的路必须真的被建好的东西分开。","h2":"在 Minnesota，只有在分隔道路上，也就是有实体护栏或凸起、下沉的中央隔离带把两边分开时，对面的司机才不用停车。","p":"对。只有真正的中央隔离带或护栏，才能让对面的车继续开。"},"vi":{"q":"Ở Minnesota, khi nào xe đi ngược chiều được tiếp tục chạy qua xe buýt trường học đang giơ cần báo dừng?","o":["Khi xe buýt ở trên đường hai làn","Khi không thấy trẻ em nào","Khi đường có bốn làn nhưng không có dải phân cách","Khi có dải phân cách nổi cao hoặc trũng thấp ngăn hai bên đường"],"h1":"Hai bên đường phải thật sự được ngăn cách bằng một thứ được xây dựng.","h2":"Ở Minnesota, xe đi ngược chiều chỉ không cần dừng trên đường có phân cách, nơi có rào chắn hoặc dải phân cách nổi cao hay trũng thấp ngăn hai bên đường.","p":"Đúng. Chỉ có dải phân cách thật hoặc rào chắn mới cho xe ngược chiều tiếp tục chạy."},"tl":{"q":"Sa Minnesota, kailan puwedeng tumuloy ang paparating na sasakyan sa kabilang direksyon na dumaan sa school bus na nakalabas ang stop arm?","o":["Kapag ang bus ay nasa daang may dalawang lane","Kapag walang nakikitang bata","Kapag may apat na lane ang daan pero walang median","Kapag may nakaangat o nakababang median na naghihiwalay sa mga daan"],"h1":"Ang mga daan ay dapat talagang hiwalay dahil sa isang bagay na itinayo.","h2":"Sa Minnesota, hindi kailangang huminto ang mga paparating na driver sa kabilang direksyon kapag nasa divided road lang, kung saan may harang o nakaangat o nakababang median na naghihiwalay sa dalawang panig.","p":"Tama. Tunay na median o harang lang ang nagpapahintulot sa kabilang direksyon na tumuloy."},"ar":{"q":"في Minnesota، متى يجوز لحركة المرور القادمة من الاتجاه المعاكس أن تستمر في المرور بجانب حافلة مدرسية ذراع التوقف فيها ممدودة؟","o":["عندما تكون الحافلة على طريق بحارتين","عندما لا يُرى أي أطفال","عندما يكون للطريق أربع حارات ولكن بلا جزيرة وسطية","عندما تفصل جزيرة وسطية مرتفعة أو منخفضة بين الطريقين"],"h1":"يجب أن يكون الطريقان مفصولين فعلًا بشيء مبني.","h2":"في Minnesota، لا يلزم السائقين القادمين من الاتجاه المعاكس أن يتوقفوا إلا على طريق مقسوم، حيث يفصل حاجز أو جزيرة وسطية مرتفعة أو منخفضة بين الجانبين.","p":"صحيح. فقط جزيرة وسطية حقيقية أو حاجز يسمح لحركة المرور المعاكسة بالاستمرار."},"ref":{"doc":"MN","page":42}},{"id":"mn-021","scope":"MN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Minnesota, under the Not a Drop law, how much alcohol may a driver under 21 have?","o":["Up to 0.02","None at all","Up to 0.05","Up to 0.08"],"h1":"The name of the law gives the answer.","h2":"Minnesota's Not a Drop law makes it illegal for a driver under 21 to drive after drinking any alcohol at all.","p":"Right. Under 21 means not a drop."},"es":{"q":"En Minnesota, según la ley Not a Drop (Ni una gota), ¿cuánto alcohol puede tener un conductor menor de 21?","o":["Hasta 0.02","Nada","Hasta 0.05","Hasta 0.08"],"h1":"El nombre de la ley da la respuesta.","h2":"La ley Not a Drop de Minnesota prohíbe que un conductor menor de 21 maneje después de tomar cualquier cantidad de alcohol.","p":"Correcto. Menor de 21 significa ni una gota."},"zh":{"q":"在 Minnesota，根据 Not a Drop 法，21 岁以下的司机体内可以有多少酒精？","o":["最多 0.02","一点都不行","最多 0.05","最多 0.08"],"h1":"这条法律的名字就给出了答案（Not a Drop 的意思是一滴都不行）。","h2":"Minnesota 的 Not a Drop 法规定，21 岁以下的司机只要喝了任何酒，再开车就是违法的。","p":"对。21 岁以下就是一滴都不行。"},"vi":{"q":"Ở Minnesota, theo luật Not a Drop (không một giọt), người lái xe dưới 21 tuổi được có bao nhiêu rượu bia trong người?","o":["Tối đa 0.02","Hoàn toàn không có","Tối đa 0.05","Tối đa 0.08"],"h1":"Tên của luật cho bạn câu trả lời.","h2":"Luật Not a Drop của Minnesota cấm người lái xe dưới 21 tuổi lái xe sau khi uống bất kỳ chút rượu bia nào.","p":"Đúng. Dưới 21 tuổi nghĩa là không một giọt."},"tl":{"q":"Sa Minnesota, sa ilalim ng Not a Drop law (batas na kahit isang patak ay bawal), gaano karaming alak ang puwedeng mayroon ang driver na wala pang 21?","o":["Hanggang 0.02","Wala talaga","Hanggang 0.05","Hanggang 0.08"],"h1":"Ang pangalan ng batas ang nagbibigay ng sagot.","h2":"Ginagawang ilegal ng Not a Drop law ng Minnesota ang pagmamaneho ng driver na wala pang 21 pagkatapos uminom ng kahit anong alak.","p":"Tama. Kung wala pang 21, kahit isang patak ay bawal."},"ar":{"q":"في Minnesota، بموجب قانون Not a Drop (ولا قطرة)، كم من الكحول يجوز أن يكون لدى سائق عمره أقل من 21 سنة؟","o":["حتى 0.02","لا شيء على الإطلاق","حتى 0.05","حتى 0.08"],"h1":"اسم القانون يعطيك الجواب.","h2":"قانون Not a Drop في Minnesota يجعل القيادة بعد شرب أي كمية من الكحول ممنوعة على السائق الذي عمره أقل من 21 سنة.","p":"صحيح. تحت 21 سنة يعني ولا قطرة."},"ref":{"doc":"MN","page":95}},{"id":"mn-022","scope":"MN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Minnesota, unless a sign says otherwise, what is the speed limit in an urban district?","o":["30 mph","25 mph","35 mph","40 mph"],"h1":"It is a round number below 35.","h2":"Minnesota law sets 30 mph in an urban district when no other limit is posted, because homes, businesses and people are close to the road.","p":"Right. Urban districts are 30 mph."},"es":{"q":"En Minnesota, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad en zona urbana?","o":["30 mph","25 mph","35 mph","40 mph"],"h1":"Es un número redondo menor que 35.","h2":"La ley de Minnesota fija 30 mph en zona urbana cuando no hay otro límite indicado, porque hay casas, negocios y personas cerca de la vía.","p":"Correcto. En zona urbana el límite es 30 mph."},"zh":{"q":"在 Minnesota，除非有标志另外规定，城区（urban district）的限速是多少？","o":["30 英里/小时","25 英里/小时","35 英里/小时","40 英里/小时"],"h1":"这是一个比 35 小的整数。","h2":"没有标出其他限速时，Minnesota 法律规定城区限速 30 英里/小时，因为住家、商店和人都离路很近。","p":"对。城区限速 30 英里/小时。"},"vi":{"q":"Ở Minnesota, nếu không có biển báo khác, tốc độ giới hạn trong khu đô thị là bao nhiêu?","o":["30 mph","25 mph","35 mph","40 mph"],"h1":"Đó là một số tròn nhỏ hơn 35.","h2":"Luật Minnesota đặt tốc độ 30 mph trong khu đô thị khi không có giới hạn khác được ghi, vì nhà cửa, cửa hàng và người đi bộ ở gần đường.","p":"Đúng. Khu đô thị là 30 mph."},"tl":{"q":"Sa Minnesota, maliban kung iba ang sinasabi ng karatula, ano ang speed limit sa urban district (lugar sa lungsod)?","o":["30 mph","25 mph","35 mph","40 mph"],"h1":"Ito ay buong bilang na mas mababa sa 35.","h2":"Itinatakda ng batas ng Minnesota ang 30 mph sa urban district kapag walang ibang nakapaskil na limit, dahil malapit sa daan ang mga bahay, negosyo at tao.","p":"Tama. 30 mph sa urban district."},"ar":{"q":"في Minnesota، ما لم تقل لافتة غير ذلك، ما حد السرعة في منطقة حضرية (urban district)؟","o":["30 mph","25 mph","35 mph","40 mph"],"h1":"إنه رقم مستدير أقل من 35.","h2":"يحدد قانون Minnesota سرعة 30 mph في المنطقة الحضرية عندما لا يوجد حد آخر معلن، لأن البيوت والمحلات والناس قريبون من الطريق.","p":"صحيح. المناطق الحضرية 30 mph."},"ref":{"doc":"MN","page":26}},{"id":"mn-023","scope":"MN","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Minnesota, what is the speed limit on an interstate outside a large urban area, unless posted otherwise?","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"Inside big cities the interstate limit is 5 mph lower.","h2":"Minnesota sets 70 mph on interstates outside urbanized areas of more than 50,000 people, and 65 mph inside them.","p":"Right. Rural interstates are 70 mph."},"es":{"q":"En Minnesota, ¿cuál es el límite de velocidad en una interestatal fuera de una zona urbana grande, si no hay otro indicado?","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"Dentro de las ciudades grandes el límite en la interestatal es 5 mph menos.","h2":"Minnesota fija 70 mph en las interestatales fuera de zonas urbanas de más de 50,000 personas, y 65 mph dentro de ellas.","p":"Correcto. Las interestatales rurales son de 70 mph."},"zh":{"q":"在 Minnesota，除非另有标示，大城市地区以外的州际公路限速是多少？","o":["55 英里/小时","65 英里/小时","70 英里/小时","75 英里/小时"],"h1":"在大城市里，州际公路的限速低 5 英里/小时。","h2":"Minnesota 规定，在人口超过 50,000 的城市化地区以外，州际公路限速 70 英里/小时，在这些地区以内是 65 英里/小时。","p":"对。乡村的州际公路限速 70 英里/小时。"},"vi":{"q":"Ở Minnesota, tốc độ giới hạn trên xa lộ liên bang (interstate) bên ngoài khu đô thị lớn là bao nhiêu, nếu không có biển báo khác?","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"Trong các thành phố lớn, giới hạn trên xa lộ liên bang thấp hơn 5 mph.","h2":"Minnesota đặt 70 mph trên xa lộ liên bang bên ngoài khu đô thị có hơn 50,000 dân, và 65 mph bên trong các khu đó.","p":"Đúng. Xa lộ liên bang ở vùng nông thôn là 70 mph."},"tl":{"q":"Sa Minnesota, ano ang speed limit sa interstate sa labas ng malaking urban area, maliban kung iba ang nakapaskil?","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"Sa loob ng malalaking lungsod, 5 mph na mas mababa ang limit sa interstate.","h2":"Itinatakda ng Minnesota ang 70 mph sa mga interstate sa labas ng urbanized area na may higit sa 50,000 tao, at 65 mph sa loob ng mga ito.","p":"Tama. 70 mph sa mga interstate sa probinsya."},"ar":{"q":"في Minnesota، ما حد السرعة على الطريق السريع بين الولايات (interstate) خارج منطقة حضرية كبيرة، ما لم يُعلن غير ذلك؟","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"داخل المدن الكبيرة يكون حد السرعة على الطريق السريع أقل بـ 5 mph.","h2":"تحدد Minnesota سرعة 70 mph على الطرق السريعة بين الولايات خارج المناطق الحضرية التي يزيد سكانها على 50,000 شخص، و65 mph داخلها.","p":"صحيح. الطرق السريعة بين الولايات في الريف 70 mph."},"ref":{"doc":"MN","page":null}},{"id":"mn-024","scope":"MN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Minnesota, when must you turn on your headlights during the day?","o":["Only on the freeway","Whenever it is raining or snowing","Only in a tunnel","Only after 6 p.m."],"h1":"Think about weather that makes cars hard to see.","h2":"Minnesota law requires headlights whenever it is raining, snowing, sleeting or hailing, even in daytime, so other drivers can see you.","p":"Right. Rain or snow means headlights on."},"es":{"q":"En Minnesota, ¿cuándo debe encender los faros durante el día?","o":["Solo en la autopista","Siempre que llueva o nieve","Solo en un túnel","Solo después de las 6 p.m."],"h1":"Piense en el clima que hace difícil ver los carros.","h2":"La ley de Minnesota exige los faros encendidos siempre que llueva, nieve, caiga aguanieve o granizo, aunque sea de día, para que otros conductores lo vean.","p":"Correcto. Con lluvia o nieve, faros encendidos."},"zh":{"q":"在 Minnesota，白天什么时候必须打开车头灯？","o":["只在高速公路上","只要在下雨或下雪","只在隧道里","只在下午 6 点以后"],"h1":"想一想让车很难被看见的天气。","h2":"Minnesota 法律规定，只要在下雨、下雪、下雨夹雪或下冰雹，即使是白天，也必须打开车头灯，这样其他司机才能看见你。","p":"对。下雨或下雪就要开车头灯。"},"vi":{"q":"Ở Minnesota, khi nào bạn phải bật đèn pha vào ban ngày?","o":["Chỉ trên xa lộ","Bất cứ khi nào trời mưa hoặc có tuyết","Chỉ trong đường hầm","Chỉ sau 6 giờ chiều"],"h1":"Hãy nghĩ đến thời tiết làm khó thấy xe.","h2":"Luật Minnesota yêu cầu bật đèn pha bất cứ khi nào trời mưa, có tuyết, mưa tuyết hoặc mưa đá, kể cả ban ngày, để người lái xe khác thấy bạn.","p":"Đúng. Trời mưa hoặc có tuyết thì bật đèn pha."},"tl":{"q":"Sa Minnesota, kailan mo dapat buksan ang headlights sa araw?","o":["Sa freeway lang","Tuwing umuulan o umuulan ng niyebe","Sa tunnel lang","Pagkatapos lang ng 6 p.m."],"h1":"Isipin ang panahon na nagpapahirap makita ang mga kotse.","h2":"Inuutos ng batas ng Minnesota na nakabukas ang headlights tuwing umuulan, umuulan ng niyebe, sleet o yelo (hail), kahit araw, para makita ka ng ibang driver.","p":"Tama. Kapag ulan o niyebe, bukas ang headlights."},"ar":{"q":"في Minnesota، متى يجب أن تشغّل المصابيح الأمامية أثناء النهار؟","o":["على الطريق السريع فقط","كلما كان هناك مطر أو ثلج","في النفق فقط","بعد الساعة 6 مساءً فقط"],"h1":"فكّر في الطقس الذي يجعل رؤية السيارات صعبة.","h2":"يشترط قانون Minnesota تشغيل المصابيح الأمامية كلما كان هناك مطر أو ثلج أو مطر متجمّد أو بَرَد، حتى في النهار، حتى يراك السائقون الآخرون.","p":"صحيح. المطر أو الثلج يعني تشغيل المصابيح الأمامية."},"ref":{"doc":"MN","page":23}},{"id":"mn-025","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, what type of coverage must every car owner carry because the state has a no-fault system?","o":["Collision coverage","Rental car coverage","Roadside assistance","Personal injury protection (PIP)"],"h1":"It pays your own medical bills no matter who caused the crash.","h2":"Minnesota is a no-fault state, so every owner must carry no-fault insurance, called personal injury protection, which pays your own medical costs and lost wages whoever was at fault.","p":"Right. Minnesota requires personal injury protection."},"es":{"q":"En Minnesota, ¿qué tipo de cobertura debe tener todo dueño de carro porque el estado tiene un sistema sin culpa (no-fault)?","o":["Cobertura de choque","Cobertura de auto de alquiler","Asistencia en el camino","Protección por lesiones personales (PIP)"],"h1":"Paga sus propios gastos médicos sin importar quién causó el choque.","h2":"Minnesota es un estado sin culpa, así que todo dueño debe tener el seguro sin culpa, llamado protección contra lesiones personales, que paga sus propios gastos médicos y salarios perdidos sin importar quién tuvo la culpa.","p":"Correcto. Minnesota exige protección por lesiones personales."},"zh":{"q":"在 Minnesota，因为州里实行无过失制度，每位车主都必须买哪种保险？","o":["碰撞险","租车保险","道路救援","个人伤害保障 (PIP)"],"h1":"不管车祸是谁造成的，它都支付你自己的医疗费用。","h2":"Minnesota 是无过失州，所以每位车主都必须买无过失保险，叫做个人伤害保障，不管谁有过错，它都支付你自己的医疗费用和损失的工资。","p":"对。Minnesota 要求个人伤害保障。"},"vi":{"q":"Ở Minnesota, mọi chủ xe phải mua loại bảo hiểm nào vì tiểu bang có hệ thống không xét lỗi (no-fault)?","o":["Bảo hiểm va chạm (collision)","Bảo hiểm xe thuê","Hỗ trợ bên đường","Bảo hiểm thương tích cá nhân (personal injury protection, PIP)"],"h1":"Nó trả chi phí y tế của chính bạn, bất kể ai gây ra tai nạn.","h2":"Minnesota là tiểu bang không xét lỗi, nên mọi chủ xe phải có bảo hiểm không xét lỗi, gọi là bảo hiểm thương tích cá nhân, trả chi phí y tế và tiền lương bị mất của chính bạn, bất kể ai có lỗi.","p":"Đúng. Minnesota yêu cầu bảo hiểm thương tích cá nhân."},"tl":{"q":"Sa Minnesota, anong uri ng coverage ang dapat mayroon ang bawat may-ari ng kotse dahil may no-fault system ang estado?","o":["Collision coverage","Coverage para sa inuupahang kotse","Roadside assistance","Personal injury protection (PIP)"],"h1":"Binabayaran nito ang sarili mong gastos sa pagpapagamot kahit sino ang may sanhi ng banggaan.","h2":"Ang Minnesota ay no-fault state, kaya ang bawat may-ari ay dapat may no-fault insurance, na tinatawag na personal injury protection, na nagbabayad ng sarili mong gastos sa pagpapagamot at nawalang sahod kahit sino ang may kasalanan.","p":"Tama. Inuutos ng Minnesota ang personal injury protection."},"ar":{"q":"في Minnesota، ما نوع التغطية التأمينية التي يجب أن يحملها كل مالك سيارة لأن الولاية تتبع نظام عدم تحديد الخطأ (no-fault)؟","o":["تأمين التصادم (collision)","تأمين السيارة المستأجرة","المساعدة على الطريق","تأمين الحماية من الإصابة الشخصية (personal injury protection, PIP)"],"h1":"إنه يدفع تكاليفك الطبية أنت مهما كان المتسبب في الحادث.","h2":"Minnesota ولاية بنظام عدم تحديد الخطأ، لذلك يجب على كل مالك أن يحمل تأمين عدم تحديد الخطأ، ويسمى الحماية من الإصابة الشخصية، وهو يدفع تكاليفك الطبية وأجرك الضائع أيًّا كان المخطئ.","p":"صحيح. تشترط Minnesota تأمين الحماية من الإصابة الشخصية."},"ref":{"doc":"MN","page":40}},{"id":"mn-026","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, what is the minimum liability insurance for damage to other people's property in one crash?","o":["$10,000","$15,000","$25,000","$30,000"],"h1":"It is the last number in 30/60/10.","h2":"Minnesota requires at least $10,000 of property damage liability for one crash, the last number in the 30/60/10 minimum.","p":"Right. The property damage minimum is $10,000."},"es":{"q":"En Minnesota, ¿cuál es el seguro mínimo de responsabilidad por daños a la propiedad de otros en un choque?","o":["$10,000","$15,000","$25,000","$30,000"],"h1":"Es el último número de 30/60/10.","h2":"Minnesota exige por lo menos $10,000 de cobertura por daños a la propiedad en un choque, el último número del mínimo 30/60/10.","p":"Correcto. El mínimo por daños a la propiedad es $10,000."},"zh":{"q":"在 Minnesota，一次车祸中对别人财产损失的最低责任保险是多少？","o":["$10,000","$15,000","$25,000","$30,000"],"h1":"它是 30/60/10 里的最后一个数字。","h2":"Minnesota 要求一次车祸至少有 $10,000 的财产损失责任保险，也就是 30/60/10 最低标准里的最后一个数字。","p":"对。财产损失的最低额是 $10,000。"},"vi":{"q":"Ở Minnesota, bảo hiểm trách nhiệm tối thiểu cho thiệt hại tài sản của người khác trong một tai nạn là bao nhiêu?","o":["$10,000","$15,000","$25,000","$30,000"],"h1":"Đó là số cuối cùng trong 30/60/10.","h2":"Minnesota yêu cầu ít nhất $10,000 bảo hiểm trách nhiệm thiệt hại tài sản cho một tai nạn, là số cuối cùng trong mức tối thiểu 30/60/10.","p":"Đúng. Mức tối thiểu cho thiệt hại tài sản là $10,000."},"tl":{"q":"Sa Minnesota, ano ang pinakamababang liability insurance para sa pinsala sa ari-arian ng ibang tao sa isang banggaan?","o":["$10,000","$15,000","$25,000","$30,000"],"h1":"Ito ang huling bilang sa 30/60/10.","h2":"Inuutos ng Minnesota ang hindi bababa sa $10,000 na property damage liability para sa isang banggaan, ang huling bilang sa minimum na 30/60/10.","p":"Tama. Ang minimum para sa pinsala sa ari-arian ay $10,000."},"ar":{"q":"في Minnesota، ما الحد الأدنى لتأمين المسؤولية عن الضرر في ممتلكات الآخرين في حادث واحد؟","o":["$10,000","$15,000","$25,000","$30,000"],"h1":"إنه الرقم الأخير في 30/60/10.","h2":"تشترط Minnesota تأمين مسؤولية عن الضرر في الممتلكات قدره $10,000 على الأقل لحادث واحد، وهو الرقم الأخير في الحد الأدنى 30/60/10.","p":"صحيح. الحد الأدنى للضرر في الممتلكات هو $10,000."},"ref":{"doc":"MN","page":null}},{"id":"mn-027","scope":"MN","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Minnesota, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 15 feet","No closer than 25 feet"],"h1":"Minnesota's distance is shorter than in many other states.","h2":"In Minnesota you may not park within 10 feet of a fire hydrant, so fire crews can reach it.","p":"Right. Stay at least 10 feet from a hydrant."},"es":{"q":"En Minnesota, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 15 pies","No más cerca de 25 pies"],"h1":"La distancia de Minnesota es más corta que en muchos otros estados.","h2":"En Minnesota usted no puede estacionarse a menos de 10 pies de un hidrante, para que los bomberos puedan llegar a él.","p":"Correcto. Quédese por lo menos a 10 pies de un hidrante."},"zh":{"q":"在 Minnesota，你可以把车停在离消防栓多近的地方？","o":["不得近于 5 英尺","不得近于 10 英尺","不得近于 15 英尺","不得近于 25 英尺"],"h1":"Minnesota 的距离比很多其他州短。","h2":"在 Minnesota，你不可以在离消防栓 10 英尺以内停车，这样消防员才能用到它。","p":"对。离消防栓至少 10 英尺。"},"vi":{"q":"Ở Minnesota, bạn được đậu xe gần trụ nước cứu hỏa đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 15 feet","Không gần hơn 25 feet"],"h1":"Khoảng cách ở Minnesota ngắn hơn ở nhiều tiểu bang khác.","h2":"Ở Minnesota, bạn không được đậu xe trong vòng 10 feet cách trụ nước cứu hỏa, để lính cứu hỏa có thể đến được trụ nước.","p":"Đúng. Hãy cách trụ nước cứu hỏa ít nhất 10 feet."},"tl":{"q":"Sa Minnesota, gaano kalapit sa fire hydrant ang puwede mong pagparadahan?","o":["Hindi lalapit sa 5 feet","Hindi lalapit sa 10 feet","Hindi lalapit sa 15 feet","Hindi lalapit sa 25 feet"],"h1":"Mas maikli ang layo sa Minnesota kaysa sa maraming ibang estado.","h2":"Sa Minnesota, hindi ka puwedeng pumarada sa loob ng 10 feet mula sa fire hydrant, para maabot ito ng mga bumbero.","p":"Tama. Lumayo nang hindi bababa sa 10 feet mula sa hydrant."},"ar":{"q":"في Minnesota، إلى أي مسافة يمكنك أن تركن قرب صنبور إطفاء الحريق؟","o":["ليس أقرب من 5 feet","ليس أقرب من 10 feet","ليس أقرب من 15 feet","ليس أقرب من 25 feet"],"h1":"المسافة في Minnesota أقصر منها في كثير من الولايات الأخرى.","h2":"في Minnesota لا يجوز لك أن تركن على بعد أقل من 10 feet من صنبور إطفاء الحريق، حتى يستطيع رجال الإطفاء الوصول إليه.","p":"صحيح. ابقَ على بعد 10 feet على الأقل من صنبور الإطفاء."},"ref":{"doc":"MN","page":35}},{"id":"mn-028","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, what vision do you need to pass the vision screening, with glasses or contacts if you use them?","o":["At least 20/20","At least 20/30","At least 20/40","At least 20/70"],"h1":"It is the same number many states use.","h2":"In Minnesota your vision, with or without correction, must be at least 20/40 to pass the vision screening.","p":"Right. You need at least 20/40 vision."},"es":{"q":"En Minnesota, ¿qué visión necesita para pasar el examen de la vista, con lentes o lentes de contacto si los usa?","o":["Por lo menos 20/20","Por lo menos 20/30","Por lo menos 20/40","Por lo menos 20/70"],"h1":"Es el mismo número que usan muchos estados.","h2":"En Minnesota su visión, con o sin corrección, debe ser por lo menos 20/40 para pasar el examen de la vista.","p":"Correcto. Necesita una visión de por lo menos 20/40."},"zh":{"q":"在 Minnesota，要通过视力检查，你需要多好的视力？（如果你戴眼镜或隐形眼镜，就戴着测）","o":["至少 20/20","至少 20/30","至少 20/40","至少 20/70"],"h1":"这和很多州用的数字一样。","h2":"在 Minnesota，你的视力（戴不戴矫正眼镜都算）必须至少是 20/40，才能通过视力检查。","p":"对。你的视力需要至少 20/40。"},"vi":{"q":"Ở Minnesota, bạn cần thị lực như thế nào để qua bài kiểm tra mắt, khi đeo kính hoặc kính áp tròng nếu bạn có dùng?","o":["Ít nhất 20/20","Ít nhất 20/30","Ít nhất 20/40","Ít nhất 20/70"],"h1":"Đó là con số mà nhiều tiểu bang cũng dùng.","h2":"Ở Minnesota, thị lực của bạn, có hoặc không có kính, phải ít nhất là 20/40 để qua bài kiểm tra mắt.","p":"Đúng. Bạn cần thị lực ít nhất 20/40."},"tl":{"q":"Sa Minnesota, anong paningin ang kailangan mo para pumasa sa vision screening, suot ang salamin o contact lens kung gumagamit ka nito?","o":["Hindi bababa sa 20/20","Hindi bababa sa 20/30","Hindi bababa sa 20/40","Hindi bababa sa 20/70"],"h1":"Ito rin ang numerong ginagamit ng maraming estado.","h2":"Sa Minnesota, ang paningin mo, may salamin man o wala, ay dapat hindi bababa sa 20/40 para pumasa sa vision screening.","p":"Tama. Kailangan mo ng paningin na hindi bababa sa 20/40."},"ar":{"q":"في Minnesota، ما قوة النظر التي تحتاجها لتنجح في فحص النظر، مع النظارة أو العدسات اللاصقة إن كنت تستعملها؟","o":["20/20 على الأقل","20/30 على الأقل","20/40 على الأقل","20/70 على الأقل"],"h1":"إنه الرقم نفسه الذي تستعمله ولايات كثيرة.","h2":"في Minnesota يجب أن يكون نظرك، مع التصحيح أو بدونه، 20/40 على الأقل لتنجح في فحص النظر.","p":"صحيح. تحتاج إلى نظر 20/40 على الأقل."},"ref":{"doc":"MN","page":10}},{"id":"mn-029","scope":"MN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Minnesota, how much space must you leave between your car and a bicyclist you are passing?","o":["At least 3 feet","At least 1 foot","At least 18 inches","At least 2 feet"],"h1":"Think of about one long step.","h2":"In Minnesota you must leave at least 3 feet between your car and a bicyclist when you pass, and you may cross the center line to do it when it is safe.","p":"Right. Give a bicyclist at least 3 feet."},"es":{"q":"En Minnesota, ¿cuánto espacio debe dejar entre su carro y un ciclista al que va a rebasar?","o":["Por lo menos 3 pies","Por lo menos 1 pie","Por lo menos 18 pulgadas","Por lo menos 2 pies"],"h1":"Piense en un paso largo.","h2":"En Minnesota usted debe dejar por lo menos 3 pies entre su carro y un ciclista al rebasarlo, y puede cruzar la línea central para hacerlo cuando sea seguro.","p":"Correcto. Deje por lo menos 3 pies a un ciclista."},"zh":{"q":"在 Minnesota，你超过骑自行车的人时，你的车和他之间必须留多少空间？","o":["至少 3 英尺","至少 1 英尺","至少 18 英寸","至少 2 英尺"],"h1":"想一想大约一大步的距离。","h2":"在 Minnesota，你超过骑自行车的人时，必须在你的车和他之间留至少 3 英尺；在安全的时候，你可以越过中线来这样做。","p":"对。给骑自行车的人留至少 3 英尺。"},"vi":{"q":"Ở Minnesota, khi vượt người đi xe đạp, bạn phải chừa bao nhiêu khoảng cách giữa xe của bạn và người đó?","o":["Ít nhất 3 feet","Ít nhất 1 foot","Ít nhất 18 inches","Ít nhất 2 feet"],"h1":"Hãy nghĩ đến khoảng một bước dài.","h2":"Ở Minnesota, khi vượt người đi xe đạp, bạn phải chừa ít nhất 3 feet giữa xe của bạn và người đó, và bạn được lấn qua vạch giữa đường để làm vậy khi an toàn.","p":"Đúng. Hãy chừa cho người đi xe đạp ít nhất 3 feet."},"tl":{"q":"Sa Minnesota, gaano kalaking espasyo ang dapat mong iwan sa pagitan ng kotse mo at ng nagbibisikleta na inuunahan mo?","o":["Hindi bababa sa 3 feet","Hindi bababa sa 1 foot","Hindi bababa sa 18 inches","Hindi bababa sa 2 feet"],"h1":"Isipin ang mga isang mahabang hakbang.","h2":"Sa Minnesota, dapat kang mag-iwan ng hindi bababa sa 3 feet sa pagitan ng kotse mo at ng nagbibisikleta kapag inuunahan mo siya, at puwede kang tumawid sa gitnang linya para gawin ito kapag ligtas.","p":"Tama. Bigyan ang nagbibisikleta ng hindi bababa sa 3 feet."},"ar":{"q":"في Minnesota، كم مسافة يجب أن تتركها بين سيارتك وراكب الدراجة الذي تتجاوزه؟","o":["3 feet على الأقل","1 foot على الأقل","18 inches على الأقل","2 feet على الأقل"],"h1":"فكّر في خطوة طويلة تقريبًا.","h2":"في Minnesota يجب أن تترك 3 feet على الأقل بين سيارتك وراكب الدراجة عندما تتجاوزه، ويجوز لك أن تعبر الخط الأوسط لتفعل ذلك عندما يكون آمنًا.","p":"صحيح. اترك 3 feet على الأقل لراكب الدراجة."},"ref":{"doc":"MN","page":48}},{"id":"mn-030","scope":"MN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Minnesota, how close to an intersection or railroad crossing may you pass another vehicle?","o":["No closer than 25 feet","No closer than 50 feet","No closer than 300 feet","No closer than 100 feet"],"h1":"It is about the length of six or seven cars.","h2":"In Minnesota you may not pass another vehicle within 100 feet of an intersection, underpass, tunnel or railroad crossing.","p":"Right. Do not pass within 100 feet of those places."},"es":{"q":"En Minnesota, ¿qué tan cerca de una intersección o de un cruce de ferrocarril puede rebasar a otro vehículo?","o":["No más cerca de 25 pies","No más cerca de 50 pies","No más cerca de 300 pies","No más cerca de 100 pies"],"h1":"Es como el largo de seis o siete carros.","h2":"En Minnesota usted no puede rebasar a otro vehículo a menos de 100 pies de una intersección, un paso a desnivel, un túnel o un cruce de ferrocarril.","p":"Correcto. No rebase a menos de 100 pies de esos lugares."},"zh":{"q":"在 Minnesota，你可以在离路口或铁路道口多近的地方超车？","o":["不得近于 25 英尺","不得近于 50 英尺","不得近于 300 英尺","不得近于 100 英尺"],"h1":"大约是六七辆车的长度。","h2":"在 Minnesota，你不可以在离路口、地下通道、隧道或铁路道口 100 英尺以内超车。","p":"对。在这些地方 100 英尺以内不要超车。"},"vi":{"q":"Ở Minnesota, bạn được vượt xe khác khi cách giao lộ hoặc chỗ băng qua đường ray xe lửa bao xa?","o":["Không gần hơn 25 feet","Không gần hơn 50 feet","Không gần hơn 300 feet","Không gần hơn 100 feet"],"h1":"Khoảng bằng chiều dài của sáu hoặc bảy chiếc xe.","h2":"Ở Minnesota, bạn không được vượt xe khác trong vòng 100 feet cách giao lộ, đường chui, đường hầm hoặc chỗ băng qua đường ray xe lửa.","p":"Đúng. Không vượt xe trong vòng 100 feet cách những nơi đó."},"tl":{"q":"Sa Minnesota, gaano kalapit sa intersection o tawiran ng riles ng tren ang puwede kang umunahan ng ibang sasakyan?","o":["Hindi lalapit sa 25 feet","Hindi lalapit sa 50 feet","Hindi lalapit sa 300 feet","Hindi lalapit sa 100 feet"],"h1":"Mga haba ito ng anim o pitong kotse.","h2":"Sa Minnesota, hindi ka puwedeng umunahan ng ibang sasakyan sa loob ng 100 feet mula sa intersection, underpass, tunnel o tawiran ng riles ng tren.","p":"Tama. Huwag umunahan sa loob ng 100 feet mula sa mga lugar na iyon."},"ar":{"q":"في Minnesota، على أي مسافة من تقاطع أو معبر سكة حديد يمكنك أن تتجاوز مركبة أخرى؟","o":["ليس أقرب من 25 feet","ليس أقرب من 50 feet","ليس أقرب من 300 feet","ليس أقرب من 100 feet"],"h1":"إنها تقريبًا طول ست أو سبع سيارات.","h2":"في Minnesota لا يجوز لك أن تتجاوز مركبة أخرى على بعد أقل من 100 feet من تقاطع أو ممر سفلي أو نفق أو معبر سكة حديد.","p":"صحيح. لا تتجاوز على بعد أقل من 100 feet من تلك الأماكن."},"ref":{"doc":"MN","page":34}},{"id":"mn-031","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, when does a driver's license marked \"Under 21\" expire?","o":["On your 18th birthday","One year after it is issued","On your 21st birthday","On your 25th birthday"],"h1":"Look at the words printed on the license.","h2":"In Minnesota a license marked \"Under 21\" expires on your 21st birthday, and after that it expires every four years on your birthday.","p":"Right. It expires on your 21st birthday."},"es":{"q":"En Minnesota, ¿cuándo vence una licencia de manejo marcada \"Under 21\" (menor de 21)?","o":["En su cumpleaños número 18","Un año después de emitida","En su cumpleaños número 21","En su cumpleaños número 25"],"h1":"Fíjese en las palabras impresas en la licencia.","h2":"En Minnesota una licencia marcada \"Under 21\" vence en su cumpleaños número 21, y después vence cada cuatro años en su cumpleaños.","p":"Correcto. Vence en su cumpleaños número 21."},"zh":{"q":"在 Minnesota，标有 \"Under 21\"（未满 21 岁）的驾照什么时候过期？","o":["在你 18 岁生日那天","发证一年以后","在你 21 岁生日那天","在你 25 岁生日那天"],"h1":"看看驾照上印的字。","h2":"在 Minnesota，标有 \"Under 21\" 的驾照在你 21 岁生日那天过期，以后每四年在你生日那天过期。","p":"对。它在你 21 岁生日那天过期。"},"vi":{"q":"Ở Minnesota, bằng lái có ghi \"Under 21\" (dưới 21 tuổi) hết hạn khi nào?","o":["Vào sinh nhật thứ 18 của bạn","Một năm sau khi được cấp","Vào sinh nhật thứ 21 của bạn","Vào sinh nhật thứ 25 của bạn"],"h1":"Hãy nhìn chữ in trên bằng lái.","h2":"Ở Minnesota, bằng lái có ghi \"Under 21\" hết hạn vào sinh nhật thứ 21 của bạn, và sau đó hết hạn mỗi bốn năm vào ngày sinh nhật của bạn.","p":"Đúng. Bằng lái hết hạn vào sinh nhật thứ 21 của bạn."},"tl":{"q":"Sa Minnesota, kailan mag-e-expire ang driver's license na may markang \"Under 21\" (wala pang 21)?","o":["Sa ika-18 kaarawan mo","Isang taon pagkatapos itong ibigay","Sa ika-21 kaarawan mo","Sa ika-25 kaarawan mo"],"h1":"Tingnan ang mga salitang nakalimbag sa lisensya.","h2":"Sa Minnesota, ang lisensyang may markang \"Under 21\" ay mag-e-expire sa ika-21 kaarawan mo, at pagkatapos noon ay mag-e-expire ito tuwing apat na taon sa kaarawan mo.","p":"Tama. Mag-e-expire ito sa ika-21 kaarawan mo."},"ar":{"q":"في Minnesota، متى تنتهي صلاحية رخصة القيادة المكتوب عليها \"Under 21\" (أقل من 21)؟","o":["في عيد ميلادك الـ 18","بعد سنة من إصدارها","في عيد ميلادك الـ 21","في عيد ميلادك الـ 25"],"h1":"انظر إلى الكلمات المطبوعة على الرخصة.","h2":"في Minnesota تنتهي صلاحية الرخصة المكتوب عليها \"Under 21\" في عيد ميلادك الـ 21، وبعد ذلك تنتهي صلاحيتها كل أربع سنوات في عيد ميلادك.","p":"صحيح. تنتهي صلاحيتها في عيد ميلادك الـ 21."},"ref":{"doc":"MN","page":16}},{"id":"mn-032","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, you just became a resident and have a valid car license from another state. How long do you have to get a Minnesota license?","o":["30 days","60 days","90 days","1 year"],"h1":"It is more than one month but less than three.","h2":"A new Minnesota resident with a valid license from another state has 60 days to get a Minnesota license.","p":"Right. New residents have 60 days."},"es":{"q":"En Minnesota, usted acaba de hacerse residente y tiene una licencia de auto válida de otro estado. ¿Cuánto tiempo tiene para sacar una licencia de Minnesota?","o":["30 días","60 días","90 días","1 año"],"h1":"Es más de un mes, pero menos de tres.","h2":"Un nuevo residente de Minnesota con una licencia válida de otro estado tiene 60 días para sacar una licencia de Minnesota.","p":"Correcto. Los nuevos residentes tienen 60 días."},"ref":{"doc":"MN","page":6}},{"id":"mn-033","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, how long is an instruction permit valid?","o":["6 months","1 year","4 years","2 years"],"h1":"It gives you more than one year to practice.","h2":"A Minnesota instruction permit is valid for two years of practice driving with a supervising driver.","p":"Right. The permit lasts two years."},"es":{"q":"En Minnesota, ¿por cuánto tiempo es válido un permiso de aprendizaje (instruction permit)?","o":["6 meses","1 año","4 años","2 años"],"h1":"Le da más de un año para practicar.","h2":"Un permiso de aprendizaje de Minnesota es válido por dos años de práctica con un conductor supervisor.","p":"Correcto. El permiso dura dos años."},"ref":{"doc":"MN","page":13}},{"id":"mn-034","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, you move to a new address. How soon must you apply for a duplicate license?","o":["Within 30 days","Within 90 days","Within 1 year","At your next renewal"],"h1":"Do not wait for your renewal. The time is short.","h2":"In Minnesota, if you change your name or address, you must apply for a duplicate license within 30 days.","p":"Right. Apply within 30 days."},"es":{"q":"En Minnesota, usted se muda a una nueva dirección. ¿En cuánto tiempo debe solicitar una licencia duplicada?","o":["Dentro de 30 días","Dentro de 90 días","Dentro de 1 año","En su próxima renovación"],"h1":"No espere a la renovación. El plazo es corto.","h2":"En Minnesota, si cambia de nombre o de dirección, debe solicitar una licencia duplicada dentro de 30 días.","p":"Correcto. Solicítela dentro de 30 días."},"ref":{"doc":"MN","page":19}},{"id":"mn-035","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, after a crash, an officer asks for your insurance information, but you do not have it with you. How soon must you give it?","o":["Within 24 hours","Within 30 days","Within 72 hours","Within 10 days"],"h1":"It is a few days, not weeks.","h2":"After a crash in Minnesota, if you do not have your insurance information with you, you must provide it within 72 hours.","p":"Right. You have 72 hours."},"es":{"q":"En Minnesota, después de un choque, un oficial le pide la información de su seguro, pero usted no la tiene consigo. ¿En cuánto tiempo debe darla?","o":["Dentro de 24 horas","Dentro de 30 días","Dentro de 72 horas","Dentro de 10 días"],"h1":"Son unos pocos días, no semanas.","h2":"Después de un choque en Minnesota, si no tiene consigo la información de su seguro, debe entregarla dentro de 72 horas.","p":"Correcto. Tiene 72 horas."},"ref":{"doc":"MN","page":39}},{"id":"mn-036","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, what must you do after you fail the road test four times?","o":["Wait one full year before testing again","Take at least 6 hours of lessons with a licensed instructor","Ride with a police officer for one day","Pay a $500 retest fee"],"h1":"Think about what would help you drive better.","h2":"In Minnesota, after four failed road tests you must take at least six hours of behind-the-wheel lessons with a licensed instructor before you test again.","p":"Right. Six hours of lessons come first."},"es":{"q":"En Minnesota, ¿qué debe hacer después de reprobar el examen de manejo cuatro veces?","o":["Esperar un año completo antes de volver a intentarlo","Tomar por lo menos 6 horas de clases con un instructor con licencia","Viajar con un policía durante un día","Pagar $500 por volver a tomar el examen"],"h1":"Piense en lo que le ayudaría a manejar mejor.","h2":"En Minnesota, después de reprobar el examen de manejo cuatro veces, debe tomar por lo menos seis horas de clases al volante con un instructor con licencia antes de volver a intentarlo.","p":"Correcto. Primero vienen seis horas de clases."},"ref":{"doc":"MN","page":12}},{"id":"mn-037","scope":"MN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Minnesota, you are stranded in your car during a winter storm. What is the safest thing to do?","o":["Walk to the nearest house for help","Keep the engine running with all windows shut","Leave the car to look for the main road","Stay with your vehicle and wait for help"],"h1":"Most deaths happen when people get lost out in the cold.","h2":"If you are stranded in cold weather in Minnesota, stay with your vehicle and wait for help, because most deaths happen when people leave their cars and get lost.","p":"Right. Stay with your car."},"es":{"q":"En Minnesota, usted queda atrapado en su auto durante una tormenta de invierno. ¿Qué es lo más seguro?","o":["Caminar a la casa más cercana para pedir ayuda","Dejar el motor encendido con todas las ventanas cerradas","Salir del auto para buscar la carretera principal","Quedarse en su vehículo y esperar ayuda"],"h1":"La mayoría de las muertes ocurren cuando la gente se pierde en el frío.","h2":"Si queda atrapado en el frío en Minnesota, quédese en su vehículo y espere ayuda, porque la mayoría de las muertes ocurren cuando la gente deja el auto y se pierde.","p":"Correcto. Quédese en su auto."},"ref":{"doc":"MN","page":82}},{"id":"mn-038","scope":"MN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Minnesota, you are stranded in a cold car. How long should you run the engine and heater?","o":["About 10 minutes each hour","Nonstop until help comes","About 1 minute each hour","Never, keep it off the whole time"],"h1":"Run it long enough to warm up and charge the battery, then turn it off.","h2":"When you are stranded in the cold, run the engine about 10 minutes each hour, keep the exhaust pipe clear of snow and leave a window open a little.","p":"Right. About 10 minutes each hour."},"es":{"q":"En Minnesota, usted está atrapado en un auto frío. ¿Cuánto tiempo debe encender el motor y la calefacción?","o":["Unos 10 minutos cada hora","Sin parar hasta que llegue ayuda","Como 1 minuto cada hora","Nunca, debe dejarlo apagado todo el tiempo"],"h1":"Enciéndalo lo suficiente para calentarse y cargar la batería, y luego apáguelo.","h2":"Cuando está atrapado en el frío, encienda el motor unos 10 minutos cada hora, mantenga el tubo de escape libre de nieve y deje una ventana un poco abierta.","p":"Correcto. Unos 10 minutos cada hora."},"ref":{"doc":"MN","page":82}},{"id":"mn-039","scope":"MN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Minnesota, which flashing lights warn you that a snowplow is ahead?","o":["Green only","Red and green","White, yellow and blue","Purple only"],"h1":"Snowplows may use a color that police cars use too.","h2":"In Minnesota, snowplows use flashing white, yellow and blue lights, so watch for them when roads have snow or ice.","p":"Right. White, yellow and blue mean a snowplow."},"es":{"q":"En Minnesota, ¿qué luces intermitentes le avisan que hay un quitanieves adelante?","o":["Solo verdes","Rojas y verdes","Blancas, amarillas y azules","Solo moradas"],"h1":"Los quitanieves pueden usar un color que también usan los autos de policía.","h2":"En Minnesota, los quitanieves usan luces intermitentes blancas, amarillas y azules, así que búsquelas cuando hay nieve o hielo en la carretera.","p":"Correcto. Blancas, amarillas y azules indican un quitanieves."},"ref":{"doc":"MN","page":81}},{"id":"mn-040","scope":"MN","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Minnesota, you are using high beams at night. How close can an oncoming car get before you must switch to low beams?","o":["Within 500 feet","Within 1,000 feet","Within 200 feet","Within 2,000 feet"],"h1":"It is a long distance, more than three football fields.","h2":"In Minnesota you must use low beams when you are within 1,000 feet of an oncoming vehicle.","p":"Right. Dim your lights within 1,000 feet."},"es":{"q":"En Minnesota, usted usa las luces altas de noche. ¿Qué tan cerca puede estar un auto que viene de frente antes de que deba cambiar a luces bajas?","o":["A menos de 500 pies","A menos de 1,000 pies","A menos de 200 pies","A menos de 2,000 pies"],"h1":"Es una distancia larga, más de tres campos de fútbol americano.","h2":"En Minnesota debe usar las luces bajas cuando está a menos de 1,000 pies de un vehículo que viene de frente.","p":"Correcto. Baje las luces a menos de 1,000 pies."},"ref":{"doc":"MN","page":73}},{"id":"mn-041","scope":"MN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Minnesota, you are following another car at night. How close can you get before you must use low beams?","o":["Within 50 feet","Within 500 feet","Within 1,000 feet","Within 200 feet"],"h1":"It is a shorter distance than the rule for oncoming cars.","h2":"In Minnesota you must use low beams when you follow another vehicle at 200 feet or less.","p":"Right. Use low beams within 200 feet."},"es":{"q":"En Minnesota, usted va detrás de otro auto de noche. ¿Qué tan cerca puede estar antes de que deba usar las luces bajas?","o":["A menos de 50 pies","A menos de 500 pies","A menos de 1,000 pies","A menos de 200 pies"],"h1":"Es una distancia más corta que la regla para autos que vienen de frente.","h2":"En Minnesota debe usar las luces bajas cuando sigue a otro vehículo a 200 pies o menos.","p":"Correcto. Use luces bajas a menos de 200 pies."},"ref":{"doc":"MN","page":73}},{"id":"mn-042","scope":"MN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Minnesota, on a two-lane highway with a 55 mph speed limit, how much faster may you go while lawfully passing another vehicle?","o":["Up to 10 mph over the limit","Up to 20 mph over the limit","Up to 5 mph over the limit","Not even 1 mph over the limit"],"h1":"Minnesota gives a small extra margin to finish the pass quickly.","h2":"On a Minnesota two-lane highway with a speed limit of 55 mph or more, the limit goes up by 10 mph while you are lawfully passing.","p":"Right. Up to 10 mph more while passing."},"es":{"q":"En Minnesota, en una carretera de dos carriles con límite de 55 mph, ¿cuánto más rápido puede ir mientras rebasa legalmente a otro vehículo?","o":["Hasta 10 mph sobre el límite","Hasta 20 mph sobre el límite","Hasta 5 mph sobre el límite","Ni 1 mph sobre el límite"],"h1":"Minnesota da un pequeño margen extra para terminar de rebasar rápido.","h2":"En una carretera de dos carriles de Minnesota con límite de 55 mph o más, el límite sube 10 mph mientras usted rebasa legalmente.","p":"Correcto. Hasta 10 mph más mientras rebasa."},"ref":{"doc":"MN","page":34}},{"id":"mn-043","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, what happens if you drive faster than 100 mph?","o":["You get a warning letter only","You pay a $50 fine only","Your license is revoked for at least six months","You get two points and no fine"],"h1":"This is one of the most serious speeding offenses.","h2":"In Minnesota, if you drive over 100 mph, your driving privileges are revoked for at least six months.","p":"Right. Over 100 mph means losing your license for at least six months."},"es":{"q":"En Minnesota, ¿qué pasa si maneja a más de 100 mph?","o":["Solo recibe una carta de advertencia","Solo paga una multa de $50","Le revocan la licencia por lo menos seis meses","Recibe dos puntos y ninguna multa"],"h1":"Es una de las faltas de velocidad más graves.","h2":"En Minnesota, si maneja a más de 100 mph, le revocan el privilegio de manejar por lo menos seis meses.","p":"Correcto. Más de 100 mph significa perder la licencia por lo menos seis meses."},"ref":{"doc":"MN","page":27}},{"id":"mn-044","scope":"MN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Minnesota, you speed in a work zone while workers are present. What extra fine do you face?","o":["$25","$50","$100","$300"],"h1":"It is a big fine, because workers are very close to traffic.","h2":"In Minnesota, speeding in a work zone when workers are present brings a $300 fine on top of the regular speeding ticket.","p":"Right. It costs an extra $300."},"es":{"q":"En Minnesota, usted va con exceso de velocidad en una zona de obras mientras hay trabajadores. ¿Qué multa extra puede recibir?","o":["$25","$50","$100","$300"],"h1":"Es una multa grande, porque los trabajadores están muy cerca del tráfico.","h2":"En Minnesota, ir con exceso de velocidad en una zona de obras cuando hay trabajadores trae una multa de $300 además de la multa normal por velocidad.","p":"Correcto. Cuesta $300 extra."},"ref":{"doc":"MN","page":54}},{"id":"mn-045","scope":"MN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Minnesota, what is the smallest fine for not stopping for a school bus with its red lights flashing?","o":["$100","$500","$50","$250"],"h1":"The fine is high because children's lives are at risk.","h2":"In Minnesota, if you are convicted of not stopping for a school bus with red lights flashing, the fine is at least $500 and you lose your driving privileges.","p":"Right. The fine is at least $500."},"es":{"q":"En Minnesota, ¿cuál es la multa mínima por no parar ante un autobús escolar con las luces rojas intermitentes?","o":["$100","$500","$50","$250"],"h1":"La multa es alta porque la vida de los niños está en riesgo.","h2":"En Minnesota, si lo declaran culpable de no parar ante un autobús escolar con luces rojas intermitentes, la multa es de por lo menos $500 y pierde el privilegio de manejar.","p":"Correcto. La multa es de por lo menos $500."},"ref":{"doc":"MN","page":42}},{"id":"mn-046","scope":"MN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Minnesota, when may you pass a school bus on its right side?","o":["Never while its yellow or red lights are flashing","Any time its stop arm is folded in","Whenever only its yellow lights are flashing","When no children are in sight"],"h1":"Children may be getting on or off on that side.","h2":"In Minnesota it is against the law to pass a school bus on the right while it shows flashing yellow or red lights.","p":"Right. Never pass on the right while the lights flash."},"es":{"q":"En Minnesota, ¿cuándo puede rebasar a un autobús escolar por su lado derecho?","o":["Nunca mientras tenga las luces amarillas o rojas intermitentes","Siempre que el brazo de alto esté recogido","Cuando solo tenga las luces amarillas intermitentes","Cuando no se vean niños"],"h1":"Puede haber niños subiendo o bajando por ese lado.","h2":"En Minnesota es ilegal rebasar a un autobús escolar por la derecha mientras tiene luces amarillas o rojas intermitentes.","p":"Correcto. Nunca rebase por la derecha mientras las luces parpadean."},"ref":{"doc":"MN","page":41}},{"id":"mn-047","scope":"MN","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Minnesota, a fire truck is on an emergency run. How far behind it must you stay?","o":["At least 50 feet","At least 100 feet","At least 500 feet","At least 1 mile"],"h1":"It is more than the length of a city block.","h2":"In Minnesota, only vehicles on official emergency business may follow within 500 feet of a firefighting vehicle on an emergency run.","p":"Right. Stay at least 500 feet back."},"es":{"q":"En Minnesota, un camión de bomberos va a una emergencia. ¿A qué distancia detrás de él debe mantenerse?","o":["Por lo menos 50 pies","Por lo menos 100 pies","Por lo menos 500 pies","Por lo menos 1 milla"],"h1":"Es más que el largo de una cuadra de la ciudad.","h2":"En Minnesota, solo los vehículos en servicio oficial de emergencia pueden seguir a menos de 500 pies a un vehículo de bomberos que va a una emergencia.","p":"Correcto. Manténgase por lo menos a 500 pies."},"ref":{"doc":"MN","page":44}},{"id":"mn-048","scope":"MN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Minnesota, how close to a stop sign may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 15 feet","No closer than 30 feet"],"h1":"Other drivers need to see the sign from far away.","h2":"In Minnesota you may not park within 30 feet of a stop sign, flashing light or traffic signal on the side of the road.","p":"Right. Park at least 30 feet away."},"es":{"q":"En Minnesota, ¿qué tan cerca de una señal de alto puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 15 pies","No más cerca de 30 pies"],"h1":"Los otros conductores necesitan ver la señal desde lejos.","h2":"En Minnesota no puede estacionarse a menos de 30 pies de una señal de alto, una luz intermitente o un semáforo al lado de la calle.","p":"Correcto. Estaciónese por lo menos a 30 pies."},"ref":{"doc":"MN","page":35}},{"id":"mn-049","scope":"MN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Minnesota, the lights are flashing at a railroad crossing. How far from the nearest rail or gate must you stop?","o":["At least 10 feet","At least 2 feet","At least 100 feet","At least 300 feet"],"h1":"It is a short distance, a little less than one car length.","h2":"In Minnesota, when the lights or gates at a railroad crossing are working, you must stop at least 10 feet from the nearest rail or gate.","p":"Right. Stop at least 10 feet away."},"es":{"q":"En Minnesota, las luces de un cruce de tren están parpadeando. ¿A qué distancia del riel o de la barrera más cercana debe parar?","o":["Por lo menos 10 pies","Por lo menos 2 pies","Por lo menos 100 pies","Por lo menos 300 pies"],"h1":"Es una distancia corta, un poco menos que el largo de un auto.","h2":"En Minnesota, cuando las luces o las barreras de un cruce de tren están funcionando, debe parar por lo menos a 10 pies del riel o de la barrera más cercana.","p":"Correcto. Pare por lo menos a 10 pies."},"ref":{"doc":"MN","page":53}},{"id":"mn-050","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, a driver under 21 is convicted for the first time of driving with any alcohol in their body. How long is the license suspended?","o":["7 days","1 year","30 days","180 days"],"h1":"It is about one month. A second conviction brings a much longer suspension.","h2":"In Minnesota, a first conviction for a driver under 21 who drives with any alcohol means a 30-day suspension, and a second means 180 days.","p":"Right. The first time, it is 30 days."},"es":{"q":"En Minnesota, un conductor menor de 21 es declarado culpable por primera vez de manejar con cualquier cantidad de alcohol en el cuerpo. ¿Por cuánto tiempo le suspenden la licencia?","o":["7 días","1 año","30 días","180 días"],"h1":"Es como un mes. Una segunda condena trae una suspensión mucho más larga.","h2":"En Minnesota, la primera condena de un conductor menor de 21 que maneja con cualquier cantidad de alcohol significa 30 días de suspensión, y la segunda, 180 días.","p":"Correcto. La primera vez son 30 días."},"ref":{"doc":"MN","page":95}},{"id":"mn-051","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, an officer has good reason to believe you are driving impaired and asks for a blood, breath or urine test. What happens if you refuse?","o":["Nothing, because the test is optional","It is a crime, and your license is revoked","You only get a warning the first time","You pay a small fine and keep your license"],"h1":"Minnesota's implied consent law treats refusing very seriously.","h2":"In Minnesota, refusing a lawful blood, breath or urine test is a crime and leads to a license revocation of one to six years.","p":"Right. Refusing is a crime and costs you your license."},"es":{"q":"En Minnesota, un oficial tiene buenas razones para creer que usted maneja bajo los efectos del alcohol o drogas y le pide una prueba de sangre, aliento u orina. ¿Qué pasa si se niega?","o":["Nada, porque la prueba es opcional","Es un delito y le revocan la licencia","Solo recibe una advertencia la primera vez","Paga una multa pequeña y conserva su licencia"],"h1":"La ley de consentimiento implícito de Minnesota trata la negativa con mucha seriedad.","h2":"En Minnesota, negarse a una prueba legal de sangre, aliento u orina es un delito y lleva a una revocación de la licencia de uno a seis años.","p":"Correcto. Negarse es un delito y le cuesta la licencia."},"ref":{"doc":"MN","page":93}},{"id":"mo-001","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","16 years old","15 and a half years old"],"h1":"It is one year before the intermediate license.","h2":"You can get a Missouri instruction permit at 15, one year before you can apply for an intermediate license at 16.","p":"Right. The Missouri permit starts at 15."},"es":{"q":"En Missouri, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["14 años","15 años","16 años","15 años y medio"],"h1":"Es un año antes de la licencia intermedia.","h2":"Usted puede obtener el permiso de instrucción en Missouri a los 15 años, un año antes de poder solicitar la licencia intermedia a los 16.","p":"Correcto. El permiso en Missouri empieza a los 15."},"zh":{"q":"在 Missouri，最小几岁可以拿到学习驾照（instruction permit）？","o":["14 岁","15 岁","16 岁","15 岁半"],"h1":"它比中级驾照早一年。","h2":"你 15 岁就可以拿到 Missouri 的学习驾照，比 16 岁可以申请的中级驾照早一年。","p":"对。Missouri 的学习驾照从 15 岁开始。"},"vi":{"q":"Ở Missouri, tuổi nhỏ nhất để lấy giấy phép tập lái (instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","15 tuổi rưỡi"],"h1":"Đó là một năm trước bằng lái trung gian.","h2":"Bạn có thể lấy giấy phép tập lái ở Missouri khi 15 tuổi, một năm trước khi bạn có thể xin bằng lái trung gian (intermediate license) lúc 16 tuổi.","p":"Đúng. Ở Missouri, giấy phép tập lái bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Missouri, ano ang pinakabatang edad para makakuha ng instruction permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","15 at kalahating taong gulang"],"h1":"Isang taon ito bago ang intermediate license.","h2":"Puwede kang kumuha ng instruction permit sa Missouri sa edad na 15, isang taon bago ka puwedeng mag-apply ng intermediate license sa edad na 16.","p":"Tama. Nagsisimula ang permit sa Missouri sa 15."},"ar":{"q":"في Missouri، ما أصغر عمر للحصول على تصريح التعلّم (instruction permit)؟","o":["14 سنة","15 سنة","16 سنة","15 سنة ونصف"],"h1":"هو سنة واحدة قبل الرخصة المتوسطة.","h2":"يمكنك الحصول على تصريح التعلّم في Missouri في عمر 15 سنة، أي قبل سنة من إمكانية التقديم على الرخصة المتوسطة (intermediate license) في عمر 16 سنة.","p":"صحيح. في Missouri يبدأ التصريح في عمر 15 سنة."},"ref":{"doc":"MO","page":3}},{"id":"mo-002","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, how long must a teen hold an instruction permit before getting an intermediate license?","o":["30 days","90 days","At least 182 days, about six months","One full year"],"h1":"It is about half a year.","h2":"A Missouri teen must hold the instruction permit for at least 182 days, about six months, before applying for an intermediate license.","p":"Right. The permit must be held about six months."},"es":{"q":"En Missouri, ¿cuánto tiempo debe tener un adolescente el permiso de instrucción antes de obtener la licencia intermedia?","o":["30 días","90 días","Por lo menos 182 días, unos seis meses","Un año completo"],"h1":"Es más o menos medio año.","h2":"Un adolescente en Missouri debe tener el permiso de instrucción por lo menos 182 días, unos seis meses, antes de solicitar la licencia intermedia.","p":"Correcto. El permiso se debe tener unos seis meses."},"zh":{"q":"在 Missouri，青少年必须持有学习驾照多久，才能拿到中级驾照？","o":["30 天","90 天","至少 182 天，大约六个月","整整一年"],"h1":"大约半年。","h2":"Missouri 的青少年必须持有学习驾照至少 182 天，大约六个月，才能申请中级驾照。","p":"对。学习驾照必须持有大约六个月。"},"vi":{"q":"Ở Missouri, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái trung gian (intermediate license)?","o":["30 ngày","90 ngày","Ít nhất 182 ngày, khoảng sáu tháng","Một năm đầy đủ"],"h1":"Đó là khoảng nửa năm.","h2":"Thiếu niên ở Missouri phải giữ giấy phép tập lái ít nhất 182 ngày, khoảng sáu tháng, trước khi xin bằng lái trung gian.","p":"Đúng. Phải giữ giấy phép tập lái khoảng sáu tháng."},"tl":{"q":"Sa Missouri, gaano katagal dapat hawak ng isang tinedyer ang instruction permit bago makakuha ng intermediate license?","o":["30 araw","90 araw","Hindi bababa sa 182 araw, mga anim na buwan","Isang buong taon"],"h1":"Mga kalahating taon ito.","h2":"Ang isang tinedyer sa Missouri ay dapat humawak ng instruction permit nang hindi bababa sa 182 araw, mga anim na buwan, bago mag-apply ng intermediate license.","p":"Tama. Dapat hawak ang permit nang mga anim na buwan."},"ar":{"q":"في Missouri، كم يجب أن يحمل المراهق تصريح التعلّم قبل الحصول على الرخصة المتوسطة (intermediate license)؟","o":["30 يومًا","90 يومًا","182 يومًا على الأقل، أي نحو ستة أشهر","سنة كاملة"],"h1":"هي نحو نصف سنة.","h2":"يجب على المراهق في Missouri أن يحمل تصريح التعلّم 182 يومًا على الأقل، أي نحو ستة أشهر، قبل التقديم على الرخصة المتوسطة.","p":"صحيح. يجب حمل التصريح نحو ستة أشهر."},"ref":{"doc":"MO","page":16}},{"id":"mo-003","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, how many hours of driving instruction must a teen complete before an intermediate license?","o":["40 hours","20 hours","50 hours","60 hours"],"h1":"It is less than fifty.","h2":"A Missouri teen must complete 40 hours of driving instruction with a qualified person before getting an intermediate license.","p":"Right. Missouri asks for 40 hours of driving instruction."},"es":{"q":"En Missouri, ¿cuántas horas de instrucción de manejo debe completar un adolescente antes de la licencia intermedia?","o":["40 horas","20 horas","50 horas","60 horas"],"h1":"Es menos de cincuenta.","h2":"Un adolescente en Missouri debe completar 40 horas de instrucción de manejo con una persona calificada antes de obtener la licencia intermedia.","p":"Correcto. Missouri pide 40 horas de instrucción de manejo."},"zh":{"q":"在 Missouri，青少年拿中级驾照前必须完成多少小时的驾驶指导？","o":["40 小时","20 小时","50 小时","60 小时"],"h1":"它少于五十。","h2":"Missouri 的青少年拿中级驾照前，必须和合格的人一起完成 40 小时的驾驶指导。","p":"对。Missouri 要求 40 小时的驾驶指导。"},"vi":{"q":"Ở Missouri, thiếu niên phải hoàn thành bao nhiêu giờ tập lái trước khi lấy bằng lái trung gian?","o":["40 giờ","20 giờ","50 giờ","60 giờ"],"h1":"Đó là ít hơn năm mươi.","h2":"Thiếu niên ở Missouri phải hoàn thành 40 giờ tập lái với một người đủ điều kiện trước khi lấy bằng lái trung gian.","p":"Đúng. Missouri yêu cầu 40 giờ tập lái."},"tl":{"q":"Sa Missouri, ilang oras ng pagsasanay sa pagmamaneho ang dapat tapusin ng isang tinedyer bago ang intermediate license?","o":["40 oras","20 oras","50 oras","60 oras"],"h1":"Mas kaunti ito sa limampu.","h2":"Ang isang tinedyer sa Missouri ay dapat tumapos ng 40 oras ng pagsasanay sa pagmamaneho kasama ang isang kwalipikadong tao bago makakuha ng intermediate license.","p":"Tama. Humihingi ang Missouri ng 40 oras ng pagsasanay sa pagmamaneho."},"ar":{"q":"في Missouri، كم ساعة من التدريب على القيادة يجب أن يكملها المراهق قبل الرخصة المتوسطة؟","o":["40 ساعة","20 ساعة","50 ساعة","60 ساعة"],"h1":"هي أقل من خمسين.","h2":"يجب على المراهق في Missouri أن يكمل 40 ساعة من التدريب على القيادة مع شخص مؤهَّل قبل الحصول على الرخصة المتوسطة.","p":"صحيح. تطلب Missouri 40 ساعة من التدريب على القيادة."},"ref":{"doc":"MO","page":16}},{"id":"mo-004","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, how many of the 40 required practice hours must be at night?","o":["At least 2 hours","At least 5 hours","At least 20 hours","At least 10 hours"],"h1":"It is one quarter of the total.","h2":"At least 10 of Missouri's 40 required hours of driving instruction must be driven at night.","p":"Right. At least 10 of the hours must be at night."},"es":{"q":"En Missouri, ¿cuántas de las 40 horas de práctica exigidas deben ser de noche?","o":["Por lo menos 2 horas","Por lo menos 5 horas","Por lo menos 20 horas","Por lo menos 10 horas"],"h1":"Es la cuarta parte del total.","h2":"Por lo menos 10 de las 40 horas de instrucción exigidas en Missouri deben ser de noche.","p":"Correcto. Por lo menos 10 de las horas deben ser de noche."},"zh":{"q":"在 Missouri，规定的 40 小时练习中，有多少小时必须在晚上？","o":["至少 2 小时","至少 5 小时","至少 20 小时","至少 10 小时"],"h1":"是总数的四分之一。","h2":"Missouri 规定的 40 小时驾驶指导中，至少 10 小时必须在晚上开。","p":"对。至少 10 小时必须在晚上。"},"vi":{"q":"Ở Missouri, trong 40 giờ tập lái bắt buộc, bao nhiêu giờ phải lái vào ban đêm?","o":["Ít nhất 2 giờ","Ít nhất 5 giờ","Ít nhất 20 giờ","Ít nhất 10 giờ"],"h1":"Đó là một phần tư của tổng số.","h2":"Ở Missouri, ít nhất 10 trong 40 giờ tập lái bắt buộc phải lái vào ban đêm.","p":"Đúng. Ít nhất 10 giờ phải lái vào ban đêm."},"tl":{"q":"Sa Missouri, ilan sa 40 kinakailangang oras ng pagsasanay ang dapat sa gabi?","o":["Hindi bababa sa 2 oras","Hindi bababa sa 5 oras","Hindi bababa sa 20 oras","Hindi bababa sa 10 oras"],"h1":"Isang-kapat ito ng kabuuan.","h2":"Hindi bababa sa 10 sa 40 kinakailangang oras ng pagsasanay sa Missouri ang dapat imaneho sa gabi.","p":"Tama. Hindi bababa sa 10 oras ang dapat sa gabi."},"ar":{"q":"في Missouri، كم ساعة من ساعات التدريب الـ 40 المطلوبة يجب أن تكون في الليل؟","o":["ساعتان على الأقل (2)","5 ساعات على الأقل","20 ساعة على الأقل","10 ساعات على الأقل"],"h1":"هي ربع المجموع.","h2":"يجب أن تكون 10 ساعات على الأقل من ساعات التدريب الـ 40 المطلوبة في Missouri قيادةً في الليل.","p":"صحيح. يجب أن تكون 10 ساعات على الأقل في الليل."},"ref":{"doc":"MO","page":16}},{"id":"mo-005","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, during which hours may a driver with an intermediate license not drive alone?","o":["Midnight to 6 a.m.","1 a.m. to 5 a.m.","11 p.m. to 5 a.m.","10 p.m. to 6 a.m."],"h1":"The limit starts one hour after midnight.","h2":"A Missouri intermediate license holder may not drive alone from 1 a.m. to 5 a.m., the late night curfew for new drivers.","p":"Right. The curfew is 1 a.m. to 5 a.m."},"es":{"q":"En Missouri, ¿en qué horario no puede manejar solo un conductor con licencia intermedia?","o":["De medianoche a 6 a.m.","De 1 a.m. a 5 a.m.","De 11 p.m. a 5 a.m.","De 10 p.m. a 6 a.m."],"h1":"El límite empieza una hora después de la medianoche.","h2":"Quien tiene licencia intermedia en Missouri no puede manejar solo de 1 a.m. a 5 a.m., el toque de queda nocturno para conductores nuevos.","p":"Correcto. El toque de queda es de 1 a.m. a 5 a.m."},"zh":{"q":"在 Missouri，持中级驾照的司机在哪段时间不能单独开车？","o":["午夜到早上 6 点","凌晨 1 点到早上 5 点","晚上 11 点到早上 5 点","晚上 10 点到早上 6 点"],"h1":"限制从午夜后一个小时开始。","h2":"Missouri 持中级驾照的人在凌晨 1 点到早上 5 点不能单独开车，这是新司机的深夜宵禁。","p":"对。宵禁是凌晨 1 点到早上 5 点。"},"vi":{"q":"Ở Missouri, người có bằng lái trung gian không được lái một mình trong những giờ nào?","o":["Từ nửa đêm đến 6 giờ sáng","Từ 1 giờ sáng đến 5 giờ sáng","Từ 11 giờ tối đến 5 giờ sáng","Từ 10 giờ tối đến 6 giờ sáng"],"h1":"Giới hạn bắt đầu một giờ sau nửa đêm.","h2":"Ở Missouri, người có bằng lái trung gian không được lái một mình từ 1 giờ sáng đến 5 giờ sáng, đó là giờ giới nghiêm ban đêm cho tài xế mới.","p":"Đúng. Giờ giới nghiêm là từ 1 giờ sáng đến 5 giờ sáng."},"tl":{"q":"Sa Missouri, sa anong mga oras hindi puwedeng magmaneho nang mag-isa ang may intermediate license?","o":["Hatinggabi hanggang 6 a.m.","1 a.m. hanggang 5 a.m.","11 p.m. hanggang 5 a.m.","10 p.m. hanggang 6 a.m."],"h1":"Nagsisimula ang limitasyon isang oras pagkatapos ng hatinggabi.","h2":"Ang may intermediate license sa Missouri ay hindi puwedeng magmaneho nang mag-isa mula 1 a.m. hanggang 5 a.m., ang curfew sa hatinggabi para sa mga bagong driver.","p":"Tama. Ang curfew ay 1 a.m. hanggang 5 a.m."},"ar":{"q":"في Missouri، في أي ساعات لا يجوز لمن يحمل الرخصة المتوسطة أن يقود وحده؟","o":["من منتصف الليل إلى 6 صباحًا","من 1 صباحًا إلى 5 صباحًا","من 11 مساءً إلى 5 صباحًا","من 10 مساءً إلى 6 صباحًا"],"h1":"يبدأ المنع بعد منتصف الليل بساعة.","h2":"لا يجوز لمن يحمل الرخصة المتوسطة في Missouri أن يقود وحده من 1 صباحًا إلى 5 صباحًا، وهو حظر التجوّل الليلي للسائقين الجدد.","p":"صحيح. حظر التجوّل من 1 صباحًا إلى 5 صباحًا."},"ref":{"doc":"MO","page":16}},{"id":"mo-006","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, during the first six months of an intermediate license, how many passengers under 19 who are not family may ride with the driver?","o":["None","Three","One","Two"],"h1":"The limit is as small as it can be without being zero.","h2":"In the first six months, a Missouri intermediate driver may carry no more than one passenger under 19 who is not immediate family.","p":"Right. Only one non-family passenger under 19 at first."},"es":{"q":"En Missouri, durante los primeros seis meses de la licencia intermedia, ¿cuántos pasajeros menores de 19 años que no son familia pueden ir con el conductor?","o":["Ninguno","Tres","Uno","Dos"],"h1":"El límite es lo más pequeño posible sin ser cero.","h2":"En los primeros seis meses, un conductor con licencia intermedia en Missouri puede llevar como máximo un pasajero menor de 19 años que no sea familiar directo.","p":"Correcto. Al principio, solo un pasajero menor de 19 que no sea familia."},"zh":{"q":"在 Missouri，持中级驾照的前六个月，可以有多少位不是家人、19 岁以下的乘客坐车？","o":["一个都不行","三位","一位","两位"],"h1":"这个限制小到不能再小，但不是零。","h2":"在前六个月，Missouri 持中级驾照的司机最多只能载一位不是直系家人、19 岁以下的乘客。","p":"对。一开始只能载一位不是家人、19 岁以下的乘客。"},"vi":{"q":"Ở Missouri, trong sáu tháng đầu có bằng lái trung gian, bao nhiêu hành khách dưới 19 tuổi không phải người nhà được đi cùng tài xế?","o":["Không ai","Ba người","Một người","Hai người"],"h1":"Giới hạn nhỏ nhất có thể mà không phải là số không.","h2":"Trong sáu tháng đầu, tài xế có bằng lái trung gian ở Missouri chỉ được chở tối đa một hành khách dưới 19 tuổi không phải người nhà trực hệ.","p":"Đúng. Lúc đầu chỉ được một hành khách dưới 19 tuổi không phải người nhà."},"tl":{"q":"Sa Missouri, sa unang anim na buwan ng intermediate license, ilang pasaherong wala pang 19 taong gulang na hindi kapamilya ang puwedeng sumakay kasama ng driver?","o":["Wala","Tatlo","Isa","Dalawa"],"h1":"Pinakamaliit na limitasyon ito na hindi zero.","h2":"Sa unang anim na buwan, ang driver na may intermediate license sa Missouri ay puwedeng magsakay ng hindi hihigit sa isang pasaherong wala pang 19 taong gulang na hindi malapit na kapamilya.","p":"Tama. Isang pasaherong wala pang 19 na hindi kapamilya lang sa simula."},"ar":{"q":"في Missouri، في أول ستة أشهر من الرخصة المتوسطة، كم راكبًا عمره أقل من 19 سنة وليس من العائلة يمكن أن يركب مع السائق؟","o":["لا أحد","ثلاثة","واحد","اثنان"],"h1":"الحدّ صغير قدر الإمكان من غير أن يكون صفرًا.","h2":"في أول ستة أشهر، لا يجوز لسائق الرخصة المتوسطة في Missouri أن يحمل أكثر من راكب واحد عمره أقل من 19 سنة وليس من العائلة المباشرة.","p":"صحيح. في البداية راكب واحد فقط أقل من 19 سنة من خارج العائلة."},"ref":{"doc":"MO","page":16}},{"id":"mo-007","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, after the first six months of an intermediate license, how many passengers under 19 who are not family may ride with the driver?","o":["One","Two","Five","Three"],"h1":"The limit grows after six months, but it does not disappear.","h2":"After the first six months, a Missouri intermediate driver may carry no more than three passengers under 19 who are not immediate family.","p":"Right. After six months the limit is three."},"es":{"q":"En Missouri, después de los primeros seis meses de la licencia intermedia, ¿cuántos pasajeros menores de 19 años que no son familia pueden ir con el conductor?","o":["Uno","Dos","Cinco","Tres"],"h1":"El límite aumenta después de seis meses, pero no desaparece.","h2":"Después de los primeros seis meses, un conductor con licencia intermedia en Missouri puede llevar como máximo tres pasajeros menores de 19 años que no sean familiares directos.","p":"Correcto. Después de seis meses el límite es tres."},"zh":{"q":"在 Missouri，持中级驾照满六个月以后，可以有多少位不是家人、19 岁以下的乘客坐车？","o":["一位","两位","五位","三位"],"h1":"六个月以后限制放宽了，但没有取消。","h2":"前六个月以后，Missouri 持中级驾照的司机最多可以载三位不是直系家人、19 岁以下的乘客。","p":"对。六个月以后，限制是三位。"},"vi":{"q":"Ở Missouri, sau sáu tháng đầu có bằng lái trung gian, bao nhiêu hành khách dưới 19 tuổi không phải người nhà được đi cùng tài xế?","o":["Một người","Hai người","Năm người","Ba người"],"h1":"Giới hạn tăng lên sau sáu tháng, nhưng không mất đi.","h2":"Sau sáu tháng đầu, tài xế có bằng lái trung gian ở Missouri chỉ được chở tối đa ba hành khách dưới 19 tuổi không phải người nhà trực hệ.","p":"Đúng. Sau sáu tháng, giới hạn là ba người."},"tl":{"q":"Sa Missouri, pagkatapos ng unang anim na buwan ng intermediate license, ilang pasaherong wala pang 19 taong gulang na hindi kapamilya ang puwedeng sumakay kasama ng driver?","o":["Isa","Dalawa","Lima","Tatlo"],"h1":"Lumalaki ang limitasyon pagkatapos ng anim na buwan, pero hindi ito nawawala.","h2":"Pagkatapos ng unang anim na buwan, ang driver na may intermediate license sa Missouri ay puwedeng magsakay ng hindi hihigit sa tatlong pasaherong wala pang 19 taong gulang na hindi malapit na kapamilya.","p":"Tama. Pagkatapos ng anim na buwan, tatlo ang limitasyon."},"ar":{"q":"في Missouri، بعد أول ستة أشهر من الرخصة المتوسطة، كم راكبًا عمره أقل من 19 سنة وليس من العائلة يمكن أن يركب مع السائق؟","o":["واحد","اثنان","خمسة","ثلاثة"],"h1":"يكبر الحدّ بعد ستة أشهر، لكنه لا يختفي.","h2":"بعد أول ستة أشهر، لا يجوز لسائق الرخصة المتوسطة في Missouri أن يحمل أكثر من ثلاثة ركاب أعمارهم أقل من 19 سنة وليسوا من العائلة المباشرة.","p":"صحيح. بعد ستة أشهر يصبح الحدّ ثلاثة."},"ref":{"doc":"MO","page":16}},{"id":"mo-008","scope":"MO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Missouri, who must wear a seat belt when a driver has an intermediate license?","o":["The driver and every passenger","Only the driver","Only front seat riders","Only passengers under 16"],"h1":"The rule covers everyone in the car.","h2":"With a Missouri intermediate license, the driver and all passengers must wear seat belts.","p":"Right. Everyone in the car must buckle up."},"es":{"q":"En Missouri, ¿quién debe usar el cinturón de seguridad cuando el conductor tiene licencia intermedia?","o":["El conductor y todos los pasajeros","Solo el conductor","Solo los del asiento delantero","Solo los pasajeros menores de 16"],"h1":"La regla cubre a todos en el auto.","h2":"Con una licencia intermedia de Missouri, el conductor y todos los pasajeros deben usar el cinturón de seguridad.","p":"Correcto. Todos en el auto deben abrocharse el cinturón."},"zh":{"q":"在 Missouri，司机持中级驾照时，谁必须系安全带？","o":["司机和每一位乘客","只有司机","只有坐前排的人","只有 16 岁以下的乘客"],"h1":"这条规定包括车里的每个人。","h2":"持 Missouri 中级驾照时，司机和所有乘客都必须系安全带。","p":"对。车里每个人都必须系好安全带。"},"vi":{"q":"Ở Missouri, khi tài xế có bằng lái trung gian, ai phải thắt dây an toàn?","o":["Tài xế và mọi hành khách","Chỉ tài xế","Chỉ người ngồi ghế trước","Chỉ hành khách dưới 16 tuổi"],"h1":"Quy định áp dụng cho mọi người trong xe.","h2":"Với bằng lái trung gian ở Missouri, tài xế và tất cả hành khách phải thắt dây an toàn.","p":"Đúng. Mọi người trong xe phải thắt dây an toàn."},"tl":{"q":"Sa Missouri, sino ang dapat magsuot ng seat belt kapag ang driver ay may intermediate license?","o":["Ang driver at bawat pasahero","Ang driver lang","Ang mga nasa harapang upuan lang","Ang mga pasaherong wala pang 16 lang"],"h1":"Sakop ng patakaran ang lahat ng nasa sasakyan.","h2":"Kapag may intermediate license sa Missouri, ang driver at lahat ng pasahero ay dapat magsuot ng seat belt.","p":"Tama. Lahat ng nasa sasakyan ay dapat mag-seat belt."},"ar":{"q":"في Missouri، من يجب أن يربط حزام الأمان عندما يحمل السائق رخصة متوسطة؟","o":["السائق وكل راكب","السائق فقط","ركاب المقعد الأمامي فقط","الركاب الذين أعمارهم أقل من 16 سنة فقط"],"h1":"القاعدة تشمل كل من في السيارة.","h2":"مع الرخصة المتوسطة في Missouri، يجب على السائق وكل الركاب أن يربطوا أحزمة الأمان.","p":"صحيح. يجب على كل من في السيارة أن يربط الحزام."},"ref":{"doc":"MO","page":16}},{"id":"mo-009","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, how many questions are on the written test for a regular driver license?","o":["20 questions","30 questions","25 questions","40 questions"],"h1":"It is a quarter of one hundred.","h2":"The Missouri written test for a regular license has 25 multiple-choice questions.","p":"Right. The test has 25 questions."},"es":{"q":"En Missouri, ¿cuántas preguntas tiene el examen escrito para la licencia de conducir normal?","o":["20 preguntas","30 preguntas","25 preguntas","40 preguntas"],"h1":"Es la cuarta parte de cien.","h2":"El examen escrito de Missouri para la licencia normal tiene 25 preguntas de opción múltiple.","p":"Correcto. El examen tiene 25 preguntas."},"zh":{"q":"在 Missouri，普通驾照的笔试有多少道题？","o":["20 道题","30 道题","25 道题","40 道题"],"h1":"是一百的四分之一。","h2":"Missouri 普通驾照的笔试有 25 道选择题。","p":"对。笔试有 25 道题。"},"vi":{"q":"Ở Missouri, bài thi viết cho bằng lái thường có bao nhiêu câu hỏi?","o":["20 câu","30 câu","25 câu","40 câu"],"h1":"Đó là một phần tư của một trăm.","h2":"Bài thi viết ở Missouri cho bằng lái thường có 25 câu hỏi trắc nghiệm.","p":"Đúng. Bài thi có 25 câu hỏi."},"tl":{"q":"Sa Missouri, ilang tanong ang nasa written test para sa regular na driver license?","o":["20 tanong","30 tanong","25 tanong","40 tanong"],"h1":"Isang-kapat ito ng isang daan.","h2":"Ang written test sa Missouri para sa regular na lisensya ay may 25 multiple-choice na tanong.","p":"Tama. May 25 tanong ang test."},"ar":{"q":"في Missouri، كم سؤالًا في الامتحان الكتابي لرخصة القيادة العادية؟","o":["20 سؤالًا","30 سؤالًا","25 سؤالًا","40 سؤالًا"],"h1":"هو ربع المئة.","h2":"الامتحان الكتابي في Missouri للرخصة العادية فيه 25 سؤالًا من نوع الاختيار من متعدد.","p":"صحيح. في الامتحان 25 سؤالًا."},"ref":{"doc":"MO","page":18}},{"id":"mo-010","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, how many of the 25 written test questions must you answer correctly to pass?","o":["15","20","18","22"],"h1":"You may miss five.","h2":"You must answer 20 of the 25 questions correctly on the Missouri written test, which is 80 percent.","p":"Right. You need 20 correct answers out of 25."},"es":{"q":"En Missouri, ¿cuántas de las 25 preguntas del examen escrito debe contestar bien para aprobar?","o":["15","20","18","22"],"h1":"Puede fallar cinco.","h2":"Usted debe contestar bien 20 de las 25 preguntas del examen escrito de Missouri, es decir, el 80 por ciento.","p":"Correcto. Necesita 20 respuestas correctas de 25."},"zh":{"q":"在 Missouri，25 道笔试题中必须答对几道才能通过？","o":["15","20","18","22"],"h1":"你可以答错五道。","h2":"在 Missouri 的笔试中，你必须在 25 道题里答对 20 道，也就是 80%。","p":"对。25 道题里你需要答对 20 道。"},"vi":{"q":"Ở Missouri, bạn phải trả lời đúng bao nhiêu trong 25 câu hỏi của bài thi viết để đậu?","o":["15","20","18","22"],"h1":"Bạn được sai năm câu.","h2":"Bạn phải trả lời đúng 20 trong 25 câu hỏi của bài thi viết ở Missouri, tức là 80 phần trăm.","p":"Đúng. Bạn cần trả lời đúng 20 trên 25 câu."},"tl":{"q":"Sa Missouri, ilan sa 25 tanong ng written test ang dapat mong masagot nang tama para pumasa?","o":["15","20","18","22"],"h1":"Puwede kang magkamali ng lima.","h2":"Dapat mong masagot nang tama ang 20 sa 25 tanong ng written test sa Missouri, na 80 porsiyento.","p":"Tama. Kailangan mo ng 20 tamang sagot sa 25."},"ar":{"q":"في Missouri، كم سؤالًا من أسئلة الامتحان الكتابي الـ 25 يجب أن تجيب عنه إجابة صحيحة لتنجح؟","o":["15","20","18","22"],"h1":"يمكنك أن تخطئ في خمسة.","h2":"يجب أن تجيب إجابة صحيحة عن 20 سؤالًا من 25 في الامتحان الكتابي في Missouri، أي 80 في المئة.","p":"صحيح. تحتاج إلى 20 إجابة صحيحة من 25."},"ref":{"doc":"MO","page":1}},{"id":"mo-011","scope":"MO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Missouri, since the hands-free law, which drivers may not hold a phone while driving?","o":["Only drivers under 21","Only commercial drivers","Only drivers in school zones","All drivers"],"h1":"The newer law does not depend on age.","h2":"Missouri's hands-free law applies to all drivers: you may not hold, type on or scroll a phone while driving, and tickets began on January 1, 2025.","p":"Right. No driver may hold a phone while driving."},"es":{"q":"En Missouri, desde la ley de manos libres, ¿qué conductores no pueden sostener el teléfono mientras manejan?","o":["Solo los menores de 21","Solo los conductores comerciales","Solo en zonas escolares","Todos los conductores"],"h1":"La ley más nueva no depende de la edad.","h2":"La ley de manos libres de Missouri se aplica a todos los conductores: no puede sostener, escribir ni desplazarse en el teléfono mientras maneja, y las multas empezaron el 1 de enero de 2025.","p":"Correcto. Ningún conductor puede sostener el teléfono mientras maneja."},"zh":{"q":"在 Missouri，有了免提法以后，哪些司机开车时不能手拿手机？","o":["只有 21 岁以下的司机","只有商业司机","只有在学校区域的司机","所有司机"],"h1":"这条较新的法律和年龄无关。","h2":"Missouri 的免提法适用于所有司机：开车时你不能拿着手机、在手机上打字或滑动屏幕，从 2025 年 1 月 1 日开始开罚单。","p":"对。任何司机开车时都不能手拿手机。"},"vi":{"q":"Ở Missouri, từ khi có luật rảnh tay (hands-free law), những tài xế nào không được cầm điện thoại khi lái xe?","o":["Chỉ tài xế dưới 21 tuổi","Chỉ tài xế xe thương mại","Chỉ tài xế trong khu vực trường học","Tất cả tài xế"],"h1":"Luật mới không phụ thuộc vào tuổi.","h2":"Luật rảnh tay của Missouri áp dụng cho tất cả tài xế: bạn không được cầm, gõ chữ hay cuộn màn hình điện thoại khi lái xe, và việc phạt bắt đầu từ ngày 1 tháng 1 năm 2025.","p":"Đúng. Không tài xế nào được cầm điện thoại khi lái xe."},"tl":{"q":"Sa Missouri, mula nang magkaroon ng hands-free law, aling mga driver ang hindi puwedeng humawak ng telepono habang nagmamaneho?","o":["Mga driver na wala pang 21 lang","Mga commercial driver lang","Mga driver sa school zone lang","Lahat ng driver"],"h1":"Hindi nakadepende sa edad ang mas bagong batas.","h2":"Ang hands-free law ng Missouri ay para sa lahat ng driver: hindi ka puwedeng humawak, mag-type o mag-scroll sa telepono habang nagmamaneho, at nagsimula ang mga tiket noong Enero 1, 2025.","p":"Tama. Walang driver ang puwedeng humawak ng telepono habang nagmamaneho."},"ar":{"q":"في Missouri، منذ قانون القيادة بدون استخدام اليدين (hands-free law)، أي السائقين لا يجوز لهم حمل الهاتف أثناء القيادة؟","o":["السائقون الذين أعمارهم أقل من 21 سنة فقط","سائقو المركبات التجارية فقط","السائقون في مناطق المدارس فقط","كل السائقين"],"h1":"القانون الأحدث لا يتعلّق بالعمر.","h2":"قانون القيادة بدون استخدام اليدين في Missouri يشمل كل السائقين: لا يجوز لك أن تحمل الهاتف أو تكتب عليه أو تتصفّحه أثناء القيادة، وبدأت المخالفات في 1 يناير 2025.","p":"صحيح. لا يجوز لأي سائق أن يحمل الهاتف أثناء القيادة."},"ref":{"doc":"MO","page":93}},{"id":"mo-012","scope":"MO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Missouri, which way of using a phone is allowed for an adult driver?","o":["Talking with Bluetooth or speaker, hands-free","Holding the phone to your ear","Typing a text at a stop sign","Scrolling a map in your hand"],"h1":"Your hands must stay off the phone.","h2":"Missouri lets drivers use hands-free features such as Bluetooth, speaker or voice-to-text, but not holding or typing on the phone.","p":"Right. Hands-free use is allowed."},"es":{"q":"En Missouri, ¿qué forma de usar el teléfono está permitida para un conductor adulto?","o":["Hablar con Bluetooth o altavoz, sin manos","Sostener el teléfono en la oreja","Escribir un mensaje en un alto","Mover un mapa con la mano"],"h1":"Sus manos no deben tocar el teléfono.","h2":"Missouri permite usar funciones de manos libres como Bluetooth, altavoz o dictado por voz, pero no sostener ni escribir en el teléfono.","p":"Correcto. El uso con manos libres está permitido."},"zh":{"q":"在 Missouri，成年司机可以用哪种方式使用手机？","o":["用蓝牙或扬声器通话，免提","把手机拿到耳边","在停车标志前打短信","手拿着手机滑动地图"],"h1":"你的手必须离开手机。","h2":"Missouri 允许司机使用蓝牙、扬声器或语音转文字等免提功能，但不能拿着手机或在手机上打字。","p":"对。可以免提使用。"},"vi":{"q":"Ở Missouri, cách dùng điện thoại nào được phép cho tài xế người lớn?","o":["Nói chuyện bằng Bluetooth hoặc loa ngoài, không cầm máy","Cầm điện thoại áp vào tai","Gõ tin nhắn khi dừng ở biển STOP","Cuộn bản đồ trên điện thoại cầm tay"],"h1":"Tay bạn phải rời khỏi điện thoại.","h2":"Missouri cho phép tài xế dùng các chức năng rảnh tay như Bluetooth, loa ngoài hoặc đọc thành chữ, nhưng không được cầm hay gõ trên điện thoại.","p":"Đúng. Được phép dùng điện thoại kiểu rảnh tay."},"tl":{"q":"Sa Missouri, aling paraan ng paggamit ng telepono ang pinapayagan para sa adult na driver?","o":["Pakikipag-usap gamit ang Bluetooth o speaker, nang hands-free","Paghawak ng telepono sa tainga","Pag-type ng text sa stop sign","Pag-scroll ng mapa sa kamay"],"h1":"Dapat hindi hawak ng kamay mo ang telepono.","h2":"Pinapayagan ng Missouri ang mga driver na gumamit ng hands-free na feature tulad ng Bluetooth, speaker o voice-to-text, pero hindi ang paghawak o pag-type sa telepono.","p":"Tama. Pinapayagan ang hands-free na paggamit."},"ar":{"q":"في Missouri، أي طريقة لاستخدام الهاتف مسموحة للسائق البالغ؟","o":["التحدّث عبر Bluetooth أو مكبّر الصوت، بدون استخدام اليدين","حمل الهاتف على الأذن","كتابة رسالة عند إشارة STOP","تصفّح الخريطة والهاتف في يدك"],"h1":"يجب أن تبقى يداك بعيدتين عن الهاتف.","h2":"تسمح Missouri للسائقين باستخدام ميزات بدون اليدين مثل Bluetooth أو مكبّر الصوت أو تحويل الصوت إلى نص، لكن لا يجوز حمل الهاتف أو الكتابة عليه.","p":"صحيح. الاستخدام بدون اليدين مسموح."},"ref":{"doc":"MO","page":93}},{"id":"mo-013","scope":"MO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Missouri, at what blood alcohol level can a driver under 21 be charged?","o":["0.08 percent","0.02 percent","0.05 percent","0.10 percent"],"h1":"It is much lower than the adult limit.","h2":"In Missouri, a driver under 21 can be charged with a blood alcohol level of 0.02 percent, far below the adult limit of 0.08.","p":"Right. Under 21, the limit is 0.02 percent."},"es":{"q":"En Missouri, ¿con qué nivel de alcohol en la sangre se puede acusar a un conductor menor de 21 años?","o":["0.08 por ciento","0.02 por ciento","0.05 por ciento","0.10 por ciento"],"h1":"Es mucho menor que el límite para adultos.","h2":"En Missouri, a un conductor menor de 21 años se le puede acusar con 0.02 por ciento de alcohol en la sangre, muy por debajo del límite de 0.08 para adultos.","p":"Correcto. Para menores de 21, el límite es 0.02 por ciento."},"zh":{"q":"在 Missouri，21 岁以下的司机血液酒精浓度达到多少就可能被起诉？","o":["0.08%","0.02%","0.05%","0.10%"],"h1":"它比成年人的限值低很多。","h2":"在 Missouri，21 岁以下的司机血液酒精浓度达到 0.02% 就可能被起诉，远低于成年人 0.08 的限值。","p":"对。21 岁以下，限值是 0.02%。"},"vi":{"q":"Ở Missouri, tài xế dưới 21 tuổi có thể bị buộc tội ở mức nồng độ cồn trong máu nào?","o":["0.08 phần trăm","0.02 phần trăm","0.05 phần trăm","0.10 phần trăm"],"h1":"Mức này thấp hơn nhiều so với giới hạn của người lớn.","h2":"Ở Missouri, tài xế dưới 21 tuổi có thể bị buộc tội khi nồng độ cồn trong máu là 0.02 phần trăm, thấp hơn nhiều so với giới hạn 0.08 của người lớn.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02 phần trăm."},"tl":{"q":"Sa Missouri, sa anong antas ng alak sa dugo puwedeng kasuhan ang driver na wala pang 21?","o":["0.08 porsiyento","0.02 porsiyento","0.05 porsiyento","0.10 porsiyento"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon para sa adult.","h2":"Sa Missouri, ang driver na wala pang 21 ay puwedeng kasuhan kapag 0.02 porsiyento ang alak sa dugo, mas mababa nang malaki sa limitasyon para sa adult na 0.08.","p":"Tama. Kapag wala pang 21, 0.02 porsiyento ang limitasyon."},"ar":{"q":"في Missouri، عند أي نسبة كحول في الدم يمكن أن يُتّهم السائق الذي عمره أقل من 21 سنة؟","o":["0.08 في المئة","0.02 في المئة","0.05 في المئة","0.10 في المئة"],"h1":"هي أقل بكثير من حدّ البالغين.","h2":"في Missouri، يمكن أن يُتّهم السائق الذي عمره أقل من 21 سنة إذا كانت نسبة الكحول في دمه 0.02 في المئة، وهي أقل بكثير من حدّ البالغين 0.08.","p":"صحيح. لمن عمره أقل من 21 سنة الحدّ هو 0.02 في المئة."},"ref":{"doc":"MO","page":67}},{"id":"mo-014","scope":"MO","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Missouri, you approach a stopped emergency vehicle with flashing lights on a highway with two lanes your way. What must you do?","o":["Stop in your lane","Speed up to pass quickly","Change lanes away from it if safe, or slow down","Honk and keep your speed"],"h1":"Give the workers more space.","h2":"Missouri's move over law says to change to a lane away from the stopped vehicle if it is safe, or slow down if you cannot.","p":"Right. Move over, or slow down if you cannot."},"es":{"q":"En Missouri, usted se acerca a un vehículo de emergencia detenido con luces intermitentes en una carretera con dos carriles en su dirección. ¿Qué debe hacer?","o":["Detenerse en su carril","Acelerar para pasar rápido","Cambiarse de carril, alejándose, si es seguro, o reducir la velocidad","Tocar la bocina y mantener la velocidad"],"h1":"Dé más espacio a los trabajadores.","h2":"La ley de Missouri dice que debe cambiarse a un carril lejos del vehículo detenido si es seguro, o reducir la velocidad si no puede.","p":"Correcto. Cámbiese de carril, o reduzca la velocidad si no puede."},"zh":{"q":"在 Missouri，你在你的方向有两条车道的公路上，接近一辆停着、闪着灯的急救车辆。你必须怎么做？","o":["在你的车道里停车","加速很快开过去","如果安全，换到离它远的车道，否则减速","按喇叭，保持速度"],"h1":"给工作人员更多空间。","h2":"Missouri 的 move over 法规定，如果安全，要换到离停着的车远的车道；如果不能换道，就要减速。","p":"对。让出车道，不能让就减速。"},"vi":{"q":"Ở Missouri, bạn đến gần một xe cấp cứu đang dừng và nháy đèn trên xa lộ có hai làn theo chiều của bạn. Bạn phải làm gì?","o":["Dừng lại trong làn của bạn","Tăng tốc để vượt nhanh","Chuyển sang làn xa xe đó nếu an toàn, hoặc chạy chậm lại","Bấm còi và giữ tốc độ"],"h1":"Hãy cho người làm việc thêm chỗ.","h2":"Luật nhường làn (move over law) của Missouri nói phải chuyển sang làn xa xe đang dừng nếu an toàn, hoặc chạy chậm lại nếu bạn không thể chuyển làn.","p":"Đúng. Chuyển làn, hoặc chạy chậm lại nếu không thể."},"tl":{"q":"Sa Missouri, papalapit ka sa isang nakahintong emergency vehicle na may kumikislap na ilaw sa highway na may dalawang lane sa direksyon mo. Ano ang dapat mong gawin?","o":["Huminto sa lane mo","Bumilis para mabilis na makalampas","Lumipat sa lane na malayo rito kung ligtas, o bumagal","Bumusina at panatilihin ang bilis"],"h1":"Bigyan ng mas maraming espasyo ang mga nagtatrabaho.","h2":"Sinasabi ng move over law ng Missouri na lumipat sa lane na malayo sa nakahintong sasakyan kung ligtas, o bumagal kung hindi ka makalipat.","p":"Tama. Lumipat ng lane, o bumagal kung hindi puwede."},"ar":{"q":"في Missouri، تقترب من مركبة طوارئ متوقفة وأضواؤها تومض على طريق سريع فيه مساران في اتجاهك. ماذا يجب أن تفعل؟","o":["تتوقف في مسارك","تسرع لتتجاوزها بسرعة","تنتقل إلى مسار بعيد عنها إذا كان ذلك آمنًا، أو تخفّف السرعة","تضغط على البوق وتحافظ على سرعتك"],"h1":"أعطِ العاملين مساحة أكبر.","h2":"قانون الابتعاد (move over law) في Missouri يقول أن تنتقل إلى مسار بعيد عن المركبة المتوقفة إذا كان ذلك آمنًا، أو أن تخفّف السرعة إذا لم تستطع.","p":"صحيح. ابتعد بتغيير المسار، أو خفّف السرعة إذا لم تستطع."},"ref":{"doc":"MO","page":23}},{"id":"mo-015","scope":"MO","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Missouri, which stopped vehicles are covered by the move over law besides police, fire and ambulances?","o":["Only school buses","Only mail trucks","Any car parked on the shoulder","MoDOT vehicles with amber lights"],"h1":"Think of highway work trucks with yellow lights.","h2":"Missouri's move over law also covers stopped vehicles showing amber or amber and white lights, such as MoDOT trucks, so road workers get room too.","p":"Right. MoDOT vehicles with amber lights are covered."},"es":{"q":"En Missouri, ¿qué vehículos detenidos cubre la ley de cambiarse de carril, además de policía, bomberos y ambulancias?","o":["Solo los autobuses escolares","Solo los camiones del correo","Cualquier auto en el acotamiento","Los vehículos de MoDOT con luces ámbar"],"h1":"Piense en camiones de trabajo en la carretera con luces amarillas.","h2":"La ley de Missouri también cubre los vehículos detenidos con luces ámbar o ámbar y blancas, como los camiones de MoDOT, para que los trabajadores también tengan espacio.","p":"Correcto. Los vehículos de MoDOT con luces ámbar están cubiertos."},"zh":{"q":"在 Missouri，除了警车、消防车和救护车，move over 法还包括哪些停着的车？","o":["只有校车","只有邮政卡车","任何停在路肩上的车","开着琥珀色灯的 MoDOT 车辆"],"h1":"想一想开着黄灯的公路工作卡车。","h2":"Missouri 的 move over 法也包括停着、开着琥珀色灯或琥珀色加白色灯的车，比如 MoDOT 的卡车，这样道路工人也有空间。","p":"对。开着琥珀色灯的 MoDOT 车辆也包括在内。"},"vi":{"q":"Ở Missouri, ngoài xe cảnh sát, xe cứu hỏa và xe cứu thương, luật nhường làn (move over law) còn áp dụng cho xe đang dừng nào?","o":["Chỉ xe buýt trường học","Chỉ xe tải bưu điện","Bất kỳ xe nào đậu bên lề đường","Xe của MoDOT có đèn màu hổ phách"],"h1":"Hãy nghĩ đến xe tải làm đường có đèn vàng.","h2":"Luật nhường làn của Missouri cũng áp dụng cho xe đang dừng có đèn màu hổ phách, hoặc đèn hổ phách và trắng, như xe tải của MoDOT, để công nhân làm đường cũng có chỗ.","p":"Đúng. Xe của MoDOT có đèn màu hổ phách cũng được áp dụng."},"tl":{"q":"Sa Missouri, bukod sa pulis, bumbero at ambulansya, aling mga nakahintong sasakyan ang sakop ng move over law?","o":["Mga school bus lang","Mga mail truck lang","Anumang kotseng nakaparada sa shoulder","Mga sasakyan ng MoDOT na may amber na ilaw"],"h1":"Isipin ang mga trak na pantrabaho sa highway na may dilaw na ilaw.","h2":"Sakop din ng move over law ng Missouri ang mga nakahintong sasakyan na may amber o amber at puting ilaw, tulad ng mga trak ng MoDOT, para may espasyo rin ang mga manggagawa sa kalsada.","p":"Tama. Sakop ang mga sasakyan ng MoDOT na may amber na ilaw."},"ar":{"q":"في Missouri، غير الشرطة والإطفاء والإسعاف، أي المركبات المتوقفة يشملها قانون الابتعاد (move over law)؟","o":["الحافلات المدرسية فقط","شاحنات البريد فقط","أي سيارة متوقفة على كتف الطريق","مركبات MoDOT ذات الأضواء الكهرمانية"],"h1":"فكّر في شاحنات العمل على الطرق ذات الأضواء الصفراء.","h2":"قانون الابتعاد في Missouri يشمل أيضًا المركبات المتوقفة التي تُظهر أضواء كهرمانية، أو كهرمانية وبيضاء، مثل شاحنات MoDOT، حتى يحصل عمّال الطرق أيضًا على مساحة.","p":"صحيح. مركبات MoDOT ذات الأضواء الكهرمانية مشمولة."},"ref":{"doc":"MO","page":null}},{"id":"mo-016","scope":"MO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Missouri, when must your headlights be on during the day?","o":["Whenever the weather requires your windshield wipers","Only after sunset","Only on interstates","Only in work zones"],"h1":"Think of rain on your windshield.","h2":"Missouri requires lighted headlights any time the weather makes you use your windshield wipers, and also in fog.","p":"Right. Wipers on means headlights on."},"es":{"q":"En Missouri, ¿cuándo deben estar encendidas las luces delanteras durante el día?","o":["Siempre que el clima exija usar los limpiaparabrisas","Solo después de la puesta del sol","Solo en autopistas interestatales","Solo en zonas de trabajo"],"h1":"Piense en la lluvia sobre su parabrisas.","h2":"Missouri exige las luces delanteras encendidas cada vez que el clima le obliga a usar los limpiaparabrisas, y también con niebla.","p":"Correcto. Limpiaparabrisas encendidos significa luces encendidas."},"zh":{"q":"在 Missouri，白天什么时候必须打开车头灯？","o":["只要天气让你需要用雨刷","只在日落以后","只在州际公路上","只在施工区"],"h1":"想一想挡风玻璃上的雨。","h2":"Missouri 规定，只要天气让你使用挡风玻璃雨刷，就必须打开车头灯，有雾时也一样。","p":"对。开雨刷就要开车头灯。"},"vi":{"q":"Ở Missouri, khi nào bạn phải bật đèn pha vào ban ngày?","o":["Bất cứ khi nào thời tiết cần bật cần gạt nước","Chỉ sau khi mặt trời lặn","Chỉ trên xa lộ liên bang","Chỉ trong khu vực công trường"],"h1":"Hãy nghĩ đến mưa trên kính chắn gió.","h2":"Missouri yêu cầu bật đèn pha bất cứ khi nào thời tiết khiến bạn phải dùng cần gạt nước, và cả khi có sương mù.","p":"Đúng. Bật cần gạt nước thì bật đèn pha."},"tl":{"q":"Sa Missouri, kailan dapat nakabukas ang headlights mo sa araw?","o":["Tuwing kailangan ng panahon ang windshield wipers mo","Pagkatapos lang lumubog ang araw","Sa interstate lang","Sa work zone lang"],"h1":"Isipin ang ulan sa windshield mo.","h2":"Hinihingi ng Missouri na nakabukas ang headlights tuwing ang panahon ay nagpapagamit sa iyo ng windshield wipers, at pati kapag may hamog (fog).","p":"Tama. Kapag bukas ang wipers, bukas ang headlights."},"ar":{"q":"في Missouri، متى يجب أن تكون المصابيح الأمامية مضاءة أثناء النهار؟","o":["كلما احتاج الطقس إلى تشغيل مسّاحات الزجاج الأمامي","بعد غروب الشمس فقط","على الطرق السريعة بين الولايات فقط","في مناطق العمل فقط"],"h1":"فكّر في المطر على الزجاج الأمامي.","h2":"تطلب Missouri إضاءة المصابيح الأمامية في أي وقت يجعلك فيه الطقس تستخدم مسّاحات الزجاج الأمامي، وكذلك في الضباب.","p":"صحيح. إذا شغّلت المسّاحات فأضئ المصابيح الأمامية."},"ref":{"doc":"MO","page":62}},{"id":"mo-017","scope":"MO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Missouri, there is fog but you do not need your wipers. Must your headlights be on?","o":["No, only when wipers are on","Only if you drive over 45 mph","Yes, fog also requires headlights","Only after sunset"],"h1":"The law names fog on its own.","h2":"Missouri law requires headlights during fog even when you do not need your windshield wipers.","p":"Right. Fog means headlights on."},"es":{"q":"En Missouri, hay niebla pero no necesita los limpiaparabrisas. ¿Deben estar encendidas las luces delanteras?","o":["No, solo cuando usa los limpiaparabrisas","Solo si maneja a más de 45 mph","Sí, la niebla también exige luces","Solo después de la puesta del sol"],"h1":"La ley menciona la niebla por separado.","h2":"La ley de Missouri exige las luces delanteras con niebla aunque no necesite los limpiaparabrisas.","p":"Correcto. Con niebla, luces encendidas."},"zh":{"q":"在 Missouri，有雾，但你不需要开雨刷。你必须打开车头灯吗？","o":["不用，只有开雨刷时才要","只有开超过 45 英里/小时时","要，有雾也必须开车头灯","只在日落以后"],"h1":"法律单独写明了雾。","h2":"Missouri 法律规定，有雾时必须打开车头灯，即使你不需要开挡风玻璃雨刷。","p":"对。有雾就要开车头灯。"},"vi":{"q":"Ở Missouri, trời có sương mù nhưng bạn không cần dùng cần gạt nước. Bạn có phải bật đèn pha không?","o":["Không, chỉ khi bật cần gạt nước","Chỉ khi bạn chạy trên 45 mph","Có, sương mù cũng bắt buộc bật đèn pha","Chỉ sau khi mặt trời lặn"],"h1":"Luật nói riêng về sương mù.","h2":"Luật Missouri yêu cầu bật đèn pha khi có sương mù, ngay cả khi bạn không cần dùng cần gạt nước.","p":"Đúng. Có sương mù thì bật đèn pha."},"tl":{"q":"Sa Missouri, may hamog (fog) pero hindi mo kailangan ang wipers mo. Dapat bang nakabukas ang headlights mo?","o":["Hindi, kapag bukas lang ang wipers","Kung nagmamaneho ka lang nang higit sa 45 mph","Oo, kailangan din ng headlights kapag may hamog","Pagkatapos lang lumubog ang araw"],"h1":"Binabanggit ng batas ang hamog nang hiwalay.","h2":"Hinihingi ng batas ng Missouri ang headlights kapag may hamog kahit hindi mo kailangan ang windshield wipers mo.","p":"Tama. Kapag may hamog, bukas ang headlights."},"ar":{"q":"في Missouri، يوجد ضباب لكنك لا تحتاج إلى المسّاحات. هل يجب أن تكون المصابيح الأمامية مضاءة؟","o":["لا، فقط عندما تكون المسّاحات تعمل","فقط إذا كنت تقود بسرعة أكثر من 45 mph","نعم، الضباب أيضًا يتطلّب المصابيح الأمامية","بعد غروب الشمس فقط"],"h1":"القانون يذكر الضباب وحده.","h2":"قانون Missouri يتطلّب المصابيح الأمامية في الضباب حتى عندما لا تحتاج إلى مسّاحات الزجاج الأمامي.","p":"صحيح. في الضباب أضئ المصابيح الأمامية."},"ref":{"doc":"MO","page":null}},{"id":"mo-018","scope":"MO","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Missouri, a school bus with flashing red lights is stopped on the other side of a divided highway with a median. What must you do?","o":["Stop until the lights turn off","You do not have to stop","Stop, then pass at 10 mph","Stop only if you see children"],"h1":"The median separates you from the bus.","h2":"In Missouri, drivers on the opposite side of a divided highway, or of a highway with four or more lanes, do not have to stop for a school bus, but traffic behind the bus must stop.","p":"Right. The other side of a divided highway does not have to stop."},"es":{"q":"En Missouri, un autobús escolar con luces rojas intermitentes está detenido al otro lado de una carretera dividida con camellón. ¿Qué debe hacer usted?","o":["Detenerse hasta que se apaguen las luces","No tiene que detenerse","Detenerse y luego pasar a 10 mph","Detenerse solo si ve niños"],"h1":"El camellón lo separa del autobús.","h2":"En Missouri, los conductores del otro lado de una carretera dividida, o de una carretera de cuatro carriles o más, no tienen que detenerse por un autobús escolar, pero el tráfico detrás del autobús sí debe detenerse.","p":"Correcto. El otro lado de una carretera dividida no tiene que detenerse."},"zh":{"q":"在 Missouri，一辆闪着红灯的校车停在有中央隔离带的分隔公路另一边。你必须怎么做？","o":["停车，直到灯熄灭","你不必停车","停车，然后用 10 英里/小时开过去","只有看到孩子时才停车"],"h1":"中央隔离带把你和校车分开。","h2":"在 Missouri，在分隔公路或四条及以上车道的公路对面行驶的司机，不必为校车停车，但校车后面的车必须停车。","p":"对。分隔公路另一边的车不必停车。"},"vi":{"q":"Ở Missouri, một xe buýt trường học nháy đèn đỏ đang dừng ở phía bên kia của xa lộ có dải phân cách. Bạn phải làm gì?","o":["Dừng lại cho đến khi đèn tắt","Bạn không phải dừng lại","Dừng lại, rồi vượt qua với tốc độ 10 mph","Chỉ dừng lại nếu bạn thấy trẻ em"],"h1":"Dải phân cách ngăn cách bạn với xe buýt.","h2":"Ở Missouri, tài xế ở phía bên kia của xa lộ có dải phân cách, hoặc của xa lộ có bốn làn trở lên, không phải dừng lại cho xe buýt trường học, nhưng xe chạy phía sau xe buýt phải dừng lại.","p":"Đúng. Phía bên kia của xa lộ có dải phân cách không phải dừng lại."},"tl":{"q":"Sa Missouri, may school bus na may kumikislap na pulang ilaw na nakahinto sa kabilang panig ng divided highway na may median. Ano ang dapat mong gawin?","o":["Huminto hanggang mamatay ang mga ilaw","Hindi mo kailangang huminto","Huminto, saka lumampas sa 10 mph","Huminto lang kung may makita kang mga bata"],"h1":"Pinaghihiwalay ka ng median sa bus.","h2":"Sa Missouri, ang mga driver sa kabilang panig ng divided highway, o ng highway na may apat o higit pang lane, ay hindi kailangang huminto para sa school bus, pero ang mga sasakyan sa likod ng bus ay dapat huminto.","p":"Tama. Hindi kailangang huminto ang kabilang panig ng divided highway."},"ar":{"q":"في Missouri، حافلة مدرسية أضواؤها الحمراء تومض متوقفة على الجانب الآخر من طريق سريع مقسوم بجزيرة وسطى. ماذا يجب أن تفعل؟","o":["تتوقف حتى تنطفئ الأضواء","ليس عليك أن تتوقف","تتوقف، ثم تتجاوز بسرعة 10 mph","تتوقف فقط إذا رأيت أطفالًا"],"h1":"الجزيرة الوسطى تفصلك عن الحافلة.","h2":"في Missouri، ليس على السائقين في الجانب الآخر من طريق سريع مقسوم، أو من طريق سريع فيه أربعة مسارات أو أكثر، أن يتوقفوا للحافلة المدرسية، لكن السيارات خلف الحافلة يجب أن تتوقف.","p":"صحيح. الجانب الآخر من الطريق المقسوم ليس عليه أن يتوقف."},"ref":{"doc":"MO","page":24}},{"id":"mo-019","scope":"MO","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Missouri, you are behind a school bus on a divided highway when it stops with red lights flashing. What must you do?","o":["Pass on the left with care","Pass if no children are near","Slow to 20 mph and pass","Stop and wait"],"h1":"You are on the same side as the bus.","h2":"When you travel in the same direction as a stopped school bus in Missouri, you must stop, even on a divided highway.","p":"Right. Traffic on the same side must stop."},"es":{"q":"En Missouri, usted va detrás de un autobús escolar en una carretera dividida cuando se detiene con luces rojas intermitentes. ¿Qué debe hacer?","o":["Rebasar por la izquierda con cuidado","Rebasar si no hay niños cerca","Bajar a 20 mph y rebasar","Detenerse y esperar"],"h1":"Usted está del mismo lado que el autobús.","h2":"Cuando usted va en la misma dirección que un autobús escolar detenido en Missouri, debe detenerse, aunque sea una carretera dividida.","p":"Correcto. El tráfico del mismo lado debe detenerse."},"zh":{"q":"在 Missouri，你在分隔公路上跟在一辆校车后面，它停下来并闪着红灯。你必须怎么做？","o":["小心地从左边超过去","如果附近没有孩子就超过去","减速到 20 英里/小时再超过去","停车等待"],"h1":"你和校车在同一边。","h2":"在 Missouri，当你和停着的校车同方向行驶时，你必须停车，即使是在分隔公路上。","p":"对。同一边的车必须停车。"},"vi":{"q":"Ở Missouri, bạn đang chạy sau một xe buýt trường học trên xa lộ có dải phân cách thì xe buýt dừng lại và nháy đèn đỏ. Bạn phải làm gì?","o":["Vượt bên trái một cách cẩn thận","Vượt nếu không có trẻ em ở gần","Chạy chậm xuống 20 mph rồi vượt","Dừng lại và chờ"],"h1":"Bạn ở cùng phía với xe buýt.","h2":"Ở Missouri, khi bạn đi cùng chiều với một xe buýt trường học đang dừng, bạn phải dừng lại, ngay cả trên xa lộ có dải phân cách.","p":"Đúng. Xe cùng phía phải dừng lại."},"tl":{"q":"Sa Missouri, nasa likod ka ng school bus sa divided highway nang huminto ito na kumikislap ang pulang ilaw. Ano ang dapat mong gawin?","o":["Lumampas sa kaliwa nang maingat","Lumampas kung walang batang malapit","Bumagal sa 20 mph at lumampas","Huminto at maghintay"],"h1":"Nasa parehong panig ka ng bus.","h2":"Kapag pareho ang direksyon mo at ng nakahintong school bus sa Missouri, dapat kang huminto, kahit sa divided highway.","p":"Tama. Dapat huminto ang mga sasakyan sa parehong panig."},"ar":{"q":"في Missouri، أنت خلف حافلة مدرسية على طريق سريع مقسوم عندما تتوقف وأضواؤها الحمراء تومض. ماذا يجب أن تفعل؟","o":["تتجاوز من اليسار بحذر","تتجاوز إذا لم يكن هناك أطفال قريبون","تخفّف إلى 20 mph وتتجاوز","تتوقف وتنتظر"],"h1":"أنت على نفس جانب الحافلة.","h2":"عندما تسير في نفس اتجاه حافلة مدرسية متوقفة في Missouri، يجب أن تتوقف، حتى على طريق سريع مقسوم.","p":"صحيح. السيارات على نفس الجانب يجب أن تتوقف."},"ref":{"doc":"MO","page":23}},{"id":"mo-020","scope":"MO","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Missouri, a 2026 law allows up to 75 mph on some rural interstates. What speed must you obey where the sign still says 70 mph?","o":["70 mph, the posted limit","75 mph, the new law","80 mph when traffic is light","65 mph, the expressway limit"],"h1":"The sign on the road tells you the limit.","h2":"You must obey the posted sign: where it says 70 mph, the limit is 70 mph, even though Missouri allows up to 75 mph on some rural interstates.","p":"Right. Always obey the posted limit."},"es":{"q":"En Missouri, una ley de 2026 permite hasta 75 mph en algunas autopistas rurales. ¿Qué velocidad debe respetar donde el letrero todavía dice 70 mph?","o":["70 mph, el límite indicado","75 mph, la nueva ley","80 mph si hay poco tráfico","65 mph, el límite de vía rápida"],"h1":"El letrero en la carretera le dice el límite.","h2":"Usted debe respetar el letrero: donde dice 70 mph, el límite es 70 mph, aunque Missouri permite hasta 75 mph en algunas autopistas rurales.","p":"Correcto. Siempre respete el límite indicado."},"zh":{"q":"在 Missouri，2026 年的一条法律允许一些乡村州际公路限速最高到 75 英里/小时。在标志仍然写着 70 英里/小时的地方，你必须遵守什么速度？","o":["70 英里/小时，标出的限速","75 英里/小时，新法律","车少时 80 英里/小时","65 英里/小时，快速路的限速"],"h1":"路上的标志告诉你限速。","h2":"你必须遵守标出的标志：标志写 70 英里/小时的地方，限速就是 70 英里/小时，即使 Missouri 允许一些乡村州际公路最高到 75 英里/小时。","p":"对。一定要遵守标出的限速。"},"vi":{"q":"Ở Missouri, một luật năm 2026 cho phép chạy đến 75 mph trên một số xa lộ liên bang ở vùng nông thôn. Bạn phải theo tốc độ nào ở nơi biển báo vẫn ghi 70 mph?","o":["70 mph, giới hạn ghi trên biển","75 mph, theo luật mới","80 mph khi ít xe","65 mph, giới hạn của đường cao tốc"],"h1":"Biển báo trên đường cho bạn biết giới hạn.","h2":"Bạn phải theo biển báo: nơi biển ghi 70 mph thì giới hạn là 70 mph, dù Missouri cho phép đến 75 mph trên một số xa lộ liên bang ở vùng nông thôn.","p":"Đúng. Luôn theo giới hạn ghi trên biển báo."},"tl":{"q":"Sa Missouri, may batas noong 2026 na nagpapahintulot ng hanggang 75 mph sa ilang rural interstate. Anong bilis ang dapat mong sundin kung saan 70 mph pa rin ang nakasulat sa sign?","o":["70 mph, ang nakapaskil na limitasyon","75 mph, ang bagong batas","80 mph kapag kaunti ang trapiko","65 mph, ang limitasyon sa expressway"],"h1":"Ang sign sa kalsada ang nagsasabi sa iyo ng limitasyon.","h2":"Dapat mong sundin ang nakapaskil na sign: kung saan nakasulat ang 70 mph, 70 mph ang limitasyon, kahit pinapayagan ng Missouri ang hanggang 75 mph sa ilang rural interstate.","p":"Tama. Laging sundin ang nakapaskil na limitasyon."},"ar":{"q":"في Missouri، قانون من سنة 2026 يسمح بسرعة حتى 75 mph على بعض الطرق السريعة الريفية بين الولايات. أي سرعة يجب أن تلتزم بها حيث ما زالت اللافتة تقول 70 mph؟","o":["70 mph، الحدّ المكتوب على اللافتة","75 mph، القانون الجديد","80 mph عندما تكون حركة المرور خفيفة","65 mph، حدّ الطرق السريعة"],"h1":"اللافتة على الطريق تخبرك بالحدّ.","h2":"يجب أن تلتزم باللافتة المكتوبة: حيث تقول 70 mph فالحدّ هو 70 mph، مع أن Missouri تسمح بحتى 75 mph على بعض الطرق السريعة الريفية بين الولايات.","p":"صحيح. التزم دائمًا بالحدّ المكتوب على اللافتة."},"ref":{"doc":"MO","page":50}},{"id":"mo-021","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, how many points within 18 months lead to a license suspension?","o":["4 points","6 points","8 points","12 points"],"h1":"It is double the number that brings a warning letter.","h2":"In Missouri, 8 points within 18 months lead to a suspension, starting at 30 days for a first time.","p":"Right. Eight points in 18 months means suspension."},"es":{"q":"En Missouri, ¿cuántos puntos en 18 meses llevan a la suspensión de la licencia?","o":["4 puntos","6 puntos","8 puntos","12 puntos"],"h1":"Es el doble del número que trae una carta de aviso.","h2":"En Missouri, 8 puntos en 18 meses llevan a una suspensión, que empieza con 30 días la primera vez.","p":"Correcto. Ocho puntos en 18 meses significan suspensión."},"zh":{"q":"在 Missouri，18 个月内被扣多少分会导致驾照被暂停？","o":["4 分","6 分","8 分","12 分"],"h1":"它是收到警告信的分数的两倍。","h2":"在 Missouri，18 个月内被扣 8 分会导致驾照被暂停，第一次是 30 天起。","p":"对。18 个月内 8 分就会被暂停驾照。"},"vi":{"q":"Ở Missouri, bị bao nhiêu điểm trong vòng 18 tháng thì bị treo bằng lái?","o":["4 điểm","6 điểm","8 điểm","12 điểm"],"h1":"Đó là gấp đôi số điểm khiến bạn nhận thư cảnh báo.","h2":"Ở Missouri, bị 8 điểm trong vòng 18 tháng thì bị treo bằng lái, bắt đầu từ 30 ngày cho lần đầu.","p":"Đúng. Tám điểm trong 18 tháng thì bị treo bằng lái."},"tl":{"q":"Sa Missouri, ilang puntos sa loob ng 18 buwan ang humahantong sa suspensyon ng lisensya?","o":["4 na puntos","6 na puntos","8 puntos","12 puntos"],"h1":"Doble ito ng bilang na nagdadala ng sulat ng babala.","h2":"Sa Missouri, ang 8 puntos sa loob ng 18 buwan ay humahantong sa suspensyon, na nagsisimula sa 30 araw sa unang beses.","p":"Tama. Walong puntos sa 18 buwan ay nangangahulugang suspensyon."},"ar":{"q":"في Missouri، كم نقطة خلال 18 شهرًا تؤدي إلى تعليق الرخصة؟","o":["4 نقاط","6 نقاط","8 نقاط","12 نقطة"],"h1":"هي ضعف العدد الذي يجلب رسالة تحذير.","h2":"في Missouri، 8 نقاط خلال 18 شهرًا تؤدي إلى تعليق الرخصة، يبدأ من 30 يومًا في المرة الأولى.","p":"صحيح. ثماني نقاط في 18 شهرًا تعني تعليق الرخصة."},"ref":{"doc":"MO","page":73}},{"id":"mo-022","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, what happens when a driver gets 4 points within 12 months?","o":["The license is revoked for a year","The Department of Revenue sends a warning letter","The driver must retake the road test","Nothing happens"],"h1":"It is a first step, not a penalty.","h2":"When a Missouri driver gets 4 points in 12 months, the Department of Revenue sends an advisory letter as a warning.","p":"Right. Four points in 12 months brings a warning letter."},"es":{"q":"En Missouri, ¿qué pasa cuando un conductor acumula 4 puntos en 12 meses?","o":["Le revocan la licencia por un año","El Departamento de Ingresos le envía una carta de aviso","Debe repetir el examen de manejo","No pasa nada"],"h1":"Es un primer paso, no un castigo.","h2":"Cuando un conductor en Missouri acumula 4 puntos en 12 meses, el Departamento de Ingresos le envía una carta de aviso.","p":"Correcto. Cuatro puntos en 12 meses traen una carta de aviso."},"zh":{"q":"在 Missouri，司机在 12 个月内被扣 4 分会怎样？","o":["驾照被吊销一年","Department of Revenue 寄来一封警告信","司机必须重新路考","什么都不会发生"],"h1":"这是第一步，不是处罚。","h2":"Missouri 的司机在 12 个月内被扣 4 分时，Department of Revenue 会寄一封提醒信作为警告。","p":"对。12 个月内 4 分会收到警告信。"},"vi":{"q":"Ở Missouri, điều gì xảy ra khi tài xế bị 4 điểm trong vòng 12 tháng?","o":["Bằng lái bị thu hồi một năm","Department of Revenue (Sở Thuế vụ) gửi thư cảnh báo","Tài xế phải thi lái lại","Không có gì xảy ra"],"h1":"Đó là bước đầu tiên, không phải hình phạt.","h2":"Khi tài xế ở Missouri bị 4 điểm trong 12 tháng, Department of Revenue gửi một thư nhắc nhở để cảnh báo.","p":"Đúng. Bốn điểm trong 12 tháng sẽ nhận thư cảnh báo."},"tl":{"q":"Sa Missouri, ano ang mangyayari kapag ang isang driver ay nagkaroon ng 4 na puntos sa loob ng 12 buwan?","o":["Babawiin ang lisensya nang isang taon","Magpapadala ang Department of Revenue ng sulat ng babala","Dapat ulitin ng driver ang road test","Walang mangyayari"],"h1":"Unang hakbang ito, hindi parusa.","h2":"Kapag ang isang driver sa Missouri ay nagkaroon ng 4 na puntos sa 12 buwan, magpapadala ang Department of Revenue ng advisory letter bilang babala.","p":"Tama. Ang apat na puntos sa 12 buwan ay nagdadala ng sulat ng babala."},"ar":{"q":"في Missouri، ماذا يحدث عندما يحصل السائق على 4 نقاط خلال 12 شهرًا؟","o":["تُلغى الرخصة لمدة سنة","ترسل Department of Revenue (دائرة الإيرادات) رسالة تحذير","يجب على السائق أن يعيد امتحان القيادة على الطريق","لا يحدث شيء"],"h1":"هي خطوة أولى، وليست عقوبة.","h2":"عندما يحصل سائق في Missouri على 4 نقاط خلال 12 شهرًا، ترسل Department of Revenue رسالة تنبيه كتحذير.","p":"صحيح. أربع نقاط في 12 شهرًا تجلب رسالة تحذير."},"ref":{"doc":"MO","page":73}},{"id":"mo-023","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, what is the minimum liability insurance for property damage?","o":["$5,000","$10,000","$50,000","$25,000"],"h1":"It matches the amount required for injury to one person.","h2":"Since January 1, 2024, Missouri requires at least $25,000 of property damage coverage, with $25,000 per injured person and $50,000 per crash.","p":"Right. Property damage coverage must be at least $25,000."},"es":{"q":"En Missouri, ¿cuál es el seguro de responsabilidad mínimo por daños a la propiedad?","o":["$5,000","$10,000","$50,000","$25,000"],"h1":"Es igual a la cantidad exigida por lesiones a una persona.","h2":"Desde el 1 de enero de 2024, Missouri exige por lo menos $25,000 de cobertura por daños a la propiedad, con $25,000 por persona lesionada y $50,000 por choque.","p":"Correcto. La cobertura por daños a la propiedad debe ser de por lo menos $25,000."},"zh":{"q":"在 Missouri，财产损失的最低责任保险是多少？","o":["$5,000","$10,000","$50,000","$25,000"],"h1":"它和一个人受伤所要求的金额一样。","h2":"从 2024 年 1 月 1 日起，Missouri 要求至少 $25,000 的财产损失保险，每位受伤的人 $25,000，每次车祸 $50,000。","p":"对。财产损失保险必须至少 $25,000。"},"vi":{"q":"Ở Missouri, bảo hiểm trách nhiệm tối thiểu cho thiệt hại tài sản là bao nhiêu?","o":["$5,000","$10,000","$50,000","$25,000"],"h1":"Số tiền này bằng số tiền bắt buộc cho thương tích của một người.","h2":"Từ ngày 1 tháng 1 năm 2024, Missouri yêu cầu bảo hiểm thiệt hại tài sản ít nhất $25,000, cùng với $25,000 cho mỗi người bị thương và $50,000 cho mỗi vụ tai nạn.","p":"Đúng. Bảo hiểm thiệt hại tài sản phải ít nhất là $25,000."},"tl":{"q":"Sa Missouri, ano ang pinakamababang liability insurance para sa pinsala sa ari-arian?","o":["$5,000","$10,000","$50,000","$25,000"],"h1":"Kapareho ito ng halagang kailangan para sa pinsala sa isang tao.","h2":"Mula Enero 1, 2024, hinihingi ng Missouri ang hindi bababa sa $25,000 na coverage para sa pinsala sa ari-arian, kasama ang $25,000 bawat taong nasaktan at $50,000 bawat aksidente.","p":"Tama. Ang coverage para sa pinsala sa ari-arian ay dapat hindi bababa sa $25,000."},"ar":{"q":"في Missouri، ما الحدّ الأدنى لتأمين المسؤولية عن أضرار الممتلكات؟","o":["$5,000","$10,000","$50,000","$25,000"],"h1":"يساوي المبلغ المطلوب لإصابة شخص واحد.","h2":"منذ 1 يناير 2024، تطلب Missouri تغطية لأضرار الممتلكات لا تقل عن $25,000، مع $25,000 لكل شخص مصاب و$50,000 لكل حادث.","p":"صحيح. يجب ألا تقل تغطية أضرار الممتلكات عن $25,000."},"ref":{"doc":"MO","page":79}},{"id":"mo-024","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, besides liability, which insurance coverage must every car policy include?","o":["Uninsured motorist coverage","Collision coverage","Rental car coverage","Roadside assistance"],"h1":"It protects you when the other driver has no insurance.","h2":"Missouri requires uninsured motorist coverage for injuries, so you are protected if a driver without insurance hurts you.","p":"Right. Uninsured motorist coverage is required."},"es":{"q":"En Missouri, además de la responsabilidad civil, ¿qué cobertura debe incluir toda póliza de auto?","o":["Cobertura contra conductores sin seguro","Cobertura de choque","Cobertura de auto de alquiler","Asistencia en el camino"],"h1":"Le protege cuando el otro conductor no tiene seguro.","h2":"Missouri exige la cobertura contra conductores sin seguro para lesiones, para protegerle si un conductor sin seguro le lastima.","p":"Correcto. La cobertura contra conductores sin seguro es obligatoria."},"zh":{"q":"在 Missouri，除了责任保险，每份汽车保单还必须包括哪种保险？","o":["无保险驾驶人保险（uninsured motorist）","碰撞险","租车保险","道路救援"],"h1":"当对方司机没有保险时，它保护你。","h2":"Missouri 要求有针对受伤的无保险驾驶人保险，这样如果一位没有保险的司机伤到你，你也有保障。","p":"对。必须有无保险驾驶人保险。"},"vi":{"q":"Ở Missouri, ngoài bảo hiểm trách nhiệm, mọi hợp đồng bảo hiểm xe phải có loại bảo hiểm nào?","o":["Bảo hiểm tài xế không có bảo hiểm (uninsured motorist coverage)","Bảo hiểm va chạm","Bảo hiểm xe thuê","Dịch vụ cứu hộ trên đường"],"h1":"Nó bảo vệ bạn khi tài xế kia không có bảo hiểm.","h2":"Missouri yêu cầu bảo hiểm tài xế không có bảo hiểm cho thương tích, để bạn được bảo vệ nếu một tài xế không có bảo hiểm làm bạn bị thương.","p":"Đúng. Bảo hiểm tài xế không có bảo hiểm là bắt buộc."},"tl":{"q":"Sa Missouri, bukod sa liability, anong insurance coverage ang dapat kasama sa bawat car policy?","o":["Uninsured motorist coverage","Collision coverage","Coverage para sa rental car","Roadside assistance"],"h1":"Pinoprotektahan ka nito kapag walang insurance ang ibang driver.","h2":"Hinihingi ng Missouri ang uninsured motorist coverage para sa mga pinsala sa katawan, para protektado ka kung masaktan ka ng driver na walang insurance.","p":"Tama. Kailangan ang uninsured motorist coverage."},"ar":{"q":"في Missouri، غير تأمين المسؤولية، أي تغطية تأمينية يجب أن تكون في كل وثيقة تأمين سيارة؟","o":["تغطية السائق غير المؤمَّن (uninsured motorist coverage)","تغطية الاصطدام","تغطية السيارة المستأجرة","المساعدة على الطريق"],"h1":"تحميك عندما لا يكون لدى السائق الآخر تأمين.","h2":"تطلب Missouri تغطية السائق غير المؤمَّن للإصابات، حتى تكون محميًا إذا أصابك سائق ليس لديه تأمين.","p":"صحيح. تغطية السائق غير المؤمَّن مطلوبة."},"ref":{"doc":"MO","page":79}},{"id":"mo-025","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, until a permit holder turns 16, which person may ride along as the supervising driver?","o":["Any friend age 18 or older","A grandparent with a valid license","Any licensed sibling","A neighbor age 19 or older"],"h1":"Think of a close family member from an older generation.","h2":"Before age 16, a Missouri permit holder must drive with a parent, grandparent, guardian or certified instructor, or another qualified adult the rules allow.","p":"Right. A grandparent may supervise a permit holder under 16."},"es":{"q":"En Missouri, hasta que el titular del permiso cumple 16 años, ¿qué persona puede acompañarle como conductor supervisor?","o":["Cualquier amigo de 18 años o más","Un abuelo o abuela con licencia válida","Cualquier hermano con licencia","Un vecino de 19 años o más"],"h1":"Piense en un familiar cercano de una generación mayor.","h2":"Antes de los 16 años, el titular de un permiso en Missouri debe manejar con su padre, madre, abuelo, tutor o un instructor certificado, u otro adulto calificado que permitan las reglas.","p":"Correcto. Un abuelo puede supervisar a un titular de permiso menor de 16."},"zh":{"q":"在 Missouri，持学习驾照的人满 16 岁之前，谁可以作为陪同的司机同车？","o":["任何 18 岁或以上的朋友","持有效驾照的祖父母","任何有驾照的兄弟姐妹","19 岁或以上的邻居"],"h1":"想一想上一代的亲近家人。","h2":"16 岁以前，Missouri 持学习驾照的人必须和父母、祖父母、监护人或有证书的教练一起开车，或者和规定允许的其他合格成年人一起开车。","p":"对。祖父母可以陪同 16 岁以下持学习驾照的人。"},"vi":{"q":"Ở Missouri, cho đến khi người có giấy phép tập lái đủ 16 tuổi, ai có thể ngồi cùng làm người giám sát?","o":["Bất kỳ người bạn nào từ 18 tuổi trở lên","Ông hoặc bà có bằng lái hợp lệ","Bất kỳ anh chị em nào có bằng lái","Một người hàng xóm từ 19 tuổi trở lên"],"h1":"Hãy nghĩ đến một người thân trong gia đình thuộc thế hệ lớn hơn.","h2":"Trước 16 tuổi, người có giấy phép tập lái ở Missouri phải lái cùng cha mẹ, ông bà, người giám hộ hoặc giáo viên dạy lái có chứng nhận, hoặc một người lớn đủ điều kiện khác mà quy định cho phép.","p":"Đúng. Ông hoặc bà có thể giám sát người có giấy phép tập lái dưới 16 tuổi."},"tl":{"q":"Sa Missouri, hanggang sa mag-16 ang may permit, sino ang puwedeng sumama bilang supervising driver?","o":["Sinumang kaibigan na 18 taong gulang pataas","Isang lolo o lola na may valid na lisensya","Sinumang kapatid na may lisensya","Isang kapitbahay na 19 taong gulang pataas"],"h1":"Isipin ang isang malapit na kapamilya mula sa mas nakatatandang henerasyon.","h2":"Bago mag-16, ang may permit sa Missouri ay dapat magmaneho kasama ang magulang, lolo o lola, guardian o certified instructor, o ibang kwalipikadong adult na pinapayagan ng mga patakaran.","p":"Tama. Puwedeng magbantay ang lolo o lola sa may permit na wala pang 16."},"ar":{"q":"في Missouri، إلى أن يبلغ حامل التصريح 16 سنة، من يمكنه أن يرافقه كسائق مشرف؟","o":["أي صديق عمره 18 سنة أو أكثر","جدّ أو جدّة لديه رخصة سارية","أي أخ أو أخت لديه رخصة","جار عمره 19 سنة أو أكثر"],"h1":"فكّر في قريب من العائلة من جيل أكبر.","h2":"قبل عمر 16 سنة، يجب على حامل التصريح في Missouri أن يقود مع أحد الوالدين أو الجدّ أو الجدّة أو الوصي أو مدرّب معتمد، أو شخص بالغ مؤهَّل آخر تسمح به القواعد.","p":"صحيح. يمكن للجدّ أو الجدّة أن يشرف على حامل التصريح الذي عمره أقل من 16 سنة."},"ref":{"doc":"MO","page":15}},{"id":"mo-026","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, what happens if you refuse a chemical test for alcohol when a police officer asks?","o":["You get a warning letter","You pay a small fine only","Your license is taken away for one year","You must retake the written test"],"h1":"Refusing has a serious, long result.","h2":"In Missouri, if you refuse a chemical test of your blood alcohol, your driver license is taken away for one year.","p":"Right. Refusing the test costs you your license for one year."},"es":{"q":"En Missouri, ¿qué pasa si usted se niega a hacer una prueba química de alcohol cuando un policía se lo pide?","o":["Recibe una carta de advertencia","Solo paga una multa pequeña","Le quitan la licencia por un año","Debe repetir el examen escrito"],"h1":"Negarse tiene un resultado serio y largo.","h2":"En Missouri, si usted se niega a una prueba química del alcohol en la sangre, le quitan la licencia de manejar por un año.","p":"Correcto. Negarse a la prueba le cuesta la licencia por un año."},"zh":{"q":"在 Missouri，如果警察要求你做酒精化学检测而你拒绝，会怎么样？","o":["你会收到一封警告信","你只需要交一小笔罚款","你的驾照会被收回一年","你必须重新参加笔试"],"h1":"拒绝检测的后果很严重，而且时间很长。","h2":"在 Missouri，如果你拒绝做血液酒精化学检测，你的驾照会被收回一年。","p":"对。拒绝检测会让你失去驾照一年。"},"vi":{"q":"Ở Missouri, điều gì xảy ra nếu bạn từ chối làm xét nghiệm hóa học về rượu khi cảnh sát yêu cầu?","o":["Bạn nhận một lá thư cảnh cáo","Bạn chỉ phải trả một khoản phạt nhỏ","Bằng lái của bạn bị tước trong một năm","Bạn phải thi lại phần thi viết"],"h1":"Từ chối sẽ có hậu quả nghiêm trọng và kéo dài.","h2":"Ở Missouri, nếu bạn từ chối làm xét nghiệm hóa học về nồng độ cồn trong máu, bằng lái của bạn sẽ bị tước trong một năm.","p":"Đúng. Từ chối xét nghiệm làm bạn mất bằng lái trong một năm."},"tl":{"q":"Sa Missouri, ano ang mangyayari kung tumanggi ka sa chemical test para sa alak kapag hiningi ito ng pulis?","o":["Makakatanggap ka ng warning letter","Magbabayad ka lang ng maliit na multa","Kukunin ang lisensya mo nang isang taon","Kailangan mong ulitin ang written test"],"h1":"Seryoso at matagal ang resulta ng pagtanggi.","h2":"Sa Missouri, kung tumanggi ka sa chemical test ng alak sa dugo mo, kukunin ang driver license mo nang isang taon.","p":"Tama. Kapag tumanggi ka sa test, mawawala ang lisensya mo nang isang taon."},"ar":{"q":"في Missouri، ماذا يحدث إذا رفضت فحصًا كيميائيًا للكحول عندما يطلبه منك شرطي؟","o":["تحصل على رسالة تحذير","تدفع غرامة صغيرة فقط","تُسحب رخصتك لمدة سنة واحدة","يجب أن تعيد الاختبار الكتابي"],"h1":"للرفض نتيجة خطيرة وطويلة.","h2":"في Missouri، إذا رفضت فحصًا كيميائيًا لنسبة الكحول في دمك، تُسحب رخصة القيادة منك لمدة سنة واحدة.","p":"صحيح. رفض الفحص يُفقدك رخصتك لمدة سنة واحدة."},"ref":{"doc":"MO","page":70}},{"id":"mo-027","scope":"MO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Missouri, what is the highest fine a judge may give for littering?","o":["$1,000","$50","$100","$250"],"h1":"There can also be up to a year in jail.","h2":"In Missouri a person found guilty of littering may have to pay a fine of up to $1,000, spend up to one year in jail, or both.","p":"Right. Littering can cost up to $1,000."},"es":{"q":"En Missouri, ¿cuál es la multa más alta que un juez puede dar por tirar basura?","o":["$1,000","$50","$100","$250"],"h1":"También puede haber hasta un año de cárcel.","h2":"En Missouri una persona declarada culpable de tirar basura puede pagar una multa de hasta $1,000, pasar hasta un año en la cárcel, o las dos cosas.","p":"Correcto. Tirar basura puede costar hasta $1,000."},"zh":{"q":"在 Missouri，乱扔垃圾时法官最多可以罚多少钱？","o":["$1,000","$50","$100","$250"],"h1":"还可能被判最多一年监禁。","h2":"在 Missouri，乱扔垃圾被判有罪的人最多可能被罚 $1,000，或者最多坐一年牢，或者两样都有。","p":"对。乱扔垃圾最多可能被罚 $1,000。"},"vi":{"q":"Ở Missouri, thẩm phán có thể phạt tối đa bao nhiêu tiền vì xả rác?","o":["$1,000","$50","$100","$250"],"h1":"Cũng có thể bị tù đến một năm.","h2":"Ở Missouri, người bị kết tội xả rác có thể phải trả tiền phạt đến $1,000, bị tù đến một năm, hoặc cả hai.","p":"Đúng. Xả rác có thể bị phạt đến $1,000."},"tl":{"q":"Sa Missouri, ano ang pinakamataas na multa na puwedeng ibigay ng judge para sa pagkakalat ng basura?","o":["$1,000","$50","$100","$250"],"h1":"Puwede ring makulong nang hanggang isang taon.","h2":"Sa Missouri, ang taong napatunayang nagkalat ng basura ay puwedeng magbayad ng multa na hanggang $1,000, makulong nang hanggang isang taon, o pareho.","p":"Tama. Puwedeng umabot sa $1,000 ang multa sa pagkakalat ng basura."},"ar":{"q":"في Missouri، ما أعلى غرامة يمكن أن يفرضها القاضي على رمي النفايات في غير مكانها؟","o":["$1,000","$50","$100","$250"],"h1":"قد يكون هناك أيضًا سجن حتى سنة واحدة.","h2":"في Missouri، الشخص الذي تثبت إدانته برمي النفايات قد يدفع غرامة تصل إلى $1,000، أو يُسجن حتى سنة واحدة، أو الاثنين معًا.","p":"صحيح. رمي النفايات قد يكلّف حتى $1,000."},"ref":{"doc":"MO","page":34}},{"id":"mo-028","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, your license has expired. After how long must you take the written and driving tests again to renew it?","o":["After 30 days","After 60 days","After 2 years","After 6 months (184 days)"],"h1":"It is the same length of time as the early-renewal window.","h2":"In Missouri, if you do not renew within six months (184 days) after your license expires, you must take the written and driving tests again, plus the vision and road sign tests.","p":"Right. Wait more than 184 days and you must retest."},"es":{"q":"En Missouri, su licencia está vencida. ¿Después de cuánto tiempo debe repetir los exámenes escrito y de manejo para renovarla?","o":["Después de 30 días","Después de 60 días","Después de 2 años","Después de 6 meses (184 días)"],"h1":"Es el mismo tiempo que el plazo para renovar antes.","h2":"En Missouri, si usted no renueva dentro de seis meses (184 días) después del vencimiento, debe repetir los exámenes escrito y de manejo, además de los de vista y señales.","p":"Correcto. Si pasan más de 184 días, debe volver a examinarse."},"zh":{"q":"在 Missouri，你的驾照已经过期。过期多久以后，你必须重新参加笔试和路考才能更新？","o":["30 天以后","60 天以后","2 年以后","6 个月（184 天）以后"],"h1":"这和提前更新的期限一样长。","h2":"在 Missouri，如果驾照过期后六个月（184 天）内你没有更新，你必须重新参加笔试和路考，还要参加视力测试和路标测试。","p":"对。超过 184 天，你就必须重新考试。"},"vi":{"q":"Ở Missouri, bằng lái của bạn đã hết hạn. Sau bao lâu thì bạn phải thi lại phần thi viết và thi lái để gia hạn?","o":["Sau 30 ngày","Sau 60 ngày","Sau 2 năm","Sau 6 tháng (184 ngày)"],"h1":"Đó là cùng khoảng thời gian với thời hạn gia hạn sớm.","h2":"Ở Missouri, nếu bạn không gia hạn trong vòng sáu tháng (184 ngày) sau khi bằng lái hết hạn, bạn phải thi lại phần thi viết và thi lái, cùng với bài kiểm tra thị lực và bài kiểm tra biển báo đường.","p":"Đúng. Chờ quá 184 ngày thì bạn phải thi lại."},"tl":{"q":"Sa Missouri, expired na ang lisensya mo. Pagkalipas ng gaano katagal kailangan mong ulitin ang written at driving test para ma-renew ito?","o":["Pagkalipas ng 30 araw","Pagkalipas ng 60 araw","Pagkalipas ng 2 taon","Pagkalipas ng 6 na buwan (184 araw)"],"h1":"Kapareho ito ng haba ng panahon para sa maagang pag-renew.","h2":"Sa Missouri, kung hindi ka mag-renew sa loob ng anim na buwan (184 araw) matapos mag-expire ang lisensya mo, kailangan mong ulitin ang written at driving test, pati ang vision test at road sign test.","p":"Tama. Kapag lumampas ka sa 184 araw, kailangan mong mag-test ulit."},"ar":{"q":"في Missouri، انتهت صلاحية رخصتك. بعد كم من الوقت يجب أن تعيد الاختبار الكتابي واختبار القيادة لتجديدها؟","o":["بعد 30 يومًا","بعد 60 يومًا","بعد سنتين (2)","بعد 6 أشهر (184 يومًا)"],"h1":"إنها نفس مدة فترة التجديد المبكر.","h2":"في Missouri، إذا لم تجدّد رخصتك خلال ستة أشهر (184 يومًا) بعد انتهاء صلاحيتها، يجب أن تعيد الاختبار الكتابي واختبار القيادة، بالإضافة إلى اختبار النظر واختبار إشارات الطريق.","p":"صحيح. إذا انتظرت أكثر من 184 يومًا يجب أن تعيد الاختبار."},"ref":{"doc":"MO","page":11}},{"id":"mo-029","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, when you must file an accident report with the Department of Revenue, how long do you have?","o":["24 hours","30 days","6 months","1 year"],"h1":"It is about one month.","h2":"In Missouri a required accident report must be filed with the Driver License Bureau within 30 days.","p":"Right. File the accident report within 30 days."},"es":{"q":"En Missouri, cuando debe presentar un informe de accidente al Departamento de Ingresos, ¿cuánto tiempo tiene?","o":["24 horas","30 días","6 meses","1 año"],"h1":"Es más o menos un mes.","h2":"En Missouri un informe de accidente obligatorio se debe presentar a la Oficina de Licencias de Manejar dentro de 30 días.","p":"Correcto. Presente el informe dentro de 30 días."},"zh":{"q":"在 Missouri，如果你必须向 Department of Revenue 提交事故报告，你有多长时间？","o":["24 小时","30 天","6 个月","1 年"],"h1":"大约一个月。","h2":"在 Missouri，必须提交的事故报告要在 30 天内交给 Driver License Bureau。","p":"对。要在 30 天内提交事故报告。"},"vi":{"q":"Ở Missouri, khi bạn phải nộp báo cáo tai nạn cho Department of Revenue, bạn có bao nhiêu thời gian?","o":["24 giờ","30 ngày","6 tháng","1 năm"],"h1":"Khoảng một tháng.","h2":"Ở Missouri, báo cáo tai nạn bắt buộc phải được nộp cho Driver License Bureau trong vòng 30 ngày.","p":"Đúng. Hãy nộp báo cáo tai nạn trong vòng 30 ngày."},"tl":{"q":"Sa Missouri, kapag kailangan mong mag-file ng accident report sa Department of Revenue, gaano katagal ang mayroon ka?","o":["24 oras","30 araw","6 na buwan","1 taon"],"h1":"Mga isang buwan ito.","h2":"Sa Missouri, ang kinakailangang accident report ay dapat i-file sa Driver License Bureau sa loob ng 30 araw.","p":"Tama. I-file ang accident report sa loob ng 30 araw."},"ar":{"q":"في Missouri، عندما يجب عليك تقديم تقرير حادث إلى Department of Revenue، كم من الوقت لديك؟","o":["24 ساعة","30 يومًا","6 أشهر","سنة واحدة (1)"],"h1":"إنها حوالي شهر واحد.","h2":"في Missouri، يجب تقديم تقرير الحادث المطلوب إلى Driver License Bureau خلال 30 يومًا.","p":"صحيح. قدّم تقرير الحادث خلال 30 يومًا."},"ref":{"doc":"MO","page":81}},{"id":"mo-030","scope":"MO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Missouri, you have a minor crash on the highway and no one is hurt. What should you do with your car?","o":["Leave it in the lane until police arrive","Drive away and call later","Move it onto the shoulder or off the road","Turn off the engine and wait inside"],"h1":"Think \"steer it and clear it.\"","h2":"In Missouri, after a minor crash with no injuries, you should move your car onto the shoulder or another spot off the road so traffic does not back up.","p":"Right. Steer it and clear it off the road."},"es":{"q":"En Missouri, usted tiene un choque leve en la carretera y nadie está herido. ¿Qué debe hacer con su carro?","o":["Dejarlo en el carril hasta que llegue la policía","Irse y llamar después","Moverlo al acotamiento o fuera de la carretera","Apagar el motor y esperar adentro"],"h1":"Piense en \"muévalo y despeje\".","h2":"En Missouri, después de un choque leve sin heridos, usted debe mover su carro al acotamiento u otro lugar fuera de la carretera para que el tráfico no se detenga.","p":"Correcto. Mueva el carro y despeje la carretera."},"zh":{"q":"在 Missouri，你在公路上发生了小车祸，没有人受伤。你应该怎么处理你的车？","o":["留在车道上，等警察来","开走，以后再打电话","把车移到路肩上或离开道路","关掉发动机，在车里等"],"h1":"记住“把车开走，把路让开”。","h2":"在 Missouri，发生没有人受伤的小车祸后，你应该把车移到路肩上或其他离开道路的地方，这样交通就不会堵塞。","p":"对。把车开走，把路让开。"},"vi":{"q":"Ở Missouri, bạn bị va chạm nhẹ trên xa lộ và không ai bị thương. Bạn nên làm gì với xe của mình?","o":["Để xe trong làn đường cho đến khi cảnh sát đến","Lái đi và gọi điện sau","Di chuyển xe vào lề đường hoặc ra khỏi đường","Tắt máy và ngồi chờ trong xe"],"h1":"Hãy nghĩ: \"lái xe ra và dọn đường\".","h2":"Ở Missouri, sau một va chạm nhẹ không ai bị thương, bạn nên di chuyển xe vào lề đường hoặc một chỗ khác ra khỏi đường để xe cộ không bị ùn tắc.","p":"Đúng. Lái xe ra và dọn đường."},"tl":{"q":"Sa Missouri, nagkaroon ka ng maliit na banggaan sa highway at walang nasaktan. Ano ang dapat mong gawin sa sasakyan mo?","o":["Iwan ito sa lane hanggang dumating ang pulis","Umalis at tumawag na lang mamaya","Ilipat ito sa shoulder o palabas ng kalsada","Patayin ang makina at maghintay sa loob"],"h1":"Isipin ang \"steer it and clear it\": imaneho ito at alisin sa daan.","h2":"Sa Missouri, pagkatapos ng maliit na banggaan na walang nasaktan, dapat mong ilipat ang sasakyan mo sa shoulder o sa ibang lugar na wala sa kalsada para hindi magkatrapik.","p":"Tama. Imaneho ito at alisin sa kalsada."},"ar":{"q":"في Missouri، وقع لك حادث بسيط على الطريق السريع ولم يُصب أحد. ماذا يجب أن تفعل بسيارتك؟","o":["اتركها في المسار حتى تصل الشرطة","ابتعد بالسيارة واتصل لاحقًا","انقلها إلى كتف الطريق أو خارج الطريق","أطفئ المحرك وانتظر داخل السيارة"],"h1":"فكّر في: \"حرّكها وأخلِ الطريق\".","h2":"في Missouri، بعد حادث بسيط بلا إصابات، يجب أن تنقل سيارتك إلى كتف الطريق أو إلى مكان آخر خارج الطريق حتى لا تتوقف حركة السير.","p":"صحيح. حرّك السيارة وأخلِ الطريق."},"ref":{"doc":"MO","page":81}},{"id":"mo-031","scope":"MO","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Missouri, on a highway with two or more lanes in each direction, when should you use the left lane?","o":["To pass slower traffic","Whenever you want to drive fast","Only when towing a trailer","For the whole trip"],"h1":"Keep right most of the time.","h2":"In Missouri, on a highway with two or more lanes in each direction, you keep to the right and use the left lane to pass slower traffic; the only other reasons to leave the right lane are to make room for a driver entering the road or to get ready for a legal left turn.","p":"Right. Use the left lane to pass, then move back right."},"es":{"q":"En Missouri, en una carretera con dos o más carriles en cada dirección, ¿cuándo debe usar el carril izquierdo?","o":["Para rebasar al tráfico más lento","Siempre que quiera ir rápido","Solo cuando jala un remolque","Durante todo el viaje"],"h1":"Manténgase a la derecha casi siempre.","h2":"En Missouri, en una carretera con dos o más carriles en cada dirección, usted se mantiene a la derecha y usa el carril izquierdo para rebasar al tráfico más lento; las únicas otras razones para dejar el carril derecho son dar espacio a un conductor que entra a la carretera o prepararse para una vuelta a la izquierda permitida.","p":"Correcto. Use el carril izquierdo para rebasar y luego vuelva a la derecha."},"zh":{"q":"在 Missouri，在每个方向有两条或更多车道的公路上，你什么时候应该用左车道？","o":["超过开得比较慢的车","每次你想开快的时候","只在拖拖车的时候","整个路程都用"],"h1":"大部分时间靠右行驶。","h2":"在 Missouri，在每个方向有两条或更多车道的公路上，你要靠右行驶，用左车道超过开得比较慢的车；离开右车道的其他理由只有两个：给正在进入道路的司机让出空间，或者准备合法地左转。","p":"对。用左车道超车，然后回到右边。"},"vi":{"q":"Ở Missouri, trên xa lộ có hai làn đường trở lên mỗi chiều, khi nào bạn nên dùng làn bên trái?","o":["Để vượt xe chạy chậm hơn","Bất cứ khi nào bạn muốn chạy nhanh","Chỉ khi kéo rơ-moóc","Trong suốt chuyến đi"],"h1":"Hầu hết thời gian hãy đi bên phải.","h2":"Ở Missouri, trên xa lộ có hai làn đường trở lên mỗi chiều, bạn đi bên phải và dùng làn bên trái để vượt xe chạy chậm hơn; lý do khác duy nhất để rời làn bên phải là nhường chỗ cho tài xế đang vào đường hoặc chuẩn bị rẽ trái hợp pháp.","p":"Đúng. Dùng làn bên trái để vượt, rồi trở lại bên phải."},"tl":{"q":"Sa Missouri, sa highway na may dalawa o higit pang lane sa bawat direksyon, kailan mo dapat gamitin ang kaliwang lane?","o":["Para mag-overtake sa mas mabagal na sasakyan","Tuwing gusto mong magmaneho nang mabilis","Kapag may hila kang trailer lang","Sa buong biyahe"],"h1":"Manatili sa kanan halos sa lahat ng oras.","h2":"Sa Missouri, sa highway na may dalawa o higit pang lane sa bawat direksyon, manatili ka sa kanan at gamitin ang kaliwang lane para mag-overtake sa mas mabagal na sasakyan; ang tanging ibang dahilan para umalis sa kanang lane ay para magbigay-daan sa driver na pumapasok sa kalsada o para maghanda sa legal na pagliko pakaliwa.","p":"Tama. Gamitin ang kaliwang lane para mag-overtake, pagkatapos bumalik sa kanan."},"ar":{"q":"في Missouri، على طريق سريع فيه مساران أو أكثر في كل اتجاه، متى يجب أن تستخدم المسار الأيسر؟","o":["لتجاوز السيارات الأبطأ","كلما أردت أن تقود بسرعة","فقط عندما تجرّ مقطورة","طوال الرحلة"],"h1":"ابقَ على اليمين معظم الوقت.","h2":"في Missouri، على طريق سريع فيه مساران أو أكثر في كل اتجاه، تبقى على اليمين وتستخدم المسار الأيسر لتجاوز السيارات الأبطأ؛ والسببان الآخران الوحيدان لترك المسار الأيمن هما إفساح المجال لسائق يدخل الطريق أو الاستعداد لانعطاف قانوني إلى اليسار.","p":"صحيح. استخدم المسار الأيسر للتجاوز، ثم عُد إلى اليمين."},"ref":{"doc":"MO","page":37}},{"id":"mo-032","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, a regular driver license can be valid for up to how many years?","o":["2 years","4 years","6 years","10 years"],"h1":"It is the longest period the guide gives for one license.","h2":"A Missouri driver license can be valid for up to six years.","p":"Right. A Missouri license can last up to six years."},"es":{"q":"En Missouri, ¿por cuántos años como máximo puede ser válida una licencia de conducir normal?","o":["2 años","4 años","6 años","10 años"],"h1":"Es el período más largo que da la guía para una licencia.","h2":"Una licencia de conducir de Missouri puede ser válida hasta por seis años.","p":"Correcto. Una licencia de Missouri puede durar hasta seis años."},"ref":{"doc":"MO","page":11}},{"id":"mo-033","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, what is the standard minimum vision for a driver license?","o":["20/40 with one or both eyes","20/20 in each eye","20/100 with both eyes","20/200 with glasses"],"h1":"Many drivers pass it with or without glasses.","h2":"Missouri's standard is at least 20/40 vision with either eye or both eyes.","p":"Right. The standard is 20/40 with one or both eyes."},"es":{"q":"En Missouri, ¿cuál es la visión mínima normal para obtener una licencia de conducir?","o":["20/40 con uno o ambos ojos","20/20 en cada ojo","20/100 con ambos ojos","20/200 con lentes"],"h1":"Muchos conductores la pasan con o sin lentes.","h2":"La norma de Missouri es una visión de al menos 20/40 con un ojo o con ambos.","p":"Correcto. La norma es 20/40 con uno o ambos ojos."},"ref":{"doc":"MO","page":18}},{"id":"mo-034","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, during the driving test the examiner takes off points for mistakes. You fail if you lose more than how many points?","o":["10 points","20 points","50 points","30 points"],"h1":"It is a round number between 20 and 50.","h2":"You fail the Missouri driving test if you lose more than 30 points.","p":"Right. Losing more than 30 points means you fail."},"es":{"q":"En Missouri, durante el examen de manejo el examinador le resta puntos por cada error. Usted reprueba si pierde más de cierta cantidad de puntos. ¿Cuál es esa cantidad?","o":["10 puntos","20 puntos","50 puntos","30 puntos"],"h1":"Es un número redondo entre 20 y 50.","h2":"Usted reprueba el examen de manejo de Missouri si pierde más de 30 puntos.","p":"Correcto. Si pierde más de 30 puntos, reprueba."},"ref":{"doc":"MO","page":21}},{"id":"mo-035","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, what happens if you get 12 or more points on your record within 12 months?","o":["You get only a warning letter","Your license is revoked for one year","Your license is suspended for 30 days","Nothing happens until you reach 24 points"],"h1":"This is more serious than the result for 8 points.","h2":"Getting 12 or more points within 12 months means your Missouri license is revoked for one year.","p":"Right. 12 points in 12 months means a one-year revocation."},"es":{"q":"En Missouri, ¿qué pasa si acumula 12 puntos o más en su historial dentro de 12 meses?","o":["Solo recibe una carta de aviso","Le revocan la licencia por un año","Le suspenden la licencia por 30 días","No pasa nada hasta llegar a 24 puntos"],"h1":"Es más grave que lo que pasa con 8 puntos.","h2":"Si acumula 12 puntos o más dentro de 12 meses, le revocan la licencia de Missouri por un año.","p":"Correcto. 12 puntos en 12 meses significan una revocación de un año."},"ref":{"doc":"MO","page":73}},{"id":"mo-036","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, an officer finds your blood alcohol is 0.08% or more, takes your license and gives you a notice. When does the suspension or revocation start?","o":["After 15 days","The next morning","After 6 months","Only after a jury trial"],"h1":"The notice can include a short temporary driving permit.","h2":"The suspension or revocation starts 15 days after the officer gives you the notice.","p":"Right. You lose the right to drive after 15 days."},"es":{"q":"En Missouri, un oficial encuentra que su nivel de alcohol en la sangre es de 0.08% o más, le quita la licencia y le da un aviso. ¿Cuándo empieza la suspensión o revocación?","o":["Después de 15 días","A la mañana siguiente","Después de 6 meses","Solo después de un juicio con jurado"],"h1":"El aviso puede incluir un permiso temporal corto para manejar.","h2":"La suspensión o revocación empieza 15 días después de que el oficial le da el aviso.","p":"Correcto. Pierde el derecho a manejar después de 15 días."},"ref":{"doc":"MO","page":67}},{"id":"mo-037","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, under the Abuse and Lose law, a driver under 21 is found guilty of an alcohol-related traffic offense. How long can the license be taken away?","o":["10 days","2 years","5 years","90 days"],"h1":"It is about three months.","h2":"Under Missouri's Abuse and Lose law, a driver under 21 can lose the license for 90 days.","p":"Right. Abuse and Lose means 90 days without a license."},"es":{"q":"En Missouri, según la ley Abuse and Lose, un conductor menor de 21 años es declarado culpable de una infracción de tránsito relacionada con alcohol. ¿Por cuánto tiempo le pueden quitar la licencia?","o":["10 días","2 años","5 años","90 días"],"h1":"Son unos tres meses.","h2":"Según la ley Abuse and Lose de Missouri, un conductor menor de 21 años puede perder la licencia por 90 días.","p":"Correcto. Abuse and Lose significa 90 días sin licencia."},"ref":{"doc":"MO","page":69}},{"id":"mo-038","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, you must report a crash to the Driver License Bureau when someone had no insurance and property damage is more than what amount?","o":["$250","$500","$1,000","$2,500"],"h1":"It is less than one thousand dollars.","h2":"You must report the crash when someone was uninsured and property damage is more than $500, or someone was hurt or killed.","p":"Right. The line is more than $500 in damage."},"es":{"q":"En Missouri, debe reportar un choque a la Oficina de Licencias de Conducir cuando alguien no tenía seguro y los daños a la propiedad pasan de cierta cantidad. ¿Cuál es esa cantidad?","o":["$250","$500","$1,000","$2,500"],"h1":"Es menos de mil dólares.","h2":"Debe reportar el choque cuando alguien no tenía seguro y los daños a la propiedad pasan de $500, o cuando alguien resultó herido o muerto.","p":"Correcto. El límite es más de $500 en daños."},"ref":{"doc":"MO","page":82}},{"id":"mo-039","scope":"MO","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Missouri, what is the lowest speed you may drive on an interstate highway in normal conditions?","o":["30 mph","45 mph","40 mph","55 mph"],"h1":"It is well below the maximum speed limit.","h2":"In normal conditions you may not drive slower than 40 mph on a Missouri interstate.","p":"Right. The minimum on interstates is 40 mph."},"es":{"q":"En Missouri, ¿cuál es la velocidad más baja a la que puede manejar en una autopista interestatal en condiciones normales?","o":["30 mph","45 mph","40 mph","55 mph"],"h1":"Está muy por debajo del límite máximo.","h2":"En condiciones normales no puede manejar a menos de 40 mph en una interestatal de Missouri.","p":"Correcto. La mínima en las interestatales es 40 mph."},"ref":{"doc":"MO","page":50}},{"id":"mo-040","scope":"MO","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Missouri, what is the speed limit in a city, town or village when no other limit is posted?","o":["25 mph","20 mph","30 mph","35 mph"],"h1":"It is the same number many states use for neighborhoods.","h2":"The speed limit in any Missouri city, town or village is 25 mph unless a sign shows a different limit.","p":"Right. Unless posted otherwise, it is 25 mph in town."},"es":{"q":"En Missouri, ¿cuál es el límite de velocidad en una ciudad, pueblo o aldea cuando no hay otro límite señalado?","o":["25 mph","20 mph","30 mph","35 mph"],"h1":"Es el mismo número que muchos estados usan en los vecindarios.","h2":"El límite de velocidad en cualquier ciudad, pueblo o aldea de Missouri es 25 mph, a menos que un letrero indique otro.","p":"Correcto. Si no hay otro letrero, es 25 mph en la ciudad."},"ref":{"doc":"MO","page":50}},{"id":"mo-041","scope":"MO","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Missouri, you may not pass on the left when you are within how many feet of an intersection or railroad crossing?","o":["50 feet","300 feet","500 feet","100 feet"],"h1":"The same distance applies near bridges and tunnels when your view is blocked.","h2":"You may not pass on the left within 100 feet of an intersection or a railroad crossing.","p":"Right. No passing within 100 feet of an intersection or railroad crossing."},"es":{"q":"En Missouri, ¿a menos de cuántos pies de una intersección o un cruce de ferrocarril no puede rebasar por la izquierda?","o":["50 pies","300 pies","500 pies","100 pies"],"h1":"La misma distancia se aplica cerca de puentes y túneles cuando la vista está bloqueada.","h2":"No puede rebasar por la izquierda a menos de 100 pies de una intersección o un cruce de ferrocarril.","p":"Correcto. No se rebasa a menos de 100 pies de una intersección o cruce de ferrocarril."},"ref":{"doc":"MO","page":22}},{"id":"mo-042","scope":"MO","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Missouri, what is the smallest fine for a first offense of speeding or passing in a work zone on state roads?","o":["$50","$250","$100","$1,000"],"h1":"A second offense costs at least $300.","h2":"A first offense of speeding or passing in a Missouri work zone carries a fine of at least $250.","p":"Right. The first offense costs at least $250."},"es":{"q":"En Missouri, ¿cuál es la multa mínima por una primera infracción de exceso de velocidad o de rebasar en una zona de trabajo en carreteras estatales?","o":["$50","$250","$100","$1,000"],"h1":"Una segunda infracción cuesta por lo menos $300.","h2":"Una primera infracción de exceso de velocidad o de rebasar en una zona de trabajo de Missouri tiene una multa de al menos $250.","p":"Correcto. La primera infracción cuesta al menos $250."},"ref":{"doc":"MO","page":22}},{"id":"mo-043","scope":"MO","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Missouri, how many points are added to your record if you are found guilty of not stopping for a school bus that is loading or unloading students?","o":["2 points","3 points","5 points","12 points"],"h1":"It is more than the points for speeding.","h2":"Failing to stop for a school bus that is loading or unloading students adds five points to your Missouri record.","p":"Right. Passing a stopped school bus costs five points."},"es":{"q":"En Missouri, ¿cuántos puntos se agregan a su historial si lo declaran culpable de no detenerse ante un autobús escolar que sube o baja estudiantes?","o":["2 puntos","3 puntos","5 puntos","12 puntos"],"h1":"Son más que los puntos por exceso de velocidad.","h2":"No detenerse ante un autobús escolar que sube o baja estudiantes agrega cinco puntos a su historial de Missouri.","p":"Correcto. Pasar un autobús escolar detenido cuesta cinco puntos."},"ref":{"doc":"MO","page":24}},{"id":"mo-044","scope":"MO","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Missouri, the red lights are flashing at a railroad crossing. Where must you stop?","o":["Between 15 and 50 feet from the tracks","Right on top of the first rail","Within 5 feet of the tracks","At least 200 feet from the tracks"],"h1":"Not too close and not too far from the nearest rail.","h2":"When you must stop at a Missouri railroad crossing, stop between 15 and 50 feet from the tracks.","p":"Right. Stop 15 to 50 feet before the tracks."},"es":{"q":"En Missouri, las luces rojas parpadean en un cruce de ferrocarril. ¿Dónde debe detenerse?","o":["Entre 15 y 50 pies de las vías","Justo encima del primer riel","A menos de 5 pies de las vías","Por lo menos a 200 pies de las vías"],"h1":"Ni muy cerca ni muy lejos del riel más cercano.","h2":"Cuando debe detenerse en un cruce de ferrocarril en Missouri, deténgase entre 15 y 50 pies de las vías.","p":"Correcto. Deténgase de 15 a 50 pies antes de las vías."},"ref":{"doc":"MO","page":51}},{"id":"mo-045","scope":"MO","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Missouri, an organized funeral procession is driving through an intersection against a red light. What should you do?","o":["Drive between the cars since your light is green","Join the end of the line to get through faster","Pass the cars in the procession on the right","Wait, because the procession has the right-of-way"],"h1":"The cars in the procession have their flashing lights on.","h2":"An organized funeral procession has the right-of-way at intersections, so you must wait and not cut through it.","p":"Right. Let the funeral procession pass."},"es":{"q":"En Missouri, un cortejo fúnebre organizado cruza una intersección con la luz roja. ¿Qué debe hacer?","o":["Pasar entre los autos porque su luz está en verde","Unirse al final de la fila para pasar más rápido","Rebasar los autos del cortejo por la derecha","Esperar, porque el cortejo tiene el derecho de paso"],"h1":"Los autos del cortejo llevan las luces intermitentes encendidas.","h2":"Un cortejo fúnebre organizado tiene el derecho de paso en las intersecciones, así que usted debe esperar y no cruzarlo.","p":"Correcto. Deje pasar el cortejo fúnebre."},"ref":{"doc":"MO","page":33}},{"id":"mo-046","scope":"MO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Missouri, when the driver has a full license, which people in a passenger car does the seat belt law cover?","o":["Only the driver","The driver and front-seat passengers","Only passengers in the back seat","No one, it is a personal choice"],"h1":"Think about who sits in the front row.","h2":"Missouri's seat belt law requires the driver and front-seat passengers to wear a seat belt.","p":"Right. The driver and front-seat riders must buckle up."},"es":{"q":"En Missouri, cuando el conductor tiene licencia completa, ¿a qué personas de un auto de pasajeros cubre la ley del cinturón de seguridad?","o":["Solo al conductor","Al conductor y a los pasajeros del asiento delantero","Solo a los pasajeros del asiento trasero","A nadie, es una decisión personal"],"h1":"Piense en quiénes van en la fila de adelante.","h2":"La ley de Missouri exige que el conductor y los pasajeros del asiento delantero usen el cinturón de seguridad.","p":"Correcto. El conductor y quienes van adelante deben abrocharse."},"ref":{"doc":"MO","page":55}},{"id":"mo-047","scope":"MO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Missouri, how must a child younger than four years old ride in a car, no matter how much the child weighs?","o":["With only the adult seat belt","Unbuckled if riding in the back seat","In a child safety seat that fits the child","On an adult's lap, held tightly"],"h1":"Very young children need special equipment.","h2":"A child under four in Missouri must ride in a child safety seat that is right for that child, whatever the child's weight.","p":"Right. Children under four ride in a child safety seat."},"es":{"q":"En Missouri, ¿cómo debe viajar en un auto un niño menor de cuatro años, sin importar cuánto pese?","o":["Solo con el cinturón de adulto","Sin abrochar si va en el asiento trasero","En un asiento de seguridad adecuado para el niño","En las piernas de un adulto, bien sujeto"],"h1":"Los niños muy pequeños necesitan un equipo especial.","h2":"En Missouri, un niño menor de cuatro años debe viajar en un asiento de seguridad adecuado para él, pese lo que pese.","p":"Correcto. Los niños menores de cuatro años van en un asiento de seguridad."},"ref":{"doc":"MO","page":55}},{"id":"mo-048","scope":"MO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Missouri, you are using high beams at night. A car comes toward you. Within how many feet must you switch to low beams?","o":["200 feet","350 feet","500 feet","1,000 feet"],"h1":"The guide says it is about one block.","h2":"You must switch to low beams when an oncoming vehicle is within 500 feet.","p":"Right. Dim your lights within 500 feet of an oncoming car."},"es":{"q":"En Missouri, usted maneja de noche con las luces altas. Viene un auto de frente. ¿A cuántos pies debe cambiar a luces bajas?","o":["200 pies","350 pies","500 pies","1,000 pies"],"h1":"La guía dice que es más o menos una cuadra.","h2":"Debe cambiar a luces bajas cuando un vehículo que viene de frente está a menos de 500 pies.","p":"Correcto. Baje las luces a 500 pies de un auto que viene de frente."},"ref":{"doc":"MO","page":62}},{"id":"mo-049","scope":"MO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Missouri, how much space should you leave behind the car ahead when driving on snow or ice?","o":["About 1 second","About 2 seconds","About 3 seconds","About 8 to 10 seconds"],"h1":"It is much more than on a dry road.","h2":"On snow or ice, leave about eight to ten seconds between you and the vehicle ahead.","p":"Right. On snow or ice, keep about 8 to 10 seconds of space."},"es":{"q":"En Missouri, ¿cuánto espacio debe dejar detrás del auto de adelante cuando maneja sobre nieve o hielo?","o":["Más o menos 1 segundo","Más o menos 2 segundos","Más o menos 3 segundos","Más o menos de 8 a 10 segundos"],"h1":"Es mucho más que en una carretera seca.","h2":"Sobre nieve o hielo, deje entre ocho y diez segundos entre usted y el vehículo de adelante.","p":"Correcto. Sobre nieve o hielo, deje de 8 a 10 segundos de espacio."},"ref":{"doc":"MO","page":63}},{"id":"mo-050","scope":"MO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Missouri, when may your car have studded snow tires?","o":["From November 1 to April 1","At any time of the year","Only in January and February","From October 1 to June 1"],"h1":"It covers the cold months, from late fall to early spring.","h2":"Missouri allows studded snow tires only from November 1 to April 1.","p":"Right. Studded tires are allowed November 1 to April 1."},"es":{"q":"En Missouri, ¿cuándo puede su auto tener llantas de nieve con clavos?","o":["Del 1 de noviembre al 1 de abril","En cualquier época del año","Solo en enero y febrero","Del 1 de octubre al 1 de junio"],"h1":"Cubre los meses fríos, de finales del otoño a principios de la primavera.","h2":"Missouri permite llantas de nieve con clavos solo del 1 de noviembre al 1 de abril.","p":"Correcto. Las llantas con clavos se permiten del 1 de noviembre al 1 de abril."},"ref":{"doc":"MO","page":85}},{"id":"mo-051","scope":"MO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Missouri, which cell phone number does the Driver Guide give for reporting a highway emergency?","o":["311","*55","*88","411"],"h1":"It starts with a star.","h2":"The Missouri Driver Guide says the cell phone number to call in a highway emergency is *55.","p":"Right. Dial *55 from a cell phone for a highway emergency."},"es":{"q":"En Missouri, ¿qué número de celular da la Guía del Conductor para reportar una emergencia en la carretera?","o":["311","*55","*88","411"],"h1":"Empieza con un asterisco.","h2":"La Guía del Conductor de Missouri dice que el número de celular para una emergencia en la carretera es *55.","p":"Correcto. Marque *55 desde un celular para una emergencia en la carretera."},"ref":{"doc":"MO","page":41}},{"id":"ms-001","scope":"MS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Mississippi, what is the youngest age to get a regular learner's permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before you can get a regular driver's license.","h2":"In Mississippi, you can get a regular learner's permit at 15, one year before you can get a regular driver's license at 16.","p":"Right. The regular learner's permit starts at age 15."},"es":{"q":"En Mississippi, ¿cuál es la edad mínima para obtener un permiso de aprendiz regular?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de poder obtener la licencia de conducir regular.","h2":"En Mississippi, usted puede obtener un permiso de aprendiz regular a los 15 años, un año antes de poder obtener la licencia de conducir regular a los 16.","p":"Correcto. El permiso de aprendiz regular empieza a los 15 años."},"zh":{"q":"在 Mississippi，最小几岁可以拿到普通学习驾照（learner's permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比你可以拿普通驾照的时间早一年。","h2":"在 Mississippi，你 15 岁就可以拿到普通学习驾照，比 16 岁可以拿的普通驾照早一年。","p":"对。普通学习驾照从 15 岁开始。"},"vi":{"q":"Ở Mississippi, tuổi nhỏ nhất để được cấp giấy phép tập lái thông thường (learner's permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là một năm trước khi bạn có thể được cấp bằng lái thông thường.","h2":"Ở Mississippi, bạn có thể được cấp giấy phép tập lái thông thường lúc 15 tuổi, một năm trước khi bạn có thể được cấp bằng lái thông thường lúc 16 tuổi.","p":"Đúng. Giấy phép tập lái thông thường bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Mississippi, ano ang pinakabatang edad para makakuha ng regular na learner's permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ka makakuha ng regular na driver's license.","h2":"Sa Mississippi, puwede kang makakuha ng regular na learner's permit sa edad na 15, isang taon bago ka makakuha ng regular na driver's license sa edad na 16.","p":"Tama. Nagsisimula ang regular na learner's permit sa edad na 15."},"ar":{"q":"في Mississippi، ما أصغر سن للحصول على تصريح تعلّم القيادة العادي (learner's permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"إنه قبل سنة واحدة من السن الذي يمكنك فيه الحصول على رخصة القيادة العادية.","h2":"في Mississippi، يمكنك الحصول على تصريح تعلّم القيادة العادي في سن 15، أي قبل سنة واحدة من حصولك على رخصة القيادة العادية في سن 16.","p":"صحيح. يبدأ تصريح تعلّم القيادة العادي في سن 15."},"ref":{"doc":"MS","page":13}},{"id":"ms-002","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, a 14-year-old may get a learner's permit in one case. Which one?","o":["If a parent signs a special form","If the teen lives on a farm","If the teen passes the test with a perfect score","If the teen is enrolled in a certified driver education program"],"h1":"Think about a class that teaches driving.","h2":"Mississippi allows a learner's permit at 14 only for a teen who is enrolled in a certified driver education program.","p":"Right. At 14, the permit requires enrollment in certified driver education."},"es":{"q":"En Mississippi, un joven de 14 años puede obtener un permiso de aprendiz en un solo caso. ¿Cuál es?","o":["Si un padre firma un formulario especial","Si el joven vive en una granja","Si el joven aprueba el examen sin errores","Si el joven está inscrito en un programa certificado de educación vial"],"h1":"Piense en una clase que enseña a manejar.","h2":"Mississippi permite el permiso de aprendiz a los 14 años solo a un joven inscrito en un programa certificado de educación vial.","p":"Correcto. A los 14 años, el permiso exige estar inscrito en educación vial certificada."},"zh":{"q":"在 Mississippi，14 岁的人在一种情况下可以拿到学习驾照。是哪一种？","o":["如果父母签一份特别表格","如果青少年住在农场","如果青少年考试得满分","如果青少年报名参加了有认证的驾驶教育课程"],"h1":"想一想教开车的课。","h2":"Mississippi 只允许报名参加了有认证的驾驶教育课程的青少年在 14 岁拿学习驾照。","p":"对。14 岁拿学习驾照，必须报名参加有认证的驾驶教育。"},"vi":{"q":"Ở Mississippi, thiếu niên 14 tuổi có thể được cấp giấy phép tập lái trong một trường hợp. Đó là trường hợp nào?","o":["Nếu cha mẹ ký một mẫu đơn đặc biệt","Nếu thiếu niên sống ở nông trại","Nếu thiếu niên đậu bài thi với điểm tuyệt đối","Nếu thiếu niên đang ghi danh vào một chương trình giáo dục lái xe được chứng nhận (driver education)"],"h1":"Hãy nghĩ đến một lớp học dạy lái xe.","h2":"Mississippi chỉ cho phép cấp giấy phép tập lái lúc 14 tuổi cho thiếu niên đang ghi danh vào một chương trình giáo dục lái xe được chứng nhận.","p":"Đúng. Lúc 14 tuổi, giấy phép đòi hỏi phải ghi danh học giáo dục lái xe được chứng nhận."},"tl":{"q":"Sa Mississippi, puwedeng makakuha ng learner's permit ang isang 14 taong gulang sa isang kaso lang. Alin ito?","o":["Kung pipirma ang magulang sa isang espesyal na form","Kung nakatira ang kabataan sa bukid","Kung pumasa ang kabataan sa test nang perpekto ang iskor","Kung naka-enroll ang kabataan sa isang sertipikadong programa ng driver education"],"h1":"Isipin ang isang klase na nagtuturo ng pagmamaneho.","h2":"Pinapayagan ng Mississippi ang learner's permit sa edad na 14 para lang sa kabataang naka-enroll sa isang sertipikadong programa ng driver education.","p":"Tama. Sa edad na 14, kailangang naka-enroll sa sertipikadong driver education para sa permit."},"ar":{"q":"في Mississippi، يمكن لشخص عمره 14 سنة أن يحصل على تصريح تعلّم القيادة في حالة واحدة. ما هي؟","o":["إذا وقّع أحد الوالدين على نموذج خاص","إذا كان المراهق يعيش في مزرعة","إذا نجح المراهق في الاختبار بالدرجة الكاملة","إذا كان المراهق مسجلًا في برنامج معتمد لتعليم القيادة (driver education)"],"h1":"فكّر في صف دراسي يعلّم القيادة.","h2":"تسمح Mississippi بتصريح تعلّم القيادة في سن 14 فقط للمراهق المسجل في برنامج معتمد لتعليم القيادة.","p":"صحيح. في سن 14، يتطلب التصريح التسجيل في برنامج معتمد لتعليم القيادة."},"ref":{"doc":"MS","page":null}},{"id":"ms-004","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, who must sit beside a driver with a learner's permit?","o":["Any passenger who is 16 or older","A licensed driver who is at least 18","A licensed driver who is at least 21","A licensed driver who is at least 25"],"h1":"The helper must be an adult old enough to buy alcohol legally.","h2":"In Mississippi, a learner's permit holder must drive with a licensed adult who is at least 21 years old sitting in the front seat.","p":"Right. A licensed driver 21 or older sits in the front seat."},"es":{"q":"En Mississippi, ¿quién debe sentarse al lado de un conductor con permiso de aprendiz?","o":["Cualquier pasajero de 16 años o más","Un conductor con licencia de por lo menos 18 años","Un conductor con licencia de por lo menos 21 años","Un conductor con licencia de por lo menos 25 años"],"h1":"El acompañante debe ser un adulto con edad suficiente para comprar alcohol legalmente.","h2":"En Mississippi, quien tiene permiso de aprendiz debe manejar con un adulto con licencia de por lo menos 21 años sentado en el asiento delantero.","p":"Correcto. Un conductor con licencia de 21 años o más va en el asiento delantero."},"zh":{"q":"在 Mississippi，谁必须坐在持学习驾照的司机旁边？","o":["任何 16 岁或以上的乘客","至少 18 岁、有驾照的司机","至少 21 岁、有驾照的司机","至少 25 岁、有驾照的司机"],"h1":"陪同的人必须是年龄够大、可以合法买酒的成年人。","h2":"在 Mississippi，持学习驾照的人开车时，必须有一位至少 21 岁、有驾照的成年人坐在前排。","p":"对。21 岁或以上、有驾照的司机坐在前排。"},"vi":{"q":"Ở Mississippi, ai phải ngồi bên cạnh người lái có giấy phép tập lái?","o":["Bất kỳ hành khách nào từ 16 tuổi trở lên","Một người có bằng lái ít nhất 18 tuổi","Một người có bằng lái ít nhất 21 tuổi","Một người có bằng lái ít nhất 25 tuổi"],"h1":"Người hướng dẫn phải là người lớn đủ tuổi để mua rượu hợp pháp.","h2":"Ở Mississippi, người có giấy phép tập lái phải lái xe cùng một người lớn có bằng lái, ít nhất 21 tuổi, ngồi ở ghế trước.","p":"Đúng. Một người có bằng lái từ 21 tuổi trở lên ngồi ở ghế trước."},"tl":{"q":"Sa Mississippi, sino ang dapat umupo sa tabi ng driver na may learner's permit?","o":["Kahit sinong pasahero na 16 taong gulang pataas","Isang driver na may lisensya at hindi bababa sa 18 taong gulang","Isang driver na may lisensya at hindi bababa sa 21 taong gulang","Isang driver na may lisensya at hindi bababa sa 25 taong gulang"],"h1":"Dapat ay adult ang tagatulong na nasa sapat na edad para legal na bumili ng alak.","h2":"Sa Mississippi, ang may learner's permit ay dapat magmaneho kasama ang isang adult na may lisensya, hindi bababa sa 21 taong gulang, na nakaupo sa harap.","p":"Tama. Isang driver na may lisensya at 21 taong gulang pataas ang nakaupo sa harap."},"ar":{"q":"في Mississippi، من يجب أن يجلس بجانب السائق الذي يحمل تصريح تعلّم القيادة؟","o":["أي راكب عمره 16 سنة أو أكثر","سائق يحمل رخصة وعمره 18 سنة على الأقل","سائق يحمل رخصة وعمره 21 سنة على الأقل","سائق يحمل رخصة وعمره 25 سنة على الأقل"],"h1":"يجب أن يكون المرافق شخصًا بالغًا بلغ السن القانونية لشراء الكحول.","h2":"في Mississippi، يجب على حامل تصريح تعلّم القيادة أن يقود مع شخص بالغ يحمل رخصة وعمره 21 سنة على الأقل، ويجلس في المقعد الأمامي.","p":"صحيح. يجلس في المقعد الأمامي سائق يحمل رخصة وعمره 21 سنة أو أكثر."},"ref":{"doc":"MS","page":13}},{"id":"ms-005","scope":"MS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Mississippi, a teen has held a learner's permit for one year. What is the youngest age to get a regular driver's license?","o":["15 years old","16 years old","17 years old","18 years old"],"h1":"The permit starts at 15 and must be held for one year.","h2":"In Mississippi, you can get a regular driver's license at 16 if you have held a learner's permit for one year.","p":"Right. With a permit held for one year, you can get a regular license at 16."},"es":{"q":"En Mississippi, un joven ha tenido un permiso de aprendiz por un año. ¿Cuál es la edad mínima para obtener una licencia de conducir regular?","o":["15 años","16 años","17 años","18 años"],"h1":"El permiso empieza a los 15 años y se debe tener por un año.","h2":"En Mississippi, usted puede obtener una licencia de conducir regular a los 16 años si ha tenido un permiso de aprendiz por un año.","p":"Correcto. Con el permiso por un año, puede obtener la licencia regular a los 16."},"zh":{"q":"在 Mississippi，一个青少年已经持有学习驾照一年。最小几岁可以拿到普通驾照？","o":["15 岁","16 岁","17 岁","18 岁"],"h1":"学习驾照从 15 岁开始，而且必须持有一年。","h2":"在 Mississippi，如果你已经持有学习驾照一年，你 16 岁就可以拿到普通驾照。","p":"对。持有学习驾照一年后，你 16 岁就可以拿普通驾照。"},"vi":{"q":"Ở Mississippi, một thiếu niên đã có giấy phép tập lái được một năm. Tuổi nhỏ nhất để được cấp bằng lái thông thường là bao nhiêu?","o":["15 tuổi","16 tuổi","17 tuổi","18 tuổi"],"h1":"Giấy phép tập lái bắt đầu từ 15 tuổi và phải giữ trong một năm.","h2":"Ở Mississippi, bạn có thể được cấp bằng lái thông thường lúc 16 tuổi nếu bạn đã có giấy phép tập lái được một năm.","p":"Đúng. Khi đã giữ giấy phép tập lái một năm, bạn có thể được cấp bằng lái thông thường lúc 16 tuổi."},"tl":{"q":"Sa Mississippi, may learner's permit na ang isang kabataan nang isang taon. Ano ang pinakabatang edad para makakuha ng regular na driver's license?","o":["15 taong gulang","16 taong gulang","17 taong gulang","18 taong gulang"],"h1":"Nagsisimula ang permit sa edad na 15 at dapat itong hawakan nang isang taon.","h2":"Sa Mississippi, puwede kang makakuha ng regular na driver's license sa edad na 16 kung may learner's permit ka na nang isang taon.","p":"Tama. Kapag may permit ka na nang isang taon, puwede kang makakuha ng regular na lisensya sa edad na 16."},"ar":{"q":"في Mississippi، يحمل مراهق تصريح تعلّم القيادة منذ سنة واحدة. ما أصغر سن للحصول على رخصة القيادة العادية؟","o":["15 سنة","16 سنة","17 سنة","18 سنة"],"h1":"يبدأ التصريح في سن 15 ويجب حمله لمدة سنة واحدة.","h2":"في Mississippi، يمكنك الحصول على رخصة القيادة العادية في سن 16 إذا كنت قد حملت تصريح تعلّم القيادة لمدة سنة واحدة.","p":"صحيح. بعد حمل التصريح لمدة سنة واحدة، يمكنك الحصول على رخصة عادية في سن 16."},"ref":{"doc":"MS","page":15}},{"id":"ms-006","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, a 15-year-old gets a learner's permit. How long must the teen hold it before getting a regular driver's license?","o":["Three months","Six months","One year","Two years"],"h1":"Think of a full trip around the calendar.","h2":"In Mississippi, you must hold a learner's permit for one year before you can get a regular driver's license, unless you turn 17 first.","p":"Right. You must hold the permit for one year."},"es":{"q":"En Mississippi, un joven de 15 años obtiene un permiso de aprendiz. ¿Cuánto tiempo debe tenerlo antes de obtener una licencia de conducir regular?","o":["Tres meses","Seis meses","Un año","Dos años"],"h1":"Piense en una vuelta completa al calendario.","h2":"En Mississippi, usted debe tener el permiso de aprendiz por un año antes de obtener una licencia de conducir regular, a menos que cumpla 17 años antes.","p":"Correcto. Debe tener el permiso por un año."},"zh":{"q":"在 Mississippi，一个 15 岁的青少年拿到了学习驾照。在拿普通驾照之前，他必须持有学习驾照多久？","o":["三个月","六个月","一年","两年"],"h1":"想一想日历走完整整一圈。","h2":"在 Mississippi，你必须持有学习驾照一年，才可以拿普通驾照，除非你先满 17 岁。","p":"对。你必须持有学习驾照一年。"},"vi":{"q":"Ở Mississippi, một thiếu niên 15 tuổi được cấp giấy phép tập lái. Thiếu niên đó phải giữ giấy phép bao lâu trước khi được cấp bằng lái thông thường?","o":["Ba tháng","Sáu tháng","Một năm","Hai năm"],"h1":"Hãy nghĩ đến một vòng trọn vẹn của lịch.","h2":"Ở Mississippi, bạn phải giữ giấy phép tập lái một năm trước khi được cấp bằng lái thông thường, trừ khi bạn đủ 17 tuổi trước.","p":"Đúng. Bạn phải giữ giấy phép tập lái một năm."},"tl":{"q":"Sa Mississippi, nakakuha ng learner's permit ang isang 15 taong gulang. Gaano katagal dapat itong hawakan ng kabataan bago makakuha ng regular na driver's license?","o":["Tatlong buwan","Anim na buwan","Isang taon","Dalawang taon"],"h1":"Isipin ang isang buong ikot ng kalendaryo.","h2":"Sa Mississippi, dapat mong hawakan ang learner's permit nang isang taon bago ka makakuha ng regular na driver's license, maliban kung mag-17 ka muna.","p":"Tama. Dapat mong hawakan ang permit nang isang taon."},"ar":{"q":"في Mississippi، حصل مراهق عمره 15 سنة على تصريح تعلّم القيادة. كم يجب أن يحمله قبل الحصول على رخصة القيادة العادية؟","o":["ثلاثة أشهر","ستة أشهر","سنة واحدة","سنتان"],"h1":"فكّر في دورة كاملة للتقويم.","h2":"في Mississippi، يجب أن تحمل تصريح تعلّم القيادة لمدة سنة واحدة قبل أن تحصل على رخصة القيادة العادية، إلا إذا بلغت 17 سنة قبل ذلك.","p":"صحيح. يجب أن تحمل التصريح لمدة سنة واحدة."},"ref":{"doc":"MS","page":13}},{"id":"ms-007","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, a 16-year-old applies for a regular driver's license. How many hours of driving must a parent, teacher or guardian sign that they watched?","o":["10 hours","25 hours","50 hours","100 hours"],"h1":"It is half of one hundred.","h2":"In Mississippi, a driver under 17 needs a signed statement from a parent, teacher or guardian who watched at least 50 hours of driving.","p":"Right. An adult must sign for at least 50 hours of driving."},"es":{"q":"En Mississippi, un joven de 16 años solicita una licencia de conducir regular. ¿Cuántas horas de manejo debe firmar un padre, maestro o tutor que vio?","o":["10 horas","25 horas","50 horas","100 horas"],"h1":"Es la mitad de cien.","h2":"En Mississippi, un conductor menor de 17 años necesita una declaración firmada por un padre, maestro o tutor que vio por lo menos 50 horas de manejo.","p":"Correcto. Un adulto debe firmar por lo menos 50 horas de manejo."},"zh":{"q":"在 Mississippi，一个 16 岁的人申请普通驾照。父母、老师或监护人必须签字证明看过他开车多少小时？","o":["10 小时","25 小时","50 小时","100 小时"],"h1":"这是一百的一半。","h2":"在 Mississippi，未满 17 岁的司机需要一份由父母、老师或监护人签字的声明，证明他们看过至少 50 小时的驾驶。","p":"对。一个成年人必须签字证明至少 50 小时的驾驶。"},"vi":{"q":"Ở Mississippi, một thiếu niên 16 tuổi nộp đơn xin bằng lái thông thường. Cha mẹ, giáo viên hoặc người giám hộ phải ký xác nhận đã theo dõi bao nhiêu giờ lái xe?","o":["10 giờ","25 giờ","50 giờ","100 giờ"],"h1":"Đó là một nửa của một trăm.","h2":"Ở Mississippi, tài xế dưới 17 tuổi cần một bản xác nhận có chữ ký của cha mẹ, giáo viên hoặc người giám hộ đã theo dõi ít nhất 50 giờ lái xe.","p":"Đúng. Một người lớn phải ký xác nhận ít nhất 50 giờ lái xe."},"tl":{"q":"Sa Mississippi, nag-apply ng regular na driver's license ang isang 16 taong gulang. Ilang oras ng pagmamaneho ang dapat pirmahan ng magulang, guro o guardian na nakita nila?","o":["10 oras","25 oras","50 oras","100 oras"],"h1":"Ito ay kalahati ng isang daan.","h2":"Sa Mississippi, ang driver na wala pang 17 ay kailangan ng pinirmahang pahayag mula sa magulang, guro o guardian na nakakita ng hindi bababa sa 50 oras ng pagmamaneho.","p":"Tama. Dapat pumirma ang isang adult para sa hindi bababa sa 50 oras ng pagmamaneho."},"ar":{"q":"في Mississippi، يتقدّم شخص عمره 16 سنة للحصول على رخصة القيادة العادية. كم ساعة من القيادة يجب أن يوقّع أحد الوالدين أو المعلم أو الوصي أنه شاهدها؟","o":["10 ساعات","25 ساعة","50 ساعة","100 ساعة"],"h1":"إنها نصف المئة.","h2":"في Mississippi، يحتاج السائق الذي عمره أقل من 17 سنة إلى إقرار موقّع من أحد الوالدين أو المعلم أو الوصي الذي شاهد 50 ساعة على الأقل من القيادة.","p":"صحيح. يجب أن يوقّع شخص بالغ على 50 ساعة على الأقل من القيادة."},"ref":{"doc":"MS","page":15}},{"id":"ms-008","scope":"MS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Mississippi, which drivers are banned from texting while driving?","o":["Only drivers with a learner's permit","Only drivers under 18","Drivers of every age","Only drivers of school buses"],"h1":"This rule does not depend on age or license type.","h2":"Mississippi bans all drivers from writing, sending or reading text messages while driving.","p":"Right. No driver of any age may text while driving in Mississippi."},"es":{"q":"En Mississippi, ¿a qué conductores se les prohíbe enviar mensajes de texto mientras manejan?","o":["Solo a quienes tienen permiso de aprendiz","Solo a los menores de 18 años","A los conductores de todas las edades","Solo a los choferes de autobús escolar"],"h1":"Esta regla no depende de la edad ni del tipo de licencia.","h2":"Mississippi prohíbe a todos los conductores escribir, enviar o leer mensajes de texto mientras manejan.","p":"Correcto. Ningún conductor, de ninguna edad, puede enviar mensajes mientras maneja en Mississippi."},"zh":{"q":"在 Mississippi，哪些司机开车时禁止发短信？","o":["只有持学习驾照的司机","只有 18 岁以下的司机","所有年龄的司机","只有校车司机"],"h1":"这条规定和年龄或驾照种类无关。","h2":"Mississippi 禁止所有司机在开车时写、发送或阅读短信。","p":"对。在 Mississippi，任何年龄的司机开车时都不能发短信。"},"vi":{"q":"Ở Mississippi, những người lái xe nào bị cấm nhắn tin khi đang lái xe?","o":["Chỉ người có giấy phép tập lái","Chỉ người lái dưới 18 tuổi","Người lái ở mọi lứa tuổi","Chỉ người lái xe buýt trường học"],"h1":"Quy định này không phụ thuộc vào tuổi hay loại bằng lái.","h2":"Mississippi cấm tất cả người lái xe viết, gửi hoặc đọc tin nhắn khi đang lái xe.","p":"Đúng. Ở Mississippi, không người lái nào, ở bất kỳ tuổi nào, được nhắn tin khi lái xe."},"tl":{"q":"Sa Mississippi, aling mga driver ang bawal mag-text habang nagmamaneho?","o":["Ang mga may learner's permit lang","Ang mga driver na wala pang 18 taong gulang lang","Mga driver sa lahat ng edad","Ang mga driver ng school bus lang"],"h1":"Hindi nakadepende ang patakarang ito sa edad o uri ng lisensya.","h2":"Ipinagbabawal ng Mississippi sa lahat ng driver ang pagsulat, pagpapadala o pagbabasa ng text message habang nagmamaneho.","p":"Tama. Walang driver sa anumang edad ang puwedeng mag-text habang nagmamaneho sa Mississippi."},"ar":{"q":"في Mississippi، أي السائقين ممنوعون من كتابة الرسائل النصية أثناء القيادة؟","o":["حاملو تصريح تعلّم القيادة فقط","السائقون الذين أعمارهم أقل من 18 سنة فقط","السائقون من جميع الأعمار","سائقو الحافلات المدرسية فقط"],"h1":"هذه القاعدة لا تعتمد على العمر أو نوع الرخصة.","h2":"تمنع Mississippi جميع السائقين من كتابة الرسائل النصية أو إرسالها أو قراءتها أثناء القيادة.","p":"صحيح. لا يجوز لأي سائق من أي عمر أن يكتب رسائل نصية أثناء القيادة في Mississippi."},"ref":{"doc":"MS","page":23}},{"id":"ms-009","scope":"MS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Mississippi, which of these does the texting law still allow while driving?","o":["Reading a social media post","Using a hands-free or voice-operated device","Sending a short email","Typing a text at a slow speed"],"h1":"Think about using your voice instead of your hands.","h2":"Mississippi's texting law does not apply to hands-free or voice-operated devices, so a driver may still use them while driving.","p":"Right. Hands-free and voice-operated devices are still allowed."},"es":{"q":"En Mississippi, ¿cuál de estas cosas todavía permite la ley de mensajes de texto mientras se maneja?","o":["Leer una publicación en redes sociales","Usar un dispositivo de manos libres o de voz","Enviar un correo corto","Escribir un mensaje despacio"],"h1":"Piense en usar la voz en lugar de las manos.","h2":"La ley de mensajes de texto de Mississippi no se aplica a los dispositivos de manos libres o de voz, así que el conductor todavía puede usarlos mientras maneja.","p":"Correcto. Los dispositivos de manos libres y de voz todavía están permitidos."},"zh":{"q":"在 Mississippi，短信法仍然允许开车时做下面哪一件事？","o":["看社交媒体上的帖子","使用免提或声控设备","发一封短的电子邮件","慢速行驶时打短信"],"h1":"想一想用声音代替用手。","h2":"Mississippi 的短信法不适用于免提或声控设备，所以司机开车时仍然可以使用它们。","p":"对。免提和声控设备仍然可以用。"},"vi":{"q":"Ở Mississippi, luật về nhắn tin vẫn cho phép điều nào sau đây khi đang lái xe?","o":["Đọc một bài đăng trên mạng xã hội","Dùng thiết bị rảnh tay hoặc điều khiển bằng giọng nói","Gửi một email ngắn","Gõ tin nhắn khi chạy chậm"],"h1":"Hãy nghĩ đến việc dùng giọng nói thay vì dùng tay.","h2":"Luật về nhắn tin của Mississippi không áp dụng cho thiết bị rảnh tay hoặc điều khiển bằng giọng nói, nên người lái vẫn có thể dùng chúng khi lái xe.","p":"Đúng. Thiết bị rảnh tay và điều khiển bằng giọng nói vẫn được phép."},"tl":{"q":"Sa Mississippi, alin dito ang pinapayagan pa rin ng batas sa pag-text habang nagmamaneho?","o":["Pagbasa ng post sa social media","Paggamit ng hands-free o voice-operated na device","Pagpapadala ng maikling email","Pag-type ng text habang mabagal ang takbo"],"h1":"Isipin ang paggamit ng boses sa halip na mga kamay.","h2":"Hindi sakop ng batas sa pag-text ng Mississippi ang mga hands-free o voice-operated na device, kaya puwede pa rin itong gamitin ng driver habang nagmamaneho.","p":"Tama. Pinapayagan pa rin ang mga hands-free at voice-operated na device."},"ar":{"q":"في Mississippi، أي من هذه الأمور لا يزال قانون الرسائل النصية يسمح بها أثناء القيادة؟","o":["قراءة منشور على وسائل التواصل الاجتماعي","استخدام جهاز بدون يدين (hands-free) أو جهاز يعمل بالصوت","إرسال بريد إلكتروني قصير","كتابة رسالة نصية أثناء السير ببطء"],"h1":"فكّر في استخدام صوتك بدلًا من يديك.","h2":"قانون الرسائل النصية في Mississippi لا ينطبق على الأجهزة التي تعمل بدون يدين أو بالصوت، لذلك يجوز للسائق أن يستخدمها أثناء القيادة.","p":"صحيح. الأجهزة التي تعمل بدون يدين أو بالصوت لا تزال مسموحة."},"ref":{"doc":"MS","page":23}},{"id":"ms-010","scope":"MS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Mississippi, what blood alcohol level is illegal for a driver under 21?","o":["0.02 percent or higher","0.05 percent or higher","0.08 percent or higher","0.10 percent or higher"],"h1":"It is much lower than the limit for adults.","h2":"Under Mississippi's zero tolerance law, a driver under 21 with a blood alcohol level of 0.02 percent or higher breaks the law.","p":"Right. For drivers under 21, the limit is 0.02 percent."},"es":{"q":"En Mississippi, ¿qué nivel de alcohol en la sangre es ilegal para un conductor menor de 21 años?","o":["0.02 por ciento o más","0.05 por ciento o más","0.08 por ciento o más","0.10 por ciento o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"Según la ley de tolerancia cero de Mississippi, un conductor menor de 21 años con un nivel de alcohol en la sangre de 0.02 por ciento o más viola la ley.","p":"Correcto. Para los menores de 21, el límite es 0.02 por ciento."},"zh":{"q":"在 Mississippi，21 岁以下的司机血液酒精浓度达到多少就违法？","o":["0.02% 或更高","0.05% 或更高","0.08% 或更高","0.10% 或更高"],"h1":"它比成年人的限值低很多。","h2":"根据 Mississippi 的零容忍法，21 岁以下的司机血液酒精浓度达到 0.02% 或更高，就违法。","p":"对。21 岁以下的司机，限值是 0.02%。"},"vi":{"q":"Ở Mississippi, nồng độ cồn trong máu bao nhiêu là bất hợp pháp đối với người lái dưới 21 tuổi?","o":["0.02 phần trăm trở lên","0.05 phần trăm trở lên","0.08 phần trăm trở lên","0.10 phần trăm trở lên"],"h1":"Mức này thấp hơn nhiều so với giới hạn của người lớn.","h2":"Theo luật không khoan nhượng (zero tolerance) của Mississippi, người lái dưới 21 tuổi có nồng độ cồn trong máu từ 0.02 phần trăm trở lên là vi phạm luật.","p":"Đúng. Với người lái dưới 21 tuổi, giới hạn là 0.02 phần trăm."},"tl":{"q":"Sa Mississippi, anong antas ng alak sa dugo ang ilegal para sa driver na wala pang 21 taong gulang?","o":["0.02 porsiyento o higit pa","0.05 porsiyento o higit pa","0.08 porsiyento o higit pa","0.10 porsiyento o higit pa"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon para sa mga adult.","h2":"Sa ilalim ng zero tolerance law ng Mississippi, lumalabag sa batas ang driver na wala pang 21 taong gulang na may antas ng alak sa dugo na 0.02 porsiyento o higit pa.","p":"Tama. Para sa mga driver na wala pang 21, ang limitasyon ay 0.02 porsiyento."},"ar":{"q":"في Mississippi، ما نسبة الكحول في الدم التي تكون غير قانونية للسائق الذي عمره أقل من 21 سنة؟","o":["0.02 بالمئة أو أكثر","0.05 بالمئة أو أكثر","0.08 بالمئة أو أكثر","0.10 بالمئة أو أكثر"],"h1":"إنها أقل بكثير من الحد المسموح للبالغين.","h2":"بموجب قانون عدم التسامح (zero tolerance) في Mississippi، يخالف القانون السائق الذي عمره أقل من 21 سنة إذا كانت نسبة الكحول في دمه 0.02 بالمئة أو أكثر.","p":"صحيح. للسائقين الذين أعمارهم أقل من 21 سنة، الحد هو 0.02 بالمئة."},"ref":{"doc":"MS","page":78}},{"id":"ms-011","scope":"MS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Mississippi, a driver under 21 has a blood alcohol level of 0.08 percent. How is the driver treated?","o":["Only a warning is given","As a minor under the 0.02 rule only","Under the same DUI penalties as adults","Only the parents are fined"],"h1":"At this level, age no longer gives a lighter charge.","h2":"In Mississippi, a driver under 21 with a blood alcohol level of 0.08 percent or higher faces the adult DUI penalties.","p":"Right. At 0.08 percent, a driver under 21 is treated like an adult."},"es":{"q":"En Mississippi, un conductor menor de 21 años tiene un nivel de alcohol en la sangre de 0.08 por ciento. ¿Cómo se le trata?","o":["Solo recibe una advertencia","Solo como menor bajo la regla de 0.02","Con las mismas penas por DUI que los adultos","Solo se multa a los padres"],"h1":"A este nivel, la edad ya no da un cargo más leve.","h2":"En Mississippi, un conductor menor de 21 años con un nivel de alcohol en la sangre de 0.08 por ciento o más recibe las penas de DUI para adultos.","p":"Correcto. Con 0.08 por ciento, el menor de 21 recibe el mismo trato que un adulto."},"zh":{"q":"在 Mississippi，一位 21 岁以下的司机血液酒精浓度是 0.08%。这位司机会被怎样处理？","o":["只给警告","只按未成年人的 0.02 规定处理","按和成年人一样的 DUI 处罚","只罚父母的款"],"h1":"到了这个浓度，年龄不会再让罪名变轻。","h2":"在 Mississippi，21 岁以下的司机血液酒精浓度达到 0.08% 或更高，会受到成年人的 DUI 处罚。","p":"对。到了 0.08%，21 岁以下的司机会被当作成年人处理。"},"vi":{"q":"Ở Mississippi, một người lái dưới 21 tuổi có nồng độ cồn trong máu là 0.08 phần trăm. Người lái này bị xử lý như thế nào?","o":["Chỉ bị cảnh cáo","Chỉ như người vị thành niên theo quy định 0.02","Chịu cùng mức phạt DUI như người lớn","Chỉ cha mẹ bị phạt tiền"],"h1":"Ở mức này, tuổi tác không còn giúp được xử nhẹ hơn.","h2":"Ở Mississippi, người lái dưới 21 tuổi có nồng độ cồn trong máu từ 0.08 phần trăm trở lên sẽ chịu các mức phạt DUI dành cho người lớn.","p":"Đúng. Ở mức 0.08 phần trăm, người lái dưới 21 tuổi bị xử lý như người lớn."},"tl":{"q":"Sa Mississippi, may 0.08 porsiyentong antas ng alak sa dugo ang isang driver na wala pang 21 taong gulang. Paano siya ituturing?","o":["Babala lang ang ibibigay","Bilang menor de edad sa ilalim lang ng 0.02 na patakaran","Sa ilalim ng parehong parusa sa DUI gaya ng mga adult","Ang mga magulang lang ang pagmumultahin"],"h1":"Sa antas na ito, hindi na nagbibigay ng mas magaan na kaso ang edad.","h2":"Sa Mississippi, haharap sa mga parusa sa DUI para sa adult ang driver na wala pang 21 taong gulang na may antas ng alak sa dugo na 0.08 porsiyento o higit pa.","p":"Tama. Sa 0.08 porsiyento, itinuturing na parang adult ang driver na wala pang 21."},"ar":{"q":"في Mississippi، سائق عمره أقل من 21 سنة نسبة الكحول في دمه 0.08 بالمئة. كيف يُعامل هذا السائق؟","o":["يُعطى إنذارًا فقط","كقاصر بموجب قاعدة 0.02 فقط","بنفس عقوبات القيادة تحت تأثير الكحول (DUI) المطبقة على البالغين","يُغرَّم الوالدان فقط"],"h1":"عند هذا المستوى، لم يعد العمر يعطي تهمة أخف.","h2":"في Mississippi، السائق الذي عمره أقل من 21 سنة ونسبة الكحول في دمه 0.08 بالمئة أو أكثر يواجه عقوبات DUI الخاصة بالبالغين.","p":"صحيح. عند 0.08 بالمئة، يُعامل السائق الذي عمره أقل من 21 سنة مثل البالغ."},"ref":{"doc":"MS","page":79}},{"id":"ms-012","scope":"MS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Mississippi, what is the highest speed limit on interstate highways?","o":["60 mph","65 mph","75 mph","70 mph"],"h1":"It is 5 mph above the limit on four-lane state and U.S. highways.","h2":"The highest speed limit on Mississippi interstates is 70 mph, day and night.","p":"Right. Mississippi interstates top out at 70 mph."},"es":{"q":"En Mississippi, ¿cuál es el límite de velocidad más alto en las autopistas interestatales?","o":["60 mph","65 mph","75 mph","70 mph"],"h1":"Es 5 mph más que el límite de las carreteras estatales y federales de cuatro carriles.","h2":"El límite de velocidad más alto en las interestatales de Mississippi es 70 mph, de día y de noche.","p":"Correcto. En las interestatales de Mississippi, el máximo es 70 mph."},"zh":{"q":"在 Mississippi，州际公路的最高限速是多少？","o":["60 英里/小时","65 英里/小时","75 英里/小时","70 英里/小时"],"h1":"它比四车道的州公路和联邦公路（U.S. highway）的限速高 5 英里/小时。","h2":"Mississippi 州际公路的最高限速是 70 英里/小时，白天晚上都一样。","p":"对。Mississippi 州际公路最高 70 英里/小时。"},"vi":{"q":"Ở Mississippi, tốc độ tối đa cao nhất trên xa lộ liên bang (interstate) là bao nhiêu?","o":["60 mph","65 mph","75 mph","70 mph"],"h1":"Mức này cao hơn 5 mph so với giới hạn trên xa lộ tiểu bang và xa lộ U.S. có bốn làn xe.","h2":"Tốc độ tối đa cao nhất trên các xa lộ liên bang ở Mississippi là 70 mph, cả ngày lẫn đêm.","p":"Đúng. Xa lộ liên bang ở Mississippi có tốc độ tối đa là 70 mph."},"tl":{"q":"Sa Mississippi, ano ang pinakamataas na speed limit sa mga interstate highway?","o":["60 mph","65 mph","75 mph","70 mph"],"h1":"5 mph itong mas mataas kaysa sa limitasyon sa mga four-lane na state at U.S. highway.","h2":"Ang pinakamataas na speed limit sa mga interstate ng Mississippi ay 70 mph, araw man o gabi.","p":"Tama. Hanggang 70 mph ang mga interstate ng Mississippi."},"ar":{"q":"في Mississippi، ما أعلى حد للسرعة على الطرق السريعة بين الولايات (interstate)؟","o":["60 mph","65 mph","75 mph","70 mph"],"h1":"إنه أعلى بـ5 mph من الحد على طرق الولاية والطرق الأمريكية (U.S.) ذات الأربعة مسارات.","h2":"أعلى حد للسرعة على الطرق السريعة بين الولايات في Mississippi هو 70 mph، نهارًا وليلًا.","p":"صحيح. أعلى سرعة على الطرق السريعة بين الولايات في Mississippi هي 70 mph."},"ref":{"doc":"MS","page":41}},{"id":"ms-013","scope":"MS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Mississippi, what is the usual maximum speed on a four-lane state or U.S. highway, unless signs show a different limit?","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"It is 10 mph more than on a two-lane highway.","h2":"In Mississippi, the usual maximum speed on a four-lane state or U.S. highway is 65 mph.","p":"Right. Four-lane state and U.S. highways usually have a 65 mph limit."},"es":{"q":"En Mississippi, ¿cuál es la velocidad máxima habitual en una carretera estatal o federal de cuatro carriles, si las señales no indican otra?","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"Es 10 mph más que en una carretera de dos carriles.","h2":"En Mississippi, la velocidad máxima habitual en una carretera estatal o federal de cuatro carriles es 65 mph.","p":"Correcto. Las carreteras estatales y federales de cuatro carriles suelen tener un límite de 65 mph."},"zh":{"q":"在 Mississippi，除非标志显示不同的限速，四车道的州公路或联邦公路（U.S. highway）通常的最高速度是多少？","o":["55 英里/小时","65 英里/小时","70 英里/小时","75 英里/小时"],"h1":"它比双车道公路高 10 英里/小时。","h2":"在 Mississippi，四车道的州公路或联邦公路通常的最高速度是 65 英里/小时。","p":"对。四车道的州公路和联邦公路通常限速 65 英里/小时。"},"vi":{"q":"Ở Mississippi, tốc độ tối đa thông thường trên xa lộ tiểu bang hoặc xa lộ U.S. có bốn làn xe là bao nhiêu, trừ khi biển báo ghi giới hạn khác?","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"Mức này cao hơn 10 mph so với xa lộ có hai làn xe.","h2":"Ở Mississippi, tốc độ tối đa thông thường trên xa lộ tiểu bang hoặc xa lộ U.S. có bốn làn xe là 65 mph.","p":"Đúng. Xa lộ tiểu bang và xa lộ U.S. có bốn làn xe thường có giới hạn 65 mph."},"tl":{"q":"Sa Mississippi, ano ang karaniwang pinakamabilis na takbo sa four-lane na state o U.S. highway, maliban kung iba ang limitasyong ipinapakita ng mga karatula?","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"10 mph itong mas mataas kaysa sa two-lane na highway.","h2":"Sa Mississippi, ang karaniwang pinakamabilis na takbo sa four-lane na state o U.S. highway ay 65 mph.","p":"Tama. Karaniwang 65 mph ang limitasyon sa mga four-lane na state at U.S. highway."},"ar":{"q":"في Mississippi، ما السرعة القصوى المعتادة على طريق ولاية أو طريق أمريكي (U.S.) ذي أربعة مسارات، إلا إذا أظهرت اللافتات حدًا مختلفًا؟","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"إنها أعلى بـ10 mph من الطريق ذي المسارين.","h2":"في Mississippi، السرعة القصوى المعتادة على طريق ولاية أو طريق أمريكي ذي أربعة مسارات هي 65 mph.","p":"صحيح. طرق الولاية والطرق الأمريكية ذات الأربعة مسارات حدها المعتاد 65 mph."},"ref":{"doc":"MS","page":41}},{"id":"ms-015","scope":"MS","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Mississippi, you cannot safely change lanes away from a stopped emergency vehicle with flashing lights. What must you do?","o":["Keep your speed and stay in your lane","Stop completely in your lane","Drive onto the shoulder on the other side","Slow down and be ready to stop"],"h1":"If you cannot add distance, reduce your speed.","h2":"Under Mississippi's move-over law, if you cannot change lanes safely, you must slow to a safe speed and be prepared to stop.","p":"Right. When you cannot move over, slow down and be ready to stop."},"es":{"q":"En Mississippi, usted no puede cambiarse de carril con seguridad para alejarse de un vehículo de emergencia detenido con luces intermitentes. ¿Qué debe hacer?","o":["Mantener la velocidad y seguir en su carril","Detenerse por completo en su carril","Pasar por el acotamiento del otro lado","Reducir la velocidad y estar listo para detenerse"],"h1":"Si no puede alejarse, reduzca la velocidad.","h2":"Según la ley de Mississippi, si usted no puede cambiarse de carril con seguridad, debe reducir a una velocidad segura y estar listo para detenerse.","p":"Correcto. Si no puede moverse de carril, reduzca la velocidad y esté listo para detenerse."},"zh":{"q":"在 Mississippi，你没办法安全地换道，离开一辆停着、闪着灯的急救车辆。你必须怎么做？","o":["保持速度，留在你的车道","在你的车道里完全停车","开到另一边的路肩上","减速，并准备好停车"],"h1":"如果你不能拉开距离，就降低速度。","h2":"根据 Mississippi 的 move-over 法，如果你不能安全换道，就必须减速到安全的速度，并准备好停车。","p":"对。不能让出车道时，就减速并准备停车。"},"vi":{"q":"Ở Mississippi, bạn không thể chuyển làn một cách an toàn để tránh xa một xe cấp cứu đang dừng có đèn nhấp nháy. Bạn phải làm gì?","o":["Giữ nguyên tốc độ và ở lại trong làn của bạn","Dừng hẳn trong làn của bạn","Lái lên lề đường ở phía bên kia","Giảm tốc độ và sẵn sàng dừng lại"],"h1":"Nếu bạn không thể tạo thêm khoảng cách, hãy giảm tốc độ.","h2":"Theo luật nhường làn của Mississippi, nếu bạn không thể chuyển làn an toàn, bạn phải giảm xuống tốc độ an toàn và sẵn sàng dừng lại.","p":"Đúng. Khi không thể nhường làn, hãy giảm tốc độ và sẵn sàng dừng lại."},"tl":{"q":"Sa Mississippi, hindi ka ligtas na makalipat ng lane palayo sa isang nakahintong emergency vehicle na may kumikislap na ilaw. Ano ang dapat mong gawin?","o":["Panatilihin ang bilis at manatili sa iyong lane","Huminto nang tuluyan sa iyong lane","Magmaneho papunta sa shoulder sa kabilang panig","Bagalan ang takbo at maging handang huminto"],"h1":"Kung hindi ka makalayo, bawasan ang bilis mo.","h2":"Sa ilalim ng move-over law ng Mississippi, kung hindi ka ligtas na makalipat ng lane, dapat kang bumagal sa ligtas na bilis at maging handang huminto.","p":"Tama. Kapag hindi ka makalipat, bumagal at maging handang huminto."},"ar":{"q":"في Mississippi، لا يمكنك تغيير المسار بأمان للابتعاد عن مركبة طوارئ متوقفة ذات أضواء وامضة. ماذا يجب أن تفعل؟","o":["حافظ على سرعتك وابقَ في مسارك","توقف تمامًا في مسارك","اذهب إلى كتف الطريق على الجانب الآخر","خفّف سرعتك وكن مستعدًا للتوقف"],"h1":"إذا لم تستطع زيادة المسافة، فخفّف سرعتك.","h2":"بموجب قانون الابتعاد في Mississippi، إذا لم تستطع تغيير المسار بأمان، يجب أن تخفّف سرعتك إلى سرعة آمنة وتكون مستعدًا للتوقف.","p":"صحيح. عندما لا تستطيع الابتعاد، خفّف سرعتك وكن مستعدًا للتوقف."},"ref":{"doc":"MS","page":67}},{"id":"ms-017","scope":"MS","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Mississippi, how far from a stopped school bus must you stop when it is loading or unloading children?","o":["At least 5 feet","At least 10 feet","At least 30 feet","At least 50 feet"],"h1":"It is about the length of one small car.","h2":"Mississippi law requires you to stop at least 10 feet from a school bus that is stopped to pick up or drop off children.","p":"Right. You stop at least 10 feet from the bus."},"es":{"q":"En Mississippi, ¿a qué distancia de un autobús escolar detenido debe detenerse cuando suben o bajan niños?","o":["Por lo menos 5 pies","Por lo menos 10 pies","Por lo menos 30 pies","Por lo menos 50 pies"],"h1":"Es más o menos el largo de un carro pequeño.","h2":"La ley de Mississippi exige que usted se detenga por lo menos a 10 pies de un autobús escolar detenido para recoger o dejar niños.","p":"Correcto. Usted se detiene por lo menos a 10 pies del autobús."},"zh":{"q":"在 Mississippi，校车停下来让孩子上下车时，你必须在离校车多远的地方停车？","o":["至少 5 英尺","至少 10 英尺","至少 30 英尺","至少 50 英尺"],"h1":"大约是一辆小汽车的长度。","h2":"Mississippi 法律要求你在离停下来接送孩子的校车至少 10 英尺的地方停车。","p":"对。你要在离校车至少 10 英尺的地方停车。"},"vi":{"q":"Ở Mississippi, bạn phải dừng cách xe buýt trường học đang dừng bao xa khi xe đang đón hoặc trả học sinh?","o":["Ít nhất 5 feet","Ít nhất 10 feet","Ít nhất 30 feet","Ít nhất 50 feet"],"h1":"Khoảng cách này bằng chiều dài của một chiếc xe hơi nhỏ.","h2":"Luật Mississippi yêu cầu bạn dừng cách ít nhất 10 feet so với xe buýt trường học đang dừng để đón hoặc trả học sinh.","p":"Đúng. Bạn dừng cách xe buýt ít nhất 10 feet."},"tl":{"q":"Sa Mississippi, gaano kalayo ka dapat huminto mula sa nakahintong school bus kapag nagsasakay o nagbababa ito ng mga bata?","o":["Hindi bababa sa 5 feet","Hindi bababa sa 10 feet","Hindi bababa sa 30 feet","Hindi bababa sa 50 feet"],"h1":"Halos kasinghaba ito ng isang maliit na kotse.","h2":"Ayon sa batas ng Mississippi, dapat kang huminto nang hindi bababa sa 10 feet mula sa school bus na nakahinto para magsakay o magbaba ng mga bata.","p":"Tama. Huminto ka nang hindi bababa sa 10 feet mula sa bus."},"ar":{"q":"في Mississippi، على أي مسافة يجب أن تتوقف من حافلة مدرسية متوقفة عندما تُركب الأطفال أو تُنزلهم؟","o":["5 feet على الأقل","10 feet على الأقل","30 feet على الأقل","50 feet على الأقل"],"h1":"إنها تقريبًا طول سيارة صغيرة واحدة.","h2":"يُلزمك قانون Mississippi بالتوقف على بعد 10 feet على الأقل من الحافلة المدرسية المتوقفة لإركاب الأطفال أو إنزالهم.","p":"صحيح. تتوقف على بعد 10 feet على الأقل من الحافلة."},"ref":{"doc":"MS","page":58}},{"id":"ms-018","scope":"MS","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Mississippi, you are on a divided highway with two lanes in each direction. A school bus on the other side stops with its red lights flashing. What must you do?","o":["You may keep going with care","Stop until the bus moves","Stop, then pass at 10 mph","Move to the left lane and stop"],"h1":"A physical divider separates you from the children's side.","h2":"In Mississippi, on a divided highway with at least two lanes in each direction, drivers on the other side do not have to stop for a stopped school bus, but should still drive with care.","p":"Right. On a divided highway, the opposite side may keep going with care."},"es":{"q":"En Mississippi, usted va por una carretera dividida con dos carriles en cada sentido. Un autobús escolar del otro lado se detiene con las luces rojas intermitentes. ¿Qué debe hacer?","o":["Puede seguir con cuidado","Detenerse hasta que el autobús avance","Detenerse y luego pasar a 10 mph","Pasarse al carril izquierdo y detenerse"],"h1":"Una división física lo separa del lado de los niños.","h2":"En Mississippi, en una carretera dividida con por lo menos dos carriles en cada sentido, los conductores del otro lado no tienen que detenerse ante un autobús escolar detenido, pero deben manejar con cuidado.","p":"Correcto. En una carretera dividida, el lado contrario puede seguir con cuidado."},"zh":{"q":"在 Mississippi，你在每个方向有两条车道的分隔公路上。另一边的一辆校车停下来，闪着红灯。你必须怎么做？","o":["你可以小心地继续开","停车，直到校车开走","停车，然后用 10 英里/小时开过去","换到左车道并停车"],"h1":"有一个实体隔离把你和孩子那一边分开。","h2":"在 Mississippi，在每个方向至少有两条车道的分隔公路上，另一边的司机不必为停着的校车停车，但仍然要小心开。","p":"对。在分隔公路上，对面的车可以小心地继续开。"},"vi":{"q":"Ở Mississippi, bạn đang ở trên xa lộ có dải phân cách với hai làn xe mỗi chiều. Một xe buýt trường học ở chiều bên kia dừng lại và bật đèn đỏ nhấp nháy. Bạn phải làm gì?","o":["Bạn có thể tiếp tục đi nhưng phải cẩn thận","Dừng lại cho đến khi xe buýt chạy","Dừng lại, rồi vượt qua với tốc độ 10 mph","Chuyển sang làn bên trái và dừng lại"],"h1":"Một dải phân cách tách bạn khỏi phía có trẻ em.","h2":"Ở Mississippi, trên xa lộ có dải phân cách với ít nhất hai làn xe mỗi chiều, người lái ở chiều bên kia không phải dừng lại cho xe buýt trường học đang dừng, nhưng vẫn phải lái xe cẩn thận.","p":"Đúng. Trên xa lộ có dải phân cách, xe ở chiều bên kia có thể tiếp tục đi một cách cẩn thận."},"tl":{"q":"Sa Mississippi, nasa divided highway ka na may dalawang lane sa bawat direksyon. Huminto ang isang school bus sa kabilang panig at kumikislap ang pulang ilaw nito. Ano ang dapat mong gawin?","o":["Puwede kang magpatuloy nang maingat","Huminto hanggang umandar ang bus","Huminto, pagkatapos ay lumampas sa 10 mph","Lumipat sa kaliwang lane at huminto"],"h1":"May harang na naghihiwalay sa iyo mula sa panig ng mga bata.","h2":"Sa Mississippi, sa divided highway na may hindi bababa sa dalawang lane sa bawat direksyon, hindi kailangang huminto ng mga driver sa kabilang panig para sa nakahintong school bus, pero dapat pa rin silang magmaneho nang maingat.","p":"Tama. Sa divided highway, puwedeng magpatuloy nang maingat ang mga sasakyan sa kabilang panig."},"ar":{"q":"في Mississippi، أنت على طريق سريع مقسوم فيه مساران في كل اتجاه. حافلة مدرسية على الجانب الآخر تتوقف وأضواؤها الحمراء تومض. ماذا يجب أن تفعل؟","o":["يجوز لك أن تستمر بحذر","توقف حتى تتحرك الحافلة","توقف، ثم تجاوزها بسرعة 10 mph","انتقل إلى المسار الأيسر وتوقف"],"h1":"هناك فاصل يفصلك عن جانب الأطفال.","h2":"في Mississippi، على الطريق السريع المقسوم الذي فيه مساران على الأقل في كل اتجاه، لا يلزم السائقين على الجانب الآخر أن يتوقفوا للحافلة المدرسية المتوقفة، لكن يجب عليهم أن يقودوا بحذر.","p":"صحيح. على الطريق المقسوم، يجوز لمن في الاتجاه المعاكس أن يستمروا بحذر."},"ref":{"doc":"MS","page":58}},{"id":"ms-019","scope":"MS","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Mississippi, a school bus stops on a divided highway with a median. You are driving behind it, in the same direction. What must you do?","o":["Pass it on the left with care","Pass it on the right shoulder","Slow to 15 mph and pass","Stop until it moves again"],"h1":"The median protects only the drivers on the other side.","h2":"In Mississippi, when a school bus stops on a divided highway, drivers going the same direction as the bus must stop.","p":"Right. Traffic behind the bus must always stop."},"es":{"q":"En Mississippi, un autobús escolar se detiene en una carretera dividida con una franja central. Usted va detrás, en el mismo sentido. ¿Qué debe hacer?","o":["Pasarlo por la izquierda con cuidado","Pasarlo por el acotamiento derecho","Reducir a 15 mph y pasar","Detenerse hasta que vuelva a avanzar"],"h1":"La franja central solo protege a los conductores del otro lado.","h2":"En Mississippi, cuando un autobús escolar se detiene en una carretera dividida, los conductores que van en el mismo sentido que el autobús deben detenerse.","p":"Correcto. El tráfico que va detrás del autobús siempre debe detenerse."},"zh":{"q":"在 Mississippi，一辆校车在有中央隔离带的分隔公路上停下。你在它后面，同方向行驶。你必须怎么做？","o":["小心地从左边超过去","从右边路肩超过去","减速到 15 英里/小时再超过去","停车，直到它再开动"],"h1":"中央隔离带只保护另一边的司机。","h2":"在 Mississippi，校车在分隔公路上停下时，和校车同方向的司机必须停车。","p":"对。校车后面的车一定要停。"},"vi":{"q":"Ở Mississippi, một xe buýt trường học dừng lại trên xa lộ có dải phân cách ở giữa. Bạn đang lái phía sau xe buýt, cùng chiều. Bạn phải làm gì?","o":["Vượt qua bên trái một cách cẩn thận","Vượt qua bằng lề đường bên phải","Giảm xuống 15 mph rồi vượt qua","Dừng lại cho đến khi xe buýt chạy tiếp"],"h1":"Dải phân cách chỉ bảo vệ người lái ở chiều bên kia.","h2":"Ở Mississippi, khi xe buýt trường học dừng trên xa lộ có dải phân cách, người lái đi cùng chiều với xe buýt phải dừng lại.","p":"Đúng. Xe phía sau xe buýt luôn phải dừng lại."},"tl":{"q":"Sa Mississippi, huminto ang isang school bus sa divided highway na may median. Nagmamaneho ka sa likod nito, sa parehong direksyon. Ano ang dapat mong gawin?","o":["Lampasan ito sa kaliwa nang maingat","Lampasan ito sa kanang shoulder","Bumagal sa 15 mph at lumampas","Huminto hanggang umandar itong muli"],"h1":"Ang median ay nagpoprotekta lang sa mga driver sa kabilang panig.","h2":"Sa Mississippi, kapag huminto ang school bus sa divided highway, dapat huminto ang mga driver na papunta sa parehong direksyon ng bus.","p":"Tama. Laging dapat huminto ang mga sasakyan sa likod ng bus."},"ar":{"q":"في Mississippi، تتوقف حافلة مدرسية على طريق سريع مقسوم فيه فاصل في الوسط. أنت تقود خلفها، في نفس الاتجاه. ماذا يجب أن تفعل؟","o":["تجاوزها من اليسار بحذر","تجاوزها من كتف الطريق الأيمن","خفّف سرعتك إلى 15 mph وتجاوزها","توقف حتى تتحرك مرة أخرى"],"h1":"الفاصل يحمي السائقين على الجانب الآخر فقط.","h2":"في Mississippi، عندما تتوقف حافلة مدرسية على طريق سريع مقسوم، يجب على السائقين الذين يسيرون في نفس اتجاه الحافلة أن يتوقفوا.","p":"صحيح. يجب على السيارات خلف الحافلة أن تتوقف دائمًا."},"ref":{"doc":"MS","page":58}},{"id":"ms-022","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, what is the minimum liability insurance a driver must carry?","o":["$25,000 / $50,000 / $25,000","$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000"],"h1":"The first and last numbers are the same.","h2":"Mississippi requires at least $25,000 for injury to one person, $50,000 for injuries in one crash, and $25,000 for property damage.","p":"Right. The Mississippi minimum is 25, 50 and 25 thousand dollars."},"es":{"q":"En Mississippi, ¿cuál es el seguro mínimo de responsabilidad civil que debe tener un conductor?","o":["$25,000 / $50,000 / $25,000","$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000"],"h1":"El primer número y el último son iguales.","h2":"Mississippi exige por lo menos $25,000 por lesiones a una persona, $50,000 por lesiones en un choque y $25,000 por daños a la propiedad.","p":"Correcto. El mínimo en Mississippi es de 25, 50 y 25 mil dólares."},"zh":{"q":"在 Mississippi，司机必须买的最低责任保险是多少？","o":["$25,000 / $50,000 / $25,000","$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000"],"h1":"第一个和最后一个数字一样。","h2":"Mississippi 要求一个人受伤至少 $25,000，一次车祸中的伤害至少 $50,000，财产损失至少 $25,000。","p":"对。Mississippi 的最低标准是 25、50 和 25 千美元。"},"vi":{"q":"Ở Mississippi, người lái xe phải có bảo hiểm trách nhiệm (liability insurance) tối thiểu là bao nhiêu?","o":["$25,000 / $50,000 / $25,000","$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000"],"h1":"Số đầu tiên và số cuối cùng giống nhau.","h2":"Mississippi yêu cầu ít nhất $25,000 cho thương tích của một người, $50,000 cho thương tích trong một vụ tai nạn, và $25,000 cho thiệt hại tài sản.","p":"Đúng. Mức tối thiểu ở Mississippi là 25, 50 và 25 nghìn đô la."},"tl":{"q":"Sa Mississippi, ano ang pinakamababang liability insurance na dapat mayroon ang isang driver?","o":["$25,000 / $50,000 / $25,000","$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000"],"h1":"Pareho ang una at huling numero.","h2":"Hinihingi ng Mississippi ang hindi bababa sa $25,000 para sa pagkasugat ng isang tao, $50,000 para sa mga pagkasugat sa isang aksidente, at $25,000 para sa pinsala sa ari-arian.","p":"Tama. Ang minimum sa Mississippi ay 25, 50 at 25 libong dolyar."},"ar":{"q":"في Mississippi، ما الحد الأدنى من تأمين المسؤولية (liability insurance) الذي يجب أن يكون لدى السائق؟","o":["$25,000 / $50,000 / $25,000","$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000"],"h1":"الرقم الأول والرقم الأخير متساويان.","h2":"تشترط Mississippi ما لا يقل عن $25,000 لإصابة شخص واحد، و$50,000 للإصابات في حادث واحد، و$25,000 للأضرار بالممتلكات.","p":"صحيح. الحد الأدنى في Mississippi هو 25 و50 و25 ألف دولار."},"ref":{"doc":"MS","page":76}},{"id":"ms-023","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, how long is a regular learner's permit valid?","o":["Six months","One year","Two years","Four years"],"h1":"It lasts longer than the one year you must hold it.","h2":"In Mississippi, a regular learner's permit is valid for two years.","p":"Right. The learner's permit is good for two years."},"es":{"q":"En Mississippi, ¿por cuánto tiempo es válido un permiso de aprendiz regular?","o":["Seis meses","Un año","Dos años","Cuatro años"],"h1":"Dura más que el año que usted debe tenerlo.","h2":"En Mississippi, el permiso de aprendiz regular es válido por dos años.","p":"Correcto. El permiso de aprendiz es válido por dos años."},"zh":{"q":"在 Mississippi，普通学习驾照（learner's permit）的有效期是多久？","o":["六个月","一年","两年","四年"],"h1":"它比你必须持有学习驾照的一年更长。","h2":"在 Mississippi，普通学习驾照的有效期是两年。","p":"对。学习驾照两年内有效。"},"vi":{"q":"Ở Mississippi, giấy phép tập lái thông thường (learner's permit) có giá trị trong bao lâu?","o":["Sáu tháng","Một năm","Hai năm","Bốn năm"],"h1":"Thời hạn này dài hơn một năm mà bạn phải giữ giấy phép.","h2":"Ở Mississippi, giấy phép tập lái thông thường có giá trị trong hai năm.","p":"Đúng. Giấy phép tập lái có giá trị trong hai năm."},"tl":{"q":"Sa Mississippi, gaano katagal valid ang regular na learner's permit?","o":["Anim na buwan","Isang taon","Dalawang taon","Apat na taon"],"h1":"Mas matagal ito kaysa sa isang taon na dapat mong hawakan ito.","h2":"Sa Mississippi, valid ang regular na learner's permit nang dalawang taon.","p":"Tama. Valid ang learner's permit nang dalawang taon."},"ar":{"q":"في Mississippi، ما مدة صلاحية تصريح تعلّم القيادة العادي (learner's permit)؟","o":["ستة أشهر","سنة واحدة","سنتان","أربع سنوات"],"h1":"مدته أطول من السنة الواحدة التي يجب أن تحمله فيها.","h2":"في Mississippi، تصريح تعلّم القيادة العادي صالح لمدة سنتين.","p":"صحيح. تصريح تعلّم القيادة صالح لمدة سنتين."},"ref":{"doc":"MS","page":13}},{"id":"ms-024","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, you move here with a license from another state. How soon must you get a Mississippi driver's license?","o":["Within 60 days","Within 10 days","Within 6 months","Within 1 year"],"h1":"You have about two months.","h2":"In Mississippi, a new resident must get a Mississippi driver's license within 60 days of moving here.","p":"Right. New residents have 60 days to get a Mississippi license."},"es":{"q":"En Mississippi, usted se muda aquí con una licencia de otro estado. ¿En cuánto tiempo debe obtener una licencia de conducir de Mississippi?","o":["En un plazo de 60 días","En un plazo de 10 días","En un plazo de 6 meses","En un plazo de 1 año"],"h1":"Tiene unos dos meses.","h2":"En Mississippi, un nuevo residente debe obtener una licencia de conducir de Mississippi dentro de los 60 días después de mudarse aquí.","p":"Correcto. Los nuevos residentes tienen 60 días para obtener una licencia de Mississippi."},"zh":{"q":"在 Mississippi，你搬来这里时有别的州的驾照。你必须在多长时间内拿到 Mississippi 驾照？","o":["60 天内","10 天内","6 个月内","1 年内"],"h1":"你大约有两个月。","h2":"在 Mississippi，新居民必须在搬来后 60 天内拿到 Mississippi 驾照。","p":"对。新居民有 60 天的时间拿 Mississippi 驾照。"},"vi":{"q":"Ở Mississippi, bạn chuyển đến đây với bằng lái của một tiểu bang khác. Bạn phải lấy bằng lái Mississippi trong thời gian bao lâu?","o":["Trong vòng 60 ngày","Trong vòng 10 ngày","Trong vòng 6 tháng","Trong vòng 1 năm"],"h1":"Bạn có khoảng hai tháng.","h2":"Ở Mississippi, cư dân mới phải lấy bằng lái Mississippi trong vòng 60 ngày sau khi chuyển đến đây.","p":"Đúng. Cư dân mới có 60 ngày để lấy bằng lái Mississippi."},"tl":{"q":"Sa Mississippi, lumipat ka rito na may lisensya mula sa ibang state. Gaano kabilis ka dapat kumuha ng Mississippi driver's license?","o":["Sa loob ng 60 araw","Sa loob ng 10 araw","Sa loob ng 6 na buwan","Sa loob ng 1 taon"],"h1":"Mayroon kang mga dalawang buwan.","h2":"Sa Mississippi, dapat kumuha ng Mississippi driver's license ang bagong residente sa loob ng 60 araw mula nang lumipat dito.","p":"Tama. May 60 araw ang mga bagong residente para kumuha ng Mississippi license."},"ar":{"q":"في Mississippi، انتقلت إلى هنا ومعك رخصة من ولاية أخرى. خلال كم من الوقت يجب أن تحصل على رخصة قيادة من Mississippi؟","o":["خلال 60 يومًا","خلال 10 أيام","خلال 6 أشهر","خلال سنة واحدة"],"h1":"لديك شهران تقريبًا.","h2":"في Mississippi، يجب على المقيم الجديد أن يحصل على رخصة قيادة من Mississippi خلال 60 يومًا من انتقاله إلى هنا.","p":"صحيح. لدى المقيمين الجدد 60 يومًا للحصول على رخصة من Mississippi."},"ref":{"doc":"MS","page":11}},{"id":"ms-025","scope":"MS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Mississippi, you have a crash and no one is hurt. When must you report it to the police right away?","o":["Only if the other driver asks you to","Only if a car must be towed","Only if it happens on an interstate","If the damage looks like more than $500"],"h1":"It depends on the dollar amount of the damage.","h2":"In Mississippi, you must report a crash to the police right away if anyone is hurt or killed, or if the damage looks like more than $500.","p":"Right. Damage over $500 must be reported right away."},"es":{"q":"En Mississippi, usted tiene un choque y nadie resulta herido. ¿Cuándo debe reportarlo a la policía de inmediato?","o":["Solo si el otro conductor se lo pide","Solo si hay que remolcar un vehículo","Solo si ocurre en una autopista interestatal","Si los daños parecen ser de más de $500"],"h1":"Depende de la cantidad en dólares de los daños.","h2":"En Mississippi, usted debe reportar un choque a la policía de inmediato si alguien resulta herido o muerto, o si los daños parecen ser de más de $500.","p":"Correcto. Los daños de más de $500 se deben reportar de inmediato."},"zh":{"q":"在 Mississippi，你出了车祸，没有人受伤。什么时候你必须马上向警察报告？","o":["只有另一位司机要求你报告时","只有车必须被拖走时","只有在州际公路上发生时","如果损失看起来超过 $500"],"h1":"这取决于损失的金额。","h2":"在 Mississippi，如果有人受伤或死亡，或者损失看起来超过 $500，你必须马上向警察报告车祸。","p":"对。损失超过 $500 必须马上报告。"},"vi":{"q":"Ở Mississippi, bạn bị tai nạn và không ai bị thương. Khi nào bạn phải báo ngay cho cảnh sát?","o":["Chỉ khi người lái kia yêu cầu bạn báo","Chỉ khi có xe phải bị kéo đi","Chỉ khi tai nạn xảy ra trên xa lộ liên bang","Nếu thiệt hại có vẻ hơn $500"],"h1":"Điều này phụ thuộc vào số tiền thiệt hại.","h2":"Ở Mississippi, bạn phải báo ngay cho cảnh sát về tai nạn nếu có người bị thương hoặc tử vong, hoặc nếu thiệt hại có vẻ hơn $500.","p":"Đúng. Thiệt hại hơn $500 phải được báo ngay."},"tl":{"q":"Sa Mississippi, naaksidente ka at walang nasaktan. Kailan mo ito dapat iulat agad sa pulis?","o":["Kung hihilingin lang ito ng ibang driver","Kung kailangan lang hilahin ang isang sasakyan","Kung nangyari lang ito sa interstate","Kung mukhang higit sa $500 ang pinsala"],"h1":"Nakadepende ito sa halaga ng pinsala sa dolyar.","h2":"Sa Mississippi, dapat mong iulat agad sa pulis ang aksidente kung may nasaktan o namatay, o kung mukhang higit sa $500 ang pinsala.","p":"Tama. Dapat iulat agad ang pinsalang higit sa $500."},"ar":{"q":"في Mississippi، وقع لك حادث ولم يُصب أحد. متى يجب أن تبلّغ الشرطة عنه فورًا؟","o":["فقط إذا طلب منك السائق الآخر ذلك","فقط إذا كان يجب سحب سيارة","فقط إذا وقع على طريق سريع بين الولايات (interstate)","إذا بدا أن الضرر أكثر من $500"],"h1":"يعتمد ذلك على قيمة الضرر بالدولار.","h2":"في Mississippi، يجب أن تبلّغ الشرطة عن الحادث فورًا إذا أُصيب أحد أو مات، أو إذا بدا أن الضرر أكثر من $500.","p":"صحيح. يجب الإبلاغ فورًا عن الضرر الذي يزيد على $500."},"ref":{"doc":"MS","page":66}},{"id":"ms-026","scope":"MS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Mississippi, which children must ride in a child car seat?","o":["Children under 2","Children under 4","Children under 8","Children under 10"],"h1":"Think of a preschool child who is not yet old enough for a booster seat.","h2":"In Mississippi, a child under 4 years old must ride in a child car seat that meets safety standards.","p":"Right. Children under 4 must be in a car seat."},"es":{"q":"En Mississippi, ¿qué niños deben viajar en un asiento de seguridad para niños?","o":["Los menores de 2 años","Los menores de 4 años","Los menores de 8 años","Los menores de 10 años"],"h1":"Piense en un niño en edad preescolar que todavía no tiene edad para un asiento elevado.","h2":"En Mississippi, un niño menor de 4 años debe viajar en un asiento de seguridad para niños que cumpla las normas de seguridad.","p":"Correcto. Los niños menores de 4 años deben ir en un asiento de seguridad."},"zh":{"q":"在 Mississippi，哪些孩子必须坐儿童汽车座椅？","o":["2 岁以下的孩子","4 岁以下的孩子","8 岁以下的孩子","10 岁以下的孩子"],"h1":"想一想一个还没到可以用加高座椅（booster seat）年龄的学龄前孩子。","h2":"在 Mississippi，4 岁以下的孩子必须坐符合安全标准的儿童汽车座椅。","p":"对。4 岁以下的孩子必须坐儿童汽车座椅。"},"vi":{"q":"Ở Mississippi, những trẻ em nào phải ngồi ghế an toàn cho trẻ em trên xe?","o":["Trẻ em dưới 2 tuổi","Trẻ em dưới 4 tuổi","Trẻ em dưới 8 tuổi","Trẻ em dưới 10 tuổi"],"h1":"Hãy nghĩ đến một trẻ mẫu giáo chưa đủ lớn để ngồi ghế nâng (booster seat).","h2":"Ở Mississippi, trẻ em dưới 4 tuổi phải ngồi ghế an toàn cho trẻ em đạt tiêu chuẩn an toàn.","p":"Đúng. Trẻ em dưới 4 tuổi phải ngồi ghế an toàn cho trẻ em."},"tl":{"q":"Sa Mississippi, aling mga bata ang dapat nakaupo sa child car seat?","o":["Mga batang wala pang 2 taong gulang","Mga batang wala pang 4 taong gulang","Mga batang wala pang 8 taong gulang","Mga batang wala pang 10 taong gulang"],"h1":"Isipin ang isang batang preschool na hindi pa sapat ang edad para sa booster seat.","h2":"Sa Mississippi, ang batang wala pang 4 taong gulang ay dapat nakaupo sa child car seat na pumapasa sa mga pamantayan sa kaligtasan.","p":"Tama. Dapat nasa car seat ang mga batang wala pang 4 taong gulang."},"ar":{"q":"في Mississippi، أي الأطفال يجب أن يجلسوا في مقعد سيارة خاص بالأطفال؟","o":["الأطفال الذين أعمارهم أقل من سنتين","الأطفال الذين أعمارهم أقل من 4 سنوات","الأطفال الذين أعمارهم أقل من 8 سنوات","الأطفال الذين أعمارهم أقل من 10 سنوات"],"h1":"فكّر في طفل في سن ما قبل المدرسة لم يكبر بعد بما يكفي لمقعد الرفع (booster seat).","h2":"في Mississippi، يجب أن يجلس الطفل الذي عمره أقل من 4 سنوات في مقعد سيارة خاص بالأطفال يستوفي معايير السلامة.","p":"صحيح. يجب أن يجلس الأطفال الذين أعمارهم أقل من 4 سنوات في مقعد سيارة خاص بالأطفال."},"ref":{"doc":"MS","page":64}},{"id":"ms-027","scope":"MS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Mississippi, a 5-year-old is 4 feet tall and weighs 45 pounds. What must the child ride in?","o":["An adult seat belt alone","A lap belt in the front seat","A belt-positioning booster seat","Nothing, if the child sits in the back"],"h1":"The child is too small for an adult belt alone.","h2":"In Mississippi, a child from 4 to 6 years old who is shorter than 4 feet 9 inches or weighs under 65 pounds must ride in a belt-positioning booster seat.","p":"Right. This child must use a booster seat."},"es":{"q":"En Mississippi, un niño de 5 años mide 4 pies y pesa 45 libras. ¿En qué debe viajar el niño?","o":["Solo con el cinturón de seguridad de adulto","Con un cinturón de regazo en el asiento delantero","En un asiento elevado (booster) que posiciona el cinturón","En nada, si el niño va en el asiento trasero"],"h1":"El niño es demasiado pequeño para usar solo el cinturón de adulto.","h2":"En Mississippi, un niño de 4 a 6 años que mide menos de 4 pies y 9 pulgadas o pesa menos de 65 libras debe viajar en un asiento elevado (booster) que posiciona el cinturón.","p":"Correcto. Este niño debe usar un asiento elevado."},"zh":{"q":"在 Mississippi，一个 5 岁的孩子身高 4 英尺，体重 45 磅。这个孩子必须坐什么？","o":["只用成年人的安全带","前排的腰部安全带","调整安全带位置的加高座椅（booster seat）","什么都不用，只要孩子坐在后排"],"h1":"这个孩子太小，不能只用成年人的安全带。","h2":"在 Mississippi，4 到 6 岁、身高不到 4 英尺 9 英寸或体重不到 65 磅的孩子，必须坐调整安全带位置的加高座椅。","p":"对。这个孩子必须用加高座椅。"},"vi":{"q":"Ở Mississippi, một em bé 5 tuổi cao 4 feet và nặng 45 pounds. Em bé phải ngồi gì?","o":["Chỉ dây an toàn của người lớn","Dây an toàn ngang hông ở ghế trước","Ghế nâng định vị dây an toàn (booster seat)","Không cần gì, nếu em bé ngồi ở ghế sau"],"h1":"Em bé quá nhỏ để chỉ dùng dây an toàn của người lớn.","h2":"Ở Mississippi, trẻ em từ 4 đến 6 tuổi cao dưới 4 feet 9 inches hoặc nặng dưới 65 pounds phải ngồi ghế nâng định vị dây an toàn.","p":"Đúng. Em bé này phải dùng ghế nâng."},"tl":{"q":"Sa Mississippi, 4 feet ang taas at 45 pounds ang bigat ng isang 5 taong gulang na bata. Saan dapat nakaupo ang bata?","o":["Seat belt lang ng adult","Lap belt sa harapang upuan","Belt-positioning booster seat","Wala, kung sa likod nakaupo ang bata"],"h1":"Masyadong maliit ang bata para sa seat belt lang ng adult.","h2":"Sa Mississippi, ang batang 4 hanggang 6 taong gulang na mas maikli sa 4 feet 9 inches o mas magaan sa 65 pounds ay dapat nakaupo sa belt-positioning booster seat.","p":"Tama. Dapat gumamit ng booster seat ang batang ito."},"ar":{"q":"في Mississippi، طفل عمره 5 سنوات طوله 4 feet ووزنه 45 pounds. في ماذا يجب أن يجلس هذا الطفل؟","o":["حزام أمان البالغين وحده","حزام حضن في المقعد الأمامي","مقعد رفع يضبط وضع الحزام (booster seat)","لا شيء، إذا جلس الطفل في الخلف"],"h1":"الطفل أصغر من أن يستخدم حزام أمان البالغين وحده.","h2":"في Mississippi، الطفل الذي عمره من 4 إلى 6 سنوات وطوله أقل من 4 feet و9 inches أو وزنه أقل من 65 pounds يجب أن يجلس في مقعد رفع يضبط وضع الحزام.","p":"صحيح. يجب أن يستخدم هذا الطفل مقعد رفع."},"ref":{"doc":"MS","page":64}},{"id":"ms-028","scope":"MS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Mississippi, you refuse a breath test when an officer asks. For how long is your license suspended?","o":["90 days","30 days","10 days","5 years"],"h1":"It is about three months.","h2":"In Mississippi, refusing a breath or chemical test leads to a 90-day license suspension.","p":"Right. Refusing the test means a 90-day suspension."},"es":{"q":"En Mississippi, usted se niega a hacer la prueba de aliento cuando un oficial se lo pide. ¿Por cuánto tiempo se suspende su licencia?","o":["90 días","30 días","10 días","5 años"],"h1":"Son unos tres meses.","h2":"En Mississippi, negarse a una prueba de aliento o química lleva a una suspensión de la licencia por 90 días.","p":"Correcto. Negarse a la prueba significa una suspensión de 90 días."},"zh":{"q":"在 Mississippi，警察要求你做呼气测试，你拒绝了。你的驾照会被暂停多久？","o":["90 天","30 天","10 天","5 年"],"h1":"大约三个月。","h2":"在 Mississippi，拒绝呼气测试或化学测试会导致驾照被暂停 90 天。","p":"对。拒绝测试就会被暂停 90 天。"},"vi":{"q":"Ở Mississippi, bạn từ chối thổi kiểm tra hơi thở khi cảnh sát yêu cầu. Bằng lái của bạn bị đình chỉ trong bao lâu?","o":["90 ngày","30 ngày","10 ngày","5 năm"],"h1":"Khoảng ba tháng.","h2":"Ở Mississippi, từ chối kiểm tra hơi thở hoặc kiểm tra hóa học sẽ bị đình chỉ bằng lái 90 ngày.","p":"Đúng. Từ chối kiểm tra nghĩa là bị đình chỉ 90 ngày."},"tl":{"q":"Sa Mississippi, tumanggi ka sa breath test nang hilingin ito ng pulis. Gaano katagal masususpinde ang lisensya mo?","o":["90 araw","30 araw","10 araw","5 taon"],"h1":"Mga tatlong buwan ito.","h2":"Sa Mississippi, ang pagtanggi sa breath test o chemical test ay nagdudulot ng 90 araw na suspensyon ng lisensya.","p":"Tama. Ang pagtanggi sa test ay nangangahulugang 90 araw na suspensyon."},"ar":{"q":"في Mississippi، رفضت اختبار التنفس عندما طلبه منك الشرطي. لكم من الوقت تُوقَف رخصتك؟","o":["90 يومًا","30 يومًا","10 أيام","5 سنوات"],"h1":"إنها حوالي ثلاثة أشهر.","h2":"في Mississippi، رفض اختبار التنفس أو الاختبار الكيميائي يؤدي إلى إيقاف الرخصة لمدة 90 يومًا.","p":"صحيح. رفض الاختبار يعني إيقاف الرخصة لمدة 90 يومًا."},"ref":{"doc":"MS","page":78}},{"id":"ms-029","scope":"MS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Mississippi, a driver 21 or older is convicted of a first DUI. For how long is the license suspended?","o":["30 days","5 years","10 days","120 days"],"h1":"It is about four months.","h2":"In Mississippi, a first DUI conviction for a driver 21 or older brings a 120-day license suspension.","p":"Right. A first DUI means a 120-day suspension."},"es":{"q":"En Mississippi, un conductor de 21 años o más es declarado culpable de un primer DUI. ¿Por cuánto tiempo se suspende la licencia?","o":["30 días","5 años","10 días","120 días"],"h1":"Son unos cuatro meses.","h2":"En Mississippi, una primera condena por DUI para un conductor de 21 años o más trae una suspensión de la licencia por 120 días.","p":"Correcto. Un primer DUI significa una suspensión de 120 días."},"zh":{"q":"在 Mississippi，一位 21 岁或以上的司机第一次被判 DUI（酒后驾驶）。驾照会被暂停多久？","o":["30 天","5 年","10 天","120 天"],"h1":"大约四个月。","h2":"在 Mississippi，21 岁或以上的司机第一次被判 DUI，驾照会被暂停 120 天。","p":"对。第一次 DUI 会被暂停 120 天。"},"vi":{"q":"Ở Mississippi, một người lái từ 21 tuổi trở lên bị kết tội DUI (lái xe khi say rượu) lần đầu. Bằng lái bị đình chỉ trong bao lâu?","o":["30 ngày","5 năm","10 ngày","120 ngày"],"h1":"Khoảng bốn tháng.","h2":"Ở Mississippi, người lái từ 21 tuổi trở lên bị kết tội DUI lần đầu sẽ bị đình chỉ bằng lái 120 ngày.","p":"Đúng. DUI lần đầu nghĩa là bị đình chỉ 120 ngày."},"tl":{"q":"Sa Mississippi, nahatulan sa unang DUI ang isang driver na 21 taong gulang pataas. Gaano katagal masususpinde ang lisensya?","o":["30 araw","5 taon","10 araw","120 araw"],"h1":"Mga apat na buwan ito.","h2":"Sa Mississippi, ang unang hatol sa DUI para sa driver na 21 taong gulang pataas ay nagdudulot ng 120 araw na suspensyon ng lisensya.","p":"Tama. Ang unang DUI ay nangangahulugang 120 araw na suspensyon."},"ar":{"q":"في Mississippi، أُدين سائق عمره 21 سنة أو أكثر بأول مخالفة قيادة تحت تأثير الكحول (DUI). لكم من الوقت تُوقَف رخصته؟","o":["30 يومًا","5 سنوات","10 أيام","120 يومًا"],"h1":"إنها حوالي أربعة أشهر.","h2":"في Mississippi، أول إدانة DUI لسائق عمره 21 سنة أو أكثر تؤدي إلى إيقاف الرخصة لمدة 120 يومًا.","p":"صحيح. أول DUI يعني إيقاف الرخصة لمدة 120 يومًا."},"ref":{"doc":"MS","page":79}},{"id":"ms-030","scope":"MS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Mississippi, what is the highest speed allowed for any vehicle in a school zone?","o":["10 mph","15 mph","25 mph","35 mph"],"h1":"It is slower than most city streets.","h2":"In Mississippi, no vehicle may go faster than 15 mph in a school zone.","p":"Right. The school zone limit is 15 mph."},"es":{"q":"En Mississippi, ¿cuál es la velocidad máxima permitida para cualquier vehículo en una zona escolar?","o":["10 mph","15 mph","25 mph","35 mph"],"h1":"Es más lenta que en la mayoría de las calles de la ciudad.","h2":"En Mississippi, ningún vehículo puede ir a más de 15 mph en una zona escolar.","p":"Correcto. El límite en una zona escolar es de 15 mph."},"zh":{"q":"在 Mississippi，任何车辆在学校区域（school zone）允许的最高速度是多少？","o":["10 英里/小时","15 英里/小时","25 英里/小时","35 英里/小时"],"h1":"它比大多数市区街道的速度慢。","h2":"在 Mississippi，任何车辆在学校区域都不能超过 15 英里/小时。","p":"对。学校区域的限速是 15 英里/小时。"},"vi":{"q":"Ở Mississippi, tốc độ cao nhất cho phép đối với mọi xe trong khu vực trường học (school zone) là bao nhiêu?","o":["10 mph","15 mph","25 mph","35 mph"],"h1":"Mức này chậm hơn hầu hết các con đường trong thành phố.","h2":"Ở Mississippi, không xe nào được chạy nhanh hơn 15 mph trong khu vực trường học.","p":"Đúng. Giới hạn trong khu vực trường học là 15 mph."},"tl":{"q":"Sa Mississippi, ano ang pinakamabilis na takbong pinapayagan para sa anumang sasakyan sa school zone?","o":["10 mph","15 mph","25 mph","35 mph"],"h1":"Mas mabagal ito kaysa sa karamihan ng kalye sa lungsod.","h2":"Sa Mississippi, walang sasakyang puwedeng tumakbo nang higit sa 15 mph sa school zone.","p":"Tama. 15 mph ang limitasyon sa school zone."},"ar":{"q":"في Mississippi، ما أعلى سرعة مسموح بها لأي مركبة في منطقة المدرسة (school zone)؟","o":["10 mph","15 mph","25 mph","35 mph"],"h1":"إنها أبطأ من معظم شوارع المدينة.","h2":"في Mississippi، لا يجوز لأي مركبة أن تسير بسرعة أكثر من 15 mph في منطقة المدرسة.","p":"صحيح. حد السرعة في منطقة المدرسة هو 15 mph."},"ref":{"doc":"MS","page":41}},{"id":"ms-031","scope":"MS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Mississippi, what is the minimum speed on an interstate highway when conditions are good?","o":["20 mph","30 mph","40 mph","50 mph"],"h1":"Driving far below the flow of traffic on an interstate is also unsafe.","h2":"In Mississippi, the minimum speed on an interstate highway is 40 mph.","p":"Right. Do not drive slower than 40 mph on an interstate."},"es":{"q":"En Mississippi, ¿cuál es la velocidad mínima en una autopista interestatal cuando las condiciones son buenas?","o":["20 mph","30 mph","40 mph","50 mph"],"h1":"Manejar muy por debajo del ritmo del tráfico en una interestatal también es peligroso.","h2":"En Mississippi, la velocidad mínima en una autopista interestatal es de 40 mph.","p":"Correcto. No maneje a menos de 40 mph en una interestatal."},"zh":{"q":"在 Mississippi，路况良好时，州际公路的最低速度是多少？","o":["20 英里/小时","30 英里/小时","40 英里/小时","50 英里/小时"],"h1":"在州际公路上开得比车流慢很多，也不安全。","h2":"在 Mississippi，州际公路的最低速度是 40 英里/小时。","p":"对。在州际公路上不要开得比 40 英里/小时慢。"},"vi":{"q":"Ở Mississippi, tốc độ tối thiểu trên xa lộ liên bang (interstate) khi điều kiện tốt là bao nhiêu?","o":["20 mph","30 mph","40 mph","50 mph"],"h1":"Lái chậm hơn nhiều so với dòng xe trên xa lộ liên bang cũng không an toàn.","h2":"Ở Mississippi, tốc độ tối thiểu trên xa lộ liên bang là 40 mph.","p":"Đúng. Đừng lái chậm hơn 40 mph trên xa lộ liên bang."},"tl":{"q":"Sa Mississippi, ano ang pinakamabagal na takbo sa interstate highway kapag maganda ang kondisyon?","o":["20 mph","30 mph","40 mph","50 mph"],"h1":"Hindi rin ligtas ang magmaneho nang mas mabagal nang malaki kaysa sa daloy ng trapiko sa interstate.","h2":"Sa Mississippi, ang pinakamabagal na takbo sa interstate highway ay 40 mph.","p":"Tama. Huwag magmaneho nang mas mabagal sa 40 mph sa interstate."},"ar":{"q":"في Mississippi، ما الحد الأدنى للسرعة على الطريق السريع بين الولايات (interstate) عندما تكون الظروف جيدة؟","o":["20 mph","30 mph","40 mph","50 mph"],"h1":"القيادة أبطأ بكثير من حركة المرور على الطريق السريع بين الولايات غير آمنة أيضًا.","h2":"في Mississippi، الحد الأدنى للسرعة على الطريق السريع بين الولايات هو 40 mph.","p":"صحيح. لا تقُد بسرعة أقل من 40 mph على الطريق السريع بين الولايات."},"ref":{"doc":"MS","page":41}},{"id":"ms-032","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, how early may you renew your driver's license before it expires?","o":["Up to 30 days","Up to 2 years","Only on the day it expires","Up to 6 months"],"h1":"It is half a year.","h2":"In Mississippi, a driver who qualifies for renewal may renew up to six months before the license expires.","p":"Right. You may renew up to 6 months early."},"es":{"q":"En Mississippi, ¿con cuánta anticipación puede renovar su licencia de conducir antes de que venza?","o":["Hasta 30 días antes","Hasta 2 años antes","Solo el día en que vence","Hasta 6 meses antes"],"h1":"Es medio año.","h2":"En Mississippi, un conductor que califica para renovar puede hacerlo hasta seis meses antes de que venza la licencia.","p":"Correcto. Puede renovar hasta 6 meses antes."},"zh":{"q":"在 Mississippi，你最早可以在驾照到期前多久续期？","o":["最多 30 天","最多 2 年","只能在到期当天","最多 6 个月"],"h1":"是半年。","h2":"在 Mississippi，符合续期条件的司机最早可以在驾照到期前六个月续期。","p":"对。你最早可以提前 6 个月续期。"},"vi":{"q":"Ở Mississippi, bạn có thể gia hạn bằng lái sớm nhất bao lâu trước khi bằng hết hạn?","o":["Tối đa 30 ngày","Tối đa 2 năm","Chỉ vào ngày bằng hết hạn","Tối đa 6 tháng"],"h1":"Đó là nửa năm.","h2":"Ở Mississippi, tài xế đủ điều kiện gia hạn có thể gia hạn bằng lái sớm nhất sáu tháng trước khi bằng hết hạn.","p":"Đúng. Bạn có thể gia hạn sớm tối đa 6 tháng."},"tl":{"q":"Sa Mississippi, gaano kaaga ka puwedeng mag-renew ng driver's license bago ito mag-expire?","o":["Hanggang 30 araw","Hanggang 2 taon","Sa mismong araw lang na mag-e-expire ito","Hanggang 6 na buwan"],"h1":"Kalahating taon ito.","h2":"Sa Mississippi, ang driver na puwedeng mag-renew ay makakapag-renew hanggang anim na buwan bago mag-expire ang license.","p":"Tama. Puwede kang mag-renew hanggang 6 na buwan nang mas maaga."},"ar":{"q":"في Mississippi، قبل كم من الوقت من انتهاء رخصة القيادة يمكنك تجديدها؟","o":["حتى 30 يومًا","حتى سنتين (2)","فقط في يوم انتهائها","حتى 6 أشهر"],"h1":"إنها نصف سنة.","h2":"في Mississippi، يمكن للسائق المؤهل للتجديد أن يجدد رخصته حتى ستة أشهر قبل انتهائها.","p":"صحيح. يمكنك التجديد مبكرًا حتى 6 أشهر."},"ref":{"doc":"MS","page":12}},{"id":"ms-033","scope":"MS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Mississippi, how much space must you leave between your vehicle and a bicycle when you pass it?","o":["At least 3 feet","At least 1 foot","At least 10 feet","At least 20 feet"],"h1":"Think of about one long step.","h2":"In Mississippi, you must leave at least 3 feet between your vehicle and a bicycle when you pass it.","p":"Right. Leave at least 3 feet."},"es":{"q":"En Mississippi, ¿cuánto espacio debe dejar entre su vehículo y una bicicleta al pasarla?","o":["Por lo menos 3 pies","Por lo menos 1 pie","Por lo menos 10 pies","Por lo menos 20 pies"],"h1":"Piense en un paso largo.","h2":"En Mississippi, usted debe dejar por lo menos 3 pies entre su vehículo y una bicicleta al pasarla.","p":"Correcto. Deje por lo menos 3 pies."},"zh":{"q":"在 Mississippi，超过自行车时，你的车和自行车之间必须留出多少空间？","o":["至少 3 英尺","至少 1 英尺","至少 10 英尺","至少 20 英尺"],"h1":"大约是迈一大步的距离。","h2":"在 Mississippi，超过自行车时，你的车和自行车之间必须至少留出 3 英尺。","p":"对。至少留出 3 英尺。"},"vi":{"q":"Ở Mississippi, khi vượt xe đạp, bạn phải chừa khoảng cách bao nhiêu giữa xe của bạn và xe đạp?","o":["Ít nhất 3 feet","Ít nhất 1 feet","Ít nhất 10 feet","Ít nhất 20 feet"],"h1":"Hãy nghĩ đến khoảng một bước chân dài.","h2":"Ở Mississippi, khi vượt xe đạp, bạn phải chừa ít nhất 3 feet giữa xe của bạn và xe đạp.","p":"Đúng. Hãy chừa ít nhất 3 feet."},"tl":{"q":"Sa Mississippi, gaano kalaking espasyo ang dapat mong iwan sa pagitan ng sasakyan mo at ng bisikleta kapag nilalampasan mo ito?","o":["Hindi bababa sa 3 feet","Hindi bababa sa 1 foot","Hindi bababa sa 10 feet","Hindi bababa sa 20 feet"],"h1":"Isipin ang mga isang mahabang hakbang.","h2":"Sa Mississippi, dapat kang mag-iwan ng hindi bababa sa 3 feet sa pagitan ng sasakyan mo at ng bisikleta kapag nilalampasan mo ito.","p":"Tama. Mag-iwan ng hindi bababa sa 3 feet."},"ar":{"q":"في Mississippi، ما المسافة التي يجب أن تتركها بين سيارتك والدراجة الهوائية عندما تتجاوزها؟","o":["3 feet على الأقل","1 foot على الأقل","10 feet على الأقل","20 feet على الأقل"],"h1":"فكّر في خطوة واحدة طويلة تقريبًا.","h2":"في Mississippi، يجب أن تترك 3 feet على الأقل بين سيارتك والدراجة الهوائية عندما تتجاوزها.","p":"صحيح. اترك 3 feet على الأقل."},"ref":{"doc":"MS","page":73}},{"id":"ms-034","scope":"MS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Mississippi, you are using high beams at night. A car is coming toward you. When must you switch to low beams?","o":["When it is 50 feet away","Only if the other driver flashes the lights","When it is within 500 feet","When it is within one mile"],"h1":"The same distance applies when you follow another car.","h2":"In Mississippi, you must use low beams when an oncoming vehicle is within 500 feet, and also when you follow within 500 feet of another vehicle.","p":"Right. Switch to low beams within 500 feet."},"es":{"q":"En Mississippi, usted usa las luces altas de noche. Un carro viene hacia usted. ¿Cuándo debe cambiar a luces bajas?","o":["Cuando esté a 50 pies","Solo si el otro conductor le hace cambio de luces","Cuando esté a menos de 500 pies","Cuando esté a menos de una milla"],"h1":"La misma distancia aplica cuando sigue a otro carro.","h2":"En Mississippi, usted debe usar luces bajas cuando un vehículo que viene de frente está a menos de 500 pies, y también cuando sigue a otro vehículo a menos de 500 pies.","p":"Correcto. Cambie a luces bajas a menos de 500 pies."},"zh":{"q":"在 Mississippi，你在夜间开着远光灯，一辆车迎面开来。你必须在什么时候换成近光灯？","o":["当它离你 50 英尺时","只有对方司机闪灯时","当它在 500 英尺以内时","当它在一英里以内时"],"h1":"你跟在别的车后面时，也用同样的距离。","h2":"在 Mississippi，迎面来车在 500 英尺以内时，你必须使用近光灯；你跟在另一辆车后面 500 英尺以内时，也必须使用近光灯。","p":"对。在 500 英尺以内要换成近光灯。"},"vi":{"q":"Ở Mississippi, bạn đang bật đèn chiếu xa vào ban đêm. Có một xe đang chạy ngược chiều về phía bạn. Khi nào bạn phải chuyển sang đèn chiếu gần?","o":["Khi xe đó cách 50 feet","Chỉ khi tài xế kia nháy đèn","Khi xe đó ở trong vòng 500 feet","Khi xe đó ở trong vòng một dặm"],"h1":"Khoảng cách này cũng áp dụng khi bạn chạy sau một xe khác.","h2":"Ở Mississippi, bạn phải dùng đèn chiếu gần khi xe ngược chiều ở trong vòng 500 feet, và cả khi bạn chạy sau một xe khác trong vòng 500 feet.","p":"Đúng. Hãy chuyển sang đèn chiếu gần trong vòng 500 feet."},"tl":{"q":"Sa Mississippi, gumagamit ka ng high beams sa gabi. May kotseng papalapit sa iyo. Kailan ka dapat lumipat sa low beams?","o":["Kapag 50 feet na lang ang layo nito","Kapag nag-flash lang ng ilaw ang ibang driver","Kapag nasa loob na ito ng 500 feet","Kapag nasa loob na ito ng isang milya"],"h1":"Ganito rin ang layo kapag sumusunod ka sa ibang sasakyan.","h2":"Sa Mississippi, dapat kang gumamit ng low beams kapag nasa loob ng 500 feet ang paparating na sasakyan, at kapag sumusunod ka sa ibang sasakyan sa loob ng 500 feet.","p":"Tama. Lumipat sa low beams sa loob ng 500 feet."},"ar":{"q":"في Mississippi، أنت تستخدم الأضواء العالية ليلًا. وهناك سيارة قادمة نحوك. متى يجب أن تنتقل إلى الأضواء المنخفضة؟","o":["عندما تكون على بعد 50 feet","فقط إذا ومض السائق الآخر بأضوائه","عندما تكون ضمن 500 feet","عندما تكون ضمن ميل واحد"],"h1":"المسافة نفسها تنطبق عندما تسير خلف سيارة أخرى.","h2":"في Mississippi، يجب أن تستخدم الأضواء المنخفضة عندما تكون السيارة القادمة نحوك ضمن 500 feet، وكذلك عندما تسير خلف سيارة أخرى ضمن 500 feet.","p":"صحيح. انتقل إلى الأضواء المنخفضة ضمن 500 feet."},"ref":{"doc":"MS","page":63}},{"id":"ms-035","scope":"MS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Mississippi, how close to the nearest rail of a railroad crossing may you park?","o":["No closer than 5 feet","No closer than 15 feet","No closer than 100 feet","No closer than 3 feet"],"h1":"It is more than 10 feet but less than 20.","h2":"In Mississippi, you may not park within 15 feet of the nearest rail of a railroad crossing.","p":"Right. Stay at least 15 feet from the nearest rail."},"es":{"q":"En Mississippi, ¿qué tan cerca del riel más cercano de un cruce de ferrocarril puede estacionarse?","o":["A no menos de 5 pies","A no menos de 15 pies","A no menos de 100 pies","A no menos de 3 pies"],"h1":"Es más de 10 pies pero menos de 20.","h2":"En Mississippi, no puede estacionarse a menos de 15 pies del riel más cercano de un cruce de ferrocarril.","p":"Correcto. Quédese por lo menos a 15 pies del riel más cercano."},"zh":{"q":"在 Mississippi，你停车时离铁路道口最近的铁轨最近可以有多近？","o":["不能近于 5 英尺","不能近于 15 英尺","不能近于 100 英尺","不能近于 3 英尺"],"h1":"它多于 10 英尺，但少于 20 英尺。","h2":"在 Mississippi，你不可以在离铁路道口最近的铁轨 15 英尺以内停车。","p":"对。要离最近的铁轨至少 15 英尺。"},"vi":{"q":"Ở Mississippi, bạn được đỗ xe gần thanh ray gần nhất của chỗ giao với đường sắt đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 15 feet","Không gần hơn 100 feet","Không gần hơn 3 feet"],"h1":"Nhiều hơn 10 feet nhưng ít hơn 20 feet.","h2":"Ở Mississippi, bạn không được đỗ xe trong vòng 15 feet tính từ thanh ray gần nhất của chỗ giao với đường sắt.","p":"Đúng. Hãy cách thanh ray gần nhất ít nhất 15 feet."},"tl":{"q":"Sa Mississippi, gaano kalapit ka puwedeng pumarada sa pinakamalapit na riles ng railroad crossing?","o":["Hindi mas malapit sa 5 feet","Hindi mas malapit sa 15 feet","Hindi mas malapit sa 100 feet","Hindi mas malapit sa 3 feet"],"h1":"Higit ito sa 10 feet pero kulang sa 20.","h2":"Sa Mississippi, hindi ka puwedeng pumarada sa loob ng 15 feet mula sa pinakamalapit na riles ng railroad crossing.","p":"Tama. Lumayo nang hindi bababa sa 15 feet mula sa pinakamalapit na riles."},"ar":{"q":"في Mississippi، إلى أي مدى يمكنك أن تركن سيارتك قريبًا من أقرب سكة في معبر السكة الحديدية؟","o":["ليس أقرب من 5 feet","ليس أقرب من 15 feet","ليس أقرب من 100 feet","ليس أقرب من 3 feet"],"h1":"إنها أكثر من 10 feet لكن أقل من 20.","h2":"في Mississippi، لا يجوز لك أن تركن سيارتك ضمن 15 feet من أقرب سكة في معبر السكة الحديدية.","p":"صحيح. ابقَ على بعد 15 feet على الأقل من أقرب سكة."},"ref":{"doc":"MS","page":60}},{"id":"ms-036","scope":"MS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Mississippi, how close to a crosswalk at an intersection may you park?","o":["No closer than 5 feet","No closer than 50 feet","No closer than 20 feet","No closer than 2 feet"],"h1":"It is about the length of one large car plus a little more.","h2":"In Mississippi, you may not park on a crosswalk or within 20 feet of a crosswalk at an intersection.","p":"Right. Stay at least 20 feet from the crosswalk."},"es":{"q":"En Mississippi, ¿qué tan cerca de un cruce peatonal en una intersección puede estacionarse?","o":["A no menos de 5 pies","A no menos de 50 pies","A no menos de 20 pies","A no menos de 2 pies"],"h1":"Es como el largo de un carro grande y un poco más.","h2":"En Mississippi, no puede estacionarse sobre un cruce peatonal ni a menos de 20 pies de un cruce peatonal en una intersección.","p":"Correcto. Quédese por lo menos a 20 pies del cruce peatonal."},"zh":{"q":"在 Mississippi，你停车时离路口的人行横道最近可以有多近？","o":["不能近于 5 英尺","不能近于 50 英尺","不能近于 20 英尺","不能近于 2 英尺"],"h1":"大约是一辆大车的长度再多一点。","h2":"在 Mississippi，你不可以停在人行横道上，也不可以停在路口人行横道 20 英尺以内。","p":"对。要离人行横道至少 20 英尺。"},"vi":{"q":"Ở Mississippi, bạn được đỗ xe gần lối băng qua đường cho người đi bộ tại giao lộ đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 50 feet","Không gần hơn 20 feet","Không gần hơn 2 feet"],"h1":"Khoảng bằng chiều dài một chiếc xe hơi lớn và thêm một chút.","h2":"Ở Mississippi, bạn không được đỗ xe trên lối băng qua đường cho người đi bộ hoặc trong vòng 20 feet tính từ lối băng qua đường tại giao lộ.","p":"Đúng. Hãy cách lối băng qua đường ít nhất 20 feet."},"tl":{"q":"Sa Mississippi, gaano kalapit ka puwedeng pumarada sa tawiran (crosswalk) sa isang intersection?","o":["Hindi mas malapit sa 5 feet","Hindi mas malapit sa 50 feet","Hindi mas malapit sa 20 feet","Hindi mas malapit sa 2 feet"],"h1":"Halos kasinghaba ito ng isang malaking kotse at kaunti pa.","h2":"Sa Mississippi, hindi ka puwedeng pumarada sa tawiran o sa loob ng 20 feet mula sa tawiran sa isang intersection.","p":"Tama. Lumayo nang hindi bababa sa 20 feet mula sa tawiran."},"ar":{"q":"في Mississippi، إلى أي مدى يمكنك أن تركن سيارتك قريبًا من ممر المشاة عند التقاطع؟","o":["ليس أقرب من 5 feet","ليس أقرب من 50 feet","ليس أقرب من 20 feet","ليس أقرب من 2 feet"],"h1":"إنها تقريبًا طول سيارة كبيرة واحدة وأكثر قليلًا.","h2":"في Mississippi، لا يجوز لك أن تركن سيارتك على ممر المشاة أو ضمن 20 feet من ممر المشاة عند التقاطع.","p":"صحيح. ابقَ على بعد 20 feet على الأقل من ممر المشاة."},"ref":{"doc":"MS","page":60}},{"id":"ms-037","scope":"MS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Mississippi, what is the usual maximum speed on a two-lane state or U.S. highway, unless signs show a different limit?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"It is 10 mph lower than on a four-lane highway.","h2":"In Mississippi, the usual maximum speed on a two-lane state or U.S. highway is 55 mph.","p":"Right. Two-lane highways usually have a 55 mph limit."},"es":{"q":"En Mississippi, ¿cuál es la velocidad máxima habitual en una carretera estatal o federal de dos carriles, a menos que las señales indiquen otro límite?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Es 10 mph menos que en una carretera de cuatro carriles.","h2":"En Mississippi, la velocidad máxima habitual en una carretera estatal o federal de dos carriles es de 55 mph.","p":"Correcto. Las carreteras de dos carriles suelen tener un límite de 55 mph."},"ref":{"doc":"MS","page":41}},{"id":"ms-038","scope":"MS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Mississippi, what is the maximum speed on the Natchez Trace Parkway, unless a lower limit is posted?","o":["40 mph","50 mph","60 mph","70 mph"],"h1":"It is slower than a regular two-lane highway.","h2":"In Mississippi, the maximum speed on the Natchez Trace Parkway is 50 mph, unless a lower limit is posted.","p":"Right. The Natchez Trace Parkway limit is 50 mph."},"es":{"q":"En Mississippi, ¿cuál es la velocidad máxima en el Natchez Trace Parkway, a menos que se indique un límite más bajo?","o":["40 mph","50 mph","60 mph","70 mph"],"h1":"Es más lenta que en una carretera normal de dos carriles.","h2":"En Mississippi, la velocidad máxima en el Natchez Trace Parkway es de 50 mph, a menos que se indique un límite más bajo.","p":"Correcto. El límite en el Natchez Trace Parkway es de 50 mph."},"ref":{"doc":"MS","page":41}},{"id":"ms-039","scope":"MS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Mississippi, how close to a fire hydrant may you park?","o":["No closer than 3 feet","No closer than 50 feet","No closer than 10 feet","No closer than 100 feet"],"h1":"It is about two car widths.","h2":"In Mississippi, you may not park within 10 feet of a fire hydrant.","p":"Right. Stay at least 10 feet from a fire hydrant."},"es":{"q":"En Mississippi, ¿qué tan cerca de un hidrante puede estacionarse?","o":["A no menos de 3 pies","A no menos de 50 pies","A no menos de 10 pies","A no menos de 100 pies"],"h1":"Es más o menos el ancho de dos carros.","h2":"En Mississippi, no puede estacionarse a menos de 10 pies de un hidrante.","p":"Correcto. Quédese por lo menos a 10 pies de un hidrante."},"ref":{"doc":"MS","page":60}},{"id":"ms-040","scope":"MS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Mississippi, there is no sign. How close to the driveway entrance of a fire station may you park?","o":["No closer than 5 feet","No closer than 100 feet","No closer than 500 feet","No closer than 20 feet"],"h1":"It is the same distance as from a crosswalk at an intersection.","h2":"In Mississippi, you may not park within 20 feet of a fire station driveway, or within 75 feet if a sign says so.","p":"Right. Stay at least 20 feet from a fire station driveway, or 75 feet where posted."},"es":{"q":"En Mississippi, no hay ninguna señal. ¿Qué tan cerca de la entrada de vehículos de una estación de bomberos puede estacionarse?","o":["A no menos de 5 pies","A no menos de 100 pies","A no menos de 500 pies","A no menos de 20 pies"],"h1":"Es la misma distancia que desde un cruce peatonal en una intersección.","h2":"En Mississippi, no puede estacionarse a menos de 20 pies de la entrada de una estación de bomberos, o a menos de 75 pies si una señal lo indica.","p":"Correcto. Quédese por lo menos a 20 pies de la entrada de una estación de bomberos, o a 75 pies donde haya señal."},"ref":{"doc":"MS","page":60}},{"id":"ms-041","scope":"MS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Mississippi, how close to a stop sign or traffic light on your side of the road may you park?","o":["No closer than 5 feet","No closer than 30 feet","No closer than 200 feet","No closer than 500 feet"],"h1":"It is more than the distance from a crosswalk, but less than 50 feet.","h2":"In Mississippi, you may not park within 30 feet of the approach to a stop sign, traffic light or other traffic control device.","p":"Right. Stay at least 30 feet back from a stop sign or traffic light."},"es":{"q":"En Mississippi, ¿qué tan cerca de una señal de alto o un semáforo de su lado de la calle puede estacionarse?","o":["A no menos de 5 pies","A no menos de 30 pies","A no menos de 200 pies","A no menos de 500 pies"],"h1":"Es más que la distancia desde un cruce peatonal, pero menos de 50 pies.","h2":"En Mississippi, no puede estacionarse a menos de 30 pies antes de una señal de alto, un semáforo u otro dispositivo de control de tráfico.","p":"Correcto. Quédese por lo menos a 30 pies antes de una señal de alto o un semáforo."},"ref":{"doc":"MS","page":60}},{"id":"ms-042","scope":"MS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Mississippi, when you parallel park, how close to the curb should your tires be?","o":["Within 12 inches","Within 24 inches","Within 3 feet","Within 5 feet"],"h1":"It is about the length of a ruler.","h2":"In Mississippi, when you parallel park, your tires should be within 12 inches of the curb.","p":"Right. Park with your tires within 12 inches of the curb."},"es":{"q":"En Mississippi, cuando se estaciona en paralelo, ¿qué tan cerca del borde de la acera deben estar sus llantas?","o":["A 12 pulgadas o menos","A 24 pulgadas o menos","A 3 pies o menos","A 5 pies o menos"],"h1":"Es más o menos el largo de una regla.","h2":"En Mississippi, cuando se estaciona en paralelo, sus llantas deben quedar a 12 pulgadas o menos del borde de la acera.","p":"Correcto. Estaciónese con las llantas a 12 pulgadas o menos del borde."},"ref":{"doc":"MS","page":61}},{"id":"ms-043","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, you move here and your out-of-state license expired more than 30 days ago. What must you do?","o":["Nothing more than a regular new resident","Take only a driving road test","Hold a learner's permit for one year","Take the computerized knowledge exam"],"h1":"A valid out-of-state license lets you skip one test. An expired one does not.","h2":"In Mississippi, if your out-of-state license expired more than 30 days ago, you must take the computerized exam.","p":"Right. A license expired over 30 days means you take the computerized exam."},"es":{"q":"En Mississippi, usted se muda aquí y su licencia de otro estado venció hace más de 30 días. ¿Qué debe hacer?","o":["Nada más que un nuevo residente común","Tomar solo un examen práctico de manejo","Tener un permiso de aprendiz por un año","Tomar el examen de conocimientos por computadora"],"h1":"Una licencia válida de otro estado le permite saltarse un examen. Una vencida, no.","h2":"En Mississippi, si su licencia de otro estado venció hace más de 30 días, usted debe tomar el examen por computadora.","p":"Correcto. Con una licencia vencida hace más de 30 días, usted toma el examen por computadora."},"ref":{"doc":"MS","page":11}},{"id":"ms-044","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, you passed the computerized exam for your learner's permit. How long is that passing score good for?","o":["Six months","One year","Two years","Ten years"],"h1":"It is the same length of time the learner's permit is valid.","h2":"In Mississippi, a passing score on the computerized exam is valid for two years.","p":"Right. Your exam score stays good for two years."},"es":{"q":"En Mississippi, usted aprobó el examen por computadora para su permiso de aprendiz. ¿Por cuánto tiempo es válido ese resultado?","o":["Seis meses","Un año","Dos años","Diez años"],"h1":"Es el mismo tiempo que dura el permiso de aprendiz.","h2":"En Mississippi, el resultado aprobado del examen por computadora es válido por dos años.","p":"Correcto. Su resultado del examen es válido por dos años."},"ref":{"doc":"MS","page":13}},{"id":"ms-045","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, a teen got a learner's permit at 16. The teen turns 17 before holding it for a full year. What is true?","o":["The teen may apply for a regular license now","The teen must still wait the full year","The teen must get a new learner's permit","The teen must wait until age 18"],"h1":"Age 17 changes the waiting rule.","h2":"In Mississippi, if you turn 17 before you have held a learner's permit for one year, you may apply for a regular license.","p":"Right. At 17, the one-year wait no longer applies."},"es":{"q":"En Mississippi, un joven obtuvo un permiso de aprendiz a los 16 años. Cumple 17 antes de tenerlo un año completo. ¿Qué es cierto?","o":["Ya puede solicitar una licencia regular","Todavía debe esperar el año completo","Debe obtener un nuevo permiso de aprendiz","Debe esperar hasta los 18 años"],"h1":"Cumplir 17 años cambia la regla de espera.","h2":"En Mississippi, si usted cumple 17 años antes de tener el permiso de aprendiz por un año, puede solicitar una licencia regular.","p":"Correcto. A los 17 años, ya no aplica la espera de un año."},"ref":{"doc":"MS","page":13}},{"id":"ms-046","scope":"MS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Mississippi, an applicant under 18 brings a Certification of Attendance from school. How old may that form be?","o":["No more than 1 year old","No more than 30 days old","No more than 6 months old","Any age, if it is signed"],"h1":"It must be about one month old or newer.","h2":"In Mississippi, the school Certification of Attendance for an applicant under 18 must not be more than 30 days old.","p":"Right. The attendance form must be 30 days old or newer."},"es":{"q":"En Mississippi, un solicitante menor de 18 años trae un Certificado de Asistencia de la escuela. ¿Qué antigüedad puede tener ese formulario?","o":["No más de 1 año","No más de 30 días","No más de 6 meses","Cualquiera, si está firmado"],"h1":"Debe tener más o menos un mes o menos.","h2":"En Mississippi, el Certificado de Asistencia escolar de un solicitante menor de 18 años no debe tener más de 30 días.","p":"Correcto. El formulario de asistencia debe tener 30 días o menos."},"ref":{"doc":"MS","page":16}},{"id":"ms-047","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, a parent signs a teen's application for a permit or license. What does that signature mean?","o":["The parent must ride along on every trip","The parent pays the teen's insurance by law","The parent must take the exam too","The parent becomes liable for the teen's negligent driving"],"h1":"The person who signs takes on legal responsibility.","h2":"In Mississippi, whoever signs a teen's application becomes liable for the teen's negligence or willful misconduct, and the signature must be notarized.","p":"Right. The signer becomes responsible for the teen's negligent driving."},"es":{"q":"En Mississippi, un padre o una madre firma la solicitud de permiso o licencia de un joven. ¿Qué significa esa firma?","o":["Debe acompañar al joven en cada viaje","Debe pagar por ley el seguro del joven","También debe tomar el examen","Se vuelve responsable legal por la negligencia del joven al manejar"],"h1":"La persona que firma asume una responsabilidad legal.","h2":"En Mississippi, quien firma la solicitud de un joven se vuelve responsable por la negligencia o mala conducta intencional del joven, y la firma debe estar notarizada.","p":"Correcto. Quien firma se vuelve responsable si el joven maneja con negligencia."},"ref":{"doc":"MS","page":16}},{"id":"ms-048","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, you refuse a breath test and give your license to the officer. How long is the officer's receipt good as a temporary permit?","o":["10 days","90 days","45 days","1 year"],"h1":"It is about a month and a half.","h2":"In Mississippi, after you refuse a breath or chemical test, the officer's receipt works as a temporary permit for 45 days.","p":"Right. The receipt is a temporary permit for 45 days."},"es":{"q":"En Mississippi, usted se niega a la prueba de aliento y entrega su licencia al oficial. ¿Por cuánto tiempo sirve el recibo del oficial como permiso temporal?","o":["10 días","90 días","45 días","1 año"],"h1":"Es más o menos un mes y medio.","h2":"En Mississippi, después de negarse a una prueba de aliento o química, el recibo del oficial sirve como permiso temporal por 45 días.","p":"Correcto. El recibo es un permiso temporal por 45 días."},"ref":{"doc":"MS","page":78}},{"id":"ms-049","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, what is the fine for a first DUI offense for a driver 21 or older?","o":["$250 to $1,000","$25 to $100","$2,000 to $5,000","$5,000 to $10,000"],"h1":"The highest amount is one thousand dollars.","h2":"In Mississippi, a first DUI offense for a driver 21 or older carries a fine of $250 to $1,000.","p":"Right. A first DUI fine is $250 to $1,000."},"es":{"q":"En Mississippi, ¿cuál es la multa por un primer DUI para un conductor de 21 años o más?","o":["De $250 a $1,000","De $25 a $100","De $2,000 a $5,000","De $5,000 a $10,000"],"h1":"La cantidad más alta es de mil dólares.","h2":"En Mississippi, un primer DUI para un conductor de 21 años o más tiene una multa de $250 a $1,000.","p":"Correcto. La multa por un primer DUI es de $250 a $1,000."},"ref":{"doc":"MS","page":79}},{"id":"ms-050","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, a driver is convicted of a first DUI and also refused the breath test. What happens to the license suspension?","o":["The refusal is ignored","The suspension is cut in half","The license is taken for life","90 days are added to the suspension"],"h1":"Refusing the test makes the penalty longer.","h2":"In Mississippi, if you are convicted of a first DUI and you also refused the breath or chemical test, 90 days are added to the license suspension.","p":"Right. Refusing the test adds 90 days."},"es":{"q":"En Mississippi, un conductor es declarado culpable de un primer DUI y además se negó a la prueba de aliento. ¿Qué pasa con la suspensión de la licencia?","o":["No se toma en cuenta la negativa","La suspensión se reduce a la mitad","Se le quita la licencia de por vida","Se agregan 90 días a la suspensión"],"h1":"Negarse a la prueba hace la pena más larga.","h2":"En Mississippi, si usted es declarado culpable de un primer DUI y además se negó a la prueba de aliento o química, se agregan 90 días a la suspensión de la licencia.","p":"Correcto. Negarse a la prueba agrega 90 días."},"ref":{"doc":"MS","page":79}},{"id":"ms-051","scope":"MS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Mississippi, a driver 21 or older is convicted of a second DUI within five years. For how long is the license suspended?","o":["30 days","1 year","120 days","10 years"],"h1":"It is much longer than for a first offense.","h2":"In Mississippi, a second DUI within five years brings a license suspension of one year.","p":"Right. A second DUI within five years means a one-year suspension."},"es":{"q":"En Mississippi, un conductor de 21 años o más es declarado culpable de un segundo DUI en un plazo de cinco años. ¿Por cuánto tiempo se suspende la licencia?","o":["30 días","1 año","120 días","10 años"],"h1":"Es mucho más largo que por una primera vez.","h2":"En Mississippi, un segundo DUI en un plazo de cinco años trae una suspensión de la licencia por un año.","p":"Correcto. Un segundo DUI en cinco años significa una suspensión de un año."},"ref":{"doc":"MS","page":79}},{"id":"ms-052","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, a driver is convicted of reckless driving three times within 12 months. What happens?","o":["Only a written warning","A required safe-driving video","The license is revoked for one year","Nothing, if the fines are paid"],"h1":"The Commissioner must take the license away.","h2":"In Mississippi, three reckless driving convictions within 12 months mean the license is revoked for one year.","p":"Right. Three reckless driving convictions in a year mean a one-year revocation."},"es":{"q":"En Mississippi, un conductor es declarado culpable de manejo imprudente tres veces en 12 meses. ¿Qué pasa?","o":["Solo recibe una advertencia por escrito","Debe ver un video de manejo seguro","Se le revoca la licencia por un año","Nada, si paga las multas"],"h1":"El Comisionado debe quitarle la licencia.","h2":"En Mississippi, tres condenas por manejo imprudente en 12 meses significan que la licencia se revoca por un año.","p":"Correcto. Tres condenas por manejo imprudente en un año significan una revocación de un año."},"ref":{"doc":"MS","page":80}},{"id":"ms-053","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, an at-fault driver had no liability insurance at the time of a crash. For how long must the driver keep proof of insurance on file?","o":["Three years from the crash","Six months from the crash","Until the next renewal","Ten years from the crash"],"h1":"It is longer than one year but less than five.","h2":"In Mississippi, an at-fault driver who had no liability insurance must buy it and keep proof on file for three years from the date of the crash.","p":"Right. The proof of insurance must stay in effect for three years."},"es":{"q":"En Mississippi, un conductor culpable de un choque no tenía seguro de responsabilidad civil en ese momento. ¿Por cuánto tiempo debe mantener registrada la prueba de seguro?","o":["Tres años desde el choque","Seis meses desde el choque","Hasta la próxima renovación","Diez años desde el choque"],"h1":"Es más de un año pero menos de cinco.","h2":"En Mississippi, un conductor culpable que no tenía seguro de responsabilidad civil debe comprarlo y mantener registrada la prueba por tres años desde la fecha del choque.","p":"Correcto. La prueba de seguro debe estar vigente por tres años."},"ref":{"doc":"MS","page":76}},{"id":"ms-054","scope":"MS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Mississippi, you see an emergency on a highway. What can you dial on a cell phone to reach a Highway Patrol dispatcher?","o":["*311","*411","*511","*HP (*47)"],"h1":"The letters stand for Highway Patrol.","h2":"In Mississippi, you can dial *HP (*47) on a cell phone to reach a Highway Patrol dispatcher for a real emergency.","p":"Right. Dial *HP, which is *47, for the Highway Patrol."},"es":{"q":"En Mississippi, usted ve una emergencia en una carretera. ¿Qué número puede marcar en un celular para hablar con un despachador de la Patrulla de Carreteras?","o":["*311","*411","*511","*HP (*47)"],"h1":"Las letras significan Highway Patrol (Patrulla de Carreteras).","h2":"En Mississippi, puede marcar *HP (*47) en un celular para hablar con un despachador de la Patrulla de Carreteras en una emergencia real.","p":"Correcto. Marque *HP, que es *47, para la Patrulla de Carreteras."},"ref":{"doc":"MS","page":66}},{"id":"ms-055","scope":"MS","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Mississippi, which vehicle must always stop at every railroad crossing, even with no lights or gates?","o":["A pickup truck towing a boat","A school bus carrying even one child","A motorcycle with a passenger","Any car after dark"],"h1":"Think of vehicles that carry children, paying passengers or dangerous cargo.","h2":"In Mississippi, a school bus with even one child, a vehicle for hire with passengers, and a vehicle carrying explosives or flammable liquids must stop at every railroad crossing.","p":"Right. A school bus with any child on board must always stop."},"es":{"q":"En Mississippi, ¿qué vehículo siempre debe detenerse en todos los cruces de ferrocarril, aunque no haya luces ni barreras?","o":["Una camioneta que remolca un bote","Un autobús escolar que lleva aunque sea un niño","Una motocicleta con un pasajero","Cualquier carro de noche"],"h1":"Piense en vehículos que llevan niños, pasajeros que pagan o carga peligrosa.","h2":"En Mississippi, un autobús escolar con aunque sea un niño, un vehículo de alquiler con pasajeros y un vehículo que lleva explosivos o líquidos inflamables deben detenerse en todos los cruces de ferrocarril.","p":"Correcto. Un autobús escolar con cualquier niño a bordo siempre debe detenerse."},"ref":{"doc":"MS","page":35}},{"id":"ms-056","scope":"MS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Mississippi, a car has aftermarket window tint. How much light must all the windows let through?","o":["At least 5 percent","At least 10 percent","At least 28 percent","At least 90 percent"],"h1":"It is a little more than one quarter of the light.","h2":"In Mississippi, all windows must let through at least 28 percent of light, and aftermarket tint needs an inspection certificate and decal.","p":"Right. Windows must let through at least 28 percent of light."},"es":{"q":"En Mississippi, un carro tiene polarizado de ventanas instalado después de la compra. ¿Cuánta luz deben dejar pasar todas las ventanas?","o":["Por lo menos 5 por ciento","Por lo menos 10 por ciento","Por lo menos 28 por ciento","Por lo menos 90 por ciento"],"h1":"Es un poco más de la cuarta parte de la luz.","h2":"En Mississippi, todas las ventanas deben dejar pasar por lo menos el 28 por ciento de la luz, y el polarizado instalado después de la compra necesita un certificado de inspección y una calcomanía.","p":"Correcto. Las ventanas deben dejar pasar por lo menos el 28 por ciento de la luz."},"ref":{"doc":"MS","page":75}},{"id":"mt-001","scope":"MT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Montana, what is the youngest age to get a learner license if you are enrolled in an approved traffic education course?","o":["14 and a half","15 and a half","16 years old","17 years old"],"h1":"Montana lets students start younger than almost any other state.","h2":"In Montana a teen who is enrolled in an approved traffic education course can get a learner license at 14 and a half.","p":"Right. With traffic education, the learner license starts at 14 and a half."},"es":{"q":"En Montana, ¿cuál es la edad mínima para obtener una licencia de aprendiz si usted está inscrito en un curso aprobado de educación vial?","o":["14 años y medio","15 años y medio","16 años","17 años"],"h1":"Montana permite empezar más joven que casi cualquier otro estado.","h2":"En Montana, un adolescente inscrito en un curso aprobado de educación vial puede obtener la licencia de aprendiz a los 14 años y medio.","p":"Correcto. Con educación vial, la licencia de aprendiz empieza a los 14 años y medio."},"zh":{"q":"在 Montana，如果你报名参加了批准的交通教育课程，最小几岁可以拿到学习驾照（learner license）？","o":["14 岁半","15 岁半","16 岁","17 岁"],"h1":"Montana 让学生比几乎任何其他州都更早开始。","h2":"在 Montana，报名参加了批准的交通教育课程的青少年，14 岁半就可以拿到学习驾照。","p":"对。上了交通教育课，学习驾照从 14 岁半开始。"},"vi":{"q":"Ở Montana, độ tuổi nhỏ nhất để được cấp giấy phép tập lái (learner license) là bao nhiêu nếu bạn đang học một khóa giáo dục giao thông được chấp thuận (traffic education)?","o":["14 tuổi rưỡi","15 tuổi rưỡi","16 tuổi","17 tuổi"],"h1":"Montana cho học sinh bắt đầu sớm hơn hầu hết các tiểu bang khác.","h2":"Ở Montana, một thiếu niên đang học khóa giáo dục giao thông được chấp thuận có thể được cấp giấy phép tập lái khi 14 tuổi rưỡi.","p":"Đúng. Khi học giáo dục giao thông, giấy phép tập lái bắt đầu từ 14 tuổi rưỡi."},"tl":{"q":"Sa Montana, ano ang pinakabatang edad para makakuha ng learner license kung naka-enroll ka sa isang aprubadong kurso ng traffic education?","o":["14 at kalahating taon","15 at kalahating taon","16 na taon","17 na taon"],"h1":"Mas maagang pinapayagang magsimula ang mga estudyante sa Montana kaysa halos lahat ng ibang estado.","h2":"Sa Montana, ang isang tinedyer na naka-enroll sa aprubadong kurso ng traffic education ay maaaring makakuha ng learner license sa edad na 14 at kalahati.","p":"Tama. Kapag may traffic education, nagsisimula ang learner license sa 14 at kalahati."},"ar":{"q":"في Montana، ما أصغر عمر للحصول على رخصة التعلّم (learner license) إذا كنت مسجَّلًا في دورة معتمدة لتعليم المرور (traffic education)؟","o":["14 سنة ونصف","15 سنة ونصف","16 سنة","17 سنة"],"h1":"تسمح Montana للطلاب بالبدء أبكر من كل الولايات الأخرى تقريبًا.","h2":"في Montana يمكن للمراهق المسجَّل في دورة معتمدة لتعليم المرور أن يحصل على رخصة التعلّم في عمر 14 سنة ونصف.","p":"صحيح. مع دورة تعليم المرور تبدأ رخصة التعلّم من عمر 14 سنة ونصف."},"ref":{"doc":"MT","page":8}},{"id":"mt-002","scope":"MT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Montana, how long must a teen hold a learner license before getting a first-year restricted license?","o":["1 month","3 months","6 months","12 months"],"h1":"It is half a year.","h2":"A Montana teen must hold the learner license for at least six months in a row before applying for the first-year restricted license.","p":"Right. The learner license is held for six months."},"es":{"q":"En Montana, ¿cuánto tiempo debe tener un adolescente la licencia de aprendiz antes de obtener la licencia restringida del primer año?","o":["1 mes","3 meses","6 meses","12 meses"],"h1":"Es medio año.","h2":"En Montana, un adolescente debe tener la licencia de aprendiz por lo menos seis meses seguidos antes de solicitar la licencia restringida del primer año.","p":"Correcto. La licencia de aprendiz se tiene seis meses."},"zh":{"q":"在 Montana，青少年必须持有学习驾照多久，才能拿到第一年限制驾照？","o":["1 个月","3 个月","6 个月","12 个月"],"h1":"是半年。","h2":"Montana 的青少年必须连续持有学习驾照至少六个月，才能申请第一年限制驾照。","p":"对。学习驾照要持有六个月。"},"vi":{"q":"Ở Montana, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi được cấp bằng lái hạn chế năm đầu (first-year restricted license)?","o":["1 tháng","3 tháng","6 tháng","12 tháng"],"h1":"Đó là nửa năm.","h2":"Ở Montana, thiếu niên phải giữ giấy phép tập lái ít nhất sáu tháng liên tục trước khi xin bằng lái hạn chế năm đầu.","p":"Đúng. Giấy phép tập lái phải được giữ sáu tháng."},"tl":{"q":"Sa Montana, gaano katagal dapat hawak ng tinedyer ang learner license bago makakuha ng first-year restricted license (restriktadong lisensiya sa unang taon)?","o":["1 buwan","3 buwan","6 na buwan","12 buwan"],"h1":"Kalahating taon ito.","h2":"Ang isang tinedyer sa Montana ay dapat may hawak na learner license nang hindi bababa sa anim na magkakasunod na buwan bago mag-apply para sa first-year restricted license.","p":"Tama. Hawak ang learner license nang anim na buwan."},"ar":{"q":"في Montana، كم مدة يجب أن يحمل المراهق رخصة التعلّم قبل الحصول على الرخصة المقيَّدة للسنة الأولى (first-year restricted license)؟","o":["شهر واحد","3 أشهر","6 أشهر","12 شهرًا"],"h1":"إنها نصف سنة.","h2":"يجب على المراهق في Montana أن يحمل رخصة التعلّم ستة أشهر متتالية على الأقل قبل التقدّم للرخصة المقيَّدة للسنة الأولى.","p":"صحيح. تُحمَل رخصة التعلّم ستة أشهر."},"ref":{"doc":"MT","page":8}},{"id":"mt-003","scope":"MT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Montana, how many hours of supervised driving must a teen complete with a learner license?","o":["20 hours","30 hours","40 hours","50 hours"],"h1":"A parent records these hours on a driving log.","h2":"A Montana teen must complete at least 50 hours of supervised driving while holding the learner license, and a parent certifies the log.","p":"Right. Montana asks for 50 supervised hours."},"es":{"q":"En Montana, ¿cuántas horas de manejo supervisado debe completar un adolescente con licencia de aprendiz?","o":["20 horas","30 horas","40 horas","50 horas"],"h1":"Uno de los padres anota estas horas en un registro de manejo.","h2":"En Montana, un adolescente debe completar por lo menos 50 horas de manejo supervisado con la licencia de aprendiz, y uno de los padres certifica el registro.","p":"Correcto. Montana pide 50 horas supervisadas."},"zh":{"q":"在 Montana，青少年持学习驾照时必须完成多少小时有人监督的驾驶？","o":["20 小时","30 小时","40 小时","50 小时"],"h1":"父母会把这些时间记在驾驶记录表上。","h2":"Montana 的青少年持学习驾照时必须完成至少 50 小时有人监督的驾驶，由父母证明记录表。","p":"对。Montana 要求 50 小时有人监督的驾驶。"},"vi":{"q":"Ở Montana, thiếu niên có giấy phép tập lái phải lái xe có người giám sát bao nhiêu giờ?","o":["20 giờ","30 giờ","40 giờ","50 giờ"],"h1":"Cha mẹ ghi những giờ này vào sổ ghi chép lái xe.","h2":"Ở Montana, thiếu niên phải lái xe có người giám sát ít nhất 50 giờ trong thời gian giữ giấy phép tập lái, và cha mẹ xác nhận sổ ghi chép.","p":"Đúng. Montana yêu cầu 50 giờ có người giám sát."},"tl":{"q":"Sa Montana, ilang oras ng pagmamaneho na may gumagabay ang dapat tapusin ng tinedyer na may learner license?","o":["20 oras","30 oras","40 oras","50 oras"],"h1":"Itinatala ng magulang ang mga oras na ito sa isang driving log.","h2":"Ang isang tinedyer sa Montana ay dapat makatapos ng hindi bababa sa 50 oras ng pagmamaneho na may gumagabay habang may hawak na learner license, at pinapatunayan ng magulang ang log.","p":"Tama. 50 oras na may gumagabay ang hinihingi ng Montana."},"ar":{"q":"في Montana، كم ساعة من القيادة تحت الإشراف يجب أن يُكملها المراهق الذي يحمل رخصة التعلّم؟","o":["20 ساعة","30 ساعة","40 ساعة","50 ساعة"],"h1":"يسجّل أحد الوالدين هذه الساعات في سجل القيادة.","h2":"يجب على المراهق في Montana أن يُكمل 50 ساعة على الأقل من القيادة تحت الإشراف وهو يحمل رخصة التعلّم، ويوقّع أحد الوالدين على السجل.","p":"صحيح. تطلب Montana 50 ساعة تحت الإشراف."},"ref":{"doc":"MT","page":7}},{"id":"mt-004","scope":"MT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Montana, how many of the 50 supervised practice hours must be at night?","o":["5 hours","10 hours","20 hours","25 hours"],"h1":"It is one fifth of the total.","h2":"Of the 50 supervised hours in Montana, at least 10 must be driven at night, so the teen learns to drive in the dark.","p":"Right. 10 of the 50 hours are at night."},"es":{"q":"En Montana, ¿cuántas de las 50 horas de práctica supervisada deben ser de noche?","o":["5 horas","10 horas","20 horas","25 horas"],"h1":"Es una quinta parte del total.","h2":"De las 50 horas supervisadas en Montana, por lo menos 10 deben ser de noche, para que el adolescente aprenda a manejar en la oscuridad.","p":"Correcto. 10 de las 50 horas son de noche."},"zh":{"q":"在 Montana，50 小时有人监督的练习中，有多少小时必须在晚上？","o":["5 小时","10 小时","20 小时","25 小时"],"h1":"是总数的五分之一。","h2":"在 Montana 的 50 小时有人监督的驾驶中，至少 10 小时必须在晚上开，这样青少年能学会在黑暗中开车。","p":"对。50 小时中有 10 小时在晚上。"},"vi":{"q":"Ở Montana, trong 50 giờ tập lái có người giám sát, bao nhiêu giờ phải lái vào ban đêm?","o":["5 giờ","10 giờ","20 giờ","25 giờ"],"h1":"Đó là một phần năm của tổng số giờ.","h2":"Trong 50 giờ có người giám sát ở Montana, ít nhất 10 giờ phải lái vào ban đêm, để thiếu niên học cách lái trong bóng tối.","p":"Đúng. 10 trong 50 giờ là vào ban đêm."},"tl":{"q":"Sa Montana, ilan sa 50 oras ng pagsasanay na may gumagabay ang dapat sa gabi?","o":["5 oras","10 oras","20 oras","25 oras"],"h1":"Ito ay ikalimang bahagi ng kabuuan.","h2":"Sa 50 oras na may gumagabay sa Montana, hindi bababa sa 10 ang dapat imaneho sa gabi, para matutong magmaneho ang tinedyer sa dilim.","p":"Tama. 10 sa 50 oras ay sa gabi."},"ar":{"q":"في Montana، كم ساعة من ساعات التدريب الـ 50 تحت الإشراف يجب أن تكون في الليل؟","o":["5 ساعات","10 ساعات","20 ساعة","25 ساعة"],"h1":"إنها خُمس المجموع.","h2":"من الساعات الـ 50 تحت الإشراف في Montana، يجب أن تكون 10 ساعات على الأقل في الليل، حتى يتعلّم المراهق القيادة في الظلام.","p":"صحيح. 10 من الـ 50 ساعة في الليل."},"ref":{"doc":"MT","page":7}},{"id":"mt-005","scope":"MT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Montana, a learner under 18 may drive with a parent or guardian, or with their permission, with whom?","o":["Any passenger of any age","A friend age 16 or older","Only a police officer","A licensed driver age 18 or older"],"h1":"The person must be an adult with a license.","h2":"In Montana a learner under 18 must be supervised by a parent or guardian, or, with the parent's permission, by a licensed driver who is at least 18.","p":"Right. With permission, a licensed driver 18 or older may supervise."},"es":{"q":"En Montana, un aprendiz menor de 18 años puede manejar con su padre, madre o tutor, o con su permiso, ¿con quién?","o":["Cualquier pasajero de cualquier edad","Un amigo de 16 años o más","Solamente un policía","Un conductor con licencia de 18 años o más"],"h1":"La persona debe ser un adulto con licencia.","h2":"En Montana, un aprendiz menor de 18 años debe ir supervisado por su padre, madre o tutor, o, con permiso de ellos, por un conductor con licencia de por lo menos 18 años.","p":"Correcto. Con permiso, puede supervisar un conductor con licencia de 18 años o más."},"zh":{"q":"在 Montana，18 岁以下的学习驾驶的人可以和父母或监护人一起开车，或者经他们允许，和谁一起开车？","o":["任何年龄的任何乘客","16 岁或以上的朋友","只有警察","18 岁或以上、有驾照的司机"],"h1":"这个人必须是有驾照的成年人。","h2":"在 Montana，18 岁以下的学习驾驶的人必须由父母或监护人监督，或者经父母允许，由至少 18 岁、有驾照的司机监督。","p":"对。经允许，18 岁或以上、有驾照的司机可以监督。"},"vi":{"q":"Ở Montana, người tập lái dưới 18 tuổi có thể lái xe với cha mẹ hoặc người giám hộ, hoặc, khi được họ cho phép, với ai?","o":["Bất kỳ hành khách nào ở bất kỳ tuổi nào","Một người bạn từ 16 tuổi trở lên","Chỉ một cảnh sát","Một người có bằng lái từ 18 tuổi trở lên"],"h1":"Người đó phải là người lớn có bằng lái.","h2":"Ở Montana, người tập lái dưới 18 tuổi phải được cha mẹ hoặc người giám hộ giám sát, hoặc, khi cha mẹ cho phép, được một người có bằng lái từ 18 tuổi trở lên giám sát.","p":"Đúng. Khi được cho phép, một người có bằng lái từ 18 tuổi trở lên có thể giám sát."},"tl":{"q":"Sa Montana, ang learner na wala pang 18 taong gulang ay maaaring magmaneho kasama ang magulang o guardian, o, kung may pahintulot nila, kasama sino?","o":["Kahit sinong pasahero sa kahit anong edad","Isang kaibigan na 16 taong gulang pataas","Isang pulis lamang","Isang lisensiyadong driver na 18 taong gulang pataas"],"h1":"Ang tao ay dapat nasa hustong gulang at may lisensiya.","h2":"Sa Montana, ang learner na wala pang 18 ay dapat gabayan ng magulang o guardian, o, kung may pahintulot ng magulang, ng isang lisensiyadong driver na hindi bababa sa 18 taong gulang.","p":"Tama. Kung may pahintulot, maaaring gumabay ang lisensiyadong driver na 18 pataas."},"ar":{"q":"في Montana، يمكن للمتعلّم الذي عمره أقل من 18 سنة أن يقود مع أحد الوالدين أو الوصي، أو بإذنهما، مع مَن؟","o":["أي راكب من أي عمر","صديق عمره 16 سنة أو أكثر","شرطي فقط","سائق مرخَّص عمره 18 سنة أو أكثر"],"h1":"يجب أن يكون الشخص بالغًا ومعه رخصة.","h2":"في Montana يجب أن يكون المتعلّم الذي عمره أقل من 18 سنة تحت إشراف أحد الوالدين أو الوصي، أو، بإذن الوالدين، تحت إشراف سائق مرخَّص عمره 18 سنة على الأقل.","p":"صحيح. بالإذن، يمكن لسائق مرخَّص عمره 18 سنة أو أكثر أن يُشرف."},"ref":{"doc":"MT","page":7}},{"id":"mt-006","scope":"MT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Montana, during the first year with a restricted license, when may a teen not drive unless an exception applies?","o":["From 10 p.m. to 6 a.m.","From 11 p.m. to 5 a.m.","From midnight to 5 a.m.","From 9 p.m. to 5 a.m."],"h1":"It starts one hour before midnight.","h2":"A Montana teen with a first-year restricted license may not drive between 11 p.m. and 5 a.m., unless a listed exception applies, such as an emergency.","p":"Right. No driving from 11 p.m. to 5 a.m. without an exception."},"es":{"q":"En Montana, durante el primer año con licencia restringida, ¿cuándo no puede manejar un adolescente salvo que aplique una excepción?","o":["De 10 p.m. a 6 a.m.","De 11 p.m. a 5 a.m.","De medianoche a 5 a.m.","De 9 p.m. a 5 a.m."],"h1":"Empieza una hora antes de la medianoche.","h2":"En Montana, un adolescente con licencia restringida del primer año no puede manejar entre las 11 p.m. y las 5 a.m., salvo que aplique una excepción de la lista, como una emergencia.","p":"Correcto. No se maneja de 11 p.m. a 5 a.m. sin una excepción."},"zh":{"q":"在 Montana，持限制驾照的第一年，除非有例外情况，青少年什么时候不能开车？","o":["晚上 10 点到早上 6 点","晚上 11 点到早上 5 点","午夜到早上 5 点","晚上 9 点到早上 5 点"],"h1":"它从午夜前一个小时开始。","h2":"Montana 持第一年限制驾照的青少年，在晚上 11 点到早上 5 点之间不能开车，除非有列出的例外情况，比如紧急情况。","p":"对。没有例外情况时，晚上 11 点到早上 5 点不能开车。"},"vi":{"q":"Ở Montana, trong năm đầu có bằng lái hạn chế, thiếu niên không được lái xe vào giờ nào, trừ khi có trường hợp ngoại lệ?","o":["Từ 10 giờ tối đến 6 giờ sáng","Từ 11 giờ tối đến 5 giờ sáng","Từ nửa đêm đến 5 giờ sáng","Từ 9 giờ tối đến 5 giờ sáng"],"h1":"Bắt đầu một giờ trước nửa đêm.","h2":"Ở Montana, thiếu niên có bằng lái hạn chế năm đầu không được lái xe từ 11 giờ tối đến 5 giờ sáng, trừ khi có một ngoại lệ được liệt kê, ví dụ như trường hợp khẩn cấp.","p":"Đúng. Không lái từ 11 giờ tối đến 5 giờ sáng nếu không có ngoại lệ."},"tl":{"q":"Sa Montana, sa unang taon na may restricted license, kailan bawal magmaneho ang tinedyer maliban kung may eksepsiyon?","o":["Mula 10 p.m. hanggang 6 a.m.","Mula 11 p.m. hanggang 5 a.m.","Mula hatinggabi hanggang 5 a.m.","Mula 9 p.m. hanggang 5 a.m."],"h1":"Nagsisimula ito isang oras bago maghatinggabi.","h2":"Ang tinedyer sa Montana na may first-year restricted license ay bawal magmaneho mula 11 p.m. hanggang 5 a.m., maliban kung may nakalistang eksepsiyon, gaya ng emergency.","p":"Tama. Bawal magmaneho mula 11 p.m. hanggang 5 a.m. kung walang eksepsiyon."},"ar":{"q":"في Montana، خلال السنة الأولى مع الرخصة المقيَّدة، متى لا يجوز للمراهق أن يقود إلا إذا كان هناك استثناء؟","o":["من 10 مساءً إلى 6 صباحًا","من 11 مساءً إلى 5 صباحًا","من منتصف الليل إلى 5 صباحًا","من 9 مساءً إلى 5 صباحًا"],"h1":"تبدأ قبل منتصف الليل بساعة واحدة.","h2":"لا يجوز للمراهق في Montana الذي يحمل الرخصة المقيَّدة للسنة الأولى أن يقود بين 11 مساءً و5 صباحًا، إلا إذا كان هناك استثناء مذكور، مثل حالة طارئة.","p":"صحيح. لا قيادة من 11 مساءً إلى 5 صباحًا بدون استثناء."},"ref":{"doc":"MT","page":8}},{"id":"mt-007","scope":"MT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Montana, during the first six months with a restricted license, how many passengers under 18 may a teen carry without an adult supervisor?","o":["No more than one","No more than two","No more than three","As many as there are seat belts"],"h1":"The number is very small at first.","h2":"In the first six months, a Montana restricted licensee may not carry more than one passenger under 18 unless a licensed driver age 18 or older is supervising.","p":"Right. At first, no more than one passenger under 18."},"es":{"q":"En Montana, durante los primeros seis meses con licencia restringida, ¿cuántos pasajeros menores de 18 años puede llevar un adolescente sin un adulto supervisor?","o":["No más de uno","No más de dos","No más de tres","Tantos como cinturones haya"],"h1":"Al principio el número es muy pequeño.","h2":"En los primeros seis meses, quien tiene licencia restringida en Montana no puede llevar más de un pasajero menor de 18 años, salvo que lo supervise un conductor con licencia de 18 años o más.","p":"Correcto. Al principio, no más de un pasajero menor de 18."},"zh":{"q":"在 Montana，持限制驾照的前六个月，没有成年人监督时，青少年可以载多少位 18 岁以下的乘客？","o":["最多一位","最多两位","最多三位","有几条安全带就载几位"],"h1":"一开始这个数字很小。","h2":"在前六个月，Montana 持限制驾照的人不能载超过一位 18 岁以下的乘客，除非有 18 岁或以上、有驾照的司机监督。","p":"对。一开始最多只能载一位 18 岁以下的乘客。"},"vi":{"q":"Ở Montana, trong sáu tháng đầu có bằng lái hạn chế, thiếu niên được chở bao nhiêu hành khách dưới 18 tuổi khi không có người lớn giám sát?","o":["Không quá một người","Không quá hai người","Không quá ba người","Bằng số dây an toàn trong xe"],"h1":"Lúc đầu con số này rất nhỏ.","h2":"Trong sáu tháng đầu, người có bằng lái hạn chế ở Montana không được chở quá một hành khách dưới 18 tuổi, trừ khi có một người có bằng lái từ 18 tuổi trở lên giám sát.","p":"Đúng. Lúc đầu, không quá một hành khách dưới 18 tuổi."},"tl":{"q":"Sa Montana, sa unang anim na buwan na may restricted license, ilang pasaherong wala pang 18 ang maaaring isakay ng tinedyer kung walang adult na gumagabay?","o":["Hindi hihigit sa isa","Hindi hihigit sa dalawa","Hindi hihigit sa tatlo","Kasing dami ng seat belt"],"h1":"Napakaliit ng bilang sa simula.","h2":"Sa unang anim na buwan, ang may restricted license sa Montana ay hindi maaaring magsakay ng higit sa isang pasaherong wala pang 18, maliban kung may gumagabay na lisensiyadong driver na 18 pataas.","p":"Tama. Sa simula, hindi hihigit sa isang pasaherong wala pang 18."},"ar":{"q":"في Montana، خلال الأشهر الستة الأولى مع الرخصة المقيَّدة، كم راكبًا عمره أقل من 18 سنة يمكن للمراهق أن ينقل بدون مشرف بالغ؟","o":["ليس أكثر من واحد","ليس أكثر من اثنين","ليس أكثر من ثلاثة","بعدد أحزمة الأمان"],"h1":"العدد صغير جدًا في البداية.","h2":"في الأشهر الستة الأولى، لا يجوز لحامل الرخصة المقيَّدة في Montana أن ينقل أكثر من راكب واحد عمره أقل من 18 سنة، إلا إذا كان سائق مرخَّص عمره 18 سنة أو أكثر يُشرف عليه.","p":"صحيح. في البداية، ليس أكثر من راكب واحد عمره أقل من 18 سنة."},"ref":{"doc":"MT","page":8}},{"id":"mt-008","scope":"MT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Montana, how long do the restrictions on a teen's first license last?","o":["Six months, at any age","Two years, or until age 21","One year, or until age 18 if sooner","Until the teen finishes high school"],"h1":"Whichever comes first ends them.","h2":"Montana's first-license restrictions last one year from the date the license is issued, or until the driver turns 18 if that comes first.","p":"Right. One year, or until 18, whichever is first."},"es":{"q":"En Montana, ¿cuánto duran las restricciones de la primera licencia de un adolescente?","o":["Seis meses, a cualquier edad","Dos años, o hasta los 21","Un año, o hasta los 18 si es antes","Hasta que termine la secundaria"],"h1":"Las termina lo que ocurra primero.","h2":"Las restricciones de la primera licencia en Montana duran un año desde que se emite la licencia, o hasta que el conductor cumple 18 años si eso ocurre antes.","p":"Correcto. Un año, o hasta los 18, lo que ocurra primero."},"zh":{"q":"在 Montana，青少年第一张驾照的限制会持续多久？","o":["六个月，不管几岁","两年，或者到 21 岁","一年，或者到 18 岁（如果更早）","到青少年高中毕业"],"h1":"哪个先到，限制就在那时结束。","h2":"Montana 第一张驾照的限制从拿到驾照那天起持续一年，如果司机更早满 18 岁，就到满 18 岁为止。","p":"对。一年，或者到 18 岁，哪个先到就算哪个。"},"vi":{"q":"Ở Montana, các hạn chế trên bằng lái đầu tiên của thiếu niên kéo dài bao lâu?","o":["Sáu tháng, ở bất kỳ tuổi nào","Hai năm, hoặc đến 21 tuổi","Một năm, hoặc đến 18 tuổi nếu sớm hơn","Đến khi thiếu niên học xong trung học"],"h1":"Điều nào đến trước thì các hạn chế kết thúc.","h2":"Các hạn chế trên bằng lái đầu tiên ở Montana kéo dài một năm kể từ ngày cấp bằng, hoặc đến khi người lái tròn 18 tuổi nếu điều đó đến trước.","p":"Đúng. Một năm, hoặc đến 18 tuổi, tùy điều nào đến trước."},"tl":{"q":"Sa Montana, gaano katagal ang mga restriksiyon sa unang lisensiya ng tinedyer?","o":["Anim na buwan, sa kahit anong edad","Dalawang taon, o hanggang edad 21","Isang taon, o hanggang edad 18 kung mas maaga","Hanggang matapos ng tinedyer ang high school"],"h1":"Kung alin ang mauna, iyon ang tatapos sa mga ito.","h2":"Ang mga restriksiyon sa unang lisensiya sa Montana ay tumatagal ng isang taon mula sa araw na ibinigay ang lisensiya, o hanggang mag-18 ang driver kung iyon ang mauna.","p":"Tama. Isang taon, o hanggang 18, kung alin ang mauna."},"ar":{"q":"في Montana، كم تستمر القيود على أول رخصة للمراهق؟","o":["ستة أشهر، في أي عمر","سنتان، أو حتى عمر 21","سنة واحدة، أو حتى عمر 18 إذا جاء أولًا","حتى ينهي المراهق المدرسة الثانوية"],"h1":"ما يأتي أولًا هو الذي يُنهيها.","h2":"تستمر قيود أول رخصة في Montana سنة واحدة من تاريخ إصدار الرخصة، أو حتى يبلغ السائق 18 سنة إذا جاء ذلك أولًا.","p":"صحيح. سنة واحدة، أو حتى عمر 18، أيهما أولًا."},"ref":{"doc":"MT","page":8}},{"id":"mt-009","scope":"MT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Montana, what seat belt rule applies to a teen with a first-year restricted license?","o":["Only the driver must buckle up","Only front-seat riders must buckle up","Belts are needed only on highways","Every rider must be belted, one person per belt"],"h1":"The number of people may not be more than the number of belts.","h2":"A Montana restricted licensee may drive only if every person in the vehicle wears a seat belt or proper restraint, and there are no more riders than belts.","p":"Right. Everyone belted, and no more riders than seat belts."},"es":{"q":"En Montana, ¿qué regla de cinturón de seguridad aplica a un adolescente con licencia restringida del primer año?","o":["Solo el conductor debe abrocharse","Solo los de adelante deben abrocharse","Los cinturones solo se necesitan en carretera","Todos deben usar cinturón, una persona por cinturón"],"h1":"El número de personas no puede ser mayor que el de cinturones.","h2":"En Montana, quien tiene licencia restringida solo puede manejar si cada persona en el vehículo usa cinturón o el sistema de sujeción adecuado, y no hay más personas que cinturones.","p":"Correcto. Todos con cinturón, y no más personas que cinturones."},"zh":{"q":"在 Montana，持第一年限制驾照的青少年要遵守哪条安全带规定？","o":["只有司机要系安全带","只有坐前排的人要系安全带","只有在公路上才需要系安全带","每个乘车的人都要系安全带，一人一条"],"h1":"人数不能超过安全带的数量。","h2":"Montana 持限制驾照的人只有在车里每个人都系好安全带或合适的约束装置，而且乘车的人不比安全带多时，才可以开车。","p":"对。每个人都系安全带，乘车的人不能比安全带多。"},"vi":{"q":"Ở Montana, quy định nào về dây an toàn áp dụng cho thiếu niên có bằng lái hạn chế năm đầu?","o":["Chỉ người lái phải thắt dây an toàn","Chỉ người ngồi ghế trước phải thắt dây an toàn","Chỉ cần thắt dây an toàn trên xa lộ","Mọi người trong xe phải thắt dây an toàn, mỗi người một dây"],"h1":"Số người không được nhiều hơn số dây an toàn.","h2":"Ở Montana, người có bằng lái hạn chế chỉ được lái xe khi mọi người trong xe đều thắt dây an toàn hoặc dùng ghế an toàn phù hợp, và số người không nhiều hơn số dây an toàn.","p":"Đúng. Mọi người thắt dây an toàn, và số người không nhiều hơn số dây an toàn."},"tl":{"q":"Sa Montana, anong patakaran sa seat belt ang para sa tinedyer na may first-year restricted license?","o":["Ang driver lang ang dapat mag-seat belt","Ang mga nasa harapan lang ang dapat mag-seat belt","Kailangan lang ang seat belt sa highway","Bawat sakay ay dapat naka-seat belt, isang tao bawat belt"],"h1":"Hindi puwedeng mas marami ang tao kaysa sa bilang ng seat belt.","h2":"Ang may restricted license sa Montana ay maaari lang magmaneho kung bawat tao sa sasakyan ay naka-seat belt o tamang restraint, at hindi mas marami ang sakay kaysa sa mga belt.","p":"Tama. Lahat naka-seat belt, at hindi mas marami ang sakay kaysa sa seat belt."},"ar":{"q":"في Montana، ما قاعدة حزام الأمان التي تنطبق على المراهق الذي يحمل الرخصة المقيَّدة للسنة الأولى؟","o":["السائق فقط يجب أن يربط الحزام","ركاب المقعد الأمامي فقط يجب أن يربطوا الحزام","الأحزمة مطلوبة على الطرق السريعة فقط","كل راكب يجب أن يربط حزامًا، شخص واحد لكل حزام"],"h1":"لا يجوز أن يكون عدد الأشخاص أكثر من عدد الأحزمة.","h2":"يمكن لحامل الرخصة المقيَّدة في Montana أن يقود فقط إذا كان كل شخص في السيارة يربط حزام الأمان أو وسيلة حماية مناسبة، ولا يزيد عدد الركاب على عدد الأحزمة.","p":"صحيح. الجميع يربطون الحزام، ولا يزيد عدد الركاب على عدد الأحزمة."},"ref":{"doc":"MT","page":8}},{"id":"mt-010","scope":"MT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Montana, how long is a learner license valid after you pass the written test?","o":["30 days","6 months","One year","Two years"],"h1":"It lasts long enough for a full season of practice and more.","h2":"A Montana learner license is issued after you pass the written and vision tests, and it is valid for one year.","p":"Right. The learner license is valid for one year."},"es":{"q":"En Montana, ¿cuánto tiempo es válida la licencia de aprendiz después de aprobar el examen escrito?","o":["30 días","6 meses","Un año","Dos años"],"h1":"Dura lo suficiente para una temporada completa de práctica y más.","h2":"En Montana, la licencia de aprendiz se emite después de aprobar el examen escrito y el de la vista, y es válida por un año.","p":"Correcto. La licencia de aprendiz es válida por un año."},"zh":{"q":"在 Montana，通过笔试以后，学习驾照有效多久？","o":["30 天","6 个月","一年","两年"],"h1":"它的时间够你练习整整一个季节，还更长。","h2":"Montana 的学习驾照在你通过笔试和视力检查以后发给你，有效期是一年。","p":"对。学习驾照有效一年。"},"vi":{"q":"Ở Montana, giấy phép tập lái có giá trị bao lâu sau khi bạn đậu bài thi viết?","o":["30 ngày","6 tháng","Một năm","Hai năm"],"h1":"Thời gian đủ dài cho cả một mùa tập lái và hơn nữa.","h2":"Ở Montana, giấy phép tập lái được cấp sau khi bạn đậu bài thi viết và bài kiểm tra thị lực, và có giá trị một năm.","p":"Đúng. Giấy phép tập lái có giá trị một năm."},"tl":{"q":"Sa Montana, gaano katagal valid ang learner license pagkatapos mong pumasa sa written test?","o":["30 araw","6 na buwan","Isang taon","Dalawang taon"],"h1":"Sapat ang haba nito para sa isang buong season ng pagsasanay at higit pa.","h2":"Ang learner license sa Montana ay ibinibigay pagkatapos mong pumasa sa written test at vision test, at valid ito nang isang taon.","p":"Tama. Valid ang learner license nang isang taon."},"ar":{"q":"في Montana، كم مدة صلاحية رخصة التعلّم بعد أن تنجح في الاختبار الكتابي؟","o":["30 يومًا","6 أشهر","سنة واحدة","سنتان"],"h1":"إنها طويلة بما يكفي لموسم كامل من التدريب وأكثر.","h2":"تُصدَر رخصة التعلّم في Montana بعد أن تنجح في الاختبار الكتابي واختبار النظر، وهي صالحة لمدة سنة واحدة.","p":"صحيح. رخصة التعلّم صالحة لمدة سنة واحدة."},"ref":{"doc":"MT","page":8}},{"id":"mt-011","scope":"MT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Montana, what is the speed limit on an interstate outside a city of 50,000 people or more?","o":["75 mph","80 mph","70 mph","85 mph"],"h1":"It is one of the highest limits in the country.","h2":"Montana law sets 80 mph at all times on interstates outside urbanized areas of 50,000 people or more, unless a lower limit is posted.","p":"Right. Rural Montana interstates are 80 mph."},"es":{"q":"En Montana, ¿cuál es el límite de velocidad en una autopista interestatal fuera de una ciudad de 50,000 habitantes o más?","o":["75 mph","80 mph","70 mph","85 mph"],"h1":"Es uno de los límites más altos del país.","h2":"La ley de Montana fija 80 mph a toda hora en las autopistas interestatales fuera de zonas urbanas de 50,000 habitantes o más, salvo que se indique un límite menor.","p":"Correcto. Las interestatales rurales de Montana son de 80 mph."},"zh":{"q":"在 Montana，在人口 50,000 或以上的城市以外，州际公路的限速是多少？","o":["75 英里/小时","80 英里/小时","70 英里/小时","85 英里/小时"],"h1":"它是全国最高的限速之一。","h2":"Montana 法律规定，在人口 50,000 或以上的城市化地区以外，州际公路任何时候都限速 80 英里/小时，除非标出更低的限速。","p":"对。Montana 乡村的州际公路限速 80 英里/小时。"},"vi":{"q":"Ở Montana, tốc độ tối đa trên xa lộ liên bang (interstate) bên ngoài thành phố có 50,000 dân trở lên là bao nhiêu?","o":["75 mph","80 mph","70 mph","85 mph"],"h1":"Đây là một trong những giới hạn cao nhất cả nước.","h2":"Luật Montana đặt giới hạn 80 mph vào mọi lúc trên xa lộ liên bang bên ngoài khu đô thị có 50,000 dân trở lên, trừ khi có biển báo giới hạn thấp hơn.","p":"Đúng. Xa lộ liên bang ở vùng nông thôn Montana là 80 mph."},"tl":{"q":"Sa Montana, ano ang speed limit sa interstate sa labas ng lungsod na may 50,000 tao o higit pa?","o":["75 mph","80 mph","70 mph","85 mph"],"h1":"Isa ito sa pinakamataas na limit sa bansa.","h2":"Itinatakda ng batas ng Montana ang 80 mph sa lahat ng oras sa mga interstate sa labas ng urban area na may 50,000 tao o higit pa, maliban kung may nakapaskil na mas mababang limit.","p":"Tama. 80 mph ang mga interstate sa probinsiya ng Montana."},"ar":{"q":"في Montana، ما الحد الأقصى للسرعة على الطريق السريع بين الولايات (interstate) خارج مدينة يسكنها 50,000 شخص أو أكثر؟","o":["75 mph","80 mph","70 mph","85 mph"],"h1":"إنه من أعلى الحدود في البلاد.","h2":"يحدّد قانون Montana سرعة 80 mph في كل الأوقات على الطرق السريعة بين الولايات خارج المناطق الحضرية التي يسكنها 50,000 شخص أو أكثر، إلا إذا كانت هناك لافتة بحد أقل.","p":"صحيح. الطرق السريعة بين الولايات في ريف Montana حدها 80 mph."},"ref":{"doc":"MT","page":null}},{"id":"mt-012","scope":"MT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Montana, what is the speed limit on an interstate inside an urban area of 50,000 people or more, such as Billings?","o":["55 mph","70 mph","80 mph","65 mph"],"h1":"It is 15 mph lower than on rural interstates.","h2":"Montana law sets 65 mph on interstates inside urbanized areas of 50,000 people or more, because traffic there is heavier.","p":"Right. Urban interstates in Montana are 65 mph."},"es":{"q":"En Montana, ¿cuál es el límite de velocidad en una autopista interestatal dentro de una zona urbana de 50,000 habitantes o más, como Billings?","o":["55 mph","70 mph","80 mph","65 mph"],"h1":"Es 15 mph menos que en las interestatales rurales.","h2":"La ley de Montana fija 65 mph en las autopistas interestatales dentro de zonas urbanas de 50,000 habitantes o más, porque allí hay más tráfico.","p":"Correcto. Las interestatales urbanas de Montana son de 65 mph."},"zh":{"q":"在 Montana，在人口 50,000 或以上的城市地区里，比如 Billings，州际公路的限速是多少？","o":["55 英里/小时","70 英里/小时","80 英里/小时","65 英里/小时"],"h1":"它比乡村的州际公路低 15 英里/小时。","h2":"Montana 法律规定，在人口 50,000 或以上的城市化地区里，州际公路限速 65 英里/小时，因为那里车更多。","p":"对。Montana 城市里的州际公路限速 65 英里/小时。"},"vi":{"q":"Ở Montana, tốc độ tối đa trên xa lộ liên bang bên trong khu đô thị có 50,000 dân trở lên, như Billings, là bao nhiêu?","o":["55 mph","70 mph","80 mph","65 mph"],"h1":"Thấp hơn 15 mph so với xa lộ liên bang ở nông thôn.","h2":"Luật Montana đặt giới hạn 65 mph trên xa lộ liên bang bên trong khu đô thị có 50,000 dân trở lên, vì giao thông ở đó đông hơn.","p":"Đúng. Xa lộ liên bang trong đô thị ở Montana là 65 mph."},"tl":{"q":"Sa Montana, ano ang speed limit sa interstate sa loob ng urban area na may 50,000 tao o higit pa, gaya ng Billings?","o":["55 mph","70 mph","80 mph","65 mph"],"h1":"Mas mababa ito nang 15 mph kaysa sa mga interstate sa probinsiya.","h2":"Itinatakda ng batas ng Montana ang 65 mph sa mga interstate sa loob ng urban area na may 50,000 tao o higit pa, dahil mas mabigat ang trapiko roon.","p":"Tama. 65 mph ang mga interstate sa lungsod sa Montana."},"ar":{"q":"في Montana، ما الحد الأقصى للسرعة على الطريق السريع بين الولايات داخل منطقة حضرية يسكنها 50,000 شخص أو أكثر، مثل Billings؟","o":["55 mph","70 mph","80 mph","65 mph"],"h1":"إنه أقل بـ 15 mph من الطرق السريعة في الريف.","h2":"يحدّد قانون Montana سرعة 65 mph على الطرق السريعة بين الولايات داخل المناطق الحضرية التي يسكنها 50,000 شخص أو أكثر، لأن حركة المرور هناك أكثف.","p":"صحيح. الطرق السريعة بين الولايات داخل المدن في Montana حدها 65 mph."},"ref":{"doc":"MT","page":38}},{"id":"mt-013","scope":"MT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Montana, what is the daytime speed limit for a car on a two-lane highway?","o":["70 mph","60 mph","65 mph","80 mph"],"h1":"The night limit on the same road is 5 mph lower.","h2":"On a Montana two-lane highway, a car may go up to 70 mph in the daytime, unless a sign shows a different limit.","p":"Right. Two-lane highways are 70 mph in the daytime."},"es":{"q":"En Montana, ¿cuál es el límite de velocidad de día para un carro en una carretera de dos carriles?","o":["70 mph","60 mph","65 mph","80 mph"],"h1":"El límite de noche en esa misma carretera es 5 mph menor.","h2":"En una carretera de dos carriles de Montana, un carro puede ir hasta 70 mph de día, salvo que un letrero indique otro límite.","p":"Correcto. Las carreteras de dos carriles son de 70 mph de día."},"zh":{"q":"在 Montana，汽车在双车道公路上白天的限速是多少？","o":["70 英里/小时","60 英里/小时","65 英里/小时","80 英里/小时"],"h1":"同一条路晚上的限速低 5 英里/小时。","h2":"在 Montana 的双车道公路上，汽车白天最高可以开 70 英里/小时，除非标志显示不同的限速。","p":"对。双车道公路白天限速 70 英里/小时。"},"vi":{"q":"Ở Montana, tốc độ tối đa ban ngày cho xe hơi trên xa lộ hai làn là bao nhiêu?","o":["70 mph","60 mph","65 mph","80 mph"],"h1":"Giới hạn ban đêm trên cùng con đường thấp hơn 5 mph.","h2":"Trên xa lộ hai làn ở Montana, xe hơi được chạy tối đa 70 mph vào ban ngày, trừ khi biển báo cho thấy giới hạn khác.","p":"Đúng. Xa lộ hai làn là 70 mph vào ban ngày."},"tl":{"q":"Sa Montana, ano ang speed limit sa araw para sa kotse sa two-lane highway (highway na may dalawang lane)?","o":["70 mph","60 mph","65 mph","80 mph"],"h1":"Mas mababa nang 5 mph ang limit sa gabi sa parehong kalsada.","h2":"Sa two-lane highway sa Montana, ang kotse ay maaaring tumakbo hanggang 70 mph sa araw, maliban kung may karatulang nagpapakita ng ibang limit.","p":"Tama. 70 mph ang two-lane highway sa araw."},"ar":{"q":"في Montana، ما الحد الأقصى للسرعة في النهار للسيارة على طريق سريع بحارتين (two-lane highway)؟","o":["70 mph","60 mph","65 mph","80 mph"],"h1":"الحد في الليل على نفس الطريق أقل بـ 5 mph.","h2":"على طريق سريع بحارتين في Montana، يمكن للسيارة أن تسير حتى 70 mph في النهار، إلا إذا أظهرت لافتة حدًا مختلفًا.","p":"صحيح. الطرق السريعة بحارتين حدها 70 mph في النهار."},"ref":{"doc":"MT","page":38}},{"id":"mt-014","scope":"MT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Montana, what is the nighttime speed limit for a car on a two-lane highway?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"It is 5 mph lower than the daytime limit.","h2":"On a Montana two-lane highway, a car may go up to 65 mph at night, which is 5 mph lower than in the daytime.","p":"Right. Two-lane highways are 65 mph at night."},"es":{"q":"En Montana, ¿cuál es el límite de velocidad de noche para un carro en una carretera de dos carriles?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Es 5 mph menos que el límite de día.","h2":"En una carretera de dos carriles de Montana, un carro puede ir hasta 65 mph de noche, 5 mph menos que de día.","p":"Correcto. Las carreteras de dos carriles son de 65 mph de noche."},"zh":{"q":"在 Montana，汽车在双车道公路上晚上的限速是多少？","o":["55 英里/小时","60 英里/小时","65 英里/小时","70 英里/小时"],"h1":"它比白天的限速低 5 英里/小时。","h2":"在 Montana 的双车道公路上，汽车晚上最高可以开 65 英里/小时，比白天低 5 英里/小时。","p":"对。双车道公路晚上限速 65 英里/小时。"},"vi":{"q":"Ở Montana, tốc độ tối đa ban đêm cho xe hơi trên xa lộ hai làn là bao nhiêu?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Thấp hơn 5 mph so với giới hạn ban ngày.","h2":"Trên xa lộ hai làn ở Montana, xe hơi được chạy tối đa 65 mph vào ban đêm, thấp hơn 5 mph so với ban ngày.","p":"Đúng. Xa lộ hai làn là 65 mph vào ban đêm."},"tl":{"q":"Sa Montana, ano ang speed limit sa gabi para sa kotse sa two-lane highway?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Mas mababa ito nang 5 mph kaysa sa limit sa araw.","h2":"Sa two-lane highway sa Montana, ang kotse ay maaaring tumakbo hanggang 65 mph sa gabi, na mas mababa nang 5 mph kaysa sa araw.","p":"Tama. 65 mph ang two-lane highway sa gabi."},"ar":{"q":"في Montana، ما الحد الأقصى للسرعة في الليل للسيارة على طريق سريع بحارتين؟","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"إنه أقل بـ 5 mph من حد النهار.","h2":"على طريق سريع بحارتين في Montana، يمكن للسيارة أن تسير حتى 65 mph في الليل، وهذا أقل بـ 5 mph من النهار.","p":"صحيح. الطرق السريعة بحارتين حدها 65 mph في الليل."},"ref":{"doc":"MT","page":38}},{"id":"mt-015","scope":"MT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Montana, for speed limits, when does \"daytime\" begin and end?","o":["From sunrise to sunset","From 6 a.m. to 6 p.m.","From 7 a.m. to 9 p.m.","From half an hour before sunrise to half an hour after sunset"],"h1":"It adds a little time at each end of the day.","h2":"Montana law defines daytime as from half an hour before sunrise to half an hour after sunset, and every other hour counts as nighttime.","p":"Right. Daytime runs half an hour before sunrise to half an hour after sunset."},"es":{"q":"En Montana, para los límites de velocidad, ¿cuándo empieza y termina el \"día\"?","o":["Desde la salida hasta la puesta del sol","De 6 a.m. a 6 p.m.","De 7 a.m. a 9 p.m.","Desde media hora antes de la salida del sol hasta media hora después de la puesta"],"h1":"Agrega un poco de tiempo a cada extremo del día.","h2":"La ley de Montana define el día como desde media hora antes de la salida del sol hasta media hora después de la puesta, y toda otra hora cuenta como noche.","p":"Correcto. El día va de media hora antes del amanecer a media hora después del atardecer."},"zh":{"q":"在 Montana，对限速来说，“白天”从什么时候开始，到什么时候结束？","o":["从日出到日落","从早上 6 点到晚上 6 点","从早上 7 点到晚上 9 点","从日出前半小时到日落后半小时"],"h1":"它在一天的两头各多加一点时间。","h2":"Montana 法律规定，白天是从日出前半小时到日落后半小时，其他时间都算晚上。","p":"对。白天是从日出前半小时到日落后半小时。"},"vi":{"q":"Ở Montana, đối với giới hạn tốc độ, \"ban ngày\" bắt đầu và kết thúc khi nào?","o":["Từ lúc mặt trời mọc đến lúc mặt trời lặn","Từ 6 giờ sáng đến 6 giờ chiều","Từ 7 giờ sáng đến 9 giờ tối","Từ nửa giờ trước khi mặt trời mọc đến nửa giờ sau khi mặt trời lặn"],"h1":"Có thêm một chút thời gian ở mỗi đầu ngày.","h2":"Luật Montana định nghĩa ban ngày là từ nửa giờ trước khi mặt trời mọc đến nửa giờ sau khi mặt trời lặn, và mọi giờ khác được tính là ban đêm.","p":"Đúng. Ban ngày là từ nửa giờ trước khi mặt trời mọc đến nửa giờ sau khi mặt trời lặn."},"tl":{"q":"Sa Montana, para sa speed limit, kailan nagsisimula at nagtatapos ang \"araw\" (daytime)?","o":["Mula pagsikat hanggang paglubog ng araw","Mula 6 a.m. hanggang 6 p.m.","Mula 7 a.m. hanggang 9 p.m.","Mula kalahating oras bago sumikat ang araw hanggang kalahating oras pagkalubog ng araw"],"h1":"May dagdag na kaunting oras sa bawat dulo ng araw.","h2":"Itinuturing ng batas ng Montana na daytime ang oras mula kalahating oras bago sumikat ang araw hanggang kalahating oras pagkalubog ng araw, at ang lahat ng ibang oras ay gabi.","p":"Tama. Ang daytime ay mula kalahating oras bago sumikat hanggang kalahating oras pagkalubog ng araw."},"ar":{"q":"في Montana، بالنسبة لحدود السرعة، متى يبدأ \"النهار\" (daytime) ومتى ينتهي؟","o":["من شروق الشمس إلى غروبها","من 6 صباحًا إلى 6 مساءً","من 7 صباحًا إلى 9 مساءً","من نصف ساعة قبل شروق الشمس إلى نصف ساعة بعد غروبها"],"h1":"يضيف وقتًا قليلًا في كل طرف من اليوم.","h2":"يعرّف قانون Montana النهار بأنه من نصف ساعة قبل شروق الشمس إلى نصف ساعة بعد غروبها، وكل ساعة أخرى تُحسب ليلًا.","p":"صحيح. النهار من نصف ساعة قبل الشروق إلى نصف ساعة بعد الغروب."},"ref":{"doc":"MT","page":null}},{"id":"mt-016","scope":"MT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Montana, what is the speed limit in an urban district, if no sign says otherwise?","o":["20 mph","25 mph","35 mph","45 mph"],"h1":"It is the same number many states use near homes.","h2":"Montana law sets 25 mph in urban districts unless a different limit is posted, because people and cars are close together there.","p":"Right. Urban districts are 25 mph."},"es":{"q":"En Montana, ¿cuál es el límite de velocidad en una zona urbana, si no hay letrero que diga otra cosa?","o":["20 mph","25 mph","35 mph","45 mph"],"h1":"Es el mismo número que muchos estados usan cerca de las casas.","h2":"La ley de Montana fija 25 mph en zonas urbanas salvo que se indique otro límite, porque allí la gente y los carros están muy cerca.","p":"Correcto. Las zonas urbanas son de 25 mph."},"zh":{"q":"在 Montana，如果没有标志另外规定，城区（urban district）的限速是多少？","o":["20 英里/小时","25 英里/小时","35 英里/小时","45 英里/小时"],"h1":"很多州在住家附近也用这个数字。","h2":"Montana 法律规定，除非标出不同的限速，城区限速 25 英里/小时，因为那里人和车都很近。","p":"对。城区限速 25 英里/小时。"},"vi":{"q":"Ở Montana, tốc độ tối đa trong khu đô thị là bao nhiêu, nếu không có biển báo khác?","o":["20 mph","25 mph","35 mph","45 mph"],"h1":"Đây là con số mà nhiều tiểu bang dùng gần khu nhà ở.","h2":"Luật Montana đặt giới hạn 25 mph trong khu đô thị trừ khi có biển báo giới hạn khác, vì ở đó người và xe ở gần nhau.","p":"Đúng. Khu đô thị là 25 mph."},"tl":{"q":"Sa Montana, ano ang speed limit sa urban district kung walang karatulang nagsasabi ng iba?","o":["20 mph","25 mph","35 mph","45 mph"],"h1":"Ito ang parehong numero na ginagamit ng maraming estado malapit sa mga bahay.","h2":"Itinatakda ng batas ng Montana ang 25 mph sa mga urban district maliban kung may nakapaskil na ibang limit, dahil magkakalapit doon ang mga tao at sasakyan.","p":"Tama. 25 mph ang mga urban district."},"ar":{"q":"في Montana، ما الحد الأقصى للسرعة في منطقة حضرية (urban district) إذا لم تقل لافتة غير ذلك؟","o":["20 mph","25 mph","35 mph","45 mph"],"h1":"إنه نفس الرقم الذي تستخدمه ولايات كثيرة قرب البيوت.","h2":"يحدّد قانون Montana سرعة 25 mph في المناطق الحضرية إلا إذا كانت هناك لافتة بحد مختلف، لأن الناس والسيارات قريبون من بعضهم هناك.","p":"صحيح. المناطق الحضرية حدها 25 mph."},"ref":{"doc":"MT","page":null}},{"id":"mt-017","scope":"MT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Montana, on a two-lane highway, when may you go up to 10 mph over the limit?","o":["Whenever traffic is light","When you are late for work","Only while passing in a passing zone","Only at night on empty roads"],"h1":"It is a short moment, not a whole trip.","h2":"Montana lets you exceed the limit by up to 10 mph only while passing on a two-lane highway in a passing zone, and you must return safely to the right lane.","p":"Right. Only while passing, in a passing zone."},"es":{"q":"En Montana, en una carretera de dos carriles, ¿cuándo puede ir hasta 10 mph por encima del límite?","o":["Siempre que haya poco tráfico","Cuando va tarde al trabajo","Solo mientras rebasa en una zona de rebase","Solo de noche en caminos vacíos"],"h1":"Es un momento corto, no todo el viaje.","h2":"Montana le permite pasar el límite hasta por 10 mph solo mientras rebasa en una carretera de dos carriles, en una zona de rebase, y debe volver con seguridad al carril derecho.","p":"Correcto. Solo al rebasar, en una zona de rebase."},"zh":{"q":"在 Montana，在双车道公路上，什么时候可以超过限速最多 10 英里/小时？","o":["只要车少的时候","上班要迟到的时候","只有在超车区超车的时候","只有晚上路上没车的时候"],"h1":"这只是很短的一会儿，不是整段路程。","h2":"Montana 只允许你在双车道公路的超车区超车时，超过限速最多 10 英里/小时，而且你必须安全地回到右边车道。","p":"对。只有在超车区超车的时候。"},"vi":{"q":"Ở Montana, trên xa lộ hai làn, khi nào bạn được chạy vượt giới hạn tối đa 10 mph?","o":["Bất cứ khi nào xe cộ ít","Khi bạn bị trễ giờ làm","Chỉ khi đang vượt xe trong khu vực được phép vượt","Chỉ vào ban đêm trên đường vắng"],"h1":"Đó là một khoảnh khắc ngắn, không phải cả chuyến đi.","h2":"Montana cho phép bạn chạy vượt giới hạn tối đa 10 mph chỉ khi đang vượt xe trên xa lộ hai làn trong khu vực được phép vượt, và bạn phải trở lại làn bên phải một cách an toàn.","p":"Đúng. Chỉ khi đang vượt xe, trong khu vực được phép vượt."},"tl":{"q":"Sa Montana, sa two-lane highway, kailan ka maaaring lumampas nang hanggang 10 mph sa limit?","o":["Kapag kaunti ang trapiko","Kapag huli ka na sa trabaho","Habang nag-o-overtake lang sa passing zone","Sa gabi lang sa walang lamang kalsada"],"h1":"Maikling sandali lang ito, hindi ang buong biyahe.","h2":"Pinapayagan ka ng Montana na lumampas nang hanggang 10 mph sa limit habang nag-o-overtake lang sa two-lane highway sa passing zone, at dapat kang bumalik nang ligtas sa kanang lane.","p":"Tama. Habang nag-o-overtake lang, sa passing zone."},"ar":{"q":"في Montana، على طريق سريع بحارتين، متى يمكنك أن تتجاوز الحد بما يصل إلى 10 mph؟","o":["عندما تكون حركة المرور خفيفة","عندما تتأخر عن العمل","فقط أثناء التجاوز في منطقة يُسمح فيها بالتجاوز","فقط في الليل على الطرق الخالية"],"h1":"إنها لحظة قصيرة، وليست رحلة كاملة.","h2":"تسمح Montana بتجاوز الحد بما يصل إلى 10 mph فقط أثناء التجاوز على طريق سريع بحارتين في منطقة يُسمح فيها بالتجاوز، ويجب أن تعود بأمان إلى الحارة اليمنى.","p":"صحيح. فقط أثناء التجاوز، في منطقة يُسمح فيها بالتجاوز."},"ref":{"doc":"MT","page":38}},{"id":"mt-018","scope":"MT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Montana, a driver under 21 breaks the law with what blood alcohol level or more?","o":["0.08 percent","0.05 percent","0.02 percent","0.10 percent"],"h1":"It is far below the adult limit.","h2":"In Montana it is illegal for a person under 21 to drive with a blood alcohol level of 0.02 percent or more.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Montana, ¿a partir de qué nivel de alcohol en la sangre viola la ley un conductor menor de 21 años?","o":["0.08 por ciento","0.05 por ciento","0.02 por ciento","0.10 por ciento"],"h1":"Está muy por debajo del límite para adultos.","h2":"En Montana es ilegal que una persona menor de 21 años maneje con un nivel de alcohol en la sangre de 0.02 por ciento o más.","p":"Correcto. Para menores de 21, el límite es 0.02."},"zh":{"q":"在 Montana，21 岁以下的司机血液酒精浓度达到多少或更高就违法？","o":["0.08%","0.05%","0.02%","0.10%"],"h1":"它远低于成年人的限值。","h2":"在 Montana，21 岁以下的人血液酒精浓度达到 0.02% 或更高时开车是违法的。","p":"对。21 岁以下，限值是 0.02。"},"vi":{"q":"Ở Montana, người lái dưới 21 tuổi vi phạm luật khi nồng độ cồn trong máu từ mức nào trở lên?","o":["0.08 phần trăm","0.05 phần trăm","0.02 phần trăm","0.10 phần trăm"],"h1":"Mức này thấp hơn nhiều so với giới hạn của người lớn.","h2":"Ở Montana, người dưới 21 tuổi lái xe với nồng độ cồn trong máu từ 0.02 phần trăm trở lên là phạm luật.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa Montana, lumalabag sa batas ang driver na wala pang 21 kapag ang blood alcohol level ay umabot sa anong antas o higit pa?","o":["0.08 porsiyento","0.05 porsiyento","0.02 porsiyento","0.10 porsiyento"],"h1":"Mas mababa ito nang malaki kaysa sa limit para sa adult.","h2":"Sa Montana, bawal sa taong wala pang 21 na magmaneho na may blood alcohol level na 0.02 porsiyento o higit pa.","p":"Tama. Kung wala pang 21, ang limit ay 0.02."},"ar":{"q":"في Montana، يخالف السائق الذي عمره أقل من 21 سنة القانون عند أي نسبة كحول في الدم أو أكثر؟","o":["0.08 بالمئة","0.05 بالمئة","0.02 بالمئة","0.10 بالمئة"],"h1":"إنها أقل بكثير من حد البالغين.","h2":"في Montana يُمنع على الشخص الذي عمره أقل من 21 سنة أن يقود ونسبة الكحول في دمه 0.02 بالمئة أو أكثر.","p":"صحيح. لمن هم أقل من 21 سنة، الحد هو 0.02."},"ref":{"doc":"MT","page":72}},{"id":"mt-019","scope":"MT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Montana, what is the legal blood alcohol limit for an adult driving a regular car?","o":["0.05 percent","0.08 percent","0.04 percent","0.10 percent"],"h1":"It is the most common adult limit in the United States.","h2":"In Montana an adult driving a regular car is legally under the influence at a blood alcohol level of 0.08 percent or more.","p":"Right. The adult limit is 0.08."},"es":{"q":"En Montana, ¿cuál es el límite legal de alcohol en la sangre para un adulto que maneja un carro común?","o":["0.05 por ciento","0.08 por ciento","0.04 por ciento","0.10 por ciento"],"h1":"Es el límite para adultos más común en Estados Unidos.","h2":"En Montana, un adulto que maneja un carro común está legalmente bajo la influencia con un nivel de alcohol de 0.08 por ciento o más.","p":"Correcto. El límite para adultos es 0.08."},"zh":{"q":"在 Montana，成年人开普通汽车时，法定的血液酒精浓度限值是多少？","o":["0.05%","0.08%","0.04%","0.10%"],"h1":"这是美国最常见的成年人限值。","h2":"在 Montana，成年人开普通汽车时，血液酒精浓度达到 0.08% 或更高，在法律上就算受酒精影响。","p":"对。成年人的限值是 0.08。"},"vi":{"q":"Ở Montana, giới hạn nồng độ cồn trong máu theo luật cho người lớn lái xe hơi thông thường là bao nhiêu?","o":["0.05 phần trăm","0.08 phần trăm","0.04 phần trăm","0.10 phần trăm"],"h1":"Đây là giới hạn phổ biến nhất cho người lớn ở Hoa Kỳ.","h2":"Ở Montana, người lớn lái xe hơi thông thường bị coi là say xỉn theo luật khi nồng độ cồn trong máu từ 0.08 phần trăm trở lên.","p":"Đúng. Giới hạn cho người lớn là 0.08."},"tl":{"q":"Sa Montana, ano ang legal na blood alcohol limit para sa adult na nagmamaneho ng karaniwang kotse?","o":["0.05 porsiyento","0.08 porsiyento","0.04 porsiyento","0.10 porsiyento"],"h1":"Ito ang pinakakaraniwang limit para sa adult sa Estados Unidos.","h2":"Sa Montana, ang adult na nagmamaneho ng karaniwang kotse ay legal na lasing kapag ang blood alcohol level ay 0.08 porsiyento o higit pa.","p":"Tama. Ang limit para sa adult ay 0.08."},"ar":{"q":"في Montana، ما الحد القانوني لنسبة الكحول في الدم للبالغ الذي يقود سيارة عادية؟","o":["0.05 بالمئة","0.08 بالمئة","0.04 بالمئة","0.10 بالمئة"],"h1":"إنه الحد الأكثر شيوعًا للبالغين في الولايات المتحدة.","h2":"في Montana يُعتبر البالغ الذي يقود سيارة عادية تحت تأثير الكحول قانونيًا عندما تكون نسبة الكحول في دمه 0.08 بالمئة أو أكثر.","p":"صحيح. حد البالغين هو 0.08."},"ref":{"doc":"MT","page":72}},{"id":"mt-020","scope":"MT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Montana, where can a driver be ticketed for using a hand-held phone while driving?","o":["On every road in the state","Only on interstate highways","Only in school zones statewide","Only in cities or counties with their own ban"],"h1":"Montana has no statewide ban, but some local governments do.","h2":"Montana has no statewide ban on hand-held phones or texting while driving, but many cities have their own bans, so a ticket depends on local law.","p":"Right. Only where a city or county has its own ban."},"es":{"q":"En Montana, ¿dónde se puede multar a un conductor por usar el teléfono en la mano al manejar?","o":["En todos los caminos del estado","Solo en las autopistas interestatales","Solo en zonas escolares de todo el estado","Solo en ciudades o condados con su propia prohibición"],"h1":"Montana no tiene una prohibición estatal, pero algunos gobiernos locales sí.","h2":"Montana no tiene una prohibición estatal de usar el teléfono en la mano o enviar mensajes al manejar, pero muchas ciudades tienen la suya, así que la multa depende de la ley local.","p":"Correcto. Solo donde la ciudad o el condado lo prohíbe."},"zh":{"q":"在 Montana，司机在哪里开车时手拿手机可能会被开罚单？","o":["全州每一条路上","只在州际公路上","只在全州的学校区域","只在有自己禁令的市或县"],"h1":"Montana 没有全州的禁令，但有些地方政府有。","h2":"Montana 没有全州禁止开车时手拿手机或发短信的法律，但很多城市有自己的禁令，所以会不会被开罚单要看当地法律。","p":"对。只在有自己禁令的市或县。"},"vi":{"q":"Ở Montana, người lái có thể bị phạt ở đâu vì cầm điện thoại trên tay khi lái xe?","o":["Trên mọi con đường trong tiểu bang","Chỉ trên xa lộ liên bang","Chỉ trong khu vực trường học trên toàn tiểu bang","Chỉ ở những thành phố hoặc quận có lệnh cấm riêng"],"h1":"Montana không có lệnh cấm toàn tiểu bang, nhưng một số chính quyền địa phương có.","h2":"Montana không có lệnh cấm toàn tiểu bang về việc cầm điện thoại hoặc nhắn tin khi lái xe, nhưng nhiều thành phố có lệnh cấm riêng, nên việc bị phạt tùy vào luật địa phương.","p":"Đúng. Chỉ ở nơi thành phố hoặc quận có lệnh cấm riêng."},"tl":{"q":"Sa Montana, saan maaaring tiketan ang driver dahil sa paggamit ng hawak na telepono habang nagmamaneho?","o":["Sa bawat kalsada sa estado","Sa mga interstate highway lang","Sa mga school zone lang sa buong estado","Sa mga lungsod o county lang na may sariling pagbabawal"],"h1":"Walang pagbabawal sa buong estado ang Montana, pero mayroon ang ilang lokal na pamahalaan.","h2":"Walang pagbabawal sa buong Montana sa paghawak ng telepono o pag-text habang nagmamaneho, pero maraming lungsod ang may sariling pagbabawal, kaya ang tiket ay depende sa lokal na batas.","p":"Tama. Kung saan lang may sariling pagbabawal ang lungsod o county."},"ar":{"q":"في Montana، أين يمكن أن يحصل السائق على مخالفة لاستخدامه الهاتف باليد أثناء القيادة؟","o":["على كل طريق في الولاية","على الطرق السريعة بين الولايات فقط","في مناطق المدارس فقط في كل الولاية","فقط في المدن أو المقاطعات التي لها منع خاص بها"],"h1":"ليس في Montana منع على مستوى الولاية، لكن بعض الحكومات المحلية لديها منع.","h2":"ليس في Montana منع على مستوى الولاية لاستخدام الهاتف باليد أو كتابة الرسائل أثناء القيادة، لكن مدنًا كثيرة لها منع خاص بها، لذلك تعتمد المخالفة على القانون المحلي.","p":"صحيح. فقط حيث يكون للمدينة أو المقاطعة منع خاص بها."},"ref":{"doc":"MT","page":49}},{"id":"mt-021","scope":"MT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Montana, can police stop an adult driver only because they are not wearing a seat belt?","o":["No, only for another violation","Yes, at any time","Yes, but only at night","Yes, but only on interstates"],"h1":"For adults, the belt law is enforced together with another stop.","h2":"Montana's adult seat belt law is secondary, so police may ticket for it only after stopping a driver for another violation; you should still always buckle up.","p":"Right. For adults, the seat belt law is secondary."},"es":{"q":"En Montana, ¿puede la policía detener a un conductor adulto solo porque no lleva el cinturón de seguridad?","o":["No, solo por otra infracción","Sí, en cualquier momento","Sí, pero solo de noche","Sí, pero solo en interestatales"],"h1":"Para adultos, la ley del cinturón se aplica junto con otra detención.","h2":"La ley del cinturón para adultos en Montana es secundaria, así que la policía puede multar por ella solo después de detener al conductor por otra infracción; aun así, siempre debe abrocharse.","p":"Correcto. Para adultos, la ley del cinturón es secundaria."},"zh":{"q":"在 Montana，警察可以只因为成年司机没系安全带就让他停车吗？","o":["不可以，只能因为其他违规","可以，任何时候","可以，但只在晚上","可以，但只在州际公路上"],"h1":"对成年人来说，安全带法要和其他原因的拦车一起执行。","h2":"Montana 的成年人安全带法是次要执法，所以警察只有在因为其他违规让司机停车以后，才可以为这个开罚单；你还是应该一直系好安全带。","p":"对。对成年人来说，安全带法是次要执法。"},"vi":{"q":"Ở Montana, cảnh sát có thể dừng xe một người lái là người lớn chỉ vì họ không thắt dây an toàn không?","o":["Không, chỉ khi có vi phạm khác","Có, bất cứ lúc nào","Có, nhưng chỉ vào ban đêm","Có, nhưng chỉ trên xa lộ liên bang"],"h1":"Với người lớn, luật dây an toàn được áp dụng cùng với một lần dừng xe vì lý do khác.","h2":"Luật dây an toàn cho người lớn ở Montana là luật thứ cấp, nên cảnh sát chỉ được phạt lỗi này sau khi đã dừng xe vì một vi phạm khác; bạn vẫn nên luôn thắt dây an toàn.","p":"Đúng. Với người lớn, luật dây an toàn là luật thứ cấp."},"tl":{"q":"Sa Montana, maaari bang patigilin ng pulis ang adult na driver dahil lang hindi siya naka-seat belt?","o":["Hindi, kapag may ibang paglabag lang","Oo, kahit kailan","Oo, pero sa gabi lang","Oo, pero sa mga interstate lang"],"h1":"Para sa adult, ipinapatupad ang batas sa seat belt kasabay ng ibang dahilan ng pagpapatigil.","h2":"Secondary ang batas sa seat belt para sa adult sa Montana, kaya maaari lang itong tiketan ng pulis pagkatapos patigilin ang driver dahil sa ibang paglabag; dapat ka pa ring laging mag-seat belt.","p":"Tama. Para sa adult, secondary ang batas sa seat belt."},"ar":{"q":"في Montana، هل يمكن للشرطة أن توقف سائقًا بالغًا فقط لأنه لا يربط حزام الأمان؟","o":["لا، فقط مع مخالفة أخرى","نعم، في أي وقت","نعم، لكن في الليل فقط","نعم، لكن على الطرق السريعة بين الولايات فقط"],"h1":"بالنسبة للبالغين، يُطبَّق قانون الحزام مع إيقاف لسبب آخر.","h2":"قانون حزام الأمان للبالغين في Montana قانون ثانوي، لذلك يمكن للشرطة أن تعطي مخالفة عليه فقط بعد إيقاف السائق بسبب مخالفة أخرى؛ ومع ذلك يجب أن تربط الحزام دائمًا.","p":"صحيح. بالنسبة للبالغين، قانون حزام الأمان ثانوي."},"ref":{"doc":"MT","page":null}},{"id":"mt-022","scope":"MT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Montana, you come up on a stopped police car, emergency vehicle, or highway work vehicle with its lights flashing. What must you do?","o":["Keep your lane and your speed","Stop next to it until it leaves","Slow down and move to a lane away from it if you safely can","Honk to warn the workers"],"h1":"The law asks you to give workers both space and time.","h2":"In Montana you must slow down when you pass a stopped police, emergency or highway work vehicle with flashing lights, and move to a lane that is not next to it when you safely can.","p":"Right. Slow down and move over when you safely can."},"es":{"q":"En Montana, usted se acerca a un carro de policía, vehículo de emergencia o vehículo de obras viales detenido con las luces intermitentes. ¿Qué debe hacer?","o":["Seguir en su carril y a su velocidad","Pararse a su lado hasta que se vaya","Bajar la velocidad y pasarse a un carril alejado si puede hacerlo con seguridad","Tocar la bocina para avisar a los trabajadores"],"h1":"La ley le pide dar a los trabajadores espacio y tiempo.","h2":"En Montana, usted debe bajar la velocidad al pasar un vehículo de policía, de emergencia o de obras viales detenido con luces intermitentes, y pasarse a un carril que no esté junto a él cuando pueda hacerlo con seguridad.","p":"Correcto. Baje la velocidad y cámbiese de carril cuando sea seguro."},"zh":{"q":"在 Montana，你遇到一辆停着、闪着灯的警车、急救车辆或公路工作车辆。你必须怎么做？","o":["保持你的车道和速度","在它旁边停车，直到它开走","减速，如果能安全换道，就换到离它远的车道","按喇叭提醒工作人员"],"h1":"法律要求你给工作人员留出空间和时间。","h2":"在 Montana，你经过停着、闪着灯的警车、急救车辆或公路工作车辆时必须减速，能安全换道时，要换到不紧挨着它的车道。","p":"对。减速，能安全换道时就让出车道。"},"vi":{"q":"Ở Montana, bạn đến gần một xe cảnh sát, xe cấp cứu hoặc xe làm việc trên xa lộ đang dừng và nháy đèn. Bạn phải làm gì?","o":["Giữ nguyên làn và tốc độ","Dừng bên cạnh cho đến khi xe đó rời đi","Giảm tốc độ và chuyển sang làn cách xa xe đó nếu có thể làm an toàn","Bấm còi để cảnh báo công nhân"],"h1":"Luật yêu cầu bạn cho công nhân cả khoảng cách và thời gian.","h2":"Ở Montana, bạn phải giảm tốc độ khi đi qua xe cảnh sát, xe cấp cứu hoặc xe làm việc trên xa lộ đang dừng và nháy đèn, và chuyển sang làn không sát bên xe đó khi có thể làm an toàn.","p":"Đúng. Giảm tốc độ và chuyển làn khi có thể làm an toàn."},"tl":{"q":"Sa Montana, papalapit ka sa nakahintong sasakyan ng pulis, emergency vehicle, o sasakyang pantrabaho sa highway na kumikislap ang ilaw. Ano ang dapat mong gawin?","o":["Manatili sa iyong lane at bilis","Huminto sa tabi nito hanggang umalis ito","Bumagal at lumipat sa lane na malayo rito kung ligtas","Bumusina para balaan ang mga manggagawa"],"h1":"Hinihingi ng batas na bigyan mo ang mga manggagawa ng espasyo at oras.","h2":"Sa Montana, dapat kang bumagal kapag dumadaan sa nakahintong sasakyan ng pulis, emergency o pantrabaho sa highway na kumikislap ang ilaw, at lumipat sa lane na hindi katabi nito kapag ligtas.","p":"Tama. Bumagal at lumipat ng lane kapag ligtas."},"ar":{"q":"في Montana، تقترب من سيارة شرطة أو مركبة طوارئ أو مركبة عمل على الطريق السريع متوقفة وأضواؤها تومض. ماذا يجب أن تفعل؟","o":["تبقى في حارتك وبنفس سرعتك","تتوقف بجانبها حتى تغادر","تخفّف السرعة وتنتقل إلى حارة بعيدة عنها إذا أمكنك ذلك بأمان","تستخدم البوق لتحذير العمال"],"h1":"يطلب القانون أن تعطي العمال مساحة ووقتًا.","h2":"في Montana يجب أن تخفّف السرعة عندما تمر بجانب سيارة شرطة أو مركبة طوارئ أو مركبة عمل على الطريق السريع متوقفة وأضواؤها تومض، وأن تنتقل إلى حارة ليست بجانبها عندما يمكنك ذلك بأمان.","p":"صحيح. خفّف السرعة وانتقل إلى حارة أخرى عندما يمكنك ذلك بأمان."},"ref":{"doc":"MT","page":null}},{"id":"mt-023","scope":"MT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Montana, on a divided highway with a raised median, which drivers must stop for a school bus with flashing red lights?","o":["All drivers in both directions","Drivers going the same direction as the bus","Only drivers in the lane next to the bus","Only drivers going the opposite direction"],"h1":"The raised median keeps children from crossing the far side.","h2":"On a Montana divided highway with a raised median, drivers going the same direction as a stopped school bus must stop, while traffic on the other side does not have to.","p":"Right. With a raised median, same-direction traffic stops."},"es":{"q":"En Montana, en una carretera dividida con camellón elevado, ¿qué conductores deben parar ante un autobús escolar con luces rojas intermitentes?","o":["Todos los conductores en ambas direcciones","Los que van en la misma dirección que el autobús","Solo los del carril junto al autobús","Solo los que van en dirección contraria"],"h1":"El camellón elevado impide que los niños crucen al otro lado.","h2":"En una carretera dividida con camellón elevado en Montana, los conductores que van en la misma dirección que el autobús escolar detenido deben parar, y el tráfico del otro lado no tiene que hacerlo.","p":"Correcto. Con camellón elevado, para el tráfico de la misma dirección."},"zh":{"q":"在 Montana，在有凸起中央隔离带的分隔公路上，哪些司机必须为闪着红灯的校车停车？","o":["两个方向的所有司机","和校车同方向的司机","只有校车旁边车道的司机","只有对面方向的司机"],"h1":"凸起的隔离带让孩子不会穿过远的那一边。","h2":"在 Montana 有凸起中央隔离带的分隔公路上，和停着的校车同方向的司机必须停车，另一边的车不必停。","p":"对。有凸起的隔离带时，同方向的车要停。"},"vi":{"q":"Ở Montana, trên xa lộ có dải phân cách nổi (raised median), những người lái nào phải dừng lại khi xe buýt trường học nháy đèn đỏ?","o":["Tất cả người lái ở cả hai chiều","Người lái đi cùng chiều với xe buýt","Chỉ người lái ở làn sát bên xe buýt","Chỉ người lái đi ngược chiều"],"h1":"Dải phân cách nổi giữ cho trẻ em không băng qua phía bên kia.","h2":"Trên xa lộ có dải phân cách nổi ở Montana, người lái đi cùng chiều với xe buýt trường học đang dừng phải dừng lại, còn xe ở phía bên kia thì không cần dừng.","p":"Đúng. Có dải phân cách nổi thì xe đi cùng chiều phải dừng."},"tl":{"q":"Sa Montana, sa divided highway na may raised median (nakataas na harang sa gitna), sinong mga driver ang dapat huminto para sa school bus na kumikislap ang pulang ilaw?","o":["Lahat ng driver sa dalawang direksiyon","Mga driver na papunta sa parehong direksiyon ng bus","Mga driver lang sa lane na katabi ng bus","Mga driver lang na papunta sa kabilang direksiyon"],"h1":"Pinipigilan ng raised median ang mga bata na tumawid sa kabilang panig.","h2":"Sa divided highway sa Montana na may raised median, ang mga driver na papunta sa parehong direksiyon ng nakahintong school bus ay dapat huminto, at ang trapiko sa kabilang panig ay hindi kailangang huminto.","p":"Tama. Kapag may raised median, ang trapikong kapareho ng direksiyon ang humihinto."},"ar":{"q":"في Montana، على طريق سريع مقسوم بفاصل مرتفع في الوسط (raised median)، أي السائقين يجب أن يتوقفوا لحافلة مدرسية أضواؤها الحمراء تومض؟","o":["كل السائقين في الاتجاهين","السائقون الذين يسيرون في نفس اتجاه الحافلة","فقط السائقون في الحارة التي بجانب الحافلة","فقط السائقون الذين يسيرون في الاتجاه المعاكس"],"h1":"الفاصل المرتفع يمنع الأطفال من العبور إلى الجانب الآخر.","h2":"على طريق سريع مقسوم في Montana بفاصل مرتفع، يجب على السائقين الذين يسيرون في نفس اتجاه الحافلة المدرسية المتوقفة أن يتوقفوا، أما حركة المرور على الجانب الآخر فلا يلزمها التوقف.","p":"صحيح. مع الفاصل المرتفع، تتوقف حركة المرور في نفس الاتجاه."},"ref":{"doc":"MT","page":40}},{"id":"mt-024","scope":"MT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Montana, what is the minimum liability insurance a driver must carry?","o":["$25,000 / $50,000 / $20,000","$25,000 / $50,000 / $15,000","$50,000 / $100,000 / $25,000","$15,000 / $30,000 / $10,000"],"h1":"The property damage part is $20,000.","h2":"Montana requires at least $25,000 for injury to one person, $50,000 for injuries in one crash, and $20,000 for property damage.","p":"Right. Montana's minimum is 25/50/20."},"es":{"q":"En Montana, ¿cuál es el seguro de responsabilidad mínimo que debe tener un conductor?","o":["$25,000 / $50,000 / $20,000","$25,000 / $50,000 / $15,000","$50,000 / $100,000 / $25,000","$15,000 / $30,000 / $10,000"],"h1":"La parte de daños a la propiedad es de $20,000.","h2":"Montana exige por lo menos $25,000 por lesiones a una persona, $50,000 por lesiones en un mismo choque y $20,000 por daños a la propiedad.","p":"Correcto. El mínimo en Montana es 25/50/20."},"zh":{"q":"在 Montana，司机必须买的最低责任保险是多少？","o":["$25,000 / $50,000 / $20,000","$25,000 / $50,000 / $15,000","$50,000 / $100,000 / $25,000","$15,000 / $30,000 / $10,000"],"h1":"财产损失的部分是 $20,000。","h2":"Montana 要求一个人受伤至少 $25,000，一次车祸中的伤害至少 $50,000，财产损失至少 $20,000。","p":"对。Montana 的最低标准是 25/50/20。"},"vi":{"q":"Ở Montana, mức bảo hiểm trách nhiệm (liability insurance) tối thiểu mà người lái phải có là bao nhiêu?","o":["$25,000 / $50,000 / $20,000","$25,000 / $50,000 / $15,000","$50,000 / $100,000 / $25,000","$15,000 / $30,000 / $10,000"],"h1":"Phần thiệt hại tài sản là $20,000.","h2":"Montana yêu cầu ít nhất $25,000 cho thương tích của một người, $50,000 cho thương tích trong một vụ tai nạn, và $20,000 cho thiệt hại tài sản.","p":"Đúng. Mức tối thiểu của Montana là 25/50/20."},"tl":{"q":"Sa Montana, ano ang pinakamababang liability insurance na dapat mayroon ang driver?","o":["$25,000 / $50,000 / $20,000","$25,000 / $50,000 / $15,000","$50,000 / $100,000 / $25,000","$15,000 / $30,000 / $10,000"],"h1":"$20,000 ang bahagi para sa pinsala sa ari-arian.","h2":"Hinihingi ng Montana ang hindi bababa sa $25,000 para sa pinsala sa isang tao, $50,000 para sa mga pinsala sa isang aksidente, at $20,000 para sa pinsala sa ari-arian.","p":"Tama. 25/50/20 ang pinakamababa sa Montana."},"ar":{"q":"في Montana، ما الحد الأدنى لتأمين المسؤولية (liability insurance) الذي يجب أن يكون عند السائق؟","o":["$25,000 / $50,000 / $20,000","$25,000 / $50,000 / $15,000","$50,000 / $100,000 / $25,000","$15,000 / $30,000 / $10,000"],"h1":"جزء الأضرار بالممتلكات هو $20,000.","h2":"تطلب Montana على الأقل $25,000 لإصابة شخص واحد، و$50,000 للإصابات في حادث واحد، و$20,000 للأضرار بالممتلكات.","p":"صحيح. الحد الأدنى في Montana هو 25/50/20."},"ref":{"doc":"MT","page":null}},{"id":"mt-025","scope":"MT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Montana, cattle are crossing the road ahead of you in open range country. What should you do?","o":["Honk so they move faster","Drive slowly through the herd","Nudge them gently with the bumper","Stop and wait until they have crossed"],"h1":"Animals can slip on pavement when they are scared.","h2":"In Montana's open range, when livestock are crossing the road you should stop and wait, because honking or pushing can make animals panic and fall.","p":"Right. Stop and wait for the animals to cross."},"es":{"q":"En Montana, unas vacas cruzan el camino delante de usted en zona de campo abierto. ¿Qué debe hacer?","o":["Tocar la bocina para que se apuren","Pasar despacio entre el ganado","Empujarlas suavemente con el parachoques","Parar y esperar hasta que hayan cruzado"],"h1":"Los animales pueden resbalar en el pavimento cuando se asustan.","h2":"En el campo abierto de Montana, cuando el ganado cruza el camino usted debe parar y esperar, porque la bocina o los empujones pueden asustar a los animales y hacerlos caer.","p":"Correcto. Pare y espere a que crucen los animales."},"zh":{"q":"在 Montana，在开放牧场（open range）地区，前面有牛在过马路。你应该怎么做？","o":["按喇叭让它们走快点","慢慢开过牛群","用保险杠轻轻推它们","停车，等它们过完"],"h1":"动物受惊时可能在路面上滑倒。","h2":"在 Montana 的开放牧场，牲畜过马路时你应该停车等待，因为按喇叭或推它们会让动物惊慌并摔倒。","p":"对。停车，等动物过完马路。"},"vi":{"q":"Ở Montana, bò đang băng qua đường phía trước bạn ở vùng chăn thả tự do (open range). Bạn nên làm gì?","o":["Bấm còi để chúng đi nhanh hơn","Lái chậm xuyên qua đàn bò","Đẩy nhẹ chúng bằng cản xe","Dừng lại và chờ đến khi chúng đã qua đường"],"h1":"Động vật có thể trượt ngã trên mặt đường khi chúng sợ hãi.","h2":"Ở vùng chăn thả tự do của Montana, khi gia súc đang băng qua đường, bạn nên dừng lại và chờ, vì bấm còi hoặc đẩy có thể làm con vật hoảng sợ và ngã.","p":"Đúng. Dừng lại và chờ các con vật băng qua."},"tl":{"q":"Sa Montana, tumatawid ang mga baka sa kalsada sa harap mo sa open range (lupang walang bakod). Ano ang dapat mong gawin?","o":["Bumusina para bumilis sila","Dahan-dahang magmaneho sa gitna ng kawan","Itulak sila nang marahan gamit ang bumper","Huminto at maghintay hanggang makatawid sila"],"h1":"Maaaring madulas ang mga hayop sa kalsada kapag natatakot sila.","h2":"Sa open range ng Montana, kapag tumatawid ang mga alagang hayop sa kalsada, dapat kang huminto at maghintay, dahil ang pagbusina o pagtulak ay maaaring magpataranta at magpabagsak sa mga hayop.","p":"Tama. Huminto at hintaying makatawid ang mga hayop."},"ar":{"q":"في Montana، أبقار تعبر الطريق أمامك في منطقة المراعي المفتوحة (open range). ماذا يجب أن تفعل؟","o":["تستخدم البوق حتى تتحرك أسرع","تقود ببطء وسط القطيع","تدفعها بلطف بمصدّ السيارة","تتوقف وتنتظر حتى تعبر"],"h1":"يمكن أن تنزلق الحيوانات على الطريق عندما تخاف.","h2":"في المراعي المفتوحة في Montana، عندما تعبر المواشي الطريق يجب أن تتوقف وتنتظر، لأن البوق أو الدفع قد يجعل الحيوانات تذعر وتسقط.","p":"صحيح. توقّف وانتظر حتى تعبر الحيوانات."},"ref":{"doc":"MT","page":67}},{"id":"mt-026","scope":"MT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Montana, what does \"open range\" mean for drivers?","o":["Roads closed to trucks","Land without a proper fence, where livestock may be on the road","Highways with no speed limit","Areas where hunting is allowed from cars"],"h1":"Think about what a fence keeps off the road.","h2":"In Montana, open range is land not closed in by a fence, including public highways, so cattle and other livestock may be on or near the road.","p":"Right. On open range, expect livestock on the road."},"es":{"q":"En Montana, ¿qué significa \"campo abierto\" (open range) para los conductores?","o":["Caminos cerrados a camiones","Terreno sin una cerca adecuada, donde puede haber ganado en el camino","Carreteras sin límite de velocidad","Zonas donde se permite cazar desde el carro"],"h1":"Piense en lo que una cerca mantiene fuera del camino.","h2":"En Montana, el campo abierto es el terreno que no está cerrado por una cerca, incluidas las carreteras públicas, así que puede haber vacas y otro ganado en el camino o cerca de él.","p":"Correcto. En campo abierto, espere ganado en el camino."},"zh":{"q":"在 Montana，“open range”（开放牧场）对司机来说是什么意思？","o":["禁止卡车通行的道路","没有正规围栏的土地，牲畜可能会在路上","没有限速的公路","可以在车里打猎的地区"],"h1":"想一想围栏能把什么挡在路外。","h2":"在 Montana，开放牧场是没有用围栏围起来的土地，也包括公共公路，所以牛和其他牲畜可能在路上或路边。","p":"对。在开放牧场，要预料路上会有牲畜。"},"vi":{"q":"Ở Montana, \"open range\" (vùng chăn thả tự do) có nghĩa gì đối với người lái?","o":["Đường cấm xe tải","Đất không có hàng rào đúng cách, nơi gia súc có thể ở trên đường","Xa lộ không có giới hạn tốc độ","Khu vực được phép săn bắn từ trong xe"],"h1":"Hãy nghĩ xem hàng rào giữ cái gì khỏi đường.","h2":"Ở Montana, vùng chăn thả tự do là đất không được rào lại, kể cả xa lộ công cộng, nên bò và các gia súc khác có thể ở trên hoặc gần đường.","p":"Đúng. Ở vùng chăn thả tự do, hãy dự đoán có gia súc trên đường."},"tl":{"q":"Sa Montana, ano ang ibig sabihin ng \"open range\" para sa mga driver?","o":["Mga kalsadang sarado sa mga trak","Lupang walang tamang bakod, kung saan maaaring may alagang hayop sa kalsada","Mga highway na walang speed limit","Mga lugar kung saan pinapayagan ang pangangaso mula sa kotse"],"h1":"Isipin kung ano ang pinipigilan ng bakod na makapunta sa kalsada.","h2":"Sa Montana, ang open range ay lupang hindi nababakuran, kasama ang mga pampublikong highway, kaya maaaring may baka at ibang alagang hayop sa kalsada o malapit dito.","p":"Tama. Sa open range, asahan na may alagang hayop sa kalsada."},"ar":{"q":"في Montana، ماذا يعني \"open range\" (المراعي المفتوحة) بالنسبة للسائقين؟","o":["طرق مغلقة أمام الشاحنات","أرض بدون سياج مناسب، حيث قد تكون المواشي على الطريق","طرق سريعة بدون حد للسرعة","مناطق يُسمح فيها بالصيد من السيارات"],"h1":"فكّر في ما يمنعه السياج من الوصول إلى الطريق.","h2":"في Montana، المراعي المفتوحة هي أرض غير محاطة بسياج، ومنها الطرق السريعة العامة، لذلك قد تكون الأبقار والمواشي الأخرى على الطريق أو قريبة منه.","p":"صحيح. في المراعي المفتوحة، توقّع وجود مواشٍ على الطريق."},"ref":{"doc":"MT","page":25}},{"id":"mt-027","scope":"MT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Montana, when does a driver license issued to someone under 21 expire?","o":["On the 21st birthday","On the 18th birthday","Four years after it is issued","Eight years after it is issued"],"h1":"It is tied to a birthday, not a number of years.","h2":"In Montana a driver license issued to someone under 21 expires on that person's 21st birthday.","p":"Right. It expires on the 21st birthday."},"es":{"q":"En Montana, ¿cuándo vence una licencia de manejo emitida a una persona menor de 21 años?","o":["En el cumpleaños número 21","En el cumpleaños número 18","Cuatro años después de emitida","Ocho años después de emitida"],"h1":"Depende de un cumpleaños, no de un número de años.","h2":"En Montana una licencia de manejo emitida a una persona menor de 21 años vence en su cumpleaños número 21.","p":"Correcto. Vence en el cumpleaños número 21."},"zh":{"q":"在 Montana，发给未满 21 岁的人的驾照什么时候到期？","o":["在 21 岁生日那天","在 18 岁生日那天","发证后四年","发证后八年"],"h1":"它和生日有关，而不是年数。","h2":"在 Montana，发给未满 21 岁的人的驾照在这个人 21 岁生日那天到期。","p":"对。它在 21 岁生日那天到期。"},"vi":{"q":"Ở Montana, bằng lái cấp cho người dưới 21 tuổi hết hạn khi nào?","o":["Vào sinh nhật 21 tuổi","Vào sinh nhật 18 tuổi","Bốn năm sau khi cấp","Tám năm sau khi cấp"],"h1":"Nó gắn với ngày sinh nhật, không phải số năm.","h2":"Ở Montana, bằng lái cấp cho người dưới 21 tuổi hết hạn vào ngày sinh nhật 21 tuổi của người đó.","p":"Đúng. Nó hết hạn vào sinh nhật 21 tuổi."},"tl":{"q":"Sa Montana, kailan mag-e-expire ang driver license na ibinigay sa taong wala pang 21 taong gulang?","o":["Sa ika-21 kaarawan","Sa ika-18 kaarawan","Apat na taon matapos itong ibigay","Walong taon matapos itong ibigay"],"h1":"Nakatali ito sa isang kaarawan, hindi sa bilang ng taon.","h2":"Sa Montana, ang driver license na ibinigay sa taong wala pang 21 taong gulang ay mag-e-expire sa ika-21 kaarawan ng taong iyon.","p":"Tama. Mag-e-expire ito sa ika-21 kaarawan."},"ar":{"q":"في Montana، متى تنتهي صلاحية رخصة القيادة الصادرة لشخص عمره أقل من 21 سنة؟","o":["في عيد ميلاده الحادي والعشرين","في عيد ميلاده الثامن عشر","بعد أربع سنوات من صدورها","بعد ثماني سنوات من صدورها"],"h1":"ترتبط بعيد ميلاد، لا بعدد من السنوات.","h2":"في Montana تنتهي صلاحية رخصة القيادة الصادرة لشخص عمره أقل من 21 سنة في عيد ميلاده الحادي والعشرين.","p":"صحيح. تنتهي صلاحيتها في عيد الميلاد الحادي والعشرين."},"ref":{"doc":"MT","page":8}},{"id":"mt-028","scope":"MT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Montana, when must you dim your high beams for a car coming toward you?","o":["When it is within 200 feet","When it is within 500 feet","When it is within 1,000 feet","When it is within 1 mile"],"h1":"Montana's distance is longer than in many states.","h2":"In Montana you must dim your high beams when an oncoming car is within 1,000 feet, and when you are within 500 feet behind another car.","p":"Right. Dim within 1,000 feet of an oncoming car."},"es":{"q":"En Montana, ¿cuándo debe bajar las luces altas por un carro que viene hacia usted?","o":["Cuando esté a menos de 200 pies","Cuando esté a menos de 500 pies","Cuando esté a menos de 1,000 pies","Cuando esté a menos de 1 milla"],"h1":"La distancia de Montana es más larga que en muchos estados.","h2":"En Montana usted debe bajar las luces altas cuando un carro que viene de frente esté a menos de 1,000 pies, y cuando usted esté a menos de 500 pies detrás de otro carro.","p":"Correcto. Baje las luces a menos de 1,000 pies de un carro que viene de frente."},"zh":{"q":"在 Montana，迎面来车时，你什么时候必须把远光灯（high beams）调暗？","o":["在 200 英尺以内时","在 500 英尺以内时","在 1,000 英尺以内时","在 1 英里以内时"],"h1":"Montana 的距离比很多州都长。","h2":"在 Montana，迎面来车在 1,000 英尺以内时，以及你在另一辆车后面 500 英尺以内时，你必须把远光灯调暗。","p":"对。迎面来车在 1,000 英尺以内时要调暗。"},"vi":{"q":"Ở Montana, khi có xe chạy ngược chiều tới, lúc nào bạn phải giảm đèn chiếu xa (high beams)?","o":["Khi xe đó ở trong vòng 200 feet","Khi xe đó ở trong vòng 500 feet","Khi xe đó ở trong vòng 1,000 feet","Khi xe đó ở trong vòng 1 dặm"],"h1":"Khoảng cách của Montana dài hơn ở nhiều tiểu bang.","h2":"Ở Montana, bạn phải giảm đèn chiếu xa khi xe ngược chiều ở trong vòng 1,000 feet, và khi bạn ở trong vòng 500 feet phía sau một xe khác.","p":"Đúng. Giảm đèn khi xe ngược chiều ở trong vòng 1,000 feet."},"tl":{"q":"Sa Montana, kailan mo dapat i-dim ang high beams mo para sa sasakyang paparating sa iyo?","o":["Kapag nasa loob ito ng 200 talampakan","Kapag nasa loob ito ng 500 talampakan","Kapag nasa loob ito ng 1,000 talampakan","Kapag nasa loob ito ng 1 milya"],"h1":"Mas mahaba ang layo sa Montana kaysa sa maraming estado.","h2":"Sa Montana, dapat mong i-dim ang high beams mo kapag ang paparating na sasakyan ay nasa loob ng 1,000 talampakan, at kapag ikaw ay nasa loob ng 500 talampakan sa likod ng ibang sasakyan.","p":"Tama. I-dim sa loob ng 1,000 talampakan ng paparating na sasakyan."},"ar":{"q":"في Montana، متى يجب أن تخفض الأضواء العالية (high beams) لسيارة قادمة نحوك؟","o":["عندما تكون ضمن 200 قدم","عندما تكون ضمن 500 قدم","عندما تكون ضمن 1,000 قدم","عندما تكون ضمن 1 ميل"],"h1":"المسافة في Montana أطول منها في كثير من الولايات.","h2":"في Montana يجب أن تخفض الأضواء العالية عندما تكون السيارة القادمة ضمن 1,000 قدم، وعندما تكون أنت ضمن 500 قدم خلف سيارة أخرى.","p":"صحيح. اخفض الأضواء ضمن 1,000 قدم من السيارة القادمة."},"ref":{"doc":"MT","page":14}},{"id":"mt-029","scope":"MT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Montana, what is the fine for a first conviction of driving without liability insurance?","o":["$25 to $50","$100 to $150","$1,000 to $2,000","$250 to $500"],"h1":"It is a few hundred dollars.","h2":"In Montana a first conviction for driving without liability insurance brings a fine of $250 to $500.","p":"Right. The fine is $250 to $500."},"es":{"q":"En Montana, ¿cuál es la multa por una primera condena por manejar sin seguro de responsabilidad civil?","o":["De $25 a $50","De $100 a $150","De $1,000 a $2,000","De $250 a $500"],"h1":"Son unos cientos de dólares.","h2":"En Montana una primera condena por manejar sin seguro de responsabilidad civil trae una multa de $250 a $500.","p":"Correcto. La multa es de $250 a $500."},"zh":{"q":"在 Montana，第一次因为没有责任保险（liability insurance）开车被定罪，罚款是多少？","o":["$25 到 $50","$100 到 $150","$1,000 到 $2,000","$250 到 $500"],"h1":"是几百美元。","h2":"在 Montana，第一次因为没有责任保险开车被定罪，罚款是 $250 到 $500。","p":"对。罚款是 $250 到 $500。"},"vi":{"q":"Ở Montana, tiền phạt cho lần bị kết tội đầu tiên vì lái xe không có bảo hiểm trách nhiệm (liability insurance) là bao nhiêu?","o":["$25 đến $50","$100 đến $150","$1,000 đến $2,000","$250 đến $500"],"h1":"Đó là vài trăm đô la.","h2":"Ở Montana, lần bị kết tội đầu tiên vì lái xe không có bảo hiểm trách nhiệm bị phạt từ $250 đến $500.","p":"Đúng. Tiền phạt là $250 đến $500."},"tl":{"q":"Sa Montana, magkano ang multa sa unang conviction dahil sa pagmamaneho nang walang liability insurance?","o":["$25 hanggang $50","$100 hanggang $150","$1,000 hanggang $2,000","$250 hanggang $500"],"h1":"Ilang daang dolyar ito.","h2":"Sa Montana, ang unang conviction dahil sa pagmamaneho nang walang liability insurance ay may multang $250 hanggang $500.","p":"Tama. Ang multa ay $250 hanggang $500."},"ar":{"q":"في Montana، ما الغرامة على أول إدانة بالقيادة دون تأمين المسؤولية (liability insurance)؟","o":["من $25 إلى $50","من $100 إلى $150","من $1,000 إلى $2,000","من $250 إلى $500"],"h1":"إنها بضع مئات من الدولارات.","h2":"في Montana تكون الغرامة على أول إدانة بالقيادة دون تأمين المسؤولية من $250 إلى $500.","p":"صحيح. الغرامة من $250 إلى $500."},"ref":{"doc":"MT","page":47}},{"id":"mt-030","scope":"MT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Montana, how close to a fire hydrant may you park?","o":["No closer than 10 feet","No closer than 5 feet","No closer than 15 feet","No closer than 30 feet"],"h1":"It is about the length of one car.","h2":"In Montana you may not park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a hydrant."},"es":{"q":"En Montana, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 5 pies","No más cerca de 15 pies","No más cerca de 30 pies"],"h1":"Es como el largo de un carro.","h2":"En Montana usted no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese por lo menos a 15 pies de un hidrante."},"zh":{"q":"在 Montana，你可以在离消防栓多近的地方停车？","o":["不能少于 10 英尺","不能少于 5 英尺","不能少于 15 英尺","不能少于 30 英尺"],"h1":"大约是一辆车的长度。","h2":"在 Montana，你不可以在消防栓 15 英尺以内停车。","p":"对。离消防栓至少 15 英尺。"},"vi":{"q":"Ở Montana, bạn được đậu xe gần trụ nước chữa cháy đến mức nào?","o":["Không gần hơn 10 feet","Không gần hơn 5 feet","Không gần hơn 15 feet","Không gần hơn 30 feet"],"h1":"Khoảng bằng chiều dài một chiếc xe.","h2":"Ở Montana, bạn không được đậu xe trong vòng 15 feet tính từ trụ nước chữa cháy.","p":"Đúng. Cách trụ nước chữa cháy ít nhất 15 feet."},"tl":{"q":"Sa Montana, gaano kalapit sa fire hydrant ka puwedeng pumarada?","o":["Hindi lalapit sa 10 talampakan","Hindi lalapit sa 5 talampakan","Hindi lalapit sa 15 talampakan","Hindi lalapit sa 30 talampakan"],"h1":"Halos kasinghaba ito ng isang kotse.","h2":"Sa Montana, hindi ka puwedeng pumarada sa loob ng 15 talampakan mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 15 talampakan mula sa hydrant."},"ar":{"q":"في Montana، ما أقرب مسافة من صنبور إطفاء الحريق يمكنك أن تركن عندها؟","o":["ليس أقرب من 10 أقدام","ليس أقرب من 5 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 30 قدمًا"],"h1":"إنها تقريبًا طول سيارة واحدة.","h2":"في Montana لا يجوز أن تركن ضمن 15 قدمًا من صنبور إطفاء الحريق.","p":"صحيح. ابتعد 15 قدمًا على الأقل عن صنبور الإطفاء."},"ref":{"doc":"MT","page":46}},{"id":"mt-031","scope":"MT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Montana, when a written crash report is required, how soon must it be filed?","o":["Within 24 hours","Within 10 days","Within 30 days","Within 6 months"],"h1":"It is less than two weeks.","h2":"In Montana a required written crash report must be filed within 10 days of the crash.","p":"Right. File it within 10 days."},"es":{"q":"En Montana, cuando se requiere un informe escrito de un choque, ¿en qué plazo se debe presentar?","o":["Dentro de 24 horas","Dentro de 10 días","Dentro de 30 días","Dentro de 6 meses"],"h1":"Es menos de dos semanas.","h2":"En Montana un informe escrito de choque que sea obligatorio se debe presentar dentro de los 10 días después del choque.","p":"Correcto. Preséntelo dentro de 10 días."},"zh":{"q":"在 Montana，如果需要书面车祸报告，必须在多久之内提交？","o":["24 小时之内","10 天之内","30 天之内","6 个月之内"],"h1":"不到两个星期。","h2":"在 Montana，需要的书面车祸报告必须在车祸后 10 天之内提交。","p":"对。在 10 天之内提交。"},"vi":{"q":"Ở Montana, khi cần có báo cáo tai nạn bằng văn bản, phải nộp báo cáo trong bao lâu?","o":["Trong vòng 24 giờ","Trong vòng 10 ngày","Trong vòng 30 ngày","Trong vòng 6 tháng"],"h1":"Ít hơn hai tuần.","h2":"Ở Montana, báo cáo tai nạn bằng văn bản bắt buộc phải được nộp trong vòng 10 ngày sau tai nạn.","p":"Đúng. Nộp trong vòng 10 ngày."},"tl":{"q":"Sa Montana, kapag kailangan ang nakasulat na ulat ng banggaan, gaano kabilis ito dapat isumite?","o":["Sa loob ng 24 na oras","Sa loob ng 10 araw","Sa loob ng 30 araw","Sa loob ng 6 na buwan"],"h1":"Kulang ito sa dalawang linggo.","h2":"Sa Montana, ang kinakailangang nakasulat na ulat ng banggaan ay dapat isumite sa loob ng 10 araw mula sa banggaan.","p":"Tama. Isumite ito sa loob ng 10 araw."},"ar":{"q":"في Montana، عندما يكون تقرير الحادث المكتوب مطلوبًا، خلال كم من الوقت يجب تقديمه؟","o":["خلال 24 ساعة","خلال 10 أيام","خلال 30 يومًا","خلال 6 أشهر"],"h1":"إنها أقل من أسبوعين.","h2":"في Montana يجب تقديم تقرير الحادث المكتوب المطلوب خلال 10 أيام من وقوع الحادث.","p":"صحيح. قدّمه خلال 10 أيام."},"ref":{"doc":"MT","page":80}},{"id":"mt-032","scope":"MT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Montana, you move to a new address. How soon must you tell the Motor Vehicle Division?","o":["Within 10 days","Within 30 days","Within 60 days","At your next renewal"],"h1":"It is less than two weeks.","h2":"Montana law says you must report your new address to the Motor Vehicle Division within 10 days of moving.","p":"Right. Report a new address within 10 days."},"es":{"q":"En Montana, usted se muda a una nueva dirección. ¿En cuánto tiempo debe avisar a la División de Vehículos Motorizados?","o":["En 10 días","En 30 días","En 60 días","En su próxima renovación"],"h1":"Es menos de dos semanas.","h2":"La ley de Montana dice que usted debe informar su nueva dirección a la División de Vehículos Motorizados dentro de los 10 días después de mudarse.","p":"Correcto. Informe su nueva dirección en 10 días."},"ref":{"doc":"MT","page":10}},{"id":"mt-033","scope":"MT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Montana, how early can you renew your driver license before it expires?","o":["Up to 1 month before","Up to 3 months before","Up to 6 months before","Up to 1 year before"],"h1":"Think of half a year.","h2":"In Montana you may renew your driver license up to 6 months before the date it expires.","p":"Right. You can renew up to 6 months early."},"es":{"q":"En Montana, ¿con cuánta anticipación puede renovar su licencia de conducir antes de que venza?","o":["Hasta 1 mes antes","Hasta 3 meses antes","Hasta 6 meses antes","Hasta 1 año antes"],"h1":"Piense en medio año.","h2":"En Montana usted puede renovar su licencia de conducir hasta 6 meses antes de la fecha en que vence.","p":"Correcto. Puede renovarla hasta 6 meses antes."},"ref":{"doc":"MT","page":9}},{"id":"mt-034","scope":"MT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Montana, a driver license is issued to a person age 75 or older. For how long is it valid at most?","o":["2 years","4 years","8 years","12 years"],"h1":"Older drivers renew more often than younger adults.","h2":"In Montana, a license issued to someone age 75 or older expires on their birthday 4 years or less after it is issued.","p":"Right. At 75 or older, a license lasts up to 4 years."},"es":{"q":"En Montana, se emite una licencia de conducir a una persona de 75 años o más. ¿Por cuánto tiempo es válida como máximo?","o":["2 años","4 años","8 años","12 años"],"h1":"Los conductores mayores renuevan más seguido que los adultos más jóvenes.","h2":"En Montana, una licencia emitida a una persona de 75 años o más vence en su cumpleaños 4 años o menos después de emitirse.","p":"Correcto. A los 75 años o más, la licencia dura hasta 4 años."},"ref":{"doc":"MT","page":8}},{"id":"mt-035","scope":"MT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Montana, a teen breaks a rule of the first-year restricted license for the first time. What is the penalty?","o":["A warning letter only","A $500 fine","Loss of the license for one year","20 to 60 hours of community service"],"h1":"The teen has to give some time to help others.","h2":"In Montana, a first violation of the first-year license rules brings 20 to 60 hours of community service; a second one brings a 6-month suspension.","p":"Right. The first time, it is 20 to 60 hours of community service."},"es":{"q":"En Montana, un adolescente rompe por primera vez una regla de la licencia restringida del primer año. ¿Cuál es la sanción?","o":["Solo una carta de advertencia","Una multa de $500","La pérdida de la licencia por un año","De 20 a 60 horas de servicio comunitario"],"h1":"El adolescente debe dar parte de su tiempo para ayudar a otros.","h2":"En Montana, la primera infracción de las reglas de la licencia del primer año trae de 20 a 60 horas de servicio comunitario; la segunda trae una suspensión de 6 meses.","p":"Correcto. La primera vez son de 20 a 60 horas de servicio comunitario."},"ref":{"doc":"MT","page":8}},{"id":"mt-036","scope":"MT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Montana, a passenger in your car is not wearing a seat belt. What is the fine for the driver?","o":["$20","$50","$100","$250"],"h1":"It is a small amount.","h2":"In Montana the driver is responsible for every rider being buckled, and the fine for breaking the seat belt law is $20.","p":"Right. The seat belt fine is $20, and the driver pays it."},"es":{"q":"En Montana, un pasajero de su auto no lleva puesto el cinturón de seguridad. ¿Cuál es la multa para el conductor?","o":["$20","$50","$100","$250"],"h1":"Es una cantidad pequeña.","h2":"En Montana el conductor es responsable de que todos lleven el cinturón abrochado, y la multa por no cumplir la ley del cinturón es de $20.","p":"Correcto. La multa del cinturón es de $20 y la paga el conductor."},"ref":{"doc":"MT","page":19}},{"id":"mt-037","scope":"MT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Montana, how must a child under 2 years old ride in a car?","o":["In a forward-facing booster seat","With an adult seat belt in the back seat","In a rear-facing child safety seat","On an adult's lap with a belt"],"h1":"The baby faces the back of the car.","h2":"Montana law says a child under 2 years old must ride in a rear-facing child safety seat that meets federal standards.","p":"Right. Under age 2, a child rides in a rear-facing seat."},"es":{"q":"En Montana, ¿cómo debe viajar en un auto un niño menor de 2 años?","o":["En un asiento elevado mirando hacia adelante","Con un cinturón de adulto en el asiento trasero","En un asiento de seguridad infantil mirando hacia atrás","En las piernas de un adulto con cinturón"],"h1":"El bebé mira hacia la parte de atrás del auto.","h2":"La ley de Montana dice que un niño menor de 2 años debe viajar en un asiento de seguridad infantil mirando hacia atrás que cumpla las normas federales.","p":"Correcto. Antes de los 2 años, el niño viaja en un asiento mirando hacia atrás."},"ref":{"doc":"MT","page":null}},{"id":"mt-038","scope":"MT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Montana, it is daytime, but snow or blowing dust makes it hard to see. When must your headlights be on?","o":["When you cannot see 1,000 feet ahead","When you cannot clearly see people and cars 500 feet ahead","When you cannot see 200 feet ahead","Only after sunset"],"h1":"It is a bit less than two city blocks.","h2":"Montana law says to use headlights at night and any time you cannot clearly see people and vehicles 500 feet ahead.","p":"Right. If you cannot see 500 feet ahead, turn on your headlights."},"es":{"q":"En Montana, es de día, pero la nieve o el polvo hacen difícil ver. ¿Cuándo debe tener encendidos los faros?","o":["Cuando no pueda ver 1,000 pies adelante","Cuando no pueda ver bien a personas y autos a 500 pies adelante","Cuando no pueda ver 200 pies adelante","Solo después de la puesta del sol"],"h1":"La distancia es de menos de dos cuadras de ciudad.","h2":"La ley de Montana dice que use los faros de noche y en cualquier momento en que no pueda ver bien a personas y vehículos a 500 pies adelante.","p":"Correcto. Si no puede ver a 500 pies, encienda los faros."},"ref":{"doc":"MT","page":14}},{"id":"mt-039","scope":"MT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Montana, you plan to turn on a rural road outside town. How far before the turn must you signal?","o":["At least 50 feet","At least 100 feet","At least 200 feet","At least 300 feet"],"h1":"It is three times the distance used in town.","h2":"In Montana you must signal at least 100 feet before a turn in town and at least 300 feet before a turn on rural roads.","p":"Right. On rural roads, signal at least 300 feet before you turn."},"es":{"q":"En Montana, usted va a girar en una carretera rural fuera del pueblo. ¿Con cuánta anticipación debe poner la señal?","o":["Al menos 50 pies antes","Al menos 100 pies antes","Al menos 200 pies antes","Al menos 300 pies antes"],"h1":"Es tres veces la distancia que se usa en el pueblo.","h2":"En Montana debe poner la señal al menos 100 pies antes de girar en el pueblo y al menos 300 pies antes de girar en carreteras rurales.","p":"Correcto. En carreteras rurales, ponga la señal al menos 300 pies antes de girar."},"ref":{"doc":"MT","page":37}},{"id":"mt-040","scope":"MT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Montana, the lights are flashing at a railroad crossing. Where must you stop?","o":["Right on the edge of the first rail","At least 5 feet from the nearest rail","At least 15 feet from the nearest rail","Only if you can see the train"],"h1":"Leave room in case the train or its load sticks out.","h2":"In Montana, when signals warn of a train, you must stop at least 15 feet from the nearest rail and wait until it is safe.","p":"Right. Stop at least 15 feet from the nearest rail."},"es":{"q":"En Montana, las luces destellan en un cruce de ferrocarril. ¿Dónde debe detenerse?","o":["Justo al borde del primer riel","Al menos a 5 pies del riel más cercano","Al menos a 15 pies del riel más cercano","Solo si puede ver el tren"],"h1":"Deje espacio por si el tren o su carga sobresale.","h2":"En Montana, cuando las señales avisan de un tren, debe detenerse al menos a 15 pies del riel más cercano y esperar hasta que sea seguro.","p":"Correcto. Deténgase al menos a 15 pies del riel más cercano."},"ref":{"doc":"MT","page":33}},{"id":"mt-041","scope":"MT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Montana, you get a traffic ticket in a work zone while highway workers are there. What happens to the fine?","o":["It is doubled","It stays the same","It is cut in half","It becomes a warning"],"h1":"Work zones protect people working near traffic.","h2":"In Montana, traffic fines in a work zone are doubled when highway workers are present.","p":"Right. Fines double in work zones when workers are present."},"es":{"q":"En Montana, a usted le ponen una multa de tránsito en una zona de obras mientras hay trabajadores de carreteras. ¿Qué pasa con la multa?","o":["Se duplica","Sigue igual","Se reduce a la mitad","Se convierte en una advertencia"],"h1":"Las zonas de obras protegen a personas que trabajan cerca del tráfico.","h2":"En Montana, las multas de tránsito en una zona de obras se duplican cuando hay trabajadores de carreteras presentes.","p":"Correcto. Las multas se duplican en zonas de obras con trabajadores."},"ref":{"doc":"MT","page":28}},{"id":"mt-042","scope":"MT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Montana, a funeral procession is moving past you. You are not part of it. When may you drive between its cars?","o":["Whenever there is a gap","When your light turns green","When you are late","Only if a police officer tells you to"],"h1":"Let the procession stay together.","h2":"In Montana you may not drive between the cars of a moving funeral procession unless a police officer allows it or you drive an emergency vehicle.","p":"Right. Do not cut into a funeral procession unless an officer tells you to."},"es":{"q":"En Montana, un cortejo fúnebre pasa frente a usted. Usted no forma parte de él. ¿Cuándo puede pasar entre sus autos?","o":["Siempre que haya un espacio","Cuando su semáforo cambie a verde","Cuando vaya tarde","Solo si un policía se lo indica"],"h1":"Deje que el cortejo siga unido.","h2":"En Montana no puede pasar entre los autos de un cortejo fúnebre en movimiento, a menos que un policía lo permita o usted maneje un vehículo de emergencia.","p":"Correcto. No se meta en un cortejo fúnebre a menos que un policía se lo indique."},"ref":{"doc":"MT","page":42}},{"id":"mt-043","scope":"MT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Montana, how close to a railroad crossing may you park?","o":["No closer than 15 feet","No closer than 50 feet","No closer than 25 feet","No closer than 100 feet"],"h1":"It is more than the distance for a fire hydrant.","h2":"In Montana you may not park within 50 feet of the nearest rail of a railroad crossing.","p":"Right. Park at least 50 feet from a railroad crossing."},"es":{"q":"En Montana, ¿qué tan cerca de un cruce de ferrocarril puede estacionarse?","o":["No más cerca de 15 pies","No más cerca de 50 pies","No más cerca de 25 pies","No más cerca de 100 pies"],"h1":"Es más que la distancia para un hidrante.","h2":"En Montana no puede estacionarse a menos de 50 pies del riel más cercano de un cruce de ferrocarril.","p":"Correcto. Estaciónese al menos a 50 pies de un cruce de ferrocarril."},"ref":{"doc":"MT","page":46}},{"id":"mt-044","scope":"MT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Montana, how close to a stop sign may you park?","o":["No closer than 10 feet","No closer than 20 feet","No closer than 30 feet","No closer than 50 feet"],"h1":"Drivers need to see the sign from far away.","h2":"In Montana you may not park within 30 feet of a stop sign, yield sign, or traffic signal at the side of the road.","p":"Right. Park at least 30 feet from a stop sign."},"es":{"q":"En Montana, ¿qué tan cerca de una señal de alto puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 20 pies","No más cerca de 30 pies","No más cerca de 50 pies"],"h1":"Los conductores necesitan ver la señal desde lejos.","h2":"En Montana no puede estacionarse a menos de 30 pies de una señal de alto, de ceda el paso o de un semáforo al lado de la vía.","p":"Correcto. Estaciónese al menos a 30 pies de una señal de alto."},"ref":{"doc":"MT","page":46}},{"id":"mt-045","scope":"MT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Montana, you are convicted of driving without liability insurance. How many points go on your driving record?","o":["2 points","3 points","10 points","5 points"],"h1":"It is more than a speeding ticket, which is 3.","h2":"In Montana, a conviction for driving without liability insurance adds 5 points to your driving record, on top of the fine.","p":"Right. No insurance means 5 points on your record."},"es":{"q":"En Montana, a usted lo declaran culpable de manejar sin seguro de responsabilidad civil. ¿Cuántos puntos se agregan a su historial de manejo?","o":["2 puntos","3 puntos","10 puntos","5 puntos"],"h1":"Es más que una multa por exceso de velocidad, que son 3.","h2":"En Montana, una condena por manejar sin seguro de responsabilidad civil agrega 5 puntos a su historial de manejo, además de la multa.","p":"Correcto. Manejar sin seguro son 5 puntos en su historial."},"ref":{"doc":"MT","page":47}},{"id":"mt-046","scope":"MT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Montana, during which months may you use studded tires?","o":["October 1 through May 31","All year long","November 1 through March 31","June 1 through September 30"],"h1":"Studs are for the snowy part of the year, which is long in Montana.","h2":"In Montana, studded tires may be used only from October 1 through May 31, because they damage roads.","p":"Right. Studded tires are allowed October 1 through May 31."},"es":{"q":"En Montana, ¿en qué meses puede usar llantas con clavos?","o":["Del 1 de octubre al 31 de mayo","Todo el año","Del 1 de noviembre al 31 de marzo","Del 1 de junio al 30 de septiembre"],"h1":"Los clavos son para la parte del año con nieve, que en Montana es larga.","h2":"En Montana, las llantas con clavos solo se pueden usar del 1 de octubre al 31 de mayo, porque dañan las carreteras.","p":"Correcto. Las llantas con clavos se permiten del 1 de octubre al 31 de mayo."},"ref":{"doc":"MT","page":60}},{"id":"mt-047","scope":"MT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Montana, a farm tractor or other farm vehicle is coming toward you on the highway. How must you slow down?","o":["Slow down 5 mph","Slow to half the posted speed limit","Stop until it passes","Keep your speed and honk"],"h1":"Cut the posted number in two.","h2":"Montana law says that when a farm vehicle comes toward you, you must slow to half the posted speed limit.","p":"Right. Slow to half the speed limit for an oncoming farm vehicle."},"es":{"q":"En Montana, un tractor u otro vehículo agrícola viene hacia usted en la carretera. ¿Cómo debe reducir la velocidad?","o":["Bajar 5 mph","Bajar a la mitad del límite de velocidad indicado","Detenerse hasta que pase","Mantener la velocidad y tocar la bocina"],"h1":"Divida entre dos el número del letrero.","h2":"La ley de Montana dice que cuando un vehículo agrícola viene hacia usted, debe bajar a la mitad del límite de velocidad indicado.","p":"Correcto. Baje a la mitad del límite ante un vehículo agrícola que viene de frente."},"ref":{"doc":"MT","page":null}},{"id":"mt-048","scope":"MT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Montana, a motorcycle may pass stopped or very slow cars in the same lane (\"lane filtering\"). How fast may the motorcycle go while doing this?","o":["No faster than 40 mph","Any speed that feels safe","No faster than 5 mph","No faster than 20 mph"],"h1":"It is twice the top speed of the cars being passed.","h2":"Montana law allows lane filtering only past vehicles going 10 mph or less, and the motorcycle may go no faster than 20 mph.","p":"Right. A lane-filtering motorcycle may go up to 20 mph."},"es":{"q":"En Montana, una motocicleta puede pasar entre autos detenidos o muy lentos en el mismo carril (\"lane filtering\"). ¿A qué velocidad puede ir la motocicleta al hacerlo?","o":["No más de 40 mph","A la velocidad que le parezca segura","No más de 5 mph","No más de 20 mph"],"h1":"Es el doble de la velocidad máxima de los autos que pasa.","h2":"La ley de Montana permite el lane filtering solo junto a vehículos que van a 10 mph o menos, y la motocicleta no puede ir a más de 20 mph.","p":"Correcto. Una motocicleta que hace lane filtering puede ir hasta 20 mph."},"ref":{"doc":"MT","page":null}},{"id":"mt-049","scope":"MT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Montana, you are lawfully asked to take a test for alcohol or drugs and you refuse for the first time. What happens to your license?","o":["Nothing, if you were not drunk","It is suspended for 30 days","It is suspended for 6 months","It is revoked for life"],"h1":"It is half a year.","h2":"In Montana, a first refusal of a lawful alcohol or drug test suspends your license for 6 months, with no restricted license.","p":"Right. A first refusal means a 6-month suspension."},"es":{"q":"En Montana, le piden legalmente una prueba de alcohol o drogas y usted se niega por primera vez. ¿Qué pasa con su licencia?","o":["Nada, si no estaba ebrio","La suspenden por 30 días","La suspenden por 6 meses","Se la quitan de por vida"],"h1":"Es medio año.","h2":"En Montana, la primera negativa a una prueba legal de alcohol o drogas suspende su licencia por 6 meses, sin licencia restringida.","p":"Correcto. La primera negativa trae una suspensión de 6 meses."},"ref":{"doc":"MT","page":null}},{"id":"mt-050","scope":"MT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Montana, a driver becomes a \"habitual traffic offender\" after collecting how many points?","o":["30 points within 3 years","12 points within 1 year","20 points within 2 years","50 points within 5 years"],"h1":"Think of ten points for each year.","h2":"In Montana, a driver who gets 30 or more conviction points within 3 years is a habitual traffic offender.","p":"Right. 30 points in 3 years makes a habitual traffic offender."},"es":{"q":"En Montana, ¿después de acumular cuántos puntos un conductor se considera \"infractor habitual de tránsito\"?","o":["30 puntos en 3 años","12 puntos en 1 año","20 puntos en 2 años","50 puntos en 5 años"],"h1":"Piense en diez puntos por cada año.","h2":"En Montana, un conductor que acumula 30 puntos o más por condenas en 3 años es un infractor habitual de tránsito.","p":"Correcto. 30 puntos en 3 años hacen a un infractor habitual."},"ref":{"doc":"MT","page":null}},{"id":"mt-051","scope":"MT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Montana, you have a crash where no one is hurt. You must tell the police right away if the damage looks like it is at least how much?","o":["$250","$1,000","$2,500","$5,000"],"h1":"It is a four-digit amount.","h2":"Montana law says to notify the police right away after a crash with injury, death, or damage that appears to be $1,000 or more.","p":"Right. Damage of $1,000 or more must be reported right away."},"es":{"q":"En Montana, usted tiene un choque sin heridos. ¿A partir de qué cantidad de daño aparente debe avisar a la policía de inmediato?","o":["$250","$1,000","$2,500","$5,000"],"h1":"Es una cantidad de cuatro cifras.","h2":"La ley de Montana dice que avise a la policía de inmediato después de un choque con heridos, muertos o daños que parezcan ser de $1,000 o más.","p":"Correcto. Los daños de $1,000 o más se deben reportar de inmediato."},"ref":{"doc":"MT","page":null}},{"id":"nc-001","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, what is the youngest age to get a limited learner permit (Level 1)?","o":["14 years old","15 years old","16 years old","18 years old"],"h1":"It is one year before the age for a Level 2 license.","h2":"In North Carolina you can get a Level 1 limited learner permit at 15, after a driver education course.","p":"Right. The Level 1 permit starts at 15."},"es":{"q":"En Carolina del Norte, ¿cuál es la edad mínima para obtener el permiso limitado de aprendiz (Nivel 1)?","o":["14 años","15 años","16 años","18 años"],"h1":"Es un año antes de la edad para la licencia de Nivel 2.","h2":"En Carolina del Norte usted puede obtener el permiso limitado de aprendiz de Nivel 1 a los 15 años, después de un curso de educación vial.","p":"Correcto. El permiso de Nivel 1 empieza a los 15."},"zh":{"q":"在 North Carolina，最小几岁可以拿到有限制的学习驾照（limited learner permit，Level 1）？","o":["14 岁","15 岁","16 岁","18 岁"],"h1":"它比拿 Level 2 驾照的年龄早一年。","h2":"在 North Carolina，你上完驾驶教育课程以后，15 岁就可以拿到 Level 1 有限制的学习驾照。","p":"对。Level 1 学习驾照从 15 岁开始。"},"vi":{"q":"Ở North Carolina, tuổi nhỏ nhất để lấy giấy phép tập lái có giới hạn Cấp 1 (Level 1 limited learner permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","18 tuổi"],"h1":"Đó là một năm trước độ tuổi để lấy bằng Cấp 2.","h2":"Ở North Carolina, bạn có thể lấy giấy phép tập lái có giới hạn Cấp 1 khi 15 tuổi, sau khi học xong một khóa giáo dục lái xe.","p":"Đúng. Giấy phép Cấp 1 bắt đầu từ 15 tuổi."},"tl":{"q":"Sa North Carolina, ano ang pinakabatang edad para makakuha ng Level 1 limited learner permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","18 taong gulang"],"h1":"Isang taon ito bago ang edad para sa Level 2 na lisensya.","h2":"Sa North Carolina, puwede kang makakuha ng Level 1 limited learner permit sa edad na 15, pagkatapos ng isang kurso sa driver education.","p":"Tama. Nagsisimula ang Level 1 permit sa edad na 15."},"ar":{"q":"في North Carolina، ما أصغر عمر للحصول على تصريح تعلّم القيادة المحدود من المستوى 1 (Level 1 limited learner permit)؟","o":["14 سنة","15 سنة","16 سنة","18 سنة"],"h1":"هو قبل سنة واحدة من عمر رخصة المستوى 2.","h2":"في North Carolina يمكنك الحصول على تصريح تعلّم القيادة المحدود من المستوى 1 في عمر 15 سنة، بعد إكمال دورة لتعليم القيادة.","p":"صحيح. يبدأ تصريح المستوى 1 في عمر 15 سنة."},"ref":{"doc":"NC","page":12}},{"id":"nc-002","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, how many levels does the graduated license for teens have?","o":["Three","Two","Four","Five"],"h1":"Learner permit, limited provisional, then full provisional.","h2":"North Carolina's teen license has three levels: a limited learner permit, a limited provisional license and a full provisional license.","p":"Right. There are three levels."},"es":{"q":"En Carolina del Norte, ¿cuántos niveles tiene la licencia graduada para adolescentes?","o":["Tres","Dos","Cuatro","Cinco"],"h1":"Permiso de aprendiz, provisional limitada y luego provisional completa.","h2":"La licencia para adolescentes en Carolina del Norte tiene tres niveles: permiso limitado de aprendiz, licencia provisional limitada y licencia provisional completa.","p":"Correcto. Son tres niveles."},"zh":{"q":"在 North Carolina，青少年的分级驾照一共有几级？","o":["三级","两级","四级","五级"],"h1":"学习驾照、有限制的临时驾照，然后是完整的临时驾照。","h2":"North Carolina 的青少年驾照有三级：有限制的学习驾照、有限制的临时驾照和完整的临时驾照。","p":"对。一共有三级。"},"vi":{"q":"Ở North Carolina, bằng lái theo từng giai đoạn cho thanh thiếu niên có bao nhiêu cấp?","o":["Ba","Hai","Bốn","Năm"],"h1":"Giấy phép tập lái, bằng tạm thời có giới hạn, rồi bằng tạm thời đầy đủ.","h2":"Bằng lái cho thanh thiếu niên ở North Carolina có ba cấp: giấy phép tập lái có giới hạn, bằng tạm thời có giới hạn (limited provisional license) và bằng tạm thời đầy đủ (full provisional license).","p":"Đúng. Có ba cấp."},"tl":{"q":"Sa North Carolina, ilang level mayroon ang graduated license para sa mga kabataan?","o":["Tatlo","Dalawa","Apat","Lima"],"h1":"Learner permit, limited provisional, at pagkatapos ay full provisional.","h2":"May tatlong level ang lisensya para sa kabataan sa North Carolina: limited learner permit, limited provisional license at full provisional license.","p":"Tama. May tatlong level."},"ar":{"q":"في North Carolina، كم مستوى في الرخصة المتدرّجة للمراهقين؟","o":["ثلاثة","اثنان","أربعة","خمسة"],"h1":"تصريح التعلّم، ثم الرخصة المؤقتة المحدودة، ثم الرخصة المؤقتة الكاملة.","h2":"رخصة المراهقين في North Carolina لها ثلاثة مستويات: تصريح تعلّم محدود، ورخصة مؤقتة محدودة (limited provisional license)، ورخصة مؤقتة كاملة (full provisional license).","p":"صحيح. هناك ثلاثة مستويات."},"ref":{"doc":"NC","page":12}},{"id":"nc-003","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, during the first six months of a Level 1 permit, when may the permit holder drive?","o":["Any time, day or night","Only on weekends","Only between 5 a.m. and 9 p.m., with a supervising driver","Only between noon and 6 p.m."],"h1":"The window starts early in the morning and ends in the evening.","h2":"During the first six months of a North Carolina Level 1 permit, you may drive only between 5 a.m. and 9 p.m., and always with a supervising driver.","p":"Right. 5 a.m. to 9 p.m., with a supervisor."},"es":{"q":"En Carolina del Norte, durante los primeros seis meses del permiso de Nivel 1, ¿cuándo puede manejar el titular?","o":["A cualquier hora, de día o de noche","Solo los fines de semana","Solo entre las 5 a.m. y las 9 p.m., con un conductor supervisor","Solo entre el mediodía y las 6 p.m."],"h1":"El horario empieza temprano en la mañana y termina en la noche.","h2":"Durante los primeros seis meses del permiso de Nivel 1 en Carolina del Norte, usted solo puede manejar entre las 5 a.m. y las 9 p.m., y siempre con un conductor supervisor.","p":"Correcto. De 5 a.m. a 9 p.m., con un supervisor."},"zh":{"q":"在 North Carolina，持 Level 1 学习驾照的前六个月，什么时候可以开车？","o":["白天晚上任何时间","只在周末","只在早上 5 点到晚上 9 点之间，而且要有陪同的司机","只在中午到晚上 6 点之间"],"h1":"可以开车的时间从清早开始，到傍晚结束。","h2":"持 North Carolina Level 1 学习驾照的前六个月，你只能在早上 5 点到晚上 9 点之间开车，而且一直要有陪同的司机。","p":"对。早上 5 点到晚上 9 点，要有陪同的人。"},"vi":{"q":"Ở North Carolina, trong sáu tháng đầu của giấy phép Cấp 1, người có giấy phép được lái xe khi nào?","o":["Bất cứ lúc nào, ngày hay đêm","Chỉ vào cuối tuần","Chỉ từ 5 giờ sáng đến 9 giờ tối, có người lái xe giám sát đi cùng","Chỉ từ 12 giờ trưa đến 6 giờ chiều"],"h1":"Khoảng thời gian này bắt đầu từ sáng sớm và kết thúc vào buổi tối.","h2":"Trong sáu tháng đầu của giấy phép Cấp 1 ở North Carolina, bạn chỉ được lái xe từ 5 giờ sáng đến 9 giờ tối, và luôn phải có người lái xe giám sát đi cùng.","p":"Đúng. Từ 5 giờ sáng đến 9 giờ tối, có người giám sát."},"tl":{"q":"Sa North Carolina, sa unang anim na buwan ng Level 1 permit, kailan puwedeng magmaneho ang may hawak ng permit?","o":["Kahit anong oras, araw man o gabi","Tuwing weekend lang","Mula 5 a.m. hanggang 9 p.m. lang, kasama ang isang supervising driver","Mula tanghali hanggang 6 p.m. lang"],"h1":"Nagsisimula ang oras nang maaga sa umaga at natatapos sa gabi.","h2":"Sa unang anim na buwan ng Level 1 permit sa North Carolina, puwede kang magmaneho mula 5 a.m. hanggang 9 p.m. lang, at palaging may kasamang supervising driver.","p":"Tama. 5 a.m. hanggang 9 p.m., may kasamang supervisor."},"ar":{"q":"في North Carolina، خلال الأشهر الستة الأولى من تصريح المستوى 1، متى يمكن لحامل التصريح أن يقود؟","o":["في أي وقت، نهارًا أو ليلًا","في عطلة نهاية الأسبوع فقط","من 5 صباحًا إلى 9 مساءً فقط، مع سائق مشرف","من الظهر إلى 6 مساءً فقط"],"h1":"تبدأ الفترة في الصباح الباكر وتنتهي في المساء.","h2":"خلال الأشهر الستة الأولى من تصريح المستوى 1 في North Carolina، يمكنك القيادة فقط من 5 صباحًا إلى 9 مساءً، ودائمًا مع سائق مشرف.","p":"صحيح. من 5 صباحًا إلى 9 مساءً، مع مشرف."},"ref":{"doc":"NC","page":12}},{"id":"nc-004","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, after the first six months of a Level 1 permit, when may the permit holder drive?","o":["Only in daylight","Alone at any time","Never at night","At any time, but only with a supervising driver"],"h1":"The hours open up, but one thing does not change.","h2":"After the first six months, a North Carolina Level 1 permit holder may drive at any time, but still only with a supervising driver.","p":"Right. Any time, but always with a supervisor."},"es":{"q":"En Carolina del Norte, después de los primeros seis meses del permiso de Nivel 1, ¿cuándo puede manejar el titular?","o":["Solo de día","Solo, a cualquier hora","Nunca de noche","A cualquier hora, pero solo con un conductor supervisor"],"h1":"El horario se abre, pero hay algo que no cambia.","h2":"Después de los primeros seis meses, el titular de un permiso de Nivel 1 en Carolina del Norte puede manejar a cualquier hora, pero siempre con un conductor supervisor.","p":"Correcto. A cualquier hora, pero siempre con un supervisor."},"zh":{"q":"在 North Carolina，持 Level 1 学习驾照满六个月以后，什么时候可以开车？","o":["只在白天","任何时间都可以单独开","晚上永远不行","任何时间，但只能和陪同的司机一起"],"h1":"时间放开了，但有一件事不变。","h2":"前六个月以后，North Carolina 持 Level 1 学习驾照的人可以在任何时间开车，但仍然只能和陪同的司机一起。","p":"对。任何时间，但一直要有陪同的人。"},"vi":{"q":"Ở North Carolina, sau sáu tháng đầu của giấy phép Cấp 1, người có giấy phép được lái xe khi nào?","o":["Chỉ vào ban ngày","Lái một mình bất cứ lúc nào","Không bao giờ được lái vào ban đêm","Bất cứ lúc nào, nhưng chỉ khi có người lái xe giám sát"],"h1":"Giờ lái được mở rộng, nhưng có một điều không thay đổi.","h2":"Sau sáu tháng đầu, người có giấy phép Cấp 1 ở North Carolina được lái xe bất cứ lúc nào, nhưng vẫn chỉ khi có người lái xe giám sát.","p":"Đúng. Bất cứ lúc nào, nhưng luôn có người giám sát."},"tl":{"q":"Sa North Carolina, pagkatapos ng unang anim na buwan ng Level 1 permit, kailan puwedeng magmaneho ang may hawak ng permit?","o":["Kapag may liwanag ng araw lang","Mag-isa, kahit anong oras","Hindi kailanman sa gabi","Kahit anong oras, pero kasama lang ang isang supervising driver"],"h1":"Lumuluwag ang oras, pero may isang bagay na hindi nagbabago.","h2":"Pagkatapos ng unang anim na buwan, puwedeng magmaneho kahit anong oras ang may hawak ng Level 1 permit sa North Carolina, pero kasama pa rin ang isang supervising driver.","p":"Tama. Kahit anong oras, pero palaging may supervisor."},"ar":{"q":"في North Carolina، بعد الأشهر الستة الأولى من تصريح المستوى 1، متى يمكن لحامل التصريح أن يقود؟","o":["في ضوء النهار فقط","وحده في أي وقت","لا يقود في الليل أبدًا","في أي وقت، لكن مع سائق مشرف فقط"],"h1":"تصبح الساعات مفتوحة، لكن شيئًا واحدًا لا يتغيّر.","h2":"بعد الأشهر الستة الأولى، يمكن لحامل تصريح المستوى 1 في North Carolina أن يقود في أي وقت، لكن مع سائق مشرف فقط كما كان من قبل.","p":"صحيح. في أي وقت، لكن دائمًا مع مشرف."},"ref":{"doc":"NC","page":12}},{"id":"nc-005","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, how long must a supervising driver have been licensed?","o":["At least one year","At least five years","At least ten years","At least 20 years"],"h1":"It is more than a few years, but less than ten.","h2":"In North Carolina a supervising driver must be a licensed driver who has held a license for at least five years.","p":"Right. Licensed for at least five years."},"es":{"q":"En Carolina del Norte, ¿cuánto tiempo debe tener licencia un conductor supervisor?","o":["Por lo menos un año","Por lo menos cinco años","Por lo menos diez años","Por lo menos 20 años"],"h1":"Son más de unos pocos años, pero menos de diez.","h2":"En Carolina del Norte el conductor supervisor debe tener licencia de manejo desde hace por lo menos cinco años.","p":"Correcto. Con licencia desde hace por lo menos cinco años."},"zh":{"q":"在 North Carolina，陪同的司机必须持有驾照多久？","o":["至少一年","至少五年","至少十年","至少 20 年"],"h1":"比几年多，但少于十年。","h2":"在 North Carolina，陪同的司机必须是持有驾照至少五年的有驾照司机。","p":"对。持有驾照至少五年。"},"vi":{"q":"Ở North Carolina, người lái xe giám sát phải có bằng lái ít nhất bao lâu?","o":["Ít nhất một năm","Ít nhất năm năm","Ít nhất mười năm","Ít nhất 20 năm"],"h1":"Hơn vài năm, nhưng ít hơn mười năm.","h2":"Ở North Carolina, người lái xe giám sát phải là người có bằng lái và đã có bằng ít nhất năm năm.","p":"Đúng. Có bằng lái ít nhất năm năm."},"tl":{"q":"Sa North Carolina, gaano na katagal dapat may lisensya ang isang supervising driver?","o":["Hindi bababa sa isang taon","Hindi bababa sa limang taon","Hindi bababa sa sampung taon","Hindi bababa sa 20 taon"],"h1":"Higit ito sa ilang taon, pero kulang sa sampu.","h2":"Sa North Carolina, ang supervising driver ay dapat may lisensya at may hawak na lisensya nang hindi bababa sa limang taon.","p":"Tama. May lisensya nang hindi bababa sa limang taon."},"ar":{"q":"في North Carolina، منذ كم سنة على الأقل يجب أن يحمل السائق المشرف رخصة قيادة؟","o":["سنة واحدة على الأقل","خمس سنوات على الأقل","عشر سنوات على الأقل","20 سنة على الأقل"],"h1":"أكثر من بضع سنوات، لكن أقل من عشر.","h2":"في North Carolina يجب أن يكون السائق المشرف سائقًا مرخّصًا يحمل رخصة قيادة منذ خمس سنوات على الأقل.","p":"صحيح. رخصة منذ خمس سنوات على الأقل."},"ref":{"doc":"NC","page":12}},{"id":"nc-006","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, where must the supervising driver sit while a Level 1 permit holder drives?","o":["In the front seat, beside the driver","In the back seat","Anywhere in the car","In another car nearby"],"h1":"The supervisor must be close enough to help right away.","h2":"In North Carolina the supervising driver must sit in the front seat beside the permit holder whenever the car is moving.","p":"Right. The supervisor sits beside you in front."},"es":{"q":"En Carolina del Norte, ¿dónde debe sentarse el conductor supervisor mientras maneja el titular de un permiso de Nivel 1?","o":["En el asiento delantero, al lado del conductor","En el asiento de atrás","En cualquier lugar del carro","En otro carro cercano"],"h1":"El supervisor debe estar lo bastante cerca para ayudar de inmediato.","h2":"En Carolina del Norte el conductor supervisor debe sentarse en el asiento delantero, al lado del titular del permiso, siempre que el carro esté en movimiento.","p":"Correcto. El supervisor va a su lado, adelante."},"zh":{"q":"在 North Carolina，持 Level 1 学习驾照的人开车时，陪同的司机必须坐在哪里？","o":["前排，在司机旁边","后排","车里任何地方","附近的另一辆车里"],"h1":"陪同的人必须离得够近，能马上帮忙。","h2":"在 North Carolina，只要车在开，陪同的司机就必须坐在前排，在持学习驾照的人旁边。","p":"对。陪同的人坐在前排，在你旁边。"},"vi":{"q":"Ở North Carolina, người lái xe giám sát phải ngồi ở đâu khi người có giấy phép Cấp 1 lái xe?","o":["Ở ghế trước, bên cạnh người lái","Ở ghế sau","Ở bất cứ chỗ nào trong xe","Trong một xe khác ở gần đó"],"h1":"Người giám sát phải ngồi đủ gần để giúp ngay lập tức.","h2":"Ở North Carolina, người lái xe giám sát phải ngồi ở ghế trước, bên cạnh người có giấy phép, bất cứ khi nào xe đang chạy.","p":"Đúng. Người giám sát ngồi bên cạnh bạn ở ghế trước."},"tl":{"q":"Sa North Carolina, saan dapat umupo ang supervising driver habang nagmamaneho ang may hawak ng Level 1 permit?","o":["Sa harapang upuan, katabi ng nagmamaneho","Sa likurang upuan","Kahit saan sa kotse","Sa ibang kotse na malapit"],"h1":"Dapat sapat na malapit ang supervisor para makatulong agad.","h2":"Sa North Carolina, dapat umupo ang supervising driver sa harapang upuan, katabi ng may hawak ng permit, tuwing umaandar ang kotse.","p":"Tama. Katabi mo sa harap ang supervisor."},"ar":{"q":"في North Carolina، أين يجب أن يجلس السائق المشرف بينما يقود حامل تصريح المستوى 1؟","o":["في المقعد الأمامي، بجانب السائق","في المقعد الخلفي","في أي مكان في السيارة","في سيارة أخرى قريبة"],"h1":"يجب أن يكون المشرف قريبًا بما يكفي ليساعد فورًا.","h2":"في North Carolina يجب أن يجلس السائق المشرف في المقعد الأمامي بجانب حامل التصريح كلما كانت السيارة تتحرك.","p":"صحيح. المشرف يجلس بجانبك في الأمام."},"ref":{"doc":"NC","page":null}},{"id":"nc-007","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, what is the youngest age for a Level 2 limited provisional license?","o":["15 years old","15 and a half","16 years old","18 years old"],"h1":"It is one year after the youngest age for a Level 1 permit.","h2":"In North Carolina the youngest age for a Level 2 limited provisional license is 16.","p":"Right. Level 2 starts at 16."},"es":{"q":"En Carolina del Norte, ¿cuál es la edad mínima para la licencia provisional limitada de Nivel 2?","o":["15 años","15 años y medio","16 años","18 años"],"h1":"Es un año después de la edad mínima para el permiso de Nivel 1.","h2":"En Carolina del Norte la edad mínima para la licencia provisional limitada de Nivel 2 es de 16 años.","p":"Correcto. El Nivel 2 empieza a los 16."},"zh":{"q":"在 North Carolina，最小几岁可以拿到 Level 2 有限制的临时驾照？","o":["15 岁","15 岁半","16 岁","18 岁"],"h1":"它比拿 Level 1 学习驾照的最小年龄晚一年。","h2":"在 North Carolina，拿 Level 2 有限制的临时驾照的最小年龄是 16 岁。","p":"对。Level 2 从 16 岁开始。"},"vi":{"q":"Ở North Carolina, tuổi nhỏ nhất để lấy bằng tạm thời có giới hạn Cấp 2 (Level 2 limited provisional license) là bao nhiêu?","o":["15 tuổi","15 tuổi rưỡi","16 tuổi","18 tuổi"],"h1":"Đó là một năm sau tuổi nhỏ nhất để lấy giấy phép Cấp 1.","h2":"Ở North Carolina, tuổi nhỏ nhất để lấy bằng tạm thời có giới hạn Cấp 2 là 16 tuổi.","p":"Đúng. Cấp 2 bắt đầu từ 16 tuổi."},"tl":{"q":"Sa North Carolina, ano ang pinakabatang edad para sa Level 2 limited provisional license?","o":["15 taong gulang","15 at kalahati","16 taong gulang","18 taong gulang"],"h1":"Isang taon ito pagkatapos ng pinakabatang edad para sa Level 1 permit.","h2":"Sa North Carolina, ang pinakabatang edad para sa Level 2 limited provisional license ay 16.","p":"Tama. Nagsisimula ang Level 2 sa edad na 16."},"ar":{"q":"في North Carolina، ما أصغر عمر للحصول على الرخصة المؤقتة المحدودة من المستوى 2 (Level 2 limited provisional license)؟","o":["15 سنة","15 سنة ونصف","16 سنة","18 سنة"],"h1":"هو بعد سنة واحدة من أصغر عمر لتصريح المستوى 1.","h2":"في North Carolina أصغر عمر للرخصة المؤقتة المحدودة من المستوى 2 هو 16 سنة.","p":"صحيح. يبدأ المستوى 2 في عمر 16 سنة."},"ref":{"doc":"NC","page":13}},{"id":"nc-008","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, during which hours may a Level 2 driver drive without a supervising driver?","o":["From 5 a.m. to 9 p.m.","From 6 a.m. to midnight","From 7 a.m. to 7 p.m.","Any hour of the day"],"h1":"These are the same hours as the first months of the Level 1 permit.","h2":"A North Carolina Level 2 driver may drive alone from 5 a.m. to 9 p.m.; from 9 p.m. to 5 a.m. a supervising driver is needed, with a few exceptions.","p":"Right. Alone from 5 a.m. to 9 p.m."},"es":{"q":"En Carolina del Norte, ¿en qué horario puede manejar un conductor de Nivel 2 sin un conductor supervisor?","o":["De 5 a.m. a 9 p.m.","De 6 a.m. a medianoche","De 7 a.m. a 7 p.m.","A cualquier hora del día"],"h1":"Es el mismo horario de los primeros meses del permiso de Nivel 1.","h2":"Un conductor de Nivel 2 en Carolina del Norte puede manejar solo de 5 a.m. a 9 p.m.; de 9 p.m. a 5 a.m. necesita un conductor supervisor, con algunas excepciones.","p":"Correcto. Solo, de 5 a.m. a 9 p.m."},"zh":{"q":"在 North Carolina，Level 2 司机在哪段时间可以没有陪同的司机开车？","o":["早上 5 点到晚上 9 点","早上 6 点到午夜","早上 7 点到晚上 7 点","一天中任何时间"],"h1":"这和 Level 1 学习驾照前几个月的时间一样。","h2":"North Carolina 的 Level 2 司机可以在早上 5 点到晚上 9 点单独开车；从晚上 9 点到早上 5 点需要有陪同的司机，只有几个例外。","p":"对。早上 5 点到晚上 9 点可以单独开车。"},"vi":{"q":"Ở North Carolina, người lái Cấp 2 được lái xe mà không cần người giám sát trong những giờ nào?","o":["Từ 5 giờ sáng đến 9 giờ tối","Từ 6 giờ sáng đến nửa đêm","Từ 7 giờ sáng đến 7 giờ tối","Bất cứ giờ nào trong ngày"],"h1":"Đây là cùng khung giờ với những tháng đầu của giấy phép Cấp 1.","h2":"Người lái Cấp 2 ở North Carolina được lái một mình từ 5 giờ sáng đến 9 giờ tối; từ 9 giờ tối đến 5 giờ sáng thì cần có người lái xe giám sát, trừ một vài trường hợp ngoại lệ.","p":"Đúng. Lái một mình từ 5 giờ sáng đến 9 giờ tối."},"tl":{"q":"Sa North Carolina, sa anong mga oras puwedeng magmaneho ang Level 2 driver nang walang supervising driver?","o":["Mula 5 a.m. hanggang 9 p.m.","Mula 6 a.m. hanggang hatinggabi","Mula 7 a.m. hanggang 7 p.m.","Kahit anong oras sa araw"],"h1":"Pareho ito sa mga oras ng mga unang buwan ng Level 1 permit.","h2":"Puwedeng magmaneho nang mag-isa ang Level 2 driver sa North Carolina mula 5 a.m. hanggang 9 p.m.; mula 9 p.m. hanggang 5 a.m., kailangan ng supervising driver, maliban sa ilang eksepsiyon.","p":"Tama. Mag-isa mula 5 a.m. hanggang 9 p.m."},"ar":{"q":"في North Carolina، في أي ساعات يمكن لسائق المستوى 2 أن يقود بدون سائق مشرف؟","o":["من 5 صباحًا إلى 9 مساءً","من 6 صباحًا إلى منتصف الليل","من 7 صباحًا إلى 7 مساءً","في أي ساعة من اليوم"],"h1":"هي نفس ساعات الأشهر الأولى من تصريح المستوى 1.","h2":"يمكن لسائق المستوى 2 في North Carolina أن يقود وحده من 5 صباحًا إلى 9 مساءً؛ ومن 9 مساءً إلى 5 صباحًا يلزم وجود سائق مشرف، مع بعض الاستثناءات.","p":"صحيح. وحده من 5 صباحًا إلى 9 مساءً."},"ref":{"doc":"NC","page":13}},{"id":"nc-009","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, which trip may a Level 2 driver make alone after 9 p.m.?","o":["Going to a friend's party","Driving around for fun","Going to the movies","Driving directly to or from work"],"h1":"It is a trip with a serious, regular purpose.","h2":"A North Carolina Level 2 driver may drive alone after 9 p.m. when driving directly to or from work; volunteer fire, rescue or EMS trips are also allowed.","p":"Right. Driving straight to or from work is allowed."},"es":{"q":"En Carolina del Norte, ¿qué viaje puede hacer solo un conductor de Nivel 2 después de las 9 p.m.?","o":["Ir a la fiesta de un amigo","Pasear por diversión","Ir al cine","Manejar directo al trabajo o de regreso del trabajo"],"h1":"Es un viaje con un propósito serio y regular.","h2":"Un conductor de Nivel 2 en Carolina del Norte puede manejar solo después de las 9 p.m. cuando va directo al trabajo o regresa de él; también se permiten viajes como voluntario de bomberos, rescate o emergencias médicas.","p":"Correcto. Ir directo al trabajo o regresar está permitido."},"zh":{"q":"在 North Carolina，Level 2 司机晚上 9 点以后可以单独开车去做哪件事？","o":["去朋友的派对","开车出去玩","去看电影","直接去上班或下班"],"h1":"这是一个有正经、固定目的的路程。","h2":"North Carolina 的 Level 2 司机在晚上 9 点以后直接去上班或下班时可以单独开车；志愿消防、救援或急救（EMS）的路程也可以。","p":"对。直接去上班或下班是可以的。"},"vi":{"q":"Ở North Carolina, người lái Cấp 2 được lái một mình sau 9 giờ tối cho chuyến đi nào?","o":["Đi dự tiệc của bạn bè","Lái xe đi chơi cho vui","Đi xem phim","Lái xe thẳng đến nơi làm việc hoặc từ nơi làm việc về"],"h1":"Đó là một chuyến đi có mục đích nghiêm túc và thường xuyên.","h2":"Người lái Cấp 2 ở North Carolina được lái một mình sau 9 giờ tối khi lái xe thẳng đến hoặc từ nơi làm việc; các chuyến đi làm tình nguyện cứu hỏa, cứu hộ hoặc cấp cứu (EMS) cũng được phép.","p":"Đúng. Được lái thẳng đến hoặc từ nơi làm việc."},"tl":{"q":"Sa North Carolina, anong biyahe ang puwedeng gawin nang mag-isa ng Level 2 driver pagkalipas ng 9 p.m.?","o":["Pagpunta sa party ng kaibigan","Pagmamaneho-maneho para magsaya","Pagpunta sa sinehan","Diretsong pagmamaneho papunta o pauwi mula sa trabaho"],"h1":"Ito ay biyaheng may seryoso at regular na layunin.","h2":"Puwedeng magmaneho nang mag-isa ang Level 2 driver sa North Carolina pagkalipas ng 9 p.m. kapag diretsong papunta o pauwi mula sa trabaho; pinapayagan din ang mga biyahe para sa volunteer fire, rescue o EMS.","p":"Tama. Pinapayagan ang diretsong biyahe papunta o pauwi mula sa trabaho."},"ar":{"q":"في North Carolina، أي رحلة يمكن لسائق المستوى 2 أن يقوم بها وحده بعد 9 مساءً؟","o":["الذهاب إلى حفلة صديق","القيادة للتسلية","الذهاب إلى السينما","القيادة مباشرة إلى العمل أو من العمل"],"h1":"هي رحلة لها هدف جاد ومنتظم.","h2":"يمكن لسائق المستوى 2 في North Carolina أن يقود وحده بعد 9 مساءً عندما يقود مباشرة إلى العمل أو منه؛ ورحلات التطوّع في الإطفاء أو الإنقاذ أو الإسعاف (EMS) مسموحة أيضًا.","p":"صحيح. القيادة مباشرة إلى العمل أو منه مسموحة."},"ref":{"doc":"NC","page":13}},{"id":"nc-010","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, as a general rule, how many passengers under 21 who are not family may a Level 2 driver carry when no supervising driver is in the car?","o":["None","Three","One","Four"],"h1":"It is the smallest number above zero.","h2":"As a general rule, a North Carolina Level 2 driver without a supervisor may carry only one passenger under 21 who is not from the driver's household; one more student may ride on a trip straight to or from school.","p":"Right. Only one passenger under 21."},"es":{"q":"En Carolina del Norte, como regla general, ¿cuántos pasajeros menores de 21 años que no son de la familia puede llevar un conductor de Nivel 2 cuando no va un conductor supervisor en el carro?","o":["Ninguno","Tres","Uno","Cuatro"],"h1":"Es el número más pequeño mayor que cero.","h2":"Como regla general, un conductor de Nivel 2 en Carolina del Norte sin supervisor solo puede llevar un pasajero menor de 21 años que no sea de su hogar; un estudiante más puede ir en un viaje directo a la escuela o de regreso.","p":"Correcto. Solo un pasajero menor de 21."},"zh":{"q":"在 North Carolina，一般来说，车里没有陪同的司机时，Level 2 司机可以载多少位不是家人、21 岁以下的乘客？","o":["一个都不行","三位","一位","四位"],"h1":"这是大于零的最小数字。","h2":"一般来说，North Carolina 的 Level 2 司机没有陪同的人时，只能载一位不是同一家庭、21 岁以下的乘客；直接上学或放学的路上，可以再多载一位学生。","p":"对。只能载一位 21 岁以下的乘客。"},"vi":{"q":"Ở North Carolina, theo quy định chung, người lái Cấp 2 được chở bao nhiêu hành khách dưới 21 tuổi không phải người nhà khi không có người lái xe giám sát trong xe?","o":["Không ai","Ba","Một","Bốn"],"h1":"Đó là số nhỏ nhất lớn hơn không.","h2":"Theo quy định chung, người lái Cấp 2 ở North Carolina khi không có người giám sát chỉ được chở một hành khách dưới 21 tuổi không sống cùng nhà với người lái; được chở thêm một học sinh nữa trên chuyến đi thẳng đến trường hoặc từ trường về.","p":"Đúng. Chỉ một hành khách dưới 21 tuổi."},"tl":{"q":"Sa North Carolina, bilang pangkalahatang tuntunin, ilang pasaherong wala pang 21 taong gulang at hindi kapamilya ang puwedeng isakay ng Level 2 driver kapag walang supervising driver sa kotse?","o":["Wala","Tatlo","Isa","Apat"],"h1":"Ito ang pinakamaliit na bilang na higit sa zero.","h2":"Bilang pangkalahatang tuntunin, ang Level 2 driver sa North Carolina na walang supervisor ay puwedeng magsakay ng isang pasahero lang na wala pang 21 at hindi kasama sa sambahayan ng driver; puwedeng sumakay ang isa pang estudyante sa diretsong biyahe papunta o pauwi mula sa paaralan.","p":"Tama. Isang pasahero lang na wala pang 21."},"ar":{"q":"في North Carolina، كقاعدة عامة، كم راكبًا عمره أقل من 21 سنة وليس من العائلة يمكن لسائق المستوى 2 أن ينقل عندما لا يكون في السيارة سائق مشرف؟","o":["لا أحد","ثلاثة","واحد","أربعة"],"h1":"هو أصغر عدد أكبر من الصفر.","h2":"كقاعدة عامة، يمكن لسائق المستوى 2 في North Carolina بدون مشرف أن ينقل راكبًا واحدًا فقط عمره أقل من 21 سنة ولا يعيش في بيت السائق؛ ويمكن أن يركب طالب إضافي واحد في رحلة مباشرة إلى المدرسة أو منها.","p":"صحيح. راكب واحد فقط عمره أقل من 21 سنة."},"ref":{"doc":"NC","page":13}},{"id":"nc-011","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, when does the one-passenger-under-21 limit for Level 2 drivers not apply?","o":["When it is raining","When all the passengers live in the driver's household","When the passengers are over 16","On short trips"],"h1":"Think about who lives under the same roof.","h2":"The North Carolina Level 2 limit of one passenger under 21 does not apply when all the passengers are members of the driver's household.","p":"Right. Household members are the exception."},"es":{"q":"En Carolina del Norte, ¿cuándo no se aplica el límite de un pasajero menor de 21 años para conductores de Nivel 2?","o":["Cuando llueve","Cuando todos los pasajeros viven en el mismo hogar que el conductor","Cuando los pasajeros tienen más de 16 años","En viajes cortos"],"h1":"Piense en quién vive bajo el mismo techo.","h2":"El límite de un pasajero menor de 21 años para el Nivel 2 en Carolina del Norte no se aplica cuando todos los pasajeros son miembros del hogar del conductor.","p":"Correcto. Los miembros del hogar son la excepción."},"zh":{"q":"在 North Carolina，Level 2 司机只能载一位 21 岁以下乘客的限制，什么时候不适用？","o":["下雨的时候","所有乘客都和司机住在同一个家里时","乘客超过 16 岁时","短途的时候"],"h1":"想一想谁和你住在同一个屋檐下。","h2":"当所有乘客都是司机家里的成员时，North Carolina Level 2 只能载一位 21 岁以下乘客的限制就不适用。","p":"对。家里的成员是例外。"},"vi":{"q":"Ở North Carolina, khi nào giới hạn một hành khách dưới 21 tuổi cho người lái Cấp 2 không được áp dụng?","o":["Khi trời mưa","Khi tất cả hành khách sống cùng nhà với người lái","Khi hành khách trên 16 tuổi","Trên những chuyến đi ngắn"],"h1":"Hãy nghĩ đến những người sống dưới cùng một mái nhà.","h2":"Giới hạn một hành khách dưới 21 tuổi cho người lái Cấp 2 ở North Carolina không áp dụng khi tất cả hành khách là người sống cùng nhà với người lái.","p":"Đúng. Người sống cùng nhà là trường hợp ngoại lệ."},"tl":{"q":"Sa North Carolina, kailan hindi umiiral ang limitasyon na isang pasaherong wala pang 21 para sa mga Level 2 driver?","o":["Kapag umuulan","Kapag lahat ng pasahero ay nakatira sa sambahayan ng driver","Kapag ang mga pasahero ay higit sa 16","Sa maiikling biyahe"],"h1":"Isipin kung sino ang nakatira sa iisang bubong.","h2":"Hindi umiiral ang limitasyon ng North Carolina na isang pasaherong wala pang 21 para sa Level 2 kapag lahat ng pasahero ay kasapi ng sambahayan ng driver.","p":"Tama. Ang mga kasama sa bahay ang eksepsiyon."},"ar":{"q":"في North Carolina، متى لا يُطبَّق حدّ الراكب الواحد الذي عمره أقل من 21 سنة على سائقي المستوى 2؟","o":["عندما تمطر","عندما يعيش كل الركاب في بيت السائق","عندما يكون الركاب أكبر من 16 سنة","في الرحلات القصيرة"],"h1":"فكّر في من يعيشون تحت سقف واحد.","h2":"لا يُطبَّق حدّ الراكب الواحد الذي عمره أقل من 21 سنة على سائق المستوى 2 في North Carolina عندما يكون كل الركاب من أفراد بيت السائق.","p":"صحيح. أفراد البيت هم الاستثناء."},"ref":{"doc":"NC","page":13}},{"id":"nc-012","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, what changes when a teen moves to a Level 3 full provisional license?","o":["Nothing changes","The teen may no longer drive at night","The teen needs a new supervisor","The time, supervision and passenger limits of Levels 1 and 2 no longer apply"],"h1":"Level 3 is the last step before a regular license.","h2":"With a North Carolina Level 3 full provisional license, the time, supervision and passenger limits of Levels 1 and 2 no longer apply.","p":"Right. Level 3 lifts those limits."},"es":{"q":"En Carolina del Norte, ¿qué cambia cuando un adolescente pasa a la licencia provisional completa de Nivel 3?","o":["No cambia nada","Ya no puede manejar de noche","Necesita un nuevo supervisor","Ya no se aplican los límites de horario, supervisión y pasajeros de los Niveles 1 y 2"],"h1":"El Nivel 3 es el último paso antes de una licencia regular.","h2":"Con la licencia provisional completa de Nivel 3 en Carolina del Norte, ya no se aplican los límites de horario, supervisión y pasajeros de los Niveles 1 y 2.","p":"Correcto. El Nivel 3 quita esos límites."},"zh":{"q":"在 North Carolina，青少年升到 Level 3 完整的临时驾照时，有什么改变？","o":["什么都不变","青少年不能再在晚上开车","青少年需要一位新的陪同人","Level 1 和 Level 2 的时间、陪同和乘客限制不再适用"],"h1":"Level 3 是拿普通驾照前的最后一步。","h2":"持 North Carolina Level 3 完整的临时驾照时，Level 1 和 Level 2 的时间、陪同和乘客限制都不再适用。","p":"对。Level 3 取消了这些限制。"},"vi":{"q":"Ở North Carolina, điều gì thay đổi khi một thanh thiếu niên lên bằng tạm thời đầy đủ Cấp 3 (Level 3 full provisional license)?","o":["Không có gì thay đổi","Thanh thiếu niên không còn được lái xe vào ban đêm","Thanh thiếu niên cần một người giám sát mới","Các giới hạn về giờ lái, người giám sát và hành khách của Cấp 1 và Cấp 2 không còn áp dụng"],"h1":"Cấp 3 là bước cuối cùng trước bằng lái thông thường.","h2":"Với bằng tạm thời đầy đủ Cấp 3 ở North Carolina, các giới hạn về giờ lái, người giám sát và hành khách của Cấp 1 và Cấp 2 không còn áp dụng.","p":"Đúng. Cấp 3 bỏ những giới hạn đó."},"tl":{"q":"Sa North Carolina, ano ang nagbabago kapag lumipat ang isang kabataan sa Level 3 full provisional license?","o":["Walang nagbabago","Hindi na puwedeng magmaneho sa gabi ang kabataan","Kailangan ng kabataan ng bagong supervisor","Hindi na umiiral ang mga limitasyon sa oras, supervision at pasahero ng Level 1 at 2"],"h1":"Ang Level 3 ang huling hakbang bago ang regular na lisensya.","h2":"Sa Level 3 full provisional license sa North Carolina, hindi na umiiral ang mga limitasyon sa oras, supervision at pasahero ng Level 1 at 2.","p":"Tama. Inaalis ng Level 3 ang mga limitasyong iyon."},"ar":{"q":"في North Carolina، ما الذي يتغيّر عندما ينتقل المراهق إلى الرخصة المؤقتة الكاملة من المستوى 3 (Level 3 full provisional license)؟","o":["لا شيء يتغيّر","لا يعود المراهق يستطيع القيادة في الليل","يحتاج المراهق إلى مشرف جديد","لا تعود قيود الوقت والإشراف والركاب في المستويين 1 و2 مطبّقة"],"h1":"المستوى 3 هو الخطوة الأخيرة قبل الرخصة العادية.","h2":"مع الرخصة المؤقتة الكاملة من المستوى 3 في North Carolina، لا تعود قيود الوقت والإشراف والركاب في المستويين 1 و2 مطبّقة.","p":"صحيح. المستوى 3 يرفع تلك القيود."},"ref":{"doc":"NC","page":13}},{"id":"nc-013","scope":"NC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Carolina, may a driver under 18 talk on a hands-free phone while driving?","o":["Yes, hands-free is always allowed","Yes, but only on highways","No, drivers under 18 may not use a phone at all, hands-free included","Yes, if a friend is in the car"],"h1":"For teens, the rule is stricter than for adults.","h2":"In North Carolina a driver under 18 may not use a mobile phone while driving, even a hands-free one, except for a few emergency and family calls.","p":"Right. Under 18, no phone, even hands-free."},"es":{"q":"En Carolina del Norte, ¿puede un conductor menor de 18 años hablar por teléfono con manos libres mientras maneja?","o":["Sí, el manos libres siempre está permitido","Sí, pero solo en carreteras","No, los menores de 18 no pueden usar el teléfono, ni siquiera con manos libres","Sí, si va un amigo en el carro"],"h1":"Para los adolescentes, la regla es más estricta que para los adultos.","h2":"En Carolina del Norte un conductor menor de 18 años no puede usar el teléfono mientras maneja, ni siquiera con manos libres, salvo algunas llamadas de emergencia y de familia.","p":"Correcto. Menores de 18: nada de teléfono, ni con manos libres."},"zh":{"q":"在 North Carolina，18 岁以下的司机开车时可以用免提手机通话吗？","o":["可以，免提一直都可以","可以，但只在公路上","不可以，18 岁以下的司机完全不能用手机，免提也不行","可以，如果车里有朋友"],"h1":"对青少年来说，规定比成年人更严格。","h2":"在 North Carolina，18 岁以下的司机开车时不能用手机，免提的也不行，只有几种紧急和家人电话例外。","p":"对。18 岁以下，不能用手机，免提也不行。"},"vi":{"q":"Ở North Carolina, người lái xe dưới 18 tuổi có được nói chuyện qua điện thoại rảnh tay (hands-free) khi lái xe không?","o":["Có, rảnh tay thì luôn được phép","Có, nhưng chỉ trên xa lộ","Không, người lái dưới 18 tuổi hoàn toàn không được dùng điện thoại, kể cả rảnh tay","Có, nếu có bạn ngồi trong xe"],"h1":"Đối với thanh thiếu niên, quy định nghiêm hơn so với người lớn.","h2":"Ở North Carolina, người lái xe dưới 18 tuổi không được dùng điện thoại di động khi lái xe, kể cả loại rảnh tay, trừ một vài cuộc gọi khẩn cấp và gọi cho gia đình.","p":"Đúng. Dưới 18 tuổi, không dùng điện thoại, kể cả rảnh tay."},"tl":{"q":"Sa North Carolina, puwede bang makipag-usap sa hands-free na telepono ang driver na wala pang 18 habang nagmamaneho?","o":["Oo, palaging pinapayagan ang hands-free","Oo, pero sa highway lang","Hindi, hindi puwedeng gumamit ng telepono ang mga driver na wala pang 18, kasama ang hands-free","Oo, kung may kaibigan sa kotse"],"h1":"Para sa mga kabataan, mas mahigpit ang tuntunin kaysa sa mga adult.","h2":"Sa North Carolina, hindi puwedeng gumamit ng mobile phone habang nagmamaneho ang driver na wala pang 18, kahit hands-free, maliban sa ilang tawag para sa emergency at pamilya.","p":"Tama. Wala pang 18, bawal ang telepono, kahit hands-free."},"ar":{"q":"في North Carolina، هل يمكن للسائق الذي عمره أقل من 18 سنة أن يتكلّم بهاتف بدون استخدام اليدين (hands-free) أثناء القيادة؟","o":["نعم، الهاتف بدون يدين مسموح دائمًا","نعم، لكن على الطرق السريعة فقط","لا، السائقون الذين أعمارهم أقل من 18 سنة لا يستخدمون الهاتف أبدًا، حتى بدون يدين","نعم، إذا كان صديق في السيارة"],"h1":"بالنسبة للمراهقين، القاعدة أشدّ منها للكبار.","h2":"في North Carolina لا يجوز للسائق الذي عمره أقل من 18 سنة أن يستخدم الهاتف المحمول أثناء القيادة، حتى بدون يدين، إلا في بعض مكالمات الطوارئ والعائلة.","p":"صحيح. أقل من 18 سنة، لا هاتف، حتى بدون يدين."},"ref":{"doc":"NC","page":41}},{"id":"nc-014","scope":"NC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Carolina, which phone call may a driver under 18 make while driving?","o":["A call to a friend","A call to a parent, legal guardian or spouse","A call to order food","Any call shorter than one minute"],"h1":"The exception is for emergencies and close family.","h2":"A North Carolina driver under 18 may call a parent, legal guardian or spouse, or emergency services, while driving; other calls are not allowed.","p":"Right. A parent, guardian or spouse is allowed."},"es":{"q":"En Carolina del Norte, ¿qué llamada puede hacer un conductor menor de 18 años mientras maneja?","o":["Una llamada a un amigo","Una llamada a su padre, madre, tutor legal o cónyuge","Una llamada para pedir comida","Cualquier llamada de menos de un minuto"],"h1":"La excepción es para emergencias y familia cercana.","h2":"Un conductor menor de 18 años en Carolina del Norte puede llamar a su padre, madre, tutor legal o cónyuge, o a servicios de emergencia, mientras maneja; otras llamadas no están permitidas.","p":"Correcto. Puede llamar a su padre, madre, tutor o cónyuge."},"zh":{"q":"在 North Carolina，18 岁以下的司机开车时可以打哪一种电话？","o":["打给朋友","打给父母、法定监护人或配偶","打电话订餐","任何一分钟以内的电话"],"h1":"例外是给紧急情况和亲近家人的。","h2":"North Carolina 18 岁以下的司机开车时可以打电话给父母、法定监护人或配偶，或者打给紧急服务；其他电话都不可以。","p":"对。可以打给父母、监护人或配偶。"},"vi":{"q":"Ở North Carolina, người lái xe dưới 18 tuổi được gọi cuộc điện thoại nào khi đang lái xe?","o":["Gọi cho bạn bè","Gọi cho cha mẹ, người giám hộ hợp pháp hoặc vợ/chồng","Gọi để đặt đồ ăn","Bất kỳ cuộc gọi nào ngắn hơn một phút"],"h1":"Ngoại lệ dành cho trường hợp khẩn cấp và gia đình gần gũi.","h2":"Người lái xe dưới 18 tuổi ở North Carolina được gọi cho cha mẹ, người giám hộ hợp pháp hoặc vợ/chồng, hoặc gọi dịch vụ khẩn cấp, khi đang lái xe; các cuộc gọi khác không được phép.","p":"Đúng. Được gọi cho cha mẹ, người giám hộ hoặc vợ/chồng."},"tl":{"q":"Sa North Carolina, anong tawag sa telepono ang puwedeng gawin ng driver na wala pang 18 habang nagmamaneho?","o":["Tawag sa kaibigan","Tawag sa magulang, legal na tagapag-alaga o asawa","Tawag para umorder ng pagkain","Kahit anong tawag na mas maikli sa isang minuto"],"h1":"Ang eksepsiyon ay para sa emergency at malapit na pamilya.","h2":"Ang driver sa North Carolina na wala pang 18 ay puwedeng tumawag sa magulang, legal na tagapag-alaga o asawa, o sa emergency services, habang nagmamaneho; hindi pinapayagan ang ibang tawag.","p":"Tama. Pinapayagan ang magulang, tagapag-alaga o asawa."},"ar":{"q":"في North Carolina، أي مكالمة هاتفية يمكن للسائق الذي عمره أقل من 18 سنة أن يجريها أثناء القيادة؟","o":["مكالمة لصديق","مكالمة لأحد الوالدين أو الوصي القانوني أو الزوج أو الزوجة","مكالمة لطلب طعام","أي مكالمة أقصر من دقيقة واحدة"],"h1":"الاستثناء للطوارئ وللعائلة القريبة.","h2":"يمكن للسائق في North Carolina الذي عمره أقل من 18 سنة أن يتّصل بأحد الوالدين أو الوصي القانوني أو الزوج أو الزوجة، أو بخدمات الطوارئ، أثناء القيادة؛ والمكالمات الأخرى غير مسموحة.","p":"صحيح. الوالدان أو الوصي أو الزوج أو الزوجة مسموح."},"ref":{"doc":"NC","page":12}},{"id":"nc-015","scope":"NC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Carolina, may an adult driver read a text message while the car is moving?","o":["No, no driver may text or read texts while the car is moving","Yes, if the message is short","Yes, on empty roads","Yes, if the driver is over 21"],"h1":"This rule applies to drivers of every age.","h2":"North Carolina bans all drivers, of any age, from texting or reading a text message while the vehicle is moving.","p":"Right. No texting while moving, at any age."},"es":{"q":"En Carolina del Norte, ¿puede un conductor adulto leer un mensaje de texto mientras el carro está en movimiento?","o":["No, ningún conductor puede escribir ni leer mensajes mientras el carro está en movimiento","Sí, si el mensaje es corto","Sí, en calles vacías","Sí, si el conductor tiene más de 21 años"],"h1":"Esta regla es para conductores de todas las edades.","h2":"Carolina del Norte prohíbe a todos los conductores, de cualquier edad, escribir o leer mensajes de texto mientras el vehículo está en movimiento.","p":"Correcto. Nada de mensajes en movimiento, a ninguna edad."},"zh":{"q":"在 North Carolina，成年司机可以在车开动时看短信吗？","o":["不可以，车在开动时任何司机都不能发短信或看短信","可以，如果短信很短","可以，在没车的路上","可以，如果司机超过 21 岁"],"h1":"这条规定适用于所有年龄的司机。","h2":"North Carolina 禁止所有司机，不管几岁，在车开动时发短信或看短信。","p":"对。不管几岁，车在开时都不能发短信。"},"vi":{"q":"Ở North Carolina, người lái xe trưởng thành có được đọc tin nhắn khi xe đang chạy không?","o":["Không, không người lái xe nào được nhắn tin hoặc đọc tin nhắn khi xe đang chạy","Có, nếu tin nhắn ngắn","Có, trên đường vắng","Có, nếu người lái trên 21 tuổi"],"h1":"Quy định này áp dụng cho người lái xe ở mọi lứa tuổi.","h2":"North Carolina cấm tất cả người lái xe, ở mọi lứa tuổi, nhắn tin hoặc đọc tin nhắn khi xe đang chạy.","p":"Đúng. Không nhắn tin khi xe đang chạy, ở mọi lứa tuổi."},"tl":{"q":"Sa North Carolina, puwede bang magbasa ng text message ang adult na driver habang umaandar ang kotse?","o":["Hindi, walang driver na puwedeng mag-text o magbasa ng text habang umaandar ang kotse","Oo, kung maikli ang mensahe","Oo, sa walang laman na kalsada","Oo, kung ang driver ay higit sa 21"],"h1":"Para sa mga driver sa lahat ng edad ang tuntuning ito.","h2":"Ipinagbabawal ng North Carolina sa lahat ng driver, anuman ang edad, ang pag-text o pagbasa ng text message habang umaandar ang sasakyan.","p":"Tama. Bawal mag-text habang umaandar, sa anumang edad."},"ar":{"q":"في North Carolina، هل يمكن للسائق البالغ أن يقرأ رسالة نصية بينما السيارة تتحرك؟","o":["لا، لا يجوز لأي سائق أن يكتب أو يقرأ رسائل نصية بينما السيارة تتحرك","نعم، إذا كانت الرسالة قصيرة","نعم، على الطرق الفارغة","نعم، إذا كان عمر السائق أكثر من 21 سنة"],"h1":"هذه القاعدة تنطبق على السائقين من كل الأعمار.","h2":"تمنع North Carolina كل السائقين، من أي عمر، من كتابة أو قراءة الرسائل النصية بينما المركبة تتحرك.","p":"صحيح. لا رسائل نصية أثناء الحركة، في أي عمر."},"ref":{"doc":"NC","page":41}},{"id":"nc-016","scope":"NC","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In North Carolina, a school bus stops with its stop arm out on a two-lane road with a center turn lane. Who must stop?","o":["Only traffic behind the bus","Only traffic coming toward the bus","No one, because the turn lane separates traffic","Traffic in both directions"],"h1":"On a road with only two lanes, the turn lane does not change the rule.","h2":"In North Carolina, on a two-lane road with a center turn lane, traffic in both directions must stop for a stopped school bus.","p":"Right. Both directions stop."},"es":{"q":"En Carolina del Norte, un autobús escolar se detiene con el brazo de alto extendido en una calle de dos carriles con un carril central para girar. ¿Quién debe detenerse?","o":["Solo el tráfico detrás del autobús","Solo el tráfico que viene hacia el autobús","Nadie, porque el carril para girar separa el tráfico","El tráfico en ambas direcciones"],"h1":"En una calle de solo dos carriles, el carril para girar no cambia la regla.","h2":"En Carolina del Norte, en una calle de dos carriles con carril central para girar, el tráfico en ambas direcciones debe detenerse por un autobús escolar detenido.","p":"Correcto. Ambas direcciones se detienen."},"zh":{"q":"在 North Carolina，一辆校车在有中央转弯车道的双车道路上停下，伸出停车臂。谁必须停车？","o":["只有校车后面的车","只有朝校车开过来的车","没有人，因为转弯车道把车流分开了","两个方向的车"],"h1":"在只有两条车道的路上，转弯车道不会改变规定。","h2":"在 North Carolina，在有中央转弯车道的双车道路上，两个方向的车都必须为停着的校车停车。","p":"对。两个方向都要停。"},"vi":{"q":"Ở North Carolina, một xe buýt trường học dừng lại và giơ cần báo dừng (stop arm) trên con đường hai làn có làn rẽ ở giữa. Ai phải dừng lại?","o":["Chỉ xe ở phía sau xe buýt","Chỉ xe đang đi về phía xe buýt","Không ai, vì làn rẽ ngăn cách hai chiều xe","Xe ở cả hai chiều"],"h1":"Trên con đường chỉ có hai làn, làn rẽ không làm thay đổi quy định.","h2":"Ở North Carolina, trên con đường hai làn có làn rẽ ở giữa, xe ở cả hai chiều phải dừng lại khi xe buýt trường học dừng.","p":"Đúng. Cả hai chiều đều dừng."},"tl":{"q":"Sa North Carolina, huminto ang isang school bus na nakalabas ang stop arm sa kalsadang may dalawang lane at may center turn lane sa gitna. Sino ang dapat huminto?","o":["Ang mga sasakyan lang sa likod ng bus","Ang mga sasakyan lang na papalapit sa bus","Wala, dahil hinahati ng turn lane ang trapiko","Ang mga sasakyan sa magkabilang direksyon"],"h1":"Sa kalsadang may dalawang lane lang, hindi binabago ng turn lane ang tuntunin.","h2":"Sa North Carolina, sa kalsadang may dalawang lane at center turn lane, dapat huminto ang mga sasakyan sa magkabilang direksyon para sa nakahintong school bus.","p":"Tama. Humihinto ang magkabilang direksyon."},"ar":{"q":"في North Carolina، توقّفت حافلة مدرسية وذراع التوقّف (stop arm) مفتوح على طريق بمسارين مع مسار للانعطاف في الوسط. من يجب أن يتوقّف؟","o":["السيارات خلف الحافلة فقط","السيارات القادمة نحو الحافلة فقط","لا أحد، لأن مسار الانعطاف يفصل بين الاتجاهين","السيارات في الاتجاهين"],"h1":"على طريق بمسارين فقط، مسار الانعطاف لا يغيّر القاعدة.","h2":"في North Carolina، على طريق بمسارين مع مسار للانعطاف في الوسط، يجب أن تتوقّف السيارات في الاتجاهين عند توقّف الحافلة المدرسية.","p":"صحيح. الاتجاهان يتوقّفان."},"ref":{"doc":"NC","page":48}},{"id":"nc-017","scope":"NC","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In North Carolina, a school bus stops on a four-lane road with no median, only painted lines. Who must stop?","o":["Only traffic behind the bus","Only the lane next to the bus","Traffic in both directions","No one"],"h1":"Painted lines do not separate the two sides.","h2":"In North Carolina, on a four-lane road with no median, all traffic in both directions must stop for a stopped school bus.","p":"Right. With no median, everyone stops."},"es":{"q":"En Carolina del Norte, un autobús escolar se detiene en una calle de cuatro carriles sin mediana, solo con líneas pintadas. ¿Quién debe detenerse?","o":["Solo el tráfico detrás del autobús","Solo el carril al lado del autobús","El tráfico en ambas direcciones","Nadie"],"h1":"Las líneas pintadas no separan los dos lados.","h2":"En Carolina del Norte, en una calle de cuatro carriles sin mediana, todo el tráfico en ambas direcciones debe detenerse por un autobús escolar detenido.","p":"Correcto. Sin mediana, todos se detienen."},"zh":{"q":"在 North Carolina，一辆校车在没有中央隔离带、只有画线的四车道路上停下。谁必须停车？","o":["只有校车后面的车","只有校车旁边车道的车","两个方向的车","没有人"],"h1":"画的线不能把两边分开。","h2":"在 North Carolina，在没有中央隔离带的四车道路上，两个方向的所有车都必须为停着的校车停车。","p":"对。没有隔离带时，每个人都要停。"},"vi":{"q":"Ở North Carolina, một xe buýt trường học dừng lại trên con đường bốn làn không có dải phân cách, chỉ có vạch sơn. Ai phải dừng lại?","o":["Chỉ xe ở phía sau xe buýt","Chỉ làn bên cạnh xe buýt","Xe ở cả hai chiều","Không ai"],"h1":"Vạch sơn không ngăn cách hai bên đường.","h2":"Ở North Carolina, trên con đường bốn làn không có dải phân cách, tất cả xe ở cả hai chiều phải dừng lại khi xe buýt trường học dừng.","p":"Đúng. Không có dải phân cách thì mọi người đều dừng."},"tl":{"q":"Sa North Carolina, huminto ang isang school bus sa kalsadang may apat na lane na walang median, may pinturang guhit lang. Sino ang dapat huminto?","o":["Ang mga sasakyan lang sa likod ng bus","Ang lane lang na katabi ng bus","Ang mga sasakyan sa magkabilang direksyon","Wala"],"h1":"Hindi hinahati ng pinturang guhit ang dalawang panig.","h2":"Sa North Carolina, sa kalsadang may apat na lane na walang median, dapat huminto ang lahat ng sasakyan sa magkabilang direksyon para sa nakahintong school bus.","p":"Tama. Kapag walang median, humihinto ang lahat."},"ar":{"q":"في North Carolina، توقّفت حافلة مدرسية على طريق بأربعة مسارات بدون فاصل في الوسط، فقط خطوط مرسومة. من يجب أن يتوقّف؟","o":["السيارات خلف الحافلة فقط","المسار الذي بجانب الحافلة فقط","السيارات في الاتجاهين","لا أحد"],"h1":"الخطوط المرسومة لا تفصل بين جانبي الطريق.","h2":"في North Carolina، على طريق بأربعة مسارات بدون فاصل في الوسط، يجب أن تتوقّف كل السيارات في الاتجاهين عند توقّف الحافلة المدرسية.","p":"صحيح. بدون فاصل، الجميع يتوقّف."},"ref":{"doc":"NC","page":48}},{"id":"nc-018","scope":"NC","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In North Carolina, a school bus stops on a divided highway with a median. Who must stop?","o":["Traffic in both directions","Only traffic following the bus","Only traffic coming toward the bus","No one"],"h1":"A median protects the other side of the road.","h2":"In North Carolina, on a divided highway with a median, only the traffic following the bus must stop.","p":"Right. Only traffic behind the bus stops."},"es":{"q":"En Carolina del Norte, un autobús escolar se detiene en una carretera dividida con mediana. ¿Quién debe detenerse?","o":["El tráfico en ambas direcciones","Solo el tráfico que va detrás del autobús","Solo el tráfico que viene hacia el autobús","Nadie"],"h1":"Una mediana protege el otro lado de la carretera.","h2":"En Carolina del Norte, en una carretera dividida con mediana, solo el tráfico que va detrás del autobús debe detenerse.","p":"Correcto. Solo se detiene el tráfico detrás del autobús."},"zh":{"q":"在 North Carolina，一辆校车在有中央隔离带的分隔公路上停下。谁必须停车？","o":["两个方向的车","只有跟在校车后面的车","只有朝校车开过来的车","没有人"],"h1":"中央隔离带保护着路的另一边。","h2":"在 North Carolina，在有中央隔离带的分隔公路上，只有跟在校车后面的车必须停车。","p":"对。只有校车后面的车要停。"},"vi":{"q":"Ở North Carolina, một xe buýt trường học dừng lại trên xa lộ có dải phân cách ở giữa. Ai phải dừng lại?","o":["Xe ở cả hai chiều","Chỉ xe đi theo sau xe buýt","Chỉ xe đang đi về phía xe buýt","Không ai"],"h1":"Dải phân cách bảo vệ phía bên kia đường.","h2":"Ở North Carolina, trên xa lộ có dải phân cách ở giữa, chỉ xe đi theo sau xe buýt phải dừng lại.","p":"Đúng. Chỉ xe phía sau xe buýt phải dừng."},"tl":{"q":"Sa North Carolina, huminto ang isang school bus sa divided highway na may median. Sino ang dapat huminto?","o":["Ang mga sasakyan sa magkabilang direksyon","Ang mga sasakyan lang na sumusunod sa bus","Ang mga sasakyan lang na papalapit sa bus","Wala"],"h1":"Pinoprotektahan ng median ang kabilang panig ng kalsada.","h2":"Sa North Carolina, sa divided highway na may median, ang mga sasakyan lang na sumusunod sa bus ang dapat huminto.","p":"Tama. Ang mga sasakyan lang sa likod ng bus ang humihinto."},"ar":{"q":"في North Carolina، توقّفت حافلة مدرسية على طريق سريع مقسوم بفاصل في الوسط. من يجب أن يتوقّف؟","o":["السيارات في الاتجاهين","السيارات التي تسير خلف الحافلة فقط","السيارات القادمة نحو الحافلة فقط","لا أحد"],"h1":"الفاصل في الوسط يحمي الجانب الآخر من الطريق.","h2":"في North Carolina، على طريق سريع مقسوم بفاصل في الوسط، يجب أن تتوقّف فقط السيارات التي تسير خلف الحافلة.","p":"صحيح. فقط السيارات خلف الحافلة تتوقّف."},"ref":{"doc":"NC","page":48}},{"id":"nc-019","scope":"NC","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In North Carolina, what does the Move Over Law require when you approach an emergency vehicle stopped on the side of the road with lights flashing?","o":["Keep your speed and lane","Stop behind it","Honk and pass quickly","Move over a lane, or slow down and be ready to stop if you cannot"],"h1":"There is a first choice, and a second choice when the first is not possible.","h2":"North Carolina's Move Over Law requires you to move over a lane, or, if you cannot, slow down to a speed that lets you stop if needed.","p":"Right. Move over, or slow down."},"es":{"q":"En Carolina del Norte, ¿qué exige la Ley de Cambio de Carril (Move Over) cuando usted se acerca a un vehículo de emergencia detenido al lado de la carretera con luces intermitentes?","o":["Mantener su velocidad y su carril","Detenerse detrás de él","Tocar la bocina y pasar rápido","Cambiarse un carril o, si no puede, bajar la velocidad y estar listo para detenerse"],"h1":"Hay una primera opción, y una segunda cuando la primera no es posible.","h2":"La Ley de Cambio de Carril de Carolina del Norte exige que usted se cambie un carril o, si no puede, que baje a una velocidad que le permita detenerse si hace falta.","p":"Correcto. Cámbiese de carril o baje la velocidad."},"zh":{"q":"在 North Carolina，当你接近一辆停在路边、闪着灯的急救车辆时，Move Over Law 要求你怎么做？","o":["保持速度和车道","在它后面停车","按喇叭，很快开过去","换开一条车道；如果不能，就减速并准备停车"],"h1":"有第一个选择，第一个做不到时还有第二个选择。","h2":"North Carolina 的 Move Over Law 要求你换开一条车道；如果不能，就减速到需要时可以停下来的速度。","p":"对。让出车道，或者减速。"},"vi":{"q":"Ở North Carolina, Luật Tránh Sang Làn Khác (Move Over Law) yêu cầu gì khi bạn đến gần một xe cấp cứu đang dừng bên lề đường và nháy đèn?","o":["Giữ nguyên tốc độ và làn xe","Dừng lại phía sau xe đó","Bấm còi và vượt qua thật nhanh","Chuyển sang một làn khác, hoặc nếu không thể thì chạy chậm lại và sẵn sàng dừng"],"h1":"Có một lựa chọn đầu tiên, và một lựa chọn thứ hai khi không làm được lựa chọn đầu tiên.","h2":"Luật Move Over của North Carolina yêu cầu bạn chuyển sang một làn khác, hoặc nếu không thể, phải giảm tốc độ đến mức có thể dừng lại khi cần.","p":"Đúng. Chuyển làn, hoặc chạy chậm lại."},"tl":{"q":"Sa North Carolina, ano ang hinihingi ng Move Over Law kapag papalapit ka sa emergency vehicle na nakahinto sa gilid ng kalsada at may kumikislap na ilaw?","o":["Panatilihin ang bilis at lane mo","Huminto sa likod nito","Bumusina at lumampas nang mabilis","Lumipat ng isang lane, o kung hindi mo kaya, bumagal at maging handang huminto"],"h1":"May unang pagpipilian, at pangalawa kapag hindi posible ang una.","h2":"Hinihingi ng Move Over Law ng North Carolina na lumipat ka ng isang lane, o kung hindi mo kaya, bumagal sa bilis na makakapagpahinto sa iyo kung kailangan.","p":"Tama. Lumipat ng lane, o bumagal."},"ar":{"q":"في North Carolina، ماذا يطلب قانون الابتعاد (Move Over Law) عندما تقترب من مركبة طوارئ متوقّفة على جانب الطريق وأضواؤها تومض؟","o":["حافظ على سرعتك ومسارك","توقّف خلفها","استخدم البوق وتجاوزها بسرعة","انتقل إلى مسار آخر، أو إذا لم تستطع، خفّف السرعة وكن مستعدًا للتوقّف"],"h1":"هناك خيار أول، وخيار ثانٍ عندما لا يكون الأول ممكنًا.","h2":"يطلب قانون Move Over في North Carolina أن تنتقل إلى مسار آخر، أو إذا لم تستطع، أن تخفّف سرعتك إلى سرعة تسمح لك بالتوقّف عند الحاجة.","p":"صحيح. انتقل إلى مسار آخر، أو خفّف السرعة."},"ref":{"doc":"NC","page":49}},{"id":"nc-020","scope":"NC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Carolina, how much alcohol may a driver under 21 have in their body while driving?","o":["None at all","Up to 0.02 percent","Up to 0.05 percent","Up to 0.08 percent"],"h1":"For drivers under 21, the rule is the strictest possible.","h2":"In North Carolina a driver under 21 may not have any alcohol in their body while driving; the 0.08 limit is only for drivers 21 and older.","p":"Right. Under 21, no alcohol at all."},"es":{"q":"En Carolina del Norte, ¿cuánto alcohol puede tener en el cuerpo un conductor menor de 21 años mientras maneja?","o":["Nada","Hasta 0.02 por ciento","Hasta 0.05 por ciento","Hasta 0.08 por ciento"],"h1":"Para menores de 21, la regla es la más estricta posible.","h2":"En Carolina del Norte un conductor menor de 21 años no puede tener nada de alcohol en el cuerpo mientras maneja; el límite de 0.08 es solo para conductores de 21 años o más.","p":"Correcto. Menores de 21: nada de alcohol."},"zh":{"q":"在 North Carolina，21 岁以下的司机开车时体内可以有多少酒精？","o":["一点都不行","最多 0.02%","最多 0.05%","最多 0.08%"],"h1":"对 21 岁以下的司机，规定是最严格的。","h2":"在 North Carolina，21 岁以下的司机开车时体内不能有任何酒精；0.08 的限值只适用于 21 岁及以上的司机。","p":"对。21 岁以下，完全不能有酒精。"},"vi":{"q":"Ở North Carolina, người lái xe dưới 21 tuổi được có bao nhiêu rượu trong cơ thể khi lái xe?","o":["Hoàn toàn không có","Tối đa 0.02 phần trăm","Tối đa 0.05 phần trăm","Tối đa 0.08 phần trăm"],"h1":"Đối với người lái dưới 21 tuổi, quy định nghiêm ngặt nhất có thể.","h2":"Ở North Carolina, người lái xe dưới 21 tuổi không được có chút rượu nào trong cơ thể khi lái xe; mức giới hạn 0.08 chỉ dành cho người lái từ 21 tuổi trở lên.","p":"Đúng. Dưới 21 tuổi, hoàn toàn không có rượu."},"tl":{"q":"Sa North Carolina, gaano karaming alak ang puwedeng nasa katawan ng driver na wala pang 21 habang nagmamaneho?","o":["Wala talaga","Hanggang 0.02 porsiyento","Hanggang 0.05 porsiyento","Hanggang 0.08 porsiyento"],"h1":"Para sa mga driver na wala pang 21, ang tuntunin ang pinakamahigpit.","h2":"Sa North Carolina, hindi puwedeng may kahit anong alak sa katawan ang driver na wala pang 21 habang nagmamaneho; ang limitasyong 0.08 ay para lang sa mga driver na 21 pataas.","p":"Tama. Wala pang 21, walang alak talaga."},"ar":{"q":"في North Carolina، كم من الكحول يمكن أن يكون في جسم السائق الذي عمره أقل من 21 سنة أثناء القيادة؟","o":["لا شيء على الإطلاق","حتى 0.02 بالمئة","حتى 0.05 بالمئة","حتى 0.08 بالمئة"],"h1":"للسائقين الذين أعمارهم أقل من 21 سنة، القاعدة هي الأشدّ.","h2":"في North Carolina لا يجوز أن يكون في جسم السائق الذي عمره أقل من 21 سنة أي كحول أثناء القيادة؛ وحدّ 0.08 هو فقط للسائقين الذين أعمارهم 21 سنة فأكثر.","p":"صحيح. أقل من 21 سنة، لا كحول على الإطلاق."},"ref":{"doc":"NC","page":33}},{"id":"nc-021","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, how many driver license points within three years can lead to a license suspension?","o":["4 points","7 points","12 points","10 points"],"h1":"It is more than the number that sends you to a driver improvement clinic.","h2":"In North Carolina, your license may be suspended if you collect 12 points within three years.","p":"Right. 12 points in three years can mean a suspension."},"es":{"q":"En Carolina del Norte, ¿cuántos puntos en la licencia dentro de tres años pueden llevar a una suspensión?","o":["4 puntos","7 puntos","12 puntos","10 puntos"],"h1":"Es más que el número que lo manda a una clínica para mejorar como conductor.","h2":"En Carolina del Norte, su licencia puede ser suspendida si acumula 12 puntos dentro de tres años.","p":"Correcto. 12 puntos en tres años pueden causar una suspensión."},"zh":{"q":"在 North Carolina，三年内累计多少驾照扣分可能导致驾照被暂停？","o":["4 分","7 分","12 分","10 分"],"h1":"它比让你去上驾驶改进课（driver improvement clinic）的分数多。","h2":"在 North Carolina，如果你在三年内累计 12 分，你的驾照可能会被暂停。","p":"对。三年内 12 分可能导致驾照被暂停。"},"vi":{"q":"Ở North Carolina, bao nhiêu điểm phạt trên bằng lái trong vòng ba năm có thể làm bằng lái bị đình chỉ?","o":["4 điểm","7 điểm","12 điểm","10 điểm"],"h1":"Con số này nhiều hơn số điểm khiến bạn phải đi học lớp cải thiện kỹ năng lái xe (driver improvement clinic).","h2":"Ở North Carolina, bằng lái của bạn có thể bị đình chỉ nếu bạn bị 12 điểm trong vòng ba năm.","p":"Đúng. 12 điểm trong ba năm có thể dẫn đến đình chỉ bằng lái."},"tl":{"q":"Sa North Carolina, ilang point sa driver license sa loob ng tatlong taon ang puwedeng humantong sa suspensyon ng lisensya?","o":["4 na point","7 point","12 point","10 point"],"h1":"Mas marami ito kaysa sa bilang na magpapapunta sa iyo sa driver improvement clinic.","h2":"Sa North Carolina, puwedeng masuspinde ang lisensya mo kung makaipon ka ng 12 point sa loob ng tatlong taon.","p":"Tama. Ang 12 point sa tatlong taon ay puwedeng mauwi sa suspensyon."},"ar":{"q":"في North Carolina، كم نقطة على رخصة القيادة خلال ثلاث سنوات قد تؤدي إلى إيقاف الرخصة؟","o":["4 نقاط","7 نقاط","12 نقطة","10 نقاط"],"h1":"هو أكثر من العدد الذي يرسلك إلى دورة تحسين القيادة (driver improvement clinic).","h2":"في North Carolina، قد تُوقَف رخصتك إذا جمعت 12 نقطة خلال ثلاث سنوات.","p":"صحيح. 12 نقطة في ثلاث سنوات قد تعني إيقاف الرخصة."},"ref":{"doc":"NC","page":34}},{"id":"nc-022","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, how many license points do you get for passing a stopped school bus?","o":["5 points","1 point","2 points","3 points"],"h1":"It is one of the highest point values on the list for regular drivers.","h2":"In North Carolina, passing a stopped school bus puts 5 points on your license.","p":"Right. Passing a stopped school bus costs 5 points."},"es":{"q":"En Carolina del Norte, ¿cuántos puntos en la licencia recibe por rebasar un autobús escolar detenido?","o":["5 puntos","1 punto","2 puntos","3 puntos"],"h1":"Es uno de los valores más altos de la lista para conductores comunes.","h2":"En Carolina del Norte, rebasar un autobús escolar detenido pone 5 puntos en su licencia.","p":"Correcto. Rebasar un autobús escolar detenido cuesta 5 puntos."},"zh":{"q":"在 North Carolina，超越停着的校车会被扣多少驾照分？","o":["5 分","1 分","2 分","3 分"],"h1":"这是普通驾驶人扣分表上最高的分数之一。","h2":"在 North Carolina，超越停着的校车会在你的驾照上记 5 分。","p":"对。超越停着的校车要扣 5 分。"},"vi":{"q":"Ở North Carolina, bạn bị bao nhiêu điểm phạt trên bằng lái khi vượt qua một xe buýt trường học đang dừng?","o":["5 điểm","1 điểm","2 điểm","3 điểm"],"h1":"Đây là một trong những mức điểm cao nhất trong danh sách dành cho tài xế thông thường.","h2":"Ở North Carolina, vượt qua một xe buýt trường học đang dừng sẽ bị ghi 5 điểm vào bằng lái của bạn.","p":"Đúng. Vượt xe buýt trường học đang dừng bị 5 điểm."},"tl":{"q":"Sa North Carolina, ilang puntos sa lisensya ang makukuha mo kapag nilampasan mo ang isang nakahintong school bus?","o":["5 puntos","1 punto","2 puntos","3 puntos"],"h1":"Isa ito sa pinakamataas na puntos sa listahan para sa karaniwang mga driver.","h2":"Sa North Carolina, ang paglampas sa isang nakahintong school bus ay naglalagay ng 5 puntos sa lisensya mo.","p":"Tama. 5 puntos ang kapalit ng paglampas sa nakahintong school bus."},"ar":{"q":"في North Carolina، كم نقطة تُسجَّل على رخصتك إذا تجاوزت حافلة مدرسية متوقفة؟","o":["5 نقاط","نقطة واحدة (1)","نقطتان (2)","3 نقاط"],"h1":"هي من أعلى قيم النقاط في القائمة للسائقين العاديين.","h2":"في North Carolina، تجاوز حافلة مدرسية متوقفة يضع 5 نقاط على رخصتك.","p":"صحيح. تجاوز حافلة مدرسية متوقفة يكلّفك 5 نقاط."},"ref":{"doc":"NC","page":34}},{"id":"nc-023","scope":"NC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Carolina, a driver charged with impaired driving refuses a breath or blood test. What happens to the license?","o":["Nothing, if the driver was not drunk","A warning letter from the DMV","A fine, but no loss of license","At least 30 days right away, plus at least 12 months from the DMV"],"h1":"Refusing the test is treated very seriously.","h2":"In North Carolina, refusing the test means the license is taken right away for at least 30 days, and the DMV adds at least 12 more months.","p":"Right. Refusing the test costs your license for a long time."},"es":{"q":"En Carolina del Norte, a un conductor acusado de manejar bajo los efectos se le pide una prueba de aliento o de sangre y se niega. ¿Qué pasa con su licencia?","o":["Nada, si el conductor no estaba ebrio","Una carta de advertencia del DMV","Una multa, pero no pierde la licencia","Al menos 30 días de inmediato, más al menos 12 meses por parte del DMV"],"h1":"Negarse a la prueba se toma muy en serio.","h2":"En Carolina del Norte, negarse a la prueba significa que le quitan la licencia de inmediato por al menos 30 días, y el DMV agrega al menos 12 meses más.","p":"Correcto. Negarse a la prueba le cuesta la licencia por mucho tiempo."},"zh":{"q":"在 North Carolina，一名被控酒后或药后驾驶（impaired driving）的驾驶人拒绝做呼气或血液检测。驾照会怎样？","o":["如果驾驶人没喝醉，就没有任何事","DMV 寄一封警告信","罚款，但不会失去驾照","马上被收走至少 30 天，DMV 还会再加至少 12 个月"],"h1":"拒绝检测会被非常严肃地处理。","h2":"在 North Carolina，拒绝检测意味着驾照马上被收走至少 30 天，DMV 还会再加至少 12 个月。","p":"对。拒绝检测会让你很长时间失去驾照。"},"vi":{"q":"Ở North Carolina, một tài xế bị buộc tội lái xe khi say (impaired driving) từ chối thử hơi thở hoặc thử máu. Bằng lái sẽ ra sao?","o":["Không sao cả, nếu tài xế không say","Một lá thư cảnh cáo từ DMV","Bị phạt tiền, nhưng không mất bằng lái","Bị tước ngay ít nhất 30 ngày, cộng thêm ít nhất 12 tháng từ DMV"],"h1":"Từ chối thử nghiệm bị xem là rất nghiêm trọng.","h2":"Ở North Carolina, từ chối thử nghiệm nghĩa là bằng lái bị tước ngay ít nhất 30 ngày, và DMV cộng thêm ít nhất 12 tháng nữa.","p":"Đúng. Từ chối thử nghiệm khiến bạn mất bằng lái trong thời gian dài."},"tl":{"q":"Sa North Carolina, isang driver na kinasuhan ng impaired driving ang tumanggi sa breath o blood test. Ano ang mangyayari sa lisensya?","o":["Wala, kung hindi lasing ang driver","Isang sulat ng babala mula sa DMV","Multa, pero hindi mawawala ang lisensya","Hindi bababa sa 30 araw agad-agad, at hindi bababa sa 12 buwan pa mula sa DMV"],"h1":"Itinuturing na napakaseryoso ang pagtanggi sa test.","h2":"Sa North Carolina, kapag tumanggi ka sa test, kukunin agad ang lisensya nang hindi bababa sa 30 araw, at magdadagdag pa ang DMV ng hindi bababa sa 12 buwan.","p":"Tama. Ang pagtanggi sa test ay magpapawala ng lisensya mo nang matagal."},"ar":{"q":"في North Carolina، سائق متهم بالقيادة تحت التأثير (impaired driving) يرفض فحص النَّفَس أو الدم. ماذا يحدث للرخصة؟","o":["لا شيء، إذا لم يكن السائق سكرانًا","رسالة تحذير من DMV","غرامة، لكن بدون فقدان الرخصة","30 يومًا على الأقل فورًا، ثم 12 شهرًا على الأقل من DMV"],"h1":"رفض الفحص يُعامَل بجدية كبيرة.","h2":"في North Carolina، رفض الفحص يعني سحب الرخصة فورًا لمدة 30 يومًا على الأقل، ويضيف DMV مدة 12 شهرًا أخرى على الأقل.","p":"صحيح. رفض الفحص يُفقدك رخصتك لمدة طويلة."},"ref":{"doc":"NC","page":31}},{"id":"nc-024","scope":"NC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Carolina, which child must ride in a child safety seat or booster made for their weight?","o":["Only a child under 2","A child under 8 who weighs less than 80 pounds","Any child under 16","Only a child riding in the front seat"],"h1":"Think of both an age and a weight.","h2":"In North Carolina, a child under 8 who weighs less than 80 pounds must ride in a child restraint that fits their weight.","p":"Right. Under 8 and under 80 pounds means a child restraint."},"es":{"q":"En Carolina del Norte, ¿qué niño debe viajar en un asiento de seguridad o elevador adecuado para su peso?","o":["Solo un niño menor de 2 años","Un niño menor de 8 años que pese menos de 80 libras","Cualquier niño menor de 16 años","Solo un niño que viaja en el asiento delantero"],"h1":"Piense en una edad y también en un peso.","h2":"En Carolina del Norte, un niño menor de 8 años que pese menos de 80 libras debe viajar en un sistema de retención infantil adecuado para su peso.","p":"Correcto. Menor de 8 años y de menos de 80 libras significa asiento infantil."},"zh":{"q":"在 North Carolina，哪种孩子必须坐适合其体重的儿童安全座椅或增高座椅？","o":["只有 2 岁以下的孩子","8 岁以下、体重不到 80 磅的孩子","任何 16 岁以下的孩子","只有坐在前座的孩子"],"h1":"同时想一想年龄和体重。","h2":"在 North Carolina，8 岁以下、体重不到 80 磅的孩子必须坐适合其体重的儿童约束装置。","p":"对。8 岁以下并且不到 80 磅，就要用儿童约束装置。"},"vi":{"q":"Ở North Carolina, trẻ nào phải ngồi ghế an toàn trẻ em hoặc ghế nâng (booster) phù hợp với cân nặng của trẻ?","o":["Chỉ trẻ dưới 2 tuổi","Trẻ dưới 8 tuổi và nặng dưới 80 pound","Bất kỳ trẻ nào dưới 16 tuổi","Chỉ trẻ ngồi ở ghế trước"],"h1":"Hãy nghĩ đến cả tuổi và cân nặng.","h2":"Ở North Carolina, trẻ dưới 8 tuổi và nặng dưới 80 pound phải ngồi trong thiết bị giữ an toàn trẻ em phù hợp với cân nặng của trẻ.","p":"Đúng. Dưới 8 tuổi và dưới 80 pound thì phải dùng thiết bị giữ an toàn trẻ em."},"tl":{"q":"Sa North Carolina, aling bata ang dapat nakaupo sa child safety seat o booster na ginawa para sa kanyang timbang?","o":["Bata lang na wala pang 2 taon","Batang wala pang 8 taon na mas magaan sa 80 pounds","Kahit sinong batang wala pang 16 taon","Bata lang na nakaupo sa harapang upuan"],"h1":"Isipin ang edad at ang timbang.","h2":"Sa North Carolina, ang batang wala pang 8 taon na mas magaan sa 80 pounds ay dapat nakaupo sa child restraint na angkop sa kanyang timbang.","p":"Tama. Wala pang 8 taon at wala pang 80 pounds ay nangangailangan ng child restraint."},"ar":{"q":"في North Carolina، أيّ طفل يجب أن يجلس في مقعد أمان للأطفال أو مقعد رافع (booster) مناسب لوزنه؟","o":["الطفل دون سن 2 فقط","الطفل دون سن 8 الذي يزن أقل من 80 رطلًا","أي طفل دون سن 16","الطفل الذي يجلس في المقعد الأمامي فقط"],"h1":"فكّر في العمر والوزن معًا.","h2":"في North Carolina، الطفل دون سن 8 الذي يزن أقل من 80 رطلًا يجب أن يجلس في مقعد أمان للأطفال يناسب وزنه.","p":"صحيح. دون 8 سنوات وأقل من 80 رطلًا يعني مقعد أمان للأطفال."},"ref":{"doc":"NC","page":44}},{"id":"nc-025","scope":"NC","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In North Carolina, what is the speed limit in cities and towns when no sign shows a different limit?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"It is 20 mph lower than the limit outside cities and towns.","h2":"In North Carolina, the speed limit in cities and towns is 35 mph unless a sign says otherwise.","p":"Right. In cities and towns it is 35 mph unless posted."},"es":{"q":"En Carolina del Norte, ¿cuál es el límite de velocidad en ciudades y pueblos cuando ninguna señal indica otro límite?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"Es 20 mph menos que el límite fuera de las ciudades y pueblos.","h2":"En Carolina del Norte, el límite de velocidad en ciudades y pueblos es de 35 mph, a menos que una señal indique otra cosa.","p":"Correcto. En ciudades y pueblos es de 35 mph si no hay señal."},"zh":{"q":"在 North Carolina，如果没有标志显示其他限速，城市和镇里的限速是多少？","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"它比城市和镇以外的限速低 20 mph。","h2":"在 North Carolina，除非有标志另外规定，城市和镇里的限速是 35 mph。","p":"对。除非有标志，城市和镇里是 35 mph。"},"vi":{"q":"Ở North Carolina, tốc độ tối đa trong thành phố và thị trấn là bao nhiêu khi không có biển báo nào ghi giới hạn khác?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"Nó thấp hơn 20 mph so với giới hạn bên ngoài thành phố và thị trấn.","h2":"Ở North Carolina, tốc độ tối đa trong thành phố và thị trấn là 35 mph, trừ khi có biển báo ghi khác.","p":"Đúng. Trong thành phố và thị trấn là 35 mph nếu không có biển báo."},"tl":{"q":"Sa North Carolina, ano ang speed limit sa mga lungsod at bayan kapag walang karatula na nagpapakita ng ibang limit?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"Mas mababa ito nang 20 mph kaysa sa limit sa labas ng mga lungsod at bayan.","h2":"Sa North Carolina, 35 mph ang speed limit sa mga lungsod at bayan maliban kung iba ang sinasabi ng karatula.","p":"Tama. Sa mga lungsod at bayan, 35 mph ito maliban kung may karatula."},"ar":{"q":"في North Carolina، ما حدّ السرعة في المدن والبلدات عندما لا توجد لافتة تُظهر حدًّا مختلفًا؟","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"هو أقل بـ 20 mph من الحدّ خارج المدن والبلدات.","h2":"في North Carolina، حدّ السرعة في المدن والبلدات هو 35 mph إلا إذا قالت لافتة غير ذلك.","p":"صحيح. في المدن والبلدات هو 35 mph ما لم توجد لافتة."},"ref":{"doc":"NC","page":53}},{"id":"nc-026","scope":"NC","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In North Carolina, you turn on your windshield wipers because it is raining. What else must you turn on?","o":["Your headlights","Your hazard lights","Your fog lights only","Your interior light"],"h1":"These lights help other drivers see you in bad weather.","h2":"In North Carolina, you must turn on your headlights whenever you use your wipers because of bad weather.","p":"Right. Wipers on for weather means headlights on."},"es":{"q":"En Carolina del Norte, usted enciende los limpiaparabrisas porque está lloviendo. ¿Qué más debe encender?","o":["Las luces delanteras","Las luces de emergencia","Solo las luces antiniebla","La luz interior"],"h1":"Estas luces ayudan a que otros conductores lo vean con mal tiempo.","h2":"En Carolina del Norte, usted debe encender las luces delanteras siempre que use los limpiaparabrisas por mal tiempo.","p":"Correcto. Limpiaparabrisas por mal tiempo significa luces encendidas."},"zh":{"q":"在 North Carolina，因为下雨你打开了雨刷。你还必须打开什么？","o":["你的大灯","你的危险警示灯","只开你的雾灯","你的车内灯"],"h1":"这些灯能帮助其他驾驶人在坏天气里看到你。","h2":"在 North Carolina，只要因为坏天气使用雨刷，你就必须打开大灯。","p":"对。因为天气开雨刷，就要开大灯。"},"vi":{"q":"Ở North Carolina, bạn bật cần gạt nước vì trời mưa. Bạn còn phải bật gì nữa?","o":["Đèn pha của bạn","Đèn cảnh báo nguy hiểm của bạn","Chỉ đèn sương mù của bạn","Đèn trong xe của bạn"],"h1":"Những đèn này giúp các tài xế khác nhìn thấy bạn khi thời tiết xấu.","h2":"Ở North Carolina, bạn phải bật đèn pha bất cứ khi nào bạn dùng cần gạt nước vì thời tiết xấu.","p":"Đúng. Bật gạt nước vì thời tiết thì phải bật đèn pha."},"tl":{"q":"Sa North Carolina, binuksan mo ang windshield wipers dahil umuulan. Ano pa ang dapat mong buksan?","o":["Ang headlights mo","Ang hazard lights mo","Ang fog lights mo lang","Ang ilaw sa loob ng sasakyan"],"h1":"Tumutulong ang mga ilaw na ito para makita ka ng ibang driver kapag masama ang panahon.","h2":"Sa North Carolina, dapat mong buksan ang headlights mo tuwing gagamit ka ng wipers dahil sa masamang panahon.","p":"Tama. Kapag bukas ang wipers dahil sa panahon, bukas din ang headlights."},"ar":{"q":"في North Carolina، شغّلت مسّاحات الزجاج الأمامي لأن المطر ينزل. ماذا يجب أن تشغّل أيضًا؟","o":["المصابيح الأمامية","أضواء التحذير (الطوارئ)","مصابيح الضباب فقط","الضوء الداخلي للسيارة"],"h1":"هذه الأضواء تساعد السائقين الآخرين على رؤيتك في الطقس السيئ.","h2":"في North Carolina، يجب أن تشغّل المصابيح الأمامية كلما استخدمت المسّاحات بسبب الطقس السيئ.","p":"صحيح. المسّاحات بسبب الطقس تعني تشغيل المصابيح الأمامية."},"ref":{"doc":"NC","page":73}},{"id":"nc-027","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, no one is hurt in a crash. When must you report it to the police right away?","o":["Only if a car must be towed","When the damage looks like $1,000 or more","Only if the other driver asks you to","When the damage looks like $500 or more"],"h1":"It depends on how much the damage seems to cost.","h2":"In North Carolina, you must report a crash to the police right away if anyone is hurt or killed, or if the damage looks like $1,000 or more.","p":"Right. Damage of about $1,000 or more must be reported."},"es":{"q":"En Carolina del Norte, nadie resulta herido en un choque. ¿Cuándo debe reportarlo a la policía de inmediato?","o":["Solo si hay que remolcar un auto","Cuando el daño parece ser de $1,000 o más","Solo si el otro conductor se lo pide","Cuando el daño parece ser de $500 o más"],"h1":"Depende de cuánto parece costar el daño.","h2":"En Carolina del Norte, debe reportar un choque a la policía de inmediato si alguien resulta herido o muerto, o si el daño parece ser de $1,000 o más.","p":"Correcto. Un daño de unos $1,000 o más se debe reportar."},"zh":{"q":"在 North Carolina，一次车祸中没有人受伤。什么时候必须马上向警察报告？","o":["只有当车必须被拖走时","当损坏看起来有 $1,000 或以上时","只有当另一位司机要求你报告时","当损坏看起来有 $500 或以上时"],"h1":"这要看损坏看起来值多少钱。","h2":"在 North Carolina，如果有人受伤或死亡，或者损坏看起来有 $1,000 或以上，你必须马上向警察报告车祸。","p":"对。大约 $1,000 或以上的损坏必须报告。"},"vi":{"q":"Ở North Carolina, không ai bị thương trong một vụ tai nạn. Khi nào bạn phải báo cho cảnh sát ngay?","o":["Chỉ khi phải kéo một chiếc xe đi","Khi thiệt hại trông có vẻ từ $1,000 trở lên","Chỉ khi tài xế kia yêu cầu bạn","Khi thiệt hại trông có vẻ từ $500 trở lên"],"h1":"Điều đó tùy vào thiệt hại trông có vẻ tốn bao nhiêu tiền.","h2":"Ở North Carolina, bạn phải báo tai nạn cho cảnh sát ngay nếu có người bị thương hoặc chết, hoặc nếu thiệt hại trông có vẻ từ $1,000 trở lên.","p":"Đúng. Thiệt hại khoảng $1,000 trở lên phải được báo."},"tl":{"q":"Sa North Carolina, walang nasaktan sa isang banggaan. Kailan mo ito dapat i-report agad sa pulis?","o":["Kung kailangan lang hilahin ang isang kotse","Kapag mukhang $1,000 o higit pa ang pinsala","Kung hilingin lang ito ng kabilang driver","Kapag mukhang $500 o higit pa ang pinsala"],"h1":"Nakadepende ito sa kung magkano ang mukhang halaga ng pinsala.","h2":"Sa North Carolina, dapat mong i-report agad sa pulis ang banggaan kung may nasaktan o namatay, o kung mukhang $1,000 o higit pa ang pinsala.","p":"Tama. Dapat i-report ang pinsalang mga $1,000 o higit pa."},"ar":{"q":"في North Carolina، لم يُصب أحد في حادث. متى يجب أن تبلّغ الشرطة عنه فورًا؟","o":["فقط إذا كان يجب سحب سيارة","عندما يبدو أن الضرر $1,000 أو أكثر","فقط إذا طلب منك السائق الآخر ذلك","عندما يبدو أن الضرر $500 أو أكثر"],"h1":"يعتمد ذلك على كم تبدو تكلفة الضرر.","h2":"في North Carolina، يجب أن تبلّغ الشرطة عن الحادث فورًا إذا أُصيب أحد أو مات، أو إذا بدا أن الضرر $1,000 أو أكثر.","p":"صحيح. يجب التبليغ عن ضرر بحوالي $1,000 أو أكثر."},"ref":{"doc":"NC","page":78}},{"id":"nc-028","scope":"NC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Carolina, besides from sunset to sunrise, when does the law require headlights?","o":["When you can see only 400 feet or less","Only when it is snowing","Whenever you drive over 55 mph","Only on interstate highways"],"h1":"Think about how far ahead you can see.","h2":"In North Carolina, the law requires headlights from sunset to sunrise and whenever you can see only 400 feet or less.","p":"Right. Use headlights when you can see 400 feet or less."},"es":{"q":"En Carolina del Norte, además de la puesta a la salida del sol, ¿cuándo exige la ley usar los faros?","o":["Cuando solo puede ver 400 pies o menos","Solo cuando está nevando","Siempre que maneje a más de 55 mph","Solo en las autopistas interestatales"],"h1":"Piense en qué tan lejos puede ver hacia adelante.","h2":"En Carolina del Norte, la ley exige los faros desde la puesta hasta la salida del sol y siempre que solo pueda ver 400 pies o menos.","p":"Correcto. Use los faros cuando vea 400 pies o menos."},"zh":{"q":"在 North Carolina，除了日落到日出这段时间，法律还要求在什么时候开大灯？","o":["你只能看清 400 英尺或更近的时候","只在下雪的时候","每次车速超过 55 mph 的时候","只在州际公路上"],"h1":"想一想你能看清前面多远。","h2":"在 North Carolina，法律要求从日落到日出要开大灯，而且只要你只能看清 400 英尺或更近，也要开大灯。","p":"对。只能看清 400 英尺或更近时，要开大灯。"},"vi":{"q":"Ở North Carolina, ngoài thời gian từ lúc mặt trời lặn đến lúc mặt trời mọc, luật còn bắt buộc bật đèn pha khi nào?","o":["Khi bạn chỉ nhìn thấy được 400 feet hoặc ít hơn","Chỉ khi trời có tuyết","Bất cứ khi nào bạn lái nhanh hơn 55 mph","Chỉ trên xa lộ liên bang"],"h1":"Hãy nghĩ xem bạn nhìn thấy được bao xa phía trước.","h2":"Ở North Carolina, luật bắt buộc bật đèn pha từ lúc mặt trời lặn đến lúc mặt trời mọc và bất cứ khi nào bạn chỉ nhìn thấy được 400 feet hoặc ít hơn.","p":"Đúng. Hãy bật đèn pha khi bạn chỉ nhìn thấy được 400 feet hoặc ít hơn."},"tl":{"q":"Sa North Carolina, bukod sa mula paglubog hanggang pagsikat ng araw, kailan pa iniuutos ng batas ang headlights?","o":["Kapag 400 feet o mas maikli lang ang nakikita mo","Kapag umuulan lang ng niyebe","Tuwing nagmamaneho ka nang lampas 55 mph","Sa mga interstate highway lang"],"h1":"Isipin kung gaano kalayo ang nakikita mo sa unahan.","h2":"Sa North Carolina, iniuutos ng batas ang headlights mula paglubog hanggang pagsikat ng araw at tuwing 400 feet o mas maikli lang ang nakikita mo.","p":"Tama. Gamitin ang headlights kapag 400 feet o mas maikli lang ang nakikita mo."},"ar":{"q":"في North Carolina، إضافة إلى الوقت من غروب الشمس حتى شروقها، متى يفرض القانون تشغيل الأضواء الأمامية؟","o":["عندما لا ترى إلا مسافة 400 feet أو أقل","فقط عندما يتساقط الثلج","كلما قدت بسرعة أكثر من 55 mph","فقط على الطرق السريعة بين الولايات"],"h1":"فكّر في المسافة التي تستطيع أن تراها أمامك.","h2":"في North Carolina، يفرض القانون تشغيل الأضواء الأمامية من غروب الشمس حتى شروقها، وكلما كنت لا ترى إلا مسافة 400 feet أو أقل.","p":"صحيح. شغّل الأضواء الأمامية عندما لا ترى إلا 400 feet أو أقل."},"ref":{"doc":"NC","page":71}},{"id":"nc-029","scope":"NC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In North Carolina, when you pass another vehicle, how far to its left must you stay?","o":["At least 1 foot","At least 2 feet","At least 5 feet","At least 10 feet"],"h1":"It is a short distance, but more than one foot.","h2":"In North Carolina, the law requires you to pass at least 2 feet to the left of the vehicle you are passing.","p":"Right. Leave at least 2 feet when you pass."},"es":{"q":"En Carolina del Norte, cuando rebasa a otro vehículo, ¿a qué distancia a su izquierda debe pasar?","o":["Al menos 1 pie","Al menos 2 pies","Al menos 5 pies","Al menos 10 pies"],"h1":"Es una distancia corta, pero de más de un pie.","h2":"En Carolina del Norte, la ley exige pasar al menos a 2 pies a la izquierda del vehículo que rebasa.","p":"Correcto. Deje al menos 2 pies al rebasar."},"zh":{"q":"在 North Carolina，超过另一辆车时，你必须在它左边保持多远的距离？","o":["至少 1 英尺","至少 2 英尺","至少 5 英尺","至少 10 英尺"],"h1":"距离很短，但比 1 英尺多。","h2":"在 North Carolina，法律要求你超车时，要在被超车辆的左边至少 2 英尺的地方经过。","p":"对。超车时至少留出 2 英尺。"},"vi":{"q":"Ở North Carolina, khi bạn vượt một xe khác, bạn phải cách bên trái xe đó bao xa?","o":["Ít nhất 1 feet","Ít nhất 2 feet","Ít nhất 5 feet","Ít nhất 10 feet"],"h1":"Đó là một khoảng cách ngắn, nhưng hơn 1 feet.","h2":"Ở North Carolina, luật bắt buộc bạn vượt qua cách bên trái xe mà bạn đang vượt ít nhất 2 feet.","p":"Đúng. Hãy chừa ít nhất 2 feet khi bạn vượt xe."},"tl":{"q":"Sa North Carolina, kapag nag-overtake ka sa ibang sasakyan, gaano kalayo sa kaliwa nito ang dapat mong panatilihin?","o":["Hindi bababa sa 1 foot","Hindi bababa sa 2 feet","Hindi bababa sa 5 feet","Hindi bababa sa 10 feet"],"h1":"Maikling layo ito, pero higit sa 1 foot.","h2":"Sa North Carolina, iniuutos ng batas na dumaan ka nang hindi bababa sa 2 feet sa kaliwa ng sasakyang inoovertake mo.","p":"Tama. Mag-iwan ng hindi bababa sa 2 feet kapag nag-overtake ka."},"ar":{"q":"في North Carolina، عندما تتجاوز مركبة أخرى، كم يجب أن تبتعد إلى يسارها؟","o":["1 foot على الأقل","2 feet على الأقل","5 feet على الأقل","10 feet على الأقل"],"h1":"هي مسافة قصيرة، لكنها أكثر من 1 foot.","h2":"في North Carolina، يفرض القانون أن تمرّ على بُعد 2 feet على الأقل إلى يسار المركبة التي تتجاوزها.","p":"صحيح. اترك 2 feet على الأقل عندما تتجاوز."},"ref":{"doc":"NC","page":55}},{"id":"nc-030","scope":"NC","cat":"signals","sign":null,"c":3,"en":{"q":"In North Carolina, the speed limit is 45 mph or more. How far before a turn must you start to signal?","o":["At least 50 feet","At least 100 feet","At least 150 feet","At least 200 feet"],"h1":"On slower roads it is 100 feet. On faster roads it is more.","h2":"In North Carolina, when the speed limit is 45 mph or more, you must signal at least the last 200 feet before you turn.","p":"Right. On faster roads, signal at least 200 feet ahead."},"es":{"q":"En Carolina del Norte, el límite de velocidad es de 45 mph o más. ¿Con cuánta anticipación debe señalar antes de girar?","o":["Al menos 50 pies","Al menos 100 pies","Al menos 150 pies","Al menos 200 pies"],"h1":"En calles más lentas son 100 pies. En vías más rápidas es más.","h2":"En Carolina del Norte, cuando el límite es de 45 mph o más, debe señalar al menos en los últimos 200 pies antes de girar.","p":"Correcto. En vías rápidas, señale al menos 200 pies antes."},"zh":{"q":"在 North Carolina，限速是 45 mph 或更高。转弯前你必须在多远的地方开始打转向灯？","o":["至少 50 英尺","至少 100 英尺","至少 150 英尺","至少 200 英尺"],"h1":"在慢一点的路上是 100 英尺。在快一点的路上要更多。","h2":"在 North Carolina，限速是 45 mph 或更高时，你必须在转弯前至少最后 200 英尺就打转向灯。","p":"对。在快一点的路上，至少提前 200 英尺打灯。"},"vi":{"q":"Ở North Carolina, tốc độ tối đa là 45 mph hoặc cao hơn. Bạn phải bắt đầu bật đèn xi nhan cách chỗ rẽ bao xa?","o":["Ít nhất 50 feet","Ít nhất 100 feet","Ít nhất 150 feet","Ít nhất 200 feet"],"h1":"Trên đường chậm hơn là 100 feet. Trên đường nhanh hơn thì nhiều hơn.","h2":"Ở North Carolina, khi tốc độ tối đa là 45 mph hoặc cao hơn, bạn phải bật đèn xi nhan ít nhất trong 200 feet cuối cùng trước khi rẽ.","p":"Đúng. Trên đường nhanh hơn, hãy bật đèn xi nhan trước ít nhất 200 feet."},"tl":{"q":"Sa North Carolina, 45 mph o higit pa ang speed limit. Gaano kalayo bago lumiko ka dapat magsimulang mag-signal?","o":["Hindi bababa sa 50 feet","Hindi bababa sa 100 feet","Hindi bababa sa 150 feet","Hindi bababa sa 200 feet"],"h1":"Sa mas mabagal na daan, 100 feet ito. Sa mas mabilis na daan, mas malayo.","h2":"Sa North Carolina, kapag 45 mph o higit pa ang speed limit, dapat kang mag-signal nang hindi bababa sa huling 200 feet bago ka lumiko.","p":"Tama. Sa mas mabilis na daan, mag-signal nang hindi bababa sa 200 feet bago lumiko."},"ar":{"q":"في North Carolina، حدّ السرعة 45 mph أو أكثر. على أي مسافة قبل المنعطف يجب أن تبدأ بإعطاء الإشارة؟","o":["50 feet على الأقل","100 feet على الأقل","150 feet على الأقل","200 feet على الأقل"],"h1":"على الطرق الأبطأ هي 100 feet. وعلى الطرق الأسرع هي أكثر.","h2":"في North Carolina، عندما يكون حدّ السرعة 45 mph أو أكثر، يجب أن تعطي الإشارة على الأقل في آخر 200 feet قبل أن تنعطف.","p":"صحيح. على الطرق الأسرع، أعطِ الإشارة قبل 200 feet على الأقل."},"ref":{"doc":"NC","page":69}},{"id":"nc-031","scope":"NC","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In North Carolina, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 15 feet","No closer than 30 feet"],"h1":"The same distance applies to the entrance of a fire station.","h2":"In North Carolina, you may not park within 15 feet of a fire hydrant or the entrance to a fire station.","p":"Right. Stay at least 15 feet from a hydrant."},"es":{"q":"En Carolina del Norte, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No a menos de 5 pies","No a menos de 10 pies","No a menos de 15 pies","No a menos de 30 pies"],"h1":"La misma distancia se aplica a la entrada de una estación de bomberos.","h2":"En Carolina del Norte, no puede estacionarse a menos de 15 pies de un hidrante o de la entrada de una estación de bomberos.","p":"Correcto. Quédese al menos a 15 pies de un hidrante."},"zh":{"q":"在 North Carolina，你可以把车停在离消防栓多近的地方？","o":["不能近于 5 英尺","不能近于 10 英尺","不能近于 15 英尺","不能近于 30 英尺"],"h1":"消防站的入口也是同样的距离。","h2":"在 North Carolina，你不可以把车停在离消防栓或消防站入口 15 英尺以内的地方。","p":"对。停车时离消防栓至少 15 英尺。"},"vi":{"q":"Ở North Carolina, bạn được đậu xe gần trụ nước cứu hỏa đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 15 feet","Không gần hơn 30 feet"],"h1":"Khoảng cách này cũng áp dụng cho lối vào của trạm cứu hỏa.","h2":"Ở North Carolina, bạn không được đậu xe trong vòng 15 feet tính từ trụ nước cứu hỏa hoặc lối vào trạm cứu hỏa.","p":"Đúng. Hãy đậu xe cách trụ nước cứu hỏa ít nhất 15 feet."},"tl":{"q":"Sa North Carolina, gaano kalapit sa fire hydrant ka puwedeng pumarada?","o":["Hindi lalapit sa 5 feet","Hindi lalapit sa 10 feet","Hindi lalapit sa 15 feet","Hindi lalapit sa 30 feet"],"h1":"Pareho rin ang layo para sa pasukan ng fire station.","h2":"Sa North Carolina, hindi ka puwedeng pumarada sa loob ng 15 feet mula sa fire hydrant o sa pasukan ng fire station.","p":"Tama. Lumayo nang hindi bababa sa 15 feet mula sa hydrant."},"ar":{"q":"في North Carolina، كم يمكنك أن تقترب من صنبور إطفاء الحريق عندما توقف سيارتك؟","o":["ليس أقرب من 5 feet","ليس أقرب من 10 feet","ليس أقرب من 15 feet","ليس أقرب من 30 feet"],"h1":"المسافة نفسها تنطبق على مدخل محطة الإطفاء.","h2":"في North Carolina، لا يجوز لك أن توقف سيارتك على بُعد أقل من 15 feet من صنبور إطفاء الحريق أو من مدخل محطة الإطفاء.","p":"صحيح. ابقَ على بُعد 15 feet على الأقل من صنبور الإطفاء."},"ref":{"doc":"NC","page":56}},{"id":"nc-032","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, how many driver license points can get you sent to a driver improvement clinic?","o":["3 points","7 points","5 points","12 points"],"h1":"It is fewer points than the number that can lead to a suspension.","h2":"In North Carolina, a driver with 7 points may be sent to a driver improvement clinic, and finishing it takes 3 points off the record.","p":"Right. At 7 points you may be sent to a driver improvement clinic."},"es":{"q":"En Carolina del Norte, ¿con cuántos puntos en la licencia lo pueden mandar a una clínica para mejorar como conductor?","o":["3 puntos","7 puntos","5 puntos","12 puntos"],"h1":"Son menos puntos que el número que puede llevar a una suspensión.","h2":"En Carolina del Norte, a un conductor con 7 puntos lo pueden mandar a una clínica para mejorar como conductor, y terminarla le quita 3 puntos del historial.","p":"Correcto. Con 7 puntos lo pueden mandar a una clínica para mejorar como conductor."},"ref":{"doc":"NC","page":34}},{"id":"nc-033","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, your license is suspended for points for the first time. How long may it be taken?","o":["30 days","6 months","12 months","60 days"],"h1":"It is longer than one month, and later suspensions are longer still.","h2":"In North Carolina, a first suspension for points may last 60 days; a second may last 6 months and a third 12 months.","p":"Right. A first points suspension may last 60 days."},"es":{"q":"En Carolina del Norte, su licencia es suspendida por puntos por primera vez. ¿Por cuánto tiempo se la pueden quitar?","o":["30 días","6 meses","12 meses","60 días"],"h1":"Es más de un mes, y las suspensiones siguientes son aún más largas.","h2":"En Carolina del Norte, una primera suspensión por puntos puede durar 60 días; la segunda puede durar 6 meses y la tercera 12 meses.","p":"Correcto. Una primera suspensión por puntos puede durar 60 días."},"ref":{"doc":"NC","page":34}},{"id":"nc-034","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, a driver under 18 is convicted of a second moving violation within 12 months. How long may the license be suspended?","o":["30 days","90 days","6 months","1 year"],"h1":"It is the shortest of the suspensions for young drivers; more violations bring longer ones.","h2":"In North Carolina, a driver under 18 may lose the license for 30 days after a second moving violation within 12 months; a third brings 90 days and a fourth six months.","p":"Right. A second moving violation within 12 months can mean a 30-day suspension."},"es":{"q":"En Carolina del Norte, un conductor menor de 18 años es declarado culpable de una segunda infracción en movimiento dentro de 12 meses. ¿Por cuánto tiempo pueden suspender su licencia?","o":["30 días","90 días","6 meses","1 año"],"h1":"Es la más corta de las suspensiones para conductores jóvenes; más infracciones traen suspensiones más largas.","h2":"En Carolina del Norte, un conductor menor de 18 años puede perder la licencia por 30 días tras una segunda infracción en movimiento dentro de 12 meses; la tercera trae 90 días y la cuarta seis meses.","p":"Correcto. Una segunda infracción en movimiento dentro de 12 meses puede causar una suspensión de 30 días."},"ref":{"doc":"NC","page":39}},{"id":"nc-035","scope":"NC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Carolina, what happens to the license of a driver convicted of DWI for the first time?","o":["It is revoked for 30 days","It is revoked for 6 months","It is revoked for one year","It is revoked for four years"],"h1":"The 30 days is what happens right after the arrest, not after the conviction.","h2":"In North Carolina, a first DWI conviction brings a mandatory one-year license revocation.","p":"Right. A first DWI conviction means losing the license for one year."},"es":{"q":"En Carolina del Norte, ¿qué le pasa a la licencia de un conductor declarado culpable de DWI (manejar bajo los efectos) por primera vez?","o":["Se revoca por 30 días","Se revoca por 6 meses","Se revoca por un año","Se revoca por cuatro años"],"h1":"Los 30 días son lo que pasa justo después del arresto, no después de la condena.","h2":"En Carolina del Norte, una primera condena por DWI trae la revocación obligatoria de la licencia por un año.","p":"Correcto. Una primera condena por DWI significa perder la licencia por un año."},"ref":{"doc":"NC","page":32}},{"id":"nc-036","scope":"NC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Carolina, a driver is convicted of DWI with a blood alcohol level of 0.15 or more. What must be put in the vehicle?","o":["A GPS tracker","An ignition interlock device","A dashboard camera","A speed limiter"],"h1":"The device checks the driver's breath before the car will start.","h2":"In North Carolina, a DWI conviction with a blood alcohol level of 0.15 or more requires an ignition interlock device in the vehicle.","p":"Right. A 0.15 or higher DWI means an ignition interlock device."},"es":{"q":"En Carolina del Norte, un conductor es declarado culpable de DWI con un nivel de alcohol en la sangre de 0.15 o más. ¿Qué se debe instalar en el vehículo?","o":["Un rastreador GPS","Un dispositivo de bloqueo de encendido (ignition interlock)","Una cámara en el tablero","Un limitador de velocidad"],"h1":"El dispositivo revisa el aliento del conductor antes de que el carro arranque.","h2":"En Carolina del Norte, una condena por DWI con un nivel de alcohol en la sangre de 0.15 o más exige un dispositivo de bloqueo de encendido en el vehículo.","p":"Correcto. Un DWI con 0.15 o más significa un dispositivo de bloqueo de encendido."},"ref":{"doc":"NC","page":32}},{"id":"nc-037","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, you just moved here and became a resident. How soon must you get a North Carolina license?","o":["Within 10 days","Within 30 days","Within 60 days","Within 90 days"],"h1":"It is about two months.","h2":"In North Carolina, a new resident has 60 days after moving here to get a North Carolina license.","p":"Right. New residents have 60 days."},"es":{"q":"En Carolina del Norte, usted acaba de mudarse y ahora es residente. ¿En cuánto tiempo debe sacar una licencia de Carolina del Norte?","o":["Dentro de 10 días","Dentro de 30 días","Dentro de 60 días","Dentro de 90 días"],"h1":"Son unos dos meses.","h2":"En Carolina del Norte, un nuevo residente tiene 60 días después de mudarse para sacar una licencia de Carolina del Norte.","p":"Correcto. Los nuevos residentes tienen 60 días."},"ref":{"doc":"NC","page":25}},{"id":"nc-038","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, you are 30 years old when you get your driver license. How long is it valid?","o":["4 years","5 years","10 years","8 years"],"h1":"Drivers 66 and older get a shorter license than this.","h2":"In North Carolina, a license issued to a driver aged 18 to 65 is valid for 8 years; from age 66 it is valid for 5 years.","p":"Right. Between 18 and 65, a license lasts 8 years."},"es":{"q":"En Carolina del Norte, usted tiene 30 años cuando recibe su licencia de manejar. ¿Por cuánto tiempo es válida?","o":["4 años","5 años","10 años","8 años"],"h1":"Los conductores de 66 años o más reciben una licencia más corta que esta.","h2":"En Carolina del Norte, una licencia dada a un conductor de 18 a 65 años es válida por 8 años; desde los 66 años es válida por 5 años.","p":"Correcto. Entre los 18 y los 65 años, la licencia dura 8 años."},"ref":{"doc":"NC","page":28}},{"id":"nc-039","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, at least how much liability insurance must a car owner carry for injuries to one person in a crash?","o":["$30,000","$10,000","$25,000","$60,000"],"h1":"It is half the amount required for all injuries in one crash.","h2":"In North Carolina, liability insurance must cover at least $30,000 for injuries to one person, $60,000 for all injuries and $25,000 for property damage in a crash.","p":"Right. At least $30,000 for injuries to one person."},"es":{"q":"En Carolina del Norte, ¿cuánto seguro de responsabilidad debe tener como mínimo el dueño de un carro para las lesiones de una persona en un choque?","o":["$30,000","$10,000","$25,000","$60,000"],"h1":"Es la mitad de lo que se exige para todas las lesiones de un choque.","h2":"En Carolina del Norte, el seguro de responsabilidad debe cubrir al menos $30,000 por las lesiones de una persona, $60,000 por todas las lesiones y $25,000 por daños a la propiedad en un choque.","p":"Correcto. Al menos $30,000 por las lesiones de una persona."},"ref":{"doc":"NC","page":99}},{"id":"nc-040","scope":"NC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In North Carolina, outside cities and towns, what is the speed limit when no sign shows a different one?","o":["45 mph","55 mph","65 mph","70 mph"],"h1":"It is 20 mph more than the limit in cities and towns.","h2":"In North Carolina, the speed limit outside cities and towns is 55 mph unless a sign shows a different limit.","p":"Right. Outside cities and towns, the limit is 55 mph unless posted."},"es":{"q":"En Carolina del Norte, fuera de ciudades y pueblos, ¿cuál es el límite de velocidad cuando ningún letrero indica otro?","o":["45 mph","55 mph","65 mph","70 mph"],"h1":"Son 20 mph más que el límite en ciudades y pueblos.","h2":"En Carolina del Norte, el límite de velocidad fuera de ciudades y pueblos es 55 mph, a menos que un letrero indique otro límite.","p":"Correcto. Fuera de ciudades y pueblos, el límite es 55 mph si no hay letrero."},"ref":{"doc":"NC","page":53}},{"id":"nc-041","scope":"NC","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In North Carolina, what is the highest speed a school bus may drive?","o":["35 mph","55 mph","45 mph","65 mph"],"h1":"School activity buses may go faster than this.","h2":"In North Carolina, the maximum speed limit for a school bus is 45 mph.","p":"Right. A school bus may not go over 45 mph."},"es":{"q":"En Carolina del Norte, ¿cuál es la velocidad más alta a la que puede ir un autobús escolar?","o":["35 mph","55 mph","45 mph","65 mph"],"h1":"Los autobuses para actividades escolares pueden ir más rápido que esto.","h2":"En Carolina del Norte, el límite de velocidad máximo para un autobús escolar es 45 mph.","p":"Correcto. Un autobús escolar no puede pasar de 45 mph."},"ref":{"doc":"NC","page":53}},{"id":"nc-042","scope":"NC","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In North Carolina, the street has a curb. How close to the curb line of a crossing street may you park?","o":["No closer than 10 feet","No closer than 15 feet","No closer than 50 feet","No closer than 25 feet"],"h1":"The shorter distance is only for streets with no curb.","h2":"In North Carolina, you may not park within 25 feet of the curb line of a crossing street, or within 15 feet where there is no curb.","p":"Right. Stay at least 25 feet from the curb line of a crossing street."},"es":{"q":"En Carolina del Norte, la calle tiene bordillo. ¿Qué tan cerca de la línea del bordillo de una calle que cruza puede estacionarse?","o":["No a menos de 10 pies","No a menos de 15 pies","No a menos de 50 pies","No a menos de 25 pies"],"h1":"La distancia más corta es solo para calles sin bordillo.","h2":"En Carolina del Norte, no puede estacionarse a menos de 25 pies de la línea del bordillo de una calle que cruza, ni a menos de 15 pies donde no hay bordillo.","p":"Correcto. Quédese al menos a 25 pies de la línea del bordillo de la calle que cruza."},"ref":{"doc":"NC","page":56}},{"id":"nc-043","scope":"NC","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In North Carolina, an emergency vehicle has stopped at a crash to give help. How close to it may you park?","o":["No closer than 100 feet","No closer than 25 feet","No closer than 50 feet","No closer than 500 feet"],"h1":"Think of about six car lengths.","h2":"In North Carolina, you may not park within 100 feet of an emergency vehicle that has stopped at a crash or to give help.","p":"Right. Park no closer than 100 feet."},"es":{"q":"En Carolina del Norte, un vehículo de emergencia se detuvo en un choque para dar ayuda. ¿Qué tan cerca de él puede estacionarse?","o":["No a menos de 100 pies","No a menos de 25 pies","No a menos de 50 pies","No a menos de 500 pies"],"h1":"Piense en unos seis carros en fila.","h2":"En Carolina del Norte, no puede estacionarse a menos de 100 pies de un vehículo de emergencia que se detuvo en un choque o para dar ayuda.","p":"Correcto. No se estacione a menos de 100 pies."},"ref":{"doc":"NC","page":48}},{"id":"nc-044","scope":"NC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Carolina, who must wear a bicycle helmet?","o":["Only riders under 12","All riders and passengers under 16","All riders of any age","Only riders on busy highways"],"h1":"The rule is about age, and it covers passengers too.","h2":"In North Carolina, every bicycle rider and passenger under 16 must wear an approved bicycle helmet.","p":"Right. Riders and passengers under 16 must wear a helmet."},"es":{"q":"En Carolina del Norte, ¿quién debe usar casco en bicicleta?","o":["Solo los ciclistas menores de 12 años","Todos los ciclistas y pasajeros menores de 16 años","Todos los ciclistas de cualquier edad","Solo los ciclistas en carreteras con mucho tráfico"],"h1":"La regla depende de la edad y también incluye a los pasajeros.","h2":"En Carolina del Norte, todo ciclista y pasajero de bicicleta menor de 16 años debe usar un casco aprobado.","p":"Correcto. Los ciclistas y pasajeros menores de 16 años deben usar casco."},"ref":{"doc":"NC","page":90}},{"id":"nc-045","scope":"NC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Carolina, a bicycle is ridden at night. How far away must its front light be seen?","o":["At least 100 feet","At least 200 feet","At least 300 feet","At least 500 feet"],"h1":"It is farther than the rear red light or reflector must be seen.","h2":"In North Carolina, a bicycle ridden at night needs a front light seen from at least 300 feet and a red rear light or reflector seen from at least 200 feet.","p":"Right. The front light must be seen from at least 300 feet."},"es":{"q":"En Carolina del Norte, alguien anda en bicicleta de noche. ¿Desde qué distancia se debe ver su luz delantera?","o":["Al menos 100 pies","Al menos 200 pies","Al menos 300 pies","Al menos 500 pies"],"h1":"Es más lejos que la distancia desde la que se debe ver la luz o el reflector rojo de atrás.","h2":"En Carolina del Norte, una bicicleta de noche necesita una luz delantera que se vea desde al menos 300 pies y una luz o reflector rojo atrás que se vea desde al menos 200 pies.","p":"Correcto. La luz delantera se debe ver desde al menos 300 pies."},"ref":{"doc":"NC","page":90}},{"id":"nc-046","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, how old must you be to ride a moped on a public road?","o":["14 years old","15 years old","18 years old","16 years old"],"h1":"You also need a North Carolina driver license or ID card.","h2":"In North Carolina, you must be at least 16 and have a North Carolina driver license or ID card to ride a moped on a public road.","p":"Right. You must be at least 16 to ride a moped."},"es":{"q":"En Carolina del Norte, ¿qué edad debe tener para manejar un moped en una vía pública?","o":["14 años","15 años","18 años","16 años"],"h1":"También necesita una licencia de manejar o una tarjeta de identificación de Carolina del Norte.","h2":"En Carolina del Norte, debe tener al menos 16 años y una licencia de manejar o tarjeta de identificación de Carolina del Norte para manejar un moped en una vía pública.","p":"Correcto. Debe tener al menos 16 años para manejar un moped."},"ref":{"doc":"NC","page":93}},{"id":"nc-047","scope":"NC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Carolina, as a general rule, who may not ride in the open bed of a pickup truck?","o":["Children under 16","Children under 12","Anyone under 18","Adults over 65"],"h1":"The age is the same as the one for bicycle helmets.","h2":"In North Carolina, children under 16 may not ride in the open bed of a pickup truck, except in a few cases such as when an adult in the bed supervises them.","p":"Right. Children under 16 may not ride in an open truck bed."},"es":{"q":"En Carolina del Norte, como regla general, ¿quién no puede viajar en la caja abierta de una camioneta pickup?","o":["Los niños menores de 16 años","Los niños menores de 12 años","Cualquier persona menor de 18 años","Los adultos mayores de 65 años"],"h1":"La edad es la misma que para el casco de bicicleta.","h2":"En Carolina del Norte, los niños menores de 16 años no pueden viajar en la caja abierta de una camioneta pickup, salvo en algunos casos, como cuando un adulto en la caja los supervisa.","p":"Correcto. Los niños menores de 16 años no pueden viajar en una caja abierta."},"ref":{"doc":"NC","page":45}},{"id":"nc-048","scope":"NC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Carolina, your car has a back seat and a front passenger air bag that is turned on. Which child must ride in the back seat?","o":["A child under 8 who weighs less than 80 pounds","A child under 5 who weighs less than 40 pounds","Any child under 16","A child under 10 who weighs less than 60 pounds"],"h1":"It is a younger, lighter child than the one who needs a booster seat.","h2":"In North Carolina, when the car has an active front passenger air bag and a back seat, a child under 5 who weighs less than 40 pounds must ride in the back seat, unless the child seat is made for use with the air bag.","p":"Right. A child under 5 and under 40 pounds must ride in the back."},"es":{"q":"En Carolina del Norte, su carro tiene asiento trasero y una bolsa de aire del pasajero delantero que está encendida. ¿Qué niño debe ir en el asiento trasero?","o":["Un niño menor de 8 años que pesa menos de 80 libras","Un niño menor de 5 años que pesa menos de 40 libras","Cualquier niño menor de 16 años","Un niño menor de 10 años que pesa menos de 60 libras"],"h1":"Es un niño más pequeño y liviano que el que necesita un asiento elevado.","h2":"En Carolina del Norte, cuando el carro tiene una bolsa de aire delantera del pasajero activa y un asiento trasero, un niño menor de 5 años que pesa menos de 40 libras debe ir atrás, salvo que su asiento esté hecho para usarse con la bolsa de aire.","p":"Correcto. Un niño menor de 5 años y de menos de 40 libras debe ir atrás."},"ref":{"doc":"NC","page":44}},{"id":"nc-049","scope":"NC","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In North Carolina, you are driving the same way as a funeral procession. When may you pass it?","o":["Any time, if you honk first","Whenever it goes slower than 25 mph","Only when the road has two or more lanes going your way","Never, on any road"],"h1":"It depends on how many lanes go in your direction.","h2":"In North Carolina, you may not pass a funeral procession going your way unless the road is marked for two or more lanes in that direction.","p":"Right. Pass only when there are two or more lanes going your way."},"es":{"q":"En Carolina del Norte, usted maneja en la misma dirección que un cortejo fúnebre. ¿Cuándo puede rebasarlo?","o":["En cualquier momento, si toca la bocina primero","Cuando vaya a menos de 25 mph","Solo cuando la vía tiene dos o más carriles en su dirección","Nunca, en ninguna vía"],"h1":"Depende de cuántos carriles van en su dirección.","h2":"En Carolina del Norte, no puede rebasar un cortejo fúnebre que va en su dirección, a menos que la vía tenga marcados dos o más carriles en esa dirección.","p":"Correcto. Rebase solo cuando hay dos o más carriles en su dirección."},"ref":{"doc":"NC","page":52}},{"id":"nc-050","scope":"NC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Carolina, trash is thrown from your car and you are convicted of littering for the first time. What is the lowest fine?","o":["$25","$100","$500","$250"],"h1":"The highest fine for a first offense is $1,000.","h2":"In North Carolina, a first littering conviction carries a fine of at least $250 and up to $1,000, and the driver is held responsible for litter from the vehicle.","p":"Right. The fine starts at $250."},"es":{"q":"En Carolina del Norte, alguien tira basura desde su carro y usted es declarado culpable de tirar basura por primera vez. ¿Cuál es la multa más baja?","o":["$25","$100","$500","$250"],"h1":"La multa más alta para una primera vez es $1,000.","h2":"En Carolina del Norte, una primera condena por tirar basura tiene una multa de al menos $250 y hasta $1,000, y el conductor es responsable de la basura que sale del vehículo.","p":"Correcto. La multa empieza en $250."},"ref":{"doc":"NC","page":95}},{"id":"nd-001","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"North Dakota lets teens start younger than most states.","h2":"In North Dakota you can get an instruction permit at 14 years old.","p":"Right. North Dakota permits start at 14."},"es":{"q":"En Dakota del Norte, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["14 años","15 años","16 años","17 años"],"h1":"Dakota del Norte deja empezar más joven que la mayoría de los estados.","h2":"En Dakota del Norte usted puede obtener un permiso de instrucción a los 14 años.","p":"Correcto. El permiso en Dakota del Norte empieza a los 14."},"zh":{"q":"在 North Dakota，最小几岁可以拿到学习驾照（instruction permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"North Dakota 让青少年比大多数州更早开始。","h2":"在 North Dakota，你 14 岁就可以拿到学习驾照。","p":"对。North Dakota 的学习驾照从 14 岁开始。"},"vi":{"q":"Ở North Dakota, tuổi nhỏ nhất để được cấp giấy phép tập lái (instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"North Dakota cho thanh thiếu niên bắt đầu sớm hơn hầu hết các tiểu bang.","h2":"Ở North Dakota, bạn có thể được cấp giấy phép tập lái khi đủ 14 tuổi.","p":"Đúng. Ở North Dakota, giấy phép tập lái bắt đầu từ 14 tuổi."},"tl":{"q":"Sa North Dakota, ano ang pinakabatang edad para makakuha ng instruction permit (permit sa pag-aaral magmaneho)?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Mas maaga pinapayagang magsimula ng North Dakota ang mga kabataan kaysa sa karamihan ng estado.","h2":"Sa North Dakota, makakakuha ka ng instruction permit sa edad na 14.","p":"Tama. Sa North Dakota, nagsisimula ang permit sa edad na 14."},"ar":{"q":"في North Dakota، ما أصغر عمر للحصول على تصريح التعلّم (instruction permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"تسمح North Dakota للمراهقين بالبدء في عمر أصغر من معظم الولايات.","h2":"في North Dakota يمكنك الحصول على تصريح التعلّم في عمر 14 سنة.","p":"صحيح. يبدأ التصريح في North Dakota من عمر 14 سنة."},"ref":{"doc":"ND","page":3}},{"id":"nd-004","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, how old must the licensed adult with a permit holder be?","o":["At least 16","At least 18","At least 21","At least 25"],"h1":"It is the age when a person becomes a legal adult.","h2":"A North Dakota permit holder must drive with a licensed adult who is at least 18 years old.","p":"Right. The adult with you must be 18 or older."},"es":{"q":"En Dakota del Norte, ¿qué edad debe tener el adulto con licencia que acompaña a quien tiene permiso?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 21","Por lo menos 25"],"h1":"Es la edad en que una persona se vuelve adulta ante la ley.","h2":"Quien tiene un permiso en Dakota del Norte debe manejar con un adulto con licencia de por lo menos 18 años.","p":"Correcto. El adulto que lo acompaña debe tener 18 años o más."},"zh":{"q":"在 North Dakota，陪同持学习驾照的人、有驾照的成年人必须几岁？","o":["至少 16 岁","至少 18 岁","至少 21 岁","至少 25 岁"],"h1":"这是一个人在法律上成年的年龄。","h2":"North Dakota 持学习驾照的人必须和至少 18 岁、有驾照的成年人一起开车。","p":"对。陪你的成年人必须 18 岁或以上。"},"vi":{"q":"Ở North Dakota, người lớn có bằng lái đi cùng người có giấy phép tập lái phải bao nhiêu tuổi?","o":["Ít nhất 16 tuổi","Ít nhất 18 tuổi","Ít nhất 21 tuổi","Ít nhất 25 tuổi"],"h1":"Đó là tuổi một người trở thành người lớn theo luật.","h2":"Ở North Dakota, người có giấy phép tập lái phải lái xe cùng một người lớn có bằng lái, ít nhất 18 tuổi.","p":"Đúng. Người lớn đi cùng bạn phải từ 18 tuổi trở lên."},"tl":{"q":"Sa North Dakota, ilang taon dapat ang adult na may lisensya na kasama ng may hawak ng permit?","o":["Hindi bababa sa 16","Hindi bababa sa 18","Hindi bababa sa 21","Hindi bababa sa 25"],"h1":"Ito ang edad kung kailan nagiging adult ang isang tao ayon sa batas.","h2":"Sa North Dakota, ang may hawak ng permit ay dapat magmaneho kasama ang isang adult na may lisensya na hindi bababa sa 18 taong gulang.","p":"Tama. Ang adult na kasama mo ay dapat 18 o mas matanda."},"ar":{"q":"في North Dakota، كم يجب أن يكون عمر الشخص البالغ الذي يحمل رخصة ويرافق حامل التصريح؟","o":["16 سنة على الأقل","18 سنة على الأقل","21 سنة على الأقل","25 سنة على الأقل"],"h1":"إنه العمر الذي يصبح فيه الشخص بالغاً حسب القانون.","h2":"في North Dakota يجب أن يقود حامل التصريح مع شخص بالغ يحمل رخصة وعمره 18 سنة على الأقل.","p":"صحيح. يجب أن يكون البالغ المرافق لك عمره 18 سنة أو أكثر."},"ref":{"doc":"ND","page":3}},{"id":"nd-005","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, how much driving experience must the adult supervising a permit holder have?","o":["None","6 months","1 year","At least 3 years"],"h1":"It is more than a couple of years.","h2":"The adult supervising a North Dakota permit holder must have at least three years of driving experience.","p":"Right. The helper needs three years of experience."},"es":{"q":"En Dakota del Norte, ¿cuánta experiencia de manejo debe tener el adulto que supervisa a quien tiene permiso?","o":["Ninguna","6 meses","1 año","Por lo menos 3 años"],"h1":"Es más de un par de años.","h2":"El adulto que supervisa a quien tiene permiso en Dakota del Norte debe tener por lo menos tres años de experiencia manejando.","p":"Correcto. El acompañante necesita tres años de experiencia."},"zh":{"q":"在 North Dakota，陪同持学习驾照的人的成年人必须有多少开车经验？","o":["不需要","6 个月","1 年","至少 3 年"],"h1":"比两年多一点。","h2":"陪同 North Dakota 持学习驾照的人的成年人必须有至少三年的开车经验。","p":"对。陪同的人需要三年的经验。"},"vi":{"q":"Ở North Dakota, người lớn giám sát người có giấy phép tập lái phải có bao nhiêu kinh nghiệm lái xe?","o":["Không cần","6 tháng","1 năm","Ít nhất 3 năm"],"h1":"Nhiều hơn vài năm.","h2":"Ở North Dakota, người lớn giám sát người có giấy phép tập lái phải có ít nhất ba năm kinh nghiệm lái xe.","p":"Đúng. Người đi cùng cần có ba năm kinh nghiệm."},"tl":{"q":"Sa North Dakota, gaano karaming karanasan sa pagmamaneho ang dapat mayroon ang adult na nagbabantay sa may hawak ng permit?","o":["Wala","6 na buwan","1 taon","Hindi bababa sa 3 taon"],"h1":"Higit ito sa dalawang taon.","h2":"Sa North Dakota, ang adult na nagbabantay sa may hawak ng permit ay dapat may hindi bababa sa tatlong taon na karanasan sa pagmamaneho.","p":"Tama. Kailangan ng kasama ang tatlong taon na karanasan."},"ar":{"q":"في North Dakota، ما مقدار خبرة القيادة التي يجب أن تكون لدى البالغ الذي يشرف على حامل التصريح؟","o":["لا شيء","6 أشهر","سنة واحدة","3 سنوات على الأقل"],"h1":"إنها أكثر من سنتين.","h2":"في North Dakota يجب أن تكون لدى البالغ الذي يشرف على حامل التصريح خبرة قيادة لا تقل عن ثلاث سنوات.","p":"صحيح. يحتاج المرافق إلى خبرة ثلاث سنوات."},"ref":{"doc":"ND","page":3}},{"id":"nd-006","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, a teen gets an instruction permit at 14. How long must they hold it before the road test?","o":["30 days","3 months","1 year","2 years"],"h1":"It is a full trip around the calendar.","h2":"A 14-year-old in North Dakota must hold the instruction permit for 12 months, which is one year, before the road test.","p":"Right. At 14, you hold the permit for one year."},"es":{"q":"En Dakota del Norte, un adolescente obtiene el permiso de instrucción a los 14 años. ¿Cuánto tiempo debe tenerlo antes del examen de manejo?","o":["30 días","3 meses","1 año","2 años"],"h1":"Es una vuelta completa al calendario.","h2":"Un joven de 14 años en Dakota del Norte debe tener el permiso de instrucción por 12 meses, es decir un año, antes del examen de manejo.","p":"Correcto. A los 14, tiene el permiso por un año."},"zh":{"q":"在 North Dakota，一个青少年 14 岁拿到学习驾照。他必须持有多久才能路考？","o":["30 天","3 个月","1 年","2 年"],"h1":"是日历上完整的一圈。","h2":"North Dakota 14 岁的人必须持有学习驾照 12 个月，也就是一年，才能路考。","p":"对。14 岁时，学习驾照要持有一年。"},"vi":{"q":"Ở North Dakota, một thiếu niên được cấp giấy phép tập lái khi 14 tuổi. Người đó phải giữ giấy phép bao lâu trước khi thi lái xe trên đường?","o":["30 ngày","3 tháng","1 năm","2 năm"],"h1":"Đó là trọn một vòng lịch.","h2":"Ở North Dakota, người 14 tuổi phải giữ giấy phép tập lái 12 tháng, tức là một năm, trước khi thi lái xe trên đường.","p":"Đúng. Khi 14 tuổi, bạn giữ giấy phép trong một năm."},"tl":{"q":"Sa North Dakota, nakakuha ng instruction permit ang isang kabataan sa edad na 14. Gaano katagal niya ito dapat hawak bago ang road test?","o":["30 araw","3 buwan","1 taon","2 taon"],"h1":"Ito ay isang buong ikot ng kalendaryo.","h2":"Sa North Dakota, ang 14 taong gulang ay dapat humawak ng instruction permit nang 12 buwan, o isang taon, bago ang road test.","p":"Tama. Sa edad na 14, hawak mo ang permit nang isang taon."},"ar":{"q":"في North Dakota، حصل مراهق على تصريح التعلّم في عمر 14 سنة. كم مدة يجب أن يحمله قبل اختبار القيادة على الطريق؟","o":["30 يوماً","3 أشهر","سنة واحدة","سنتان"],"h1":"إنها دورة كاملة في التقويم.","h2":"في North Dakota يجب على من عمره 14 سنة أن يحمل تصريح التعلّم 12 شهراً، أي سنة واحدة، قبل اختبار القيادة على الطريق.","p":"صحيح. في عمر 14 سنة تحمل التصريح لمدة سنة واحدة."},"ref":{"doc":"ND","page":3}},{"id":"nd-007","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, how long must a 16-year-old hold an instruction permit before a license?","o":["6 months","1 month","1 year","18 months"],"h1":"It is half as long as the rule for younger teens.","h2":"A 16-year-old in North Dakota must hold the instruction permit for six months before getting a license.","p":"Right. At 16, the wait is six months."},"es":{"q":"En Dakota del Norte, ¿cuánto tiempo debe tener el permiso de instrucción una persona de 16 años antes de la licencia?","o":["6 meses","1 mes","1 año","18 meses"],"h1":"Es la mitad del tiempo que deben esperar los más jóvenes.","h2":"Una persona de 16 años en Dakota del Norte debe tener el permiso de instrucción seis meses antes de obtener la licencia.","p":"Correcto. A los 16, la espera es de seis meses."},"zh":{"q":"在 North Dakota，16 岁的人必须持有学习驾照多久才能拿驾照？","o":["6 个月","1 个月","1 年","18 个月"],"h1":"它是年龄小一点的青少年规定时间的一半。","h2":"North Dakota 16 岁的人必须持有学习驾照六个月，才能拿到驾照。","p":"对。16 岁时，要等六个月。"},"vi":{"q":"Ở North Dakota, người 16 tuổi phải giữ giấy phép tập lái bao lâu trước khi được cấp bằng lái?","o":["6 tháng","1 tháng","1 năm","18 tháng"],"h1":"Chỉ bằng một nửa thời gian quy định cho thiếu niên nhỏ tuổi hơn.","h2":"Ở North Dakota, người 16 tuổi phải giữ giấy phép tập lái sáu tháng trước khi được cấp bằng lái.","p":"Đúng. Khi 16 tuổi, thời gian chờ là sáu tháng."},"tl":{"q":"Sa North Dakota, gaano katagal dapat hawak ng 16 taong gulang ang instruction permit bago makakuha ng lisensya?","o":["6 na buwan","1 buwan","1 taon","18 buwan"],"h1":"Kalahati ito ng haba ng patakaran para sa mas batang kabataan.","h2":"Sa North Dakota, ang 16 taong gulang ay dapat humawak ng instruction permit nang anim na buwan bago makakuha ng lisensya.","p":"Tama. Sa edad na 16, anim na buwan ang paghihintay."},"ar":{"q":"في North Dakota، كم مدة يجب أن يحمل من عمره 16 سنة تصريح التعلّم قبل الحصول على رخصة القيادة؟","o":["6 أشهر","شهر واحد","سنة واحدة","18 شهراً"],"h1":"إنها نصف المدة المطلوبة من المراهقين الأصغر سناً.","h2":"في North Dakota يجب على من عمره 16 سنة أن يحمل تصريح التعلّم ستة أشهر قبل الحصول على رخصة القيادة.","p":"صحيح. في عمر 16 سنة، الانتظار ستة أشهر."},"ref":{"doc":"ND","page":3}},{"id":"nd-008","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, how many hours of supervised driving must a permit holder under 16 complete?","o":["10 hours","20 hours","100 hours","50 hours"],"h1":"It is half of one hundred.","h2":"A North Dakota permit holder under 16 must complete at least 50 hours of supervised practice driving.","p":"Right. Under 16, you need 50 hours."},"es":{"q":"En Dakota del Norte, ¿cuántas horas de manejo supervisado debe completar un joven con permiso menor de 16 años?","o":["10 horas","20 horas","100 horas","50 horas"],"h1":"Es la mitad de cien.","h2":"Un joven con permiso menor de 16 años en Dakota del Norte debe completar por lo menos 50 horas de práctica de manejo supervisado.","p":"Correcto. Menor de 16, necesita 50 horas."},"zh":{"q":"在 North Dakota，16 岁以下持学习驾照的人必须完成多少小时有人监督的驾驶？","o":["10 小时","20 小时","100 小时","50 小时"],"h1":"是一百的一半。","h2":"North Dakota 16 岁以下持学习驾照的人必须完成至少 50 小时有人监督的练习驾驶。","p":"对。16 岁以下，你需要 50 小时。"},"vi":{"q":"Ở North Dakota, người có giấy phép tập lái dưới 16 tuổi phải lái xe có giám sát bao nhiêu giờ?","o":["10 giờ","20 giờ","100 giờ","50 giờ"],"h1":"Đó là một nửa của một trăm.","h2":"Ở North Dakota, người có giấy phép tập lái dưới 16 tuổi phải lái xe tập có giám sát ít nhất 50 giờ.","p":"Đúng. Dưới 16 tuổi, bạn cần 50 giờ."},"tl":{"q":"Sa North Dakota, ilang oras ng pagmamaneho na may bantay ang dapat tapusin ng may hawak ng permit na wala pang 16?","o":["10 oras","20 oras","100 oras","50 oras"],"h1":"Ito ay kalahati ng isang daan.","h2":"Sa North Dakota, ang may hawak ng permit na wala pang 16 ay dapat tumapos ng hindi bababa sa 50 oras ng pagsasanay sa pagmamaneho na may bantay.","p":"Tama. Kung wala ka pang 16, kailangan mo ng 50 oras."},"ar":{"q":"في North Dakota، كم ساعة من القيادة تحت الإشراف يجب أن يكملها حامل التصريح الذي عمره أقل من 16 سنة؟","o":["10 ساعات","20 ساعة","100 ساعة","50 ساعة"],"h1":"إنها نصف المئة.","h2":"في North Dakota يجب على حامل التصريح الذي عمره أقل من 16 سنة أن يكمل 50 ساعة على الأقل من التدريب على القيادة تحت الإشراف.","p":"صحيح. إذا كان عمرك أقل من 16 سنة، تحتاج إلى 50 ساعة."},"ref":{"doc":"ND","page":3}},{"id":"nd-009","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, what is the youngest age to get a restricted license?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year after the permit age of 14.","h2":"In North Dakota the restricted license is available from age 15.","p":"Right. The restricted license starts at 15."},"es":{"q":"En Dakota del Norte, ¿cuál es la edad mínima para obtener una licencia restringida?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año después de la edad del permiso, que es 14.","h2":"En Dakota del Norte la licencia restringida se puede obtener desde los 15 años.","p":"Correcto. La licencia restringida empieza a los 15."},"zh":{"q":"在 North Dakota，最小几岁可以拿到限制驾照（restricted license）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比 14 岁的学习驾照年龄晚一年。","h2":"在 North Dakota，从 15 岁起可以拿到限制驾照。","p":"对。限制驾照从 15 岁开始。"},"vi":{"q":"Ở North Dakota, tuổi nhỏ nhất để được cấp bằng lái hạn chế (restricted license) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là một năm sau tuổi được cấp giấy phép tập lái là 14.","h2":"Ở North Dakota, bằng lái hạn chế được cấp từ 15 tuổi.","p":"Đúng. Bằng lái hạn chế bắt đầu từ 15 tuổi."},"tl":{"q":"Sa North Dakota, ano ang pinakabatang edad para makakuha ng restricted license (lisensyang may limitasyon)?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito pagkatapos ng edad ng permit na 14.","h2":"Sa North Dakota, makukuha ang restricted license simula sa edad na 15.","p":"Tama. Nagsisimula ang restricted license sa edad na 15."},"ar":{"q":"في North Dakota، ما أصغر عمر للحصول على رخصة القيادة المقيّدة (restricted license)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"إنه بعد سنة واحدة من عمر التصريح وهو 14 سنة.","h2":"في North Dakota تتوفر رخصة القيادة المقيّدة من عمر 15 سنة.","p":"صحيح. تبدأ الرخصة المقيّدة من عمر 15 سنة."},"ref":{"doc":"ND","page":6}},{"id":"nd-010","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, when may a 15-year-old with a restricted license not drive without a parent, guardian or adult 18 or older?","o":["From 6 p.m. to 6 a.m.","From midnight to 4 a.m.","From 9 p.m. to 5 a.m.","On weekends"],"h1":"The limit starts in the evening, earlier than midnight.","h2":"A 15-year-old with a North Dakota restricted license may not drive from 9 p.m., or sunset if that is later, until 5 a.m. without a parent, guardian or adult 18 or older, except straight to or from work, school activities or religious activities.","p":"Right. No driving alone from 9 p.m. to 5 a.m."},"es":{"q":"En Dakota del Norte, ¿cuándo no puede manejar un joven de 15 años con licencia restringida sin su padre, madre, tutor o un adulto de 18 años o más?","o":["De 6 p.m. a 6 a.m.","De medianoche a 4 a.m.","De 9 p.m. a 5 a.m.","Los fines de semana"],"h1":"El límite empieza en la noche, antes de la medianoche.","h2":"Un joven de 15 años con licencia restringida en Dakota del Norte no puede manejar desde las 9 p.m., o la puesta del sol si es más tarde, hasta las 5 a.m. sin su padre, madre, tutor o un adulto de 18 años o más, salvo para ir directo al trabajo, a actividades escolares o religiosas, o volver de ellos.","p":"Correcto. No maneja solo de 9 p.m. a 5 a.m."},"zh":{"q":"在 North Dakota，持限制驾照的 15 岁司机，什么时候不能在没有父母、监护人或 18 岁或以上的成年人陪同时开车？","o":["晚上 6 点到早上 6 点","午夜到凌晨 4 点","晚上 9 点到早上 5 点","周末"],"h1":"限制从晚上开始，比午夜早。","h2":"持 North Dakota 限制驾照的 15 岁司机，从晚上 9 点（如果日落更晚，就从日落）到早上 5 点，没有父母、监护人或 18 岁或以上的成年人陪同时不能开车，除非是直接去或离开工作、学校活动或宗教活动。","p":"对。晚上 9 点到早上 5 点不能单独开车。"},"vi":{"q":"Ở North Dakota, khi nào người 15 tuổi có bằng lái hạn chế không được lái xe nếu không có cha mẹ, người giám hộ hoặc người lớn từ 18 tuổi trở lên?","o":["Từ 6 giờ tối đến 6 giờ sáng","Từ nửa đêm đến 4 giờ sáng","Từ 9 giờ tối đến 5 giờ sáng","Vào cuối tuần"],"h1":"Giới hạn bắt đầu vào buổi tối, sớm hơn nửa đêm.","h2":"Ở North Dakota, người 15 tuổi có bằng lái hạn chế không được lái xe từ 9 giờ tối, hoặc từ lúc mặt trời lặn nếu muộn hơn, đến 5 giờ sáng nếu không có cha mẹ, người giám hộ hoặc người lớn từ 18 tuổi trở lên, trừ khi đi thẳng đến hoặc về từ nơi làm việc, hoạt động của trường hoặc hoạt động tôn giáo.","p":"Đúng. Không lái xe một mình từ 9 giờ tối đến 5 giờ sáng."},"tl":{"q":"Sa North Dakota, kailan hindi maaaring magmaneho ang 15 taong gulang na may restricted license nang walang magulang, guardian o adult na 18 o mas matanda?","o":["Mula 6 p.m. hanggang 6 a.m.","Mula hatinggabi hanggang 4 a.m.","Mula 9 p.m. hanggang 5 a.m.","Tuwing weekend"],"h1":"Nagsisimula ang limitasyon sa gabi, mas maaga sa hatinggabi.","h2":"Sa North Dakota, ang 15 taong gulang na may restricted license ay hindi maaaring magmaneho mula 9 p.m., o paglubog ng araw kung mas huli iyon, hanggang 5 a.m. nang walang magulang, guardian o adult na 18 o mas matanda, maliban kung diretso papunta o pauwi mula sa trabaho, gawain sa paaralan o gawaing panrelihiyon.","p":"Tama. Bawal magmanehong mag-isa mula 9 p.m. hanggang 5 a.m."},"ar":{"q":"في North Dakota، متى لا يجوز لمن عمره 15 سنة ويحمل رخصة مقيّدة أن يقود دون أحد الوالدين أو الوصي أو شخص بالغ عمره 18 سنة أو أكثر؟","o":["من 6 مساءً إلى 6 صباحاً","من منتصف الليل إلى 4 صباحاً","من 9 مساءً إلى 5 صباحاً","في عطلة نهاية الأسبوع"],"h1":"يبدأ المنع في المساء، قبل منتصف الليل.","h2":"في North Dakota لا يجوز لمن عمره 15 سنة ويحمل رخصة مقيّدة أن يقود من 9 مساءً، أو من غروب الشمس إذا كان أبعد، حتى 5 صباحاً دون أحد الوالدين أو الوصي أو شخص بالغ عمره 18 سنة أو أكثر، إلا إذا كان ذاهباً مباشرة إلى العمل أو أنشطة المدرسة أو الأنشطة الدينية أو عائداً منها.","p":"صحيح. لا قيادة وحدك من 9 مساءً إلى 5 صباحاً."},"ref":{"doc":"ND","page":6}},{"id":"nd-011","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, whose car may a young driver with a restricted license drive?","o":["Only a car that belongs to a parent, guardian, grandparent, brother, sister, aunt or uncle","Any car with insurance","A friend's car","A rental car"],"h1":"The car must belong to the teen's close family.","h2":"A young North Dakota driver with a restricted license may drive only a car that belongs to a parent, guardian, grandparent, brother, sister, aunt or uncle.","p":"Right. Only a car owned by close family."},"es":{"q":"En Dakota del Norte, ¿el carro de quién puede manejar un joven con licencia restringida?","o":["Solo un carro de su padre, madre, tutor, abuelo, abuela, hermano, hermana, tía o tío","Cualquier carro con seguro","El carro de un amigo","Un carro alquilado"],"h1":"El carro debe ser de su familia cercana.","h2":"Un joven con licencia restringida en Dakota del Norte solo puede manejar un carro que sea de su padre, madre, tutor, abuelo, abuela, hermano, hermana, tía o tío.","p":"Correcto. Solo un carro de su familia cercana."},"zh":{"q":"在 North Dakota，持限制驾照的年轻司机可以开谁的车？","o":["只能开父母、监护人、祖父母、兄弟姐妹、阿姨姑姑或叔叔舅舅的车","任何有保险的车","朋友的车","租来的车"],"h1":"这辆车必须属于青少年的亲近家人。","h2":"North Dakota 持限制驾照的年轻司机只能开属于父母、监护人、祖父母、兄弟姐妹、阿姨姑姑或叔叔舅舅的车。","p":"对。只能开亲近家人的车。"},"vi":{"q":"Ở North Dakota, người lái xe trẻ có bằng lái hạn chế được lái xe của ai?","o":["Chỉ xe của cha mẹ, người giám hộ, ông bà, anh chị em, cô dì hoặc chú bác","Bất kỳ xe nào có bảo hiểm","Xe của bạn bè","Xe thuê"],"h1":"Xe phải thuộc về gia đình thân của thiếu niên.","h2":"Ở North Dakota, người lái xe trẻ có bằng lái hạn chế chỉ được lái xe của cha mẹ, người giám hộ, ông bà, anh chị em, cô dì hoặc chú bác.","p":"Đúng. Chỉ xe của gia đình thân."},"tl":{"q":"Sa North Dakota, kaninong kotse ang maaaring imaneho ng batang driver na may restricted license?","o":["Kotse lamang ng magulang, guardian, lolo o lola, kapatid na lalaki, kapatid na babae, tita o tito","Anumang kotse na may insurance","Kotse ng kaibigan","Inuupahang kotse"],"h1":"Ang kotse ay dapat pag-aari ng malapit na pamilya ng kabataan.","h2":"Sa North Dakota, ang batang driver na may restricted license ay maaari lamang magmaneho ng kotse na pag-aari ng magulang, guardian, lolo o lola, kapatid na lalaki, kapatid na babae, tita o tito.","p":"Tama. Kotse lamang ng malapit na pamilya."},"ar":{"q":"في North Dakota، سيارة مَن يجوز للسائق الصغير الذي يحمل رخصة مقيّدة أن يقودها؟","o":["فقط سيارة يملكها أحد الوالدين أو الوصي أو الجد أو الجدة أو الأخ أو الأخت أو العمة أو الخالة أو العم أو الخال","أي سيارة عليها تأمين","سيارة صديق","سيارة مستأجرة"],"h1":"يجب أن تكون السيارة ملكاً للعائلة القريبة للمراهق.","h2":"في North Dakota لا يجوز للسائق الصغير الذي يحمل رخصة مقيّدة أن يقود إلا سيارة يملكها أحد الوالدين أو الوصي أو الجد أو الجدة أو الأخ أو الأخت أو العمة أو الخالة أو العم أو الخال.","p":"صحيح. فقط سيارة تملكها العائلة القريبة."},"ref":{"doc":"ND","page":6}},{"id":"nd-012","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, may a driver under 18 use a cell phone while driving?","o":["No, drivers under 18 may not use any electronic communication device","Yes, for calls only","Yes, at red lights","Yes, if the call is short"],"h1":"Young drivers have a stricter rule than adults.","h2":"North Dakota law says drivers under 18 may not use any electronic communication device, including a cell phone, while driving.","p":"Right. Under 18, no phone while driving."},"es":{"q":"En Dakota del Norte, ¿puede un conductor menor de 18 usar el celular mientras maneja?","o":["No, los menores de 18 no pueden usar ningún aparato de comunicación electrónica","Sí, solo para llamadas","Sí, en los semáforos en rojo","Sí, si la llamada es corta"],"h1":"Los conductores jóvenes tienen una regla más estricta que los adultos.","h2":"La ley de Dakota del Norte dice que los conductores menores de 18 no pueden usar ningún aparato de comunicación electrónica, incluido el celular, mientras manejan.","p":"Correcto. Menor de 18, nada de teléfono al manejar."},"zh":{"q":"在 North Dakota，18 岁以下的司机开车时可以用手机吗？","o":["不可以，18 岁以下的司机不能使用任何电子通讯设备","可以，只能打电话","可以，在红灯时","可以，如果电话很短"],"h1":"年轻司机的规定比成年人更严格。","h2":"North Dakota 法律规定，18 岁以下的司机开车时不能使用任何电子通讯设备，包括手机。","p":"对。18 岁以下，开车时不能用手机。"},"vi":{"q":"Ở North Dakota, người lái xe dưới 18 tuổi có được dùng điện thoại di động khi lái xe không?","o":["Không, người lái xe dưới 18 tuổi không được dùng bất kỳ thiết bị liên lạc điện tử nào","Có, chỉ để gọi điện","Có, khi dừng đèn đỏ","Có, nếu cuộc gọi ngắn"],"h1":"Người lái xe trẻ có quy định nghiêm hơn người lớn.","h2":"Luật North Dakota nói người lái xe dưới 18 tuổi không được dùng bất kỳ thiết bị liên lạc điện tử nào, kể cả điện thoại di động, khi lái xe.","p":"Đúng. Dưới 18 tuổi, không dùng điện thoại khi lái xe."},"tl":{"q":"Sa North Dakota, maaari bang gumamit ng cell phone habang nagmamaneho ang driver na wala pang 18?","o":["Hindi, ang mga driver na wala pang 18 ay hindi maaaring gumamit ng anumang electronic communication device","Oo, para sa tawag lamang","Oo, sa red light","Oo, kung maikli ang tawag"],"h1":"Mas mahigpit ang patakaran para sa mga batang driver kaysa sa mga adult.","h2":"Ayon sa batas ng North Dakota, ang mga driver na wala pang 18 ay hindi maaaring gumamit ng anumang electronic communication device, kasama ang cell phone, habang nagmamaneho.","p":"Tama. Kung wala ka pang 18, bawal ang phone habang nagmamaneho."},"ar":{"q":"في North Dakota، هل يجوز للسائق الذي عمره أقل من 18 سنة أن يستخدم الهاتف المحمول أثناء القيادة؟","o":["لا، لا يجوز للسائقين الذين عمرهم أقل من 18 سنة استخدام أي جهاز اتصال إلكتروني","نعم، للمكالمات فقط","نعم، عند الإشارة الحمراء","نعم، إذا كانت المكالمة قصيرة"],"h1":"للسائقين الصغار قاعدة أشد من البالغين.","h2":"يقول قانون North Dakota إن السائقين الذين عمرهم أقل من 18 سنة لا يجوز لهم استخدام أي جهاز اتصال إلكتروني، ومنه الهاتف المحمول، أثناء القيادة.","p":"صحيح. تحت 18 سنة، لا هاتف أثناء القيادة."},"ref":{"doc":"ND","page":6}},{"id":"nd-013","scope":"ND","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Dakota, who is banned from texting while driving?","o":["Only drivers under 18","Only bus drivers","Only drivers with a permit","All drivers"],"h1":"The texting rule does not depend on age.","h2":"In North Dakota, text messaging while driving is banned for all drivers.","p":"Right. No one may text while driving."},"es":{"q":"En Dakota del Norte, ¿a quién se le prohíbe enviar mensajes de texto mientras maneja?","o":["Solo a los menores de 18","Solo a los choferes de autobús","Solo a quienes tienen permiso","A todos los conductores"],"h1":"La regla de los mensajes no depende de la edad.","h2":"En Dakota del Norte, enviar mensajes de texto mientras maneja está prohibido para todos los conductores.","p":"Correcto. Nadie puede enviar mensajes al manejar."},"zh":{"q":"在 North Dakota，谁开车时禁止发短信？","o":["只有 18 岁以下的司机","只有公共汽车司机","只有持学习驾照的司机","所有司机"],"h1":"发短信的规定和年龄无关。","h2":"在 North Dakota，所有司机开车时都禁止发短信。","p":"对。任何人开车时都不能发短信。"},"vi":{"q":"Ở North Dakota, ai bị cấm nhắn tin khi lái xe?","o":["Chỉ người lái xe dưới 18 tuổi","Chỉ tài xế xe buýt","Chỉ người có giấy phép tập lái","Tất cả người lái xe"],"h1":"Quy định về nhắn tin không phụ thuộc vào tuổi.","h2":"Ở North Dakota, tất cả người lái xe đều bị cấm nhắn tin khi lái xe.","p":"Đúng. Không ai được nhắn tin khi lái xe."},"tl":{"q":"Sa North Dakota, sino ang bawal mag-text habang nagmamaneho?","o":["Mga driver lamang na wala pang 18","Mga driver lamang ng bus","Mga driver lamang na may permit","Lahat ng driver"],"h1":"Hindi nakadepende sa edad ang patakaran sa pag-text.","h2":"Sa North Dakota, bawal sa lahat ng driver ang pag-text habang nagmamaneho.","p":"Tama. Walang sinuman ang maaaring mag-text habang nagmamaneho."},"ar":{"q":"في North Dakota، مَن الممنوع من كتابة الرسائل النصية أثناء القيادة؟","o":["فقط السائقون الذين عمرهم أقل من 18 سنة","فقط سائقو الحافلات","فقط السائقون الذين يحملون تصريحاً","جميع السائقين"],"h1":"قاعدة الرسائل النصية لا تعتمد على العمر.","h2":"في North Dakota كتابة الرسائل النصية أثناء القيادة ممنوعة على جميع السائقين.","p":"صحيح. لا يجوز لأحد كتابة الرسائل أثناء القيادة."},"ref":{"doc":"ND","page":30}},{"id":"nd-014","scope":"ND","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Dakota, what is the fine for texting while driving?","o":["$20","$100","$500","$1,000"],"h1":"It is a round number in the hundreds.","h2":"The fine for texting while driving in North Dakota is $100.","p":"Right. The fine is $100."},"es":{"q":"En Dakota del Norte, ¿cuál es la multa por enviar mensajes de texto mientras maneja?","o":["$20","$100","$500","$1,000"],"h1":"Es un número redondo de cientos.","h2":"La multa por enviar mensajes de texto mientras maneja en Dakota del Norte es de $100.","p":"Correcto. La multa es de $100."},"zh":{"q":"在 North Dakota，开车时发短信的罚款是多少？","o":["$20","$100","$500","$1,000"],"h1":"这是几百里的一个整数。","h2":"在 North Dakota，开车时发短信的罚款是 $100。","p":"对。罚款是 $100。"},"vi":{"q":"Ở North Dakota, tiền phạt cho việc nhắn tin khi lái xe là bao nhiêu?","o":["$20","$100","$500","$1,000"],"h1":"Đó là một số tròn hàng trăm.","h2":"Ở North Dakota, tiền phạt cho việc nhắn tin khi lái xe là $100.","p":"Đúng. Tiền phạt là $100."},"tl":{"q":"Sa North Dakota, magkano ang multa sa pag-text habang nagmamaneho?","o":["$20","$100","$500","$1,000"],"h1":"Ito ay isang buong numero na nasa daan-daan.","h2":"Sa North Dakota, ang multa sa pag-text habang nagmamaneho ay $100.","p":"Tama. Ang multa ay $100."},"ar":{"q":"في North Dakota، كم غرامة كتابة الرسائل النصية أثناء القيادة؟","o":["$20","$100","$500","$1,000"],"h1":"إنه رقم مستدير بالمئات.","h2":"غرامة كتابة الرسائل النصية أثناء القيادة في North Dakota هي $100.","p":"صحيح. الغرامة $100."},"ref":{"doc":"ND","page":30}},{"id":"nd-015","scope":"ND","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Dakota, what is the legal alcohol limit for a driver under 21?","o":["0.08 percent","0.05 percent","0.02 percent","0.10 percent"],"h1":"It is much lower than the adult limit.","h2":"In North Dakota the alcohol limit for a driver under 21 is 0.02 percent.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Dakota del Norte, ¿cuál es el límite legal de alcohol para un conductor menor de 21?","o":["0.08 por ciento","0.05 por ciento","0.02 por ciento","0.10 por ciento"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Dakota del Norte el límite de alcohol para un conductor menor de 21 es de 0.02 por ciento.","p":"Correcto. Menor de 21, el límite es 0.02."},"zh":{"q":"在 North Dakota，21 岁以下司机的法定酒精限值是多少？","o":["0.08%","0.05%","0.02%","0.10%"],"h1":"它比成年人的限值低很多。","h2":"在 North Dakota，21 岁以下司机的酒精限值是 0.02%。","p":"对。21 岁以下，限值是 0.02。"},"vi":{"q":"Ở North Dakota, giới hạn nồng độ cồn hợp pháp cho người lái xe dưới 21 tuổi là bao nhiêu?","o":["0.08 phần trăm","0.05 phần trăm","0.02 phần trăm","0.10 phần trăm"],"h1":"Thấp hơn nhiều so với giới hạn cho người lớn.","h2":"Ở North Dakota, giới hạn nồng độ cồn cho người lái xe dưới 21 tuổi là 0.02 phần trăm.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa North Dakota, ano ang legal na limitasyon ng alak para sa driver na wala pang 21?","o":["0.08 porsiyento","0.05 porsiyento","0.02 porsiyento","0.10 porsiyento"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon para sa adult.","h2":"Sa North Dakota, ang limitasyon ng alak para sa driver na wala pang 21 ay 0.02 porsiyento.","p":"Tama. Kung wala ka pang 21, ang limitasyon ay 0.02."},"ar":{"q":"في North Dakota، ما الحد القانوني للكحول للسائق الذي عمره أقل من 21 سنة؟","o":["0.08 بالمئة","0.05 بالمئة","0.02 بالمئة","0.10 بالمئة"],"h1":"إنه أقل بكثير من حد البالغين.","h2":"في North Dakota حد الكحول للسائق الذي عمره أقل من 21 سنة هو 0.02 بالمئة.","p":"صحيح. تحت 21 سنة، الحد 0.02."},"ref":{"doc":"ND","page":36}},{"id":"nd-016","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, what is the legal alcohol limit for a driver 21 or older?","o":["0.08 percent","0.02 percent","0.10 percent","0.12 percent"],"h1":"It is the same limit used in most states.","h2":"In North Dakota the alcohol limit for a driver 21 or older is 0.08 percent.","p":"Right. For adults, the limit is 0.08."},"es":{"q":"En Dakota del Norte, ¿cuál es el límite legal de alcohol para un conductor de 21 años o más?","o":["0.08 por ciento","0.02 por ciento","0.10 por ciento","0.12 por ciento"],"h1":"Es el mismo límite que usan la mayoría de los estados.","h2":"En Dakota del Norte el límite de alcohol para un conductor de 21 años o más es de 0.08 por ciento.","p":"Correcto. Para adultos, el límite es 0.08."},"zh":{"q":"在 North Dakota，21 岁或以上司机的法定酒精限值是多少？","o":["0.08%","0.02%","0.10%","0.12%"],"h1":"它和大多数州用的限值一样。","h2":"在 North Dakota，21 岁或以上司机的酒精限值是 0.08%。","p":"对。成年人的限值是 0.08。"},"vi":{"q":"Ở North Dakota, giới hạn nồng độ cồn hợp pháp cho người lái xe từ 21 tuổi trở lên là bao nhiêu?","o":["0.08 phần trăm","0.02 phần trăm","0.10 phần trăm","0.12 phần trăm"],"h1":"Đó là cùng giới hạn được dùng ở hầu hết các tiểu bang.","h2":"Ở North Dakota, giới hạn nồng độ cồn cho người lái xe từ 21 tuổi trở lên là 0.08 phần trăm.","p":"Đúng. Với người lớn, giới hạn là 0.08."},"tl":{"q":"Sa North Dakota, ano ang legal na limitasyon ng alak para sa driver na 21 o mas matanda?","o":["0.08 porsiyento","0.02 porsiyento","0.10 porsiyento","0.12 porsiyento"],"h1":"Ito ang parehong limitasyon na ginagamit sa karamihan ng estado.","h2":"Sa North Dakota, ang limitasyon ng alak para sa driver na 21 o mas matanda ay 0.08 porsiyento.","p":"Tama. Para sa mga adult, ang limitasyon ay 0.08."},"ar":{"q":"في North Dakota، ما الحد القانوني للكحول للسائق الذي عمره 21 سنة أو أكثر؟","o":["0.08 بالمئة","0.02 بالمئة","0.10 بالمئة","0.12 بالمئة"],"h1":"إنه نفس الحد المستخدم في معظم الولايات.","h2":"في North Dakota حد الكحول للسائق الذي عمره 21 سنة أو أكثر هو 0.08 بالمئة.","p":"صحيح. للبالغين، الحد 0.08."},"ref":{"doc":"ND","page":36}},{"id":"nd-017","scope":"ND","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In North Dakota, on a multi-lane highway, what must you do when you pass a stopped vehicle with flashing lights?","o":["Honk to warn them","Stop behind it","Keep the same lane and speed","Change lanes if it is safe, or slow down if you cannot"],"h1":"Give the people on the shoulder more room.","h2":"North Dakota's move over law says to change to a lane away from the stopped vehicle if it is safe, and to slow down if you cannot change lanes.","p":"Right. Move over, or slow down."},"es":{"q":"En Dakota del Norte, en una carretera de varios carriles, ¿qué debe hacer al pasar un vehículo detenido con luces intermitentes?","o":["Tocar la bocina para avisar","Detenerse detrás de él","Seguir en el mismo carril y a la misma velocidad","Cambiarse de carril si es seguro, o bajar la velocidad si no puede"],"h1":"Dé más espacio a las personas en el acotamiento.","h2":"La ley de Dakota del Norte para moverse de carril dice que debe cambiarse a un carril lejos del vehículo detenido si es seguro, y bajar la velocidad si no puede cambiarse.","p":"Correcto. Cámbiese de carril o baje la velocidad."},"zh":{"q":"在 North Dakota，在多车道公路上，经过一辆停着、闪着灯的车时，你必须怎么做？","o":["按喇叭提醒他们","在它后面停车","保持同一条车道和速度","如果安全就换道，不能换道就减速"],"h1":"给路肩上的人更多空间。","h2":"North Dakota 的 move over 法规定，如果安全，要换到离停着的车远的车道；如果不能换道，就要减速。","p":"对。让出车道，或者减速。"},"vi":{"q":"Ở North Dakota, trên xa lộ nhiều làn, bạn phải làm gì khi chạy qua một xe đang dừng có đèn nhấp nháy?","o":["Bóp còi để cảnh báo họ","Dừng lại phía sau xe đó","Giữ nguyên làn và tốc độ","Đổi làn nếu an toàn, hoặc chạy chậm lại nếu không đổi làn được"],"h1":"Hãy chừa thêm chỗ cho những người ở lề đường.","h2":"Luật nhường làn (move over law) của North Dakota nói phải đổi sang làn xa xe đang dừng nếu an toàn, và chạy chậm lại nếu bạn không đổi làn được.","p":"Đúng. Nhường làn, hoặc chạy chậm lại."},"tl":{"q":"Sa North Dakota, sa highway na maraming lane, ano ang dapat mong gawin kapag dumaan ka sa nakahintong sasakyan na may kumikislap na ilaw?","o":["Bumusina para balaan sila","Huminto sa likod nito","Manatili sa parehong lane at bilis","Lumipat ng lane kung ligtas, o bumagal kung hindi ka makalipat"],"h1":"Bigyan ng mas maraming espasyo ang mga tao sa gilid ng daan.","h2":"Ayon sa move over law ng North Dakota, lumipat sa lane na malayo sa nakahintong sasakyan kung ligtas, at bumagal kung hindi ka makalipat ng lane.","p":"Tama. Lumipat ng lane, o bumagal."},"ar":{"q":"في North Dakota، على طريق سريع متعدد المسارات، ماذا يجب أن تفعل عندما تمر بمركبة متوقفة أضواؤها تومض؟","o":["استخدم البوق لتحذيرهم","توقف خلفها","ابقَ في نفس المسار وبنفس السرعة","غيّر المسار إذا كان ذلك آمناً، أو خفّف السرعة إذا لم تستطع"],"h1":"أعطِ الأشخاص على جانب الطريق مساحة أكبر.","h2":"يقول قانون الابتعاد (move over law) في North Dakota أن تنتقل إلى مسار بعيد عن المركبة المتوقفة إذا كان ذلك آمناً، وأن تخفّف السرعة إذا لم تستطع تغيير المسار.","p":"صحيح. ابتعد، أو خفّف السرعة."},"ref":{"doc":"ND","page":32}},{"id":"nd-018","scope":"ND","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In North Dakota, on an interstate or multi-lane highway outside a city, which stopped vehicles does the move over rule cover?","o":["Only police cars","Any vehicle showing flashing hazard lights","Only ambulances and fire trucks","Only school buses"],"h1":"It is not only for emergency vehicles.","h2":"In North Dakota, the move over rule also covers any vehicle stopped on an interstate or multi-lane highway outside a city with its flashing hazard lights on.","p":"Right. Any vehicle with hazard lights is covered."},"es":{"q":"En Dakota del Norte, en una interestatal o carretera de varios carriles fuera de una ciudad, ¿qué vehículos detenidos cubre la regla para moverse de carril?","o":["Solo carros de policía","Cualquier vehículo con luces de emergencia intermitentes","Solo ambulancias y bomberos","Solo autobuses escolares"],"h1":"No es solo para vehículos de emergencia.","h2":"En Dakota del Norte, la regla para moverse de carril también cubre cualquier vehículo detenido en una interestatal o carretera de varios carriles fuera de una ciudad con sus luces de emergencia intermitentes encendidas.","p":"Correcto. Cualquier vehículo con luces de emergencia está cubierto."},"zh":{"q":"在 North Dakota，在城市以外的州际公路或多车道公路上，move over 规定包括哪些停着的车？","o":["只有警车","任何开着危险警示灯的车","只有救护车和消防车","只有校车"],"h1":"它不只是给急救车辆的。","h2":"在 North Dakota，move over 规定也包括任何停在城市以外的州际公路或多车道公路上、开着危险警示灯的车。","p":"对。任何开着危险警示灯的车都包括在内。"},"vi":{"q":"Ở North Dakota, trên xa lộ liên tiểu bang (interstate) hoặc xa lộ nhiều làn bên ngoài thành phố, quy định nhường làn áp dụng cho những xe đang dừng nào?","o":["Chỉ xe cảnh sát","Bất kỳ xe nào đang bật đèn cảnh báo nhấp nháy","Chỉ xe cứu thương và xe cứu hỏa","Chỉ xe buýt trường học"],"h1":"Không chỉ dành cho xe khẩn cấp.","h2":"Ở North Dakota, quy định nhường làn cũng áp dụng cho bất kỳ xe nào đang dừng trên xa lộ liên tiểu bang hoặc xa lộ nhiều làn bên ngoài thành phố và đang bật đèn cảnh báo nhấp nháy.","p":"Đúng. Bất kỳ xe nào bật đèn cảnh báo đều được áp dụng."},"tl":{"q":"Sa North Dakota, sa interstate o highway na maraming lane sa labas ng lungsod, aling mga nakahintong sasakyan ang sakop ng move over rule?","o":["Mga kotse lamang ng pulis","Anumang sasakyan na nakabukas ang kumikislap na hazard lights","Mga ambulansya at trak ng bumbero lamang","Mga school bus lamang"],"h1":"Hindi lamang ito para sa mga emergency vehicle.","h2":"Sa North Dakota, sakop din ng move over rule ang anumang sasakyan na nakahinto sa interstate o highway na maraming lane sa labas ng lungsod na nakabukas ang kumikislap na hazard lights.","p":"Tama. Sakop ang anumang sasakyan na may hazard lights."},"ar":{"q":"في North Dakota، على طريق سريع بين الولايات (interstate) أو طريق سريع متعدد المسارات خارج المدينة، أي المركبات المتوقفة تشملها قاعدة الابتعاد؟","o":["سيارات الشرطة فقط","أي مركبة تشغّل أضواء التحذير الوامضة","سيارات الإسعاف والإطفاء فقط","الحافلات المدرسية فقط"],"h1":"إنها ليست لمركبات الطوارئ فقط.","h2":"في North Dakota تشمل قاعدة الابتعاد أيضاً أي مركبة متوقفة على طريق سريع بين الولايات أو طريق سريع متعدد المسارات خارج المدينة وأضواء التحذير الوامضة فيها مشغّلة.","p":"صحيح. أي مركبة بأضواء التحذير مشمولة."},"ref":{"doc":"ND","page":32}},{"id":"nd-019","scope":"ND","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In North Dakota, on a two-way road with no median, who must stop for a school bus with its stop arm out?","o":["Traffic in both directions","Only traffic behind the bus","Only trucks","No one, if the road is clear"],"h1":"On an undivided road, the children may cross toward either side.","h2":"In North Dakota, when a school bus stops with red lights flashing and the stop arm out on an undivided road, traffic in both directions must stop.","p":"Right. Both directions stop."},"es":{"q":"En Dakota del Norte, en una vía de doble sentido sin división, ¿quién debe detenerse ante un autobús escolar con el brazo de alto extendido?","o":["El tráfico en ambos sentidos","Solo el tráfico detrás del autobús","Solo los camiones","Nadie, si la vía está libre"],"h1":"En una vía sin división, los niños pueden cruzar hacia cualquier lado.","h2":"En Dakota del Norte, cuando un autobús escolar se detiene con luces rojas intermitentes y el brazo de alto extendido en una vía sin división, el tráfico en ambos sentidos debe detenerse.","p":"Correcto. Ambos sentidos se detienen."},"zh":{"q":"在 North Dakota，在没有中央隔离带的双向道路上，谁必须为伸出停车臂的校车停车？","o":["两个方向的车","只有校车后面的车","只有卡车","没有人，如果路上没人"],"h1":"在没有分隔的路上，孩子可能往任何一边过马路。","h2":"在 North Dakota，校车在没有分隔的路上停下、闪着红灯并伸出停车臂时，两个方向的车都必须停车。","p":"对。两个方向都要停。"},"vi":{"q":"Ở North Dakota, trên đường hai chiều không có dải phân cách, ai phải dừng lại khi xe buýt trường học giương biển STOP?","o":["Xe cộ ở cả hai chiều","Chỉ xe phía sau xe buýt","Chỉ xe tải","Không ai, nếu đường trống"],"h1":"Trên đường không có dải phân cách, trẻ em có thể băng qua về bất kỳ bên nào.","h2":"Ở North Dakota, khi xe buýt trường học dừng lại, đèn đỏ nhấp nháy và giương biển STOP trên đường không có dải phân cách, xe cộ ở cả hai chiều phải dừng lại.","p":"Đúng. Cả hai chiều đều dừng lại."},"tl":{"q":"Sa North Dakota, sa daang two-way na walang median, sino ang dapat huminto para sa school bus na nakalabas ang stop arm?","o":["Mga sasakyan sa magkabilang direksyon","Mga sasakyan lamang sa likod ng bus","Mga trak lamang","Wala, kung maluwag ang daan"],"h1":"Sa daang walang harang sa gitna, maaaring tumawid ang mga bata papunta sa alinmang gilid.","h2":"Sa North Dakota, kapag huminto ang school bus na kumikislap ang pulang ilaw at nakalabas ang stop arm sa daang walang harang sa gitna, dapat huminto ang mga sasakyan sa magkabilang direksyon.","p":"Tama. Huminto ang magkabilang direksyon."},"ar":{"q":"في North Dakota، على طريق باتجاهين بلا جزيرة وسطية، مَن يجب أن يتوقف لحافلة مدرسية ذراع التوقف (STOP) فيها مفتوح؟","o":["حركة المرور في الاتجاهين","حركة المرور خلف الحافلة فقط","الشاحنات فقط","لا أحد، إذا كان الطريق خالياً"],"h1":"على طريق غير مقسوم، قد يعبر الأطفال نحو أي جانب.","h2":"في North Dakota، عندما تتوقف حافلة مدرسية وأضواؤها الحمراء تومض وذراع التوقف مفتوح على طريق غير مقسوم، يجب أن تتوقف حركة المرور في الاتجاهين.","p":"صحيح. يتوقف الاتجاهان."},"ref":{"doc":"ND","page":20}},{"id":"nd-020","scope":"ND","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In North Dakota, when may oncoming drivers keep going past a stopped school bus with its stop arm out?","o":["When they are in a hurry","When the bus is yellow","When a physical median or barrier divides the highway","When they honk first"],"h1":"Something solid must separate your side from the bus's side.","h2":"In North Dakota, oncoming drivers do not have to stop for a school bus only when the highway has separate roadways, divided by a median or barrier, and the bus is on the other roadway.","p":"Right. A physical median makes the difference."},"es":{"q":"En Dakota del Norte, ¿cuándo pueden seguir los conductores que vienen de frente ante un autobús escolar detenido con el brazo de alto extendido?","o":["Cuando tienen prisa","Cuando el autobús es amarillo","Cuando una división física o barrera separa la carretera","Cuando tocan la bocina primero"],"h1":"Algo sólido debe separar su lado del lado del autobús.","h2":"En Dakota del Norte, los conductores que vienen de frente no tienen que detenerse ante un autobús escolar solo cuando la carretera tiene calzadas separadas por una división o barrera y el autobús está en la otra calzada.","p":"Correcto. La división física hace la diferencia."},"zh":{"q":"在 North Dakota，对面开来的司机什么时候可以继续开过伸出停车臂、停着的校车？","o":["他们赶时间的时候","校车是黄色的时候","有实体中央隔离带或护栏把公路分开的时候","他们先按了喇叭的时候"],"h1":"必须有坚固的东西把你这边和校车那边分开。","h2":"在 North Dakota，只有当公路被中央隔离带或护栏分成两条独立的路面，而且校车在另一条路面上时，对面的司机才不用为校车停车。","p":"对。实体的中央隔离带是关键。"},"vi":{"q":"Ở North Dakota, khi nào xe chạy ngược chiều được tiếp tục chạy qua xe buýt trường học đang dừng và giương biển STOP?","o":["Khi họ đang vội","Khi xe buýt màu vàng","Khi có dải phân cách hoặc rào chắn chia đôi xa lộ","Khi họ bóp còi trước"],"h1":"Phải có một vật cứng ngăn cách phía bạn với phía xe buýt.","h2":"Ở North Dakota, xe chạy ngược chiều chỉ không phải dừng lại cho xe buýt trường học khi xa lộ có hai lòng đường riêng, được chia bởi dải phân cách hoặc rào chắn, và xe buýt ở lòng đường bên kia.","p":"Đúng. Dải phân cách thật sự là điều tạo nên sự khác biệt."},"tl":{"q":"Sa North Dakota, kailan maaaring tumuloy ang mga sasakyang paparating sa kabilang direksyon at lumampas sa nakahintong school bus na nakalabas ang stop arm?","o":["Kapag nagmamadali sila","Kapag dilaw ang bus","Kapag may median o harang na naghahati sa highway","Kapag bumusina muna sila"],"h1":"May matibay na bagay na dapat naghihiwalay sa iyong panig at sa panig ng bus.","h2":"Sa North Dakota, hindi kailangang huminto ng mga paparating na sasakyan para sa school bus lamang kapag ang highway ay may hiwalay na daan, na hinahati ng median o harang, at nasa kabilang daan ang bus.","p":"Tama. Ang median o harang ang nagpapaiba."},"ar":{"q":"في North Dakota، متى يجوز للسائقين القادمين من الاتجاه المعاكس أن يستمروا في المرور بجانب حافلة مدرسية متوقفة ذراع التوقف فيها مفتوح؟","o":["عندما يكونون مستعجلين","عندما تكون الحافلة صفراء","عندما تقسم جزيرة وسطية أو حاجز الطريق السريع","عندما يستخدمون البوق أولاً"],"h1":"يجب أن يفصل شيء صلب جانبك عن جانب الحافلة.","h2":"في North Dakota، ليس على السائقين القادمين من الاتجاه المعاكس أن يتوقفوا للحافلة المدرسية في حالة واحدة فقط: عندما يكون للطريق السريع طريقان منفصلان تقسمهما جزيرة وسطية أو حاجز، وتكون الحافلة على الطريق الآخر.","p":"صحيح. الجزيرة الوسطية أو الحاجز هو ما يصنع الفرق."},"ref":{"doc":"ND","page":null}},{"id":"nd-021","scope":"ND","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In North Dakota, what is the top speed limit on rural interstate highways, unless a sign says otherwise?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"It is higher than the limit on divided highways that are not interstates.","h2":"In North Dakota the speed limit on rural interstate highways is 80 mph unless a sign shows a different limit.","p":"Right. Rural interstates in North Dakota allow up to 80 mph."},"es":{"q":"En Dakota del Norte, ¿cuál es el límite de velocidad máximo en las autopistas interestatales rurales, si no hay una señal que diga otra cosa?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"Es más alto que el límite en las carreteras divididas que no son interestatales.","h2":"En Dakota del Norte el límite de velocidad en las autopistas interestatales rurales es de 80 mph, a menos que una señal indique otro límite.","p":"Correcto. En las interestatales rurales de Dakota del Norte se permite hasta 80 mph."},"zh":{"q":"在 North Dakota，如果没有标志另行规定，乡村州际公路的最高限速是多少？","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"它比不是州际公路的分隔公路的限速更高。","h2":"在 North Dakota，乡村州际公路的限速是 80 mph，除非标志显示不同的限速。","p":"对。North Dakota 的乡村州际公路最高可以开到 80 mph。"},"vi":{"q":"Ở North Dakota, tốc độ tối đa trên xa lộ liên tiểu bang ở vùng nông thôn là bao nhiêu, trừ khi có biển báo khác?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"Nó cao hơn giới hạn trên các xa lộ có dải phân cách không phải là xa lộ liên tiểu bang.","h2":"Ở North Dakota, giới hạn tốc độ trên xa lộ liên tiểu bang ở vùng nông thôn là 80 mph, trừ khi biển báo ghi giới hạn khác.","p":"Đúng. Xa lộ liên tiểu bang ở vùng nông thôn của North Dakota cho phép chạy tới 80 mph."},"tl":{"q":"Sa North Dakota, ano ang pinakamataas na speed limit sa mga rural interstate highway, maliban kung iba ang sinasabi ng karatula?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"Mas mataas ito kaysa sa limit sa mga divided highway na hindi interstate.","h2":"Sa North Dakota, ang speed limit sa mga rural interstate highway ay 80 mph maliban kung ibang limit ang nakasaad sa karatula.","p":"Tama. Hanggang 80 mph ang pinapayagan sa mga rural interstate sa North Dakota."},"ar":{"q":"في North Dakota، ما هو الحد الأقصى للسرعة على الطرق السريعة بين الولايات في المناطق الريفية، ما لم تقل لافتة غير ذلك؟","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"إنه أعلى من الحد على الطرق المقسمة التي ليست طرقًا بين الولايات.","h2":"في North Dakota، حد السرعة على الطرق السريعة بين الولايات في المناطق الريفية هو 80 mph ما لم تُظهر لافتة حدًا مختلفًا.","p":"صحيح. الطرق السريعة الريفية بين الولايات في North Dakota تسمح بسرعة تصل إلى 80 mph."},"ref":{"doc":"ND","page":20}},{"id":"nd-022","scope":"ND","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In North Dakota, what is the speed limit on a gravel or dirt road when no limit is posted?","o":["45 mph","55 mph","65 mph","35 mph"],"h1":"It is the same as on a paved county road with no posted limit.","h2":"In North Dakota the speed limit on gravel, dirt or other loose-surface roads is 55 mph when no other limit is posted.","p":"Right. Gravel and dirt roads have a 55 mph limit unless posted."},"es":{"q":"En Dakota del Norte, ¿cuál es el límite de velocidad en un camino de grava o de tierra cuando no hay un límite señalado?","o":["45 mph","55 mph","65 mph","35 mph"],"h1":"Es igual que en una carretera pavimentada del condado sin límite señalado.","h2":"En Dakota del Norte el límite de velocidad en caminos de grava, de tierra u otra superficie suelta es de 55 mph cuando no hay otro límite señalado.","p":"Correcto. Los caminos de grava y de tierra tienen un límite de 55 mph si no hay señal."},"zh":{"q":"在 North Dakota，没有标出限速时，碎石路或土路的限速是多少？","o":["45 mph","55 mph","65 mph","35 mph"],"h1":"它和没有标出限速的铺装县道一样。","h2":"在 North Dakota，没有标出其他限速时，碎石路、土路或其他松散路面道路的限速是 55 mph。","p":"对。除非另有标示，碎石路和土路的限速是 55 mph。"},"vi":{"q":"Ở North Dakota, giới hạn tốc độ trên đường sỏi hoặc đường đất là bao nhiêu khi không có biển báo giới hạn?","o":["45 mph","55 mph","65 mph","35 mph"],"h1":"Nó giống như trên đường quận trải nhựa không có biển báo giới hạn.","h2":"Ở North Dakota, giới hạn tốc độ trên đường sỏi, đường đất hoặc đường có mặt đường rời khác là 55 mph khi không có giới hạn nào khác được ghi.","p":"Đúng. Đường sỏi và đường đất có giới hạn 55 mph trừ khi có biển báo khác."},"tl":{"q":"Sa North Dakota, ano ang speed limit sa daang graba o lupa kapag walang nakapaskil na limit?","o":["45 mph","55 mph","65 mph","35 mph"],"h1":"Pareho ito sa sementadong county road na walang nakapaskil na limit.","h2":"Sa North Dakota, ang speed limit sa mga daang graba, lupa o iba pang maluwag ang ibabaw ay 55 mph kapag walang ibang limit na nakapaskil.","p":"Tama. May 55 mph na limit ang mga daang graba at lupa maliban kung may nakapaskil."},"ar":{"q":"في North Dakota، ما هو حد السرعة على طريق من الحصى أو التراب عندما لا يكون هناك حد مكتوب؟","o":["45 mph","55 mph","65 mph","35 mph"],"h1":"إنه نفس الحد على طريق مقاطعة معبد بلا حد مكتوب.","h2":"في North Dakota، حد السرعة على طرق الحصى أو التراب أو الطرق ذات السطح غير الثابت هو 55 mph عندما لا يكون هناك حد آخر مكتوب.","p":"صحيح. طرق الحصى والتراب حدها 55 mph ما لم يُكتب غير ذلك."},"ref":{"doc":"ND","page":20}},{"id":"nd-023","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, what is the fine for a first offense of driving without liability insurance?","o":["$50","$100","$500","$150"],"h1":"A second offense within three years costs twice as much.","h2":"In North Dakota the fine for a first offense of driving without liability insurance is $150, and your license may also be suspended.","p":"Right. A first no-insurance offense is a $150 fine."},"es":{"q":"En Dakota del Norte, ¿cuál es la multa por una primera infracción de manejar sin seguro de responsabilidad civil?","o":["$50","$100","$500","$150"],"h1":"Una segunda infracción en tres años cuesta el doble.","h2":"En Dakota del Norte la multa por una primera infracción de manejar sin seguro de responsabilidad civil es de $150, y además le pueden suspender la licencia.","p":"Correcto. La primera infracción por no tener seguro es una multa de $150."},"zh":{"q":"在 North Dakota，第一次没有责任保险开车会被罚款多少？","o":["$50","$100","$500","$150"],"h1":"三年内第二次违规要付两倍的钱。","h2":"在 North Dakota，第一次没有责任保险开车的罚款是 $150，你的驾照也可能被暂停。","p":"对。第一次没有保险的罚款是 $150。"},"vi":{"q":"Ở North Dakota, tiền phạt cho lần vi phạm đầu tiên vì lái xe không có bảo hiểm trách nhiệm là bao nhiêu?","o":["$50","$100","$500","$150"],"h1":"Lần vi phạm thứ hai trong vòng ba năm bị phạt gấp đôi.","h2":"Ở North Dakota, tiền phạt cho lần đầu lái xe không có bảo hiểm trách nhiệm là $150, và bằng lái của bạn cũng có thể bị đình chỉ.","p":"Đúng. Lần đầu không có bảo hiểm bị phạt $150."},"tl":{"q":"Sa North Dakota, magkano ang multa sa unang paglabag sa pagmamaneho nang walang liability insurance?","o":["$50","$100","$500","$150"],"h1":"Doble ang babayaran sa ikalawang paglabag sa loob ng tatlong taon.","h2":"Sa North Dakota, ang multa sa unang paglabag sa pagmamaneho nang walang liability insurance ay $150, at maaari ring masuspinde ang iyong lisensya.","p":"Tama. $150 ang multa sa unang paglabag na walang insurance."},"ar":{"q":"في North Dakota، ما هي الغرامة على المخالفة الأولى للقيادة بدون تأمين المسؤولية؟","o":["$50","$100","$500","$150"],"h1":"المخالفة الثانية خلال ثلاث سنوات تكلف ضعف المبلغ.","h2":"في North Dakota، الغرامة على المخالفة الأولى للقيادة بدون تأمين المسؤولية هي $150، وقد تُعلَّق رخصتك أيضًا.","p":"صحيح. المخالفة الأولى بدون تأمين غرامتها $150."},"ref":{"doc":"ND","page":27}},{"id":"nd-024","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, a crash with no injuries must be reported to police right away when the total damage reaches what amount?","o":["$4,000 or more","$1,000 or more","$500 or more","$10,000 or more"],"h1":"The amount is a few thousand dollars, added up for all vehicles and property.","h2":"In North Dakota you must report a crash to police right away when the combined damage is $4,000 or more, or when anyone is hurt or killed.","p":"Right. Combined damage of $4,000 or more must be reported."},"es":{"q":"En Dakota del Norte, un choque sin heridos se debe reportar a la policía de inmediato cuando el daño total llega a ¿qué cantidad?","o":["$4,000 o más","$1,000 o más","$500 o más","$10,000 o más"],"h1":"La cantidad es de unos miles de dólares, sumando todos los vehículos y la propiedad.","h2":"En Dakota del Norte usted debe reportar un choque a la policía de inmediato cuando el daño combinado es de $4,000 o más, o cuando alguien resulta herido o muere.","p":"Correcto. Un daño combinado de $4,000 o más se debe reportar."},"zh":{"q":"在 North Dakota，没有人受伤的车祸，总损失达到多少时必须马上报警？","o":["$4,000 或以上","$1,000 或以上","$500 或以上","$10,000 或以上"],"h1":"这个金额是几千美元，把所有车辆和财产的损失加在一起计算。","h2":"在 North Dakota，当总损失达到 $4,000 或以上，或者有人受伤或死亡时，你必须马上向警察报告车祸。","p":"对。总损失 $4,000 或以上必须报告。"},"vi":{"q":"Ở North Dakota, một vụ tai nạn không có người bị thương phải được báo ngay cho cảnh sát khi tổng thiệt hại đạt mức nào?","o":["$4,000 trở lên","$1,000 trở lên","$500 trở lên","$10,000 trở lên"],"h1":"Số tiền này là vài nghìn đô la, cộng lại cho tất cả xe và tài sản.","h2":"Ở North Dakota, bạn phải báo tai nạn cho cảnh sát ngay khi tổng thiệt hại là $4,000 trở lên, hoặc khi có người bị thương hay tử vong.","p":"Đúng. Tổng thiệt hại từ $4,000 trở lên phải được báo."},"tl":{"q":"Sa North Dakota, ang banggaang walang nasaktan ay dapat i-report agad sa pulis kapag umabot ang kabuuang pinsala sa anong halaga?","o":["$4,000 o higit pa","$1,000 o higit pa","$500 o higit pa","$10,000 o higit pa"],"h1":"Ilang libong dolyar ang halaga, pinagsama para sa lahat ng sasakyan at ari-arian.","h2":"Sa North Dakota, dapat mong i-report agad sa pulis ang banggaan kapag ang pinagsamang pinsala ay $4,000 o higit pa, o kapag may nasaktan o namatay.","p":"Tama. Dapat i-report ang pinagsamang pinsala na $4,000 o higit pa."},"ar":{"q":"في North Dakota، يجب إبلاغ الشرطة فورًا عن حادث بلا إصابات عندما يصل مجموع الأضرار إلى أي مبلغ؟","o":["$4,000 أو أكثر","$1,000 أو أكثر","$500 أو أكثر","$10,000 أو أكثر"],"h1":"المبلغ بضعة آلاف من الدولارات، مجموعًا لكل المركبات والممتلكات.","h2":"في North Dakota، يجب أن تبلغ الشرطة عن الحادث فورًا عندما يكون مجموع الأضرار $4,000 أو أكثر، أو عندما يُصاب أحد أو يُقتل.","p":"صحيح. يجب الإبلاغ عن أضرار مجموعها $4,000 أو أكثر."},"ref":{"doc":"ND","page":27}},{"id":"nd-025","scope":"ND","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Dakota, children under what age must ride in a car seat or booster seat (unless they are at least 57 inches tall)?","o":["Under 5","Under 8","Under 10","Under 12"],"h1":"Older children, up to age 17, may use a seat belt instead.","h2":"In North Dakota children under 8 must ride in a car seat or booster seat, unless they are at least 57 inches tall and can use a seat belt.","p":"Right. Children under 8 need a car seat or booster seat."},"es":{"q":"En Dakota del Norte, ¿los niños menores de qué edad deben viajar en un asiento de seguridad o elevador (a menos que midan al menos 57 pulgadas)?","o":["Menores de 5","Menores de 8","Menores de 10","Menores de 12"],"h1":"Los niños mayores, hasta los 17 años, pueden usar el cinturón de seguridad.","h2":"En Dakota del Norte los niños menores de 8 años deben viajar en un asiento de seguridad o elevador, a menos que midan al menos 57 pulgadas y puedan usar el cinturón.","p":"Correcto. Los niños menores de 8 años necesitan un asiento de seguridad o elevador."},"zh":{"q":"在 North Dakota，几岁以下的儿童必须坐儿童安全座椅或增高座椅（除非身高至少 57 英寸）？","o":["5 岁以下","8 岁以下","10 岁以下","12 岁以下"],"h1":"更大的孩子，到 17 岁为止，可以改用安全带。","h2":"在 North Dakota，8 岁以下的儿童必须坐儿童安全座椅或增高座椅，除非他们身高至少 57 英寸并且可以使用安全带。","p":"对。8 岁以下的儿童需要儿童安全座椅或增高座椅。"},"vi":{"q":"Ở North Dakota, trẻ em dưới bao nhiêu tuổi phải ngồi ghế an toàn hoặc ghế nâng (trừ khi cao ít nhất 57 inch)?","o":["Dưới 5 tuổi","Dưới 8 tuổi","Dưới 10 tuổi","Dưới 12 tuổi"],"h1":"Trẻ lớn hơn, đến 17 tuổi, có thể dùng dây an toàn thay thế.","h2":"Ở North Dakota, trẻ em dưới 8 tuổi phải ngồi ghế an toàn hoặc ghế nâng, trừ khi các em cao ít nhất 57 inch và có thể dùng dây an toàn.","p":"Đúng. Trẻ em dưới 8 tuổi cần ghế an toàn hoặc ghế nâng."},"tl":{"q":"Sa North Dakota, ang mga batang wala pang anong edad ang dapat nakaupo sa car seat o booster seat (maliban kung hindi bababa sa 57 pulgada ang taas nila)?","o":["Wala pang 5","Wala pang 8","Wala pang 10","Wala pang 12"],"h1":"Ang mas malalaking bata, hanggang edad 17, ay maaaring gumamit ng seat belt sa halip.","h2":"Sa North Dakota, ang mga batang wala pang 8 taong gulang ay dapat nakaupo sa car seat o booster seat, maliban kung hindi bababa sa 57 pulgada ang taas nila at kaya nilang gumamit ng seat belt.","p":"Tama. Kailangan ng car seat o booster seat ang mga batang wala pang 8."},"ar":{"q":"في North Dakota، الأطفال دون أي عمر يجب أن يجلسوا في مقعد أطفال أو مقعد رافع (إلا إذا كان طولهم 57 بوصة على الأقل)؟","o":["دون 5","دون 8","دون 10","دون 12"],"h1":"الأطفال الأكبر سنًا، حتى عمر 17، يمكنهم استخدام حزام الأمان بدلاً من ذلك.","h2":"في North Dakota، يجب أن يجلس الأطفال دون 8 سنوات في مقعد أطفال أو مقعد رافع، إلا إذا كان طولهم 57 بوصة على الأقل ويمكنهم استخدام حزام الأمان.","p":"صحيح. الأطفال دون 8 سنوات يحتاجون إلى مقعد أطفال أو مقعد رافع."},"ref":{"doc":"ND","page":34}},{"id":"nd-026","scope":"ND","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Dakota, what happens if you refuse a chemical test for alcohol or drugs when an officer asks?","o":["You get a warning only","You pay a $100 fine","You must take a driving class","Your license is revoked for 180 days to 3 years"],"h1":"By getting a license, you already agreed to be tested.","h2":"In North Dakota, if you refuse a chemical test, your license is revoked for 180 days to three years.","p":"Right. Refusing the test brings a revocation of 180 days to 3 years."},"es":{"q":"En Dakota del Norte, ¿qué pasa si usted se niega a hacerse una prueba química de alcohol o drogas cuando un oficial se lo pide?","o":["Solo recibe una advertencia","Paga una multa de $100","Debe tomar una clase de manejo","Le revocan la licencia de 180 días a 3 años"],"h1":"Al obtener la licencia, usted ya aceptó hacerse la prueba.","h2":"En Dakota del Norte, si usted se niega a una prueba química, le revocan la licencia por un período de 180 días a tres años.","p":"Correcto. Negarse a la prueba trae una revocación de 180 días a 3 años."},"zh":{"q":"在 North Dakota，如果警察要求你做酒精或毒品化学检测而你拒绝，会怎样？","o":["你只会收到警告","你要付 $100 罚款","你必须上驾驶课","你的驾照会被吊销 180 天到 3 年"],"h1":"拿到驾照时，你就已经同意接受检测。","h2":"在 North Dakota，如果你拒绝化学检测，你的驾照会被吊销 180 天到三年。","p":"对。拒绝检测会导致驾照被吊销 180 天到 3 年。"},"vi":{"q":"Ở North Dakota, điều gì xảy ra nếu bạn từ chối xét nghiệm hóa học về rượu hoặc ma túy khi cảnh sát yêu cầu?","o":["Bạn chỉ bị cảnh cáo","Bạn bị phạt $100","Bạn phải học một lớp lái xe","Bằng lái của bạn bị thu hồi từ 180 ngày đến 3 năm"],"h1":"Khi nhận bằng lái, bạn đã đồng ý được xét nghiệm.","h2":"Ở North Dakota, nếu bạn từ chối xét nghiệm hóa học, bằng lái của bạn bị thu hồi từ 180 ngày đến ba năm.","p":"Đúng. Từ chối xét nghiệm dẫn đến bị thu hồi bằng từ 180 ngày đến 3 năm."},"tl":{"q":"Sa North Dakota, ano ang mangyayari kapag tumanggi ka sa chemical test para sa alak o droga kapag hiniling ito ng pulis?","o":["Babala lang ang matatanggap mo","Magbabayad ka ng $100 na multa","Kailangan mong kumuha ng klase sa pagmamaneho","Babawiin ang iyong lisensya nang 180 araw hanggang 3 taon"],"h1":"Nang kumuha ka ng lisensya, pumayag ka nang ma-test.","h2":"Sa North Dakota, kapag tumanggi ka sa chemical test, babawiin ang iyong lisensya nang 180 araw hanggang tatlong taon.","p":"Tama. Ang pagtanggi sa test ay nagdudulot ng pagbawi ng lisensya nang 180 araw hanggang 3 taon."},"ar":{"q":"في North Dakota، ماذا يحدث إذا رفضت فحصًا كيميائيًا للكحول أو المخدرات عندما يطلبه الشرطي؟","o":["تحصل على تحذير فقط","تدفع غرامة $100","يجب أن تحضر دورة قيادة","تُلغى رخصتك لمدة من 180 يومًا إلى 3 سنوات"],"h1":"عندما حصلت على الرخصة، وافقت مسبقًا على أن تُفحص.","h2":"في North Dakota، إذا رفضت الفحص الكيميائي، تُلغى رخصتك لمدة من 180 يومًا إلى ثلاث سنوات.","p":"صحيح. رفض الفحص يؤدي إلى إلغاء الرخصة لمدة من 180 يومًا إلى 3 سنوات."},"ref":{"doc":"ND","page":36}},{"id":"nd-027","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, how many points on your driving record lead to a license suspension?","o":["12 or more","6 or more","8 or more","20 or more"],"h1":"It is a dozen.","h2":"In North Dakota your license is suspended when your driving record reaches 12 or more points.","p":"Right. Twelve or more points means a suspension."},"es":{"q":"En Dakota del Norte, ¿cuántos puntos en su historial de manejo llevan a la suspensión de la licencia?","o":["12 o más","6 o más","8 o más","20 o más"],"h1":"Es una docena.","h2":"En Dakota del Norte le suspenden la licencia cuando su historial de manejo llega a 12 puntos o más.","p":"Correcto. Doce puntos o más significan una suspensión."},"zh":{"q":"在 North Dakota，驾驶记录上有多少分会导致驾照被暂停？","o":["12 分或以上","6 分或以上","8 分或以上","20 分或以上"],"h1":"是一打。","h2":"在 North Dakota，当你的驾驶记录达到 12 分或以上时，你的驾照会被暂停。","p":"对。12 分或以上就会被暂停驾照。"},"vi":{"q":"Ở North Dakota, bao nhiêu điểm trong hồ sơ lái xe sẽ dẫn đến việc đình chỉ bằng lái?","o":["12 điểm trở lên","6 điểm trở lên","8 điểm trở lên","20 điểm trở lên"],"h1":"Đó là một tá.","h2":"Ở North Dakota, bằng lái của bạn bị đình chỉ khi hồ sơ lái xe có 12 điểm trở lên.","p":"Đúng. Từ 12 điểm trở lên nghĩa là bị đình chỉ."},"tl":{"q":"Sa North Dakota, ilang puntos sa iyong driving record ang magdudulot ng pagsuspinde ng lisensya?","o":["12 o higit pa","6 o higit pa","8 o higit pa","20 o higit pa"],"h1":"Isang dosena ito.","h2":"Sa North Dakota, masususpinde ang iyong lisensya kapag umabot sa 12 o higit pang puntos ang iyong driving record.","p":"Tama. Ang 12 o higit pang puntos ay nangangahulugang suspensyon."},"ar":{"q":"في North Dakota، كم نقطة في سجل قيادتك تؤدي إلى تعليق الرخصة؟","o":["12 أو أكثر","6 أو أكثر","8 أو أكثر","20 أو أكثر"],"h1":"إنها دزينة.","h2":"في North Dakota، تُعلَّق رخصتك عندما يصل سجل قيادتك إلى 12 نقطة أو أكثر.","p":"صحيح. 12 نقطة أو أكثر تعني التعليق."},"ref":{"doc":"ND","page":40}},{"id":"nd-028","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, how can you have one point taken off your driving record without taking a class?","o":["Pay a fee to the state","Ask a judge after one month","Go three months with no new points","Wait until your next birthday"],"h1":"It happens on its own if you keep a clean record.","h2":"In North Dakota one point comes off your record for every three months in which you get no new points.","p":"Right. Each three months with no new points removes one point."},"es":{"q":"En Dakota del Norte, ¿cómo se le puede quitar un punto de su historial de manejo sin tomar una clase?","o":["Pagar una tarifa al estado","Pedírselo a un juez después de un mes","Pasar tres meses sin puntos nuevos","Esperar hasta su próximo cumpleaños"],"h1":"Pasa solo si usted mantiene un historial limpio.","h2":"En Dakota del Norte se le quita un punto de su historial por cada tres meses en los que no recibe puntos nuevos.","p":"Correcto. Cada tres meses sin puntos nuevos le quita un punto."},"zh":{"q":"在 North Dakota，不上课的话，怎样可以从驾驶记录上减掉一分？","o":["向州政府付一笔费用","一个月后请求法官","连续三个月没有新扣分","等到你下一个生日"],"h1":"只要保持记录干净，它会自动发生。","h2":"在 North Dakota，每连续三个月没有新扣分，你的记录就会减掉一分。","p":"对。每三个月没有新扣分就减掉一分。"},"vi":{"q":"Ở North Dakota, làm sao để được xóa một điểm khỏi hồ sơ lái xe mà không cần học một lớp?","o":["Trả một khoản phí cho tiểu bang","Xin thẩm phán sau một tháng","Ba tháng liền không bị thêm điểm mới","Chờ đến sinh nhật tiếp theo"],"h1":"Điều này tự xảy ra nếu bạn giữ hồ sơ sạch.","h2":"Ở North Dakota, cứ mỗi ba tháng bạn không bị thêm điểm mới thì hồ sơ của bạn được xóa một điểm.","p":"Đúng. Mỗi ba tháng không có điểm mới sẽ xóa một điểm."},"tl":{"q":"Sa North Dakota, paano mo maaalis ang isang puntos sa iyong driving record nang hindi kumukuha ng klase?","o":["Magbayad ng bayad sa estado","Humiling sa hukom pagkalipas ng isang buwan","Tatlong buwan nang walang bagong puntos","Maghintay hanggang sa susunod mong kaarawan"],"h1":"Kusa itong nangyayari kung malinis ang iyong record.","h2":"Sa North Dakota, may isang puntos na naaalis sa iyong record sa bawat tatlong buwan na wala kang bagong puntos.","p":"Tama. Bawat tatlong buwan na walang bagong puntos ay nag-aalis ng isang puntos."},"ar":{"q":"في North Dakota، كيف يمكنك حذف نقطة واحدة من سجل قيادتك دون حضور دورة؟","o":["أن تدفع رسومًا للولاية","أن تطلب من قاضٍ بعد شهر","أن تمضي ثلاثة أشهر دون نقاط جديدة","أن تنتظر حتى عيد ميلادك القادم"],"h1":"يحدث ذلك من تلقاء نفسه إذا حافظت على سجل نظيف.","h2":"في North Dakota، تُحذف نقطة واحدة من سجلك عن كل ثلاثة أشهر لا تحصل فيها على نقاط جديدة.","p":"صحيح. كل ثلاثة أشهر بلا نقاط جديدة تحذف نقطة واحدة."},"ref":{"doc":"ND","page":40}},{"id":"nd-029","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, what is the penalty on your driving record for breaking the rules of your instruction permit?","o":["One point","Two points","Four points","Six points"],"h1":"It is a small number of points, more than one.","h2":"In North Dakota, driving against the conditions of your instruction permit puts two points on your driving record.","p":"Right. Breaking permit rules adds two points."},"es":{"q":"En Dakota del Norte, ¿cuál es la sanción en su historial de manejo por no cumplir las reglas de su permiso de instrucción?","o":["Un punto","Dos puntos","Cuatro puntos","Seis puntos"],"h1":"Es un número pequeño de puntos, más de uno.","h2":"En Dakota del Norte, manejar sin cumplir las condiciones de su permiso de instrucción agrega dos puntos a su historial de manejo.","p":"Correcto. No cumplir las reglas del permiso agrega dos puntos."},"zh":{"q":"在 North Dakota，违反学习驾照（instruction permit）的规定，在驾驶记录上会受到什么处罚？","o":["一分","两分","四分","六分"],"h1":"分数不多，但多于一分。","h2":"在 North Dakota，违反学习驾照的条件开车，会在你的驾驶记录上记两分。","p":"对。违反学习驾照规定会加两分。"},"vi":{"q":"Ở North Dakota, hình phạt trong hồ sơ lái xe khi vi phạm quy định của giấy phép học lái (instruction permit) là gì?","o":["Một điểm","Hai điểm","Bốn điểm","Sáu điểm"],"h1":"Đó là một số điểm nhỏ, nhiều hơn một.","h2":"Ở North Dakota, lái xe trái với điều kiện của giấy phép học lái sẽ bị ghi hai điểm vào hồ sơ lái xe.","p":"Đúng. Vi phạm quy định của giấy phép học lái bị thêm hai điểm."},"tl":{"q":"Sa North Dakota, ano ang parusa sa iyong driving record kapag nilabag mo ang mga patakaran ng iyong instruction permit?","o":["Isang puntos","Dalawang puntos","Apat na puntos","Anim na puntos"],"h1":"Maliit na bilang ng puntos ito, higit sa isa.","h2":"Sa North Dakota, ang pagmamaneho nang labag sa mga kondisyon ng iyong instruction permit ay naglalagay ng dalawang puntos sa iyong driving record.","p":"Tama. Ang paglabag sa mga patakaran ng permit ay nagdadagdag ng dalawang puntos."},"ar":{"q":"في North Dakota، ما هي العقوبة في سجل قيادتك عند مخالفة قواعد تصريح التعلم (instruction permit)؟","o":["نقطة واحدة","نقطتان","أربع نقاط","ست نقاط"],"h1":"إنه عدد صغير من النقاط، أكثر من واحدة.","h2":"في North Dakota، القيادة بما يخالف شروط تصريح التعلم تضيف نقطتين إلى سجل قيادتك.","p":"صحيح. مخالفة قواعد التصريح تضيف نقطتين."},"ref":{"doc":"ND","page":4}},{"id":"nd-030","scope":"ND","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In North Dakota, how close to a fire hydrant may you park?","o":["5 feet","10 feet","25 feet","50 feet"],"h1":"It is closer than in many other states.","h2":"In North Dakota you may not park within 10 feet of a fire hydrant.","p":"Right. Stay at least 10 feet from a fire hydrant."},"es":{"q":"En North Dakota, ¿qué tan cerca de un hidrante puede estacionarse?","o":["5 pies","10 pies","25 pies","50 pies"],"h1":"Es más cerca que en muchos otros estados.","h2":"En North Dakota usted no puede estacionarse a menos de 10 pies de un hidrante.","p":"Correcto. Quédese por lo menos a 10 pies de un hidrante."},"zh":{"q":"在 North Dakota，停车时离消防栓（fire hydrant）要多远？","o":["5 英尺","10 英尺","25 英尺","50 英尺"],"h1":"这个距离比很多其他州更近。","h2":"在 North Dakota，你不可以把车停在离消防栓 10 英尺以内的地方。","p":"对。离消防栓至少 10 英尺。"},"vi":{"q":"Ở North Dakota, bạn được đỗ xe cách trụ nước cứu hỏa (fire hydrant) bao xa?","o":["5 feet","10 feet","25 feet","50 feet"],"h1":"Khoảng cách này gần hơn so với nhiều tiểu bang khác.","h2":"Ở North Dakota, bạn không được đỗ xe trong vòng 10 feet tính từ trụ nước cứu hỏa.","p":"Đúng. Hãy cách trụ nước cứu hỏa ít nhất 10 feet."},"tl":{"q":"Sa North Dakota, gaano kalapit sa fire hydrant (gripo ng bumbero) ka puwedeng pumarada?","o":["5 talampakan","10 talampakan","25 talampakan","50 talampakan"],"h1":"Mas malapit ito kaysa sa maraming ibang estado.","h2":"Sa North Dakota, bawal kang pumarada sa loob ng 10 talampakan mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 10 talampakan mula sa fire hydrant."},"ar":{"q":"في North Dakota، على أي مسافة من صنبور إطفاء الحريق (fire hydrant) يمكنك أن تركن سيارتك؟","o":["5 أقدام","10 أقدام","25 قدمًا","50 قدمًا"],"h1":"هذه المسافة أقرب مما هي في كثير من الولايات الأخرى.","h2":"في North Dakota لا يجوز لك أن تركن سيارتك على بعد أقل من 10 أقدام من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بعد 10 أقدام على الأقل من صنبور إطفاء الحريق."},"ref":{"doc":"ND","page":26}},{"id":"nd-031","scope":"ND","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Dakota, how much space must you leave when passing a bicycle?","o":["6 inches","1 foot","2 feet","At least 3 feet"],"h1":"Give the rider room to wobble.","h2":"In North Dakota a driver must leave at least three feet of space when passing a bicycle.","p":"Right. Leave at least 3 feet when you pass a bicycle."},"es":{"q":"En North Dakota, ¿cuánto espacio debe dejar al rebasar una bicicleta?","o":["6 pulgadas","1 pie","2 pies","Por lo menos 3 pies"],"h1":"Dele espacio al ciclista por si se tambalea.","h2":"En North Dakota el conductor debe dejar por lo menos tres pies de espacio al rebasar una bicicleta.","p":"Correcto. Deje por lo menos 3 pies al rebasar una bicicleta."},"zh":{"q":"在 North Dakota，超过自行车时必须留出多大的空间？","o":["6 英寸","1 英尺","2 英尺","至少 3 英尺"],"h1":"给骑车的人留出摇晃的空间。","h2":"在 North Dakota，司机超过自行车时必须留出至少 3 英尺的空间。","p":"对。超过自行车时要留出至少 3 英尺。"},"vi":{"q":"Ở North Dakota, khi vượt xe đạp, bạn phải chừa khoảng cách bao nhiêu?","o":["6 inch","1 foot","2 feet","Ít nhất 3 feet"],"h1":"Hãy chừa chỗ để người đi xe đạp có thể lắc lư.","h2":"Ở North Dakota, tài xế phải chừa khoảng cách ít nhất 3 feet khi vượt xe đạp.","p":"Đúng. Hãy chừa ít nhất 3 feet khi vượt xe đạp."},"tl":{"q":"Sa North Dakota, gaano kalaking espasyo ang dapat mong iwan kapag nag-overtake ka sa bisikleta?","o":["6 pulgada","1 talampakan","2 talampakan","Hindi bababa sa 3 talampakan"],"h1":"Bigyan ng puwang ang siklista kung sakaling gumewang siya.","h2":"Sa North Dakota, dapat mag-iwan ang drayber ng hindi bababa sa 3 talampakang espasyo kapag nag-overtake sa bisikleta.","p":"Tama. Mag-iwan ng hindi bababa sa 3 talampakan kapag nag-overtake ka sa bisikleta."},"ar":{"q":"في North Dakota، ما المسافة التي يجب أن تتركها عندما تتجاوز دراجة هوائية؟","o":["6 بوصات","قدم واحد","قدمان","3 أقدام على الأقل"],"h1":"اترك لراكب الدراجة مساحة إذا تمايل.","h2":"في North Dakota يجب على السائق أن يترك مسافة 3 أقدام على الأقل عندما يتجاوز دراجة هوائية.","p":"صحيح. اترك 3 أقدام على الأقل عندما تتجاوز دراجة هوائية."},"ref":{"doc":"ND","page":33}},{"id":"nd-032","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, where must an open container of alcohol be kept in a car?","o":["In the trunk","Under the driver's seat","In the glove box","In a passenger's hand"],"h1":"It must be out of reach of everyone in the car.","h2":"In North Dakota you may not have an open container of alcohol in the car, so any open container must be put in the trunk.","p":"Right. Open containers go in the trunk."},"es":{"q":"En North Dakota, ¿dónde se debe guardar un envase abierto de alcohol en el carro?","o":["En la cajuela","Debajo del asiento del conductor","En la guantera","En la mano de un pasajero"],"h1":"Debe estar fuera del alcance de todos en el carro.","h2":"En North Dakota no puede llevar un envase abierto de alcohol en el carro, así que cualquier envase abierto debe ir en la cajuela.","p":"Correcto. Los envases abiertos van en la cajuela."},"zh":{"q":"在 North Dakota，车里打开过的酒（open container）必须放在哪里？","o":["后备箱里","司机座位下面","手套箱里","乘客手里"],"h1":"它必须放在车里所有人都够不到的地方。","h2":"在 North Dakota，车里不可以有打开过的酒，所以打开过的酒必须放在后备箱里。","p":"对。打开过的酒要放在后备箱里。"},"vi":{"q":"Ở North Dakota, đồ uống có cồn đã mở (open container) phải được để ở đâu trong xe?","o":["Trong cốp xe","Dưới ghế tài xế","Trong hộc đựng đồ (glove box)","Trong tay hành khách"],"h1":"Nó phải ở ngoài tầm với của mọi người trong xe.","h2":"Ở North Dakota, bạn không được để đồ uống có cồn đã mở trong khoang xe, vì vậy đồ uống có cồn đã mở phải được để trong cốp xe.","p":"Đúng. Đồ uống có cồn đã mở phải để trong cốp xe."},"tl":{"q":"Sa North Dakota, saan dapat ilagay sa kotse ang bukas na lalagyan ng alak (open container)?","o":["Sa trunk (likurang kompartimento)","Sa ilalim ng upuan ng drayber","Sa glove box","Sa kamay ng pasahero"],"h1":"Dapat hindi ito maabot ng sinuman sa loob ng kotse.","h2":"Sa North Dakota, bawal magkaroon ng bukas na lalagyan ng alak sa loob ng kotse, kaya dapat ilagay sa trunk ang anumang bukas na lalagyan.","p":"Tama. Sa trunk inilalagay ang bukas na lalagyan ng alak."},"ar":{"q":"في North Dakota، أين يجب أن يوضع وعاء الكحول المفتوح (open container) في السيارة؟","o":["في صندوق السيارة الخلفي","تحت مقعد السائق","في درج القفازات","في يد أحد الركاب"],"h1":"يجب أن يكون بعيدًا عن متناول كل من في السيارة.","h2":"في North Dakota لا يجوز أن يكون معك وعاء كحول مفتوح داخل السيارة، لذلك يجب وضع أي وعاء مفتوح في صندوق السيارة الخلفي.","p":"صحيح. الأوعية المفتوحة توضع في صندوق السيارة الخلفي."},"ref":{"doc":"ND","page":37}},{"id":"nd-033","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, how early can you renew your license without losing time left on the old one?","o":["1 month before it expires","3 months before it expires","10 months before it expires","2 years before it expires"],"h1":"It is almost a full year.","h2":"In North Dakota you may renew your license up to 10 months before it expires without losing the time left on your old license.","p":"Right. You can renew up to 10 months early."},"es":{"q":"En North Dakota, ¿con cuánta anticipación puede renovar su licencia sin perder el tiempo que le queda a la anterior?","o":["1 mes antes del vencimiento","3 meses antes del vencimiento","10 meses antes del vencimiento","2 años antes del vencimiento"],"h1":"Es casi un año completo.","h2":"En North Dakota usted puede renovar su licencia hasta 10 meses antes del vencimiento sin perder el tiempo que le queda a la licencia anterior.","p":"Correcto. Puede renovar hasta 10 meses antes."},"zh":{"q":"在 North Dakota，最早可以提前多久更新驾照，而不会失去旧驾照剩下的时间？","o":["到期前 1 个月","到期前 3 个月","到期前 10 个月","到期前 2 年"],"h1":"差不多是一整年。","h2":"在 North Dakota，你可以在驾照到期前最多 10 个月更新，而不会失去旧驾照剩下的时间。","p":"对。你最多可以提前 10 个月更新。"},"vi":{"q":"Ở North Dakota, bạn có thể gia hạn bằng lái sớm nhất là bao lâu mà không mất thời gian còn lại của bằng cũ?","o":["1 tháng trước khi hết hạn","3 tháng trước khi hết hạn","10 tháng trước khi hết hạn","2 năm trước khi hết hạn"],"h1":"Gần như trọn một năm.","h2":"Ở North Dakota, bạn có thể gia hạn bằng lái tối đa 10 tháng trước khi hết hạn mà không mất thời gian còn lại của bằng cũ.","p":"Đúng. Bạn có thể gia hạn sớm tối đa 10 tháng."},"tl":{"q":"Sa North Dakota, gaano kaaga ka puwedeng mag-renew ng lisensya nang hindi nawawala ang natitirang panahon ng luma?","o":["1 buwan bago ito mag-expire","3 buwan bago ito mag-expire","10 buwan bago ito mag-expire","2 taon bago ito mag-expire"],"h1":"Halos isang buong taon ito.","h2":"Sa North Dakota, puwede kang mag-renew ng lisensya hanggang 10 buwan bago ito mag-expire nang hindi nawawala ang natitirang panahon ng lumang lisensya.","p":"Tama. Puwede kang mag-renew hanggang 10 buwan nang mas maaga."},"ar":{"q":"في North Dakota، كم مبكرًا يمكنك تجديد رخصتك دون أن تخسر المدة المتبقية في الرخصة القديمة؟","o":["قبل انتهائها بشهر واحد","قبل انتهائها بـ 3 أشهر","قبل انتهائها بـ 10 أشهر","قبل انتهائها بسنتين"],"h1":"إنها تقريبًا سنة كاملة.","h2":"في North Dakota يمكنك تجديد رخصتك قبل انتهائها بمدة تصل إلى 10 أشهر دون أن تخسر المدة المتبقية في رخصتك القديمة.","p":"صحيح. يمكنك التجديد مبكرًا بمدة تصل إلى 10 أشهر."},"ref":{"doc":"ND","page":7}},{"id":"nd-034","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, you just moved here and have a valid license from another state. How long may you drive a car with it?","o":["30 days","60 days","90 days","1 year"],"h1":"It is about two months.","h2":"In North Dakota a new resident may drive with a valid license from another state for 60 days, then must get a North Dakota license.","p":"Right. You have 60 days to get a North Dakota license."},"es":{"q":"En Dakota del Norte, usted acaba de mudarse y tiene una licencia válida de otro estado. ¿Por cuánto tiempo puede manejar un carro con ella?","o":["30 días","60 días","90 días","1 año"],"h1":"Son unos dos meses.","h2":"En Dakota del Norte un nuevo residente puede manejar con una licencia válida de otro estado por 60 días, y después debe sacar una licencia de Dakota del Norte.","p":"Correcto. Usted tiene 60 días para sacar una licencia de Dakota del Norte."},"ref":{"doc":"ND","page":2}},{"id":"nd-035","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, you change your name or address. How soon must you tell the Driver License Division?","o":["Within 10 days","Within 30 days","Within 60 days","At your next renewal"],"h1":"It is less than two weeks.","h2":"In North Dakota you must tell the Driver License Division about a new name or address within 10 days.","p":"Right. Report a new name or address within 10 days."},"es":{"q":"En Dakota del Norte, usted cambia de nombre o de dirección. ¿En cuánto tiempo debe avisar a la División de Licencias de Conducir?","o":["Dentro de 10 días","Dentro de 30 días","Dentro de 60 días","En su próxima renovación"],"h1":"Es menos de dos semanas.","h2":"En Dakota del Norte usted debe avisar a la División de Licencias de Conducir de un nuevo nombre o dirección dentro de 10 días.","p":"Correcto. Avise de un nuevo nombre o dirección dentro de 10 días."},"ref":{"doc":"ND","page":8}},{"id":"nd-036","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, you are driving with an instruction permit. Who may sit in the front seat with you?","o":["Any passenger who wears a seat belt","Any passenger 16 or older","Only the supervising driver, unless the vehicle has only a front seat","Anyone, if the back seat is full"],"h1":"The front seat is kept for the person who is teaching you.","h2":"In North Dakota only the supervising driver may sit in the front seat with a permit holder, unless the vehicle has only a front seat.","p":"Right. Only the supervising driver sits up front with you."},"es":{"q":"En Dakota del Norte, usted maneja con un permiso de aprendizaje. ¿Quién puede ir en el asiento delantero con usted?","o":["Cualquier pasajero que use el cinturón","Cualquier pasajero de 16 años o más","Solo el conductor que lo supervisa, a menos que el vehículo tenga solo asiento delantero","Cualquier persona, si el asiento de atrás está lleno"],"h1":"El asiento delantero es para la persona que le enseña.","h2":"En Dakota del Norte solo el conductor que supervisa puede ir en el asiento delantero con quien tiene un permiso, a menos que el vehículo tenga solo asiento delantero.","p":"Correcto. Solo el conductor que lo supervisa va adelante con usted."},"ref":{"doc":"ND","page":3}},{"id":"nd-037","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, how can you have the Class D road test waived?","o":["Pass the knowledge test with a perfect score","Hold your permit for two years","Log 100 hours of driving with a parent","Show a certificate from an approved course with 30 hours of classroom and 6 hours behind the wheel"],"h1":"Think of a driver training course with both class time and driving time.","h2":"In North Dakota the road test can be waived with a certificate from an approved course of at least 30 hours of classroom and 6 hours of behind-the-wheel training.","p":"Right. An approved 30-hour classroom and 6-hour driving course can waive the road test."},"es":{"q":"En Dakota del Norte, ¿cómo puede usted quedar exento del examen de manejo de la Clase D?","o":["Aprobar el examen escrito con una nota perfecta","Tener el permiso por dos años","Anotar 100 horas de manejo con un padre","Mostrar un certificado de un curso aprobado con 30 horas de clase y 6 horas al volante"],"h1":"Piense en un curso de manejo con horas de clase y horas manejando.","h2":"En Dakota del Norte se puede omitir el examen de manejo con un certificado de un curso aprobado de al menos 30 horas de clase y 6 horas de práctica al volante.","p":"Correcto. Un curso aprobado de 30 horas de clase y 6 horas al volante puede reemplazar el examen de manejo."},"ref":{"doc":"ND","page":4}},{"id":"nd-038","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, how many points can an approved driver improvement course, such as a defensive driving course, take off your record?","o":["1 point","3 points","6 points","All of your points"],"h1":"It is more than the one point you get back after three months with no new points.","h2":"In North Dakota finishing an approved driver improvement course takes 3 points off your driving record.","p":"Right. The course takes off 3 points."},"es":{"q":"En Dakota del Norte, ¿cuántos puntos puede quitar de su récord un curso aprobado de mejoramiento del conductor, como un curso de manejo defensivo?","o":["1 punto","3 puntos","6 puntos","Todos sus puntos"],"h1":"Es más que el punto que se quita después de tres meses sin puntos nuevos.","h2":"En Dakota del Norte terminar un curso aprobado de mejoramiento del conductor quita 3 puntos de su récord de manejo.","p":"Correcto. El curso quita 3 puntos."},"ref":{"doc":"ND","page":40}},{"id":"nd-039","scope":"ND","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Dakota, what is the fine for throwing litter on a public highway?","o":["$50","$100","$500","$1,000"],"h1":"It is several hundred dollars.","h2":"In North Dakota throwing litter on a public highway can bring a $500 fine.","p":"Right. Littering on a highway can cost $500."},"es":{"q":"En Dakota del Norte, ¿cuál es la multa por tirar basura en una carretera pública?","o":["$50","$100","$500","$1,000"],"h1":"Son varios cientos de dólares.","h2":"En Dakota del Norte tirar basura en una carretera pública puede costar una multa de $500.","p":"Correcto. Tirar basura en la carretera puede costar $500."},"ref":{"doc":"ND","page":27}},{"id":"nd-040","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, what is the fine for driving onto a road that is officially closed because of dangerous conditions?","o":["$250","$50","$100","$1,000"],"h1":"It is more than $200.","h2":"In North Dakota driving onto a road that is officially closed for dangerous conditions brings a $250 fine.","p":"Right. Entering a closed road costs $250."},"es":{"q":"En Dakota del Norte, ¿cuál es la multa por entrar a una carretera cerrada oficialmente por condiciones peligrosas?","o":["$250","$50","$100","$1,000"],"h1":"Es más de $200.","h2":"En Dakota del Norte entrar a una carretera cerrada oficialmente por condiciones peligrosas trae una multa de $250.","p":"Correcto. Entrar a una carretera cerrada cuesta $250."},"ref":{"doc":"ND","page":27}},{"id":"nd-041","scope":"ND","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Dakota, when may you use studded snow tires?","o":["All year","From November 1 to March 1","Only when snow is on the road","From October 15 to April 15"],"h1":"The season starts in the middle of October.","h2":"In North Dakota studded snow tires may be used from October 15 to April 15.","p":"Right. Studded tires are allowed from October 15 to April 15."},"es":{"q":"En Dakota del Norte, ¿cuándo puede usar llantas de nieve con clavos?","o":["Todo el año","Del 1 de noviembre al 1 de marzo","Solo cuando hay nieve en la carretera","Del 15 de octubre al 15 de abril"],"h1":"La temporada empieza a mediados de octubre.","h2":"En Dakota del Norte las llantas de nieve con clavos se pueden usar del 15 de octubre al 15 de abril.","p":"Correcto. Las llantas con clavos se permiten del 15 de octubre al 15 de abril."},"ref":{"doc":"ND","page":28}},{"id":"nd-042","scope":"ND","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Dakota, your car gets stuck in a snowstorm. What should you do?","o":["Walk to the nearest house for help","Stay with the car and run the engine and heater only for short times, with a window open a little","Run the engine the whole time with all windows closed","Leave the car and follow the road on foot"],"h1":"Most deaths happen when people leave their cars and get lost.","h2":"In North Dakota, if you are stuck in a snowstorm, you should stay with your car and run the engine and heater only for short times, with a window slightly open.","p":"Right. Stay with the car and run the heater only now and then, with a window open a little."},"es":{"q":"En Dakota del Norte, su carro se queda atascado en una tormenta de nieve. ¿Qué debe hacer?","o":["Caminar a la casa más cercana para pedir ayuda","Quedarse con el carro y prender el motor y la calefacción solo por ratos cortos, con una ventana un poco abierta","Dejar el motor prendido todo el tiempo con las ventanas cerradas","Dejar el carro y seguir la carretera a pie"],"h1":"La mayoría de las muertes ocurren cuando la gente deja el carro y se pierde.","h2":"En Dakota del Norte, si usted queda atascado en una tormenta de nieve, debe quedarse con el carro y prender el motor y la calefacción solo por ratos cortos, con una ventana un poco abierta.","p":"Correcto. Quédese con el carro y use la calefacción solo por ratos, con una ventana un poco abierta."},"ref":{"doc":"ND","page":28}},{"id":"nd-043","scope":"ND","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Dakota, a driver has a first offense in seven years with an alcohol level of 0.08 percent (below 0.18). How long is the license suspended?","o":["30 days","1 year","91 days","2 years"],"h1":"It is about three months.","h2":"In North Dakota a first offense in seven years at 0.08 percent or more, but below 0.18, brings a 91-day license suspension.","p":"Right. A first offense brings a 91-day suspension."},"es":{"q":"En Dakota del Norte, un conductor tiene una primera infracción en siete años con un nivel de alcohol de 0.08 por ciento (menos de 0.18). ¿Por cuánto tiempo se suspende la licencia?","o":["30 días","1 año","91 días","2 años"],"h1":"Son unos tres meses.","h2":"En Dakota del Norte una primera infracción en siete años con 0.08 por ciento o más, pero menos de 0.18, trae una suspensión de la licencia de 91 días.","p":"Correcto. Una primera infracción trae una suspensión de 91 días."},"ref":{"doc":"ND","page":36}},{"id":"nd-044","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, what is the penalty for the driver when a child is not buckled in as the child passenger law requires?","o":["A $25 fine and one point on the license","A warning only","A $500 fine and a license suspension","Two points and no fine"],"h1":"The fine is small, but it also goes on your record.","h2":"In North Dakota breaking the child passenger safety law costs the driver a $25 fine and one point on the license.","p":"Right. It is a $25 fine and one point."},"es":{"q":"En Dakota del Norte, ¿cuál es la sanción para el conductor cuando un niño no va asegurado como exige la ley de pasajeros infantiles?","o":["Una multa de $25 y un punto en la licencia","Solo una advertencia","Una multa de $500 y la suspensión de la licencia","Dos puntos y ninguna multa"],"h1":"La multa es pequeña, pero también va a su récord.","h2":"En Dakota del Norte violar la ley de seguridad de pasajeros infantiles le cuesta al conductor una multa de $25 y un punto en la licencia.","p":"Correcto. Es una multa de $25 y un punto."},"ref":{"doc":"ND","page":34}},{"id":"nd-045","scope":"ND","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Dakota, in rain, snow or fog, you should turn on your headlights when you cannot see clearly for how far?","o":["200 feet","500 feet","2,000 feet","1,000 feet"],"h1":"It is a little less than a fifth of a mile.","h2":"In North Dakota you should use your headlights in bad weather when you cannot see clearly for 1,000 feet.","p":"Right. Lights on when you cannot see 1,000 feet ahead."},"es":{"q":"En Dakota del Norte, con lluvia, nieve o niebla, ¿debe prender las luces delanteras cuando no puede ver con claridad a qué distancia?","o":["200 pies","500 pies","2,000 pies","1,000 pies"],"h1":"Es un poco menos de un quinto de milla.","h2":"En Dakota del Norte usted debe usar las luces delanteras con mal tiempo cuando no puede ver con claridad a 1,000 pies.","p":"Correcto. Prenda las luces cuando no pueda ver a 1,000 pies."},"ref":{"doc":"ND","page":24}},{"id":"nd-046","scope":"ND","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In North Dakota, what is the speed limit in a business or residential district when no sign says otherwise?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"It is a quarter of 100.","h2":"In North Dakota the speed limit in a business or residential district is 25 mph unless a sign says otherwise.","p":"Right. It is 25 mph in town unless posted."},"es":{"q":"En Dakota del Norte, ¿cuál es el límite de velocidad en una zona comercial o residencial cuando no hay un letrero que diga otra cosa?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Es la cuarta parte de 100.","h2":"En Dakota del Norte el límite de velocidad en una zona comercial o residencial es de 25 mph, a menos que un letrero diga otra cosa.","p":"Correcto. Son 25 mph en la ciudad si no hay otro letrero."},"ref":{"doc":"ND","page":20}},{"id":"nd-047","scope":"ND","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In North Dakota, you are coming up to a railroad crossing and your view of the track is blocked. What is the speed limit, unless a sign says otherwise?","o":["10 mph","30 mph","20 mph","35 mph"],"h1":"It is the same as the limit near a school at recess.","h2":"In North Dakota the speed limit is 20 mph when you approach a railroad crossing and cannot see the track clearly, unless a sign says otherwise.","p":"Right. Slow to 20 mph when you cannot see the track."},"es":{"q":"En Dakota del Norte, usted se acerca a un cruce de ferrocarril y no puede ver bien la vía. ¿Cuál es el límite de velocidad, a menos que un letrero diga otra cosa?","o":["10 mph","30 mph","20 mph","35 mph"],"h1":"Es igual al límite cerca de una escuela durante el recreo.","h2":"En Dakota del Norte el límite de velocidad es de 20 mph al acercarse a un cruce de ferrocarril cuando no puede ver bien la vía, a menos que un letrero diga otra cosa.","p":"Correcto. Baje a 20 mph cuando no pueda ver la vía."},"ref":{"doc":"ND","page":20}},{"id":"nd-048","scope":"ND","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In North Dakota, what is the speed limit on a paved, divided highway with more than one lane each way (not an interstate), unless a sign says otherwise?","o":["55 mph","65 mph","80 mph","70 mph"],"h1":"It is 10 mph less than on rural interstates.","h2":"In North Dakota the speed limit on a paved, divided multi-lane highway is 70 mph unless a sign says otherwise.","p":"Right. It is 70 mph on divided multi-lane highways."},"es":{"q":"En Dakota del Norte, ¿cuál es el límite de velocidad en una carretera pavimentada y dividida con más de un carril en cada sentido (que no es interestatal), a menos que un letrero diga otra cosa?","o":["55 mph","65 mph","80 mph","70 mph"],"h1":"Es 10 mph menos que en las interestatales rurales.","h2":"En Dakota del Norte el límite de velocidad en una carretera pavimentada y dividida de varios carriles es de 70 mph, a menos que un letrero diga otra cosa.","p":"Correcto. Son 70 mph en carreteras divididas de varios carriles."},"ref":{"doc":"ND","page":20}},{"id":"nd-049","scope":"ND","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In North Dakota, how close to a stop sign or a traffic signal at the side of the road may you park?","o":["No closer than 15 feet","No closer than 5 feet","No closer than 30 feet","No closer than 50 feet"],"h1":"It is more than the distance for a fire hydrant.","h2":"In North Dakota you may not park within 15 feet of a stop sign, a flashing beacon or a traffic signal at the side of the road.","p":"Right. Stay at least 15 feet from a stop sign or signal."},"es":{"q":"En Dakota del Norte, ¿qué tan cerca de un letrero de alto o de un semáforo al lado de la calle puede estacionarse?","o":["A no menos de 15 pies","A no menos de 5 pies","A no menos de 30 pies","A no menos de 50 pies"],"h1":"Es más que la distancia para un hidrante.","h2":"En Dakota del Norte usted no puede estacionarse a menos de 15 pies de un letrero de alto, una luz intermitente o un semáforo al lado de la calle.","p":"Correcto. Quédese por lo menos a 15 pies de un letrero de alto o un semáforo."},"ref":{"doc":"ND","page":26}},{"id":"nd-050","scope":"ND","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In North Dakota, you are passing on a two-lane road. How far ahead of an oncoming vehicle should you be back in your own lane?","o":["At least 50 feet","At least 100 feet","At least 200 feet","At least 1,000 feet"],"h1":"It is about the length of ten cars.","h2":"In North Dakota you should finish passing and be back in your lane at least 200 feet before you meet an oncoming vehicle.","p":"Right. Be back in your lane at least 200 feet before oncoming traffic."},"es":{"q":"En Dakota del Norte, usted está rebasando en una carretera de dos carriles. ¿A qué distancia de un vehículo que viene de frente debe estar ya de vuelta en su carril?","o":["Por lo menos 50 pies","Por lo menos 100 pies","Por lo menos 200 pies","Por lo menos 1,000 pies"],"h1":"Es más o menos el largo de diez carros.","h2":"En Dakota del Norte usted debe terminar de rebasar y estar de vuelta en su carril por lo menos 200 pies antes de encontrarse con un vehículo que viene de frente.","p":"Correcto. Vuelva a su carril por lo menos 200 pies antes del tráfico que viene de frente."},"ref":{"doc":"ND","page":21}},{"id":"nd-051","scope":"ND","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In North Dakota, on a two-lane road, a police car is parked at a crash with its emergency lights flashing. No officer is directing traffic. What must you do?","o":["Keep going at the same speed","Drive to the right side of the road and stop, then pass with care when the road is clear","Honk and pass quickly","Stop in your lane until the police car leaves"],"h1":"First you stop at the edge of the road; then you may go on carefully.","h2":"In North Dakota you must drive to the right side of the road and stop for an emergency vehicle parked at a crash with its lights flashing, then you may pass with care when the road is clear.","p":"Right. Pull right and stop, then pass with care when it is clear."},"es":{"q":"En Dakota del Norte, en una carretera de dos carriles, un carro de policía está estacionado en un choque con sus luces de emergencia encendidas. Ningún oficial dirige el tráfico. ¿Qué debe hacer?","o":["Seguir a la misma velocidad","Ir al lado derecho de la carretera y detenerse, y luego pasar con cuidado cuando el camino esté libre","Tocar la bocina y pasar rápido","Detenerse en su carril hasta que el carro de policía se vaya"],"h1":"Primero se detiene a la orilla del camino; después puede seguir con cuidado.","h2":"En Dakota del Norte usted debe ir al lado derecho de la carretera y detenerse ante un vehículo de emergencia estacionado en un choque con las luces encendidas, y luego puede pasar con cuidado cuando el camino esté libre.","p":"Correcto. Oríllese a la derecha y deténgase, y luego pase con cuidado cuando esté libre."},"ref":{"doc":"ND","page":20}},{"id":"nd-052","scope":"ND","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In North Dakota, which vehicles must always stop at a railroad crossing, so you should not pass them there?","o":["Only vehicles pulling a trailer","Only motorcycles","All pickup trucks","School buses, buses with passengers, and trucks carrying fuel or explosives"],"h1":"Think of vehicles that carry children, many people, or dangerous loads.","h2":"In North Dakota school buses, buses carrying passengers, and vehicles carrying explosives or flammable liquids must stop between 15 and 50 feet from the tracks, so you should not pass them there.","p":"Right. School buses, passenger buses, and fuel or explosive trucks always stop at the tracks."},"es":{"q":"En Dakota del Norte, ¿qué vehículos deben detenerse siempre en un cruce de ferrocarril, por lo que usted no debe rebasarlos allí?","o":["Solo los vehículos que jalan un remolque","Solo las motocicletas","Todas las camionetas pickup","Los autobuses escolares, los autobuses con pasajeros y los camiones con combustible o explosivos"],"h1":"Piense en vehículos que llevan niños, mucha gente o cargas peligrosas.","h2":"En Dakota del Norte los autobuses escolares, los autobuses con pasajeros y los vehículos con explosivos o líquidos inflamables deben detenerse a entre 15 y 50 pies de la vía, por lo que usted no debe rebasarlos allí.","p":"Correcto. Los autobuses escolares, los de pasajeros y los camiones con combustible o explosivos siempre se detienen en la vía."},"ref":{"doc":"ND","page":18}},{"id":"ne-001","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, what is the youngest age to get a learner's permit (LPD)?","o":["13 years old","14 years old","15 years old","16 years old"],"h1":"It is one year before the provisional permit.","h2":"In Nebraska you can get a learner's permit (LPD) at 15 years old.","p":"Right. The LPD starts at 15."},"es":{"q":"En Nebraska, ¿cuál es la edad mínima para obtener el permiso de aprendiz (LPD)?","o":["13 años","14 años","15 años","16 años"],"h1":"Es un año antes del permiso provisional.","h2":"En Nebraska puede obtener un permiso de aprendiz (LPD) a los 15 años.","p":"Correcto. El LPD empieza a los 15."},"zh":{"q":"在 Nebraska，最小几岁可以拿到学习驾照（LPD）？","o":["13 岁","14 岁","15 岁","16 岁"],"h1":"它比临时驾照早一年。","h2":"在 Nebraska，你 15 岁就可以拿到学习驾照（LPD）。","p":"对。LPD 从 15 岁开始。"},"vi":{"q":"Ở Nebraska, tuổi nhỏ nhất để có giấy phép tập lái (learner's permit, LPD) là bao nhiêu?","o":["13 tuổi","14 tuổi","15 tuổi","16 tuổi"],"h1":"Đó là một năm trước giấy phép tạm thời (provisional permit).","h2":"Ở Nebraska, bạn có thể có giấy phép tập lái (LPD) khi 15 tuổi.","p":"Đúng. LPD bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Nebraska, ano ang pinakabatang edad para makakuha ng learner's permit (LPD)?","o":["13 taong gulang","14 taong gulang","15 taong gulang","16 taong gulang"],"h1":"Isang taon ito bago ang provisional permit.","h2":"Sa Nebraska, makakakuha ka ng learner's permit (LPD) sa edad na 15.","p":"Tama. Nagsisimula ang LPD sa 15."},"ar":{"q":"في Nebraska، ما أصغر عمر للحصول على تصريح التعلّم (learner's permit, LPD)؟","o":["13 سنة","14 سنة","15 سنة","16 سنة"],"h1":"إنه قبل التصريح المؤقت (provisional permit) بسنة واحدة.","h2":"في Nebraska يمكنك الحصول على تصريح التعلّم (LPD) في عمر 15 سنة.","p":"صحيح. يبدأ تصريح LPD من عمر 15 سنة."},"ref":{"doc":"NE","page":3}},{"id":"ne-002","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, what is the youngest age for a school learner's permit (LPE), used to practice for driving to school?","o":["13 years old","14 years old","15 years old","16 years old"],"h1":"It comes one year before the regular learner's permit.","h2":"In Nebraska a teen can get a school learner's permit (LPE) at 14, so they can practice for driving to school.","p":"Right. The school learner's permit starts at 14."},"es":{"q":"En Nebraska, ¿cuál es la edad mínima para el permiso escolar de aprendiz (LPE), que sirve para practicar para manejar a la escuela?","o":["13 años","14 años","15 años","16 años"],"h1":"Llega un año antes del permiso de aprendiz normal.","h2":"En Nebraska un adolescente puede obtener el permiso escolar de aprendiz (LPE) a los 14 años, para practicar para manejar a la escuela.","p":"Correcto. El permiso escolar de aprendiz empieza a los 14."},"zh":{"q":"在 Nebraska，用来练习开车上学的学校学习驾照（LPE），最小几岁可以拿？","o":["13 岁","14 岁","15 岁","16 岁"],"h1":"它比普通学习驾照早一年。","h2":"在 Nebraska，青少年 14 岁就可以拿到学校学习驾照（LPE），这样他们可以练习开车上学。","p":"对。学校学习驾照从 14 岁开始。"},"vi":{"q":"Ở Nebraska, tuổi nhỏ nhất để có giấy phép tập lái đi học (school learner's permit, LPE), dùng để tập lái xe đến trường, là bao nhiêu?","o":["13 tuổi","14 tuổi","15 tuổi","16 tuổi"],"h1":"Nó đến một năm trước giấy phép tập lái thông thường.","h2":"Ở Nebraska, thiếu niên có thể có giấy phép tập lái đi học (LPE) khi 14 tuổi, để tập lái xe đến trường.","p":"Đúng. Giấy phép tập lái đi học bắt đầu từ 14 tuổi."},"tl":{"q":"Sa Nebraska, ano ang pinakabatang edad para sa school learner's permit (LPE), na ginagamit para magsanay sa pagmamaneho papunta sa paaralan?","o":["13 taong gulang","14 taong gulang","15 taong gulang","16 taong gulang"],"h1":"Isang taon ito bago ang karaniwang learner's permit.","h2":"Sa Nebraska, makakakuha ang isang tinedyer ng school learner's permit (LPE) sa edad na 14, para makapagsanay sa pagmamaneho papunta sa paaralan.","p":"Tama. Nagsisimula ang school learner's permit sa 14."},"ar":{"q":"في Nebraska، ما أصغر عمر للحصول على تصريح التعلّم المدرسي (school learner's permit, LPE)، الذي يُستخدم للتدرّب على القيادة إلى المدرسة؟","o":["13 سنة","14 سنة","15 سنة","16 سنة"],"h1":"إنه قبل تصريح التعلّم العادي بسنة واحدة.","h2":"في Nebraska يمكن للمراهق الحصول على تصريح التعلّم المدرسي (LPE) في عمر 14 سنة، ليتدرّب على القيادة إلى المدرسة.","p":"صحيح. يبدأ تصريح التعلّم المدرسي من عمر 14 سنة."},"ref":{"doc":"NE","page":2}},{"id":"ne-003","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, who must sit in the front passenger seat when a teen drives with a learner's permit (LPD)?","o":["Any passenger with a permit","A licensed driver 18 or older","Any adult, licensed or not","A licensed driver 21 or older"],"h1":"The helper must be an adult who can legally drink.","h2":"A Nebraska LPD holder must always drive with a licensed adult who is at least 21 in the front passenger seat.","p":"Right. A licensed adult 21 or older beside you."},"es":{"q":"En Nebraska, ¿quién debe ir en el asiento delantero del pasajero cuando un adolescente maneja con permiso de aprendiz (LPD)?","o":["Cualquier pasajero con permiso","Un conductor con licencia de 18 años o más","Cualquier adulto, con o sin licencia","Un conductor con licencia de 21 años o más"],"h1":"El acompañante debe ser un adulto que ya puede tomar alcohol legalmente.","h2":"Quien tiene un LPD en Nebraska siempre debe manejar con un adulto con licencia de por lo menos 21 años en el asiento delantero del pasajero.","p":"Correcto. Un adulto con licencia de 21 años o más a su lado."},"zh":{"q":"在 Nebraska，青少年持学习驾照（LPD）开车时，谁必须坐在前排乘客座位？","o":["任何有学习驾照的乘客","18 岁或以上、有驾照的司机","任何成年人，有没有驾照都可以","21 岁或以上、有驾照的司机"],"h1":"陪同的人必须是在法律上可以喝酒的成年人。","h2":"Nebraska 持 LPD 的人开车时，前排乘客座位上必须一直有一位至少 21 岁、有驾照的成年人。","p":"对。一位 21 岁或以上、有驾照的成年人坐在你旁边。"},"vi":{"q":"Ở Nebraska, ai phải ngồi ở ghế hành khách phía trước khi thiếu niên lái xe với giấy phép tập lái (LPD)?","o":["Bất kỳ hành khách nào có giấy phép tập lái","Một tài xế có bằng lái, từ 18 tuổi trở lên","Bất kỳ người lớn nào, có bằng lái hay không","Một tài xế có bằng lái, từ 21 tuổi trở lên"],"h1":"Người hướng dẫn phải là người lớn đủ tuổi uống rượu hợp pháp.","h2":"Người có LPD ở Nebraska luôn phải lái xe với một người lớn có bằng lái, ít nhất 21 tuổi, ngồi ở ghế hành khách phía trước.","p":"Đúng. Một người lớn có bằng lái, từ 21 tuổi trở lên, ngồi bên cạnh bạn."},"tl":{"q":"Sa Nebraska, sino ang dapat umupo sa harap na upuan ng pasahero kapag nagmamaneho ang isang tinedyer na may learner's permit (LPD)?","o":["Kahit sinong pasahero na may permit","Isang lisensyadong drayber na 18 taong gulang o higit pa","Kahit sinong adulto, may lisensya man o wala","Isang lisensyadong drayber na 21 taong gulang o higit pa"],"h1":"Ang tumutulong ay dapat adultong legal nang uminom ng alak.","h2":"Ang may hawak ng LPD sa Nebraska ay dapat laging magmaneho kasama ang isang lisensyadong adulto na hindi bababa sa 21 taong gulang sa harap na upuan ng pasahero.","p":"Tama. Isang lisensyadong adulto na 21 o higit pa sa tabi mo."},"ar":{"q":"في Nebraska، من يجب أن يجلس في مقعد الراكب الأمامي عندما يقود مراهق بتصريح التعلّم (LPD)؟","o":["أي راكب معه تصريح","سائق مرخّص عمره 18 سنة أو أكثر","أي شخص بالغ، مرخّص أو غير مرخّص","سائق مرخّص عمره 21 سنة أو أكثر"],"h1":"يجب أن يكون المرافق شخصاً بالغاً يحق له قانونياً شرب الكحول.","h2":"يجب على حامل تصريح LPD في Nebraska أن يقود دائماً مع شخص بالغ مرخّص عمره 21 سنة على الأقل في مقعد الراكب الأمامي.","p":"صحيح. شخص بالغ مرخّص عمره 21 سنة أو أكثر بجانبك."},"ref":{"doc":"NE","page":4}},{"id":"ne-004","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, what is the youngest age for a provisional operator's permit (POP), which lets a teen drive alone?","o":["16 years old","15 years old","17 years old","18 years old"],"h1":"It is the most common age for a first license.","h2":"In Nebraska you must be at least 16 to get a provisional operator's permit (POP).","p":"Right. The POP starts at 16."},"es":{"q":"En Nebraska, ¿cuál es la edad mínima para el permiso provisional de operador (POP), que permite manejar solo?","o":["16 años","15 años","17 años","18 años"],"h1":"Es la edad más común para la primera licencia.","h2":"En Nebraska usted debe tener por lo menos 16 años para obtener el permiso provisional de operador (POP).","p":"Correcto. El POP empieza a los 16."},"zh":{"q":"在 Nebraska，可以让青少年单独开车的临时驾照（POP），最小几岁可以拿？","o":["16 岁","15 岁","17 岁","18 岁"],"h1":"这是拿第一张驾照最常见的年龄。","h2":"在 Nebraska，你必须至少 16 岁才能拿到临时驾照（POP）。","p":"对。POP 从 16 岁开始。"},"vi":{"q":"Ở Nebraska, tuổi nhỏ nhất để có giấy phép lái xe tạm thời (provisional operator's permit, POP), cho phép thiếu niên lái xe một mình, là bao nhiêu?","o":["16 tuổi","15 tuổi","17 tuổi","18 tuổi"],"h1":"Đó là tuổi phổ biến nhất để có bằng lái đầu tiên.","h2":"Ở Nebraska, bạn phải ít nhất 16 tuổi để có giấy phép lái xe tạm thời (POP).","p":"Đúng. POP bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Nebraska, ano ang pinakabatang edad para sa provisional operator's permit (POP), na nagpapahintulot sa tinedyer na magmaneho nang mag-isa?","o":["16 taong gulang","15 taong gulang","17 taong gulang","18 taong gulang"],"h1":"Ito ang pinakakaraniwang edad para sa unang lisensya.","h2":"Sa Nebraska, dapat ay hindi bababa sa 16 taong gulang ka para makakuha ng provisional operator's permit (POP).","p":"Tama. Nagsisimula ang POP sa 16."},"ar":{"q":"في Nebraska، ما أصغر عمر للحصول على تصريح القيادة المؤقت (provisional operator's permit, POP)، الذي يسمح للمراهق بالقيادة وحده؟","o":["16 سنة","15 سنة","17 سنة","18 سنة"],"h1":"إنه العمر الأكثر شيوعاً لأول رخصة.","h2":"في Nebraska يجب أن يكون عمرك 16 سنة على الأقل للحصول على تصريح القيادة المؤقت (POP).","p":"صحيح. يبدأ تصريح POP من عمر 16 سنة."},"ref":{"doc":"NE","page":4}},{"id":"ne-005","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, how long must a teen hold a learner's permit before getting a provisional operator's permit (POP)?","o":["3 months","6 months","9 months","12 months"],"h1":"It is half a year.","h2":"A Nebraska teen must hold a learner's permit for at least 6 months before getting a provisional operator's permit.","p":"Right. Six months with the permit."},"es":{"q":"En Nebraska, ¿cuánto tiempo debe tener un adolescente el permiso de aprendiz antes del permiso provisional de operador (POP)?","o":["3 meses","6 meses","9 meses","12 meses"],"h1":"Es medio año.","h2":"Un adolescente en Nebraska debe tener el permiso de aprendiz por lo menos 6 meses antes de obtener el permiso provisional de operador.","p":"Correcto. Seis meses con el permiso."},"zh":{"q":"在 Nebraska，青少年必须持有学习驾照多久，才能拿到临时驾照（POP）？","o":["3 个月","6 个月","9 个月","12 个月"],"h1":"是半年。","h2":"Nebraska 的青少年必须持有学习驾照至少 6 个月，才能拿到临时驾照。","p":"对。持有学习驾照六个月。"},"vi":{"q":"Ở Nebraska, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi có giấy phép lái xe tạm thời (POP)?","o":["3 tháng","6 tháng","9 tháng","12 tháng"],"h1":"Đó là nửa năm.","h2":"Thiếu niên ở Nebraska phải giữ giấy phép tập lái ít nhất 6 tháng trước khi có giấy phép lái xe tạm thời.","p":"Đúng. Sáu tháng với giấy phép tập lái."},"tl":{"q":"Sa Nebraska, gaano katagal dapat hawak ng tinedyer ang learner's permit bago makakuha ng provisional operator's permit (POP)?","o":["3 buwan","6 na buwan","9 na buwan","12 buwan"],"h1":"Kalahating taon ito.","h2":"Ang tinedyer sa Nebraska ay dapat humawak ng learner's permit nang hindi bababa sa 6 na buwan bago makakuha ng provisional operator's permit.","p":"Tama. Anim na buwan na may permit."},"ar":{"q":"في Nebraska، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل الحصول على تصريح القيادة المؤقت (POP)؟","o":["3 أشهر","6 أشهر","9 أشهر","12 شهراً"],"h1":"إنها نصف سنة.","h2":"يجب على المراهق في Nebraska أن يحمل تصريح التعلّم 6 أشهر على الأقل قبل الحصول على تصريح القيادة المؤقت.","p":"صحيح. ستة أشهر مع التصريح."},"ref":{"doc":"NE","page":4}},{"id":"ne-006","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, if a teen does not take an approved driver safety course, how many hours of supervised driving must be logged for a POP?","o":["20 hours","30 hours","50 hours","100 hours"],"h1":"It is the same as a full work week plus ten.","h2":"A Nebraska teen who skips the approved driver safety course must log 50 hours of supervised driving to get a provisional operator's permit.","p":"Right. 50 logged hours."},"es":{"q":"En Nebraska, si un adolescente no toma un curso aprobado de seguridad vial, ¿cuántas horas de manejo supervisado debe registrar para el POP?","o":["20 horas","30 horas","50 horas","100 horas"],"h1":"Es lo mismo que una semana completa de trabajo más diez.","h2":"Un adolescente en Nebraska que no toma el curso aprobado de seguridad vial debe registrar 50 horas de manejo supervisado para obtener el permiso provisional de operador.","p":"Correcto. 50 horas registradas."},"zh":{"q":"在 Nebraska，如果青少年没有上批准的驾驶安全课程，要拿 POP 必须记录多少小时有人监督的驾驶？","o":["20 小时","30 小时","50 小时","100 小时"],"h1":"它等于一个完整工作周的时间再加十。","h2":"Nebraska 的青少年如果不上批准的驾驶安全课程，必须记录 50 小时有人监督的驾驶，才能拿到临时驾照。","p":"对。记录 50 小时。"},"vi":{"q":"Ở Nebraska, nếu thiếu niên không học khóa an toàn lái xe được chấp thuận, phải ghi lại bao nhiêu giờ lái xe có giám sát để có POP?","o":["20 giờ","30 giờ","50 giờ","100 giờ"],"h1":"Nó bằng một tuần làm việc đầy đủ cộng thêm mười.","h2":"Thiếu niên ở Nebraska không học khóa an toàn lái xe được chấp thuận phải ghi lại 50 giờ lái xe có giám sát để có giấy phép lái xe tạm thời.","p":"Đúng. 50 giờ được ghi lại."},"tl":{"q":"Sa Nebraska, kung hindi kumuha ang tinedyer ng aprubadong kurso sa ligtas na pagmamaneho, ilang oras ng pagmamanehong may gabay ang dapat itala para sa POP?","o":["20 oras","30 oras","50 oras","100 oras"],"h1":"Kapareho ito ng isang buong linggo ng trabaho at dagdag na sampu.","h2":"Ang tinedyer sa Nebraska na hindi kumuha ng aprubadong kurso sa ligtas na pagmamaneho ay dapat magtala ng 50 oras ng pagmamanehong may gabay para makakuha ng provisional operator's permit.","p":"Tama. 50 oras na naitala."},"ar":{"q":"في Nebraska، إذا لم يأخذ المراهق دورة سلامة قيادة معتمدة، كم ساعة من القيادة تحت الإشراف يجب أن يسجّل للحصول على تصريح POP؟","o":["20 ساعة","30 ساعة","50 ساعة","100 ساعة"],"h1":"إنها مثل أسبوع عمل كامل وزيادة عشرة.","h2":"المراهق في Nebraska الذي لا يأخذ دورة سلامة القيادة المعتمدة يجب أن يسجّل 50 ساعة من القيادة تحت الإشراف للحصول على تصريح القيادة المؤقت.","p":"صحيح. 50 ساعة مسجّلة."},"ref":{"doc":"NE","page":4}},{"id":"ne-007","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, who must sign the 50-hour driving log for a provisional operator's permit?","o":["The teen driver","A teacher at school","A DMV examiner","A licensed driver at least 21 years old"],"h1":"It is the same kind of person who supervises practice.","h2":"The Nebraska 50-hour driving form must be signed by a parent, a guardian, or a licensed driver who is at least 21 years old.","p":"Right. A licensed driver 21 or older signs it."},"es":{"q":"En Nebraska, ¿quién debe firmar el registro de 50 horas de manejo para el permiso provisional de operador?","o":["El conductor adolescente","Un maestro de la escuela","Un examinador del DMV","Un conductor con licencia de por lo menos 21 años"],"h1":"Es el mismo tipo de persona que supervisa la práctica.","h2":"El formulario de 50 horas de manejo en Nebraska debe firmarlo uno de los padres, un tutor o un conductor con licencia de por lo menos 21 años.","p":"Correcto. Lo firma un conductor con licencia de 21 años o más."},"zh":{"q":"在 Nebraska，临时驾照的 50 小时驾驶记录必须由谁签名？","o":["青少年司机自己","学校的老师","DMV 考官","至少 21 岁、有驾照的司机"],"h1":"和陪同练习的是同一种人。","h2":"Nebraska 的 50 小时驾驶表必须由父母、监护人，或至少 21 岁、有驾照的司机签名。","p":"对。由 21 岁或以上、有驾照的司机签名。"},"vi":{"q":"Ở Nebraska, ai phải ký sổ ghi 50 giờ lái xe để có giấy phép lái xe tạm thời?","o":["Thiếu niên lái xe","Một giáo viên ở trường","Một giám khảo DMV","Một tài xế có bằng lái, ít nhất 21 tuổi"],"h1":"Đó là cùng loại người giám sát khi tập lái.","h2":"Mẫu ghi 50 giờ lái xe ở Nebraska phải được ký bởi cha mẹ, người giám hộ, hoặc một tài xế có bằng lái ít nhất 21 tuổi.","p":"Đúng. Một tài xế có bằng lái, từ 21 tuổi trở lên, ký tên."},"tl":{"q":"Sa Nebraska, sino ang dapat pumirma sa talaan ng 50 oras ng pagmamaneho para sa provisional operator's permit?","o":["Ang tinedyer na drayber","Isang guro sa paaralan","Isang tagasuri ng DMV","Isang lisensyadong drayber na hindi bababa sa 21 taong gulang"],"h1":"Kaparehong uri ito ng tao na gumagabay sa pagsasanay.","h2":"Ang form ng 50 oras ng pagmamaneho sa Nebraska ay dapat pirmahan ng magulang, tagapag-alaga, o lisensyadong drayber na hindi bababa sa 21 taong gulang.","p":"Tama. Isang lisensyadong drayber na 21 o higit pa ang pipirma."},"ar":{"q":"في Nebraska، من يجب أن يوقّع سجل القيادة لمدة 50 ساعة للحصول على تصريح القيادة المؤقت؟","o":["السائق المراهق","معلّم في المدرسة","فاحص من DMV","سائق مرخّص عمره 21 سنة على الأقل"],"h1":"إنه نفس نوع الشخص الذي يشرف على التدريب.","h2":"يجب أن يوقّع استمارة الـ 50 ساعة من القيادة في Nebraska أحد الوالدين، أو الوصي، أو سائق مرخّص عمره 21 سنة على الأقل.","p":"صحيح. يوقّعها سائق مرخّص عمره 21 سنة أو أكثر."},"ref":{"doc":"NE","page":4}},{"id":"ne-008","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, during which hours may a POP holder not drive alone, except for work or school activities?","o":["Midnight to 6 a.m.","10 p.m. to 5 a.m.","11 p.m. to 6 a.m.","1 a.m. to 5 a.m."],"h1":"The limit starts exactly at midnight.","h2":"A Nebraska POP holder may not drive alone between midnight and 6 a.m., except to or from work or a school activity.","p":"Right. No solo driving from midnight to 6 a.m."},"es":{"q":"En Nebraska, ¿en qué horario no puede manejar solo quien tiene POP, salvo para el trabajo o actividades escolares?","o":["De medianoche a 6 a.m.","De 10 p.m. a 5 a.m.","De 11 p.m. a 6 a.m.","De 1 a.m. a 5 a.m."],"h1":"El límite empieza justo a la medianoche.","h2":"Quien tiene POP en Nebraska no puede manejar solo entre la medianoche y las 6 a.m., salvo para ir o volver del trabajo o de una actividad escolar.","p":"Correcto. No puede manejar solo de medianoche a 6 a.m."},"zh":{"q":"在 Nebraska，除了工作或学校活动，持 POP 的人在哪段时间不能单独开车？","o":["午夜到早上 6 点","晚上 10 点到早上 5 点","晚上 11 点到早上 6 点","凌晨 1 点到早上 5 点"],"h1":"限制正好从午夜开始。","h2":"Nebraska 持 POP 的人在午夜到早上 6 点之间不能单独开车，除非是去或离开工作或学校活动。","p":"对。午夜到早上 6 点不能单独开车。"},"vi":{"q":"Ở Nebraska, trong những giờ nào người có POP không được lái xe một mình, trừ khi đi làm hoặc đi hoạt động ở trường?","o":["Nửa đêm đến 6 giờ sáng","10 giờ tối đến 5 giờ sáng","11 giờ tối đến 6 giờ sáng","1 giờ sáng đến 5 giờ sáng"],"h1":"Giới hạn bắt đầu đúng lúc nửa đêm.","h2":"Người có POP ở Nebraska không được lái xe một mình từ nửa đêm đến 6 giờ sáng, trừ khi đi đến hoặc về từ nơi làm việc hay hoạt động ở trường.","p":"Đúng. Không lái một mình từ nửa đêm đến 6 giờ sáng."},"tl":{"q":"Sa Nebraska, sa anong mga oras hindi puwedeng magmaneho nang mag-isa ang may hawak ng POP, maliban kung para sa trabaho o gawain sa paaralan?","o":["Hatinggabi hanggang 6 a.m.","10 p.m. hanggang 5 a.m.","11 p.m. hanggang 6 a.m.","1 a.m. hanggang 5 a.m."],"h1":"Nagsisimula ang limitasyon eksakto sa hatinggabi.","h2":"Ang may hawak ng POP sa Nebraska ay hindi puwedeng magmaneho nang mag-isa mula hatinggabi hanggang 6 a.m., maliban kung papunta o pauwi mula sa trabaho o gawain sa paaralan.","p":"Tama. Bawal magmanehong mag-isa mula hatinggabi hanggang 6 a.m."},"ar":{"q":"في Nebraska، في أي ساعات لا يجوز لحامل تصريح POP أن يقود وحده، إلا للعمل أو لأنشطة المدرسة؟","o":["من منتصف الليل إلى 6 صباحاً","من 10 مساءً إلى 5 صباحاً","من 11 مساءً إلى 6 صباحاً","من 1 صباحاً إلى 5 صباحاً"],"h1":"يبدأ المنع عند منتصف الليل تماماً.","h2":"لا يجوز لحامل تصريح POP في Nebraska أن يقود وحده بين منتصف الليل و6 صباحاً، إلا في الذهاب إلى العمل أو نشاط مدرسي أو العودة منهما.","p":"صحيح. لا قيادة وحدك من منتصف الليل إلى 6 صباحاً."},"ref":{"doc":"NE","page":4}},{"id":"ne-009","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, a POP holder wants to drive at 1 a.m. to visit a friend. When is this allowed?","o":["Never","Only on weekends","When a licensed driver 21 or older is in the car","When the friend is under 19"],"h1":"An experienced adult in the car changes the rule.","h2":"A Nebraska POP holder may drive between midnight and 6 a.m. when a licensed driver who is 21 or older rides along.","p":"Right. With a licensed adult 21 or older."},"es":{"q":"En Nebraska, quien tiene POP quiere manejar a la 1 a.m. para visitar a un amigo. ¿Cuándo está permitido?","o":["Nunca","Solo los fines de semana","Cuando va en el carro un conductor con licencia de 21 años o más","Cuando el amigo es menor de 19 años"],"h1":"Un adulto con experiencia en el carro cambia la regla.","h2":"Quien tiene POP en Nebraska puede manejar entre la medianoche y las 6 a.m. cuando lo acompaña un conductor con licencia de 21 años o más.","p":"Correcto. Con un adulto con licencia de 21 años o más."},"zh":{"q":"在 Nebraska，持 POP 的人想在凌晨 1 点开车去看朋友。什么情况下可以？","o":["永远不可以","只在周末","车里有 21 岁或以上、有驾照的司机时","朋友未满 19 岁时"],"h1":"车里有一位有经验的成年人，规定就不同了。","h2":"Nebraska 持 POP 的人在有 21 岁或以上、有驾照的司机同车时，可以在午夜到早上 6 点之间开车。","p":"对。有 21 岁或以上、有驾照的成年人同车就可以。"},"vi":{"q":"Ở Nebraska, một người có POP muốn lái xe lúc 1 giờ sáng để thăm bạn. Khi nào điều này được phép?","o":["Không bao giờ","Chỉ vào cuối tuần","Khi có một tài xế có bằng lái, từ 21 tuổi trở lên, trong xe","Khi người bạn dưới 19 tuổi"],"h1":"Một người lớn có kinh nghiệm trong xe làm thay đổi quy định.","h2":"Người có POP ở Nebraska được lái xe từ nửa đêm đến 6 giờ sáng khi có một tài xế có bằng lái, từ 21 tuổi trở lên, đi cùng.","p":"Đúng. Với một người lớn có bằng lái, từ 21 tuổi trở lên."},"tl":{"q":"Sa Nebraska, gustong magmaneho ng may hawak ng POP nang 1 a.m. para bisitahin ang isang kaibigan. Kailan ito pinapayagan?","o":["Hindi kailanman","Tuwing weekend lang","Kapag may lisensyadong drayber na 21 o higit pa sa sasakyan","Kapag ang kaibigan ay wala pang 19"],"h1":"Nagbabago ang patakaran kapag may bihasang adulto sa sasakyan.","h2":"Ang may hawak ng POP sa Nebraska ay puwedeng magmaneho mula hatinggabi hanggang 6 a.m. kapag may kasamang lisensyadong drayber na 21 taong gulang o higit pa.","p":"Tama. Kasama ang lisensyadong adulto na 21 o higit pa."},"ar":{"q":"في Nebraska، يريد حامل تصريح POP أن يقود في الساعة 1 صباحاً لزيارة صديق. متى يُسمح بذلك؟","o":["أبداً","في عطلة نهاية الأسبوع فقط","عندما يكون في السيارة سائق مرخّص عمره 21 سنة أو أكثر","عندما يكون عمر الصديق أقل من 19 سنة"],"h1":"وجود شخص بالغ ذي خبرة في السيارة يغيّر القاعدة.","h2":"يجوز لحامل تصريح POP في Nebraska أن يقود بين منتصف الليل و6 صباحاً عندما يرافقه سائق مرخّص عمره 21 سنة أو أكثر.","p":"صحيح. مع شخص بالغ مرخّص عمره 21 سنة أو أكثر."},"ref":{"doc":"NE","page":4}},{"id":"ne-010","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, during the first 6 months with a POP, how many passengers under 19 who are not family may ride along?","o":["None","No more than one","No more than two","No more than three"],"h1":"The limit is very small.","h2":"During the first 6 months with a POP, a Nebraska teen may carry no more than one passenger under 19 who is not immediate family.","p":"Right. Only one non-family passenger under 19."},"es":{"q":"En Nebraska, durante los primeros 6 meses con POP, ¿cuántos pasajeros menores de 19 años que no son familiares pueden ir con usted?","o":["Ninguno","No más de uno","No más de dos","No más de tres"],"h1":"El límite es muy pequeño.","h2":"Durante los primeros 6 meses con POP, un adolescente en Nebraska puede llevar no más de un pasajero menor de 19 años que no sea familiar directo.","p":"Correcto. Solo un pasajero menor de 19 que no es familiar."},"zh":{"q":"在 Nebraska，持 POP 的前 6 个月，可以有多少位不是家人、19 岁以下的乘客同车？","o":["一个都不行","最多一位","最多两位","最多三位"],"h1":"这个限制很小。","h2":"持 POP 的前 6 个月，Nebraska 的青少年最多只能载一位不是直系家人、19 岁以下的乘客。","p":"对。只能载一位不是家人、19 岁以下的乘客。"},"vi":{"q":"Ở Nebraska, trong 6 tháng đầu với POP, được chở bao nhiêu hành khách dưới 19 tuổi không phải người trong gia đình?","o":["Không ai","Không quá một người","Không quá hai người","Không quá ba người"],"h1":"Giới hạn rất nhỏ.","h2":"Trong 6 tháng đầu với POP, thiếu niên ở Nebraska được chở không quá một hành khách dưới 19 tuổi không phải người trong gia đình trực hệ.","p":"Đúng. Chỉ một hành khách dưới 19 tuổi không phải người nhà."},"tl":{"q":"Sa Nebraska, sa unang 6 na buwan na may POP, ilang pasaherong wala pang 19 na hindi kapamilya ang puwedeng isakay?","o":["Wala","Hindi hihigit sa isa","Hindi hihigit sa dalawa","Hindi hihigit sa tatlo"],"h1":"Napakaliit ng limitasyon.","h2":"Sa unang 6 na buwan na may POP, ang tinedyer sa Nebraska ay puwedeng magsakay ng hindi hihigit sa isang pasaherong wala pang 19 na hindi malapit na kapamilya.","p":"Tama. Isa lang na hindi kapamilyang pasahero na wala pang 19."},"ar":{"q":"في Nebraska، خلال أول 6 أشهر مع تصريح POP، كم راكباً عمره أقل من 19 سنة وليس من العائلة يمكن أن يركب معك؟","o":["لا أحد","ليس أكثر من واحد","ليس أكثر من اثنين","ليس أكثر من ثلاثة"],"h1":"الحد صغير جداً.","h2":"خلال أول 6 أشهر مع تصريح POP، يجوز للمراهق في Nebraska أن يحمل راكباً واحداً فقط على الأكثر عمره أقل من 19 سنة وليس من أفراد العائلة المباشرين.","p":"صحيح. راكب واحد فقط من خارج العائلة عمره أقل من 19 سنة."},"ref":{"doc":"NE","page":4}},{"id":"ne-011","scope":"NE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nebraska, may a POP holder talk or text on a wireless phone while driving?","o":["Yes, if hands-free","Yes, for calls only","Yes, at stop signs","No, interactive wireless devices are not allowed"],"h1":"The POP has a stricter rule than for adults.","h2":"A Nebraska POP holder may not use an interactive wireless device, such as a phone, while driving.","p":"Right. No phones for POP drivers."},"es":{"q":"En Nebraska, ¿puede quien tiene POP hablar o escribir mensajes en un teléfono inalámbrico mientras maneja?","o":["Sí, con manos libres","Sí, solo para llamadas","Sí, en las señales de alto","No, no se permiten aparatos inalámbricos interactivos"],"h1":"El POP tiene una regla más estricta que la de los adultos.","h2":"Quien tiene POP en Nebraska no puede usar un aparato inalámbrico interactivo, como un teléfono, mientras maneja.","p":"Correcto. Nada de teléfonos para conductores con POP."},"zh":{"q":"在 Nebraska，持 POP 的人开车时可以用无线电话通话或发短信吗？","o":["可以，如果是免提","可以，只能打电话","可以，在停车标志前","不可以，不能使用互动式无线设备"],"h1":"POP 的规定比成年人更严格。","h2":"Nebraska 持 POP 的人开车时不能使用互动式无线设备，比如手机。","p":"对。持 POP 的司机不能用手机。"},"vi":{"q":"Ở Nebraska, người có POP có được nói chuyện hoặc nhắn tin bằng điện thoại không dây khi lái xe không?","o":["Có, nếu dùng rảnh tay","Có, chỉ để gọi điện","Có, khi dừng ở biển dừng","Không, không được dùng thiết bị không dây tương tác"],"h1":"POP có quy định nghiêm hơn so với người lớn.","h2":"Người có POP ở Nebraska không được dùng thiết bị không dây tương tác, như điện thoại, khi lái xe.","p":"Đúng. Tài xế có POP không được dùng điện thoại."},"tl":{"q":"Sa Nebraska, puwede bang tumawag o mag-text sa wireless na telepono ang may hawak ng POP habang nagmamaneho?","o":["Oo, kung hands-free","Oo, para sa tawag lang","Oo, sa mga stop sign","Hindi, bawal ang interactive na wireless device"],"h1":"Mas mahigpit ang patakaran sa POP kaysa sa mga adulto.","h2":"Ang may hawak ng POP sa Nebraska ay hindi puwedeng gumamit ng interactive na wireless device, tulad ng telepono, habang nagmamaneho.","p":"Tama. Bawal ang telepono sa mga drayber na may POP."},"ar":{"q":"في Nebraska، هل يجوز لحامل تصريح POP أن يتكلم أو يرسل رسائل نصية على هاتف لاسلكي أثناء القيادة؟","o":["نعم، إذا كان بدون استخدام اليدين","نعم، للمكالمات فقط","نعم، عند علامات التوقف","لا، الأجهزة اللاسلكية التفاعلية غير مسموح بها"],"h1":"لتصريح POP قاعدة أشد من قاعدة البالغين.","h2":"لا يجوز لحامل تصريح POP في Nebraska أن يستخدم جهازاً لاسلكياً تفاعلياً، مثل الهاتف، أثناء القيادة.","p":"صحيح. لا هواتف لسائقي POP."},"ref":{"doc":"NE","page":1}},{"id":"ne-012","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, when can a POP holder move up to a full operator's license?","o":["At 16, after 3 months","At 16 and a half, after 6 months","At 17, after holding the POP for 12 months","At 18 only"],"h1":"It takes a full year on the POP.","h2":"A Nebraska POP holder can get a full operator's license at 17, after holding the POP for 12 months with a good record.","p":"Right. Age 17 and 12 months on the POP."},"es":{"q":"En Nebraska, ¿cuándo puede quien tiene POP pasar a la licencia de operador completa?","o":["A los 16, después de 3 meses","A los 16 y medio, después de 6 meses","A los 17, después de tener el POP 12 meses","Solo a los 18"],"h1":"Se necesita un año completo con el POP.","h2":"Quien tiene POP en Nebraska puede obtener la licencia de operador completa a los 17 años, después de tener el POP 12 meses con buen historial.","p":"Correcto. A los 17 y 12 meses con el POP."},"zh":{"q":"在 Nebraska，持 POP 的人什么时候可以升到正式驾照（full operator's license）？","o":["16 岁，持有 3 个月以后","16 岁半，持有 6 个月以后","17 岁，持有 POP 12 个月以后","只能在 18 岁"],"h1":"需要持有 POP 整整一年。","h2":"Nebraska 持 POP 的人在 17 岁、持有 POP 12 个月并且记录良好以后，可以拿到正式驾照。","p":"对。17 岁，并持有 POP 12 个月。"},"vi":{"q":"Ở Nebraska, khi nào người có POP được lên bằng lái đầy đủ (operator's license)?","o":["Khi 16 tuổi, sau 3 tháng","Khi 16 tuổi rưỡi, sau 6 tháng","Khi 17 tuổi, sau khi giữ POP 12 tháng","Chỉ khi 18 tuổi"],"h1":"Cần giữ POP trọn một năm.","h2":"Người có POP ở Nebraska có thể có bằng lái đầy đủ khi 17 tuổi, sau khi giữ POP 12 tháng với hồ sơ lái xe tốt.","p":"Đúng. 17 tuổi và 12 tháng với POP."},"tl":{"q":"Sa Nebraska, kailan puwedeng umakyat sa buong operator's license ang may hawak ng POP?","o":["Sa 16, pagkalipas ng 3 buwan","Sa 16 at kalahati, pagkalipas ng 6 na buwan","Sa 17, pagkatapos hawakan ang POP nang 12 buwan","Sa 18 lang"],"h1":"Kailangan ng isang buong taon sa POP.","h2":"Ang may hawak ng POP sa Nebraska ay makakakuha ng buong operator's license sa edad na 17, pagkatapos hawakan ang POP nang 12 buwan na may magandang rekord.","p":"Tama. Edad 17 at 12 buwan sa POP."},"ar":{"q":"في Nebraska، متى يمكن لحامل تصريح POP أن ينتقل إلى رخصة القيادة الكاملة (operator's license)؟","o":["في عمر 16، بعد 3 أشهر","في عمر 16 ونصف، بعد 6 أشهر","في عمر 17، بعد حمل تصريح POP لمدة 12 شهراً","في عمر 18 فقط"],"h1":"يحتاج سنة كاملة مع تصريح POP.","h2":"يمكن لحامل تصريح POP في Nebraska الحصول على رخصة القيادة الكاملة في عمر 17، بعد حمل تصريح POP لمدة 12 شهراً مع سجل جيد.","p":"صحيح. عمر 17 و12 شهراً مع تصريح POP."},"ref":{"doc":"NE","page":5}},{"id":"ne-013","scope":"NE","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nebraska, what blood alcohol level is illegal for a driver under 21?","o":["0.02 or more","0.08 or more","0.05 or more","0.10 or more"],"h1":"It is much lower than the adult limit.","h2":"In Nebraska it is against the law for a driver under 21 to drive with a blood alcohol level of 0.02 or more.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Nebraska, ¿qué nivel de alcohol en la sangre es ilegal para un conductor menor de 21 años?","o":["0.02 o más","0.08 o más","0.05 o más","0.10 o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Nebraska es ilegal que un conductor menor de 21 años maneje con un nivel de alcohol en la sangre de 0.02 o más.","p":"Correcto. Para menores de 21, el límite es 0.02."},"zh":{"q":"在 Nebraska，21 岁以下的司机血液酒精浓度达到多少就违法？","o":["0.02 或更高","0.08 或更高","0.05 或更高","0.10 或更高"],"h1":"它比成年人的限值低很多。","h2":"在 Nebraska，21 岁以下的司机血液酒精浓度达到 0.02 或更高时开车是违法的。","p":"对。21 岁以下，限值是 0.02。"},"vi":{"q":"Ở Nebraska, nồng độ cồn trong máu bao nhiêu là phạm luật đối với tài xế dưới 21 tuổi?","o":["0.02 trở lên","0.08 trở lên","0.05 trở lên","0.10 trở lên"],"h1":"Nó thấp hơn nhiều so với giới hạn cho người lớn.","h2":"Ở Nebraska, tài xế dưới 21 tuổi lái xe với nồng độ cồn trong máu từ 0.02 trở lên là phạm luật.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa Nebraska, anong antas ng alak sa dugo ang ilegal para sa drayber na wala pang 21?","o":["0.02 o higit pa","0.08 o higit pa","0.05 o higit pa","0.10 o higit pa"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon para sa adulto.","h2":"Sa Nebraska, labag sa batas para sa drayber na wala pang 21 ang magmaneho na may antas ng alak sa dugo na 0.02 o higit pa.","p":"Tama. Kapag wala pang 21, ang limitasyon ay 0.02."},"ar":{"q":"في Nebraska، ما نسبة الكحول في الدم غير القانونية للسائق الذي عمره أقل من 21 سنة؟","o":["0.02 أو أكثر","0.08 أو أكثر","0.05 أو أكثر","0.10 أو أكثر"],"h1":"إنها أقل بكثير من حد البالغين.","h2":"في Nebraska من المخالف للقانون أن يقود سائق عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02 أو أكثر.","p":"صحيح. تحت 21 سنة، الحد هو 0.02."},"ref":{"doc":"NE","page":24}},{"id":"ne-014","scope":"NE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nebraska, may a driver read or send a text on a handheld phone while the car is moving?","o":["Yes, on rural roads","No, it is against the law","Yes, below 30 mph","Yes, at night"],"h1":"Texting takes your eyes off the road.","h2":"No. In Nebraska it is against the law to read, type, or send a text on a handheld phone while driving.","p":"Right. No texting while you drive."},"es":{"q":"En Nebraska, ¿puede un conductor leer o enviar un mensaje de texto en un teléfono en la mano mientras el carro está en movimiento?","o":["Sí, en caminos rurales","No, es ilegal","Sí, a menos de 30 mph","Sí, de noche"],"h1":"Escribir mensajes le quita la vista del camino.","h2":"No. En Nebraska es ilegal leer, escribir o enviar un mensaje de texto en un teléfono en la mano mientras maneja.","p":"Correcto. Nada de mensajes mientras maneja."},"zh":{"q":"在 Nebraska，车在开动时，司机可以用手拿的手机看短信或发短信吗？","o":["可以，在乡村道路上","不可以，这是违法的","可以，在 30 英里/小时以下时","可以，在晚上"],"h1":"发短信会让你的眼睛离开道路。","h2":"不可以。在 Nebraska，开车时用手拿的手机看短信、打短信或发短信是违法的。","p":"对。开车时不能发短信。"},"vi":{"q":"Ở Nebraska, tài xế có được đọc hoặc gửi tin nhắn trên điện thoại cầm tay khi xe đang chạy không?","o":["Có, trên đường nông thôn","Không, điều đó là phạm luật","Có, dưới 30 mph","Có, vào ban đêm"],"h1":"Nhắn tin làm mắt bạn rời khỏi đường.","h2":"Không. Ở Nebraska, đọc, gõ hoặc gửi tin nhắn trên điện thoại cầm tay khi lái xe là phạm luật.","p":"Đúng. Không nhắn tin khi lái xe."},"tl":{"q":"Sa Nebraska, puwede bang magbasa o magpadala ng text sa hawak na telepono ang drayber habang umaandar ang sasakyan?","o":["Oo, sa mga daan sa probinsya","Hindi, labag ito sa batas","Oo, kapag mas mabagal sa 30 mph","Oo, sa gabi"],"h1":"Inaalis ng pag-text ang mata mo sa daan.","h2":"Hindi. Sa Nebraska, labag sa batas ang magbasa, mag-type, o magpadala ng text sa hawak na telepono habang nagmamaneho.","p":"Tama. Bawal mag-text habang nagmamaneho."},"ar":{"q":"في Nebraska، هل يجوز للسائق أن يقرأ أو يرسل رسالة نصية على هاتف محمول باليد أثناء سير السيارة؟","o":["نعم، على الطرق الريفية","لا، هذا مخالف للقانون","نعم، تحت 30 mph","نعم، في الليل"],"h1":"كتابة الرسائل تُبعد عينيك عن الطريق.","h2":"لا. في Nebraska من المخالف للقانون أن تقرأ أو تكتب أو ترسل رسالة نصية على هاتف محمول باليد أثناء القيادة.","p":"صحيح. لا رسائل نصية أثناء القيادة."},"ref":{"doc":"NE","page":65}},{"id":"ne-015","scope":"NE","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Nebraska, on an interstate, you come up to a stopped car on the shoulder with people near it. What must you do?","o":["Nothing; the law covers only police cars","Stop next to it","Honk to warn the people","Move one lane over, or slow down if you cannot"],"h1":"Give the people on the shoulder more room.","h2":"On a Nebraska interstate, you must move one lane away from a stopped vehicle with people in or near it, or slow down if you cannot move over.","p":"Right. Move over, or slow down."},"es":{"q":"En Nebraska, en una interestatal, usted se acerca a un carro detenido en el acotamiento con personas cerca. ¿Qué debe hacer?","o":["Nada; la ley solo aplica a patrullas","Detenerse junto a él","Tocar la bocina para avisar","Pasarse un carril, o bajar la velocidad si no puede"],"h1":"Deles más espacio a las personas en el acotamiento.","h2":"En una interestatal de Nebraska, usted debe pasarse a un carril más lejos de un vehículo detenido con personas dentro o cerca, o bajar la velocidad si no puede cambiarse.","p":"Correcto. Cambiar de carril, o bajar la velocidad."},"zh":{"q":"在 Nebraska，在州际公路上，你遇到一辆停在路肩上的车，旁边有人。你必须怎么做？","o":["什么都不用做；法律只包括警车","在它旁边停车","按喇叭提醒那些人","换开一条车道，不能换就减速"],"h1":"给路肩上的人更多空间。","h2":"在 Nebraska 的州际公路上，你必须离开一辆车里或旁边有人、停着的车一条车道；如果不能换道，就要减速。","p":"对。让出车道，或者减速。"},"vi":{"q":"Ở Nebraska, trên xa lộ liên bang (interstate), bạn đến gần một xe đang dừng ở lề đường có người ở gần. Bạn phải làm gì?","o":["Không làm gì; luật chỉ áp dụng cho xe cảnh sát","Dừng lại bên cạnh xe đó","Bấm còi để cảnh báo mọi người","Chuyển sang một làn khác, hoặc giảm tốc độ nếu không chuyển được"],"h1":"Hãy chừa thêm chỗ cho những người ở lề đường.","h2":"Trên xa lộ liên bang ở Nebraska, bạn phải chuyển sang một làn cách xa xe đang dừng có người ở trong hoặc ở gần, hoặc giảm tốc độ nếu không thể chuyển làn.","p":"Đúng. Chuyển làn, hoặc giảm tốc độ."},"tl":{"q":"Sa Nebraska, sa isang interstate, papalapit ka sa nakahintong sasakyan sa gilid ng daan (shoulder) na may mga tao sa malapit. Ano ang dapat mong gawin?","o":["Wala; para lang sa sasakyan ng pulis ang batas","Huminto sa tabi nito","Bumusina para balaan ang mga tao","Lumipat ng isang lane, o bumagal kung hindi ka makalipat"],"h1":"Bigyan ng mas maraming espasyo ang mga tao sa gilid ng daan.","h2":"Sa isang interstate sa Nebraska, dapat kang lumipat ng isang lane palayo sa nakahintong sasakyan na may mga tao sa loob o malapit dito, o bumagal kung hindi ka makalipat.","p":"Tama. Lumipat ng lane, o bumagal."},"ar":{"q":"في Nebraska، على طريق سريع بين الولايات (interstate)، تقترب من سيارة متوقفة على كتف الطريق وبقربها أشخاص. ماذا يجب أن تفعل؟","o":["لا شيء؛ القانون يشمل سيارات الشرطة فقط","توقّف بجانبها","استخدم البوق لتحذير الناس","انتقل حارة واحدة بعيداً، أو خفّف السرعة إذا لم تستطع"],"h1":"أعطِ الناس على كتف الطريق مساحة أكبر.","h2":"على طريق interstate في Nebraska، يجب أن تنتقل حارة واحدة بعيداً عن مركبة متوقفة فيها أو بقربها أشخاص، أو أن تخفّف السرعة إذا لم تستطع الانتقال.","p":"صحيح. انتقل إلى حارة أخرى، أو خفّف السرعة."},"ref":{"doc":"NE","page":null}},{"id":"ne-016","scope":"NE","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Nebraska, on a road divided by a median, a school bus stops with its red lights flashing and stop arm out. Who must stop?","o":["Every vehicle, from both directions","Only traffic coming toward the bus","Only traffic going the same direction as the bus","No one, if no child is crossing"],"h1":"The median separates the two sides of the road.","h2":"On a Nebraska road divided by a median, only traffic going the same direction as the school bus must stop.","p":"Right. Only the same direction stops."},"es":{"q":"En Nebraska, en un camino dividido por un camellón, un autobús escolar se detiene con las luces rojas encendidas y el brazo de alto extendido. ¿Quién debe detenerse?","o":["Todos los vehículos, de los dos sentidos","Solo el tráfico que viene hacia el autobús","Solo el tráfico que va en el mismo sentido que el autobús","Nadie, si ningún niño está cruzando"],"h1":"El camellón separa los dos lados del camino.","h2":"En un camino de Nebraska dividido por un camellón, solo el tráfico que va en el mismo sentido que el autobús escolar debe detenerse.","p":"Correcto. Solo se detiene el mismo sentido."},"zh":{"q":"在 Nebraska，在有中央隔离带分隔的路上，一辆校车停下来，闪着红灯并伸出停车臂。谁必须停车？","o":["两个方向的每一辆车","只有朝校车开过来的车","只有和校车同方向的车","没有人，如果没有孩子在过马路"],"h1":"中央隔离带把路的两边分开。","h2":"在 Nebraska 有中央隔离带分隔的路上，只有和校车同方向的车必须停车。","p":"对。只有同方向的车要停。"},"vi":{"q":"Ở Nebraska, trên đường có dải phân cách ở giữa, một xe buýt trường học dừng lại với đèn đỏ nhấp nháy và cần báo dừng (stop arm) mở ra. Ai phải dừng?","o":["Mọi xe, từ cả hai chiều","Chỉ xe đi ngược chiều về phía xe buýt","Chỉ xe đi cùng chiều với xe buýt","Không ai, nếu không có trẻ em băng qua đường"],"h1":"Dải phân cách chia hai bên đường ra.","h2":"Trên đường có dải phân cách ở Nebraska, chỉ xe đi cùng chiều với xe buýt trường học phải dừng.","p":"Đúng. Chỉ xe cùng chiều phải dừng."},"tl":{"q":"Sa Nebraska, sa daang hinahati ng median, huminto ang school bus na kumikislap ang pulang ilaw at nakalabas ang stop arm. Sino ang dapat huminto?","o":["Lahat ng sasakyan, mula sa dalawang direksyon","Ang mga sasakyang paparating lang sa bus","Ang mga sasakyang kapareho lang ng direksyon ng bus","Wala, kung walang batang tumatawid"],"h1":"Pinaghihiwalay ng median ang dalawang panig ng daan.","h2":"Sa daang hinahati ng median sa Nebraska, ang mga sasakyang kapareho lang ng direksyon ng school bus ang dapat huminto.","p":"Tama. Ang kaparehong direksyon lang ang hihinto."},"ar":{"q":"في Nebraska، على طريق مقسوم بجزيرة وسطية (median)، تتوقف حافلة مدرسية وأضواؤها الحمراء تومض وذراع التوقف (stop arm) ممدودة. من يجب أن يتوقف؟","o":["كل المركبات، من الاتجاهين","المركبات القادمة نحو الحافلة فقط","المركبات التي تسير في نفس اتجاه الحافلة فقط","لا أحد، إذا لم يكن هناك طفل يعبر"],"h1":"الجزيرة الوسطية تفصل بين جانبي الطريق.","h2":"على طريق في Nebraska مقسوم بجزيرة وسطية، يجب أن تتوقف فقط المركبات التي تسير في نفس اتجاه الحافلة المدرسية.","p":"صحيح. يتوقف نفس الاتجاه فقط."},"ref":{"doc":"NE","page":70}},{"id":"ne-017","scope":"NE","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Nebraska, what is the usual posted speed limit on most rural interstates?","o":["75 mph","65 mph","70 mph","80 mph"],"h1":"It is higher than in many eastern states.","h2":"The speed limit on most rural interstates in Nebraska is 75 mph; city stretches are lower.","p":"Right. 75 mph on most rural interstates."},"es":{"q":"En Nebraska, ¿cuál es el límite de velocidad usual en la mayoría de las interestatales rurales?","o":["75 mph","65 mph","70 mph","80 mph"],"h1":"Es más alto que en muchos estados del este.","h2":"El límite de velocidad en la mayoría de las interestatales rurales de Nebraska es de 75 millas por hora; los tramos en la ciudad son más bajos.","p":"Correcto. 75 mph en la mayoría de las interestatales rurales."},"zh":{"q":"在 Nebraska，大多数乡村州际公路通常标出的限速是多少？","o":["75 英里/小时","65 英里/小时","70 英里/小时","80 英里/小时"],"h1":"它比很多东部的州高。","h2":"Nebraska 大多数乡村州际公路的限速是 75 英里/小时；城市路段更低。","p":"对。大多数乡村州际公路限速 75 英里/小时。"},"vi":{"q":"Ở Nebraska, tốc độ tối đa thường được ghi trên hầu hết xa lộ liên bang ở vùng nông thôn là bao nhiêu?","o":["75 mph","65 mph","70 mph","80 mph"],"h1":"Nó cao hơn ở nhiều bang miền đông.","h2":"Tốc độ tối đa trên hầu hết xa lộ liên bang ở vùng nông thôn của Nebraska là 75 mph; các đoạn trong thành phố thấp hơn.","p":"Đúng. 75 mph trên hầu hết xa lộ liên bang ở vùng nông thôn."},"tl":{"q":"Sa Nebraska, ano ang karaniwang nakapaskil na speed limit sa karamihan ng interstate sa probinsya?","o":["75 mph","65 mph","70 mph","80 mph"],"h1":"Mas mataas ito kaysa sa maraming estado sa silangan.","h2":"Ang speed limit sa karamihan ng interstate sa probinsya sa Nebraska ay 75 mph; mas mababa sa mga bahaging nasa lungsod.","p":"Tama. 75 mph sa karamihan ng interstate sa probinsya."},"ar":{"q":"في Nebraska، ما حد السرعة المعتاد المكتوب على معظم الطرق السريعة بين الولايات في المناطق الريفية؟","o":["75 mph","65 mph","70 mph","80 mph"],"h1":"إنه أعلى منه في كثير من الولايات الشرقية.","h2":"حد السرعة على معظم الطرق السريعة بين الولايات في المناطق الريفية في Nebraska هو 75 mph؛ وهو أقل في أجزائها داخل المدن.","p":"صحيح. 75 mph على معظم الطرق السريعة الريفية بين الولايات."},"ref":{"doc":"NE","page":52}},{"id":"ne-018","scope":"NE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nebraska, can police stop an adult driver only for not wearing a seat belt?","o":["Yes, it is a primary offense","Yes, but only at night","Yes, but only on interstates","No, it is a secondary law"],"h1":"The ticket comes only with another violation.","h2":"Nebraska's adult seat belt law is secondary, so a driver gets a seat belt ticket only when stopped for another violation. You should still always buckle up.","p":"Right. For adults it is a secondary law, but buckle up anyway."},"es":{"q":"En Nebraska, ¿puede la policía detener a un conductor adulto solo por no usar el cinturón de seguridad?","o":["Sí, es una infracción primaria","Sí, pero solo de noche","Sí, pero solo en interestatales","No, es una ley secundaria"],"h1":"La multa llega solo junto con otra infracción.","h2":"La ley de cinturón de seguridad para adultos en Nebraska es secundaria, así que el conductor recibe esa multa solo cuando lo detienen por otra infracción. Aun así, abróchese siempre.","p":"Correcto. Para adultos es una ley secundaria, pero abróchese de todos modos."},"zh":{"q":"在 Nebraska，警察可以只因为成年司机没系安全带就让他停车吗？","o":["可以，这是主要违规","可以，但只在晚上","可以，但只在州际公路上","不可以，这是次要执法的法律"],"h1":"只有在有其他违规时，才会开这张罚单。","h2":"Nebraska 的成年人安全带法是次要执法，所以司机只有在因为其他违规被拦下时，才会收到安全带罚单。你还是应该一直系好安全带。","p":"对。对成年人来说这是次要执法的法律，但还是要系好安全带。"},"vi":{"q":"Ở Nebraska, cảnh sát có thể chặn một tài xế người lớn chỉ vì không thắt dây an toàn không?","o":["Có, đó là vi phạm chính (primary offense)","Có, nhưng chỉ vào ban đêm","Có, nhưng chỉ trên xa lộ liên bang","Không, đó là luật phụ (secondary law)"],"h1":"Vé phạt chỉ đi kèm với một vi phạm khác.","h2":"Luật dây an toàn cho người lớn ở Nebraska là luật phụ, nên tài xế chỉ bị phạt về dây an toàn khi bị chặn vì một vi phạm khác. Bạn vẫn nên luôn thắt dây an toàn.","p":"Đúng. Với người lớn đó là luật phụ, nhưng hãy luôn thắt dây an toàn."},"tl":{"q":"Sa Nebraska, puwede bang patigilin ng pulis ang adultong drayber dahil lang hindi siya naka-seat belt?","o":["Oo, ito ay primary offense","Oo, pero sa gabi lang","Oo, pero sa interstate lang","Hindi, ito ay secondary law"],"h1":"Darating lang ang tiket kasama ng ibang paglabag.","h2":"Secondary ang batas sa seat belt para sa adulto sa Nebraska, kaya natitiketan lang ang drayber sa seat belt kapag pinatigil siya dahil sa ibang paglabag. Dapat ka pa ring laging mag-seat belt.","p":"Tama. Para sa adulto, secondary law ito, pero mag-seat belt pa rin."},"ar":{"q":"في Nebraska، هل يمكن للشرطة إيقاف سائق بالغ فقط لأنه لا يضع حزام الأمان؟","o":["نعم، إنها مخالفة أساسية (primary offense)","نعم، ولكن في الليل فقط","نعم، ولكن على الطرق السريعة بين الولايات فقط","لا، إنه قانون ثانوي (secondary law)"],"h1":"المخالفة تأتي فقط مع مخالفة أخرى.","h2":"قانون حزام الأمان للبالغين في Nebraska قانون ثانوي، لذلك يحصل السائق على مخالفة حزام الأمان فقط عندما يُوقَف بسبب مخالفة أخرى. ومع ذلك يجب أن تضع حزام الأمان دائماً.","p":"صحيح. للبالغين هو قانون ثانوي، لكن ضع الحزام على أي حال."},"ref":{"doc":"NE","page":26}},{"id":"ne-019","scope":"NE","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Nebraska, on a road divided by a median, you meet a stopped school bus on the other side. What must you do?","o":["You do not have to stop, but watch for children","Stop until the bus moves","Stop only if children are near the bus","Pull onto the shoulder"],"h1":"The median separates you from the bus.","h2":"On a Nebraska road divided by a median, traffic coming from the opposite direction does not have to stop for a stopped school bus, but should watch for children.","p":"Right. Oncoming traffic on a divided highway may pass with care."},"es":{"q":"En Nebraska, en un camino dividido por un camellón, usted se encuentra con un autobús escolar detenido del otro lado. ¿Qué debe hacer?","o":["No tiene que detenerse, pero esté atento a los niños","Detenerse hasta que el autobús avance","Detenerse solo si hay niños cerca del autobús","Orillarse al acotamiento"],"h1":"El camellón lo separa del autobús.","h2":"En un camino de Nebraska dividido por un camellón, el tráfico que viene en sentido contrario no tiene que detenerse por un autobús escolar detenido, pero debe estar atento a los niños.","p":"Correcto. En una carretera dividida, el tráfico contrario puede pasar con cuidado."},"zh":{"q":"在 Nebraska，在有中央隔离带分隔的路上，你遇到另一边停着的校车。你必须怎么做？","o":["你不必停车，但要注意孩子","停车，直到校车开走","只有孩子在校车附近时才停车","开到路肩上"],"h1":"中央隔离带把你和校车分开。","h2":"在 Nebraska 有中央隔离带分隔的路上，从对面方向开来的车不必为停着的校车停车，但应该注意孩子。","p":"对。在分隔公路上，对面的车可以小心地开过去。"},"vi":{"q":"Ở Nebraska, trên đường có dải phân cách ở giữa, bạn gặp một xe buýt trường học đang dừng ở phía bên kia. Bạn phải làm gì?","o":["Bạn không phải dừng, nhưng hãy chú ý trẻ em","Dừng lại cho đến khi xe buýt chạy","Chỉ dừng nếu có trẻ em gần xe buýt","Tấp vào lề đường"],"h1":"Dải phân cách ngăn cách bạn với xe buýt.","h2":"Trên đường có dải phân cách ở Nebraska, xe đi ngược chiều không phải dừng khi xe buýt trường học dừng, nhưng phải chú ý trẻ em.","p":"Đúng. Xe đi ngược chiều trên đường có dải phân cách có thể đi qua một cách cẩn thận."},"tl":{"q":"Sa Nebraska, sa daang hinahati ng median, nakasalubong mo ang nakahintong school bus sa kabilang panig. Ano ang dapat mong gawin?","o":["Hindi mo kailangang huminto, pero bantayan ang mga bata","Huminto hanggang umandar ang bus","Huminto lang kung may mga bata malapit sa bus","Pumunta sa gilid ng daan (shoulder)"],"h1":"Pinaghihiwalay ka ng median sa bus.","h2":"Sa daang hinahati ng median sa Nebraska, ang mga sasakyang galing sa kabilang direksyon ay hindi kailangang huminto para sa nakahintong school bus, pero dapat magbantay sa mga bata.","p":"Tama. Puwedeng dumaan nang maingat ang paparating na sasakyan sa daang may median."},"ar":{"q":"في Nebraska، على طريق مقسوم بجزيرة وسطية (median)، تصادف حافلة مدرسية متوقفة على الجانب الآخر. ماذا يجب أن تفعل؟","o":["ليس عليك أن تتوقف، لكن انتبه للأطفال","توقّف حتى تتحرك الحافلة","توقّف فقط إذا كان هناك أطفال قرب الحافلة","انتقل إلى كتف الطريق"],"h1":"الجزيرة الوسطية تفصلك عن الحافلة.","h2":"على طريق في Nebraska مقسوم بجزيرة وسطية، ليس على المركبات القادمة من الاتجاه المعاكس أن تتوقف لحافلة مدرسية متوقفة، لكن يجب أن تنتبه للأطفال.","p":"صحيح. المركبات القادمة من الاتجاه المعاكس على طريق مقسوم يمكنها المرور بحذر."},"ref":{"doc":"NE","page":70}},{"id":"ne-020","scope":"NE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nebraska, who must wear a seat belt by law?","o":["Only the driver","The driver, every front-seat passenger, and all children under 18","Only passengers under 16","Only people on interstates"],"h1":"The law covers the front seat and all children.","h2":"Nebraska law requires the driver and each front-seat passenger to buckle up, and every child under 18 must ride in a seat belt or a child safety seat.","p":"Right. The front seat, plus every child under 18."},"es":{"q":"En Nebraska, ¿quién debe usar el cinturón de seguridad por ley?","o":["Solo el conductor","El conductor, cada pasajero del asiento delantero y todos los niños menores de 18 años","Solo los pasajeros menores de 16 años","Solo quienes van en interestatales"],"h1":"La ley cubre el asiento delantero y a todos los niños.","h2":"La ley de Nebraska exige que el conductor y cada pasajero del asiento delantero usen el cinturón, y todo niño menor de 18 años debe ir con cinturón o en un asiento de seguridad para niños.","p":"Correcto. El asiento delantero, y todos los niños menores de 18."},"zh":{"q":"在 Nebraska，法律规定谁必须系安全带？","o":["只有司机","司机、每位前排乘客，以及所有 18 岁以下的孩子","只有 16 岁以下的乘客","只有在州际公路上的人"],"h1":"这条法律包括前排和所有孩子。","h2":"Nebraska 法律要求司机和每位前排乘客系好安全带，每个 18 岁以下的孩子都必须系安全带或坐儿童安全座椅。","p":"对。前排的人，加上每个 18 岁以下的孩子。"},"vi":{"q":"Ở Nebraska, theo luật ai phải thắt dây an toàn?","o":["Chỉ tài xế","Tài xế, mọi hành khách ở ghế trước, và tất cả trẻ em dưới 18 tuổi","Chỉ hành khách dưới 16 tuổi","Chỉ người đi trên xa lộ liên bang"],"h1":"Luật áp dụng cho ghế trước và tất cả trẻ em.","h2":"Luật Nebraska bắt buộc tài xế và mỗi hành khách ở ghế trước phải thắt dây an toàn, và mọi trẻ em dưới 18 tuổi phải ngồi với dây an toàn hoặc ghế an toàn cho trẻ em.","p":"Đúng. Ghế trước, cộng với mọi trẻ em dưới 18 tuổi."},"tl":{"q":"Sa Nebraska, sino ang dapat mag-seat belt ayon sa batas?","o":["Ang drayber lang","Ang drayber, bawat pasahero sa harap na upuan, at lahat ng batang wala pang 18","Ang mga pasaherong wala pang 16 lang","Ang mga tao lang sa interstate"],"h1":"Sakop ng batas ang harap na upuan at lahat ng bata.","h2":"Ayon sa batas ng Nebraska, dapat mag-seat belt ang drayber at bawat pasahero sa harap na upuan, at bawat batang wala pang 18 ay dapat naka-seat belt o nasa child safety seat.","p":"Tama. Ang harap na upuan, at bawat batang wala pang 18."},"ar":{"q":"في Nebraska، من يجب أن يضع حزام الأمان حسب القانون؟","o":["السائق فقط","السائق، وكل راكب في المقعد الأمامي، وكل الأطفال تحت 18 سنة","الركاب تحت 16 سنة فقط","الناس على الطرق السريعة بين الولايات فقط"],"h1":"القانون يشمل المقعد الأمامي وكل الأطفال.","h2":"قانون Nebraska يُلزم السائق وكل راكب في المقعد الأمامي بوضع حزام الأمان، ويجب أن يركب كل طفل تحت 18 سنة بحزام أمان أو في مقعد أمان للأطفال.","p":"صحيح. المقعد الأمامي، وكل طفل تحت 18 سنة."},"ref":{"doc":"NE","page":26}},{"id":"ne-021","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, what happens if a driver collects 12 points within two years?","o":["A warning letter only","The license is revoked for six months","A one-day safety class","Higher fines, but the license is kept"],"h1":"Under the point system, this is automatic.","h2":"In Nebraska, collecting 12 points within two years means the license is automatically revoked for six months.","p":"Right. 12 points in two years means a six-month revocation."},"es":{"q":"En Nebraska, ¿qué pasa si un conductor acumula 12 puntos dentro de dos años?","o":["Solo recibe una carta de advertencia","La licencia se revoca por seis meses","Una clase de seguridad de un día","Multas más altas, pero conserva la licencia"],"h1":"Con el sistema de puntos, esto es automático.","h2":"En Nebraska, acumular 12 puntos dentro de dos años significa que la licencia se revoca automáticamente por seis meses.","p":"Correcto. 12 puntos en dos años significan una revocación de seis meses."},"zh":{"q":"在 Nebraska，如果司机在两年内累计 12 分，会怎么样？","o":["只收到一封警告信","驾照被吊销六个月","上一天的安全课","罚款更高，但可以保留驾照"],"h1":"按照扣分制度，这是自动发生的。","h2":"在 Nebraska，两年内累计 12 分，驾照会被自动吊销六个月。","p":"对。两年内 12 分，驾照被吊销六个月。"},"vi":{"q":"Ở Nebraska, chuyện gì xảy ra nếu tài xế bị 12 điểm trong vòng hai năm?","o":["Chỉ nhận một thư cảnh cáo","Bằng lái bị thu hồi sáu tháng","Học một lớp an toàn một ngày","Bị phạt nặng hơn, nhưng vẫn giữ bằng lái"],"h1":"Theo hệ thống tính điểm, việc này xảy ra tự động.","h2":"Ở Nebraska, bị 12 điểm trong vòng hai năm có nghĩa là bằng lái tự động bị thu hồi sáu tháng.","p":"Đúng. 12 điểm trong hai năm thì bị thu hồi bằng lái sáu tháng."},"tl":{"q":"Sa Nebraska, ano ang mangyayari kapag nakaipon ang drayber ng 12 puntos sa loob ng dalawang taon?","o":["Isang sulat ng babala lang","Babawiin ang lisensya nang anim na buwan","Isang araw na klase sa kaligtasan","Mas mataas na multa, pero mananatili ang lisensya"],"h1":"Sa point system, awtomatiko ito.","h2":"Sa Nebraska, kapag nakaipon ka ng 12 puntos sa loob ng dalawang taon, awtomatikong babawiin ang lisensya mo nang anim na buwan.","p":"Tama. Ang 12 puntos sa dalawang taon ay anim na buwang pagbawi ng lisensya."},"ar":{"q":"في Nebraska، ماذا يحدث إذا جمع السائق 12 نقطة خلال سنتين؟","o":["رسالة تحذير فقط","تُسحب الرخصة لمدة ستة أشهر","دورة سلامة ليوم واحد","غرامات أعلى، لكن يحتفظ بالرخصة"],"h1":"حسب نظام النقاط، يحدث هذا تلقائياً.","h2":"في Nebraska، إذا جمع السائق 12 نقطة خلال سنتين تُسحب رخصته تلقائياً لمدة ستة أشهر.","p":"صحيح. 12 نقطة خلال سنتين تعني سحب الرخصة لمدة ستة أشهر."},"ref":{"doc":"NE","page":18}},{"id":"ne-022","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, a driver under 21 gets 6 or more points within one year. What must the driver do?","o":["Retake the driving skills test","Pay a $1,000 fine","Wait until age 21 to drive again","Take a driver improvement course within three months"],"h1":"It is a course meant to help the driver do better.","h2":"In Nebraska, a driver under 21 with 6 or more points in one year must take a driver improvement course within three months.","p":"Right. A driver improvement course within three months is required."},"es":{"q":"En Nebraska, un conductor menor de 21 años acumula 6 puntos o más dentro de un año. ¿Qué debe hacer?","o":["Repetir el examen práctico de manejo","Pagar una multa de $1,000","Esperar hasta los 21 años para volver a manejar","Tomar un curso para mejorar como conductor dentro de tres meses"],"h1":"Es un curso que busca ayudar al conductor a mejorar.","h2":"En Nebraska, un conductor menor de 21 años con 6 puntos o más en un año debe tomar un curso para mejorar como conductor dentro de tres meses.","p":"Correcto. Se exige un curso para mejorar como conductor dentro de tres meses."},"zh":{"q":"在 Nebraska，一位 21 岁以下的司机在一年内被扣 6 分或更多。这位司机必须做什么？","o":["重新参加驾驶技能考试","交 $1,000 罚款","等到 21 岁才能再开车","在三个月内上驾驶改进课程"],"h1":"这是一门帮助司机开得更好的课程。","h2":"在 Nebraska，21 岁以下的司机如果一年内被扣 6 分或更多，必须在三个月内上驾驶改进课程。","p":"对。必须在三个月内上驾驶改进课程。"},"vi":{"q":"Ở Nebraska, một tài xế dưới 21 tuổi bị 6 điểm trở lên trong vòng một năm. Tài xế đó phải làm gì?","o":["Thi lại phần thi kỹ năng lái xe","Nộp phạt $1,000","Chờ đến 21 tuổi mới được lái lại","Học một khóa cải thiện kỹ năng lái xe (driver improvement course) trong vòng ba tháng"],"h1":"Đó là một khóa học giúp tài xế lái tốt hơn.","h2":"Ở Nebraska, tài xế dưới 21 tuổi bị 6 điểm trở lên trong một năm phải học một khóa cải thiện kỹ năng lái xe trong vòng ba tháng.","p":"Đúng. Phải học khóa cải thiện kỹ năng lái xe trong vòng ba tháng."},"tl":{"q":"Sa Nebraska, nakakuha ang isang drayber na wala pang 21 ng 6 o higit pang puntos sa loob ng isang taon. Ano ang dapat gawin ng drayber?","o":["Kumuha ulit ng driving skills test","Magbayad ng $1,000 na multa","Maghintay hanggang edad 21 bago magmaneho ulit","Kumuha ng driver improvement course sa loob ng tatlong buwan"],"h1":"Isa itong kurso para tulungan ang drayber na gumaling.","h2":"Sa Nebraska, ang drayber na wala pang 21 na may 6 o higit pang puntos sa isang taon ay dapat kumuha ng driver improvement course sa loob ng tatlong buwan.","p":"Tama. Kailangan ang driver improvement course sa loob ng tatlong buwan."},"ar":{"q":"في Nebraska، حصل سائق عمره أقل من 21 سنة على 6 نقاط أو أكثر خلال سنة واحدة. ماذا يجب على السائق أن يفعل؟","o":["أن يعيد اختبار مهارات القيادة","أن يدفع غرامة $1,000","أن ينتظر حتى عمر 21 سنة ليقود مرة أخرى","أن يأخذ دورة تحسين القيادة (driver improvement course) خلال ثلاثة أشهر"],"h1":"إنها دورة تساعد السائق على أن يقود بشكل أفضل.","h2":"في Nebraska، السائق الذي عمره أقل من 21 سنة ويحصل على 6 نقاط أو أكثر خلال سنة يجب أن يأخذ دورة تحسين القيادة خلال ثلاثة أشهر.","p":"صحيح. دورة تحسين القيادة خلال ثلاثة أشهر مطلوبة."},"ref":{"doc":"NE","page":1}},{"id":"ne-023","scope":"NE","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nebraska, a driver refuses a chemical test for alcohol or drugs when a police officer asks. What is the administrative penalty?","o":["One year of license revocation","A 30-day warning period","A $50 fine only","No penalty if the driver passes a later test"],"h1":"Every driver in Nebraska has already agreed to be tested.","h2":"In Nebraska, refusing a chemical test leads to a one-year license revocation, and the refusal is also a separate crime.","p":"Right. Refusing the test means one year without a license."},"es":{"q":"En Nebraska, un conductor se niega a hacer una prueba química de alcohol o drogas cuando un policía se la pide. ¿Cuál es la sanción administrativa?","o":["Un año de revocación de la licencia","Un período de advertencia de 30 días","Solo una multa de $50","Ninguna sanción si pasa una prueba después"],"h1":"Todo conductor en Nebraska ya aceptó hacerse la prueba.","h2":"En Nebraska, negarse a una prueba química lleva a una revocación de la licencia por un año, y negarse también es un delito aparte.","p":"Correcto. Negarse a la prueba significa un año sin licencia."},"zh":{"q":"在 Nebraska，警察要求司机做酒精或毒品化学检测，司机拒绝了。行政处罚是什么？","o":["吊销驾照一年","30 天的警告期","只罚款 $50","如果司机之后检测通过，就没有处罚"],"h1":"Nebraska 的每位司机都已经同意接受检测。","h2":"在 Nebraska，拒绝化学检测会导致驾照被吊销一年，而且拒绝检测本身也是另一项犯罪。","p":"对。拒绝检测就是一年没有驾照。"},"vi":{"q":"Ở Nebraska, tài xế từ chối xét nghiệm hóa học (chemical test) về rượu hoặc ma túy khi cảnh sát yêu cầu. Hình phạt hành chính là gì?","o":["Bị thu hồi bằng lái một năm","Thời gian cảnh cáo 30 ngày","Chỉ bị phạt $50","Không bị phạt nếu tài xế qua được xét nghiệm sau đó"],"h1":"Mọi tài xế ở Nebraska đều đã đồng ý cho xét nghiệm.","h2":"Ở Nebraska, từ chối xét nghiệm hóa học sẽ bị thu hồi bằng lái một năm, và việc từ chối cũng là một tội riêng.","p":"Đúng. Từ chối xét nghiệm nghĩa là một năm không có bằng lái."},"tl":{"q":"Sa Nebraska, tumanggi ang drayber sa chemical test para sa alak o droga nang hilingin ito ng pulis. Ano ang administratibong parusa?","o":["Isang taong pagbawi ng lisensya","30 araw na panahon ng babala","$50 na multa lang","Walang parusa kung pumasa ang drayber sa susunod na test"],"h1":"Pumayag na ang bawat drayber sa Nebraska na magpa-test.","h2":"Sa Nebraska, ang pagtanggi sa chemical test ay nagdudulot ng isang taong pagbawi ng lisensya, at hiwalay na krimen din ang pagtanggi.","p":"Tama. Ang pagtanggi sa test ay isang taon nang walang lisensya."},"ar":{"q":"في Nebraska، رفض سائق إجراء فحص كيميائي (chemical test) للكحول أو المخدرات عندما طلب منه الشرطي ذلك. ما هي العقوبة الإدارية؟","o":["سحب الرخصة لمدة سنة واحدة","فترة تحذير لمدة 30 يوماً","غرامة $50 فقط","لا عقوبة إذا نجح السائق في فحص لاحق"],"h1":"كل سائق في Nebraska قد وافق مسبقاً على إجراء الفحص.","h2":"في Nebraska، رفض الفحص الكيميائي يؤدي إلى سحب الرخصة لمدة سنة واحدة، والرفض أيضاً جريمة منفصلة.","p":"صحيح. رفض الفحص يعني سنة واحدة بدون رخصة."},"ref":{"doc":"NE","page":24}},{"id":"ne-024","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, what is the minimum liability insurance for injury to one person in one crash?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"It is the same amount as the minimum for property damage.","h2":"In Nebraska, a vehicle must carry at least $25,000 of coverage for injury to one person in a crash.","p":"Right. The minimum is $25,000 for one injured person."},"es":{"q":"En Nebraska, ¿cuál es el seguro de responsabilidad mínimo por lesiones a una persona en un choque?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"Es la misma cantidad que el mínimo por daños a la propiedad.","h2":"En Nebraska, un vehículo debe tener al menos $25,000 de cobertura por lesiones a una persona en un choque.","p":"Correcto. El mínimo es de $25,000 por una persona lesionada."},"zh":{"q":"在 Nebraska，一次车祸中一人受伤的最低责任保险金额是多少？","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"它和财产损失的最低金额一样。","h2":"在 Nebraska，车辆必须至少有 $25,000 的保险，用于车祸中一人受伤。","p":"对。一人受伤的最低金额是 $25,000。"},"vi":{"q":"Ở Nebraska, bảo hiểm trách nhiệm tối thiểu cho thương tích của một người trong một vụ tai nạn là bao nhiêu?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"Số tiền này bằng mức tối thiểu cho thiệt hại tài sản.","h2":"Ở Nebraska, xe phải có bảo hiểm ít nhất $25,000 cho thương tích của một người trong một vụ tai nạn.","p":"Đúng. Mức tối thiểu là $25,000 cho một người bị thương."},"tl":{"q":"Sa Nebraska, ano ang pinakamababang liability insurance para sa pinsala sa isang tao sa isang aksidente?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"Kapareho ito ng pinakamababang halaga para sa pinsala sa ari-arian.","h2":"Sa Nebraska, dapat may hindi bababa sa $25,000 na coverage ang sasakyan para sa pinsala sa isang tao sa aksidente.","p":"Tama. $25,000 ang pinakamababa para sa isang taong nasaktan."},"ar":{"q":"في Nebraska، ما الحد الأدنى لتأمين المسؤولية (liability insurance) عن إصابة شخص واحد في حادث واحد؟","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"إنه نفس مبلغ الحد الأدنى لأضرار الممتلكات.","h2":"في Nebraska، يجب أن يكون للمركبة تأمين لا يقل عن $25,000 لإصابة شخص واحد في حادث.","p":"صحيح. الحد الأدنى هو $25,000 لشخص واحد مصاب."},"ref":{"doc":"NE","page":28}},{"id":"ne-025","scope":"NE","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Nebraska, what happens to a speeding fine in a school zone, or in a work zone when workers are present?","o":["It stays the same","It is doubled","It is cut in half","It is replaced by a warning"],"h1":"These zones protect children and workers, so the penalty is higher.","h2":"In Nebraska, speeding fines are doubled in school zones and in work zones when workers are present.","p":"Right. Fines are doubled in those zones."},"es":{"q":"En Nebraska, ¿qué pasa con la multa por exceso de velocidad en una zona escolar, o en una zona de obras cuando hay trabajadores?","o":["Se queda igual","Se duplica","Se reduce a la mitad","Se cambia por una advertencia"],"h1":"Estas zonas protegen a niños y trabajadores, así que la sanción es mayor.","h2":"En Nebraska, las multas por exceso de velocidad se duplican en zonas escolares y en zonas de obras cuando hay trabajadores.","p":"Correcto. Las multas se duplican en esas zonas."},"zh":{"q":"在 Nebraska，在学校区，或在有工人在场的施工区超速，罚款会怎么样？","o":["保持不变","加倍","减半","改成警告"],"h1":"这些区域保护孩子和工人，所以处罚更重。","h2":"在 Nebraska，在学校区和有工人在场的施工区超速，罚款会加倍。","p":"对。在这些区域罚款加倍。"},"vi":{"q":"Ở Nebraska, tiền phạt chạy quá tốc độ trong khu vực trường học, hoặc trong khu vực công trường khi có công nhân, sẽ thế nào?","o":["Vẫn như cũ","Tăng gấp đôi","Giảm một nửa","Được thay bằng cảnh cáo"],"h1":"Những khu vực này bảo vệ trẻ em và công nhân, nên hình phạt nặng hơn.","h2":"Ở Nebraska, tiền phạt chạy quá tốc độ tăng gấp đôi trong khu vực trường học và trong khu vực công trường khi có công nhân.","p":"Đúng. Tiền phạt tăng gấp đôi trong những khu vực đó."},"tl":{"q":"Sa Nebraska, ano ang nangyayari sa multa sa sobrang bilis sa school zone, o sa work zone kapag may mga manggagawa?","o":["Hindi ito nagbabago","Nadodoble ito","Nahahati ito sa kalahati","Napapalitan ito ng babala"],"h1":"Pinoprotektahan ng mga zone na ito ang mga bata at manggagawa, kaya mas mabigat ang parusa.","h2":"Sa Nebraska, nadodoble ang multa sa sobrang bilis sa school zone at sa work zone kapag may mga manggagawa.","p":"Tama. Doble ang multa sa mga zone na iyon."},"ar":{"q":"في Nebraska، ماذا يحدث لغرامة تجاوز السرعة في منطقة مدرسية، أو في منطقة أعمال عندما يكون العمّال موجودين؟","o":["تبقى كما هي","تتضاعف","تُخفَّض إلى النصف","تُستبدل بتحذير"],"h1":"هذه المناطق تحمي الأطفال والعمّال، لذلك العقوبة أعلى.","h2":"في Nebraska، تتضاعف غرامات تجاوز السرعة في المناطق المدرسية وفي مناطق الأعمال عندما يكون العمّال موجودين.","p":"صحيح. الغرامات تتضاعف في تلك المناطق."},"ref":{"doc":"NE","page":53}},{"id":"ne-026","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, a new resident has a valid license from another state. How soon must they get a Nebraska license?","o":["Within 10 days","Within 6 months","Within 30 days","Within one year"],"h1":"It is about one month.","h2":"In Nebraska, a new resident with a valid out-of-state license must get a Nebraska license within 30 days.","p":"Right. New residents have 30 days."},"es":{"q":"En Nebraska, un nuevo residente tiene una licencia válida de otro estado. ¿En cuánto tiempo debe obtener una licencia de Nebraska?","o":["Dentro de 10 días","Dentro de 6 meses","Dentro de 30 días","Dentro de un año"],"h1":"Es más o menos un mes.","h2":"En Nebraska, un nuevo residente con una licencia válida de otro estado debe obtener una licencia de Nebraska dentro de 30 días.","p":"Correcto. Los nuevos residentes tienen 30 días."},"zh":{"q":"在 Nebraska，一位新居民有另一个州的有效驾照。他们必须在多久内拿到 Nebraska 驾照？","o":["10 天内","6 个月内","30 天内","一年内"],"h1":"大约是一个月。","h2":"在 Nebraska，有外州有效驾照的新居民必须在 30 天内拿到 Nebraska 驾照。","p":"对。新居民有 30 天。"},"vi":{"q":"Ở Nebraska, một cư dân mới có bằng lái còn hiệu lực của tiểu bang khác. Họ phải có bằng lái Nebraska trong bao lâu?","o":["Trong vòng 10 ngày","Trong vòng 6 tháng","Trong vòng 30 ngày","Trong vòng một năm"],"h1":"Khoảng một tháng.","h2":"Ở Nebraska, cư dân mới có bằng lái còn hiệu lực của tiểu bang khác phải có bằng lái Nebraska trong vòng 30 ngày.","p":"Đúng. Cư dân mới có 30 ngày."},"tl":{"q":"Sa Nebraska, may valid na lisensya mula sa ibang estado ang isang bagong residente. Gaano kabilis siya dapat kumuha ng lisensya ng Nebraska?","o":["Sa loob ng 10 araw","Sa loob ng 6 na buwan","Sa loob ng 30 araw","Sa loob ng isang taon"],"h1":"Mga isang buwan ito.","h2":"Sa Nebraska, ang bagong residente na may valid na lisensya mula sa ibang estado ay dapat kumuha ng lisensya ng Nebraska sa loob ng 30 araw.","p":"Tama. May 30 araw ang mga bagong residente."},"ar":{"q":"في Nebraska، مقيم جديد لديه رخصة سارية من ولاية أخرى. خلال كم من الوقت يجب أن يحصل على رخصة Nebraska؟","o":["خلال 10 أيام","خلال 6 أشهر","خلال 30 يوماً","خلال سنة واحدة"],"h1":"إنها حوالي شهر واحد.","h2":"في Nebraska، يجب على المقيم الجديد الذي لديه رخصة سارية من ولاية أخرى أن يحصل على رخصة Nebraska خلال 30 يوماً.","p":"صحيح. المقيمون الجدد لديهم 30 يوماً."},"ref":{"doc":"NE","page":1}},{"id":"ne-027","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, you are in a crash that no police officer looked into, and someone was hurt. When must you send a crash report to the Department of Transportation?","o":["Within 24 hours","Within 30 days","Only if your insurance company asks","Within 10 days"],"h1":"You have a little more than one week.","h2":"In Nebraska, if no officer investigated and someone was hurt or the damage was $1,500 or more, you must send a crash report within 10 days.","p":"Right. The report is due within 10 days."},"es":{"q":"En Nebraska, usted tiene un choque que ningún policía investigó, y alguien resultó herido. ¿Cuándo debe enviar un reporte del choque al Departamento de Transporte?","o":["Dentro de 24 horas","Dentro de 30 días","Solo si su compañía de seguros lo pide","Dentro de 10 días"],"h1":"Tiene un poco más de una semana.","h2":"En Nebraska, si ningún policía investigó y alguien resultó herido o el daño fue de $1,500 o más, debe enviar un reporte del choque dentro de 10 días.","p":"Correcto. El reporte se debe enviar dentro de 10 días."},"zh":{"q":"在 Nebraska，你发生了一起没有警察调查的车祸，而且有人受伤。你必须在什么时候向交通部（Department of Transportation）提交车祸报告？","o":["24 小时内","30 天内","只有保险公司要求时","10 天内"],"h1":"你有一个多星期的时间。","h2":"在 Nebraska，如果没有警察调查，而且有人受伤或损失达到 $1,500 或更多，你必须在 10 天内提交车祸报告。","p":"对。报告要在 10 天内提交。"},"vi":{"q":"Ở Nebraska, bạn bị tai nạn mà không có cảnh sát điều tra, và có người bị thương. Khi nào bạn phải gửi báo cáo tai nạn cho Sở Giao thông (Department of Transportation)?","o":["Trong vòng 24 giờ","Trong vòng 30 ngày","Chỉ khi công ty bảo hiểm yêu cầu","Trong vòng 10 ngày"],"h1":"Bạn có hơn một tuần một chút.","h2":"Ở Nebraska, nếu không có cảnh sát điều tra và có người bị thương hoặc thiệt hại từ $1,500 trở lên, bạn phải gửi báo cáo tai nạn trong vòng 10 ngày.","p":"Đúng. Báo cáo phải nộp trong vòng 10 ngày."},"tl":{"q":"Sa Nebraska, naaksidente ka at walang pulis na nag-imbestiga, at may nasaktan. Kailan mo dapat ipadala ang crash report sa Department of Transportation?","o":["Sa loob ng 24 na oras","Sa loob ng 30 araw","Kapag hiningi lang ng insurance company mo","Sa loob ng 10 araw"],"h1":"May kaunti kang higit sa isang linggo.","h2":"Sa Nebraska, kung walang pulis na nag-imbestiga at may nasaktan o umabot sa $1,500 o higit pa ang pinsala, dapat kang magpadala ng crash report sa loob ng 10 araw.","p":"Tama. Dapat maipadala ang report sa loob ng 10 araw."},"ar":{"q":"في Nebraska، تعرّضت لحادث لم يحقق فيه أي شرطي، وأُصيب شخص. متى يجب أن ترسل تقرير الحادث إلى وزارة النقل (Department of Transportation)؟","o":["خلال 24 ساعة","خلال 30 يوماً","فقط إذا طلبت شركة التأمين","خلال 10 أيام"],"h1":"لديك أكثر من أسبوع بقليل.","h2":"في Nebraska، إذا لم يحقق أي شرطي في الحادث وأُصيب شخص أو كانت الأضرار $1,500 أو أكثر، يجب أن ترسل تقرير الحادث خلال 10 أيام.","p":"صحيح. التقرير مطلوب خلال 10 أيام."},"ref":{"doc":"NE","page":73}},{"id":"ne-028","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, what happens if you fail the drive test three times in a row?","o":["You must wait one full year to try again","You need a driver training course or 90 days with an LPD","You must pay a double fee and test the next day","You lose your learner's permit for six months"],"h1":"You need more training or more practice time before you can try again.","h2":"In Nebraska, after three failed drive tests in a row, you must finish an approved driver training course or hold an LPD for at least 90 days before you apply again.","p":"Right. Take a course or practice with an LPD for 90 days."},"es":{"q":"En Nebraska, ¿qué pasa si reprueba el examen de manejo tres veces seguidas?","o":["Debe esperar un año completo para intentarlo otra vez","Necesita un curso de manejo o 90 días con un LPD","Debe pagar el doble y examinarse al día siguiente","Pierde su permiso de aprendiz por seis meses"],"h1":"Necesita más entrenamiento o más tiempo de práctica antes de intentarlo otra vez.","h2":"En Nebraska, después de reprobar tres veces seguidas el examen de manejo, debe terminar un curso de manejo aprobado o tener un LPD por al menos 90 días antes de volver a solicitar.","p":"Correcto. Tome un curso o practique con un LPD por 90 días."},"zh":{"q":"在 Nebraska，如果你连续三次路考不及格，会怎么样？","o":["你必须等整整一年才能再考","你需要上驾驶培训课，或持有 LPD 满 90 天","你必须付双倍费用，第二天再考","你的学习驾照会被收回六个月"],"h1":"你需要更多培训或更多练习时间，才能再考。","h2":"在 Nebraska，连续三次路考不及格后，你必须完成一门认可的驾驶培训课，或持有 LPD 至少 90 天，然后才能再次申请。","p":"对。去上课，或持 LPD 练习 90 天。"},"vi":{"q":"Ở Nebraska, chuyện gì xảy ra nếu bạn thi lái xe trượt ba lần liên tiếp?","o":["Bạn phải chờ đủ một năm mới được thi lại","Bạn cần học một khóa đào tạo lái xe hoặc có LPD 90 ngày","Bạn phải trả gấp đôi lệ phí và thi vào ngày hôm sau","Bạn bị mất giấy phép tập lái trong sáu tháng"],"h1":"Bạn cần học thêm hoặc tập thêm trước khi thi lại.","h2":"Ở Nebraska, sau khi thi lái xe trượt ba lần liên tiếp, bạn phải học xong một khóa đào tạo lái xe được chấp thuận hoặc có LPD ít nhất 90 ngày trước khi nộp đơn lại.","p":"Đúng. Học một khóa hoặc tập lái với LPD trong 90 ngày."},"tl":{"q":"Sa Nebraska, ano ang mangyayari kung bumagsak ka sa drive test nang tatlong beses na sunud-sunod?","o":["Dapat kang maghintay ng isang buong taon bago sumubok ulit","Kailangan mo ng driver training course o 90 araw na may LPD","Dapat kang magbayad ng dobleng bayad at mag-test kinabukasan","Mawawala ang learner's permit mo nang anim na buwan"],"h1":"Kailangan mo ng dagdag na training o dagdag na oras ng pagsasanay bago sumubok ulit.","h2":"Sa Nebraska, pagkatapos bumagsak sa drive test nang tatlong beses na sunud-sunod, dapat mong tapusin ang isang aprubadong driver training course o magkaroon ng LPD nang hindi bababa sa 90 araw bago mag-apply ulit.","p":"Tama. Mag-course o magsanay gamit ang LPD nang 90 araw."},"ar":{"q":"في Nebraska، ماذا يحدث إذا رسبت في اختبار القيادة ثلاث مرات متتالية؟","o":["يجب أن تنتظر سنة كاملة لتحاول مرة أخرى","تحتاج إلى دورة تدريب على القيادة أو 90 يوماً مع تصريح LPD","يجب أن تدفع رسوماً مضاعفة وتختبر في اليوم التالي","تفقد تصريح التعلّم لمدة ستة أشهر"],"h1":"تحتاج إلى تدريب أكثر أو وقت تمرين أطول قبل أن تحاول مرة أخرى.","h2":"في Nebraska، بعد الرسوب في اختبار القيادة ثلاث مرات متتالية، يجب أن تُكمل دورة تدريب على القيادة معتمدة أو أن تحمل تصريح LPD لمدة 90 يوماً على الأقل قبل أن تتقدّم مرة أخرى.","p":"صحيح. خذ دورة أو تمرّن مع تصريح LPD لمدة 90 يوماً."},"ref":{"doc":"NE","page":12}},{"id":"ne-029","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, when does a license issued to a driver under 21 expire?","o":["On the driver's 21st birthday","On the driver's 18th birthday","One year after it is issued","Five years after it is issued"],"h1":"It is tied to the age when adult alcohol rules begin.","h2":"In Nebraska, a license issued to someone under 21 expires on the driver's 21st birthday.","p":"Right. It expires on the 21st birthday."},"es":{"q":"En Nebraska, ¿cuándo vence una licencia emitida a un conductor menor de 21 años?","o":["El día que cumple 21 años","El día que cumple 18 años","Un año después de emitida","Cinco años después de emitida"],"h1":"Está ligada a la edad en que empiezan las reglas de alcohol para adultos.","h2":"En Nebraska, la licencia emitida a una persona menor de 21 años vence el día que el conductor cumple 21 años.","p":"Correcto. Vence al cumplir 21 años."},"zh":{"q":"在 Nebraska，发给 21 岁以下驾驶人的驾照什么时候到期？","o":["在驾驶人 21 岁生日那天","在驾驶人 18 岁生日那天","发证后一年","发证后五年"],"h1":"这和成年人饮酒规定开始的年龄有关。","h2":"在 Nebraska，发给 21 岁以下的人的驾照，在驾驶人 21 岁生日那天到期。","p":"对。驾照在 21 岁生日那天到期。"},"vi":{"q":"Ở Nebraska, bằng lái cấp cho người lái dưới 21 tuổi hết hạn khi nào?","o":["Vào sinh nhật lần thứ 21 của người lái","Vào sinh nhật lần thứ 18 của người lái","Một năm sau khi được cấp","Năm năm sau khi được cấp"],"h1":"Nó gắn với tuổi bắt đầu áp dụng luật rượu bia cho người lớn.","h2":"Ở Nebraska, bằng lái cấp cho người dưới 21 tuổi hết hạn vào sinh nhật lần thứ 21 của người lái.","p":"Đúng. Bằng lái hết hạn vào sinh nhật lần thứ 21."},"tl":{"q":"Sa Nebraska, kailan mag-e-expire ang lisensyang ibinigay sa driver na wala pang 21?","o":["Sa ika-21 kaarawan ng driver","Sa ika-18 kaarawan ng driver","Isang taon pagkatapos itong ibigay","Limang taon pagkatapos itong ibigay"],"h1":"Nakatali ito sa edad kung kailan nagsisimula ang mga patakaran sa alak para sa adult.","h2":"Sa Nebraska, ang lisensyang ibinigay sa taong wala pang 21 ay mag-e-expire sa ika-21 kaarawan ng driver.","p":"Tama. Mag-e-expire ito sa ika-21 kaarawan."},"ar":{"q":"في Nebraska، متى تنتهي صلاحية الرخصة الصادرة لسائق عمره أقل من 21 سنة؟","o":["في عيد ميلاد السائق الحادي والعشرين (21)","في عيد ميلاد السائق الثامن عشر (18)","بعد سنة واحدة من صدورها","بعد خمس سنوات من صدورها"],"h1":"الأمر مرتبط بالعمر الذي تبدأ فيه قواعد الكحول الخاصة بالبالغين.","h2":"في Nebraska، تنتهي صلاحية الرخصة الصادرة لشخص عمره أقل من 21 سنة في عيد ميلاد السائق الحادي والعشرين (21).","p":"صحيح. تنتهي صلاحيتها في عيد الميلاد الحادي والعشرين (21)."},"ref":{"doc":"NE","page":15}},{"id":"ne-030","scope":"NE","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Nebraska, it is illegal to pass another vehicle within what distance of an intersection or railroad crossing?","o":["25 feet","50 feet","100 feet","500 feet"],"h1":"It is about the length of a few houses.","h2":"In Nebraska, it is illegal to pass another vehicle within 100 feet of an intersection or a railroad crossing.","p":"Right. No passing within 100 feet of either one."},"es":{"q":"En Nebraska, ¿a qué distancia de una intersección o de un cruce de ferrocarril es ilegal rebasar a otro vehículo?","o":["25 pies","50 pies","100 pies","500 pies"],"h1":"Es más o menos el largo de unas cuantas casas.","h2":"En Nebraska, es ilegal rebasar a otro vehículo a menos de 100 pies de una intersección o de un cruce de ferrocarril.","p":"Correcto. No rebase a menos de 100 pies de ninguno de los dos."},"zh":{"q":"在 Nebraska，在距离路口或铁路道口多远以内超车是违法的？","o":["25 英尺","50 英尺","100 英尺","500 英尺"],"h1":"大约是几栋房子的长度。","h2":"在 Nebraska，在距离路口或铁路道口 100 英尺以内超车是违法的。","p":"对。在这两种地方 100 英尺以内都不能超车。"},"vi":{"q":"Ở Nebraska, vượt xe khác trong khoảng cách bao nhiêu gần giao lộ hoặc chỗ băng qua đường ray xe lửa là phạm luật?","o":["25 feet","50 feet","100 feet","500 feet"],"h1":"Khoảng bằng chiều dài của vài căn nhà.","h2":"Ở Nebraska, vượt xe khác trong vòng 100 feet gần giao lộ hoặc chỗ băng qua đường ray xe lửa là phạm luật.","p":"Đúng. Không được vượt trong vòng 100 feet gần cả hai nơi này."},"tl":{"q":"Sa Nebraska, bawal mag-overtake sa ibang sasakyan sa loob ng anong layo mula sa intersection o railroad crossing?","o":["25 feet","50 feet","100 feet","500 feet"],"h1":"Mga kasinghaba ito ng ilang bahay.","h2":"Sa Nebraska, bawal mag-overtake sa ibang sasakyan sa loob ng 100 feet mula sa intersection o railroad crossing.","p":"Tama. Bawal mag-overtake sa loob ng 100 feet mula sa alinman sa dalawa."},"ar":{"q":"في Nebraska، يُمنع تجاوز مركبة أخرى ضمن أي مسافة من التقاطع أو من معبر السكة الحديدية؟","o":["25 قدماً","50 قدماً","100 قدم","500 قدم"],"h1":"إنها تقريباً بطول بضعة بيوت.","h2":"في Nebraska، يُمنع تجاوز مركبة أخرى ضمن 100 قدم من التقاطع أو من معبر السكة الحديدية.","p":"صحيح. لا تجاوز ضمن 100 قدم من أيّ منهما."},"ref":{"doc":"NE","page":53}},{"id":"ne-031","scope":"NE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nebraska, a snowplow is working on the road ahead. Unless you are passing, how far back should you stay?","o":["20 feet","50 feet","75 feet","100 feet"],"h1":"Sand and chunks of ice can fly off the plow.","h2":"In Nebraska, you should stay 100 feet behind a snowplow or other road maintenance vehicle that is working, unless you are passing.","p":"Right. Keep 100 feet behind a working snowplow."},"es":{"q":"En Nebraska, un quitanieves está trabajando en la carretera delante de usted. Si no va a rebasar, ¿a qué distancia debe mantenerse?","o":["20 pies","50 pies","75 pies","100 pies"],"h1":"Del quitanieves pueden salir volando arena y trozos de hielo.","h2":"En Nebraska, debe mantenerse a 100 pies detrás de un quitanieves u otro vehículo de mantenimiento que esté trabajando, a menos que vaya a rebasar.","p":"Correcto. Manténgase a 100 pies de un quitanieves que trabaja."},"zh":{"q":"在 Nebraska，前方道路上有一辆扫雪车正在工作。除非你要超车，你应该在后面保持多远？","o":["20 英尺","50 英尺","75 英尺","100 英尺"],"h1":"沙子和冰块可能会从扫雪车上飞出来。","h2":"在 Nebraska，除非你要超车，你应该在正在工作的扫雪车或其他道路养护车后面保持 100 英尺。","p":"对。在正在工作的扫雪车后面保持 100 英尺。"},"vi":{"q":"Ở Nebraska, có một xe ủi tuyết đang làm việc trên đường phía trước. Trừ khi bạn đang vượt, bạn nên giữ khoảng cách phía sau bao xa?","o":["20 feet","50 feet","75 feet","100 feet"],"h1":"Cát và những cục băng có thể văng ra từ xe ủi tuyết.","h2":"Ở Nebraska, bạn nên ở cách 100 feet phía sau xe ủi tuyết hoặc xe bảo trì đường khác đang làm việc, trừ khi bạn đang vượt.","p":"Đúng. Giữ cách 100 feet phía sau xe ủi tuyết đang làm việc."},"tl":{"q":"Sa Nebraska, may snowplow na nagtatrabaho sa daan sa unahan mo. Maliban kung nag-o-overtake ka, gaano kalayo ka dapat manatili sa likod?","o":["20 feet","50 feet","75 feet","100 feet"],"h1":"Puwedeng tumilapon ang buhangin at piraso ng yelo mula sa snowplow.","h2":"Sa Nebraska, dapat kang manatili nang 100 feet sa likod ng snowplow o ibang sasakyang pang-maintenance ng daan na nagtatrabaho, maliban kung nag-o-overtake ka.","p":"Tama. Manatili nang 100 feet sa likod ng nagtatrabahong snowplow."},"ar":{"q":"في Nebraska، هناك كاسحة ثلج تعمل على الطريق أمامك. ما لم تكن تتجاوزها، على أي مسافة يجب أن تبقى خلفها؟","o":["20 قدماً","50 قدماً","75 قدماً","100 قدم"],"h1":"قد يتطاير الرمل وقطع الجليد من كاسحة الثلج.","h2":"في Nebraska، يجب أن تبقى على بُعد 100 قدم خلف كاسحة الثلج أو أي مركبة صيانة طرق أخرى تعمل، ما لم تكن تتجاوزها.","p":"صحيح. ابقَ على بُعد 100 قدم خلف كاسحة الثلج التي تعمل."},"ref":{"doc":"NE","page":70}},{"id":"ne-032","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, how long is a learner's permit (LPD) valid?","o":["Six months after it is issued","One year after it is issued","Until the 16th birthday","Two years after it is issued"],"h1":"It lasts longer than the six-month school learner's permit.","h2":"In Nebraska, a learner's permit (LPD) expires one year after the date it is issued.","p":"Right. The LPD is good for one year."},"es":{"q":"En Nebraska, ¿por cuánto tiempo es válido el permiso de aprendiz (LPD)?","o":["Seis meses después de emitido","Un año después de emitido","Hasta cumplir 16 años","Dos años después de emitido"],"h1":"Dura más que el permiso escolar de aprendiz de seis meses.","h2":"En Nebraska, el permiso de aprendiz (LPD) vence un año después de la fecha en que se emite.","p":"Correcto. El LPD es válido por un año."},"ref":{"doc":"NE","page":4}},{"id":"ne-033","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, when does a provisional operator's permit (POP) expire?","o":["On the 16th birthday","One year after it is issued","On the 21st birthday","On the 18th birthday"],"h1":"It ends when the driver becomes an adult.","h2":"In Nebraska, a provisional operator's permit (POP) expires on the holder's 18th birthday.","p":"Right. The POP ends at 18."},"es":{"q":"En Nebraska, ¿cuándo vence el permiso provisional de operador (POP)?","o":["Al cumplir 16 años","Un año después de emitido","Al cumplir 21 años","Al cumplir 18 años"],"h1":"Termina cuando el conductor llega a la mayoría de edad.","h2":"En Nebraska, el permiso provisional de operador (POP) vence cuando el titular cumple 18 años.","p":"Correcto. El POP termina a los 18."},"ref":{"doc":"NE","page":5}},{"id":"ne-034","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, a School Permit (SCP) lets a young teen drive to school. Where must the teen live or go to school to get one?","o":["Outside a city of 5,000 or more people","Inside a city of 50,000 or more people","Within one mile of the school","In a county with no school buses"],"h1":"This permit is meant for teens in small towns and the country.","h2":"In Nebraska, a School Permit can be issued to a teen who lives, or goes to school, outside a city of 5,000 or more people.","p":"Right. The SCP is for teens outside cities of 5,000 or more."},"es":{"q":"En Nebraska, el permiso escolar (SCP) permite a un adolescente joven manejar a la escuela. ¿Dónde debe vivir o estudiar el adolescente para obtenerlo?","o":["Fuera de una ciudad de 5,000 habitantes o más","Dentro de una ciudad de 50,000 habitantes o más","A menos de una milla de la escuela","En un condado sin autobuses escolares"],"h1":"Este permiso es para adolescentes de pueblos pequeños y del campo.","h2":"En Nebraska, el permiso escolar se puede dar a un adolescente que vive, o estudia, fuera de una ciudad de 5,000 habitantes o más.","p":"Correcto. El SCP es para adolescentes fuera de ciudades de 5,000 o más."},"ref":{"doc":"NE","page":2}},{"id":"ne-035","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, you change your name or move to a new address. How soon must you update your license?","o":["Within 10 days","Within 30 days","Within 60 days","Within 90 days"],"h1":"It is about two months.","h2":"In Nebraska, state law says you must report a name or address change within 60 days.","p":"Right. You have 60 days to update it."},"es":{"q":"En Nebraska, usted cambia de nombre o se muda a otra dirección. ¿En cuánto tiempo debe actualizar su licencia?","o":["Dentro de 10 días","Dentro de 30 días","Dentro de 60 días","Dentro de 90 días"],"h1":"Son unos dos meses.","h2":"En Nebraska, la ley estatal dice que debe informar un cambio de nombre o de dirección dentro de 60 días.","p":"Correcto. Tiene 60 días para actualizarla."},"ref":{"doc":"NE","page":16}},{"id":"ne-036","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, a driver finishes a DMV-approved driver improvement course before reaching 12 points. What may the driver get?","o":["All points are erased","A credit of 2 points","A credit of 6 points","A free license renewal"],"h1":"The credit is small, and it can be used only once every five years.","h2":"In Nebraska, a driver who finishes a DMV-approved driver improvement course before reaching 12 points may get a 2-point credit, once every five years.","p":"Right. The course can earn a 2-point credit."},"es":{"q":"En Nebraska, un conductor termina un curso de mejora para conductores aprobado por el DMV antes de llegar a 12 puntos. ¿Qué puede recibir?","o":["Se borran todos los puntos","Un crédito de 2 puntos","Un crédito de 6 puntos","Una renovación de licencia gratis"],"h1":"El crédito es pequeño y solo se puede usar una vez cada cinco años.","h2":"En Nebraska, un conductor que termina un curso de mejora aprobado por el DMV antes de llegar a 12 puntos puede recibir un crédito de 2 puntos, una vez cada cinco años.","p":"Correcto. El curso puede dar un crédito de 2 puntos."},"ref":{"doc":"NE","page":19}},{"id":"ne-037","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, how many points go on a regular (Class O) license holder's record for reading, typing or sending a text on a handheld phone while driving?","o":["2 points","No points","6 points","3 points"],"h1":"It is more than for most small violations, but less than for drunk driving.","h2":"In Nebraska, using a handheld phone to read, type or send written messages while driving adds 3 points to your record.","p":"Right. Texting while driving costs 3 points."},"es":{"q":"En Nebraska, ¿cuántos puntos se agregan al historial de un conductor con licencia regular (Clase O) por leer, escribir o enviar un mensaje de texto en un teléfono de mano mientras maneja?","o":["2 puntos","Ningún punto","6 puntos","3 puntos"],"h1":"Es más que por la mayoría de las faltas pequeñas, pero menos que por manejar ebrio.","h2":"En Nebraska, usar un teléfono de mano para leer, escribir o enviar mensajes mientras maneja agrega 3 puntos a su historial.","p":"Correcto. Enviar textos al manejar cuesta 3 puntos."},"ref":{"doc":"NE","page":19}},{"id":"ne-038","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, a driver's license is revoked under the point system for the second time in five years. How long is this revocation?","o":["Three years","Six months","One year","Ten years"],"h1":"It is much longer than the first six-month revocation.","h2":"In Nebraska, a driver whose license is revoked under the point system twice in five years loses it for three years.","p":"Right. A second point revocation lasts three years."},"es":{"q":"En Nebraska, a un conductor le revocan la licencia por el sistema de puntos por segunda vez en cinco años. ¿Cuánto dura esta revocación?","o":["Tres años","Seis meses","Un año","Diez años"],"h1":"Es mucho más larga que la primera revocación de seis meses.","h2":"En Nebraska, un conductor a quien le revocan la licencia por el sistema de puntos dos veces en cinco años la pierde por tres años.","p":"Correcto. Una segunda revocación por puntos dura tres años."},"ref":{"doc":"NE","page":18}},{"id":"ne-039","scope":"NE","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Nebraska, a first-time offender fails an alcohol test after a DUI arrest. How long is the administrative license revocation?","o":["30 days","90 days","180 days","Two years"],"h1":"It is about half a year.","h2":"In Nebraska, a first-time offender who fails an alcohol test has the license administratively revoked for 180 days.","p":"Right. A first failed test means 180 days."},"es":{"q":"En Nebraska, un conductor sin infracciones anteriores no pasa la prueba de alcohol después de un arresto por manejar ebrio (DUI). ¿Cuánto dura la revocación administrativa de la licencia?","o":["30 días","90 días","180 días","Dos años"],"h1":"Es más o menos medio año.","h2":"En Nebraska, a quien no pasa una prueba de alcohol por primera vez se le revoca la licencia de forma administrativa por 180 días.","p":"Correcto. La primera prueba fallida significa 180 días."},"ref":{"doc":"NE","page":20}},{"id":"ne-040","scope":"NE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nebraska, a police officer takes your license because you failed or refused an alcohol test. How long is the temporary license you get valid?","o":["24 hours","15 days","30 days","60 days"],"h1":"It is about two weeks.","h2":"In Nebraska, after an officer takes your license for a failed or refused alcohol test, the temporary license expires 15 days after it is issued.","p":"Right. The temporary license lasts 15 days."},"es":{"q":"En Nebraska, un policía le quita la licencia porque usted no pasó o se negó a una prueba de alcohol. ¿Por cuánto tiempo es válida la licencia temporal que recibe?","o":["24 horas","15 días","30 días","60 días"],"h1":"Son unas dos semanas.","h2":"En Nebraska, después de que un policía le quita la licencia por no pasar o negarse a una prueba de alcohol, la licencia temporal vence 15 días después de emitida.","p":"Correcto. La licencia temporal dura 15 días."},"ref":{"doc":"NE","page":20}},{"id":"ne-041","scope":"NE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nebraska, a driver under 21 is convicted of driving with a blood alcohol level of .02 or more. What does the court do with the license?","o":["Nothing, it is only a warning","Revokes it for one year","Suspends it for six months","Impounds it for 30 days"],"h1":"The court holds the license for about a month.","h2":"In Nebraska, for a driver under 21 convicted at .02, the court impounds the license for 30 days.","p":"Right. The court holds the license for 30 days."},"es":{"q":"En Nebraska, un conductor menor de 21 años es condenado por manejar con un nivel de alcohol en la sangre de .02 o más. ¿Qué hace el tribunal con la licencia?","o":["Nada, es solo una advertencia","La revoca por un año","La suspende por seis meses","La retiene por 30 días"],"h1":"El tribunal guarda la licencia por más o menos un mes.","h2":"En Nebraska, si un conductor menor de 21 años es condenado con .02, el tribunal retiene su licencia por 30 días.","p":"Correcto. El tribunal retiene la licencia por 30 días."},"ref":{"doc":"NE","page":20}},{"id":"ne-042","scope":"NE","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nebraska, until when must a young child ride in a rear-facing car seat?","o":["Until age 2, or until the seat's height or weight limit","Until age 6 months","Until age 4","Until age 8"],"h1":"Think of a toddler, not a baby or a school child.","h2":"In Nebraska, children ride rear-facing until age 2, or until they reach the height or weight limit set by the car seat maker.","p":"Right. Rear-facing until age 2 or the seat's limit."},"es":{"q":"En Nebraska, ¿hasta cuándo debe un niño pequeño ir en un asiento de seguridad mirando hacia atrás?","o":["Hasta los 2 años, o hasta el límite de altura o peso del asiento","Hasta los 6 meses","Hasta los 4 años","Hasta los 8 años"],"h1":"Piense en un niño que empieza a caminar, no en un bebé ni en un escolar.","h2":"En Nebraska, los niños van mirando hacia atrás hasta los 2 años, o hasta llegar al límite de altura o peso que fija el fabricante del asiento.","p":"Correcto. Mirando hacia atrás hasta los 2 años o el límite del asiento."},"ref":{"doc":"NE","page":26}},{"id":"ne-043","scope":"NE","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Nebraska, your steering wheel has an air bag. How much space should you leave between yourself and the wheel?","o":["About 2 inches","About 5 inches","At least 10 inches","Exactly 24 inches"],"h1":"An air bag opens with great force, so give it room.","h2":"In Nebraska, a driver should leave at least 10 inches between themselves and a steering wheel with an air bag.","p":"Right. Keep at least 10 inches from the wheel."},"es":{"q":"En Nebraska, su volante tiene bolsa de aire. ¿Cuánto espacio debe dejar entre usted y el volante?","o":["Unas 2 pulgadas","Unas 5 pulgadas","Por lo menos 10 pulgadas","Exactamente 24 pulgadas"],"h1":"La bolsa de aire se abre con mucha fuerza, así que déjele espacio.","h2":"En Nebraska, el conductor debe dejar por lo menos 10 pulgadas entre su cuerpo y un volante con bolsa de aire.","p":"Correcto. Manténgase por lo menos a 10 pulgadas del volante."},"ref":{"doc":"NE","page":26}},{"id":"ne-044","scope":"NE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nebraska, a deer jumps onto the road and you are about to hit it. What is the safest thing to do?","o":["Swerve hard into the other lane","Brake firmly, keep control, and do not swerve","Speed up to get past it","Steer off the road into the ditch"],"h1":"Nebraska says: Don't veer for deer.","h2":"In Nebraska, if you are about to hit a deer, the safest action is to brake firmly, steer to keep control and stop, instead of swerving.","p":"Right. Brake, keep control, and don't veer."},"es":{"q":"En Nebraska, un venado salta a la carretera y está a punto de chocarlo. ¿Qué es lo más seguro?","o":["Desviarse con fuerza al otro carril","Frenar con firmeza, mantener el control y no desviarse","Acelerar para pasarlo","Salirse de la carretera hacia la cuneta"],"h1":"Nebraska dice: no se desvíe por un venado.","h2":"En Nebraska, si está a punto de chocar con un venado, lo más seguro es frenar con firmeza, mantener el control y detenerse, en vez de desviarse.","p":"Correcto. Frene, mantenga el control y no se desvíe."},"ref":{"doc":"NE","page":26}},{"id":"ne-045","scope":"NE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nebraska, when is it legal to use studded tires?","o":["Any time of year","Only in January and February","From October 1 to May 1","From November 1 to April 1"],"h1":"It covers the snowy months, from late fall to early spring.","h2":"In Nebraska, studded tires are legal only from November 1 to April 1.","p":"Right. Studded tires: November 1 to April 1."},"es":{"q":"En Nebraska, ¿cuándo es legal usar llantas con clavos?","o":["En cualquier época del año","Solo en enero y febrero","Del 1 de octubre al 1 de mayo","Del 1 de noviembre al 1 de abril"],"h1":"Cubre los meses de nieve, de fines de otoño a principios de primavera.","h2":"En Nebraska, las llantas con clavos son legales solo del 1 de noviembre al 1 de abril.","p":"Correcto. Llantas con clavos: del 1 de noviembre al 1 de abril."},"ref":{"doc":"NE","page":63}},{"id":"ne-046","scope":"NE","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Nebraska, what is the minimum speed on the interstate?","o":["40 mph","30 mph","45 mph","55 mph"],"h1":"It is well below the usual interstate limit, but not very slow.","h2":"In Nebraska, the minimum speed on the interstate is 40 mph.","p":"Right. Do not drive under 40 mph on the interstate."},"es":{"q":"En Nebraska, ¿cuál es la velocidad mínima en la autopista interestatal?","o":["40 mph","30 mph","45 mph","55 mph"],"h1":"Está muy por debajo del límite normal de la interestatal, pero no es muy lenta.","h2":"En Nebraska, la velocidad mínima en la autopista interestatal es de 40 mph.","p":"Correcto. No maneje a menos de 40 mph en la interestatal."},"ref":{"doc":"NE","page":60}},{"id":"ne-047","scope":"NE","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Nebraska, what is the speed limit on a gravel road when no sign says otherwise?","o":["35 mph","45 mph","50 mph","55 mph"],"h1":"It is 5 mph lower than on a paved road off the state highway system.","h2":"In Nebraska, the speed limit on a gravel road is 50 mph unless a sign shows a different limit.","p":"Right. Gravel roads: 50 mph unless posted."},"es":{"q":"En Nebraska, ¿cuál es el límite de velocidad en un camino de grava cuando ninguna señal indica otro?","o":["35 mph","45 mph","50 mph","55 mph"],"h1":"Es 5 mph menos que en un camino pavimentado fuera del sistema de carreteras estatales.","h2":"En Nebraska, el límite de velocidad en un camino de grava es de 50 mph, a menos que una señal indique otro límite.","p":"Correcto. Caminos de grava: 50 mph si no hay señal."},"ref":{"doc":"NE","page":52}},{"id":"ne-048","scope":"NE","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Nebraska, a school bus ahead turns on its flashing amber (yellow) lights. What should you do?","o":["Pass it quickly before it stops","Slow to 25 mph and get ready to stop","Keep your speed; the lights are only for the bus driver","Honk so the children know you are coming"],"h1":"Amber lights mean the bus is about to stop for children.","h2":"In Nebraska, when a school bus shows its amber warning lights, you must slow to 25 mph and get ready to stop.","p":"Right. Slow to 25 mph and be ready to stop."},"es":{"q":"En Nebraska, un autobús escolar delante de usted enciende sus luces ámbar (amarillas) intermitentes. ¿Qué debe hacer?","o":["Rebasarlo rápido antes de que se detenga","Bajar a 25 mph y prepararse para detenerse","Mantener su velocidad; las luces son solo para el conductor del autobús","Tocar la bocina para que los niños sepan que viene"],"h1":"Las luces ámbar indican que el autobús está por detenerse para los niños.","h2":"En Nebraska, cuando un autobús escolar enciende sus luces ámbar de advertencia, debe bajar a 25 mph y prepararse para detenerse.","p":"Correcto. Baje a 25 mph y prepárese para detenerse."},"ref":{"doc":"NE","page":70}},{"id":"ne-049","scope":"NE","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Nebraska, a fire truck is going to an emergency. How close behind it may you follow?","o":["100 feet","200 feet","300 feet","No closer than 500 feet"],"h1":"It is more than the length of a football field.","h2":"In Nebraska, you may not follow a fire truck on an emergency call closer than 500 feet.","p":"Right. Stay at least 500 feet behind a fire truck."},"es":{"q":"En Nebraska, un camión de bomberos va a una emergencia. ¿A qué distancia detrás de él puede seguirlo?","o":["100 pies","200 pies","300 pies","No más cerca de 500 pies"],"h1":"Es más que el largo de un campo de fútbol americano.","h2":"En Nebraska, no puede seguir a un camión de bomberos que va a una emergencia a menos de 500 pies.","p":"Correcto. Manténgase por lo menos a 500 pies de un camión de bomberos."},"ref":{"doc":"NE","page":52}},{"id":"ne-050","scope":"NE","cat":"signals","sign":null,"c":0,"en":{"q":"In Nebraska, which vehicles must show the slow-moving vehicle emblem on a public road?","o":["Vehicles that travel 25 mph or less","Vehicles that travel 35 mph or less","Vehicles that travel 45 mph or less","Any vehicle pulling a trailer"],"h1":"Think of farm equipment, which moves very slowly.","h2":"In Nebraska, vehicles that travel 25 mph or less, such as farm equipment, must show the slow-moving vehicle emblem on a public road.","p":"Right. The emblem is for vehicles at 25 mph or less."},"es":{"q":"En Nebraska, ¿qué vehículos deben mostrar el emblema de vehículo lento en una vía pública?","o":["Los vehículos que andan a 25 mph o menos","Los vehículos que andan a 35 mph o menos","Los vehículos que andan a 45 mph o menos","Cualquier vehículo que jala un remolque"],"h1":"Piense en la maquinaria agrícola, que avanza muy despacio.","h2":"En Nebraska, los vehículos que andan a 25 mph o menos, como la maquinaria agrícola, deben mostrar el emblema de vehículo lento en una vía pública.","p":"Correcto. El emblema es para vehículos a 25 mph o menos."},"ref":{"doc":"NE","page":42}},{"id":"nh-001","scope":"NH","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Hampshire, what score do you need to pass a knowledge test?","o":["60 percent","70 percent","80 percent","90 percent"],"h1":"It is the same as getting 4 out of 5 right.","h2":"Every New Hampshire knowledge test requires a passing grade of 80 percent.","p":"Right. You need 80 percent."},"es":{"q":"En New Hampshire, ¿qué puntaje necesita para aprobar un examen de conocimientos?","o":["60 por ciento","70 por ciento","80 por ciento","90 por ciento"],"h1":"Es lo mismo que acertar 4 de cada 5.","h2":"Todos los exámenes de conocimientos en New Hampshire exigen una nota mínima del 80 por ciento.","p":"Correcto. Necesita el 80 por ciento."},"zh":{"q":"在 New Hampshire，笔试要得多少分才能通过？","o":["60%","70%","80%","90%"],"h1":"它等于 5 道题答对 4 道。","h2":"New Hampshire 的每一种笔试都要求得到 80% 才能通过。","p":"对。你需要 80%。"},"vi":{"q":"Ở New Hampshire, bạn cần bao nhiêu điểm để đậu bài thi kiến thức?","o":["60 phần trăm","70 phần trăm","80 phần trăm","90 phần trăm"],"h1":"Điều này giống như trả lời đúng 4 trên 5 câu.","h2":"Mọi bài thi kiến thức ở New Hampshire đều cần điểm đậu là 80 phần trăm.","p":"Đúng. Bạn cần 80 phần trăm."},"tl":{"q":"Sa New Hampshire, anong iskor ang kailangan mo para pumasa sa knowledge test?","o":["60 porsiyento","70 porsiyento","80 porsiyento","90 porsiyento"],"h1":"Pareho ito ng pagkuha ng 4 na tama sa 5.","h2":"Bawat knowledge test sa New Hampshire ay nangangailangan ng pasadong marka na 80 porsiyento.","p":"Tama. Kailangan mo ng 80 porsiyento."},"ar":{"q":"في New Hampshire، ما الدرجة التي تحتاجها لتنجح في اختبار المعرفة (knowledge test)؟","o":["60 بالمئة","70 بالمئة","80 بالمئة","90 بالمئة"],"h1":"هذا مثل أن تجيب إجابة صحيحة عن 4 من 5.","h2":"كل اختبار معرفة في New Hampshire يحتاج إلى درجة نجاح 80 بالمئة.","p":"صحيح. تحتاج إلى 80 بالمئة."},"ref":{"doc":"NH","page":2}},{"id":"nh-002","scope":"NH","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Hampshire, what is the youngest age to practice driving on public roads with a licensed adult?","o":["15","15 and a half","16","14 and a half"],"h1":"It is six months before the age of 16.","h2":"In New Hampshire a teen may start practice driving at 15 and a half, with a licensed adult in the front seat.","p":"Correct. Practice starts at 15 and a half."},"es":{"q":"En New Hampshire, ¿cuál es la edad mínima para practicar manejo en las calles con un adulto con licencia?","o":["15 años","15 años y medio","16 años","14 años y medio"],"h1":"Es seis meses antes de cumplir 16 años.","h2":"En New Hampshire un joven puede empezar a practicar a los 15 años y medio, con un adulto con licencia en el asiento delantero.","p":"Correcto. La práctica empieza a los 15 años y medio."},"zh":{"q":"在 New Hampshire，最小几岁可以和有驾照的成年人一起在公共道路上练习开车？","o":["15 岁","15 岁半","16 岁","14 岁半"],"h1":"是 16 岁前六个月。","h2":"在 New Hampshire，青少年 15 岁半就可以开始练习开车，前排要有一位有驾照的成年人。","p":"对。15 岁半开始练习。"},"vi":{"q":"Ở New Hampshire, tuổi nhỏ nhất để tập lái trên đường công cộng cùng một người lớn có bằng lái là bao nhiêu?","o":["15","15 tuổi rưỡi","16","14 tuổi rưỡi"],"h1":"Đó là sáu tháng trước tuổi 16.","h2":"Ở New Hampshire, thiếu niên có thể bắt đầu tập lái khi 15 tuổi rưỡi, với một người lớn có bằng lái ngồi ở ghế trước.","p":"Đúng. Tập lái bắt đầu lúc 15 tuổi rưỡi."},"tl":{"q":"Sa New Hampshire, ano ang pinakabatang edad para mag-praktis magmaneho sa pampublikong kalsada kasama ang isang adult na may lisensya?","o":["15","15 at kalahati","16","14 at kalahati"],"h1":"Anim na buwan ito bago ang edad na 16.","h2":"Sa New Hampshire, puwedeng magsimulang mag-praktis magmaneho ang isang teen sa edad na 15 at kalahati, kasama ang isang adult na may lisensya sa upuan sa harap.","p":"Tama. Nagsisimula ang praktis sa 15 at kalahati."},"ar":{"q":"في New Hampshire، ما أصغر عمر للتدرّب على القيادة في الطرق العامة مع شخص بالغ يحمل رخصة؟","o":["15","15 سنة ونصف","16","14 سنة ونصف"],"h1":"هذا العمر قبل 16 سنة بستة أشهر.","h2":"في New Hampshire يمكن للمراهق أن يبدأ التدرّب على القيادة في عمر 15 سنة ونصف، مع شخص بالغ يحمل رخصة في المقعد الأمامي.","p":"صحيح. التدرّب يبدأ في عمر 15 سنة ونصف."},"ref":{"doc":"NH","page":2}},{"id":"nh-004","scope":"NH","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Hampshire, how old must the licensed adult be who supervises a teen's practice driving?","o":["At least 18","At least 19","At least 21","At least 25"],"h1":"It is older than the drinking age.","h2":"In New Hampshire the adult who supervises practice driving must be licensed and at least 25 years old.","p":"Correct. The adult must be 25 or older."},"es":{"q":"En New Hampshire, ¿qué edad debe tener el adulto con licencia que supervisa la práctica de un joven?","o":["Por lo menos 18","Por lo menos 19","Por lo menos 21","Por lo menos 25"],"h1":"Es mayor que la edad legal para tomar alcohol.","h2":"En New Hampshire el adulto que supervisa la práctica debe tener licencia y por lo menos 25 años.","p":"Correcto. El adulto debe tener 25 años o más."},"zh":{"q":"在 New Hampshire，陪同青少年练习开车的有驾照成年人必须几岁？","o":["至少 18 岁","至少 19 岁","至少 21 岁","至少 25 岁"],"h1":"它比可以喝酒的年龄还大。","h2":"在 New Hampshire，陪同练习开车的成年人必须有驾照，而且至少 25 岁。","p":"对。这位成年人必须 25 岁或以上。"},"vi":{"q":"Ở New Hampshire, người lớn có bằng lái giám sát thiếu niên tập lái phải bao nhiêu tuổi?","o":["Ít nhất 18 tuổi","Ít nhất 19 tuổi","Ít nhất 21 tuổi","Ít nhất 25 tuổi"],"h1":"Tuổi này lớn hơn tuổi được phép uống rượu.","h2":"Ở New Hampshire, người lớn giám sát việc tập lái phải có bằng lái và ít nhất 25 tuổi.","p":"Đúng. Người lớn phải từ 25 tuổi trở lên."},"tl":{"q":"Sa New Hampshire, ilang taon dapat ang adult na may lisensya na nagbabantay sa praktis sa pagmamaneho ng isang teen?","o":["Hindi bababa sa 18","Hindi bababa sa 19","Hindi bababa sa 21","Hindi bababa sa 25"],"h1":"Mas matanda ito sa edad na puwedeng uminom ng alak.","h2":"Sa New Hampshire, ang adult na nagbabantay sa praktis sa pagmamaneho ay dapat may lisensya at hindi bababa sa 25 taong gulang.","p":"Tama. Dapat 25 o higit pa ang adult."},"ar":{"q":"في New Hampshire، كم يجب أن يكون عمر الشخص البالغ الذي يحمل رخصة ويشرف على تدرّب المراهق على القيادة؟","o":["18 سنة على الأقل","19 سنة على الأقل","21 سنة على الأقل","25 سنة على الأقل"],"h1":"هذا العمر أكبر من العمر المسموح فيه بشرب الكحول.","h2":"في New Hampshire يجب أن يحمل الشخص البالغ الذي يشرف على التدرّب على القيادة رخصة، وأن يكون عمره 25 سنة على الأقل.","p":"صحيح. يجب أن يكون عمر البالغ 25 سنة أو أكثر."},"ref":{"doc":"NH","page":1}},{"id":"nh-005","scope":"NH","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Hampshire, who must take driver education to get a license?","o":["Everyone, at any age","Only drivers over 65","Applicants under 18","Only drivers from another country"],"h1":"It depends on the applicant's age.","h2":"In New Hampshire driver education is required for anyone under 18 who applies for a driver license.","p":"Right. Under 18 needs driver education."},"es":{"q":"En New Hampshire, ¿quién debe tomar un curso de educación vial para obtener la licencia?","o":["Todos, a cualquier edad","Solo los mayores de 65","Los solicitantes menores de 18 años","Solo los conductores de otro país"],"h1":"Depende de la edad de la persona.","h2":"En New Hampshire el curso de educación vial es obligatorio para toda persona menor de 18 años que solicita una licencia.","p":"Correcto. Menor de 18 necesita educación vial."},"zh":{"q":"在 New Hampshire，谁必须上驾驶教育课才能拿驾照？","o":["每个人，不管几岁","只有 65 岁以上的司机","18 岁以下的申请人","只有来自其他国家的司机"],"h1":"这要看申请人的年龄。","h2":"在 New Hampshire，任何 18 岁以下申请驾照的人都必须上驾驶教育课。","p":"对。18 岁以下需要驾驶教育。"},"vi":{"q":"Ở New Hampshire, ai phải học giáo dục lái xe (driver education) để có bằng lái?","o":["Mọi người, ở bất kỳ tuổi nào","Chỉ người lái xe trên 65 tuổi","Người nộp đơn dưới 18 tuổi","Chỉ người lái xe từ nước khác"],"h1":"Điều này tùy theo tuổi của người nộp đơn.","h2":"Ở New Hampshire, bất kỳ ai dưới 18 tuổi nộp đơn xin bằng lái đều phải học giáo dục lái xe.","p":"Đúng. Dưới 18 tuổi cần học giáo dục lái xe."},"tl":{"q":"Sa New Hampshire, sino ang dapat kumuha ng driver education para magkaroon ng lisensya?","o":["Lahat, kahit anong edad","Mga driver lang na higit sa 65","Mga aplikanteng wala pang 18","Mga driver lang na galing sa ibang bansa"],"h1":"Depende ito sa edad ng aplikante.","h2":"Sa New Hampshire, kailangan ang driver education para sa sinumang wala pang 18 na nag-a-apply ng driver license.","p":"Tama. Kailangan ng driver education kung wala pang 18."},"ar":{"q":"في New Hampshire، من يجب أن يأخذ دورة تعليم القيادة (driver education) ليحصل على رخصة؟","o":["الجميع، في أي عمر","السائقون الذين تزيد أعمارهم عن 65 سنة فقط","المتقدّمون الذين أعمارهم أقل من 18 سنة","السائقون القادمون من بلد آخر فقط"],"h1":"هذا يعتمد على عمر المتقدّم.","h2":"في New Hampshire تعليم القيادة مطلوب من كل شخص عمره أقل من 18 سنة يتقدّم للحصول على رخصة قيادة.","p":"صحيح. من عمره أقل من 18 سنة يحتاج إلى تعليم القيادة."},"ref":{"doc":"NH","page":1}},{"id":"nh-006","scope":"NH","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Hampshire, how many hours of supervised driving must a student log, on top of driver education?","o":["20 hours","40 hours","50 hours","60 hours"],"h1":"It is less than 50.","h2":"A New Hampshire student must log 40 hours of supervised driving with a parent, guardian or other responsible adult before applying for a license.","p":"Correct. Forty supervised hours."},"es":{"q":"En New Hampshire, ¿cuántas horas de manejo supervisado debe registrar un estudiante, además del curso de educación vial?","o":["20 horas","40 horas","50 horas","60 horas"],"h1":"Son menos de 50.","h2":"Un estudiante en New Hampshire debe registrar 40 horas de manejo supervisado con su padre, madre, tutor u otro adulto responsable antes de solicitar la licencia.","p":"Correcto. Cuarenta horas supervisadas."},"zh":{"q":"在 New Hampshire，除了驾驶教育，学生还必须记录多少小时有人监督的驾驶？","o":["20 小时","40 小时","50 小时","60 小时"],"h1":"它少于 50。","h2":"New Hampshire 的学生申请驾照前，必须和父母、监护人或其他负责任的成年人一起记录 40 小时有人监督的驾驶。","p":"对。四十小时有人监督的驾驶。"},"vi":{"q":"Ở New Hampshire, ngoài giáo dục lái xe, học viên phải ghi lại bao nhiêu giờ lái xe có người giám sát?","o":["20 giờ","40 giờ","50 giờ","60 giờ"],"h1":"Số giờ ít hơn 50.","h2":"Học viên ở New Hampshire phải ghi lại 40 giờ lái xe có giám sát với cha mẹ, người giám hộ hoặc một người lớn có trách nhiệm khác trước khi xin bằng lái.","p":"Đúng. Bốn mươi giờ có giám sát."},"tl":{"q":"Sa New Hampshire, ilang oras ng supervised na pagmamaneho ang dapat itala ng estudyante, bukod pa sa driver education?","o":["20 oras","40 oras","50 oras","60 oras"],"h1":"Mas kaunti ito sa 50.","h2":"Ang estudyante sa New Hampshire ay dapat magtala ng 40 oras ng supervised na pagmamaneho kasama ang magulang, guardian o ibang responsableng adult bago mag-apply ng lisensya.","p":"Tama. Apatnapung supervised na oras."},"ar":{"q":"في New Hampshire، كم ساعة من القيادة تحت الإشراف يجب أن يسجّل الطالب، بالإضافة إلى تعليم القيادة؟","o":["20 ساعة","40 ساعة","50 ساعة","60 ساعة"],"h1":"العدد أقل من 50.","h2":"يجب على الطالب في New Hampshire أن يسجّل 40 ساعة من القيادة تحت الإشراف مع أحد الوالدين أو الوصي أو شخص بالغ مسؤول آخر قبل أن يتقدّم للحصول على رخصة.","p":"صحيح. أربعون ساعة تحت الإشراف."},"ref":{"doc":"NH","page":1}},{"id":"nh-007","scope":"NH","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Hampshire, how many of the 40 supervised hours must be at night?","o":["At least 10","At least 2","At least 20","None"],"h1":"It is one quarter of the total.","h2":"At least 10 of the 40 supervised hours in New Hampshire must be driven at night.","p":"Right. Ten hours at night."},"es":{"q":"En New Hampshire, ¿cuántas de las 40 horas supervisadas deben ser de noche?","o":["Por lo menos 10","Por lo menos 2","Por lo menos 20","Ninguna"],"h1":"Es la cuarta parte del total.","h2":"En New Hampshire, por lo menos 10 de las 40 horas supervisadas deben ser de noche.","p":"Correcto. Diez horas de noche."},"zh":{"q":"在 New Hampshire，40 小时有人监督的驾驶中，有多少小时必须在晚上？","o":["至少 10 小时","至少 2 小时","至少 20 小时","不需要"],"h1":"是总数的四分之一。","h2":"在 New Hampshire，40 小时有人监督的驾驶中，至少 10 小时必须在晚上开。","p":"对。十小时在晚上。"},"vi":{"q":"Ở New Hampshire, trong 40 giờ có giám sát, bao nhiêu giờ phải lái vào ban đêm?","o":["Ít nhất 10 giờ","Ít nhất 2 giờ","Ít nhất 20 giờ","Không giờ nào"],"h1":"Đó là một phần tư của tổng số giờ.","h2":"Ở New Hampshire, ít nhất 10 trong 40 giờ có giám sát phải được lái vào ban đêm.","p":"Đúng. Mười giờ vào ban đêm."},"tl":{"q":"Sa New Hampshire, ilan sa 40 supervised na oras ang dapat sa gabi?","o":["Hindi bababa sa 10","Hindi bababa sa 2","Hindi bababa sa 20","Wala"],"h1":"Isang-kapat ito ng kabuuan.","h2":"Hindi bababa sa 10 sa 40 supervised na oras sa New Hampshire ang dapat imaneho sa gabi.","p":"Tama. Sampung oras sa gabi."},"ar":{"q":"في New Hampshire، كم ساعة من الساعات الـ 40 تحت الإشراف يجب أن تكون في الليل؟","o":["10 ساعات على الأقل","ساعتان على الأقل","20 ساعة على الأقل","لا شيء"],"h1":"هذا ربع المجموع.","h2":"في New Hampshire يجب أن تكون 10 ساعات على الأقل من الساعات الـ 40 تحت الإشراف قيادةً في الليل.","p":"صحيح. عشر ساعات في الليل."},"ref":{"doc":"NH","page":1}},{"id":"nh-009","scope":"NH","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Hampshire, when does a Youth Operator License expire?","o":["On the 18th birthday","After one year","On the 21st birthday","After six months"],"h1":"It ends when the driver becomes a full adult in the eyes of most laws.","h2":"A New Hampshire Youth Operator License expires on the holder's 21st birthday.","p":"Right. It expires at 21."},"es":{"q":"En New Hampshire, ¿cuándo vence la licencia de conductor joven (Youth Operator License)?","o":["Al cumplir 18 años","Después de un año","Al cumplir 21 años","Después de seis meses"],"h1":"Termina cuando el conductor llega a la edad adulta para la mayoría de las leyes.","h2":"La licencia de conductor joven de New Hampshire vence el día que su titular cumple 21 años.","p":"Correcto. Vence a los 21."},"zh":{"q":"在 New Hampshire，青少年驾照（Youth Operator License）什么时候到期？","o":["18 岁生日那天","一年以后","21 岁生日那天","六个月以后"],"h1":"在大多数法律看来，司机成为完全的成年人时，它就结束了。","h2":"New Hampshire 的青少年驾照在持有人 21 岁生日那天到期。","p":"对。它在 21 岁时到期。"},"vi":{"q":"Ở New Hampshire, bằng lái dành cho người trẻ (Youth Operator License) hết hạn khi nào?","o":["Vào sinh nhật 18 tuổi","Sau một năm","Vào sinh nhật 21 tuổi","Sau sáu tháng"],"h1":"Nó hết hạn khi người lái trở thành người lớn hoàn toàn theo hầu hết các luật.","h2":"Bằng lái dành cho người trẻ (Youth Operator License) ở New Hampshire hết hạn vào sinh nhật 21 tuổi của người có bằng.","p":"Đúng. Nó hết hạn lúc 21 tuổi."},"tl":{"q":"Sa New Hampshire, kailan mag-e-expire ang Youth Operator License?","o":["Sa ika-18 kaarawan","Pagkalipas ng isang taon","Sa ika-21 kaarawan","Pagkalipas ng anim na buwan"],"h1":"Natatapos ito kapag ganap nang adult ang driver ayon sa karamihan ng batas.","h2":"Ang Youth Operator License sa New Hampshire ay mag-e-expire sa ika-21 kaarawan ng may-hawak nito.","p":"Tama. Mag-e-expire ito sa edad na 21."},"ar":{"q":"في New Hampshire، متى تنتهي رخصة السائق الشاب (Youth Operator License)؟","o":["في عيد الميلاد الـ 18","بعد سنة واحدة","في عيد الميلاد الـ 21","بعد ستة أشهر"],"h1":"تنتهي عندما يصبح السائق بالغًا تمامًا في نظر أغلب القوانين.","h2":"تنتهي رخصة السائق الشاب (Youth Operator License) في New Hampshire في عيد الميلاد الـ 21 لصاحبها.","p":"صحيح. تنتهي في عمر 21 سنة."},"ref":{"doc":"NH","page":4}},{"id":"nh-010","scope":"NH","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Hampshire, during which hours may a Youth Operator License holder not drive?","o":["Midnight to 5 a.m.","1 a.m. to 4 a.m.","11 p.m. to 5 a.m.","10 p.m. to 6 a.m."],"h1":"The window is only three hours long.","h2":"A New Hampshire Youth Operator License holder may not drive between 1 a.m. and 4 a.m.","p":"Correct. No driving from 1 to 4 a.m."},"es":{"q":"En New Hampshire, ¿en qué horario no puede manejar el titular de una licencia de conductor joven?","o":["De medianoche a 5 a.m.","De 1 a.m. a 4 a.m.","De 11 p.m. a 5 a.m.","De 10 p.m. a 6 a.m."],"h1":"El período dura solo tres horas.","h2":"El titular de una licencia de conductor joven en New Hampshire no puede manejar entre la 1 a.m. y las 4 a.m.","p":"Correcto. No se maneja de 1 a 4 a.m."},"zh":{"q":"在 New Hampshire，持青少年驾照的人在哪段时间不能开车？","o":["午夜到早上 5 点","凌晨 1 点到凌晨 4 点","晚上 11 点到早上 5 点","晚上 10 点到早上 6 点"],"h1":"这段时间只有三个小时。","h2":"New Hampshire 持青少年驾照的人在凌晨 1 点到凌晨 4 点之间不能开车。","p":"对。凌晨 1 点到 4 点不能开车。"},"vi":{"q":"Ở New Hampshire, người có bằng lái dành cho người trẻ (Youth Operator License) không được lái xe trong khoảng giờ nào?","o":["Từ nửa đêm đến 5 giờ sáng","Từ 1 giờ sáng đến 4 giờ sáng","Từ 11 giờ tối đến 5 giờ sáng","Từ 10 giờ tối đến 6 giờ sáng"],"h1":"Khoảng thời gian này chỉ dài ba tiếng.","h2":"Ở New Hampshire, người có bằng lái dành cho người trẻ không được lái xe từ 1 giờ sáng đến 4 giờ sáng.","p":"Đúng. Không lái xe từ 1 đến 4 giờ sáng."},"tl":{"q":"Sa New Hampshire, sa anong mga oras bawal magmaneho ang may hawak ng Youth Operator License?","o":["Hatinggabi hanggang alas-5 ng umaga","Ala-1 hanggang alas-4 ng madaling-araw","Alas-11 ng gabi hanggang alas-5 ng umaga","Alas-10 ng gabi hanggang alas-6 ng umaga"],"h1":"Tatlong oras lang ang haba nito.","h2":"Ang may hawak ng Youth Operator License sa New Hampshire ay bawal magmaneho mula ala-1 hanggang alas-4 ng madaling-araw.","p":"Tama. Bawal magmaneho mula ala-1 hanggang alas-4 ng madaling-araw."},"ar":{"q":"في New Hampshire، في أي ساعات لا يجوز لصاحب رخصة السائق الشاب (Youth Operator License) أن يقود؟","o":["من منتصف الليل إلى 5 صباحًا","من 1 صباحًا إلى 4 صباحًا","من 11 مساءً إلى 5 صباحًا","من 10 مساءً إلى 6 صباحًا"],"h1":"هذه الفترة طولها ثلاث ساعات فقط.","h2":"في New Hampshire لا يجوز لصاحب رخصة السائق الشاب أن يقود بين الساعة 1 صباحًا والساعة 4 صباحًا.","p":"صحيح. ممنوع القيادة من 1 إلى 4 صباحًا."},"ref":{"doc":"NH","page":4}},{"id":"nh-011","scope":"NH","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Hampshire, during the first six months of a Youth Operator License, how many non-family passengers under 25 may the driver carry?","o":["One","None","Two","Three"],"h1":"The limit is more than zero but very small.","h2":"During the first six months, a New Hampshire youth operator may carry no more than one passenger under 25 who is not a family member.","p":"Right. Only one."},"es":{"q":"En New Hampshire, durante los primeros seis meses de la licencia de conductor joven, ¿cuántos pasajeros menores de 25 años que no son familiares puede llevar el conductor?","o":["Uno","Ninguno","Dos","Tres"],"h1":"El límite es mayor que cero, pero muy pequeño.","h2":"Durante los primeros seis meses, un conductor joven en New Hampshire no puede llevar más de un pasajero menor de 25 años que no sea de su familia.","p":"Correcto. Solo uno."},"zh":{"q":"在 New Hampshire，持青少年驾照的前六个月，司机可以载多少位不是家人、25 岁以下的乘客？","o":["一位","一个都不行","两位","三位"],"h1":"这个限制大于零，但很小。","h2":"在前六个月，New Hampshire 持青少年驾照的司机最多只能载一位不是家人、25 岁以下的乘客。","p":"对。只能一位。"},"vi":{"q":"Ở New Hampshire, trong sáu tháng đầu có bằng lái dành cho người trẻ (Youth Operator License), người lái được chở bao nhiêu hành khách dưới 25 tuổi không phải người trong gia đình?","o":["Một người","Không người nào","Hai người","Ba người"],"h1":"Giới hạn này nhiều hơn số không nhưng rất nhỏ.","h2":"Trong sáu tháng đầu, người lái trẻ ở New Hampshire chỉ được chở tối đa một hành khách dưới 25 tuổi không phải người trong gia đình.","p":"Đúng. Chỉ một người."},"tl":{"q":"Sa New Hampshire, sa unang anim na buwan ng Youth Operator License, ilang pasaherong wala pang 25 na hindi kapamilya ang puwedeng isakay ng driver?","o":["Isa","Wala","Dalawa","Tatlo"],"h1":"Higit ito sa zero pero napakaliit.","h2":"Sa unang anim na buwan, ang batang driver sa New Hampshire ay puwedeng magsakay ng hindi hihigit sa isang pasaherong wala pang 25 na hindi kapamilya.","p":"Tama. Isa lang."},"ar":{"q":"في New Hampshire، في الأشهر الستة الأولى من رخصة السائق الشاب (Youth Operator License)، كم راكبًا عمره أقل من 25 سنة ومن خارج العائلة يمكن للسائق أن ينقل؟","o":["واحد","لا أحد","اثنان","ثلاثة"],"h1":"الحد أكثر من صفر لكنه صغير جدًا.","h2":"في الأشهر الستة الأولى، لا يجوز للسائق الشاب في New Hampshire أن ينقل أكثر من راكب واحد عمره أقل من 25 سنة وليس من أفراد العائلة.","p":"صحيح. واحد فقط."},"ref":{"doc":"NH","page":4}},{"id":"nh-012","scope":"NH","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Hampshire, when may a new youth operator carry more than one non-family passenger under 25 in the first six months?","o":["On weekends","On roads with a low speed limit","During daylight","When a licensed adult at least 25 years old is in the car"],"h1":"An experienced adult has to be with them.","h2":"In New Hampshire the one-passenger limit does not apply when a licensed responsible adult at least 25 years old rides along.","p":"Correct. A licensed adult 25 or older lifts the limit."},"es":{"q":"En New Hampshire, ¿cuándo puede un conductor joven nuevo llevar más de un pasajero menor de 25 años que no sea familiar en los primeros seis meses?","o":["Los fines de semana","En calles con límite de velocidad bajo","Durante el día","Cuando lo acompaña un adulto con licencia de por lo menos 25 años"],"h1":"Debe ir con un adulto con experiencia.","h2":"En New Hampshire el límite de un pasajero no se aplica cuando lo acompaña un adulto responsable con licencia de por lo menos 25 años.","p":"Correcto. Un adulto con licencia de 25 años o más quita el límite."},"zh":{"q":"在 New Hampshire，持青少年驾照的新司机在前六个月什么时候可以载超过一位不是家人、25 岁以下的乘客？","o":["周末","在限速低的路上","白天","车里有一位至少 25 岁、有驾照的成年人时"],"h1":"必须有一位有经验的成年人和他们一起。","h2":"在 New Hampshire，有一位至少 25 岁、有驾照、负责任的成年人同车时，只能载一位乘客的限制就不适用。","p":"对。有一位 25 岁或以上、有驾照的成年人同车，就取消这个限制。"},"vi":{"q":"Ở New Hampshire, trong sáu tháng đầu, khi nào người lái trẻ mới được chở hơn một hành khách dưới 25 tuổi không phải người trong gia đình?","o":["Vào cuối tuần","Trên đường có tốc độ giới hạn thấp","Vào ban ngày","Khi có một người lớn có bằng lái, ít nhất 25 tuổi, ở trong xe"],"h1":"Phải có một người lớn có kinh nghiệm đi cùng.","h2":"Ở New Hampshire, giới hạn một hành khách không áp dụng khi có một người lớn có trách nhiệm, có bằng lái, ít nhất 25 tuổi, đi cùng trong xe.","p":"Đúng. Một người lớn có bằng lái từ 25 tuổi trở lên sẽ bỏ giới hạn này."},"tl":{"q":"Sa New Hampshire, kailan puwedeng magsakay ang bagong batang driver ng higit sa isang pasaherong wala pang 25 na hindi kapamilya sa unang anim na buwan?","o":["Tuwing weekend","Sa mga kalsadang mababa ang speed limit","Sa araw","Kapag may adult na may lisensya na hindi bababa sa 25 taong gulang sa sasakyan"],"h1":"Kailangang may kasamang adult na may karanasan.","h2":"Sa New Hampshire, hindi umiiral ang limitasyong isang pasahero kapag may kasamang responsableng adult na may lisensya na hindi bababa sa 25 taong gulang.","p":"Tama. Inaalis ng adult na may lisensya na 25 o higit pa ang limitasyon."},"ar":{"q":"في New Hampshire، متى يمكن للسائق الشاب الجديد أن ينقل أكثر من راكب واحد عمره أقل من 25 سنة ومن خارج العائلة في الأشهر الستة الأولى؟","o":["في عطلة نهاية الأسبوع","في الطرق ذات حد السرعة المنخفض","في النهار","عندما يكون في السيارة شخص بالغ يحمل رخصة وعمره 25 سنة على الأقل"],"h1":"يجب أن يكون معه شخص بالغ له خبرة.","h2":"في New Hampshire لا ينطبق حد الراكب الواحد عندما يرافق السائقَ شخصٌ بالغ مسؤول يحمل رخصة وعمره 25 سنة على الأقل.","p":"صحيح. وجود بالغ يحمل رخصة وعمره 25 سنة أو أكثر يرفع الحد."},"ref":{"doc":"NH","page":4}},{"id":"nh-013","scope":"NH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Hampshire, how many people may ride with a youth operator?","o":["Any number","No more than four","No more than there are seat belts","Only one"],"h1":"Every person needs a place to buckle up.","h2":"A New Hampshire youth operator may not carry more people than the vehicle has seat belts.","p":"Right. One seat belt for each person."},"es":{"q":"En New Hampshire, ¿cuántas personas pueden ir con un conductor joven?","o":["Cualquier número","No más de cuatro","No más que el número de cinturones de seguridad","Solo una"],"h1":"Cada persona necesita un lugar donde abrocharse.","h2":"Un conductor joven en New Hampshire no puede llevar más personas que el número de cinturones de seguridad del vehículo.","p":"Correcto. Un cinturón para cada persona."},"zh":{"q":"在 New Hampshire，持青少年驾照的司机可以载多少人？","o":["多少人都可以","最多四个人","不能超过安全带的数量","只能一个人"],"h1":"每个人都需要一个系安全带的位置。","h2":"New Hampshire 持青少年驾照的司机载的人不能比车里的安全带多。","p":"对。每个人一条安全带。"},"vi":{"q":"Ở New Hampshire, bao nhiêu người được đi cùng xe với người lái trẻ?","o":["Bao nhiêu cũng được","Không quá bốn người","Không nhiều hơn số dây an toàn trong xe","Chỉ một người"],"h1":"Mỗi người cần một chỗ để thắt dây an toàn.","h2":"Người lái trẻ ở New Hampshire không được chở nhiều người hơn số dây an toàn có trong xe.","p":"Đúng. Mỗi người một dây an toàn."},"tl":{"q":"Sa New Hampshire, ilang tao ang puwedeng sumakay kasama ng batang driver?","o":["Kahit ilan","Hindi hihigit sa apat","Hindi hihigit sa bilang ng seat belt","Isa lang"],"h1":"Bawat tao ay kailangan ng lugar para mag-seat belt.","h2":"Ang batang driver sa New Hampshire ay hindi puwedeng magsakay ng mas maraming tao kaysa sa bilang ng seat belt ng sasakyan.","p":"Tama. Isang seat belt sa bawat tao."},"ar":{"q":"في New Hampshire، كم شخصًا يمكن أن يركب مع السائق الشاب؟","o":["أي عدد","لا يزيد عن أربعة","لا يزيد عن عدد أحزمة الأمان","واحد فقط"],"h1":"كل شخص يحتاج إلى مكان يربط فيه حزام الأمان.","h2":"لا يجوز للسائق الشاب في New Hampshire أن ينقل أشخاصًا أكثر من عدد أحزمة الأمان في السيارة.","p":"صحيح. حزام أمان واحد لكل شخص."},"ref":{"doc":"NH","page":4}},{"id":"nh-014","scope":"NH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Hampshire, may a driver under 18 talk on a phone using a hands-free device?","o":["Yes, any time","No, only to report an emergency","Yes, but only at a red light","Yes, if the call is short"],"h1":"Younger drivers have a stricter rule than adults.","h2":"In New Hampshire a driver under 18 may not use a phone or other mobile device at all while driving, even hands-free, except to report an emergency.","p":"Correct. Under 18, no phone except emergencies."},"es":{"q":"En New Hampshire, ¿puede un conductor menor de 18 años hablar por teléfono con un dispositivo de manos libres?","o":["Sí, en cualquier momento","No, solo para reportar una emergencia","Sí, pero solo en un semáforo en rojo","Sí, si la llamada es corta"],"h1":"Los conductores más jóvenes tienen una regla más estricta que los adultos.","h2":"En New Hampshire un conductor menor de 18 años no puede usar un teléfono ni otro dispositivo móvil mientras maneja, ni siquiera con manos libres, excepto para reportar una emergencia.","p":"Correcto. Menor de 18, nada de teléfono salvo emergencias."},"zh":{"q":"在 New Hampshire，18 岁以下的司机可以用免提设备打电话吗？","o":["可以，任何时候","不可以，只能报告紧急情况","可以，但只在红灯时","可以，如果电话很短"],"h1":"年轻司机的规定比成年人更严格。","h2":"在 New Hampshire，18 岁以下的司机开车时完全不能用手机或其他移动设备，免提也不行，只有报告紧急情况例外。","p":"对。18 岁以下，除了紧急情况，不能用手机。"},"vi":{"q":"Ở New Hampshire, người lái xe dưới 18 tuổi có được nói điện thoại bằng thiết bị rảnh tay (hands-free) không?","o":["Có, bất cứ lúc nào","Không, chỉ được gọi để báo trường hợp khẩn cấp","Có, nhưng chỉ khi dừng đèn đỏ","Có, nếu cuộc gọi ngắn"],"h1":"Người lái trẻ có luật nghiêm hơn người lớn.","h2":"Ở New Hampshire, người lái xe dưới 18 tuổi hoàn toàn không được dùng điện thoại hay thiết bị di động khác khi lái xe, kể cả rảnh tay, trừ khi để báo trường hợp khẩn cấp.","p":"Đúng. Dưới 18 tuổi, không dùng điện thoại trừ khi khẩn cấp."},"tl":{"q":"Sa New Hampshire, puwede bang makipag-usap sa telepono gamit ang hands-free device ang driver na wala pang 18?","o":["Oo, kahit kailan","Hindi, puwede lang para mag-report ng emergency","Oo, pero sa red light lang","Oo, kung maikli ang tawag"],"h1":"Mas mahigpit ang patakaran para sa mas batang driver kaysa sa mga adult.","h2":"Sa New Hampshire, ang driver na wala pang 18 ay bawal gumamit ng telepono o ibang mobile device habang nagmamaneho, kahit hands-free, maliban para mag-report ng emergency.","p":"Tama. Kung wala pang 18, walang telepono maliban sa emergency."},"ar":{"q":"في New Hampshire، هل يجوز للسائق الذي عمره أقل من 18 سنة أن يتكلّم في الهاتف باستخدام جهاز من غير استعمال اليدين (hands-free)؟","o":["نعم، في أي وقت","لا، إلا للإبلاغ عن حالة طوارئ","نعم، لكن عند الإشارة الحمراء فقط","نعم، إذا كانت المكالمة قصيرة"],"h1":"للسائقين الأصغر سنًا قاعدة أشد من قاعدة البالغين.","h2":"في New Hampshire لا يجوز للسائق الذي عمره أقل من 18 سنة أن يستخدم الهاتف أو أي جهاز محمول آخر أبدًا أثناء القيادة، حتى من غير استعمال اليدين، إلا للإبلاغ عن حالة طوارئ.","p":"صحيح. أقل من 18 سنة: لا هاتف إلا في الطوارئ."},"ref":{"doc":"NH","page":4}},{"id":"nh-015","scope":"NH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Hampshire, how may an adult driver make a phone call while driving?","o":["With a Bluetooth or other hands-free device","Holding the phone to the ear","Holding the phone while stopped in traffic","Typing the number on the screen in the hand"],"h1":"The law bans hand-held use, even when stopped in traffic.","h2":"New Hampshire bans hand-held phone use while driving, even when stopped in traffic, but an adult may use a Bluetooth or other hands-free device.","p":"Right. Hands-free only."},"es":{"q":"En New Hampshire, ¿cómo puede un conductor adulto hacer una llamada mientras maneja?","o":["Con un dispositivo Bluetooth u otro de manos libres","Sosteniendo el teléfono junto al oído","Sosteniendo el teléfono cuando está detenido en el tráfico","Marcando el número en la pantalla con el teléfono en la mano"],"h1":"La ley prohíbe usar el teléfono en la mano, aun detenido en el tráfico.","h2":"New Hampshire prohíbe usar el teléfono en la mano mientras se maneja, aun detenido en el tráfico, pero un adulto puede usar un dispositivo Bluetooth u otro de manos libres.","p":"Correcto. Solo manos libres."},"zh":{"q":"在 New Hampshire，成年司机开车时可以怎样打电话？","o":["用蓝牙或其他免提设备","把手机拿到耳边","在车流中停着时拿着手机","手拿着手机在屏幕上按号码"],"h1":"法律禁止手拿使用，即使在车流中停着也不行。","h2":"New Hampshire 禁止开车时手拿手机使用，即使在车流中停着也不行，但成年人可以用蓝牙或其他免提设备。","p":"对。只能免提。"},"vi":{"q":"Ở New Hampshire, người lái xe là người lớn có thể gọi điện thoại khi lái xe bằng cách nào?","o":["Bằng Bluetooth hoặc thiết bị rảnh tay (hands-free) khác","Cầm điện thoại áp vào tai","Cầm điện thoại khi đang dừng vì kẹt xe","Bấm số trên màn hình điện thoại cầm trong tay"],"h1":"Luật cấm cầm điện thoại trên tay, kể cả khi đang dừng vì kẹt xe.","h2":"New Hampshire cấm cầm điện thoại trên tay khi lái xe, kể cả khi đang dừng vì kẹt xe, nhưng người lớn có thể dùng Bluetooth hoặc thiết bị rảnh tay khác.","p":"Đúng. Chỉ dùng rảnh tay."},"tl":{"q":"Sa New Hampshire, paano puwedeng tumawag ang adult na driver habang nagmamaneho?","o":["Gamit ang Bluetooth o ibang hands-free device","Hawak ang telepono sa tainga","Hawak ang telepono habang nakahinto sa trapiko","Pinipindot ang numero sa screen ng teleponong hawak"],"h1":"Bawal ng batas ang paghawak ng telepono, kahit nakahinto sa trapiko.","h2":"Bawal sa New Hampshire ang paghawak ng telepono habang nagmamaneho, kahit nakahinto sa trapiko, pero puwedeng gumamit ang adult ng Bluetooth o ibang hands-free device.","p":"Tama. Hands-free lang."},"ar":{"q":"في New Hampshire، كيف يمكن للسائق البالغ أن يجري مكالمة هاتفية أثناء القيادة؟","o":["باستخدام Bluetooth أو جهاز آخر من غير استعمال اليدين (hands-free)","بإمساك الهاتف على الأذن","بإمساك الهاتف أثناء التوقّف في زحمة السير","بكتابة الرقم على شاشة الهاتف وهو في اليد"],"h1":"القانون يمنع إمساك الهاتف باليد، حتى أثناء التوقّف في زحمة السير.","h2":"تمنع New Hampshire إمساك الهاتف باليد أثناء القيادة، حتى أثناء التوقّف في زحمة السير، لكن يمكن للبالغ أن يستخدم Bluetooth أو جهازًا آخر من غير استعمال اليدين.","p":"صحيح. من غير استعمال اليدين فقط."},"ref":{"doc":"NH","page":7}},{"id":"nh-017","scope":"NH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Hampshire, which drivers must wear a seat belt by law?","o":["Only drivers on the highway","Only drivers over 65","Drivers under 18","Only taxi drivers"],"h1":"The rule is about young drivers.","h2":"New Hampshire law says a person under 18 may not drive unless wearing a properly fastened seat belt.","p":"Right. Drivers under 18 must buckle up."},"es":{"q":"En New Hampshire, ¿qué conductores deben usar cinturón de seguridad por ley?","o":["Solo los que manejan en la autopista","Solo los mayores de 65","Los conductores menores de 18 años","Solo los taxistas"],"h1":"La regla se refiere a los conductores jóvenes.","h2":"La ley de New Hampshire dice que una persona menor de 18 años no puede manejar sin el cinturón de seguridad bien abrochado.","p":"Correcto. Los menores de 18 deben abrocharse."},"zh":{"q":"在 New Hampshire，法律规定哪些司机必须系安全带？","o":["只有在公路上的司机","只有 65 岁以上的司机","18 岁以下的司机","只有出租车司机"],"h1":"这条规定和年轻司机有关。","h2":"New Hampshire 法律规定，18 岁以下的人必须正确系好安全带才能开车。","p":"对。18 岁以下的司机必须系好安全带。"},"vi":{"q":"Ở New Hampshire, theo luật, những người lái xe nào phải thắt dây an toàn?","o":["Chỉ người lái xe trên xa lộ","Chỉ người lái xe trên 65 tuổi","Người lái xe dưới 18 tuổi","Chỉ tài xế taxi"],"h1":"Luật này nói về người lái xe trẻ.","h2":"Luật New Hampshire nói rằng người dưới 18 tuổi không được lái xe nếu không thắt dây an toàn đúng cách.","p":"Đúng. Người lái xe dưới 18 tuổi phải thắt dây an toàn."},"tl":{"q":"Sa New Hampshire, aling mga driver ang dapat mag-seat belt ayon sa batas?","o":["Mga driver lang sa highway","Mga driver lang na higit sa 65","Mga driver na wala pang 18","Mga taxi driver lang"],"h1":"Tungkol sa mga batang driver ang patakaran.","h2":"Sinasabi ng batas ng New Hampshire na ang taong wala pang 18 ay bawal magmaneho kung hindi siya nakasuot ng seat belt nang tama.","p":"Tama. Dapat mag-seat belt ang mga driver na wala pang 18."},"ar":{"q":"في New Hampshire، أي السائقين يجب عليهم بحكم القانون أن يربطوا حزام الأمان؟","o":["السائقون على الطريق السريع فقط","السائقون الذين تزيد أعمارهم عن 65 سنة فقط","السائقون الذين أعمارهم أقل من 18 سنة","سائقو سيارات الأجرة فقط"],"h1":"القاعدة تخص السائقين الصغار.","h2":"قانون New Hampshire يقول إن الشخص الذي عمره أقل من 18 سنة لا يجوز له أن يقود إلا وهو رابط حزام الأمان بشكل صحيح.","p":"صحيح. السائقون الذين أعمارهم أقل من 18 سنة يجب أن يربطوا الحزام."},"ref":{"doc":"NH","page":11}},{"id":"nh-018","scope":"NH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Hampshire, which passengers must the driver make sure are wearing a seat belt?","o":["Only the front-seat passenger","Every passenger under 18","Only passengers over 65","No one but the driver"],"h1":"The driver is responsible for young passengers.","h2":"In New Hampshire a driver may not carry a passenger under 18 who is not wearing a properly fastened seat belt.","p":"Correct. Every passenger under 18."},"es":{"q":"En New Hampshire, ¿qué pasajeros debe asegurarse el conductor de que usen cinturón de seguridad?","o":["Solo el pasajero del asiento delantero","Todo pasajero menor de 18 años","Solo los pasajeros mayores de 65","Nadie más que el conductor"],"h1":"El conductor es responsable de los pasajeros jóvenes.","h2":"En New Hampshire un conductor no puede llevar a un pasajero menor de 18 años que no tenga el cinturón de seguridad bien abrochado.","p":"Correcto. Todo pasajero menor de 18."},"zh":{"q":"在 New Hampshire，司机必须确认哪些乘客系好了安全带？","o":["只有前排乘客","每位 18 岁以下的乘客","只有 65 岁以上的乘客","除了司机，谁都不用"],"h1":"司机要为年轻乘客负责。","h2":"在 New Hampshire，司机不能载没有正确系好安全带的 18 岁以下乘客。","p":"对。每位 18 岁以下的乘客。"},"vi":{"q":"Ở New Hampshire, người lái xe phải bảo đảm những hành khách nào thắt dây an toàn?","o":["Chỉ hành khách ngồi ghế trước","Mọi hành khách dưới 18 tuổi","Chỉ hành khách trên 65 tuổi","Không ai ngoài người lái xe"],"h1":"Người lái xe chịu trách nhiệm cho hành khách trẻ.","h2":"Ở New Hampshire, người lái xe không được chở hành khách dưới 18 tuổi nếu người đó không thắt dây an toàn đúng cách.","p":"Đúng. Mọi hành khách dưới 18 tuổi."},"tl":{"q":"Sa New Hampshire, aling mga pasahero ang dapat tiyakin ng driver na naka-seat belt?","o":["Ang pasahero lang sa upuan sa harap","Bawat pasaherong wala pang 18","Mga pasahero lang na higit sa 65","Wala, ang driver lang"],"h1":"Responsable ang driver sa mga batang pasahero.","h2":"Sa New Hampshire, bawal magsakay ang driver ng pasaherong wala pang 18 na hindi nakasuot ng seat belt nang tama.","p":"Tama. Bawat pasaherong wala pang 18."},"ar":{"q":"في New Hampshire، أي الركاب يجب على السائق أن يتأكد أنهم يربطون حزام الأمان؟","o":["راكب المقعد الأمامي فقط","كل راكب عمره أقل من 18 سنة","الركاب الذين تزيد أعمارهم عن 65 سنة فقط","لا أحد غير السائق"],"h1":"السائق مسؤول عن الركاب الصغار.","h2":"في New Hampshire لا يجوز للسائق أن ينقل راكبًا عمره أقل من 18 سنة إذا لم يكن رابطًا حزام الأمان بشكل صحيح.","p":"صحيح. كل راكب عمره أقل من 18 سنة."},"ref":{"doc":"NH","page":11}},{"id":"nh-019","scope":"NH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Hampshire, at what blood alcohol level is a driver under 21 legally intoxicated?","o":["0.02 or more","0.05 or more","0.08 or more","0.10 or more"],"h1":"It is much lower than the adult limit of 0.08.","h2":"In New Hampshire a driver under 21 is legally intoxicated at a blood alcohol level of 0.02 or more.","p":"Right. The limit under 21 is 0.02."},"es":{"q":"En New Hampshire, ¿con qué nivel de alcohol en la sangre se considera legalmente intoxicado a un conductor menor de 21 años?","o":["0.02 o más","0.05 o más","0.08 o más","0.10 o más"],"h1":"Es mucho más bajo que el límite para adultos, que es 0.08.","h2":"En New Hampshire un conductor menor de 21 años está legalmente intoxicado con un nivel de alcohol en la sangre de 0.02 o más.","p":"Correcto. El límite para menores de 21 es 0.02."},"zh":{"q":"在 New Hampshire，21 岁以下的司机血液酒精浓度达到多少，在法律上就算醉酒？","o":["0.02 或更高","0.05 或更高","0.08 或更高","0.10 或更高"],"h1":"它比成年人 0.08 的限值低很多。","h2":"在 New Hampshire，21 岁以下的司机血液酒精浓度达到 0.02 或更高，在法律上就算醉酒。","p":"对。21 岁以下的限值是 0.02。"},"vi":{"q":"Ở New Hampshire, người lái xe dưới 21 tuổi bị coi là say rượu theo luật khi nồng độ cồn trong máu là bao nhiêu?","o":["0.02 trở lên","0.05 trở lên","0.08 trở lên","0.10 trở lên"],"h1":"Mức này thấp hơn nhiều so với giới hạn 0.08 cho người lớn.","h2":"Ở New Hampshire, người lái xe dưới 21 tuổi bị coi là say rượu theo luật khi nồng độ cồn trong máu từ 0.02 trở lên.","p":"Đúng. Giới hạn cho người dưới 21 tuổi là 0.02."},"tl":{"q":"Sa New Hampshire, sa anong blood alcohol level itinuturing na legal na lasing ang driver na wala pang 21?","o":["0.02 o higit pa","0.05 o higit pa","0.08 o higit pa","0.10 o higit pa"],"h1":"Mas mababa ito nang malaki sa limitasyon ng adult na 0.08.","h2":"Sa New Hampshire, ang driver na wala pang 21 ay legal na lasing kapag ang blood alcohol level niya ay 0.02 o higit pa.","p":"Tama. 0.02 ang limitasyon kung wala pang 21."},"ar":{"q":"في New Hampshire، عند أي نسبة كحول في الدم يُعتبر السائق الذي عمره أقل من 21 سنة سكرانًا قانونيًا؟","o":["0.02 أو أكثر","0.05 أو أكثر","0.08 أو أكثر","0.10 أو أكثر"],"h1":"هذه النسبة أقل بكثير من حد البالغين وهو 0.08.","h2":"في New Hampshire يُعتبر السائق الذي عمره أقل من 21 سنة سكرانًا قانونيًا عندما تكون نسبة الكحول في دمه 0.02 أو أكثر.","p":"صحيح. الحد لمن عمره أقل من 21 سنة هو 0.02."},"ref":{"doc":"NH","page":6}},{"id":"nh-020","scope":"NH","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Hampshire, when does the Move Over law ask you to slow down and give extra space?","o":["Only for police cars with sirens","Only on interstate highways","Only at night","For a stopped vehicle showing flashing blue, red or amber lights, such as police, fire, tow or road crews"],"h1":"Think of the flashing lights on emergency and work vehicles.","h2":"New Hampshire's Move Over law asks drivers to slow down and move over, when safe, for a stopped vehicle showing flashing blue, red or amber lights, such as police, fire, tow or road crews.","p":"Correct. Stopped vehicles with flashing blue, red or amber lights."},"es":{"q":"En New Hampshire, ¿cuándo le pide la ley Move Over que reduzca la velocidad y deje más espacio?","o":["Solo con carros de policía con sirena","Solo en las autopistas interestatales","Solo de noche","Con un vehículo detenido con luces intermitentes azules, rojas o ámbar, como policía, bomberos, grúas o equipos de carretera"],"h1":"Piense en las luces intermitentes de los vehículos de emergencia y de trabajo.","h2":"La ley Move Over de New Hampshire pide a los conductores reducir la velocidad y cambiarse de carril, cuando sea seguro, ante un vehículo detenido con luces intermitentes azules, rojas o ámbar, como policía, bomberos, grúas o equipos de carretera.","p":"Correcto. Vehículos detenidos con luces intermitentes azules, rojas o ámbar."},"zh":{"q":"在 New Hampshire，让道法（Move Over law）什么时候要求你减速并留出更多空间？","o":["只对拉着警笛的警车","只在州际公路上","只在晚上","对闪着蓝色、红色或黄色灯的停着的车辆，例如警察、消防、拖车或道路工作人员的车"],"h1":"想一想紧急车辆和工作车辆上闪烁的灯。","h2":"New Hampshire 的让道法要求司机在安全时，对闪着蓝色、红色或黄色灯的停着的车辆减速并让开，例如警察、消防、拖车或道路工作人员的车。","p":"对。闪着蓝色、红色或黄色灯的停着的车辆。"},"vi":{"q":"Ở New Hampshire, khi nào luật nhường làn (Move Over law) yêu cầu bạn chạy chậm lại và chừa thêm khoảng trống?","o":["Chỉ với xe cảnh sát đang hú còi","Chỉ trên xa lộ liên bang","Chỉ vào ban đêm","Với xe đang dừng có đèn chớp màu xanh dương, đỏ hoặc vàng hổ phách, như xe cảnh sát, cứu hỏa, xe kéo hoặc đội làm đường"],"h1":"Hãy nghĩ đến đèn chớp trên xe cấp cứu và xe công tác.","h2":"Luật nhường làn của New Hampshire yêu cầu tài xế chạy chậm lại và tránh sang làn khác, khi an toàn, với xe đang dừng có đèn chớp màu xanh dương, đỏ hoặc vàng hổ phách, như xe cảnh sát, cứu hỏa, xe kéo hoặc đội làm đường.","p":"Đúng. Xe đang dừng có đèn chớp màu xanh dương, đỏ hoặc vàng hổ phách."},"tl":{"q":"Sa New Hampshire, kailan ka pinababagal at pinabibigay ng dagdag na espasyo ng Move Over law?","o":["Para lang sa mga police car na may sirena","Sa mga interstate highway lang","Sa gabi lang","Para sa nakahintong sasakyan na may kumikislap na asul, pula o amber na ilaw, gaya ng pulis, bumbero, tow truck o road crew"],"h1":"Isipin ang mga kumikislap na ilaw sa mga emergency at work vehicle.","h2":"Hinihiling ng Move Over law ng New Hampshire na magbagal ang mga driver at lumipat ng lane, kapag ligtas, para sa nakahintong sasakyan na may kumikislap na asul, pula o amber na ilaw, gaya ng pulis, bumbero, tow truck o road crew.","p":"Tama. Mga nakahintong sasakyan na may kumikislap na asul, pula o amber na ilaw."},"ar":{"q":"في New Hampshire، متى يطلب منك قانون الابتعاد (Move Over law) أن تخفف السرعة وتترك مسافة إضافية؟","o":["فقط لسيارات الشرطة التي تشغّل صفارات الإنذار","فقط على الطرق السريعة بين الولايات","فقط في الليل","لمركبة متوقفة تُظهر أضواء وامضة زرقاء أو حمراء أو كهرمانية، مثل الشرطة أو الإطفاء أو سيارات السحب أو فرق الطرق"],"h1":"فكّر في الأضواء الوامضة على مركبات الطوارئ ومركبات العمل.","h2":"يطلب قانون الابتعاد في New Hampshire من السائقين أن يخففوا السرعة ويبتعدوا إلى مسار آخر، عندما يكون ذلك آمنًا، لمركبة متوقفة تُظهر أضواء وامضة زرقاء أو حمراء أو كهرمانية، مثل الشرطة أو الإطفاء أو سيارات السحب أو فرق الطرق.","p":"صحيح. المركبات المتوقفة التي تُظهر أضواء وامضة زرقاء أو حمراء أو كهرمانية."},"ref":{"doc":"NH","page":40}},{"id":"nh-021","scope":"NH","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Hampshire, how fast may you drive in a posted school zone while the school limit is in effect?","o":["5 mph below the usual posted limit","15 mph, whatever the usual limit is","10 mph below the usual posted limit","20 mph below the usual posted limit"],"h1":"The school limit is found by taking a set number off the usual limit.","h2":"In a posted New Hampshire school zone, the limit is 10 mph below the usual posted limit while the school limit is in effect.","p":"Right. Drive 10 mph under the usual limit."},"es":{"q":"En New Hampshire, ¿a qué velocidad puede manejar en una zona escolar señalizada mientras rige el límite escolar?","o":["5 mph menos que el límite habitual","15 mph, sea cual sea el límite habitual","10 mph menos que el límite habitual","20 mph menos que el límite habitual"],"h1":"El límite escolar se obtiene restando un número fijo al límite habitual.","h2":"En una zona escolar señalizada de New Hampshire, el límite es 10 mph menos que el límite habitual mientras rige el límite escolar.","p":"Correcto. Maneje 10 mph por debajo del límite habitual."},"ref":{"doc":"NH","page":null}},{"id":"nh-022","scope":"NH","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Hampshire, when does the lower speed limit in a posted school zone apply?","o":["From 45 minutes before school opens until it opens, and from closing until 45 minutes after","All day, every day of the year","Only when children are on the sidewalk","From 7 a.m. to 5 p.m. on weekdays"],"h1":"It is tied to the times the school opens and closes.","h2":"In New Hampshire, the school zone limit applies from 45 minutes before school opens until it opens, and from the time school closes until 45 minutes later.","p":"Right. 45 minutes before opening and 45 minutes after closing."},"es":{"q":"En New Hampshire, ¿cuándo rige el límite de velocidad más bajo en una zona escolar señalizada?","o":["Desde 45 minutos antes de que abra la escuela hasta que abre, y desde el cierre hasta 45 minutos después","Todo el día, todos los días del año","Solo cuando hay niños en la acera","De 7 a.m. a 5 p.m. los días entre semana"],"h1":"Depende de la hora en que la escuela abre y cierra.","h2":"En New Hampshire, el límite de la zona escolar rige desde 45 minutos antes de que abra la escuela hasta que abre, y desde que cierra hasta 45 minutos después.","p":"Correcto. 45 minutos antes de abrir y 45 minutos después de cerrar."},"ref":{"doc":"NH","page":null}},{"id":"nh-023","scope":"NH","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Hampshire, what is the speed limit in a business district or a city residential area when no sign says otherwise?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"It is the lowest of the everyday limits set by state law.","h2":"In New Hampshire, the speed limit in a business or urban residence district is 30 mph unless a sign says otherwise.","p":"Right. 30 mph in business and city residential areas."},"es":{"q":"En New Hampshire, ¿cuál es el límite de velocidad en una zona comercial o un barrio residencial de ciudad cuando ninguna señal indica otra cosa?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Es el más bajo de los límites comunes que fija la ley estatal.","h2":"En New Hampshire, el límite de velocidad en una zona comercial o un barrio residencial urbano es de 30 mph, salvo que una señal indique otra cosa.","p":"Correcto. 30 mph en zonas comerciales y barrios de ciudad."},"ref":{"doc":"NH","page":null}},{"id":"nh-024","scope":"NH","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Hampshire, what is the speed limit in a rural residential area when no sign says otherwise?","o":["25 mph","30 mph","45 mph","35 mph"],"h1":"It is a little higher than the limit in a town business area.","h2":"In New Hampshire, the speed limit in a rural residence district is 35 mph unless a sign says otherwise.","p":"Right. 35 mph in rural residential areas."},"es":{"q":"En New Hampshire, ¿cuál es el límite de velocidad en una zona residencial rural cuando ninguna señal indica otra cosa?","o":["25 mph","30 mph","45 mph","35 mph"],"h1":"Es un poco más alto que el límite en una zona comercial de un pueblo.","h2":"En New Hampshire, el límite de velocidad en una zona residencial rural es de 35 mph, salvo que una señal indique otra cosa.","p":"Correcto. 35 mph en zonas residenciales rurales."},"ref":{"doc":"NH","page":null}},{"id":"nh-025","scope":"NH","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Hampshire, you are on a paved highway outside business and residential areas. It is not an interstate, and no sign shows the limit. What is the speed limit?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"It is 10 mph less than the usual limit on a four-lane interstate.","h2":"In New Hampshire, the speed limit on such a highway is 55 mph when no sign says otherwise.","p":"Right. The limit there is 55 mph."},"es":{"q":"En New Hampshire, usted va por una carretera pavimentada fuera de zonas comerciales y residenciales. No es una interestatal y ninguna señal indica el límite. ¿Cuál es el límite de velocidad?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"Es 10 mph menos que el límite habitual en una interestatal de cuatro carriles.","h2":"En New Hampshire, el límite de velocidad en esa carretera es de 55 mph cuando ninguna señal indica otra cosa.","p":"Correcto. Allí el límite es de 55 mph."},"ref":{"doc":"NH","page":null}},{"id":"nh-026","scope":"NH","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Hampshire, where is the speed limit set at 70 mph by state law?","o":["On every interstate highway","On part of I-93, from mile marker 45 to the Vermont border","On I-95 along the seacoast","Nowhere; the top limit is 65 mph"],"h1":"It is one stretch of a single interstate, heading north and west.","h2":"In New Hampshire, the speed limit is 70 mph on part of I-93, from mile marker 45 to the Vermont border.","p":"Right. 70 mph on I-93 from mile marker 45 to Vermont."},"es":{"q":"En New Hampshire, ¿dónde fija la ley estatal un límite de velocidad de 70 mph?","o":["En todas las carreteras interestatales","En parte de la I-93, desde la milla 45 hasta la frontera con Vermont","En la I-95 a lo largo de la costa","En ningún lugar; el límite máximo es de 65 mph"],"h1":"Es un tramo de una sola interestatal, hacia el norte y el oeste.","h2":"En New Hampshire, el límite de velocidad es de 70 mph en parte de la I-93, desde la milla 45 hasta la frontera con Vermont.","p":"Correcto. 70 mph en la I-93 desde la milla 45 hasta Vermont."},"ref":{"doc":"NH","page":null}},{"id":"nh-027","scope":"NH","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Hampshire, road workers are working on or right next to the road. How fast may you drive past them?","o":["The usual posted limit","5 mph below the usual limit","25 mph, on any road","At least 10 mph below the usual limit"],"h1":"You must take off a set number, and you may slow down even more.","h2":"In New Hampshire, when workers are on or close to the road, you must drive at least 10 mph below the usual posted limit.","p":"Right. At least 10 mph under the usual limit."},"es":{"q":"En New Hampshire, hay trabajadores en la vía o justo al lado. ¿A qué velocidad puede pasar junto a ellos?","o":["Al límite habitual señalizado","5 mph menos que el límite habitual","25 mph, en cualquier vía","Al menos 10 mph menos que el límite habitual"],"h1":"Debe restar un número fijo, y puede ir aún más despacio.","h2":"En New Hampshire, cuando hay trabajadores en la vía o muy cerca, debe manejar al menos 10 mph por debajo del límite habitual señalizado.","p":"Correcto. Al menos 10 mph menos que el límite habitual."},"ref":{"doc":"NH","page":null}},{"id":"nh-028","scope":"NH","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Hampshire, your car has a toll transponder, such as E-ZPass. How fast may you go through a toll booth with a transponder reader that is not an open road tolling lane?","o":["25 mph","15 mph","35 mph","45 mph"],"h1":"It is a little slower than the limit in a town business area.","h2":"In New Hampshire, a car with a transponder may go no faster than 25 mph through a toll booth with a transponder reader, unless it is an open road tolling lane.","p":"Right. 25 mph through the toll booth."},"es":{"q":"En New Hampshire, su carro tiene un transpondedor de peaje, como E-ZPass. ¿A qué velocidad puede pasar por una caseta de peaje con lector de transpondedor que no es un carril de peaje abierto (open road tolling)?","o":["25 mph","15 mph","35 mph","45 mph"],"h1":"Es un poco más lento que el límite en una zona comercial de un pueblo.","h2":"En New Hampshire, un carro con transpondedor no puede pasar a más de 25 mph por una caseta de peaje con lector de transpondedor, salvo en un carril de peaje abierto.","p":"Correcto. 25 mph por la caseta de peaje."},"ref":{"doc":"NH","page":null}},{"id":"nh-029","scope":"NH","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Hampshire, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 15 feet","No closer than 25 feet"],"h1":"It is about the length of one car.","h2":"In New Hampshire, you may not park within 15 feet of a fire hydrant.","p":"Right. Stay 15 feet from a hydrant."},"es":{"q":"En New Hampshire, ¿a qué distancia de un hidrante puede estacionarse?","o":["No a menos de 5 pies","No a menos de 10 pies","No a menos de 15 pies","No a menos de 25 pies"],"h1":"Es más o menos el largo de un carro.","h2":"En New Hampshire, no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese a 15 pies del hidrante."},"ref":{"doc":"NH","page":null}},{"id":"nh-030","scope":"NH","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Hampshire, how close to a crosswalk at an intersection may you park?","o":["No closer than 10 feet","No closer than 20 feet","No closer than 30 feet","No closer than 50 feet"],"h1":"It is more than the space you leave at a fire hydrant.","h2":"In New Hampshire, you may not park within 20 feet of a crosswalk at an intersection.","p":"Right. Stay 20 feet from the crosswalk."},"es":{"q":"En New Hampshire, ¿a qué distancia de un cruce peatonal en una intersección puede estacionarse?","o":["No a menos de 10 pies","No a menos de 20 pies","No a menos de 30 pies","No a menos de 50 pies"],"h1":"Es más que el espacio que deja junto a un hidrante.","h2":"En New Hampshire, no puede estacionarse a menos de 20 pies de un cruce peatonal en una intersección.","p":"Correcto. Quédese a 20 pies del cruce peatonal."},"ref":{"doc":"NH","page":null}},{"id":"nh-031","scope":"NH","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Hampshire, you are coming up to a stop sign, a flashing signal or a traffic light at the side of the road. How close to it may you park?","o":["No closer than 10 feet","No closer than 15 feet","No closer than 20 feet","No closer than 30 feet"],"h1":"Drivers need room to see the sign or light, so the gap is longer than at a crosswalk.","h2":"In New Hampshire, you may not park within 30 feet before a stop sign, flashing signal or traffic light at the side of the road.","p":"Right. Stay 30 feet back."},"es":{"q":"En New Hampshire, usted se acerca a una señal de alto, una luz intermitente o un semáforo al lado de la vía. ¿A qué distancia puede estacionarse?","o":["No a menos de 10 pies","No a menos de 15 pies","No a menos de 20 pies","No a menos de 30 pies"],"h1":"Los conductores necesitan espacio para ver la señal o la luz, así que la distancia es mayor que en un cruce peatonal.","h2":"En New Hampshire, no puede estacionarse a menos de 30 pies antes de una señal de alto, una luz intermitente o un semáforo al lado de la vía.","p":"Correcto. Quédese a 30 pies."},"ref":{"doc":"NH","page":null}},{"id":"nh-032","scope":"NH","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Hampshire, how close to the nearest rail of a railroad crossing may you park?","o":["No closer than 50 feet","No closer than 15 feet","No closer than 25 feet","No closer than 100 feet"],"h1":"It is the longest of the usual parking distances.","h2":"In New Hampshire, you may not park within 50 feet of the nearest rail of a railroad crossing, except for a short stop to load or unload.","p":"Right. Stay 50 feet from the nearest rail."},"es":{"q":"En New Hampshire, ¿a qué distancia del riel más cercano de un cruce de ferrocarril puede estacionarse?","o":["No a menos de 50 pies","No a menos de 15 pies","No a menos de 25 pies","No a menos de 100 pies"],"h1":"Es la mayor de las distancias comunes para estacionar.","h2":"En New Hampshire, no puede estacionarse a menos de 50 pies del riel más cercano de un cruce de ferrocarril, salvo una parada corta para cargar o descargar.","p":"Correcto. Quédese a 50 pies del riel más cercano."},"ref":{"doc":"NH","page":null}},{"id":"nh-033","scope":"NH","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Hampshire, how close to the driveway of a fire station may you park, on the same side of the street?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 20 feet","No closer than 100 feet"],"h1":"It is the same distance as from a crosswalk at an intersection.","h2":"In New Hampshire, you may not park within 20 feet of the driveway entrance of a fire station.","p":"Right. Stay 20 feet from a fire station driveway."},"es":{"q":"En New Hampshire, ¿a qué distancia de la entrada de vehículos de una estación de bomberos puede estacionarse, del mismo lado de la calle?","o":["No a menos de 5 pies","No a menos de 10 pies","No a menos de 20 pies","No a menos de 100 pies"],"h1":"Es la misma distancia que desde un cruce peatonal en una intersección.","h2":"En New Hampshire, no puede estacionarse a menos de 20 pies de la entrada de vehículos de una estación de bomberos.","p":"Correcto. Quédese a 20 pies de la entrada de los bomberos."},"ref":{"doc":"NH","page":null}},{"id":"nh-034","scope":"NH","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Hampshire, a school bus is stopped with its red lights flashing. How far from the bus must you stop?","o":["At least 10 feet away","At least 25 feet away","At least 50 feet away","At least 100 feet away"],"h1":"It is more than two car lengths.","h2":"In New Hampshire, you must stop at least 25 feet from a school bus with flashing red lights and wait until it moves or the lights stop.","p":"Right. Stop at least 25 feet away."},"es":{"q":"En New Hampshire, un autobús escolar está detenido con sus luces rojas intermitentes. ¿A qué distancia del autobús debe detenerse?","o":["Al menos a 10 pies","Al menos a 25 pies","Al menos a 50 pies","Al menos a 100 pies"],"h1":"Es más que el largo de dos carros.","h2":"En New Hampshire, debe detenerse al menos a 25 pies de un autobús escolar con luces rojas intermitentes y esperar hasta que se mueva o se apaguen las luces.","p":"Correcto. Deténgase al menos a 25 pies."},"ref":{"doc":"NH","page":null}},{"id":"nh-035","scope":"NH","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New Hampshire, you are on a divided highway with separate roadways. A school bus going the other way is stopped on the other roadway with red lights flashing. What must you do?","o":["Stop at least 25 feet away until the bus moves","Pull onto the shoulder and stop","Slow to 10 mph as you pass","You do not need to stop"],"h1":"The bus is on a separate roadway, going the opposite way.","h2":"In New Hampshire, on a divided highway with separate roadways, you do not need to stop for a school bus going the opposite way.","p":"Right. On a divided highway, oncoming traffic does not stop."},"es":{"q":"En New Hampshire, usted va por una carretera dividida con calzadas separadas. Un autobús escolar que va en sentido contrario está detenido en la otra calzada con luces rojas intermitentes. ¿Qué debe hacer?","o":["Detenerse al menos a 25 pies hasta que el autobús se mueva","Salir al acotamiento y detenerse","Bajar a 10 mph al pasar","No necesita detenerse"],"h1":"El autobús está en una calzada separada y va en sentido contrario.","h2":"En New Hampshire, en una carretera dividida con calzadas separadas, no necesita detenerse por un autobús escolar que va en sentido contrario.","p":"Correcto. En una carretera dividida, el tránsito en sentido contrario no se detiene."},"ref":{"doc":"NH","page":null}},{"id":"nh-036","scope":"NH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Hampshire, you pass a bicycle while driving at 50 mph. What is the smallest gap the law treats as safe?","o":["3 feet","4 feet","5 feet","6 feet"],"h1":"The 3-foot rule is for 30 mph or less. Above that, you need more room.","h2":"In New Hampshire, the gap starts at 3 feet at 30 mph or less and grows by one foot for every 10 mph above 30, so at 50 mph it is 5 feet.","p":"Right. At 50 mph, give at least 5 feet."},"es":{"q":"En New Hampshire, usted rebasa a una bicicleta manejando a 50 mph. ¿Cuál es el espacio mínimo que la ley considera seguro?","o":["3 pies","4 pies","5 pies","6 pies"],"h1":"La regla de 3 pies es para 30 mph o menos. Más rápido, necesita más espacio.","h2":"En New Hampshire, el espacio empieza en 3 pies a 30 mph o menos y aumenta un pie por cada 10 mph por encima de 30, así que a 50 mph es de 5 pies.","p":"Correcto. A 50 mph, deje al menos 5 pies."},"ref":{"doc":"NH","page":null}},{"id":"nh-037","scope":"NH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Hampshire, which child passenger must ride in an approved child restraint, such as a car seat or booster seat?","o":["A child under 7 who is shorter than 57 inches","Any child under 12","Only a child under 4","Any child shorter than 4 feet, at any age"],"h1":"The rule uses both an age and a height.","h2":"In New Hampshire, a child under 7 must ride in an approved child restraint unless the child is 57 inches tall or more.","p":"Right. Under 7 and under 57 inches means a child restraint."},"es":{"q":"En New Hampshire, ¿qué niño pasajero debe ir en un sistema de retención infantil aprobado, como una silla de auto o un asiento elevador?","o":["Un niño menor de 7 años que mide menos de 57 pulgadas","Cualquier niño menor de 12 años","Solo un niño menor de 4 años","Cualquier niño que mide menos de 4 pies, a cualquier edad"],"h1":"La regla usa una edad y una estatura.","h2":"En New Hampshire, un niño menor de 7 años debe ir en un sistema de retención infantil aprobado, salvo que mida 57 pulgadas o más.","p":"Correcto. Menor de 7 años y de menos de 57 pulgadas va en asiento infantil."},"ref":{"doc":"NH","page":null}},{"id":"nh-038","scope":"NH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Hampshire, a child under what age must ride in a rear-facing car seat?","o":["Under 6 months","Under 1 year","Under 4 years","Under 2 years"],"h1":"It covers babies and young toddlers.","h2":"In New Hampshire, a child under 2 years old must ride in a rear-facing child restraint.","p":"Right. Under 2 rides rear-facing."},"es":{"q":"En New Hampshire, ¿un niño menor de qué edad debe ir en una silla de auto mirando hacia atrás?","o":["Menor de 6 meses","Menor de 1 año","Menor de 4 años","Menor de 2 años"],"h1":"Incluye a bebés y a niños que recién empiezan a caminar.","h2":"En New Hampshire, un niño menor de 2 años debe ir en un sistema de retención infantil mirando hacia atrás.","p":"Correcto. Menores de 2 años van mirando hacia atrás."},"ref":{"doc":"NH","page":null}},{"id":"nh-039","scope":"NH","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Hampshire, which rule applies to a rider with a motorcycle learner's permit?","o":["May ride at any hour with one passenger","May ride only in daylight and may not carry passengers","May ride only on interstate highways","May ride at night only with a passenger 25 or older"],"h1":"A new rider rides alone, when it is easiest to see.","h2":"In New Hampshire, a motorcycle learner's permit allows riding only between sunrise and sunset, with no passengers.","p":"Right. Daylight only, and no passengers."},"es":{"q":"En New Hampshire, ¿qué regla se aplica a un motociclista con permiso de aprendiz de motocicleta?","o":["Puede manejar a cualquier hora con un pasajero","Puede manejar solo de día y no puede llevar pasajeros","Puede manejar solo en carreteras interestatales","Puede manejar de noche solo con un pasajero de 25 años o más"],"h1":"Un motociclista nuevo va solo, cuando es más fácil ver.","h2":"En New Hampshire, el permiso de aprendiz de motocicleta permite manejar solo entre la salida y la puesta del sol, sin pasajeros.","p":"Correcto. Solo de día y sin pasajeros."},"ref":{"doc":"NH","page":null}},{"id":"nh-040","scope":"NH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Hampshire, during what period does the law require your vehicle's lamps to be lit?","o":["Only from 9 p.m. to 5 a.m.","From half an hour after sunset to half an hour before sunrise","From 1 hour after sunset to 1 hour before sunrise","Only when the street lights are off"],"h1":"It starts a short time after the sun goes down.","h2":"In New Hampshire, your lamps must be lit from half an hour after sunset to half an hour before sunrise.","p":"Right. Lights on from half an hour after sunset to half an hour before sunrise."},"es":{"q":"En New Hampshire, ¿durante qué período exige la ley que las luces de su vehículo estén encendidas?","o":["Solo de 9 p.m. a 5 a.m.","Desde media hora después de la puesta del sol hasta media hora antes de la salida del sol","Desde 1 hora después de la puesta del sol hasta 1 hora antes de la salida del sol","Solo cuando las luces de la calle están apagadas"],"h1":"Empieza poco después de que se pone el sol.","h2":"En New Hampshire, las luces deben estar encendidas desde media hora después de la puesta del sol hasta media hora antes de la salida del sol.","p":"Correcto. Luces encendidas desde media hora después de la puesta del sol hasta media hora antes de la salida."},"ref":{"doc":"NH","page":null}},{"id":"nh-041","scope":"NH","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In New Hampshire, a fire truck is going to a fire alarm. How close behind it may you follow?","o":["No closer than 500 feet","No closer than 100 feet","No closer than 200 feet","No closer than 1,000 feet"],"h1":"It is about the length of one and a half football fields.","h2":"In New Hampshire, you may not follow a fire truck answering an alarm any closer than 500 feet.","p":"Right. Stay at least 500 feet behind."},"es":{"q":"En New Hampshire, un camión de bomberos va a atender una alarma de incendio. ¿A qué distancia detrás de él puede seguirlo?","o":["No a menos de 500 pies","No a menos de 100 pies","No a menos de 200 pies","No a menos de 1,000 pies"],"h1":"Es más o menos el largo de una cancha y media de fútbol americano.","h2":"En New Hampshire, no puede seguir a un camión de bomberos que atiende una alarma a menos de 500 pies.","p":"Correcto. Quédese al menos a 500 pies detrás."},"ref":{"doc":"NH","page":null}},{"id":"nh-042","scope":"NH","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Hampshire, you are in a crash and no police officer investigates it. When must you send a written report to the Division of Motor Vehicles?","o":["Within 24 hours, for any crash","Within 30 days, if damage is over $500","Within 15 days, if anyone is hurt or killed or damage is over $1,000","Only if your insurance company asks for one"],"h1":"The report is needed for injuries or larger damage, and you have about two weeks.","h2":"In New Hampshire, if no officer investigates, you must report in writing to the Division of Motor Vehicles within 15 days when anyone is hurt or killed or damage is over $1,000.","p":"Right. Within 15 days, for injury, death or damage over $1,000."},"es":{"q":"En New Hampshire, usted tiene un choque y ningún policía lo investiga. ¿Cuándo debe enviar un informe por escrito a la División de Vehículos Motorizados?","o":["En 24 horas, para cualquier choque","En 30 días, si los daños pasan de $500","En 15 días, si alguien resulta herido o muerto o los daños pasan de $1,000","Solo si su compañía de seguros lo pide"],"h1":"El informe se exige por heridos o daños mayores, y usted tiene unas dos semanas.","h2":"En New Hampshire, si ningún policía investiga, debe informar por escrito a la División de Vehículos Motorizados en 15 días cuando alguien resulta herido o muerto o los daños pasan de $1,000.","p":"Correcto. En 15 días, por heridos, muertos o daños de más de $1,000."},"ref":{"doc":"NH","page":null}},{"id":"nh-043","scope":"NH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Hampshire, you hit a dog or a cat with your car. What must you do?","o":["Nothing, if the animal ran away","Report it only if the animal dies","Call your insurance company within 30 days","Report it as soon as possible to the owner or a police officer"],"h1":"Someone needs to know about the animal quickly.","h2":"In New Hampshire, if you hit a dog or a cat, you must report it as soon as possible to the owner or to a police officer.","p":"Right. Tell the owner or the police as soon as you can."},"es":{"q":"En New Hampshire, usted atropella a un perro o un gato con su carro. ¿Qué debe hacer?","o":["Nada, si el animal se fue corriendo","Informarlo solo si el animal muere","Llamar a su compañía de seguros en 30 días","Informarlo lo antes posible al dueño o a un policía"],"h1":"Alguien debe saber pronto lo que le pasó al animal.","h2":"En New Hampshire, si atropella a un perro o un gato, debe informarlo lo antes posible al dueño o a un policía.","p":"Correcto. Avise al dueño o a la policía lo antes posible."},"ref":{"doc":"NH","page":null}},{"id":"nh-044","scope":"NH","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Hampshire, you move or change your name. How soon must you tell the DMV in writing?","o":["Within 10 days","Within 30 days","Within 60 days","At your next license renewal"],"h1":"You have about one month.","h2":"In New Hampshire, you must tell the DMV in writing within 30 days after you change your name or address.","p":"Right. Within 30 days."},"es":{"q":"En New Hampshire, usted se muda o cambia de nombre. ¿En cuánto tiempo debe avisarle al DMV por escrito?","o":["En 10 días","En 30 días","En 60 días","En su próxima renovación de licencia"],"h1":"Tiene más o menos un mes.","h2":"En New Hampshire, debe avisarle al DMV por escrito en un plazo de 30 días después de cambiar de nombre o de dirección.","p":"Correcto. En 30 días."},"ref":{"doc":"NH","page":null}},{"id":"nh-045","scope":"NH","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Hampshire, when does a regular adult driver's license expire?","o":["On your fifth birthday after the license was issued","Exactly 4 years after the issue date","On your eighth birthday after the license was issued","Every 2 years on January 1"],"h1":"It ends on a birthday, a few years after you got it.","h2":"In New Hampshire, a regular driver's license expires on your fifth birthday after it was issued.","p":"Right. It expires on your fifth birthday after issue."},"es":{"q":"En New Hampshire, ¿cuándo vence una licencia de conducir común para adultos?","o":["En su quinto cumpleaños después de que se emitió la licencia","Exactamente 4 años después de la fecha de emisión","En su octavo cumpleaños después de que se emitió la licencia","Cada 2 años el 1 de enero"],"h1":"Vence en un cumpleaños, unos años después de recibirla.","h2":"En New Hampshire, una licencia de conducir común vence en su quinto cumpleaños después de que se emitió.","p":"Correcto. Vence en su quinto cumpleaños después de emitida."},"ref":{"doc":"NH","page":null}},{"id":"nh-046","scope":"NH","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Hampshire, you move here from another state and become a resident. How soon must you get a New Hampshire driver's license?","o":["Within 10 days","Within 30 days","Within 60 days","Within 1 year"],"h1":"You have about two months.","h2":"In New Hampshire, a new resident must get a New Hampshire driver's license within 60 days of becoming a resident.","p":"Right. Within 60 days."},"es":{"q":"En New Hampshire, usted se muda aquí desde otro estado y pasa a ser residente. ¿En cuánto tiempo debe obtener una licencia de conducir de New Hampshire?","o":["En 10 días","En 30 días","En 60 días","En 1 año"],"h1":"Tiene más o menos dos meses.","h2":"En New Hampshire, un nuevo residente debe obtener una licencia de conducir de New Hampshire en un plazo de 60 días desde que pasa a ser residente.","p":"Correcto. En 60 días."},"ref":{"doc":"NH","page":null}},{"id":"nh-047","scope":"NH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Hampshire, you leave your car parked on a hill with no one in it. What must you do?","o":["Stop the engine and leave the key in, with the wheels pointed straight","Leave the engine running, set the brake and lock the doors","Stop the engine, take the key, and leave the car in neutral","Stop the engine, take the key, set the brake and turn the front wheels to the curb or side of the road"],"h1":"The car must not be able to start or roll away.","h2":"In New Hampshire, before leaving a car on a hill, you must stop the engine, take the key, set the brake and turn the front wheels to the curb or side of the road.","p":"Right. Engine off, key out, brake set, wheels to the curb."},"es":{"q":"En New Hampshire, usted deja su carro estacionado en una pendiente sin nadie adentro. ¿Qué debe hacer?","o":["Apagar el motor y dejar la llave puesta, con las ruedas derechas","Dejar el motor encendido, poner el freno y cerrar las puertas con llave","Apagar el motor, sacar la llave y dejar el carro en neutro","Apagar el motor, sacar la llave, poner el freno y girar las ruedas delanteras hacia la acera o el lado de la vía"],"h1":"El carro no debe poder arrancar ni rodar.","h2":"En New Hampshire, antes de dejar un carro en una pendiente, debe apagar el motor, sacar la llave, poner el freno y girar las ruedas delanteras hacia la acera o el lado de la vía.","p":"Correcto. Motor apagado, llave afuera, freno puesto y ruedas hacia la acera."},"ref":{"doc":"NH","page":null}},{"id":"nh-048","scope":"NH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Hampshire, you are driving with a capped bottle of wine that is partly empty. Where must it be?","o":["Under the driver's seat","In the trunk","In the glove box","On the back seat, as long as it is capped"],"h1":"It must be out of the area where people sit.","h2":"In New Hampshire, a capped, partly full container of alcohol must ride in the trunk, or in the place hardest for the driver to reach if there is no trunk.","p":"Right. It goes in the trunk."},"es":{"q":"En New Hampshire, usted maneja con una botella de vino tapada que está medio vacía. ¿Dónde debe ir?","o":["Debajo del asiento del conductor","En el maletero (cajuela)","En la guantera","En el asiento de atrás, si está tapada"],"h1":"Debe estar fuera del área donde van las personas.","h2":"En New Hampshire, un envase de alcohol tapado y parcialmente lleno debe ir en el maletero, o en el lugar más difícil de alcanzar para el conductor si no hay maletero.","p":"Correcto. Va en el maletero."},"ref":{"doc":"NH","page":null}},{"id":"nh-049","scope":"NH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Hampshire, what is the smallest fine for a first conviction for impaired driving (DWI)?","o":["$100","$250","$500","$5,000"],"h1":"It is several hundred dollars.","h2":"In New Hampshire, a first DWI conviction brings a fine of at least $500.","p":"Right. The fine is at least $500."},"es":{"q":"En New Hampshire, ¿cuál es la multa mínima por una primera condena por manejar bajo los efectos del alcohol o drogas (DWI)?","o":["$100","$250","$500","$5,000"],"h1":"Son varios cientos de dólares.","h2":"En New Hampshire, una primera condena por DWI trae una multa de al menos $500.","p":"Correcto. La multa es de al menos $500."},"ref":{"doc":"NH","page":null}},{"id":"nh-050","scope":"NH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Hampshire, at what blood alcohol level is driving aggravated DWI, even with no other factor?","o":["0.16 or more","0.10 or more","0.12 or more","0.20 or more"],"h1":"It is twice the usual adult limit of 0.08.","h2":"In New Hampshire, driving with a blood alcohol level of 0.16 or more is aggravated DWI on its own.","p":"Right. 0.16 or more is aggravated DWI."},"es":{"q":"En New Hampshire, ¿con qué nivel de alcohol en la sangre manejar es DWI agravado, aunque no haya otro factor?","o":["0.16 o más","0.10 o más","0.12 o más","0.20 o más"],"h1":"Es el doble del límite habitual para adultos, que es 0.08.","h2":"En New Hampshire, manejar con un nivel de alcohol en la sangre de 0.16 o más es DWI agravado por sí solo.","p":"Correcto. 0.16 o más es DWI agravado."},"ref":{"doc":"NH","page":null}},{"id":"nh-051","scope":"NH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Hampshire, who must wear a helmet on a motorcycle by law?","o":["Every rider and passenger","Only the driver","Only riders over 65","Riders and passengers under 18"],"h1":"The law is about age, not about who steers.","h2":"In New Hampshire, the law requires a helmet for motorcycle riders and passengers under 18.","p":"Right. The helmet law covers anyone under 18."},"es":{"q":"En New Hampshire, ¿quién debe usar casco en una motocicleta por ley?","o":["Todos los motociclistas y pasajeros","Solo quien maneja","Solo los motociclistas mayores de 65 años","Los motociclistas y pasajeros menores de 18 años"],"h1":"La ley se basa en la edad, no en quién maneja.","h2":"En New Hampshire, la ley exige casco a los motociclistas y pasajeros menores de 18 años.","p":"Correcto. La ley del casco aplica a menores de 18 años."},"ref":{"doc":"NH","page":null}},{"id":"nh-052","scope":"NH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Hampshire, what is the smallest tire tread depth allowed by law on a car?","o":["1/32 of an inch","2/32 of an inch","4/32 of an inch","6/32 of an inch"],"h1":"It is very thin, but not the thinnest choice here.","h2":"In New Hampshire, a car's tires must have a tread depth of at least 2/32 of an inch.","p":"Right. At least 2/32 of an inch."},"es":{"q":"En New Hampshire, ¿cuál es la profundidad mínima de la banda de rodadura de las llantas que permite la ley en un carro?","o":["1/32 de pulgada","2/32 de pulgada","4/32 de pulgada","6/32 de pulgada"],"h1":"Es muy poca, pero no la menor de estas opciones.","h2":"En New Hampshire, las llantas de un carro deben tener una banda de rodadura de al menos 2/32 de pulgada.","p":"Correcto. Al menos 2/32 de pulgada."},"ref":{"doc":"NH","page":null}},{"id":"nh-053","scope":"NH","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New Hampshire, the car ahead of you in your lane has stopped at a crosswalk to let a person cross. What must you do?","o":["Pass it carefully on the left","Honk and pass it on the right","Do not pass it; stay behind it","Pass it once the person reaches the middle of the road"],"h1":"The other driver may be stopped for someone you cannot see.","h2":"In New Hampshire, you may not pass a car that has stopped at a crosswalk to let a person cross.","p":"Right. Never pass a car stopped for a person crossing."},"es":{"q":"En New Hampshire, el carro que va delante en su carril se detuvo en un cruce peatonal para dejar pasar a una persona. ¿Qué debe hacer?","o":["Rebasarlo con cuidado por la izquierda","Tocar la bocina y rebasarlo por la derecha","No rebasarlo; quedarse detrás","Rebasarlo cuando la persona llegue a la mitad de la calle"],"h1":"El otro conductor puede estar detenido por alguien que usted no ve.","h2":"En New Hampshire, no puede rebasar a un carro que se detuvo en un cruce peatonal para dejar pasar a una persona.","p":"Correcto. Nunca rebase a un carro detenido por un peatón."},"ref":{"doc":"NH","page":null}},{"id":"nj-001","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, how many questions are on the knowledge test?","o":["20 questions","25 questions","35 questions","50 questions"],"h1":"It is half of one hundred.","h2":"The New Jersey knowledge test has 50 multiple-choice questions.","p":"Right. The New Jersey test has 50 questions."},"es":{"q":"En New Jersey, ¿cuántas preguntas tiene el examen de conocimientos?","o":["20 preguntas","25 preguntas","35 preguntas","50 preguntas"],"h1":"Es la mitad de cien.","h2":"El examen de conocimientos de New Jersey tiene 50 preguntas de opción múltiple.","p":"Correcto. El examen de New Jersey tiene 50 preguntas."},"zh":{"q":"在 New Jersey，知识考试有多少道题？","o":["20 道题","25 道题","35 道题","50 道题"],"h1":"它是一百的一半。","h2":"New Jersey 的知识考试有 50 道选择题。","p":"对。New Jersey 的考试有 50 道题。"},"vi":{"q":"Ở New Jersey, bài thi kiến thức (knowledge test) có bao nhiêu câu hỏi?","o":["20 câu hỏi","25 câu hỏi","35 câu hỏi","50 câu hỏi"],"h1":"Đó là một nửa của một trăm.","h2":"Bài thi kiến thức của New Jersey có 50 câu hỏi trắc nghiệm.","p":"Đúng. Bài thi của New Jersey có 50 câu hỏi."},"tl":{"q":"Sa New Jersey, ilang tanong ang nasa knowledge test?","o":["20 tanong","25 tanong","35 tanong","50 tanong"],"h1":"Ito ay kalahati ng isang daan.","h2":"Ang knowledge test ng New Jersey ay may 50 multiple-choice na tanong.","p":"Tama. May 50 tanong ang test ng New Jersey."},"ar":{"q":"في New Jersey، كم سؤالًا في اختبار المعرفة (knowledge test)؟","o":["20 سؤالًا","25 سؤالًا","35 سؤالًا","50 سؤالًا"],"h1":"إنه نصف المئة.","h2":"في اختبار المعرفة في New Jersey يوجد 50 سؤالًا من نوع الاختيار من متعدد.","p":"صحيح. في اختبار New Jersey يوجد 50 سؤالًا."},"ref":{"doc":"NJ","page":30}},{"id":"nj-002","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, how many knowledge test questions must you answer correctly to pass?","o":["30","40","35","45"],"h1":"You need 80 percent of the 50 questions.","h2":"You must answer at least 40 of the 50 New Jersey test questions correctly, which is 80 percent.","p":"Right. You need 40 correct answers."},"es":{"q":"En New Jersey, ¿cuántas preguntas del examen de conocimientos debe contestar bien para aprobar?","o":["30","40","35","45"],"h1":"Necesita el 80 por ciento de las 50 preguntas.","h2":"Usted debe contestar bien por lo menos 40 de las 50 preguntas del examen de New Jersey, que es el 80 por ciento.","p":"Correcto. Necesita 40 respuestas correctas."},"zh":{"q":"在 New Jersey，知识考试必须答对多少道题才能通过？","o":["30","40","35","45"],"h1":"你需要答对 50 道题的百分之 80。","h2":"你必须答对 New Jersey 考试 50 道题里的至少 40 道，也就是百分之 80。","p":"对。你需要答对 40 道。"},"vi":{"q":"Ở New Jersey, bạn phải trả lời đúng bao nhiêu câu hỏi của bài thi kiến thức để đậu?","o":["30","40","35","45"],"h1":"Bạn cần đúng 80 phần trăm của 50 câu hỏi.","h2":"Bạn phải trả lời đúng ít nhất 40 trong 50 câu hỏi của bài thi New Jersey, tức là 80 phần trăm.","p":"Đúng. Bạn cần 40 câu trả lời đúng."},"tl":{"q":"Sa New Jersey, ilang tanong sa knowledge test ang dapat mong masagot nang tama para pumasa?","o":["30","40","35","45"],"h1":"Kailangan mo ang 80 porsiyento ng 50 tanong.","h2":"Dapat mong masagot nang tama ang hindi bababa sa 40 sa 50 tanong ng test sa New Jersey, na 80 porsiyento.","p":"Tama. Kailangan mo ng 40 tamang sagot."},"ar":{"q":"في New Jersey، كم سؤالًا من أسئلة اختبار المعرفة يجب أن تجيب عنه إجابة صحيحة لتنجح؟","o":["30","40","35","45"],"h1":"تحتاج إلى 80 بالمئة من الأسئلة الخمسين.","h2":"يجب أن تجيب إجابة صحيحة عن 40 سؤالًا على الأقل من 50 سؤالًا في اختبار New Jersey، أي 80 بالمئة.","p":"صحيح. تحتاج إلى 40 إجابة صحيحة."},"ref":{"doc":"NJ","page":31}},{"id":"nj-003","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, if you fail the knowledge test, how long must you wait to take it again?","o":["The same day","One day","7 days","30 days"],"h1":"It is one week.","h2":"In New Jersey you must wait 7 days before you can retake a failed knowledge test.","p":"Right. You wait seven days to try again."},"es":{"q":"En New Jersey, si no aprueba el examen de conocimientos, ¿cuánto debe esperar para presentarlo otra vez?","o":["El mismo día","Un día","7 días","30 días"],"h1":"Es una semana.","h2":"En New Jersey usted debe esperar 7 días antes de volver a presentar un examen de conocimientos que no aprobó.","p":"Correcto. Se esperan siete días para intentarlo de nuevo."},"zh":{"q":"在 New Jersey，如果知识考试没通过，要等多久才能再考？","o":["当天","一天","7 天","30 天"],"h1":"它是一个星期。","h2":"在 New Jersey，知识考试没通过的话，你必须等 7 天才能再考。","p":"对。你要等七天才能再考。"},"vi":{"q":"Ở New Jersey, nếu bạn thi rớt bài thi kiến thức, bạn phải chờ bao lâu để thi lại?","o":["Cùng ngày","Một ngày","7 ngày","30 ngày"],"h1":"Đó là một tuần.","h2":"Ở New Jersey, bạn phải chờ 7 ngày rồi mới được thi lại bài thi kiến thức đã rớt.","p":"Đúng. Bạn chờ bảy ngày để thi lại."},"tl":{"q":"Sa New Jersey, kung bumagsak ka sa knowledge test, gaano katagal ka dapat maghintay bago kumuha ulit?","o":["Sa parehong araw","Isang araw","7 araw","30 araw"],"h1":"Ito ay isang linggo.","h2":"Sa New Jersey, dapat kang maghintay ng 7 araw bago mo ulitin ang knowledge test na binagsak mo.","p":"Tama. Maghihintay ka ng pitong araw bago sumubok ulit."},"ar":{"q":"في New Jersey، إذا رسبت في اختبار المعرفة، كم يجب أن تنتظر لتعيده؟","o":["في اليوم نفسه","يومًا واحدًا","7 أيام","30 يومًا"],"h1":"إنه أسبوع واحد.","h2":"في New Jersey يجب أن تنتظر 7 أيام قبل أن تعيد اختبار المعرفة الذي رسبت فيه.","p":"صحيح. تنتظر سبعة أيام لتحاول مرة أخرى."},"ref":{"doc":"NJ","page":null}},{"id":"nj-004","scope":"NJ","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Jersey, what lets a 16-year-old get a special learner's permit?","o":["Being enrolled in a behind-the-wheel driver training course","Having a parent with a license","Passing a road test first","Owning a car"],"h1":"It is connected to driving lessons.","h2":"A New Jersey 16-year-old can get a special learner's permit by enrolling in a behind-the-wheel driver training course at a high school or a licensed driving school.","p":"Right. Driver training opens the permit at 16."},"es":{"q":"En New Jersey, ¿qué le permite a un joven de 16 años obtener un permiso especial de aprendiz?","o":["Estar inscrito en un curso de manejo práctico al volante","Tener un padre con licencia","Aprobar primero un examen de manejo","Ser dueño de un carro"],"h1":"Tiene que ver con clases de manejo.","h2":"Un joven de 16 años en New Jersey puede obtener un permiso especial de aprendiz si se inscribe en un curso de manejo práctico al volante en una escuela secundaria o en una escuela de manejo con licencia.","p":"Correcto. El curso de manejo abre el permiso a los 16."},"zh":{"q":"在 New Jersey，16 岁的青少年怎样才能拿到特别学习驾照（special learner's permit）？","o":["报名参加实际上路的驾驶训练课程","父母有驾照","先通过路考","自己有一辆车"],"h1":"它和驾驶课有关。","h2":"New Jersey 16 岁的青少年报名参加高中或有执照的驾校的实际上路驾驶训练课程，就可以拿到特别学习驾照。","p":"对。参加驾驶训练，16 岁就能拿学习驾照。"},"vi":{"q":"Ở New Jersey, điều gì cho phép một người 16 tuổi lấy giấy phép tập lái đặc biệt (special learner's permit)?","o":["Đã ghi danh vào một khóa học lái xe thực hành (behind-the-wheel)","Có cha hoặc mẹ có bằng lái","Thi đậu bài thi lái xe trên đường trước","Có xe hơi riêng"],"h1":"Điều này liên quan đến các buổi học lái xe.","h2":"Ở New Jersey, một người 16 tuổi có thể lấy giấy phép tập lái đặc biệt khi ghi danh vào một khóa học lái xe thực hành tại trường trung học hoặc tại một trường dạy lái xe có giấy phép.","p":"Đúng. Khóa học lái xe giúp bạn lấy giấy phép ở tuổi 16."},"tl":{"q":"Sa New Jersey, ano ang nagpapahintulot sa isang 16 taong gulang na makakuha ng special learner's permit?","o":["Naka-enroll sa isang behind-the-wheel na kurso sa pagmamaneho","May magulang na may lisensya","Pumasa muna sa road test","May sariling kotse"],"h1":"May kinalaman ito sa mga leksyon sa pagmamaneho.","h2":"Sa New Jersey, ang isang 16 taong gulang ay makakakuha ng special learner's permit kapag naka-enroll sa isang behind-the-wheel na kurso sa pagmamaneho sa high school o sa isang lisensyadong driving school.","p":"Tama. Ang kurso sa pagmamaneho ang nagbubukas ng permit sa edad na 16."},"ar":{"q":"في New Jersey، ما الذي يسمح لشخص عمره 16 سنة بالحصول على تصريح تعلّم خاص (special learner's permit)؟","o":["التسجيل في دورة تدريب عملي على القيادة (behind-the-wheel)","أن يكون لأحد والديه رخصة قيادة","النجاح في اختبار الطريق أولًا","امتلاك سيارة"],"h1":"الأمر له علاقة بدروس القيادة.","h2":"في New Jersey يستطيع من عمره 16 سنة الحصول على تصريح تعلّم خاص إذا سجّل في دورة تدريب عملي على القيادة في مدرسة ثانوية أو في مدرسة قيادة مرخّصة.","p":"صحيح. دورة تدريب القيادة تتيح التصريح في عمر 16."},"ref":{"doc":"NJ","page":19}},{"id":"nj-005","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, at what age can you get an examination permit without a driver training course?","o":["16","17","18","21"],"h1":"It is one year after the age for the special learner's permit.","h2":"In New Jersey you can get an examination permit at 17 without taking a driver training course.","p":"Right. At 17 no driver training course is needed."},"es":{"q":"En New Jersey, ¿a qué edad puede obtener un permiso de examen sin un curso de manejo?","o":["16","17","18","21"],"h1":"Es un año después de la edad del permiso especial de aprendiz.","h2":"En New Jersey usted puede obtener un permiso de examen a los 17 años sin tomar un curso de manejo.","p":"Correcto. A los 17 no se necesita curso de manejo."},"zh":{"q":"在 New Jersey，不上驾驶训练课程，几岁可以拿到考试学习驾照（examination permit）？","o":["16","17","18","21"],"h1":"它比特别学习驾照的年龄大一岁。","h2":"在 New Jersey，你 17 岁时不用上驾驶训练课程，就可以拿到考试学习驾照。","p":"对。17 岁不需要上驾驶训练课程。"},"vi":{"q":"Ở New Jersey, bạn có thể lấy giấy phép thi (examination permit) mà không cần khóa học lái xe từ bao nhiêu tuổi?","o":["16","17","18","21"],"h1":"Đó là một năm sau độ tuổi lấy giấy phép tập lái đặc biệt.","h2":"Ở New Jersey, bạn có thể lấy giấy phép thi (examination permit) từ 17 tuổi mà không cần học khóa lái xe.","p":"Đúng. Từ 17 tuổi thì không cần khóa học lái xe."},"tl":{"q":"Sa New Jersey, sa anong edad ka makakakuha ng examination permit nang walang kurso sa pagmamaneho?","o":["16","17","18","21"],"h1":"Ito ay isang taon pagkatapos ng edad para sa special learner's permit.","h2":"Sa New Jersey, makakakuha ka ng examination permit sa edad na 17 nang hindi kumukuha ng kurso sa pagmamaneho.","p":"Tama. Sa edad na 17, hindi na kailangan ng kurso sa pagmamaneho."},"ar":{"q":"في New Jersey، في أي عمر يمكنك الحصول على تصريح الاختبار (examination permit) دون دورة تدريب على القيادة؟","o":["16","17","18","21"],"h1":"إنه بعد سنة واحدة من عمر تصريح التعلّم الخاص.","h2":"في New Jersey يمكنك الحصول على تصريح الاختبار (examination permit) في عمر 17 سنة دون أن تأخذ دورة تدريب على القيادة.","p":"صحيح. في عمر 17 لا تحتاج إلى دورة تدريب على القيادة."},"ref":{"doc":"NJ","page":20}},{"id":"nj-006","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, how much driving experience must the adult supervising a permit holder have?","o":["At least 1 year","At least 6 months","At least 10 years","At least 3 years"],"h1":"It is more than two years but less than five.","h2":"The supervising driver in New Jersey must be at least 21, hold a valid New Jersey license, and have at least three years of driving experience.","p":"Right. The supervisor needs three years of experience."},"es":{"q":"En New Jersey, ¿cuánta experiencia de manejo debe tener el adulto que supervisa a un conductor con permiso?","o":["Por lo menos 1 año","Por lo menos 6 meses","Por lo menos 10 años","Por lo menos 3 años"],"h1":"Es más de dos años pero menos de cinco.","h2":"El conductor supervisor en New Jersey debe tener por lo menos 21 años, una licencia válida de New Jersey y por lo menos tres años de experiencia manejando.","p":"Correcto. El supervisor necesita tres años de experiencia."},"zh":{"q":"在 New Jersey，监督学习驾照持有人的成年人必须有多少驾驶经验？","o":["至少 1 年","至少 6 个月","至少 10 年","至少 3 年"],"h1":"它比两年多，但比五年少。","h2":"在 New Jersey，监督司机必须至少 21 岁，有有效的 New Jersey 驾照，并且至少有三年驾驶经验。","p":"对。监督的人需要三年经验。"},"vi":{"q":"Ở New Jersey, người lớn đi kèm giám sát người có giấy phép tập lái phải có bao nhiêu kinh nghiệm lái xe?","o":["Ít nhất 1 năm","Ít nhất 6 tháng","Ít nhất 10 năm","Ít nhất 3 năm"],"h1":"Nhiều hơn hai năm nhưng ít hơn năm năm.","h2":"Ở New Jersey, người lái xe giám sát phải ít nhất 21 tuổi, có bằng lái New Jersey còn hiệu lực, và có ít nhất ba năm kinh nghiệm lái xe.","p":"Đúng. Người giám sát cần ba năm kinh nghiệm."},"tl":{"q":"Sa New Jersey, gaano karaming karanasan sa pagmamaneho ang dapat mayroon ang adult na nagbabantay sa may permit?","o":["Hindi bababa sa 1 taon","Hindi bababa sa 6 na buwan","Hindi bababa sa 10 taon","Hindi bababa sa 3 taon"],"h1":"Higit ito sa dalawang taon pero kulang sa lima.","h2":"Sa New Jersey, ang nagbabantay na driver ay dapat hindi bababa sa 21 taong gulang, may valid na lisensya ng New Jersey, at may hindi bababa sa tatlong taon na karanasan sa pagmamaneho.","p":"Tama. Kailangan ng nagbabantay ang tatlong taon na karanasan."},"ar":{"q":"في New Jersey، كم سنة من الخبرة في القيادة يجب أن تكون لدى الشخص البالغ الذي يرافق حامل التصريح ويشرف عليه؟","o":["سنة واحدة على الأقل","6 أشهر على الأقل","10 سنوات على الأقل","3 سنوات على الأقل"],"h1":"أكثر من سنتين وأقل من خمس سنوات.","h2":"في New Jersey يجب أن يكون السائق المشرف عمره 21 سنة على الأقل، ويحمل رخصة قيادة سارية من New Jersey، ولديه ثلاث سنوات على الأقل من الخبرة في القيادة.","p":"صحيح. يحتاج المشرف إلى ثلاث سنوات من الخبرة."},"ref":{"doc":"NJ","page":18}},{"id":"nj-007","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, where must the supervising driver sit when a permit holder drives?","o":["In the back seat","Anywhere in the car","In the front seat","In a separate car following behind"],"h1":"The supervisor must be close enough to help right away.","h2":"In New Jersey the adult supervising driver must sit in the front seat next to the permit holder.","p":"Right. The supervisor sits in the front seat."},"es":{"q":"En New Jersey, ¿dónde debe sentarse el conductor supervisor cuando maneja alguien con permiso?","o":["En el asiento de atrás","En cualquier lugar del carro","En el asiento de adelante","En otro carro que va detrás"],"h1":"El supervisor debe estar lo bastante cerca para ayudar de inmediato.","h2":"En New Jersey el adulto supervisor debe sentarse en el asiento de adelante, al lado del conductor con permiso.","p":"Correcto. El supervisor va en el asiento de adelante."},"zh":{"q":"在 New Jersey，学习驾照持有人开车时，监督司机必须坐在哪里？","o":["后排座位","车里任何地方","前排座位","跟在后面的另一辆车里"],"h1":"监督的人必须离得够近，能马上帮忙。","h2":"在 New Jersey，监督的成年司机必须坐在前排，在学习驾照持有人旁边。","p":"对。监督的人坐在前排。"},"vi":{"q":"Ở New Jersey, khi người có giấy phép tập lái đang lái xe, người lái xe giám sát phải ngồi ở đâu?","o":["Ở ghế sau","Ở bất cứ chỗ nào trong xe","Ở ghế trước","Trong một xe khác chạy theo phía sau"],"h1":"Người giám sát phải ngồi đủ gần để giúp ngay lập tức.","h2":"Ở New Jersey, người lớn giám sát phải ngồi ở ghế trước, bên cạnh người có giấy phép tập lái.","p":"Đúng. Người giám sát ngồi ở ghế trước."},"tl":{"q":"Sa New Jersey, saan dapat umupo ang nagbabantay na driver kapag nagmamaneho ang may permit?","o":["Sa likurang upuan","Kahit saan sa kotse","Sa harapang upuan","Sa ibang kotse na sumusunod sa likod"],"h1":"Dapat sapat na malapit ang nagbabantay para tumulong agad.","h2":"Sa New Jersey, ang adult na nagbabantay na driver ay dapat umupo sa harapang upuan, katabi ng may permit.","p":"Tama. Sa harapang upuan umuupo ang nagbabantay."},"ar":{"q":"في New Jersey، أين يجب أن يجلس السائق المشرف عندما يقود حامل التصريح؟","o":["في المقعد الخلفي","في أي مكان في السيارة","في المقعد الأمامي","في سيارة أخرى تسير خلفه"],"h1":"يجب أن يكون المشرف قريبًا بما يكفي ليساعد فورًا.","h2":"في New Jersey يجب أن يجلس السائق البالغ المشرف في المقعد الأمامي بجانب حامل التصريح.","p":"صحيح. يجلس المشرف في المقعد الأمامي."},"ref":{"doc":"NJ","page":18}},{"id":"nj-008","scope":"NJ","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Jersey, how long must a permit holder under 21 drive only with a supervising adult before the road test?","o":["At least 6 months","At least 1 month","At least 2 years","No set time"],"h1":"It is half a year.","h2":"In New Jersey a permit holder under 21 must drive with a supervising adult for at least six months before passing the road test.","p":"Right. Six months of supervised driving come first."},"es":{"q":"En New Jersey, ¿cuánto tiempo debe manejar solo con un adulto supervisor un conductor con permiso menor de 21 años antes del examen de manejo?","o":["Por lo menos 6 meses","Por lo menos 1 mes","Por lo menos 2 años","No hay tiempo fijo"],"h1":"Es medio año.","h2":"En New Jersey un conductor con permiso menor de 21 años debe manejar con un adulto supervisor por lo menos seis meses antes de aprobar el examen de manejo.","p":"Correcto. Primero vienen seis meses de manejo supervisado."},"zh":{"q":"在 New Jersey，未满 21 岁的学习驾照持有人在路考前，必须只和监督的成年人一起开车多久？","o":["至少 6 个月","至少 1 个月","至少 2 年","没有规定时间"],"h1":"它是半年。","h2":"在 New Jersey，未满 21 岁的学习驾照持有人在通过路考前，必须和监督的成年人一起开车至少六个月。","p":"对。先要有六个月有人监督的驾驶。"},"vi":{"q":"Ở New Jersey, người có giấy phép tập lái dưới 21 tuổi phải lái xe chỉ khi có người lớn giám sát trong bao lâu trước khi thi lái xe trên đường?","o":["Ít nhất 6 tháng","Ít nhất 1 tháng","Ít nhất 2 năm","Không có thời gian quy định"],"h1":"Đó là nửa năm.","h2":"Ở New Jersey, người có giấy phép tập lái dưới 21 tuổi phải lái xe với người lớn giám sát ít nhất sáu tháng trước khi thi đậu bài thi lái xe trên đường.","p":"Đúng. Phải lái xe có giám sát sáu tháng trước."},"tl":{"q":"Sa New Jersey, gaano katagal dapat magmaneho ang may permit na wala pang 21 taong gulang kasama lamang ang nagbabantay na adult bago ang road test?","o":["Hindi bababa sa 6 na buwan","Hindi bababa sa 1 buwan","Hindi bababa sa 2 taon","Walang takdang panahon"],"h1":"Ito ay kalahating taon.","h2":"Sa New Jersey, ang may permit na wala pang 21 taong gulang ay dapat magmaneho kasama ang nagbabantay na adult nang hindi bababa sa anim na buwan bago pumasa sa road test.","p":"Tama. Anim na buwan ng binabantayang pagmamaneho muna."},"ar":{"q":"في New Jersey، كم من الوقت يجب على حامل التصريح الذي عمره أقل من 21 سنة أن يقود مع شخص بالغ مشرف فقط قبل اختبار الطريق؟","o":["6 أشهر على الأقل","شهر واحد على الأقل","سنتان على الأقل","لا توجد مدة محددة"],"h1":"إنها نصف سنة.","h2":"في New Jersey يجب على حامل التصريح الذي عمره أقل من 21 سنة أن يقود مع شخص بالغ مشرف ستة أشهر على الأقل قبل أن ينجح في اختبار الطريق.","p":"صحيح. ستة أشهر من القيادة تحت الإشراف أولًا."},"ref":{"doc":"NJ","page":15}},{"id":"nj-009","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, between which hours may a probationary driver under 21 not drive?","o":["10:00 p.m. to 6:00 a.m.","11:01 p.m. to 5:00 a.m.","Midnight to 4:00 a.m.","9:00 p.m. to 5:00 a.m."],"h1":"It starts just after eleven at night.","h2":"In New Jersey a probationary driver under 21 may not drive from 11:01 p.m. to 5:00 a.m., unless they carry a letter showing they must drive then for work or religion.","p":"Right. No driving from 11:01 p.m. to 5:00 a.m."},"es":{"q":"En New Jersey, ¿entre qué horas no puede manejar un conductor con licencia probatoria menor de 21 años?","o":["10:00 p.m. a 6:00 a.m.","11:01 p.m. a 5:00 a.m.","Medianoche a 4:00 a.m.","9:00 p.m. a 5:00 a.m."],"h1":"Empieza justo después de las once de la noche.","h2":"En New Jersey un conductor con licencia probatoria menor de 21 años no puede manejar de 11:01 p.m. a 5:00 a.m., a menos que lleve una carta que muestre que debe manejar a esa hora por trabajo o por religión.","p":"Correcto. No se maneja de 11:01 p.m. a 5:00 a.m."},"zh":{"q":"在 New Jersey，未满 21 岁的试用驾照（probationary license）司机在哪个时间段不能开车？","o":["晚上 10:00 到早上 6:00","晚上 11:01 到早上 5:00","午夜到凌晨 4:00","晚上 9:00 到早上 5:00"],"h1":"它从晚上十一点刚过开始。","h2":"在 New Jersey，未满 21 岁的试用驾照司机从晚上 11:01 到早上 5:00 不能开车，除非带着一封信，证明因为工作或宗教必须在这个时间开车。","p":"对。晚上 11:01 到早上 5:00 不能开车。"},"vi":{"q":"Ở New Jersey, người lái xe tạm thời (probationary driver) dưới 21 tuổi không được lái xe trong khoảng giờ nào?","o":["10:00 p.m. đến 6:00 a.m.","11:01 p.m. đến 5:00 a.m.","Nửa đêm đến 4:00 a.m.","9:00 p.m. đến 5:00 a.m."],"h1":"Bắt đầu ngay sau mười một giờ đêm.","h2":"Ở New Jersey, người lái xe tạm thời dưới 21 tuổi không được lái xe từ 11:01 p.m. đến 5:00 a.m., trừ khi họ mang theo một lá thư cho thấy họ phải lái xe vào giờ đó vì công việc hoặc tôn giáo.","p":"Đúng. Không lái xe từ 11:01 p.m. đến 5:00 a.m."},"tl":{"q":"Sa New Jersey, sa pagitan ng anong mga oras bawal magmaneho ang probationary driver na wala pang 21 taong gulang?","o":["10:00 p.m. hanggang 6:00 a.m.","11:01 p.m. hanggang 5:00 a.m.","Hatinggabi hanggang 4:00 a.m.","9:00 p.m. hanggang 5:00 a.m."],"h1":"Nagsisimula ito pagkalipas lang ng alas-onse ng gabi.","h2":"Sa New Jersey, ang probationary driver na wala pang 21 taong gulang ay hindi puwedeng magmaneho mula 11:01 p.m. hanggang 5:00 a.m., maliban kung may dala siyang sulat na nagpapakitang kailangan niyang magmaneho sa oras na iyon dahil sa trabaho o relihiyon.","p":"Tama. Bawal magmaneho mula 11:01 p.m. hanggang 5:00 a.m."},"ar":{"q":"في New Jersey، في أي ساعات لا يجوز للسائق تحت الاختبار (probationary driver) الذي عمره أقل من 21 سنة أن يقود؟","o":["من 10:00 p.m. إلى 6:00 a.m.","من 11:01 p.m. إلى 5:00 a.m.","من منتصف الليل إلى 4:00 a.m.","من 9:00 p.m. إلى 5:00 a.m."],"h1":"تبدأ بعد الساعة الحادية عشرة ليلًا مباشرة.","h2":"في New Jersey لا يجوز للسائق تحت الاختبار الذي عمره أقل من 21 سنة أن يقود من 11:01 p.m. إلى 5:00 a.m.، إلا إذا كان يحمل رسالة تُظهر أنه يجب أن يقود في هذا الوقت بسبب العمل أو الدين.","p":"صحيح. لا قيادة من 11:01 p.m. إلى 5:00 a.m."},"ref":{"doc":"NJ","page":18}},{"id":"nj-010","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, how many passengers may a probationary driver under 21 carry when no parent or guardian is in the car?","o":["None","Two","Three","One, plus the driver's own dependents"],"h1":"The driver's own dependents do not count.","h2":"A New Jersey probationary driver under 21 may carry only one passenger, plus the driver's own dependents, unless a parent or guardian is in the car.","p":"Right. One passenger, plus the driver's dependents."},"es":{"q":"En New Jersey, ¿cuántos pasajeros puede llevar un conductor con licencia probatoria menor de 21 años si no va un padre o tutor en el carro?","o":["Ninguno","Dos","Tres","Uno, más los dependientes del conductor"],"h1":"Los dependientes del propio conductor no cuentan.","h2":"Un conductor con licencia probatoria menor de 21 años en New Jersey solo puede llevar un pasajero, más sus propios dependientes, a menos que vaya un padre o tutor en el carro.","p":"Correcto. Un pasajero, más los dependientes del conductor."},"zh":{"q":"在 New Jersey，车里没有父母或监护人时，未满 21 岁的试用驾照司机可以载几位乘客？","o":["一位也不行","两位","三位","一位，再加上司机自己的家属（受抚养人）"],"h1":"司机自己的受抚养人不算在内。","h2":"New Jersey 未满 21 岁的试用驾照司机只能载一位乘客，再加上自己的受抚养人，除非车里有父母或监护人。","p":"对。一位乘客，再加上司机的受抚养人。"},"vi":{"q":"Ở New Jersey, người lái xe tạm thời (probationary driver) dưới 21 tuổi được chở bao nhiêu hành khách khi không có cha mẹ hoặc người giám hộ trong xe?","o":["Không ai","Hai người","Ba người","Một người, cộng thêm những người phụ thuộc của chính người lái"],"h1":"Những người phụ thuộc của chính người lái không bị tính.","h2":"Ở New Jersey, người lái xe tạm thời dưới 21 tuổi chỉ được chở một hành khách, cộng thêm những người phụ thuộc của chính người lái, trừ khi có cha mẹ hoặc người giám hộ trong xe.","p":"Đúng. Một hành khách, cộng thêm những người phụ thuộc của người lái."},"tl":{"q":"Sa New Jersey, ilang pasahero ang puwedeng isakay ng probationary driver na wala pang 21 taong gulang kapag walang magulang o guardian sa kotse?","o":["Wala","Dalawa","Tatlo","Isa, dagdag ang sariling mga dependent ng driver"],"h1":"Hindi binibilang ang sariling mga dependent ng driver.","h2":"Ang probationary driver sa New Jersey na wala pang 21 taong gulang ay puwedeng magsakay ng isang pasahero lamang, dagdag ang sariling mga dependent ng driver, maliban kung may magulang o guardian sa kotse.","p":"Tama. Isang pasahero, dagdag ang mga dependent ng driver."},"ar":{"q":"في New Jersey، كم راكبًا يجوز للسائق تحت الاختبار (probationary driver) الذي عمره أقل من 21 سنة أن يحمل عندما لا يكون أحد الوالدين أو الوصي في السيارة؟","o":["لا أحد","اثنان","ثلاثة","واحد، بالإضافة إلى المُعالين التابعين للسائق نفسه"],"h1":"المُعالون التابعون للسائق نفسه لا يُحسبون.","h2":"في New Jersey يجوز للسائق تحت الاختبار الذي عمره أقل من 21 سنة أن يحمل راكبًا واحدًا فقط، بالإضافة إلى المُعالين التابعين له، إلا إذا كان أحد الوالدين أو الوصي في السيارة.","p":"صحيح. راكب واحد، بالإضافة إلى المُعالين التابعين للسائق."},"ref":{"doc":"NJ","page":18}},{"id":"nj-011","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, may a probationary driver use a hands-free phone while driving?","o":["No, hand-held and hands-free are both banned","Yes, hands-free is allowed","Yes, but only at red lights","Yes, if the call is short"],"h1":"The rule for new drivers covers every kind of phone use.","h2":"A New Jersey probationary driver may not use any wireless device while driving, hand-held or hands-free.","p":"Right. No phone at all for probationary drivers."},"es":{"q":"En New Jersey, ¿puede un conductor con licencia probatoria usar un teléfono manos libres mientras maneja?","o":["No, están prohibidos el teléfono en la mano y el manos libres","Sí, el manos libres está permitido","Sí, pero solo en semáforos en rojo","Sí, si la llamada es corta"],"h1":"La regla para conductores nuevos cubre todo uso del teléfono.","h2":"Un conductor con licencia probatoria en New Jersey no puede usar ningún aparato inalámbrico mientras maneja, ni en la mano ni con manos libres.","p":"Correcto. Nada de teléfono para conductores con licencia probatoria."},"zh":{"q":"在 New Jersey，试用驾照司机开车时可以用免提电话吗？","o":["不可以，手持和免提都禁止","可以，免提是允许的","可以，但只能在红灯时","可以，如果通话很短"],"h1":"新司机的规定包括所有用手机的方式。","h2":"New Jersey 的试用驾照司机开车时不能用任何无线设备，手持和免提都不行。","p":"对。试用驾照司机完全不能用手机。"},"vi":{"q":"Ở New Jersey, người lái xe tạm thời (probationary driver) có được dùng điện thoại rảnh tay khi lái xe không?","o":["Không, cả cầm tay và rảnh tay đều bị cấm","Có, được dùng rảnh tay","Có, nhưng chỉ khi dừng đèn đỏ","Có, nếu cuộc gọi ngắn"],"h1":"Luật cho người mới lái xe áp dụng cho mọi cách dùng điện thoại.","h2":"Ở New Jersey, người lái xe tạm thời không được dùng bất kỳ thiết bị không dây nào khi lái xe, dù cầm tay hay rảnh tay.","p":"Đúng. Người lái xe tạm thời không được dùng điện thoại chút nào."},"tl":{"q":"Sa New Jersey, puwede bang gumamit ng hands-free na telepono ang probationary driver habang nagmamaneho?","o":["Hindi, bawal ang hand-held at hands-free","Oo, puwede ang hands-free","Oo, pero sa red light lamang","Oo, kung maikli ang tawag"],"h1":"Sakop ng patakaran para sa mga bagong driver ang lahat ng uri ng paggamit ng telepono.","h2":"Ang probationary driver sa New Jersey ay hindi puwedeng gumamit ng kahit anong wireless device habang nagmamaneho, hand-held man o hands-free.","p":"Tama. Walang telepono para sa mga probationary driver."},"ar":{"q":"في New Jersey، هل يجوز للسائق تحت الاختبار (probationary driver) أن يستخدم هاتفًا بدون يدين (hands-free) أثناء القيادة؟","o":["لا، الهاتف المحمول باليد والهاتف بدون يدين ممنوعان كلاهما","نعم، الهاتف بدون يدين مسموح","نعم، ولكن فقط عند الإشارة الحمراء","نعم، إذا كانت المكالمة قصيرة"],"h1":"القاعدة للسائقين الجدد تشمل كل أنواع استخدام الهاتف.","h2":"في New Jersey لا يجوز للسائق تحت الاختبار أن يستخدم أي جهاز لاسلكي أثناء القيادة، سواء كان محمولًا باليد أو بدون يدين.","p":"صحيح. لا هاتف أبدًا للسائقين تحت الاختبار."},"ref":{"doc":"NJ","page":86}},{"id":"nj-012","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, how many reflective decals must a permit or probationary driver under 21 display on the vehicle?","o":["None","One","Two","Four"],"h1":"It is more than one but fewer than three.","h2":"A New Jersey permit or probationary driver under 21 must display two red reflective decals, one on the front license plate and one on the rear plate.","p":"Right. Two decals are displayed."},"es":{"q":"En New Jersey, ¿cuántas calcomanías reflectantes debe mostrar en el vehículo un conductor con permiso o licencia probatoria menor de 21 años?","o":["Ninguna","Una","Dos","Cuatro"],"h1":"Es más de una pero menos de tres.","h2":"En New Jersey, un conductor con permiso o licencia probatoria menor de 21 años debe mostrar dos calcomanías rojas reflectantes, una en la placa delantera y otra en la placa trasera.","p":"Correcto. Se muestran dos calcomanías."},"zh":{"q":"在 New Jersey，未满 21 岁的学习驾照或试用驾照司机必须在车上贴几张反光贴纸（decal）？","o":["不用贴","一张","两张","四张"],"h1":"它比一多，但比三少。","h2":"New Jersey 未满 21 岁的学习驾照或试用驾照司机必须贴两张红色反光贴纸，一张在前车牌上，一张在后车牌上。","p":"对。要贴两张贴纸。"},"vi":{"q":"Ở New Jersey, người có giấy phép tập lái hoặc người lái xe tạm thời dưới 21 tuổi phải dán bao nhiêu miếng dán phản quang (decal) trên xe?","o":["Không có","Một","Hai","Bốn"],"h1":"Nhiều hơn một nhưng ít hơn ba.","h2":"Ở New Jersey, người có giấy phép tập lái hoặc người lái xe tạm thời dưới 21 tuổi phải dán hai miếng dán phản quang màu đỏ, một miếng trên biển số trước và một miếng trên biển số sau.","p":"Đúng. Phải dán hai miếng dán."},"tl":{"q":"Sa New Jersey, ilang reflective decal ang dapat ilagay sa sasakyan ng may permit o probationary driver na wala pang 21 taong gulang?","o":["Wala","Isa","Dalawa","Apat"],"h1":"Higit ito sa isa pero kulang sa tatlo.","h2":"Ang may permit o probationary driver sa New Jersey na wala pang 21 taong gulang ay dapat maglagay ng dalawang pulang reflective decal, isa sa plaka sa harap at isa sa plaka sa likod.","p":"Tama. Dalawang decal ang inilalagay."},"ar":{"q":"في New Jersey، كم ملصقًا عاكسًا (decal) يجب أن يضع حامل التصريح أو السائق تحت الاختبار الذي عمره أقل من 21 سنة على السيارة؟","o":["لا شيء","واحد","اثنان","أربعة"],"h1":"أكثر من واحد وأقل من ثلاثة.","h2":"في New Jersey يجب على حامل التصريح أو السائق تحت الاختبار الذي عمره أقل من 21 سنة أن يضع ملصقين عاكسين باللون الأحمر، واحدًا على لوحة الأرقام الأمامية وواحدًا على لوحة الأرقام الخلفية.","p":"صحيح. يوضع ملصقان."},"ref":{"doc":"NJ","page":19}},{"id":"nj-013","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, what is the fine for a permit or probationary driver under 21 who drives without the required decals?","o":["$25","$100","$500","There is no fine"],"h1":"It is a round number with three digits.","h2":"In New Jersey, breaking a graduated license rule, such as driving without the required decals, can bring a $100 fine.","p":"Right. Missing decals can cost $100."},"es":{"q":"En New Jersey, ¿cuál es la multa para un conductor con permiso o licencia probatoria menor de 21 años que maneja sin las calcomanías obligatorias?","o":["$25","$100","$500","No hay multa"],"h1":"Es un número redondo de tres cifras.","h2":"En New Jersey, no cumplir una regla de la licencia gradual, como manejar sin las calcomanías obligatorias, puede costar una multa de $100.","p":"Correcto. No llevar las calcomanías puede costar $100."},"zh":{"q":"在 New Jersey，未满 21 岁的学习驾照或试用驾照司机没贴规定的贴纸开车，罚款多少？","o":["$25","$100","$500","不罚款"],"h1":"它是一个整数，有三位数。","h2":"在 New Jersey，违反分级驾照的规定，比如没贴规定的贴纸开车，可能被罚 $100。","p":"对。没贴贴纸可能被罚 $100。"},"vi":{"q":"Ở New Jersey, người có giấy phép tập lái hoặc người lái xe tạm thời dưới 21 tuổi lái xe mà không có miếng dán bắt buộc sẽ bị phạt bao nhiêu?","o":["$25","$100","$500","Không bị phạt"],"h1":"Đó là một số tròn có ba chữ số.","h2":"Ở New Jersey, vi phạm luật bằng lái theo từng giai đoạn, chẳng hạn như lái xe không có miếng dán bắt buộc, có thể bị phạt $100.","p":"Đúng. Thiếu miếng dán có thể bị phạt $100."},"tl":{"q":"Sa New Jersey, magkano ang multa para sa may permit o probationary driver na wala pang 21 taong gulang na nagmamaneho nang walang kailangang decal?","o":["$25","$100","$500","Walang multa"],"h1":"Ito ay buong numero na may tatlong digit.","h2":"Sa New Jersey, ang paglabag sa patakaran ng graduated license, gaya ng pagmamaneho nang walang kailangang decal, ay puwedeng magresulta sa multang $100.","p":"Tama. Ang kulang na decal ay puwedeng magkahalaga ng $100."},"ar":{"q":"في New Jersey، ما الغرامة على حامل التصريح أو السائق تحت الاختبار الذي عمره أقل من 21 سنة إذا قاد دون الملصقات المطلوبة؟","o":["$25","$100","$500","لا توجد غرامة"],"h1":"إنه رقم مستدير من ثلاث خانات.","h2":"في New Jersey، مخالفة قواعد الرخصة المتدرجة، مثل القيادة دون الملصقات المطلوبة، قد تؤدي إلى غرامة قدرها $100.","p":"صحيح. غياب الملصقات قد يكلّف $100."},"ref":{"doc":"NJ","page":14}},{"id":"nj-014","scope":"NJ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Jersey, what is the fine range for a first offense of using a hand-held phone while driving?","o":["$25 to $50","$50 to $100","$1,000 to $2,000","$200 to $400"],"h1":"It starts at two hundred dollars.","h2":"A first offense for using a hand-held phone while driving in New Jersey carries a fine of $200 to $400.","p":"Right. A first offense costs $200 to $400."},"es":{"q":"En New Jersey, ¿cuál es el rango de la multa por una primera vez de usar el teléfono en la mano mientras maneja?","o":["$25 a $50","$50 a $100","$1,000 a $2,000","$200 a $400"],"h1":"Empieza en doscientos dólares.","h2":"Una primera infracción por usar el teléfono en la mano mientras maneja en New Jersey tiene una multa de $200 a $400.","p":"Correcto. Una primera infracción cuesta de $200 a $400."},"zh":{"q":"在 New Jersey，第一次因为开车时用手持手机被抓，罚款范围是多少？","o":["$25 到 $50","$50 到 $100","$1,000 到 $2,000","$200 到 $400"],"h1":"它从两百美元开始。","h2":"在 New Jersey，第一次因为开车时用手持手机被抓，罚款 $200 到 $400。","p":"对。第一次罚 $200 到 $400。"},"vi":{"q":"Ở New Jersey, mức phạt cho lần vi phạm đầu tiên vì dùng điện thoại cầm tay khi lái xe là bao nhiêu?","o":["$25 đến $50","$50 đến $100","$1,000 đến $2,000","$200 đến $400"],"h1":"Bắt đầu từ hai trăm đô la.","h2":"Ở New Jersey, lần vi phạm đầu tiên vì dùng điện thoại cầm tay khi lái xe bị phạt từ $200 đến $400.","p":"Đúng. Lần vi phạm đầu tiên bị phạt $200 đến $400."},"tl":{"q":"Sa New Jersey, magkano ang multa sa unang paglabag sa paggamit ng hand-held na telepono habang nagmamaneho?","o":["$25 hanggang $50","$50 hanggang $100","$1,000 hanggang $2,000","$200 hanggang $400"],"h1":"Nagsisimula ito sa dalawang daang dolyar.","h2":"Ang unang paglabag sa paggamit ng hand-held na telepono habang nagmamaneho sa New Jersey ay may multang $200 hanggang $400.","p":"Tama. Ang unang paglabag ay $200 hanggang $400."},"ar":{"q":"في New Jersey، ما مقدار الغرامة على المخالفة الأولى لاستخدام هاتف محمول باليد أثناء القيادة؟","o":["من $25 إلى $50","من $50 إلى $100","من $1,000 إلى $2,000","من $200 إلى $400"],"h1":"تبدأ من مئتي دولار.","h2":"في New Jersey، المخالفة الأولى لاستخدام هاتف محمول باليد أثناء القيادة عليها غرامة من $200 إلى $400.","p":"صحيح. المخالفة الأولى تكلّف من $200 إلى $400."},"ref":{"doc":"NJ","page":86}},{"id":"nj-015","scope":"NJ","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New Jersey, you are on the opposite side of a highway divided by a raised median from a stopped school bus. What must you do?","o":["Stop until the bus moves","Keep your normal speed","Slow to no more than 10 mph while passing","Honk and pass"],"h1":"You do not have to stop, but you must go very slowly.","h2":"In New Jersey, if a safety island or raised median separates you from a stopped school bus on the other side, you must slow to no more than 10 miles per hour while passing.","p":"Right. Slow to 10 mph or less."},"es":{"q":"En New Jersey, usted va por el lado opuesto de una carretera dividida por un camellón elevado y hay un autobús escolar detenido. ¿Qué debe hacer?","o":["Detenerse hasta que el autobús avance","Mantener su velocidad normal","Bajar a no más de 10 mph al pasar","Tocar el claxon y pasar"],"h1":"No tiene que detenerse, pero debe ir muy despacio.","h2":"En New Jersey, si una isla de seguridad o un camellón elevado lo separa de un autobús escolar detenido del otro lado, usted debe bajar a no más de 10 millas por hora al pasar.","p":"Correcto. Baje a 10 mph o menos."},"zh":{"q":"在 New Jersey，你在一条有凸起中间隔离带的公路上，校车停在对面。你必须怎么做？","o":["停车，等到校车开走","保持正常速度","经过时减速到不超过 10 mph","按喇叭然后超过去"],"h1":"你不用停车，但必须开得很慢。","h2":"在 New Jersey，如果安全岛或凸起的中间隔离带把你和对面停着的校车分开，你经过时必须减速到每小时不超过 10 英里。","p":"对。减速到 10 mph 或更低。"},"vi":{"q":"Ở New Jersey, bạn đang ở phía bên kia của một xa lộ có dải phân cách nhô cao, đối diện một xe buýt trường học đang dừng. Bạn phải làm gì?","o":["Dừng lại cho đến khi xe buýt chạy","Giữ tốc độ bình thường","Chạy chậm lại không quá 10 mph khi đi qua","Bấm còi rồi chạy qua"],"h1":"Bạn không phải dừng, nhưng phải chạy thật chậm.","h2":"Ở New Jersey, nếu có đảo an toàn hoặc dải phân cách nhô cao ngăn cách bạn với xe buýt trường học đang dừng ở phía bên kia, bạn phải chạy chậm lại không quá 10 dặm một giờ khi đi qua.","p":"Đúng. Chạy chậm lại 10 mph hoặc thấp hơn."},"tl":{"q":"Sa New Jersey, nasa kabilang panig ka ng highway na hinahati ng nakataas na median mula sa isang nakahintong school bus. Ano ang dapat mong gawin?","o":["Huminto hanggang umandar ang bus","Panatilihin ang karaniwang bilis","Bumagal sa hindi hihigit sa 10 mph habang dumadaan","Bumusina at lumampas"],"h1":"Hindi mo kailangang huminto, pero dapat napakabagal mo.","h2":"Sa New Jersey, kung may safety island o nakataas na median na naghihiwalay sa iyo at sa nakahintong school bus sa kabilang panig, dapat kang bumagal sa hindi hihigit sa 10 milya kada oras habang dumadaan.","p":"Tama. Bumagal sa 10 mph o mas mababa."},"ar":{"q":"في New Jersey، أنت على الجانب المقابل لطريق سريع مقسوم بفاصل مرتفع، وفي الجانب الآخر حافلة مدرسية متوقفة. ماذا يجب أن تفعل؟","o":["تتوقف حتى تتحرك الحافلة","تحافظ على سرعتك العادية","تُبطئ إلى 10 mph أو أقل أثناء المرور","تستخدم البوق وتمرّ"],"h1":"ليس عليك أن تتوقف، لكن يجب أن تسير ببطء شديد.","h2":"في New Jersey، إذا كانت جزيرة أمان أو فاصل مرتفع يفصلك عن حافلة مدرسية متوقفة في الجانب الآخر، يجب أن تُبطئ إلى 10 أميال في الساعة أو أقل أثناء المرور.","p":"صحيح. أبطئ إلى 10 mph أو أقل."},"ref":{"doc":"NJ","page":77}},{"id":"nj-016","scope":"NJ","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Jersey, when may you drive in the left lane of a multi-lane highway?","o":["When passing or turning left","Whenever you like","Only at night","Only when going the speed limit"],"h1":"New Jersey has a keep right law.","h2":"New Jersey law says to keep to the right lane and use the left lane only to pass another vehicle or to turn left.","p":"Right. Keep right, and pass on the left."},"es":{"q":"En New Jersey, ¿cuándo puede manejar en el carril izquierdo de una carretera de varios carriles?","o":["Cuando rebasa o va a dar vuelta a la izquierda","Siempre que quiera","Solo de noche","Solo si va al límite de velocidad"],"h1":"New Jersey tiene una ley de mantenerse a la derecha.","h2":"La ley de New Jersey dice que debe mantenerse en el carril derecho y usar el carril izquierdo solo para rebasar a otro vehículo o para dar vuelta a la izquierda.","p":"Correcto. Manténgase a la derecha y rebase por la izquierda."},"zh":{"q":"在 New Jersey，在多车道的公路上，什么时候可以走左车道？","o":["超车或左转时","想走就走","只在晚上","只在开到限速时"],"h1":"New Jersey 有靠右行驶的法律。","h2":"New Jersey 法律规定要走右车道，只有超车或左转时才走左车道。","p":"对。靠右行驶，从左边超车。"},"vi":{"q":"Ở New Jersey, khi nào bạn được lái xe ở làn bên trái của xa lộ có nhiều làn?","o":["Khi vượt xe hoặc khi rẽ trái","Bất cứ khi nào bạn muốn","Chỉ vào ban đêm","Chỉ khi chạy đúng tốc độ giới hạn"],"h1":"New Jersey có luật đi bên phải (keep right law).","h2":"Luật New Jersey nói phải đi ở làn bên phải và chỉ dùng làn bên trái để vượt xe khác hoặc để rẽ trái.","p":"Đúng. Đi bên phải, và vượt bên trái."},"tl":{"q":"Sa New Jersey, kailan ka puwedeng magmaneho sa kaliwang lane ng highway na maraming lane?","o":["Kapag lumalampas o kumakaliwa","Kahit kailan mo gusto","Sa gabi lamang","Kapag nasa speed limit lamang"],"h1":"May keep right law ang New Jersey.","h2":"Sinasabi ng batas ng New Jersey na manatili sa kanang lane at gamitin ang kaliwang lane para lamang lumampas sa ibang sasakyan o para kumaliwa.","p":"Tama. Manatili sa kanan, at lumampas sa kaliwa."},"ar":{"q":"في New Jersey، متى يجوز لك أن تقود في المسار الأيسر لطريق سريع متعدد المسارات؟","o":["عند التجاوز أو الانعطاف يسارًا","في أي وقت تريده","في الليل فقط","فقط عند السير بالسرعة القصوى المسموحة"],"h1":"في New Jersey قانون البقاء في اليمين (keep right law).","h2":"قانون New Jersey يقول أن تبقى في المسار الأيمن وأن تستخدم المسار الأيسر فقط لتجاوز مركبة أخرى أو للانعطاف يسارًا.","p":"صحيح. ابقَ في اليمين، وتجاوز من اليسار."},"ref":{"doc":"NJ","page":65}},{"id":"nj-017","scope":"NJ","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Jersey, what is the fine range for breaking the Move Over law?","o":["$25 to $50","$100 to $500","$1,000 to $5,000","There is only a warning"],"h1":"It starts at one hundred dollars.","h2":"Breaking the New Jersey Move Over law carries a fine of $100 to $500.","p":"Right. The fine is $100 to $500."},"es":{"q":"En New Jersey, ¿cuál es el rango de la multa por no cumplir la ley de \"Move Over\" (cambie de carril)?","o":["$25 a $50","$100 a $500","$1,000 a $5,000","Solo hay una advertencia"],"h1":"Empieza en cien dólares.","h2":"No cumplir la ley de \"Move Over\" en New Jersey tiene una multa de $100 a $500.","p":"Correcto. La multa es de $100 a $500."},"zh":{"q":"在 New Jersey，违反让道变道法（Move Over law）罚款范围是多少？","o":["$25 到 $50","$100 到 $500","$1,000 到 $5,000","只会警告"],"h1":"它从一百美元开始。","h2":"违反 New Jersey 的让道变道法（Move Over law），罚款 $100 到 $500。","p":"对。罚款是 $100 到 $500。"},"vi":{"q":"Ở New Jersey, mức phạt khi vi phạm luật Nhường Làn (Move Over law) là bao nhiêu?","o":["$25 đến $50","$100 đến $500","$1,000 đến $5,000","Chỉ bị cảnh cáo"],"h1":"Bắt đầu từ một trăm đô la.","h2":"Vi phạm luật Nhường Làn (Move Over law) của New Jersey bị phạt từ $100 đến $500.","p":"Đúng. Mức phạt là $100 đến $500."},"tl":{"q":"Sa New Jersey, magkano ang multa sa paglabag sa Move Over law?","o":["$25 hanggang $50","$100 hanggang $500","$1,000 hanggang $5,000","Babala lamang"],"h1":"Nagsisimula ito sa isang daang dolyar.","h2":"Ang paglabag sa Move Over law ng New Jersey ay may multang $100 hanggang $500.","p":"Tama. Ang multa ay $100 hanggang $500."},"ar":{"q":"في New Jersey، ما مقدار الغرامة على مخالفة قانون الابتعاد عن المركبات المتوقفة (Move Over law)؟","o":["من $25 إلى $50","من $100 إلى $500","من $1,000 إلى $5,000","يوجد تحذير فقط"],"h1":"تبدأ من مئة دولار.","h2":"مخالفة قانون الابتعاد عن المركبات المتوقفة (Move Over law) في New Jersey عليها غرامة من $100 إلى $500.","p":"صحيح. الغرامة من $100 إلى $500."},"ref":{"doc":"NJ","page":78}},{"id":"nj-018","scope":"NJ","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New Jersey, besides emergency, tow and road crew vehicles, what else does the Move Over law cover?","o":["Only parked school buses","Only police on foot","Nothing else","Disabled vehicles with their hazard lights on"],"h1":"A car with flashing hazard lights on the shoulder counts too.","h2":"The New Jersey Move Over law now also covers disabled vehicles that have their hazard lights on.","p":"Right. Disabled cars with hazard lights are covered."},"es":{"q":"En New Jersey, además de vehículos de emergencia, grúas y cuadrillas de carretera, ¿qué más cubre la ley de \"Move Over\"?","o":["Solo autobuses escolares estacionados","Solo policías a pie","Nada más","Vehículos descompuestos con las luces intermitentes encendidas"],"h1":"Un carro en el acotamiento con luces intermitentes también cuenta.","h2":"La ley de \"Move Over\" de New Jersey ahora también cubre vehículos descompuestos que tienen las luces intermitentes encendidas.","p":"Correcto. Los carros descompuestos con luces intermitentes están cubiertos."},"zh":{"q":"在 New Jersey，除了紧急车辆、拖车和道路工程车，让道变道法（Move Over law）还包括什么？","o":["只有停着的校车","只有步行的警察","没有别的","开着危险警示灯的故障车"],"h1":"路肩上闪着危险警示灯的车也算。","h2":"New Jersey 的让道变道法（Move Over law）现在也包括开着危险警示灯的故障车。","p":"对。开着危险警示灯的故障车也包括在内。"},"vi":{"q":"Ở New Jersey, ngoài xe khẩn cấp, xe kéo và xe của đội làm đường, luật Nhường Làn (Move Over law) còn áp dụng cho gì nữa?","o":["Chỉ xe buýt trường học đang đậu","Chỉ cảnh sát đi bộ","Không gì khác","Xe bị hư đang bật đèn cảnh báo nguy hiểm (hazard lights)"],"h1":"Một xe hơi nháy đèn cảnh báo nguy hiểm bên lề đường cũng được tính.","h2":"Luật Nhường Làn (Move Over law) của New Jersey nay cũng áp dụng cho xe bị hư đang bật đèn cảnh báo nguy hiểm.","p":"Đúng. Xe bị hư có bật đèn cảnh báo cũng được bảo vệ."},"tl":{"q":"Sa New Jersey, bukod sa mga emergency vehicle, tow truck at sasakyan ng road crew, ano pa ang sakop ng Move Over law?","o":["Mga nakaparadang school bus lamang","Mga pulis na naglalakad lamang","Wala nang iba","Mga sirang sasakyan na nakabukas ang hazard lights"],"h1":"Kasama rin ang kotse sa gilid ng daan na kumikislap ang hazard lights.","h2":"Sakop na rin ng Move Over law ng New Jersey ang mga sirang sasakyan na nakabukas ang hazard lights.","p":"Tama. Sakop ang mga sirang kotse na may hazard lights."},"ar":{"q":"في New Jersey، إلى جانب مركبات الطوارئ وشاحنات السحب ومركبات عمّال الطرق، ماذا يشمل أيضًا قانون الابتعاد عن المركبات المتوقفة (Move Over law)؟","o":["الحافلات المدرسية المتوقفة فقط","الشرطة الذين يسيرون على الأقدام فقط","لا شيء آخر","المركبات المعطّلة التي أضواء التحذير (hazard lights) فيها مشتعلة"],"h1":"السيارة على جانب الطريق التي تومض أضواء التحذير فيها تُحسب أيضًا.","h2":"قانون الابتعاد عن المركبات المتوقفة (Move Over law) في New Jersey يشمل الآن أيضًا المركبات المعطّلة التي أضواء التحذير فيها مشتعلة.","p":"صحيح. السيارات المعطّلة ذات أضواء التحذير مشمولة."},"ref":{"doc":"NJ","page":78}},{"id":"nj-019","scope":"NJ","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New Jersey, you pass a person walking or biking on the road and cannot change lanes or leave 4 feet. What must you do?","o":["Honk and pass quickly","Pass at the posted speed","Slow to 25 mph and be ready to stop","Stop and wait for them to leave the road"],"h1":"There is a set speed for this case.","h2":"In New Jersey, if you cannot change lanes or leave 4 feet when passing a pedestrian or bicyclist, you must slow to 25 miles per hour and be ready to stop.","p":"Right. Slow to 25 mph and be ready to stop."},"es":{"q":"En New Jersey, usted va a rebasar a una persona que camina o va en bicicleta por la calle y no puede cambiar de carril ni dejar 4 pies. ¿Qué debe hacer?","o":["Tocar el claxon y pasar rápido","Pasar al límite de velocidad","Bajar a 25 mph y estar listo para detenerse","Detenerse y esperar a que salga de la calle"],"h1":"Hay una velocidad fija para este caso.","h2":"En New Jersey, si no puede cambiar de carril ni dejar 4 pies al rebasar a un peatón o ciclista, debe bajar a 25 millas por hora y estar listo para detenerse.","p":"Correcto. Baje a 25 mph y esté listo para detenerse."},"zh":{"q":"在 New Jersey，你要经过路上走路或骑自行车的人，但不能换车道，也不能留出 4 英尺。你必须怎么做？","o":["按喇叭然后快速超过去","按标示的限速超过去","减速到 25 mph，并准备好停车","停车，等他们离开道路"],"h1":"这种情况有规定的速度。","h2":"在 New Jersey，经过行人或骑自行车的人时，如果不能换车道或留出 4 英尺，你必须减速到每小时 25 英里，并准备好停车。","p":"对。减速到 25 mph，并准备好停车。"},"vi":{"q":"Ở New Jersey, bạn đang vượt qua một người đi bộ hoặc đi xe đạp trên đường và không thể chuyển làn hoặc chừa khoảng cách 4 feet. Bạn phải làm gì?","o":["Bấm còi và vượt qua thật nhanh","Vượt qua với tốc độ giới hạn được ghi","Chạy chậm lại 25 mph và sẵn sàng dừng lại","Dừng lại và chờ họ rời khỏi đường"],"h1":"Có một tốc độ quy định cho trường hợp này.","h2":"Ở New Jersey, nếu bạn không thể chuyển làn hoặc chừa 4 feet khi vượt qua người đi bộ hoặc người đi xe đạp, bạn phải chạy chậm lại 25 dặm một giờ và sẵn sàng dừng lại.","p":"Đúng. Chạy chậm lại 25 mph và sẵn sàng dừng lại."},"tl":{"q":"Sa New Jersey, nilalampasan mo ang taong naglalakad o nagbibisikleta sa daan at hindi ka makalipat ng lane o makapag-iwan ng 4 feet. Ano ang dapat mong gawin?","o":["Bumusina at lumampas nang mabilis","Lumampas sa nakapaskil na bilis","Bumagal sa 25 mph at maging handang huminto","Huminto at hintayin silang umalis sa daan"],"h1":"May takdang bilis para sa ganitong kaso.","h2":"Sa New Jersey, kung hindi ka makalipat ng lane o makapag-iwan ng 4 feet kapag nilalampasan mo ang naglalakad o nagbibisikleta, dapat kang bumagal sa 25 milya kada oras at maging handang huminto.","p":"Tama. Bumagal sa 25 mph at maging handang huminto."},"ar":{"q":"في New Jersey، أنت تتجاوز شخصًا يمشي أو يركب دراجة على الطريق، ولا تستطيع تغيير المسار أو ترك مسافة 4 feet. ماذا يجب أن تفعل؟","o":["تستخدم البوق وتتجاوز بسرعة","تتجاوز بالسرعة المكتوبة على اللافتة","تُبطئ إلى 25 mph وتكون مستعدًا للتوقف","تتوقف وتنتظر حتى يتركوا الطريق"],"h1":"توجد سرعة محددة لهذه الحالة.","h2":"في New Jersey، إذا لم تستطع تغيير المسار أو ترك مسافة 4 feet عند تجاوز شخص يمشي أو يركب دراجة، يجب أن تُبطئ إلى 25 ميلًا في الساعة وتكون مستعدًا للتوقف.","p":"صحيح. أبطئ إلى 25 mph وكن مستعدًا للتوقف."},"ref":{"doc":"NJ","page":150}},{"id":"nj-020","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, at what blood alcohol level can a driver under 21 be charged?","o":["0.01","0.05","0.08","0.10"],"h1":"Even a very small amount counts.","h2":"New Jersey has zero tolerance for drivers under 21, so a blood alcohol level of just 0.01 can lead to a charge.","p":"Right. Under 21, 0.01 is already too much."},"es":{"q":"En New Jersey, ¿con qué nivel de alcohol en la sangre se puede acusar a un conductor menor de 21 años?","o":["0.01","0.05","0.08","0.10"],"h1":"Incluso una cantidad muy pequeña cuenta.","h2":"New Jersey tiene tolerancia cero para conductores menores de 21 años, así que un nivel de alcohol en la sangre de apenas 0.01 puede llevar a una acusación.","p":"Correcto. Menor de 21, 0.01 ya es demasiado."},"zh":{"q":"在 New Jersey，未满 21 岁的司机血液酒精浓度到多少就可能被起诉？","o":["0.01","0.05","0.08","0.10"],"h1":"就算很少的量也算。","h2":"New Jersey 对未满 21 岁的司机零容忍，所以血液酒精浓度只有 0.01 也可能被起诉。","p":"对。未满 21 岁，0.01 就已经太多了。"},"vi":{"q":"Ở New Jersey, người lái xe dưới 21 tuổi có thể bị buộc tội khi nồng độ cồn trong máu ở mức nào?","o":["0.01","0.05","0.08","0.10"],"h1":"Ngay cả một lượng rất nhỏ cũng bị tính.","h2":"New Jersey không khoan nhượng với người lái xe dưới 21 tuổi, nên nồng độ cồn trong máu chỉ 0.01 cũng có thể bị buộc tội.","p":"Đúng. Dưới 21 tuổi, 0.01 đã là quá nhiều."},"tl":{"q":"Sa New Jersey, sa anong blood alcohol level puwedeng kasuhan ang driver na wala pang 21 taong gulang?","o":["0.01","0.05","0.08","0.10"],"h1":"Kahit napakaliit na dami ay binibilang.","h2":"May zero tolerance ang New Jersey para sa mga driver na wala pang 21 taong gulang, kaya ang blood alcohol level na 0.01 lamang ay puwedeng humantong sa kaso.","p":"Tama. Kung wala pang 21, sobra na ang 0.01."},"ar":{"q":"في New Jersey، عند أي نسبة كحول في الدم يمكن توجيه تهمة إلى سائق عمره أقل من 21 سنة؟","o":["0.01","0.05","0.08","0.10"],"h1":"حتى كمية صغيرة جدًا تُحسب.","h2":"في New Jersey لا تسامح أبدًا مع السائقين الذين أعمارهم أقل من 21 سنة، لذلك فإن نسبة كحول في الدم قدرها 0.01 فقط قد تؤدي إلى توجيه تهمة.","p":"صحيح. تحت 21 سنة، نسبة 0.01 كثيرة جدًا بالفعل."},"ref":{"doc":"NJ","page":115}},{"id":"nj-021","scope":"NJ","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Jersey, what is the speed limit on a rural road with no posted limit?","o":["35 mph","45 mph","50 mph","65 mph"],"h1":"It is lower than the limit on most interstates.","h2":"In New Jersey, the speed limit on a rural road with no speed limit sign is 50 mph.","p":"Right. Unposted rural roads have a 50 mph limit."},"es":{"q":"En New Jersey, ¿cuál es el límite de velocidad en una carretera rural sin límite señalizado?","o":["35 mph","45 mph","50 mph","65 mph"],"h1":"Es más bajo que el límite de la mayoría de las autopistas interestatales.","h2":"En New Jersey, el límite de velocidad en una carretera rural sin señal de límite es de 50 mph.","p":"Correcto. Las carreteras rurales sin señal tienen un límite de 50 mph."},"zh":{"q":"在 New Jersey，没有限速标志的乡村道路限速是多少？","o":["35 mph","45 mph","50 mph","65 mph"],"h1":"它比大多数州际公路的限速低。","h2":"在 New Jersey，没有限速标志的乡村道路限速是 50 mph。","p":"对。没有限速标志的乡村道路限速是 50 mph。"},"vi":{"q":"Ở New Jersey, tốc độ tối đa trên đường nông thôn không có biển báo tốc độ là bao nhiêu?","o":["35 mph","45 mph","50 mph","65 mph"],"h1":"Nó thấp hơn tốc độ tối đa trên hầu hết các xa lộ liên bang.","h2":"Ở New Jersey, tốc độ tối đa trên đường nông thôn không có biển báo tốc độ là 50 mph.","p":"Đúng. Đường nông thôn không có biển báo có tốc độ tối đa 50 mph."},"tl":{"q":"Sa New Jersey, ano ang speed limit sa daan sa probinsya na walang nakapaskil na limit?","o":["35 mph","45 mph","50 mph","65 mph"],"h1":"Mas mababa ito kaysa sa limit sa karamihan ng interstate.","h2":"Sa New Jersey, ang speed limit sa daan sa probinsya na walang speed limit sign ay 50 mph.","p":"Tama. 50 mph ang limit sa daan sa probinsya na walang nakapaskil na limit."},"ar":{"q":"في New Jersey، ما حد السرعة على طريق ريفي لا توجد عليه لافتة لحد السرعة؟","o":["35 mph","45 mph","50 mph","65 mph"],"h1":"إنه أقل من حد السرعة على معظم الطرق السريعة بين الولايات.","h2":"في New Jersey، حد السرعة على طريق ريفي لا توجد عليه لافتة لحد السرعة هو 50 mph.","p":"صحيح. حد السرعة على الطرق الريفية التي لا توجد عليها لافتة هو 50 mph."},"ref":{"doc":"NJ","page":62}},{"id":"nj-022","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, you must turn on your headlights when you can see only how far ahead?","o":["500 feet or less","1,000 feet or less","200 feet or less","1 mile or less"],"h1":"It is about the length of one and a half football fields.","h2":"In New Jersey, you must use your headlights when you can see 500 feet or less ahead.","p":"Right. Headlights go on when you can see 500 feet or less."},"es":{"q":"En New Jersey, ¿debe encender las luces delanteras cuando solo puede ver hasta qué distancia?","o":["500 pies o menos","1,000 pies o menos","200 pies o menos","1 milla o menos"],"h1":"Es como un campo de fútbol americano y medio.","h2":"En New Jersey, usted debe usar las luces delanteras cuando puede ver 500 pies o menos hacia adelante.","p":"Correcto. Las luces se encienden cuando se ve a 500 pies o menos."},"zh":{"q":"在 New Jersey，当你只能看到前方多远时，必须打开车头灯？","o":["500 英尺或更短","1,000 英尺或更短","200 英尺或更短","1 英里或更短"],"h1":"大约是一个半足球场的长度。","h2":"在 New Jersey，当你只能看到前方 500 英尺或更短时，必须打开车头灯。","p":"对。能看到的距离只有 500 英尺或更短时，要打开车头灯。"},"vi":{"q":"Ở New Jersey, bạn phải bật đèn pha khi bạn chỉ nhìn thấy phía trước bao xa?","o":["500 feet hoặc ít hơn","1,000 feet hoặc ít hơn","200 feet hoặc ít hơn","1 dặm hoặc ít hơn"],"h1":"Nó dài khoảng một sân bóng bầu dục rưỡi.","h2":"Ở New Jersey, bạn phải bật đèn pha khi bạn chỉ nhìn thấy phía trước 500 feet hoặc ít hơn.","p":"Đúng. Bật đèn pha khi bạn chỉ nhìn thấy 500 feet hoặc ít hơn."},"tl":{"q":"Sa New Jersey, kailangan mong buksan ang headlights kapag gaano kalayo lang ang nakikita mo sa unahan?","o":["500 feet o mas maikli","1,000 feet o mas maikli","200 feet o mas maikli","1 milya o mas maikli"],"h1":"Mga isa't kalahating haba ng football field ito.","h2":"Sa New Jersey, kailangan mong gamitin ang headlights kapag 500 feet o mas maikli lang ang nakikita mo sa unahan.","p":"Tama. Buksan ang headlights kapag 500 feet o mas maikli lang ang nakikita mo."},"ar":{"q":"في New Jersey، يجب أن تشغّل المصابيح الأمامية عندما لا ترى أمامك إلا إلى أي مسافة؟","o":["500 قدم أو أقل","1,000 قدم أو أقل","200 قدم أو أقل","1 ميل أو أقل"],"h1":"إنها تقريبًا طول ملعب كرة قدم ونصف.","h2":"في New Jersey، يجب أن تستخدم المصابيح الأمامية عندما لا ترى أمامك إلا 500 قدم أو أقل.","p":"صحيح. شغّل المصابيح الأمامية عندما لا ترى إلا 500 قدم أو أقل."},"ref":{"doc":"NJ","page":83}},{"id":"nj-023","scope":"NJ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Jersey, a child is 6 years old and 50 inches tall. Where and how must the child ride?","o":["In the front seat with a seat belt","In any seat with only a lap belt","On an adult's lap in the back seat","In a rear seat, in a booster seat or harness car seat"],"h1":"Think of children under 8 who are shorter than 57 inches.","h2":"In New Jersey, a child under 8 who is shorter than 57 inches must ride in a rear seat in a booster seat or a car seat with a harness.","p":"Right. Under 8 and under 57 inches means a booster or harness seat in the back."},"es":{"q":"En New Jersey, un niño tiene 6 años y mide 50 pulgadas. ¿Dónde y cómo debe viajar?","o":["En el asiento delantero con cinturón","En cualquier asiento con solo el cinturón de cadera","En las piernas de un adulto en el asiento trasero","En un asiento trasero, en un asiento elevado o una silla con arnés"],"h1":"Piense en los niños menores de 8 años que miden menos de 57 pulgadas.","h2":"En New Jersey, un niño menor de 8 años que mide menos de 57 pulgadas debe viajar en un asiento trasero, en un asiento elevado o en una silla con arnés.","p":"Correcto. Menor de 8 años y de menos de 57 pulgadas: asiento elevado o silla con arnés atrás."},"zh":{"q":"在 New Jersey，一个孩子 6 岁，身高 50 英寸。这个孩子必须坐在哪里、怎样坐？","o":["坐前排，系安全带","坐任何座位，只系腰部安全带","在后排坐在大人腿上","坐后排，用增高座椅或带安全背带的儿童座椅"],"h1":"想一想不到 8 岁、身高不到 57 英寸的孩子。","h2":"在 New Jersey，不到 8 岁、身高不到 57 英寸的孩子必须坐在后排，使用增高座椅或带安全背带的儿童座椅。","p":"对。不到 8 岁、身高不到 57 英寸，就要在后排用增高座椅或带背带的座椅。"},"vi":{"q":"Ở New Jersey, một em bé 6 tuổi và cao 50 inch. Em phải ngồi ở đâu và ngồi như thế nào?","o":["Ngồi ghế trước, thắt dây an toàn","Ngồi ghế nào cũng được, chỉ với dây an toàn ngang hông","Ngồi trên đùi người lớn ở ghế sau","Ngồi ghế sau, trong ghế nâng (booster seat) hoặc ghế xe có dây đai"],"h1":"Hãy nghĩ đến trẻ dưới 8 tuổi và thấp hơn 57 inch.","h2":"Ở New Jersey, trẻ dưới 8 tuổi và thấp hơn 57 inch phải ngồi ở ghế sau, trong ghế nâng hoặc ghế xe có dây đai.","p":"Đúng. Dưới 8 tuổi và thấp hơn 57 inch thì phải ngồi ghế nâng hoặc ghế có dây đai ở phía sau."},"tl":{"q":"Sa New Jersey, ang isang bata ay 6 na taong gulang at 50 inches ang taas. Saan at paano dapat sumakay ang bata?","o":["Sa upuan sa harap, may seat belt","Sa kahit anong upuan, lap belt lang","Nakakandong sa matanda sa upuan sa likod","Sa upuan sa likod, sa booster seat o car seat na may harness"],"h1":"Isipin ang mga batang wala pang 8 taon na mas maikli sa 57 inches.","h2":"Sa New Jersey, ang batang wala pang 8 taon na mas maikli sa 57 inches ay dapat sumakay sa upuan sa likod, sa booster seat o car seat na may harness.","p":"Tama. Kapag wala pang 8 taon at mas maikli sa 57 inches, booster o harness seat sa likod."},"ar":{"q":"في New Jersey، طفل عمره 6 سنوات وطوله 50 بوصة. أين وكيف يجب أن يجلس؟","o":["في المقعد الأمامي مع حزام الأمان","في أي مقعد مع حزام الحِجر فقط","في حضن شخص بالغ في المقعد الخلفي","في مقعد خلفي، في مقعد رافع (booster seat) أو مقعد سيارة بأحزمة"],"h1":"فكّر في الأطفال الذين عمرهم أقل من 8 سنوات وطولهم أقل من 57 بوصة.","h2":"في New Jersey، الطفل الذي عمره أقل من 8 سنوات وطوله أقل من 57 بوصة يجب أن يجلس في مقعد خلفي، في مقعد رافع أو مقعد سيارة بأحزمة.","p":"صحيح. أقل من 8 سنوات وأقل من 57 بوصة يعني مقعدًا رافعًا أو مقعدًا بأحزمة في الخلف."},"ref":{"doc":"NJ","page":42}},{"id":"nj-024","scope":"NJ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Jersey, what is the fine for breaking the child passenger safety law?","o":["$10 to $25","$50 to $75","$200 to $400","$500 to $1,000"],"h1":"It is less than one hundred dollars, plus court costs.","h2":"In New Jersey, breaking the child car seat law can bring a fine of $50 to $75, plus fees and court costs.","p":"Right. The fine is $50 to $75, plus costs."},"es":{"q":"En New Jersey, ¿cuál es la multa por no cumplir la ley de seguridad de pasajeros infantiles?","o":["De $10 a $25","De $50 a $75","De $200 a $400","De $500 a $1,000"],"h1":"Es menos de cien dólares, más los costos del tribunal.","h2":"En New Jersey, no cumplir la ley de asientos de seguridad para niños puede costar una multa de $50 a $75, más cargos y costos del tribunal.","p":"Correcto. La multa es de $50 a $75, más los costos."},"zh":{"q":"在 New Jersey，违反儿童乘车安全法的罚款是多少？","o":["$10 到 $25","$50 到 $75","$200 到 $400","$500 到 $1,000"],"h1":"不到一百美元，另加法院费用。","h2":"在 New Jersey，违反儿童安全座椅法可被罚款 $50 到 $75，另加手续费和法院费用。","p":"对。罚款是 $50 到 $75，另加费用。"},"vi":{"q":"Ở New Jersey, tiền phạt khi vi phạm luật an toàn cho trẻ em đi xe là bao nhiêu?","o":["$10 đến $25","$50 đến $75","$200 đến $400","$500 đến $1,000"],"h1":"Nó dưới một trăm đô la, cộng thêm án phí.","h2":"Ở New Jersey, vi phạm luật ghế xe cho trẻ em có thể bị phạt $50 đến $75, cộng thêm lệ phí và án phí.","p":"Đúng. Tiền phạt là $50 đến $75, cộng thêm các khoản phí."},"tl":{"q":"Sa New Jersey, magkano ang multa sa paglabag sa batas sa kaligtasan ng batang pasahero?","o":["$10 hanggang $25","$50 hanggang $75","$200 hanggang $400","$500 hanggang $1,000"],"h1":"Mas mababa ito sa isang daang dolyar, dagdag ang gastos sa korte.","h2":"Sa New Jersey, ang paglabag sa batas sa car seat ng bata ay may multang $50 hanggang $75, dagdag ang mga bayarin at gastos sa korte.","p":"Tama. $50 hanggang $75 ang multa, dagdag ang mga gastos."},"ar":{"q":"في New Jersey، ما الغرامة على مخالفة قانون سلامة الأطفال الركاب؟","o":["من $10 إلى $25","من $50 إلى $75","من $200 إلى $400","من $500 إلى $1,000"],"h1":"إنها أقل من مئة دولار، بالإضافة إلى رسوم المحكمة.","h2":"في New Jersey، مخالفة قانون مقعد الطفل في السيارة قد تؤدي إلى غرامة من $50 إلى $75، بالإضافة إلى الرسوم وتكاليف المحكمة.","p":"صحيح. الغرامة من $50 إلى $75، بالإضافة إلى التكاليف."},"ref":{"doc":"NJ","page":43}},{"id":"nj-025","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, who is responsible when a passenger under 18 does not wear a seat belt?","o":["The driver","The passenger","The car's owner","The passenger's parent, even if not in the car"],"h1":"Think of the person behind the wheel.","h2":"In New Jersey, the driver is responsible for making sure every passenger under 18 wears a seat belt.","p":"Right. The driver answers for passengers under 18."},"es":{"q":"En New Jersey, ¿quién es responsable cuando un pasajero menor de 18 años no usa el cinturón de seguridad?","o":["El conductor","El pasajero","El dueño del auto","El padre o la madre del pasajero, aunque no esté en el auto"],"h1":"Piense en la persona que va al volante.","h2":"En New Jersey, el conductor es responsable de que cada pasajero menor de 18 años use el cinturón de seguridad.","p":"Correcto. El conductor responde por los pasajeros menores de 18 años."},"zh":{"q":"在 New Jersey，未满 18 岁的乘客没有系安全带时，由谁负责？","o":["司机","乘客","车主","乘客的父母，即使他们不在车上"],"h1":"想一想握方向盘的人。","h2":"在 New Jersey，司机有责任确保每位未满 18 岁的乘客都系好安全带。","p":"对。司机要为未满 18 岁的乘客负责。"},"vi":{"q":"Ở New Jersey, ai chịu trách nhiệm khi một hành khách dưới 18 tuổi không thắt dây an toàn?","o":["Người lái xe","Hành khách","Chủ xe","Cha mẹ của hành khách, dù không ở trong xe"],"h1":"Hãy nghĩ đến người cầm vô lăng.","h2":"Ở New Jersey, người lái xe có trách nhiệm bảo đảm mọi hành khách dưới 18 tuổi đều thắt dây an toàn.","p":"Đúng. Người lái xe chịu trách nhiệm cho hành khách dưới 18 tuổi."},"tl":{"q":"Sa New Jersey, sino ang mananagot kapag hindi nakasuot ng seat belt ang pasaherong wala pang 18?","o":["Ang driver","Ang pasahero","Ang may-ari ng kotse","Ang magulang ng pasahero, kahit wala sa kotse"],"h1":"Isipin ang taong nasa likod ng manibela.","h2":"Sa New Jersey, ang driver ang may pananagutan na siguraduhing nakasuot ng seat belt ang bawat pasaherong wala pang 18.","p":"Tama. Ang driver ang mananagot sa mga pasaherong wala pang 18."},"ar":{"q":"في New Jersey، مَن المسؤول عندما لا يربط راكب عمره أقل من 18 عامًا حزام الأمان؟","o":["السائق","الراكب","مالك السيارة","أحد والدَي الراكب، حتى لو لم يكن في السيارة"],"h1":"فكّر في الشخص الذي يمسك المِقوَد.","h2":"في New Jersey، السائق هو المسؤول عن التأكد من أن كل راكب عمره أقل من 18 عامًا يربط حزام الأمان.","p":"صحيح. السائق مسؤول عن الركاب الذين أعمارهم أقل من 18 عامًا."},"ref":{"doc":"NJ","page":40}},{"id":"nj-026","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, a crash causes more than $500 in damage and the police file no report. What must you do?","o":["Nothing, if no one was hurt","Call the MVC within 24 hours","Send a written report to the MVC within 10 days","Report it at your next license renewal"],"h1":"You put it in writing, and you have less than two weeks.","h2":"In New Jersey, if damage is over $500 or someone is hurt and the police file no report, you must send a written report to the MVC within 10 days.","p":"Right. Without a police report, you send a written report to the MVC within 10 days."},"es":{"q":"En New Jersey, un choque causa más de $500 en daños y la policía no hace un informe. ¿Qué debe hacer usted?","o":["Nada, si nadie resultó herido","Llamar a la MVC dentro de 24 horas","Enviar un informe escrito a la MVC dentro de 10 días","Informarlo cuando renueve su licencia"],"h1":"Se hace por escrito, y tiene menos de dos semanas.","h2":"En New Jersey, si los daños pasan de $500 o hay alguien herido y la policía no hace un informe, usted debe enviar un informe escrito a la MVC dentro de 10 días.","p":"Correcto. Sin informe policial, usted envía un informe escrito a la MVC dentro de 10 días."},"zh":{"q":"在 New Jersey，一场车祸造成超过 $500 的损失，警察没有写报告。你必须怎么做？","o":["如果没人受伤，什么都不用做","在 24 小时内打电话给 MVC","在 10 天内向 MVC 寄送书面报告","在下次更新驾照时报告"],"h1":"你要写成书面的，而且时间不到两个星期。","h2":"在 New Jersey，如果损失超过 $500 或有人受伤，而警察没有写报告，你必须在 10 天内向 MVC 寄送书面报告。","p":"对。没有警察报告时，你要在 10 天内向 MVC 寄送书面报告。"},"vi":{"q":"Ở New Jersey, một vụ tai nạn gây thiệt hại hơn $500 và cảnh sát không làm biên bản. Bạn phải làm gì?","o":["Không cần làm gì, nếu không ai bị thương","Gọi cho MVC trong vòng 24 giờ","Gửi báo cáo bằng văn bản cho MVC trong vòng 10 ngày","Báo cáo khi gia hạn bằng lái lần tới"],"h1":"Bạn phải viết ra giấy, và bạn có chưa đến hai tuần.","h2":"Ở New Jersey, nếu thiệt hại hơn $500 hoặc có người bị thương và cảnh sát không làm biên bản, bạn phải gửi báo cáo bằng văn bản cho MVC trong vòng 10 ngày.","p":"Đúng. Khi không có biên bản của cảnh sát, bạn gửi báo cáo bằng văn bản cho MVC trong vòng 10 ngày."},"tl":{"q":"Sa New Jersey, ang isang banggaan ay nagdulot ng higit sa $500 na pinsala at walang report na ginawa ang pulis. Ano ang dapat mong gawin?","o":["Wala, kung walang nasaktan","Tumawag sa MVC sa loob ng 24 oras","Magpadala ng nakasulat na report sa MVC sa loob ng 10 araw","I-report ito sa susunod mong pag-renew ng lisensya"],"h1":"Isusulat mo ito, at mayroon kang wala pang dalawang linggo.","h2":"Sa New Jersey, kung higit sa $500 ang pinsala o may nasaktan at walang report na ginawa ang pulis, dapat kang magpadala ng nakasulat na report sa MVC sa loob ng 10 araw.","p":"Tama. Kapag walang police report, magpadala ng nakasulat na report sa MVC sa loob ng 10 araw."},"ar":{"q":"في New Jersey، تسبّب حادث في أضرار تزيد على $500 ولم تكتب الشرطة أي تقرير. ماذا يجب أن تفعل؟","o":["لا شيء، إذا لم يُصب أحد","الاتصال بـ MVC خلال 24 ساعة","إرسال تقرير مكتوب إلى MVC خلال 10 أيام","الإبلاغ عنه عند تجديد رخصتك القادم"],"h1":"تكتبه على الورق، ولديك أقل من أسبوعين.","h2":"في New Jersey، إذا زادت الأضرار على $500 أو أُصيب أحد ولم تكتب الشرطة تقريرًا، يجب أن ترسل تقريرًا مكتوبًا إلى MVC خلال 10 أيام.","p":"صحيح. عندما لا يوجد تقرير من الشرطة، ترسل تقريرًا مكتوبًا إلى MVC خلال 10 أيام."},"ref":{"doc":"NJ","page":111}},{"id":"nj-027","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, how many points can come off your record for each year you drive with no violation or suspension?","o":["One point","Up to three points","Up to six points","All of your points"],"h1":"It is a small number, and your total never goes below zero.","h2":"In New Jersey, up to three points are taken off your record for each year with no violation or suspension.","p":"Right. A clean year can remove up to three points."},"es":{"q":"En New Jersey, ¿cuántos puntos se pueden quitar de su historial por cada año que maneja sin infracciones ni suspensiones?","o":["Un punto","Hasta tres puntos","Hasta seis puntos","Todos sus puntos"],"h1":"Es un número pequeño, y su total nunca baja de cero.","h2":"En New Jersey, se quitan hasta tres puntos de su historial por cada año sin infracciones ni suspensiones.","p":"Correcto. Un año limpio puede quitar hasta tres puntos."},"zh":{"q":"在 New Jersey，你每开车一年没有违规或被吊销驾照，记录上可以减去多少分？","o":["一分","最多三分","最多六分","全部分数"],"h1":"这是一个小数字，而且你的总分永远不会低于零。","h2":"在 New Jersey，每一年没有违规或被吊销驾照，你的记录上最多可以减去三分。","p":"对。一年没有违规最多可以减去三分。"},"vi":{"q":"Ở New Jersey, mỗi năm bạn lái xe không vi phạm và không bị treo bằng lái, hồ sơ của bạn được trừ bao nhiêu điểm?","o":["Một điểm","Tối đa ba điểm","Tối đa sáu điểm","Tất cả số điểm của bạn"],"h1":"Đó là một con số nhỏ, và tổng điểm của bạn không bao giờ dưới không.","h2":"Ở New Jersey, mỗi năm không vi phạm và không bị treo bằng lái, hồ sơ của bạn được trừ tối đa ba điểm.","p":"Đúng. Một năm không vi phạm có thể trừ tối đa ba điểm."},"tl":{"q":"Sa New Jersey, ilang puntos ang puwedeng matanggal sa record mo sa bawat taon na nagmaneho ka nang walang paglabag o suspensyon?","o":["Isang puntos","Hanggang tatlong puntos","Hanggang anim na puntos","Lahat ng puntos mo"],"h1":"Maliit na numero ito, at hindi bababa sa zero ang kabuuan mo.","h2":"Sa New Jersey, hanggang tatlong puntos ang tinatanggal sa record mo sa bawat taon na walang paglabag o suspensyon.","p":"Tama. Ang isang malinis na taon ay puwedeng mag-alis ng hanggang tatlong puntos."},"ar":{"q":"في New Jersey، كم نقطة يمكن أن تُحذف من سجلّك عن كل سنة تقود فيها بلا مخالفة أو إيقاف للرخصة؟","o":["نقطة واحدة","حتى ثلاث نقاط","حتى ست نقاط","كل نقاطك"],"h1":"إنه عدد صغير، ومجموع نقاطك لا ينزل أبدًا تحت الصفر.","h2":"في New Jersey، تُحذف حتى ثلاث نقاط من سجلّك عن كل سنة بلا مخالفة أو إيقاف للرخصة.","p":"صحيح. السنة النظيفة يمكن أن تحذف حتى ثلاث نقاط."},"ref":{"doc":"NJ","page":137}},{"id":"nj-028","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, what eyesight must a basic license applicant have, with or without glasses?","o":["20/20","20/40","20/50","20/100"],"h1":"The rule for commercial drivers is stricter than this one.","h2":"In New Jersey, a basic license applicant needs 20/50 vision, with or without glasses or contact lenses.","p":"Right. A basic license needs 20/50 vision."},"es":{"q":"En Nueva Jersey, ¿qué visión debe tener quien solicita una licencia básica, con o sin anteojos?","o":["20/20","20/40","20/50","20/100"],"h1":"La regla para conductores comerciales es más estricta que esta.","h2":"En Nueva Jersey, quien solicita una licencia básica necesita una visión de 20/50, con o sin anteojos o lentes de contacto.","p":"Correcto. La licencia básica pide una visión de 20/50."},"zh":{"q":"在 New Jersey，申请普通驾照的人戴或不戴眼镜，视力必须达到多少？","o":["20/20","20/40","20/50","20/100"],"h1":"商业驾驶员的规定比这个更严格。","h2":"在 New Jersey，申请普通驾照的人戴或不戴眼镜或隐形眼镜，视力都需要达到 20/50。","p":"对。普通驾照需要 20/50 的视力。"},"vi":{"q":"Ở New Jersey, người xin bằng lái thông thường phải có thị lực bao nhiêu, dù có đeo kính hay không?","o":["20/20","20/40","20/50","20/100"],"h1":"Quy định cho tài xế thương mại nghiêm ngặt hơn quy định này.","h2":"Ở New Jersey, người xin bằng lái thông thường cần có thị lực 20/50, dù có đeo kính hoặc kính áp tròng hay không.","p":"Đúng. Bằng lái thông thường cần thị lực 20/50."},"tl":{"q":"Sa New Jersey, anong linaw ng paningin ang kailangan ng nag-a-apply ng basic na lisensya, may salamin man o wala?","o":["20/20","20/40","20/50","20/100"],"h1":"Mas mahigpit ang patakaran para sa mga commercial driver kaysa rito.","h2":"Sa New Jersey, kailangan ng nag-a-apply ng basic na lisensya ang 20/50 na paningin, may salamin o contact lens man o wala.","p":"Tama. Kailangan ng 20/50 na paningin para sa basic na lisensya."},"ar":{"q":"في New Jersey، ما قوة النظر المطلوبة لمن يتقدّم لرخصة قيادة عادية، بالنظارة أو بدونها؟","o":["20/20","20/40","20/50","20/100"],"h1":"القاعدة لسائقي المركبات التجارية أشدّ من هذه.","h2":"في New Jersey، يحتاج المتقدّم لرخصة عادية إلى نظر 20/50، بالنظارة أو العدسات اللاصقة أو بدونها.","p":"صحيح. الرخصة العادية تحتاج إلى نظر 20/50."},"ref":{"doc":"NJ","page":31}},{"id":"nj-029","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, how many points of ID must your documents add up to when you apply for a license?","o":["At least three points","At least four points","At least five points","At least six points"],"h1":"The MVC's ID system is named after this number.","h2":"In New Jersey, your ID documents must add up to at least six points, with at least one primary and one secondary document, plus proof of address.","p":"Right. You need at least six points of ID."},"es":{"q":"En Nueva Jersey, ¿cuántos puntos deben sumar sus documentos de identidad al solicitar una licencia?","o":["Al menos tres puntos","Al menos cuatro puntos","Al menos cinco puntos","Al menos seis puntos"],"h1":"El sistema de identificación de la MVC lleva el nombre de este número.","h2":"En Nueva Jersey, sus documentos de identidad deben sumar al menos seis puntos, con al menos un documento primario y uno secundario, más prueba de domicilio.","p":"Correcto. Necesita al menos seis puntos de identificación."},"zh":{"q":"在 New Jersey，申请驾照时，你的身份证明文件加起来必须有多少分？","o":["至少三分","至少四分","至少五分","至少六分"],"h1":"MVC 的身份证明制度就是用这个数字命名的。","h2":"在 New Jersey，你的身份证明文件加起来必须至少有六分，其中至少要有一份主要文件和一份次要文件，另外还要有地址证明。","p":"对。你需要至少六分的身份证明。"},"vi":{"q":"Ở New Jersey, khi xin bằng lái, giấy tờ tùy thân của bạn phải cộng lại được bao nhiêu điểm?","o":["Ít nhất ba điểm","Ít nhất bốn điểm","Ít nhất năm điểm","Ít nhất sáu điểm"],"h1":"Hệ thống giấy tờ tùy thân của MVC được đặt tên theo con số này.","h2":"Ở New Jersey, giấy tờ tùy thân của bạn phải cộng lại được ít nhất sáu điểm, với ít nhất một giấy tờ chính và một giấy tờ phụ, cùng với giấy tờ chứng minh địa chỉ.","p":"Đúng. Bạn cần ít nhất sáu điểm giấy tờ tùy thân."},"tl":{"q":"Sa New Jersey, ilang puntos ng ID ang dapat kabuuan ng mga dokumento mo kapag nag-apply ka ng lisensya?","o":["Hindi bababa sa tatlong puntos","Hindi bababa sa apat na puntos","Hindi bababa sa limang puntos","Hindi bababa sa anim na puntos"],"h1":"Ipinangalan sa numerong ito ang ID system ng MVC.","h2":"Sa New Jersey, dapat umabot sa hindi bababa sa anim na puntos ang mga ID document mo, kasama ang hindi bababa sa isang primary at isang secondary na dokumento, at patunay ng address.","p":"Tama. Kailangan mo ng hindi bababa sa anim na puntos ng ID."},"ar":{"q":"في New Jersey، كم نقطة يجب أن يكون مجموع وثائق هويتك عندما تتقدّم لرخصة القيادة؟","o":["ثلاث نقاط على الأقل","أربع نقاط على الأقل","خمس نقاط على الأقل","ست نقاط على الأقل"],"h1":"نظام الهوية في MVC يحمل اسم هذا الرقم.","h2":"في New Jersey، يجب أن يكون مجموع وثائق هويتك ست نقاط على الأقل، منها وثيقة أساسية واحدة ووثيقة ثانوية واحدة على الأقل، مع إثبات العنوان.","p":"صحيح. تحتاج إلى ست نقاط على الأقل من وثائق الهوية."},"ref":{"doc":"NJ","page":9}},{"id":"nj-030","scope":"NJ","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In New Jersey, after an emergency vehicle with its siren or lights on passes you, how far behind it must you stay?","o":["At least 300 feet","At least 50 feet","At least 100 feet","At least 1,000 feet"],"h1":"It is about the length of a football field.","h2":"In New Jersey, after an emergency vehicle passes, you must stay at least 300 feet behind it while its signals are on.","p":"Right. Stay at least 300 feet behind."},"es":{"q":"En Nueva Jersey, después de que lo pasa un vehículo de emergencia con la sirena o las luces encendidas, ¿a qué distancia detrás debe mantenerse?","o":["Al menos 300 pies","Al menos 50 pies","Al menos 100 pies","Al menos 1,000 pies"],"h1":"Es más o menos el largo de un campo de fútbol americano.","h2":"En Nueva Jersey, después de que pasa un vehículo de emergencia, debe mantenerse al menos a 300 pies detrás mientras tenga sus señales encendidas.","p":"Correcto. Manténgase al menos a 300 pies detrás."},"zh":{"q":"在 New Jersey，一辆开着警笛或警灯的紧急车辆从你旁边经过后，你必须在它后面保持多远？","o":["至少 300 英尺","至少 50 英尺","至少 100 英尺","至少 1,000 英尺"],"h1":"大约是一个橄榄球场的长度。","h2":"在 New Jersey，紧急车辆经过后，只要它的信号还开着，你必须在它后面保持至少 300 英尺。","p":"对。要在后面保持至少 300 英尺。"},"vi":{"q":"Ở New Jersey, sau khi một xe cấp cứu đang bật còi hoặc đèn chạy qua bạn, bạn phải đi cách phía sau nó bao xa?","o":["Ít nhất 300 feet","Ít nhất 50 feet","Ít nhất 100 feet","Ít nhất 1,000 feet"],"h1":"Khoảng bằng chiều dài một sân bóng bầu dục.","h2":"Ở New Jersey, sau khi xe cấp cứu chạy qua, bạn phải đi cách phía sau nó ít nhất 300 feet khi nó còn bật tín hiệu.","p":"Đúng. Hãy đi cách phía sau ít nhất 300 feet."},"tl":{"q":"Sa New Jersey, pagkalampas sa iyo ng emergency vehicle na may sirena o ilaw na nakabukas, gaano kalayo ka dapat manatili sa likod nito?","o":["Hindi bababa sa 300 talampakan","Hindi bababa sa 50 talampakan","Hindi bababa sa 100 talampakan","Hindi bababa sa 1,000 talampakan"],"h1":"Halos kasinghaba ito ng isang football field.","h2":"Sa New Jersey, pagkalampas ng emergency vehicle, dapat kang manatili nang hindi bababa sa 300 talampakan sa likod nito habang nakabukas ang mga signal nito.","p":"Tama. Manatili nang hindi bababa sa 300 talampakan sa likod."},"ar":{"q":"في New Jersey، بعد أن تتجاوزك مركبة طوارئ صفّارتها أو أضواؤها تعمل، كم يجب أن تبقى بعيدًا خلفها؟","o":["300 قدم على الأقل","50 قدمًا على الأقل","100 قدم على الأقل","1,000 قدم على الأقل"],"h1":"إنها تقريبًا طول ملعب كرة قدم أمريكية.","h2":"في New Jersey، بعد أن تمرّ مركبة الطوارئ، يجب أن تبقى خلفها 300 قدم على الأقل ما دامت إشاراتها تعمل.","p":"صحيح. ابقَ خلفها 300 قدم على الأقل."},"ref":{"doc":"NJ","page":78}},{"id":"nj-031","scope":"NJ","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Jersey, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 15 feet","No closer than 25 feet"],"h1":"In New Jersey it is less than the 15 feet used in many other states.","h2":"In New Jersey, you may not park within 10 feet of a fire hydrant.","p":"Right. Stay at least 10 feet from a hydrant."},"es":{"q":"En Nueva Jersey, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No a menos de 5 pies","No a menos de 10 pies","No a menos de 15 pies","No a menos de 25 pies"],"h1":"En Nueva Jersey es menos que los 15 pies que se usan en muchos otros estados.","h2":"En Nueva Jersey, no puede estacionarse a menos de 10 pies de un hidrante.","p":"Correcto. Quédese al menos a 10 pies de un hidrante."},"zh":{"q":"在 New Jersey，你可以在离消防栓多近的地方停车？","o":["不能近于 5 英尺","不能近于 10 英尺","不能近于 15 英尺","不能近于 25 英尺"],"h1":"在 New Jersey，这个距离比很多其他州使用的 15 英尺要短。","h2":"在 New Jersey，你不可以在离消防栓 10 英尺以内的地方停车。","p":"对。停车要离消防栓至少 10 英尺。"},"vi":{"q":"Ở New Jersey, bạn được đậu xe gần trụ nước cứu hỏa đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 15 feet","Không gần hơn 25 feet"],"h1":"Ở New Jersey, khoảng cách này ngắn hơn mức 15 feet mà nhiều tiểu bang khác dùng.","h2":"Ở New Jersey, bạn không được đậu xe trong vòng 10 feet tính từ trụ nước cứu hỏa.","p":"Đúng. Hãy đậu cách trụ nước cứu hỏa ít nhất 10 feet."},"tl":{"q":"Sa New Jersey, gaano kalapit ka puwedeng pumarada sa fire hydrant?","o":["Hindi lalapit sa 5 talampakan","Hindi lalapit sa 10 talampakan","Hindi lalapit sa 15 talampakan","Hindi lalapit sa 25 talampakan"],"h1":"Sa New Jersey, mas maikli ito kaysa sa 15 talampakan na ginagamit sa maraming ibang estado.","h2":"Sa New Jersey, hindi ka puwedeng pumarada sa loob ng 10 talampakan mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 10 talampakan sa hydrant."},"ar":{"q":"في New Jersey، ما أقرب مسافة يمكنك أن تركن فيها من صنبور إطفاء الحريق؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 10 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 25 قدمًا"],"h1":"في New Jersey هي أقل من الـ 15 قدمًا المستخدمة في ولايات كثيرة أخرى.","h2":"في New Jersey، لا يجوز لك أن تركن على مسافة أقل من 10 أقدام من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بعد 10 أقدام على الأقل من صنبور الإطفاء."},"ref":{"doc":"NJ","page":85}},{"id":"nj-032","scope":"NJ","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Jersey, you move to a new home. How soon must you report your new address to the MVC?","o":["Within one week","Within 30 days","Within 60 days","Only when you renew your license"],"h1":"It is a short time, counted in days, not months.","h2":"In New Jersey, you must report a new address to the MVC within one week after you move.","p":"Right. Report a new address within one week."},"es":{"q":"En New Jersey, usted se muda a una casa nueva. ¿En cuánto tiempo debe informar su nueva dirección a la MVC?","o":["Dentro de una semana","Dentro de 30 días","Dentro de 60 días","Solo cuando renueve su licencia"],"h1":"Es poco tiempo, contado en días, no en meses.","h2":"En New Jersey, usted debe informar su nueva dirección a la MVC dentro de una semana después de mudarse.","p":"Correcto. Informe la nueva dirección dentro de una semana."},"ref":{"doc":"NJ","page":4}},{"id":"nj-033","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, for how long is a new driver license valid?","o":["Two years","Four years","Eight years","Until you turn 65"],"h1":"It is more than two years but less than eight.","h2":"In New Jersey, driver licenses are valid for four years.","p":"Right. A New Jersey license lasts four years."},"es":{"q":"En New Jersey, ¿por cuánto tiempo es válida una licencia de conducir nueva?","o":["Dos años","Cuatro años","Ocho años","Hasta que cumpla 65 años"],"h1":"Es más de dos años pero menos de ocho.","h2":"En New Jersey, las licencias de conducir son válidas por cuatro años.","p":"Correcto. Una licencia de New Jersey dura cuatro años."},"ref":{"doc":"NJ","page":6}},{"id":"nj-034","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, how many hours of behind-the-wheel lessons does an approved course for a special learner permit include?","o":["Two hours","Fifty hours","Six hours","Ten hours"],"h1":"It is about one full school day of lessons with an instructor.","h2":"In New Jersey, an approved course for a special learner permit is six full hours of behind-the-wheel lessons in a car with dual controls.","p":"Right. The course is six hours behind the wheel."},"es":{"q":"En New Jersey, ¿cuántas horas de clases al volante incluye un curso aprobado para el permiso especial de aprendiz?","o":["Dos horas","Cincuenta horas","Seis horas","Diez horas"],"h1":"Es más o menos un día escolar completo de clases con un instructor.","h2":"En New Jersey, un curso aprobado para el permiso especial de aprendiz son seis horas completas de clases al volante en un carro con doble control.","p":"Correcto. El curso es de seis horas al volante."},"ref":{"doc":"NJ","page":19}},{"id":"nj-035","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, how long must you drive with a probationary license before you can get a basic driver license?","o":["Three months","Six months","Two years","At least one year"],"h1":"It is longer than the six months of supervised practice.","h2":"In New Jersey, you must drive for at least one year with a probationary license before you can get a basic driver license.","p":"Right. At least one year on a probationary license."},"es":{"q":"En New Jersey, ¿cuánto tiempo debe manejar con licencia probatoria antes de obtener la licencia de conducir básica?","o":["Tres meses","Seis meses","Dos años","Al menos un año"],"h1":"Es más que los seis meses de práctica supervisada.","h2":"En New Jersey, usted debe manejar al menos un año con licencia probatoria antes de obtener la licencia de conducir básica.","p":"Correcto. Al menos un año con licencia probatoria."},"ref":{"doc":"NJ","page":15}},{"id":"nj-036","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, when may you use studded snow tires?","o":["From November 15 to April 1","From October 1 to May 1","From December 1 to March 1","Any time of the year"],"h1":"The season starts in the middle of November.","h2":"In New Jersey, you may use studded snow tires from November 15 to April 1.","p":"Right. Studded tires are allowed from November 15 to April 1."},"es":{"q":"En New Jersey, ¿cuándo puede usar llantas de nieve con clavos?","o":["Del 15 de noviembre al 1 de abril","Del 1 de octubre al 1 de mayo","Del 1 de diciembre al 1 de marzo","En cualquier época del año"],"h1":"La temporada empieza a mediados de noviembre.","h2":"En New Jersey, puede usar llantas de nieve con clavos del 15 de noviembre al 1 de abril.","p":"Correcto. Las llantas con clavos se permiten del 15 de noviembre al 1 de abril."},"ref":{"doc":"NJ","page":99}},{"id":"nj-037","scope":"NJ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Jersey, you drive without clearing the snow and ice off your car. What fine can you get, even if nothing flies off?","o":["No fine, unless snow flies off","$25 to $75","$200 to $1,000","$1,500"],"h1":"You can be fined even if no snow falls off, but the amount is small.","h2":"In New Jersey, driving without clearing snow and ice off your car can bring a fine of $25 to $75, even if nothing flies off.","p":"Right. Not clearing your car can cost $25 to $75."},"es":{"q":"En New Jersey, usted maneja sin quitar la nieve y el hielo de su carro. ¿Qué multa le pueden poner, aunque no se caiga nada?","o":["Ninguna multa, a menos que se caiga la nieve","$25 a $75","$200 a $1,000","$1,500"],"h1":"Le pueden multar aunque no se caiga nada de nieve, pero la cantidad es pequeña.","h2":"En New Jersey, manejar sin quitar la nieve y el hielo de su carro puede costarle una multa de $25 a $75, aunque no se caiga nada.","p":"Correcto. No limpiar su carro puede costar de $25 a $75."},"ref":{"doc":"NJ","page":47}},{"id":"nj-038","scope":"NJ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Jersey, apart from a few exceptions such as being stuck in traffic, how long may a vehicle sit with its engine idling?","o":["One minute","Ten minutes","Three minutes","Fifteen minutes"],"h1":"It is only a few minutes.","h2":"In New Jersey, the law limits vehicle idling to three minutes or less, with a few exceptions such as being stuck in traffic.","p":"Right. Idling is limited to three minutes."},"es":{"q":"En New Jersey, salvo algunas excepciones como estar atascado en el tráfico, ¿cuánto tiempo puede estar un vehículo con el motor encendido sin moverse?","o":["Un minuto","Diez minutos","Tres minutos","Quince minutos"],"h1":"Son solo unos pocos minutos.","h2":"En New Jersey, la ley limita a tres minutos o menos el tiempo que un vehículo puede estar con el motor encendido sin moverse, con algunas excepciones como estar atascado en el tráfico.","p":"Correcto. El motor encendido sin moverse se limita a tres minutos."},"ref":{"doc":"NJ","page":50}},{"id":"nj-039","scope":"NJ","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New Jersey, an ice cream truck ahead has its red lights flashing and its stop arm out. What must you do?","o":["Slow to 25 mph and pass","Pass at normal speed if no one is crossing","Stop and wait until the truck drives away","Stop, then pass at no more than 15 mph"],"h1":"Children may run to or from the truck, so you stop first.","h2":"In New Jersey, you must stop for an ice cream truck with flashing red lights and a stop arm, yield to people crossing, then pass at no more than 15 mph.","p":"Right. Stop first, then pass at 15 mph or less."},"es":{"q":"En New Jersey, un camión de helados adelante tiene las luces rojas intermitentes y el brazo de pare extendido. ¿Qué debe hacer?","o":["Bajar a 25 mph y pasar","Pasar a velocidad normal si nadie está cruzando","Parar y esperar hasta que el camión se vaya","Parar, y luego pasar a no más de 15 mph"],"h1":"Puede haber niños que corren hacia el camión o desde él, así que primero se para.","h2":"En New Jersey, usted debe parar ante un camión de helados con luces rojas intermitentes y brazo de pare, ceder el paso a quienes cruzan, y luego pasar a no más de 15 mph.","p":"Correcto. Primero pare, y luego pase a 15 mph o menos."},"ref":{"doc":"NJ","page":78}},{"id":"nj-040","scope":"NJ","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Jersey, how close may you park to a fire department vehicle that is in service?","o":["No closer than 200 feet","No closer than 50 feet","No closer than 20 feet","No closer than 10 feet"],"h1":"It is a long distance, more than half a football field.","h2":"In New Jersey, you may not park within 200 feet of a fire department vehicle that is in service.","p":"Right. Stay at least 200 feet away from a working fire vehicle."},"es":{"q":"En New Jersey, ¿qué tan cerca puede estacionarse de un vehículo de bomberos que está en servicio?","o":["No a menos de 200 pies","No a menos de 50 pies","No a menos de 20 pies","No a menos de 10 pies"],"h1":"Es una distancia larga, más de medio campo de fútbol americano.","h2":"En New Jersey, no puede estacionarse a menos de 200 pies de un vehículo de bomberos que está en servicio.","p":"Correcto. Quédese al menos a 200 pies de un vehículo de bomberos en servicio."},"ref":{"doc":"NJ","page":78}},{"id":"nj-041","scope":"NJ","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Jersey, how many points go on your record if you fail to stop for a person in a crosswalk?","o":["None, only a fine","Two points","Five points","Eight points"],"h1":"It is the same number of points as many common moving violations.","h2":"In New Jersey, failing to stop for a person in a crosswalk adds two points to your record, along with a fine of up to $500.","p":"Right. It adds two points to your record."},"es":{"q":"En New Jersey, ¿cuántos puntos se agregan a su historial si no para ante una persona en un cruce peatonal?","o":["Ninguno, solo una multa","Dos puntos","Cinco puntos","Ocho puntos"],"h1":"Es la misma cantidad de puntos que muchas infracciones de tránsito comunes.","h2":"En New Jersey, no parar ante una persona en un cruce peatonal agrega dos puntos a su historial, además de una multa de hasta $500.","p":"Correcto. Agrega dos puntos a su historial."},"ref":{"doc":"NJ","page":66}},{"id":"nj-042","scope":"NJ","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Jersey, on a road with a 65 mph limit, how fast over the limit must you go for the speeding fine to double?","o":["Any amount over the limit","5 mph or more over","10 mph or more over","20 mph or more over"],"h1":"It is a round number between 5 and 20.","h2":"In New Jersey, speeding fines are doubled for going 10 mph or more over the limit in a 65 mph zone.","p":"Right. Fines double at 10 mph or more over in a 65 mph zone."},"es":{"q":"En New Jersey, en una carretera con límite de 65 mph, ¿cuánto debe pasar el límite para que la multa por exceso de velocidad sea el doble?","o":["Cualquier cantidad sobre el límite","5 mph o más sobre el límite","10 mph o más sobre el límite","20 mph o más sobre el límite"],"h1":"Es un número redondo entre 5 y 20.","h2":"En New Jersey, las multas por exceso de velocidad son el doble si va a 10 mph o más sobre el límite en una zona de 65 mph.","p":"Correcto. La multa es el doble a 10 mph o más sobre el límite en una zona de 65 mph."},"ref":{"doc":"NJ","page":62}},{"id":"nj-043","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, how many points do you get for driving 15 to 29 mph over the speed limit?","o":["Two points","Three points","Five points","Four points"],"h1":"It is more than the points for going 1 to 14 mph over, and less than for 30 or more.","h2":"In New Jersey, driving 15 to 29 mph over the speed limit adds four points to your record.","p":"Right. Going 15 to 29 mph over costs four points."},"es":{"q":"En New Jersey, ¿cuántos puntos recibe por manejar de 15 a 29 mph sobre el límite de velocidad?","o":["Dos puntos","Tres puntos","Cinco puntos","Cuatro puntos"],"h1":"Es más que los puntos por ir de 1 a 14 mph sobre el límite, y menos que por ir 30 o más.","h2":"En New Jersey, manejar de 15 a 29 mph sobre el límite de velocidad agrega cuatro puntos a su historial.","p":"Correcto. Ir de 15 a 29 mph sobre el límite cuesta cuatro puntos."},"ref":{"doc":"NJ","page":139}},{"id":"nj-044","scope":"NJ","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Jersey, how many points come off your record when you finish an approved defensive driving course?","o":["Two points","Four points","Six points","All of your points"],"h1":"It is a small number, and the MVC counts the course only once every five years.","h2":"In New Jersey, finishing an approved defensive driving course takes two points off your record.","p":"Right. The course removes two points."},"es":{"q":"En New Jersey, ¿cuántos puntos se quitan de su historial cuando termina un curso aprobado de manejo defensivo?","o":["Dos puntos","Cuatro puntos","Seis puntos","Todos sus puntos"],"h1":"Es un número pequeño, y la MVC cuenta el curso solo una vez cada cinco años.","h2":"En New Jersey, terminar un curso aprobado de manejo defensivo quita dos puntos de su historial.","p":"Correcto. El curso quita dos puntos."},"ref":{"doc":"NJ","page":135}},{"id":"nj-045","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, a new driver is convicted of two moving violations worth 4 or more points in the first two years after getting a permit. What must the driver do?","o":["Retake the knowledge test","Complete the Probationary Driver Program","Pay a $1,000 surcharge","Get a new permit and start over"],"h1":"It is a program for new drivers, run by approved driving schools and safety groups.","h2":"In New Jersey, a new driver with two or more moving violations worth 4 or more points in the two-year probationary period must complete the Probationary Driver Program.","p":"Right. The driver must complete the Probationary Driver Program."},"es":{"q":"En New Jersey, un conductor nuevo es condenado por dos infracciones de tránsito que suman 4 puntos o más en los primeros dos años después de obtener el permiso. ¿Qué debe hacer?","o":["Volver a tomar el examen de conocimientos","Completar el Probationary Driver Program (programa para conductores nuevos)","Pagar un recargo de $1,000","Obtener un permiso nuevo y empezar de cero"],"h1":"Es un programa para conductores nuevos que dan escuelas de manejo y organizaciones de seguridad aprobadas.","h2":"En New Jersey, un conductor nuevo con dos o más infracciones que suman 4 puntos o más en el período probatorio de dos años debe completar el Probationary Driver Program.","p":"Correcto. El conductor debe completar el Probationary Driver Program."},"ref":{"doc":"NJ","page":134}},{"id":"nj-046","scope":"NJ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Jersey, a driver refuses to take a breath test. What surcharge does the driver face?","o":["$250, paid once","$500 a year for two years","$1,000 a year for three years","No surcharge, only a warning"],"h1":"It is paid every year for more than one year.","h2":"In New Jersey, a driver who refuses a breath test faces a surcharge of $1,000 a year for three years.","p":"Right. Refusing costs $1,000 a year for three years."},"es":{"q":"En New Jersey, un conductor se niega a hacerse la prueba de aliento. ¿Qué recargo le corresponde?","o":["$250, que se paga una vez","$500 al año por dos años","$1,000 al año por tres años","Ningún recargo, solo una advertencia"],"h1":"Se paga cada año, por más de un año.","h2":"En New Jersey, un conductor que se niega a la prueba de aliento debe pagar un recargo de $1,000 al año por tres años.","p":"Correcto. Negarse cuesta $1,000 al año por tres años."},"ref":{"doc":"NJ","page":127}},{"id":"nj-047","scope":"NJ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Jersey, a driver leaves the scene of a crash where someone was hurt. For a first offense, how long does the driver lose their license?","o":["30 days","Six months","For life","One year"],"h1":"Losing it for life is the penalty for doing it again.","h2":"In New Jersey, a first offense of leaving the scene of a crash where someone was hurt means losing your license for one year.","p":"Right. A first hit-and-run with injury costs your license for one year."},"es":{"q":"En New Jersey, un conductor se va del lugar de un choque donde alguien resultó herido. Por una primera infracción, ¿por cuánto tiempo pierde la licencia?","o":["30 días","Seis meses","De por vida","Un año"],"h1":"Perderla de por vida es el castigo por hacerlo otra vez.","h2":"En New Jersey, una primera infracción por irse del lugar de un choque donde alguien resultó herido significa perder la licencia por un año.","p":"Correcto. Una primera fuga con heridos le quita la licencia por un año."},"ref":{"doc":"NJ","page":130}},{"id":"nj-048","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, what is the fine for a first offense of carrying an open container of alcohol in the passenger area of a car?","o":["$200","$50","$100","$1,000"],"h1":"It is a few hundred dollars, not thousands.","h2":"In New Jersey, a first offense of carrying an open container of alcohol in the passenger area of a car brings a $200 fine.","p":"Right. A first offense costs $200."},"es":{"q":"En New Jersey, ¿cuál es la multa por una primera vez de llevar un envase de alcohol abierto en el área de pasajeros de un carro?","o":["$200","$50","$100","$1,000"],"h1":"Son unos cientos de dólares, no miles.","h2":"En New Jersey, una primera infracción por llevar un envase de alcohol abierto en el área de pasajeros de un carro tiene una multa de $200.","p":"Correcto. Una primera infracción cuesta $200."},"ref":{"doc":"NJ","page":129}},{"id":"nj-049","scope":"NJ","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Jersey, a bus has picked up passengers and signals to pull back into traffic. What must you do?","o":["Speed up and pass it before it moves","Yield and let the bus back into the lane","Yield only if it is a school bus","Honk and keep going, because the bus must wait"],"h1":"State law protects buses at this moment.","h2":"In New Jersey, you must yield to a bus that is pulling back into traffic after picking up or dropping off passengers.","p":"Right. Let the bus back into traffic."},"es":{"q":"En New Jersey, un autobús recogió pasajeros y señala que va a volver al tráfico. ¿Qué debe hacer?","o":["Acelerar y pasarlo antes de que se mueva","Ceder el paso y dejar que el autobús vuelva al carril","Ceder el paso solo si es un autobús escolar","Tocar la bocina y seguir, porque el autobús debe esperar"],"h1":"La ley del estado protege a los autobuses en este momento.","h2":"En New Jersey, usted debe ceder el paso a un autobús que vuelve al tráfico después de recoger o dejar pasajeros.","p":"Correcto. Deje que el autobús vuelva al tráfico."},"ref":{"doc":"NJ","page":150}},{"id":"nj-050","scope":"NJ","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New Jersey, how fast may you go when you come up to or pass a horse-drawn vehicle?","o":["No more than 10 mph","No more than 35 mph","No more than 25 mph","The posted speed limit"],"h1":"It is the same speed as in many school zones.","h2":"In New Jersey, you must slow to 25 mph or less when you come up to or pass a horse-drawn vehicle.","p":"Right. Slow to 25 mph or less near a horse-drawn vehicle."},"es":{"q":"En New Jersey, ¿a qué velocidad puede ir cuando se acerca a un vehículo tirado por caballos o lo pasa?","o":["A no más de 10 mph","A no más de 35 mph","A no más de 25 mph","Al límite de velocidad indicado"],"h1":"Es la misma velocidad que en muchas zonas escolares.","h2":"En New Jersey, usted debe bajar a 25 mph o menos cuando se acerca a un vehículo tirado por caballos o lo pasa.","p":"Correcto. Baje a 25 mph o menos cerca de un vehículo tirado por caballos."},"ref":{"doc":"NJ","page":155}},{"id":"nm-001","scope":"NM","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Mexico, what is the youngest age to apply for an instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year younger than 16.","h2":"In New Mexico you can apply for an instruction permit at 15 if you are in or have finished an approved driver education course.","p":"Right. The New Mexico permit starts at 15."},"es":{"q":"En Nuevo México, ¿cuál es la edad mínima para solicitar un permiso de instrucción?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año menos que 16.","h2":"En Nuevo México usted puede solicitar un permiso de instrucción a los 15 años si está tomando o ya terminó un curso aprobado de educación vial.","p":"Correcto. El permiso en Nuevo México empieza a los 15."},"zh":{"q":"在 New Mexico，最小几岁可以申请学习驾照（instruction permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比 16 岁小一岁。","h2":"在 New Mexico，如果你正在上或已经上完认可的驾驶教育课程，15 岁就可以申请学习驾照。","p":"对。New Mexico 的学习驾照从 15 岁开始。"},"vi":{"q":"Ở New Mexico, tuổi nhỏ nhất để xin giấy phép tập lái (instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Nó nhỏ hơn 16 một tuổi.","h2":"Ở New Mexico, bạn có thể xin giấy phép tập lái lúc 15 tuổi nếu bạn đang học hoặc đã học xong một khóa giáo dục lái xe được chấp thuận.","p":"Đúng. Giấy phép tập lái ở New Mexico bắt đầu từ 15 tuổi."},"tl":{"q":"Sa New Mexico, ano ang pinakabatang edad para mag-apply ng instruction permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Ito ay isang taon na mas bata sa 16.","h2":"Sa New Mexico, puwede kang mag-apply ng instruction permit sa edad na 15 kung nag-aaral ka o tapos ka na sa isang aprubadong kurso sa driver education.","p":"Tama. Ang permit sa New Mexico ay nagsisimula sa edad na 15."},"ar":{"q":"في New Mexico، ما أصغر عمر للتقدّم بطلب تصريح التعلّم (instruction permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"إنه أصغر من 16 بسنة واحدة.","h2":"في New Mexico يمكنك التقدّم بطلب تصريح التعلّم في سن 15 إذا كنت تدرس في دورة معتمدة لتعليم القيادة أو أنهيتها.","p":"صحيح. يبدأ تصريح التعلّم في New Mexico من سن 15."},"ref":{"doc":"NM","page":1}},{"id":"nm-002","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, what must the driver education course include for a teen to get an instruction permit?","o":["A car repair class","A first aid certificate","A DWI prevention and education part","A night driving test"],"h1":"It is about drinking and driving.","h2":"In New Mexico the approved driver education course must include a DWI prevention and education part.","p":"Correct. The course includes DWI education."},"es":{"q":"En Nuevo México, ¿qué debe incluir el curso de educación vial para que un joven obtenga el permiso de instrucción?","o":["Una clase de mecánica","Un certificado de primeros auxilios","Una parte de prevención y educación sobre manejar bajo la influencia (DWI)","Un examen de manejo nocturno"],"h1":"Tiene que ver con tomar alcohol y manejar.","h2":"En Nuevo México, el curso aprobado de educación vial debe incluir una parte de prevención y educación sobre manejar bajo la influencia (DWI).","p":"Correcto. El curso incluye educación sobre DWI."},"zh":{"q":"在 New Mexico，青少年要拿学习驾照，驾驶教育课程必须包括什么？","o":["修车课","急救证书","DWI（酒后驾车）预防和教育的部分","夜间驾驶考试"],"h1":"它和喝酒开车有关。","h2":"在 New Mexico，认可的驾驶教育课程必须包括 DWI（酒后驾车）预防和教育的部分。","p":"对。课程包括 DWI 教育。"},"vi":{"q":"Ở New Mexico, khóa giáo dục lái xe phải có phần nào để thanh thiếu niên được cấp giấy phép tập lái?","o":["Một lớp sửa xe","Một chứng chỉ sơ cứu","Một phần phòng chống và giáo dục về lái xe khi say rượu (DWI)","Một bài thi lái xe ban đêm"],"h1":"Nó nói về uống rượu và lái xe.","h2":"Ở New Mexico, khóa giáo dục lái xe được chấp thuận phải có một phần phòng chống và giáo dục về lái xe khi say rượu (DWI).","p":"Đúng. Khóa học có phần giáo dục về DWI."},"tl":{"q":"Sa New Mexico, ano ang dapat kasama sa kurso sa driver education para makakuha ang isang teen ng instruction permit?","o":["Isang klase sa pag-aayos ng kotse","Isang sertipiko sa first aid","Isang bahagi tungkol sa pag-iwas at edukasyon sa DWI (pagmamaneho nang lasing)","Isang pagsusulit sa pagmamaneho sa gabi"],"h1":"Ito ay tungkol sa pag-inom ng alak at pagmamaneho.","h2":"Sa New Mexico, ang aprubadong kurso sa driver education ay dapat may bahagi tungkol sa pag-iwas at edukasyon sa DWI (pagmamaneho nang lasing).","p":"Tama. May edukasyon sa DWI ang kurso."},"ar":{"q":"في New Mexico، ماذا يجب أن تتضمّن دورة تعليم القيادة حتى يحصل المراهق على تصريح التعلّم؟","o":["درسًا في إصلاح السيارات","شهادة إسعافات أولية","جزءًا عن الوقاية والتوعية من القيادة تحت تأثير الكحول (DWI)","اختبار قيادة ليلية"],"h1":"إنه عن شرب الكحول والقيادة.","h2":"في New Mexico يجب أن تتضمّن دورة تعليم القيادة المعتمدة جزءًا عن الوقاية والتوعية من القيادة تحت تأثير الكحول (DWI).","p":"صحيح. تتضمّن الدورة توعية عن DWI."},"ref":{"doc":"NM","page":1}},{"id":"nm-003","scope":"NM","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Mexico, how old must the licensed driver beside an instruction permit holder be?","o":["16 or older","18 or older","25 or older","21 or older"],"h1":"The helper must be old enough to drink legally.","h2":"In New Mexico an instruction permit holder must drive with a licensed driver who is 21 or older in the seat beside them.","p":"Right. The supervisor must be 21 or older."},"es":{"q":"En Nuevo México, ¿qué edad debe tener el conductor con licencia que va al lado de quien tiene permiso de instrucción?","o":["16 años o más","18 años o más","25 años o más","21 años o más"],"h1":"El acompañante debe tener edad para tomar alcohol legalmente.","h2":"En Nuevo México, quien tiene permiso de instrucción debe manejar con un conductor con licencia de 21 años o más sentado a su lado.","p":"Correcto. El supervisor debe tener 21 años o más."},"zh":{"q":"在 New Mexico，坐在学习驾照持有人旁边的有驾照司机必须几岁？","o":["16 岁或以上","18 岁或以上","25 岁或以上","21 岁或以上"],"h1":"陪同的人必须到了可以合法喝酒的年龄。","h2":"在 New Mexico，学习驾照持有人开车时，旁边的座位必须坐一位 21 岁或以上、有驾照的司机。","p":"对。监督的人必须 21 岁或以上。"},"vi":{"q":"Ở New Mexico, người lái xe có bằng ngồi bên cạnh người có giấy phép tập lái phải bao nhiêu tuổi?","o":["16 tuổi trở lên","18 tuổi trở lên","25 tuổi trở lên","21 tuổi trở lên"],"h1":"Người giúp đỡ phải đủ tuổi để được uống rượu hợp pháp.","h2":"Ở New Mexico, người có giấy phép tập lái phải lái xe cùng một người có bằng lái từ 21 tuổi trở lên ngồi ở ghế bên cạnh.","p":"Đúng. Người giám sát phải từ 21 tuổi trở lên."},"tl":{"q":"Sa New Mexico, ilang taon dapat ang lisensiyadong driver na katabi ng may instruction permit?","o":["16 pataas","18 pataas","25 pataas","21 pataas"],"h1":"Ang tagatulong ay dapat nasa edad na legal nang uminom ng alak.","h2":"Sa New Mexico, ang may instruction permit ay dapat magmaneho kasama ang isang lisensiyadong driver na 21 taong gulang pataas na nakaupo sa tabi niya.","p":"Tama. Ang superbisor ay dapat 21 taong gulang pataas."},"ar":{"q":"في New Mexico، كم يجب أن يكون عمر السائق المرخَّص الذي يجلس بجانب حامل تصريح التعلّم؟","o":["16 سنة أو أكثر","18 سنة أو أكثر","25 سنة أو أكثر","21 سنة أو أكثر"],"h1":"يجب أن يكون المساعد في العمر الذي يُسمح فيه قانونيًا بشرب الكحول.","h2":"في New Mexico يجب أن يقود حامل تصريح التعلّم مع سائق مرخَّص عمره 21 سنة أو أكثر يجلس في المقعد بجانبه.","p":"صحيح. يجب أن يكون المشرف عمره 21 سنة أو أكثر."},"ref":{"doc":"NM","page":1}},{"id":"nm-004","scope":"NM","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Mexico, how long must the supervising driver have been licensed?","o":["At least three years","At least six months","At least one year","At least ten years"],"h1":"It is more than one year but less than five.","h2":"In New Mexico the supervising driver must have been licensed for at least three years, in New Mexico or another state.","p":"Correct. Three years of licensed driving are required."},"es":{"q":"En Nuevo México, ¿cuánto tiempo debe tener licencia el conductor que supervisa?","o":["Por lo menos tres años","Por lo menos seis meses","Por lo menos un año","Por lo menos diez años"],"h1":"Es más de un año, pero menos de cinco.","h2":"En Nuevo México, el conductor que supervisa debe tener licencia desde hace por lo menos tres años, en Nuevo México o en otro estado.","p":"Correcto. Se piden tres años con licencia."},"zh":{"q":"在 New Mexico，监督司机必须有驾照多久？","o":["至少三年","至少六个月","至少一年","至少十年"],"h1":"它比一年多，但比五年少。","h2":"在 New Mexico，监督司机必须有驾照至少三年，在 New Mexico 或其他州都可以。","p":"对。需要有三年驾照。"},"vi":{"q":"Ở New Mexico, người lái xe giám sát phải có bằng lái được bao lâu?","o":["Ít nhất ba năm","Ít nhất sáu tháng","Ít nhất một năm","Ít nhất mười năm"],"h1":"Nó nhiều hơn một năm nhưng ít hơn năm năm.","h2":"Ở New Mexico, người lái xe giám sát phải có bằng lái ít nhất ba năm, ở New Mexico hoặc ở một tiểu bang khác.","p":"Đúng. Cần ba năm có bằng lái."},"tl":{"q":"Sa New Mexico, gaano na katagal dapat may lisensiya ang nagbabantay na driver?","o":["Hindi bababa sa tatlong taon","Hindi bababa sa anim na buwan","Hindi bababa sa isang taon","Hindi bababa sa sampung taon"],"h1":"Ito ay higit sa isang taon pero kulang sa limang taon.","h2":"Sa New Mexico, ang nagbabantay na driver ay dapat may lisensiya nang hindi bababa sa tatlong taon, sa New Mexico o sa ibang estado.","p":"Tama. Kailangan ang tatlong taon na may lisensiya."},"ar":{"q":"في New Mexico، منذ كم من الوقت يجب أن يكون السائق المشرف حاصلًا على رخصة؟","o":["ثلاث سنوات على الأقل","ستة أشهر على الأقل","سنة واحدة على الأقل","عشر سنوات على الأقل"],"h1":"إنها أكثر من سنة وأقل من خمس سنوات.","h2":"في New Mexico يجب أن يكون السائق المشرف حاصلًا على رخصة منذ ثلاث سنوات على الأقل، في New Mexico أو في ولاية أخرى.","p":"صحيح. يجب أن يكون لديه رخصة منذ ثلاث سنوات."},"ref":{"doc":"NM","page":1}},{"id":"nm-005","scope":"NM","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Mexico, where must the supervising driver sit?","o":["In any back seat","In the seat beside the driver","Anywhere in the vehicle","In a car following behind"],"h1":"They need to see the road and help right away.","h2":"In New Mexico the supervising driver must sit in the seat beside the permit holder.","p":"Right. The supervisor sits beside you."},"es":{"q":"En Nuevo México, ¿dónde debe sentarse el conductor que supervisa?","o":["En cualquier asiento de atrás","En el asiento al lado del conductor","En cualquier lugar del vehículo","En otro auto que va detrás"],"h1":"Necesita ver el camino y ayudar de inmediato.","h2":"En Nuevo México, el conductor que supervisa debe ir sentado al lado de quien tiene el permiso.","p":"Correcto. El supervisor va a su lado."},"zh":{"q":"在 New Mexico，监督司机必须坐在哪里？","o":["任何后排座位","司机旁边的座位","车里任何地方","跟在后面的车里"],"h1":"他们需要看到道路，并能马上帮忙。","h2":"在 New Mexico，监督司机必须坐在学习驾照持有人旁边的座位。","p":"对。监督的人坐在你旁边。"},"vi":{"q":"Ở New Mexico, người lái xe giám sát phải ngồi ở đâu?","o":["Ở bất kỳ ghế sau nào","Ở ghế bên cạnh người lái","Ở bất cứ chỗ nào trong xe","Trong một xe chạy theo phía sau"],"h1":"Họ cần nhìn thấy đường và giúp ngay lập tức.","h2":"Ở New Mexico, người lái xe giám sát phải ngồi ở ghế bên cạnh người có giấy phép tập lái.","p":"Đúng. Người giám sát ngồi bên cạnh bạn."},"tl":{"q":"Sa New Mexico, saan dapat umupo ang nagbabantay na driver?","o":["Sa kahit anong upuan sa likod","Sa upuan sa tabi ng driver","Kahit saan sa sasakyan","Sa kotseng sumusunod sa likod"],"h1":"Kailangan nilang makita ang daan at tumulong agad.","h2":"Sa New Mexico, ang nagbabantay na driver ay dapat umupo sa upuan sa tabi ng may permit.","p":"Tama. Ang superbisor ay nakaupo sa tabi mo."},"ar":{"q":"في New Mexico، أين يجب أن يجلس السائق المشرف؟","o":["في أي مقعد خلفي","في المقعد بجانب السائق","في أي مكان في السيارة","في سيارة تسير خلفك"],"h1":"يحتاج أن يرى الطريق وأن يساعد فورًا.","h2":"في New Mexico يجب أن يجلس السائق المشرف في المقعد بجانب حامل تصريح التعلّم.","p":"صحيح. يجلس المشرف بجانبك."},"ref":{"doc":"NM","page":1}},{"id":"nm-006","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, how long must you hold an instruction permit before a provisional license?","o":["At least one month","At least three months","At least six months","At least two years"],"h1":"It is half a year.","h2":"In New Mexico you must hold an instruction permit for at least six months before getting a provisional license.","p":"Correct. Six months is the minimum."},"es":{"q":"En Nuevo México, ¿cuánto tiempo debe tener el permiso de instrucción antes de la licencia provisional?","o":["Por lo menos un mes","Por lo menos tres meses","Por lo menos seis meses","Por lo menos dos años"],"h1":"Es medio año.","h2":"En Nuevo México usted debe tener el permiso de instrucción por lo menos seis meses antes de obtener la licencia provisional.","p":"Correcto. Seis meses es el mínimo."},"zh":{"q":"在 New Mexico，拿过渡驾照（provisional license）前，必须持有学习驾照多久？","o":["至少一个月","至少三个月","至少六个月","至少两年"],"h1":"它是半年。","h2":"在 New Mexico，你必须持有学习驾照至少六个月，才能拿过渡驾照。","p":"对。最少六个月。"},"vi":{"q":"Ở New Mexico, bạn phải giữ giấy phép tập lái bao lâu trước khi được bằng lái tạm thời (provisional license)?","o":["Ít nhất một tháng","Ít nhất ba tháng","Ít nhất sáu tháng","Ít nhất hai năm"],"h1":"Nó là nửa năm.","h2":"Ở New Mexico, bạn phải giữ giấy phép tập lái ít nhất sáu tháng trước khi được bằng lái tạm thời.","p":"Đúng. Ít nhất là sáu tháng."},"tl":{"q":"Sa New Mexico, gaano katagal mo dapat hawak ang instruction permit bago makakuha ng provisional license?","o":["Hindi bababa sa isang buwan","Hindi bababa sa tatlong buwan","Hindi bababa sa anim na buwan","Hindi bababa sa dalawang taon"],"h1":"Ito ay kalahating taon.","h2":"Sa New Mexico, dapat mong hawak ang instruction permit nang hindi bababa sa anim na buwan bago makakuha ng provisional license.","p":"Tama. Anim na buwan ang pinakamaikli."},"ar":{"q":"في New Mexico، كم من الوقت يجب أن تحمل تصريح التعلّم قبل الحصول على الرخصة المؤقتة (provisional license)؟","o":["شهر واحد على الأقل","ثلاثة أشهر على الأقل","ستة أشهر على الأقل","سنتان على الأقل"],"h1":"إنها نصف سنة.","h2":"في New Mexico يجب أن تحمل تصريح التعلّم ستة أشهر على الأقل قبل الحصول على الرخصة المؤقتة.","p":"صحيح. ستة أشهر هي أقل مدة."},"ref":{"doc":"NM","page":1}},{"id":"nm-007","scope":"NM","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Mexico, what happens to the permit waiting period if you get a traffic violation while driving on a permit?","o":["Nothing changes","It starts over from zero","It grows by one year","It grows by 30 days for each violation"],"h1":"Each ticket adds about one month.","h2":"In New Mexico the six-month permit period is extended by 30 days for each traffic violation committed while driving on the permit.","p":"Right. Each violation adds 30 days."},"es":{"q":"En Nuevo México, ¿qué pasa con el período de espera del permiso si comete una infracción de tránsito mientras maneja con permiso?","o":["No cambia nada","Empieza otra vez desde cero","Aumenta un año","Aumenta 30 días por cada infracción"],"h1":"Cada multa agrega más o menos un mes.","h2":"En Nuevo México, el período de seis meses con permiso se alarga 30 días por cada infracción de tránsito cometida mientras maneja con el permiso.","p":"Correcto. Cada infracción agrega 30 días."},"zh":{"q":"在 New Mexico，如果你用学习驾照开车时有交通违规，学习驾照的等待期会怎样？","o":["没有改变","从零重新开始","多一年","每次违规多 30 天"],"h1":"每张罚单大约多一个月。","h2":"在 New Mexico，用学习驾照开车时每有一次交通违规，六个月的学习驾照期就延长 30 天。","p":"对。每次违规多 30 天。"},"vi":{"q":"Ở New Mexico, thời gian chờ của giấy phép tập lái thay đổi thế nào nếu bạn vi phạm luật giao thông khi đang lái bằng giấy phép tập lái?","o":["Không có gì thay đổi","Nó bắt đầu lại từ số không","Nó dài thêm một năm","Nó dài thêm 30 ngày cho mỗi lần vi phạm"],"h1":"Mỗi vé phạt thêm khoảng một tháng.","h2":"Ở New Mexico, thời gian sáu tháng của giấy phép tập lái được kéo dài thêm 30 ngày cho mỗi lần vi phạm luật giao thông khi đang lái bằng giấy phép tập lái.","p":"Đúng. Mỗi lần vi phạm thêm 30 ngày."},"tl":{"q":"Sa New Mexico, ano ang mangyayari sa panahon ng paghihintay ng permit kung magkaroon ka ng traffic violation habang nagmamaneho gamit ang permit?","o":["Walang nagbabago","Magsisimula ulit ito sa zero","Hahaba ito nang isang taon","Hahaba ito nang 30 araw sa bawat violation"],"h1":"Ang bawat tiket ay nagdadagdag ng mga isang buwan.","h2":"Sa New Mexico, ang anim na buwan ng permit ay hahaba nang 30 araw sa bawat traffic violation na nagawa habang nagmamaneho gamit ang permit.","p":"Tama. Ang bawat violation ay nagdadagdag ng 30 araw."},"ar":{"q":"في New Mexico، ماذا يحدث لمدة انتظار التصريح إذا ارتكبت مخالفة مرورية وأنت تقود بتصريح التعلّم؟","o":["لا يتغيّر شيء","تبدأ من الصفر من جديد","تزيد سنة واحدة","تزيد 30 يومًا عن كل مخالفة"],"h1":"كل مخالفة تضيف شهرًا تقريبًا.","h2":"في New Mexico تزيد مدة التصريح البالغة ستة أشهر 30 يومًا عن كل مخالفة مرورية تُرتكب أثناء القيادة بتصريح التعلّم.","p":"صحيح. كل مخالفة تضيف 30 يومًا."},"ref":{"doc":"NM","page":null}},{"id":"nm-008","scope":"NM","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Mexico, how many hours of supervised driving practice do you need before a provisional license?","o":["50 hours","20 hours","30 hours","100 hours"],"h1":"It is a round number between 30 and 100.","h2":"In New Mexico you need a total of 50 hours of supervised driving practice before a provisional license.","p":"Correct. New Mexico asks for 50 hours."},"es":{"q":"En Nuevo México, ¿cuántas horas de práctica supervisada necesita antes de la licencia provisional?","o":["50 horas","20 horas","30 horas","100 horas"],"h1":"Es un número redondo entre 30 y 100.","h2":"En Nuevo México usted necesita un total de 50 horas de práctica supervisada antes de la licencia provisional.","p":"Correcto. Nuevo México pide 50 horas."},"zh":{"q":"在 New Mexico，拿过渡驾照前需要多少小时有人监督的驾驶练习？","o":["50 小时","20 小时","30 小时","100 小时"],"h1":"它是 30 到 100 之间的一个整数。","h2":"在 New Mexico，拿过渡驾照前一共需要 50 小时有人监督的驾驶练习。","p":"对。New Mexico 要求 50 小时。"},"vi":{"q":"Ở New Mexico, bạn cần bao nhiêu giờ tập lái có người giám sát trước khi được bằng lái tạm thời?","o":["50 giờ","20 giờ","30 giờ","100 giờ"],"h1":"Nó là một số tròn ở giữa 30 và 100.","h2":"Ở New Mexico, bạn cần tổng cộng 50 giờ tập lái có người giám sát trước khi được bằng lái tạm thời.","p":"Đúng. New Mexico yêu cầu 50 giờ."},"tl":{"q":"Sa New Mexico, ilang oras ng pagsasanay sa pagmamaneho na may nagbabantay ang kailangan mo bago makakuha ng provisional license?","o":["50 oras","20 oras","30 oras","100 oras"],"h1":"Ito ay isang buong numero sa pagitan ng 30 at 100.","h2":"Sa New Mexico, kailangan mo ng kabuuang 50 oras ng pagsasanay sa pagmamaneho na may nagbabantay bago makakuha ng provisional license.","p":"Tama. Humihingi ang New Mexico ng 50 oras."},"ar":{"q":"في New Mexico، كم ساعة من التدرّب على القيادة مع مشرف تحتاج قبل الحصول على الرخصة المؤقتة؟","o":["50 ساعة","20 ساعة","30 ساعة","100 ساعة"],"h1":"إنه عدد مُقرَّب بين 30 و100.","h2":"في New Mexico تحتاج إلى 50 ساعة في المجموع من التدرّب على القيادة مع مشرف قبل الحصول على الرخصة المؤقتة.","p":"صحيح. تطلب New Mexico 50 ساعة."},"ref":{"doc":"NM","page":1}},{"id":"nm-009","scope":"NM","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Mexico, how many of the supervised practice hours must be at night?","o":["At least 2 hours","At least 10 hours","At least 5 hours","At least 20 hours"],"h1":"It is one fifth of the total.","h2":"In New Mexico at least 10 of the 50 supervised practice hours must be at night.","p":"Right. Ten hours must be at night."},"es":{"q":"En Nuevo México, ¿cuántas de las horas de práctica supervisada deben ser de noche?","o":["Por lo menos 2 horas","Por lo menos 10 horas","Por lo menos 5 horas","Por lo menos 20 horas"],"h1":"Es la quinta parte del total.","h2":"En Nuevo México, por lo menos 10 de las 50 horas de práctica supervisada deben ser de noche.","p":"Correcto. Diez horas deben ser de noche."},"zh":{"q":"在 New Mexico，有人监督的练习时间里，有多少小时必须在晚上？","o":["至少 2 小时","至少 10 小时","至少 5 小时","至少 20 小时"],"h1":"它是全部时间的五分之一。","h2":"在 New Mexico，50 小时有人监督的练习里，至少 10 小时必须在晚上。","p":"对。十小时必须在晚上。"},"vi":{"q":"Ở New Mexico, bao nhiêu giờ tập lái có người giám sát phải là vào ban đêm?","o":["Ít nhất 2 giờ","Ít nhất 10 giờ","Ít nhất 5 giờ","Ít nhất 20 giờ"],"h1":"Nó là một phần năm của tổng số.","h2":"Ở New Mexico, ít nhất 10 trong 50 giờ tập lái có người giám sát phải là vào ban đêm.","p":"Đúng. Mười giờ phải là vào ban đêm."},"tl":{"q":"Sa New Mexico, ilan sa mga oras ng pagsasanay na may nagbabantay ang dapat sa gabi?","o":["Hindi bababa sa 2 oras","Hindi bababa sa 10 oras","Hindi bababa sa 5 oras","Hindi bababa sa 20 oras"],"h1":"Ito ay one fifth (isang ikalima) ng kabuuan.","h2":"Sa New Mexico, hindi bababa sa 10 sa 50 oras ng pagsasanay na may nagbabantay ang dapat sa gabi.","p":"Tama. Sampung oras ang dapat sa gabi."},"ar":{"q":"في New Mexico، كم ساعة من ساعات التدرّب مع مشرف يجب أن تكون في الليل؟","o":["ساعتان على الأقل (2)","10 ساعات على الأقل","5 ساعات على الأقل","20 ساعة على الأقل"],"h1":"إنها خُمس المجموع.","h2":"في New Mexico يجب أن تكون 10 ساعات على الأقل من الـ 50 ساعة من التدرّب مع مشرف في الليل.","p":"صحيح. يجب أن تكون عشر ساعات في الليل."},"ref":{"doc":"NM","page":1}},{"id":"nm-010","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, who must certify in writing that the supervised practice hours are done?","o":["A school teacher","Any friend over 18","A parent or guardian","The permit holder alone"],"h1":"It is the adult legally responsible for the teen.","h2":"In New Mexico a parent or guardian must certify in writing that the 50 supervised practice hours are complete.","p":"Correct. A parent or guardian signs for the hours."},"es":{"q":"En Nuevo México, ¿quién debe certificar por escrito que se completaron las horas de práctica supervisada?","o":["Un maestro de la escuela","Cualquier amigo mayor de 18","Un padre o tutor","Solo quien tiene el permiso"],"h1":"Es el adulto legalmente responsable del joven.","h2":"En Nuevo México, un padre o tutor debe certificar por escrito que se completaron las 50 horas de práctica supervisada.","p":"Correcto. Un padre o tutor firma por las horas."},"zh":{"q":"在 New Mexico，谁必须书面证明有人监督的练习时间已经完成？","o":["学校老师","任何 18 岁以上的朋友","父母或监护人","学习驾照持有人自己"],"h1":"是在法律上对青少年负责的成年人。","h2":"在 New Mexico，父母或监护人必须书面证明 50 小时有人监督的练习已经完成。","p":"对。父母或监护人为练习时间签字。"},"vi":{"q":"Ở New Mexico, ai phải xác nhận bằng văn bản rằng các giờ tập lái có người giám sát đã xong?","o":["Một giáo viên ở trường","Bất kỳ người bạn nào trên 18 tuổi","Cha mẹ hoặc người giám hộ","Chỉ người có giấy phép tập lái"],"h1":"Đó là người lớn chịu trách nhiệm pháp lý cho thanh thiếu niên.","h2":"Ở New Mexico, cha mẹ hoặc người giám hộ phải xác nhận bằng văn bản rằng 50 giờ tập lái có người giám sát đã xong.","p":"Đúng. Cha mẹ hoặc người giám hộ ký xác nhận số giờ."},"tl":{"q":"Sa New Mexico, sino ang dapat magpatunay nang nakasulat na tapos na ang mga oras ng pagsasanay na may nagbabantay?","o":["Isang guro sa paaralan","Kahit sinong kaibigan na higit 18","Isang magulang o guardian","Ang may permit lamang"],"h1":"Siya ang adult na legal na responsable sa teen.","h2":"Sa New Mexico, ang isang magulang o guardian ay dapat magpatunay nang nakasulat na tapos na ang 50 oras ng pagsasanay na may nagbabantay.","p":"Tama. Ang magulang o guardian ang pumipirma para sa mga oras."},"ar":{"q":"في New Mexico، من يجب أن يؤكّد كتابيًا أن ساعات التدرّب مع مشرف قد اكتملت؟","o":["معلّم في المدرسة","أي صديق عمره أكثر من 18","أحد الوالدين أو الوصي","حامل التصريح وحده"],"h1":"إنه الشخص البالغ المسؤول قانونيًا عن المراهق.","h2":"في New Mexico يجب أن يؤكّد أحد الوالدين أو الوصي كتابيًا أن الـ 50 ساعة من التدرّب مع مشرف قد اكتملت.","p":"صحيح. يوقّع أحد الوالدين أو الوصي على الساعات."},"ref":{"doc":"NM","page":1}},{"id":"nm-011","scope":"NM","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Mexico, during which hours is a provisional license holder not allowed to drive, unless an exception applies?","o":["9 p.m. to 5 a.m.","10 p.m. to 6 a.m.","11 p.m. to 4 a.m.","Midnight to 5 a.m."],"h1":"The limit starts when the date changes.","h2":"In New Mexico a provisional license holder may not drive from midnight to 5 a.m. unless an exception applies, such as a licensed driver 21 or older in the vehicle.","p":"Right. No driving from midnight to 5 a.m."},"es":{"q":"En Nuevo México, ¿en qué horario no puede manejar quien tiene licencia provisional, salvo una excepción?","o":["De 9 p.m. a 5 a.m.","De 10 p.m. a 6 a.m.","De 11 p.m. a 4 a.m.","De medianoche a 5 a.m."],"h1":"El límite empieza cuando cambia la fecha.","h2":"En Nuevo México, quien tiene licencia provisional no puede manejar de medianoche a 5 a.m., salvo una excepción, como ir con un conductor con licencia de 21 años o más.","p":"Correcto. No se maneja de medianoche a 5 a.m."},"zh":{"q":"在 New Mexico，除非有例外情况，过渡驾照持有人在哪个时间段不能开车？","o":["晚上 9 点到早上 5 点","晚上 10 点到早上 6 点","晚上 11 点到凌晨 4 点","午夜到早上 5 点"],"h1":"限制从日期改变的时候开始。","h2":"在 New Mexico，过渡驾照持有人从午夜到早上 5 点不能开车，除非有例外情况，比如车里有一位 21 岁或以上、有驾照的司机。","p":"对。午夜到早上 5 点不能开车。"},"vi":{"q":"Ở New Mexico, người có bằng lái tạm thời không được lái xe trong những giờ nào, trừ khi có trường hợp ngoại lệ?","o":["9 giờ tối đến 5 giờ sáng","10 giờ tối đến 6 giờ sáng","11 giờ tối đến 4 giờ sáng","Nửa đêm đến 5 giờ sáng"],"h1":"Giới hạn bắt đầu khi sang ngày mới.","h2":"Ở New Mexico, người có bằng lái tạm thời không được lái xe từ nửa đêm đến 5 giờ sáng, trừ khi có ngoại lệ, ví dụ có một người lái xe có bằng từ 21 tuổi trở lên ở trong xe.","p":"Đúng. Không lái xe từ nửa đêm đến 5 giờ sáng."},"tl":{"q":"Sa New Mexico, sa anong mga oras bawal magmaneho ang may provisional license, maliban kung may exception?","o":["9 p.m. hanggang 5 a.m.","10 p.m. hanggang 6 a.m.","11 p.m. hanggang 4 a.m.","Hatinggabi hanggang 5 a.m."],"h1":"Nagsisimula ang limitasyon kapag nagpalit ang petsa.","h2":"Sa New Mexico, ang may provisional license ay bawal magmaneho mula hatinggabi hanggang 5 a.m. maliban kung may exception, gaya ng lisensiyadong driver na 21 taong gulang pataas na nasa sasakyan.","p":"Tama. Bawal magmaneho mula hatinggabi hanggang 5 a.m."},"ar":{"q":"في New Mexico، في أي ساعات لا يُسمح لحامل الرخصة المؤقتة بالقيادة، إلا إذا كان هناك استثناء؟","o":["من 9 مساءً إلى 5 صباحًا","من 10 مساءً إلى 6 صباحًا","من 11 مساءً إلى 4 صباحًا","من منتصف الليل إلى 5 صباحًا"],"h1":"يبدأ المنع عندما يتغيّر التاريخ.","h2":"في New Mexico لا يجوز لحامل الرخصة المؤقتة أن يقود من منتصف الليل إلى 5 صباحًا إلا إذا كان هناك استثناء، مثل وجود سائق مرخَّص عمره 21 سنة أو أكثر في السيارة.","p":"صحيح. لا قيادة من منتصف الليل إلى 5 صباحًا."},"ref":{"doc":"NM","page":1}},{"id":"nm-012","scope":"NM","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Mexico, a provisional license holder wants to drive at 1 a.m. Which situation allows it?","o":["A licensed driver 21 or older is in the vehicle","A friend 18 years old is in the vehicle","The driver feels wide awake","The roads are empty"],"h1":"Think of the same kind of adult who supervises a permit holder.","h2":"In New Mexico a provisional license holder may drive between midnight and 5 a.m. when a licensed driver 21 or older is in the vehicle.","p":"Correct. An adult driver 21 or older makes it allowed."},"es":{"q":"En Nuevo México, alguien con licencia provisional quiere manejar a la 1 a.m. ¿Qué situación lo permite?","o":["Va en el vehículo un conductor con licencia de 21 años o más","Va en el vehículo un amigo de 18 años","El conductor se siente bien despierto","Las calles están vacías"],"h1":"Piense en el mismo tipo de adulto que supervisa a quien tiene permiso.","h2":"En Nuevo México, quien tiene licencia provisional puede manejar entre medianoche y 5 a.m. si va en el vehículo un conductor con licencia de 21 años o más.","p":"Correcto. Un conductor adulto de 21 años o más lo permite."},"zh":{"q":"在 New Mexico，过渡驾照持有人想在凌晨 1 点开车。哪种情况可以？","o":["车里有一位 21 岁或以上、有驾照的司机","车里有一位 18 岁的朋友","司机觉得很清醒","路上没有车"],"h1":"想想监督学习驾照持有人的是哪种成年人。","h2":"在 New Mexico，如果车里有一位 21 岁或以上、有驾照的司机，过渡驾照持有人可以在午夜到早上 5 点之间开车。","p":"对。有一位 21 岁或以上的成年司机就可以。"},"vi":{"q":"Ở New Mexico, một người có bằng lái tạm thời muốn lái xe lúc 1 giờ sáng. Trường hợp nào cho phép điều đó?","o":["Có một người lái xe có bằng từ 21 tuổi trở lên ở trong xe","Có một người bạn 18 tuổi ở trong xe","Người lái cảm thấy rất tỉnh táo","Đường vắng"],"h1":"Hãy nghĩ đến loại người lớn giống như người giám sát người có giấy phép tập lái.","h2":"Ở New Mexico, người có bằng lái tạm thời được lái xe từ nửa đêm đến 5 giờ sáng khi có một người lái xe có bằng từ 21 tuổi trở lên ở trong xe.","p":"Đúng. Một người lớn có bằng lái từ 21 tuổi trở lên làm cho việc này được phép."},"tl":{"q":"Sa New Mexico, gustong magmaneho ng isang may provisional license nang 1 a.m. Anong sitwasyon ang pumapayag dito?","o":["May lisensiyadong driver na 21 taong gulang pataas sa sasakyan","May kaibigang 18 taong gulang sa sasakyan","Gising na gising ang pakiramdam ng driver","Walang tao sa mga kalsada"],"h1":"Isipin ang parehong uri ng adult na nagbabantay sa may permit.","h2":"Sa New Mexico, ang may provisional license ay puwedeng magmaneho mula hatinggabi hanggang 5 a.m. kapag may lisensiyadong driver na 21 taong gulang pataas sa sasakyan.","p":"Tama. Puwede ito kung may adult na driver na 21 taong gulang pataas."},"ar":{"q":"في New Mexico، يريد حامل رخصة مؤقتة أن يقود في الساعة 1 صباحًا. أي حالة تسمح بذلك؟","o":["وجود سائق مرخَّص عمره 21 سنة أو أكثر في السيارة","وجود صديق عمره 18 سنة في السيارة","شعور السائق بأنه مستيقظ تمامًا","خلوّ الطرق من السيارات"],"h1":"فكّر في نفس نوع الشخص البالغ الذي يشرف على حامل تصريح التعلّم.","h2":"في New Mexico يجوز لحامل الرخصة المؤقتة أن يقود بين منتصف الليل و5 صباحًا عندما يكون في السيارة سائق مرخَّص عمره 21 سنة أو أكثر.","p":"صحيح. وجود سائق بالغ عمره 21 سنة أو أكثر يجعل ذلك مسموحًا."},"ref":{"doc":"NM","page":2}},{"id":"nm-013","scope":"NM","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Mexico, how many passengers under 21 who are not immediate family may a provisional driver carry?","o":["None at all","No more than one","No more than two","No more than three"],"h1":"It is the smallest number that is not zero.","h2":"In New Mexico a provisional driver may carry no more than one passenger under 21 who is not immediate family, unless a licensed driver 21 or older is in the vehicle.","p":"Right. Only one young non-family passenger."},"es":{"q":"En Nuevo México, ¿cuántos pasajeros menores de 21 años que no son familia directa puede llevar un conductor provisional?","o":["Ninguno","No más de uno","No más de dos","No más de tres"],"h1":"Es el número más pequeño que no es cero.","h2":"En Nuevo México, un conductor provisional no puede llevar más de un pasajero menor de 21 años que no sea familia directa, salvo que vaya un conductor con licencia de 21 años o más.","p":"Correcto. Solo un pasajero joven que no sea familia."},"zh":{"q":"在 New Mexico，过渡驾照司机可以载几位不是直系亲属、未满 21 岁的乘客？","o":["一位也不行","不超过一位","不超过两位","不超过三位"],"h1":"它是不等于零的最小数字。","h2":"在 New Mexico，过渡驾照司机最多只能载一位不是直系亲属、未满 21 岁的乘客，除非车里有一位 21 岁或以上、有驾照的司机。","p":"对。只能载一位不是家人的年轻乘客。"},"vi":{"q":"Ở New Mexico, người có bằng lái tạm thời được chở bao nhiêu hành khách dưới 21 tuổi không phải là người thân trong gia đình?","o":["Không ai cả","Không quá một người","Không quá hai người","Không quá ba người"],"h1":"Nó là số nhỏ nhất mà không phải là số không.","h2":"Ở New Mexico, người có bằng lái tạm thời được chở không quá một hành khách dưới 21 tuổi không phải là người thân trong gia đình, trừ khi có một người lái xe có bằng từ 21 tuổi trở lên ở trong xe.","p":"Đúng. Chỉ một hành khách trẻ không phải người thân."},"tl":{"q":"Sa New Mexico, ilang pasahero na wala pang 21 at hindi malapit na kapamilya ang puwedeng isakay ng provisional driver?","o":["Wala talaga","Hindi hihigit sa isa","Hindi hihigit sa dalawa","Hindi hihigit sa tatlo"],"h1":"Ito ang pinakamaliit na numero na hindi zero.","h2":"Sa New Mexico, ang provisional driver ay puwedeng magsakay ng hindi hihigit sa isang pasahero na wala pang 21 at hindi malapit na kapamilya, maliban kung may lisensiyadong driver na 21 taong gulang pataas sa sasakyan.","p":"Tama. Isa lang na batang pasahero na hindi kapamilya."},"ar":{"q":"في New Mexico، كم راكبًا عمره أقل من 21 وليس من العائلة القريبة يجوز للسائق بالرخصة المؤقتة أن ينقل؟","o":["لا أحد أبدًا","راكب واحد فقط على الأكثر","راكبان على الأكثر","ثلاثة ركاب على الأكثر"],"h1":"إنه أصغر عدد غير الصفر.","h2":"في New Mexico يجوز للسائق بالرخصة المؤقتة أن ينقل راكبًا واحدًا على الأكثر عمره أقل من 21 وليس من العائلة القريبة، إلا إذا كان في السيارة سائق مرخَّص عمره 21 سنة أو أكثر.","p":"صحيح. راكب شاب واحد فقط من خارج العائلة."},"ref":{"doc":"NM","page":1}},{"id":"nm-014","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, how long must you hold a provisional license before applying for a full license?","o":["At least 3 months","At least 6 months","At least 12 months","At least 3 years"],"h1":"It is one full year.","h2":"In New Mexico you must hold a provisional license for at least 12 months before applying for a full license.","p":"Correct. It takes at least one year."},"es":{"q":"En Nuevo México, ¿cuánto tiempo debe tener la licencia provisional antes de solicitar la licencia completa?","o":["Por lo menos 3 meses","Por lo menos 6 meses","Por lo menos 12 meses","Por lo menos 3 años"],"h1":"Es un año completo.","h2":"En Nuevo México usted debe tener la licencia provisional por lo menos 12 meses antes de solicitar la licencia completa.","p":"Correcto. Se necesita por lo menos un año."},"zh":{"q":"在 New Mexico，申请正式驾照前，必须持有过渡驾照多久？","o":["至少 3 个月","至少 6 个月","至少 12 个月","至少 3 年"],"h1":"它是整整一年。","h2":"在 New Mexico，你必须持有过渡驾照至少 12 个月，才能申请正式驾照。","p":"对。至少要一年。"},"vi":{"q":"Ở New Mexico, bạn phải giữ bằng lái tạm thời bao lâu trước khi xin bằng lái đầy đủ?","o":["Ít nhất 3 tháng","Ít nhất 6 tháng","Ít nhất 12 tháng","Ít nhất 3 năm"],"h1":"Nó là một năm trọn.","h2":"Ở New Mexico, bạn phải giữ bằng lái tạm thời ít nhất 12 tháng trước khi xin bằng lái đầy đủ.","p":"Đúng. Cần ít nhất một năm."},"tl":{"q":"Sa New Mexico, gaano katagal mo dapat hawak ang provisional license bago mag-apply ng full license?","o":["Hindi bababa sa 3 buwan","Hindi bababa sa 6 na buwan","Hindi bababa sa 12 buwan","Hindi bababa sa 3 taon"],"h1":"Ito ay isang buong taon.","h2":"Sa New Mexico, dapat mong hawak ang provisional license nang hindi bababa sa 12 buwan bago mag-apply ng full license.","p":"Tama. Kailangan ng hindi bababa sa isang taon."},"ar":{"q":"في New Mexico، كم من الوقت يجب أن تحمل الرخصة المؤقتة قبل التقدّم بطلب الرخصة الكاملة؟","o":["3 أشهر على الأقل","6 أشهر على الأقل","12 شهرًا على الأقل","3 سنوات على الأقل"],"h1":"إنها سنة كاملة.","h2":"في New Mexico يجب أن تحمل الرخصة المؤقتة 12 شهرًا على الأقل قبل التقدّم بطلب الرخصة الكاملة.","p":"صحيح. يحتاج ذلك سنة واحدة على الأقل."},"ref":{"doc":"NM","page":2}},{"id":"nm-015","scope":"NM","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Mexico, what score do you need to pass the written test for a car license?","o":["50 percent or better","60 percent or better","90 percent or better","70 percent or better"],"h1":"It is the same as a passing grade of C in many schools.","h2":"In New Mexico you need a score of 70 percent or better to pass the written test.","p":"Right. You need 70 percent."},"es":{"q":"En Nuevo México, ¿qué calificación necesita para aprobar el examen escrito para licencia de auto?","o":["50 por ciento o más","60 por ciento o más","90 por ciento o más","70 por ciento o más"],"h1":"Es como una nota de aprobado en muchas escuelas.","h2":"En Nuevo México usted necesita 70 por ciento o más para aprobar el examen escrito.","p":"Correcto. Se necesita 70 por ciento."},"zh":{"q":"在 New Mexico，小汽车驾照的笔试要得多少分才能通过？","o":["百分之 50 或以上","百分之 60 或以上","百分之 90 或以上","百分之 70 或以上"],"h1":"它和很多学校里及格的 C 等级一样。","h2":"在 New Mexico，笔试要得百分之 70 或以上才能通过。","p":"对。你需要百分之 70。"},"vi":{"q":"Ở New Mexico, bạn cần bao nhiêu điểm để đậu bài thi viết lấy bằng lái xe hơi?","o":["50 phần trăm trở lên","60 phần trăm trở lên","90 phần trăm trở lên","70 phần trăm trở lên"],"h1":"Nó giống như điểm C đủ để đậu ở nhiều trường học.","h2":"Ở New Mexico, bạn cần được 70 phần trăm trở lên để đậu bài thi viết.","p":"Đúng. Bạn cần 70 phần trăm."},"tl":{"q":"Sa New Mexico, anong score ang kailangan mo para pumasa sa written test para sa lisensiya sa kotse?","o":["50 porsiyento o higit pa","60 porsiyento o higit pa","90 porsiyento o higit pa","70 porsiyento o higit pa"],"h1":"Ito ay katulad ng pasadong grade na C sa maraming paaralan.","h2":"Sa New Mexico, kailangan mo ng score na 70 porsiyento o higit pa para pumasa sa written test.","p":"Tama. Kailangan mo ng 70 porsiyento."},"ar":{"q":"في New Mexico، ما الدرجة التي تحتاجها لتنجح في الاختبار الكتابي لرخصة السيارة؟","o":["50 بالمئة أو أكثر","60 بالمئة أو أكثر","90 بالمئة أو أكثر","70 بالمئة أو أكثر"],"h1":"إنها مثل درجة النجاح C في مدارس كثيرة.","h2":"في New Mexico تحتاج إلى درجة 70 بالمئة أو أكثر لتنجح في الاختبار الكتابي.","p":"صحيح. تحتاج إلى 70 بالمئة."},"ref":{"doc":"NM","page":null}},{"id":"nm-016","scope":"NM","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Mexico, in which languages can you take the written knowledge test?","o":["English, Spanish and several other languages","English only","English and Spanish only on weekends","Spanish only at the border"],"h1":"New Mexico offers more than two choices.","h2":"In New Mexico the written test is offered in English, Spanish and several other languages.","p":"Correct. Spanish and other languages are offered."},"es":{"q":"En Nuevo México, ¿en qué idiomas puede tomar el examen escrito de conocimientos?","o":["Inglés, español y varios idiomas más","Solo en inglés","Inglés y español solo los fines de semana","Español solo en la frontera"],"h1":"Nuevo México ofrece más de dos opciones.","h2":"En Nuevo México el examen escrito se ofrece en inglés, español y varios idiomas más.","p":"Correcto. Se ofrece en español y en otros idiomas."},"zh":{"q":"在 New Mexico，笔试（知识考试）可以用哪些语言考？","o":["英语、西班牙语和其他几种语言","只有英语","只在周末有英语和西班牙语","只在边境有西班牙语"],"h1":"New Mexico 提供两种以上的选择。","h2":"在 New Mexico，笔试有英语、西班牙语和其他几种语言。","p":"对。可以用西班牙语和其他语言考。"},"vi":{"q":"Ở New Mexico, bạn có thể làm bài thi kiến thức viết bằng những ngôn ngữ nào?","o":["Tiếng Anh, tiếng Tây Ban Nha và một số ngôn ngữ khác","Chỉ tiếng Anh","Tiếng Anh và tiếng Tây Ban Nha chỉ vào cuối tuần","Chỉ tiếng Tây Ban Nha ở vùng biên giới"],"h1":"New Mexico có nhiều hơn hai lựa chọn.","h2":"Ở New Mexico, bài thi viết có bằng tiếng Anh, tiếng Tây Ban Nha và một số ngôn ngữ khác.","p":"Đúng. Có tiếng Tây Ban Nha và các ngôn ngữ khác."},"tl":{"q":"Sa New Mexico, sa anong mga wika puwede mong kunin ang written knowledge test?","o":["English, Spanish at ilang iba pang wika","English lamang","English at Spanish tuwing weekend lamang","Spanish lamang sa border"],"h1":"Ang New Mexico ay may higit sa dalawang pagpipilian.","h2":"Sa New Mexico, ang written test ay mayroon sa English, Spanish at ilang iba pang wika.","p":"Tama. May Spanish at iba pang wika."},"ar":{"q":"في New Mexico، بأي لغات يمكنك أداء اختبار المعرفة الكتابي؟","o":["الإنجليزية والإسبانية وعدة لغات أخرى","الإنجليزية فقط","الإنجليزية والإسبانية في عطلة نهاية الأسبوع فقط","الإسبانية فقط عند الحدود"],"h1":"تقدّم New Mexico أكثر من خيارين.","h2":"في New Mexico يُقدَّم الاختبار الكتابي بالإنجليزية والإسبانية وعدة لغات أخرى.","p":"صحيح. الإسبانية ولغات أخرى متاحة."},"ref":{"doc":"NM","page":null}},{"id":"nm-017","scope":"NM","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Mexico, who does not need to take the written test when getting a first New Mexico license?","o":["Anyone over 18","Someone with a current license from another state","Anyone who owns a car","Anyone with a permit from another country"],"h1":"They already hold a valid license from a US state.","h2":"In New Mexico the written test is not required if you hold a current driver license from another state.","p":"Right. A current out-of-state license skips the written test."},"es":{"q":"En Nuevo México, ¿quién no necesita tomar el examen escrito al sacar su primera licencia de Nuevo México?","o":["Cualquier persona mayor de 18","Alguien con una licencia vigente de otro estado","Cualquiera que tenga carro propio","Cualquiera con permiso de otro país"],"h1":"Esa persona ya tiene una licencia válida de un estado del país.","h2":"En Nuevo México no se exige el examen escrito si usted tiene una licencia de manejo vigente de otro estado.","p":"Correcto. Con licencia vigente de otro estado no hace falta el examen escrito."},"zh":{"q":"在 New Mexico，第一次拿 New Mexico 驾照时，谁不需要参加笔试？","o":["任何 18 岁以上的人","有其他州有效驾照的人","任何有车的人","任何有外国学习驾照的人"],"h1":"他们已经有美国某个州的有效驾照。","h2":"在 New Mexico，如果你有其他州的有效驾照，就不需要参加笔试。","p":"对。有其他州的有效驾照就不用笔试。"},"vi":{"q":"Ở New Mexico, ai không cần làm bài thi viết khi lấy bằng lái New Mexico lần đầu?","o":["Bất kỳ ai trên 18 tuổi","Người có bằng lái còn hạn của một tiểu bang khác","Bất kỳ ai có xe hơi","Bất kỳ ai có giấy phép từ một nước khác"],"h1":"Họ đã có bằng lái hợp lệ của một tiểu bang ở Mỹ.","h2":"Ở New Mexico, bạn không cần làm bài thi viết nếu bạn có bằng lái còn hạn của một tiểu bang khác.","p":"Đúng. Bằng lái còn hạn của tiểu bang khác thì không cần thi viết."},"tl":{"q":"Sa New Mexico, sino ang hindi kailangang kumuha ng written test kapag kumukuha ng unang lisensiya sa New Mexico?","o":["Kahit sinong higit 18","Isang taong may kasalukuyang lisensiya mula sa ibang estado","Kahit sinong may sariling kotse","Kahit sinong may permit mula sa ibang bansa"],"h1":"May hawak na silang balidong lisensiya mula sa isang estado sa US.","h2":"Sa New Mexico, hindi kailangan ang written test kung may hawak kang kasalukuyang driver license mula sa ibang estado.","p":"Tama. Kung may kasalukuyang lisensiya mula sa ibang estado, hindi na kailangan ang written test."},"ar":{"q":"في New Mexico، من لا يحتاج إلى أداء الاختبار الكتابي عند الحصول على أول رخصة من New Mexico؟","o":["أي شخص عمره أكثر من 18","شخص لديه رخصة سارية من ولاية أخرى","أي شخص يملك سيارة","أي شخص لديه تصريح من بلد آخر"],"h1":"لديه بالفعل رخصة سارية من ولاية أمريكية.","h2":"في New Mexico لا يُطلب الاختبار الكتابي إذا كانت لديك رخصة قيادة سارية من ولاية أخرى.","p":"صحيح. الرخصة السارية من ولاية أخرى تُعفيك من الاختبار الكتابي."},"ref":{"doc":"NM","page":null}},{"id":"nm-018","scope":"NM","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Mexico, what blood or breath alcohol level is illegal for a driver under 21?","o":["0.08 or more","0.05 or more","0.02 or more","0.10 or more"],"h1":"It is far below the adult limit.","h2":"In New Mexico it is illegal for a driver under 21 to drive with an alcohol level of 0.02 or more.","p":"Correct. Under 21, the limit is 0.02."},"es":{"q":"En Nuevo México, ¿qué nivel de alcohol en la sangre o el aliento es ilegal para un conductor menor de 21 años?","o":["0.08 o más","0.05 o más","0.02 o más","0.10 o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Nuevo México es ilegal que un conductor menor de 21 años maneje con un nivel de alcohol de 0.02 o más.","p":"Correcto. Para menores de 21, el límite es 0.02."},"zh":{"q":"在 New Mexico，未满 21 岁的司机血液或呼气酒精浓度到多少是违法的？","o":["0.08 或以上","0.05 或以上","0.02 或以上","0.10 或以上"],"h1":"它比成年人的上限低很多。","h2":"在 New Mexico，未满 21 岁的司机酒精浓度在 0.02 或以上开车是违法的。","p":"对。未满 21 岁，上限是 0.02。"},"vi":{"q":"Ở New Mexico, nồng độ cồn trong máu hoặc hơi thở bao nhiêu là phạm luật đối với người lái xe dưới 21 tuổi?","o":["0.08 trở lên","0.05 trở lên","0.02 trở lên","0.10 trở lên"],"h1":"Nó thấp hơn nhiều so với giới hạn của người lớn.","h2":"Ở New Mexico, người lái xe dưới 21 tuổi lái xe với nồng độ cồn 0.02 trở lên là phạm luật.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa New Mexico, anong antas ng alak sa dugo o hininga ang bawal para sa driver na wala pang 21?","o":["0.08 o higit pa","0.05 o higit pa","0.02 o higit pa","0.10 o higit pa"],"h1":"Ito ay mas mababa nang malaki kaysa sa limit para sa adult.","h2":"Sa New Mexico, bawal sa driver na wala pang 21 na magmaneho nang may antas ng alak na 0.02 o higit pa.","p":"Tama. Kung wala pang 21, ang limit ay 0.02."},"ar":{"q":"في New Mexico، ما نسبة الكحول في الدم أو النَّفَس التي تكون غير قانونية للسائق الذي عمره أقل من 21؟","o":["0.08 أو أكثر","0.05 أو أكثر","0.02 أو أكثر","0.10 أو أكثر"],"h1":"إنها أقل بكثير من الحد المسموح للبالغين.","h2":"في New Mexico من غير القانوني أن يقود سائق عمره أقل من 21 ونسبة الكحول لديه 0.02 أو أكثر.","p":"صحيح. لمن عمره أقل من 21، الحد هو 0.02."},"ref":{"doc":"NM","page":29}},{"id":"nm-019","scope":"NM","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New Mexico, a school bus is stopped with red lights flashing on the opposite side of a road with no median. What must you do?","o":["Keep going, because the bus is on the other side","Slow to 20 mph and pass","Honk and pass carefully","Stop, because you must stop on either side of an undivided road"],"h1":"Only a median or barrier would change the rule.","h2":"In New Mexico you must stop for a school bus with flashing red lights even on the opposite side, unless a median or physical barrier separates you from it.","p":"Right. Without a median, everyone stops."},"es":{"q":"En Nuevo México, un autobús escolar está detenido con luces rojas intermitentes al otro lado de una calle sin mediana. ¿Qué debe hacer?","o":["Seguir, porque el autobús está del otro lado","Bajar a 20 mph y pasar","Tocar la bocina y pasar con cuidado","Detenerse, porque en una calle sin división se detiene de los dos lados"],"h1":"Solo una mediana o barrera cambiaría la regla.","h2":"En Nuevo México debe detenerse ante un autobús escolar con luces rojas intermitentes aunque esté del otro lado, salvo que lo separe una mediana o barrera física.","p":"Correcto. Sin mediana, todos se detienen."},"zh":{"q":"在 New Mexico，一条没有中间隔离带的路上，对面停着一辆闪着红灯的校车。你必须怎么做？","o":["继续开，因为校车在对面","减速到 20 mph 然后经过","按喇叭然后小心经过","停车，因为在没有分隔的路上，两边都必须停车"],"h1":"只有中间隔离带或障碍物才会改变规定。","h2":"在 New Mexico，就算校车在对面，只要它闪着红灯，你也必须停车，除非有中间隔离带或实体障碍物把你和它分开。","p":"对。没有中间隔离带，所有人都要停车。"},"vi":{"q":"Ở New Mexico, một xe buýt trường học đang dừng và nháy đèn đỏ ở phía bên kia của một con đường không có dải phân cách. Bạn phải làm gì?","o":["Cứ đi tiếp, vì xe buýt ở phía bên kia","Giảm còn 20 mph và vượt qua","Bấm còi và vượt qua cẩn thận","Dừng lại, vì bạn phải dừng ở cả hai phía của đường không có dải phân cách"],"h1":"Chỉ có dải phân cách hoặc rào chắn mới làm thay đổi luật.","h2":"Ở New Mexico, bạn phải dừng lại khi xe buýt trường học nháy đèn đỏ, ngay cả khi nó ở phía bên kia đường, trừ khi có dải phân cách hoặc rào chắn ngăn cách bạn với xe buýt.","p":"Đúng. Không có dải phân cách thì mọi người đều dừng."},"tl":{"q":"Sa New Mexico, may school bus na nakahinto at kumikislap ang pulang ilaw sa kabilang panig ng daan na walang median (harang sa gitna). Ano ang dapat mong gawin?","o":["Tuloy lang, dahil nasa kabilang panig ang bus","Bumagal sa 20 mph at lumampas","Bumusina at lumampas nang maingat","Huminto, dahil dapat kang huminto sa alinmang panig ng daan na walang harang sa gitna"],"h1":"Median o harang lamang ang makapagbabago ng patakaran.","h2":"Sa New Mexico, dapat kang huminto para sa school bus na may kumikislap na pulang ilaw kahit nasa kabilang panig ito, maliban kung may median o pisikal na harang sa pagitan ninyo.","p":"Tama. Kung walang median, lahat ay humihinto."},"ar":{"q":"في New Mexico، حافلة مدرسية متوقفة وأضواؤها الحمراء تومض على الجانب المقابل من طريق ليس فيه فاصل في الوسط (median). ماذا يجب أن تفعل؟","o":["أكمل السير، لأن الحافلة على الجانب الآخر","خفّف السرعة إلى 20 mph وتجاوزها","اضغط على البوق وتجاوز بحذر","توقّف، لأنه يجب التوقف على الجانبين في الطريق غير المقسوم"],"h1":"فقط الفاصل في الوسط أو الحاجز يغيّر القاعدة.","h2":"في New Mexico يجب أن تتوقف للحافلة المدرسية التي تومض أضواؤها الحمراء حتى لو كانت على الجانب المقابل، إلا إذا كان بينك وبينها فاصل في الوسط أو حاجز مادي.","p":"صحيح. بدون فاصل في الوسط، يتوقف الجميع."},"ref":{"doc":"NM","page":12}},{"id":"nm-020","scope":"NM","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In New Mexico, when do you not have to stop for a school bus with flashing red lights?","o":["When it is coming toward you and a median or barrier separates the roads","When you are behind it","When it is at an intersection ahead","When you are late for work"],"h1":"It depends on the bus's direction and what lies between you.","h2":"In New Mexico you do not have to stop when the school bus is traveling toward you on a road separated by a median or other physical barrier.","p":"Correct. A median and opposite direction mean no stop."},"es":{"q":"En Nuevo México, ¿cuándo no tiene que detenerse por un autobús escolar con luces rojas intermitentes?","o":["Cuando viene hacia usted y una mediana o barrera separa los carriles","Cuando usted va detrás de él","Cuando está en una intersección adelante","Cuando usted va tarde al trabajo"],"h1":"Depende de la dirección del autobús y de lo que hay entre ustedes.","h2":"En Nuevo México no tiene que detenerse cuando el autobús escolar viene hacia usted por una vía separada por una mediana u otra barrera física.","p":"Correcto. Con mediana y en dirección contraria, no se detiene."},"zh":{"q":"在 New Mexico，什么时候不用为闪着红灯的校车停车？","o":["校车朝你开过来，而且中间隔离带或障碍物把道路分开时","你在校车后面时","校车在前面路口时","你上班要迟到时"],"h1":"这要看校车的方向，和你们中间有什么。","h2":"在 New Mexico，如果校车在有中间隔离带或其他实体障碍物分开的路上朝你开过来，你不用停车。","p":"对。有中间隔离带，而且方向相反，就不用停车。"},"vi":{"q":"Ở New Mexico, khi nào bạn không phải dừng lại cho xe buýt trường học đang nháy đèn đỏ?","o":["Khi nó đang chạy về phía bạn và có dải phân cách hoặc rào chắn ngăn cách hai bên đường","Khi bạn ở phía sau nó","Khi nó ở ngã tư phía trước","Khi bạn bị trễ giờ làm"],"h1":"Nó phụ thuộc vào hướng đi của xe buýt và những gì ở giữa bạn và xe buýt.","h2":"Ở New Mexico, bạn không phải dừng lại khi xe buýt trường học đang chạy về phía bạn trên con đường có dải phân cách hoặc rào chắn khác ngăn cách.","p":"Đúng. Có dải phân cách và đi ngược chiều thì không cần dừng."},"tl":{"q":"Sa New Mexico, kailan hindi mo kailangang huminto para sa school bus na may kumikislap na pulang ilaw?","o":["Kapag papunta ito sa direksiyon mo at may median o harang sa pagitan ng mga daan","Kapag nasa likod ka nito","Kapag nasa intersection ito sa unahan","Kapag late ka na sa trabaho"],"h1":"Depende ito sa direksiyon ng bus at kung ano ang nasa pagitan ninyo.","h2":"Sa New Mexico, hindi mo kailangang huminto kapag ang school bus ay papunta sa direksiyon mo sa daan na may median o ibang pisikal na harang sa pagitan.","p":"Tama. Kung may median at kabilang direksiyon, hindi kailangang huminto."},"ar":{"q":"في New Mexico، متى لا يكون عليك أن تتوقف لحافلة مدرسية تومض أضواؤها الحمراء؟","o":["عندما تكون قادمة نحوك ويفصل بين الطريقين فاصل في الوسط أو حاجز","عندما تكون خلفها","عندما تكون عند تقاطع أمامك","عندما تكون متأخرًا عن العمل"],"h1":"يعتمد ذلك على اتجاه الحافلة وعلى ما يوجد بينك وبينها.","h2":"في New Mexico ليس عليك أن تتوقف عندما تكون الحافلة المدرسية قادمة نحوك على طريق يفصله فاصل في الوسط أو حاجز مادي آخر.","p":"صحيح. الفاصل في الوسط مع الاتجاه المعاكس يعني عدم التوقف."},"ref":{"doc":"NM","page":12}},{"id":"nm-021","scope":"NM","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Mexico, what does state law say about texting while driving?","o":["It is allowed at speeds under 30 mph","It is against the law to read or type text messages while driving","It is allowed on rural roads","It is only a warning, never a fine"],"h1":"It carries a fine.","h2":"In New Mexico it is against the law to read, view or type text messages on a phone while driving, and it carries a fine.","p":"Right. Texting while driving is illegal."},"es":{"q":"En Nuevo México, ¿qué dice la ley estatal sobre los mensajes de texto al manejar?","o":["Se permite a menos de 30 mph","Es ilegal leer o escribir mensajes de texto mientras maneja","Se permite en caminos rurales","Es solo una advertencia, nunca una multa"],"h1":"Tiene una multa.","h2":"En Nuevo México es ilegal leer, ver o escribir mensajes de texto en un teléfono mientras maneja, y tiene una multa.","p":"Correcto. Escribir mensajes al manejar es ilegal."},"zh":{"q":"在 New Mexico，州法律对开车时发短信是怎么规定的？","o":["车速低于 30 mph 时可以","开车时看或打短信是违法的","在乡村道路上可以","只会警告，不会罚款"],"h1":"它会被罚款。","h2":"在 New Mexico，开车时在手机上看、读或打短信是违法的，会被罚款。","p":"对。开车时发短信是违法的。"},"vi":{"q":"Ở New Mexico, luật tiểu bang nói gì về việc nhắn tin khi lái xe?","o":["Được phép khi chạy dưới 30 mph","Đọc hoặc gõ tin nhắn khi lái xe là phạm luật","Được phép trên đường nông thôn","Chỉ bị cảnh cáo, không bao giờ bị phạt tiền"],"h1":"Nó bị phạt tiền.","h2":"Ở New Mexico, đọc, xem hoặc gõ tin nhắn trên điện thoại khi lái xe là phạm luật và bị phạt tiền.","p":"Đúng. Nhắn tin khi lái xe là phạm luật."},"tl":{"q":"Sa New Mexico, ano ang sinasabi ng batas ng estado tungkol sa pag-text habang nagmamaneho?","o":["Puwede ito kapag ang bilis ay mas mababa sa 30 mph","Labag sa batas ang magbasa o mag-type ng text message habang nagmamaneho","Puwede ito sa mga daan sa probinsiya","Babala lang ito, hindi kailanman multa"],"h1":"May multa ito.","h2":"Sa New Mexico, labag sa batas ang magbasa, tumingin o mag-type ng text message sa telepono habang nagmamaneho, at may multa ito.","p":"Tama. Bawal ang pag-text habang nagmamaneho."},"ar":{"q":"في New Mexico، ماذا يقول قانون الولاية عن كتابة الرسائل النصية أثناء القيادة؟","o":["إنها مسموحة بسرعة أقل من 30 mph","من المخالف للقانون قراءة أو كتابة الرسائل النصية أثناء القيادة","إنها مسموحة على الطرق الريفية","إنها تحذير فقط، ولا غرامة أبدًا"],"h1":"عليها غرامة.","h2":"في New Mexico من المخالف للقانون قراءة الرسائل النصية أو مشاهدتها أو كتابتها على الهاتف أثناء القيادة، وعليها غرامة.","p":"صحيح. كتابة الرسائل النصية أثناء القيادة مخالفة للقانون."},"ref":{"doc":"NM","page":null}},{"id":"nm-022","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, what happens if a driver gets 12 or more points within 12 months?","o":["A warning letter only","A 30-day suspension","A one-year suspension","A fine but no suspension"],"h1":"The suspension lasts as long as the period the points are counted in.","h2":"In New Mexico, a driver with 12 or more points within 12 months has the license suspended for one year.","p":"Right. 12 points in a year means a one-year suspension."},"es":{"q":"En Nuevo México, ¿qué pasa si un conductor acumula 12 puntos o más en 12 meses?","o":["Solo una carta de advertencia","Una suspensión de 30 días","Una suspensión de un año","Una multa pero sin suspensión"],"h1":"La suspensión dura lo mismo que el período en que se cuentan los puntos.","h2":"En Nuevo México, a un conductor con 12 puntos o más en 12 meses le suspenden la licencia por un año.","p":"Correcto. 12 puntos en un año significan una suspensión de un año."},"zh":{"q":"在 New Mexico，如果司机在 12 个月内被记 12 分或更多，会怎样？","o":["只收到一封警告信","暂停驾照 30 天","暂停驾照一年","罚款，但不暂停驾照"],"h1":"暂停的时间和计算分数的时间一样长。","h2":"在 New Mexico，司机在 12 个月内被记 12 分或更多，驾照会被暂停一年。","p":"对。一年内 12 分，就会暂停驾照一年。"},"vi":{"q":"Ở New Mexico, điều gì xảy ra nếu một tài xế bị 12 điểm trở lên trong vòng 12 tháng?","o":["Chỉ nhận một thư cảnh cáo","Bị đình chỉ bằng lái 30 ngày","Bị đình chỉ bằng lái một năm","Bị phạt tiền nhưng không bị đình chỉ"],"h1":"Thời gian đình chỉ dài bằng khoảng thời gian tính điểm.","h2":"Ở New Mexico, tài xế bị 12 điểm trở lên trong vòng 12 tháng sẽ bị đình chỉ bằng lái một năm.","p":"Đúng. 12 điểm trong một năm nghĩa là bị đình chỉ một năm."},"tl":{"q":"Sa New Mexico, ano ang mangyayari kung ang isang driver ay magkaroon ng 12 puntos o higit pa sa loob ng 12 buwan?","o":["Isang sulat ng babala lang","Suspensyon ng 30 araw","Suspensyon ng isang taon","Multa pero walang suspensyon"],"h1":"Ang haba ng suspensyon ay kapareho ng panahon kung kailan binibilang ang mga puntos.","h2":"Sa New Mexico, ang driver na may 12 puntos o higit pa sa loob ng 12 buwan ay masususpinde ang lisensya nang isang taon.","p":"Tama. Ang 12 puntos sa isang taon ay nangangahulugang suspensyon ng isang taon."},"ar":{"q":"في New Mexico، ماذا يحدث إذا حصل السائق على 12 نقطة أو أكثر خلال 12 شهرًا؟","o":["رسالة تحذير فقط","إيقاف الرخصة لمدة 30 يومًا","إيقاف الرخصة لمدة سنة واحدة","غرامة بدون إيقاف"],"h1":"مدة الإيقاف تساوي المدة التي تُحسب فيها النقاط.","h2":"في New Mexico، السائق الذي يحصل على 12 نقطة أو أكثر خلال 12 شهرًا تُوقف رخصته لمدة سنة واحدة.","p":"صحيح. 12 نقطة في سنة تعني إيقاف الرخصة لمدة سنة."},"ref":{"doc":"NM","page":14}},{"id":"nm-023","scope":"NM","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Mexico, what can happen if you refuse an alcohol test when a police officer asks?","o":["You can lose your license for one year","Nothing, the test is your choice","You get a warning the first time","You only pay a small fine"],"h1":"Saying no to the test has its own penalty.","h2":"In New Mexico, if you refuse a blood alcohol test when an officer asks, you can lose your driver license for one year.","p":"Right. Refusing the test can cost your license for a year."},"es":{"q":"En Nuevo México, ¿qué puede pasar si usted se niega a una prueba de alcohol cuando un policía se la pide?","o":["Puede perder su licencia por un año","Nada, la prueba es opcional","Recibe una advertencia la primera vez","Solo paga una multa pequeña"],"h1":"Negarse a la prueba tiene su propio castigo.","h2":"En Nuevo México, si usted se niega a una prueba de alcohol en la sangre cuando un policía se la pide, puede perder su licencia de manejar por un año.","p":"Correcto. Negarse a la prueba puede costarle la licencia por un año."},"zh":{"q":"在 New Mexico，如果警察要求你做酒精测试而你拒绝，会发生什么？","o":["你可能失去驾照一年","什么都不会发生，测试由你决定","第一次只会收到警告","你只需要付一小笔罚款"],"h1":"拒绝测试本身就有惩罚。","h2":"在 New Mexico，如果警察要求你做血液酒精测试而你拒绝，你可能失去驾照一年。","p":"对。拒绝测试可能让你失去驾照一年。"},"vi":{"q":"Ở New Mexico, điều gì có thể xảy ra nếu bạn từ chối kiểm tra nồng độ cồn khi cảnh sát yêu cầu?","o":["Bạn có thể bị mất bằng lái một năm","Không có gì, kiểm tra là do bạn chọn","Bạn bị cảnh cáo trong lần đầu","Bạn chỉ phải trả một khoản phạt nhỏ"],"h1":"Từ chối kiểm tra cũng có hình phạt riêng.","h2":"Ở New Mexico, nếu bạn từ chối kiểm tra nồng độ cồn trong máu khi cảnh sát yêu cầu, bạn có thể bị mất bằng lái một năm.","p":"Đúng. Từ chối kiểm tra có thể khiến bạn mất bằng lái một năm."},"tl":{"q":"Sa New Mexico, ano ang puwedeng mangyari kung tumanggi ka sa alcohol test kapag hiniling ng pulis?","o":["Puwede kang mawalan ng lisensya nang isang taon","Wala, ikaw ang pipili kung magpapa-test ka","Babala ang makukuha mo sa unang beses","Maliit na multa lang ang babayaran mo"],"h1":"May sariling parusa ang pagtanggi sa test.","h2":"Sa New Mexico, kung tumanggi ka sa blood alcohol test kapag hiniling ng pulis, puwede kang mawalan ng driver license nang isang taon.","p":"Tama. Ang pagtanggi sa test ay puwedeng magpawala ng lisensya mo nang isang taon."},"ar":{"q":"في New Mexico، ماذا يمكن أن يحدث إذا رفضت اختبار الكحول عندما يطلبه منك شرطي؟","o":["يمكن أن تفقد رخصتك لمدة سنة واحدة","لا شيء، الاختبار باختيارك","تحصل على تحذير في المرة الأولى","تدفع غرامة صغيرة فقط"],"h1":"رفض الاختبار له عقوبة خاصة به.","h2":"في New Mexico، إذا رفضت اختبار الكحول في الدم عندما يطلبه منك شرطي، يمكن أن تفقد رخصة القيادة لمدة سنة واحدة.","p":"صحيح. رفض الاختبار يمكن أن يفقدك رخصتك لمدة سنة."},"ref":{"doc":"NM","page":29}},{"id":"nm-024","scope":"NM","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Mexico, what is the top speed on rural interstate highways unless a sign says otherwise?","o":["55 mph","60 mph","65 mph","75 mph"],"h1":"Open country interstates have the highest limit in the state.","h2":"In New Mexico, the speed limit on rural interstate highways is 75 mph unless a different limit is posted.","p":"Right. Rural interstates allow 75 mph."},"es":{"q":"En Nuevo México, ¿cuál es la velocidad máxima en las autopistas interestatales rurales si no hay un letrero que diga otra cosa?","o":["55 mph","60 mph","65 mph","75 mph"],"h1":"Las interestatales en el campo tienen el límite más alto del estado.","h2":"En Nuevo México, el límite de velocidad en las autopistas interestatales rurales es de 75 mph, a menos que un letrero indique otro límite.","p":"Correcto. En las interestatales rurales se permiten 75 mph."},"zh":{"q":"在 New Mexico，如果没有标志另行规定，乡村州际公路的最高速度是多少？","o":["55 mph","60 mph","65 mph","75 mph"],"h1":"乡村的州际公路有全州最高的限速。","h2":"在 New Mexico，除非标志写着不同的限速，乡村州际公路的限速是 75 mph。","p":"对。乡村州际公路可以开到 75 mph。"},"vi":{"q":"Ở New Mexico, tốc độ tối đa trên xa lộ liên bang ở vùng nông thôn là bao nhiêu nếu không có biển báo khác?","o":["55 mph","60 mph","65 mph","75 mph"],"h1":"Xa lộ liên bang ở vùng quê có giới hạn cao nhất trong tiểu bang.","h2":"Ở New Mexico, giới hạn tốc độ trên xa lộ liên bang ở vùng nông thôn là 75 mph, trừ khi có biển báo giới hạn khác.","p":"Đúng. Xa lộ liên bang ở nông thôn cho phép 75 mph."},"tl":{"q":"Sa New Mexico, ano ang pinakamataas na bilis sa mga rural interstate highway kung walang karatulang nagsasabi ng iba?","o":["55 mph","60 mph","65 mph","75 mph"],"h1":"Ang mga interstate sa probinsya ang may pinakamataas na limit sa estado.","h2":"Sa New Mexico, ang speed limit sa mga rural interstate highway ay 75 mph maliban kung may ibang limit na nakapaskil.","p":"Tama. Pinapayagan ang 75 mph sa mga rural interstate."},"ar":{"q":"في New Mexico، ما السرعة القصوى على الطرق السريعة بين الولايات في المناطق الريفية إذا لم تقل لافتة غير ذلك؟","o":["55 mph","60 mph","65 mph","75 mph"],"h1":"الطرق السريعة بين الولايات في الريف لها أعلى حد سرعة في الولاية.","h2":"في New Mexico، حد السرعة على الطرق السريعة بين الولايات في المناطق الريفية هو 75 mph إلا إذا كانت هناك لافتة بحد مختلف.","p":"صحيح. يُسمح بسرعة 75 mph على الطرق السريعة الريفية بين الولايات."},"ref":{"doc":"NM","page":12}},{"id":"nm-025","scope":"NM","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Mexico, what is the speed limit in a posted school zone?","o":["10 mph","15 mph","25 mph","30 mph"],"h1":"It is lower than the limit on a normal city street.","h2":"In New Mexico, the speed limit in a posted school zone is 15 mph.","p":"Right. School zones are 15 mph."},"es":{"q":"En Nuevo México, ¿cuál es el límite de velocidad en una zona escolar señalizada?","o":["10 mph","15 mph","25 mph","30 mph"],"h1":"Es más bajo que el límite en una calle normal de la ciudad.","h2":"En Nuevo México, el límite de velocidad en una zona escolar señalizada es de 15 mph.","p":"Correcto. En las zonas escolares el límite es 15 mph."},"zh":{"q":"在 New Mexico，有标志的学校区限速是多少？","o":["10 mph","15 mph","25 mph","30 mph"],"h1":"它比普通城市街道的限速低。","h2":"在 New Mexico，有标志的学校区限速是 15 mph。","p":"对。学校区限速是 15 mph。"},"vi":{"q":"Ở New Mexico, giới hạn tốc độ trong khu vực trường học có biển báo là bao nhiêu?","o":["10 mph","15 mph","25 mph","30 mph"],"h1":"Nó thấp hơn giới hạn trên một con đường bình thường trong thành phố.","h2":"Ở New Mexico, giới hạn tốc độ trong khu vực trường học có biển báo là 15 mph.","p":"Đúng. Khu vực trường học giới hạn 15 mph."},"tl":{"q":"Sa New Mexico, ano ang speed limit sa school zone na may karatula?","o":["10 mph","15 mph","25 mph","30 mph"],"h1":"Mas mababa ito kaysa sa limit sa karaniwang kalye sa lungsod.","h2":"Sa New Mexico, ang speed limit sa school zone na may karatula ay 15 mph.","p":"Tama. 15 mph ang limit sa mga school zone."},"ar":{"q":"في New Mexico، ما حد السرعة في منطقة مدرسية عليها لافتة؟","o":["10 mph","15 mph","25 mph","30 mph"],"h1":"إنه أقل من حد السرعة في شارع عادي في المدينة.","h2":"في New Mexico، حد السرعة في منطقة مدرسية عليها لافتة هو 15 mph.","p":"صحيح. حد السرعة في المناطق المدرسية هو 15 mph."},"ref":{"doc":"NM","page":12}},{"id":"nm-026","scope":"NM","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Mexico, what is the minimum insurance for damage to other people's property in one crash?","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"It is the smallest of the three required amounts.","h2":"In New Mexico, liability insurance must cover at least $10,000 for property damage, $25,000 for injury to one person, and $50,000 for two or more people in one crash.","p":"Right. Property damage coverage starts at $10,000."},"es":{"q":"En Nuevo México, ¿cuál es el seguro mínimo por daños a la propiedad de otras personas en un choque?","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"Es la más pequeña de las tres cantidades requeridas.","h2":"En Nuevo México, el seguro de responsabilidad debe cubrir al menos $10,000 por daños a la propiedad, $25,000 por lesiones a una persona y $50,000 por dos o más personas en un choque.","p":"Correcto. La cobertura por daños a la propiedad empieza en $10,000."},"zh":{"q":"在 New Mexico，一次车祸中对他人财产损失的最低保险金额是多少？","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"它是三个规定金额中最小的。","h2":"在 New Mexico，责任保险至少要赔付财产损失 $10,000、一人受伤 $25,000、一次车祸中两人或更多人受伤 $50,000。","p":"对。财产损失的保险从 $10,000 起。"},"vi":{"q":"Ở New Mexico, bảo hiểm tối thiểu cho thiệt hại tài sản của người khác trong một vụ tai nạn là bao nhiêu?","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"Đó là số nhỏ nhất trong ba số tiền bắt buộc.","h2":"Ở New Mexico, bảo hiểm trách nhiệm phải chi trả ít nhất $10,000 cho thiệt hại tài sản, $25,000 cho thương tích của một người, và $50,000 cho hai người trở lên trong một vụ tai nạn.","p":"Đúng. Bảo hiểm thiệt hại tài sản bắt đầu từ $10,000."},"tl":{"q":"Sa New Mexico, ano ang pinakamababang insurance para sa pinsala sa ari-arian ng ibang tao sa isang banggaan?","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"Ito ang pinakamaliit sa tatlong kinakailangang halaga.","h2":"Sa New Mexico, ang liability insurance ay dapat sumagot ng hindi bababa sa $10,000 para sa pinsala sa ari-arian, $25,000 para sa pinsala sa isang tao, at $50,000 para sa dalawa o higit pang tao sa isang banggaan.","p":"Tama. Nagsisimula sa $10,000 ang coverage para sa pinsala sa ari-arian."},"ar":{"q":"في New Mexico، ما الحد الأدنى للتأمين على الأضرار بممتلكات الآخرين في حادث واحد؟","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"إنه أصغر المبالغ الثلاثة المطلوبة.","h2":"في New Mexico، يجب أن يغطي تأمين المسؤولية على الأقل $10,000 لأضرار الممتلكات، و$25,000 لإصابة شخص واحد، و$50,000 لشخصين أو أكثر في حادث واحد.","p":"صحيح. تبدأ تغطية أضرار الممتلكات من $10,000."},"ref":{"doc":"NM","page":35}},{"id":"nm-027","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, how long must you go without a traffic conviction before you apply for a provisional license?","o":["7 days","30 days","90 days","One year"],"h1":"It is about three months.","h2":"In New Mexico, you must have no traffic conviction in the 90 days before you apply for a provisional license.","p":"Right. You need 90 days with no traffic conviction."},"es":{"q":"En Nuevo México, ¿cuánto tiempo debe pasar sin una condena de tránsito antes de solicitar una licencia provisional?","o":["7 días","30 días","90 días","Un año"],"h1":"Son unos tres meses.","h2":"En Nuevo México, usted no debe tener ninguna condena de tránsito en los 90 días antes de solicitar una licencia provisional.","p":"Correcto. Necesita 90 días sin condenas de tránsito."},"zh":{"q":"在 New Mexico，申请临时驾照（provisional license）前，你必须多长时间没有交通定罪？","o":["7 天","30 天","90 天","一年"],"h1":"大约是三个月。","h2":"在 New Mexico，申请临时驾照前的 90 天内，你必须没有任何交通定罪。","p":"对。你需要 90 天没有交通定罪。"},"vi":{"q":"Ở New Mexico, bạn phải không bị kết tội vi phạm giao thông trong bao lâu trước khi xin bằng lái tạm thời (provisional license)?","o":["7 ngày","30 ngày","90 ngày","Một năm"],"h1":"Khoảng ba tháng.","h2":"Ở New Mexico, bạn không được có bất kỳ lần bị kết tội vi phạm giao thông nào trong 90 ngày trước khi xin bằng lái tạm thời.","p":"Đúng. Bạn cần 90 ngày không bị kết tội vi phạm giao thông."},"tl":{"q":"Sa New Mexico, gaano katagal ka dapat walang traffic conviction bago ka mag-apply ng provisional license?","o":["7 araw","30 araw","90 araw","Isang taon"],"h1":"Mga tatlong buwan ito.","h2":"Sa New Mexico, dapat wala kang traffic conviction sa loob ng 90 araw bago ka mag-apply ng provisional license.","p":"Tama. Kailangan mo ng 90 araw na walang traffic conviction."},"ar":{"q":"في New Mexico، كم من الوقت يجب أن تمضي بدون إدانة مرورية قبل أن تتقدّم بطلب رخصة مؤقتة (provisional license)؟","o":["7 أيام","30 يومًا","90 يومًا","سنة واحدة"],"h1":"إنها حوالي ثلاثة أشهر.","h2":"في New Mexico، يجب ألا تكون لديك أي إدانة مرورية خلال الـ 90 يومًا التي تسبق تقديم طلب الرخصة المؤقتة.","p":"صحيح. تحتاج إلى 90 يومًا بدون إدانة مرورية."},"ref":{"doc":"NM","page":2}},{"id":"nm-028","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, when may you renew your driver license?","o":["Only on the day it expires","Only in the month after it expires","From 90 days before until 30 days after it expires","Any time up to one year after it expires"],"h1":"You can renew a few months early, and a short time late.","h2":"In New Mexico you may renew your driver license from 90 days before it expires until 30 days after it expires.","p":"Right. Renew from 90 days before to 30 days after the expiration date."},"es":{"q":"En Nuevo México, ¿cuándo puede renovar su licencia de conducir?","o":["Solo el día en que vence","Solo en el mes después de que vence","Desde 90 días antes hasta 30 días después de que vence","En cualquier momento hasta un año después de que vence"],"h1":"Puede renovar unos meses antes y un poco tarde.","h2":"En Nuevo México usted puede renovar su licencia de conducir desde 90 días antes de que venza hasta 30 días después de que venza.","p":"Correcto. Se renueva desde 90 días antes hasta 30 días después del vencimiento."},"zh":{"q":"在 New Mexico，你什么时候可以更新（续期）驾照？","o":["只能在驾照到期的那一天","只能在驾照到期后的那个月","从到期前 90 天到到期后 30 天","到期后一年内的任何时间"],"h1":"你可以提前几个月更新，也可以晚一点点更新。","h2":"在 New Mexico，你可以从驾照到期前 90 天到到期后 30 天之间更新驾照。","p":"对。从到期日前 90 天到到期日后 30 天都可以更新。"},"vi":{"q":"Ở New Mexico, khi nào bạn có thể gia hạn bằng lái xe?","o":["Chỉ vào ngày bằng lái hết hạn","Chỉ trong tháng sau khi bằng lái hết hạn","Từ 90 ngày trước cho đến 30 ngày sau khi bằng lái hết hạn","Bất cứ lúc nào cho đến một năm sau khi bằng lái hết hạn"],"h1":"Bạn có thể gia hạn sớm vài tháng, và trễ một chút.","h2":"Ở New Mexico, bạn có thể gia hạn bằng lái xe từ 90 ngày trước khi hết hạn cho đến 30 ngày sau khi hết hạn.","p":"Đúng. Gia hạn từ 90 ngày trước đến 30 ngày sau ngày hết hạn."},"tl":{"q":"Sa New Mexico, kailan mo puwedeng i-renew ang iyong driver license?","o":["Sa mismong araw lang na mag-e-expire ito","Sa buwan lang pagkatapos itong mag-expire","Mula 90 araw bago hanggang 30 araw pagkatapos itong mag-expire","Kahit kailan hanggang isang taon pagkatapos itong mag-expire"],"h1":"Puwede kang mag-renew nang ilang buwan na mas maaga, at nang medyo huli.","h2":"Sa New Mexico, puwede mong i-renew ang iyong driver license mula 90 araw bago ito mag-expire hanggang 30 araw pagkatapos itong mag-expire.","p":"Tama. Mag-renew mula 90 araw bago hanggang 30 araw pagkatapos ng expiration date."},"ar":{"q":"في New Mexico، متى يمكنك تجديد رخصة القيادة؟","o":["فقط في يوم انتهائها","فقط في الشهر الذي يلي انتهاءها","من 90 يومًا قبل انتهائها حتى 30 يومًا بعد انتهائها","في أي وقت حتى سنة واحدة بعد انتهائها"],"h1":"يمكنك التجديد قبل الموعد ببضعة أشهر، وبعده بوقت قصير.","h2":"في New Mexico يمكنك تجديد رخصة القيادة من 90 يومًا قبل انتهائها حتى 30 يومًا بعد انتهائها.","p":"صحيح. جدّد الرخصة من 90 يومًا قبل تاريخ الانتهاء حتى 30 يومًا بعده."},"ref":{"doc":"NM","page":2}},{"id":"nm-029","scope":"NM","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Mexico, what vision do you need to pass the vision test for a driver license?","o":["At least 20/40 in at least one eye, with or without glasses","At least 20/20 in both eyes, without glasses","At least 20/100 in both eyes","At least 20/40 in both eyes, without glasses"],"h1":"You may wear glasses or contacts, and one eye can be enough.","h2":"In New Mexico you need at least 20/40 vision in at least one eye, with or without glasses or contact lenses, to get a driver license.","p":"Right. You need 20/40 in at least one eye, and glasses are allowed."},"es":{"q":"En Nuevo México, ¿qué visión necesita para pasar el examen de la vista para una licencia de conducir?","o":["Por lo menos 20/40 en al menos un ojo, con o sin anteojos","Por lo menos 20/20 en ambos ojos, sin anteojos","Por lo menos 20/100 en ambos ojos","Por lo menos 20/40 en ambos ojos, sin anteojos"],"h1":"Puede usar anteojos o lentes de contacto, y un ojo puede ser suficiente.","h2":"En Nuevo México usted necesita una visión de por lo menos 20/40 en al menos un ojo, con o sin anteojos o lentes de contacto, para obtener una licencia de conducir.","p":"Correcto. Necesita 20/40 en al menos un ojo, y se permiten anteojos."},"zh":{"q":"在 New Mexico，要通过驾照的视力测试，你需要什么样的视力？","o":["至少一只眼睛达到 20/40，戴不戴眼镜都可以","两只眼睛都达到 20/20，不戴眼镜","两只眼睛都至少达到 20/100","两只眼睛都达到 20/40，不戴眼镜"],"h1":"你可以戴眼镜或隐形眼镜，一只眼睛可能就够了。","h2":"在 New Mexico，你至少一只眼睛的视力要达到 20/40，戴不戴眼镜或隐形眼镜都可以，才能拿到驾照。","p":"对。至少一只眼睛要达到 20/40，可以戴眼镜。"},"vi":{"q":"Ở New Mexico, bạn cần thị lực như thế nào để qua bài kiểm tra mắt khi lấy bằng lái xe?","o":["Ít nhất 20/40 ở ít nhất một mắt, có hoặc không đeo kính","Ít nhất 20/20 ở cả hai mắt, không đeo kính","Ít nhất 20/100 ở cả hai mắt","Ít nhất 20/40 ở cả hai mắt, không đeo kính"],"h1":"Bạn có thể đeo kính hoặc kính áp tròng, và một mắt có thể là đủ.","h2":"Ở New Mexico, bạn cần thị lực ít nhất 20/40 ở ít nhất một mắt, có hoặc không đeo kính hay kính áp tròng, để lấy bằng lái xe.","p":"Đúng. Bạn cần 20/40 ở ít nhất một mắt, và được phép đeo kính."},"tl":{"q":"Sa New Mexico, anong paningin ang kailangan mo para pumasa sa vision test para sa driver license?","o":["Hindi bababa sa 20/40 sa kahit isang mata, may salamin man o wala","Hindi bababa sa 20/20 sa dalawang mata, nang walang salamin","Hindi bababa sa 20/100 sa dalawang mata","Hindi bababa sa 20/40 sa dalawang mata, nang walang salamin"],"h1":"Puwede kang magsuot ng salamin o contact lens, at puwedeng sapat na ang isang mata.","h2":"Sa New Mexico, kailangan mo ng paningin na hindi bababa sa 20/40 sa kahit isang mata, may salamin o contact lens man o wala, para makakuha ng driver license.","p":"Tama. Kailangan mo ng 20/40 sa kahit isang mata, at puwede ang salamin."},"ar":{"q":"في New Mexico، ما قوة النظر التي تحتاجها لتنجح في فحص النظر لرخصة القيادة؟","o":["20/40 على الأقل في عين واحدة على الأقل، بنظارة أو بدونها","20/20 على الأقل في العينين، بدون نظارة","20/100 على الأقل في العينين","20/40 على الأقل في العينين، بدون نظارة"],"h1":"يمكنك لبس النظارة أو العدسات اللاصقة، وقد تكفي عين واحدة.","h2":"في New Mexico تحتاج إلى نظر 20/40 على الأقل في عين واحدة على الأقل، بنظارة أو عدسات لاصقة أو بدونها، لتحصل على رخصة القيادة.","p":"صحيح. تحتاج إلى 20/40 في عين واحدة على الأقل، والنظارة مسموحة."},"ref":{"doc":"NM","page":28}},{"id":"nm-030","scope":"NM","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Mexico, how close to a railroad crossing may you park?","o":["No closer than 10 feet","No closer than 20 feet","No closer than 30 feet","No closer than 50 feet"],"h1":"It is the largest of these distances.","h2":"In New Mexico you may not park within 50 feet of a railroad crossing.","p":"Right. Stay at least 50 feet away from a railroad crossing when you park."},"es":{"q":"En Nuevo México, ¿qué tan cerca de un cruce de ferrocarril puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 20 pies","No más cerca de 30 pies","No más cerca de 50 pies"],"h1":"Es la mayor de estas distancias.","h2":"En Nuevo México usted no puede estacionarse a menos de 50 pies de un cruce de ferrocarril.","p":"Correcto. Quédese por lo menos a 50 pies de un cruce de ferrocarril al estacionarse."},"zh":{"q":"在 New Mexico，你最近可以在离铁路道口多远的地方停车？","o":["不能近于 10 英尺","不能近于 20 英尺","不能近于 30 英尺","不能近于 50 英尺"],"h1":"是这几个距离中最大的那个。","h2":"在 New Mexico，你不可以在铁路道口 50 英尺以内停车。","p":"对。停车时，要离铁路道口至少 50 英尺。"},"vi":{"q":"Ở New Mexico, bạn được đậu xe gần đường ray xe lửa đến mức nào?","o":["Không gần hơn 10 feet","Không gần hơn 20 feet","Không gần hơn 30 feet","Không gần hơn 50 feet"],"h1":"Đó là khoảng cách lớn nhất trong các khoảng cách này.","h2":"Ở New Mexico, bạn không được đậu xe trong vòng 50 feet từ chỗ băng qua đường ray xe lửa.","p":"Đúng. Khi đậu xe, hãy cách chỗ băng qua đường ray xe lửa ít nhất 50 feet."},"tl":{"q":"Sa New Mexico, gaano kalapit sa railroad crossing ka puwedeng mag-park?","o":["Hindi mas malapit sa 10 talampakan","Hindi mas malapit sa 20 talampakan","Hindi mas malapit sa 30 talampakan","Hindi mas malapit sa 50 talampakan"],"h1":"Ito ang pinakamalayo sa mga distansyang ito.","h2":"Sa New Mexico, hindi ka puwedeng mag-park sa loob ng 50 talampakan mula sa railroad crossing.","p":"Tama. Lumayo nang hindi bababa sa 50 talampakan mula sa railroad crossing kapag nagpa-park ka."},"ar":{"q":"في New Mexico، إلى أي مدى يمكنك أن تركن سيارتك قريبًا من معبر سكة الحديد؟","o":["ليس أقرب من 10 أقدام (feet)","ليس أقرب من 20 قدمًا (feet)","ليس أقرب من 30 قدمًا (feet)","ليس أقرب من 50 قدمًا (feet)"],"h1":"إنها أكبر مسافة بين هذه المسافات.","h2":"في New Mexico لا يجوز لك أن تركن سيارتك على بعد أقل من 50 قدمًا (feet) من معبر سكة الحديد.","p":"صحيح. ابقَ على بعد 50 قدمًا (feet) على الأقل من معبر سكة الحديد عندما تركن سيارتك."},"ref":{"doc":"NM","page":13}},{"id":"nm-031","scope":"NM","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Mexico, you are driving behind another car at night. Within what distance should you use your low beams?","o":["100 feet","200 feet","1,000 feet","1 mile"],"h1":"It is about the length of 13 cars.","h2":"In New Mexico you should use your low beams when you are within 200 feet of a vehicle you are following.","p":"Right. Switch to low beams within 200 feet of the car ahead."},"es":{"q":"En Nuevo México, usted maneja de noche detrás de otro carro. ¿A qué distancia debe usar las luces bajas?","o":["100 pies","200 pies","1,000 pies","1 milla"],"h1":"Es más o menos el largo de 13 carros.","h2":"En Nuevo México usted debe usar las luces bajas cuando está a menos de 200 pies del vehículo que va delante.","p":"Correcto. Cambie a luces bajas a menos de 200 pies del carro de adelante."},"zh":{"q":"在 New Mexico，你晚上开在另一辆车后面。在多远的距离内你应该用近光灯？","o":["100 英尺","200 英尺","1,000 英尺","1 英里"],"h1":"大约是 13 辆车的长度。","h2":"在 New Mexico，当你离前面跟着的车在 200 英尺以内时，你应该用近光灯。","p":"对。离前车 200 英尺以内时，换成近光灯。"},"vi":{"q":"Ở New Mexico, bạn đang lái xe phía sau một xe khác vào ban đêm. Trong khoảng cách bao xa thì bạn nên dùng đèn cốt (đèn chiếu gần)?","o":["100 feet","200 feet","1,000 feet","1 dặm"],"h1":"Đó là khoảng chiều dài của 13 chiếc xe.","h2":"Ở New Mexico, bạn nên dùng đèn cốt (đèn chiếu gần) khi bạn ở trong vòng 200 feet sau chiếc xe bạn đang đi theo.","p":"Đúng. Chuyển sang đèn cốt khi bạn ở trong vòng 200 feet sau xe phía trước."},"tl":{"q":"Sa New Mexico, nagmamaneho ka sa likod ng ibang kotse sa gabi. Sa loob ng anong distansya ka dapat gumamit ng low beams?","o":["100 talampakan","200 talampakan","1,000 talampakan","1 milya"],"h1":"Ito ay mga kasinghaba ng 13 kotse.","h2":"Sa New Mexico, dapat kang gumamit ng low beams kapag nasa loob ka ng 200 talampakan mula sa sasakyang sinusundan mo.","p":"Tama. Lumipat sa low beams kapag nasa loob ka ng 200 talampakan mula sa kotse sa unahan."},"ar":{"q":"في New Mexico، أنت تقود خلف سيارة أخرى في الليل. ضمن أي مسافة يجب أن تستعمل الأضواء المنخفضة؟","o":["100 قدم (feet)","200 قدم (feet)","1,000 قدم (feet)","1 ميل"],"h1":"إنها تقريبًا طول 13 سيارة.","h2":"في New Mexico يجب أن تستعمل الأضواء المنخفضة عندما تكون على بعد أقل من 200 قدم (feet) من السيارة التي تسير خلفها.","p":"صحيح. انتقل إلى الأضواء المنخفضة عندما تكون على بعد أقل من 200 قدم (feet) من السيارة التي أمامك."},"ref":{"doc":"NM","page":18}},{"id":"nm-032","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, how long is a driver license valid?","o":["1 or 2 years","2 or 3 years","4 or 8 years","10 or 12 years"],"h1":"There are two choices, and one is twice as long as the other.","h2":"In New Mexico a driver license is valid for either 4 years or 8 years.","p":"Right. A New Mexico license lasts 4 or 8 years."},"es":{"q":"En Nuevo México, ¿por cuánto tiempo es válida una licencia de conducir?","o":["1 o 2 años","2 o 3 años","4 u 8 años","10 o 12 años"],"h1":"Hay dos opciones, y una dura el doble que la otra.","h2":"En Nuevo México una licencia de conducir es válida por 4 años o por 8 años.","p":"Correcto. Una licencia de Nuevo México dura 4 u 8 años."},"ref":{"doc":"NM","page":2}},{"id":"nm-033","scope":"NM","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Mexico, which of these can stop a provisional driver from getting a full (unrestricted) license?","o":["An alcohol or drug offense during the provisional period","Driving with a parent in the car","Carrying a brother or sister as a passenger","Taking a driver education course"],"h1":"Think about what the law treats as a serious offense for young drivers.","h2":"In New Mexico you cannot get an unrestricted license if you were found guilty of, or have a pending case for, an alcohol or drug offense during the provisional period.","p":"Right. An alcohol or drug offense while on a provisional license blocks the full license."},"es":{"q":"En Nuevo México, ¿cuál de estas cosas puede impedir que un conductor con licencia provisional obtenga una licencia completa (sin restricciones)?","o":["Un delito de alcohol o drogas durante el período provisional","Manejar con un padre en el auto","Llevar a un hermano o hermana como pasajero","Tomar un curso de educación vial"],"h1":"Piense en lo que la ley considera una falta grave para los conductores jóvenes.","h2":"En Nuevo México usted no puede obtener una licencia sin restricciones si fue declarado culpable, o tiene un caso pendiente, de un delito de alcohol o drogas durante el período provisional.","p":"Correcto. Un delito de alcohol o drogas con licencia provisional impide la licencia completa."},"ref":{"doc":"NM","page":2}},{"id":"nm-034","scope":"NM","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Mexico, how close to a stop sign, yield sign or traffic signal may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 15 feet","No closer than 30 feet"],"h1":"It is about the length of two cars.","h2":"In New Mexico you may not park within 30 feet of a stop sign, yield sign or traffic signal.","p":"Right. Stay at least 30 feet away from a stop sign, yield sign or traffic signal."},"es":{"q":"En Nuevo México, ¿qué tan cerca de una señal de alto, una señal de ceda el paso o un semáforo puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 15 pies","No más cerca de 30 pies"],"h1":"Es más o menos el largo de dos autos.","h2":"En Nuevo México usted no puede estacionarse a menos de 30 pies de una señal de alto, una señal de ceda el paso o un semáforo.","p":"Correcto. Manténgase al menos a 30 pies de una señal de alto, de ceda el paso o de un semáforo."},"ref":{"doc":"NM","page":13}},{"id":"nm-035","scope":"NM","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Mexico, how close to a crosswalk at an intersection may you park?","o":["No closer than 10 feet","No closer than 25 feet","No closer than 50 feet","No closer than 100 feet"],"h1":"It is a quarter of 100 feet.","h2":"In New Mexico you may not park within 25 feet of a crosswalk at an intersection.","p":"Right. Park at least 25 feet from a crosswalk at an intersection."},"es":{"q":"En Nuevo México, ¿qué tan cerca de un cruce peatonal en una intersección puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 25 pies","No más cerca de 50 pies","No más cerca de 100 pies"],"h1":"Es la cuarta parte de 100 pies.","h2":"En Nuevo México usted no puede estacionarse a menos de 25 pies de un cruce peatonal en una intersección.","p":"Correcto. Estaciónese al menos a 25 pies de un cruce peatonal en una intersección."},"ref":{"doc":"NM","page":13}},{"id":"nm-036","scope":"NM","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Mexico, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 8 feet","No closer than 15 feet","No closer than 40 feet"],"h1":"Firefighters need room to reach the hydrant. The answer is between 10 and 20 feet.","h2":"In New Mexico you may not park within 15 feet of a fire hydrant.","p":"Right. Keep at least 15 feet from a fire hydrant."},"es":{"q":"En Nuevo México, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 8 pies","No más cerca de 15 pies","No más cerca de 40 pies"],"h1":"Los bomberos necesitan espacio para llegar al hidrante. La respuesta está entre 10 y 20 pies.","h2":"En Nuevo México usted no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Manténgase al menos a 15 pies de un hidrante."},"ref":{"doc":"NM","page":13}},{"id":"nm-037","scope":"NM","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Mexico, you park next to a curb. How far from the curb may your car be?","o":["No more than 18 inches","No more than 3 feet","No more than 4 feet","Any distance, if your lights are on"],"h1":"It is less than two feet.","h2":"In New Mexico you may not park more than 18 inches from the curb.","p":"Right. Park no more than 18 inches from the curb."},"es":{"q":"En Nuevo México, usted se estaciona junto a la acera. ¿A qué distancia de la acera puede quedar su auto?","o":["A no más de 18 pulgadas","A no más de 3 pies","A no más de 4 pies","A cualquier distancia, si tiene las luces encendidas"],"h1":"Es menos de dos pies.","h2":"En Nuevo México usted no puede estacionarse a más de 18 pulgadas de la acera.","p":"Correcto. Estaciónese a no más de 18 pulgadas de la acera."},"ref":{"doc":"NM","page":13}},{"id":"nm-038","scope":"NM","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Mexico, you want to park on the same side of the street as a fire station driveway. How close to that driveway may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 75 feet","No closer than 20 feet"],"h1":"On the same side of the street the distance is shorter than on the other side.","h2":"In New Mexico you may not park within 20 feet of a fire station driveway on the same side of the street.","p":"Right. On the same side, stay at least 20 feet from a fire station driveway."},"es":{"q":"En Nuevo México, usted quiere estacionarse en el mismo lado de la calle que la entrada de una estación de bomberos. ¿Qué tan cerca de esa entrada puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 75 pies","No más cerca de 20 pies"],"h1":"En el mismo lado de la calle la distancia es más corta que en el otro lado.","h2":"En Nuevo México usted no puede estacionarse a menos de 20 pies de la entrada de una estación de bomberos en el mismo lado de la calle.","p":"Correcto. En el mismo lado, manténgase al menos a 20 pies de la entrada de una estación de bomberos."},"ref":{"doc":"NM","page":13}},{"id":"nm-039","scope":"NM","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Mexico, what does a curb painted red mean?","o":["Short stops only","A fire zone: no parking or standing","Parking for people with disabilities only","A loading zone"],"h1":"Red is the color for fire and danger.","h2":"In New Mexico a red curb marks a fire zone where you may not park or stand.","p":"Right. A red curb means a fire zone with no parking or standing."},"es":{"q":"En Nuevo México, ¿qué significa una acera pintada de rojo?","o":["Solo paradas cortas","Una zona de incendios: no se puede estacionar ni detenerse","Estacionamiento solo para personas con discapacidad","Una zona de carga"],"h1":"El rojo es el color del fuego y del peligro.","h2":"En Nuevo México una acera roja marca una zona de incendios donde no se puede estacionar ni detenerse.","p":"Correcto. Una acera roja indica una zona de incendios donde no se puede estacionar ni detenerse."},"ref":{"doc":"NM","page":14}},{"id":"nm-040","scope":"NM","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Mexico, what is the speed limit in a business or residential area when no sign says otherwise?","o":["15 mph","25 mph","30 mph","40 mph"],"h1":"It is twice the school zone limit.","h2":"In New Mexico the speed limit in business and residential areas is 30 mph unless a sign shows a different limit.","p":"Right. Business and residential areas are 30 mph unless posted otherwise."},"es":{"q":"En Nuevo México, ¿cuál es el límite de velocidad en una zona comercial o residencial cuando ninguna señal indica otro?","o":["15 mph","25 mph","30 mph","40 mph"],"h1":"Es el doble del límite en una zona escolar.","h2":"En Nuevo México el límite de velocidad en zonas comerciales y residenciales es de 30 mph, a menos que una señal indique otro límite.","p":"Correcto. Las zonas comerciales y residenciales son de 30 mph si no hay otra señal."},"ref":{"doc":"NM","page":12}},{"id":"nm-041","scope":"NM","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Mexico, what is the speed limit on a public highway that is not a rural interstate, when no sign says otherwise?","o":["55 mph","45 mph","65 mph","75 mph"],"h1":"It is 20 mph less than the rural interstate limit.","h2":"In New Mexico the speed limit on public highways is 55 mph unless a sign shows a different limit.","p":"Right. Public highways are 55 mph unless posted otherwise."},"es":{"q":"En Nuevo México, ¿cuál es el límite de velocidad en una carretera pública que no es una interestatal rural, cuando ninguna señal indica otro?","o":["55 mph","45 mph","65 mph","75 mph"],"h1":"Es 20 mph menos que el límite en las interestatales rurales.","h2":"En Nuevo México el límite de velocidad en las carreteras públicas es de 55 mph, a menos que una señal indique otro límite.","p":"Correcto. Las carreteras públicas son de 55 mph si no hay otra señal."},"ref":{"doc":"NM","page":12}},{"id":"nm-042","scope":"NM","cat":"signals","sign":null,"c":3,"en":{"q":"In New Mexico, how far before a turn should you turn on your turn signal?","o":["At least 10 feet","Only when you start to turn","At least 1 mile","At least 100 feet"],"h1":"It is about the length of a few cars in a row, more than 50 feet.","h2":"In New Mexico you should signal at least 100 feet before you turn.","p":"Right. Signal at least 100 feet before the turn."},"es":{"q":"En Nuevo México, ¿con cuánta anticipación antes de girar debe encender la direccional?","o":["Al menos 10 pies antes","Solo cuando empieza a girar","Al menos 1 milla antes","Al menos 100 pies antes"],"h1":"Es como el largo de varios autos en fila, más de 50 pies.","h2":"En Nuevo México usted debe señalar al menos 100 pies antes de girar.","p":"Correcto. Señale al menos 100 pies antes del giro."},"ref":{"doc":"NM","page":19}},{"id":"nm-043","scope":"NM","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Mexico, you are using high beams at night. When should you dim them for a car coming toward you?","o":["When it is about half a mile away","When it is within about one block","Only when it is right next to you","Never; high beams are always allowed"],"h1":"Think of the length of one city block.","h2":"In New Mexico you should dim your high beams when an oncoming vehicle is within about one block.","p":"Right. Dim your high beams within about one block of an oncoming car."},"es":{"q":"En Nuevo México, usted usa las luces altas de noche. ¿Cuándo debe bajarlas por un auto que viene de frente?","o":["Cuando está a media milla","Cuando está a una cuadra o menos","Solo cuando está justo a su lado","Nunca; las luces altas siempre están permitidas"],"h1":"Piense en el largo de una cuadra de la ciudad.","h2":"En Nuevo México usted debe bajar las luces altas cuando un vehículo que viene de frente está a una cuadra o menos.","p":"Correcto. Baje las luces altas cuando un auto de frente esté a una cuadra o menos."},"ref":{"doc":"NM","page":18}},{"id":"nm-044","scope":"NM","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Mexico, the road is covered with packed snow. How much should you slow down?","o":["About 5 mph","About 10 mph","Cut your speed about in half","Not at all, if you have good tires"],"h1":"Packed snow is much more slippery than a wet road.","h2":"In New Mexico the driver manual says to cut your speed about in half on packed snow.","p":"Right. On packed snow, cut your speed about in half."},"es":{"q":"En Nuevo México, la carretera está cubierta de nieve compacta. ¿Cuánto debe reducir la velocidad?","o":["Unas 5 mph","Unas 10 mph","Reducir la velocidad más o menos a la mitad","Nada, si tiene buenas llantas"],"h1":"La nieve compacta es mucho más resbalosa que una carretera mojada.","h2":"En Nuevo México el manual del conductor dice que debe reducir la velocidad más o menos a la mitad sobre nieve compacta.","p":"Correcto. Sobre nieve compacta, reduzca la velocidad más o menos a la mitad."},"ref":{"doc":"NM","page":20}},{"id":"nm-045","scope":"NM","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Mexico, who must wear a helmet on a motorcycle?","o":["All riders and passengers under 18","Only the rider, not the passenger","Only riders on interstate highways","No one; helmets are never required"],"h1":"The law covers young people. Helmets are recommended for everyone.","h2":"In New Mexico the law requires motorcycle riders and passengers under 18 to wear a helmet.","p":"Right. Riders and passengers under 18 must wear a helmet."},"es":{"q":"En Nuevo México, ¿quién debe usar casco en una motocicleta?","o":["Todos los conductores y pasajeros menores de 18 años","Solo el conductor, no el pasajero","Solo los conductores en carreteras interestatales","Nadie; el casco nunca es obligatorio"],"h1":"La ley protege a los jóvenes. Se recomienda el casco para todos.","h2":"En Nuevo México la ley exige que los conductores y pasajeros de motocicleta menores de 18 años usen casco.","p":"Correcto. Los conductores y pasajeros menores de 18 años deben usar casco."},"ref":{"doc":"NM","page":37}},{"id":"nm-046","scope":"NM","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Mexico, you are passing a person on a bicycle. How much space should you try to give?","o":["At least 1 foot","At least 2 feet","No space is needed","At least 5 feet"],"h1":"It is more than one yard, but less than two yards.","h2":"In New Mexico you should try to leave at least five feet when you pass a bicyclist.","p":"Right. Try to give a bicyclist at least five feet."},"es":{"q":"En Nuevo México, usted va a rebasar a una persona en bicicleta. ¿Cuánto espacio debe tratar de dejarle?","o":["Al menos 1 pie","Al menos 2 pies","No hace falta espacio","Al menos 5 pies"],"h1":"Es más de una yarda, pero menos de dos yardas.","h2":"En Nuevo México usted debe tratar de dejar al menos cinco pies al rebasar a un ciclista.","p":"Correcto. Trate de dejarle al menos cinco pies al ciclista."},"ref":{"doc":"NM","page":25}},{"id":"nm-047","scope":"NM","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Mexico, a school bus or a truck carrying gasoline comes to a railroad crossing. What must it do?","o":["Cross quickly without stopping","Stop at least 15 feet from the crossing before going on","Stop only if a train can be seen","Stop right on the tracks to look both ways"],"h1":"These vehicles must always stop, and not too close to the tracks.","h2":"In New Mexico school buses, vehicles for hire that carry passengers, and trucks carrying dangerous loads such as gasoline must stop at least 15 feet from a railroad crossing before going on.","p":"Right. They must stop at least 15 feet from the crossing."},"es":{"q":"En Nuevo México, un autobús escolar o un camión que lleva gasolina llega a un cruce de ferrocarril. ¿Qué debe hacer?","o":["Cruzar rápido sin detenerse","Detenerse al menos a 15 pies del cruce antes de seguir","Detenerse solo si se ve un tren","Detenerse sobre las vías para mirar a ambos lados"],"h1":"Estos vehículos siempre deben detenerse, y no demasiado cerca de las vías.","h2":"En Nuevo México los autobuses escolares, los vehículos de alquiler que llevan pasajeros y los camiones con cargas peligrosas como gasolina deben detenerse al menos a 15 pies de un cruce de ferrocarril antes de seguir.","p":"Correcto. Deben detenerse al menos a 15 pies del cruce."},"ref":{"doc":"NM","page":6}},{"id":"nm-048","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, what is the minimum insurance for injury to or death of one person in one crash?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"It is more than the minimum for property damage, but less than $50,000.","h2":"In New Mexico the minimum liability insurance for injury to or death of one person in one crash is $25,000.","p":"Right. The minimum for one person is $25,000."},"es":{"q":"En Nuevo México, ¿cuál es el seguro mínimo por lesiones o muerte de una persona en un choque?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"Es más que el mínimo por daños a la propiedad, pero menos de $50,000.","h2":"En Nuevo México el seguro de responsabilidad mínimo por lesiones o muerte de una persona en un choque es de $25,000.","p":"Correcto. El mínimo por una persona es de $25,000."},"ref":{"doc":"NM","page":35}},{"id":"nm-049","scope":"NM","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Mexico, what can happen if you do not have car insurance?","o":["Your vehicle registration can be suspended and you may have to turn in your plates","Nothing, if you drive carefully","You only get a warning the first time","You must take the road test again"],"h1":"The state can take away your right to keep the car on the road.","h2":"In New Mexico driving without insurance can lead to a suspended registration, turning in your license plates, and possible criminal penalties.","p":"Right. No insurance can cost you your registration and your plates."},"es":{"q":"En Nuevo México, ¿qué puede pasar si no tiene seguro de auto?","o":["Le pueden suspender el registro del vehículo y puede tener que entregar las placas","Nada, si maneja con cuidado","Solo recibe una advertencia la primera vez","Debe tomar otra vez el examen de manejo"],"h1":"El estado puede quitarle el derecho de tener el auto en la carretera.","h2":"En Nuevo México manejar sin seguro puede llevar a la suspensión del registro, a entregar las placas y a posibles sanciones penales.","p":"Correcto. No tener seguro le puede costar el registro y las placas."},"ref":{"doc":"NM","page":35}},{"id":"nm-050","scope":"NM","cat":"signals","sign":null,"c":3,"en":{"q":"In New Mexico, you see an orange triangle on the back of a vehicle. What does it tell you?","o":["The vehicle carries a dangerous load","The driver is a student","The vehicle is an emergency vehicle","The vehicle goes less than 25 mph"],"h1":"You often see it on farm tractors and horse-drawn wagons.","h2":"In New Mexico an orange triangle on the back of a vehicle means it is a slow-moving vehicle that travels under 25 mph.","p":"Right. The orange triangle marks a slow vehicle going under 25 mph."},"es":{"q":"En Nuevo México, usted ve un triángulo anaranjado en la parte de atrás de un vehículo. ¿Qué le indica?","o":["El vehículo lleva una carga peligrosa","El conductor es un estudiante","Es un vehículo de emergencia","El vehículo va a menos de 25 mph"],"h1":"Se ve a menudo en tractores agrícolas y carretas tiradas por caballos.","h2":"En Nuevo México un triángulo anaranjado en la parte de atrás de un vehículo indica que es un vehículo lento que va a menos de 25 mph.","p":"Correcto. El triángulo anaranjado marca un vehículo lento que va a menos de 25 mph."},"ref":{"doc":"NM","page":7}},{"id":"nv-001","scope":"NV","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nevada, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","15 and a half years old","16 years old"],"h1":"It is a half year past a birthday.","h2":"In Nevada you can get an instruction permit at 15 and a half years old.","p":"Right. Nevada permits start at 15 and a half."},"es":{"q":"En Nevada, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["14 años","15 años","15 años y medio","16 años"],"h1":"Es medio año después de un cumpleaños.","h2":"En Nevada usted puede obtener el permiso de instrucción a los 15 años y medio.","p":"Correcto. El permiso en Nevada empieza a los 15 años y medio."},"zh":{"q":"在 Nevada，最小几岁可以拿到学习驾照（instruction permit）？","o":["14 岁","15 岁","15 岁半","16 岁"],"h1":"它是过了某个生日半年。","h2":"在 Nevada，你 15 岁半就可以拿到学习驾照。","p":"对。Nevada 的学习驾照从 15 岁半开始。"},"vi":{"q":"Ở Nevada, tuổi nhỏ nhất để được cấp giấy phép tập lái (instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","15 tuổi rưỡi","16 tuổi"],"h1":"Đó là nửa năm sau một ngày sinh nhật.","h2":"Ở Nevada, bạn có thể được cấp giấy phép tập lái khi 15 tuổi rưỡi.","p":"Đúng. Ở Nevada, giấy phép tập lái bắt đầu từ 15 tuổi rưỡi."},"tl":{"q":"Sa Nevada, ano ang pinakabatang edad para makakuha ng instruction permit (permit sa pag-aaral magmaneho)?","o":["14 taong gulang","15 taong gulang","15 at kalahating taong gulang","16 taong gulang"],"h1":"Kalahating taon ito pagkatapos ng isang kaarawan.","h2":"Sa Nevada, makakakuha ka ng instruction permit sa edad na 15 at kalahati.","p":"Tama. Sa Nevada, nagsisimula ang permit sa edad na 15 at kalahati."},"ar":{"q":"في Nevada، ما أصغر عمر للحصول على تصريح تعلّم القيادة (instruction permit)؟","o":["14 سنة","15 سنة","15 سنة ونصف","16 سنة"],"h1":"هو نصف سنة بعد يوم ميلاد.","h2":"في Nevada يمكنك الحصول على تصريح تعلّم القيادة في عمر 15 سنة ونصف.","p":"صحيح. في Nevada يبدأ تصريح التعلّم من عمر 15 سنة ونصف."},"ref":{"doc":"NV","page":15}},{"id":"nv-002","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, how long is an instruction permit valid?","o":["Six months","One year","Two years","Until age 18"],"h1":"It lasts one trip around the calendar.","h2":"A Nevada instruction permit is valid for one year.","p":"Right. The permit lasts one year."},"es":{"q":"En Nevada, ¿por cuánto tiempo es válido el permiso de instrucción?","o":["Seis meses","Un año","Dos años","Hasta los 18 años"],"h1":"Dura una vuelta completa al calendario.","h2":"En Nevada, el permiso de instrucción es válido por un año.","p":"Correcto. El permiso dura un año."},"zh":{"q":"在 Nevada，学习驾照有效期多久？","o":["六个月","一年","两年","到 18 岁"],"h1":"它是日历走一整圈的时间。","h2":"Nevada 的学习驾照有效期是一年。","p":"对。学习驾照有效一年。"},"vi":{"q":"Ở Nevada, giấy phép tập lái có giá trị trong bao lâu?","o":["Sáu tháng","Một năm","Hai năm","Cho đến 18 tuổi"],"h1":"Nó kéo dài trọn một vòng lịch.","h2":"Giấy phép tập lái ở Nevada có giá trị trong một năm.","p":"Đúng. Giấy phép có giá trị một năm."},"tl":{"q":"Sa Nevada, gaano katagal valid ang instruction permit?","o":["Anim na buwan","Isang taon","Dalawang taon","Hanggang edad 18"],"h1":"Tumatagal ito ng isang buong ikot ng kalendaryo.","h2":"Ang Nevada instruction permit ay valid nang isang taon.","p":"Tama. Tumatagal nang isang taon ang permit."},"ar":{"q":"في Nevada، كم مدة صلاحية تصريح تعلّم القيادة؟","o":["ستة أشهر","سنة واحدة","سنتان","حتى عمر 18 سنة"],"h1":"يدوم دورة كاملة في التقويم.","h2":"تصريح تعلّم القيادة في Nevada صالح لمدة سنة واحدة.","p":"صحيح. التصريح صالح لمدة سنة واحدة."},"ref":{"doc":"NV","page":15}},{"id":"nv-003","scope":"NV","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nevada, how many supervised driving hours must a teen complete, and how many at night?","o":["50 hours, 10 at night","30 hours, 5 at night","40 hours, 15 at night","100 hours, 20 at night"],"h1":"The night hours are one fifth of the total.","h2":"A Nevada teen must complete at least 50 hours of supervised driving, and 10 of those hours must be at night.","p":"Right. Fifty hours, ten at night."},"es":{"q":"En Nevada, ¿cuántas horas de manejo supervisado debe completar un adolescente, y cuántas de noche?","o":["50 horas, 10 de noche","30 horas, 5 de noche","40 horas, 15 de noche","100 horas, 20 de noche"],"h1":"Las horas de noche son una quinta parte del total.","h2":"En Nevada, un adolescente debe completar por lo menos 50 horas de manejo supervisado, y 10 de ellas deben ser de noche.","p":"Correcto. Cincuenta horas, diez de noche."},"zh":{"q":"在 Nevada，青少年必须完成多少小时有人监督的驾驶，其中多少小时在晚上？","o":["50 小时，10 小时在晚上","30 小时，5 小时在晚上","40 小时，15 小时在晚上","100 小时，20 小时在晚上"],"h1":"晚上的时间是全部时间的五分之一。","h2":"Nevada 的青少年必须完成至少 50 小时有人监督的驾驶，其中 10 小时必须在晚上。","p":"对。五十小时，十小时在晚上。"},"vi":{"q":"Ở Nevada, thiếu niên phải hoàn thành bao nhiêu giờ lái xe có người giám sát, và bao nhiêu giờ vào ban đêm?","o":["50 giờ, 10 giờ ban đêm","30 giờ, 5 giờ ban đêm","40 giờ, 15 giờ ban đêm","100 giờ, 20 giờ ban đêm"],"h1":"Số giờ ban đêm bằng một phần năm tổng số giờ.","h2":"Ở Nevada, thiếu niên phải lái xe có người giám sát ít nhất 50 giờ, và 10 giờ trong số đó phải vào ban đêm.","p":"Đúng. Năm mươi giờ, mười giờ vào ban đêm."},"tl":{"q":"Sa Nevada, ilang oras ng supervised na pagmamaneho ang dapat tapusin ng isang tinedyer, at ilan dito ang sa gabi?","o":["50 oras, 10 sa gabi","30 oras, 5 sa gabi","40 oras, 15 sa gabi","100 oras, 20 sa gabi"],"h1":"Ang oras sa gabi ay ikalimang bahagi ng kabuuan.","h2":"Sa Nevada, ang tinedyer ay dapat magmaneho nang hindi bababa sa 50 oras na may gumagabay, at 10 sa mga oras na iyon ay dapat sa gabi.","p":"Tama. Limampung oras, sampu sa gabi."},"ar":{"q":"في Nevada، كم ساعة من القيادة تحت الإشراف يجب أن يُكمل المراهق، وكم منها في الليل؟","o":["50 ساعة، منها 10 في الليل","30 ساعة، منها 5 في الليل","40 ساعة، منها 15 في الليل","100 ساعة، منها 20 في الليل"],"h1":"ساعات الليل هي خُمس المجموع.","h2":"في Nevada يجب أن يُكمل المراهق 50 ساعة على الأقل من القيادة تحت الإشراف، و10 ساعات منها يجب أن تكون في الليل.","p":"صحيح. خمسون ساعة، منها عشر في الليل."},"ref":{"doc":"NV","page":14}},{"id":"nv-004","scope":"NV","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nevada, who may supervise a teen's practice driving?","o":["Any person with a permit","Any adult over 18","A licensed driver over 25 only","A licensed driver at least 21 who has been licensed at least one year"],"h1":"There is a rule about age and a rule about experience.","h2":"In Nevada, a teen may practice with any licensed driver who is at least 21 and has held a license for at least one year.","p":"Right. At least 21, and licensed for at least a year."},"es":{"q":"En Nevada, ¿quién puede supervisar la práctica de manejo de un adolescente?","o":["Cualquier persona con permiso","Cualquier adulto mayor de 18","Solo un conductor con licencia mayor de 25","Un conductor con licencia de por lo menos 21 años y con licencia desde hace por lo menos un año"],"h1":"Hay una regla de edad y otra de experiencia.","h2":"En Nevada, un adolescente puede practicar con cualquier conductor con licencia que tenga por lo menos 21 años y haya tenido licencia por lo menos un año.","p":"Correcto. Por lo menos 21 años y un año con licencia."},"zh":{"q":"在 Nevada，谁可以监督青少年练习开车？","o":["任何有学习驾照的人","任何 18 岁以上的成年人","只有 25 岁以上、有驾照的司机","至少 21 岁、有驾照至少一年的司机"],"h1":"有一条关于年龄的规定，还有一条关于经验的规定。","h2":"在 Nevada，青少年可以和任何至少 21 岁、有驾照至少一年的司机一起练习。","p":"对。至少 21 岁，有驾照至少一年。"},"vi":{"q":"Ở Nevada, ai được giám sát thiếu niên khi tập lái?","o":["Bất kỳ ai có giấy phép tập lái","Bất kỳ người lớn nào trên 18 tuổi","Chỉ người có bằng lái trên 25 tuổi","Người có bằng lái từ 21 tuổi trở lên và đã có bằng ít nhất một năm"],"h1":"Có một quy định về tuổi và một quy định về kinh nghiệm.","h2":"Ở Nevada, thiếu niên có thể tập lái với bất kỳ người có bằng lái nào từ 21 tuổi trở lên và đã có bằng ít nhất một năm.","p":"Đúng. Ít nhất 21 tuổi, và đã có bằng lái ít nhất một năm."},"tl":{"q":"Sa Nevada, sino ang puwedeng gumabay sa pagsasanay magmaneho ng isang tinedyer?","o":["Kahit sinong may permit","Kahit sinong adulto na lampas 18","Lisensiyadong drayber na lampas 25 lamang","Lisensiyadong drayber na hindi bababa sa 21 taong gulang at may lisensya nang hindi bababa sa isang taon"],"h1":"May patakaran tungkol sa edad at may patakaran tungkol sa karanasan.","h2":"Sa Nevada, puwedeng magsanay ang tinedyer kasama ang kahit sinong lisensiyadong drayber na hindi bababa sa 21 taong gulang at may lisensya nang hindi bababa sa isang taon.","p":"Tama. Hindi bababa sa 21, at may lisensya nang hindi bababa sa isang taon."},"ar":{"q":"في Nevada، من يمكنه الإشراف على تدريب المراهق على القيادة؟","o":["أي شخص لديه تصريح تعلّم","أي شخص بالغ عمره أكثر من 18 سنة","سائق مرخّص عمره أكثر من 25 سنة فقط","سائق مرخّص عمره 21 سنة على الأقل ولديه رخصة منذ سنة على الأقل"],"h1":"هناك قاعدة عن العمر وقاعدة عن الخبرة.","h2":"في Nevada يمكن للمراهق أن يتدرّب مع أي سائق مرخّص عمره 21 سنة على الأقل ولديه رخصة منذ سنة على الأقل.","p":"صحيح. 21 سنة على الأقل، ورخصة منذ سنة على الأقل."},"ref":{"doc":"NV","page":15}},{"id":"nv-005","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, where must the experienced driver sit while a beginner practices?","o":["In the back seat","In the seat next to the beginner","Anywhere in the car","In a car following behind"],"h1":"They need to be close enough to help right away.","h2":"In Nevada, the experienced driver must sit in the seat next to the beginning driver.","p":"Right. The helper sits right beside you."},"es":{"q":"En Nevada, ¿dónde debe sentarse el conductor con experiencia mientras practica un principiante?","o":["En el asiento de atrás","En el asiento junto al principiante","En cualquier lugar del carro","En otro carro detrás"],"h1":"Debe estar lo bastante cerca para ayudar de inmediato.","h2":"En Nevada, el conductor con experiencia debe ir sentado en el asiento junto al conductor principiante.","p":"Correcto. El acompañante va a su lado."},"zh":{"q":"在 Nevada，新手练习开车时，有经验的司机必须坐在哪里？","o":["后排座位","新手旁边的座位","车里任何地方","跟在后面的车里"],"h1":"他们需要离得够近，能马上帮忙。","h2":"在 Nevada，有经验的司机必须坐在新手司机旁边的座位。","p":"对。陪同的人就坐在你旁边。"},"vi":{"q":"Ở Nevada, người lái có kinh nghiệm phải ngồi ở đâu khi người mới tập lái?","o":["Ở ghế sau","Ở ghế ngay bên cạnh người mới tập","Ở bất kỳ chỗ nào trong xe","Trong một xe chạy phía sau"],"h1":"Họ cần ngồi đủ gần để giúp ngay lập tức.","h2":"Ở Nevada, người lái có kinh nghiệm phải ngồi ở ghế ngay bên cạnh người mới tập lái.","p":"Đúng. Người giúp ngồi ngay bên cạnh bạn."},"tl":{"q":"Sa Nevada, saan dapat umupo ang may-karanasang drayber habang nagsasanay ang baguhan?","o":["Sa likurang upuan","Sa upuan katabi ng baguhan","Kahit saan sa sasakyan","Sa sasakyang sumusunod sa likod"],"h1":"Kailangan silang malapit para makatulong agad.","h2":"Sa Nevada, ang may-karanasang drayber ay dapat umupo sa upuan katabi ng baguhang drayber.","p":"Tama. Nakaupo mismo sa tabi mo ang tumutulong."},"ar":{"q":"في Nevada، أين يجب أن يجلس السائق صاحب الخبرة أثناء تدريب السائق المبتدئ؟","o":["في المقعد الخلفي","في المقعد المجاور للمبتدئ","في أي مكان في السيارة","في سيارة تسير خلفه"],"h1":"يجب أن يكون قريبًا بما يكفي ليساعد فورًا.","h2":"في Nevada يجب أن يجلس السائق صاحب الخبرة في المقعد المجاور للسائق المبتدئ.","p":"صحيح. المساعد يجلس بجانبك مباشرة."},"ref":{"doc":"NV","page":15}},{"id":"nv-006","scope":"NV","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nevada, how do a teen and parent prove the supervised driving hours?","o":["They take a photo of the car","No proof is needed","They keep a log of the dates and times of practice","They send text messages to the DMV"],"h1":"It is a written record.","h2":"In Nevada, the teen and a parent or guardian must keep a log of the dates and times of the supervised driving.","p":"Right. Keep a written log of your practice."},"es":{"q":"En Nevada, ¿cómo comprueban un adolescente y su padre las horas de manejo supervisado?","o":["Toman una foto del carro","No se necesita prueba","Llevan un registro de las fechas y horas de práctica","Mandan mensajes de texto al DMV"],"h1":"Es un registro escrito.","h2":"En Nevada, el adolescente y su padre, madre o tutor deben llevar un registro de las fechas y horas del manejo supervisado.","p":"Correcto. Lleve un registro escrito de su práctica."},"zh":{"q":"在 Nevada，青少年和父母怎样证明有人监督的驾驶时间？","o":["给车拍照","不需要证明","记录练习的日期和时间","给 DMV 发短信"],"h1":"它是书面记录。","h2":"在 Nevada，青少年和父母或监护人必须记录有人监督驾驶的日期和时间。","p":"对。把你的练习写下来做记录。"},"vi":{"q":"Ở Nevada, thiếu niên và cha mẹ chứng minh số giờ lái xe có giám sát bằng cách nào?","o":["Họ chụp ảnh chiếc xe","Không cần chứng minh","Họ ghi sổ ngày và giờ tập lái","Họ gửi tin nhắn cho DMV"],"h1":"Đó là một bản ghi chép bằng văn bản.","h2":"Ở Nevada, thiếu niên và cha mẹ hoặc người giám hộ phải ghi sổ (log) ngày và giờ của các buổi lái xe có giám sát.","p":"Đúng. Hãy ghi sổ các buổi tập lái của bạn."},"tl":{"q":"Sa Nevada, paano pinatutunayan ng tinedyer at magulang ang mga oras ng supervised na pagmamaneho?","o":["Kinukunan nila ng litrato ang sasakyan","Hindi kailangan ng patunay","Nagtatala sila ng log ng mga petsa at oras ng pagsasanay","Nagpapadala sila ng text message sa DMV"],"h1":"Isa itong nakasulat na talaan.","h2":"Sa Nevada, ang tinedyer at isang magulang o guardian ay dapat magtala ng log ng mga petsa at oras ng supervised na pagmamaneho.","p":"Tama. Magtala ng nakasulat na log ng iyong pagsasanay."},"ar":{"q":"في Nevada، كيف يُثبت المراهق والوالد ساعات القيادة تحت الإشراف؟","o":["يلتقطان صورة للسيارة","لا حاجة إلى إثبات","يحتفظان بسجلّ (log) لتواريخ وأوقات التدريب","يرسلان رسائل نصية إلى DMV"],"h1":"هو سجلّ مكتوب.","h2":"في Nevada يجب أن يحتفظ المراهق وأحد الوالدين أو الوصي بسجلّ لتواريخ وأوقات القيادة تحت الإشراف.","p":"صحيح. احتفظ بسجلّ مكتوب لتدريبك."},"ref":{"doc":"NV","page":13}},{"id":"nv-007","scope":"NV","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nevada, is driver education required to get an instruction permit?","o":["No, it is not required for the permit","Yes, always","Only for adults","Only in Las Vegas"],"h1":"It is required later, but not at the very first step.","h2":"In Nevada, driver education is not required to get an instruction permit.","p":"Right. The permit does not require driver education."},"es":{"q":"En Nevada, ¿se exige educación vial para obtener el permiso de instrucción?","o":["No, no se exige para el permiso","Sí, siempre","Solo para adultos","Solo en Las Vegas"],"h1":"Se exige más adelante, pero no en el primer paso.","h2":"En Nevada, no se exige educación vial para obtener el permiso de instrucción.","p":"Correcto. El permiso no exige educación vial."},"zh":{"q":"在 Nevada，拿学习驾照需要先上驾驶教育课程吗？","o":["不需要，拿学习驾照不需要","需要，一直都需要","只有成年人需要","只在 Las Vegas 需要"],"h1":"以后会需要，但第一步不需要。","h2":"在 Nevada，拿学习驾照不需要上驾驶教育课程。","p":"对。拿学习驾照不需要驾驶教育。"},"vi":{"q":"Ở Nevada, có bắt buộc học lớp lái xe (driver education) để được cấp giấy phép tập lái không?","o":["Không, không bắt buộc để có giấy phép tập lái","Có, luôn luôn bắt buộc","Chỉ đối với người lớn","Chỉ ở Las Vegas"],"h1":"Nó bắt buộc sau này, nhưng không phải ở bước đầu tiên.","h2":"Ở Nevada, không bắt buộc học lớp lái xe để được cấp giấy phép tập lái.","p":"Đúng. Giấy phép tập lái không đòi hỏi lớp lái xe."},"tl":{"q":"Sa Nevada, kailangan ba ang driver education para makakuha ng instruction permit?","o":["Hindi, hindi ito kailangan para sa permit","Oo, palagi","Para lamang sa mga adulto","Sa Las Vegas lamang"],"h1":"Kailangan ito sa bandang huli, pero hindi sa pinakaunang hakbang.","h2":"Sa Nevada, hindi kailangan ang driver education para makakuha ng instruction permit.","p":"Tama. Hindi kailangan ng permit ang driver education."},"ar":{"q":"في Nevada، هل دورة تعليم القيادة (driver education) مطلوبة للحصول على تصريح تعلّم القيادة؟","o":["لا، ليست مطلوبة للتصريح","نعم، دائمًا","للبالغين فقط","في Las Vegas فقط"],"h1":"هي مطلوبة لاحقًا، لكن ليس في الخطوة الأولى.","h2":"في Nevada لا تُطلب دورة تعليم القيادة للحصول على تصريح تعلّم القيادة.","p":"صحيح. التصريح لا يحتاج إلى دورة تعليم القيادة."},"ref":{"doc":"NV","page":15}},{"id":"nv-008","scope":"NV","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nevada, what must a parent or guardian sign when a teen applies for a permit?","o":["A school report card","A car title","A medical form","A financial responsibility statement"],"h1":"It is about who pays if something goes wrong.","h2":"In Nevada, a parent or guardian must be present to sign a financial responsibility statement for the teen's permit.","p":"Right. The parent signs for financial responsibility."},"es":{"q":"En Nevada, ¿qué debe firmar el padre, madre o tutor cuando un adolescente solicita el permiso?","o":["Una boleta de calificaciones","El título del carro","Un formulario médico","Una declaración de responsabilidad financiera"],"h1":"Tiene que ver con quién paga si algo sale mal.","h2":"En Nevada, el padre, madre o tutor debe estar presente para firmar una declaración de responsabilidad financiera para el permiso del adolescente.","p":"Correcto. El padre firma la responsabilidad financiera."},"zh":{"q":"在 Nevada，青少年申请学习驾照时，父母或监护人必须签什么？","o":["学校成绩单","汽车所有权证（title）","医疗表格","经济责任声明"],"h1":"它是关于出了事由谁付钱。","h2":"在 Nevada，父母或监护人必须到场，为青少年的学习驾照签一份经济责任声明。","p":"对。父母签经济责任声明。"},"vi":{"q":"Ở Nevada, khi thiếu niên xin giấy phép tập lái, cha mẹ hoặc người giám hộ phải ký giấy gì?","o":["Phiếu điểm ở trường","Giấy chủ quyền xe (car title)","Giấy khám sức khỏe","Bản cam kết trách nhiệm tài chính (financial responsibility statement)"],"h1":"Nó nói về ai sẽ trả tiền nếu có chuyện xảy ra.","h2":"Ở Nevada, cha mẹ hoặc người giám hộ phải có mặt để ký bản cam kết trách nhiệm tài chính cho giấy phép tập lái của thiếu niên.","p":"Đúng. Cha mẹ ký nhận trách nhiệm tài chính."},"tl":{"q":"Sa Nevada, ano ang dapat pirmahan ng magulang o guardian kapag nag-aaplay ng permit ang isang tinedyer?","o":["Report card sa paaralan","Titulo ng sasakyan (car title)","Medical na form","Financial responsibility statement (pahayag ng pananagutang pinansiyal)"],"h1":"Tungkol ito sa kung sino ang magbabayad kapag may nangyaring masama.","h2":"Sa Nevada, dapat naroroon ang magulang o guardian para pirmahan ang financial responsibility statement para sa permit ng tinedyer.","p":"Tama. Pumipirma ang magulang para sa pananagutang pinansiyal."},"ar":{"q":"في Nevada، ماذا يجب أن يوقّع الوالد أو الوصي عندما يتقدّم المراهق بطلب تصريح تعلّم القيادة؟","o":["شهادة الدرجات المدرسية","وثيقة ملكية السيارة (car title)","نموذج طبي","إقرار المسؤولية المالية (financial responsibility statement)"],"h1":"يتعلّق بمن يدفع إذا حدث شيء سيّئ.","h2":"في Nevada يجب أن يحضر الوالد أو الوصي ليوقّع إقرار المسؤولية المالية لتصريح المراهق.","p":"صحيح. الوالد يوقّع على المسؤولية المالية."},"ref":{"doc":"NV","page":null}},{"id":"nv-009","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, during which hours may a licensed driver under 18 not drive, unless going to or from a scheduled event?","o":["Midnight to 6 a.m.","10 p.m. to 5 a.m.","9 p.m. to 6 a.m.","11 p.m. to 4 a.m."],"h1":"It starts at ten at night.","h2":"In Nevada, a licensed driver under 18 may not drive between 10 p.m. and 5 a.m. unless going to or from a scheduled event such as work or school.","p":"Right. No driving from 10 p.m. to 5 a.m."},"es":{"q":"En Nevada, ¿en qué horario no puede manejar un conductor con licencia menor de 18 años, salvo para ir o volver de un evento programado?","o":["De medianoche a 6 a.m.","De 10 p.m. a 5 a.m.","De 9 p.m. a 6 a.m.","De 11 p.m. a 4 a.m."],"h1":"Empieza a las diez de la noche.","h2":"En Nevada, un conductor con licencia menor de 18 años no puede manejar entre las 10 p.m. y las 5 a.m., salvo para ir o volver de un evento programado como el trabajo o la escuela.","p":"Correcto. No se maneja de 10 p.m. a 5 a.m."},"zh":{"q":"在 Nevada，除非是去或离开预定的活动，未满 18 岁的有驾照司机在哪个时间段不能开车？","o":["午夜到早上 6 点","晚上 10 点到早上 5 点","晚上 9 点到早上 6 点","晚上 11 点到凌晨 4 点"],"h1":"它从晚上十点开始。","h2":"在 Nevada，未满 18 岁的有驾照司机在晚上 10 点到早上 5 点之间不能开车，除非是去或离开预定的活动，比如上班或上学。","p":"对。晚上 10 点到早上 5 点不能开车。"},"vi":{"q":"Ở Nevada, người có bằng lái dưới 18 tuổi không được lái xe trong khoảng giờ nào, trừ khi đi đến hoặc về từ một sự kiện đã lên lịch?","o":["Nửa đêm đến 6 giờ sáng","10 giờ tối đến 5 giờ sáng","9 giờ tối đến 6 giờ sáng","11 giờ tối đến 4 giờ sáng"],"h1":"Nó bắt đầu lúc mười giờ tối.","h2":"Ở Nevada, người có bằng lái dưới 18 tuổi không được lái xe từ 10 giờ tối đến 5 giờ sáng, trừ khi đi đến hoặc về từ một sự kiện đã lên lịch như đi làm hoặc đi học.","p":"Đúng. Không lái xe từ 10 giờ tối đến 5 giờ sáng."},"tl":{"q":"Sa Nevada, sa anong mga oras hindi puwedeng magmaneho ang lisensiyadong drayber na wala pang 18, maliban kung papunta o pauwi mula sa nakatakdang event?","o":["Hatinggabi hanggang 6 a.m.","10 p.m. hanggang 5 a.m.","9 p.m. hanggang 6 a.m.","11 p.m. hanggang 4 a.m."],"h1":"Nagsisimula ito nang alas-diyes ng gabi.","h2":"Sa Nevada, ang lisensiyadong drayber na wala pang 18 ay hindi puwedeng magmaneho mula 10 p.m. hanggang 5 a.m., maliban kung papunta o pauwi mula sa nakatakdang event tulad ng trabaho o paaralan.","p":"Tama. Bawal magmaneho mula 10 p.m. hanggang 5 a.m."},"ar":{"q":"في Nevada، في أي ساعات لا يجوز للسائق المرخّص الذي عمره أقل من 18 سنة أن يقود، إلا إذا كان ذاهبًا إلى حدث مُجدول أو عائدًا منه؟","o":["من منتصف الليل إلى 6 صباحًا","من 10 مساءً إلى 5 صباحًا","من 9 مساءً إلى 6 صباحًا","من 11 مساءً إلى 4 صباحًا"],"h1":"تبدأ في الساعة العاشرة ليلًا.","h2":"في Nevada لا يجوز للسائق المرخّص الذي عمره أقل من 18 سنة أن يقود بين 10 مساءً و5 صباحًا، إلا إذا كان ذاهبًا إلى حدث مُجدول مثل العمل أو المدرسة أو عائدًا منه.","p":"صحيح. لا قيادة من 10 مساءً إلى 5 صباحًا."},"ref":{"doc":"NV","page":15}},{"id":"nv-010","scope":"NV","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nevada, for how long after getting a license may a teen not carry passengers under 18 who are not family?","o":["One month","Three months","Six months","Two years"],"h1":"It is half a year.","h2":"In Nevada, a new teen driver may not carry passengers under 18, except immediate family, for the first six months after getting a license.","p":"Right. The first six months."},"es":{"q":"En Nevada, ¿por cuánto tiempo después de obtener la licencia no puede un adolescente llevar pasajeros menores de 18 años que no sean familia?","o":["Un mes","Tres meses","Seis meses","Dos años"],"h1":"Es medio año.","h2":"En Nevada, un conductor adolescente nuevo no puede llevar pasajeros menores de 18 años, salvo familiares directos, durante los primeros seis meses con licencia.","p":"Correcto. Los primeros seis meses."},"zh":{"q":"在 Nevada，青少年拿到驾照后多久内，不能载不是家人、未满 18 岁的乘客？","o":["一个月","三个月","六个月","两年"],"h1":"它是半年。","h2":"在 Nevada，青少年新司机拿到驾照后的前六个月，不能载未满 18 岁的乘客，直系亲属除外。","p":"对。前六个月。"},"vi":{"q":"Ở Nevada, sau khi có bằng lái, thiếu niên không được chở hành khách dưới 18 tuổi không phải người nhà trong bao lâu?","o":["Một tháng","Ba tháng","Sáu tháng","Hai năm"],"h1":"Đó là nửa năm.","h2":"Ở Nevada, người lái trẻ mới có bằng không được chở hành khách dưới 18 tuổi, trừ người nhà trực tiếp, trong sáu tháng đầu sau khi có bằng lái.","p":"Đúng. Sáu tháng đầu tiên."},"tl":{"q":"Sa Nevada, gaano katagal pagkatapos makakuha ng lisensya na hindi puwedeng magsakay ang tinedyer ng mga pasaherong wala pang 18 na hindi kapamilya?","o":["Isang buwan","Tatlong buwan","Anim na buwan","Dalawang taon"],"h1":"Kalahating taon ito.","h2":"Sa Nevada, ang bagong tinedyer na drayber ay hindi puwedeng magsakay ng mga pasaherong wala pang 18, maliban sa malapit na kapamilya, sa unang anim na buwan pagkatapos makakuha ng lisensya.","p":"Tama. Ang unang anim na buwan."},"ar":{"q":"في Nevada، كم مدة بعد الحصول على الرخصة لا يجوز للمراهق أن ينقل ركّابًا أعمارهم أقل من 18 سنة وليسوا من العائلة؟","o":["شهر واحد","ثلاثة أشهر","ستة أشهر","سنتان"],"h1":"هي نصف سنة.","h2":"في Nevada لا يجوز للسائق المراهق الجديد أن ينقل ركّابًا أعمارهم أقل من 18 سنة، ما عدا أفراد العائلة المباشرين، في الأشهر الستة الأولى بعد الحصول على الرخصة.","p":"صحيح. الأشهر الستة الأولى."},"ref":{"doc":"NV","page":15}},{"id":"nv-011","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, how many questions are on the car knowledge test, and how many must you answer correctly?","o":["20 questions, 15 correct","25 questions, 20 correct","40 questions, 30 correct","50 questions, 40 correct"],"h1":"You need 80 percent.","h2":"The Nevada knowledge test has 25 multiple-choice questions, and you must answer 20 correctly, which is 80 percent.","p":"Right. 20 out of 25."},"es":{"q":"En Nevada, ¿cuántas preguntas tiene el examen de conocimientos para carro, y cuántas debe contestar bien?","o":["20 preguntas, 15 correctas","25 preguntas, 20 correctas","40 preguntas, 30 correctas","50 preguntas, 40 correctas"],"h1":"Necesita el 80 por ciento.","h2":"El examen de conocimientos de Nevada tiene 25 preguntas de opción múltiple, y usted debe contestar 20 bien, que es el 80 por ciento.","p":"Correcto. 20 de 25."},"zh":{"q":"在 Nevada，小汽车知识考试有多少道题，必须答对多少道？","o":["20 道题，答对 15 道","25 道题，答对 20 道","40 道题，答对 30 道","50 道题，答对 40 道"],"h1":"你需要答对百分之 80。","h2":"Nevada 的知识考试有 25 道选择题，你必须答对 20 道，也就是百分之 80。","p":"对。25 道题答对 20 道。"},"vi":{"q":"Ở Nevada, bài thi kiến thức cho xe hơi có bao nhiêu câu hỏi, và bạn phải trả lời đúng bao nhiêu câu?","o":["20 câu, đúng 15 câu","25 câu, đúng 20 câu","40 câu, đúng 30 câu","50 câu, đúng 40 câu"],"h1":"Bạn cần đúng 80 phần trăm.","h2":"Bài thi kiến thức ở Nevada có 25 câu hỏi trắc nghiệm, và bạn phải trả lời đúng 20 câu, tức là 80 phần trăm.","p":"Đúng. 20 trên 25 câu."},"tl":{"q":"Sa Nevada, ilang tanong ang nasa knowledge test para sa kotse, at ilan ang dapat mong masagot nang tama?","o":["20 tanong, 15 tama","25 tanong, 20 tama","40 tanong, 30 tama","50 tanong, 40 tama"],"h1":"Kailangan mo ng 80 porsiyento.","h2":"Ang Nevada knowledge test ay may 25 multiple-choice na tanong, at dapat mong masagot nang tama ang 20, na 80 porsiyento.","p":"Tama. 20 sa 25."},"ar":{"q":"في Nevada، كم سؤالًا في اختبار المعرفة للسيارات، وكم سؤالًا يجب أن تجيب عنه إجابة صحيحة؟","o":["20 سؤالًا، 15 صحيحة","25 سؤالًا، 20 صحيحة","40 سؤالًا، 30 صحيحة","50 سؤالًا، 40 صحيحة"],"h1":"تحتاج إلى 80 بالمئة.","h2":"اختبار المعرفة في Nevada فيه 25 سؤالًا من نوع الاختيار من متعدّد، ويجب أن تجيب عن 20 منها إجابة صحيحة، أي 80 بالمئة.","p":"صحيح. 20 من 25."},"ref":{"doc":"NV","page":null}},{"id":"nv-013","scope":"NV","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nevada, how long is a passed knowledge test result valid?","o":["30 days","90 days","Six months","One year"],"h1":"It matches how long the permit lasts.","h2":"In Nevada, a passed knowledge test result is valid for one year from the date you pass.","p":"Right. The result is good for one year."},"es":{"q":"En Nevada, ¿por cuánto tiempo es válido el resultado de un examen de conocimientos aprobado?","o":["30 días","90 días","Seis meses","Un año"],"h1":"Coincide con lo que dura el permiso.","h2":"En Nevada, el resultado de un examen de conocimientos aprobado es válido por un año desde la fecha en que lo aprueba.","p":"Correcto. El resultado vale un año."},"zh":{"q":"在 Nevada，通过的知识考试成绩有效期多久？","o":["30 天","90 天","六个月","一年"],"h1":"它和学习驾照的有效期一样长。","h2":"在 Nevada，通过的知识考试成绩从你通过那天起有效一年。","p":"对。成绩有效一年。"},"vi":{"q":"Ở Nevada, kết quả thi kiến thức đã đậu có giá trị trong bao lâu?","o":["30 ngày","90 ngày","Sáu tháng","Một năm"],"h1":"Nó bằng thời hạn của giấy phép tập lái.","h2":"Ở Nevada, kết quả thi kiến thức đã đậu có giá trị một năm kể từ ngày bạn đậu.","p":"Đúng. Kết quả có giá trị một năm."},"tl":{"q":"Sa Nevada, gaano katagal valid ang resulta ng knowledge test na naipasa mo?","o":["30 araw","90 araw","Anim na buwan","Isang taon"],"h1":"Kapareho ito ng tagal ng permit.","h2":"Sa Nevada, ang resulta ng naipasang knowledge test ay valid nang isang taon mula sa petsa ng pagpasa mo.","p":"Tama. Valid ang resulta nang isang taon."},"ar":{"q":"في Nevada، كم مدة صلاحية نتيجة اختبار المعرفة بعد النجاح فيه؟","o":["30 يومًا","90 يومًا","ستة أشهر","سنة واحدة"],"h1":"هي نفس مدة صلاحية تصريح التعلّم.","h2":"في Nevada تبقى نتيجة اختبار المعرفة الناجحة صالحة لمدة سنة واحدة من تاريخ نجاحك.","p":"صحيح. النتيجة صالحة لمدة سنة واحدة."},"ref":{"doc":"NV","page":null}},{"id":"nv-014","scope":"NV","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nevada, in which languages can you take the car knowledge test?","o":["English only","Spanish only","English or Spanish","Any language you choose"],"h1":"This app uses the same two languages.","h2":"In Nevada you can take the car knowledge test in English or in Spanish.","p":"Right. English or Spanish."},"es":{"q":"En Nevada, ¿en qué idiomas puede tomar el examen de conocimientos para carro?","o":["Solo inglés","Solo español","Inglés o español","Cualquier idioma que elija"],"h1":"Esta aplicación usa los mismos dos idiomas.","h2":"En Nevada usted puede tomar el examen de conocimientos para carro en inglés o en español.","p":"Correcto. Inglés o español."},"zh":{"q":"在 Nevada，小汽车知识考试可以用哪些语言考？","o":["只有英语","只有西班牙语","英语或西班牙语","你选择的任何语言"],"h1":"这个应用最先用的也是这两种语言。","h2":"在 Nevada，小汽车知识考试可以用英语或西班牙语考。","p":"对。英语或西班牙语。"},"vi":{"q":"Ở Nevada, bạn có thể thi kiến thức cho xe hơi bằng những ngôn ngữ nào?","o":["Chỉ tiếng Anh","Chỉ tiếng Tây Ban Nha","Tiếng Anh hoặc tiếng Tây Ban Nha","Bất kỳ ngôn ngữ nào bạn chọn"],"h1":"Đó là hai ngôn ngữ chính của ứng dụng này.","h2":"Ở Nevada, bạn có thể thi kiến thức cho xe hơi bằng tiếng Anh hoặc tiếng Tây Ban Nha.","p":"Đúng. Tiếng Anh hoặc tiếng Tây Ban Nha."},"tl":{"q":"Sa Nevada, sa anong mga wika puwedeng kunin ang knowledge test para sa kotse?","o":["Ingles lamang","Espanyol lamang","Ingles o Espanyol","Kahit anong wikang pipiliin mo"],"h1":"Ito ang dalawang pangunahing wika ng app na ito.","h2":"Sa Nevada, puwede mong kunin ang knowledge test para sa kotse sa Ingles o sa Espanyol.","p":"Tama. Ingles o Espanyol."},"ar":{"q":"في Nevada، بأي لغات يمكنك أن تؤدّي اختبار المعرفة للسيارات؟","o":["الإنجليزية فقط","الإسبانية فقط","الإنجليزية أو الإسبانية","أي لغة تختارها"],"h1":"هما اللغتان الرئيسيتان في هذا التطبيق.","h2":"في Nevada يمكنك أن تؤدّي اختبار المعرفة للسيارات بالإنجليزية أو بالإسبانية.","p":"صحيح. الإنجليزية أو الإسبانية."},"ref":{"doc":"NV","page":12}},{"id":"nv-015","scope":"NV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nevada, what is the blood alcohol limit for drivers under 21?","o":[".02 percent",".05 percent",".08 percent",".10 percent"],"h1":"It is a tiny fraction of the adult limit.","h2":"In Nevada the blood alcohol limit for drivers under 21 is .02 percent, much lower than the adult limit of .08.","p":"Right. Under 21, the limit is .02."},"es":{"q":"En Nevada, ¿cuál es el límite de alcohol en la sangre para conductores menores de 21 años?","o":[".02 por ciento",".05 por ciento",".08 por ciento",".10 por ciento"],"h1":"Es una fracción muy pequeña del límite para adultos.","h2":"En Nevada el límite de alcohol en la sangre para conductores menores de 21 años es .02 por ciento, mucho menor que el límite de .08 para adultos.","p":"Correcto. Para menores de 21, el límite es .02."},"zh":{"q":"在 Nevada，未满 21 岁的司机血液酒精浓度上限是多少？","o":[".02%",".05%",".08%",".10%"],"h1":"它只是成年人上限的很小一部分。","h2":"在 Nevada，未满 21 岁的司机血液酒精浓度上限是 .02%，比成年人的上限 .08 低很多。","p":"对。未满 21 岁，上限是 .02。"},"vi":{"q":"Ở Nevada, giới hạn nồng độ cồn trong máu đối với người lái dưới 21 tuổi là bao nhiêu?","o":[".02 phần trăm",".05 phần trăm",".08 phần trăm",".10 phần trăm"],"h1":"Nó chỉ bằng một phần rất nhỏ của giới hạn cho người lớn.","h2":"Ở Nevada, giới hạn nồng độ cồn trong máu đối với người lái dưới 21 tuổi là .02 phần trăm, thấp hơn nhiều so với giới hạn .08 của người lớn.","p":"Đúng. Dưới 21 tuổi, giới hạn là .02."},"tl":{"q":"Sa Nevada, ano ang limitasyon ng alcohol sa dugo para sa mga drayber na wala pang 21?","o":[".02 porsiyento",".05 porsiyento",".08 porsiyento",".10 porsiyento"],"h1":"Napakaliit na bahagi ito ng limitasyon para sa adulto.","h2":"Sa Nevada, ang limitasyon ng alcohol sa dugo para sa mga drayber na wala pang 21 ay .02 porsiyento, mas mababa kaysa sa .08 na limitasyon para sa adulto.","p":"Tama. Kapag wala pang 21, .02 ang limitasyon."},"ar":{"q":"في Nevada، ما الحدّ الأقصى لنسبة الكحول في الدم للسائقين الذين أعمارهم أقل من 21 سنة؟","o":[".02 بالمئة",".05 بالمئة",".08 بالمئة",".10 بالمئة"],"h1":"هو جزء صغير جدًا من حدّ البالغين.","h2":"في Nevada الحدّ الأقصى لنسبة الكحول في الدم للسائقين الذين أعمارهم أقل من 21 سنة هو .02 بالمئة، وهو أقل بكثير من حدّ البالغين وهو .08.","p":"صحيح. تحت 21 سنة، الحدّ هو .02."},"ref":{"doc":"NV","page":79}},{"id":"nv-016","scope":"NV","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Nevada, the move-over law covers more than emergency vehicles. Which of these does it also cover?","o":["Parked cars at a mall","A stalled vehicle or debris on the road","Bicycles in a bike lane","Buses at a bus stop"],"h1":"The law also covers hazards on the road itself.","h2":"In Nevada the move-over law also covers traffic incidents, such as a crash, a stalled vehicle or debris on the road.","p":"Right. Stalled cars and debris count too."},"es":{"q":"En Nevada, la ley de cambiarse de carril cubre más que los vehículos de emergencia. ¿Qué otra cosa también cubre?","o":["Carros estacionados en un centro comercial","Un vehículo averiado o escombros en la vía","Bicicletas en una ciclovía","Autobuses en una parada"],"h1":"La ley también cubre peligros en la misma vía.","h2":"En Nevada la ley de cambiarse de carril también cubre incidentes de tráfico, como un choque, un vehículo averiado o escombros en la vía.","p":"Correcto. Los vehículos averiados y los escombros también cuentan."},"zh":{"q":"在 Nevada，让道变道法（move-over law）不只包括紧急车辆。它还包括下面哪一种？","o":["购物中心停着的车","路上抛锚的车或杂物","自行车道上的自行车","公交车站的公交车"],"h1":"这条法律也包括路面上的危险。","h2":"在 Nevada，让道变道法（move-over law）也包括交通事故现场，比如撞车、抛锚的车或路上的杂物。","p":"对。抛锚的车和杂物也算。"},"vi":{"q":"Ở Nevada, luật nhường làn (move-over law) không chỉ áp dụng cho xe khẩn cấp. Luật này còn áp dụng cho trường hợp nào dưới đây?","o":["Xe đậu ở trung tâm mua sắm","Một xe bị chết máy hoặc vật cản trên đường","Xe đạp trong làn xe đạp","Xe buýt ở trạm xe buýt"],"h1":"Luật này cũng áp dụng cho các mối nguy ngay trên mặt đường.","h2":"Ở Nevada, luật nhường làn cũng áp dụng cho sự cố giao thông, như tai nạn, xe bị chết máy hoặc vật cản trên đường.","p":"Đúng. Xe chết máy và vật cản cũng được tính."},"tl":{"q":"Sa Nevada, saklaw ng move-over law ang higit pa sa mga emergency vehicle. Alin sa mga ito ang saklaw rin nito?","o":["Mga nakaparadang sasakyan sa mall","Sasakyang tumirik o mga kalat sa kalsada","Mga bisikleta sa bike lane","Mga bus sa hintuan ng bus"],"h1":"Saklaw rin ng batas ang mga panganib sa mismong kalsada.","h2":"Sa Nevada, saklaw rin ng move-over law ang mga insidente sa trapiko, tulad ng banggaan, sasakyang tumirik o mga kalat sa kalsada.","p":"Tama. Kasama rin ang mga tumirik na sasakyan at kalat."},"ar":{"q":"في Nevada، قانون إفساح المسار (move-over law) لا يشمل مركبات الطوارئ فقط. أيّ مما يلي يشمله أيضًا؟","o":["سيارات متوقّفة في مركز تسوّق","مركبة معطّلة أو حطام على الطريق","دراجات هوائية في مسار الدراجات","حافلات في موقف الحافلات"],"h1":"القانون يشمل أيضًا المخاطر الموجودة على الطريق نفسه.","h2":"في Nevada يشمل قانون إفساح المسار أيضًا حوادث المرور، مثل التصادم أو مركبة معطّلة أو حطام على الطريق.","p":"صحيح. المركبات المعطّلة والحطام تُحسب أيضًا."},"ref":{"doc":"NV","page":null}},{"id":"nv-017","scope":"NV","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Nevada, what must you do when passing an emergency vehicle stopped on the shoulder with its lights flashing?","o":["Speed up to pass quickly","Stop in your lane","Honk to warn them","Slow down and, if you can, use a lane that is not next to it"],"h1":"Give them more space and less speed.","h2":"In Nevada you must slow down below the posted limit, drive with care, be ready to stop and, if you can, use a lane that is not next to the stopped emergency vehicle.","p":"Right. Slow down and move over."},"es":{"q":"En Nevada, ¿qué debe hacer al pasar un vehículo de emergencia detenido en el acotamiento con las luces encendidas?","o":["Acelerar para pasar rápido","Detenerse en su carril","Tocar la bocina para avisar","Bajar la velocidad y, si puede, usar un carril que no esté al lado"],"h1":"Deles más espacio y vaya más despacio.","h2":"En Nevada usted debe bajar la velocidad por debajo del límite indicado, manejar con cuidado, estar listo para detenerse y, si puede, usar un carril que no esté al lado del vehículo de emergencia detenido.","p":"Correcto. Baje la velocidad y cámbiese de carril."},"zh":{"q":"在 Nevada，经过停在路肩、闪着灯的紧急车辆时，你必须怎么做？","o":["加速快点开过去","在你的车道停下","按喇叭提醒他们","减速，如果可以，换到不靠近它的车道"],"h1":"给他们更多空间，开得更慢。","h2":"在 Nevada，你必须减速到标示的限速以下，小心开车，准备好停车，如果可以，换到不靠近停着的紧急车辆的车道。","p":"对。减速并让道变道。"},"vi":{"q":"Ở Nevada, bạn phải làm gì khi chạy ngang qua một xe khẩn cấp đang dừng bên lề đường với đèn đang nhấp nháy?","o":["Tăng tốc để qua nhanh","Dừng lại trong làn của bạn","Bấm còi để báo cho họ","Giảm tốc độ và, nếu có thể, đi vào làn không nằm sát xe đó"],"h1":"Hãy cho họ thêm khoảng trống và giảm tốc độ.","h2":"Ở Nevada, bạn phải giảm tốc độ xuống dưới mức giới hạn đã ghi, lái xe cẩn thận, sẵn sàng dừng lại và, nếu có thể, đi vào làn không nằm sát xe khẩn cấp đang dừng.","p":"Đúng. Giảm tốc độ và chuyển làn tránh xa."},"tl":{"q":"Sa Nevada, ano ang dapat mong gawin kapag dadaan ka sa isang emergency vehicle na nakahinto sa gilid ng kalsada na kumikislap ang ilaw?","o":["Bumilis para makalampas agad","Huminto sa iyong lane","Bumusina para balaan sila","Bumagal at, kung kaya, gumamit ng lane na hindi katabi nito"],"h1":"Bigyan sila ng mas maluwag na espasyo at bawasan ang bilis.","h2":"Sa Nevada, dapat kang bumagal nang mas mababa sa nakapaskil na speed limit, magmaneho nang maingat, maging handang huminto at, kung kaya, gumamit ng lane na hindi katabi ng nakahintong emergency vehicle.","p":"Tama. Bumagal at lumipat ng lane."},"ar":{"q":"في Nevada، ماذا يجب أن تفعل عندما تمرّ بمركبة طوارئ متوقّفة على كتف الطريق وأضواؤها تومض؟","o":["أسرع لتمرّ بسرعة","توقّف في مسارك","استخدم البوق لتحذيرهم","خفّف السرعة، وإذا استطعت، استخدم مسارًا غير مجاور لها"],"h1":"أعطهم مسافة أكبر وسرعة أقل.","h2":"في Nevada يجب أن تخفّف سرعتك إلى أقل من الحدّ المكتوب، وتقود بحذر، وتكون مستعدًا للتوقّف، وإذا استطعت، تستخدم مسارًا غير مجاور لمركبة الطوارئ المتوقّفة.","p":"صحيح. خفّف السرعة وابتعد عن المسار المجاور."},"ref":{"doc":"NV","page":61}},{"id":"nv-018","scope":"NV","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Nevada, when do you not have to stop for a stopped school bus with flashing red lights?","o":["When you are in a hurry","When no children are visible","When the bus is on the other roadway of a divided highway","When you are on a two-lane road"],"h1":"A barrier or dividing section separates you from the bus.","h2":"In Nevada, on a divided highway, you need not stop for a school bus that is on the other roadway; traffic going the same way as the bus must stop.","p":"Right. Only the divided highway exception applies."},"es":{"q":"En Nevada, ¿cuándo no tiene que detenerse ante un autobús escolar detenido con luces rojas intermitentes?","o":["Cuando tiene prisa","Cuando no se ven niños","Cuando el autobús está en el otro lado de una carretera dividida","Cuando va por una carretera de dos carriles"],"h1":"Una barrera o franja divisoria lo separa del autobús.","h2":"En Nevada, en una carretera dividida, usted no tiene que detenerse por un autobús escolar que está en la otra calzada; el tráfico que va en la misma dirección que el autobús sí debe detenerse.","p":"Correcto. Solo aplica la excepción de la carretera dividida."},"zh":{"q":"在 Nevada，什么时候不用为停着、闪着红灯的校车停车？","o":["你很赶时间时","看不到孩子时","校车在分隔公路的另一边道路上时","你在双车道的路上时"],"h1":"有障碍物或分隔带把你和校车分开。","h2":"在 Nevada，在分隔公路上，如果校车在另一边的道路上，你不用停车；和校车同方向的车必须停车。","p":"对。只有分隔公路是例外。"},"vi":{"q":"Ở Nevada, khi nào bạn không phải dừng lại cho xe buýt trường học đang dừng với đèn đỏ nhấp nháy?","o":["Khi bạn đang vội","Khi không thấy trẻ em nào","Khi xe buýt ở phía đường bên kia của xa lộ có dải phân cách","Khi bạn đang đi trên đường hai làn"],"h1":"Có một rào chắn hoặc dải phân cách ngăn giữa bạn và xe buýt.","h2":"Ở Nevada, trên xa lộ có dải phân cách, bạn không cần dừng lại cho xe buýt trường học ở phía đường bên kia; xe chạy cùng chiều với xe buýt thì phải dừng lại.","p":"Đúng. Chỉ có ngoại lệ xa lộ có dải phân cách."},"tl":{"q":"Sa Nevada, kailan hindi mo kailangang huminto para sa nakahintong school bus na may kumikislap na pulang ilaw?","o":["Kapag nagmamadali ka","Kapag walang nakikitang bata","Kapag nasa kabilang daan ng divided highway ang bus","Kapag nasa kalsadang may dalawang lane ka"],"h1":"May harang o pagitan na naghihiwalay sa iyo at sa bus.","h2":"Sa Nevada, sa divided highway, hindi mo kailangang huminto para sa school bus na nasa kabilang daan; ang trapikong papunta sa parehong direksiyon ng bus ay dapat huminto.","p":"Tama. Ang divided highway lamang ang eksepsiyon."},"ar":{"q":"في Nevada، متى لا يكون عليك أن تتوقّف لحافلة مدرسية متوقّفة وأضواؤها الحمراء تومض؟","o":["عندما تكون مستعجلًا","عندما لا ترى أي أطفال","عندما تكون الحافلة على الجهة الأخرى من طريق سريع مقسوم (divided highway)","عندما تكون على طريق من مسارين"],"h1":"هناك حاجز أو فاصل يفصلك عن الحافلة.","h2":"في Nevada، على الطريق السريع المقسوم، ليس عليك أن تتوقّف لحافلة مدرسية على الجهة الأخرى من الطريق؛ أما السيارات التي تسير في نفس اتجاه الحافلة فيجب أن تتوقّف.","p":"صحيح. الاستثناء الوحيد هو الطريق السريع المقسوم."},"ref":{"doc":"NV","page":64}},{"id":"nv-019","scope":"NV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nevada, how may an adult driver talk on a cell phone while driving?","o":["Only with a hands-free device","Holding the phone in one hand","Only at speeds under 25 mph","Any way they like"],"h1":"Your hands must stay free for the wheel.","h2":"In Nevada it is illegal to hold a phone to talk while driving, so an adult may only talk using a hands-free device.","p":"Right. Hands-free only."},"es":{"q":"En Nevada, ¿cómo puede un conductor adulto hablar por celular mientras maneja?","o":["Solo con un dispositivo manos libres","Sosteniendo el teléfono en una mano","Solo a menos de 25 mph","Como quiera"],"h1":"Sus manos deben quedar libres para el volante.","h2":"En Nevada es ilegal sostener el teléfono para hablar mientras maneja, así que un adulto solo puede hablar con un dispositivo manos libres.","p":"Correcto. Solo manos libres."},"zh":{"q":"在 Nevada，成年司机开车时可以怎样打手机？","o":["只能用免提设备","一只手拿着手机","只在车速低于 25 mph 时","想怎样都可以"],"h1":"你的手必须空出来握方向盘。","h2":"在 Nevada，开车时拿着手机通话是违法的，所以成年人只能用免提设备通话。","p":"对。只能用免提。"},"vi":{"q":"Ở Nevada, người lái xe là người lớn được nói chuyện điện thoại khi lái xe bằng cách nào?","o":["Chỉ dùng thiết bị rảnh tay (hands-free)","Cầm điện thoại bằng một tay","Chỉ khi chạy dưới 25 mph","Bằng bất kỳ cách nào họ muốn"],"h1":"Tay bạn phải luôn rảnh để cầm vô lăng.","h2":"Ở Nevada, cầm điện thoại để nói chuyện khi lái xe là phạm luật, vì vậy người lớn chỉ được nói chuyện bằng thiết bị rảnh tay.","p":"Đúng. Chỉ dùng thiết bị rảnh tay."},"tl":{"q":"Sa Nevada, paano puwedeng makipag-usap sa cell phone ang adultong drayber habang nagmamaneho?","o":["Gamit lamang ang hands-free na device","Hawak ang telepono sa isang kamay","Kapag ang bilis ay mas mababa sa 25 mph lamang","Kahit anong paraan na gusto nila"],"h1":"Dapat manatiling malaya ang iyong mga kamay para sa manibela.","h2":"Sa Nevada, bawal ang paghawak ng telepono para makipag-usap habang nagmamaneho, kaya ang adulto ay puwede lamang makipag-usap gamit ang hands-free na device.","p":"Tama. Hands-free lamang."},"ar":{"q":"في Nevada، كيف يمكن للسائق البالغ أن يتكلّم بالهاتف المحمول أثناء القيادة؟","o":["باستخدام جهاز من دون استخدام اليدين (hands-free) فقط","وهو يمسك الهاتف بيد واحدة","فقط بسرعة أقل من 25 mph","بأي طريقة يريدها"],"h1":"يجب أن تبقى يداك حرّتين لعجلة القيادة.","h2":"في Nevada يُمنع إمساك الهاتف للتكلّم أثناء القيادة، لذلك لا يمكن للبالغ أن يتكلّم إلا باستخدام جهاز من دون استخدام اليدين.","p":"صحيح. من دون استخدام اليدين فقط."},"ref":{"doc":"NV","page":43}},{"id":"nv-020","scope":"NV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nevada, what is the fine for a first handheld phone or texting offense in seven years?","o":["$25","$50","$250","$500"],"h1":"It is the lowest step of three: then $100, then $250.","h2":"In Nevada, the fine for a first handheld phone or texting offense in seven years is $50, and it can double in a work zone.","p":"Right. The first fine is $50."},"es":{"q":"En Nevada, ¿cuál es la multa por la primera infracción de usar el teléfono en la mano o enviar mensajes en siete años?","o":["$25","$50","$250","$500"],"h1":"Es el escalón más bajo de tres: luego $100, luego $250.","h2":"En Nevada, la multa por la primera infracción de teléfono en la mano o mensajes en siete años es de $50, y puede duplicarse en una zona de obras.","p":"Correcto. La primera multa es de $50."},"zh":{"q":"在 Nevada，七年内第一次因为手持手机或发短信被抓，罚款多少？","o":["$25","$50","$250","$500"],"h1":"它是三级里最低的一级：接下来是 $100，再接下来是 $250。","h2":"在 Nevada，七年内第一次因为手持手机或发短信被抓，罚款 $50，在施工区可能加倍。","p":"对。第一次罚 $50。"},"vi":{"q":"Ở Nevada, tiền phạt cho lần vi phạm đầu tiên trong bảy năm về cầm điện thoại hoặc nhắn tin khi lái xe là bao nhiêu?","o":["$25","$50","$250","$500"],"h1":"Đó là mức thấp nhất trong ba mức: sau đó là $100, rồi $250.","h2":"Ở Nevada, tiền phạt cho lần vi phạm đầu tiên trong bảy năm về cầm điện thoại hoặc nhắn tin là $50, và có thể tăng gấp đôi trong khu vực công trường.","p":"Đúng. Lần phạt đầu tiên là $50."},"tl":{"q":"Sa Nevada, magkano ang multa sa unang paglabag sa loob ng pitong taon sa paghawak ng telepono o pag-text habang nagmamaneho?","o":["$25","$50","$250","$500"],"h1":"Ito ang pinakamababa sa tatlong antas: susunod ang $100, tapos $250.","h2":"Sa Nevada, ang multa sa unang paglabag sa loob ng pitong taon sa paghawak ng telepono o pag-text ay $50, at puwede itong dumoble sa work zone.","p":"Tama. $50 ang unang multa."},"ar":{"q":"في Nevada، ما غرامة المخالفة الأولى خلال سبع سنوات لإمساك الهاتف أو كتابة الرسائل أثناء القيادة؟","o":["$25","$50","$250","$500"],"h1":"هي أقل درجة من ثلاث درجات: بعدها $100، ثم $250.","h2":"في Nevada غرامة المخالفة الأولى خلال سبع سنوات لإمساك الهاتف أو كتابة الرسائل هي $50، ويمكن أن تتضاعف في منطقة أعمال الطرق.","p":"صحيح. الغرامة الأولى هي $50."},"ref":{"doc":"NV","page":null}},{"id":"nv-021","scope":"NV","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Nevada, what is the highest speed limit the state may post on its highways?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"It matches the name of a big interstate across northern Nevada.","h2":"Nevada may post a speed limit of up to 80 mph on state highways, and only where a sign shows it.","p":"Right. The top posted limit is 80 mph."},"es":{"q":"En Nevada, ¿cuál es el límite de velocidad más alto que el estado puede indicar en sus carreteras?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Coincide con el nombre de una autopista grande en el norte de Nevada.","h2":"Nevada puede indicar un límite de hasta 80 mph en carreteras estatales, y solo donde un letrero lo muestre.","p":"Correcto. El límite más alto es 80 mph."},"zh":{"q":"在 Nevada，州政府在公路上最高可以标示多少限速？","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"它和横穿 Nevada 北部的一条大州际公路的号码一样。","h2":"Nevada 在州公路上最高可以标示 80 mph 的限速，而且只在有标志显示的地方。","p":"对。标示的最高限速是 80 mph。"},"vi":{"q":"Ở Nevada, giới hạn tốc độ cao nhất mà tiểu bang có thể ghi trên các xa lộ là bao nhiêu?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Nó trùng với số của một xa lộ liên bang lớn chạy qua miền bắc Nevada.","h2":"Nevada có thể ghi giới hạn tốc độ đến 80 mph trên các xa lộ của tiểu bang, và chỉ ở nơi có biển báo ghi như vậy.","p":"Đúng. Giới hạn cao nhất được ghi là 80 mph."},"tl":{"q":"Sa Nevada, ano ang pinakamataas na speed limit na puwedeng ipaskil ng estado sa mga highway nito?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Kapareho ito ng numero ng isang malaking interstate na dumadaan sa hilagang Nevada.","h2":"Puwedeng magpaskil ang Nevada ng speed limit na hanggang 80 mph sa mga highway ng estado, at kung saan lamang may karatulang nagpapakita nito.","p":"Tama. 80 mph ang pinakamataas na nakapaskil na limitasyon."},"ar":{"q":"في Nevada، ما أعلى حدّ للسرعة يمكن للولاية أن تضعه على طرقها السريعة؟","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"هو نفس رقم طريق سريع كبير بين الولايات (interstate) يعبر شمال Nevada.","h2":"يمكن لولاية Nevada أن تضع حدًّا للسرعة يصل إلى 80 mph على طرق الولاية السريعة، وفقط حيث توجد لافتة تُظهر ذلك.","p":"صحيح. أعلى حدّ مكتوب هو 80 mph."},"ref":{"doc":"NV","page":null}},{"id":"nv-022","scope":"NV","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nevada, how many demerit points in 12 months will get your license suspended?","o":["4 or more","8 or more","12 or more","10 or more"],"h1":"It is the number of months in a year.","h2":"In Nevada, your license is suspended if you get 12 or more demerit points in any 12-month period.","p":"Right. 12 points in 12 months means a suspension."},"es":{"q":"En Nevada, ¿cuántos puntos de demérito en 12 meses causan la suspensión de su licencia?","o":["4 o más","8 o más","12 o más","10 o más"],"h1":"Es el número de meses que tiene un año.","h2":"En Nevada, su licencia se suspende si acumula 12 o más puntos de demérito en cualquier período de 12 meses.","p":"Correcto. 12 puntos en 12 meses significan una suspensión."},"zh":{"q":"在 Nevada，12 个月内累计多少扣分会让你的驾照被暂停？","o":["4 分或以上","8 分或以上","12 分或以上","10 分或以上"],"h1":"它是一年里月份的数目。","h2":"在 Nevada，如果你在任何 12 个月内累计 12 分或以上的扣分，你的驾照会被暂停。","p":"对。12 个月内 12 分就会被暂停驾照。"},"vi":{"q":"Ở Nevada, bao nhiêu điểm phạt trong 12 tháng sẽ làm bằng lái của bạn bị đình chỉ?","o":["Từ 4 trở lên","Từ 8 trở lên","Từ 12 trở lên","Từ 10 trở lên"],"h1":"Đó là số tháng trong một năm.","h2":"Ở Nevada, bằng lái của bạn bị đình chỉ nếu bạn bị từ 12 điểm phạt trở lên trong bất kỳ khoảng 12 tháng nào.","p":"Đúng. 12 điểm trong 12 tháng nghĩa là bị đình chỉ bằng lái."},"tl":{"q":"Sa Nevada, ilang demerit point sa loob ng 12 buwan ang magpapasuspinde sa lisensya mo?","o":["4 o higit pa","8 o higit pa","12 o higit pa","10 o higit pa"],"h1":"Ito ang bilang ng buwan sa isang taon.","h2":"Sa Nevada, sinususpinde ang lisensya mo kung makakuha ka ng 12 o higit pang demerit point sa alinmang 12 buwan.","p":"Tama. Ang 12 point sa 12 buwan ay nangangahulugang suspensyon."},"ar":{"q":"في Nevada، كم نقطة مخالفة خلال 12 شهرًا تؤدي إلى إيقاف رخصتك؟","o":["4 أو أكثر","8 أو أكثر","12 أو أكثر","10 أو أكثر"],"h1":"هو عدد الأشهر في السنة.","h2":"في Nevada، تُوقَف رخصتك إذا حصلت على 12 نقطة مخالفة أو أكثر خلال أي فترة 12 شهرًا.","p":"صحيح. 12 نقطة في 12 شهرًا تعني إيقاف الرخصة."},"ref":{"doc":"NV","page":77}},{"id":"nv-023","scope":"NV","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nevada, how many demerit points can a DMV-approved traffic safety course remove?","o":["Up to 3 points","Up to 6 points","Up to 12 points","None at all"],"h1":"It is a small number, and you can do it once in 12 months.","h2":"In Nevada, a DMV-approved traffic safety course can remove up to 3 demerit points, once in a 12-month period.","p":"Right. Traffic school removes up to 3 points."},"es":{"q":"En Nevada, ¿cuántos puntos de demérito puede quitar un curso de seguridad vial aprobado por el DMV?","o":["Hasta 3 puntos","Hasta 6 puntos","Hasta 12 puntos","Ninguno"],"h1":"Es un número pequeño, y solo se puede hacer una vez cada 12 meses.","h2":"En Nevada, un curso de seguridad vial aprobado por el DMV puede quitar hasta 3 puntos de demérito, una vez en un período de 12 meses.","p":"Correcto. La escuela de tránsito quita hasta 3 puntos."},"zh":{"q":"在 Nevada，参加 DMV 认可的交通安全课程可以消除多少扣分？","o":["最多 3 分","最多 6 分","最多 12 分","一分也不能"],"h1":"它是一个小数字，而且 12 个月内只能上一次。","h2":"在 Nevada，DMV 认可的交通安全课程最多可以消除 3 分，12 个月内只能用一次。","p":"对。交通学校最多消除 3 分。"},"vi":{"q":"Ở Nevada, một khóa học an toàn giao thông được DMV chấp thuận có thể xóa bao nhiêu điểm phạt?","o":["Tối đa 3 điểm","Tối đa 6 điểm","Tối đa 12 điểm","Không xóa điểm nào"],"h1":"Đó là một con số nhỏ, và bạn chỉ được làm một lần trong 12 tháng.","h2":"Ở Nevada, một khóa học an toàn giao thông được DMV chấp thuận có thể xóa tối đa 3 điểm phạt, một lần trong khoảng 12 tháng.","p":"Đúng. Trường dạy luật giao thông xóa tối đa 3 điểm."},"tl":{"q":"Sa Nevada, ilang demerit point ang puwedeng alisin ng isang traffic safety course na aprubado ng DMV?","o":["Hanggang 3 point","Hanggang 6 na point","Hanggang 12 point","Wala kahit isa"],"h1":"Maliit na numero ito, at isang beses mo lang ito magagawa sa loob ng 12 buwan.","h2":"Sa Nevada, ang traffic safety course na aprubado ng DMV ay puwedeng mag-alis ng hanggang 3 demerit point, isang beses sa loob ng 12 buwan.","p":"Tama. Ang traffic school ay nag-aalis ng hanggang 3 point."},"ar":{"q":"في Nevada، كم نقطة مخالفة يمكن أن تمحوها دورة سلامة مرورية معتمدة من DMV؟","o":["حتى 3 نقاط","حتى 6 نقاط","حتى 12 نقطة","لا شيء أبدًا"],"h1":"هو رقم صغير، ويمكنك فعل ذلك مرة واحدة خلال 12 شهرًا.","h2":"في Nevada، يمكن لدورة سلامة مرورية معتمدة من DMV أن تمحو حتى 3 نقاط مخالفة، مرة واحدة خلال فترة 12 شهرًا.","p":"صحيح. مدرسة المرور تمحو حتى 3 نقاط."},"ref":{"doc":"NV","page":77}},{"id":"nv-024","scope":"NV","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nevada, police do not investigate a crash that causes $750 or more in damage. What must you do?","o":["Nothing, if no one was hurt","Tell your insurance company only","Call the DMV within 30 days","Send a crash report form (SR-1) to the DMV within 10 days"],"h1":"There is a form, and you have less than two weeks.","h2":"In Nevada, if police do not investigate a crash with $750 or more in damage or an injury, you must send an SR-1 crash report to the DMV within 10 days.","p":"Right. You send the SR-1 form to the DMV within 10 days."},"es":{"q":"En Nevada, la policía no investiga un choque que causa $750 o más en daños. ¿Qué debe hacer usted?","o":["Nada, si nadie resultó herido","Avisar solo a su compañía de seguros","Llamar al DMV dentro de 30 días","Enviar un formulario de informe de choque (SR-1) al DMV dentro de 10 días"],"h1":"Hay un formulario, y tiene menos de dos semanas.","h2":"En Nevada, si la policía no investiga un choque con $750 o más en daños o con heridos, usted debe enviar un informe de choque SR-1 al DMV dentro de 10 días.","p":"Correcto. Usted envía el formulario SR-1 al DMV dentro de 10 días."},"zh":{"q":"在 Nevada，如果警察没有调查一起造成 $750 或以上损失的车祸，你必须做什么？","o":["如果没人受伤，什么都不用做","只告诉你的保险公司","在 30 天内打电话给 DMV","在 10 天内把车祸报告表（SR-1）交给 DMV"],"h1":"有一张表格，而且你的时间不到两个星期。","h2":"在 Nevada，如果警察没有调查一起造成 $750 或以上损失或有人受伤的车祸，你必须在 10 天内把 SR-1 车祸报告交给 DMV。","p":"对。你要在 10 天内把 SR-1 表格交给 DMV。"},"vi":{"q":"Ở Nevada, cảnh sát không điều tra một vụ tai nạn gây thiệt hại từ $750 trở lên. Bạn phải làm gì?","o":["Không cần làm gì, nếu không ai bị thương","Chỉ báo cho công ty bảo hiểm","Gọi cho DMV trong vòng 30 ngày","Gửi mẫu báo cáo tai nạn (SR-1) cho DMV trong vòng 10 ngày"],"h1":"Có một mẫu đơn, và bạn có chưa tới hai tuần.","h2":"Ở Nevada, nếu cảnh sát không điều tra một vụ tai nạn gây thiệt hại từ $750 trở lên hoặc có người bị thương, bạn phải gửi báo cáo tai nạn SR-1 cho DMV trong vòng 10 ngày.","p":"Đúng. Bạn gửi mẫu SR-1 cho DMV trong vòng 10 ngày."},"tl":{"q":"Sa Nevada, hindi inimbestigahan ng pulis ang isang banggaan na may pinsalang $750 o higit pa. Ano ang dapat mong gawin?","o":["Wala, kung walang nasaktan","Sabihan lamang ang iyong insurance company","Tawagan ang DMV sa loob ng 30 araw","Magpadala ng crash report form (SR-1) sa DMV sa loob ng 10 araw"],"h1":"May isang form, at wala pang dalawang linggo ang iyong oras.","h2":"Sa Nevada, kung hindi inimbestigahan ng pulis ang isang banggaan na may pinsalang $750 o higit pa o may nasaktan, dapat kang magpadala ng SR-1 crash report sa DMV sa loob ng 10 araw.","p":"Tama. Ipapadala mo ang SR-1 form sa DMV sa loob ng 10 araw."},"ar":{"q":"في Nevada، لم تحقّق الشرطة في حادث سبّب أضرارًا بقيمة $750 أو أكثر. ماذا يجب أن تفعل؟","o":["لا شيء، إذا لم يُصَب أحد","أخبر شركة التأمين فقط","اتصل بـ DMV خلال 30 يومًا","أرسل نموذج تقرير الحادث (SR-1) إلى DMV خلال 10 أيام"],"h1":"هناك نموذج، ولديك أقل من أسبوعين.","h2":"في Nevada، إذا لم تحقّق الشرطة في حادث فيه أضرار بقيمة $750 أو أكثر أو فيه إصابة، يجب أن ترسل تقرير الحادث SR-1 إلى DMV خلال 10 أيام.","p":"صحيح. ترسل نموذج SR-1 إلى DMV خلال 10 أيام."},"ref":{"doc":"NV","page":75}},{"id":"nv-025","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, what is the minimum liability insurance for injury to one person in a crash?","o":["$10,000","$25,000","$50,000","$100,000"],"h1":"It is half of the amount required for two or more people.","h2":"In Nevada, the minimum liability insurance is $25,000 for injury or death of one person in a crash.","p":"Right. The minimum for one person is $25,000."},"es":{"q":"En Nevada, ¿cuál es el seguro de responsabilidad civil mínimo por lesiones a una persona en un choque?","o":["$10,000","$25,000","$50,000","$100,000"],"h1":"Es la mitad de lo que se exige para dos o más personas.","h2":"En Nevada, el seguro de responsabilidad civil mínimo es de $25,000 por lesiones o muerte de una persona en un choque.","p":"Correcto. El mínimo para una persona es de $25,000."},"zh":{"q":"在 Nevada，车祸中一个人受伤的最低责任保险金额是多少？","o":["$10,000","$25,000","$50,000","$100,000"],"h1":"它是两人或以上所需金额的一半。","h2":"在 Nevada，车祸中一个人受伤或死亡的最低责任保险金额是 $25,000。","p":"对。一个人的最低金额是 $25,000。"},"vi":{"q":"Ở Nevada, bảo hiểm trách nhiệm tối thiểu cho thương tích của một người trong một vụ tai nạn là bao nhiêu?","o":["$10,000","$25,000","$50,000","$100,000"],"h1":"Đó là một nửa số tiền bắt buộc cho hai người trở lên.","h2":"Ở Nevada, bảo hiểm trách nhiệm tối thiểu là $25,000 cho thương tích hoặc tử vong của một người trong một vụ tai nạn.","p":"Đúng. Mức tối thiểu cho một người là $25,000."},"tl":{"q":"Sa Nevada, magkano ang pinakamababang liability insurance para sa pinsala sa isang tao sa isang banggaan?","o":["$10,000","$25,000","$50,000","$100,000"],"h1":"Kalahati ito ng halagang kailangan para sa dalawa o higit pang tao.","h2":"Sa Nevada, ang pinakamababang liability insurance ay $25,000 para sa pinsala o pagkamatay ng isang tao sa isang banggaan.","p":"Tama. $25,000 ang pinakamababa para sa isang tao."},"ar":{"q":"في Nevada، ما الحدّ الأدنى لتأمين المسؤولية عن إصابة شخص واحد في حادث؟","o":["$10,000","$25,000","$50,000","$100,000"],"h1":"هو نصف المبلغ المطلوب لشخصين أو أكثر.","h2":"في Nevada، الحدّ الأدنى لتأمين المسؤولية هو $25,000 عن إصابة شخص واحد أو وفاته في حادث.","p":"صحيح. الحدّ الأدنى لشخص واحد هو $25,000."},"ref":{"doc":"NV","page":75}},{"id":"nv-026","scope":"NV","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Nevada, which children must ride in an approved child restraint system?","o":["Only babies under 1 year","Children under 12, at any height","Children under 6 who are shorter than 57 inches","Only children riding in the front seat"],"h1":"Think of age six and a height of 4 feet 9 inches.","h2":"In Nevada, children under 6 who are shorter than 57 inches must ride in an approved child restraint system.","p":"Right. Under 6 and under 57 inches means a child restraint."},"es":{"q":"En Nevada, ¿qué niños deben viajar en un sistema de retención infantil aprobado?","o":["Solo los bebés menores de 1 año","Los menores de 12 años, de cualquier estatura","Los menores de 6 años que miden menos de 57 pulgadas","Solo los niños que viajan en el asiento delantero"],"h1":"Piense en la edad de seis años y una estatura de 4 pies 9 pulgadas.","h2":"En Nevada, los niños menores de 6 años que miden menos de 57 pulgadas deben viajar en un sistema de retención infantil aprobado.","p":"Correcto. Menor de 6 años y de menos de 57 pulgadas: va en un asiento de seguridad."},"zh":{"q":"在 Nevada，哪些孩子必须坐在认可的儿童安全座椅里？","o":["只有不到 1 岁的婴儿","不到 12 岁的孩子，不管多高","不到 6 岁而且身高不到 57 英寸的孩子","只有坐在前座的孩子"],"h1":"想一想 6 岁和 4 英尺 9 英寸的身高。","h2":"在 Nevada，不到 6 岁而且身高不到 57 英寸的孩子必须坐在认可的儿童安全座椅里。","p":"对。不到 6 岁并且不到 57 英寸，就要用儿童安全座椅。"},"vi":{"q":"Ở Nevada, những trẻ em nào phải ngồi trong hệ thống ghế an toàn trẻ em được chấp thuận?","o":["Chỉ em bé dưới 1 tuổi","Trẻ em dưới 12 tuổi, bất kể chiều cao","Trẻ em dưới 6 tuổi và thấp hơn 57 inch","Chỉ trẻ em ngồi ở ghế trước"],"h1":"Hãy nghĩ đến 6 tuổi và chiều cao 4 feet 9 inch.","h2":"Ở Nevada, trẻ em dưới 6 tuổi và thấp hơn 57 inch phải ngồi trong hệ thống ghế an toàn trẻ em được chấp thuận.","p":"Đúng. Dưới 6 tuổi và dưới 57 inch thì phải dùng ghế an toàn trẻ em."},"tl":{"q":"Sa Nevada, aling mga bata ang dapat sumakay sa aprubadong child restraint system?","o":["Mga sanggol lamang na wala pang 1 taon","Mga batang wala pang 12 taon, kahit gaano kataas","Mga batang wala pang 6 na taon at mas maliit sa 57 pulgada","Mga batang nakaupo lamang sa harapang upuan"],"h1":"Isipin ang edad na anim at taas na 4 na talampakan at 9 na pulgada.","h2":"Sa Nevada, ang mga batang wala pang 6 na taon at mas maliit sa 57 pulgada ay dapat sumakay sa aprubadong child restraint system.","p":"Tama. Wala pang 6 na taon at mas maliit sa 57 pulgada ay nangangahulugan ng child restraint."},"ar":{"q":"في Nevada، أيّ الأطفال يجب أن يركبوا في مقعد أمان معتمد للأطفال؟","o":["الرضّع تحت عمر سنة واحدة فقط","الأطفال تحت 12 سنة، مهما كان طولهم","الأطفال تحت 6 سنوات الذين طولهم أقل من 57 إنشًا","الأطفال الذين يجلسون في المقعد الأمامي فقط"],"h1":"فكّر في عمر ست سنوات وطول 4 أقدام و9 إنشات.","h2":"في Nevada، يجب أن يركب الأطفال تحت 6 سنوات الذين طولهم أقل من 57 إنشًا في مقعد أمان معتمد للأطفال.","p":"صحيح. تحت 6 سنوات وأقل من 57 إنشًا يعني مقعد أمان للأطفال."},"ref":{"doc":"NV","page":25}},{"id":"nv-027","scope":"NV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nevada, you must use headlights when you cannot clearly see people or vehicles at what distance?","o":["1,000 feet","300 feet","100 feet","2 miles"],"h1":"It is a little more than three football fields.","h2":"In Nevada, headlights are required whenever you cannot clearly see people or vehicles 1,000 feet away.","p":"Right. Headlights go on when you cannot see clearly at 1,000 feet."},"es":{"q":"En Nevada, ¿debe usar las luces delanteras cuando no puede ver con claridad a personas o vehículos a qué distancia?","o":["1,000 pies","300 pies","100 pies","2 millas"],"h1":"Es un poco más que tres campos de fútbol americano.","h2":"En Nevada, las luces delanteras son obligatorias siempre que no pueda ver con claridad a personas o vehículos a 1,000 pies.","p":"Correcto. Las luces se encienden cuando no se ve bien a 1,000 pies."},"zh":{"q":"在 Nevada，当你在多远的距离看不清楚行人或车辆时，必须开大灯？","o":["1,000 英尺","300 英尺","100 英尺","2 英里"],"h1":"它比三个足球场长一点。","h2":"在 Nevada，只要你看不清楚 1,000 英尺外的行人或车辆，就必须开大灯。","p":"对。在 1,000 英尺看不清楚时就要开大灯。"},"vi":{"q":"Ở Nevada, bạn phải bật đèn pha khi không thể nhìn rõ người hoặc xe ở khoảng cách bao xa?","o":["1,000 feet","300 feet","100 feet","2 dặm"],"h1":"Nó dài hơn ba sân bóng bầu dục một chút.","h2":"Ở Nevada, bạn phải bật đèn pha bất cứ khi nào bạn không thể nhìn rõ người hoặc xe ở cách xa 1,000 feet.","p":"Đúng. Bật đèn pha khi bạn không nhìn rõ ở 1,000 feet."},"tl":{"q":"Sa Nevada, dapat kang gumamit ng headlight kapag hindi mo malinaw na makita ang mga tao o sasakyan sa anong layo?","o":["1,000 talampakan","300 talampakan","100 talampakan","2 milya"],"h1":"Medyo higit ito sa haba ng tatlong football field.","h2":"Sa Nevada, kailangan ang headlight tuwing hindi mo malinaw na makita ang mga tao o sasakyan na 1,000 talampakan ang layo.","p":"Tama. Binubuksan ang headlight kapag hindi ka makakita nang malinaw sa 1,000 talampakan."},"ar":{"q":"في Nevada، يجب أن تشغّل المصابيح الأمامية عندما لا ترى الناس أو المركبات بوضوح على أيّ مسافة؟","o":["1,000 قدم","300 قدم","100 قدم","2 ميل"],"h1":"هي أكثر قليلًا من طول ثلاثة ملاعب كرة قدم أمريكية.","h2":"في Nevada، يجب تشغيل المصابيح الأمامية كلما لم تستطع أن ترى الناس أو المركبات بوضوح على بُعد 1,000 قدم.","p":"صحيح. تُشغَّل المصابيح الأمامية عندما لا ترى بوضوح على بُعد 1,000 قدم."},"ref":{"doc":"NV","page":56}},{"id":"nv-028","scope":"NV","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Nevada, when is a school zone speed limit in effect, unless signs say otherwise?","o":["Every day of the year, at all hours","School days, from 7 a.m. to 3 p.m. only","Only when a crossing guard is in the street","School days, from 30 minutes before to 30 minutes after classes"],"h1":"It covers the school day plus a short time on each side.","h2":"In Nevada, unless signs say otherwise, the school zone limit applies on school days from half an hour before school starts until half an hour after it ends.","p":"Right. It runs from half an hour before to half an hour after school."},"es":{"q":"En Nevada, ¿cuándo rige el límite de velocidad de una zona escolar, si las señales no dicen otra cosa?","o":["Todos los días del año, a toda hora","En días de clase, solo de 7 a.m. a 3 p.m.","Solo cuando hay un guardia de cruce en la calle","En días de clase, de 30 minutos antes a 30 minutos después de las clases"],"h1":"Cubre el horario escolar más un rato antes y después.","h2":"En Nevada, si las señales no dicen otra cosa, el límite de la zona escolar rige en días de clase desde media hora antes de que empiecen las clases hasta media hora después de que terminen.","p":"Correcto. Rige desde media hora antes hasta media hora después de las clases."},"zh":{"q":"在 Nevada，如果没有标志另外说明，学校区的限速什么时候有效？","o":["一年中每一天，全天","上学日，只在早上 7 点到下午 3 点","只在有交通协管员站在街上时","上学日，从上课前 30 分钟到放学后 30 分钟"],"h1":"它包括上学时间，再加上前后一小段时间。","h2":"在 Nevada，除非标志另外说明，学校区限速在上学日从上学前半小时一直到放学后半小时有效。","p":"对。从上学前半小时到放学后半小时。"},"vi":{"q":"Ở Nevada, giới hạn tốc độ khu vực trường học có hiệu lực khi nào, trừ khi biển báo ghi khác?","o":["Mọi ngày trong năm, mọi giờ","Ngày đi học, chỉ từ 7 giờ sáng đến 3 giờ chiều","Chỉ khi có người hướng dẫn qua đường đứng trên đường","Ngày đi học, từ 30 phút trước đến 30 phút sau giờ học"],"h1":"Nó bao gồm giờ học cộng thêm một khoảng thời gian ngắn ở trước và sau.","h2":"Ở Nevada, trừ khi biển báo ghi khác, giới hạn tốc độ khu vực trường học áp dụng vào ngày đi học, từ nửa giờ trước khi vào học đến nửa giờ sau khi tan học.","p":"Đúng. Nó áp dụng từ nửa giờ trước đến nửa giờ sau giờ học."},"tl":{"q":"Sa Nevada, kailan may bisa ang speed limit sa school zone, maliban kung iba ang sinasabi ng mga karatula?","o":["Araw-araw sa buong taon, sa lahat ng oras","Sa mga araw ng pasok, mula 7 a.m. hanggang 3 p.m. lamang","Kapag may crossing guard lamang sa kalye","Sa mga araw ng pasok, mula 30 minuto bago hanggang 30 minuto pagkatapos ng klase"],"h1":"Saklaw nito ang oras ng pasok, at maikling oras bago at pagkatapos.","h2":"Sa Nevada, maliban kung iba ang sinasabi ng mga karatula, may bisa ang limitasyon sa school zone sa mga araw ng pasok mula kalahating oras bago magsimula ang klase hanggang kalahating oras pagkatapos nito matapos.","p":"Tama. Mula kalahating oras bago hanggang kalahating oras pagkatapos ng klase."},"ar":{"q":"في Nevada، متى يكون حدّ السرعة في منطقة المدرسة ساريًا، إلا إذا قالت اللافتات غير ذلك؟","o":["كل يوم في السنة، في كل الساعات","في أيام الدراسة، من 7 صباحًا إلى 3 بعد الظهر فقط","فقط عندما يكون حارس عبور في الشارع","في أيام الدراسة، من 30 دقيقة قبل الحصص إلى 30 دقيقة بعدها"],"h1":"يشمل اليوم الدراسي ووقتًا قصيرًا قبله وبعده.","h2":"في Nevada، إلا إذا قالت اللافتات غير ذلك، يسري حدّ السرعة في منطقة المدرسة في أيام الدراسة من نصف ساعة قبل بدء الدراسة حتى نصف ساعة بعد انتهائها.","p":"صحيح. يسري من نصف ساعة قبل الدراسة إلى نصف ساعة بعدها."},"ref":{"doc":"NV","page":33}},{"id":"nv-029","scope":"NV","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Nevada, you pass a bicycle on a road with only one lane in your direction. How much space must you leave?","o":["At least 1 foot","At least 2 feet","At least 3 feet","At least 10 feet"],"h1":"It is about the length of a yardstick.","h2":"In Nevada, when there is no other lane to move into, you must pass a bicycle on its left with at least three feet of space.","p":"Right. Give a bicycle at least three feet when you pass."},"es":{"q":"En Nevada, usted pasa a una bicicleta en una calle con un solo carril en su dirección. ¿Cuánto espacio debe dejar?","o":["Por lo menos 1 pie","Por lo menos 2 pies","Por lo menos 3 pies","Por lo menos 10 pies"],"h1":"Es más o menos el largo de una regla de una yarda.","h2":"En Nevada, cuando no hay otro carril al cual moverse, usted debe pasar a una bicicleta por su izquierda dejando por lo menos tres pies de espacio.","p":"Correcto. Deje por lo menos tres pies a una bicicleta al pasarla."},"zh":{"q":"在 Nevada，你在本方向只有一条车道的道路上超过一辆自行车。你必须留出多少空间？","o":["至少 1 英尺","至少 2 英尺","至少 3 英尺","至少 10 英尺"],"h1":"大约是一根码尺（yardstick）的长度。","h2":"在 Nevada，当没有别的车道可以换过去时，你必须从自行车的左边超过它，并留出至少三英尺的空间。","p":"对。超过自行车时，至少要留出三英尺。"},"vi":{"q":"Ở Nevada, bạn vượt một xe đạp trên con đường chỉ có một làn theo hướng của bạn. Bạn phải chừa khoảng trống bao nhiêu?","o":["Ít nhất 1 foot","Ít nhất 2 feet","Ít nhất 3 feet","Ít nhất 10 feet"],"h1":"Nó dài khoảng bằng một cây thước yard.","h2":"Ở Nevada, khi không có làn nào khác để chuyển sang, bạn phải vượt xe đạp ở bên trái của nó và chừa ít nhất ba feet khoảng trống.","p":"Đúng. Hãy chừa cho xe đạp ít nhất ba feet khi bạn vượt."},"tl":{"q":"Sa Nevada, nag-o-overtake ka sa isang bisikleta sa kalsadang may iisang lane lang sa direksyon mo. Gaano kalaking espasyo ang dapat mong iwan?","o":["Hindi bababa sa 1 talampakan","Hindi bababa sa 2 talampakan","Hindi bababa sa 3 talampakan","Hindi bababa sa 10 talampakan"],"h1":"Halos kasinghaba ito ng isang yardstick (panukat na isang yarda).","h2":"Sa Nevada, kapag walang ibang lane na malilipatan, dapat mong lampasan ang bisikleta sa kaliwa nito at mag-iwan ng hindi bababa sa tatlong talampakan na espasyo.","p":"Tama. Bigyan ang bisikleta ng hindi bababa sa tatlong talampakan kapag lumalampas ka."},"ar":{"q":"في Nevada، تتجاوز درّاجة على طريق فيه مسار واحد فقط في اتجاهك. كم مسافة يجب أن تترك؟","o":["1 قدم على الأقل","2 قدم على الأقل","3 أقدام على الأقل","10 أقدام على الأقل"],"h1":"هي تقريبًا طول مسطرة الياردة.","h2":"في Nevada، عندما لا يوجد مسار آخر تنتقل إليه، يجب أن تتجاوز الدرّاجة من يسارها وتترك مسافة ثلاثة أقدام على الأقل.","p":"صحيح. اترك للدرّاجة ثلاثة أقدام على الأقل عندما تتجاوزها."},"ref":{"doc":"NV","page":48}},{"id":"nv-030","scope":"NV","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Nevada, you are on a highway outside a city with two lanes in your direction. When is it illegal to stay in the far left lane?","o":["When you go slower than the speed limit and a faster car comes up behind you","Any time it is dark outside","When you are about to pass a slower car","Any time you drive faster than 45 mph"],"h1":"Think about a faster driver who wants to get by.","h2":"In Nevada, on a highway with two lanes in your direction, it is illegal to stay in the far left lane below the speed limit when a faster vehicle is coming up behind you in that lane.","p":"Right. If you are slower than the limit and someone faster is behind you, leave the left lane."},"es":{"q":"En Nevada, usted va por una carretera fuera de la ciudad con dos carriles en su dirección. ¿Cuándo es ilegal quedarse en el carril de la extrema izquierda?","o":["Cuando va más despacio que el límite de velocidad y un carro más rápido se acerca por detrás","Siempre que está oscuro afuera","Cuando está por pasar a un carro más lento","Siempre que maneja a más de 45 mph"],"h1":"Piense en un conductor más rápido que quiere pasar.","h2":"En Nevada, en una carretera con dos carriles en su dirección, es ilegal quedarse en el carril de la extrema izquierda por debajo del límite de velocidad cuando un vehículo más rápido se acerca por detrás en ese carril.","p":"Correcto. Si va más lento que el límite y alguien más rápido viene detrás, deje el carril izquierdo."},"zh":{"q":"在 Nevada，你在城外的公路上，本方向有两条车道。什么时候留在最左边的车道是违法的？","o":["当你开得比限速慢，而有一辆更快的车从后面开过来时","天黑的任何时候","当你正要超过一辆较慢的车时","你开得比 45 mph 快的任何时候"],"h1":"想一想一位想开过去的更快的司机。","h2":"在 Nevada，在本方向有两条车道的公路上，如果你开得比限速慢，而有一辆更快的车在这条车道上从你后面开过来，留在最左边的车道就是违法的。","p":"对。如果你比限速慢，而后面有更快的车，就要离开左车道。"},"vi":{"q":"Ở Nevada, bạn đang ở trên xa lộ ngoài thành phố có hai làn theo hướng của bạn. Khi nào ở lại làn ngoài cùng bên trái là phạm luật?","o":["Khi bạn chạy chậm hơn tốc độ giới hạn và có một xe nhanh hơn chạy đến phía sau bạn","Bất cứ lúc nào trời tối","Khi bạn sắp vượt một xe chạy chậm hơn","Bất cứ lúc nào bạn chạy nhanh hơn 45 mph"],"h1":"Hãy nghĩ đến một người lái xe nhanh hơn muốn đi qua.","h2":"Ở Nevada, trên xa lộ có hai làn theo hướng của bạn, việc ở lại làn ngoài cùng bên trái khi chạy chậm hơn tốc độ giới hạn là phạm luật nếu có một xe nhanh hơn đang chạy đến phía sau bạn trong làn đó.","p":"Đúng. Nếu bạn chạy chậm hơn giới hạn và có người nhanh hơn ở phía sau, hãy rời làn bên trái."},"tl":{"q":"Sa Nevada, nasa highway ka sa labas ng lungsod na may dalawang lane sa direksyon mo. Kailan bawal manatili sa pinakakaliwang lane?","o":["Kapag mas mabagal ka kaysa sa speed limit at may mas mabilis na sasakyang dumarating sa likod mo","Anumang oras na madilim sa labas","Kapag malapit ka nang lumampas sa mas mabagal na sasakyan","Anumang oras na mas mabilis ka sa 45 mph"],"h1":"Isipin ang mas mabilis na drayber na gustong makadaan.","h2":"Sa Nevada, sa highway na may dalawang lane sa direksyon mo, bawal manatili sa pinakakaliwang lane nang mas mabagal sa speed limit kapag may mas mabilis na sasakyang dumarating sa likod mo sa lane na iyon.","p":"Tama. Kung mas mabagal ka sa limit at may mas mabilis sa likod mo, umalis ka sa kaliwang lane."},"ar":{"q":"في Nevada، أنت على طريق سريع خارج المدينة فيه مساران في اتجاهك. متى يكون البقاء في المسار الأيسر الأقصى مخالفًا للقانون؟","o":["عندما تسير أبطأ من حد السرعة وتقترب سيارة أسرع من خلفك","في أي وقت يكون فيه الجو مظلمًا","عندما تكون على وشك تجاوز سيارة أبطأ","في أي وقت تسير فيه أسرع من 45 mph"],"h1":"فكّر في سائق أسرع يريد أن يمرّ.","h2":"في Nevada، على طريق سريع فيه مساران في اتجاهك، يُمنع البقاء في المسار الأيسر الأقصى بسرعة أقل من حد السرعة عندما تقترب مركبة أسرع من خلفك في هذا المسار.","p":"صحيح. إذا كنت أبطأ من الحد وكان خلفك من هو أسرع، فاترك المسار الأيسر."},"ref":{"doc":"NV","page":47}},{"id":"nv-031","scope":"NV","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Nevada, how close to the nearest rail of a railroad may you park?","o":["No closer than 10 feet","No closer than 15 feet","No closer than 25 feet","No closer than 50 feet"],"h1":"It is the largest of these distances.","h2":"In Nevada you may not park within 50 feet of the nearest rail of a railroad.","p":"Right. Park at least 50 feet from the nearest rail."},"es":{"q":"En Nevada, ¿qué tan cerca del riel más cercano de un ferrocarril puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 15 pies","No más cerca de 25 pies","No más cerca de 50 pies"],"h1":"Es la mayor de estas distancias.","h2":"En Nevada usted no puede estacionarse a menos de 50 pies del riel más cercano de un ferrocarril.","p":"Correcto. Estaciónese por lo menos a 50 pies del riel más cercano."},"zh":{"q":"在 Nevada，你可以在离铁路最近的铁轨多近的地方停车？","o":["不能近于 10 英尺","不能近于 15 英尺","不能近于 25 英尺","不能近于 50 英尺"],"h1":"它是这些距离中最大的一个。","h2":"在 Nevada，你不可以在离铁路最近的铁轨 50 英尺以内停车。","p":"对。停车时要离最近的铁轨至少 50 英尺。"},"vi":{"q":"Ở Nevada, bạn được đậu xe gần đường ray gần nhất của đường xe lửa đến mức nào?","o":["Không gần hơn 10 feet","Không gần hơn 15 feet","Không gần hơn 25 feet","Không gần hơn 50 feet"],"h1":"Đó là khoảng cách lớn nhất trong các khoảng cách này.","h2":"Ở Nevada, bạn không được đậu xe trong vòng 50 feet tính từ đường ray gần nhất của đường xe lửa.","p":"Đúng. Hãy đậu xe cách đường ray gần nhất ít nhất 50 feet."},"tl":{"q":"Sa Nevada, gaano kalapit sa pinakamalapit na riles ng tren ka puwedeng pumarada?","o":["Hindi lalapit sa 10 talampakan","Hindi lalapit sa 15 talampakan","Hindi lalapit sa 25 talampakan","Hindi lalapit sa 50 talampakan"],"h1":"Ito ang pinakamalaki sa mga layong ito.","h2":"Sa Nevada, hindi ka puwedeng pumarada sa loob ng 50 talampakan mula sa pinakamalapit na riles ng tren.","p":"Tama. Pumarada nang hindi bababa sa 50 talampakan mula sa pinakamalapit na riles."},"ar":{"q":"في Nevada، إلى أيّ قرب من أقرب قضيب لسكة الحديد يمكنك أن تركن سيارتك؟","o":["ليس أقرب من 10 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 25 قدمًا","ليس أقرب من 50 قدمًا"],"h1":"هي أكبر هذه المسافات.","h2":"في Nevada لا يجوز لك أن تركن سيارتك على بُعد أقل من 50 قدمًا من أقرب قضيب لسكة الحديد.","p":"صحيح. اركن على بُعد 50 قدمًا على الأقل من أقرب قضيب."},"ref":{"doc":"NV","page":50}},{"id":"nv-032","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, how long is a first driver license valid for a person under 65?","o":["Four years","Eight years","Ten years","Twelve years"],"h1":"Drivers 65 and older get half this time.","h2":"In Nevada a first driver license for a person under 65 is valid for eight years and expires on the driver's birthday.","p":"Right. A first Nevada license lasts eight years if you are under 65."},"es":{"q":"En Nevada, ¿por cuánto tiempo es válida una primera licencia de conducir para una persona menor de 65 años?","o":["Cuatro años","Ocho años","Diez años","Doce años"],"h1":"Los conductores de 65 años o más reciben la mitad de este tiempo.","h2":"En Nevada una primera licencia de conducir para una persona menor de 65 años es válida por ocho años y vence el día del cumpleaños del conductor.","p":"Correcto. Una primera licencia de Nevada dura ocho años si usted tiene menos de 65."},"zh":{"q":"在 Nevada，65 岁以下的人第一次拿到的驾照有效期是多久？","o":["四年","八年","十年","十二年"],"h1":"65 岁及以上的司机只有这个时间的一半。","h2":"在 Nevada，65 岁以下的人第一次拿到的驾照有效期是八年，在司机生日那天到期。","p":"对。如果你不到 65 岁，第一张 Nevada 驾照有效八年。"},"vi":{"q":"Ở Nevada, bằng lái xe đầu tiên của người dưới 65 tuổi có giá trị trong bao lâu?","o":["Bốn năm","Tám năm","Mười năm","Mười hai năm"],"h1":"Người lái xe từ 65 tuổi trở lên được một nửa thời gian này.","h2":"Ở Nevada, bằng lái xe đầu tiên của người dưới 65 tuổi có giá trị tám năm và hết hạn vào ngày sinh nhật của người lái xe.","p":"Đúng. Bằng lái đầu tiên ở Nevada có giá trị tám năm nếu bạn dưới 65 tuổi."},"tl":{"q":"Sa Nevada, gaano katagal may bisa ang unang driver license ng taong wala pang 65 taong gulang?","o":["Apat na taon","Walong taon","Sampung taon","Labindalawang taon"],"h1":"Kalahati lang ng panahong ito ang nakukuha ng mga drayber na 65 pataas.","h2":"Sa Nevada, ang unang driver license ng taong wala pang 65 ay may bisa nang walong taon at mag-e-expire sa kaarawan ng drayber.","p":"Tama. Walong taon ang bisa ng unang Nevada license kung wala ka pang 65."},"ar":{"q":"في Nevada، ما مدة صلاحية أول رخصة قيادة لشخص عمره أقل من 65 سنة؟","o":["أربع سنوات","ثماني سنوات","عشر سنوات","اثنتا عشرة سنة"],"h1":"السائقون في عمر 65 فما فوق يحصلون على نصف هذه المدة.","h2":"في Nevada تكون أول رخصة قيادة لشخص عمره أقل من 65 سنة صالحة لمدة ثماني سنوات، وتنتهي في يوم ميلاد السائق.","p":"صحيح. أول رخصة في Nevada تدوم ثماني سنوات إذا كان عمرك أقل من 65 سنة."},"ref":{"doc":"NV","page":6}},{"id":"nv-033","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, you refuse an officer's blood, breath, or urine test for the first time. How long can you not get a license?","o":["185 days","One year","90 days","Three years"],"h1":"It is longer than six months. Three years is for a repeat refusal.","h2":"In Nevada, if you refuse the blood, breath, or urine test the first time, your license is revoked and you cannot get one for one year.","p":"Right. A first refusal costs you your license for one year."},"es":{"q":"En Nevada, usted se niega por primera vez a la prueba de sangre, aliento u orina que pide un oficial. ¿Por cuánto tiempo no puede obtener una licencia?","o":["185 días","Un año","90 días","Tres años"],"h1":"Es más de seis meses. Tres años es para quien se niega otra vez.","h2":"En Nevada, si usted se niega por primera vez a la prueba de sangre, aliento u orina, le revocan la licencia y no puede obtener una por un año.","p":"Correcto. La primera negativa le quita la licencia por un año."},"ref":{"doc":"NV","page":79}},{"id":"nv-034","scope":"NV","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nevada, how many demerit points does a conviction for reckless driving add to your record?","o":["4 points","6 points","2 points","8 points"],"h1":"It is the most points on the list of common violations.","h2":"In Nevada, reckless driving adds 8 demerit points to your driving record.","p":"Right. Reckless driving is 8 points."},"es":{"q":"En Nevada, ¿cuántos puntos de demérito agrega a su historial una condena por manejo imprudente (reckless driving)?","o":["4 puntos","6 puntos","2 puntos","8 puntos"],"h1":"Es la mayor cantidad de puntos en la lista de infracciones comunes.","h2":"En Nevada, el manejo imprudente agrega 8 puntos de demérito a su historial de manejo.","p":"Correcto. El manejo imprudente son 8 puntos."},"ref":{"doc":"NV","page":78}},{"id":"nv-035","scope":"NV","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nevada, what is the minimum liability insurance for damage to other people's property in one crash?","o":["$20,000","$10,000","$25,000","$50,000"],"h1":"It is less than the amount for injury to one person.","h2":"In Nevada, your liability insurance must cover at least $20,000 for damage to other people's property in one crash.","p":"Right. Property damage coverage must be at least $20,000."},"es":{"q":"En Nevada, ¿cuál es el seguro mínimo de responsabilidad civil por daños a la propiedad de otras personas en un choque?","o":["$20,000","$10,000","$25,000","$50,000"],"h1":"Es menos que la cantidad por lesiones a una persona.","h2":"En Nevada, su seguro de responsabilidad civil debe cubrir por lo menos $20,000 por daños a la propiedad de otras personas en un choque.","p":"Correcto. La cobertura por daños a la propiedad debe ser de por lo menos $20,000."},"ref":{"doc":"NV","page":75}},{"id":"nv-036","scope":"NV","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nevada, you move to a new address. How soon must you tell the DMV?","o":["Within 10 days","Within 60 days","Within 30 days","Within 1 year"],"h1":"It is about one month.","h2":"In Nevada, you must tell the DMV about a new address or a new name within 30 days.","p":"Right. Tell the DMV within 30 days."},"es":{"q":"En Nevada, usted se muda a una nueva dirección. ¿En cuánto tiempo debe avisar al DMV?","o":["Dentro de 10 días","Dentro de 60 días","Dentro de 30 días","Dentro de 1 año"],"h1":"Es más o menos un mes.","h2":"En Nevada, usted debe avisar al DMV de una nueva dirección o un nuevo nombre dentro de 30 días.","p":"Correcto. Avise al DMV dentro de 30 días."},"ref":{"doc":"NV","page":19}},{"id":"nv-037","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, you are under 18. How long must you hold an instruction permit before you apply for a driver license?","o":["At least 3 months","At least 6 months","At least 9 months","At least 12 months"],"h1":"It is half a year.","h2":"In Nevada, a driver under 18 must hold an instruction permit for at least 6 months before applying for a driver license.","p":"Right. Hold the permit at least 6 months first."},"es":{"q":"En Nevada, usted es menor de 18 años. ¿Por cuánto tiempo debe tener el permiso de instrucción antes de solicitar la licencia de manejar?","o":["Por lo menos 3 meses","Por lo menos 6 meses","Por lo menos 9 meses","Por lo menos 12 meses"],"h1":"Es medio año.","h2":"En Nevada, un conductor menor de 18 años debe tener el permiso de instrucción por lo menos 6 meses antes de solicitar la licencia de manejar.","p":"Correcto. Primero tenga el permiso por lo menos 6 meses."},"ref":{"doc":"NV","page":15}},{"id":"nv-038","scope":"NV","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nevada, how must a child under age 2 ride in a car?","o":["In a booster seat in the front seat","Facing forward in the front seat","Facing forward in the back seat","In a rear-facing seat in the back seat"],"h1":"The baby faces the back of the car, away from the front.","h2":"In Nevada, a child under age 2 must ride in a rear-facing child seat in the back seat.","p":"Right. Under 2: rear-facing, in the back seat."},"es":{"q":"En Nevada, ¿cómo debe viajar en el carro un niño menor de 2 años?","o":["En un asiento elevado (booster) en el asiento delantero","Mirando hacia adelante en el asiento delantero","Mirando hacia adelante en el asiento trasero","En un asiento orientado hacia atrás en el asiento trasero"],"h1":"El bebé mira hacia la parte de atrás del carro, no hacia el frente.","h2":"En Nevada, un niño menor de 2 años debe viajar en un asiento de seguridad orientado hacia atrás en el asiento trasero.","p":"Correcto. Menores de 2 años: mirando hacia atrás, en el asiento trasero."},"ref":{"doc":"NV","page":25}},{"id":"nv-039","scope":"NV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nevada, you may not leave a child aged 7 or younger alone in a car when it puts the child at risk, unless someone watches the child. How old must that person be?","o":["At least 12","At least 10","At least 16","At least 18"],"h1":"The person can be younger than a teen driver.","h2":"In Nevada, a child aged 7 or younger may not be left in a car when it is risky unless a person at least 12 years old is watching and can see the child.","p":"Right. The person watching must be at least 12."},"es":{"q":"En Nevada, usted no puede dejar solo en un carro a un niño de 7 años o menos cuando eso lo pone en riesgo, a menos que alguien lo cuide. ¿Qué edad debe tener esa persona?","o":["Por lo menos 12 años","Por lo menos 10 años","Por lo menos 16 años","Por lo menos 18 años"],"h1":"La persona puede ser menor que un conductor adolescente.","h2":"En Nevada, no se puede dejar en un carro a un niño de 7 años o menos cuando es peligroso, a menos que lo cuide y lo pueda ver una persona de por lo menos 12 años.","p":"Correcto. La persona que lo cuida debe tener por lo menos 12 años."},"ref":{"doc":"NV","page":25}},{"id":"nv-040","scope":"NV","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Nevada, you use a center turn lane to make a left turn. What is the farthest you may drive in it before you turn?","o":["100 feet","300 feet","200 feet","500 feet"],"h1":"It is about 20 car lengths.","h2":"In Nevada, you may not drive more than 200 feet in a center turn lane before you make your left turn.","p":"Right. No more than 200 feet in the center turn lane before turning."},"es":{"q":"En Nevada, usted usa un carril central de vuelta para dar vuelta a la izquierda. ¿Cuál es la distancia máxima que puede manejar en él antes de dar la vuelta?","o":["100 pies","300 pies","200 pies","500 pies"],"h1":"Son más o menos 20 largos de carro.","h2":"En Nevada, usted no puede manejar más de 200 pies en un carril central de vuelta antes de dar vuelta a la izquierda.","p":"Correcto. No más de 200 pies en el carril central antes de dar la vuelta."},"ref":{"doc":"NV","page":32}},{"id":"nv-041","scope":"NV","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Nevada, what is the speed limit in a school zone?","o":["10 or 20 mph","15 or 25 mph","20 or 30 mph","25 or 35 mph"],"h1":"The higher number is the usual limit in business and residential areas.","h2":"In Nevada, the speed limit in a school zone is either 15 mph or 25 mph.","p":"Right. School zones in Nevada are 15 or 25 mph."},"es":{"q":"En Nevada, ¿cuál es el límite de velocidad en una zona escolar?","o":["10 o 20 mph","15 o 25 mph","20 o 30 mph","25 o 35 mph"],"h1":"El número más alto es el límite usual en zonas comerciales y residenciales.","h2":"En Nevada, el límite de velocidad en una zona escolar es de 15 mph o de 25 mph.","p":"Correcto. Las zonas escolares en Nevada son de 15 o 25 mph."},"ref":{"doc":"NV","page":33}},{"id":"nv-042","scope":"NV","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Nevada, a school crossing guard is in the crosswalk in front of you. When may you go?","o":["As soon as the children reach the curb","When the guard turns to face the sidewalk","Right away, if you drive slowly around the guard","When the guard is all the way out of the crosswalk"],"h1":"Think about where the guard is standing, not the children.","h2":"In Nevada, you must wait until the school crossing guard is completely out of the crosswalk before you go.","p":"Right. Wait until the guard has left the crosswalk."},"es":{"q":"En Nevada, un guardia de cruce escolar está en el cruce de peatones frente a usted. ¿Cuándo puede seguir?","o":["En cuanto los niños lleguen a la banqueta","Cuando el guardia se voltee hacia la acera","Enseguida, si maneja despacio alrededor del guardia","Cuando el guardia haya salido por completo del cruce de peatones"],"h1":"Piense en dónde está el guardia, no los niños.","h2":"En Nevada, usted debe esperar a que el guardia de cruce escolar salga por completo del cruce de peatones antes de seguir.","p":"Correcto. Espere a que el guardia salga del cruce de peatones."},"ref":{"doc":"NV","page":33}},{"id":"nv-043","scope":"NV","cat":"signals","sign":null,"c":0,"en":{"q":"In Nevada, you are on an open highway. How far ahead should you start signaling before a turn?","o":["At least 300 feet (about 30 car lengths)","At least 100 feet (about 10 car lengths)","At least 50 feet (about 5 car lengths)","At least 1,000 feet (about 100 car lengths)"],"h1":"On a city street it is 100 feet. On an open highway it is three times as far.","h2":"In Nevada, on an open highway you should signal at least 300 feet, about 30 car lengths, before you turn.","p":"Right. Signal at least 300 feet ahead on an open highway."},"es":{"q":"En Nevada, usted va por una carretera abierta. ¿Con cuánta anticipación debe poner la señal antes de dar vuelta?","o":["Por lo menos 300 pies (unos 30 largos de carro)","Por lo menos 100 pies (unos 10 largos de carro)","Por lo menos 50 pies (unos 5 largos de carro)","Por lo menos 1,000 pies (unos 100 largos de carro)"],"h1":"En una calle de la ciudad son 100 pies. En una carretera abierta es tres veces más.","h2":"En Nevada, en una carretera abierta usted debe poner la señal por lo menos 300 pies, unos 30 largos de carro, antes de dar vuelta.","p":"Correcto. Ponga la señal por lo menos 300 pies antes en una carretera abierta."},"ref":{"doc":"NV","page":45}},{"id":"nv-044","scope":"NV","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Nevada, you may not make a U-turn if a curve, hill, rain, or fog blocks your clear view for a certain distance in each direction. What is that distance?","o":["50 feet","100 feet","200 feet","1,000 feet"],"h1":"It is about 20 car lengths.","h2":"In Nevada, you may not make a U-turn where you cannot see clearly for 200 feet in each direction.","p":"Right. You need a clear view of 200 feet each way for a U-turn."},"es":{"q":"En Nevada, no puede dar una vuelta en U si una curva, una colina, la lluvia o la neblina no le deja ver con claridad cierta distancia en cada dirección. ¿Qué distancia es?","o":["50 pies","100 pies","200 pies","1,000 pies"],"h1":"Son más o menos 20 largos de carro.","h2":"En Nevada, usted no puede dar una vuelta en U donde no puede ver con claridad 200 pies en cada dirección.","p":"Correcto. Para una vuelta en U necesita ver bien 200 pies en cada dirección."},"ref":{"doc":"NV","page":46}},{"id":"nv-045","scope":"NV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nevada, on the same side of the street, how close to the driveway entrance of a fire station may you park?","o":["No closer than 10 feet","No closer than 20 feet","No closer than 50 feet","No closer than 100 feet"],"h1":"It is the same as the distance from a crosswalk.","h2":"In Nevada, you may not park within 20 feet of the driveway entrance to a fire station.","p":"Right. Stay at least 20 feet from a fire station driveway."},"es":{"q":"En Nevada, en el mismo lado de la calle, ¿qué tan cerca de la entrada de vehículos de una estación de bomberos puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 20 pies","No más cerca de 50 pies","No más cerca de 100 pies"],"h1":"Es la misma distancia que de un cruce de peatones.","h2":"En Nevada, usted no puede estacionarse a menos de 20 pies de la entrada de vehículos de una estación de bomberos.","p":"Correcto. Quédese por lo menos a 20 pies de la entrada de una estación de bomberos."},"ref":{"doc":"NV","page":50}},{"id":"nv-046","scope":"NV","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nevada, what is the lowest fine for parking in a disabled parking space without the right placard or license plate?","o":["$50","$100","$150","$250"],"h1":"It is the highest amount here.","h2":"In Nevada, the minimum fine for parking in a space for people with disabilities without the right placard or plate is $250.","p":"Right. The fine starts at $250."},"es":{"q":"En Nevada, ¿cuál es la multa mínima por estacionarse en un espacio para personas con discapacidad sin el permiso (placard) o la placa correspondiente?","o":["$50","$100","$150","$250"],"h1":"Es la cantidad más alta de estas.","h2":"En Nevada, la multa mínima por estacionarse en un espacio para personas con discapacidad sin el permiso o la placa correspondiente es de $250.","p":"Correcto. La multa empieza en $250."},"ref":{"doc":"NV","page":50}},{"id":"nv-047","scope":"NV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nevada, when may you use studded snow tires?","o":["From October 1 through April 30","From November 1 through March 31","From December 1 through the end of February","Any time of year"],"h1":"The season starts in the fall and ends in the spring.","h2":"In Nevada, studded snow tires may be used only from October 1 through April 30.","p":"Right. Studded tires are allowed October 1 through April 30."},"es":{"q":"En Nevada, ¿cuándo puede usar llantas de nieve con clavos?","o":["Del 1 de octubre al 30 de abril","Del 1 de noviembre al 31 de marzo","Del 1 de diciembre hasta el final de febrero","En cualquier época del año"],"h1":"La temporada empieza en el otoño y termina en la primavera.","h2":"En Nevada, las llantas de nieve con clavos solo se pueden usar del 1 de octubre al 30 de abril.","p":"Correcto. Las llantas con clavos se permiten del 1 de octubre al 30 de abril."},"ref":{"doc":"NV","page":57}},{"id":"nv-048","scope":"NV","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Nevada, how many people must be in a car to use an HOV (carpool) lane?","o":["Only the driver","At least 3","At least 2","At least 4"],"h1":"The driver and one passenger are enough.","h2":"In Nevada, a car needs at least 2 people in it to use an HOV (carpool) lane.","p":"Right. Two or more people may use the carpool lane."},"es":{"q":"En Nevada, ¿cuántas personas deben ir en un carro para usar un carril HOV (de vehículos compartidos)?","o":["Solo el conductor","Por lo menos 3","Por lo menos 2","Por lo menos 4"],"h1":"Basta con el conductor y un pasajero.","h2":"En Nevada, un carro necesita por lo menos 2 personas para usar un carril HOV (de vehículos compartidos).","p":"Correcto. Dos o más personas pueden usar el carril de vehículos compartidos."},"ref":{"doc":"NV","page":39}},{"id":"nv-049","scope":"NV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nevada, who may not ride in the open bed of a pickup truck on a paved highway, except in a parade or for farm or ranch work?","o":["Only children under 6","Anyone under 18","Only children under 12","Anyone over 65"],"h1":"It is anyone who is not yet an adult.","h2":"In Nevada, no one under 18 may ride in the bed of a pickup truck on a paved highway, except in an approved parade or for farm or ranch work.","p":"Right. No one under 18 may ride in a pickup bed on a paved highway."},"es":{"q":"En Nevada, ¿quién no puede viajar en la caja abierta de una camioneta pickup en una carretera pavimentada, salvo en un desfile o en trabajo de granja o rancho?","o":["Solo los niños menores de 6 años","Cualquier persona menor de 18 años","Solo los niños menores de 12 años","Cualquier persona mayor de 65 años"],"h1":"Es cualquier persona que todavía no es adulta.","h2":"En Nevada, ninguna persona menor de 18 años puede viajar en la caja de una camioneta pickup en una carretera pavimentada, salvo en un desfile autorizado o en trabajo de granja o rancho.","p":"Correcto. Nadie menor de 18 años puede viajar en la caja de una pickup en una carretera pavimentada."},"ref":{"doc":"NV","page":66}},{"id":"nv-050","scope":"NV","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nevada, what can you dial on a cell phone to report a driver you think is drunk?","o":["*311","*411","*368 (*DMV)","*647 (*NHP)"],"h1":"The letters stand for the Nevada Highway Patrol.","h2":"In Nevada, you can report a suspected drunk driver or a highway emergency by dialing *NHP, which is *647.","p":"Right. Dial *NHP (*647) to report a drunk driver."},"es":{"q":"En Nevada, ¿qué número puede marcar en un teléfono celular para reportar a un conductor que usted cree que está borracho?","o":["*311","*411","*368 (*DMV)","*647 (*NHP)"],"h1":"Las letras son de la Patrulla de Carreteras de Nevada (Nevada Highway Patrol).","h2":"En Nevada, usted puede reportar a un conductor que parece borracho o una emergencia en la carretera marcando *NHP, que es *647.","p":"Correcto. Marque *NHP (*647) para reportar a un conductor borracho."},"ref":{"doc":"NV","page":81}},{"id":"nv-051","scope":"NV","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nevada, which rule applies to a rider with a motorcycle instruction permit?","o":["Ride only in daylight hours","Ride at night only with a supervisor","Carry one passenger who is at least 21","Ride on freeways only with a supervisor"],"h1":"Permit riders may not carry passengers or use freeways.","h2":"In Nevada, a rider with a motorcycle instruction permit may ride only in daylight, with no passengers and not on freeways.","p":"Right. Motorcycle permit riders ride in daylight only."},"es":{"q":"En Nevada, ¿qué regla se aplica a quien tiene un permiso de instrucción de motocicleta?","o":["Manejar solo durante las horas de luz del día","Manejar de noche solo con un supervisor","Llevar un pasajero de por lo menos 21 años","Manejar en autopistas solo con un supervisor"],"h1":"Con el permiso no se pueden llevar pasajeros ni usar autopistas.","h2":"En Nevada, quien tiene un permiso de instrucción de motocicleta solo puede manejar de día, sin pasajeros y no en autopistas.","p":"Correcto. Con el permiso de motocicleta se maneja solo de día."},"ref":{"doc":"NV","page":18}},{"id":"ny-001","scope":"NY","cat":"licensing","sign":null,"c":2,"en":{"q":"In New York, what is the youngest age to apply for a learner permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is the same age many states use for a first license.","h2":"You must be at least 16 to apply for a New York learner permit.","p":"Right. In New York the permit starts at 16."},"es":{"q":"En Nueva York, ¿cuál es la edad mínima para solicitar un permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es la misma edad que muchos estados usan para la primera licencia.","h2":"Usted debe tener por lo menos 16 años para solicitar un permiso de aprendiz en Nueva York.","p":"Correcto. En Nueva York el permiso empieza a los 16."},"zh":{"q":"在 New York，最小几岁可以申请学习驾照（learner permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"很多州第一次拿驾照也是这个年龄。","h2":"你必须至少 16 岁才能申请 New York 的学习驾照。","p":"对。在 New York，学习驾照从 16 岁开始。"},"vi":{"q":"Ở New York, tuổi nhỏ nhất để nộp đơn xin giấy phép tập lái (learner permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đây là cùng độ tuổi mà nhiều tiểu bang dùng cho bằng lái đầu tiên.","h2":"Bạn phải ít nhất 16 tuổi để nộp đơn xin giấy phép tập lái ở New York.","p":"Đúng. Ở New York, giấy phép tập lái bắt đầu từ 16 tuổi."},"tl":{"q":"Sa New York, ano ang pinakabatang edad para mag-apply ng learner permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Ito ang parehong edad na ginagamit ng maraming estado para sa unang lisensya.","h2":"Dapat ay hindi bababa sa 16 taong gulang ka para mag-apply ng learner permit sa New York.","p":"Tama. Sa New York, nagsisimula ang permit sa edad na 16."},"ar":{"q":"في New York، ما أصغر عمر للتقدّم بطلب تصريح تعلّم القيادة (learner permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هو نفس العمر الذي تستخدمه ولايات كثيرة لأول رخصة قيادة.","h2":"يجب أن يكون عمرك 16 سنة على الأقل لتتقدّم بطلب تصريح تعلّم القيادة في New York.","p":"صحيح. في New York يبدأ التصريح في عمر 16 سنة."},"ref":{"doc":"NY","page":11}},{"id":"ny-002","scope":"NY","cat":"licensing","sign":null,"c":0,"en":{"q":"In New York, how many of the 20 questions on the written permit test must you answer correctly?","o":["At least 14","At least 10","At least 16","At least 18"],"h1":"You may miss up to six questions.","h2":"To pass the New York written permit test you must answer at least 14 of the 20 questions correctly.","p":"Right. You need at least 14 out of 20."},"es":{"q":"En Nueva York, ¿cuántas de las 20 preguntas del examen escrito del permiso debe contestar bien?","o":["Por lo menos 14","Por lo menos 10","Por lo menos 16","Por lo menos 18"],"h1":"Puede equivocarse hasta en seis preguntas.","h2":"Para aprobar el examen escrito del permiso en Nueva York debe contestar bien por lo menos 14 de las 20 preguntas.","p":"Correcto. Necesita por lo menos 14 de 20."},"zh":{"q":"在 New York，学习驾照笔试的 20 道题里，你必须答对多少道？","o":["至少 14 道","至少 10 道","至少 16 道","至少 18 道"],"h1":"你最多可以答错六道。","h2":"要通过 New York 的学习驾照笔试，你必须答对 20 道题里的至少 14 道。","p":"对。20 道里你至少要答对 14 道。"},"vi":{"q":"Ở New York, trong 20 câu hỏi của bài thi viết để lấy giấy phép tập lái, bạn phải trả lời đúng bao nhiêu câu?","o":["Ít nhất 14 câu","Ít nhất 10 câu","Ít nhất 16 câu","Ít nhất 18 câu"],"h1":"Bạn có thể sai tối đa sáu câu.","h2":"Để đậu bài thi viết lấy giấy phép tập lái ở New York, bạn phải trả lời đúng ít nhất 14 trong 20 câu hỏi.","p":"Đúng. Bạn cần ít nhất 14 trên 20 câu."},"tl":{"q":"Sa New York, ilan sa 20 tanong sa written permit test ang dapat mong masagot nang tama?","o":["Hindi bababa sa 14","Hindi bababa sa 10","Hindi bababa sa 16","Hindi bababa sa 18"],"h1":"Puwede kang magkamali sa hanggang anim na tanong.","h2":"Para pumasa sa written permit test ng New York, dapat mong masagot nang tama ang hindi bababa sa 14 sa 20 tanong.","p":"Tama. Kailangan mo ng hindi bababa sa 14 sa 20."},"ar":{"q":"في New York، كم سؤالًا من أسئلة الاختبار الكتابي العشرين للتصريح يجب أن تجيب عنه إجابة صحيحة؟","o":["14 على الأقل","10 على الأقل","16 على الأقل","18 على الأقل"],"h1":"يمكنك أن تخطئ في ستة أسئلة كحدّ أقصى.","h2":"لتنجح في الاختبار الكتابي للتصريح في New York يجب أن تجيب إجابة صحيحة عن 14 سؤالًا على الأقل من 20.","p":"صحيح. تحتاج إلى 14 من 20 على الأقل."},"ref":{"doc":"NY","page":10}},{"id":"ny-003","scope":"NY","cat":"licensing","sign":null,"c":3,"en":{"q":"In New York, what else must you get right on the written permit test, besides 14 of 20 questions?","o":["All four road sign questions","The first five questions","Every question about alcohol","At least two of the four road sign questions"],"h1":"It is half of the sign questions.","h2":"On the New York written permit test you must also answer at least two of the four road sign questions correctly, or you fail.","p":"Right. You need two of the four sign questions."},"es":{"q":"En Nueva York, además de 14 de 20 preguntas, ¿qué más debe contestar bien en el examen escrito del permiso?","o":["Las cuatro preguntas sobre señales de tránsito","Las primeras cinco preguntas","Todas las preguntas sobre alcohol","Por lo menos dos de las cuatro preguntas sobre señales de tránsito"],"h1":"Es la mitad de las preguntas sobre señales.","h2":"En el examen escrito del permiso de Nueva York también debe contestar bien por lo menos dos de las cuatro preguntas sobre señales de tránsito, o no aprueba.","p":"Correcto. Necesita dos de las cuatro preguntas sobre señales."},"zh":{"q":"在 New York，学习驾照笔试除了要答对 20 道里的 14 道，还必须答对什么？","o":["全部四道交通标志题","前五道题","每一道关于酒精的题","四道交通标志题里至少两道"],"h1":"它是交通标志题的一半。","h2":"在 New York 的学习驾照笔试中，你还必须答对四道交通标志题里的至少两道，不然就不通过。","p":"对。四道标志题你要答对两道。"},"vi":{"q":"Ở New York, ngoài việc đúng 14 trên 20 câu, bạn còn phải trả lời đúng điều gì khác trong bài thi viết?","o":["Cả bốn câu hỏi về biển báo giao thông","Năm câu hỏi đầu tiên","Mọi câu hỏi về rượu bia","Ít nhất hai trong bốn câu hỏi về biển báo giao thông"],"h1":"Đó là một nửa số câu hỏi về biển báo.","h2":"Trong bài thi viết lấy giấy phép tập lái ở New York, bạn cũng phải trả lời đúng ít nhất hai trong bốn câu hỏi về biển báo giao thông, nếu không bạn sẽ rớt.","p":"Đúng. Bạn cần đúng hai trong bốn câu hỏi về biển báo."},"tl":{"q":"Sa New York, bukod sa 14 sa 20 tanong, ano pa ang dapat mong masagot nang tama sa written permit test?","o":["Lahat ng apat na tanong tungkol sa road sign","Ang unang limang tanong","Bawat tanong tungkol sa alak","Hindi bababa sa dalawa sa apat na tanong tungkol sa road sign"],"h1":"Kalahati ito ng mga tanong tungkol sa sign.","h2":"Sa written permit test ng New York, dapat mo ring masagot nang tama ang hindi bababa sa dalawa sa apat na tanong tungkol sa road sign, kung hindi ay babagsak ka.","p":"Tama. Kailangan mo ng dalawa sa apat na tanong tungkol sa sign."},"ar":{"q":"في New York، ما الذي يجب أن تجيب عنه إجابة صحيحة أيضًا في الاختبار الكتابي للتصريح، إلى جانب 14 من 20 سؤالًا؟","o":["كل أسئلة إشارات الطريق الأربعة","الأسئلة الخمسة الأولى","كل سؤال عن الكحول","سؤالان على الأقل من أسئلة إشارات الطريق الأربعة"],"h1":"هي نصف أسئلة الإشارات.","h2":"في الاختبار الكتابي للتصريح في New York يجب أيضًا أن تجيب إجابة صحيحة عن سؤالين على الأقل من أسئلة إشارات الطريق الأربعة، وإلا ترسب.","p":"صحيح. تحتاج إلى سؤالين من أسئلة الإشارات الأربعة."},"ref":{"doc":"NY","page":10}},{"id":"ny-004","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, can you take the Class D written permit test in Spanish?","o":["No, only in English","Yes, it is offered in Spanish and many other languages","Only in New York City","Only with a paid interpreter"],"h1":"The DMV offers the test in about 20 languages.","h2":"Yes, the New York DMV offers the Class D written permit test in Spanish and many other languages.","p":"Right. You can take it in Spanish."},"es":{"q":"En Nueva York, ¿puede tomar en español el examen escrito del permiso clase D?","o":["No, solo en inglés","Sí, se ofrece en español y en muchos otros idiomas","Solo en la ciudad de Nueva York","Solo con un intérprete pagado"],"h1":"El DMV ofrece el examen en unos 20 idiomas.","h2":"Sí, el DMV de Nueva York ofrece el examen escrito del permiso clase D en español y en muchos otros idiomas.","p":"Correcto. Puede tomarlo en español."},"zh":{"q":"在 New York，Class D 学习驾照笔试可以用西班牙语考吗？","o":["不可以，只能用英语","可以，有西班牙语和很多其他语言","只在 New York City 可以","只有付钱请翻译才可以"],"h1":"DMV 提供大约 20 种语言的考试。","h2":"可以，New York DMV 提供西班牙语和很多其他语言的 Class D 学习驾照笔试。","p":"对。你可以用西班牙语考。"},"vi":{"q":"Ở New York, bạn có thể làm bài thi viết lấy giấy phép Class D bằng tiếng Tây Ban Nha không?","o":["Không, chỉ bằng tiếng Anh","Có, bài thi có bằng tiếng Tây Ban Nha và nhiều ngôn ngữ khác","Chỉ ở New York City","Chỉ khi có thông dịch viên trả tiền"],"h1":"DMV có bài thi bằng khoảng 20 ngôn ngữ.","h2":"Có, DMV New York có bài thi viết lấy giấy phép Class D bằng tiếng Tây Ban Nha và nhiều ngôn ngữ khác.","p":"Đúng. Bạn có thể thi bằng tiếng Tây Ban Nha."},"tl":{"q":"Sa New York, puwede mo bang kunin ang Class D written permit test sa Spanish?","o":["Hindi, sa English lang","Oo, inaalok ito sa Spanish at sa marami pang ibang wika","Sa New York City lang","Kung may bayad na interpreter lang"],"h1":"Inaalok ng DMV ang test sa mga 20 wika.","h2":"Oo, inaalok ng New York DMV ang Class D written permit test sa Spanish at sa marami pang ibang wika.","p":"Tama. Puwede mo itong kunin sa Spanish."},"ar":{"q":"في New York، هل يمكنك أداء الاختبار الكتابي لتصريح Class D باللغة الإسبانية؟","o":["لا، بالإنجليزية فقط","نعم، هو متاح بالإسبانية وبلغات أخرى كثيرة","في New York City فقط","مع مترجم مدفوع الأجر فقط"],"h1":"تقدّم إدارة DMV الاختبار بحوالي 20 لغة.","h2":"نعم، تقدّم إدارة DMV في New York الاختبار الكتابي لتصريح Class D بالإسبانية وبلغات أخرى كثيرة.","p":"صحيح. يمكنك أداؤه بالإسبانية."},"ref":{"doc":"NY","page":10}},{"id":"ny-005","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, how many hours of supervised driving must a teen complete before the road test?","o":["30 hours","50 hours","40 hours","60 hours"],"h1":"It is half of one hundred.","h2":"A New York teen must complete at least 50 hours of supervised practice driving before the road test.","p":"Right. New York asks for 50 supervised hours."},"es":{"q":"En Nueva York, ¿cuántas horas de manejo supervisado debe completar un joven antes del examen de manejo?","o":["30 horas","50 horas","40 horas","60 horas"],"h1":"Es la mitad de cien.","h2":"En Nueva York, un joven debe completar por lo menos 50 horas de práctica de manejo supervisada antes del examen de manejo.","p":"Correcto. Nueva York pide 50 horas supervisadas."},"zh":{"q":"在 New York，青少年路考前必须完成多少小时有人监督的驾驶？","o":["30 小时","50 小时","40 小时","60 小时"],"h1":"它是一百的一半。","h2":"New York 的青少年路考前必须完成至少 50 小时有人监督的驾驶练习。","p":"对。New York 要求 50 小时有人监督的练习。"},"vi":{"q":"Ở New York, thiếu niên phải lái xe có người giám sát bao nhiêu giờ trước khi thi lái trên đường (road test)?","o":["30 giờ","50 giờ","40 giờ","60 giờ"],"h1":"Đó là một nửa của một trăm.","h2":"Thiếu niên ở New York phải tập lái có người giám sát ít nhất 50 giờ trước khi thi lái trên đường.","p":"Đúng. New York yêu cầu 50 giờ có người giám sát."},"tl":{"q":"Sa New York, ilang oras ng supervised driving (pagmamaneho na may kasamang nagbabantay) ang dapat tapusin ng isang teen bago ang road test?","o":["30 oras","50 oras","40 oras","60 oras"],"h1":"Kalahati ito ng isang daan.","h2":"Ang isang teen sa New York ay dapat makatapos ng hindi bababa sa 50 oras ng supervised practice driving bago ang road test.","p":"Tama. Humihingi ang New York ng 50 supervised na oras."},"ar":{"q":"في New York، كم ساعة من القيادة تحت الإشراف يجب أن يكملها المراهق قبل اختبار القيادة على الطريق (road test)؟","o":["30 ساعة","50 ساعة","40 ساعة","60 ساعة"],"h1":"هي نصف المئة.","h2":"يجب أن يكمل المراهق في New York ما لا يقل عن 50 ساعة من التدريب على القيادة تحت الإشراف قبل اختبار القيادة على الطريق.","p":"صحيح. تطلب New York خمسين ساعة تحت الإشراف."},"ref":{"doc":"NY","page":13}},{"id":"ny-006","scope":"NY","cat":"licensing","sign":null,"c":3,"en":{"q":"In New York, how many of the 50 supervised hours must be driven after sunset?","o":["5 hours","10 hours","20 hours","15 hours"],"h1":"It is more than 10 and less than 20.","h2":"At least 15 of the 50 supervised hours in New York must be driven after sunset.","p":"Right. Fifteen of the hours are after sunset."},"es":{"q":"En Nueva York, ¿cuántas de las 50 horas supervisadas deben ser después de la puesta del sol?","o":["5 horas","10 horas","20 horas","15 horas"],"h1":"Son más de 10 y menos de 20.","h2":"En Nueva York, por lo menos 15 de las 50 horas supervisadas deben ser después de la puesta del sol.","p":"Correcto. Quince de las horas son después de la puesta del sol."},"zh":{"q":"在 New York，50 小时有人监督的驾驶里，有多少小时必须在日落以后开？","o":["5 小时","10 小时","20 小时","15 小时"],"h1":"它比 10 多，比 20 少。","h2":"在 New York，50 小时有人监督的驾驶里，至少 15 小时必须在日落以后开。","p":"对。其中十五小时在日落以后。"},"vi":{"q":"Ở New York, trong 50 giờ lái có người giám sát, phải có bao nhiêu giờ lái sau khi mặt trời lặn?","o":["5 giờ","10 giờ","20 giờ","15 giờ"],"h1":"Nhiều hơn 10 và ít hơn 20.","h2":"Ở New York, ít nhất 15 trong 50 giờ lái có người giám sát phải là sau khi mặt trời lặn.","p":"Đúng. Mười lăm giờ là sau khi mặt trời lặn."},"tl":{"q":"Sa New York, ilan sa 50 supervised na oras ang dapat imaneho pagkatapos lumubog ang araw?","o":["5 oras","10 oras","20 oras","15 oras"],"h1":"Higit ito sa 10 at kulang sa 20.","h2":"Sa New York, hindi bababa sa 15 sa 50 supervised na oras ang dapat imaneho pagkatapos lumubog ang araw.","p":"Tama. Labinlima sa mga oras ay pagkatapos lumubog ang araw."},"ar":{"q":"في New York، كم ساعة من الخمسين ساعة تحت الإشراف يجب أن تكون بعد غروب الشمس؟","o":["5 ساعات","10 ساعات","20 ساعة","15 ساعة"],"h1":"هي أكثر من 10 وأقل من 20.","h2":"في New York يجب أن تكون 15 ساعة على الأقل من الخمسين ساعة تحت الإشراف بعد غروب الشمس.","p":"صحيح. خمس عشرة ساعة منها بعد غروب الشمس."},"ref":{"doc":"NY","page":13}},{"id":"ny-007","scope":"NY","cat":"licensing","sign":null,"c":0,"en":{"q":"In New York, what must a teen bring to every road test to show the supervised hours?","o":["A Certification of Supervised Driving signed by a parent or guardian","A letter from a teacher","A copy of the learner permit test","Nothing, the DMV checks online"],"h1":"It is a DMV form that a parent signs.","h2":"A New York teen must bring a Certification of Supervised Driving, signed by a parent or guardian, each time they take the road test.","p":"Right. Bring the signed certification every time."},"es":{"q":"En Nueva York, ¿qué debe llevar un joven a cada examen de manejo para demostrar las horas supervisadas?","o":["Una Certificación de Manejo Supervisado firmada por un padre, madre o tutor","Una carta de un maestro","Una copia del examen del permiso","Nada, el DMV lo revisa en línea"],"h1":"Es un formulario del DMV que firma un padre.","h2":"En Nueva York, un joven debe llevar una Certificación de Manejo Supervisado, firmada por un padre, madre o tutor, cada vez que toma el examen de manejo.","p":"Correcto. Lleve la certificación firmada cada vez."},"zh":{"q":"在 New York，青少年每次路考必须带什么来证明有人监督的驾驶时间？","o":["一份由父母或监护人签字的有人监督驾驶证明（Certification of Supervised Driving）","一封老师的信","一份学习驾照考试的复印件","什么都不用带，DMV 会在网上查"],"h1":"它是一份父母签字的 DMV 表格。","h2":"New York 的青少年每次路考都必须带一份由父母或监护人签字的有人监督驾驶证明（Certification of Supervised Driving）。","p":"对。每次都要带签好字的证明。"},"vi":{"q":"Ở New York, thiếu niên phải mang gì đến mỗi lần thi lái trên đường để chứng minh số giờ lái có người giám sát?","o":["Giấy Chứng nhận Lái xe có Giám sát (Certification of Supervised Driving) có chữ ký của cha mẹ hoặc người giám hộ","Một lá thư của giáo viên","Một bản sao bài thi giấy phép tập lái","Không cần gì, DMV kiểm tra trên mạng"],"h1":"Đó là một mẫu đơn của DMV mà cha mẹ ký tên.","h2":"Thiếu niên ở New York phải mang Giấy Chứng nhận Lái xe có Giám sát (Certification of Supervised Driving), có chữ ký của cha mẹ hoặc người giám hộ, mỗi lần đi thi lái trên đường.","p":"Đúng. Mỗi lần thi đều mang giấy chứng nhận đã ký."},"tl":{"q":"Sa New York, ano ang dapat dalhin ng isang teen sa bawat road test para ipakita ang supervised na oras?","o":["Isang Certification of Supervised Driving na pinirmahan ng magulang o guardian","Isang sulat mula sa guro","Kopya ng learner permit test","Wala, tinitingnan ng DMV online"],"h1":"Isa itong form ng DMV na pinipirmahan ng magulang.","h2":"Ang isang teen sa New York ay dapat magdala ng Certification of Supervised Driving, na pinirmahan ng magulang o guardian, sa bawat pagkuha ng road test.","p":"Tama. Dalhin ang pinirmahang certification sa bawat pagkakataon."},"ar":{"q":"في New York، ماذا يجب أن يُحضر المراهق إلى كل اختبار قيادة على الطريق ليُثبت ساعات القيادة تحت الإشراف؟","o":["شهادة القيادة تحت الإشراف (Certification of Supervised Driving) موقّعة من أحد الوالدين أو الوصي","رسالة من معلّم","نسخة من اختبار تصريح التعلّم","لا شيء، فإدارة DMV تتحقق عبر الإنترنت"],"h1":"هي استمارة من DMV يوقّعها أحد الوالدين.","h2":"يجب أن يُحضر المراهق في New York شهادة القيادة تحت الإشراف (Certification of Supervised Driving)، موقّعة من أحد الوالدين أو الوصي، في كل مرة يؤدي فيها اختبار القيادة على الطريق.","p":"صحيح. أحضِر الشهادة الموقّعة في كل مرة."},"ref":{"doc":"NY","page":14}},{"id":"ny-008","scope":"NY","cat":"licensing","sign":null,"c":2,"en":{"q":"In New York, how old must the supervising driver of a learner permit holder be?","o":["At least 16","At least 18","At least 21","At least 25"],"h1":"The supervisor must be old enough to drink alcohol legally.","h2":"In New York the supervising driver must be at least 21 and hold a valid license for the type of vehicle being driven.","p":"Right. The supervisor must be 21 or older."},"es":{"q":"En Nueva York, ¿qué edad debe tener el conductor que supervisa a quien tiene permiso de aprendiz?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 21","Por lo menos 25"],"h1":"El supervisor debe tener edad para tomar alcohol legalmente.","h2":"En Nueva York, el conductor supervisor debe tener por lo menos 21 años y una licencia válida para el tipo de vehículo que se maneja.","p":"Correcto. El supervisor debe tener 21 años o más."},"zh":{"q":"在 New York，监督学习驾照持有人的司机必须几岁？","o":["至少 16 岁","至少 18 岁","至少 21 岁","至少 25 岁"],"h1":"监督的人必须到了可以合法喝酒的年龄。","h2":"在 New York，监督司机必须至少 21 岁，并且有所开车辆类型的有效驾照。","p":"对。监督的人必须 21 岁或以上。"},"vi":{"q":"Ở New York, người lái xe giám sát người có giấy phép tập lái phải bao nhiêu tuổi?","o":["Ít nhất 16 tuổi","Ít nhất 18 tuổi","Ít nhất 21 tuổi","Ít nhất 25 tuổi"],"h1":"Người giám sát phải đủ tuổi để được uống rượu hợp pháp.","h2":"Ở New York, người lái xe giám sát phải ít nhất 21 tuổi và có bằng lái hợp lệ cho loại xe đang lái.","p":"Đúng. Người giám sát phải từ 21 tuổi trở lên."},"tl":{"q":"Sa New York, ilang taon dapat ang supervising driver (nagbabantay na driver) ng may learner permit?","o":["Hindi bababa sa 16","Hindi bababa sa 18","Hindi bababa sa 21","Hindi bababa sa 25"],"h1":"Dapat ay nasa edad na ang supervisor para legal na uminom ng alak.","h2":"Sa New York, ang supervising driver ay dapat hindi bababa sa 21 taong gulang at may valid na lisensya para sa uri ng sasakyang minamaneho.","p":"Tama. Dapat ay 21 o mas matanda ang supervisor."},"ar":{"q":"في New York، كم يجب أن يكون عمر السائق المشرف على حامل تصريح التعلّم؟","o":["16 على الأقل","18 على الأقل","21 على الأقل","25 على الأقل"],"h1":"يجب أن يكون المشرف في عمر يسمح له بشرب الكحول قانونيًا.","h2":"في New York يجب أن يكون السائق المشرف بعمر 21 سنة على الأقل وأن يحمل رخصة سارية لنوع المركبة التي تُقاد.","p":"صحيح. يجب أن يكون المشرف بعمر 21 أو أكثر."},"ref":{"doc":"NY","page":11}},{"id":"ny-009","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, how long must a teen hold the learner permit before taking the road test?","o":["At least one month","At least six months","At least three months","At least one year"],"h1":"It is half a year.","h2":"A New York teen must hold the learner permit for at least six months before taking the road test.","p":"Right. Hold the permit at least six months."},"es":{"q":"En Nueva York, ¿cuánto tiempo debe tener un joven el permiso de aprendiz antes del examen de manejo?","o":["Por lo menos un mes","Por lo menos seis meses","Por lo menos tres meses","Por lo menos un año"],"h1":"Es medio año.","h2":"En Nueva York, un joven debe tener el permiso de aprendiz por lo menos seis meses antes del examen de manejo.","p":"Correcto. Tenga el permiso por lo menos seis meses."},"zh":{"q":"在 New York，青少年必须持有学习驾照多久才能参加路考？","o":["至少一个月","至少六个月","至少三个月","至少一年"],"h1":"它是半年。","h2":"New York 的青少年必须持有学习驾照至少六个月，才能参加路考。","p":"对。持有学习驾照至少六个月。"},"vi":{"q":"Ở New York, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi thi lái trên đường?","o":["Ít nhất một tháng","Ít nhất sáu tháng","Ít nhất ba tháng","Ít nhất một năm"],"h1":"Đó là nửa năm.","h2":"Thiếu niên ở New York phải giữ giấy phép tập lái ít nhất sáu tháng trước khi thi lái trên đường.","p":"Đúng. Giữ giấy phép ít nhất sáu tháng."},"tl":{"q":"Sa New York, gaano katagal dapat hawak ng isang teen ang learner permit bago kumuha ng road test?","o":["Hindi bababa sa isang buwan","Hindi bababa sa anim na buwan","Hindi bababa sa tatlong buwan","Hindi bababa sa isang taon"],"h1":"Kalahating taon ito.","h2":"Ang isang teen sa New York ay dapat may hawak ng learner permit nang hindi bababa sa anim na buwan bago kumuha ng road test.","p":"Tama. Hawakan ang permit nang hindi bababa sa anim na buwan."},"ar":{"q":"في New York، كم يجب أن يحمل المراهق تصريح التعلّم قبل أداء اختبار القيادة على الطريق؟","o":["شهر واحد على الأقل","ستة أشهر على الأقل","ثلاثة أشهر على الأقل","سنة واحدة على الأقل"],"h1":"هي نصف سنة.","h2":"يجب أن يحمل المراهق في New York تصريح التعلّم ستة أشهر على الأقل قبل أداء اختبار القيادة على الطريق.","p":"صحيح. احمل التصريح ستة أشهر على الأقل."},"ref":{"doc":"NY","page":14}},{"id":"ny-010","scope":"NY","cat":"licensing","sign":null,"c":3,"en":{"q":"In New York, who may sit in the front seat when a junior permit holder is driving?","o":["Any passenger over 16","Any family member","Anyone wearing a seat belt","Only the supervising driver"],"h1":"The seat beside the learner is saved for one person.","h2":"When a New York junior permit holder drives, no one may sit in the front seat except the supervising driver.","p":"Right. Only the supervisor sits in front."},"es":{"q":"En Nueva York, ¿quién puede ir en el asiento delantero cuando maneja alguien con permiso de aprendiz juvenil?","o":["Cualquier pasajero mayor de 16","Cualquier familiar","Cualquiera que use el cinturón","Solo el conductor supervisor"],"h1":"El asiento al lado del aprendiz es para una sola persona.","h2":"Cuando maneja en Nueva York alguien con permiso de aprendiz juvenil, nadie puede ir en el asiento delantero excepto el conductor supervisor.","p":"Correcto. Solo el supervisor va adelante."},"zh":{"q":"在 New York，青少年学习驾照（junior permit）持有人开车时，谁可以坐在前排？","o":["任何 16 岁以上的乘客","任何家人","任何系了安全带的人","只有监督司机"],"h1":"学员旁边的座位是留给一个人的。","h2":"New York 的青少年学习驾照持有人开车时，除了监督司机，任何人都不能坐在前排。","p":"对。只有监督的人坐在前面。"},"vi":{"q":"Ở New York, ai được ngồi ghế trước khi người có giấy phép tập lái thiếu niên (junior permit) đang lái xe?","o":["Bất kỳ hành khách nào trên 16 tuổi","Bất kỳ người nào trong gia đình","Bất kỳ ai thắt dây an toàn","Chỉ người lái xe giám sát"],"h1":"Ghế bên cạnh người tập lái được dành cho một người.","h2":"Khi người có junior permit ở New York lái xe, không ai được ngồi ghế trước ngoại trừ người lái xe giám sát.","p":"Đúng. Chỉ người giám sát ngồi phía trước."},"tl":{"q":"Sa New York, sino ang puwedeng umupo sa harapang upuan kapag nagmamaneho ang may junior permit?","o":["Kahit sinong pasahero na higit 16 taong gulang","Kahit sinong miyembro ng pamilya","Kahit sinong nakasuot ng seat belt","Ang supervising driver lang"],"h1":"Ang upuan sa tabi ng nag-aaral ay para sa iisang tao.","h2":"Kapag nagmamaneho ang may junior permit sa New York, walang ibang puwedeng umupo sa harapang upuan maliban sa supervising driver.","p":"Tama. Ang supervisor lang ang nasa harap."},"ar":{"q":"في New York، من يمكنه الجلوس في المقعد الأمامي عندما يقود حامل تصريح التعلّم للصغار (junior permit)؟","o":["أي راكب عمره أكثر من 16","أي فرد من العائلة","أي شخص يضع حزام الأمان","السائق المشرف فقط"],"h1":"المقعد بجانب المتعلّم محجوز لشخص واحد.","h2":"عندما يقود حامل junior permit في New York، لا يجوز لأحد الجلوس في المقعد الأمامي إلا السائق المشرف.","p":"صحيح. المشرف وحده يجلس في الأمام."},"ref":{"doc":"NY","page":13}},{"id":"ny-011","scope":"NY","cat":"licensing","sign":null,"c":0,"en":{"q":"In New York City, when may a junior permit holder (under 18) never drive?","o":["Between 9 p.m. and 5 a.m.","Between midnight and 6 a.m.","Between 10 p.m. and 4 a.m.","Between 11 p.m. and 5 a.m."],"h1":"It starts at 9 in the evening.","h2":"A junior permit holder may never drive in the five boroughs of New York City between 9 p.m. and 5 a.m.","p":"Right. No junior permit driving in the city from 9 p.m. to 5 a.m."},"es":{"q":"En la ciudad de Nueva York, ¿en qué horario no puede manejar nunca quien tiene un permiso juvenil (menor de 18 años)?","o":["Entre las 9 p.m. y las 5 a.m.","Entre la medianoche y las 6 a.m.","Entre las 10 p.m. y las 4 a.m.","Entre las 11 p.m. y las 5 a.m."],"h1":"Empieza a las 9 de la noche.","h2":"Quien tiene un permiso juvenil nunca puede manejar en los cinco condados de la ciudad de Nueva York entre las 9 p.m. y las 5 a.m.","p":"Correcto. Con permiso juvenil no se maneja en la ciudad de 9 p.m. a 5 a.m."},"zh":{"q":"在 New York City，青少年学习驾照（junior permit）持有人（未满 18 岁）什么时候绝对不能开车？","o":["晚上 9 点到早上 5 点之间","午夜到早上 6 点之间","晚上 10 点到凌晨 4 点之间","晚上 11 点到早上 5 点之间"],"h1":"它从晚上 9 点开始。","h2":"青少年学习驾照持有人在晚上 9 点到早上 5 点之间，绝对不能在 New York City 的五个区开车。","p":"对。晚上 9 点到早上 5 点，青少年学习驾照不能在市内开车。"},"vi":{"q":"Ở New York City, người có junior permit (dưới 18 tuổi) không bao giờ được lái xe vào giờ nào?","o":["Từ 9 giờ tối đến 5 giờ sáng","Từ nửa đêm đến 6 giờ sáng","Từ 10 giờ tối đến 4 giờ sáng","Từ 11 giờ tối đến 5 giờ sáng"],"h1":"Bắt đầu lúc 9 giờ tối.","h2":"Người có junior permit không bao giờ được lái xe trong năm quận của New York City từ 9 giờ tối đến 5 giờ sáng.","p":"Đúng. Người có junior permit không được lái trong thành phố từ 9 giờ tối đến 5 giờ sáng."},"tl":{"q":"Sa New York City, kailan hindi kailanman puwedeng magmaneho ang may junior permit (wala pang 18)?","o":["Mula 9 p.m. hanggang 5 a.m.","Mula hatinggabi hanggang 6 a.m.","Mula 10 p.m. hanggang 4 a.m.","Mula 11 p.m. hanggang 5 a.m."],"h1":"Nagsisimula ito nang 9 ng gabi.","h2":"Ang may junior permit ay hindi kailanman puwedeng magmaneho sa limang borough ng New York City mula 9 p.m. hanggang 5 a.m.","p":"Tama. Bawal magmaneho ang may junior permit sa lungsod mula 9 p.m. hanggang 5 a.m."},"ar":{"q":"في New York City، متى لا يجوز أبدًا لحامل junior permit (أقل من 18 سنة) أن يقود؟","o":["من 9 مساءً إلى 5 صباحًا","من منتصف الليل إلى 6 صباحًا","من 10 مساءً إلى 4 صباحًا","من 11 مساءً إلى 5 صباحًا"],"h1":"يبدأ في الساعة 9 مساءً.","h2":"لا يجوز أبدًا لحامل junior permit أن يقود في الأحياء الخمسة (boroughs) في New York City من 9 مساءً إلى 5 صباحًا.","p":"صحيح. لا قيادة بتصريح junior في المدينة من 9 مساءً إلى 5 صباحًا."},"ref":{"doc":"NY","page":12}},{"id":"ny-012","scope":"NY","cat":"licensing","sign":null,"c":2,"en":{"q":"In New York City, what kind of car must a junior permit holder (under 18) use during the day?","o":["Any car with four doors","A car with automatic transmission","A car with dual controls","A car with a backup camera"],"h1":"The supervisor must be able to brake too.","h2":"In New York City a junior permit holder may drive during the day only in a car with dual controls, so the supervisor can brake too.","p":"Right. In the city, the car must have dual controls."},"es":{"q":"En la ciudad de Nueva York, ¿qué tipo de auto debe usar de día quien tiene un permiso juvenil (menor de 18 años)?","o":["Cualquier auto de cuatro puertas","Un auto con transmisión automática","Un auto con doble control","Un auto con cámara de reversa"],"h1":"El supervisor también debe poder frenar.","h2":"En la ciudad de Nueva York, quien tiene un permiso juvenil solo puede manejar de día en un auto con doble control, para que el supervisor también pueda frenar.","p":"Correcto. En la ciudad, el auto debe tener doble control."},"zh":{"q":"在 New York City，青少年学习驾照（junior permit）持有人（未满 18 岁）白天必须用什么样的车？","o":["任何四门车","自动挡的车","有双控制装置（dual controls）的车","有倒车摄像头的车"],"h1":"监督的人也必须能刹车。","h2":"在 New York City，青少年学习驾照持有人白天只能开有双控制装置（dual controls）的车，这样监督的人也能刹车。","p":"对。在市内，车必须有双控制装置。"},"vi":{"q":"Ở New York City, người có junior permit (dưới 18 tuổi) phải dùng loại xe nào vào ban ngày?","o":["Bất kỳ xe nào có bốn cửa","Xe số tự động","Xe có bộ điều khiển kép (dual controls)","Xe có camera lùi"],"h1":"Người giám sát cũng phải có thể đạp thắng.","h2":"Ở New York City, người có junior permit chỉ được lái ban ngày trong xe có bộ điều khiển kép (dual controls), để người giám sát cũng có thể đạp thắng.","p":"Đúng. Trong thành phố, xe phải có bộ điều khiển kép."},"tl":{"q":"Sa New York City, anong uri ng kotse ang dapat gamitin ng may junior permit (wala pang 18) sa araw?","o":["Kahit anong kotse na may apat na pinto","Kotseng automatic ang transmission","Kotseng may dual controls","Kotseng may backup camera"],"h1":"Dapat ay kaya ring magpreno ng supervisor.","h2":"Sa New York City, ang may junior permit ay puwedeng magmaneho sa araw sa kotseng may dual controls lang, para kaya ring magpreno ng supervisor.","p":"Tama. Sa lungsod, dapat may dual controls ang kotse."},"ar":{"q":"في New York City، أي نوع من السيارات يجب أن يستخدمه حامل junior permit (أقل من 18 سنة) أثناء النهار؟","o":["أي سيارة بأربعة أبواب","سيارة بناقل حركة أوتوماتيكي","سيارة بأدوات تحكم مزدوجة (dual controls)","سيارة بكاميرا خلفية"],"h1":"يجب أن يتمكن المشرف أيضًا من الضغط على الفرامل.","h2":"في New York City لا يجوز لحامل junior permit أن يقود في النهار إلا في سيارة بأدوات تحكم مزدوجة (dual controls)، حتى يتمكن المشرف أيضًا من الضغط على الفرامل.","p":"صحيح. في المدينة يجب أن تكون للسيارة أدوات تحكم مزدوجة."},"ref":{"doc":"NY","page":12}},{"id":"ny-013","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, where may a junior license holder never drive?","o":["On Long Island","In New York City","On rural roads","In parking lots"],"h1":"It is the largest city in the state.","h2":"A New York junior license holder may not drive in New York City under any circumstances.","p":"Right. A junior license does not allow driving in New York City."},"es":{"q":"En Nueva York, ¿dónde nunca puede manejar quien tiene licencia juvenil?","o":["En Long Island","En la ciudad de Nueva York","En caminos rurales","En estacionamientos"],"h1":"Es la ciudad más grande del estado.","h2":"En Nueva York, quien tiene licencia juvenil no puede manejar en la ciudad de Nueva York bajo ninguna circunstancia.","p":"Correcto. La licencia juvenil no permite manejar en la ciudad de Nueva York."},"zh":{"q":"在 New York，青少年驾照（junior license）持有人绝对不能在哪里开车？","o":["在 Long Island","在 New York City","在乡村道路上","在停车场"],"h1":"它是这个州最大的城市。","h2":"New York 的青少年驾照持有人在任何情况下都不能在 New York City 开车。","p":"对。青少年驾照不能在 New York City 开车。"},"vi":{"q":"Ở New York, người có bằng lái thiếu niên (junior license) không bao giờ được lái xe ở đâu?","o":["Ở Long Island","Ở New York City","Trên đường nông thôn","Trong bãi đậu xe"],"h1":"Đó là thành phố lớn nhất của tiểu bang.","h2":"Người có junior license ở New York không được lái xe ở New York City trong bất kỳ trường hợp nào.","p":"Đúng. Junior license không cho phép lái xe ở New York City."},"tl":{"q":"Sa New York, saan hindi kailanman puwedeng magmaneho ang may junior license?","o":["Sa Long Island","Sa New York City","Sa mga daan sa probinsya","Sa mga parking lot"],"h1":"Ito ang pinakamalaking lungsod sa estado.","h2":"Ang may junior license sa New York ay hindi puwedeng magmaneho sa New York City sa anumang sitwasyon.","p":"Tama. Hindi pinapayagan ng junior license ang pagmamaneho sa New York City."},"ar":{"q":"في New York، أين لا يجوز أبدًا لحامل رخصة القيادة للصغار (junior license) أن يقود؟","o":["في Long Island","في New York City","على الطرق الريفية","في مواقف السيارات"],"h1":"هي أكبر مدينة في الولاية.","h2":"لا يجوز لحامل junior license في New York أن يقود في New York City في أي حال من الأحوال.","p":"صحيح. رخصة junior لا تسمح بالقيادة في New York City."},"ref":{"doc":"NY","page":16}},{"id":"ny-014","scope":"NY","cat":"licensing","sign":null,"c":3,"en":{"q":"In New York, how many passengers under 21 who are not close family may a junior license holder carry without a supervisor?","o":["None at all","No more than two","No more than three","No more than one"],"h1":"It is the smallest number that is not zero.","h2":"A New York junior license holder driving without a supervisor may carry no more than one passenger under 21 who is not an immediate family member.","p":"Right. Only one passenger under 21 who is not family."},"es":{"q":"En Nueva York, ¿cuántos pasajeros menores de 21 años que no son familiares cercanos puede llevar sin supervisor quien tiene licencia juvenil?","o":["Ninguno","No más de dos","No más de tres","No más de uno"],"h1":"Es el número más pequeño que no es cero.","h2":"En Nueva York, quien tiene licencia juvenil y maneja sin supervisor puede llevar no más de un pasajero menor de 21 años que no sea familiar cercano.","p":"Correcto. Solo un pasajero menor de 21 que no sea familiar."},"zh":{"q":"在 New York，没有监督的人时，青少年驾照（junior license）持有人可以载几位不是近亲、未满 21 岁的乘客？","o":["一位也不行","不超过两位","不超过三位","不超过一位"],"h1":"它是不等于零的最小数字。","h2":"New York 的青少年驾照持有人在没有监督的人时，最多只能载一位不是直系亲属、未满 21 岁的乘客。","p":"对。只能载一位不是家人、未满 21 岁的乘客。"},"vi":{"q":"Ở New York, khi không có người giám sát, người có junior license được chở bao nhiêu hành khách dưới 21 tuổi không phải người thân gần?","o":["Không ai cả","Không quá hai người","Không quá ba người","Không quá một người"],"h1":"Đó là số nhỏ nhất mà không phải là số không.","h2":"Người có junior license ở New York, khi lái không có người giám sát, được chở không quá một hành khách dưới 21 tuổi không phải người thân trong gia đình.","p":"Đúng. Chỉ một hành khách dưới 21 tuổi không phải người nhà."},"tl":{"q":"Sa New York, ilang pasahero na wala pang 21 at hindi malapit na kapamilya ang puwedeng isakay ng may junior license kapag walang supervisor?","o":["Wala talaga","Hindi hihigit sa dalawa","Hindi hihigit sa tatlo","Hindi hihigit sa isa"],"h1":"Ito ang pinakamaliit na numero na hindi zero.","h2":"Ang may junior license sa New York na nagmamaneho nang walang supervisor ay puwedeng magsakay ng hindi hihigit sa isang pasahero na wala pang 21 at hindi malapit na kapamilya.","p":"Tama. Isang pasahero lang na wala pang 21 na hindi kapamilya."},"ar":{"q":"في New York، كم راكبًا عمره أقل من 21 وليس من العائلة القريبة يمكن أن يحمل حامل junior license دون مشرف؟","o":["لا أحد على الإطلاق","اثنان على الأكثر","ثلاثة على الأكثر","واحد على الأكثر"],"h1":"هو أصغر عدد ليس صفرًا.","h2":"حامل junior license في New York الذي يقود دون مشرف يمكنه أن يحمل راكبًا واحدًا على الأكثر عمره أقل من 21 وليس من أفراد العائلة المباشرين.","p":"صحيح. راكب واحد فقط عمره أقل من 21 وليس من العائلة."},"ref":{"doc":"NY","page":15}},{"id":"ny-015","scope":"NY","cat":"licensing","sign":null,"c":0,"en":{"q":"In upstate New York (outside New York City and Long Island), between what hours may a junior license holder not drive alone, except straight between home and work or school?","o":["Between 9 p.m. and 5 a.m.","Between midnight and 6 a.m.","Between 11 p.m. and 5 a.m.","Between 10 p.m. and 6 a.m."],"h1":"It starts at 9 in the evening.","h2":"In upstate New York a junior license holder may not drive alone between 9 p.m. and 5 a.m., except straight between home and work or a school course.","p":"Right. Upstate, no driving alone from 9 p.m. to 5 a.m., except to work or school."},"es":{"q":"En el norte del estado de Nueva York (fuera de la ciudad de Nueva York y de Long Island), ¿en qué horario no puede manejar solo quien tiene licencia juvenil, salvo directo entre la casa y el trabajo o la escuela?","o":["Entre las 9 p.m. y las 5 a.m.","Entre la medianoche y las 6 a.m.","Entre las 11 p.m. y las 5 a.m.","Entre las 10 p.m. y las 6 a.m."],"h1":"Empieza a las 9 de la noche.","h2":"En el norte del estado de Nueva York, quien tiene licencia juvenil no puede manejar solo entre las 9 p.m. y las 5 a.m., salvo directo entre la casa y el trabajo o un curso escolar.","p":"Correcto. En el norte del estado no se maneja solo de 9 p.m. a 5 a.m., salvo al trabajo o la escuela."},"zh":{"q":"在 New York 州北部（New York City 和 Long Island 以外），除了直接往返家和工作或学校，青少年驾照（junior license）持有人在哪个时间段不能自己开车？","o":["晚上 9 点到早上 5 点之间","午夜到早上 6 点之间","晚上 11 点到早上 5 点之间","晚上 10 点到早上 6 点之间"],"h1":"它从晚上 9 点开始。","h2":"在 New York 州北部，青少年驾照持有人在晚上 9 点到早上 5 点之间不能自己开车，除非是直接往返家和工作或学校课程。","p":"对。在州北部，晚上 9 点到早上 5 点不能自己开车，去上班或上学除外。"},"vi":{"q":"Ở vùng upstate New York (ngoài New York City và Long Island), người có junior license không được lái một mình vào giờ nào, trừ khi đi thẳng giữa nhà và nơi làm việc hoặc trường học?","o":["Từ 9 giờ tối đến 5 giờ sáng","Từ nửa đêm đến 6 giờ sáng","Từ 11 giờ tối đến 5 giờ sáng","Từ 10 giờ tối đến 6 giờ sáng"],"h1":"Bắt đầu lúc 9 giờ tối.","h2":"Ở upstate New York, người có junior license không được lái một mình từ 9 giờ tối đến 5 giờ sáng, trừ khi đi thẳng giữa nhà và nơi làm việc hoặc một khóa học ở trường.","p":"Đúng. Ở upstate, không lái một mình từ 9 giờ tối đến 5 giờ sáng, trừ khi đi làm hoặc đi học."},"tl":{"q":"Sa upstate New York (labas ng New York City at Long Island), sa anong mga oras hindi puwedeng magmaneho nang mag-isa ang may junior license, maliban kung diretso sa pagitan ng bahay at trabaho o paaralan?","o":["Mula 9 p.m. hanggang 5 a.m.","Mula hatinggabi hanggang 6 a.m.","Mula 11 p.m. hanggang 5 a.m.","Mula 10 p.m. hanggang 6 a.m."],"h1":"Nagsisimula ito nang 9 ng gabi.","h2":"Sa upstate New York, ang may junior license ay hindi puwedeng magmaneho nang mag-isa mula 9 p.m. hanggang 5 a.m., maliban kung diretso sa pagitan ng bahay at trabaho o ng isang kurso sa paaralan.","p":"Tama. Sa upstate, bawal magmaneho nang mag-isa mula 9 p.m. hanggang 5 a.m., maliban papunta sa trabaho o paaralan."},"ar":{"q":"في شمال ولاية New York (upstate، خارج New York City وLong Island)، في أي ساعات لا يجوز لحامل junior license أن يقود وحده، إلا مباشرة بين البيت والعمل أو المدرسة؟","o":["من 9 مساءً إلى 5 صباحًا","من منتصف الليل إلى 6 صباحًا","من 11 مساءً إلى 5 صباحًا","من 10 مساءً إلى 6 صباحًا"],"h1":"يبدأ في الساعة 9 مساءً.","h2":"في upstate New York لا يجوز لحامل junior license أن يقود وحده من 9 مساءً إلى 5 صباحًا، إلا مباشرة بين البيت والعمل أو دورة دراسية.","p":"صحيح. في upstate لا قيادة وحدك من 9 مساءً إلى 5 صباحًا، إلا إلى العمل أو المدرسة."},"ref":{"doc":"NY","page":16}},{"id":"ny-016","scope":"NY","cat":"licensing","sign":null,"c":2,"en":{"q":"In New York, what course must most new drivers complete before the road test?","o":["A 1-hour online video","A 20-hour defensive driving course","A 5-hour pre-licensing course","A first aid course"],"h1":"It is a short classroom course of a few hours.","h2":"Most new drivers in New York must complete a 5-hour pre-licensing course before the road test, unless they finished a high school or college driver education program.","p":"Right. Most new drivers take the 5-hour course."},"es":{"q":"En Nueva York, ¿qué curso deben completar la mayoría de los conductores nuevos antes del examen de manejo?","o":["Un video en línea de 1 hora","Un curso de manejo defensivo de 20 horas","Un curso previo a la licencia de 5 horas","Un curso de primeros auxilios"],"h1":"Es un curso corto de pocas horas en un salón.","h2":"La mayoría de los conductores nuevos en Nueva York deben completar un curso previo a la licencia de 5 horas antes del examen de manejo, salvo que hayan terminado un programa de educación vial en la escuela secundaria o la universidad.","p":"Correcto. La mayoría toma el curso de 5 horas."},"zh":{"q":"在 New York，大多数新司机路考前必须完成什么课程？","o":["1 小时的网上视频","20 小时的防御性驾驶课程","5 小时的驾照前课程（pre-licensing course）","急救课程"],"h1":"它是一个只有几小时的短课堂课程。","h2":"New York 的大多数新司机路考前必须完成 5 小时的驾照前课程（pre-licensing course），除非已经上完高中或大学的驾驶教育课程。","p":"对。大多数新司机要上 5 小时的课程。"},"vi":{"q":"Ở New York, phần lớn người mới lái xe phải hoàn thành khóa học nào trước khi thi lái trên đường?","o":["Một video trên mạng dài 1 giờ","Một khóa lái xe phòng thủ 20 giờ","Một khóa học trước khi cấp bằng (pre-licensing course) 5 giờ","Một khóa sơ cứu"],"h1":"Đó là một khóa học ngắn trong lớp, vài giờ.","h2":"Phần lớn người mới lái xe ở New York phải hoàn thành khóa học trước khi cấp bằng (pre-licensing course) 5 giờ trước khi thi lái trên đường, trừ khi họ đã học xong chương trình giáo dục lái xe ở trường trung học hoặc đại học.","p":"Đúng. Phần lớn người mới lái học khóa 5 giờ."},"tl":{"q":"Sa New York, anong kurso ang dapat tapusin ng karamihan ng bagong driver bago ang road test?","o":["Isang 1 oras na video online","Isang 20 oras na defensive driving course","Isang 5 oras na pre-licensing course","Isang kurso sa first aid"],"h1":"Isa itong maikling kurso sa classroom na ilang oras lang.","h2":"Karamihan ng bagong driver sa New York ay dapat makatapos ng 5 oras na pre-licensing course bago ang road test, maliban kung natapos nila ang driver education program sa high school o kolehiyo.","p":"Tama. Kinukuha ng karamihan ng bagong driver ang 5 oras na kurso."},"ar":{"q":"في New York، ما الدورة التي يجب أن يكملها معظم السائقين الجدد قبل اختبار القيادة على الطريق؟","o":["فيديو على الإنترنت مدته ساعة واحدة","دورة قيادة دفاعية مدتها 20 ساعة","دورة ما قبل الترخيص (pre-licensing course) مدتها 5 ساعات","دورة إسعافات أولية"],"h1":"هي دورة قصيرة في الصف مدتها بضع ساعات.","h2":"يجب أن يكمل معظم السائقين الجدد في New York دورة ما قبل الترخيص (pre-licensing course) مدتها 5 ساعات قبل اختبار القيادة على الطريق، إلا إذا أنهوا برنامج تعليم القيادة في المدرسة الثانوية أو الكلية.","p":"صحيح. معظم السائقين الجدد يأخذون الدورة ذات الخمس ساعات."},"ref":{"doc":"NY","page":8}},{"id":"ny-017","scope":"NY","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New York, a school bus with flashing red lights is stopped on the other side of a divided highway. What must you do?","o":["Keep driving, because the highway is divided","Stop, even though you are on the other side","Slow down to 20 mph and pass","Honk and pass with care"],"h1":"In New York this rule has no exception for divided highways.","h2":"In New York you must stop for a school bus with flashing red lights even when it is on the other side of a divided highway.","p":"Right. In New York, traffic on both sides stops."},"es":{"q":"En Nueva York, un autobús escolar con luces rojas intermitentes está detenido al otro lado de una carretera dividida. ¿Qué debe hacer?","o":["Seguir manejando, porque la carretera está dividida","Detenerse, aunque usted esté del otro lado","Bajar a 20 mph y pasar","Tocar la bocina y pasar con cuidado"],"h1":"En Nueva York esta regla no tiene excepción para carreteras divididas.","h2":"En Nueva York usted debe detenerse ante un autobús escolar con luces rojas intermitentes aunque esté al otro lado de una carretera dividida.","p":"Correcto. En Nueva York se detiene el tráfico de los dos lados."},"zh":{"q":"在 New York，一辆闪着红灯的校车停在分隔公路的另一边。你必须怎么做？","o":["继续开，因为公路有分隔","停车，就算你在另一边","减速到 20 mph 然后经过","按喇叭然后小心经过"],"h1":"在 New York，这条规定对分隔公路没有例外。","h2":"在 New York，就算闪着红灯的校车在分隔公路的另一边，你也必须停车。","p":"对。在 New York，两边的车都要停。"},"vi":{"q":"Ở New York, một xe buýt trường học đang bật đèn đỏ nhấp nháy dừng ở phía bên kia của xa lộ có dải phân cách. Bạn phải làm gì?","o":["Tiếp tục lái, vì xa lộ có dải phân cách","Dừng lại, dù bạn ở phía bên kia","Giảm tốc xuống 20 mph rồi chạy qua","Bấm còi và chạy qua cẩn thận"],"h1":"Ở New York, luật này không có ngoại lệ cho xa lộ có dải phân cách.","h2":"Ở New York, bạn phải dừng lại khi có xe buýt trường học bật đèn đỏ nhấp nháy, ngay cả khi nó ở phía bên kia của xa lộ có dải phân cách.","p":"Đúng. Ở New York, xe cả hai chiều đều phải dừng."},"tl":{"q":"Sa New York, may school bus na may kumikislap na pulang ilaw na nakahinto sa kabilang panig ng divided highway. Ano ang dapat mong gawin?","o":["Tuloy lang sa pagmamaneho, dahil divided ang highway","Huminto, kahit nasa kabilang panig ka","Bagalan hanggang 20 mph at lumampas","Bumusina at lumampas nang maingat"],"h1":"Sa New York, walang exception ang patakarang ito para sa divided highway.","h2":"Sa New York, dapat kang huminto para sa school bus na may kumikislap na pulang ilaw kahit nasa kabilang panig ito ng divided highway.","p":"Tama. Sa New York, humihinto ang trapiko sa magkabilang panig."},"ar":{"q":"في New York، حافلة مدرسية متوقفة وأضواؤها الحمراء تومض على الجانب الآخر من طريق سريع مقسوم بفاصل. ماذا يجب أن تفعل؟","o":["تستمر في القيادة لأن الطريق مقسوم","تتوقف، حتى لو كنت على الجانب الآخر","تخفّف السرعة إلى 20 mph وتتجاوز","تضغط على البوق وتتجاوز بحذر"],"h1":"في New York لا يوجد استثناء في هذه القاعدة للطرق المقسومة.","h2":"في New York يجب أن تتوقف للحافلة المدرسية ذات الأضواء الحمراء الوامضة حتى لو كانت على الجانب الآخر من طريق سريع مقسوم.","p":"صحيح. في New York تتوقف السيارات في الاتجاهين."},"ref":{"doc":"NY","page":40}},{"id":"ny-018","scope":"NY","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New York, how far from a stopped school bus with flashing red lights should you stop?","o":["At least 5 feet","At least 10 feet","Right next to the bus","At least 20 feet"],"h1":"It is a bit more than the length of a car.","h2":"In New York you should stop at least 20 feet away from a school bus with flashing red lights.","p":"Right. Stay at least 20 feet back."},"es":{"q":"En Nueva York, ¿a qué distancia de un autobús escolar detenido con luces rojas intermitentes debe detenerse?","o":["Por lo menos a 5 pies","Por lo menos a 10 pies","Justo al lado del autobús","Por lo menos a 20 pies"],"h1":"Es un poco más que el largo de un auto.","h2":"En Nueva York usted debe detenerse por lo menos a 20 pies de un autobús escolar con luces rojas intermitentes.","p":"Correcto. Quédese por lo menos a 20 pies."},"zh":{"q":"在 New York，你应该停在离闪着红灯的校车多远的地方？","o":["至少 5 英尺","至少 10 英尺","就在校车旁边","至少 20 英尺"],"h1":"它比一辆车的长度多一点。","h2":"在 New York，你应该停在离闪着红灯的校车至少 20 英尺的地方。","p":"对。离开至少 20 英尺。"},"vi":{"q":"Ở New York, bạn nên dừng cách xe buýt trường học đang dừng và bật đèn đỏ nhấp nháy bao xa?","o":["Ít nhất 5 feet","Ít nhất 10 feet","Ngay sát bên xe buýt","Ít nhất 20 feet"],"h1":"Dài hơn chiều dài một chiếc xe hơi một chút.","h2":"Ở New York, bạn nên dừng cách xe buýt trường học đang bật đèn đỏ nhấp nháy ít nhất 20 feet.","p":"Đúng. Dừng cách xa ít nhất 20 feet."},"tl":{"q":"Sa New York, gaano kalayo ka dapat huminto mula sa nakahintong school bus na may kumikislap na pulang ilaw?","o":["Hindi bababa sa 5 feet","Hindi bababa sa 10 feet","Mismong katabi ng bus","Hindi bababa sa 20 feet"],"h1":"Medyo mas mahaba ito sa haba ng isang kotse.","h2":"Sa New York, dapat kang huminto nang hindi bababa sa 20 feet ang layo mula sa school bus na may kumikislap na pulang ilaw.","p":"Tama. Manatili nang hindi bababa sa 20 feet ang layo."},"ar":{"q":"في New York، على أي مسافة يجب أن تتوقف من حافلة مدرسية متوقفة وأضواؤها الحمراء تومض؟","o":["5 أقدام (feet) على الأقل","10 أقدام (feet) على الأقل","بجانب الحافلة مباشرة","20 قدمًا (feet) على الأقل"],"h1":"هي أطول قليلًا من طول سيارة.","h2":"في New York يجب أن تتوقف على بعد 20 قدمًا (feet) على الأقل من الحافلة المدرسية ذات الأضواء الحمراء الوامضة.","p":"صحيح. ابقَ على بعد 20 قدمًا على الأقل."},"ref":{"doc":"NY","page":40}},{"id":"ny-019","scope":"NY","cat":"signals","sign":null,"c":2,"en":{"q":"In New York City, may you turn right on a red light after a full stop?","o":["Yes, always after a full stop","Yes, but only at night","No, unless a sign says it is allowed","Yes, if no police officer is present"],"h1":"The city has the opposite rule from the rest of the state.","h2":"In New York City you may not turn right on a red light unless a sign says it is allowed.","p":"Right. No turn on red in the city without a sign."},"es":{"q":"En la ciudad de Nueva York, ¿puede dar vuelta a la derecha con la luz roja después de detenerse por completo?","o":["Sí, siempre después de detenerse","Sí, pero solo de noche","No, salvo que una señal lo permita","Sí, si no hay un policía"],"h1":"La ciudad tiene la regla contraria al resto del estado.","h2":"En la ciudad de Nueva York no puede dar vuelta a la derecha con la luz roja, salvo que una señal lo permita.","p":"Correcto. En la ciudad no se da vuelta con la luz roja sin una señal."},"zh":{"q":"在 New York City，红灯时完全停车以后可以右转吗？","o":["可以，完全停车以后都可以","可以，但只在晚上","不可以，除非有标志说允许","可以，如果没有警察"],"h1":"这个城市的规定和州里其他地方相反。","h2":"在 New York City，红灯时不能右转，除非有标志说允许。","p":"对。在市内，没有标志就不能红灯右转。"},"vi":{"q":"Ở New York City, bạn có được quẹo phải khi đèn đỏ sau khi đã dừng hẳn không?","o":["Có, luôn được sau khi dừng hẳn","Có, nhưng chỉ vào ban đêm","Không, trừ khi có biển báo cho phép","Có, nếu không có cảnh sát"],"h1":"Thành phố có luật ngược lại với phần còn lại của tiểu bang.","h2":"Ở New York City, bạn không được quẹo phải khi đèn đỏ, trừ khi có biển báo cho phép.","p":"Đúng. Trong thành phố không được quẹo khi đèn đỏ nếu không có biển báo."},"tl":{"q":"Sa New York City, puwede ka bang kumanan sa pulang ilaw pagkatapos ng buong paghinto?","o":["Oo, palagi pagkatapos ng buong paghinto","Oo, pero sa gabi lang","Hindi, maliban kung may sign na nagsasabing pinapayagan ito","Oo, kung walang pulis"],"h1":"Kabaligtaran ang patakaran ng lungsod sa ibang bahagi ng estado.","h2":"Sa New York City, hindi ka puwedeng kumanan sa pulang ilaw maliban kung may sign na nagsasabing pinapayagan ito.","p":"Tama. Bawal kumanan sa pula sa lungsod kung walang sign."},"ar":{"q":"في New York City، هل يجوز لك الانعطاف يمينًا عند الإشارة الحمراء بعد التوقف التام؟","o":["نعم، دائمًا بعد التوقف التام","نعم، لكن في الليل فقط","لا، إلا إذا كانت هناك لافتة تسمح بذلك","نعم، إذا لم يكن هناك شرطي"],"h1":"المدينة لها قاعدة عكس باقي الولاية.","h2":"في New York City لا يجوز لك الانعطاف يمينًا عند الإشارة الحمراء إلا إذا كانت هناك لافتة تسمح بذلك.","p":"صحيح. لا انعطاف عند الأحمر في المدينة بدون لافتة."},"ref":{"doc":"NY","page":31}},{"id":"ny-020","scope":"NY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New York, when must you turn on your headlights during the day?","o":["Whenever the weather makes you use your windshield wipers","Only inside tunnels","Only on highways","Never during the day"],"h1":"Think about rain, snow, sleet or fog.","h2":"New York law says you must turn on your headlights whenever the weather makes you use your windshield wipers, and daytime running lights do not count.","p":"Right. Wipers on, headlights on."},"es":{"q":"En Nueva York, ¿cuándo debe encender los faros durante el día?","o":["Siempre que el clima le obligue a usar los limpiaparabrisas","Solo dentro de los túneles","Solo en las autopistas","Nunca durante el día"],"h1":"Piense en lluvia, nieve, aguanieve o niebla.","h2":"La ley de Nueva York dice que debe encender los faros siempre que el clima le obligue a usar los limpiaparabrisas, y las luces de circulación diurna no cuentan.","p":"Correcto. Si usa los limpiaparabrisas, encienda los faros."},"zh":{"q":"在 New York，白天什么时候必须开大灯？","o":["天气让你需要用雨刷的时候","只在隧道里","只在高速公路上","白天从来不用"],"h1":"想想下雨、下雪、冻雨或有雾。","h2":"New York 法律规定，天气让你需要用雨刷时，你必须开大灯，日间行车灯不算。","p":"对。开雨刷，就开大灯。"},"vi":{"q":"Ở New York, khi nào bạn phải bật đèn pha vào ban ngày?","o":["Bất cứ khi nào thời tiết khiến bạn phải dùng cần gạt nước kính chắn gió","Chỉ trong đường hầm","Chỉ trên xa lộ","Không bao giờ vào ban ngày"],"h1":"Hãy nghĩ đến mưa, tuyết, mưa tuyết hoặc sương mù.","h2":"Luật New York nói bạn phải bật đèn pha bất cứ khi nào thời tiết khiến bạn phải dùng cần gạt nước, và đèn chạy ban ngày (daytime running lights) không được tính.","p":"Đúng. Bật cần gạt nước thì bật đèn pha."},"tl":{"q":"Sa New York, kailan mo dapat buksan ang headlights sa araw?","o":["Tuwing pinapagamit ka ng panahon ng windshield wipers","Sa loob lang ng tunnel","Sa highway lang","Hindi kailanman sa araw"],"h1":"Isipin ang ulan, niyebe, sleet o fog.","h2":"Sinasabi ng batas ng New York na dapat mong buksan ang headlights tuwing pinapagamit ka ng panahon ng windshield wipers, at hindi binibilang ang daytime running lights.","p":"Tama. Bukas ang wipers, bukas ang headlights."},"ar":{"q":"في New York، متى يجب أن تشغّل المصابيح الأمامية أثناء النهار؟","o":["كلما جعلك الطقس تستخدم مسّاحات الزجاج الأمامي","داخل الأنفاق فقط","على الطرق السريعة فقط","أبدًا أثناء النهار"],"h1":"فكّر في المطر أو الثلج أو المطر المتجمد أو الضباب.","h2":"يقول قانون New York إنه يجب أن تشغّل المصابيح الأمامية كلما جعلك الطقس تستخدم مسّاحات الزجاج الأمامي، وأضواء النهار (daytime running lights) لا تُحسب.","p":"صحيح. المسّاحات تعمل، المصابيح تعمل."},"ref":{"doc":"NY","page":63}},{"id":"ny-021","scope":"NY","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New York State, outside New York City, what is the speed limit when no limit is posted?","o":["45 mph","60 mph","65 mph","55 mph"],"h1":"It is the same number used on many expressways in the state.","h2":"In New York State, when no speed limit is posted, you may not drive faster than 55 mph.","p":"Right. With no sign, the limit is 55 mph."},"es":{"q":"En el estado de Nueva York, fuera de la ciudad de Nueva York, ¿cuál es el límite de velocidad cuando no hay uno indicado?","o":["45 mph","60 mph","65 mph","55 mph"],"h1":"Es el mismo número de muchas autopistas del estado.","h2":"En el estado de Nueva York, cuando no hay un límite indicado, no puede manejar a más de 55 mph.","p":"Correcto. Sin señal, el límite es 55 mph."},"zh":{"q":"在 New York 州，New York City 以外，没有标示限速时，限速是多少？","o":["45 mph","60 mph","65 mph","55 mph"],"h1":"这个州很多快速路也用这个数字。","h2":"在 New York 州，没有标示限速时，你开车不能超过 55 mph。","p":"对。没有标志时，限速是 55 mph。"},"vi":{"q":"Ở tiểu bang New York, ngoài New York City, giới hạn tốc độ là bao nhiêu khi không có biển báo tốc độ?","o":["45 mph","60 mph","65 mph","55 mph"],"h1":"Đó là cùng con số dùng trên nhiều đường cao tốc trong tiểu bang.","h2":"Ở tiểu bang New York, khi không có biển báo giới hạn tốc độ, bạn không được lái nhanh hơn 55 mph.","p":"Đúng. Không có biển báo thì giới hạn là 55 mph."},"tl":{"q":"Sa New York State, labas ng New York City, ano ang speed limit kapag walang nakapaskil na limit?","o":["45 mph","60 mph","65 mph","55 mph"],"h1":"Ito ang parehong numero na ginagamit sa maraming expressway sa estado.","h2":"Sa New York State, kapag walang nakapaskil na speed limit, hindi ka puwedeng magmaneho nang mas mabilis sa 55 mph.","p":"Tama. Kung walang sign, 55 mph ang limit."},"ar":{"q":"في ولاية New York، خارج New York City، ما حدّ السرعة عندما لا توجد لافتة حدّ سرعة؟","o":["45 mph","60 mph","65 mph","55 mph"],"h1":"هو نفس الرقم المستخدم على كثير من الطرق السريعة في الولاية.","h2":"في ولاية New York، عندما لا توجد لافتة حدّ سرعة، لا يجوز أن تقود أسرع من 55 mph.","p":"صحيح. بدون لافتة، الحدّ هو 55 mph."},"ref":{"doc":"NY","page":47}},{"id":"ny-022","scope":"NY","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New York City, what is the speed limit when no other limit is posted?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"It is lower than the 30 mph used in many towns.","h2":"In New York City the speed limit is 25 mph unless a sign shows a different limit.","p":"Right. The city default is 25 mph."},"es":{"q":"En la ciudad de Nueva York, ¿cuál es el límite de velocidad cuando no hay otro indicado?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Es más bajo que las 30 mph de muchos pueblos.","h2":"En la ciudad de Nueva York el límite de velocidad es 25 mph, salvo que una señal indique otro límite.","p":"Correcto. En la ciudad, el límite general es 25 mph."},"zh":{"q":"在 New York City，没有标示其他限速时，限速是多少？","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"它比很多城镇用的 30 mph 低。","h2":"在 New York City，除非标志显示不同的限速，限速是 25 mph。","p":"对。市内默认限速是 25 mph。"},"vi":{"q":"Ở New York City, giới hạn tốc độ là bao nhiêu khi không có biển báo giới hạn khác?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Nó thấp hơn mức 30 mph dùng ở nhiều thị trấn.","h2":"Ở New York City, giới hạn tốc độ là 25 mph trừ khi có biển báo ghi giới hạn khác.","p":"Đúng. Giới hạn mặc định trong thành phố là 25 mph."},"tl":{"q":"Sa New York City, ano ang speed limit kapag walang ibang nakapaskil na limit?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Mas mababa ito sa 30 mph na ginagamit sa maraming bayan.","h2":"Sa New York City, 25 mph ang speed limit maliban kung may sign na nagpapakita ng ibang limit.","p":"Tama. 25 mph ang default sa lungsod."},"ar":{"q":"في New York City، ما حدّ السرعة عندما لا توجد لافتة بحدّ آخر؟","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"هو أقل من 30 mph المستخدم في بلدات كثيرة.","h2":"في New York City حدّ السرعة هو 25 mph إلا إذا أظهرت لافتة حدًّا مختلفًا.","p":"صحيح. الحدّ العادي في المدينة 25 mph."},"ref":{"doc":"NY","page":47}},{"id":"ny-023","scope":"NY","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New York, on a parkway or expressway, the Move Over law also covers which stopped vehicles?","o":["Only police cars","Only ambulances and fire trucks","Any vehicle stopped on the shoulder or in the road","Only tow trucks"],"h1":"It is not only emergency vehicles.","h2":"On a New York parkway or expressway, the Move Over law covers any vehicle stopped on the shoulder or in the road, so you slow down and move over when it is safe.","p":"Right. On those roads it covers every stopped vehicle."},"es":{"q":"En Nueva York, en una autopista o parkway, ¿qué vehículos detenidos también cubre la ley de cambiar de carril (Move Over)?","o":["Solo las patrullas de policía","Solo las ambulancias y los camiones de bomberos","Cualquier vehículo detenido en el acotamiento o en el camino","Solo las grúas"],"h1":"No son solo los vehículos de emergencia.","h2":"En una autopista o parkway de Nueva York, la ley de cambiar de carril cubre cualquier vehículo detenido en el acotamiento o en el camino, así que usted baja la velocidad y se cambia de carril cuando sea seguro.","p":"Correcto. En esas vías cubre a todo vehículo detenido."},"zh":{"q":"在 New York，在景观大道（parkway）或快速路（expressway）上，让道变道法（Move Over law）还包括哪些停着的车？","o":["只有警车","只有救护车和消防车","任何停在路肩或路上的车","只有拖车"],"h1":"不只是紧急车辆。","h2":"在 New York 的景观大道或快速路上，让道变道法（Move Over law）包括任何停在路肩或路上的车，所以在安全时你要减速并换车道让开。","p":"对。在这些路上，所有停着的车都包括在内。"},"vi":{"q":"Ở New York, trên parkway hoặc expressway, luật Tránh Sang Làn Khác (Move Over law) còn áp dụng cho những xe nào đang dừng?","o":["Chỉ xe cảnh sát","Chỉ xe cứu thương và xe cứu hỏa","Bất kỳ xe nào dừng trên lề đường hoặc trên đường","Chỉ xe kéo"],"h1":"Không chỉ là xe khẩn cấp.","h2":"Trên parkway hoặc expressway ở New York, luật Move Over áp dụng cho bất kỳ xe nào dừng trên lề đường hoặc trên đường, nên bạn giảm tốc và chuyển làn khi an toàn.","p":"Đúng. Trên những con đường đó, luật áp dụng cho mọi xe đang dừng."},"tl":{"q":"Sa New York, sa parkway o expressway, aling mga nakahintong sasakyan ang sakop din ng Move Over law?","o":["Mga sasakyan ng pulis lang","Mga ambulansya at fire truck lang","Kahit anong sasakyang nakahinto sa shoulder o sa daan","Mga tow truck lang"],"h1":"Hindi lang ito mga emergency vehicle.","h2":"Sa parkway o expressway sa New York, sakop ng Move Over law ang kahit anong sasakyang nakahinto sa shoulder o sa daan, kaya magbagal ka at lumipat ng lane kapag ligtas.","p":"Tama. Sa mga daang iyon, sakop nito ang bawat nakahintong sasakyan."},"ar":{"q":"في New York، على طريق parkway أو expressway، أي مركبات متوقفة يشملها أيضًا قانون الابتعاد (Move Over law)؟","o":["سيارات الشرطة فقط","سيارات الإسعاف والإطفاء فقط","أي مركبة متوقفة على كتف الطريق أو في الطريق","سيارات السحب فقط"],"h1":"ليست مركبات الطوارئ فقط.","h2":"على طريق parkway أو expressway في New York، يشمل قانون Move Over أي مركبة متوقفة على كتف الطريق أو في الطريق، لذلك تخفّف السرعة وتنتقل إلى مسار آخر عندما يكون ذلك آمنًا.","p":"صحيح. على تلك الطرق يشمل كل مركبة متوقفة."},"ref":{"doc":"NY","page":35}},{"id":"ny-024","scope":"NY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New York, what blood alcohol level breaks the Zero Tolerance law for a driver under 21?","o":["0.02 to 0.07 percent","0.08 percent or more","Only 0.10 percent or more","Any level is legal under 21 with a permit"],"h1":"It starts at the smallest amount a test can reliably measure.","h2":"In New York a driver under 21 breaks the Zero Tolerance law with a blood alcohol level from 0.02 to 0.07 percent, and a higher level is a criminal charge.","p":"Right. Zero Tolerance covers 0.02 to 0.07 percent."},"es":{"q":"En Nueva York, ¿qué nivel de alcohol en la sangre viola la ley de Tolerancia Cero para un conductor menor de 21 años?","o":["De 0.02 a 0.07 por ciento","0.08 por ciento o más","Solo 0.10 por ciento o más","Con permiso, cualquier nivel es legal para menores de 21"],"h1":"Empieza en la cantidad más pequeña que una prueba puede medir con seguridad.","h2":"En Nueva York, un conductor menor de 21 años viola la ley de Tolerancia Cero con un nivel de alcohol en la sangre de 0.02 a 0.07 por ciento, y un nivel más alto es un delito.","p":"Correcto. Tolerancia Cero cubre de 0.02 a 0.07 por ciento."},"zh":{"q":"在 New York，未满 21 岁的司机血液酒精浓度到多少就违反零容忍法（Zero Tolerance law）？","o":["0.02% 到 0.07%","0.08% 或以上","只有 0.10% 或以上","未满 21 岁、有学习驾照，任何浓度都合法"],"h1":"它从测试能可靠测出的最小量开始。","h2":"在 New York，未满 21 岁的司机血液酒精浓度在 0.02% 到 0.07% 就违反零容忍法（Zero Tolerance law），更高的浓度是刑事指控。","p":"对。零容忍法包括 0.02% 到 0.07%。"},"vi":{"q":"Ở New York, nồng độ cồn trong máu bao nhiêu thì vi phạm luật Không Dung Thứ (Zero Tolerance law) đối với người lái dưới 21 tuổi?","o":["0.02 đến 0.07 phần trăm","0.08 phần trăm trở lên","Chỉ từ 0.10 phần trăm trở lên","Dưới 21 tuổi có giấy phép thì mức nào cũng hợp pháp"],"h1":"Bắt đầu từ lượng nhỏ nhất mà máy đo có thể đo chính xác.","h2":"Ở New York, người lái dưới 21 tuổi vi phạm luật Zero Tolerance khi nồng độ cồn trong máu từ 0.02 đến 0.07 phần trăm, và mức cao hơn là tội hình sự.","p":"Đúng. Zero Tolerance áp dụng từ 0.02 đến 0.07 phần trăm."},"tl":{"q":"Sa New York, anong blood alcohol level ang lumalabag sa Zero Tolerance law para sa driver na wala pang 21?","o":["0.02 hanggang 0.07 porsyento","0.08 porsyento o higit pa","0.10 porsyento o higit pa lang","Legal ang kahit anong level kung wala pang 21 at may permit"],"h1":"Nagsisimula ito sa pinakamaliit na dami na maaasahang masukat ng test.","h2":"Sa New York, lumalabag sa Zero Tolerance law ang driver na wala pang 21 kapag ang blood alcohol level ay mula 0.02 hanggang 0.07 porsyento, at ang mas mataas na level ay isang kasong kriminal.","p":"Tama. Sakop ng Zero Tolerance ang 0.02 hanggang 0.07 porsyento."},"ar":{"q":"في New York، أي نسبة كحول في الدم تخالف قانون عدم التسامح (Zero Tolerance law) لسائق عمره أقل من 21؟","o":["من 0.02 إلى 0.07 بالمئة","0.08 بالمئة أو أكثر","0.10 بالمئة أو أكثر فقط","أي نسبة قانونية تحت 21 مع تصريح"],"h1":"تبدأ من أصغر كمية يمكن للاختبار قياسها بدقة.","h2":"في New York يخالف السائق الذي عمره أقل من 21 قانون Zero Tolerance إذا كانت نسبة الكحول في دمه من 0.02 إلى 0.07 بالمئة، والنسبة الأعلى تُعدّ تهمة جنائية.","p":"صحيح. Zero Tolerance يشمل من 0.02 إلى 0.07 بالمئة."},"ref":{"doc":"NY","page":57}},{"id":"ny-025","scope":"NY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New York, what happens after a first Zero Tolerance violation by a driver under 21?","o":["Only a written warning","A 30-day suspension","A fine with no suspension","The license is suspended for six months"],"h1":"It is half a year without a license.","h2":"After a first Zero Tolerance violation in New York, the driver under 21 has the license suspended for six months.","p":"Right. A first violation means a six-month suspension."},"es":{"q":"En Nueva York, ¿qué pasa después de una primera violación de Tolerancia Cero de un conductor menor de 21 años?","o":["Solo una advertencia por escrito","Una suspensión de 30 días","Una multa sin suspensión","Le suspenden la licencia por seis meses"],"h1":"Es medio año sin licencia.","h2":"Después de una primera violación de Tolerancia Cero en Nueva York, al conductor menor de 21 años le suspenden la licencia por seis meses.","p":"Correcto. La primera violación trae una suspensión de seis meses."},"zh":{"q":"在 New York，未满 21 岁的司机第一次违反零容忍法（Zero Tolerance）以后会怎么样？","o":["只有书面警告","暂停 30 天","只罚款，不暂停","驾照被暂停六个月"],"h1":"它是半年没有驾照。","h2":"在 New York，未满 21 岁的司机第一次违反零容忍法以后，驾照会被暂停六个月。","p":"对。第一次违反，暂停六个月。"},"vi":{"q":"Ở New York, điều gì xảy ra sau lần vi phạm Zero Tolerance đầu tiên của người lái dưới 21 tuổi?","o":["Chỉ một lời cảnh cáo bằng văn bản","Bị treo bằng 30 ngày","Bị phạt tiền mà không bị treo bằng","Bằng lái bị treo sáu tháng"],"h1":"Đó là nửa năm không có bằng lái.","h2":"Sau lần vi phạm Zero Tolerance đầu tiên ở New York, người lái dưới 21 tuổi bị treo bằng lái sáu tháng.","p":"Đúng. Lần vi phạm đầu tiên bị treo bằng sáu tháng."},"tl":{"q":"Sa New York, ano ang mangyayari pagkatapos ng unang Zero Tolerance violation ng driver na wala pang 21?","o":["Nakasulat na babala lang","30 araw na suspension","Multa na walang suspension","Masususpinde ang lisensya nang anim na buwan"],"h1":"Kalahating taon ito na walang lisensya.","h2":"Pagkatapos ng unang Zero Tolerance violation sa New York, masususpinde nang anim na buwan ang lisensya ng driver na wala pang 21.","p":"Tama. Ang unang violation ay anim na buwang suspension."},"ar":{"q":"في New York، ماذا يحدث بعد أول مخالفة لقانون Zero Tolerance لسائق عمره أقل من 21؟","o":["إنذار مكتوب فقط","إيقاف لمدة 30 يومًا","غرامة بدون إيقاف","إيقاف الرخصة لمدة ستة أشهر"],"h1":"هي نصف سنة بدون رخصة.","h2":"بعد أول مخالفة لقانون Zero Tolerance في New York، تُوقف رخصة السائق الذي عمره أقل من 21 لمدة ستة أشهر.","p":"صحيح. أول مخالفة تعني إيقافًا لمدة ستة أشهر."},"ref":{"doc":"NY","page":57}},{"id":"ny-026","scope":"NY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New York, Driving While Ability Impaired by alcohol (DWAI) starts at what blood alcohol level?","o":["More than 0.01 percent","More than 0.05 percent","More than 0.08 percent","More than 0.10 percent"],"h1":"It is below the 0.08 level for Driving While Intoxicated.","h2":"In New York, Driving While Ability Impaired by alcohol starts at a blood alcohol level of more than 0.05 percent, below the 0.08 percent level for Driving While Intoxicated.","p":"Right. DWAI starts above 0.05 percent."},"es":{"q":"En Nueva York, ¿a partir de qué nivel de alcohol en la sangre se considera manejar con la capacidad disminuida por alcohol (DWAI)?","o":["Más de 0.01 por ciento","Más de 0.05 por ciento","Más de 0.08 por ciento","Más de 0.10 por ciento"],"h1":"Está por debajo del nivel de 0.08 de manejar en estado de ebriedad.","h2":"En Nueva York, manejar con la capacidad disminuida por alcohol empieza con un nivel de alcohol en la sangre de más de 0.05 por ciento, por debajo del 0.08 por ciento de manejar en estado de ebriedad.","p":"Correcto. DWAI empieza con más de 0.05 por ciento."},"zh":{"q":"在 New York，酒精导致驾驶能力受损（DWAI）从血液酒精浓度多少开始？","o":["超过 0.01%","超过 0.05%","超过 0.08%","超过 0.10%"],"h1":"它低于醉酒驾驶（Driving While Intoxicated）的 0.08。","h2":"在 New York，酒精导致驾驶能力受损（DWAI）从血液酒精浓度超过 0.05% 开始，低于醉酒驾驶的 0.08%。","p":"对。DWAI 从超过 0.05% 开始。"},"vi":{"q":"Ở New York, tội Lái Xe Khi Bị Rượu Làm Giảm Khả Năng (Driving While Ability Impaired, DWAI) bắt đầu từ nồng độ cồn trong máu bao nhiêu?","o":["Hơn 0.01 phần trăm","Hơn 0.05 phần trăm","Hơn 0.08 phần trăm","Hơn 0.10 phần trăm"],"h1":"Nó thấp hơn mức 0.08 của tội Lái Xe Khi Say Rượu (Driving While Intoxicated).","h2":"Ở New York, tội Lái Xe Khi Bị Rượu Làm Giảm Khả Năng (DWAI) bắt đầu khi nồng độ cồn trong máu hơn 0.05 phần trăm, thấp hơn mức 0.08 phần trăm của tội Lái Xe Khi Say Rượu (Driving While Intoxicated).","p":"Đúng. DWAI bắt đầu từ trên 0.05 phần trăm."},"tl":{"q":"Sa New York, sa anong blood alcohol level nagsisimula ang Driving While Ability Impaired by alcohol (DWAI)?","o":["Higit sa 0.01 porsyento","Higit sa 0.05 porsyento","Higit sa 0.08 porsyento","Higit sa 0.10 porsyento"],"h1":"Mas mababa ito sa 0.08 level para sa Driving While Intoxicated.","h2":"Sa New York, nagsisimula ang Driving While Ability Impaired by alcohol (DWAI) sa blood alcohol level na higit sa 0.05 porsyento, mas mababa sa 0.08 porsyento na level para sa Driving While Intoxicated.","p":"Tama. Nagsisimula ang DWAI sa higit sa 0.05 porsyento."},"ar":{"q":"في New York، من أي نسبة كحول في الدم تبدأ مخالفة القيادة مع ضعف القدرة بسبب الكحول (Driving While Ability Impaired, DWAI)؟","o":["أكثر من 0.01 بالمئة","أكثر من 0.05 بالمئة","أكثر من 0.08 بالمئة","أكثر من 0.10 بالمئة"],"h1":"هي أقل من نسبة 0.08 الخاصة بالقيادة في حالة سُكر (Driving While Intoxicated).","h2":"في New York تبدأ مخالفة القيادة مع ضعف القدرة بسبب الكحول (DWAI) عند نسبة كحول في الدم أكثر من 0.05 بالمئة، وهي أقل من نسبة 0.08 بالمئة الخاصة بالقيادة في حالة سُكر (Driving While Intoxicated).","p":"صحيح. DWAI يبدأ فوق 0.05 بالمئة."},"ref":{"doc":"NY","page":58}},{"id":"ny-027","scope":"NY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New York, what happens to a junior permit or license holder after a first conviction for using a phone or texting while driving?","o":["A warning letter only","A 30-day suspension","The permit or license is suspended for 120 days","Points only, with no suspension"],"h1":"It is about four months.","h2":"In New York, a first phone or texting conviction suspends a junior permit or license for 120 days.","p":"Right. A first conviction means a 120-day suspension."},"es":{"q":"En Nueva York, ¿qué le pasa a quien tiene permiso o licencia juvenil después de una primera condena por usar el teléfono o enviar mensajes mientras maneja?","o":["Solo una carta de advertencia","Una suspensión de 30 días","Le suspenden el permiso o la licencia por 120 días","Solo puntos, sin suspensión"],"h1":"Son unos cuatro meses.","h2":"En Nueva York, una primera condena por usar el teléfono o enviar mensajes suspende el permiso o la licencia juvenil por 120 días.","p":"Correcto. La primera condena trae una suspensión de 120 días."},"zh":{"q":"在 New York，青少年学习驾照或青少年驾照持有人第一次因为开车时用手机或发短信被定罪，会怎么样？","o":["只有警告信","暂停 30 天","学习驾照或驾照被暂停 120 天","只扣分，不暂停"],"h1":"它大约是四个月。","h2":"在 New York，第一次因为用手机或发短信被定罪，青少年学习驾照或驾照会被暂停 120 天。","p":"对。第一次定罪，暂停 120 天。"},"vi":{"q":"Ở New York, điều gì xảy ra với người có junior permit hoặc junior license sau lần đầu bị kết tội dùng điện thoại hoặc nhắn tin khi lái xe?","o":["Chỉ một lá thư cảnh cáo","Bị treo 30 ngày","Giấy phép hoặc bằng lái bị treo 120 ngày","Chỉ bị trừ điểm, không bị treo"],"h1":"Khoảng bốn tháng.","h2":"Ở New York, lần đầu bị kết tội dùng điện thoại hoặc nhắn tin khi lái xe sẽ làm junior permit hoặc junior license bị treo 120 ngày.","p":"Đúng. Lần đầu bị kết tội là bị treo 120 ngày."},"tl":{"q":"Sa New York, ano ang mangyayari sa may junior permit o junior license pagkatapos ng unang conviction sa paggamit ng phone o pag-text habang nagmamaneho?","o":["Sulat ng babala lang","30 araw na suspension","Masususpinde ang permit o lisensya nang 120 araw","Points lang, walang suspension"],"h1":"Mga apat na buwan ito.","h2":"Sa New York, ang unang conviction sa paggamit ng phone o pag-text ay magsususpinde sa junior permit o lisensya nang 120 araw.","p":"Tama. Ang unang conviction ay 120 araw na suspension."},"ar":{"q":"في New York، ماذا يحدث لحامل junior permit أو junior license بعد أول إدانة باستخدام الهاتف أو إرسال الرسائل أثناء القيادة؟","o":["رسالة إنذار فقط","إيقاف لمدة 30 يومًا","إيقاف التصريح أو الرخصة لمدة 120 يومًا","نقاط فقط، بدون إيقاف"],"h1":"هي حوالي أربعة أشهر.","h2":"في New York، أول إدانة باستخدام الهاتف أو إرسال الرسائل أثناء القيادة توقف junior permit أو الرخصة لمدة 120 يومًا.","p":"صحيح. أول إدانة تعني إيقافًا لمدة 120 يومًا."},"ref":{"doc":"NY","page":19}},{"id":"ny-028","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, what vision do you need to pass the DMV vision test, with or without glasses?","o":["20/20 in both eyes","20/40 in at least one eye","20/60 in both eyes","20/100 in at least one eye"],"h1":"Only one eye has to meet the standard.","h2":"In New York you need 20/40 vision in at least one eye, with or without glasses or contacts, to pass the vision test.","p":"Right. You need 20/40 in at least one eye."},"es":{"q":"En Nueva York, ¿qué visión necesita para pasar el examen de la vista del DMV, con o sin lentes?","o":["20/20 en ambos ojos","20/40 en por lo menos un ojo","20/60 en ambos ojos","20/100 en por lo menos un ojo"],"h1":"Solo un ojo tiene que cumplir el requisito.","h2":"En Nueva York usted necesita una visión de 20/40 en por lo menos un ojo, con o sin lentes o lentes de contacto, para pasar el examen de la vista.","p":"Correcto. Necesita 20/40 en por lo menos un ojo."},"zh":{"q":"在 New York，要通过 DMV 视力检查，你需要什么视力（戴不戴眼镜都可以）？","o":["两只眼睛都是 20/20","至少一只眼睛是 20/40","两只眼睛都是 20/60","至少一只眼睛是 20/100"],"h1":"只需要一只眼睛达到标准。","h2":"在 New York，至少一只眼睛的视力要达到 20/40（戴不戴眼镜或隐形眼镜都可以），才能通过视力检查。","p":"对。至少一只眼睛要达到 20/40。"},"vi":{"q":"Ở New York, bạn cần thị lực như thế nào để qua bài kiểm tra thị lực của DMV, có hoặc không có kính?","o":["20/20 ở cả hai mắt","20/40 ở ít nhất một mắt","20/60 ở cả hai mắt","20/100 ở ít nhất một mắt"],"h1":"Chỉ cần một mắt đạt tiêu chuẩn.","h2":"Ở New York, bạn cần thị lực 20/40 ở ít nhất một mắt, có hoặc không có kính hay kính áp tròng, để qua bài kiểm tra thị lực.","p":"Đúng. Bạn cần 20/40 ở ít nhất một mắt."},"tl":{"q":"Sa New York, anong paningin ang kailangan mo para pumasa sa vision test ng DMV, may salamin man o wala?","o":["20/20 sa dalawang mata","20/40 sa kahit isang mata","20/60 sa dalawang mata","20/100 sa kahit isang mata"],"h1":"Isang mata lang ang kailangang umabot sa pamantayan.","h2":"Sa New York, kailangan mo ng 20/40 na paningin sa kahit isang mata, may salamin o contact lens man o wala, para pumasa sa vision test.","p":"Tama. Kailangan mo ng 20/40 sa kahit isang mata."},"ar":{"q":"في New York، ما النظر الذي تحتاجه لتنجح في فحص النظر في DMV، بالنظارة أو بدونها؟","o":["20/20 في العينين","20/40 في عين واحدة على الأقل","20/60 في العينين","20/100 في عين واحدة على الأقل"],"h1":"يكفي أن تحقق عين واحدة المعيار.","h2":"في New York تحتاج إلى نظر 20/40 في عين واحدة على الأقل، بالنظارة أو العدسات اللاصقة أو بدونها، لتنجح في فحص النظر.","p":"صحيح. تحتاج إلى 20/40 في عين واحدة على الأقل."},"ref":{"doc":"NY","page":10}},{"id":"ny-029","scope":"NY","cat":"licensing","sign":null,"c":3,"en":{"q":"In New York, when you apply for your first license, your proofs of name and identity must add up to how many points?","o":["At least 2 points","At least 4 points","At least 10 points","At least 6 points"],"h1":"A U.S. passport counts for 4 points, and that is not enough on its own.","h2":"In New York your proofs of name must add up to at least 6 points, and at least one of them must have your signature.","p":"Right. You need at least 6 points."},"es":{"q":"En Nueva York, cuando solicita su primera licencia, ¿cuántos puntos deben sumar sus pruebas de nombre e identidad?","o":["Por lo menos 2 puntos","Por lo menos 4 puntos","Por lo menos 10 puntos","Por lo menos 6 puntos"],"h1":"Un pasaporte de EE. UU. vale 4 puntos, y eso solo no es suficiente.","h2":"En Nueva York sus pruebas de nombre deben sumar por lo menos 6 puntos, y por lo menos una de ellas debe tener su firma.","p":"Correcto. Necesita por lo menos 6 puntos."},"zh":{"q":"在 New York，第一次申请驾照时，你的姓名和身份证明文件加起来必须有多少分？","o":["至少 2 分","至少 4 分","至少 10 分","至少 6 分"],"h1":"美国护照算 4 分，只有它还不够。","h2":"在 New York，你的姓名证明文件加起来必须至少有 6 分，而且至少有一份要有你的签名。","p":"对。你需要至少 6 分。"},"vi":{"q":"Ở New York, khi bạn xin bằng lái lần đầu, giấy tờ chứng minh tên và danh tính của bạn phải cộng lại được bao nhiêu điểm?","o":["Ít nhất 2 điểm","Ít nhất 4 điểm","Ít nhất 10 điểm","Ít nhất 6 điểm"],"h1":"Hộ chiếu Mỹ được tính 4 điểm, và chỉ một mình nó thì chưa đủ.","h2":"Ở New York, giấy tờ chứng minh tên của bạn phải cộng lại được ít nhất 6 điểm, và ít nhất một giấy tờ phải có chữ ký của bạn.","p":"Đúng. Bạn cần ít nhất 6 điểm."},"tl":{"q":"Sa New York, kapag nag-apply ka ng una mong lisensya, ilang points dapat ang kabuuan ng mga patunay ng pangalan at pagkakakilanlan mo?","o":["Hindi bababa sa 2 points","Hindi bababa sa 4 points","Hindi bababa sa 10 points","Hindi bababa sa 6 points"],"h1":"Ang U.S. passport ay 4 points, at hindi ito sapat nang mag-isa.","h2":"Sa New York, ang mga patunay ng pangalan mo ay dapat umabot ng hindi bababa sa 6 points, at kahit isa sa mga ito ay dapat may pirma mo.","p":"Tama. Kailangan mo ng hindi bababa sa 6 points."},"ar":{"q":"في New York، عندما تقدّم طلبًا لأول رخصة لك، كم نقطة يجب أن يكون مجموع إثباتات الاسم والهوية؟","o":["نقطتان على الأقل","4 نقاط على الأقل","10 نقاط على الأقل","6 نقاط على الأقل"],"h1":"جواز السفر الأمريكي يُحسب 4 نقاط، ولا يكفي وحده.","h2":"في New York يجب أن يكون مجموع إثباتات اسمك 6 نقاط على الأقل، ويجب أن يحمل واحد منها على الأقل توقيعك.","p":"صحيح. تحتاج إلى 6 نقاط على الأقل."},"ref":{"doc":"NY","page":8}},{"id":"ny-030","scope":"NY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New York, how must a child aged 4 to 7 ride in a car?","o":["In an approved child seat, usually a booster, with the lap and shoulder belt","With only the car's seat belt","On an adult's lap in the back seat","In a rear-facing infant seat"],"h1":"The car's belt alone does not fit a small child.","h2":"In New York a child aged 4 to 7 must ride in an approved child restraint, usually a booster seat, used with the lap and shoulder belt.","p":"Right. A booster or other approved child seat is required."},"es":{"q":"En Nueva York, ¿cómo debe viajar en un carro un niño de 4 a 7 años?","o":["En un asiento infantil aprobado, por lo general un asiento elevado, con el cinturón de regazo y hombro","Solo con el cinturón de seguridad del carro","En las piernas de un adulto en el asiento trasero","En un asiento para bebé mirando hacia atrás"],"h1":"El cinturón del carro solo no le queda bien a un niño pequeño.","h2":"En Nueva York un niño de 4 a 7 años debe viajar en un sistema de retención infantil aprobado, por lo general un asiento elevado, usado con el cinturón de regazo y hombro.","p":"Correcto. Se requiere un asiento elevado u otro asiento infantil aprobado."},"zh":{"q":"在 New York，4 到 7 岁的孩子坐车时必须怎么坐？","o":["坐在合格的儿童座椅上，通常是增高座椅，并系上腰带和肩带","只系汽车的安全带","坐在后座大人的腿上","坐在后向婴儿座椅上"],"h1":"只用汽车的安全带不适合小孩子。","h2":"在 New York，4 到 7 岁的孩子必须坐在合格的儿童安全座椅上，通常是增高座椅，并配合腰带和肩带使用。","p":"对。必须用增高座椅或其他合格的儿童座椅。"},"vi":{"q":"Ở New York, trẻ từ 4 đến 7 tuổi phải ngồi trong xe như thế nào?","o":["Trong ghế trẻ em được chấp thuận, thường là ghế nâng, với dây đai ngang hông và dây đai vai","Chỉ với dây an toàn của xe","Ngồi trên đùi người lớn ở ghế sau","Trong ghế em bé quay mặt về phía sau"],"h1":"Chỉ dây an toàn của xe thì không vừa với trẻ nhỏ.","h2":"Ở New York, trẻ từ 4 đến 7 tuổi phải ngồi trong ghế an toàn trẻ em được chấp thuận, thường là ghế nâng, dùng cùng dây đai ngang hông và dây đai vai.","p":"Đúng. Phải có ghế nâng hoặc ghế trẻ em khác được chấp thuận."},"tl":{"q":"Sa New York, paano dapat sumakay sa kotse ang batang 4 hanggang 7 taong gulang?","o":["Sa aprubadong child seat, karaniwang booster, kasama ang lap at shoulder belt","Gamit lang ang seat belt ng kotse","Nakakandong sa adult sa likod na upuan","Sa rear-facing na upuan ng sanggol"],"h1":"Hindi kasya sa maliit na bata ang seat belt lang ng kotse.","h2":"Sa New York, ang batang 4 hanggang 7 taong gulang ay dapat nakaupo sa aprubadong child restraint, karaniwang booster seat, na ginagamit kasama ang lap at shoulder belt.","p":"Tama. Kailangan ang booster o iba pang aprubadong child seat."},"ar":{"q":"في New York، كيف يجب أن يجلس طفل عمره من 4 إلى 7 سنوات في السيارة؟","o":["في مقعد أطفال معتمد، وعادةً مقعد رافع، مع حزام الحِجر وحزام الكتف","بحزام أمان السيارة فقط","في حضن شخص بالغ في المقعد الخلفي","في مقعد رضيع موجّه إلى الخلف"],"h1":"حزام السيارة وحده لا يناسب الطفل الصغير.","h2":"في New York يجب أن يجلس الطفل الذي عمره من 4 إلى 7 سنوات في مقعد أطفال معتمد، وعادةً مقعد رافع، يُستخدم مع حزام الحِجر وحزام الكتف.","p":"صحيح. يجب استخدام مقعد رافع أو مقعد أطفال معتمد آخر."},"ref":{"doc":"NY","page":48}},{"id":"ny-031","scope":"NY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New York, after a crash with $1,000 or more in damage to one person's property, how soon must you report it to the DMV?","o":["Within 24 hours","Within 30 days","Within 10 days","Within 90 days"],"h1":"Reporting to your insurance company does not count.","h2":"In New York you must file a crash report with the DMV within 10 days when someone is hurt or killed, or when one person's property has $1,000 or more in damage.","p":"Right. Report it to the DMV within 10 days."},"es":{"q":"En Nueva York, después de un choque con $1,000 o más en daños a la propiedad de una persona, ¿en qué plazo debe reportarlo al DMV?","o":["Dentro de 24 horas","Dentro de 30 días","Dentro de 10 días","Dentro de 90 días"],"h1":"Avisar a su compañía de seguros no cuenta.","h2":"En Nueva York usted debe presentar un informe de choque al DMV dentro de 10 días cuando alguien resulta herido o muere, o cuando la propiedad de una persona tiene $1,000 o más en daños.","p":"Correcto. Repórtelo al DMV dentro de 10 días."},"zh":{"q":"在 New York，发生车祸后，如果一个人的财产损失达到 $1,000 或以上，你必须在多久之内向 DMV 报告？","o":["24 小时之内","30 天之内","10 天之内","90 天之内"],"h1":"向你的保险公司报告不算数。","h2":"在 New York，如果有人受伤或死亡，或者一个人的财产损失达到 $1,000 或以上，你必须在 10 天之内向 DMV 提交车祸报告。","p":"对。10 天之内向 DMV 报告。"},"vi":{"q":"Ở New York, sau một vụ tai nạn làm hư hại tài sản của một người từ $1,000 trở lên, bạn phải báo cho DMV trong bao lâu?","o":["Trong vòng 24 giờ","Trong vòng 30 ngày","Trong vòng 10 ngày","Trong vòng 90 ngày"],"h1":"Báo cho công ty bảo hiểm của bạn thì không tính.","h2":"Ở New York, bạn phải nộp báo cáo tai nạn cho DMV trong vòng 10 ngày khi có người bị thương hoặc tử vong, hoặc khi tài sản của một người bị hư hại từ $1,000 trở lên.","p":"Đúng. Báo cho DMV trong vòng 10 ngày."},"tl":{"q":"Sa New York, pagkatapos ng banggaan na may $1,000 o higit pang pinsala sa ari-arian ng isang tao, gaano kabilis mo ito dapat i-report sa DMV?","o":["Sa loob ng 24 oras","Sa loob ng 30 araw","Sa loob ng 10 araw","Sa loob ng 90 araw"],"h1":"Hindi binibilang ang pag-report sa insurance company mo.","h2":"Sa New York, dapat kang mag-file ng crash report sa DMV sa loob ng 10 araw kapag may nasaktan o namatay, o kapag ang ari-arian ng isang tao ay may $1,000 o higit pang pinsala.","p":"Tama. I-report ito sa DMV sa loob ng 10 araw."},"ar":{"q":"في New York، بعد حادث تسبّب في ضرر بقيمة $1,000 أو أكثر لممتلكات شخص واحد، خلال كم من الوقت يجب أن تبلّغ DMV؟","o":["خلال 24 ساعة","خلال 30 يومًا","خلال 10 أيام","خلال 90 يومًا"],"h1":"إبلاغ شركة التأمين لا يُحسب.","h2":"في New York يجب أن تقدّم تقرير حادث إلى DMV خلال 10 أيام إذا أُصيب أحد أو توفي، أو إذا كان الضرر في ممتلكات شخص واحد $1,000 أو أكثر.","p":"صحيح. بلّغ DMV خلال 10 أيام."},"ref":{"doc":"NY","page":77}},{"id":"ny-032","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, how many points within 24 months lead to a notice that your license will be suspended?","o":["6 or more points","11 or more points","15 or more points","20 or more points"],"h1":"It is more than 10.","h2":"In New York, if you get 11 or more points within 24 months, the DMV will tell you by mail that your license will be suspended.","p":"Right. 11 points in 24 months means a suspension."},"es":{"q":"En Nueva York, ¿cuántos puntos en 24 meses traen un aviso de que su licencia será suspendida?","o":["6 puntos o más","11 puntos o más","15 puntos o más","20 puntos o más"],"h1":"Son más de 10.","h2":"En Nueva York, si usted acumula 11 puntos o más en 24 meses, el DMV le avisará por correo que su licencia será suspendida.","p":"Correcto. 11 puntos en 24 meses traen una suspensión."},"ref":{"doc":"NY","page":22}},{"id":"ny-033","scope":"NY","cat":"licensing","sign":null,"c":2,"en":{"q":"In New York, by how many points can a DMV-approved crash prevention course (PIRP) lower your point total?","o":["1 point","2 points","Up to 4 points","All of your points"],"h1":"It helps, but it does not erase everything.","h2":"In New York, a DMV-approved crash prevention course (PIRP) can lower your point total by up to 4 points.","p":"Right. The course can take off up to 4 points."},"es":{"q":"En Nueva York, ¿cuántos puntos puede reducir de su total un curso de prevención de choques aprobado por el DMV (PIRP)?","o":["1 punto","2 puntos","Hasta 4 puntos","Todos sus puntos"],"h1":"Ayuda, pero no lo borra todo.","h2":"En Nueva York, un curso de prevención de choques aprobado por el DMV (PIRP) puede reducir su total hasta en 4 puntos.","p":"Correcto. El curso puede quitar hasta 4 puntos."},"ref":{"doc":"NY","page":15}},{"id":"ny-034","scope":"NY","cat":"licensing","sign":null,"c":0,"en":{"q":"In New York, you are 18 or older and pass your road test. How long is your new license on probation?","o":["Six months","One month","Two years","There is no probation"],"h1":"It is half a year.","h2":"In New York, a driver who is 18 or older when passing the road test is on probation for six months.","p":"Right. New adult drivers are on probation for six months."},"es":{"q":"En Nueva York, usted tiene 18 años o más y aprueba el examen de manejo. ¿Cuánto dura el período de prueba de su nueva licencia?","o":["Seis meses","Un mes","Dos años","No hay período de prueba"],"h1":"Es medio año.","h2":"En Nueva York, quien tiene 18 años o más al aprobar el examen de manejo queda en período de prueba por seis meses.","p":"Correcto. Los nuevos conductores adultos están a prueba seis meses."},"ref":{"doc":"NY","page":19}},{"id":"ny-035","scope":"NY","cat":"licensing","sign":null,"c":3,"en":{"q":"In New York, you move to a new home. How soon must you tell the DMV your new address?","o":["Within 24 hours","Within 60 days","When you renew your license","Within 10 days"],"h1":"It is less than two weeks.","h2":"In New York, you must tell the DMV your new address within 10 days, by mail or online.","p":"Right. Tell the DMV within 10 days."},"es":{"q":"En Nueva York, usted se muda a una casa nueva. ¿En qué plazo debe avisar al DMV su nueva dirección?","o":["Dentro de 24 horas","Dentro de 60 días","Cuando renueve su licencia","Dentro de 10 días"],"h1":"Es menos de dos semanas.","h2":"En Nueva York, usted debe avisar al DMV su nueva dirección dentro de 10 días, por correo o en línea.","p":"Correcto. Avise al DMV dentro de 10 días."},"ref":{"doc":"NY","page":17}},{"id":"ny-036","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, you move here from another state and become a resident. How soon must you apply for a New York license?","o":["Within 10 days","Within 30 days","Within 6 months","Only when your old license expires"],"h1":"It is about one month.","h2":"In New York, a new resident must apply for a New York driver license within 30 days of becoming a resident.","p":"Right. New residents have 30 days."},"es":{"q":"En Nueva York, usted se muda desde otro estado y se hace residente. ¿En qué plazo debe solicitar una licencia de Nueva York?","o":["Dentro de 10 días","Dentro de 30 días","Dentro de 6 meses","Solo cuando venza su licencia anterior"],"h1":"Es más o menos un mes.","h2":"En Nueva York, un nuevo residente debe solicitar una licencia de conducir de Nueva York dentro de 30 días de hacerse residente.","p":"Correcto. Los nuevos residentes tienen 30 días."},"ref":{"doc":"NY","page":18}},{"id":"ny-037","scope":"NY","cat":"licensing","sign":null,"c":2,"en":{"q":"In New York, what is the minimum liability insurance for injury to one person in a crash?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"It is more than $10,000 but much less than $100,000.","h2":"In New York, your liability insurance must cover at least $25,000 for injury to one person.","p":"Right. The minimum is $25,000 for injury to one person."},"es":{"q":"En Nueva York, ¿cuál es el seguro de responsabilidad mínimo por lesiones a una persona en un choque?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"Es más de $10,000 pero mucho menos de $100,000.","h2":"En Nueva York, su seguro de responsabilidad debe cubrir por lo menos $25,000 por lesiones a una persona.","p":"Correcto. El mínimo es $25,000 por lesiones a una persona."},"ref":{"doc":"NY","page":27}},{"id":"ny-038","scope":"NY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New York, a driver age 21 or older refuses a chemical test for the first time. What happens to the license?","o":["Nothing, if the driver is found not guilty","A warning only","A 30-day suspension","It is revoked for at least one year"],"h1":"Refusing is treated more strictly than many people think.","h2":"In New York, a first chemical test refusal by a driver age 21 or older means the license is revoked for at least one year.","p":"Right. A first refusal means at least a one-year revocation."},"es":{"q":"En Nueva York, un conductor de 21 años o más se niega por primera vez a una prueba química. ¿Qué pasa con la licencia?","o":["Nada, si lo declaran no culpable","Solo una advertencia","Una suspensión de 30 días","Se revoca por al menos un año"],"h1":"Negarse se castiga con más fuerza de lo que muchos piensan.","h2":"En Nueva York, la primera vez que un conductor de 21 años o más se niega a una prueba química, su licencia se revoca por al menos un año.","p":"Correcto. Negarse la primera vez trae una revocación de al menos un año."},"ref":{"doc":"NY","page":21}},{"id":"ny-039","scope":"NY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New York, Aggravated Driving While Intoxicated (Agg-DWI) starts at what blood alcohol level?","o":["0.18 percent","0.05 percent","0.08 percent","0.12 percent"],"h1":"It is more than twice the usual legal limit.","h2":"In New York, a blood alcohol level of 0.18 percent or more is evidence of Aggravated Driving While Intoxicated.","p":"Right. Agg-DWI starts at 0.18 percent."},"es":{"q":"En Nueva York, ¿a partir de qué nivel de alcohol en la sangre se considera Manejar en Estado de Intoxicación Agravado (Agg-DWI)?","o":["0.18 por ciento","0.05 por ciento","0.08 por ciento","0.12 por ciento"],"h1":"Es más del doble del límite legal normal.","h2":"En Nueva York, un nivel de alcohol en la sangre de 0.18 por ciento o más es prueba de Manejar en Estado de Intoxicación Agravado.","p":"Correcto. El Agg-DWI empieza en 0.18 por ciento."},"ref":{"doc":"NY","page":55}},{"id":"ny-040","scope":"NY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New York, under Leandra's Law, what can a drunk driver face if a child under 16 is in the vehicle?","o":["Only a larger fine","A felony charge","Points only","A warning letter"],"h1":"It is a much more serious crime than a traffic ticket.","h2":"Under New York's Leandra's Law, a person who drives drunk with a child under 16 in the vehicle can be charged with a felony.","p":"Right. With a child under 16 in the car, it can be a felony."},"es":{"q":"En Nueva York, según la Ley de Leandra, ¿a qué se expone un conductor ebrio si lleva en el vehículo a un niño menor de 16 años?","o":["Solo a una multa más alta","A un cargo de delito grave (felony)","Solo a puntos","A una carta de advertencia"],"h1":"Es un delito mucho más serio que una multa de tráfico.","h2":"Según la Ley de Leandra de Nueva York, quien maneja ebrio con un niño menor de 16 años en el vehículo puede ser acusado de un delito grave (felony).","p":"Correcto. Con un niño menor de 16 años en el auto, puede ser un delito grave."},"ref":{"doc":"NY","page":59}},{"id":"ny-041","scope":"NY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New York, how many points can an adult driver get for a first offense of talking on a hand-held phone while driving?","o":["No points","2 points","5 points","11 points"],"h1":"It is more than for most small violations.","h2":"In New York, a first offense for using a hand-held phone while driving can bring a fine of up to $200 and 5 points.","p":"Right. A hand-held phone can cost you 5 points."},"es":{"q":"En Nueva York, ¿cuántos puntos puede recibir un conductor adulto por una primera infracción de hablar con el teléfono en la mano mientras maneja?","o":["Ningún punto","2 puntos","5 puntos","11 puntos"],"h1":"Es más que por la mayoría de las infracciones menores.","h2":"En Nueva York, una primera infracción por usar el teléfono en la mano mientras maneja puede traer una multa de hasta $200 y 5 puntos.","p":"Correcto. El teléfono en la mano le puede costar 5 puntos."},"ref":{"doc":"NY","page":52}},{"id":"ny-042","scope":"NY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New York, a passenger under 16 is not buckled in. What can happen to the driver?","o":["Nothing, the passenger gets the ticket","Only a warning","A $500 fine and a suspension","A fine of $25 to $100 and 3 points"],"h1":"The driver is responsible for young passengers.","h2":"In New York, the driver can be fined $25 to $100 and get 3 points for each passenger under 16 who is not properly buckled in.","p":"Right. The driver can get a fine and 3 points."},"es":{"q":"En Nueva York, un pasajero menor de 16 años no lleva puesto el cinturón. ¿Qué le puede pasar al conductor?","o":["Nada, la multa es para el pasajero","Solo una advertencia","Una multa de $500 y una suspensión","Una multa de $25 a $100 y 3 puntos"],"h1":"El conductor es responsable de los pasajeros jóvenes.","h2":"En Nueva York, el conductor puede recibir una multa de $25 a $100 y 3 puntos por cada pasajero menor de 16 años que no esté bien abrochado.","p":"Correcto. El conductor puede recibir una multa y 3 puntos."},"ref":{"doc":"NY","page":48}},{"id":"ny-043","scope":"NY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New York, how long must a young child ride in a rear-facing car seat?","o":["Until age 2, or until the child reaches the seat's weight or height limit","Until age 6 months","Until age 1, no matter what","Until the child can walk"],"h1":"Think of a toddler's second birthday.","h2":"In New York, a child must ride rear-facing until age 2, or until the child reaches the highest weight or height the car seat allows.","p":"Right. Rear-facing until age 2 or the seat's limit."},"es":{"q":"En Nueva York, ¿hasta cuándo debe viajar un niño pequeño en un asiento de seguridad mirando hacia atrás?","o":["Hasta los 2 años, o hasta que alcance el límite de peso o altura del asiento","Hasta los 6 meses","Hasta 1 año, sin importar nada más","Hasta que el niño pueda caminar"],"h1":"Piense en el segundo cumpleaños de un niño pequeño.","h2":"En Nueva York, un niño debe viajar mirando hacia atrás hasta los 2 años, o hasta que alcance el peso o la altura máxima que permite el asiento.","p":"Correcto. Mirando hacia atrás hasta los 2 años o hasta el límite del asiento."},"ref":{"doc":"NY","page":48}},{"id":"ny-044","scope":"NY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New York, when may you use tires with metal studs?","o":["All year","Only from October 16 through April 30","Only in December, January and February","Never"],"h1":"Think of the cold part of the year, from fall to spring.","h2":"In New York, tires with metal studs may be used only from October 16 through April 30.","p":"Right. Studded tires are allowed from October 16 to April 30."},"es":{"q":"En Nueva York, ¿cuándo puede usar llantas con clavos de metal?","o":["Todo el año","Solo del 16 de octubre al 30 de abril","Solo en diciembre, enero y febrero","Nunca"],"h1":"Piense en la parte fría del año, del otoño a la primavera.","h2":"En Nueva York, las llantas con clavos de metal solo se pueden usar del 16 de octubre al 30 de abril.","p":"Correcto. Las llantas con clavos se permiten del 16 de octubre al 30 de abril."},"ref":{"doc":"NY","page":64}},{"id":"ny-045","scope":"NY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New York, which bicycle riders must wear an approved helmet by state law?","o":["Only riders under age 5","All riders of every age","Riders and passengers ages 1 to 13","Only riders on highways"],"h1":"State law covers children, not adults.","h2":"In New York, bicycle riders and passengers ages 1 to 13 must wear an approved helmet.","p":"Right. Ages 1 to 13 must wear a helmet."},"es":{"q":"En Nueva York, ¿qué ciclistas deben usar un casco aprobado según la ley estatal?","o":["Solo los menores de 5 años","Todos, de cualquier edad","Ciclistas y pasajeros de 1 a 13 años","Solo los que van por autopistas"],"h1":"La ley estatal cubre a los niños, no a los adultos.","h2":"En Nueva York, los ciclistas y sus pasajeros de 1 a 13 años deben usar un casco aprobado.","p":"Correcto. De 1 a 13 años deben usar casco."},"ref":{"doc":"NY","page":69}},{"id":"ny-046","scope":"NY","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New York, on a two-way road, an ambulance with its siren on is coming toward you in the opposite lane. What must you do?","o":["Keep driving, it is not in your lane","Speed up to clear the way","Stop right where you are, in your lane","Pull over to the right edge and stop"],"h1":"The rule is the same no matter which direction it comes from.","h2":"In New York, you must pull over to the right edge and stop for an emergency vehicle, even when it is coming toward you in the opposite lane of a two-way road.","p":"Right. Pull over and stop, even for the opposite lane."},"es":{"q":"En Nueva York, en una calle de doble sentido, una ambulancia con la sirena encendida viene hacia usted por el carril contrario. ¿Qué debe hacer?","o":["Seguir manejando, no está en su carril","Acelerar para abrir paso","Detenerse donde está, en su carril","Orillarse a la derecha y detenerse"],"h1":"La regla es la misma venga de donde venga.","h2":"En Nueva York, usted debe orillarse a la derecha y detenerse ante un vehículo de emergencia, aunque venga hacia usted por el carril contrario de una calle de doble sentido.","p":"Correcto. Oríllese y deténgase, aunque venga por el carril contrario."},"ref":{"doc":"NY","page":35}},{"id":"ny-047","scope":"NY","cat":"signals","sign":null,"c":0,"en":{"q":"In New York, a personal car shows a flashing blue light. Who is usually driving it?","o":["A volunteer firefighter answering an alarm","A police officer making a traffic stop","A snowplow driver","A school bus driver"],"h1":"Green lights are used by volunteer ambulance members.","h2":"In New York, a flashing blue light on a personal car usually means a volunteer firefighter answering an alarm; it is not an emergency vehicle, but you should let it pass if you safely can.","p":"Right. Blue light means a volunteer firefighter."},"es":{"q":"En Nueva York, un auto particular lleva una luz azul intermitente. ¿Quién lo maneja normalmente?","o":["Un bombero voluntario que acude a una alarma","Un policía que detiene a un conductor","El conductor de un quitanieves","El conductor de un autobús escolar"],"h1":"Las luces verdes las usan los voluntarios de ambulancia.","h2":"En Nueva York, una luz azul intermitente en un auto particular suele indicar un bombero voluntario que acude a una alarma; no es un vehículo de emergencia, pero debe dejarlo pasar si puede hacerlo con seguridad.","p":"Correcto. La luz azul indica un bombero voluntario."},"ref":{"doc":"NY","page":35}},{"id":"ny-048","scope":"NY","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New York, you may not make a U-turn where other drivers cannot see your car from how far away?","o":["100 feet","500 feet","50 feet","1 mile"],"h1":"It is a long distance, more than the length of a football field.","h2":"In New York, you may not make a U-turn near a hilltop, a curve or any place where other drivers cannot see your car from 500 feet away in either direction.","p":"Right. Drivers must be able to see you from 500 feet."},"es":{"q":"En Nueva York, no puede dar una vuelta en U donde otros conductores no puedan ver su auto desde ¿qué distancia?","o":["100 pies","500 pies","50 pies","1 milla"],"h1":"Es una distancia larga, más que el largo de un campo de fútbol americano.","h2":"En Nueva York, no puede dar una vuelta en U cerca de la cima de una colina, en una curva ni en ningún lugar donde otros conductores no puedan ver su auto desde 500 pies en cualquier dirección.","p":"Correcto. Los demás deben poder verlo desde 500 pies."},"ref":{"doc":"NY","page":37}},{"id":"ny-049","scope":"NY","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New York, you are about to pass a person riding a horse along the road. What must you not do?","o":["Slow down","Leave extra space","Sound your horn","Pass when it is safe"],"h1":"A loud noise can scare the horse.","h2":"In New York, it is against the law to sound your horn when you come near or pass a horse.","p":"Right. Never honk near a horse."},"es":{"q":"En Nueva York, está por pasar a una persona que va a caballo por la calle. ¿Qué no debe hacer?","o":["Reducir la velocidad","Dejar más espacio","Tocar la bocina","Pasar cuando sea seguro"],"h1":"Un ruido fuerte puede asustar al caballo.","h2":"En Nueva York, es ilegal tocar la bocina cuando se acerca a un caballo o lo pasa.","p":"Correcto. Nunca toque la bocina cerca de un caballo."},"ref":{"doc":"NY","page":76}},{"id":"ny-050","scope":"NY","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New York, how close to a fire station driveway may you park on the same side of the street?","o":["5 feet","10 feet","15 feet","No closer than 20 feet"],"h1":"Across the street, the distance is 75 feet.","h2":"In New York, you may not park or stand within 20 feet of a fire station driveway on the same side of the street, or within 75 feet on the other side.","p":"Right. Stay at least 20 feet from a fire station driveway."},"es":{"q":"En Nueva York, ¿a qué distancia de la entrada de una estación de bomberos puede estacionarse del mismo lado de la calle?","o":["5 pies","10 pies","15 pies","No más cerca de 20 pies"],"h1":"Del otro lado de la calle, la distancia es de 75 pies.","h2":"En Nueva York, no puede estacionarse ni detenerse a menos de 20 pies de la entrada de una estación de bomberos del mismo lado de la calle, ni a menos de 75 pies del otro lado.","p":"Correcto. Manténgase por lo menos a 20 pies de la entrada de los bomberos."},"ref":{"doc":"NY","page":43}},{"id":"oh-001","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, what is the youngest age to get a temporary instruction permit?","o":["14 years old","15 years old","15 and a half years old","16 years old"],"h1":"It is half a year before the probationary license age.","h2":"In Ohio you can get a temporary instruction permit at 15 and a half years old.","p":"Right. The Ohio permit starts at 15 and a half."},"es":{"q":"En Ohio, ¿cuál es la edad mínima para obtener un permiso temporal de aprendizaje?","o":["14 años","15 años","15 años y medio","16 años"],"h1":"Es medio año antes de la edad para la licencia probatoria.","h2":"En Ohio usted puede obtener un permiso temporal de aprendizaje a los 15 años y medio.","p":"Correcto. El permiso en Ohio empieza a los 15 años y medio."},"zh":{"q":"在 Ohio，最小几岁可以拿到临时学习驾照（temporary instruction permit）？","o":["14 岁","15 岁","15 岁半","16 岁"],"h1":"它比拿试用驾照的年龄早半年。","h2":"在 Ohio，你 15 岁半就可以拿到临时学习驾照。","p":"对。Ohio 的学习驾照从 15 岁半开始。"},"vi":{"q":"Ở Ohio, tuổi nhỏ nhất để lấy giấy phép tập lái tạm thời (temporary instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","15 tuổi rưỡi","16 tuổi"],"h1":"Đó là nửa năm trước tuổi lấy bằng lái thử thách.","h2":"Ở Ohio, bạn có thể lấy giấy phép tập lái tạm thời khi 15 tuổi rưỡi.","p":"Đúng. Ở Ohio, giấy phép tập lái bắt đầu từ 15 tuổi rưỡi."},"tl":{"q":"Sa Ohio, ano ang pinakabatang edad para makakuha ng temporary instruction permit?","o":["14 taong gulang","15 taong gulang","15 at kalahating taong gulang","16 taong gulang"],"h1":"Kalahating taon ito bago ang edad para sa probationary license.","h2":"Sa Ohio, puwede kang kumuha ng temporary instruction permit sa edad na 15 at kalahati.","p":"Tama. Nagsisimula ang permit sa Ohio sa 15 at kalahati."},"ar":{"q":"في Ohio، ما أصغر عمر للحصول على تصريح التعلّم المؤقت (temporary instruction permit)؟","o":["14 سنة","15 سنة","15 سنة ونصف","16 سنة"],"h1":"هو نصف سنة قبل عمر الرخصة التجريبية.","h2":"في Ohio يمكنك الحصول على تصريح التعلّم المؤقت في عمر 15 سنة ونصف.","p":"صحيح. في Ohio يبدأ التصريح في عمر 15 سنة ونصف."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-002","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, how long is a temporary instruction permit valid?","o":["One year","Six months","Two years","Four years"],"h1":"It lasts long enough to cover the holding period twice.","h2":"In Ohio a temporary instruction permit is valid for one year.","p":"Right. The permit is valid for one year."},"es":{"q":"En Ohio, ¿por cuánto tiempo es válido un permiso temporal de aprendizaje?","o":["Un año","Seis meses","Dos años","Cuatro años"],"h1":"Dura lo suficiente para cubrir dos veces el período de espera.","h2":"En Ohio un permiso temporal de aprendizaje es válido por un año.","p":"Correcto. El permiso es válido por un año."},"zh":{"q":"在 Ohio，临时学习驾照有效期多久？","o":["一年","六个月","两年","四年"],"h1":"它够长，可以覆盖两次必须持有的时间。","h2":"在 Ohio，临时学习驾照有效期是一年。","p":"对。学习驾照有效一年。"},"vi":{"q":"Ở Ohio, giấy phép tập lái tạm thời (temporary instruction permit) có giá trị trong bao lâu?","o":["Một năm","Sáu tháng","Hai năm","Bốn năm"],"h1":"Nó đủ dài bằng hai lần thời gian phải giữ giấy phép.","h2":"Ở Ohio, giấy phép tập lái tạm thời có giá trị trong một năm.","p":"Đúng. Giấy phép có giá trị một năm."},"tl":{"q":"Sa Ohio, gaano katagal valid ang temporary instruction permit?","o":["Isang taon","Anim na buwan","Dalawang taon","Apat na taon"],"h1":"Sapat ang haba nito para dalawang beses ang panahon ng paghawak ng permit.","h2":"Sa Ohio, valid ang temporary instruction permit nang isang taon.","p":"Tama. Valid ang permit nang isang taon."},"ar":{"q":"في Ohio، ما مدة صلاحية تصريح التعلّم المؤقت (temporary instruction permit)؟","o":["سنة واحدة","ستة أشهر","سنتان","أربع سنوات"],"h1":"مدته طويلة بما يكفي لتغطية فترة الاحتفاظ بالتصريح مرتين.","h2":"في Ohio يكون تصريح التعلّم المؤقت صالحًا لمدة سنة واحدة.","p":"صحيح. التصريح صالح لمدة سنة واحدة."},"ref":{"doc":"OH","page":null}},{"id":"oh-003","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, how long must a teen hold a temporary instruction permit before getting a probationary license?","o":["One month","At least six months","At least one year","At least two years"],"h1":"It is half a year.","h2":"In Ohio a teen must hold a temporary instruction permit for at least six months before getting a probationary license.","p":"Right. Hold the permit at least six months."},"es":{"q":"En Ohio, ¿cuánto tiempo debe tener un joven el permiso temporal antes de obtener la licencia probatoria?","o":["Un mes","Por lo menos seis meses","Por lo menos un año","Por lo menos dos años"],"h1":"Es medio año.","h2":"En Ohio un joven debe tener el permiso temporal de aprendizaje por lo menos seis meses antes de obtener la licencia probatoria.","p":"Correcto. Debe tener el permiso por lo menos seis meses."},"zh":{"q":"在 Ohio，青少年拿试用驾照（probationary license）前，必须持有临时学习驾照多久？","o":["一个月","至少六个月","至少一年","至少两年"],"h1":"它是半年。","h2":"在 Ohio，青少年必须持有临时学习驾照至少六个月，才能拿试用驾照。","p":"对。持有学习驾照至少六个月。"},"vi":{"q":"Ở Ohio, thiếu niên phải giữ giấy phép tập lái tạm thời (temporary instruction permit) bao lâu trước khi lấy bằng lái thử thách (probationary license)?","o":["Một tháng","Ít nhất sáu tháng","Ít nhất một năm","Ít nhất hai năm"],"h1":"Đó là nửa năm.","h2":"Ở Ohio, thiếu niên phải giữ giấy phép tập lái tạm thời ít nhất sáu tháng trước khi lấy bằng lái thử thách.","p":"Đúng. Giữ giấy phép ít nhất sáu tháng."},"tl":{"q":"Sa Ohio, gaano katagal dapat hawak ng isang teen ang temporary instruction permit bago makakuha ng probationary license?","o":["Isang buwan","Hindi bababa sa anim na buwan","Hindi bababa sa isang taon","Hindi bababa sa dalawang taon"],"h1":"Kalahating taon ito.","h2":"Sa Ohio, dapat hawak ng teen ang temporary instruction permit nang hindi bababa sa anim na buwan bago makakuha ng probationary license.","p":"Tama. Hawakan ang permit nang hindi bababa sa anim na buwan."},"ar":{"q":"في Ohio، كم مدة يجب أن يحتفظ المراهق بـتصريح التعلّم المؤقت (temporary instruction permit) قبل الحصول على الرخصة التجريبية (probationary license)؟","o":["شهر واحد","ستة أشهر على الأقل","سنة واحدة على الأقل","سنتان على الأقل"],"h1":"هي نصف سنة.","h2":"في Ohio يجب أن يحتفظ المراهق بتصريح التعلّم المؤقت ستة أشهر على الأقل قبل الحصول على الرخصة التجريبية.","p":"صحيح. احتفظ بالتصريح ستة أشهر على الأقل."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-004","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, what is the youngest age to get a probationary driver's license?","o":["15","17","18","16"],"h1":"It is six months after the earliest permit age.","h2":"In Ohio you can get a probationary driver's license at 16, after holding a permit for at least six months.","p":"Right. The probationary license starts at 16."},"es":{"q":"En Ohio, ¿cuál es la edad mínima para obtener una licencia de conducir probatoria?","o":["15","17","18","16"],"h1":"Es seis meses después de la edad mínima para el permiso.","h2":"En Ohio usted puede obtener la licencia probatoria a los 16 años, después de tener el permiso por lo menos seis meses.","p":"Correcto. La licencia probatoria empieza a los 16."},"zh":{"q":"在 Ohio，最小几岁可以拿到试用驾照（probationary driver's license）？","o":["15","17","18","16"],"h1":"它比最早拿学习驾照的年龄晚六个月。","h2":"在 Ohio，持有学习驾照至少六个月以后，你 16 岁就可以拿到试用驾照。","p":"对。试用驾照从 16 岁开始。"},"vi":{"q":"Ở Ohio, tuổi nhỏ nhất để lấy bằng lái thử thách (probationary license) là bao nhiêu?","o":["15","17","18","16"],"h1":"Đó là sáu tháng sau tuổi sớm nhất để lấy giấy phép tập lái.","h2":"Ở Ohio, bạn có thể lấy bằng lái thử thách khi 16 tuổi, sau khi giữ giấy phép tập lái ít nhất sáu tháng.","p":"Đúng. Bằng lái thử thách bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Ohio, ano ang pinakabatang edad para makakuha ng probationary driver's license?","o":["15","17","18","16"],"h1":"Anim na buwan ito pagkatapos ng pinakamaagang edad para sa permit.","h2":"Sa Ohio, puwede kang kumuha ng probationary driver's license sa edad na 16, pagkatapos hawakan ang permit nang hindi bababa sa anim na buwan.","p":"Tama. Nagsisimula ang probationary license sa 16."},"ar":{"q":"في Ohio، ما أصغر عمر للحصول على الرخصة التجريبية (probationary license)؟","o":["15","17","18","16"],"h1":"هو بعد ستة أشهر من أصغر عمر للتصريح.","h2":"في Ohio يمكنك الحصول على الرخصة التجريبية في عمر 16 سنة، بعد الاحتفاظ بالتصريح ستة أشهر على الأقل.","p":"صحيح. تبدأ الرخصة التجريبية في عمر 16 سنة."},"ref":{"doc":"OH","page":null}},{"id":"oh-005","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, how many hours of supervised driving must a teen complete before a probationary license?","o":["20 hours","30 hours","50 hours","100 hours"],"h1":"It is half of one hundred.","h2":"In Ohio a teen must complete 50 hours of supervised driving before getting a probationary license.","p":"Right. 50 supervised hours."},"es":{"q":"En Ohio, ¿cuántas horas de manejo supervisado debe completar un joven antes de la licencia probatoria?","o":["20 horas","30 horas","50 horas","100 horas"],"h1":"Es la mitad de cien.","h2":"En Ohio un joven debe completar 50 horas de manejo supervisado antes de obtener la licencia probatoria.","p":"Correcto. 50 horas supervisadas."},"zh":{"q":"在 Ohio，青少年拿试用驾照前，必须完成多少小时有人监督的驾驶？","o":["20 小时","30 小时","50 小时","100 小时"],"h1":"它是一百的一半。","h2":"在 Ohio，青少年拿试用驾照前必须完成 50 小时有人监督的驾驶。","p":"对。50 小时有人监督的驾驶。"},"vi":{"q":"Ở Ohio, thiếu niên phải lái xe có người giám sát bao nhiêu giờ trước khi lấy bằng lái thử thách (probationary license)?","o":["20 giờ","30 giờ","50 giờ","100 giờ"],"h1":"Đó là một nửa của một trăm.","h2":"Ở Ohio, thiếu niên phải lái xe có người giám sát 50 giờ trước khi lấy bằng lái thử thách.","p":"Đúng. 50 giờ có người giám sát."},"tl":{"q":"Sa Ohio, ilang oras ng supervised driving ang dapat tapusin ng teen bago ang probationary license?","o":["20 oras","30 oras","50 oras","100 oras"],"h1":"Kalahati ito ng isang daan.","h2":"Sa Ohio, dapat tapusin ng teen ang 50 oras ng supervised driving bago makakuha ng probationary license.","p":"Tama. 50 oras na may bantay."},"ar":{"q":"في Ohio، كم ساعة من القيادة تحت الإشراف يجب أن يكملها المراهق قبل الرخصة التجريبية (probationary license)؟","o":["20 ساعة","30 ساعة","50 ساعة","100 ساعة"],"h1":"هو نصف المئة.","h2":"في Ohio يجب أن يكمل المراهق 50 ساعة من القيادة تحت الإشراف قبل الحصول على الرخصة التجريبية.","p":"صحيح. 50 ساعة تحت الإشراف."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-006","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, how many of the supervised driving hours must be at night?","o":["10 hours","5 hours","15 hours","25 hours"],"h1":"It is one fifth of the total.","h2":"In Ohio 10 of the 50 supervised driving hours must be at night.","p":"Right. 10 hours at night."},"es":{"q":"En Ohio, ¿cuántas de las horas de manejo supervisado deben ser de noche?","o":["10 horas","5 horas","15 horas","25 horas"],"h1":"Es la quinta parte del total.","h2":"En Ohio 10 de las 50 horas de manejo supervisado deben ser de noche.","p":"Correcto. 10 horas de noche."},"zh":{"q":"在 Ohio，有人监督的驾驶时间里，有多少小时必须在晚上？","o":["10 小时","5 小时","15 小时","25 小时"],"h1":"它是全部时间的五分之一。","h2":"在 Ohio，50 小时有人监督的驾驶里，10 小时必须在晚上。","p":"对。晚上 10 小时。"},"vi":{"q":"Ở Ohio, bao nhiêu giờ trong số giờ lái xe có người giám sát phải là vào ban đêm?","o":["10 giờ","5 giờ","15 giờ","25 giờ"],"h1":"Đó là một phần năm của tổng số giờ.","h2":"Ở Ohio, 10 trong số 50 giờ lái xe có người giám sát phải là vào ban đêm.","p":"Đúng. 10 giờ vào ban đêm."},"tl":{"q":"Sa Ohio, ilan sa mga oras ng supervised driving ang dapat gawin sa gabi?","o":["10 oras","5 oras","15 oras","25 oras"],"h1":"Isang-ikalima ito ng kabuuan.","h2":"Sa Ohio, 10 sa 50 oras ng supervised driving ang dapat gawin sa gabi.","p":"Tama. 10 oras sa gabi."},"ar":{"q":"في Ohio، كم ساعة من ساعات القيادة تحت الإشراف يجب أن تكون في الليل؟","o":["10 ساعات","5 ساعات","15 ساعة","25 ساعة"],"h1":"هي خُمس المجموع.","h2":"في Ohio يجب أن تكون 10 من أصل 50 ساعة من القيادة تحت الإشراف في الليل.","p":"صحيح. 10 ساعات في الليل."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-007","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, who certifies a teen's supervised driving hours?","o":["The driving test examiner","A parent or guardian, by signing an affidavit","A police officer","The teen alone"],"h1":"It is the adult responsible for the teen.","h2":"In Ohio a parent or guardian signs an affidavit that the teen completed the supervised hours, and lying on it can bring a fine or jail.","p":"Right. A parent or guardian signs for the hours."},"es":{"q":"En Ohio, ¿quién certifica las horas de manejo supervisado de un joven?","o":["El examinador de la prueba de manejo","Su padre, madre o tutor, firmando una declaración jurada","Un policía","El joven solo"],"h1":"Es el adulto responsable del joven.","h2":"En Ohio el padre, la madre o el tutor firma una declaración jurada de que el joven completó las horas supervisadas, y mentir en ella puede causar una multa o cárcel.","p":"Correcto. El padre, la madre o el tutor firma por las horas."},"zh":{"q":"在 Ohio，谁证明青少年有人监督的驾驶时间？","o":["路考考官","父母或监护人，签一份宣誓书（affidavit）","警察","青少年自己"],"h1":"是对青少年负责的成年人。","h2":"在 Ohio，父母或监护人签一份宣誓书（affidavit），证明青少年完成了有人监督的驾驶时间，在上面说谎可能被罚款或坐牢。","p":"对。父母或监护人为练习时间签字。"},"vi":{"q":"Ở Ohio, ai xác nhận số giờ lái xe có người giám sát của thiếu niên?","o":["Giám khảo thi lái xe","Cha mẹ hoặc người giám hộ, bằng cách ký một bản cam kết (affidavit)","Một cảnh sát","Chỉ một mình thiếu niên"],"h1":"Đó là người lớn chịu trách nhiệm về thiếu niên.","h2":"Ở Ohio, cha mẹ hoặc người giám hộ ký một bản cam kết (affidavit) rằng thiếu niên đã lái đủ số giờ có người giám sát, và khai gian có thể bị phạt tiền hoặc ngồi tù.","p":"Đúng. Cha mẹ hoặc người giám hộ ký xác nhận số giờ."},"tl":{"q":"Sa Ohio, sino ang nagpapatunay sa mga oras ng supervised driving ng teen?","o":["Ang examiner ng driving test","Isang magulang o guardian, sa pagpirma ng affidavit","Isang pulis","Ang teen lang"],"h1":"Ito ang adultong responsable sa teen.","h2":"Sa Ohio, pumipirma ang magulang o guardian ng affidavit na natapos ng teen ang mga oras na may bantay, at ang pagsisinungaling dito ay puwedeng magdulot ng multa o kulong.","p":"Tama. Magulang o guardian ang pumipirma para sa mga oras."},"ar":{"q":"في Ohio، من يؤكد ساعات القيادة تحت الإشراف التي أكملها المراهق؟","o":["فاحص اختبار القيادة","أحد الوالدين أو الوصي، بتوقيع إقرار رسمي (affidavit)","شرطي","المراهق وحده"],"h1":"هو الشخص البالغ المسؤول عن المراهق.","h2":"في Ohio يوقّع أحد الوالدين أو الوصي إقرارًا رسميًا (affidavit) بأن المراهق أكمل الساعات تحت الإشراف، والكذب فيه قد يؤدي إلى غرامة أو سجن.","p":"صحيح. أحد الوالدين أو الوصي يوقّع على الساعات."},"ref":{"doc":"OH","page":null}},{"id":"oh-008","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, during the first 12 months with a probationary license, when may a teen not drive unless a parent or guardian is along?","o":["9 p.m. to 6 a.m.","11 p.m. to 5 a.m.","1 a.m. to 5 a.m.","Midnight to 6 a.m."],"h1":"It starts at midnight.","h2":"In Ohio, during the first 12 months, a probationary driver may not drive from midnight to 6 a.m. unless a parent or guardian is in the car, with a few exceptions such as work or school.","p":"Right. Midnight to 6 a.m. in the first year."},"es":{"q":"En Ohio, durante los primeros 12 meses con licencia probatoria, ¿en qué horario no puede manejar un joven sin uno de sus padres o tutor?","o":["De 9 p.m. a 6 a.m.","De 11 p.m. a 5 a.m.","De 1 a.m. a 5 a.m.","De medianoche a 6 a.m."],"h1":"Empieza a la medianoche.","h2":"En Ohio, durante los primeros 12 meses, un conductor con licencia probatoria no puede manejar de medianoche a 6 a.m. sin su padre, madre o tutor en el carro, con algunas excepciones como el trabajo o la escuela.","p":"Correcto. De medianoche a 6 a.m. el primer año."},"zh":{"q":"在 Ohio，持试用驾照的前 12 个月，除非父母或监护人在车上，青少年什么时候不能开车？","o":["晚上 9 点到早上 6 点","晚上 11 点到早上 5 点","凌晨 1 点到早上 5 点","午夜到早上 6 点"],"h1":"它从午夜开始。","h2":"在 Ohio，前 12 个月里，持试用驾照的司机从午夜到早上 6 点不能开车，除非父母或监护人在车上，也有一些例外，比如上班或上学。","p":"对。第一年是午夜到早上 6 点。"},"vi":{"q":"Ở Ohio, trong 12 tháng đầu có bằng lái thử thách (probationary license), thiếu niên không được lái xe vào giờ nào nếu không có cha mẹ hoặc người giám hộ đi cùng?","o":["9 giờ tối đến 6 giờ sáng","11 giờ tối đến 5 giờ sáng","1 giờ sáng đến 5 giờ sáng","Nửa đêm đến 6 giờ sáng"],"h1":"Nó bắt đầu lúc nửa đêm.","h2":"Ở Ohio, trong 12 tháng đầu, người có bằng lái thử thách không được lái xe từ nửa đêm đến 6 giờ sáng nếu không có cha mẹ hoặc người giám hộ trong xe, trừ một vài trường hợp như đi làm hoặc đi học.","p":"Đúng. Từ nửa đêm đến 6 giờ sáng trong năm đầu tiên."},"tl":{"q":"Sa Ohio, sa unang 12 buwan na may probationary license, kailan hindi puwedeng magmaneho ang teen kung walang kasamang magulang o guardian?","o":["9 p.m. hanggang 6 a.m.","11 p.m. hanggang 5 a.m.","1 a.m. hanggang 5 a.m.","Hatinggabi hanggang 6 a.m."],"h1":"Nagsisimula ito sa hatinggabi.","h2":"Sa Ohio, sa unang 12 buwan, hindi puwedeng magmaneho ang probationary driver mula hatinggabi hanggang 6 a.m. kung walang magulang o guardian sa kotse, maliban sa ilang kaso tulad ng trabaho o paaralan.","p":"Tama. Hatinggabi hanggang 6 a.m. sa unang taon."},"ar":{"q":"في Ohio، خلال أول 12 شهرًا مع الرخصة التجريبية (probationary license)، متى لا يجوز للمراهق القيادة إلا إذا كان معه أحد الوالدين أو الوصي؟","o":["من 9 مساءً إلى 6 صباحًا","من 11 مساءً إلى 5 صباحًا","من 1 صباحًا إلى 5 صباحًا","من منتصف الليل إلى 6 صباحًا"],"h1":"تبدأ عند منتصف الليل.","h2":"في Ohio، خلال أول 12 شهرًا، لا يجوز لصاحب الرخصة التجريبية القيادة من منتصف الليل إلى 6 صباحًا إلا إذا كان أحد الوالدين أو الوصي في السيارة، مع بعض الاستثناءات مثل العمل أو المدرسة.","p":"صحيح. من منتصف الليل إلى 6 صباحًا في السنة الأولى."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-009","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, after holding a probationary license for 12 months, which hours are still restricted unless a parent or guardian is along?","o":["Midnight to 6 a.m.","11 p.m. to 5 a.m.","1 a.m. to 5 a.m.","No hours are restricted"],"h1":"The window becomes shorter at both ends.","h2":"In Ohio, after 12 months with a probationary license, a teen may not drive from 1 a.m. to 5 a.m. unless a parent or guardian is along.","p":"Right. After a year the limit is 1 a.m. to 5 a.m."},"es":{"q":"En Ohio, después de 12 meses con licencia probatoria, ¿qué horario sigue restringido sin uno de sus padres o tutor?","o":["De medianoche a 6 a.m.","De 11 p.m. a 5 a.m.","De 1 a.m. a 5 a.m.","Ningún horario"],"h1":"El horario se acorta por los dos lados.","h2":"En Ohio, después de 12 meses con licencia probatoria, un joven no puede manejar de 1 a.m. a 5 a.m. sin su padre, madre o tutor.","p":"Correcto. Después de un año el límite es de 1 a.m. a 5 a.m."},"zh":{"q":"在 Ohio，持试用驾照 12 个月以后，除非父母或监护人在车上，哪些时间仍然有限制？","o":["午夜到早上 6 点","晚上 11 点到早上 5 点","凌晨 1 点到早上 5 点","没有时间限制"],"h1":"限制的时间段两头都变短了。","h2":"在 Ohio，持试用驾照 12 个月以后，青少年从凌晨 1 点到早上 5 点不能开车，除非父母或监护人在车上。","p":"对。一年以后，限制是凌晨 1 点到早上 5 点。"},"vi":{"q":"Ở Ohio, sau khi giữ bằng lái thử thách (probationary license) 12 tháng, những giờ nào vẫn bị hạn chế nếu không có cha mẹ hoặc người giám hộ đi cùng?","o":["Nửa đêm đến 6 giờ sáng","11 giờ tối đến 5 giờ sáng","1 giờ sáng đến 5 giờ sáng","Không có giờ nào bị hạn chế"],"h1":"Khoảng thời gian ngắn lại ở cả hai đầu.","h2":"Ở Ohio, sau 12 tháng có bằng lái thử thách, thiếu niên không được lái xe từ 1 giờ sáng đến 5 giờ sáng nếu không có cha mẹ hoặc người giám hộ đi cùng.","p":"Đúng. Sau một năm, giới hạn là từ 1 giờ sáng đến 5 giờ sáng."},"tl":{"q":"Sa Ohio, pagkatapos hawakan ang probationary license nang 12 buwan, aling mga oras ang bawal pa rin kung walang kasamang magulang o guardian?","o":["Hatinggabi hanggang 6 a.m.","11 p.m. hanggang 5 a.m.","1 a.m. hanggang 5 a.m.","Walang bawal na oras"],"h1":"Umiikli ang oras sa magkabilang dulo.","h2":"Sa Ohio, pagkatapos ng 12 buwan na may probationary license, hindi puwedeng magmaneho ang teen mula 1 a.m. hanggang 5 a.m. kung walang kasamang magulang o guardian.","p":"Tama. Pagkatapos ng isang taon, ang limit ay 1 a.m. hanggang 5 a.m."},"ar":{"q":"في Ohio، بعد الاحتفاظ بـالرخصة التجريبية (probationary license) لمدة 12 شهرًا، ما الساعات التي تبقى ممنوعة إلا إذا كان معه أحد الوالدين أو الوصي؟","o":["من منتصف الليل إلى 6 صباحًا","من 11 مساءً إلى 5 صباحًا","من 1 صباحًا إلى 5 صباحًا","لا توجد ساعات ممنوعة"],"h1":"تصبح الفترة أقصر من البداية والنهاية.","h2":"في Ohio، بعد 12 شهرًا مع الرخصة التجريبية، لا يجوز للمراهق القيادة من 1 صباحًا إلى 5 صباحًا إلا إذا كان معه أحد الوالدين أو الوصي.","p":"صحيح. بعد سنة يصبح المنع من 1 صباحًا إلى 5 صباحًا."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-010","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, what must a probationary driver carry to drive to or from work during restricted night hours?","o":["Written documentation from the employer","A pay stub from last year","A note from a friend","Nothing; work is always allowed"],"h1":"It is a paper from the job.","h2":"In Ohio a probationary driver going to or from work during restricted hours must have written documentation from the employer with them.","p":"Right. Carry the paper from your employer."},"es":{"q":"En Ohio, ¿qué debe llevar un conductor con licencia probatoria para ir o volver del trabajo en el horario nocturno restringido?","o":["Un documento escrito del empleador","Un recibo de pago del año pasado","Una nota de un amigo","Nada; ir al trabajo siempre está permitido"],"h1":"Es un papel del trabajo.","h2":"En Ohio un conductor con licencia probatoria que va o vuelve del trabajo en el horario restringido debe llevar consigo un documento escrito del empleador.","p":"Correcto. Lleve el documento de su empleador."},"zh":{"q":"在 Ohio，持试用驾照的司机在限制的夜间时间开车上下班，必须带什么？","o":["雇主写的书面证明","去年的工资单","朋友写的字条","什么都不用带，上班一直都可以"],"h1":"它是工作单位给的一张纸。","h2":"在 Ohio，持试用驾照的司机在限制的时间开车上下班，必须随身带着雇主写的书面证明。","p":"对。带上雇主给的证明。"},"vi":{"q":"Ở Ohio, người có bằng lái thử thách phải mang theo gì để lái xe đi làm hoặc đi làm về trong giờ ban đêm bị hạn chế?","o":["Giấy tờ viết tay hoặc in từ chủ lao động","Phiếu lương của năm ngoái","Một tờ giấy từ bạn bè","Không cần gì; đi làm luôn được phép"],"h1":"Đó là một tờ giấy từ nơi làm việc.","h2":"Ở Ohio, người có bằng lái thử thách lái xe đi làm hoặc đi làm về trong giờ bị hạn chế phải mang theo giấy tờ xác nhận bằng văn bản từ chủ lao động.","p":"Đúng. Mang theo giấy tờ từ chủ lao động của bạn."},"tl":{"q":"Sa Ohio, ano ang dapat dalhin ng probationary driver para magmaneho papunta o pauwi mula sa trabaho sa mga bawal na oras sa gabi?","o":["Nakasulat na dokumento mula sa employer","Pay stub mula noong nakaraang taon","Sulat mula sa isang kaibigan","Wala; laging pinapayagan ang trabaho"],"h1":"Isa itong papel mula sa trabaho.","h2":"Sa Ohio, ang probationary driver na papunta o pauwi mula sa trabaho sa mga bawal na oras ay dapat may dalang nakasulat na dokumento mula sa employer.","p":"Tama. Dalhin ang papel mula sa iyong employer."},"ar":{"q":"في Ohio، ماذا يجب أن يحمل صاحب الرخصة التجريبية ليقود إلى العمل أو منه في ساعات الليل الممنوعة؟","o":["ورقة مكتوبة من صاحب العمل","قسيمة راتب من السنة الماضية","ورقة من صديق","لا شيء؛ العمل مسموح دائمًا"],"h1":"هي ورقة من مكان العمل.","h2":"في Ohio يجب أن يحمل صاحب الرخصة التجريبية الذي يقود إلى العمل أو منه في الساعات الممنوعة ورقة مكتوبة من صاحب العمل.","p":"صحيح. احمل الورقة من صاحب عملك."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-011","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, during the first year with a probationary license, how many passengers who are not family may a teen carry without a parent or guardian?","o":["None","One","Two","Three"],"h1":"It is the smallest number above zero.","h2":"In Ohio, during the first year, a probationary driver may carry no more than one passenger who is not a family member, unless a parent or guardian is in the car.","p":"Right. Only one non-family passenger in the first year."},"es":{"q":"En Ohio, durante el primer año con licencia probatoria, ¿cuántos pasajeros que no son de la familia puede llevar un joven sin uno de sus padres o tutor?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Es el número más pequeño después del cero.","h2":"En Ohio, durante el primer año, un conductor con licencia probatoria no puede llevar más de un pasajero que no sea de su familia, salvo que vaya su padre, madre o tutor.","p":"Correcto. Solo un pasajero que no es de la familia el primer año."},"zh":{"q":"在 Ohio，持试用驾照的第一年，没有父母或监护人时，青少年可以载几位不是家人的乘客？","o":["一位也不行","一位","两位","三位"],"h1":"它是大于零的最小数字。","h2":"在 Ohio，第一年里，持试用驾照的司机最多只能载一位不是家人的乘客，除非父母或监护人在车上。","p":"对。第一年只能载一位不是家人的乘客。"},"vi":{"q":"Ở Ohio, trong năm đầu có bằng lái thử thách, thiếu niên được chở bao nhiêu hành khách không phải người trong gia đình khi không có cha mẹ hoặc người giám hộ?","o":["Không ai","Một","Hai","Ba"],"h1":"Đó là số nhỏ nhất lớn hơn không.","h2":"Ở Ohio, trong năm đầu tiên, người có bằng lái thử thách được chở không quá một hành khách không phải người trong gia đình, trừ khi có cha mẹ hoặc người giám hộ trong xe.","p":"Đúng. Chỉ một hành khách không phải người nhà trong năm đầu."},"tl":{"q":"Sa Ohio, sa unang taon na may probationary license, ilang pasaherong hindi kapamilya ang puwedeng isakay ng teen kung walang magulang o guardian?","o":["Wala","Isa","Dalawa","Tatlo"],"h1":"Ito ang pinakamaliit na bilang na higit sa zero.","h2":"Sa Ohio, sa unang taon, hindi puwedeng magsakay ang probationary driver ng higit sa isang pasaherong hindi kapamilya, maliban kung may magulang o guardian sa kotse.","p":"Tama. Isang pasaherong hindi kapamilya lang sa unang taon."},"ar":{"q":"في Ohio، خلال السنة الأولى مع الرخصة التجريبية، كم راكبًا من غير العائلة يمكن للمراهق أن يحمل بدون أحد الوالدين أو الوصي؟","o":["لا أحد","واحد","اثنان","ثلاثة"],"h1":"هو أصغر عدد أكبر من صفر.","h2":"في Ohio، خلال السنة الأولى، لا يجوز لصاحب الرخصة التجريبية أن يحمل أكثر من راكب واحد من غير العائلة، إلا إذا كان أحد الوالدين أو الوصي في السيارة.","p":"صحيح. راكب واحد فقط من غير العائلة في السنة الأولى."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-012","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, once a permit holder turns 16, who may supervise them while they drive?","o":["Any passenger over 16","Only a driving instructor","A licensed driver who is at least 18","A licensed driver who is at least 21, in the front passenger seat"],"h1":"The helper must be old enough to drink legally, and sit beside you.","h2":"In Ohio a permit holder who is 16 or older may drive with any licensed driver who is at least 21 and sits in the front passenger seat.","p":"Right. A licensed driver 21 or older beside you."},"es":{"q":"En Ohio, cuando quien tiene permiso cumple 16 años, ¿quién puede supervisarle al manejar?","o":["Cualquier pasajero mayor de 16","Solo un instructor de manejo","Un conductor con licencia de por lo menos 18 años","Un conductor con licencia de por lo menos 21 años, en el asiento del pasajero delantero"],"h1":"El acompañante debe tener edad para tomar alcohol legalmente, y sentarse a su lado.","h2":"En Ohio quien tiene permiso y tiene 16 años o más puede manejar con cualquier conductor con licencia de por lo menos 21 años que vaya en el asiento del pasajero delantero.","p":"Correcto. Un conductor con licencia de 21 años o más a su lado."},"zh":{"q":"在 Ohio，学习驾照持有人满 16 岁以后，谁可以在他们开车时监督？","o":["任何 16 岁以上的乘客","只有驾驶教练","至少 18 岁、有驾照的司机","至少 21 岁、有驾照、坐在前排乘客座位的司机"],"h1":"陪同的人必须到了可以合法喝酒的年龄，而且坐在你旁边。","h2":"在 Ohio，16 岁或以上的学习驾照持有人可以和任何至少 21 岁、有驾照、坐在前排乘客座位的司机一起开车。","p":"对。一位 21 岁或以上、有驾照的司机坐在你旁边。"},"vi":{"q":"Ở Ohio, khi người có giấy phép tập lái đủ 16 tuổi, ai có thể giám sát họ khi lái xe?","o":["Bất kỳ hành khách nào trên 16 tuổi","Chỉ giáo viên dạy lái xe","Một người có bằng lái ít nhất 18 tuổi","Một người có bằng lái ít nhất 21 tuổi, ngồi ở ghế hành khách phía trước"],"h1":"Người giúp phải đủ tuổi uống rượu hợp pháp, và ngồi bên cạnh bạn.","h2":"Ở Ohio, người có giấy phép tập lái từ 16 tuổi trở lên có thể lái xe với bất kỳ người có bằng lái nào ít nhất 21 tuổi ngồi ở ghế hành khách phía trước.","p":"Đúng. Một người có bằng lái từ 21 tuổi trở lên ngồi bên cạnh bạn."},"tl":{"q":"Sa Ohio, kapag nag-16 na ang may hawak ng permit, sino ang puwedeng magbantay sa kanila habang nagmamaneho?","o":["Kahit sinong pasahero na higit 16","Driving instructor lang","Isang lisensyadong driver na hindi bababa sa 18","Isang lisensyadong driver na hindi bababa sa 21, sa front passenger seat"],"h1":"Dapat sapat ang edad ng kasama para legal na uminom ng alak, at umupo sa tabi mo.","h2":"Sa Ohio, ang may hawak ng permit na 16 pataas ay puwedeng magmaneho kasama ang kahit sinong lisensyadong driver na hindi bababa sa 21 at nakaupo sa front passenger seat.","p":"Tama. Isang lisensyadong driver na 21 pataas sa tabi mo."},"ar":{"q":"في Ohio، عندما يبلغ صاحب التصريح 16 سنة، من يمكنه الإشراف عليه أثناء القيادة؟","o":["أي راكب عمره فوق 16 سنة","مدرّب القيادة فقط","سائق مرخّص عمره 18 سنة على الأقل","سائق مرخّص عمره 21 سنة على الأقل، في المقعد الأمامي بجانب السائق"],"h1":"يجب أن يكون المرافق في العمر القانوني لشرب الكحول، وأن يجلس بجانبك.","h2":"في Ohio يمكن لصاحب التصريح الذي عمره 16 سنة أو أكثر أن يقود مع أي سائق مرخّص عمره 21 سنة على الأقل ويجلس في المقعد الأمامي بجانب السائق.","p":"صحيح. سائق مرخّص عمره 21 سنة أو أكثر بجانبك."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-013","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, how many classroom hours of driver education must a teen complete?","o":["24 hours","8 hours","38 hours","50 hours"],"h1":"It is one full day of hours.","h2":"In Ohio a teen must complete 24 hours of driver education in the classroom, plus 8 hours of driving with an instructor.","p":"Right. 24 classroom hours."},"es":{"q":"En Ohio, ¿cuántas horas de clase de manejo debe completar un joven?","o":["24 horas","8 horas","38 horas","50 horas"],"h1":"Son las horas de un día completo.","h2":"En Ohio un joven debe completar 24 horas de clase de manejo, más 8 horas de manejo con un instructor.","p":"Correcto. 24 horas de clase."},"zh":{"q":"在 Ohio，青少年必须完成多少小时的驾驶教育课堂课？","o":["24 小时","8 小时","38 小时","50 小时"],"h1":"它是一整天的小时数。","h2":"在 Ohio，青少年必须完成 24 小时的驾驶教育课堂课，再加上和教练一起开车 8 小时。","p":"对。课堂课 24 小时。"},"vi":{"q":"Ở Ohio, thiếu niên phải học bao nhiêu giờ lý thuyết lái xe (driver education) trong lớp?","o":["24 giờ","8 giờ","38 giờ","50 giờ"],"h1":"Đó là số giờ của một ngày trọn vẹn.","h2":"Ở Ohio, thiếu niên phải học 24 giờ lý thuyết lái xe trong lớp, cộng thêm 8 giờ lái xe với giáo viên.","p":"Đúng. 24 giờ học trong lớp."},"tl":{"q":"Sa Ohio, ilang oras ng driver education sa classroom ang dapat tapusin ng teen?","o":["24 oras","8 oras","38 oras","50 oras"],"h1":"Ito ang bilang ng oras sa isang buong araw.","h2":"Sa Ohio, dapat tapusin ng teen ang 24 oras ng driver education sa classroom, dagdag ang 8 oras ng pagmamaneho kasama ang instructor.","p":"Tama. 24 oras sa classroom."},"ar":{"q":"في Ohio، كم ساعة من دروس تعليم القيادة (driver education) في الصف يجب أن يكملها المراهق؟","o":["24 ساعة","8 ساعات","38 ساعة","50 ساعة"],"h1":"هي عدد ساعات يوم كامل.","h2":"في Ohio يجب أن يكمل المراهق 24 ساعة من تعليم القيادة في الصف، بالإضافة إلى 8 ساعات من القيادة مع مدرّب.","p":"صحيح. 24 ساعة في الصف."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-014","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, how many hours of behind-the-wheel training with a driving instructor must a teen complete?","o":["2 hours","24 hours","8 hours","50 hours"],"h1":"It is one third of the classroom hours.","h2":"In Ohio a teen must complete 8 hours of behind-the-wheel training with a driving instructor.","p":"Right. 8 hours with an instructor."},"es":{"q":"En Ohio, ¿cuántas horas de práctica al volante con un instructor de manejo debe completar un joven?","o":["2 horas","24 horas","8 horas","50 horas"],"h1":"Es la tercera parte de las horas de clase.","h2":"En Ohio un joven debe completar 8 horas de práctica al volante con un instructor de manejo.","p":"Correcto. 8 horas con un instructor."},"zh":{"q":"在 Ohio，青少年必须和驾驶教练完成多少小时的实际上路训练？","o":["2 小时","24 小时","8 小时","50 小时"],"h1":"它是课堂课时间的三分之一。","h2":"在 Ohio，青少年必须和驾驶教练完成 8 小时的实际上路训练。","p":"对。和教练开 8 小时。"},"vi":{"q":"Ở Ohio, thiếu niên phải học bao nhiêu giờ lái xe thực hành (behind-the-wheel) với giáo viên dạy lái?","o":["2 giờ","24 giờ","8 giờ","50 giờ"],"h1":"Đó là một phần ba số giờ học trong lớp.","h2":"Ở Ohio, thiếu niên phải học 8 giờ lái xe thực hành với giáo viên dạy lái.","p":"Đúng. 8 giờ với giáo viên."},"tl":{"q":"Sa Ohio, ilang oras ng behind-the-wheel training kasama ang driving instructor ang dapat tapusin ng teen?","o":["2 oras","24 oras","8 oras","50 oras"],"h1":"Isang-katlo ito ng mga oras sa classroom.","h2":"Sa Ohio, dapat tapusin ng teen ang 8 oras ng behind-the-wheel training kasama ang driving instructor.","p":"Tama. 8 oras kasama ang instructor."},"ar":{"q":"في Ohio، كم ساعة من التدريب العملي خلف المقود (behind-the-wheel) مع مدرّب القيادة يجب أن يكملها المراهق؟","o":["2 ساعة","24 ساعة","8 ساعات","50 ساعة"],"h1":"هي ثلث ساعات الصف.","h2":"في Ohio يجب أن يكمل المراهق 8 ساعات من التدريب العملي خلف المقود مع مدرّب القيادة.","p":"صحيح. 8 ساعات مع المدرّب."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-015","scope":"OH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Ohio, can police stop a driver only for holding a phone while driving?","o":["No, only if there is another violation","Yes, it is a primary offense","Only on interstates","Only at night"],"h1":"The law changed in April 2023 to make this stronger.","h2":"In Ohio, since April 4, 2023, using a hand-held phone while driving is a primary offense, so police can stop you for that alone.","p":"Right. Holding the phone is enough to be stopped."},"es":{"q":"En Ohio, ¿puede la policía detener a un conductor solo por tener el teléfono en la mano mientras maneja?","o":["No, solo si hay otra infracción","Sí, es una infracción principal","Solo en las autopistas interestatales","Solo de noche"],"h1":"La ley cambió en abril de 2023 para ser más fuerte.","h2":"En Ohio, desde el 4 de abril de 2023, usar el teléfono en la mano al manejar es una infracción principal, y la policía puede detenerle solo por eso.","p":"Correcto. Tener el teléfono en la mano basta para que le detengan."},"zh":{"q":"在 Ohio，警察可以只因为司机开车时拿着手机就让他停车吗？","o":["不可以，只有在有其他违规时才可以","可以，它是主要违规（primary offense）","只在州际公路上可以","只在晚上可以"],"h1":"法律在 2023 年 4 月改得更严了。","h2":"在 Ohio，从 2023 年 4 月 4 日起，开车时用手持手机是主要违规（primary offense），所以警察只因为这一点就可以让你停车。","p":"对。拿着手机就足够被拦下。"},"vi":{"q":"Ở Ohio, cảnh sát có thể chặn xe chỉ vì tài xế cầm điện thoại khi lái không?","o":["Không, chỉ khi có vi phạm khác","Có, đó là vi phạm chính (primary offense)","Chỉ trên đường cao tốc liên tiểu bang","Chỉ vào ban đêm"],"h1":"Luật đã thay đổi vào tháng 4 năm 2023 để nghiêm hơn.","h2":"Ở Ohio, từ ngày 4 tháng 4 năm 2023, cầm điện thoại khi lái xe là vi phạm chính (primary offense), nên cảnh sát có thể chặn xe bạn chỉ vì lý do đó.","p":"Đúng. Chỉ cần cầm điện thoại là có thể bị chặn xe."},"tl":{"q":"Sa Ohio, puwede bang patigilin ng pulis ang driver dahil lang sa paghawak ng phone habang nagmamaneho?","o":["Hindi, kung may iba pang paglabag lang","Oo, ito ay primary offense","Sa mga interstate lang","Sa gabi lang"],"h1":"Nagbago ang batas noong April 2023 para gawin itong mas mahigpit.","h2":"Sa Ohio, mula April 4, 2023, ang paggamit ng hawak na phone habang nagmamaneho ay primary offense, kaya puwede kang patigilin ng pulis dahil lang doon.","p":"Tama. Sapat na ang paghawak ng phone para patigilin ka."},"ar":{"q":"في Ohio، هل يمكن للشرطة إيقاف السائق فقط لأنه يمسك الهاتف أثناء القيادة؟","o":["لا، فقط إذا كانت هناك مخالفة أخرى","نعم، إنها مخالفة أساسية (primary offense)","على الطرق السريعة بين الولايات فقط","في الليل فقط"],"h1":"تغيّر القانون في أبريل 2023 ليصبح أشد.","h2":"في Ohio، منذ 4 أبريل 2023، استخدام الهاتف باليد أثناء القيادة مخالفة أساسية (primary offense)، لذلك يمكن للشرطة إيقافك لهذا السبب وحده.","p":"صحيح. إمساك الهاتف يكفي لإيقافك."},"ref":{"doc":"OH","page":"§3"}},{"id":"oh-016","scope":"OH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Ohio, how much may an adult driver touch a phone while driving, in most cases?","o":["As much as needed at a red light","Only to send short texts","Not at all, even to answer a call","A single touch or swipe"],"h1":"It is the smallest possible action.","h2":"In Ohio, in most cases, a driver may use only a single touch or swipe on a phone; anything more is against the law.","p":"Right. One touch or swipe at most."},"es":{"q":"En Ohio, en la mayoría de los casos, ¿cuánto puede tocar el teléfono un conductor adulto mientras maneja?","o":["Lo que necesite en un semáforo en rojo","Solo para enviar mensajes cortos","Nada, ni siquiera para contestar una llamada","Un solo toque o deslizamiento"],"h1":"Es la acción más pequeña posible.","h2":"En Ohio, en la mayoría de los casos, un conductor solo puede dar un toque o un deslizamiento en el teléfono; más que eso va contra la ley.","p":"Correcto. Un toque o deslizamiento como máximo."},"zh":{"q":"在 Ohio，大多数情况下，成年司机开车时可以碰手机多少？","o":["红灯时想用多少就用多少","只能发短的短信","完全不能碰，接电话也不行","点一下或划一下"],"h1":"它是最小的动作。","h2":"在 Ohio，大多数情况下，司机只能在手机上点一下或划一下；再多就是违法的。","p":"对。最多点一下或划一下。"},"vi":{"q":"Ở Ohio, trong hầu hết trường hợp, tài xế người lớn được chạm vào điện thoại bao nhiêu khi lái xe?","o":["Bao nhiêu cũng được khi dừng đèn đỏ","Chỉ để gửi tin nhắn ngắn","Hoàn toàn không, kể cả để nghe cuộc gọi","Một lần chạm hoặc vuốt"],"h1":"Đó là hành động nhỏ nhất có thể.","h2":"Ở Ohio, trong hầu hết trường hợp, tài xế chỉ được chạm hoặc vuốt điện thoại một lần; làm nhiều hơn là phạm luật.","p":"Đúng. Nhiều nhất là một lần chạm hoặc vuốt."},"tl":{"q":"Sa Ohio, gaano kadalas puwedeng hawakan ng adultong driver ang phone habang nagmamaneho, sa karamihan ng kaso?","o":["Kahit gaano karami kapag naka-red light","Para lang magpadala ng maikling text","Hindi talaga, kahit para sumagot ng tawag","Isang touch o swipe"],"h1":"Ito ang pinakamaliit na posibleng galaw.","h2":"Sa Ohio, sa karamihan ng kaso, isang touch o swipe lang sa phone ang puwede sa driver; labag sa batas ang higit doon.","p":"Tama. Isang touch o swipe lang ang pinakamarami."},"ar":{"q":"في Ohio، إلى أي حد يجوز للسائق البالغ أن يلمس الهاتف أثناء القيادة، في معظم الحالات؟","o":["بقدر ما يحتاج عند الإشارة الحمراء","فقط لإرسال رسائل قصيرة","لا يجوز أبدًا، حتى للرد على مكالمة","لمسة واحدة أو سحبة واحدة"],"h1":"هو أصغر فعل ممكن.","h2":"في Ohio، في معظم الحالات، يجوز للسائق لمسة واحدة أو سحبة واحدة فقط على الهاتف؛ وأي شيء أكثر من ذلك مخالف للقانون.","p":"صحيح. لمسة أو سحبة واحدة على الأكثر."},"ref":{"doc":"OH","page":"§3"}},{"id":"oh-017","scope":"OH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Ohio, what is the penalty for a first hand-held phone offense?","o":["Up to a $150 fine and 2 points, or a distracted driving course instead","A $25 fine","Loss of the license for one year","Only a warning, always"],"h1":"There is a choice between paying and learning.","h2":"In Ohio a first hand-held phone offense brings 2 points and a fine of up to $150, but a distracted driving course can let you avoid the fine and points.","p":"Right. Up to $150 and 2 points, or a distracted driving course."},"es":{"q":"En Ohio, ¿cuál es la sanción por la primera vez que se usa el teléfono en la mano al manejar?","o":["Una multa de hasta $150 y 2 puntos, o un curso sobre manejo distraído en su lugar","Una multa de $25","Perder la licencia por un año","Siempre solo una advertencia"],"h1":"Hay que elegir entre pagar o aprender.","h2":"En Ohio la primera infracción por usar el teléfono en la mano trae 2 puntos y una multa de hasta $150, pero un curso sobre manejo distraído le permite evitar la multa y los puntos.","p":"Correcto. Hasta $150 y 2 puntos, o un curso sobre manejo distraído."},"zh":{"q":"在 Ohio，第一次因为手持手机被抓，处罚是什么？","o":["最高罚款 $150 并扣 2 分，或者改上分心驾驶课程","罚款 $25","吊销驾照一年","只会警告，一直都是"],"h1":"可以在付钱和学习之间选择。","h2":"在 Ohio，第一次因为手持手机被抓，扣 2 分并罚款最高 $150，但上分心驾驶课程可以让你不用罚款和扣分。","p":"对。最高 $150 并扣 2 分，或者上分心驾驶课程。"},"vi":{"q":"Ở Ohio, hình phạt cho lần đầu vi phạm cầm điện thoại khi lái xe là gì?","o":["Phạt tối đa $150 và 2 điểm, hoặc học khóa lái xe mất tập trung (distracted driving course) thay thế","Phạt $25","Mất bằng lái một năm","Luôn luôn chỉ bị cảnh cáo"],"h1":"Bạn được chọn giữa trả tiền và đi học.","h2":"Ở Ohio, lần đầu vi phạm cầm điện thoại bị 2 điểm và phạt tối đa $150, nhưng học một khóa về lái xe mất tập trung có thể giúp bạn tránh tiền phạt và điểm.","p":"Đúng. Tối đa $150 và 2 điểm, hoặc học khóa lái xe mất tập trung."},"tl":{"q":"Sa Ohio, ano ang parusa sa unang paglabag sa paghawak ng phone?","o":["Multang hanggang $150 at 2 points, o isang distracted driving course bilang kapalit","Multang $25","Pagkawala ng lisensya nang isang taon","Babala lang, palagi"],"h1":"May pagpipilian sa pagitan ng pagbabayad at pag-aaral.","h2":"Sa Ohio, ang unang paglabag sa paghawak ng phone ay may 2 points at multang hanggang $150, pero ang isang distracted driving course ay puwedeng magligtas sa iyo sa multa at points.","p":"Tama. Hanggang $150 at 2 points, o isang distracted driving course."},"ar":{"q":"في Ohio، ما عقوبة المخالفة الأولى لاستخدام الهاتف باليد؟","o":["غرامة حتى $150 و2 نقاط، أو دورة عن القيادة المشتّتة (distracted driving course) بدلًا منها","غرامة $25","سحب الرخصة لمدة سنة","تحذير فقط، دائمًا"],"h1":"هناك اختيار بين الدفع والتعلّم.","h2":"في Ohio تؤدي المخالفة الأولى لاستخدام الهاتف باليد إلى 2 نقاط وغرامة حتى $150، لكن دورة عن القيادة المشتّتة قد تعفيك من الغرامة والنقاط.","p":"صحيح. حتى $150 و2 نقاط، أو دورة عن القيادة المشتّتة."},"ref":{"doc":"OH","page":"§3"}},{"id":"oh-018","scope":"OH","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Ohio, which stopped vehicles with warning lights on must you move over for?","o":["Only police cars","Only ambulances and fire trucks","Police, emergency, tow, road crew and garbage trucks","Only tow trucks"],"h1":"The law covers more than police and fire. Think of road workers too.","h2":"In Ohio you must move one lane away from stopped police and emergency vehicles, tow trucks, road maintenance trucks and garbage trucks with warning lights on, or slow down if you cannot move over safely.","p":"Right. Emergency, tow, road crew and garbage trucks all count."},"es":{"q":"En Ohio, ¿ante qué vehículos detenidos con luces de advertencia encendidas debe cambiarse de carril?","o":["Solo patrullas de policía","Solo ambulancias y camiones de bomberos","Policía, emergencias, grúas, equipos de carreteras y camiones de basura","Solo grúas"],"h1":"La ley cubre más que la policía y los bomberos. Piense también en los trabajadores de carreteras.","h2":"En Ohio usted debe alejarse un carril de los vehículos de policía y emergencias, grúas, camiones de mantenimiento de carreteras y camiones de basura que estén detenidos con luces de advertencia, o bajar la velocidad si no puede cambiarse con seguridad.","p":"Correcto. Emergencias, grúas, equipos de carreteras y camiones de basura cuentan."},"zh":{"q":"在 Ohio，你必须为哪些停着、开着警示灯的车让道变道（move over）？","o":["只有警车","只有救护车和消防车","警车、紧急车辆、拖车、道路工程车和垃圾车","只有拖车"],"h1":"这条法律不只包括警察和消防。也想想道路工人。","h2":"在 Ohio，遇到停着、开着警示灯的警车、紧急车辆、拖车、道路维修车和垃圾车，你必须换到离它们远一条的车道，如果不能安全换道，就要减速。","p":"对。紧急车辆、拖车、道路工程车和垃圾车都算。"},"vi":{"q":"Ở Ohio, bạn phải chuyển làn tránh xa những xe đang dừng có bật đèn cảnh báo nào?","o":["Chỉ xe cảnh sát","Chỉ xe cứu thương và xe cứu hỏa","Xe cảnh sát, xe cấp cứu, xe kéo, xe sửa đường và xe rác","Chỉ xe kéo"],"h1":"Luật áp dụng cho nhiều xe hơn cảnh sát và cứu hỏa. Hãy nghĩ cả đến công nhân làm đường.","h2":"Ở Ohio, bạn phải chuyển sang cách một làn với xe cảnh sát và xe cấp cứu, xe kéo, xe bảo trì đường và xe rác đang dừng có bật đèn cảnh báo, hoặc chạy chậm lại nếu không thể chuyển làn an toàn.","p":"Đúng. Xe cấp cứu, xe kéo, xe sửa đường và xe rác đều tính."},"tl":{"q":"Sa Ohio, aling mga nakahintong sasakyan na may nakabukas na warning lights ang dapat mong lipatan ng lane?","o":["Mga police car lang","Mga ambulansya at fire truck lang","Police, emergency, tow, road crew at garbage truck","Mga tow truck lang"],"h1":"Mas marami ang saklaw ng batas kaysa pulis at bumbero. Isipin din ang mga trabahador sa kalsada.","h2":"Sa Ohio, dapat kang lumipat ng isang lane palayo sa mga nakahintong police at emergency vehicle, tow truck, road maintenance truck at garbage truck na may nakabukas na warning lights, o bumagal kung hindi ka ligtas na makakalipat.","p":"Tama. Kasama ang emergency, tow, road crew at garbage truck."},"ar":{"q":"في Ohio، ما المركبات المتوقفة التي أضواء التحذير فيها مضاءة ويجب أن تبتعد عنها بتغيير المسار؟","o":["سيارات الشرطة فقط","سيارات الإسعاف والإطفاء فقط","الشرطة والطوارئ وشاحنات السحب وعمال الطرق وشاحنات القمامة","شاحنات السحب فقط"],"h1":"القانون يشمل أكثر من الشرطة والإطفاء. فكّر في عمال الطرق أيضًا.","h2":"في Ohio يجب أن تنتقل مسارًا واحدًا بعيدًا عن سيارات الشرطة والطوارئ وشاحنات السحب وشاحنات صيانة الطرق وشاحنات القمامة المتوقفة وأضواء التحذير فيها مضاءة، أو أن تخفف السرعة إذا لم تستطع تغيير المسار بأمان.","p":"صحيح. الطوارئ وشاحنات السحب وعمال الطرق وشاحنات القمامة كلها مشمولة."},"ref":{"doc":"OH","page":"§9"}},{"id":"oh-019","scope":"OH","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Ohio, on a road with four or more lanes, who must stop for a school bus loading or unloading students?","o":["All traffic in both directions","Only traffic moving in the same direction as the bus","Only traffic coming toward the bus","No one"],"h1":"On a wide road, the bus lets students out only on the side where they live.","h2":"In Ohio, on a road with four or more lanes, only traffic moving in the same direction as the school bus must stop.","p":"Right. Only the same direction stops on four or more lanes."},"es":{"q":"En Ohio, en una carretera de cuatro carriles o más, ¿quién debe detenerse ante un autobús escolar que sube o baja estudiantes?","o":["Todo el tráfico en los dos sentidos","Solo el tráfico que va en el mismo sentido que el autobús","Solo el tráfico que viene hacia el autobús","Nadie"],"h1":"En una carretera ancha, el autobús deja a los estudiantes solo del lado donde viven.","h2":"En Ohio, en una carretera de cuatro carriles o más, solo el tráfico que va en el mismo sentido que el autobús escolar debe detenerse.","p":"Correcto. En cuatro carriles o más, solo se detiene el mismo sentido."},"zh":{"q":"在 Ohio，在四条或更多车道的路上，校车上下学生时，谁必须停车？","o":["两个方向的所有车","只有和校车同方向的车","只有朝校车开过来的车","谁都不用"],"h1":"在宽的路上，校车只在学生住的那一边让他们下车。","h2":"在 Ohio，在四条或更多车道的路上，只有和校车同方向的车必须停车。","p":"对。四条或更多车道时，只有同方向的车停。"},"vi":{"q":"Ở Ohio, trên đường có bốn làn trở lên, ai phải dừng lại khi xe buýt trường học đang cho học sinh lên hoặc xuống?","o":["Tất cả xe cộ ở cả hai chiều","Chỉ xe chạy cùng chiều với xe buýt","Chỉ xe chạy ngược chiều về phía xe buýt","Không ai cả"],"h1":"Trên đường rộng, xe buýt chỉ cho học sinh xuống ở phía nhà của các em.","h2":"Ở Ohio, trên đường có bốn làn trở lên, chỉ xe chạy cùng chiều với xe buýt trường học phải dừng lại.","p":"Đúng. Trên đường bốn làn trở lên, chỉ xe cùng chiều phải dừng."},"tl":{"q":"Sa Ohio, sa kalsadang may apat o higit pang lane, sino ang dapat huminto para sa school bus na nagsasakay o nagbababa ng mga estudyante?","o":["Lahat ng sasakyan sa dalawang direksyon","Ang mga sasakyan lang na papunta sa parehong direksyon ng bus","Ang mga sasakyan lang na papalapit sa bus","Wala"],"h1":"Sa malawak na kalsada, nagbababa lang ang bus ng estudyante sa gilid kung saan sila nakatira.","h2":"Sa Ohio, sa kalsadang may apat o higit pang lane, ang mga sasakyan lang na papunta sa parehong direksyon ng school bus ang dapat huminto.","p":"Tama. Ang parehong direksyon lang ang humihinto sa apat o higit pang lane."},"ar":{"q":"في Ohio، على طريق فيه أربعة مسارات أو أكثر، من يجب أن يتوقف لحافلة مدرسية تُركب الطلاب أو تُنزلهم؟","o":["كل السيارات في الاتجاهين","فقط السيارات التي تسير في نفس اتجاه الحافلة","فقط السيارات القادمة نحو الحافلة","لا أحد"],"h1":"على الطريق العريض، تُنزل الحافلة الطلاب فقط في الجهة التي يسكنون فيها.","h2":"في Ohio، على طريق فيه أربعة مسارات أو أكثر، فقط السيارات التي تسير في نفس اتجاه الحافلة المدرسية يجب أن تتوقف.","p":"صحيح. على أربعة مسارات أو أكثر، يتوقف فقط من يسير في نفس الاتجاه."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-020","scope":"OH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Ohio, what is the legal blood alcohol limit for a driver under 21?","o":["0.08 percent","0.10 percent","0.04 percent","0.02 percent"],"h1":"It is much lower than the adult limit of 0.08.","h2":"In Ohio a driver under 21 breaks the law with a blood alcohol level of 0.02 percent or more.","p":"Right. For drivers under 21 the limit is 0.02."},"es":{"q":"En Ohio, ¿cuál es el límite legal de alcohol en la sangre para un conductor menor de 21?","o":["0.08 por ciento","0.10 por ciento","0.04 por ciento","0.02 por ciento"],"h1":"Es mucho más bajo que el límite de 0.08 para adultos.","h2":"En Ohio un conductor menor de 21 viola la ley con un nivel de alcohol en la sangre de 0.02 por ciento o más.","p":"Correcto. Para menores de 21 el límite es 0.02."},"zh":{"q":"在 Ohio，未满 21 岁的司机法定血液酒精浓度上限是多少？","o":["0.08%","0.10%","0.04%","0.02%"],"h1":"它比成年人的上限 0.08 低很多。","h2":"在 Ohio，未满 21 岁的司机血液酒精浓度在 0.02% 或以上就违法。","p":"对。未满 21 岁的司机上限是 0.02。"},"vi":{"q":"Ở Ohio, giới hạn nồng độ cồn trong máu hợp pháp cho tài xế dưới 21 tuổi là bao nhiêu?","o":["0.08 phần trăm","0.10 phần trăm","0.04 phần trăm","0.02 phần trăm"],"h1":"Nó thấp hơn nhiều so với giới hạn của người lớn là 0.08.","h2":"Ở Ohio, tài xế dưới 21 tuổi phạm luật khi có nồng độ cồn trong máu từ 0.02 phần trăm trở lên.","p":"Đúng. Với tài xế dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa Ohio, ano ang legal na limit ng alcohol sa dugo para sa driver na wala pang 21?","o":["0.08 percent","0.10 percent","0.04 percent","0.02 percent"],"h1":"Mas mababa ito nang malaki kaysa sa limit ng adulto na 0.08.","h2":"Sa Ohio, lumalabag sa batas ang driver na wala pang 21 kapag 0.02 percent o higit pa ang alcohol sa kanyang dugo.","p":"Tama. Para sa mga driver na wala pang 21, ang limit ay 0.02."},"ar":{"q":"في Ohio، ما الحد القانوني لنسبة الكحول في الدم للسائق الذي عمره أقل من 21 سنة؟","o":["0.08 بالمئة","0.10 بالمئة","0.04 بالمئة","0.02 بالمئة"],"h1":"هو أقل بكثير من حد البالغين وهو 0.08.","h2":"في Ohio يخالف السائق الذي عمره أقل من 21 سنة القانون إذا كانت نسبة الكحول في دمه 0.02 بالمئة أو أكثر.","p":"صحيح. للسائقين تحت 21 سنة الحد هو 0.02."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-021","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, how many points within two years lead to a license suspension?","o":["6 points","12 or more points","8 points","10 points"],"h1":"At 6 points you only get a warning letter.","h2":"In Ohio, a driver who gets 12 or more points within two years has the license suspended by the BMV.","p":"Right. 12 points in two years means a suspension."},"es":{"q":"En Ohio, ¿cuántos puntos en dos años llevan a la suspensión de la licencia?","o":["6 puntos","12 puntos o más","8 puntos","10 puntos"],"h1":"Con 6 puntos solo recibe una carta de advertencia.","h2":"En Ohio, al conductor que acumula 12 puntos o más en dos años, el BMV le suspende la licencia.","p":"Correcto. 12 puntos en dos años significan una suspensión."},"zh":{"q":"在 Ohio，两年内累计多少分会导致驾照被暂停？","o":["6 分","12 分或以上","8 分","10 分"],"h1":"到 6 分时你只会收到一封警告信。","h2":"在 Ohio，两年内累计 12 分或以上的司机，驾照会被 BMV 暂停。","p":"对。两年内 12 分就会被暂停驾照。"},"vi":{"q":"Ở Ohio, bao nhiêu điểm trong vòng hai năm sẽ dẫn đến đình chỉ bằng lái?","o":["6 điểm","Từ 12 điểm trở lên","8 điểm","10 điểm"],"h1":"Khi bị 6 điểm, bạn chỉ nhận một lá thư cảnh cáo.","h2":"Ở Ohio, tài xế bị từ 12 điểm trở lên trong vòng hai năm sẽ bị BMV đình chỉ bằng lái.","p":"Đúng. 12 điểm trong hai năm nghĩa là bị đình chỉ bằng lái."},"tl":{"q":"Sa Ohio, ilang point sa loob ng dalawang taon ang humahantong sa suspensyon ng lisensya?","o":["6 na point","12 o higit pang point","8 point","10 point"],"h1":"Sa 6 na point, warning letter lang ang matatanggap mo.","h2":"Sa Ohio, ang driver na makakuha ng 12 o higit pang point sa loob ng dalawang taon ay sinususpindehan ng lisensya ng BMV.","p":"Tama. Ang 12 point sa dalawang taon ay nangangahulugang suspensyon."},"ar":{"q":"في Ohio، كم نقطة خلال سنتين تؤدي إلى إيقاف الرخصة؟","o":["6 نقاط","12 نقطة أو أكثر","8 نقاط","10 نقاط"],"h1":"عند 6 نقاط تحصل فقط على رسالة تحذير.","h2":"في Ohio، السائق الذي يحصل على 12 نقطة أو أكثر خلال سنتين يوقف الـ BMV رخصته.","p":"صحيح. 12 نقطة في سنتين تعني إيقاف الرخصة."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-022","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, what is the minimum liability insurance a driver must carry?","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000","$25,000 / $50,000 / $25,000"],"h1":"The first and last numbers are the same, and the middle one is twice as big.","h2":"In Ohio, the minimum liability insurance is $25,000 for one person hurt, $50,000 for two or more people hurt, and $25,000 for property damage.","p":"Right. $25,000, $50,000 and $25,000."},"es":{"q":"En Ohio, ¿cuál es el seguro mínimo de responsabilidad civil que debe tener un conductor?","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000","$25,000 / $50,000 / $25,000"],"h1":"El primer número y el último son iguales, y el del medio es el doble.","h2":"En Ohio, el seguro mínimo de responsabilidad civil es de $25,000 por una persona herida, $50,000 por dos o más personas heridas y $25,000 por daños a la propiedad.","p":"Correcto. $25,000, $50,000 y $25,000."},"zh":{"q":"在 Ohio，司机最低必须买多少责任保险？","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000","$25,000 / $50,000 / $25,000"],"h1":"第一个和最后一个数字一样，中间的数字是它们的两倍。","h2":"在 Ohio，最低责任保险是：一人受伤 $25,000，两人或更多人受伤 $50,000，财产损失 $25,000。","p":"对。$25,000、$50,000 和 $25,000。"},"vi":{"q":"Ở Ohio, người lái xe phải có bảo hiểm trách nhiệm tối thiểu là bao nhiêu?","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000","$25,000 / $50,000 / $25,000"],"h1":"Số đầu và số cuối giống nhau, số ở giữa lớn gấp đôi.","h2":"Ở Ohio, bảo hiểm trách nhiệm tối thiểu là $25,000 khi một người bị thương, $50,000 khi hai người trở lên bị thương, và $25,000 cho thiệt hại tài sản.","p":"Đúng. $25,000, $50,000 và $25,000."},"tl":{"q":"Sa Ohio, ano ang pinakamababang liability insurance na dapat mayroon ang drayber?","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000","$25,000 / $50,000 / $25,000"],"h1":"Pareho ang una at huling numero, at doble ang nasa gitna.","h2":"Sa Ohio, ang pinakamababang liability insurance ay $25,000 para sa isang taong nasaktan, $50,000 para sa dalawa o higit pang taong nasaktan, at $25,000 para sa sira sa ari-arian.","p":"Tama. $25,000, $50,000 at $25,000."},"ar":{"q":"في Ohio، ما الحد الأدنى من تأمين المسؤولية الذي يجب أن يملكه السائق؟","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000","$25,000 / $50,000 / $25,000"],"h1":"الرقم الأول والأخير متساويان، والرقم الأوسط ضعفهما.","h2":"في Ohio، الحد الأدنى من تأمين المسؤولية هو $25,000 لإصابة شخص واحد، و$50,000 لإصابة شخصين أو أكثر، و$25,000 لأضرار الممتلكات.","p":"صحيح. $25,000 و$50,000 و$25,000."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-023","scope":"OH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Ohio, what happens the first time a driver refuses a chemical test for alcohol after an arrest?","o":["A one-year license suspension","Only a warning","A 30-day license suspension","A fine, but no suspension"],"h1":"Refusing is treated more harshly than failing the test the first time.","h2":"In Ohio, refusing a chemical test for the first time brings a one-year license suspension that starts right away, even if the driver is later found not guilty.","p":"Right. A first refusal means a one-year suspension."},"es":{"q":"En Ohio, ¿qué pasa la primera vez que un conductor arrestado se niega a una prueba química de alcohol?","o":["Una suspensión de la licencia por un año","Solo una advertencia","Una suspensión de la licencia por 30 días","Una multa, pero sin suspensión"],"h1":"Negarse se castiga más que no pasar la prueba la primera vez.","h2":"En Ohio, negarse por primera vez a una prueba química trae una suspensión de la licencia por un año que empieza de inmediato, aunque después declaren inocente al conductor.","p":"Correcto. La primera negativa significa un año de suspensión."},"zh":{"q":"在 Ohio，司机被逮捕后第一次拒绝做酒精化学检测，会怎么样？","o":["暂停驾照一年","只有警告","暂停驾照 30 天","罚款，但不暂停驾照"],"h1":"第一次拒绝检测，处罚比检测没通过更重。","h2":"在 Ohio，第一次拒绝化学检测会被马上暂停驾照一年，即使司机后来被判无罪也一样。","p":"对。第一次拒绝就会被暂停驾照一年。"},"vi":{"q":"Ở Ohio, điều gì xảy ra khi người lái xe lần đầu từ chối xét nghiệm hóa học về rượu sau khi bị bắt?","o":["Bị đình chỉ bằng lái một năm","Chỉ bị cảnh cáo","Bị đình chỉ bằng lái 30 ngày","Bị phạt tiền, nhưng không bị đình chỉ"],"h1":"Lần đầu từ chối bị xử nặng hơn là xét nghiệm không đạt.","h2":"Ở Ohio, lần đầu từ chối xét nghiệm hóa học sẽ bị đình chỉ bằng lái một năm ngay lập tức, kể cả khi sau đó người lái xe được tuyên vô tội.","p":"Đúng. Lần đầu từ chối nghĩa là bị đình chỉ bằng lái một năm."},"tl":{"q":"Sa Ohio, ano ang mangyayari sa unang beses na tumanggi ang drayber sa chemical test para sa alak matapos maaresto?","o":["Isang taong suspensyon ng lisensya","Babala lang","30 araw na suspensyon ng lisensya","Multa, pero walang suspensyon"],"h1":"Mas mabigat ang parusa sa pagtanggi kaysa sa pagbagsak sa test sa unang beses.","h2":"Sa Ohio, ang unang pagtanggi sa chemical test ay may isang taong suspensyon ng lisensya na nagsisimula agad, kahit mapatunayang hindi nagkasala ang drayber sa huli.","p":"Tama. Ang unang pagtanggi ay nangangahulugan ng isang taong suspensyon."},"ar":{"q":"في Ohio، ماذا يحدث أول مرة يرفض فيها السائق الفحص الكيميائي للكحول بعد القبض عليه؟","o":["إيقاف الرخصة لمدة سنة","تحذير فقط","إيقاف الرخصة لمدة 30 يومًا","غرامة، لكن بدون إيقاف"],"h1":"الرفض في المرة الأولى عقوبته أشد من الرسوب في الفحص.","h2":"في Ohio، رفض الفحص الكيميائي أول مرة يؤدي إلى إيقاف الرخصة لمدة سنة يبدأ فورًا، حتى لو ثبتت براءة السائق لاحقًا.","p":"صحيح. الرفض الأول يعني إيقاف الرخصة لمدة سنة."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-024","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, what happens to a driver under 18 who is convicted of two moving violations?","o":["A warning letter only","A one-year license suspension","A three-month license suspension","Nothing, until 12 points"],"h1":"For teens, the BMV acts quickly. Two violations bring a short suspension.","h2":"In Ohio, a driver under 18 who is convicted of two moving violations gets an automatic three-month license suspension.","p":"Right. Two moving violations mean three months without a license."},"es":{"q":"En Ohio, ¿qué le pasa a un conductor menor de 18 años condenado por dos infracciones de tránsito en movimiento?","o":["Solo una carta de advertencia","Una suspensión de la licencia por un año","Una suspensión de la licencia por tres meses","Nada, hasta llegar a 12 puntos"],"h1":"Con los adolescentes, el BMV actúa rápido. Dos infracciones traen una suspensión corta.","h2":"En Ohio, un conductor menor de 18 años condenado por dos infracciones en movimiento recibe una suspensión automática de la licencia por tres meses.","p":"Correcto. Dos infracciones significan tres meses sin licencia."},"zh":{"q":"在 Ohio，未满 18 岁的司机如果有两次行车违规定罪，会怎么样？","o":["只收到警告信","暂停驾照一年","暂停驾照三个月","到 12 分之前都没事"],"h1":"对青少年，BMV 处理得很快。两次违规就会被短期暂停驾照。","h2":"在 Ohio，未满 18 岁的司机如果有两次行车违规定罪，会被自动暂停驾照三个月。","p":"对。两次行车违规就是三个月没有驾照。"},"vi":{"q":"Ở Ohio, điều gì xảy ra với người lái xe dưới 18 tuổi bị kết tội hai lần vi phạm khi lái xe?","o":["Chỉ nhận thư cảnh cáo","Bị đình chỉ bằng lái một năm","Bị đình chỉ bằng lái ba tháng","Không sao, cho đến khi bị 12 điểm"],"h1":"Với thanh thiếu niên, BMV xử lý rất nhanh. Hai lần vi phạm sẽ bị đình chỉ một thời gian ngắn.","h2":"Ở Ohio, người lái xe dưới 18 tuổi bị kết tội hai lần vi phạm khi lái xe sẽ tự động bị đình chỉ bằng lái ba tháng.","p":"Đúng. Hai lần vi phạm khi lái xe nghĩa là ba tháng không có bằng lái."},"tl":{"q":"Sa Ohio, ano ang mangyayari sa drayber na wala pang 18 na nahatulan sa dalawang moving violation?","o":["Sulat ng babala lang","Isang taong suspensyon ng lisensya","Tatlong buwang suspensyon ng lisensya","Wala, hanggang umabot sa 12 puntos"],"h1":"Sa mga kabataan, mabilis kumilos ang BMV. Ang dalawang paglabag ay may maikling suspensyon.","h2":"Sa Ohio, ang drayber na wala pang 18 na nahatulan sa dalawang moving violation ay awtomatikong masususpinde ang lisensya nang tatlong buwan.","p":"Tama. Ang dalawang moving violation ay nangangahulugan ng tatlong buwang walang lisensya."},"ar":{"q":"في Ohio، ماذا يحدث للسائق تحت 18 سنة إذا أُدين بمخالفتين أثناء القيادة؟","o":["رسالة تحذير فقط","إيقاف الرخصة لمدة سنة","إيقاف الرخصة لمدة ثلاثة أشهر","لا شيء، حتى يصل إلى 12 نقطة"],"h1":"مع المراهقين تتصرف إدارة BMV بسرعة. مخالفتان تعنيان إيقافًا قصيرًا.","h2":"في Ohio، السائق تحت 18 سنة الذي يُدان بمخالفتين أثناء القيادة تُوقف رخصته تلقائيًا لمدة ثلاثة أشهر.","p":"صحيح. مخالفتان أثناء القيادة تعنيان ثلاثة أشهر بدون رخصة."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-025","scope":"OH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Ohio, a child is 6 years old and 4 feet tall. How must the child ride in a car?","o":["With only a seat belt","In a booster seat","In a rear-facing infant seat","On an adult's lap"],"h1":"Children from 4 up to 8 years old need extra height unless they are already 4 feet 9 inches tall.","h2":"In Ohio, a child at least 4 but under 8 years old must ride in a booster seat unless the child is 4 feet 9 inches tall or taller.","p":"Right. This child needs a booster seat."},"es":{"q":"En Ohio, un niño tiene 6 años y mide 4 pies. ¿Cómo debe viajar en el carro?","o":["Solo con el cinturón de seguridad","En un asiento elevado (booster)","En un asiento para bebé mirando hacia atrás","En las piernas de un adulto"],"h1":"Los niños de 4 a 8 años necesitan más altura, a menos que ya midan 4 pies 9 pulgadas.","h2":"En Ohio, un niño de al menos 4 años pero menor de 8 debe viajar en un asiento elevado (booster), a menos que mida 4 pies 9 pulgadas o más.","p":"Correcto. Este niño necesita un asiento elevado."},"zh":{"q":"在 Ohio，一个孩子 6 岁，身高 4 英尺。这个孩子坐车时必须怎么坐？","o":["只系安全带","坐增高座椅（booster seat）","坐后向婴儿座椅","坐在大人腿上"],"h1":"4 岁到 8 岁的孩子需要垫高，除非已经有 4 英尺 9 英寸高。","h2":"在 Ohio，至少 4 岁但未满 8 岁的孩子必须坐增高座椅，除非孩子身高达到 4 英尺 9 英寸或更高。","p":"对。这个孩子需要坐增高座椅。"},"vi":{"q":"Ở Ohio, một em bé 6 tuổi và cao 4 feet. Em bé phải ngồi trong xe như thế nào?","o":["Chỉ cần thắt dây an toàn","Ngồi ghế nâng (booster seat)","Ngồi ghế trẻ sơ sinh quay về phía sau","Ngồi trong lòng người lớn"],"h1":"Trẻ từ 4 đến 8 tuổi cần được ngồi cao hơn, trừ khi đã cao 4 feet 9 inch.","h2":"Ở Ohio, trẻ từ 4 tuổi nhưng chưa đủ 8 tuổi phải ngồi ghế nâng, trừ khi trẻ cao từ 4 feet 9 inch trở lên.","p":"Đúng. Em bé này cần ngồi ghế nâng."},"tl":{"q":"Sa Ohio, may batang 6 na taong gulang at 4 na talampakan ang taas. Paano dapat sumakay ang bata sa kotse?","o":["Seat belt lang","Sa booster seat","Sa rear-facing na upuan ng sanggol","Sa kandungan ng matanda"],"h1":"Ang mga batang 4 hanggang 8 taong gulang ay kailangang iupo nang mas mataas, maliban kung 4 na talampakan at 9 na pulgada na ang taas nila.","h2":"Sa Ohio, ang batang hindi bababa sa 4 pero wala pang 8 taong gulang ay dapat nasa booster seat, maliban kung 4 na talampakan at 9 na pulgada o higit pa ang taas ng bata.","p":"Tama. Kailangan ng batang ito ng booster seat."},"ar":{"q":"في Ohio، طفل عمره 6 سنوات وطوله 4 أقدام. كيف يجب أن يجلس الطفل في السيارة؟","o":["بحزام الأمان فقط","في مقعد رافع (booster seat)","في مقعد رضيع موجّه للخلف","في حضن شخص بالغ"],"h1":"الأطفال من 4 إلى 8 سنوات يحتاجون إلى رفع إضافي، إلا إذا كان طولهم 4 أقدام و9 بوصات.","h2":"في Ohio، الطفل الذي عمره 4 سنوات على الأقل وأقل من 8 سنوات يجب أن يجلس في مقعد رافع، إلا إذا كان طوله 4 أقدام و9 بوصات أو أكثر.","p":"صحيح. هذا الطفل يحتاج إلى مقعد رافع."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-026","scope":"OH","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Ohio, when must your headlights be on during the day?","o":["Only on the highway","Only inside tunnels","Never during the day","When your wipers are on because of rain or snow"],"h1":"Think about what you turn on when it starts to rain.","h2":"In Ohio, your headlights must be on whenever your windshield wipers are in use because of rain, snow or other weather, and also when it is hard to see.","p":"Right. Wipers on for rain or snow means headlights on."},"es":{"q":"En Ohio, ¿cuándo deben estar encendidas sus luces delanteras durante el día?","o":["Solo en la autopista","Solo dentro de los túneles","Nunca durante el día","Cuando usa los limpiaparabrisas por lluvia o nieve"],"h1":"Piense en lo que enciende cuando empieza a llover.","h2":"En Ohio, las luces delanteras deben estar encendidas siempre que use los limpiaparabrisas por lluvia, nieve u otro mal tiempo, y también cuando se ve poco.","p":"Correcto. Limpiaparabrisas por lluvia o nieve significa luces encendidas."},"zh":{"q":"在 Ohio，白天什么时候必须开大灯？","o":["只在高速公路上","只在隧道里","白天从来不用","因为下雨或下雪而开雨刷时"],"h1":"想一想，开始下雨时你会打开什么。","h2":"在 Ohio，只要因为下雨、下雪或其他天气而使用雨刷，就必须开大灯；看不清楚的时候也必须开。","p":"对。下雨或下雪开雨刷，就要开大灯。"},"vi":{"q":"Ở Ohio, khi nào bạn phải bật đèn pha vào ban ngày?","o":["Chỉ trên xa lộ","Chỉ trong đường hầm","Không bao giờ vào ban ngày","Khi bạn bật cần gạt nước vì mưa hoặc tuyết"],"h1":"Hãy nghĩ xem bạn bật cái gì khi trời bắt đầu mưa.","h2":"Ở Ohio, bạn phải bật đèn pha mỗi khi dùng cần gạt nước vì mưa, tuyết hoặc thời tiết khác, và cả khi khó nhìn thấy.","p":"Đúng. Bật cần gạt nước vì mưa hoặc tuyết thì phải bật đèn pha."},"tl":{"q":"Sa Ohio, kailan dapat nakabukas ang headlights mo sa araw?","o":["Sa highway lang","Sa loob ng tunnel lang","Hindi kailanman sa araw","Kapag nakabukas ang wipers mo dahil sa ulan o niyebe"],"h1":"Isipin kung ano ang binubuksan mo kapag nagsimulang umulan.","h2":"Sa Ohio, dapat nakabukas ang headlights mo tuwing ginagamit ang windshield wipers dahil sa ulan, niyebe o ibang panahon, at pati kapag mahirap makakita.","p":"Tama. Kapag bukas ang wipers dahil sa ulan o niyebe, bukas din ang headlights."},"ar":{"q":"في Ohio، متى يجب تشغيل المصابيح الأمامية أثناء النهار؟","o":["على الطريق السريع فقط","داخل الأنفاق فقط","أبدًا أثناء النهار","عندما تشغّل المسّاحات بسبب المطر أو الثلج"],"h1":"فكّر فيما تشغّله عندما يبدأ المطر.","h2":"في Ohio، يجب تشغيل المصابيح الأمامية كلما استخدمت مسّاحات الزجاج بسبب المطر أو الثلج أو أي طقس آخر، وأيضًا عندما تكون الرؤية صعبة.","p":"صحيح. المسّاحات تعمل بسبب المطر أو الثلج تعني أن المصابيح الأمامية تعمل."},"ref":{"doc":"OH","page":"§2"}},{"id":"oh-027","scope":"OH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Ohio, when are studded tires legal?","o":["From November 1 through April 15","All year","Only in January and February","Never"],"h1":"They are allowed only during the cold months, from late fall to mid-spring.","h2":"In Ohio, you may use studded tires only from November 1 to April 15.","p":"Right. November 1 through April 15."},"es":{"q":"En Ohio, ¿cuándo son legales las llantas con clavos?","o":["Del 1 de noviembre al 15 de abril","Todo el año","Solo en enero y febrero","Nunca"],"h1":"Se permiten solo en los meses fríos, desde fines del otoño hasta mediados de la primavera.","h2":"En Ohio, usted puede usar llantas con clavos solo del 1 de noviembre al 15 de abril.","p":"Correcto. Del 1 de noviembre al 15 de abril."},"zh":{"q":"在 Ohio，什么时候可以合法使用钉胎（studded tires）？","o":["从 11 月 1 日到 4 月 15 日","全年","只在 1 月和 2 月","永远不可以"],"h1":"只在寒冷的月份可以用，从深秋到春天中期。","h2":"在 Ohio，你只能在 11 月 1 日到 4 月 15 日之间使用钉胎。","p":"对。从 11 月 1 日到 4 月 15 日。"},"vi":{"q":"Ở Ohio, khi nào lốp xe có đinh (studded tires) là hợp pháp?","o":["Từ ngày 1 tháng 11 đến ngày 15 tháng 4","Cả năm","Chỉ trong tháng 1 và tháng 2","Không bao giờ"],"h1":"Chỉ được phép trong những tháng lạnh, từ cuối mùa thu đến giữa mùa xuân.","h2":"Ở Ohio, bạn chỉ được dùng lốp xe có đinh từ ngày 1 tháng 11 đến ngày 15 tháng 4.","p":"Đúng. Từ ngày 1 tháng 11 đến ngày 15 tháng 4."},"tl":{"q":"Sa Ohio, kailan legal ang studded tires?","o":["Mula Nobyembre 1 hanggang Abril 15","Buong taon","Sa Enero at Pebrero lang","Hindi kailanman"],"h1":"Pinapayagan lang ang mga ito sa malalamig na buwan, mula huling bahagi ng taglagas hanggang kalagitnaan ng tagsibol.","h2":"Sa Ohio, puwede kang gumamit ng studded tires mula Nobyembre 1 hanggang Abril 15 lang.","p":"Tama. Mula Nobyembre 1 hanggang Abril 15."},"ar":{"q":"في Ohio، متى تكون إطارات المسامير (studded tires) قانونية؟","o":["من 1 نوفمبر حتى 15 أبريل","طوال السنة","في يناير وفبراير فقط","أبدًا"],"h1":"مسموح بها فقط في الأشهر الباردة، من أواخر الخريف إلى منتصف الربيع.","h2":"في Ohio، يمكنك استعمال إطارات المسامير فقط من 1 نوفمبر إلى 15 أبريل.","p":"صحيح. من 1 نوفمبر حتى 15 أبريل."},"ref":{"doc":"OH","page":"§2"}},{"id":"oh-028","scope":"OH","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Ohio, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 25 feet","No closer than 50 feet"],"h1":"It is less than the 15 feet many other states use.","h2":"In Ohio you may not stop, park or stand a vehicle within 10 feet of a fire hydrant.","p":"Right. In Ohio, stay at least 10 feet from a fire hydrant."},"es":{"q":"En Ohio, ¿qué tan cerca de un hidrante de incendios puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 25 pies","No más cerca de 50 pies"],"h1":"Es menos que los 15 pies que usan muchos otros estados.","h2":"En Ohio usted no puede detenerse, estacionarse ni quedarse parado con un vehículo a menos de 10 pies de un hidrante de incendios.","p":"Correcto. En Ohio, quédese por lo menos a 10 pies de un hidrante."},"zh":{"q":"在 Ohio，你可以把车停在离消防栓多近的地方？","o":["不少于 5 英尺","不少于 10 英尺","不少于 25 英尺","不少于 50 英尺"],"h1":"它比很多其他州规定的 15 英尺要少。","h2":"在 Ohio，你不可以在离消防栓 10 英尺以内停车、泊车或停留。","p":"对。在 Ohio，要离消防栓至少 10 英尺。"},"vi":{"q":"Ở Ohio, bạn được đậu xe gần trụ nước cứu hỏa đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 25 feet","Không gần hơn 50 feet"],"h1":"Khoảng cách này ít hơn 15 feet mà nhiều tiểu bang khác dùng.","h2":"Ở Ohio, bạn không được dừng, đậu hoặc để xe đứng trong vòng 10 feet cách trụ nước cứu hỏa.","p":"Đúng. Ở Ohio, hãy cách trụ nước cứu hỏa ít nhất 10 feet."},"tl":{"q":"Sa Ohio, gaano kalapit sa fire hydrant ang puwede mong pagparadahan?","o":["Hindi lalapit sa 5 talampakan","Hindi lalapit sa 10 talampakan","Hindi lalapit sa 25 talampakan","Hindi lalapit sa 50 talampakan"],"h1":"Mas maikli ito sa 15 talampakan na ginagamit ng maraming ibang estado.","h2":"Sa Ohio, hindi ka puwedeng huminto, pumarada o magpatigil ng sasakyan sa loob ng 10 talampakan mula sa fire hydrant.","p":"Tama. Sa Ohio, lumayo nang hindi bababa sa 10 talampakan mula sa fire hydrant."},"ar":{"q":"في Ohio، ما أقرب مسافة يمكنك أن توقف فيها سيارتك من صنبور إطفاء الحريق؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 10 أقدام","ليس أقرب من 25 قدمًا","ليس أقرب من 50 قدمًا"],"h1":"هي أقل من 15 قدمًا التي تستخدمها ولايات كثيرة أخرى.","h2":"في Ohio لا يجوز لك أن تتوقف أو تركن أو تترك سيارتك واقفة على بُعد أقل من 10 أقدام من صنبور إطفاء الحريق.","p":"صحيح. في Ohio ابقَ على بُعد 10 أقدام على الأقل من صنبور إطفاء الحريق."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-029","scope":"OH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Ohio, what is the minimum following distance the driver manual tells you to keep behind the car ahead?","o":["Half a second","One second","Two seconds","Four seconds"],"h1":"Count \"one-thousand-one\" and keep going past three.","h2":"The Ohio driver manual says to stay at least four seconds behind the vehicle ahead, or one car length for every 10 mph.","p":"Right. Keep at least four seconds between you and the car ahead."},"es":{"q":"En Ohio, ¿cuál es la distancia mínima que el manual del conductor le pide mantener detrás del carro de adelante?","o":["Medio segundo","Un segundo","Dos segundos","Cuatro segundos"],"h1":"Cuente \"mil uno\" y siga más allá de tres.","h2":"El manual del conductor de Ohio dice que se mantenga por lo menos cuatro segundos detrás del vehículo de adelante, o el largo de un carro por cada 10 mph.","p":"Correcto. Mantenga por lo menos cuatro segundos entre usted y el carro de adelante."},"zh":{"q":"在 Ohio，驾驶手册要求你和前车至少保持多长的跟车距离？","o":["半秒","1 秒","2 秒","4 秒"],"h1":"数 “one-thousand-one”，数过 3 之后继续数。","h2":"Ohio 驾驶手册说，要和前车保持至少 4 秒的距离，或者每 10 mph 保持一个车身的长度。","p":"对。和前车之间至少保持 4 秒。"},"vi":{"q":"Ở Ohio, sổ tay lái xe bảo bạn giữ khoảng cách tối thiểu bao nhiêu với xe phía trước?","o":["Nửa giây","Một giây","Hai giây","Bốn giây"],"h1":"Đếm \"one-thousand-one\" và tiếp tục đếm qua số ba.","h2":"Sổ tay lái xe của Ohio nói phải ở cách xe phía trước ít nhất bốn giây, hoặc một thân xe cho mỗi 10 mph.","p":"Đúng. Hãy giữ ít nhất bốn giây giữa bạn và xe phía trước."},"tl":{"q":"Sa Ohio, ano ang pinakamaikling pagitan na sinasabi ng driver manual na panatilihin mo sa likod ng sasakyan sa unahan?","o":["Kalahating segundo","Isang segundo","Dalawang segundo","Apat na segundo"],"h1":"Magbilang ng \"one-thousand-one\" at ituloy lampas sa tatlo.","h2":"Sinasabi ng Ohio driver manual na manatili nang hindi bababa sa apat na segundo sa likod ng sasakyan sa unahan, o isang haba ng kotse sa bawat 10 mph.","p":"Tama. Panatilihin ang hindi bababa sa apat na segundo sa pagitan mo at ng kotse sa unahan."},"ar":{"q":"في Ohio، ما أقل مسافة يطلب منك دليل السائق أن تتركها خلف السيارة التي أمامك؟","o":["نصف ثانية","ثانية واحدة","ثانيتان","أربع ثوانٍ"],"h1":"عُدّ \"one-thousand-one\" واستمر في العدّ بعد الثلاثة.","h2":"يقول دليل السائق في Ohio أن تبقى خلف السيارة التي أمامك بأربع ثوانٍ على الأقل، أو بطول سيارة واحدة لكل 10 mph.","p":"صحيح. اترك أربع ثوانٍ على الأقل بينك وبين السيارة التي أمامك."},"ref":{"doc":"OH","page":"§8"}},{"id":"oh-030","scope":"OH","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Ohio, how much space should you keep between your car and a bicycle?","o":["At least 6 inches","At least 1 foot","At least 3 feet","At least 20 feet"],"h1":"It is about the length of a yardstick.","h2":"In Ohio you should keep a safety zone of at least three feet between your car and a bicycle.","p":"Right. Give a bicycle at least three feet of space."},"es":{"q":"En Ohio, ¿cuánto espacio debe dejar entre su carro y una bicicleta?","o":["Por lo menos 6 pulgadas","Por lo menos 1 pie","Por lo menos 3 pies","Por lo menos 20 pies"],"h1":"Es más o menos el largo de una regla de una yarda.","h2":"En Ohio usted debe mantener una zona de seguridad de por lo menos tres pies entre su carro y una bicicleta.","p":"Correcto. Deje por lo menos tres pies de espacio a una bicicleta."},"zh":{"q":"在 Ohio，你的车和自行车之间应该保持多大的空间？","o":["至少 6 英寸","至少 1 英尺","至少 3 英尺","至少 20 英尺"],"h1":"大约是一把码尺的长度。","h2":"在 Ohio，你的车和自行车之间应该保持至少 3 英尺的安全距离。","p":"对。给自行车至少 3 英尺的空间。"},"vi":{"q":"Ở Ohio, bạn nên giữ khoảng cách bao nhiêu giữa xe của bạn và xe đạp?","o":["Ít nhất 6 inch","Ít nhất 1 foot","Ít nhất 3 feet","Ít nhất 20 feet"],"h1":"Khoảng bằng chiều dài một cây thước yard.","h2":"Ở Ohio, bạn nên giữ một vùng an toàn ít nhất ba feet giữa xe của bạn và xe đạp.","p":"Đúng. Hãy chừa cho xe đạp ít nhất ba feet."},"tl":{"q":"Sa Ohio, gaano kalaking espasyo ang dapat mong panatilihin sa pagitan ng kotse mo at ng bisikleta?","o":["Hindi bababa sa 6 na pulgada","Hindi bababa sa 1 talampakan","Hindi bababa sa 3 talampakan","Hindi bababa sa 20 talampakan"],"h1":"Halos kasinghaba ito ng isang yardstick.","h2":"Sa Ohio, dapat kang magpanatili ng safety zone na hindi bababa sa tatlong talampakan sa pagitan ng kotse mo at ng bisikleta.","p":"Tama. Bigyan ang bisikleta ng hindi bababa sa tatlong talampakan na espasyo."},"ar":{"q":"في Ohio، ما المسافة التي يجب أن تتركها بين سيارتك والدراجة الهوائية؟","o":["6 بوصات على الأقل","قدم واحدة على الأقل","3 أقدام على الأقل","20 قدمًا على الأقل"],"h1":"هي تقريبًا طول مسطرة الياردة.","h2":"في Ohio يجب أن تترك منطقة أمان لا تقل عن ثلاثة أقدام بين سيارتك والدراجة الهوائية.","p":"صحيح. اترك للدراجة الهوائية مسافة ثلاثة أقدام على الأقل."},"ref":{"doc":"OH","page":"§9"}},{"id":"oh-031","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, after you pass the vision screening and knowledge test, how long do you have to buy your temporary instruction permit?","o":["60 days","7 days","1 year","2 years"],"h1":"It is about two months.","h2":"In Ohio you must buy your temporary instruction permit within 60 days of passing the tests, or you have to take the vision screening and knowledge test again.","p":"Right. Buy the permit within 60 days, or you start over."},"es":{"q":"En Ohio, después de pasar el examen de la vista y el examen de conocimientos, ¿cuánto tiempo tiene para comprar su permiso temporal de instrucción?","o":["60 días","7 días","1 año","2 años"],"h1":"Son más o menos dos meses.","h2":"En Ohio usted debe comprar su permiso temporal de instrucción dentro de los 60 días después de pasar los exámenes, o tendrá que tomar de nuevo el examen de la vista y el de conocimientos.","p":"Correcto. Compre el permiso dentro de 60 días o tendrá que empezar de nuevo."},"zh":{"q":"在 Ohio，通过视力检查和知识考试后，你有多长时间去购买临时学习驾照？","o":["60 天","7 天","1 年","2 年"],"h1":"大约是两个月。","h2":"在 Ohio，你必须在通过考试后 60 天内购买临时学习驾照，否则要重新参加视力检查和知识考试。","p":"对。在 60 天内购买学习驾照，否则要从头再来。"},"vi":{"q":"Ở Ohio, sau khi bạn đậu bài kiểm tra thị lực và bài thi kiến thức, bạn có bao lâu để mua giấy phép tập lái tạm thời?","o":["60 ngày","7 ngày","1 năm","2 năm"],"h1":"Khoảng hai tháng.","h2":"Ở Ohio, bạn phải mua giấy phép tập lái tạm thời trong vòng 60 ngày sau khi đậu các bài thi, nếu không bạn phải thi lại bài kiểm tra thị lực và bài thi kiến thức.","p":"Đúng. Hãy mua giấy phép trong vòng 60 ngày, nếu không bạn phải bắt đầu lại."},"tl":{"q":"Sa Ohio, pagkatapos mong pumasa sa vision screening at knowledge test, gaano katagal ang mayroon ka para bilhin ang temporary instruction permit mo?","o":["60 araw","7 araw","1 taon","2 taon"],"h1":"Mga dalawang buwan ito.","h2":"Sa Ohio, dapat mong bilhin ang temporary instruction permit mo sa loob ng 60 araw mula nang pumasa ka sa mga test, o kailangan mong kumuha ulit ng vision screening at knowledge test.","p":"Tama. Bilhin ang permit sa loob ng 60 araw, o magsisimula ka ulit."},"ar":{"q":"في Ohio، بعد أن تنجح في فحص النظر واختبار المعرفة، كم لديك من الوقت لشراء تصريح التعلّم المؤقت؟","o":["60 يومًا","7 أيام","سنة واحدة","سنتان"],"h1":"هي تقريبًا شهران.","h2":"في Ohio يجب أن تشتري تصريح التعلّم المؤقت خلال 60 يومًا من نجاحك في الاختبارات، وإلا يجب أن تعيد فحص النظر واختبار المعرفة.","p":"صحيح. اشترِ التصريح خلال 60 يومًا، وإلا تبدأ من جديد."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-032","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, a driver who is 21 or older fails the driving test. What must they usually do before the second try?","o":["Wait one year","Take a short adult driver training course","Retake the knowledge test","Nothing; they may test again the next day"],"h1":"Ohio wants adults who fail to get some extra training first.","h2":"In Ohio, a driver 21 or older who fails the driving test must take an Abbreviated Adult Driver Training Course before testing again, unless they finished an approved driver education course within the past year.","p":"Right. Adults who fail take a short training course first."},"es":{"q":"En Ohio, un conductor de 21 años o más no pasa el examen de manejo. ¿Qué debe hacer normalmente antes del segundo intento?","o":["Esperar un año","Tomar un curso corto de manejo para adultos","Repetir el examen de conocimientos","Nada; puede volver a intentarlo al día siguiente"],"h1":"Ohio quiere que los adultos que no pasan reciban un poco más de entrenamiento primero.","h2":"En Ohio, un conductor de 21 años o más que no pasa el examen de manejo debe tomar un curso abreviado de manejo para adultos antes de volver a intentarlo, a menos que haya terminado un curso aprobado de educación vial en el último año.","p":"Correcto. Los adultos que no pasan toman primero un curso corto."},"ref":{"doc":"OH","page":"§11"}},{"id":"oh-033","scope":"OH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Ohio, a driver takes a chemical test after an arrest and the result is 0.08 or higher, for the first time. How long is the license suspended right away?","o":["One week","30 days","90 days","Five years"],"h1":"It is shorter than the suspension for refusing the test.","h2":"In Ohio, a first chemical test over the legal limit brings an administrative license suspension of three months, or 90 days.","p":"Right. A first test over the limit means a 90-day suspension."},"es":{"q":"En Ohio, un conductor arrestado se hace una prueba química y el resultado es 0.08 o más, por primera vez. ¿Por cuánto tiempo le suspenden la licencia de inmediato?","o":["Una semana","30 días","90 días","Cinco años"],"h1":"Es menos que la suspensión por negarse a la prueba.","h2":"En Ohio, la primera prueba química por encima del límite legal trae una suspensión administrativa de la licencia por tres meses, es decir, 90 días.","p":"Correcto. La primera prueba por encima del límite significa 90 días de suspensión."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-034","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, what happens to a driver under 18 who is convicted of three moving violations?","o":["A warning letter","A 30-day license suspension","A three-month license suspension","A one-year license suspension"],"h1":"Two violations bring three months. A third one brings much more.","h2":"In Ohio, a driver under 18 who is convicted of three moving violations gets an automatic one-year license suspension.","p":"Right. Three moving violations mean a year without a license."},"es":{"q":"En Ohio, ¿qué le pasa a un conductor menor de 18 años condenado por tres infracciones de tránsito en movimiento?","o":["Una carta de advertencia","Una suspensión de la licencia por 30 días","Una suspensión de la licencia por tres meses","Una suspensión de la licencia por un año"],"h1":"Dos infracciones traen tres meses. Una tercera trae mucho más.","h2":"En Ohio, un conductor menor de 18 años condenado por tres infracciones en movimiento recibe una suspensión automática de la licencia por un año.","p":"Correcto. Tres infracciones significan un año sin licencia."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-035","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, what fine can a driver get for driving while the license is suspended?","o":["Up to $1,000","Up to $50","Up to $150","No fine, only a warning"],"h1":"It is a serious crime, a first-degree misdemeanor.","h2":"In Ohio, driving with a suspended license is a first-degree misdemeanor with a fine of up to $1,000, and the license can be suspended for one more year.","p":"Right. Up to $1,000, and maybe another year of suspension."},"es":{"q":"En Ohio, ¿qué multa puede recibir un conductor por manejar con la licencia suspendida?","o":["Hasta $1,000","Hasta $50","Hasta $150","Ninguna multa, solo una advertencia"],"h1":"Es un delito serio, un delito menor de primer grado.","h2":"En Ohio, manejar con la licencia suspendida es un delito menor de primer grado con una multa de hasta $1,000, y la licencia puede quedar suspendida un año más.","p":"Correcto. Hasta $1,000, y tal vez un año más de suspensión."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-036","scope":"OH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Ohio, up to what age should children ride in the back seat?","o":["Age 4 and younger","Age 8 and younger","Age 12 and younger","Age 16 and younger"],"h1":"Front air bags can hurt children until they are about to become teenagers.","h2":"In Ohio, children age 12 and younger should ride in the back seat so a front air bag cannot hurt them in a crash.","p":"Right. Age 12 and younger ride in the back."},"es":{"q":"En Ohio, ¿hasta qué edad deben viajar los niños en el asiento trasero?","o":["Hasta los 4 años","Hasta los 8 años","Hasta los 12 años","Hasta los 16 años"],"h1":"Las bolsas de aire delanteras pueden lastimar a los niños hasta casi la adolescencia.","h2":"En Ohio, los niños de 12 años o menos deben viajar en el asiento trasero para que una bolsa de aire delantera no los lastime en un choque.","p":"Correcto. Los niños de 12 años o menos van atrás."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-037","scope":"OH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Ohio, a driver under 18 is caught using a phone while driving for the first time. What is the penalty?","o":["Only a warning","A 60-day license suspension and a $150 fine","A $25 fine","Two points, with no suspension"],"h1":"Teens lose the license for about two months.","h2":"In Ohio, a first phone violation by a driver under 18 brings a 60-day license suspension and a $150 fine.","p":"Right. 60 days without a license and a $150 fine."},"es":{"q":"En Ohio, a un conductor menor de 18 años lo detienen por primera vez por usar el teléfono al manejar. ¿Cuál es la sanción?","o":["Solo una advertencia","Una suspensión de la licencia por 60 días y una multa de $150","Una multa de $25","Dos puntos, sin suspensión"],"h1":"Los adolescentes pierden la licencia por unos dos meses.","h2":"En Ohio, la primera infracción por usar el teléfono de un conductor menor de 18 años trae una suspensión de la licencia por 60 días y una multa de $150.","p":"Correcto. 60 días sin licencia y una multa de $150."},"ref":{"doc":"OH","page":"§3"}},{"id":"oh-038","scope":"OH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Ohio, what happens to the fine for a hand-held phone offense in a work zone?","o":["It is cut in half","It stays the same","It becomes only a warning","It is doubled"],"h1":"Work zones protect road workers, so the penalty goes up.","h2":"In Ohio, the fine for using a hand-held phone while driving is doubled if it happens in a work zone.","p":"Right. In a work zone, the phone fine is doubled."},"es":{"q":"En Ohio, ¿qué pasa con la multa por usar el teléfono en la mano en una zona de obras?","o":["Se reduce a la mitad","Queda igual","Se convierte solo en una advertencia","Se duplica"],"h1":"Las zonas de obras protegen a los trabajadores, así que la sanción sube.","h2":"En Ohio, la multa por usar el teléfono en la mano al manejar se duplica si ocurre en una zona de obras.","p":"Correcto. En una zona de obras, la multa por el teléfono se duplica."},"ref":{"doc":"OH","page":"§3"}},{"id":"oh-039","scope":"OH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Ohio, what is the smallest tread depth a safe tire should have?","o":["One-sixteenth of an inch","One-half of an inch","One inch","Two inches"],"h1":"It is very thin. You can check it with a penny.","h2":"In Ohio, a safe tire must have at least one-sixteenth of an inch of tread depth and no major bumps or bulges.","p":"Right. At least one-sixteenth of an inch of tread."},"es":{"q":"En Ohio, ¿cuál es la profundidad mínima de la banda de rodadura que debe tener una llanta segura?","o":["Un dieciseisavo de pulgada","Media pulgada","Una pulgada","Dos pulgadas"],"h1":"Es muy poca. La puede revisar con una moneda de un centavo.","h2":"En Ohio, una llanta segura debe tener al menos un dieciseisavo de pulgada de profundidad en la banda de rodadura y no tener bultos grandes.","p":"Correcto. Al menos un dieciseisavo de pulgada de banda."},"ref":{"doc":"OH","page":"§2"}},{"id":"oh-040","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, a qualified driver who is 30 years old renews the license. What is the longest license they can choose?","o":["2 years","4 years","8 years","12 years"],"h1":"Drivers from 21 up to 65 may choose twice the usual length.","h2":"In Ohio, a qualified driver who is at least 21 but not yet 65 may buy an 8-year license; otherwise the license lasts 4 years.","p":"Right. Drivers 21 to 64 can choose an 8-year license."},"es":{"q":"En Ohio, un conductor que cumple los requisitos y tiene 30 años renueva su licencia. ¿Cuál es la licencia más larga que puede elegir?","o":["2 años","4 años","8 años","12 años"],"h1":"Los conductores de 21 a 65 años pueden elegir el doble del plazo normal.","h2":"En Ohio, un conductor que cumple los requisitos y tiene al menos 21 años pero menos de 65 puede comprar una licencia de 8 años; si no, la licencia dura 4 años.","p":"Correcto. De 21 a 64 años se puede elegir una licencia de 8 años."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-041","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, a parent co-signs a teen's license application. Until when is the parent also responsible for damage the teen causes while driving?","o":["Only while the teen has a permit","Until the teen turns 18","Until the teen turns 21","For the rest of the teen's life"],"h1":"It ends when the teen becomes an adult.","h2":"In Ohio, a parent or guardian who co-signs a minor's license application shares liability for damage the minor causes while driving until the minor's 18th birthday.","p":"Right. The co-signer is responsible until the teen turns 18."},"es":{"q":"En Ohio, un padre firma como codeudor la solicitud de licencia de su hijo adolescente. ¿Hasta cuándo es el padre también responsable por los daños que cause el joven al manejar?","o":["Solo mientras el joven tiene el permiso","Hasta que el joven cumpla 18 años","Hasta que el joven cumpla 21 años","Por el resto de la vida del joven"],"h1":"Termina cuando el joven llega a la mayoría de edad.","h2":"En Ohio, el padre o tutor que firma la solicitud de licencia de un menor comparte la responsabilidad por los daños que el menor cause al manejar hasta que el menor cumpla 18 años.","p":"Correcto. El codeudor es responsable hasta que el joven cumpla 18 años."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-042","scope":"OH","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Ohio, a school bus is stopped with red lights flashing on a road with fewer than four lanes. How far from the bus must you stop?","o":["At least 10 feet","At least 2 feet","At least 50 feet","At least 100 feet"],"h1":"It is less than the length of one car.","h2":"In Ohio, on a road with fewer than four lanes, traffic from both directions must stop at least 10 feet from the front or back of a stopped school bus.","p":"Right. Stop at least 10 feet from the bus."},"es":{"q":"En Ohio, un autobús escolar está detenido con las luces rojas intermitentes en una carretera de menos de cuatro carriles. ¿A qué distancia del autobús debe detenerse?","o":["Al menos a 10 pies","Al menos a 2 pies","Al menos a 50 pies","Al menos a 100 pies"],"h1":"Es menos que el largo de un carro.","h2":"En Ohio, en una carretera de menos de cuatro carriles, el tráfico de los dos sentidos debe detenerse al menos a 10 pies del frente o de la parte de atrás de un autobús escolar detenido.","p":"Correcto. Deténgase al menos a 10 pies del autobús."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-043","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, a driver under 21 fails the driving test. How long must they wait before testing again?","o":["One hour","One week","One month","Two days"],"h1":"It is a very short wait, just a little longer than for the knowledge test.","h2":"In Ohio, a driver under 21 who fails the driving test must wait two days before taking it again.","p":"Right. Wait two days, then try again."},"es":{"q":"En Ohio, un conductor menor de 21 años no pasa el examen de manejo. ¿Cuánto tiempo debe esperar para volver a intentarlo?","o":["Una hora","Una semana","Un mes","Dos días"],"h1":"Es una espera muy corta, solo un poco más que para el examen de conocimientos.","h2":"En Ohio, un conductor menor de 21 años que no pasa el examen de manejo debe esperar dos días para volver a tomarlo.","p":"Correcto. Espere dos días y vuelva a intentarlo."},"ref":{"doc":"OH","page":"§11"}},{"id":"oh-044","scope":"OH","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Ohio, besides at night and in bad weather, when must your headlights be on?","o":["When you cannot see clearly 500 feet ahead","When you cannot see clearly 1,000 feet ahead","When you cannot see clearly 200 feet ahead","When you cannot see clearly 100 feet ahead"],"h1":"The distance is a round number, about the length of three football fields.","h2":"In Ohio, your headlights must be on any time the light is too poor to see things clearly 1,000 feet ahead.","p":"Right. If you cannot see 1,000 feet ahead, turn your headlights on."},"es":{"q":"En Ohio, además de la noche y el mal tiempo, ¿cuándo deben estar encendidas sus luces delanteras?","o":["Cuando no puede ver bien a 500 pies adelante","Cuando no puede ver bien a 1,000 pies adelante","Cuando no puede ver bien a 200 pies adelante","Cuando no puede ver bien a 100 pies adelante"],"h1":"La distancia es un número redondo, como el largo de tres campos de fútbol americano.","h2":"En Ohio, las luces delanteras deben estar encendidas siempre que la luz no permita ver bien las cosas a 1,000 pies adelante.","p":"Correcto. Si no puede ver a 1,000 pies adelante, encienda las luces."},"ref":{"doc":"OH","page":"§7"}},{"id":"oh-045","scope":"OH","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Ohio, an orange and red triangle is on the back of a farm tractor. What does it tell you?","o":["The vehicle is going less than 45 mph","The vehicle is going less than 35 mph","The vehicle is going less than 25 mph","The vehicle is about to turn left"],"h1":"It is the slow-moving vehicle sign. Think of a speed slower than most town streets.","h2":"In Ohio, the orange and red slow-moving vehicle triangle means the vehicle travels at less than 25 mph.","p":"Right. The triangle means less than 25 mph."},"es":{"q":"En Ohio, un tractor agrícola lleva atrás un triángulo anaranjado y rojo. ¿Qué le indica?","o":["El vehículo va a menos de 45 mph","El vehículo va a menos de 35 mph","El vehículo va a menos de 25 mph","El vehículo está por doblar a la izquierda"],"h1":"Es la señal de vehículo lento. Piense en una velocidad menor que la de la mayoría de las calles del pueblo.","h2":"En Ohio, el triángulo anaranjado y rojo de vehículo lento significa que el vehículo va a menos de 25 mph.","p":"Correcto. El triángulo significa menos de 25 mph."},"ref":{"doc":"OH","page":"§9"}},{"id":"oh-046","scope":"OH","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Ohio, when may you cross a solid yellow line to pass a slow-moving vehicle?","o":["When it goes less than half the speed limit, there is clear room, and you stay within the limit","Any time it goes slower than you","Never, for any reason","Only at night"],"h1":"The vehicle must be very slow, and you must still pass safely and legally.","h2":"In Ohio, you may cross a solid yellow line to pass a slow-moving vehicle only if it is going less than half the posted speed limit, the oncoming lane is clear enough, and you do not go over the speed limit.","p":"Right. Less than half the limit, clear room, and no speeding."},"es":{"q":"En Ohio, ¿cuándo puede cruzar una línea amarilla continua para rebasar a un vehículo lento?","o":["Cuando va a menos de la mitad del límite de velocidad, hay espacio libre y usted no pasa el límite","Siempre que vaya más despacio que usted","Nunca, por ninguna razón","Solo de noche"],"h1":"El vehículo debe ir muy despacio, y usted debe rebasar de forma segura y legal.","h2":"En Ohio, usted puede cruzar una línea amarilla continua para rebasar a un vehículo lento solo si este va a menos de la mitad del límite de velocidad, el carril contrario tiene suficiente espacio libre y usted no pasa el límite de velocidad.","p":"Correcto. Menos de la mitad del límite, espacio libre y sin exceso de velocidad."},"ref":{"doc":"OH","page":"§9"}},{"id":"oh-047","scope":"OH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Ohio, a loaded truck is going 55 mph in ideal conditions. About how much distance does it need to stop?","o":["About 50 feet","About 100 feet","About 150 feet","At least 335 feet"],"h1":"It needs more than one and a half times what a car needs.","h2":"The Ohio driver manual says a loaded truck at 55 mph needs at least 335 feet to stop, so never cut in front of one.","p":"Right. At least 335 feet, so do not cut in front of a truck."},"es":{"q":"En Ohio, un camión cargado va a 55 mph en condiciones ideales. ¿Más o menos qué distancia necesita para detenerse?","o":["Unos 50 pies","Unos 100 pies","Unos 150 pies","Al menos 335 pies"],"h1":"Necesita más de una vez y media lo que necesita un carro.","h2":"El manual de manejo de Ohio dice que un camión cargado a 55 mph necesita al menos 335 pies para detenerse, así que nunca se le meta adelante.","p":"Correcto. Al menos 335 pies, así que no se meta delante de un camión."},"ref":{"doc":"OH","page":"§9"}},{"id":"oh-048","scope":"OH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Ohio, your car breaks down on the road. If you have flares, where should you put them?","o":["Right next to your car","About 20 to 30 feet behind your car","About 200 to 300 feet behind your car","In front of your car only"],"h1":"Put them far enough back that drivers have time to change lanes.","h2":"In Ohio, if your car breaks down, place flares about 200 to 300 feet behind it so other drivers have time to move over.","p":"Right. About 200 to 300 feet behind the car."},"es":{"q":"En Ohio, su carro se descompone en la carretera. Si tiene bengalas, ¿dónde debe ponerlas?","o":["Justo al lado de su carro","Unos 20 a 30 pies detrás de su carro","Unos 200 a 300 pies detrás de su carro","Solo delante de su carro"],"h1":"Póngalas lo bastante lejos para que los conductores tengan tiempo de cambiarse de carril.","h2":"En Ohio, si su carro se descompone, ponga bengalas unos 200 a 300 pies detrás de él para que los demás conductores tengan tiempo de cambiarse de carril.","p":"Correcto. Unos 200 a 300 pies detrás del carro."},"ref":{"doc":"OH","page":"§10"}},{"id":"oh-049","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, when does a driver license issued to someone under 21 expire?","o":["On the driver's 21st birthday","On the driver's 18th birthday","Eight years after it is issued","It never expires"],"h1":"It ends on a birthday that also ends the under-21 rules.","h2":"In Ohio, a driver license issued to someone under 21 expires on their 21st birthday and must be renewed in person.","p":"Right. It expires on your 21st birthday."},"es":{"q":"En Ohio, ¿cuándo vence una licencia de conducir dada a una persona menor de 21 años?","o":["El día que el conductor cumple 21 años","El día que el conductor cumple 18 años","Ocho años después de emitida","Nunca vence"],"h1":"Vence en un cumpleaños que también pone fin a las reglas para menores de 21.","h2":"En Ohio, una licencia de conducir dada a una persona menor de 21 años vence el día que cumple 21 años y se debe renovar en persona.","p":"Correcto. Vence el día que cumple 21 años."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-050","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, what is the youngest age to apply for a moped license?","o":["12","14","15 and a half","16"],"h1":"It is younger than the age for a car permit.","h2":"In Ohio, you can apply for a moped license at age 14, and riders who are 14 or 15 may ride only in daylight.","p":"Right. A moped license starts at 14."},"es":{"q":"En Ohio, ¿cuál es la edad mínima para solicitar una licencia de ciclomotor (moped)?","o":["12","14","15 y medio","16"],"h1":"Es menos que la edad para el permiso de carro.","h2":"En Ohio, usted puede solicitar una licencia de ciclomotor (moped) a los 14 años, y quienes tienen 14 o 15 años solo pueden manejarlo de día.","p":"Correcto. La licencia de ciclomotor empieza a los 14 años."},"ref":{"doc":"OH","page":"§12"}},{"id":"ok-001","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, how many questions are on the written exam for a learner permit?","o":["10","20","30","50"],"h1":"It is a short test, fewer than in many states.","h2":"In Oklahoma, the written exam for a learner permit has 20 questions.","p":"Right. The Oklahoma written exam has 20 questions."},"es":{"q":"En Oklahoma, ¿cuántas preguntas tiene el examen escrito para el permiso de aprendiz?","o":["10","20","30","50"],"h1":"Es un examen corto, con menos preguntas que en muchos estados.","h2":"En Oklahoma, el examen escrito para el permiso de aprendiz tiene 20 preguntas.","p":"Correcto. El examen escrito de Oklahoma tiene 20 preguntas."},"zh":{"q":"在 Oklahoma，学习驾照（learner permit）的笔试有多少道题？","o":["10","20","30","50"],"h1":"它是一个短的考试，比很多州的题少。","h2":"在 Oklahoma，学习驾照的笔试有 20 道题。","p":"对。Oklahoma 的笔试有 20 道题。"},"vi":{"q":"Ở Oklahoma, bài thi viết để lấy giấy phép tập lái (learner permit) có bao nhiêu câu hỏi?","o":["10","20","30","50"],"h1":"Đây là bài thi ngắn, ít câu hơn so với nhiều tiểu bang khác.","h2":"Ở Oklahoma, bài thi viết để lấy giấy phép tập lái có 20 câu hỏi.","p":"Đúng. Bài thi viết ở Oklahoma có 20 câu hỏi."},"tl":{"q":"Sa Oklahoma, ilang tanong ang nasa written exam para sa learner permit?","o":["10","20","30","50"],"h1":"Maikli ang test na ito, mas kaunti kaysa sa maraming estado.","h2":"Sa Oklahoma, may 20 tanong ang written exam para sa learner permit.","p":"Tama. May 20 tanong ang written exam sa Oklahoma."},"ar":{"q":"في Oklahoma، كم سؤالًا في الاختبار الكتابي للحصول على تصريح التعلّم (learner permit)؟","o":["10","20","30","50"],"h1":"هو اختبار قصير، فيه أسئلة أقل من ولايات كثيرة.","h2":"في Oklahoma، الاختبار الكتابي للحصول على تصريح التعلّم فيه 20 سؤالًا.","p":"صحيح. الاختبار الكتابي في Oklahoma فيه 20 سؤالًا."},"ref":{"doc":"OK","page":null}},{"id":"ok-002","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, what must a 15-year-old be doing to get a learner permit?","o":["Working a part-time job","Nothing extra; age is enough","Holding a high school diploma","Taking an approved driver education course"],"h1":"At 15 you are still learning in a class.","h2":"In Oklahoma, a 15-year-old must be enrolled in and taking an approved driver education course, and must pass the written exam, to get a learner permit.","p":"Right. At 15, driver education comes first."},"es":{"q":"En Oklahoma, ¿qué debe estar haciendo un joven de 15 años para obtener un permiso de aprendiz?","o":["Tener un trabajo de medio tiempo","Nada más; la edad es suficiente","Tener diploma de secundaria","Tomar un curso aprobado de educación vial"],"h1":"A los 15 años usted todavía está aprendiendo en una clase.","h2":"En Oklahoma, un joven de 15 años debe estar inscrito y tomando un curso aprobado de educación vial, y aprobar el examen escrito, para obtener el permiso de aprendiz.","p":"Correcto. A los 15, primero va la educación vial."},"zh":{"q":"在 Oklahoma，15 岁的青少年要拿学习驾照，必须正在做什么？","o":["做兼职工作","不用做别的，年龄够就行","有高中毕业证","上认可的驾驶教育课程"],"h1":"15 岁时你还在上课学习。","h2":"在 Oklahoma，15 岁的青少年必须报名并正在上认可的驾驶教育课程，还要通过笔试，才能拿学习驾照。","p":"对。15 岁时，先要上驾驶教育。"},"vi":{"q":"Ở Oklahoma, người 15 tuổi phải đang làm gì để lấy giấy phép tập lái (learner permit)?","o":["Đang làm việc bán thời gian","Không cần gì thêm; đủ tuổi là được","Đã có bằng tốt nghiệp trung học","Đang học một khóa giáo dục lái xe (driver education) được chấp thuận"],"h1":"Ở tuổi 15, bạn vẫn còn đang học trong một lớp học.","h2":"Ở Oklahoma, người 15 tuổi phải đã đăng ký và đang học một khóa giáo dục lái xe được chấp thuận, và phải đậu bài thi viết, để lấy giấy phép tập lái.","p":"Đúng. Ở tuổi 15, phải học giáo dục lái xe trước."},"tl":{"q":"Sa Oklahoma, ano ang dapat ginagawa ng isang 15 taong gulang para makakuha ng learner permit?","o":["Nagtatrabaho nang part-time","Wala nang iba; sapat na ang edad","May high school diploma","Kumukuha ng aprobadong kurso sa driver education"],"h1":"Sa edad na 15, nag-aaral ka pa sa isang klase.","h2":"Sa Oklahoma, ang isang 15 taong gulang ay dapat naka-enroll at kumukuha ng aprobadong kurso sa driver education, at dapat pumasa sa written exam, para makakuha ng learner permit.","p":"Tama. Sa edad na 15, driver education muna."},"ar":{"q":"في Oklahoma، ماذا يجب أن يفعل من عمره 15 سنة للحصول على تصريح التعلّم (learner permit)؟","o":["أن يعمل في وظيفة بدوام جزئي","لا شيء إضافي؛ العمر يكفي","أن يحمل شهادة الثانوية","أن يدرس في دورة تعليم قيادة (driver education) معتمدة"],"h1":"في عمر 15 سنة ما زلت تتعلّم في صف دراسي.","h2":"في Oklahoma، يجب على من عمره 15 سنة أن يكون مسجّلًا في دورة تعليم قيادة معتمدة ويدرس فيها، وأن ينجح في الاختبار الكتابي، للحصول على تصريح التعلّم.","p":"صحيح. في عمر 15 سنة يأتي تعليم القيادة أولًا."},"ref":{"doc":"OK","page":6}},{"id":"ok-003","scope":"OK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oklahoma, is driver education required for a 16-year-old to get a learner permit?","o":["No, it is optional at 16","Yes, always","Yes, and you must pass the road test first","No, and you may drive alone right away"],"h1":"At 16 one requirement drops away.","h2":"In Oklahoma, driver education is optional at 16. You still pass the written exam, unless a finished driver education course lets you skip it.","p":"Right. At 16, driver education is optional."},"es":{"q":"En Oklahoma, ¿se requiere educación vial para que un joven de 16 años obtenga un permiso de aprendiz?","o":["No, es opcional a los 16","Sí, siempre","Sí, y primero debe aprobar el examen de manejo","No, y puede manejar solo de inmediato"],"h1":"A los 16 se quita un requisito.","h2":"En Oklahoma, la educación vial es opcional a los 16 años. Usted todavía debe aprobar el examen escrito, a menos que un curso de educación vial terminado le permita omitirlo.","p":"Correcto. A los 16, la educación vial es opcional."},"zh":{"q":"在 Oklahoma，16 岁的青少年拿学习驾照需要上驾驶教育吗？","o":["不需要，16 岁时可以选择上或不上","需要，一直都需要","需要，而且必须先通过路考","不需要，而且马上就可以自己开车"],"h1":"16 岁时少了一个要求。","h2":"在 Oklahoma，16 岁时驾驶教育可以选择上或不上。你仍然要通过笔试，除非你上完了驾驶教育课程，可以不用考。","p":"对。16 岁时，驾驶教育可以选择上或不上。"},"vi":{"q":"Ở Oklahoma, người 16 tuổi có bắt buộc phải học giáo dục lái xe (driver education) để lấy giấy phép tập lái không?","o":["Không, ở tuổi 16 thì không bắt buộc","Có, luôn luôn bắt buộc","Có, và bạn phải đậu bài thi lái xe trên đường trước","Không, và bạn có thể lái một mình ngay"],"h1":"Ở tuổi 16, có một yêu cầu không còn nữa.","h2":"Ở Oklahoma, giáo dục lái xe không bắt buộc ở tuổi 16. Bạn vẫn phải đậu bài thi viết, trừ khi đã học xong một khóa giáo dục lái xe cho phép bạn bỏ qua bài thi này.","p":"Đúng. Ở tuổi 16, giáo dục lái xe không bắt buộc."},"tl":{"q":"Sa Oklahoma, kailangan ba ang driver education para makakuha ng learner permit ang isang 16 taong gulang?","o":["Hindi, hindi ito kailangan sa edad na 16","Oo, palagi","Oo, at dapat ka munang pumasa sa road test","Hindi, at puwede ka nang magmaneho nang mag-isa agad"],"h1":"Sa edad na 16, nawawala ang isang kailangan.","h2":"Sa Oklahoma, hindi kailangan ang driver education sa edad na 16. Kailangan mo pa ring pumasa sa written exam, maliban kung may natapos kang kurso sa driver education na nagpapahintulot na laktawan ito.","p":"Tama. Sa edad na 16, hindi kailangan ang driver education."},"ar":{"q":"في Oklahoma، هل تعليم القيادة (driver education) مطلوب لمن عمره 16 سنة للحصول على تصريح التعلّم؟","o":["لا، هو اختياري في عمر 16 سنة","نعم، دائمًا","نعم، ويجب أن تنجح في اختبار القيادة على الطريق أولًا","لا، ويمكنك أن تقود وحدك فورًا"],"h1":"في عمر 16 سنة يسقط أحد الشروط.","h2":"في Oklahoma، تعليم القيادة اختياري في عمر 16 سنة. وما زال عليك أن تنجح في الاختبار الكتابي، إلا إذا أنهيت دورة تعليم قيادة تسمح لك بتخطّيه.","p":"صحيح. في عمر 16 سنة، تعليم القيادة اختياري."},"ref":{"doc":"OK","page":6}},{"id":"ok-004","scope":"OK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oklahoma, during which hours may a learner permit holder drive?","o":["Any time of day","6:00 a.m. to 9:00 p.m.","5:00 a.m. to 10:00 p.m.","Daylight hours only"],"h1":"The window starts very early and ends at ten.","h2":"In Oklahoma, a learner permit holder may drive between 5:00 in the morning and 10:00 at night, with a licensed driver at least 21 years old.","p":"Right. Oklahoma learners drive from 5 a.m. to 10 p.m."},"es":{"q":"En Oklahoma, ¿en qué horario puede manejar una persona con permiso de aprendiz?","o":["A cualquier hora","De 6:00 a.m. a 9:00 p.m.","De 5:00 a.m. a 10:00 p.m.","Solo con luz del día"],"h1":"El horario empieza muy temprano y termina a las diez.","h2":"En Oklahoma, quien tiene permiso de aprendiz puede manejar entre las 5:00 de la mañana y las 10:00 de la noche, con un conductor con licencia de por lo menos 21 años.","p":"Correcto. Los aprendices en Oklahoma manejan de 5 a.m. a 10 p.m."},"zh":{"q":"在 Oklahoma，学习驾照持有人在什么时间可以开车？","o":["白天晚上任何时间","早上 6:00 到晚上 9:00","早上 5:00 到晚上 10:00","只能在白天"],"h1":"可以开车的时间很早开始，到十点结束。","h2":"在 Oklahoma，学习驾照持有人可以在早上 5:00 到晚上 10:00 之间开车，要有一位至少 21 岁、有驾照的司机陪同。","p":"对。Oklahoma 的学员从早上 5 点开到晚上 10 点。"},"vi":{"q":"Ở Oklahoma, người có giấy phép tập lái được lái xe trong những giờ nào?","o":["Bất cứ giờ nào trong ngày","6:00 sáng đến 9:00 tối","5:00 sáng đến 10:00 tối","Chỉ khi trời sáng"],"h1":"Khung giờ bắt đầu rất sớm và kết thúc lúc mười giờ.","h2":"Ở Oklahoma, người có giấy phép tập lái được lái xe từ 5:00 sáng đến 10:00 tối, cùng với một người có bằng lái từ 21 tuổi trở lên.","p":"Đúng. Người tập lái ở Oklahoma được lái từ 5 giờ sáng đến 10 giờ tối."},"tl":{"q":"Sa Oklahoma, sa anong mga oras puwedeng magmaneho ang may hawak ng learner permit?","o":["Kahit anong oras","6:00 a.m. hanggang 9:00 p.m.","5:00 a.m. hanggang 10:00 p.m.","Kapag maliwanag lang"],"h1":"Napakaaga nagsisimula ang oras at natatapos ito nang alas-diyes.","h2":"Sa Oklahoma, puwedeng magmaneho ang may hawak ng learner permit mula 5:00 ng umaga hanggang 10:00 ng gabi, kasama ang isang lisensiyadong driver na hindi bababa sa 21 taong gulang.","p":"Tama. Nagmamaneho ang mga learner sa Oklahoma mula 5 a.m. hanggang 10 p.m."},"ar":{"q":"في Oklahoma، في أي ساعات يمكن لحامل تصريح التعلّم أن يقود؟","o":["في أي وقت من اليوم","من 6:00 صباحًا إلى 9:00 مساءً","من 5:00 صباحًا إلى 10:00 مساءً","في ساعات النهار فقط"],"h1":"الفترة تبدأ مبكرًا جدًا وتنتهي في الساعة العاشرة.","h2":"في Oklahoma، يمكن لحامل تصريح التعلّم أن يقود بين الساعة 5:00 صباحًا والساعة 10:00 مساءً، مع سائق مرخّص عمره 21 سنة على الأقل.","p":"صحيح. المتعلّمون في Oklahoma يقودون من 5 صباحًا إلى 10 مساءً."},"ref":{"doc":"OK","page":null}},{"id":"ok-005","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, how old must the licensed driver with a learner permit holder be?","o":["At least 18","At least 21","At least 25","At least 30"],"h1":"The supervisor must be old enough to drink legally.","h2":"In Oklahoma, a learner permit holder must drive with a licensed driver who is at least 21 years old.","p":"Right. The supervisor must be 21 or older."},"es":{"q":"En Oklahoma, ¿qué edad debe tener el conductor con licencia que acompaña a quien tiene permiso de aprendiz?","o":["Por lo menos 18","Por lo menos 21","Por lo menos 25","Por lo menos 30"],"h1":"El supervisor debe tener edad para tomar alcohol legalmente.","h2":"En Oklahoma, quien tiene permiso de aprendiz debe manejar con un conductor con licencia de por lo menos 21 años.","p":"Correcto. El supervisor debe tener 21 años o más."},"zh":{"q":"在 Oklahoma，陪同学习驾照持有人的有驾照司机必须几岁？","o":["至少 18 岁","至少 21 岁","至少 25 岁","至少 30 岁"],"h1":"监督的人必须到了可以合法喝酒的年龄。","h2":"在 Oklahoma，学习驾照持有人必须和一位至少 21 岁、有驾照的司机一起开车。","p":"对。监督的人必须 21 岁或以上。"},"vi":{"q":"Ở Oklahoma, người có bằng lái đi cùng người có giấy phép tập lái phải bao nhiêu tuổi?","o":["Ít nhất 18 tuổi","Ít nhất 21 tuổi","Ít nhất 25 tuổi","Ít nhất 30 tuổi"],"h1":"Người giám sát phải đủ tuổi để uống rượu hợp pháp.","h2":"Ở Oklahoma, người có giấy phép tập lái phải lái xe cùng một người có bằng lái từ 21 tuổi trở lên.","p":"Đúng. Người giám sát phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Oklahoma, ilang taon dapat ang lisensiyadong driver na kasama ng may hawak ng learner permit?","o":["Hindi bababa sa 18","Hindi bababa sa 21","Hindi bababa sa 25","Hindi bababa sa 30"],"h1":"Dapat sapat ang edad ng nagbabantay para legal na uminom ng alak.","h2":"Sa Oklahoma, ang may hawak ng learner permit ay dapat magmaneho kasama ang isang lisensiyadong driver na hindi bababa sa 21 taong gulang.","p":"Tama. Dapat 21 taong gulang pataas ang nagbabantay."},"ar":{"q":"في Oklahoma، كم يجب أن يكون عمر السائق المرخّص الذي يرافق حامل تصريح التعلّم؟","o":["18 سنة على الأقل","21 سنة على الأقل","25 سنة على الأقل","30 سنة على الأقل"],"h1":"يجب أن يكون المشرف في عمر يسمح له قانونيًا بشرب الكحول.","h2":"في Oklahoma، يجب على حامل تصريح التعلّم أن يقود مع سائق مرخّص عمره 21 سنة على الأقل.","p":"صحيح. يجب أن يكون عمر المشرف 21 سنة أو أكثر."},"ref":{"doc":"OK","page":6}},{"id":"ok-006","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, how many hours of supervised driving must a teen complete before the intermediate license?","o":["20 hours, including 5 at night","30 hours, including 10 at night","60 hours, including 15 at night","50 hours, including 10 at night"],"h1":"It is half of one hundred, with 10 of them at night.","h2":"In Oklahoma, a teen must complete 50 hours of supervised driving, including 10 hours at night, before getting an intermediate license.","p":"Right. 50 hours, 10 at night."},"es":{"q":"En Oklahoma, ¿cuántas horas de manejo supervisado debe completar un joven antes de la licencia intermedia?","o":["20 horas, 5 de ellas de noche","30 horas, 10 de ellas de noche","60 horas, 15 de ellas de noche","50 horas, 10 de ellas de noche"],"h1":"Es la mitad de cien, con 10 de ellas de noche.","h2":"En Oklahoma, un joven debe completar 50 horas de manejo supervisado, 10 de ellas de noche, antes de obtener la licencia intermedia.","p":"Correcto. 50 horas, 10 de noche."},"zh":{"q":"在 Oklahoma，青少年拿中级驾照（intermediate license）前，必须完成多少小时有人监督的驾驶？","o":["20 小时，其中 5 小时在晚上","30 小时，其中 10 小时在晚上","60 小时，其中 15 小时在晚上","50 小时，其中 10 小时在晚上"],"h1":"它是一百的一半，其中 10 小时在晚上。","h2":"在 Oklahoma，青少年拿中级驾照前必须完成 50 小时有人监督的驾驶，其中 10 小时在晚上。","p":"对。50 小时，10 小时在晚上。"},"vi":{"q":"Ở Oklahoma, thiếu niên phải lái xe có giám sát bao nhiêu giờ trước khi lấy bằng lái trung gian (intermediate license)?","o":["20 giờ, gồm 5 giờ ban đêm","30 giờ, gồm 10 giờ ban đêm","60 giờ, gồm 15 giờ ban đêm","50 giờ, gồm 10 giờ ban đêm"],"h1":"Đó là một nửa của một trăm, trong đó có 10 giờ ban đêm.","h2":"Ở Oklahoma, thiếu niên phải lái xe có giám sát 50 giờ, gồm 10 giờ ban đêm, trước khi lấy bằng lái trung gian.","p":"Đúng. 50 giờ, có 10 giờ ban đêm."},"tl":{"q":"Sa Oklahoma, ilang oras ng pagmamaneho na may nagbabantay ang dapat makumpleto ng isang teen bago ang intermediate license?","o":["20 oras, kasama ang 5 sa gabi","30 oras, kasama ang 10 sa gabi","60 oras, kasama ang 15 sa gabi","50 oras, kasama ang 10 sa gabi"],"h1":"Kalahati ito ng isang daan, at 10 dito ay sa gabi.","h2":"Sa Oklahoma, dapat makumpleto ng isang teen ang 50 oras ng pagmamaneho na may nagbabantay, kasama ang 10 oras sa gabi, bago makakuha ng intermediate license.","p":"Tama. 50 oras, 10 dito sa gabi."},"ar":{"q":"في Oklahoma، كم ساعة من القيادة تحت الإشراف يجب أن يُكملها المراهق قبل الرخصة المتوسطة (intermediate license)؟","o":["20 ساعة، منها 5 في الليل","30 ساعة، منها 10 في الليل","60 ساعة، منها 15 في الليل","50 ساعة، منها 10 في الليل"],"h1":"هو نصف المئة، و10 منها في الليل.","h2":"في Oklahoma، يجب أن يُكمل المراهق 50 ساعة من القيادة تحت الإشراف، منها 10 ساعات في الليل، قبل الحصول على الرخصة المتوسطة.","p":"صحيح. 50 ساعة، منها 10 في الليل."},"ref":{"doc":"OK","page":null}},{"id":"ok-007","scope":"OK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oklahoma, how long must a teen hold a learner permit before getting an intermediate license?","o":["About 6 months (180 days)","30 days","1 year","2 years"],"h1":"It is half a year.","h2":"In Oklahoma, a teen must hold the learner permit for at least 180 days, about six months, before getting an intermediate license.","p":"Right. 180 days with the permit first."},"es":{"q":"En Oklahoma, ¿cuánto tiempo debe tener un joven el permiso de aprendiz antes de obtener la licencia intermedia?","o":["Unos 6 meses (180 días)","30 días","1 año","2 años"],"h1":"Es medio año.","h2":"En Oklahoma, un joven debe tener el permiso de aprendiz por lo menos 180 días, unos seis meses, antes de obtener la licencia intermedia.","p":"Correcto. Primero 180 días con el permiso."},"zh":{"q":"在 Oklahoma，青少年拿中级驾照前，必须持有学习驾照多久？","o":["大约 6 个月（180 天）","30 天","1 年","2 年"],"h1":"它是半年。","h2":"在 Oklahoma，青少年必须持有学习驾照至少 180 天，大约六个月，才能拿中级驾照。","p":"对。先持有学习驾照 180 天。"},"vi":{"q":"Ở Oklahoma, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái trung gian (intermediate license)?","o":["Khoảng 6 tháng (180 ngày)","30 ngày","1 năm","2 năm"],"h1":"Đó là nửa năm.","h2":"Ở Oklahoma, thiếu niên phải giữ giấy phép tập lái ít nhất 180 ngày, khoảng sáu tháng, trước khi lấy bằng lái trung gian.","p":"Đúng. Phải giữ giấy phép tập lái 180 ngày trước."},"tl":{"q":"Sa Oklahoma, gaano katagal dapat hawak ng isang teen ang learner permit bago makakuha ng intermediate license?","o":["Mga 6 na buwan (180 araw)","30 araw","1 taon","2 taon"],"h1":"Kalahating taon ito.","h2":"Sa Oklahoma, dapat hawak ng isang teen ang learner permit nang hindi bababa sa 180 araw, mga anim na buwan, bago makakuha ng intermediate license.","p":"Tama. 180 araw muna na hawak ang permit."},"ar":{"q":"في Oklahoma، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل الحصول على الرخصة المتوسطة (intermediate license)؟","o":["حوالي 6 أشهر (180 يومًا)","30 يومًا","سنة واحدة","سنتان"],"h1":"هي نصف سنة.","h2":"في Oklahoma، يجب أن يحمل المراهق تصريح التعلّم 180 يومًا على الأقل، أي حوالي ستة أشهر، قبل الحصول على الرخصة المتوسطة.","p":"صحيح. 180 يومًا مع التصريح أولًا."},"ref":{"doc":"OK","page":6}},{"id":"ok-008","scope":"OK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oklahoma, during which hours may an intermediate license holder not drive alone, unless an exception applies?","o":["Midnight to 5:00 a.m.","9:00 p.m. to 6:00 a.m.","10:00 p.m. to 5:00 a.m.","There is no night limit"],"h1":"It starts at the same hour the learner permit day ends.","h2":"In Oklahoma, an intermediate license holder may not drive alone between 10:00 at night and 5:00 in the morning, unless an exception such as work, school or church applies.","p":"Right. No solo driving from 10 p.m. to 5 a.m."},"es":{"q":"En Oklahoma, ¿en qué horario no puede manejar solo quien tiene licencia intermedia, salvo una excepción?","o":["De medianoche a 5:00 a.m.","De 9:00 p.m. a 6:00 a.m.","De 10:00 p.m. a 5:00 a.m.","No hay límite de noche"],"h1":"Empieza a la misma hora en que termina el día del permiso de aprendiz.","h2":"En Oklahoma, quien tiene licencia intermedia no puede manejar solo entre las 10:00 de la noche y las 5:00 de la mañana, salvo una excepción como trabajo, escuela o iglesia.","p":"Correcto. No se maneja solo de 10 p.m. a 5 a.m."},"zh":{"q":"在 Oklahoma，除非有例外情况，中级驾照持有人在哪个时间段不能自己开车？","o":["午夜到早上 5:00","晚上 9:00 到早上 6:00","晚上 10:00 到早上 5:00","晚上没有限制"],"h1":"它开始的时间，和学习驾照可以开车的时间结束得一样。","h2":"在 Oklahoma，中级驾照持有人在晚上 10:00 到早上 5:00 之间不能自己开车，除非有例外情况，比如上班、上学或去教堂。","p":"对。晚上 10 点到早上 5 点不能自己开车。"},"vi":{"q":"Ở Oklahoma, người có bằng lái trung gian (intermediate license) không được lái xe một mình trong những giờ nào, trừ khi có trường hợp ngoại lệ?","o":["Nửa đêm đến 5:00 sáng","9:00 tối đến 6:00 sáng","10:00 tối đến 5:00 sáng","Không có giới hạn ban đêm"],"h1":"Nó bắt đầu đúng vào giờ mà ngày lái của giấy phép tập lái kết thúc.","h2":"Ở Oklahoma, người có bằng lái trung gian không được lái xe một mình từ 10:00 tối đến 5:00 sáng, trừ khi có ngoại lệ như đi làm, đi học hoặc đi nhà thờ.","p":"Đúng. Không lái một mình từ 10 giờ tối đến 5 giờ sáng."},"tl":{"q":"Sa Oklahoma, sa anong mga oras hindi puwedeng magmaneho nang mag-isa ang may hawak ng intermediate license, maliban kung may exception?","o":["Hatinggabi hanggang 5:00 a.m.","9:00 p.m. hanggang 6:00 a.m.","10:00 p.m. hanggang 5:00 a.m.","Walang limitasyon sa gabi"],"h1":"Nagsisimula ito sa parehong oras kung kailan natatapos ang araw ng learner permit.","h2":"Sa Oklahoma, hindi puwedeng magmaneho nang mag-isa ang may hawak ng intermediate license mula 10:00 ng gabi hanggang 5:00 ng umaga, maliban kung may exception gaya ng trabaho, paaralan o simbahan.","p":"Tama. Bawal magmaneho nang mag-isa mula 10 p.m. hanggang 5 a.m."},"ar":{"q":"في Oklahoma، في أي ساعات لا يجوز لحامل الرخصة المتوسطة (intermediate license) أن يقود وحده، إلا إذا وُجد استثناء؟","o":["من منتصف الليل إلى 5:00 صباحًا","من 9:00 مساءً إلى 6:00 صباحًا","من 10:00 مساءً إلى 5:00 صباحًا","لا يوجد حدّ في الليل"],"h1":"تبدأ في نفس الساعة التي ينتهي فيها يوم تصريح التعلّم.","h2":"في Oklahoma، لا يجوز لحامل الرخصة المتوسطة أن يقود وحده بين الساعة 10:00 مساءً والساعة 5:00 صباحًا، إلا إذا وُجد استثناء مثل العمل أو المدرسة أو الكنيسة.","p":"صحيح. لا قيادة وحدك من 10 مساءً إلى 5 صباحًا."},"ref":{"doc":"OK","page":14}},{"id":"ok-009","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, how many passengers who do not live in the driver's home may an intermediate license holder carry, without a supervising driver?","o":["None","One","Two","Three"],"h1":"Think of one friend, not a carload.","h2":"In Oklahoma, an intermediate license holder may carry only one passenger who does not live in the driver's home, unless a licensed driver 21 or older sits in the front seat.","p":"Right. Only one passenger from outside the home."},"es":{"q":"En Oklahoma, ¿cuántos pasajeros que no viven en la casa del conductor puede llevar alguien con licencia intermedia, sin un conductor supervisor?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Piense en un amigo, no en un carro lleno.","h2":"En Oklahoma, quien tiene licencia intermedia puede llevar solo un pasajero que no vive en su casa, a menos que un conductor con licencia de 21 años o más vaya en el asiento delantero.","p":"Correcto. Solo un pasajero de fuera de la casa."},"zh":{"q":"在 Oklahoma，没有监督司机时，中级驾照持有人可以载几位不住在司机家里的乘客？","o":["一位也不行","一位","两位","三位"],"h1":"想想一位朋友，不是一车人。","h2":"在 Oklahoma，中级驾照持有人只能载一位不住在司机家里的乘客，除非有一位 21 岁或以上、有驾照的司机坐在前排。","p":"对。只能载一位不住在家里的乘客。"},"vi":{"q":"Ở Oklahoma, khi không có người giám sát, người có bằng lái trung gian được chở bao nhiêu hành khách không sống chung nhà với người lái?","o":["Không ai","Một người","Hai người","Ba người"],"h1":"Hãy nghĩ đến một người bạn, không phải cả một xe đầy người.","h2":"Ở Oklahoma, người có bằng lái trung gian chỉ được chở một hành khách không sống chung nhà với người lái, trừ khi có một người có bằng lái từ 21 tuổi trở lên ngồi ở ghế trước.","p":"Đúng. Chỉ một hành khách không sống chung nhà."},"tl":{"q":"Sa Oklahoma, ilang pasaherong hindi nakatira sa bahay ng driver ang puwedeng isakay ng may hawak ng intermediate license, kung walang nagbabantay na driver?","o":["Wala","Isa","Dalawa","Tatlo"],"h1":"Isipin ang isang kaibigan, hindi isang buong kotse.","h2":"Sa Oklahoma, isang pasahero lang na hindi nakatira sa bahay ng driver ang puwedeng isakay ng may hawak ng intermediate license, maliban kung may lisensiyadong driver na 21 taong gulang pataas na nakaupo sa harap.","p":"Tama. Isang pasahero lang mula sa labas ng bahay."},"ar":{"q":"في Oklahoma، كم راكبًا لا يعيشون في بيت السائق يمكن لحامل الرخصة المتوسطة أن ينقلهم، بدون سائق مشرف؟","o":["لا أحد","واحد","اثنان","ثلاثة"],"h1":"فكّر في صديق واحد، وليس في سيارة مليئة.","h2":"في Oklahoma، يمكن لحامل الرخصة المتوسطة أن ينقل راكبًا واحدًا فقط لا يعيش في بيت السائق، إلا إذا جلس في المقعد الأمامي سائق مرخّص عمره 21 سنة أو أكثر.","p":"صحيح. راكب واحد فقط من خارج البيت."},"ref":{"doc":"OK","page":14}},{"id":"ok-010","scope":"OK","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Oklahoma, may a driver read or send a text message on a hand-held phone while driving?","o":["Yes, at a slow speed","Yes, on rural roads","Yes, if the message is short","No, it is against the law"],"h1":"Since 2015, the answer is the same for all drivers.","h2":"In Oklahoma, it is against the law to text on a hand-held phone while driving.","p":"Right. Texting while driving is against the law in Oklahoma."},"es":{"q":"En Oklahoma, ¿puede un conductor leer o enviar un mensaje de texto con el teléfono en la mano mientras maneja?","o":["Sí, a baja velocidad","Sí, en caminos rurales","Sí, si el mensaje es corto","No, es ilegal"],"h1":"Desde 2015, la respuesta es la misma para todos los conductores.","h2":"En Oklahoma, es ilegal enviar o leer mensajes de texto en un teléfono en la mano mientras maneja.","p":"Correcto. En Oklahoma es ilegal enviar mensajes de texto mientras maneja."},"zh":{"q":"在 Oklahoma，司机开车时可以用手持手机看或发短信吗？","o":["可以，开得慢时","可以，在乡村道路上","可以，如果短信很短","不可以，这是违法的"],"h1":"从 2015 年起，所有司机的答案都一样。","h2":"在 Oklahoma，开车时用手持手机发短信是违法的。","p":"对。在 Oklahoma，开车时发短信是违法的。"},"vi":{"q":"Ở Oklahoma, người lái xe có được đọc hoặc gửi tin nhắn trên điện thoại cầm tay khi đang lái xe không?","o":["Có, khi chạy chậm","Có, trên đường nông thôn","Có, nếu tin nhắn ngắn","Không, điều đó là phạm luật"],"h1":"Từ năm 2015, câu trả lời giống nhau cho mọi người lái xe.","h2":"Ở Oklahoma, nhắn tin trên điện thoại cầm tay khi đang lái xe là phạm luật.","p":"Đúng. Nhắn tin khi lái xe là phạm luật ở Oklahoma."},"tl":{"q":"Sa Oklahoma, puwede bang magbasa o magpadala ng text message ang driver sa hawak na cellphone habang nagmamaneho?","o":["Oo, kapag mabagal","Oo, sa mga daan sa probinsiya","Oo, kung maikli ang mensahe","Hindi, labag ito sa batas"],"h1":"Mula 2015, pareho ang sagot para sa lahat ng driver.","h2":"Sa Oklahoma, labag sa batas ang mag-text sa hawak na cellphone habang nagmamaneho.","p":"Tama. Labag sa batas sa Oklahoma ang mag-text habang nagmamaneho."},"ar":{"q":"في Oklahoma، هل يجوز للسائق أن يقرأ أو يرسل رسالة نصية على هاتف محمول باليد أثناء القيادة؟","o":["نعم، بسرعة بطيئة","نعم، على الطرق الريفية","نعم، إذا كانت الرسالة قصيرة","لا، هذا مخالف للقانون"],"h1":"منذ سنة 2015، الجواب نفسه لكل السائقين.","h2":"في Oklahoma، كتابة الرسائل النصية على هاتف محمول باليد أثناء القيادة مخالفة للقانون.","p":"صحيح. كتابة الرسائل أثناء القيادة مخالفة للقانون في Oklahoma."},"ref":{"doc":"OK","page":61}},{"id":"ok-011","scope":"OK","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Oklahoma, what is the fine for a first violation of the Move Over law?","o":["$1,000","$50","$100","$250"],"h1":"Since late 2023 the fine is very high, with four digits.","h2":"In Oklahoma, a first violation of the Move Over law carries a fine of $1,000.","p":"Right. $1,000 for a first offense."},"es":{"q":"En Oklahoma, ¿cuál es la multa por una primera infracción de la ley Move Over (cámbiese de carril)?","o":["$1,000","$50","$100","$250"],"h1":"Desde finales de 2023 la multa es muy alta, de cuatro cifras.","h2":"En Oklahoma, una primera infracción de la ley Move Over tiene una multa de $1,000.","p":"Correcto. $1,000 por la primera infracción."},"zh":{"q":"在 Oklahoma，第一次违反让道变道法（Move Over law）罚款多少？","o":["$1,000","$50","$100","$250"],"h1":"从 2023 年底起，罚款很高，有四位数。","h2":"在 Oklahoma，第一次违反让道变道法（Move Over law）罚款 $1,000。","p":"对。第一次罚 $1,000。"},"vi":{"q":"Ở Oklahoma, tiền phạt cho lần vi phạm đầu tiên của luật Tránh Sang Làn Khác (Move Over law) là bao nhiêu?","o":["$1,000","$50","$100","$250"],"h1":"Từ cuối năm 2023, tiền phạt rất cao, có bốn chữ số.","h2":"Ở Oklahoma, lần vi phạm đầu tiên luật Tránh Sang Làn Khác (Move Over law) bị phạt $1,000.","p":"Đúng. $1,000 cho lần vi phạm đầu tiên."},"tl":{"q":"Sa Oklahoma, magkano ang multa sa unang paglabag sa Move Over law?","o":["$1,000","$50","$100","$250"],"h1":"Mula sa huling bahagi ng 2023, napakataas ng multa, may apat na digit.","h2":"Sa Oklahoma, ang unang paglabag sa Move Over law ay may multang $1,000.","p":"Tama. $1,000 para sa unang paglabag."},"ar":{"q":"في Oklahoma، ما الغرامة على المخالفة الأولى لقانون الابتعاد إلى حارة أخرى (Move Over law)؟","o":["$1,000","$50","$100","$250"],"h1":"منذ أواخر سنة 2023 الغرامة عالية جدًا، من أربعة أرقام.","h2":"في Oklahoma، المخالفة الأولى لقانون الابتعاد إلى حارة أخرى (Move Over law) عليها غرامة $1,000.","p":"صحيح. $1,000 على المخالفة الأولى."},"ref":{"doc":"OK","page":null}},{"id":"ok-012","scope":"OK","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Oklahoma, a school bus stops with red lights flashing on a four-lane road with a center turn lane and no median. Who must stop?","o":["Only traffic behind the bus","Only traffic in the lane next to the bus","All traffic in both directions","No one, because of the turn lane"],"h1":"A center turn lane is not a median.","h2":"In Oklahoma, on a road with four or more lanes and no median, traffic in both directions must stop for a stopped school bus, even if there is a center turn lane.","p":"Right. No median means everyone stops."},"es":{"q":"En Oklahoma, un autobús escolar se detiene con luces rojas intermitentes en una calle de cuatro carriles con carril central de vuelta y sin camellón. ¿Quién debe detenerse?","o":["Solo el tráfico detrás del autobús","Solo el tráfico en el carril junto al autobús","Todo el tráfico en ambas direcciones","Nadie, por el carril de vuelta"],"h1":"Un carril central de vuelta no es un camellón.","h2":"En Oklahoma, en una calle de cuatro carriles o más sin camellón, el tráfico en ambas direcciones debe detenerse ante un autobús escolar detenido, aunque haya un carril central de vuelta.","p":"Correcto. Sin camellón, todos se detienen."},"zh":{"q":"在 Oklahoma，一辆校车在一条有中间转弯车道、没有中间隔离带的四车道路上停下，闪着红灯。谁必须停车？","o":["只有校车后面的车","只有校车旁边车道的车","两个方向的所有车","谁都不用，因为有转弯车道"],"h1":"中间转弯车道不是中间隔离带。","h2":"在 Oklahoma，在四条或更多车道、没有中间隔离带的路上，两个方向的车都必须为停着的校车停车，就算有中间转弯车道也一样。","p":"对。没有中间隔离带，所有人都要停车。"},"vi":{"q":"Ở Oklahoma, một xe buýt trường học dừng lại với đèn đỏ nhấp nháy trên đường bốn làn có làn rẽ ở giữa và không có dải phân cách. Ai phải dừng lại?","o":["Chỉ xe phía sau xe buýt","Chỉ xe ở làn bên cạnh xe buýt","Tất cả xe ở cả hai chiều","Không ai, vì có làn rẽ"],"h1":"Làn rẽ ở giữa không phải là dải phân cách.","h2":"Ở Oklahoma, trên đường có bốn làn trở lên và không có dải phân cách, xe ở cả hai chiều phải dừng lại khi xe buýt trường học dừng, ngay cả khi có làn rẽ ở giữa.","p":"Đúng. Không có dải phân cách thì mọi người đều phải dừng."},"tl":{"q":"Sa Oklahoma, huminto ang isang school bus na kumikislap ang pulang ilaw sa daang may apat na lane, may center turn lane sa gitna at walang median. Sino ang dapat huminto?","o":["Ang mga sasakyan lang sa likod ng bus","Ang mga sasakyan lang sa lane na katabi ng bus","Lahat ng sasakyan sa dalawang direksiyon","Wala, dahil may turn lane"],"h1":"Hindi median ang center turn lane.","h2":"Sa Oklahoma, sa daang may apat o higit pang lane at walang median, dapat huminto ang mga sasakyan sa dalawang direksiyon para sa nakahintong school bus, kahit may center turn lane.","p":"Tama. Kapag walang median, lahat ay hihinto."},"ar":{"q":"في Oklahoma، توقّفت حافلة مدرسية وأضواؤها الحمراء تومض على طريق من أربع حارات فيه حارة انعطاف في الوسط ولا يوجد فاصل وسطي (median). من يجب أن يتوقّف؟","o":["السيارات خلف الحافلة فقط","السيارات في الحارة المجاورة للحافلة فقط","كل السيارات في الاتجاهين","لا أحد، بسبب حارة الانعطاف"],"h1":"حارة الانعطاف في الوسط ليست فاصلًا وسطيًا.","h2":"في Oklahoma، على طريق من أربع حارات أو أكثر بدون فاصل وسطي، يجب على السيارات في الاتجاهين أن تتوقّف للحافلة المدرسية المتوقّفة، حتى لو كانت هناك حارة انعطاف في الوسط.","p":"صحيح. لا فاصل وسطي يعني أن الجميع يتوقّف."},"ref":{"doc":"OK","page":30}},{"id":"ok-013","scope":"OK","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Oklahoma, a school bus stops with red lights flashing on a road with a median. What must traffic going the opposite way do?","o":["Stop until the lights go off","Keep moving with caution","Stop, then pass at once","Change lanes toward the bus"],"h1":"The median separates the two sides of the road.","h2":"In Oklahoma, when a road has a median, traffic going the opposite way from the school bus may keep moving with caution, while traffic going the same way must stop.","p":"Right. With a median, oncoming traffic may continue with care."},"es":{"q":"En Oklahoma, un autobús escolar se detiene con luces rojas intermitentes en una calle con camellón. ¿Qué debe hacer el tráfico que va en dirección contraria?","o":["Detenerse hasta que se apaguen las luces","Seguir con precaución","Detenerse y luego pasar de inmediato","Cambiarse de carril hacia el autobús"],"h1":"El camellón separa los dos lados de la calle.","h2":"En Oklahoma, cuando la calle tiene camellón, el tráfico que va en dirección contraria al autobús escolar puede seguir con precaución, y el que va en la misma dirección debe detenerse.","p":"Correcto. Con camellón, el tráfico de frente puede seguir con cuidado."},"zh":{"q":"在 Oklahoma，一辆校车在有中间隔离带的路上停下，闪着红灯。相反方向的车必须怎么做？","o":["停车，直到灯熄灭","小心地继续开","停车，然后马上超过去","换到靠近校车的车道"],"h1":"中间隔离带把道路的两边分开。","h2":"在 Oklahoma，如果道路有中间隔离带，和校车方向相反的车可以小心地继续开，和校车同方向的车必须停车。","p":"对。有中间隔离带时，对面来的车可以小心地继续开。"},"vi":{"q":"Ở Oklahoma, một xe buýt trường học dừng lại với đèn đỏ nhấp nháy trên đường có dải phân cách. Xe đi ngược chiều phải làm gì?","o":["Dừng lại cho đến khi đèn tắt","Tiếp tục chạy một cách cẩn thận","Dừng lại, rồi vượt qua ngay","Chuyển làn về phía xe buýt"],"h1":"Dải phân cách chia hai bên đường ra.","h2":"Ở Oklahoma, khi đường có dải phân cách, xe đi ngược chiều với xe buýt trường học có thể tiếp tục chạy một cách cẩn thận, còn xe đi cùng chiều phải dừng lại.","p":"Đúng. Có dải phân cách thì xe ngược chiều có thể tiếp tục chạy cẩn thận."},"tl":{"q":"Sa Oklahoma, huminto ang isang school bus na kumikislap ang pulang ilaw sa daang may median. Ano ang dapat gawin ng mga sasakyang papunta sa kabilang direksiyon?","o":["Huminto hanggang mamatay ang ilaw","Magpatuloy nang maingat","Huminto, tapos lumampas agad","Lumipat ng lane papunta sa bus"],"h1":"Pinaghihiwalay ng median ang dalawang panig ng daan.","h2":"Sa Oklahoma, kapag may median ang daan, puwedeng magpatuloy nang maingat ang mga sasakyang papunta sa kabilang direksiyon ng school bus, pero dapat huminto ang mga sasakyang papunta sa parehong direksiyon.","p":"Tama. Kapag may median, puwedeng magpatuloy nang maingat ang mga paparating na sasakyan."},"ar":{"q":"في Oklahoma، توقّفت حافلة مدرسية وأضواؤها الحمراء تومض على طريق فيه فاصل وسطي (median). ماذا يجب أن تفعل السيارات القادمة من الاتجاه المعاكس؟","o":["تتوقّف حتى تنطفئ الأضواء","تستمر في السير بحذر","تتوقّف، ثم تتجاوز فورًا","تغيّر الحارة نحو الحافلة"],"h1":"الفاصل الوسطي يفصل بين جانبي الطريق.","h2":"في Oklahoma، عندما يكون في الطريق فاصل وسطي، يمكن للسيارات القادمة من الاتجاه المعاكس للحافلة المدرسية أن تستمر في السير بحذر، أما السيارات في نفس اتجاه الحافلة فيجب أن تتوقّف.","p":"صحيح. مع وجود فاصل وسطي، يمكن للسيارات القادمة أن تستمر بحذر."},"ref":{"doc":"OK","page":30}},{"id":"ok-014","scope":"OK","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Oklahoma, what is the speed limit on a turnpike when no other limit is posted?","o":["65 mph","70 mph","80 mph","85 mph"],"h1":"Turnpikes have the highest limit in the state chart.","h2":"In Oklahoma, the speed limit on a turnpike is 80 mph unless a sign shows a different limit.","p":"Right. Oklahoma turnpikes allow 80 mph unless posted otherwise."},"es":{"q":"En Oklahoma, ¿cuál es el límite de velocidad en una autopista de peaje (turnpike) cuando no hay otro límite señalado?","o":["65 mph","70 mph","80 mph","85 mph"],"h1":"Las autopistas de peaje tienen el límite más alto de la tabla del estado.","h2":"En Oklahoma, el límite de velocidad en una autopista de peaje es de 80 mph, a menos que una señal indique otro límite.","p":"Correcto. En las autopistas de peaje de Oklahoma se permite 80 mph, salvo que se indique otra cosa."},"zh":{"q":"在 Oklahoma，如果没有标出别的限速，收费公路（turnpike）的限速是多少？","o":["65 mph","70 mph","80 mph","85 mph"],"h1":"在州的限速表里，收费公路的限速最高。","h2":"在 Oklahoma，收费公路的限速是 80 mph，除非标志写着别的限速。","p":"对。Oklahoma 的收费公路限速是 80 mph，除非标志写着别的。"},"vi":{"q":"Ở Oklahoma, tốc độ tối đa trên đường cao tốc thu phí (turnpike) là bao nhiêu khi không có biển báo giới hạn khác?","o":["65 mph","70 mph","80 mph","85 mph"],"h1":"Đường cao tốc thu phí có giới hạn cao nhất trong bảng của tiểu bang.","h2":"Ở Oklahoma, tốc độ tối đa trên đường cao tốc thu phí là 80 mph, trừ khi có biển báo ghi giới hạn khác.","p":"Đúng. Đường cao tốc thu phí ở Oklahoma cho phép 80 mph, trừ khi có biển báo khác."},"tl":{"q":"Sa Oklahoma, ano ang speed limit sa turnpike kapag walang ibang limit na nakapaskil?","o":["65 mph","70 mph","80 mph","85 mph"],"h1":"Ang turnpike ang may pinakamataas na limit sa listahan ng estado.","h2":"Sa Oklahoma, 80 mph ang speed limit sa turnpike maliban kung may sign na nagpapakita ng ibang limit.","p":"Tama. Puwede ang 80 mph sa mga turnpike sa Oklahoma maliban kung iba ang nakapaskil."},"ar":{"q":"في Oklahoma، ما حدّ السرعة على الطريق السريع ذي الرسوم (turnpike) عندما لا توجد لافتة بحدّ آخر؟","o":["65 mph","70 mph","80 mph","85 mph"],"h1":"الطرق السريعة ذات الرسوم لها أعلى حدّ في جدول الولاية.","h2":"في Oklahoma، حدّ السرعة على الطريق السريع ذي الرسوم هو 80 mph، إلا إذا كانت هناك لافتة تُظهر حدًّا آخر.","p":"صحيح. الطرق السريعة ذات الرسوم في Oklahoma تسمح بـ 80 mph إلا إذا كانت هناك لافتة بحدّ آخر."},"ref":{"doc":"OK","page":41}},{"id":"ok-015","scope":"OK","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Oklahoma, what is the speed limit on a county road when no sign is posted?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"It is lower than the limit on an undivided state highway.","h2":"In Oklahoma, the speed limit on a county road is 55 mph when no other limit is posted.","p":"Right. On Oklahoma county roads the limit is 55 mph unless posted otherwise."},"es":{"q":"En Oklahoma, ¿cuál es el límite de velocidad en un camino del condado cuando no hay señal?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Es menor que el límite en una carretera estatal no dividida.","h2":"En Oklahoma, el límite de velocidad en un camino del condado es de 55 mph cuando no hay otro límite señalado.","p":"Correcto. En los caminos del condado de Oklahoma el límite es de 55 mph, salvo que se indique otra cosa."},"zh":{"q":"在 Oklahoma，如果没有限速标志，县道（county road）的限速是多少？","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"它比没有中间隔离带的州公路的限速低。","h2":"在 Oklahoma，如果没有标出别的限速，县道的限速是 55 mph。","p":"对。Oklahoma 县道的限速是 55 mph，除非标志写着别的。"},"vi":{"q":"Ở Oklahoma, tốc độ tối đa trên đường quận (county road) là bao nhiêu khi không có biển báo?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Nó thấp hơn giới hạn trên đường tiểu bang không có dải phân cách.","h2":"Ở Oklahoma, tốc độ tối đa trên đường quận là 55 mph khi không có biển báo giới hạn khác.","p":"Đúng. Trên đường quận ở Oklahoma, giới hạn là 55 mph, trừ khi có biển báo khác."},"tl":{"q":"Sa Oklahoma, ano ang speed limit sa county road kapag walang sign na nakapaskil?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Mas mababa ito kaysa sa limit sa state highway na walang divider.","h2":"Sa Oklahoma, 55 mph ang speed limit sa county road kapag walang ibang limit na nakapaskil.","p":"Tama. Sa mga county road sa Oklahoma, 55 mph ang limit maliban kung iba ang nakapaskil."},"ar":{"q":"في Oklahoma، ما حدّ السرعة على طريق المقاطعة (county road) عندما لا توجد لافتة؟","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"هو أقل من الحدّ على طريق الولاية السريع الذي ليس فيه فاصل وسطي.","h2":"في Oklahoma، حدّ السرعة على طريق المقاطعة هو 55 mph عندما لا توجد لافتة بحدّ آخر.","p":"صحيح. على طرق المقاطعات في Oklahoma الحدّ هو 55 mph إلا إذا كانت هناك لافتة بحدّ آخر."},"ref":{"doc":"OK","page":41}},{"id":"ok-016","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, how many points on your driving record will lead to a license suspension?","o":["6 or more in 1 year","10 or more in 5 years","8 or more in 5 years","15 or more in 10 years"],"h1":"Count the points over several years, not just one.","h2":"In Oklahoma, your license will be suspended if you get 10 or more points within 5 years.","p":"Right. 10 or more points in 5 years means a suspension in Oklahoma."},"es":{"q":"En Oklahoma, ¿cuántos puntos en su historial de manejo causan la suspensión de la licencia?","o":["6 o más en 1 año","10 o más en 5 años","8 o más en 5 años","15 o más en 10 años"],"h1":"Los puntos se cuentan durante varios años, no solo uno.","h2":"En Oklahoma, su licencia será suspendida si acumula 10 puntos o más en 5 años.","p":"Correcto. 10 puntos o más en 5 años significan una suspensión en Oklahoma."},"zh":{"q":"在 Oklahoma，驾驶记录上有多少分会导致驾照被暂停？","o":["1 年内 6 分或更多","5 年内 10 分或更多","5 年内 8 分或更多","10 年内 15 分或更多"],"h1":"要算好几年里的分数，不只是一年。","h2":"在 Oklahoma，如果你在 5 年内被记 10 分或更多，你的驾照会被暂停。","p":"对。在 Oklahoma，5 年内 10 分或更多就会被暂停驾照。"},"vi":{"q":"Ở Oklahoma, bao nhiêu điểm trong hồ sơ lái xe sẽ dẫn đến việc bị treo bằng lái?","o":["6 điểm trở lên trong 1 năm","10 điểm trở lên trong 5 năm","8 điểm trở lên trong 5 năm","15 điểm trở lên trong 10 năm"],"h1":"Hãy đếm điểm trong nhiều năm, không chỉ một năm.","h2":"Ở Oklahoma, bằng lái của bạn sẽ bị treo nếu bạn bị 10 điểm trở lên trong vòng 5 năm.","p":"Đúng. Ở Oklahoma, 10 điểm trở lên trong 5 năm nghĩa là bị treo bằng."},"tl":{"q":"Sa Oklahoma, ilang puntos sa driving record mo ang magdudulot ng suspensiyon ng lisensiya?","o":["6 o higit pa sa loob ng 1 taon","10 o higit pa sa loob ng 5 taon","8 o higit pa sa loob ng 5 taon","15 o higit pa sa loob ng 10 taon"],"h1":"Bilangin ang puntos sa loob ng ilang taon, hindi lang isa.","h2":"Sa Oklahoma, masususpinde ang lisensiya mo kung makakuha ka ng 10 o higit pang puntos sa loob ng 5 taon.","p":"Tama. Sa Oklahoma, ang 10 o higit pang puntos sa loob ng 5 taon ay nangangahulugang suspensiyon."},"ar":{"q":"في Oklahoma، كم نقطة في سجلّ قيادتك تؤدي إلى إيقاف الرخصة؟","o":["6 نقاط أو أكثر خلال سنة واحدة","10 نقاط أو أكثر خلال 5 سنوات","8 نقاط أو أكثر خلال 5 سنوات","15 نقطة أو أكثر خلال 10 سنوات"],"h1":"احسب النقاط على مدى عدة سنوات، وليس سنة واحدة فقط.","h2":"في Oklahoma، سيتم إيقاف رخصتك إذا حصلت على 10 نقاط أو أكثر خلال 5 سنوات.","p":"صحيح. في Oklahoma، 10 نقاط أو أكثر خلال 5 سنوات تعني إيقاف الرخصة."},"ref":{"doc":"OK","page":71}},{"id":"ok-017","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, how many points are added to your record for not stopping for a school bus that is loading or unloading?","o":["1 point","2 points","3 points","4 points"],"h1":"It is one of the most serious offenses on the point list.","h2":"In Oklahoma, failing to stop for a school bus that is loading or unloading adds 4 points to your record.","p":"Right. Not stopping for a loading school bus costs 4 points in Oklahoma."},"es":{"q":"En Oklahoma, ¿cuántos puntos se agregan a su historial por no detenerse ante un autobús escolar que sube o baja estudiantes?","o":["1 punto","2 puntos","3 puntos","4 puntos"],"h1":"Es una de las faltas más graves de la lista de puntos.","h2":"En Oklahoma, no detenerse ante un autobús escolar que sube o baja estudiantes agrega 4 puntos a su historial.","p":"Correcto. No detenerse ante un autobús escolar cuesta 4 puntos en Oklahoma."},"zh":{"q":"在 Oklahoma，校车正在上下学生时你没有停车，记录上会加几分？","o":["1 分","2 分","3 分","4 分"],"h1":"这是记分表上最严重的违规之一。","h2":"在 Oklahoma，校车正在上下学生时没有停车，你的记录上会加 4 分。","p":"对。在 Oklahoma，校车上下学生时不停车要扣 4 分。"},"vi":{"q":"Ở Oklahoma, nếu không dừng lại khi xe buýt trường học đang cho học sinh lên hoặc xuống, bạn bị cộng bao nhiêu điểm vào hồ sơ?","o":["1 điểm","2 điểm","3 điểm","4 điểm"],"h1":"Đây là một trong những vi phạm nghiêm trọng nhất trong danh sách tính điểm.","h2":"Ở Oklahoma, không dừng lại khi xe buýt trường học đang cho học sinh lên hoặc xuống sẽ bị cộng 4 điểm vào hồ sơ của bạn.","p":"Đúng. Ở Oklahoma, không dừng cho xe buýt trường học đang đón trả học sinh bị 4 điểm."},"tl":{"q":"Sa Oklahoma, ilang puntos ang idinadagdag sa iyong record kapag hindi ka huminto para sa school bus na nagsasakay o nagbababa ng mga bata?","o":["1 puntos","2 puntos","3 puntos","4 puntos"],"h1":"Isa ito sa pinakamabibigat na paglabag sa listahan ng puntos.","h2":"Sa Oklahoma, ang hindi paghinto para sa school bus na nagsasakay o nagbababa ng mga bata ay nagdadagdag ng 4 na puntos sa iyong record.","p":"Tama. Sa Oklahoma, 4 na puntos ang hindi paghinto para sa school bus na nagsasakay o nagbababa."},"ar":{"q":"في Oklahoma، كم نقطة تُضاف إلى سجلّك إذا لم تتوقّف لحافلة مدرسية يصعد إليها الطلاب أو ينزلون منها؟","o":["نقطة واحدة","نقطتان","3 نقاط","4 نقاط"],"h1":"هي من أخطر المخالفات في قائمة النقاط.","h2":"في Oklahoma، عدم التوقّف لحافلة مدرسية يصعد إليها الطلاب أو ينزلون منها يضيف 4 نقاط إلى سجلّك.","p":"صحيح. عدم التوقّف لحافلة مدرسية يصعد إليها الطلاب أو ينزلون منها يكلّف 4 نقاط في Oklahoma."},"ref":{"doc":"OK","page":71}},{"id":"ok-018","scope":"OK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oklahoma, how can points come off your driving record over time?","o":["2 points for each year with no convictions","1 point for each month with no tickets","All points after 6 months","Points never come off"],"h1":"A clean year helps you.","h2":"In Oklahoma, 2 points come off your record for each 12-month period with no convictions for pointable violations.","p":"Right. Each year with no pointable convictions removes 2 points in Oklahoma."},"es":{"q":"En Oklahoma, ¿cómo se pueden quitar puntos de su historial de manejo con el tiempo?","o":["2 puntos por cada año sin condenas","1 punto por cada mes sin multas","Todos los puntos después de 6 meses","Los puntos nunca se quitan"],"h1":"Un año sin faltas le ayuda.","h2":"En Oklahoma, se quitan 2 puntos de su historial por cada período de 12 meses sin condenas por infracciones con puntos.","p":"Correcto. Cada año sin condenas con puntos quita 2 puntos en Oklahoma."},"zh":{"q":"在 Oklahoma，驾驶记录上的分数怎样会随着时间被去掉？","o":["每一年没有定罪，去掉 2 分","每一个月没有罚单，去掉 1 分","6 个月后去掉所有分数","分数永远不会去掉"],"h1":"干净的一年对你有帮助。","h2":"在 Oklahoma，每 12 个月没有因要记分的违规被定罪，你的记录上会去掉 2 分。","p":"对。在 Oklahoma，每一年没有要记分的定罪，就去掉 2 分。"},"vi":{"q":"Ở Oklahoma, điểm trong hồ sơ lái xe có thể được xóa theo thời gian như thế nào?","o":["2 điểm cho mỗi năm không bị kết tội","1 điểm cho mỗi tháng không bị phạt","Tất cả điểm sau 6 tháng","Điểm không bao giờ được xóa"],"h1":"Một năm không vi phạm sẽ giúp bạn.","h2":"Ở Oklahoma, cứ mỗi 12 tháng không bị kết tội vì vi phạm có tính điểm, hồ sơ của bạn được xóa 2 điểm.","p":"Đúng. Ở Oklahoma, mỗi năm không bị kết tội vi phạm có tính điểm sẽ được xóa 2 điểm."},"tl":{"q":"Sa Oklahoma, paano natatanggal ang mga puntos sa iyong driving record sa paglipas ng panahon?","o":["2 puntos sa bawat taon na walang conviction","1 puntos sa bawat buwan na walang ticket","Lahat ng puntos pagkalipas ng 6 na buwan","Hindi kailanman natatanggal ang mga puntos"],"h1":"Nakakatulong sa iyo ang isang malinis na taon.","h2":"Sa Oklahoma, natatanggal ang 2 puntos sa iyong record sa bawat 12 buwan na walang conviction para sa paglabag na may puntos.","p":"Tama. Sa Oklahoma, bawat taon na walang conviction na may puntos ay nag-aalis ng 2 puntos."},"ar":{"q":"في Oklahoma، كيف يمكن أن تُزال النقاط من سجلّ القيادة مع الوقت؟","o":["نقطتان عن كل سنة بدون إدانات","نقطة واحدة عن كل شهر بدون مخالفات","كل النقاط بعد 6 أشهر","النقاط لا تُزال أبدًا"],"h1":"السنة النظيفة تساعدك.","h2":"في Oklahoma، تُزال نقطتان من سجلّك عن كل فترة 12 شهرًا بدون إدانات بمخالفات عليها نقاط.","p":"صحيح. كل سنة بدون إدانات بمخالفات عليها نقاط تُزيل نقطتين في Oklahoma."},"ref":{"doc":"OK","page":72}},{"id":"ok-019","scope":"OK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oklahoma, what are the minimum amounts of liability insurance a driver must carry?","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $15,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $50,000"],"h1":"The amount for two or more people is twice the amount for one person.","h2":"In Oklahoma, the minimum liability insurance is $25,000 for one person, $50,000 for two or more people, and $25,000 for property damage.","p":"Right. Oklahoma requires at least $25,000, $50,000 and $25,000 of liability coverage."},"es":{"q":"En Oklahoma, ¿cuáles son los montos mínimos del seguro de responsabilidad civil que debe tener un conductor?","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $15,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $50,000"],"h1":"El monto para dos o más personas es el doble del monto para una persona.","h2":"En Oklahoma, el seguro de responsabilidad civil mínimo es de $25,000 por una persona, $50,000 por dos o más personas y $25,000 por daños a la propiedad.","p":"Correcto. Oklahoma exige como mínimo $25,000, $50,000 y $25,000 de cobertura de responsabilidad civil."},"zh":{"q":"在 Oklahoma，司机必须买的责任保险（liability insurance）最低金额是多少？","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $15,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $50,000"],"h1":"两人或以上的金额是一人金额的两倍。","h2":"在 Oklahoma，最低责任保险是：一人 $25,000，两人或以上 $50,000，财产损失 $25,000。","p":"对。Oklahoma 要求至少 $25,000、$50,000 和 $25,000 的责任保险。"},"vi":{"q":"Ở Oklahoma, số tiền bảo hiểm trách nhiệm (liability insurance) tối thiểu mà người lái xe phải có là bao nhiêu?","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $15,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $50,000"],"h1":"Số tiền cho hai người trở lên gấp đôi số tiền cho một người.","h2":"Ở Oklahoma, bảo hiểm trách nhiệm tối thiểu là $25,000 cho một người, $50,000 cho hai người trở lên, và $25,000 cho thiệt hại tài sản.","p":"Đúng. Oklahoma yêu cầu bảo hiểm trách nhiệm ít nhất $25,000, $50,000 và $25,000."},"tl":{"q":"Sa Oklahoma, ano ang pinakamababang halaga ng liability insurance na dapat mayroon ang isang driver?","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $15,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $50,000"],"h1":"Ang halaga para sa dalawa o higit pang tao ay doble ng halaga para sa isang tao.","h2":"Sa Oklahoma, ang pinakamababang liability insurance ay $25,000 para sa isang tao, $50,000 para sa dalawa o higit pang tao, at $25,000 para sa pinsala sa ari-arian.","p":"Tama. Hinihingi ng Oklahoma ang hindi bababa sa $25,000, $50,000 at $25,000 na liability coverage."},"ar":{"q":"في Oklahoma، ما الحدّ الأدنى لمبالغ تأمين المسؤولية (liability insurance) الذي يجب أن يكون عند السائق؟","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $15,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $50,000"],"h1":"المبلغ لشخصين أو أكثر هو ضعف المبلغ لشخص واحد.","h2":"في Oklahoma، الحدّ الأدنى لتأمين المسؤولية هو $25,000 لشخص واحد، و$50,000 لشخصين أو أكثر، و$25,000 لأضرار الممتلكات.","p":"صحيح. Oklahoma تطلب تغطية مسؤولية لا تقل عن $25,000 و$50,000 و$25,000."},"ref":{"doc":"OK","page":72}},{"id":"ok-020","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, what can happen if you cannot show proof of insurance to an officer who asks for it?","o":["A written warning, the first time only","A fine up to $250, possible jail, and suspension","A $25 fine, with no other penalty","A new written and driving test"],"h1":"The penalty affects both your license and your car's registration.","h2":"In Oklahoma, not showing proof of insurance when an officer asks can bring a fine of up to $250, up to 30 days in jail, and suspension of your license and registration.","p":"Right. In Oklahoma it can mean a fine up to $250, jail up to 30 days, and a suspended license and registration."},"es":{"q":"En Oklahoma, ¿qué puede pasar si no puede mostrar prueba de seguro a un oficial que se la pide?","o":["Una advertencia por escrito, solo la primera vez","Una multa de hasta $250, posible cárcel y suspensión","Una multa de $25, sin otra sanción","Repetir el examen escrito y el de manejo"],"h1":"La sanción afecta tanto su licencia como el registro de su carro.","h2":"En Oklahoma, no mostrar prueba de seguro cuando un oficial la pide puede causar una multa de hasta $250, hasta 30 días de cárcel y la suspensión de su licencia y registro.","p":"Correcto. En Oklahoma puede significar una multa de hasta $250, hasta 30 días de cárcel y la suspensión de la licencia y el registro."},"zh":{"q":"在 Oklahoma，如果警察要你出示保险证明而你拿不出来，会怎么样？","o":["书面警告，只限第一次","最高 $250 罚款，可能坐牢，并被暂停","$25 罚款，没有别的处罚","重新考笔试和路考"],"h1":"这个处罚会影响你的驾照，也会影响你的车辆登记。","h2":"在 Oklahoma，警察要求时拿不出保险证明，可能被罚款最高 $250，坐牢最多 30 天，驾照和车辆登记也会被暂停。","p":"对。在 Oklahoma，这可能是最高 $250 罚款、最多 30 天坐牢，以及驾照和车辆登记被暂停。"},"vi":{"q":"Ở Oklahoma, điều gì có thể xảy ra nếu bạn không đưa ra được giấy tờ chứng minh bảo hiểm khi cảnh sát yêu cầu?","o":["Cảnh cáo bằng văn bản, chỉ lần đầu tiên","Phạt đến $250, có thể bị tù, và bị đình chỉ","Phạt $25, không có hình phạt nào khác","Phải thi lại bài thi viết và bài thi lái xe"],"h1":"Hình phạt ảnh hưởng cả bằng lái lẫn giấy đăng ký xe của bạn.","h2":"Ở Oklahoma, không đưa ra được giấy tờ chứng minh bảo hiểm khi cảnh sát yêu cầu có thể bị phạt đến $250, bị tù đến 30 ngày, và bị đình chỉ bằng lái và giấy đăng ký xe.","p":"Đúng. Ở Oklahoma, có thể bị phạt đến $250, bị tù đến 30 ngày, và bị đình chỉ bằng lái và giấy đăng ký xe."},"tl":{"q":"Sa Oklahoma, ano ang puwedeng mangyari kung hindi mo maipakita ang proof of insurance sa pulis na humihingi nito?","o":["Isang nakasulat na babala, sa unang beses lang","Multang hanggang $250, posibleng kulong, at suspensiyon","Multang $25, walang ibang parusa","Bagong written test at driving test"],"h1":"Naaapektuhan ng parusa ang iyong lisensiya at ang registration ng iyong sasakyan.","h2":"Sa Oklahoma, ang hindi pagpapakita ng proof of insurance kapag hiningi ng pulis ay puwedeng magresulta sa multang hanggang $250, kulong nang hanggang 30 araw, at suspensiyon ng iyong lisensiya at registration.","p":"Tama. Sa Oklahoma, puwede itong mangahulugan ng multang hanggang $250, kulong nang hanggang 30 araw, at suspendidong lisensiya at registration."},"ar":{"q":"في Oklahoma، ماذا يمكن أن يحدث إذا لم تستطع أن تُظهر إثبات التأمين لشرطي يطلبه منك؟","o":["إنذار مكتوب، في المرة الأولى فقط","غرامة حتى $250، وسجن محتمل، وإيقاف","غرامة $25، بدون أي عقوبة أخرى","اختبار كتابي واختبار قيادة جديدان"],"h1":"العقوبة تؤثّر على رخصتك وعلى تسجيل سيارتك معًا.","h2":"في Oklahoma، عدم إظهار إثبات التأمين عندما يطلبه الشرطي يمكن أن يؤدّي إلى غرامة حتى $250، وسجن حتى 30 يومًا، وإيقاف رخصتك وتسجيل سيارتك.","p":"صحيح. في Oklahoma يمكن أن يعني ذلك غرامة حتى $250، وسجنًا حتى 30 يومًا، وإيقاف الرخصة وتسجيل السيارة."},"ref":{"doc":"OK","page":72}},{"id":"ok-021","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, the child passenger restraint law covers children up to what age?","o":["Under 3","Under 12","Under 16","Under 8"],"h1":"Think of a child in about second or third grade.","h2":"In Oklahoma, the child passenger restraint law covers every child under 8. A child under 8 must ride in a child safety seat or booster seat unless the child is taller than 4 feet 9 inches.","p":"Right. Oklahoma's child restraint law covers children under 8."},"es":{"q":"En Oklahoma, ¿hasta qué edad cubre la ley de sistemas de retención infantil?","o":["Menores de 3","Menores de 12","Menores de 16","Menores de 8"],"h1":"Piense en un niño de segundo o tercer grado, más o menos.","h2":"En Oklahoma, la ley de sistemas de retención infantil cubre a todo niño menor de 8 años. Un niño menor de 8 años debe ir en una silla de seguridad o un asiento elevador, a menos que mida más de 4 pies 9 pulgadas.","p":"Correcto. La ley de retención infantil de Oklahoma cubre a los niños menores de 8 años."},"zh":{"q":"在 Oklahoma，儿童乘客安全约束法适用于多大以下的孩子？","o":["3 岁以下","12 岁以下","16 岁以下","8 岁以下"],"h1":"想一想大约上二年级或三年级的孩子。","h2":"在 Oklahoma，儿童乘客安全约束法适用于每个 8 岁以下的孩子。8 岁以下的孩子必须坐儿童安全座椅或增高座椅，除非孩子身高超过 4 英尺 9 英寸。","p":"对。Oklahoma 的儿童安全约束法适用于 8 岁以下的孩子。"},"vi":{"q":"Ở Oklahoma, luật về ghế an toàn cho trẻ em áp dụng cho trẻ em đến bao nhiêu tuổi?","o":["Dưới 3 tuổi","Dưới 12 tuổi","Dưới 16 tuổi","Dưới 8 tuổi"],"h1":"Hãy nghĩ đến một đứa trẻ khoảng lớp hai hoặc lớp ba.","h2":"Ở Oklahoma, luật về ghế an toàn cho trẻ em áp dụng cho mọi trẻ em dưới 8 tuổi. Trẻ em dưới 8 tuổi phải ngồi ghế an toàn cho trẻ em hoặc ghế nâng, trừ khi trẻ cao hơn 4 feet 9 inch.","p":"Đúng. Luật về ghế an toàn cho trẻ em của Oklahoma áp dụng cho trẻ em dưới 8 tuổi."},"tl":{"q":"Sa Oklahoma, hanggang anong edad ng bata sakop ang batas sa child passenger restraint?","o":["Wala pang 3","Wala pang 12","Wala pang 16","Wala pang 8"],"h1":"Isipin ang batang nasa mga ikalawa o ikatlong baitang.","h2":"Sa Oklahoma, sakop ng batas sa child passenger restraint ang bawat batang wala pang 8. Ang batang wala pang 8 ay dapat nakaupo sa child safety seat o booster seat, maliban kung mas matangkad ang bata sa 4 feet 9 inches.","p":"Tama. Sakop ng batas sa child restraint ng Oklahoma ang mga batang wala pang 8."},"ar":{"q":"في Oklahoma، حتى أي عمر يشمل قانون مقاعد أمان الأطفال الركّاب الأطفالَ؟","o":["أقل من 3","أقل من 12","أقل من 16","أقل من 8"],"h1":"فكّر في طفل في الصف الثاني أو الثالث تقريبًا.","h2":"في Oklahoma، يشمل قانون مقاعد أمان الأطفال الركّاب كل طفل عمره أقل من 8 سنوات. يجب أن يجلس الطفل الذي عمره أقل من 8 سنوات في مقعد أمان للأطفال أو مقعد رافع، إلا إذا كان طول الطفل أكثر من 4 أقدام و9 بوصات.","p":"صحيح. قانون مقاعد أمان الأطفال في Oklahoma يشمل الأطفال الذين عمرهم أقل من 8 سنوات."},"ref":{"doc":"OK","page":17}},{"id":"ok-022","scope":"OK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oklahoma, until what age must a child ride in a rear-facing car seat, unless the child outgrows the seat's height or weight limit?","o":["2 years","1 year","3 years","4 years"],"h1":"It is before the child turns 3.","h2":"In Oklahoma, a child must ride in a rear-facing car seat until age 2, or until the child reaches the seat maker's height or weight limit.","p":"Right. In Oklahoma a child rides rear-facing until age 2 or until outgrowing the seat."},"es":{"q":"En Oklahoma, ¿hasta qué edad debe viajar un niño en un asiento orientado hacia atrás, a menos que supere el límite de altura o peso del asiento?","o":["2 años","1 año","3 años","4 años"],"h1":"Es antes de que el niño cumpla 3 años.","h2":"En Oklahoma, un niño debe viajar en un asiento orientado hacia atrás hasta los 2 años, o hasta que alcance el límite de altura o peso que fija el fabricante.","p":"Correcto. En Oklahoma un niño viaja mirando hacia atrás hasta los 2 años o hasta que el asiento le quede pequeño."},"zh":{"q":"在 Oklahoma，除非孩子超过了座椅的身高或体重限制，孩子必须坐后向安全座椅到几岁？","o":["2 岁","1 岁","3 岁","4 岁"],"h1":"是在孩子满 3 岁之前。","h2":"在 Oklahoma，孩子必须坐后向安全座椅到 2 岁，或者到孩子达到座椅制造商的身高或体重限制。","p":"对。在 Oklahoma，孩子坐后向座椅到 2 岁，或者到长大超过座椅的限制。"},"vi":{"q":"Ở Oklahoma, trẻ em phải ngồi ghế ô tô quay mặt về phía sau đến bao nhiêu tuổi, trừ khi trẻ đã vượt quá giới hạn chiều cao hoặc cân nặng của ghế?","o":["2 tuổi","1 tuổi","3 tuổi","4 tuổi"],"h1":"Đó là trước khi trẻ được 3 tuổi.","h2":"Ở Oklahoma, trẻ em phải ngồi ghế ô tô quay mặt về phía sau đến 2 tuổi, hoặc đến khi trẻ đạt giới hạn chiều cao hoặc cân nặng của nhà sản xuất ghế.","p":"Đúng. Ở Oklahoma, trẻ ngồi ghế quay về phía sau đến 2 tuổi hoặc đến khi lớn hơn giới hạn của ghế."},"tl":{"q":"Sa Oklahoma, hanggang ilang taong gulang dapat nakasakay ang bata sa rear-facing car seat, maliban kung lumampas na ang bata sa height o weight limit ng upuan?","o":["2 taon","1 taon","3 taon","4 na taon"],"h1":"Bago ito mag-3 taong gulang ang bata.","h2":"Sa Oklahoma, dapat nakasakay ang bata sa rear-facing car seat hanggang 2 taong gulang, o hanggang maabot ng bata ang height o weight limit ng gumawa ng upuan.","p":"Tama. Sa Oklahoma, rear-facing ang bata hanggang 2 taong gulang o hanggang lumaki na siya para sa upuan."},"ar":{"q":"في Oklahoma، حتى أي عمر يجب أن يجلس الطفل في مقعد سيارة مواجه للخلف، إلا إذا تجاوز الطفل حدّ الطول أو الوزن للمقعد؟","o":["سنتان","سنة واحدة","3 سنوات","4 سنوات"],"h1":"هو قبل أن يبلغ الطفل 3 سنوات.","h2":"في Oklahoma، يجب أن يجلس الطفل في مقعد سيارة مواجه للخلف حتى عمر سنتين، أو حتى يصل إلى حدّ الطول أو الوزن الذي حدّده صانع المقعد.","p":"صحيح. في Oklahoma يجلس الطفل مواجهًا للخلف حتى عمر سنتين أو حتى يكبر على المقعد."},"ref":{"doc":"OK","page":17}},{"id":"ok-023","scope":"OK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oklahoma, how early may you renew your driver license before it expires?","o":["30 days","90 days","1 year","2 years"],"h1":"You have quite a long time to do it.","h2":"In Oklahoma, you may renew your driver license up to 1 year before it expires.","p":"Right. Oklahoma lets you renew up to 1 year early."},"es":{"q":"En Oklahoma, ¿con cuánta anticipación puede renovar su licencia de manejo antes de que venza?","o":["30 días","90 días","1 año","2 años"],"h1":"Tiene bastante tiempo para hacerlo.","h2":"En Oklahoma, puede renovar su licencia de manejo hasta 1 año antes de que venza.","p":"Correcto. Oklahoma le permite renovar hasta 1 año antes."},"zh":{"q":"在 Oklahoma，驾照到期前最早可以提前多久续期？","o":["30 天","90 天","1 年","2 年"],"h1":"你有相当长的时间可以办。","h2":"在 Oklahoma，你最早可以在驾照到期前 1 年续期。","p":"对。Oklahoma 让你最早提前 1 年续期。"},"vi":{"q":"Ở Oklahoma, bạn có thể gia hạn bằng lái sớm nhất bao lâu trước khi hết hạn?","o":["30 ngày","90 ngày","1 năm","2 năm"],"h1":"Bạn có khá nhiều thời gian để làm việc này.","h2":"Ở Oklahoma, bạn có thể gia hạn bằng lái sớm nhất là 1 năm trước khi hết hạn.","p":"Đúng. Oklahoma cho phép gia hạn sớm nhất là 1 năm."},"tl":{"q":"Sa Oklahoma, gaano kaaga mo puwedeng i-renew ang iyong driver license bago ito mag-expire?","o":["30 araw","90 araw","1 taon","2 taon"],"h1":"Medyo mahaba ang panahon mo para gawin ito.","h2":"Sa Oklahoma, puwede mong i-renew ang iyong driver license hanggang 1 taon bago ito mag-expire.","p":"Tama. Pinapayagan ka ng Oklahoma na mag-renew hanggang 1 taon nang maaga."},"ar":{"q":"في Oklahoma، كم من الوقت قبل انتهاء رخصة القيادة يمكنك أن تجدّدها؟","o":["30 يومًا","90 يومًا","سنة واحدة","سنتان"],"h1":"عندك وقت طويل نوعًا ما لتفعل ذلك.","h2":"في Oklahoma، يمكنك أن تجدّد رخصة القيادة قبل انتهائها بمدة تصل إلى سنة واحدة.","p":"صحيح. Oklahoma تسمح لك بالتجديد قبل الموعد بمدة تصل إلى سنة واحدة."},"ref":{"doc":"OK","page":13}},{"id":"ok-024","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, after you move, how soon must you tell Service Oklahoma your new address?","o":["Within 5 days","Within 10 days","Within 30 days","Within 60 days"],"h1":"It is less than two weeks.","h2":"In Oklahoma, you must tell Service Oklahoma your new address within 10 days after you move.","p":"Right. Oklahoma drivers must report a new address within 10 days."},"es":{"q":"En Oklahoma, después de mudarse, ¿en cuánto tiempo debe informar su nueva dirección a Service Oklahoma?","o":["En 5 días","En 10 días","En 30 días","En 60 días"],"h1":"Es menos de dos semanas.","h2":"En Oklahoma, debe informar su nueva dirección a Service Oklahoma dentro de los 10 días después de mudarse.","p":"Correcto. Los conductores de Oklahoma deben informar su nueva dirección en 10 días."},"zh":{"q":"在 Oklahoma，你搬家以后，必须在多久内把新地址告诉 Service Oklahoma？","o":["5 天内","10 天内","30 天内","60 天内"],"h1":"不到两个星期。","h2":"在 Oklahoma，你搬家以后必须在 10 天内把新地址告诉 Service Oklahoma。","p":"对。Oklahoma 的司机必须在 10 天内报告新地址。"},"vi":{"q":"Ở Oklahoma, sau khi chuyển nhà, bạn phải báo địa chỉ mới cho Service Oklahoma trong bao lâu?","o":["Trong vòng 5 ngày","Trong vòng 10 ngày","Trong vòng 30 ngày","Trong vòng 60 ngày"],"h1":"Ít hơn hai tuần.","h2":"Ở Oklahoma, bạn phải báo địa chỉ mới cho Service Oklahoma trong vòng 10 ngày sau khi chuyển nhà.","p":"Đúng. Người lái xe ở Oklahoma phải báo địa chỉ mới trong vòng 10 ngày."},"tl":{"q":"Sa Oklahoma, pagkatapos mong lumipat, gaano kabilis mo dapat sabihin sa Service Oklahoma ang iyong bagong address?","o":["Sa loob ng 5 araw","Sa loob ng 10 araw","Sa loob ng 30 araw","Sa loob ng 60 araw"],"h1":"Mas maikli ito sa dalawang linggo.","h2":"Sa Oklahoma, dapat mong sabihin sa Service Oklahoma ang iyong bagong address sa loob ng 10 araw pagkatapos mong lumipat.","p":"Tama. Dapat i-report ng mga driver sa Oklahoma ang bagong address sa loob ng 10 araw."},"ar":{"q":"في Oklahoma، بعد أن تنتقل إلى بيت جديد، خلال كم من الوقت يجب أن تُبلغ Service Oklahoma بعنوانك الجديد؟","o":["خلال 5 أيام","خلال 10 أيام","خلال 30 يومًا","خلال 60 يومًا"],"h1":"هي أقل من أسبوعين.","h2":"في Oklahoma، يجب أن تُبلغ Service Oklahoma بعنوانك الجديد خلال 10 أيام بعد أن تنتقل.","p":"صحيح. يجب على السائقين في Oklahoma أن يُبلغوا عن العنوان الجديد خلال 10 أيام."},"ref":{"doc":"OK","page":13}},{"id":"ok-025","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, what happens if you refuse a breath or blood test when a police officer asks?","o":["Nothing, if you have not been drinking","You get a warning the first time","You pay a small fine only","Your driving privilege is automatically revoked"],"h1":"By driving, you have already agreed to be tested.","h2":"In Oklahoma, refusing a breath or blood test leads to automatic revocation of your driving privilege, even if you have not been drinking.","p":"Right. In Oklahoma a refusal means your license is revoked automatically."},"es":{"q":"En Oklahoma, ¿qué pasa si se niega a una prueba de aliento o de sangre cuando un oficial de policía se la pide?","o":["Nada, si no ha tomado alcohol","Recibe una advertencia la primera vez","Solo paga una multa pequeña","Su privilegio de manejar se revoca automáticamente"],"h1":"Al manejar, usted ya aceptó hacerse la prueba.","h2":"En Oklahoma, negarse a una prueba de aliento o de sangre causa la revocación automática de su privilegio de manejar, aunque no haya tomado alcohol.","p":"Correcto. En Oklahoma, negarse significa que su licencia se revoca automáticamente."},"zh":{"q":"在 Oklahoma，警察要求你做呼气或验血测试时，如果你拒绝，会怎么样？","o":["如果你没喝酒，就没事","第一次会得到警告","只要付一点小罚款","你的驾驶资格会被自动吊销"],"h1":"你开车时，就已经同意接受测试了。","h2":"在 Oklahoma，拒绝做呼气或验血测试，你的驾驶资格会被自动吊销，就算你没有喝酒也一样。","p":"对。在 Oklahoma，拒绝测试意味着你的驾照会被自动吊销。"},"vi":{"q":"Ở Oklahoma, điều gì xảy ra nếu bạn từ chối kiểm tra hơi thở hoặc thử máu khi cảnh sát yêu cầu?","o":["Không sao, nếu bạn không uống rượu","Bạn bị cảnh cáo lần đầu tiên","Bạn chỉ phải trả một khoản phạt nhỏ","Quyền lái xe của bạn bị tự động thu hồi"],"h1":"Khi lái xe, bạn đã đồng ý để được kiểm tra.","h2":"Ở Oklahoma, từ chối kiểm tra hơi thở hoặc thử máu sẽ làm quyền lái xe của bạn bị tự động thu hồi, ngay cả khi bạn không uống rượu.","p":"Đúng. Ở Oklahoma, từ chối kiểm tra nghĩa là bằng lái của bạn bị tự động thu hồi."},"tl":{"q":"Sa Oklahoma, ano ang mangyayari kung tumanggi ka sa breath test o blood test kapag hiningi ito ng pulis?","o":["Wala, kung hindi ka uminom","Babala lang sa unang beses","Maliit na multa lang ang babayaran mo","Awtomatikong babawiin ang iyong pribilehiyong magmaneho"],"h1":"Sa pagmamaneho, pumayag ka na na ma-test.","h2":"Sa Oklahoma, ang pagtanggi sa breath test o blood test ay nagdudulot ng awtomatikong pagbawi ng iyong pribilehiyong magmaneho, kahit hindi ka uminom.","p":"Tama. Sa Oklahoma, kapag tumanggi ka, awtomatikong babawiin ang iyong lisensiya."},"ar":{"q":"في Oklahoma، ماذا يحدث إذا رفضت فحص النفَس أو فحص الدم عندما يطلبه منك الشرطي؟","o":["لا شيء، إذا لم تكن قد شربت","تحصل على إنذار في المرة الأولى","تدفع غرامة صغيرة فقط","يُسحب حقّك في القيادة تلقائيًا"],"h1":"بمجرّد أن تقود، فأنت قد وافقت مسبقًا على الفحص.","h2":"في Oklahoma، رفض فحص النفَس أو فحص الدم يؤدّي إلى سحب حقّك في القيادة تلقائيًا، حتى لو لم تكن قد شربت.","p":"صحيح. في Oklahoma الرفض يعني أن رخصتك تُسحب تلقائيًا."},"ref":{"doc":"OK","page":65}},{"id":"ok-026","scope":"OK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oklahoma, you hit a parked car and cannot find the owner. What must you do?","o":["Leave your name, address and insurance information where the owner will find it","Drive away if the damage looks small and minor","Wait next to the parked car until the next day","Call the owner's insurance company to report it"],"h1":"The owner needs a way to reach you.","h2":"In Oklahoma, if you hit a parked car and cannot find the owner, you must leave the driver's and owner's name and address and your insurance information on the damaged car.","p":"Right. In Oklahoma you leave your name, address and insurance details where the owner will see them."},"es":{"q":"En Oklahoma, usted choca contra un carro estacionado y no encuentra al dueño. ¿Qué debe hacer?","o":["Dejar su nombre, dirección e información del seguro donde el dueño la encuentre","Irse si el daño parece pequeño y sin importancia","Esperar junto al carro estacionado hasta el día siguiente","Llamar a la compañía de seguros del dueño para avisar"],"h1":"El dueño necesita una forma de comunicarse con usted.","h2":"En Oklahoma, si choca contra un carro estacionado y no encuentra al dueño, debe dejar el nombre y la dirección del conductor y del dueño, y la información de su seguro, en el carro dañado.","p":"Correcto. En Oklahoma usted deja su nombre, dirección y datos del seguro donde el dueño los vea."},"zh":{"q":"在 Oklahoma，你撞到一辆停着的车，找不到车主。你必须怎么做？","o":["把你的姓名、地址和保险信息留在车主会看到的地方","如果损坏看起来很小，就开走","在停着的车旁边等到第二天","打电话给车主的保险公司报告"],"h1":"车主需要有办法联系你。","h2":"在 Oklahoma，如果你撞到一辆停着的车，又找不到车主，你必须在被撞的车上留下司机和车主的姓名、地址，以及你的保险信息。","p":"对。在 Oklahoma，你要把你的姓名、地址和保险信息留在车主会看到的地方。"},"vi":{"q":"Ở Oklahoma, bạn đâm vào một xe đang đậu và không tìm được chủ xe. Bạn phải làm gì?","o":["Để lại tên, địa chỉ và thông tin bảo hiểm của bạn ở nơi chủ xe sẽ thấy","Lái đi nếu hư hỏng có vẻ nhỏ và không đáng kể","Chờ bên cạnh xe đang đậu đến ngày hôm sau","Gọi cho công ty bảo hiểm của chủ xe để báo"],"h1":"Chủ xe cần có cách liên lạc với bạn.","h2":"Ở Oklahoma, nếu bạn đâm vào một xe đang đậu và không tìm được chủ xe, bạn phải để lại tên và địa chỉ của người lái và của chủ xe, cùng thông tin bảo hiểm của bạn, trên chiếc xe bị hư hỏng.","p":"Đúng. Ở Oklahoma, bạn để lại tên, địa chỉ và thông tin bảo hiểm ở nơi chủ xe sẽ thấy."},"tl":{"q":"Sa Oklahoma, nabangga mo ang isang nakaparadang sasakyan at hindi mo makita ang may-ari. Ano ang dapat mong gawin?","o":["Iwan ang iyong pangalan, address at impormasyon ng insurance kung saan ito makikita ng may-ari","Umalis kung mukhang maliit at hindi malala ang sira","Maghintay sa tabi ng nakaparadang sasakyan hanggang kinabukasan","Tawagan ang insurance company ng may-ari para i-report ito"],"h1":"Kailangan ng may-ari ng paraan para makontak ka.","h2":"Sa Oklahoma, kung nabangga mo ang isang nakaparadang sasakyan at hindi mo makita ang may-ari, dapat mong iwan sa nasirang sasakyan ang pangalan at address ng driver at ng may-ari, at ang iyong impormasyon ng insurance.","p":"Tama. Sa Oklahoma, iniiwan mo ang iyong pangalan, address at detalye ng insurance kung saan makikita ito ng may-ari."},"ar":{"q":"في Oklahoma، صدمت سيارة متوقّفة ولا تستطيع أن تجد صاحبها. ماذا يجب أن تفعل؟","o":["أن تترك اسمك وعنوانك ومعلومات تأمينك في مكان سيجدها فيه صاحب السيارة","أن تبتعد بالسيارة إذا كان الضرر يبدو صغيرًا وبسيطًا","أن تنتظر بجانب السيارة المتوقّفة حتى اليوم التالي","أن تتّصل بشركة تأمين صاحب السيارة لتُبلغ عن الحادث"],"h1":"صاحب السيارة يحتاج إلى طريقة للتواصل معك.","h2":"في Oklahoma، إذا صدمت سيارة متوقّفة ولم تجد صاحبها، يجب أن تترك على السيارة المتضرّرة اسم السائق وعنوانه واسم صاحب السيارة وعنوانه ومعلومات تأمينك.","p":"صحيح. في Oklahoma تترك اسمك وعنوانك وتفاصيل تأمينك في مكان سيراها فيه صاحب السيارة."},"ref":{"doc":"OK","page":63}},{"id":"ok-027","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, you fail the written test. How long must you wait before you take it again?","o":["At least one week","At least one day","At least 30 days","At least 6 months"],"h1":"It is a short wait.","h2":"In Oklahoma, if you fail the written test, the law says you must wait at least one day before you take it again.","p":"Right. You must wait at least one day."},"es":{"q":"En Oklahoma, usted no aprueba el examen escrito. ¿Cuánto tiempo debe esperar para tomarlo otra vez?","o":["Por lo menos una semana","Por lo menos un día","Por lo menos 30 días","Por lo menos 6 meses"],"h1":"Es una espera corta.","h2":"En Oklahoma, si no aprueba el examen escrito, la ley dice que debe esperar por lo menos un día antes de tomarlo otra vez.","p":"Correcto. Debe esperar por lo menos un día."},"zh":{"q":"在 Oklahoma，你笔试没有通过。你要等多久才能再考？","o":["至少一周","至少一天","至少 30 天","至少 6 个月"],"h1":"要等的时间很短。","h2":"在 Oklahoma，如果你笔试没有通过，法律规定你至少要等一天才能再考。","p":"对。你至少要等一天。"},"vi":{"q":"Ở Oklahoma, bạn thi viết bị rớt. Bạn phải chờ bao lâu mới được thi lại?","o":["Ít nhất một tuần","Ít nhất một ngày","Ít nhất 30 ngày","Ít nhất 6 tháng"],"h1":"Thời gian chờ ngắn.","h2":"Ở Oklahoma, nếu bạn thi viết bị rớt, luật nói bạn phải chờ ít nhất một ngày rồi mới được thi lại.","p":"Đúng. Bạn phải chờ ít nhất một ngày."},"tl":{"q":"Sa Oklahoma, bumagsak ka sa written test. Gaano katagal ka dapat maghintay bago ka kumuha ulit nito?","o":["Hindi bababa sa isang linggo","Hindi bababa sa isang araw","Hindi bababa sa 30 araw","Hindi bababa sa 6 na buwan"],"h1":"Maikli lang ang paghihintay.","h2":"Sa Oklahoma, kapag bumagsak ka sa written test, sinasabi ng batas na dapat kang maghintay nang hindi bababa sa isang araw bago ka kumuha ulit nito.","p":"Tama. Dapat kang maghintay nang hindi bababa sa isang araw."},"ar":{"q":"في Oklahoma، رسبت في الاختبار الكتابي. كم يجب أن تنتظر قبل أن تعيده؟","o":["أسبوع واحد على الأقل","يوم واحد على الأقل","30 يومًا على الأقل","6 أشهر على الأقل"],"h1":"الانتظار قصير.","h2":"في Oklahoma، إذا رسبت في الاختبار الكتابي، يقول القانون إنه يجب أن تنتظر يومًا واحدًا على الأقل قبل أن تعيده.","p":"صحيح. يجب أن تنتظر يومًا واحدًا على الأقل."},"ref":{"doc":"OK","page":9}},{"id":"ok-028","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, for how long can a driver license be issued?","o":["1 or 2 years","10 years only","For life","4 or 8 years"],"h1":"There are two choices, and one is twice the other.","h2":"In Oklahoma, a driver license can be issued for either 4 or 8 years, and it expires on the last day of the month.","p":"Right. It can be issued for 4 or 8 years."},"es":{"q":"En Oklahoma, ¿por cuánto tiempo se puede emitir una licencia de conducir?","o":["1 o 2 años","Solo 10 años","De por vida","4 u 8 años"],"h1":"Hay dos opciones, y una es el doble de la otra.","h2":"En Oklahoma, una licencia de conducir se puede emitir por 4 u 8 años, y vence el último día del mes.","p":"Correcto. Se puede emitir por 4 u 8 años."},"zh":{"q":"在 Oklahoma，驾照的有效期可以是多久？","o":["1 年或 2 年","只有 10 年","终身","4 年或 8 年"],"h1":"有两个选择，一个是另一个的两倍。","h2":"在 Oklahoma，驾照的有效期可以是 4 年或 8 年，并在那个月的最后一天到期。","p":"对。驾照的有效期可以是 4 年或 8 年。"},"vi":{"q":"Ở Oklahoma, bằng lái xe có thể được cấp trong bao lâu?","o":["1 hoặc 2 năm","Chỉ 10 năm","Suốt đời","4 hoặc 8 năm"],"h1":"Có hai lựa chọn, và một số gấp đôi số kia.","h2":"Ở Oklahoma, bằng lái xe có thể được cấp trong 4 hoặc 8 năm, và hết hạn vào ngày cuối cùng của tháng.","p":"Đúng. Bằng lái có thể được cấp trong 4 hoặc 8 năm."},"tl":{"q":"Sa Oklahoma, gaano katagal maaaring ibigay ang isang driver license?","o":["1 o 2 taon","10 taon lang","Habambuhay","4 o 8 taon"],"h1":"May dalawang pagpipilian, at doble ng isa ang isa pa.","h2":"Sa Oklahoma, maaaring ibigay ang driver license nang 4 o 8 taon, at mag-e-expire ito sa huling araw ng buwan.","p":"Tama. Maaari itong ibigay nang 4 o 8 taon."},"ar":{"q":"في Oklahoma، لأي مدة يمكن إصدار رخصة القيادة؟","o":["سنة أو سنتان","10 سنوات فقط","مدى الحياة","4 أو 8 سنوات"],"h1":"هناك خياران، وأحدهما ضعف الآخر.","h2":"في Oklahoma، يمكن إصدار رخصة القيادة لمدة 4 أو 8 سنوات، وتنتهي في آخر يوم من الشهر.","p":"صحيح. يمكن إصدارها لمدة 4 أو 8 سنوات."},"ref":{"doc":"OK","page":13}},{"id":"ok-029","scope":"OK","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Oklahoma, a blind person with a white cane is in the road ahead. How far from the person must your vehicle stop?","o":["15 feet","2 feet","5 feet","100 feet"],"h1":"It is more than 10 feet but less than 20.","h2":"In Oklahoma, a vehicle must stop 15 feet from a blind person in the roadway or at an intersection, outside the crosswalk.","p":"Right. Stop 15 feet away."},"es":{"q":"En Oklahoma, una persona ciega con bastón blanco está en la calle adelante. ¿A qué distancia de la persona debe detenerse su vehículo?","o":["15 pies","2 pies","5 pies","100 pies"],"h1":"Es más de 10 pies pero menos de 20.","h2":"En Oklahoma, un vehículo debe detenerse a 15 pies de una persona ciega que está en la calle o en una intersección, fuera del cruce peatonal.","p":"Correcto. Deténgase a 15 pies."},"zh":{"q":"在 Oklahoma，前面路上有一位拿着白色手杖的盲人。你的车必须在离这个人多远的地方停下？","o":["15 英尺","2 英尺","5 英尺","100 英尺"],"h1":"比 10 英尺多，但比 20 英尺少。","h2":"在 Oklahoma，如果盲人在道路上或路口，车辆必须在离他 15 英尺的地方停下，停在人行横道外面。","p":"对。在 15 英尺外停下。"},"vi":{"q":"Ở Oklahoma, phía trước có một người mù cầm gậy trắng đang ở trên đường. Xe của bạn phải dừng cách người đó bao xa?","o":["15 feet","2 feet","5 feet","100 feet"],"h1":"Nhiều hơn 10 feet nhưng ít hơn 20 feet.","h2":"Ở Oklahoma, xe phải dừng cách người mù 15 feet khi người đó ở trên đường hoặc ở giao lộ, bên ngoài lối qua đường.","p":"Đúng. Hãy dừng cách 15 feet."},"tl":{"q":"Sa Oklahoma, may bulag na tao na may puting tungkod sa kalsada sa unahan. Gaano kalayo sa tao dapat huminto ang sasakyan mo?","o":["15 feet","2 feet","5 feet","100 feet"],"h1":"Higit ito sa 10 feet pero kulang sa 20.","h2":"Sa Oklahoma, dapat huminto ang sasakyan nang 15 feet ang layo sa bulag na tao na nasa kalsada o nasa intersection, sa labas ng crosswalk.","p":"Tama. Huminto nang 15 feet ang layo."},"ar":{"q":"في Oklahoma، يوجد شخص كفيف يحمل عصا بيضاء على الطريق أمامك. على أي مسافة من هذا الشخص يجب أن تتوقف سيارتك؟","o":["15 قدمًا","2 قدم","5 أقدام","100 قدم"],"h1":"هي أكثر من 10 أقدام وأقل من 20.","h2":"في Oklahoma، يجب أن تتوقف السيارة على بعد 15 قدمًا من الشخص الكفيف على الطريق أو عند التقاطع، خارج ممر المشاة.","p":"صحيح. توقف على بعد 15 قدمًا."},"ref":{"doc":"OK","page":28}},{"id":"ok-030","scope":"OK","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Oklahoma, how close to the nearest rail of a railroad crossing may you park?","o":["No closer than 5 feet","No closer than 15 feet","No closer than 50 feet","No closer than 500 feet"],"h1":"It is a longer distance than for a fire hydrant.","h2":"In Oklahoma, you may not park within 50 feet of the nearest rail of a railroad crossing.","p":"Right. Stay at least 50 feet from the nearest rail."},"es":{"q":"En Oklahoma, ¿qué tan cerca del riel más cercano de un cruce de ferrocarril puede estacionarse?","o":["A no menos de 5 pies","A no menos de 15 pies","A no menos de 50 pies","A no menos de 500 pies"],"h1":"Es una distancia mayor que la de un hidrante.","h2":"En Oklahoma, no puede estacionarse a menos de 50 pies del riel más cercano de un cruce de ferrocarril.","p":"Correcto. Quédese por lo menos a 50 pies del riel más cercano."},"zh":{"q":"在 Oklahoma，你可以在离铁路道口最近的铁轨多近的地方停车？","o":["不能少于 5 英尺","不能少于 15 英尺","不能少于 50 英尺","不能少于 500 英尺"],"h1":"这个距离比消防栓的距离更长。","h2":"在 Oklahoma，你不可以在离铁路道口最近的铁轨 50 英尺以内停车。","p":"对。要离最近的铁轨至少 50 英尺。"},"vi":{"q":"Ở Oklahoma, bạn được đậu xe gần thanh ray gần nhất của chỗ giao với đường sắt đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 15 feet","Không gần hơn 50 feet","Không gần hơn 500 feet"],"h1":"Khoảng cách này dài hơn khoảng cách với vòi nước chữa cháy.","h2":"Ở Oklahoma, bạn không được đậu xe trong vòng 50 feet tính từ thanh ray gần nhất của chỗ giao với đường sắt.","p":"Đúng. Hãy cách thanh ray gần nhất ít nhất 50 feet."},"tl":{"q":"Sa Oklahoma, gaano kalapit sa pinakamalapit na riles ng railroad crossing ka maaaring mag-park?","o":["Hindi lalapit sa 5 feet","Hindi lalapit sa 15 feet","Hindi lalapit sa 50 feet","Hindi lalapit sa 500 feet"],"h1":"Mas mahaba ito kaysa sa layo para sa fire hydrant.","h2":"Sa Oklahoma, hindi ka maaaring mag-park sa loob ng 50 feet mula sa pinakamalapit na riles ng railroad crossing.","p":"Tama. Lumayo nang hindi bababa sa 50 feet sa pinakamalapit na riles."},"ar":{"q":"في Oklahoma، إلى أي مدى يمكنك أن تركن سيارتك قريبًا من أقرب قضيب في معبر السكة الحديدية؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 50 قدمًا","ليس أقرب من 500 قدم"],"h1":"هي مسافة أطول من المسافة عند حنفية الإطفاء.","h2":"في Oklahoma، لا يجوز أن تركن سيارتك على مسافة أقل من 50 قدمًا من أقرب قضيب في معبر السكة الحديدية.","p":"صحيح. ابقَ على بعد 50 قدمًا على الأقل من أقرب قضيب."},"ref":{"doc":"OK","page":49}},{"id":"ok-031","scope":"OK","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Oklahoma, you are on a road with four or more lanes. What is the rule about the left lane?","o":["Only trucks may use it","You may not drive there in a way that blocks the normal flow of traffic","You may drive there at any speed you like","You may use it only at night"],"h1":"Think about faster cars that want to pass.","h2":"In Oklahoma, on a road divided into four or more lanes, you may not block the normal flow of traffic by driving in the left lane.","p":"Right. Do not hold up traffic in the left lane."},"es":{"q":"En Oklahoma, usted va por una carretera de cuatro carriles o más. ¿Cuál es la regla sobre el carril izquierdo?","o":["Solo los camiones pueden usarlo","No puede manejar ahí de una forma que bloquee el flujo normal del tráfico","Puede manejar ahí a la velocidad que quiera","Solo puede usarlo de noche"],"h1":"Piense en los carros más rápidos que quieren pasar.","h2":"En Oklahoma, en una carretera dividida en cuatro carriles o más, usted no puede bloquear el flujo normal del tráfico manejando en el carril izquierdo.","p":"Correcto. No detenga el tráfico en el carril izquierdo."},"zh":{"q":"在 Oklahoma，你在一条有四条或更多车道的路上。关于左车道的规定是什么？","o":["只有卡车可以用","你不可以在那里开车挡住正常的交通","你可以在那里用任何速度开车","你只可以在晚上用"],"h1":"想一想想要超车的更快的车。","h2":"在 Oklahoma，在分成四条或更多车道的路上，你不可以在左车道开车挡住正常的交通。","p":"对。不要在左车道挡住交通。"},"vi":{"q":"Ở Oklahoma, bạn đang ở trên con đường có bốn làn xe trở lên. Quy định về làn bên trái là gì?","o":["Chỉ xe tải được đi","Bạn không được lái ở đó theo cách cản trở dòng xe bình thường","Bạn được lái ở đó với bất kỳ tốc độ nào bạn muốn","Bạn chỉ được đi làn đó vào ban đêm"],"h1":"Hãy nghĩ đến những xe chạy nhanh hơn muốn vượt.","h2":"Ở Oklahoma, trên con đường chia thành bốn làn xe trở lên, bạn không được cản trở dòng xe bình thường bằng cách lái ở làn bên trái.","p":"Đúng. Đừng làm chậm dòng xe ở làn bên trái."},"tl":{"q":"Sa Oklahoma, nasa kalsada ka na may apat o higit pang lane. Ano ang patakaran tungkol sa kaliwang lane?","o":["Mga trak lang ang maaaring gumamit nito","Hindi ka maaaring magmaneho roon sa paraang humaharang sa normal na daloy ng trapiko","Maaari kang magmaneho roon sa anumang bilis na gusto mo","Maaari mo lang itong gamitin sa gabi"],"h1":"Isipin ang mas mabibilis na sasakyan na gustong mag-overtake.","h2":"Sa Oklahoma, sa kalsadang hinati sa apat o higit pang lane, hindi mo maaaring harangan ang normal na daloy ng trapiko sa pagmamaneho sa kaliwang lane.","p":"Tama. Huwag pabagalin ang trapiko sa kaliwang lane."},"ar":{"q":"في Oklahoma، أنت على طريق فيه أربعة مسارات أو أكثر. ما القاعدة بخصوص المسار الأيسر؟","o":["الشاحنات فقط يمكنها استخدامه","لا يجوز أن تقود فيه بطريقة تعيق حركة المرور العادية","يمكنك أن تقود فيه بأي سرعة تريدها","يمكنك استخدامه في الليل فقط"],"h1":"فكّر في السيارات الأسرع التي تريد التجاوز.","h2":"في Oklahoma، على طريق مقسّم إلى أربعة مسارات أو أكثر، لا يجوز أن تعيق حركة المرور العادية بالقيادة في المسار الأيسر.","p":"صحيح. لا تعطّل حركة المرور في المسار الأيسر."},"ref":{"doc":"OK","page":35}},{"id":"ok-032","scope":"OK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oklahoma, a rider has a motorcycle-only license before age 16. What is the largest engine size allowed?","o":["50 cc","150 cc","300 cc","500 cc"],"h1":"It is a small bike, but not the smallest size on the list.","h2":"In Oklahoma, a rider under 16 with a motorcycle-only license may ride a motorcycle or scooter of no more than 300 cc.","p":"Right. Young riders are limited to 300 cc or less."},"es":{"q":"En Oklahoma, una persona menor de 16 años tiene una licencia solo para motocicleta. ¿Cuál es el motor más grande permitido?","o":["50 cc","150 cc","300 cc","500 cc"],"h1":"Es una moto pequeña, pero no el tamaño más pequeño de la lista.","h2":"En Oklahoma, una persona menor de 16 años con licencia solo para motocicleta puede manejar una motocicleta o scooter de no más de 300 cc.","p":"Correcto. Los motociclistas jóvenes están limitados a 300 cc o menos."},"ref":{"doc":"OK","page":7}},{"id":"ok-033","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, who must wear a helmet when riding a motorcycle?","o":["Every rider, at any age","Riders under 18","Riders under 21","Only riders with a learner permit"],"h1":"The law is about young riders only.","h2":"In Oklahoma, a motorcycle helmet is required for anyone under 18 years old.","p":"Right. Riders under 18 must wear a helmet in Oklahoma."},"es":{"q":"En Oklahoma, ¿quién debe usar casco al manejar una motocicleta?","o":["Todos, a cualquier edad","Los menores de 18 años","Los menores de 21 años","Solo quienes tienen permiso de aprendiz"],"h1":"La ley es solo para los motociclistas jóvenes.","h2":"En Oklahoma, el casco de motocicleta es obligatorio para toda persona menor de 18 años.","p":"Correcto. En Oklahoma, los menores de 18 años deben usar casco."},"ref":{"doc":"OK","page":7}},{"id":"ok-034","scope":"OK","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Oklahoma, a motorcycle has no windshield. What must the rider wear?","o":["Approved goggles or a face shield","A bright reflective vest","Any pair of sunglasses","Nothing extra is needed"],"h1":"It protects the eyes and face from things flying through the air.","h2":"In Oklahoma, a motorcycle rider without a windshield must wear approved goggles or a face shield.","p":"Right. No windshield means approved goggles or a face shield."},"es":{"q":"En Oklahoma, una motocicleta no tiene parabrisas. ¿Qué debe usar quien la maneja?","o":["Gafas protectoras aprobadas o una careta","Un chaleco reflectante de color vivo","Cualquier par de lentes de sol","No necesita nada más"],"h1":"Protege los ojos y la cara de objetos que vuelan por el aire.","h2":"En Oklahoma, quien maneja una motocicleta sin parabrisas debe usar gafas protectoras aprobadas o una careta.","p":"Correcto. Sin parabrisas, se usan gafas protectoras aprobadas o una careta."},"ref":{"doc":"OK","page":53}},{"id":"ok-035","scope":"OK","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Oklahoma, you are convicted of not stopping for a school bus with its red loading lights flashing. What happens to your license?","o":["Nothing, if it is your first time","It is suspended for 30 days","You get a warning letter","It is revoked for one year"],"h1":"The law treats this very seriously, with a long loss of your license.","h2":"In Oklahoma, not stopping for a school bus with its red loading lights flashing leads to a mandatory one-year revocation of your license.","p":"Right. Passing a loading school bus costs your license for one year."},"es":{"q":"En Oklahoma, lo declaran culpable de no detenerse ante un autobús escolar con sus luces rojas de carga encendidas. ¿Qué pasa con su licencia?","o":["Nada, si es la primera vez","Se suspende por 30 días","Recibe una carta de advertencia","Se revoca por un año"],"h1":"La ley trata esto como algo muy grave, con una pérdida larga de la licencia.","h2":"En Oklahoma, no detenerse ante un autobús escolar con sus luces rojas de carga encendidas causa la revocación obligatoria de su licencia por un año.","p":"Correcto. No detenerse ante un autobús escolar le cuesta la licencia por un año."},"ref":{"doc":"OK","page":30}},{"id":"ok-036","scope":"OK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oklahoma, a driver is convicted of a second DUI within 10 years. What kind of crime is it?","o":["A warning only","A traffic ticket only","A felony","A misdemeanor, the same as the first"],"h1":"The second time is much more serious than the first.","h2":"In Oklahoma, a second DUI offense within 10 years is a felony.","p":"Right. A second DUI within 10 years is a felony in Oklahoma."},"es":{"q":"En Oklahoma, una persona es declarada culpable de un segundo DUI en 10 años. ¿Qué tipo de delito es?","o":["Solo una advertencia","Solo una multa de tránsito","Un delito grave (felony)","Un delito menor, igual que el primero"],"h1":"La segunda vez es mucho más grave que la primera.","h2":"En Oklahoma, un segundo DUI en 10 años es un delito grave (felony).","p":"Correcto. Un segundo DUI en 10 años es un delito grave en Oklahoma."},"ref":{"doc":"OK","page":65}},{"id":"ok-037","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, your blood alcohol level is over 0.05 but under 0.08. Can you be charged?","o":["No, the limit is 0.08","Yes, with impaired driving","Only if you were in a crash","Only if you drive a truck"],"h1":"Oklahoma has a lower charge for drivers who are affected but below 0.08.","h2":"In Oklahoma, a driver with a blood alcohol level over 0.05 but under 0.08 can be convicted of impaired driving.","p":"Right. Over 0.05 can mean an impaired driving charge in Oklahoma."},"es":{"q":"En Oklahoma, su nivel de alcohol en la sangre es mayor de 0.05 pero menor de 0.08. ¿Pueden acusarlo?","o":["No, el límite es 0.08","Sí, de manejar con facultades disminuidas","Solo si tuvo un choque","Solo si maneja un camión"],"h1":"Oklahoma tiene un cargo menor para conductores afectados aunque estén por debajo de 0.08.","h2":"En Oklahoma, un conductor con un nivel de alcohol en la sangre mayor de 0.05 pero menor de 0.08 puede ser declarado culpable de manejar con facultades disminuidas.","p":"Correcto. Más de 0.05 puede significar un cargo por manejar con facultades disminuidas en Oklahoma."},"ref":{"doc":"OK","page":65}},{"id":"ok-038","scope":"OK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oklahoma, a driver under 21 has a first offense under the Zero Tolerance law. How long is the license revoked?","o":["6 months","30 days","2 years","5 years"],"h1":"It is half a year.","h2":"In Oklahoma, a first Zero Tolerance offense for a driver under 21 leads to a license revocation of six months.","p":"Right. A first Zero Tolerance offense means six months without a license."},"es":{"q":"En Oklahoma, un conductor menor de 21 años comete una primera falta bajo la ley de Tolerancia Cero. ¿Por cuánto tiempo se revoca la licencia?","o":["6 meses","30 días","2 años","5 años"],"h1":"Es medio año.","h2":"En Oklahoma, una primera falta de Tolerancia Cero de un conductor menor de 21 años causa la revocación de la licencia por seis meses.","p":"Correcto. Una primera falta de Tolerancia Cero significa seis meses sin licencia."},"ref":{"doc":"OK","page":67}},{"id":"ok-039","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, cannabis is legal for some medical uses. Is it legal to drive with cannabis in your system?","o":["Yes, if you have a medical card","Yes, if you feel fine","Yes, below a set legal limit","No, any detectable amount is illegal"],"h1":"Unlike alcohol for adults, there is no amount that is allowed.","h2":"In Oklahoma, it is illegal for anyone to drive with any detectable level of cannabis in their system.","p":"Right. Any detectable cannabis makes driving illegal in Oklahoma."},"es":{"q":"En Oklahoma, el cannabis es legal para algunos usos médicos. ¿Es legal manejar con cannabis en el cuerpo?","o":["Sí, si tiene una tarjeta médica","Sí, si se siente bien","Sí, por debajo de un límite legal","No, cualquier cantidad detectable es ilegal"],"h1":"A diferencia del alcohol para los adultos, no hay ninguna cantidad permitida.","h2":"En Oklahoma, es ilegal que cualquier persona maneje con cualquier nivel detectable de cannabis en el cuerpo.","p":"Correcto. Cualquier cantidad detectable de cannabis hace ilegal manejar en Oklahoma."},"ref":{"doc":"OK","page":66}},{"id":"ok-040","scope":"OK","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Oklahoma, what is the highest fine for a speeding conviction, outside school and work zones?","o":["$100","$250","$654","$5,000"],"h1":"It is more than $500 but far less than $1,000.","h2":"In Oklahoma, a speeding conviction can bring a fine of up to $654 and up to 30 days in jail.","p":"Right. Speeding can cost up to $654 in Oklahoma."},"es":{"q":"En Oklahoma, ¿cuál es la multa más alta por exceso de velocidad, fuera de zonas escolares y de obras?","o":["$100","$250","$654","$5,000"],"h1":"Es más de $500 pero mucho menos de $1,000.","h2":"En Oklahoma, una condena por exceso de velocidad puede traer una multa de hasta $654 y hasta 30 días de cárcel.","p":"Correcto. El exceso de velocidad puede costar hasta $654 en Oklahoma."},"ref":{"doc":"OK","page":40}},{"id":"ok-041","scope":"OK","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Oklahoma, what is the speed limit on a highway inside a state park or wildlife refuge when no other limit is posted?","o":["25 mph","35 mph","45 mph","55 mph"],"h1":"Parks have people and animals near the road, so the limit is low.","h2":"In Oklahoma, the speed limit on highways inside state parks or wildlife refuges is 35 mph unless another limit is posted.","p":"Right. 35 mph in state parks and wildlife refuges."},"es":{"q":"En Oklahoma, ¿cuál es el límite de velocidad en una carretera dentro de un parque estatal o refugio de vida silvestre si no hay otro límite señalado?","o":["25 mph","35 mph","45 mph","55 mph"],"h1":"En los parques hay personas y animales cerca del camino, así que el límite es bajo.","h2":"En Oklahoma, el límite de velocidad en las carreteras dentro de parques estatales o refugios de vida silvestre es 35 mph, a menos que haya otro límite señalado.","p":"Correcto. 35 mph en parques estatales y refugios de vida silvestre."},"ref":{"doc":"OK","page":41}},{"id":"ok-042","scope":"OK","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Oklahoma, what is the speed limit in a marked school zone on a highway outside a city or town, when no other limit is posted?","o":["25 mph","15 mph","35 mph","45 mph"],"h1":"It is the same number as a common neighborhood limit.","h2":"In Oklahoma, the speed limit in a properly marked school zone on a highway outside a city or town is 25 mph unless another limit is posted.","p":"Right. 25 mph in a marked school zone outside town."},"es":{"q":"En Oklahoma, ¿cuál es el límite de velocidad en una zona escolar señalada en una carretera fuera de una ciudad o pueblo, si no hay otro límite señalado?","o":["25 mph","15 mph","35 mph","45 mph"],"h1":"Es el mismo número que un límite común en los vecindarios.","h2":"En Oklahoma, el límite de velocidad en una zona escolar bien señalada en una carretera fuera de una ciudad o pueblo es 25 mph, a menos que haya otro límite señalado.","p":"Correcto. 25 mph en una zona escolar señalada fuera del pueblo."},"ref":{"doc":"OK","page":41}},{"id":"ok-043","scope":"OK","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Oklahoma, what fine can you get for not obeying the signs, signals or markings in a work zone?","o":["$5 to $25","$10 to $50","$25 to $75","$100 to $1,000"],"h1":"It can reach four digits, and there may also be jail time.","h2":"In Oklahoma, not obeying work zone signs, signals or markings can bring a fine from $100 to $1,000 and up to 30 days in jail.","p":"Right. $100 to $1,000 for ignoring work zone signs."},"es":{"q":"En Oklahoma, ¿qué multa puede recibir por no obedecer las señales, semáforos o marcas en una zona de obras?","o":["De $5 a $25","De $10 a $50","De $25 a $75","De $100 a $1,000"],"h1":"Puede llegar a cuatro cifras, y también puede haber cárcel.","h2":"En Oklahoma, no obedecer las señales, semáforos o marcas de una zona de obras puede traer una multa de $100 a $1,000 y hasta 30 días de cárcel.","p":"Correcto. De $100 a $1,000 por no obedecer las señales de una zona de obras."},"ref":{"doc":"OK","page":24}},{"id":"ok-044","scope":"OK","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Oklahoma, you drive in a caravan outside a business or residential area. How much space should you leave between vehicles?","o":["At least 20 feet","At least 50 feet","At least 200 feet","At least 1,000 feet"],"h1":"Other cars and trucks must be able to pull into the line safely.","h2":"In Oklahoma, cars in a caravan outside a business or residential area should keep at least 200 feet between each vehicle.","p":"Right. Leave at least 200 feet between vehicles in a caravan."},"es":{"q":"En Oklahoma, usted maneja en una caravana fuera de una zona comercial o residencial. ¿Cuánto espacio debe dejar entre los vehículos?","o":["Por lo menos 20 pies","Por lo menos 50 pies","Por lo menos 200 pies","Por lo menos 1,000 pies"],"h1":"Otros carros y camiones deben poder entrar en la fila sin peligro.","h2":"En Oklahoma, los vehículos en una caravana fuera de una zona comercial o residencial deben dejar por lo menos 200 pies entre cada uno.","p":"Correcto. Deje por lo menos 200 pies entre los vehículos de una caravana."},"ref":{"doc":"OK","page":44}},{"id":"ok-045","scope":"OK","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Oklahoma, you park next to a curb on a hill. How close to the curb should your car stop?","o":["Within 2 feet","Within 6 inches","Within 3 feet","Touching the sidewalk"],"h1":"On a hill, you need to be closer to the curb than in normal parallel parking.","h2":"In Oklahoma, when you park on a hill, you should stop within six inches of the curb.","p":"Right. On a hill, stop within six inches of the curb."},"es":{"q":"En Oklahoma, usted se estaciona junto a la acera en una cuesta. ¿Qué tan cerca de la acera debe quedar su carro?","o":["A menos de 2 pies","A menos de 6 pulgadas","A menos de 3 pies","Tocando la banqueta"],"h1":"En una cuesta debe quedar más cerca de la acera que al estacionarse en paralelo normalmente.","h2":"En Oklahoma, cuando se estaciona en una cuesta, debe quedar a menos de seis pulgadas de la acera.","p":"Correcto. En una cuesta, quede a menos de seis pulgadas de la acera."},"ref":{"doc":"OK","page":47}},{"id":"ok-046","scope":"OK","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Oklahoma, how close to the driveway entrance of a fire station may you park on the same side of the street?","o":["As close as you like","No closer than 5 feet","No closer than 10 feet","No closer than 20 feet"],"h1":"Fire trucks need room to get out fast.","h2":"In Oklahoma, you may not park within 20 feet of the driveway entrance to a fire station.","p":"Right. Stay at least 20 feet from a fire station entrance."},"es":{"q":"En Oklahoma, ¿qué tan cerca de la entrada de un cuartel de bomberos puede estacionarse del mismo lado de la calle?","o":["Tan cerca como quiera","A no menos de 5 pies","A no menos de 10 pies","A no menos de 20 pies"],"h1":"Los camiones de bomberos necesitan espacio para salir rápido.","h2":"En Oklahoma, no puede estacionarse a menos de 20 pies de la entrada de un cuartel de bomberos.","p":"Correcto. Quédese por lo menos a 20 pies de la entrada de un cuartel de bomberos."},"ref":{"doc":"OK","page":49}},{"id":"ok-047","scope":"OK","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Oklahoma, a bicyclist comes to a stop sign, and there is no danger. What does the law allow the bicyclist to do?","o":["Slow down, yield, and go on without a full stop","Nothing: the bicyclist must always stop fully","Get off and walk the bike across","Wait for a car to wave them on"],"h1":"Oklahoma has a special stop sign rule for bicycles.","h2":"In Oklahoma, a bicyclist must slow down at a stop sign and yield, but may go on without stopping when there is no danger.","p":"Right. With no danger, a bicyclist may slow, yield and roll through a stop sign."},"es":{"q":"En Oklahoma, un ciclista llega a una señal de alto y no hay peligro. ¿Qué le permite hacer la ley?","o":["Reducir la velocidad, ceder el paso y seguir sin detenerse por completo","Nada: el ciclista siempre debe detenerse por completo","Bajarse y cruzar caminando con la bicicleta","Esperar a que un carro le haga señas para pasar"],"h1":"Oklahoma tiene una regla especial de la señal de alto para las bicicletas.","h2":"En Oklahoma, un ciclista debe reducir la velocidad ante una señal de alto y ceder el paso, pero puede seguir sin detenerse cuando no hay peligro.","p":"Correcto. Sin peligro, el ciclista puede reducir la velocidad, ceder el paso y seguir."},"ref":{"doc":"OK","page":52}},{"id":"ok-048","scope":"OK","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Oklahoma, a bicyclist has stopped at a red light, and no traffic is a danger. What may the bicyclist do?","o":["Wait for green, no matter what","Ride onto the sidewalk to cross","Go on through the red light with care","Wait two full minutes, then go"],"h1":"For bicycles, Oklahoma treats a red light much like a stop sign.","h2":"In Oklahoma, a bicyclist must stop at a red light, but may then go on through it when it is safe and no traffic is a danger.","p":"Right. After stopping, a bicyclist may go through a red light when it is safe."},"es":{"q":"En Oklahoma, un ciclista se detuvo en un semáforo en rojo y ningún vehículo es un peligro. ¿Qué puede hacer el ciclista?","o":["Esperar la luz verde, pase lo que pase","Subirse a la banqueta para cruzar","Seguir a través de la luz roja con cuidado","Esperar dos minutos completos y luego seguir"],"h1":"Para las bicicletas, Oklahoma trata la luz roja casi como una señal de alto.","h2":"En Oklahoma, un ciclista debe detenerse ante una luz roja, pero luego puede seguir cuando es seguro y ningún vehículo es un peligro.","p":"Correcto. Después de detenerse, el ciclista puede pasar la luz roja cuando es seguro."},"ref":{"doc":"OK","page":52}},{"id":"ok-049","scope":"OK","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Oklahoma, may you coast down a hill with your car in neutral?","o":["Yes, it saves fuel","No, it is against the law","Yes, on steep hills only","Yes, if no one is behind you"],"h1":"On a downhill, you need the engine to help control your speed.","h2":"In Oklahoma, coasting downhill with the car in neutral is against the law.","p":"Right. Coasting downhill in neutral is illegal in Oklahoma."},"es":{"q":"En Oklahoma, ¿puede bajar una cuesta en neutro, dejando rodar el carro?","o":["Sí, ahorra gasolina","No, es contra la ley","Sí, solo en cuestas empinadas","Sí, si nadie viene detrás"],"h1":"Al bajar una cuesta, necesita el motor para ayudar a controlar la velocidad.","h2":"En Oklahoma, bajar una cuesta con el carro en neutro es contra la ley.","p":"Correcto. Bajar una cuesta en neutro es ilegal en Oklahoma."},"ref":{"doc":"OK","page":59}},{"id":"ok-050","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, a driver with no insurance is in a crash. When will Service Oklahoma suspend that driver's license?","o":["Only if someone is killed","Only after a third crash","Only if the police ask for it","If anyone is hurt or the damage is $500 or more"],"h1":"The damage amount is quite low.","h2":"In Oklahoma, an uninsured driver in a crash with any injury or with property damage of $500 or more will have the license suspended.","p":"Right. Any injury or $500 in damage means suspension for an uninsured driver."},"es":{"q":"En Oklahoma, un conductor sin seguro tiene un choque. ¿Cuándo le suspende Service Oklahoma la licencia?","o":["Solo si alguien muere","Solo después de un tercer choque","Solo si la policía lo pide","Si alguien sale herido o los daños son de $500 o más"],"h1":"La cantidad de daños es bastante baja.","h2":"En Oklahoma, a un conductor sin seguro que tiene un choque con cualquier herido o con daños de $500 o más se le suspende la licencia.","p":"Correcto. Cualquier herido o $500 en daños significa suspensión para un conductor sin seguro."},"ref":{"doc":"OK","page":16}},{"id":"or-001","scope":"OR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oregon, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before the provisional license.","h2":"In Oregon you can get an instruction permit at 15.","p":"Right. The Oregon instruction permit starts at 15."},"es":{"q":"En Oregon, ¿cuál es la edad mínima para obtener el permiso de instrucción?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la licencia provisional.","h2":"En Oregon usted puede obtener el permiso de instrucción a los 15 años.","p":"Correcto. El permiso de instrucción en Oregon empieza a los 15."},"zh":{"q":"在 Oregon，最小几岁可以拿到学习驾照（instruction permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比过渡驾照早一年。","h2":"在 Oregon，你 15 岁就可以拿到学习驾照。","p":"对。Oregon 的学习驾照从 15 岁开始。"},"vi":{"q":"Ở Oregon, tuổi nhỏ nhất để lấy giấy phép tập lái (instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là một năm trước khi lấy bằng lái tạm thời (provisional license).","h2":"Ở Oregon, bạn có thể lấy giấy phép tập lái khi 15 tuổi.","p":"Đúng. Giấy phép tập lái ở Oregon bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Oregon, ano ang pinakabatang edad para makakuha ng instruction permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ang provisional license.","h2":"Sa Oregon, puwede kang kumuha ng instruction permit sa edad na 15.","p":"Tama. Nagsisimula ang instruction permit sa Oregon sa edad na 15."},"ar":{"q":"في Oregon، ما أصغر عمر للحصول على تصريح التعلّم (instruction permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هو سنة واحدة قبل الرخصة المؤقتة (provisional license).","h2":"في Oregon يمكنك الحصول على تصريح التعلّم في عمر 15 سنة.","p":"صحيح. في Oregon يبدأ تصريح التعلّم في عمر 15 سنة."},"ref":{"doc":"OR","page":89}},{"id":"or-002","scope":"OR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oregon, how old must the licensed person beside a permit driver be?","o":["At least 16","At least 18","At least 21","At least 30"],"h1":"It is the age when an adult may legally buy alcohol.","h2":"An Oregon permit driver must have a licensed person who is at least 21 years old in the seat beside them.","p":"Right. The person beside you must be 21 or older."},"es":{"q":"En Oregon, ¿qué edad debe tener la persona con licencia que va al lado de un conductor con permiso?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 21","Por lo menos 30"],"h1":"Es la edad en que un adulto ya puede comprar alcohol legalmente.","h2":"Un conductor con permiso en Oregon debe llevar al lado a una persona con licencia de por lo menos 21 años.","p":"Correcto. Su acompañante debe tener 21 años o más."},"zh":{"q":"在 Oregon，坐在学习驾照司机旁边的有驾照的人必须几岁？","o":["至少 16 岁","至少 18 岁","至少 21 岁","至少 30 岁"],"h1":"它是成年人可以合法买酒的年龄。","h2":"Oregon 的学习驾照司机旁边的座位必须坐一位至少 21 岁、有驾照的人。","p":"对。你旁边的人必须 21 岁或以上。"},"vi":{"q":"Ở Oregon, người có bằng lái ngồi bên cạnh người tập lái phải bao nhiêu tuổi?","o":["Ít nhất 16 tuổi","Ít nhất 18 tuổi","Ít nhất 21 tuổi","Ít nhất 30 tuổi"],"h1":"Đó là tuổi người lớn được phép mua rượu theo luật.","h2":"Ở Oregon, người tập lái phải có một người có bằng lái, ít nhất 21 tuổi, ngồi ở ghế bên cạnh.","p":"Đúng. Người ngồi bên cạnh bạn phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Oregon, ilang taon dapat ang taong may lisensya na nakaupo sa tabi ng nagmamaneho na may permit?","o":["Hindi bababa sa 16","Hindi bababa sa 18","Hindi bababa sa 21","Hindi bababa sa 30"],"h1":"Ito ang edad kung kailan legal nang bumili ng alak ang isang adulto.","h2":"Sa Oregon, ang nagmamaneho na may permit ay dapat may kasamang taong may lisensya na hindi bababa sa 21 taong gulang sa upuan sa tabi niya.","p":"Tama. Ang katabi mo ay dapat 21 taong gulang o higit pa."},"ar":{"q":"في Oregon، كم يجب أن يكون عمر الشخص الحاصل على رخصة والجالس بجانب سائق التصريح؟","o":["16 سنة على الأقل","18 سنة على الأقل","21 سنة على الأقل","30 سنة على الأقل"],"h1":"هو العمر الذي يُسمح فيه للبالغ قانونًا بشراء الكحول.","h2":"في Oregon يجب أن يجلس بجانب سائق التصريح شخص حاصل على رخصة وعمره 21 سنة على الأقل.","p":"صحيح. يجب أن يكون الشخص بجانبك في عمر 21 سنة أو أكثر."},"ref":{"doc":"OR","page":90}},{"id":"or-003","scope":"OR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oregon, how long must the adult beside a permit driver have held a valid license?","o":["At least 3 years","At least 1 month","At least 10 years","At least 20 years"],"h1":"It is a few years, fewer than five.","h2":"In Oregon, the adult beside a permit driver must have held a valid license for at least 3 years.","p":"Right. Three years of license experience is required."},"es":{"q":"En Oregon, ¿cuánto tiempo debe haber tenido una licencia válida el adulto que va al lado de un conductor con permiso?","o":["Por lo menos 3 años","Por lo menos 1 mes","Por lo menos 10 años","Por lo menos 20 años"],"h1":"Son pocos años, menos de cinco.","h2":"En Oregon, el adulto que va al lado de un conductor con permiso debe haber tenido una licencia válida por lo menos 3 años.","p":"Correcto. Se requieren tres años con licencia."},"zh":{"q":"在 Oregon，坐在学习驾照司机旁边的成年人必须有有效驾照多久？","o":["至少 3 年","至少 1 个月","至少 10 年","至少 20 年"],"h1":"它是几年，少于五年。","h2":"在 Oregon，坐在学习驾照司机旁边的成年人必须有有效驾照至少 3 年。","p":"对。需要有三年驾照经验。"},"vi":{"q":"Ở Oregon, người lớn ngồi bên cạnh người tập lái phải có bằng lái hợp lệ trong bao lâu?","o":["Ít nhất 3 năm","Ít nhất 1 tháng","Ít nhất 10 năm","Ít nhất 20 năm"],"h1":"Đó là vài năm, ít hơn năm năm.","h2":"Ở Oregon, người lớn ngồi bên cạnh người tập lái phải có bằng lái hợp lệ ít nhất 3 năm.","p":"Đúng. Cần có ba năm kinh nghiệm có bằng lái."},"tl":{"q":"Sa Oregon, gaano katagal na dapat may valid na lisensya ang adultong nakaupo sa tabi ng nagmamaneho na may permit?","o":["Hindi bababa sa 3 taon","Hindi bababa sa 1 buwan","Hindi bababa sa 10 taon","Hindi bababa sa 20 taon"],"h1":"Ilang taon ito, kulang sa lima.","h2":"Sa Oregon, ang adultong katabi ng nagmamaneho na may permit ay dapat may valid na lisensya nang hindi bababa sa 3 taon.","p":"Tama. Kailangan ang tatlong taong karanasan na may lisensya."},"ar":{"q":"في Oregon، منذ كم من الوقت يجب أن يحمل البالغ الجالس بجانب سائق التصريح رخصة سارية؟","o":["3 سنوات على الأقل","شهر واحد على الأقل","10 سنوات على الأقل","20 سنة على الأقل"],"h1":"هي بضع سنوات، أقل من خمس.","h2":"في Oregon يجب أن يكون البالغ الجالس بجانب سائق التصريح قد حمل رخصة سارية لمدة 3 سنوات على الأقل.","p":"صحيح. يلزم ثلاث سنوات من الخبرة مع الرخصة."},"ref":{"doc":"OR","page":90}},{"id":"or-004","scope":"OR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oregon, how many supervised driving hours does a teen need if they took an approved driver education course?","o":["20 hours","30 hours","100 hours","50 hours"],"h1":"It is half of what a teen without the course needs.","h2":"An Oregon teen who completes an approved driver education course needs 50 hours of supervised driving.","p":"Right. With driver education, Oregon asks for 50 hours."},"es":{"q":"En Oregon, ¿cuántas horas de manejo supervisado necesita un adolescente que tomó un curso aprobado de educación vial?","o":["20 horas","30 horas","100 horas","50 horas"],"h1":"Es la mitad de lo que necesita un adolescente sin el curso.","h2":"Un adolescente en Oregon que termina un curso aprobado de educación vial necesita 50 horas de manejo supervisado.","p":"Correcto. Con educación vial, Oregon pide 50 horas."},"zh":{"q":"在 Oregon，上过认可的驾驶教育课程的青少年，需要多少小时有人监督的驾驶？","o":["20 小时","30 小时","100 小时","50 小时"],"h1":"它是没上课程的青少年需要的一半。","h2":"Oregon 上完认可的驾驶教育课程的青少年，需要 50 小时有人监督的驾驶。","p":"对。上了驾驶教育，Oregon 要求 50 小时。"},"vi":{"q":"Ở Oregon, thiếu niên cần bao nhiêu giờ lái xe có người giám sát nếu đã học một khóa giáo dục lái xe được chấp thuận?","o":["20 giờ","30 giờ","100 giờ","50 giờ"],"h1":"Đó là một nửa số giờ của thiếu niên không học khóa này.","h2":"Ở Oregon, thiếu niên hoàn thành khóa giáo dục lái xe được chấp thuận cần 50 giờ lái xe có người giám sát.","p":"Đúng. Có học giáo dục lái xe, Oregon yêu cầu 50 giờ."},"tl":{"q":"Sa Oregon, ilang oras ng pagmamaneho na may gumagabay ang kailangan ng isang teen kung kumuha siya ng aprubadong kurso sa driver education?","o":["20 oras","30 oras","100 oras","50 oras"],"h1":"Kalahati ito ng kailangan ng teen na walang kurso.","h2":"Sa Oregon, ang teen na tapos sa aprubadong kurso sa driver education ay kailangan ng 50 oras ng pagmamaneho na may gumagabay.","p":"Tama. Kapag may driver education, 50 oras ang hinihingi ng Oregon."},"ar":{"q":"في Oregon، كم ساعة من القيادة تحت الإشراف يحتاج المراهق إذا أخذ دورة تعليم قيادة معتمدة؟","o":["20 ساعة","30 ساعة","100 ساعة","50 ساعة"],"h1":"هي نصف ما يحتاجه المراهق الذي لم يأخذ الدورة.","h2":"في Oregon يحتاج المراهق الذي أكمل دورة تعليم قيادة معتمدة إلى 50 ساعة من القيادة تحت الإشراف.","p":"صحيح. مع تعليم القيادة تطلب Oregon خمسين ساعة."},"ref":{"doc":"OR","page":90}},{"id":"or-005","scope":"OR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oregon, how many supervised driving hours does a teen need without a driver education course?","o":["50 hours","70 hours","100 hours","150 hours"],"h1":"It is twice the number needed with the course.","h2":"An Oregon teen who does not take an approved driver education course needs 100 hours of supervised driving.","p":"Right. Without driver education, Oregon asks for 100 hours."},"es":{"q":"En Oregon, ¿cuántas horas de manejo supervisado necesita un adolescente sin curso de educación vial?","o":["50 horas","70 horas","100 horas","150 horas"],"h1":"Es el doble de lo que se necesita con el curso.","h2":"Un adolescente en Oregon que no toma un curso aprobado de educación vial necesita 100 horas de manejo supervisado.","p":"Correcto. Sin educación vial, Oregon pide 100 horas."},"zh":{"q":"在 Oregon，没上驾驶教育课程的青少年，需要多少小时有人监督的驾驶？","o":["50 小时","70 小时","100 小时","150 小时"],"h1":"它是上了课程需要的两倍。","h2":"Oregon 没上认可的驾驶教育课程的青少年，需要 100 小时有人监督的驾驶。","p":"对。没上驾驶教育，Oregon 要求 100 小时。"},"vi":{"q":"Ở Oregon, thiếu niên cần bao nhiêu giờ lái xe có người giám sát nếu không học khóa giáo dục lái xe?","o":["50 giờ","70 giờ","100 giờ","150 giờ"],"h1":"Đó là gấp đôi số giờ khi có học khóa này.","h2":"Ở Oregon, thiếu niên không học khóa giáo dục lái xe được chấp thuận cần 100 giờ lái xe có người giám sát.","p":"Đúng. Không học giáo dục lái xe, Oregon yêu cầu 100 giờ."},"tl":{"q":"Sa Oregon, ilang oras ng pagmamaneho na may gumagabay ang kailangan ng isang teen kung walang kurso sa driver education?","o":["50 oras","70 oras","100 oras","150 oras"],"h1":"Doble ito ng kailangan kapag may kurso.","h2":"Sa Oregon, ang teen na hindi kumuha ng aprubadong kurso sa driver education ay kailangan ng 100 oras ng pagmamaneho na may gumagabay.","p":"Tama. Kapag walang driver education, 100 oras ang hinihingi ng Oregon."},"ar":{"q":"في Oregon، كم ساعة من القيادة تحت الإشراف يحتاج المراهق بدون دورة تعليم قيادة؟","o":["50 ساعة","70 ساعة","100 ساعة","150 ساعة"],"h1":"هي ضعف العدد المطلوب مع الدورة.","h2":"في Oregon يحتاج المراهق الذي لم يأخذ دورة تعليم قيادة معتمدة إلى 100 ساعة من القيادة تحت الإشراف.","p":"صحيح. بدون تعليم القيادة تطلب Oregon مئة ساعة."},"ref":{"doc":"OR","page":90}},{"id":"or-006","scope":"OR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oregon, how long must a teen hold an instruction permit before getting a provisional license?","o":["1 month","6 months","2 years","No minimum time"],"h1":"It is half a year.","h2":"An Oregon teen must hold the instruction permit for at least 6 months before getting a provisional license.","p":"Right. Six months with the permit first."},"es":{"q":"En Oregon, ¿cuánto tiempo debe tener un adolescente el permiso de instrucción antes de obtener la licencia provisional?","o":["1 mes","6 meses","2 años","No hay tiempo mínimo"],"h1":"Es medio año.","h2":"Un adolescente en Oregon debe tener el permiso de instrucción por lo menos 6 meses antes de obtener la licencia provisional.","p":"Correcto. Primero, seis meses con el permiso."},"zh":{"q":"在 Oregon，青少年拿过渡驾照（provisional license）前，必须持有学习驾照多久？","o":["1 个月","6 个月","2 年","没有最短时间"],"h1":"它是半年。","h2":"Oregon 的青少年必须持有学习驾照至少 6 个月，才能拿过渡驾照。","p":"对。先持有学习驾照六个月。"},"vi":{"q":"Ở Oregon, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái tạm thời?","o":["1 tháng","6 tháng","2 năm","Không có thời gian tối thiểu"],"h1":"Đó là nửa năm.","h2":"Ở Oregon, thiếu niên phải giữ giấy phép tập lái ít nhất 6 tháng trước khi lấy bằng lái tạm thời.","p":"Đúng. Trước tiên phải có giấy phép tập lái sáu tháng."},"tl":{"q":"Sa Oregon, gaano katagal dapat hawak ng isang teen ang instruction permit bago makakuha ng provisional license?","o":["1 buwan","6 na buwan","2 taon","Walang pinakamaikling panahon"],"h1":"Kalahating taon ito.","h2":"Sa Oregon, dapat hawak ng teen ang instruction permit nang hindi bababa sa 6 na buwan bago makakuha ng provisional license.","p":"Tama. Anim na buwan muna na may permit."},"ar":{"q":"في Oregon، كم من الوقت يجب أن يحمل المراهق تصريح التعلّم قبل الحصول على الرخصة المؤقتة؟","o":["شهر واحد","6 أشهر","سنتان","لا توجد مدة دنيا"],"h1":"هي نصف سنة.","h2":"في Oregon يجب أن يحمل المراهق تصريح التعلّم 6 أشهر على الأقل قبل الحصول على الرخصة المؤقتة.","p":"صحيح. ستة أشهر مع التصريح أولًا."},"ref":{"doc":"OR","page":90}},{"id":"or-007","scope":"OR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oregon, during the first 6 months of a provisional license, who may ride as a passenger under age 20?","o":["Only immediate family members","Up to three friends","Any one friend","Anyone with a seat belt"],"h1":"Think of the people you live with.","h2":"During the first 6 months of an Oregon provisional license, passengers under 20 must be immediate family members.","p":"Right. Only family under 20 at first."},"es":{"q":"En Oregon, durante los primeros 6 meses de la licencia provisional, ¿quién puede viajar como pasajero menor de 20 años?","o":["Solo familiares directos","Hasta tres amigos","Un amigo cualquiera","Cualquiera con cinturón"],"h1":"Piense en las personas con quienes vive.","h2":"Durante los primeros 6 meses de la licencia provisional de Oregon, los pasajeros menores de 20 años deben ser familiares directos.","p":"Correcto. Al principio, solo familiares menores de 20."},"zh":{"q":"在 Oregon，持过渡驾照的前 6 个月，谁可以作为未满 20 岁的乘客坐车？","o":["只有直系亲属","最多三个朋友","任何一个朋友","任何系了安全带的人"],"h1":"想想和你住在一起的人。","h2":"Oregon 持过渡驾照的前 6 个月，未满 20 岁的乘客必须是直系亲属。","p":"对。一开始只能载未满 20 岁的家人。"},"vi":{"q":"Ở Oregon, trong 6 tháng đầu có bằng lái tạm thời, ai dưới 20 tuổi được đi cùng xe làm hành khách?","o":["Chỉ người thân trong gia đình","Tối đa ba người bạn","Một người bạn bất kỳ","Bất kỳ ai có thắt dây an toàn"],"h1":"Hãy nghĩ đến những người sống cùng nhà với bạn.","h2":"Trong 6 tháng đầu có bằng lái tạm thời ở Oregon, hành khách dưới 20 tuổi phải là người thân trong gia đình.","p":"Đúng. Lúc đầu, chỉ người thân dưới 20 tuổi."},"tl":{"q":"Sa Oregon, sa unang 6 na buwan ng provisional license, sino ang puwedeng isakay na pasaherong wala pang 20 taong gulang?","o":["Mga kapamilya lamang","Hanggang tatlong kaibigan","Kahit sinong isang kaibigan","Kahit sino na naka-seat belt"],"h1":"Isipin ang mga taong kasama mo sa bahay.","h2":"Sa unang 6 na buwan ng provisional license sa Oregon, ang mga pasaherong wala pang 20 ay dapat kapamilya.","p":"Tama. Sa simula, kapamilya lamang ang puwede kung wala pang 20."},"ar":{"q":"في Oregon، خلال أول 6 أشهر من الرخصة المؤقتة، من يمكنه الركوب كراكب إذا كان عمره أقل من 20 سنة؟","o":["أفراد العائلة المباشرة فقط","حتى ثلاثة أصدقاء","صديق واحد أيًّا كان","أي شخص يضع حزام الأمان"],"h1":"فكّر في الأشخاص الذين تعيش معهم.","h2":"خلال أول 6 أشهر من الرخصة المؤقتة في Oregon، يجب أن يكون الركاب الذين أعمارهم أقل من 20 سنة من أفراد العائلة المباشرة.","p":"صحيح. في البداية العائلة فقط لمن هم أقل من 20 سنة."},"ref":{"doc":"OR","page":null}},{"id":"or-008","scope":"OR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oregon, during the second 6 months of a provisional license, how many passengers under 20 who are not family may ride along?","o":["None","One","No more than three","No limit"],"h1":"The limit loosens, but there is still a limit.","h2":"During the second 6 months of an Oregon provisional license, the driver may carry no more than three passengers under 20 who are not family.","p":"Right. Up to three in the second six months."},"es":{"q":"En Oregon, durante los segundos 6 meses de la licencia provisional, ¿cuántos pasajeros menores de 20 años que no son familiares pueden viajar?","o":["Ninguno","Uno","No más de tres","Sin límite"],"h1":"El límite se afloja, pero todavía hay un límite.","h2":"Durante los segundos 6 meses de la licencia provisional de Oregon, el conductor puede llevar como máximo tres pasajeros menores de 20 años que no son familiares.","p":"Correcto. Hasta tres en los segundos seis meses."},"zh":{"q":"在 Oregon，持过渡驾照的第二个 6 个月，可以载几位不是家人、未满 20 岁的乘客？","o":["一位也不行","一位","不超过三位","没有限制"],"h1":"限制放宽了，但还是有限制。","h2":"Oregon 持过渡驾照的第二个 6 个月，司机最多可以载三位不是家人、未满 20 岁的乘客。","p":"对。第二个六个月最多三位。"},"vi":{"q":"Ở Oregon, trong 6 tháng thứ hai có bằng lái tạm thời, được chở bao nhiêu hành khách dưới 20 tuổi không phải người thân?","o":["Không ai","Một người","Không quá ba người","Không giới hạn"],"h1":"Giới hạn được nới ra, nhưng vẫn còn giới hạn.","h2":"Trong 6 tháng thứ hai có bằng lái tạm thời ở Oregon, người lái được chở không quá ba hành khách dưới 20 tuổi không phải người thân.","p":"Đúng. Tối đa ba người trong sáu tháng thứ hai."},"tl":{"q":"Sa Oregon, sa ikalawang 6 na buwan ng provisional license, ilang pasaherong wala pang 20 na hindi kapamilya ang puwedeng isakay?","o":["Wala","Isa","Hindi hihigit sa tatlo","Walang limitasyon"],"h1":"Lumuluwag ang limitasyon, pero may limitasyon pa rin.","h2":"Sa ikalawang 6 na buwan ng provisional license sa Oregon, puwedeng magsakay ang driver ng hindi hihigit sa tatlong pasaherong wala pang 20 na hindi kapamilya.","p":"Tama. Hanggang tatlo sa ikalawang anim na buwan."},"ar":{"q":"في Oregon، خلال الأشهر الستة الثانية من الرخصة المؤقتة، كم راكبًا أقل من 20 سنة من غير العائلة يمكن أن يركب معك؟","o":["لا أحد","واحد","ثلاثة على الأكثر","بلا حد"],"h1":"يصبح الحد أخفّ، لكن ما زال هناك حد.","h2":"خلال الأشهر الستة الثانية من الرخصة المؤقتة في Oregon، يمكن للسائق أن يحمل ثلاثة ركاب على الأكثر أعمارهم أقل من 20 سنة وليسوا من العائلة.","p":"صحيح. حتى ثلاثة في الأشهر الستة الثانية."},"ref":{"doc":"OR","page":null}},{"id":"or-009","scope":"OR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oregon, during which hours may a provisional driver in the first year not drive, unless an exception applies?","o":["9 p.m. to 6 a.m.","10 p.m. to 5 a.m.","11 p.m. to 4 a.m.","Midnight to 5 a.m."],"h1":"It starts at the very start of a new day.","h2":"In the first year, an Oregon provisional driver may not drive from midnight to 5 a.m. unless an exception applies.","p":"Right. Midnight to 5 a.m. is off limits."},"es":{"q":"En Oregon, ¿en qué horario no puede manejar un conductor provisional en su primer año, salvo una excepción?","o":["De 9 p.m. a 6 a.m.","De 10 p.m. a 5 a.m.","De 11 p.m. a 4 a.m.","De medianoche a 5 a.m."],"h1":"Empieza justo al comienzo de un nuevo día.","h2":"En el primer año, un conductor provisional en Oregon no puede manejar de medianoche a 5 a.m., salvo una excepción.","p":"Correcto. De medianoche a 5 a.m. no se maneja."},"zh":{"q":"在 Oregon，除非有例外情况，持过渡驾照第一年的司机在哪个时间段不能开车？","o":["晚上 9 点到早上 6 点","晚上 10 点到早上 5 点","晚上 11 点到凌晨 4 点","午夜到早上 5 点"],"h1":"它从新的一天刚开始的时候开始。","h2":"在第一年，Oregon 持过渡驾照的司机从午夜到早上 5 点不能开车，除非有例外情况。","p":"对。午夜到早上 5 点不能开车。"},"vi":{"q":"Ở Oregon, trong năm đầu, người có bằng lái tạm thời không được lái xe vào giờ nào, trừ khi có ngoại lệ?","o":["9 giờ tối đến 6 giờ sáng","10 giờ tối đến 5 giờ sáng","11 giờ tối đến 4 giờ sáng","Nửa đêm đến 5 giờ sáng"],"h1":"Nó bắt đầu ngay lúc bắt đầu một ngày mới.","h2":"Trong năm đầu, người có bằng lái tạm thời ở Oregon không được lái xe từ nửa đêm đến 5 giờ sáng, trừ khi có ngoại lệ.","p":"Đúng. Không được lái từ nửa đêm đến 5 giờ sáng."},"tl":{"q":"Sa Oregon, sa unang taon, anong oras hindi puwedeng magmaneho ang may provisional license, maliban kung may exception?","o":["9 p.m. hanggang 6 a.m.","10 p.m. hanggang 5 a.m.","11 p.m. hanggang 4 a.m.","Hatinggabi hanggang 5 a.m."],"h1":"Nagsisimula ito sa mismong simula ng bagong araw.","h2":"Sa unang taon, ang may provisional license sa Oregon ay hindi puwedeng magmaneho mula hatinggabi hanggang 5 a.m., maliban kung may exception.","p":"Tama. Bawal mula hatinggabi hanggang 5 a.m."},"ar":{"q":"في Oregon، في أي ساعات لا يجوز لسائق الرخصة المؤقتة في السنة الأولى أن يقود، إلا إذا انطبق استثناء؟","o":["من 9 مساءً إلى 6 صباحًا","من 10 مساءً إلى 5 صباحًا","من 11 مساءً إلى 4 صباحًا","من منتصف الليل إلى 5 صباحًا"],"h1":"تبدأ في أول لحظة من يوم جديد.","h2":"في السنة الأولى لا يجوز لسائق الرخصة المؤقتة في Oregon أن يقود من منتصف الليل إلى 5 صباحًا، إلا إذا انطبق استثناء.","p":"صحيح. من منتصف الليل إلى 5 صباحًا ممنوع."},"ref":{"doc":"OR","page":null}},{"id":"or-010","scope":"OR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oregon, a provisional driver may drive between midnight and 5 a.m. when riding with a licensed driver of what age?","o":["At least 18","At least 25","At least 21","At least 65"],"h1":"It is older than the usual permit supervisor.","h2":"An Oregon provisional driver may drive between midnight and 5 a.m. when a licensed driver who is at least 25 years old is along.","p":"Right. A licensed driver 25 or older makes it allowed."},"es":{"q":"En Oregon, un conductor provisional puede manejar entre medianoche y 5 a.m. si lo acompaña un conductor con licencia de ¿qué edad?","o":["Por lo menos 18","Por lo menos 25","Por lo menos 21","Por lo menos 65"],"h1":"Es mayor que la edad del supervisor normal del permiso.","h2":"Un conductor provisional en Oregon puede manejar entre medianoche y 5 a.m. si va con un conductor con licencia de por lo menos 25 años.","p":"Correcto. Con un conductor de 25 años o más, está permitido."},"zh":{"q":"在 Oregon，持过渡驾照的司机和几岁的有驾照司机在一起时，可以在午夜到早上 5 点之间开车？","o":["至少 18 岁","至少 25 岁","至少 21 岁","至少 65 岁"],"h1":"它比通常监督学习驾照的人年龄大。","h2":"Oregon 持过渡驾照的司机如果有一位至少 25 岁、有驾照的司机在车上，就可以在午夜到早上 5 点之间开车。","p":"对。有一位 25 岁或以上、有驾照的司机就可以。"},"vi":{"q":"Ở Oregon, người có bằng lái tạm thời được lái xe từ nửa đêm đến 5 giờ sáng khi đi cùng một người có bằng lái bao nhiêu tuổi?","o":["Ít nhất 18 tuổi","Ít nhất 25 tuổi","Ít nhất 21 tuổi","Ít nhất 65 tuổi"],"h1":"Người này lớn tuổi hơn người giám sát tập lái thông thường.","h2":"Ở Oregon, người có bằng lái tạm thời được lái xe từ nửa đêm đến 5 giờ sáng khi có một người có bằng lái ít nhất 25 tuổi đi cùng.","p":"Đúng. Có người có bằng lái từ 25 tuổi trở lên đi cùng thì được phép."},"tl":{"q":"Sa Oregon, puwedeng magmaneho ang may provisional license mula hatinggabi hanggang 5 a.m. kung kasama ang driver na may lisensya na ilang taong gulang?","o":["Hindi bababa sa 18","Hindi bababa sa 25","Hindi bababa sa 21","Hindi bababa sa 65"],"h1":"Mas matanda ito kaysa sa karaniwang gumagabay sa may permit.","h2":"Sa Oregon, puwedeng magmaneho ang may provisional license mula hatinggabi hanggang 5 a.m. kung kasama ang driver na may lisensya na hindi bababa sa 25 taong gulang.","p":"Tama. Puwede kapag kasama ang driver na may lisensya na 25 o higit pa."},"ar":{"q":"في Oregon، يجوز لسائق الرخصة المؤقتة أن يقود بين منتصف الليل و5 صباحًا إذا كان معه سائق حاصل على رخصة بأي عمر؟","o":["18 سنة على الأقل","25 سنة على الأقل","21 سنة على الأقل","65 سنة على الأقل"],"h1":"هو أكبر من عمر المشرف المعتاد على سائق التصريح.","h2":"في Oregon يجوز لسائق الرخصة المؤقتة أن يقود بين منتصف الليل و5 صباحًا إذا كان معه سائق حاصل على رخصة وعمره 25 سنة على الأقل.","p":"صحيح. وجود سائق مرخّص عمره 25 سنة أو أكثر يجعل ذلك مسموحًا."},"ref":{"doc":"OR","page":null}},{"id":"or-011","scope":"OR","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Oregon, may a driver under 18 talk on a cell phone with a hands-free device?","o":["No, not even hands-free","Yes, hands-free is always allowed","Yes, but only on highways","Yes, but only during the day"],"h1":"The rule for teens is stricter than for adults.","h2":"In Oregon, a driver under 18 may not use a cell phone while driving, not even with a hands-free device.","p":"Right. No phone at all for drivers under 18."},"es":{"q":"En Oregon, ¿puede un conductor menor de 18 años hablar por celular con un dispositivo de manos libres?","o":["No, ni siquiera con manos libres","Sí, manos libres siempre está permitido","Sí, pero solo en autopistas","Sí, pero solo de día"],"h1":"La regla para adolescentes es más estricta que para adultos.","h2":"En Oregon, un conductor menor de 18 años no puede usar el celular mientras maneja, ni siquiera con un dispositivo de manos libres.","p":"Correcto. Nada de teléfono para menores de 18."},"zh":{"q":"在 Oregon，未满 18 岁的司机可以用免提设备打手机吗？","o":["不可以，免提也不行","可以，免提一直都可以","可以，但只在高速公路上","可以，但只在白天"],"h1":"青少年的规定比成年人严。","h2":"在 Oregon，未满 18 岁的司机开车时不能用手机，用免提设备也不行。","p":"对。未满 18 岁的司机完全不能用手机。"},"vi":{"q":"Ở Oregon, người lái xe dưới 18 tuổi có được nói chuyện điện thoại bằng thiết bị rảnh tay (hands-free) không?","o":["Không, kể cả rảnh tay","Có, rảnh tay luôn được phép","Có, nhưng chỉ trên xa lộ","Có, nhưng chỉ vào ban ngày"],"h1":"Quy định cho thiếu niên nghiêm hơn cho người lớn.","h2":"Ở Oregon, người lái xe dưới 18 tuổi không được dùng điện thoại khi lái xe, kể cả với thiết bị rảnh tay.","p":"Đúng. Người lái dưới 18 tuổi hoàn toàn không được dùng điện thoại."},"tl":{"q":"Sa Oregon, puwede bang makipag-usap sa cell phone gamit ang hands-free device ang driver na wala pang 18?","o":["Hindi, kahit hands-free","Oo, laging puwede ang hands-free","Oo, pero sa highway lamang","Oo, pero sa araw lamang"],"h1":"Mas mahigpit ang patakaran sa mga teen kaysa sa mga adulto.","h2":"Sa Oregon, ang driver na wala pang 18 ay hindi puwedeng gumamit ng cell phone habang nagmamaneho, kahit may hands-free device.","p":"Tama. Bawal ang anumang paggamit ng phone sa driver na wala pang 18."},"ar":{"q":"في Oregon، هل يجوز للسائق الذي عمره أقل من 18 سنة أن يتكلم في الهاتف المحمول بجهاز بدون استخدام اليدين (hands-free)؟","o":["لا، ولا حتى بدون استخدام اليدين","نعم، بدون استخدام اليدين مسموح دائمًا","نعم، لكن على الطرق السريعة فقط","نعم، لكن في النهار فقط"],"h1":"القاعدة للمراهقين أشد من القاعدة للبالغين.","h2":"في Oregon لا يجوز للسائق الذي عمره أقل من 18 سنة أن يستخدم الهاتف المحمول أثناء القيادة، ولا حتى بجهاز بدون استخدام اليدين.","p":"صحيح. لا هاتف أبدًا للسائقين تحت 18 سنة."},"ref":{"doc":"OR","page":80}},{"id":"or-012","scope":"OR","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Oregon, you approach a stopped emergency vehicle with lights flashing and cannot change lanes safely. What must you do?","o":["Keep your speed","Stop in your lane","Slow to at least 5 mph below the posted speed","Speed up to pass quickly"],"h1":"You must lower your speed by a set amount.","h2":"In Oregon, if you cannot safely move over, you must slow to at least 5 mph below the posted speed.","p":"Right. Slow down at least 5 mph below the limit."},"es":{"q":"En Oregon, usted se acerca a un vehículo de emergencia detenido con luces encendidas y no puede cambiar de carril con seguridad. ¿Qué debe hacer?","o":["Mantener su velocidad","Detenerse en su carril","Bajar a por lo menos 5 mph menos que la velocidad indicada","Acelerar para pasar rápido"],"h1":"Debe bajar su velocidad una cantidad fija.","h2":"En Oregon, si no puede cambiarse de carril con seguridad, debe bajar a por lo menos 5 mph menos que la velocidad indicada.","p":"Correcto. Baje por lo menos 5 mph del límite."},"zh":{"q":"在 Oregon，你接近一辆停着、闪着灯的紧急车辆，但不能安全地换车道。你必须怎么做？","o":["保持你的速度","在你的车道停下","减速到比标示的限速至少低 5 mph","加速快点开过去"],"h1":"你必须把速度降低一个规定的量。","h2":"在 Oregon，如果你不能安全地让道变道，你必须减速到比标示的限速至少低 5 mph。","p":"对。减速到比限速至少低 5 mph。"},"vi":{"q":"Ở Oregon, bạn đến gần một xe cấp cứu đang dừng và nháy đèn, nhưng không thể đổi làn an toàn. Bạn phải làm gì?","o":["Giữ nguyên tốc độ","Dừng lại trong làn của bạn","Giảm tốc độ xuống ít nhất 5 mph dưới tốc độ quy định trên biển","Tăng tốc để vượt qua nhanh"],"h1":"Bạn phải giảm tốc độ một mức nhất định.","h2":"Ở Oregon, nếu bạn không thể tránh sang làn khác an toàn, bạn phải giảm tốc độ xuống ít nhất 5 mph dưới tốc độ quy định trên biển.","p":"Đúng. Giảm tốc độ ít nhất 5 mph dưới giới hạn."},"tl":{"q":"Sa Oregon, papalapit ka sa nakahintong emergency vehicle na may kumikislap na ilaw at hindi ka ligtas na makakalipat ng lane. Ano ang dapat mong gawin?","o":["Panatilihin ang bilis mo","Huminto sa lane mo","Bagalan sa hindi bababa sa 5 mph na mas mababa sa nakapaskil na speed limit","Bilisan para makalampas agad"],"h1":"Dapat mong ibaba ang bilis mo nang tiyak na halaga.","h2":"Sa Oregon, kung hindi ka ligtas na makakalipat ng lane, dapat kang magbagal nang hindi bababa sa 5 mph na mas mababa sa nakapaskil na speed limit.","p":"Tama. Magbagal nang hindi bababa sa 5 mph na mas mababa sa limit."},"ar":{"q":"في Oregon، تقترب من مركبة طوارئ متوقفة وأضواؤها تومض، ولا تستطيع تغيير المسار بأمان. ماذا يجب أن تفعل؟","o":["حافظ على سرعتك","توقف في مسارك","خفّف السرعة إلى 5 mph على الأقل تحت السرعة المكتوبة على اللافتة","أسرع لتتجاوزها بسرعة"],"h1":"يجب أن تخفض سرعتك بمقدار محدد.","h2":"في Oregon إذا لم تستطع الابتعاد إلى مسار آخر بأمان، يجب أن تخفف السرعة إلى 5 mph على الأقل تحت السرعة المكتوبة على اللافتة.","p":"صحيح. خفّف السرعة 5 mph على الأقل تحت الحد."},"ref":{"doc":"OR","page":null}},{"id":"or-013","scope":"OR","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Oregon, for which stopped vehicles on the shoulder must you move over or slow down?","o":["Only police cars","Only ambulances","Only tow trucks","Any vehicle showing hazard lights, flares or an emergency sign"],"h1":"The law was expanded to cover more than emergency vehicles.","h2":"In Oregon, you must move over or slow down for any vehicle stopped on the shoulder that shows hazard lights, flares or an emergency sign.","p":"Right. The rule covers any stopped vehicle with warning signs."},"es":{"q":"En Oregon, ¿por cuáles vehículos detenidos en el acotamiento debe cambiarse de carril o bajar la velocidad?","o":["Solo patrullas de policía","Solo ambulancias","Solo grúas","Cualquier vehículo con luces de emergencia, bengalas o un letrero de emergencia"],"h1":"La ley se amplió para incluir más que vehículos de emergencia.","h2":"En Oregon, debe cambiarse de carril o bajar la velocidad por cualquier vehículo detenido en el acotamiento que tenga luces de emergencia, bengalas o un letrero de emergencia.","p":"Correcto. La regla incluye cualquier vehículo detenido con señales de aviso."},"zh":{"q":"在 Oregon，路肩上停着哪些车时，你必须让道变道或减速？","o":["只有警车","只有救护车","只有拖车","任何开着危险警示灯、放着照明弹（flare）或紧急标志的车"],"h1":"这条法律扩大了，不只包括紧急车辆。","h2":"在 Oregon，任何停在路肩、开着危险警示灯、放着照明弹（flare）或紧急标志的车，你都必须让道变道或减速。","p":"对。这条规定包括任何有警示标志的停着的车。"},"vi":{"q":"Ở Oregon, bạn phải tránh sang làn khác hoặc giảm tốc độ khi gặp những xe nào đang dừng bên lề đường?","o":["Chỉ xe cảnh sát","Chỉ xe cứu thương","Chỉ xe kéo","Bất kỳ xe nào bật đèn báo nguy hiểm, đặt pháo sáng hoặc có biển báo khẩn cấp"],"h1":"Luật đã được mở rộng, không chỉ cho xe cấp cứu.","h2":"Ở Oregon, bạn phải tránh sang làn khác hoặc giảm tốc độ khi gặp bất kỳ xe nào dừng bên lề đường có bật đèn báo nguy hiểm, đặt pháo sáng hoặc có biển báo khẩn cấp.","p":"Đúng. Quy định áp dụng cho mọi xe đang dừng có dấu hiệu cảnh báo."},"tl":{"q":"Sa Oregon, para sa aling mga sasakyang nakahinto sa gilid ng daan (shoulder) ka dapat lumipat ng lane o magbagal?","o":["Mga sasakyan ng pulis lamang","Mga ambulansya lamang","Mga tow truck lamang","Anumang sasakyan na may hazard lights, flares o emergency sign"],"h1":"Pinalawak ang batas para sumaklaw sa higit pa sa mga emergency vehicle.","h2":"Sa Oregon, dapat kang lumipat ng lane o magbagal para sa anumang sasakyang nakahinto sa shoulder na may hazard lights, flares o emergency sign.","p":"Tama. Sakop ng patakaran ang anumang nakahintong sasakyan na may babala."},"ar":{"q":"في Oregon، لأي مركبات متوقفة على كتف الطريق (shoulder) يجب أن تبتعد إلى مسار آخر أو تخفف السرعة؟","o":["سيارات الشرطة فقط","سيارات الإسعاف فقط","شاحنات السحب فقط","أي مركبة تُظهر أضواء التحذير أو مشاعل أو لافتة طوارئ"],"h1":"تم توسيع القانون ليشمل أكثر من مركبات الطوارئ.","h2":"في Oregon يجب أن تبتعد إلى مسار آخر أو تخفف السرعة لأي مركبة متوقفة على كتف الطريق تُظهر أضواء التحذير أو مشاعل أو لافتة طوارئ.","p":"صحيح. القاعدة تشمل أي مركبة متوقفة عليها علامات تحذير."},"ref":{"doc":"OR","page":null}},{"id":"or-014","scope":"OR","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Oregon, what is the speed limit in a business district when no other limit is posted?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"It is the same as in a school zone.","h2":"In Oregon, the speed limit in a business district is 20 mph unless another limit is posted.","p":"Right. Business districts are 20 mph."},"es":{"q":"En Oregon, ¿cuál es el límite de velocidad en una zona comercial cuando no hay otro límite indicado?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Es igual que en una zona escolar.","h2":"En Oregon, el límite de velocidad en una zona comercial es 20 mph, salvo que haya otro límite indicado.","p":"Correcto. Las zonas comerciales son de 20 mph."},"zh":{"q":"在 Oregon，没有标示其他限速时，商业区的限速是多少？","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"它和学校区一样。","h2":"在 Oregon，除非标示了其他限速，商业区的限速是 20 mph。","p":"对。商业区是 20 mph。"},"vi":{"q":"Ở Oregon, tốc độ giới hạn trong khu thương mại là bao nhiêu khi không có biển báo giới hạn khác?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Giống như trong khu trường học.","h2":"Ở Oregon, tốc độ giới hạn trong khu thương mại là 20 mph, trừ khi có biển báo giới hạn khác.","p":"Đúng. Khu thương mại là 20 mph."},"tl":{"q":"Sa Oregon, ano ang speed limit sa business district kapag walang ibang limit na nakapaskil?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Pareho ito sa school zone.","h2":"Sa Oregon, ang speed limit sa business district ay 20 mph maliban kung may ibang limit na nakapaskil.","p":"Tama. 20 mph sa mga business district."},"ar":{"q":"في Oregon، ما حد السرعة في المنطقة التجارية عندما لا توجد لافتة بحد آخر؟","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"هو نفس الحد في منطقة المدرسة.","h2":"في Oregon حد السرعة في المنطقة التجارية هو 20 mph إلا إذا كانت هناك لافتة بحد آخر.","p":"صحيح. المناطق التجارية 20 mph."},"ref":{"doc":"OR","page":19}},{"id":"or-015","scope":"OR","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Oregon, what is the speed limit in a residential district when no other limit is posted?","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"It is a little faster than a business district.","h2":"In Oregon, the speed limit in a residential district is 25 mph unless another limit is posted.","p":"Right. Residential districts are 25 mph."},"es":{"q":"En Oregon, ¿cuál es el límite de velocidad en una zona residencial cuando no hay otro límite indicado?","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"Es un poco más rápido que en una zona comercial.","h2":"En Oregon, el límite de velocidad en una zona residencial es 25 mph, salvo que haya otro límite indicado.","p":"Correcto. Las zonas residenciales son de 25 mph."},"zh":{"q":"在 Oregon，没有标示其他限速时，住宅区的限速是多少？","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"它比商业区快一点。","h2":"在 Oregon，除非标示了其他限速，住宅区的限速是 25 mph。","p":"对。住宅区是 25 mph。"},"vi":{"q":"Ở Oregon, tốc độ giới hạn trong khu dân cư là bao nhiêu khi không có biển báo giới hạn khác?","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"Nhanh hơn khu thương mại một chút.","h2":"Ở Oregon, tốc độ giới hạn trong khu dân cư là 25 mph, trừ khi có biển báo giới hạn khác.","p":"Đúng. Khu dân cư là 25 mph."},"tl":{"q":"Sa Oregon, ano ang speed limit sa residential district kapag walang ibang limit na nakapaskil?","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"Medyo mas mabilis ito kaysa sa business district.","h2":"Sa Oregon, ang speed limit sa residential district ay 25 mph maliban kung may ibang limit na nakapaskil.","p":"Tama. 25 mph sa mga residential district."},"ar":{"q":"في Oregon، ما حد السرعة في المنطقة السكنية عندما لا توجد لافتة بحد آخر؟","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"هو أسرع قليلًا من المنطقة التجارية.","h2":"في Oregon حد السرعة في المنطقة السكنية هو 25 mph إلا إذا كانت هناك لافتة بحد آخر.","p":"صحيح. المناطق السكنية 25 mph."},"ref":{"doc":"OR","page":19}},{"id":"or-016","scope":"OR","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Oregon, what is the speed limit in an alley?","o":["25 mph","20 mph","15 mph","5 mph"],"h1":"It is the slowest of the usual city limits.","h2":"In Oregon, the speed limit in an alley is 15 mph.","p":"Right. Alleys are 15 mph."},"es":{"q":"En Oregon, ¿cuál es el límite de velocidad en un callejón?","o":["25 mph","20 mph","15 mph","5 mph"],"h1":"Es el más lento de los límites comunes de la ciudad.","h2":"En Oregon, el límite de velocidad en un callejón es 15 mph.","p":"Correcto. Los callejones son de 15 mph."},"zh":{"q":"在 Oregon，小巷（alley）的限速是多少？","o":["25 mph","20 mph","15 mph","5 mph"],"h1":"它是一般城市限速里最慢的。","h2":"在 Oregon，小巷的限速是 15 mph。","p":"对。小巷是 15 mph。"},"vi":{"q":"Ở Oregon, tốc độ giới hạn trong hẻm (alley) là bao nhiêu?","o":["25 mph","20 mph","15 mph","5 mph"],"h1":"Đó là mức chậm nhất trong các giới hạn thường gặp trong thành phố.","h2":"Ở Oregon, tốc độ giới hạn trong hẻm là 15 mph.","p":"Đúng. Trong hẻm là 15 mph."},"tl":{"q":"Sa Oregon, ano ang speed limit sa eskinita (alley)?","o":["25 mph","20 mph","15 mph","5 mph"],"h1":"Ito ang pinakamabagal sa mga karaniwang limit sa lungsod.","h2":"Sa Oregon, ang speed limit sa eskinita ay 15 mph.","p":"Tama. 15 mph sa mga eskinita."},"ar":{"q":"في Oregon، ما حد السرعة في الزقاق (alley)؟","o":["25 mph","20 mph","15 mph","5 mph"],"h1":"هو الأبطأ بين الحدود المعتادة في المدينة.","h2":"في Oregon حد السرعة في الزقاق هو 15 mph.","p":"صحيح. الأزقة 15 mph."},"ref":{"doc":"OR","page":19}},{"id":"or-017","scope":"OR","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Oregon, how much alcohol may a driver under 21 have in their body?","o":["Up to 0.08 percent","Up to 0.05 percent","Up to 0.02 percent","None at all"],"h1":"Oregon has zero tolerance for young drivers.","h2":"In Oregon, a driver under 21 may not drive with any amount of alcohol in their body.","p":"Right. Under 21, no alcohol at all."},"es":{"q":"En Oregon, ¿cuánto alcohol puede tener en el cuerpo un conductor menor de 21 años?","o":["Hasta 0.08 por ciento","Hasta 0.05 por ciento","Hasta 0.02 por ciento","Nada"],"h1":"Oregon tiene tolerancia cero para los conductores jóvenes.","h2":"En Oregon, un conductor menor de 21 años no puede manejar con ninguna cantidad de alcohol en el cuerpo.","p":"Correcto. Menores de 21, nada de alcohol."},"zh":{"q":"在 Oregon，未满 21 岁的司机体内可以有多少酒精？","o":["最多 0.08%","最多 0.05%","最多 0.02%","一点也不能有"],"h1":"Oregon 对年轻司机零容忍。","h2":"在 Oregon，未满 21 岁的司机体内有任何酒精都不能开车。","p":"对。未满 21 岁，一点酒精也不能有。"},"vi":{"q":"Ở Oregon, người lái xe dưới 21 tuổi được có bao nhiêu rượu trong cơ thể?","o":["Tối đa 0.08 phần trăm","Tối đa 0.05 phần trăm","Tối đa 0.02 phần trăm","Hoàn toàn không có"],"h1":"Oregon không khoan nhượng với người lái xe trẻ tuổi.","h2":"Ở Oregon, người lái xe dưới 21 tuổi không được lái xe khi có bất kỳ lượng rượu nào trong cơ thể.","p":"Đúng. Dưới 21 tuổi, hoàn toàn không có rượu."},"tl":{"q":"Sa Oregon, gaano karaming alak ang puwedeng nasa katawan ng driver na wala pang 21?","o":["Hanggang 0.08 porsiyento","Hanggang 0.05 porsiyento","Hanggang 0.02 porsiyento","Wala talaga"],"h1":"Zero tolerance ang Oregon para sa mga batang driver.","h2":"Sa Oregon, ang driver na wala pang 21 ay hindi puwedeng magmaneho na may kahit kaunting alak sa katawan.","p":"Tama. Kapag wala pang 21, walang alak talaga."},"ar":{"q":"في Oregon، كم من الكحول يجوز أن يكون في جسم السائق الذي عمره أقل من 21 سنة؟","o":["حتى 0.08 بالمئة","حتى 0.05 بالمئة","حتى 0.02 بالمئة","لا شيء أبدًا"],"h1":"Oregon لا تتسامح أبدًا مع السائقين الصغار.","h2":"في Oregon لا يجوز للسائق الذي عمره أقل من 21 سنة أن يقود وفي جسمه أي كمية من الكحول.","p":"صحيح. تحت 21 سنة، لا كحول أبدًا."},"ref":{"doc":"OR","page":83}},{"id":"or-018","scope":"OR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oregon, the knowledge test for a regular license has 35 questions. How many must you answer correctly to pass?","o":["21","25","28","32"],"h1":"You need about 80 percent right.","h2":"In Oregon you must answer 28 of the 35 questions correctly to pass the knowledge test.","p":"Right. You need 28 correct answers out of 35."},"es":{"q":"En Oregon, el examen de conocimientos para una licencia normal tiene 35 preguntas. ¿Cuántas debe contestar bien para aprobar?","o":["21","25","28","32"],"h1":"Necesita cerca del 80 por ciento correcto.","h2":"En Oregon usted debe contestar bien 28 de las 35 preguntas para aprobar el examen de conocimientos.","p":"Correcto. Necesita 28 respuestas correctas de 35."},"zh":{"q":"在 Oregon，普通驾照的笔试有 35 道题。你至少要答对几道才能通过？","o":["21","25","28","32"],"h1":"你大约需要答对 80%。","h2":"在 Oregon，笔试 35 道题中你必须答对 28 道才能通过。","p":"对。35 道题中需要答对 28 道。"},"vi":{"q":"Ở Oregon, bài thi kiến thức để lấy bằng lái thường có 35 câu hỏi. Bạn phải trả lời đúng bao nhiêu câu để đậu?","o":["21","25","28","32"],"h1":"Bạn cần đúng khoảng 80 phần trăm.","h2":"Ở Oregon, bạn phải trả lời đúng 28 trên 35 câu hỏi để đậu bài thi kiến thức.","p":"Đúng. Bạn cần 28 câu đúng trên 35 câu."},"tl":{"q":"Sa Oregon, may 35 tanong ang knowledge test para sa regular na lisensya. Ilan ang dapat mong masagot nang tama para pumasa?","o":["21","25","28","32"],"h1":"Kailangan mong makakuha ng mga 80 porsiyentong tama.","h2":"Sa Oregon, dapat mong masagot nang tama ang 28 sa 35 tanong para pumasa sa knowledge test.","p":"Tama. Kailangan mo ng 28 tamang sagot sa 35."},"ar":{"q":"في Oregon، اختبار المعرفة للرخصة العادية فيه 35 سؤالًا. كم سؤالًا يجب أن تجيب عنه إجابة صحيحة لتنجح؟","o":["21","25","28","32"],"h1":"تحتاج إلى نحو 80 بالمئة من الإجابات الصحيحة.","h2":"في Oregon يجب أن تجيب إجابة صحيحة عن 28 سؤالًا من 35 لتنجح في اختبار المعرفة.","p":"صحيح. تحتاج إلى 28 إجابة صحيحة من 35."},"ref":{"doc":"OR","page":2}},{"id":"or-019","scope":"OR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oregon, you were in a crash that must be reported to the DMV. How soon must you file the report?","o":["Within 72 hours","Within 10 days","Within 30 days","Only if the police ask"],"h1":"It is counted in hours, not days.","h2":"In Oregon you must file a crash report with the DMV within 72 hours when the crash must be reported.","p":"Right. The DMV report is due within 72 hours."},"es":{"q":"En Oregon, usted tuvo un choque que debe reportarse al DMV. ¿En cuánto tiempo debe presentar el reporte?","o":["Dentro de 72 horas","Dentro de 10 días","Dentro de 30 días","Solo si la policía lo pide"],"h1":"Se cuenta en horas, no en días.","h2":"En Oregon usted debe presentar el reporte de choque al DMV dentro de 72 horas cuando el choque debe reportarse.","p":"Correcto. El reporte al DMV se entrega dentro de 72 horas."},"zh":{"q":"在 Oregon，你发生了一起必须向 DMV 报告的车祸。你必须在多长时间内提交报告？","o":["72 小时内","10 天内","30 天内","只有警察要求时才报"],"h1":"它是按小时算的，不是按天。","h2":"在 Oregon，必须报告的车祸要在 72 小时内向 DMV 提交车祸报告。","p":"对。DMV 报告要在 72 小时内提交。"},"vi":{"q":"Ở Oregon, bạn bị tai nạn mà phải báo cho DMV. Bạn phải nộp báo cáo trong bao lâu?","o":["Trong vòng 72 giờ","Trong vòng 10 ngày","Trong vòng 30 ngày","Chỉ khi cảnh sát yêu cầu"],"h1":"Thời hạn được tính bằng giờ, không phải bằng ngày.","h2":"Ở Oregon, khi tai nạn phải được báo cáo, bạn phải nộp báo cáo tai nạn cho DMV trong vòng 72 giờ.","p":"Đúng. Báo cáo cho DMV phải nộp trong vòng 72 giờ."},"tl":{"q":"Sa Oregon, naaksidente ka at dapat itong i-report sa DMV. Gaano kabilis mo dapat i-file ang report?","o":["Sa loob ng 72 oras","Sa loob ng 10 araw","Sa loob ng 30 araw","Kung hihilingin lang ng pulis"],"h1":"Binibilang ito sa oras, hindi sa araw.","h2":"Sa Oregon, dapat kang mag-file ng crash report sa DMV sa loob ng 72 oras kapag kailangang i-report ang aksidente.","p":"Tama. Dapat maipasa ang report sa DMV sa loob ng 72 oras."},"ar":{"q":"في Oregon، وقع لك حادث يجب الإبلاغ عنه إلى DMV. خلال كم من الوقت يجب أن تقدّم التقرير؟","o":["خلال 72 ساعة","خلال 10 أيام","خلال 30 يومًا","فقط إذا طلبت الشرطة"],"h1":"المدة تُحسب بالساعات، لا بالأيام.","h2":"في Oregon يجب أن تقدّم تقرير الحادث إلى DMV خلال 72 ساعة عندما يجب الإبلاغ عن الحادث.","p":"صحيح. تقرير DMV مطلوب خلال 72 ساعة."},"ref":{"doc":"OR","page":94}},{"id":"or-020","scope":"OR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oregon, you must report a crash to the DMV if the damage to the car you were driving is more than what amount?","o":["$500","$1,000","$1,500","$2,500"],"h1":"It is the highest amount listed.","h2":"In Oregon you must report a crash to the DMV when the damage to the car you were driving is over $2,500.","p":"Right. Damage over $2,500 means you must file a report."},"es":{"q":"En Oregon, usted debe reportar un choque al DMV si el daño al carro que manejaba es mayor de ¿qué cantidad?","o":["$500","$1,000","$1,500","$2,500"],"h1":"Es la cantidad más alta de la lista.","h2":"En Oregon usted debe reportar un choque al DMV cuando el daño al carro que manejaba es mayor de $2,500.","p":"Correcto. Un daño de más de $2,500 significa que debe presentar un reporte."},"zh":{"q":"在 Oregon，如果你所驾驶的车损坏超过多少钱，就必须向 DMV 报告车祸？","o":["$500","$1,000","$1,500","$2,500"],"h1":"是选项中最高的金额。","h2":"在 Oregon，如果你所驾驶的车损坏超过 $2,500，你必须向 DMV 报告车祸。","p":"对。损坏超过 $2,500 就必须提交报告。"},"vi":{"q":"Ở Oregon, bạn phải báo tai nạn cho DMV nếu thiệt hại của chiếc xe bạn đang lái vượt quá số tiền nào?","o":["$500","$1,000","$1,500","$2,500"],"h1":"Đó là số tiền cao nhất trong các lựa chọn.","h2":"Ở Oregon, bạn phải báo tai nạn cho DMV khi thiệt hại của chiếc xe bạn đang lái vượt quá $2,500.","p":"Đúng. Thiệt hại trên $2,500 thì bạn phải nộp báo cáo."},"tl":{"q":"Sa Oregon, dapat mong i-report sa DMV ang aksidente kung ang sira sa sasakyang minamaneho mo ay higit sa anong halaga?","o":["$500","$1,000","$1,500","$2,500"],"h1":"Ito ang pinakamataas na halaga sa listahan.","h2":"Sa Oregon, dapat mong i-report sa DMV ang aksidente kapag ang sira sa sasakyang minamaneho mo ay higit sa $2,500.","p":"Tama. Kapag higit sa $2,500 ang sira, dapat kang mag-file ng report."},"ar":{"q":"في Oregon، يجب أن تبلّغ DMV عن الحادث إذا كان ضرر السيارة التي كنت تقودها أكثر من أي مبلغ؟","o":["$500","$1,000","$1,500","$2,500"],"h1":"هو أعلى مبلغ في القائمة.","h2":"في Oregon يجب أن تبلّغ DMV عن الحادث عندما يكون ضرر السيارة التي كنت تقودها أكثر من $2,500.","p":"صحيح. الضرر فوق $2,500 يعني أنه يجب أن تقدّم تقريرًا."},"ref":{"doc":"OR","page":94}},{"id":"or-021","scope":"OR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oregon, does a police report about your crash take the place of your own report to the DMV?","o":["Yes, the police send it for you","No, you must still file your own DMV report","Yes, if no one was hurt","Only if the other driver agrees"],"h1":"The duty to report is yours.","h2":"In Oregon a police report does not replace your own crash report, so you must still file one with the DMV.","p":"Right. You still file your own report with the DMV."},"es":{"q":"En Oregon, ¿un reporte de la policía sobre su choque reemplaza su propio reporte al DMV?","o":["Sí, la policía lo envía por usted","No, usted debe presentar su propio reporte al DMV","Sí, si nadie salió herido","Solo si el otro conductor está de acuerdo"],"h1":"La obligación de reportar es suya.","h2":"En Oregon un reporte de la policía no reemplaza su propio reporte de choque, así que usted debe presentar uno al DMV.","p":"Correcto. Usted presenta su propio reporte al DMV de todos modos."},"zh":{"q":"在 Oregon，警察写的车祸报告可以代替你自己向 DMV 提交的报告吗？","o":["可以，警察会替你寄","不可以，你仍然必须自己向 DMV 提交报告","可以，如果没有人受伤","只有对方司机同意时才可以"],"h1":"报告的责任在你自己。","h2":"在 Oregon，警察的报告不能代替你自己的车祸报告，所以你仍然必须向 DMV 提交一份。","p":"对。你仍然要自己向 DMV 提交报告。"},"vi":{"q":"Ở Oregon, biên bản của cảnh sát về vụ tai nạn có thay thế được báo cáo của chính bạn gửi cho DMV không?","o":["Có, cảnh sát gửi giúp bạn","Không, bạn vẫn phải tự nộp báo cáo cho DMV","Có, nếu không ai bị thương","Chỉ khi tài xế kia đồng ý"],"h1":"Trách nhiệm báo cáo là của bạn.","h2":"Ở Oregon, biên bản của cảnh sát không thay thế báo cáo tai nạn của bạn, nên bạn vẫn phải tự nộp một báo cáo cho DMV.","p":"Đúng. Bạn vẫn phải tự nộp báo cáo cho DMV."},"tl":{"q":"Sa Oregon, napapalitan ba ng police report tungkol sa aksidente mo ang sarili mong report sa DMV?","o":["Oo, ang pulis ang magpapadala nito para sa iyo","Hindi, dapat ka pa ring mag-file ng sarili mong report sa DMV","Oo, kung walang nasaktan","Kung papayag lang ang kabilang driver"],"h1":"Ikaw ang may tungkuling mag-report.","h2":"Sa Oregon, hindi napapalitan ng police report ang sarili mong crash report, kaya dapat ka pa ring mag-file nito sa DMV.","p":"Tama. Magfa-file ka pa rin ng sarili mong report sa DMV."},"ar":{"q":"في Oregon، هل يحلّ تقرير الشرطة عن حادثك محلّ تقريرك أنت إلى DMV؟","o":["نعم، الشرطة ترسله عنك","لا، يجب أن تقدّم تقريرك أنت إلى DMV","نعم، إذا لم يُصب أحد","فقط إذا وافق السائق الآخر"],"h1":"واجب الإبلاغ عليك أنت.","h2":"في Oregon تقرير الشرطة لا يحلّ محلّ تقرير الحادث الخاص بك، لذلك يجب أن تقدّم تقريرك إلى DMV.","p":"صحيح. ما زلت تقدّم تقريرك أنت إلى DMV."},"ref":{"doc":"OR","page":94}},{"id":"or-022","scope":"OR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oregon, what is the minimum bodily injury liability coverage a car owner must carry for one person?","o":["$25,000","$10,000","$15,000","$50,000"],"h1":"It is half of the minimum for two or more people.","h2":"In Oregon, a car owner must carry at least $25,000 of bodily injury liability coverage for one person.","p":"Right. The bodily injury liability minimum is $25,000 per person."},"es":{"q":"En Oregon, ¿cuál es la cobertura mínima de responsabilidad por lesiones corporales que debe tener el dueño de un carro por una persona?","o":["$25,000","$10,000","$15,000","$50,000"],"h1":"Es la mitad del mínimo para dos o más personas.","h2":"En Oregon, el dueño de un carro debe tener por lo menos $25,000 de cobertura de responsabilidad por lesiones corporales por persona.","p":"Correcto. El mínimo de responsabilidad por lesiones corporales es $25,000 por persona."},"zh":{"q":"在 Oregon，车主为一个人必须买的最低人身伤害责任保险（bodily injury liability）是多少？","o":["$25,000","$10,000","$15,000","$50,000"],"h1":"它是两人或以上最低额度的一半。","h2":"在 Oregon，车主必须为一个人买至少 $25,000 的人身伤害责任保险。","p":"对。人身伤害责任保险的最低额度是每人 $25,000。"},"vi":{"q":"Ở Oregon, chủ xe phải có mức bảo hiểm trách nhiệm thương tích cơ thể (bodily injury liability) tối thiểu là bao nhiêu cho một người?","o":["$25,000","$10,000","$15,000","$50,000"],"h1":"Đó là một nửa mức tối thiểu cho hai người trở lên.","h2":"Ở Oregon, chủ xe phải có ít nhất $25,000 bảo hiểm trách nhiệm thương tích cơ thể cho một người.","p":"Đúng. Mức tối thiểu cho trách nhiệm thương tích cơ thể là $25,000 mỗi người."},"tl":{"q":"Sa Oregon, ano ang pinakamababang bodily injury liability coverage na dapat mayroon ang may-ari ng kotse para sa isang tao?","o":["$25,000","$10,000","$15,000","$50,000"],"h1":"Kalahati ito ng pinakamababa para sa dalawa o higit pang tao.","h2":"Sa Oregon, dapat may hindi bababa sa $25,000 na bodily injury liability coverage ang may-ari ng kotse para sa isang tao.","p":"Tama. Ang pinakamababang bodily injury liability ay $25,000 bawat tao."},"ar":{"q":"في Oregon، ما الحد الأدنى لتأمين المسؤولية عن الإصابات الجسدية (bodily injury liability) الذي يجب أن يملكه صاحب السيارة لشخص واحد؟","o":["$25,000","$10,000","$15,000","$50,000"],"h1":"هو نصف الحد الأدنى لشخصين أو أكثر.","h2":"في Oregon، يجب أن يملك صاحب السيارة على الأقل $25,000 من تأمين المسؤولية عن الإصابات الجسدية لشخص واحد.","p":"صحيح. الحد الأدنى لتأمين المسؤولية عن الإصابات الجسدية هو $25,000 لكل شخص."},"ref":{"doc":"OR","page":93}},{"id":"or-023","scope":"OR","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Oregon, until when must a child ride in an approved child safety seat?","o":["Until age 4 or 40 pounds","Until age 6 or 4 feet tall","Until age 8 or 4 feet 9 inches tall, when the adult belt fits","Until age 12, no matter the height"],"h1":"It depends on both the age and the height of the child.","h2":"In Oregon a child must ride in an approved child safety seat until age 8 or 4 feet 9 inches tall, when the adult lap and shoulder belt fits correctly.","p":"Right. A child seat is needed until age 8 or 4 feet 9 inches, when the adult belt fits."},"es":{"q":"En Oregon, ¿hasta cuándo debe viajar un niño en un asiento de seguridad aprobado?","o":["Hasta los 4 años o 40 libras","Hasta los 6 años o 4 pies de altura","Hasta los 8 años o 4 pies 9 pulgadas, cuando el cinturón de adulto le queda bien","Hasta los 12 años, sin importar la altura"],"h1":"Depende de la edad y también de la estatura del niño.","h2":"En Oregon un niño debe viajar en un asiento de seguridad aprobado hasta los 8 años o hasta medir 4 pies 9 pulgadas, cuando el cinturón de regazo y hombro de adulto le queda bien.","p":"Correcto. Se necesita el asiento hasta los 8 años o 4 pies 9 pulgadas, cuando el cinturón de adulto le queda bien."},"zh":{"q":"在 Oregon，儿童必须坐在合格的儿童安全座椅里，直到什么时候？","o":["到 4 岁或 40 磅","到 6 岁或身高 4 英尺","到 8 岁或身高 4 英尺 9 英寸，成人安全带合适时","到 12 岁，不论身高"],"h1":"这要看孩子的年龄和身高。","h2":"在 Oregon，儿童必须坐在合格的儿童安全座椅里，直到 8 岁或身高 4 英尺 9 英寸，而且成人腰带和肩带能正确系好。","p":"对。儿童座椅要用到 8 岁或 4 英尺 9 英寸，成人安全带合适时为止。"},"vi":{"q":"Ở Oregon, trẻ em phải ngồi ghế an toàn trẻ em được chấp thuận cho đến khi nào?","o":["Đến 4 tuổi hoặc 40 pound","Đến 6 tuổi hoặc cao 4 feet","Đến 8 tuổi hoặc cao 4 feet 9 inch, khi dây an toàn người lớn vừa","Đến 12 tuổi, bất kể chiều cao"],"h1":"Điều này tùy vào cả tuổi và chiều cao của trẻ.","h2":"Ở Oregon, trẻ em phải ngồi ghế an toàn trẻ em được chấp thuận cho đến 8 tuổi hoặc cao 4 feet 9 inch, khi dây an toàn vai và hông của người lớn vừa đúng.","p":"Đúng. Cần ghế trẻ em đến 8 tuổi hoặc 4 feet 9 inch, khi dây an toàn người lớn vừa."},"tl":{"q":"Sa Oregon, hanggang kailan dapat nakasakay ang bata sa aprubadong child safety seat?","o":["Hanggang 4 na taon o 40 pounds","Hanggang 6 na taon o 4 feet ang taas","Hanggang 8 taon o 4 feet 9 inches ang taas, kapag kasya na ang seat belt ng adult","Hanggang 12 taon, anuman ang taas"],"h1":"Nakadepende ito sa edad at taas ng bata.","h2":"Sa Oregon, dapat nakasakay ang bata sa aprubadong child safety seat hanggang 8 taon o 4 feet 9 inches ang taas, kapag tama na ang kasya ng lap at shoulder belt ng adult.","p":"Tama. Kailangan ang child seat hanggang 8 taon o 4 feet 9 inches, kapag kasya na ang seat belt ng adult."},"ar":{"q":"في Oregon، حتى متى يجب أن يجلس الطفل في مقعد أمان للأطفال معتمد؟","o":["حتى عمر 4 سنوات أو 40 رطلًا","حتى عمر 6 سنوات أو طول 4 أقدام","حتى عمر 8 سنوات أو طول 4 أقدام و9 بوصات، عندما يناسبه حزام البالغين","حتى عمر 12 سنة، مهما كان الطول"],"h1":"يعتمد ذلك على عمر الطفل وطوله معًا.","h2":"في Oregon يجب أن يجلس الطفل في مقعد أمان للأطفال معتمد حتى عمر 8 سنوات أو طول 4 أقدام و9 بوصات، عندما يناسبه حزام الحضن والكتف للبالغين بشكل صحيح.","p":"صحيح. مقعد الطفل مطلوب حتى عمر 8 سنوات أو 4 أقدام و9 بوصات، عندما يناسبه حزام البالغين."},"ref":{"doc":"OR","page":74}},{"id":"or-024","scope":"OR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Oregon, during which months are studded tires generally allowed?","o":["October 1 through April 30","November 1 through March 31","December 1 through February 28","All year in the mountains"],"h1":"It starts in late fall and ends as spring begins.","h2":"In Oregon studded tires are generally allowed only from November 1 through March 31.","p":"Right. Studded tires are generally allowed from November 1 through March 31."},"es":{"q":"En Oregon, ¿en qué meses se permiten en general las llantas con clavos (studded tires)?","o":["Del 1 de octubre al 30 de abril","Del 1 de noviembre al 31 de marzo","Del 1 de diciembre al 28 de febrero","Todo el año en las montañas"],"h1":"Empieza a fines del otoño y termina al comenzar la primavera.","h2":"En Oregon las llantas con clavos se permiten en general solo del 1 de noviembre al 31 de marzo.","p":"Correcto. Las llantas con clavos se permiten en general del 1 de noviembre al 31 de marzo."},"zh":{"q":"在 Oregon，一般在哪几个月可以使用钉胎（studded tires）？","o":["10 月 1 日到 4 月 30 日","11 月 1 日到 3 月 31 日","12 月 1 日到 2 月 28 日","在山区全年都可以"],"h1":"它从深秋开始，到春天开始时结束。","h2":"在 Oregon，钉胎一般只能在 11 月 1 日到 3 月 31 日之间使用。","p":"对。钉胎一般在 11 月 1 日到 3 月 31 日可以使用。"},"vi":{"q":"Ở Oregon, lốp xe có đinh (studded tires) thường được phép dùng trong những tháng nào?","o":["Từ 1 tháng 10 đến 30 tháng 4","Từ 1 tháng 11 đến 31 tháng 3","Từ 1 tháng 12 đến 28 tháng 2","Cả năm ở vùng núi"],"h1":"Thời gian bắt đầu vào cuối mùa thu và kết thúc khi mùa xuân bắt đầu.","h2":"Ở Oregon, lốp xe có đinh thường chỉ được phép dùng từ 1 tháng 11 đến 31 tháng 3.","p":"Đúng. Lốp xe có đinh thường được phép dùng từ 1 tháng 11 đến 31 tháng 3."},"tl":{"q":"Sa Oregon, sa anong mga buwan karaniwang pinapayagan ang studded tires?","o":["Oktubre 1 hanggang Abril 30","Nobyembre 1 hanggang Marso 31","Disyembre 1 hanggang Pebrero 28","Buong taon sa kabundukan"],"h1":"Nagsisimula ito sa huling bahagi ng taglagas at natatapos pagsimula ng tagsibol.","h2":"Sa Oregon, karaniwang pinapayagan lang ang studded tires mula Nobyembre 1 hanggang Marso 31.","p":"Tama. Karaniwang pinapayagan ang studded tires mula Nobyembre 1 hanggang Marso 31."},"ar":{"q":"في Oregon، في أي أشهر يُسمح عادةً بالإطارات ذات المسامير (studded tires)؟","o":["من 1 أكتوبر حتى 30 أبريل","من 1 نوفمبر حتى 31 مارس","من 1 ديسمبر حتى 28 فبراير","طوال السنة في الجبال"],"h1":"تبدأ في أواخر الخريف وتنتهي مع بداية الربيع.","h2":"في Oregon يُسمح عادةً بالإطارات ذات المسامير فقط من 1 نوفمبر حتى 31 مارس.","p":"صحيح. يُسمح عادةً بالإطارات ذات المسامير من 1 نوفمبر حتى 31 مارس."},"ref":{"doc":"OR","page":79}},{"id":"or-025","scope":"OR","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Oregon, you are turning at an intersection with a traffic light. A person is crossing the street you are turning into. When may you start your turn?","o":["As soon as the person reaches the center line","When the person is 2 feet from your car","When your light turns green, no matter where the person is","When the person is at least 6 feet from the lane you are turning into"],"h1":"The person needs a safe space away from your lane.","h2":"In Oregon, at an intersection with a traffic light, you may start your turn only when the person is at least 6 feet from the lane you are turning into.","p":"Right. Wait until the person is 6 feet or more from your lane."},"es":{"q":"En Oregon, usted va a dar vuelta en una intersección con semáforo. Una persona está cruzando la calle a la que usted va a entrar. ¿Cuándo puede empezar la vuelta?","o":["En cuanto la persona llegue a la línea central","Cuando la persona esté a 2 pies de su carro","Cuando su luz cambie a verde, sin importar dónde esté la persona","Cuando la persona esté por lo menos a 6 pies del carril al que usted va a entrar"],"h1":"La persona necesita un espacio seguro lejos de su carril.","h2":"En Oregon, en una intersección con semáforo, usted puede empezar la vuelta solo cuando la persona está por lo menos a 6 pies del carril al que va a entrar.","p":"Correcto. Espere hasta que la persona esté a 6 pies o más de su carril."},"zh":{"q":"在 Oregon，你在有红绿灯的路口转弯。有一个人正在过你要转进去的那条街。你什么时候可以开始转弯？","o":["那个人一走到中线就可以","那个人离你的车 2 英尺时","你的灯变绿时，不管那个人在哪里","那个人离你要转进去的车道至少 6 英尺时"],"h1":"那个人需要离你的车道有一段安全距离。","h2":"在 Oregon，在有红绿灯的路口，只有当那个人离你要转进去的车道至少 6 英尺时，你才可以开始转弯。","p":"对。要等那个人离你的车道 6 英尺或更远。"},"vi":{"q":"Ở Oregon, bạn đang rẽ tại giao lộ có đèn giao thông. Có một người đang băng qua con đường bạn sắp rẽ vào. Khi nào bạn có thể bắt đầu rẽ?","o":["Ngay khi người đó đến vạch giữa đường","Khi người đó cách xe bạn 2 feet","Khi đèn của bạn chuyển xanh, bất kể người đó ở đâu","Khi người đó cách làn bạn sắp rẽ vào ít nhất 6 feet"],"h1":"Người đó cần một khoảng an toàn cách xa làn của bạn.","h2":"Ở Oregon, tại giao lộ có đèn giao thông, bạn chỉ được bắt đầu rẽ khi người đó cách làn bạn sắp rẽ vào ít nhất 6 feet.","p":"Đúng. Hãy chờ đến khi người đó cách làn của bạn 6 feet trở lên."},"tl":{"q":"Sa Oregon, liliko ka sa intersection na may traffic light. May taong tumatawid sa kalyeng liliko-an mo. Kailan ka puwedeng magsimulang lumiko?","o":["Kapag naabot na ng tao ang center line","Kapag 2 feet na lang ang layo ng tao sa sasakyan mo","Kapag naging green ang ilaw mo, kahit nasaan ang tao","Kapag hindi bababa sa 6 feet ang layo ng tao sa lane na liliko-an mo"],"h1":"Kailangan ng tao ng ligtas na layo mula sa lane mo.","h2":"Sa Oregon, sa intersection na may traffic light, puwede ka lang magsimulang lumiko kapag hindi bababa sa 6 feet ang layo ng tao sa lane na liliko-an mo.","p":"Tama. Maghintay hanggang 6 feet o higit pa ang layo ng tao sa lane mo."},"ar":{"q":"في Oregon، أنت تنعطف عند تقاطع فيه إشارة مرور. يوجد شخص يعبر الشارع الذي تنعطف إليه. متى يمكنك أن تبدأ الانعطاف؟","o":["بمجرد أن يصل الشخص إلى خط المنتصف","عندما يكون الشخص على بعد 2 قدم من سيارتك","عندما تصبح إشارتك خضراء، أينما كان الشخص","عندما يكون الشخص على بعد 6 أقدام على الأقل من المسار الذي تنعطف إليه"],"h1":"يحتاج الشخص إلى مسافة آمنة بعيدًا عن مسارك.","h2":"في Oregon، عند تقاطع فيه إشارة مرور، يمكنك أن تبدأ الانعطاف فقط عندما يكون الشخص على بعد 6 أقدام على الأقل من المسار الذي تنعطف إليه.","p":"صحيح. انتظر حتى يكون الشخص على بعد 6 أقدام أو أكثر من مسارك."},"ref":{"doc":"OR","page":47}},{"id":"or-026","scope":"OR","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Oregon, how close to a fire hydrant may you park?","o":["No closer than 10 feet","No closer than 5 feet","No closer than 20 feet","No closer than 30 feet"],"h1":"It is a little less than the length of one car.","h2":"In Oregon you may not park within 10 feet of a fire hydrant.","p":"Right. Stay at least 10 feet away from a fire hydrant."},"es":{"q":"En Oregon, ¿qué tan cerca de un hidrante de incendios puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 5 pies","No más cerca de 20 pies","No más cerca de 30 pies"],"h1":"Es un poco menos que el largo de un carro.","h2":"En Oregon usted no puede estacionarse a menos de 10 pies de un hidrante de incendios.","p":"Correcto. Manténgase por lo menos a 10 pies de un hidrante."},"zh":{"q":"在 Oregon，你停车时离消防栓最近可以多近？","o":["不能近于 10 英尺","不能近于 5 英尺","不能近于 20 英尺","不能近于 30 英尺"],"h1":"它比一辆车的长度短一点。","h2":"在 Oregon，你不能在消防栓 10 英尺以内停车。","p":"对。停车时要离消防栓至少 10 英尺。"},"vi":{"q":"Ở Oregon, bạn được đậu xe gần trụ nước cứu hỏa đến mức nào?","o":["Không gần hơn 10 feet","Không gần hơn 5 feet","Không gần hơn 20 feet","Không gần hơn 30 feet"],"h1":"Khoảng cách này ngắn hơn chiều dài một chiếc xe một chút.","h2":"Ở Oregon, bạn không được đậu xe trong vòng 10 feet tính từ trụ nước cứu hỏa.","p":"Đúng. Hãy đậu xe cách trụ nước cứu hỏa ít nhất 10 feet."},"tl":{"q":"Sa Oregon, gaano kalapit ka puwedeng pumarada sa fire hydrant?","o":["Hindi lalapit sa 10 feet","Hindi lalapit sa 5 feet","Hindi lalapit sa 20 feet","Hindi lalapit sa 30 feet"],"h1":"Medyo mas maikli ito sa haba ng isang kotse.","h2":"Sa Oregon, hindi ka puwedeng pumarada sa loob ng 10 feet mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 10 feet mula sa fire hydrant."},"ar":{"q":"في Oregon، إلى أي مدى يمكنك أن تقترب من صنبور إطفاء الحريق عند الوقوف؟","o":["ليس أقرب من 10 أقدام","ليس أقرب من 5 أقدام","ليس أقرب من 20 قدمًا","ليس أقرب من 30 قدمًا"],"h1":"هي أقل قليلًا من طول سيارة واحدة.","h2":"في Oregon لا يجوز لك الوقوف على بعد أقل من 10 أقدام من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بعد 10 أقدام على الأقل من صنبور إطفاء الحريق."},"ref":{"doc":"OR","page":70}},{"id":"or-027","scope":"OR","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Oregon, how close to a crosswalk at an intersection may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 20 feet","No closer than 50 feet"],"h1":"It is about the length of one large car.","h2":"In Oregon you may not park within 20 feet of a crosswalk at an intersection, marked or not.","p":"Right. Stay at least 20 feet from a crosswalk at an intersection."},"es":{"q":"En Oregon, ¿qué tan cerca de un cruce peatonal en una intersección puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 20 pies","No más cerca de 50 pies"],"h1":"Es más o menos el largo de un carro grande.","h2":"En Oregon usted no puede estacionarse a menos de 20 pies de un cruce peatonal en una intersección, esté marcado o no.","p":"Correcto. Manténgase por lo menos a 20 pies de un cruce peatonal en una intersección."},"zh":{"q":"在 Oregon，在路口的人行横道附近，你停车时最近可以多近？","o":["不能近于 5 英尺","不能近于 10 英尺","不能近于 20 英尺","不能近于 50 英尺"],"h1":"它大约是一辆大车的长度。","h2":"在 Oregon，不论路口的人行横道有没有画线，你都不能在它 20 英尺以内停车。","p":"对。停车时要离路口的人行横道至少 20 英尺。"},"vi":{"q":"Ở Oregon, bạn được đậu xe gần lối qua đường dành cho người đi bộ ở giao lộ đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 20 feet","Không gần hơn 50 feet"],"h1":"Khoảng cách này bằng chiều dài một chiếc xe lớn.","h2":"Ở Oregon, bạn không được đậu xe trong vòng 20 feet tính từ lối qua đường ở giao lộ, dù lối đó có kẻ vạch hay không.","p":"Đúng. Hãy đậu xe cách lối qua đường ở giao lộ ít nhất 20 feet."},"tl":{"q":"Sa Oregon, gaano kalapit ka puwedeng pumarada sa tawiran (crosswalk) sa isang interseksyon?","o":["Hindi lalapit sa 5 feet","Hindi lalapit sa 10 feet","Hindi lalapit sa 20 feet","Hindi lalapit sa 50 feet"],"h1":"Halos kasinghaba ito ng isang malaking kotse.","h2":"Sa Oregon, hindi ka puwedeng pumarada sa loob ng 20 feet mula sa tawiran sa interseksyon, may guhit man ito o wala.","p":"Tama. Lumayo nang hindi bababa sa 20 feet mula sa tawiran sa interseksyon."},"ar":{"q":"في Oregon، إلى أي مدى يمكنك أن تقترب من ممر المشاة عند التقاطع عند الوقوف؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 10 أقدام","ليس أقرب من 20 قدمًا","ليس أقرب من 50 قدمًا"],"h1":"هي تقريبًا طول سيارة كبيرة واحدة.","h2":"في Oregon لا يجوز لك الوقوف على بعد أقل من 20 قدمًا من ممر المشاة عند التقاطع، سواء كان مرسومًا أم لا.","p":"صحيح. ابقَ على بعد 20 قدمًا على الأقل من ممر المشاة عند التقاطع."},"ref":{"doc":"OR","page":71}},{"id":"or-028","scope":"OR","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Oregon, you must stop at a railroad crossing that has no stop line. Where do you stop?","o":["At least 15 feet from the nearest rail","At least 5 feet from the nearest rail","Right next to the first rail","At least 100 feet from the tracks"],"h1":"Leave room so a train cannot hit the front of your car.","h2":"In Oregon, when a railroad crossing has no stop line, you must stop at least 15 feet from the nearest rail.","p":"Right. With no stop line, stop at least 15 feet from the nearest rail."},"es":{"q":"En Oregon, usted debe detenerse en un cruce de ferrocarril que no tiene línea de alto. ¿Dónde se detiene?","o":["Por lo menos a 15 pies del riel más cercano","Por lo menos a 5 pies del riel más cercano","Justo al lado del primer riel","Por lo menos a 100 pies de las vías"],"h1":"Deje espacio para que el tren no golpee el frente de su carro.","h2":"En Oregon, cuando un cruce de ferrocarril no tiene línea de alto, usted debe detenerse por lo menos a 15 pies del riel más cercano.","p":"Correcto. Sin línea de alto, deténgase por lo menos a 15 pies del riel más cercano."},"zh":{"q":"在 Oregon，你必须在一个没有停车线的铁路道口停车。你应该停在哪里？","o":["离最近的铁轨至少 15 英尺","离最近的铁轨至少 5 英尺","紧挨着第一条铁轨","离铁路至少 100 英尺"],"h1":"留出空间，让火车不会撞到你的车头。","h2":"在 Oregon，如果铁路道口没有停车线，你必须停在离最近的铁轨至少 15 英尺的地方。","p":"对。没有停车线时，要停在离最近的铁轨至少 15 英尺的地方。"},"vi":{"q":"Ở Oregon, bạn phải dừng lại ở một chỗ băng qua đường sắt không có vạch dừng. Bạn dừng ở đâu?","o":["Cách đường ray gần nhất ít nhất 15 feet","Cách đường ray gần nhất ít nhất 5 feet","Sát ngay đường ray đầu tiên","Cách đường sắt ít nhất 100 feet"],"h1":"Chừa khoảng trống để tàu hỏa không đụng vào đầu xe của bạn.","h2":"Ở Oregon, khi chỗ băng qua đường sắt không có vạch dừng, bạn phải dừng cách đường ray gần nhất ít nhất 15 feet.","p":"Đúng. Khi không có vạch dừng, hãy dừng cách đường ray gần nhất ít nhất 15 feet."},"tl":{"q":"Sa Oregon, kailangan mong huminto sa tawiran ng tren na walang stop line. Saan ka hihinto?","o":["Hindi bababa sa 15 feet mula sa pinakamalapit na riles","Hindi bababa sa 5 feet mula sa pinakamalapit na riles","Katabi mismo ng unang riles","Hindi bababa sa 100 feet mula sa riles"],"h1":"Mag-iwan ng puwang para hindi tamaan ng tren ang harap ng kotse mo.","h2":"Sa Oregon, kapag walang stop line ang tawiran ng tren, kailangan mong huminto nang hindi bababa sa 15 feet mula sa pinakamalapit na riles.","p":"Tama. Kapag walang stop line, huminto nang hindi bababa sa 15 feet mula sa pinakamalapit na riles."},"ar":{"q":"في Oregon، يجب أن تتوقف عند معبر سكة حديد ليس فيه خط توقف. أين تتوقف؟","o":["على بعد 15 قدمًا على الأقل من أقرب قضيب","على بعد 5 أقدام على الأقل من أقرب قضيب","بجانب القضيب الأول مباشرة","على بعد 100 قدم على الأقل من السكة"],"h1":"اترك مسافة حتى لا يصطدم القطار بمقدمة سيارتك.","h2":"في Oregon، عندما لا يكون في معبر السكة الحديد خط توقف، يجب أن تتوقف على بعد 15 قدمًا على الأقل من أقرب قضيب.","p":"صحيح. إذا لم يكن هناك خط توقف، فتوقف على بعد 15 قدمًا على الأقل من أقرب قضيب."},"ref":{"doc":"OR","page":64}},{"id":"or-029","scope":"OR","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Oregon, you pulled over for a fire truck with its siren on. After it passes, how far behind it must you stay?","o":["At least 50 feet","At least 100 feet","At least 200 feet","At least 500 feet"],"h1":"Give it plenty of room, because it may stop or turn suddenly.","h2":"In Oregon, after an emergency vehicle passes, you must stay at least 500 feet behind it.","p":"Right. Stay at least 500 feet behind an emergency vehicle."},"es":{"q":"En Oregon, usted se orilló para dejar pasar a un camión de bomberos con la sirena prendida. Después de que pasa, ¿a qué distancia detrás de él debe quedarse?","o":["Por lo menos a 50 pies","Por lo menos a 100 pies","Por lo menos a 200 pies","Por lo menos a 500 pies"],"h1":"Dele mucho espacio, porque puede detenerse o dar vuelta de repente.","h2":"En Oregon, después de que pasa un vehículo de emergencia, usted debe quedarse por lo menos a 500 pies detrás de él.","p":"Correcto. Quédese por lo menos a 500 pies detrás de un vehículo de emergencia."},"zh":{"q":"在 Oregon，你为一辆开着警笛的消防车靠边停车。它开过去以后，你必须在它后面保持多远？","o":["至少 50 英尺","至少 100 英尺","至少 200 英尺","至少 500 英尺"],"h1":"给它留足空间，因为它可能会突然停车或转弯。","h2":"在 Oregon，紧急车辆开过去以后，你必须在它后面保持至少 500 英尺。","p":"对。要在紧急车辆后面保持至少 500 英尺。"},"vi":{"q":"Ở Oregon, bạn đã tấp vào lề để nhường một xe cứu hỏa đang hú còi. Sau khi xe đó chạy qua, bạn phải giữ khoảng cách phía sau nó bao xa?","o":["Ít nhất 50 feet","Ít nhất 100 feet","Ít nhất 200 feet","Ít nhất 500 feet"],"h1":"Hãy chừa nhiều khoảng trống, vì xe đó có thể dừng hoặc rẽ bất ngờ.","h2":"Ở Oregon, sau khi xe khẩn cấp chạy qua, bạn phải giữ khoảng cách ít nhất 500 feet phía sau nó.","p":"Đúng. Hãy giữ khoảng cách ít nhất 500 feet phía sau xe khẩn cấp."},"tl":{"q":"Sa Oregon, tumabi ka para sa isang fire truck na nakabukas ang sirena. Pagkalampas nito, gaano kalayo ka dapat manatili sa likod nito?","o":["Hindi bababa sa 50 feet","Hindi bababa sa 100 feet","Hindi bababa sa 200 feet","Hindi bababa sa 500 feet"],"h1":"Bigyan ito ng malaking puwang, dahil baka bigla itong huminto o lumiko.","h2":"Sa Oregon, pagkalampas ng emergency vehicle, kailangan mong manatili nang hindi bababa sa 500 feet sa likod nito.","p":"Tama. Manatili nang hindi bababa sa 500 feet sa likod ng emergency vehicle."},"ar":{"q":"في Oregon، توقفت على جانب الطريق لسيارة إطفاء تعمل صفارتها. بعد أن تمر، على أي بعد يجب أن تبقى خلفها؟","o":["50 قدمًا على الأقل","100 قدم على الأقل","200 قدم على الأقل","500 قدم على الأقل"],"h1":"اترك لها مسافة كبيرة، لأنها قد تتوقف أو تنعطف فجأة.","h2":"في Oregon، بعد أن تمر سيارة الطوارئ، يجب أن تبقى خلفها على بعد 500 قدم على الأقل.","p":"صحيح. ابقَ خلف سيارة الطوارئ على بعد 500 قدم على الأقل."},"ref":{"doc":"OR","page":58}},{"id":"or-030","scope":"OR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Oregon, you are using your high beams. A car is coming toward you. When must you dim your lights?","o":["When it is within 100 feet","When it is within 500 feet","When it is within 1,000 feet","Only if the other driver flashes their lights"],"h1":"Switch early, so the other driver is not blinded.","h2":"In Oregon you must dim your high beams when an oncoming vehicle is within 500 feet.","p":"Right. Dim your high beams when an oncoming car is within 500 feet."},"es":{"q":"En Oregon, usted lleva las luces altas prendidas. Un carro viene hacia usted. ¿Cuándo debe bajar las luces?","o":["Cuando esté a menos de 100 pies","Cuando esté a menos de 500 pies","Cuando esté a menos de 1,000 pies","Solo si el otro conductor le hace cambio de luces"],"h1":"Cambie temprano, para no deslumbrar al otro conductor.","h2":"En Oregon usted debe bajar las luces altas cuando un vehículo que viene de frente está a menos de 500 pies.","p":"Correcto. Baje las luces altas cuando un carro de frente esté a menos de 500 pies."},"zh":{"q":"在 Oregon，你正在开远光灯。前面有一辆车朝你开过来。你必须在什么时候把灯调暗？","o":["当它在 100 英尺以内时","当它在 500 英尺以内时","当它在 1,000 英尺以内时","只有当对方司机闪灯时"],"h1":"要早点换灯，这样对方司机不会被晃得看不见。","h2":"在 Oregon，当对面来车在 500 英尺以内时，你必须把远光灯调暗。","p":"对。对面来车在 500 英尺以内时，要把远光灯调暗。"},"vi":{"q":"Ở Oregon, bạn đang bật đèn pha (đèn chiếu xa). Có một xe đang chạy ngược chiều về phía bạn. Khi nào bạn phải giảm đèn?","o":["Khi xe đó cách bạn trong vòng 100 feet","Khi xe đó cách bạn trong vòng 500 feet","Khi xe đó cách bạn trong vòng 1,000 feet","Chỉ khi tài xế kia nháy đèn"],"h1":"Hãy đổi đèn sớm để tài xế kia không bị chói mắt.","h2":"Ở Oregon, bạn phải giảm đèn pha khi xe chạy ngược chiều cách bạn trong vòng 500 feet.","p":"Đúng. Hãy giảm đèn pha khi xe ngược chiều cách bạn trong vòng 500 feet."},"tl":{"q":"Sa Oregon, gamit mo ang high beams. May kotseng papalapit sa iyo mula sa harap. Kailan mo kailangang i-dim ang ilaw mo?","o":["Kapag nasa loob na ito ng 100 feet","Kapag nasa loob na ito ng 500 feet","Kapag nasa loob na ito ng 1,000 feet","Kapag nag-flash lang ng ilaw ang ibang driver"],"h1":"Magpalit nang maaga para hindi masilaw ang ibang driver.","h2":"Sa Oregon, kailangan mong i-dim ang high beams mo kapag nasa loob ng 500 feet ang paparating na sasakyan.","p":"Tama. I-dim ang high beams kapag nasa loob ng 500 feet ang paparating na kotse."},"ar":{"q":"في Oregon، أنت تستخدم الأضواء العالية. هناك سيارة قادمة نحوك. متى يجب أن تخفض أضواءك؟","o":["عندما تصبح على بعد 100 قدم أو أقل","عندما تصبح على بعد 500 قدم أو أقل","عندما تصبح على بعد 1,000 قدم أو أقل","فقط إذا ومض السائق الآخر بأضوائه"],"h1":"بدّل الأضواء مبكرًا حتى لا يُبهَر السائق الآخر.","h2":"في Oregon يجب أن تخفض أضواءك العالية عندما تكون السيارة القادمة نحوك على بعد 500 قدم أو أقل.","p":"صحيح. اخفض أضواءك العالية عندما تكون السيارة القادمة على بعد 500 قدم أو أقل."},"ref":{"doc":"OR","page":76}},{"id":"or-031","scope":"OR","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Oregon, inside city limits, you may not make a U-turn where traffic from either direction cannot see your car from how far away?","o":["100 feet","250 feet","500 feet","1,000 feet"],"h1":"Outside city limits the distance is twice as far.","h2":"In Oregon, inside city limits, you may not make a U-turn where traffic from either direction cannot see your car within 500 feet.","p":"Right. In a city, other drivers must be able to see you from 500 feet."},"es":{"q":"En Oregon, dentro de los límites de una ciudad, no puede dar una vuelta en U donde el tráfico de cualquier dirección no puede ver su carro desde ¿qué distancia?","o":["100 pies","250 pies","500 pies","1,000 pies"],"h1":"Fuera de la ciudad la distancia es el doble.","h2":"En Oregon, dentro de los límites de una ciudad, usted no puede dar una vuelta en U donde el tráfico de cualquier dirección no puede ver su carro a 500 pies.","p":"Correcto. En la ciudad, los otros conductores deben poder verlo desde 500 pies."},"zh":{"q":"在 Oregon 的城市范围内，如果两个方向的车辆在多远的距离内看不到你的车，你就不能掉头（U-turn）？","o":["100 英尺","250 英尺","500 英尺","1,000 英尺"],"h1":"在城市范围外，这个距离是两倍远。","h2":"在 Oregon 的城市范围内，如果两个方向的车辆在 500 英尺内看不到你的车，你就不能掉头。","p":"对。在城市里，其他司机必须能在 500 英尺外看到你。"},"vi":{"q":"Ở Oregon, trong phạm vi thành phố, bạn không được quay đầu xe (U-turn) ở chỗ mà xe từ cả hai hướng không thể thấy xe bạn từ khoảng cách bao xa?","o":["100 feet","250 feet","500 feet","1,000 feet"],"h1":"Ngoài phạm vi thành phố, khoảng cách này xa gấp đôi.","h2":"Ở Oregon, trong phạm vi thành phố, bạn không được quay đầu xe ở chỗ mà xe từ cả hai hướng không thể thấy xe bạn trong vòng 500 feet.","p":"Đúng. Trong thành phố, các tài xế khác phải thấy được bạn từ 500 feet."},"tl":{"q":"Sa Oregon, sa loob ng city limits, hindi ka puwedeng mag-U-turn kung saan hindi makikita ng trapiko mula sa alinmang direksyon ang kotse mo mula sa gaano kalayo?","o":["100 feet","250 feet","500 feet","1,000 feet"],"h1":"Sa labas ng city limits, doble ang layo nito.","h2":"Sa Oregon, sa loob ng city limits, hindi ka puwedeng mag-U-turn kung saan hindi makikita ng trapiko mula sa alinmang direksyon ang kotse mo sa loob ng 500 feet.","p":"Tama. Sa lungsod, dapat kang makita ng ibang driver mula sa 500 feet."},"ar":{"q":"في Oregon، داخل حدود المدينة، لا يجوز لك الالتفاف للخلف (U-turn) في مكان لا تستطيع فيه السيارات من أي اتجاه أن ترى سيارتك من أي مسافة؟","o":["100 قدم","250 قدمًا","500 قدم","1,000 قدم"],"h1":"خارج حدود المدينة تكون المسافة ضعف ذلك.","h2":"في Oregon، داخل حدود المدينة، لا يجوز لك الالتفاف للخلف في مكان لا تستطيع فيه السيارات من أي اتجاه أن ترى سيارتك من مسافة 500 قدم.","p":"صحيح. في المدينة يجب أن يستطيع السائقون الآخرون رؤيتك من مسافة 500 قدم."},"ref":{"doc":"OR","page":41}},{"id":"pa-001","scope":"PA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Pennsylvania, what is the youngest age to apply for a learner's permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is later than in many other states.","h2":"In Pennsylvania you can apply for a learner's permit once you turn 16, with a parent or guardian's consent.","p":"Right. The Pennsylvania permit starts at 16."},"es":{"q":"En Pensilvania, ¿cuál es la edad mínima para solicitar el permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es más tarde que en muchos otros estados.","h2":"En Pensilvania usted puede solicitar el permiso de aprendiz al cumplir 16 años, con el consentimiento de su padre, madre o tutor.","p":"Correcto. El permiso en Pensilvania empieza a los 16."},"zh":{"q":"在 Pennsylvania，最小几岁可以申请学习驾照（learner's permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比很多其他州晚。","h2":"在 Pennsylvania，你满 16 岁并得到父母或监护人同意后，就可以申请学习驾照。","p":"对。Pennsylvania 的学习驾照从 16 岁开始。"},"vi":{"q":"Ở Pennsylvania, tuổi nhỏ nhất để nộp đơn xin giấy phép tập lái (learner's permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Tuổi này muộn hơn ở nhiều tiểu bang khác.","h2":"Ở Pennsylvania, bạn có thể nộp đơn xin giấy phép tập lái khi đủ 16 tuổi, có sự đồng ý của cha mẹ hoặc người giám hộ.","p":"Đúng. Giấy phép tập lái ở Pennsylvania bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Pennsylvania, ano ang pinakabatang edad para mag-apply ng learner's permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Mas huli ito kaysa sa maraming ibang estado.","h2":"Sa Pennsylvania, puwede kang mag-apply ng learner's permit pagdating mo ng 16, kung may pahintulot ng magulang o guardian.","p":"Tama. Sa Pennsylvania, nagsisimula ang permit sa 16."},"ar":{"q":"في Pennsylvania، ما أصغر سن يمكنك فيه التقدم لتصريح تعلّم القيادة (learner's permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هو أكبر من السن في كثير من الولايات الأخرى.","h2":"في Pennsylvania يمكنك التقدم لتصريح تعلّم القيادة عندما تبلغ 16 سنة، بموافقة أحد الوالدين أو الوصي.","p":"صحيح. تصريح التعلّم في Pennsylvania يبدأ من سن 16."},"ref":{"doc":"PA","page":1}},{"id":"pa-002","scope":"PA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Pennsylvania, how many questions are on the learner's permit knowledge test?","o":["10 questions","18 questions","25 questions","50 questions"],"h1":"It is fewer than 20.","h2":"The Pennsylvania knowledge test has 18 multiple-choice questions.","p":"Right. The test has 18 questions."},"es":{"q":"En Pensilvania, ¿cuántas preguntas tiene el examen de conocimientos para el permiso de aprendiz?","o":["10 preguntas","18 preguntas","25 preguntas","50 preguntas"],"h1":"Son menos de 20.","h2":"El examen de conocimientos de Pensilvania tiene 18 preguntas de opción múltiple.","p":"Correcto. El examen tiene 18 preguntas."},"zh":{"q":"在 Pennsylvania，学习驾照的笔试有多少道题？","o":["10 道题","18 道题","25 道题","50 道题"],"h1":"少于 20 道。","h2":"Pennsylvania 的笔试有 18 道选择题。","p":"对。笔试有 18 道题。"},"vi":{"q":"Ở Pennsylvania, bài thi kiến thức để lấy giấy phép tập lái có bao nhiêu câu hỏi?","o":["10 câu","18 câu","25 câu","50 câu"],"h1":"Ít hơn 20 câu.","h2":"Bài thi kiến thức ở Pennsylvania có 18 câu hỏi trắc nghiệm.","p":"Đúng. Bài thi có 18 câu."},"tl":{"q":"Sa Pennsylvania, ilang tanong ang nasa knowledge test para sa learner's permit?","o":["10 tanong","18 tanong","25 tanong","50 tanong"],"h1":"Mas kaunti ito sa 20.","h2":"Ang knowledge test ng Pennsylvania ay may 18 multiple-choice na tanong.","p":"Tama. May 18 tanong ang test."},"ar":{"q":"في Pennsylvania، كم سؤالًا في الاختبار النظري لتصريح تعلّم القيادة؟","o":["10 أسئلة","18 سؤالًا","25 سؤالًا","50 سؤالًا"],"h1":"العدد أقل من 20.","h2":"الاختبار النظري في Pennsylvania فيه 18 سؤالًا من نوع الاختيار من متعدد.","p":"صحيح. في الاختبار 18 سؤالًا."},"ref":{"doc":"PA","page":5}},{"id":"pa-003","scope":"PA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Pennsylvania, how many questions must you answer correctly to pass the knowledge test?","o":["9","12","18","15"],"h1":"You may miss only three.","h2":"To pass the Pennsylvania knowledge test you must answer 15 of the 18 questions correctly.","p":"Right. You need 15 correct answers."},"es":{"q":"En Pensilvania, ¿cuántas preguntas debe contestar bien para aprobar el examen de conocimientos?","o":["9","12","18","15"],"h1":"Solo puede fallar tres.","h2":"Para aprobar el examen de conocimientos de Pensilvania debe contestar bien 15 de las 18 preguntas.","p":"Correcto. Necesita 15 respuestas correctas."},"zh":{"q":"在 Pennsylvania，笔试要答对多少道题才能通过？","o":["9","12","18","15"],"h1":"你最多只能答错三道。","h2":"要通过 Pennsylvania 的笔试，18 道题中你必须答对 15 道。","p":"对。你需要答对 15 道。"},"vi":{"q":"Ở Pennsylvania, bạn phải trả lời đúng bao nhiêu câu để đậu bài thi kiến thức?","o":["9","12","18","15"],"h1":"Bạn chỉ được sai ba câu.","h2":"Để đậu bài thi kiến thức ở Pennsylvania, bạn phải trả lời đúng 15 trên 18 câu.","p":"Đúng. Bạn cần 15 câu đúng."},"tl":{"q":"Sa Pennsylvania, ilang tanong ang dapat mong masagot nang tama para pumasa sa knowledge test?","o":["9","12","18","15"],"h1":"Tatlo lang ang puwede mong mali.","h2":"Para pumasa sa knowledge test ng Pennsylvania, dapat mong masagot nang tama ang 15 sa 18 tanong.","p":"Tama. Kailangan mo ng 15 tamang sagot."},"ar":{"q":"في Pennsylvania، كم سؤالًا يجب أن تجيب عنه إجابة صحيحة لتنجح في الاختبار النظري؟","o":["9","12","18","15"],"h1":"يمكنك أن تخطئ في ثلاثة أسئلة فقط.","h2":"لتنجح في الاختبار النظري في Pennsylvania يجب أن تجيب إجابة صحيحة عن 15 سؤالًا من 18.","p":"صحيح. تحتاج إلى 15 إجابة صحيحة."},"ref":{"doc":"PA","page":5}},{"id":"pa-004","scope":"PA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Pennsylvania, if you are under 18, how long must you wait after getting your learner's permit before taking the road test?","o":["Six months","One month","Three months","Two years"],"h1":"It is half a year.","h2":"In Pennsylvania a driver under 18 may not take the road test until six months after receiving the learner's permit.","p":"Right. Wait six months."},"es":{"q":"En Pensilvania, si usted es menor de 18 años, ¿cuánto tiempo debe esperar después de obtener el permiso de aprendiz para hacer el examen de manejo?","o":["Seis meses","Un mes","Tres meses","Dos años"],"h1":"Es medio año.","h2":"En Pensilvania un conductor menor de 18 años no puede hacer el examen de manejo hasta seis meses después de recibir el permiso de aprendiz.","p":"Correcto. Debe esperar seis meses."},"zh":{"q":"在 Pennsylvania，如果你未满 18 岁，拿到学习驾照后要等多久才能考路考？","o":["六个月","一个月","三个月","两年"],"h1":"是半年。","h2":"在 Pennsylvania，未满 18 岁的司机拿到学习驾照六个月以后，才可以考路考。","p":"对。要等六个月。"},"vi":{"q":"Ở Pennsylvania, nếu bạn dưới 18 tuổi, sau khi có giấy phép tập lái bạn phải chờ bao lâu mới được thi lái xe trên đường?","o":["Sáu tháng","Một tháng","Ba tháng","Hai năm"],"h1":"Đó là nửa năm.","h2":"Ở Pennsylvania, người lái dưới 18 tuổi chỉ được thi lái xe trên đường sau sáu tháng kể từ khi nhận giấy phép tập lái.","p":"Đúng. Chờ sáu tháng."},"tl":{"q":"Sa Pennsylvania, kung wala ka pang 18, gaano katagal ka dapat maghintay matapos makuha ang learner's permit bago kumuha ng road test?","o":["Anim na buwan","Isang buwan","Tatlong buwan","Dalawang taon"],"h1":"Kalahating taon ito.","h2":"Sa Pennsylvania, ang driver na wala pang 18 ay hindi puwedeng kumuha ng road test hangga't hindi pa lumilipas ang anim na buwan mula nang matanggap ang learner's permit.","p":"Tama. Maghintay ng anim na buwan."},"ar":{"q":"في Pennsylvania، إذا كان عمرك أقل من 18 سنة، كم يجب أن تنتظر بعد حصولك على تصريح التعلّم قبل اختبار القيادة على الطريق؟","o":["ستة أشهر","شهر واحد","ثلاثة أشهر","سنتان"],"h1":"المدة نصف سنة.","h2":"في Pennsylvania لا يجوز للسائق الذي عمره أقل من 18 سنة أن يقدّم اختبار القيادة على الطريق إلا بعد ستة أشهر من حصوله على تصريح التعلّم.","p":"صحيح. انتظر ستة أشهر."},"ref":{"doc":"PA","page":2}},{"id":"pa-005","scope":"PA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Pennsylvania, how many hours of supervised behind-the-wheel practice must a driver under 18 complete before the road test?","o":["30 hours","50 hours","65 hours","100 hours"],"h1":"It is more than 60 and less than 70.","h2":"In Pennsylvania a driver under 18 must complete at least 65 hours of supervised behind-the-wheel practice before the road test.","p":"Right. Pennsylvania asks for 65 hours."},"es":{"q":"En Pensilvania, ¿cuántas horas de práctica supervisada al volante debe completar un conductor menor de 18 años antes del examen de manejo?","o":["30 horas","50 horas","65 horas","100 horas"],"h1":"Son más de 60 y menos de 70.","h2":"En Pensilvania un conductor menor de 18 años debe completar por lo menos 65 horas de práctica supervisada al volante antes del examen de manejo.","p":"Correcto. Pensilvania pide 65 horas."},"zh":{"q":"在 Pennsylvania，未满 18 岁的司机在路考前必须完成多少小时有人陪同的开车练习？","o":["30 小时","50 小时","65 小时","100 小时"],"h1":"多于 60，少于 70。","h2":"在 Pennsylvania，未满 18 岁的司机在路考前必须完成至少 65 小时有人陪同的开车练习。","p":"对。Pennsylvania 要求 65 小时。"},"vi":{"q":"Ở Pennsylvania, người lái dưới 18 tuổi phải tập lái có người kèm bao nhiêu giờ trước khi thi lái xe trên đường?","o":["30 giờ","50 giờ","65 giờ","100 giờ"],"h1":"Nhiều hơn 60 và ít hơn 70.","h2":"Ở Pennsylvania, người lái dưới 18 tuổi phải tập lái có người kèm ít nhất 65 giờ trước khi thi lái xe trên đường.","p":"Đúng. Pennsylvania yêu cầu 65 giờ."},"tl":{"q":"Sa Pennsylvania, ilang oras ng pagsasanay sa pagmamaneho na may kasamang tagabantay ang dapat tapusin ng driver na wala pang 18 bago ang road test?","o":["30 oras","50 oras","65 oras","100 oras"],"h1":"Higit sa 60 at kulang sa 70.","h2":"Sa Pennsylvania, ang driver na wala pang 18 ay dapat makatapos ng hindi bababa sa 65 oras ng pagsasanay sa pagmamaneho na may kasamang tagabantay bago ang road test.","p":"Tama. 65 oras ang hinihingi ng Pennsylvania."},"ar":{"q":"في Pennsylvania، كم ساعة من التدريب على القيادة مع مرافق يجب أن يكملها السائق الذي عمره أقل من 18 سنة قبل اختبار الطريق؟","o":["30 ساعة","50 ساعة","65 ساعة","100 ساعة"],"h1":"العدد أكثر من 60 وأقل من 70.","h2":"في Pennsylvania يجب على السائق الذي عمره أقل من 18 سنة أن يكمل 65 ساعة على الأقل من التدريب على القيادة مع مرافق قبل اختبار الطريق.","p":"صحيح. Pennsylvania تطلب 65 ساعة."},"ref":{"doc":"PA","page":2}},{"id":"pa-006","scope":"PA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Pennsylvania, how many of the 65 practice hours must be driven at night?","o":["5 hours","10 hours","20 hours","30 hours"],"h1":"It is twice the number of bad-weather hours.","h2":"Of the 65 practice hours in Pennsylvania, at least 10 must be nighttime driving.","p":"Right. At least 10 hours at night."},"es":{"q":"En Pensilvania, ¿cuántas de las 65 horas de práctica deben ser de noche?","o":["5 horas","10 horas","20 horas","30 horas"],"h1":"Es el doble de las horas con mal tiempo.","h2":"De las 65 horas de práctica en Pensilvania, por lo menos 10 deben ser de manejo nocturno.","p":"Correcto. Por lo menos 10 horas de noche."},"zh":{"q":"在 Pennsylvania，65 小时练习中，有多少小时必须在晚上开？","o":["5 小时","10 小时","20 小时","30 小时"],"h1":"是坏天气小时数的两倍。","h2":"在 Pennsylvania 的 65 小时练习中，至少 10 小时必须在晚上开车。","p":"对。晚上至少 10 小时。"},"vi":{"q":"Ở Pennsylvania, trong 65 giờ tập lái, bao nhiêu giờ phải lái vào ban đêm?","o":["5 giờ","10 giờ","20 giờ","30 giờ"],"h1":"Gấp đôi số giờ lái khi thời tiết xấu.","h2":"Trong 65 giờ tập lái ở Pennsylvania, ít nhất 10 giờ phải lái vào ban đêm.","p":"Đúng. Ít nhất 10 giờ ban đêm."},"tl":{"q":"Sa Pennsylvania, ilan sa 65 oras ng pagsasanay ang dapat imaneho sa gabi?","o":["5 oras","10 oras","20 oras","30 oras"],"h1":"Doble ito ng oras sa masamang panahon.","h2":"Sa 65 oras ng pagsasanay sa Pennsylvania, hindi bababa sa 10 ang dapat pagmamaneho sa gabi.","p":"Tama. Hindi bababa sa 10 oras sa gabi."},"ar":{"q":"في Pennsylvania، كم ساعة من ساعات التدريب الـ 65 يجب أن تكون قيادة في الليل؟","o":["5 ساعات","10 ساعات","20 ساعة","30 ساعة"],"h1":"العدد ضعف ساعات القيادة في الطقس السيئ.","h2":"من ساعات التدريب الـ 65 في Pennsylvania، يجب أن تكون 10 ساعات على الأقل قيادة في الليل.","p":"صحيح. 10 ساعات على الأقل في الليل."},"ref":{"doc":"PA","page":2}},{"id":"pa-007","scope":"PA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Pennsylvania, how many of the 65 practice hours must be driven in bad weather?","o":["None","1 hour","15 hours","5 hours"],"h1":"It is half the number of night hours.","h2":"Of the 65 practice hours in Pennsylvania, at least 5 must be driven in bad weather, such as rain, snow or fog.","p":"Right. At least 5 hours in bad weather."},"es":{"q":"En Pensilvania, ¿cuántas de las 65 horas de práctica deben ser con mal tiempo?","o":["Ninguna","1 hora","15 horas","5 horas"],"h1":"Es la mitad de las horas de noche.","h2":"De las 65 horas de práctica en Pensilvania, por lo menos 5 deben ser con mal tiempo, como lluvia, nieve o niebla.","p":"Correcto. Por lo menos 5 horas con mal tiempo."},"zh":{"q":"在 Pennsylvania，65 小时练习中，有多少小时必须在坏天气里开？","o":["不需要","1 小时","15 小时","5 小时"],"h1":"是晚上小时数的一半。","h2":"在 Pennsylvania 的 65 小时练习中，至少 5 小时必须在坏天气里开车，例如下雨、下雪或有雾。","p":"对。坏天气里至少 5 小时。"},"vi":{"q":"Ở Pennsylvania, trong 65 giờ tập lái, bao nhiêu giờ phải lái khi thời tiết xấu?","o":["Không cần","1 giờ","15 giờ","5 giờ"],"h1":"Bằng một nửa số giờ lái ban đêm.","h2":"Trong 65 giờ tập lái ở Pennsylvania, ít nhất 5 giờ phải lái khi thời tiết xấu, như mưa, tuyết hoặc sương mù.","p":"Đúng. Ít nhất 5 giờ khi thời tiết xấu."},"tl":{"q":"Sa Pennsylvania, ilan sa 65 oras ng pagsasanay ang dapat imaneho sa masamang panahon?","o":["Wala","1 oras","15 oras","5 oras"],"h1":"Kalahati ito ng oras sa gabi.","h2":"Sa 65 oras ng pagsasanay sa Pennsylvania, hindi bababa sa 5 ang dapat imaneho sa masamang panahon, gaya ng ulan, niyebe o hamog.","p":"Tama. Hindi bababa sa 5 oras sa masamang panahon."},"ar":{"q":"في Pennsylvania، كم ساعة من ساعات التدريب الـ 65 يجب أن تكون قيادة في الطقس السيئ؟","o":["لا شيء","ساعة واحدة (1)","15 ساعة","5 ساعات"],"h1":"العدد نصف ساعات القيادة في الليل.","h2":"من ساعات التدريب الـ 65 في Pennsylvania، يجب أن تكون 5 ساعات على الأقل قيادة في الطقس السيئ، مثل المطر أو الثلج أو الضباب.","p":"صحيح. 5 ساعات على الأقل في الطقس السيئ."},"ref":{"doc":"PA","page":2}},{"id":"pa-008","scope":"PA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Pennsylvania, who signs the form saying a teen finished the 65 hours of practice?","o":["A parent or guardian","The teen alone","A friend from school","Nobody; no form is needed"],"h1":"It is the adult responsible for the teen.","h2":"In Pennsylvania a parent or guardian signs the certification form saying the teen completed the 65 hours of supervised driving.","p":"Right. A parent or guardian signs it."},"es":{"q":"En Pensilvania, ¿quién firma el formulario que dice que un adolescente completó las 65 horas de práctica?","o":["Un padre, madre o tutor","El adolescente solo","Un amigo de la escuela","Nadie; no hace falta formulario"],"h1":"Es el adulto responsable del adolescente.","h2":"En Pensilvania un padre, madre o tutor firma el formulario de certificación que dice que el adolescente completó las 65 horas de manejo supervisado.","p":"Correcto. Lo firma un padre, madre o tutor."},"zh":{"q":"在 Pennsylvania，谁在表格上签字，证明青少年已完成 65 小时练习？","o":["父母或监护人","青少年自己","学校的朋友","没有人，不需要表格"],"h1":"是对这个青少年负责的大人。","h2":"在 Pennsylvania，由父母或监护人在证明表上签字，证明青少年已完成 65 小时有人陪同的开车练习。","p":"对。由父母或监护人签字。"},"vi":{"q":"Ở Pennsylvania, ai ký vào mẫu đơn xác nhận thiếu niên đã tập đủ 65 giờ?","o":["Cha mẹ hoặc người giám hộ","Chỉ thiếu niên đó","Một người bạn ở trường","Không ai cả; không cần mẫu đơn"],"h1":"Đó là người lớn chịu trách nhiệm về thiếu niên đó.","h2":"Ở Pennsylvania, cha mẹ hoặc người giám hộ ký vào mẫu đơn xác nhận thiếu niên đã tập lái có người kèm đủ 65 giờ.","p":"Đúng. Cha mẹ hoặc người giám hộ ký."},"tl":{"q":"Sa Pennsylvania, sino ang pumipirma sa form na nagsasabing natapos ng tinedyer ang 65 oras ng pagsasanay?","o":["Magulang o guardian","Ang tinedyer lang","Isang kaibigan sa paaralan","Wala; hindi kailangan ng form"],"h1":"Ito ang adultong may pananagutan sa tinedyer.","h2":"Sa Pennsylvania, ang magulang o guardian ang pumipirma sa certification form na nagsasabing natapos ng tinedyer ang 65 oras ng pagmamaneho na may kasamang tagabantay.","p":"Tama. Magulang o guardian ang pumipirma."},"ar":{"q":"في Pennsylvania، من يوقّع النموذج الذي يقول إن المراهق أكمل 65 ساعة من التدريب؟","o":["أحد الوالدين أو الوصي","المراهق وحده","صديق من المدرسة","لا أحد؛ لا حاجة إلى نموذج"],"h1":"هو الشخص البالغ المسؤول عن المراهق.","h2":"في Pennsylvania يوقّع أحد الوالدين أو الوصي نموذج الإقرار الذي يقول إن المراهق أكمل 65 ساعة من القيادة مع مرافق.","p":"صحيح. يوقّعه أحد الوالدين أو الوصي."},"ref":{"doc":"PA","page":5}},{"id":"pa-009","scope":"PA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Pennsylvania, during which hours may a junior license holder not drive, unless a parent, guardian or spouse 18 or older is in the car?","o":["9 p.m. to 6 a.m.","Midnight to 6 a.m.","11 p.m. to 5 a.m.","10 p.m. to 4 a.m."],"h1":"It starts one hour before midnight.","h2":"In Pennsylvania a junior license holder may not drive between 11 p.m. and 5 a.m. unless a parent, guardian or spouse 18 or older is with them, or an exception applies.","p":"Right. Not from 11 p.m. to 5 a.m."},"es":{"q":"En Pensilvania, ¿en qué horario no puede manejar el titular de una licencia junior, a menos que vaya con él su padre, madre, tutor o cónyuge de 18 años o más?","o":["De 9 p.m. a 6 a.m.","De medianoche a 6 a.m.","De 11 p.m. a 5 a.m.","De 10 p.m. a 4 a.m."],"h1":"Empieza una hora antes de la medianoche.","h2":"En Pensilvania el titular de una licencia junior no puede manejar entre las 11 p.m. y las 5 a.m., a menos que vaya con él su padre, madre, tutor o cónyuge de 18 años o más, o que se aplique una excepción.","p":"Correcto. No de 11 p.m. a 5 a.m."},"zh":{"q":"在 Pennsylvania，持青少年驾照（junior license）的人在哪段时间不能开车，除非车里有 18 岁或以上的父母、监护人或配偶？","o":["晚上 9 点到早上 6 点","午夜 12 点到早上 6 点","晚上 11 点到早上 5 点","晚上 10 点到早上 4 点"],"h1":"它从午夜前一小时开始。","h2":"在 Pennsylvania，持青少年驾照的人在晚上 11 点到早上 5 点之间不能开车，除非有 18 岁或以上的父母、监护人或配偶在车里，或者符合例外情况。","p":"对。晚上 11 点到早上 5 点不能开。"},"vi":{"q":"Ở Pennsylvania, người có bằng lái thiếu niên (junior license) không được lái xe trong khoảng giờ nào, trừ khi có cha mẹ, người giám hộ hoặc vợ/chồng từ 18 tuổi trở lên ngồi trong xe?","o":["9 giờ tối đến 6 giờ sáng","Nửa đêm đến 6 giờ sáng","11 giờ tối đến 5 giờ sáng","10 giờ tối đến 4 giờ sáng"],"h1":"Bắt đầu một giờ trước nửa đêm.","h2":"Ở Pennsylvania, người có bằng lái thiếu niên không được lái xe từ 11 giờ tối đến 5 giờ sáng, trừ khi có cha mẹ, người giám hộ hoặc vợ/chồng từ 18 tuổi trở lên đi cùng, hoặc có trường hợp ngoại lệ.","p":"Đúng. Không lái từ 11 giờ tối đến 5 giờ sáng."},"tl":{"q":"Sa Pennsylvania, sa anong mga oras hindi puwedeng magmaneho ang may hawak ng junior license, maliban kung may magulang, guardian o asawa na 18 pataas sa sasakyan?","o":["9 p.m. hanggang 6 a.m.","Hatinggabi hanggang 6 a.m.","11 p.m. hanggang 5 a.m.","10 p.m. hanggang 4 a.m."],"h1":"Nagsisimula ito isang oras bago maghatinggabi.","h2":"Sa Pennsylvania, ang may hawak ng junior license ay hindi puwedeng magmaneho mula 11 p.m. hanggang 5 a.m., maliban kung kasama ang magulang, guardian o asawa na 18 pataas, o may exception na tumutugma.","p":"Tama. Bawal mula 11 p.m. hanggang 5 a.m."},"ar":{"q":"في Pennsylvania، في أي ساعات لا يجوز لحامل رخصة الناشئين (junior license) أن يقود، إلا إذا كان معه في السيارة أحد الوالدين أو الوصي أو الزوج أو الزوجة بعمر 18 سنة أو أكثر؟","o":["من 9 مساءً إلى 6 صباحًا","من منتصف الليل إلى 6 صباحًا","من 11 مساءً إلى 5 صباحًا","من 10 مساءً إلى 4 صباحًا"],"h1":"تبدأ قبل منتصف الليل بساعة واحدة.","h2":"في Pennsylvania لا يجوز لحامل رخصة الناشئين أن يقود بين 11 مساءً و5 صباحًا، إلا إذا كان معه أحد الوالدين أو الوصي أو الزوج أو الزوجة بعمر 18 سنة أو أكثر، أو إذا انطبق استثناء.","p":"صحيح. لا قيادة من 11 مساءً إلى 5 صباحًا."},"ref":{"doc":"PA","page":3}},{"id":"pa-010","scope":"PA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Pennsylvania, which reason lets a junior license holder drive alone between 11 p.m. and 5 a.m.?","o":["Working during those hours, with proper documentation","Visiting friends","Going out to eat","Driving to practice for the road test"],"h1":"It is a duty, not a social outing.","h2":"A Pennsylvania junior license holder may drive between 11 p.m. and 5 a.m. for a job, public or charitable service, or a volunteer fire company, carrying proper documentation.","p":"Right. Work or volunteer service is an exception."},"es":{"q":"En Pensilvania, ¿qué razón permite que el titular de una licencia junior maneje solo entre las 11 p.m. y las 5 a.m.?","o":["Trabajar en ese horario, con la documentación correcta","Visitar a amigos","Salir a comer","Practicar para el examen de manejo"],"h1":"Es una obligación, no una salida social.","h2":"El titular de una licencia junior en Pensilvania puede manejar entre las 11 p.m. y las 5 a.m. por su trabajo, por servicio público o caritativo, o como bombero voluntario, si lleva la documentación correcta.","p":"Correcto. El trabajo o el voluntariado son una excepción."},"zh":{"q":"在 Pennsylvania，哪个理由可以让持青少年驾照（junior license）的人在晚上 11 点到早上 5 点之间独自开车？","o":["在那段时间工作，并带着正式证明文件","去看朋友","出去吃饭","开车练习准备路考"],"h1":"它是一种职责，不是社交活动。","h2":"在 Pennsylvania，持青少年驾照的人可以在晚上 11 点到早上 5 点之间为了工作、公共或慈善服务、或志愿消防队开车，但要带着正式证明文件。","p":"对。工作或志愿服务是例外。"},"vi":{"q":"Ở Pennsylvania, lý do nào cho phép người có bằng lái thiếu niên (junior license) lái xe một mình từ 11 giờ tối đến 5 giờ sáng?","o":["Đi làm trong những giờ đó, có giấy tờ chứng minh hợp lệ","Đi thăm bạn bè","Đi ăn ngoài","Lái xe tập luyện cho kỳ thi lái xe trên đường"],"h1":"Đó là một nhiệm vụ, không phải đi chơi.","h2":"Ở Pennsylvania, người có bằng lái thiếu niên được lái xe từ 11 giờ tối đến 5 giờ sáng để đi làm, làm công việc công ích hoặc từ thiện, hoặc cho đội cứu hỏa tình nguyện, và phải mang theo giấy tờ chứng minh hợp lệ.","p":"Đúng. Đi làm hoặc làm tình nguyện là ngoại lệ."},"tl":{"q":"Sa Pennsylvania, anong dahilan ang nagpapahintulot sa may hawak ng junior license na magmaneho nang mag-isa mula 11 p.m. hanggang 5 a.m.?","o":["Pagtatrabaho sa mga oras na iyon, na may tamang dokumento","Pagbisita sa mga kaibigan","Paglabas para kumain","Pagmamaneho para magsanay para sa road test"],"h1":"Isa itong tungkulin, hindi lakad kasama ang barkada.","h2":"Sa Pennsylvania, ang may hawak ng junior license ay puwedeng magmaneho mula 11 p.m. hanggang 5 a.m. para sa trabaho, serbisyo publiko o kawanggawa, o volunteer fire company, basta may dalang tamang dokumento.","p":"Tama. Exception ang trabaho o boluntaryong serbisyo."},"ar":{"q":"في Pennsylvania، ما السبب الذي يسمح لحامل رخصة الناشئين (junior license) أن يقود وحده بين 11 مساءً و5 صباحًا؟","o":["العمل في تلك الساعات، مع وثائق رسمية مناسبة","زيارة الأصدقاء","الخروج لتناول الطعام","القيادة للتدريب على اختبار الطريق"],"h1":"هو واجب، وليس نزهة اجتماعية.","h2":"في Pennsylvania يجوز لحامل رخصة الناشئين أن يقود بين 11 مساءً و5 صباحًا من أجل العمل، أو خدمة عامة أو خيرية، أو فرقة إطفاء تطوعية، بشرط أن يحمل وثائق رسمية مناسبة.","p":"صحيح. العمل أو الخدمة التطوعية استثناء."},"ref":{"doc":"PA","page":3}},{"id":"pa-011","scope":"PA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Pennsylvania, during the first six months with a junior license, how many passengers under 18 who are not immediate family may ride with the driver?","o":["None","One","Two","Three"],"h1":"It is the smallest number above zero.","h2":"During the first six months with a Pennsylvania junior license, the driver may carry only one passenger under 18 who is not immediate family, unless a parent or guardian is in the car.","p":"Right. Only one non-family passenger under 18."},"es":{"q":"En Pensilvania, durante los primeros seis meses con licencia junior, ¿cuántos pasajeros menores de 18 años que no son familia inmediata pueden ir con el conductor?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Es el número más pequeño mayor que cero.","h2":"Durante los primeros seis meses con licencia junior en Pensilvania, el conductor solo puede llevar un pasajero menor de 18 años que no sea familia inmediata, a menos que vaya su padre, madre o tutor.","p":"Correcto. Solo un pasajero menor de 18 que no es familia."},"zh":{"q":"在 Pennsylvania，拿到青少年驾照（junior license）的前六个月，可以载几个不是直系亲属、未满 18 岁的乘客？","o":["不能载","一个","两个","三个"],"h1":"是大于零的最小数字。","h2":"在 Pennsylvania 拿到青少年驾照的前六个月，司机只能载一个不是直系亲属、未满 18 岁的乘客，除非父母或监护人在车里。","p":"对。只能载一个非家人、未满 18 岁的乘客。"},"vi":{"q":"Ở Pennsylvania, trong sáu tháng đầu có bằng lái thiếu niên (junior license), người lái được chở bao nhiêu hành khách dưới 18 tuổi không phải người thân trong gia đình?","o":["Không được chở ai","Một","Hai","Ba"],"h1":"Đó là số nhỏ nhất lớn hơn không.","h2":"Trong sáu tháng đầu có bằng lái thiếu niên ở Pennsylvania, người lái chỉ được chở một hành khách dưới 18 tuổi không phải người thân trong gia đình, trừ khi có cha mẹ hoặc người giám hộ trong xe.","p":"Đúng. Chỉ một hành khách dưới 18 tuổi không phải người nhà."},"tl":{"q":"Sa Pennsylvania, sa unang anim na buwan ng junior license, ilang pasaherong wala pang 18 na hindi malapit na pamilya ang puwedeng isakay ng driver?","o":["Wala","Isa","Dalawa","Tatlo"],"h1":"Ito ang pinakamaliit na bilang na higit sa zero.","h2":"Sa unang anim na buwan ng junior license sa Pennsylvania, isang pasahero lang na wala pang 18 at hindi malapit na pamilya ang puwedeng isakay ng driver, maliban kung may magulang o guardian sa sasakyan.","p":"Tama. Isa lang na pasaherong wala pang 18 na hindi pamilya."},"ar":{"q":"في Pennsylvania، خلال الأشهر الستة الأولى مع رخصة الناشئين (junior license)، كم راكبًا عمره أقل من 18 سنة وليس من العائلة المباشرة يمكن أن يركب مع السائق؟","o":["لا أحد","واحد","اثنان","ثلاثة"],"h1":"هو أصغر عدد أكبر من الصفر.","h2":"خلال الأشهر الستة الأولى مع رخصة الناشئين في Pennsylvania، يمكن للسائق أن يحمل راكبًا واحدًا فقط عمره أقل من 18 سنة وليس من العائلة المباشرة، إلا إذا كان أحد الوالدين أو الوصي في السيارة.","p":"صحيح. راكب واحد فقط من غير العائلة عمره أقل من 18 سنة."},"ref":{"doc":"PA","page":4}},{"id":"pa-012","scope":"PA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Pennsylvania, after six months with a junior license and a clean record, how many passengers under 18 who are not family may ride with the driver?","o":["One","Two","Any number","Three"],"h1":"The limit goes up, but there is still a limit.","h2":"After six months with a Pennsylvania junior license, with no at-fault crash and no driving conviction, the limit rises to three passengers under 18 who are not family.","p":"Right. The limit rises to three."},"es":{"q":"En Pensilvania, después de seis meses con licencia junior y un historial limpio, ¿cuántos pasajeros menores de 18 años que no son familia pueden ir con el conductor?","o":["Uno","Dos","Cualquier cantidad","Tres"],"h1":"El límite sube, pero todavía hay un límite.","h2":"Después de seis meses con licencia junior en Pensilvania, sin choques por su culpa y sin condenas de tránsito, el límite sube a tres pasajeros menores de 18 años que no sean familia.","p":"Correcto. El límite sube a tres."},"zh":{"q":"在 Pennsylvania，持青少年驾照（junior license）满六个月并且记录良好后，可以载几个不是家人、未满 18 岁的乘客？","o":["一个","两个","不限人数","三个"],"h1":"限制提高了，但还是有限制。","h2":"在 Pennsylvania 持青少年驾照满六个月后，如果没有负责任的车祸，也没有交通违法定罪，限制提高到三个不是家人、未满 18 岁的乘客。","p":"对。限制提高到三个。"},"vi":{"q":"Ở Pennsylvania, sau sáu tháng có bằng lái thiếu niên (junior license) và hồ sơ lái xe sạch, người lái được chở bao nhiêu hành khách dưới 18 tuổi không phải người nhà?","o":["Một","Hai","Bao nhiêu cũng được","Ba"],"h1":"Giới hạn tăng lên, nhưng vẫn còn giới hạn.","h2":"Sau sáu tháng có bằng lái thiếu niên ở Pennsylvania, nếu không gây tai nạn và không bị kết tội vi phạm lái xe, giới hạn tăng lên ba hành khách dưới 18 tuổi không phải người nhà.","p":"Đúng. Giới hạn tăng lên ba."},"tl":{"q":"Sa Pennsylvania, matapos ang anim na buwan sa junior license na malinis ang record, ilang pasaherong wala pang 18 na hindi pamilya ang puwedeng isakay ng driver?","o":["Isa","Dalawa","Kahit ilan","Tatlo"],"h1":"Tumataas ang limitasyon, pero may limitasyon pa rin.","h2":"Matapos ang anim na buwan sa junior license sa Pennsylvania, kung walang aksidenteng ikaw ang may kasalanan at walang conviction sa pagmamaneho, tumataas ang limitasyon sa tatlong pasaherong wala pang 18 na hindi pamilya.","p":"Tama. Tumataas ang limitasyon sa tatlo."},"ar":{"q":"في Pennsylvania، بعد ستة أشهر مع رخصة الناشئين (junior license) وسجل نظيف، كم راكبًا عمره أقل من 18 سنة وليس من العائلة يمكن أن يركب مع السائق؟","o":["واحد","اثنان","أي عدد","ثلاثة"],"h1":"الحد يرتفع، لكن ما زال هناك حد.","h2":"بعد ستة أشهر مع رخصة الناشئين في Pennsylvania، إذا لم يكن هناك حادث بخطأ السائق ولا إدانة في مخالفة قيادة، يرتفع الحد إلى ثلاثة ركاب أعمارهم أقل من 18 سنة وليسوا من العائلة.","p":"صحيح. يرتفع الحد إلى ثلاثة."},"ref":{"doc":"PA","page":4}},{"id":"pa-013","scope":"PA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Pennsylvania, what is the most passengers a junior license holder may ever carry?","o":["Five, in any car","As many as fit","No more than the number of seat belts in the car","Two"],"h1":"Every passenger needs something to wear.","h2":"In Pennsylvania a junior driver may never carry more passengers than there are seat belts in the vehicle.","p":"Right. No more passengers than seat belts."},"es":{"q":"En Pensilvania, ¿cuál es el número máximo de pasajeros que puede llevar el titular de una licencia junior?","o":["Cinco, en cualquier carro","Todos los que quepan","No más que la cantidad de cinturones de seguridad del carro","Dos"],"h1":"Cada pasajero necesita algo que ponerse.","h2":"En Pensilvania un conductor con licencia junior nunca puede llevar más pasajeros que cinturones de seguridad tiene el vehículo.","p":"Correcto. No más pasajeros que cinturones."},"zh":{"q":"在 Pennsylvania，持青少年驾照（junior license）的人最多能载多少乘客？","o":["五个，任何车都一样","坐得下多少就载多少","不超过车里安全带的数量","两个"],"h1":"每个乘客都需要系上一样东西。","h2":"在 Pennsylvania，青少年司机载的乘客永远不能多于车里的安全带数量。","p":"对。乘客不能多于安全带。"},"vi":{"q":"Ở Pennsylvania, người có bằng lái thiếu niên (junior license) được chở tối đa bao nhiêu hành khách?","o":["Năm người, với bất kỳ xe nào","Bao nhiêu người ngồi vừa cũng được","Không nhiều hơn số dây an toàn trong xe","Hai"],"h1":"Mỗi hành khách cần đeo một thứ.","h2":"Ở Pennsylvania, người lái có bằng lái thiếu niên không bao giờ được chở nhiều hành khách hơn số dây an toàn trong xe.","p":"Đúng. Không nhiều hành khách hơn số dây an toàn."},"tl":{"q":"Sa Pennsylvania, ano ang pinakamaraming pasahero na puwedeng isakay ng may hawak ng junior license?","o":["Lima, sa kahit anong sasakyan","Kung ilan ang kasya","Hindi hihigit sa bilang ng seat belt sa sasakyan","Dalawa"],"h1":"Bawat pasahero ay may kailangang isuot.","h2":"Sa Pennsylvania, ang junior driver ay hindi kailanman puwedeng magsakay ng mas maraming pasahero kaysa sa bilang ng seat belt sa sasakyan.","p":"Tama. Hindi hihigit ang pasahero sa seat belt."},"ar":{"q":"في Pennsylvania، ما أكبر عدد من الركاب يمكن أن يحمله حامل رخصة الناشئين (junior license)؟","o":["خمسة، في أي سيارة","بقدر ما تتسع السيارة","لا يزيد على عدد أحزمة الأمان في السيارة","اثنان"],"h1":"كل راكب يحتاج إلى شيء يلبسه.","h2":"في Pennsylvania لا يجوز أبدًا للسائق الناشئ أن يحمل ركابًا أكثر من عدد أحزمة الأمان في السيارة.","p":"صحيح. لا ركاب أكثر من أحزمة الأمان."},"ref":{"doc":"PA","page":3}},{"id":"pa-014","scope":"PA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Pennsylvania, when does the junior license limit on passengers under 18 not apply?","o":["When a parent or legal guardian is in the car","On weekends","When driving under 25 mph","When the passengers are 17"],"h1":"Think about which adult could be riding along.","h2":"The Pennsylvania junior license limit on passengers under 18 does not apply when a parent or legal guardian is in the vehicle.","p":"Right. A parent or guardian in the car lifts the limit."},"es":{"q":"En Pensilvania, ¿cuándo no se aplica el límite de pasajeros menores de 18 años de la licencia junior?","o":["Cuando va en el carro su padre, madre o tutor legal","Los fines de semana","Cuando maneja a menos de 25 mph","Cuando los pasajeros tienen 17 años"],"h1":"Piense en qué adulto podría ir con usted.","h2":"El límite de pasajeros menores de 18 años de la licencia junior en Pensilvania no se aplica cuando va en el vehículo su padre, madre o tutor legal.","p":"Correcto. Si va su padre, madre o tutor, no hay límite."},"zh":{"q":"在 Pennsylvania，青少年驾照（junior license）对未满 18 岁乘客的人数限制，什么时候不适用？","o":["父母或法定监护人在车里时","周末时","车速低于 25 mph 时","乘客是 17 岁时"],"h1":"想一想哪位大人可能坐在车里。","h2":"在 Pennsylvania，当父母或法定监护人在车里时，青少年驾照对未满 18 岁乘客的限制不适用。","p":"对。父母或监护人在车里，限制就取消。"},"vi":{"q":"Ở Pennsylvania, khi nào giới hạn hành khách dưới 18 tuổi của bằng lái thiếu niên (junior license) không áp dụng?","o":["Khi có cha mẹ hoặc người giám hộ hợp pháp trong xe","Vào cuối tuần","Khi lái dưới 25 mph","Khi hành khách 17 tuổi"],"h1":"Hãy nghĩ xem người lớn nào có thể ngồi cùng.","h2":"Ở Pennsylvania, giới hạn hành khách dưới 18 tuổi của bằng lái thiếu niên không áp dụng khi có cha mẹ hoặc người giám hộ hợp pháp trong xe.","p":"Đúng. Có cha mẹ hoặc người giám hộ trong xe thì không còn giới hạn."},"tl":{"q":"Sa Pennsylvania, kailan hindi umiiral ang limitasyon ng junior license sa mga pasaherong wala pang 18?","o":["Kapag may magulang o legal guardian sa sasakyan","Tuwing weekend","Kapag nagmamaneho nang mas mabagal sa 25 mph","Kapag 17 ang mga pasahero"],"h1":"Isipin kung sinong adulto ang puwedeng kasama sa biyahe.","h2":"Sa Pennsylvania, hindi umiiral ang limitasyon ng junior license sa mga pasaherong wala pang 18 kapag may magulang o legal guardian sa sasakyan.","p":"Tama. Nawawala ang limitasyon kapag may magulang o guardian sa sasakyan."},"ar":{"q":"في Pennsylvania، متى لا ينطبق حد رخصة الناشئين (junior license) على الركاب الذين أعمارهم أقل من 18 سنة؟","o":["عندما يكون أحد الوالدين أو الوصي القانوني في السيارة","في عطلة نهاية الأسبوع","عند القيادة بسرعة أقل من 25 mph","عندما يكون عمر الركاب 17 سنة"],"h1":"فكّر في الشخص البالغ الذي يمكن أن يركب معك.","h2":"في Pennsylvania لا ينطبق حد رخصة الناشئين على الركاب الذين أعمارهم أقل من 18 سنة عندما يكون أحد الوالدين أو الوصي القانوني في السيارة.","p":"صحيح. وجود أحد الوالدين أو الوصي في السيارة يلغي الحد."},"ref":{"doc":"PA","page":4}},{"id":"pa-015","scope":"PA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Pennsylvania, you are on the opposite side of a divided highway, with a guide rail or grass median between you and a stopped school bus. What must you do?","o":["Stop until the bus moves","Honk to warn the children","Speed up to pass quickly","You do not have to stop, but slow down and drive with caution"],"h1":"A physical divider protects the other side of the road.","h2":"In Pennsylvania, on the opposite side of a divided highway, you do not have to stop for a school bus, but you must slow down and drive with caution.","p":"Right. No stop needed, but slow down with caution."},"es":{"q":"En Pensilvania, usted va del lado contrario de una carretera dividida, con una barrera o una mediana de pasto entre usted y un autobús escolar detenido. ¿Qué debe hacer?","o":["Detenerse hasta que el autobús avance","Tocar la bocina para avisar a los niños","Acelerar para pasar rápido","No tiene que detenerse, pero debe bajar la velocidad y manejar con precaución"],"h1":"Una división física protege el otro lado de la carretera.","h2":"En Pensilvania, del lado contrario de una carretera dividida, usted no tiene que detenerse por un autobús escolar, pero debe bajar la velocidad y manejar con precaución.","p":"Correcto. No se detiene, pero baja la velocidad con precaución."},"zh":{"q":"在 Pennsylvania，你在分隔公路的对面一侧，你和停着的校车之间有护栏或草地中间带。你必须怎么做？","o":["停车，直到校车开走","按喇叭提醒孩子们","加速快点开过去","你不必停车，但要减速并小心驾驶"],"h1":"实体分隔物保护着公路的另一侧。","h2":"在 Pennsylvania，如果你在分隔公路的对面一侧，你不必为校车停车，但必须减速并小心驾驶。","p":"对。不用停车，但要减速小心。"},"vi":{"q":"Ở Pennsylvania, bạn ở phía bên kia của xa lộ có dải phân cách, giữa bạn và chiếc xe buýt trường học đang dừng có rào chắn hoặc dải cỏ. Bạn phải làm gì?","o":["Dừng lại cho đến khi xe buýt chạy đi","Bấm còi để báo cho các em","Tăng tốc để vượt qua nhanh","Bạn không cần dừng, nhưng phải chạy chậm lại và lái cẩn thận"],"h1":"Vật ngăn cách bảo vệ phía bên kia đường.","h2":"Ở Pennsylvania, khi ở phía bên kia của xa lộ có dải phân cách, bạn không cần dừng lại vì xe buýt trường học, nhưng phải chạy chậm lại và lái cẩn thận.","p":"Đúng. Không cần dừng, nhưng chạy chậm và cẩn thận."},"tl":{"q":"Sa Pennsylvania, nasa kabilang panig ka ng divided highway, at may guide rail o damuhang median sa pagitan mo at ng nakahintong school bus. Ano ang dapat mong gawin?","o":["Huminto hanggang umandar ang bus","Bumusina para bigyang-babala ang mga bata","Bumilis para mabilis na makalampas","Hindi mo kailangang huminto, pero bumagal at mag-ingat sa pagmamaneho"],"h1":"May pisikal na harang na nagpoprotekta sa kabilang panig ng daan.","h2":"Sa Pennsylvania, sa kabilang panig ng divided highway, hindi mo kailangang huminto para sa school bus, pero dapat kang bumagal at mag-ingat sa pagmamaneho.","p":"Tama. Hindi kailangang huminto, pero bumagal at mag-ingat."},"ar":{"q":"في Pennsylvania، أنت في الجهة المقابلة من طريق سريع مقسوم، وبينك وبين حافلة مدرسية متوقفة حاجز حديدي أو جزيرة وسطية من العشب. ماذا يجب أن تفعل؟","o":["توقف حتى تتحرك الحافلة","استخدم البوق لتحذير الأطفال","أسرِع لتتجاوز بسرعة","ليس عليك أن تتوقف، لكن خفّف السرعة وقُد بحذر"],"h1":"حاجز مادي يحمي الجهة الأخرى من الطريق.","h2":"في Pennsylvania، في الجهة المقابلة من طريق سريع مقسوم، ليس عليك أن تتوقف للحافلة المدرسية، لكن يجب أن تخفّف السرعة وتقود بحذر.","p":"صحيح. لا حاجة للتوقف، لكن خفّف السرعة وانتبه."},"ref":{"doc":"PA","page":58}},{"id":"pa-016","scope":"PA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Pennsylvania, what happens to your license if you fail to stop for a school bus with red lights flashing and the stop arm out?","o":["Nothing happens to the license","A 60-day license suspension","A one-week suspension","Only a warning"],"h1":"It is about two months.","h2":"In Pennsylvania, failing to stop for a school bus with red lights flashing and the stop arm out brings a 60-day license suspension, five points and a fine.","p":"Right. A 60-day suspension."},"es":{"q":"En Pensilvania, ¿qué pasa con su licencia si no se detiene por un autobús escolar con luces rojas intermitentes y el brazo de alto extendido?","o":["No le pasa nada a la licencia","Una suspensión de la licencia por 60 días","Una suspensión de una semana","Solo una advertencia"],"h1":"Son unos dos meses.","h2":"En Pensilvania, no detenerse por un autobús escolar con luces rojas intermitentes y el brazo de alto extendido trae una suspensión de la licencia por 60 días, cinco puntos y una multa.","p":"Correcto. Una suspensión de 60 días."},"zh":{"q":"在 Pennsylvania，如果校车红灯在闪、停车牌伸出来，你却没有停车，你的驾照会怎样？","o":["驾照没有任何影响","驾照被暂停 60 天","暂停一个星期","只是警告"],"h1":"大约两个月。","h2":"在 Pennsylvania，校车红灯在闪、停车牌伸出来时没有停车，驾照会被暂停 60 天，还要扣五分并罚款。","p":"对。暂停 60 天。"},"vi":{"q":"Ở Pennsylvania, bằng lái của bạn sẽ ra sao nếu bạn không dừng lại khi xe buýt trường học nháy đèn đỏ và đưa cần STOP ra?","o":["Bằng lái không bị gì cả","Bị treo bằng lái 60 ngày","Bị treo một tuần","Chỉ bị cảnh cáo"],"h1":"Khoảng hai tháng.","h2":"Ở Pennsylvania, không dừng lại khi xe buýt trường học nháy đèn đỏ và đưa cần STOP ra sẽ bị treo bằng lái 60 ngày, bị năm điểm và bị phạt tiền.","p":"Đúng. Bị treo 60 ngày."},"tl":{"q":"Sa Pennsylvania, ano ang mangyayari sa lisensya mo kung hindi ka huminto para sa school bus na kumikislap ang pulang ilaw at nakalabas ang stop arm?","o":["Walang mangyayari sa lisensya","Suspensyon ng lisensya nang 60 araw","Suspensyon nang isang linggo","Babala lang"],"h1":"Mga dalawang buwan ito.","h2":"Sa Pennsylvania, ang hindi paghinto para sa school bus na kumikislap ang pulang ilaw at nakalabas ang stop arm ay may 60 araw na suspensyon ng lisensya, limang puntos at multa.","p":"Tama. 60 araw na suspensyon."},"ar":{"q":"في Pennsylvania، ماذا يحدث لرخصتك إذا لم تتوقف لحافلة مدرسية أضواؤها الحمراء تومض وذراع التوقف (STOP) ممدودة؟","o":["لا يحدث شيء للرخصة","تعليق الرخصة 60 يومًا","تعليق لمدة أسبوع","إنذار فقط"],"h1":"المدة شهران تقريبًا.","h2":"في Pennsylvania، عدم التوقف لحافلة مدرسية أضواؤها الحمراء تومض وذراع التوقف ممدودة يؤدي إلى تعليق الرخصة 60 يومًا، وخمس نقاط، وغرامة.","p":"صحيح. تعليق 60 يومًا."},"ref":{"doc":"PA","page":58}},{"id":"pa-017","scope":"PA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Pennsylvania, how many points go on your driving record for failing to stop for a school bus?","o":["Five points","One point","Two points","No points"],"h1":"It is more than four and less than six.","h2":"In Pennsylvania, failing to stop for a school bus adds five points to your driving record, along with a suspension and a fine.","p":"Right. Five points."},"es":{"q":"En Pensilvania, ¿cuántos puntos se agregan a su historial de manejo por no detenerse por un autobús escolar?","o":["Cinco puntos","Un punto","Dos puntos","Ningún punto"],"h1":"Es más de cuatro y menos de seis.","h2":"En Pensilvania, no detenerse por un autobús escolar agrega cinco puntos a su historial de manejo, además de una suspensión y una multa.","p":"Correcto. Cinco puntos."},"zh":{"q":"在 Pennsylvania，没有为校车停车，你的驾驶记录上会记几分？","o":["五分","一分","两分","不记分"],"h1":"多于四，少于六。","h2":"在 Pennsylvania，没有为校车停车，你的驾驶记录会加五分，还会被暂停驾照并罚款。","p":"对。五分。"},"vi":{"q":"Ở Pennsylvania, không dừng lại vì xe buýt trường học sẽ bị ghi bao nhiêu điểm vào hồ sơ lái xe?","o":["Năm điểm","Một điểm","Hai điểm","Không bị điểm"],"h1":"Nhiều hơn bốn và ít hơn sáu.","h2":"Ở Pennsylvania, không dừng lại vì xe buýt trường học sẽ bị ghi năm điểm vào hồ sơ lái xe, cùng với bị treo bằng và bị phạt tiền.","p":"Đúng. Năm điểm."},"tl":{"q":"Sa Pennsylvania, ilang puntos ang idinadagdag sa driving record mo kapag hindi ka huminto para sa school bus?","o":["Limang puntos","Isang puntos","Dalawang puntos","Walang puntos"],"h1":"Higit sa apat at kulang sa anim.","h2":"Sa Pennsylvania, ang hindi paghinto para sa school bus ay nagdadagdag ng limang puntos sa driving record mo, kasama ang suspensyon at multa.","p":"Tama. Limang puntos."},"ar":{"q":"في Pennsylvania، كم نقطة تُضاف إلى سجل القيادة إذا لم تتوقف لحافلة مدرسية؟","o":["خمس نقاط","نقطة واحدة","نقطتان","لا نقاط"],"h1":"العدد أكثر من أربعة وأقل من ستة.","h2":"في Pennsylvania، عدم التوقف لحافلة مدرسية يضيف خمس نقاط إلى سجل القيادة، مع تعليق الرخصة وغرامة.","p":"صحيح. خمس نقاط."},"ref":{"doc":"PA","page":58}},{"id":"pa-018","scope":"PA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Pennsylvania, what does the Move Over law ask you to do near an emergency response area?","o":["Stop and wait until it is cleared","Turn on your hazard lights and keep going","Move into a lane that is not next to it, or slow down if you cannot","Use the shoulder to pass"],"h1":"The law's name tells you the first step.","h2":"Pennsylvania's Move Over law requires you to move into a lane that is not next to an emergency response area, or, if you cannot move over, to slow down to at least 20 mph below the speed limit.","p":"Right. Move over, or slow down if you cannot."},"es":{"q":"En Pensilvania, ¿qué le pide la ley Move Over (muévase al otro carril) cerca de un área de respuesta a emergencias?","o":["Detenerse y esperar hasta que se despeje","Encender las luces de emergencia y seguir","Pasarse a un carril que no esté junto a la zona o, si no puede, bajar la velocidad","Usar el acotamiento para pasar"],"h1":"El nombre de la ley le dice el primer paso.","h2":"La ley Move Over de Pensilvania le exige pasarse a un carril que no esté junto a un área de respuesta a emergencias o, si no puede cambiarse de carril, bajar la velocidad a por lo menos 20 mph por debajo del límite.","p":"Correcto. Cámbiese de carril, o baje la velocidad si no puede."},"zh":{"q":"在 Pennsylvania，让道法（Move Over law）要求你在紧急救援区域附近怎么做？","o":["停车，等到清理完毕","打开双闪灯继续开","换到不紧挨着它的车道；如果换不了，就减速","用路肩超车"],"h1":"这条法律的名字告诉你第一步。","h2":"Pennsylvania 的让道法（Move Over law）要求你换到不紧挨着紧急救援区域的车道；如果换不了，就要减速到比限速至少低 20 mph。","p":"对。换车道，换不了就减速。"},"vi":{"q":"Ở Pennsylvania, luật Nhường Làn (Move Over law) yêu cầu bạn làm gì khi đến gần khu vực cấp cứu khẩn cấp?","o":["Dừng lại và chờ đến khi dọn xong","Bật đèn khẩn cấp và tiếp tục chạy","Chuyển sang làn không sát bên khu vực đó, hoặc chạy chậm lại nếu không chuyển được","Chạy trên lề đường để vượt qua"],"h1":"Tên của luật cho bạn biết bước đầu tiên.","h2":"Luật Nhường Làn (Move Over law) của Pennsylvania yêu cầu bạn chuyển sang làn không sát bên khu vực cấp cứu khẩn cấp, hoặc nếu không chuyển được thì chạy chậm lại ít nhất 20 mph dưới tốc độ giới hạn.","p":"Đúng. Chuyển làn, hoặc chạy chậm lại nếu không chuyển được."},"tl":{"q":"Sa Pennsylvania, ano ang ipinagagawa sa iyo ng Move Over law malapit sa emergency response area?","o":["Huminto at maghintay hanggang malinis ito","Buksan ang hazard lights at magpatuloy","Lumipat sa lane na hindi katabi nito, o bumagal kung hindi ka makalipat","Gamitin ang shoulder para makalampas"],"h1":"Sinasabi ng pangalan ng batas ang unang hakbang.","h2":"Ang Move Over law ng Pennsylvania ay nag-uutos na lumipat ka sa lane na hindi katabi ng emergency response area, o kung hindi ka makalipat, bumagal nang hindi bababa sa 20 mph mas mababa sa speed limit.","p":"Tama. Lumipat ng lane, o bumagal kung hindi makalipat."},"ar":{"q":"في Pennsylvania، ماذا يطلب منك قانون إفساح الطريق (Move Over law) قرب منطقة استجابة للطوارئ؟","o":["توقف وانتظر حتى يتم إخلاؤها","شغّل أضواء التحذير واستمر في السير","انتقل إلى مسار غير مجاور لها، أو خفّف السرعة إذا لم تستطع","استخدم كتف الطريق لتتجاوز"],"h1":"اسم القانون يخبرك بالخطوة الأولى.","h2":"قانون إفساح الطريق (Move Over law) في Pennsylvania يطلب منك أن تنتقل إلى مسار غير مجاور لمنطقة الاستجابة للطوارئ، أو إذا لم تستطع الانتقال، أن تخفّف السرعة إلى 20 mph على الأقل تحت حد السرعة.","p":"صحيح. انتقل إلى مسار آخر، أو خفّف السرعة إذا لم تستطع."},"ref":{"doc":"PA","page":59}},{"id":"pa-019","scope":"PA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Pennsylvania, may you hold your phone while stopped at a red light?","o":["Yes, if the car is stopped","No, holding a phone is banned even when stopped in traffic or at a red light","Yes, for less than one minute","Yes, if you are over 21"],"h1":"Stopping for a moment still counts as driving.","h2":"Pennsylvania's Paul Miller's Law bans holding a phone while driving, even when stopped for a moment in traffic or at a red light; hands-free use is allowed.","p":"Right. No phone in your hand, even at a red light."},"es":{"q":"En Pensilvania, ¿puede sostener su teléfono mientras está detenido en un semáforo en rojo?","o":["Sí, si el carro está detenido","No, sostener el teléfono está prohibido aunque esté detenido en el tráfico o en un semáforo en rojo","Sí, por menos de un minuto","Sí, si tiene más de 21 años"],"h1":"Detenerse un momento todavía cuenta como manejar.","h2":"La Ley Paul Miller de Pensilvania prohíbe sostener el teléfono mientras maneja, incluso cuando se detiene un momento en el tráfico o en un semáforo en rojo; el uso con manos libres está permitido.","p":"Correcto. Nada de teléfono en la mano, ni en el semáforo."},"zh":{"q":"在 Pennsylvania，停在红灯前时，你可以手拿手机吗？","o":["可以，只要车停着","不可以，即使在车流中停着或在红灯前，也禁止手拿手机","可以，不超过一分钟","可以，如果你超过 21 岁"],"h1":"停一下也还算是在开车。","h2":"Pennsylvania 的 Paul Miller 法（Paul Miller's Law）禁止开车时手拿手机，即使在车流中或红灯前暂时停下也一样；可以用免提。","p":"对。即使在红灯前，手里也不能拿手机。"},"vi":{"q":"Ở Pennsylvania, bạn có được cầm điện thoại khi dừng ở đèn đỏ không?","o":["Được, nếu xe đang dừng","Không, cấm cầm điện thoại ngay cả khi dừng trong dòng xe hoặc ở đèn đỏ","Được, nếu ít hơn một phút","Được, nếu bạn trên 21 tuổi"],"h1":"Dừng một lát vẫn được tính là đang lái xe.","h2":"Luật Paul Miller (Paul Miller's Law) của Pennsylvania cấm cầm điện thoại khi lái xe, ngay cả khi dừng một lát trong dòng xe hoặc ở đèn đỏ; được dùng loại rảnh tay.","p":"Đúng. Không cầm điện thoại trên tay, kể cả ở đèn đỏ."},"tl":{"q":"Sa Pennsylvania, puwede mo bang hawakan ang phone mo habang nakahinto sa pulang ilaw?","o":["Oo, kung nakahinto ang sasakyan","Hindi, bawal humawak ng phone kahit nakahinto sa trapiko o sa pulang ilaw","Oo, kung wala pang isang minuto","Oo, kung lampas 21 ka na"],"h1":"Ang sandaling paghinto ay itinuturing pa ring pagmamaneho.","h2":"Ipinagbabawal ng Paul Miller's Law ng Pennsylvania ang paghawak ng phone habang nagmamaneho, kahit sandaling nakahinto sa trapiko o sa pulang ilaw; puwede ang hands-free.","p":"Tama. Walang phone sa kamay, kahit sa pulang ilaw."},"ar":{"q":"في Pennsylvania، هل يجوز أن تمسك هاتفك بيدك وأنت متوقف عند إشارة حمراء؟","o":["نعم، إذا كانت السيارة متوقفة","لا، إمساك الهاتف ممنوع حتى عند التوقف في الزحام أو عند إشارة حمراء","نعم، لمدة أقل من دقيقة واحدة","نعم، إذا كان عمرك أكثر من 21 سنة"],"h1":"التوقف للحظة ما زال يُعتبر قيادة.","h2":"قانون Paul Miller (Paul Miller's Law) في Pennsylvania يمنع إمساك الهاتف أثناء القيادة، حتى عند التوقف للحظة في الزحام أو عند إشارة حمراء؛ الاستخدام بدون استعمال اليدين مسموح.","p":"صحيح. لا هاتف في يدك، حتى عند الإشارة الحمراء."},"ref":{"doc":"PA","page":null}},{"id":"pa-020","scope":"PA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Pennsylvania, what blood alcohol level is illegal for a driver under 21?","o":["0.08 percent or more","0.05 percent or more","0.10 percent or more","0.02 percent or more"],"h1":"It is far lower than the adult limit.","h2":"In Pennsylvania a driver under 21 breaks the law at a blood alcohol level of 0.02 percent or more, far below the 0.08 adult limit.","p":"Right. Under 21, the limit is 0.02 percent."},"es":{"q":"En Pensilvania, ¿qué nivel de alcohol en la sangre es ilegal para un conductor menor de 21 años?","o":["0.08 por ciento o más","0.05 por ciento o más","0.10 por ciento o más","0.02 por ciento o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Pensilvania un conductor menor de 21 años viola la ley con un nivel de alcohol en la sangre de 0.02 por ciento o más, muy por debajo del límite de 0.08 para adultos.","p":"Correcto. Para menores de 21, el límite es 0.02 por ciento."},"zh":{"q":"在 Pennsylvania，未满 21 岁的司机，血液酒精浓度多少就违法？","o":["0.08% 或以上","0.05% 或以上","0.10% 或以上","0.02% 或以上"],"h1":"它比成年人的限制低很多。","h2":"在 Pennsylvania，未满 21 岁的司机血液酒精浓度达到 0.02% 或以上就违法，远低于成年人 0.08% 的限制。","p":"对。未满 21 岁，限制是 0.02%。"},"vi":{"q":"Ở Pennsylvania, nồng độ cồn trong máu bao nhiêu là phạm pháp đối với người lái dưới 21 tuổi?","o":["0.08 phần trăm trở lên","0.05 phần trăm trở lên","0.10 phần trăm trở lên","0.02 phần trăm trở lên"],"h1":"Thấp hơn nhiều so với giới hạn của người lớn.","h2":"Ở Pennsylvania, người lái dưới 21 tuổi phạm luật khi nồng độ cồn trong máu từ 0.02 phần trăm trở lên, thấp hơn nhiều so với giới hạn 0.08 của người lớn.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02 phần trăm."},"tl":{"q":"Sa Pennsylvania, anong blood alcohol level ang ilegal para sa driver na wala pang 21?","o":["0.08 porsiyento o higit pa","0.05 porsiyento o higit pa","0.10 porsiyento o higit pa","0.02 porsiyento o higit pa"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon ng adulto.","h2":"Sa Pennsylvania, lumalabag sa batas ang driver na wala pang 21 kapag ang blood alcohol level ay 0.02 porsiyento o higit pa, mas mababa nang malaki sa 0.08 na limitasyon ng adulto.","p":"Tama. Para sa wala pang 21, 0.02 porsiyento ang limitasyon."},"ar":{"q":"في Pennsylvania، ما نسبة الكحول في الدم التي تكون مخالفة للقانون للسائق الذي عمره أقل من 21 سنة؟","o":["0.08 بالمئة أو أكثر","0.05 بالمئة أو أكثر","0.10 بالمئة أو أكثر","0.02 بالمئة أو أكثر"],"h1":"هي أقل بكثير من الحد المسموح للبالغين.","h2":"في Pennsylvania يخالف السائق الذي عمره أقل من 21 سنة القانون إذا كانت نسبة الكحول في دمه 0.02 بالمئة أو أكثر، وهذا أقل بكثير من حد البالغين 0.08.","p":"صحيح. لمن عمره أقل من 21 سنة، الحد هو 0.02 بالمئة."},"ref":{"doc":"PA","page":33}},{"id":"pa-021","scope":"PA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Pennsylvania, how long is a learner's permit valid?","o":["90 days","Six months","One year","Two years"],"h1":"It lasts twice as long as the time a teen must wait before the road test.","h2":"In Pennsylvania, a learner's permit is valid for one year from the issue date printed on it.","p":"Right. A learner's permit lasts one year."},"es":{"q":"En Pensilvania, ¿por cuánto tiempo es válido un permiso de aprendizaje?","o":["90 días","Seis meses","Un año","Dos años"],"h1":"Dura el doble del tiempo que un adolescente debe esperar antes del examen de manejo.","h2":"En Pensilvania, el permiso de aprendizaje es válido por un año a partir de la fecha de emisión impresa en él.","p":"Correcto. El permiso de aprendizaje dura un año."},"zh":{"q":"在 Pennsylvania，学习驾照（learner's permit）的有效期是多久？","o":["90 天","六个月","一年","两年"],"h1":"它的时长是青少年参加路考前必须等待时间的两倍。","h2":"在 Pennsylvania，学习驾照从上面印的签发日期起有效一年。","p":"对。学习驾照有效一年。"},"vi":{"q":"Ở Pennsylvania, giấy phép tập lái (learner's permit) có giá trị trong bao lâu?","o":["90 ngày","Sáu tháng","Một năm","Hai năm"],"h1":"Thời gian này dài gấp đôi thời gian một thiếu niên phải chờ trước khi thi lái xe trên đường.","h2":"Ở Pennsylvania, giấy phép tập lái có giá trị một năm kể từ ngày cấp được in trên giấy phép.","p":"Đúng. Giấy phép tập lái có giá trị một năm."},"tl":{"q":"Sa Pennsylvania, gaano katagal valid ang learner's permit?","o":["90 araw","Anim na buwan","Isang taon","Dalawang taon"],"h1":"Doble ito ng panahong kailangang hintayin ng isang teen bago ang road test.","h2":"Sa Pennsylvania, valid ang learner's permit nang isang taon mula sa petsa ng pag-issue na nakalimbag dito.","p":"Tama. Isang taon ang learner's permit."},"ar":{"q":"في Pennsylvania، ما مدة صلاحية تصريح تعلّم القيادة (learner's permit)؟","o":["90 يومًا","ستة أشهر","سنة واحدة","سنتان"],"h1":"مدته ضعف المدة التي يجب أن ينتظرها المراهق قبل اختبار القيادة على الطريق.","h2":"في Pennsylvania، يكون تصريح تعلّم القيادة صالحًا لمدة سنة واحدة من تاريخ الإصدار المطبوع عليه.","p":"صحيح. تصريح تعلّم القيادة صالح لمدة سنة واحدة."},"ref":{"doc":"PA","page":3}},{"id":"pa-022","scope":"PA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Pennsylvania, what happens the first time a driver's record reaches 6 points?","o":["The driver must take a written special point exam","The license is taken away for one year","Nothing happens yet","The driver must retake the road test"],"h1":"The first step is a test on paper, not a suspension.","h2":"In Pennsylvania, the first time a driving record reaches 6 or more points, the driver gets a notice to take a written special point exam.","p":"Right. The first time at 6 points means a written point exam."},"es":{"q":"En Pensilvania, ¿qué pasa la primera vez que el historial de un conductor llega a 6 puntos?","o":["El conductor debe tomar un examen escrito especial de puntos","Le quitan la licencia por un año","Todavía no pasa nada","El conductor debe repetir el examen de manejo"],"h1":"El primer paso es un examen en papel, no una suspensión.","h2":"En Pensilvania, la primera vez que el historial llega a 6 puntos o más, el conductor recibe un aviso para tomar un examen escrito especial de puntos.","p":"Correcto. La primera vez con 6 puntos significa un examen escrito de puntos."},"zh":{"q":"在 Pennsylvania，驾驶记录第一次达到 6 分时会怎样？","o":["驾驶人必须参加笔试形式的特别扣分考试（special point exam）","驾照被收回一年","暂时什么都不会发生","驾驶人必须重新参加路考"],"h1":"第一步是一次纸上考试，而不是吊销驾照。","h2":"在 Pennsylvania，驾驶记录第一次达到 6 分或以上时，驾驶人会收到通知，必须参加笔试形式的特别扣分考试。","p":"对。第一次达到 6 分，就要参加笔试形式的扣分考试。"},"vi":{"q":"Ở Pennsylvania, điều gì xảy ra lần đầu tiên hồ sơ lái xe của một tài xế đạt 6 điểm?","o":["Tài xế phải làm một bài thi viết đặc biệt về điểm (special point exam)","Bằng lái bị thu hồi một năm","Chưa có chuyện gì xảy ra","Tài xế phải thi lại phần lái xe trên đường"],"h1":"Bước đầu tiên là một bài thi trên giấy, không phải bị treo bằng lái.","h2":"Ở Pennsylvania, lần đầu tiên hồ sơ lái xe đạt 6 điểm trở lên, tài xế sẽ nhận được thông báo phải làm một bài thi viết đặc biệt về điểm.","p":"Đúng. Lần đầu đạt 6 điểm thì phải làm bài thi viết về điểm."},"tl":{"q":"Sa Pennsylvania, ano ang mangyayari sa unang beses na umabot sa 6 na puntos ang driving record ng isang driver?","o":["Kailangang kumuha ang driver ng nakasulat na special point exam","Kukunin ang lisensya nang isang taon","Wala pang mangyayari","Kailangang ulitin ng driver ang road test"],"h1":"Ang unang hakbang ay isang pagsusulit sa papel, hindi suspensyon.","h2":"Sa Pennsylvania, sa unang beses na umabot sa 6 o higit pang puntos ang driving record, makakatanggap ang driver ng abiso na kumuha ng nakasulat na special point exam.","p":"Tama. Sa unang beses na umabot sa 6 na puntos, may nakasulat na point exam."},"ar":{"q":"في Pennsylvania، ماذا يحدث في المرة الأولى التي يصل فيها سجل السائق إلى 6 نقاط؟","o":["يجب على السائق أن يجري امتحانًا كتابيًا خاصًا بالنقاط (special point exam)","تُسحب الرخصة لمدة سنة واحدة","لا يحدث شيء بعد","يجب على السائق أن يعيد اختبار القيادة على الطريق"],"h1":"الخطوة الأولى امتحان على الورق، وليست إيقاف الرخصة.","h2":"في Pennsylvania، في المرة الأولى التي يصل فيها سجل القيادة إلى 6 نقاط أو أكثر، يحصل السائق على إشعار بأن يجري امتحانًا كتابيًا خاصًا بالنقاط.","p":"صحيح. الوصول إلى 6 نقاط أول مرة يعني امتحانًا كتابيًا بالنقاط."},"ref":{"doc":"PA","page":79}},{"id":"pa-023","scope":"PA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Pennsylvania, how many points come off your record for every 12 months in a row with no violations or suspension?","o":["1 point","2 points","All of your points","3 points"],"h1":"Safe driving for a full year removes a few points, but not all of them.","h2":"In Pennsylvania, 3 points are removed from your driving record for every 12 months in a row without a suspension or a violation that adds points.","p":"Right. Three points come off for each clean year."},"es":{"q":"En Pensilvania, ¿cuántos puntos se quitan de su historial por cada 12 meses seguidos sin infracciones ni suspensión?","o":["1 punto","2 puntos","Todos sus puntos","3 puntos"],"h1":"Manejar con seguridad un año completo quita algunos puntos, pero no todos.","h2":"En Pensilvania, se quitan 3 puntos de su historial por cada 12 meses seguidos sin suspensión ni infracciones que sumen puntos.","p":"Correcto. Se quitan tres puntos por cada año limpio."},"zh":{"q":"在 Pennsylvania，每连续 12 个月没有违规也没有被吊销驾照，记录上会减去几分？","o":["1 分","2 分","全部的分","3 分"],"h1":"安全驾驶整整一年会减去几分，但不是全部。","h2":"在 Pennsylvania，每连续 12 个月没有被吊销驾照、也没有会加分的违规，你的驾驶记录就会减去 3 分。","p":"对。每个没有违规的一年减去三分。"},"vi":{"q":"Ở Pennsylvania, cứ mỗi 12 tháng liên tục không vi phạm và không bị treo bằng lái, hồ sơ của bạn được xóa bao nhiêu điểm?","o":["1 điểm","2 điểm","Tất cả số điểm của bạn","3 điểm"],"h1":"Lái xe an toàn trọn một năm sẽ xóa vài điểm, nhưng không xóa hết.","h2":"Ở Pennsylvania, cứ mỗi 12 tháng liên tục không bị treo bằng lái và không có vi phạm bị cộng điểm, hồ sơ lái xe của bạn được xóa 3 điểm.","p":"Đúng. Mỗi năm không vi phạm được xóa ba điểm."},"tl":{"q":"Sa Pennsylvania, ilang puntos ang inaalis sa record mo sa bawat 12 sunod-sunod na buwan na walang violation o suspensyon?","o":["1 puntos","2 puntos","Lahat ng puntos mo","3 puntos"],"h1":"Ang ligtas na pagmamaneho nang buong isang taon ay nag-aalis ng ilang puntos, pero hindi lahat.","h2":"Sa Pennsylvania, 3 puntos ang inaalis sa driving record mo sa bawat 12 sunod-sunod na buwan na walang suspensyon o violation na nagdadagdag ng puntos.","p":"Tama. Tatlong puntos ang inaalis sa bawat malinis na taon."},"ar":{"q":"في Pennsylvania، كم نقطة تُحذف من سجلك عن كل 12 شهرًا متتالية بلا مخالفات ولا إيقاف للرخصة؟","o":["نقطة واحدة (1)","نقطتان (2)","كل نقاطك","3 نقاط"],"h1":"القيادة الآمنة لسنة كاملة تحذف بعض النقاط، لكن ليس كلها.","h2":"في Pennsylvania، تُحذف 3 نقاط من سجل قيادتك عن كل 12 شهرًا متتالية بلا إيقاف للرخصة وبلا مخالفة تضيف نقاطًا.","p":"صحيح. تُحذف ثلاث نقاط عن كل سنة نظيفة."},"ref":{"doc":"PA","page":79}},{"id":"pa-024","scope":"PA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Pennsylvania, what happens the first time a driver arrested for DUI refuses a breath or blood test?","o":["Only a warning","A one-year license suspension","A 30-day license suspension","Nothing, if found not guilty"],"h1":"By getting a license, you already agreed to be tested.","h2":"In Pennsylvania, refusing a breath or blood test for the first time brings a one-year license suspension, even if the driver is found not guilty of DUI.","p":"Right. A first refusal means a one-year suspension."},"es":{"q":"En Pensilvania, ¿qué pasa la primera vez que un conductor arrestado por manejar bajo los efectos (DUI) se niega a una prueba de aliento o de sangre?","o":["Solo una advertencia","Una suspensión de la licencia por un año","Una suspensión de la licencia por 30 días","Nada, si lo declaran inocente"],"h1":"Al sacar la licencia, usted ya aceptó hacerse la prueba.","h2":"En Pensilvania, negarse por primera vez a una prueba de aliento o de sangre trae una suspensión de la licencia por un año, aunque al conductor lo declaren inocente de DUI.","p":"Correcto. La primera negativa significa un año de suspensión."},"zh":{"q":"在 Pennsylvania，因酒后或药后驾驶（DUI）被逮捕的驾驶人第一次拒绝呼气或验血检测，会怎样？","o":["只是警告","吊销驾照一年","吊销驾照 30 天","如果被判无罪，就什么都没有"],"h1":"你拿到驾照时，就已经同意接受检测了。","h2":"在 Pennsylvania，第一次拒绝呼气或验血检测会被吊销驾照一年，即使驾驶人后来被判 DUI 无罪也一样。","p":"对。第一次拒绝检测会被吊销驾照一年。"},"vi":{"q":"Ở Pennsylvania, điều gì xảy ra lần đầu tiên một tài xế bị bắt vì lái xe khi say (DUI) từ chối thử hơi thở hoặc thử máu?","o":["Chỉ bị cảnh cáo","Bị treo bằng lái một năm","Bị treo bằng lái 30 ngày","Không có gì, nếu được tuyên vô tội"],"h1":"Khi nhận bằng lái, bạn đã đồng ý cho kiểm tra rồi.","h2":"Ở Pennsylvania, từ chối thử hơi thở hoặc thử máu lần đầu sẽ bị treo bằng lái một năm, ngay cả khi tài xế được tuyên vô tội về DUI.","p":"Đúng. Từ chối lần đầu nghĩa là bị treo bằng lái một năm."},"tl":{"q":"Sa Pennsylvania, ano ang mangyayari sa unang beses na tumanggi sa breath o blood test ang driver na inaresto dahil sa DUI?","o":["Babala lang","Isang taong suspensyon ng lisensya","30 araw na suspensyon ng lisensya","Wala, kung mapatunayang hindi nagkasala"],"h1":"Nang kumuha ka ng lisensya, pumayag ka na na ma-test.","h2":"Sa Pennsylvania, ang pagtanggi sa breath o blood test sa unang beses ay may isang taong suspensyon ng lisensya, kahit mapatunayang hindi nagkasala ng DUI ang driver.","p":"Tama. Ang unang pagtanggi ay isang taong suspensyon."},"ar":{"q":"في Pennsylvania، ماذا يحدث في المرة الأولى التي يرفض فيها سائق قُبض عليه بتهمة القيادة تحت تأثير الكحول أو المخدرات (DUI) اختبار النفَس أو الدم؟","o":["إنذار فقط","إيقاف الرخصة لمدة سنة واحدة","إيقاف الرخصة لمدة 30 يومًا","لا شيء، إذا ثبتت براءته"],"h1":"عندما حصلت على الرخصة، كنت قد وافقت مسبقًا على الخضوع للاختبار.","h2":"في Pennsylvania، رفض اختبار النفَس أو الدم لأول مرة يؤدي إلى إيقاف الرخصة لمدة سنة واحدة، حتى لو ثبتت براءة السائق من تهمة DUI.","p":"صحيح. الرفض الأول يعني إيقاف الرخصة لمدة سنة واحدة."},"ref":{"doc":"PA","page":82}},{"id":"pa-025","scope":"PA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Pennsylvania, how must a 5-year-old child ride in a car?","o":["With only a seat belt","On an adult's lap","In a booster seat","In a rear-facing infant seat"],"h1":"Children from age 4 up to age 8 need a seat that raises them up.","h2":"In Pennsylvania, children age 4 and older but under 8 must ride in a booster seat used with a lap and shoulder belt, in the front or back seat.","p":"Right. A 5-year-old rides in a booster seat."},"es":{"q":"En Pensilvania, ¿cómo debe viajar en el carro un niño de 5 años?","o":["Solo con el cinturón de seguridad","En las piernas de un adulto","En un asiento elevado (booster)","En un asiento para bebé mirando hacia atrás"],"h1":"Los niños de 4 a 8 años necesitan un asiento que los suba.","h2":"En Pensilvania, los niños de 4 años o más pero menores de 8 deben viajar en un asiento elevado (booster) con cinturón de cadera y hombro, en el asiento delantero o trasero.","p":"Correcto. Un niño de 5 años viaja en un asiento elevado."},"zh":{"q":"在 Pennsylvania，5 岁的孩子坐车时必须怎样乘坐？","o":["只系安全带","坐在大人腿上","坐增高座椅（booster seat）","坐后向婴儿座椅"],"h1":"4 岁到 8 岁的孩子需要一个能把他们垫高的座椅。","h2":"在 Pennsylvania，4 岁及以上、未满 8 岁的孩子必须坐增高座椅，并配合腰部和肩部安全带使用，坐前排或后排都可以。","p":"对。5 岁的孩子要坐增高座椅。"},"vi":{"q":"Ở Pennsylvania, một trẻ 5 tuổi phải ngồi trên xe như thế nào?","o":["Chỉ thắt dây an toàn","Ngồi trên đùi người lớn","Ngồi ghế nâng (booster seat)","Ngồi ghế em bé quay mặt về phía sau"],"h1":"Trẻ từ 4 tuổi đến 8 tuổi cần một chiếc ghế nâng các em lên cao.","h2":"Ở Pennsylvania, trẻ từ 4 tuổi trở lên nhưng chưa đến 8 tuổi phải ngồi ghế nâng, dùng cùng dây an toàn ngang hông và chéo vai, ở ghế trước hoặc ghế sau.","p":"Đúng. Trẻ 5 tuổi ngồi ghế nâng."},"tl":{"q":"Sa Pennsylvania, paano dapat sumakay sa kotse ang isang batang 5 taong gulang?","o":["Naka-seat belt lang","Nakaupo sa kandungan ng matanda","Sa booster seat","Sa rear-facing na upuan ng sanggol"],"h1":"Ang mga batang 4 hanggang 8 taong gulang ay kailangan ng upuang nagpapataas sa kanila.","h2":"Sa Pennsylvania, ang mga batang 4 taong gulang pataas pero wala pang 8 ay dapat sumakay sa booster seat na may lap at shoulder belt, sa harap o likod na upuan.","p":"Tama. Sa booster seat sumasakay ang batang 5 taong gulang."},"ar":{"q":"في Pennsylvania، كيف يجب أن يركب طفل عمره 5 سنوات في السيارة؟","o":["بحزام الأمان فقط","في حضن شخص بالغ","في مقعد رافع (booster seat)","في مقعد رضيع موجّه إلى الخلف"],"h1":"الأطفال من سن 4 حتى سن 8 يحتاجون إلى مقعد يرفعهم إلى أعلى.","h2":"في Pennsylvania، يجب أن يركب الأطفال من سن 4 فما فوق ودون 8 سنوات في مقعد رافع يُستخدم مع حزام الحِجر والكتف، في المقعد الأمامي أو الخلفي.","p":"صحيح. الطفل الذي عمره 5 سنوات يركب في مقعد رافع."},"ref":{"doc":"PA","page":90}},{"id":"pa-026","scope":"PA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Pennsylvania, when must your headlights be on during the day?","o":["When your wipers are on because of the weather","Only on the turnpike","Only after 5 p.m.","Never during the day"],"h1":"Think about what you turn on when it starts to rain.","h2":"In Pennsylvania, your headlights must be on any time your wipers are in use because of the weather, and also in work zones and when it is hard to see.","p":"Right. Wipers on for weather means headlights on."},"es":{"q":"En Pensilvania, ¿cuándo deben estar encendidas sus luces delanteras durante el día?","o":["Cuando usa los limpiaparabrisas por el mal tiempo","Solo en la autopista de peaje","Solo después de las 5 p.m.","Nunca durante el día"],"h1":"Piense en lo que enciende cuando empieza a llover.","h2":"En Pensilvania, las luces delanteras deben estar encendidas siempre que use los limpiaparabrisas por el mal tiempo, y también en zonas de construcción y cuando se ve poco.","p":"Correcto. Limpiaparabrisas por mal tiempo significa luces encendidas."},"zh":{"q":"在 Pennsylvania，白天什么时候必须打开车头灯？","o":["因为天气原因使用雨刷的时候","只在收费高速公路（turnpike）上","只在下午 5 点以后","白天从来不用"],"h1":"想一想开始下雨时你会打开什么。","h2":"在 Pennsylvania，只要因为天气原因使用雨刷，就必须打开车头灯；在施工区和看不清楚的时候也要打开。","p":"对。因为天气开雨刷，就要开车头灯。"},"vi":{"q":"Ở Pennsylvania, khi nào bạn phải bật đèn pha vào ban ngày?","o":["Khi bạn bật cần gạt nước vì thời tiết","Chỉ trên đường cao tốc thu phí (turnpike)","Chỉ sau 5 giờ chiều","Không bao giờ vào ban ngày"],"h1":"Hãy nghĩ xem bạn bật cái gì khi trời bắt đầu mưa.","h2":"Ở Pennsylvania, bạn phải bật đèn pha bất cứ khi nào dùng cần gạt nước vì thời tiết, và cả trong khu vực công trường và khi khó nhìn thấy.","p":"Đúng. Bật cần gạt nước vì thời tiết thì phải bật đèn pha."},"tl":{"q":"Sa Pennsylvania, kailan dapat nakabukas ang headlights mo sa araw?","o":["Kapag nakabukas ang wipers mo dahil sa panahon","Sa turnpike lang","Pagkalipas lang ng 5 p.m.","Hindi kailanman sa araw"],"h1":"Isipin kung ano ang binubuksan mo kapag nagsisimulang umulan.","h2":"Sa Pennsylvania, dapat nakabukas ang headlights mo tuwing ginagamit mo ang wipers dahil sa panahon, at gayundin sa mga work zone at kapag mahirap makakita.","p":"Tama. Kapag bukas ang wipers dahil sa panahon, bukas din ang headlights."},"ar":{"q":"في Pennsylvania، متى يجب أن تكون المصابيح الأمامية مضاءة أثناء النهار؟","o":["عندما تكون المسّاحات تعمل بسبب الطقس","على الطريق السريع ذي الرسوم (turnpike) فقط","بعد الساعة 5 مساءً فقط","أبدًا أثناء النهار"],"h1":"فكّر فيما تشغّله عندما يبدأ المطر.","h2":"في Pennsylvania، يجب أن تكون المصابيح الأمامية مضاءة في أي وقت تستخدم فيه المسّاحات بسبب الطقس، وكذلك في مناطق العمل وعندما تصعب الرؤية.","p":"صحيح. المسّاحات تعمل بسبب الطقس يعني أن المصابيح الأمامية مضاءة."},"ref":{"doc":"PA","page":40}},{"id":"pa-027","scope":"PA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Pennsylvania, police did not investigate a crash in which someone was hurt. How soon must you send a crash report to PennDOT?","o":["Within 30 days","Within 24 hours","Within 10 days","Within 5 days"],"h1":"It is less than one week.","h2":"In Pennsylvania, if police do not investigate a crash where someone was hurt or killed or a vehicle had to be towed, you must send a Driver's Accident Report to PennDOT within 5 days.","p":"Right. Send the report within 5 days."},"es":{"q":"En Pensilvania, la policía no investigó un choque en el que alguien resultó herido. ¿En qué plazo debe enviar un informe del choque a PennDOT?","o":["En 30 días","En 24 horas","En 10 días","En 5 días"],"h1":"Es menos de una semana.","h2":"En Pensilvania, si la policía no investiga un choque en el que alguien resultó herido o murió, o un vehículo tuvo que ser remolcado, usted debe enviar un informe de accidente del conductor a PennDOT en 5 días.","p":"Correcto. Envíe el informe en 5 días."},"zh":{"q":"在 Pennsylvania，一起有人受伤的车祸没有警察调查。你必须在多长时间内把车祸报告交给 PennDOT？","o":["30 天内","24 小时内","10 天内","5 天内"],"h1":"不到一个星期。","h2":"在 Pennsylvania，如果有人受伤或死亡、或有车辆需要拖走的车祸没有警察调查，你必须在 5 天内把驾驶人事故报告（Driver's Accident Report）交给 PennDOT。","p":"对。要在 5 天内交报告。"},"vi":{"q":"Ở Pennsylvania, cảnh sát không điều tra một vụ tai nạn có người bị thương. Bạn phải gửi báo cáo tai nạn cho PennDOT trong bao lâu?","o":["Trong vòng 30 ngày","Trong vòng 24 giờ","Trong vòng 10 ngày","Trong vòng 5 ngày"],"h1":"Thời gian này ít hơn một tuần.","h2":"Ở Pennsylvania, nếu cảnh sát không điều tra một vụ tai nạn có người bị thương hoặc tử vong, hoặc có xe phải kéo đi, bạn phải gửi Báo cáo Tai nạn của Tài xế (Driver's Accident Report) cho PennDOT trong vòng 5 ngày.","p":"Đúng. Gửi báo cáo trong vòng 5 ngày."},"tl":{"q":"Sa Pennsylvania, hindi inimbestigahan ng pulis ang isang aksidente kung saan may nasaktan. Gaano kabilis mo dapat ipadala ang crash report sa PennDOT?","o":["Sa loob ng 30 araw","Sa loob ng 24 oras","Sa loob ng 10 araw","Sa loob ng 5 araw"],"h1":"Kulang ito sa isang linggo.","h2":"Sa Pennsylvania, kung hindi inimbestigahan ng pulis ang aksidente kung saan may nasaktan o namatay o may sasakyang kinailangang i-tow, dapat mong ipadala ang Driver's Accident Report sa PennDOT sa loob ng 5 araw.","p":"Tama. Ipadala ang report sa loob ng 5 araw."},"ar":{"q":"في Pennsylvania، لم تحقّق الشرطة في حادث أُصيب فيه شخص. خلال كم من الوقت يجب أن ترسل تقرير الحادث إلى PennDOT؟","o":["خلال 30 يومًا","خلال 24 ساعة","خلال 10 أيام","خلال 5 أيام"],"h1":"المدة أقل من أسبوع واحد.","h2":"في Pennsylvania، إذا لم تحقّق الشرطة في حادث أُصيب فيه شخص أو مات أو اضطُرّ فيه إلى سحب مركبة، يجب أن ترسل تقرير السائق عن الحادث (Driver's Accident Report) إلى PennDOT خلال 5 أيام.","p":"صحيح. أرسل التقرير خلال 5 أيام."},"ref":{"doc":"PA","page":81}},{"id":"pa-028","scope":"PA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Pennsylvania, a car is coming toward you at night. Within what distance must you switch to low beams?","o":["100 feet","200 feet","500 feet","1 mile"],"h1":"It is the distance of about one and a half football fields.","h2":"Pennsylvania law requires low beams within 500 feet of an oncoming vehicle, and within 300 feet of a vehicle you are following.","p":"Right. Dim to low beams within 500 feet of an oncoming car."},"es":{"q":"En Pensilvania, un carro viene hacia usted de noche. ¿A qué distancia debe cambiar a luces bajas?","o":["100 pies","200 pies","500 pies","1 milla"],"h1":"Es la distancia de más o menos un campo y medio de fútbol americano.","h2":"La ley de Pensilvania exige luces bajas a menos de 500 pies de un vehículo que viene de frente, y a menos de 300 pies de un vehículo que usted sigue.","p":"Correcto. Cambie a luces bajas a menos de 500 pies de un carro que viene de frente."},"zh":{"q":"在 Pennsylvania，夜里有车迎面开来。你必须在多远距离内改用近光灯？","o":["100 英尺","200 英尺","500 英尺","1 英里"],"h1":"这个距离大约是一个半美式橄榄球场那么长。","h2":"Pennsylvania 法律规定，迎面来车在 500 英尺以内时要用近光灯；跟在别的车后面 300 英尺以内时也要用近光灯。","p":"对。迎面来车在 500 英尺以内时，要改用近光灯。"},"vi":{"q":"Ở Pennsylvania, ban đêm có một xe đang chạy ngược chiều về phía bạn. Bạn phải chuyển sang đèn cốt (đèn chiếu gần) khi xe đó cách bạn bao xa?","o":["100 feet","200 feet","500 feet","1 dặm"],"h1":"Khoảng cách này dài khoảng một sân bóng bầu dục Mỹ rưỡi.","h2":"Luật Pennsylvania bắt buộc dùng đèn cốt khi xe ngược chiều cách bạn trong vòng 500 feet, và khi bạn chạy sau một xe khác trong vòng 300 feet.","p":"Đúng. Chuyển sang đèn cốt khi xe ngược chiều cách bạn trong vòng 500 feet."},"tl":{"q":"Sa Pennsylvania, may kotseng paparating sa iyo sa gabi. Sa loob ng anong layo dapat kang lumipat sa low beam?","o":["100 talampakan","200 talampakan","500 talampakan","1 milya"],"h1":"Halos kasinghaba ito ng isa't kalahating football field.","h2":"Sa batas ng Pennsylvania, dapat kang gumamit ng low beam kapag ang paparating na sasakyan ay nasa loob ng 500 talampakan, at kapag sinusundan mo ang isang sasakyan sa loob ng 300 talampakan.","p":"Tama. Lumipat sa low beam kapag ang paparating na kotse ay nasa loob ng 500 talampakan."},"ar":{"q":"في Pennsylvania، سيارة قادمة نحوك في الليل. على أي مسافة يجب أن تنتقل إلى الأضواء المنخفضة؟","o":["100 قدم","200 قدم","500 قدم","1 ميل"],"h1":"هذه المسافة تساوي تقريبًا طول ملعب ونصف من ملاعب كرة القدم الأمريكية.","h2":"قانون Pennsylvania يوجب استخدام الأضواء المنخفضة عندما تكون السيارة القادمة على بُعد 500 قدم أو أقل، وعندما تسير خلف سيارة على بُعد 300 قدم أو أقل.","p":"صحيح. انتقل إلى الأضواء المنخفضة عندما تكون السيارة القادمة على بُعد 500 قدم أو أقل."},"ref":{"doc":"PA","page":40}},{"id":"pa-029","scope":"PA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Pennsylvania, how much space must you leave when you pass a bicycle?","o":["At least 2 feet","At least 4 feet","At least 8 feet","At least 12 feet"],"h1":"It is more than the 3 feet some states use.","h2":"In Pennsylvania you must leave at least four feet between your vehicle and a bicycle when you pass, and you may cross a double yellow line to do it if it is safe.","p":"Right. Pennsylvania requires at least four feet when passing a bicycle."},"es":{"q":"En Pensilvania, ¿cuánto espacio debe dejar cuando pasa a una bicicleta?","o":["Por lo menos 2 pies","Por lo menos 4 pies","Por lo menos 8 pies","Por lo menos 12 pies"],"h1":"Es más que los 3 pies que usan algunos estados.","h2":"En Pensilvania usted debe dejar por lo menos cuatro pies entre su vehículo y una bicicleta al pasarla, y puede cruzar una doble línea amarilla para hacerlo si es seguro.","p":"Correcto. Pensilvania exige por lo menos cuatro pies al pasar a una bicicleta."},"zh":{"q":"在 Pennsylvania，超过自行车时，你必须留出多少空间？","o":["至少 2 英尺","至少 4 英尺","至少 8 英尺","至少 12 英尺"],"h1":"它比有些州用的 3 英尺多。","h2":"在 Pennsylvania，超过自行车时，你的车和自行车之间必须至少留出四英尺；如果安全，你可以为此越过双黄线。","p":"对。Pennsylvania 规定超过自行车时至少要留四英尺。"},"vi":{"q":"Ở Pennsylvania, khi vượt qua một xe đạp, bạn phải chừa khoảng cách bao nhiêu?","o":["Ít nhất 2 feet","Ít nhất 4 feet","Ít nhất 8 feet","Ít nhất 12 feet"],"h1":"Khoảng cách này nhiều hơn 3 feet mà một số tiểu bang dùng.","h2":"Ở Pennsylvania, khi vượt xe đạp, bạn phải chừa ít nhất bốn feet giữa xe của bạn và xe đạp, và bạn có thể lấn qua vạch đôi màu vàng để làm việc này nếu an toàn.","p":"Đúng. Pennsylvania bắt buộc chừa ít nhất bốn feet khi vượt xe đạp."},"tl":{"q":"Sa Pennsylvania, gaano kalaking espasyo ang dapat mong iwan kapag nilalampasan mo ang bisikleta?","o":["Hindi bababa sa 2 talampakan","Hindi bababa sa 4 talampakan","Hindi bababa sa 8 talampakan","Hindi bababa sa 12 talampakan"],"h1":"Mas malaki ito kaysa sa 3 talampakan na ginagamit ng ilang estado.","h2":"Sa Pennsylvania, dapat kang mag-iwan ng hindi bababa sa apat na talampakan sa pagitan ng sasakyan mo at ng bisikleta kapag nilalampasan mo ito, at puwede kang tumawid sa dobleng dilaw na linya para gawin ito kung ligtas.","p":"Tama. Sa Pennsylvania, hindi bababa sa apat na talampakan kapag nilalampasan ang bisikleta."},"ar":{"q":"في Pennsylvania، ما المسافة التي يجب أن تتركها عندما تتجاوز دراجة هوائية؟","o":["2 قدم على الأقل","4 أقدام على الأقل","8 أقدام على الأقل","12 قدمًا على الأقل"],"h1":"هي أكثر من 3 أقدام التي تستخدمها بعض الولايات.","h2":"في Pennsylvania يجب أن تترك أربعة أقدام على الأقل بين سيارتك والدراجة الهوائية عندما تتجاوزها، ويمكنك أن تعبر الخط الأصفر المزدوج لذلك إذا كان آمنًا.","p":"صحيح. Pennsylvania تشترط أربعة أقدام على الأقل عند تجاوز دراجة هوائية."},"ref":{"doc":"PA","page":92}},{"id":"pa-030","scope":"PA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Pennsylvania, how close to a bridge or tunnel may you pass another vehicle?","o":["Not within 100 feet","Not within 10 feet","Not within 25 feet","Not within 1 mile"],"h1":"The same distance applies to intersections and railroad crossings.","h2":"In Pennsylvania you may not pass another vehicle within 100 feet of a bridge, elevated structure or tunnel.","p":"Right. No passing within 100 feet of a bridge or tunnel."},"es":{"q":"En Pensilvania, ¿qué tan cerca de un puente o túnel puede pasar a otro vehículo?","o":["No a menos de 100 pies","No a menos de 10 pies","No a menos de 25 pies","No a menos de 1 milla"],"h1":"La misma distancia se aplica a intersecciones y cruces de ferrocarril.","h2":"En Pensilvania usted no puede pasar a otro vehículo a menos de 100 pies de un puente, una estructura elevada o un túnel.","p":"Correcto. No se pasa a menos de 100 pies de un puente o túnel."},"zh":{"q":"在 Pennsylvania，离桥或隧道多近时不可以超车？","o":["100 英尺以内不可以","10 英尺以内不可以","25 英尺以内不可以","1 英里以内不可以"],"h1":"路口和铁路道口也用同样的距离。","h2":"在 Pennsylvania，离桥、高架结构或隧道 100 英尺以内时，你不可以超车。","p":"对。离桥或隧道 100 英尺以内不可以超车。"},"vi":{"q":"Ở Pennsylvania, bạn được vượt xe khác khi cách cầu hoặc đường hầm bao xa?","o":["Không gần hơn 100 feet","Không gần hơn 10 feet","Không gần hơn 25 feet","Không gần hơn 1 dặm"],"h1":"Khoảng cách này cũng áp dụng cho giao lộ và chỗ băng qua đường sắt.","h2":"Ở Pennsylvania, bạn không được vượt xe khác khi cách cầu, công trình trên cao hoặc đường hầm trong vòng 100 feet.","p":"Đúng. Không được vượt xe trong vòng 100 feet trước cầu hoặc đường hầm."},"tl":{"q":"Sa Pennsylvania, gaano kalapit sa tulay o tunnel puwede kang lumampas sa ibang sasakyan?","o":["Hindi sa loob ng 100 talampakan","Hindi sa loob ng 10 talampakan","Hindi sa loob ng 25 talampakan","Hindi sa loob ng 1 milya"],"h1":"Pareho ang layong ito para sa mga intersection at tawiran ng tren.","h2":"Sa Pennsylvania, hindi ka puwedeng lumampas sa ibang sasakyan sa loob ng 100 talampakan mula sa tulay, mataas na istruktura, o tunnel.","p":"Tama. Bawal lumampas sa loob ng 100 talampakan mula sa tulay o tunnel."},"ar":{"q":"في Pennsylvania، على أي قُرب من جسر أو نفق يمكنك أن تتجاوز سيارة أخرى؟","o":["ليس على بُعد 100 قدم أو أقل","ليس على بُعد 10 أقدام أو أقل","ليس على بُعد 25 قدمًا أو أقل","ليس على بُعد 1 ميل أو أقل"],"h1":"المسافة نفسها تنطبق على التقاطعات ومعابر السكك الحديدية.","h2":"في Pennsylvania لا يجوز لك أن تتجاوز سيارة أخرى على بُعد 100 قدم أو أقل من جسر أو منشأة مرتفعة أو نفق.","p":"صحيح. لا تجاوز على بُعد 100 قدم أو أقل من جسر أو نفق."},"ref":{"doc":"PA","page":47}},{"id":"pa-031","scope":"PA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Pennsylvania, what is the highest fine for throwing trash from a vehicle onto a road?","o":["$25","$50","$100","$300"],"h1":"It is the largest amount listed.","h2":"In Pennsylvania, throwing trash from a vehicle can bring a fine of up to $300, and the driver can be fined for what passengers throw out.","p":"Right. Littering from a vehicle can cost up to $300."},"es":{"q":"En Pensilvania, ¿cuál es la multa más alta por tirar basura desde un vehículo a la calle?","o":["$25","$50","$100","$300"],"h1":"Es la cantidad más alta de la lista.","h2":"En Pensilvania, tirar basura desde un vehículo puede costar una multa de hasta $300, y al conductor se le puede multar por lo que tiran los pasajeros.","p":"Correcto. Tirar basura desde un vehículo puede costar hasta $300."},"zh":{"q":"在 Pennsylvania，从车里往路上扔垃圾，最高罚款是多少？","o":["$25","$50","$100","$300"],"h1":"它是列出的最大金额。","h2":"在 Pennsylvania，从车里扔垃圾最高可罚 $300，而且乘客扔出去的东西，司机也可能被罚款。","p":"对。从车里乱扔垃圾最高可罚 $300。"},"vi":{"q":"Ở Pennsylvania, mức phạt cao nhất cho việc ném rác từ xe xuống đường là bao nhiêu?","o":["$25","$50","$100","$300"],"h1":"Đó là số tiền lớn nhất trong danh sách.","h2":"Ở Pennsylvania, ném rác từ xe có thể bị phạt đến $300, và người lái có thể bị phạt vì những gì hành khách ném ra.","p":"Đúng. Xả rác từ xe có thể bị phạt đến $300."},"tl":{"q":"Sa Pennsylvania, magkano ang pinakamataas na multa sa pagtatapon ng basura mula sa sasakyan papunta sa kalsada?","o":["$25","$50","$100","$300"],"h1":"Ito ang pinakamalaking halaga sa listahan.","h2":"Sa Pennsylvania, ang pagtatapon ng basura mula sa sasakyan ay puwedeng magmulta ng hanggang $300, at puwedeng multahan ang drayber sa itinatapon ng mga pasahero.","p":"Tama. Ang pagtatapon ng basura mula sa sasakyan ay puwedeng magmulta ng hanggang $300."},"ar":{"q":"في Pennsylvania، ما أعلى غرامة لرمي القمامة من السيارة على الطريق؟","o":["$25","$50","$100","$300"],"h1":"هو أكبر مبلغ في القائمة.","h2":"في Pennsylvania، رمي القمامة من السيارة قد يؤدي إلى غرامة تصل إلى $300، ويمكن تغريم السائق على ما يرميه الركاب.","p":"صحيح. رمي القمامة من السيارة قد يكلّف غرامة تصل إلى $300."},"ref":{"doc":"PA","page":92}},{"id":"ri-001","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, what is the youngest age to get a limited instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"Rhode Island starts later than many states.","h2":"In Rhode Island you can get a limited instruction permit at 16 years old.","p":"Right. The Rhode Island permit starts at 16."},"es":{"q":"En Rhode Island, ¿cuál es la edad mínima para obtener un permiso de instrucción limitado?","o":["14 años","15 años","16 años","17 años"],"h1":"Rhode Island empieza más tarde que muchos estados.","h2":"En Rhode Island usted puede obtener un permiso de instrucción limitado a los 16 años.","p":"Correcto. El permiso en Rhode Island empieza a los 16."},"zh":{"q":"在 Rhode Island，最小几岁可以拿到受限学习驾照（limited instruction permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"Rhode Island 开始得比很多州晚。","h2":"在 Rhode Island，你 16 岁就可以拿到受限学习驾照。","p":"对。Rhode Island 的学习驾照从 16 岁开始。"},"vi":{"q":"Ở Rhode Island, tuổi nhỏ nhất để lấy giấy phép tập lái có giới hạn (limited instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Rhode Island bắt đầu muộn hơn nhiều tiểu bang khác.","h2":"Ở Rhode Island, bạn có thể lấy giấy phép tập lái có giới hạn khi 16 tuổi.","p":"Đúng. Giấy phép tập lái ở Rhode Island bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Rhode Island, ano ang pinakabatang edad para makakuha ng limited instruction permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Mas huli nagsisimula ang Rhode Island kaysa sa maraming estado.","h2":"Sa Rhode Island, puwede kang kumuha ng limited instruction permit sa edad na 16.","p":"Tama. Nagsisimula ang permit sa Rhode Island sa edad na 16."},"ar":{"q":"في Rhode Island، ما أصغر عمر للحصول على تصريح تعلّم محدود (limited instruction permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"تبدأ Rhode Island في عمر أكبر من ولايات كثيرة.","h2":"في Rhode Island يمكنك الحصول على تصريح تعلّم محدود في عمر 16 سنة.","p":"صحيح. يبدأ التصريح في Rhode Island في عمر 16 سنة."},"ref":{"doc":"RI","page":10}},{"id":"ri-002","scope":"RI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Rhode Island, how long is the driver education course a teen must finish for a permit?","o":["10 hours","33 hours","6 hours","100 hours"],"h1":"It is a little more than thirty hours.","h2":"A Rhode Island teen must complete a 33-hour driver education course to qualify for a limited instruction permit.","p":"Right. The course is 33 hours."},"es":{"q":"En Rhode Island, ¿cuántas horas dura el curso de educación vial que un adolescente debe terminar para el permiso?","o":["10 horas","33 horas","6 horas","100 horas"],"h1":"Son un poco más de treinta horas.","h2":"Un adolescente en Rhode Island debe completar un curso de educación vial de 33 horas para obtener el permiso de instrucción limitado.","p":"Correcto. El curso es de 33 horas."},"zh":{"q":"在 Rhode Island，青少年为了拿学习驾照，必须完成多长的驾驶教育课程？","o":["10 小时","33 小时","6 小时","100 小时"],"h1":"它比三十小时多一点。","h2":"在 Rhode Island，青少年必须完成 33 小时的驾驶教育课程，才有资格拿受限学习驾照。","p":"对。这个课程是 33 小时。"},"vi":{"q":"Ở Rhode Island, khóa học lái xe mà thiếu niên phải hoàn thành để lấy giấy phép tập lái dài bao lâu?","o":["10 giờ","33 giờ","6 giờ","100 giờ"],"h1":"Nó hơn ba mươi giờ một chút.","h2":"Thiếu niên ở Rhode Island phải hoàn thành khóa học lái xe 33 giờ để đủ điều kiện lấy giấy phép tập lái có giới hạn.","p":"Đúng. Khóa học dài 33 giờ."},"tl":{"q":"Sa Rhode Island, gaano kahaba ang driver education course na dapat tapusin ng teenager para sa permit?","o":["10 oras","33 oras","6 na oras","100 oras"],"h1":"Medyo higit ito sa tatlumpung oras.","h2":"Ang teenager sa Rhode Island ay dapat tumapos ng 33 oras na driver education course para maging kwalipikado sa limited instruction permit.","p":"Tama. 33 oras ang course."},"ar":{"q":"في Rhode Island، كم مدة دورة تعليم القيادة التي يجب أن يكملها المراهق للحصول على التصريح؟","o":["10 ساعات","33 ساعة","6 ساعات","100 ساعة"],"h1":"هي أكثر قليلاً من ثلاثين ساعة.","h2":"يجب على المراهق في Rhode Island أن يكمل دورة تعليم قيادة مدتها 33 ساعة ليكون مؤهلاً للحصول على تصريح التعلّم المحدود.","p":"صحيح. مدة الدورة 33 ساعة."},"ref":{"doc":"RI","page":10}},{"id":"ri-003","scope":"RI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Rhode Island, where can a teen take the permit knowledge test?","o":["At any police station","Online at home","At the high school office","In the CCRI driver education course, or at the DMV in Cranston"],"h1":"One place is a college, the other is the DMV headquarters.","h2":"In Rhode Island the permit knowledge test is part of the CCRI driver education course; otherwise you take it at the DMV headquarters in Cranston.","p":"Right. CCRI or the Cranston DMV."},"es":{"q":"En Rhode Island, ¿dónde puede un adolescente presentar el examen de conocimientos para el permiso?","o":["En cualquier estación de policía","En línea desde la casa","En la oficina de la escuela secundaria","En el curso de educación vial de CCRI, o en el DMV de Cranston"],"h1":"Un lugar es un colegio comunitario y el otro es la sede del DMV.","h2":"En Rhode Island el examen de conocimientos para el permiso es parte del curso de educación vial de CCRI; si no, se presenta en la sede del DMV en Cranston.","p":"Correcto. CCRI o el DMV de Cranston."},"zh":{"q":"在 Rhode Island，青少年可以在哪里参加学习驾照的知识考试？","o":["在任何一个警察局","在家里上网考","在高中办公室","在 CCRI 驾驶教育课程里，或在 Cranston 的 DMV"],"h1":"一个地方是一所学院，另一个是 DMV 总部。","h2":"在 Rhode Island，学习驾照知识考试是 CCRI 驾驶教育课程的一部分；不然你要去 Cranston 的 DMV 总部考试。","p":"对。在 CCRI 或 Cranston 的 DMV。"},"vi":{"q":"Ở Rhode Island, thiếu niên có thể thi kiến thức để lấy giấy phép tập lái ở đâu?","o":["Ở bất kỳ đồn cảnh sát nào","Trên mạng tại nhà","Ở văn phòng trường trung học","Trong khóa học lái xe CCRI, hoặc tại DMV ở Cranston"],"h1":"Một nơi là trường cao đẳng, nơi kia là trụ sở DMV.","h2":"Ở Rhode Island, bài thi kiến thức để lấy giấy phép tập lái là một phần của khóa học lái xe CCRI; nếu không, bạn thi tại trụ sở DMV ở Cranston.","p":"Đúng. CCRI hoặc DMV ở Cranston."},"tl":{"q":"Sa Rhode Island, saan puwedeng kumuha ang teenager ng knowledge test para sa permit?","o":["Sa kahit anong police station","Online sa bahay","Sa opisina ng high school","Sa CCRI driver education course, o sa DMV sa Cranston"],"h1":"Ang isang lugar ay isang kolehiyo, ang isa ay ang punong-tanggapan ng DMV.","h2":"Sa Rhode Island, bahagi ng CCRI driver education course ang knowledge test para sa permit; kung hindi, kukunin mo ito sa punong-tanggapan ng DMV sa Cranston.","p":"Tama. Sa CCRI o sa DMV sa Cranston."},"ar":{"q":"في Rhode Island، أين يمكن للمراهق أن يؤدي اختبار المعرفة للحصول على التصريح؟","o":["في أي مركز شرطة","عبر الإنترنت في البيت","في مكتب المدرسة الثانوية","في دورة تعليم القيادة في CCRI، أو في DMV في Cranston"],"h1":"أحد المكانين كلية، والآخر هو المقر الرئيسي لـ DMV.","h2":"في Rhode Island يكون اختبار المعرفة للتصريح جزءاً من دورة تعليم القيادة في CCRI؛ وإلا فإنك تؤديه في المقر الرئيسي لـ DMV في Cranston.","p":"صحيح. في CCRI أو في DMV في Cranston."},"ref":{"doc":"RI","page":10}},{"id":"ri-004","scope":"RI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Rhode Island, who must come to the DMV to co-sign a teen's permit application?","o":["A parent, guardian or adult spouse","A teacher","Any adult friend","No one"],"h1":"It is an adult who is legally responsible for the teen.","h2":"In Rhode Island a parent, guardian or adult spouse must come to the DMV and co-sign the teen's permit application.","p":"Right. A parent, guardian or adult spouse signs too."},"es":{"q":"En Rhode Island, ¿quién debe ir al DMV a firmar junto con el adolescente la solicitud del permiso?","o":["Su padre, madre, tutor o cónyuge adulto","Un maestro","Cualquier amigo adulto","Nadie"],"h1":"Es un adulto que responde legalmente por el adolescente.","h2":"En Rhode Island su padre, madre, tutor o cónyuge adulto debe ir al DMV y firmar también la solicitud del permiso del adolescente.","p":"Correcto. Su padre, madre, tutor o cónyuge adulto también firma."},"zh":{"q":"在 Rhode Island，谁必须到 DMV 在青少年的学习驾照申请上共同签名？","o":["父母、监护人或成年配偶","老师","任何成年朋友","不需要任何人"],"h1":"这个人是对青少年负有法律责任的成年人。","h2":"在 Rhode Island，父母、监护人或成年配偶必须到 DMV，在青少年的学习驾照申请上共同签名。","p":"对。父母、监护人或成年配偶也要签名。"},"vi":{"q":"Ở Rhode Island, ai phải đến DMV để cùng ký đơn xin giấy phép tập lái của thiếu niên?","o":["Cha mẹ, người giám hộ hoặc vợ/chồng đã trưởng thành","Một giáo viên","Bất kỳ người bạn trưởng thành nào","Không ai cả"],"h1":"Đó là một người lớn chịu trách nhiệm pháp lý cho thiếu niên.","h2":"Ở Rhode Island, cha mẹ, người giám hộ hoặc vợ/chồng đã trưởng thành phải đến DMV và cùng ký đơn xin giấy phép tập lái của thiếu niên.","p":"Đúng. Cha mẹ, người giám hộ hoặc vợ/chồng đã trưởng thành cũng ký."},"tl":{"q":"Sa Rhode Island, sino ang dapat pumunta sa DMV para pumirma rin sa aplikasyon ng teenager para sa permit?","o":["Isang magulang, guardian, o asawang nasa hustong gulang","Isang guro","Kahit sinong kaibigang nasa hustong gulang","Wala"],"h1":"Isa itong adult na may legal na pananagutan sa teenager.","h2":"Sa Rhode Island, ang isang magulang, guardian, o asawang nasa hustong gulang ay dapat pumunta sa DMV at pumirma rin sa aplikasyon ng teenager para sa permit.","p":"Tama. Pumipirma rin ang magulang, guardian, o asawang nasa hustong gulang."},"ar":{"q":"في Rhode Island، من يجب أن يحضر إلى DMV ليوقّع مع المراهق على طلب التصريح؟","o":["أحد الوالدين أو الوصي أو الزوج أو الزوجة البالغ","معلّم","أي صديق بالغ","لا أحد"],"h1":"هو شخص بالغ مسؤول قانونياً عن المراهق.","h2":"في Rhode Island يجب أن يحضر أحد الوالدين أو الوصي أو الزوج أو الزوجة البالغ إلى DMV ويوقّع مع المراهق على طلب التصريح.","p":"صحيح. يوقّع أيضاً أحد الوالدين أو الوصي أو الزوج أو الزوجة البالغ."},"ref":{"doc":"RI","page":11}},{"id":"ri-005","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, how long must a teen hold the instruction permit before a limited provisional license?","o":["30 days","3 months","6 months","1 year"],"h1":"It is half a year.","h2":"A Rhode Island teen must hold the instruction permit for at least six months before applying for a limited provisional license.","p":"Right. You hold the permit six months."},"es":{"q":"En Rhode Island, ¿cuánto tiempo debe tener un adolescente el permiso de instrucción antes de la licencia provisional limitada?","o":["30 días","3 meses","6 meses","1 año"],"h1":"Es medio año.","h2":"Un adolescente en Rhode Island debe tener el permiso de instrucción por lo menos seis meses antes de solicitar la licencia provisional limitada.","p":"Correcto. Tiene el permiso seis meses."},"zh":{"q":"在 Rhode Island，青少年拿受限试用驾照（limited provisional license）前，必须持有学习驾照多久？","o":["30 天","3 个月","6 个月","1 年"],"h1":"它是半年。","h2":"在 Rhode Island，青少年必须持有学习驾照至少六个月，才能申请受限试用驾照。","p":"对。学习驾照要持有六个月。"},"vi":{"q":"Ở Rhode Island, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái tạm thời có giới hạn (limited provisional license)?","o":["30 ngày","3 tháng","6 tháng","1 năm"],"h1":"Đó là nửa năm.","h2":"Thiếu niên ở Rhode Island phải giữ giấy phép tập lái ít nhất sáu tháng trước khi xin bằng lái tạm thời có giới hạn.","p":"Đúng. Bạn giữ giấy phép tập lái sáu tháng."},"tl":{"q":"Sa Rhode Island, gaano katagal dapat hawak ng teenager ang instruction permit bago makakuha ng limited provisional license?","o":["30 araw","3 buwan","6 na buwan","1 taon"],"h1":"Kalahating taon ito.","h2":"Ang teenager sa Rhode Island ay dapat humawak ng instruction permit nang hindi bababa sa anim na buwan bago mag-apply para sa limited provisional license.","p":"Tama. Hawak mo ang permit nang anim na buwan."},"ar":{"q":"في Rhode Island، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل الحصول على رخصة مؤقتة محدودة (limited provisional license)؟","o":["30 يوماً","3 أشهر","6 أشهر","سنة واحدة"],"h1":"هي نصف سنة.","h2":"يجب على المراهق في Rhode Island أن يحمل تصريح التعلّم ستة أشهر على الأقل قبل أن يتقدّم بطلب رخصة مؤقتة محدودة.","p":"صحيح. تحمل التصريح ستة أشهر."},"ref":{"doc":"RI","page":12}},{"id":"ri-006","scope":"RI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Rhode Island, how many hours of supervised driving must a parent certify for a teen under 18?","o":["20 hours","50 hours","30 hours","100 hours"],"h1":"It is half of one hundred.","h2":"A Rhode Island parent or guardian must sign a statement that a teen under 18 has driven at least 50 supervised hours.","p":"Right. The teen needs 50 hours."},"es":{"q":"En Rhode Island, ¿cuántas horas de manejo supervisado debe certificar un padre para un adolescente menor de 18?","o":["20 horas","50 horas","30 horas","100 horas"],"h1":"Es la mitad de cien.","h2":"En Rhode Island, el padre, la madre o el tutor debe firmar que el adolescente menor de 18 ha manejado por lo menos 50 horas supervisadas.","p":"Correcto. El adolescente necesita 50 horas."},"zh":{"q":"在 Rhode Island，对 18 岁以下的青少年，父母必须证明他有多少小时有人监督的驾驶？","o":["20 小时","50 小时","30 小时","100 小时"],"h1":"它是一百的一半。","h2":"在 Rhode Island，父母或监护人必须签一份声明，证明 18 岁以下的青少年至少有 50 小时有人监督的驾驶。","p":"对。青少年需要 50 小时。"},"vi":{"q":"Ở Rhode Island, cha mẹ phải xác nhận bao nhiêu giờ lái xe có giám sát cho thiếu niên dưới 18 tuổi?","o":["20 giờ","50 giờ","30 giờ","100 giờ"],"h1":"Đó là một nửa của một trăm.","h2":"Ở Rhode Island, cha mẹ hoặc người giám hộ phải ký giấy xác nhận rằng thiếu niên dưới 18 tuổi đã lái xe có giám sát ít nhất 50 giờ.","p":"Đúng. Thiếu niên cần 50 giờ."},"tl":{"q":"Sa Rhode Island, ilang oras ng supervised driving ang dapat patunayan ng magulang para sa teenager na wala pang 18?","o":["20 oras","50 oras","30 oras","100 oras"],"h1":"Kalahati ito ng isang daan.","h2":"Sa Rhode Island, ang magulang o guardian ay dapat pumirma ng pahayag na ang teenager na wala pang 18 ay nakapagmaneho nang hindi bababa sa 50 oras na may gumagabay.","p":"Tama. Kailangan ng teenager ng 50 oras."},"ar":{"q":"في Rhode Island، كم ساعة من القيادة تحت الإشراف يجب أن يشهد بها أحد الوالدين لمراهق عمره أقل من 18 سنة؟","o":["20 ساعة","50 ساعة","30 ساعة","100 ساعة"],"h1":"هي نصف المئة.","h2":"في Rhode Island يجب على أحد الوالدين أو الوصي أن يوقّع بياناً بأن المراهق الذي عمره أقل من 18 سنة قاد 50 ساعة على الأقل تحت الإشراف.","p":"صحيح. يحتاج المراهق إلى 50 ساعة."},"ref":{"doc":"RI","page":12}},{"id":"ri-007","scope":"RI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Rhode Island, how many of the 50 supervised hours must be at night?","o":["None","5 hours","25 hours","10 hours"],"h1":"It is one fifth of the total.","h2":"At least 10 of the 50 supervised driving hours for a Rhode Island teen must be at night.","p":"Right. Ten hours at night."},"es":{"q":"En Rhode Island, ¿cuántas de las 50 horas supervisadas deben ser de noche?","o":["Ninguna","5 horas","25 horas","10 horas"],"h1":"Es la quinta parte del total.","h2":"Por lo menos 10 de las 50 horas de manejo supervisado de un adolescente en Rhode Island deben ser de noche.","p":"Correcto. Diez horas de noche."},"zh":{"q":"在 Rhode Island，这 50 小时有人监督的驾驶中，必须有多少小时在夜间？","o":["不需要","5 小时","25 小时","10 小时"],"h1":"它是总数的五分之一。","h2":"在 Rhode Island，青少年 50 小时有人监督的驾驶中，至少 10 小时必须在夜间。","p":"对。夜间 10 小时。"},"vi":{"q":"Ở Rhode Island, trong 50 giờ lái xe có giám sát, bao nhiêu giờ phải là ban đêm?","o":["Không giờ nào","5 giờ","25 giờ","10 giờ"],"h1":"Đó là một phần năm của tổng số.","h2":"Ít nhất 10 trong 50 giờ lái xe có giám sát của thiếu niên ở Rhode Island phải là ban đêm.","p":"Đúng. Mười giờ vào ban đêm."},"tl":{"q":"Sa Rhode Island, ilan sa 50 oras ng supervised driving ang dapat sa gabi?","o":["Wala","5 oras","25 oras","10 oras"],"h1":"Isang-ikalima ito ng kabuuan.","h2":"Hindi bababa sa 10 sa 50 oras ng supervised driving ng teenager sa Rhode Island ang dapat sa gabi.","p":"Tama. Sampung oras sa gabi."},"ar":{"q":"في Rhode Island، كم ساعة من الـ 50 ساعة تحت الإشراف يجب أن تكون في الليل؟","o":["ولا ساعة","5 ساعات","25 ساعة","10 ساعات"],"h1":"هي خُمس المجموع.","h2":"يجب أن تكون 10 ساعات على الأقل من الـ 50 ساعة من القيادة تحت الإشراف للمراهق في Rhode Island في الليل.","p":"صحيح. عشر ساعات في الليل."},"ref":{"doc":"RI","page":12}},{"id":"ri-008","scope":"RI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Rhode Island, during which hours may a limited provisional licensee not drive without a qualified adult?","o":["1 a.m. to 5 a.m.","9 p.m. to 5 a.m.","11 p.m. to 6 a.m.","Midnight to 6 a.m."],"h1":"It starts one hour after midnight.","h2":"A Rhode Island limited provisional licensee may not drive between 1 a.m. and 5 a.m. unless a qualified adult is in the car.","p":"Right. The limit is 1 a.m. to 5 a.m."},"es":{"q":"En Rhode Island, ¿en qué horas no puede manejar sin un adulto calificado quien tiene licencia provisional limitada?","o":["De 1 a.m. a 5 a.m.","De 9 p.m. a 5 a.m.","De 11 p.m. a 6 a.m.","De medianoche a 6 a.m."],"h1":"Empieza una hora después de la medianoche.","h2":"Quien tiene licencia provisional limitada en Rhode Island no puede manejar entre la 1 a.m. y las 5 a.m., salvo que vaya un adulto calificado en el carro.","p":"Correcto. El límite es de 1 a.m. a 5 a.m."},"zh":{"q":"在 Rhode Island，持受限试用驾照的人在哪个时间段不能在没有合格成年人陪同的情况下开车？","o":["凌晨 1 点到 5 点","晚上 9 点到早上 5 点","晚上 11 点到早上 6 点","午夜到早上 6 点"],"h1":"它从午夜后一小时开始。","h2":"在 Rhode Island，持受限试用驾照的人在凌晨 1 点到 5 点之间不能开车，除非车里有一位合格的成年人。","p":"对。限制时间是凌晨 1 点到 5 点。"},"vi":{"q":"Ở Rhode Island, người có bằng lái tạm thời có giới hạn không được lái xe mà không có người lớn đủ điều kiện đi cùng trong những giờ nào?","o":["1 giờ sáng đến 5 giờ sáng","9 giờ tối đến 5 giờ sáng","11 giờ tối đến 6 giờ sáng","Nửa đêm đến 6 giờ sáng"],"h1":"Nó bắt đầu một giờ sau nửa đêm.","h2":"Người có bằng lái tạm thời có giới hạn ở Rhode Island không được lái xe từ 1 giờ sáng đến 5 giờ sáng, trừ khi có một người lớn đủ điều kiện ngồi trong xe.","p":"Đúng. Giới hạn là từ 1 giờ sáng đến 5 giờ sáng."},"tl":{"q":"Sa Rhode Island, sa anong mga oras hindi puwedeng magmaneho ang may limited provisional license nang walang kasamang qualified adult?","o":["1 a.m. hanggang 5 a.m.","9 p.m. hanggang 5 a.m.","11 p.m. hanggang 6 a.m.","Hatinggabi hanggang 6 a.m."],"h1":"Nagsisimula ito isang oras pagkatapos ng hatinggabi.","h2":"Ang may limited provisional license sa Rhode Island ay hindi puwedeng magmaneho mula 1 a.m. hanggang 5 a.m. maliban kung may qualified adult sa kotse.","p":"Tama. Ang limitasyon ay 1 a.m. hanggang 5 a.m."},"ar":{"q":"في Rhode Island، في أي ساعات لا يجوز لحامل الرخصة المؤقتة المحدودة أن يقود بدون شخص بالغ مؤهل؟","o":["من 1 صباحاً إلى 5 صباحاً","من 9 مساءً إلى 5 صباحاً","من 11 مساءً إلى 6 صباحاً","من منتصف الليل إلى 6 صباحاً"],"h1":"تبدأ بعد منتصف الليل بساعة واحدة.","h2":"لا يجوز لحامل الرخصة المؤقتة المحدودة في Rhode Island أن يقود بين 1 صباحاً و5 صباحاً إلا إذا كان معه في السيارة شخص بالغ مؤهل.","p":"صحيح. القيد من 1 صباحاً إلى 5 صباحاً."},"ref":{"doc":"RI","page":14}},{"id":"ri-009","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, which trip is allowed alone during the 1 a.m. to 5 a.m. limit?","o":["Driving friends home from a party","Going out for food","Driving to or from work","Practicing on empty roads"],"h1":"Think of a trip you need for your job.","h2":"A Rhode Island limited provisional licensee may drive alone between 1 a.m. and 5 a.m. when driving to or from work.","p":"Right. A trip to or from work is allowed."},"es":{"q":"En Rhode Island, ¿qué viaje se permite manejar solo durante el límite de 1 a.m. a 5 a.m.?","o":["Llevar a los amigos a casa después de una fiesta","Salir a comprar comida","Manejar hacia o desde el trabajo","Practicar en calles vacías"],"h1":"Piense en un viaje que necesita para su empleo.","h2":"Quien tiene licencia provisional limitada en Rhode Island puede manejar solo entre la 1 a.m. y las 5 a.m. cuando va hacia o desde el trabajo.","p":"Correcto. Se permite ir o volver del trabajo."},"zh":{"q":"在 Rhode Island，在凌晨 1 点到 5 点的限制时间里，哪一种行程可以一个人开车？","o":["开车送朋友从聚会回家","出去买吃的","开车上班或下班","在空的马路上练习"],"h1":"想一想你工作需要的行程。","h2":"在 Rhode Island，持受限试用驾照的人在凌晨 1 点到 5 点之间，如果是开车上班或下班，可以一个人开车。","p":"对。上班或下班的行程是允许的。"},"vi":{"q":"Ở Rhode Island, trong giờ giới hạn từ 1 giờ sáng đến 5 giờ sáng, chuyến đi nào được phép lái một mình?","o":["Chở bạn bè từ tiệc về nhà","Đi ra ngoài mua đồ ăn","Lái xe đi làm hoặc đi làm về","Tập lái trên đường vắng"],"h1":"Hãy nghĩ đến chuyến đi bạn cần cho công việc.","h2":"Người có bằng lái tạm thời có giới hạn ở Rhode Island được lái một mình từ 1 giờ sáng đến 5 giờ sáng khi lái xe đi làm hoặc đi làm về.","p":"Đúng. Chuyến đi làm hoặc đi làm về được phép."},"tl":{"q":"Sa Rhode Island, aling biyahe ang puwedeng mag-isa sa oras ng limitasyon mula 1 a.m. hanggang 5 a.m.?","o":["Paghatid sa mga kaibigan pauwi mula sa party","Paglabas para bumili ng pagkain","Pagmamaneho papunta o pauwi galing sa trabaho","Pag-eensayo sa mga bakanteng kalsada"],"h1":"Isipin ang biyaheng kailangan mo para sa trabaho.","h2":"Ang may limited provisional license sa Rhode Island ay puwedeng magmaneho nang mag-isa mula 1 a.m. hanggang 5 a.m. kapag papunta o pauwi galing sa trabaho.","p":"Tama. Pinapayagan ang biyahe papunta o pauwi galing sa trabaho."},"ar":{"q":"في Rhode Island، أي رحلة مسموح بها وحدك خلال قيد الساعات من 1 صباحاً إلى 5 صباحاً؟","o":["توصيل الأصدقاء إلى بيوتهم من حفلة","الخروج لشراء طعام","القيادة إلى العمل أو منه","التدرّب على طرق فارغة"],"h1":"فكّر في رحلة تحتاجها لعملك.","h2":"يجوز لحامل الرخصة المؤقتة المحدودة في Rhode Island أن يقود وحده بين 1 صباحاً و5 صباحاً عندما يقود إلى العمل أو منه.","p":"صحيح. الرحلة إلى العمل أو منه مسموح بها."},"ref":{"doc":"RI","page":14}},{"id":"ri-010","scope":"RI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Rhode Island, how many passengers under 21 may a new limited provisional licensee carry?","o":["None","One","Two","Three"],"h1":"Count on one hand, and use just one finger.","h2":"During the first 12 months of a Rhode Island limited provisional license, the driver may carry no more than one passenger under 21, not counting immediate family.","p":"Right. Only one passenger under 21."},"es":{"q":"En Rhode Island, ¿cuántos pasajeros menores de 21 puede llevar quien acaba de recibir la licencia provisional limitada?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Cuente con una mano, y use solo un dedo.","h2":"Durante los primeros 12 meses de la licencia provisional limitada en Rhode Island, el conductor puede llevar como máximo a un pasajero menor de 21, sin contar a su familia inmediata.","p":"Correcto. Solo un pasajero menor de 21."},"zh":{"q":"在 Rhode Island，刚拿到受限试用驾照的人可以载多少名 21 岁以下的乘客？","o":["一个都不能","一名","两名","三名"],"h1":"用一只手数，只用一根手指。","h2":"在 Rhode Island，拿到受限试用驾照的头 12 个月里，司机最多只能载一名 21 岁以下的乘客，直系亲属不算在内。","p":"对。只能载一名 21 岁以下的乘客。"},"vi":{"q":"Ở Rhode Island, người mới có bằng lái tạm thời có giới hạn được chở bao nhiêu hành khách dưới 21 tuổi?","o":["Không ai","Một người","Hai người","Ba người"],"h1":"Đếm trên một bàn tay, và chỉ dùng một ngón.","h2":"Trong 12 tháng đầu của bằng lái tạm thời có giới hạn ở Rhode Island, người lái chỉ được chở tối đa một hành khách dưới 21 tuổi, không tính người thân trong gia đình.","p":"Đúng. Chỉ một hành khách dưới 21 tuổi."},"tl":{"q":"Sa Rhode Island, ilang pasaherong wala pang 21 ang puwedeng isakay ng bagong may limited provisional license?","o":["Wala","Isa","Dalawa","Tatlo"],"h1":"Magbilang sa isang kamay, at isang daliri lang ang gamitin.","h2":"Sa unang 12 buwan ng limited provisional license sa Rhode Island, hindi puwedeng magsakay ang driver ng higit sa isang pasaherong wala pang 21, hindi kasama ang malapit na pamilya.","p":"Tama. Isang pasaherong wala pang 21 lang."},"ar":{"q":"في Rhode Island، كم راكباً عمره أقل من 21 سنة يمكن أن يحمل حامل الرخصة المؤقتة المحدودة الجديد؟","o":["ولا راكب","راكب واحد","راكبان","ثلاثة ركاب"],"h1":"عُدّ على يد واحدة، واستخدم إصبعاً واحداً فقط.","h2":"خلال أول 12 شهراً من الرخصة المؤقتة المحدودة في Rhode Island، لا يجوز للسائق أن يحمل أكثر من راكب واحد عمره أقل من 21 سنة، دون احتساب أفراد الأسرة المباشرين.","p":"صحيح. راكب واحد فقط عمره أقل من 21 سنة."},"ref":{"doc":"RI","page":14}},{"id":"ri-011","scope":"RI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Rhode Island, how long does the passenger limit last on a limited provisional license?","o":["1 month","3 months","6 months","The first 12 months"],"h1":"It lasts a full year.","h2":"The Rhode Island passenger limit applies during the first 12 months of the limited provisional license.","p":"Right. It lasts the first 12 months."},"es":{"q":"En Rhode Island, ¿cuánto dura el límite de pasajeros en la licencia provisional limitada?","o":["1 mes","3 meses","6 meses","Los primeros 12 meses"],"h1":"Dura un año completo.","h2":"El límite de pasajeros en Rhode Island se aplica durante los primeros 12 meses de la licencia provisional limitada.","p":"Correcto. Dura los primeros 12 meses."},"zh":{"q":"在 Rhode Island，受限试用驾照的乘客限制持续多久？","o":["1 个月","3 个月","6 个月","最初的 12 个月"],"h1":"它持续整整一年。","h2":"在 Rhode Island，乘客限制适用于受限试用驾照的最初 12 个月。","p":"对。它持续最初的 12 个月。"},"vi":{"q":"Ở Rhode Island, giới hạn hành khách của bằng lái tạm thời có giới hạn kéo dài bao lâu?","o":["1 tháng","3 tháng","6 tháng","12 tháng đầu tiên"],"h1":"Nó kéo dài trọn một năm.","h2":"Giới hạn hành khách ở Rhode Island áp dụng trong 12 tháng đầu tiên của bằng lái tạm thời có giới hạn.","p":"Đúng. Nó kéo dài 12 tháng đầu tiên."},"tl":{"q":"Sa Rhode Island, gaano katagal ang limitasyon sa pasahero sa limited provisional license?","o":["1 buwan","3 buwan","6 na buwan","Ang unang 12 buwan"],"h1":"Tumatagal ito ng isang buong taon.","h2":"Ang limitasyon sa pasahero sa Rhode Island ay para sa unang 12 buwan ng limited provisional license.","p":"Tama. Tumatagal ito ng unang 12 buwan."},"ar":{"q":"في Rhode Island، كم يستمر قيد الركاب على الرخصة المؤقتة المحدودة؟","o":["شهر واحد","3 أشهر","6 أشهر","أول 12 شهراً"],"h1":"يستمر سنة كاملة.","h2":"ينطبق قيد الركاب في Rhode Island خلال أول 12 شهراً من الرخصة المؤقتة المحدودة.","p":"صحيح. يستمر أول 12 شهراً."},"ref":{"doc":"RI","page":14}},{"id":"ri-012","scope":"RI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Rhode Island, which young passengers do not count toward the provisional passenger limit?","o":["Immediate family members","Classmates","Teammates","Coworkers"],"h1":"Think of brothers and sisters.","h2":"In Rhode Island, immediate family members do not count toward the one-passenger limit on a limited provisional license.","p":"Right. Immediate family does not count."},"es":{"q":"En Rhode Island, ¿qué pasajeros jóvenes no cuentan en el límite de pasajeros de la licencia provisional?","o":["Los familiares inmediatos","Los compañeros de clase","Los compañeros de equipo","Los compañeros de trabajo"],"h1":"Piense en hermanos y hermanas.","h2":"En Rhode Island, los familiares inmediatos no cuentan en el límite de un pasajero de la licencia provisional limitada.","p":"Correcto. La familia inmediata no cuenta."},"zh":{"q":"在 Rhode Island，哪些年轻乘客不算在试用驾照的乘客限制里？","o":["直系亲属","同学","队友","同事"],"h1":"想一想兄弟姐妹。","h2":"在 Rhode Island，直系亲属不算在受限试用驾照的一名乘客限制里。","p":"对。直系亲属不算。"},"vi":{"q":"Ở Rhode Island, những hành khách trẻ nào không bị tính vào giới hạn hành khách của bằng lái tạm thời?","o":["Người thân trong gia đình","Bạn cùng lớp","Đồng đội","Đồng nghiệp"],"h1":"Hãy nghĩ đến anh chị em.","h2":"Ở Rhode Island, người thân trong gia đình không bị tính vào giới hạn một hành khách của bằng lái tạm thời có giới hạn.","p":"Đúng. Người thân trong gia đình không bị tính."},"tl":{"q":"Sa Rhode Island, aling mga batang pasahero ang hindi binibilang sa limitasyon sa pasahero ng provisional license?","o":["Malapit na pamilya (immediate family)","Mga kaklase","Mga kasama sa team","Mga katrabaho"],"h1":"Isipin ang mga kapatid na lalaki at babae.","h2":"Sa Rhode Island, hindi binibilang ang malapit na pamilya sa limitasyong isang pasahero sa limited provisional license.","p":"Tama. Hindi binibilang ang malapit na pamilya."},"ar":{"q":"في Rhode Island، أي ركاب صغار لا يُحسبون ضمن قيد الركاب على الرخصة المؤقتة؟","o":["أفراد الأسرة المباشرون","زملاء الصف","زملاء الفريق","زملاء العمل"],"h1":"فكّر في الإخوة والأخوات.","h2":"في Rhode Island لا يُحسب أفراد الأسرة المباشرون ضمن قيد الراكب الواحد على الرخصة المؤقتة المحدودة.","p":"صحيح. أفراد الأسرة المباشرون لا يُحسبون."},"ref":{"doc":"RI","page":14}},{"id":"ri-013","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, who may supervise a teen driving with an instruction permit?","o":["Any licensed driver over 18","Any passenger over 16","A licensed adult over 21 who has been licensed for five years","Only a police officer"],"h1":"The helper needs both age and years behind the wheel.","h2":"A Rhode Island permit holder must drive with a licensed adult over 21 who has held a license for at least five years.","p":"Right. Over 21 and licensed five years."},"es":{"q":"En Rhode Island, ¿quién puede supervisar a un adolescente que maneja con permiso de instrucción?","o":["Cualquier conductor con licencia mayor de 18","Cualquier pasajero mayor de 16","Un adulto mayor de 21 que tiene licencia desde hace cinco años","Solo un policía"],"h1":"El acompañante necesita edad y también años de manejo.","h2":"Quien tiene permiso en Rhode Island debe manejar con un adulto mayor de 21 que tenga licencia desde hace por lo menos cinco años.","p":"Correcto. Mayor de 21 y con licencia desde hace cinco años."},"zh":{"q":"在 Rhode Island，谁可以监督持学习驾照的青少年开车？","o":["任何 18 岁以上有驾照的司机","任何 16 岁以上的乘客","21 岁以上、已经有驾照五年的成年人","只有警察"],"h1":"陪同的人既要够年龄，也要有多年驾驶经验。","h2":"在 Rhode Island，持学习驾照的人必须和一位 21 岁以上、持有驾照至少五年的成年人一起开车。","p":"对。21 岁以上，并有驾照五年。"},"vi":{"q":"Ở Rhode Island, ai được giám sát thiếu niên lái xe với giấy phép tập lái?","o":["Bất kỳ tài xế có bằng nào trên 18 tuổi","Bất kỳ hành khách nào trên 16 tuổi","Một người lớn trên 21 tuổi đã có bằng lái được năm năm","Chỉ cảnh sát"],"h1":"Người kèm cần cả tuổi tác và nhiều năm lái xe.","h2":"Người có giấy phép tập lái ở Rhode Island phải lái xe cùng một người lớn có bằng lái, trên 21 tuổi, đã có bằng ít nhất năm năm.","p":"Đúng. Trên 21 tuổi và có bằng năm năm."},"tl":{"q":"Sa Rhode Island, sino ang puwedeng gumabay sa teenager na nagmamaneho na may instruction permit?","o":["Kahit sinong lisensyadong driver na higit 18","Kahit sinong pasaherong higit 16","Isang lisensyadong adult na higit 21 na may lisensya na nang limang taon","Pulis lang"],"h1":"Kailangan ng gabay ang tamang edad at maraming taon ng pagmamaneho.","h2":"Ang may permit sa Rhode Island ay dapat magmaneho kasama ang isang lisensyadong adult na higit 21 na may lisensya na nang hindi bababa sa limang taon.","p":"Tama. Higit 21 at may lisensya nang limang taon."},"ar":{"q":"في Rhode Island، من يجوز له الإشراف على مراهق يقود بتصريح تعلّم؟","o":["أي سائق مرخّص عمره أكثر من 18 سنة","أي راكب عمره أكثر من 16 سنة","شخص بالغ مرخّص عمره أكثر من 21 سنة ولديه رخصة منذ خمس سنوات","ضابط شرطة فقط"],"h1":"المرافق يحتاج إلى العمر وإلى سنوات من القيادة معاً.","h2":"يجب على حامل التصريح في Rhode Island أن يقود مع شخص بالغ مرخّص عمره أكثر من 21 سنة ويحمل رخصة منذ خمس سنوات على الأقل.","p":"صحيح. أكثر من 21 سنة ومرخّص منذ خمس سنوات."},"ref":{"doc":"RI","page":11}},{"id":"ri-014","scope":"RI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Rhode Island, may a driver read a text message while the car is moving?","o":["Yes, if it is short","No, texting while driving is banned","Yes, on the highway","Yes, if no one is in the car"],"h1":"Reading counts the same as writing.","h2":"Rhode Island bans texting while driving, which includes writing, sending or reading messages while the car is moving.","p":"Right. No reading or writing texts while driving."},"es":{"q":"En Rhode Island, ¿puede un conductor leer un mensaje de texto mientras el carro está en movimiento?","o":["Sí, si es corto","No, enviar o leer mensajes al manejar está prohibido","Sí, en la autopista","Sí, si no hay nadie en el carro"],"h1":"Leer cuenta igual que escribir.","h2":"Rhode Island prohíbe los mensajes de texto al manejar, lo que incluye escribir, enviar o leer mensajes mientras el carro está en movimiento.","p":"Correcto. Nada de leer ni escribir mensajes al manejar."},"zh":{"q":"在 Rhode Island，车在行驶时，司机可以看短信吗？","o":["可以，如果短信很短","不可以，开车时禁止发短信","可以，在高速公路上","可以，如果车里没有别人"],"h1":"看短信和写短信一样算。","h2":"Rhode Island 禁止开车时发短信，包括车在行驶时写、发送或阅读短信。","p":"对。开车时不能看也不能写短信。"},"vi":{"q":"Ở Rhode Island, tài xế có được đọc tin nhắn khi xe đang chạy không?","o":["Có, nếu tin nhắn ngắn","Không, cấm nhắn tin khi lái xe","Có, trên xa lộ","Có, nếu không có ai trong xe"],"h1":"Đọc cũng bị tính giống như viết.","h2":"Rhode Island cấm nhắn tin khi lái xe, bao gồm viết, gửi hoặc đọc tin nhắn khi xe đang chạy.","p":"Đúng. Không đọc và không viết tin nhắn khi lái xe."},"tl":{"q":"Sa Rhode Island, puwede bang magbasa ng text message ang driver habang umaandar ang kotse?","o":["Oo, kung maikli","Hindi, bawal ang pag-text habang nagmamaneho","Oo, sa highway","Oo, kung walang ibang tao sa kotse"],"h1":"Kapareho ng pagsulat ang pagbasa.","h2":"Bawal sa Rhode Island ang pag-text habang nagmamaneho, kasama ang pagsulat, pagpapadala, o pagbasa ng mensahe habang umaandar ang kotse.","p":"Tama. Bawal magbasa o magsulat ng text habang nagmamaneho."},"ar":{"q":"في Rhode Island، هل يجوز للسائق أن يقرأ رسالة نصية والسيارة تتحرك؟","o":["نعم، إذا كانت قصيرة","لا، الرسائل النصية أثناء القيادة ممنوعة","نعم، على الطريق السريع","نعم، إذا لم يكن أحد في السيارة"],"h1":"القراءة تُحسب مثل الكتابة.","h2":"تمنع Rhode Island الرسائل النصية أثناء القيادة، وهذا يشمل كتابة الرسائل أو إرسالها أو قراءتها والسيارة تتحرك.","p":"صحيح. لا قراءة ولا كتابة للرسائل أثناء القيادة."},"ref":{"doc":"RI","page":36}},{"id":"ri-015","scope":"RI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Rhode Island, how may an adult driver talk on a phone while driving?","o":["Holding the phone to the ear","On speaker, held in the hand","Any way they like","Only hands-free"],"h1":"Your hands must stay free for the wheel.","h2":"In Rhode Island an adult driver may talk on a phone while driving only hands-free, never holding it.","p":"Right. Only hands-free."},"es":{"q":"En Rhode Island, ¿cómo puede un conductor adulto hablar por teléfono mientras maneja?","o":["Con el teléfono en la oreja","En altavoz, con el teléfono en la mano","Como quiera","Solo con manos libres"],"h1":"Sus manos deben quedar libres para el volante.","h2":"En Rhode Island un conductor adulto solo puede hablar por teléfono al manejar con manos libres, nunca sosteniéndolo.","p":"Correcto. Solo con manos libres."},"zh":{"q":"在 Rhode Island，成年司机开车时可以怎样打电话？","o":["把手机拿到耳边","开扬声器，手拿着手机","怎样都可以","只能用免提（hands-free）"],"h1":"你的手必须空出来握方向盘。","h2":"在 Rhode Island，成年司机开车时只能用免提打电话，绝不能手拿手机。","p":"对。只能用免提。"},"vi":{"q":"Ở Rhode Island, tài xế người lớn được nói chuyện điện thoại khi lái xe bằng cách nào?","o":["Cầm điện thoại áp vào tai","Bật loa ngoài, cầm trên tay","Bằng bất kỳ cách nào","Chỉ dùng rảnh tay (hands-free)"],"h1":"Tay bạn phải rảnh để cầm vô lăng.","h2":"Ở Rhode Island, tài xế người lớn chỉ được nói chuyện điện thoại khi lái xe bằng cách rảnh tay, không bao giờ cầm điện thoại.","p":"Đúng. Chỉ dùng rảnh tay."},"tl":{"q":"Sa Rhode Island, paano puwedeng makipag-usap sa telepono ang adult na driver habang nagmamaneho?","o":["Hawak ang telepono sa tainga","Naka-speaker, hawak sa kamay","Kahit anong paraan","Hands-free lang"],"h1":"Dapat libre ang mga kamay mo para sa manibela.","h2":"Sa Rhode Island, ang adult na driver ay puwedeng makipag-usap sa telepono habang nagmamaneho nang hands-free lang, hindi kailanman hawak ito.","p":"Tama. Hands-free lang."},"ar":{"q":"في Rhode Island، كيف يجوز للسائق البالغ أن يتكلم في الهاتف أثناء القيادة؟","o":["بوضع الهاتف على الأذن","بمكبّر الصوت مع حمل الهاتف في اليد","بأي طريقة يريدها","بدون استخدام اليدين (hands-free) فقط"],"h1":"يجب أن تبقى يداك حرّتين لعجلة القيادة.","h2":"في Rhode Island يجوز للسائق البالغ أن يتكلم في الهاتف أثناء القيادة بدون استخدام اليدين فقط، ولا يحمله أبداً.","p":"صحيح. بدون استخدام اليدين فقط."},"ref":{"doc":"RI","page":null}},{"id":"ri-016","scope":"RI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Rhode Island, what is the legal alcohol limit for a driver under 21?","o":["0.02 percent","0.08 percent","0.05 percent","0.10 percent"],"h1":"It is much lower than the adult limit.","h2":"In Rhode Island the alcohol limit for a driver under 21 is 0.02 percent.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Rhode Island, ¿cuál es el límite legal de alcohol para un conductor menor de 21?","o":["0.02 por ciento","0.08 por ciento","0.05 por ciento","0.10 por ciento"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Rhode Island el límite de alcohol para un conductor menor de 21 es de 0.02 por ciento.","p":"Correcto. Menor de 21, el límite es 0.02."},"zh":{"q":"在 Rhode Island，21 岁以下司机的法定酒精限度是多少？","o":["0.02%","0.08%","0.05%","0.10%"],"h1":"它比成年人的限度低很多。","h2":"在 Rhode Island，21 岁以下司机的酒精限度是 0.02%。","p":"对。21 岁以下，限度是 0.02。"},"vi":{"q":"Ở Rhode Island, giới hạn nồng độ cồn hợp pháp cho tài xế dưới 21 tuổi là bao nhiêu?","o":["0.02 phần trăm","0.08 phần trăm","0.05 phần trăm","0.10 phần trăm"],"h1":"Nó thấp hơn nhiều so với giới hạn của người lớn.","h2":"Ở Rhode Island, giới hạn nồng độ cồn cho tài xế dưới 21 tuổi là 0.02 phần trăm.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa Rhode Island, ano ang legal na limitasyon sa alak para sa driver na wala pang 21?","o":["0.02 porsiyento","0.08 porsiyento","0.05 porsiyento","0.10 porsiyento"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon ng adult.","h2":"Sa Rhode Island, ang limitasyon sa alak para sa driver na wala pang 21 ay 0.02 porsiyento.","p":"Tama. Kapag wala pang 21, ang limitasyon ay 0.02."},"ar":{"q":"في Rhode Island، ما الحد القانوني للكحول للسائق الذي عمره أقل من 21 سنة؟","o":["0.02 بالمئة","0.08 بالمئة","0.05 بالمئة","0.10 بالمئة"],"h1":"هو أقل بكثير من حد البالغين.","h2":"في Rhode Island حد الكحول للسائق الذي عمره أقل من 21 سنة هو 0.02 بالمئة.","p":"صحيح. لمن عمره أقل من 21 سنة، الحد 0.02."},"ref":{"doc":"RI","page":58}},{"id":"ri-017","scope":"RI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Rhode Island, what is the legal alcohol limit for a driver 21 or older?","o":["0.02 percent","0.10 percent","0.08 percent","0.12 percent"],"h1":"It is the same limit used in most states.","h2":"In Rhode Island the alcohol limit for a driver 21 or older is 0.08 percent.","p":"Right. For adults, the limit is 0.08."},"es":{"q":"En Rhode Island, ¿cuál es el límite legal de alcohol para un conductor de 21 años o más?","o":["0.02 por ciento","0.10 por ciento","0.08 por ciento","0.12 por ciento"],"h1":"Es el mismo límite que usan la mayoría de los estados.","h2":"En Rhode Island el límite de alcohol para un conductor de 21 años o más es de 0.08 por ciento.","p":"Correcto. Para adultos, el límite es 0.08."},"zh":{"q":"在 Rhode Island，21 岁或以上司机的法定酒精限度是多少？","o":["0.02%","0.10%","0.08%","0.12%"],"h1":"它和大多数州用的限度一样。","h2":"在 Rhode Island，21 岁或以上司机的酒精限度是 0.08%。","p":"对。成年人的限度是 0.08。"},"vi":{"q":"Ở Rhode Island, giới hạn nồng độ cồn hợp pháp cho tài xế từ 21 tuổi trở lên là bao nhiêu?","o":["0.02 phần trăm","0.10 phần trăm","0.08 phần trăm","0.12 phần trăm"],"h1":"Đó là giới hạn giống như ở hầu hết các tiểu bang.","h2":"Ở Rhode Island, giới hạn nồng độ cồn cho tài xế từ 21 tuổi trở lên là 0.08 phần trăm.","p":"Đúng. Với người lớn, giới hạn là 0.08."},"tl":{"q":"Sa Rhode Island, ano ang legal na limitasyon sa alak para sa driver na 21 pataas?","o":["0.02 porsiyento","0.10 porsiyento","0.08 porsiyento","0.12 porsiyento"],"h1":"Ito ang parehong limitasyong ginagamit sa karamihan ng estado.","h2":"Sa Rhode Island, ang limitasyon sa alak para sa driver na 21 pataas ay 0.08 porsiyento.","p":"Tama. Para sa adult, ang limitasyon ay 0.08."},"ar":{"q":"في Rhode Island، ما الحد القانوني للكحول للسائق الذي عمره 21 سنة أو أكثر؟","o":["0.02 بالمئة","0.10 بالمئة","0.08 بالمئة","0.12 بالمئة"],"h1":"هو نفس الحد المستخدم في معظم الولايات.","h2":"في Rhode Island حد الكحول للسائق الذي عمره 21 سنة أو أكثر هو 0.08 بالمئة.","p":"صحيح. للبالغين، الحد 0.08."},"ref":{"doc":"RI","page":58}},{"id":"ri-018","scope":"RI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Rhode Island, what must you do when you approach a stopped police car with its lights on?","o":["Speed up to pass quickly","Change lanes away from it or slow down","Stop in your lane","Flash your high beams"],"h1":"Give the officer more room or more time.","h2":"Rhode Island's move over law says to change to a lane away from the stopped vehicle, or slow down, when it shows its emergency lights.","p":"Right. Move over or slow down."},"es":{"q":"En Rhode Island, ¿qué debe hacer al acercarse a un carro de policía detenido con las luces encendidas?","o":["Acelerar para pasar rápido","Cambiarse a un carril lejos de él o bajar la velocidad","Detenerse en su carril","Encender las luces altas"],"h1":"Dé al oficial más espacio o más tiempo.","h2":"La ley de Rhode Island para moverse de carril dice que debe cambiarse a un carril lejos del vehículo detenido, o bajar la velocidad, cuando tiene encendidas sus luces de emergencia.","p":"Correcto. Cámbiese de carril o baje la velocidad."},"zh":{"q":"在 Rhode Island，当你接近一辆停着并亮着灯的警车时，你必须怎么做？","o":["加速快速开过去","换到离它远的车道，或减速","在你的车道上停车","闪你的远光灯"],"h1":"给警察更多空间或更多时间。","h2":"Rhode Island 的让道法（move over law）规定，停着的车亮着紧急灯时，你要换到离它远的车道，或者减速。","p":"对。让道或减速。"},"vi":{"q":"Ở Rhode Island, bạn phải làm gì khi đến gần một xe cảnh sát đang dừng và bật đèn?","o":["Tăng tốc để vượt qua nhanh","Chuyển sang làn xa nó hoặc chạy chậm lại","Dừng lại trong làn của bạn","Nháy đèn pha"],"h1":"Hãy cho cảnh sát thêm khoảng trống hoặc thêm thời gian.","h2":"Luật nhường làn (move over law) của Rhode Island nói rằng bạn phải chuyển sang làn xa chiếc xe đang dừng, hoặc chạy chậm lại, khi xe đó bật đèn khẩn cấp.","p":"Đúng. Chuyển làn hoặc chạy chậm lại."},"tl":{"q":"Sa Rhode Island, ano ang dapat mong gawin kapag papalapit ka sa nakahintong police car na may ilaw na nakabukas?","o":["Bumilis para makalampas agad","Lumipat sa lane na malayo rito o bumagal","Huminto sa lane mo","I-flash ang high beams mo"],"h1":"Bigyan ang pulis ng mas maraming espasyo o mas maraming oras.","h2":"Sinasabi ng move over law ng Rhode Island na lumipat sa lane na malayo sa nakahintong sasakyan, o bumagal, kapag nakabukas ang emergency lights nito.","p":"Tama. Lumipat ng lane o bumagal."},"ar":{"q":"في Rhode Island، ماذا يجب أن تفعل عندما تقترب من سيارة شرطة متوقفة وأضواؤها مشتعلة؟","o":["تسرع لتتجاوزها بسرعة","تنتقل إلى مسار بعيد عنها أو تخفّف السرعة","تتوقف في مسارك","تومض بالأضواء العالية"],"h1":"أعطِ الشرطي مساحة أكبر أو وقتاً أطول.","h2":"يقول قانون الابتعاد (move over law) في Rhode Island أن تنتقل إلى مسار بعيد عن المركبة المتوقفة، أو تخفّف السرعة، عندما تكون أضواء الطوارئ فيها مشتعلة.","p":"صحيح. ابتعد بمسارك أو خفّف السرعة."},"ref":{"doc":"RI","page":null}},{"id":"ri-019","scope":"RI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Rhode Island, does the move over law apply to an ordinary car stopped on the shoulder?","o":["No, only police cars","No, only tow trucks","Only at night","Yes, move over or slow down for it too"],"h1":"Since 2023 the law protects more than emergency vehicles.","h2":"Yes. Rhode Island's move over law also covers any vehicle stopped on the shoulder or breakdown lane, so you move over or slow down for it.","p":"Right. Move over or slow down for any car stopped on the shoulder."},"es":{"q":"En Rhode Island, ¿la ley para moverse de carril se aplica a un carro común detenido en el acotamiento?","o":["No, solo a los carros de policía","No, solo a las grúas","Solo de noche","Sí, también debe cambiar de carril o bajar la velocidad"],"h1":"Desde 2023 la ley protege a más vehículos que los de emergencia.","h2":"Sí. La ley de Rhode Island para moverse de carril también cubre cualquier vehículo detenido en el acotamiento o carril de emergencia, así que usted debe cambiar de carril o bajar la velocidad.","p":"Correcto. Cambie de carril o baje la velocidad ante cualquier carro detenido en el acotamiento."},"zh":{"q":"在 Rhode Island，让道法也适用于停在路肩上的普通汽车吗？","o":["不，只适用于警车","不，只适用于拖车","只在夜间","是的，对它也要让道或减速"],"h1":"从 2023 年起，这条法律保护的不只是紧急车辆。","h2":"是的。Rhode Island 的让道法也包括任何停在路肩或故障车道上的车辆，所以你要为它让道或减速。","p":"对。对任何停在路肩上的车都要让道或减速。"},"vi":{"q":"Ở Rhode Island, luật nhường làn có áp dụng cho một chiếc xe bình thường đang dừng trên lề đường không?","o":["Không, chỉ xe cảnh sát","Không, chỉ xe kéo","Chỉ vào ban đêm","Có, cũng phải chuyển làn hoặc chạy chậm lại"],"h1":"Từ năm 2023, luật này bảo vệ nhiều hơn chỉ xe khẩn cấp.","h2":"Có. Luật nhường làn của Rhode Island cũng áp dụng cho bất kỳ xe nào dừng trên lề đường hoặc làn xe hư, nên bạn phải chuyển làn hoặc chạy chậm lại.","p":"Đúng. Chuyển làn hoặc chạy chậm lại với bất kỳ xe nào dừng trên lề đường."},"tl":{"q":"Sa Rhode Island, saklaw ba ng move over law ang ordinaryong kotse na nakahinto sa shoulder?","o":["Hindi, police car lang","Hindi, tow truck lang","Sa gabi lang","Oo, lumipat ng lane o bumagal din para rito"],"h1":"Mula 2023, mas marami na ang pinoprotektahan ng batas kaysa emergency vehicles lang.","h2":"Oo. Saklaw din ng move over law ng Rhode Island ang anumang sasakyang nakahinto sa shoulder o breakdown lane, kaya lumipat ka ng lane o bumagal para rito.","p":"Tama. Lumipat ng lane o bumagal para sa anumang kotseng nakahinto sa shoulder."},"ar":{"q":"في Rhode Island، هل ينطبق قانون الابتعاد على سيارة عادية متوقفة على كتف الطريق؟","o":["لا، فقط سيارات الشرطة","لا، فقط شاحنات السحب","في الليل فقط","نعم، ابتعد بمسارك أو خفّف السرعة لها أيضاً"],"h1":"منذ 2023 يحمي القانون أكثر من مركبات الطوارئ.","h2":"نعم. قانون الابتعاد في Rhode Island يشمل أيضاً أي مركبة متوقفة على كتف الطريق أو في مسار الأعطال، لذلك تبتعد بمسارك أو تخفّف السرعة لها.","p":"صحيح. ابتعد بمسارك أو خفّف السرعة لأي سيارة متوقفة على كتف الطريق."},"ref":{"doc":"RI","page":null}},{"id":"ri-020","scope":"RI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Rhode Island, on a highway with a median strip, must you stop for a school bus stopped on the other side?","o":["No, you do not have to stop","Yes, always","Only if children are visible","Only on school days"],"h1":"The median separates you from the children.","h2":"Under Rhode Island law, you do not have to stop for a school bus that is stopped on the other side of a divided highway.","p":"Right. The other side of a divided highway need not stop."},"es":{"q":"En Rhode Island, en una carretera con franja divisoria, ¿debe detenerse ante un autobús escolar detenido del otro lado?","o":["No, no tiene que detenerse","Sí, siempre","Solo si se ven niños","Solo en días de clases"],"h1":"La franja divisoria lo separa de los niños.","h2":"Según la ley de Rhode Island, usted no tiene que detenerse ante un autobús escolar detenido del otro lado de una carretera dividida.","p":"Correcto. El otro lado de una carretera dividida no tiene que detenerse."},"zh":{"q":"在 Rhode Island，在有中间隔离带的公路上，对面停着的校车，你必须停车吗？","o":["不，你不必停车","是的，一定要停","只有看得见孩子时才停","只有上学的日子才停"],"h1":"中间隔离带把你和孩子们隔开。","h2":"根据 Rhode Island 的法律，校车停在分隔公路的另一边时，你不必停车。","p":"对。分隔公路另一边的车不必停。"},"vi":{"q":"Ở Rhode Island, trên xa lộ có dải phân cách ở giữa, bạn có phải dừng lại cho xe buýt trường học đang dừng ở phía bên kia không?","o":["Không, bạn không phải dừng","Có, luôn luôn","Chỉ khi thấy trẻ em","Chỉ vào ngày đi học"],"h1":"Dải phân cách ngăn bạn với các em nhỏ.","h2":"Theo luật Rhode Island, bạn không phải dừng lại cho xe buýt trường học đang dừng ở phía bên kia của xa lộ có dải phân cách.","p":"Đúng. Xe ở phía bên kia của xa lộ có dải phân cách không cần dừng."},"tl":{"q":"Sa Rhode Island, sa highway na may median strip, dapat ka bang huminto para sa school bus na nakahinto sa kabilang panig?","o":["Hindi, hindi mo kailangang huminto","Oo, palagi","Kapag may nakikitang mga bata lang","Sa mga araw ng pasok lang"],"h1":"Pinaghihiwalay ka ng median sa mga bata.","h2":"Ayon sa batas ng Rhode Island, hindi mo kailangang huminto para sa school bus na nakahinto sa kabilang panig ng divided highway.","p":"Tama. Hindi kailangang huminto sa kabilang panig ng divided highway."},"ar":{"q":"في Rhode Island، على طريق سريع فيه جزيرة وسطية، هل يجب أن تتوقف لحافلة مدرسية متوقفة في الجهة الأخرى؟","o":["لا، ليس عليك أن تتوقف","نعم، دائماً","فقط إذا كان الأطفال ظاهرين","فقط في أيام الدراسة"],"h1":"الجزيرة الوسطية تفصلك عن الأطفال.","h2":"حسب قانون Rhode Island، ليس عليك أن تتوقف لحافلة مدرسية متوقفة في الجهة الأخرى من طريق مقسوم.","p":"صحيح. الجهة الأخرى من الطريق المقسوم لا تحتاج إلى التوقف."},"ref":{"doc":"RI","page":51}},{"id":"ri-021","scope":"RI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Rhode Island, on a road with no median, which drivers must stop for a school bus with flashing red lights?","o":["Only drivers behind the bus","Only drivers in the right lane","All drivers coming from either direction","No one, if the road is wide"],"h1":"On an undivided road, children may cross toward either side.","h2":"In Rhode Island, on a road with no median, drivers coming from either direction must stop for a school bus with flashing red lights.","p":"Right. Traffic from both directions stops."},"es":{"q":"En Rhode Island, en una vía sin división, ¿qué conductores deben detenerse ante un autobús escolar con luces rojas intermitentes?","o":["Solo los conductores detrás del autobús","Solo los del carril derecho","Todos los conductores que vienen de cualquier dirección","Nadie, si la vía es ancha"],"h1":"En una vía sin división, los niños pueden cruzar hacia cualquier lado.","h2":"En Rhode Island, en una vía sin división, los conductores que vienen de cualquier dirección deben detenerse ante un autobús escolar con luces rojas intermitentes.","p":"Correcto. El tráfico de ambos sentidos se detiene."},"zh":{"q":"在 Rhode Island，在没有中间隔离带的路上，哪些司机必须为闪着红灯的校车停车？","o":["只有校车后面的司机","只有右车道的司机","从两个方向来的所有司机","如果路很宽，谁都不用停"],"h1":"在没有分隔的路上，孩子可能往任何一边过马路。","h2":"在 Rhode Island，在没有中间隔离带的路上，两个方向来的司机都必须为闪着红灯的校车停车。","p":"对。两个方向的车都要停。"},"vi":{"q":"Ở Rhode Island, trên đường không có dải phân cách, những tài xế nào phải dừng lại cho xe buýt trường học đang nháy đèn đỏ?","o":["Chỉ tài xế phía sau xe buýt","Chỉ tài xế ở làn bên phải","Tất cả tài xế đến từ cả hai hướng","Không ai, nếu đường rộng"],"h1":"Trên đường không có phân cách, trẻ em có thể băng qua về bất kỳ phía nào.","h2":"Ở Rhode Island, trên đường không có dải phân cách, tài xế đến từ cả hai hướng phải dừng lại cho xe buýt trường học đang nháy đèn đỏ.","p":"Đúng. Xe từ cả hai hướng đều dừng."},"tl":{"q":"Sa Rhode Island, sa kalsadang walang median, aling mga driver ang dapat huminto para sa school bus na may kumikislap na pulang ilaw?","o":["Ang mga driver sa likod ng bus lang","Ang mga driver sa kanang lane lang","Lahat ng driver mula sa alinmang direksyon","Wala, kung malapad ang kalsada"],"h1":"Sa kalsadang walang hati, puwedeng tumawid ang mga bata sa alinmang panig.","h2":"Sa Rhode Island, sa kalsadang walang median, ang mga driver mula sa alinmang direksyon ay dapat huminto para sa school bus na may kumikislap na pulang ilaw.","p":"Tama. Humihinto ang trapiko mula sa dalawang direksyon."},"ar":{"q":"في Rhode Island، على طريق بدون جزيرة وسطية، أي سائقين يجب أن يتوقفوا لحافلة مدرسية أضواؤها الحمراء تومض؟","o":["فقط السائقون خلف الحافلة","فقط السائقون في المسار الأيمن","كل السائقين القادمين من أي اتجاه","لا أحد، إذا كان الطريق عريضاً"],"h1":"على طريق غير مقسوم، قد يعبر الأطفال نحو أي جهة.","h2":"في Rhode Island، على طريق بدون جزيرة وسطية، يجب على السائقين القادمين من أي اتجاه أن يتوقفوا لحافلة مدرسية أضواؤها الحمراء تومض.","p":"صحيح. تتوقف حركة المرور من الاتجاهين."},"ref":{"doc":"RI","page":51}},{"id":"ri-023","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, how long is a limited instruction permit good for?","o":["Six months, then it must be renewed","Three years from the date it is issued","One year, or until age 18 if that comes first","Until the teen finishes high school"],"h1":"It is longer than the time you must hold it before the road test.","h2":"A Rhode Island limited instruction permit is valid for one year, or until the holder turns 18 if that comes first.","p":"Right. One year, or until age 18."},"es":{"q":"En Rhode Island, ¿por cuánto tiempo es válido un permiso de instrucción limitado?","o":["Seis meses, y luego se debe renovar","Tres años desde la fecha en que se emite","Un año, o hasta los 18 años si eso ocurre antes","Hasta que el joven termine la secundaria"],"h1":"Es más largo que el tiempo que debe tenerlo antes del examen de manejo.","h2":"En Rhode Island, el permiso de instrucción limitado es válido por un año, o hasta que el titular cumpla 18 años si eso ocurre antes.","p":"Correcto. Un año, o hasta los 18 años."},"zh":{"q":"在 Rhode Island，受限学习驾照（limited instruction permit）的有效期是多久？","o":["六个月，之后必须续期","从发证日期起三年","一年，或者到 18 岁为止，以先到者为准","直到青少年读完高中"],"h1":"它比你参加路考前必须持有的时间更长。","h2":"Rhode Island 的受限学习驾照有效期是一年，或者到持有人满 18 岁为止，以先到者为准。","p":"对。一年，或者到 18 岁为止。"},"vi":{"q":"Ở Rhode Island, giấy phép tập lái có giới hạn (limited instruction permit) có hiệu lực trong bao lâu?","o":["Sáu tháng, sau đó phải gia hạn","Ba năm kể từ ngày cấp","Một năm, hoặc đến 18 tuổi nếu điều đó đến trước","Đến khi thiếu niên học xong trung học"],"h1":"Thời gian này dài hơn thời gian bạn phải giữ giấy phép trước khi thi lái trên đường.","h2":"Giấy phép tập lái có giới hạn ở Rhode Island có hiệu lực một năm, hoặc đến khi người giữ giấy phép đủ 18 tuổi nếu điều đó đến trước.","p":"Đúng. Một năm, hoặc đến 18 tuổi."},"tl":{"q":"Sa Rhode Island, gaano katagal valid ang limited instruction permit?","o":["Anim na buwan, at pagkatapos ay kailangan itong i-renew","Tatlong taon mula sa araw na ibinigay ito","Isang taon, o hanggang edad 18 kung iyon ang mauna","Hanggang matapos ng teen ang high school"],"h1":"Mas mahaba ito kaysa sa panahong kailangan mo itong hawakan bago ang road test.","h2":"Ang limited instruction permit sa Rhode Island ay valid nang isang taon, o hanggang mag-18 ang may hawak nito kung iyon ang mauna.","p":"Tama. Isang taon, o hanggang edad 18."},"ar":{"q":"في Rhode Island، ما مدة صلاحية تصريح التعلّم المحدود (limited instruction permit)؟","o":["ستة أشهر، ثم يجب تجديده","ثلاث سنوات من تاريخ إصداره","سنة واحدة، أو حتى عمر 18 سنة إذا جاء ذلك أولًا","حتى ينهي المراهق المدرسة الثانوية"],"h1":"المدة أطول من الوقت الذي يجب أن تحمل فيه التصريح قبل اختبار القيادة على الطريق.","h2":"تصريح التعلّم المحدود في Rhode Island صالح لمدة سنة واحدة، أو حتى يبلغ حامله 18 سنة إذا جاء ذلك أولًا.","p":"صحيح. سنة واحدة، أو حتى عمر 18 سنة."},"ref":{"doc":"RI","page":11}},{"id":"ri-024","scope":"RI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Rhode Island, can police stop a car just because someone inside is not wearing a seat belt?","o":["Yes, for a person of any age","Only if the person is under 8","Only if the driver is under 18","No, only together with another offense"],"h1":"Rhode Island calls its seat belt law a primary law.","h2":"Rhode Island's seat belt law is a primary law for all ages, so police may pull a car over when anyone inside is not buckled up.","p":"Right. Police can stop you for an unbuckled person of any age."},"es":{"q":"En Rhode Island, ¿puede la policía detener un carro solo porque alguien adentro no lleva el cinturón de seguridad?","o":["Sí, por una persona de cualquier edad","Solo si la persona tiene menos de 8 años","Solo si el conductor tiene menos de 18 años","No, solo junto con otra infracción"],"h1":"Rhode Island llama a su ley del cinturón una ley primaria.","h2":"La ley del cinturón de seguridad de Rhode Island es una ley primaria para todas las edades, así que la policía puede detener un carro cuando alguien adentro no lleva el cinturón puesto.","p":"Correcto. La policía puede detenerlo por una persona sin cinturón de cualquier edad."},"zh":{"q":"在 Rhode Island，警察能不能只因为车里有人没系安全带就让车停下？","o":["能，任何年龄的人都算","只有那个人不满 8 岁时才能","只有司机不满 18 岁时才能","不能，只能和其他违规一起处理"],"h1":"Rhode Island 把它的安全带法律叫做主要法律（primary law）。","h2":"Rhode Island 的安全带法律对所有年龄都是主要法律，所以只要车里有人没系安全带，警察就可以让车停下。","p":"对。车里任何年龄的人没系安全带，警察都可以让你停车。"},"vi":{"q":"Ở Rhode Island, cảnh sát có thể chặn xe chỉ vì có người trong xe không thắt dây an toàn không?","o":["Có, với người ở bất kỳ tuổi nào","Chỉ khi người đó dưới 8 tuổi","Chỉ khi tài xế dưới 18 tuổi","Không, chỉ khi đi kèm với một vi phạm khác"],"h1":"Rhode Island gọi luật dây an toàn của mình là luật chính (primary law).","h2":"Luật dây an toàn ở Rhode Island là luật chính cho mọi lứa tuổi, nên cảnh sát có thể chặn xe khi có bất kỳ ai trong xe không thắt dây an toàn.","p":"Đúng. Cảnh sát có thể chặn bạn vì một người ở bất kỳ tuổi nào không thắt dây an toàn."},"tl":{"q":"Sa Rhode Island, puwede bang patigilin ng pulis ang kotse dahil lang may nakasakay na hindi naka-seat belt?","o":["Oo, para sa tao ng anumang edad","Kung wala pang 8 taong gulang ang tao lamang","Kung wala pang 18 taong gulang ang driver lamang","Hindi, kasama lang ng ibang paglabag"],"h1":"Tinatawag ng Rhode Island ang batas nito sa seat belt na primary law.","h2":"Ang batas sa seat belt ng Rhode Island ay primary law para sa lahat ng edad, kaya puwedeng patigilin ng pulis ang kotse kapag may sinumang nakasakay na hindi naka-seat belt.","p":"Tama. Puwede kang patigilin ng pulis dahil sa sinumang hindi naka-seat belt, anumang edad."},"ar":{"q":"في Rhode Island، هل يمكن للشرطة إيقاف سيارة فقط لأن شخصًا بداخلها لا يربط حزام الأمان؟","o":["نعم، لشخص من أي عمر","فقط إذا كان الشخص أقل من 8 سنوات","فقط إذا كان السائق أقل من 18 سنة","لا، فقط مع مخالفة أخرى"],"h1":"تسمّي Rhode Island قانون حزام الأمان فيها قانونًا أساسيًا (primary law).","h2":"قانون حزام الأمان في Rhode Island قانون أساسي لكل الأعمار، لذلك يمكن للشرطة إيقاف السيارة عندما لا يربط أي شخص بداخلها حزام الأمان.","p":"صحيح. يمكن للشرطة إيقافك بسبب شخص من أي عمر لا يربط الحزام."},"ref":{"doc":"RI","page":25}},{"id":"ri-025","scope":"RI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Rhode Island, where must a child under 8 who is shorter than 57 inches and under 80 pounds ride?","o":["In the front seat with a seat belt","Anywhere, as long as an adult holds the child","In the front seat in a booster seat","In a rear seat, in an approved child safety seat"],"h1":"Think about the safest part of the car for a small child.","h2":"In Rhode Island, a child under 8 who is less than 57 inches tall and less than 80 pounds must ride in a rear seat in an approved child restraint.","p":"Right. A rear seat, in an approved child safety seat."},"es":{"q":"En Rhode Island, ¿dónde debe viajar un niño menor de 8 años que mide menos de 57 pulgadas y pesa menos de 80 libras?","o":["En el asiento delantero con cinturón","En cualquier lugar, si un adulto lo sostiene","En el asiento delantero en un asiento elevado","En un asiento trasero, en un asiento de seguridad aprobado"],"h1":"Piense en la parte más segura del carro para un niño pequeño.","h2":"En Rhode Island, un niño menor de 8 años que mide menos de 57 pulgadas y pesa menos de 80 libras debe viajar en un asiento trasero, en un sistema de retención infantil aprobado.","p":"Correcto. En un asiento trasero, en un asiento de seguridad aprobado."},"zh":{"q":"在 Rhode Island，不满 8 岁、身高不到 57 英寸、体重不到 80 磅的孩子必须坐在哪里？","o":["坐在前座，系安全带","哪里都行，只要有大人抱着孩子","坐在前座的增高座椅上","坐在后座，使用合格的儿童安全座椅"],"h1":"想一想车里哪个位置对小孩子最安全。","h2":"在 Rhode Island，不满 8 岁、身高不到 57 英寸、体重不到 80 磅的孩子必须坐在后座，使用合格的儿童安全座椅。","p":"对。坐在后座，使用合格的儿童安全座椅。"},"vi":{"q":"Ở Rhode Island, trẻ dưới 8 tuổi, cao dưới 57 inch và nặng dưới 80 pound phải ngồi ở đâu?","o":["Ở ghế trước, có thắt dây an toàn","Ở bất kỳ đâu, miễn là có người lớn bế trẻ","Ở ghế trước, trên ghế nâng (booster seat)","Ở ghế sau, trong ghế an toàn trẻ em được chấp thuận"],"h1":"Hãy nghĩ xem chỗ nào trong xe an toàn nhất cho trẻ nhỏ.","h2":"Ở Rhode Island, trẻ dưới 8 tuổi, cao dưới 57 inch và nặng dưới 80 pound phải ngồi ở ghế sau, trong ghế an toàn trẻ em được chấp thuận.","p":"Đúng. Ở ghế sau, trong ghế an toàn trẻ em được chấp thuận."},"tl":{"q":"Sa Rhode Island, saan dapat umupo ang batang wala pang 8 taong gulang na mas mababa sa 57 pulgada at wala pang 80 libra?","o":["Sa upuan sa harap, naka-seat belt","Kahit saan, basta may adult na humahawak sa bata","Sa upuan sa harap, sa booster seat","Sa upuan sa likod, sa aprubadong child safety seat"],"h1":"Isipin kung aling bahagi ng kotse ang pinakaligtas para sa maliit na bata.","h2":"Sa Rhode Island, ang batang wala pang 8 taong gulang na mas mababa sa 57 pulgada at wala pang 80 libra ay dapat umupo sa upuan sa likod, sa aprubadong child safety seat.","p":"Tama. Sa upuan sa likod, sa aprubadong child safety seat."},"ar":{"q":"في Rhode Island، أين يجب أن يجلس طفل عمره أقل من 8 سنوات وطوله أقل من 57 بوصة ووزنه أقل من 80 رطلًا؟","o":["في المقعد الأمامي مع حزام الأمان","في أي مكان، ما دام شخص بالغ يحمل الطفل","في المقعد الأمامي على مقعد رافع (booster seat)","في مقعد خلفي، في مقعد أمان للأطفال معتمد"],"h1":"فكّر في أكثر مكان أمانًا في السيارة لطفل صغير.","h2":"في Rhode Island، يجب أن يجلس الطفل الذي عمره أقل من 8 سنوات وطوله أقل من 57 بوصة ووزنه أقل من 80 رطلًا في مقعد خلفي، في مقعد أمان للأطفال معتمد.","p":"صحيح. في مقعد خلفي، في مقعد أمان للأطفال معتمد."},"ref":{"doc":"RI","page":25}},{"id":"ri-026","scope":"RI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Rhode Island, what happens to your license if you refuse a chemical test for alcohol?","o":["Nothing, the test is your choice","It is suspended for at least six months","You get a written warning only","It is suspended for one week"],"h1":"Driving in Rhode Island means you have already agreed to be tested.","h2":"In Rhode Island, refusing a chemical test for alcohol or drugs leads to a license suspension of at least six months, plus a fine and other penalties.","p":"Right. A suspension of at least six months."},"es":{"q":"En Rhode Island, ¿qué pasa con su licencia si se niega a hacerse una prueba química de alcohol?","o":["Nada, la prueba es opcional","Se suspende por al menos seis meses","Solo recibe una advertencia por escrito","Se suspende por una semana"],"h1":"Manejar en Rhode Island significa que usted ya aceptó hacerse la prueba.","h2":"En Rhode Island, negarse a una prueba química de alcohol o drogas lleva a una suspensión de la licencia de al menos seis meses, además de una multa y otras sanciones.","p":"Correcto. Una suspensión de al menos seis meses."},"zh":{"q":"在 Rhode Island，如果你拒绝做酒精化学检测，你的驾照会怎样？","o":["不会怎样，检测由你自己决定","至少被吊销六个月","你只会收到书面警告","被吊销一个星期"],"h1":"在 Rhode Island 开车，就表示你已经同意接受检测。","h2":"在 Rhode Island，拒绝做酒精或药物化学检测，驾照会被吊销至少六个月，还要交罚款并受到其他处罚。","p":"对。驾照至少被吊销六个月。"},"vi":{"q":"Ở Rhode Island, điều gì xảy ra với bằng lái của bạn nếu bạn từ chối xét nghiệm hóa học về rượu?","o":["Không có gì, xét nghiệm là do bạn chọn","Bằng lái bị treo ít nhất sáu tháng","Bạn chỉ bị cảnh cáo bằng văn bản","Bằng lái bị treo một tuần"],"h1":"Lái xe ở Rhode Island có nghĩa là bạn đã đồng ý cho xét nghiệm.","h2":"Ở Rhode Island, từ chối xét nghiệm hóa học về rượu hoặc ma túy sẽ khiến bằng lái bị treo ít nhất sáu tháng, cộng thêm tiền phạt và các hình phạt khác.","p":"Đúng. Bằng lái bị treo ít nhất sáu tháng."},"tl":{"q":"Sa Rhode Island, ano ang mangyayari sa lisensya mo kung tatanggi ka sa chemical test para sa alak?","o":["Wala, ikaw ang pipili kung magpapa-test ka","Masususpinde ito nang hindi bababa sa anim na buwan","Nakasulat na babala lang ang matatanggap mo","Masususpinde ito nang isang linggo"],"h1":"Ang pagmamaneho sa Rhode Island ay nangangahulugang pumayag ka na sa test.","h2":"Sa Rhode Island, ang pagtanggi sa chemical test para sa alak o droga ay nagdudulot ng suspensyon ng lisensya nang hindi bababa sa anim na buwan, kasama ang multa at iba pang parusa.","p":"Tama. Suspensyon nang hindi bababa sa anim na buwan."},"ar":{"q":"في Rhode Island، ماذا يحدث لرخصتك إذا رفضت إجراء فحص كيميائي للكحول؟","o":["لا شيء، الفحص اختياري لك","يتم إيقافها لمدة ستة أشهر على الأقل","تحصل على إنذار مكتوب فقط","يتم إيقافها لمدة أسبوع واحد"],"h1":"القيادة في Rhode Island تعني أنك وافقت مسبقًا على إجراء الفحص.","h2":"في Rhode Island، رفض الفحص الكيميائي للكحول أو المخدرات يؤدي إلى إيقاف الرخصة لمدة ستة أشهر على الأقل، مع غرامة وعقوبات أخرى.","p":"صحيح. إيقاف لمدة ستة أشهر على الأقل."},"ref":{"doc":"RI","page":58}},{"id":"ri-027","scope":"RI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Rhode Island, when must your headlights be on during the day?","o":["Only when driving inside a tunnel","Only when driving on an interstate highway","Whenever your windshield wipers are on because of the weather","Only when a police officer tells you"],"h1":"Think about rain, sleet or snow.","h2":"In Rhode Island, you must turn on your headlights any time your windshield wipers are in use because of rain, sleet or snow, as well as from sunset to sunrise.","p":"Right. Wipers on means headlights on."},"es":{"q":"En Rhode Island, ¿cuándo debe tener las luces delanteras encendidas durante el día?","o":["Solo cuando maneja dentro de un túnel","Solo cuando maneja en una autopista interestatal","Siempre que use los limpiaparabrisas por el mal tiempo","Solo cuando un policía se lo indique"],"h1":"Piense en la lluvia, el aguanieve o la nieve.","h2":"En Rhode Island, debe encender las luces delanteras siempre que use los limpiaparabrisas por lluvia, aguanieve o nieve, además de desde la puesta hasta la salida del sol.","p":"Correcto. Si usa los limpiaparabrisas, encienda las luces."},"zh":{"q":"在 Rhode Island，白天什么时候必须开大灯？","o":["只有在隧道里开车时","只有在州际高速公路上开车时","只要因为天气开了雨刷","只有警察叫你开的时候"],"h1":"想一想下雨、下冻雨或下雪的时候。","h2":"在 Rhode Island，只要因为下雨、冻雨或下雪而使用雨刷，就必须开大灯；从日落到日出也必须开大灯。","p":"对。开雨刷，就要开大灯。"},"vi":{"q":"Ở Rhode Island, khi nào bạn phải bật đèn pha vào ban ngày?","o":["Chỉ khi lái xe trong đường hầm","Chỉ khi lái xe trên xa lộ liên tiểu bang","Bất cứ khi nào cần gạt nước đang bật vì thời tiết","Chỉ khi cảnh sát bảo bạn"],"h1":"Hãy nghĩ đến mưa, mưa tuyết hoặc tuyết.","h2":"Ở Rhode Island, bạn phải bật đèn pha bất cứ khi nào dùng cần gạt nước vì mưa, mưa tuyết hoặc tuyết, và cả từ lúc mặt trời lặn đến lúc mặt trời mọc.","p":"Đúng. Bật cần gạt nước thì bật đèn pha."},"tl":{"q":"Sa Rhode Island, kailan dapat nakabukas ang headlights mo sa araw?","o":["Kapag nagmamaneho sa loob ng tunnel lamang","Kapag nagmamaneho sa interstate highway lamang","Tuwing nakabukas ang windshield wipers mo dahil sa panahon","Kapag sinabihan ka ng pulis lamang"],"h1":"Isipin ang ulan, sleet o niyebe.","h2":"Sa Rhode Island, dapat mong buksan ang headlights mo tuwing ginagamit mo ang windshield wipers dahil sa ulan, sleet o niyebe, at gayundin mula paglubog hanggang pagsikat ng araw.","p":"Tama. Kapag nakabukas ang wipers, nakabukas din ang headlights."},"ar":{"q":"في Rhode Island، متى يجب تشغيل المصابيح الأمامية أثناء النهار؟","o":["فقط عند القيادة داخل نفق","فقط عند القيادة على طريق سريع بين الولايات","كلما كانت ماسحات الزجاج الأمامي تعمل بسبب الطقس","فقط عندما يطلب منك ضابط شرطة ذلك"],"h1":"فكّر في المطر أو المطر المتجمد أو الثلج.","h2":"في Rhode Island، يجب أن تشغّل المصابيح الأمامية كلما استخدمت ماسحات الزجاج الأمامي بسبب المطر أو المطر المتجمد أو الثلج، وكذلك من غروب الشمس حتى شروقها.","p":"صحيح. إذا عملت الماسحات، تعمل المصابيح الأمامية."},"ref":{"doc":"RI","page":49}},{"id":"ri-028","scope":"RI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Rhode Island, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 8 feet","No closer than 15 feet","No closer than 25 feet"],"h1":"It is less than 10 feet.","h2":"In Rhode Island you may not park within 8 feet of a fire hydrant.","p":"Right. Stay at least 8 feet away from a fire hydrant."},"es":{"q":"En Rhode Island, ¿qué tan cerca de un hidrante de incendios puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 8 pies","No más cerca de 15 pies","No más cerca de 25 pies"],"h1":"Es menos de 10 pies.","h2":"En Rhode Island usted no puede estacionarse a menos de 8 pies de un hidrante de incendios.","p":"Correcto. Manténgase por lo menos a 8 pies de un hidrante."},"zh":{"q":"在 Rhode Island，停车时可以离消防栓多近？","o":["不能近于 5 英尺","不能近于 8 英尺","不能近于 15 英尺","不能近于 25 英尺"],"h1":"少于 10 英尺。","h2":"在 Rhode Island，你不可以在离消防栓 8 英尺以内的地方停车。","p":"对。离消防栓至少 8 英尺。"},"vi":{"q":"Ở Rhode Island, bạn được đậu xe gần trụ nước chữa cháy đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 8 feet","Không gần hơn 15 feet","Không gần hơn 25 feet"],"h1":"Khoảng cách này ít hơn 10 feet.","h2":"Ở Rhode Island, bạn không được đậu xe trong vòng 8 feet tính từ trụ nước chữa cháy.","p":"Đúng. Hãy cách trụ nước chữa cháy ít nhất 8 feet."},"tl":{"q":"Sa Rhode Island, gaano kalapit sa fire hydrant ka puwedeng pumarada?","o":["Hindi lalapit sa 5 talampakan","Hindi lalapit sa 8 talampakan","Hindi lalapit sa 15 talampakan","Hindi lalapit sa 25 talampakan"],"h1":"Mas kaunti ito sa 10 talampakan.","h2":"Sa Rhode Island, hindi ka puwedeng pumarada sa loob ng 8 talampakan mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 8 talampakan mula sa fire hydrant."},"ar":{"q":"في Rhode Island، ما أقرب مسافة يمكنك أن تركن فيها سيارتك من صنبور إطفاء الحريق؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 8 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 25 قدمًا"],"h1":"المسافة أقل من 10 أقدام.","h2":"في Rhode Island لا يجوز لك أن تركن سيارتك على مسافة أقل من 8 أقدام من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بعد 8 أقدام على الأقل من صنبور إطفاء الحريق."},"ref":{"doc":"RI","page":32}},{"id":"ri-029","scope":"RI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Rhode Island, how close to a stop sign or traffic light may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 15 feet","No closer than 30 feet"],"h1":"Other drivers need to see the sign or light from far away.","h2":"In Rhode Island you may not park within 30 feet of a stop sign, a traffic light or a flashing red or yellow light.","p":"Right. Park at least 30 feet from a stop sign or traffic light."},"es":{"q":"En Rhode Island, ¿qué tan cerca de una señal de alto o un semáforo puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 15 pies","No más cerca de 30 pies"],"h1":"Los otros conductores necesitan ver la señal o la luz desde lejos.","h2":"En Rhode Island usted no puede estacionarse a menos de 30 pies de una señal de alto, un semáforo o una luz roja o amarilla intermitente.","p":"Correcto. Estaciónese por lo menos a 30 pies de una señal de alto o un semáforo."},"zh":{"q":"在 Rhode Island，停车时可以离停车标志（stop sign）或红绿灯多近？","o":["不能近于 5 英尺","不能近于 10 英尺","不能近于 15 英尺","不能近于 30 英尺"],"h1":"其他司机需要从远处看到标志或灯。","h2":"在 Rhode Island，你不可以在离停车标志、红绿灯或闪烁的红灯、黄灯 30 英尺以内的地方停车。","p":"对。停车时离停车标志或红绿灯至少 30 英尺。"},"vi":{"q":"Ở Rhode Island, bạn được đậu xe gần biển báo dừng (stop sign) hoặc đèn giao thông đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 15 feet","Không gần hơn 30 feet"],"h1":"Các tài xế khác cần nhìn thấy biển báo hoặc đèn từ xa.","h2":"Ở Rhode Island, bạn không được đậu xe trong vòng 30 feet tính từ biển báo dừng, đèn giao thông hoặc đèn đỏ hay đèn vàng nhấp nháy.","p":"Đúng. Hãy đậu xe cách biển báo dừng hoặc đèn giao thông ít nhất 30 feet."},"tl":{"q":"Sa Rhode Island, gaano kalapit sa stop sign o traffic light ka puwedeng pumarada?","o":["Hindi lalapit sa 5 talampakan","Hindi lalapit sa 10 talampakan","Hindi lalapit sa 15 talampakan","Hindi lalapit sa 30 talampakan"],"h1":"Kailangang makita ng ibang driver ang sign o ilaw mula sa malayo.","h2":"Sa Rhode Island, hindi ka puwedeng pumarada sa loob ng 30 talampakan mula sa stop sign, traffic light, o kumikislap na pula o dilaw na ilaw.","p":"Tama. Pumarada nang hindi bababa sa 30 talampakan mula sa stop sign o traffic light."},"ar":{"q":"في Rhode Island، ما أقرب مسافة يمكنك أن تركن فيها سيارتك من إشارة التوقف (stop sign) أو إشارة المرور الضوئية؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 10 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 30 قدمًا"],"h1":"يحتاج السائقون الآخرون إلى رؤية الإشارة أو الضوء من بعيد.","h2":"في Rhode Island لا يجوز لك أن تركن سيارتك على مسافة أقل من 30 قدمًا من إشارة التوقف أو إشارة المرور الضوئية أو الضوء الأحمر أو الأصفر الوامض.","p":"صحيح. اركن سيارتك على بعد 30 قدمًا على الأقل من إشارة التوقف أو إشارة المرور الضوئية."},"ref":{"doc":"RI","page":32}},{"id":"ri-030","scope":"RI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Rhode Island, you are using high beams at night and following another car. When must you dim your lights?","o":["When you are within 200 feet of it","When you are within 50 feet of it","When you are within 1,000 feet of it","Only when it is raining"],"h1":"It is less than the 500 feet used for oncoming cars.","h2":"In Rhode Island you must dim your high beams when you follow another vehicle within 200 feet.","p":"Right. Dim your high beams when you are 200 feet or less behind another car."},"es":{"q":"En Rhode Island, usted lleva las luces altas de noche y va detrás de otro carro. ¿Cuándo debe bajar las luces?","o":["Cuando esté a menos de 200 pies de él","Cuando esté a menos de 50 pies de él","Cuando esté a menos de 1,000 pies de él","Solo cuando está lloviendo"],"h1":"Es menos que los 500 pies que se usan para los carros que vienen de frente.","h2":"En Rhode Island usted debe bajar las luces altas cuando va detrás de otro vehículo a menos de 200 pies.","p":"Correcto. Baje las luces altas cuando esté a 200 pies o menos detrás de otro carro."},"zh":{"q":"在 Rhode Island，你晚上开着远光灯，跟在另一辆车后面。你什么时候必须把灯调暗？","o":["在离它 200 英尺以内时","在离它 50 英尺以内时","在离它 1,000 英尺以内时","只有下雨时"],"h1":"它比对面来车用的 500 英尺要少。","h2":"在 Rhode Island，当你跟在另一辆车后面 200 英尺以内时，必须把远光灯调暗。","p":"对。当你在另一辆车后面 200 英尺或更近时，要把远光灯调暗。"},"vi":{"q":"Ở Rhode Island, bạn đang bật đèn pha (đèn chiếu xa) vào ban đêm và đi sau một xe khác. Khi nào bạn phải giảm đèn?","o":["Khi bạn cách xe đó trong vòng 200 feet","Khi bạn cách xe đó trong vòng 50 feet","Khi bạn cách xe đó trong vòng 1,000 feet","Chỉ khi trời mưa"],"h1":"Khoảng cách này ít hơn 500 feet dùng cho xe chạy ngược chiều.","h2":"Ở Rhode Island, bạn phải giảm đèn pha khi đi sau một xe khác trong vòng 200 feet.","p":"Đúng. Hãy giảm đèn pha khi bạn ở sau một xe khác 200 feet hoặc gần hơn."},"tl":{"q":"Sa Rhode Island, gumagamit ka ng high beams sa gabi at sumusunod sa ibang kotse. Kailan mo dapat hinaan ang iyong ilaw?","o":["Kapag nasa loob ka ng 200 talampakan mula rito","Kapag nasa loob ka ng 50 talampakan mula rito","Kapag nasa loob ka ng 1,000 talampakan mula rito","Kapag umuulan lang"],"h1":"Mas kaunti ito sa 500 talampakan na ginagamit para sa mga paparating na kotse.","h2":"Sa Rhode Island, dapat mong hinaan ang iyong high beams kapag sumusunod ka sa ibang sasakyan sa loob ng 200 talampakan.","p":"Tama. Hinaan ang high beams kapag 200 talampakan o mas malapit ka sa likod ng ibang kotse."},"ar":{"q":"في Rhode Island، تستخدم الأضواء العالية ليلًا وتسير خلف سيارة أخرى. متى يجب أن تخفّض أضواءك؟","o":["عندما تكون على بعد 200 قدم منها أو أقل","عندما تكون على بعد 50 قدمًا منها أو أقل","عندما تكون على بعد 1,000 قدم منها أو أقل","فقط عندما تمطر"],"h1":"المسافة أقل من 500 قدم المستخدمة مع السيارات القادمة من الاتجاه المقابل.","h2":"في Rhode Island يجب أن تخفّض أضواءك العالية عندما تسير خلف سيارة أخرى على بعد 200 قدم أو أقل.","p":"صحيح. خفّض أضواءك العالية عندما تكون على بعد 200 قدم أو أقل خلف سيارة أخرى."},"ref":{"doc":"RI","page":49}},{"id":"ri-031","scope":"RI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Rhode Island, a fire truck is going to a fire alarm. How close may you follow it?","o":["No closer than 50 feet","No closer than 200 feet","No closer than 500 feet","As close as you want if you are careful"],"h1":"Give it plenty of room, because it may stop or turn suddenly.","h2":"In Rhode Island you may not follow a fire truck going to an alarm any closer than 500 feet.","p":"Right. Stay at least 500 feet behind a fire truck on its way to an alarm."},"es":{"q":"En Rhode Island, un camión de bomberos va hacia una alarma de incendio. ¿Qué tan cerca puede seguirlo?","o":["No más cerca de 50 pies","No más cerca de 200 pies","No más cerca de 500 pies","Tan cerca como quiera si tiene cuidado"],"h1":"Dele mucho espacio, porque puede detenerse o dar vuelta de repente.","h2":"En Rhode Island usted no puede seguir a un camión de bomberos que va hacia una alarma a menos de 500 pies.","p":"Correcto. Quédese por lo menos a 500 pies detrás de un camión de bomberos que va a una alarma."},"zh":{"q":"在 Rhode Island，一辆消防车正在去处理火警。你跟在它后面可以多近？","o":["不能近于 50 英尺","不能近于 200 英尺","不能近于 500 英尺","只要小心，多近都可以"],"h1":"给它留很多空间，因为它可能会突然停下或转弯。","h2":"在 Rhode Island，跟在去处理火警的消防车后面时，不可以近于 500 英尺。","p":"对。跟在去处理火警的消防车后面时，至少保持 500 英尺。"},"vi":{"q":"Ở Rhode Island, một xe cứu hỏa đang đi đến nơi có báo cháy. Bạn được chạy theo sau nó gần đến mức nào?","o":["Không gần hơn 50 feet","Không gần hơn 200 feet","Không gần hơn 500 feet","Gần bao nhiêu cũng được nếu bạn cẩn thận"],"h1":"Hãy chừa nhiều khoảng trống, vì xe có thể dừng hoặc rẽ bất ngờ.","h2":"Ở Rhode Island, bạn không được chạy theo sau xe cứu hỏa đang đến nơi báo cháy gần hơn 500 feet.","p":"Đúng. Hãy ở sau xe cứu hỏa đang đến nơi báo cháy ít nhất 500 feet."},"tl":{"q":"Sa Rhode Island, may fire truck na papunta sa isang fire alarm. Gaano kalapit ka puwedeng sumunod dito?","o":["Hindi lalapit sa 50 talampakan","Hindi lalapit sa 200 talampakan","Hindi lalapit sa 500 talampakan","Kahit gaano kalapit basta mag-ingat ka"],"h1":"Bigyan ito ng maraming espasyo, dahil puwede itong biglang huminto o lumiko.","h2":"Sa Rhode Island, hindi ka puwedeng sumunod sa fire truck na papunta sa alarm nang mas malapit sa 500 talampakan.","p":"Tama. Manatili nang hindi bababa sa 500 talampakan sa likod ng fire truck na papunta sa alarm."},"ar":{"q":"في Rhode Island، شاحنة إطفاء متجهة إلى إنذار حريق. ما أقرب مسافة يمكنك أن تسير فيها خلفها؟","o":["ليس أقرب من 50 قدمًا","ليس أقرب من 200 قدم","ليس أقرب من 500 قدم","بأي مسافة تريدها إذا كنت حذرًا"],"h1":"اترك لها مسافة كبيرة، لأنها قد تتوقف أو تنعطف فجأة.","h2":"في Rhode Island لا يجوز لك أن تسير خلف شاحنة إطفاء متجهة إلى إنذار على مسافة أقرب من 500 قدم.","p":"صحيح. ابقَ على بعد 500 قدم على الأقل خلف شاحنة إطفاء في طريقها إلى إنذار."},"ref":{"doc":"RI","page":35}},{"id":"ri-032","scope":"RI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Rhode Island, what is the speed limit in a residential area when no other limit is posted?","o":["20 mph","25 mph","35 mph","40 mph"],"h1":"It is the same limit used in business districts.","h2":"In Rhode Island the speed limit in a residential area is 25 mph when no other limit is posted.","p":"Right. The limit in a residential area is 25 mph."},"es":{"q":"En Rhode Island, ¿cuál es el límite de velocidad en una zona residencial cuando no hay otro límite indicado?","o":["20 mph","25 mph","35 mph","40 mph"],"h1":"Es el mismo límite que en las zonas comerciales.","h2":"En Rhode Island el límite de velocidad en una zona residencial es de 25 mph cuando no hay otro límite indicado.","p":"Correcto. El límite en una zona residencial es de 25 mph."},"zh":{"q":"在 Rhode Island，如果没有标出其他限速，住宅区的限速是多少？","o":["20 mph","25 mph","35 mph","40 mph"],"h1":"它和商业区用的限速一样。","h2":"在 Rhode Island，如果没有标出其他限速，住宅区的限速是 25 mph。","p":"对。住宅区的限速是 25 mph。"},"vi":{"q":"Ở Rhode Island, tốc độ tối đa trong khu dân cư là bao nhiêu khi không có biển báo tốc độ khác?","o":["20 mph","25 mph","35 mph","40 mph"],"h1":"Đó là cùng tốc độ tối đa dùng trong khu kinh doanh.","h2":"Ở Rhode Island, tốc độ tối đa trong khu dân cư là 25 mph khi không có biển báo tốc độ khác.","p":"Đúng. Tốc độ tối đa trong khu dân cư là 25 mph."},"tl":{"q":"Sa Rhode Island, ano ang speed limit sa residential area kapag walang ibang limit na nakapaskil?","o":["20 mph","25 mph","35 mph","40 mph"],"h1":"Pareho ito sa limit na ginagamit sa mga business district.","h2":"Sa Rhode Island, ang speed limit sa residential area ay 25 mph kapag walang ibang limit na nakapaskil.","p":"Tama. Ang limit sa residential area ay 25 mph."},"ar":{"q":"في Rhode Island، ما حد السرعة في المنطقة السكنية عندما لا توجد لافتة بحد آخر؟","o":["20 mph","25 mph","35 mph","40 mph"],"h1":"هو نفس الحد المستخدم في المناطق التجارية.","h2":"في Rhode Island حد السرعة في المنطقة السكنية هو 25 mph عندما لا توجد لافتة بحد آخر.","p":"صحيح. حد السرعة في المنطقة السكنية هو 25 mph."},"ref":{"doc":"RI","page":35}},{"id":"sc-001","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, what is the youngest age to get a beginner's permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before the special restricted license.","h2":"In South Carolina you can get a beginner's permit at 15, after you pass the vision and knowledge tests.","p":"Right. The beginner's permit starts at 15."},"es":{"q":"En Carolina del Sur, ¿cuál es la edad mínima para obtener el permiso de principiante?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la licencia restringida especial.","h2":"En Carolina del Sur usted puede obtener el permiso de principiante a los 15 años, después de aprobar el examen de la vista y el examen de conocimientos.","p":"Correcto. El permiso de principiante empieza a los 15."},"zh":{"q":"在 South Carolina，最小几岁可以拿到初学者学习驾照（beginner's permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比特别限制驾照早一年。","h2":"在 South Carolina，你 15 岁通过视力考试和知识考试后，就可以拿到初学者学习驾照。","p":"对。初学者学习驾照从 15 岁开始。"},"vi":{"q":"Ở South Carolina, tuổi nhỏ nhất để lấy giấy phép tập lái (beginner's permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là một năm trước bằng lái hạn chế đặc biệt.","h2":"Ở South Carolina, bạn có thể lấy giấy phép tập lái lúc 15 tuổi, sau khi đậu bài kiểm tra thị lực và bài kiểm tra kiến thức.","p":"Đúng. Giấy phép tập lái bắt đầu từ 15 tuổi."},"tl":{"q":"Sa South Carolina, ano ang pinakabatang edad para makakuha ng permit ng baguhan (beginner's permit)?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ang espesyal na limitadong lisensya.","h2":"Sa South Carolina, makakakuha ka ng permit ng baguhan sa edad na 15, pagkatapos mong pumasa sa pagsusulit sa paningin at sa pagsusulit sa kaalaman.","p":"Tama. Nagsisimula ang permit ng baguhan sa 15."},"ar":{"q":"في South Carolina، ما أصغر عمر للحصول على تصريح المبتدئ (beginner's permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"إنه قبل الرخصة المقيدة الخاصة بسنة واحدة.","h2":"في South Carolina يمكنك الحصول على تصريح المبتدئ في عمر 15 سنة، بعد أن تنجح في فحص النظر واختبار المعرفة.","p":"صحيح. تصريح المبتدئ يبدأ من عمر 15 سنة."},"ref":{"doc":"SC","page":"1-4"}},{"id":"sc-002","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, who must supervise a driver with a beginner's permit?","o":["Any passenger 16 or older","Any adult with a car","A licensed driver 18 or older","A licensed driver 21 or older with at least one year of driving experience"],"h1":"The helper must be an adult with some experience behind the wheel.","h2":"A South Carolina permit holder must be supervised by a licensed driver who is at least 21 and has at least one year of driving experience.","p":"Right. 21 or older, with a year of experience."},"es":{"q":"En Carolina del Sur, ¿quién debe supervisar a un conductor con permiso de principiante?","o":["Cualquier pasajero de 16 años o más","Cualquier adulto con carro","Un conductor con licencia de 18 años o más","Un conductor con licencia de 21 años o más con por lo menos un año de experiencia"],"h1":"El acompañante debe ser un adulto con algo de experiencia al volante.","h2":"Quien tiene permiso en Carolina del Sur debe estar supervisado por un conductor con licencia de por lo menos 21 años y con por lo menos un año de experiencia manejando.","p":"Correcto. 21 años o más, con un año de experiencia."},"zh":{"q":"在 South Carolina，谁必须陪同持有初学者学习驾照的司机？","o":["任何 16 岁或以上的乘客","任何有车的成年人","18 岁或以上的持照司机","21 岁或以上、至少有一年驾驶经验的持照司机"],"h1":"陪同的人必须是有一些开车经验的成年人。","h2":"在 South Carolina，学习驾照持有人必须由至少 21 岁、至少有一年驾驶经验的持照司机陪同。","p":"对。21 岁或以上，有一年经验。"},"vi":{"q":"Ở South Carolina, ai phải giám sát người lái có giấy phép tập lái?","o":["Bất kỳ hành khách nào từ 16 tuổi trở lên","Bất kỳ người lớn nào có xe","Một người có bằng lái từ 18 tuổi trở lên","Một người có bằng lái từ 21 tuổi trở lên, có ít nhất một năm kinh nghiệm lái xe"],"h1":"Người giúp phải là người lớn có kinh nghiệm lái xe.","h2":"Ở South Carolina, người có giấy phép tập lái phải được giám sát bởi một người có bằng lái ít nhất 21 tuổi và có ít nhất một năm kinh nghiệm lái xe.","p":"Đúng. Từ 21 tuổi trở lên, có một năm kinh nghiệm."},"tl":{"q":"Sa South Carolina, sino ang dapat magbantay sa drayber na may permit ng baguhan?","o":["Kahit sinong pasahero na 16 o mas matanda","Kahit sinong adulto na may kotse","Isang drayber na may lisensya na 18 o mas matanda","Isang drayber na may lisensya na 21 o mas matanda at may hindi bababa sa isang taon na karanasan sa pagmamaneho"],"h1":"Ang tagabantay ay dapat adulto na may karanasan sa pagmamaneho.","h2":"Sa South Carolina, ang may hawak ng permit ay dapat bantayan ng drayber na may lisensya na hindi bababa sa 21 taong gulang at may hindi bababa sa isang taon na karanasan sa pagmamaneho.","p":"Tama. 21 o mas matanda, na may isang taon na karanasan."},"ar":{"q":"في South Carolina، من يجب أن يشرف على سائق معه تصريح المبتدئ؟","o":["أي راكب عمره 16 سنة أو أكثر","أي شخص بالغ عنده سيارة","سائق مرخص عمره 18 سنة أو أكثر","سائق مرخص عمره 21 سنة أو أكثر وعنده خبرة قيادة سنة واحدة على الأقل"],"h1":"يجب أن يكون المرافق شخصًا بالغًا عنده بعض الخبرة في القيادة.","h2":"في South Carolina يجب أن يشرف على صاحب التصريح سائق مرخص عمره 21 سنة على الأقل وعنده خبرة قيادة سنة واحدة على الأقل.","p":"صحيح. 21 سنة أو أكثر، مع سنة من الخبرة."},"ref":{"doc":"SC","page":"1-4"}},{"id":"sc-003","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, a permit holder wants to practice at 1 a.m. Who must be the supervisor?","o":["A licensed parent or guardian","Any licensed adult 21 or older","A driving instructor only","No one; practice is not allowed"],"h1":"Late at night, the rule is about family.","h2":"In South Carolina, a permit holder driving between midnight and 6 a.m. must be supervised by a licensed parent or guardian, or another adult the law allows, such as one with notarized permission from a parent.","p":"Right. A licensed parent or guardian after midnight."},"es":{"q":"En Carolina del Sur, quien tiene permiso quiere practicar a la 1 a.m. ¿Quién debe ser el supervisor?","o":["Un padre, madre o tutor con licencia","Cualquier adulto con licencia de 21 años o más","Solo un instructor de manejo","Nadie; no se permite practicar"],"h1":"De madrugada, la regla tiene que ver con la familia.","h2":"En Carolina del Sur, quien tiene permiso y maneja entre la medianoche y las 6 a.m. debe estar supervisado por su padre, madre o tutor con licencia, u otro adulto que la ley permite, como uno con permiso notariado de un padre.","p":"Correcto. Un padre o tutor con licencia después de la medianoche."},"zh":{"q":"在 South Carolina，学习驾照持有人想在凌晨 1 点练车。谁必须陪同？","o":["持有驾照的父母或监护人","任何 21 岁或以上的持照成年人","只能是驾驶教练","没有人；不允许练车"],"h1":"深夜的规定和家人有关。","h2":"在 South Carolina，学习驾照持有人在午夜到早上 6 点之间开车，必须由持有驾照的父母或监护人陪同，或由法律允许的其他成年人陪同，例如有父母公证许可的人。","p":"对。午夜以后要有持照的父母或监护人。"},"vi":{"q":"Ở South Carolina, người có giấy phép tập lái muốn tập lúc 1 giờ sáng. Ai phải giám sát?","o":["Cha mẹ hoặc người giám hộ có bằng lái","Bất kỳ người lớn nào có bằng lái từ 21 tuổi trở lên","Chỉ huấn luyện viên lái xe","Không ai cả; không được tập"],"h1":"Vào khuya, luật liên quan đến gia đình.","h2":"Ở South Carolina, người có giấy phép tập lái lái xe từ nửa đêm đến 6 giờ sáng phải được giám sát bởi cha mẹ hoặc người giám hộ có bằng lái, hoặc một người lớn khác mà luật cho phép, ví dụ người có giấy phép của cha mẹ được công chứng.","p":"Đúng. Sau nửa đêm phải có cha mẹ hoặc người giám hộ có bằng lái."},"tl":{"q":"Sa South Carolina, gustong magpraktis ng may hawak ng permit nang 1 a.m. Sino ang dapat magbantay?","o":["Magulang o tagapag-alaga na may lisensya","Kahit sinong adulto na may lisensya na 21 o mas matanda","Instruktor sa pagmamaneho lamang","Wala; hindi pinapayagan ang praktis"],"h1":"Sa hatinggabi, tungkol sa pamilya ang patakaran.","h2":"Sa South Carolina, ang may hawak ng permit na nagmamaneho mula hatinggabi hanggang 6 a.m. ay dapat bantayan ng magulang o tagapag-alaga na may lisensya, o ng ibang adulto na pinapayagan ng batas, gaya ng may notaryadong pahintulot mula sa magulang.","p":"Tama. Magulang o tagapag-alaga na may lisensya pagkalipas ng hatinggabi."},"ar":{"q":"في South Carolina، صاحب تصريح يريد أن يتدرب الساعة 1 بعد منتصف الليل. من يجب أن يكون المشرف؟","o":["أحد الوالدين أو الوصي المرخص","أي شخص بالغ مرخص عمره 21 سنة أو أكثر","مدرب قيادة فقط","لا أحد؛ التدريب غير مسموح"],"h1":"في وقت متأخر من الليل، القاعدة تتعلق بالعائلة.","h2":"في South Carolina، صاحب التصريح الذي يقود بين منتصف الليل والساعة 6 صباحًا يجب أن يشرف عليه أحد الوالدين أو الوصي المرخص، أو شخص بالغ آخر يسمح به القانون، مثل شخص معه إذن موثق من أحد الوالدين.","p":"صحيح. أحد الوالدين أو الوصي المرخص بعد منتصف الليل."},"ref":{"doc":"SC","page":"1-4"}},{"id":"sc-004","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, how long must a teen hold a beginner's permit before taking the road test?","o":["30 days","90 days","180 days","365 days"],"h1":"It is about six months.","h2":"A South Carolina driver with no experience must hold the beginner's permit for 180 days before the road test, unless they are 18 or older.","p":"Right. 180 days with the permit."},"es":{"q":"En Carolina del Sur, ¿cuánto tiempo debe tener un adolescente el permiso de principiante antes del examen de manejo?","o":["30 días","90 días","180 días","365 días"],"h1":"Son unos seis meses.","h2":"En Carolina del Sur, un conductor sin experiencia debe tener el permiso de principiante 180 días antes del examen de manejo, salvo que tenga 18 años o más.","p":"Correcto. 180 días con el permiso."},"zh":{"q":"在 South Carolina，青少年必须持有初学者学习驾照多久，才能参加路考？","o":["30 天","90 天","180 天","365 天"],"h1":"大约六个月。","h2":"在 South Carolina，没有驾驶经验的司机必须持有初学者学习驾照 180 天才能参加路考，18 岁或以上的人除外。","p":"对。持有学习驾照 180 天。"},"vi":{"q":"Ở South Carolina, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi thi lái trên đường?","o":["30 ngày","90 ngày","180 ngày","365 ngày"],"h1":"Khoảng sáu tháng.","h2":"Ở South Carolina, người chưa có kinh nghiệm lái xe phải giữ giấy phép tập lái 180 ngày trước khi thi lái trên đường, trừ khi họ từ 18 tuổi trở lên.","p":"Đúng. Giữ giấy phép 180 ngày."},"tl":{"q":"Sa South Carolina, gaano katagal dapat hawak ng tinedyer ang permit ng baguhan bago kumuha ng pagsusulit sa kalsada?","o":["30 araw","90 araw","180 araw","365 araw"],"h1":"Mga anim na buwan ito.","h2":"Sa South Carolina, ang drayber na walang karanasan ay dapat humawak ng permit ng baguhan nang 180 araw bago ang pagsusulit sa kalsada, maliban kung sila ay 18 o mas matanda.","p":"Tama. 180 araw na may permit."},"ar":{"q":"في South Carolina، كم مدة يجب أن يحمل المراهق تصريح المبتدئ قبل اختبار القيادة على الطريق؟","o":["30 يومًا","90 يومًا","180 يومًا","365 يومًا"],"h1":"إنها حوالي ستة أشهر.","h2":"في South Carolina، السائق الذي ليس عنده خبرة يجب أن يحمل تصريح المبتدئ 180 يومًا قبل اختبار القيادة على الطريق، إلا إذا كان عمره 18 سنة أو أكثر.","p":"صحيح. 180 يومًا مع التصريح."},"ref":{"doc":"SC","page":"1-4"}},{"id":"sc-005","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, how many hours of supervised practice must a teen complete before a conditional license?","o":["20 hours","40 hours","50 hours","60 hours"],"h1":"It is less than a full week of work hours.","h2":"A South Carolina teen must complete at least 40 hours of supervised practice before a conditional license.","p":"Right. 40 hours of practice."},"es":{"q":"En Carolina del Sur, ¿cuántas horas de práctica supervisada debe completar un adolescente antes de la licencia condicional?","o":["20 horas","40 horas","50 horas","60 horas"],"h1":"Son menos que una semana completa de horas de trabajo.","h2":"Un adolescente en Carolina del Sur debe completar por lo menos 40 horas de práctica supervisada antes de la licencia condicional.","p":"Correcto. 40 horas de práctica."},"zh":{"q":"在 South Carolina，青少年拿条件驾照（conditional license）前，必须完成多少小时有人陪同的练习？","o":["20 小时","40 小时","50 小时","60 小时"],"h1":"它比一整周的工作时间少。","h2":"在 South Carolina，青少年必须完成至少 40 小时有人陪同的练习，才能拿条件驾照。","p":"对。练习 40 小时。"},"vi":{"q":"Ở South Carolina, thiếu niên phải tập lái có giám sát bao nhiêu giờ trước khi lấy bằng lái có điều kiện (conditional license)?","o":["20 giờ","40 giờ","50 giờ","60 giờ"],"h1":"Ít hơn số giờ làm việc của một tuần.","h2":"Ở South Carolina, thiếu niên phải tập lái có giám sát ít nhất 40 giờ trước khi lấy bằng lái có điều kiện.","p":"Đúng. Tập 40 giờ."},"tl":{"q":"Sa South Carolina, ilang oras ng praktis na may bantay ang dapat tapusin ng tinedyer bago makakuha ng kondisyonal na lisensya (conditional license)?","o":["20 oras","40 oras","50 oras","60 oras"],"h1":"Mas kaunti ito sa oras ng trabaho sa isang buong linggo.","h2":"Sa South Carolina, ang tinedyer ay dapat tumapos ng hindi bababa sa 40 oras ng praktis na may bantay bago makakuha ng kondisyonal na lisensya.","p":"Tama. 40 oras ng praktis."},"ar":{"q":"في South Carolina، كم ساعة من التدريب تحت الإشراف يجب أن يكملها المراهق قبل الرخصة المشروطة (conditional license)؟","o":["20 ساعة","40 ساعة","50 ساعة","60 ساعة"],"h1":"إنها أقل من ساعات العمل في أسبوع كامل.","h2":"في South Carolina يجب أن يكمل المراهق 40 ساعة على الأقل من التدريب تحت الإشراف قبل الرخصة المشروطة.","p":"صحيح. 40 ساعة من التدريب."},"ref":{"doc":"SC","page":"1-6"}},{"id":"sc-006","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, how many of the 40 practice hours must be driven in darkness?","o":["None","2 hours","5 hours","10 hours"],"h1":"It is one quarter of the total.","h2":"At least 10 of the 40 practice hours in South Carolina must be driven in darkness.","p":"Right. Ten hours after dark."},"es":{"q":"En Carolina del Sur, ¿cuántas de las 40 horas de práctica deben manejarse en la oscuridad?","o":["Ninguna","2 horas","5 horas","10 horas"],"h1":"Es la cuarta parte del total.","h2":"Por lo menos 10 de las 40 horas de práctica en Carolina del Sur deben manejarse en la oscuridad.","p":"Correcto. Diez horas de noche."},"zh":{"q":"在 South Carolina，40 小时练习中有多少小时必须在天黑时开？","o":["不需要","2 小时","5 小时","10 小时"],"h1":"它是总数的四分之一。","h2":"在 South Carolina，40 小时练习中至少有 10 小时必须在天黑时开。","p":"对。天黑后开 10 小时。"},"vi":{"q":"Ở South Carolina, trong 40 giờ tập lái, bao nhiêu giờ phải lái khi trời tối?","o":["Không giờ nào","2 giờ","5 giờ","10 giờ"],"h1":"Đó là một phần tư tổng số giờ.","h2":"Ở South Carolina, ít nhất 10 trong 40 giờ tập lái phải lái khi trời tối.","p":"Đúng. Mười giờ sau khi trời tối."},"tl":{"q":"Sa South Carolina, ilan sa 40 oras ng praktis ang dapat imaneho sa dilim?","o":["Wala","2 oras","5 oras","10 oras"],"h1":"Isang-kapat ito ng kabuuan.","h2":"Sa South Carolina, hindi bababa sa 10 sa 40 oras ng praktis ang dapat imaneho sa dilim.","p":"Tama. Sampung oras pagkadilim."},"ar":{"q":"في South Carolina، كم ساعة من ساعات التدريب الـ 40 يجب أن تكون في الظلام؟","o":["ولا ساعة","2 ساعة","5 ساعات","10 ساعات"],"h1":"إنها ربع المجموع.","h2":"في South Carolina يجب أن تكون 10 ساعات على الأقل من ساعات التدريب الـ 40 في الظلام.","p":"صحيح. عشر ساعات بعد حلول الظلام."},"ref":{"doc":"SC","page":"1-6"}},{"id":"sc-007","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, until what time may a conditional license holder drive alone in standard time (not daylight saving time)?","o":["Midnight","9 p.m.","6 p.m.","10 p.m."],"h1":"It is early in the evening.","h2":"A South Carolina conditional license holder may drive alone from 6 a.m. until 6 p.m. in standard time.","p":"Right. Alone until 6 p.m."},"es":{"q":"En Carolina del Sur, ¿hasta qué hora puede manejar solo quien tiene licencia condicional en horario normal (no de verano)?","o":["Medianoche","9 p.m.","6 p.m.","10 p.m."],"h1":"Es temprano por la tarde.","h2":"Quien tiene licencia condicional en Carolina del Sur puede manejar solo de 6 a.m. a 6 p.m. en horario normal.","p":"Correcto. Solo hasta las 6 p.m."},"zh":{"q":"在 South Carolina，在标准时间（不是夏令时），条件驾照持有人可以独自开车到几点？","o":["午夜","晚上 9 点","晚上 6 点","晚上 10 点"],"h1":"是傍晚比较早的时候。","h2":"在 South Carolina，在标准时间，条件驾照持有人可以从早上 6 点到晚上 6 点独自开车。","p":"对。独自开车到晚上 6 点。"},"vi":{"q":"Ở South Carolina, vào giờ chuẩn (không phải giờ mùa hè), người có bằng lái có điều kiện được lái một mình đến mấy giờ?","o":["Nửa đêm","9 giờ tối","6 giờ chiều","10 giờ tối"],"h1":"Đó là lúc chiều tối sớm.","h2":"Ở South Carolina, vào giờ chuẩn, người có bằng lái có điều kiện được lái một mình từ 6 giờ sáng đến 6 giờ chiều.","p":"Đúng. Lái một mình đến 6 giờ chiều."},"tl":{"q":"Sa South Carolina, hanggang anong oras puwedeng magmaneho nang mag-isa ang may hawak ng kondisyonal na lisensya sa standard time (hindi daylight saving time)?","o":["Hatinggabi","9 p.m.","6 p.m.","10 p.m."],"h1":"Maaga pa ito sa gabi.","h2":"Sa South Carolina, ang may hawak ng kondisyonal na lisensya ay puwedeng magmaneho nang mag-isa mula 6 a.m. hanggang 6 p.m. sa standard time.","p":"Tama. Mag-isa hanggang 6 p.m."},"ar":{"q":"في South Carolina، حتى أي ساعة يمكن لصاحب الرخصة المشروطة أن يقود وحده في التوقيت العادي (وليس التوقيت الصيفي)؟","o":["منتصف الليل","9 مساءً","6 مساءً","10 مساءً"],"h1":"إنها في أول المساء.","h2":"في South Carolina يمكن لصاحب الرخصة المشروطة أن يقود وحده من 6 صباحًا حتى 6 مساءً في التوقيت العادي.","p":"صحيح. وحده حتى 6 مساءً."},"ref":{"doc":"SC","page":"1-7"}},{"id":"sc-008","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, during daylight saving time, until what time may a conditional license holder drive alone?","o":["8 p.m.","6 p.m.","10 p.m.","Midnight"],"h1":"It is two hours later than in winter.","h2":"During daylight saving time, a South Carolina conditional license holder may drive alone until 8 p.m.","p":"Right. Until 8 p.m. in daylight saving time."},"es":{"q":"En Carolina del Sur, durante el horario de verano, ¿hasta qué hora puede manejar solo quien tiene licencia condicional?","o":["8 p.m.","6 p.m.","10 p.m.","Medianoche"],"h1":"Son dos horas más tarde que en invierno.","h2":"Durante el horario de verano, quien tiene licencia condicional en Carolina del Sur puede manejar solo hasta las 8 p.m.","p":"Correcto. Hasta las 8 p.m. en horario de verano."},"zh":{"q":"在 South Carolina，在夏令时期间，条件驾照持有人可以独自开车到几点？","o":["晚上 8 点","晚上 6 点","晚上 10 点","午夜"],"h1":"它比冬天晚两个小时。","h2":"在夏令时期间，South Carolina 的条件驾照持有人可以独自开车到晚上 8 点。","p":"对。夏令时可以开到晚上 8 点。"},"vi":{"q":"Ở South Carolina, vào giờ mùa hè, người có bằng lái có điều kiện được lái một mình đến mấy giờ?","o":["8 giờ tối","6 giờ chiều","10 giờ tối","Nửa đêm"],"h1":"Muộn hơn mùa đông hai giờ.","h2":"Vào giờ mùa hè, người có bằng lái có điều kiện ở South Carolina được lái một mình đến 8 giờ tối.","p":"Đúng. Đến 8 giờ tối vào giờ mùa hè."},"tl":{"q":"Sa South Carolina, sa panahon ng daylight saving time, hanggang anong oras puwedeng magmaneho nang mag-isa ang may hawak ng kondisyonal na lisensya?","o":["8 p.m.","6 p.m.","10 p.m.","Hatinggabi"],"h1":"Dalawang oras itong mas huli kaysa sa taglamig.","h2":"Sa panahon ng daylight saving time, ang may hawak ng kondisyonal na lisensya sa South Carolina ay puwedeng magmaneho nang mag-isa hanggang 8 p.m.","p":"Tama. Hanggang 8 p.m. sa daylight saving time."},"ar":{"q":"في South Carolina، في فترة التوقيت الصيفي، حتى أي ساعة يمكن لصاحب الرخصة المشروطة أن يقود وحده؟","o":["8 مساءً","6 مساءً","10 مساءً","منتصف الليل"],"h1":"إنها بعد وقت الشتاء بساعتين.","h2":"في فترة التوقيت الصيفي، يمكن لصاحب الرخصة المشروطة في South Carolina أن يقود وحده حتى 8 مساءً.","p":"صحيح. حتى 8 مساءً في التوقيت الصيفي."},"ref":{"doc":"SC","page":"1-7"}},{"id":"sc-009","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, a conditional license holder wants to drive at 9 p.m. Who must be in the car?","o":["A friend with a permit","A licensed driver 21 or older","Any passenger 18 or older","No one; driving after dark is banned"],"h1":"An experienced adult driver allows evening driving.","h2":"After the evening limit, a South Carolina conditional license holder may drive until midnight with a licensed driver 21 or older in the car.","p":"Right. A licensed driver 21 or older."},"es":{"q":"En Carolina del Sur, quien tiene licencia condicional quiere manejar a las 9 p.m. ¿Quién debe ir en el carro?","o":["Un amigo con permiso","Un conductor con licencia de 21 años o más","Cualquier pasajero de 18 años o más","Nadie; está prohibido manejar de noche"],"h1":"Un conductor adulto con experiencia permite manejar por la noche.","h2":"Después del límite de la tarde, quien tiene licencia condicional en Carolina del Sur puede manejar hasta la medianoche con un conductor con licencia de 21 años o más en el carro.","p":"Correcto. Un conductor con licencia de 21 años o más."},"zh":{"q":"在 South Carolina，条件驾照持有人想在晚上 9 点开车。车里必须有谁？","o":["一个有学习驾照的朋友","21 岁或以上的持照司机","任何 18 岁或以上的乘客","没有人；天黑后禁止开车"],"h1":"有经验的成年司机在车上，晚上就可以开车。","h2":"过了晚上的时间限制后，South Carolina 的条件驾照持有人如果车上有 21 岁或以上的持照司机，可以开车到午夜。","p":"对。21 岁或以上的持照司机。"},"vi":{"q":"Ở South Carolina, người có bằng lái có điều kiện muốn lái xe lúc 9 giờ tối. Ai phải ở trong xe?","o":["Một người bạn có giấy phép tập lái","Một người có bằng lái từ 21 tuổi trở lên","Bất kỳ hành khách nào từ 18 tuổi trở lên","Không ai cả; cấm lái xe sau khi trời tối"],"h1":"Có một người lớn lái xe nhiều kinh nghiệm thì được lái buổi tối.","h2":"Sau giới hạn buổi tối, người có bằng lái có điều kiện ở South Carolina được lái đến nửa đêm nếu có một người có bằng lái từ 21 tuổi trở lên trong xe.","p":"Đúng. Một người có bằng lái từ 21 tuổi trở lên."},"tl":{"q":"Sa South Carolina, gustong magmaneho ng may hawak ng kondisyonal na lisensya nang 9 p.m. Sino ang dapat nasa kotse?","o":["Isang kaibigan na may permit","Isang drayber na may lisensya na 21 o mas matanda","Kahit sinong pasahero na 18 o mas matanda","Wala; bawal magmaneho pagkadilim"],"h1":"Kapag may kasamang adultong drayber na may karanasan, puwedeng magmaneho sa gabi.","h2":"Pagkalipas ng limitasyon sa gabi, ang may hawak ng kondisyonal na lisensya sa South Carolina ay puwedeng magmaneho hanggang hatinggabi kung may kasamang drayber na may lisensya na 21 o mas matanda sa kotse.","p":"Tama. Isang drayber na may lisensya na 21 o mas matanda."},"ar":{"q":"في South Carolina، صاحب رخصة مشروطة يريد أن يقود الساعة 9 مساءً. من يجب أن يكون في السيارة؟","o":["صديق معه تصريح","سائق مرخص عمره 21 سنة أو أكثر","أي راكب عمره 18 سنة أو أكثر","لا أحد؛ القيادة بعد الظلام ممنوعة"],"h1":"وجود سائق بالغ عنده خبرة يسمح بالقيادة في المساء.","h2":"بعد حد المساء، يمكن لصاحب الرخصة المشروطة في South Carolina أن يقود حتى منتصف الليل إذا كان معه في السيارة سائق مرخص عمره 21 سنة أو أكثر.","p":"صحيح. سائق مرخص عمره 21 سنة أو أكثر."},"ref":{"doc":"SC","page":"1-8"}},{"id":"sc-010","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, a conditional license holder drives between midnight and 6 a.m. Who must be in the car?","o":["Any licensed adult","A friend over 18","A police officer","A licensed parent or guardian"],"h1":"Late at night, the rule is about family.","h2":"Between midnight and 6 a.m., a South Carolina conditional license holder may drive only with a licensed parent or guardian, or another adult the law allows, in the car.","p":"Right. A licensed parent or guardian."},"es":{"q":"En Carolina del Sur, quien tiene licencia condicional maneja entre la medianoche y las 6 a.m. ¿Quién debe ir en el carro?","o":["Cualquier adulto con licencia","Un amigo mayor de 18","Un policía","Un padre, madre o tutor con licencia"],"h1":"De madrugada, la regla tiene que ver con la familia.","h2":"Entre la medianoche y las 6 a.m., quien tiene licencia condicional en Carolina del Sur solo puede manejar con su padre, madre o tutor con licencia, u otro adulto que la ley permite, en el carro.","p":"Correcto. Un padre o tutor con licencia."},"zh":{"q":"在 South Carolina，条件驾照持有人在午夜到早上 6 点之间开车。车里必须有谁？","o":["任何持照成年人","一个 18 岁以上的朋友","一名警察","持有驾照的父母或监护人"],"h1":"深夜的规定和家人有关。","h2":"在午夜到早上 6 点之间，South Carolina 的条件驾照持有人只能在车上有持照的父母或监护人，或法律允许的其他成年人时开车。","p":"对。持有驾照的父母或监护人。"},"vi":{"q":"Ở South Carolina, người có bằng lái có điều kiện lái xe từ nửa đêm đến 6 giờ sáng. Ai phải ở trong xe?","o":["Bất kỳ người lớn nào có bằng lái","Một người bạn trên 18 tuổi","Một cảnh sát","Cha mẹ hoặc người giám hộ có bằng lái"],"h1":"Vào khuya, luật liên quan đến gia đình.","h2":"Từ nửa đêm đến 6 giờ sáng, người có bằng lái có điều kiện ở South Carolina chỉ được lái khi có cha mẹ hoặc người giám hộ có bằng lái, hoặc một người lớn khác mà luật cho phép, trong xe.","p":"Đúng. Cha mẹ hoặc người giám hộ có bằng lái."},"tl":{"q":"Sa South Carolina, nagmamaneho ang may hawak ng kondisyonal na lisensya mula hatinggabi hanggang 6 a.m. Sino ang dapat nasa kotse?","o":["Kahit sinong adulto na may lisensya","Isang kaibigan na lampas 18","Isang pulis","Magulang o tagapag-alaga na may lisensya"],"h1":"Sa hatinggabi, tungkol sa pamilya ang patakaran.","h2":"Mula hatinggabi hanggang 6 a.m., ang may hawak ng kondisyonal na lisensya sa South Carolina ay puwedeng magmaneho lamang kung may kasamang magulang o tagapag-alaga na may lisensya, o ibang adulto na pinapayagan ng batas, sa kotse.","p":"Tama. Magulang o tagapag-alaga na may lisensya."},"ar":{"q":"في South Carolina، صاحب رخصة مشروطة يقود بين منتصف الليل والساعة 6 صباحًا. من يجب أن يكون في السيارة؟","o":["أي شخص بالغ مرخص","صديق عمره أكثر من 18 سنة","شرطي","أحد الوالدين أو الوصي المرخص"],"h1":"في وقت متأخر من الليل، القاعدة تتعلق بالعائلة.","h2":"بين منتصف الليل والساعة 6 صباحًا، يمكن لصاحب الرخصة المشروطة في South Carolina أن يقود فقط إذا كان معه في السيارة أحد الوالدين أو الوصي المرخص، أو شخص بالغ آخر يسمح به القانون.","p":"صحيح. أحد الوالدين أو الوصي المرخص."},"ref":{"doc":"SC","page":"1-8"}},{"id":"sc-011","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, how many passengers under 21 may a conditional license holder carry without an adult, not counting family or students going to school?","o":["None","One","Two","Four"],"h1":"It is a small number, but more than one.","h2":"A South Carolina conditional license holder may carry no more than two passengers under 21, unless a licensed adult 21 or older rides along or the riders are family or students going to or from school.","p":"Right. No more than two."},"es":{"q":"En Carolina del Sur, ¿cuántos pasajeros menores de 21 años puede llevar sin un adulto quien tiene licencia condicional, sin contar familiares ni estudiantes que van a la escuela?","o":["Ninguno","Uno","Dos","Cuatro"],"h1":"Es un número pequeño, pero más de uno.","h2":"Quien tiene licencia condicional en Carolina del Sur puede llevar no más de dos pasajeros menores de 21 años, salvo que lo acompañe un adulto con licencia de 21 años o más, o que sean familiares o estudiantes que van o vuelven de la escuela.","p":"Correcto. No más de dos."},"zh":{"q":"在 South Carolina，没有成年人在车上时，条件驾照持有人最多可以载几名 21 岁以下的乘客（不算家人或上学的学生）？","o":["不能载","一名","两名","四名"],"h1":"数量很少，但不止一名。","h2":"在 South Carolina，条件驾照持有人最多只能载两名 21 岁以下的乘客，除非车上有 21 岁或以上的持照成年人，或乘客是家人或上下学的学生。","p":"对。最多两名。"},"vi":{"q":"Ở South Carolina, khi không có người lớn, người có bằng lái có điều kiện được chở bao nhiêu hành khách dưới 21 tuổi, không tính người trong gia đình hoặc học sinh đi học?","o":["Không ai","Một","Hai","Bốn"],"h1":"Đó là số nhỏ, nhưng nhiều hơn một.","h2":"Ở South Carolina, người có bằng lái có điều kiện được chở không quá hai hành khách dưới 21 tuổi, trừ khi có một người lớn có bằng lái từ 21 tuổi trở lên đi cùng, hoặc hành khách là người trong gia đình hoặc học sinh đi học hay đi học về.","p":"Đúng. Không quá hai."},"tl":{"q":"Sa South Carolina, ilang pasahero na wala pang 21 ang puwedeng isakay ng may hawak ng kondisyonal na lisensya nang walang adulto, hindi kasama ang pamilya o mga estudyanteng papasok sa paaralan?","o":["Wala","Isa","Dalawa","Apat"],"h1":"Maliit na bilang ito, pero higit sa isa.","h2":"Sa South Carolina, ang may hawak ng kondisyonal na lisensya ay puwedeng magsakay ng hindi hihigit sa dalawang pasahero na wala pang 21, maliban kung may kasamang adulto na may lisensya na 21 o mas matanda, o ang mga pasahero ay pamilya o mga estudyanteng papunta o pauwi mula sa paaralan.","p":"Tama. Hindi hihigit sa dalawa."},"ar":{"q":"في South Carolina، كم راكبًا عمره أقل من 21 سنة يمكن لصاحب الرخصة المشروطة أن يحمل بدون شخص بالغ، من غير أفراد العائلة أو الطلاب الذاهبين إلى المدرسة؟","o":["ولا أحد","واحد","اثنان","أربعة"],"h1":"إنه عدد صغير، لكنه أكثر من واحد.","h2":"في South Carolina لا يمكن لصاحب الرخصة المشروطة أن يحمل أكثر من راكبين عمرهما أقل من 21 سنة، إلا إذا كان معه شخص بالغ مرخص عمره 21 سنة أو أكثر، أو كان الركاب من العائلة أو طلابًا ذاهبين إلى المدرسة أو عائدين منها.","p":"صحيح. ليس أكثر من اثنين."},"ref":{"doc":"SC","page":"1-7"}},{"id":"sc-012","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, at what age can a teen who meets the conditional license rules get a special restricted license instead?","o":["16 years old","15 years old","17 years old","18 years old"],"h1":"The only difference from the conditional license is age.","h2":"A South Carolina teen who is 16 but not yet 17 and meets the conditional license rules can get a special restricted license.","p":"Right. The special restricted license is for age 16."},"es":{"q":"En Carolina del Sur, ¿a qué edad puede un adolescente que cumple las reglas de la licencia condicional obtener la licencia restringida especial?","o":["16 años","15 años","17 años","18 años"],"h1":"La única diferencia con la licencia condicional es la edad.","h2":"Un adolescente en Carolina del Sur que tiene 16 años pero todavía no 17 y cumple las reglas de la licencia condicional puede obtener la licencia restringida especial.","p":"Correcto. La licencia restringida especial es para los 16 años."},"zh":{"q":"在 South Carolina，符合条件驾照规定的青少年几岁可以改拿特别限制驾照（special restricted license）？","o":["16 岁","15 岁","17 岁","18 岁"],"h1":"它和条件驾照唯一的不同是年龄。","h2":"在 South Carolina，16 岁但还不到 17 岁、并符合条件驾照规定的青少年，可以拿特别限制驾照。","p":"对。特别限制驾照是给 16 岁的人。"},"vi":{"q":"Ở South Carolina, thiếu niên đáp ứng các quy định của bằng lái có điều kiện được lấy bằng lái hạn chế đặc biệt (special restricted license) thay vào đó ở tuổi nào?","o":["16 tuổi","15 tuổi","17 tuổi","18 tuổi"],"h1":"Điểm khác duy nhất so với bằng lái có điều kiện là tuổi.","h2":"Ở South Carolina, thiếu niên 16 tuổi nhưng chưa 17 tuổi và đáp ứng các quy định của bằng lái có điều kiện có thể lấy bằng lái hạn chế đặc biệt.","p":"Đúng. Bằng lái hạn chế đặc biệt dành cho tuổi 16."},"tl":{"q":"Sa South Carolina, sa anong edad puwedeng kumuha ng espesyal na limitadong lisensya (special restricted license) ang tinedyer na sumusunod sa mga patakaran ng kondisyonal na lisensya?","o":["16 taong gulang","15 taong gulang","17 taong gulang","18 taong gulang"],"h1":"Ang tanging pagkakaiba sa kondisyonal na lisensya ay ang edad.","h2":"Sa South Carolina, ang tinedyer na 16 pero hindi pa 17 at sumusunod sa mga patakaran ng kondisyonal na lisensya ay puwedeng kumuha ng espesyal na limitadong lisensya.","p":"Tama. Ang espesyal na limitadong lisensya ay para sa edad na 16."},"ar":{"q":"في South Carolina، في أي عمر يمكن للمراهق الذي يستوفي شروط الرخصة المشروطة أن يحصل بدلًا منها على الرخصة المقيدة الخاصة (special restricted license)؟","o":["16 سنة","15 سنة","17 سنة","18 سنة"],"h1":"الفرق الوحيد عن الرخصة المشروطة هو العمر.","h2":"في South Carolina، المراهق الذي عمره 16 سنة ولم يبلغ 17 بعد ويستوفي شروط الرخصة المشروطة يمكنه الحصول على الرخصة المقيدة الخاصة.","p":"صحيح. الرخصة المقيدة الخاصة لعمر 16 سنة."},"ref":{"doc":"SC","page":"1-8"}},{"id":"sc-013","scope":"SC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Carolina, what blood alcohol level breaks the zero tolerance law for a driver under 21?","o":["0.08","0.02","0.05","0.10"],"h1":"It is much lower than the adult limit.","h2":"In South Carolina a driver under 21 with a blood alcohol level of 0.02 breaks the zero tolerance law.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Carolina del Sur, ¿qué nivel de alcohol en la sangre viola la ley de tolerancia cero para un conductor menor de 21 años?","o":["0.08","0.02","0.05","0.10"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Carolina del Sur un conductor menor de 21 años con un nivel de alcohol en la sangre de 0.02 viola la ley de tolerancia cero.","p":"Correcto. Para menores de 21, el límite es 0.02."},"zh":{"q":"在 South Carolina，21 岁以下的司机血液酒精浓度达到多少就违反零容忍法（zero tolerance law）？","o":["0.08","0.02","0.05","0.10"],"h1":"它比成年人的上限低很多。","h2":"在 South Carolina，21 岁以下的司机血液酒精浓度达到 0.02 就违反零容忍法。","p":"对。21 岁以下，上限是 0.02。"},"vi":{"q":"Ở South Carolina, nồng độ cồn trong máu bao nhiêu thì người lái dưới 21 tuổi vi phạm luật không khoan nhượng (zero tolerance law)?","o":["0.08","0.02","0.05","0.10"],"h1":"Thấp hơn nhiều so với giới hạn của người lớn.","h2":"Ở South Carolina, người lái dưới 21 tuổi có nồng độ cồn trong máu 0.02 là vi phạm luật không khoan nhượng.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa South Carolina, anong antas ng alak sa dugo ang lumalabag sa batas na zero tolerance (zero tolerance law) para sa drayber na wala pang 21?","o":["0.08","0.02","0.05","0.10"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon para sa adulto.","h2":"Sa South Carolina, ang drayber na wala pang 21 na may antas ng alak sa dugo na 0.02 ay lumalabag sa batas na zero tolerance.","p":"Tama. Kapag wala pang 21, ang limitasyon ay 0.02."},"ar":{"q":"في South Carolina، ما نسبة الكحول في الدم التي تخالف قانون عدم التسامح (zero tolerance law) لسائق عمره أقل من 21 سنة؟","o":["0.08","0.02","0.05","0.10"],"h1":"إنها أقل بكثير من حد البالغين.","h2":"في South Carolina، السائق الذي عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02 يخالف قانون عدم التسامح.","p":"صحيح. لمن عمره أقل من 21 سنة، الحد هو 0.02."},"ref":{"doc":"SC","page":"3-7"}},{"id":"sc-014","scope":"SC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Carolina, what happens on a first zero tolerance offense for a driver under 21?","o":["Only a warning","A one-week suspension","A five-year suspension","A suspension of at least three months"],"h1":"It is a few months.","h2":"In South Carolina, a driver under 21 with a blood alcohol level of 0.02 or more loses the right to drive right away, for at least three months.","p":"Right. At least three months without driving."},"es":{"q":"En Carolina del Sur, ¿qué pasa en la primera infracción de tolerancia cero de un conductor menor de 21 años?","o":["Solo una advertencia","Una suspensión de una semana","Una suspensión de cinco años","Una suspensión de por lo menos tres meses"],"h1":"Son unos pocos meses.","h2":"En Carolina del Sur, un conductor menor de 21 años con un nivel de alcohol en la sangre de 0.02 o más pierde el derecho a manejar de inmediato, por lo menos por tres meses.","p":"Correcto. Por lo menos tres meses sin manejar."},"zh":{"q":"在 South Carolina，21 岁以下的司机第一次违反零容忍法，会怎样？","o":["只是警告","吊销驾照一周","吊销驾照五年","吊销驾照至少三个月"],"h1":"是几个月。","h2":"在 South Carolina，21 岁以下的司机血液酒精浓度达到 0.02 或以上，会马上失去开车的权利，至少三个月。","p":"对。至少三个月不能开车。"},"vi":{"q":"Ở South Carolina, chuyện gì xảy ra khi người lái dưới 21 tuổi vi phạm luật không khoan nhượng lần đầu?","o":["Chỉ bị cảnh cáo","Bị treo bằng một tuần","Bị treo bằng năm năm","Bị treo bằng ít nhất ba tháng"],"h1":"Đó là vài tháng.","h2":"Ở South Carolina, người lái dưới 21 tuổi có nồng độ cồn trong máu từ 0.02 trở lên mất quyền lái xe ngay lập tức, ít nhất ba tháng.","p":"Đúng. Ít nhất ba tháng không được lái."},"tl":{"q":"Sa South Carolina, ano ang mangyayari sa unang paglabag sa zero tolerance ng drayber na wala pang 21?","o":["Babala lamang","Isang linggong suspensyon","Limang taong suspensyon","Suspensyon na hindi bababa sa tatlong buwan"],"h1":"Ilang buwan ito.","h2":"Sa South Carolina, ang drayber na wala pang 21 na may antas ng alak sa dugo na 0.02 o higit pa ay agad na nawawalan ng karapatang magmaneho, nang hindi bababa sa tatlong buwan.","p":"Tama. Hindi bababa sa tatlong buwan na walang pagmamaneho."},"ar":{"q":"في South Carolina، ماذا يحدث في أول مخالفة لقانون عدم التسامح لسائق عمره أقل من 21 سنة؟","o":["تحذير فقط","إيقاف الرخصة لمدة أسبوع","إيقاف الرخصة لمدة خمس سنوات","إيقاف الرخصة لمدة ثلاثة أشهر على الأقل"],"h1":"إنها بضعة أشهر.","h2":"في South Carolina، السائق الذي عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02 أو أكثر يفقد حق القيادة فورًا، لمدة ثلاثة أشهر على الأقل.","p":"صحيح. ثلاثة أشهر على الأقل بدون قيادة."},"ref":{"doc":"SC","page":"3-7"}},{"id":"sc-015","scope":"SC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Carolina, can police stop a driver only for holding a phone while driving?","o":["No, only with another violation","Only on interstates","Yes, it is a primary offense","Only in school zones"],"h1":"The hands-free law is enforced on its own.","h2":"South Carolina's hands-free law is a primary offense, so police can stop a driver they clearly see holding a phone, with no other reason.","p":"Right. Holding a phone is enough for a stop."},"es":{"q":"En Carolina del Sur, ¿puede la policía detener a un conductor solo por sostener el teléfono mientras maneja?","o":["No, solo con otra infracción","Solo en interestatales","Sí, es una infracción primaria","Solo en zonas escolares"],"h1":"La ley de manos libres se aplica por sí sola.","h2":"La ley de manos libres de Carolina del Sur es una infracción primaria, así que la policía puede detener a un conductor que ve claramente con el teléfono en la mano, sin otra razón.","p":"Correcto. Sostener el teléfono basta para que lo detengan."},"zh":{"q":"在 South Carolina，警察可以只因为司机开车时手拿手机就拦车吗？","o":["不可以，必须还有其他违规","只在州际公路上","可以，这是主要违规（primary offense）","只在学校区域"],"h1":"免提法本身就可以执法。","h2":"South Carolina 的免提法是主要违规，所以警察清楚看到司机手拿手机时，不需要其他理由就可以拦车。","p":"对。手拿手机就足以被拦车。"},"vi":{"q":"Ở South Carolina, cảnh sát có thể chặn xe chỉ vì người lái cầm điện thoại khi lái không?","o":["Không, chỉ khi có vi phạm khác","Chỉ trên xa lộ liên bang","Có, đó là vi phạm chính (primary offense)","Chỉ trong khu vực trường học"],"h1":"Luật rảnh tay được thi hành riêng.","h2":"Luật rảnh tay của South Carolina là vi phạm chính, nên cảnh sát có thể chặn người lái mà họ thấy rõ đang cầm điện thoại, không cần lý do nào khác.","p":"Đúng. Cầm điện thoại là đủ để bị chặn xe."},"tl":{"q":"Sa South Carolina, puwede bang patigilin ng pulis ang drayber dahil lamang may hawak siyang telepono habang nagmamaneho?","o":["Hindi, kailangan may iba pang paglabag","Sa interstate lamang","Oo, ito ay pangunahing paglabag (primary offense)","Sa school zone lamang"],"h1":"Ang batas na hands-free ay ipinapatupad nang mag-isa.","h2":"Ang batas na hands-free ng South Carolina ay pangunahing paglabag, kaya puwedeng patigilin ng pulis ang drayber na malinaw nilang nakikitang may hawak na telepono, kahit walang ibang dahilan.","p":"Tama. Sapat na ang paghawak ng telepono para patigilin ka."},"ar":{"q":"في South Carolina، هل يمكن للشرطة أن توقف السائق فقط لأنه يمسك الهاتف أثناء القيادة؟","o":["لا، فقط مع مخالفة أخرى","فقط على الطرق السريعة بين الولايات","نعم، إنها مخالفة أساسية (primary offense)","فقط في مناطق المدارس"],"h1":"قانون عدم استخدام اليدين يُطبَّق وحده.","h2":"قانون عدم استخدام اليدين في South Carolina مخالفة أساسية، لذلك يمكن للشرطة أن توقف السائق الذي تراه بوضوح يمسك الهاتف، بدون أي سبب آخر.","p":"صحيح. إمساك الهاتف يكفي لإيقافك."},"ref":{"doc":"SC","page":null}},{"id":"sc-016","scope":"SC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Carolina, how may you make a phone call while driving?","o":["Hands-free, such as a car speaker or earpiece","Holding the phone to your ear","Holding the phone on speaker","Holding the phone, if you drive slowly"],"h1":"Your hands stay on the wheel.","h2":"South Carolina allows phone calls while driving only hands-free, such as through the car's speaker or an earpiece.","p":"Right. Hands-free calls only."},"es":{"q":"En Carolina del Sur, ¿cómo puede hacer una llamada mientras maneja?","o":["Con manos libres, como la bocina del carro o un audífono","Sosteniendo el teléfono en la oreja","Sosteniendo el teléfono en altavoz","Sosteniendo el teléfono, si maneja despacio"],"h1":"Sus manos se quedan en el volante.","h2":"Carolina del Sur permite llamadas mientras maneja solo con manos libres, como la bocina del carro o un audífono.","p":"Correcto. Solo llamadas con manos libres."},"zh":{"q":"在 South Carolina，开车时怎样才可以打电话？","o":["用免提，例如车上的扬声器或耳机","把手机拿到耳边","手拿手机开扬声器","手拿手机，只要开得慢"],"h1":"你的手要放在方向盘上。","h2":"在 South Carolina，开车时只能用免提打电话，例如通过车上的扬声器或耳机。","p":"对。只能用免提打电话。"},"vi":{"q":"Ở South Carolina, bạn được gọi điện thoại khi lái xe bằng cách nào?","o":["Rảnh tay, ví dụ loa trong xe hoặc tai nghe","Cầm điện thoại áp vào tai","Cầm điện thoại bật loa ngoài","Cầm điện thoại, nếu lái chậm"],"h1":"Tay bạn luôn ở trên vô lăng.","h2":"Ở South Carolina, khi lái xe chỉ được gọi điện thoại bằng cách rảnh tay, ví dụ qua loa trong xe hoặc tai nghe.","p":"Đúng. Chỉ gọi điện rảnh tay."},"tl":{"q":"Sa South Carolina, paano ka puwedeng tumawag sa telepono habang nagmamaneho?","o":["Hands-free, gaya ng speaker ng kotse o earpiece","Hawak ang telepono sa tainga","Hawak ang telepono na naka-speaker","Hawak ang telepono, kung mabagal ang takbo"],"h1":"Nananatili ang mga kamay mo sa manibela.","h2":"Sa South Carolina, puwede lamang tumawag habang nagmamaneho kung hands-free, gaya ng sa speaker ng kotse o sa earpiece.","p":"Tama. Hands-free na tawag lamang."},"ar":{"q":"في South Carolina، كيف يمكنك إجراء مكالمة هاتفية أثناء القيادة؟","o":["بدون استخدام اليدين، مثل سماعة السيارة أو سماعة الأذن","بإمساك الهاتف على أذنك","بإمساك الهاتف مع مكبر الصوت","بإمساك الهاتف، إذا كنت تقود ببطء"],"h1":"يداك تبقيان على المقود.","h2":"في South Carolina يُسمح بالمكالمات أثناء القيادة فقط بدون استخدام اليدين، مثل سماعة السيارة أو سماعة الأذن.","p":"صحيح. مكالمات بدون استخدام اليدين فقط."},"ref":{"doc":"SC","page":"3-5"}},{"id":"sc-017","scope":"SC","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In South Carolina, you approach a stopped emergency vehicle with flashing lights. What should you do if it is safe?","o":["Keep your speed and lane","Slow down and change to a lane not next to it","Stop in your lane","Use the shoulder to pass"],"h1":"Give it a whole lane of space.","h2":"In South Carolina you must slow down and, if possible, change to a lane that is not next to a stopped emergency vehicle with flashing lights.","p":"Right. Slow down and move over."},"es":{"q":"En Carolina del Sur, se acerca a un vehículo de emergencia detenido con luces intermitentes. ¿Qué debe hacer si es seguro?","o":["Mantener su velocidad y su carril","Bajar la velocidad y cambiarse a un carril que no esté junto a él","Detenerse en su carril","Usar el acotamiento para pasar"],"h1":"Déjele un carril completo de espacio.","h2":"En Carolina del Sur usted debe bajar la velocidad y, si es posible, cambiarse a un carril que no esté junto al vehículo de emergencia detenido con luces intermitentes.","p":"Correcto. Bajar la velocidad y cambiarse de carril."},"zh":{"q":"在 South Carolina，你接近一辆停着并闪灯的紧急车辆。如果安全，你应该怎么做？","o":["保持车速和车道","减速，并换到不紧挨着它的车道","在你的车道上停车","从路肩超过去"],"h1":"给它让出一整条车道的空间。","h2":"在 South Carolina，你必须减速，并且如果可能，换到不紧挨着停着并闪灯的紧急车辆的车道。","p":"对。减速并让出车道。"},"vi":{"q":"Ở South Carolina, bạn đến gần một xe cấp cứu đang dừng và nháy đèn. Nếu an toàn, bạn nên làm gì?","o":["Giữ tốc độ và làn đường","Giảm tốc độ và đổi sang làn không sát bên nó","Dừng lại trong làn của bạn","Đi lên lề đường để vượt"],"h1":"Chừa cho nó trống cả một làn đường.","h2":"Ở South Carolina, bạn phải giảm tốc độ và, nếu có thể, đổi sang làn không sát bên xe cấp cứu đang dừng và nháy đèn.","p":"Đúng. Giảm tốc độ và tránh sang làn khác."},"tl":{"q":"Sa South Carolina, papalapit ka sa nakahintong sasakyang pang-emergency na may kumikislap na ilaw. Ano ang dapat mong gawin kung ligtas?","o":["Panatilihin ang bilis at linya mo","Bumagal at lumipat sa linyang hindi katabi nito","Huminto sa linya mo","Dumaan sa gilid ng kalsada para lumampas"],"h1":"Bigyan ito ng isang buong linya na espasyo.","h2":"Sa South Carolina, dapat kang bumagal at, kung puwede, lumipat sa linyang hindi katabi ng nakahintong sasakyang pang-emergency na may kumikislap na ilaw.","p":"Tama. Bumagal at lumipat ng linya."},"ar":{"q":"في South Carolina، تقترب من مركبة طوارئ متوقفة وأضواؤها تومض. ماذا يجب أن تفعل إذا كان ذلك آمنًا؟","o":["حافظ على سرعتك ومسارك","خفف السرعة وانتقل إلى مسار ليس بجانبها","توقف في مسارك","استخدم كتف الطريق لتتجاوزها"],"h1":"اترك لها مسارًا كاملًا فارغًا.","h2":"في South Carolina يجب أن تخفف السرعة، وإذا أمكن، تنتقل إلى مسار ليس بجانب مركبة الطوارئ المتوقفة التي تومض أضواؤها.","p":"صحيح. خفف السرعة وابتعد إلى مسار آخر."},"ref":{"doc":"SC","page":"10-15"}},{"id":"sc-018","scope":"SC","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In South Carolina, you cannot safely change lanes away from a stopped emergency vehicle. What must you do?","o":["Speed up to pass quickly","Stop completely","Honk as you pass","Slow down and keep a safe speed"],"h1":"If moving over is not possible, there is still one thing to do.","h2":"In South Carolina, when you cannot safely change lanes, you must slow down and keep a safe speed as you pass a stopped emergency vehicle.","p":"Right. Slow down when you cannot move over."},"es":{"q":"En Carolina del Sur, no puede cambiarse de carril con seguridad para alejarse de un vehículo de emergencia detenido. ¿Qué debe hacer?","o":["Acelerar para pasar rápido","Detenerse por completo","Tocar la bocina al pasar","Bajar la velocidad y mantener una velocidad segura"],"h1":"Si no puede cambiarse, todavía hay algo que hacer.","h2":"En Carolina del Sur, cuando no puede cambiarse de carril con seguridad, debe bajar la velocidad y mantener una velocidad segura al pasar un vehículo de emergencia detenido.","p":"Correcto. Bajar la velocidad cuando no puede cambiarse."},"zh":{"q":"在 South Carolina，你不能安全地换道离开停着的紧急车辆。你必须怎么做？","o":["加速快点超过","完全停车","经过时按喇叭","减速，保持安全车速"],"h1":"如果不能换道，还有一件事要做。","h2":"在 South Carolina，当你不能安全换道时，经过停着的紧急车辆时必须减速，并保持安全车速。","p":"对。不能换道时要减速。"},"vi":{"q":"Ở South Carolina, bạn không thể đổi làn an toàn để tránh xa một xe cấp cứu đang dừng. Bạn phải làm gì?","o":["Tăng tốc để vượt nhanh","Dừng hẳn lại","Bấm còi khi đi qua","Giảm tốc độ và giữ tốc độ an toàn"],"h1":"Nếu không tránh sang làn khác được, vẫn còn một việc phải làm.","h2":"Ở South Carolina, khi không thể đổi làn an toàn, bạn phải giảm tốc độ và giữ tốc độ an toàn khi đi qua xe cấp cứu đang dừng.","p":"Đúng. Giảm tốc độ khi không thể tránh sang làn khác."},"tl":{"q":"Sa South Carolina, hindi ka ligtas na makalipat ng linya palayo sa nakahintong sasakyang pang-emergency. Ano ang dapat mong gawin?","o":["Bumilis para mabilis na lumampas","Huminto nang tuluyan","Bumusina habang dumadaan","Bumagal at panatilihin ang ligtas na bilis"],"h1":"Kung hindi puwedeng lumipat ng linya, may isa pang dapat gawin.","h2":"Sa South Carolina, kapag hindi ka ligtas na makalipat ng linya, dapat kang bumagal at panatilihin ang ligtas na bilis habang dumadaan sa nakahintong sasakyang pang-emergency.","p":"Tama. Bumagal kapag hindi ka makalipat ng linya."},"ar":{"q":"في South Carolina، لا يمكنك أن تغير المسار بأمان بعيدًا عن مركبة طوارئ متوقفة. ماذا يجب أن تفعل؟","o":["زد السرعة لتتجاوز بسرعة","توقف تمامًا","استخدم البوق وأنت تمر","خفف السرعة وحافظ على سرعة آمنة"],"h1":"إذا لم يمكنك الابتعاد إلى مسار آخر، يبقى شيء واحد يجب فعله.","h2":"في South Carolina، عندما لا يمكنك تغيير المسار بأمان، يجب أن تخفف السرعة وتحافظ على سرعة آمنة وأنت تمر بمركبة الطوارئ المتوقفة.","p":"صحيح. خفف السرعة عندما لا يمكنك الابتعاد."},"ref":{"doc":"SC","page":"10-15"}},{"id":"sc-019","scope":"SC","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In South Carolina, on a highway with at least two lanes in each direction, you meet a stopped school bus coming the other way. What must you do?","o":["Stop until the bus moves","Stop only if there is no median","You do not have to stop, but go with caution","Stop and wait for the driver's signal"],"h1":"The number of lanes matters more than the median.","h2":"On a South Carolina highway with at least two lanes in each direction, traffic going the opposite way does not have to stop for a school bus, whatever the median, but should go with caution.","p":"Right. Oncoming traffic may pass with caution."},"es":{"q":"En Carolina del Sur, en una carretera con por lo menos dos carriles en cada sentido, usted se encuentra con un autobús escolar detenido que viene en sentido contrario. ¿Qué debe hacer?","o":["Detenerse hasta que el autobús avance","Detenerse solo si no hay camellón","No tiene que detenerse, pero avance con cuidado","Detenerse y esperar la señal del chofer"],"h1":"El número de carriles importa más que el camellón.","h2":"En una carretera de Carolina del Sur con por lo menos dos carriles en cada sentido, el tráfico en sentido contrario no tiene que detenerse por un autobús escolar, haya o no camellón, pero debe avanzar con cuidado.","p":"Correcto. El tráfico contrario puede pasar con cuidado."},"zh":{"q":"在 South Carolina，在每个方向至少有两条车道的公路上，你遇到对面方向一辆停着的校车。你必须怎么做？","o":["停车，直到校车开走","只有没有中间隔离带时才停车","你不用停车，但要小心行驶","停车，等司机的手势"],"h1":"车道的数量比中间隔离带更重要。","h2":"在 South Carolina，每个方向至少有两条车道的公路上，对面方向的车辆不论有没有中间隔离带，都不用为校车停车，但应该小心行驶。","p":"对。对面来车可以小心通过。"},"vi":{"q":"Ở South Carolina, trên xa lộ có ít nhất hai làn mỗi chiều, bạn gặp một xe buýt trường học đang dừng ở chiều ngược lại. Bạn phải làm gì?","o":["Dừng lại cho đến khi xe buýt chạy","Chỉ dừng nếu không có dải phân cách","Bạn không phải dừng, nhưng hãy đi cẩn thận","Dừng lại và chờ tín hiệu của tài xế"],"h1":"Số làn đường quan trọng hơn dải phân cách.","h2":"Trên xa lộ ở South Carolina có ít nhất hai làn mỗi chiều, xe đi chiều ngược lại không phải dừng cho xe buýt trường học, dù có dải phân cách hay không, nhưng nên đi cẩn thận.","p":"Đúng. Xe đi ngược chiều có thể đi qua cẩn thận."},"tl":{"q":"Sa South Carolina, sa highway na may hindi bababa sa dalawang linya sa bawat direksyon, nakasalubong mo ang nakahintong school bus mula sa kabilang direksyon. Ano ang dapat mong gawin?","o":["Huminto hanggang umandar ang bus","Huminto lamang kung walang median","Hindi mo kailangang huminto, pero mag-ingat sa pagdaan","Huminto at hintayin ang senyas ng drayber"],"h1":"Mas mahalaga ang bilang ng linya kaysa sa median.","h2":"Sa highway sa South Carolina na may hindi bababa sa dalawang linya sa bawat direksyon, ang trapiko sa kabilang direksyon ay hindi kailangang huminto para sa school bus, may median man o wala, pero dapat mag-ingat sa pagdaan.","p":"Tama. Ang kasalubong na trapiko ay puwedeng dumaan nang may pag-iingat."},"ar":{"q":"في South Carolina، على طريق سريع فيه مساران على الأقل في كل اتجاه، تقابل حافلة مدرسية متوقفة قادمة من الاتجاه المعاكس. ماذا يجب أن تفعل؟","o":["توقف حتى تتحرك الحافلة","توقف فقط إذا لم يكن هناك فاصل في الوسط","ليس عليك أن تتوقف، لكن تقدم بحذر","توقف وانتظر إشارة السائق"],"h1":"عدد المسارات أهم من الفاصل في الوسط.","h2":"على طريق سريع في South Carolina فيه مساران على الأقل في كل اتجاه، السيارات في الاتجاه المعاكس ليس عليها أن تتوقف للحافلة المدرسية، سواء كان هناك فاصل في الوسط أم لا، لكن يجب أن تتقدم بحذر.","p":"صحيح. السيارات القادمة من الاتجاه المعاكس يمكنها أن تمر بحذر."},"ref":{"doc":"SC","page":"7-10"}},{"id":"sc-020","scope":"SC","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In South Carolina, on a four-lane highway, you are behind a school bus that stops with its red lights flashing. What must you do?","o":["Pass it carefully on the left","Stop","Slow to 15 mph and pass","Stop only if a child is in the road"],"h1":"Traffic going the same way as the bus never passes it.","h2":"On a South Carolina four-lane highway, traffic going the same direction as a stopped school bus must stop.","p":"Right. You stop behind the bus."},"es":{"q":"En Carolina del Sur, en una carretera de cuatro carriles, usted va detrás de un autobús escolar que se detiene con las luces rojas intermitentes. ¿Qué debe hacer?","o":["Rebasarlo con cuidado por la izquierda","Detenerse","Bajar a 15 mph y pasar","Detenerse solo si hay un niño en el camino"],"h1":"El tráfico que va en el mismo sentido que el autobús nunca lo rebasa.","h2":"En una carretera de cuatro carriles de Carolina del Sur, el tráfico que va en el mismo sentido que un autobús escolar detenido debe detenerse.","p":"Correcto. Usted se detiene detrás del autobús."},"zh":{"q":"在 South Carolina，在四车道公路上，你跟在一辆校车后面，校车停下并闪着红灯。你必须怎么做？","o":["从左边小心超过","停车","减速到 15 mph 再超过","只有孩子在路上时才停车"],"h1":"和校车同方向的车辆永远不能超过它。","h2":"在 South Carolina 的四车道公路上，和停着的校车同方向的车辆必须停车。","p":"对。你要在校车后面停车。"},"vi":{"q":"Ở South Carolina, trên xa lộ bốn làn, bạn đi sau một xe buýt trường học dừng lại và nháy đèn đỏ. Bạn phải làm gì?","o":["Vượt cẩn thận bên trái","Dừng lại","Giảm còn 15 mph và vượt","Chỉ dừng nếu có trẻ em trên đường"],"h1":"Xe đi cùng chiều với xe buýt không bao giờ được vượt nó.","h2":"Trên xa lộ bốn làn ở South Carolina, xe đi cùng chiều với xe buýt trường học đang dừng phải dừng lại.","p":"Đúng. Bạn dừng lại sau xe buýt."},"tl":{"q":"Sa South Carolina, sa highway na may apat na linya, nasa likod ka ng school bus na huminto na kumikislap ang pulang ilaw. Ano ang dapat mong gawin?","o":["Lampasan ito nang maingat sa kaliwa","Huminto","Bumagal sa 15 mph at lumampas","Huminto lamang kung may bata sa kalsada"],"h1":"Ang trapiko na kapareho ng direksyon ng bus ay hindi kailanman lumalampas dito.","h2":"Sa highway sa South Carolina na may apat na linya, ang trapiko na kapareho ng direksyon ng nakahintong school bus ay dapat huminto.","p":"Tama. Huminto ka sa likod ng bus."},"ar":{"q":"في South Carolina، على طريق سريع من أربعة مسارات، أنت خلف حافلة مدرسية توقفت وأضواؤها الحمراء تومض. ماذا يجب أن تفعل؟","o":["تجاوزها بحذر من اليسار","توقف","خفف السرعة إلى 15 mph وتجاوزها","توقف فقط إذا كان هناك طفل في الطريق"],"h1":"السيارات التي تسير في نفس اتجاه الحافلة لا تتجاوزها أبدًا.","h2":"على طريق سريع من أربعة مسارات في South Carolina، يجب أن تتوقف السيارات التي تسير في نفس اتجاه الحافلة المدرسية المتوقفة.","p":"صحيح. تتوقف خلف الحافلة."},"ref":{"doc":"SC","page":"7-9"}},{"id":"sc-021","scope":"SC","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In South Carolina, what is the highest speed limit on interstate highways?","o":["55 mph","60 mph","75 mph","70 mph"],"h1":"It is lower than in some western states.","h2":"The highest speed limit on South Carolina interstate highways is 70 mph, where signs show it.","p":"Right. 70 mph on interstates."},"es":{"q":"En Carolina del Sur, ¿cuál es el límite de velocidad más alto en las autopistas interestatales?","o":["55 mph","60 mph","75 mph","70 mph"],"h1":"Es más bajo que en algunos estados del oeste.","h2":"El límite de velocidad más alto en las autopistas interestatales de Carolina del Sur es de 70 millas por hora, donde las señales lo indican.","p":"Correcto. 70 mph en las interestatales."},"zh":{"q":"在 South Carolina，州际公路的最高限速是多少？","o":["55 mph","60 mph","75 mph","70 mph"],"h1":"它比一些西部州低。","h2":"在 South Carolina，州际公路的最高限速是 70 mph，以标志显示的为准。","p":"对。州际公路 70 mph。"},"vi":{"q":"Ở South Carolina, tốc độ tối đa cao nhất trên xa lộ liên bang (interstate) là bao nhiêu?","o":["55 mph","60 mph","75 mph","70 mph"],"h1":"Thấp hơn so với một số tiểu bang miền tây.","h2":"Tốc độ tối đa cao nhất trên xa lộ liên bang ở South Carolina là 70 mph, ở nơi có biển báo ghi như vậy.","p":"Đúng. 70 mph trên xa lộ liên bang."},"tl":{"q":"Sa South Carolina, ano ang pinakamataas na speed limit sa mga interstate highway?","o":["55 mph","60 mph","75 mph","70 mph"],"h1":"Mas mababa ito kaysa sa ilang estado sa kanluran.","h2":"Ang pinakamataas na speed limit sa mga interstate highway sa South Carolina ay 70 mph, kung saan ito ipinapakita ng mga karatula.","p":"Tama. 70 mph sa mga interstate."},"ar":{"q":"في South Carolina، ما أعلى حد للسرعة على الطرق السريعة بين الولايات (interstate)؟","o":["55 mph","60 mph","75 mph","70 mph"],"h1":"إنه أقل مما في بعض الولايات الغربية.","h2":"أعلى حد للسرعة على الطرق السريعة بين الولايات في South Carolina هو 70 mph، حيث تُظهره اللافتات.","p":"صحيح. 70 mph على الطرق السريعة بين الولايات."},"ref":{"doc":"SC","page":null}},{"id":"sc-022","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, how many points on a driver's record lead to a license suspension for a driver 17 or older?","o":["4 points","6 points","12 points","20 points"],"h1":"At 6 points you only get a warning letter.","h2":"In South Carolina, a driver 17 or older gets a warning letter at 6 points, and the license is suspended when the total reaches 12 points or more.","p":"Right. 12 points means a suspension."},"es":{"q":"En Carolina del Sur, ¿cuántos puntos en el historial llevan a la suspensión de la licencia de un conductor de 17 años o más?","o":["4 puntos","6 puntos","12 puntos","20 puntos"],"h1":"Con 6 puntos solo recibe una carta de advertencia.","h2":"En Carolina del Sur, un conductor de 17 años o más recibe una carta de advertencia con 6 puntos, y la licencia se suspende cuando el total llega a 12 puntos o más.","p":"Correcto. Con 12 puntos se suspende la licencia."},"zh":{"q":"在 South Carolina，17 岁或以上的司机驾驶记录上有多少分会被吊销驾照？","o":["4 分","6 分","12 分","20 分"],"h1":"到 6 分时，你只会收到一封警告信。","h2":"在 South Carolina，17 岁或以上的司机到 6 分时会收到警告信，总分达到 12 分或以上时驾照会被吊销。","p":"对。12 分就会被吊销驾照。"},"vi":{"q":"Ở South Carolina, người lái từ 17 tuổi trở lên bị bao nhiêu điểm trong hồ sơ lái xe thì bị treo bằng lái?","o":["4 điểm","6 điểm","12 điểm","20 điểm"],"h1":"Ở 6 điểm bạn chỉ nhận một thư cảnh cáo.","h2":"Ở South Carolina, người lái từ 17 tuổi trở lên nhận thư cảnh cáo khi có 6 điểm, và bị treo bằng lái khi tổng số điểm lên đến 12 điểm trở lên.","p":"Đúng. 12 điểm là bị treo bằng lái."},"tl":{"q":"Sa South Carolina, ilang puntos sa rekord ng drayber ang nagdudulot ng suspensyon ng lisensya para sa drayber na 17 o mas matanda?","o":["4 na puntos","6 na puntos","12 puntos","20 puntos"],"h1":"Sa 6 na puntos, sulat ng babala lang ang matatanggap mo.","h2":"Sa South Carolina, ang drayber na 17 o mas matanda ay nakakatanggap ng sulat ng babala sa 6 na puntos, at sinususpinde ang lisensya kapag umabot ang kabuuan sa 12 puntos o higit pa.","p":"Tama. Ang 12 puntos ay nangangahulugang suspensyon."},"ar":{"q":"في South Carolina، كم نقطة في سجل السائق تؤدي إلى إيقاف الرخصة للسائق الذي عمره 17 سنة أو أكثر؟","o":["4 نقاط","6 نقاط","12 نقطة","20 نقطة"],"h1":"عند 6 نقاط تحصل فقط على رسالة تحذير.","h2":"في South Carolina، السائق الذي عمره 17 سنة أو أكثر يحصل على رسالة تحذير عند 6 نقاط، وتُوقَف رخصته عندما يصل المجموع إلى 12 نقطة أو أكثر.","p":"صحيح. 12 نقطة تعني إيقاف الرخصة."},"ref":{"doc":"SC","page":"1-19"}},{"id":"sc-023","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, how many points will get a beginner's permit or conditional license suspended?","o":["6 points or more","2 points or more","10 points or more","15 points or more"],"h1":"New drivers have a lower limit than adult drivers.","h2":"In South Carolina, a holder of a beginner's permit, conditional license or special restricted license who gets 6 or more points has the driving privilege suspended.","p":"Right. 6 points is the limit for new drivers."},"es":{"q":"En Carolina del Sur, ¿cuántos puntos hacen que se suspenda un permiso de principiante o una licencia condicional?","o":["6 puntos o más","2 puntos o más","10 puntos o más","15 puntos o más"],"h1":"Los conductores nuevos tienen un límite más bajo que los adultos.","h2":"En Carolina del Sur, quien tiene un permiso de principiante, una licencia condicional o una licencia restringida especial y acumula 6 puntos o más pierde el privilegio de manejar por suspensión.","p":"Correcto. 6 puntos es el límite para conductores nuevos."},"zh":{"q":"在 South Carolina，初学者学习驾照或条件驾照有多少分会被吊销？","o":["6 分或以上","2 分或以上","10 分或以上","15 分或以上"],"h1":"新司机的上限比成年司机低。","h2":"在 South Carolina，持有初学者学习驾照、条件驾照或特别限制驾照的人，如果有 6 分或以上，开车的权利就会被吊销。","p":"对。新司机的上限是 6 分。"},"vi":{"q":"Ở South Carolina, bao nhiêu điểm thì giấy phép tập lái hoặc bằng lái có điều kiện bị treo?","o":["6 điểm trở lên","2 điểm trở lên","10 điểm trở lên","15 điểm trở lên"],"h1":"Người mới lái có giới hạn thấp hơn người lái trưởng thành.","h2":"Ở South Carolina, người có giấy phép tập lái, bằng lái có điều kiện hoặc bằng lái hạn chế đặc biệt mà bị 6 điểm trở lên thì bị treo quyền lái xe.","p":"Đúng. 6 điểm là giới hạn cho người mới lái."},"tl":{"q":"Sa South Carolina, ilang puntos ang magpapasuspinde sa permit ng baguhan o kondisyonal na lisensya?","o":["6 na puntos o higit pa","2 puntos o higit pa","10 puntos o higit pa","15 puntos o higit pa"],"h1":"Mas mababa ang limitasyon ng mga bagong drayber kaysa sa mga adultong drayber.","h2":"Sa South Carolina, ang may hawak ng permit ng baguhan, kondisyonal na lisensya o espesyal na limitadong lisensya na nagkaroon ng 6 o higit pang puntos ay sinususpinde ang pribilehiyong magmaneho.","p":"Tama. Ang 6 na puntos ang limitasyon para sa mga bagong drayber."},"ar":{"q":"في South Carolina، كم نقطة تؤدي إلى إيقاف تصريح المبتدئ أو الرخصة المشروطة؟","o":["6 نقاط أو أكثر","2 نقطة أو أكثر","10 نقاط أو أكثر","15 نقطة أو أكثر"],"h1":"الحد للسائقين الجدد أقل من الحد للسائقين البالغين.","h2":"في South Carolina، صاحب تصريح المبتدئ أو الرخصة المشروطة أو الرخصة المقيدة الخاصة الذي يحصل على 6 نقاط أو أكثر يُوقَف حقه في القيادة.","p":"صحيح. 6 نقاط هي الحد للسائقين الجدد."},"ref":{"doc":"SC","page":"1-19"}},{"id":"sc-024","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, what happens to the points from a traffic ticket one year after the violation?","o":["They double","They stay the same for ten years","They are moved to your insurance company","They are cut in half"],"h1":"Points get smaller over time.","h2":"In South Carolina, the points from a traffic violation are reduced by half one year after the violation date, so 4 points become 2.","p":"Right. After one year the points are cut in half."},"es":{"q":"En Carolina del Sur, ¿qué pasa con los puntos de una multa de tránsito un año después de la infracción?","o":["Se duplican","Se quedan igual por diez años","Pasan a su compañía de seguros","Se reducen a la mitad"],"h1":"Los puntos bajan con el tiempo.","h2":"En Carolina del Sur, los puntos de una infracción de tránsito se reducen a la mitad un año después de la fecha de la infracción, así que 4 puntos pasan a ser 2.","p":"Correcto. Después de un año los puntos se reducen a la mitad."},"zh":{"q":"在 South Carolina，交通罚单的分数在违规一年后会怎样？","o":["分数加倍","十年内保持不变","转给你的保险公司","分数减半"],"h1":"分数会随着时间变少。","h2":"在 South Carolina，交通违规的分数在违规日期一年后会减半，所以 4 分会变成 2 分。","p":"对。一年后分数减半。"},"vi":{"q":"Ở South Carolina, điểm từ một vé phạt giao thông sẽ ra sao một năm sau khi vi phạm?","o":["Điểm tăng gấp đôi","Điểm giữ nguyên trong mười năm","Điểm được chuyển cho công ty bảo hiểm của bạn","Điểm giảm một nửa"],"h1":"Điểm giảm dần theo thời gian.","h2":"Ở South Carolina, điểm từ một lần vi phạm giao thông được giảm một nửa một năm sau ngày vi phạm, nên 4 điểm trở thành 2 điểm.","p":"Đúng. Sau một năm điểm giảm một nửa."},"tl":{"q":"Sa South Carolina, ano ang nangyayari sa mga puntos mula sa tiket sa trapiko isang taon pagkatapos ng paglabag?","o":["Nadodoble ang mga ito","Nananatiling pareho ang mga ito nang sampung taon","Inililipat ang mga ito sa kompanya ng insurance mo","Nahahati ang mga ito sa kalahati"],"h1":"Lumiliit ang mga puntos habang tumatagal.","h2":"Sa South Carolina, ang mga puntos mula sa paglabag sa trapiko ay nababawasan ng kalahati isang taon pagkatapos ng petsa ng paglabag, kaya ang 4 na puntos ay nagiging 2.","p":"Tama. Pagkalipas ng isang taon, nahahati sa kalahati ang mga puntos."},"ar":{"q":"في South Carolina، ماذا يحدث لنقاط مخالفة المرور بعد سنة واحدة من المخالفة؟","o":["تتضاعف","تبقى كما هي لمدة عشر سنوات","تُنقَل إلى شركة التأمين الخاصة بك","تنخفض إلى النصف"],"h1":"النقاط تصغر مع مرور الوقت.","h2":"في South Carolina، تنخفض نقاط مخالفة المرور إلى النصف بعد سنة واحدة من تاريخ المخالفة، فتصبح 4 نقاط نقطتين (2).","p":"صحيح. بعد سنة واحدة تنخفض النقاط إلى النصف."},"ref":{"doc":"SC","page":"1-18"}},{"id":"sc-025","scope":"SC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Carolina, what happens if a driver under 21 refuses a test for alcohol?","o":["A fine, but no loss of driving","Loss of driving privileges for at least six months","A warning letter from the DMV","Loss of driving privileges for one day"],"h1":"Refusing is treated more harshly than a 0.02 result.","h2":"In South Carolina, a driver under 21 who refuses a test for alcohol or drugs loses the privilege to drive right away, for at least six months.","p":"Right. At least six months without driving."},"es":{"q":"En Carolina del Sur, ¿qué pasa si un conductor menor de 21 años se niega a una prueba de alcohol?","o":["Una multa, pero sigue manejando","Pierde el privilegio de manejar por lo menos seis meses","Una carta de advertencia del DMV","Pierde el privilegio de manejar por un día"],"h1":"Negarse se castiga más que un resultado de 0.02.","h2":"En Carolina del Sur, un conductor menor de 21 años que se niega a una prueba de alcohol o drogas pierde de inmediato el privilegio de manejar, por lo menos por seis meses.","p":"Correcto. Por lo menos seis meses sin manejar."},"zh":{"q":"在 South Carolina，21 岁以下的司机如果拒绝酒精检测，会怎样？","o":["罚款，但不会失去开车的权利","失去开车的权利至少六个月","收到 DMV 的警告信","失去开车的权利一天"],"h1":"拒绝检测的处罚比测出 0.02 更重。","h2":"在 South Carolina，21 岁以下的司机如果拒绝酒精或毒品检测，会马上失去开车的权利，至少六个月。","p":"对。至少六个月不能开车。"},"vi":{"q":"Ở South Carolina, điều gì xảy ra nếu người lái dưới 21 tuổi từ chối kiểm tra nồng độ cồn?","o":["Bị phạt tiền, nhưng không mất quyền lái xe","Mất quyền lái xe ít nhất sáu tháng","Nhận thư cảnh cáo từ DMV","Mất quyền lái xe một ngày"],"h1":"Từ chối bị xử phạt nặng hơn kết quả 0.02.","h2":"Ở South Carolina, người lái dưới 21 tuổi từ chối kiểm tra rượu bia hoặc ma túy sẽ mất quyền lái xe ngay lập tức, ít nhất sáu tháng.","p":"Đúng. Ít nhất sáu tháng không được lái xe."},"tl":{"q":"Sa South Carolina, ano ang mangyayari kung tumanggi ang drayber na wala pang 21 sa pagsusuri para sa alak?","o":["Multa, pero hindi mawawalan ng karapatang magmaneho","Mawawalan ng pribilehiyong magmaneho nang hindi bababa sa anim na buwan","Sulat ng babala mula sa DMV","Mawawalan ng pribilehiyong magmaneho nang isang araw"],"h1":"Mas mabigat ang parusa sa pagtanggi kaysa sa resultang 0.02.","h2":"Sa South Carolina, ang drayber na wala pang 21 na tumanggi sa pagsusuri para sa alak o droga ay agad na nawawalan ng pribilehiyong magmaneho, nang hindi bababa sa anim na buwan.","p":"Tama. Hindi bababa sa anim na buwan na walang pagmamaneho."},"ar":{"q":"في South Carolina، ماذا يحدث إذا رفض سائق عمره أقل من 21 سنة اختبار الكحول؟","o":["غرامة، لكن دون فقدان حق القيادة","فقدان حق القيادة لمدة ستة أشهر على الأقل","رسالة تحذير من DMV","فقدان حق القيادة ليوم واحد"],"h1":"الرفض يُعاقَب بشدة أكبر من نتيجة 0.02.","h2":"في South Carolina، السائق الذي عمره أقل من 21 سنة ويرفض اختبار الكحول أو المخدرات يفقد حق القيادة فورًا، لمدة ستة أشهر على الأقل.","p":"صحيح. ستة أشهر على الأقل بدون قيادة."},"ref":{"doc":"SC","page":"3-7"}},{"id":"sc-026","scope":"SC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Carolina, can an officer stop a driver only because someone in the car is not wearing a seat belt?","o":["No, only after a crash","Only if the person is a child","Yes, it is a primary law","Only on interstate highways"],"h1":"South Carolina has primary seat belt enforcement.","h2":"In South Carolina, the seat belt law is a primary law, so an officer who clearly sees a driver or passenger without a seat belt or child seat may stop the car.","p":"Right. It is a primary law."},"es":{"q":"En Carolina del Sur, ¿puede un policía detener a un conductor solo porque alguien en el carro no lleva el cinturón de seguridad?","o":["No, solo después de un choque","Solo si la persona es un niño","Sí, es una ley primaria","Solo en las autopistas interestatales"],"h1":"Carolina del Sur aplica el cinturón como ley primaria.","h2":"En Carolina del Sur, la ley del cinturón de seguridad es una ley primaria, así que un policía que ve claramente a un conductor o pasajero sin cinturón o sin asiento infantil puede detener el carro.","p":"Correcto. Es una ley primaria."},"zh":{"q":"在 South Carolina，警察可以只因为车上有人没系安全带就让司机停车吗？","o":["不可以，只有在发生车祸后才可以","只有当这个人是儿童时才可以","可以，这是主要执法法律（primary law）","只有在州际高速公路上才可以"],"h1":"South Carolina 的安全带法律是主要执法。","h2":"在 South Carolina，安全带法律是主要执法法律，所以警察如果清楚看到司机或乘客没有系安全带或没有坐儿童座椅，就可以让车停下。","p":"对。这是主要执法法律。"},"vi":{"q":"Ở South Carolina, cảnh sát có thể chặn xe chỉ vì có người trong xe không thắt dây an toàn không?","o":["Không, chỉ sau khi có tai nạn","Chỉ khi người đó là trẻ em","Có, đó là luật chính (primary law)","Chỉ trên đường cao tốc liên bang"],"h1":"South Carolina thi hành luật dây an toàn theo kiểu luật chính.","h2":"Ở South Carolina, luật dây an toàn là luật chính, nên cảnh sát thấy rõ người lái hoặc hành khách không thắt dây an toàn hoặc không ngồi ghế trẻ em thì có thể chặn xe.","p":"Đúng. Đó là luật chính."},"tl":{"q":"Sa South Carolina, puwede bang pahintuin ng pulis ang drayber dahil lang may isang tao sa kotse na hindi nakasuot ng seat belt?","o":["Hindi, pagkatapos lang ng banggaan","Kung bata lang ang tao","Oo, ito ay pangunahing batas (primary law)","Sa mga interstate highway lang"],"h1":"Ang South Carolina ay may pangunahing pagpapatupad ng batas sa seat belt.","h2":"Sa South Carolina, ang batas sa seat belt ay pangunahing batas, kaya ang pulis na malinaw na nakakita ng drayber o pasahero na walang seat belt o upuan ng bata ay puwedeng magpahinto ng kotse.","p":"Tama. Ito ay pangunahing batas."},"ar":{"q":"في South Carolina، هل يمكن للشرطي أن يوقف السائق فقط لأن شخصًا في السيارة لا يربط حزام الأمان؟","o":["لا، فقط بعد حادث","فقط إذا كان الشخص طفلًا","نعم، إنه قانون أساسي (primary law)","فقط على الطرق السريعة بين الولايات"],"h1":"في South Carolina يُطبَّق قانون حزام الأمان بشكل أساسي.","h2":"في South Carolina، قانون حزام الأمان قانون أساسي، لذلك يمكن للشرطي الذي يرى بوضوح سائقًا أو راكبًا بدون حزام أمان أو مقعد طفل أن يوقف السيارة.","p":"صحيح. إنه قانون أساسي."},"ref":{"doc":"SC","page":"4-6"}},{"id":"sc-027","scope":"SC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Carolina, where must a child age seven or younger ride?","o":["In a car seat in the back seat","In the front seat with a seat belt","On an adult's lap in the back seat","Anywhere with an adult seat belt"],"h1":"Air bags in the front can hurt small children.","h2":"In South Carolina, children age seven and younger must ride in a car seat in the back seat of the vehicle, away from the front air bag.","p":"Right. A car seat, in the back seat."},"es":{"q":"En Carolina del Sur, ¿dónde debe viajar un niño de siete años o menos?","o":["En un asiento de seguridad en el asiento trasero","En el asiento delantero con cinturón","En las piernas de un adulto en el asiento trasero","En cualquier lugar con un cinturón de adulto"],"h1":"Las bolsas de aire de adelante pueden lastimar a los niños pequeños.","h2":"En Carolina del Sur, los niños de siete años o menos deben viajar en un asiento de seguridad en el asiento trasero del vehículo, lejos de la bolsa de aire delantera.","p":"Correcto. En un asiento de seguridad, en el asiento trasero."},"zh":{"q":"在 South Carolina，七岁或以下的儿童必须坐在哪里？","o":["后座的儿童座椅里","前座，系上安全带","后座，坐在大人的腿上","任何地方，系上大人的安全带就行"],"h1":"前面的安全气囊可能会伤到小孩。","h2":"在 South Carolina，七岁和以下的儿童必须坐在车子后座的儿童座椅里，远离前面的安全气囊。","p":"对。坐儿童座椅，在后座。"},"vi":{"q":"Ở South Carolina, trẻ em từ bảy tuổi trở xuống phải ngồi ở đâu?","o":["Trong ghế trẻ em ở ghế sau","Ở ghế trước, có thắt dây an toàn","Ngồi trên đùi người lớn ở ghế sau","Ở bất cứ chỗ nào có dây an toàn của người lớn"],"h1":"Túi khí ở phía trước có thể làm trẻ nhỏ bị thương.","h2":"Ở South Carolina, trẻ em từ bảy tuổi trở xuống phải ngồi trong ghế trẻ em ở ghế sau của xe, tránh xa túi khí phía trước.","p":"Đúng. Ghế trẻ em, ở ghế sau."},"tl":{"q":"Sa South Carolina, saan dapat sumakay ang batang pitong taong gulang o mas bata?","o":["Sa upuan ng bata sa likurang upuan","Sa harapang upuan na may seat belt","Sa kandungan ng adulto sa likurang upuan","Kahit saan basta may seat belt ng adulto"],"h1":"Ang mga air bag sa harapan ay puwedeng makasakit sa maliliit na bata.","h2":"Sa South Carolina, ang mga batang pitong taong gulang at mas bata ay dapat sumakay sa upuan ng bata sa likurang upuan ng sasakyan, malayo sa air bag sa harapan.","p":"Tama. Upuan ng bata, sa likurang upuan."},"ar":{"q":"في South Carolina، أين يجب أن يجلس الطفل الذي عمره سبع سنوات أو أقل؟","o":["في مقعد طفل في المقعد الخلفي","في المقعد الأمامي مع حزام الأمان","في حضن شخص بالغ في المقعد الخلفي","في أي مكان مع حزام أمان للبالغين"],"h1":"الوسائد الهوائية في الأمام يمكن أن تؤذي الأطفال الصغار.","h2":"في South Carolina، يجب أن يجلس الأطفال الذين عمرهم سبع سنوات أو أقل في مقعد طفل في المقعد الخلفي للسيارة، بعيدًا عن الوسادة الهوائية الأمامية.","p":"صحيح. مقعد طفل، في المقعد الخلفي."},"ref":{"doc":"SC","page":"4-7"}},{"id":"sc-028","scope":"SC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Carolina, what is the smallest following distance the driver's manual says to keep behind the car ahead?","o":["2 seconds","3 seconds","4 seconds","1 second"],"h1":"Pick a sign or pole and count how long it takes you to reach it after the car ahead passes it.","h2":"In South Carolina, the driver's manual says to stay at least 4 seconds behind the vehicle in front of you.","p":"Right. At least 4 seconds behind."},"es":{"q":"En Carolina del Sur, ¿cuál es la distancia mínima que, según el manual, debe dejar detrás del auto de adelante?","o":["2 segundos","3 segundos","4 segundos","1 segundo"],"h1":"Elija un letrero o un poste y cuente cuánto tarda en llegar a él después de que pase el auto de adelante.","h2":"En Carolina del Sur, el manual de manejo dice que debe mantenerse al menos 4 segundos detrás del vehículo de adelante.","p":"Correcto. Al menos 4 segundos detrás."},"zh":{"q":"在 South Carolina，驾驶手册说你和前面的车之间最少要保持多远的跟车距离？","o":["2 秒","3 秒","4 秒","1 秒"],"h1":"选一个路牌或电线杆，前面的车经过它以后，数一数你要多久才到那里。","h2":"在 South Carolina，驾驶手册说你要和前面的车保持至少 4 秒的距离。","p":"对。至少保持 4 秒的距离。"},"vi":{"q":"Ở South Carolina, sổ tay lái xe nói bạn phải giữ khoảng cách ít nhất bao nhiêu với xe phía trước?","o":["2 giây","3 giây","4 giây","1 giây"],"h1":"Chọn một biển báo hoặc cột điện, rồi đếm xem bạn mất bao lâu để tới đó sau khi xe phía trước chạy qua.","h2":"Ở South Carolina, sổ tay lái xe nói bạn phải đi cách xe phía trước ít nhất 4 giây.","p":"Đúng. Cách xe phía trước ít nhất 4 giây."},"tl":{"q":"Sa South Carolina, ano ang pinakamaikling layo na sinasabi ng driver's manual na dapat mong panatilihin sa likod ng sasakyan sa unahan?","o":["2 segundo","3 segundo","4 segundo","1 segundo"],"h1":"Pumili ng karatula o poste at bilangin kung gaano katagal bago ka makarating doon matapos itong lampasan ng sasakyan sa unahan.","h2":"Sa South Carolina, sinasabi ng driver's manual na dapat kang manatili nang hindi bababa sa 4 segundo sa likod ng sasakyan sa unahan mo.","p":"Tama. Hindi bababa sa 4 segundo sa likod."},"ar":{"q":"في South Carolina، ما أقل مسافة يقول دليل القيادة أن تتركها خلف السيارة التي أمامك؟","o":["2 ثانية","3 ثوانٍ","4 ثوانٍ","1 ثانية"],"h1":"اختر لافتة أو عمودًا، وعُدّ كم من الوقت تحتاج لتصل إليه بعد أن تمر به السيارة التي أمامك.","h2":"في South Carolina، يقول دليل القيادة أن تبقى على الأقل 4 ثوانٍ خلف السيارة التي أمامك.","p":"صحيح. على الأقل 4 ثوانٍ خلفها."},"ref":{"doc":"SC","page":"8-6"}},{"id":"sc-029","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, your driver's license has been expired for more than nine months. What must you do to get a license again?","o":["Pay a late fee online","Pass the vision, knowledge and skills tests again","Show a new photo ID only","Wait 30 days and renew by mail"],"h1":"After a long time, the state wants to check your skills again.","h2":"In South Carolina, if your license has been expired for more than nine months, you must go to an SCDMV branch and pass the vision, knowledge and skills tests again.","p":"Right. All three tests again."},"es":{"q":"En Carolina del Sur, su licencia de conducir lleva más de nueve meses vencida. ¿Qué debe hacer para obtener una licencia otra vez?","o":["Pagar un recargo por internet","Aprobar otra vez los exámenes de la vista, de conocimientos y de manejo","Mostrar solo una nueva identificación con foto","Esperar 30 días y renovar por correo"],"h1":"Después de mucho tiempo, el estado quiere revisar otra vez sus habilidades.","h2":"En Carolina del Sur, si su licencia lleva más de nueve meses vencida, debe ir a una oficina del SCDMV y aprobar otra vez los exámenes de la vista, de conocimientos y de manejo.","p":"Correcto. Los tres exámenes otra vez."},"zh":{"q":"在 South Carolina，你的驾照已经过期超过九个月。你要怎样才能再拿到驾照？","o":["在网上交滞纳金","重新通过视力、笔试和路考","只出示新的带照片的身份证件","等 30 天，然后用邮寄方式更新"],"h1":"过了很长时间以后，州政府要再检查一次你的驾驶能力。","h2":"在 South Carolina，如果你的驾照过期超过九个月，你必须去 SCDMV 办公室，重新通过视力、笔试和路考。","p":"对。三项考试都要重新考。"},"vi":{"q":"Ở South Carolina, bằng lái của bạn đã hết hạn hơn chín tháng. Bạn phải làm gì để có lại bằng lái?","o":["Trả phí trễ hạn trên mạng","Thi lại bài kiểm tra thị lực, lý thuyết và lái xe","Chỉ cần đưa giấy tờ tùy thân có ảnh mới","Đợi 30 ngày rồi gia hạn qua bưu điện"],"h1":"Sau một thời gian dài, tiểu bang muốn kiểm tra lại kỹ năng của bạn.","h2":"Ở South Carolina, nếu bằng lái của bạn đã hết hạn hơn chín tháng, bạn phải đến văn phòng SCDMV và thi lại bài kiểm tra thị lực, lý thuyết và lái xe.","p":"Đúng. Thi lại cả ba bài."},"tl":{"q":"Sa South Carolina, mahigit siyam na buwan nang expired ang iyong lisensya. Ano ang dapat mong gawin para magkaroon ulit ng lisensya?","o":["Magbayad ng multa sa pagkahuli online","Pumasa ulit sa vision, knowledge at skills test","Magpakita lang ng bagong ID na may litrato","Maghintay ng 30 araw at mag-renew sa koreo"],"h1":"Pagkatapos ng mahabang panahon, gusto ng estado na suriin ulit ang iyong kakayahan.","h2":"Sa South Carolina, kung mahigit siyam na buwan nang expired ang iyong lisensya, dapat kang pumunta sa isang sangay ng SCDMV at pumasa ulit sa vision, knowledge at skills test.","p":"Tama. Lahat ng tatlong test ulit."},"ar":{"q":"في South Carolina، انتهت رخصة القيادة الخاصة بك منذ أكثر من تسعة أشهر. ماذا يجب أن تفعل لتحصل على رخصة مرة أخرى؟","o":["تدفع غرامة تأخير عبر الإنترنت","تنجح مرة أخرى في اختبارات النظر والمعرفة والقيادة","تُظهر بطاقة هوية جديدة بصورة فقط","تنتظر 30 يومًا وتجدد بالبريد"],"h1":"بعد وقت طويل، تريد الولاية أن تفحص مهاراتك مرة أخرى.","h2":"في South Carolina، إذا انتهت رخصتك منذ أكثر من تسعة أشهر، يجب أن تذهب إلى فرع SCDMV وتنجح مرة أخرى في اختبارات النظر والمعرفة والقيادة.","p":"صحيح. الاختبارات الثلاثة كلها مرة أخرى."},"ref":{"doc":"SC","page":"1-18"}},{"id":"sc-030","scope":"SC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Carolina, a car is coming toward you at night. When should you dim your high beams?","o":["When it is still 500 feet or more away","When it is about 100 feet away","Only if it flashes its lights at you","When it is right beside you"],"h1":"Bright lights can blind the other driver from far away.","h2":"In South Carolina, you should dim your high beams while an oncoming vehicle is still 500 feet or more away.","p":"Right. Dim them at 500 feet or more."},"es":{"q":"En Carolina del Sur, un auto viene hacia usted de noche. ¿Cuándo debe bajar las luces altas?","o":["Cuando todavía está a 500 pies o más","Cuando está a unos 100 pies","Solo si le hace cambio de luces","Cuando está justo a su lado"],"h1":"Las luces fuertes pueden encandilar al otro conductor desde lejos.","h2":"En Carolina del Sur, debe bajar las luces altas cuando el vehículo que viene de frente todavía está a 500 pies o más.","p":"Correcto. Bájelas a 500 pies o más."},"zh":{"q":"在 South Carolina，晚上有一辆车朝你开过来。你应该什么时候把远光灯调成近光灯？","o":["在它还在 500 英尺或更远的时候","在它大约 100 英尺远的时候","只有在它对你闪灯的时候","在它就在你旁边的时候"],"h1":"很亮的车灯从很远的地方就会让对面的司机看不清。","h2":"在 South Carolina，对面来车还在 500 英尺或更远的时候，你就应该把远光灯调成近光灯。","p":"对。在 500 英尺或更远就调暗。"},"vi":{"q":"Ở South Carolina, ban đêm có một xe đang chạy về phía bạn. Khi nào bạn nên hạ đèn pha xuống đèn cốt?","o":["Khi xe đó vẫn còn cách 500 feet hoặc xa hơn","Khi xe đó cách khoảng 100 feet","Chỉ khi xe đó nháy đèn với bạn","Khi xe đó ở ngay bên cạnh bạn"],"h1":"Đèn sáng có thể làm người lái xe kia bị chói từ rất xa.","h2":"Ở South Carolina, bạn nên hạ đèn pha xuống khi xe chạy ngược chiều vẫn còn cách 500 feet hoặc xa hơn.","p":"Đúng. Hạ đèn khi còn cách 500 feet hoặc xa hơn."},"tl":{"q":"Sa South Carolina, may sasakyang papalapit sa iyo sa gabi. Kailan mo dapat i-dim ang iyong high beams?","o":["Kapag 500 feet pa o mas malayo ito","Kapag mga 100 feet na lang ito","Kapag nag-flash lang ito ng ilaw sa iyo","Kapag nasa tabi mo na ito"],"h1":"Ang maliliwanag na ilaw ay puwedeng makasilaw sa ibang driver kahit malayo pa.","h2":"Sa South Carolina, dapat mong i-dim ang iyong high beams habang ang paparating na sasakyan ay 500 feet pa o mas malayo.","p":"Tama. I-dim ang mga ito sa 500 feet o higit pa."},"ar":{"q":"في South Carolina، سيارة قادمة نحوك في الليل. متى يجب أن تخفض الأضواء العالية؟","o":["عندما تكون ما زالت على بعد 500 قدم أو أكثر","عندما تكون على بعد حوالي 100 قدم","فقط إذا أومضت أضواءها لك","عندما تكون بجانبك تمامًا"],"h1":"الأضواء القوية يمكن أن تُعمي السائق الآخر من مسافة بعيدة.","h2":"في South Carolina، يجب أن تخفض الأضواء العالية عندما تكون السيارة القادمة ما زالت على بعد 500 قدم أو أكثر.","p":"صحيح. اخفضها على بعد 500 قدم أو أكثر."},"ref":{"doc":"SC","page":"11-1"}},{"id":"sc-031","scope":"SC","cat":"signals","sign":null,"c":3,"en":{"q":"In South Carolina, how far before a turn or lane change does state law say you must turn on your signal?","o":["At least 25 feet","At least 50 feet","Only as you begin to turn","At least 100 feet"],"h1":"The distance is about the length of five or six cars.","h2":"In South Carolina, state law says you must signal at least 100 feet before you turn, change lanes or merge.","p":"Right. At least 100 feet ahead."},"es":{"q":"En Carolina del Sur, ¿con cuánta anticipación exige la ley estatal poner la direccional antes de girar o cambiar de carril?","o":["Al menos 25 pies","Al menos 50 pies","Solo al empezar a girar","Al menos 100 pies"],"h1":"La distancia es más o menos el largo de cinco o seis autos.","h2":"En Carolina del Sur, la ley estatal exige poner la direccional al menos 100 pies antes de girar, cambiar de carril o incorporarse al tráfico.","p":"Correcto. Al menos 100 pies antes."},"zh":{"q":"在 South Carolina，州法律规定你在转弯或换车道前多远就必须打方向灯？","o":["至少 25 英尺","至少 50 英尺","只在开始转弯的时候","至少 100 英尺"],"h1":"这个距离大约是五六辆车的长度。","h2":"在 South Carolina，州法律规定你在转弯、换车道或并道前至少 100 英尺就必须打方向灯。","p":"对。至少提前 100 英尺。"},"vi":{"q":"Ở South Carolina, luật tiểu bang nói bạn phải bật đèn xi nhan cách bao xa trước khi rẽ hoặc đổi làn?","o":["Ít nhất 25 feet","Ít nhất 50 feet","Chỉ khi bạn bắt đầu rẽ","Ít nhất 100 feet"],"h1":"Khoảng cách này dài bằng khoảng năm hoặc sáu chiếc xe.","h2":"Ở South Carolina, luật tiểu bang nói bạn phải bật đèn xi nhan ít nhất 100 feet trước khi rẽ, đổi làn hoặc nhập làn.","p":"Đúng. Ít nhất 100 feet trước đó."},"tl":{"q":"Sa South Carolina, gaano kalayo bago lumiko o lumipat ng lane sinasabi ng batas ng estado na dapat mong buksan ang iyong signal?","o":["Hindi bababa sa 25 feet","Hindi bababa sa 50 feet","Kapag nagsisimula ka na lang lumiko","Hindi bababa sa 100 feet"],"h1":"Ang layo ay halos haba ng lima o anim na sasakyan.","h2":"Sa South Carolina, sinasabi ng batas ng estado na dapat kang mag-signal nang hindi bababa sa 100 feet bago ka lumiko, lumipat ng lane o sumanib sa trapiko.","p":"Tama. Hindi bababa sa 100 feet bago."},"ar":{"q":"في South Carolina، على أي مسافة قبل الانعطاف أو تغيير المسار يقول قانون الولاية إنه يجب أن تشغّل الإشارة؟","o":["على الأقل 25 قدمًا","على الأقل 50 قدمًا","فقط عندما تبدأ الانعطاف","على الأقل 100 قدم"],"h1":"هذه المسافة تساوي تقريبًا طول خمس أو ست سيارات.","h2":"في South Carolina، يقول قانون الولاية إنه يجب أن تشغّل الإشارة على الأقل 100 قدم قبل أن تنعطف أو تغيّر المسار أو تندمج في حركة السير.","p":"صحيح. على الأقل 100 قدم قبلها."},"ref":{"doc":"SC","page":"8-9"}},{"id":"sd-001","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","16 years old","15 and a half"],"h1":"South Dakota lets teens start earlier than most states.","h2":"In South Dakota you can get an instruction permit at age 14, which is earlier than in most states.","p":"Right. The South Dakota instruction permit starts at age 14."},"es":{"q":"En Dakota del Sur, ¿cuál es la edad mínima para obtener el permiso de instrucción?","o":["14 años","15 años","16 años","15 años y medio"],"h1":"Dakota del Sur deja empezar antes que la mayoría de los estados.","h2":"En Dakota del Sur usted puede obtener el permiso de instrucción a los 14 años, antes que en la mayoría de los estados.","p":"Correcto. El permiso de instrucción en Dakota del Sur empieza a los 14 años."},"zh":{"q":"在 South Dakota，最小几岁可以拿到学习驾照（instruction permit）？","o":["14 岁","15 岁","16 岁","15 岁半"],"h1":"South Dakota 让青少年比大多数州更早开始。","h2":"在 South Dakota，你 14 岁就可以拿到学习驾照，这比大多数州都早。","p":"对。South Dakota 的学习驾照从 14 岁开始。"},"vi":{"q":"Ở South Dakota, tuổi nhỏ nhất để có giấy phép tập lái (instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","15 tuổi rưỡi"],"h1":"South Dakota cho thanh thiếu niên bắt đầu sớm hơn hầu hết các tiểu bang.","h2":"Ở South Dakota, bạn có thể có giấy phép tập lái khi 14 tuổi, sớm hơn hầu hết các tiểu bang khác.","p":"Đúng. Giấy phép tập lái ở South Dakota bắt đầu từ 14 tuổi."},"tl":{"q":"Sa South Dakota, ano ang pinakabatang edad para makakuha ng instruction permit (permit sa pag-aaral magmaneho)?","o":["14 taong gulang","15 taong gulang","16 taong gulang","15 at kalahati"],"h1":"Mas maaga pinapayagang magsimula ng South Dakota ang mga kabataan kaysa sa karamihan ng estado.","h2":"Sa South Dakota, makakakuha ka ng instruction permit sa edad na 14, na mas maaga kaysa sa karamihan ng estado.","p":"Tama. Sa South Dakota, nagsisimula ang instruction permit sa edad na 14."},"ar":{"q":"في South Dakota، ما أصغر عمر للحصول على تصريح التعلّم (instruction permit)؟","o":["14 سنة","15 سنة","16 سنة","15 سنة ونصف"],"h1":"تسمح South Dakota للمراهقين بالبدء أبكر من معظم الولايات.","h2":"في South Dakota يمكنك الحصول على تصريح التعلّم في عمر 14 سنة، وهذا أبكر من معظم الولايات.","p":"صحيح. يبدأ تصريح التعلّم في South Dakota من عمر 14 سنة."},"ref":{"doc":"SD","page":8}},{"id":"sd-002","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, during which hours may an instruction permit holder drive with any qualified licensed adult beside them?","o":["6 a.m. to 8 p.m.","5 a.m. to midnight","6 a.m. to 10 p.m.","6 a.m. to 6 p.m."],"h1":"It ends in the late evening, before midnight.","h2":"A South Dakota instruction permit allows driving from 6 a.m. to 10 p.m. with a qualified licensed adult beside you; from 10 p.m. to 6 a.m. it must be your parent or guardian.","p":"Right. Instruction permit driving is from 6 a.m. to 10 p.m."},"es":{"q":"En Dakota del Sur, ¿en qué horario puede manejar quien tiene permiso de instrucción con cualquier adulto con licencia autorizado a su lado?","o":["De 6 a.m. a 8 p.m.","De 5 a.m. a medianoche","De 6 a.m. a 10 p.m.","De 6 a.m. a 6 p.m."],"h1":"Termina tarde en la noche, antes de la medianoche.","h2":"En Dakota del Sur el permiso de instrucción permite manejar de 6 a.m. a 10 p.m. con un adulto con licencia autorizado a su lado; de 10 p.m. a 6 a.m. debe ser su padre, madre o tutor.","p":"Correcto. Con permiso de instrucción se maneja de 6 a.m. a 10 p.m."},"zh":{"q":"在 South Dakota，持有学习驾照的人在哪个时间段可以在任何合格的有驾照成年人陪同下开车？","o":["早上 6 点到晚上 8 点","早上 5 点到午夜","早上 6 点到晚上 10 点","早上 6 点到晚上 6 点"],"h1":"结束时间在晚上较晚的时候，在午夜之前。","h2":"在 South Dakota，持学习驾照的人可以在早上 6 点到晚上 10 点之间，在合格的有驾照成年人陪同下开车；晚上 10 点到早上 6 点，陪同的人必须是父母或监护人。","p":"对。持学习驾照开车的时间是早上 6 点到晚上 10 点。"},"vi":{"q":"Ở South Dakota, người có giấy phép tập lái được lái xe với bất kỳ người lớn có bằng lái đủ điều kiện ngồi bên cạnh trong những giờ nào?","o":["6 giờ sáng đến 8 giờ tối","5 giờ sáng đến nửa đêm","6 giờ sáng đến 10 giờ tối","6 giờ sáng đến 6 giờ chiều"],"h1":"Giờ kết thúc là vào buổi tối muộn, trước nửa đêm.","h2":"Giấy phép tập lái ở South Dakota cho phép lái xe từ 6 giờ sáng đến 10 giờ tối với một người lớn có bằng lái đủ điều kiện ngồi bên cạnh; từ 10 giờ tối đến 6 giờ sáng, người đó phải là cha mẹ hoặc người giám hộ của bạn.","p":"Đúng. Lái xe với giấy phép tập lái là từ 6 giờ sáng đến 10 giờ tối."},"tl":{"q":"Sa South Dakota, sa anong oras puwedeng magmaneho ang may instruction permit kasama ang sinumang kwalipikadong adult na may lisensya sa tabi niya?","o":["6 a.m. hanggang 8 p.m.","5 a.m. hanggang hatinggabi","6 a.m. hanggang 10 p.m.","6 a.m. hanggang 6 p.m."],"h1":"Natatapos ito sa gabi, bago maghatinggabi.","h2":"Pinapayagan ng South Dakota instruction permit ang pagmamaneho mula 6 a.m. hanggang 10 p.m. kasama ang kwalipikadong adult na may lisensya sa tabi mo; mula 10 p.m. hanggang 6 a.m., dapat ay magulang o guardian mo ito.","p":"Tama. Ang pagmamaneho gamit ang instruction permit ay mula 6 a.m. hanggang 10 p.m."},"ar":{"q":"في South Dakota، في أي ساعات يمكن لحامل تصريح التعلّم أن يقود مع أي شخص بالغ مؤهَّل يحمل رخصة بجانبه؟","o":["من 6 صباحًا إلى 8 مساءً","من 5 صباحًا إلى منتصف الليل","من 6 صباحًا إلى 10 مساءً","من 6 صباحًا إلى 6 مساءً"],"h1":"تنتهي في وقت متأخر من المساء، قبل منتصف الليل.","h2":"يسمح تصريح التعلّم في South Dakota بالقيادة من 6 صباحًا إلى 10 مساءً مع شخص بالغ مؤهَّل يحمل رخصة بجانبك؛ ومن 10 مساءً إلى 6 صباحًا يجب أن يكون والدك أو وليّ أمرك.","p":"صحيح. القيادة بتصريح التعلّم من 6 صباحًا إلى 10 مساءً."},"ref":{"doc":"SD","page":null}},{"id":"sd-003","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, who may sit beside an instruction permit holder while driving?","o":["Any passenger age 16 or older","A parent, guardian, or licensed adult with 1+ year of experience","Any licensed driver, even a new one","Only a certified driving instructor"],"h1":"The helper needs a license and some driving experience.","h2":"A South Dakota instruction permit holder must drive with a parent, a guardian, or another licensed adult with at least one year of driving experience seated beside them.","p":"Right. The helper is a parent, guardian, or experienced licensed adult."},"es":{"q":"En Dakota del Sur, ¿quién puede ir sentado al lado de quien tiene permiso de instrucción mientras maneja?","o":["Cualquier pasajero de 16 años o más","Un padre, tutor o adulto con licencia y 1+ año de experiencia","Cualquier conductor con licencia, aunque sea nuevo","Solo un instructor de manejo certificado"],"h1":"El acompañante necesita licencia y algo de experiencia manejando.","h2":"En Dakota del Sur quien tiene permiso de instrucción debe manejar con un padre, un tutor u otro adulto con licencia y por lo menos un año de experiencia sentado a su lado.","p":"Correcto. El acompañante es un padre, tutor o adulto con licencia y experiencia."},"zh":{"q":"在 South Dakota，持学习驾照的人开车时，谁可以坐在旁边？","o":["任何 16 岁或以上的乘客","父母、监护人，或有 1 年以上驾驶经验的有驾照成年人","任何有驾照的司机，即使是新司机","只有持证的驾驶教练"],"h1":"陪同的人需要有驾照，也需要一些驾驶经验。","h2":"在 South Dakota，持学习驾照的人开车时，旁边必须坐着父母、监护人，或另一位至少有一年驾驶经验的有驾照成年人。","p":"对。陪同的人是父母、监护人，或有经验的有驾照成年人。"},"vi":{"q":"Ở South Dakota, ai được ngồi bên cạnh người có giấy phép tập lái khi lái xe?","o":["Bất kỳ hành khách nào từ 16 tuổi trở lên","Cha mẹ, người giám hộ, hoặc người lớn có bằng lái với 1 năm kinh nghiệm trở lên","Bất kỳ tài xế có bằng lái nào, kể cả người mới lái","Chỉ giáo viên dạy lái xe có chứng nhận"],"h1":"Người hướng dẫn cần có bằng lái và một chút kinh nghiệm lái xe.","h2":"Người có giấy phép tập lái ở South Dakota phải lái xe với cha mẹ, người giám hộ, hoặc một người lớn khác có bằng lái và ít nhất một năm kinh nghiệm lái xe ngồi bên cạnh.","p":"Đúng. Người hướng dẫn là cha mẹ, người giám hộ, hoặc người lớn có bằng lái và có kinh nghiệm."},"tl":{"q":"Sa South Dakota, sino ang puwedeng umupo sa tabi ng may instruction permit habang nagmamaneho?","o":["Sinumang pasaherong 16 taong gulang pataas","Magulang, guardian, o adult na may lisensya at 1+ taon na karanasan","Sinumang drayber na may lisensya, kahit bago pa lang","Isang sertipikadong instruktor sa pagmamaneho lamang"],"h1":"Kailangan ng katulong ang lisensya at kaunting karanasan sa pagmamaneho.","h2":"Ang may South Dakota instruction permit ay dapat magmaneho kasama ang magulang, guardian, o ibang adult na may lisensya at hindi bababa sa isang taon na karanasan sa pagmamaneho na nakaupo sa tabi niya.","p":"Tama. Ang katulong ay magulang, guardian, o adult na may lisensya at may karanasan."},"ar":{"q":"في South Dakota، من يمكنه أن يجلس بجانب حامل تصريح التعلّم أثناء القيادة؟","o":["أي راكب عمره 16 سنة أو أكثر","أحد الوالدين أو وليّ الأمر أو بالغ يحمل رخصة وله خبرة سنة أو أكثر","أي سائق يحمل رخصة، حتى لو كان جديدًا","مدرّب قيادة معتمد فقط"],"h1":"يحتاج المرافق إلى رخصة وبعض الخبرة في القيادة.","h2":"يجب على حامل تصريح التعلّم في South Dakota أن يقود ويجلس بجانبه أحد الوالدين أو وليّ الأمر أو شخص بالغ آخر يحمل رخصة وله خبرة في القيادة لا تقل عن سنة واحدة.","p":"صحيح. المرافق هو أحد الوالدين أو وليّ الأمر أو بالغ ذو خبرة يحمل رخصة."},"ref":{"doc":"SD","page":8}},{"id":"sd-004","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, how long must a teen hold an instruction permit before applying for a restricted minor's permit, without driver education?","o":["90 days","180 days","365 days","275 days"],"h1":"It is about nine months.","h2":"A South Dakota teen without approved driver education must hold the instruction permit for at least 275 days before applying for a restricted minor's permit.","p":"Right. Without driver education, the wait is 275 days."},"es":{"q":"En Dakota del Sur, ¿cuánto tiempo debe tener un joven el permiso de instrucción antes de solicitar el permiso restringido de menor, sin educación vial?","o":["90 días","180 días","365 días","275 días"],"h1":"Son unos nueve meses.","h2":"En Dakota del Sur un joven sin educación vial aprobada debe tener el permiso de instrucción por lo menos 275 días antes de solicitar el permiso restringido de menor.","p":"Correcto. Sin educación vial, la espera es de 275 días."},"zh":{"q":"在 South Dakota，如果没有上驾驶教育课，青少年必须持有学习驾照多久，才能申请未成年人限制驾照（restricted minor's permit）？","o":["90 天","180 天","365 天","275 天"],"h1":"大约九个月。","h2":"在 South Dakota，没有上过批准的驾驶教育课的青少年，必须持有学习驾照至少 275 天，才能申请未成年人限制驾照。","p":"对。没有驾驶教育课，要等 275 天。"},"vi":{"q":"Ở South Dakota, nếu không học lớp giáo dục lái xe, thanh thiếu niên phải giữ giấy phép tập lái bao lâu trước khi xin giấy phép hạn chế cho người chưa thành niên (restricted minor's permit)?","o":["90 ngày","180 ngày","365 ngày","275 ngày"],"h1":"Khoảng chín tháng.","h2":"Ở South Dakota, thanh thiếu niên không học lớp giáo dục lái xe được chấp thuận phải giữ giấy phép tập lái ít nhất 275 ngày trước khi xin giấy phép hạn chế cho người chưa thành niên.","p":"Đúng. Không học giáo dục lái xe thì phải chờ 275 ngày."},"tl":{"q":"Sa South Dakota, gaano katagal dapat hawak ng kabataan ang instruction permit bago mag-apply ng restricted minor's permit, kung walang driver education?","o":["90 araw","180 araw","365 araw","275 araw"],"h1":"Mga siyam na buwan ito.","h2":"Ang kabataan sa South Dakota na walang aprubadong driver education ay dapat humawak ng instruction permit nang hindi bababa sa 275 araw bago mag-apply ng restricted minor's permit.","p":"Tama. Kung walang driver education, 275 araw ang paghihintay."},"ar":{"q":"في South Dakota، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل التقدّم لتصريح القاصر المقيَّد (restricted minor's permit)، بدون دورة تعليم القيادة؟","o":["90 يومًا","180 يومًا","365 يومًا","275 يومًا"],"h1":"إنها نحو تسعة أشهر.","h2":"يجب على المراهق في South Dakota الذي لم يأخذ دورة تعليم قيادة معتمدة أن يحمل تصريح التعلّم 275 يومًا على الأقل قبل التقدّم لتصريح القاصر المقيَّد.","p":"صحيح. بدون تعليم القيادة، الانتظار 275 يومًا."},"ref":{"doc":"SD","page":8}},{"id":"sd-005","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, if a teen passes an approved driver education course, how long must they hold the instruction permit?","o":["90 days","180 days","275 days","30 days"],"h1":"It is about six months.","h2":"In South Dakota a teen who passes an approved driver education course needs to hold the instruction permit for only 180 days instead of 275.","p":"Right. With driver education, the wait is 180 days."},"es":{"q":"En Dakota del Sur, si un joven aprueba un curso de educación vial aprobado, ¿cuánto tiempo debe tener el permiso de instrucción?","o":["90 días","180 días","275 días","30 días"],"h1":"Son unos seis meses.","h2":"En Dakota del Sur un joven que aprueba un curso de educación vial aprobado solo necesita tener el permiso de instrucción 180 días en lugar de 275.","p":"Correcto. Con educación vial, la espera es de 180 días."},"zh":{"q":"在 South Dakota，如果青少年通过了批准的驾驶教育课，必须持有学习驾照多久？","o":["90 天","180 天","275 天","30 天"],"h1":"大约六个月。","h2":"在 South Dakota，通过批准的驾驶教育课的青少年只需要持有学习驾照 180 天，而不是 275 天。","p":"对。有驾驶教育课，要等 180 天。"},"vi":{"q":"Ở South Dakota, nếu thanh thiếu niên học đậu một lớp giáo dục lái xe được chấp thuận, họ phải giữ giấy phép tập lái bao lâu?","o":["90 ngày","180 ngày","275 ngày","30 ngày"],"h1":"Khoảng sáu tháng.","h2":"Ở South Dakota, thanh thiếu niên học đậu lớp giáo dục lái xe được chấp thuận chỉ cần giữ giấy phép tập lái 180 ngày thay vì 275 ngày.","p":"Đúng. Có học giáo dục lái xe thì chờ 180 ngày."},"tl":{"q":"Sa South Dakota, kung pumasa ang kabataan sa aprubadong driver education course, gaano katagal niya dapat hawak ang instruction permit?","o":["90 araw","180 araw","275 araw","30 araw"],"h1":"Mga anim na buwan ito.","h2":"Sa South Dakota, ang kabataang pumasa sa aprubadong driver education course ay kailangang humawak ng instruction permit nang 180 araw lamang sa halip na 275.","p":"Tama. Kung may driver education, 180 araw ang paghihintay."},"ar":{"q":"في South Dakota، إذا نجح المراهق في دورة تعليم قيادة معتمدة، كم مدة يجب أن يحمل تصريح التعلّم؟","o":["90 يومًا","180 يومًا","275 يومًا","30 يومًا"],"h1":"إنها نحو ستة أشهر.","h2":"في South Dakota، المراهق الذي ينجح في دورة تعليم قيادة معتمدة يحتاج أن يحمل تصريح التعلّم 180 يومًا فقط بدلًا من 275.","p":"صحيح. مع تعليم القيادة، الانتظار 180 يومًا."},"ref":{"doc":"SD","page":8}},{"id":"sd-006","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, how many hours of supervised driving must a teen complete on an instruction permit?","o":["20 hours","40 hours","50 hours","60 hours"],"h1":"It is a round number between 40 and 60.","h2":"A South Dakota teen must complete at least 50 hours of supervised driving on an instruction permit, and a parent or guardian confirms it in writing.","p":"Right. Fifty hours of supervised driving."},"es":{"q":"En Dakota del Sur, ¿cuántas horas de manejo supervisado debe completar un joven con el permiso de instrucción?","o":["20 horas","40 horas","50 horas","60 horas"],"h1":"Es un número redondo entre 40 y 60.","h2":"En Dakota del Sur un joven debe completar por lo menos 50 horas de manejo supervisado con el permiso de instrucción, y un padre o tutor lo confirma por escrito.","p":"Correcto. Cincuenta horas de manejo supervisado."},"zh":{"q":"在 South Dakota，青少年持学习驾照时必须完成多少小时有人监督的驾驶？","o":["20 小时","40 小时","50 小时","60 小时"],"h1":"它是 40 和 60 之间的一个整数。","h2":"在 South Dakota，青少年持学习驾照时必须完成至少 50 小时有人监督的驾驶，并由父母或监护人书面确认。","p":"对。50 小时有人监督的驾驶。"},"vi":{"q":"Ở South Dakota, thanh thiếu niên phải lái xe có người giám sát bao nhiêu giờ khi có giấy phép tập lái?","o":["20 giờ","40 giờ","50 giờ","60 giờ"],"h1":"Đó là một số tròn ở giữa 40 và 60.","h2":"Thanh thiếu niên ở South Dakota phải lái xe có người giám sát ít nhất 50 giờ khi có giấy phép tập lái, và cha mẹ hoặc người giám hộ xác nhận bằng văn bản.","p":"Đúng. Năm mươi giờ lái xe có người giám sát."},"tl":{"q":"Sa South Dakota, ilang oras ng pagmamanehong may nagbabantay ang dapat matapos ng kabataan habang may instruction permit?","o":["20 oras","40 oras","50 oras","60 oras"],"h1":"Isa itong buong numero sa pagitan ng 40 at 60.","h2":"Ang kabataan sa South Dakota ay dapat makatapos ng hindi bababa sa 50 oras ng pagmamanehong may nagbabantay habang may instruction permit, at pinapatunayan ito ng magulang o guardian nang nakasulat.","p":"Tama. Limampung oras ng pagmamanehong may nagbabantay."},"ar":{"q":"في South Dakota، كم ساعة من القيادة تحت الإشراف يجب أن يكملها المراهق بتصريح التعلّم؟","o":["20 ساعة","40 ساعة","50 ساعة","60 ساعة"],"h1":"إنه رقم مستدير بين 40 و60.","h2":"يجب على المراهق في South Dakota أن يكمل 50 ساعة على الأقل من القيادة تحت الإشراف بتصريح التعلّم، ويؤكد ذلك أحد الوالدين أو وليّ الأمر كتابيًا.","p":"صحيح. خمسون ساعة من القيادة تحت الإشراف."},"ref":{"doc":"SD","page":8}},{"id":"sd-007","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, of the required supervised hours, how many must be in bad weather and how many at night?","o":["At least 10 of each","At least 5 of each","At least 20 of each","At least 15 of each"],"h1":"It is the same small number for both.","h2":"In South Dakota at least 10 of the supervised hours must be in bad weather and at least 10 at night, so new drivers practice in hard conditions with an adult.","p":"Right. At least 10 hours in bad weather and 10 at night."},"es":{"q":"En Dakota del Sur, de las horas supervisadas que se exigen, ¿cuántas deben ser con mal tiempo y cuántas de noche?","o":["Por lo menos 10 de cada una","Por lo menos 5 de cada una","Por lo menos 20 de cada una","Por lo menos 15 de cada una"],"h1":"Es el mismo número pequeño para las dos.","h2":"En Dakota del Sur por lo menos 10 de las horas supervisadas deben ser con mal tiempo y por lo menos 10 de noche, para que el conductor nuevo practique en condiciones difíciles con un adulto.","p":"Correcto. Por lo menos 10 horas con mal tiempo y 10 de noche."},"zh":{"q":"在 South Dakota，规定的监督驾驶时间中，多少小时必须在恶劣天气中，多少小时必须在夜间？","o":["各至少 10 小时","各至少 5 小时","各至少 20 小时","各至少 15 小时"],"h1":"两者是同一个较小的数字。","h2":"在 South Dakota，监督驾驶时间中至少 10 小时必须在恶劣天气中，至少 10 小时必须在夜间，这样新司机可以在成年人陪同下练习困难的路况。","p":"对。至少 10 小时恶劣天气，10 小时夜间。"},"vi":{"q":"Ở South Dakota, trong số giờ lái có giám sát bắt buộc, bao nhiêu giờ phải lái khi thời tiết xấu và bao nhiêu giờ vào ban đêm?","o":["Mỗi loại ít nhất 10 giờ","Mỗi loại ít nhất 5 giờ","Mỗi loại ít nhất 20 giờ","Mỗi loại ít nhất 15 giờ"],"h1":"Cả hai là cùng một con số nhỏ.","h2":"Ở South Dakota, ít nhất 10 giờ lái có giám sát phải là khi thời tiết xấu và ít nhất 10 giờ vào ban đêm, để tài xế mới tập lái trong điều kiện khó với người lớn đi cùng.","p":"Đúng. Ít nhất 10 giờ khi thời tiết xấu và 10 giờ ban đêm."},"tl":{"q":"Sa South Dakota, sa mga kinakailangang oras na may nagbabantay, ilan ang dapat sa masamang panahon at ilan sa gabi?","o":["Hindi bababa sa 10 bawat isa","Hindi bababa sa 5 bawat isa","Hindi bababa sa 20 bawat isa","Hindi bababa sa 15 bawat isa"],"h1":"Pareho itong maliit na numero para sa dalawa.","h2":"Sa South Dakota, hindi bababa sa 10 sa mga oras na may nagbabantay ang dapat sa masamang panahon at hindi bababa sa 10 sa gabi, para makapagsanay ang mga bagong drayber sa mahihirap na kondisyon kasama ang isang adult.","p":"Tama. Hindi bababa sa 10 oras sa masamang panahon at 10 sa gabi."},"ar":{"q":"في South Dakota، من ساعات الإشراف المطلوبة، كم ساعة يجب أن تكون في طقس سيئ وكم ساعة في الليل؟","o":["10 على الأقل لكل منهما","5 على الأقل لكل منهما","20 على الأقل لكل منهما","15 على الأقل لكل منهما"],"h1":"إنه نفس الرقم الصغير للاثنين.","h2":"في South Dakota يجب أن تكون 10 ساعات على الأقل من ساعات الإشراف في طقس سيئ و10 على الأقل في الليل، حتى يتدرّب السائقون الجدد على الظروف الصعبة مع شخص بالغ.","p":"صحيح. 10 ساعات على الأقل في طقس سيئ و10 في الليل."},"ref":{"doc":"SD","page":8}},{"id":"sd-008","scope":"SD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Dakota, what is the rule about phones for instruction permit holders while driving?","o":["Hands-free calls are allowed","Texting is allowed when stopped","Calls to parents are allowed","No wireless device may be used"],"h1":"The rule for permit holders is strict.","h2":"A South Dakota instruction permit holder may not use any kind of wireless communication device while driving, so all attention stays on learning to drive.","p":"Right. Permit holders may not use any wireless device while driving."},"es":{"q":"En Dakota del Sur, ¿cuál es la regla sobre el teléfono para quien tiene permiso de instrucción mientras maneja?","o":["Se permiten llamadas con manos libres","Se permite escribir mensajes parado","Se permiten llamadas a los padres","No se puede usar ningún aparato inalámbrico"],"h1":"La regla para los aprendices es estricta.","h2":"En Dakota del Sur quien tiene permiso de instrucción no puede usar ningún tipo de aparato de comunicación inalámbrico mientras maneja, para que toda la atención esté en aprender a manejar.","p":"Correcto. Con permiso de instrucción no se usa ningún aparato inalámbrico al manejar."},"zh":{"q":"在 South Dakota，持学习驾照的人开车时，关于手机的规定是什么？","o":["可以用免提打电话","停车时可以发短信","可以给父母打电话","不可以使用任何无线设备"],"h1":"对持学习驾照的人，规定很严格。","h2":"在 South Dakota，持学习驾照的人开车时不可以使用任何无线通信设备，这样所有注意力都放在学开车上。","p":"对。持学习驾照的人开车时不可以使用任何无线设备。"},"vi":{"q":"Ở South Dakota, quy định về điện thoại cho người có giấy phép tập lái khi đang lái xe là gì?","o":["Được gọi điện rảnh tay","Được nhắn tin khi xe dừng","Được gọi cho cha mẹ","Không được dùng bất kỳ thiết bị không dây nào"],"h1":"Quy định cho người có giấy phép tập lái rất nghiêm.","h2":"Người có giấy phép tập lái ở South Dakota không được dùng bất kỳ loại thiết bị liên lạc không dây nào khi lái xe, để mọi sự chú ý dành cho việc học lái.","p":"Đúng. Người có giấy phép tập lái không được dùng thiết bị không dây khi lái xe."},"tl":{"q":"Sa South Dakota, ano ang patakaran tungkol sa telepono para sa may instruction permit habang nagmamaneho?","o":["Puwede ang hands-free na tawag","Puwedeng mag-text kapag nakahinto","Puwedeng tumawag sa magulang","Bawal gumamit ng anumang wireless device"],"h1":"Mahigpit ang patakaran para sa may permit.","h2":"Ang may South Dakota instruction permit ay hindi puwedeng gumamit ng anumang uri ng wireless communication device habang nagmamaneho, para nasa pag-aaral magmaneho ang buong atensyon.","p":"Tama. Bawal sa may permit ang anumang wireless device habang nagmamaneho."},"ar":{"q":"في South Dakota، ما القاعدة بشأن الهواتف لحاملي تصريح التعلّم أثناء القيادة؟","o":["المكالمات بدون استخدام اليدين مسموحة","الرسائل النصية مسموحة عند التوقف","الاتصال بالوالدين مسموح","لا يجوز استخدام أي جهاز لاسلكي"],"h1":"القاعدة لحاملي التصريح صارمة.","h2":"لا يجوز لحامل تصريح التعلّم في South Dakota استخدام أي نوع من أجهزة الاتصال اللاسلكية أثناء القيادة، حتى يبقى كل انتباهه على تعلّم القيادة.","p":"صحيح. لا يجوز لحاملي التصريح استخدام أي جهاز لاسلكي أثناء القيادة."},"ref":{"doc":"SD","page":8}},{"id":"sd-009","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, during which hours may a restricted minor's permit holder drive alone with a parent's permission?","o":["5 a.m. to 9 p.m.","6 a.m. to 10 p.m.","7 a.m. to 11 p.m.","6 a.m. to midnight"],"h1":"They are the same hours as the instruction permit.","h2":"A South Dakota restricted minor's permit holder may drive alone between 6 a.m. and 10 p.m. with a parent's permission; at other hours a parent or guardian must ride along, with some exceptions.","p":"Right. Alone from 6 a.m. to 10 p.m."},"es":{"q":"En Dakota del Sur, ¿en qué horario puede manejar solo quien tiene permiso restringido de menor, con permiso de sus padres?","o":["De 5 a.m. a 9 p.m.","De 6 a.m. a 10 p.m.","De 7 a.m. a 11 p.m.","De 6 a.m. a medianoche"],"h1":"Es el mismo horario del permiso de instrucción.","h2":"En Dakota del Sur quien tiene permiso restringido de menor puede manejar solo entre las 6 a.m. y las 10 p.m. con permiso de sus padres; en otras horas debe ir un padre o tutor, con algunas excepciones.","p":"Correcto. Solo de 6 a.m. a 10 p.m."},"zh":{"q":"在 South Dakota，持未成年人限制驾照的人在父母允许下，哪个时间段可以单独开车？","o":["早上 5 点到晚上 9 点","早上 6 点到晚上 10 点","早上 7 点到晚上 11 点","早上 6 点到午夜"],"h1":"和学习驾照的时间相同。","h2":"在 South Dakota，持未成年人限制驾照的人在父母允许下，可以在早上 6 点到晚上 10 点之间单独开车；其他时间必须有父母或监护人同车，但有一些例外。","p":"对。早上 6 点到晚上 10 点可以单独开车。"},"vi":{"q":"Ở South Dakota, người có giấy phép hạn chế cho người chưa thành niên được lái xe một mình, khi cha mẹ cho phép, trong những giờ nào?","o":["5 giờ sáng đến 9 giờ tối","6 giờ sáng đến 10 giờ tối","7 giờ sáng đến 11 giờ tối","6 giờ sáng đến nửa đêm"],"h1":"Đó là cùng giờ với giấy phép tập lái.","h2":"Người có giấy phép hạn chế cho người chưa thành niên ở South Dakota được lái xe một mình từ 6 giờ sáng đến 10 giờ tối khi cha mẹ cho phép; vào giờ khác, cha mẹ hoặc người giám hộ phải đi cùng, trừ một số trường hợp.","p":"Đúng. Được lái một mình từ 6 giờ sáng đến 10 giờ tối."},"tl":{"q":"Sa South Dakota, sa anong oras puwedeng magmanehong mag-isa ang may restricted minor's permit kung may pahintulot ng magulang?","o":["5 a.m. hanggang 9 p.m.","6 a.m. hanggang 10 p.m.","7 a.m. hanggang 11 p.m.","6 a.m. hanggang hatinggabi"],"h1":"Pareho ito sa oras ng instruction permit.","h2":"Ang may South Dakota restricted minor's permit ay puwedeng magmanehong mag-isa mula 6 a.m. hanggang 10 p.m. kung may pahintulot ng magulang; sa ibang oras, dapat kasama ang magulang o guardian, maliban sa ilang eksepsyon.","p":"Tama. Mag-isa mula 6 a.m. hanggang 10 p.m."},"ar":{"q":"في South Dakota، في أي ساعات يمكن لحامل تصريح القاصر المقيَّد أن يقود وحده بإذن أحد الوالدين؟","o":["من 5 صباحًا إلى 9 مساءً","من 6 صباحًا إلى 10 مساءً","من 7 صباحًا إلى 11 مساءً","من 6 صباحًا إلى منتصف الليل"],"h1":"هي نفس ساعات تصريح التعلّم.","h2":"يمكن لحامل تصريح القاصر المقيَّد في South Dakota أن يقود وحده بين 6 صباحًا و10 مساءً بإذن أحد الوالدين؛ وفي الساعات الأخرى يجب أن يركب معه أحد الوالدين أو وليّ الأمر، مع بعض الاستثناءات.","p":"صحيح. وحده من 6 صباحًا إلى 10 مساءً."},"ref":{"doc":"SD","page":8}},{"id":"sd-010","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, which trip lets a restricted minor's permit holder drive alone after 10 p.m., by the most direct route?","o":["Going to a friend's party","Going to a late movie","Going to or from work","Going for a practice drive"],"h1":"Think of a needed trip, not one for fun.","h2":"A South Dakota restricted minor's permit holder may drive alone after 10 p.m. by the most direct route to or from work, school or church events, or farm work.","p":"Right. A direct trip to or from work is allowed."},"es":{"q":"En Dakota del Sur, ¿qué viaje permite a quien tiene permiso restringido de menor manejar solo después de las 10 p.m., por la ruta más directa?","o":["Ir a la fiesta de un amigo","Ir al cine tarde","Ir al trabajo o volver de él","Salir a practicar manejo"],"h1":"Piense en un viaje necesario, no en uno por diversión.","h2":"En Dakota del Sur quien tiene permiso restringido de menor puede manejar solo después de las 10 p.m. por la ruta más directa para ir o volver del trabajo, de eventos de la escuela o la iglesia, o de trabajo en el campo.","p":"Correcto. Un viaje directo al trabajo o desde él está permitido."},"zh":{"q":"在 South Dakota，哪种行程可以让持未成年人限制驾照的人在晚上 10 点以后走最直接的路线单独开车？","o":["去朋友的聚会","去看晚场电影","上班或下班","去练习开车"],"h1":"想一想必要的行程，而不是为了玩。","h2":"在 South Dakota，持未成年人限制驾照的人在晚上 10 点以后，可以走最直接的路线单独开车上下班、去或离开学校或教会的活动，或去做农场工作。","p":"对。直接上下班是允许的。"},"vi":{"q":"Ở South Dakota, chuyến đi nào cho phép người có giấy phép hạn chế cho người chưa thành niên lái xe một mình sau 10 giờ tối, theo đường ngắn nhất?","o":["Đi dự tiệc của bạn","Đi xem phim suất khuya","Đi làm hoặc đi làm về","Đi tập lái xe"],"h1":"Hãy nghĩ đến chuyến đi cần thiết, không phải đi chơi.","h2":"Người có giấy phép hạn chế cho người chưa thành niên ở South Dakota được lái xe một mình sau 10 giờ tối theo đường ngắn nhất để đi làm hoặc về, đi hoặc về từ hoạt động của trường hoặc nhà thờ, hoặc làm việc nông trại.","p":"Đúng. Được đi thẳng đến chỗ làm hoặc về nhà từ chỗ làm."},"tl":{"q":"Sa South Dakota, aling biyahe ang nagpapahintulot sa may restricted minor's permit na magmanehong mag-isa pagkatapos ng 10 p.m., sa pinakadiretsong ruta?","o":["Pagpunta sa party ng kaibigan","Pagpunta sa late na sine","Papunta o pauwi mula sa trabaho","Pagpunta para magsanay magmaneho"],"h1":"Isipin ang kailangang biyahe, hindi para sa kasiyahan.","h2":"Ang may South Dakota restricted minor's permit ay puwedeng magmanehong mag-isa pagkatapos ng 10 p.m. sa pinakadiretsong ruta papunta o pauwi mula sa trabaho, mga aktibidad ng paaralan o simbahan, o trabaho sa bukid.","p":"Tama. Pinapayagan ang diretsong biyahe papunta o pauwi mula sa trabaho."},"ar":{"q":"في South Dakota، أي رحلة تسمح لحامل تصريح القاصر المقيَّد أن يقود وحده بعد 10 مساءً، بأقصر طريق مباشر؟","o":["الذهاب إلى حفلة صديق","الذهاب إلى فيلم في وقت متأخر","الذهاب إلى العمل أو العودة منه","الذهاب للتدرّب على القيادة"],"h1":"فكّر في رحلة ضرورية، وليست للتسلية.","h2":"يمكن لحامل تصريح القاصر المقيَّد في South Dakota أن يقود وحده بعد 10 مساءً بأقصر طريق مباشر إلى العمل أو منه، أو إلى أنشطة المدرسة أو الكنيسة أو منها، أو لعمل المزرعة.","p":"صحيح. الرحلة المباشرة إلى العمل أو منه مسموحة."},"ref":{"doc":"SD","page":8}},{"id":"sd-011","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, during the first six months of a restricted minor's permit, who may ride as a passenger?","o":["Only immediate family or household members","Up to two friends under 18","Any passenger with a seat belt","Only passengers age 21 or older"],"h1":"The rule keeps friends out of the car at first.","h2":"For the first six months, a South Dakota restricted minor's permit holder may carry only immediate family or members of the same household, because friends in the car raise crash risk.","p":"Right. Only family or household members for the first six months."},"es":{"q":"En Dakota del Sur, durante los primeros seis meses del permiso restringido de menor, ¿quién puede ir como pasajero?","o":["Solo familia directa o personas de su hogar","Hasta dos amigos menores de 18","Cualquier pasajero con cinturón","Solo pasajeros de 21 años o más"],"h1":"La regla deja a los amigos fuera del carro al principio.","h2":"Durante los primeros seis meses, quien tiene permiso restringido de menor en Dakota del Sur solo puede llevar a su familia directa o a personas de su mismo hogar, porque los amigos en el carro aumentan el riesgo de choque.","p":"Correcto. Solo familia o personas del hogar los primeros seis meses."},"zh":{"q":"在 South Dakota，持未成年人限制驾照的最初六个月里，谁可以坐车当乘客？","o":["只有直系亲属或同住的家人","最多两个 18 岁以下的朋友","任何系好安全带的乘客","只有 21 岁或以上的乘客"],"h1":"这条规定在一开始不让朋友坐车。","h2":"在最初六个月里，South Dakota 持未成年人限制驾照的人只能载直系亲属或同住的家人，因为车上有朋友会提高车祸风险。","p":"对。最初六个月只能载家人或同住的人。"},"vi":{"q":"Ở South Dakota, trong sáu tháng đầu của giấy phép hạn chế cho người chưa thành niên, ai được đi xe làm hành khách?","o":["Chỉ người thân trong gia đình hoặc người cùng nhà","Tối đa hai bạn dưới 18 tuổi","Bất kỳ hành khách nào có thắt dây an toàn","Chỉ hành khách từ 21 tuổi trở lên"],"h1":"Quy định này không cho bạn bè lên xe lúc đầu.","h2":"Trong sáu tháng đầu, người có giấy phép hạn chế cho người chưa thành niên ở South Dakota chỉ được chở người thân trong gia đình hoặc người cùng nhà, vì có bạn bè trên xe làm tăng nguy cơ tai nạn.","p":"Đúng. Sáu tháng đầu chỉ chở người thân hoặc người cùng nhà."},"tl":{"q":"Sa South Dakota, sa unang anim na buwan ng restricted minor's permit, sino ang puwedeng sumakay bilang pasahero?","o":["Malapit na pamilya o kasama sa bahay lamang","Hanggang dalawang kaibigang wala pang 18","Sinumang pasaherong naka-seat belt","Mga pasaherong 21 pataas lamang"],"h1":"Hindi pinapasakay ng patakaran ang mga kaibigan sa simula.","h2":"Sa unang anim na buwan, ang may South Dakota restricted minor's permit ay puwedeng magsakay lamang ng malapit na pamilya o mga kasama sa iisang bahay, dahil tumataas ang panganib ng banggaan kapag may mga kaibigan sa sasakyan.","p":"Tama. Pamilya o kasama sa bahay lamang sa unang anim na buwan."},"ar":{"q":"في South Dakota، خلال الأشهر الستة الأولى من تصريح القاصر المقيَّد، من يمكنه الركوب كراكب؟","o":["أفراد العائلة المقرّبون أو من يسكنون في نفس البيت فقط","حتى صديقين عمرهما أقل من 18","أي راكب يربط حزام الأمان","الركاب الذين عمرهم 21 سنة أو أكثر فقط"],"h1":"القاعدة تُبعد الأصدقاء عن السيارة في البداية.","h2":"خلال الأشهر الستة الأولى، يمكن لحامل تصريح القاصر المقيَّد في South Dakota أن ينقل أفراد العائلة المقرّبين أو من يسكنون في نفس البيت فقط، لأن وجود الأصدقاء في السيارة يزيد خطر الحوادث.","p":"صحيح. العائلة أو أهل البيت فقط خلال الأشهر الستة الأولى."},"ref":{"doc":"SD","page":8}},{"id":"sd-012","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, after the first six months of a restricted minor's permit, how many non-family passengers under 18 may ride along?","o":["None at all","Two","Three","One"],"h1":"The limit is the smallest number above zero.","h2":"After six months, a South Dakota restricted minor's permit holder may carry no more than one passenger under 18 who is not family or from the same household.","p":"Right. Only one young non-family passenger."},"es":{"q":"En Dakota del Sur, después de los primeros seis meses del permiso restringido de menor, ¿cuántos pasajeros menores de 18 que no son familia pueden ir?","o":["Ninguno","Dos","Tres","Uno"],"h1":"El límite es el número más pequeño mayor que cero.","h2":"Después de seis meses, quien tiene permiso restringido de menor en Dakota del Sur puede llevar como máximo un pasajero menor de 18 que no sea de su familia ni de su hogar.","p":"Correcto. Solo un pasajero joven que no sea de la familia."},"zh":{"q":"在 South Dakota，持未成年人限制驾照满六个月以后，可以载几个 18 岁以下的非家人乘客？","o":["一个也不行","两个","三个","一个"],"h1":"这个限制是比零大的最小数字。","h2":"满六个月以后，South Dakota 持未成年人限制驾照的人最多只能载一个 18 岁以下、不是家人也不同住的乘客。","p":"对。只能载一个非家人的年轻乘客。"},"vi":{"q":"Ở South Dakota, sau sáu tháng đầu của giấy phép hạn chế cho người chưa thành niên, được chở bao nhiêu hành khách dưới 18 tuổi không phải người nhà?","o":["Không ai cả","Hai","Ba","Một"],"h1":"Giới hạn là số nhỏ nhất lớn hơn không.","h2":"Sau sáu tháng, người có giấy phép hạn chế cho người chưa thành niên ở South Dakota được chở không quá một hành khách dưới 18 tuổi không phải người nhà hoặc người cùng nhà.","p":"Đúng. Chỉ một hành khách trẻ không phải người nhà."},"tl":{"q":"Sa South Dakota, pagkatapos ng unang anim na buwan ng restricted minor's permit, ilang pasaherong hindi kapamilya na wala pang 18 ang puwedeng isakay?","o":["Wala talaga","Dalawa","Tatlo","Isa"],"h1":"Ang limitasyon ay ang pinakamaliit na numerong higit sa zero.","h2":"Pagkatapos ng anim na buwan, ang may South Dakota restricted minor's permit ay puwedeng magsakay ng hindi hihigit sa isang pasaherong wala pang 18 na hindi kapamilya o hindi kasama sa iisang bahay.","p":"Tama. Isang batang pasaherong hindi kapamilya lamang."},"ar":{"q":"في South Dakota، بعد الأشهر الستة الأولى من تصريح القاصر المقيَّد، كم راكبًا من غير العائلة عمره أقل من 18 يمكن أن يركب معه؟","o":["لا أحد أبدًا","اثنان","ثلاثة","واحد"],"h1":"الحد هو أصغر رقم أكبر من الصفر.","h2":"بعد ستة أشهر، يمكن لحامل تصريح القاصر المقيَّد في South Dakota أن ينقل راكبًا واحدًا فقط عمره أقل من 18 ليس من العائلة ولا من نفس البيت.","p":"صحيح. راكب شاب واحد فقط من غير العائلة."},"ref":{"doc":"SD","page":null}},{"id":"sd-013","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, what is the youngest age for a full operator's license?","o":["15 years old","15 and a half","16 years old","17 years old"],"h1":"It comes two years after the instruction permit age.","h2":"A South Dakota teen can get a full operator's license at 16, after holding a restricted minor's permit for six months with no traffic convictions.","p":"Right. The full license starts at age 16."},"es":{"q":"En Dakota del Sur, ¿cuál es la edad mínima para la licencia de operador completa?","o":["15 años","15 años y medio","16 años","17 años"],"h1":"Es dos años después de la edad del permiso de instrucción.","h2":"En Dakota del Sur un joven puede obtener la licencia de operador completa a los 16 años, después de tener el permiso restringido de menor seis meses sin infracciones de tránsito.","p":"Correcto. La licencia completa empieza a los 16 años."},"zh":{"q":"在 South Dakota，最小几岁可以拿到正式驾照（operator's license）？","o":["15 岁","15 岁半","16 岁","17 岁"],"h1":"它比拿学习驾照的年龄晚两年。","h2":"在 South Dakota，青少年持有未成年人限制驾照六个月、没有交通违规定罪后，16 岁就可以拿到正式驾照。","p":"对。正式驾照从 16 岁开始。"},"vi":{"q":"Ở South Dakota, tuổi nhỏ nhất để có bằng lái đầy đủ (operator's license) là bao nhiêu?","o":["15 tuổi","15 tuổi rưỡi","16 tuổi","17 tuổi"],"h1":"Nó đến hai năm sau tuổi có giấy phép tập lái.","h2":"Thanh thiếu niên ở South Dakota có thể có bằng lái đầy đủ khi 16 tuổi, sau khi giữ giấy phép hạn chế cho người chưa thành niên sáu tháng mà không bị kết tội vi phạm giao thông.","p":"Đúng. Bằng lái đầy đủ bắt đầu từ 16 tuổi."},"tl":{"q":"Sa South Dakota, ano ang pinakabatang edad para sa buong operator's license (lisensya sa pagmamaneho)?","o":["15 taong gulang","15 at kalahati","16 taong gulang","17 taong gulang"],"h1":"Dumarating ito dalawang taon pagkatapos ng edad para sa instruction permit.","h2":"Makakakuha ang kabataan sa South Dakota ng buong operator's license sa edad na 16, pagkatapos humawak ng restricted minor's permit nang anim na buwan nang walang traffic conviction.","p":"Tama. Nagsisimula ang buong lisensya sa edad na 16."},"ar":{"q":"في South Dakota، ما أصغر عمر للحصول على رخصة القيادة الكاملة (operator's license)؟","o":["15 سنة","15 سنة ونصف","16 سنة","17 سنة"],"h1":"تأتي بعد سنتين من عمر تصريح التعلّم.","h2":"يمكن للمراهق في South Dakota الحصول على رخصة القيادة الكاملة في عمر 16، بعد أن يحمل تصريح القاصر المقيَّد ستة أشهر بدون أي إدانة مرورية.","p":"صحيح. تبدأ الرخصة الكاملة من عمر 16 سنة."},"ref":{"doc":"SD","page":8}},{"id":"sd-014","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, a teen may not get a restricted minor's permit if they had a traffic conviction within the past how many months?","o":["3 months","6 months","12 months","24 months"],"h1":"It is half a year.","h2":"A South Dakota teen must have no traffic convictions in the six months before applying for a restricted minor's permit, which shows safe driving first.","p":"Right. No traffic convictions in the past six months."},"es":{"q":"En Dakota del Sur, ¿cuántos meses seguidos sin infracciones de tránsito necesita un joven antes de obtener el permiso restringido de menor?","o":["3 meses","6 meses","12 meses","24 meses"],"h1":"Es medio año.","h2":"En Dakota del Sur un joven no debe tener infracciones de tránsito en los seis meses antes de solicitar el permiso restringido de menor, para mostrar primero que maneja con seguridad.","p":"Correcto. Sin infracciones en los últimos seis meses."},"zh":{"q":"在 South Dakota，如果青少年在过去几个月内有交通违规定罪，就不能拿到未成年人限制驾照？","o":["3 个月","6 个月","12 个月","24 个月"],"h1":"它是半年。","h2":"在 South Dakota，青少年申请未成年人限制驾照前的六个月内，必须没有交通违规定罪，这先证明他能安全驾驶。","p":"对。过去六个月内没有交通违规定罪。"},"vi":{"q":"Ở South Dakota, thanh thiếu niên không được cấp giấy phép hạn chế cho người chưa thành niên nếu đã bị kết tội vi phạm giao thông trong bao nhiêu tháng vừa qua?","o":["3 tháng","6 tháng","12 tháng","24 tháng"],"h1":"Đó là nửa năm.","h2":"Thanh thiếu niên ở South Dakota phải không bị kết tội vi phạm giao thông nào trong sáu tháng trước khi xin giấy phép hạn chế cho người chưa thành niên, để chứng tỏ lái xe an toàn trước.","p":"Đúng. Không bị kết tội vi phạm giao thông trong sáu tháng qua."},"tl":{"q":"Sa South Dakota, hindi makakakuha ng restricted minor's permit ang kabataan kung nagkaroon siya ng traffic conviction sa nakaraang ilang buwan?","o":["3 buwan","6 na buwan","12 buwan","24 na buwan"],"h1":"Kalahating taon ito.","h2":"Ang kabataan sa South Dakota ay dapat walang traffic conviction sa anim na buwan bago mag-apply ng restricted minor's permit, na nagpapakita muna ng ligtas na pagmamaneho.","p":"Tama. Walang traffic conviction sa nakaraang anim na buwan."},"ar":{"q":"في South Dakota، لا يمكن للمراهق الحصول على تصريح القاصر المقيَّد إذا كانت لديه إدانة مرورية خلال كم شهرًا الماضية؟","o":["3 أشهر","6 أشهر","12 شهرًا","24 شهرًا"],"h1":"إنها نصف سنة.","h2":"يجب ألا تكون على المراهق في South Dakota أي إدانة مرورية في الأشهر الستة قبل التقدّم لتصريح القاصر المقيَّد، وهذا يُظهر القيادة الآمنة أولًا.","p":"صحيح. لا إدانات مرورية في الأشهر الستة الماضية."},"ref":{"doc":"SD","page":8}},{"id":"sd-015","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, what happens to a permit holder under 16 who is convicted of a traffic violation or breaks the permit limits?","o":["A 30-day suspension","Only a written warning","A free safety video","Nothing until age 18"],"h1":"The driver loses the right to drive for a short time.","h2":"In South Dakota a permit holder under 16 who is convicted of a traffic violation or breaks the permit limits has the permit suspended for 30 days.","p":"Right. It means a 30-day suspension."},"es":{"q":"En Dakota del Sur, ¿qué le pasa a quien tiene un permiso y es menor de 16 años si lo condenan por una infracción de tránsito o no cumple los límites del permiso?","o":["Una suspensión de 30 días","Solo una advertencia escrita","Un video gratis de seguridad","Nada hasta cumplir 18"],"h1":"El conductor pierde el derecho de manejar por un tiempo corto.","h2":"En Dakota del Sur, si una persona menor de 16 años con permiso es condenada por una infracción de tránsito o no cumple los límites del permiso, su permiso se suspende por 30 días.","p":"Correcto. Significa una suspensión de 30 días."},"zh":{"q":"在 South Dakota，16 岁以下持驾照许可的人如果交通违规被定罪，或违反许可的限制，会怎样？","o":["暂停 30 天","只有书面警告","一个免费的安全视频","到 18 岁前什么也不会发生"],"h1":"司机会在短时间内失去开车的权利。","h2":"在 South Dakota，16 岁以下持驾照许可的人如果交通违规被定罪，或违反许可的限制，许可会被暂停 30 天。","p":"对。这意味着暂停 30 天。"},"vi":{"q":"Ở South Dakota, điều gì xảy ra với người có giấy phép dưới 16 tuổi bị kết tội vi phạm giao thông hoặc vi phạm giới hạn của giấy phép?","o":["Bị đình chỉ 30 ngày","Chỉ bị cảnh cáo bằng văn bản","Một video an toàn miễn phí","Không có gì cho đến 18 tuổi"],"h1":"Tài xế mất quyền lái xe trong một thời gian ngắn.","h2":"Ở South Dakota, người có giấy phép dưới 16 tuổi bị kết tội vi phạm giao thông hoặc vi phạm giới hạn của giấy phép sẽ bị đình chỉ giấy phép 30 ngày.","p":"Đúng. Nghĩa là bị đình chỉ 30 ngày."},"tl":{"q":"Sa South Dakota, ano ang mangyayari sa may permit na wala pang 16 na nahatulan sa traffic violation o lumabag sa mga limitasyon ng permit?","o":["30 araw na suspensyon","Nakasulat na babala lamang","Libreng safety video","Wala hanggang edad 18"],"h1":"Mawawalan ang drayber ng karapatang magmaneho nang maikling panahon.","h2":"Sa South Dakota, ang may permit na wala pang 16 na nahatulan sa traffic violation o lumabag sa mga limitasyon ng permit ay masususpinde ang permit nang 30 araw.","p":"Tama. Ibig sabihin nito ay 30 araw na suspensyon."},"ar":{"q":"في South Dakota، ماذا يحدث لحامل تصريح عمره أقل من 16 إذا أُدين بمخالفة مرورية أو خالف حدود التصريح؟","o":["إيقاف لمدة 30 يومًا","إنذار مكتوب فقط","فيديو سلامة مجاني","لا شيء حتى عمر 18"],"h1":"يفقد السائق حق القيادة لفترة قصيرة.","h2":"في South Dakota، حامل التصريح الذي عمره أقل من 16 ويُدان بمخالفة مرورية أو يخالف حدود التصريح يُوقَف تصريحه لمدة 30 يومًا.","p":"صحيح. يعني ذلك إيقافًا لمدة 30 يومًا."},"ref":{"doc":"SD","page":null}},{"id":"sd-016","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, what score do you need to pass the knowledge test?","o":["60 percent or higher","70 percent or higher","75 percent or higher","80 percent or higher"],"h1":"It is four out of every five questions.","h2":"To pass the South Dakota knowledge test you need a score of 80 percent or higher.","p":"Right. You need 80 percent to pass."},"es":{"q":"En Dakota del Sur, ¿qué puntaje necesita para aprobar el examen de conocimientos?","o":["60 por ciento o más","70 por ciento o más","75 por ciento o más","80 por ciento o más"],"h1":"Son cuatro de cada cinco preguntas.","h2":"Para aprobar el examen de conocimientos de Dakota del Sur usted necesita un puntaje de 80 por ciento o más.","p":"Correcto. Necesita 80 por ciento para aprobar."},"zh":{"q":"在 South Dakota，笔试（knowledge test）需要多少分才能通过？","o":["60% 或以上","70% 或以上","75% 或以上","80% 或以上"],"h1":"每五道题要答对四道。","h2":"要通过 South Dakota 的笔试，你需要得到 80% 或以上。","p":"对。你需要 80% 才能通过。"},"vi":{"q":"Ở South Dakota, bạn cần bao nhiêu điểm để đậu bài thi kiến thức (knowledge test)?","o":["60% trở lên","70% trở lên","75% trở lên","80% trở lên"],"h1":"Đó là bốn trên mỗi năm câu hỏi.","h2":"Để đậu bài thi kiến thức ở South Dakota, bạn cần được 80% trở lên.","p":"Đúng. Bạn cần 80% để đậu."},"tl":{"q":"Sa South Dakota, anong score ang kailangan mo para pumasa sa knowledge test (nakasulat na pagsusulit)?","o":["60 porsiyento pataas","70 porsiyento pataas","75 porsiyento pataas","80 porsiyento pataas"],"h1":"Apat ito sa bawat limang tanong.","h2":"Para pumasa sa South Dakota knowledge test, kailangan mo ng score na 80 porsiyento pataas.","p":"Tama. Kailangan mo ng 80 porsiyento para pumasa."},"ar":{"q":"في South Dakota، ما الدرجة التي تحتاجها للنجاح في اختبار المعرفة (knowledge test)؟","o":["60 بالمئة أو أكثر","70 بالمئة أو أكثر","75 بالمئة أو أكثر","80 بالمئة أو أكثر"],"h1":"إنها أربعة من كل خمسة أسئلة.","h2":"للنجاح في اختبار المعرفة في South Dakota تحتاج إلى درجة 80 بالمئة أو أكثر.","p":"صحيح. تحتاج إلى 80 بالمئة للنجاح."},"ref":{"doc":"SD","page":null}},{"id":"sd-017","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, in which languages does state law say the written knowledge test must be offered?","o":["English only","English or Spanish","English, French, or German","Any language with a fee"],"h1":"State law names one language besides English.","h2":"South Dakota law says applicants may take the written knowledge test in English or Spanish.","p":"Right. The written test is offered in English or Spanish."},"es":{"q":"En Dakota del Sur, ¿en qué idiomas dice la ley del estado que se debe ofrecer el examen escrito de conocimientos?","o":["Solo en inglés","En inglés o en español","En inglés, francés o alemán","En cualquier idioma, pagando"],"h1":"La ley del estado nombra un idioma además del inglés.","h2":"La ley de Dakota del Sur dice que se puede tomar el examen escrito de conocimientos en inglés o en español.","p":"Correcto. El examen escrito se ofrece en inglés o en español."},"zh":{"q":"在 South Dakota，州法律规定笔试必须用哪些语言提供？","o":["只有英语","英语或西班牙语","英语、法语或德语","付费后任何语言"],"h1":"州法律除了英语，还写了一种语言。","h2":"South Dakota 法律规定，申请人可以用英语或西班牙语参加笔试。","p":"对。笔试用英语或西班牙语提供。"},"vi":{"q":"Ở South Dakota, luật tiểu bang nói bài thi kiến thức viết phải có bằng những ngôn ngữ nào?","o":["Chỉ tiếng Anh","Tiếng Anh hoặc tiếng Tây Ban Nha","Tiếng Anh, tiếng Pháp hoặc tiếng Đức","Bất kỳ ngôn ngữ nào nếu trả phí"],"h1":"Luật tiểu bang nêu một ngôn ngữ ngoài tiếng Anh.","h2":"Luật South Dakota nói người nộp đơn có thể làm bài thi kiến thức viết bằng tiếng Anh hoặc tiếng Tây Ban Nha.","p":"Đúng. Bài thi viết có bằng tiếng Anh hoặc tiếng Tây Ban Nha."},"tl":{"q":"Sa South Dakota, sa anong mga wika sinasabi ng batas ng estado na dapat ibigay ang nakasulat na knowledge test?","o":["Ingles lamang","Ingles o Espanyol","Ingles, Pranses, o Aleman","Anumang wika kung may bayad"],"h1":"Isang wika bukod sa Ingles ang binabanggit ng batas ng estado.","h2":"Sinasabi ng batas ng South Dakota na puwedeng kumuha ang mga aplikante ng nakasulat na knowledge test sa Ingles o Espanyol.","p":"Tama. Ibinibigay ang nakasulat na test sa Ingles o Espanyol."},"ar":{"q":"في South Dakota، بأي لغات يقول قانون الولاية إنه يجب تقديم اختبار المعرفة المكتوب؟","o":["الإنجليزية فقط","الإنجليزية أو الإسبانية","الإنجليزية أو الفرنسية أو الألمانية","أي لغة مقابل رسوم"],"h1":"يذكر قانون الولاية لغة واحدة غير الإنجليزية.","h2":"يقول قانون South Dakota إن المتقدّمين يمكنهم أداء اختبار المعرفة المكتوب بالإنجليزية أو الإسبانية.","p":"صحيح. يُقدَّم الاختبار المكتوب بالإنجليزية أو الإسبانية."},"ref":{"doc":"SD","page":null}},{"id":"sd-018","scope":"SD","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In South Dakota, what is the highest posted speed limit on rural stretches of interstate?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"It is higher than in most states.","h2":"Since 2015, South Dakota law allows up to 80 mph on interstates, and rural stretches may be posted at 80 mph, though the limit is lower near towns.","p":"Right. Rural South Dakota interstates go up to 80 mph."},"es":{"q":"En Dakota del Sur, ¿cuál es el límite de velocidad más alto en los tramos rurales de las interestatales?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Es más alto que en la mayoría de los estados.","h2":"Desde 2015, la ley de Dakota del Sur permite hasta 80 mph en las interestatales, y los tramos rurales pueden tener un límite de 80 mph, aunque el límite es más bajo cerca de los pueblos.","p":"Correcto. Las interestatales rurales de Dakota del Sur llegan a 80 mph."},"zh":{"q":"在 South Dakota，乡村路段的州际公路（interstate）上，标出的最高限速是多少？","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"它比大多数州都高。","h2":"从 2015 年起，South Dakota 法律允许州际公路限速最高到 80 mph，乡村路段可以标 80 mph，但靠近城镇时限速较低。","p":"对。South Dakota 乡村州际公路最高 80 mph。"},"vi":{"q":"Ở South Dakota, tốc độ tối đa được ghi trên biển ở các đoạn xa lộ liên bang (interstate) vùng nông thôn là bao nhiêu?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Nó cao hơn hầu hết các tiểu bang.","h2":"Từ năm 2015, luật South Dakota cho phép tối đa 80 mph trên xa lộ liên bang, và các đoạn nông thôn có thể ghi 80 mph, nhưng giới hạn thấp hơn khi gần thị trấn.","p":"Đúng. Xa lộ liên bang vùng nông thôn ở South Dakota lên đến 80 mph."},"tl":{"q":"Sa South Dakota, ano ang pinakamataas na nakapaskil na speed limit sa mga bahagi ng interstate sa probinsya?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Mas mataas ito kaysa sa karamihan ng estado.","h2":"Mula 2015, pinapayagan ng batas ng South Dakota ang hanggang 80 mph sa mga interstate, at puwedeng nakapaskil na 80 mph ang mga bahagi sa probinsya, pero mas mababa ang limit malapit sa mga bayan.","p":"Tama. Hanggang 80 mph ang mga interstate sa probinsya ng South Dakota."},"ar":{"q":"في South Dakota، ما أعلى حد سرعة مكتوب على الأجزاء الريفية من الطرق السريعة بين الولايات (interstate)؟","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"إنه أعلى من معظم الولايات.","h2":"منذ 2015، يسمح قانون South Dakota بسرعة تصل إلى 80 mph على الطرق السريعة بين الولايات، ويمكن أن تُكتب 80 mph على الأجزاء الريفية، لكن الحد أقل قرب المدن.","p":"صحيح. الطرق السريعة الريفية في South Dakota تصل إلى 80 mph."},"ref":{"doc":"SD","page":null}},{"id":"sd-019","scope":"SD","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In South Dakota, on a two-lane highway, how much must you slow down for a vehicle on the shoulder with warning lights (limit above 20 mph)?","o":["At least 20 mph below the limit","At least 5 mph below the limit","At least 10 mph below the limit","To exactly 15 mph"],"h1":"The number is the same as the speed in the 20 mph exception.","h2":"Under the South Dakota Move Over law, on a two-lane highway you must slow to at least 20 mph below the posted limit before passing a vehicle with warning lights on the shoulder.","p":"Right. Slow to at least 20 mph below the limit."},"es":{"q":"En Dakota del Sur, en una carretera de dos carriles, ¿cuánto debe bajar la velocidad ante un vehículo en el acotamiento con luces de advertencia (límite mayor de 20 mph)?","o":["Por lo menos 20 mph menos que el límite","Por lo menos 5 mph menos que el límite","Por lo menos 10 mph menos que el límite","Exactamente a 15 mph"],"h1":"Es el mismo número de la excepción de 20 mph.","h2":"Según la ley Move Over de Dakota del Sur, en una carretera de dos carriles usted debe bajar por lo menos a 20 mph menos que el límite antes de pasar junto a un vehículo con luces de advertencia en el acotamiento.","p":"Correcto. Baje por lo menos a 20 mph menos que el límite."},"zh":{"q":"在 South Dakota，在双车道公路上，遇到路肩上开着警示灯的车辆（限速高于 20 mph），你必须减速多少？","o":["至少比限速低 20 mph","至少比限速低 5 mph","至少比限速低 10 mph","正好减到 15 mph"],"h1":"这个数字和 20 mph 例外中的速度一样。","h2":"根据 South Dakota 的让道法（Move Over law），在双车道公路上，经过路肩上开着警示灯的车辆前，你必须减速到至少比标出的限速低 20 mph。","p":"对。减速到至少比限速低 20 mph。"},"vi":{"q":"Ở South Dakota, trên đường hai làn xe, bạn phải giảm tốc bao nhiêu khi gặp xe đậu bên lề có đèn cảnh báo (giới hạn tốc độ trên 20 mph)?","o":["Thấp hơn giới hạn ít nhất 20 mph","Thấp hơn giới hạn ít nhất 5 mph","Thấp hơn giới hạn ít nhất 10 mph","Đúng 15 mph"],"h1":"Con số này giống với tốc độ trong trường hợp ngoại lệ 20 mph.","h2":"Theo luật Nhường Làn (Move Over law) của South Dakota, trên đường hai làn xe, bạn phải giảm tốc xuống thấp hơn giới hạn ghi trên biển ít nhất 20 mph trước khi đi qua xe có đèn cảnh báo bên lề.","p":"Đúng. Giảm xuống thấp hơn giới hạn ít nhất 20 mph."},"tl":{"q":"Sa South Dakota, sa highway na may dalawang lane, gaano ka dapat bumagal para sa sasakyang nasa gilid ng daan na may warning lights (limit na higit sa 20 mph)?","o":["Hindi bababa sa 20 mph na mas mababa sa limit","Hindi bababa sa 5 mph na mas mababa sa limit","Hindi bababa sa 10 mph na mas mababa sa limit","Eksaktong 15 mph"],"h1":"Pareho ang numero sa bilis sa eksepsyon na 20 mph.","h2":"Ayon sa South Dakota Move Over law, sa highway na may dalawang lane, dapat kang bumagal nang hindi bababa sa 20 mph na mas mababa sa nakapaskil na limit bago lumampas sa sasakyang may warning lights sa gilid ng daan.","p":"Tama. Bumagal nang hindi bababa sa 20 mph na mas mababa sa limit."},"ar":{"q":"في South Dakota، على طريق ذي مسارين، كم يجب أن تخفّف سرعتك لمركبة على كتف الطريق بأضواء تحذير (الحد أعلى من 20 mph)؟","o":["20 mph على الأقل تحت الحد","5 mph على الأقل تحت الحد","10 mph على الأقل تحت الحد","إلى 15 mph بالضبط"],"h1":"الرقم هو نفس السرعة في استثناء 20 mph.","h2":"حسب قانون الإفساح (Move Over law) في South Dakota، على طريق ذي مسارين يجب أن تخفّف سرعتك إلى 20 mph على الأقل تحت الحد المكتوب قبل أن تمرّ بمركبة بأضواء تحذير على كتف الطريق.","p":"صحيح. خفّف إلى 20 mph على الأقل تحت الحد."},"ref":{"doc":"SD","page":2}},{"id":"sd-020","scope":"SD","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In South Dakota, on a highway with two or more lanes in your direction, when must you move to the lane farthest from a vehicle with warning lights?","o":["Only when you are beside it","Within 50 feet of it","At least 300 feet before it","After you pass it"],"h1":"Start early, about the length of a football field.","h2":"The South Dakota Move Over law says to move into the lane farthest from the vehicle at least 300 feet before reaching it, then proceed with caution.","p":"Right. Move over at least 300 feet before the vehicle."},"es":{"q":"En Dakota del Sur, en una carretera con dos o más carriles en su dirección, ¿cuándo debe pasarse al carril más lejano de un vehículo con luces de advertencia?","o":["Solo cuando esté a su lado","A menos de 50 pies de él","Por lo menos 300 pies antes","Después de pasarlo"],"h1":"Empiece temprano, como a la distancia de una cancha de fútbol americano.","h2":"La ley Move Over de Dakota del Sur dice que usted debe pasarse al carril más lejano del vehículo por lo menos 300 pies antes de llegar a él, y seguir con cuidado.","p":"Correcto. Cámbiese de carril por lo menos 300 pies antes."},"zh":{"q":"在 South Dakota，在你的方向有两条或更多车道的公路上，什么时候必须换到离开着警示灯的车辆最远的车道？","o":["只有在它旁边时","在离它 50 英尺内","在到它之前至少 300 英尺","经过它以后"],"h1":"要早一点开始，大约一个足球场的长度。","h2":"South Dakota 的让道法（Move Over law）规定，在到达那辆车之前至少 300 英尺，就要换到离它最远的车道，然后小心通过。","p":"对。在那辆车前至少 300 英尺就要让道。"},"vi":{"q":"Ở South Dakota, trên đường có hai làn trở lên theo hướng của bạn, khi nào bạn phải chuyển sang làn xa nhất so với xe có đèn cảnh báo?","o":["Chỉ khi bạn ở bên cạnh nó","Trong vòng 50 feet từ nó","Ít nhất 300 feet trước khi tới nó","Sau khi bạn đi qua nó"],"h1":"Bắt đầu sớm, khoảng chiều dài một sân bóng bầu dục.","h2":"Luật Nhường Làn (Move Over law) của South Dakota nói phải chuyển sang làn xa nhất so với chiếc xe đó ít nhất 300 feet trước khi tới nó, rồi đi tiếp cẩn thận.","p":"Đúng. Chuyển làn ít nhất 300 feet trước chiếc xe đó."},"tl":{"q":"Sa South Dakota, sa highway na may dalawa o higit pang lane sa direksyon mo, kailan ka dapat lumipat sa lane na pinakamalayo sa sasakyang may warning lights?","o":["Kapag katabi mo na lamang ito","Sa loob ng 50 talampakan mula rito","Hindi bababa sa 300 talampakan bago ito","Pagkatapos mo itong lampasan"],"h1":"Magsimula nang maaga, mga haba ng isang football field.","h2":"Sinasabi ng South Dakota Move Over law na lumipat sa lane na pinakamalayo sa sasakyan nang hindi bababa sa 300 talampakan bago ito marating, at magpatuloy nang maingat.","p":"Tama. Lumipat nang hindi bababa sa 300 talampakan bago ang sasakyan."},"ar":{"q":"في South Dakota، على طريق فيه مساران أو أكثر في اتجاهك، متى يجب أن تنتقل إلى المسار الأبعد عن مركبة بأضواء تحذير؟","o":["فقط عندما تكون بجانبها","على بعد 50 قدمًا منها","قبلها بـ 300 قدم على الأقل","بعد أن تتجاوزها"],"h1":"ابدأ مبكرًا، بطول ملعب كرة قدم أمريكية تقريبًا.","h2":"يقول قانون الإفساح (Move Over law) في South Dakota أن تنتقل إلى المسار الأبعد عن المركبة قبل الوصول إليها بـ 300 قدم على الأقل، ثم تتابع بحذر.","p":"صحيح. انتقل قبل المركبة بـ 300 قدم على الأقل."},"ref":{"doc":"SD","page":2}},{"id":"sd-021","scope":"SD","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In South Dakota, since July 2025, the Move Over law covers vehicles with which lights?","o":["Only red and blue police lights","Amber, yellow, or blue warning lights","Only white headlights","Only lights on fire trucks"],"h1":"The law grew to cover road crews and tow trucks too.","h2":"Since July 2025, the South Dakota Move Over law covers any vehicle on the shoulder showing amber, yellow, or blue warning lights, not only emergency vehicles.","p":"Right. Amber, yellow, and blue warning lights are covered."},"es":{"q":"En Dakota del Sur, desde julio de 2025, la ley Move Over incluye vehículos con ¿qué luces?","o":["Solo luces rojas y azules de policía","Luces de advertencia ámbar, amarillas o azules","Solo luces delanteras blancas","Solo las luces de los bomberos"],"h1":"La ley se amplió para incluir a cuadrillas de carretera y grúas.","h2":"Desde julio de 2025, la ley Move Over de Dakota del Sur incluye a cualquier vehículo en el acotamiento con luces de advertencia ámbar, amarillas o azules, no solo a los vehículos de emergencia.","p":"Correcto. Se incluyen las luces ámbar, amarillas y azules."},"zh":{"q":"在 South Dakota，从 2025 年 7 月起，让道法（Move Over law）包括开着哪些灯的车辆？","o":["只有红色和蓝色的警灯","琥珀色、黄色或蓝色的警示灯","只有白色的车头灯","只有消防车上的灯"],"h1":"这条法律扩大了，也包括道路施工车和拖车。","h2":"从 2025 年 7 月起，South Dakota 的让道法包括任何停在路肩上、开着琥珀色、黄色或蓝色警示灯的车辆，不只是紧急车辆。","p":"对。琥珀色、黄色和蓝色警示灯都包括在内。"},"vi":{"q":"Ở South Dakota, từ tháng 7 năm 2025, luật Nhường Làn (Move Over law) áp dụng cho xe có những loại đèn nào?","o":["Chỉ đèn cảnh sát màu đỏ và xanh dương","Đèn cảnh báo màu hổ phách, vàng hoặc xanh dương","Chỉ đèn pha màu trắng","Chỉ đèn trên xe cứu hỏa"],"h1":"Luật đã mở rộng để bao gồm cả đội sửa đường và xe kéo.","h2":"Từ tháng 7 năm 2025, luật Nhường Làn của South Dakota áp dụng cho mọi xe đậu bên lề có đèn cảnh báo màu hổ phách, vàng hoặc xanh dương, không chỉ xe cấp cứu.","p":"Đúng. Đèn cảnh báo màu hổ phách, vàng và xanh dương đều được bao gồm."},"tl":{"q":"Sa South Dakota, mula Hulyo 2025, saklaw ng Move Over law ang mga sasakyang may anong mga ilaw?","o":["Pula at asul na ilaw ng pulis lamang","Amber, dilaw, o asul na warning lights","Puting headlights lamang","Mga ilaw sa trak ng bumbero lamang"],"h1":"Lumawak ang batas para saklawin din ang mga road crew at tow truck.","h2":"Mula Hulyo 2025, saklaw ng South Dakota Move Over law ang anumang sasakyan sa gilid ng daan na may amber, dilaw, o asul na warning lights, hindi lamang mga emergency vehicle.","p":"Tama. Saklaw ang amber, dilaw, at asul na warning lights."},"ar":{"q":"في South Dakota، منذ يوليو 2025، يشمل قانون الإفساح (Move Over law) المركبات ذات أي أضواء؟","o":["أضواء الشرطة الحمراء والزرقاء فقط","أضواء تحذير كهرمانية أو صفراء أو زرقاء","المصابيح الأمامية البيضاء فقط","أضواء سيارات الإطفاء فقط"],"h1":"توسّع القانون ليشمل أيضًا عمّال الطرق وشاحنات السحب.","h2":"منذ يوليو 2025، يشمل قانون الإفساح في South Dakota أي مركبة على كتف الطريق تُظهر أضواء تحذير كهرمانية أو صفراء أو زرقاء، وليس مركبات الطوارئ فقط.","p":"صحيح. أضواء التحذير الكهرمانية والصفراء والزرقاء مشمولة."},"ref":{"doc":"SD","page":2}},{"id":"sd-022","scope":"SD","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In South Dakota, on a highway with two or more lanes in each direction, must you stop for a school bus with flashing red lights coming toward you?","o":["Yes, always","Yes, if children are visible","Only during school hours","No, but drive with care"],"h1":"On a wide highway, the rule depends on your direction.","h2":"In South Dakota, on a highway with two or more lanes in each direction, traffic going the opposite way does not have to stop for a school bus, but traffic behind the bus must stop.","p":"Right. Opposite traffic on a wide highway does not stop, but must take care."},"es":{"q":"En Dakota del Sur, en una carretera con dos o más carriles en cada dirección, ¿debe parar por un autobús escolar con luces rojas que viene de frente?","o":["Sí, siempre","Sí, si se ven niños","Solo en horario escolar","No, pero maneje con cuidado"],"h1":"En una carretera ancha, la regla depende de su dirección.","h2":"En Dakota del Sur, en una carretera con dos o más carriles en cada dirección, el tráfico que va en sentido contrario no tiene que parar por un autobús escolar, pero el tráfico detrás del autobús sí debe parar.","p":"Correcto. En una carretera ancha el tráfico contrario no para, pero debe tener cuidado."},"zh":{"q":"在 South Dakota，在每个方向有两条或更多车道的公路上，迎面开来的校车闪着红灯时，你必须停车吗？","o":["是，总是要停","是，如果看得到孩子","只在上学时间","不用，但要小心驾驶"],"h1":"在宽的公路上，规定取决于你的方向。","h2":"在 South Dakota，在每个方向有两条或更多车道的公路上，对面方向的车辆不必为校车停车，但校车后面的车辆必须停车。","p":"对。宽公路上对面方向的车辆不用停，但要小心。"},"vi":{"q":"Ở South Dakota, trên đường có hai làn trở lên mỗi hướng, bạn có phải dừng lại khi xe buýt trường học có đèn đỏ nhấp nháy chạy về phía bạn không?","o":["Có, luôn luôn","Có, nếu thấy trẻ em","Chỉ trong giờ học","Không, nhưng phải lái cẩn thận"],"h1":"Trên đường rộng, quy định tùy theo hướng đi của bạn.","h2":"Ở South Dakota, trên đường có hai làn trở lên mỗi hướng, xe đi ngược chiều không phải dừng lại vì xe buýt trường học, nhưng xe phía sau xe buýt phải dừng lại.","p":"Đúng. Xe ngược chiều trên đường rộng không dừng, nhưng phải cẩn thận."},"tl":{"q":"Sa South Dakota, sa highway na may dalawa o higit pang lane sa bawat direksyon, dapat ka bang huminto para sa school bus na may kumikislap na pulang ilaw na papalapit sa iyo?","o":["Oo, palagi","Oo, kung may nakikitang mga bata","Sa oras ng klase lamang","Hindi, pero magmaneho nang maingat"],"h1":"Sa malapad na highway, nakadepende ang patakaran sa direksyon mo.","h2":"Sa South Dakota, sa highway na may dalawa o higit pang lane sa bawat direksyon, hindi kailangang huminto para sa school bus ang trapikong papunta sa kabilang direksyon, pero dapat huminto ang trapikong nasa likod ng bus.","p":"Tama. Hindi humihinto ang trapiko sa kabilang direksyon sa malapad na highway, pero dapat mag-ingat."},"ar":{"q":"في South Dakota، على طريق فيه مساران أو أكثر في كل اتجاه، هل يجب أن تتوقف لحافلة مدرسية بأضواء حمراء وامضة قادمة نحوك؟","o":["نعم، دائمًا","نعم، إذا كان الأطفال ظاهرين","فقط في ساعات المدرسة","لا، لكن قُد بحذر"],"h1":"على طريق عريض، القاعدة تعتمد على اتجاهك.","h2":"في South Dakota، على طريق فيه مساران أو أكثر في كل اتجاه، ليس على السيارات في الاتجاه المعاكس أن تتوقف للحافلة المدرسية، لكن السيارات خلف الحافلة يجب أن تتوقف.","p":"صحيح. السيارات في الاتجاه المعاكس على طريق عريض لا تتوقف، لكن يجب أن تنتبه."},"ref":{"doc":"SD","page":null}},{"id":"sd-023","scope":"SD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Dakota, a driver under 21 breaks the law when driving with what blood alcohol level?","o":["0.01 percent or more","0.02 percent or more","0.05 percent or more","0.08 percent or more"],"h1":"It is far below the adult limit.","h2":"In South Dakota a driver under 21 may not drive with a blood alcohol level of 0.02 percent or more, because young drivers should not drink at all.","p":"Right. Under 21, the limit is 0.02 percent."},"es":{"q":"En Dakota del Sur, un conductor menor de 21 años viola la ley si maneja con ¿qué nivel de alcohol en la sangre?","o":["0.01 por ciento o más","0.02 por ciento o más","0.05 por ciento o más","0.08 por ciento o más"],"h1":"Es mucho más bajo que el límite de los adultos.","h2":"En Dakota del Sur un conductor menor de 21 años no puede manejar con 0.02 por ciento de alcohol en la sangre o más, porque los jóvenes no deben tomar nada.","p":"Correcto. Para menores de 21, el límite es 0.02 por ciento."},"zh":{"q":"在 South Dakota，21 岁以下的司机血液酒精浓度达到多少时开车就是违法？","o":["0.01% 或以上","0.02% 或以上","0.05% 或以上","0.08% 或以上"],"h1":"它远低于成年人的限度。","h2":"在 South Dakota，21 岁以下的司机血液酒精浓度达到 0.02% 或以上时不可以开车，因为年轻司机完全不应该喝酒。","p":"对。21 岁以下，限度是 0.02%。"},"vi":{"q":"Ở South Dakota, tài xế dưới 21 tuổi phạm luật khi lái xe với nồng độ cồn trong máu bao nhiêu?","o":["0.01% trở lên","0.02% trở lên","0.05% trở lên","0.08% trở lên"],"h1":"Nó thấp hơn nhiều so với giới hạn của người lớn.","h2":"Ở South Dakota, tài xế dưới 21 tuổi không được lái xe với nồng độ cồn trong máu từ 0.02% trở lên, vì tài xế trẻ hoàn toàn không nên uống rượu bia.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02%."},"tl":{"q":"Sa South Dakota, lumalabag sa batas ang drayber na wala pang 21 kapag nagmamaneho na may anong blood alcohol level?","o":["0.01 porsiyento pataas","0.02 porsiyento pataas","0.05 porsiyento pataas","0.08 porsiyento pataas"],"h1":"Mas mababa ito nang malayo sa limit para sa adult.","h2":"Sa South Dakota, ang drayber na wala pang 21 ay hindi puwedeng magmaneho na may blood alcohol level na 0.02 porsiyento pataas, dahil hindi dapat uminom ng alak ang mga batang drayber.","p":"Tama. Kung wala pang 21, ang limit ay 0.02 porsiyento."},"ar":{"q":"في South Dakota، يخالف السائق الذي عمره أقل من 21 القانون عند القيادة بأي نسبة كحول في الدم؟","o":["0.01 بالمئة أو أكثر","0.02 بالمئة أو أكثر","0.05 بالمئة أو أكثر","0.08 بالمئة أو أكثر"],"h1":"إنها أقل بكثير من حد البالغين.","h2":"في South Dakota لا يجوز للسائق الذي عمره أقل من 21 أن يقود بنسبة كحول في الدم 0.02 بالمئة أو أكثر، لأن السائقين الصغار يجب ألا يشربوا الكحول أبدًا.","p":"صحيح. تحت 21، الحد هو 0.02 بالمئة."},"ref":{"doc":"SD","page":20}},{"id":"sd-024","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, how long is an instruction permit valid?","o":["One year","Two years","Five years","Ten years"],"h1":"It lasts several years.","h2":"A South Dakota instruction permit is valid for five years, so a learner has plenty of time to complete the requirements.","p":"Right. The instruction permit is valid for five years."},"es":{"q":"En Dakota del Sur, ¿por cuánto tiempo es válido el permiso de instrucción?","o":["Un año","Dos años","Cinco años","Diez años"],"h1":"Dura varios años.","h2":"En Dakota del Sur el permiso de instrucción es válido por cinco años, así que el aprendiz tiene mucho tiempo para cumplir los requisitos.","p":"Correcto. El permiso de instrucción es válido por cinco años."},"zh":{"q":"在 South Dakota，学习驾照有效期多久？","o":["一年","两年","五年","十年"],"h1":"它可以用好几年。","h2":"South Dakota 的学习驾照有效期是五年，所以学习的人有足够的时间完成各项要求。","p":"对。学习驾照有效期是五年。"},"vi":{"q":"Ở South Dakota, giấy phép tập lái có giá trị bao lâu?","o":["Một năm","Hai năm","Năm năm","Mười năm"],"h1":"Nó kéo dài vài năm.","h2":"Giấy phép tập lái ở South Dakota có giá trị năm năm, nên người học có nhiều thời gian để hoàn thành các yêu cầu.","p":"Đúng. Giấy phép tập lái có giá trị năm năm."},"tl":{"q":"Sa South Dakota, gaano katagal valid ang instruction permit?","o":["Isang taon","Dalawang taon","Limang taon","Sampung taon"],"h1":"Tumatagal ito nang ilang taon.","h2":"Valid nang limang taon ang South Dakota instruction permit, kaya maraming oras ang nag-aaral para matapos ang mga kinakailangan.","p":"Tama. Valid nang limang taon ang instruction permit."},"ar":{"q":"في South Dakota، ما مدة صلاحية تصريح التعلّم؟","o":["سنة واحدة","سنتان","خمس سنوات","عشر سنوات"],"h1":"يدوم عدة سنوات.","h2":"تصريح التعلّم في South Dakota صالح لمدة خمس سنوات، لذلك لدى المتعلّم وقت كافٍ لإكمال المتطلبات.","p":"صحيح. تصريح التعلّم صالح لمدة خمس سنوات."},"ref":{"doc":"SD","page":8}},{"id":"sd-025","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, how many points within 12 months can lead to a license suspension?","o":["10 points","15 points","12 points","20 points"],"h1":"Over 24 months the number is 22.","h2":"In South Dakota you can have your license suspended if you collect 15 points within 12 months, or 22 points within 24 months.","p":"Right. Fifteen points in 12 months can bring a suspension."},"es":{"q":"En Dakota del Sur, ¿cuántos puntos en 12 meses pueden llevar a la suspensión de la licencia?","o":["10 puntos","15 puntos","12 puntos","20 puntos"],"h1":"En 24 meses el número es 22.","h2":"En Dakota del Sur le pueden suspender la licencia si acumula 15 puntos en 12 meses, o 22 puntos en 24 meses.","p":"Correcto. Quince puntos en 12 meses pueden traer una suspensión."},"zh":{"q":"在 South Dakota，12 个月内累计多少分可能会导致驾照被吊销？","o":["10 分","15 分","12 分","20 分"],"h1":"在 24 个月内，这个数字是 22 分。","h2":"在 South Dakota，如果你在 12 个月内累计 15 分，或在 24 个月内累计 22 分，你的驾照可能会被吊销。","p":"对。12 个月内累计 15 分可能会导致驾照被吊销。"},"vi":{"q":"Ở South Dakota, bị bao nhiêu điểm trong 12 tháng thì có thể bị treo bằng lái?","o":["10 điểm","15 điểm","12 điểm","20 điểm"],"h1":"Trong 24 tháng thì con số là 22 điểm.","h2":"Ở South Dakota, bạn có thể bị treo bằng lái nếu bị 15 điểm trong 12 tháng, hoặc 22 điểm trong 24 tháng.","p":"Đúng. Bị 15 điểm trong 12 tháng có thể khiến bạn bị treo bằng lái."},"tl":{"q":"Sa South Dakota, ilang puntos sa loob ng 12 buwan ang maaaring magdulot ng suspensyon ng lisensya?","o":["10 puntos","15 puntos","12 puntos","20 puntos"],"h1":"Sa loob ng 24 na buwan, ang bilang ay 22.","h2":"Sa South Dakota, maaaring masuspinde ang iyong lisensya kung makakuha ka ng 15 puntos sa loob ng 12 buwan, o 22 puntos sa loob ng 24 na buwan.","p":"Tama. Ang 15 puntos sa loob ng 12 buwan ay maaaring magdulot ng suspensyon."},"ar":{"q":"في South Dakota، كم نقطة خلال 12 شهرًا يمكن أن تؤدي إلى إيقاف رخصة القيادة؟","o":["10 نقاط","15 نقطة","12 نقطة","20 نقطة"],"h1":"خلال 24 شهرًا يكون العدد 22 نقطة.","h2":"في South Dakota يمكن إيقاف رخصتك إذا جمعت 15 نقطة خلال 12 شهرًا، أو 22 نقطة خلال 24 شهرًا.","p":"صحيح. جمع 15 نقطة خلال 12 شهرًا يمكن أن يؤدي إلى إيقاف الرخصة."},"ref":{"doc":"SD","page":14}},{"id":"sd-026","scope":"SD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Dakota, how long can you lose your driver license for refusing an alcohol test when an officer asks?","o":["30 days","90 days","Six months","One year"],"h1":"Driving on a public road means you agreed to be tested.","h2":"South Dakota can take away your driver license for a year if you say no to an alcohol test.","p":"Right. Refusing the test can cost you your license for one year."},"es":{"q":"En Dakota del Sur, ¿por cuánto tiempo puede perder su licencia de manejar si se niega a una prueba de alcohol cuando un oficial se lo pide?","o":["30 días","90 días","Seis meses","Un año"],"h1":"Manejar en una vía pública significa que usted aceptó hacerse la prueba.","h2":"Dakota del Sur le puede quitar la licencia de manejar por un año si usted dice que no a una prueba de alcohol.","p":"Correcto. Negarse a la prueba le puede costar la licencia por un año."},"zh":{"q":"在 South Dakota，如果警察要求你做酒精测试而你拒绝，你可能会失去驾照多久？","o":["30 天","90 天","六个月","一年"],"h1":"在公共道路上开车，就表示你已经同意接受测试。","h2":"在 South Dakota，如果你拒绝做酒精测试，你的驾照可能会被收回一年。","p":"对。拒绝测试可能让你失去驾照一年。"},"vi":{"q":"Ở South Dakota, bạn có thể bị mất bằng lái bao lâu nếu từ chối kiểm tra nồng độ cồn khi cảnh sát yêu cầu?","o":["30 ngày","90 ngày","Sáu tháng","Một năm"],"h1":"Lái xe trên đường công cộng có nghĩa là bạn đã đồng ý để được kiểm tra.","h2":"Ở South Dakota, bằng lái của bạn có thể bị lấy đi một năm nếu bạn từ chối kiểm tra nồng độ cồn.","p":"Đúng. Từ chối kiểm tra có thể làm bạn mất bằng lái một năm."},"tl":{"q":"Sa South Dakota, gaano katagal puwedeng mawala ang driver license mo kung tumanggi ka sa alcohol test kapag hiningi ito ng pulis?","o":["30 araw","90 araw","Anim na buwan","Isang taon"],"h1":"Ang pagmamaneho sa pampublikong daan ay nangangahulugang pumayag kang ma-test.","h2":"Sa South Dakota, puwedeng kunin ang driver license mo nang isang taon kung tumanggi ka sa alcohol test.","p":"Tama. Ang pagtanggi sa test ay puwedeng magpawala ng lisensya mo nang isang taon."},"ar":{"q":"في South Dakota، كم من الوقت قد تفقد رخصة القيادة إذا رفضت اختبار الكحول عندما يطلبه منك شرطي؟","o":["30 يومًا","90 يومًا","ستة أشهر","سنة واحدة"],"h1":"القيادة على طريق عام تعني أنك وافقت على إجراء الاختبار.","h2":"في South Dakota، قد تُسحب منك رخصة القيادة لمدة سنة إذا رفضت اختبار الكحول.","p":"صحيح. رفض الاختبار قد يُفقدك رخصتك لمدة سنة واحدة."},"ref":{"doc":"SD","page":20}},{"id":"sd-027","scope":"SD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Dakota, children under what age must ride in a child safety seat, unless they weigh at least 40 pounds?","o":["Under 5","Under 8","Under 3","Under 10"],"h1":"Children from this age up to 18 must wear a seat belt.","h2":"In South Dakota children under 5 must ride in a child safety seat, but a child under 5 who weighs at least 40 pounds may use a seat belt.","p":"Right. Children under 5 need a child safety seat unless they weigh 40 pounds or more."},"es":{"q":"En Dakota del Sur, ¿los niños menores de qué edad deben viajar en un asiento de seguridad para niños, a menos que pesen al menos 40 libras?","o":["Menores de 5","Menores de 8","Menores de 3","Menores de 10"],"h1":"Los niños desde esta edad hasta los 18 deben usar el cinturón de seguridad.","h2":"En Dakota del Sur los niños menores de 5 años deben viajar en un asiento de seguridad para niños, pero un niño menor de 5 que pese al menos 40 libras puede usar el cinturón.","p":"Correcto. Los niños menores de 5 años necesitan un asiento de seguridad, a menos que pesen 40 libras o más."},"zh":{"q":"在 South Dakota，几岁以下的儿童必须坐儿童安全座椅，除非体重至少 40 磅？","o":["5 岁以下","8 岁以下","3 岁以下","10 岁以下"],"h1":"从这个年龄到 18 岁的孩子必须系安全带。","h2":"在 South Dakota，5 岁以下的儿童必须坐儿童安全座椅，但体重至少 40 磅的 5 岁以下儿童可以使用安全带。","p":"对。5 岁以下的儿童需要坐儿童安全座椅，除非体重达到 40 磅或以上。"},"vi":{"q":"Ở South Dakota, trẻ em dưới bao nhiêu tuổi phải ngồi ghế an toàn cho trẻ em, trừ khi nặng ít nhất 40 pound?","o":["Dưới 5 tuổi","Dưới 8 tuổi","Dưới 3 tuổi","Dưới 10 tuổi"],"h1":"Trẻ em từ tuổi này đến 18 tuổi phải thắt dây an toàn.","h2":"Ở South Dakota, trẻ em dưới 5 tuổi phải ngồi ghế an toàn cho trẻ em, nhưng trẻ dưới 5 tuổi nặng ít nhất 40 pound có thể dùng dây an toàn.","p":"Đúng. Trẻ em dưới 5 tuổi cần ngồi ghế an toàn cho trẻ em, trừ khi nặng từ 40 pound trở lên."},"tl":{"q":"Sa South Dakota, ang mga batang wala pang ilang taong gulang ang dapat nakaupo sa child safety seat, maliban kung sila ay may timbang na hindi bababa sa 40 pounds?","o":["Wala pang 5","Wala pang 8","Wala pang 3","Wala pang 10"],"h1":"Ang mga bata mula sa edad na ito hanggang 18 ay dapat magsuot ng seat belt.","h2":"Sa South Dakota, ang mga batang wala pang 5 taong gulang ay dapat nakaupo sa child safety seat, pero ang batang wala pang 5 na may timbang na hindi bababa sa 40 pounds ay maaaring gumamit ng seat belt.","p":"Tama. Ang mga batang wala pang 5 ay kailangan ng child safety seat maliban kung sila ay 40 pounds o higit pa."},"ar":{"q":"في South Dakota، الأطفال دون أي عمر يجب أن يجلسوا في مقعد أمان للأطفال، إلا إذا كان وزنهم 40 رطلًا على الأقل؟","o":["دون 5 سنوات","دون 8 سنوات","دون 3 سنوات","دون 10 سنوات"],"h1":"الأطفال من هذا العمر حتى 18 سنة يجب أن يربطوا حزام الأمان.","h2":"في South Dakota يجب أن يجلس الأطفال دون 5 سنوات في مقعد أمان للأطفال، لكن الطفل دون 5 سنوات الذي يزن 40 رطلًا على الأقل يمكنه استخدام حزام الأمان.","p":"صحيح. الأطفال دون 5 سنوات يحتاجون إلى مقعد أمان للأطفال إلا إذا كان وزنهم 40 رطلًا أو أكثر."},"ref":{"doc":"SD","page":27}},{"id":"sd-028","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, how long is a driver license valid?","o":["2 years","4 years","8 years","5 years"],"h1":"It is the same length of time as the instruction permit.","h2":"In South Dakota, a driver license is valid for 5 years and expires on your birthday.","p":"Right. Five years."},"es":{"q":"En Dakota del Sur, ¿por cuánto tiempo es válida una licencia de conducir?","o":["2 años","4 años","8 años","5 años"],"h1":"Es el mismo tiempo que el permiso de aprendizaje.","h2":"En Dakota del Sur, una licencia de conducir es válida por 5 años y vence el día de su cumpleaños.","p":"Correcto. Cinco años."},"zh":{"q":"在 South Dakota，驾照的有效期是多长时间？","o":["2 年","4 年","8 年","5 年"],"h1":"它和学习驾照的有效期一样长。","h2":"在 South Dakota，驾照的有效期是 5 年，在你的生日那天到期。","p":"对。5 年。"},"vi":{"q":"Ở South Dakota, bằng lái xe có giá trị trong bao lâu?","o":["2 năm","4 năm","8 năm","5 năm"],"h1":"Thời gian này bằng với thời gian của giấy phép tập lái.","h2":"Ở South Dakota, bằng lái xe có giá trị trong 5 năm và hết hạn vào ngày sinh nhật của bạn.","p":"Đúng. 5 năm."},"tl":{"q":"Sa South Dakota, gaano katagal valid ang driver license?","o":["2 taon","4 na taon","8 taon","5 taon"],"h1":"Kapareho ito ng tagal ng instruction permit.","h2":"Sa South Dakota, valid ang driver license nang 5 taon at mag-e-expire ito sa iyong kaarawan.","p":"Tama. Limang taon."},"ar":{"q":"في South Dakota، ما مدة صلاحية رخصة القيادة؟","o":["2 سنة","4 سنوات","8 سنوات","5 سنوات"],"h1":"هي نفس مدة تصريح التعلّم.","h2":"في South Dakota، تكون رخصة القيادة صالحة لمدة 5 سنوات، وتنتهي في يوم عيد ميلادك.","p":"صحيح. خمس سنوات."},"ref":{"doc":"SD","page":12}},{"id":"sd-029","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, you renew a driver license that has already expired. Which test must you take besides the vision test?","o":["The knowledge test","The road skills test","A hearing test","No other test"],"h1":"It is the written test about road rules.","h2":"In South Dakota, if the license you turn in has expired, you must pass the knowledge test as well as the vision test.","p":"Right. The knowledge test too."},"es":{"q":"En Dakota del Sur, usted renueva una licencia que ya está vencida. ¿Qué examen debe tomar además del de la vista?","o":["El examen de conocimientos","El examen práctico de manejo","Un examen de audición","Ningún otro examen"],"h1":"Es el examen escrito sobre las reglas de tránsito.","h2":"En Dakota del Sur, si la licencia que entrega está vencida, debe aprobar el examen de conocimientos además del examen de la vista.","p":"Correcto. También el de conocimientos."},"zh":{"q":"在 South Dakota，你要更新一张已经过期的驾照。除了视力测试，你还必须参加哪项考试？","o":["知识考试（笔试）","路考","听力测试","不需要其他考试"],"h1":"就是关于交通规则的笔试。","h2":"在 South Dakota，如果你交回的驾照已经过期，除了视力测试，你还必须通过知识考试。","p":"对。还要考知识考试。"},"vi":{"q":"Ở South Dakota, bạn gia hạn một bằng lái đã hết hạn. Ngoài bài kiểm tra thị lực, bạn phải làm bài thi nào?","o":["Bài thi kiến thức","Bài thi lái xe trên đường","Bài kiểm tra thính lực","Không cần bài thi nào khác"],"h1":"Đó là bài thi viết về luật đi đường.","h2":"Ở South Dakota, nếu bằng lái bạn nộp lại đã hết hạn, bạn phải đậu bài thi kiến thức cùng với bài kiểm tra thị lực.","p":"Đúng. Phải thi cả bài thi kiến thức."},"tl":{"q":"Sa South Dakota, nagre-renew ka ng driver license na expired na. Anong pagsusulit ang dapat mong kunin bukod sa vision test?","o":["Ang knowledge test","Ang road skills test","Isang hearing test","Walang ibang pagsusulit"],"h1":"Ito ang nakasulat na pagsusulit tungkol sa mga patakaran sa daan.","h2":"Sa South Dakota, kung expired na ang license na isinusuko mo, kailangan mong pumasa sa knowledge test pati na sa vision test.","p":"Tama. Pati ang knowledge test."},"ar":{"q":"في South Dakota، تجدّد رخصة قيادة انتهت صلاحيتها بالفعل. ما الاختبار الذي يجب أن تأخذه إلى جانب اختبار النظر؟","o":["اختبار المعرفة","اختبار مهارات القيادة على الطريق","اختبار السمع","لا يوجد اختبار آخر"],"h1":"هو الاختبار الكتابي عن قواعد الطريق.","h2":"في South Dakota، إذا كانت الرخصة التي تسلّمها منتهية الصلاحية، يجب أن تنجح في اختبار المعرفة بالإضافة إلى اختبار النظر.","p":"صحيح. اختبار المعرفة أيضًا."},"ref":{"doc":"SD","page":12}},{"id":"sd-030","scope":"SD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Dakota, you park on a rural highway. How much road width must you leave for other traffic to pass?","o":["At least 5 feet","At least 10 feet","At least 15 feet","At least 30 feet"],"h1":"Other cars must still fit past you safely.","h2":"In South Dakota, when you park on a rural highway you must leave at least 15 feet of road width for other traffic to pass.","p":"Right. At least 15 feet."},"es":{"q":"En Dakota del Sur, usted se estaciona en una carretera rural. ¿Cuánto ancho de camino debe dejar para que pase el resto del tráfico?","o":["Al menos 5 pies","Al menos 10 pies","Al menos 15 pies","Al menos 30 pies"],"h1":"Los otros autos todavía deben poder pasar con seguridad.","h2":"En Dakota del Sur, cuando se estaciona en una carretera rural debe dejar al menos 15 pies de ancho de camino para que pase el resto del tráfico.","p":"Correcto. Al menos 15 pies."},"zh":{"q":"在 South Dakota，你把车停在乡村公路上。你必须留出多宽的路面让其他车辆通过？","o":["至少 5 英尺","至少 10 英尺","至少 15 英尺","至少 30 英尺"],"h1":"其他车辆仍然必须能安全地从你旁边开过去。","h2":"在 South Dakota，当你把车停在乡村公路上时，必须留出至少 15 英尺宽的路面让其他车辆通过。","p":"对。至少 15 英尺。"},"vi":{"q":"Ở South Dakota, bạn đậu xe trên đường cao tốc ở vùng nông thôn. Bạn phải chừa lại bao nhiêu bề rộng mặt đường để xe khác đi qua?","o":["Ít nhất 5 feet","Ít nhất 10 feet","Ít nhất 15 feet","Ít nhất 30 feet"],"h1":"Các xe khác vẫn phải đi qua bạn một cách an toàn.","h2":"Ở South Dakota, khi đậu xe trên đường cao tốc ở vùng nông thôn, bạn phải chừa lại ít nhất 15 feet bề rộng mặt đường để xe khác đi qua.","p":"Đúng. Ít nhất 15 feet."},"tl":{"q":"Sa South Dakota, pumarada ka sa isang rural highway. Gaano kalapad na daan ang dapat mong iwan para makadaan ang ibang sasakyan?","o":["Hindi bababa sa 5 talampakan","Hindi bababa sa 10 talampakan","Hindi bababa sa 15 talampakan","Hindi bababa sa 30 talampakan"],"h1":"Dapat ay ligtas pa ring makadaan sa tabi mo ang ibang sasakyan.","h2":"Sa South Dakota, kapag pumarada ka sa rural highway, dapat kang mag-iwan ng hindi bababa sa 15 talampakan na lapad ng daan para makadaan ang ibang sasakyan.","p":"Tama. Hindi bababa sa 15 talampakan."},"ar":{"q":"في South Dakota، توقف سيارتك على طريق سريع ريفي. ما عرض الطريق الذي يجب أن تتركه لتمرّ السيارات الأخرى؟","o":["5 أقدام على الأقل","10 أقدام على الأقل","15 قدمًا على الأقل","30 قدمًا على الأقل"],"h1":"يجب أن تتمكن السيارات الأخرى من المرور بجانبك بأمان.","h2":"في South Dakota، عندما توقف سيارتك على طريق سريع ريفي يجب أن تترك 15 قدمًا على الأقل من عرض الطريق لتمرّ السيارات الأخرى.","p":"صحيح. 15 قدمًا على الأقل."},"ref":{"doc":"SD","page":43}},{"id":"sd-031","scope":"SD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Dakota, what is the smallest following distance the manual says to keep behind the vehicle ahead?","o":["2 seconds","4 seconds","1 second","6 seconds"],"h1":"Count \"one thousand one, one thousand two...\" after the car ahead passes a pole.","h2":"In South Dakota, the manual says to keep a following distance of at least 4 seconds behind the vehicle in front.","p":"Right. At least 4 seconds."},"es":{"q":"En Dakota del Sur, ¿cuál es la distancia mínima que, según el manual, debe dejar detrás del vehículo de adelante?","o":["2 segundos","4 segundos","1 segundo","6 segundos"],"h1":"Cuente \"mil uno, mil dos...\" después de que el auto de adelante pase un poste.","h2":"En Dakota del Sur, el manual dice que debe mantener una distancia de al menos 4 segundos detrás del vehículo de adelante.","p":"Correcto. Al menos 4 segundos."},"zh":{"q":"在 South Dakota，手册说与前车之间至少要保持多长的跟车距离？","o":["2 秒","4 秒","1 秒","6 秒"],"h1":"前车经过一根电线杆后，开始数“一千零一，一千零二……”。","h2":"在 South Dakota，手册说与前车之间至少要保持 4 秒的跟车距离。","p":"对。至少 4 秒。"},"vi":{"q":"Ở South Dakota, theo sách hướng dẫn, khoảng cách tối thiểu cần giữ với xe phía trước là bao nhiêu?","o":["2 giây","4 giây","1 giây","6 giây"],"h1":"Đếm \"một nghìn lẻ một, một nghìn lẻ hai...\" sau khi xe phía trước đi qua một cột điện.","h2":"Ở South Dakota, sách hướng dẫn nói phải giữ khoảng cách ít nhất 4 giây với xe phía trước.","p":"Đúng. Ít nhất 4 giây."},"tl":{"q":"Sa South Dakota, ano ang pinakamaikling layo sa sasakyang nasa unahan na sinasabi ng manual na dapat mong panatilihin?","o":["2 segundo","4 na segundo","1 segundo","6 na segundo"],"h1":"Magbilang ng \"one thousand one, one thousand two...\" pagkalampas ng sasakyan sa unahan sa isang poste.","h2":"Sa South Dakota, sinasabi ng manual na panatilihin ang layong hindi bababa sa 4 na segundo sa likod ng sasakyang nasa unahan.","p":"Tama. Hindi bababa sa 4 na segundo."},"ar":{"q":"في South Dakota، ما أقل مسافة متابعة يقول الدليل أن تتركها خلف السيارة التي أمامك؟","o":["2 ثانية","4 ثوانٍ","1 ثانية","6 ثوانٍ"],"h1":"عُدّ \"ألف وواحد، ألف واثنان...\" بعد أن تمرّ السيارة التي أمامك بعمود.","h2":"في South Dakota، يقول الدليل أن تترك مسافة متابعة لا تقل عن 4 ثوانٍ خلف السيارة التي أمامك.","p":"صحيح. 4 ثوانٍ على الأقل."},"ref":{"doc":"SD","page":51}},{"id":"sd-032","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, you just moved here and have a valid license from another state (not a CDL). How soon must you apply for a South Dakota license?","o":["Within 30 days","Within 1 year","Within 90 days","Within 10 days"],"h1":"It is about three months.","h2":"In South Dakota, a new resident with a valid out-of-state license (not a CDL) must apply for a South Dakota license within 90 days.","p":"Right. Within 90 days."},"es":{"q":"En Dakota del Sur, usted acaba de mudarse y tiene una licencia válida de otro estado (no comercial). ¿En cuánto tiempo debe solicitar una licencia de Dakota del Sur?","o":["Dentro de 30 días","Dentro de 1 año","Dentro de 90 días","Dentro de 10 días"],"h1":"Son unos tres meses.","h2":"En Dakota del Sur, un nuevo residente con una licencia válida de otro estado (no comercial) debe solicitar la licencia de Dakota del Sur dentro de 90 días.","p":"Correcto. Dentro de 90 días."},"ref":{"doc":"SD","page":5}},{"id":"sd-033","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, what vision score with both eyes do you need for a license with no vision limits?","o":["20/40 or better","20/100 or better","20/70 or better","20/200 or better"],"h1":"It is the same number many states use for driving without glasses limits.","h2":"In South Dakota, you need 20/40 or better with both eyes, and no worse than 20/50 in either eye, for a license with no vision limits.","p":"Right. 20/40 or better with both eyes."},"es":{"q":"En Dakota del Sur, ¿qué resultado de visión con ambos ojos necesita para una licencia sin restricciones de visión?","o":["20/40 o mejor","20/100 o mejor","20/70 o mejor","20/200 o mejor"],"h1":"Es el mismo número que usan muchos estados para manejar sin restricciones de lentes.","h2":"En Dakota del Sur, necesita 20/40 o mejor con ambos ojos, y no peor que 20/50 en ningún ojo, para una licencia sin restricciones de visión.","p":"Correcto. 20/40 o mejor con ambos ojos."},"ref":{"doc":"SD","page":18}},{"id":"sd-034","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, how early may most drivers renew a license before it expires?","o":["Only on the day it expires","Up to 30 days before","Up to 2 years before","Up to 180 days before"],"h1":"It is about six months.","h2":"In South Dakota, most drivers may renew a license up to 180 days before it expires (drivers turning 21 follow a different rule).","p":"Right. Up to 180 days before."},"es":{"q":"En Dakota del Sur, ¿con cuánta anticipación puede la mayoría de los conductores renovar la licencia antes de que venza?","o":["Solo el día en que vence","Hasta 30 días antes","Hasta 2 años antes","Hasta 180 días antes"],"h1":"Son unos seis meses.","h2":"En Dakota del Sur, la mayoría de los conductores puede renovar la licencia hasta 180 días antes de que venza (quienes cumplen 21 años siguen otra regla).","p":"Correcto. Hasta 180 días antes."},"ref":{"doc":"SD","page":12}},{"id":"sd-035","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, you fail the knowledge test. When is the earliest you may take it again?","o":["The same day","The next working day","After 30 days","After 6 months"],"h1":"You do not have to wait long, but not the same day.","h2":"In South Dakota, if you fail a license test, you may not test again before the next working day.","p":"Right. The next working day at the earliest."},"es":{"q":"En Dakota del Sur, usted reprueba el examen de conocimientos. ¿Cuándo es lo más pronto que puede volver a tomarlo?","o":["El mismo día","El siguiente día hábil","Después de 30 días","Después de 6 meses"],"h1":"No tiene que esperar mucho, pero no el mismo día.","h2":"En Dakota del Sur, si reprueba un examen de licencia, no puede repetirlo antes del siguiente día hábil.","p":"Correcto. Lo más pronto, el siguiente día hábil."},"ref":{"doc":"SD","page":10}},{"id":"sd-036","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, besides the 12-month rule, how many points within 24 months can lead to a license suspension?","o":["10 points","30 points","22 points","18 points"],"h1":"It is a bit more than 20.","h2":"In South Dakota, a driver who gets 22 points within 24 months can have the license suspended.","p":"Right. 22 points in 24 months."},"es":{"q":"En Dakota del Sur, además de la regla de 12 meses, ¿cuántos puntos en 24 meses pueden causar la suspensión de la licencia?","o":["10 puntos","30 puntos","22 puntos","18 puntos"],"h1":"Es un poco más de 20.","h2":"En Dakota del Sur, un conductor que acumula 22 puntos en 24 meses puede perder la licencia por suspensión.","p":"Correcto. 22 puntos en 24 meses."},"ref":{"doc":"SD","page":14}},{"id":"sd-037","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, how long does a first license suspension for too many points last?","o":["60 days","10 days","5 years","Until age 25"],"h1":"It is about two months.","h2":"In South Dakota, a first suspension under the point system lasts 60 days.","p":"Right. 60 days."},"es":{"q":"En Dakota del Sur, ¿cuánto dura una primera suspensión de la licencia por acumular demasiados puntos?","o":["60 días","10 días","5 años","Hasta los 25 años"],"h1":"Son unos dos meses.","h2":"En Dakota del Sur, una primera suspensión por el sistema de puntos dura 60 días.","p":"Correcto. 60 días."},"ref":{"doc":"SD","page":14}},{"id":"sd-038","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, how many points go on your record for a reckless driving conviction?","o":["2 points","3 points","4 points","8 points"],"h1":"It is one of the highest point values, just below drunk driving.","h2":"In South Dakota, a reckless driving conviction puts 8 points on your driving record.","p":"Right. 8 points."},"es":{"q":"En Dakota del Sur, ¿cuántos puntos se agregan a su historial por una condena por manejo imprudente?","o":["2 puntos","3 puntos","4 puntos","8 puntos"],"h1":"Es uno de los valores más altos, justo por debajo de manejar ebrio.","h2":"En Dakota del Sur, una condena por manejo imprudente agrega 8 puntos a su historial de manejo.","p":"Correcto. 8 puntos."},"ref":{"doc":"SD","page":14}},{"id":"sd-039","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, you are convicted of driving without proof of insurance. For how long must you file proof of insurance (an SR22) with the state?","o":["6 months","3 years","10 years","Only until the fine is paid"],"h1":"It is more than one year but less than five.","h2":"In South Dakota, after a conviction for no proof of insurance, you must file proof of insurance (an SR22) with the state for 3 years.","p":"Right. For 3 years."},"es":{"q":"En Dakota del Sur, a usted lo condenan por manejar sin prueba de seguro. ¿Por cuánto tiempo debe presentar prueba de seguro (un SR22) ante el estado?","o":["6 meses","3 años","10 años","Solo hasta pagar la multa"],"h1":"Es más de un año, pero menos de cinco.","h2":"En Dakota del Sur, después de una condena por no tener prueba de seguro, debe presentar prueba de seguro (un SR22) ante el estado durante 3 años.","p":"Correcto. Durante 3 años."},"ref":{"doc":"SD","page":14}},{"id":"sd-040","scope":"SD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Dakota, a driver under 21 is caught for the first time with a blood alcohol level of 0.02 percent or more. How long is the license lost?","o":["7 days","5 years","30 days","Nothing happens the first time"],"h1":"It is about one month.","h2":"In South Dakota, a first zero tolerance offense by a driver under 21 brings a fine and a 30-day loss of the license.","p":"Right. 30 days."},"es":{"q":"En Dakota del Sur, a un conductor menor de 21 años lo detienen por primera vez con un nivel de alcohol en la sangre de 0.02 por ciento o más. ¿Por cuánto tiempo pierde la licencia?","o":["7 días","5 años","30 días","No pasa nada la primera vez"],"h1":"Es cerca de un mes.","h2":"En Dakota del Sur, una primera infracción de tolerancia cero de un conductor menor de 21 años trae una multa y la pérdida de la licencia por 30 días.","p":"Correcto. 30 días."},"ref":{"doc":"SD","page":20}},{"id":"sd-041","scope":"SD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Dakota, what kind of crime is a third offense for driving while intoxicated (DWI)?","o":["A parking ticket","A petty offense","A warning only","A felony"],"h1":"The third time is much more serious than the first two.","h2":"In South Dakota, a third DWI offense is a felony, with possible prison time and at least one year without a license.","p":"Right. A felony."},"es":{"q":"En Dakota del Sur, ¿qué tipo de delito es una tercera infracción por manejar en estado de ebriedad (DWI)?","o":["Una multa de estacionamiento","Una infracción menor","Solo una advertencia","Un delito grave (felonía)"],"h1":"La tercera vez es mucho más grave que las dos primeras.","h2":"En Dakota del Sur, una tercera infracción por DWI es un delito grave (felonía), con posible prisión y al menos un año sin licencia.","p":"Correcto. Un delito grave (felonía)."},"ref":{"doc":"SD","page":21}},{"id":"sd-042","scope":"SD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Dakota, who must wear a seat belt while the car is moving?","o":["The driver, front-seat passengers, and children under 18","Only the driver","Only children under 5","Only people on the interstate"],"h1":"Think of the front seat, and young people in any seat.","h2":"In South Dakota, the driver, all front-seat passengers, and children under 18 must wear a seat belt or proper restraint while the car is moving.","p":"Right. The driver, front-seat passengers, and children under 18."},"es":{"q":"En Dakota del Sur, ¿quién debe usar el cinturón de seguridad mientras el auto está en movimiento?","o":["El conductor, los pasajeros del asiento delantero y los menores de 18 años","Solo el conductor","Solo los niños menores de 5 años","Solo las personas en la autopista interestatal"],"h1":"Piense en el asiento delantero y en los jóvenes en cualquier asiento.","h2":"En Dakota del Sur, el conductor, todos los pasajeros del asiento delantero y los menores de 18 años deben usar cinturón de seguridad o el sistema de retención adecuado mientras el auto está en movimiento.","p":"Correcto. El conductor, los pasajeros del asiento delantero y los menores de 18 años."},"ref":{"doc":"SD","page":26}},{"id":"sd-043","scope":"SD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Dakota, what is the least light that window tint on the windshield and the front side windows must let through?","o":["5 percent","35 percent","90 percent","Any tint is allowed"],"h1":"It is about one third of the light.","h2":"In South Dakota, film on the windshield and the windows next to the driver may not cut the light that gets through below 35 percent.","p":"Right. 35 percent."},"es":{"q":"En Dakota del Sur, ¿cuál es la cantidad mínima de luz que debe dejar pasar el polarizado del parabrisas y de las ventanas laterales delanteras?","o":["5 por ciento","35 por ciento","90 por ciento","Se permite cualquier polarizado"],"h1":"Es cerca de un tercio de la luz.","h2":"En Dakota del Sur, la película en el parabrisas y en las ventanas junto al conductor no puede reducir la luz que pasa a menos del 35 por ciento.","p":"Correcto. 35 por ciento."},"ref":{"doc":"SD","page":24}},{"id":"sd-044","scope":"SD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Dakota, you pass a bicycle on a road where the speed limit is above 35 mph. How much space must you leave?","o":["1 foot","2 feet","3 feet","6 feet"],"h1":"On faster roads, the law asks for twice the space used on slow streets.","h2":"In South Dakota, you must leave at least 6 feet when passing a bicycle where the limit is above 35 mph, and at least 3 feet where it is 35 mph or less.","p":"Right. At least 6 feet."},"es":{"q":"En Dakota del Sur, usted rebasa a una bicicleta en una vía con límite de velocidad mayor de 35 mph. ¿Cuánto espacio debe dejar?","o":["1 pie","2 pies","3 pies","6 pies"],"h1":"En vías más rápidas, la ley pide el doble del espacio que en calles lentas.","h2":"En Dakota del Sur, debe dejar al menos 6 pies al rebasar a una bicicleta donde el límite es mayor de 35 mph, y al menos 3 pies donde es de 35 mph o menos.","p":"Correcto. Al menos 6 pies."},"ref":{"doc":"SD","page":62}},{"id":"sd-045","scope":"SD","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In South Dakota, how far before a turn should you turn on your signal?","o":["10 feet","1,000 feet","100 feet","Only once you start turning"],"h1":"It is about the length of a few houses.","h2":"In South Dakota, you should signal at least 100 feet before you turn.","p":"Right. 100 feet before the turn."},"es":{"q":"En Dakota del Sur, ¿con cuánta distancia antes de girar debe poner la direccional?","o":["10 pies","1,000 pies","100 pies","Solo cuando empieza a girar"],"h1":"Es más o menos el largo de unas cuantas casas.","h2":"En Dakota del Sur, debe poner la direccional al menos 100 pies antes de girar.","p":"Correcto. 100 pies antes del giro."},"ref":{"doc":"SD","page":56}},{"id":"sd-046","scope":"SD","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In South Dakota, a car is coming toward you at night. Within what distance should you dim your high beams?","o":["500 feet","50 feet","100 feet","2 miles"],"h1":"It is about one block.","h2":"In South Dakota, you should dim your high beams when you come within 500 feet of a car coming toward you.","p":"Right. Within 500 feet."},"es":{"q":"En Dakota del Sur, de noche, un auto viene hacia usted. ¿A qué distancia debe bajar las luces altas?","o":["500 pies","50 pies","100 pies","2 millas"],"h1":"Es más o menos una cuadra.","h2":"En Dakota del Sur, debe bajar las luces altas cuando esté a menos de 500 pies de un auto que viene hacia usted.","p":"Correcto. A 500 pies."},"ref":{"doc":"SD","page":55}},{"id":"sd-047","scope":"SD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Dakota, a snowplow has its red or amber lights on, on a road with a limit of 35 mph or more. How far behind it must you stay?","o":["20 feet","At least 200 feet","At least 1 mile","You may pass it on the right at any time"],"h1":"Plows throw snow and stop often. Leave a lot of room.","h2":"In South Dakota, on roads with a limit of 35 mph or more, you must stay at least 200 feet behind a snowplow with its red or amber lights on.","p":"Right. At least 200 feet."},"es":{"q":"En Dakota del Sur, un quitanieves tiene encendidas sus luces rojas o ámbar, en una vía con límite de 35 mph o más. ¿A qué distancia detrás de él debe mantenerse?","o":["20 pies","Al menos 200 pies","Al menos 1 milla","Puede rebasarlo por la derecha en cualquier momento"],"h1":"Los quitanieves lanzan nieve y se detienen a menudo. Deje mucho espacio.","h2":"En Dakota del Sur, en vías con límite de 35 mph o más, debe mantenerse al menos a 200 pies detrás de un quitanieves con sus luces rojas o ámbar encendidas.","p":"Correcto. Al menos 200 pies."},"ref":{"doc":"SD","page":67}},{"id":"sd-048","scope":"SD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Dakota, in which months should you be most alert for deer, because car-deer crashes are highest?","o":["June and July","January and February","March and April","October and November"],"h1":"Think of the fall season.","h2":"In South Dakota, car-deer crashes are highest in October and November, so be most alert for deer in those months, mainly at dusk and dawn.","p":"Right. October and November."},"es":{"q":"En Dakota del Sur, ¿en qué meses debe estar más atento a los venados, porque hay más choques con ellos?","o":["Junio y julio","Enero y febrero","Marzo y abril","Octubre y noviembre"],"h1":"Piense en el otoño.","h2":"En Dakota del Sur, los choques con venados son más frecuentes en octubre y noviembre, así que esté más atento en esos meses, sobre todo al amanecer y al anochecer.","p":"Correcto. Octubre y noviembre."},"ref":{"doc":"SD","page":50}},{"id":"sd-049","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, during which hours may a motorcycle instruction permit holder ride?","o":["6 a.m. to 8 p.m.","6 a.m. to 10 p.m.","Any time of day or night","Only after dark"],"h1":"Motorcycle permit riding ends earlier than car permit driving.","h2":"In South Dakota, a motorcycle instruction permit holder may ride only from 6 a.m. to 8 p.m., with a licensed rider on another motorcycle.","p":"Right. 6 a.m. to 8 p.m."},"es":{"q":"En Dakota del Sur, ¿en qué horario puede manejar quien tiene un permiso de aprendizaje de motocicleta?","o":["De 6 a.m. a 8 p.m.","De 6 a.m. a 10 p.m.","A cualquier hora del día o de la noche","Solo cuando está oscuro"],"h1":"El horario del permiso de motocicleta termina más temprano que el del permiso de auto.","h2":"En Dakota del Sur, quien tiene un permiso de aprendizaje de motocicleta solo puede manejar de 6 a.m. a 8 p.m., acompañado por un motociclista con licencia en otra motocicleta.","p":"Correcto. De 6 a.m. a 8 p.m."},"ref":{"doc":"SD","page":9}},{"id":"sd-050","scope":"SD","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In South Dakota, a funeral procession goes through an intersection. Which vehicle in it must obey the traffic signs and signals?","o":["Every vehicle in the procession","Only the last vehicle","Only the first vehicle","None of the vehicles"],"h1":"The others follow the one in front, with headlights on.","h2":"In South Dakota, only the first vehicle in a funeral procession must obey traffic signs and signals; the others keep their headlights on, and you must not cut into the line.","p":"Right. Only the first vehicle."},"es":{"q":"En Dakota del Sur, un cortejo fúnebre pasa por una intersección. ¿Qué vehículo del cortejo debe obedecer las señales y los semáforos?","o":["Todos los vehículos del cortejo","Solo el último vehículo","Solo el primer vehículo","Ninguno de los vehículos"],"h1":"Los demás siguen al de adelante, con los faros encendidos.","h2":"En Dakota del Sur, solo el primer vehículo de un cortejo fúnebre debe obedecer las señales y los semáforos; los demás llevan los faros encendidos, y usted no debe meterse en la fila.","p":"Correcto. Solo el primer vehículo."},"ref":{"doc":"SD","page":31}},{"id":"tn-001","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, what is the youngest age to get a learner permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before you can get an intermediate license.","h2":"You can get a Tennessee learner permit at 15 after passing the written and vision tests.","p":"Right. The learner permit starts at age 15."},"es":{"q":"En Tennessee, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de poder obtener la licencia intermedia.","h2":"Usted puede obtener el permiso de aprendiz en Tennessee a los 15 años, después de aprobar los exámenes escrito y de la vista.","p":"Correcto. El permiso de aprendiz empieza a los 15 años."},"zh":{"q":"在 Tennessee，最小几岁可以拿到学习驾照（learner permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"比可以拿中级驾照的年龄早一年。","h2":"你 15 岁通过笔试和视力测试后，就可以拿到 Tennessee 的学习驾照。","p":"对。学习驾照从 15 岁开始。"},"vi":{"q":"Ở Tennessee, tuổi nhỏ nhất để có giấy phép tập lái (learner permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là một năm trước khi bạn có thể lấy bằng lái trung cấp.","h2":"Bạn có thể lấy giấy phép tập lái của Tennessee lúc 15 tuổi sau khi đậu bài thi viết và bài kiểm tra thị lực.","p":"Đúng. Giấy phép tập lái bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Tennessee, ano ang pinakabatang edad para makakuha ng learner permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ka makakuha ng intermediate license.","h2":"Makakakuha ka ng Tennessee learner permit sa edad na 15 pagkatapos pumasa sa nakasulat na pagsusulit at sa pagsusuri sa mata.","p":"Tama. Nagsisimula ang learner permit sa edad na 15."},"ar":{"q":"في Tennessee، ما أصغر عمر للحصول على تصريح التعلّم (learner permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هو سنة واحدة قبل أن تستطيع الحصول على الرخصة المتوسطة.","h2":"يمكنك الحصول على تصريح التعلّم في Tennessee في عمر 15 سنة بعد النجاح في الاختبار الكتابي وفحص النظر.","p":"صحيح. يبدأ تصريح التعلّم في عمر 15 سنة."},"ref":{"doc":"TN","page":14}},{"id":"tn-002","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, who must be in the car when a learner permit holder drives?","o":["Any passenger age 16 or older","A licensed driver 18 or older in the back seat","A licensed driver 21 or older in the front seat","No one, during daylight hours"],"h1":"The helper must be an adult who can reach you and see the road.","h2":"A learner permit holder must always have a licensed driver who is 21 or older sitting in the front seat.","p":"Right. A licensed driver 21 or older must sit in the front seat."},"es":{"q":"En Tennessee, ¿quién debe ir en el carro cuando maneja alguien con permiso de aprendiz?","o":["Cualquier pasajero de 16 años o más","Un conductor con licencia de 18 años o más en el asiento de atrás","Un conductor con licencia de 21 años o más en el asiento de adelante","Nadie, durante el día"],"h1":"El acompañante debe ser un adulto que pueda alcanzarlo y ver el camino.","h2":"Quien tiene permiso de aprendiz siempre debe ir con un conductor con licencia de 21 años o más sentado en el asiento de adelante.","p":"Correcto. Un conductor con licencia de 21 años o más debe ir adelante."},"zh":{"q":"在 Tennessee，持学习驾照的人开车时，谁必须在车里？","o":["任何 16 岁或以上的乘客","坐在后座、18 岁或以上的持照司机","坐在前座、21 岁或以上的持照司机","不需要任何人，白天时"],"h1":"陪同的人必须是成年人，能碰到你，也能看到道路。","h2":"持学习驾照的人开车时，前座必须一直坐着一位 21 岁或以上的持照司机。","p":"对。一位 21 岁或以上的持照司机必须坐在前座。"},"vi":{"q":"Ở Tennessee, ai phải ngồi trong xe khi người có giấy phép tập lái lái xe?","o":["Bất kỳ hành khách nào từ 16 tuổi trở lên","Một tài xế có bằng lái từ 18 tuổi trở lên ngồi ở ghế sau","Một tài xế có bằng lái từ 21 tuổi trở lên ngồi ở ghế trước","Không cần ai, vào ban ngày"],"h1":"Người giúp đỡ phải là người lớn có thể với tới bạn và nhìn thấy đường.","h2":"Người có giấy phép tập lái luôn phải có một tài xế có bằng lái từ 21 tuổi trở lên ngồi ở ghế trước.","p":"Đúng. Một tài xế có bằng lái từ 21 tuổi trở lên phải ngồi ở ghế trước."},"tl":{"q":"Sa Tennessee, sino ang dapat nasa loob ng sasakyan kapag nagmamaneho ang may learner permit?","o":["Kahit sinong pasahero na 16 taong gulang pataas","Isang lisensyadong driver na 18 pataas sa likod na upuan","Isang lisensyadong driver na 21 pataas sa harap na upuan","Wala, kapag araw"],"h1":"Ang tutulong ay dapat isang adulto na maaabot ka at nakakakita ng daan.","h2":"Ang may learner permit ay dapat laging may kasamang lisensyadong driver na 21 taong gulang pataas na nakaupo sa harap na upuan.","p":"Tama. Isang lisensyadong driver na 21 pataas ang dapat nakaupo sa harap."},"ar":{"q":"في Tennessee، من يجب أن يكون في السيارة عندما يقود حامل تصريح التعلّم؟","o":["أي راكب عمره 16 سنة أو أكثر","سائق مرخّص عمره 18 سنة أو أكثر في المقعد الخلفي","سائق مرخّص عمره 21 سنة أو أكثر في المقعد الأمامي","لا أحد، في ساعات النهار"],"h1":"يجب أن يكون المساعد شخصًا بالغًا يستطيع الوصول إليك ورؤية الطريق.","h2":"يجب أن يكون مع حامل تصريح التعلّم دائمًا سائق مرخّص عمره 21 سنة أو أكثر يجلس في المقعد الأمامي.","p":"صحيح. يجب أن يجلس سائق مرخّص عمره 21 سنة أو أكثر في المقعد الأمامي."},"ref":{"doc":"TN","page":14}},{"id":"tn-003","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, during which hours may a learner permit holder not drive?","o":["10 p.m. to 6 a.m.","Midnight to 5 a.m.","11 p.m. to 6 a.m.","9 p.m. to 5 a.m."],"h1":"It starts two hours before midnight.","h2":"A learner permit holder may not drive between 10 p.m. and 6 a.m., even with an adult, because night driving is harder for beginners.","p":"Right. Learners do not drive from 10 p.m. to 6 a.m."},"es":{"q":"En Tennessee, ¿en qué horario no puede manejar quien tiene permiso de aprendiz?","o":["De 10 p.m. a 6 a.m.","De medianoche a 5 a.m.","De 11 p.m. a 6 a.m.","De 9 p.m. a 5 a.m."],"h1":"Empieza dos horas antes de la medianoche.","h2":"Quien tiene permiso de aprendiz no puede manejar entre las 10 p.m. y las 6 a.m., aun con un adulto, porque manejar de noche es más difícil para los principiantes.","p":"Correcto. Los aprendices no manejan de 10 p.m. a 6 a.m."},"zh":{"q":"在 Tennessee，持学习驾照的人在哪个时间段不可以开车？","o":["晚上 10 点到早上 6 点","午夜到早上 5 点","晚上 11 点到早上 6 点","晚上 9 点到早上 5 点"],"h1":"从午夜前两个小时开始。","h2":"持学习驾照的人在晚上 10 点到早上 6 点之间不可以开车，即使有成年人陪同也不行，因为晚上开车对新手更难。","p":"对。学习者从晚上 10 点到早上 6 点不开车。"},"vi":{"q":"Ở Tennessee, người có giấy phép tập lái không được lái xe trong khoảng giờ nào?","o":["10 giờ tối đến 6 giờ sáng","Nửa đêm đến 5 giờ sáng","11 giờ tối đến 6 giờ sáng","9 giờ tối đến 5 giờ sáng"],"h1":"Bắt đầu hai giờ trước nửa đêm.","h2":"Người có giấy phép tập lái không được lái xe từ 10 giờ tối đến 6 giờ sáng, kể cả khi có người lớn đi cùng, vì lái xe ban đêm khó hơn cho người mới.","p":"Đúng. Người tập lái không lái xe từ 10 giờ tối đến 6 giờ sáng."},"tl":{"q":"Sa Tennessee, sa anong mga oras hindi puwedeng magmaneho ang may learner permit?","o":["10 p.m. hanggang 6 a.m.","Hatinggabi hanggang 5 a.m.","11 p.m. hanggang 6 a.m.","9 p.m. hanggang 5 a.m."],"h1":"Nagsisimula ito dalawang oras bago maghatinggabi.","h2":"Hindi puwedeng magmaneho ang may learner permit mula 10 p.m. hanggang 6 a.m., kahit may kasamang adulto, dahil mas mahirap ang pagmamaneho sa gabi para sa mga baguhan.","p":"Tama. Hindi nagmamaneho ang mga learner mula 10 p.m. hanggang 6 a.m."},"ar":{"q":"في Tennessee، في أي ساعات لا يجوز لحامل تصريح التعلّم أن يقود؟","o":["من 10 مساءً إلى 6 صباحًا","من منتصف الليل إلى 5 صباحًا","من 11 مساءً إلى 6 صباحًا","من 9 مساءً إلى 5 صباحًا"],"h1":"تبدأ قبل منتصف الليل بساعتين.","h2":"لا يجوز لحامل تصريح التعلّم أن يقود بين 10 مساءً و6 صباحًا، حتى مع شخص بالغ، لأن القيادة في الليل أصعب على المبتدئين.","p":"صحيح. المتعلّمون لا يقودون من 10 مساءً إلى 6 صباحًا."},"ref":{"doc":"TN","page":14}},{"id":"tn-004","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, how long must a teen hold a learner permit before getting an intermediate restricted license?","o":["90 days","30 days","One year","180 days"],"h1":"It is about half a year.","h2":"A teen must hold the learner permit for at least 180 days before moving up to the intermediate restricted license.","p":"Right. You must hold the permit for 180 days."},"es":{"q":"En Tennessee, ¿cuánto tiempo debe tener un joven el permiso de aprendiz antes de obtener la licencia intermedia restringida?","o":["90 días","30 días","Un año","180 días"],"h1":"Es más o menos medio año.","h2":"Un joven debe tener el permiso de aprendiz por lo menos 180 días antes de pasar a la licencia intermedia restringida.","p":"Correcto. Debe tener el permiso 180 días."},"zh":{"q":"在 Tennessee，青少年必须持有学习驾照多久，才能拿到中级限制驾照（intermediate restricted license）？","o":["90 天","30 天","一年","180 天"],"h1":"大约是半年。","h2":"青少年必须持有学习驾照至少 180 天，才能升级到中级限制驾照。","p":"对。你必须持有学习驾照 180 天。"},"vi":{"q":"Ở Tennessee, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái trung cấp có hạn chế (intermediate restricted license)?","o":["90 ngày","30 ngày","Một năm","180 ngày"],"h1":"Khoảng nửa năm.","h2":"Thiếu niên phải giữ giấy phép tập lái ít nhất 180 ngày trước khi lên bằng lái trung cấp có hạn chế.","p":"Đúng. Bạn phải giữ giấy phép 180 ngày."},"tl":{"q":"Sa Tennessee, gaano katagal dapat hawak ng isang teen ang learner permit bago makakuha ng intermediate restricted license?","o":["90 araw","30 araw","Isang taon","180 araw"],"h1":"Mga kalahating taon ito.","h2":"Dapat hawak ng teen ang learner permit nang hindi bababa sa 180 araw bago umakyat sa intermediate restricted license.","p":"Tama. Dapat mong hawakan ang permit nang 180 araw."},"ar":{"q":"في Tennessee، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل الحصول على الرخصة المتوسطة المقيّدة (intermediate restricted license)؟","o":["90 يومًا","30 يومًا","سنة واحدة","180 يومًا"],"h1":"هي نحو نصف سنة.","h2":"يجب أن يحمل المراهق تصريح التعلّم 180 يومًا على الأقل قبل الانتقال إلى الرخصة المتوسطة المقيّدة.","p":"صحيح. يجب أن تحمل التصريح 180 يومًا."},"ref":{"doc":"TN","page":14}},{"id":"tn-005","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, how many hours of driving practice must a teen complete before an intermediate restricted license?","o":["30 hours","50 hours","40 hours","100 hours"],"h1":"It is half of one hundred.","h2":"A teen needs 50 hours of behind-the-wheel practice before an intermediate restricted license, signed off by a parent, guardian or driving instructor.","p":"Right. Tennessee asks for 50 hours of practice."},"es":{"q":"En Tennessee, ¿cuántas horas de práctica de manejo debe completar un joven antes de la licencia intermedia restringida?","o":["30 horas","50 horas","40 horas","100 horas"],"h1":"Es la mitad de cien.","h2":"Un joven necesita 50 horas de práctica al volante antes de la licencia intermedia restringida, certificadas por su padre, madre, tutor o instructor de manejo.","p":"Correcto. Tennessee pide 50 horas de práctica."},"zh":{"q":"在 Tennessee，青少年在拿中级限制驾照之前，必须完成多少小时的开车练习？","o":["30 小时","50 小时","40 小时","100 小时"],"h1":"是一百的一半。","h2":"青少年在拿中级限制驾照之前，需要 50 小时的实际开车练习，并由父母、监护人或驾驶教练签字确认。","p":"对。Tennessee 要求 50 小时的练习。"},"vi":{"q":"Ở Tennessee, thiếu niên phải tập lái bao nhiêu giờ trước khi lấy bằng lái trung cấp có hạn chế?","o":["30 giờ","50 giờ","40 giờ","100 giờ"],"h1":"Đó là một nửa của một trăm.","h2":"Thiếu niên cần 50 giờ tập lái thực tế trước khi lấy bằng lái trung cấp có hạn chế, có chữ ký xác nhận của cha mẹ, người giám hộ hoặc thầy dạy lái.","p":"Đúng. Tennessee yêu cầu 50 giờ tập lái."},"tl":{"q":"Sa Tennessee, ilang oras ng pagsasanay sa pagmamaneho ang dapat tapusin ng isang teen bago ang intermediate restricted license?","o":["30 oras","50 oras","40 oras","100 oras"],"h1":"Kalahati ito ng isang daan.","h2":"Kailangan ng teen ang 50 oras ng aktuwal na pagsasanay sa pagmamaneho bago ang intermediate restricted license, na pinirmahan ng magulang, guardian o driving instructor.","p":"Tama. Humihingi ang Tennessee ng 50 oras na pagsasanay."},"ar":{"q":"في Tennessee، كم ساعة من التدريب على القيادة يجب أن يكملها المراهق قبل الرخصة المتوسطة المقيّدة؟","o":["30 ساعة","50 ساعة","40 ساعة","100 ساعة"],"h1":"هي نصف المئة.","h2":"يحتاج المراهق إلى 50 ساعة من التدريب الفعلي خلف المقود قبل الرخصة المتوسطة المقيّدة، ويوقّع عليها أحد الوالدين أو الوصي أو مدرّب القيادة.","p":"صحيح. تطلب Tennessee خمسين ساعة (50) من التدريب."},"ref":{"doc":"TN","page":14}},{"id":"tn-006","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, how many of the required practice hours must be at night?","o":["2 hours","5 hours","10 hours","25 hours"],"h1":"It is one fifth of the total.","h2":"At least 10 of the 50 practice hours must be at night, so the teen has practiced in the dark with help.","p":"Right. At least 10 hours must be at night."},"es":{"q":"En Tennessee, ¿cuántas de las horas de práctica requeridas deben ser de noche?","o":["2 horas","5 horas","10 horas","25 horas"],"h1":"Es la quinta parte del total.","h2":"Por lo menos 10 de las 50 horas de práctica deben ser de noche, para que el joven haya practicado en la oscuridad con ayuda.","p":"Correcto. Por lo menos 10 horas deben ser de noche."},"zh":{"q":"在 Tennessee，规定的练习时间中，有多少小时必须在晚上？","o":["2 小时","5 小时","10 小时","25 小时"],"h1":"是总数的五分之一。","h2":"50 小时练习中至少有 10 小时必须在晚上，这样青少年就在有人帮助的情况下练习过在黑暗中开车。","p":"对。至少 10 小时必须在晚上。"},"vi":{"q":"Ở Tennessee, trong số giờ tập lái bắt buộc, bao nhiêu giờ phải vào ban đêm?","o":["2 giờ","5 giờ","10 giờ","25 giờ"],"h1":"Đó là một phần năm của tổng số.","h2":"Ít nhất 10 trong 50 giờ tập lái phải vào ban đêm, để thiếu niên đã tập lái trong bóng tối khi có người giúp.","p":"Đúng. Ít nhất 10 giờ phải vào ban đêm."},"tl":{"q":"Sa Tennessee, ilan sa mga kailangang oras ng pagsasanay ang dapat sa gabi?","o":["2 oras","5 oras","10 oras","25 oras"],"h1":"Isang ikalima ito ng kabuuan.","h2":"Hindi bababa sa 10 sa 50 oras ng pagsasanay ang dapat sa gabi, para nakapagsanay ang teen sa dilim nang may tumutulong.","p":"Tama. Hindi bababa sa 10 oras ang dapat sa gabi."},"ar":{"q":"في Tennessee، كم ساعة من ساعات التدريب المطلوبة يجب أن تكون في الليل؟","o":["ساعتان (2)","5 ساعات","10 ساعات","25 ساعة"],"h1":"هي خُمس المجموع.","h2":"يجب أن تكون 10 ساعات على الأقل من الـ 50 ساعة تدريب في الليل، حتى يكون المراهق قد تدرّب في الظلام مع من يساعده.","p":"صحيح. يجب أن تكون 10 ساعات على الأقل في الليل."},"ref":{"doc":"TN","page":14}},{"id":"tn-007","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, what is the youngest age for an intermediate restricted license?","o":["16 years old","15 years old","17 years old","18 years old"],"h1":"It is one year after the learner permit age.","h2":"You can get an intermediate restricted license at 16, after holding your permit 180 days, finishing your practice hours and passing a road test.","p":"Right. The intermediate restricted license starts at 16."},"es":{"q":"En Tennessee, ¿cuál es la edad mínima para la licencia intermedia restringida?","o":["16 años","15 años","17 años","18 años"],"h1":"Es un año después de la edad del permiso de aprendiz.","h2":"Usted puede obtener la licencia intermedia restringida a los 16 años, después de tener el permiso 180 días, terminar sus horas de práctica y aprobar el examen de manejo.","p":"Correcto. La licencia intermedia restringida empieza a los 16."},"zh":{"q":"在 Tennessee，最小几岁可以拿到中级限制驾照？","o":["16 岁","15 岁","17 岁","18 岁"],"h1":"比拿学习驾照的年龄晚一年。","h2":"你 16 岁时，在持有学习驾照 180 天、完成练习时间并通过路考之后，就可以拿到中级限制驾照。","p":"对。中级限制驾照从 16 岁开始。"},"vi":{"q":"Ở Tennessee, tuổi nhỏ nhất để có bằng lái trung cấp có hạn chế là bao nhiêu?","o":["16 tuổi","15 tuổi","17 tuổi","18 tuổi"],"h1":"Đó là một năm sau tuổi lấy giấy phép tập lái.","h2":"Bạn có thể lấy bằng lái trung cấp có hạn chế lúc 16 tuổi, sau khi giữ giấy phép tập lái 180 ngày, hoàn thành số giờ tập lái và đậu bài thi lái xe trên đường.","p":"Đúng. Bằng lái trung cấp có hạn chế bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Tennessee, ano ang pinakabatang edad para sa intermediate restricted license?","o":["16 taong gulang","15 taong gulang","17 taong gulang","18 taong gulang"],"h1":"Isang taon ito pagkatapos ng edad para sa learner permit.","h2":"Makakakuha ka ng intermediate restricted license sa edad na 16, pagkatapos hawakan ang permit nang 180 araw, tapusin ang mga oras ng pagsasanay at pumasa sa road test.","p":"Tama. Nagsisimula ang intermediate restricted license sa edad na 16."},"ar":{"q":"في Tennessee، ما أصغر عمر للرخصة المتوسطة المقيّدة؟","o":["16 سنة","15 سنة","17 سنة","18 سنة"],"h1":"هو سنة واحدة بعد عمر تصريح التعلّم.","h2":"يمكنك الحصول على الرخصة المتوسطة المقيّدة في عمر 16 سنة، بعد أن تحمل التصريح 180 يومًا، وتكمل ساعات التدريب، وتنجح في اختبار القيادة على الطريق.","p":"صحيح. تبدأ الرخصة المتوسطة المقيّدة في عمر 16 سنة."},"ref":{"doc":"TN","page":14}},{"id":"tn-008","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, who may sign the form that certifies a teen’s 50 hours of practice?","o":["Any friend who is 18","A school principal","A police officer","A parent, guardian or driving instructor"],"h1":"It is an adult who rode along and is responsible for the teen’s training.","h2":"A parent, legal guardian or driving instructor signs the 50-hour certification form to confirm the teen’s practice.","p":"Right. A parent, guardian or driving instructor signs the form."},"es":{"q":"En Tennessee, ¿quién puede firmar el formulario que certifica las 50 horas de práctica de un joven?","o":["Cualquier amigo de 18 años","El director de la escuela","Un policía","Su padre, madre, tutor o instructor de manejo"],"h1":"Es un adulto que lo acompañó y es responsable de su práctica.","h2":"Su padre, madre, tutor legal o instructor de manejo firma el formulario de certificación de 50 horas para confirmar la práctica del joven.","p":"Correcto. Firma su padre, madre, tutor o instructor de manejo."},"zh":{"q":"在 Tennessee，谁可以在证明青少年完成 50 小时练习的表格上签字？","o":["任何 18 岁的朋友","学校校长","警察","父母、监护人或驾驶教练"],"h1":"是一位陪同开车、并负责青少年训练的成年人。","h2":"父母、法定监护人或驾驶教练在 50 小时证明表上签字，确认青少年的练习。","p":"对。父母、监护人或驾驶教练在表格上签字。"},"vi":{"q":"Ở Tennessee, ai được ký vào mẫu đơn xác nhận 50 giờ tập lái của thiếu niên?","o":["Bất kỳ người bạn nào 18 tuổi","Hiệu trưởng trường học","Cảnh sát","Cha mẹ, người giám hộ hoặc thầy dạy lái"],"h1":"Đó là một người lớn đã đi cùng xe và chịu trách nhiệm việc tập lái của thiếu niên.","h2":"Cha mẹ, người giám hộ hợp pháp hoặc thầy dạy lái ký vào mẫu xác nhận 50 giờ để xác nhận việc tập lái của thiếu niên.","p":"Đúng. Cha mẹ, người giám hộ hoặc thầy dạy lái ký vào mẫu đơn."},"tl":{"q":"Sa Tennessee, sino ang puwedeng pumirma sa form na nagpapatunay sa 50 oras ng pagsasanay ng isang teen?","o":["Kahit sinong kaibigan na 18","Isang punong-guro ng paaralan","Isang pulis","Isang magulang, guardian o driving instructor"],"h1":"Isa itong adulto na sumama sa biyahe at responsable sa pagsasanay ng teen.","h2":"Ang magulang, legal na guardian o driving instructor ang pumipirma sa 50-hour certification form para kumpirmahin ang pagsasanay ng teen.","p":"Tama. Ang magulang, guardian o driving instructor ang pumipirma sa form."},"ar":{"q":"في Tennessee، من يجوز له أن يوقّع على النموذج الذي يثبت 50 ساعة تدريب للمراهق؟","o":["أي صديق عمره 18 سنة","مدير مدرسة","شرطي","أحد الوالدين أو الوصي أو مدرّب القيادة"],"h1":"هو شخص بالغ ركب مع المراهق وهو مسؤول عن تدريبه.","h2":"يوقّع أحد الوالدين أو الوصي القانوني أو مدرّب القيادة على نموذج الـ 50 ساعة لتأكيد تدريب المراهق.","p":"صحيح. يوقّع على النموذج أحد الوالدين أو الوصي أو مدرّب القيادة."},"ref":{"doc":"TN","page":14}},{"id":"tn-009","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, during which hours may an intermediate restricted driver not drive without a parent or an adult 21 or older?","o":["10 p.m. to 6 a.m.","Midnight to 5 a.m.","11 p.m. to 6 a.m.","9 p.m. to 5 a.m."],"h1":"It is one hour later than the learner permit limit.","h2":"An intermediate restricted driver may not drive from 11 p.m. to 6 a.m. unless a parent, guardian or other allowed adult is in the car, or another exception in the law applies.","p":"Right. Intermediate drivers stay off the road from 11 p.m. to 6 a.m."},"es":{"q":"En Tennessee, ¿en qué horario no puede manejar un conductor con licencia intermedia restringida sin su padre, madre o un adulto de 21 años o más?","o":["De 10 p.m. a 6 a.m.","De medianoche a 5 a.m.","De 11 p.m. a 6 a.m.","De 9 p.m. a 5 a.m."],"h1":"Es una hora más tarde que el límite del permiso de aprendiz.","h2":"Un conductor con licencia intermedia restringida no puede manejar de 11 p.m. a 6 a.m., salvo que vaya su padre, madre, tutor u otro adulto permitido, o que aplique otra excepción de la ley.","p":"Correcto. Los conductores intermedios no manejan de 11 p.m. a 6 a.m."},"zh":{"q":"在 Tennessee，持中级限制驾照的司机在没有父母或 21 岁或以上成年人陪同时，哪个时间段不可以开车？","o":["晚上 10 点到早上 6 点","午夜到早上 5 点","晚上 11 点到早上 6 点","晚上 9 点到早上 5 点"],"h1":"比学习驾照的限制晚一个小时。","h2":"持中级限制驾照的司机从晚上 11 点到早上 6 点不可以开车，除非父母、监护人或其他允许的成年人在车里，或符合法律中的其他例外。","p":"对。中级驾照司机从晚上 11 点到早上 6 点不上路。"},"vi":{"q":"Ở Tennessee, tài xế có bằng lái trung cấp có hạn chế không được lái xe trong khoảng giờ nào nếu không có cha mẹ hoặc người lớn từ 21 tuổi trở lên?","o":["10 giờ tối đến 6 giờ sáng","Nửa đêm đến 5 giờ sáng","11 giờ tối đến 6 giờ sáng","9 giờ tối đến 5 giờ sáng"],"h1":"Muộn hơn một giờ so với giới hạn của giấy phép tập lái.","h2":"Tài xế có bằng lái trung cấp có hạn chế không được lái xe từ 11 giờ tối đến 6 giờ sáng, trừ khi có cha mẹ, người giám hộ hoặc người lớn được phép khác trong xe, hoặc có trường hợp ngoại lệ khác theo luật.","p":"Đúng. Tài xế bằng trung cấp không ra đường từ 11 giờ tối đến 6 giờ sáng."},"tl":{"q":"Sa Tennessee, sa anong mga oras hindi puwedeng magmaneho ang may intermediate restricted license kung walang magulang o adultong 21 pataas?","o":["10 p.m. hanggang 6 a.m.","Hatinggabi hanggang 5 a.m.","11 p.m. hanggang 6 a.m.","9 p.m. hanggang 5 a.m."],"h1":"Isang oras itong mas huli kaysa sa limitasyon ng learner permit.","h2":"Hindi puwedeng magmaneho ang may intermediate restricted license mula 11 p.m. hanggang 6 a.m. maliban kung may magulang, guardian o ibang pinapayagang adulto sa sasakyan, o may ibang exception sa batas.","p":"Tama. Wala sa daan ang mga intermediate driver mula 11 p.m. hanggang 6 a.m."},"ar":{"q":"في Tennessee، في أي ساعات لا يجوز لسائق الرخصة المتوسطة المقيّدة أن يقود بدون أحد الوالدين أو شخص بالغ عمره 21 سنة أو أكثر؟","o":["من 10 مساءً إلى 6 صباحًا","من منتصف الليل إلى 5 صباحًا","من 11 مساءً إلى 6 صباحًا","من 9 مساءً إلى 5 صباحًا"],"h1":"هي بعد حدّ تصريح التعلّم بساعة واحدة.","h2":"لا يجوز لسائق الرخصة المتوسطة المقيّدة أن يقود من 11 مساءً إلى 6 صباحًا، إلا إذا كان في السيارة أحد الوالدين أو الوصي أو شخص بالغ آخر مسموح له، أو إذا انطبق استثناء آخر في القانون.","p":"صحيح. سائقو الرخصة المتوسطة لا يقودون من 11 مساءً إلى 6 صباحًا."},"ref":{"doc":"TN","page":19}},{"id":"tn-010","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, how many passengers may an intermediate restricted driver carry when no licensed adult 21 or older is in the car?","o":["One passenger","No passengers","Two passengers","Three passengers"],"h1":"More than zero, but fewer than two.","h2":"An intermediate restricted driver may carry only one passenger unless a licensed driver 21 or older is in the car, because more young passengers raise crash risk.","p":"Right. Only one passenger without an adult."},"es":{"q":"En Tennessee, ¿cuántos pasajeros puede llevar un conductor con licencia intermedia restringida si no va un adulto con licencia de 21 años o más?","o":["Un pasajero","Ningún pasajero","Dos pasajeros","Tres pasajeros"],"h1":"Más que cero, pero menos que dos.","h2":"Un conductor con licencia intermedia restringida solo puede llevar un pasajero, salvo que vaya un conductor con licencia de 21 años o más, porque más pasajeros jóvenes aumentan el riesgo de choque.","p":"Correcto. Solo un pasajero sin un adulto."},"zh":{"q":"在 Tennessee，车里没有 21 岁或以上的持照成年人时，持中级限制驾照的司机可以载几名乘客？","o":["一名乘客","不能载乘客","两名乘客","三名乘客"],"h1":"比零多，但比二少。","h2":"除非车里有一位 21 岁或以上的持照司机，持中级限制驾照的司机只能载一名乘客，因为年轻乘客越多，车祸风险越高。","p":"对。没有成年人时只能载一名乘客。"},"vi":{"q":"Ở Tennessee, khi trong xe không có người lớn có bằng lái từ 21 tuổi trở lên, tài xế có bằng lái trung cấp có hạn chế được chở bao nhiêu hành khách?","o":["Một hành khách","Không được chở hành khách","Hai hành khách","Ba hành khách"],"h1":"Nhiều hơn không, nhưng ít hơn hai.","h2":"Tài xế có bằng lái trung cấp có hạn chế chỉ được chở một hành khách, trừ khi có tài xế có bằng lái từ 21 tuổi trở lên trong xe, vì càng nhiều hành khách trẻ thì nguy cơ tai nạn càng cao.","p":"Đúng. Chỉ một hành khách khi không có người lớn."},"tl":{"q":"Sa Tennessee, ilang pasahero ang puwedeng isakay ng may intermediate restricted license kapag walang lisensyadong adulto na 21 pataas sa sasakyan?","o":["Isang pasahero","Walang pasahero","Dalawang pasahero","Tatlong pasahero"],"h1":"Higit sa zero, pero kulang sa dalawa.","h2":"Isang pasahero lang ang puwedeng isakay ng may intermediate restricted license maliban kung may lisensyadong driver na 21 pataas sa sasakyan, dahil mas maraming batang pasahero ay mas mataas na panganib ng banggaan.","p":"Tama. Isang pasahero lang kapag walang adulto."},"ar":{"q":"في Tennessee، كم راكبًا يجوز لسائق الرخصة المتوسطة المقيّدة أن ينقل عندما لا يكون في السيارة شخص بالغ مرخّص عمره 21 سنة أو أكثر؟","o":["راكب واحد","لا ركّاب","راكبان","ثلاثة ركّاب"],"h1":"أكثر من صفر، لكن أقل من اثنين.","h2":"يجوز لسائق الرخصة المتوسطة المقيّدة أن ينقل راكبًا واحدًا فقط، إلا إذا كان في السيارة سائق مرخّص عمره 21 سنة أو أكثر، لأن كثرة الركّاب الصغار ترفع خطر الحوادث.","p":"صحيح. راكب واحد فقط بدون شخص بالغ."},"ref":{"doc":"TN","page":19}},{"id":"tn-011","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, how long must a driver hold the intermediate restricted license before moving to the intermediate unrestricted license?","o":["Three months","Six months","Two years","One year"],"h1":"It is twelve months.","h2":"A driver must hold the intermediate restricted license for one year, without disqualifying violations, before moving up to the unrestricted license.","p":"Right. The restricted license is held for one year."},"es":{"q":"En Tennessee, ¿cuánto tiempo debe tener un conductor la licencia intermedia restringida antes de pasar a la licencia intermedia sin restricciones?","o":["Tres meses","Seis meses","Dos años","Un año"],"h1":"Son doce meses.","h2":"Un conductor debe tener la licencia intermedia restringida por un año, sin infracciones que lo descalifiquen, antes de pasar a la licencia sin restricciones.","p":"Correcto. La licencia restringida se tiene por un año."},"zh":{"q":"在 Tennessee，司机必须持有中级限制驾照多久，才能换成中级无限制驾照（intermediate unrestricted license）？","o":["三个月","六个月","两年","一年"],"h1":"是十二个月。","h2":"司机必须持有中级限制驾照一年，并且没有会取消资格的违规，才能升级到无限制驾照。","p":"对。限制驾照要持有一年。"},"vi":{"q":"Ở Tennessee, tài xế phải giữ bằng lái trung cấp có hạn chế bao lâu trước khi chuyển sang bằng lái trung cấp không hạn chế (intermediate unrestricted license)?","o":["Ba tháng","Sáu tháng","Hai năm","Một năm"],"h1":"Đó là mười hai tháng.","h2":"Tài xế phải giữ bằng lái trung cấp có hạn chế một năm, không có vi phạm làm mất tư cách, trước khi lên bằng lái không hạn chế.","p":"Đúng. Bằng lái có hạn chế được giữ một năm."},"tl":{"q":"Sa Tennessee, gaano katagal dapat hawak ng driver ang intermediate restricted license bago lumipat sa intermediate unrestricted license?","o":["Tatlong buwan","Anim na buwan","Dalawang taon","Isang taon"],"h1":"Labindalawang buwan ito.","h2":"Dapat hawak ng driver ang intermediate restricted license nang isang taon, nang walang paglabag na nakakadiskwalipika, bago umakyat sa unrestricted license.","p":"Tama. Hawak ang restricted license nang isang taon."},"ar":{"q":"في Tennessee، كم مدة يجب أن يحمل السائق الرخصة المتوسطة المقيّدة قبل الانتقال إلى الرخصة المتوسطة غير المقيّدة (intermediate unrestricted license)؟","o":["ثلاثة أشهر","ستة أشهر","سنتان","سنة واحدة"],"h1":"هي اثنا عشر شهرًا.","h2":"يجب أن يحمل السائق الرخصة المتوسطة المقيّدة سنة واحدة، بدون مخالفات تُسقط الأهلية، قبل الانتقال إلى الرخصة غير المقيّدة.","p":"صحيح. تُحمل الرخصة المقيّدة سنة واحدة."},"ref":{"doc":"TN","page":14}},{"id":"tn-012","scope":"TN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Tennessee, what is the rule on phones for drivers with a learner permit or an intermediate license?","o":["They may text only at red lights","They may not use a cell phone while driving","They may use a phone if it is on speaker","They may call only family members"],"h1":"The rule for new drivers is stricter than for adults.","h2":"Drivers with a learner permit or an intermediate license may not use a cell phone while driving, so all their attention stays on the road.","p":"Right. New Tennessee drivers may not use a phone while driving."},"es":{"q":"En Tennessee, ¿cuál es la regla sobre teléfonos para conductores con permiso de aprendiz o licencia intermedia?","o":["Pueden escribir textos solo en luces rojas","No pueden usar el celular mientras manejan","Pueden usar el teléfono si está en altavoz","Pueden llamar solo a familiares"],"h1":"La regla para conductores nuevos es más estricta que para adultos.","h2":"Los conductores con permiso de aprendiz o licencia intermedia no pueden usar el celular mientras manejan, para que toda su atención esté en el camino.","p":"Correcto. Los conductores nuevos en Tennessee no pueden usar el teléfono al manejar."},"zh":{"q":"在 Tennessee，对持学习驾照或中级驾照的司机，手机的规定是什么？","o":["只能在红灯时发短信","开车时不可以使用手机","如果开免提就可以用手机","只能打电话给家人"],"h1":"对新司机的规定比对成年人更严格。","h2":"持学习驾照或中级驾照的司机开车时不可以使用手机，这样所有注意力都放在道路上。","p":"对。Tennessee 的新司机开车时不可以用手机。"},"vi":{"q":"Ở Tennessee, quy định về điện thoại cho tài xế có giấy phép tập lái hoặc bằng lái trung cấp là gì?","o":["Họ chỉ được nhắn tin khi đèn đỏ","Họ không được dùng điện thoại di động khi lái xe","Họ được dùng điện thoại nếu bật loa ngoài","Họ chỉ được gọi cho người trong gia đình"],"h1":"Quy định cho tài xế mới nghiêm hơn so với người lớn.","h2":"Tài xế có giấy phép tập lái hoặc bằng lái trung cấp không được dùng điện thoại di động khi lái xe, để toàn bộ sự chú ý dành cho con đường.","p":"Đúng. Tài xế mới ở Tennessee không được dùng điện thoại khi lái xe."},"tl":{"q":"Sa Tennessee, ano ang patakaran sa telepono para sa mga driver na may learner permit o intermediate license?","o":["Puwede silang mag-text sa pulang ilaw lang","Hindi sila puwedeng gumamit ng cell phone habang nagmamaneho","Puwede silang gumamit ng telepono kung naka-speaker","Puwede lang silang tumawag sa pamilya"],"h1":"Mas mahigpit ang patakaran para sa mga bagong driver kaysa sa mga adulto.","h2":"Hindi puwedeng gumamit ng cell phone habang nagmamaneho ang mga driver na may learner permit o intermediate license, para nasa daan ang buong atensyon nila.","p":"Tama. Hindi puwedeng gumamit ng telepono habang nagmamaneho ang mga bagong driver sa Tennessee."},"ar":{"q":"في Tennessee، ما قاعدة الهاتف للسائقين الذين يحملون تصريح التعلّم أو الرخصة المتوسطة؟","o":["يجوز لهم إرسال الرسائل عند الإشارة الحمراء فقط","لا يجوز لهم استخدام الهاتف المحمول أثناء القيادة","يجوز لهم استخدام الهاتف إذا كان على مكبّر الصوت","يجوز لهم الاتصال بأفراد العائلة فقط"],"h1":"القاعدة للسائقين الجدد أشدّ منها للبالغين.","h2":"لا يجوز للسائقين الذين يحملون تصريح التعلّم أو الرخصة المتوسطة استخدام الهاتف المحمول أثناء القيادة، حتى يبقى كل انتباههم على الطريق.","p":"صحيح. السائقون الجدد في Tennessee لا يستخدمون الهاتف أثناء القيادة."},"ref":{"doc":"TN","page":18}},{"id":"tn-013","scope":"TN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Tennessee, what does the hands-free law forbid for all drivers?","o":["Using a phone mounted on the dashboard","Making a call with an earpiece","Holding a phone with any part of the body","Calling 911 in an emergency"],"h1":"Your hands, and even your shoulder, must stay free of the phone.","h2":"Tennessee’s hands-free law forbids every driver from holding a phone with any part of the body while driving.","p":"Right. Drivers may not hold a phone with any part of the body."},"es":{"q":"En Tennessee, ¿qué prohíbe la ley de manos libres a todos los conductores?","o":["Usar un teléfono montado en el tablero","Hacer una llamada con un audífono","Sostener el teléfono con cualquier parte del cuerpo","Llamar al 911 en una emergencia"],"h1":"Sus manos, y hasta su hombro, deben quedar libres del teléfono.","h2":"La ley de manos libres de Tennessee prohíbe a todo conductor sostener un teléfono con cualquier parte del cuerpo mientras maneja.","p":"Correcto. No puede sostener el teléfono con ninguna parte del cuerpo."},"zh":{"q":"在 Tennessee，免手持法（hands-free law）禁止所有司机做什么？","o":["使用固定在仪表板上的手机","用耳机打电话","用身体的任何部位拿着手机","紧急情况时拨打 911"],"h1":"你的手，甚至你的肩膀，都不能拿着手机。","h2":"Tennessee 的免手持法禁止每一位司机在开车时用身体的任何部位拿着手机。","p":"对。司机不可以用身体的任何部位拿着手机。"},"vi":{"q":"Ở Tennessee, luật rảnh tay (hands-free law) cấm tất cả tài xế làm gì?","o":["Dùng điện thoại gắn trên bảng điều khiển","Gọi điện bằng tai nghe","Cầm điện thoại bằng bất kỳ bộ phận nào của cơ thể","Gọi 911 khi khẩn cấp"],"h1":"Tay của bạn, và cả vai của bạn, không được giữ điện thoại.","h2":"Luật rảnh tay của Tennessee cấm mọi tài xế cầm điện thoại bằng bất kỳ bộ phận nào của cơ thể khi lái xe.","p":"Đúng. Tài xế không được cầm điện thoại bằng bất kỳ bộ phận nào của cơ thể."},"tl":{"q":"Sa Tennessee, ano ang ipinagbabawal ng hands-free law sa lahat ng driver?","o":["Paggamit ng teleponong nakakabit sa dashboard","Pagtawag gamit ang earpiece","Paghawak ng telepono gamit ang anumang bahagi ng katawan","Pagtawag sa 911 sa emergency"],"h1":"Ang mga kamay mo, at pati ang balikat mo, ay dapat walang hawak na telepono.","h2":"Ipinagbabawal ng hands-free law ng Tennessee sa bawat driver ang paghawak ng telepono gamit ang anumang bahagi ng katawan habang nagmamaneho.","p":"Tama. Hindi puwedeng humawak ng telepono ang driver gamit ang anumang bahagi ng katawan."},"ar":{"q":"في Tennessee، ماذا يمنع قانون عدم استخدام اليدين (hands-free law) على كل السائقين؟","o":["استخدام هاتف مثبّت على لوحة القيادة","إجراء مكالمة بسمّاعة أذن","حمل الهاتف بأي جزء من الجسم","الاتصال بالرقم 911 في حالة طوارئ"],"h1":"يداك، وحتى كتفك، يجب أن تبقى بعيدة عن الهاتف.","h2":"يمنع قانون عدم استخدام اليدين في Tennessee كل سائق من حمل الهاتف بأي جزء من الجسم أثناء القيادة.","p":"صحيح. لا يجوز للسائق حمل الهاتف بأي جزء من الجسم."},"ref":{"doc":"TN","page":30}},{"id":"tn-014","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, how many questions are on the knowledge test for a learner permit?","o":["30 questions","20 questions","25 questions","50 questions"],"h1":"It is a round number between 25 and 50.","h2":"The Tennessee knowledge test has 30 questions about road rules and signs.","p":"Right. The Tennessee test has 30 questions."},"es":{"q":"En Tennessee, ¿cuántas preguntas tiene el examen de conocimientos para el permiso de aprendiz?","o":["30 preguntas","20 preguntas","25 preguntas","50 preguntas"],"h1":"Es un número redondo entre 25 y 50.","h2":"El examen de conocimientos de Tennessee tiene 30 preguntas sobre reglas de tránsito y señales.","p":"Correcto. El examen de Tennessee tiene 30 preguntas."},"zh":{"q":"在 Tennessee，学习驾照的笔试有多少道题？","o":["30 道题","20 道题","25 道题","50 道题"],"h1":"是 25 和 50 之间的一个整数。","h2":"Tennessee 的笔试有 30 道关于交通规则和标志的题目。","p":"对。Tennessee 的考试有 30 道题。"},"vi":{"q":"Ở Tennessee, bài thi kiến thức để lấy giấy phép tập lái có bao nhiêu câu hỏi?","o":["30 câu hỏi","20 câu hỏi","25 câu hỏi","50 câu hỏi"],"h1":"Đó là một số tròn giữa 25 và 50.","h2":"Bài thi kiến thức của Tennessee có 30 câu hỏi về luật đi đường và biển báo.","p":"Đúng. Bài thi của Tennessee có 30 câu hỏi."},"tl":{"q":"Sa Tennessee, ilang tanong ang nasa knowledge test para sa learner permit?","o":["30 tanong","20 tanong","25 tanong","50 tanong"],"h1":"Isang buong numero ito sa pagitan ng 25 at 50.","h2":"May 30 tanong ang knowledge test ng Tennessee tungkol sa mga patakaran sa daan at mga karatula.","p":"Tama. May 30 tanong ang test ng Tennessee."},"ar":{"q":"في Tennessee، كم سؤالًا في الاختبار النظري لتصريح التعلّم؟","o":["30 سؤالًا","20 سؤالًا","25 سؤالًا","50 سؤالًا"],"h1":"هو عدد كامل بين 25 و50.","h2":"في الاختبار النظري في Tennessee يوجد 30 سؤالًا عن قواعد الطريق والإشارات.","p":"صحيح. في اختبار Tennessee يوجد 30 سؤالًا."},"ref":{"doc":"TN","page":null}},{"id":"tn-015","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, what score do you need to pass the knowledge test?","o":["At least 60 percent","At least 70 percent","At least 90 percent","At least 80 percent"],"h1":"You can miss only one question in five.","h2":"You need at least 80 percent to pass, which means 24 correct answers out of 30.","p":"Right. You need 80 percent, or 24 of 30."},"es":{"q":"En Tennessee, ¿qué puntaje necesita para aprobar el examen de conocimientos?","o":["Por lo menos 60 por ciento","Por lo menos 70 por ciento","Por lo menos 90 por ciento","Por lo menos 80 por ciento"],"h1":"Solo puede fallar una pregunta de cada cinco.","h2":"Necesita por lo menos 80 por ciento para aprobar, es decir, 24 respuestas correctas de 30.","p":"Correcto. Necesita 80 por ciento, o 24 de 30."},"zh":{"q":"在 Tennessee，笔试需要多少分才能通过？","o":["至少 60%","至少 70%","至少 90%","至少 80%"],"h1":"每五道题你只能错一道。","h2":"你需要至少 80% 才能通过，也就是 30 道题中答对 24 道。","p":"对。你需要 80%，也就是 30 道答对 24 道。"},"vi":{"q":"Ở Tennessee, bạn cần bao nhiêu điểm để đậu bài thi kiến thức?","o":["Ít nhất 60%","Ít nhất 70%","Ít nhất 90%","Ít nhất 80%"],"h1":"Bạn chỉ được sai một câu trong năm câu.","h2":"Bạn cần ít nhất 80% để đậu, nghĩa là trả lời đúng 24 trên 30 câu.","p":"Đúng. Bạn cần 80%, tức là 24 trên 30 câu."},"tl":{"q":"Sa Tennessee, anong score ang kailangan mo para pumasa sa knowledge test?","o":["Hindi bababa sa 60%","Hindi bababa sa 70%","Hindi bababa sa 90%","Hindi bababa sa 80%"],"h1":"Isang tanong lang sa bawat lima ang puwede mong mamali.","h2":"Kailangan mo ng hindi bababa sa 80% para pumasa, ibig sabihin 24 na tamang sagot sa 30.","p":"Tama. Kailangan mo ng 80%, o 24 sa 30."},"ar":{"q":"في Tennessee، ما الدرجة التي تحتاجها للنجاح في الاختبار النظري؟","o":["60% على الأقل","70% على الأقل","90% على الأقل","80% على الأقل"],"h1":"يمكنك أن تخطئ في سؤال واحد فقط من كل خمسة.","h2":"تحتاج إلى 80% على الأقل للنجاح، أي 24 إجابة صحيحة من 30.","p":"صحيح. تحتاج إلى 80%، أي 24 من 30."},"ref":{"doc":"TN","page":null}},{"id":"tn-016","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, in which languages can you take the online knowledge test?","o":["English only","English and Spanish","Spanish only","Any language you choose"],"h1":"One of them is the language of this sentence.","h2":"The online knowledge test in Tennessee is offered in English and in Spanish.","p":"Right. The online test is in English and Spanish."},"es":{"q":"En Tennessee, ¿en qué idiomas puede hacer el examen de conocimientos en línea?","o":["Solo en inglés","En inglés y en español","Solo en español","En cualquier idioma que elija"],"h1":"Uno de ellos es el idioma de esta oración.","h2":"El examen de conocimientos en línea de Tennessee se ofrece en inglés y en español.","p":"Correcto. El examen en línea está en inglés y en español."},"zh":{"q":"在 Tennessee，网上笔试可以用哪些语言参加？","o":["只有英语","英语和西班牙语","只有西班牙语","你选择的任何语言"],"h1":"其中一种是这句话原文的语言（英语）。","h2":"Tennessee 的网上笔试提供英语和西班牙语两种语言。","p":"对。网上考试有英语和西班牙语。"},"vi":{"q":"Ở Tennessee, bạn có thể làm bài thi kiến thức trực tuyến bằng những ngôn ngữ nào?","o":["Chỉ tiếng Anh","Tiếng Anh và tiếng Tây Ban Nha","Chỉ tiếng Tây Ban Nha","Bất kỳ ngôn ngữ nào bạn chọn"],"h1":"Một trong số đó là ngôn ngữ gốc của câu này (tiếng Anh).","h2":"Bài thi kiến thức trực tuyến ở Tennessee có bằng tiếng Anh và tiếng Tây Ban Nha.","p":"Đúng. Bài thi trực tuyến có tiếng Anh và tiếng Tây Ban Nha."},"tl":{"q":"Sa Tennessee, sa anong mga wika puwede mong kunin ang online knowledge test?","o":["Ingles lang","Ingles at Espanyol","Espanyol lang","Kahit anong wikang piliin mo"],"h1":"Isa sa mga ito ang orihinal na wika ng pangungusap na ito (Ingles).","h2":"Ang online knowledge test sa Tennessee ay nasa Ingles at Espanyol.","p":"Tama. Nasa Ingles at Espanyol ang online test."},"ar":{"q":"في Tennessee، بأي لغات يمكنك أن تأخذ الاختبار النظري عبر الإنترنت؟","o":["الإنجليزية فقط","الإنجليزية والإسبانية","الإسبانية فقط","أي لغة تختارها"],"h1":"إحداهما هي اللغة الأصلية لهذه الجملة (الإنجليزية).","h2":"يُقدَّم الاختبار النظري عبر الإنترنت في Tennessee باللغة الإنجليزية واللغة الإسبانية.","p":"صحيح. الاختبار عبر الإنترنت بالإنجليزية والإسبانية."},"ref":{"doc":"TN","page":null}},{"id":"tn-017","scope":"TN","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Tennessee, you approach a stopped emergency vehicle with flashing lights. What does the move-over law require?","o":["Honk to warn the crew","Stop completely in your lane","Move to a lane farther away if safe, or else slow down","Pass at the same speed in the next lane"],"h1":"Give the crew more room, or more time.","h2":"You must move into a lane away from the stopped vehicle when it is safe; if you cannot, you must slow down as you pass.","p":"Right. Move over if it is safe, or slow down."},"es":{"q":"En Tennessee, usted se acerca a un vehículo de emergencia detenido con luces intermitentes. ¿Qué exige la ley de cambio de carril?","o":["Tocar la bocina para avisar al equipo","Detenerse por completo en su carril","Pasarse a un carril más lejano si es seguro, o si no, bajar la velocidad","Pasar a la misma velocidad en el carril de al lado"],"h1":"Déle al equipo más espacio, o más tiempo.","h2":"Usted debe pasarse a un carril alejado del vehículo detenido cuando sea seguro; si no puede, debe bajar la velocidad al pasar.","p":"Correcto. Cámbiese de carril si es seguro, o baje la velocidad."},"zh":{"q":"在 Tennessee，你接近一辆停着、闪着灯的紧急车辆。让道法（move-over law）要求你做什么？","o":["按喇叭提醒工作人员","在你的车道上完全停下","如果安全，换到离它更远的车道；否则就减速","在旁边车道用同样的速度开过去"],"h1":"给工作人员更多空间，或者更多时间。","h2":"在安全时，你必须换到远离那辆停着的车的车道；如果不能换道，经过时必须减速。","p":"对。安全就换道，否则就减速。"},"vi":{"q":"Ở Tennessee, bạn đến gần một xe cấp cứu đang dừng và nháy đèn. Luật nhường làn (move-over law) yêu cầu gì?","o":["Bấm còi để báo cho nhân viên","Dừng hẳn trong làn của bạn","Chuyển sang làn xa hơn nếu an toàn, nếu không thì chạy chậm lại","Chạy qua với cùng tốc độ ở làn bên cạnh"],"h1":"Cho nhân viên thêm chỗ, hoặc thêm thời gian.","h2":"Bạn phải chuyển sang làn xa chiếc xe đang dừng khi an toàn; nếu không thể, bạn phải chạy chậm lại khi đi qua.","p":"Đúng. Chuyển làn nếu an toàn, nếu không thì chạy chậm lại."},"tl":{"q":"Sa Tennessee, papalapit ka sa nakahintong emergency vehicle na may kumikislap na ilaw. Ano ang hinihingi ng move-over law?","o":["Bumusina para balaan ang mga tauhan","Huminto nang tuluyan sa iyong lane","Lumipat sa lane na mas malayo kung ligtas, o kung hindi ay bumagal","Lumampas sa parehong bilis sa katabing lane"],"h1":"Bigyan ang mga tauhan ng mas maraming espasyo, o mas maraming oras.","h2":"Dapat kang lumipat sa lane na malayo sa nakahintong sasakyan kapag ligtas; kung hindi mo kaya, dapat kang bumagal habang dumadaan.","p":"Tama. Lumipat ng lane kung ligtas, o bumagal."},"ar":{"q":"في Tennessee، تقترب من مركبة طوارئ متوقفة وأضواؤها تومض. ماذا يطلب قانون الابتعاد (move-over law)؟","o":["استخدم البوق لتنبيه الطاقم","توقّف تمامًا في مسارك","انتقل إلى مسار أبعد إذا كان ذلك آمنًا، وإلا فخفّف السرعة","مرّ بنفس السرعة في المسار المجاور"],"h1":"أعطِ الطاقم مساحة أكبر، أو وقتًا أكثر.","h2":"يجب أن تنتقل إلى مسار بعيد عن المركبة المتوقفة عندما يكون ذلك آمنًا؛ وإذا لم تستطع، يجب أن تخفّف السرعة وأنت تمرّ.","p":"صحيح. ابتعد إذا كان ذلك آمنًا، أو خفّف السرعة."},"ref":{"doc":"TN","page":55}},{"id":"tn-018","scope":"TN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Tennessee, besides emergency vehicles, which of these must you move over or slow down for?","o":["Any stopped vehicle with its flashing lights on","Only police cars","Only tow trucks","Only vehicles parked in a driveway"],"h1":"Since 2017 the law covers more than work vehicles.","h2":"Tennessee’s move-over law covers tow trucks, road crews, utility and garbage trucks, and also any stopped vehicle with its flashing lights on.","p":"Right. Move over or slow down for any stopped vehicle with flashing lights."},"es":{"q":"En Tennessee, además de los vehículos de emergencia, ¿por cuál de estos debe cambiarse de carril o bajar la velocidad?","o":["Cualquier vehículo detenido con sus luces intermitentes encendidas","Solo carros de policía","Solo grúas","Solo vehículos estacionados en una entrada de casa"],"h1":"Desde 2017 la ley cubre más que vehículos de trabajo.","h2":"La ley de Tennessee cubre grúas, cuadrillas de carreteras, camiones de servicios públicos y de basura, y también cualquier vehículo detenido con luces intermitentes.","p":"Correcto. Cámbiese de carril o baje la velocidad por cualquier vehículo detenido con luces intermitentes."},"zh":{"q":"在 Tennessee，除了紧急车辆，你还必须为下面哪一种车换道或减速？","o":["任何停着、开着闪灯的车辆","只有警车","只有拖车","只有停在车道（driveway）上的车辆"],"h1":"从 2017 年起，这条法律不只包括工作车辆。","h2":"Tennessee 的让道法包括拖车、道路工作人员、公用事业车和垃圾车，也包括任何停着、开着闪灯的车辆。","p":"对。遇到任何停着、开着闪灯的车辆，都要换道或减速。"},"vi":{"q":"Ở Tennessee, ngoài xe cấp cứu, bạn còn phải chuyển làn hoặc chạy chậm lại cho loại xe nào dưới đây?","o":["Bất kỳ xe nào đang dừng và bật đèn nháy","Chỉ xe cảnh sát","Chỉ xe kéo","Chỉ xe đậu trong lối vào nhà (driveway)"],"h1":"Từ năm 2017, luật này áp dụng cho nhiều hơn xe công vụ.","h2":"Luật nhường làn của Tennessee áp dụng cho xe kéo, đội sửa đường, xe điện nước và xe rác, và cả bất kỳ xe nào đang dừng và bật đèn nháy.","p":"Đúng. Chuyển làn hoặc chạy chậm lại cho bất kỳ xe nào đang dừng và bật đèn nháy."},"tl":{"q":"Sa Tennessee, bukod sa mga emergency vehicle, alin dito ang dapat mong lipatan ng lane o bagalan?","o":["Anumang nakahintong sasakyan na nakabukas ang kumikislap na ilaw","Mga sasakyan ng pulis lang","Mga tow truck lang","Mga sasakyang nakaparada sa driveway lang"],"h1":"Mula 2017, sakop ng batas ang higit pa sa mga sasakyang pantrabaho.","h2":"Sakop ng move-over law ng Tennessee ang mga tow truck, road crew, utility truck at garbage truck, at pati ang anumang nakahintong sasakyan na nakabukas ang kumikislap na ilaw.","p":"Tama. Lumipat ng lane o bumagal para sa anumang nakahintong sasakyan na may kumikislap na ilaw."},"ar":{"q":"في Tennessee، بالإضافة إلى مركبات الطوارئ، لأيّ مما يلي يجب أن تبتعد أو تخفّف السرعة؟","o":["أي مركبة متوقفة أضواؤها الوامضة مشغّلة","سيارات الشرطة فقط","شاحنات السحب فقط","المركبات المتوقفة في ممر المنزل (driveway) فقط"],"h1":"منذ 2017 يشمل القانون أكثر من مركبات العمل.","h2":"يشمل قانون الابتعاد في Tennessee شاحنات السحب، وطواقم الطرق، وشاحنات المرافق والقمامة، وأيضًا أي مركبة متوقفة أضواؤها الوامضة مشغّلة.","p":"صحيح. ابتعد أو خفّف السرعة لأي مركبة متوقفة أضواؤها تومض."},"ref":{"doc":"TN","page":72}},{"id":"tn-019","scope":"TN","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Tennessee, a school bus stops with flashing red lights on the other side of a highway divided by a median. What should you do?","o":["Stop until the bus moves","Speed up to pass quickly","Stop only if children are outside","Keep going with caution; you do not need to stop"],"h1":"The median separates you from the children.","h2":"On a highway divided by a median or barrier, traffic going the other way does not need to stop for the bus but must drive with care; traffic behind the bus must stop.","p":"Right. On the far side of a divided highway, go on with caution."},"es":{"q":"En Tennessee, un autobús escolar se detiene con luces rojas intermitentes en el otro lado de una carretera dividida por un camellón. ¿Qué debe hacer?","o":["Detenerse hasta que el autobús avance","Acelerar para pasar rápido","Detenerse solo si hay niños afuera","Seguir con precaución; no necesita detenerse"],"h1":"El camellón lo separa de los niños.","h2":"En una carretera dividida por un camellón o barrera, el tráfico que va en sentido contrario no necesita detenerse por el autobús, pero debe manejar con cuidado; el tráfico detrás del autobús sí debe detenerse.","p":"Correcto. Del otro lado de una carretera dividida, siga con precaución."},"zh":{"q":"在 Tennessee，一辆校车在有中间隔离带的公路另一边停下，闪着红灯。你应该怎么做？","o":["停下，直到校车开走","加速快速开过去","只有孩子在车外时才停","小心继续开；你不需要停车"],"h1":"中间隔离带把你和孩子们分开了。","h2":"在有中间隔离带或护栏分开的公路上，对向的车不需要为校车停下，但必须小心开车；校车后面的车必须停下。","p":"对。在分隔公路的另一边，小心继续开。"},"vi":{"q":"Ở Tennessee, một xe buýt trường học dừng lại và nháy đèn đỏ ở phía bên kia của xa lộ có dải phân cách giữa. Bạn nên làm gì?","o":["Dừng lại cho đến khi xe buýt chạy","Tăng tốc để vượt qua nhanh","Chỉ dừng nếu trẻ em đang ở ngoài","Tiếp tục đi một cách cẩn thận; bạn không cần dừng"],"h1":"Dải phân cách ngăn bạn với các em nhỏ.","h2":"Trên xa lộ có dải phân cách hoặc rào chắn ở giữa, xe đi chiều ngược lại không cần dừng cho xe buýt nhưng phải lái cẩn thận; xe phía sau xe buýt phải dừng lại.","p":"Đúng. Ở phía bên kia của xa lộ có phân cách, tiếp tục đi một cách cẩn thận."},"tl":{"q":"Sa Tennessee, huminto ang isang school bus na may kumikislap na pulang ilaw sa kabilang panig ng highway na hinahati ng median. Ano ang dapat mong gawin?","o":["Huminto hanggang umandar ang bus","Bumilis para mabilis na makalampas","Huminto lang kung may mga bata sa labas","Magpatuloy nang maingat; hindi mo kailangang huminto"],"h1":"Ang median ang naghihiwalay sa iyo at sa mga bata.","h2":"Sa highway na hinahati ng median o harang, hindi kailangang huminto para sa bus ang mga sasakyang papunta sa kabilang direksyon pero dapat magmaneho nang maingat; ang mga sasakyan sa likod ng bus ay dapat huminto.","p":"Tama. Sa kabilang panig ng hinating highway, magpatuloy nang maingat."},"ar":{"q":"في Tennessee، توقفت حافلة مدرسية وأضواؤها الحمراء تومض على الجانب الآخر من طريق سريع يفصله حاجز وسطي (median). ماذا يجب أن تفعل؟","o":["توقّف حتى تتحرك الحافلة","زِد السرعة لتمرّ بسرعة","توقّف فقط إذا كان الأطفال في الخارج","استمر بحذر؛ لا تحتاج إلى التوقف"],"h1":"الحاجز الوسطي يفصلك عن الأطفال.","h2":"على طريق سريع يفصله حاجز وسطي أو حاجز، لا تحتاج حركة المرور في الاتجاه المعاكس إلى التوقف للحافلة لكن يجب أن تقود بحذر؛ أما المركبات خلف الحافلة فيجب أن تتوقف.","p":"صحيح. على الجانب الآخر من طريق مقسوم، استمر بحذر."},"ref":{"doc":"TN","page":51}},{"id":"tn-020","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, a driver 21 or older is legally drunk at what blood alcohol level?","o":["0.05 percent or more","0.08 percent or more","0.10 percent or more","0.12 percent or more"],"h1":"It is less than one tenth of one percent.","h2":"A driver 21 or older breaks Tennessee’s drunk driving law at a blood alcohol level of 0.08 percent or more.","p":"Right. The adult limit is 0.08 percent."},"es":{"q":"En Tennessee, ¿con qué nivel de alcohol en la sangre se considera legalmente ebrio a un conductor de 21 años o más?","o":["0.05 por ciento o más","0.08 por ciento o más","0.10 por ciento o más","0.12 por ciento o más"],"h1":"Es menos de una décima de uno por ciento.","h2":"Un conductor de 21 años o más viola la ley de Tennessee sobre manejar ebrio con 0.08 por ciento o más de alcohol en la sangre.","p":"Correcto. El límite para adultos es 0.08 por ciento."},"zh":{"q":"在 Tennessee，21 岁或以上的司机，血液酒精浓度达到多少就算法律上的醉酒？","o":["0.05% 或以上","0.08% 或以上","0.10% 或以上","0.12% 或以上"],"h1":"比百分之一的十分之一还少。","h2":"21 岁或以上的司机，血液酒精浓度达到 0.08% 或以上，就违反了 Tennessee 的醉酒驾驶法。","p":"对。成年人的上限是 0.08%。"},"vi":{"q":"Ở Tennessee, tài xế từ 21 tuổi trở lên bị coi là say rượu theo luật ở mức nồng độ cồn trong máu nào?","o":["0.05% trở lên","0.08% trở lên","0.10% trở lên","0.12% trở lên"],"h1":"Ít hơn một phần mười của một phần trăm.","h2":"Tài xế từ 21 tuổi trở lên vi phạm luật lái xe say rượu của Tennessee khi nồng độ cồn trong máu là 0.08% trở lên.","p":"Đúng. Giới hạn cho người lớn là 0.08%."},"tl":{"q":"Sa Tennessee, ang driver na 21 pataas ay legal na lasing sa anong blood alcohol level?","o":["0.05% o higit pa","0.08% o higit pa","0.10% o higit pa","0.12% o higit pa"],"h1":"Mas mababa ito sa isang ikasampu ng isang porsyento.","h2":"Lumalabag sa batas ng Tennessee laban sa lasing na pagmamaneho ang driver na 21 pataas kapag ang blood alcohol level ay 0.08% o higit pa.","p":"Tama. Ang limitasyon para sa adulto ay 0.08%."},"ar":{"q":"في Tennessee، يُعدّ السائق الذي عمره 21 سنة أو أكثر سكرانًا قانونيًا عند أي نسبة كحول في الدم؟","o":["0.05% أو أكثر","0.08% أو أكثر","0.10% أو أكثر","0.12% أو أكثر"],"h1":"هي أقل من عُشر واحد في المئة.","h2":"السائق الذي عمره 21 سنة أو أكثر يخالف قانون القيادة تحت تأثير الكحول في Tennessee عند نسبة كحول في الدم 0.08% أو أكثر.","p":"صحيح. حدّ البالغين هو 0.08%."},"ref":{"doc":"TN","page":81}},{"id":"tn-021","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, a driver under 21 breaks the law at what blood alcohol level?","o":["0.02 percent or more","0.05 percent or more","0.08 percent or more","0.10 percent or more"],"h1":"It is a very small amount, far below the adult limit.","h2":"Tennessee’s underage law makes it illegal for a driver under 21 to drive with a blood alcohol level of 0.02 percent or more.","p":"Right. The limit under 21 is 0.02 percent."},"es":{"q":"En Tennessee, ¿con qué nivel de alcohol en la sangre viola la ley un conductor menor de 21 años?","o":["0.02 por ciento o más","0.05 por ciento o más","0.08 por ciento o más","0.10 por ciento o más"],"h1":"Es una cantidad muy pequeña, muy por debajo del límite de adultos.","h2":"La ley de Tennessee para menores prohíbe manejar a un conductor menor de 21 años con 0.02 por ciento o más de alcohol en la sangre.","p":"Correcto. El límite para menores de 21 es 0.02 por ciento."},"zh":{"q":"在 Tennessee，21 岁以下的司机，血液酒精浓度达到多少就违法？","o":["0.02% 或以上","0.05% 或以上","0.08% 或以上","0.10% 或以上"],"h1":"是很少的量，远低于成年人的上限。","h2":"Tennessee 的未成年人法律规定，21 岁以下的司机在血液酒精浓度 0.02% 或以上时开车是违法的。","p":"对。21 岁以下的上限是 0.02%。"},"vi":{"q":"Ở Tennessee, tài xế dưới 21 tuổi phạm luật ở mức nồng độ cồn trong máu nào?","o":["0.02% trở lên","0.05% trở lên","0.08% trở lên","0.10% trở lên"],"h1":"Đó là một lượng rất nhỏ, thấp hơn nhiều so với giới hạn của người lớn.","h2":"Luật dành cho người dưới tuổi của Tennessee cấm tài xế dưới 21 tuổi lái xe khi nồng độ cồn trong máu là 0.02% trở lên.","p":"Đúng. Giới hạn dưới 21 tuổi là 0.02%."},"tl":{"q":"Sa Tennessee, ang driver na wala pang 21 ay lumalabag sa batas sa anong blood alcohol level?","o":["0.02% o higit pa","0.05% o higit pa","0.08% o higit pa","0.10% o higit pa"],"h1":"Napakaliit na halaga ito, malayo sa ilalim ng limitasyon ng adulto.","h2":"Ayon sa batas ng Tennessee para sa mga menor de edad, bawal magmaneho ang driver na wala pang 21 kapag ang blood alcohol level ay 0.02% o higit pa.","p":"Tama. Ang limitasyon para sa wala pang 21 ay 0.02%."},"ar":{"q":"في Tennessee، السائق الذي عمره أقل من 21 سنة يخالف القانون عند أي نسبة كحول في الدم؟","o":["0.02% أو أكثر","0.05% أو أكثر","0.08% أو أكثر","0.10% أو أكثر"],"h1":"هي كمية صغيرة جدًا، أقل بكثير من حدّ البالغين.","h2":"قانون القاصرين في Tennessee يجعل من غير القانوني أن يقود سائق عمره أقل من 21 سنة بنسبة كحول في الدم 0.02% أو أكثر.","p":"صحيح. الحدّ لمن هم أقل من 21 سنة هو 0.02%."},"ref":{"doc":"TN","page":83}},{"id":"tn-022","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, what is the minimum liability insurance a driver must carry?","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $25,000","$100,000 / $300,000 / $50,000"],"h1":"The first and last numbers are the same.","h2":"Tennessee requires at least $25,000 for injury to one person, $50,000 for injuries in one crash, and $25,000 for property damage.","p":"Right. Tennessee minimums are 25/50/25."},"es":{"q":"En Tennessee, ¿cuál es el seguro mínimo de responsabilidad que debe tener un conductor?","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $25,000","$100,000 / $300,000 / $50,000"],"h1":"El primer y el último número son iguales.","h2":"Tennessee exige por lo menos $25,000 por lesiones a una persona, $50,000 por lesiones en un choque y $25,000 por daños a la propiedad.","p":"Correcto. Los mínimos en Tennessee son 25/50/25."},"zh":{"q":"在 Tennessee，司机必须购买的最低责任保险是多少？","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $25,000","$100,000 / $300,000 / $50,000"],"h1":"第一个和最后一个数字相同。","h2":"Tennessee 要求至少：一人受伤 $25,000，一次车祸中的伤害 $50,000，财产损失 $25,000。","p":"对。Tennessee 的最低标准是 25/50/25。"},"vi":{"q":"Ở Tennessee, bảo hiểm trách nhiệm tối thiểu mà tài xế phải có là bao nhiêu?","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $25,000","$100,000 / $300,000 / $50,000"],"h1":"Số đầu tiên và số cuối cùng giống nhau.","h2":"Tennessee yêu cầu ít nhất $25,000 cho thương tích của một người, $50,000 cho thương tích trong một vụ tai nạn, và $25,000 cho thiệt hại tài sản.","p":"Đúng. Mức tối thiểu của Tennessee là 25/50/25."},"tl":{"q":"Sa Tennessee, ano ang pinakamababang liability insurance na dapat mayroon ang driver?","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $25,000","$100,000 / $300,000 / $50,000"],"h1":"Pareho ang una at huling numero.","h2":"Hinihingi ng Tennessee ang hindi bababa sa $25,000 para sa pinsala sa isang tao, $50,000 para sa mga pinsala sa isang banggaan, at $25,000 para sa pinsala sa ari-arian.","p":"Tama. Ang minimum ng Tennessee ay 25/50/25."},"ar":{"q":"في Tennessee، ما الحد الأدنى من تأمين المسؤولية الذي يجب أن يحمله السائق؟","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $25,000","$100,000 / $300,000 / $50,000"],"h1":"الرقم الأول والرقم الأخير متساويان.","h2":"تطلب Tennessee على الأقل $25,000 لإصابة شخص واحد، و$50,000 للإصابات في حادث واحد، و$25,000 للأضرار في الممتلكات.","p":"صحيح. الحد الأدنى في Tennessee هو 25/50/25."},"ref":{"doc":"TN","page":null}},{"id":"tn-023","scope":"TN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Tennessee, you are arrested and refuse an officer's request for an alcohol or drug test. What is the likely result?","o":["A warning letter","A $20 fine only","Nothing, if you pass a later test","Your license is suspended for 12 months"],"h1":"By driving in Tennessee, you have already agreed to be tested.","h2":"In Tennessee, refusing an alcohol or drug test after an arrest will likely lead a court to suspend your license for 12 months.","p":"Right. Refusing can cost you your license for 12 months."},"es":{"q":"En Tennessee, usted es arrestado y se niega a la prueba de alcohol o drogas que le pide un oficial. ¿Cuál es el resultado probable?","o":["Una carta de advertencia","Solo una multa de $20","Nada, si pasa una prueba después","Le suspenden la licencia por 12 meses"],"h1":"Al manejar en Tennessee, usted ya aceptó hacerse la prueba.","h2":"En Tennessee, negarse a una prueba de alcohol o drogas después de un arresto probablemente hará que un tribunal le suspenda la licencia por 12 meses.","p":"Correcto. Negarse puede costarle la licencia por 12 meses."},"zh":{"q":"在 Tennessee，你被逮捕后拒绝警察要求的酒精或药物检测。可能的结果是什么？","o":["一封警告信","只罚款 $20","如果之后的检测通过，就没事","你的驾照被吊销 12 个月"],"h1":"在 Tennessee 开车，就表示你已经同意接受检测。","h2":"在 Tennessee，被逮捕后拒绝酒精或药物检测，法院很可能会吊销你的驾照 12 个月。","p":"对。拒绝检测可能让你失去驾照 12 个月。"},"vi":{"q":"Ở Tennessee, bạn bị bắt và từ chối yêu cầu thử rượu bia hoặc ma túy của cảnh sát. Kết quả có thể là gì?","o":["Một thư cảnh cáo","Chỉ bị phạt $20","Không sao, nếu bạn đậu một lần thử sau đó","Bằng lái của bạn bị treo 12 tháng"],"h1":"Khi lái xe ở Tennessee, bạn đã đồng ý cho thử rồi.","h2":"Ở Tennessee, nếu bạn từ chối thử rượu bia hoặc ma túy sau khi bị bắt, tòa án có thể sẽ treo bằng lái của bạn 12 tháng.","p":"Đúng. Từ chối có thể làm bạn mất bằng lái 12 tháng."},"tl":{"q":"Sa Tennessee, inaresto ka at tumanggi ka sa hiling ng pulis na magpasuri para sa alak o droga. Ano ang malamang na mangyari?","o":["Isang sulat ng babala","Multa na $20 lang","Wala, kung pumasa ka sa susunod na pagsusuri","Masususpinde ang lisensya mo nang 12 buwan"],"h1":"Sa pagmamaneho sa Tennessee, pumayag ka na na masuri.","h2":"Sa Tennessee, kapag tumanggi ka sa pagsusuri para sa alak o droga pagkatapos maaresto, malamang na sususpindihin ng korte ang lisensya mo nang 12 buwan.","p":"Tama. Ang pagtanggi ay maaaring magpawala ng lisensya mo nang 12 buwan."},"ar":{"q":"في Tennessee، تم القبض عليك ورفضت طلب الشرطي إجراء فحص الكحول أو المخدرات. ما النتيجة المحتملة؟","o":["رسالة تحذير","غرامة $20 فقط","لا شيء، إذا نجحت في فحص لاحق","تُعلَّق رخصتك لمدة 12 شهرًا"],"h1":"عندما تقود في Tennessee، فأنت قد وافقت مسبقًا على إجراء الفحص.","h2":"في Tennessee، إذا رفضت فحص الكحول أو المخدرات بعد القبض عليك، فمن المحتمل أن تعلّق المحكمة رخصتك لمدة 12 شهرًا.","p":"صحيح. الرفض قد يُفقدك رخصتك لمدة 12 شهرًا."},"ref":{"doc":"TN","page":81}},{"id":"tn-024","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, after a crash with injuries or more than $400 in damage, how soon must the owner or driver send a crash report to the Department of Safety?","o":["Within 24 hours","Within 20 days","Within 6 months","Only if the police ask"],"h1":"You have about three weeks.","h2":"In Tennessee, after a crash with injury, death or more than $400 in damage, the owner or driver must file a report with the Department of Safety within 20 days.","p":"Right. File the report within 20 days."},"es":{"q":"En Tennessee, después de un choque con heridos o más de $400 en daños, ¿en cuánto tiempo debe el dueño o el conductor enviar un reporte del choque al Departamento de Seguridad?","o":["En 24 horas","En 20 días","En 6 meses","Solo si la policía lo pide"],"h1":"Tiene más o menos tres semanas.","h2":"En Tennessee, después de un choque con heridos, muertos o más de $400 en daños, el dueño o el conductor debe presentar un reporte al Departamento de Seguridad en 20 días.","p":"Correcto. Presente el reporte en 20 días."},"zh":{"q":"在 Tennessee，发生有人受伤或损失超过 $400 的车祸后，车主或司机必须在多长时间内向安全部（Department of Safety）提交车祸报告？","o":["24 小时内","20 天内","6 个月内","只有警察要求时才需要"],"h1":"你大约有三个星期。","h2":"在 Tennessee，发生有人受伤、死亡或损失超过 $400 的车祸后，车主或司机必须在 20 天内向安全部（Department of Safety）提交报告。","p":"对。要在 20 天内提交报告。"},"vi":{"q":"Ở Tennessee, sau một vụ tai nạn có người bị thương hoặc thiệt hại hơn $400, chủ xe hoặc tài xế phải gửi báo cáo tai nạn cho Sở An toàn (Department of Safety) trong bao lâu?","o":["Trong vòng 24 giờ","Trong vòng 20 ngày","Trong vòng 6 tháng","Chỉ khi cảnh sát yêu cầu"],"h1":"Bạn có khoảng ba tuần.","h2":"Ở Tennessee, sau một vụ tai nạn có người bị thương, chết hoặc thiệt hại hơn $400, chủ xe hoặc tài xế phải nộp báo cáo cho Sở An toàn (Department of Safety) trong vòng 20 ngày.","p":"Đúng. Nộp báo cáo trong vòng 20 ngày."},"tl":{"q":"Sa Tennessee, pagkatapos ng banggaan na may nasaktan o pinsalang higit sa $400, gaano kabilis dapat magpadala ang may-ari o drayber ng ulat ng banggaan sa Department of Safety?","o":["Sa loob ng 24 oras","Sa loob ng 20 araw","Sa loob ng 6 na buwan","Kung hihilingin lang ng pulis"],"h1":"May mga tatlong linggo ka.","h2":"Sa Tennessee, pagkatapos ng banggaan na may nasaktan, namatay, o pinsalang higit sa $400, dapat magsumite ang may-ari o drayber ng ulat sa Department of Safety sa loob ng 20 araw.","p":"Tama. Isumite ang ulat sa loob ng 20 araw."},"ar":{"q":"في Tennessee، بعد حادث فيه إصابات أو أضرار تزيد على $400، خلال كم من الوقت يجب على المالك أو السائق إرسال تقرير الحادث إلى إدارة السلامة (Department of Safety)؟","o":["خلال 24 ساعة","خلال 20 يومًا","خلال 6 أشهر","فقط إذا طلبت الشرطة ذلك"],"h1":"لديك نحو ثلاثة أسابيع.","h2":"في Tennessee، بعد حادث فيه إصابة أو وفاة أو أضرار تزيد على $400، يجب على المالك أو السائق تقديم تقرير إلى إدارة السلامة (Department of Safety) خلال 20 يومًا.","p":"صحيح. قدّم التقرير خلال 20 يومًا."},"ref":{"doc":"TN","page":89}},{"id":"tn-025","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, your home address changes. How soon must you tell the Department of Safety?","o":["Within 10 days","Within 90 days","At your next renewal","Within one year"],"h1":"It is a short time, less than two weeks.","h2":"In Tennessee you must tell the Department of Safety about a change of address within 10 days.","p":"Right. Report a new address within 10 days."},"es":{"q":"En Tennessee, su dirección de casa cambia. ¿En cuánto tiempo debe avisar al Departamento de Seguridad?","o":["En 10 días","En 90 días","En su próxima renovación","En un año"],"h1":"Es poco tiempo, menos de dos semanas.","h2":"En Tennessee usted debe avisar al Departamento de Seguridad de un cambio de dirección en 10 días.","p":"Correcto. Avise su nueva dirección en 10 días."},"zh":{"q":"在 Tennessee，你的住址改变了。你必须在多长时间内通知安全部（Department of Safety）？","o":["10 天内","90 天内","下次更新驾照时","一年内"],"h1":"时间很短，不到两个星期。","h2":"在 Tennessee，你必须在 10 天内把地址变更通知安全部（Department of Safety）。","p":"对。要在 10 天内报告新地址。"},"vi":{"q":"Ở Tennessee, địa chỉ nhà của bạn thay đổi. Bạn phải báo cho Sở An toàn (Department of Safety) trong bao lâu?","o":["Trong vòng 10 ngày","Trong vòng 90 ngày","Vào lần gia hạn tới","Trong vòng một năm"],"h1":"Đó là thời gian ngắn, chưa tới hai tuần.","h2":"Ở Tennessee, bạn phải báo cho Sở An toàn (Department of Safety) về việc đổi địa chỉ trong vòng 10 ngày.","p":"Đúng. Báo địa chỉ mới trong vòng 10 ngày."},"tl":{"q":"Sa Tennessee, nagbago ang address ng bahay mo. Gaano kabilis mo dapat sabihin sa Department of Safety?","o":["Sa loob ng 10 araw","Sa loob ng 90 araw","Sa susunod mong renewal","Sa loob ng isang taon"],"h1":"Maikling panahon ito, wala pang dalawang linggo.","h2":"Sa Tennessee, dapat mong sabihin sa Department of Safety ang pagbabago ng address mo sa loob ng 10 araw.","p":"Tama. Iulat ang bagong address sa loob ng 10 araw."},"ar":{"q":"في Tennessee، تغيّر عنوان منزلك. خلال كم من الوقت يجب أن تُبلغ إدارة السلامة (Department of Safety)؟","o":["خلال 10 أيام","خلال 90 يومًا","عند التجديد القادم","خلال سنة واحدة"],"h1":"إنها مدة قصيرة، أقل من أسبوعين.","h2":"في Tennessee يجب أن تُبلغ إدارة السلامة (Department of Safety) بتغيير عنوانك خلال 10 أيام.","p":"صحيح. أبلغ عن العنوان الجديد خلال 10 أيام."},"ref":{"doc":"TN","page":13}},{"id":"tn-026","scope":"TN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Tennessee, a child is 6 years old and shorter than 4 feet 9 inches. How must the child ride?","o":["With a seat belt only, in any seat","In a rear-facing car seat","In a booster seat with a seat belt","On a parent's lap"],"h1":"The child is too small for an adult belt alone, but too old for a rear-facing seat.","h2":"In Tennessee, children 4 through 8 years old who are shorter than 4 feet 9 inches must ride in a booster seat and wear a seat belt.","p":"Right. A booster seat with a seat belt."},"es":{"q":"En Tennessee, un niño tiene 6 años y mide menos de 4 pies 9 pulgadas. ¿Cómo debe viajar?","o":["Solo con cinturón, en cualquier asiento","En un asiento de auto mirando hacia atrás","En un asiento elevado con cinturón de seguridad","En las piernas de su padre o madre"],"h1":"El niño es muy pequeño para usar solo el cinturón de adulto, pero muy grande para un asiento mirando hacia atrás.","h2":"En Tennessee, los niños de 4 a 8 años que miden menos de 4 pies 9 pulgadas deben viajar en un asiento elevado y usar el cinturón de seguridad.","p":"Correcto. Un asiento elevado con cinturón."},"zh":{"q":"在 Tennessee，一个孩子 6 岁，身高不到 4 英尺 9 英寸。这个孩子必须怎样乘车？","o":["只系安全带，坐任何座位都可以","坐后向式儿童安全座椅","坐增高座椅（booster seat）并系安全带","坐在父母腿上"],"h1":"孩子太小，不能只用大人的安全带，但又太大，不适合后向式座椅。","h2":"在 Tennessee，4 到 8 岁、身高不到 4 英尺 9 英寸的孩子，必须坐增高座椅（booster seat）并系安全带。","p":"对。坐增高座椅并系安全带。"},"vi":{"q":"Ở Tennessee, một đứa trẻ 6 tuổi và thấp hơn 4 feet 9 inch. Đứa trẻ phải ngồi xe như thế nào?","o":["Chỉ thắt dây an toàn, ngồi ghế nào cũng được","Ngồi ghế xe quay mặt về phía sau","Ngồi ghế nâng (booster seat) và thắt dây an toàn","Ngồi trên đùi cha mẹ"],"h1":"Đứa trẻ quá nhỏ để chỉ dùng dây an toàn của người lớn, nhưng quá lớn để ngồi ghế quay mặt về phía sau.","h2":"Ở Tennessee, trẻ từ 4 đến 8 tuổi và thấp hơn 4 feet 9 inch phải ngồi ghế nâng (booster seat) và thắt dây an toàn.","p":"Đúng. Ngồi ghế nâng và thắt dây an toàn."},"tl":{"q":"Sa Tennessee, 6 na taong gulang ang isang bata at mas maikli sa 4 feet 9 inches. Paano dapat sumakay ang bata?","o":["Seat belt lang, sa kahit anong upuan","Sa car seat na nakaharap sa likod","Sa booster seat na may seat belt","Sa kandungan ng magulang"],"h1":"Masyadong maliit ang bata para sa seat belt ng matanda lang, pero masyadong malaki na para sa upuang nakaharap sa likod.","h2":"Sa Tennessee, ang mga batang 4 hanggang 8 taong gulang na mas maikli sa 4 feet 9 inches ay dapat sumakay sa booster seat at magsuot ng seat belt.","p":"Tama. Booster seat na may seat belt."},"ar":{"q":"في Tennessee، طفل عمره 6 سنوات وطوله أقل من 4 أقدام و9 بوصات. كيف يجب أن يركب الطفل؟","o":["بحزام الأمان فقط، في أي مقعد","في مقعد سيارة مواجه للخلف","في مقعد رافع (booster seat) مع حزام الأمان","في حضن أحد الوالدين"],"h1":"الطفل صغير جدًا على حزام الكبار وحده، لكنه كبير على المقعد المواجه للخلف.","h2":"في Tennessee، يجب على الأطفال من عمر 4 إلى 8 سنوات الذين طولهم أقل من 4 أقدام و9 بوصات أن يركبوا في مقعد رافع (booster seat) وأن يربطوا حزام الأمان.","p":"صحيح. مقعد رافع مع حزام الأمان."},"ref":{"doc":"TN","page":31}},{"id":"tn-027","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, how often does a driver license expire for a person over 21?","o":["Every 2 years","Every 8 years","Every 15 years","Never"],"h1":"It lasts more than five years.","h2":"In Tennessee a driver license for a person over 21 expires every 8 years from the date it was issued.","p":"Right. Every 8 years."},"es":{"q":"En Tennessee, ¿cada cuánto vence la licencia de conducir de una persona mayor de 21 años?","o":["Cada 2 años","Cada 8 años","Cada 15 años","Nunca"],"h1":"Dura más de cinco años.","h2":"En Tennessee la licencia de conducir de una persona mayor de 21 años vence cada 8 años desde la fecha en que se emitió.","p":"Correcto. Cada 8 años."},"zh":{"q":"在 Tennessee，21 岁以上的人的驾照多久过期一次？","o":["每 2 年","每 8 年","每 15 年","永远不过期"],"h1":"有效期超过五年。","h2":"在 Tennessee，21 岁以上的人的驾照从发证日期起每 8 年过期一次。","p":"对。每 8 年。"},"vi":{"q":"Ở Tennessee, bằng lái của người trên 21 tuổi hết hạn bao lâu một lần?","o":["Mỗi 2 năm","Mỗi 8 năm","Mỗi 15 năm","Không bao giờ"],"h1":"Nó kéo dài hơn năm năm.","h2":"Ở Tennessee, bằng lái của người trên 21 tuổi hết hạn mỗi 8 năm, tính từ ngày cấp.","p":"Đúng. Mỗi 8 năm."},"tl":{"q":"Sa Tennessee, gaano kadalas mag-expire ang driver license ng taong higit 21 taong gulang?","o":["Tuwing 2 taon","Tuwing 8 taon","Tuwing 15 taon","Hindi kailanman"],"h1":"Tumatagal ito nang higit sa limang taon.","h2":"Sa Tennessee, nag-e-expire ang driver license ng taong higit 21 taong gulang tuwing 8 taon mula sa petsa na ibinigay ito.","p":"Tama. Tuwing 8 taon."},"ar":{"q":"في Tennessee، كل كم تنتهي رخصة القيادة لشخص عمره أكثر من 21 سنة؟","o":["كل سنتين (2)","كل 8 سنوات","كل 15 سنة","لا تنتهي أبدًا"],"h1":"تدوم أكثر من خمس سنوات.","h2":"في Tennessee تنتهي رخصة القيادة لشخص عمره أكثر من 21 سنة كل 8 سنوات من تاريخ إصدارها.","p":"صحيح. كل 8 سنوات."},"ref":{"doc":"TN","page":11}},{"id":"tn-028","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, you fail the knowledge test. How long must you wait before you try again?","o":["One week","At least one day","30 days","Six months"],"h1":"The wait is short, just enough time to study again.","h2":"In Tennessee, you must wait at least one day after failing the knowledge test before you take it again.","p":"Right. At least one day."},"es":{"q":"En Tennessee, usted no aprueba el examen de conocimientos. ¿Cuánto tiempo debe esperar para intentarlo otra vez?","o":["Una semana","Al menos un día","30 días","Seis meses"],"h1":"La espera es corta, solo para que pueda estudiar otra vez.","h2":"En Tennessee, debe esperar al menos un día después de reprobar el examen de conocimientos antes de tomarlo otra vez.","p":"Correcto. Al menos un día."},"zh":{"q":"在 Tennessee，你笔试没有通过。你要等多久才能再考一次？","o":["一个星期","至少一天","30 天","六个月"],"h1":"等的时间很短，刚好够你再复习一下。","h2":"在 Tennessee，笔试没有通过以后，你必须至少等一天才能再考。","p":"对。至少一天。"},"vi":{"q":"Ở Tennessee, bạn thi trượt bài thi lý thuyết. Bạn phải chờ bao lâu mới được thi lại?","o":["Một tuần","Ít nhất một ngày","30 ngày","Sáu tháng"],"h1":"Thời gian chờ ngắn, vừa đủ để học lại.","h2":"Ở Tennessee, sau khi thi trượt bài thi lý thuyết, bạn phải chờ ít nhất một ngày rồi mới được thi lại.","p":"Đúng. Ít nhất một ngày."},"tl":{"q":"Sa Tennessee, bumagsak ka sa knowledge test. Gaano katagal ka dapat maghintay bago ka sumubok ulit?","o":["Isang linggo","Hindi bababa sa isang araw","30 araw","Anim na buwan"],"h1":"Maikli ang paghihintay, sapat lang para mag-aral ulit.","h2":"Sa Tennessee, dapat kang maghintay nang hindi bababa sa isang araw pagkatapos bumagsak sa knowledge test bago ka kumuha ulit nito.","p":"Tama. Hindi bababa sa isang araw."},"ar":{"q":"في Tennessee، رسبت في الاختبار النظري. كم يجب أن تنتظر قبل أن تحاول مرة أخرى؟","o":["أسبوع واحد","يوم واحد على الأقل","30 يومًا","ستة أشهر"],"h1":"الانتظار قصير، يكفي فقط لتدرس مرة أخرى.","h2":"في Tennessee، يجب أن تنتظر يومًا واحدًا على الأقل بعد الرسوب في الاختبار النظري قبل أن تعيده.","p":"صحيح. يوم واحد على الأقل."},"ref":{"doc":"TN","page":22}},{"id":"tn-029","scope":"TN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Tennessee, you are following another vehicle at night with your high beams on. Within what distance must you dim them?","o":["100 feet","200 feet","500 feet","1,000 feet"],"h1":"It is about the length of one city block.","h2":"In Tennessee, you must dim your high beams when you are following another vehicle within 500 feet, and also when an oncoming vehicle is within 500 feet.","p":"Right. Within 500 feet."},"es":{"q":"En Tennessee, usted va detrás de otro vehículo de noche con las luces altas encendidas. ¿A qué distancia debe bajarlas?","o":["100 pies","200 pies","500 pies","1,000 pies"],"h1":"Es más o menos el largo de una cuadra de ciudad.","h2":"En Tennessee, debe bajar las luces altas cuando va detrás de otro vehículo a menos de 500 pies, y también cuando un vehículo que viene de frente está a menos de 500 pies.","p":"Correcto. A menos de 500 pies."},"zh":{"q":"在 Tennessee，你晚上开着远光灯跟在另一辆车后面。在多远的距离以内你必须把远光灯调暗？","o":["100 英尺","200 英尺","500 英尺","1,000 英尺"],"h1":"大约是城市里一个街区的长度。","h2":"在 Tennessee，当你跟在另一辆车后面 500 英尺以内时，你必须把远光灯调暗；对面来车在 500 英尺以内时也一样。","p":"对。500 英尺以内。"},"vi":{"q":"Ở Tennessee, bạn đang chạy sau một xe khác vào ban đêm và bật đèn pha. Trong khoảng cách bao nhiêu bạn phải hạ đèn xuống?","o":["100 feet","200 feet","500 feet","1,000 feet"],"h1":"Khoảng bằng chiều dài một dãy nhà trong thành phố.","h2":"Ở Tennessee, bạn phải hạ đèn pha khi chạy sau một xe khác trong vòng 500 feet, và cả khi có xe chạy ngược chiều trong vòng 500 feet.","p":"Đúng. Trong vòng 500 feet."},"tl":{"q":"Sa Tennessee, sumusunod ka sa ibang sasakyan sa gabi at nakabukas ang high beams mo. Sa loob ng anong layo mo dapat hinaan ang mga ito?","o":["100 feet","200 feet","500 feet","1,000 feet"],"h1":"Halos kasinghaba ito ng isang block sa lungsod.","h2":"Sa Tennessee, dapat mong hinaan ang high beams mo kapag sumusunod ka sa ibang sasakyan sa loob ng 500 feet, at gayundin kapag may paparating na sasakyan sa loob ng 500 feet.","p":"Tama. Sa loob ng 500 feet."},"ar":{"q":"في Tennessee، تسير خلف سيارة أخرى ليلًا والأضواء العالية مُشغّلة. ضمن أي مسافة يجب أن تخفضها؟","o":["100 قدم","200 قدم","500 قدم","1,000 قدم"],"h1":"إنها تقريبًا طول مربع سكني واحد في المدينة.","h2":"في Tennessee، يجب أن تخفض الأضواء العالية عندما تسير خلف سيارة أخرى ضمن 500 قدم، وأيضًا عندما تقترب سيارة من الاتجاه المقابل ضمن 500 قدم.","p":"صحيح. ضمن 500 قدم."},"ref":{"doc":"TN","page":45}},{"id":"tn-030","scope":"TN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Tennessee, you may not park within how many feet of a fire hydrant?","o":["15 feet","5 feet","10 feet","30 feet"],"h1":"Fire trucks need room to connect their hoses.","h2":"In Tennessee, you may not park within 15 feet of a fire hydrant.","p":"Right. Stay 15 feet away."},"es":{"q":"En Tennessee, ¿a menos de cuántos pies de un hidrante no puede estacionarse?","o":["15 pies","5 pies","10 pies","30 pies"],"h1":"Los bomberos necesitan espacio para conectar sus mangueras.","h2":"En Tennessee, no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese a 15 pies."},"zh":{"q":"在 Tennessee，你不可以把车停在离消防栓多少英尺以内的地方？","o":["15 英尺","5 英尺","10 英尺","30 英尺"],"h1":"消防车需要空间来接水管。","h2":"在 Tennessee，你不可以把车停在离消防栓 15 英尺以内的地方。","p":"对。要离开 15 英尺。"},"vi":{"q":"Ở Tennessee, bạn không được đậu xe trong vòng bao nhiêu feet tính từ trụ nước cứu hỏa?","o":["15 feet","5 feet","10 feet","30 feet"],"h1":"Xe cứu hỏa cần chỗ để nối ống nước.","h2":"Ở Tennessee, bạn không được đậu xe trong vòng 15 feet tính từ trụ nước cứu hỏa.","p":"Đúng. Đậu cách xa 15 feet."},"tl":{"q":"Sa Tennessee, hindi ka puwedeng pumarada sa loob ng ilang feet mula sa fire hydrant?","o":["15 feet","5 feet","10 feet","30 feet"],"h1":"Kailangan ng mga fire truck ng espasyo para ikabit ang kanilang mga hose.","h2":"Sa Tennessee, hindi ka puwedeng pumarada sa loob ng 15 feet mula sa fire hydrant.","p":"Tama. Lumayo nang 15 feet."},"ar":{"q":"في Tennessee، لا يجوز لك أن تركن ضمن كم قدمًا من صنبور إطفاء الحريق؟","o":["15 قدمًا","5 أقدام","10 أقدام","30 قدمًا"],"h1":"تحتاج سيارات الإطفاء إلى مساحة لتوصيل خراطيمها.","h2":"في Tennessee، لا يجوز لك أن تركن ضمن 15 قدمًا من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بُعد 15 قدمًا."},"ref":{"doc":"TN","page":65}},{"id":"tn-031","scope":"TN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Tennessee, littering fines start at $50. How high can they go?","o":["$100","$500","$1,000","$3,000"],"h1":"The fine grows with the amount of litter, and it can be very large.","h2":"In Tennessee, littering fines start at $50 and can reach $3,000, depending on how much litter there is.","p":"Right. Up to $3,000."},"es":{"q":"En Tennessee, las multas por tirar basura empiezan en $50. ¿Hasta cuánto pueden llegar?","o":["$100","$500","$1,000","$3,000"],"h1":"La multa sube según la cantidad de basura, y puede ser muy alta.","h2":"En Tennessee, las multas por tirar basura empiezan en $50 y pueden llegar a $3,000, según la cantidad de basura.","p":"Correcto. Hasta $3,000."},"zh":{"q":"在 Tennessee，乱扔垃圾的罚款从 $50 起。最高可以罚多少？","o":["$100","$500","$1,000","$3,000"],"h1":"罚款会随着垃圾的多少而增加，而且可能非常高。","h2":"在 Tennessee，乱扔垃圾的罚款从 $50 起，最高可以到 $3,000，要看垃圾有多少。","p":"对。最高 $3,000。"},"vi":{"q":"Ở Tennessee, tiền phạt xả rác bắt đầu từ $50. Tiền phạt có thể lên cao đến mức nào?","o":["$100","$500","$1,000","$3,000"],"h1":"Tiền phạt tăng theo lượng rác, và có thể rất lớn.","h2":"Ở Tennessee, tiền phạt xả rác bắt đầu từ $50 và có thể lên đến $3,000, tùy theo lượng rác nhiều hay ít.","p":"Đúng. Lên đến $3,000."},"tl":{"q":"Sa Tennessee, nagsisimula sa $50 ang multa sa pagkakalat ng basura. Gaano ito kataas puwedeng umabot?","o":["$100","$500","$1,000","$3,000"],"h1":"Lumalaki ang multa ayon sa dami ng basura, at puwede itong maging napakalaki.","h2":"Sa Tennessee, nagsisimula sa $50 ang multa sa pagkakalat ng basura at puwedeng umabot sa $3,000, depende sa dami ng basura.","p":"Tama. Hanggang $3,000."},"ar":{"q":"في Tennessee، تبدأ غرامات رمي النفايات من $50. إلى أي حد يمكن أن ترتفع؟","o":["$100","$500","$1,000","$3,000"],"h1":"تزيد الغرامة مع كمية النفايات، ويمكن أن تكون كبيرة جدًا.","h2":"في Tennessee، تبدأ غرامات رمي النفايات من $50 ويمكن أن تصل إلى $3,000، حسب كمية النفايات.","p":"صحيح. حتى $3,000."},"ref":{"doc":"TN","page":46}},{"id":"tx-001","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, what is the youngest age to get a learner license?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before you can get a provisional license.","h2":"You can get a Texas learner license at 15, which lets you practice for a year before the provisional license at 16.","p":"Right. The Texas learner license starts at 15."},"es":{"q":"En Texas, ¿cuál es la edad mínima para obtener una licencia de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de poder obtener la licencia provisional.","h2":"Usted puede obtener la licencia de aprendiz en Texas a los 15 años, lo que le permite practicar un año antes de la licencia provisional a los 16.","p":"Correcto. La licencia de aprendiz en Texas empieza a los 15."},"zh":{"q":"在 Texas，最小几岁可以拿到学习驾照（learner license）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比拿临时驾照早一年。","h2":"你 15 岁就可以拿到 Texas 学习驾照，这样你可以练习一年，16 岁再拿临时驾照。","p":"对。Texas 的学习驾照从 15 岁开始。"},"vi":{"q":"Ở Texas, tuổi nhỏ nhất để có bằng lái tập (learner license) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là một năm trước khi bạn có thể lấy bằng lái tạm thời.","h2":"Bạn có thể lấy bằng lái tập ở Texas khi 15 tuổi, để tập lái một năm trước khi lấy bằng lái tạm thời lúc 16 tuổi.","p":"Đúng. Ở Texas, bằng lái tập bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Texas, ano ang pinakabatang edad para makakuha ng learner license?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ka makakuha ng provisional license.","h2":"Puwede kang makakuha ng Texas learner license sa edad na 15, para makapagsanay ka nang isang taon bago ang provisional license sa edad na 16.","p":"Tama. Nagsisimula ang Texas learner license sa edad na 15."},"ar":{"q":"في Texas، ما أصغر عمر للحصول على رخصة التعلّم (learner license)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هو قبل سنة واحدة من العمر الذي تحصل فيه على الرخصة المؤقتة.","h2":"يمكنك الحصول على رخصة التعلّم في Texas في عمر 15 سنة، فتتدرّب سنة كاملة قبل الرخصة المؤقتة في عمر 16 سنة.","p":"صحيح. تبدأ رخصة التعلّم في Texas في عمر 15 سنة."},"ref":{"doc":"TX","page":1}},{"id":"tx-002","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, how old must the licensed person beside a learner driver be?","o":["At least 16","At least 18","At least 25","At least 21"],"h1":"The helper must be an adult who can legally drink.","h2":"A Texas learner must drive with a licensed person who is at least 21 years old, so an experienced adult is guiding them.","p":"Right. The person beside you must be 21 or older."},"es":{"q":"En Texas, ¿qué edad debe tener la persona con licencia que va al lado de un conductor aprendiz?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 25","Por lo menos 21"],"h1":"El acompañante debe ser un adulto que ya puede tomar alcohol legalmente.","h2":"Un aprendiz en Texas debe manejar con una persona con licencia de por lo menos 21 años, para que lo guíe un adulto con experiencia.","p":"Correcto. Su acompañante debe tener 21 años o más."},"zh":{"q":"在 Texas，坐在学习司机旁边的有驾照的人必须几岁？","o":["至少 16 岁","至少 18 岁","至少 25 岁","至少 21 岁"],"h1":"这个人必须是可以合法喝酒的成年人。","h2":"Texas 的学习司机必须和至少 21 岁、有驾照的人一起开车，这样有一个有经验的成年人在旁边指导。","p":"对。坐在你旁边的人必须 21 岁或以上。"},"vi":{"q":"Ở Texas, người có bằng lái ngồi cạnh người tập lái phải bao nhiêu tuổi?","o":["Ít nhất 16 tuổi","Ít nhất 18 tuổi","Ít nhất 25 tuổi","Ít nhất 21 tuổi"],"h1":"Người giúp phải là người lớn được phép uống rượu theo luật.","h2":"Người tập lái ở Texas phải lái cùng một người có bằng lái và ít nhất 21 tuổi, để có một người lớn có kinh nghiệm hướng dẫn.","p":"Đúng. Người ngồi cạnh bạn phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Texas, ilang taon dapat ang may lisensyang tao na katabi ng learner driver?","o":["Hindi bababa sa 16","Hindi bababa sa 18","Hindi bababa sa 25","Hindi bababa sa 21"],"h1":"Dapat ay adulto ang katulong na legal nang makainom ng alak.","h2":"Ang learner sa Texas ay dapat magmaneho kasama ang may lisensyang tao na hindi bababa sa 21 taong gulang, para may adultong may karanasan na gumagabay.","p":"Tama. Ang katabi mo ay dapat 21 taong gulang o higit pa."},"ar":{"q":"في Texas، كم يجب أن يكون عمر الشخص المرخَّص الذي يجلس بجانب السائق المتعلّم؟","o":["16 سنة على الأقل","18 سنة على الأقل","25 سنة على الأقل","21 سنة على الأقل"],"h1":"يجب أن يكون المرافق شخصًا بالغًا يُسمح له قانونيًا بشرب الكحول.","h2":"يجب أن يقود المتعلّم في Texas مع شخص مرخَّص عمره 21 سنة على الأقل، حتى يرشده شخص بالغ صاحب خبرة.","p":"صحيح. الشخص الذي بجانبك يجب أن يكون عمره 21 سنة أو أكثر."},"ref":{"doc":"TX","page":1}},{"id":"tx-003","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, how much driving experience must the person supervising a learner have?","o":["At least one year","At least one month","At least five years","At least ten years"],"h1":"It is the shortest period that still means real experience.","h2":"The adult with a Texas learner must have at least one year of driving experience, so they know the road well enough to guide a beginner.","p":"Right. The supervisor needs at least one year of experience."},"es":{"q":"En Texas, ¿cuánta experiencia de manejo debe tener la persona que supervisa a un aprendiz?","o":["Por lo menos un año","Por lo menos un mes","Por lo menos cinco años","Por lo menos diez años"],"h1":"Es el periodo más corto que todavía significa experiencia real.","h2":"El adulto que acompaña a un aprendiz en Texas debe tener por lo menos un año de experiencia manejando, para conocer bien la vía y guiar a un principiante.","p":"Correcto. El supervisor necesita por lo menos un año de experiencia."},"zh":{"q":"在 Texas，监督学习司机的人必须有多少开车经验？","o":["至少一年","至少一个月","至少五年","至少十年"],"h1":"它是能算作真正经验的最短时间。","h2":"陪 Texas 学习司机的成年人必须有至少一年的开车经验，这样他足够了解道路，可以指导新手。","p":"对。监督人至少要有一年经验。"},"vi":{"q":"Ở Texas, người giám sát người tập lái phải có bao nhiêu kinh nghiệm lái xe?","o":["Ít nhất một năm","Ít nhất một tháng","Ít nhất năm năm","Ít nhất mười năm"],"h1":"Đó là thời gian ngắn nhất mà vẫn là kinh nghiệm thật.","h2":"Người lớn đi cùng người tập lái ở Texas phải có ít nhất một năm kinh nghiệm lái xe, để họ hiểu đường đủ rõ mà hướng dẫn người mới.","p":"Đúng. Người giám sát cần ít nhất một năm kinh nghiệm."},"tl":{"q":"Sa Texas, gaano karaming karanasan sa pagmamaneho ang dapat mayroon ang taong nagbabantay sa learner?","o":["Hindi bababa sa isang taon","Hindi bababa sa isang buwan","Hindi bababa sa limang taon","Hindi bababa sa sampung taon"],"h1":"Ito ang pinakamaikling panahon na tunay na karanasan pa rin.","h2":"Ang adultong kasama ng learner sa Texas ay dapat may hindi bababa sa isang taon na karanasan sa pagmamaneho, para alam niya ang daan at kaya niyang gabayan ang baguhan.","p":"Tama. Kailangan ng nagbabantay ng hindi bababa sa isang taon na karanasan."},"ar":{"q":"في Texas، كم سنة من خبرة القيادة يجب أن تكون عند الشخص الذي يشرف على المتعلّم؟","o":["سنة واحدة على الأقل","شهر واحد على الأقل","خمس سنوات على الأقل","عشر سنوات على الأقل"],"h1":"هي أقصر مدة تُعدّ خبرة حقيقية.","h2":"يجب أن يكون عند الشخص البالغ المرافق للمتعلّم في Texas سنة واحدة على الأقل من خبرة القيادة، حتى يعرف الطريق جيدًا ويرشد المبتدئ.","p":"صحيح. المشرف يحتاج إلى سنة واحدة على الأقل من الخبرة."},"ref":{"doc":"TX","page":1}},{"id":"tx-004","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, where must the supervising adult sit when a learner is driving?","o":["In any back seat","Anywhere in the vehicle","In the seat beside the driver","In the middle of the back seat"],"h1":"They must be able to reach and help right away.","h2":"The supervising adult must sit in the seat beside a Texas learner, so they can see the road and help quickly.","p":"Right. The supervisor sits beside the learner."},"es":{"q":"En Texas, ¿dónde debe sentarse el adulto supervisor cuando maneja un aprendiz?","o":["En cualquier asiento de atrás","En cualquier lugar del vehículo","En el asiento al lado del conductor","En el centro del asiento de atrás"],"h1":"Debe poder alcanzar y ayudar enseguida.","h2":"El adulto supervisor debe sentarse al lado del aprendiz en Texas, para ver la vía y ayudar rápido.","p":"Correcto. El supervisor se sienta al lado del aprendiz."},"zh":{"q":"在 Texas，学习司机开车时，监督的成年人必须坐在哪里？","o":["任何一个后座","车里任何地方","司机旁边的座位","后排中间的座位"],"h1":"他必须能马上伸手帮忙。","h2":"监督的成年人必须坐在 Texas 学习司机旁边的座位，这样他能看到路，也能很快帮忙。","p":"对。监督人坐在学习司机旁边。"},"vi":{"q":"Ở Texas, khi người tập lái đang lái, người lớn giám sát phải ngồi ở đâu?","o":["Ở bất kỳ ghế sau nào","Ở bất kỳ chỗ nào trong xe","Ở ghế bên cạnh tài xế","Ở giữa ghế sau"],"h1":"Họ phải có thể với tới và giúp ngay.","h2":"Người lớn giám sát phải ngồi ở ghế bên cạnh người tập lái ở Texas, để họ nhìn thấy đường và giúp nhanh.","p":"Đúng. Người giám sát ngồi bên cạnh người tập lái."},"tl":{"q":"Sa Texas, saan dapat umupo ang nagbabantay na adulto habang nagmamaneho ang learner?","o":["Sa kahit anong upuan sa likod","Kahit saan sa sasakyan","Sa upuang katabi ng driver","Sa gitna ng upuan sa likod"],"h1":"Dapat ay maabot niya at makatulong agad.","h2":"Ang nagbabantay na adulto ay dapat umupo sa upuang katabi ng learner sa Texas, para makita niya ang daan at makatulong agad.","p":"Tama. Katabi ng learner umuupo ang nagbabantay."},"ar":{"q":"في Texas، أين يجب أن يجلس الشخص البالغ المشرف عندما يقود المتعلّم؟","o":["في أي مقعد خلفي","في أي مكان في السيارة","في المقعد الذي بجانب السائق","في وسط المقعد الخلفي"],"h1":"يجب أن يستطيع الوصول والمساعدة فورًا.","h2":"يجب أن يجلس الشخص البالغ المشرف في المقعد الذي بجانب المتعلّم في Texas، حتى يرى الطريق ويساعد بسرعة.","p":"صحيح. المشرف يجلس بجانب المتعلّم."},"ref":{"doc":"TX","page":1}},{"id":"tx-005","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, what must a teen finish before getting a learner license?","o":["A full year of supervised driving","The classroom part of driver education","A road test with an examiner","A first aid course"],"h1":"It happens in a classroom or a parent-taught course, before the wheel.","h2":"A Texas teen must finish the classroom part of an approved driver education course and pass the knowledge test before getting a learner license.","p":"Right. Finish the classroom part of driver education first."},"es":{"q":"En Texas, ¿qué debe terminar un adolescente antes de obtener la licencia de aprendiz?","o":["Un año completo de manejo supervisado","La parte de clases de la educación vial","Un examen de manejo con un examinador","Un curso de primeros auxilios"],"h1":"Se hace en un salón o en un curso enseñado por los padres, antes de manejar.","h2":"Un adolescente en Texas debe terminar la parte de clases de un curso aprobado de educación vial y aprobar el examen de conocimientos antes de obtener la licencia de aprendiz.","p":"Correcto. Primero se termina la parte de clases de educación vial."},"zh":{"q":"在 Texas，青少年拿学习驾照前必须完成什么？","o":["一整年有人监督的驾驶","驾驶教育的课堂部分","和考官一起的路考","急救课程"],"h1":"它在教室里或家长教的课程里完成，在摸方向盘之前。","h2":"Texas 青少年必须完成认可的驾驶教育课程的课堂部分，并通过笔试，才能拿学习驾照。","p":"对。先完成驾驶教育的课堂部分。"},"vi":{"q":"Ở Texas, thiếu niên phải hoàn thành gì trước khi lấy bằng lái tập?","o":["Một năm lái xe có người giám sát","Phần học trên lớp của khóa giáo dục lái xe","Bài thi lái xe với giám khảo","Một khóa sơ cứu"],"h1":"Nó diễn ra trong lớp học hoặc khóa do cha mẹ dạy, trước khi cầm vô lăng.","h2":"Thiếu niên ở Texas phải hoàn thành phần học trên lớp của một khóa giáo dục lái xe được chấp thuận và đậu bài thi kiến thức trước khi lấy bằng lái tập.","p":"Đúng. Hoàn thành phần học trên lớp của khóa giáo dục lái xe trước."},"tl":{"q":"Sa Texas, ano ang dapat tapusin ng isang teenager bago makakuha ng learner license?","o":["Isang buong taon ng pagmamaneho na may nagbabantay","Ang bahagi sa classroom ng driver education","Isang road test kasama ang examiner","Isang kurso sa first aid"],"h1":"Nangyayari ito sa classroom o sa kursong itinuturo ng magulang, bago humawak ng manibela.","h2":"Ang teenager sa Texas ay dapat tapusin ang bahagi sa classroom ng isang aprubadong driver education course at pumasa sa knowledge test bago makakuha ng learner license.","p":"Tama. Tapusin muna ang bahagi sa classroom ng driver education."},"ar":{"q":"في Texas، ماذا يجب أن يُكمل المراهق قبل الحصول على رخصة التعلّم؟","o":["سنة كاملة من القيادة تحت الإشراف","الجزء الصفّي من دورة تعليم القيادة","اختبار القيادة مع الفاحص","دورة إسعافات أولية"],"h1":"يكون في صفّ دراسي أو في دورة يعلّمها أحد الوالدين، قبل الجلوس خلف المقود.","h2":"يجب أن يُكمل المراهق في Texas الجزء الصفّي من دورة تعليم قيادة معتمدة وأن ينجح في اختبار المعرفة قبل الحصول على رخصة التعلّم.","p":"صحيح. أكمِل أولًا الجزء الصفّي من دورة تعليم القيادة."},"ref":{"doc":"TX","page":1}},{"id":"tx-006","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, how long must a teen hold a learner license before getting a provisional license?","o":["1 month","3 months","6 months","2 years"],"h1":"It is half a year.","h2":"A Texas teen must hold the learner license for at least 6 months before applying for a provisional license.","p":"Right. Hold the learner license for at least 6 months."},"es":{"q":"En Texas, ¿cuánto tiempo debe tener un adolescente la licencia de aprendiz antes de obtener la licencia provisional?","o":["1 mes","3 meses","6 meses","2 años"],"h1":"Es medio año.","h2":"Un adolescente en Texas debe tener la licencia de aprendiz por lo menos 6 meses antes de solicitar la licencia provisional.","p":"Correcto. Debe tenerla por lo menos 6 meses."},"zh":{"q":"在 Texas，青少年拿临时驾照前，必须持有学习驾照多久？","o":["1 个月","3 个月","6 个月","2 年"],"h1":"它是半年。","h2":"Texas 青少年必须持有学习驾照至少 6 个月，才能申请临时驾照。","p":"对。持有学习驾照至少 6 个月。"},"vi":{"q":"Ở Texas, thiếu niên phải giữ bằng lái tập bao lâu trước khi lấy bằng lái tạm thời?","o":["1 tháng","3 tháng","6 tháng","2 năm"],"h1":"Đó là nửa năm.","h2":"Thiếu niên ở Texas phải giữ bằng lái tập ít nhất 6 tháng trước khi nộp đơn xin bằng lái tạm thời.","p":"Đúng. Giữ bằng lái tập ít nhất 6 tháng."},"tl":{"q":"Sa Texas, gaano katagal dapat hawak ng teenager ang learner license bago makakuha ng provisional license?","o":["1 buwan","3 buwan","6 na buwan","2 taon"],"h1":"Kalahating taon ito.","h2":"Ang teenager sa Texas ay dapat hawak ang learner license nang hindi bababa sa 6 na buwan bago mag-apply ng provisional license.","p":"Tama. Hawakan ang learner license nang hindi bababa sa 6 na buwan."},"ar":{"q":"في Texas، كم مدة يجب أن يحمل المراهق رخصة التعلّم قبل الحصول على الرخصة المؤقتة؟","o":["شهر واحد","3 أشهر","6 أشهر","سنتان"],"h1":"هي نصف سنة.","h2":"يجب أن يحمل المراهق في Texas رخصة التعلّم 6 أشهر على الأقل قبل أن يتقدّم بطلب الرخصة المؤقتة.","p":"صحيح. احمل رخصة التعلّم 6 أشهر على الأقل."},"ref":{"doc":"TX","page":2}},{"id":"tx-007","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, what is the youngest age to get a provisional license?","o":["16 years old","15 years old","17 years old","18 years old"],"h1":"It comes one year after the learner license.","h2":"A Texas teen can get a provisional license at 16 after holding a learner license for at least 6 months.","p":"Right. The provisional license starts at 16."},"es":{"q":"En Texas, ¿cuál es la edad mínima para obtener la licencia provisional?","o":["16 años","15 años","17 años","18 años"],"h1":"Viene un año después de la licencia de aprendiz.","h2":"Un adolescente en Texas puede obtener la licencia provisional a los 16 años, después de tener la licencia de aprendiz por lo menos 6 meses.","p":"Correcto. La licencia provisional empieza a los 16."},"zh":{"q":"在 Texas，最小几岁可以拿到临时驾照（provisional license）？","o":["16 岁","15 岁","17 岁","18 岁"],"h1":"它在学习驾照之后一年。","h2":"Texas 青少年持有学习驾照至少 6 个月以后，16 岁就可以拿到临时驾照。","p":"对。临时驾照从 16 岁开始。"},"vi":{"q":"Ở Texas, tuổi nhỏ nhất để có bằng lái tạm thời (provisional license) là bao nhiêu?","o":["16 tuổi","15 tuổi","17 tuổi","18 tuổi"],"h1":"Nó đến một năm sau bằng lái tập.","h2":"Thiếu niên ở Texas có thể lấy bằng lái tạm thời lúc 16 tuổi, sau khi giữ bằng lái tập ít nhất 6 tháng.","p":"Đúng. Bằng lái tạm thời bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Texas, ano ang pinakabatang edad para makakuha ng provisional license?","o":["16 taong gulang","15 taong gulang","17 taong gulang","18 taong gulang"],"h1":"Dumarating ito isang taon pagkatapos ng learner license.","h2":"Ang teenager sa Texas ay puwedeng makakuha ng provisional license sa edad na 16, pagkatapos hawakan ang learner license nang hindi bababa sa 6 na buwan.","p":"Tama. Nagsisimula ang provisional license sa edad na 16."},"ar":{"q":"في Texas، ما أصغر عمر للحصول على الرخصة المؤقتة (provisional license)؟","o":["16 سنة","15 سنة","17 سنة","18 سنة"],"h1":"تأتي بعد سنة واحدة من رخصة التعلّم.","h2":"يمكن للمراهق في Texas أن يحصل على الرخصة المؤقتة في عمر 16 سنة بعد أن يحمل رخصة التعلّم 6 أشهر على الأقل.","p":"صحيح. تبدأ الرخصة المؤقتة في عمر 16 سنة."},"ref":{"doc":"TX","page":3}},{"id":"tx-008","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, how many hours of supervised driving must a teen log, including night driving?","o":["20 hours","30 hours","40 hours","50 hours"],"h1":"Ten of these hours are at night.","h2":"A Texas teen must log 30 hours of supervised driving, including 10 hours at night, before the provisional license.","p":"Right. Texas asks for 30 supervised hours."},"es":{"q":"En Texas, ¿cuántas horas de manejo supervisado debe registrar un adolescente, incluidas las de noche?","o":["20 horas","30 horas","40 horas","50 horas"],"h1":"Diez de estas horas son de noche.","h2":"Un adolescente en Texas debe registrar 30 horas de manejo supervisado, incluidas 10 horas de noche, antes de la licencia provisional.","p":"Correcto. Texas pide 30 horas supervisadas."},"zh":{"q":"在 Texas，青少年必须记录多少小时有人监督的驾驶（包括夜间驾驶）？","o":["20 小时","30 小时","40 小时","50 小时"],"h1":"其中十个小时是在晚上。","h2":"Texas 青少年在拿临时驾照前，必须记录 30 小时有人监督的驾驶，其中包括 10 小时夜间驾驶。","p":"对。Texas 要求 30 小时有人监督的驾驶。"},"vi":{"q":"Ở Texas, thiếu niên phải ghi lại bao nhiêu giờ lái xe có người giám sát, kể cả lái ban đêm?","o":["20 giờ","30 giờ","40 giờ","50 giờ"],"h1":"Mười giờ trong số này là ban đêm.","h2":"Thiếu niên ở Texas phải ghi lại 30 giờ lái xe có người giám sát, trong đó có 10 giờ ban đêm, trước khi lấy bằng lái tạm thời.","p":"Đúng. Texas yêu cầu 30 giờ có người giám sát."},"tl":{"q":"Sa Texas, ilang oras ng pagmamaneho na may nagbabantay ang dapat itala ng teenager, kasama ang pagmamaneho sa gabi?","o":["20 oras","30 oras","40 oras","50 oras"],"h1":"Sampu sa mga oras na ito ay sa gabi.","h2":"Ang teenager sa Texas ay dapat magtala ng 30 oras ng pagmamaneho na may nagbabantay, kasama ang 10 oras sa gabi, bago ang provisional license.","p":"Tama. Humihingi ang Texas ng 30 oras na may nagbabantay."},"ar":{"q":"في Texas، كم ساعة من القيادة تحت الإشراف يجب أن يسجّل المراهق، ومنها القيادة في الليل؟","o":["20 ساعة","30 ساعة","40 ساعة","50 ساعة"],"h1":"عشر ساعات منها في الليل.","h2":"يجب أن يسجّل المراهق في Texas 30 ساعة من القيادة تحت الإشراف، منها 10 ساعات في الليل، قبل الرخصة المؤقتة.","p":"صحيح. تطلب Texas 30 ساعة تحت الإشراف."},"ref":{"doc":"TX","page":null}},{"id":"tx-009","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, how many of the supervised practice hours must be at night?","o":["2 hours","5 hours","15 hours","10 hours"],"h1":"It is one third of the 30 hours.","h2":"At least 10 of the 30 supervised hours in Texas must be at night, because driving in the dark is different and needs practice.","p":"Right. 10 of the hours must be at night."},"es":{"q":"En Texas, ¿cuántas de las horas de práctica supervisada deben ser de noche?","o":["2 horas","5 horas","15 horas","10 horas"],"h1":"Es la tercera parte de las 30 horas.","h2":"Por lo menos 10 de las 30 horas supervisadas en Texas deben ser de noche, porque manejar en la oscuridad es distinto y necesita práctica.","p":"Correcto. 10 de las horas deben ser de noche."},"zh":{"q":"在 Texas，有人监督的练习时间里，必须有多少小时是在晚上？","o":["2 小时","5 小时","15 小时","10 小时"],"h1":"它是 30 小时的三分之一。","h2":"在 Texas，30 小时有人监督的驾驶中至少 10 小时必须在晚上，因为天黑时开车不一样，需要练习。","p":"对。其中 10 小时必须在晚上。"},"vi":{"q":"Ở Texas, bao nhiêu giờ tập lái có người giám sát phải là ban đêm?","o":["2 giờ","5 giờ","15 giờ","10 giờ"],"h1":"Đó là một phần ba của 30 giờ.","h2":"Ở Texas, ít nhất 10 trong 30 giờ có người giám sát phải là ban đêm, vì lái xe trong bóng tối khác và cần tập.","p":"Đúng. 10 giờ phải là ban đêm."},"tl":{"q":"Sa Texas, ilan sa mga oras ng pagsasanay na may nagbabantay ang dapat sa gabi?","o":["2 oras","5 oras","15 oras","10 oras"],"h1":"Isang katlo ito ng 30 oras.","h2":"Hindi bababa sa 10 sa 30 oras na may nagbabantay sa Texas ang dapat sa gabi, dahil iba ang pagmamaneho sa dilim at kailangan itong sanayin.","p":"Tama. 10 sa mga oras ang dapat sa gabi."},"ar":{"q":"في Texas، كم ساعة من ساعات التدريب تحت الإشراف يجب أن تكون في الليل؟","o":["ساعتان","5 ساعات","15 ساعة","10 ساعات"],"h1":"هي ثلث الثلاثين ساعة.","h2":"يجب أن تكون 10 ساعات على الأقل من الثلاثين ساعة تحت الإشراف في Texas في الليل، لأن القيادة في الظلام مختلفة وتحتاج إلى تدريب.","p":"صحيح. 10 ساعات منها يجب أن تكون في الليل."},"ref":{"doc":"TX","page":null}},{"id":"tx-010","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, what video course must a teen finish within 90 days before the road test?","o":["Texas Safe Teens","Drive Smart Texas","Impact Texas Teen Drivers","Texas Road Ready"],"h1":"Its name includes the word Impact.","h2":"A Texas teen must complete the Impact Texas Teen Drivers course within 90 days before the driving test.","p":"Right. The course is Impact Texas Teen Drivers."},"es":{"q":"En Texas, ¿qué curso en video debe terminar un adolescente dentro de los 90 días antes del examen de manejo?","o":["Texas Safe Teens","Drive Smart Texas","Impact Texas Teen Drivers","Texas Road Ready"],"h1":"Su nombre incluye la palabra Impact.","h2":"Un adolescente en Texas debe completar el curso Impact Texas Teen Drivers dentro de los 90 días antes del examen de manejo.","p":"Correcto. El curso es Impact Texas Teen Drivers."},"zh":{"q":"在 Texas，青少年必须在路考前 90 天内完成哪个视频课程？","o":["Texas Safe Teens","Drive Smart Texas","Impact Texas Teen Drivers","Texas Road Ready"],"h1":"它的名字里有 Impact 这个词。","h2":"Texas 青少年必须在路考前 90 天内完成 Impact Texas Teen Drivers 课程。","p":"对。这个课程是 Impact Texas Teen Drivers。"},"vi":{"q":"Ở Texas, thiếu niên phải hoàn thành khóa học video nào trong vòng 90 ngày trước bài thi lái xe?","o":["Texas Safe Teens","Drive Smart Texas","Impact Texas Teen Drivers","Texas Road Ready"],"h1":"Tên của nó có chữ Impact.","h2":"Thiếu niên ở Texas phải hoàn thành khóa Impact Texas Teen Drivers trong vòng 90 ngày trước bài thi lái xe.","p":"Đúng. Khóa học là Impact Texas Teen Drivers."},"tl":{"q":"Sa Texas, anong video course ang dapat tapusin ng teenager sa loob ng 90 araw bago ang road test?","o":["Texas Safe Teens","Drive Smart Texas","Impact Texas Teen Drivers","Texas Road Ready"],"h1":"May salitang Impact sa pangalan nito.","h2":"Ang teenager sa Texas ay dapat tapusin ang Impact Texas Teen Drivers course sa loob ng 90 araw bago ang driving test.","p":"Tama. Ang course ay Impact Texas Teen Drivers."},"ar":{"q":"في Texas، أي دورة فيديو يجب أن يُكملها المراهق خلال 90 يومًا قبل اختبار القيادة؟","o":["Texas Safe Teens","Drive Smart Texas","Impact Texas Teen Drivers","Texas Road Ready"],"h1":"اسمها فيه كلمة Impact.","h2":"يجب أن يُكمل المراهق في Texas دورة Impact Texas Teen Drivers خلال 90 يومًا قبل اختبار القيادة.","p":"صحيح. الدورة هي Impact Texas Teen Drivers."},"ref":{"doc":"TX","page":null}},{"id":"tx-011","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, a driver under 18 with a provisional license may not drive during which hours?","o":["Midnight to 5 a.m.","10 p.m. to 6 a.m.","9 p.m. to 5 a.m.","11 p.m. to 4 a.m."],"h1":"The limit starts when a new day begins.","h2":"A Texas driver under 18 with a provisional license may not drive from midnight to 5 a.m., except for work, a school activity or a medical emergency.","p":"Right. No driving from midnight to 5 a.m."},"es":{"q":"En Texas, un conductor menor de 18 con licencia provisional no puede manejar en ¿qué horario?","o":["De medianoche a 5 a.m.","De 10 p.m. a 6 a.m.","De 9 p.m. a 5 a.m.","De 11 p.m. a 4 a.m."],"h1":"El límite empieza cuando comienza un nuevo día.","h2":"Un conductor menor de 18 con licencia provisional en Texas no puede manejar de medianoche a 5 a.m., salvo por trabajo, una actividad escolar o una emergencia médica.","p":"Correcto. No se maneja de medianoche a 5 a.m."},"zh":{"q":"在 Texas，持有临时驾照、未满 18 岁的司机在哪个时段不可以开车？","o":["半夜 12 点到早上 5 点","晚上 10 点到早上 6 点","晚上 9 点到早上 5 点","晚上 11 点到早上 4 点"],"h1":"这个限制从新的一天开始的时候开始。","h2":"Texas 持有临时驾照、未满 18 岁的司机，从半夜 12 点到早上 5 点不可以开车，除非是为了工作、学校活动或医疗紧急情况。","p":"对。半夜 12 点到早上 5 点不能开车。"},"vi":{"q":"Ở Texas, tài xế dưới 18 tuổi có bằng lái tạm thời không được lái xe trong giờ nào?","o":["Nửa đêm đến 5 giờ sáng","10 giờ tối đến 6 giờ sáng","9 giờ tối đến 5 giờ sáng","11 giờ tối đến 4 giờ sáng"],"h1":"Giới hạn bắt đầu khi một ngày mới bắt đầu.","h2":"Tài xế dưới 18 tuổi có bằng lái tạm thời ở Texas không được lái xe từ nửa đêm đến 5 giờ sáng, trừ khi đi làm, đi sinh hoạt của trường hoặc có cấp cứu y tế.","p":"Đúng. Không lái xe từ nửa đêm đến 5 giờ sáng."},"tl":{"q":"Sa Texas, sa anong mga oras hindi puwedeng magmaneho ang driver na wala pang 18 na may provisional license?","o":["Hatinggabi hanggang 5 a.m.","10 p.m. hanggang 6 a.m.","9 p.m. hanggang 5 a.m.","11 p.m. hanggang 4 a.m."],"h1":"Nagsisimula ang limitasyon kapag nagsimula ang bagong araw.","h2":"Ang driver sa Texas na wala pang 18 na may provisional license ay hindi puwedeng magmaneho mula hatinggabi hanggang 5 a.m., maliban kung para sa trabaho, aktibidad sa paaralan o medical emergency.","p":"Tama. Bawal magmaneho mula hatinggabi hanggang 5 a.m."},"ar":{"q":"في Texas، في أي ساعات لا يجوز للسائق الذي عمره أقل من 18 سنة ويحمل رخصة مؤقتة أن يقود؟","o":["من منتصف الليل إلى 5 صباحًا","من 10 مساءً إلى 6 صباحًا","من 9 مساءً إلى 5 صباحًا","من 11 مساءً إلى 4 صباحًا"],"h1":"يبدأ المنع عندما يبدأ يوم جديد.","h2":"لا يجوز للسائق في Texas الذي عمره أقل من 18 سنة ويحمل رخصة مؤقتة أن يقود من منتصف الليل إلى 5 صباحًا، إلا للعمل أو لنشاط مدرسي أو لحالة طبية طارئة.","p":"صحيح. لا قيادة من منتصف الليل إلى 5 صباحًا."},"ref":{"doc":"TX","page":3}},{"id":"tx-012","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, a 16-year-old with a provisional license wants to drive at 1 a.m. Which reason is allowed?","o":["Going to a party","Getting fast food","Visiting a friend","Driving home from work"],"h1":"Only work, school activities and medical emergencies count.","h2":"A Texas provisional driver under 18 may drive between midnight and 5 a.m. only for work, a school-related activity or a medical emergency, so driving home from work is allowed.","p":"Right. Driving for work is one of the allowed reasons."},"es":{"q":"En Texas, un joven de 16 años con licencia provisional quiere manejar a la 1 a.m. ¿Qué motivo está permitido?","o":["Ir a una fiesta","Comprar comida rápida","Visitar a un amigo","Regresar a casa del trabajo"],"h1":"Solo cuentan el trabajo, las actividades escolares y las emergencias médicas.","h2":"Un conductor provisional menor de 18 en Texas puede manejar entre medianoche y 5 a.m. solo por trabajo, una actividad escolar o una emergencia médica, así que regresar del trabajo está permitido.","p":"Correcto. Manejar por trabajo es uno de los motivos permitidos."},"zh":{"q":"在 Texas，一个持有临时驾照的 16 岁青少年想在凌晨 1 点开车。哪个理由是允许的？","o":["去参加派对","去买快餐","去看朋友","下班开车回家"],"h1":"只有工作、学校活动和医疗紧急情况才算。","h2":"Texas 未满 18 岁的临时驾照司机，在半夜 12 点到早上 5 点之间，只能为了工作、学校相关活动或医疗紧急情况开车，所以下班开车回家是允许的。","p":"对。为了工作开车是允许的理由之一。"},"vi":{"q":"Ở Texas, một thiếu niên 16 tuổi có bằng lái tạm thời muốn lái xe lúc 1 giờ sáng. Lý do nào được phép?","o":["Đi dự tiệc","Đi mua đồ ăn nhanh","Đi thăm bạn","Lái xe về nhà sau giờ làm"],"h1":"Chỉ tính công việc, sinh hoạt của trường và cấp cứu y tế.","h2":"Tài xế có bằng lái tạm thời dưới 18 tuổi ở Texas chỉ được lái từ nửa đêm đến 5 giờ sáng vì công việc, sinh hoạt liên quan đến trường hoặc cấp cứu y tế, nên lái xe về nhà sau giờ làm là được phép.","p":"Đúng. Lái xe vì công việc là một lý do được phép."},"tl":{"q":"Sa Texas, gustong magmaneho ng isang 16 taong gulang na may provisional license nang 1 a.m. Aling dahilan ang pinapayagan?","o":["Pagpunta sa party","Pagbili ng fast food","Pagbisita sa kaibigan","Pag-uwi galing sa trabaho"],"h1":"Trabaho, aktibidad sa paaralan at medical emergency lang ang binibilang.","h2":"Ang provisional driver sa Texas na wala pang 18 ay puwedeng magmaneho mula hatinggabi hanggang 5 a.m. para lang sa trabaho, aktibidad na may kinalaman sa paaralan o medical emergency, kaya pinapayagan ang pag-uwi galing sa trabaho.","p":"Tama. Ang pagmamaneho para sa trabaho ay isa sa mga pinapayagang dahilan."},"ar":{"q":"في Texas، مراهق عمره 16 سنة يحمل رخصة مؤقتة يريد أن يقود في الساعة 1 صباحًا. أي سبب مسموح به؟","o":["الذهاب إلى حفلة","شراء وجبة سريعة","زيارة صديق","العودة إلى البيت من العمل"],"h1":"فقط العمل والأنشطة المدرسية والحالات الطبية الطارئة تُحسب.","h2":"السائق في Texas الذي عمره أقل من 18 سنة ويحمل رخصة مؤقتة يجوز له أن يقود بين منتصف الليل و5 صباحًا فقط للعمل أو لنشاط مدرسي أو لحالة طبية طارئة، لذلك العودة إلى البيت من العمل مسموح بها.","p":"صحيح. القيادة من أجل العمل سبب من الأسباب المسموح بها."},"ref":{"doc":"TX","page":3}},{"id":"tx-013","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, how many passengers under 21 who are not family may a provisional driver under 18 carry?","o":["None","One","Two","Three"],"h1":"It is the smallest number above zero.","h2":"A Texas provisional driver under 18 may carry no more than one passenger under 21 who is not a family member, because young passengers distract new drivers.","p":"Right. Only one young passenger who is not family."},"es":{"q":"En Texas, ¿cuántos pasajeros menores de 21 que no son familiares puede llevar un conductor provisional menor de 18?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Es el número más pequeño mayor que cero.","h2":"Un conductor provisional menor de 18 en Texas puede llevar como máximo un pasajero menor de 21 que no sea familiar, porque los pasajeros jóvenes distraen a los conductores nuevos.","p":"Correcto. Solo un pasajero joven que no sea familiar."},"zh":{"q":"在 Texas，未满 18 岁的临时驾照司机可以载几个不是家人、未满 21 岁的乘客？","o":["一个都不行","一个","两个","三个"],"h1":"它是大于零的最小数字。","h2":"Texas 未满 18 岁的临时驾照司机，最多只能载一个不是家人、未满 21 岁的乘客，因为年轻乘客会让新司机分心。","p":"对。只能载一个不是家人的年轻乘客。"},"vi":{"q":"Ở Texas, tài xế có bằng lái tạm thời dưới 18 tuổi được chở bao nhiêu hành khách dưới 21 tuổi không phải người trong gia đình?","o":["Không ai","Một","Hai","Ba"],"h1":"Đó là số nhỏ nhất lớn hơn không.","h2":"Tài xế có bằng lái tạm thời dưới 18 tuổi ở Texas được chở không quá một hành khách dưới 21 tuổi không phải người trong gia đình, vì hành khách trẻ làm tài xế mới mất tập trung.","p":"Đúng. Chỉ một hành khách trẻ không phải người trong gia đình."},"tl":{"q":"Sa Texas, ilang pasaherong wala pang 21 na hindi kapamilya ang puwedeng isakay ng provisional driver na wala pang 18?","o":["Wala","Isa","Dalawa","Tatlo"],"h1":"Ito ang pinakamaliit na numerong higit sa zero.","h2":"Ang provisional driver sa Texas na wala pang 18 ay puwedeng magsakay ng hindi hihigit sa isang pasaherong wala pang 21 na hindi kapamilya, dahil nakaka-distract sa bagong driver ang mga batang pasahero.","p":"Tama. Isang batang pasahero lang na hindi kapamilya."},"ar":{"q":"في Texas، كم راكبًا عمره أقل من 21 سنة وليس من العائلة يجوز أن يحمله سائق برخصة مؤقتة عمره أقل من 18 سنة؟","o":["لا أحد","واحد","اثنان","ثلاثة"],"h1":"هو أصغر عدد أكبر من صفر.","h2":"السائق في Texas الذي عمره أقل من 18 سنة ويحمل رخصة مؤقتة لا يجوز أن يحمل أكثر من راكب واحد عمره أقل من 21 سنة وليس من العائلة، لأن الركاب الصغار يشتّتون انتباه السائقين الجدد.","p":"صحيح. راكب صغير واحد فقط ليس من العائلة."},"ref":{"doc":"TX","page":3}},{"id":"tx-014","scope":"TX","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Texas, may a driver under 18 talk on a phone using a hands-free device while driving?","o":["Yes, hands-free is always allowed","Yes, but only on the highway","No, only in an emergency","Yes, if the call is short"],"h1":"Teen drivers have a stricter rule than adults.","h2":"A Texas driver under 18 may not use any wireless device while driving, hands-free included, except to call for help in an emergency.","p":"Right. Under 18, no phone at all except in an emergency."},"es":{"q":"En Texas, ¿puede un conductor menor de 18 hablar por teléfono con manos libres mientras maneja?","o":["Sí, manos libres siempre está permitido","Sí, pero solo en la autopista","No, solo en una emergencia","Sí, si la llamada es corta"],"h1":"Los conductores adolescentes tienen una regla más estricta que los adultos.","h2":"Un conductor menor de 18 en Texas no puede usar ningún aparato inalámbrico mientras maneja, ni siquiera con manos libres, salvo para pedir ayuda en una emergencia.","p":"Correcto. Menor de 18, nada de teléfono salvo en emergencia."},"zh":{"q":"在 Texas，未满 18 岁的司机开车时可以用免提设备打电话吗？","o":["可以，免提总是允许的","可以，但只能在高速公路上","不可以，只有紧急情况可以","可以，如果电话很短"],"h1":"青少年司机的规定比成年人更严格。","h2":"Texas 未满 18 岁的司机开车时不可以用任何无线设备，包括免提，只有在紧急情况下打电话求助才可以。","p":"对。未满 18 岁，除了紧急情况，完全不能用手机。"},"vi":{"q":"Ở Texas, tài xế dưới 18 tuổi có được nói điện thoại bằng thiết bị rảnh tay khi lái xe không?","o":["Có, rảnh tay luôn được phép","Có, nhưng chỉ trên xa lộ","Không, chỉ khi khẩn cấp","Có, nếu cuộc gọi ngắn"],"h1":"Tài xế thiếu niên có luật nghiêm hơn người lớn.","h2":"Tài xế dưới 18 tuổi ở Texas không được dùng bất kỳ thiết bị không dây nào khi lái xe, kể cả rảnh tay, trừ khi gọi giúp đỡ lúc khẩn cấp.","p":"Đúng. Dưới 18 tuổi, không dùng điện thoại gì cả trừ khi khẩn cấp."},"tl":{"q":"Sa Texas, puwede bang makipag-usap sa telepono gamit ang hands-free device ang driver na wala pang 18 habang nagmamaneho?","o":["Oo, laging pinapayagan ang hands-free","Oo, pero sa highway lang","Hindi, sa emergency lang","Oo, kung maikli ang tawag"],"h1":"Mas mahigpit ang patakaran para sa teen driver kaysa sa adulto.","h2":"Ang driver sa Texas na wala pang 18 ay hindi puwedeng gumamit ng kahit anong wireless device habang nagmamaneho, kasama ang hands-free, maliban sa pagtawag para humingi ng tulong sa emergency.","p":"Tama. Kung wala pang 18, bawal ang telepono maliban sa emergency."},"ar":{"q":"في Texas، هل يجوز للسائق الذي عمره أقل من 18 سنة أن يتكلّم في الهاتف بجهاز من غير استخدام اليدين (hands-free) أثناء القيادة؟","o":["نعم، استخدام الهاتف من غير اليدين مسموح دائمًا","نعم، لكن على الطريق السريع فقط","لا، إلا في حالة طارئة","نعم، إذا كانت المكالمة قصيرة"],"h1":"للسائقين المراهقين قاعدة أشدّ من الكبار.","h2":"لا يجوز للسائق في Texas الذي عمره أقل من 18 سنة أن يستخدم أي جهاز لاسلكي أثناء القيادة، حتى من غير اليدين، إلا للاتصال طلبًا للمساعدة في حالة طارئة.","p":"صحيح. تحت 18 سنة، لا هاتف أبدًا إلا في حالة طارئة."},"ref":{"doc":"TX","page":3}},{"id":"tx-015","scope":"TX","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Texas, is it legal for an adult driver to text while driving?","o":["No, texting while driving is illegal statewide","Yes, outside of school zones","Yes, below 30 mph","Yes, on rural roads only"],"h1":"The rule covers every driver, everywhere in Texas.","h2":"Texas law makes it illegal for every driver to read, write or send text messages while driving, anywhere in the state.","p":"Right. Texting while driving is illegal in all of Texas."},"es":{"q":"En Texas, ¿es legal que un conductor adulto envíe mensajes de texto mientras maneja?","o":["No, es ilegal en todo el estado","Sí, fuera de las zonas escolares","Sí, a menos de 30 mph","Sí, solo en caminos rurales"],"h1":"La regla es para todos los conductores, en todo Texas.","h2":"La ley de Texas prohíbe a todos los conductores leer, escribir o enviar mensajes de texto mientras manejan, en cualquier parte del estado.","p":"Correcto. Enviar textos al manejar es ilegal en todo Texas."},"zh":{"q":"在 Texas，成年司机开车时发短信合法吗？","o":["不合法，开车发短信在全州都违法","合法，在学校区以外","合法，车速低于 30 mph 时","合法，只在乡村道路上"],"h1":"这条规定适用于每个司机，在 Texas 的每个地方。","h2":"Texas 法律规定，每个司机开车时读、写或发短信都是违法的，在全州任何地方都一样。","p":"对。在整个 Texas，开车发短信都是违法的。"},"vi":{"q":"Ở Texas, tài xế người lớn nhắn tin khi lái xe có hợp pháp không?","o":["Không, nhắn tin khi lái xe là bất hợp pháp trên toàn tiểu bang","Có, bên ngoài khu vực trường học","Có, khi chạy dưới 30 mph","Có, chỉ trên đường nông thôn"],"h1":"Luật này áp dụng cho mọi tài xế, ở mọi nơi trong Texas.","h2":"Luật Texas cấm mọi tài xế đọc, viết hoặc gửi tin nhắn khi lái xe, ở bất kỳ đâu trong tiểu bang.","p":"Đúng. Nhắn tin khi lái xe là bất hợp pháp ở khắp Texas."},"tl":{"q":"Sa Texas, legal ba para sa adultong driver ang mag-text habang nagmamaneho?","o":["Hindi, ilegal ang pag-text habang nagmamaneho sa buong estado","Oo, sa labas ng school zone","Oo, kapag mas mababa sa 30 mph","Oo, sa mga daan sa probinsya lang"],"h1":"Para sa bawat driver ang patakaran, saanman sa Texas.","h2":"Ayon sa batas ng Texas, ilegal para sa bawat driver ang magbasa, magsulat o magpadala ng text message habang nagmamaneho, kahit saan sa estado.","p":"Tama. Ilegal ang pag-text habang nagmamaneho sa buong Texas."},"ar":{"q":"في Texas، هل يجوز قانونيًا للسائق البالغ أن يكتب رسائل نصية أثناء القيادة؟","o":["لا، الرسائل النصية أثناء القيادة ممنوعة في كل الولاية","نعم، خارج مناطق المدارس","نعم، تحت 30 mph","نعم، على الطرق الريفية فقط"],"h1":"القاعدة تشمل كل سائق، في كل مكان في Texas.","h2":"قانون Texas يمنع كل سائق من قراءة الرسائل النصية أو كتابتها أو إرسالها أثناء القيادة، في أي مكان في الولاية.","p":"صحيح. الرسائل النصية أثناء القيادة ممنوعة في كل Texas."},"ref":{"doc":"TX","page":54}},{"id":"tx-016","scope":"TX","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Texas, what is the rule for hand-held phones in an active school zone?","o":["They are allowed below 20 mph","Drivers may not use them","They are allowed for short calls","Only teens are banned"],"h1":"Children are crossing nearby.","h2":"Texas drivers may not use a hand-held phone in an active school zone, so their eyes and hands stay ready for children; hands-free use and emergency calls are exceptions.","p":"Right. No hand-held phone in an active school zone."},"es":{"q":"En Texas, ¿cuál es la regla para los teléfonos en la mano en una zona escolar activa?","o":["Se permiten a menos de 20 mph","Los conductores no pueden usarlos","Se permiten para llamadas cortas","Solo están prohibidos para adolescentes"],"h1":"Hay niños cruzando cerca.","h2":"En Texas los conductores no pueden usar un teléfono en la mano en una zona escolar activa, para tener la vista y las manos listas por los niños; el uso con manos libres y las llamadas de emergencia son excepciones.","p":"Correcto. No se usa el teléfono en la mano en una zona escolar activa."},"zh":{"q":"在 Texas，在正在生效的学校区（active school zone）里，手持手机有什么规定？","o":["车速低于 20 mph 时可以用","司机不可以用","短电话可以用","只禁止青少年用"],"h1":"附近有孩子在过马路。","h2":"Texas 司机在正在生效的学校区里不可以用手持手机，这样眼睛和手都能随时注意孩子；免提和紧急电话是例外。","p":"对。在正在生效的学校区里不能用手持手机。"},"vi":{"q":"Ở Texas, luật về điện thoại cầm tay trong khu vực trường học đang hoạt động (active school zone) là gì?","o":["Được phép khi chạy dưới 20 mph","Tài xế không được dùng","Được phép cho cuộc gọi ngắn","Chỉ cấm thiếu niên"],"h1":"Trẻ em đang băng qua đường gần đó.","h2":"Tài xế ở Texas không được dùng điện thoại cầm tay trong khu vực trường học đang hoạt động, để mắt và tay luôn sẵn sàng cho trẻ em; dùng rảnh tay và gọi khẩn cấp là ngoại lệ.","p":"Đúng. Không dùng điện thoại cầm tay trong khu vực trường học đang hoạt động."},"tl":{"q":"Sa Texas, ano ang patakaran sa hand-held na telepono sa active school zone?","o":["Pinapayagan kapag mas mababa sa 20 mph","Hindi puwedeng gamitin ng mga driver","Pinapayagan para sa maikling tawag","Teenager lang ang bawal"],"h1":"May mga batang tumatawid sa malapit.","h2":"Ang mga driver sa Texas ay hindi puwedeng gumamit ng hand-held na telepono sa active school zone, para handa ang mata at kamay para sa mga bata; eksepsiyon ang hands-free at mga tawag sa emergency.","p":"Tama. Bawal ang hand-held na telepono sa active school zone."},"ar":{"q":"في Texas، ما القاعدة بشأن الهاتف المحمول باليد في منطقة مدرسة نشطة (active school zone)؟","o":["مسموح تحت 20 mph","لا يجوز للسائقين استخدامه","مسموح للمكالمات القصيرة","الممنوع هم المراهقون فقط"],"h1":"هناك أطفال يعبرون الطريق قريبًا منك.","h2":"لا يجوز للسائقين في Texas استخدام الهاتف المحمول باليد في منطقة مدرسة نشطة، حتى تبقى العينان واليدان جاهزة من أجل الأطفال؛ والاستخدام من غير اليدين ومكالمات الطوارئ مستثناة.","p":"صحيح. لا هاتف محمول باليد في منطقة مدرسة نشطة."},"ref":{"doc":"TX","page":31}},{"id":"tx-017","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, what score do you need to pass the driver license knowledge test?","o":["60 percent","65 percent","70 percent","80 percent"],"h1":"It is lower than in many other states.","h2":"Texas requires a score of 70 percent or better on the knowledge test to qualify for a license.","p":"Right. You need 70 percent to pass in Texas."},"es":{"q":"En Texas, ¿qué puntaje necesita para aprobar el examen de conocimientos para la licencia?","o":["60 por ciento","65 por ciento","70 por ciento","80 por ciento"],"h1":"Es más bajo que en muchos otros estados.","h2":"Texas exige 70 por ciento o más en el examen de conocimientos para obtener la licencia.","p":"Correcto. Necesita 70 por ciento para aprobar en Texas."},"zh":{"q":"在 Texas，驾照笔试要多少分才能通过？","o":["60%","65%","70%","80%"],"h1":"它比很多其他州低。","h2":"Texas 要求笔试得到 70% 或以上，才符合拿驾照的条件。","p":"对。在 Texas 要 70% 才能通过。"},"vi":{"q":"Ở Texas, bạn cần bao nhiêu điểm để đậu bài thi kiến thức lấy bằng lái?","o":["60 phần trăm","65 phần trăm","70 phần trăm","80 phần trăm"],"h1":"Nó thấp hơn so với nhiều tiểu bang khác.","h2":"Texas yêu cầu đạt 70 phần trăm trở lên trong bài thi kiến thức để đủ điều kiện lấy bằng lái.","p":"Đúng. Bạn cần 70 phần trăm để đậu ở Texas."},"tl":{"q":"Sa Texas, anong score ang kailangan mo para pumasa sa driver license knowledge test?","o":["60 porsiyento","65 porsiyento","70 porsiyento","80 porsiyento"],"h1":"Mas mababa ito kaysa sa maraming ibang estado.","h2":"Humihingi ang Texas ng score na 70 porsiyento o higit pa sa knowledge test para makakuha ng lisensya.","p":"Tama. Kailangan mo ng 70 porsiyento para pumasa sa Texas."},"ar":{"q":"في Texas، ما الدرجة التي تحتاجها للنجاح في اختبار المعرفة لرخصة القيادة؟","o":["60 في المئة","65 في المئة","70 في المئة","80 في المئة"],"h1":"هي أقل مما في ولايات أخرى كثيرة.","h2":"تطلب Texas درجة 70 في المئة أو أكثر في اختبار المعرفة لتكون مؤهّلًا للرخصة.","p":"صحيح. تحتاج إلى 70 في المئة للنجاح في Texas."},"ref":{"doc":"TX","page":7}},{"id":"tx-018","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, in which languages does DPS give the driver license knowledge test?","o":["English only","English, Spanish and French","Any language you ask for","English and Spanish"],"h1":"Texas offers exactly two languages.","h2":"Texas DPS gives the regular driver license knowledge test in English or Spanish only.","p":"Right. The Texas test is in English or Spanish."},"es":{"q":"En Texas, ¿en qué idiomas da el DPS el examen de conocimientos para la licencia?","o":["Solo en inglés","En inglés, español y francés","En cualquier idioma que pida","En inglés y español"],"h1":"Texas ofrece exactamente dos idiomas.","h2":"El DPS de Texas da el examen de conocimientos para la licencia de manejo normal solo en inglés o en español.","p":"Correcto. El examen de Texas es en inglés o en español."},"zh":{"q":"在 Texas，DPS 用哪些语言进行驾照笔试？","o":["只有英语","英语、西班牙语和法语","你要求的任何语言","英语和西班牙语"],"h1":"Texas 刚好提供两种语言。","h2":"Texas DPS 的普通驾照笔试只用英语或西班牙语。","p":"对。Texas 的考试用英语或西班牙语。"},"vi":{"q":"Ở Texas, DPS cho thi kiến thức lấy bằng lái bằng những ngôn ngữ nào?","o":["Chỉ tiếng Anh","Tiếng Anh, tiếng Tây Ban Nha và tiếng Pháp","Bất kỳ ngôn ngữ nào bạn yêu cầu","Tiếng Anh và tiếng Tây Ban Nha"],"h1":"Texas có đúng hai ngôn ngữ.","h2":"Texas DPS cho thi kiến thức lấy bằng lái thông thường chỉ bằng tiếng Anh hoặc tiếng Tây Ban Nha.","p":"Đúng. Bài thi ở Texas bằng tiếng Anh hoặc tiếng Tây Ban Nha."},"tl":{"q":"Sa Texas, sa anong mga wika ibinibigay ng DPS ang driver license knowledge test?","o":["Ingles lang","Ingles, Espanyol at Pranses","Kahit anong wika na hilingin mo","Ingles at Espanyol"],"h1":"Eksaktong dalawang wika ang inaalok ng Texas.","h2":"Ibinibigay ng Texas DPS ang regular na driver license knowledge test sa Ingles o Espanyol lang.","p":"Tama. Ang test sa Texas ay nasa Ingles o Espanyol."},"ar":{"q":"في Texas، بأي لغات يقدّم DPS اختبار المعرفة لرخصة القيادة؟","o":["الإنجليزية فقط","الإنجليزية والإسبانية والفرنسية","أي لغة تطلبها","الإنجليزية والإسبانية"],"h1":"تقدّم Texas لغتين بالضبط.","h2":"يقدّم Texas DPS اختبار المعرفة لرخصة القيادة العادية بالإنجليزية أو بالإسبانية فقط.","p":"صحيح. اختبار Texas بالإنجليزية أو بالإسبانية."},"ref":{"doc":"TX","page":null}},{"id":"tx-019","scope":"TX","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Texas, you are on a road with a 60 mph limit and you cannot leave the lane next to a stopped police car with flashing lights. How fast may you pass?","o":["40 mph or slower","50 mph or slower","55 mph or slower","60 mph or slower"],"h1":"Take 20 away from the speed limit.","h2":"Texas law says that if you cannot move out of the lane next to a stopped emergency vehicle, you must slow to 20 mph below the limit, so 40 mph on a 60 mph road.","p":"Right. Slow to 20 below the limit, so 40 mph."},"es":{"q":"En Texas, va por una vía con límite de 60 mph y no puede salir del carril junto a una patrulla detenida con luces intermitentes. ¿A qué velocidad puede pasar?","o":["A 40 mph o menos","A 50 mph o menos","A 55 mph o menos","A 60 mph o menos"],"h1":"Réstele 20 al límite de velocidad.","h2":"La ley de Texas dice que si no puede salir del carril junto a un vehículo de emergencia detenido, debe bajar a 20 mph menos que el límite, o sea 40 mph en una vía de 60 mph.","p":"Correcto. Baje a 20 menos que el límite: 40 mph."},"zh":{"q":"在 Texas，你在限速 60 mph 的路上，无法离开紧挨着一辆闪灯停着的警车的车道。你可以用多快的速度经过？","o":["40 mph 或更慢","50 mph 或更慢","55 mph 或更慢","60 mph 或更慢"],"h1":"用限速减去 20。","h2":"Texas 法律规定，如果你无法离开紧挨着停着的紧急车辆的车道，你必须减速到比限速低 20 mph，所以在 60 mph 的路上是 40 mph。","p":"对。减速到比限速低 20，所以是 40 mph。"},"vi":{"q":"Ở Texas, bạn đang đi trên đường có giới hạn 60 mph và không thể rời làn xe kế bên một xe cảnh sát đang đỗ có đèn nhấp nháy. Bạn được chạy qua với tốc độ bao nhiêu?","o":["40 mph hoặc chậm hơn","50 mph hoặc chậm hơn","55 mph hoặc chậm hơn","60 mph hoặc chậm hơn"],"h1":"Lấy giới hạn tốc độ trừ đi 20.","h2":"Luật Texas nói nếu bạn không thể rời làn xe kế bên một xe khẩn cấp đang đỗ, bạn phải chạy chậm hơn giới hạn 20 mph, tức là 40 mph trên đường 60 mph.","p":"Đúng. Chạy chậm hơn giới hạn 20, tức là 40 mph."},"tl":{"q":"Sa Texas, nasa daan ka na may 60 mph na limit at hindi ka makaalis sa lane na katabi ng nakahintong police car na may kumikislap na ilaw. Gaano kabilis ka puwedeng dumaan?","o":["40 mph o mas mabagal","50 mph o mas mabagal","55 mph o mas mabagal","60 mph o mas mabagal"],"h1":"Bawasan ng 20 ang speed limit.","h2":"Sinasabi ng batas ng Texas na kung hindi ka makaalis sa lane na katabi ng nakahintong emergency vehicle, dapat kang bumagal sa 20 mph na mas mababa sa limit, kaya 40 mph sa daang 60 mph.","p":"Tama. Bumagal sa 20 na mas mababa sa limit, kaya 40 mph."},"ar":{"q":"في Texas، أنت على طريق حدّ السرعة فيه 60 mph، ولا تستطيع ترك الحارة التي بجانب سيارة شرطة متوقفة أضواؤها تومض. بأي سرعة يجوز أن تمرّ؟","o":["40 mph أو أبطأ","50 mph أو أبطأ","55 mph أو أبطأ","60 mph أو أبطأ"],"h1":"اطرح 20 من حدّ السرعة.","h2":"يقول قانون Texas إنك إذا لم تستطع ترك الحارة التي بجانب مركبة طوارئ متوقفة، يجب أن تخفّف سرعتك إلى 20 mph أقل من الحدّ، أي 40 mph على طريق حدّه 60 mph.","p":"صحيح. خفّف إلى 20 أقل من الحدّ، أي 40 mph."},"ref":{"doc":"TX","page":23}},{"id":"tx-020","scope":"TX","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Texas, the speed limit is 25 mph. You pass a stopped emergency vehicle with flashing lights and cannot move out of the lane next to it. How fast may you go?","o":["15 mph","5 mph","10 mph","20 mph"],"h1":"Take 20 away from the speed limit.","h2":"On a Texas road posted 25 mph, you must slow to 20 mph below the limit, which is 5 mph, when you pass a stopped emergency vehicle with its lights on.","p":"Right. At a 25 mph limit, pass at 5 mph."},"es":{"q":"En Texas, el límite es 25 mph. Usted pasa junto a un vehículo de emergencia detenido con luces intermitentes y no puede salir del carril de al lado. ¿A qué velocidad puede ir?","o":["15 mph","5 mph","10 mph","20 mph"],"h1":"Réstele 20 al límite de velocidad.","h2":"En una vía de Texas con límite de 25 mph, debe bajar a 20 mph menos que el límite, es decir 5 mph, al pasar junto a un vehículo de emergencia detenido con las luces encendidas.","p":"Correcto. Con límite de 25 mph, pase a 5 mph."},"zh":{"q":"在 Texas，限速是 25 mph。你经过一辆闪灯停着的紧急车辆，无法离开紧挨着它的车道。你可以开多快？","o":["15 mph","5 mph","10 mph","20 mph"],"h1":"用限速减去 20。","h2":"在 Texas 限速 25 mph 的路上，经过闪灯停着的紧急车辆时，你必须减速到比限速低 20 mph，也就是 5 mph。","p":"对。限速 25 mph 时，用 5 mph 经过。"},"vi":{"q":"Ở Texas, giới hạn tốc độ là 25 mph. Bạn đi ngang một xe khẩn cấp đang đỗ có đèn nhấp nháy và không thể rời làn xe kế bên nó. Bạn được chạy bao nhanh?","o":["15 mph","5 mph","10 mph","20 mph"],"h1":"Lấy giới hạn tốc độ trừ đi 20.","h2":"Trên đường ở Texas có giới hạn 25 mph, bạn phải chạy chậm hơn giới hạn 20 mph, tức là 5 mph, khi đi ngang một xe khẩn cấp đang đỗ có bật đèn.","p":"Đúng. Ở giới hạn 25 mph, chạy qua với 5 mph."},"tl":{"q":"Sa Texas, 25 mph ang speed limit. Dumaraan ka sa nakahintong emergency vehicle na may kumikislap na ilaw at hindi ka makaalis sa lane na katabi nito. Gaano kabilis ka puwedeng pumunta?","o":["15 mph","5 mph","10 mph","20 mph"],"h1":"Bawasan ng 20 ang speed limit.","h2":"Sa daan sa Texas na may nakapaskil na 25 mph, dapat kang bumagal sa 20 mph na mas mababa sa limit, na 5 mph, kapag dumaraan ka sa nakahintong emergency vehicle na nakabukas ang ilaw.","p":"Tama. Sa 25 mph na limit, dumaan sa 5 mph."},"ar":{"q":"في Texas، حدّ السرعة 25 mph. تمرّ بمركبة طوارئ متوقفة أضواؤها تومض، ولا تستطيع ترك الحارة التي بجانبها. بأي سرعة يجوز أن تسير؟","o":["15 mph","5 mph","10 mph","20 mph"],"h1":"اطرح 20 من حدّ السرعة.","h2":"على طريق في Texas حدّه 25 mph، يجب أن تخفّف سرعتك إلى 20 mph أقل من الحدّ، أي 5 mph، عندما تمرّ بمركبة طوارئ متوقفة أضواؤها مضاءة.","p":"صحيح. عند حدّ 25 mph، مُرّ بسرعة 5 mph."},"ref":{"doc":"TX","page":23}},{"id":"tx-021","scope":"TX","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Texas, a school bus with flashing red lights is stopped on the other side of a road divided only by a center left-turn lane. What must you do?","o":["Keep going, the turn lane divides the road","Slow to 20 mph and pass","Stop, because a turn lane does not divide the road","Honk and pass with care"],"h1":"A turn lane is not a barrier.","h2":"In Texas a center left-turn lane does not make separate roadways, so drivers going both ways must stop for a school bus with flashing red lights.","p":"Right. A turn lane does not count; you must stop."},"es":{"q":"En Texas, un autobús escolar con luces rojas intermitentes está detenido al otro lado de una vía dividida solo por un carril central para girar a la izquierda. ¿Qué debe hacer?","o":["Seguir, el carril de giro divide la vía","Bajar a 20 mph y pasar","Parar, porque un carril de giro no divide la vía","Tocar el claxon y pasar con cuidado"],"h1":"Un carril de giro no es una barrera.","h2":"En Texas un carril central para girar a la izquierda no crea vías separadas, así que los conductores en ambos sentidos deben parar ante un autobús escolar con luces rojas intermitentes.","p":"Correcto. El carril de giro no cuenta; debe parar."},"zh":{"q":"在 Texas，一辆闪红灯的校车停在路的另一边，这条路只用中间的左转车道分开。你必须怎么做？","o":["继续开，转弯车道把路分开了","减速到 20 mph 再经过","停车，因为转弯车道不算把路分开","按喇叭，小心经过"],"h1":"转弯车道不是隔离物。","h2":"在 Texas，中间的左转车道不会把路分成两条独立的道路，所以两个方向的司机都必须为闪红灯的校车停车。","p":"对。转弯车道不算，你必须停车。"},"vi":{"q":"Ở Texas, một xe buýt trường học có đèn đỏ nhấp nháy đang dừng ở phía bên kia con đường, và con đường chỉ được chia bằng một làn rẽ trái ở giữa. Bạn phải làm gì?","o":["Cứ đi tiếp, làn rẽ chia con đường","Giảm xuống 20 mph rồi chạy qua","Dừng lại, vì làn rẽ không chia con đường","Bấm còi rồi cẩn thận chạy qua"],"h1":"Làn rẽ không phải là vật chắn.","h2":"Ở Texas, làn rẽ trái ở giữa không tạo thành hai con đường riêng, nên tài xế đi cả hai chiều phải dừng lại cho xe buýt trường học có đèn đỏ nhấp nháy.","p":"Đúng. Làn rẽ không được tính; bạn phải dừng lại."},"tl":{"q":"Sa Texas, nakahinto ang school bus na may kumikislap na pulang ilaw sa kabilang panig ng daan na hinahati lang ng center left-turn lane. Ano ang dapat mong gawin?","o":["Tumuloy, hinahati ng turn lane ang daan","Bumagal sa 20 mph at dumaan","Huminto, dahil hindi hinahati ng turn lane ang daan","Bumusina at dumaan nang maingat"],"h1":"Hindi harang ang turn lane.","h2":"Sa Texas, hindi gumagawa ng magkahiwalay na daan ang center left-turn lane, kaya ang mga driver sa magkabilang direksyon ay dapat huminto para sa school bus na may kumikislap na pulang ilaw.","p":"Tama. Hindi binibilang ang turn lane; dapat kang huminto."},"ar":{"q":"في Texas، حافلة مدرسية أضواؤها الحمراء تومض متوقفة على الجانب الآخر من طريق لا يفصله إلا حارة انعطاف يسار في الوسط. ماذا يجب أن تفعل؟","o":["استمرّ، فحارة الانعطاف تفصل الطريق","خفّف إلى 20 mph ومُرّ","توقّف، لأن حارة الانعطاف لا تفصل الطريق","استخدم البوق ومُرّ بحذر"],"h1":"حارة الانعطاف ليست حاجزًا.","h2":"في Texas، حارة الانعطاف يسارًا في الوسط لا تجعل الطريق طريقين منفصلين، لذلك يجب على السائقين في الاتجاهين أن يتوقّفوا للحافلة المدرسية التي أضواؤها الحمراء تومض.","p":"صحيح. حارة الانعطاف لا تُحسب؛ يجب أن تتوقّف."},"ref":{"doc":"TX","page":null}},{"id":"tx-022","scope":"TX","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Texas, when may you keep going past a stopped school bus with flashing red lights coming the other way?","o":["When no children are in sight","When you are late for work","When the bus is more than 50 feet away","When a physical barrier or median separates the roads"],"h1":"The two directions must be truly separated.","h2":"In Texas you need not stop for a school bus on the other roadway only when the roads are separated by a physical barrier or a space where cars cannot drive.","p":"Right. Only a real barrier or median lets you keep going."},"es":{"q":"En Texas, ¿cuándo puede seguir adelante si viene en sentido contrario a un autobús escolar detenido con luces rojas intermitentes?","o":["Cuando no se ven niños","Cuando va tarde al trabajo","Cuando el autobús está a más de 50 pies","Cuando una barrera física o un camellón separa las vías"],"h1":"Los dos sentidos deben estar realmente separados.","h2":"En Texas no tiene que parar ante un autobús escolar en la otra vía solo cuando las vías están separadas por una barrera física o un espacio por donde no pueden pasar carros.","p":"Correcto. Solo una barrera o un camellón real le permite seguir."},"zh":{"q":"在 Texas，对面方向有一辆闪红灯停着的校车，什么时候你可以继续开过去？","o":["看不到孩子的时候","你上班快迟到的时候","校车在 50 英尺以外的时候","有实体隔离物或中央分隔带把两边道路分开的时候"],"h1":"两个方向必须真的被分开。","h2":"在 Texas，只有当两边道路被实体隔离物或车辆不能开过去的空间分开时，你才不需要为另一边道路上的校车停车。","p":"对。只有真正的隔离物或中央分隔带才能让你继续开。"},"vi":{"q":"Ở Texas, khi nào bạn được đi tiếp qua một xe buýt trường học đang dừng có đèn đỏ nhấp nháy ở chiều ngược lại?","o":["Khi không thấy trẻ em nào","Khi bạn sắp trễ giờ làm","Khi xe buýt cách xa hơn 50 feet","Khi có vật chắn thật hoặc dải phân cách chia hai con đường"],"h1":"Hai chiều xe phải thật sự được tách ra.","h2":"Ở Texas, bạn chỉ không cần dừng cho xe buýt trường học ở con đường bên kia khi hai con đường được chia bằng vật chắn thật hoặc một khoảng mà xe không thể chạy qua.","p":"Đúng. Chỉ vật chắn thật hoặc dải phân cách mới cho bạn đi tiếp."},"tl":{"q":"Sa Texas, kailan ka puwedeng tumuloy sa pagdaan sa nakahintong school bus na may kumikislap na pulang ilaw na nasa kabilang direksyon?","o":["Kapag walang makitang bata","Kapag huli ka na sa trabaho","Kapag mahigit 50 feet ang layo ng bus","Kapag may pisikal na harang o median na naghihiwalay sa mga daan"],"h1":"Dapat ay tunay na magkahiwalay ang dalawang direksyon.","h2":"Sa Texas, hindi mo kailangang huminto para sa school bus sa kabilang daan kapag lang hinihiwalay ang mga daan ng pisikal na harang o espasyong hindi madadaanan ng mga sasakyan.","p":"Tama. Tunay na harang o median lang ang nagpapahintulot sa iyong tumuloy."},"ar":{"q":"في Texas، متى يجوز أن تستمرّ وتمرّ بحافلة مدرسية متوقفة أضواؤها الحمراء تومض وهي في الاتجاه المعاكس؟","o":["عندما لا ترى أي أطفال","عندما تكون متأخرًا عن العمل","عندما تكون الحافلة على بُعد أكثر من 50 قدمًا","عندما يفصل بين الطريقين حاجز مادي أو جزيرة وسطية"],"h1":"يجب أن يكون الاتجاهان منفصلين فعلًا.","h2":"في Texas لا تحتاج إلى التوقّف لحافلة مدرسية على الطريق الآخر إلا إذا كان الطريقان مفصولين بحاجز مادي أو بمساحة لا تستطيع السيارات السير فيها.","p":"صحيح. فقط حاجز حقيقي أو جزيرة وسطية تسمح لك بالاستمرار."},"ref":{"doc":"TX","page":23}},{"id":"tx-023","scope":"TX","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Texas, what fine range applies for a first offense of passing a stopped school bus illegally?","o":["$500 to $1,250","$50 to $200","$100 to $500","$2,000 to $5,000"],"h1":"It starts at five hundred dollars.","h2":"In Texas a first offense of illegally passing a stopped school bus carries a fine of $500 to $1,250, and repeat offenses cost more.","p":"Right. A first offense costs $500 to $1,250."},"es":{"q":"En Texas, ¿qué rango de multa se aplica la primera vez que se pasa ilegalmente un autobús escolar detenido?","o":["De $500 a $1,250","De $50 a $200","De $100 a $500","De $2,000 a $5,000"],"h1":"Empieza en quinientos dólares.","h2":"En Texas, la primera vez que se pasa ilegalmente un autobús escolar detenido la multa es de $500 a $1,250, y si se repite cuesta más.","p":"Correcto. La primera vez cuesta de $500 a $1,250."},"zh":{"q":"在 Texas，第一次违法超过停着的校车，罚款范围是多少？","o":["$500 到 $1,250","$50 到 $200","$100 到 $500","$2,000 到 $5,000"],"h1":"它从五百美元开始。","h2":"在 Texas，第一次违法超过停着的校车，罚款是 $500 到 $1,250，再犯罚得更多。","p":"对。第一次违法罚 $500 到 $1,250。"},"vi":{"q":"Ở Texas, mức phạt cho lần vi phạm đầu tiên vì vượt qua xe buýt trường học đang dừng một cách bất hợp pháp là bao nhiêu?","o":["$500 đến $1,250","$50 đến $200","$100 đến $500","$2,000 đến $5,000"],"h1":"Nó bắt đầu từ năm trăm đô la.","h2":"Ở Texas, lần đầu vượt qua xe buýt trường học đang dừng một cách bất hợp pháp bị phạt từ $500 đến $1,250, và các lần sau bị phạt nặng hơn.","p":"Đúng. Lần vi phạm đầu bị phạt $500 đến $1,250."},"tl":{"q":"Sa Texas, magkano ang multa para sa unang paglabag sa ilegal na pag-overtake sa nakahintong school bus?","o":["$500 hanggang $1,250","$50 hanggang $200","$100 hanggang $500","$2,000 hanggang $5,000"],"h1":"Nagsisimula ito sa limandaang dolyar.","h2":"Sa Texas, ang unang paglabag sa ilegal na pag-overtake sa nakahintong school bus ay may multang $500 hanggang $1,250, at mas mahal ang mga sumunod na paglabag.","p":"Tama. Ang unang paglabag ay $500 hanggang $1,250."},"ar":{"q":"في Texas، ما نطاق الغرامة على المخالفة الأولى لتجاوز حافلة مدرسية متوقفة بشكل غير قانوني؟","o":["$500 إلى $1,250","$50 إلى $200","$100 إلى $500","$2,000 إلى $5,000"],"h1":"تبدأ من خمسمئة دولار.","h2":"في Texas، المخالفة الأولى لتجاوز حافلة مدرسية متوقفة بشكل غير قانوني عليها غرامة من $500 إلى $1,250، والمخالفات المتكرّرة تكلّف أكثر.","p":"صحيح. المخالفة الأولى تكلّف من $500 إلى $1,250."},"ref":{"doc":"TX","page":23}},{"id":"tx-024","scope":"TX","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Texas, unless a sign says otherwise, what is the speed limit on a street in an urban district?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"It is a round number that is lower than 35.","h2":"Texas law sets 30 mph as the speed limit on streets in an urban district when no other limit is posted.","p":"Right. The urban district limit is 30 mph."},"es":{"q":"En Texas, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad en una calle de zona urbana?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Es un número redondo menor que 35.","h2":"La ley de Texas fija 30 mph como límite en las calles de zona urbana cuando no hay otro límite indicado.","p":"Correcto. El límite en zona urbana es 30 mph."},"zh":{"q":"在 Texas，如果没有标志另外规定，市区（urban district）街道的限速是多少？","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"它是一个比 35 小的整数。","h2":"Texas 法律规定，没有标出其他限速时，市区街道的限速是 30 mph。","p":"对。市区限速是 30 mph。"},"vi":{"q":"Ở Texas, nếu không có biển báo khác, giới hạn tốc độ trên đường phố trong khu đô thị (urban district) là bao nhiêu?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Đó là một số tròn nhỏ hơn 35.","h2":"Luật Texas đặt giới hạn 30 mph trên đường phố trong khu đô thị khi không có giới hạn nào khác được ghi.","p":"Đúng. Giới hạn trong khu đô thị là 30 mph."},"tl":{"q":"Sa Texas, kung walang ibang sinasabi ang karatula, ano ang speed limit sa kalye sa urban district?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Isa itong buong numero na mas mababa sa 35.","h2":"Itinatakda ng batas ng Texas ang 30 mph bilang speed limit sa mga kalye sa urban district kapag walang ibang limit na nakapaskil.","p":"Tama. 30 mph ang limit sa urban district."},"ar":{"q":"في Texas، إذا لم تقل لافتة غير ذلك، ما حدّ السرعة في شارع داخل منطقة حضرية (urban district)؟","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"هو رقم مدوَّر أقل من 35.","h2":"يحدّد قانون Texas سرعة 30 mph حدًّا للسرعة في شوارع المنطقة الحضرية عندما لا يكون هناك حدّ آخر مكتوب.","p":"صحيح. حدّ السرعة في المنطقة الحضرية 30 mph."},"ref":{"doc":"TX","page":46}},{"id":"tx-025","scope":"TX","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Texas, how much alcohol may a driver under 21 have in their system?","o":["Less than 0.08","Less than 0.05","Less than 0.02","None that can be detected"],"h1":"Texas has zero tolerance for young drivers.","h2":"A Texas driver under 21 commits an offense with any detectable amount of alcohol, even below the adult limit of 0.08.","p":"Right. Under 21 means no detectable alcohol."},"es":{"q":"En Texas, ¿cuánto alcohol puede tener en el cuerpo un conductor menor de 21 años?","o":["Menos de 0.08","Menos de 0.05","Menos de 0.02","Nada que se pueda detectar"],"h1":"Texas tiene tolerancia cero para conductores jóvenes.","h2":"Un conductor menor de 21 en Texas comete un delito con cualquier cantidad de alcohol que se pueda detectar, aunque esté por debajo del límite de 0.08 para adultos.","p":"Correcto. Menor de 21 significa nada de alcohol detectable."},"zh":{"q":"在 Texas，未满 21 岁的司机体内可以有多少酒精？","o":["低于 0.08","低于 0.05","低于 0.02","一点都不能被检测到"],"h1":"Texas 对年轻司机是零容忍。","h2":"Texas 未满 21 岁的司机，只要体内能检测到任何酒精就是违法，即使低于成年人的 0.08 上限。","p":"对。未满 21 岁，不能有任何能检测到的酒精。"},"vi":{"q":"Ở Texas, tài xế dưới 21 tuổi được có bao nhiêu rượu bia trong cơ thể?","o":["Dưới 0.08","Dưới 0.05","Dưới 0.02","Không có chút nào đo được"],"h1":"Texas không khoan nhượng với tài xế trẻ.","h2":"Tài xế dưới 21 tuổi ở Texas phạm luật nếu có bất kỳ lượng rượu bia nào đo được, kể cả dưới mức 0.08 của người lớn.","p":"Đúng. Dưới 21 tuổi là không có rượu bia nào đo được."},"tl":{"q":"Sa Texas, gaano karaming alak ang puwedeng nasa katawan ng driver na wala pang 21?","o":["Mas mababa sa 0.08","Mas mababa sa 0.05","Mas mababa sa 0.02","Wala na kayang ma-detect"],"h1":"Zero tolerance ang Texas para sa mga batang driver.","h2":"Ang driver sa Texas na wala pang 21 ay lumalabag sa batas kapag may kahit anong dami ng alak na kayang ma-detect, kahit mas mababa sa 0.08 na limit para sa adulto.","p":"Tama. Kung wala pang 21, walang alak na kayang ma-detect."},"ar":{"q":"في Texas، كم من الكحول يجوز أن يكون في جسم السائق الذي عمره أقل من 21 سنة؟","o":["أقل من 0.08","أقل من 0.05","أقل من 0.02","لا شيء يمكن اكتشافه"],"h1":"Texas لا تتسامح أبدًا مع السائقين الصغار.","h2":"السائق في Texas الذي عمره أقل من 21 سنة يرتكب مخالفة إذا وُجدت في جسمه أي كمية من الكحول يمكن اكتشافها، حتى لو كانت أقل من حدّ الكبار 0.08.","p":"صحيح. تحت 21 سنة يعني لا كحول يمكن اكتشافه."},"ref":{"doc":"TX","page":56}},{"id":"tx-026","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, what is the minimum liability insurance for injury to one person in a crash?","o":["$15,000","$25,000","$30,000","$50,000"],"h1":"It is the first number in 30/60/25.","h2":"Texas requires at least $30,000 of bodily injury coverage for one person in a crash, the first number in the 30/60/25 minimum.","p":"Right. The minimum for one injured person is $30,000."},"es":{"q":"En Texas, ¿cuál es el seguro mínimo de responsabilidad por lesiones a una persona en un choque?","o":["$15,000","$25,000","$30,000","$50,000"],"h1":"Es el primer número de 30/60/25.","h2":"Texas exige por lo menos $30,000 de cobertura por lesiones a una persona en un choque, el primer número del mínimo 30/60/25.","p":"Correcto. El mínimo por una persona lesionada es $30,000."},"zh":{"q":"在 Texas，车祸中一个人受伤的最低责任保险是多少？","o":["$15,000","$25,000","$30,000","$50,000"],"h1":"它是 30/60/25 里的第一个数字。","h2":"Texas 要求车祸中一个人的人身伤害保险至少 $30,000，也就是 30/60/25 最低标准里的第一个数字。","p":"对。一个人受伤的最低保额是 $30,000。"},"vi":{"q":"Ở Texas, bảo hiểm trách nhiệm tối thiểu cho thương tích của một người trong tai nạn là bao nhiêu?","o":["$15,000","$25,000","$30,000","$50,000"],"h1":"Đó là số đầu tiên trong 30/60/25.","h2":"Texas yêu cầu ít nhất $30,000 bảo hiểm thương tích cho một người trong tai nạn, là số đầu tiên trong mức tối thiểu 30/60/25.","p":"Đúng. Mức tối thiểu cho một người bị thương là $30,000."},"tl":{"q":"Sa Texas, ano ang minimum na liability insurance para sa pinsala sa katawan ng isang tao sa banggaan?","o":["$15,000","$25,000","$30,000","$50,000"],"h1":"Ito ang unang numero sa 30/60/25.","h2":"Humihingi ang Texas ng hindi bababa sa $30,000 na bodily injury coverage para sa isang tao sa banggaan, ang unang numero sa 30/60/25 na minimum.","p":"Tama. $30,000 ang minimum para sa isang taong nasaktan."},"ar":{"q":"في Texas، ما الحدّ الأدنى لتأمين المسؤولية عن إصابة شخص واحد في حادث؟","o":["$15,000","$25,000","$30,000","$50,000"],"h1":"هو الرقم الأول في 30/60/25.","h2":"تطلب Texas تأمينًا لا يقلّ عن $30,000 للإصابات الجسدية لشخص واحد في حادث، وهو الرقم الأول في الحدّ الأدنى 30/60/25.","p":"صحيح. الحدّ الأدنى لشخص واحد مصاب هو $30,000."},"ref":{"doc":"TX","page":18}},{"id":"tx-027","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, what is the minimum liability insurance for damage to other people's property in one crash?","o":["$10,000","$25,000","$30,000","$60,000"],"h1":"It is the last number in 30/60/25.","h2":"Texas requires at least $25,000 of property damage liability for one crash, the last number in the 30/60/25 minimum.","p":"Right. The property damage minimum is $25,000."},"es":{"q":"En Texas, ¿cuál es el seguro mínimo de responsabilidad por daños a la propiedad de otros en un choque?","o":["$10,000","$25,000","$30,000","$60,000"],"h1":"Es el último número de 30/60/25.","h2":"Texas exige por lo menos $25,000 de cobertura por daños a la propiedad en un choque, el último número del mínimo 30/60/25.","p":"Correcto. El mínimo por daños a la propiedad es $25,000."},"zh":{"q":"在 Texas，一次车祸中对别人财产损失的最低责任保险是多少？","o":["$10,000","$25,000","$30,000","$60,000"],"h1":"它是 30/60/25 里的最后一个数字。","h2":"Texas 要求一次车祸的财产损失责任保险至少 $25,000，也就是 30/60/25 最低标准里的最后一个数字。","p":"对。财产损失的最低保额是 $25,000。"},"vi":{"q":"Ở Texas, bảo hiểm trách nhiệm tối thiểu cho thiệt hại tài sản của người khác trong một tai nạn là bao nhiêu?","o":["$10,000","$25,000","$30,000","$60,000"],"h1":"Đó là số cuối cùng trong 30/60/25.","h2":"Texas yêu cầu ít nhất $25,000 bảo hiểm trách nhiệm thiệt hại tài sản cho một tai nạn, là số cuối cùng trong mức tối thiểu 30/60/25.","p":"Đúng. Mức tối thiểu cho thiệt hại tài sản là $25,000."},"tl":{"q":"Sa Texas, ano ang minimum na liability insurance para sa pinsala sa ari-arian ng ibang tao sa isang banggaan?","o":["$10,000","$25,000","$30,000","$60,000"],"h1":"Ito ang huling numero sa 30/60/25.","h2":"Humihingi ang Texas ng hindi bababa sa $25,000 na property damage liability para sa isang banggaan, ang huling numero sa 30/60/25 na minimum.","p":"Tama. $25,000 ang minimum para sa pinsala sa ari-arian."},"ar":{"q":"في Texas، ما الحدّ الأدنى لتأمين المسؤولية عن الأضرار في ممتلكات الآخرين في حادث واحد؟","o":["$10,000","$25,000","$30,000","$60,000"],"h1":"هو الرقم الأخير في 30/60/25.","h2":"تطلب Texas تأمين مسؤولية لا يقلّ عن $25,000 لأضرار الممتلكات في حادث واحد، وهو الرقم الأخير في الحدّ الأدنى 30/60/25.","p":"صحيح. الحدّ الأدنى لأضرار الممتلكات هو $25,000."},"ref":{"doc":"TX","page":18}},{"id":"tx-028","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, when does a teen's learner license expire?","o":["One year after it is issued","On the teen's 18th birthday","Six months after it is issued","On the teen's 21st birthday"],"h1":"It is tied to a birthday.","h2":"In Texas a learner license expires on the minor's 18th birthday.","p":"Right. It expires on the 18th birthday."},"es":{"q":"En Texas, ¿cuándo vence la licencia de aprendiz de un adolescente?","o":["Un año después de emitida","En el cumpleaños número 18 del adolescente","Seis meses después de emitida","En el cumpleaños número 21 del adolescente"],"h1":"Depende de un cumpleaños.","h2":"En Texas una licencia de aprendiz vence en el cumpleaños número 18 del menor.","p":"Correcto. Vence en el cumpleaños número 18."},"zh":{"q":"在 Texas，青少年的学习驾照（learner license）什么时候过期？","o":["发证一年后","在青少年 18 岁生日那天","发证六个月后","在青少年 21 岁生日那天"],"h1":"它和生日有关。","h2":"在 Texas，未成年人的学习驾照在他 18 岁生日那天过期。","p":"对。它在 18 岁生日那天过期。"},"vi":{"q":"Ở Texas, bằng lái tập (learner license) của thiếu niên hết hạn khi nào?","o":["Một năm sau khi được cấp","Vào ngày sinh nhật 18 tuổi của thiếu niên","Sáu tháng sau khi được cấp","Vào ngày sinh nhật 21 tuổi của thiếu niên"],"h1":"Nó gắn với một ngày sinh nhật.","h2":"Ở Texas, bằng lái tập của người chưa thành niên hết hạn vào ngày sinh nhật 18 tuổi.","p":"Đúng. Nó hết hạn vào ngày sinh nhật 18 tuổi."},"tl":{"q":"Sa Texas, kailan mag-e-expire ang learner license ng isang teenager?","o":["Isang taon matapos itong ibigay","Sa ika-18 kaarawan ng teenager","Anim na buwan matapos itong ibigay","Sa ika-21 kaarawan ng teenager"],"h1":"Nakatali ito sa isang kaarawan.","h2":"Sa Texas, nag-e-expire ang learner license ng isang menor de edad sa kanyang ika-18 kaarawan.","p":"Tama. Nag-e-expire ito sa ika-18 kaarawan."},"ar":{"q":"في Texas، متى تنتهي رخصة التعلّم (learner license) للمراهق؟","o":["بعد سنة من إصدارها","في عيد ميلاد المراهق الثامن عشر (18)","بعد ستة أشهر من إصدارها","في عيد ميلاد المراهق الحادي والعشرين (21)"],"h1":"ترتبط بعيد ميلاد.","h2":"في Texas تنتهي رخصة التعلّم للقاصر في عيد ميلاده الثامن عشر (18).","p":"صحيح. تنتهي في عيد الميلاد الثامن عشر (18)."},"ref":{"doc":"TX","page":1}},{"id":"tx-029","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, what fine can a driver get for a first conviction of driving without proof of liability insurance?","o":["$175 to $350","$50 to $100","$500 to $750","$1,000 to $2,000"],"h1":"A second conviction costs more, up to $1,000.","h2":"In Texas a first conviction for driving without proof of liability insurance brings a fine of $175 to $350.","p":"Right. The first fine is $175 to $350."},"es":{"q":"En Texas, ¿qué multa puede recibir un conductor por una primera condena por manejar sin prueba de seguro de responsabilidad civil?","o":["De $175 a $350","De $50 a $100","De $500 a $750","De $1,000 a $2,000"],"h1":"Una segunda condena cuesta más, hasta $1,000.","h2":"En Texas una primera condena por manejar sin prueba de seguro de responsabilidad civil trae una multa de $175 a $350.","p":"Correcto. La primera multa es de $175 a $350."},"zh":{"q":"在 Texas，司机第一次因为开车时没有责任保险证明而被定罪，可能被罚多少钱？","o":["$175 到 $350","$50 到 $100","$500 到 $750","$1,000 到 $2,000"],"h1":"第二次定罪罚得更多，最高 $1,000。","h2":"在 Texas，第一次因为开车时没有责任保险证明而被定罪，罚款是 $175 到 $350。","p":"对。第一次罚款是 $175 到 $350。"},"vi":{"q":"Ở Texas, tài xế có thể bị phạt bao nhiêu khi bị kết tội lần đầu vì lái xe không có giấy chứng nhận bảo hiểm trách nhiệm?","o":["$175 đến $350","$50 đến $100","$500 đến $750","$1,000 đến $2,000"],"h1":"Bị kết tội lần thứ hai sẽ tốn nhiều hơn, đến $1,000.","h2":"Ở Texas, bị kết tội lần đầu vì lái xe không có giấy chứng nhận bảo hiểm trách nhiệm sẽ bị phạt từ $175 đến $350.","p":"Đúng. Tiền phạt lần đầu là $175 đến $350."},"tl":{"q":"Sa Texas, magkano ang multa na puwedeng makuha ng driver sa unang conviction dahil nagmaneho nang walang patunay ng liability insurance?","o":["$175 hanggang $350","$50 hanggang $100","$500 hanggang $750","$1,000 hanggang $2,000"],"h1":"Mas mahal ang ikalawang conviction, hanggang $1,000.","h2":"Sa Texas, ang unang conviction dahil nagmaneho nang walang patunay ng liability insurance ay may multang $175 hanggang $350.","p":"Tama. Ang unang multa ay $175 hanggang $350."},"ar":{"q":"في Texas، ما الغرامة التي قد يتلقاها السائق عند إدانته أول مرة بالقيادة دون إثبات تأمين المسؤولية؟","o":["من $175 إلى $350","من $50 إلى $100","من $500 إلى $750","من $1,000 إلى $2,000"],"h1":"الإدانة الثانية تكلّف أكثر، حتى $1,000.","h2":"في Texas، الإدانة الأولى بالقيادة دون إثبات تأمين المسؤولية تعني غرامة من $175 إلى $350.","p":"صحيح. الغرامة الأولى من $175 إلى $350."},"ref":{"doc":"TX","page":18}},{"id":"tx-030","scope":"TX","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Texas, how close may you follow a fire truck that is answering an alarm with its red lights flashing?","o":["No closer than 50 feet","No closer than 100 feet","No closer than 250 feet","No closer than 500 feet"],"h1":"It is more than the length of a football field.","h2":"In Texas you may not follow within 500 feet of a fire truck answering an alarm, or an ambulance, when its flashing red lights are on.","p":"Right. Stay at least 500 feet behind."},"es":{"q":"En Texas, ¿qué tan cerca puede seguir a un camión de bomberos que atiende una alarma con sus luces rojas intermitentes?","o":["No más cerca de 50 pies","No más cerca de 100 pies","No más cerca de 250 pies","No más cerca de 500 pies"],"h1":"Es más que el largo de un campo de fútbol americano.","h2":"En Texas usted no puede seguir a menos de 500 pies a un camión de bomberos que atiende una alarma, ni a una ambulancia, cuando tiene encendidas sus luces rojas intermitentes.","p":"Correcto. Quédese por lo menos a 500 pies detrás."},"zh":{"q":"在 Texas，消防车闪着红灯去处理警报时，你可以跟在它后面多近？","o":["不能近于 50 英尺","不能近于 100 英尺","不能近于 250 英尺","不能近于 500 英尺"],"h1":"它比一个橄榄球场还长。","h2":"在 Texas，消防车去处理警报或救护车闪着红灯时，你不能跟在它后面 500 英尺以内。","p":"对。至少保持在 500 英尺以外。"},"vi":{"q":"Ở Texas, bạn được chạy theo sau xe cứu hỏa đang đi xử lý báo động và nháy đèn đỏ gần đến mức nào?","o":["Không gần hơn 50 feet","Không gần hơn 100 feet","Không gần hơn 250 feet","Không gần hơn 500 feet"],"h1":"Nó dài hơn một sân bóng bầu dục.","h2":"Ở Texas, bạn không được chạy theo trong vòng 500 feet sau xe cứu hỏa đang đi xử lý báo động, hoặc xe cứu thương, khi xe đang nháy đèn đỏ.","p":"Đúng. Hãy giữ cách xa ít nhất 500 feet."},"tl":{"q":"Sa Texas, gaano kalapit ka puwedeng sumunod sa isang fire truck na rumeresponde sa alarma at kumikislap ang pulang ilaw?","o":["Hindi lalapit sa 50 talampakan","Hindi lalapit sa 100 talampakan","Hindi lalapit sa 250 talampakan","Hindi lalapit sa 500 talampakan"],"h1":"Mas mahaba ito kaysa sa isang football field.","h2":"Sa Texas, hindi ka puwedeng sumunod nang mas malapit sa 500 talampakan sa isang fire truck na rumeresponde sa alarma, o sa ambulansya, kapag kumikislap ang pulang ilaw nito.","p":"Tama. Manatili nang hindi bababa sa 500 talampakan sa likod."},"ar":{"q":"في Texas، إلى أي مسافة يمكنك أن تقترب وأنت تسير خلف سيارة إطفاء تستجيب لإنذار وأضواؤها الحمراء تومض؟","o":["ليس أقرب من 50 قدمًا","ليس أقرب من 100 قدم","ليس أقرب من 250 قدمًا","ليس أقرب من 500 قدم"],"h1":"المسافة أطول من ملعب كرة قدم أمريكية.","h2":"في Texas لا يجوز لك أن تسير على بعد أقل من 500 قدم خلف سيارة إطفاء تستجيب لإنذار، أو خلف سيارة إسعاف، عندما تكون أضواؤها الحمراء تومض.","p":"صحيح. ابقَ على بعد 500 قدم على الأقل."},"ref":{"doc":"TX","page":22}},{"id":"tx-031","scope":"TX","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Texas, what is the highest fine for having an open container of alcohol in the passenger area of a vehicle on a public road?","o":["$50","$100","$500","$5,000"],"h1":"The car does not even have to be moving.","h2":"In Texas having an open container of alcohol in the passenger area on a public road can bring a fine of up to $500, even if the vehicle is stopped or parked.","p":"Right. The fine can be up to $500."},"es":{"q":"En Texas, ¿cuál es la multa más alta por tener un envase abierto de alcohol en el área de pasajeros de un vehículo en una vía pública?","o":["$50","$100","$500","$5,000"],"h1":"El carro ni siquiera tiene que estar en movimiento.","h2":"En Texas tener un envase abierto de alcohol en el área de pasajeros en una vía pública puede traer una multa de hasta $500, aunque el vehículo esté detenido o estacionado.","p":"Correcto. La multa puede ser de hasta $500."},"zh":{"q":"在 Texas，在公共道路上的车辆乘客区放着打开的酒类容器，最高罚款是多少？","o":["$50","$100","$500","$5,000"],"h1":"车子甚至不需要在开动。","h2":"在 Texas，在公共道路上的车辆乘客区放着打开的酒类容器，最高可罚 $500，即使车子停着或已经停放。","p":"对。罚款最高 $500。"},"vi":{"q":"Ở Texas, tiền phạt cao nhất cho việc để đồ uống có cồn đã mở trong khu vực hành khách của xe trên đường công cộng là bao nhiêu?","o":["$50","$100","$500","$5,000"],"h1":"Xe thậm chí không cần đang chạy.","h2":"Ở Texas, để đồ uống có cồn đã mở trong khu vực hành khách của xe trên đường công cộng có thể bị phạt đến $500, ngay cả khi xe đang dừng hoặc đậu.","p":"Đúng. Tiền phạt có thể đến $500."},"tl":{"q":"Sa Texas, ano ang pinakamataas na multa kapag may bukas na lalagyan ng alak sa lugar ng pasahero ng sasakyan sa pampublikong kalsada?","o":["$50","$100","$500","$5,000"],"h1":"Hindi na kailangang umaandar ang sasakyan.","h2":"Sa Texas, ang pagkakaroon ng bukas na lalagyan ng alak sa lugar ng pasahero sa pampublikong kalsada ay puwedeng magmulta nang hanggang $500, kahit nakahinto o nakaparada ang sasakyan.","p":"Tama. Ang multa ay puwedeng umabot sa $500."},"ar":{"q":"في Texas، ما أعلى غرامة لوجود عبوة كحول مفتوحة في مكان الركّاب في مركبة على طريق عام؟","o":["$50","$100","$500","$5,000"],"h1":"لا يلزم حتى أن تكون السيارة تتحرك.","h2":"في Texas، وجود عبوة كحول مفتوحة في مكان الركّاب على طريق عام قد يؤدي إلى غرامة تصل إلى $500، حتى لو كانت المركبة متوقفة أو مركونة.","p":"صحيح. قد تصل الغرامة إلى $500."},"ref":{"doc":"TX","page":56}},{"id":"ut-001","scope":"UT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Utah, what is the youngest age to get a learner permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before you can get a driver license.","h2":"In Utah, you can get a learner permit when you are at least 15 years old, one year before you can get a license at 16.","p":"Right. A Utah learner permit starts at age 15."},"es":{"q":"En Utah, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de poder obtener la licencia de conducir.","h2":"En Utah, usted puede obtener el permiso de aprendiz cuando tiene por lo menos 15 años, un año antes de poder obtener la licencia a los 16.","p":"Correcto. El permiso de aprendiz en Utah empieza a los 15 años."},"zh":{"q":"在 Utah，最小几岁可以拿到学习驾照（learner permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比拿驾照的年龄早一年。","h2":"在 Utah，你至少 15 岁就可以拿到学习驾照，比 16 岁拿驾照早一年。","p":"对。Utah 的学习驾照从 15 岁开始。"},"vi":{"q":"Ở Utah, tuổi nhỏ nhất để lấy giấy phép tập lái (learner permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là một năm trước khi bạn có thể lấy bằng lái.","h2":"Ở Utah, bạn có thể lấy giấy phép tập lái khi ít nhất 15 tuổi, một năm trước khi có thể lấy bằng lái lúc 16 tuổi.","p":"Đúng. Giấy phép tập lái ở Utah bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Utah, ano ang pinakabatang edad para makakuha ng learner permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ka makakuha ng driver license.","h2":"Sa Utah, puwede kang kumuha ng learner permit kapag hindi bababa sa 15 taong gulang ka, isang taon bago ka makakuha ng license sa edad na 16.","p":"Tama. Nagsisimula ang learner permit sa Utah sa edad na 15."},"ar":{"q":"في Utah، ما أصغر عمر للحصول على تصريح التعلّم (learner permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هو سنة واحدة قبل أن تحصل على رخصة القيادة.","h2":"في Utah يمكنك الحصول على تصريح التعلّم عندما يكون عمرك 15 سنة على الأقل، أي قبل سنة من الحصول على الرخصة في عمر 16.","p":"صحيح. في Utah يبدأ تصريح التعلّم في عمر 15 سنة."},"ref":{"doc":"UT","page":7}},{"id":"ut-002","scope":"UT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Utah, how long is a learner permit valid?","o":["6 months","12 months","18 months","24 months"],"h1":"It is a year and a half.","h2":"Utah law says a learner permit is valid for 18 months, which gives a new driver time to practice and finish the requirements.","p":"Right. A Utah learner permit lasts 18 months."},"es":{"q":"En Utah, ¿cuánto tiempo es válido el permiso de aprendiz?","o":["6 meses","12 meses","18 meses","24 meses"],"h1":"Es un año y medio.","h2":"La ley de Utah dice que el permiso de aprendiz es válido por 18 meses, lo que le da tiempo al nuevo conductor para practicar y cumplir los requisitos.","p":"Correcto. El permiso de aprendiz en Utah dura 18 meses."},"zh":{"q":"在 Utah，学习驾照的有效期是多久？","o":["6 个月","12 个月","18 个月","24 个月"],"h1":"是一年半。","h2":"Utah 法律规定，学习驾照的有效期是 18 个月，让新司机有时间练习并完成要求。","p":"对。Utah 的学习驾照有效期是 18 个月。"},"vi":{"q":"Ở Utah, giấy phép tập lái có giá trị trong bao lâu?","o":["6 tháng","12 tháng","18 tháng","24 tháng"],"h1":"Đó là một năm rưỡi.","h2":"Luật Utah nói giấy phép tập lái có giá trị trong 18 tháng, cho người lái mới thời gian để tập và hoàn thành các yêu cầu.","p":"Đúng. Giấy phép tập lái ở Utah có giá trị 18 tháng."},"tl":{"q":"Sa Utah, gaano katagal may bisa ang learner permit?","o":["6 na buwan","12 buwan","18 buwan","24 na buwan"],"h1":"Isang taon at kalahati ito.","h2":"Sinasabi ng batas ng Utah na may bisa ang learner permit nang 18 buwan, para may oras ang bagong driver na magsanay at tapusin ang mga kailangan.","p":"Tama. Tumatagal nang 18 buwan ang learner permit sa Utah."},"ar":{"q":"في Utah، كم مدة صلاحية تصريح التعلّم؟","o":["6 أشهر","12 شهرًا","18 شهرًا","24 شهرًا"],"h1":"هي سنة ونصف.","h2":"قانون Utah يقول إن تصريح التعلّم صالح لمدة 18 شهرًا، وهذا يعطي السائق الجديد وقتًا للتدريب وإكمال الشروط.","p":"صحيح. تصريح التعلّم في Utah صالح لمدة 18 شهرًا."},"ref":{"doc":"UT","page":7}},{"id":"ut-003","scope":"UT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Utah, how many hours of supervised driving must a teen log before getting a license?","o":["20 hours","30 hours","40 hours","60 hours"],"h1":"Ten of these hours must be at night.","h2":"In Utah, a teen must log at least 40 hours of supervised driving, including at least 10 hours at night, before getting a license.","p":"Right. Utah requires 40 supervised hours."},"es":{"q":"En Utah, ¿cuántas horas de manejo supervisado debe registrar un joven antes de obtener la licencia?","o":["20 horas","30 horas","40 horas","60 horas"],"h1":"Diez de estas horas deben ser de noche.","h2":"En Utah, un joven debe registrar por lo menos 40 horas de manejo supervisado, incluidas por lo menos 10 horas de noche, antes de obtener la licencia.","p":"Correcto. Utah exige 40 horas supervisadas."},"zh":{"q":"在 Utah，青少年在拿驾照之前，必须记录多少小时有人陪同的驾驶？","o":["20 小时","30 小时","40 小时","60 小时"],"h1":"其中 10 小时必须在夜间。","h2":"在 Utah，青少年拿驾照之前，必须记录至少 40 小时有人陪同的驾驶，其中至少 10 小时在夜间。","p":"对。Utah 要求 40 小时有人陪同的驾驶。"},"vi":{"q":"Ở Utah, thiếu niên phải ghi lại bao nhiêu giờ lái xe có người giám sát trước khi lấy bằng lái?","o":["20 giờ","30 giờ","40 giờ","60 giờ"],"h1":"Mười giờ trong số đó phải lái vào ban đêm.","h2":"Ở Utah, thiếu niên phải ghi lại ít nhất 40 giờ lái xe có người giám sát, trong đó ít nhất 10 giờ vào ban đêm, trước khi lấy bằng lái.","p":"Đúng. Utah yêu cầu 40 giờ có người giám sát."},"tl":{"q":"Sa Utah, ilang oras ng pagmamaneho na may gumagabay ang dapat itala ng isang teen bago makakuha ng license?","o":["20 oras","30 oras","40 oras","60 oras"],"h1":"Sampu sa mga oras na ito ay dapat sa gabi.","h2":"Sa Utah, dapat magtala ang isang teen ng hindi bababa sa 40 oras ng pagmamaneho na may gumagabay, kasama ang hindi bababa sa 10 oras sa gabi, bago makakuha ng license.","p":"Tama. Kailangan ng Utah ang 40 oras na may gumagabay."},"ar":{"q":"في Utah، كم ساعة من القيادة تحت الإشراف يجب أن يسجّل المراهق قبل الحصول على الرخصة؟","o":["20 ساعة","30 ساعة","40 ساعة","60 ساعة"],"h1":"عشر ساعات منها يجب أن تكون في الليل.","h2":"في Utah يجب أن يسجّل المراهق 40 ساعة على الأقل من القيادة تحت الإشراف، منها 10 ساعات على الأقل في الليل، قبل الحصول على الرخصة.","p":"صحيح. تطلب Utah 40 ساعة تحت الإشراف."},"ref":{"doc":"UT","page":6}},{"id":"ut-004","scope":"UT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Utah, how many of a teen's supervised practice hours must be at night?","o":["At least 10 hours","At least 2 hours","At least 5 hours","At least 20 hours"],"h1":"It is a small part of the 40 total hours, but more than a few.","h2":"Of the 40 supervised hours Utah requires, at least 10 must be driven at night so the teen gains experience in the dark.","p":"Right. At least 10 of the hours must be at night."},"es":{"q":"En Utah, ¿cuántas de las horas de práctica supervisada de un joven deben ser de noche?","o":["Por lo menos 10 horas","Por lo menos 2 horas","Por lo menos 5 horas","Por lo menos 20 horas"],"h1":"Es una parte pequeña de las 40 horas en total, pero más que unas pocas.","h2":"De las 40 horas supervisadas que exige Utah, por lo menos 10 deben ser de noche para que el joven gane experiencia en la oscuridad.","p":"Correcto. Por lo menos 10 de las horas deben ser de noche."},"zh":{"q":"在 Utah，青少年有人陪同的练习时间中，有多少小时必须在夜间？","o":["至少 10 小时","至少 2 小时","至少 5 小时","至少 20 小时"],"h1":"这是总共 40 小时中的一小部分，但不只几个小时。","h2":"在 Utah 要求的 40 小时有人陪同的驾驶中，至少 10 小时必须在夜间，让青少年积累在黑暗中开车的经验。","p":"对。至少 10 小时必须在夜间。"},"vi":{"q":"Ở Utah, trong số giờ tập lái có người giám sát của thiếu niên, bao nhiêu giờ phải lái vào ban đêm?","o":["Ít nhất 10 giờ","Ít nhất 2 giờ","Ít nhất 5 giờ","Ít nhất 20 giờ"],"h1":"Đó là một phần nhỏ của tổng 40 giờ, nhưng nhiều hơn vài giờ.","h2":"Trong 40 giờ có người giám sát mà Utah yêu cầu, ít nhất 10 giờ phải lái vào ban đêm để thiếu niên có kinh nghiệm lái trong bóng tối.","p":"Đúng. Ít nhất 10 giờ phải lái vào ban đêm."},"tl":{"q":"Sa Utah, ilan sa mga oras ng pagsasanay na may gumagabay ng isang teen ang dapat sa gabi?","o":["Hindi bababa sa 10 oras","Hindi bababa sa 2 oras","Hindi bababa sa 5 oras","Hindi bababa sa 20 oras"],"h1":"Maliit na bahagi ito ng kabuuang 40 oras, pero higit sa ilan lang.","h2":"Sa 40 oras na may gumagabay na kailangan ng Utah, hindi bababa sa 10 ang dapat imaneho sa gabi para magkaroon ng karanasan ang teen sa dilim.","p":"Tama. Hindi bababa sa 10 sa mga oras ang dapat sa gabi."},"ar":{"q":"في Utah، كم ساعة من ساعات التدريب تحت الإشراف للمراهق يجب أن تكون في الليل؟","o":["10 ساعات على الأقل","2 ساعة على الأقل","5 ساعات على الأقل","20 ساعة على الأقل"],"h1":"هي جزء صغير من مجموع 40 ساعة، لكنها أكثر من بضع ساعات.","h2":"من الـ 40 ساعة تحت الإشراف التي تطلبها Utah، يجب أن تكون 10 ساعات على الأقل في الليل حتى يكتسب المراهق خبرة القيادة في الظلام.","p":"صحيح. يجب أن تكون 10 ساعات على الأقل في الليل."},"ref":{"doc":"UT","page":6}},{"id":"ut-005","scope":"UT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Utah, how long must a 16- or 17-year-old hold a learner permit before getting a license?","o":["30 days","90 days","One year","Six months"],"h1":"It is half of a year.","h2":"In Utah, a driver who is 16 or 17 must hold the learner permit for at least six months before getting a driver license.","p":"Right. Drivers who are 16 or 17 hold the permit for at least six months."},"es":{"q":"En Utah, ¿cuánto tiempo debe tener el permiso de aprendiz un joven de 16 o 17 años antes de obtener la licencia?","o":["30 días","90 días","Un año","Seis meses"],"h1":"Es la mitad de un año.","h2":"En Utah, un conductor de 16 o 17 años debe tener el permiso de aprendiz por lo menos seis meses antes de obtener la licencia de conducir.","p":"Correcto. Los conductores de 16 o 17 años tienen el permiso por lo menos seis meses."},"zh":{"q":"在 Utah，16 岁或 17 岁的人必须持有学习驾照多久，才能拿驾照？","o":["30 天","90 天","一年","六个月"],"h1":"是半年。","h2":"在 Utah，16 岁或 17 岁的司机必须持有学习驾照至少六个月，才能拿到驾照。","p":"对。16 岁或 17 岁的司机要持有学习驾照至少六个月。"},"vi":{"q":"Ở Utah, người 16 hoặc 17 tuổi phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái?","o":["30 ngày","90 ngày","Một năm","Sáu tháng"],"h1":"Đó là nửa năm.","h2":"Ở Utah, người lái 16 hoặc 17 tuổi phải giữ giấy phép tập lái ít nhất sáu tháng trước khi lấy bằng lái.","p":"Đúng. Người lái 16 hoặc 17 tuổi giữ giấy phép ít nhất sáu tháng."},"tl":{"q":"Sa Utah, gaano katagal dapat hawak ng isang 16 o 17 taong gulang ang learner permit bago makakuha ng license?","o":["30 araw","90 araw","Isang taon","Anim na buwan"],"h1":"Kalahating taon ito.","h2":"Sa Utah, ang driver na 16 o 17 taong gulang ay dapat humawak ng learner permit nang hindi bababa sa anim na buwan bago makakuha ng driver license.","p":"Tama. Hawak ng mga driver na 16 o 17 ang permit nang hindi bababa sa anim na buwan."},"ar":{"q":"في Utah، كم مدة يجب أن يحمل الشخص الذي عمره 16 أو 17 سنة تصريح التعلّم قبل الحصول على الرخصة؟","o":["30 يومًا","90 يومًا","سنة واحدة","ستة أشهر"],"h1":"هي نصف سنة.","h2":"في Utah يجب على السائق الذي عمره 16 أو 17 سنة أن يحمل تصريح التعلّم ستة أشهر على الأقل قبل الحصول على رخصة القيادة.","p":"صحيح. السائقون في عمر 16 أو 17 يحملون التصريح ستة أشهر على الأقل."},"ref":{"doc":"UT","page":7}},{"id":"ut-006","scope":"UT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Utah, how long must a driver who is 19 or older hold a learner permit before getting a license?","o":["30 days","90 days","Six months","One year"],"h1":"It is shorter than the time for teens, about three months.","h2":"In Utah, a driver who is 19 or older must hold the learner permit for at least 90 days, unless they finish an approved driver education course.","p":"Right. Drivers 19 and older hold the permit for at least 90 days."},"es":{"q":"En Utah, ¿cuánto tiempo debe tener el permiso de aprendiz un conductor de 19 años o más antes de obtener la licencia?","o":["30 días","90 días","Seis meses","Un año"],"h1":"Es menos tiempo que para los jóvenes, unos tres meses.","h2":"En Utah, un conductor de 19 años o más debe tener el permiso de aprendiz por lo menos 90 días, a menos que termine un curso aprobado de educación vial.","p":"Correcto. Los conductores de 19 años o más tienen el permiso por lo menos 90 días."},"zh":{"q":"在 Utah，19 岁或以上的人必须持有学习驾照多久，才能拿驾照？","o":["30 天","90 天","六个月","一年"],"h1":"比青少年的时间短，大约三个月。","h2":"在 Utah，19 岁或以上的司机必须持有学习驾照至少 90 天，除非他们完成了经过批准的驾驶教育课程。","p":"对。19 岁及以上的司机要持有学习驾照至少 90 天。"},"vi":{"q":"Ở Utah, người lái từ 19 tuổi trở lên phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái?","o":["30 ngày","90 ngày","Sáu tháng","Một năm"],"h1":"Ngắn hơn thời gian của thiếu niên, khoảng ba tháng.","h2":"Ở Utah, người lái từ 19 tuổi trở lên phải giữ giấy phép tập lái ít nhất 90 ngày, trừ khi họ hoàn thành một khóa học lái xe được chấp thuận.","p":"Đúng. Người lái từ 19 tuổi trở lên giữ giấy phép ít nhất 90 ngày."},"tl":{"q":"Sa Utah, gaano katagal dapat hawak ng driver na 19 taong gulang o pataas ang learner permit bago makakuha ng license?","o":["30 araw","90 araw","Anim na buwan","Isang taon"],"h1":"Mas maikli ito kaysa sa oras para sa mga teen, mga tatlong buwan.","h2":"Sa Utah, ang driver na 19 taong gulang o pataas ay dapat humawak ng learner permit nang hindi bababa sa 90 araw, maliban kung natapos nila ang isang aprubadong driver education course.","p":"Tama. Hawak ng mga driver na 19 pataas ang permit nang hindi bababa sa 90 araw."},"ar":{"q":"في Utah، كم مدة يجب أن يحمل السائق الذي عمره 19 سنة أو أكثر تصريح التعلّم قبل الحصول على الرخصة؟","o":["30 يومًا","90 يومًا","ستة أشهر","سنة واحدة"],"h1":"هي أقصر من مدة المراهقين، حوالي ثلاثة أشهر.","h2":"في Utah يجب على السائق الذي عمره 19 سنة أو أكثر أن يحمل تصريح التعلّم 90 يومًا على الأقل، إلا إذا أكمل دورة معتمدة لتعليم القيادة.","p":"صحيح. السائقون في عمر 19 فأكثر يحملون التصريح 90 يومًا على الأقل."},"ref":{"doc":"UT","page":7}},{"id":"ut-007","scope":"UT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Utah, a driver under 18 with a learner permit must have a qualified adult in which seat?","o":["The seat beside the driver","Any back seat","The seat behind the driver","Any seat in the car"],"h1":"The adult must be close enough to help right away.","h2":"In Utah, a learner under 18 may drive only when a parent or guardian, a driving instructor, or a responsible adult who signed for them sits in the seat beside them.","p":"Right. The adult sits in the seat beside the learner."},"es":{"q":"En Utah, un conductor menor de 18 años con permiso de aprendiz debe llevar a un adulto autorizado. ¿En qué asiento?","o":["En el asiento al lado del conductor","En cualquier asiento trasero","En el asiento detrás del conductor","En cualquier asiento del carro"],"h1":"El adulto debe estar lo bastante cerca para ayudar de inmediato.","h2":"En Utah, un aprendiz menor de 18 años solo puede manejar si un padre o tutor, un instructor de manejo o un adulto responsable que firmó por él va sentado a su lado.","p":"Correcto. El adulto va sentado al lado del aprendiz."},"zh":{"q":"在 Utah，未满 18 岁、持有学习驾照的司机开车时，合格的成年人必须坐在哪个座位？","o":["司机旁边的座位","任何后座","司机后面的座位","车里任何座位"],"h1":"这个成年人必须离得够近，可以马上帮忙。","h2":"在 Utah，未满 18 岁的学员只有在父母或监护人、驾驶教练，或为他们签字的负责任成年人坐在旁边座位时，才可以开车。","p":"对。成年人坐在学员旁边的座位。"},"vi":{"q":"Ở Utah, người lái dưới 18 tuổi có giấy phép tập lái phải có một người lớn đủ điều kiện ngồi ở ghế nào?","o":["Ghế bên cạnh người lái","Bất kỳ ghế sau nào","Ghế phía sau người lái","Bất kỳ ghế nào trong xe"],"h1":"Người lớn phải ở đủ gần để giúp ngay lập tức.","h2":"Ở Utah, người tập lái dưới 18 tuổi chỉ được lái khi cha mẹ hoặc người giám hộ, giáo viên dạy lái, hoặc một người lớn có trách nhiệm đã ký cho họ ngồi ở ghế bên cạnh.","p":"Đúng. Người lớn ngồi ở ghế bên cạnh người tập lái."},"tl":{"q":"Sa Utah, ang driver na wala pang 18 na may learner permit ay dapat may kuwalipikadong adult sa aling upuan?","o":["Ang upuan sa tabi ng driver","Kahit anong upuan sa likod","Ang upuan sa likod ng driver","Kahit anong upuan sa sasakyan"],"h1":"Dapat sapat na malapit ang adult para tumulong agad.","h2":"Sa Utah, ang learner na wala pang 18 ay puwedeng magmaneho lamang kapag nakaupo sa tabi niya ang magulang o guardian, isang driving instructor, o isang responsableng adult na pumirma para sa kanya.","p":"Tama. Nakaupo ang adult sa tabi ng learner."},"ar":{"q":"في Utah، السائق الأصغر من 18 سنة الذي يحمل تصريح التعلّم يجب أن يكون معه شخص بالغ مؤهّل في أي مقعد؟","o":["المقعد بجانب السائق","أي مقعد خلفي","المقعد خلف السائق","أي مقعد في السيارة"],"h1":"يجب أن يكون الشخص البالغ قريبًا بما يكفي ليساعد فورًا.","h2":"في Utah لا يجوز للمتعلّم الأصغر من 18 سنة أن يقود إلا إذا جلس بجانبه أحد الوالدين أو الوصي، أو مدرّب قيادة، أو شخص بالغ مسؤول وقّع له.","p":"صحيح. يجلس الشخص البالغ في المقعد بجانب المتعلّم."},"ref":{"doc":"UT","page":6}},{"id":"ut-008","scope":"UT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Utah, during which hours may a young driver with a provisional license not drive, unless an exception applies?","o":["10 p.m. to 5 a.m.","11 p.m. to 6 a.m.","9 p.m. to 6 a.m.","Midnight to 5 a.m."],"h1":"The limit starts at the very start of a new day.","h2":"In Utah, a young provisional license holder may not drive from midnight to 5 a.m., unless with a licensed adult 21 or older in front, going to or from work, for a school activity, for farm work, or in an emergency.","p":"Right. Young provisional drivers stay off the road from midnight to 5 a.m."},"es":{"q":"En Utah, ¿en qué horario no puede manejar un conductor joven con licencia provisional, salvo que aplique una excepción?","o":["De 10 p.m. a 5 a.m.","De 11 p.m. a 6 a.m.","De 9 p.m. a 6 a.m.","De medianoche a 5 a.m."],"h1":"El límite empieza justo al inicio de un nuevo día.","h2":"En Utah, un joven con licencia provisional no puede manejar de medianoche a 5 a.m., salvo con un adulto con licencia de 21 años o más en el asiento delantero, para ir o volver del trabajo, por una actividad escolar, por trabajo agrícola o en una emergencia.","p":"Correcto. Los conductores jóvenes con licencia provisional no manejan de medianoche a 5 a.m."},"zh":{"q":"在 Utah，持有临时驾照（provisional license）的年轻司机，在哪个时间段不可以开车（除非有例外情况）？","o":["晚上 10 点到早上 5 点","晚上 11 点到早上 6 点","晚上 9 点到早上 6 点","午夜 12 点到早上 5 点"],"h1":"这个限制从新的一天刚开始的时候开始。","h2":"在 Utah，年轻的临时驾照持有人从午夜 12 点到早上 5 点不可以开车，除非前座有 21 岁或以上的有驾照成年人、上下班、参加学校活动、做农活，或遇到紧急情况。","p":"对。年轻的临时驾照司机从午夜 12 点到早上 5 点不能上路。"},"vi":{"q":"Ở Utah, người lái trẻ có bằng lái tạm thời (provisional license) không được lái trong khoảng giờ nào, trừ khi có ngoại lệ?","o":["10 giờ tối đến 5 giờ sáng","11 giờ tối đến 6 giờ sáng","9 giờ tối đến 6 giờ sáng","Nửa đêm đến 5 giờ sáng"],"h1":"Giới hạn bắt đầu ngay lúc bắt đầu một ngày mới.","h2":"Ở Utah, người trẻ có bằng lái tạm thời không được lái từ nửa đêm đến 5 giờ sáng, trừ khi có một người lớn có bằng lái từ 21 tuổi trở lên ngồi phía trước, đi làm hoặc đi làm về, cho hoạt động của trường, làm việc nông trại, hoặc trong trường hợp khẩn cấp.","p":"Đúng. Người lái trẻ có bằng tạm thời không lên đường từ nửa đêm đến 5 giờ sáng."},"tl":{"q":"Sa Utah, sa anong mga oras hindi puwedeng magmaneho ang batang driver na may provisional license, maliban kung may exception?","o":["10 p.m. hanggang 5 a.m.","11 p.m. hanggang 6 a.m.","9 p.m. hanggang 6 a.m.","Hatinggabi hanggang 5 a.m."],"h1":"Nagsisimula ang limitasyon sa mismong simula ng bagong araw.","h2":"Sa Utah, ang batang may provisional license ay hindi puwedeng magmaneho mula hatinggabi hanggang 5 a.m., maliban kung may kasamang adult na may license na 21 pataas sa harap, papunta o pauwi galing trabaho, para sa aktibidad ng paaralan, para sa trabaho sa bukid, o sa emergency.","p":"Tama. Hindi nagmamaneho ang mga batang provisional driver mula hatinggabi hanggang 5 a.m."},"ar":{"q":"في Utah، في أي ساعات لا يجوز للسائق الصغير الذي يحمل رخصة مؤقتة (provisional license) أن يقود، إلا في حالة استثناء؟","o":["من 10 مساءً إلى 5 صباحًا","من 11 مساءً إلى 6 صباحًا","من 9 مساءً إلى 6 صباحًا","من منتصف الليل إلى 5 صباحًا"],"h1":"يبدأ المنع في أول لحظة من يوم جديد.","h2":"في Utah لا يجوز لحامل الرخصة المؤقتة الصغير أن يقود من منتصف الليل إلى 5 صباحًا، إلا مع شخص بالغ عمره 21 سنة أو أكثر ويحمل رخصة في المقعد الأمامي، أو في الذهاب إلى العمل أو العودة منه، أو لنشاط مدرسي، أو لعمل في مزرعة، أو في حالة طارئة.","p":"صحيح. السائقون الصغار برخصة مؤقتة لا يقودون من منتصف الليل إلى 5 صباحًا."},"ref":{"doc":"UT","page":8}},{"id":"ut-009","scope":"UT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Utah, for how long after getting a provisional license may a teen carry only immediate family members as passengers, unless an exception applies?","o":["The first month","The first six months","The first year","Until age 21"],"h1":"It is half of a year.","h2":"In Utah, for the first six months with a provisional license, a teen may carry only immediate family members, unless a licensed driver 21 or older is in the front seat, the trip is for farm work, or there is an emergency.","p":"Right. For the first six months, only family members may ride along."},"es":{"q":"En Utah, ¿durante cuánto tiempo después de obtener la licencia provisional puede un joven llevar solo a familiares directos como pasajeros, salvo que aplique una excepción?","o":["El primer mes","Los primeros seis meses","El primer año","Hasta los 21 años"],"h1":"Es la mitad de un año.","h2":"En Utah, durante los primeros seis meses con licencia provisional, un joven puede llevar solo a familiares directos, salvo que vaya un conductor con licencia de 21 años o más en el asiento delantero, el viaje sea por trabajo agrícola o haya una emergencia.","p":"Correcto. Durante los primeros seis meses, solo los familiares pueden ir como pasajeros."},"zh":{"q":"在 Utah，青少年拿到临时驾照后，在多长时间内只能载直系家庭成员作为乘客（除非有例外情况）？","o":["第一个月","前六个月","第一年","到 21 岁为止"],"h1":"是半年。","h2":"在 Utah，拿到临时驾照的前六个月，青少年只能载直系家庭成员，除非前座有 21 岁或以上的有驾照司机、出行是为了农活，或遇到紧急情况。","p":"对。前六个月只有家庭成员可以搭车。"},"vi":{"q":"Ở Utah, sau khi có bằng lái tạm thời, trong bao lâu thiếu niên chỉ được chở người thân trong gia đình trực hệ, trừ khi có ngoại lệ?","o":["Tháng đầu tiên","Sáu tháng đầu","Năm đầu tiên","Cho đến 21 tuổi"],"h1":"Đó là nửa năm.","h2":"Ở Utah, trong sáu tháng đầu có bằng lái tạm thời, thiếu niên chỉ được chở người thân trong gia đình trực hệ, trừ khi có người lái có bằng từ 21 tuổi trở lên ở ghế trước, chuyến đi là để làm việc nông trại, hoặc có trường hợp khẩn cấp.","p":"Đúng. Trong sáu tháng đầu, chỉ người trong gia đình được đi cùng."},"tl":{"q":"Sa Utah, gaano katagal pagkatapos makakuha ng provisional license na ang isang teen ay puwedeng magsakay lamang ng malapit na kapamilya, maliban kung may exception?","o":["Ang unang buwan","Ang unang anim na buwan","Ang unang taon","Hanggang edad 21"],"h1":"Kalahating taon ito.","h2":"Sa Utah, sa unang anim na buwan na may provisional license, ang teen ay puwedeng magsakay lamang ng malapit na kapamilya, maliban kung may driver na may license na 21 pataas sa harap na upuan, ang biyahe ay para sa trabaho sa bukid, o may emergency.","p":"Tama. Sa unang anim na buwan, mga kapamilya lang ang puwedeng sumakay."},"ar":{"q":"في Utah، بعد الحصول على الرخصة المؤقتة، لأي مدة لا يجوز للمراهق أن ينقل إلا أفراد العائلة المباشرين كركّاب، إلا في حالة استثناء؟","o":["الشهر الأول","الأشهر الستة الأولى","السنة الأولى","حتى عمر 21"],"h1":"هي نصف سنة.","h2":"في Utah، في الأشهر الستة الأولى مع الرخصة المؤقتة، لا يجوز للمراهق أن ينقل إلا أفراد العائلة المباشرين، إلا إذا كان في المقعد الأمامي سائق يحمل رخصة وعمره 21 سنة أو أكثر، أو كانت الرحلة لعمل في مزرعة، أو كانت هناك حالة طارئة.","p":"صحيح. في الأشهر الستة الأولى، أفراد العائلة فقط يمكنهم الركوب."},"ref":{"doc":"UT","page":8}},{"id":"ut-010","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, a teen got a provisional license two months ago. When may the teen carry a friend as a passenger?","o":["When the passenger is under 16","When the trip is under 10 miles","When a licensed driver 21 or older is in the front seat","When the teen drives only in daylight"],"h1":"An experienced adult changes the rule.","h2":"In Utah, during the first six months a teen may carry friends only when a licensed driver 21 or older sits in the front seat, or for farm work or an emergency.","p":"Right. A licensed driver 21 or older in front lifts the passenger limit."},"es":{"q":"En Utah, un joven obtuvo la licencia provisional hace dos meses. ¿Cuándo puede llevar a un amigo como pasajero?","o":["Cuando el pasajero es menor de 16 años","Cuando el viaje es de menos de 10 millas","Cuando va un conductor con licencia de 21 años o más en el asiento delantero","Cuando maneja solo de día"],"h1":"Un adulto con experiencia cambia la regla.","h2":"En Utah, durante los primeros seis meses un joven puede llevar amigos solo cuando un conductor con licencia de 21 años o más va en el asiento delantero, o por trabajo agrícola o una emergencia.","p":"Correcto. Un conductor con licencia de 21 años o más adelante quita el límite de pasajeros."},"zh":{"q":"在 Utah，一名青少年两个月前拿到了临时驾照。他什么时候可以载朋友作为乘客？","o":["当乘客未满 16 岁时","当路程少于 10 英里时","当前座有 21 岁或以上的有驾照司机时","当青少年只在白天开车时"],"h1":"有经验的成年人会改变这个规定。","h2":"在 Utah，在前六个月内，青少年只有在前座有 21 岁或以上的有驾照司机时，或为了农活或紧急情况，才可以载朋友。","p":"对。前座有 21 岁或以上的有驾照司机，就可以不受乘客限制。"},"vi":{"q":"Ở Utah, một thiếu niên có bằng lái tạm thời được hai tháng. Khi nào thiếu niên này được chở một người bạn?","o":["Khi người đi cùng dưới 16 tuổi","Khi chuyến đi dưới 10 dặm","Khi có người lái có bằng từ 21 tuổi trở lên ở ghế trước","Khi thiếu niên chỉ lái vào ban ngày"],"h1":"Một người lớn có kinh nghiệm làm thay đổi quy định.","h2":"Ở Utah, trong sáu tháng đầu, thiếu niên chỉ được chở bạn bè khi có người lái có bằng từ 21 tuổi trở lên ngồi ở ghế trước, hoặc để làm việc nông trại hoặc trong trường hợp khẩn cấp.","p":"Đúng. Người lái có bằng từ 21 tuổi trở lên ở phía trước bỏ giới hạn người đi cùng."},"tl":{"q":"Sa Utah, nakakuha ng provisional license ang isang teen dalawang buwan na ang nakaraan. Kailan puwedeng magsakay ang teen ng kaibigan?","o":["Kapag wala pang 16 ang pasahero","Kapag ang biyahe ay wala pang 10 milya","Kapag may driver na may license na 21 pataas sa harap na upuan","Kapag sa araw lang nagmamaneho ang teen"],"h1":"Binabago ng isang may karanasang adult ang patakaran.","h2":"Sa Utah, sa unang anim na buwan, ang teen ay puwedeng magsakay ng mga kaibigan lamang kapag may driver na may license na 21 pataas na nakaupo sa harap na upuan, o para sa trabaho sa bukid o emergency.","p":"Tama. Inaalis ng driver na may license na 21 pataas sa harap ang limitasyon sa pasahero."},"ar":{"q":"في Utah، حصل مراهق على رخصة مؤقتة قبل شهرين. متى يجوز له أن ينقل صديقًا كراكب؟","o":["عندما يكون عمر الراكب أقل من 16 سنة","عندما تكون الرحلة أقل من 10 أميال","عندما يكون في المقعد الأمامي سائق يحمل رخصة وعمره 21 سنة أو أكثر","عندما يقود المراهق في النهار فقط"],"h1":"وجود شخص بالغ له خبرة يغيّر القاعدة.","h2":"في Utah، في الأشهر الستة الأولى، لا يجوز للمراهق أن ينقل أصدقاء إلا إذا جلس في المقعد الأمامي سائق يحمل رخصة وعمره 21 سنة أو أكثر، أو لعمل في مزرعة أو في حالة طارئة.","p":"صحيح. وجود سائق يحمل رخصة وعمره 21 سنة أو أكثر في الأمام يرفع حدّ الركّاب."},"ref":{"doc":"UT","page":8}},{"id":"ut-011","scope":"UT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Utah, what is the rule on talking on a cell phone for drivers under 18?","o":["They may not use a wireless phone to talk while driving","They may talk only with a hands-free device","They may talk only on roads under 45 mph","They may talk if the call is short"],"h1":"For the youngest drivers, the rule is stricter than for adults.","h2":"In Utah, a driver younger than 18 may not use a phone while driving, except in an emergency, to report a hazard or a crime, or to talk with a parent or guardian.","p":"Right. Drivers under 18 may not talk on a phone while driving."},"es":{"q":"En Utah, ¿cuál es la regla sobre hablar por celular para conductores menores de 18 años?","o":["No pueden usar un teléfono inalámbrico para hablar mientras manejan","Pueden hablar solo con manos libres","Pueden hablar solo en calles de menos de 45 mph","Pueden hablar si la llamada es corta"],"h1":"Para los conductores más jóvenes, la regla es más estricta que para los adultos.","h2":"En Utah, un conductor menor de 18 años no puede usar el teléfono mientras maneja, salvo en una emergencia, para reportar un peligro o un delito, o para hablar con su padre, madre o tutor.","p":"Correcto. Los menores de 18 no pueden hablar por teléfono mientras manejan."},"zh":{"q":"在 Utah，对未满 18 岁的司机，开车时打手机通话有什么规定？","o":["开车时不可以用无线电话通话","只可以用免提设备通话","只可以在时速低于 45 mph 的道路上通话","如果通话很短就可以"],"h1":"对最年轻的司机，规定比成年人更严格。","h2":"在 Utah，未满 18 岁的司机开车时不可以使用电话，除非是紧急情况、报告危险或犯罪，或与父母或监护人通话。","p":"对。未满 18 岁的司机开车时不可以打电话。"},"vi":{"q":"Ở Utah, quy định về việc nói chuyện điện thoại di động đối với người lái dưới 18 tuổi là gì?","o":["Họ không được dùng điện thoại không dây để nói chuyện khi lái xe","Họ chỉ được nói chuyện bằng thiết bị rảnh tay","Họ chỉ được nói chuyện trên đường dưới 45 mph","Họ được nói chuyện nếu cuộc gọi ngắn"],"h1":"Với người lái trẻ nhất, quy định nghiêm hơn người lớn.","h2":"Ở Utah, người lái dưới 18 tuổi không được dùng điện thoại khi lái xe, trừ trường hợp khẩn cấp, để báo nguy hiểm hoặc tội phạm, hoặc để nói chuyện với cha mẹ hoặc người giám hộ.","p":"Đúng. Người lái dưới 18 tuổi không được nói chuyện điện thoại khi lái xe."},"tl":{"q":"Sa Utah, ano ang patakaran sa pakikipag-usap sa cell phone para sa mga driver na wala pang 18?","o":["Hindi sila puwedeng gumamit ng wireless phone para makipag-usap habang nagmamaneho","Puwede lang silang makipag-usap gamit ang hands-free device","Puwede lang silang makipag-usap sa mga daan na mababa sa 45 mph","Puwede silang makipag-usap kung maikli ang tawag"],"h1":"Para sa pinakabatang driver, mas mahigpit ang patakaran kaysa sa adult.","h2":"Sa Utah, ang driver na wala pang 18 ay hindi puwedeng gumamit ng phone habang nagmamaneho, maliban sa emergency, para mag-report ng panganib o krimen, o para makipag-usap sa magulang o guardian.","p":"Tama. Hindi puwedeng makipag-usap sa phone habang nagmamaneho ang mga driver na wala pang 18."},"ar":{"q":"في Utah، ما القاعدة في الحديث على الهاتف المحمول للسائقين الأصغر من 18 سنة؟","o":["لا يجوز لهم استخدام هاتف لاسلكي للحديث أثناء القيادة","يجوز لهم الحديث فقط بجهاز بدون استخدام اليدين","يجوز لهم الحديث فقط على طرق سرعتها أقل من 45 mph","يجوز لهم الحديث إذا كانت المكالمة قصيرة"],"h1":"للسائقين الأصغر سنًا، القاعدة أشدّ من قاعدة البالغين.","h2":"في Utah لا يجوز للسائق الأصغر من 18 سنة أن يستخدم الهاتف أثناء القيادة، إلا في حالة طارئة، أو للإبلاغ عن خطر أو جريمة، أو للحديث مع أحد الوالدين أو الوصي.","p":"صحيح. السائقون الأصغر من 18 سنة لا يجوز لهم الحديث على الهاتف أثناء القيادة."},"ref":{"doc":"UT","page":59}},{"id":"ut-012","scope":"UT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Utah, which of these may an adult driver do with a handheld phone while driving?","o":["Write a text message","Read an email","Watch a video","Talk on a call started by voice command"],"h1":"Typing, reading and watching are not allowed.","h2":"In Utah, a driver 18 or older may not type, read, browse or watch video on a handheld phone, but may talk on a call that was started by voice command.","p":"Right. An adult may talk on a call started by voice command."},"es":{"q":"En Utah, ¿cuál de estas cosas puede hacer un conductor adulto con el teléfono en la mano mientras maneja?","o":["Escribir un mensaje de texto","Leer un correo","Ver un video","Hablar en una llamada iniciada con comandos de voz"],"h1":"Escribir, leer y ver videos no está permitido.","h2":"En Utah, un conductor de 18 años o más no puede escribir, leer, navegar ni ver videos en el teléfono en la mano, pero puede hablar en una llamada iniciada con comandos de voz.","p":"Correcto. Un adulto puede hablar en una llamada iniciada con comandos de voz."},"zh":{"q":"在 Utah，成年司机开车时可以用手持电话做下面哪件事？","o":["写短信","读电子邮件","看视频","进行用语音指令拨出的通话"],"h1":"打字、阅读和观看都不可以。","h2":"在 Utah，18 岁或以上的司机不可以在手持电话上打字、阅读、浏览或看视频，但可以进行用语音指令拨出的通话。","p":"对。成年人可以进行用语音指令拨出的通话。"},"vi":{"q":"Ở Utah, người lái trưởng thành được làm điều nào sau đây với điện thoại cầm tay khi lái xe?","o":["Viết tin nhắn","Đọc email","Xem video","Nói chuyện trong cuộc gọi bắt đầu bằng lệnh giọng nói"],"h1":"Gõ chữ, đọc và xem đều không được phép.","h2":"Ở Utah, người lái từ 18 tuổi trở lên không được gõ chữ, đọc, lướt web hoặc xem video trên điện thoại cầm tay, nhưng được nói chuyện trong cuộc gọi bắt đầu bằng lệnh giọng nói.","p":"Đúng. Người lớn được nói chuyện trong cuộc gọi bắt đầu bằng lệnh giọng nói."},"tl":{"q":"Sa Utah, alin sa mga ito ang puwedeng gawin ng adult na driver gamit ang hawak na phone habang nagmamaneho?","o":["Sumulat ng text message","Magbasa ng email","Manood ng video","Makipag-usap sa tawag na sinimulan sa voice command"],"h1":"Hindi puwede ang mag-type, magbasa at manood.","h2":"Sa Utah, ang driver na 18 pataas ay hindi puwedeng mag-type, magbasa, mag-browse o manood ng video sa hawak na phone, pero puwedeng makipag-usap sa tawag na sinimulan sa voice command.","p":"Tama. Puwedeng makipag-usap ang adult sa tawag na sinimulan sa voice command."},"ar":{"q":"في Utah، أيّ من هذه الأشياء يجوز للسائق البالغ أن يفعله بهاتف في يده أثناء القيادة؟","o":["كتابة رسالة نصية","قراءة بريد إلكتروني","مشاهدة فيديو","الحديث في مكالمة بدأت بأمر صوتي"],"h1":"الكتابة والقراءة والمشاهدة غير مسموحة.","h2":"في Utah لا يجوز للسائق الذي عمره 18 سنة أو أكثر أن يكتب أو يقرأ أو يتصفّح أو يشاهد فيديو على هاتف في يده، لكن يجوز له الحديث في مكالمة بدأت بأمر صوتي.","p":"صحيح. يجوز للبالغ الحديث في مكالمة بدأت بأمر صوتي."},"ref":{"doc":"UT","page":59}},{"id":"ut-013","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, at what blood alcohol level can a driver 21 or older be charged with DUI?","o":["0.02 percent or higher","0.08 percent or higher","0.05 percent or higher","0.10 percent or higher"],"h1":"Utah's limit is lower than the one most states use.","h2":"In Utah, a driver 21 or older breaks the DUI law with a blood alcohol level of 0.05 percent or higher.","p":"Right. Utah's adult limit is 0.05 percent."},"es":{"q":"En Utah, ¿con qué nivel de alcohol en la sangre se puede acusar de DUI a un conductor de 21 años o más?","o":["0.02 por ciento o más","0.08 por ciento o más","0.05 por ciento o más","0.10 por ciento o más"],"h1":"El límite de Utah es más bajo que el de la mayoría de los estados.","h2":"En Utah, un conductor de 21 años o más viola la ley de DUI con un nivel de alcohol en la sangre de 0.05 por ciento o más.","p":"Correcto. El límite para adultos en Utah es 0.05 por ciento."},"zh":{"q":"在 Utah，21 岁或以上的司机血液酒精浓度达到多少，就可以被控酒后驾驶（DUI）？","o":["0.02% 或更高","0.08% 或更高","0.05% 或更高","0.10% 或更高"],"h1":"Utah 的标准比大多数州低。","h2":"在 Utah，21 岁或以上的司机血液酒精浓度达到 0.05% 或更高，就违反了酒后驾驶（DUI）法律。","p":"对。Utah 成年人的标准是 0.05%。"},"vi":{"q":"Ở Utah, người lái từ 21 tuổi trở lên có thể bị buộc tội lái xe khi say (DUI) ở nồng độ cồn trong máu bao nhiêu?","o":["0.02 phần trăm trở lên","0.08 phần trăm trở lên","0.05 phần trăm trở lên","0.10 phần trăm trở lên"],"h1":"Giới hạn của Utah thấp hơn giới hạn mà hầu hết các tiểu bang dùng.","h2":"Ở Utah, người lái từ 21 tuổi trở lên vi phạm luật DUI khi nồng độ cồn trong máu từ 0.05 phần trăm trở lên.","p":"Đúng. Giới hạn cho người lớn ở Utah là 0.05 phần trăm."},"tl":{"q":"Sa Utah, sa anong antas ng alak sa dugo puwedeng kasuhan ng DUI ang driver na 21 pataas?","o":["0.02 porsiyento o higit pa","0.08 porsiyento o higit pa","0.05 porsiyento o higit pa","0.10 porsiyento o higit pa"],"h1":"Mas mababa ang limitasyon ng Utah kaysa sa ginagamit ng karamihan ng estado.","h2":"Sa Utah, nilalabag ng driver na 21 pataas ang batas sa DUI kapag ang antas ng alak sa dugo ay 0.05 porsiyento o higit pa.","p":"Tama. Ang limitasyon para sa adult sa Utah ay 0.05 porsiyento."},"ar":{"q":"في Utah، عند أي نسبة كحول في الدم يمكن اتهام السائق الذي عمره 21 سنة أو أكثر بالقيادة تحت تأثير الكحول (DUI)؟","o":["0.02 بالمئة أو أكثر","0.08 بالمئة أو أكثر","0.05 بالمئة أو أكثر","0.10 بالمئة أو أكثر"],"h1":"حدّ Utah أقل من الحدّ الذي تستخدمه معظم الولايات.","h2":"في Utah يخالف السائق الذي عمره 21 سنة أو أكثر قانون القيادة تحت تأثير الكحول (DUI) عندما تكون نسبة الكحول في دمه 0.05 بالمئة أو أكثر.","p":"صحيح. حدّ البالغين في Utah هو 0.05 بالمئة."},"ref":{"doc":"UT","page":52}},{"id":"ut-014","scope":"UT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Utah, how does the adult blood alcohol limit compare with most other states?","o":["It is the same 0.08 percent","It is lower, at 0.05 percent","It is higher, at 0.10 percent","Utah has no fixed limit"],"h1":"Utah changed its law in 2018.","h2":"Utah lowered its adult limit from 0.08 to 0.05 percent in 2018, which made it the lowest limit in the country at the time.","p":"Right. Utah's 0.05 percent limit is lower than most states."},"es":{"q":"En Utah, ¿cómo se compara el límite de alcohol para adultos con el de la mayoría de los estados?","o":["Es el mismo, 0.08 por ciento","Es más bajo, 0.05 por ciento","Es más alto, 0.10 por ciento","Utah no tiene un límite fijo"],"h1":"Utah cambió su ley en 2018.","h2":"Utah bajó su límite para adultos de 0.08 a 0.05 por ciento en 2018, y así tuvo el límite más bajo del país en ese momento.","p":"Correcto. El límite de 0.05 por ciento de Utah es más bajo que en la mayoría de los estados."},"zh":{"q":"在 Utah，成年人的血液酒精浓度标准和大多数其他州相比怎么样？","o":["一样是 0.08%","更低，是 0.05%","更高，是 0.10%","Utah 没有固定标准"],"h1":"Utah 在 2018 年修改了法律。","h2":"Utah 在 2018 年把成年人的标准从 0.08% 降到 0.05%，这在当时是全国最低的标准。","p":"对。Utah 的 0.05% 标准比大多数州低。"},"vi":{"q":"Ở Utah, giới hạn nồng độ cồn trong máu cho người lớn so với hầu hết các tiểu bang khác thì thế nào?","o":["Giống nhau, 0.08 phần trăm","Thấp hơn, 0.05 phần trăm","Cao hơn, 0.10 phần trăm","Utah không có giới hạn cố định"],"h1":"Utah đã thay đổi luật vào năm 2018.","h2":"Năm 2018, Utah hạ giới hạn cho người lớn từ 0.08 xuống 0.05 phần trăm, khiến đó là giới hạn thấp nhất cả nước vào thời điểm đó.","p":"Đúng. Giới hạn 0.05 phần trăm của Utah thấp hơn hầu hết các tiểu bang."},"tl":{"q":"Sa Utah, paano maihahambing ang limitasyon ng alak sa dugo para sa adult sa karamihan ng ibang estado?","o":["Pareho ito, 0.08 porsiyento","Mas mababa ito, 0.05 porsiyento","Mas mataas ito, 0.10 porsiyento","Walang tiyak na limitasyon ang Utah"],"h1":"Binago ng Utah ang batas nito noong 2018.","h2":"Ibinaba ng Utah ang limitasyon para sa adult mula 0.08 hanggang 0.05 porsiyento noong 2018, kaya ito ang naging pinakamababang limitasyon sa bansa noong panahong iyon.","p":"Tama. Mas mababa ang 0.05 porsiyento na limitasyon ng Utah kaysa sa karamihan ng estado."},"ar":{"q":"في Utah، كيف يُقارَن حدّ الكحول في الدم للبالغين مع معظم الولايات الأخرى؟","o":["هو نفسه 0.08 بالمئة","هو أقل، 0.05 بالمئة","هو أعلى، 0.10 بالمئة","ليس في Utah حدّ ثابت"],"h1":"غيّرت Utah قانونها في سنة 2018.","h2":"خفّضت Utah حدّ البالغين من 0.08 إلى 0.05 بالمئة في سنة 2018، وكان هذا أقل حدّ في البلد في ذلك الوقت.","p":"صحيح. حدّ Utah وهو 0.05 بالمئة أقل من معظم الولايات."},"ref":{"doc":"UT","page":52}},{"id":"ut-015","scope":"UT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Utah, how much alcohol may a driver under 21 have in their body while driving?","o":["None at all","Up to 0.02 percent","Up to 0.05 percent","Up to 0.08 percent"],"h1":"Utah calls this rule \"not a drop.\"","h2":"Utah does not allow a driver under 21 to drive with any measurable alcohol in their body.","p":"Right. Under 21, the limit is not a drop."},"es":{"q":"En Utah, ¿cuánto alcohol puede tener en el cuerpo un conductor menor de 21 años mientras maneja?","o":["Nada en absoluto","Hasta 0.02 por ciento","Hasta 0.05 por ciento","Hasta 0.08 por ciento"],"h1":"En Utah esta regla se conoce como \"ni una gota\".","h2":"Utah no permite que un conductor menor de 21 años maneje con alcohol medible en el cuerpo.","p":"Correcto. Para menores de 21, el límite es ni una gota."},"zh":{"q":"在 Utah，未满 21 岁的司机开车时，体内可以有多少酒精？","o":["完全不可以有","最多 0.02%","最多 0.05%","最多 0.08%"],"h1":"Utah 把这条规定叫做“一滴都不行”（not a drop）。","h2":"Utah 不允许未满 21 岁的司机在体内有任何可测出的酒精时开车。","p":"对。未满 21 岁，一滴都不行。"},"vi":{"q":"Ở Utah, người lái dưới 21 tuổi được có bao nhiêu cồn trong cơ thể khi lái xe?","o":["Hoàn toàn không có","Tối đa 0.02 phần trăm","Tối đa 0.05 phần trăm","Tối đa 0.08 phần trăm"],"h1":"Utah gọi quy định này là \"không một giọt\" (not a drop).","h2":"Utah không cho phép người lái dưới 21 tuổi lái xe khi có bất kỳ lượng cồn đo được nào trong cơ thể.","p":"Đúng. Dưới 21 tuổi, giới hạn là không một giọt."},"tl":{"q":"Sa Utah, gaano karaming alak ang puwedeng nasa katawan ng driver na wala pang 21 habang nagmamaneho?","o":["Wala talaga","Hanggang 0.02 porsiyento","Hanggang 0.05 porsiyento","Hanggang 0.08 porsiyento"],"h1":"Tinatawag ng Utah ang patakarang ito na \"kahit isang patak, hindi\" (not a drop).","h2":"Hindi pinapayagan ng Utah ang driver na wala pang 21 na magmaneho nang may kahit anong nasusukat na alak sa katawan.","p":"Tama. Kapag wala pang 21, kahit isang patak ay hindi puwede."},"ar":{"q":"في Utah، كم من الكحول يجوز أن يكون في جسم السائق الأصغر من 21 سنة أثناء القيادة؟","o":["لا شيء أبدًا","حتى 0.02 بالمئة","حتى 0.05 بالمئة","حتى 0.08 بالمئة"],"h1":"تسمّي Utah هذه القاعدة \"ولا قطرة\" (not a drop).","h2":"لا تسمح Utah للسائق الأصغر من 21 سنة بالقيادة مع أي كمية كحول يمكن قياسها في جسمه.","p":"صحيح. تحت 21 سنة، الحدّ هو ولا قطرة."},"ref":{"doc":"UT","page":52}},{"id":"ut-016","scope":"UT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Utah, what is the highest speed limit posted on some rural interstate stretches?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"It is higher than in most states.","h2":"Utah allows speed limits up to 80 mph on some rural interstate highways, where signs show it.","p":"Right. Some rural Utah interstates allow 80 mph."},"es":{"q":"En Utah, ¿cuál es el límite de velocidad más alto en algunos tramos rurales de interestatales?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Es más alto que en la mayoría de los estados.","h2":"Utah permite límites de hasta 80 mph en algunas carreteras interestatales rurales, donde las señales lo indican.","p":"Correcto. Algunas interestatales rurales de Utah permiten 80 mph."},"zh":{"q":"在 Utah，一些乡村州际公路路段上标示的最高限速是多少？","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"比大多数州都高。","h2":"Utah 在一些乡村州际公路上允许最高 80 mph 的限速，以路标标示为准。","p":"对。Utah 一些乡村州际公路允许 80 mph。"},"vi":{"q":"Ở Utah, tốc độ tối đa cao nhất được ghi trên biển ở một số đoạn xa lộ liên tiểu bang vùng nông thôn là bao nhiêu?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Nó cao hơn so với hầu hết các tiểu bang.","h2":"Utah cho phép tốc độ tối đa đến 80 mph trên một số xa lộ liên tiểu bang vùng nông thôn, nơi có biển báo ghi rõ.","p":"Đúng. Một số xa lộ liên tiểu bang vùng nông thôn ở Utah cho phép 80 mph."},"tl":{"q":"Sa Utah, ano ang pinakamataas na speed limit na nakapaskil sa ilang bahagi ng rural interstate?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Mas mataas ito kaysa sa karamihan ng estado.","h2":"Pinapayagan ng Utah ang speed limit hanggang 80 mph sa ilang rural interstate highway, kung saan ito ipinapakita ng mga sign.","p":"Tama. Pinapayagan ang 80 mph sa ilang rural interstate sa Utah."},"ar":{"q":"في Utah، ما أعلى حدّ للسرعة مكتوب على بعض أجزاء الطرق السريعة بين الولايات (interstate) في المناطق الريفية؟","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"هو أعلى من معظم الولايات.","h2":"تسمح Utah بحدّ سرعة يصل إلى 80 mph على بعض الطرق السريعة بين الولايات في المناطق الريفية، حيث تُظهر اللافتات ذلك.","p":"صحيح. بعض الطرق السريعة الريفية في Utah تسمح بـ 80 mph."},"ref":{"doc":"UT","page":44}},{"id":"ut-017","scope":"UT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Utah, when should you drive in the left lane of a multi-lane highway?","o":["Whenever you drive at the speed limit","Whenever traffic is light","To pass slower vehicles, then move back right","Whenever you plan to exit soon"],"h1":"The left lane is not a lane to stay in.","h2":"In Utah, the left lane of a multi-lane road is for passing slower vehicles, and you must move right when someone comes up behind you.","p":"Right. Use the left lane to pass, then move back right."},"es":{"q":"En Utah, ¿cuándo debe usar el carril izquierdo de una carretera de varios carriles?","o":["Siempre que maneje al límite de velocidad","Siempre que haya poco tráfico","Para rebasar a vehículos más lentos y luego volver a la derecha","Siempre que piense salir pronto"],"h1":"El carril izquierdo no es un carril para quedarse.","h2":"En Utah, el carril izquierdo de una carretera de varios carriles es para rebasar a vehículos más lentos, y usted debe pasarse a la derecha cuando alguien se acerca por detrás.","p":"Correcto. Use el carril izquierdo para rebasar y luego vuelva a la derecha."},"zh":{"q":"在 Utah，在多车道公路上，你什么时候应该在左车道行驶？","o":["只要你按限速行驶的时候","只要车流量少的时候","超过较慢的车辆时，然后回到右边","只要你打算很快下高速的时候"],"h1":"左车道不是用来一直待着的车道。","h2":"在 Utah，多车道道路的左车道是用来超过较慢车辆的，有人从后面靠近时，你必须移到右边。","p":"对。用左车道超车，然后回到右边。"},"vi":{"q":"Ở Utah, khi nào bạn nên lái ở làn bên trái của xa lộ nhiều làn?","o":["Bất cứ khi nào bạn lái đúng tốc độ tối đa","Bất cứ khi nào xe ít","Để vượt xe chậm hơn, rồi trở lại bên phải","Bất cứ khi nào bạn sắp ra khỏi xa lộ"],"h1":"Làn bên trái không phải là làn để ở lại.","h2":"Ở Utah, làn bên trái của đường nhiều làn là để vượt xe chậm hơn, và bạn phải sang phải khi có xe đến gần phía sau bạn.","p":"Đúng. Dùng làn bên trái để vượt, rồi trở lại bên phải."},"tl":{"q":"Sa Utah, kailan ka dapat magmaneho sa kaliwang lane ng highway na maraming lane?","o":["Tuwing nagmamaneho ka sa speed limit","Tuwing kaunti ang trapiko","Para lampasan ang mas mabagal na sasakyan, saka bumalik sa kanan","Tuwing malapit ka nang lumabas"],"h1":"Hindi lane na tinitirhan ang kaliwang lane.","h2":"Sa Utah, ang kaliwang lane ng daan na maraming lane ay para sa paglampas sa mas mabagal na sasakyan, at dapat kang lumipat sa kanan kapag may dumarating sa likod mo.","p":"Tama. Gamitin ang kaliwang lane para lumampas, saka bumalik sa kanan."},"ar":{"q":"في Utah، متى يجب أن تقود في الحارة اليسرى من طريق سريع متعدد الحارات؟","o":["كلما كنت تقود بحدّ السرعة","كلما كانت حركة المرور خفيفة","لتجاوز المركبات الأبطأ، ثم العودة إلى اليمين","كلما كنت تنوي الخروج قريبًا"],"h1":"الحارة اليسرى ليست حارة للبقاء فيها.","h2":"في Utah، الحارة اليسرى في الطريق متعدد الحارات هي لتجاوز المركبات الأبطأ، ويجب أن تنتقل إلى اليمين عندما تقترب منك سيارة من الخلف.","p":"صحيح. استخدم الحارة اليسرى للتجاوز، ثم عُد إلى اليمين."},"ref":{"doc":"UT","page":34}},{"id":"ut-018","scope":"UT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Utah, which stopped vehicles does the move-over law cover?","o":["Only police cars with red and blue lights","Any stopped vehicle by the road with flashing lights, including hazard lights","Only ambulances carrying a patient","Only cars parked in a legal parking area"],"h1":"It is not only for police and emergency vehicles.","h2":"Utah's move-over law covers any vehicle stopped by the road with flashing lights, including a car with its hazard lights on, unless it is in a legal parking area.","p":"Right. The law covers any stopped vehicle with flashing lights, even hazard lights."},"es":{"q":"En Utah, ¿qué vehículos detenidos cubre la ley de moverse de carril?","o":["Solo patrullas con luces rojas y azules","Cualquier vehículo detenido junto a la carretera con luces intermitentes, incluso luces de emergencia","Solo ambulancias que llevan a un paciente","Solo carros estacionados en un lugar legal"],"h1":"No es solo para la policía y los vehículos de emergencia.","h2":"La ley de Utah de moverse de carril cubre cualquier vehículo detenido junto a la carretera con luces intermitentes, incluso un carro con las luces de emergencia encendidas, salvo que esté en un lugar legal de estacionamiento.","p":"Correcto. La ley cubre cualquier vehículo detenido con luces intermitentes, incluso luces de emergencia."},"zh":{"q":"在 Utah，让道法（move-over law）适用于哪些停着的车辆？","o":["只有亮红蓝灯的警车","路边任何亮着闪光灯的停着的车辆，包括亮着危险警示灯的车","只有载着病人的救护车","只有停在合法停车区的车"],"h1":"它不只适用于警车和紧急车辆。","h2":"Utah 的让道法适用于路边任何亮着闪光灯的停着的车辆，包括亮着危险警示灯的汽车，除非它停在合法停车区。","p":"对。这条法律适用于任何亮着闪光灯的停着的车辆，即使是危险警示灯。"},"vi":{"q":"Ở Utah, luật nhường làn (move-over law) áp dụng cho những xe đang dừng nào?","o":["Chỉ xe cảnh sát có đèn đỏ và xanh","Bất kỳ xe nào dừng bên đường có đèn nhấp nháy, kể cả đèn báo nguy hiểm","Chỉ xe cứu thương đang chở bệnh nhân","Chỉ xe đậu trong khu vực đậu xe hợp pháp"],"h1":"Nó không chỉ dành cho xe cảnh sát và xe cấp cứu.","h2":"Luật nhường làn của Utah áp dụng cho bất kỳ xe nào dừng bên đường có đèn nhấp nháy, kể cả xe bật đèn báo nguy hiểm, trừ khi xe ở trong khu vực đậu xe hợp pháp.","p":"Đúng. Luật áp dụng cho bất kỳ xe đang dừng nào có đèn nhấp nháy, kể cả đèn báo nguy hiểm."},"tl":{"q":"Sa Utah, aling nakahintong sasakyan ang sakop ng move-over law?","o":["Mga sasakyan lang ng pulis na may pula at asul na ilaw","Kahit anong sasakyang nakahinto sa tabi ng daan na may kumikislap na ilaw, kasama ang hazard lights","Mga ambulansiya lang na may sakay na pasyente","Mga sasakyan lang na nakaparada sa legal na paradahan"],"h1":"Hindi lang ito para sa pulis at emergency vehicle.","h2":"Sakop ng move-over law ng Utah ang kahit anong sasakyang nakahinto sa tabi ng daan na may kumikislap na ilaw, kasama ang sasakyang naka-on ang hazard lights, maliban kung nasa legal na paradahan ito.","p":"Tama. Sakop ng batas ang kahit anong nakahintong sasakyan na may kumikislap na ilaw, kahit hazard lights."},"ar":{"q":"في Utah، ما المركبات المتوقفة التي يشملها قانون الابتعاد (move-over law)؟","o":["سيارات الشرطة ذات الأضواء الحمراء والزرقاء فقط","أي مركبة متوقفة بجانب الطريق لها أضواء وامضة، ومنها أضواء التحذير (hazard lights)","سيارات الإسعاف التي تنقل مريضًا فقط","السيارات المتوقفة في مكان وقوف قانوني فقط"],"h1":"ليس فقط للشرطة ومركبات الطوارئ.","h2":"قانون الابتعاد في Utah يشمل أي مركبة متوقفة بجانب الطريق لها أضواء وامضة، ومنها سيارة أضواء التحذير فيها مُشغَّلة، إلا إذا كانت في مكان وقوف قانوني.","p":"صحيح. القانون يشمل أي مركبة متوقفة لها أضواء وامضة، حتى أضواء التحذير."},"ref":{"doc":"UT","page":77}},{"id":"ut-019","scope":"UT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Utah, you cannot safely move over a lane for a stopped tow truck with flashing amber lights. What must you do?","o":["Slow down and leave as much space as you can","Keep your speed and pass quickly","Stop in your lane until it leaves","Flash your headlights and pass"],"h1":"If you cannot add a lane, add space and reduce speed.","h2":"Under Utah's move-over law, if you cannot safely change lanes, you must slow down and give the stopped vehicle as much space as you can.","p":"Right. Slow down and give as much space as possible."},"es":{"q":"En Utah, usted no puede cambiarse de carril con seguridad ante una grúa detenida con luces ámbar intermitentes. ¿Qué debe hacer?","o":["Reducir la velocidad y dejar todo el espacio que pueda","Mantener la velocidad y pasar rápido","Detenerse en su carril hasta que se vaya","Hacer cambio de luces y pasar"],"h1":"Si no puede cambiar de carril, deje espacio y reduzca la velocidad.","h2":"Según la ley de Utah, si usted no puede cambiarse de carril con seguridad, debe reducir la velocidad y dejar al vehículo detenido todo el espacio que pueda.","p":"Correcto. Reduzca la velocidad y deje todo el espacio posible."},"zh":{"q":"在 Utah，你无法安全地为一辆亮着琥珀色闪光灯的停着的拖车让出一条车道。你必须怎么做？","o":["减速，并尽量留出空间","保持速度，快速通过","停在你的车道上，直到它离开","闪一下大灯然后通过"],"h1":"如果不能让出一条车道，就留出空间并减速。","h2":"根据 Utah 的让道法，如果你不能安全换道，你必须减速，并尽量给停着的车辆留出空间。","p":"对。减速，并尽量留出空间。"},"vi":{"q":"Ở Utah, bạn không thể sang làn khác một cách an toàn để nhường một xe kéo đang dừng có đèn vàng hổ phách nhấp nháy. Bạn phải làm gì?","o":["Giảm tốc độ và chừa khoảng cách càng nhiều càng tốt","Giữ tốc độ và vượt nhanh","Dừng trong làn của bạn cho đến khi xe đó đi","Nháy đèn pha và vượt qua"],"h1":"Nếu không thể sang làn, hãy chừa thêm khoảng cách và giảm tốc độ.","h2":"Theo luật nhường làn của Utah, nếu bạn không thể đổi làn một cách an toàn, bạn phải giảm tốc độ và chừa cho xe đang dừng khoảng cách càng nhiều càng tốt.","p":"Đúng. Giảm tốc độ và chừa khoảng cách càng nhiều càng tốt."},"tl":{"q":"Sa Utah, hindi ka ligtas na makakalipat ng lane para sa nakahintong tow truck na may kumikislap na amber na ilaw. Ano ang dapat mong gawin?","o":["Bumagal at mag-iwan ng pinakamaraming espasyo na kaya mo","Panatilihin ang bilis at lumampas nang mabilis","Huminto sa lane mo hanggang umalis ito","I-flash ang headlights at lumampas"],"h1":"Kung hindi ka makalipat ng lane, magdagdag ng espasyo at bawasan ang bilis.","h2":"Ayon sa move-over law ng Utah, kung hindi ka ligtas na makakalipat ng lane, dapat kang bumagal at bigyan ang nakahintong sasakyan ng pinakamaraming espasyo na kaya mo.","p":"Tama. Bumagal at magbigay ng pinakamaraming espasyo hangga't maaari."},"ar":{"q":"في Utah، لا يمكنك أن تنتقل بأمان إلى حارة أخرى من أجل شاحنة سحب متوقفة لها أضواء وامضة كهرمانية. ماذا يجب أن تفعل؟","o":["خفّف السرعة واترك أكبر مسافة ممكنة","حافظ على سرعتك وتجاوز بسرعة","توقّف في حارتك حتى تغادر","أومض بالأضواء الأمامية وتجاوز"],"h1":"إذا لم تستطع أن تترك حارة، فاترك مسافة وخفّف السرعة.","h2":"بحسب قانون الابتعاد في Utah، إذا لم تستطع تغيير الحارة بأمان، يجب أن تخفّف السرعة وتترك للمركبة المتوقفة أكبر مسافة ممكنة.","p":"صحيح. خفّف السرعة واترك أكبر مسافة ممكنة."},"ref":{"doc":"UT","page":77}},{"id":"ut-020","scope":"UT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Utah, what must a driver do after being convicted of breaking the move-over law?","o":["Pay a $25 fine only","Retake the driving skills test","Take a four-hour live defensive driving class within 90 days","Lose your license for one year"],"h1":"It is a class you attend in person.","h2":"In Utah, a driver convicted of breaking the move-over law must take a four-hour live defensive driving class within 90 days, or the license is suspended for 90 days.","p":"Right. The driver must take a four-hour defensive driving class within 90 days."},"es":{"q":"En Utah, ¿qué debe hacer un conductor declarado culpable de no cumplir la ley de moverse de carril?","o":["Pagar solo una multa de $25","Volver a tomar el examen práctico de manejo","Tomar una clase presencial de manejo defensivo de cuatro horas dentro de 90 días","Perder la licencia por un año"],"h1":"Es una clase a la que se asiste en persona.","h2":"En Utah, un conductor declarado culpable de no cumplir la ley de moverse de carril debe tomar una clase presencial de manejo defensivo de cuatro horas dentro de 90 días, o su licencia se suspende por 90 días.","p":"Correcto. El conductor debe tomar una clase de manejo defensivo de cuatro horas dentro de 90 días."},"zh":{"q":"在 Utah，司机因违反让道法被定罪后，必须做什么？","o":["只需支付 $25 罚款","重新参加驾驶技能考试","在 90 天内参加四小时的现场防御性驾驶课","驾照被吊销一年"],"h1":"这是一门要亲自去上的课。","h2":"在 Utah，因违反让道法被定罪的司机必须在 90 天内参加四小时的现场防御性驾驶课，否则驾照会被暂停 90 天。","p":"对。司机必须在 90 天内参加四小时的防御性驾驶课。"},"vi":{"q":"Ở Utah, người lái bị kết tội vi phạm luật nhường làn phải làm gì?","o":["Chỉ trả tiền phạt $25","Thi lại bài thi kỹ năng lái xe","Học một lớp lái xe phòng thủ trực tiếp bốn giờ trong vòng 90 ngày","Bị mất bằng lái một năm"],"h1":"Đó là một lớp học bạn phải đến tham dự trực tiếp.","h2":"Ở Utah, người lái bị kết tội vi phạm luật nhường làn phải học một lớp lái xe phòng thủ trực tiếp bốn giờ trong vòng 90 ngày, nếu không bằng lái sẽ bị đình chỉ 90 ngày.","p":"Đúng. Người lái phải học một lớp lái xe phòng thủ bốn giờ trong vòng 90 ngày."},"tl":{"q":"Sa Utah, ano ang dapat gawin ng driver pagkatapos mahatulang lumabag sa move-over law?","o":["Magbayad lang ng $25 na multa","Ulitin ang driving skills test","Kumuha ng apat na oras na live na defensive driving class sa loob ng 90 araw","Mawalan ng license nang isang taon"],"h1":"Isa itong klase na personal mong pupuntahan.","h2":"Sa Utah, ang driver na nahatulang lumabag sa move-over law ay dapat kumuha ng apat na oras na live na defensive driving class sa loob ng 90 araw, o masususpinde ang license nang 90 araw.","p":"Tama. Dapat kumuha ang driver ng apat na oras na defensive driving class sa loob ng 90 araw."},"ar":{"q":"في Utah، ماذا يجب أن يفعل السائق بعد إدانته بمخالفة قانون الابتعاد؟","o":["دفع غرامة $25 فقط","إعادة اختبار مهارات القيادة","حضور درس مباشر في القيادة الوقائية مدته أربع ساعات خلال 90 يومًا","فقدان الرخصة لمدة سنة"],"h1":"هو درس تحضره بنفسك.","h2":"في Utah، السائق المُدان بمخالفة قانون الابتعاد يجب أن يحضر درسًا مباشرًا في القيادة الوقائية مدته أربع ساعات خلال 90 يومًا، وإلا تُوقَف رخصته لمدة 90 يومًا.","p":"صحيح. يجب أن يحضر السائق درسًا في القيادة الوقائية مدته أربع ساعات خلال 90 يومًا."},"ref":{"doc":"UT","page":77}},{"id":"ut-021","scope":"UT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Utah, you are on a divided highway with four or more lanes and a median. A school bus stops on the other side with red lights flashing. What must you do?","o":["Stop until the lights turn off","Stop, then pass at 10 mph","You do not need to stop, but stay alert","Honk and keep your speed"],"h1":"A median separates you from the bus and the children.","h2":"In Utah, on a divided highway with four or more lanes and a median, drivers coming toward a stopped school bus do not need to stop, but drivers behind the bus must stop.","p":"Right. On a divided highway, oncoming traffic does not need to stop."},"es":{"q":"En Utah, usted va por una carretera dividida de cuatro carriles o más con franja central. Un autobús escolar se detiene del otro lado con las luces rojas intermitentes. ¿Qué debe hacer?","o":["Detenerse hasta que se apaguen las luces","Detenerse y luego pasar a 10 mph","No necesita detenerse, pero debe estar atento","Tocar la bocina y mantener la velocidad"],"h1":"Una franja central lo separa del autobús y de los niños.","h2":"En Utah, en una carretera dividida de cuatro carriles o más con franja central, los conductores que vienen de frente a un autobús escolar detenido no necesitan detenerse, pero los que van detrás del autobús sí deben detenerse.","p":"Correcto. En una carretera dividida, el tráfico que viene de frente no necesita detenerse."},"zh":{"q":"在 Utah，你在一条有四条或以上车道和中间分隔带的分隔公路上。一辆校车在对面停下，红灯在闪。你必须怎么做？","o":["停车，直到灯熄灭","停车，然后以 10 mph 通过","你不需要停车，但要保持警觉","按喇叭并保持速度"],"h1":"中间分隔带把你和校车及孩子们隔开。","h2":"在 Utah，在有四条或以上车道和中间分隔带的分隔公路上，迎面驶向停着的校车的司机不需要停车，但在校车后面的司机必须停车。","p":"对。在分隔公路上，对向车辆不需要停车。"},"vi":{"q":"Ở Utah, bạn đang ở trên xa lộ có dải phân cách với bốn làn trở lên. Một xe buýt trường học dừng ở phía bên kia với đèn đỏ nhấp nháy. Bạn phải làm gì?","o":["Dừng cho đến khi đèn tắt","Dừng, rồi vượt qua với tốc độ 10 mph","Bạn không cần dừng, nhưng hãy chú ý","Bấm còi và giữ tốc độ"],"h1":"Dải phân cách tách bạn khỏi xe buýt và các em học sinh.","h2":"Ở Utah, trên xa lộ có dải phân cách với bốn làn trở lên, người lái đi ngược chiều về phía xe buýt trường học đang dừng không cần dừng, nhưng người lái phía sau xe buýt phải dừng.","p":"Đúng. Trên xa lộ có dải phân cách, xe đi ngược chiều không cần dừng."},"tl":{"q":"Sa Utah, nasa divided highway ka na may apat o higit pang lane at median. Huminto ang school bus sa kabilang panig na kumikislap ang pulang ilaw. Ano ang dapat mong gawin?","o":["Huminto hanggang mamatay ang mga ilaw","Huminto, saka lumampas sa 10 mph","Hindi mo kailangang huminto, pero manatiling alerto","Bumusina at panatilihin ang bilis"],"h1":"Inihihiwalay ka ng median sa bus at sa mga bata.","h2":"Sa Utah, sa divided highway na may apat o higit pang lane at median, ang mga driver na papalapit mula sa kabilang direksiyon sa nakahintong school bus ay hindi kailangang huminto, pero ang mga driver sa likod ng bus ay dapat huminto.","p":"Tama. Sa divided highway, hindi kailangang huminto ang trapiko sa kabilang direksiyon."},"ar":{"q":"في Utah، أنت على طريق سريع مقسوم فيه أربع حارات أو أكثر وفاصل في الوسط. توقفت حافلة مدرسية على الجهة الأخرى وأضواؤها الحمراء تومض. ماذا يجب أن تفعل؟","o":["توقّف حتى تنطفئ الأضواء","توقّف، ثم تجاوز بسرعة 10 mph","لا تحتاج أن تتوقف، لكن ابقَ منتبهًا","استخدم البوق وحافظ على سرعتك"],"h1":"الفاصل في الوسط يفصلك عن الحافلة والأطفال.","h2":"في Utah، على الطريق السريع المقسوم الذي فيه أربع حارات أو أكثر وفاصل في الوسط، السائقون القادمون من الاتجاه المقابل نحو حافلة مدرسية متوقفة لا يحتاجون أن يتوقفوا، لكن السائقين خلف الحافلة يجب أن يتوقفوا.","p":"صحيح. على الطريق المقسوم، السير في الاتجاه المقابل لا يحتاج أن يتوقف."},"ref":{"doc":"UT","page":36}},{"id":"ut-022","scope":"UT","cat":"signals","sign":null,"c":1,"en":{"q":"In Utah, when is a left turn on a red light allowed after a full stop?","o":["From any street onto a two-way street","From a one-way street onto another one-way street","Only when a police officer is present","Never, under any condition"],"h1":"Both streets must carry traffic in only one direction.","h2":"In Utah, you may turn left on red after a full stop only where two one-way streets meet, when it is safe and no sign forbids it.","p":"Right. Left on red is allowed only from one one-way street onto another."},"es":{"q":"En Utah, ¿cuándo se permite girar a la izquierda con luz roja después de detenerse por completo?","o":["Desde cualquier calle hacia una calle de doble sentido","Desde una calle de un solo sentido hacia otra de un solo sentido","Solo cuando hay un policía presente","Nunca, en ningún caso"],"h1":"Las dos calles deben tener tráfico en un solo sentido.","h2":"En Utah, usted puede girar a la izquierda con luz roja después de detenerse por completo solo donde se cruzan dos calles de un solo sentido, si es seguro y ninguna señal lo prohíbe.","p":"Correcto. Girar a la izquierda en rojo se permite solo de una calle de un solo sentido a otra."},"zh":{"q":"在 Utah，什么时候可以在完全停车后红灯左转？","o":["从任何街道转入双向街道","从单行道转入另一条单行道","只有在有警察在场时","在任何情况下都不可以"],"h1":"两条街道都必须只有一个方向的车流。","h2":"在 Utah，只有在两条单行道相交的地方，在安全且没有标志禁止时，你才可以在完全停车后红灯左转。","p":"对。只有从一条单行道转入另一条单行道时，才可以红灯左转。"},"vi":{"q":"Ở Utah, khi nào được rẽ trái khi đèn đỏ sau khi dừng hẳn?","o":["Từ bất kỳ đường nào vào đường hai chiều","Từ đường một chiều vào một đường một chiều khác","Chỉ khi có cảnh sát ở đó","Không bao giờ, trong bất kỳ trường hợp nào"],"h1":"Cả hai con đường đều phải chỉ có xe chạy một chiều.","h2":"Ở Utah, bạn chỉ được rẽ trái khi đèn đỏ sau khi dừng hẳn ở nơi hai đường một chiều gặp nhau, khi an toàn và không có biển cấm.","p":"Đúng. Rẽ trái khi đèn đỏ chỉ được phép từ một đường một chiều vào một đường một chiều khác."},"tl":{"q":"Sa Utah, kailan pinapayagan ang pagliko sa kaliwa sa pulang ilaw pagkatapos ng buong paghinto?","o":["Mula sa kahit anong kalye papunta sa two-way na kalye","Mula sa one-way na kalye papunta sa isa pang one-way na kalye","Kapag may pulis lang","Hindi kailanman, sa anumang kondisyon"],"h1":"Dapat iisang direksiyon lang ang trapiko sa parehong kalye.","h2":"Sa Utah, puwede kang lumiko sa kaliwa sa pulang ilaw pagkatapos ng buong paghinto lamang kung saan nagtatagpo ang dalawang one-way na kalye, kapag ligtas at walang sign na nagbabawal.","p":"Tama. Ang kaliwa sa pula ay pinapayagan lamang mula sa isang one-way na kalye papunta sa isa pa."},"ar":{"q":"في Utah، متى يُسمح بالانعطاف يسارًا عند الإشارة الحمراء بعد التوقف الكامل؟","o":["من أي شارع إلى شارع باتجاهين","من شارع باتجاه واحد إلى شارع آخر باتجاه واحد","فقط عندما يكون شرطي موجودًا","أبدًا، في أي حالة"],"h1":"يجب أن يكون السير في الشارعين باتجاه واحد فقط.","h2":"في Utah يجوز لك الانعطاف يسارًا عند الإشارة الحمراء بعد التوقف الكامل فقط حيث يلتقي شارعان باتجاه واحد، عندما يكون ذلك آمنًا ولا توجد لافتة تمنعه.","p":"صحيح. الانعطاف يسارًا عند الأحمر مسموح فقط من شارع باتجاه واحد إلى شارع آخر باتجاه واحد."},"ref":{"doc":"UT","page":null}},{"id":"ut-023","scope":"UT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Utah, what is the minimum liability insurance for policies issued since January 1, 2025?","o":["$30,000 / $65,000 / $25,000","$25,000 / $50,000 / $25,000","$25,000 / $65,000 / $15,000","$15,000 / $30,000 / $10,000"],"h1":"Utah raised its limits in 2025; the middle number is $65,000.","h2":"Since January 1, 2025, Utah requires at least $30,000 for injury to one person, $65,000 for injuries in one crash, and $25,000 for property damage.","p":"Right. The Utah minimum is now 30, 65 and 25 thousand dollars."},"es":{"q":"En Utah, ¿cuál es el seguro mínimo de responsabilidad civil para pólizas emitidas desde el 1 de enero de 2025?","o":["$30,000 / $65,000 / $25,000","$25,000 / $50,000 / $25,000","$25,000 / $65,000 / $15,000","$15,000 / $30,000 / $10,000"],"h1":"Utah subió sus límites en 2025; el número del medio es $65,000.","h2":"Desde el 1 de enero de 2025, Utah exige por lo menos $30,000 por lesiones a una persona, $65,000 por lesiones en un choque y $25,000 por daños a la propiedad.","p":"Correcto. El mínimo en Utah ahora es de 30, 65 y 25 mil dólares."},"zh":{"q":"在 Utah，2025 年 1 月 1 日以后签发的保单，最低责任保险是多少？","o":["$30,000 / $65,000 / $25,000","$25,000 / $50,000 / $25,000","$25,000 / $65,000 / $15,000","$15,000 / $30,000 / $10,000"],"h1":"Utah 在 2025 年提高了标准；中间的数字是 $65,000。","h2":"从 2025 年 1 月 1 日起，Utah 要求至少：一个人受伤 $30,000，一次事故多人受伤 $65,000，财产损失 $25,000。","p":"对。Utah 现在的最低标准是 3 万、6 万 5 千和 2 万 5 千美元。"},"vi":{"q":"Ở Utah, bảo hiểm trách nhiệm tối thiểu cho các hợp đồng được cấp từ ngày 1 tháng 1 năm 2025 là bao nhiêu?","o":["$30,000 / $65,000 / $25,000","$25,000 / $50,000 / $25,000","$25,000 / $65,000 / $15,000","$15,000 / $30,000 / $10,000"],"h1":"Utah đã tăng mức tối thiểu vào năm 2025; số ở giữa là $65,000.","h2":"Từ ngày 1 tháng 1 năm 2025, Utah yêu cầu ít nhất $30,000 cho thương tích của một người, $65,000 cho thương tích trong một vụ tai nạn, và $25,000 cho thiệt hại tài sản.","p":"Đúng. Mức tối thiểu ở Utah bây giờ là 30, 65 và 25 nghìn đô la."},"tl":{"q":"Sa Utah, ano ang minimum na liability insurance para sa mga policy na inilabas mula Enero 1, 2025?","o":["$30,000 / $65,000 / $25,000","$25,000 / $50,000 / $25,000","$25,000 / $65,000 / $15,000","$15,000 / $30,000 / $10,000"],"h1":"Itinaas ng Utah ang mga limitasyon noong 2025; $65,000 ang gitnang numero.","h2":"Mula Enero 1, 2025, kailangan ng Utah ang hindi bababa sa $30,000 para sa pinsala sa isang tao, $65,000 para sa mga pinsala sa isang aksidente, at $25,000 para sa pinsala sa ari-arian.","p":"Tama. Ang minimum sa Utah ngayon ay 30, 65 at 25 libong dolyar."},"ar":{"q":"في Utah، ما الحدّ الأدنى لتأمين المسؤولية للوثائق الصادرة منذ 1 يناير 2025؟","o":["$30,000 / $65,000 / $25,000","$25,000 / $50,000 / $25,000","$25,000 / $65,000 / $15,000","$15,000 / $30,000 / $10,000"],"h1":"رفعت Utah حدودها في سنة 2025؛ الرقم الأوسط هو $65,000.","h2":"منذ 1 يناير 2025 تطلب Utah على الأقل $30,000 لإصابة شخص واحد، و$65,000 للإصابات في حادث واحد، و$25,000 لأضرار الممتلكات.","p":"صحيح. الحدّ الأدنى في Utah الآن هو 30 و65 و25 ألف دولار."},"ref":{"doc":"UT","page":null}},{"id":"ut-024","scope":"UT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Utah, besides liability, what minimum personal injury protection must a driver carry?","o":["$500","$1,000","$10,000","$3,000"],"h1":"Utah is a no-fault state, and this amount is a few thousand dollars.","h2":"Utah is a no-fault state, so drivers must also carry at least $3,000 of personal injury protection to pay their own medical costs after a crash.","p":"Right. Utah requires $3,000 of personal injury protection."},"es":{"q":"En Utah, además de la responsabilidad civil, ¿qué protección mínima contra lesiones personales debe tener un conductor?","o":["$500","$1,000","$10,000","$3,000"],"h1":"Utah es un estado sin culpa, y esta cantidad es de unos miles de dólares.","h2":"Utah es un estado sin culpa, así que los conductores también deben tener por lo menos $3,000 de protección contra lesiones personales para pagar sus propios gastos médicos después de un choque.","p":"Correcto. Utah exige $3,000 de protección contra lesiones personales."},"zh":{"q":"在 Utah，除了责任保险以外，司机还必须买多少最低的个人伤害保障（personal injury protection）？","o":["$500","$1,000","$10,000","$3,000"],"h1":"Utah 是无过失（no-fault）州，这个金额是几千美元。","h2":"Utah 是无过失（no-fault）州，所以司机还必须买至少 $3,000 的个人伤害保障（personal injury protection），用来支付自己在事故后的医疗费用。","p":"对。Utah 要求 $3,000 的个人伤害保障。"},"vi":{"q":"Ở Utah, ngoài bảo hiểm trách nhiệm, người lái phải có mức bảo vệ thương tích cá nhân (personal injury protection) tối thiểu là bao nhiêu?","o":["$500","$1,000","$10,000","$3,000"],"h1":"Utah là tiểu bang không lỗi (no-fault), và số tiền này là vài nghìn đô la.","h2":"Utah là tiểu bang không lỗi (no-fault), nên người lái cũng phải có ít nhất $3,000 bảo vệ thương tích cá nhân (personal injury protection) để trả chi phí y tế của chính mình sau tai nạn.","p":"Đúng. Utah yêu cầu $3,000 bảo vệ thương tích cá nhân."},"tl":{"q":"Sa Utah, bukod sa liability, anong minimum na personal injury protection ang dapat mayroon ang driver?","o":["$500","$1,000","$10,000","$3,000"],"h1":"Isang no-fault state ang Utah, at ilang libong dolyar ang halagang ito.","h2":"Isang no-fault state ang Utah, kaya dapat ding may hindi bababa sa $3,000 na personal injury protection ang mga driver para bayaran ang sarili nilang gastos sa pagpapagamot pagkatapos ng aksidente.","p":"Tama. Kailangan ng Utah ang $3,000 na personal injury protection."},"ar":{"q":"في Utah، بالإضافة إلى تأمين المسؤولية، ما الحدّ الأدنى لتأمين الحماية من الإصابة الشخصية (personal injury protection) الذي يجب أن يكون لدى السائق؟","o":["$500","$1,000","$10,000","$3,000"],"h1":"Utah ولاية بدون خطأ (no-fault)، وهذا المبلغ بضعة آلاف من الدولارات.","h2":"Utah ولاية بدون خطأ (no-fault)، لذلك يجب أن يكون لدى السائقين أيضًا $3,000 على الأقل من الحماية من الإصابة الشخصية (personal injury protection) لدفع تكاليفهم الطبية بعد الحادث.","p":"صحيح. تطلب Utah مبلغ $3,000 للحماية من الإصابة الشخصية."},"ref":{"doc":"UT","page":null}},{"id":"ut-025","scope":"UT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Utah, how many questions are on the written knowledge test for a person who has never had a license?","o":["20 questions","25 questions","50 questions","100 questions"],"h1":"Drivers who had a license before take a shorter test.","h2":"In Utah, a person who has never been licensed takes a 50-question knowledge test, while a previously licensed driver takes a 25-question test.","p":"Right. New drivers answer 50 questions."},"es":{"q":"En Utah, ¿cuántas preguntas tiene el examen escrito para una persona que nunca ha tenido licencia?","o":["20 preguntas","25 preguntas","50 preguntas","100 preguntas"],"h1":"Quienes ya tuvieron licencia hacen un examen más corto.","h2":"En Utah, una persona que nunca ha tenido licencia hace un examen de 50 preguntas, mientras que quien ya tuvo licencia hace un examen de 25 preguntas.","p":"Correcto. Los conductores nuevos responden 50 preguntas."},"zh":{"q":"在 Utah，从来没有拿过驾照的人，笔试有多少道题？","o":["20 道题","25 道题","50 道题","100 道题"],"h1":"以前有过驾照的司机考的题目更少。","h2":"在 Utah，从来没有拿过驾照的人要考 50 道题的笔试，以前有过驾照的司机考 25 道题。","p":"对。新司机要回答 50 道题。"},"vi":{"q":"Ở Utah, bài thi kiến thức viết có bao nhiêu câu hỏi cho người chưa bao giờ có bằng lái?","o":["20 câu hỏi","25 câu hỏi","50 câu hỏi","100 câu hỏi"],"h1":"Người đã từng có bằng lái làm bài thi ngắn hơn.","h2":"Ở Utah, người chưa bao giờ có bằng lái làm bài thi kiến thức 50 câu, còn người đã từng có bằng lái làm bài thi 25 câu.","p":"Đúng. Người lái mới trả lời 50 câu hỏi."},"tl":{"q":"Sa Utah, ilang tanong ang nasa written knowledge test para sa taong hindi pa nagkaroon ng license?","o":["20 tanong","25 tanong","50 tanong","100 tanong"],"h1":"Mas maikling test ang kinukuha ng mga driver na nagkaroon na ng license dati.","h2":"Sa Utah, ang taong hindi pa nagkaroon ng license ay kumukuha ng knowledge test na may 50 tanong, habang ang driver na nagkaroon na ng license dati ay kumukuha ng test na may 25 tanong.","p":"Tama. Sinasagot ng mga bagong driver ang 50 tanong."},"ar":{"q":"في Utah، كم سؤالًا في الاختبار النظري المكتوب للشخص الذي لم تكن لديه رخصة أبدًا؟","o":["20 سؤالًا","25 سؤالًا","50 سؤالًا","100 سؤال"],"h1":"السائقون الذين كانت لديهم رخصة من قبل يأخذون اختبارًا أقصر.","h2":"في Utah، الشخص الذي لم تكن لديه رخصة أبدًا يأخذ اختبارًا نظريًا فيه 50 سؤالًا، أما السائق الذي كانت لديه رخصة من قبل فيأخذ اختبارًا فيه 25 سؤالًا.","p":"صحيح. السائقون الجدد يجيبون عن 50 سؤالًا."},"ref":{"doc":"UT","page":null}},{"id":"ut-026","scope":"UT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Utah, what score do you need to pass the written knowledge test?","o":["70 percent","80 percent","75 percent","90 percent"],"h1":"It is the same passing score many states use.","h2":"Utah requires you to answer at least 80 percent of the knowledge test questions correctly, which is 40 out of 50.","p":"Right. You need 80 percent to pass."},"es":{"q":"En Utah, ¿qué puntaje necesita para aprobar el examen escrito?","o":["70 por ciento","80 por ciento","75 por ciento","90 por ciento"],"h1":"Es el mismo puntaje que usan muchos estados para aprobar.","h2":"Utah exige que usted conteste bien por lo menos el 80 por ciento de las preguntas del examen, es decir, 40 de 50.","p":"Correcto. Necesita 80 por ciento para aprobar."},"zh":{"q":"在 Utah，笔试需要多少分才能通过？","o":["70%","80%","75%","90%"],"h1":"和很多州的及格分数一样。","h2":"Utah 要求你答对至少 80% 的笔试题目，也就是 50 道题中答对 40 道。","p":"对。你需要 80% 才能通过。"},"vi":{"q":"Ở Utah, bạn cần bao nhiêu điểm để đậu bài thi kiến thức viết?","o":["70 phần trăm","80 phần trăm","75 phần trăm","90 phần trăm"],"h1":"Đó là điểm đậu giống nhiều tiểu bang khác.","h2":"Utah yêu cầu bạn trả lời đúng ít nhất 80 phần trăm câu hỏi của bài thi kiến thức, tức là 40 trên 50 câu.","p":"Đúng. Bạn cần 80 phần trăm để đậu."},"tl":{"q":"Sa Utah, anong score ang kailangan mo para pumasa sa written knowledge test?","o":["70 porsiyento","80 porsiyento","75 porsiyento","90 porsiyento"],"h1":"Ito ang parehong passing score na ginagamit ng maraming estado.","h2":"Kailangan ng Utah na masagot mo nang tama ang hindi bababa sa 80 porsiyento ng mga tanong sa knowledge test, ibig sabihin 40 sa 50.","p":"Tama. Kailangan mo ng 80 porsiyento para pumasa."},"ar":{"q":"في Utah، ما الدرجة التي تحتاجها للنجاح في الاختبار النظري المكتوب؟","o":["70 بالمئة","80 بالمئة","75 بالمئة","90 بالمئة"],"h1":"هي نفس درجة النجاح التي تستخدمها ولايات كثيرة.","h2":"تطلب Utah أن تجيب إجابة صحيحة عن 80 بالمئة على الأقل من أسئلة الاختبار النظري، أي 40 من 50.","p":"صحيح. تحتاج 80 بالمئة للنجاح."},"ref":{"doc":"UT","page":23}},{"id":"ut-027","scope":"UT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Utah, how close to a fire hydrant may you park?","o":["Up to 5 feet away","Up to 10 feet away","No closer than 15 feet","No closer than 30 feet"],"h1":"Firefighters need room to reach the hydrant.","h2":"In Utah, you may not park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a fire hydrant."},"es":{"q":"En Utah, ¿a qué distancia de un hidrante puede estacionarse?","o":["Hasta 5 pies de distancia","Hasta 10 pies de distancia","No más cerca de 15 pies","No más cerca de 30 pies"],"h1":"Los bomberos necesitan espacio para llegar al hidrante.","h2":"En Utah, usted no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese por lo menos a 15 pies de un hidrante."},"zh":{"q":"在 Utah，你可以把车停在离消防栓多近的地方？","o":["最近 5 英尺","最近 10 英尺","不能少于 15 英尺","不能少于 30 英尺"],"h1":"消防员需要空间才能接到消防栓。","h2":"在 Utah，你不能把车停在离消防栓 15 英尺以内的地方。","p":"对。要离消防栓至少 15 英尺。"},"vi":{"q":"Ở Utah, bạn được đậu xe gần trụ nước cứu hỏa đến mức nào?","o":["Cách tối đa 5 feet","Cách tối đa 10 feet","Không gần hơn 15 feet","Không gần hơn 30 feet"],"h1":"Lính cứu hỏa cần chỗ trống để đến được trụ nước.","h2":"Ở Utah, bạn không được đậu xe trong vòng 15 feet tính từ trụ nước cứu hỏa.","p":"Đúng. Hãy đậu xe cách trụ nước cứu hỏa ít nhất 15 feet."},"tl":{"q":"Sa Utah, gaano kalapit sa fire hydrant ka puwedeng mag-park?","o":["Hanggang 5 feet ang layo","Hanggang 10 feet ang layo","Hindi lalapit sa 15 feet","Hindi lalapit sa 30 feet"],"h1":"Kailangan ng mga bumbero ng espasyo para maabot ang hydrant.","h2":"Sa Utah, hindi ka puwedeng mag-park sa loob ng 15 feet mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 15 feet mula sa fire hydrant."},"ar":{"q":"في Utah، إلى أي مدى يمكنك أن تركن قرب حنفية إطفاء الحريق؟","o":["حتى 5 feet بعيدًا","حتى 10 feet بعيدًا","ليس أقرب من 15 feet","ليس أقرب من 30 feet"],"h1":"يحتاج رجال الإطفاء إلى مساحة للوصول إلى الحنفية.","h2":"في Utah لا يجوز لك أن تركن على مسافة أقل من 15 feet من حنفية إطفاء الحريق.","p":"صحيح. ابقَ على بُعد 15 feet على الأقل من حنفية إطفاء الحريق."},"ref":{"doc":"UT","page":32}},{"id":"ut-028","scope":"UT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Utah, how much space must you leave when you pass a bicyclist?","o":["At least 3 feet","At least 1 foot","At least 10 feet","Any space is fine if you honk"],"h1":"Utah law sets a minimum distance for passing people on bikes.","h2":"In Utah, the law requires you to leave at least three feet between your vehicle and a bicyclist you are passing.","p":"Right. Give a bicyclist at least 3 feet."},"es":{"q":"En Utah, ¿cuánto espacio debe dejar al rebasar a un ciclista?","o":["Por lo menos 3 pies","Por lo menos 1 pie","Por lo menos 10 pies","Cualquier espacio si toca la bocina"],"h1":"La ley de Utah fija una distancia mínima para rebasar a personas en bicicleta.","h2":"En Utah, la ley exige que deje por lo menos tres pies entre su vehículo y el ciclista que rebasa.","p":"Correcto. Deje por lo menos 3 pies al ciclista."},"zh":{"q":"在 Utah，超过骑自行车的人时，你必须留出多大的空间？","o":["至少 3 英尺","至少 1 英尺","至少 10 英尺","只要按喇叭，多少空间都可以"],"h1":"Utah 法律规定了超过骑车人时的最小距离。","h2":"在 Utah，法律要求你超过骑自行车的人时，你的车和骑车人之间至少要留 3 英尺。","p":"对。要给骑自行车的人留至少 3 英尺。"},"vi":{"q":"Ở Utah, bạn phải chừa khoảng cách bao nhiêu khi vượt người đi xe đạp?","o":["Ít nhất 3 feet","Ít nhất 1 foot","Ít nhất 10 feet","Khoảng cách nào cũng được nếu bạn bấm còi"],"h1":"Luật Utah đặt ra khoảng cách tối thiểu khi vượt người đi xe đạp.","h2":"Ở Utah, luật bắt buộc bạn chừa ít nhất 3 feet giữa xe của bạn và người đi xe đạp mà bạn đang vượt.","p":"Đúng. Hãy chừa cho người đi xe đạp ít nhất 3 feet."},"tl":{"q":"Sa Utah, gaano kalaking espasyo ang dapat mong iwan kapag nilalampasan mo ang nagbibisikleta?","o":["Hindi bababa sa 3 feet","Hindi bababa sa 1 foot","Hindi bababa sa 10 feet","Ayos lang ang kahit anong espasyo kung bubusina ka"],"h1":"May itinakdang pinakamaliit na layo ang batas ng Utah sa paglampas sa mga nagbibisikleta.","h2":"Sa Utah, iniuutos ng batas na mag-iwan ka ng hindi bababa sa 3 feet sa pagitan ng sasakyan mo at ng nagbibisikletang nilalampasan mo.","p":"Tama. Bigyan ang nagbibisikleta ng hindi bababa sa 3 feet."},"ar":{"q":"في Utah، ما المسافة التي يجب أن تتركها عندما تتجاوز راكب دراجة هوائية؟","o":["3 feet على الأقل","1 foot على الأقل","10 feet على الأقل","أي مسافة مقبولة إذا استخدمت البوق"],"h1":"قانون Utah يحدد مسافة دنيا عند تجاوز راكبي الدراجات.","h2":"في Utah يُلزمك القانون بأن تترك 3 feet على الأقل بين سيارتك وراكب الدراجة الذي تتجاوزه.","p":"صحيح. اترك لراكب الدراجة 3 feet على الأقل."},"ref":{"doc":"UT","page":75}},{"id":"ut-029","scope":"UT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Utah, when may a motorcycle rider pass between cars in the same lane (lane filtering)?","o":["At any speed on the freeway","Only on an on-ramp","Whenever traffic is moving slowly","When the cars are stopped and the speed limit is 45 mph or less"],"h1":"The cars being passed must not be moving.","h2":"In Utah, a motorcycle may filter between lanes only past vehicles that are stopped, at 15 mph or less, on a road with two or more lanes going the same way and a speed limit of 45 mph or less, or on an off-ramp, and never on an on-ramp.","p":"Right. Only past stopped cars, at 15 mph or less, on roads of 45 mph or less."},"es":{"q":"En Utah, ¿cuándo puede un motociclista pasar entre autos en el mismo carril (lane filtering)?","o":["A cualquier velocidad en la autopista","Solo en una rampa de entrada","Siempre que el tráfico avance despacio","Cuando los autos están detenidos y el límite es de 45 mph o menos"],"h1":"Los autos que rebasa no deben estar en movimiento.","h2":"En Utah, una motocicleta puede pasar entre carriles (lane filtering) solo junto a vehículos detenidos, a 15 mph o menos, en una vía con dos o más carriles en el mismo sentido y un límite de 45 mph o menos, o en una rampa de salida, y nunca en una rampa de entrada.","p":"Correcto. Solo junto a autos detenidos, a 15 mph o menos, en vías de 45 mph o menos."},"zh":{"q":"在 Utah，骑摩托车的人什么时候可以在同一车道的车辆之间穿行（lane filtering）？","o":["在高速公路上任何速度都可以","只在高速公路入口匝道上","只要车流走得慢就可以","当车辆停着，而且限速是 45 mph 或以下时"],"h1":"被超过的车辆必须是停着不动的。","h2":"在 Utah，摩托车只能从停着的车辆旁边穿行，速度要在 15 mph 或以下，道路要有两条或更多同方向车道且限速 45 mph 或以下，或者在出口匝道上，绝不能在入口匝道上。","p":"对。只能从停着的车旁边穿行，速度 15 mph 或以下，在限速 45 mph 或以下的道路上。"},"vi":{"q":"Ở Utah, khi nào người lái xe máy được chạy len giữa các xe trong cùng làn (lane filtering)?","o":["Ở bất kỳ tốc độ nào trên xa lộ","Chỉ trên đường dẫn vào xa lộ","Bất cứ khi nào xe cộ chạy chậm","Khi các xe đang dừng và tốc độ giới hạn là 45 mph hoặc thấp hơn"],"h1":"Các xe được vượt phải đang đứng yên.","h2":"Ở Utah, xe máy chỉ được chạy len qua các xe đang dừng, ở tốc độ 15 mph hoặc thấp hơn, trên đường có hai làn trở lên cùng chiều và tốc độ giới hạn 45 mph hoặc thấp hơn, hoặc trên đường dẫn ra khỏi xa lộ, và không bao giờ trên đường dẫn vào xa lộ.","p":"Đúng. Chỉ qua các xe đang dừng, ở 15 mph hoặc thấp hơn, trên đường 45 mph hoặc thấp hơn."},"tl":{"q":"Sa Utah, kailan puwedeng sumingit ang nagmomotorsiklo sa pagitan ng mga kotse sa iisang lane (lane filtering)?","o":["Sa kahit anong bilis sa freeway","Sa on-ramp lang","Tuwing mabagal ang takbo ng trapiko","Kapag nakahinto ang mga kotse at 45 mph o mas mababa ang speed limit"],"h1":"Hindi dapat gumagalaw ang mga kotseng nilalampasan.","h2":"Sa Utah, puwede lang sumingit ang motorsiklo sa mga sasakyang nakahinto, sa bilis na 15 mph o mas mababa, sa daan na may dalawa o higit pang lane na pareho ang direksyon at may speed limit na 45 mph o mas mababa, o sa off-ramp, at hindi kailanman sa on-ramp.","p":"Tama. Sa mga nakahintong kotse lang, sa 15 mph o mas mababa, sa mga daang 45 mph o mas mababa."},"ar":{"q":"في Utah، متى يجوز لسائق الدراجة النارية أن يمرّ بين السيارات في المسار نفسه (lane filtering)؟","o":["بأي سرعة على الطريق السريع","فقط على منحدر الدخول إلى الطريق السريع","كلما كانت حركة السير بطيئة","عندما تكون السيارات متوقفة وحد السرعة 45 mph أو أقل"],"h1":"يجب ألا تكون السيارات التي يمرّ بجانبها متحركة.","h2":"في Utah يجوز للدراجة النارية أن تمرّ بين المسارات فقط بجانب سيارات متوقفة، بسرعة 15 mph أو أقل، على طريق فيه مساران أو أكثر في الاتجاه نفسه وحد سرعته 45 mph أو أقل، أو على منحدر الخروج، ولا يجوز ذلك أبدًا على منحدر الدخول.","p":"صحيح. فقط بجانب سيارات متوقفة، بسرعة 15 mph أو أقل، على طرق حد سرعتها 45 mph أو أقل."},"ref":{"doc":"UT","page":82}},{"id":"ut-030","scope":"UT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Utah, which children must ride in an approved child safety seat?","o":["Only babies under 1 year","Children 8 and under, unless they are 57 inches tall","Children under 4 only","Children under 12 riding in front"],"h1":"The rule uses an age and a height.","h2":"In Utah, all children aged eight and under must be secured in an approved child safety seat unless they are 57 inches tall.","p":"Right. Age 8 and under, unless 57 inches tall."},"es":{"q":"En Utah, ¿qué niños deben ir en un asiento de seguridad aprobado?","o":["Solo los bebés menores de 1 año","Los niños de 8 años o menos, salvo que midan 57 pulgadas","Solo los menores de 4 años","Los menores de 12 años que van adelante"],"h1":"La regla usa una edad y una estatura.","h2":"En Utah, todos los niños de ocho años o menos deben ir sujetos en un asiento de seguridad aprobado, salvo que midan 57 pulgadas.","p":"Correcto. Ocho años o menos, salvo que midan 57 pulgadas."},"zh":{"q":"在 Utah，哪些孩子必须坐在合格的儿童安全座椅里？","o":["只有 1 岁以下的婴儿","8 岁及以下的孩子，除非身高达到 57 英寸","只有 4 岁以下的孩子","坐在前排的 12 岁以下孩子"],"h1":"这条规定用的是年龄和身高。","h2":"在 Utah，所有 8 岁及以下的孩子都必须坐在合格的儿童安全座椅里并固定好，除非身高达到 57 英寸。","p":"对。8 岁及以下，除非身高 57 英寸。"},"vi":{"q":"Ở Utah, những trẻ em nào phải ngồi ghế an toàn cho trẻ em được chấp thuận?","o":["Chỉ em bé dưới 1 tuổi","Trẻ từ 8 tuổi trở xuống, trừ khi cao 57 inches","Chỉ trẻ dưới 4 tuổi","Trẻ dưới 12 tuổi ngồi ghế trước"],"h1":"Quy định này dùng cả tuổi và chiều cao.","h2":"Ở Utah, mọi trẻ em từ 8 tuổi trở xuống phải được cài chặt trong ghế an toàn cho trẻ em được chấp thuận, trừ khi trẻ cao 57 inches.","p":"Đúng. Từ 8 tuổi trở xuống, trừ khi cao 57 inches."},"tl":{"q":"Sa Utah, aling mga bata ang dapat nakaupo sa aprubadong child safety seat?","o":["Mga sanggol lang na wala pang 1 taon","Mga batang 8 taong gulang pababa, maliban kung 57 inches ang taas nila","Mga batang wala pang 4 taon lang","Mga batang wala pang 12 taon na nakaupo sa harap"],"h1":"Gumagamit ang patakaran ng edad at taas.","h2":"Sa Utah, lahat ng batang 8 taong gulang pababa ay dapat nakakabit sa aprubadong child safety seat, maliban kung 57 inches ang taas nila.","p":"Tama. 8 taong gulang pababa, maliban kung 57 inches ang taas."},"ar":{"q":"في Utah، أي الأطفال يجب أن يجلسوا في مقعد أمان معتمد للأطفال؟","o":["الرُّضّع تحت عمر سنة واحدة فقط","الأطفال بعمر 8 سنوات وأقل، إلا إذا كان طولهم 57 inches","الأطفال تحت 4 سنوات فقط","الأطفال تحت 12 سنة الذين يجلسون في الأمام"],"h1":"القاعدة تستخدم العمر والطول.","h2":"في Utah يجب تثبيت جميع الأطفال بعمر 8 سنوات وأقل في مقعد أمان معتمد للأطفال، إلا إذا كان طولهم 57 inches.","p":"صحيح. بعمر 8 سنوات وأقل، إلا إذا كان الطول 57 inches."},"ref":{"doc":"UT","page":28}},{"id":"ut-031","scope":"UT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Utah, when you renew a regular driver license, for how long is the new license good?","o":["Two years","Four years","Eight years","For life"],"h1":"It is longer than in many states.","h2":"In Utah, a renewed regular driver license expires on your birthday eight years after it is issued.","p":"Right. A renewed license lasts eight years."},"es":{"q":"En Utah, cuando renueva una licencia de conducir regular, ¿por cuánto tiempo es válida la nueva licencia?","o":["Dos años","Cuatro años","Ocho años","De por vida"],"h1":"Es más tiempo que en muchos estados.","h2":"En Utah, una licencia regular renovada vence en su cumpleaños ocho años después de emitida.","p":"Correcto. Una licencia renovada dura ocho años."},"zh":{"q":"在 Utah，换发普通驾照后，新驾照的有效期是多久？","o":["两年","四年","八年","终身有效"],"h1":"它比很多州的有效期都长。","h2":"在 Utah，换发的普通驾照在签发八年后你生日那天到期。","p":"对。换发的驾照有效八年。"},"vi":{"q":"Ở Utah, khi bạn gia hạn bằng lái thường, bằng lái mới có giá trị trong bao lâu?","o":["Hai năm","Bốn năm","Tám năm","Suốt đời"],"h1":"Thời hạn này dài hơn ở nhiều tiểu bang khác.","h2":"Ở Utah, bằng lái thường được gia hạn sẽ hết hạn vào ngày sinh nhật của bạn tám năm sau khi được cấp.","p":"Đúng. Bằng lái được gia hạn có giá trị tám năm."},"tl":{"q":"Sa Utah, kapag nag-renew ka ng regular na driver license, gaano katagal valid ang bagong license?","o":["Dalawang taon","Apat na taon","Walong taon","Habambuhay"],"h1":"Mas mahaba ito kaysa sa maraming estado.","h2":"Sa Utah, ang na-renew na regular na driver license ay mag-e-expire sa kaarawan mo walong taon matapos itong ibigay.","p":"Tama. Walong taon ang bisa ng na-renew na license."},"ar":{"q":"في Utah، عندما تجدّد رخصة القيادة العادية، كم مدة صلاحية الرخصة الجديدة؟","o":["سنتان","أربع سنوات","ثماني سنوات","مدى الحياة"],"h1":"هي أطول مما في كثير من الولايات.","h2":"في Utah تنتهي رخصة القيادة العادية المجدّدة في يوم عيد ميلادك بعد ثماني سنوات من إصدارها.","p":"صحيح. الرخصة المجدّدة صالحة لثماني سنوات."},"ref":{"doc":"UT","page":18}},{"id":"va-001","scope":"VA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Virginia, what is the youngest age to get a learner's permit?","o":["14 years old","15 years old","15 years and 6 months","16 years old"],"h1":"It is halfway between two birthdays.","h2":"In Virginia you can get a learner's permit when you are at least 15 years and 6 months old.","p":"Right. The Virginia permit starts at 15 and a half."},"es":{"q":"En Virginia, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["14 años","15 años","15 años y 6 meses","16 años"],"h1":"Está a mitad de camino entre dos cumpleaños.","h2":"En Virginia usted puede obtener un permiso de aprendiz cuando tiene por lo menos 15 años y 6 meses.","p":"Correcto. El permiso en Virginia empieza a los 15 años y medio."},"zh":{"q":"在 Virginia，最小几岁可以拿到学习驾照（learner's permit）？","o":["14 岁","15 岁","15 岁 6 个月","16 岁"],"h1":"它在两个生日的正中间。","h2":"在 Virginia，你至少 15 岁 6 个月时就可以拿到学习驾照。","p":"对。Virginia 的学习驾照从 15 岁半开始。"},"vi":{"q":"Ở Virginia, tuổi nhỏ nhất để lấy giấy phép tập lái (learner's permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","15 tuổi 6 tháng","16 tuổi"],"h1":"Đó là khoảng giữa hai ngày sinh nhật.","h2":"Ở Virginia, bạn có thể lấy giấy phép tập lái khi được ít nhất 15 tuổi 6 tháng.","p":"Đúng. Ở Virginia, giấy phép tập lái bắt đầu từ 15 tuổi rưỡi."},"tl":{"q":"Sa Virginia, ano ang pinakabatang edad para makakuha ng learner's permit?","o":["14 taong gulang","15 taong gulang","15 taon at 6 na buwan","16 taong gulang"],"h1":"Nasa gitna ito ng dalawang kaarawan.","h2":"Sa Virginia, puwede kang kumuha ng learner's permit kapag ikaw ay hindi bababa sa 15 taon at 6 na buwang gulang.","p":"Tama. Nagsisimula ang permit sa Virginia sa 15 at kalahati."},"ar":{"q":"في Virginia، ما أصغر عمر للحصول على تصريح التعلّم (learner's permit)؟","o":["14 سنة","15 سنة","15 سنة و6 أشهر","16 سنة"],"h1":"هو في منتصف المسافة بين عيدَي ميلاد.","h2":"في Virginia يمكنك الحصول على تصريح التعلّم عندما يكون عمرك 15 سنة و6 أشهر على الأقل.","p":"صحيح. في Virginia يبدأ التصريح في عمر 15 سنة ونصف."},"ref":{"doc":"VA","page":null}},{"id":"va-002","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, how long must a teen hold a learner's permit before getting a license?","o":["6 months","9 months","12 months","3 months"],"h1":"It is three quarters of a year.","h2":"A Virginia teen must hold the learner's permit for at least nine months before getting a driver's license.","p":"Right. The permit is held for nine months."},"es":{"q":"En Virginia, ¿cuánto tiempo debe tener un adolescente el permiso de aprendiz antes de obtener la licencia?","o":["6 meses","9 meses","12 meses","3 meses"],"h1":"Son tres cuartas partes de un año.","h2":"En Virginia, un adolescente debe tener el permiso de aprendiz por lo menos nueve meses antes de obtener la licencia de manejar.","p":"Correcto. El permiso se tiene nueve meses."},"zh":{"q":"在 Virginia，青少年拿到学习驾照后，至少要持有多久才能拿驾照？","o":["6 个月","9 个月","12 个月","3 个月"],"h1":"它是一年的四分之三。","h2":"Virginia 的青少年必须持有学习驾照至少 9 个月，才能拿到驾照。","p":"对。学习驾照要持有 9 个月。"},"vi":{"q":"Ở Virginia, thanh thiếu niên phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái?","o":["6 tháng","9 tháng","12 tháng","3 tháng"],"h1":"Đó là ba phần tư của một năm.","h2":"Thanh thiếu niên ở Virginia phải giữ giấy phép tập lái ít nhất 9 tháng trước khi lấy bằng lái.","p":"Đúng. Giấy phép tập lái được giữ 9 tháng."},"tl":{"q":"Sa Virginia, gaano katagal dapat hawak ng isang teen ang learner's permit bago kumuha ng lisensya?","o":["6 na buwan","9 na buwan","12 buwan","3 buwan"],"h1":"Tatlong-kapat ito ng isang taon.","h2":"Ang teen sa Virginia ay dapat humawak ng learner's permit nang hindi bababa sa 9 na buwan bago makakuha ng driver's license.","p":"Tama. Hawak ang permit nang 9 na buwan."},"ar":{"q":"في Virginia، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل الحصول على الرخصة؟","o":["6 أشهر","9 أشهر","12 شهرًا","3 أشهر"],"h1":"هي ثلاثة أرباع السنة.","h2":"يجب أن يحمل المراهق في Virginia تصريح التعلّم 9 أشهر على الأقل قبل الحصول على رخصة القيادة.","p":"صحيح. يُحمل التصريح 9 أشهر."},"ref":{"doc":"VA","page":null}},{"id":"va-003","scope":"VA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Virginia, how many hours of supervised driving must a teen complete before getting a license?","o":["20 hours","30 hours","50 hours","45 hours"],"h1":"It is a little less than 50.","h2":"A Virginia teen must complete at least 45 hours of supervised driving practice before getting a license.","p":"Right. Virginia asks for 45 supervised hours."},"es":{"q":"En Virginia, ¿cuántas horas de manejo supervisado debe completar un adolescente antes de obtener la licencia?","o":["20 horas","30 horas","50 horas","45 horas"],"h1":"Es un poco menos de 50.","h2":"En Virginia, un adolescente debe completar por lo menos 45 horas de práctica de manejo supervisado antes de obtener la licencia.","p":"Correcto. Virginia pide 45 horas supervisadas."},"zh":{"q":"在 Virginia，青少年拿驾照前，必须完成多少小时有人陪同的驾驶练习？","o":["20 小时","30 小时","50 小时","45 小时"],"h1":"它比 50 少一点。","h2":"Virginia 的青少年拿驾照前，必须完成至少 45 小时有人陪同的驾驶练习。","p":"对。Virginia 要求 45 小时有人陪同的练习。"},"vi":{"q":"Ở Virginia, thanh thiếu niên phải lái bao nhiêu giờ có người giám sát trước khi lấy bằng lái?","o":["20 giờ","30 giờ","50 giờ","45 giờ"],"h1":"Con số này ít hơn 50 một chút.","h2":"Thanh thiếu niên ở Virginia phải tập lái có người giám sát ít nhất 45 giờ trước khi lấy bằng lái.","p":"Đúng. Virginia yêu cầu 45 giờ có người giám sát."},"tl":{"q":"Sa Virginia, ilang oras ng pagmamaneho na may gumagabay ang dapat tapusin ng teen bago kumuha ng lisensya?","o":["20 oras","30 oras","50 oras","45 oras"],"h1":"Medyo mas mababa ito sa 50.","h2":"Ang teen sa Virginia ay dapat tumapos ng hindi bababa sa 45 oras ng pagsasanay sa pagmamaneho na may gumagabay bago kumuha ng lisensya.","p":"Tama. 45 oras na may gumagabay ang hinihingi ng Virginia."},"ar":{"q":"في Virginia، كم ساعة من القيادة تحت الإشراف يجب أن يكملها المراهق قبل الحصول على الرخصة؟","o":["20 ساعة","30 ساعة","50 ساعة","45 ساعة"],"h1":"هو أقل من 50 بقليل.","h2":"يجب أن يكمل المراهق في Virginia 45 ساعة على الأقل من التدريب على القيادة تحت الإشراف قبل الحصول على الرخصة.","p":"صحيح. تطلب Virginia 45 ساعة تحت الإشراف."},"ref":{"doc":"VA","page":null}},{"id":"va-004","scope":"VA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Virginia, how many of the 45 supervised hours must be driven at night?","o":["15 hours","5 hours","10 hours","20 hours"],"h1":"It is one third of the total.","h2":"Of the 45 supervised hours in Virginia, at least 15 must be driven at night, so the teen practices in the dark.","p":"Right. 15 of the 45 hours are at night."},"es":{"q":"En Virginia, ¿cuántas de las 45 horas supervisadas deben ser de noche?","o":["15 horas","5 horas","10 horas","20 horas"],"h1":"Es una tercera parte del total.","h2":"De las 45 horas supervisadas en Virginia, por lo menos 15 deben ser de noche, para que el adolescente practique en la oscuridad.","p":"Correcto. 15 de las 45 horas son de noche."},"zh":{"q":"在 Virginia，这 45 小时有人陪同的练习中，有多少小时必须在晚上开？","o":["15 小时","5 小时","10 小时","20 小时"],"h1":"它是总数的三分之一。","h2":"在 Virginia 的 45 小时有人陪同练习中，至少 15 小时必须在晚上开，这样青少年可以练习在黑暗中开车。","p":"对。45 小时中有 15 小时在晚上。"},"vi":{"q":"Ở Virginia, trong 45 giờ có người giám sát, bao nhiêu giờ phải lái vào ban đêm?","o":["15 giờ","5 giờ","10 giờ","20 giờ"],"h1":"Đó là một phần ba của tổng số.","h2":"Trong 45 giờ có người giám sát ở Virginia, ít nhất 15 giờ phải lái vào ban đêm, để thanh thiếu niên tập lái trong bóng tối.","p":"Đúng. 15 trong 45 giờ là vào ban đêm."},"tl":{"q":"Sa Virginia, ilan sa 45 oras na may gumagabay ang dapat gawin sa gabi?","o":["15 oras","5 oras","10 oras","20 oras"],"h1":"Isang-katlo ito ng kabuuan.","h2":"Sa 45 oras na may gumagabay sa Virginia, hindi bababa sa 15 ang dapat gawin sa gabi, para masanay ang teen na magmaneho sa dilim.","p":"Tama. 15 sa 45 oras ay sa gabi."},"ar":{"q":"في Virginia، كم ساعة من الـ45 ساعة تحت الإشراف يجب أن تكون في الليل؟","o":["15 ساعة","5 ساعات","10 ساعات","20 ساعة"],"h1":"هي ثلث المجموع.","h2":"من الـ45 ساعة تحت الإشراف في Virginia، يجب أن تكون 15 ساعة على الأقل في الليل، حتى يتدرّب المراهق على القيادة في الظلام.","p":"صحيح. 15 ساعة من الـ45 تكون في الليل."},"ref":{"doc":"VA","page":null}},{"id":"va-005","scope":"VA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Virginia, how old must the licensed driver beside a learner usually be?","o":["At least 16","At least 18","At least 21","At least 25"],"h1":"A legal guardian or a brother or sister may be younger than the usual age.","h2":"A Virginia learner must drive with a licensed driver seated beside them who is at least 21, or with a parent, a legal guardian, or a brother or sister who is at least 18.","p":"Right. The supervisor is usually 21 or older."},"es":{"q":"En Virginia, ¿qué edad debe tener normalmente el conductor con licencia que va al lado del aprendiz?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 21","Por lo menos 25"],"h1":"Un tutor legal o un hermano puede ser menor que la edad habitual.","h2":"En Virginia, el aprendiz debe manejar con un conductor con licencia sentado a su lado que tenga por lo menos 21 años, o con su padre o madre, su tutor legal, o un hermano o hermana de por lo menos 18 años.","p":"Correcto. El supervisor normalmente tiene 21 años o más."},"zh":{"q":"在 Virginia，坐在学车人旁边的持照司机通常至少要几岁？","o":["至少 16 岁","至少 18 岁","至少 21 岁","至少 25 岁"],"h1":"法定监护人或兄弟姐妹可以比通常的年龄小。","h2":"Virginia 的学车人必须由坐在旁边、至少 21 岁的持照司机陪同，或由至少 18 岁的父母、法定监护人或兄弟姐妹陪同。","p":"对。陪同的人通常要 21 岁或以上。"},"vi":{"q":"Ở Virginia, người có bằng lái ngồi cạnh người tập lái thường phải bao nhiêu tuổi?","o":["Ít nhất 16 tuổi","Ít nhất 18 tuổi","Ít nhất 21 tuổi","Ít nhất 25 tuổi"],"h1":"Người giám hộ hợp pháp hoặc anh chị em có thể nhỏ tuổi hơn mức thường lệ.","h2":"Người tập lái ở Virginia phải lái cùng một người có bằng lái ngồi bên cạnh, ít nhất 21 tuổi, hoặc cùng cha mẹ, người giám hộ hợp pháp, hay anh chị em ít nhất 18 tuổi.","p":"Đúng. Người giám sát thường từ 21 tuổi trở lên."},"tl":{"q":"Sa Virginia, karaniwang ilang taon dapat ang may lisensyang driver na katabi ng nag-aaral magmaneho?","o":["Hindi bababa sa 16","Hindi bababa sa 18","Hindi bababa sa 21","Hindi bababa sa 25"],"h1":"Ang legal na tagapag-alaga o kapatid ay puwedeng mas bata sa karaniwang edad.","h2":"Ang nag-aaral magmaneho sa Virginia ay dapat may katabing driver na may lisensya na hindi bababa sa 21 taong gulang, o magulang, legal na tagapag-alaga, o kapatid na hindi bababa sa 18 taong gulang.","p":"Tama. Karaniwang 21 pataas ang gumagabay."},"ar":{"q":"في Virginia، كم يجب أن يكون عمر السائق المرخَّص الذي يجلس بجانب المتعلّم عادةً؟","o":["16 سنة على الأقل","18 سنة على الأقل","21 سنة على الأقل","25 سنة على الأقل"],"h1":"يمكن أن يكون الوصي القانوني أو الأخ أو الأخت أصغر من العمر المعتاد.","h2":"يجب أن يقود المتعلّم في Virginia ومعه سائق مرخَّص يجلس بجانبه عمره 21 سنة على الأقل، أو مع أحد الوالدين أو الوصي القانوني أو أخ أو أخت عمره 18 سنة على الأقل.","p":"صحيح. المشرف عادةً عمره 21 سنة أو أكثر."},"ref":{"doc":"VA","page":31}},{"id":"va-006","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, how many passengers under 21 who are not family may ride with a learner's permit holder?","o":["None at all","No more than one","No more than two","No more than three"],"h1":"Think of just one friend.","h2":"A Virginia learner's permit holder may carry no more than one passenger under 21 who is not a family member.","p":"Right. With a permit, only one passenger under 21 who is not family."},"es":{"q":"En Virginia, ¿cuántos pasajeros menores de 21 años que no son familiares pueden viajar con alguien que tiene permiso de aprendiz?","o":["Ninguno","No más de uno","No más de dos","No más de tres"],"h1":"Piense en un solo amigo.","h2":"En Virginia, quien tiene permiso de aprendiz puede llevar como máximo un pasajero menor de 21 años que no sea familiar.","p":"Correcto. Con permiso, solo un pasajero menor de 21 años que no sea familiar."},"zh":{"q":"在 Virginia，持学习驾照的人开车时，可以载几位不是家人、未满 21 岁的乘客？","o":["一个也不行","最多一位","最多两位","最多三位"],"h1":"想一想只带一个朋友。","h2":"Virginia 持学习驾照的人，最多只能载一位不是家人、未满 21 岁的乘客。","p":"对。持学习驾照时，只能载一位不是家人、未满 21 岁的乘客。"},"vi":{"q":"Ở Virginia, người có giấy phép tập lái được chở bao nhiêu hành khách dưới 21 tuổi không phải người trong gia đình?","o":["Không ai cả","Không quá một người","Không quá hai người","Không quá ba người"],"h1":"Hãy nghĩ đến chỉ một người bạn.","h2":"Người có giấy phép tập lái ở Virginia được chở không quá một hành khách dưới 21 tuổi không phải người trong gia đình.","p":"Đúng. Với giấy phép tập lái, chỉ một hành khách dưới 21 tuổi không phải người nhà."},"tl":{"q":"Sa Virginia, ilang pasaherong wala pang 21 at hindi kapamilya ang puwedeng isakay ng may hawak ng learner's permit?","o":["Wala talaga","Hindi hihigit sa isa","Hindi hihigit sa dalawa","Hindi hihigit sa tatlo"],"h1":"Isipin ang isang kaibigan lang.","h2":"Ang may hawak ng learner's permit sa Virginia ay puwedeng magsakay ng hindi hihigit sa isang pasaherong wala pang 21 na hindi kapamilya.","p":"Tama. Kapag may permit, isang pasahero lang na wala pang 21 na hindi kapamilya."},"ar":{"q":"في Virginia، كم راكبًا عمره أقل من 21 سنة وليس من العائلة يمكن أن يركب مع حامل تصريح التعلّم؟","o":["لا أحد أبدًا","واحد فقط على الأكثر","اثنان على الأكثر","ثلاثة على الأكثر"],"h1":"فكّر في صديق واحد فقط.","h2":"يمكن لحامل تصريح التعلّم في Virginia أن يحمل راكبًا واحدًا فقط على الأكثر عمره أقل من 21 سنة وليس من العائلة.","p":"صحيح. مع التصريح، راكب واحد فقط عمره أقل من 21 سنة وليس من العائلة."},"ref":{"doc":"VA","page":null}},{"id":"va-007","scope":"VA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Virginia, when may a driver under 18 with a driver's license not drive, unless an exception applies?","o":["From 10 p.m. to 5 a.m.","From 11 p.m. to 5 a.m.","From 9 p.m. to 6 a.m.","From midnight to 4 a.m."],"h1":"It starts at midnight.","h2":"A Virginia driver under 18 with a license may not drive from midnight to 4 a.m., except for reasons such as work, a supervised school activity or an emergency. A learner's permit holder may not drive in those hours at all.","p":"Right. No driving from midnight to 4 a.m. under 18."},"es":{"q":"En Virginia, ¿cuándo no puede manejar un conductor menor de 18 años con licencia de manejar, salvo que aplique una excepción?","o":["De 10 p.m. a 5 a.m.","De 11 p.m. a 5 a.m.","De 9 p.m. a 6 a.m.","De medianoche a 4 a.m."],"h1":"Empieza a la medianoche.","h2":"En Virginia, un conductor menor de 18 años con licencia no puede manejar de la medianoche a las 4 a.m., salvo por razones como el trabajo, una actividad escolar supervisada o una emergencia. Quien tiene permiso de aprendiz no puede manejar en esas horas.","p":"Correcto. No se maneja de medianoche a 4 a.m. si es menor de 18."},"zh":{"q":"在 Virginia，未满 18 岁、有驾照的司机，在什么时间不可以开车（除非有例外）？","o":["晚上 10 点到早上 5 点","晚上 11 点到早上 5 点","晚上 9 点到早上 6 点","半夜 12 点到早上 4 点"],"h1":"它从半夜开始。","h2":"Virginia 未满 18 岁、有驾照的司机，从半夜 12 点到早上 4 点不可以开车，除非是为了工作、有人监督的学校活动或紧急情况等原因。持学习驾照的人在这段时间完全不可以开车。","p":"对。未满 18 岁，半夜 12 点到早上 4 点不可以开车。"},"vi":{"q":"Ở Virginia, khi nào tài xế dưới 18 tuổi có bằng lái không được lái xe, trừ khi có ngoại lệ?","o":["Từ 10 giờ tối đến 5 giờ sáng","Từ 11 giờ tối đến 5 giờ sáng","Từ 9 giờ tối đến 6 giờ sáng","Từ nửa đêm đến 4 giờ sáng"],"h1":"Nó bắt đầu lúc nửa đêm.","h2":"Ở Virginia, tài xế dưới 18 tuổi có bằng lái không được lái xe từ nửa đêm đến 4 giờ sáng, trừ các lý do như đi làm, hoạt động ở trường có người giám sát, hoặc trường hợp khẩn cấp. Người có giấy phép tập lái hoàn toàn không được lái xe trong những giờ đó.","p":"Đúng. Dưới 18 tuổi, không lái xe từ nửa đêm đến 4 giờ sáng."},"tl":{"q":"Sa Virginia, kailan hindi puwedeng magmaneho ang driver na wala pang 18 na may driver's license, maliban kung may eksepsiyon?","o":["Mula 10 p.m. hanggang 5 a.m.","Mula 11 p.m. hanggang 5 a.m.","Mula 9 p.m. hanggang 6 a.m.","Mula hatinggabi hanggang 4 a.m."],"h1":"Nagsisimula ito sa hatinggabi.","h2":"Ang driver sa Virginia na wala pang 18 na may lisensya ay hindi puwedeng magmaneho mula hatinggabi hanggang 4 a.m., maliban sa mga dahilan gaya ng trabaho, aktibidad sa paaralan na may gumagabay, o emergency. Ang may hawak ng learner's permit ay hindi talaga puwedeng magmaneho sa mga oras na iyon.","p":"Tama. Bawal magmaneho mula hatinggabi hanggang 4 a.m. kapag wala pang 18."},"ar":{"q":"في Virginia، متى لا يجوز للسائق الذي عمره أقل من 18 سنة ومعه رخصة قيادة أن يقود، إلا إذا كان هناك استثناء؟","o":["من 10 مساءً إلى 5 صباحًا","من 11 مساءً إلى 5 صباحًا","من 9 مساءً إلى 6 صباحًا","من منتصف الليل إلى 4 صباحًا"],"h1":"يبدأ عند منتصف الليل.","h2":"في Virginia لا يجوز للسائق الذي عمره أقل من 18 سنة ومعه رخصة أن يقود من منتصف الليل إلى 4 صباحًا، إلا لأسباب مثل العمل أو نشاط مدرسي تحت الإشراف أو حالة طوارئ. أما حامل تصريح التعلّم فلا يجوز له أن يقود في هذه الساعات أبدًا.","p":"صحيح. لا قيادة من منتصف الليل إلى 4 صباحًا لمن عمره أقل من 18 سنة."},"ref":{"doc":"VA","page":null}},{"id":"va-008","scope":"VA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Virginia, which trip is allowed between midnight and 4 a.m. for a driver under 18 with a driver's license?","o":["Driving to or from a job","Driving home from a party","Driving a friend to the store","Driving to practice for the road test"],"h1":"It is a trip connected to earning money.","h2":"Virginia lets a licensed driver under 18 drive between midnight and 4 a.m. to or from a job, and for a few other listed reasons such as an emergency.","p":"Right. Driving to or from work is allowed."},"es":{"q":"En Virginia, ¿qué viaje se permite entre la medianoche y las 4 a.m. a un conductor menor de 18 años con licencia de manejar?","o":["Ir o volver del trabajo","Volver a casa de una fiesta","Llevar a un amigo a la tienda","Practicar para el examen de manejo"],"h1":"Es un viaje relacionado con ganar dinero.","h2":"Virginia permite que un conductor menor de 18 años con licencia maneje entre la medianoche y las 4 a.m. para ir o volver del trabajo, y por otras pocas razones, como una emergencia.","p":"Correcto. Se permite ir o volver del trabajo."},"zh":{"q":"在 Virginia，未满 18 岁、有驾照的司机，在半夜 12 点到早上 4 点之间，可以开哪一种车程？","o":["开车去上班或下班回家","参加派对后开车回家","开车送朋友去商店","开车去练习路考"],"h1":"这是和赚钱有关的车程。","h2":"Virginia 允许未满 18 岁、有驾照的司机在半夜 12 点到早上 4 点之间开车去上班或下班回家，也允许其他几个列出的原因，例如紧急情况。","p":"对。开车上下班是允许的。"},"vi":{"q":"Ở Virginia, chuyến đi nào được phép từ nửa đêm đến 4 giờ sáng đối với tài xế dưới 18 tuổi có bằng lái?","o":["Lái xe đi làm hoặc đi làm về","Lái xe về nhà sau bữa tiệc","Chở bạn đi cửa hàng","Lái xe đi tập cho kỳ thi lái xe"],"h1":"Đó là chuyến đi liên quan đến việc kiếm tiền.","h2":"Virginia cho phép tài xế dưới 18 tuổi có bằng lái được lái xe từ nửa đêm đến 4 giờ sáng để đi làm hoặc đi làm về, và vì một vài lý do khác được liệt kê như trường hợp khẩn cấp.","p":"Đúng. Được phép lái xe đi làm hoặc đi làm về."},"tl":{"q":"Sa Virginia, aling biyahe ang pinapayagan mula hatinggabi hanggang 4 a.m. para sa driver na wala pang 18 na may driver's license?","o":["Pagmamaneho papunta o pauwi mula sa trabaho","Pagmamaneho pauwi mula sa party","Paghatid sa kaibigan sa tindahan","Pagmamaneho para magsanay para sa road test"],"h1":"Biyahe ito na may kinalaman sa pagkita ng pera.","h2":"Pinapayagan ng Virginia ang driver na wala pang 18 na may lisensya na magmaneho mula hatinggabi hanggang 4 a.m. papunta o pauwi mula sa trabaho, at sa ilang iba pang nakalistang dahilan gaya ng emergency.","p":"Tama. Pinapayagan ang pagmamaneho papunta o pauwi mula sa trabaho."},"ar":{"q":"في Virginia، أي رحلة مسموح بها بين منتصف الليل و4 صباحًا للسائق الذي عمره أقل من 18 سنة ومعه رخصة قيادة؟","o":["القيادة إلى العمل أو العودة منه","القيادة إلى البيت بعد حفلة","توصيل صديق إلى المتجر","القيادة للتدرّب على اختبار القيادة العملي"],"h1":"هي رحلة لها علاقة بكسب المال.","h2":"تسمح Virginia للسائق المرخَّص الذي عمره أقل من 18 سنة بالقيادة بين منتصف الليل و4 صباحًا للذهاب إلى العمل أو العودة منه، ولبعض الأسباب الأخرى المذكورة مثل حالة الطوارئ.","p":"صحيح. القيادة إلى العمل أو العودة منه مسموح بها."},"ref":{"doc":"VA","page":null}},{"id":"va-009","scope":"VA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Virginia, during the first year with a license, how many passengers under 21 may a driver under 18 carry?","o":["None at all","Two","One","Three"],"h1":"Family members do not count toward this limit.","h2":"In the first year with a Virginia license, a driver under 18 may carry only one passenger under 21 who is not a family member.","p":"Right. One passenger under 21 in the first year."},"es":{"q":"En Virginia, durante el primer año con licencia, ¿cuántos pasajeros menores de 21 años puede llevar un conductor menor de 18?","o":["Ninguno","Dos","Uno","Tres"],"h1":"Los familiares no cuentan para este límite.","h2":"En el primer año con licencia en Virginia, un conductor menor de 18 años solo puede llevar un pasajero menor de 21 años que no sea familiar.","p":"Correcto. Un pasajero menor de 21 el primer año."},"zh":{"q":"在 Virginia，未满 18 岁的司机拿到驾照后的第一年，可以载几位未满 21 岁的乘客？","o":["一个也不行","两位","一位","三位"],"h1":"家人不算在这个限制里。","h2":"在 Virginia 拿到驾照后的第一年，未满 18 岁的司机只能载一位不是家人、未满 21 岁的乘客。","p":"对。第一年只能载一位未满 21 岁的乘客。"},"vi":{"q":"Ở Virginia, trong năm đầu có bằng lái, tài xế dưới 18 tuổi được chở bao nhiêu hành khách dưới 21 tuổi?","o":["Không ai cả","Hai người","Một người","Ba người"],"h1":"Người trong gia đình không tính vào giới hạn này.","h2":"Trong năm đầu có bằng lái ở Virginia, tài xế dưới 18 tuổi chỉ được chở một hành khách dưới 21 tuổi không phải người trong gia đình.","p":"Đúng. Một hành khách dưới 21 tuổi trong năm đầu."},"tl":{"q":"Sa Virginia, sa unang taon na may lisensya, ilang pasaherong wala pang 21 ang puwedeng isakay ng driver na wala pang 18?","o":["Wala talaga","Dalawa","Isa","Tatlo"],"h1":"Hindi kasama sa limitasyong ito ang mga kapamilya.","h2":"Sa unang taon na may lisensya sa Virginia, ang driver na wala pang 18 ay puwedeng magsakay ng isang pasahero lang na wala pang 21 na hindi kapamilya.","p":"Tama. Isang pasaherong wala pang 21 sa unang taon."},"ar":{"q":"في Virginia، في السنة الأولى مع الرخصة، كم راكبًا عمره أقل من 21 سنة يمكن أن يحمل السائق الذي عمره أقل من 18 سنة؟","o":["لا أحد أبدًا","اثنان","واحد","ثلاثة"],"h1":"أفراد العائلة لا يُحسبون في هذا الحد.","h2":"في السنة الأولى مع رخصة Virginia، يمكن للسائق الذي عمره أقل من 18 سنة أن يحمل راكبًا واحدًا فقط عمره أقل من 21 سنة وليس من العائلة.","p":"صحيح. راكب واحد عمره أقل من 21 سنة في السنة الأولى."},"ref":{"doc":"VA","page":null}},{"id":"va-010","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, after holding a license for one year, how many passengers under 21 may a driver under 18 carry in limited situations, such as going to a school activity?","o":["Two","Up to three","Up to five","Any number"],"h1":"The number goes up after the first year, but only for certain trips.","h2":"After one year with a license, a Virginia driver under 18 may carry up to three passengers under 21 in limited situations, such as a trip to or from a school activity.","p":"Right. Up to three, in limited situations."},"es":{"q":"En Virginia, después de tener la licencia un año, ¿cuántos pasajeros menores de 21 años puede llevar un conductor menor de 18 en situaciones limitadas, como ir a una actividad escolar?","o":["Dos","Hasta tres","Hasta cinco","Cualquier número"],"h1":"El número sube después del primer año, pero solo para ciertos viajes.","h2":"Después de un año con licencia, un conductor menor de 18 años en Virginia puede llevar hasta tres pasajeros menores de 21 en situaciones limitadas, como ir o volver de una actividad escolar.","p":"Correcto. Hasta tres, en situaciones limitadas."},"zh":{"q":"在 Virginia，未满 18 岁的司机拿驾照满一年后，在少数情况下（例如去参加学校活动），可以载几位未满 21 岁的乘客？","o":["两位","最多三位","最多五位","不限人数"],"h1":"第一年后人数会增加，但只限某些车程。","h2":"在 Virginia，未满 18 岁的司机拿驾照满一年后，在少数情况下（例如往返学校活动），最多可以载三位未满 21 岁的乘客。","p":"对。在少数情况下最多三位。"},"vi":{"q":"Ở Virginia, sau khi có bằng lái một năm, tài xế dưới 18 tuổi được chở bao nhiêu hành khách dưới 21 tuổi trong một số trường hợp, như đi đến hoạt động ở trường?","o":["Hai người","Tối đa ba người","Tối đa năm người","Bao nhiêu cũng được"],"h1":"Số người tăng lên sau năm đầu, nhưng chỉ cho một số chuyến đi.","h2":"Sau một năm có bằng lái, tài xế dưới 18 tuổi ở Virginia được chở tối đa ba hành khách dưới 21 tuổi trong một số trường hợp, như đi đến hoặc về từ hoạt động ở trường.","p":"Đúng. Tối đa ba người, trong một số trường hợp."},"tl":{"q":"Sa Virginia, pagkatapos ng isang taon na may lisensya, ilang pasaherong wala pang 21 ang puwedeng isakay ng driver na wala pang 18 sa ilang sitwasyon, gaya ng pagpunta sa aktibidad sa paaralan?","o":["Dalawa","Hanggang tatlo","Hanggang lima","Kahit ilan"],"h1":"Tumataas ang bilang pagkatapos ng unang taon, pero para lang sa ilang biyahe.","h2":"Pagkatapos ng isang taon na may lisensya, ang driver sa Virginia na wala pang 18 ay puwedeng magsakay ng hanggang tatlong pasaherong wala pang 21 sa ilang sitwasyon, gaya ng biyahe papunta o pauwi mula sa aktibidad sa paaralan.","p":"Tama. Hanggang tatlo, sa ilang sitwasyon."},"ar":{"q":"في Virginia، بعد سنة واحدة مع الرخصة، كم راكبًا عمره أقل من 21 سنة يمكن أن يحمل السائق الذي عمره أقل من 18 سنة في حالات محدودة، مثل الذهاب إلى نشاط مدرسي؟","o":["اثنان","حتى ثلاثة","حتى خمسة","أي عدد"],"h1":"يزيد العدد بعد السنة الأولى، لكن لبعض الرحلات فقط.","h2":"بعد سنة واحدة مع الرخصة، يمكن للسائق في Virginia الذي عمره أقل من 18 سنة أن يحمل حتى ثلاثة ركاب أعمارهم أقل من 21 سنة في حالات محدودة، مثل الذهاب إلى نشاط مدرسي أو العودة منه.","p":"صحيح. حتى ثلاثة، في حالات محدودة."},"ref":{"doc":"VA","page":null}},{"id":"va-011","scope":"VA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Virginia, when may a driver use a phone for navigation while driving?","o":["When holding it in one hand to see the map","When typing a new address while moving slowly","When not holding it and not typing into it","Never; map apps are banned while driving"],"h1":"Following directions is allowed; holding or typing is not.","h2":"In Virginia, a driver may use a phone for navigation while driving, as long as the driver is not holding it or entering information into it.","p":"Right. Navigation is allowed if you do not hold the phone or type into it."},"es":{"q":"En Virginia, ¿cuándo puede un conductor usar el celular para navegar mientras maneja?","o":["Cuando lo sostiene en una mano para ver el mapa","Cuando escribe una dirección nueva mientras avanza despacio","Cuando no lo sostiene ni escribe en él","Nunca; las aplicaciones de mapas están prohibidas al manejar"],"h1":"Seguir indicaciones está permitido; sostenerlo o escribir no.","h2":"En Virginia, un conductor puede usar el celular para navegar mientras maneja, siempre que no lo sostenga ni escriba información en él.","p":"Correcto. Navegar está permitido si no sostiene el celular ni escribe en él."},"zh":{"q":"在 Virginia，司机开车时什么时候可以用手机导航？","o":["一只手拿着手机看地图的时候","车开得慢时输入新地址的时候","不拿着手机、也不在手机上打字的时候","永远不可以；开车时禁止用地图应用"],"h1":"跟着路线走是可以的；拿着手机或打字是不可以的。","h2":"在 Virginia，司机开车时可以用手机导航，只要不拿着手机，也不在手机上输入信息。","p":"对。只要不拿着手机、不在上面打字，就可以导航。"},"vi":{"q":"Ở Virginia, khi nào tài xế được dùng điện thoại để chỉ đường trong lúc lái xe?","o":["Khi cầm điện thoại bằng một tay để xem bản đồ","Khi gõ địa chỉ mới trong lúc chạy chậm","Khi không cầm điện thoại và không gõ vào điện thoại","Không bao giờ; ứng dụng bản đồ bị cấm khi lái xe"],"h1":"Đi theo chỉ đường thì được; cầm hoặc gõ thì không được.","h2":"Ở Virginia, tài xế được dùng điện thoại để chỉ đường trong lúc lái xe, miễn là tài xế không cầm điện thoại và không nhập thông tin vào điện thoại.","p":"Đúng. Được dùng chỉ đường nếu bạn không cầm điện thoại và không gõ vào nó."},"tl":{"q":"Sa Virginia, kailan puwedeng gumamit ang driver ng telepono para sa navigation habang nagmamaneho?","o":["Kapag hawak ito sa isang kamay para makita ang mapa","Kapag nagta-type ng bagong address habang mabagal ang takbo","Kapag hindi ito hawak at hindi nagta-type dito","Hindi kailanman; bawal ang map apps habang nagmamaneho"],"h1":"Puwede ang pagsunod sa direksyon; hindi puwede ang paghawak o pag-type.","h2":"Sa Virginia, puwedeng gumamit ang driver ng telepono para sa navigation habang nagmamaneho, basta hindi niya ito hawak at hindi siya naglalagay ng impormasyon dito.","p":"Tama. Puwede ang navigation kung hindi mo hawak ang telepono at hindi ka nagta-type dito."},"ar":{"q":"في Virginia، متى يجوز للسائق أن يستخدم الهاتف للملاحة أثناء القيادة؟","o":["عندما يمسكه بيد واحدة ليرى الخريطة","عندما يكتب عنوانًا جديدًا وهو يسير ببطء","عندما لا يمسكه ولا يكتب فيه","أبدًا؛ تطبيقات الخرائط ممنوعة أثناء القيادة"],"h1":"اتباع الاتجاهات مسموح؛ الإمساك بالهاتف أو الكتابة فيه غير مسموح.","h2":"في Virginia، يجوز للسائق أن يستخدم الهاتف للملاحة أثناء القيادة، بشرط ألا يمسكه وألا يُدخل فيه معلومات.","p":"صحيح. الملاحة مسموحة إذا كنت لا تمسك الهاتف ولا تكتب فيه."},"ref":{"doc":"VA","page":24}},{"id":"va-012","scope":"VA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Virginia, since January 1, 2021, what is illegal for every driver while the car is moving?","o":["Holding a phone in your hand","Listening to the radio","Using a hands-free phone","Talking to passengers"],"h1":"The law is about where the phone is.","h2":"Since January 1, 2021, Virginia drivers may not hold a hand-held phone or other communication device while driving, except in an emergency or when lawfully stopped or parked.","p":"Right. Holding a phone while driving is illegal."},"es":{"q":"En Virginia, desde el 1 de enero de 2021, ¿qué es ilegal para todo conductor mientras el carro está en movimiento?","o":["Sostener el teléfono en la mano","Escuchar la radio","Usar el teléfono con manos libres","Hablar con los pasajeros"],"h1":"La ley trata de dónde está el teléfono.","h2":"Desde el 1 de enero de 2021, los conductores en Virginia no pueden sostener un teléfono u otro dispositivo de comunicación al manejar, salvo en una emergencia o cuando están detenidos o estacionados legalmente.","p":"Correcto. Sostener el teléfono al manejar es ilegal."},"zh":{"q":"在 Virginia，从 2021 年 1 月 1 日起，车在行驶时，所有司机都不可以做什么？","o":["用手拿着手机","听收音机","用免提电话","和乘客说话"],"h1":"这条法律和手机放在哪里有关。","h2":"从 2021 年 1 月 1 日起，Virginia 的司机开车时不可以用手拿着手机或其他通讯设备，除非是紧急情况，或车已合法停下或停好。","p":"对。开车时拿着手机是违法的。"},"vi":{"q":"Ở Virginia, từ ngày 1 tháng 1 năm 2021, điều gì là bất hợp pháp với mọi tài xế khi xe đang chạy?","o":["Cầm điện thoại trên tay","Nghe radio","Dùng điện thoại rảnh tay","Nói chuyện với hành khách"],"h1":"Luật này nói về vị trí của điện thoại.","h2":"Từ ngày 1 tháng 1 năm 2021, tài xế ở Virginia không được cầm điện thoại hoặc thiết bị liên lạc khác trên tay khi lái xe, trừ trường hợp khẩn cấp hoặc khi xe đã dừng hay đỗ hợp pháp.","p":"Đúng. Cầm điện thoại khi lái xe là bất hợp pháp."},"tl":{"q":"Sa Virginia, mula Enero 1, 2021, ano ang bawal sa bawat driver habang umaandar ang sasakyan?","o":["Paghawak ng telepono sa kamay","Pakikinig sa radyo","Paggamit ng hands-free na telepono","Pakikipag-usap sa mga pasahero"],"h1":"Tungkol ang batas sa kung nasaan ang telepono.","h2":"Mula Enero 1, 2021, hindi puwedeng humawak ang mga driver sa Virginia ng telepono o ibang communication device habang nagmamaneho, maliban sa emergency o kapag legal na nakahinto o nakaparada.","p":"Tama. Bawal humawak ng telepono habang nagmamaneho."},"ar":{"q":"في Virginia، منذ 1 يناير 2021، ما الممنوع على كل سائق أثناء حركة السيارة؟","o":["إمساك الهاتف في يدك","الاستماع إلى الراديو","استخدام هاتف بدون استعمال اليدين","التحدث مع الركاب"],"h1":"القانون يتعلّق بمكان الهاتف.","h2":"منذ 1 يناير 2021، لا يجوز للسائقين في Virginia أن يمسكوا الهاتف أو أي جهاز اتصال آخر في اليد أثناء القيادة، إلا في حالة طوارئ أو عند التوقف أو الوقوف بشكل قانوني.","p":"صحيح. إمساك الهاتف أثناء القيادة ممنوع."},"ref":{"doc":"VA","page":24}},{"id":"va-013","scope":"VA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Virginia, what is the fine for a first offense of holding a phone while driving?","o":["$25","$50","$125","$500"],"h1":"It is more than one hundred dollars.","h2":"A first offense of holding a phone while driving in Virginia carries a $125 fine.","p":"Right. The first offense is $125."},"es":{"q":"En Virginia, ¿cuál es la multa por la primera vez que se sostiene el teléfono al manejar?","o":["$25","$50","$125","$500"],"h1":"Es más de cien dólares.","h2":"La primera infracción por sostener el teléfono al manejar en Virginia tiene una multa de $125.","p":"Correcto. La primera vez son $125."},"zh":{"q":"在 Virginia，第一次被抓到开车时拿着手机，罚款是多少？","o":["$25","$50","$125","$500"],"h1":"它超过一百美元。","h2":"在 Virginia，第一次开车时拿着手机，罚款是 $125。","p":"对。第一次罚 $125。"},"vi":{"q":"Ở Virginia, tiền phạt cho lần vi phạm đầu tiên vì cầm điện thoại khi lái xe là bao nhiêu?","o":["$25","$50","$125","$500"],"h1":"Số tiền này hơn một trăm đô la.","h2":"Ở Virginia, lần đầu cầm điện thoại khi lái xe bị phạt $125.","p":"Đúng. Lần vi phạm đầu tiên là $125."},"tl":{"q":"Sa Virginia, magkano ang multa sa unang paglabag ng paghawak ng telepono habang nagmamaneho?","o":["$25","$50","$125","$500"],"h1":"Higit ito sa isang daang dolyar.","h2":"Sa Virginia, ang unang paglabag ng paghawak ng telepono habang nagmamaneho ay may multang $125.","p":"Tama. $125 ang unang paglabag."},"ar":{"q":"في Virginia، كم غرامة المخالفة الأولى لإمساك الهاتف أثناء القيادة؟","o":["$25","$50","$125","$500"],"h1":"هي أكثر من مئة دولار.","h2":"في Virginia، المخالفة الأولى لإمساك الهاتف أثناء القيادة غرامتها $125.","p":"صحيح. المخالفة الأولى $125."},"ref":{"doc":"VA","page":null}},{"id":"va-014","scope":"VA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Virginia, what is the fine for holding a phone while driving in a highway work zone?","o":["$125","$250","$75","$1,000"],"h1":"It is the same as the fine for a second offense.","h2":"Holding a phone while driving in a Virginia highway work zone, or a second offense, carries a $250 fine, double the first-offense fine.","p":"Right. In a work zone the fine is $250."},"es":{"q":"En Virginia, ¿cuál es la multa por sostener el teléfono al manejar en una zona de trabajos en la carretera?","o":["$125","$250","$75","$1,000"],"h1":"Es igual a la multa por una segunda infracción.","h2":"Sostener el teléfono al manejar en una zona de trabajos en una carretera de Virginia, o una segunda infracción, tiene una multa de $250, el doble que la primera vez.","p":"Correcto. En una zona de trabajos la multa es $250."},"zh":{"q":"在 Virginia，在高速公路施工区开车时拿着手机，罚款是多少？","o":["$125","$250","$75","$1,000"],"h1":"它和第二次违规的罚款一样。","h2":"在 Virginia 的高速公路施工区开车时拿着手机，或第二次违规，罚款是 $250，是第一次罚款的两倍。","p":"对。在施工区罚 $250。"},"vi":{"q":"Ở Virginia, tiền phạt vì cầm điện thoại khi lái xe trong khu vực thi công trên xa lộ là bao nhiêu?","o":["$125","$250","$75","$1,000"],"h1":"Số tiền này bằng tiền phạt cho lần vi phạm thứ hai.","h2":"Cầm điện thoại khi lái xe trong khu vực thi công trên xa lộ ở Virginia, hoặc vi phạm lần thứ hai, bị phạt $250, gấp đôi tiền phạt lần đầu.","p":"Đúng. Trong khu vực thi công, tiền phạt là $250."},"tl":{"q":"Sa Virginia, magkano ang multa sa paghawak ng telepono habang nagmamaneho sa work zone ng highway?","o":["$125","$250","$75","$1,000"],"h1":"Kapareho ito ng multa sa ikalawang paglabag.","h2":"Ang paghawak ng telepono habang nagmamaneho sa work zone ng highway sa Virginia, o ang ikalawang paglabag, ay may multang $250, doble ng multa sa unang paglabag.","p":"Tama. Sa work zone, $250 ang multa."},"ar":{"q":"في Virginia، كم غرامة إمساك الهاتف أثناء القيادة في منطقة أعمال على الطريق السريع؟","o":["$125","$250","$75","$1,000"],"h1":"هي نفس غرامة المخالفة الثانية.","h2":"إمساك الهاتف أثناء القيادة في منطقة أعمال على طريق سريع في Virginia، أو المخالفة الثانية، غرامته $250، أي ضعف غرامة المخالفة الأولى.","p":"صحيح. في منطقة الأعمال الغرامة $250."},"ref":{"doc":"VA","page":null}},{"id":"va-015","scope":"VA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Virginia, a driver under 21 who has been drinking breaks the law at what blood alcohol level?","o":["0.08 percent","0.05 percent","0.10 percent","0.02 percent"],"h1":"It is the lowest number on the list.","h2":"In Virginia a driver under 21 who drives after drinking alcohol breaks the law with a blood alcohol level of 0.02 percent or more.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Virginia, ¿con qué nivel de alcohol en la sangre viola la ley un conductor menor de 21 años que ha bebido?","o":["0.08 por ciento","0.05 por ciento","0.10 por ciento","0.02 por ciento"],"h1":"Es el número más bajo de la lista.","h2":"En Virginia, un conductor menor de 21 años que maneja después de beber viola la ley con un nivel de alcohol de 0.02 por ciento o más.","p":"Correcto. Para menores de 21, el límite es 0.02."},"zh":{"q":"在 Virginia，未满 21 岁的司机喝酒后开车，血液酒精浓度达到多少就违法？","o":["0.08%","0.05%","0.10%","0.02%"],"h1":"它是选项中最小的数字。","h2":"在 Virginia，未满 21 岁的司机喝酒后开车，血液酒精浓度达到 0.02% 或以上就违法。","p":"对。未满 21 岁，上限是 0.02。"},"vi":{"q":"Ở Virginia, tài xế dưới 21 tuổi đã uống rượu bia sẽ phạm luật ở nồng độ cồn trong máu bao nhiêu?","o":["0.08%","0.05%","0.10%","0.02%"],"h1":"Đó là con số nhỏ nhất trong danh sách.","h2":"Ở Virginia, tài xế dưới 21 tuổi lái xe sau khi uống rượu bia sẽ phạm luật khi nồng độ cồn trong máu từ 0.02% trở lên.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa Virginia, ang driver na wala pang 21 na uminom ng alak ay lumalabag sa batas sa anong antas ng alkohol sa dugo?","o":["0.08 porsiyento","0.05 porsiyento","0.10 porsiyento","0.02 porsiyento"],"h1":"Ito ang pinakamababang numero sa listahan.","h2":"Sa Virginia, ang driver na wala pang 21 na nagmaneho pagkatapos uminom ng alak ay lumalabag sa batas kapag 0.02 porsiyento o higit pa ang alkohol sa dugo niya.","p":"Tama. Kapag wala pang 21, 0.02 ang limitasyon."},"ar":{"q":"في Virginia، السائق الذي عمره أقل من 21 سنة وشرب الكحول يخالف القانون عند أي نسبة كحول في الدم؟","o":["0.08 بالمئة","0.05 بالمئة","0.10 بالمئة","0.02 بالمئة"],"h1":"هي أصغر رقم في القائمة.","h2":"في Virginia، السائق الذي عمره أقل من 21 سنة ويقود بعد شرب الكحول يخالف القانون إذا كانت نسبة الكحول في دمه 0.02 بالمئة أو أكثر.","p":"صحيح. لمن عمره أقل من 21 سنة، الحد هو 0.02."},"ref":{"doc":"VA","page":24}},{"id":"va-016","scope":"VA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Virginia, what happens to the license of a driver under 21 convicted of driving after drinking?","o":["It is lost for one year","It gets a warning stamp","It is lost for one week","Nothing happens to it"],"h1":"The loss lasts a full year.","h2":"A driver under 21 convicted of driving after drinking in Virginia loses the license for one year and must also pay at least $500 or do 50 hours of community service.","p":"Right. The license is lost for one year."},"es":{"q":"En Virginia, ¿qué le pasa a la licencia de un conductor menor de 21 años condenado por manejar después de beber?","o":["La pierde por un año","Recibe un sello de advertencia","La pierde por una semana","No le pasa nada"],"h1":"La pérdida dura un año completo.","h2":"En Virginia, un conductor menor de 21 años condenado por manejar después de beber pierde la licencia por un año y además debe pagar por lo menos $500 o hacer 50 horas de servicio comunitario.","p":"Correcto. Pierde la licencia por un año."},"zh":{"q":"在 Virginia，未满 21 岁的司机因喝酒后开车被定罪，驾照会怎样？","o":["被吊销一年","被盖上警告章","被吊销一周","驾照没有任何影响"],"h1":"吊销时间是整整一年。","h2":"在 Virginia，未满 21 岁的司机因喝酒后开车被定罪，会被吊销驾照一年，还必须付至少 $500 罚款或做 50 小时社区服务。","p":"对。驾照会被吊销一年。"},"vi":{"q":"Ở Virginia, điều gì xảy ra với bằng lái của tài xế dưới 21 tuổi bị kết tội lái xe sau khi uống rượu bia?","o":["Bị mất bằng một năm","Bị đóng dấu cảnh cáo","Bị mất bằng một tuần","Không có gì xảy ra"],"h1":"Thời gian mất bằng là trọn một năm.","h2":"Ở Virginia, tài xế dưới 21 tuổi bị kết tội lái xe sau khi uống rượu bia sẽ mất bằng lái một năm, và còn phải trả ít nhất $500 hoặc làm 50 giờ phục vụ cộng đồng.","p":"Đúng. Bằng lái bị mất một năm."},"tl":{"q":"Sa Virginia, ano ang mangyayari sa lisensya ng driver na wala pang 21 na nahatulan sa pagmamaneho pagkatapos uminom?","o":["Mawawala ito nang isang taon","Lalagyan ito ng tatak ng babala","Mawawala ito nang isang linggo","Walang mangyayari dito"],"h1":"Buong isang taon ang pagkawala.","h2":"Sa Virginia, ang driver na wala pang 21 na nahatulan sa pagmamaneho pagkatapos uminom ay mawawalan ng lisensya nang isang taon, at dapat ding magbayad ng hindi bababa sa $500 o gumawa ng 50 oras na community service.","p":"Tama. Mawawala ang lisensya nang isang taon."},"ar":{"q":"في Virginia، ماذا يحدث لرخصة السائق الذي عمره أقل من 21 سنة إذا أُدين بالقيادة بعد الشرب؟","o":["تُسحب لمدة سنة","يوضع عليها ختم تحذير","تُسحب لمدة أسبوع","لا يحدث لها شيء"],"h1":"السحب يستمر سنة كاملة.","h2":"في Virginia، السائق الذي عمره أقل من 21 سنة ويُدان بالقيادة بعد الشرب تُسحب رخصته لمدة سنة، ويجب أيضًا أن يدفع $500 على الأقل أو يقوم بـ50 ساعة من خدمة المجتمع.","p":"صحيح. تُسحب الرخصة لمدة سنة."},"ref":{"doc":"VA","page":30}},{"id":"va-017","scope":"VA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Virginia, driving how much over the speed limit counts as reckless driving?","o":["5 mph or more","10 mph or more","20 mph or more","30 mph or more"],"h1":"In Virginia this is a crime, not just a ticket.","h2":"In Virginia, driving 20 mph or more over the speed limit is reckless driving, a serious offense.","p":"Right. 20 mph or more over the limit is reckless driving."},"es":{"q":"En Virginia, ¿cuánto por encima del límite de velocidad se considera manejo imprudente (reckless driving)?","o":["5 mph o más","10 mph o más","20 mph o más","30 mph o más"],"h1":"En Virginia esto es un delito, no solo una multa.","h2":"En Virginia, manejar 20 mph o más por encima del límite es manejo imprudente, una infracción grave.","p":"Correcto. 20 mph o más sobre el límite es manejo imprudente."},"zh":{"q":"在 Virginia，开车超过限速多少就算鲁莽驾驶（reckless driving）？","o":["超过 5 mph 或以上","超过 10 mph 或以上","超过 20 mph 或以上","超过 30 mph 或以上"],"h1":"在 Virginia，这是犯罪，不只是罚单。","h2":"在 Virginia，超过限速 20 mph 或以上就是鲁莽驾驶，是严重的违法行为。","p":"对。超过限速 20 mph 或以上就是鲁莽驾驶。"},"vi":{"q":"Ở Virginia, lái xe vượt tốc độ giới hạn bao nhiêu thì bị coi là lái xe liều lĩnh (reckless driving)?","o":["Từ 5 mph trở lên","Từ 10 mph trở lên","Từ 20 mph trở lên","Từ 30 mph trở lên"],"h1":"Ở Virginia, đây là tội, không chỉ là một vé phạt.","h2":"Ở Virginia, lái xe vượt tốc độ giới hạn từ 20 mph trở lên là lái xe liều lĩnh, một vi phạm nghiêm trọng.","p":"Đúng. Vượt giới hạn từ 20 mph trở lên là lái xe liều lĩnh."},"tl":{"q":"Sa Virginia, gaano kalaki ang lampas sa speed limit para ituring na reckless driving?","o":["5 mph o higit pa","10 mph o higit pa","20 mph o higit pa","30 mph o higit pa"],"h1":"Sa Virginia, krimen ito, hindi lang tiket.","h2":"Sa Virginia, ang pagmamaneho nang 20 mph o higit pa sa speed limit ay reckless driving, isang mabigat na paglabag.","p":"Tama. 20 mph o higit pa sa limit ay reckless driving."},"ar":{"q":"في Virginia، القيادة بكم فوق حد السرعة تُعتبر قيادة متهورة (reckless driving)؟","o":["5 mph أو أكثر","10 mph أو أكثر","20 mph أو أكثر","30 mph أو أكثر"],"h1":"في Virginia هذه جريمة، وليست مجرد مخالفة.","h2":"في Virginia، القيادة بسرعة 20 mph أو أكثر فوق حد السرعة هي قيادة متهورة، وهي مخالفة خطيرة.","p":"صحيح. 20 mph أو أكثر فوق الحد هي قيادة متهورة."},"ref":{"doc":"VA","page":14}},{"id":"va-018","scope":"VA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Virginia, above what speed is driving always reckless, whatever the posted limit?","o":["75 mph","85 mph","80 mph","100 mph"],"h1":"It is 15 mph above the top interstate limit.","h2":"In Virginia, driving faster than 85 mph is reckless driving no matter what the posted speed limit is.","p":"Right. Over 85 mph is always reckless driving."},"es":{"q":"En Virginia, ¿a partir de qué velocidad es siempre manejo imprudente, sin importar el límite indicado?","o":["75 mph","85 mph","80 mph","100 mph"],"h1":"Es 15 mph más que el límite máximo de las interestatales.","h2":"En Virginia, manejar a más de 85 mph es manejo imprudente sin importar el límite de velocidad indicado.","p":"Correcto. Más de 85 mph es siempre manejo imprudente."},"zh":{"q":"在 Virginia，不管标示的限速是多少，车速超过多少就一定算鲁莽驾驶？","o":["75 mph","85 mph","80 mph","100 mph"],"h1":"它比州际公路的最高限速高 15 mph。","h2":"在 Virginia，不管标示的限速是多少，车速超过 85 mph 就是鲁莽驾驶。","p":"对。超过 85 mph 一定是鲁莽驾驶。"},"vi":{"q":"Ở Virginia, trên tốc độ nào thì lái xe luôn bị coi là liều lĩnh, dù giới hạn ghi trên biển là bao nhiêu?","o":["75 mph","85 mph","80 mph","100 mph"],"h1":"Nó cao hơn giới hạn cao nhất trên xa lộ liên tiểu bang 15 mph.","h2":"Ở Virginia, lái xe nhanh hơn 85 mph là lái xe liều lĩnh, dù tốc độ giới hạn ghi trên biển là bao nhiêu.","p":"Đúng. Trên 85 mph luôn là lái xe liều lĩnh."},"tl":{"q":"Sa Virginia, lampas sa anong bilis ay laging reckless driving, anuman ang nakapaskil na limit?","o":["75 mph","85 mph","80 mph","100 mph"],"h1":"15 mph ito sa itaas ng pinakamataas na limit sa interstate.","h2":"Sa Virginia, ang pagmamaneho nang mas mabilis sa 85 mph ay reckless driving, anuman ang nakapaskil na speed limit.","p":"Tama. Lampas sa 85 mph ay laging reckless driving."},"ar":{"q":"في Virginia، فوق أي سرعة تكون القيادة متهورة دائمًا، مهما كان الحد المكتوب على اللافتة؟","o":["75 mph","85 mph","80 mph","100 mph"],"h1":"هي أعلى بـ15 mph من أعلى حد على الطرق السريعة بين الولايات.","h2":"في Virginia، القيادة بسرعة أكثر من 85 mph هي قيادة متهورة مهما كان حد السرعة المكتوب على اللافتة.","p":"صحيح. أكثر من 85 mph هي دائمًا قيادة متهورة."},"ref":{"doc":"VA","page":14}},{"id":"va-019","scope":"VA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Virginia, what is the highest speed limit on rural interstates?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"It is lower than in many western states.","h2":"The highest posted limit on Virginia's rural interstates is 70 mph; always follow the posted signs.","p":"Right. Rural interstates in Virginia go up to 70 mph."},"es":{"q":"En Virginia, ¿cuál es el límite de velocidad más alto en las interestatales rurales?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Es más bajo que en muchos estados del oeste.","h2":"El límite más alto en las interestatales rurales de Virginia es de 70 mph; siempre siga los letreros.","p":"Correcto. Las interestatales rurales de Virginia llegan a 70 mph."},"zh":{"q":"在 Virginia，乡村州际公路（interstate）的最高限速是多少？","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"它比很多西部州低。","h2":"Virginia 乡村州际公路标示的最高限速是 70 mph；一定要遵守标示的路牌。","p":"对。Virginia 乡村州际公路最高 70 mph。"},"vi":{"q":"Ở Virginia, tốc độ giới hạn cao nhất trên xa lộ liên tiểu bang (interstate) ở vùng nông thôn là bao nhiêu?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Nó thấp hơn ở nhiều tiểu bang miền tây.","h2":"Tốc độ giới hạn cao nhất ghi trên biển ở xa lộ liên tiểu bang vùng nông thôn của Virginia là 70 mph; luôn làm theo biển báo.","p":"Đúng. Xa lộ liên tiểu bang vùng nông thôn ở Virginia lên đến 70 mph."},"tl":{"q":"Sa Virginia, ano ang pinakamataas na speed limit sa mga rural interstate?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Mas mababa ito kaysa sa maraming estado sa kanluran.","h2":"Ang pinakamataas na nakapaskil na limit sa mga rural interstate ng Virginia ay 70 mph; laging sundin ang mga nakapaskil na sign.","p":"Tama. Hanggang 70 mph ang mga rural interstate sa Virginia."},"ar":{"q":"في Virginia، ما أعلى حد للسرعة على الطرق السريعة بين الولايات (interstate) في المناطق الريفية؟","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"هو أقل مما في كثير من الولايات الغربية.","h2":"أعلى حد مكتوب على الطرق السريعة بين الولايات في المناطق الريفية في Virginia هو 70 mph؛ اتبع دائمًا اللافتات المكتوبة.","p":"صحيح. الطرق السريعة الريفية في Virginia تصل إلى 70 mph."},"ref":{"doc":"VA","page":null}},{"id":"va-020","scope":"VA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Virginia, on a highway with two lanes in your direction, you approach a stopped vehicle with flashing lights. What should you do?","o":["Change to a lane not next to it, or slow down if that is unsafe","Stop in your lane until it leaves","Speed up to pass it quickly","Flash your lights and keep going"],"h1":"First try to give it a whole lane of space.","h2":"Virginia's move-over law asks you to change to a lane not next to the stopped vehicle when safe, and if you cannot, to slow down and pass with care.","p":"Right. Move over, or slow down if you cannot."},"es":{"q":"En Virginia, en una carretera con dos carriles en su dirección, usted se acerca a un vehículo detenido con luces intermitentes. ¿Qué debe hacer?","o":["Pasarse a un carril que no esté junto a él, o bajar la velocidad si no es seguro","Pararse en su carril hasta que se vaya","Acelerar para pasarlo rápido","Hacer cambio de luces y seguir"],"h1":"Primero trate de dejarle un carril completo de espacio.","h2":"La ley de Virginia le pide pasarse a un carril que no esté junto al vehículo detenido cuando sea seguro, y si no puede, bajar la velocidad y pasar con cuidado.","p":"Correcto. Cámbiese de carril, o baje la velocidad si no puede."},"zh":{"q":"在 Virginia，你在同方向有两条车道的公路上，前面有一辆停着、亮着闪灯的车。你应该怎么做？","o":["换到不紧挨着它的车道；如果不安全就减速","在你的车道停下，等它离开","加速快快超过它","闪你的车灯然后继续开"],"h1":"先试着给它让出一整条车道。","h2":"Virginia 的让道法（move-over law）要求你在安全时换到不紧挨着停着车辆的车道；如果做不到，就减速并小心开过去。","p":"对。让出车道；做不到就减速。"},"vi":{"q":"Ở Virginia, trên xa lộ có hai làn cùng chiều với bạn, bạn đến gần một xe đang dừng có đèn nhấp nháy. Bạn nên làm gì?","o":["Chuyển sang làn không sát bên xe đó, hoặc chạy chậm lại nếu chuyển làn không an toàn","Dừng lại trong làn của bạn cho đến khi xe đó đi","Tăng tốc để vượt qua nhanh","Nháy đèn rồi chạy tiếp"],"h1":"Trước hết hãy cố chừa cho xe đó cả một làn đường.","h2":"Luật nhường làn (move-over law) của Virginia yêu cầu bạn chuyển sang làn không sát bên xe đang dừng khi an toàn, và nếu không thể, hãy chạy chậm lại và đi qua cẩn thận.","p":"Đúng. Chuyển làn, hoặc chạy chậm lại nếu không thể."},"tl":{"q":"Sa Virginia, sa highway na may dalawang lane sa direksyon mo, may papalapit kang nakahintong sasakyan na may kumikislap na ilaw. Ano ang dapat mong gawin?","o":["Lumipat sa lane na hindi katabi nito, o bumagal kung hindi ligtas lumipat","Huminto sa lane mo hanggang umalis ito","Bumilis para malampasan ito agad","Ikislap ang ilaw mo at magpatuloy"],"h1":"Subukan munang bigyan ito ng isang buong lane na espasyo.","h2":"Ang move-over law ng Virginia ay humihiling na lumipat ka sa lane na hindi katabi ng nakahintong sasakyan kapag ligtas, at kung hindi mo kaya, bumagal at dumaan nang maingat.","p":"Tama. Lumipat ng lane, o bumagal kung hindi kaya."},"ar":{"q":"في Virginia، على طريق سريع فيه حارتان في اتجاهك، تقترب من سيارة متوقفة أضواؤها تومض. ماذا يجب أن تفعل؟","o":["انتقل إلى حارة غير ملاصقة لها، أو خفّف السرعة إذا كان الانتقال غير آمن","توقّف في حارتك حتى تذهب","زِد السرعة لتتجاوزها بسرعة","أومِض بأضوائك واستمر"],"h1":"حاول أولًا أن تترك لها حارة كاملة.","h2":"قانون الابتعاد (move-over law) في Virginia يطلب منك أن تنتقل إلى حارة غير ملاصقة للسيارة المتوقفة عندما يكون ذلك آمنًا، وإذا لم تستطع، أن تخفّف السرعة وتمر بحذر.","p":"صحيح. ابتعد بحارة، أو خفّف السرعة إذا لم تستطع."},"ref":{"doc":"VA","page":16}},{"id":"va-021","scope":"VA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Virginia, the move-over law also covers which stopped vehicles?","o":["Only police cars","Only school buses","Any vehicle with hazard lights, flares or warning signs","Only vehicles from the power company"],"h1":"Think of an ordinary car with its flashers on.","h2":"Virginia's move-over law also covers any stopped vehicle that shows hazard lights, flares or warning signs, not only emergency vehicles.","p":"Right. It covers any vehicle with hazard lights, flares or warning signs."},"es":{"q":"En Virginia, ¿qué otros vehículos detenidos protege también la ley de cambiarse de carril?","o":["Solo los carros de policía","Solo los autobuses escolares","Cualquier vehículo con luces de emergencia, bengalas o señales de aviso","Solo los vehículos de la compañía eléctrica"],"h1":"Piense en un carro común con las luces intermitentes encendidas.","h2":"En Virginia, la ley de cambiarse de carril también protege a cualquier vehículo detenido que muestre luces de emergencia, bengalas o señales de advertencia, no solo a los vehículos de emergencia.","p":"Correcto. Protege a cualquier vehículo con luces de emergencia, bengalas o señales."},"zh":{"q":"在 Virginia，让道法（move-over law）也适用于哪些停着的车？","o":["只有警车","只有校车","任何亮着危险警示灯、放了照明弹或警告牌的车","只有电力公司的车"],"h1":"想一想一辆亮着双闪灯的普通汽车。","h2":"Virginia 的让道法也适用于任何亮着危险警示灯、放了照明弹或警告牌的停着的车，不只是紧急车辆。","p":"对。适用于任何亮着危险警示灯、放了照明弹或警告牌的车。"},"vi":{"q":"Ở Virginia, luật nhường làn (move-over law) cũng áp dụng cho những xe đang dừng nào?","o":["Chỉ xe cảnh sát","Chỉ xe buýt trường học","Bất kỳ xe nào bật đèn báo nguy hiểm, đặt pháo sáng hoặc biển cảnh báo","Chỉ xe của công ty điện"],"h1":"Hãy nghĩ đến một chiếc xe bình thường đang bật đèn nháy.","h2":"Luật nhường làn của Virginia cũng áp dụng cho bất kỳ xe đang dừng nào bật đèn báo nguy hiểm, đặt pháo sáng hoặc biển cảnh báo, không chỉ xe khẩn cấp.","p":"Đúng. Luật áp dụng cho bất kỳ xe nào bật đèn báo nguy hiểm, đặt pháo sáng hoặc biển cảnh báo."},"tl":{"q":"Sa Virginia, saklaw din ng move-over law ang aling mga nakahintong sasakyan?","o":["Mga sasakyan ng pulis lang","Mga school bus lang","Anumang sasakyan na may hazard lights, flare o warning sign","Mga sasakyan lang ng kompanya ng kuryente"],"h1":"Isipin ang isang ordinaryong kotse na nakabukas ang flashers.","h2":"Saklaw din ng move-over law ng Virginia ang anumang nakahintong sasakyan na may hazard lights, flare o warning sign, hindi lang mga emergency vehicle.","p":"Tama. Saklaw nito ang anumang sasakyan na may hazard lights, flare o warning sign."},"ar":{"q":"في Virginia، قانون الابتعاد (move-over law) يشمل أيضًا أي سيارات متوقفة؟","o":["سيارات الشرطة فقط","الحافلات المدرسية فقط","أي سيارة تُشغّل أضواء التحذير أو تضع مشاعل أو لافتات تحذير","سيارات شركة الكهرباء فقط"],"h1":"فكّر في سيارة عادية أضواء التحذير فيها تعمل.","h2":"قانون الابتعاد في Virginia يشمل أيضًا أي سيارة متوقفة تُشغّل أضواء التحذير أو تضع مشاعل أو لافتات تحذير، وليس سيارات الطوارئ فقط.","p":"صحيح. يشمل أي سيارة تُشغّل أضواء التحذير أو تضع مشاعل أو لافتات تحذير."},"ref":{"doc":"VA","page":16}},{"id":"va-022","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, for policies issued or renewed since January 1, 2025, what is the minimum liability insurance?","o":["$30,000 / $60,000 / $20,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $20,000","$100,000 / $300,000 / $100,000"],"h1":"The amounts went up in 2025 from 30/60/20.","h2":"Virginia policies issued or renewed since January 1, 2025 must have at least $50,000 for injury to one person, $100,000 per crash and $25,000 for property damage.","p":"Right. Virginia's minimum is now 50/100/25."},"es":{"q":"En Virginia, para las pólizas emitidas o renovadas desde el 1 de enero de 2025, ¿cuál es el seguro de responsabilidad mínimo?","o":["$30,000 / $60,000 / $20,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $20,000","$100,000 / $300,000 / $100,000"],"h1":"Los montos subieron en 2025 desde 30/60/20.","h2":"Las pólizas de Virginia emitidas o renovadas desde el 1 de enero de 2025 deben tener por lo menos $50,000 por lesiones a una persona, $100,000 por choque y $25,000 por daños a la propiedad.","p":"Correcto. El mínimo en Virginia ahora es 50/100/25."},"zh":{"q":"在 Virginia，从 2025 年 1 月 1 日起签发或续保的保单，最低责任保险是多少？","o":["$30,000 / $60,000 / $20,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $20,000","$100,000 / $300,000 / $100,000"],"h1":"2025 年金额从 30/60/20 提高了。","h2":"Virginia 从 2025 年 1 月 1 日起签发或续保的保单，必须至少有：每人受伤 $50,000、每次车祸 $100,000、财产损失 $25,000。","p":"对。Virginia 现在的最低标准是 50/100/25。"},"vi":{"q":"Ở Virginia, với hợp đồng bảo hiểm được cấp hoặc gia hạn từ ngày 1 tháng 1 năm 2025, mức bảo hiểm trách nhiệm tối thiểu là bao nhiêu?","o":["$30,000 / $60,000 / $20,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $20,000","$100,000 / $300,000 / $100,000"],"h1":"Các mức này đã tăng lên vào năm 2025 từ 30/60/20.","h2":"Hợp đồng bảo hiểm ở Virginia được cấp hoặc gia hạn từ ngày 1 tháng 1 năm 2025 phải có ít nhất $50,000 cho thương tích của một người, $100,000 cho mỗi tai nạn và $25,000 cho thiệt hại tài sản.","p":"Đúng. Mức tối thiểu của Virginia bây giờ là 50/100/25."},"tl":{"q":"Sa Virginia, para sa mga policy na inilabas o ni-renew mula Enero 1, 2025, ano ang pinakamababang liability insurance?","o":["$30,000 / $60,000 / $20,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $20,000","$100,000 / $300,000 / $100,000"],"h1":"Tumaas ang mga halaga noong 2025 mula 30/60/20.","h2":"Ang mga policy sa Virginia na inilabas o ni-renew mula Enero 1, 2025 ay dapat may hindi bababa sa $50,000 para sa pinsala sa isang tao, $100,000 bawat aksidente at $25,000 para sa pinsala sa ari-arian.","p":"Tama. 50/100/25 na ngayon ang minimum ng Virginia."},"ar":{"q":"في Virginia، للوثائق التي صدرت أو جُدّدت منذ 1 يناير 2025، ما الحد الأدنى لتأمين المسؤولية؟","o":["$30,000 / $60,000 / $20,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $20,000","$100,000 / $300,000 / $100,000"],"h1":"المبالغ ارتفعت في 2025 من 30/60/20.","h2":"وثائق التأمين في Virginia التي صدرت أو جُدّدت منذ 1 يناير 2025 يجب أن يكون فيها على الأقل $50,000 لإصابة شخص واحد، و$100,000 لكل حادث، و$25,000 لأضرار الممتلكات.","p":"صحيح. الحد الأدنى في Virginia الآن 50/100/25."},"ref":{"doc":"VA","page":null}},{"id":"va-023","scope":"VA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Virginia, since July 1, 2024, what must a vehicle owner have to register a car?","o":["A $500 uninsured motor vehicle fee","A clean driving record","A safety course certificate","Insurance that meets the state minimum"],"h1":"Paying a fee instead is no longer an option.","h2":"Since July 1, 2024, Virginia no longer lets owners pay a fee to drive uninsured, so every registered vehicle must carry insurance that meets the state minimum.","p":"Right. Insurance is now required to register."},"es":{"q":"En Virginia, desde el 1 de julio de 2024, ¿qué debe tener el dueño de un vehículo para registrarlo?","o":["La cuota de $500 por vehículo sin seguro","Un historial de manejo limpio","Un certificado de curso de seguridad","Un seguro que cumpla el mínimo del estado"],"h1":"Pagar una cuota en su lugar ya no es una opción.","h2":"Desde el 1 de julio de 2024, Virginia ya no permite pagar una cuota para manejar sin seguro, así que todo vehículo registrado debe tener un seguro que cumpla el mínimo del estado.","p":"Correcto. Ahora se necesita seguro para registrar."},"zh":{"q":"在 Virginia，从 2024 年 7 月 1 日起，车主必须有什么才能登记汽车？","o":["$500 的无保险车辆费","没有违规的驾驶记录","安全课程证书","符合州最低标准的保险"],"h1":"不能再用付费来代替了。","h2":"从 2024 年 7 月 1 日起，Virginia 不再允许车主付费后无保险开车，所以每辆登记的车都必须有符合州最低标准的保险。","p":"对。现在登记汽车必须有保险。"},"vi":{"q":"Ở Virginia, từ ngày 1 tháng 7 năm 2024, chủ xe phải có gì để đăng ký xe?","o":["Phí xe không bảo hiểm $500","Hồ sơ lái xe không vi phạm","Giấy chứng nhận khóa học an toàn","Bảo hiểm đạt mức tối thiểu của tiểu bang"],"h1":"Không còn được trả phí thay cho bảo hiểm nữa.","h2":"Từ ngày 1 tháng 7 năm 2024, Virginia không còn cho chủ xe trả phí để lái xe không có bảo hiểm, nên mọi xe đã đăng ký phải có bảo hiểm đạt mức tối thiểu của tiểu bang.","p":"Đúng. Bây giờ phải có bảo hiểm mới đăng ký xe được."},"tl":{"q":"Sa Virginia, mula Hulyo 1, 2024, ano ang dapat mayroon ang may-ari ng sasakyan para mairehistro ang kotse?","o":["$500 na uninsured motor vehicle fee","Malinis na driving record","Sertipiko ng safety course","Insurance na umaabot sa minimum ng estado"],"h1":"Hindi na puwedeng magbayad ng fee bilang kapalit.","h2":"Mula Hulyo 1, 2024, hindi na pinapayagan ng Virginia ang mga may-ari na magbayad ng fee para magmaneho nang walang insurance, kaya bawat rehistradong sasakyan ay dapat may insurance na umaabot sa minimum ng estado.","p":"Tama. Kailangan na ang insurance para makapagrehistro."},"ar":{"q":"في Virginia، منذ 1 يوليو 2024، ماذا يجب أن يكون عند مالك السيارة لتسجيلها؟","o":["رسم $500 للسيارة غير المؤمَّنة","سجل قيادة نظيف","شهادة دورة سلامة","تأمين يحقق الحد الأدنى للولاية"],"h1":"دفع رسم بدلًا من ذلك لم يعد ممكنًا.","h2":"منذ 1 يوليو 2024، لم تعد Virginia تسمح للمالكين بدفع رسم للقيادة بدون تأمين، لذلك يجب أن يكون لكل سيارة مسجّلة تأمين يحقق الحد الأدنى للولاية.","p":"صحيح. التأمين مطلوب الآن للتسجيل."},"ref":{"doc":"VA","page":null}},{"id":"va-024","scope":"VA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Virginia, how many of the 10 road sign questions on the knowledge exam must you answer correctly?","o":["All 10","8 of them","7 of them","5 of them"],"h1":"Not a single mistake is allowed in this part.","h2":"On the Virginia knowledge exam you must answer all 10 road sign questions correctly before the general knowledge part is scored.","p":"Right. All 10 sign questions must be correct."},"es":{"q":"En Virginia, ¿cuántas de las 10 preguntas sobre señales del examen de conocimientos debe contestar bien?","o":["Las 10","8 de ellas","7 de ellas","5 de ellas"],"h1":"En esta parte no se permite ni un solo error.","h2":"En el examen de conocimientos de Virginia usted debe contestar bien las 10 preguntas sobre señales antes de que se califique la parte de conocimientos generales.","p":"Correcto. Las 10 preguntas sobre señales deben estar bien."},"zh":{"q":"在 Virginia 的笔试中，10 道路牌题你必须答对几道？","o":["全部 10 道","8 道","7 道","5 道"],"h1":"这一部分一个错误都不可以有。","h2":"在 Virginia 的笔试中，你必须答对全部 10 道路牌题，才会计算一般知识部分的分数。","p":"对。10 道路牌题必须全部答对。"},"vi":{"q":"Ở Virginia, trong bài thi kiến thức, bạn phải trả lời đúng bao nhiêu câu trong 10 câu về biển báo?","o":["Cả 10 câu","8 câu","7 câu","5 câu"],"h1":"Phần này không được sai câu nào.","h2":"Trong bài thi kiến thức ở Virginia, bạn phải trả lời đúng cả 10 câu về biển báo thì phần kiến thức chung mới được chấm điểm.","p":"Đúng. Cả 10 câu biển báo phải đúng."},"tl":{"q":"Sa Virginia, ilan sa 10 tanong tungkol sa road sign sa knowledge exam ang dapat mong masagot nang tama?","o":["Lahat ng 10","8 sa mga ito","7 sa mga ito","5 sa mga ito"],"h1":"Walang kahit isang mali ang puwede sa bahaging ito.","h2":"Sa knowledge exam ng Virginia, dapat mong masagot nang tama ang lahat ng 10 tanong tungkol sa road sign bago bigyan ng marka ang bahaging general knowledge.","p":"Tama. Dapat tama ang lahat ng 10 tanong sa sign."},"ar":{"q":"في Virginia، كم سؤالًا من أسئلة لافتات الطريق العشرة في الامتحان النظري يجب أن تجيب عنه بشكل صحيح؟","o":["كل الأسئلة الـ10","8 منها","7 منها","5 منها"],"h1":"لا يُسمح بأي خطأ في هذا الجزء.","h2":"في الامتحان النظري في Virginia يجب أن تجيب عن كل أسئلة لافتات الطريق الـ10 بشكل صحيح قبل أن يُصحَّح جزء المعلومات العامة.","p":"صحيح. يجب أن تكون كل أسئلة اللافتات الـ10 صحيحة."},"ref":{"doc":"VA","page":3}},{"id":"va-025","scope":"VA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Virginia, the general knowledge part of the exam has 30 questions. How many must you answer correctly?","o":["18","20","24","28"],"h1":"You need 80 percent.","h2":"To pass the general knowledge part of the Virginia exam you must answer at least 24 of the 30 questions correctly, which is 80 percent.","p":"Right. You need 24 of 30."},"es":{"q":"En Virginia, la parte de conocimientos generales del examen tiene 30 preguntas. ¿Cuántas debe contestar bien?","o":["18","20","24","28"],"h1":"Necesita el 80 por ciento.","h2":"Para aprobar la parte de conocimientos generales del examen de Virginia debe contestar bien por lo menos 24 de las 30 preguntas, es decir, el 80 por ciento.","p":"Correcto. Necesita 24 de 30."},"zh":{"q":"在 Virginia，笔试的一般知识部分有 30 道题。你必须答对几道？","o":["18","20","24","28"],"h1":"你需要 80%。","h2":"要通过 Virginia 笔试的一般知识部分，你必须在 30 道题中至少答对 24 道，也就是 80%。","p":"对。30 道题中要答对 24 道。"},"vi":{"q":"Ở Virginia, phần kiến thức chung của bài thi có 30 câu. Bạn phải trả lời đúng bao nhiêu câu?","o":["18","20","24","28"],"h1":"Bạn cần 80%.","h2":"Để đậu phần kiến thức chung của bài thi ở Virginia, bạn phải trả lời đúng ít nhất 24 trong 30 câu, tức là 80%.","p":"Đúng. Bạn cần 24 trên 30 câu."},"tl":{"q":"Sa Virginia, may 30 tanong ang bahaging general knowledge ng exam. Ilan ang dapat mong masagot nang tama?","o":["18","20","24","28"],"h1":"Kailangan mo ng 80 porsiyento.","h2":"Para makapasa sa bahaging general knowledge ng exam sa Virginia, dapat mong masagot nang tama ang hindi bababa sa 24 sa 30 tanong, na 80 porsiyento.","p":"Tama. Kailangan mo ng 24 sa 30."},"ar":{"q":"في Virginia، جزء المعلومات العامة في الامتحان فيه 30 سؤالًا. كم سؤالًا يجب أن تجيب عنه بشكل صحيح؟","o":["18","20","24","28"],"h1":"تحتاج إلى 80 بالمئة.","h2":"لتنجح في جزء المعلومات العامة في امتحان Virginia يجب أن تجيب عن 24 سؤالًا على الأقل من 30 بشكل صحيح، أي 80 بالمئة.","p":"صحيح. تحتاج إلى 24 من 30."},"ref":{"doc":"VA","page":null}},{"id":"va-026","scope":"VA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Virginia, what must you do after failing the knowledge exam three times?","o":["Wait one full year","Pay a $500 fine","Bring a lawyer to the next test","Complete a driver education classroom course"],"h1":"The state wants you to study with a teacher first.","h2":"After three failed knowledge exams in Virginia, you must complete a driver education classroom course before you may take the exam again.","p":"Right. After three failures, take a classroom course first."},"es":{"q":"En Virginia, ¿qué debe hacer después de reprobar tres veces el examen de conocimientos?","o":["Esperar un año completo","Pagar una multa de $500","Llevar un abogado al próximo examen","Completar un curso de educación vial en el aula"],"h1":"El estado quiere que primero estudie con un maestro.","h2":"Después de reprobar tres veces el examen de conocimientos en Virginia, usted debe completar un curso de educación vial en el aula antes de volver a presentarlo.","p":"Correcto. Después de tres fallos, primero tome un curso en el aula."},"zh":{"q":"在 Virginia，笔试考了三次没通过后，你必须做什么？","o":["等整整一年","付 $500 罚款","下次考试带律师","完成驾驶教育课堂课程"],"h1":"州政府希望你先跟老师学习。","h2":"在 Virginia，笔试三次没通过后，你必须先完成驾驶教育课堂课程，才可以再考。","p":"对。三次没通过后，要先上课堂课程。"},"vi":{"q":"Ở Virginia, bạn phải làm gì sau khi trượt bài thi kiến thức ba lần?","o":["Chờ trọn một năm","Trả $500 tiền phạt","Mang luật sư đến lần thi sau","Hoàn thành khóa học lái xe trên lớp"],"h1":"Tiểu bang muốn bạn học với giáo viên trước.","h2":"Sau ba lần trượt bài thi kiến thức ở Virginia, bạn phải hoàn thành khóa học lái xe trên lớp rồi mới được thi lại.","p":"Đúng. Sau ba lần trượt, hãy học khóa trên lớp trước."},"tl":{"q":"Sa Virginia, ano ang dapat mong gawin pagkatapos bumagsak nang tatlong beses sa knowledge exam?","o":["Maghintay ng buong isang taon","Magbayad ng $500 na multa","Magdala ng abogado sa susunod na exam","Tapusin ang driver education classroom course"],"h1":"Gusto ng estado na mag-aral ka muna kasama ang guro.","h2":"Pagkatapos ng tatlong bagsak na knowledge exam sa Virginia, dapat mong tapusin ang driver education classroom course bago ka makapag-exam ulit.","p":"Tama. Pagkatapos ng tatlong bagsak, kumuha muna ng classroom course."},"ar":{"q":"في Virginia، ماذا يجب أن تفعل بعد الرسوب في الامتحان النظري ثلاث مرات؟","o":["أن تنتظر سنة كاملة","أن تدفع غرامة $500","أن تُحضر محاميًا إلى الامتحان القادم","أن تُكمل دورة تعليم القيادة في الصف"],"h1":"الولاية تريد أن تدرس مع معلّم أولًا.","h2":"بعد الرسوب في الامتحان النظري ثلاث مرات في Virginia، يجب أن تُكمل دورة تعليم القيادة في الصف قبل أن يُسمح لك بالامتحان مرة أخرى.","p":"صحيح. بعد ثلاث مرات رسوب، خذ دورة في الصف أولًا."},"ref":{"doc":"VA","page":3}},{"id":"va-027","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, can you take the driver knowledge exam in Spanish?","o":["No, only in English","Yes, Spanish is one of the offered languages","Only with your own translator","Only in large cities"],"h1":"The DMV offers it in many languages.","h2":"The Virginia DMV offers the driver knowledge exam in Spanish and other languages, and translators may not be used for the languages that are offered.","p":"Right. The exam is offered in Spanish."},"es":{"q":"En Virginia, ¿puede presentar el examen de conocimientos de manejo en español?","o":["No, solo en inglés","Sí, el español es uno de los idiomas ofrecidos","Solo con su propio traductor","Solo en las ciudades grandes"],"h1":"El DMV lo ofrece en muchos idiomas.","h2":"El DMV de Virginia ofrece el examen de conocimientos en español y en otros idiomas, y no se permiten traductores para los idiomas que se ofrecen.","p":"Correcto. El examen se ofrece en español."},"zh":{"q":"在 Virginia，可以用西班牙语考驾驶笔试吗？","o":["不行，只能用英语","可以，西班牙语是提供的语言之一","只能带自己的翻译","只在大城市可以"],"h1":"DMV 提供很多种语言。","h2":"Virginia DMV 提供西班牙语和其他语言的驾驶笔试；对于已提供的语言，不可以使用翻译员。","p":"对。笔试有西班牙语版本。"},"vi":{"q":"Ở Virginia, bạn có thể thi kiến thức lái xe bằng tiếng Tây Ban Nha không?","o":["Không, chỉ bằng tiếng Anh","Có, tiếng Tây Ban Nha là một trong các ngôn ngữ được cung cấp","Chỉ khi có người phiên dịch riêng","Chỉ ở các thành phố lớn"],"h1":"DMV cung cấp bài thi bằng nhiều ngôn ngữ.","h2":"DMV của Virginia cung cấp bài thi kiến thức lái xe bằng tiếng Tây Ban Nha và các ngôn ngữ khác, và không được dùng người phiên dịch cho các ngôn ngữ đã được cung cấp.","p":"Đúng. Bài thi có bằng tiếng Tây Ban Nha."},"tl":{"q":"Sa Virginia, puwede mo bang kunin ang driver knowledge exam sa Spanish?","o":["Hindi, sa English lang","Oo, isa ang Spanish sa mga inaalok na wika","Kung may sarili kang tagasalin lang","Sa malalaking lungsod lang"],"h1":"Inaalok ito ng DMV sa maraming wika.","h2":"Inaalok ng Virginia DMV ang driver knowledge exam sa Spanish at iba pang wika, at hindi puwedeng gumamit ng tagasalin para sa mga wikang inaalok.","p":"Tama. Inaalok ang exam sa Spanish."},"ar":{"q":"في Virginia، هل يمكنك أن تقدّم امتحان القيادة النظري باللغة الإسبانية؟","o":["لا، بالإنجليزية فقط","نعم، الإسبانية من اللغات المتوفرة","فقط مع مترجمك الخاص","فقط في المدن الكبيرة"],"h1":"إدارة المركبات (DMV) تقدّمه بلغات كثيرة.","h2":"إدارة المركبات في Virginia (Virginia DMV) تقدّم امتحان القيادة النظري بالإسبانية ولغات أخرى، ولا يُسمح باستخدام مترجمين للغات المتوفرة.","p":"صحيح. الامتحان متوفر بالإسبانية."},"ref":{"doc":"VA","page":null}},{"id":"va-028","scope":"VA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Virginia, how close may you follow an emergency vehicle that has its lights flashing?","o":["No closer than 100 feet","No closer than 500 feet","No closer than 50 feet","As close as you like if you are careful"],"h1":"The distance is longer than a city block.","h2":"In Virginia, you must never follow an emergency vehicle with flashing lights closer than 500 feet.","p":"Right. Stay at least 500 feet behind it."},"es":{"q":"En Virginia, ¿qué tan cerca puede seguir a un vehículo de emergencia con las luces encendidas?","o":["No más cerca de 100 pies","No más cerca de 500 pies","No más cerca de 50 pies","Tan cerca como quiera si tiene cuidado"],"h1":"La distancia es más larga que una cuadra.","h2":"En Virginia, nunca debe seguir a un vehículo de emergencia con luces intermitentes a menos de 500 pies.","p":"Correcto. Quédese por lo menos a 500 pies detrás."},"zh":{"q":"在 Virginia，跟在闪着灯的紧急车辆后面时，最近可以跟多近？","o":["不能近于 100 英尺","不能近于 500 英尺","不能近于 50 英尺","只要小心，多近都可以"],"h1":"这个距离比城市里的一个街区还长。","h2":"在 Virginia，跟在闪着灯的紧急车辆后面时，绝不能近于 500 英尺。","p":"对。至少在它后面 500 英尺。"},"vi":{"q":"Ở Virginia, bạn được đi theo sau xe khẩn cấp đang nháy đèn gần đến mức nào?","o":["Không gần hơn 100 feet","Không gần hơn 500 feet","Không gần hơn 50 feet","Gần bao nhiêu cũng được nếu bạn cẩn thận"],"h1":"Khoảng cách này dài hơn một dãy phố trong thành phố.","h2":"Ở Virginia, bạn không bao giờ được đi theo sau xe khẩn cấp đang nháy đèn gần hơn 500 feet.","p":"Đúng. Hãy ở phía sau xe đó ít nhất 500 feet."},"tl":{"q":"Sa Virginia, gaano kalapit ka puwedeng sumunod sa emergency vehicle na kumikislap ang mga ilaw?","o":["Hindi lalapit sa 100 talampakan","Hindi lalapit sa 500 talampakan","Hindi lalapit sa 50 talampakan","Kahit gaano kalapit basta mag-ingat ka"],"h1":"Mas mahaba ang layo kaysa sa isang city block.","h2":"Sa Virginia, hindi ka dapat sumunod sa emergency vehicle na kumikislap ang mga ilaw nang mas malapit sa 500 talampakan.","p":"Tama. Manatili nang hindi bababa sa 500 talampakan sa likod nito."},"ar":{"q":"في Virginia، إلى أي مدى يمكنك أن تقترب وأنت تسير خلف مركبة طوارئ أضواؤها تومض؟","o":["ليس أقرب من 100 قدم","ليس أقرب من 500 قدم","ليس أقرب من 50 قدمًا","بالقرب الذي تريده إذا كنت حذرًا"],"h1":"المسافة أطول من شارع واحد في المدينة.","h2":"في Virginia، لا يجوز لك أبدًا أن تسير خلف مركبة طوارئ أضواؤها تومض على مسافة أقرب من 500 قدم.","p":"صحيح. ابقَ خلفها بمسافة 500 قدم على الأقل."},"ref":{"doc":"VA","page":16}},{"id":"va-029","scope":"VA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Virginia, you want to pass a bicyclist, but the lane is too narrow to leave 3 feet. What must you do?","o":["Honk and pass anyway","Drive in the bike lane to pass","Pass quickly with less space","Change lanes to pass safely"],"h1":"The 3-foot rule still applies.","h2":"In Virginia, you must give a bicyclist at least three feet when passing, and if the lane is too narrow for that, you must change lanes to pass.","p":"Right. Change lanes if you cannot leave 3 feet."},"es":{"q":"En Virginia, quiere rebasar a un ciclista, pero el carril es muy angosto para dejar 3 pies. ¿Qué debe hacer?","o":["Tocar la bocina y rebasar de todos modos","Usar el carril de bicicletas para rebasar","Rebasar rápido con menos espacio","Cambiarse de carril para rebasar con seguridad"],"h1":"La regla de los 3 pies sigue vigente.","h2":"En Virginia, debe dejar por lo menos tres pies al rebasar a un ciclista, y si el carril es muy angosto para eso, debe cambiarse de carril para rebasar.","p":"Correcto. Cámbiese de carril si no puede dejar 3 pies."},"zh":{"q":"在 Virginia，你想超过一个骑自行车的人，但车道太窄，留不出 3 英尺。你必须怎么做？","o":["按喇叭，照样超车","开进自行车道去超车","留更小的空间快速超过","换车道，安全地超车"],"h1":"3 英尺的规定仍然有效。","h2":"在 Virginia，超过骑自行车的人时必须留出至少 3 英尺；如果车道太窄做不到，你必须换车道再超车。","p":"对。留不出 3 英尺就换车道。"},"vi":{"q":"Ở Virginia, bạn muốn vượt người đi xe đạp, nhưng làn đường quá hẹp để chừa 3 feet. Bạn phải làm gì?","o":["Bấm còi và cứ vượt","Chạy vào làn xe đạp để vượt","Vượt nhanh với khoảng cách ít hơn","Chuyển làn để vượt an toàn"],"h1":"Quy định 3 feet vẫn áp dụng.","h2":"Ở Virginia, khi vượt người đi xe đạp bạn phải chừa ít nhất 3 feet, và nếu làn đường quá hẹp để làm vậy thì bạn phải chuyển làn để vượt.","p":"Đúng. Nếu không chừa được 3 feet thì hãy chuyển làn."},"tl":{"q":"Sa Virginia, gusto mong lampasan ang isang nagbibisikleta, pero masyadong makitid ang lane para mag-iwan ng 3 talampakan. Ano ang dapat mong gawin?","o":["Bumusina at lumampas pa rin","Magmaneho sa bike lane para lumampas","Lumampas nang mabilis na mas maliit ang agwat","Lumipat ng lane para ligtas na lumampas"],"h1":"May bisa pa rin ang patakaran na 3 talampakan.","h2":"Sa Virginia, dapat kang mag-iwan ng hindi bababa sa 3 talampakan kapag lumalampas sa nagbibisikleta, at kung masyadong makitid ang lane para doon, dapat kang lumipat ng lane para lumampas.","p":"Tama. Lumipat ng lane kung hindi ka makapag-iwan ng 3 talampakan."},"ar":{"q":"في Virginia، تريد أن تتجاوز راكب دراجة، لكن الحارة ضيقة جدًا ولا تسمح بترك 3 أقدام. ماذا يجب أن تفعل؟","o":["تطلق البوق وتتجاوز على أي حال","تسير في حارة الدراجات لتتجاوز","تتجاوز بسرعة مع مسافة أقل","تغيّر الحارة لتتجاوز بأمان"],"h1":"قاعدة الأقدام الثلاثة ما زالت سارية.","h2":"في Virginia، يجب أن تترك 3 أقدام على الأقل عند تجاوز راكب دراجة، وإذا كانت الحارة ضيقة جدًا لذلك، يجب أن تغيّر الحارة لتتجاوز.","p":"صحيح. غيّر الحارة إذا لم تستطع ترك 3 أقدام."},"ref":{"doc":"VA","page":20}},{"id":"va-030","scope":"VA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Virginia, on a two-lane road, you come up on a stopped trash truck collecting garbage. What must you do?","o":["Slow to 10 mph below the limit and pass at least 2 feet away","Keep your speed and pass close to it","Stop and wait until it drives away","Honk so the workers move aside"],"h1":"You need to lower your speed and leave a gap.","h2":"In Virginia, if you cannot change lanes around a stopped trash truck, you must slow to 10 mph below the speed limit and pass at least two feet to its left.","p":"Right. Slow down by 10 mph and leave at least 2 feet."},"es":{"q":"En Virginia, en una vía de dos carriles, se acerca a un camión de basura detenido que recoge basura. ¿Qué debe hacer?","o":["Bajar a 10 mph menos del límite y pasar a por lo menos 2 pies","Mantener su velocidad y pasar cerca","Detenerse y esperar a que se vaya","Tocar la bocina para que los trabajadores se aparten"],"h1":"Debe bajar la velocidad y dejar espacio.","h2":"En Virginia, si no puede cambiarse de carril junto a un camión de basura detenido, debe bajar a 10 mph menos del límite y pasar por lo menos a dos pies a su izquierda.","p":"Correcto. Baje 10 mph y deje por lo menos 2 pies."},"zh":{"q":"在 Virginia，在双车道的路上，你遇到一辆停着收垃圾的垃圾车。你必须怎么做？","o":["减速到比限速低 10 mph，并在至少 2 英尺外超过","保持车速，贴近它超过","停下来，等它开走","按喇叭让工人让开"],"h1":"你需要降低车速，并留出空隙。","h2":"在 Virginia，如果你不能换车道绕过停着的垃圾车，你必须减速到比限速低 10 mph，并在它左边至少 2 英尺外超过。","p":"对。减速 10 mph，并留出至少 2 英尺。"},"vi":{"q":"Ở Virginia, trên đường hai làn, bạn gặp một xe rác đang dừng để gom rác. Bạn phải làm gì?","o":["Giảm xuống thấp hơn tốc độ giới hạn 10 mph và vượt cách xa ít nhất 2 feet","Giữ tốc độ và vượt sát xe đó","Dừng lại và chờ đến khi xe chạy đi","Bấm còi để công nhân tránh ra"],"h1":"Bạn cần giảm tốc độ và chừa khoảng cách.","h2":"Ở Virginia, nếu bạn không thể chuyển làn để đi vòng qua xe rác đang dừng, bạn phải giảm xuống thấp hơn tốc độ giới hạn 10 mph và vượt cách bên trái xe đó ít nhất 2 feet.","p":"Đúng. Giảm 10 mph và chừa ít nhất 2 feet."},"tl":{"q":"Sa Virginia, sa kalsadang may dalawang lane, nakasalubong mo ang nakahintong trak ng basura na nangongolekta ng basura. Ano ang dapat mong gawin?","o":["Bumagal sa 10 mph na mas mababa sa limit at lumampas nang hindi bababa sa 2 talampakan ang layo","Panatilihin ang bilis at lumampas nang malapit dito","Huminto at maghintay hanggang umalis ito","Bumusina para tumabi ang mga manggagawa"],"h1":"Kailangan mong bawasan ang bilis at mag-iwan ng agwat.","h2":"Sa Virginia, kung hindi ka makalipat ng lane para iwasan ang nakahintong trak ng basura, dapat kang bumagal sa 10 mph na mas mababa sa speed limit at lumampas nang hindi bababa sa 2 talampakan sa kaliwa nito.","p":"Tama. Bumagal nang 10 mph at mag-iwan ng hindi bababa sa 2 talampakan."},"ar":{"q":"في Virginia، على طريق بحارتين، تصل إلى شاحنة قمامة متوقفة تجمع القمامة. ماذا يجب أن تفعل؟","o":["تخفّض سرعتك إلى أقل من الحد بمقدار 10 mph وتتجاوز على بُعد 2 قدم على الأقل","تحافظ على سرعتك وتتجاوز قريبًا منها","تتوقف وتنتظر حتى تبتعد","تطلق البوق ليبتعد العمّال"],"h1":"عليك أن تخفّض سرعتك وأن تترك مسافة.","h2":"في Virginia، إذا لم تستطع تغيير الحارة لتمرّ حول شاحنة قمامة متوقفة، يجب أن تخفّض سرعتك إلى أقل من الحد الأقصى بمقدار 10 mph وأن تتجاوز على بُعد 2 قدم على الأقل إلى يسارها.","p":"صحيح. خفّف سرعتك بمقدار 10 mph واترك 2 قدم على الأقل."},"ref":{"doc":"VA","page":16}},{"id":"va-031","scope":"VA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Virginia, when must you turn on your headlights during the day?","o":["Only on the interstate","Only in a work zone","When your wipers are on because of bad weather","Only when it snows"],"h1":"Think about rain and what you use to clear the windshield.","h2":"In Virginia, you must use your headlights whenever you use your windshield wipers because of bad weather, and when rain, fog or snow cut visibility to 500 feet.","p":"Right. Wipers on for bad weather means headlights on."},"es":{"q":"En Virginia, ¿cuándo debe encender los faros durante el día?","o":["Solo en la autopista interestatal","Solo en una zona de obras","Cuando usa los limpiaparabrisas por mal tiempo","Solo cuando nieva"],"h1":"Piense en la lluvia y en lo que usa para limpiar el parabrisas.","h2":"En Virginia, debe usar los faros siempre que use los limpiaparabrisas por mal tiempo, y cuando la lluvia, la neblina o la nieve reducen la visibilidad a 500 pies.","p":"Correcto. Limpiaparabrisas por mal tiempo significa faros encendidos."},"zh":{"q":"在 Virginia，白天什么时候必须打开大灯？","o":["只在州际公路上","只在施工区","因为天气不好而开着雨刷的时候","只在下雪的时候"],"h1":"想一想下雨，以及你用什么来清理挡风玻璃。","h2":"在 Virginia，只要你因为天气不好而使用雨刷，就必须打开大灯；当雨、雾或雪让能见度降到 500 英尺时也必须打开。","p":"对。因为天气不好开雨刷，就要开大灯。"},"vi":{"q":"Ở Virginia, ban ngày khi nào bạn phải bật đèn pha?","o":["Chỉ trên xa lộ liên bang","Chỉ trong khu vực đang thi công","Khi bạn bật cần gạt nước vì thời tiết xấu","Chỉ khi có tuyết rơi"],"h1":"Hãy nghĩ đến trời mưa và thứ bạn dùng để làm sạch kính chắn gió.","h2":"Ở Virginia, bạn phải bật đèn pha mỗi khi dùng cần gạt nước vì thời tiết xấu, và khi mưa, sương mù hoặc tuyết làm tầm nhìn giảm còn 500 feet.","p":"Đúng. Bật cần gạt nước vì thời tiết xấu thì phải bật đèn pha."},"tl":{"q":"Sa Virginia, kailan mo dapat buksan ang headlights sa araw?","o":["Sa interstate lang","Sa work zone lang","Kapag naka-on ang wipers mo dahil sa masamang panahon","Kapag umuulan lang ng niyebe"],"h1":"Isipin ang ulan at ang ginagamit mo para linisin ang windshield.","h2":"Sa Virginia, dapat mong gamitin ang headlights tuwing ginagamit mo ang windshield wipers dahil sa masamang panahon, at kapag ang ulan, hamog o niyebe ay nagpababa ng visibility sa 500 talampakan.","p":"Tama. Kapag naka-on ang wipers dahil sa masamang panahon, dapat naka-on din ang headlights."},"ar":{"q":"في Virginia، متى يجب أن تشغّل المصابيح الأمامية أثناء النهار؟","o":["على الطريق السريع بين الولايات فقط","في منطقة أعمال الطرق فقط","عندما تكون المسّاحات تعمل بسبب سوء الطقس","عندما يتساقط الثلج فقط"],"h1":"فكّر في المطر وفي ما تستخدمه لتنظيف الزجاج الأمامي.","h2":"في Virginia، يجب أن تستخدم المصابيح الأمامية كلما استخدمت مسّاحات الزجاج الأمامي بسبب سوء الطقس، وعندما يقلّل المطر أو الضباب أو الثلج مدى الرؤية إلى 500 قدم.","p":"صحيح. إذا شغّلت المسّاحات بسبب سوء الطقس فشغّل المصابيح الأمامية."},"ref":{"doc":"VA","page":22}},{"id":"vt-001","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, what is the youngest age to get a learner's permit?","o":["14 years old","15 years old","16 years old","15 and a half years old"],"h1":"It is one year before the junior operator's license.","h2":"You can get a Vermont learner's permit at 15, then practice for at least a year before a junior operator's license.","p":"Right. The Vermont permit starts at 15."},"es":{"q":"En Vermont, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["14 años","15 años","16 años","15 años y medio"],"h1":"Es un año antes de la licencia de operador menor.","h2":"Usted puede obtener el permiso de aprendiz en Vermont a los 15 años y luego practicar por lo menos un año antes de la licencia de operador menor.","p":"Correcto. El permiso en Vermont empieza a los 15."},"zh":{"q":"在 Vermont，最小几岁可以拿到学习驾照（learner's permit）？","o":["14 岁","15 岁","16 岁","15 岁半"],"h1":"它比青少年驾照早一年。","h2":"在 Vermont，你 15 岁就可以拿到学习驾照，然后至少练习一年，才能拿青少年驾照（junior operator's license）。","p":"对。Vermont 的学习驾照从 15 岁开始。"},"vi":{"q":"Ở Vermont, tuổi nhỏ nhất để có giấy phép tập lái (learner's permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","15 tuổi rưỡi"],"h1":"Đó là một năm trước bằng lái thiếu niên.","h2":"Ở Vermont, bạn có thể có giấy phép tập lái lúc 15 tuổi, rồi tập ít nhất một năm trước khi có bằng lái thiếu niên (junior operator's license).","p":"Đúng. Giấy phép tập lái ở Vermont bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Vermont, ano ang pinakabatang edad para makakuha ng learner's permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","15 at kalahating taong gulang"],"h1":"Isang taon ito bago ang lisensya ng batang drayber.","h2":"Puwede kang kumuha ng learner's permit sa Vermont sa edad na 15, pagkatapos ay magsanay nang hindi bababa sa isang taon bago ang lisensya ng batang drayber (junior operator's license).","p":"Tama. Nagsisimula ang permit sa Vermont sa edad na 15."},"ar":{"q":"في Vermont، ما أصغر عمر للحصول على تصريح تعلّم القيادة (learner's permit)؟","o":["14 سنة","15 سنة","16 سنة","15 سنة ونصف"],"h1":"إنه قبل رخصة السائق الصغير بسنة واحدة.","h2":"يمكنك الحصول على تصريح تعلّم القيادة في Vermont في عمر 15 سنة، ثم تتدرّب سنة على الأقل قبل رخصة السائق الصغير (junior operator's license).","p":"صحيح. تصريح التعلّم في Vermont يبدأ من عمر 15 سنة."},"ref":{"doc":"VT","page":12}},{"id":"vt-002","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, a learner's permit holder may drive with which licensed person in the front seat?","o":["Any licensed driver age 18 or older","A licensed friend age 21 or older","Any passenger with a permit","A parent or guardian, a driving instructor, or a licensed adult age 25 or older"],"h1":"The adult must be older than in many other states, or a parent or teacher.","h2":"A Vermont permit holder must drive with a licensed parent or guardian, a certified driving instructor, or a licensed adult at least 25 years old beside them.","p":"Right. The supervisor must be a parent, guardian, instructor, or licensed adult 25 or older."},"es":{"q":"En Vermont, el titular de un permiso de aprendiz puede manejar con, ¿qué persona con licencia en el asiento delantero?","o":["Cualquier conductor con licencia de 18 años o más","Un amigo con licencia de 21 años o más","Cualquier pasajero con permiso","Su padre, madre o tutor, un instructor de manejo, o un adulto con licencia de 25 años o más"],"h1":"El adulto debe ser mayor que en muchos otros estados, o ser un padre o un maestro.","h2":"Quien tiene permiso en Vermont debe manejar con su padre, madre o tutor con licencia, un instructor de manejo certificado o un adulto con licencia de por lo menos 25 años a su lado.","p":"Correcto. El supervisor debe ser un padre, tutor, instructor o adulto con licencia de 25 años o más."},"zh":{"q":"在 Vermont，持学习驾照的人开车时，前座可以坐哪位有驾照的人？","o":["任何 18 岁或以上有驾照的人","21 岁或以上有驾照的朋友","任何有学习驾照的乘客","父母或监护人、驾驶教练，或 25 岁或以上有驾照的成年人"],"h1":"这个成年人的年龄要比很多州要求的大，或者是父母或老师。","h2":"在 Vermont，持学习驾照的人开车时，旁边必须坐着有驾照的父母或监护人、有资格的驾驶教练，或至少 25 岁、有驾照的成年人。","p":"对。陪同的人必须是父母、监护人、教练，或 25 岁或以上有驾照的成年人。"},"vi":{"q":"Ở Vermont, người có giấy phép tập lái được lái xe với người có bằng lái nào ngồi ghế trước?","o":["Bất kỳ ai có bằng lái từ 18 tuổi trở lên","Một người bạn có bằng lái từ 21 tuổi trở lên","Bất kỳ hành khách nào có giấy phép tập lái","Cha mẹ hoặc người giám hộ, giáo viên dạy lái xe, hoặc người lớn có bằng lái từ 25 tuổi trở lên"],"h1":"Người lớn phải lớn tuổi hơn so với nhiều tiểu bang khác, hoặc là cha mẹ hay giáo viên.","h2":"Ở Vermont, người có giấy phép tập lái phải lái xe với cha mẹ hoặc người giám hộ có bằng lái, giáo viên dạy lái xe có chứng chỉ, hoặc người lớn có bằng lái ít nhất 25 tuổi ngồi bên cạnh.","p":"Đúng. Người giám sát phải là cha mẹ, người giám hộ, giáo viên, hoặc người lớn có bằng lái từ 25 tuổi trở lên."},"tl":{"q":"Sa Vermont, puwedeng magmaneho ang may learner's permit kasama ang aling may lisensyang tao sa upuan sa harap?","o":["Sinumang may lisensyang drayber na edad 18 pataas","Isang kaibigang may lisensya na edad 21 pataas","Sinumang pasaherong may permit","Magulang o tagapag-alaga, guro sa pagmamaneho, o may lisensyang adulto na edad 25 pataas"],"h1":"Mas matanda ang adulto kaysa sa maraming ibang estado, o kaya magulang o guro.","h2":"Ang may permit sa Vermont ay dapat magmaneho kasama sa tabi ang may lisensyang magulang o tagapag-alaga, isang sertipikadong guro sa pagmamaneho, o may lisensyang adulto na hindi bababa sa 25 taong gulang.","p":"Tama. Ang kasama ay dapat magulang, tagapag-alaga, guro, o may lisensyang adulto na 25 pataas."},"ar":{"q":"في Vermont، يمكن لحامل تصريح التعلّم أن يقود مع أيّ شخص يحمل رخصة في المقعد الأمامي؟","o":["أي سائق يحمل رخصة وعمره 18 سنة أو أكثر","صديق يحمل رخصة وعمره 21 سنة أو أكثر","أي راكب معه تصريح تعلّم","أحد الوالدين أو الوصي، أو مدرّب قيادة، أو شخص بالغ يحمل رخصة وعمره 25 سنة أو أكثر"],"h1":"يجب أن يكون البالغ أكبر سنًّا مما في ولايات كثيرة أخرى، أو أن يكون أحد الوالدين أو معلّمًا.","h2":"يجب على حامل تصريح التعلّم في Vermont أن يقود وبجانبه أحد الوالدين أو الوصي يحمل رخصة، أو مدرّب قيادة معتمد، أو شخص بالغ يحمل رخصة وعمره 25 سنة على الأقل.","p":"صحيح. يجب أن يكون المرافق أحد الوالدين أو الوصي أو مدرّبًا أو بالغًا يحمل رخصة وعمره 25 سنة أو أكثر."},"ref":{"doc":"VT","page":13}},{"id":"vt-003","scope":"VT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Vermont, how long must a teen hold a learner's permit before getting a junior operator's license?","o":["At least one year","At least 3 months","At least 6 months","At least 2 years"],"h1":"It is longer than in many states.","h2":"A Vermont teen must hold a learner's permit for at least one year before getting a junior operator's license.","p":"Right. The permit must be held at least one year."},"es":{"q":"En Vermont, ¿cuánto tiempo debe tener un adolescente el permiso de aprendiz antes de obtener la licencia de operador menor?","o":["Por lo menos un año","Por lo menos 3 meses","Por lo menos 6 meses","Por lo menos 2 años"],"h1":"Es más tiempo que en muchos estados.","h2":"Un adolescente en Vermont debe tener el permiso de aprendiz por lo menos un año antes de obtener la licencia de operador menor.","p":"Correcto. El permiso se debe tener por lo menos un año."},"zh":{"q":"在 Vermont，青少年拿青少年驾照（junior operator's license）前，必须持有学习驾照多久？","o":["至少一年","至少 3 个月","至少 6 个月","至少 2 年"],"h1":"它比很多州要求的时间长。","h2":"在 Vermont，青少年必须持有学习驾照至少一年，才能拿青少年驾照。","p":"对。学习驾照必须持有至少一年。"},"vi":{"q":"Ở Vermont, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi có bằng lái thiếu niên (junior operator's license)?","o":["Ít nhất một năm","Ít nhất 3 tháng","Ít nhất 6 tháng","Ít nhất 2 năm"],"h1":"Thời gian này dài hơn so với nhiều tiểu bang.","h2":"Ở Vermont, thiếu niên phải giữ giấy phép tập lái ít nhất một năm trước khi có bằng lái thiếu niên.","p":"Đúng. Phải giữ giấy phép tập lái ít nhất một năm."},"tl":{"q":"Sa Vermont, gaano katagal dapat hawak ng tinedyer ang learner's permit bago makakuha ng lisensya ng batang drayber (junior operator's license)?","o":["Hindi bababa sa isang taon","Hindi bababa sa 3 buwan","Hindi bababa sa 6 na buwan","Hindi bababa sa 2 taon"],"h1":"Mas matagal ito kaysa sa maraming estado.","h2":"Ang tinedyer sa Vermont ay dapat humawak ng learner's permit nang hindi bababa sa isang taon bago makakuha ng lisensya ng batang drayber.","p":"Tama. Dapat hawak ang permit nang hindi bababa sa isang taon."},"ar":{"q":"في Vermont، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل الحصول على رخصة السائق الصغير (junior operator's license)؟","o":["سنة واحدة على الأقل","3 أشهر على الأقل","6 أشهر على الأقل","سنتان على الأقل"],"h1":"إنها أطول مما في ولايات كثيرة.","h2":"يجب على المراهق في Vermont أن يحمل تصريح التعلّم سنة واحدة على الأقل قبل الحصول على رخصة السائق الصغير.","p":"صحيح. يجب حمل تصريح التعلّم سنة واحدة على الأقل."},"ref":{"doc":"VT","page":13}},{"id":"vt-004","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, how many hours of supervised driving must a teen complete before a junior operator's license?","o":["20 hours","30 hours","40 hours","60 hours"],"h1":"It is less than fifty.","h2":"A Vermont teen must complete at least 40 hours of supervised driving before a junior operator's license.","p":"Right. Vermont asks for 40 hours of practice."},"es":{"q":"En Vermont, ¿cuántas horas de manejo supervisado debe completar un adolescente antes de la licencia de operador menor?","o":["20 horas","30 horas","40 horas","60 horas"],"h1":"Es menos de cincuenta.","h2":"Un adolescente en Vermont debe completar por lo menos 40 horas de manejo supervisado antes de la licencia de operador menor.","p":"Correcto. Vermont pide 40 horas de práctica."},"zh":{"q":"在 Vermont，青少年拿青少年驾照前，必须完成多少小时有人陪同的驾驶练习？","o":["20 小时","30 小时","40 小时","60 小时"],"h1":"它少于五十。","h2":"在 Vermont，青少年拿青少年驾照前，必须完成至少 40 小时有人陪同的驾驶练习。","p":"对。Vermont 要求练习 40 小时。"},"vi":{"q":"Ở Vermont, thiếu niên phải lái xe có người giám sát bao nhiêu giờ trước khi có bằng lái thiếu niên?","o":["20 giờ","30 giờ","40 giờ","60 giờ"],"h1":"Ít hơn năm mươi.","h2":"Ở Vermont, thiếu niên phải lái xe có người giám sát ít nhất 40 giờ trước khi có bằng lái thiếu niên.","p":"Đúng. Vermont yêu cầu 40 giờ tập lái."},"tl":{"q":"Sa Vermont, ilang oras ng pagmamanehong may kasamang tagabantay ang dapat tapusin ng tinedyer bago ang lisensya ng batang drayber?","o":["20 oras","30 oras","40 oras","60 oras"],"h1":"Mas kaunti ito sa limampu.","h2":"Ang tinedyer sa Vermont ay dapat tumapos ng hindi bababa sa 40 oras ng pagmamanehong may kasamang tagabantay bago ang lisensya ng batang drayber.","p":"Tama. Humihingi ang Vermont ng 40 oras ng pagsasanay."},"ar":{"q":"في Vermont، كم ساعة من القيادة تحت الإشراف يجب أن يُكملها المراهق قبل رخصة السائق الصغير؟","o":["20 ساعة","30 ساعة","40 ساعة","60 ساعة"],"h1":"إنها أقل من خمسين.","h2":"يجب على المراهق في Vermont أن يُكمل 40 ساعة على الأقل من القيادة تحت الإشراف قبل رخصة السائق الصغير.","p":"صحيح. تطلب Vermont 40 ساعة من التدريب."},"ref":{"doc":"VT","page":13}},{"id":"vt-005","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, how many of the 40 practice hours must be driven at night?","o":["At least 5 hours","At least 10 hours","At least 15 hours","At least 20 hours"],"h1":"It is one quarter of the total.","h2":"At least 10 of the 40 practice hours in Vermont must be at night, because driving in the dark needs its own practice.","p":"Right. At least 10 hours must be at night."},"es":{"q":"En Vermont, ¿cuántas de las 40 horas de práctica deben ser de noche?","o":["Por lo menos 5 horas","Por lo menos 10 horas","Por lo menos 15 horas","Por lo menos 20 horas"],"h1":"Es la cuarta parte del total.","h2":"Por lo menos 10 de las 40 horas de práctica en Vermont deben ser de noche, porque manejar en la oscuridad necesita su propia práctica.","p":"Correcto. Por lo menos 10 horas deben ser de noche."},"zh":{"q":"在 Vermont，40 小时练习中，有多少小时必须在夜间开车？","o":["至少 5 小时","至少 10 小时","至少 15 小时","至少 20 小时"],"h1":"它是总数的四分之一。","h2":"在 Vermont，40 小时练习中至少 10 小时必须在夜间，因为天黑开车需要专门练习。","p":"对。至少 10 小时必须在夜间。"},"vi":{"q":"Ở Vermont, trong 40 giờ tập lái, bao nhiêu giờ phải lái vào ban đêm?","o":["Ít nhất 5 giờ","Ít nhất 10 giờ","Ít nhất 15 giờ","Ít nhất 20 giờ"],"h1":"Đó là một phần tư tổng số.","h2":"Ở Vermont, ít nhất 10 trong 40 giờ tập lái phải vào ban đêm, vì lái xe trong bóng tối cần được tập riêng.","p":"Đúng. Ít nhất 10 giờ phải vào ban đêm."},"tl":{"q":"Sa Vermont, ilan sa 40 oras ng pagsasanay ang dapat imaneho sa gabi?","o":["Hindi bababa sa 5 oras","Hindi bababa sa 10 oras","Hindi bababa sa 15 oras","Hindi bababa sa 20 oras"],"h1":"Ito ay isang-kapat ng kabuuan.","h2":"Hindi bababa sa 10 sa 40 oras ng pagsasanay sa Vermont ang dapat sa gabi, dahil kailangan ng sariling pagsasanay ang pagmamaneho sa dilim.","p":"Tama. Hindi bababa sa 10 oras ang dapat sa gabi."},"ar":{"q":"في Vermont، كم ساعة من ساعات التدريب الـ 40 يجب أن تكون في الليل؟","o":["5 ساعات على الأقل","10 ساعات على الأقل","15 ساعة على الأقل","20 ساعة على الأقل"],"h1":"إنها ربع المجموع.","h2":"يجب أن تكون 10 ساعات على الأقل من ساعات التدريب الـ 40 في Vermont في الليل، لأن القيادة في الظلام تحتاج إلى تدريب خاص بها.","p":"صحيح. يجب أن تكون 10 ساعات على الأقل في الليل."},"ref":{"doc":"VT","page":13}},{"id":"vt-006","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, what course must a teen pass before getting a junior operator's license?","o":["A first aid course","A car repair course","A defensive driving course for adults","A state-approved driver education course"],"h1":"It is taught to new drivers, often in high school.","h2":"A Vermont teen must finish a state-approved driver education course before getting a junior operator's license.","p":"Right. Driver education is required."},"es":{"q":"En Vermont, ¿qué curso debe aprobar un adolescente antes de obtener la licencia de operador menor?","o":["Un curso de primeros auxilios","Un curso de reparación de autos","Un curso de manejo defensivo para adultos","Un curso de educación vial aprobado por el estado"],"h1":"Se enseña a conductores nuevos, muchas veces en la secundaria.","h2":"Un adolescente en Vermont debe terminar un curso de educación vial aprobado por el estado antes de obtener la licencia de operador menor.","p":"Correcto. La educación vial es obligatoria."},"zh":{"q":"在 Vermont，青少年拿青少年驾照前，必须通过什么课程？","o":["急救课程","修车课程","成人防御性驾驶课程","州政府认可的驾驶教育课程"],"h1":"这门课是教新司机的，常常在高中上。","h2":"在 Vermont，青少年必须完成州政府认可的驾驶教育课程（driver education），才能拿青少年驾照。","p":"对。必须上驾驶教育课。"},"vi":{"q":"Ở Vermont, thiếu niên phải học xong khóa học nào trước khi có bằng lái thiếu niên?","o":["Khóa sơ cứu","Khóa sửa xe","Khóa lái xe phòng thủ cho người lớn","Khóa giáo dục lái xe được tiểu bang chấp thuận"],"h1":"Khóa này dạy cho người mới lái, thường ở trường trung học.","h2":"Ở Vermont, thiếu niên phải học xong khóa giáo dục lái xe (driver education) được tiểu bang chấp thuận trước khi có bằng lái thiếu niên.","p":"Đúng. Bắt buộc phải học giáo dục lái xe."},"tl":{"q":"Sa Vermont, anong kurso ang dapat ipasa ng tinedyer bago makakuha ng lisensya ng batang drayber?","o":["Kurso sa first aid","Kurso sa pag-aayos ng kotse","Kurso sa ligtas na pagmamaneho para sa adulto","Kurso sa edukasyon sa pagmamaneho na aprubado ng estado"],"h1":"Itinuturo ito sa mga bagong drayber, madalas sa high school.","h2":"Ang tinedyer sa Vermont ay dapat tumapos ng kurso sa edukasyon sa pagmamaneho (driver education) na aprubado ng estado bago makakuha ng lisensya ng batang drayber.","p":"Tama. Kailangan ang edukasyon sa pagmamaneho."},"ar":{"q":"في Vermont، أيّ دورة يجب أن ينجح فيها المراهق قبل الحصول على رخصة السائق الصغير؟","o":["دورة إسعافات أولية","دورة تصليح سيارات","دورة القيادة الدفاعية للبالغين","دورة تعليم قيادة معتمدة من الولاية"],"h1":"تُدرَّس للسائقين الجدد، وغالبًا في المدرسة الثانوية.","h2":"يجب على المراهق في Vermont أن يُنهي دورة تعليم قيادة (driver education) معتمدة من الولاية قبل الحصول على رخصة السائق الصغير.","p":"صحيح. تعليم القيادة مطلوب."},"ref":{"doc":"VT","page":13}},{"id":"vt-007","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, during the first three months of a junior operator's license, who may ride with the driver?","o":["Any friends, if they wear seat belts","Only brothers and sisters","No one, or a parent, guardian, instructor, or licensed adult age 25 or older","Up to two friends under 18"],"h1":"In the first months, the driver is alone or with a qualified adult.","h2":"For the first three months, a Vermont junior operator may drive only alone or with a parent or guardian, a driving instructor, or a licensed adult 25 or older.","p":"Right. At first, drive alone or with a qualified adult."},"es":{"q":"En Vermont, durante los primeros tres meses de la licencia de operador menor, ¿quién puede ir con el conductor?","o":["Cualquier amigo, si usa cinturón","Solo hermanos y hermanas","Nadie, o un padre, tutor, instructor o adulto con licencia de 25 años o más","Hasta dos amigos menores de 18"],"h1":"En los primeros meses, el conductor va solo o con un adulto calificado.","h2":"Durante los primeros tres meses, un operador menor en Vermont solo puede manejar solo o con su padre, madre o tutor, un instructor de manejo o un adulto con licencia de 25 años o más.","p":"Correcto. Al principio, maneje solo o con un adulto calificado."},"zh":{"q":"在 Vermont，拿到青少年驾照的头三个月，谁可以和司机一起坐车？","o":["任何朋友，只要系安全带","只有兄弟姐妹","没有人，或者父母、监护人、教练，或 25 岁或以上有驾照的成年人","最多两个 18 岁以下的朋友"],"h1":"头几个月，司机要么一个人，要么和合格的成年人一起。","h2":"在 Vermont，拿到青少年驾照的头三个月，司机只能一个人开车，或者和父母或监护人、驾驶教练，或 25 岁或以上有驾照的成年人一起开车。","p":"对。开始时，一个人开车或和合格的成年人一起开车。"},"vi":{"q":"Ở Vermont, trong ba tháng đầu có bằng lái thiếu niên, ai được đi cùng xe với người lái?","o":["Bất kỳ người bạn nào, nếu họ thắt dây an toàn","Chỉ anh chị em ruột","Không ai, hoặc cha mẹ, người giám hộ, giáo viên, hoặc người lớn có bằng lái từ 25 tuổi trở lên","Tối đa hai người bạn dưới 18 tuổi"],"h1":"Trong những tháng đầu, người lái đi một mình hoặc với một người lớn đủ điều kiện.","h2":"Ở Vermont, trong ba tháng đầu, người có bằng lái thiếu niên chỉ được lái một mình hoặc với cha mẹ hay người giám hộ, giáo viên dạy lái xe, hoặc người lớn có bằng lái từ 25 tuổi trở lên.","p":"Đúng. Lúc đầu, lái một mình hoặc với một người lớn đủ điều kiện."},"tl":{"q":"Sa Vermont, sa unang tatlong buwan ng lisensya ng batang drayber, sino ang puwedeng sumakay kasama ng drayber?","o":["Kahit sinong kaibigan, kung naka-seat belt sila","Mga kapatid lamang","Walang iba, o magulang, tagapag-alaga, guro, o may lisensyang adulto na edad 25 pataas","Hanggang dalawang kaibigang wala pang 18"],"h1":"Sa mga unang buwan, mag-isa ang drayber o kasama ang kuwalipikadong adulto.","h2":"Sa unang tatlong buwan, ang batang drayber sa Vermont ay puwedeng magmaneho nang mag-isa lamang, o kasama ang magulang o tagapag-alaga, guro sa pagmamaneho, o may lisensyang adulto na 25 pataas.","p":"Tama. Sa simula, magmaneho nang mag-isa o kasama ang kuwalipikadong adulto."},"ar":{"q":"في Vermont، خلال الأشهر الثلاثة الأولى من رخصة السائق الصغير، مَن يمكنه الركوب مع السائق؟","o":["أي أصدقاء، إذا ربطوا أحزمة الأمان","الإخوة والأخوات فقط","لا أحد، أو أحد الوالدين أو الوصي أو مدرّب أو شخص بالغ يحمل رخصة وعمره 25 سنة أو أكثر","صديقان على الأكثر عمرهما أقل من 18 سنة"],"h1":"في الأشهر الأولى، يكون السائق وحده أو مع شخص بالغ مؤهّل.","h2":"في الأشهر الثلاثة الأولى، يمكن للسائق الصغير في Vermont أن يقود وحده فقط، أو مع أحد الوالدين أو الوصي، أو مدرّب قيادة، أو شخص بالغ يحمل رخصة وعمره 25 سنة أو أكثر.","p":"صحيح. في البداية، قُد وحدك أو مع شخص بالغ مؤهّل."},"ref":{"doc":"VT","page":15}},{"id":"vt-008","scope":"VT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Vermont, during months four to six of a junior operator's license, who else may the driver carry?","o":["Family members","Any friend over 18","Up to three classmates","Anyone with a learner's permit"],"h1":"Think of the people you live with.","h2":"During the second three months, a Vermont junior operator may also carry family members, but not other young passengers without a qualified adult.","p":"Right. Family members may ride in months four to six."},"es":{"q":"En Vermont, durante los meses cuatro a seis de la licencia de operador menor, ¿a quién más puede llevar el conductor?","o":["A familiares","A cualquier amigo mayor de 18","Hasta tres compañeros de clase","A cualquiera con permiso de aprendiz"],"h1":"Piense en las personas con quienes vive.","h2":"Durante los segundos tres meses, un operador menor en Vermont también puede llevar a familiares, pero no a otros pasajeros jóvenes sin un adulto calificado.","p":"Correcto. Los familiares pueden ir en los meses cuatro a seis."},"zh":{"q":"在 Vermont，拿到青少年驾照的第四到第六个月，司机还可以载谁？","o":["家人","任何 18 岁以上的朋友","最多三个同学","任何有学习驾照的人"],"h1":"想想和你住在一起的人。","h2":"在 Vermont，第二个三个月里，青少年司机还可以载家人，但没有合格的成年人在车上时，不能载其他年轻乘客。","p":"对。第四到第六个月可以载家人。"},"vi":{"q":"Ở Vermont, từ tháng thứ tư đến tháng thứ sáu có bằng lái thiếu niên, người lái còn được chở thêm ai?","o":["Người trong gia đình","Bất kỳ người bạn nào trên 18 tuổi","Tối đa ba bạn cùng lớp","Bất kỳ ai có giấy phép tập lái"],"h1":"Hãy nghĩ đến những người sống cùng nhà với bạn.","h2":"Ở Vermont, trong ba tháng thứ hai, người có bằng lái thiếu niên được chở thêm người trong gia đình, nhưng không được chở hành khách trẻ khác nếu không có người lớn đủ điều kiện.","p":"Đúng. Người trong gia đình được đi cùng từ tháng thứ tư đến tháng thứ sáu."},"tl":{"q":"Sa Vermont, sa ikaapat hanggang ikaanim na buwan ng lisensya ng batang drayber, sino pa ang puwedeng isakay ng drayber?","o":["Mga kapamilya","Kahit sinong kaibigan na lampas 18","Hanggang tatlong kaklase","Sinumang may learner's permit"],"h1":"Isipin ang mga taong kasama mo sa bahay.","h2":"Sa ikalawang tatlong buwan, puwede ring magsakay ng mga kapamilya ang batang drayber sa Vermont, pero hindi ibang batang pasahero kung walang kuwalipikadong adulto.","p":"Tama. Puwedeng sumakay ang mga kapamilya sa ikaapat hanggang ikaanim na buwan."},"ar":{"q":"في Vermont، خلال الأشهر من الرابع إلى السادس من رخصة السائق الصغير، مَن أيضًا يمكن للسائق أن يُركِب معه؟","o":["أفراد العائلة","أي صديق عمره أكثر من 18 سنة","ثلاثة زملاء دراسة على الأكثر","أي شخص معه تصريح تعلّم"],"h1":"فكّر في الأشخاص الذين تعيش معهم.","h2":"خلال الأشهر الثلاثة الثانية، يمكن للسائق الصغير في Vermont أن يُركِب أيضًا أفراد العائلة، ولكن لا يُركِب ركّابًا صغارًا آخرين بدون شخص بالغ مؤهّل.","p":"صحيح. يمكن لأفراد العائلة الركوب في الأشهر من الرابع إلى السادس."},"ref":{"doc":"VT","page":15}},{"id":"vt-009","scope":"VT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Vermont, a junior operator may never carry more passengers than what?","o":["Two people","The number of seat belts in the car","Four people","The number of doors on the car"],"h1":"Every rider needs something to buckle.","h2":"A Vermont junior operator may never carry more passengers than there are seat belts in the vehicle.","p":"Right. No more passengers than seat belts."},"es":{"q":"En Vermont, un operador menor nunca puede llevar más pasajeros que, ¿qué?","o":["Dos personas","El número de cinturones de seguridad del auto","Cuatro personas","El número de puertas del auto"],"h1":"Cada pasajero necesita algo para abrocharse.","h2":"Un operador menor en Vermont nunca puede llevar más pasajeros que cinturones de seguridad hay en el vehículo.","p":"Correcto. No más pasajeros que cinturones."},"zh":{"q":"在 Vermont，青少年司机载的乘客，绝不能多于什么？","o":["两个人","车里安全带的数量","四个人","车门的数量"],"h1":"每个乘客都需要能系上的东西。","h2":"在 Vermont，青少年司机载的乘客绝不能多于车里安全带的数量。","p":"对。乘客不能多于安全带。"},"vi":{"q":"Ở Vermont, người có bằng lái thiếu niên không bao giờ được chở nhiều hành khách hơn số nào?","o":["Hai người","Số dây an toàn trong xe","Bốn người","Số cửa của xe"],"h1":"Mỗi người ngồi xe cần có thứ để cài.","h2":"Ở Vermont, người có bằng lái thiếu niên không bao giờ được chở nhiều hành khách hơn số dây an toàn trong xe.","p":"Đúng. Không chở nhiều hành khách hơn số dây an toàn."},"tl":{"q":"Sa Vermont, hindi kailanman puwedeng magsakay ang batang drayber ng mas maraming pasahero kaysa sa ano?","o":["Dalawang tao","Bilang ng seat belt sa kotse","Apat na tao","Bilang ng pinto ng kotse"],"h1":"Bawat sakay ay kailangan ng maikakabit.","h2":"Ang batang drayber sa Vermont ay hindi kailanman puwedeng magsakay ng mas maraming pasahero kaysa sa bilang ng seat belt sa sasakyan.","p":"Tama. Hindi lalampas ang pasahero sa bilang ng seat belt."},"ar":{"q":"في Vermont، لا يجوز أبدًا للسائق الصغير أن يُركِب ركّابًا أكثر من ماذا؟","o":["شخصين","عدد أحزمة الأمان في السيارة","أربعة أشخاص","عدد أبواب السيارة"],"h1":"كل راكب يحتاج إلى شيء يربطه.","h2":"لا يجوز أبدًا للسائق الصغير في Vermont أن يُركِب ركّابًا أكثر من عدد أحزمة الأمان في السيارة.","p":"صحيح. لا ركّاب أكثر من أحزمة الأمان."},"ref":{"doc":"VT","page":15}},{"id":"vt-010","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, what happens if a junior operator breaks the passenger rules?","o":["Only a warning","A one-year suspension","A new road test","The license is recalled for 90 days"],"h1":"The license is taken back for about three months.","h2":"Breaking the passenger rules in Vermont leads to a 90-day recall of the junior operator's license.","p":"Right. The penalty is a 90-day recall."},"es":{"q":"En Vermont, ¿qué pasa si un operador menor no cumple las reglas de pasajeros?","o":["Solo una advertencia","Una suspensión de un año","Un nuevo examen de manejo","Le retiran la licencia por 90 días"],"h1":"Le quitan la licencia unos tres meses.","h2":"No cumplir las reglas de pasajeros en Vermont lleva a que le retiren la licencia de operador menor por 90 días.","p":"Correcto. El castigo es retirar la licencia por 90 días."},"zh":{"q":"在 Vermont，青少年司机违反乘客规定会怎样？","o":["只是警告","吊销驾照一年","重新考路考","驾照被收回 90 天"],"h1":"驾照会被收回大约三个月。","h2":"在 Vermont，违反乘客规定会被收回青少年驾照 90 天。","p":"对。处罚是收回驾照 90 天。"},"vi":{"q":"Ở Vermont, chuyện gì xảy ra nếu người có bằng lái thiếu niên vi phạm luật về hành khách?","o":["Chỉ bị cảnh cáo","Bị treo bằng một năm","Phải thi lái lại","Bằng lái bị thu hồi 90 ngày"],"h1":"Bằng lái bị lấy lại khoảng ba tháng.","h2":"Ở Vermont, vi phạm luật về hành khách sẽ bị thu hồi bằng lái thiếu niên 90 ngày.","p":"Đúng. Hình phạt là thu hồi bằng 90 ngày."},"tl":{"q":"Sa Vermont, ano ang mangyayari kung lumabag ang batang drayber sa mga tuntunin sa pasahero?","o":["Babala lamang","Suspensyon nang isang taon","Bagong road test","Babawiin ang lisensya nang 90 araw"],"h1":"Kukunin muli ang lisensya nang mga tatlong buwan.","h2":"Sa Vermont, ang paglabag sa mga tuntunin sa pasahero ay humahantong sa pagbawi ng lisensya ng batang drayber nang 90 araw.","p":"Tama. Ang parusa ay pagbawi nang 90 araw."},"ar":{"q":"في Vermont، ماذا يحدث إذا خالف السائق الصغير قواعد الركّاب؟","o":["تحذير فقط","إيقاف الرخصة لمدة سنة","اختبار قيادة جديد","تُسحب الرخصة لمدة 90 يومًا"],"h1":"تُؤخذ الرخصة لمدة ثلاثة أشهر تقريبًا.","h2":"مخالفة قواعد الركّاب في Vermont تؤدي إلى سحب رخصة السائق الصغير لمدة 90 يومًا.","p":"صحيح. العقوبة هي سحب الرخصة لمدة 90 يومًا."},"ref":{"doc":"VT","page":null}},{"id":"vt-011","scope":"VT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Vermont, may a driver under 18 use a phone hands-free while driving?","o":["Yes, if it is on speaker","Yes, on roads under 40 mph","No, not even hands-free","Yes, after six months of driving"],"h1":"The rule for young drivers is stricter than for adults.","h2":"A Vermont driver under 18 may not use any portable electronic device while driving, even hands-free, except to reach police or emergency services in an emergency.","p":"Right. Drivers under 18 may not use a phone, even hands-free."},"es":{"q":"En Vermont, ¿puede un conductor menor de 18 años usar el teléfono con manos libres mientras maneja?","o":["Sí, si está en altavoz","Sí, en caminos de menos de 40 mph","No, ni siquiera con manos libres","Sí, después de seis meses manejando"],"h1":"La regla para conductores jóvenes es más estricta que para los adultos.","h2":"Un conductor menor de 18 años en Vermont no puede usar ningún aparato electrónico portátil mientras maneja, ni con manos libres, salvo para comunicarse con la policía o los servicios de emergencia en una emergencia.","p":"Correcto. Los menores de 18 no pueden usar el teléfono, ni con manos libres."},"zh":{"q":"在 Vermont，18 岁以下的司机开车时可以用免提打电话吗？","o":["可以，如果开扬声器","可以，在时速低于 40 mph 的路上","不可以，免提也不行","可以，开车六个月以后"],"h1":"对年轻司机的规定比对成年人更严格。","h2":"在 Vermont，18 岁以下的司机开车时不能用任何便携电子设备，免提也不行，只有在紧急情况下联系警察或急救服务除外。","p":"对。18 岁以下的司机不能用手机，免提也不行。"},"vi":{"q":"Ở Vermont, người lái dưới 18 tuổi có được dùng điện thoại rảnh tay khi lái xe không?","o":["Có, nếu bật loa ngoài","Có, trên đường dưới 40 mph","Không, rảnh tay cũng không được","Có, sau sáu tháng lái xe"],"h1":"Luật cho người lái trẻ nghiêm hơn cho người lớn.","h2":"Ở Vermont, người lái dưới 18 tuổi không được dùng bất kỳ thiết bị điện tử cầm tay nào khi lái xe, kể cả rảnh tay, trừ khi gọi cảnh sát hoặc dịch vụ cấp cứu trong trường hợp khẩn cấp.","p":"Đúng. Người lái dưới 18 tuổi không được dùng điện thoại, kể cả rảnh tay."},"tl":{"q":"Sa Vermont, puwede bang gumamit ng telepono nang hands-free ang drayber na wala pang 18 habang nagmamaneho?","o":["Oo, kung naka-speaker","Oo, sa mga daang mas mababa sa 40 mph","Hindi, kahit hands-free","Oo, pagkatapos ng anim na buwang pagmamaneho"],"h1":"Mas mahigpit ang tuntunin para sa batang drayber kaysa sa adulto.","h2":"Ang drayber sa Vermont na wala pang 18 ay hindi puwedeng gumamit ng anumang portable na electronic device habang nagmamaneho, kahit hands-free, maliban sa pagtawag sa pulis o emergency services sa oras ng emergency.","p":"Tama. Ang drayber na wala pang 18 ay hindi puwedeng gumamit ng telepono, kahit hands-free."},"ar":{"q":"في Vermont، هل يجوز للسائق الذي عمره أقل من 18 سنة استخدام الهاتف بدون يدين أثناء القيادة؟","o":["نعم، إذا كان على مكبّر الصوت","نعم، على الطرق التي سرعتها أقل من 40 mph","لا، ولا حتى بدون يدين","نعم، بعد ستة أشهر من القيادة"],"h1":"القاعدة للسائقين الصغار أشدّ منها للبالغين.","h2":"لا يجوز للسائق في Vermont الذي عمره أقل من 18 سنة استخدام أي جهاز إلكتروني محمول أثناء القيادة، حتى بدون يدين، إلا للاتصال بالشرطة أو خدمات الطوارئ في حالة طارئة.","p":"صحيح. السائقون تحت 18 سنة لا يستخدمون الهاتف، حتى بدون يدين."},"ref":{"doc":"VT","page":null}},{"id":"vt-012","scope":"VT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Vermont, may an adult driver hold a phone while stopped at a red light?","o":["No, the ban applies even when stopped","Yes, the car is not moving","Yes, for a short text only","Yes, if the engine is idling"],"h1":"Stopping in traffic does not end the rule.","h2":"Vermont bans holding a phone while driving, and the ban still applies when you are stopped at a red light or stop sign.","p":"Right. No handheld phone, even at a red light."},"es":{"q":"En Vermont, ¿puede un conductor adulto sostener el teléfono mientras está detenido en un semáforo rojo?","o":["No, la prohibición vale aunque esté detenido","Sí, el auto no se mueve","Sí, solo para un mensaje corto","Sí, si el motor está encendido"],"h1":"Detenerse en el tráfico no termina la regla.","h2":"Vermont prohíbe sostener el teléfono mientras maneja, y la prohibición sigue cuando está detenido en un semáforo rojo o en un alto.","p":"Correcto. Nada de teléfono en la mano, ni en el semáforo rojo."},"zh":{"q":"在 Vermont，成年司机在红灯前停车时可以手拿手机吗？","o":["不可以，停车时也禁止","可以，车没有在动","可以，只发一条短信","可以，如果发动机在空转"],"h1":"在车流中停下来，规定并不结束。","h2":"Vermont 禁止开车时手拿手机，在红灯或停车标志前停下时也同样禁止。","p":"对。红灯时也不能手拿手机。"},"vi":{"q":"Ở Vermont, người lái là người lớn có được cầm điện thoại khi dừng đèn đỏ không?","o":["Không, lệnh cấm vẫn áp dụng khi dừng xe","Có, vì xe không chạy","Có, chỉ để nhắn tin ngắn","Có, nếu máy xe đang nổ"],"h1":"Dừng lại giữa dòng xe không làm hết luật.","h2":"Vermont cấm cầm điện thoại khi lái xe, và lệnh cấm vẫn áp dụng khi bạn dừng ở đèn đỏ hoặc bảng dừng (stop sign).","p":"Đúng. Không cầm điện thoại, kể cả khi dừng đèn đỏ."},"tl":{"q":"Sa Vermont, puwede bang hawakan ng adultong drayber ang telepono habang nakahinto sa pulang ilaw?","o":["Hindi, umiiral pa rin ang pagbabawal kahit nakahinto","Oo, hindi gumagalaw ang kotse","Oo, para sa maikling text lamang","Oo, kung umaandar ang makina"],"h1":"Hindi natatapos ang tuntunin kapag huminto ka sa trapiko.","h2":"Ipinagbabawal ng Vermont ang paghawak ng telepono habang nagmamaneho, at umiiral pa rin ito kapag nakahinto ka sa pulang ilaw o STOP sign.","p":"Tama. Bawal hawakan ang telepono, kahit sa pulang ilaw."},"ar":{"q":"في Vermont، هل يجوز للسائق البالغ أن يمسك الهاتف وهو متوقف عند الإشارة الحمراء؟","o":["لا، المنع يسري حتى عند التوقف","نعم، السيارة لا تتحرك","نعم، لرسالة قصيرة فقط","نعم، إذا كان المحرك يعمل"],"h1":"التوقف في حركة المرور لا يُنهي القاعدة.","h2":"تمنع Vermont إمساك الهاتف أثناء القيادة، ويبقى المنع ساريًا عندما تتوقف عند إشارة حمراء أو لافتة توقف (STOP).","p":"صحيح. لا تمسك الهاتف، حتى عند الإشارة الحمراء."},"ref":{"doc":"VT","page":55}},{"id":"vt-013","scope":"VT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Vermont, which phone use is allowed for a driver age 18 or older?","o":["Typing a text at low speed","Talking hands-free, without holding the phone","Holding the phone on speaker","Watching a video at a stop"],"h1":"Your hands must stay off the phone.","h2":"Vermont lets adult drivers use a phone only hands-free, without holding it in either hand.","p":"Right. Adults may use a phone hands-free."},"es":{"q":"En Vermont, ¿qué uso del teléfono está permitido para un conductor de 18 años o más?","o":["Escribir un mensaje a baja velocidad","Hablar con manos libres, sin sostener el teléfono","Sostener el teléfono en altavoz","Ver un video en un alto"],"h1":"Sus manos no deben tocar el teléfono.","h2":"Vermont permite a los conductores adultos usar el teléfono solo con manos libres, sin sostenerlo en ninguna mano.","p":"Correcto. Los adultos pueden usar el teléfono con manos libres."},"zh":{"q":"在 Vermont，18 岁或以上的司机可以怎样使用手机？","o":["低速时打字发短信","用免提通话，不用手拿手机","开扬声器拿着手机","停车时看视频"],"h1":"你的手不能碰手机。","h2":"Vermont 只允许成年司机用免提使用手机，两只手都不能拿着手机。","p":"对。成年人可以用免提使用手机。"},"vi":{"q":"Ở Vermont, người lái từ 18 tuổi trở lên được dùng điện thoại theo cách nào?","o":["Nhắn tin khi chạy chậm","Nói chuyện rảnh tay, không cầm điện thoại","Cầm điện thoại bật loa ngoài","Xem video khi dừng xe"],"h1":"Tay bạn phải không chạm vào điện thoại.","h2":"Vermont chỉ cho người lái là người lớn dùng điện thoại rảnh tay, không cầm điện thoại bằng tay nào cả.","p":"Đúng. Người lớn được dùng điện thoại rảnh tay."},"tl":{"q":"Sa Vermont, aling paggamit ng telepono ang pinapayagan para sa drayber na edad 18 pataas?","o":["Pag-type ng text sa mabagal na takbo","Pakikipag-usap nang hands-free, nang hindi hinahawakan ang telepono","Paghawak ng telepono na naka-speaker","Panonood ng video kapag nakahinto"],"h1":"Hindi dapat hawakan ng iyong mga kamay ang telepono.","h2":"Pinapayagan ng Vermont ang adultong drayber na gumamit ng telepono nang hands-free lamang, nang hindi ito hinahawakan ng alinmang kamay.","p":"Tama. Puwedeng gumamit ang adulto ng telepono nang hands-free."},"ar":{"q":"في Vermont، أيّ استخدام للهاتف مسموح للسائق الذي عمره 18 سنة أو أكثر؟","o":["كتابة رسالة على سرعة منخفضة","التحدّث بدون يدين، بدون إمساك الهاتف","إمساك الهاتف على مكبّر الصوت","مشاهدة فيديو عند التوقف"],"h1":"يجب أن تبقى يداك بعيدتين عن الهاتف.","h2":"تسمح Vermont للسائقين البالغين باستخدام الهاتف بدون يدين فقط، بدون إمساكه بأيّ يد.","p":"صحيح. يمكن للبالغين استخدام الهاتف بدون يدين."},"ref":{"doc":"VT","page":null}},{"id":"vt-014","scope":"VT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Vermont, a driver under 21 breaks the law with a blood alcohol level of what?","o":["0.08 or more","0.05 or more","0.10 or more","0.02 or more"],"h1":"It is much lower than the adult limit.","h2":"In Vermont, a driver under 21 with a blood alcohol level of 0.02 or more commits a violation, far below the adult limit of 0.08.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Vermont, un conductor menor de 21 años viola la ley con un nivel de alcohol en la sangre de, ¿cuánto?","o":["0.08 o más","0.05 o más","0.10 o más","0.02 o más"],"h1":"Es mucho menor que el límite para adultos.","h2":"En Vermont, un conductor menor de 21 años con 0.02 o más de alcohol en la sangre comete una infracción, muy por debajo del límite de 0.08 para adultos.","p":"Correcto. Para menores de 21, el límite es 0.02."},"zh":{"q":"在 Vermont，21 岁以下的司机血液酒精浓度达到多少就违法？","o":["0.08 或以上","0.05 或以上","0.10 或以上","0.02 或以上"],"h1":"它比成年人的上限低很多。","h2":"在 Vermont，21 岁以下的司机血液酒精浓度达到 0.02 或以上就违法，远低于成年人的上限 0.08。","p":"对。21 岁以下，上限是 0.02。"},"vi":{"q":"Ở Vermont, người lái dưới 21 tuổi phạm luật khi nồng độ cồn trong máu là bao nhiêu?","o":["0.08 trở lên","0.05 trở lên","0.10 trở lên","0.02 trở lên"],"h1":"Nó thấp hơn nhiều so với giới hạn cho người lớn.","h2":"Ở Vermont, người lái dưới 21 tuổi có nồng độ cồn trong máu từ 0.02 trở lên là phạm luật, thấp hơn nhiều so với giới hạn 0.08 cho người lớn.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa Vermont, lumalabag sa batas ang drayber na wala pang 21 kapag ang alak sa dugo ay ano?","o":["0.08 o higit pa","0.05 o higit pa","0.10 o higit pa","0.02 o higit pa"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon ng adulto.","h2":"Sa Vermont, ang drayber na wala pang 21 na may 0.02 o higit pang alak sa dugo ay lumalabag, mas mababa nang malaki kaysa sa limitasyon ng adulto na 0.08.","p":"Tama. Kung wala pang 21, ang limitasyon ay 0.02."},"ar":{"q":"في Vermont، يخالف السائق الذي عمره أقل من 21 سنة القانون إذا كانت نسبة الكحول في دمه كم؟","o":["0.08 أو أكثر","0.05 أو أكثر","0.10 أو أكثر","0.02 أو أكثر"],"h1":"إنها أقل بكثير من حدّ البالغين.","h2":"في Vermont، السائق الذي عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02 أو أكثر يرتكب مخالفة، وهذا أقل بكثير من حدّ البالغين وهو 0.08.","p":"صحيح. تحت 21 سنة، الحدّ هو 0.02."},"ref":{"doc":"VT","page":52}},{"id":"vt-015","scope":"VT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Vermont, what happens the first time a driver under 21 is caught at 0.02 or more?","o":["A warning letter only","A 30-day suspension","A 90-day license suspension","A one-week suspension"],"h1":"It lasts about three months.","h2":"Since July 2025, a Vermont driver under 21 caught at 0.02 or more loses the license for 90 days the first time, and for 180 days if they do not finish the required youth alcohol program.","p":"Right. A first violation means a 90-day suspension."},"es":{"q":"En Vermont, ¿qué pasa la primera vez que encuentran a un conductor menor de 21 años con 0.02 o más?","o":["Solo una carta de aviso","Una suspensión de 30 días","Una suspensión de la licencia de 90 días","Una suspensión de una semana"],"h1":"Dura unos tres meses.","h2":"Desde julio de 2025, un conductor menor de 21 años en Vermont con 0.02 o más pierde la licencia por 90 días la primera vez, y por 180 días si no termina el programa obligatorio para jóvenes sobre el alcohol.","p":"Correcto. La primera infracción significa una suspensión de 90 días."},"zh":{"q":"在 Vermont，21 岁以下的司机第一次被查到酒精浓度 0.02 或以上，会怎样？","o":["只收到警告信","吊销驾照 30 天","吊销驾照 90 天","吊销驾照一星期"],"h1":"大约三个月。","h2":"从 2025 年 7 月起，在 Vermont，21 岁以下的司机第一次被查到 0.02 或以上，驾照会被吊销 90 天；如果没有完成规定的青少年酒精课程，就是 180 天。","p":"对。第一次违规会吊销驾照 90 天。"},"vi":{"q":"Ở Vermont, lần đầu người lái dưới 21 tuổi bị bắt với nồng độ 0.02 trở lên thì sao?","o":["Chỉ nhận thư cảnh cáo","Bị treo bằng 30 ngày","Bị treo bằng lái 90 ngày","Bị treo bằng một tuần"],"h1":"Khoảng ba tháng.","h2":"Từ tháng 7 năm 2025, ở Vermont, người lái dưới 21 tuổi bị bắt lần đầu với nồng độ 0.02 trở lên sẽ mất bằng 90 ngày, và 180 ngày nếu không học xong chương trình về rượu bia cho người trẻ theo yêu cầu.","p":"Đúng. Vi phạm lần đầu là treo bằng 90 ngày."},"tl":{"q":"Sa Vermont, ano ang mangyayari sa unang beses na mahuli ang drayber na wala pang 21 na may 0.02 o higit pa?","o":["Sulat ng babala lamang","Suspensyon nang 30 araw","Suspensyon ng lisensya nang 90 araw","Suspensyon nang isang linggo"],"h1":"Tumatagal ito nang mga tatlong buwan.","h2":"Mula Hulyo 2025, ang drayber sa Vermont na wala pang 21 na nahuli na may 0.02 o higit pa ay mawawalan ng lisensya nang 90 araw sa unang beses, at 180 araw kung hindi niya tatapusin ang kinakailangang programa tungkol sa alak para sa kabataan.","p":"Tama. Ang unang paglabag ay suspensyon nang 90 araw."},"ar":{"q":"في Vermont، ماذا يحدث في المرة الأولى التي يُضبط فيها سائق عمره أقل من 21 سنة بنسبة 0.02 أو أكثر؟","o":["رسالة تحذير فقط","إيقاف لمدة 30 يومًا","إيقاف الرخصة لمدة 90 يومًا","إيقاف لمدة أسبوع"],"h1":"يستمر نحو ثلاثة أشهر.","h2":"منذ يوليو 2025، السائق في Vermont الذي عمره أقل من 21 سنة ويُضبط بنسبة 0.02 أو أكثر يفقد رخصته لمدة 90 يومًا في المرة الأولى، و180 يومًا إذا لم يُنهِ برنامج الكحول المطلوب للشباب.","p":"صحيح. المخالفة الأولى تعني إيقاف الرخصة لمدة 90 يومًا."},"ref":{"doc":"VT","page":null}},{"id":"vt-016","scope":"VT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Vermont, what is the highest speed allowed when no sign shows a different limit?","o":["50 mph","55 mph","45 mph","65 mph"],"h1":"It is lower than in many states.","h2":"Vermont law sets 50 mph as the maximum speed unless a different limit is posted, and you must go slower when conditions require.","p":"Right. Without a sign, the maximum is 50 mph."},"es":{"q":"En Vermont, ¿cuál es la velocidad máxima permitida cuando ningún letrero indica otro límite?","o":["50 mph","55 mph","45 mph","65 mph"],"h1":"Es menor que en muchos estados.","h2":"La ley de Vermont fija 50 mph como velocidad máxima si no hay otro límite indicado, y usted debe ir más despacio cuando las condiciones lo exigen.","p":"Correcto. Sin letrero, el máximo es 50 mph."},"zh":{"q":"在 Vermont，没有标志显示别的限速时，最高车速是多少？","o":["50 mph","55 mph","45 mph","65 mph"],"h1":"它比很多州的低。","h2":"Vermont 法律规定，除非标出别的限速，最高车速是 50 mph，路况需要时你还要开得更慢。","p":"对。没有标志时，最高 50 mph。"},"vi":{"q":"Ở Vermont, tốc độ cao nhất được phép là bao nhiêu khi không có bảng ghi giới hạn khác?","o":["50 mph","55 mph","45 mph","65 mph"],"h1":"Nó thấp hơn so với nhiều tiểu bang.","h2":"Luật Vermont đặt 50 mph là tốc độ tối đa nếu không có bảng ghi giới hạn khác, và bạn phải chạy chậm hơn khi điều kiện đòi hỏi.","p":"Đúng. Không có bảng, tối đa là 50 mph."},"tl":{"q":"Sa Vermont, ano ang pinakamataas na bilis na pinapayagan kapag walang karatulang nagpapakita ng ibang limitasyon?","o":["50 mph","55 mph","45 mph","65 mph"],"h1":"Mas mababa ito kaysa sa maraming estado.","h2":"Itinatakda ng batas ng Vermont ang 50 mph bilang pinakamataas na bilis maliban kung may nakapaskil na ibang limitasyon, at dapat kang bumagal kapag kailangan ng kondisyon.","p":"Tama. Kung walang karatula, ang pinakamataas ay 50 mph."},"ar":{"q":"في Vermont، ما أعلى سرعة مسموحة عندما لا توجد لافتة تُظهر حدًّا مختلفًا؟","o":["50 mph","55 mph","45 mph","65 mph"],"h1":"إنها أقل مما في ولايات كثيرة.","h2":"يحدّد قانون Vermont أن 50 mph هي السرعة القصوى إلا إذا وُضعت لافتة بحدّ مختلف، ويجب أن تقود أبطأ عندما تتطلّب الظروف ذلك.","p":"صحيح. بدون لافتة، السرعة القصوى 50 mph."},"ref":{"doc":"VT","page":28}},{"id":"vt-017","scope":"VT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Vermont, what is the highest speed limit on an Interstate?","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"It is lower than in many western states.","h2":"The highest speed on a Vermont Interstate is 65 mph, unless a sign shows a lower limit.","p":"Right. Vermont Interstates top out at 65 mph."},"es":{"q":"En Vermont, ¿cuál es el límite de velocidad más alto en una autopista interestatal?","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"Es menor que en muchos estados del oeste.","h2":"La velocidad más alta en una autopista interestatal de Vermont es 65 mph, a menos que un letrero indique un límite menor.","p":"Correcto. En Vermont el máximo en las interestatales es 65 mph."},"zh":{"q":"在 Vermont，州际公路（Interstate）的最高限速是多少？","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"它比很多西部州的低。","h2":"Vermont 州际公路的最高车速是 65 mph，除非标志显示更低的限速。","p":"对。Vermont 州际公路最高 65 mph。"},"vi":{"q":"Ở Vermont, giới hạn tốc độ cao nhất trên xa lộ liên bang (Interstate) là bao nhiêu?","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"Nó thấp hơn so với nhiều tiểu bang miền tây.","h2":"Tốc độ cao nhất trên xa lộ liên bang ở Vermont là 65 mph, trừ khi có bảng ghi giới hạn thấp hơn.","p":"Đúng. Xa lộ liên bang ở Vermont tối đa 65 mph."},"tl":{"q":"Sa Vermont, ano ang pinakamataas na speed limit sa Interstate?","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"Mas mababa ito kaysa sa maraming estado sa kanluran.","h2":"Ang pinakamataas na bilis sa Interstate ng Vermont ay 65 mph, maliban kung may karatulang nagpapakita ng mas mababang limitasyon.","p":"Tama. Hanggang 65 mph lamang ang mga Interstate ng Vermont."},"ar":{"q":"في Vermont، ما أعلى حدّ للسرعة على الطريق السريع بين الولايات (Interstate)؟","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"إنه أقل مما في ولايات غربية كثيرة.","h2":"أعلى سرعة على Interstate في Vermont هي 65 mph، إلا إذا أظهرت لافتة حدًّا أقل.","p":"صحيح. أقصى سرعة على Interstate في Vermont هي 65 mph."},"ref":{"doc":"VT","page":28}},{"id":"vt-018","scope":"VT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Vermont, you approach a stopped police car, ambulance or tow truck with flashing lights. What must you do?","o":["Keep your speed and lane","Slow down and, if safe, move out of the lane next to it","Stop behind it until it leaves","Speed up to pass quickly"],"h1":"Give the people at the roadside more space and time.","h2":"Vermont's move over law says to slow down and, when it is safe, leave the lane closest to a stopped emergency or tow vehicle with flashing lights.","p":"Right. Slow down and move over when safe."},"es":{"q":"En Vermont, usted se acerca a una patrulla, ambulancia o grúa detenida con luces intermitentes. ¿Qué debe hacer?","o":["Mantener su velocidad y carril","Reducir la velocidad y, si es seguro, salir del carril junto a ella","Detenerse detrás hasta que se vaya","Acelerar para pasar rápido"],"h1":"Dé más espacio y tiempo a las personas al lado del camino.","h2":"La ley de Vermont dice que debe reducir la velocidad y, cuando sea seguro, salir del carril más cercano a un vehículo de emergencia o grúa detenido con luces intermitentes.","p":"Correcto. Reduzca la velocidad y cámbiese de carril si es seguro."},"zh":{"q":"在 Vermont，你开近一辆停着、闪着灯的警车、救护车或拖车。你必须怎么做？","o":["保持车速和车道","减速，安全时离开它旁边的车道","停在它后面等它开走","加速快点开过去"],"h1":"给路边的人更多空间和时间。","h2":"Vermont 的让道法（move over law）规定，要减速，安全时离开最靠近停着、闪着灯的紧急车辆或拖车的车道。","p":"对。减速，安全时换道让开。"},"vi":{"q":"Ở Vermont, bạn đến gần một xe cảnh sát, xe cứu thương hoặc xe kéo đang dừng và chớp đèn. Bạn phải làm gì?","o":["Giữ tốc độ và làn đường","Chạy chậm lại và, nếu an toàn, rời khỏi làn đường sát bên nó","Dừng phía sau cho đến khi nó đi","Tăng tốc để vượt nhanh"],"h1":"Hãy cho những người bên lề đường thêm khoảng trống và thời gian.","h2":"Luật tránh sang (move over law) của Vermont nói phải chạy chậm lại và, khi an toàn, rời khỏi làn đường gần nhất với xe khẩn cấp hoặc xe kéo đang dừng và chớp đèn.","p":"Đúng. Chạy chậm lại và tránh sang khi an toàn."},"tl":{"q":"Sa Vermont, papalapit ka sa nakahintong kotse ng pulis, ambulansya o tow truck na may kumikislap na ilaw. Ano ang dapat mong gawin?","o":["Panatilihin ang bilis at linya","Bumagal at, kung ligtas, lumipat mula sa linyang katabi nito","Huminto sa likod nito hanggang umalis ito","Bumilis para mabilis na lumampas"],"h1":"Bigyan ng mas maraming espasyo at oras ang mga tao sa gilid ng daan.","h2":"Sinasabi ng move over law ng Vermont na bumagal at, kapag ligtas, umalis sa linyang pinakamalapit sa nakahintong emergency vehicle o tow truck na may kumikislap na ilaw.","p":"Tama. Bumagal at lumipat ng linya kapag ligtas."},"ar":{"q":"في Vermont، تقترب من سيارة شرطة أو إسعاف أو سيارة سحب متوقفة وأضواؤها تومض. ماذا يجب أن تفعل؟","o":["حافظ على سرعتك ومسارك","خفّف السرعة، وإذا كان آمنًا، ابتعد عن المسار المجاور لها","توقّف خلفها حتى تغادر","زِد السرعة لتتجاوزها بسرعة"],"h1":"أعطِ الناس على جانب الطريق مساحة ووقتًا أكثر.","h2":"قانون الابتعاد (move over law) في Vermont يقول أن تخفّف السرعة، وعندما يكون آمنًا، تترك المسار الأقرب إلى سيارة طوارئ أو سيارة سحب متوقفة وأضواؤها تومض.","p":"صحيح. خفّف السرعة وابتعد عندما يكون آمنًا."},"ref":{"doc":"VT","page":31}},{"id":"vt-019","scope":"VT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Vermont, how long must you stay stopped for a school bus with flashing red lights?","o":["Until the red lights stop flashing","For 30 seconds","Until the door closes","Until you see no children"],"h1":"Watch the bus lights, not a clock.","h2":"In Vermont you must stay stopped as long as the school bus's red lights are flashing.","p":"Right. Stay stopped while the red lights flash."},"es":{"q":"En Vermont, ¿cuánto tiempo debe quedarse detenido ante un autobús escolar con luces rojas intermitentes?","o":["Hasta que las luces rojas dejen de parpadear","Durante 30 segundos","Hasta que se cierre la puerta","Hasta que no vea niños"],"h1":"Mire las luces del autobús, no el reloj.","h2":"En Vermont usted debe quedarse detenido mientras las luces rojas del autobús escolar estén parpadeando.","p":"Correcto. Quédese detenido mientras parpadean las luces rojas."},"zh":{"q":"在 Vermont，校车闪红灯时，你必须停多久？","o":["直到红灯不再闪","30 秒","直到车门关上","直到看不见孩子"],"h1":"看校车的灯，不是看时钟。","h2":"在 Vermont，只要校车的红灯在闪，你就必须一直停着。","p":"对。红灯闪着时一直停着。"},"vi":{"q":"Ở Vermont, bạn phải dừng bao lâu khi xe buýt học sinh chớp đèn đỏ?","o":["Cho đến khi đèn đỏ ngừng chớp","Trong 30 giây","Cho đến khi cửa xe đóng","Cho đến khi không thấy trẻ em"],"h1":"Hãy nhìn đèn xe buýt, không phải đồng hồ.","h2":"Ở Vermont, bạn phải dừng suốt thời gian đèn đỏ của xe buýt học sinh còn chớp.","p":"Đúng. Dừng khi đèn đỏ còn chớp."},"tl":{"q":"Sa Vermont, gaano katagal ka dapat nakahinto para sa school bus na may kumikislap na pulang ilaw?","o":["Hanggang tumigil ang pagkislap ng pulang ilaw","Nang 30 segundo","Hanggang sumara ang pinto","Hanggang wala ka nang makitang bata"],"h1":"Tingnan ang ilaw ng bus, hindi ang orasan.","h2":"Sa Vermont, dapat kang manatiling nakahinto habang kumikislap ang pulang ilaw ng school bus.","p":"Tama. Manatiling nakahinto habang kumikislap ang pulang ilaw."},"ar":{"q":"في Vermont، كم مدة يجب أن تبقى متوقفًا عند حافلة مدرسية أضواؤها الحمراء تومض؟","o":["حتى تتوقف الأضواء الحمراء عن الوميض","لمدة 30 ثانية","حتى يُغلق الباب","حتى لا ترى أطفالًا"],"h1":"راقب أضواء الحافلة، لا الساعة.","h2":"في Vermont يجب أن تبقى متوقفًا ما دامت الأضواء الحمراء للحافلة المدرسية تومض.","p":"صحيح. ابقَ متوقفًا ما دامت الأضواء الحمراء تومض."},"ref":{"doc":"VT","page":39}},{"id":"vt-020","scope":"VT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Vermont, a school bus with flashing red lights is stopped on the other roadway of a divided highway. What must you do?","o":["Stop until the lights turn off","Stop, then pass at 10 mph","You do not have to stop","Honk and pass slowly"],"h1":"A divided highway has separate roadways for each direction.","h2":"In Vermont, you do not have to stop for a school bus that is on a different roadway of a divided highway, but drive with care.","p":"Right. The other roadway of a divided highway does not have to stop."},"es":{"q":"En Vermont, un autobús escolar con luces rojas intermitentes está detenido en la otra calzada de una carretera dividida. ¿Qué debe hacer usted?","o":["Detenerse hasta que se apaguen las luces","Detenerse y luego pasar a 10 mph","No tiene que detenerse","Tocar la bocina y pasar despacio"],"h1":"Una carretera dividida tiene calzadas separadas para cada dirección.","h2":"En Vermont, usted no tiene que detenerse por un autobús escolar que está en otra calzada de una carretera dividida, pero maneje con cuidado.","p":"Correcto. La otra calzada de una carretera dividida no tiene que detenerse."},"zh":{"q":"在 Vermont，一辆闪红灯的校车停在分隔公路的另一边车道上。你必须怎么做？","o":["停车，直到灯熄灭","停车，然后以 10 mph 开过去","你不用停车","按喇叭，慢慢开过去"],"h1":"分隔公路的每个方向都有分开的路面。","h2":"在 Vermont，校车如果在分隔公路的另一边路面上，你不用停车，但要小心驾驶。","p":"对。分隔公路另一边的车不用停。"},"vi":{"q":"Ở Vermont, một xe buýt học sinh chớp đèn đỏ đang dừng ở phần đường bên kia của xa lộ có dải phân cách. Bạn phải làm gì?","o":["Dừng cho đến khi đèn tắt","Dừng, rồi vượt qua ở 10 mph","Bạn không phải dừng","Bấm còi và vượt chậm"],"h1":"Xa lộ có dải phân cách có phần đường riêng cho mỗi chiều.","h2":"Ở Vermont, bạn không phải dừng cho xe buýt học sinh ở phần đường khác của xa lộ có dải phân cách, nhưng phải lái cẩn thận.","p":"Đúng. Xe ở phần đường bên kia của xa lộ có dải phân cách không phải dừng."},"tl":{"q":"Sa Vermont, may school bus na may kumikislap na pulang ilaw na nakahinto sa kabilang daan ng divided highway. Ano ang dapat mong gawin?","o":["Huminto hanggang mamatay ang ilaw","Huminto, pagkatapos ay lumampas sa 10 mph","Hindi mo kailangang huminto","Bumusina at lumampas nang dahan-dahan"],"h1":"Ang divided highway ay may hiwalay na daan para sa bawat direksyon.","h2":"Sa Vermont, hindi mo kailangang huminto para sa school bus na nasa ibang daan ng divided highway, pero magmaneho nang maingat.","p":"Tama. Hindi kailangang huminto sa kabilang daan ng divided highway."},"ar":{"q":"في Vermont، حافلة مدرسية أضواؤها الحمراء تومض متوقفة على الطريق الآخر من طريق سريع مقسوم. ماذا يجب أن تفعل؟","o":["توقّف حتى تنطفئ الأضواء","توقّف، ثم تجاوز بسرعة 10 mph","ليس عليك أن تتوقف","استعمل البوق وتجاوز ببطء"],"h1":"الطريق المقسوم فيه طريق منفصل لكل اتجاه.","h2":"في Vermont، ليس عليك أن تتوقف لحافلة مدرسية على طريق مختلف من طريق سريع مقسوم، ولكن قُد بحذر.","p":"صحيح. الطريق الآخر من الطريق المقسوم ليس عليه أن يتوقف."},"ref":{"doc":"VT","page":40}},{"id":"vt-021","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, how many points within two years start a license suspension?","o":["5 points","10 points","8 points","12 points"],"h1":"It is a round number.","h2":"In Vermont, 10 or more points within two years lead the Commissioner to suspend your license.","p":"Right. Ten points in two years starts a suspension."},"es":{"q":"En Vermont, ¿cuántos puntos en dos años inician una suspensión de la licencia?","o":["5 puntos","10 puntos","8 puntos","12 puntos"],"h1":"Es un número redondo.","h2":"En Vermont, 10 puntos o más en dos años llevan a que el Comisionado suspenda su licencia.","p":"Correcto. Diez puntos en dos años inician una suspensión."},"zh":{"q":"在 Vermont，两年内扣多少分会开始吊销驾照？","o":["5 分","10 分","8 分","12 分"],"h1":"它是个整数。","h2":"在 Vermont，两年内扣 10 分或以上，州长官（Commissioner）会吊销你的驾照。","p":"对。两年内 10 分就会开始吊销。"},"vi":{"q":"Ở Vermont, bao nhiêu điểm trong hai năm thì bắt đầu bị treo bằng lái?","o":["5 điểm","10 điểm","8 điểm","12 điểm"],"h1":"Đó là một số tròn.","h2":"Ở Vermont, từ 10 điểm trở lên trong hai năm thì Ủy viên (Commissioner) sẽ treo bằng lái của bạn.","p":"Đúng. Mười điểm trong hai năm là bắt đầu bị treo bằng."},"tl":{"q":"Sa Vermont, ilang puntos sa loob ng dalawang taon ang nagsisimula ng suspensyon ng lisensya?","o":["5 puntos","10 puntos","8 puntos","12 puntos"],"h1":"Ito ay buong bilang na madaling tandaan.","h2":"Sa Vermont, ang 10 o higit pang puntos sa loob ng dalawang taon ay nagiging dahilan para suspindihin ng Commissioner ang iyong lisensya.","p":"Tama. Sampung puntos sa dalawang taon ang nagsisimula ng suspensyon."},"ar":{"q":"في Vermont، كم نقطة خلال سنتين تبدأ إيقاف الرخصة؟","o":["5 نقاط","10 نقاط","8 نقاط","12 نقطة"],"h1":"إنه رقم مستدير.","h2":"في Vermont، 10 نقاط أو أكثر خلال سنتين تجعل المفوّض (Commissioner) يوقف رخصتك.","p":"صحيح. عشر نقاط في سنتين تبدأ الإيقاف."},"ref":{"doc":"VT","page":64}},{"id":"vt-022","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, how long is the suspension for reaching 10 points?","o":["One year","90 days","30 days","10 days"],"h1":"The number of days matches the number of points.","h2":"Reaching 10 points in Vermont brings a 10-day suspension, and the time grows as points go up.","p":"Right. Ten points means a 10-day suspension."},"es":{"q":"En Vermont, ¿cuánto dura la suspensión por llegar a 10 puntos?","o":["Un año","90 días","30 días","10 días"],"h1":"El número de días es igual al número de puntos.","h2":"Llegar a 10 puntos en Vermont trae una suspensión de 10 días, y el tiempo aumenta con más puntos.","p":"Correcto. Diez puntos significan una suspensión de 10 días."},"zh":{"q":"在 Vermont，扣到 10 分会吊销驾照多久？","o":["一年","90 天","30 天","10 天"],"h1":"天数和分数一样。","h2":"在 Vermont，扣到 10 分会吊销驾照 10 天，分数越多，时间越长。","p":"对。10 分就是吊销 10 天。"},"vi":{"q":"Ở Vermont, khi đủ 10 điểm thì bị treo bằng bao lâu?","o":["Một năm","90 ngày","30 ngày","10 ngày"],"h1":"Số ngày bằng số điểm.","h2":"Ở Vermont, đủ 10 điểm sẽ bị treo bằng 10 ngày, và thời gian tăng lên khi điểm tăng.","p":"Đúng. Mười điểm là treo bằng 10 ngày."},"tl":{"q":"Sa Vermont, gaano katagal ang suspensyon kapag umabot ka sa 10 puntos?","o":["Isang taon","90 araw","30 araw","10 araw"],"h1":"Pareho ang bilang ng araw at ang bilang ng puntos.","h2":"Ang pag-abot sa 10 puntos sa Vermont ay nagdudulot ng 10 araw na suspensyon, at humahaba ang panahon habang dumarami ang puntos.","p":"Tama. Sampung puntos ay 10 araw na suspensyon."},"ar":{"q":"في Vermont، كم مدة الإيقاف عند الوصول إلى 10 نقاط؟","o":["سنة واحدة","90 يومًا","30 يومًا","10 أيام"],"h1":"عدد الأيام يساوي عدد النقاط.","h2":"الوصول إلى 10 نقاط في Vermont يجلب إيقافًا لمدة 10 أيام، وتزيد المدة كلما زادت النقاط.","p":"صحيح. عشر نقاط تعني إيقافًا لمدة 10 أيام."},"ref":{"doc":"VT","page":null}},{"id":"vt-023","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, what is the minimum liability insurance for property damage?","o":["$5,000","$25,000","$10,000","$15,000"],"h1":"It is the smallest of the three required amounts.","h2":"Vermont requires at least $10,000 for property damage, with $25,000 per injured person and $50,000 per crash.","p":"Right. Property damage coverage must be at least $10,000."},"es":{"q":"En Vermont, ¿cuál es el seguro de responsabilidad mínimo por daños a la propiedad?","o":["$5,000","$25,000","$10,000","$15,000"],"h1":"Es la menor de las tres cantidades exigidas.","h2":"Vermont exige por lo menos $10,000 por daños a la propiedad, con $25,000 por persona lesionada y $50,000 por choque.","p":"Correcto. La cobertura por daños a la propiedad debe ser de por lo menos $10,000."},"zh":{"q":"在 Vermont，财产损失的最低责任保险是多少？","o":["$5,000","$25,000","$10,000","$15,000"],"h1":"它是三个必须金额中最小的。","h2":"Vermont 要求财产损失保险至少 $10,000，每个受伤的人 $25,000，每次车祸 $50,000。","p":"对。财产损失保险至少 $10,000。"},"vi":{"q":"Ở Vermont, bảo hiểm trách nhiệm tối thiểu cho thiệt hại tài sản là bao nhiêu?","o":["$5,000","$25,000","$10,000","$15,000"],"h1":"Đó là số nhỏ nhất trong ba số tiền bắt buộc.","h2":"Vermont yêu cầu ít nhất $10,000 cho thiệt hại tài sản, $25,000 cho mỗi người bị thương và $50,000 cho mỗi vụ tai nạn.","p":"Đúng. Bảo hiểm thiệt hại tài sản phải ít nhất $10,000."},"tl":{"q":"Sa Vermont, ano ang pinakamababang liability insurance para sa pinsala sa ari-arian?","o":["$5,000","$25,000","$10,000","$15,000"],"h1":"Ito ang pinakamaliit sa tatlong kinakailangang halaga.","h2":"Hinihingi ng Vermont ang hindi bababa sa $10,000 para sa pinsala sa ari-arian, $25,000 bawat taong nasaktan, at $50,000 bawat banggaan.","p":"Tama. Ang insurance sa pinsala sa ari-arian ay dapat hindi bababa sa $10,000."},"ar":{"q":"في Vermont، ما الحدّ الأدنى لتأمين المسؤولية عن أضرار الممتلكات؟","o":["$5,000","$25,000","$10,000","$15,000"],"h1":"إنه أصغر المبالغ الثلاثة المطلوبة.","h2":"تطلب Vermont على الأقل $10,000 لأضرار الممتلكات، و$25,000 لكل شخص مُصاب، و$50,000 لكل حادث.","p":"صحيح. تأمين أضرار الممتلكات يجب أن يكون $10,000 على الأقل."},"ref":{"doc":"VT","page":67}},{"id":"vt-024","scope":"VT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Vermont, how many of the 20 questions on the learner's permit test must you answer correctly?","o":["16","14","18","12"],"h1":"You may miss four.","h2":"To pass the Vermont learner's permit test, you must answer at least 16 of the 20 questions correctly, which is 80 percent.","p":"Right. You need 16 correct answers out of 20."},"es":{"q":"En Vermont, ¿cuántas de las 20 preguntas del examen del permiso de aprendiz debe contestar bien?","o":["16","14","18","12"],"h1":"Puede fallar cuatro.","h2":"Para aprobar el examen del permiso de aprendiz en Vermont, debe contestar bien por lo menos 16 de las 20 preguntas, es decir, el 80 por ciento.","p":"Correcto. Necesita 16 respuestas correctas de 20."},"zh":{"q":"在 Vermont，学习驾照考试 20 道题中，你必须答对多少道？","o":["16","14","18","12"],"h1":"你可以错四道。","h2":"要通过 Vermont 学习驾照考试，你必须答对 20 道题中至少 16 道，也就是 80%。","p":"对。20 道题要答对 16 道。"},"vi":{"q":"Ở Vermont, trong 20 câu hỏi của bài thi giấy phép tập lái, bạn phải trả lời đúng bao nhiêu câu?","o":["16","14","18","12"],"h1":"Bạn được sai bốn câu.","h2":"Để đậu bài thi giấy phép tập lái ở Vermont, bạn phải trả lời đúng ít nhất 16 trong 20 câu, tức là 80 phần trăm.","p":"Đúng. Bạn cần 16 câu đúng trong 20 câu."},"tl":{"q":"Sa Vermont, ilan sa 20 tanong sa learner's permit test ang dapat mong masagot nang tama?","o":["16","14","18","12"],"h1":"Puwede kang magkamali ng apat.","h2":"Para pumasa sa learner's permit test ng Vermont, dapat mong masagot nang tama ang hindi bababa sa 16 sa 20 tanong, na 80 porsiyento.","p":"Tama. Kailangan mo ng 16 na tamang sagot sa 20."},"ar":{"q":"في Vermont، كم سؤالًا من الأسئلة الـ 20 في اختبار تصريح التعلّم يجب أن تجيب عنه إجابة صحيحة؟","o":["16","14","18","12"],"h1":"يمكنك أن تُخطئ في أربعة.","h2":"لكي تنجح في اختبار تصريح التعلّم في Vermont، يجب أن تجيب إجابة صحيحة عن 16 سؤالًا على الأقل من 20، أي 80 بالمئة.","p":"صحيح. تحتاج إلى 16 إجابة صحيحة من 20."},"ref":{"doc":"VT","page":18}},{"id":"vt-025","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, after a crash with an injury or more than $3,000 in damage, how soon must you send a written report to the DMV?","o":["Within 24 hours","Within 72 hours","Within 10 days","Within 30 days"],"h1":"It is three days.","h2":"In Vermont, a crash that hurts someone or causes more than $3,000 in damage must be reported to the DMV in writing within 72 hours.","p":"Right. Report it to the DMV within 72 hours."},"es":{"q":"En Vermont, después de un choque con un herido o con más de $3,000 en daños, ¿en cuánto tiempo debe enviar un reporte escrito al DMV?","o":["En 24 horas","En 72 horas","En 10 días","En 30 días"],"h1":"Son tres días.","h2":"En Vermont, un choque que hiere a alguien o causa más de $3,000 en daños se debe reportar por escrito al DMV en 72 horas.","p":"Correcto. Repórtelo al DMV en 72 horas."},"zh":{"q":"在 Vermont，发生有人受伤或损坏超过 $3,000 的车祸后，你必须在多长时间内向 DMV 交书面报告？","o":["24 小时内","72 小时内","10 天内","30 天内"],"h1":"是三天。","h2":"在 Vermont，造成有人受伤或损坏超过 $3,000 的车祸，必须在 72 小时内用书面形式报告给 DMV。","p":"对。在 72 小时内报告给 DMV。"},"vi":{"q":"Ở Vermont, sau một vụ tai nạn có người bị thương hoặc thiệt hại hơn $3,000, bạn phải gửi báo cáo bằng văn bản cho DMV trong bao lâu?","o":["Trong vòng 24 giờ","Trong vòng 72 giờ","Trong vòng 10 ngày","Trong vòng 30 ngày"],"h1":"Đó là ba ngày.","h2":"Ở Vermont, vụ tai nạn làm người khác bị thương hoặc gây thiệt hại hơn $3,000 phải được báo cáo bằng văn bản cho DMV trong vòng 72 giờ.","p":"Đúng. Báo cho DMV trong vòng 72 giờ."},"tl":{"q":"Sa Vermont, pagkatapos ng banggaan na may nasaktan o may pinsalang higit sa $3,000, gaano kabilis ka dapat magpadala ng nakasulat na report sa DMV?","o":["Sa loob ng 24 oras","Sa loob ng 72 oras","Sa loob ng 10 araw","Sa loob ng 30 araw"],"h1":"Tatlong araw ito.","h2":"Sa Vermont, ang banggaan na may nasaktan o may pinsalang higit sa $3,000 ay dapat i-report nang nakasulat sa DMV sa loob ng 72 oras.","p":"Tama. I-report ito sa DMV sa loob ng 72 oras."},"ar":{"q":"في Vermont، بعد حادث فيه إصابة أو ضرر بأكثر من $3,000، خلال كم من الوقت يجب أن ترسل تقريرًا مكتوبًا إلى الـ DMV؟","o":["خلال 24 ساعة","خلال 72 ساعة","خلال 10 أيام","خلال 30 يومًا"],"h1":"هي ثلاثة أيام.","h2":"في Vermont، الحادث الذي يُصيب شخصًا أو يسبب ضررًا بأكثر من $3,000 يجب التبليغ عنه كتابةً إلى الـ DMV خلال 72 ساعة.","p":"صحيح. بلّغ الـ DMV خلال 72 ساعة."},"ref":{"doc":"VT","page":58}},{"id":"vt-026","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, what happens if a driver refuses a police officer's request for an alcohol or drug test?","o":["Nothing, the test is optional","A warning letter from the DMV","A 10-day suspension","Loss of the license for at least six months"],"h1":"Vermont has an Implied Consent law, so refusing has a real cost.","h2":"Under Vermont's Implied Consent law, a driver who refuses the alcohol or drug test loses the driver's license for at least six months.","p":"Right. Refusing the test means losing your license for at least six months."},"es":{"q":"En Vermont, ¿qué pasa si un conductor se niega cuando un policía le pide una prueba de alcohol o drogas?","o":["Nada, la prueba es opcional","Una carta de advertencia del DMV","Una suspensión de 10 días","Pierde la licencia por al menos seis meses"],"h1":"Vermont tiene una ley de Consentimiento Implícito, así que negarse tiene un costo real.","h2":"Bajo la ley de Consentimiento Implícito de Vermont, el conductor que se niega a la prueba de alcohol o drogas pierde su licencia por al menos seis meses.","p":"Correcto. Negarse a la prueba significa perder la licencia por al menos seis meses."},"zh":{"q":"在 Vermont，如果司机拒绝警察要求的酒精或药物检测，会怎样？","o":["没事，检测可以不做","DMV 寄来一封警告信","吊销驾照 10 天","失去驾照至少六个月"],"h1":"Vermont 有默示同意法（Implied Consent law），所以拒绝会有真正的后果。","h2":"根据 Vermont 的默示同意法（Implied Consent law），拒绝酒精或药物检测的司机会失去驾照至少六个月。","p":"对。拒绝检测就会失去驾照至少六个月。"},"vi":{"q":"Ở Vermont, điều gì xảy ra nếu tài xế từ chối yêu cầu kiểm tra rượu bia hoặc ma túy của cảnh sát?","o":["Không sao, kiểm tra là tùy ý","Một thư cảnh cáo từ DMV","Bị treo bằng 10 ngày","Mất bằng lái ít nhất sáu tháng"],"h1":"Vermont có luật Đồng Ý Ngầm (Implied Consent law), nên từ chối sẽ có hậu quả thật.","h2":"Theo luật Đồng Ý Ngầm (Implied Consent law) của Vermont, tài xế từ chối kiểm tra rượu bia hoặc ma túy sẽ mất bằng lái ít nhất sáu tháng.","p":"Đúng. Từ chối kiểm tra nghĩa là mất bằng lái ít nhất sáu tháng."},"tl":{"q":"Sa Vermont, ano ang mangyayari kung tumanggi ang drayber sa hiling ng pulis na magpa-test sa alak o droga?","o":["Wala, hindi sapilitan ang test","Isang sulat ng babala mula sa DMV","10 araw na suspensyon","Mawawala ang lisensya nang hindi bababa sa anim na buwan"],"h1":"May Implied Consent law ang Vermont, kaya may tunay na kapalit ang pagtanggi.","h2":"Ayon sa Implied Consent law ng Vermont, ang drayber na tumanggi sa test sa alak o droga ay mawawalan ng lisensya sa pagmamaneho nang hindi bababa sa anim na buwan.","p":"Tama. Kapag tumanggi sa test, mawawala ang lisensya mo nang hindi bababa sa anim na buwan."},"ar":{"q":"في Vermont، ماذا يحدث إذا رفض السائق طلب الشرطي إجراء فحص الكحول أو المخدرات؟","o":["لا شيء، الفحص اختياري","رسالة تحذير من DMV","إيقاف الرخصة 10 أيام","فقدان الرخصة ستة أشهر على الأقل"],"h1":"في Vermont قانون الموافقة الضمنية (Implied Consent law)، لذلك للرفض ثمن حقيقي.","h2":"بموجب قانون الموافقة الضمنية (Implied Consent law) في Vermont، السائق الذي يرفض فحص الكحول أو المخدرات يفقد رخصة القيادة ستة أشهر على الأقل.","p":"صحيح. رفض الفحص يعني فقدان رخصتك ستة أشهر على الأقل."},"ref":{"doc":"VT","page":53}},{"id":"vt-027","scope":"VT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Vermont, how must a child under 2 years old ride in a car?","o":["In a rear-facing car seat with a harness","In a booster seat with a lap belt","In a forward-facing seat in the front","On an adult's lap with a seat belt"],"h1":"The youngest children face the back of the car.","h2":"In Vermont, a child under two years old must ride in an approved rear-facing car seat with a harness, never in front of an active airbag.","p":"Right. Under 2, the child rides rear-facing in a harnessed car seat."},"es":{"q":"En Vermont, ¿cómo debe viajar en el carro un niño menor de 2 años?","o":["En un asiento de seguridad mirando hacia atrás, con arnés","En un asiento elevador con cinturón de cadera","En un asiento mirando hacia adelante, en el frente","En las piernas de un adulto con cinturón"],"h1":"Los niños más pequeños miran hacia la parte de atrás del carro.","h2":"En Vermont, un niño menor de dos años debe viajar en un asiento de seguridad aprobado, mirando hacia atrás y con arnés, nunca delante de una bolsa de aire activa.","p":"Correcto. Antes de los 2 años, el niño va mirando hacia atrás en un asiento con arnés."},"zh":{"q":"在 Vermont，不满 2 岁的孩子坐车时必须怎么坐？","o":["坐在带安全带束带的后向儿童座椅里","坐在增高座椅上，用腰部安全带","坐在前排的前向座椅里","坐在大人腿上，系安全带"],"h1":"最小的孩子要面朝车尾。","h2":"在 Vermont，不满两岁的孩子必须坐在合格的、带束带的后向儿童座椅里，绝不能放在开启的安全气囊前面。","p":"对。不满 2 岁，孩子要坐带束带的后向儿童座椅。"},"vi":{"q":"Ở Vermont, trẻ dưới 2 tuổi phải ngồi trên xe như thế nào?","o":["Trong ghế xe quay mặt về phía sau có dây đai","Trong ghế nâng với dây thắt lưng ngang hông","Trong ghế quay mặt về phía trước ở hàng ghế trước","Trên đùi người lớn có thắt dây an toàn"],"h1":"Trẻ nhỏ nhất quay mặt về phía sau xe.","h2":"Ở Vermont, trẻ dưới hai tuổi phải ngồi trong ghế xe quay mặt về phía sau được chấp thuận, có dây đai, và không bao giờ ngồi trước túi khí đang hoạt động.","p":"Đúng. Dưới 2 tuổi, trẻ ngồi ghế xe quay mặt về phía sau có dây đai."},"tl":{"q":"Sa Vermont, paano dapat sumakay sa kotse ang batang wala pang 2 taong gulang?","o":["Sa car seat na nakaharap sa likod at may harness","Sa booster seat na may lap belt","Sa upuang nakaharap sa unahan sa harap","Sa kandungan ng matanda na may seat belt"],"h1":"Nakaharap sa likod ng kotse ang pinakabatang mga bata.","h2":"Sa Vermont, ang batang wala pang dalawang taong gulang ay dapat sumakay sa aprubadong car seat na nakaharap sa likod at may harness, at hindi kailanman sa harap ng gumaganang airbag.","p":"Tama. Kapag wala pang 2 taon, nakaharap sa likod ang bata sa car seat na may harness."},"ar":{"q":"في Vermont، كيف يجب أن يركب الطفل الذي عمره أقل من 2 سنة في السيارة؟","o":["في مقعد سيارة مواجه للخلف مع أحزمة","في مقعد رافع مع حزام الحِجر","في مقعد مواجه للأمام في المقدمة","في حضن شخص بالغ مع حزام الأمان"],"h1":"أصغر الأطفال يواجهون مؤخرة السيارة.","h2":"في Vermont، يجب أن يركب الطفل الذي عمره أقل من سنتين في مقعد سيارة معتمد مواجه للخلف مع أحزمة، وأبدًا أمام وسادة هوائية تعمل.","p":"صحيح. تحت عمر 2، يركب الطفل في مقعد سيارة مواجه للخلف مع أحزمة."},"ref":{"doc":"VT","page":62}},{"id":"vt-028","scope":"VT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Vermont, you may not park within how many feet of a fire hydrant?","o":["15 feet","6 feet","20 feet","10 feet"],"h1":"Vermont's distance is shorter than in many other states.","h2":"In Vermont, you may not park within 6 feet of a fire hydrant.","p":"Right. Stay at least 6 feet away."},"es":{"q":"En Vermont, ¿a menos de cuántos pies de un hidrante no puede estacionarse?","o":["15 pies","6 pies","20 pies","10 pies"],"h1":"La distancia de Vermont es más corta que en muchos otros estados.","h2":"En Vermont, no puede estacionarse a menos de 6 pies de un hidrante.","p":"Correcto. Quédese al menos a 6 pies."},"zh":{"q":"在 Vermont，你不能把车停在离消防栓多少英尺以内的地方？","o":["15 英尺","6 英尺","20 英尺","10 英尺"],"h1":"Vermont 的距离比很多其他州短。","h2":"在 Vermont，你不能把车停在离消防栓 6 英尺以内的地方。","p":"对。至少离开 6 英尺。"},"vi":{"q":"Ở Vermont, bạn không được đậu xe trong vòng bao nhiêu feet tính từ trụ cứu hỏa?","o":["15 feet","6 feet","20 feet","10 feet"],"h1":"Khoảng cách ở Vermont ngắn hơn ở nhiều tiểu bang khác.","h2":"Ở Vermont, bạn không được đậu xe trong vòng 6 feet tính từ trụ cứu hỏa.","p":"Đúng. Hãy cách ra ít nhất 6 feet."},"tl":{"q":"Sa Vermont, hindi ka puwedeng mag-park sa loob ng ilang feet mula sa fire hydrant?","o":["15 feet","6 feet","20 feet","10 feet"],"h1":"Mas maikli ang layo sa Vermont kaysa sa maraming ibang estado.","h2":"Sa Vermont, hindi ka puwedeng mag-park sa loob ng 6 feet mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 6 feet."},"ar":{"q":"في Vermont، لا يجوز لك أن تركن سيارتك على مسافة أقل من كم قدمًا من حنفية الإطفاء؟","o":["15 قدمًا","6 أقدام","20 قدمًا","10 أقدام"],"h1":"المسافة في Vermont أقصر منها في كثير من الولايات الأخرى.","h2":"في Vermont، لا يجوز لك أن تركن سيارتك على مسافة أقل من 6 أقدام من حنفية الإطفاء.","p":"صحيح. ابقَ بعيدًا 6 أقدام على الأقل."},"ref":{"doc":"VT","page":29}},{"id":"vt-029","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, your driver's license has expired. After how many days is it no longer valid for driving?","o":["30 days","60 days","90 days","14 days"],"h1":"It is about two weeks.","h2":"In Vermont, a license that has been expired for more than 14 days is not valid, and you may not drive with it.","p":"Right. After 14 days."},"es":{"q":"En Vermont, su licencia de conducir está vencida. ¿Después de cuántos días ya no es válida para manejar?","o":["30 días","60 días","90 días","14 días"],"h1":"Son unas dos semanas.","h2":"En Vermont, una licencia que lleva más de 14 días vencida no es válida y no puede manejar con ella.","p":"Correcto. Después de 14 días."},"zh":{"q":"在 Vermont，你的驾照过期了。过期多少天以后就不能再用来开车？","o":["30 天","60 天","90 天","14 天"],"h1":"大约是两个星期。","h2":"在 Vermont，驾照过期超过 14 天就无效了，你不能再用它开车。","p":"对。14 天以后。"},"vi":{"q":"Ở Vermont, bằng lái của bạn đã hết hạn. Sau bao nhiêu ngày thì bằng lái không còn dùng để lái xe được nữa?","o":["30 ngày","60 ngày","90 ngày","14 ngày"],"h1":"Khoảng hai tuần.","h2":"Ở Vermont, bằng lái đã hết hạn hơn 14 ngày thì không còn giá trị, và bạn không được lái xe với bằng lái đó.","p":"Đúng. Sau 14 ngày."},"tl":{"q":"Sa Vermont, expired na ang iyong lisensya sa pagmamaneho. Pagkalipas ng ilang araw ito hindi na puwedeng gamitin sa pagmamaneho?","o":["30 araw","60 araw","90 araw","14 araw"],"h1":"Mga dalawang linggo ito.","h2":"Sa Vermont, hindi na valid ang lisensyang expired nang higit sa 14 araw, at hindi ka puwedeng magmaneho gamit ito.","p":"Tama. Pagkalipas ng 14 araw."},"ar":{"q":"في Vermont، انتهت صلاحية رخصة القيادة الخاصة بك. بعد كم يومًا لا تعود صالحة للقيادة؟","o":["30 يومًا","60 يومًا","90 يومًا","14 يومًا"],"h1":"إنها نحو أسبوعين.","h2":"في Vermont، الرخصة التي انتهت صلاحيتها منذ أكثر من 14 يومًا لا تكون صالحة، ولا يجوز لك أن تقود بها.","p":"صحيح. بعد 14 يومًا."},"ref":{"doc":"VT","page":24}},{"id":"vt-030","scope":"VT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Vermont, how much space should you leave when you pass a bicycle?","o":["At least 4 feet","At least 2 feet","At least 1 foot","At least 10 feet"],"h1":"Give more room than an arm's length.","h2":"In Vermont, you should leave at least four feet of space between your vehicle and a bicycle or vehicle you are passing.","p":"Right. At least four feet."},"es":{"q":"En Vermont, ¿cuánto espacio debe dejar al rebasar a una bicicleta?","o":["Al menos 4 pies","Al menos 2 pies","Al menos 1 pie","Al menos 10 pies"],"h1":"Deje más espacio que el largo de un brazo.","h2":"En Vermont, debe dejar al menos cuatro pies de espacio entre su vehículo y la bicicleta o el vehículo que rebasa.","p":"Correcto. Al menos cuatro pies."},"zh":{"q":"在 Vermont，你超过一辆自行车时，应该留出多少空间？","o":["至少 4 英尺","至少 2 英尺","至少 1 英尺","至少 10 英尺"],"h1":"留出的空间要比一只手臂的长度更多。","h2":"在 Vermont，你超过自行车或其他车辆时，你的车和它之间应该留出至少 4 英尺的空间。","p":"对。至少 4 英尺。"},"vi":{"q":"Ở Vermont, bạn nên chừa bao nhiêu khoảng trống khi vượt một chiếc xe đạp?","o":["Ít nhất 4 feet","Ít nhất 2 feet","Ít nhất 1 foot","Ít nhất 10 feet"],"h1":"Hãy chừa nhiều hơn chiều dài một cánh tay.","h2":"Ở Vermont, bạn nên chừa ít nhất 4 feet giữa xe của bạn và chiếc xe đạp hoặc xe mà bạn đang vượt.","p":"Đúng. Ít nhất 4 feet."},"tl":{"q":"Sa Vermont, gaano kalaking espasyo ang dapat mong iwan kapag nag-o-overtake ka sa bisikleta?","o":["Hindi bababa sa 4 feet","Hindi bababa sa 2 feet","Hindi bababa sa 1 foot","Hindi bababa sa 10 feet"],"h1":"Magbigay ng mas malaking espasyo kaysa sa haba ng isang braso.","h2":"Sa Vermont, dapat kang mag-iwan ng hindi bababa sa 4 feet na espasyo sa pagitan ng iyong sasakyan at ng bisikleta o sasakyang ino-overtake mo.","p":"Tama. Hindi bababa sa 4 feet."},"ar":{"q":"في Vermont، ما المسافة التي يجب أن تتركها عندما تتجاوز درّاجة هوائية؟","o":["4 أقدام على الأقل","قدمان على الأقل","قدم واحدة على الأقل","10 أقدام على الأقل"],"h1":"اترك مسافة أكبر من طول الذراع.","h2":"في Vermont، يجب أن تترك مسافة 4 أقدام على الأقل بين سيارتك والدرّاجة أو المركبة التي تتجاوزها.","p":"صحيح. 4 أقدام على الأقل."},"ref":{"doc":"VT","page":52}},{"id":"vt-031","scope":"VT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Vermont, the law says your headlights must be on when you cannot clearly see people or vehicles how far ahead?","o":["100 feet","250 feet","500 feet","1,000 feet"],"h1":"Think of fog, heavy rain or heavy snow.","h2":"In Vermont, the law requires your headlights to be on whenever you cannot clearly see people or vehicles 500 feet ahead.","p":"Right. 500 feet."},"es":{"q":"En Vermont, la ley exige encender las luces cuando no puede ver con claridad a personas o vehículos a cierta distancia adelante. ¿Cuál es esa distancia?","o":["100 pies","250 pies","500 pies","1,000 pies"],"h1":"Piense en niebla, lluvia fuerte o nieve fuerte.","h2":"En Vermont, la ley exige tener las luces encendidas siempre que no pueda ver con claridad a personas o vehículos a 500 pies adelante.","p":"Correcto. 500 pies."},"zh":{"q":"在 Vermont，法律规定：当你看不清前方多远的人或车辆时，必须打开车头灯？","o":["100 英尺","250 英尺","500 英尺","1,000 英尺"],"h1":"想一想大雾、大雨或大雪的时候。","h2":"在 Vermont，法律规定，只要你看不清前方 500 英尺的人或车辆，就必须打开车头灯。","p":"对。500 英尺。"},"vi":{"q":"Ở Vermont, luật nói rằng bạn phải bật đèn pha khi không thể nhìn rõ người hoặc xe ở phía trước bao xa?","o":["100 feet","250 feet","500 feet","1,000 feet"],"h1":"Hãy nghĩ đến sương mù, mưa lớn hoặc tuyết dày.","h2":"Ở Vermont, luật bắt buộc bạn phải bật đèn pha bất cứ khi nào bạn không thể nhìn rõ người hoặc xe ở phía trước 500 feet.","p":"Đúng. 500 feet."},"tl":{"q":"Sa Vermont, sinasabi ng batas na dapat nakabukas ang iyong headlights kapag hindi mo malinaw na makita ang mga tao o sasakyan sa unahan na gaano kalayo?","o":["100 feet","250 feet","500 feet","1,000 feet"],"h1":"Isipin ang makapal na fog, malakas na ulan o makapal na snow.","h2":"Sa Vermont, iniuutos ng batas na nakabukas ang iyong headlights tuwing hindi mo malinaw na makita ang mga tao o sasakyan na 500 feet sa unahan.","p":"Tama. 500 feet."},"ar":{"q":"في Vermont، يقول القانون إن مصابيحك الأمامية يجب أن تكون مضاءة عندما لا تستطيع أن ترى بوضوح الناس أو المركبات على أي مسافة أمامك؟","o":["100 قدم","250 قدمًا","500 قدم","1,000 قدم"],"h1":"فكّر في الضباب أو المطر الغزير أو الثلج الكثيف.","h2":"في Vermont، يفرض القانون أن تكون مصابيحك الأمامية مضاءة كلما لم تستطع أن ترى بوضوح الناس أو المركبات على بُعد 500 قدم أمامك.","p":"صحيح. 500 قدم."},"ref":{"doc":"VT","page":46}},{"id":"wa-001","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, how many questions are on the knowledge test?","o":["25 questions","40 questions","50 questions","20 questions"],"h1":"It is a round number between 30 and 50.","h2":"The Washington knowledge test has 40 questions.","p":"Right. The test has 40 questions."},"es":{"q":"En Washington, ¿cuántas preguntas tiene el examen de conocimientos?","o":["25 preguntas","40 preguntas","50 preguntas","20 preguntas"],"h1":"Es un número redondo entre 30 y 50.","h2":"El examen de conocimientos de Washington tiene 40 preguntas.","p":"Correcto. El examen tiene 40 preguntas."},"zh":{"q":"在 Washington，笔试（knowledge test）有多少道题？","o":["25 道题","40 道题","50 道题","20 道题"],"h1":"它是 30 到 50 之间的一个整数。","h2":"Washington 的笔试有 40 道题。","p":"对。笔试有 40 道题。"},"vi":{"q":"Ở Washington, bài thi lý thuyết (knowledge test) có bao nhiêu câu hỏi?","o":["25 câu hỏi","40 câu hỏi","50 câu hỏi","20 câu hỏi"],"h1":"Đó là một số tròn giữa 30 và 50.","h2":"Bài thi lý thuyết ở Washington có 40 câu hỏi.","p":"Đúng. Bài thi có 40 câu hỏi."},"tl":{"q":"Sa Washington, ilang tanong ang nasa knowledge test?","o":["25 tanong","40 tanong","50 tanong","20 tanong"],"h1":"Isa itong buong numero sa pagitan ng 30 at 50.","h2":"May 40 tanong ang knowledge test sa Washington.","p":"Tama. May 40 tanong ang test."},"ar":{"q":"في Washington، كم سؤالًا في الامتحان النظري (knowledge test)؟","o":["25 سؤالًا","40 سؤالًا","50 سؤالًا","20 سؤالًا"],"h1":"هو عدد كامل بين 30 و50.","h2":"الامتحان النظري في Washington فيه 40 سؤالًا.","p":"صحيح. في الامتحان 40 سؤالًا."},"ref":{"doc":"WA","page":null}},{"id":"wa-002","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, how many correct answers do you need to pass the knowledge test?","o":["20","28","35","32"],"h1":"It is 80 percent of 40.","h2":"To pass the Washington knowledge test you need 32 correct answers out of 40, which is 80 percent.","p":"Correct. You need 32 right answers."},"es":{"q":"En Washington, ¿cuántas respuestas correctas necesita para aprobar el examen de conocimientos?","o":["20","28","35","32"],"h1":"Es el 80 por ciento de 40.","h2":"Para aprobar el examen de conocimientos de Washington necesita 32 respuestas correctas de 40, que es el 80 por ciento.","p":"Correcto. Necesita 32 respuestas correctas."},"zh":{"q":"在 Washington，笔试要答对多少道题才能通过？","o":["20","28","35","32"],"h1":"它是 40 的 80%。","h2":"要通过 Washington 的笔试，40 道题中你需要答对 32 道，也就是 80%。","p":"对。你需要答对 32 道题。"},"vi":{"q":"Ở Washington, bạn cần trả lời đúng bao nhiêu câu để đậu bài thi lý thuyết?","o":["20","28","35","32"],"h1":"Đó là 80% của 40.","h2":"Để đậu bài thi lý thuyết ở Washington, bạn cần trả lời đúng 32 trên 40 câu, tức là 80%.","p":"Đúng. Bạn cần 32 câu trả lời đúng."},"tl":{"q":"Sa Washington, ilang tamang sagot ang kailangan mo para pumasa sa knowledge test?","o":["20","28","35","32"],"h1":"Ito ang 80% ng 40.","h2":"Para pumasa sa knowledge test sa Washington, kailangan mo ng 32 tamang sagot sa 40, o 80%.","p":"Tama. Kailangan mo ng 32 tamang sagot."},"ar":{"q":"في Washington، كم إجابة صحيحة تحتاج لتنجح في الامتحان النظري؟","o":["20","28","35","32"],"h1":"هي 80% من 40.","h2":"لتنجح في الامتحان النظري في Washington تحتاج 32 إجابة صحيحة من 40، أي 80%.","p":"صحيح. تحتاج 32 إجابة صحيحة."},"ref":{"doc":"WA","page":null}},{"id":"wa-003","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, how long is a passing knowledge test score good for?","o":["2 years","30 days","6 months","Forever"],"h1":"It lasts more than one year.","h2":"A passing score on the Washington knowledge test stays valid for 2 years.","p":"Right. It is good for 2 years."},"es":{"q":"En Washington, ¿por cuánto tiempo es válido un puntaje aprobado en el examen de conocimientos?","o":["2 años","30 días","6 meses","Para siempre"],"h1":"Dura más de un año.","h2":"Un puntaje aprobado en el examen de conocimientos de Washington sigue siendo válido por 2 años.","p":"Correcto. Es válido por 2 años."},"zh":{"q":"在 Washington，笔试及格的成绩有效多久？","o":["2 年","30 天","6 个月","永久"],"h1":"它超过一年。","h2":"Washington 笔试的及格成绩有效期为 2 年。","p":"对。有效期是 2 年。"},"vi":{"q":"Ở Washington, điểm đậu bài thi lý thuyết có giá trị trong bao lâu?","o":["2 năm","30 ngày","6 tháng","Mãi mãi"],"h1":"Nó kéo dài hơn một năm.","h2":"Điểm đậu bài thi lý thuyết ở Washington có giá trị trong 2 năm.","p":"Đúng. Nó có giá trị 2 năm."},"tl":{"q":"Sa Washington, gaano katagal may bisa ang pumasang score sa knowledge test?","o":["2 taon","30 araw","6 na buwan","Habambuhay"],"h1":"Mas matagal ito sa isang taon.","h2":"Ang pumasang score sa knowledge test sa Washington ay may bisa nang 2 taon.","p":"Tama. May bisa ito nang 2 taon."},"ar":{"q":"في Washington، كم مدة صلاحية نتيجة النجاح في الامتحان النظري؟","o":["2 سنة","30 يومًا","6 أشهر","إلى الأبد"],"h1":"هي أكثر من سنة واحدة.","h2":"نتيجة النجاح في الامتحان النظري في Washington تبقى صالحة لمدة 2 سنة.","p":"صحيح. هي صالحة لمدة 2 سنة."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-004","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, what is the youngest age to get an instruction permit if you are enrolled in driver training?","o":["14","14 and a half","15","16"],"h1":"Without a course you would wait six months longer.","h2":"In Washington you can get an instruction permit at 15 if you are enrolled in an approved driver training course.","p":"Correct. Age 15 with driver training."},"es":{"q":"En Washington, ¿cuál es la edad mínima para obtener un permiso de instrucción si está inscrito en un curso de manejo?","o":["14 años","14 años y medio","15 años","16 años"],"h1":"Sin curso tendría que esperar seis meses más.","h2":"En Washington usted puede obtener un permiso de instrucción a los 15 años si está inscrito en un curso de manejo aprobado.","p":"Correcto. A los 15 con curso de manejo."},"zh":{"q":"在 Washington，如果你报名参加了驾驶培训课程，最小几岁可以拿到学习驾照（instruction permit）？","o":["14","14 岁半","15","16"],"h1":"如果不上课程，你要多等六个月。","h2":"在 Washington，如果你报名参加了批准的驾驶培训课程，15 岁就可以拿到学习驾照。","p":"对。参加驾驶培训可以在 15 岁拿到。"},"vi":{"q":"Ở Washington, nếu bạn đã ghi danh khóa huấn luyện lái xe, tuổi nhỏ nhất để lấy giấy phép tập lái (instruction permit) là bao nhiêu?","o":["14","14 tuổi rưỡi","15","16"],"h1":"Nếu không học khóa nào, bạn phải chờ thêm sáu tháng.","h2":"Ở Washington, bạn có thể lấy giấy phép tập lái khi 15 tuổi nếu bạn đã ghi danh một khóa huấn luyện lái xe được chấp thuận.","p":"Đúng. 15 tuổi khi có học lái xe."},"tl":{"q":"Sa Washington, ano ang pinakabatang edad para makakuha ng instruction permit kung naka-enroll ka sa driver training?","o":["14","14 at kalahati","15","16"],"h1":"Kung walang kurso, maghihintay ka pa nang anim na buwan.","h2":"Sa Washington, puwede kang kumuha ng instruction permit sa edad na 15 kung naka-enroll ka sa aprubadong driver training course.","p":"Tama. Edad 15 kapag may driver training."},"ar":{"q":"في Washington، ما أصغر عمر للحصول على تصريح التعلّم (instruction permit) إذا كنت مسجّلًا في دورة تدريب على القيادة؟","o":["14","14 سنة ونصف","15","16"],"h1":"بدون دورة ستنتظر ستة أشهر أكثر.","h2":"في Washington يمكنك الحصول على تصريح التعلّم في عمر 15 سنة إذا كنت مسجّلًا في دورة تدريب على القيادة معتمدة.","p":"صحيح. عمر 15 سنة مع دورة تدريب."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-005","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, what is the youngest age to get an instruction permit without enrolling in driver training?","o":["15","15 and a half","16","17"],"h1":"It is half a year later than with a course.","h2":"In Washington a teen who is not in a driver training course must be 15 and a half to get an instruction permit.","p":"Right. 15 and a half without a course."},"es":{"q":"En Washington, ¿cuál es la edad mínima para obtener un permiso de instrucción sin inscribirse en un curso de manejo?","o":["15 años","15 años y medio","16 años","17 años"],"h1":"Es medio año más tarde que con un curso.","h2":"En Washington un joven que no está en un curso de manejo debe tener 15 años y medio para obtener un permiso de instrucción.","p":"Correcto. 15 años y medio sin curso."},"zh":{"q":"在 Washington，如果不参加驾驶培训课程，最小几岁可以拿到学习驾照（instruction permit）？","o":["15","15 岁半","16","17"],"h1":"它比上课程的情况晚半年。","h2":"在 Washington，没有参加驾驶培训课程的青少年必须年满 15 岁半才能拿到学习驾照。","p":"对。不上课程要 15 岁半。"},"vi":{"q":"Ở Washington, nếu không ghi danh khóa huấn luyện lái xe, tuổi nhỏ nhất để lấy giấy phép tập lái (instruction permit) là bao nhiêu?","o":["15","15 tuổi rưỡi","16","17"],"h1":"Nó trễ hơn nửa năm so với khi có học khóa.","h2":"Ở Washington, thiếu niên không học khóa huấn luyện lái xe phải đủ 15 tuổi rưỡi mới lấy được giấy phép tập lái.","p":"Đúng. 15 tuổi rưỡi nếu không học khóa."},"tl":{"q":"Sa Washington, ano ang pinakabatang edad para makakuha ng instruction permit kung hindi ka naka-enroll sa driver training?","o":["15","15 at kalahati","16","17"],"h1":"Kalahating taon itong mas huli kaysa kapag may kurso.","h2":"Sa Washington, ang tinedyer na wala sa driver training course ay dapat 15 at kalahating taong gulang para makakuha ng instruction permit.","p":"Tama. 15 at kalahati kapag walang kurso."},"ar":{"q":"في Washington، ما أصغر عمر للحصول على تصريح التعلّم (instruction permit) بدون التسجيل في دورة تدريب على القيادة؟","o":["15","15 سنة ونصف","16","17"],"h1":"هو بعد نصف سنة من العمر مع الدورة.","h2":"في Washington يجب أن يكون عمر المراهق غير المسجّل في دورة تدريب على القيادة 15 سنة ونصف ليحصل على تصريح التعلّم.","p":"صحيح. 15 سنة ونصف بدون دورة."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-006","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, who may supervise a driver with an instruction permit?","o":["Any person 16 or older","Any passenger with a car","A driver licensed for at least 1 year","A driver licensed for at least 5 years"],"h1":"The rule is about years of driving experience, not age.","h2":"A Washington permit holder must drive with a driving instructor or a licensed driver who has at least 5 years of driving experience.","p":"Correct. Licensed for 5 years or more."},"es":{"q":"En Washington, ¿quién puede supervisar a un conductor con permiso de instrucción?","o":["Cualquier persona de 16 años o más","Cualquier pasajero que tenga carro","Un conductor con licencia desde hace por lo menos 1 año","Un conductor con licencia desde hace por lo menos 5 años"],"h1":"La regla se refiere a los años de experiencia, no a la edad.","h2":"En Washington, quien tiene permiso debe manejar con un instructor de manejo o con un conductor con licencia que tenga por lo menos 5 años de experiencia.","p":"Correcto. Con licencia desde hace 5 años o más."},"zh":{"q":"在 Washington，谁可以监督持有学习驾照的驾驶人？","o":["任何 16 岁或以上的人","任何有车的乘客","有驾照至少 1 年的驾驶人","有驾照至少 5 年的驾驶人"],"h1":"这条规定看的是驾驶经验的年数，不是年龄。","h2":"Washington 的学习驾照持有人必须和驾驶教练一起开车，或者和有至少 5 年驾驶经验的持照驾驶人一起开车。","p":"对。有驾照 5 年或以上。"},"vi":{"q":"Ở Washington, ai có thể giám sát người lái có giấy phép tập lái?","o":["Bất kỳ ai từ 16 tuổi trở lên","Bất kỳ hành khách nào có xe","Người lái có bằng ít nhất 1 năm","Người lái có bằng ít nhất 5 năm"],"h1":"Quy định này dựa trên số năm kinh nghiệm lái xe, không phải tuổi.","h2":"Ở Washington, người có giấy phép tập lái phải lái cùng giáo viên dạy lái xe hoặc một người có bằng lái với ít nhất 5 năm kinh nghiệm lái xe.","p":"Đúng. Có bằng lái từ 5 năm trở lên."},"tl":{"q":"Sa Washington, sino ang puwedeng magbantay sa driver na may instruction permit?","o":["Kahit sinong 16 taong gulang pataas","Kahit sinong pasahero na may kotse","Driver na may lisensya nang hindi bababa sa 1 taon","Driver na may lisensya nang hindi bababa sa 5 taon"],"h1":"Tungkol sa dami ng taon ng karanasan sa pagmamaneho ang patakaran, hindi sa edad.","h2":"Sa Washington, ang may permit ay dapat magmaneho kasama ang driving instructor o lisensyadong driver na may hindi bababa sa 5 taong karanasan sa pagmamaneho.","p":"Tama. May lisensya nang 5 taon o higit pa."},"ar":{"q":"في Washington، من يمكنه أن يراقب سائقًا معه تصريح تعلّم؟","o":["أي شخص عمره 16 سنة أو أكثر","أي راكب عنده سيارة","سائق معه رخصة منذ سنة 1 على الأقل","سائق معه رخصة منذ 5 سنوات على الأقل"],"h1":"القاعدة عن عدد سنوات الخبرة في القيادة، وليس عن العمر.","h2":"في Washington يجب أن يقود صاحب التصريح مع مدرّب قيادة أو مع سائق له رخصة وخبرة في القيادة 5 سنوات على الأقل.","p":"صحيح. معه رخصة منذ 5 سنوات أو أكثر."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-007","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, where must the supervising driver sit when a permit holder drives?","o":["In the seat beside the driver","In the back seat","Anywhere in the car","In another car following behind"],"h1":"The helper must be close enough to help right away.","h2":"In Washington the supervising driver must sit in the seat beside the permit holder.","p":"Right. Beside the driver."},"es":{"q":"En Washington, ¿dónde debe sentarse el conductor que supervisa cuando maneja alguien con permiso?","o":["En el asiento al lado del conductor","En el asiento de atrás","En cualquier lugar del carro","En otro carro que va detrás"],"h1":"El acompañante debe estar lo bastante cerca para ayudar de inmediato.","h2":"En Washington el conductor que supervisa debe sentarse en el asiento al lado de quien tiene el permiso.","p":"Correcto. Al lado del conductor."},"zh":{"q":"在 Washington，学习驾照持有人开车时，监督的驾驶人必须坐在哪里？","o":["坐在驾驶人旁边的座位","坐在后座","坐在车里任何地方","坐在后面跟着的另一辆车里"],"h1":"帮忙的人必须坐得够近，可以马上帮忙。","h2":"在 Washington，监督的驾驶人必须坐在学习驾照持有人旁边的座位上。","p":"对。坐在驾驶人旁边。"},"vi":{"q":"Ở Washington, khi người có giấy phép tập lái đang lái, người giám sát phải ngồi ở đâu?","o":["Ở ghế bên cạnh người lái","Ở ghế sau","Ở bất kỳ chỗ nào trong xe","Trong một xe khác chạy theo sau"],"h1":"Người giúp phải ngồi đủ gần để giúp ngay lập tức.","h2":"Ở Washington, người giám sát phải ngồi ở ghế bên cạnh người có giấy phép tập lái.","p":"Đúng. Bên cạnh người lái."},"tl":{"q":"Sa Washington, saan dapat umupo ang nagbabantay na driver kapag nagmamaneho ang may permit?","o":["Sa upuan sa tabi ng driver","Sa likod na upuan","Kahit saan sa kotse","Sa ibang kotse na sumusunod sa likod"],"h1":"Dapat sapat na malapit ang tumutulong para makatulong agad.","h2":"Sa Washington, ang nagbabantay na driver ay dapat umupo sa upuan sa tabi ng may permit.","p":"Tama. Sa tabi ng driver."},"ar":{"q":"في Washington، أين يجب أن يجلس السائق المراقب عندما يقود صاحب التصريح؟","o":["في المقعد بجانب السائق","في المقعد الخلفي","في أي مكان في السيارة","في سيارة أخرى تسير خلفه"],"h1":"يجب أن يكون المساعد قريبًا بما يكفي ليساعد فورًا.","h2":"في Washington يجب أن يجلس السائق المراقب في المقعد بجانب صاحب التصريح.","p":"صحيح. بجانب السائق."},"ref":{"doc":"WA","page":null}},{"id":"wa-008","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, how long is an instruction permit valid?","o":["30 days","6 months","1 year","5 years"],"h1":"It can be renewed for a fee when it runs out.","h2":"A Washington instruction permit is valid for 1 year and can be renewed for a fee.","p":"Correct. One year."},"es":{"q":"En Washington, ¿por cuánto tiempo es válido un permiso de instrucción?","o":["30 días","6 meses","1 año","5 años"],"h1":"Se puede renovar pagando una tarifa cuando vence.","h2":"Un permiso de instrucción en Washington es válido por 1 año y se puede renovar pagando una tarifa.","p":"Correcto. Un año."},"zh":{"q":"在 Washington，学习驾照（instruction permit）有效多久？","o":["30 天","6 个月","1 年","5 年"],"h1":"到期后可以付费续期。","h2":"Washington 的学习驾照有效期为 1 年，可以付费续期。","p":"对。一年。"},"vi":{"q":"Ở Washington, giấy phép tập lái (instruction permit) có giá trị trong bao lâu?","o":["30 ngày","6 tháng","1 năm","5 năm"],"h1":"Khi hết hạn, có thể gia hạn nếu trả phí.","h2":"Giấy phép tập lái ở Washington có giá trị 1 năm và có thể gia hạn nếu trả phí.","p":"Đúng. Một năm."},"tl":{"q":"Sa Washington, gaano katagal may bisa ang instruction permit?","o":["30 araw","6 na buwan","1 taon","5 taon"],"h1":"Puwede itong i-renew nang may bayad kapag nag-expire.","h2":"Ang instruction permit sa Washington ay may bisa nang 1 taon at puwedeng i-renew nang may bayad.","p":"Tama. Isang taon."},"ar":{"q":"في Washington، كم مدة صلاحية تصريح التعلّم (instruction permit)؟","o":["30 يومًا","6 أشهر","1 سنة","5 سنوات"],"h1":"يمكن تجديده مقابل رسوم عندما ينتهي.","h2":"تصريح التعلّم في Washington صالح لمدة 1 سنة، ويمكن تجديده مقابل رسوم.","p":"صحيح. سنة واحدة."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-009","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, what must a teen do to get a driver license before turning 18?","o":["Nothing extra","Take a driver training course","Pass a test in another state","Wait until a parent turns 40"],"h1":"Without it, the teen must wait until 18.","h2":"In Washington a teen who wants a driver license before 18 must take a driver training course.","p":"Right. Driver training is required before 18."},"es":{"q":"En Washington, ¿qué debe hacer un joven para obtener la licencia antes de cumplir 18 años?","o":["Nada adicional","Tomar un curso de manejo","Aprobar un examen en otro estado","Esperar a que su padre o madre cumpla 40"],"h1":"Sin esto, el joven debe esperar hasta los 18.","h2":"En Washington un joven que quiere la licencia antes de los 18 años debe tomar un curso de manejo.","p":"Correcto. El curso de manejo es obligatorio antes de los 18."},"zh":{"q":"在 Washington，青少年想在 18 岁以前拿到驾照，必须做什么？","o":["不用做额外的事","参加驾驶培训课程","在另一个州考试","等到父母满 40 岁"],"h1":"如果不做这件事，青少年必须等到 18 岁。","h2":"在 Washington，想在 18 岁以前拿到驾照的青少年必须参加驾驶培训课程。","p":"对。18 岁以前必须参加驾驶培训。"},"vi":{"q":"Ở Washington, thiếu niên phải làm gì để lấy bằng lái trước khi đủ 18 tuổi?","o":["Không cần làm gì thêm","Học một khóa huấn luyện lái xe","Thi ở một tiểu bang khác","Chờ cho đến khi cha mẹ 40 tuổi"],"h1":"Nếu không làm việc này, thiếu niên phải chờ đến 18 tuổi.","h2":"Ở Washington, thiếu niên muốn có bằng lái trước 18 tuổi phải học một khóa huấn luyện lái xe.","p":"Đúng. Phải học lái xe nếu dưới 18 tuổi."},"tl":{"q":"Sa Washington, ano ang dapat gawin ng tinedyer para makakuha ng driver license bago mag-18?","o":["Wala nang iba","Kumuha ng driver training course","Pumasa sa test sa ibang estado","Maghintay hanggang mag-40 ang magulang"],"h1":"Kung wala ito, dapat maghintay ang tinedyer hanggang 18.","h2":"Sa Washington, ang tinedyer na gustong magka-driver license bago mag-18 ay dapat kumuha ng driver training course.","p":"Tama. Kailangan ang driver training bago mag-18."},"ar":{"q":"في Washington، ماذا يجب أن يفعل المراهق ليحصل على رخصة قيادة قبل عمر 18 سنة؟","o":["لا شيء إضافي","أن يأخذ دورة تدريب على القيادة","أن ينجح في امتحان في ولاية أخرى","أن ينتظر حتى يصبح عمر أحد الوالدين 40 سنة"],"h1":"بدون ذلك يجب أن ينتظر المراهق حتى عمر 18 سنة.","h2":"في Washington يجب على المراهق الذي يريد رخصة قيادة قبل عمر 18 سنة أن يأخذ دورة تدريب على القيادة.","p":"صحيح. دورة التدريب مطلوبة قبل عمر 18 سنة."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-010","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, how long must a teen hold an instruction permit before getting an intermediate license?","o":["At least 6 months","At least 1 month","At least 2 years","No minimum"],"h1":"It is half a year.","h2":"A Washington teen must hold an instruction permit for at least 6 months before getting an intermediate license.","p":"Correct. At least 6 months."},"es":{"q":"En Washington, ¿por cuánto tiempo debe un joven tener el permiso de instrucción antes de obtener la licencia intermedia?","o":["Por lo menos 6 meses","Por lo menos 1 mes","Por lo menos 2 años","No hay un mínimo"],"h1":"Es medio año.","h2":"Un joven en Washington debe tener el permiso de instrucción por lo menos 6 meses antes de obtener la licencia intermedia.","p":"Correcto. Por lo menos 6 meses."},"zh":{"q":"在 Washington，青少年要持有学习驾照多久，才能拿到中级驾照（intermediate license）？","o":["至少 6 个月","至少 1 个月","至少 2 年","没有最短时间"],"h1":"是半年。","h2":"Washington 的青少年必须持有学习驾照至少 6 个月，才能拿到中级驾照。","p":"对。至少 6 个月。"},"vi":{"q":"Ở Washington, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái trung cấp (intermediate license)?","o":["Ít nhất 6 tháng","Ít nhất 1 tháng","Ít nhất 2 năm","Không có thời gian tối thiểu"],"h1":"Đó là nửa năm.","h2":"Thiếu niên ở Washington phải giữ giấy phép tập lái ít nhất 6 tháng trước khi lấy bằng lái trung cấp.","p":"Đúng. Ít nhất 6 tháng."},"tl":{"q":"Sa Washington, gaano katagal dapat hawak ng tinedyer ang instruction permit bago makakuha ng intermediate license?","o":["Hindi bababa sa 6 na buwan","Hindi bababa sa 1 buwan","Hindi bababa sa 2 taon","Walang minimum"],"h1":"Kalahating taon ito.","h2":"Ang tinedyer sa Washington ay dapat may hawak na instruction permit nang hindi bababa sa 6 na buwan bago makakuha ng intermediate license.","p":"Tama. Hindi bababa sa 6 na buwan."},"ar":{"q":"في Washington، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل الحصول على الرخصة المتوسطة (intermediate license)؟","o":["6 أشهر على الأقل","شهر 1 على الأقل","2 سنة على الأقل","لا يوجد حد أدنى"],"h1":"هي نصف سنة.","h2":"يجب على المراهق في Washington أن يحمل تصريح التعلّم 6 أشهر على الأقل قبل الحصول على الرخصة المتوسطة.","p":"صحيح. 6 أشهر على الأقل."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-011","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, how many hours of supervised daytime driving does a teen need before an intermediate license?","o":["10 hours","20 hours","30 hours","40 hours"],"h1":"Add 10 night hours to it and you get 50.","h2":"A Washington teen needs at least 40 hours of supervised daytime driving, plus 10 hours at night, before an intermediate license.","p":"Right. Forty daytime hours."},"es":{"q":"En Washington, ¿cuántas horas de manejo supervisado de día necesita un joven antes de la licencia intermedia?","o":["10 horas","20 horas","30 horas","40 horas"],"h1":"Si le suma 10 horas de noche, da 50.","h2":"Un joven en Washington necesita por lo menos 40 horas de manejo supervisado de día, más 10 horas de noche, antes de la licencia intermedia.","p":"Correcto. Cuarenta horas de día."},"zh":{"q":"在 Washington，青少年在拿到中级驾照以前，需要多少小时有人监督的白天驾驶？","o":["10 小时","20 小时","30 小时","40 小时"],"h1":"再加上 10 小时夜间驾驶，就是 50 小时。","h2":"Washington 的青少年在拿到中级驾照以前，需要至少 40 小时有人监督的白天驾驶，再加 10 小时夜间驾驶。","p":"对。白天 40 小时。"},"vi":{"q":"Ở Washington, thiếu niên cần bao nhiêu giờ lái ban ngày có người giám sát trước khi lấy bằng lái trung cấp?","o":["10 giờ","20 giờ","30 giờ","40 giờ"],"h1":"Cộng thêm 10 giờ ban đêm thì được 50.","h2":"Thiếu niên ở Washington cần ít nhất 40 giờ lái ban ngày có người giám sát, cộng thêm 10 giờ ban đêm, trước khi lấy bằng lái trung cấp.","p":"Đúng. Bốn mươi giờ ban ngày."},"tl":{"q":"Sa Washington, ilang oras ng binabantayang pagmamaneho sa araw ang kailangan ng tinedyer bago makakuha ng intermediate license?","o":["10 oras","20 oras","30 oras","40 oras"],"h1":"Dagdagan ito ng 10 oras sa gabi at magiging 50.","h2":"Ang tinedyer sa Washington ay kailangan ng hindi bababa sa 40 oras ng binabantayang pagmamaneho sa araw, at 10 oras sa gabi, bago makakuha ng intermediate license.","p":"Tama. Apatnapung oras sa araw."},"ar":{"q":"في Washington، كم ساعة من القيادة في النهار مع مراقب يحتاج المراهق قبل الرخصة المتوسطة؟","o":["10 ساعات","20 ساعة","30 ساعة","40 ساعة"],"h1":"أضف إليها 10 ساعات في الليل فتصبح 50.","h2":"يحتاج المراهق في Washington إلى 40 ساعة على الأقل من القيادة في النهار مع مراقب، وأيضًا 10 ساعات في الليل، قبل الرخصة المتوسطة.","p":"صحيح. أربعون ساعة في النهار."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-012","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, how many hours of supervised night driving does a teen need before an intermediate license?","o":["2 hours","5 hours","10 hours","40 hours"],"h1":"It is a round number, a quarter of the daytime hours.","h2":"A Washington teen needs at least 10 hours of supervised night driving before an intermediate license.","p":"Correct. Ten night hours."},"es":{"q":"En Washington, ¿cuántas horas de manejo supervisado de noche necesita un joven antes de la licencia intermedia?","o":["2 horas","5 horas","10 horas","40 horas"],"h1":"Es un número redondo, la cuarta parte de las horas de día.","h2":"Un joven en Washington necesita por lo menos 10 horas de manejo supervisado de noche antes de la licencia intermedia.","p":"Correcto. Diez horas de noche."},"zh":{"q":"在 Washington，青少年在拿到中级驾照以前，需要多少小时有人监督的夜间驾驶？","o":["2 小时","5 小时","10 小时","40 小时"],"h1":"它是一个整数，是白天小时数的四分之一。","h2":"Washington 的青少年在拿到中级驾照以前，需要至少 10 小时有人监督的夜间驾驶。","p":"对。夜间 10 小时。"},"vi":{"q":"Ở Washington, thiếu niên cần bao nhiêu giờ lái ban đêm có người giám sát trước khi lấy bằng lái trung cấp?","o":["2 giờ","5 giờ","10 giờ","40 giờ"],"h1":"Đó là một số tròn, bằng một phần tư số giờ ban ngày.","h2":"Thiếu niên ở Washington cần ít nhất 10 giờ lái ban đêm có người giám sát trước khi lấy bằng lái trung cấp.","p":"Đúng. Mười giờ ban đêm."},"tl":{"q":"Sa Washington, ilang oras ng binabantayang pagmamaneho sa gabi ang kailangan ng tinedyer bago makakuha ng intermediate license?","o":["2 oras","5 oras","10 oras","40 oras"],"h1":"Isa itong buong numero, isang-kapat ng oras sa araw.","h2":"Ang tinedyer sa Washington ay kailangan ng hindi bababa sa 10 oras ng binabantayang pagmamaneho sa gabi bago makakuha ng intermediate license.","p":"Tama. Sampung oras sa gabi."},"ar":{"q":"في Washington، كم ساعة من القيادة في الليل مع مراقب يحتاج المراهق قبل الرخصة المتوسطة؟","o":["2 ساعة","5 ساعات","10 ساعات","40 ساعة"],"h1":"هو عدد كامل، ربع ساعات النهار.","h2":"يحتاج المراهق في Washington إلى 10 ساعات على الأقل من القيادة في الليل مع مراقب قبل الرخصة المتوسطة.","p":"صحيح. عشر ساعات في الليل."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-013","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, what is the youngest age to apply for an intermediate license?","o":["15","16","17","18"],"h1":"It comes after holding a permit for at least six months.","h2":"In Washington you can apply for an intermediate license at 16.","p":"Right. Age 16."},"es":{"q":"En Washington, ¿cuál es la edad mínima para solicitar una licencia intermedia?","o":["15 años","16 años","17 años","18 años"],"h1":"Llega después de tener el permiso por lo menos seis meses.","h2":"En Washington usted puede solicitar una licencia intermedia a los 16 años.","p":"Correcto. A los 16 años."},"zh":{"q":"在 Washington，最小几岁可以申请中级驾照（intermediate license）？","o":["15","16","17","18"],"h1":"它是在持有学习驾照至少六个月以后。","h2":"在 Washington，你 16 岁可以申请中级驾照。","p":"对。16 岁。"},"vi":{"q":"Ở Washington, tuổi nhỏ nhất để nộp đơn xin bằng lái trung cấp (intermediate license) là bao nhiêu?","o":["15","16","17","18"],"h1":"Nó đến sau khi giữ giấy phép tập lái ít nhất sáu tháng.","h2":"Ở Washington, bạn có thể nộp đơn xin bằng lái trung cấp khi 16 tuổi.","p":"Đúng. 16 tuổi."},"tl":{"q":"Sa Washington, ano ang pinakabatang edad para mag-apply ng intermediate license?","o":["15","16","17","18"],"h1":"Darating ito pagkatapos hawakan ang permit nang hindi bababa sa anim na buwan.","h2":"Sa Washington, puwede kang mag-apply ng intermediate license sa edad na 16.","p":"Tama. Edad 16."},"ar":{"q":"في Washington، ما أصغر عمر لتقديم طلب الرخصة المتوسطة (intermediate license)؟","o":["15","16","17","18"],"h1":"يأتي بعد حمل التصريح ستة أشهر على الأقل.","h2":"في Washington يمكنك تقديم طلب الرخصة المتوسطة في عمر 16 سنة.","p":"صحيح. عمر 16 سنة."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-014","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, during which hours may an intermediate license holder not drive, unless an exception applies?","o":["1 a.m. to 5 a.m.","Midnight to 6 a.m.","10 p.m. to 5 a.m.","11 p.m. to 4 a.m."],"h1":"The window is four hours long and starts after midnight.","h2":"A Washington intermediate license holder may not drive between 1 a.m. and 5 a.m., unless an exception applies.","p":"Correct. No driving from 1 to 5 a.m."},"es":{"q":"En Washington, ¿en qué horario no puede manejar el titular de una licencia intermedia, salvo una excepción?","o":["De 1 a.m. a 5 a.m.","De medianoche a 6 a.m.","De 10 p.m. a 5 a.m.","De 11 p.m. a 4 a.m."],"h1":"El período dura cuatro horas y empieza después de medianoche.","h2":"El titular de una licencia intermedia en Washington no puede manejar entre la 1 a.m. y las 5 a.m., salvo una excepción.","p":"Correcto. No se maneja de 1 a 5 a.m."},"zh":{"q":"在 Washington，除非有例外情况，中级驾照持有人在哪段时间不可以开车？","o":["凌晨 1 点到凌晨 5 点","午夜 12 点到早上 6 点","晚上 10 点到凌晨 5 点","晚上 11 点到凌晨 4 点"],"h1":"这段时间有四个小时，在午夜以后开始。","h2":"除非有例外情况，Washington 的中级驾照持有人不可以在凌晨 1 点到凌晨 5 点之间开车。","p":"对。凌晨 1 点到 5 点不能开车。"},"vi":{"q":"Ở Washington, trừ khi có trường hợp ngoại lệ, người có bằng lái trung cấp không được lái xe trong khoảng giờ nào?","o":["1 giờ sáng đến 5 giờ sáng","Nửa đêm đến 6 giờ sáng","10 giờ tối đến 5 giờ sáng","11 giờ tối đến 4 giờ sáng"],"h1":"Khoảng thời gian này dài bốn giờ và bắt đầu sau nửa đêm.","h2":"Người có bằng lái trung cấp ở Washington không được lái xe từ 1 giờ sáng đến 5 giờ sáng, trừ khi có trường hợp ngoại lệ.","p":"Đúng. Không lái từ 1 đến 5 giờ sáng."},"tl":{"q":"Sa Washington, anong oras hindi puwedeng magmaneho ang may intermediate license, maliban kung may exception?","o":["1 a.m. hanggang 5 a.m.","Hatinggabi hanggang 6 a.m.","10 p.m. hanggang 5 a.m.","11 p.m. hanggang 4 a.m."],"h1":"Apat na oras ang haba nito at nagsisimula pagkatapos ng hatinggabi.","h2":"Ang may intermediate license sa Washington ay hindi puwedeng magmaneho mula 1 a.m. hanggang 5 a.m., maliban kung may exception.","p":"Tama. Bawal magmaneho mula 1 hanggang 5 a.m."},"ar":{"q":"في Washington، في أي ساعات لا يجوز لصاحب الرخصة المتوسطة أن يقود، إلا إذا كان هناك استثناء؟","o":["من 1 صباحًا إلى 5 صباحًا","من منتصف الليل إلى 6 صباحًا","من 10 مساءً إلى 5 صباحًا","من 11 مساءً إلى 4 صباحًا"],"h1":"المدة أربع ساعات وتبدأ بعد منتصف الليل.","h2":"لا يجوز لصاحب الرخصة المتوسطة في Washington أن يقود بين 1 صباحًا و5 صباحًا، إلا إذا كان هناك استثناء.","p":"صحيح. لا قيادة من 1 إلى 5 صباحًا."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-015","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, which of these lets an intermediate license holder drive between 1 a.m. and 5 a.m.?","o":["Driving to a party","Driving with a friend who is 18","Driving on an empty road","Driving with a licensed driver who is at least 25"],"h1":"An older, experienced driver must be in the car, or the trip is for school, religion or work.","h2":"In Washington an intermediate license holder may drive between 1 a.m. and 5 a.m. with a licensed driver at least 25, or for school, religious or work activities.","p":"Right. A licensed driver 25 or older."},"es":{"q":"En Washington, ¿cuál de estas opciones permite al titular de una licencia intermedia manejar entre la 1 a.m. y las 5 a.m.?","o":["Ir a una fiesta","Manejar con un amigo de 18 años","Manejar por una calle vacía","Manejar con un conductor con licencia de por lo menos 25 años"],"h1":"Debe ir un conductor mayor con experiencia, o el viaje debe ser por escuela, religión o trabajo.","h2":"En Washington el titular de una licencia intermedia puede manejar entre la 1 a.m. y las 5 a.m. con un conductor con licencia de por lo menos 25 años, o para actividades escolares, religiosas o de trabajo.","p":"Correcto. Un conductor con licencia de 25 años o más."},"zh":{"q":"在 Washington，下面哪一种情况可以让中级驾照持有人在凌晨 1 点到凌晨 5 点之间开车？","o":["开车去参加聚会","和一个 18 岁的朋友一起开车","在空荡的路上开车","和一个至少 25 岁的持照驾驶人一起开车"],"h1":"车里必须有一位年龄较大、有经验的驾驶人，或者是为了上学、宗教或工作。","h2":"在 Washington，中级驾照持有人可以在凌晨 1 点到凌晨 5 点之间开车，条件是有一位至少 25 岁的持照驾驶人在车上，或者是为了上学、宗教或工作活动。","p":"对。一位 25 岁或以上的持照驾驶人。"},"vi":{"q":"Ở Washington, điều nào sau đây cho phép người có bằng lái trung cấp lái xe từ 1 giờ sáng đến 5 giờ sáng?","o":["Lái xe đi dự tiệc","Lái xe với một người bạn 18 tuổi","Lái xe trên đường vắng","Lái xe với một người có bằng lái ít nhất 25 tuổi"],"h1":"Phải có một người lái lớn tuổi, có kinh nghiệm trong xe, hoặc chuyến đi là vì trường học, tôn giáo hay công việc.","h2":"Ở Washington, người có bằng lái trung cấp có thể lái xe từ 1 giờ sáng đến 5 giờ sáng khi có một người có bằng lái ít nhất 25 tuổi đi cùng, hoặc vì các hoạt động trường học, tôn giáo hay công việc.","p":"Đúng. Một người có bằng lái từ 25 tuổi trở lên."},"tl":{"q":"Sa Washington, alin dito ang nagpapahintulot sa may intermediate license na magmaneho mula 1 a.m. hanggang 5 a.m.?","o":["Pagmamaneho papunta sa party","Pagmamaneho kasama ang kaibigang 18 taong gulang","Pagmamaneho sa walang lamang kalsada","Pagmamaneho kasama ang lisensyadong driver na hindi bababa sa 25 taong gulang"],"h1":"Dapat may mas matanda at may karanasang driver sa kotse, o ang biyahe ay para sa paaralan, relihiyon o trabaho.","h2":"Sa Washington, ang may intermediate license ay puwedeng magmaneho mula 1 a.m. hanggang 5 a.m. kasama ang lisensyadong driver na hindi bababa sa 25 taong gulang, o para sa gawain sa paaralan, relihiyon o trabaho.","p":"Tama. Lisensyadong driver na 25 pataas."},"ar":{"q":"في Washington، أي من هذه يسمح لصاحب الرخصة المتوسطة أن يقود بين 1 صباحًا و5 صباحًا؟","o":["القيادة إلى حفلة","القيادة مع صديق عمره 18 سنة","القيادة في طريق فارغ","القيادة مع سائق له رخصة وعمره 25 سنة على الأقل"],"h1":"يجب أن يكون في السيارة سائق أكبر سنًا وله خبرة، أو تكون الرحلة للمدرسة أو الدين أو العمل.","h2":"في Washington يجوز لصاحب الرخصة المتوسطة أن يقود بين 1 صباحًا و5 صباحًا مع سائق له رخصة وعمره 25 سنة على الأقل، أو لأنشطة المدرسة أو الدين أو العمل.","p":"صحيح. سائق له رخصة وعمره 25 سنة أو أكثر."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-016","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, during the first six months of an intermediate license, which passengers under 20 may ride with the driver?","o":["Only immediate family members","Up to three friends","One friend","Anyone"],"h1":"Friends under 20 have to wait.","h2":"During the first six months, a Washington intermediate license holder may carry no passengers under 20 except immediate family members.","p":"Correct. Only immediate family."},"es":{"q":"En Washington, durante los primeros seis meses de la licencia intermedia, ¿qué pasajeros menores de 20 años pueden ir con el conductor?","o":["Solo familiares directos","Hasta tres amigos","Un amigo","Cualquier persona"],"h1":"Los amigos menores de 20 tienen que esperar.","h2":"Durante los primeros seis meses, el titular de una licencia intermedia en Washington no puede llevar pasajeros menores de 20 años, excepto familiares directos.","p":"Correcto. Solo familiares directos."},"zh":{"q":"在 Washington，拿到中级驾照的头六个月里，哪些 20 岁以下的乘客可以坐驾驶人的车？","o":["只有直系家庭成员","最多三个朋友","一个朋友","任何人"],"h1":"20 岁以下的朋友要等一等。","h2":"在头六个月里，Washington 的中级驾照持有人除了直系家庭成员以外，不可以载任何 20 岁以下的乘客。","p":"对。只有直系家庭成员。"},"vi":{"q":"Ở Washington, trong sáu tháng đầu có bằng lái trung cấp, những hành khách dưới 20 tuổi nào được đi cùng người lái?","o":["Chỉ người trong gia đình trực hệ","Tối đa ba người bạn","Một người bạn","Bất kỳ ai"],"h1":"Bạn bè dưới 20 tuổi phải chờ.","h2":"Trong sáu tháng đầu, người có bằng lái trung cấp ở Washington không được chở hành khách nào dưới 20 tuổi, trừ người trong gia đình trực hệ.","p":"Đúng. Chỉ gia đình trực hệ."},"tl":{"q":"Sa Washington, sa unang anim na buwan ng intermediate license, aling mga pasaherong wala pang 20 ang puwedeng sumakay kasama ng driver?","o":["Mga kasapi lamang ng malapit na pamilya","Hanggang tatlong kaibigan","Isang kaibigan","Kahit sino"],"h1":"Kailangang maghintay ang mga kaibigang wala pang 20.","h2":"Sa unang anim na buwan, ang may intermediate license sa Washington ay hindi puwedeng magsakay ng pasaherong wala pang 20, maliban sa mga kasapi ng malapit na pamilya.","p":"Tama. Malapit na pamilya lamang."},"ar":{"q":"في Washington، في أول ستة أشهر من الرخصة المتوسطة، أي ركاب تحت 20 سنة يمكنهم الركوب مع السائق؟","o":["أفراد العائلة المباشرة فقط","حتى ثلاثة أصدقاء","صديق واحد","أي شخص"],"h1":"الأصدقاء تحت 20 سنة يجب أن ينتظروا.","h2":"في أول ستة أشهر، لا يجوز لصاحب الرخصة المتوسطة في Washington أن ينقل أي ركاب تحت 20 سنة إلا أفراد العائلة المباشرة.","p":"صحيح. العائلة المباشرة فقط."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-017","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, after the first six months of an intermediate license, how many non-family passengers under 20 may the driver carry?","o":["None","One","Up to three","Up to five"],"h1":"The limit goes up after six months, but it is still a small number.","h2":"After the first six months, a Washington intermediate license holder may carry no more than three passengers under 20 who are not immediate family.","p":"Right. Up to three."},"es":{"q":"En Washington, después de los primeros seis meses de la licencia intermedia, ¿cuántos pasajeros menores de 20 años que no son familiares puede llevar el conductor?","o":["Ninguno","Uno","Hasta tres","Hasta cinco"],"h1":"El límite sube después de seis meses, pero sigue siendo pequeño.","h2":"Después de los primeros seis meses, el titular de una licencia intermedia en Washington no puede llevar más de tres pasajeros menores de 20 años que no sean familiares directos.","p":"Correcto. Hasta tres."},"zh":{"q":"在 Washington，拿到中级驾照六个月以后，驾驶人可以载多少个 20 岁以下、不是家人的乘客？","o":["一个也不行","一个","最多三个","最多五个"],"h1":"六个月以后人数限制会提高，但仍然是一个小数字。","h2":"头六个月以后，Washington 的中级驾照持有人最多可以载三个不是直系家庭成员的 20 岁以下乘客。","p":"对。最多三个。"},"vi":{"q":"Ở Washington, sau sáu tháng đầu có bằng lái trung cấp, người lái được chở bao nhiêu hành khách dưới 20 tuổi không phải người trong gia đình?","o":["Không ai","Một người","Tối đa ba người","Tối đa năm người"],"h1":"Giới hạn tăng lên sau sáu tháng, nhưng vẫn là một số nhỏ.","h2":"Sau sáu tháng đầu, người có bằng lái trung cấp ở Washington được chở không quá ba hành khách dưới 20 tuổi không phải người trong gia đình trực hệ.","p":"Đúng. Tối đa ba người."},"tl":{"q":"Sa Washington, pagkatapos ng unang anim na buwan ng intermediate license, ilang pasaherong wala pang 20 at hindi kapamilya ang puwedeng isakay ng driver?","o":["Wala","Isa","Hanggang tatlo","Hanggang lima"],"h1":"Tumataas ang limitasyon pagkatapos ng anim na buwan, pero maliit na numero pa rin ito.","h2":"Pagkatapos ng unang anim na buwan, ang may intermediate license sa Washington ay puwedeng magsakay ng hindi hihigit sa tatlong pasaherong wala pang 20 na hindi malapit na kapamilya.","p":"Tama. Hanggang tatlo."},"ar":{"q":"في Washington، بعد أول ستة أشهر من الرخصة المتوسطة، كم راكبًا تحت 20 سنة من غير العائلة يمكن للسائق أن ينقل؟","o":["لا أحد","واحد","حتى ثلاثة","حتى خمسة"],"h1":"الحد يرتفع بعد ستة أشهر، لكنه ما زال عددًا صغيرًا.","h2":"بعد أول ستة أشهر، يجوز لصاحب الرخصة المتوسطة في Washington أن ينقل ثلاثة ركاب على الأكثر تحت 20 سنة ليسوا من العائلة المباشرة.","p":"صحيح. حتى ثلاثة."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-018","scope":"WA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Washington, may a driver with an instruction permit or intermediate license use a phone hands-free?","o":["Yes, any time","No, only in an emergency","Yes, at red lights","Yes, for short calls"],"h1":"New drivers have a stricter rule than other drivers.","h2":"In Washington permit and intermediate license holders may not use a wireless device at all, even hands-free, except in an emergency.","p":"Correct. No phone except in an emergency."},"es":{"q":"En Washington, ¿puede un conductor con permiso de instrucción o licencia intermedia usar el teléfono con manos libres?","o":["Sí, en cualquier momento","No, solo en una emergencia","Sí, en los semáforos en rojo","Sí, para llamadas cortas"],"h1":"Los conductores nuevos tienen una regla más estricta que los demás.","h2":"En Washington quienes tienen permiso o licencia intermedia no pueden usar ningún dispositivo inalámbrico, ni siquiera con manos libres, excepto en una emergencia.","p":"Correcto. Nada de teléfono salvo en una emergencia."},"zh":{"q":"在 Washington，持有学习驾照或中级驾照的驾驶人可以用免提方式打电话吗？","o":["可以，任何时候都可以","不可以，只有紧急情况可以","可以，在红灯时可以","可以，打短电话可以"],"h1":"新驾驶人的规定比其他驾驶人更严格。","h2":"在 Washington，学习驾照和中级驾照持有人完全不可以使用无线设备，即使是免提也不行，紧急情况除外。","p":"对。除了紧急情况，不能用电话。"},"vi":{"q":"Ở Washington, người lái có giấy phép tập lái hoặc bằng lái trung cấp có được dùng điện thoại rảnh tay (hands-free) không?","o":["Có, bất cứ lúc nào","Không, chỉ khi khẩn cấp","Có, khi dừng đèn đỏ","Có, cho các cuộc gọi ngắn"],"h1":"Người mới lái có quy định nghiêm hơn những người lái khác.","h2":"Ở Washington, người có giấy phép tập lái và bằng lái trung cấp hoàn toàn không được dùng thiết bị không dây, kể cả rảnh tay, trừ khi khẩn cấp.","p":"Đúng. Không dùng điện thoại trừ khi khẩn cấp."},"tl":{"q":"Sa Washington, puwede bang gumamit ng phone nang hands-free ang driver na may instruction permit o intermediate license?","o":["Oo, kahit kailan","Hindi, sa emergency lamang","Oo, sa red light","Oo, para sa maiikling tawag"],"h1":"Mas mahigpit ang patakaran para sa mga bagong driver kaysa sa ibang driver.","h2":"Sa Washington, ang may permit at intermediate license ay hindi puwedeng gumamit ng wireless device kahit kailan, kahit hands-free, maliban sa emergency.","p":"Tama. Bawal ang phone maliban sa emergency."},"ar":{"q":"في Washington، هل يجوز للسائق الذي معه تصريح تعلّم أو رخصة متوسطة أن يستعمل الهاتف بدون يدين (hands-free)؟","o":["نعم، في أي وقت","لا، فقط في حالة طوارئ","نعم، عند الإشارة الحمراء","نعم، للمكالمات القصيرة"],"h1":"للسائقين الجدد قاعدة أشد من السائقين الآخرين.","h2":"في Washington لا يجوز لأصحاب التصريح والرخصة المتوسطة أن يستعملوا أي جهاز لاسلكي أبدًا، حتى بدون يدين، إلا في حالة طوارئ.","p":"صحيح. لا هاتف إلا في حالة طوارئ."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-019","scope":"WA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Washington, may any driver hold a phone while stopped at a red light?","o":["Yes, while the light is red","Yes, if the engine is running","No, not even when stopped in traffic or at a light","Yes, to read a text"],"h1":"Being stopped in traffic still counts as driving.","h2":"Washington's distracted driving law says a driver may not hold a phone even when stopped in traffic or at a light.","p":"Right. Not even at a red light."},"es":{"q":"En Washington, ¿puede cualquier conductor sostener el teléfono mientras está detenido en un semáforo en rojo?","o":["Sí, mientras la luz está en rojo","Sí, si el motor está encendido","No, ni siquiera detenido en el tráfico o en un semáforo","Sí, para leer un mensaje"],"h1":"Estar detenido en el tráfico todavía cuenta como manejar.","h2":"La ley de manejo distraído de Washington dice que un conductor no puede sostener el teléfono ni siquiera detenido en el tráfico o en un semáforo.","p":"Correcto. Ni siquiera en un semáforo en rojo."},"zh":{"q":"在 Washington，任何驾驶人在红灯前停车时可以拿着手机吗？","o":["可以，在红灯时可以","可以，如果引擎还开着","不可以，即使在车流中停着或在红绿灯前停着也不可以","可以，用来看短信"],"h1":"在车流中停着仍然算是在开车。","h2":"Washington 的分心驾驶法规定，即使在车流中停着或在红绿灯前停着，驾驶人也不可以拿着手机。","p":"对。在红灯前也不可以。"},"vi":{"q":"Ở Washington, người lái nào cũng có được cầm điện thoại khi dừng đèn đỏ không?","o":["Có, khi đèn đang đỏ","Có, nếu máy xe đang chạy","Không, kể cả khi dừng trong dòng xe hay ở đèn giao thông","Có, để đọc tin nhắn"],"h1":"Dừng trong dòng xe vẫn được tính là đang lái xe.","h2":"Luật lái xe mất tập trung của Washington nói rằng người lái không được cầm điện thoại, kể cả khi dừng trong dòng xe hay ở đèn giao thông.","p":"Đúng. Kể cả ở đèn đỏ cũng không được."},"tl":{"q":"Sa Washington, puwede bang humawak ng phone ang kahit sinong driver habang nakahinto sa red light?","o":["Oo, habang pula ang ilaw","Oo, kung umaandar ang makina","Hindi, kahit nakahinto sa trapiko o sa ilaw","Oo, para magbasa ng text"],"h1":"Ang pagkakahinto sa trapiko ay itinuturing pa ring pagmamaneho.","h2":"Ayon sa distracted driving law ng Washington, hindi puwedeng humawak ng phone ang driver kahit nakahinto sa trapiko o sa ilaw.","p":"Tama. Kahit sa red light, bawal."},"ar":{"q":"في Washington، هل يجوز لأي سائق أن يمسك الهاتف وهو متوقف عند إشارة حمراء؟","o":["نعم، ما دامت الإشارة حمراء","نعم، إذا كان المحرك يعمل","لا، حتى عند التوقف في زحمة السير أو عند الإشارة","نعم، لقراءة رسالة"],"h1":"التوقف في زحمة السير ما زال يُعدّ قيادة.","h2":"قانون القيادة مع تشتّت الانتباه في Washington يقول إن السائق لا يجوز له أن يمسك الهاتف حتى عند التوقف في زحمة السير أو عند الإشارة.","p":"صحيح. ولا حتى عند الإشارة الحمراء."},"ref":{"doc":"WA","page":"§3.4"}},{"id":"wa-020","scope":"WA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Washington, if you cannot move over a lane for a stopped emergency vehicle, how much must you slow down?","o":["5 mph below the limit","To 15 mph","Not at all","At least 10 mph below the posted limit"],"h1":"It is a round number of miles per hour below the limit.","h2":"In Washington, if you cannot safely move over one lane, you must slow to at least 10 mph below the posted speed limit.","p":"Correct. At least 10 mph slower."},"es":{"q":"En Washington, si no puede cambiarse de carril por un vehículo de emergencia detenido, ¿cuánto debe reducir la velocidad?","o":["5 mph menos que el límite","Hasta 15 mph","Nada","Por lo menos 10 mph menos que el límite indicado"],"h1":"Es un número redondo de millas por hora menos que el límite.","h2":"En Washington, si no puede cambiarse un carril con seguridad, debe bajar la velocidad por lo menos 10 mph por debajo del límite indicado.","p":"Correcto. Por lo menos 10 mph menos."},"zh":{"q":"在 Washington，如果你没办法为停着的紧急车辆让出一条车道，你必须减速多少？","o":["比限速低 5 mph","降到 15 mph","完全不用减速","比标示的限速至少低 10 mph"],"h1":"它是比限速低一个整数的 mph。","h2":"在 Washington，如果你没办法安全地让出一条车道，你必须把速度降到比标示的限速至少低 10 mph。","p":"对。至少慢 10 mph。"},"vi":{"q":"Ở Washington, nếu bạn không thể chuyển sang làn khác để tránh xe cấp cứu đang dừng, bạn phải giảm tốc độ bao nhiêu?","o":["Thấp hơn giới hạn 5 mph","Xuống 15 mph","Không cần giảm","Thấp hơn giới hạn tốc độ ghi trên biển ít nhất 10 mph"],"h1":"Đó là một số tròn mph thấp hơn giới hạn.","h2":"Ở Washington, nếu bạn không thể chuyển sang một làn khác một cách an toàn, bạn phải giảm tốc độ xuống thấp hơn giới hạn tốc độ ghi trên biển ít nhất 10 mph.","p":"Đúng. Chậm hơn ít nhất 10 mph."},"tl":{"q":"Sa Washington, kung hindi ka makalipat ng lane para sa nakahintong emergency vehicle, gaano mo dapat bagalan ang takbo?","o":["5 mph na mas mababa sa limit","Hanggang 15 mph","Hindi na kailangan","Hindi bababa sa 10 mph na mas mababa sa nakapaskil na limit"],"h1":"Isa itong buong numero ng mph na mas mababa sa limit.","h2":"Sa Washington, kung hindi ka ligtas na makalipat ng isang lane, dapat mong bagalan ang takbo nang hindi bababa sa 10 mph na mas mababa sa nakapaskil na speed limit.","p":"Tama. Hindi bababa sa 10 mph na mas mabagal."},"ar":{"q":"في Washington، إذا لم تستطع الانتقال إلى مسار آخر بعيدًا عن سيارة طوارئ متوقفة، كم يجب أن تخفّف سرعتك؟","o":["5 mph أقل من الحد","إلى 15 mph","لا تخفّف أبدًا","10 mph على الأقل أقل من الحد المكتوب على اللافتة"],"h1":"هو عدد كامل من mph أقل من الحد.","h2":"في Washington، إذا لم تستطع الانتقال مسارًا واحدًا بأمان، يجب أن تخفّف سرعتك إلى 10 mph على الأقل أقل من حد السرعة المكتوب على اللافتة.","p":"صحيح. أبطأ بـ 10 mph على الأقل."},"ref":{"doc":"WA","page":"§4.17"}},{"id":"wa-021","scope":"WA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Washington, how far before and after a stopped emergency vehicle does the Move Over zone reach?","o":["50 feet","200 feet","500 feet","One mile"],"h1":"It is a few car lengths more than 100 feet.","h2":"In Washington the Move Over zone covers 200 feet before and 200 feet after the stopped emergency or work vehicle.","p":"Right. 200 feet each way."},"es":{"q":"En Washington, ¿hasta qué distancia antes y después de un vehículo de emergencia detenido llega la zona de Move Over?","o":["50 pies","200 pies","500 pies","Una milla"],"h1":"Es unos cuantos carros más que 100 pies.","h2":"En Washington la zona de Move Over cubre 200 pies antes y 200 pies después del vehículo de emergencia o de trabajo detenido.","p":"Correcto. 200 pies en cada dirección."},"zh":{"q":"在 Washington，让道区（Move Over zone）在停着的紧急车辆前后各有多远？","o":["50 英尺","200 英尺","500 英尺","1 英里"],"h1":"它比 100 英尺多几个车身的长度。","h2":"在 Washington，让道区包括停着的紧急车辆或工作车辆前面 200 英尺和后面 200 英尺。","p":"对。前后各 200 英尺。"},"vi":{"q":"Ở Washington, khu vực nhường đường (Move Over zone) kéo dài bao xa phía trước và phía sau xe cấp cứu đang dừng?","o":["50 feet","200 feet","500 feet","Một dặm"],"h1":"Nó dài hơn 100 feet vài chiều dài xe.","h2":"Ở Washington, khu vực nhường đường bao gồm 200 feet phía trước và 200 feet phía sau xe cấp cứu hoặc xe công tác đang dừng.","p":"Đúng. 200 feet mỗi bên."},"tl":{"q":"Sa Washington, gaano kalayo bago at pagkatapos ng nakahintong emergency vehicle umaabot ang Move Over zone?","o":["50 feet","200 feet","500 feet","Isang milya"],"h1":"Ilang haba ng kotse ito na mas mahaba sa 100 feet.","h2":"Sa Washington, ang Move Over zone ay sumasaklaw sa 200 feet bago at 200 feet pagkatapos ng nakahintong emergency o work vehicle.","p":"Tama. 200 feet sa bawat panig."},"ar":{"q":"في Washington، إلى أي مسافة قبل سيارة الطوارئ المتوقفة وبعدها تمتد منطقة الابتعاد (Move Over zone)؟","o":["50 قدمًا","200 قدم","500 قدم","ميل واحد"],"h1":"هي أكثر من 100 قدم بطول بضع سيارات.","h2":"في Washington تشمل منطقة الابتعاد 200 قدم قبل سيارة الطوارئ أو سيارة العمل المتوقفة و200 قدم بعدها.","p":"صحيح. 200 قدم من كل جهة."},"ref":{"doc":"WA","page":null}},{"id":"wa-022","scope":"WA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Washington, at what blood alcohol level is a driver under 21 breaking the law?","o":["0.02 or more","0.05 or more","0.08 or more","0.10 or more"],"h1":"It is much lower than the adult limit of 0.08.","h2":"In Washington a driver under 21 breaks the law with a blood alcohol level of 0.02 or more.","p":"Correct. The limit under 21 is 0.02."},"es":{"q":"En Washington, ¿con qué nivel de alcohol en la sangre un conductor menor de 21 años infringe la ley?","o":["0.02 o más","0.05 o más","0.08 o más","0.10 o más"],"h1":"Es mucho más bajo que el límite para adultos, que es 0.08.","h2":"En Washington un conductor menor de 21 años infringe la ley con un nivel de alcohol en la sangre de 0.02 o más.","p":"Correcto. El límite para menores de 21 es 0.02."},"zh":{"q":"在 Washington，21 岁以下的驾驶人血液酒精浓度达到多少就算违法？","o":["0.02 或以上","0.05 或以上","0.08 或以上","0.10 或以上"],"h1":"它比成年人的上限 0.08 低很多。","h2":"在 Washington，21 岁以下的驾驶人血液酒精浓度达到 0.02 或以上就是违法。","p":"对。21 岁以下的上限是 0.02。"},"vi":{"q":"Ở Washington, người lái dưới 21 tuổi vi phạm luật khi nồng độ cồn trong máu ở mức nào?","o":["0.02 trở lên","0.05 trở lên","0.08 trở lên","0.10 trở lên"],"h1":"Nó thấp hơn nhiều so với giới hạn 0.08 của người lớn.","h2":"Ở Washington, người lái dưới 21 tuổi vi phạm luật khi nồng độ cồn trong máu từ 0.02 trở lên.","p":"Đúng. Giới hạn cho người dưới 21 tuổi là 0.02."},"tl":{"q":"Sa Washington, sa anong blood alcohol level lumalabag sa batas ang driver na wala pang 21?","o":["0.02 o higit pa","0.05 o higit pa","0.08 o higit pa","0.10 o higit pa"],"h1":"Mas mababa ito nang malaki kaysa sa 0.08 na limit para sa adult.","h2":"Sa Washington, ang driver na wala pang 21 ay lumalabag sa batas kapag ang blood alcohol level niya ay 0.02 o higit pa.","p":"Tama. Ang limit para sa wala pang 21 ay 0.02."},"ar":{"q":"في Washington، عند أي نسبة كحول في الدم يخالف السائق تحت 21 سنة القانون؟","o":["0.02 أو أكثر","0.05 أو أكثر","0.08 أو أكثر","0.10 أو أكثر"],"h1":"هي أقل بكثير من حد البالغين وهو 0.08.","h2":"في Washington يخالف السائق تحت 21 سنة القانون إذا كانت نسبة الكحول في دمه 0.02 أو أكثر.","p":"صحيح. الحد تحت 21 سنة هو 0.02."},"ref":{"doc":"WA","page":"§1.15"}},{"id":"wa-023","scope":"WA","cat":"signals","sign":null,"c":2,"en":{"q":"In Washington, after a full stop at a red light, when may you turn left on red if no sign forbids it?","o":["Never","Only from a one-way street onto a two-way street","From a one-way or two-way street onto a one-way street going left","From any street onto any street"],"h1":"The street you turn into must carry traffic in only one direction, the way you are turning.","h2":"In Washington, after stopping and yielding, you may turn left on red from a one-way or two-way street onto a one-way street that carries traffic to the left, unless a sign forbids it.","p":"Right. Only onto a one-way street."},"es":{"q":"En Washington, después de detenerse por completo en un semáforo en rojo, ¿cuándo puede dar vuelta a la izquierda en rojo si ningún letrero lo prohíbe?","o":["Nunca","Solo de una calle de un sentido a una calle de doble sentido","De una calle de un sentido o de doble sentido a una calle de un sentido que va hacia la izquierda","De cualquier calle a cualquier calle"],"h1":"La calle a la que entra debe tener tráfico en un solo sentido, hacia donde usted da la vuelta.","h2":"En Washington, después de detenerse y ceder el paso, usted puede dar vuelta a la izquierda en rojo de una calle de un sentido o de doble sentido a una calle de un sentido con tráfico hacia la izquierda, a menos que un letrero lo prohíba.","p":"Correcto. Solo hacia una calle de un sentido."},"zh":{"q":"在 Washington，在红灯前完全停车以后，如果没有标志禁止，什么时候可以红灯左转？","o":["永远不可以","只有从单行道转进双向道","从单行道或双向道转进向左行驶的单行道","从任何街道转进任何街道"],"h1":"你转进去的街道必须只有一个行驶方向，就是你转弯的方向。","h2":"在 Washington，停车并让行以后，你可以在红灯时从单行道或双向道左转进入向左行驶的单行道，除非有标志禁止。","p":"对。只能转进单行道。"},"vi":{"q":"Ở Washington, sau khi dừng hẳn ở đèn đỏ, khi nào bạn được rẽ trái lúc đèn đỏ nếu không có biển cấm?","o":["Không bao giờ","Chỉ từ đường một chiều vào đường hai chiều","Từ đường một chiều hoặc hai chiều vào đường một chiều chạy về bên trái","Từ bất kỳ đường nào vào bất kỳ đường nào"],"h1":"Con đường bạn rẽ vào phải chỉ có xe chạy một chiều, theo hướng bạn rẽ.","h2":"Ở Washington, sau khi dừng lại và nhường đường, bạn được rẽ trái lúc đèn đỏ từ đường một chiều hoặc hai chiều vào đường một chiều có xe chạy về bên trái, trừ khi có biển cấm.","p":"Đúng. Chỉ rẽ vào đường một chiều."},"tl":{"q":"Sa Washington, pagkatapos ng full stop sa red light, kailan ka puwedeng kumaliwa sa red kung walang karatulang nagbabawal?","o":["Hindi kailanman","Mula sa one-way street papunta sa two-way street lamang","Mula sa one-way o two-way street papunta sa one-way street na papakaliwa ang daloy","Mula sa kahit anong kalye papunta sa kahit anong kalye"],"h1":"Ang kalyeng papasukan mo ay dapat may trapiko sa iisang direksyon lamang, ang direksyon ng liko mo.","h2":"Sa Washington, pagkatapos huminto at magbigay-daan, puwede kang kumaliwa sa red mula sa one-way o two-way street papunta sa one-way street na papakaliwa ang daloy ng trapiko, maliban kung may karatulang nagbabawal.","p":"Tama. Papunta lamang sa one-way street."},"ar":{"q":"في Washington، بعد التوقف الكامل عند إشارة حمراء، متى يجوز لك الانعطاف يسارًا والإشارة حمراء إذا لم تمنعه لافتة؟","o":["أبدًا","فقط من شارع باتجاه واحد إلى شارع باتجاهين","من شارع باتجاه واحد أو باتجاهين إلى شارع باتجاه واحد يسير نحو اليسار","من أي شارع إلى أي شارع"],"h1":"الشارع الذي تنعطف إليه يجب أن يكون السير فيه باتجاه واحد فقط، وهو اتجاه انعطافك.","h2":"في Washington، بعد التوقف وإعطاء الأولوية، يجوز لك الانعطاف يسارًا والإشارة حمراء من شارع باتجاه واحد أو باتجاهين إلى شارع باتجاه واحد يسير نحو اليسار، إلا إذا منعته لافتة.","p":"صحيح. فقط إلى شارع باتجاه واحد."},"ref":{"doc":"WA","page":"§4.11"}},{"id":"wa-024","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, what is the minimum liability insurance you must have?","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $10,000","$10,000 / $20,000 / $10,000"],"h1":"Injury to one person is covered for twenty-five thousand dollars.","h2":"In Washington, the minimum is $25,000 for one person hurt or killed, $50,000 for two or more people, and $10,000 for damage to property.","p":"Right. Washington requires at least $25,000, $50,000 and $10,000 of coverage."},"es":{"q":"En Washington, ¿cuál es el seguro de responsabilidad civil mínimo que debe tener?","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $10,000","$10,000 / $20,000 / $10,000"],"h1":"Las lesiones de una persona están cubiertas por veinticinco mil dólares.","h2":"En Washington, el mínimo es $25,000 por una persona herida o muerta, $50,000 por dos o más personas y $10,000 por daños a la propiedad.","p":"Correcto. Washington exige al menos $25,000, $50,000 y $10,000 de cobertura."},"zh":{"q":"在 Washington，你必须有的最低责任保险是多少？","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $10,000","$10,000 / $20,000 / $10,000"],"h1":"一个人受伤的保额是两万五千美元。","h2":"在 Washington，最低保额是：一个人受伤或死亡 $25,000，两个人或更多人 $50,000，财产损失 $10,000。","p":"对。Washington 要求至少 $25,000、$50,000 和 $10,000 的保额。"},"vi":{"q":"Ở Washington, bảo hiểm trách nhiệm tối thiểu bạn phải có là bao nhiêu?","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $10,000","$10,000 / $20,000 / $10,000"],"h1":"Thương tích của một người được bảo hiểm hai mươi lăm nghìn đô la.","h2":"Ở Washington, mức tối thiểu là $25,000 cho một người bị thương hoặc tử vong, $50,000 cho hai người trở lên, và $10,000 cho thiệt hại tài sản.","p":"Đúng. Washington yêu cầu bảo hiểm ít nhất $25,000, $50,000 và $10,000."},"tl":{"q":"Sa Washington, ano ang pinakamababang liability insurance na dapat mayroon ka?","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $10,000","$10,000 / $20,000 / $10,000"],"h1":"Ang pinsala sa isang tao ay sakop ng dalawampu't limang libong dolyar.","h2":"Sa Washington, ang pinakamababa ay $25,000 para sa isang taong nasaktan o namatay, $50,000 para sa dalawa o higit pang tao, at $10,000 para sa sira sa ari-arian.","p":"Tama. Hinihingi ng Washington ang hindi bababa sa $25,000, $50,000 at $10,000 na coverage."},"ar":{"q":"في Washington، ما الحد الأدنى من تأمين المسؤولية الذي يجب أن يكون لديك؟","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $10,000","$10,000 / $20,000 / $10,000"],"h1":"إصابة شخص واحد مغطاة بخمسة وعشرين ألف دولار.","h2":"في Washington، الحد الأدنى هو $25,000 لشخص واحد مصاب أو متوفى، و$50,000 لشخصين أو أكثر، و$10,000 لأضرار الممتلكات.","p":"صحيح. تشترط Washington تغطية لا تقل عن $25,000 و$50,000 و$10,000."},"ref":{"doc":"WA","page":"§2.3"}},{"id":"wa-025","scope":"WA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Washington, a driver 21 or older is considered under the influence of cannabis at what level of active THC in the blood?","o":["5 nanograms per milliliter or more","Any amount above zero","20 nanograms per milliliter or more","There is no THC limit"],"h1":"The number is the same as the fingers on one hand.","h2":"In Washington, a driver 21 or older with 5 nanograms or more of active THC per milliliter of blood is considered to be driving under the influence.","p":"Right. For adults, the THC limit is 5 nanograms per milliliter."},"es":{"q":"En Washington, ¿con qué nivel de THC activo en la sangre se considera que un conductor de 21 años o más maneja bajo la influencia del cannabis?","o":["5 nanogramos por mililitro o más","Cualquier cantidad mayor que cero","20 nanogramos por mililitro o más","No hay límite de THC"],"h1":"El número es igual a los dedos de una mano.","h2":"En Washington, un conductor de 21 años o más con 5 nanogramos o más de THC activo por mililitro de sangre se considera que maneja bajo la influencia.","p":"Correcto. Para los adultos, el límite de THC es de 5 nanogramos por mililitro."},"zh":{"q":"在 Washington，21 岁或以上的司机血液中活性 THC 达到多少时，被认为受大麻影响驾驶？","o":["每毫升 5 纳克或更多","任何大于零的量","每毫升 20 纳克或更多","THC 没有限制"],"h1":"这个数字和一只手的手指数一样。","h2":"在 Washington，21 岁或以上的司机，如果每毫升血液中有 5 纳克或更多的活性 THC，就被认为是受影响驾驶。","p":"对。成年人的 THC 限制是每毫升 5 纳克。"},"vi":{"q":"Ở Washington, tài xế từ 21 tuổi trở lên bị xem là lái xe dưới ảnh hưởng của cần sa khi lượng THC hoạt tính trong máu ở mức nào?","o":["5 nanogram mỗi mililít trở lên","Bất kỳ lượng nào lớn hơn không","20 nanogram mỗi mililít trở lên","Không có giới hạn THC"],"h1":"Con số này bằng số ngón tay trên một bàn tay.","h2":"Ở Washington, tài xế từ 21 tuổi trở lên có 5 nanogram THC hoạt tính trở lên trong mỗi mililít máu bị xem là lái xe dưới ảnh hưởng.","p":"Đúng. Với người lớn, giới hạn THC là 5 nanogram mỗi mililít."},"tl":{"q":"Sa Washington, ang driver na 21 taong gulang pataas ay itinuturing na under the influence ng cannabis sa anong antas ng active THC sa dugo?","o":["5 nanograms bawat milliliter o higit pa","Kahit anong dami na higit sa zero","20 nanograms bawat milliliter o higit pa","Walang limit sa THC"],"h1":"Ang numero ay kapareho ng bilang ng daliri sa isang kamay.","h2":"Sa Washington, ang driver na 21 taong gulang pataas na may 5 nanograms o higit pa ng active THC bawat milliliter ng dugo ay itinuturing na nagmamaneho nang under the influence.","p":"Tama. Para sa mga adult, ang limit ng THC ay 5 nanograms bawat milliliter."},"ar":{"q":"في Washington، عند أي مستوى من THC النشط في الدم يُعتبر السائق الذي عمره 21 عامًا أو أكثر تحت تأثير القنب؟","o":["5 نانوغرامات لكل مليلتر أو أكثر","أي كمية أكبر من صفر","20 نانوغرامًا لكل مليلتر أو أكثر","لا يوجد حد لـ THC"],"h1":"الرقم يساوي عدد أصابع اليد الواحدة.","h2":"في Washington، السائق الذي عمره 21 عامًا أو أكثر ولديه 5 نانوغرامات أو أكثر من THC النشط لكل مليلتر من الدم يُعتبر أنه يقود تحت التأثير.","p":"صحيح. بالنسبة للبالغين، حد THC هو 5 نانوغرامات لكل مليلتر."},"ref":{"doc":"WA","page":"§1.15"}},{"id":"wa-026","scope":"WA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Washington, until what age must a child ride in a rear-facing car seat?","o":["Until age 1","Until age 2","Until age 4","Until age 6"],"h1":"It is later than a baby's first birthday.","h2":"In Washington, children must ride in a rear-facing car seat until they are 2 years old.","p":"Right. Children ride rear-facing until age 2."},"es":{"q":"En Washington, ¿hasta qué edad debe un niño viajar en un asiento de seguridad orientado hacia atrás?","o":["Hasta 1 año","Hasta 2 años","Hasta 4 años","Hasta 6 años"],"h1":"Es después del primer cumpleaños del bebé.","h2":"En Washington, los niños deben viajar en un asiento de seguridad orientado hacia atrás hasta que cumplan 2 años.","p":"Correcto. Los niños viajan mirando hacia atrás hasta los 2 años."},"zh":{"q":"在 Washington，孩子必须坐后向安全座椅到几岁？","o":["到 1 岁","到 2 岁","到 4 岁","到 6 岁"],"h1":"比宝宝的第一个生日更晚。","h2":"在 Washington，孩子必须坐后向安全座椅，直到满 2 岁。","p":"对。孩子坐后向座椅到 2 岁。"},"vi":{"q":"Ở Washington, trẻ em phải ngồi ghế an toàn quay mặt về phía sau cho đến bao nhiêu tuổi?","o":["Đến 1 tuổi","Đến 2 tuổi","Đến 4 tuổi","Đến 6 tuổi"],"h1":"Muộn hơn sinh nhật đầu tiên của em bé.","h2":"Ở Washington, trẻ em phải ngồi ghế an toàn quay mặt về phía sau cho đến khi được 2 tuổi.","p":"Đúng. Trẻ em ngồi quay mặt về phía sau đến 2 tuổi."},"tl":{"q":"Sa Washington, hanggang anong edad dapat nakaupo ang bata sa rear-facing car seat?","o":["Hanggang edad 1","Hanggang edad 2","Hanggang edad 4","Hanggang edad 6"],"h1":"Mas huli ito kaysa sa unang kaarawan ng sanggol.","h2":"Sa Washington, ang mga bata ay dapat nakaupo sa rear-facing car seat hanggang sila ay 2 taong gulang.","p":"Tama. Nakaharap sa likod ang mga bata hanggang edad 2."},"ar":{"q":"في Washington، حتى أي عمر يجب أن يجلس الطفل في مقعد سيارة مواجه للخلف؟","o":["حتى عمر سنة واحدة (1)","حتى عمر سنتين (2)","حتى عمر 4 سنوات","حتى عمر 6 سنوات"],"h1":"إنه بعد عيد الميلاد الأول للطفل.","h2":"في Washington، يجب أن يجلس الأطفال في مقعد سيارة مواجه للخلف حتى يبلغوا عمر سنتين (2).","p":"صحيح. يجلس الأطفال مواجهين للخلف حتى عمر سنتين (2)."},"ref":{"doc":"WA","page":"§2.6"}},{"id":"wa-027","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, if no police officer files a report after your crash, within how many days must you file a collision report?","o":["1 day","10 days","30 days","4 days"],"h1":"It is less than one week.","h2":"In Washington, if a police officer does not file a report, you must file a collision report within 4 days of the crash.","p":"Right. You have 4 days to file the collision report."},"es":{"q":"En Washington, si ningún policía hace un informe después de su choque, ¿en cuántos días debe usted presentar un informe de colisión?","o":["1 día","10 días","30 días","4 días"],"h1":"Es menos de una semana.","h2":"En Washington, si un policía no hace el informe, usted debe presentar un informe de colisión dentro de los 4 días después del choque.","p":"Correcto. Tiene 4 días para presentar el informe de colisión."},"zh":{"q":"在 Washington，如果车祸后没有警察写报告，你必须在几天内提交事故报告？","o":["1 天","10 天","30 天","4 天"],"h1":"不到一个星期。","h2":"在 Washington，如果警察没有写报告，你必须在车祸后 4 天内提交事故报告。","p":"对。你有 4 天时间提交事故报告。"},"vi":{"q":"Ở Washington, nếu không có cảnh sát làm biên bản sau vụ tai nạn của bạn, bạn phải nộp báo cáo va chạm trong vòng bao nhiêu ngày?","o":["1 ngày","10 ngày","30 ngày","4 ngày"],"h1":"Ít hơn một tuần.","h2":"Ở Washington, nếu cảnh sát không làm biên bản, bạn phải nộp báo cáo va chạm trong vòng 4 ngày sau vụ tai nạn.","p":"Đúng. Bạn có 4 ngày để nộp báo cáo va chạm."},"tl":{"q":"Sa Washington, kung walang pulis na gumawa ng report pagkatapos ng banggaan mo, sa loob ng ilang araw dapat kang mag-file ng collision report?","o":["1 araw","10 araw","30 araw","4 na araw"],"h1":"Mas maikli ito sa isang linggo.","h2":"Sa Washington, kung walang pulis na gumawa ng report, dapat kang mag-file ng collision report sa loob ng 4 na araw pagkatapos ng banggaan.","p":"Tama. May 4 na araw ka para mag-file ng collision report."},"ar":{"q":"في Washington، إذا لم يكتب أي شرطي تقريرًا بعد حادثك، خلال كم يومًا يجب أن تقدم تقرير حادث؟","o":["يوم واحد (1)","10 أيام","30 يومًا","4 أيام"],"h1":"إنها أقل من أسبوع.","h2":"في Washington، إذا لم يكتب شرطي التقرير، يجب أن تقدم تقرير حادث خلال 4 أيام من الحادث.","p":"صحيح. لديك 4 أيام لتقديم تقرير الحادث."},"ref":{"doc":"WA","page":"§5.9"}},{"id":"wa-028","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, how early can you renew your driver license before it expires?","o":["Up to 30 days early","Up to 90 days early","Up to one year early","Only after it expires"],"h1":"You can renew quite a while before the date on your card.","h2":"In Washington, you can renew your driver license up to one year before it expires.","p":"Right. You can renew up to one year early."},"es":{"q":"En Washington, ¿con cuánta anticipación puede renovar su licencia de conducir antes de que venza?","o":["Hasta 30 días antes","Hasta 90 días antes","Hasta un año antes","Solo después de que venza"],"h1":"Puede renovarla bastante tiempo antes de la fecha de su tarjeta.","h2":"En Washington, usted puede renovar su licencia de conducir hasta un año antes de que venza.","p":"Correcto. Puede renovarla hasta un año antes."},"zh":{"q":"在 Washington，驾照到期前多久可以更新？","o":["最多提前 30 天","最多提前 90 天","最多提前一年","只能在到期后"],"h1":"你可以在卡上日期之前很久就更新。","h2":"在 Washington，你可以在驾照到期前最多一年更新驾照。","p":"对。你最多可以提前一年更新。"},"vi":{"q":"Ở Washington, bạn có thể gia hạn bằng lái sớm bao lâu trước khi bằng hết hạn?","o":["Sớm tối đa 30 ngày","Sớm tối đa 90 ngày","Sớm tối đa một năm","Chỉ sau khi hết hạn"],"h1":"Bạn có thể gia hạn khá lâu trước ngày ghi trên thẻ.","h2":"Ở Washington, bạn có thể gia hạn bằng lái tối đa một năm trước khi bằng hết hạn.","p":"Đúng. Bạn có thể gia hạn sớm tối đa một năm."},"tl":{"q":"Sa Washington, gaano kaaga mo puwedeng i-renew ang driver license mo bago ito mag-expire?","o":["Hanggang 30 araw na mas maaga","Hanggang 90 araw na mas maaga","Hanggang isang taon na mas maaga","Pagkatapos lang itong mag-expire"],"h1":"Puwede kang mag-renew nang matagal bago ang petsa sa card mo.","h2":"Sa Washington, puwede mong i-renew ang driver license mo hanggang isang taon bago ito mag-expire.","p":"Tama. Puwede kang mag-renew hanggang isang taon na mas maaga."},"ar":{"q":"في Washington، كم من الوقت قبل انتهاء رخصة القيادة يمكنك تجديدها؟","o":["حتى 30 يومًا قبل الانتهاء","حتى 90 يومًا قبل الانتهاء","حتى سنة واحدة قبل الانتهاء","فقط بعد انتهائها"],"h1":"يمكنك التجديد قبل التاريخ المكتوب على بطاقتك بوقت طويل.","h2":"في Washington، يمكنك تجديد رخصة القيادة حتى سنة واحدة قبل انتهائها.","p":"صحيح. يمكنك التجديد حتى سنة واحدة مبكرًا."},"ref":{"doc":"WA","page":"§1.15"}},{"id":"wa-029","scope":"WA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Washington, you are using high beams. How close can an oncoming vehicle get before you must switch to low beams?","o":["500 feet","100 feet","1,000 feet","50 feet"],"h1":"It is more than one and a half football fields.","h2":"In Washington, you must switch to low beams when you are within 500 feet of an oncoming vehicle.","p":"Right. Dim your lights within 500 feet of an oncoming vehicle."},"es":{"q":"En Washington, usted tiene las luces altas encendidas. ¿A qué distancia puede acercarse un vehículo que viene de frente antes de que usted cambie a luces bajas?","o":["500 pies","100 pies","1,000 pies","50 pies"],"h1":"Es más que una cancha y media de fútbol americano.","h2":"En Washington, usted debe cambiar a luces bajas cuando está a 500 pies o menos de un vehículo que viene de frente.","p":"Correcto. Baje las luces a 500 pies de un vehículo que viene de frente."},"zh":{"q":"在 Washington，你正在使用远光灯。对面来车离你多近时，你必须换成近光灯？","o":["500 英尺","100 英尺","1,000 英尺","50 英尺"],"h1":"这比一个半足球场还长。","h2":"在 Washington，当你离对面来车 500 英尺以内时，你必须换成近光灯。","p":"对。离对面来车 500 英尺以内时要把灯调暗。"},"vi":{"q":"Ở Washington, bạn đang bật đèn pha (đèn chiếu xa). Xe chạy ngược chiều đến gần bao nhiêu thì bạn phải chuyển sang đèn cos (đèn chiếu gần)?","o":["500 feet","100 feet","1,000 feet","50 feet"],"h1":"Nó dài hơn một sân bóng bầu dục rưỡi.","h2":"Ở Washington, bạn phải chuyển sang đèn cos khi bạn ở trong vòng 500 feet của xe chạy ngược chiều.","p":"Đúng. Hãy giảm đèn khi xe ngược chiều ở trong vòng 500 feet."},"tl":{"q":"Sa Washington, naka-high beam ka. Gaano kalapit ang paparating na sasakyan bago ka dapat lumipat sa low beam?","o":["500 feet","100 feet","1,000 feet","50 feet"],"h1":"Mas mahaba ito sa isa't kalahating football field.","h2":"Sa Washington, dapat kang lumipat sa low beam kapag nasa loob ka ng 500 feet ng paparating na sasakyan.","p":"Tama. Hinaan ang ilaw mo kapag nasa loob ng 500 feet ang paparating na sasakyan."},"ar":{"q":"في Washington، أنت تستخدم الأضواء العالية. كم يمكن أن تقترب سيارة قادمة من الاتجاه المقابل قبل أن يجب عليك التحويل إلى الأضواء المنخفضة؟","o":["500 قدم","100 قدم","1,000 قدم","50 قدمًا"],"h1":"هي أكثر من طول ملعب كرة قدم ونصف.","h2":"في Washington، يجب أن تحول إلى الأضواء المنخفضة عندما تكون على بعد 500 قدم أو أقل من سيارة قادمة من الاتجاه المقابل.","p":"صحيح. خفّض أضواءك على بعد 500 قدم من السيارة القادمة."},"ref":{"doc":"WA","page":"§2.5"}},{"id":"wa-030","scope":"WA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Washington, when you pass a bicyclist, how much space must you leave between the bicyclist and your vehicle?","o":["At least 1 foot","At least 2 feet","At least 5 feet","At least 3 feet"],"h1":"Measure from the widest part of your vehicle, such as the mirror.","h2":"In Washington, you must leave at least 3 feet between the bicyclist and the widest part of your vehicle when you pass.","p":"Right. Leave at least 3 feet when you pass a bicyclist."},"es":{"q":"En Washington, cuando usted rebasa a un ciclista, ¿cuánto espacio debe dejar entre el ciclista y su vehículo?","o":["Por lo menos 1 pie","Por lo menos 2 pies","Por lo menos 5 pies","Por lo menos 3 pies"],"h1":"Mida desde la parte más ancha de su vehículo, como el espejo.","h2":"En Washington, usted debe dejar por lo menos 3 pies entre el ciclista y la parte más ancha de su vehículo cuando lo rebasa.","p":"Correcto. Deje por lo menos 3 pies al rebasar a un ciclista."},"zh":{"q":"在 Washington，当你超过骑自行车的人时，你必须在自行车和你的车之间留出多少空间？","o":["至少 1 英尺","至少 2 英尺","至少 5 英尺","至少 3 英尺"],"h1":"从你的车最宽的部分量起，比如后视镜。","h2":"在 Washington，超过骑自行车的人时，你必须在骑车人和你的车最宽的部分之间留出至少 3 英尺。","p":"对。超过骑自行车的人时，至少留出 3 英尺。"},"vi":{"q":"Ở Washington, khi bạn vượt người đi xe đạp, bạn phải chừa bao nhiêu khoảng cách giữa người đi xe đạp và xe của bạn?","o":["Ít nhất 1 foot","Ít nhất 2 feet","Ít nhất 5 feet","Ít nhất 3 feet"],"h1":"Đo từ phần rộng nhất của xe bạn, ví dụ như gương chiếu hậu.","h2":"Ở Washington, khi vượt, bạn phải chừa ít nhất 3 feet giữa người đi xe đạp và phần rộng nhất của xe bạn.","p":"Đúng. Hãy chừa ít nhất 3 feet khi vượt người đi xe đạp."},"tl":{"q":"Sa Washington, kapag nag-overtake ka sa nagbibisikleta, gaano kalaking espasyo ang dapat mong iwan sa pagitan ng nagbibisikleta at ng sasakyan mo?","o":["Hindi bababa sa 1 foot","Hindi bababa sa 2 feet","Hindi bababa sa 5 feet","Hindi bababa sa 3 feet"],"h1":"Sukatin mula sa pinakamalapad na bahagi ng sasakyan mo, gaya ng salamin.","h2":"Sa Washington, kapag nag-overtake ka, dapat kang mag-iwan ng hindi bababa sa 3 feet sa pagitan ng nagbibisikleta at ng pinakamalapad na bahagi ng sasakyan mo.","p":"Tama. Mag-iwan ng hindi bababa sa 3 feet kapag nag-overtake ka sa nagbibisikleta."},"ar":{"q":"في Washington، عندما تتجاوز راكب دراجة، ما المسافة التي يجب أن تتركها بين راكب الدراجة وسيارتك؟","o":["قدم واحدة (1) على الأقل","قدمان (2) على الأقل","5 أقدام على الأقل","3 أقدام على الأقل"],"h1":"قِس من أعرض جزء في سيارتك، مثل المرآة.","h2":"في Washington، عندما تتجاوز يجب أن تترك 3 أقدام على الأقل بين راكب الدراجة وأعرض جزء في سيارتك.","p":"صحيح. اترك 3 أقدام على الأقل عندما تتجاوز راكب دراجة."},"ref":{"doc":"WA","page":"§4.6"}},{"id":"wa-031","scope":"WA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Washington, you may not park within how many feet of a railroad crossing?","o":["15 feet","50 feet","100 feet","5 feet"],"h1":"It is more than the distance for a fire hydrant.","h2":"In Washington, you may not park within 50 feet of a railroad crossing.","p":"Right. Keep at least 50 feet from a railroad crossing when you park."},"es":{"q":"En Washington, ¿a cuántos pies de un cruce de ferrocarril no puede estacionarse?","o":["15 pies","50 pies","100 pies","5 pies"],"h1":"Es más que la distancia de un hidrante.","h2":"En Washington, usted no puede estacionarse a menos de 50 pies de un cruce de ferrocarril.","p":"Correcto. Al estacionarse, quédese por lo menos a 50 pies de un cruce de ferrocarril."},"zh":{"q":"在 Washington，你不可以在铁路道口多少英尺以内停车？","o":["15 英尺","50 英尺","100 英尺","5 英尺"],"h1":"这比消防栓的距离还远。","h2":"在 Washington，你不可以在铁路道口 50 英尺以内停车。","p":"对。停车时离铁路道口至少 50 英尺。"},"vi":{"q":"Ở Washington, bạn không được đậu xe trong vòng bao nhiêu feet tính từ chỗ giao nhau với đường sắt?","o":["15 feet","50 feet","100 feet","5 feet"],"h1":"Nó xa hơn khoảng cách với trụ cứu hỏa.","h2":"Ở Washington, bạn không được đậu xe trong vòng 50 feet tính từ chỗ giao nhau với đường sắt.","p":"Đúng. Khi đậu xe, hãy cách chỗ giao nhau với đường sắt ít nhất 50 feet."},"tl":{"q":"Sa Washington, hindi ka puwedeng mag-park sa loob ng ilang feet mula sa railroad crossing?","o":["15 feet","50 feet","100 feet","5 feet"],"h1":"Mas malayo ito sa distansya para sa fire hydrant.","h2":"Sa Washington, hindi ka puwedeng mag-park sa loob ng 50 feet mula sa railroad crossing.","p":"Tama. Lumayo nang hindi bababa sa 50 feet mula sa railroad crossing kapag nagpa-park ka."},"ar":{"q":"في Washington، لا يجوز لك الوقوف (الركن) على بعد كم قدمًا من تقاطع السكة الحديدية؟","o":["15 قدمًا","50 قدمًا","100 قدم","5 أقدام"],"h1":"هي أكثر من المسافة المطلوبة عن صنبور إطفاء الحريق.","h2":"في Washington، لا يجوز لك الوقوف على بعد أقل من 50 قدمًا من تقاطع السكة الحديدية.","p":"صحيح. ابتعد 50 قدمًا على الأقل عن تقاطع السكة الحديدية عندما تقف."},"ref":{"doc":"WA","page":"§4.18"}},{"id":"wi-001","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, how many questions are on the knowledge test?","o":["20 questions","25 questions","35 questions","50 questions"],"h1":"It is half of one hundred.","h2":"The Wisconsin knowledge test has 50 questions.","p":"Right. The Wisconsin test has 50 questions."},"es":{"q":"En Wisconsin, ¿cuántas preguntas tiene el examen de conocimientos?","o":["20 preguntas","25 preguntas","35 preguntas","50 preguntas"],"h1":"Es la mitad de cien.","h2":"El examen de conocimientos de Wisconsin tiene 50 preguntas.","p":"Correcto. El examen de Wisconsin tiene 50 preguntas."},"zh":{"q":"在 Wisconsin，知识考试有多少道题？","o":["20 道题","25 道题","35 道题","50 道题"],"h1":"它是一百的一半。","h2":"Wisconsin 的知识考试有 50 道题。","p":"对。Wisconsin 的考试有 50 道题。"},"vi":{"q":"Ở Wisconsin, bài thi kiến thức có bao nhiêu câu hỏi?","o":["20 câu hỏi","25 câu hỏi","35 câu hỏi","50 câu hỏi"],"h1":"Đó là một nửa của một trăm.","h2":"Bài thi kiến thức ở Wisconsin có 50 câu hỏi.","p":"Đúng. Bài thi ở Wisconsin có 50 câu hỏi."},"tl":{"q":"Sa Wisconsin, ilang tanong ang nasa knowledge test?","o":["20 tanong","25 tanong","35 tanong","50 tanong"],"h1":"Ito ay kalahati ng isang daan.","h2":"Ang knowledge test ng Wisconsin ay may 50 tanong.","p":"Tama. Ang test sa Wisconsin ay may 50 tanong."},"ar":{"q":"في Wisconsin، كم سؤالًا في اختبار المعرفة؟","o":["20 سؤالًا","25 سؤالًا","35 سؤالًا","50 سؤالًا"],"h1":"هو نصف المئة.","h2":"اختبار المعرفة في Wisconsin فيه 50 سؤالًا.","p":"صحيح. اختبار Wisconsin فيه 50 سؤالًا."},"ref":{"doc":"WI","page":1}},{"id":"wi-002","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, how many knowledge test questions must you answer correctly to pass?","o":["40","30","35","45"],"h1":"You need 80 percent of the 50 questions.","h2":"You must answer at least 40 of the 50 Wisconsin knowledge test questions correctly, which is 80 percent.","p":"Right. You need 40 correct answers."},"es":{"q":"En Wisconsin, ¿cuántas preguntas del examen de conocimientos debe contestar bien para aprobar?","o":["40","30","35","45"],"h1":"Necesita el 80 por ciento de las 50 preguntas.","h2":"Usted debe contestar bien por lo menos 40 de las 50 preguntas del examen de conocimientos de Wisconsin, que es el 80 por ciento.","p":"Correcto. Necesita 40 respuestas correctas."},"zh":{"q":"在 Wisconsin，知识考试必须答对多少道题才能通过？","o":["40","30","35","45"],"h1":"你需要答对 50 道题中的 80%。","h2":"Wisconsin 知识考试的 50 道题中，你必须至少答对 40 道，也就是 80%。","p":"对。你需要答对 40 道题。"},"vi":{"q":"Ở Wisconsin, bạn phải trả lời đúng bao nhiêu câu trong bài thi kiến thức để đậu?","o":["40","30","35","45"],"h1":"Bạn cần đúng 80% của 50 câu hỏi.","h2":"Bạn phải trả lời đúng ít nhất 40 trong 50 câu hỏi của bài thi kiến thức ở Wisconsin, tức là 80%.","p":"Đúng. Bạn cần 40 câu trả lời đúng."},"tl":{"q":"Sa Wisconsin, ilang tanong sa knowledge test ang dapat mong masagot nang tama para pumasa?","o":["40","30","35","45"],"h1":"Kailangan mo ang 80% ng 50 tanong.","h2":"Dapat mong masagot nang tama ang hindi bababa sa 40 sa 50 tanong ng knowledge test ng Wisconsin, o 80%.","p":"Tama. Kailangan mo ng 40 tamang sagot."},"ar":{"q":"في Wisconsin، كم سؤالًا في اختبار المعرفة يجب أن تجيب عنه إجابة صحيحة لتنجح؟","o":["40","30","35","45"],"h1":"تحتاج إلى 80% من الأسئلة الـ 50.","h2":"يجب أن تجيب إجابة صحيحة عن 40 سؤالًا على الأقل من 50 سؤالًا في اختبار المعرفة في Wisconsin، أي 80%.","p":"صحيح. تحتاج إلى 40 إجابة صحيحة."},"ref":{"doc":"WI","page":1}},{"id":"wi-003","scope":"WI","cat":"signs","sign":null,"c":2,"en":{"q":"In Wisconsin, how many questions are on the separate road signs test?","o":["5 questions","10 questions","15 questions","25 questions"],"h1":"It is between 10 and 20.","h2":"Wisconsin gives a separate road signs test with 15 questions, and you must answer at least 12 correctly.","p":"Right. The signs test has 15 questions."},"es":{"q":"En Wisconsin, ¿cuántas preguntas tiene el examen separado de señales de tránsito?","o":["5 preguntas","10 preguntas","15 preguntas","25 preguntas"],"h1":"Está entre 10 y 20.","h2":"Wisconsin hace un examen separado de señales de tránsito con 15 preguntas, y usted debe contestar bien por lo menos 12.","p":"Correcto. El examen de señales tiene 15 preguntas."},"zh":{"q":"在 Wisconsin，单独的交通标志考试有多少道题？","o":["5 道题","10 道题","15 道题","25 道题"],"h1":"它在 10 和 20 之间。","h2":"Wisconsin 有单独的交通标志考试，共 15 道题，你必须至少答对 12 道。","p":"对。标志考试有 15 道题。"},"vi":{"q":"Ở Wisconsin, bài thi biển báo đường bộ riêng có bao nhiêu câu hỏi?","o":["5 câu hỏi","10 câu hỏi","15 câu hỏi","25 câu hỏi"],"h1":"Con số này nằm giữa 10 và 20.","h2":"Wisconsin có một bài thi biển báo đường bộ riêng với 15 câu hỏi, và bạn phải trả lời đúng ít nhất 12 câu.","p":"Đúng. Bài thi biển báo có 15 câu hỏi."},"tl":{"q":"Sa Wisconsin, ilang tanong ang nasa hiwalay na test tungkol sa mga karatula sa daan?","o":["5 tanong","10 tanong","15 tanong","25 tanong"],"h1":"Ito ay nasa pagitan ng 10 at 20.","h2":"May hiwalay na test ang Wisconsin tungkol sa mga karatula sa daan na may 15 tanong, at dapat mong masagot nang tama ang hindi bababa sa 12.","p":"Tama. Ang test sa karatula ay may 15 tanong."},"ar":{"q":"في Wisconsin، كم سؤالًا في اختبار إشارات الطريق المنفصل؟","o":["5 أسئلة","10 أسئلة","15 سؤالًا","25 سؤالًا"],"h1":"العدد بين 10 و 20.","h2":"في Wisconsin اختبار منفصل لإشارات الطريق فيه 15 سؤالًا، ويجب أن تجيب إجابة صحيحة عن 12 سؤالًا على الأقل.","p":"صحيح. اختبار الإشارات فيه 15 سؤالًا."},"ref":{"doc":"WI","page":1}},{"id":"wi-004","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, how many hours of driving practice does an applicant under 18 need before a probationary license?","o":["30 hours","50 hours","20 hours","100 hours"],"h1":"The number went up in 2021.","h2":"A Wisconsin applicant under 18 needs 50 hours of driving practice, 10 of them at night, before a probationary license.","p":"Right. Wisconsin requires 50 hours."},"es":{"q":"En Wisconsin, ¿cuántas horas de práctica de manejo necesita un solicitante menor de 18 años antes de la licencia probatoria?","o":["30 horas","50 horas","20 horas","100 horas"],"h1":"El número subió en 2021.","h2":"Un solicitante de Wisconsin menor de 18 años necesita 50 horas de práctica de manejo, 10 de ellas de noche, antes de la licencia probatoria.","p":"Correcto. Wisconsin exige 50 horas."},"zh":{"q":"在 Wisconsin，18 岁以下的申请人在拿试用驾照（probationary license）前需要练车多少小时？","o":["30 小时","50 小时","20 小时","100 小时"],"h1":"这个数字在 2021 年提高了。","h2":"在 Wisconsin，18 岁以下的申请人在拿试用驾照前需要练车 50 小时，其中 10 小时要在夜间。","p":"对。Wisconsin 要求 50 小时。"},"vi":{"q":"Ở Wisconsin, người nộp đơn dưới 18 tuổi cần bao nhiêu giờ tập lái trước khi có bằng lái tạm thời (probationary license)?","o":["30 giờ","50 giờ","20 giờ","100 giờ"],"h1":"Con số này đã tăng lên vào năm 2021.","h2":"Ở Wisconsin, người nộp đơn dưới 18 tuổi cần 50 giờ tập lái, trong đó 10 giờ vào ban đêm, trước khi có bằng lái tạm thời.","p":"Đúng. Wisconsin yêu cầu 50 giờ."},"tl":{"q":"Sa Wisconsin, ilang oras ng pagsasanay sa pagmamaneho ang kailangan ng aplikanteng wala pang 18 bago makakuha ng probationary license?","o":["30 oras","50 oras","20 oras","100 oras"],"h1":"Tumaas ang bilang na ito noong 2021.","h2":"Ang aplikante sa Wisconsin na wala pang 18 ay kailangan ng 50 oras ng pagsasanay sa pagmamaneho, 10 dito sa gabi, bago makakuha ng probationary license.","p":"Tama. 50 oras ang kailangan sa Wisconsin."},"ar":{"q":"في Wisconsin، كم ساعة من التدريب على القيادة يحتاج المتقدم الذي عمره أقل من 18 قبل رخصة القيادة التجريبية (probationary license)؟","o":["30 ساعة","50 ساعة","20 ساعة","100 ساعة"],"h1":"زاد هذا العدد في سنة 2021.","h2":"المتقدم في Wisconsin الذي عمره أقل من 18 يحتاج إلى 50 ساعة من التدريب على القيادة، منها 10 ساعات في الليل، قبل رخصة القيادة التجريبية.","p":"صحيح. Wisconsin تطلب 50 ساعة."},"ref":{"doc":"WI","page":6}},{"id":"wi-005","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, how many of the required practice hours must be at night?","o":["10 hours","5 hours","15 hours","25 hours"],"h1":"It is one fifth of 50.","h2":"At least 10 of the 50 practice hours required in Wisconsin must be driven at night.","p":"Right. Ten hours must be at night."},"es":{"q":"En Wisconsin, ¿cuántas de las horas de práctica obligatorias deben ser de noche?","o":["10 horas","5 horas","15 horas","25 horas"],"h1":"Es la quinta parte de 50.","h2":"Por lo menos 10 de las 50 horas de práctica que exige Wisconsin deben manejarse de noche.","p":"Correcto. Diez horas deben ser de noche."},"zh":{"q":"在 Wisconsin，规定的练车时间中有多少小时必须在夜间？","o":["10 小时","5 小时","15 小时","25 小时"],"h1":"它是 50 的五分之一。","h2":"在 Wisconsin 规定的 50 小时练车时间中，至少 10 小时必须在夜间开车。","p":"对。10 小时必须在夜间。"},"vi":{"q":"Ở Wisconsin, trong số giờ tập lái bắt buộc, bao nhiêu giờ phải lái vào ban đêm?","o":["10 giờ","5 giờ","15 giờ","25 giờ"],"h1":"Đó là một phần năm của 50.","h2":"Trong 50 giờ tập lái bắt buộc ở Wisconsin, ít nhất 10 giờ phải lái vào ban đêm.","p":"Đúng. Mười giờ phải lái vào ban đêm."},"tl":{"q":"Sa Wisconsin, ilan sa mga kailangang oras ng pagsasanay ang dapat sa gabi?","o":["10 oras","5 oras","15 oras","25 oras"],"h1":"Ito ay ikalimang bahagi ng 50.","h2":"Hindi bababa sa 10 sa 50 oras ng pagsasanay na kailangan sa Wisconsin ang dapat imaneho sa gabi.","p":"Tama. Sampung oras ang dapat sa gabi."},"ar":{"q":"في Wisconsin، كم ساعة من ساعات التدريب المطلوبة يجب أن تكون في الليل؟","o":["10 ساعات","5 ساعات","15 ساعة","25 ساعة"],"h1":"هي خُمس الـ 50.","h2":"يجب أن تكون 10 ساعات على الأقل من ساعات التدريب الـ 50 المطلوبة في Wisconsin قيادةً في الليل.","p":"صحيح. عشر ساعات يجب أن تكون في الليل."},"ref":{"doc":"WI","page":6}},{"id":"wi-006","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, how long must you hold an instruction permit, violation free, before a probationary license?","o":["1 month","3 months","12 months","6 months"],"h1":"It is half a year.","h2":"In Wisconsin you must hold an instruction permit for at least six months and be violation free for those six months before a probationary license.","p":"Right. Six months, with no violations."},"es":{"q":"En Wisconsin, ¿cuánto tiempo debe tener el permiso de aprendiz, sin infracciones, antes de la licencia probatoria?","o":["1 mes","3 meses","12 meses","6 meses"],"h1":"Es medio año.","h2":"En Wisconsin usted debe tener el permiso de aprendiz por lo menos seis meses y no tener infracciones en esos seis meses antes de la licencia probatoria.","p":"Correcto. Seis meses, sin infracciones."},"zh":{"q":"在 Wisconsin，拿试用驾照前，你必须持有学习驾照（instruction permit）多久，并且没有违规？","o":["1 个月","3 个月","12 个月","6 个月"],"h1":"它是半年。","h2":"在 Wisconsin，拿试用驾照前，你必须持有学习驾照至少六个月，而且这六个月内没有违规。","p":"对。六个月，没有违规。"},"vi":{"q":"Ở Wisconsin, bạn phải giữ giấy phép tập lái (instruction permit) bao lâu, không vi phạm, trước khi có bằng lái tạm thời?","o":["1 tháng","3 tháng","12 tháng","6 tháng"],"h1":"Đó là nửa năm.","h2":"Ở Wisconsin, bạn phải giữ giấy phép tập lái ít nhất sáu tháng và không có vi phạm nào trong sáu tháng đó trước khi có bằng lái tạm thời.","p":"Đúng. Sáu tháng, không vi phạm."},"tl":{"q":"Sa Wisconsin, gaano katagal mo dapat hawak ang instruction permit, nang walang paglabag, bago makakuha ng probationary license?","o":["1 buwan","3 buwan","12 buwan","6 na buwan"],"h1":"Ito ay kalahating taon.","h2":"Sa Wisconsin, dapat hawak mo ang instruction permit nang hindi bababa sa anim na buwan at walang paglabag sa anim na buwang iyon bago makakuha ng probationary license.","p":"Tama. Anim na buwan, walang paglabag."},"ar":{"q":"في Wisconsin، كم مدة يجب أن تحمل تصريح التعلم (instruction permit) بدون مخالفات قبل رخصة القيادة التجريبية؟","o":["شهر واحد","3 أشهر","12 شهرًا","6 أشهر"],"h1":"هي نصف سنة.","h2":"في Wisconsin يجب أن تحمل تصريح التعلم ستة أشهر على الأقل وأن تكون بدون مخالفات خلال هذه الأشهر الستة قبل رخصة القيادة التجريبية.","p":"صحيح. ستة أشهر بدون مخالفات."},"ref":{"doc":"WI","page":6}},{"id":"wi-007","scope":"WI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wisconsin, besides driver education, what else does a teen need to apply for a probationary license?","o":["A car in their own name","A part-time job","An adult sponsor","A high school diploma"],"h1":"An adult must take responsibility for the teen driver.","h2":"A Wisconsin teen applying for a probationary license must be at least 16, finish an approved driver education course, and have an adult sponsor.","p":"Right. An adult sponsor is required."},"es":{"q":"En Wisconsin, además del curso de manejo, ¿qué más necesita un joven para solicitar la licencia probatoria?","o":["Un carro a su nombre","Un trabajo de medio tiempo","Un adulto patrocinador","Un diploma de secundaria"],"h1":"Un adulto debe hacerse responsable del joven conductor.","h2":"Un joven de Wisconsin que solicita la licencia probatoria debe tener por lo menos 16 años, terminar un curso de manejo aprobado y tener un adulto patrocinador.","p":"Correcto. Se necesita un adulto patrocinador."},"zh":{"q":"在 Wisconsin，除了驾驶教育课程，青少年申请试用驾照还需要什么？","o":["一辆登记在自己名下的车","一份兼职工作","一位成年担保人（adult sponsor）","高中毕业证书"],"h1":"必须有一个成年人为这个青少年司机负责。","h2":"在 Wisconsin，申请试用驾照的青少年必须年满 16 岁，完成认可的驾驶教育课程，并有一位成年担保人。","p":"对。需要一位成年担保人。"},"vi":{"q":"Ở Wisconsin, ngoài khóa học lái xe, thiếu niên còn cần gì để xin bằng lái tạm thời?","o":["Một chiếc xe đứng tên mình","Một công việc bán thời gian","Một người lớn bảo lãnh (adult sponsor)","Bằng tốt nghiệp trung học"],"h1":"Một người lớn phải chịu trách nhiệm cho tài xế thiếu niên.","h2":"Ở Wisconsin, thiếu niên xin bằng lái tạm thời phải ít nhất 16 tuổi, hoàn thành khóa học lái xe được chấp thuận, và có một người lớn bảo lãnh.","p":"Đúng. Cần có một người lớn bảo lãnh."},"tl":{"q":"Sa Wisconsin, bukod sa driver education, ano pa ang kailangan ng isang teen para mag-apply ng probationary license?","o":["Kotseng nakapangalan sa kanya","Part-time na trabaho","Isang adult sponsor","High school diploma"],"h1":"Isang adult ang dapat managot para sa batang driver.","h2":"Ang teen sa Wisconsin na nag-a-apply ng probationary license ay dapat hindi bababa sa 16 taong gulang, tapos sa aprubadong driver education course, at may adult sponsor.","p":"Tama. Kailangan ng adult sponsor."},"ar":{"q":"في Wisconsin، بالإضافة إلى دورة تعليم القيادة، ماذا يحتاج المراهق أيضًا ليتقدم لرخصة القيادة التجريبية؟","o":["سيارة باسمه","عمل بدوام جزئي","شخص بالغ كفيل (adult sponsor)","شهادة الثانوية"],"h1":"يجب أن يتحمل شخص بالغ المسؤولية عن السائق المراهق.","h2":"المراهق في Wisconsin الذي يتقدم لرخصة القيادة التجريبية يجب أن يكون عمره 16 على الأقل، وأن يُنهي دورة معتمدة لتعليم القيادة، وأن يكون له شخص بالغ كفيل.","p":"صحيح. يجب وجود شخص بالغ كفيل."},"ref":{"doc":"WI","page":3}},{"id":"wi-008","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, during daylight, how old must the licensed adult be who rides with an instruction permit holder, when not a parent or instructor?","o":["18","21","16","30"],"h1":"The adult must be old enough to drink legally.","h2":"In Wisconsin a permit holder may practice by day with a licensed adult who is at least 21 and has at least two years of driving experience; after dark the adult must be at least 25.","p":"Right. The adult must be 21 or older."},"es":{"q":"En Wisconsin, de día, ¿qué edad debe tener el adulto con licencia que acompaña a un conductor con permiso, si no es un padre ni un instructor?","o":["18","21","16","30"],"h1":"El adulto debe tener edad para tomar alcohol legalmente.","h2":"En Wisconsin un conductor con permiso puede practicar de día con un adulto con licencia que tenga por lo menos 21 años y por lo menos dos años de experiencia manejando; de noche el adulto debe tener por lo menos 25 años.","p":"Correcto. El adulto debe tener 21 años o más."},"zh":{"q":"在 Wisconsin，白天陪学习驾照持有人开车的有驾照的成年人，如果不是父母或教练，必须几岁？","o":["18","21","16","30"],"h1":"这个成年人必须到了可以合法喝酒的年龄。","h2":"在 Wisconsin，学习驾照持有人白天可以和一位至少 21 岁、至少有两年驾驶经验、有驾照的成年人一起练车；天黑后，这个成年人必须至少 25 岁。","p":"对。这个成年人必须 21 岁或以上。"},"vi":{"q":"Ở Wisconsin, vào ban ngày, người lớn có bằng lái đi cùng người có giấy phép tập lái phải bao nhiêu tuổi, nếu không phải là cha mẹ hay người hướng dẫn?","o":["18","21","16","30"],"h1":"Người lớn đó phải đủ tuổi uống rượu hợp pháp.","h2":"Ở Wisconsin, người có giấy phép tập lái có thể tập lái ban ngày với một người lớn có bằng lái, ít nhất 21 tuổi và có ít nhất hai năm kinh nghiệm lái xe; sau khi trời tối, người lớn đó phải ít nhất 25 tuổi.","p":"Đúng. Người lớn phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Wisconsin, sa araw, ilang taon dapat ang adult na may lisensya na kasama ng may instruction permit, kung hindi siya magulang o instructor?","o":["18","21","16","30"],"h1":"Dapat nasa edad na ang adult para legal na uminom ng alak.","h2":"Sa Wisconsin, ang may permit ay puwedeng magsanay sa araw kasama ang adult na may lisensya na hindi bababa sa 21 taong gulang at may hindi bababa sa dalawang taong karanasan sa pagmamaneho; pagdilim, ang adult ay dapat hindi bababa sa 25.","p":"Tama. Ang adult ay dapat 21 o mas matanda."},"ar":{"q":"في Wisconsin، في النهار، كم يجب أن يكون عمر الشخص البالغ الذي معه رخصة ويركب مع حامل تصريح التعلم، إذا لم يكن أحد الوالدين أو مدربًا؟","o":["18","21","16","30"],"h1":"يجب أن يكون البالغ في السن القانونية لشرب الكحول.","h2":"في Wisconsin يمكن لحامل التصريح أن يتدرب في النهار مع شخص بالغ معه رخصة، عمره 21 على الأقل، وله خبرة قيادة سنتين على الأقل؛ وبعد حلول الظلام يجب أن يكون عمر البالغ 25 على الأقل.","p":"صحيح. يجب أن يكون عمر البالغ 21 أو أكثر."},"ref":{"doc":"WI","page":5}},{"id":"wi-009","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, who may ride with a probationary driver under 18 who is driving alone?","o":["No passengers at all","Only one family member","Up to three friends","Any number of immediate family and one other person"],"h1":"Family is treated differently from friends.","h2":"A Wisconsin probationary driver under 18 may carry any number of immediate family members and one other person; a qualified licensed adult may also ride along.","p":"Right. Immediate family plus one other person."},"es":{"q":"En Wisconsin, ¿quién puede viajar con un conductor con licencia probatoria menor de 18 años que maneja solo?","o":["Ningún pasajero","Solo un familiar","Hasta tres amigos","Cualquier número de familiares directos y una persona más"],"h1":"La familia se trata diferente que los amigos.","h2":"Un conductor con licencia probatoria menor de 18 años en Wisconsin puede llevar a cualquier número de familiares directos y a una persona más; también puede ir un adulto con licencia que cumpla los requisitos.","p":"Correcto. Familiares directos y una persona más."},"zh":{"q":"在 Wisconsin，18 岁以下的试用驾照司机单独开车时，谁可以坐在车上？","o":["完全不能有乘客","只能有一位家人","最多三个朋友","任何数量的直系家人，再加一个其他人"],"h1":"家人和朋友的规定不一样。","h2":"在 Wisconsin，18 岁以下的试用驾照司机可以载任何数量的直系家人，再加一个其他人；合格的有驾照成年人也可以同车。","p":"对。直系家人再加一个其他人。"},"vi":{"q":"Ở Wisconsin, ai có thể đi cùng tài xế có bằng lái tạm thời dưới 18 tuổi khi người đó lái một mình?","o":["Không có hành khách nào cả","Chỉ một người trong gia đình","Tối đa ba người bạn","Bất kỳ số người thân trong gia đình nào và thêm một người khác"],"h1":"Gia đình được đối xử khác với bạn bè.","h2":"Ở Wisconsin, tài xế có bằng lái tạm thời dưới 18 tuổi có thể chở bất kỳ số người thân trong gia đình nào và thêm một người khác; một người lớn có bằng lái đủ điều kiện cũng có thể đi cùng.","p":"Đúng. Người thân trong gia đình và thêm một người khác."},"tl":{"q":"Sa Wisconsin, sino ang puwedeng sumakay kasama ng probationary driver na wala pang 18 na nagmamaneho nang mag-isa?","o":["Walang pasahero","Isang miyembro lang ng pamilya","Hanggang tatlong kaibigan","Kahit ilang malapit na kapamilya at isa pang tao"],"h1":"Iba ang turing sa pamilya kaysa sa mga kaibigan.","h2":"Ang probationary driver sa Wisconsin na wala pang 18 ay puwedeng magsakay ng kahit ilang malapit na kapamilya at isa pang tao; puwede ring sumakay ang isang kwalipikadong adult na may lisensya.","p":"Tama. Malapit na kapamilya at isa pang tao."},"ar":{"q":"في Wisconsin، من يمكنه الركوب مع سائق برخصة تجريبية عمره أقل من 18 يقود وحده؟","o":["لا ركاب أبدًا","فرد واحد فقط من العائلة","حتى ثلاثة أصدقاء","أي عدد من أفراد العائلة المقربين وشخص واحد آخر"],"h1":"العائلة تُعامَل بشكل مختلف عن الأصدقاء.","h2":"السائق برخصة تجريبية في Wisconsin الذي عمره أقل من 18 يمكنه أن ينقل أي عدد من أفراد العائلة المقربين وشخصًا واحدًا آخر؛ ويمكن أيضًا أن يركب معه شخص بالغ مؤهل معه رخصة.","p":"صحيح. العائلة المقربة وشخص واحد آخر."},"ref":{"doc":"WI","page":6}},{"id":"wi-010","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, between midnight and 5 a.m., where may a probationary driver under 18 drive alone?","o":["Only between home, school and work","Anywhere","Only on highways","Nowhere, even for work"],"h1":"Think of the places a teen must get to.","h2":"A Wisconsin probationary driver under 18 may drive alone from midnight to 5 a.m. only between home, school and work.","p":"Right. Only between home, school and work."},"es":{"q":"En Wisconsin, entre medianoche y las 5 a.m., ¿a dónde puede manejar solo un conductor con licencia probatoria menor de 18 años?","o":["Solo entre la casa, la escuela y el trabajo","A cualquier lugar","Solo por autopistas","A ningún lugar, ni siquiera al trabajo"],"h1":"Piense en los lugares a los que un joven tiene que llegar.","h2":"Un conductor con licencia probatoria menor de 18 años en Wisconsin puede manejar solo de medianoche a 5 a.m. únicamente entre la casa, la escuela y el trabajo.","p":"Correcto. Solo entre la casa, la escuela y el trabajo."},"zh":{"q":"在 Wisconsin，午夜到早上 5 点之间，18 岁以下的试用驾照司机可以单独开车去哪里？","o":["只能在家、学校和工作地点之间","任何地方","只能在高速公路上","哪里都不行，上班也不行"],"h1":"想一想青少年必须去的地方。","h2":"在 Wisconsin，18 岁以下的试用驾照司机在午夜到早上 5 点之间，只能在家、学校和工作地点之间单独开车。","p":"对。只能在家、学校和工作地点之间。"},"vi":{"q":"Ở Wisconsin, từ nửa đêm đến 5 giờ sáng, tài xế có bằng lái tạm thời dưới 18 tuổi được lái một mình đi đâu?","o":["Chỉ giữa nhà, trường học và nơi làm việc","Bất cứ đâu","Chỉ trên đường cao tốc","Không được đi đâu cả, kể cả đi làm"],"h1":"Hãy nghĩ đến những nơi thiếu niên phải đến.","h2":"Ở Wisconsin, tài xế có bằng lái tạm thời dưới 18 tuổi chỉ được lái một mình từ nửa đêm đến 5 giờ sáng giữa nhà, trường học và nơi làm việc.","p":"Đúng. Chỉ giữa nhà, trường học và nơi làm việc."},"tl":{"q":"Sa Wisconsin, mula hatinggabi hanggang 5 a.m., saan puwedeng magmaneho nang mag-isa ang probationary driver na wala pang 18?","o":["Sa pagitan lang ng bahay, paaralan at trabaho","Kahit saan","Sa highway lang","Wala, kahit papunta sa trabaho"],"h1":"Isipin ang mga lugar na kailangang puntahan ng isang teen.","h2":"Ang probationary driver sa Wisconsin na wala pang 18 ay puwedeng magmaneho nang mag-isa mula hatinggabi hanggang 5 a.m. sa pagitan lang ng bahay, paaralan at trabaho.","p":"Tama. Sa pagitan lang ng bahay, paaralan at trabaho."},"ar":{"q":"في Wisconsin، بين منتصف الليل و5 صباحًا، أين يمكن للسائق برخصة تجريبية الذي عمره أقل من 18 أن يقود وحده؟","o":["فقط بين البيت والمدرسة والعمل","في أي مكان","على الطرق السريعة فقط","لا مكان، حتى للعمل"],"h1":"فكّر في الأماكن التي يجب أن يصل إليها المراهق.","h2":"السائق برخصة تجريبية في Wisconsin الذي عمره أقل من 18 يمكنه أن يقود وحده من منتصف الليل حتى 5 صباحًا فقط بين البيت والمدرسة والعمل.","p":"صحيح. فقط بين البيت والمدرسة والعمل."},"ref":{"doc":"WI","page":7}},{"id":"wi-011","scope":"WI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wisconsin, may a driver with an instruction permit or probationary license use a hands-free phone while driving?","o":["Yes, hands-free is allowed","No, except to report an emergency","Yes, but only on highways","Yes, if a parent says so"],"h1":"The rule covers every kind of phone, not only hand-held.","h2":"A Wisconsin driver with an instruction permit or probationary license may not use any phone while driving, hand-held or hands-free, except to report an emergency.","p":"Right. Only for an emergency."},"es":{"q":"En Wisconsin, ¿puede un conductor con permiso de aprendiz o licencia probatoria usar un teléfono manos libres mientras maneja?","o":["Sí, el manos libres está permitido","No, excepto para reportar una emergencia","Sí, pero solo en autopistas","Sí, si un padre lo autoriza"],"h1":"La regla cubre todo tipo de teléfono, no solo en la mano.","h2":"Un conductor de Wisconsin con permiso de aprendiz o licencia probatoria no puede usar ningún teléfono mientras maneja, ni en la mano ni con manos libres, excepto para reportar una emergencia.","p":"Correcto. Solo en una emergencia."},"zh":{"q":"在 Wisconsin，持学习驾照或试用驾照的司机开车时可以用免提电话吗？","o":["可以，免提是允许的","不可以，报告紧急情况除外","可以，但只能在高速公路上","可以，如果父母同意"],"h1":"这条规定包括所有电话，不只是手持电话。","h2":"在 Wisconsin，持学习驾照或试用驾照的司机开车时不能使用任何电话，手持或免提都不行，只有报告紧急情况时除外。","p":"对。只有紧急情况可以。"},"vi":{"q":"Ở Wisconsin, tài xế có giấy phép tập lái hoặc bằng lái tạm thời có được dùng điện thoại rảnh tay khi lái xe không?","o":["Có, được dùng rảnh tay","Không, trừ khi báo trường hợp khẩn cấp","Có, nhưng chỉ trên đường cao tốc","Có, nếu cha mẹ cho phép"],"h1":"Quy định này áp dụng cho mọi loại điện thoại, không chỉ điện thoại cầm tay.","h2":"Ở Wisconsin, tài xế có giấy phép tập lái hoặc bằng lái tạm thời không được dùng bất kỳ điện thoại nào khi lái xe, cầm tay hay rảnh tay, trừ khi báo trường hợp khẩn cấp.","p":"Đúng. Chỉ khi khẩn cấp."},"tl":{"q":"Sa Wisconsin, puwede bang gumamit ng hands-free na telepono habang nagmamaneho ang driver na may instruction permit o probationary license?","o":["Oo, puwede ang hands-free","Hindi, maliban kung mag-uulat ng emergency","Oo, pero sa highway lang","Oo, kung payag ang magulang"],"h1":"Sakop ng patakaran ang lahat ng uri ng telepono, hindi lang ang hawak sa kamay.","h2":"Ang driver sa Wisconsin na may instruction permit o probationary license ay hindi puwedeng gumamit ng anumang telepono habang nagmamaneho, hawak man o hands-free, maliban kung mag-uulat ng emergency.","p":"Tama. Para lang sa emergency."},"ar":{"q":"في Wisconsin، هل يمكن للسائق الذي معه تصريح تعلم أو رخصة تجريبية أن يستخدم هاتفًا بدون يدين (hands-free) أثناء القيادة؟","o":["نعم، الهاتف بدون يدين مسموح","لا، إلا للإبلاغ عن حالة طوارئ","نعم، لكن على الطرق السريعة فقط","نعم، إذا وافق أحد الوالدين"],"h1":"القاعدة تشمل كل أنواع الهواتف، وليس فقط الهاتف في اليد.","h2":"السائق في Wisconsin الذي معه تصريح تعلم أو رخصة تجريبية لا يمكنه استخدام أي هاتف أثناء القيادة، في اليد أو بدون يدين، إلا للإبلاغ عن حالة طوارئ.","p":"صحيح. فقط في حالة الطوارئ."},"ref":{"doc":"WI","page":49}},{"id":"wi-012","scope":"WI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Wisconsin, on a road with two or more lanes going your way, what does the Move Over law tell you to do for a stopped emergency vehicle with flashing lights?","o":["Stop behind it","Keep your lane and speed","Move out of the lane closest to it, or slow down if you cannot","Turn on your hazard lights and pass"],"h1":"Give the stopped vehicle a whole empty lane if you can.","h2":"Wisconsin's Move Over law says to move out of the lane closest to a stopped emergency or maintenance vehicle with flashing lights, or to slow down if you cannot move over safely.","p":"Right. Move over, or slow down if you cannot."},"es":{"q":"En Wisconsin, en un camino con dos o más carriles en su sentido, ¿qué le indica la ley de \"Move Over\" ante un vehículo de emergencia detenido con luces encendidas?","o":["Detenerse detrás de él","Seguir en su carril y a su velocidad","Salir del carril más cercano a él, o bajar la velocidad si no puede","Encender sus luces intermitentes y pasar"],"h1":"Si puede, déjele un carril completo libre al vehículo detenido.","h2":"La ley de \"Move Over\" de Wisconsin dice que debe salir del carril más cercano a un vehículo de emergencia o mantenimiento detenido con luces encendidas, o bajar la velocidad si no puede cambiarse con seguridad.","p":"Correcto. Cámbiese de carril, o baje la velocidad si no puede."},"zh":{"q":"在 Wisconsin，在你的方向有两条或更多车道的路上，对于停着并闪灯的紧急车辆，让道法（Move Over law）要求你怎么做？","o":["停在它后面","保持你的车道和速度","离开最靠近它的车道，如果做不到就减速","打开双闪灯然后超过去"],"h1":"如果可以，给停着的车留出一整条空车道。","h2":"Wisconsin 的让道法（Move Over law）规定，要离开最靠近停着并闪灯的紧急车辆或养护车辆的车道；如果不能安全变道，就要减速。","p":"对。让道，如果做不到就减速。"},"vi":{"q":"Ở Wisconsin, trên con đường có hai làn trở lên cùng chiều với bạn, luật Nhường Làn (Move Over law) bảo bạn làm gì khi có xe cấp cứu đang dừng và nháy đèn?","o":["Dừng lại phía sau xe đó","Giữ nguyên làn và tốc độ","Rời khỏi làn gần xe đó nhất, hoặc giảm tốc độ nếu không thể","Bật đèn khẩn cấp và vượt qua"],"h1":"Hãy chừa cho xe đang dừng cả một làn trống nếu có thể.","h2":"Luật Nhường Làn (Move Over law) của Wisconsin nói phải rời khỏi làn gần nhất với xe cấp cứu hoặc xe bảo trì đang dừng và nháy đèn, hoặc giảm tốc độ nếu bạn không thể chuyển làn an toàn.","p":"Đúng. Chuyển làn, hoặc giảm tốc độ nếu không thể."},"tl":{"q":"Sa Wisconsin, sa daan na may dalawa o higit pang lane papunta sa direksyon mo, ano ang sinasabi ng Move Over law na gawin mo para sa nakahintong emergency vehicle na may kumikislap na ilaw?","o":["Huminto sa likod nito","Manatili sa lane mo at sa bilis mo","Lumipat mula sa lane na pinakamalapit dito, o bumagal kung hindi mo kaya","Buksan ang hazard lights at lumampas"],"h1":"Bigyan ang nakahintong sasakyan ng isang buong bakanteng lane kung kaya mo.","h2":"Sinasabi ng Move Over law ng Wisconsin na lumipat mula sa lane na pinakamalapit sa nakahintong emergency o maintenance vehicle na may kumikislap na ilaw, o bumagal kung hindi ka ligtas na makalipat.","p":"Tama. Lumipat, o bumagal kung hindi mo kaya."},"ar":{"q":"في Wisconsin، على طريق فيه حارتان أو أكثر في اتجاهك، ماذا يطلب منك قانون الابتعاد (Move Over law) أن تفعل عند مركبة طوارئ متوقفة وأضواؤها تومض؟","o":["توقف خلفها","ابقَ في حارتك وعلى سرعتك","اخرج من الحارة الأقرب إليها، أو خفّف السرعة إذا لم تستطع","شغّل أضواء التحذير وتجاوزها"],"h1":"اترك للمركبة المتوقفة حارة كاملة فارغة إذا استطعت.","h2":"قانون الابتعاد (Move Over law) في Wisconsin يقول أن تخرج من الحارة الأقرب إلى مركبة الطوارئ أو الصيانة المتوقفة وأضواؤها تومض، أو أن تخفّف السرعة إذا لم تستطع تغيير الحارة بأمان.","p":"صحيح. ابتعد، أو خفّف السرعة إذا لم تستطع."},"ref":{"doc":"WI","page":51}},{"id":"wi-013","scope":"WI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Wisconsin, what was added to the Move Over law by 2025 Wisconsin Act 54?","o":["Disabled vehicles","Parked bicycles","Mail trucks only","Nothing was added"],"h1":"Think of a car stopped on the shoulder after breaking down.","h2":"Since 2025 Wisconsin Act 54, the Move Over law also protects disabled vehicles stopped along the road.","p":"Right. Disabled vehicles are now covered."},"es":{"q":"En Wisconsin, ¿qué se agregó a la ley de \"Move Over\" con la Ley 54 de Wisconsin de 2025?","o":["Vehículos descompuestos","Bicicletas estacionadas","Solo camiones del correo","No se agregó nada"],"h1":"Piense en un carro detenido en el acotamiento porque se descompuso.","h2":"Desde la Ley 54 de Wisconsin de 2025, la ley de \"Move Over\" también protege a los vehículos descompuestos detenidos a un lado del camino.","p":"Correcto. Los vehículos descompuestos ahora están cubiertos."},"zh":{"q":"在 Wisconsin，2025 Wisconsin Act 54 给让道法（Move Over law）增加了什么？","o":["故障车辆","停着的自行车","只有邮政卡车","什么都没增加"],"h1":"想一想车坏了以后停在路肩上的车。","h2":"自从 2025 Wisconsin Act 54 以后，让道法也保护停在路边的故障车辆。","p":"对。现在故障车辆也受保护。"},"vi":{"q":"Ở Wisconsin, 2025 Wisconsin Act 54 đã thêm gì vào luật Nhường Làn (Move Over law)?","o":["Xe bị hư","Xe đạp đang đậu","Chỉ xe chở thư","Không thêm gì cả"],"h1":"Hãy nghĩ đến chiếc xe dừng bên lề đường sau khi bị hư.","h2":"Từ khi có 2025 Wisconsin Act 54, luật Nhường Làn cũng bảo vệ các xe bị hư đang dừng bên đường.","p":"Đúng. Xe bị hư nay cũng được bảo vệ."},"tl":{"q":"Sa Wisconsin, ano ang idinagdag sa Move Over law ng 2025 Wisconsin Act 54?","o":["Mga sirang sasakyan","Mga nakaparadang bisikleta","Mga mail truck lang","Walang idinagdag"],"h1":"Isipin ang kotseng nakahinto sa gilid ng daan dahil nasira.","h2":"Mula sa 2025 Wisconsin Act 54, pinoprotektahan na rin ng Move Over law ang mga sirang sasakyan na nakahinto sa tabi ng daan.","p":"Tama. Sakop na ngayon ang mga sirang sasakyan."},"ar":{"q":"في Wisconsin، ماذا أضاف 2025 Wisconsin Act 54 إلى قانون الابتعاد (Move Over law)؟","o":["المركبات المعطّلة","الدراجات المتوقفة","شاحنات البريد فقط","لم يُضَف شيء"],"h1":"فكّر في سيارة متوقفة على كتف الطريق بعد أن تعطّلت.","h2":"منذ 2025 Wisconsin Act 54، يحمي قانون الابتعاد أيضًا المركبات المعطّلة المتوقفة على جانب الطريق.","p":"صحيح. المركبات المعطّلة مشمولة الآن."},"ref":{"doc":"WI","page":null}},{"id":"wi-014","scope":"WI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wisconsin, how much alcohol may a driver under 21 have in the blood?","o":["Up to 0.08","Up to 0.04","Up to 0.02","None at all"],"h1":"Wisconsin calls this the absolute sobriety law.","h2":"Under Wisconsin's absolute sobriety law, a driver under 21 may not drive with any alcohol in the blood.","p":"Right. Under 21, no alcohol at all."},"es":{"q":"En Wisconsin, ¿cuánto alcohol puede tener en la sangre un conductor menor de 21 años?","o":["Hasta 0.08","Hasta 0.04","Hasta 0.02","Nada de alcohol"],"h1":"Wisconsin llama a esto la ley de sobriedad absoluta.","h2":"Según la ley de sobriedad absoluta de Wisconsin, un conductor menor de 21 años no puede manejar con nada de alcohol en la sangre.","p":"Correcto. Menor de 21, nada de alcohol."},"zh":{"q":"在 Wisconsin，21 岁以下的司机血液中可以有多少酒精？","o":["最多 0.08","最多 0.04","最多 0.02","完全不可以有"],"h1":"Wisconsin 把这叫做绝对清醒法（absolute sobriety law）。","h2":"根据 Wisconsin 的绝对清醒法，21 岁以下的司机血液中有任何酒精都不能开车。","p":"对。21 岁以下，完全不能有酒精。"},"vi":{"q":"Ở Wisconsin, tài xế dưới 21 tuổi được có bao nhiêu cồn trong máu?","o":["Tối đa 0.08","Tối đa 0.04","Tối đa 0.02","Hoàn toàn không có"],"h1":"Wisconsin gọi đây là luật tỉnh táo tuyệt đối (absolute sobriety law).","h2":"Theo luật tỉnh táo tuyệt đối của Wisconsin, tài xế dưới 21 tuổi không được lái xe khi có bất kỳ chút cồn nào trong máu.","p":"Đúng. Dưới 21 tuổi, hoàn toàn không có cồn."},"tl":{"q":"Sa Wisconsin, gaano karaming alak ang puwedeng nasa dugo ng driver na wala pang 21?","o":["Hanggang 0.08","Hanggang 0.04","Hanggang 0.02","Wala talaga"],"h1":"Tinatawag ito ng Wisconsin na absolute sobriety law.","h2":"Sa ilalim ng absolute sobriety law ng Wisconsin, ang driver na wala pang 21 ay hindi puwedeng magmaneho nang may kahit anong alak sa dugo.","p":"Tama. Wala pang 21, walang alak talaga."},"ar":{"q":"في Wisconsin، كم من الكحول يمكن أن يكون في دم السائق الذي عمره أقل من 21؟","o":["حتى 0.08","حتى 0.04","حتى 0.02","لا شيء أبدًا"],"h1":"تسمّي Wisconsin هذا قانون الامتناع التام (absolute sobriety law).","h2":"حسب قانون الامتناع التام في Wisconsin، لا يمكن للسائق الذي عمره أقل من 21 أن يقود وفي دمه أي كمية من الكحول.","p":"صحيح. أقل من 21، لا كحول أبدًا."},"ref":{"doc":"WI","page":49}},{"id":"wi-015","scope":"WI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wisconsin, what is the penalty for breaking the absolute sobriety law?","o":["A warning only","A 3-month suspension, a $200 forfeiture and 4 points","Ten years in prison","A $5 fine"],"h1":"It includes a suspension of a quarter of a year.","h2":"Breaking Wisconsin's absolute sobriety law brings a three-month suspension, a $200 forfeiture and four points on your record.","p":"Right. Three months, $200 and four points."},"es":{"q":"En Wisconsin, ¿cuál es la sanción por no cumplir la ley de sobriedad absoluta?","o":["Solo una advertencia","Una suspensión de 3 meses, una multa de $200 y 4 puntos","Diez años de cárcel","Una multa de $5"],"h1":"Incluye una suspensión de la cuarta parte de un año.","h2":"No cumplir la ley de sobriedad absoluta de Wisconsin trae una suspensión de tres meses, una multa de $200 y cuatro puntos en su historial.","p":"Correcto. Tres meses, $200 y cuatro puntos."},"zh":{"q":"在 Wisconsin，违反绝对清醒法（absolute sobriety law）会受到什么处罚？","o":["只有警告","吊销驾照 3 个月，罚款 $200，记 4 分","坐牢十年","罚款 $5"],"h1":"它包括吊销驾照四分之一年。","h2":"违反 Wisconsin 的绝对清醒法会被吊销驾照三个月，罚款 $200，并在你的记录上记四分。","p":"对。三个月，$200，四分。"},"vi":{"q":"Ở Wisconsin, hình phạt khi vi phạm luật tỉnh táo tuyệt đối (absolute sobriety law) là gì?","o":["Chỉ cảnh cáo","Treo bằng 3 tháng, phạt $200 và 4 điểm","Mười năm tù","Phạt $5"],"h1":"Nó gồm việc treo bằng một phần tư năm.","h2":"Vi phạm luật tỉnh táo tuyệt đối của Wisconsin sẽ bị treo bằng ba tháng, phạt $200 và bốn điểm trong hồ sơ của bạn.","p":"Đúng. Ba tháng, $200 và bốn điểm."},"tl":{"q":"Sa Wisconsin, ano ang parusa sa paglabag sa absolute sobriety law?","o":["Babala lang","3 buwang suspensyon, $200 na multa (forfeiture) at 4 na puntos","Sampung taon sa kulungan","$5 na multa"],"h1":"Kasama dito ang suspensyon na isang-kapat ng taon.","h2":"Ang paglabag sa absolute sobriety law ng Wisconsin ay may tatlong buwang suspensyon, $200 na multa (forfeiture) at apat na puntos sa iyong record.","p":"Tama. Tatlong buwan, $200 at apat na puntos."},"ar":{"q":"في Wisconsin، ما عقوبة مخالفة قانون الامتناع التام (absolute sobriety law)؟","o":["تحذير فقط","إيقاف الرخصة 3 أشهر، وغرامة $200، و4 نقاط","عشر سنوات في السجن","غرامة $5"],"h1":"تشمل إيقاف الرخصة ربع سنة.","h2":"مخالفة قانون الامتناع التام في Wisconsin تؤدي إلى إيقاف الرخصة ثلاثة أشهر، وغرامة $200، وأربع نقاط في سجلك.","p":"صحيح. ثلاثة أشهر، و$200، وأربع نقاط."},"ref":{"doc":"WI","page":null}},{"id":"wi-016","scope":"WI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wisconsin, how is a first drunk driving (OWI) offense with no aggravating factors treated?","o":["As a felony","As a misdemeanor crime","As a civil violation, not a crime","It is not punished"],"h1":"Wisconsin is unusual among the states on this point.","h2":"In Wisconsin a first OWI offense is a civil violation rather than a crime, but it still brings a forfeiture and loss of your license.","p":"Right. A first OWI is a civil violation in Wisconsin."},"es":{"q":"En Wisconsin, ¿cómo se trata una primera infracción de manejar bajo los efectos del alcohol (OWI) sin agravantes?","o":["Como delito grave","Como delito menor","Como infracción civil, no como delito","No se castiga"],"h1":"Wisconsin es poco común entre los estados en este punto.","h2":"En Wisconsin una primera infracción OWI es una infracción civil y no un delito, pero aun así trae una multa y la pérdida de la licencia.","p":"Correcto. Una primera OWI es una infracción civil en Wisconsin."},"zh":{"q":"在 Wisconsin，第一次酒后驾驶（OWI），而且没有加重情节，会被怎样对待？","o":["当作重罪","当作轻罪","当作民事违规，不是犯罪","不会受到处罚"],"h1":"在这一点上，Wisconsin 和其他州很不一样。","h2":"在 Wisconsin，第一次 OWI 是民事违规，不是犯罪，但仍然会被罚款并失去驾照。","p":"对。在 Wisconsin，第一次 OWI 是民事违规。"},"vi":{"q":"Ở Wisconsin, lần đầu lái xe khi say rượu (OWI) mà không có tình tiết tăng nặng được xử lý thế nào?","o":["Là trọng tội","Là tội nhẹ","Là vi phạm dân sự, không phải tội phạm","Không bị phạt"],"h1":"Wisconsin khác thường so với các tiểu bang khác ở điểm này.","h2":"Ở Wisconsin, lần đầu phạm OWI là vi phạm dân sự chứ không phải tội phạm, nhưng vẫn bị phạt tiền và mất bằng lái.","p":"Đúng. Lần đầu phạm OWI ở Wisconsin là vi phạm dân sự."},"tl":{"q":"Sa Wisconsin, paano itinuturing ang unang paglabag sa pagmamaneho nang lasing (OWI) na walang nagpapabigat na dahilan?","o":["Bilang felony","Bilang misdemeanor na krimen","Bilang civil violation, hindi krimen","Hindi ito pinaparusahan"],"h1":"Kakaiba ang Wisconsin kumpara sa ibang estado sa puntong ito.","h2":"Sa Wisconsin, ang unang OWI ay civil violation at hindi krimen, pero may multa pa rin ito at mawawala ang iyong lisensya.","p":"Tama. Ang unang OWI ay civil violation sa Wisconsin."},"ar":{"q":"في Wisconsin، كيف تُعامَل أول مخالفة قيادة تحت تأثير الكحول (OWI) بدون ظروف مشدِّدة؟","o":["كجناية","كجنحة","كمخالفة مدنية، وليست جريمة","لا عقوبة عليها"],"h1":"Wisconsin غير عادية بين الولايات في هذه النقطة.","h2":"في Wisconsin أول مخالفة OWI هي مخالفة مدنية وليست جريمة، لكنها مع ذلك تؤدي إلى غرامة وفقدان رخصتك.","p":"صحيح. أول OWI مخالفة مدنية في Wisconsin."},"ref":{"doc":"WI","page":null}},{"id":"wi-017","scope":"WI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Wisconsin, unless posted otherwise, what is the speed limit when passing a school while children are going to or from school?","o":["25 mph","30 mph","20 mph","15 mph"],"h1":"It is lower than 20.","h2":"Unless a different limit is posted, Wisconsin sets 15 miles per hour when passing a school while children are going to or from school or playing near it.","p":"Right. 15 mph near schools when children are present."},"es":{"q":"En Wisconsin, si no hay otro límite indicado, ¿cuál es el límite al pasar por una escuela mientras los niños llegan o salen?","o":["25 mph","30 mph","20 mph","15 mph"],"h1":"Es menos de 20.","h2":"Si no hay otro límite indicado, Wisconsin fija 15 millas por hora al pasar por una escuela mientras los niños llegan, salen o juegan cerca.","p":"Correcto. 15 mph cerca de escuelas cuando hay niños."},"zh":{"q":"在 Wisconsin，如果没有其他标示，孩子上学或放学时经过学校，限速是多少？","o":["25 mph","30 mph","20 mph","15 mph"],"h1":"它比 20 低。","h2":"如果没有标示其他限速，Wisconsin 规定在孩子上学、放学或在附近玩耍时经过学校，限速是每小时 15 英里。","p":"对。有孩子时学校附近限速 15 mph。"},"vi":{"q":"Ở Wisconsin, nếu không có biển báo khác, tốc độ tối đa khi đi qua trường học lúc trẻ em đang đi học hoặc tan học là bao nhiêu?","o":["25 mph","30 mph","20 mph","15 mph"],"h1":"Nó thấp hơn 20.","h2":"Nếu không có biển báo tốc độ khác, Wisconsin quy định 15 dặm một giờ khi đi qua trường học lúc trẻ em đang đi học, tan học hoặc chơi gần đó.","p":"Đúng. 15 mph gần trường học khi có trẻ em."},"tl":{"q":"Sa Wisconsin, kung walang ibang nakapaskil, ano ang speed limit kapag dumadaan sa paaralan habang papasok o pauwi ang mga bata?","o":["25 mph","30 mph","20 mph","15 mph"],"h1":"Mas mababa ito sa 20.","h2":"Kung walang ibang limit na nakapaskil, 15 milya bawat oras ang itinakda ng Wisconsin kapag dumadaan sa paaralan habang papasok o pauwi ang mga bata o naglalaro malapit dito.","p":"Tama. 15 mph malapit sa paaralan kapag may mga bata."},"ar":{"q":"في Wisconsin، إذا لم توجد لافتة بحد آخر، ما حد السرعة عند المرور بجانب مدرسة أثناء ذهاب الأطفال إلى المدرسة أو عودتهم منها؟","o":["25 mph","30 mph","20 mph","15 mph"],"h1":"هو أقل من 20.","h2":"إذا لم توجد لافتة بحد آخر، تحدد Wisconsin سرعة 15 ميلًا في الساعة عند المرور بجانب مدرسة أثناء ذهاب الأطفال إليها أو عودتهم منها أو لعبهم قربها.","p":"صحيح. 15 mph قرب المدارس عند وجود الأطفال."},"ref":{"doc":"WI","page":10}},{"id":"wi-018","scope":"WI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Wisconsin, what is the highest speed limit that may be posted on some freeways?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"It is five more than 65.","h2":"Wisconsin law allows a speed limit of 70 miles per hour on freeways where signs post it.","p":"Right. Some Wisconsin freeways are posted at 70 mph."},"es":{"q":"En Wisconsin, ¿cuál es el límite de velocidad más alto que se puede indicar en algunas autopistas?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Es cinco más que 65.","h2":"La ley de Wisconsin permite un límite de 70 millas por hora en las autopistas donde las señales lo indican.","p":"Correcto. Algunas autopistas de Wisconsin están indicadas a 70 mph."},"zh":{"q":"在 Wisconsin，一些高速公路上可以标示的最高限速是多少？","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"它比 65 多五。","h2":"Wisconsin 法律允许在有标志的高速公路上限速每小时 70 英里。","p":"对。Wisconsin 一些高速公路标示 70 mph。"},"vi":{"q":"Ở Wisconsin, tốc độ tối đa cao nhất có thể được ghi trên một số xa lộ là bao nhiêu?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Nó nhiều hơn 65 năm đơn vị.","h2":"Luật Wisconsin cho phép tốc độ tối đa 70 dặm một giờ trên các xa lộ có biển báo ghi như vậy.","p":"Đúng. Một số xa lộ ở Wisconsin ghi 70 mph."},"tl":{"q":"Sa Wisconsin, ano ang pinakamataas na speed limit na puwedeng ipaskil sa ilang freeway?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Ito ay lima pa kaysa 65.","h2":"Pinapayagan ng batas ng Wisconsin ang speed limit na 70 milya bawat oras sa mga freeway kung saan ito nakapaskil.","p":"Tama. May mga freeway sa Wisconsin na naka-post na 70 mph."},"ar":{"q":"في Wisconsin، ما أعلى حد للسرعة يمكن وضعه على بعض الطرق السريعة؟","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"هو أكثر من 65 بخمسة.","h2":"قانون Wisconsin يسمح بحد سرعة 70 ميلًا في الساعة على الطرق السريعة التي توجد عليها لافتات بذلك.","p":"صحيح. بعض الطرق السريعة في Wisconsin حدها 70 mph."},"ref":{"doc":"WI","page":null}},{"id":"wi-019","scope":"WI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wisconsin, how many demerit points within 12 months will cost you your driving privilege?","o":["6 points or more","8 points or more","12 points or more","18 points or more"],"h1":"It is the same number as the months.","h2":"In Wisconsin, 12 or more demerit points within any 12-month period lead to a suspension or revocation of your driving privilege.","p":"Right. 12 points in 12 months means you lose the privilege to drive."},"es":{"q":"En Wisconsin, ¿cuántos puntos de demérito en 12 meses le hacen perder el privilegio de manejar?","o":["6 puntos o más","8 puntos o más","12 puntos o más","18 puntos o más"],"h1":"Es el mismo número que los meses.","h2":"En Wisconsin, 12 o más puntos de demérito en cualquier período de 12 meses llevan a la suspensión o revocación de su privilegio de manejar.","p":"Correcto. 12 puntos en 12 meses y usted pierde el privilegio de manejar."},"zh":{"q":"在 Wisconsin，12 个月内累计多少扣分会让你失去驾驶资格？","o":["6 分或以上","8 分或以上","12 分或以上","18 分或以上"],"h1":"它和月份的数字一样。","h2":"在 Wisconsin，任何 12 个月内累计 12 分或以上的扣分，会导致你的驾驶资格被暂停或吊销。","p":"对。12 个月内扣 12 分，你就会失去驾驶资格。"},"vi":{"q":"Ở Wisconsin, bao nhiêu điểm phạt trong vòng 12 tháng sẽ làm bạn mất quyền lái xe?","o":["6 điểm trở lên","8 điểm trở lên","12 điểm trở lên","18 điểm trở lên"],"h1":"Đó là cùng con số với số tháng.","h2":"Ở Wisconsin, có 12 điểm phạt trở lên trong bất kỳ khoảng 12 tháng nào sẽ dẫn đến việc bị đình chỉ hoặc thu hồi quyền lái xe.","p":"Đúng. 12 điểm trong 12 tháng nghĩa là bạn mất quyền lái xe."},"tl":{"q":"Sa Wisconsin, ilang demerit point sa loob ng 12 buwan ang magpapawala sa iyo ng pribilehiyong magmaneho?","o":["6 na puntos o higit pa","8 puntos o higit pa","12 puntos o higit pa","18 puntos o higit pa"],"h1":"Pareho ito sa bilang ng mga buwan.","h2":"Sa Wisconsin, ang 12 o higit pang demerit point sa loob ng anumang 12 buwan ay magdudulot ng suspensyon o pagbawi ng iyong pribilehiyong magmaneho.","p":"Tama. 12 puntos sa 12 buwan ay nangangahulugang mawawala ang pribilehiyo mong magmaneho."},"ar":{"q":"في Wisconsin، كم نقطة مخالفة خلال 12 شهرًا تجعلك تفقد حق القيادة؟","o":["6 نقاط أو أكثر","8 نقاط أو أكثر","12 نقطة أو أكثر","18 نقطة أو أكثر"],"h1":"هو نفس عدد الأشهر.","h2":"في Wisconsin، 12 نقطة مخالفة أو أكثر خلال أي فترة 12 شهرًا تؤدي إلى إيقاف حق القيادة أو سحبه.","p":"صحيح. 12 نقطة في 12 شهرًا تعني أنك تفقد حق القيادة."},"ref":{"doc":"WI","page":53}},{"id":"wi-020","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, what happens to the points of a probationary license holder on a second or later conviction?","o":["The points are doubled","The points are cut in half","No points are added","The points are removed after a month"],"h1":"New drivers are held to a stricter rule.","h2":"In Wisconsin, a probationary license holder gets double points for the second traffic conviction and every one after it.","p":"Right. Probationary drivers get double points from the second conviction on."},"es":{"q":"En Wisconsin, ¿qué pasa con los puntos de quien tiene una licencia probatoria en una segunda condena o en las siguientes?","o":["Los puntos se duplican","Los puntos se reducen a la mitad","No se agregan puntos","Los puntos se borran después de un mes"],"h1":"Los conductores nuevos tienen una regla más estricta.","h2":"En Wisconsin, quien tiene una licencia probatoria recibe el doble de puntos por la segunda condena de tránsito y por cada una después.","p":"Correcto. Los conductores con licencia probatoria reciben el doble de puntos desde la segunda condena."},"zh":{"q":"在 Wisconsin，试用驾照持有人第二次或之后被判违规时，扣分会怎样？","o":["扣分加倍","扣分减半","不扣分","一个月后扣分被取消"],"h1":"新司机要遵守更严格的规定。","h2":"在 Wisconsin，试用驾照持有人从第二次交通违规判决开始，每一次都扣双倍的分。","p":"对。试用驾照司机从第二次违规开始扣双倍的分。"},"vi":{"q":"Ở Wisconsin, điểm phạt của người có bằng lái tạm thời sẽ ra sao khi bị kết tội lần thứ hai hoặc các lần sau?","o":["Điểm bị nhân đôi","Điểm bị giảm một nửa","Không bị cộng điểm","Điểm được xóa sau một tháng"],"h1":"Tài xế mới phải theo quy định nghiêm hơn.","h2":"Ở Wisconsin, người có bằng lái tạm thời bị nhân đôi điểm phạt cho lần vi phạm giao thông thứ hai và mọi lần sau đó.","p":"Đúng. Tài xế có bằng lái tạm thời bị nhân đôi điểm từ lần vi phạm thứ hai."},"tl":{"q":"Sa Wisconsin, ano ang nangyayari sa puntos ng may probationary license sa ikalawa o susunod na conviction?","o":["Dinodoble ang puntos","Hinahati sa kalahati ang puntos","Walang puntos na idinadagdag","Inaalis ang puntos pagkalipas ng isang buwan"],"h1":"Mas mahigpit ang patakaran sa mga bagong driver.","h2":"Sa Wisconsin, ang may probationary license ay nakakakuha ng dobleng puntos sa ikalawang traffic conviction at sa bawat isa pagkatapos nito.","p":"Tama. Dobleng puntos ang probationary driver mula sa ikalawang conviction."},"ar":{"q":"في Wisconsin، ماذا يحدث لنقاط حامل رخصة القيادة التجريبية عند الإدانة الثانية أو ما بعدها؟","o":["تتضاعف النقاط","تُخفض النقاط إلى النصف","لا تُضاف نقاط","تُحذف النقاط بعد شهر"],"h1":"السائقون الجدد يخضعون لقاعدة أشد.","h2":"في Wisconsin، حامل رخصة القيادة التجريبية يحصل على نقاط مضاعفة في الإدانة المرورية الثانية وفي كل إدانة بعدها.","p":"صحيح. السائق برخصة تجريبية يحصل على نقاط مضاعفة من الإدانة الثانية فما بعد."},"ref":{"doc":"WI","page":53}},{"id":"wi-021","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, a crash with no injuries must be reported to police when private property damage reaches what amount?","o":["$200 or more","$500 or more","$2,500 or more","$1,000 or more"],"h1":"Damage to government property has a lower amount.","h2":"In Wisconsin, you must report a crash to police when it causes $1,000 or more in property damage, even if no one is hurt.","p":"Right. $1,000 or more in damage means you call the police."},"es":{"q":"En Wisconsin, un choque sin heridos se debe reportar a la policía cuando el daño a la propiedad privada llega a ¿qué cantidad?","o":["$200 o más","$500 o más","$2,500 o más","$1,000 o más"],"h1":"El daño a propiedad del gobierno tiene una cantidad más baja.","h2":"En Wisconsin, usted debe reportar un choque a la policía cuando causa $1,000 o más en daños a la propiedad, aunque nadie esté herido.","p":"Correcto. Con $1,000 o más en daños, se llama a la policía."},"zh":{"q":"在 Wisconsin，没有人受伤的车祸，私人财产损失达到多少时必须向警察报告？","o":["$200 或以上","$500 或以上","$2,500 或以上","$1,000 或以上"],"h1":"政府财产损失的金额要求更低。","h2":"在 Wisconsin，即使没有人受伤，车祸造成 $1,000 或以上的财产损失时，你必须向警察报告。","p":"对。损失达到 $1,000 或以上，就要报警。"},"vi":{"q":"Ở Wisconsin, một vụ tai nạn không có người bị thương phải được báo cho cảnh sát khi thiệt hại tài sản tư nhân đạt bao nhiêu?","o":["$200 trở lên","$500 trở lên","$2,500 trở lên","$1,000 trở lên"],"h1":"Thiệt hại tài sản của chính phủ có mức thấp hơn.","h2":"Ở Wisconsin, bạn phải báo cho cảnh sát khi vụ tai nạn gây thiệt hại tài sản từ $1,000 trở lên, kể cả khi không ai bị thương.","p":"Đúng. Thiệt hại từ $1,000 trở lên thì bạn gọi cảnh sát."},"tl":{"q":"Sa Wisconsin, ang aksidenteng walang nasaktan ay dapat i-report sa pulis kapag umabot sa anong halaga ang pinsala sa pribadong ari-arian?","o":["$200 o higit pa","$500 o higit pa","$2,500 o higit pa","$1,000 o higit pa"],"h1":"Mas mababa ang halaga para sa pinsala sa ari-arian ng gobyerno.","h2":"Sa Wisconsin, dapat mong i-report sa pulis ang aksidente kapag nagdulot ito ng $1,000 o higit pang pinsala sa ari-arian, kahit walang nasaktan.","p":"Tama. Kapag $1,000 o higit pa ang pinsala, tumawag sa pulis."},"ar":{"q":"في Wisconsin، يجب إبلاغ الشرطة عن حادث بدون إصابات عندما تصل أضرار الممتلكات الخاصة إلى أي مبلغ؟","o":["$200 أو أكثر","$500 أو أكثر","$2,500 أو أكثر","$1,000 أو أكثر"],"h1":"أضرار الممتلكات الحكومية لها مبلغ أقل.","h2":"في Wisconsin يجب أن تبلغ الشرطة عن الحادث عندما يسبب أضرارًا في الممتلكات بقيمة $1,000 أو أكثر، حتى لو لم يُصب أحد.","p":"صحيح. أضرار بقيمة $1,000 أو أكثر تعني أن تتصل بالشرطة."},"ref":{"doc":"WI","page":47}},{"id":"wi-022","scope":"WI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Wisconsin, a school bus is stopped with its red lights flashing. How far from it must you stop?","o":["At least 10 feet","At least 20 feet","At least 50 feet","At least 100 feet"],"h1":"It is about the length of one and a half cars.","h2":"In Wisconsin, stop at least 20 feet from a school bus with flashing red lights. On a divided highway, traffic on the other side of the median does not have to stop.","p":"Right. Stop at least 20 feet away from the bus."},"es":{"q":"En Wisconsin, un autobús escolar está detenido con sus luces rojas intermitentes. ¿A qué distancia de él debe usted detenerse?","o":["Al menos 10 pies","Al menos 20 pies","Al menos 50 pies","Al menos 100 pies"],"h1":"Es más o menos el largo de un carro y medio.","h2":"En Wisconsin, deténgase al menos a 20 pies de un autobús escolar con luces rojas intermitentes. En una carretera dividida, el tráfico del otro lado de la división no tiene que detenerse.","p":"Correcto. Deténgase al menos a 20 pies del autobús."},"zh":{"q":"在 Wisconsin，一辆校车闪着红灯停下。你必须在离它多远的地方停车？","o":["至少 10 英尺","至少 20 英尺","至少 50 英尺","至少 100 英尺"],"h1":"大约是一辆半汽车的长度。","h2":"在 Wisconsin，要在离闪着红灯的校车至少 20 英尺的地方停车。在有中间隔离带的公路上，隔离带另一边的车不用停。","p":"对。在离校车至少 20 英尺的地方停车。"},"vi":{"q":"Ở Wisconsin, một xe buýt trường học đang dừng và nháy đèn đỏ. Bạn phải dừng lại cách nó bao xa?","o":["Ít nhất 10 feet","Ít nhất 20 feet","Ít nhất 50 feet","Ít nhất 100 feet"],"h1":"Khoảng bằng chiều dài của một chiếc xe rưỡi.","h2":"Ở Wisconsin, hãy dừng lại cách ít nhất 20 feet so với xe buýt trường học đang nháy đèn đỏ. Trên xa lộ có dải phân cách, xe ở phía bên kia dải phân cách không phải dừng.","p":"Đúng. Dừng lại cách xe buýt ít nhất 20 feet."},"tl":{"q":"Sa Wisconsin, nakahinto ang isang school bus na kumikislap ang pulang ilaw. Gaano kalayo mula rito ka dapat huminto?","o":["Hindi bababa sa 10 feet","Hindi bababa sa 20 feet","Hindi bababa sa 50 feet","Hindi bababa sa 100 feet"],"h1":"Mga haba ito ng isa't kalahating kotse.","h2":"Sa Wisconsin, huminto nang hindi bababa sa 20 feet mula sa school bus na kumikislap ang pulang ilaw. Sa divided highway, hindi kailangang huminto ang mga sasakyan sa kabilang panig ng median.","p":"Tama. Huminto nang hindi bababa sa 20 feet mula sa bus."},"ar":{"q":"في Wisconsin، حافلة مدرسية متوقفة وأضواؤها الحمراء تومض. على أي بعد منها يجب أن تتوقف؟","o":["10 أقدام على الأقل","20 قدمًا على الأقل","50 قدمًا على الأقل","100 قدم على الأقل"],"h1":"هي تقريبًا طول سيارة ونصف.","h2":"في Wisconsin، توقّف على بعد 20 قدمًا على الأقل من حافلة مدرسية أضواؤها الحمراء تومض. على طريق سريع مقسوم، ليس على السيارات في الجهة الأخرى من الفاصل أن تتوقف.","p":"صحيح. توقّف على بعد 20 قدمًا على الأقل من الحافلة."},"ref":{"doc":"WI","page":51}},{"id":"wi-023","scope":"WI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Wisconsin, how many seconds of following distance does the handbook tell you to keep in good conditions?","o":["1 second","2 seconds","4 seconds","8 seconds"],"h1":"It is more than three seconds.","h2":"Wisconsin teaches a four-second following distance, and you add one more second for each bad condition such as rain, snow, ice or heavy traffic.","p":"Right. Keep at least four seconds behind the car ahead."},"es":{"q":"En Wisconsin, ¿cuántos segundos de distancia detrás de otro vehículo le pide mantener el manual en buenas condiciones?","o":["1 segundo","2 segundos","4 segundos","8 segundos"],"h1":"Es más de tres segundos.","h2":"Wisconsin enseña una distancia de cuatro segundos detrás del otro vehículo, y usted agrega un segundo más por cada condición mala, como lluvia, nieve, hielo o mucho tráfico.","p":"Correcto. Mantenga al menos cuatro segundos detrás del carro de adelante."},"zh":{"q":"在 Wisconsin，手册说在良好条件下要保持几秒的跟车距离？","o":["1 秒","2 秒","4 秒","8 秒"],"h1":"它多于三秒。","h2":"Wisconsin 教的是四秒跟车距离，遇到雨、雪、冰或交通拥挤等每一种不好的情况，就再加一秒。","p":"对。和前面的车保持至少四秒的距离。"},"vi":{"q":"Ở Wisconsin, sổ tay hướng dẫn bảo bạn giữ khoảng cách bao nhiêu giây với xe phía trước khi điều kiện tốt?","o":["1 giây","2 giây","4 giây","8 giây"],"h1":"Nhiều hơn ba giây.","h2":"Wisconsin dạy giữ khoảng cách bốn giây với xe phía trước, và cộng thêm một giây cho mỗi điều kiện xấu như mưa, tuyết, băng hoặc kẹt xe.","p":"Đúng. Giữ khoảng cách ít nhất bốn giây với xe phía trước."},"tl":{"q":"Sa Wisconsin, ilang segundo ng following distance ang sinasabi ng handbook na panatilihin mo kapag maayos ang kondisyon?","o":["1 segundo","2 segundo","4 na segundo","8 segundo"],"h1":"Mas mahaba ito sa tatlong segundo.","h2":"Itinuturo ng Wisconsin ang apat na segundong following distance, at magdagdag ng isa pang segundo sa bawat masamang kondisyon tulad ng ulan, niyebe, yelo o mabigat na trapiko.","p":"Tama. Manatili nang hindi bababa sa apat na segundo sa likod ng sasakyan sa unahan."},"ar":{"q":"في Wisconsin، كم ثانية من مسافة المتابعة يطلب منك الدليل أن تحافظ عليها في الظروف الجيدة؟","o":["ثانية واحدة","ثانيتان","4 ثوانٍ","8 ثوانٍ"],"h1":"هي أكثر من ثلاث ثوانٍ.","h2":"تعلّم Wisconsin مسافة متابعة أربع ثوانٍ، وتضيف ثانية أخرى لكل ظرف سيئ مثل المطر أو الثلج أو الجليد أو الزحام الشديد.","p":"صحيح. ابقَ أربع ثوانٍ على الأقل خلف السيارة التي أمامك."},"ref":{"doc":"WI","page":10}},{"id":"wi-024","scope":"WI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Wisconsin, you must turn on your headlights when you cannot see a person or vehicle how far away?","o":["500 feet","100 feet","1,000 feet","200 feet"],"h1":"It is about one city block.","h2":"In Wisconsin, you must use your headlights when you cannot see a person or vehicle 500 feet away, and from a half hour after sunset to a half hour before sunrise.","p":"Right. If you cannot see 500 feet ahead, turn your headlights on."},"es":{"q":"En Wisconsin, usted debe encender las luces delanteras cuando no puede ver a una persona o un vehículo ¿a qué distancia?","o":["500 pies","100 pies","1,000 pies","200 pies"],"h1":"Es más o menos una cuadra de la ciudad.","h2":"En Wisconsin, usted debe usar las luces delanteras cuando no puede ver a una persona o un vehículo a 500 pies, y desde media hora después de la puesta del sol hasta media hora antes del amanecer.","p":"Correcto. Si no puede ver a 500 pies, encienda las luces delanteras."},"zh":{"q":"在 Wisconsin，当你看不到多远之外的人或车辆时，必须打开前大灯？","o":["500 英尺","100 英尺","1,000 英尺","200 英尺"],"h1":"大约是城市里一个街区的长度。","h2":"在 Wisconsin，当你看不到 500 英尺外的人或车辆时，以及从日落后半小时到日出前半小时，你必须打开前大灯。","p":"对。如果看不到前面 500 英尺，就打开前大灯。"},"vi":{"q":"Ở Wisconsin, bạn phải bật đèn pha khi không thể nhìn thấy người hoặc xe ở cách bao xa?","o":["500 feet","100 feet","1,000 feet","200 feet"],"h1":"Khoảng một dãy phố trong thành phố.","h2":"Ở Wisconsin, bạn phải bật đèn pha khi không thể nhìn thấy người hoặc xe ở cách 500 feet, và từ nửa giờ sau khi mặt trời lặn đến nửa giờ trước khi mặt trời mọc.","p":"Đúng. Nếu không nhìn thấy 500 feet phía trước, hãy bật đèn pha."},"tl":{"q":"Sa Wisconsin, dapat mong buksan ang headlights kapag hindi mo makita ang tao o sasakyan sa gaano kalayo?","o":["500 feet","100 feet","1,000 feet","200 feet"],"h1":"Mga isang block sa lungsod ito.","h2":"Sa Wisconsin, dapat mong gamitin ang headlights kapag hindi mo makita ang tao o sasakyan na 500 feet ang layo, at mula kalahating oras pagkalubog ng araw hanggang kalahating oras bago sumikat ang araw.","p":"Tama. Kung hindi mo makita ang 500 feet sa unahan, buksan ang headlights."},"ar":{"q":"في Wisconsin، يجب أن تشغّل المصابيح الأمامية عندما لا ترى شخصًا أو سيارة على أي مسافة؟","o":["500 قدم","100 قدم","1,000 قدم","200 قدم"],"h1":"هي تقريبًا طول مربع سكني واحد في المدينة.","h2":"في Wisconsin يجب أن تستعمل المصابيح الأمامية عندما لا ترى شخصًا أو سيارة على بعد 500 قدم، ومن نصف ساعة بعد غروب الشمس إلى نصف ساعة قبل شروقها.","p":"صحيح. إذا لم ترَ 500 قدم أمامك، شغّل المصابيح الأمامية."},"ref":{"doc":"WI","page":21}},{"id":"wi-025","scope":"WI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wisconsin, how much room should you give a snowplow that has its lights flashing?","o":["At least 20 feet","At least 50 feet","At least 100 feet","At least 200 feet"],"h1":"Snowplows throw snow and stop often, so give them a lot of space.","h2":"In Wisconsin, you should stay at least 200 feet away from a snowplow when its red, amber or green lights are flashing.","p":"Right. Give a working snowplow at least 200 feet."},"es":{"q":"En Wisconsin, ¿cuánto espacio debe dejarle a una máquina quitanieves que tiene sus luces intermitentes?","o":["Al menos 20 pies","Al menos 50 pies","Al menos 100 pies","Al menos 200 pies"],"h1":"Las quitanieves tiran nieve y se detienen a menudo, así que deles mucho espacio.","h2":"En Wisconsin, usted debe mantenerse al menos a 200 pies de una quitanieves cuando sus luces rojas, ámbar o verdes están intermitentes.","p":"Correcto. Deje al menos 200 pies a una quitanieves trabajando."},"zh":{"q":"在 Wisconsin，对一辆灯在闪的扫雪车，你应该留出多少距离？","o":["至少 20 英尺","至少 50 英尺","至少 100 英尺","至少 200 英尺"],"h1":"扫雪车会把雪甩出来，还经常停车，所以要给它们很多空间。","h2":"在 Wisconsin，当扫雪车的红灯、琥珀色灯或绿灯在闪时，你应该离它至少 200 英尺。","p":"对。和正在工作的扫雪车保持至少 200 英尺。"},"vi":{"q":"Ở Wisconsin, bạn nên chừa khoảng cách bao nhiêu với xe ủi tuyết đang nhấp nháy đèn?","o":["Ít nhất 20 feet","Ít nhất 50 feet","Ít nhất 100 feet","Ít nhất 200 feet"],"h1":"Xe ủi tuyết hất tuyết ra và thường dừng lại, nên hãy chừa nhiều khoảng trống.","h2":"Ở Wisconsin, bạn nên cách xe ủi tuyết ít nhất 200 feet khi đèn đỏ, đèn vàng hổ phách hoặc đèn xanh của nó đang nhấp nháy.","p":"Đúng. Giữ cách xe ủi tuyết đang làm việc ít nhất 200 feet."},"tl":{"q":"Sa Wisconsin, gaano kalaking espasyo ang dapat mong ibigay sa snowplow na kumikislap ang ilaw?","o":["Hindi bababa sa 20 feet","Hindi bababa sa 50 feet","Hindi bababa sa 100 feet","Hindi bababa sa 200 feet"],"h1":"Nagtatapon ng niyebe ang snowplow at madalas huminto, kaya bigyan sila ng maraming espasyo.","h2":"Sa Wisconsin, dapat kang manatili nang hindi bababa sa 200 feet mula sa snowplow kapag kumikislap ang pula, amber o berdeng ilaw nito.","p":"Tama. Bigyan ang gumaganang snowplow ng hindi bababa sa 200 feet."},"ar":{"q":"في Wisconsin، ما المسافة التي يجب أن تتركها لكاسحة الثلج التي تومض أضواؤها؟","o":["20 قدمًا على الأقل","50 قدمًا على الأقل","100 قدم على الأقل","200 قدم على الأقل"],"h1":"كاسحات الثلج ترمي الثلج وتتوقف كثيرًا، فاترك لها مسافة كبيرة.","h2":"في Wisconsin يجب أن تبقى على بعد 200 قدم على الأقل من كاسحة الثلج عندما تومض أضواؤها الحمراء أو الكهرمانية أو الخضراء.","p":"صحيح. اترك لكاسحة الثلج التي تعمل 200 قدم على الأقل."},"ref":{"doc":"WI","page":45}},{"id":"wi-026","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, what happens if you refuse a police officer's request to take a breath or blood alcohol test?","o":["You get a warning the first time","You lose your driving privilege for at least one year","You lose your license for 30 days","You pay a small fine and keep driving"],"h1":"This is the Implied Consent Law, and the penalty is long.","h2":"In Wisconsin, if you refuse the alcohol test, you are arrested under the Implied Consent Law and lose your driving privilege for at least one year.","p":"Right. Refusing the test costs you at least one year of driving."},"es":{"q":"En Wisconsin, ¿qué pasa si usted se niega cuando un policía le pide una prueba de alcohol de aliento o de sangre?","o":["Recibe una advertencia la primera vez","Pierde su privilegio de manejar por al menos un año","Pierde su licencia por 30 días","Paga una multa pequeña y sigue manejando"],"h1":"Es la Ley de Consentimiento Implícito, y la sanción es larga.","h2":"En Wisconsin, si usted se niega a la prueba de alcohol, lo arrestan bajo la Ley de Consentimiento Implícito y pierde su privilegio de manejar por al menos un año.","p":"Correcto. Negarse a la prueba le cuesta al menos un año sin manejar."},"zh":{"q":"在 Wisconsin，如果你拒绝警察要求你做呼气或血液酒精测试，会怎样？","o":["第一次只会得到警告","你至少一年失去驾驶资格","你的驾照被吊销 30 天","你交一点罚款，可以继续开车"],"h1":"这是默示同意法（Implied Consent Law），处罚时间很长。","h2":"在 Wisconsin，如果你拒绝酒精测试，你会根据默示同意法被逮捕，并且至少一年失去驾驶资格。","p":"对。拒绝测试会让你至少一年不能开车。"},"vi":{"q":"Ở Wisconsin, điều gì xảy ra nếu bạn từ chối yêu cầu của cảnh sát làm xét nghiệm nồng độ cồn qua hơi thở hoặc máu?","o":["Lần đầu bạn chỉ bị cảnh cáo","Bạn mất quyền lái xe ít nhất một năm","Bạn bị mất bằng lái 30 ngày","Bạn trả một khoản phạt nhỏ và tiếp tục lái xe"],"h1":"Đây là Luật Đồng Ý Ngầm (Implied Consent Law), và hình phạt kéo dài.","h2":"Ở Wisconsin, nếu bạn từ chối xét nghiệm nồng độ cồn, bạn bị bắt theo Luật Đồng Ý Ngầm và mất quyền lái xe ít nhất một năm.","p":"Đúng. Từ chối xét nghiệm làm bạn mất quyền lái xe ít nhất một năm."},"tl":{"q":"Sa Wisconsin, ano ang mangyayari kung tatanggihan mo ang hiling ng pulis na magpa-breath o blood alcohol test?","o":["Babala lang sa unang beses","Mawawala ang pribilehiyo mong magmaneho nang hindi bababa sa isang taon","Mawawala ang lisensya mo nang 30 araw","Magbabayad ka ng maliit na multa at patuloy na magmamaneho"],"h1":"Ito ang Implied Consent Law, at mahaba ang parusa.","h2":"Sa Wisconsin, kapag tumanggi ka sa alcohol test, aarestuhin ka sa ilalim ng Implied Consent Law at mawawala ang pribilehiyo mong magmaneho nang hindi bababa sa isang taon.","p":"Tama. Ang pagtanggi sa test ay nagpapawala sa iyo ng pagmamaneho nang hindi bababa sa isang taon."},"ar":{"q":"في Wisconsin، ماذا يحدث إذا رفضت طلب الشرطي أن تجري اختبار الكحول بالنفس أو بالدم؟","o":["تحصل على تحذير في المرة الأولى","تفقد حق القيادة لمدة سنة على الأقل","تفقد رخصتك لمدة 30 يومًا","تدفع غرامة صغيرة وتستمر في القيادة"],"h1":"هذا هو قانون الموافقة الضمنية (Implied Consent Law)، والعقوبة طويلة.","h2":"في Wisconsin، إذا رفضت اختبار الكحول، يتم القبض عليك بموجب قانون الموافقة الضمنية وتفقد حق القيادة لمدة سنة على الأقل.","p":"صحيح. رفض الاختبار يكلفك سنة على الأقل بدون قيادة."},"ref":{"doc":"WI","page":49}},{"id":"wi-027","scope":"WI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wisconsin, until what age does a child generally need to ride in a booster seat?","o":["Age 4","Age 6","Age 8","Age 12"],"h1":"Children usually leave the car seat at 4, and the booster comes after that.","h2":"In Wisconsin, children generally ride in a child safety seat until age four and then in a booster seat until age eight.","p":"Right. A booster seat until age eight."},"es":{"q":"En Wisconsin, ¿hasta qué edad un niño generalmente debe viajar en un asiento elevador (booster)?","o":["4 años","6 años","8 años","12 años"],"h1":"Los niños suelen dejar el asiento de seguridad a los 4, y el elevador viene después.","h2":"En Wisconsin, los niños generalmente viajan en un asiento de seguridad hasta los cuatro años y luego en un asiento elevador hasta los ocho años.","p":"Correcto. Asiento elevador hasta los ocho años."},"zh":{"q":"在 Wisconsin，孩子一般要坐加高座椅（booster seat）到几岁？","o":["4 岁","6 岁","8 岁","12 岁"],"h1":"孩子通常在 4 岁离开儿童安全座椅，之后用加高座椅。","h2":"在 Wisconsin，孩子一般坐儿童安全座椅到四岁，然后坐加高座椅到八岁。","p":"对。坐加高座椅到八岁。"},"vi":{"q":"Ở Wisconsin, trẻ em thường phải ngồi ghế nâng (booster seat) đến bao nhiêu tuổi?","o":["4 tuổi","6 tuổi","8 tuổi","12 tuổi"],"h1":"Trẻ em thường rời ghế an toàn lúc 4 tuổi, và ghế nâng là bước tiếp theo.","h2":"Ở Wisconsin, trẻ em thường ngồi ghế an toàn trẻ em đến bốn tuổi và sau đó ngồi ghế nâng đến tám tuổi.","p":"Đúng. Ngồi ghế nâng đến tám tuổi."},"tl":{"q":"Sa Wisconsin, hanggang ilang taon karaniwang kailangang sumakay ang bata sa booster seat?","o":["Edad 4","Edad 6","Edad 8","Edad 12"],"h1":"Karaniwang umaalis ang bata sa car seat sa edad na 4, at booster seat ang kasunod.","h2":"Sa Wisconsin, karaniwang sumasakay ang bata sa child safety seat hanggang edad apat at pagkatapos ay sa booster seat hanggang edad walo.","p":"Tama. Booster seat hanggang edad walo."},"ar":{"q":"في Wisconsin، حتى أي عمر يجب عادةً أن يجلس الطفل في مقعد رافع (booster seat)؟","o":["عمر 4","عمر 6","عمر 8","عمر 12"],"h1":"يترك الأطفال عادةً مقعد السيارة في عمر 4، والمقعد الرافع يأتي بعد ذلك.","h2":"في Wisconsin، يجلس الأطفال عادةً في مقعد أمان للأطفال حتى عمر أربع سنوات، ثم في مقعد رافع حتى عمر ثماني سنوات.","p":"صحيح. مقعد رافع حتى عمر ثماني سنوات."},"ref":{"doc":"WI","page":55}},{"id":"wi-028","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, how often must you renew a regular driver license?","o":["Every 4 years","Every 8 years","Every 10 years","Every 2 years"],"h1":"It is a long time, but less than ten years.","h2":"In Wisconsin, a regular driver license must be renewed every eight years.","p":"Right. A regular license is renewed every eight years."},"es":{"q":"En Wisconsin, ¿cada cuánto debe renovar una licencia de conducir regular?","o":["Cada 4 años","Cada 8 años","Cada 10 años","Cada 2 años"],"h1":"Es mucho tiempo, pero menos de diez años.","h2":"En Wisconsin, una licencia de conducir regular se debe renovar cada ocho años.","p":"Correcto. La licencia regular se renueva cada ocho años."},"zh":{"q":"在 Wisconsin，普通驾照多久必须更新一次？","o":["每 4 年","每 8 年","每 10 年","每 2 年"],"h1":"时间很长，但不到十年。","h2":"在 Wisconsin，普通驾照必须每 8 年更新一次。","p":"对。普通驾照每 8 年更新一次。"},"vi":{"q":"Ở Wisconsin, bằng lái thường phải gia hạn bao lâu một lần?","o":["Mỗi 4 năm","Mỗi 8 năm","Mỗi 10 năm","Mỗi 2 năm"],"h1":"Đó là một thời gian dài, nhưng ít hơn mười năm.","h2":"Ở Wisconsin, bằng lái thường phải được gia hạn mỗi 8 năm.","p":"Đúng. Bằng lái thường được gia hạn mỗi 8 năm."},"tl":{"q":"Sa Wisconsin, gaano kadalas mo dapat i-renew ang regular na driver license?","o":["Tuwing 4 na taon","Tuwing 8 taon","Tuwing 10 taon","Tuwing 2 taon"],"h1":"Matagal ito, pero mas maikli sa sampung taon.","h2":"Sa Wisconsin, ang regular na driver license ay dapat i-renew tuwing 8 taon.","p":"Tama. Ang regular na license ay nire-renew tuwing 8 taon."},"ar":{"q":"في Wisconsin، كل كم سنة يجب أن تجدد رخصة القيادة العادية؟","o":["كل 4 سنوات","كل 8 سنوات","كل 10 سنوات","كل سنتين (2)"],"h1":"هي مدة طويلة، لكنها أقل من عشر سنوات.","h2":"في Wisconsin، يجب تجديد رخصة القيادة العادية كل 8 سنوات.","p":"صحيح. تُجدَّد الرخصة العادية كل 8 سنوات."},"ref":{"doc":"WI","page":7}},{"id":"wi-029","scope":"WI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Wisconsin, a person with a guide dog or a white cane is crossing the road. How far away must you stop?","o":["At least 3 feet","At least 5 feet","At least 10 feet","At least 50 feet"],"h1":"Give the person a lot of room, more than one car door's width.","h2":"In Wisconsin, you must stop at least 10 feet away until a person with a guide dog or white cane is off the road.","p":"Right. Stop at least 10 feet away and wait until the person is off the road."},"es":{"q":"En Wisconsin, una persona con un perro guía o un bastón blanco está cruzando la calle. ¿A qué distancia debe detenerse usted?","o":["Por lo menos a 3 pies","Por lo menos a 5 pies","Por lo menos a 10 pies","Por lo menos a 50 pies"],"h1":"Dele mucho espacio a la persona, más que el ancho de una puerta de carro.","h2":"En Wisconsin, usted debe detenerse por lo menos a 10 pies hasta que la persona con perro guía o bastón blanco salga de la calle.","p":"Correcto. Deténgase por lo menos a 10 pies y espere a que la persona salga de la calle."},"zh":{"q":"在 Wisconsin，一个带导盲犬或白手杖的人正在过马路。你必须在多远的地方停车？","o":["至少 3 英尺","至少 5 英尺","至少 10 英尺","至少 50 英尺"],"h1":"给这个人留出很大的空间，比一扇车门还宽。","h2":"在 Wisconsin，你必须在至少 10 英尺外停车，直到带导盲犬或白手杖的人离开道路。","p":"对。在至少 10 英尺外停车，等这个人离开道路。"},"vi":{"q":"Ở Wisconsin, một người có chó dẫn đường hoặc gậy trắng đang băng qua đường. Bạn phải dừng xe cách bao xa?","o":["Ít nhất 3 feet","Ít nhất 5 feet","Ít nhất 10 feet","Ít nhất 50 feet"],"h1":"Hãy chừa cho người đó nhiều chỗ, rộng hơn một cánh cửa xe.","h2":"Ở Wisconsin, bạn phải dừng xe cách ít nhất 10 feet cho đến khi người có chó dẫn đường hoặc gậy trắng ra khỏi đường.","p":"Đúng. Dừng xe cách ít nhất 10 feet và chờ đến khi người đó ra khỏi đường."},"tl":{"q":"Sa Wisconsin, may taong may guide dog o puting tungkod na tumatawid sa kalsada. Gaano kalayo ka dapat huminto?","o":["Hindi bababa sa 3 feet","Hindi bababa sa 5 feet","Hindi bababa sa 10 feet","Hindi bababa sa 50 feet"],"h1":"Bigyan ng malaking espasyo ang tao, mas malapad pa sa isang pinto ng kotse.","h2":"Sa Wisconsin, dapat kang huminto nang hindi bababa sa 10 feet ang layo hanggang makaalis sa kalsada ang taong may guide dog o puting tungkod.","p":"Tama. Huminto nang hindi bababa sa 10 feet ang layo at maghintay hanggang makaalis ang tao sa kalsada."},"ar":{"q":"في Wisconsin، شخص معه كلب مرشد أو عصا بيضاء يعبر الطريق. على أي مسافة يجب أن تتوقف؟","o":["3 أقدام على الأقل","5 أقدام على الأقل","10 أقدام على الأقل","50 قدمًا على الأقل"],"h1":"اترك للشخص مساحة كبيرة، أكثر من عرض باب سيارة واحد.","h2":"في Wisconsin، يجب أن تتوقف على بعد 10 أقدام على الأقل حتى يخرج الشخص الذي معه كلب مرشد أو عصا بيضاء من الطريق.","p":"صحيح. توقف على بعد 10 أقدام على الأقل وانتظر حتى يخرج الشخص من الطريق."},"ref":{"doc":"WI","page":9}},{"id":"wi-030","scope":"WI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wisconsin, how much room must you give a bicyclist when you pass?","o":["At least 3 feet","At least 1 foot","At least 2 feet","At least 10 feet"],"h1":"It is about the length of a yardstick.","h2":"In Wisconsin, you must give a bicyclist at least three feet of room when you pass.","p":"Right. Give bicyclists at least three feet when you pass."},"es":{"q":"En Wisconsin, ¿cuánto espacio debe dar a un ciclista cuando lo rebasa?","o":["Por lo menos 3 pies","Por lo menos 1 pie","Por lo menos 2 pies","Por lo menos 10 pies"],"h1":"Es más o menos un metro.","h2":"En Wisconsin, usted debe dar a un ciclista por lo menos tres pies de espacio cuando lo rebasa.","p":"Correcto. Dé por lo menos tres pies a los ciclistas al rebasarlos."},"zh":{"q":"在 Wisconsin，超过骑自行车的人时，你必须留出多少空间？","o":["至少 3 英尺","至少 1 英尺","至少 2 英尺","至少 10 英尺"],"h1":"大约是一把码尺的长度。","h2":"在 Wisconsin，超过骑自行车的人时，你必须留出至少 3 英尺的空间。","p":"对。超过骑自行车的人时，至少留出 3 英尺。"},"vi":{"q":"Ở Wisconsin, khi vượt người đi xe đạp, bạn phải chừa bao nhiêu khoảng trống?","o":["Ít nhất 3 feet","Ít nhất 1 foot","Ít nhất 2 feet","Ít nhất 10 feet"],"h1":"Khoảng bằng chiều dài một cây thước yard.","h2":"Ở Wisconsin, khi vượt người đi xe đạp, bạn phải chừa ít nhất 3 feet khoảng trống.","p":"Đúng. Chừa ít nhất 3 feet khi vượt người đi xe đạp."},"tl":{"q":"Sa Wisconsin, gaano kalaking espasyo ang dapat mong ibigay sa nagbibisikleta kapag lumalampas ka?","o":["Hindi bababa sa 3 feet","Hindi bababa sa 1 foot","Hindi bababa sa 2 feet","Hindi bababa sa 10 feet"],"h1":"Mga kasinghaba ito ng isang yardstick.","h2":"Sa Wisconsin, dapat kang magbigay ng hindi bababa sa 3 feet na espasyo sa nagbibisikleta kapag lumalampas ka.","p":"Tama. Magbigay ng hindi bababa sa 3 feet sa mga nagbibisikleta kapag lumalampas ka."},"ar":{"q":"في Wisconsin، كم مسافة يجب أن تترك لراكب الدراجة عندما تتجاوزه؟","o":["3 أقدام على الأقل","قدم واحدة (1) على الأقل","قدمان (2) على الأقل","10 أقدام على الأقل"],"h1":"هي تقريبًا طول مسطرة الياردة.","h2":"في Wisconsin، يجب أن تترك لراكب الدراجة مسافة 3 أقدام على الأقل عندما تتجاوزه.","p":"صحيح. اترك لراكبي الدراجات 3 أقدام على الأقل عندما تتجاوزهم."},"ref":{"doc":"WI","page":52}},{"id":"wi-031","scope":"WI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wisconsin, what must the vehicles in a funeral procession have turned on?","o":["Hazard lights only","Turn signals","Interior lights","Headlights"],"h1":"These lights help other drivers see that the cars are traveling together.","h2":"In Wisconsin, vehicles in a funeral procession must have their headlights on, and you must not cut into the line.","p":"Right. Cars in a funeral procession drive with headlights on."},"es":{"q":"En Wisconsin, ¿qué deben tener encendido los vehículos de un cortejo fúnebre?","o":["Solo las luces intermitentes","Las direccionales","Las luces interiores","Los faros delanteros"],"h1":"Estas luces ayudan a otros conductores a ver que los carros van juntos.","h2":"En Wisconsin, los vehículos de un cortejo fúnebre deben llevar los faros delanteros encendidos, y usted no debe meterse en la fila.","p":"Correcto. Los carros de un cortejo fúnebre van con los faros delanteros encendidos."},"zh":{"q":"在 Wisconsin，送葬车队中的车辆必须打开什么？","o":["只开危险警示灯","转向灯","车内灯","前大灯"],"h1":"这些灯帮助其他司机看出这些车是一起行驶的。","h2":"在 Wisconsin，送葬车队中的车辆必须打开前大灯，而且你不能插进车队。","p":"对。送葬车队中的车辆开着前大灯行驶。"},"vi":{"q":"Ở Wisconsin, các xe trong đoàn xe tang phải bật gì?","o":["Chỉ đèn khẩn cấp","Đèn xi nhan","Đèn trong xe","Đèn pha"],"h1":"Những đèn này giúp các tài xế khác thấy rằng các xe đang đi cùng nhau.","h2":"Ở Wisconsin, các xe trong đoàn xe tang phải bật đèn pha, và bạn không được chen vào đoàn xe.","p":"Đúng. Các xe trong đoàn xe tang chạy với đèn pha bật."},"tl":{"q":"Sa Wisconsin, ano ang dapat nakabukas sa mga sasakyan sa isang funeral procession?","o":["Hazard lights lang","Turn signals","Mga ilaw sa loob","Headlights"],"h1":"Tinutulungan ng mga ilaw na ito ang ibang driver na makita na magkakasamang bumibiyahe ang mga kotse.","h2":"Sa Wisconsin, ang mga sasakyan sa funeral procession ay dapat nakabukas ang headlights, at hindi ka dapat sumingit sa hanay.","p":"Tama. Nakabukas ang headlights ng mga kotse sa funeral procession."},"ar":{"q":"في Wisconsin، ماذا يجب أن تشغّل السيارات في موكب الجنازة؟","o":["أضواء التحذير فقط","إشارات الانعطاف","الأضواء الداخلية","المصابيح الأمامية"],"h1":"هذه الأضواء تساعد السائقين الآخرين على رؤية أن السيارات تسير معًا.","h2":"في Wisconsin، يجب أن تشغّل السيارات في موكب الجنازة المصابيح الأمامية، ولا يجوز لك أن تدخل بين سيارات الموكب.","p":"صحيح. تسير سيارات موكب الجنازة والمصابيح الأمامية مضاءة."},"ref":{"doc":"WI","page":43}},{"id":"wv-001","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, what is the youngest age for a Level 1 instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before the Level 2 license.","h2":"In West Virginia you can get a Level 1 instruction permit at 15.","p":"Right. Level 1 starts at 15."},"es":{"q":"En Virginia Occidental, ¿cuál es la edad mínima para el permiso de instrucción de Nivel 1?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la licencia de Nivel 2.","h2":"En Virginia Occidental usted puede obtener el permiso de instrucción de Nivel 1 a los 15 años.","p":"Correcto. El Nivel 1 empieza a los 15."},"zh":{"q":"在 West Virginia，最小几岁可以拿到第 1 级学习驾照（Level 1 instruction permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比第 2 级驾照早一年。","h2":"在 West Virginia，你 15 岁就可以拿到第 1 级学习驾照。","p":"对。第 1 级从 15 岁开始。"},"vi":{"q":"Ở West Virginia, tuổi nhỏ nhất để có giấy phép tập lái Cấp 1 (Level 1 instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Sớm hơn một năm so với bằng lái Cấp 2.","h2":"Ở West Virginia, bạn có thể có giấy phép tập lái Cấp 1 khi 15 tuổi.","p":"Đúng. Cấp 1 bắt đầu từ 15 tuổi."},"tl":{"q":"Sa West Virginia, ano ang pinakabatang edad para sa Level 1 na instruction permit (Level 1 instruction permit)?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ang Level 2 na lisensya.","h2":"Sa West Virginia, puwede kang kumuha ng Level 1 na instruction permit sa edad na 15.","p":"Tama. Nagsisimula ang Level 1 sa 15."},"ar":{"q":"في West Virginia، ما أصغر عمر للحصول على تصريح التعلّم من المستوى 1 (Level 1 instruction permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"إنه قبل رخصة المستوى 2 بسنة واحدة.","h2":"في West Virginia يمكنك الحصول على تصريح التعلّم من المستوى 1 في عمر 15 سنة.","p":"صحيح. المستوى 1 يبدأ في عمر 15 سنة."},"ref":{"doc":"WV","page":9}},{"id":"wv-002","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, who must sign the permit application of someone under 18?","o":["A school principal","Any adult friend","A parent or legal guardian","Nobody, the teen signs alone"],"h1":"It is the adult responsible for the teen.","h2":"In West Virginia a parent or legal guardian must sign the application of an applicant under 18 before testing.","p":"Correct. A parent or guardian signs."},"es":{"q":"En Virginia Occidental, ¿quién debe firmar la solicitud de permiso de un menor de 18 años?","o":["El director de la escuela","Cualquier amigo adulto","Un padre o tutor legal","Nadie, el joven firma solo"],"h1":"Es el adulto responsable del joven.","h2":"En Virginia Occidental, un padre o tutor legal debe firmar la solicitud de un menor de 18 años antes del examen.","p":"Correcto. Firma un padre o tutor."},"zh":{"q":"在 West Virginia，未满 18 岁的人申请学习驾照时，谁必须在申请表上签字？","o":["学校校长","任何成年朋友","父母或法定监护人","不需要别人，青少年自己签字"],"h1":"是对这个青少年负责的大人。","h2":"在 West Virginia，未满 18 岁的申请人考试前，必须由父母或法定监护人在申请表上签字。","p":"正确。由父母或监护人签字。"},"vi":{"q":"Ở West Virginia, ai phải ký đơn xin giấy phép tập lái của người dưới 18 tuổi?","o":["Hiệu trưởng trường học","Bất kỳ người bạn lớn tuổi nào","Cha mẹ hoặc người giám hộ hợp pháp","Không ai cả, thiếu niên tự ký"],"h1":"Đó là người lớn chịu trách nhiệm về thiếu niên đó.","h2":"Ở West Virginia, cha mẹ hoặc người giám hộ hợp pháp phải ký đơn của người dưới 18 tuổi trước khi thi.","p":"Đúng. Cha mẹ hoặc người giám hộ ký."},"tl":{"q":"Sa West Virginia, sino ang dapat pumirma sa aplikasyon para sa permit ng taong wala pang 18?","o":["Isang punong-guro ng paaralan","Kahit sinong kaibigang adulto","Isang magulang o legal na tagapag-alaga","Wala, ang tinedyer ang pipirma nang mag-isa"],"h1":"Ito ang adultong may pananagutan sa tinedyer.","h2":"Sa West Virginia, dapat pumirma ang isang magulang o legal na tagapag-alaga sa aplikasyon ng aplikanteng wala pang 18 bago ang pagsusulit.","p":"Tama. Magulang o tagapag-alaga ang pipirma."},"ar":{"q":"في West Virginia، من يجب أن يوقّع طلب التصريح لشخص عمره أقل من 18 سنة؟","o":["مدير المدرسة","أي صديق بالغ","أحد الوالدين أو الوصي القانوني","لا أحد، المراهق يوقّع وحده"],"h1":"إنه الشخص البالغ المسؤول عن المراهق.","h2":"في West Virginia يجب أن يوقّع أحد الوالدين أو الوصي القانوني على طلب المتقدّم الذي عمره أقل من 18 سنة قبل الاختبار.","p":"صحيح. أحد الوالدين أو الوصي يوقّع."},"ref":{"doc":"WV","page":9}},{"id":"wv-003","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, how old must the licensed driver supervising a Level 1 permit holder be?","o":["16 or older","18 or older","25 or older","21 or older"],"h1":"The supervisor must be old enough to drink legally.","h2":"In West Virginia a Level 1 permit holder must be supervised by a licensed driver who is 21 or older, or by a driving instructor.","p":"Right. The supervisor must be 21 or older."},"es":{"q":"En Virginia Occidental, ¿qué edad debe tener el conductor con licencia que supervisa a quien tiene permiso de Nivel 1?","o":["16 años o más","18 años o más","25 años o más","21 años o más"],"h1":"El supervisor debe tener edad para tomar alcohol legalmente.","h2":"En Virginia Occidental, quien tiene permiso de Nivel 1 debe ir supervisado por un conductor con licencia de 21 años o más, o por un instructor de manejo.","p":"Correcto. El supervisor debe tener 21 años o más."},"zh":{"q":"在 West Virginia，陪同第 1 级学习驾照持有人开车的有照司机必须几岁以上？","o":["16 岁或以上","18 岁或以上","25 岁或以上","21 岁或以上"],"h1":"陪同的人必须到了可以合法喝酒的年龄。","h2":"在 West Virginia，第 1 级学习驾照持有人开车时，必须有 21 岁或以上的有照司机或驾驶教练陪同。","p":"对。陪同的人必须 21 岁或以上。"},"vi":{"q":"Ở West Virginia, người có bằng lái đi kèm người có giấy phép tập lái Cấp 1 phải bao nhiêu tuổi?","o":["16 tuổi trở lên","18 tuổi trở lên","25 tuổi trở lên","21 tuổi trở lên"],"h1":"Người đi kèm phải đủ tuổi uống rượu hợp pháp.","h2":"Ở West Virginia, người có giấy phép tập lái Cấp 1 phải có một người lái xe có bằng từ 21 tuổi trở lên, hoặc một giáo viên dạy lái xe, đi kèm.","p":"Đúng. Người đi kèm phải từ 21 tuổi trở lên."},"tl":{"q":"Sa West Virginia, ilang taon dapat ang may lisensyang drayber na nagbabantay sa may hawak ng Level 1 na permit?","o":["16 o higit pa","18 o higit pa","25 o higit pa","21 o higit pa"],"h1":"Dapat nasa edad na ang nagbabantay para legal na uminom ng alak.","h2":"Sa West Virginia, ang may hawak ng Level 1 na permit ay dapat bantayan ng may lisensyang drayber na 21 o higit pa, o ng isang driving instructor.","p":"Tama. Dapat 21 o higit pa ang nagbabantay."},"ar":{"q":"في West Virginia، كم يجب أن يكون عمر السائق المرخّص الذي يرافق حامل تصريح المستوى 1؟","o":["16 سنة أو أكثر","18 سنة أو أكثر","25 سنة أو أكثر","21 سنة أو أكثر"],"h1":"يجب أن يكون المرافق في عمر يسمح له قانونيًا بشرب الكحول.","h2":"في West Virginia يجب أن يرافق حاملَ تصريح المستوى 1 سائقٌ مرخّص عمره 21 سنة أو أكثر، أو مدرّب قيادة.","p":"صحيح. يجب أن يكون عمر المرافق 21 سنة أو أكثر."},"ref":{"doc":"WV","page":9}},{"id":"wv-004","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, who else may sit in the front seat while a Level 1 permit holder drives?","o":["Only the supervising driver","Any friend","A younger brother or sister","Nobody may sit in front"],"h1":"The front seat is for the person in charge of the lesson.","h2":"In West Virginia the supervising driver must be the only other person in the front seat while a Level 1 permit holder drives.","p":"Correct. Only the supervisor sits in front."},"es":{"q":"En Virginia Occidental, ¿quién más puede ir en el asiento delantero mientras maneja alguien con permiso de Nivel 1?","o":["Solo el conductor que supervisa","Cualquier amigo","Un hermano menor","Nadie puede ir adelante"],"h1":"El asiento delantero es para quien está a cargo de la práctica.","h2":"En Virginia Occidental, el conductor que supervisa debe ser la única otra persona en el asiento delantero mientras maneja alguien con permiso de Nivel 1.","p":"Correcto. Solo el supervisor va adelante."},"zh":{"q":"在 West Virginia，第 1 级学习驾照持有人开车时，前排还可以坐谁？","o":["只有陪同的司机","任何朋友","弟弟或妹妹","前排不能坐任何人"],"h1":"前排座位是给负责这次练习的人坐的。","h2":"在 West Virginia，第 1 级学习驾照持有人开车时，前排除了司机只能坐陪同的司机。","p":"正确。前排只能坐陪同的人。"},"vi":{"q":"Ở West Virginia, khi người có giấy phép tập lái Cấp 1 lái xe, ai khác được ngồi ở ghế trước?","o":["Chỉ người lái xe đi kèm","Bất kỳ người bạn nào","Em trai hoặc em gái","Không ai được ngồi ở ghế trước"],"h1":"Ghế trước dành cho người phụ trách buổi tập.","h2":"Ở West Virginia, khi người có giấy phép tập lái Cấp 1 lái xe, người lái xe đi kèm phải là người duy nhất khác ngồi ở ghế trước.","p":"Đúng. Chỉ người đi kèm ngồi ở ghế trước."},"tl":{"q":"Sa West Virginia, sino pa ang puwedeng umupo sa harap habang nagmamaneho ang may hawak ng Level 1 na permit?","o":["Ang nagbabantay na drayber lamang","Kahit sinong kaibigan","Isang nakababatang kapatid","Walang puwedeng umupo sa harap"],"h1":"Ang upuan sa harap ay para sa taong namamahala sa aralin.","h2":"Sa West Virginia, ang nagbabantay na drayber lamang ang puwedeng ibang tao sa upuan sa harap habang nagmamaneho ang may hawak ng Level 1 na permit.","p":"Tama. Ang nagbabantay lamang ang uupo sa harap."},"ar":{"q":"في West Virginia، من غير السائق يمكنه الجلوس في المقعد الأمامي عندما يقود حامل تصريح المستوى 1؟","o":["السائق المرافق فقط","أي صديق","أخ أو أخت أصغر","لا يجوز لأحد الجلوس في الأمام"],"h1":"المقعد الأمامي للشخص المسؤول عن الدرس.","h2":"في West Virginia يجب أن يكون السائق المرافق هو الشخص الوحيد الآخر في المقعد الأمامي عندما يقود حامل تصريح المستوى 1.","p":"صحيح. المرافق فقط يجلس في الأمام."},"ref":{"doc":"WV","page":null}},{"id":"wv-005","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, during which hours may a Level 1 permit holder drive?","o":["Between 6 a.m. and 9 p.m.","Between 5 a.m. and 10 p.m.","Between 5 a.m. and midnight","At any hour with a supervisor"],"h1":"The window ends in the late evening, before midnight.","h2":"In West Virginia a Level 1 permit holder may drive only between 5 a.m. and 10 p.m.","p":"Right. Level 1 driving is from 5 a.m. to 10 p.m."},"es":{"q":"En Virginia Occidental, ¿en qué horario puede manejar quien tiene permiso de Nivel 1?","o":["Entre las 6 a.m. y las 9 p.m.","Entre las 5 a.m. y las 10 p.m.","Entre las 5 a.m. y la medianoche","A cualquier hora con supervisor"],"h1":"El horario termina en la noche, antes de la medianoche.","h2":"En Virginia Occidental, quien tiene permiso de Nivel 1 solo puede manejar entre las 5 a.m. y las 10 p.m.","p":"Correcto. El Nivel 1 maneja de 5 a.m. a 10 p.m."},"zh":{"q":"在 West Virginia，第 1 级学习驾照持有人在什么时间可以开车？","o":["早上 6 点到晚上 9 点","早上 5 点到晚上 10 点","早上 5 点到半夜 12 点","有人陪同时任何时间都可以"],"h1":"结束时间在晚上，比半夜早。","h2":"在 West Virginia，第 1 级学习驾照持有人只能在早上 5 点到晚上 10 点之间开车。","p":"对。第 1 级可以在早上 5 点到晚上 10 点开车。"},"vi":{"q":"Ở West Virginia, người có giấy phép tập lái Cấp 1 được lái xe trong những giờ nào?","o":["Từ 6 giờ sáng đến 9 giờ tối","Từ 5 giờ sáng đến 10 giờ tối","Từ 5 giờ sáng đến nửa đêm","Bất cứ giờ nào nếu có người đi kèm"],"h1":"Thời gian kết thúc vào buổi tối muộn, trước nửa đêm.","h2":"Ở West Virginia, người có giấy phép tập lái Cấp 1 chỉ được lái xe từ 5 giờ sáng đến 10 giờ tối.","p":"Đúng. Cấp 1 được lái từ 5 giờ sáng đến 10 giờ tối."},"tl":{"q":"Sa West Virginia, anong oras puwedeng magmaneho ang may hawak ng Level 1 na permit?","o":["Mula 6 a.m. hanggang 9 p.m.","Mula 5 a.m. hanggang 10 p.m.","Mula 5 a.m. hanggang hatinggabi","Kahit anong oras kung may nagbabantay"],"h1":"Natatapos ito sa gabi, bago maghatinggabi.","h2":"Sa West Virginia, ang may hawak ng Level 1 na permit ay puwedeng magmaneho lamang mula 5 a.m. hanggang 10 p.m.","p":"Tama. Ang pagmamaneho sa Level 1 ay mula 5 a.m. hanggang 10 p.m."},"ar":{"q":"في West Virginia، في أي ساعات يمكن لحامل تصريح المستوى 1 أن يقود؟","o":["من 6 صباحًا إلى 9 مساءً","من 5 صباحًا إلى 10 مساءً","من 5 صباحًا إلى منتصف الليل","في أي ساعة مع مرافق"],"h1":"الوقت ينتهي في آخر المساء، قبل منتصف الليل.","h2":"في West Virginia يمكن لحامل تصريح المستوى 1 أن يقود فقط من 5 صباحًا إلى 10 مساءً.","p":"صحيح. القيادة في المستوى 1 من 5 صباحًا إلى 10 مساءً."},"ref":{"doc":"WV","page":10}},{"id":"wv-006","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, how many passengers besides the supervisor may ride with a Level 1 permit holder, not counting family?","o":["None","No more than one","No more than two","No more than four"],"h1":"It is a small number, more than one.","h2":"In West Virginia a Level 1 permit holder may carry no more than two additional passengers unless they are family members.","p":"Correct. Up to two extra passengers."},"es":{"q":"En Virginia Occidental, ¿cuántos pasajeros, además del supervisor, pueden ir con alguien con permiso de Nivel 1, sin contar a la familia?","o":["Ninguno","No más de uno","No más de dos","No más de cuatro"],"h1":"Es un número pequeño, mayor que uno.","h2":"En Virginia Occidental, quien tiene permiso de Nivel 1 no puede llevar más de dos pasajeros adicionales, salvo que sean familiares.","p":"Correcto. Hasta dos pasajeros más."},"zh":{"q":"在 West Virginia，除了陪同的人，第 1 级学习驾照持有人最多可以载几个乘客（不算家人）？","o":["一个也不行","最多一个","最多两个","最多四个"],"h1":"人数很少，但多于一个。","h2":"在 West Virginia，第 1 级学习驾照持有人最多只能多载两个乘客，家人除外。","p":"正确。最多再载两个乘客。"},"vi":{"q":"Ở West Virginia, ngoài người đi kèm, người có giấy phép tập lái Cấp 1 được chở bao nhiêu hành khách, không tính người trong gia đình?","o":["Không ai","Không quá một người","Không quá hai người","Không quá bốn người"],"h1":"Đó là một số nhỏ, hơn một.","h2":"Ở West Virginia, người có giấy phép tập lái Cấp 1 được chở thêm không quá hai hành khách, trừ khi họ là người trong gia đình.","p":"Đúng. Tối đa thêm hai hành khách."},"tl":{"q":"Sa West Virginia, bukod sa nagbabantay, ilang pasahero ang puwedeng isakay ng may hawak ng Level 1 na permit, hindi kasama ang pamilya?","o":["Wala","Hindi hihigit sa isa","Hindi hihigit sa dalawa","Hindi hihigit sa apat"],"h1":"Maliit na bilang ito, higit sa isa.","h2":"Sa West Virginia, ang may hawak ng Level 1 na permit ay puwedeng magsakay ng hindi hihigit sa dalawang dagdag na pasahero, maliban kung kapamilya sila.","p":"Tama. Hanggang dalawang dagdag na pasahero."},"ar":{"q":"في West Virginia، كم راكبًا غير المرافق يمكن أن يركب مع حامل تصريح المستوى 1، دون حساب أفراد العائلة؟","o":["لا أحد","ليس أكثر من واحد","ليس أكثر من اثنين","ليس أكثر من أربعة"],"h1":"إنه عدد صغير، أكثر من واحد.","h2":"في West Virginia يمكن لحامل تصريح المستوى 1 أن يحمل راكبَين إضافيَّين على الأكثر، إلا إذا كانوا من أفراد العائلة.","p":"صحيح. راكبان إضافيان على الأكثر."},"ref":{"doc":"WV","page":10}},{"id":"wv-007","scope":"WV","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In West Virginia, what blood alcohol level is allowed for a Level 1 permit holder?","o":["Below 0.02","Below 0.05","Below 0.08","None at all"],"h1":"This is called zero tolerance.","h2":"In West Virginia a Level 1 permit holder must drive with no measurable alcohol in the blood at all.","p":"Right. Zero alcohol for permit holders."},"es":{"q":"En Virginia Occidental, ¿qué nivel de alcohol en la sangre se permite a quien tiene permiso de Nivel 1?","o":["Menos de 0.02","Menos de 0.05","Menos de 0.08","Nada en absoluto"],"h1":"Esto se llama tolerancia cero.","h2":"En Virginia Occidental, quien tiene permiso de Nivel 1 debe manejar sin ninguna cantidad medible de alcohol en la sangre.","p":"Correcto. Cero alcohol con permiso."},"zh":{"q":"在 West Virginia，第 1 级学习驾照持有人血液中可以有多少酒精？","o":["低于 0.02","低于 0.05","低于 0.08","一点都不可以"],"h1":"这叫做零容忍。","h2":"在 West Virginia，第 1 级学习驾照持有人开车时，血液中不能有任何可测出的酒精。","p":"对。持学习驾照的人不能有任何酒精。"},"vi":{"q":"Ở West Virginia, người có giấy phép tập lái Cấp 1 được phép có nồng độ cồn trong máu là bao nhiêu?","o":["Dưới 0.02","Dưới 0.05","Dưới 0.08","Hoàn toàn không có"],"h1":"Điều này gọi là không khoan nhượng.","h2":"Ở West Virginia, người có giấy phép tập lái Cấp 1 phải lái xe mà hoàn toàn không có chút cồn nào đo được trong máu.","p":"Đúng. Người có giấy phép tập lái không được có cồn."},"tl":{"q":"Sa West Virginia, gaano karaming alak sa dugo ang pinapayagan para sa may hawak ng Level 1 na permit?","o":["Mas mababa sa 0.02","Mas mababa sa 0.05","Mas mababa sa 0.08","Wala talaga"],"h1":"Ito ang tinatawag na zero tolerance.","h2":"Sa West Virginia, ang may hawak ng Level 1 na permit ay dapat magmaneho nang walang anumang nasusukat na alak sa dugo.","p":"Tama. Walang alak para sa may hawak ng permit."},"ar":{"q":"في West Virginia، ما نسبة الكحول في الدم المسموح بها لحامل تصريح المستوى 1؟","o":["أقل من 0.02","أقل من 0.05","أقل من 0.08","لا شيء على الإطلاق"],"h1":"هذا يُسمّى عدم التسامح مطلقًا.","h2":"في West Virginia يجب أن يقود حامل تصريح المستوى 1 دون أي كحول يمكن قياسه في الدم على الإطلاق.","p":"صحيح. لا كحول أبدًا لحاملي التصريح."},"ref":{"doc":"WV","page":10}},{"id":"wv-008","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, how many hours of supervised driving are needed for a Level 2 license if you did not take driver education?","o":["50 hours","20 hours","30 hours","100 hours"],"h1":"It is a round number between 30 and 100.","h2":"In West Virginia you need 50 hours of supervised behind-the-wheel driving for a Level 2 license unless you completed driver education.","p":"Correct. Fifty hours are needed."},"es":{"q":"En Virginia Occidental, ¿cuántas horas de manejo supervisado se necesitan para la licencia de Nivel 2 si no tomó educación vial?","o":["50 horas","20 horas","30 horas","100 horas"],"h1":"Es un número redondo entre 30 y 100.","h2":"En Virginia Occidental usted necesita 50 horas de manejo supervisado para la licencia de Nivel 2, salvo que haya completado educación vial.","p":"Correcto. Se necesitan 50 horas."},"zh":{"q":"在 West Virginia，如果你没有上驾驶教育课，拿第 2 级驾照需要多少小时有人陪同的驾驶练习？","o":["50 小时","20 小时","30 小时","100 小时"],"h1":"它是 30 到 100 之间的一个整数。","h2":"在 West Virginia，如果你没有完成驾驶教育课，拿第 2 级驾照需要 50 小时有人陪同的实际驾驶练习。","p":"正确。需要 50 小时。"},"vi":{"q":"Ở West Virginia, nếu bạn không học lớp giáo dục lái xe, cần bao nhiêu giờ lái xe có người đi kèm để có bằng lái Cấp 2?","o":["50 giờ","20 giờ","30 giờ","100 giờ"],"h1":"Đó là một số tròn giữa 30 và 100.","h2":"Ở West Virginia, bạn cần 50 giờ tự cầm lái có người đi kèm để có bằng lái Cấp 2, trừ khi bạn đã học xong lớp giáo dục lái xe.","p":"Đúng. Cần 50 giờ."},"tl":{"q":"Sa West Virginia, ilang oras ng binabantayang pagmamaneho ang kailangan para sa Level 2 na lisensya kung hindi ka kumuha ng driver education?","o":["50 oras","20 oras","30 oras","100 oras"],"h1":"Isa itong bilog na numero sa pagitan ng 30 at 100.","h2":"Sa West Virginia, kailangan mo ng 50 oras ng binabantayang pagmamaneho para sa Level 2 na lisensya, maliban kung natapos mo ang driver education.","p":"Tama. Limampung oras ang kailangan."},"ar":{"q":"في West Virginia، كم ساعة من القيادة مع مرافق تحتاج للحصول على رخصة المستوى 2 إذا لم تأخذ دورة تعليم القيادة؟","o":["50 ساعة","20 ساعة","30 ساعة","100 ساعة"],"h1":"إنه عدد مُقرَّب بين 30 و100.","h2":"في West Virginia تحتاج إلى 50 ساعة من القيادة الفعلية مع مرافق للحصول على رخصة المستوى 2، إلا إذا أكملت دورة تعليم القيادة.","p":"صحيح. تحتاج إلى 50 ساعة."},"ref":{"doc":"WV","page":10}},{"id":"wv-009","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, how many of the 50 supervised hours must be at night?","o":["At least 2 hours","At least 10 hours","At least 5 hours","At least 25 hours"],"h1":"It is one fifth of the total.","h2":"In West Virginia at least 10 of the 50 supervised driving hours must be at night.","p":"Right. Ten hours are at night."},"es":{"q":"En Virginia Occidental, ¿cuántas de las 50 horas supervisadas deben ser de noche?","o":["Por lo menos 2 horas","Por lo menos 10 horas","Por lo menos 5 horas","Por lo menos 25 horas"],"h1":"Es la quinta parte del total.","h2":"En Virginia Occidental, por lo menos 10 de las 50 horas de manejo supervisado deben ser de noche.","p":"Correcto. Diez horas son de noche."},"zh":{"q":"在 West Virginia，这 50 小时有人陪同的练习中，有多少小时必须在晚上？","o":["至少 2 小时","至少 10 小时","至少 5 小时","至少 25 小时"],"h1":"它是总数的五分之一。","h2":"在 West Virginia，50 小时有人陪同的驾驶练习中，至少 10 小时必须在晚上。","p":"对。10 小时在晚上。"},"vi":{"q":"Ở West Virginia, trong 50 giờ lái xe có người đi kèm, bao nhiêu giờ phải là vào ban đêm?","o":["Ít nhất 2 giờ","Ít nhất 10 giờ","Ít nhất 5 giờ","Ít nhất 25 giờ"],"h1":"Đó là một phần năm của tổng số.","h2":"Ở West Virginia, ít nhất 10 trong 50 giờ lái xe có người đi kèm phải là vào ban đêm.","p":"Đúng. 10 giờ là vào ban đêm."},"tl":{"q":"Sa West Virginia, ilan sa 50 oras ng binabantayang pagmamaneho ang dapat gawin sa gabi?","o":["Hindi bababa sa 2 oras","Hindi bababa sa 10 oras","Hindi bababa sa 5 oras","Hindi bababa sa 25 oras"],"h1":"Ito ay isang-kalima ng kabuuan.","h2":"Sa West Virginia, hindi bababa sa 10 sa 50 oras ng binabantayang pagmamaneho ang dapat gawin sa gabi.","p":"Tama. Sampung oras ang sa gabi."},"ar":{"q":"في West Virginia، كم ساعة من الـ 50 ساعة مع مرافق يجب أن تكون في الليل؟","o":["2 ساعة على الأقل","10 ساعات على الأقل","5 ساعات على الأقل","25 ساعة على الأقل"],"h1":"إنه خُمس المجموع.","h2":"في West Virginia يجب أن تكون 10 ساعات على الأقل من الـ 50 ساعة من القيادة مع مرافق في الليل.","p":"صحيح. 10 ساعات في الليل."},"ref":{"doc":"WV","page":10}},{"id":"wv-010","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, how long must you hold a Level 1 permit without a conviction before applying for Level 2?","o":["30 days","90 days","180 days","One year"],"h1":"It is about six months.","h2":"In West Virginia you must hold your Level 1 permit conviction-free for the 180 days before you apply for a Level 2 license.","p":"Correct. It is 180 days without a conviction."},"es":{"q":"En Virginia Occidental, ¿cuánto tiempo debe tener el permiso de Nivel 1 sin condenas antes de solicitar el Nivel 2?","o":["30 días","90 días","180 días","Un año"],"h1":"Son unos seis meses.","h2":"En Virginia Occidental usted debe tener el permiso de Nivel 1 sin condenas durante los 180 días antes de solicitar la licencia de Nivel 2.","p":"Correcto. Son 180 días sin condenas."},"zh":{"q":"在 West Virginia，你必须持有第 1 级学习驾照多久而没有违法定罪，才可以申请第 2 级？","o":["30 天","90 天","180 天","一年"],"h1":"大约是六个月。","h2":"在 West Virginia，申请第 2 级驾照之前，你必须持有第 1 级学习驾照 180 天，而且没有违法定罪。","p":"正确。是 180 天没有违法定罪。"},"vi":{"q":"Ở West Virginia, bạn phải giữ giấy phép tập lái Cấp 1 bao lâu mà không bị kết tội vi phạm trước khi xin Cấp 2?","o":["30 ngày","90 ngày","180 ngày","Một năm"],"h1":"Khoảng sáu tháng.","h2":"Ở West Virginia, bạn phải giữ giấy phép tập lái Cấp 1 trong 180 ngày mà không bị kết tội vi phạm trước khi xin bằng lái Cấp 2.","p":"Đúng. Là 180 ngày không bị kết tội vi phạm."},"tl":{"q":"Sa West Virginia, gaano katagal mo dapat hawak ang Level 1 na permit nang walang conviction bago mag-apply para sa Level 2?","o":["30 araw","90 araw","180 araw","Isang taon"],"h1":"Mga anim na buwan ito.","h2":"Sa West Virginia, dapat mong hawak ang Level 1 na permit nang walang conviction sa loob ng 180 araw bago ka mag-apply para sa Level 2 na lisensya.","p":"Tama. 180 araw ito nang walang conviction."},"ar":{"q":"في West Virginia، كم مدة يجب أن تحمل تصريح المستوى 1 دون إدانة قبل التقدّم للمستوى 2؟","o":["30 يومًا","90 يومًا","180 يومًا","سنة واحدة"],"h1":"إنها حوالي ستة أشهر.","h2":"في West Virginia يجب أن تحمل تصريح المستوى 1 دون أي إدانة لمدة 180 يومًا قبل أن تتقدّم لرخصة المستوى 2.","p":"صحيح. 180 يومًا دون إدانة."},"ref":{"doc":"WV","page":10}},{"id":"wv-011","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, when may a Level 2 driver drive alone without a supervisor?","o":["Between 6 a.m. and 9 p.m.","Between 5 a.m. and midnight","Only on school days","Between 5 a.m. and 10 p.m."],"h1":"It is the same window as for a Level 1 permit.","h2":"In West Virginia a Level 2 driver may drive unsupervised between 5 a.m. and 10 p.m.; later hours need a licensed driver 21 or older, except for work, school, religious events or emergencies.","p":"Right. Alone from 5 a.m. to 10 p.m."},"es":{"q":"En Virginia Occidental, ¿cuándo puede un conductor de Nivel 2 manejar solo, sin supervisor?","o":["Entre las 6 a.m. y las 9 p.m.","Entre las 5 a.m. y la medianoche","Solo los días de escuela","Entre las 5 a.m. y las 10 p.m."],"h1":"Es el mismo horario que el del permiso de Nivel 1.","h2":"En Virginia Occidental, un conductor de Nivel 2 puede manejar solo entre las 5 a.m. y las 10 p.m.; más tarde necesita un conductor con licencia de 21 años o más, salvo por trabajo, escuela, eventos religiosos o emergencias.","p":"Correcto. Solo, de 5 a.m. a 10 p.m."},"zh":{"q":"在 West Virginia，第 2 级驾照的司机什么时候可以没有人陪同、自己开车？","o":["早上 6 点到晚上 9 点","早上 5 点到半夜 12 点","只有上学的日子","早上 5 点到晚上 10 点"],"h1":"和第 1 级学习驾照的时间一样。","h2":"在 West Virginia，第 2 级驾照的司机可以在早上 5 点到晚上 10 点之间自己开车；更晚的时间需要 21 岁或以上的有照司机陪同，但上班、上学、宗教活动或紧急情况除外。","p":"对。早上 5 点到晚上 10 点可以自己开。"},"vi":{"q":"Ở West Virginia, khi nào người có bằng lái Cấp 2 được lái xe một mình mà không có người đi kèm?","o":["Từ 6 giờ sáng đến 9 giờ tối","Từ 5 giờ sáng đến nửa đêm","Chỉ vào ngày đi học","Từ 5 giờ sáng đến 10 giờ tối"],"h1":"Giống với giờ của giấy phép tập lái Cấp 1.","h2":"Ở West Virginia, người có bằng lái Cấp 2 được lái xe một mình từ 5 giờ sáng đến 10 giờ tối; giờ muộn hơn cần một người có bằng lái từ 21 tuổi trở lên đi kèm, trừ khi đi làm, đi học, đi sự kiện tôn giáo hoặc trường hợp khẩn cấp.","p":"Đúng. Lái một mình từ 5 giờ sáng đến 10 giờ tối."},"tl":{"q":"Sa West Virginia, kailan puwedeng magmaneho nang mag-isa, nang walang nagbabantay, ang drayber na may Level 2?","o":["Mula 6 a.m. hanggang 9 p.m.","Mula 5 a.m. hanggang hatinggabi","Sa mga araw ng pasok lamang","Mula 5 a.m. hanggang 10 p.m."],"h1":"Pareho ito ng oras para sa Level 1 na permit.","h2":"Sa West Virginia, ang drayber na may Level 2 ay puwedeng magmaneho nang walang nagbabantay mula 5 a.m. hanggang 10 p.m.; sa mas huling oras, kailangan ng may lisensyang drayber na 21 o higit pa, maliban kung para sa trabaho, paaralan, gawaing panrelihiyon o emergency.","p":"Tama. Mag-isa mula 5 a.m. hanggang 10 p.m."},"ar":{"q":"في West Virginia، متى يمكن لسائق المستوى 2 أن يقود وحده دون مرافق؟","o":["من 6 صباحًا إلى 9 مساءً","من 5 صباحًا إلى منتصف الليل","في أيام المدرسة فقط","من 5 صباحًا إلى 10 مساءً"],"h1":"إنه نفس وقت تصريح المستوى 1.","h2":"في West Virginia يمكن لسائق المستوى 2 أن يقود دون مرافق من 5 صباحًا إلى 10 مساءً؛ وبعد ذلك يحتاج إلى سائق مرخّص عمره 21 سنة أو أكثر، إلا للعمل أو المدرسة أو المناسبات الدينية أو حالات الطوارئ.","p":"صحيح. وحدك من 5 صباحًا إلى 10 مساءً."},"ref":{"doc":"WV","page":10}},{"id":"wv-012","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, during the first six months of a Level 2 license, how many passengers under 20 who are not family may you carry?","o":["None","One","Two","Three"],"h1":"The first months are the strictest.","h2":"In West Virginia, for the first six months of a Level 2 license, you may not carry any passengers under 20 unless they are family members.","p":"Correct. No young non-family passengers at first."},"es":{"q":"En Virginia Occidental, durante los primeros seis meses de la licencia de Nivel 2, ¿cuántos pasajeros menores de 20 años que no son familia puede llevar?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Los primeros meses son los más estrictos.","h2":"En Virginia Occidental, durante los primeros seis meses de la licencia de Nivel 2, no puede llevar pasajeros menores de 20 años, salvo que sean familiares.","p":"Correcto. Al principio, ningún pasajero joven que no sea familia."},"zh":{"q":"在 West Virginia，拿到第 2 级驾照的头六个月，你可以载几个未满 20 岁、又不是家人的乘客？","o":["一个也不行","一个","两个","三个"],"h1":"头几个月是最严格的。","h2":"在 West Virginia，拿到第 2 级驾照的头六个月，你不能载任何未满 20 岁的乘客，除非他们是家人。","p":"正确。开始时不能载不是家人的年轻乘客。"},"vi":{"q":"Ở West Virginia, trong sáu tháng đầu có bằng lái Cấp 2, bạn được chở bao nhiêu hành khách dưới 20 tuổi không phải người trong gia đình?","o":["Không ai","Một người","Hai người","Ba người"],"h1":"Những tháng đầu là nghiêm nhất.","h2":"Ở West Virginia, trong sáu tháng đầu có bằng lái Cấp 2, bạn không được chở hành khách nào dưới 20 tuổi, trừ khi họ là người trong gia đình.","p":"Đúng. Lúc đầu không được chở người trẻ không phải người nhà."},"tl":{"q":"Sa West Virginia, sa unang anim na buwan ng Level 2 na lisensya, ilang pasaherong wala pang 20 na hindi kapamilya ang puwede mong isakay?","o":["Wala","Isa","Dalawa","Tatlo"],"h1":"Ang mga unang buwan ang pinakamahigpit.","h2":"Sa West Virginia, sa unang anim na buwan ng Level 2 na lisensya, hindi ka puwedeng magsakay ng kahit sinong pasaherong wala pang 20, maliban kung kapamilya sila.","p":"Tama. Walang batang pasaherong hindi kapamilya sa simula."},"ar":{"q":"في West Virginia، خلال أول ستة أشهر من رخصة المستوى 2، كم راكبًا عمره أقل من 20 سنة وليس من العائلة يمكنك أن تحمل؟","o":["لا أحد","واحد","اثنان","ثلاثة"],"h1":"الأشهر الأولى هي الأكثر صرامة.","h2":"في West Virginia، خلال أول ستة أشهر من رخصة المستوى 2، لا يجوز لك أن تحمل أي راكب عمره أقل من 20 سنة إلا إذا كان من أفراد العائلة.","p":"صحيح. لا ركّاب صغار من خارج العائلة في البداية."},"ref":{"doc":"WV","page":11}},{"id":"wv-013","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, during the second six months of a Level 2 license, how many passengers under 20 who are not family may you carry?","o":["None","No more than one","No more than two","No more than three"],"h1":"The limit opens up by just one.","h2":"In West Virginia, for the second six months of a Level 2 license, you may not carry more than one passenger under 20 who is not a family member.","p":"Right. Only one passenger under 20."},"es":{"q":"En Virginia Occidental, durante los segundos seis meses de la licencia de Nivel 2, ¿cuántos pasajeros menores de 20 años que no son familiares puede llevar?","o":["Ninguno","No más de uno","No más de dos","No más de tres"],"h1":"El límite se abre solo en uno.","h2":"En Virginia Occidental, durante los segundos seis meses de la licencia de Nivel 2, no puede llevar más de un pasajero menor de 20 años que no sea familiar.","p":"Correcto. Solo un pasajero menor de 20."},"zh":{"q":"在 West Virginia，拿到第 2 级驾照的第二个六个月，你可以载几个未满 20 岁、又不是家人的乘客？","o":["一个也不行","最多一个","最多两个","最多三个"],"h1":"限制只放宽了一个人。","h2":"在 West Virginia，拿到第 2 级驾照的第二个六个月，你最多只能载一个未满 20 岁、又不是家人的乘客。","p":"对。只能载一个未满 20 岁的乘客。"},"vi":{"q":"Ở West Virginia, trong sáu tháng thứ hai có bằng lái Cấp 2, bạn được chở bao nhiêu hành khách dưới 20 tuổi không phải người trong gia đình?","o":["Không ai","Không quá một người","Không quá hai người","Không quá ba người"],"h1":"Giới hạn chỉ tăng thêm một người.","h2":"Ở West Virginia, trong sáu tháng thứ hai có bằng lái Cấp 2, bạn không được chở quá một hành khách dưới 20 tuổi không phải người trong gia đình.","p":"Đúng. Chỉ một hành khách dưới 20 tuổi."},"tl":{"q":"Sa West Virginia, sa ikalawang anim na buwan ng Level 2 na lisensya, ilang pasaherong wala pang 20 na hindi kapamilya ang puwede mong isakay?","o":["Wala","Hindi hihigit sa isa","Hindi hihigit sa dalawa","Hindi hihigit sa tatlo"],"h1":"Isa lang ang idinadagdag sa limitasyon.","h2":"Sa West Virginia, sa ikalawang anim na buwan ng Level 2 na lisensya, hindi ka puwedeng magsakay ng higit sa isang pasaherong wala pang 20 na hindi kapamilya.","p":"Tama. Isang pasahero lang na wala pang 20."},"ar":{"q":"في West Virginia، خلال الستة أشهر الثانية من رخصة المستوى 2، كم راكبًا عمره أقل من 20 سنة وليس من العائلة يمكنك أن تحمل؟","o":["لا أحد","ليس أكثر من واحد","ليس أكثر من اثنين","ليس أكثر من ثلاثة"],"h1":"الحدّ يزيد بواحد فقط.","h2":"في West Virginia، خلال الستة أشهر الثانية من رخصة المستوى 2، لا يجوز لك أن تحمل أكثر من راكب واحد عمره أقل من 20 سنة وليس من أفراد العائلة.","p":"صحيح. راكب واحد فقط عمره أقل من 20 سنة."},"ref":{"doc":"WV","page":11}},{"id":"wv-014","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, what is the youngest age for a Level 3 full license?","o":["16 years old","18 years old","17 years old","21 years old"],"h1":"It is one year after the youngest Level 2 age.","h2":"In West Virginia you can get a Level 3 full license at 17 after holding a Level 2 license for 12 months without a conviction.","p":"Correct. Level 3 starts at 17."},"es":{"q":"En Virginia Occidental, ¿cuál es la edad mínima para la licencia completa de Nivel 3?","o":["16 años","18 años","17 años","21 años"],"h1":"Es un año después de la edad mínima del Nivel 2.","h2":"En Virginia Occidental usted puede obtener la licencia completa de Nivel 3 a los 17 años, después de tener la licencia de Nivel 2 por 12 meses sin condenas.","p":"Correcto. El Nivel 3 empieza a los 17."},"zh":{"q":"在 West Virginia，最小几岁可以拿到第 3 级正式驾照（Level 3 full license）？","o":["16 岁","18 岁","17 岁","21 岁"],"h1":"它比拿第 2 级驾照的最小年龄晚一年。","h2":"在 West Virginia，你持有第 2 级驾照 12 个月而没有违法定罪后，17 岁就可以拿到第 3 级正式驾照。","p":"正确。第 3 级从 17 岁开始。"},"vi":{"q":"Ở West Virginia, tuổi nhỏ nhất để có bằng lái đầy đủ Cấp 3 (Level 3 full license) là bao nhiêu?","o":["16 tuổi","18 tuổi","17 tuổi","21 tuổi"],"h1":"Muộn hơn một năm so với tuổi nhỏ nhất của Cấp 2.","h2":"Ở West Virginia, bạn có thể có bằng lái đầy đủ Cấp 3 khi 17 tuổi, sau khi giữ bằng lái Cấp 2 trong 12 tháng mà không bị kết tội vi phạm.","p":"Đúng. Cấp 3 bắt đầu từ 17 tuổi."},"tl":{"q":"Sa West Virginia, ano ang pinakabatang edad para sa Level 3 na buong lisensya (Level 3 full license)?","o":["16 taong gulang","18 taong gulang","17 taong gulang","21 taong gulang"],"h1":"Isang taon ito pagkatapos ng pinakabatang edad para sa Level 2.","h2":"Sa West Virginia, puwede kang kumuha ng Level 3 na buong lisensya sa edad na 17, pagkatapos mong hawakan ang Level 2 na lisensya nang 12 buwan nang walang conviction.","p":"Tama. Nagsisimula ang Level 3 sa 17."},"ar":{"q":"في West Virginia، ما أصغر عمر للحصول على الرخصة الكاملة من المستوى 3 (Level 3 full license)؟","o":["16 سنة","18 سنة","17 سنة","21 سنة"],"h1":"إنه بعد أصغر عمر للمستوى 2 بسنة واحدة.","h2":"في West Virginia يمكنك الحصول على الرخصة الكاملة من المستوى 3 في عمر 17 سنة بعد أن تحمل رخصة المستوى 2 لمدة 12 شهرًا دون إدانة.","p":"صحيح. المستوى 3 يبدأ في عمر 17 سنة."},"ref":{"doc":"WV","page":12}},{"id":"wv-015","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, how long must you hold a Level 2 license without a conviction before Level 3?","o":["3 months","6 months","24 months","12 months"],"h1":"It is one full year.","h2":"In West Virginia you must hold a Level 2 license conviction-free for 12 months before applying for Level 3.","p":"Right. One year without a conviction."},"es":{"q":"En Virginia Occidental, ¿cuánto tiempo debe tener la licencia de Nivel 2 sin condenas antes del Nivel 3?","o":["3 meses","6 meses","24 meses","12 meses"],"h1":"Es un año completo.","h2":"En Virginia Occidental usted debe tener la licencia de Nivel 2 sin condenas durante 12 meses antes de solicitar el Nivel 3.","p":"Correcto. Un año sin condenas."},"zh":{"q":"在 West Virginia，你必须持有第 2 级驾照多久而没有违法定罪，才可以拿第 3 级？","o":["3 个月","6 个月","24 个月","12 个月"],"h1":"是整整一年。","h2":"在 West Virginia，申请第 3 级之前，你必须持有第 2 级驾照 12 个月，而且没有违法定罪。","p":"对。一年没有违法定罪。"},"vi":{"q":"Ở West Virginia, bạn phải giữ bằng lái Cấp 2 bao lâu mà không bị kết tội vi phạm trước khi lên Cấp 3?","o":["3 tháng","6 tháng","24 tháng","12 tháng"],"h1":"Đúng một năm.","h2":"Ở West Virginia, bạn phải giữ bằng lái Cấp 2 trong 12 tháng mà không bị kết tội vi phạm trước khi xin Cấp 3.","p":"Đúng. Một năm không bị kết tội vi phạm."},"tl":{"q":"Sa West Virginia, gaano katagal mo dapat hawak ang Level 2 na lisensya nang walang conviction bago ang Level 3?","o":["3 buwan","6 na buwan","24 na buwan","12 buwan"],"h1":"Isang buong taon ito.","h2":"Sa West Virginia, dapat mong hawak ang Level 2 na lisensya nang walang conviction sa loob ng 12 buwan bago mag-apply para sa Level 3.","p":"Tama. Isang taon nang walang conviction."},"ar":{"q":"في West Virginia، كم مدة يجب أن تحمل رخصة المستوى 2 دون إدانة قبل المستوى 3؟","o":["3 أشهر","6 أشهر","24 شهرًا","12 شهرًا"],"h1":"إنها سنة كاملة.","h2":"في West Virginia يجب أن تحمل رخصة المستوى 2 دون أي إدانة لمدة 12 شهرًا قبل التقدّم للمستوى 3.","p":"صحيح. سنة واحدة دون إدانة."},"ref":{"doc":"WV","page":12}},{"id":"wv-016","scope":"WV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In West Virginia, when may a driver under 18 with a permit or Level 2 license use a phone while driving?","o":["Only to call 911","Any time, if it is hands-free","Only at red lights","Only to text a parent"],"h1":"There is only one exception, and it is for emergencies.","h2":"In West Virginia a driver under 18 with a permit or Level 2 license may not use a phone or other wireless device while driving, except to call 911.","p":"Correct. Only a 911 call is allowed."},"es":{"q":"En Virginia Occidental, ¿cuándo puede un conductor menor de 18 años con permiso o licencia de Nivel 2 usar el teléfono mientras maneja?","o":["Solo para llamar al 911","En cualquier momento, si es manos libres","Solo en los semáforos en rojo","Solo para escribirle a un padre"],"h1":"Hay una sola excepción, y es para emergencias.","h2":"En Virginia Occidental, un conductor menor de 18 años con permiso o licencia de Nivel 2 no puede usar un teléfono ni otro aparato inalámbrico mientras maneja, salvo para llamar al 911.","p":"Correcto. Solo se permite llamar al 911."},"zh":{"q":"在 West Virginia，未满 18 岁、持有学习驾照或第 2 级驾照的司机，开车时什么时候可以用手机？","o":["只能打 911","任何时候，只要不用手拿","只有在红灯时","只能给父母发短信"],"h1":"只有一个例外，是为了紧急情况。","h2":"在 West Virginia，未满 18 岁、持有学习驾照或第 2 级驾照的司机，开车时不能用手机或其他无线设备，只可以打 911。","p":"正确。只可以打 911。"},"vi":{"q":"Ở West Virginia, khi nào người lái xe dưới 18 tuổi có giấy phép tập lái hoặc bằng lái Cấp 2 được dùng điện thoại khi đang lái xe?","o":["Chỉ để gọi 911","Bất cứ lúc nào, nếu không cầm tay","Chỉ khi dừng đèn đỏ","Chỉ để nhắn tin cho cha mẹ"],"h1":"Chỉ có một ngoại lệ, và đó là cho trường hợp khẩn cấp.","h2":"Ở West Virginia, người lái xe dưới 18 tuổi có giấy phép tập lái hoặc bằng lái Cấp 2 không được dùng điện thoại hay thiết bị không dây khác khi lái xe, trừ khi gọi 911.","p":"Đúng. Chỉ được gọi 911."},"tl":{"q":"Sa West Virginia, kailan puwedeng gumamit ng telepono habang nagmamaneho ang drayber na wala pang 18 na may permit o Level 2 na lisensya?","o":["Para lamang tumawag sa 911","Kahit kailan, kung hands-free","Sa pulang ilaw lamang","Para lamang mag-text sa magulang"],"h1":"Isa lang ang eksepsiyon, at ito ay para sa emergency.","h2":"Sa West Virginia, ang drayber na wala pang 18 na may permit o Level 2 na lisensya ay hindi puwedeng gumamit ng telepono o ibang wireless device habang nagmamaneho, maliban para tumawag sa 911.","p":"Tama. Pagtawag lamang sa 911 ang pinapayagan."},"ar":{"q":"في West Virginia، متى يمكن للسائق الذي عمره أقل من 18 سنة ويحمل تصريحًا أو رخصة المستوى 2 أن يستخدم الهاتف أثناء القيادة؟","o":["فقط للاتصال بـ 911","في أي وقت، إذا كان دون استخدام اليدين","فقط عند الإشارة الحمراء","فقط لإرسال رسالة إلى أحد الوالدين"],"h1":"هناك استثناء واحد فقط، وهو للطوارئ.","h2":"في West Virginia لا يجوز للسائق الذي عمره أقل من 18 سنة ويحمل تصريحًا أو رخصة المستوى 2 أن يستخدم الهاتف أو أي جهاز لاسلكي آخر أثناء القيادة، إلا للاتصال بـ 911.","p":"صحيح. مسموح فقط الاتصال بـ 911."},"ref":{"doc":"WV","page":11}},{"id":"wv-017","scope":"WV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In West Virginia, what does the law say about adult drivers and phones?","o":["You may text if traffic is slow","You may not hold the phone; calls must be hands-free","You may hold the phone on rural roads","There is no phone law for adults"],"h1":"Your hands belong on the wheel.","h2":"In West Virginia no driver may hold a phone while driving, and calls are allowed only with hands-free or voice-operated features.","p":"Right. Adults must be hands-free too."},"es":{"q":"En Virginia Occidental, ¿qué dice la ley sobre los conductores adultos y el teléfono?","o":["Puede escribir mensajes si el tráfico es lento","No puede sostener el teléfono; las llamadas deben ser manos libres","Puede sostener el teléfono en caminos rurales","No hay ley de teléfonos para adultos"],"h1":"Sus manos deben estar en el volante.","h2":"En Virginia Occidental ningún conductor puede sostener un teléfono mientras maneja, y las llamadas solo se permiten con manos libres o por voz.","p":"Correcto. Los adultos también deben usar manos libres."},"zh":{"q":"在 West Virginia，法律对成年司机用手机有什么规定？","o":["车开得慢时可以发短信","不能用手拿手机；打电话必须用免提","在乡村道路上可以用手拿手机","成年人没有手机法律"],"h1":"你的手应该放在方向盘上。","h2":"在 West Virginia，任何司机开车时都不能用手拿手机，打电话只能用免提或语音控制功能。","p":"对。成年人也必须用免提。"},"vi":{"q":"Ở West Virginia, luật nói gì về người lái xe trưởng thành và điện thoại?","o":["Bạn được nhắn tin nếu xe chạy chậm","Bạn không được cầm điện thoại; gọi điện phải dùng chế độ rảnh tay","Bạn được cầm điện thoại trên đường nông thôn","Không có luật về điện thoại cho người lớn"],"h1":"Tay bạn phải đặt trên vô lăng.","h2":"Ở West Virginia, không người lái xe nào được cầm điện thoại khi lái xe, và chỉ được gọi điện bằng chế độ rảnh tay hoặc điều khiển bằng giọng nói.","p":"Đúng. Người lớn cũng phải dùng chế độ rảnh tay."},"tl":{"q":"Sa West Virginia, ano ang sinasabi ng batas tungkol sa mga adultong drayber at telepono?","o":["Puwede kang mag-text kung mabagal ang trapiko","Hindi mo puwedeng hawakan ang telepono; ang tawag ay dapat hands-free","Puwede mong hawakan ang telepono sa mga daan sa probinsya","Walang batas sa telepono para sa mga adulto"],"h1":"Ang mga kamay mo ay dapat nasa manibela.","h2":"Sa West Virginia, walang drayber ang puwedeng humawak ng telepono habang nagmamaneho, at ang tawag ay pinapayagan lamang gamit ang hands-free o voice-operated na feature.","p":"Tama. Dapat hands-free din ang mga adulto."},"ar":{"q":"في West Virginia، ماذا يقول القانون عن السائقين البالغين والهواتف؟","o":["يمكنك إرسال الرسائل إذا كانت حركة السير بطيئة","لا يجوز لك أن تمسك الهاتف؛ المكالمات يجب أن تكون دون استخدام اليدين","يمكنك أن تمسك الهاتف على الطرق الريفية","لا يوجد قانون للهاتف للبالغين"],"h1":"يداك مكانهما على المِقوَد.","h2":"في West Virginia لا يجوز لأي سائق أن يمسك الهاتف أثناء القيادة، والمكالمات مسموحة فقط باستخدام خاصية عدم استخدام اليدين أو التحكّم بالصوت.","p":"صحيح. البالغون أيضًا يجب أن يستخدموا الهاتف دون اليدين."},"ref":{"doc":"WV","page":17}},{"id":"wv-018","scope":"WV","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In West Virginia, what blood alcohol level is a crime for a driver under 21?","o":["0.08 or more","0.05 or more","0.02 or more","0.10 or more"],"h1":"It is far below the adult limit.","h2":"In West Virginia a driver under 21 commits a misdemeanor by driving with a blood alcohol level of 0.02 or more.","p":"Correct. Under 21, the limit is 0.02."},"es":{"q":"En Virginia Occidental, ¿qué nivel de alcohol en la sangre es un delito para un conductor menor de 21 años?","o":["0.08 o más","0.05 o más","0.02 o más","0.10 o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Virginia Occidental, un conductor menor de 21 años comete un delito menor si maneja con un nivel de alcohol en la sangre de 0.02 o más.","p":"Correcto. Para menores de 21, el límite es 0.02."},"zh":{"q":"在 West Virginia，未满 21 岁的司机血液酒精浓度达到多少就是犯罪？","o":["0.08 或以上","0.05 或以上","0.02 或以上","0.10 或以上"],"h1":"它远远低于成年人的上限。","h2":"在 West Virginia，未满 21 岁的司机血液酒精浓度达到 0.02 或以上时开车，就犯了轻罪。","p":"正确。未满 21 岁，上限是 0.02。"},"vi":{"q":"Ở West Virginia, nồng độ cồn trong máu bao nhiêu là phạm tội đối với người lái xe dưới 21 tuổi?","o":["0.08 trở lên","0.05 trở lên","0.02 trở lên","0.10 trở lên"],"h1":"Nó thấp hơn nhiều so với giới hạn của người lớn.","h2":"Ở West Virginia, người lái xe dưới 21 tuổi phạm tội nhẹ nếu lái xe với nồng độ cồn trong máu từ 0.02 trở lên.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa West Virginia, anong antas ng alak sa dugo ang krimen para sa drayber na wala pang 21?","o":["0.08 o higit pa","0.05 o higit pa","0.02 o higit pa","0.10 o higit pa"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon ng adulto.","h2":"Sa West Virginia, ang drayber na wala pang 21 ay gumagawa ng misdemeanor kapag nagmaneho siya na may antas ng alak sa dugo na 0.02 o higit pa.","p":"Tama. Kung wala pang 21, ang limitasyon ay 0.02."},"ar":{"q":"في West Virginia، ما نسبة الكحول في الدم التي تُعتبر جريمة للسائق الذي عمره أقل من 21 سنة؟","o":["0.08 أو أكثر","0.05 أو أكثر","0.02 أو أكثر","0.10 أو أكثر"],"h1":"إنها أقل بكثير من حدّ البالغين.","h2":"في West Virginia يرتكب السائق الذي عمره أقل من 21 سنة جنحة إذا قاد ونسبة الكحول في دمه 0.02 أو أكثر.","p":"صحيح. لمن هم أقل من 21 سنة، الحدّ هو 0.02."},"ref":{"doc":"WV","page":null}},{"id":"wv-019","scope":"WV","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In West Virginia, which stopped vehicle with flashing lights is covered by the move over law?","o":["Only police cars","Only fire trucks","Only ambulances","All of these: police cars, ambulances and tow trucks"],"h1":"The law covers any stopped vehicle that shows warning lights.","h2":"In West Virginia the move over law covers every stopped vehicle with flashing or hazard lights, including police cars, ambulances and tow trucks, so you move over if it is safe or slow down.","p":"Right. The law covers all of them."},"es":{"q":"En Virginia Occidental, ¿qué vehículo detenido con luces intermitentes está cubierto por la ley de cambiarse de carril (move over)?","o":["Solo patrullas","Solo camiones de bomberos","Solo ambulancias","Todos estos: patrullas, ambulancias y grúas"],"h1":"La ley cubre a cualquier vehículo detenido que muestre luces de advertencia.","h2":"En Virginia Occidental, la ley de cambiarse de carril cubre a todo vehículo detenido con luces intermitentes o de emergencia, incluidas patrullas, ambulancias y grúas, así que usted se cambia de carril si es seguro o reduce la velocidad.","p":"Correcto. La ley los cubre a todos."},"zh":{"q":"在 West Virginia，哪一种停在路边、亮着闪灯的车辆受「让道法」（move over law）保护？","o":["只有警车","只有消防车","只有救护车","以上都是：警车、救护车和拖车"],"h1":"法律包括任何停着、亮着警示灯的车辆。","h2":"在 West Virginia，「让道法」包括所有停着、亮着闪灯或危险警示灯的车辆，包括警车、救护车和拖车，所以安全时你要换到另一条车道，否则要减速。","p":"对。法律包括所有这些车辆。"},"vi":{"q":"Ở West Virginia, loại xe đang dừng và có đèn nhấp nháy nào được luật nhường đường (move over law) bảo vệ?","o":["Chỉ xe cảnh sát","Chỉ xe cứu hỏa","Chỉ xe cứu thương","Tất cả: xe cảnh sát, xe cứu thương và xe kéo"],"h1":"Luật áp dụng cho bất kỳ xe nào đang dừng và bật đèn cảnh báo.","h2":"Ở West Virginia, luật nhường đường áp dụng cho mọi xe đang dừng có đèn nhấp nháy hoặc đèn cảnh báo nguy hiểm, kể cả xe cảnh sát, xe cứu thương và xe kéo, nên bạn phải chuyển làn nếu an toàn, hoặc chạy chậm lại.","p":"Đúng. Luật áp dụng cho tất cả các xe đó."},"tl":{"q":"Sa West Virginia, aling nakahintong sasakyan na may kumikislap na ilaw ang sakop ng move over law?","o":["Mga sasakyan ng pulis lamang","Mga trak ng bumbero lamang","Mga ambulansya lamang","Lahat ng ito: sasakyan ng pulis, ambulansya at tow truck"],"h1":"Sakop ng batas ang anumang nakahintong sasakyan na may babalang ilaw.","h2":"Sa West Virginia, sakop ng move over law ang bawat nakahintong sasakyan na may kumikislap o hazard na ilaw, kasama ang sasakyan ng pulis, ambulansya at tow truck, kaya lumipat ka ng lane kung ligtas, o bumagal.","p":"Tama. Sakop ng batas ang lahat ng ito."},"ar":{"q":"في West Virginia، أي مركبة متوقّفة وأضواؤها تومض يشملها قانون الابتعاد (move over law)؟","o":["سيارات الشرطة فقط","سيارات الإطفاء فقط","سيارات الإسعاف فقط","كل هذه: سيارات الشرطة والإسعاف وشاحنات السحب"],"h1":"القانون يشمل أي مركبة متوقّفة تُظهر أضواء تحذير.","h2":"في West Virginia يشمل قانون الابتعاد كل مركبة متوقّفة بأضواء وامضة أو أضواء تحذير، ومنها سيارات الشرطة والإسعاف وشاحنات السحب، لذلك تنتقل إلى مسار آخر إذا كان ذلك آمنًا، أو تخفّف السرعة.","p":"صحيح. القانون يشملها كلها."},"ref":{"doc":"WV","page":null}},{"id":"wv-020","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, if you fail the permit knowledge test, how long must you wait to try again?","o":["Seven days","One day","Thirty days","Six months"],"h1":"It is one week.","h2":"In West Virginia you must wait seven days before retaking a failed knowledge test.","p":"Correct. You wait one week."},"es":{"q":"En Virginia Occidental, si no aprueba el examen de conocimientos del permiso, ¿cuánto debe esperar para intentarlo otra vez?","o":["Siete días","Un día","Treinta días","Seis meses"],"h1":"Es una semana.","h2":"En Virginia Occidental usted debe esperar siete días antes de repetir un examen de conocimientos que no aprobó.","p":"Correcto. Se espera una semana."},"zh":{"q":"在 West Virginia，如果你没有通过学习驾照笔试，要等多久才可以再考？","o":["七天","一天","三十天","六个月"],"h1":"是一个星期。","h2":"在 West Virginia，笔试没通过，你必须等七天才可以重考。","p":"正确。你要等一个星期。"},"vi":{"q":"Ở West Virginia, nếu bạn thi trượt bài thi lý thuyết để lấy giấy phép tập lái, bạn phải chờ bao lâu để thi lại?","o":["Bảy ngày","Một ngày","Ba mươi ngày","Sáu tháng"],"h1":"Đó là một tuần.","h2":"Ở West Virginia, bạn phải chờ bảy ngày trước khi thi lại bài thi lý thuyết bị trượt.","p":"Đúng. Bạn chờ một tuần."},"tl":{"q":"Sa West Virginia, kung bumagsak ka sa knowledge test para sa permit, gaano katagal kang maghihintay bago sumubok ulit?","o":["Pitong araw","Isang araw","Tatlumpung araw","Anim na buwan"],"h1":"Isang linggo ito.","h2":"Sa West Virginia, dapat kang maghintay ng pitong araw bago kumuha ulit ng knowledge test na binagsak mo.","p":"Tama. Maghihintay ka ng isang linggo."},"ar":{"q":"في West Virginia، إذا رسبت في اختبار المعرفة للتصريح، كم يجب أن تنتظر لتحاول مرة أخرى؟","o":["سبعة أيام","يوم واحد","ثلاثون يومًا","ستة أشهر"],"h1":"إنه أسبوع واحد.","h2":"في West Virginia يجب أن تنتظر سبعة أيام قبل إعادة اختبار المعرفة الذي رسبت فيه.","p":"صحيح. تنتظر أسبوعًا واحدًا."},"ref":{"doc":"WV","page":26}},{"id":"wv-021","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, what do you need to take the permit knowledge test online?","o":["Only a smartphone","A computer with a mouse and a webcam","A tablet with no camera","A printed paper test"],"h1":"A phone will not work for this test.","h2":"In West Virginia the online knowledge test needs a computer with a mouse and a webcam; phones and touch screens do not work.","p":"Right. You need a computer with a camera."},"es":{"q":"En Virginia Occidental, ¿qué necesita para tomar en línea el examen de conocimientos del permiso?","o":["Solo un teléfono inteligente","Una computadora con ratón y cámara web","Una tableta sin cámara","Un examen impreso en papel"],"h1":"Un teléfono no sirve para este examen.","h2":"En Virginia Occidental, el examen de conocimientos en línea necesita una computadora con ratón y cámara web; los teléfonos y las pantallas táctiles no sirven.","p":"Correcto. Necesita una computadora con cámara."},"zh":{"q":"在 West Virginia，在网上考学习驾照笔试需要什么？","o":["只要一部智能手机","一台有鼠标和摄像头的电脑","一台没有摄像头的平板电脑","一份印出来的纸质考卷"],"h1":"用手机不能考这个试。","h2":"在 West Virginia，网上笔试需要一台有鼠标和摄像头的电脑；手机和触摸屏都不能用。","p":"对。你需要一台有摄像头的电脑。"},"vi":{"q":"Ở West Virginia, bạn cần gì để làm bài thi lý thuyết lấy giấy phép tập lái trực tuyến?","o":["Chỉ cần một điện thoại thông minh","Một máy tính có chuột và webcam","Một máy tính bảng không có camera","Một bài thi in trên giấy"],"h1":"Điện thoại không dùng được cho bài thi này.","h2":"Ở West Virginia, bài thi lý thuyết trực tuyến cần một máy tính có chuột và webcam; điện thoại và màn hình cảm ứng không dùng được.","p":"Đúng. Bạn cần một máy tính có camera."},"tl":{"q":"Sa West Virginia, ano ang kailangan mo para kumuha ng knowledge test para sa permit online?","o":["Isang smartphone lamang","Isang computer na may mouse at webcam","Isang tablet na walang camera","Isang naka-print na papel na test"],"h1":"Hindi gagana ang telepono para sa test na ito.","h2":"Sa West Virginia, ang online na knowledge test ay nangangailangan ng computer na may mouse at webcam; hindi gagana ang mga telepono at touch screen.","p":"Tama. Kailangan mo ng computer na may camera."},"ar":{"q":"في West Virginia، ماذا تحتاج لتأخذ اختبار المعرفة للتصريح عبر الإنترنت؟","o":["هاتف ذكي فقط","حاسوب مع فأرة وكاميرا ويب","جهاز لوحي دون كاميرا","اختبار ورقي مطبوع"],"h1":"الهاتف لا يعمل لهذا الاختبار.","h2":"في West Virginia يحتاج اختبار المعرفة عبر الإنترنت إلى حاسوب مع فأرة وكاميرا ويب؛ الهواتف والشاشات التي تعمل باللمس لا تعمل.","p":"صحيح. تحتاج إلى حاسوب مع كاميرا."},"ref":{"doc":"WV","page":null}},{"id":"wv-022","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, how many correct answers out of 25 do you need to pass the knowledge test?","o":["15","19","22","25"],"h1":"You can miss up to six questions.","h2":"In West Virginia, you need 19 correct answers out of 25 to pass the knowledge test, and the test is timed.","p":"Right. 19 out of 25."},"es":{"q":"En Virginia Occidental, ¿cuántas respuestas correctas de 25 necesita para aprobar el examen de conocimientos?","o":["15","19","22","25"],"h1":"Puede fallar hasta seis preguntas.","h2":"En Virginia Occidental, necesita 19 respuestas correctas de 25 para aprobar el examen de conocimientos, y el examen tiene un límite de tiempo.","p":"Correcto. 19 de 25."},"zh":{"q":"在 West Virginia，知识考试 25 题中你需要答对几题才能通过？","o":["15","19","22","25"],"h1":"你最多可以答错六题。","h2":"在 West Virginia，知识考试 25 题中你需要答对 19 题才能通过，而且考试有时间限制。","p":"对。25 题中答对 19 题。"},"vi":{"q":"Ở West Virginia, bạn cần trả lời đúng bao nhiêu câu trong 25 câu để đậu bài thi kiến thức?","o":["15","19","22","25"],"h1":"Bạn có thể sai tối đa sáu câu.","h2":"Ở West Virginia, bạn cần trả lời đúng 19 trên 25 câu để đậu bài thi kiến thức, và bài thi có giới hạn thời gian.","p":"Đúng. 19 trên 25 câu."},"tl":{"q":"Sa West Virginia, ilang tamang sagot sa 25 ang kailangan mo para pumasa sa knowledge test?","o":["15","19","22","25"],"h1":"Puwede kang magkamali nang hanggang anim na tanong.","h2":"Sa West Virginia, kailangan mo ng 19 na tamang sagot sa 25 para pumasa sa knowledge test, at may takdang oras ang test.","p":"Tama. 19 sa 25."},"ar":{"q":"في West Virginia، كم إجابة صحيحة من 25 تحتاج لتنجح في اختبار المعرفة؟","o":["15","19","22","25"],"h1":"يمكنك أن تخطئ في ستة أسئلة على الأكثر.","h2":"في West Virginia، تحتاج إلى 19 إجابة صحيحة من 25 لتنجح في اختبار المعرفة، والاختبار له وقت محدد.","p":"صحيح. 19 من 25."},"ref":{"doc":"WV","page":24}},{"id":"wv-023","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, what is the minimum liability insurance for the death or injury of one person?","o":["$5,000","$10,000","$100,000","$25,000"],"h1":"It is the same amount as the minimum for property damage.","h2":"In West Virginia, the minimum liability insurance is $25,000 for one death or injury, $50,000 for two or more, and $25,000 for property damage.","p":"Right. $25,000 for one person."},"es":{"q":"En Virginia Occidental, ¿cuál es el seguro de responsabilidad mínimo por la muerte o lesión de una persona?","o":["$5,000","$10,000","$100,000","$25,000"],"h1":"Es la misma cantidad que el mínimo por daños a la propiedad.","h2":"En Virginia Occidental, el seguro de responsabilidad mínimo es de $25,000 por una muerte o lesión, $50,000 por dos o más, y $25,000 por daños a la propiedad.","p":"Correcto. $25,000 por una persona."},"zh":{"q":"在 West Virginia，一个人死亡或受伤的最低责任保险是多少？","o":["$5,000","$10,000","$100,000","$25,000"],"h1":"它和财产损失的最低金额一样。","h2":"在 West Virginia，最低责任保险是：一个人死亡或受伤 $25,000，两个人或以上 $50,000，财产损失 $25,000。","p":"对。一个人是 $25,000。"},"vi":{"q":"Ở West Virginia, mức bảo hiểm trách nhiệm tối thiểu cho việc một người chết hoặc bị thương là bao nhiêu?","o":["$5,000","$10,000","$100,000","$25,000"],"h1":"Số tiền này bằng mức tối thiểu cho thiệt hại tài sản.","h2":"Ở West Virginia, bảo hiểm trách nhiệm tối thiểu là $25,000 cho một người chết hoặc bị thương, $50,000 cho hai người trở lên, và $25,000 cho thiệt hại tài sản.","p":"Đúng. $25,000 cho một người."},"tl":{"q":"Sa West Virginia, magkano ang pinakamababang liability insurance para sa pagkamatay o pagkapinsala ng isang tao?","o":["$5,000","$10,000","$100,000","$25,000"],"h1":"Pareho ito ng pinakamababang halaga para sa sira sa ari-arian.","h2":"Sa West Virginia, ang pinakamababang liability insurance ay $25,000 para sa pagkamatay o pagkapinsala ng isang tao, $50,000 para sa dalawa o higit pa, at $25,000 para sa sira sa ari-arian.","p":"Tama. $25,000 para sa isang tao."},"ar":{"q":"في West Virginia، ما الحد الأدنى لتأمين المسؤولية عن وفاة شخص واحد أو إصابته؟","o":["$5,000","$10,000","$100,000","$25,000"],"h1":"إنه نفس المبلغ الأدنى لأضرار الممتلكات.","h2":"في West Virginia، الحد الأدنى لتأمين المسؤولية هو $25,000 لوفاة شخص واحد أو إصابته، و$50,000 لشخصين أو أكثر، و$25,000 لأضرار الممتلكات.","p":"صحيح. $25,000 لشخص واحد."},"ref":{"doc":"WV","page":16}},{"id":"wv-024","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, how many points on your record can lead to a license suspension?","o":["3 points","6 points","12 points","25 points"],"h1":"At half this number, the DMV sends a letter of caution.","h2":"In West Virginia, the DMV sends a letter of caution at 6 points, and a driver with 12 points can have the license suspended.","p":"Right. 12 points can mean a suspension."},"es":{"q":"En Virginia Occidental, ¿cuántos puntos en su historial pueden llevar a la suspensión de la licencia?","o":["3 puntos","6 puntos","12 puntos","25 puntos"],"h1":"Con la mitad de este número, el DMV envía una carta de advertencia.","h2":"En Virginia Occidental, el DMV envía una carta de advertencia con 6 puntos, y a un conductor con 12 puntos se le puede suspender la licencia.","p":"Correcto. 12 puntos pueden llevar a una suspensión."},"zh":{"q":"在 West Virginia，记录上有多少分可能导致驾照被暂停？","o":["3 分","6 分","12 分","25 分"],"h1":"到这个数字的一半时，DMV 会寄一封警告信。","h2":"在 West Virginia，到 6 分时 DMV 会寄一封警告信，有 12 分的司机可能会被暂停驾照。","p":"对。12 分可能导致驾照被暂停。"},"vi":{"q":"Ở West Virginia, bao nhiêu điểm trong hồ sơ có thể khiến bằng lái bị đình chỉ?","o":["3 điểm","6 điểm","12 điểm","25 điểm"],"h1":"Khi đến một nửa số điểm này, DMV sẽ gửi thư cảnh báo.","h2":"Ở West Virginia, DMV gửi thư cảnh báo khi có 6 điểm, và tài xế có 12 điểm có thể bị đình chỉ bằng lái.","p":"Đúng. 12 điểm có thể bị đình chỉ bằng lái."},"tl":{"q":"Sa West Virginia, ilang puntos sa iyong rekord ang puwedeng mauwi sa suspensyon ng lisensya?","o":["3 puntos","6 puntos","12 puntos","25 puntos"],"h1":"Sa kalahati ng bilang na ito, magpapadala ang DMV ng sulat ng babala.","h2":"Sa West Virginia, nagpapadala ang DMV ng sulat ng babala sa 6 na puntos, at puwedeng masuspinde ang lisensya ng drayber na may 12 puntos.","p":"Tama. Ang 12 puntos ay puwedeng mauwi sa suspensyon."},"ar":{"q":"في West Virginia، كم نقطة في سجلك يمكن أن تؤدي إلى تعليق الرخصة؟","o":["3 نقاط","6 نقاط","12 نقطة","25 نقطة"],"h1":"عند نصف هذا العدد، ترسل DMV رسالة تحذير.","h2":"في West Virginia، ترسل DMV رسالة تحذير عند 6 نقاط، والسائق الذي لديه 12 نقطة يمكن أن تُعلَّق رخصته.","p":"صحيح. 12 نقطة يمكن أن تعني تعليق الرخصة."},"ref":{"doc":"WV","page":18}},{"id":"wv-025","scope":"WV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In West Virginia, what happens if you are arrested for DUI and refuse the breath test?","o":["Your license is revoked for at least one year","You pay a small fine and keep driving","You get a warning the first time","Your license is suspended for one week"],"h1":"West Virginia's implied consent law treats refusal very seriously.","h2":"In West Virginia, a driver arrested for DUI who refuses the breath test has the driving privilege revoked for at least one year, and up to life.","p":"Right. Revoked for at least one year."},"es":{"q":"En Virginia Occidental, ¿qué pasa si lo arrestan por manejar bajo los efectos del alcohol (DUI) y se niega a la prueba de aliento?","o":["Le revocan la licencia por lo menos un año","Paga una multa pequeña y sigue manejando","Recibe una advertencia la primera vez","Le suspenden la licencia por una semana"],"h1":"La ley de consentimiento implícito de Virginia Occidental trata la negativa con mucha seriedad.","h2":"En Virginia Occidental, a un conductor arrestado por DUI que se niega a la prueba de aliento le revocan el privilegio de manejar por lo menos un año, y hasta de por vida.","p":"Correcto. Revocada por lo menos un año."},"zh":{"q":"在 West Virginia，如果你因酒后驾驶（DUI）被捕并拒绝呼气测试，会怎样？","o":["你的驾照会被吊销至少一年","你交一小笔罚款，还可以继续开车","第一次只会收到警告","你的驾照会被暂停一周"],"h1":"West Virginia 的默示同意法（implied consent law）把拒绝测试看得非常严重。","h2":"在 West Virginia，因酒后驾驶（DUI）被捕并拒绝呼气测试的司机，驾驶资格会被吊销至少一年，最长可以是终身。","p":"对。至少吊销一年。"},"vi":{"q":"Ở West Virginia, điều gì xảy ra nếu bạn bị bắt vì lái xe khi say (DUI) và từ chối kiểm tra hơi thở?","o":["Bằng lái của bạn bị thu hồi ít nhất một năm","Bạn trả một khoản phạt nhỏ và tiếp tục lái xe","Bạn chỉ bị cảnh cáo lần đầu","Bằng lái của bạn bị đình chỉ một tuần"],"h1":"Luật đồng ý ngầm (implied consent law) của West Virginia coi việc từ chối là rất nghiêm trọng.","h2":"Ở West Virginia, tài xế bị bắt vì lái xe khi say (DUI) mà từ chối kiểm tra hơi thở sẽ bị thu hồi quyền lái xe ít nhất một năm, và có thể đến suốt đời.","p":"Đúng. Bị thu hồi ít nhất một năm."},"tl":{"q":"Sa West Virginia, ano ang mangyayari kung arestuhin ka dahil sa DUI at tumanggi ka sa breath test?","o":["Babawiin ang iyong lisensya nang hindi bababa sa isang taon","Magbabayad ka ng maliit na multa at magpapatuloy sa pagmamaneho","Babala lang ang makukuha mo sa unang beses","Masususpinde ang iyong lisensya nang isang linggo"],"h1":"Napakaseryoso ng pagtanggi sa ilalim ng implied consent law ng West Virginia.","h2":"Sa West Virginia, ang drayber na inaresto dahil sa DUI at tumanggi sa breath test ay babawian ng karapatang magmaneho nang hindi bababa sa isang taon, at puwedeng habambuhay.","p":"Tama. Babawiin nang hindi bababa sa isang taon."},"ar":{"q":"في West Virginia، ماذا يحدث إذا قُبض عليك بتهمة القيادة تحت التأثير (DUI) ورفضت اختبار التنفس؟","o":["تُلغى رخصتك لمدة سنة واحدة على الأقل","تدفع غرامة صغيرة وتستمر في القيادة","تحصل على تحذير في المرة الأولى","تُعلَّق رخصتك لمدة أسبوع واحد"],"h1":"قانون الموافقة الضمنية (implied consent law) في West Virginia يعامل الرفض بجدية كبيرة.","h2":"في West Virginia، السائق الذي يُقبض عليه بتهمة القيادة تحت التأثير (DUI) ويرفض اختبار التنفس يُلغى حقه في القيادة لمدة سنة واحدة على الأقل، وقد يصل ذلك إلى مدى الحياة.","p":"صحيح. تُلغى لمدة سنة واحدة على الأقل."},"ref":{"doc":"WV","page":22}},{"id":"wv-026","scope":"WV","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In West Virginia, what is the speed limit in a school zone while children are present, unless posted otherwise?","o":["10 mph","15 mph","25 mph","35 mph"],"h1":"It is lower than the 25 mph limit for residential areas.","h2":"In West Virginia, the speed limit in a school zone is 15 mph while children are present along the road.","p":"Right. 15 mph in a school zone."},"es":{"q":"En Virginia Occidental, ¿cuál es el límite de velocidad en una zona escolar cuando hay niños presentes, si no hay otro señalado?","o":["10 mph","15 mph","25 mph","35 mph"],"h1":"Es más bajo que el límite de 25 mph de las zonas residenciales.","h2":"En Virginia Occidental, el límite de velocidad en una zona escolar es de 15 mph cuando hay niños presentes a lo largo de la calle.","p":"Correcto. 15 mph en una zona escolar."},"zh":{"q":"在 West Virginia，如果没有其他标示，有孩子在场时学校区域的限速是多少？","o":["10 mph","15 mph","25 mph","35 mph"],"h1":"它比住宅区 25 mph 的限速低。","h2":"在 West Virginia，路边有孩子时，学校区域的限速是 15 mph。","p":"对。学校区域是 15 mph。"},"vi":{"q":"Ở West Virginia, nếu không có biển báo khác, tốc độ giới hạn trong khu vực trường học khi có trẻ em là bao nhiêu?","o":["10 mph","15 mph","25 mph","35 mph"],"h1":"Nó thấp hơn giới hạn 25 mph ở khu dân cư.","h2":"Ở West Virginia, tốc độ giới hạn trong khu vực trường học là 15 mph khi có trẻ em dọc theo đường.","p":"Đúng. 15 mph trong khu vực trường học."},"tl":{"q":"Sa West Virginia, ano ang speed limit sa school zone habang may mga bata, maliban kung iba ang nakapaskil?","o":["10 mph","15 mph","25 mph","35 mph"],"h1":"Mas mababa ito sa 25 mph na limit sa mga residential area.","h2":"Sa West Virginia, ang speed limit sa school zone ay 15 mph habang may mga bata sa tabi ng daan.","p":"Tama. 15 mph sa school zone."},"ar":{"q":"في West Virginia، ما حد السرعة في منطقة المدرسة عند وجود أطفال، ما لم تُوضع لافتة بغير ذلك؟","o":["10 mph","15 mph","25 mph","35 mph"],"h1":"إنه أقل من حد 25 mph في المناطق السكنية.","h2":"في West Virginia، حد السرعة في منطقة المدرسة هو 15 mph عند وجود أطفال على جانب الطريق.","p":"صحيح. 15 mph في منطقة المدرسة."},"ref":{"doc":"WV","page":42}},{"id":"wv-027","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, how many points can an approved 8-hour defensive driving class remove from your record?","o":["1 point","All of your points","3 points","6 points"],"h1":"You can only do this once every 12 months.","h2":"In West Virginia, finishing an approved 8-hour defensive driving class removes 3 points from your record, no more than once every 12 months.","p":"Right. The class removes 3 points."},"es":{"q":"En Virginia Occidental, ¿cuántos puntos puede quitar de su historial una clase aprobada de manejo defensivo de 8 horas?","o":["1 punto","Todos sus puntos","3 puntos","6 puntos"],"h1":"Solo puede hacerlo una vez cada 12 meses.","h2":"En Virginia Occidental, terminar una clase aprobada de manejo defensivo de 8 horas le quita 3 puntos de su historial, no más de una vez cada 12 meses.","p":"Correcto. La clase quita 3 puntos."},"zh":{"q":"在 West Virginia，一门认可的 8 小时防御性驾驶课程可以从你的记录中去掉几分？","o":["1 分","你所有的分数","3 分","6 分"],"h1":"每 12 个月只能这样做一次。","h2":"在 West Virginia，完成一门认可的 8 小时防御性驾驶课程可以从你的记录中去掉 3 分，每 12 个月最多一次。","p":"对。这门课去掉 3 分。"},"vi":{"q":"Ở West Virginia, một lớp lái xe phòng vệ 8 giờ được chấp thuận có thể xóa bao nhiêu điểm khỏi hồ sơ của bạn?","o":["1 điểm","Tất cả số điểm của bạn","3 điểm","6 điểm"],"h1":"Bạn chỉ có thể làm điều này một lần mỗi 12 tháng.","h2":"Ở West Virginia, hoàn thành một lớp lái xe phòng vệ 8 giờ được chấp thuận sẽ xóa 3 điểm khỏi hồ sơ của bạn, không quá một lần mỗi 12 tháng.","p":"Đúng. Lớp học xóa 3 điểm."},"tl":{"q":"Sa West Virginia, ilang puntos ang puwedeng alisin sa iyong rekord ng isang aprubadong 8-oras na defensive driving class?","o":["1 punto","Lahat ng iyong puntos","3 puntos","6 puntos"],"h1":"Isang beses mo lang ito puwedeng gawin bawat 12 buwan.","h2":"Sa West Virginia, ang pagtatapos ng isang aprubadong 8-oras na defensive driving class ay nag-aalis ng 3 puntos sa iyong rekord, hindi hihigit sa isang beses bawat 12 buwan.","p":"Tama. Nag-aalis ang klase ng 3 puntos."},"ar":{"q":"في West Virginia، كم نقطة يمكن أن تزيلها من سجلك دورة قيادة دفاعية معتمدة مدتها 8 ساعات؟","o":["نقطة واحدة","كل نقاطك","3 نقاط","6 نقاط"],"h1":"يمكنك فعل ذلك مرة واحدة فقط كل 12 شهرًا.","h2":"في West Virginia، إنهاء دورة قيادة دفاعية معتمدة مدتها 8 ساعات يزيل 3 نقاط من سجلك، ولا يكون ذلك أكثر من مرة واحدة كل 12 شهرًا.","p":"صحيح. الدورة تزيل 3 نقاط."},"ref":{"doc":"WV","page":18}},{"id":"wv-028","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, after you move to the state, how soon must you apply for a West Virginia driver's license?","o":["Within 30 days","Within 10 days","Within 90 days","Within 1 year"],"h1":"It is about one month.","h2":"In West Virginia, a new resident who wants to drive must apply for a West Virginia driver's license within 30 days.","p":"Right. New residents have 30 days to apply."},"es":{"q":"En West Virginia, después de mudarse al estado, ¿en cuánto tiempo debe solicitar una licencia de conducir de West Virginia?","o":["En 30 días","En 10 días","En 90 días","En 1 año"],"h1":"Es más o menos un mes.","h2":"En West Virginia, un nuevo residente que quiere manejar debe solicitar una licencia de conducir de West Virginia en 30 días.","p":"Correcto. Los nuevos residentes tienen 30 días para solicitarla."},"zh":{"q":"在 West Virginia，搬到本州以后，你必须在多长时间内申请 West Virginia 驾照？","o":["30 天内","10 天内","90 天内","1 年内"],"h1":"大约是一个月。","h2":"在 West Virginia，想开车的新居民必须在 30 天内申请 West Virginia 驾照。","p":"对。新居民有 30 天时间申请。"},"vi":{"q":"Ở West Virginia, sau khi chuyển đến tiểu bang, bạn phải nộp đơn xin bằng lái West Virginia trong bao lâu?","o":["Trong vòng 30 ngày","Trong vòng 10 ngày","Trong vòng 90 ngày","Trong vòng 1 năm"],"h1":"Khoảng một tháng.","h2":"Ở West Virginia, cư dân mới muốn lái xe phải nộp đơn xin bằng lái West Virginia trong vòng 30 ngày.","p":"Đúng. Cư dân mới có 30 ngày để nộp đơn."},"tl":{"q":"Sa West Virginia, pagkalipat mo sa estado, gaano kabilis ka dapat mag-apply ng West Virginia driver's license?","o":["Sa loob ng 30 araw","Sa loob ng 10 araw","Sa loob ng 90 araw","Sa loob ng 1 taon"],"h1":"Mga isang buwan ito.","h2":"Sa West Virginia, ang bagong residente na gustong magmaneho ay dapat mag-apply ng West Virginia driver's license sa loob ng 30 araw.","p":"Tama. May 30 araw ang mga bagong residente para mag-apply."},"ar":{"q":"في West Virginia، بعد أن تنتقل إلى الولاية، خلال كم من الوقت يجب أن تقدّم طلبًا للحصول على رخصة قيادة من West Virginia؟","o":["خلال 30 يومًا","خلال 10 أيام","خلال 90 يومًا","خلال سنة واحدة (1)"],"h1":"إنه نحو شهر واحد.","h2":"في West Virginia، يجب على المقيم الجديد الذي يريد القيادة أن يقدّم طلبًا للحصول على رخصة قيادة من West Virginia خلال 30 يومًا.","p":"صحيح. لدى المقيمين الجدد 30 يومًا لتقديم الطلب."},"ref":{"doc":"WV","page":2}},{"id":"wv-029","scope":"WV","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In West Virginia, you are driving at night behind another vehicle. Within how many feet must you dim your headlights?","o":["100 feet","500 feet","200 feet","1,000 feet"],"h1":"It is a shorter distance than for an oncoming vehicle.","h2":"In West Virginia, you must dim your headlights within 200 feet when you follow another vehicle.","p":"Right. Dim your lights within 200 feet of a vehicle ahead."},"es":{"q":"En West Virginia, usted maneja de noche detrás de otro vehículo. ¿A cuántos pies debe bajar las luces?","o":["100 pies","500 pies","200 pies","1,000 pies"],"h1":"Es una distancia más corta que para un vehículo que viene de frente.","h2":"En West Virginia, usted debe bajar las luces a 200 pies cuando va detrás de otro vehículo.","p":"Correcto. Baje las luces a 200 pies de un vehículo que va adelante."},"zh":{"q":"在 West Virginia，你晚上在另一辆车后面开车。你必须在多少英尺以内把大灯调暗？","o":["100 英尺","500 英尺","200 英尺","1,000 英尺"],"h1":"这个距离比对面来车时要短。","h2":"在 West Virginia，跟在另一辆车后面时，你必须在 200 英尺以内把大灯调暗。","p":"对。前面有车时，在 200 英尺以内要调暗车灯。"},"vi":{"q":"Ở West Virginia, bạn đang lái xe ban đêm phía sau một xe khác. Bạn phải giảm đèn pha trong phạm vi bao nhiêu feet?","o":["100 feet","500 feet","200 feet","1,000 feet"],"h1":"Khoảng cách này ngắn hơn so với khi có xe chạy ngược chiều.","h2":"Ở West Virginia, bạn phải giảm đèn pha trong phạm vi 200 feet khi bạn chạy theo sau một xe khác.","p":"Đúng. Giảm đèn trong phạm vi 200 feet khi có xe phía trước."},"tl":{"q":"Sa West Virginia, nagmamaneho ka sa gabi sa likod ng ibang sasakyan. Sa loob ng ilang talampakan (feet) mo dapat hinaan ang iyong headlights?","o":["100 feet","500 feet","200 feet","1,000 feet"],"h1":"Mas maikli ang layong ito kaysa sa sasakyang paparating mula sa kabila.","h2":"Sa West Virginia, dapat mong hinaan ang iyong headlights sa loob ng 200 feet kapag sumusunod ka sa ibang sasakyan.","p":"Tama. Hinaan ang ilaw sa loob ng 200 feet ng sasakyang nasa unahan."},"ar":{"q":"في West Virginia، أنت تقود ليلًا خلف مركبة أخرى. ضمن كم قدمًا يجب أن تخفّض أضواء سيارتك الأمامية؟","o":["100 قدم","500 قدم","200 قدم","1,000 قدم"],"h1":"إنها مسافة أقصر من مسافة المركبة القادمة من الاتجاه المقابل.","h2":"في West Virginia، يجب أن تخفّض أضواءك الأمامية ضمن 200 قدم عندما تسير خلف مركبة أخرى.","p":"صحيح. خفّض أضواءك ضمن 200 قدم من المركبة التي أمامك."},"ref":{"doc":"WV","page":62}},{"id":"wv-030","scope":"WV","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In West Virginia, you may not park within how many feet of a fire hydrant?","o":["5 feet","10 feet","25 feet","15 feet"],"h1":"Fire trucks need room to connect their hoses.","h2":"In West Virginia, you may not park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a fire hydrant when you park."},"es":{"q":"En West Virginia, ¿a cuántos pies de un hidrante no puede estacionarse?","o":["5 pies","10 pies","25 pies","15 pies"],"h1":"Los bomberos necesitan espacio para conectar sus mangueras.","h2":"En West Virginia, usted no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Al estacionarse, quédese por lo menos a 15 pies de un hidrante."},"zh":{"q":"在 West Virginia，你不可以在离消防栓多少英尺以内停车？","o":["5 英尺","10 英尺","25 英尺","15 英尺"],"h1":"消防车需要空间来接水管。","h2":"在 West Virginia，你不可以在离消防栓 15 英尺以内停车。","p":"对。停车时要离消防栓至少 15 英尺。"},"vi":{"q":"Ở West Virginia, bạn không được đậu xe trong phạm vi bao nhiêu feet từ trụ nước cứu hỏa?","o":["5 feet","10 feet","25 feet","15 feet"],"h1":"Xe cứu hỏa cần chỗ để nối vòi nước.","h2":"Ở West Virginia, bạn không được đậu xe trong phạm vi 15 feet từ trụ nước cứu hỏa.","p":"Đúng. Khi đậu xe, hãy cách trụ nước cứu hỏa ít nhất 15 feet."},"tl":{"q":"Sa West Virginia, hindi ka puwedeng pumarada sa loob ng ilang talampakan (feet) mula sa fire hydrant?","o":["5 feet","10 feet","25 feet","15 feet"],"h1":"Kailangan ng mga trak ng bumbero ng espasyo para ikabit ang kanilang hose.","h2":"Sa West Virginia, hindi ka puwedeng pumarada sa loob ng 15 feet mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 15 feet mula sa fire hydrant kapag pumarada ka."},"ar":{"q":"في West Virginia، لا يجوز لك أن تركن سيارتك ضمن كم قدمًا من صنبور إطفاء الحريق؟","o":["5 أقدام","10 أقدام","25 قدمًا","15 قدمًا"],"h1":"تحتاج سيارات الإطفاء إلى مساحة لتوصيل خراطيمها.","h2":"في West Virginia، لا يجوز لك أن تركن سيارتك ضمن 15 قدمًا من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بعد 15 قدمًا على الأقل من صنبور إطفاء الحريق عندما تركن."},"ref":{"doc":"WV","page":45}},{"id":"wv-031","scope":"WV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In West Virginia, what is the lowest fine for littering on a road?","o":["$10","$50","$250","$2,000"],"h1":"The fine can go up to $1,000.","h2":"In West Virginia, littering can bring a fine of at least $50 and up to $1,000, or instead jail or picking up litter along the road.","p":"Right. Littering costs at least $50, and you may also get points."},"es":{"q":"En West Virginia, ¿cuál es la multa más baja por tirar basura en la carretera?","o":["$10","$50","$250","$2,000"],"h1":"La multa puede llegar hasta $1,000.","h2":"En West Virginia, tirar basura puede costar una multa de por lo menos $50 y hasta $1,000, o en su lugar cárcel o recoger basura en la carretera.","p":"Correcto. Tirar basura cuesta por lo menos $50, y también puede recibir puntos."},"zh":{"q":"在 West Virginia，在道路上乱扔垃圾的最低罚款是多少？","o":["$10","$50","$250","$2,000"],"h1":"罚款最高可以到 $1,000。","h2":"在 West Virginia，乱扔垃圾可能被罚款至少 $50、最多 $1,000，或者改为坐牢或在路边捡垃圾。","p":"对。乱扔垃圾至少罚 $50，你还可能被扣分。"},"vi":{"q":"Ở West Virginia, tiền phạt thấp nhất cho việc xả rác trên đường là bao nhiêu?","o":["$10","$50","$250","$2,000"],"h1":"Tiền phạt có thể lên đến $1,000.","h2":"Ở West Virginia, xả rác có thể bị phạt ít nhất $50 và tối đa $1,000, hoặc thay vào đó là ngồi tù hoặc nhặt rác dọc đường.","p":"Đúng. Xả rác bị phạt ít nhất $50, và bạn cũng có thể bị trừ điểm."},"tl":{"q":"Sa West Virginia, ano ang pinakamababang multa sa pagkakalat ng basura sa kalsada?","o":["$10","$50","$250","$2,000"],"h1":"Puwedeng umabot ang multa hanggang $1,000.","h2":"Sa West Virginia, ang pagkakalat ng basura ay puwedeng magdala ng multang hindi bababa sa $50 at hanggang $1,000, o sa halip ay kulong o pamumulot ng basura sa tabi ng kalsada.","p":"Tama. Hindi bababa sa $50 ang multa sa pagkakalat ng basura, at puwede ka ring magkaroon ng points."},"ar":{"q":"في West Virginia، ما أقل غرامة لرمي النفايات على الطريق؟","o":["$10","$50","$250","$2,000"],"h1":"يمكن أن تصل الغرامة إلى $1,000.","h2":"في West Virginia، يمكن أن يؤدي رمي النفايات إلى غرامة لا تقل عن $50 وتصل إلى $1,000، أو بدلًا من ذلك السجن أو جمع النفايات على جانب الطريق.","p":"صحيح. غرامة رمي النفايات $50 على الأقل، وقد تحصل أيضًا على نقاط."},"ref":{"doc":"WV","page":77}},{"id":"wy-001","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, what is the youngest age to get a learner's permit?","o":["14 years old","15 years old","15 and a half years old","16 years old"],"h1":"It is one year before the intermediate permit.","h2":"In Wyoming you can get a learner's permit at 15 years old.","p":"Right. The Wyoming learner's permit starts at 15."},"es":{"q":"En Wyoming, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["14 años","15 años","15 años y medio","16 años"],"h1":"Es un año antes del permiso intermedio.","h2":"En Wyoming usted puede obtener el permiso de aprendiz a los 15 años.","p":"Correcto. El permiso de aprendiz en Wyoming empieza a los 15."},"zh":{"q":"在 Wyoming，最小几岁可以拿到学习驾照（learner's permit）？","o":["14 岁","15 岁","15 岁半","16 岁"],"h1":"它比拿中级驾照的年龄早一年。","h2":"在 Wyoming，你 15 岁就可以拿到学习驾照。","p":"对。Wyoming 的学习驾照从 15 岁开始。"},"vi":{"q":"Ở Wyoming, tuổi nhỏ nhất để có giấy phép tập lái (learner's permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","15 tuổi rưỡi","16 tuổi"],"h1":"Đó là một năm trước tuổi có giấy phép trung cấp.","h2":"Ở Wyoming, bạn có thể có giấy phép tập lái khi 15 tuổi.","p":"Đúng. Giấy phép tập lái ở Wyoming bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Wyoming, ano ang pinakabatang edad para makakuha ng learner's permit (permit sa pag-aaral magmaneho)?","o":["14 taong gulang","15 taong gulang","15 at kalahating taong gulang","16 taong gulang"],"h1":"Isang taon ito bago ang intermediate permit.","h2":"Sa Wyoming, makakakuha ka ng learner's permit sa edad na 15.","p":"Tama. Sa Wyoming, nagsisimula ang learner's permit sa edad na 15."},"ar":{"q":"في Wyoming، ما أصغر عمر للحصول على تصريح التعلّم (learner's permit)؟","o":["14 سنة","15 سنة","15 سنة ونصف","16 سنة"],"h1":"هو قبل التصريح المتوسط بسنة واحدة.","h2":"في Wyoming يمكنك الحصول على تصريح التعلّم في عمر 15 سنة.","p":"صحيح. يبدأ تصريح التعلّم في Wyoming من عمر 15 سنة."},"ref":{"doc":"WY","page":7}},{"id":"wy-002","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, how long must you hold a learner's permit before you can get an intermediate permit?","o":["At least 10 days","At least 6 months","At least one year","At least two years"],"h1":"Wyoming's waiting time is much shorter than in most states.","h2":"In Wyoming you must hold your learner's permit for at least 10 days before you can get an intermediate permit.","p":"Right. Only 10 days in Wyoming."},"es":{"q":"En Wyoming, ¿cuánto tiempo debe tener el permiso de aprendiz antes de obtener el permiso intermedio?","o":["Por lo menos 10 días","Por lo menos 6 meses","Por lo menos un año","Por lo menos dos años"],"h1":"En Wyoming la espera es mucho más corta que en la mayoría de los estados.","h2":"En Wyoming usted debe tener el permiso de aprendiz por lo menos 10 días antes de obtener el permiso intermedio.","p":"Correcto. Solo 10 días en Wyoming."},"zh":{"q":"在 Wyoming，拿中级驾照（intermediate permit）前，必须持有学习驾照多久？","o":["至少 10 天","至少六个月","至少一年","至少两年"],"h1":"Wyoming 的等待时间比大多数州短得多。","h2":"在 Wyoming，你必须持有学习驾照至少 10 天，才能拿中级驾照。","p":"对。在 Wyoming 只要 10 天。"},"vi":{"q":"Ở Wyoming, bạn phải giữ giấy phép tập lái bao lâu trước khi có thể có giấy phép trung cấp (intermediate permit)?","o":["Ít nhất 10 ngày","Ít nhất 6 tháng","Ít nhất một năm","Ít nhất hai năm"],"h1":"Thời gian chờ ở Wyoming ngắn hơn nhiều so với hầu hết các tiểu bang.","h2":"Ở Wyoming, bạn phải giữ giấy phép tập lái ít nhất 10 ngày trước khi có thể có giấy phép trung cấp.","p":"Đúng. Ở Wyoming chỉ cần 10 ngày."},"tl":{"q":"Sa Wyoming, gaano katagal mo dapat hawak ang learner's permit bago ka makakuha ng intermediate permit?","o":["Hindi bababa sa 10 araw","Hindi bababa sa 6 na buwan","Hindi bababa sa isang taon","Hindi bababa sa dalawang taon"],"h1":"Mas maikli nang husto ang paghihintay sa Wyoming kaysa sa karamihan ng estado.","h2":"Sa Wyoming, dapat mong hawak ang learner's permit nang hindi bababa sa 10 araw bago ka makakuha ng intermediate permit.","p":"Tama. 10 araw lang sa Wyoming."},"ar":{"q":"في Wyoming، كم مدة يجب أن تحمل تصريح التعلّم قبل أن تحصل على التصريح المتوسط (intermediate permit)؟","o":["10 أيام على الأقل","6 أشهر على الأقل","سنة واحدة على الأقل","سنتان على الأقل"],"h1":"مدة الانتظار في Wyoming أقصر بكثير من معظم الولايات.","h2":"في Wyoming يجب أن تحمل تصريح التعلّم 10 أيام على الأقل قبل أن تحصل على التصريح المتوسط.","p":"صحيح. 10 أيام فقط في Wyoming."},"ref":{"doc":"WY","page":null}},{"id":"wy-003","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, what is the youngest age to get an intermediate permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year after the learner's permit age.","h2":"In Wyoming you must be at least 16 to get an intermediate permit.","p":"Right. The intermediate permit starts at 16."},"es":{"q":"En Wyoming, ¿cuál es la edad mínima para obtener el permiso intermedio?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año después de la edad del permiso de aprendiz.","h2":"En Wyoming usted debe tener por lo menos 16 años para obtener el permiso intermedio.","p":"Correcto. El permiso intermedio empieza a los 16."},"zh":{"q":"在 Wyoming，最小几岁可以拿到中级驾照（intermediate permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比拿学习驾照的年龄晚一年。","h2":"在 Wyoming，你必须至少 16 岁才能拿到中级驾照。","p":"对。中级驾照从 16 岁开始。"},"vi":{"q":"Ở Wyoming, tuổi nhỏ nhất để có giấy phép trung cấp (intermediate permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là một năm sau tuổi có giấy phép tập lái.","h2":"Ở Wyoming, bạn phải ít nhất 16 tuổi để có giấy phép trung cấp.","p":"Đúng. Giấy phép trung cấp bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Wyoming, ano ang pinakabatang edad para makakuha ng intermediate permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito pagkatapos ng edad para sa learner's permit.","h2":"Sa Wyoming, dapat ay hindi bababa sa 16 taong gulang ka para makakuha ng intermediate permit.","p":"Tama. Nagsisimula ang intermediate permit sa edad na 16."},"ar":{"q":"في Wyoming، ما أصغر عمر للحصول على التصريح المتوسط (intermediate permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هو بعد عمر تصريح التعلّم بسنة واحدة.","h2":"في Wyoming يجب أن يكون عمرك 16 سنة على الأقل للحصول على التصريح المتوسط.","p":"صحيح. يبدأ التصريح المتوسط من عمر 16 سنة."},"ref":{"doc":"WY","page":7}},{"id":"wy-004","scope":"WY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wyoming, how many hours behind the wheel must you complete before the intermediate permit, and how many at night?","o":["25 hours, 5 at night","30 hours, 10 at night","40 hours, 15 at night","50 hours, 10 at night"],"h1":"The night hours are one fifth of the total.","h2":"In Wyoming you must complete 50 hours behind the wheel, including 10 hours at night, before getting an intermediate permit.","p":"Right. Fifty hours, ten at night."},"es":{"q":"En Wyoming, ¿cuántas horas al volante debe completar antes del permiso intermedio, y cuántas de noche?","o":["25 horas, 5 de noche","30 horas, 10 de noche","40 horas, 15 de noche","50 horas, 10 de noche"],"h1":"Las horas de noche son una quinta parte del total.","h2":"En Wyoming usted debe completar 50 horas al volante, con 10 horas de noche, antes de obtener el permiso intermedio.","p":"Correcto. Cincuenta horas, diez de noche."},"zh":{"q":"在 Wyoming，拿中级驾照前，必须完成多少小时的实际驾驶，其中多少小时在夜间？","o":["25 小时，夜间 5 小时","30 小时，夜间 10 小时","40 小时，夜间 15 小时","50 小时，夜间 10 小时"],"h1":"夜间小时数是总数的五分之一。","h2":"在 Wyoming，拿中级驾照前，你必须完成 50 小时的实际驾驶，其中包括 10 小时夜间驾驶。","p":"对。五十小时，其中十小时在夜间。"},"vi":{"q":"Ở Wyoming, bạn phải lái xe thực tế bao nhiêu giờ trước khi có giấy phép trung cấp, và bao nhiêu giờ vào ban đêm?","o":["25 giờ, 5 giờ ban đêm","30 giờ, 10 giờ ban đêm","40 giờ, 15 giờ ban đêm","50 giờ, 10 giờ ban đêm"],"h1":"Số giờ ban đêm là một phần năm của tổng số.","h2":"Ở Wyoming, bạn phải lái xe thực tế 50 giờ, trong đó có 10 giờ ban đêm, trước khi có giấy phép trung cấp.","p":"Đúng. Năm mươi giờ, mười giờ ban đêm."},"tl":{"q":"Sa Wyoming, ilang oras ng aktuwal na pagmamaneho ang dapat mong tapusin bago ang intermediate permit, at ilan dito ang sa gabi?","o":["25 oras, 5 sa gabi","30 oras, 10 sa gabi","40 oras, 15 sa gabi","50 oras, 10 sa gabi"],"h1":"Ang oras sa gabi ay ikalimang bahagi ng kabuuan.","h2":"Sa Wyoming, dapat kang magmaneho nang 50 oras, kasama ang 10 oras sa gabi, bago makakuha ng intermediate permit.","p":"Tama. Limampung oras, sampu sa gabi."},"ar":{"q":"في Wyoming، كم ساعة من القيادة الفعلية يجب أن تكملها قبل التصريح المتوسط، وكم منها في الليل؟","o":["25 ساعة، منها 5 في الليل","30 ساعة، منها 10 في الليل","40 ساعة، منها 15 في الليل","50 ساعة، منها 10 في الليل"],"h1":"ساعات الليل هي خُمس المجموع.","h2":"في Wyoming يجب أن تكمل 50 ساعة من القيادة الفعلية، منها 10 ساعات في الليل، قبل الحصول على التصريح المتوسط.","p":"صحيح. خمسون ساعة، منها عشر في الليل."},"ref":{"doc":"WY","page":14}},{"id":"wy-005","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, who must certify that a teen finished the practice driving hours?","o":["The teen alone","A parent or guardian","A police officer","A school teacher"],"h1":"It is the adult who is responsible for the teen.","h2":"In Wyoming, a parent or guardian must certify that the teen completed the practice driving hours.","p":"Right. A parent or guardian signs for the hours."},"es":{"q":"En Wyoming, ¿quién debe certificar que un adolescente terminó las horas de práctica?","o":["El adolescente solo","El padre, madre o tutor","Un policía","Un maestro de la escuela"],"h1":"Es el adulto responsable del adolescente.","h2":"En Wyoming, el padre, madre o tutor debe certificar que el adolescente completó las horas de práctica de manejo.","p":"Correcto. El padre, madre o tutor firma por las horas."},"zh":{"q":"在 Wyoming，谁必须证明青少年已经完成练习驾驶的小时数？","o":["只有青少年自己","父母或监护人","警察","学校老师"],"h1":"是对这个青少年负责的成年人。","h2":"在 Wyoming，必须由父母或监护人证明青少年已经完成练习驾驶的小时数。","p":"对。由父母或监护人为这些小时数签字。"},"vi":{"q":"Ở Wyoming, ai phải xác nhận rằng thiếu niên đã hoàn thành số giờ tập lái?","o":["Chỉ một mình thiếu niên","Cha mẹ hoặc người giám hộ","Một cảnh sát","Một giáo viên"],"h1":"Đó là người lớn chịu trách nhiệm về thiếu niên đó.","h2":"Ở Wyoming, cha mẹ hoặc người giám hộ phải xác nhận rằng thiếu niên đã hoàn thành số giờ tập lái.","p":"Đúng. Cha mẹ hoặc người giám hộ ký xác nhận số giờ."},"tl":{"q":"Sa Wyoming, sino ang dapat magpatunay na natapos ng kabataan ang mga oras ng pagsasanay sa pagmamaneho?","o":["Ang kabataan lang","Isang magulang o tagapag-alaga","Isang pulis","Isang guro sa paaralan"],"h1":"Ito ang adultong may pananagutan sa kabataan.","h2":"Sa Wyoming, isang magulang o tagapag-alaga ang dapat magpatunay na natapos ng kabataan ang mga oras ng pagsasanay sa pagmamaneho.","p":"Tama. Ang magulang o tagapag-alaga ang pumipirma para sa mga oras."},"ar":{"q":"في Wyoming، من يجب أن يشهد بأن المراهق أكمل ساعات التدريب على القيادة؟","o":["المراهق وحده","أحد الوالدين أو الوصي","شرطي","معلّم في المدرسة"],"h1":"هو الشخص البالغ المسؤول عن المراهق.","h2":"في Wyoming يجب أن يشهد أحد الوالدين أو الوصي بأن المراهق أكمل ساعات التدريب على القيادة.","p":"صحيح. أحد الوالدين أو الوصي يوقّع على الساعات."},"ref":{"doc":"WY","page":14}},{"id":"wy-006","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, during which hours may an intermediate permit holder drive?","o":["5 a.m. to 11 p.m.","6 a.m. to 9 p.m.","7 a.m. to 10 p.m.","Any time"],"h1":"The window ends late in the evening.","h2":"In Wyoming, an intermediate permit holder may drive only between 5 a.m. and 11 p.m., unless an exception applies.","p":"Right. Five in the morning to eleven at night."},"es":{"q":"En Wyoming, ¿en qué horario puede manejar quien tiene permiso intermedio?","o":["De 5 a.m. a 11 p.m.","De 6 a.m. a 9 p.m.","De 7 a.m. a 10 p.m.","A cualquier hora"],"h1":"El horario termina tarde en la noche.","h2":"En Wyoming, quien tiene permiso intermedio solo puede manejar entre las 5 a.m. y las 11 p.m., salvo que aplique una excepción.","p":"Correcto. De cinco de la mañana a once de la noche."},"zh":{"q":"在 Wyoming，持中级驾照的人可以在什么时间开车？","o":["早上 5 点到晚上 11 点","早上 6 点到晚上 9 点","早上 7 点到晚上 10 点","任何时间"],"h1":"这个时段在晚上很晚才结束。","h2":"在 Wyoming，持中级驾照的人只可以在早上 5 点到晚上 11 点之间开车，除非有例外情况。","p":"对。早上五点到晚上十一点。"},"vi":{"q":"Ở Wyoming, người có giấy phép trung cấp được lái xe trong những giờ nào?","o":["5 giờ sáng đến 11 giờ tối","6 giờ sáng đến 9 giờ tối","7 giờ sáng đến 10 giờ tối","Bất cứ lúc nào"],"h1":"Khoảng thời gian này kết thúc muộn vào buổi tối.","h2":"Ở Wyoming, người có giấy phép trung cấp chỉ được lái xe từ 5 giờ sáng đến 11 giờ tối, trừ khi có trường hợp ngoại lệ.","p":"Đúng. Từ năm giờ sáng đến mười một giờ tối."},"tl":{"q":"Sa Wyoming, sa anong mga oras puwedeng magmaneho ang may intermediate permit?","o":["5 a.m. hanggang 11 p.m.","6 a.m. hanggang 9 p.m.","7 a.m. hanggang 10 p.m.","Kahit anong oras"],"h1":"Natatapos ang oras na ito nang gabing-gabi na.","h2":"Sa Wyoming, puwedeng magmaneho ang may intermediate permit mula 5 a.m. hanggang 11 p.m. lang, maliban kung may exception.","p":"Tama. Mula alas-singko ng umaga hanggang alas-onse ng gabi."},"ar":{"q":"في Wyoming، في أي ساعات يُسمح لحامل التصريح المتوسط بالقيادة؟","o":["من 5 صباحًا إلى 11 مساءً","من 6 صباحًا إلى 9 مساءً","من 7 صباحًا إلى 10 مساءً","في أي وقت"],"h1":"هذه الفترة تنتهي في وقت متأخر من المساء.","h2":"في Wyoming يُسمح لحامل التصريح المتوسط بالقيادة فقط بين 5 صباحًا و11 مساءً، إلا إذا كان هناك استثناء.","p":"صحيح. من الخامسة صباحًا إلى الحادية عشرة ليلًا."},"ref":{"doc":"WY","page":14}},{"id":"wy-007","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, an intermediate permit holder drives at night for work. What is needed?","o":["Nothing at all","A note from a friend","A signed exception form","A police escort"],"h1":"Wyoming has a special paper for this.","h2":"In Wyoming, driving outside the allowed hours for work, school, sports or religious activities requires a signed exception form.","p":"Right. You need the signed exception form."},"es":{"q":"En Wyoming, quien tiene permiso intermedio maneja de noche por trabajo. ¿Qué necesita?","o":["Nada","Una nota de un amigo","Un formulario de excepción firmado","Una escolta de policía"],"h1":"Wyoming tiene un papel especial para esto.","h2":"En Wyoming, para manejar fuera del horario permitido por trabajo, escuela, deportes o actividades religiosas se necesita un formulario de excepción firmado.","p":"Correcto. Necesita el formulario de excepción firmado."},"zh":{"q":"在 Wyoming，持中级驾照的人因为工作要在夜间开车。需要什么？","o":["什么都不需要","朋友写的字条","签过字的例外表格","警察护送"],"h1":"Wyoming 有一张专门用于这种情况的文件。","h2":"在 Wyoming，因为工作、上学、体育或宗教活动要在允许时间以外开车，需要一张签过字的例外表格。","p":"对。你需要签过字的例外表格。"},"vi":{"q":"Ở Wyoming, người có giấy phép trung cấp lái xe ban đêm vì công việc. Cần gì?","o":["Không cần gì cả","Một tờ giấy của bạn bè","Một mẫu đơn ngoại lệ có chữ ký","Cảnh sát hộ tống"],"h1":"Wyoming có một loại giấy riêng cho việc này.","h2":"Ở Wyoming, lái xe ngoài giờ cho phép vì công việc, trường học, thể thao hoặc hoạt động tôn giáo cần có mẫu đơn ngoại lệ có chữ ký.","p":"Đúng. Bạn cần mẫu đơn ngoại lệ có chữ ký."},"tl":{"q":"Sa Wyoming, nagmamaneho sa gabi para sa trabaho ang may intermediate permit. Ano ang kailangan?","o":["Wala talaga","Sulat mula sa kaibigan","Isang pinirmahang exception form","Kasamang pulis"],"h1":"May espesyal na papel ang Wyoming para dito.","h2":"Sa Wyoming, kailangan ng pinirmahang exception form para magmaneho sa labas ng pinapayagang oras para sa trabaho, paaralan, sports o gawaing panrelihiyon.","p":"Tama. Kailangan mo ang pinirmahang exception form."},"ar":{"q":"في Wyoming، حامل التصريح المتوسط يقود في الليل من أجل العمل. ما المطلوب؟","o":["لا شيء أبدًا","ورقة من صديق","نموذج استثناء موقّع","مرافقة من الشرطة"],"h1":"لدى Wyoming ورقة خاصة لهذا.","h2":"في Wyoming، القيادة خارج الساعات المسموح بها من أجل العمل أو المدرسة أو الرياضة أو النشاطات الدينية تحتاج إلى نموذج استثناء موقّع.","p":"صحيح. تحتاج إلى نموذج الاستثناء الموقّع."},"ref":{"doc":"WY","page":14}},{"id":"wy-008","scope":"WY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wyoming, an intermediate permit holder drives to the hospital at night for a medical emergency. Is an exception form needed?","o":["Yes, always","Yes, signed by a doctor","Yes, signed by the police","No, a medical emergency does not need the form"],"h1":"In a real emergency, paperwork comes second.","h2":"In Wyoming, a trip to the hospital for a medical emergency does not require the exception form.","p":"Right. A medical emergency needs no form."},"es":{"q":"En Wyoming, quien tiene permiso intermedio maneja de noche al hospital por una emergencia médica. ¿Necesita el formulario de excepción?","o":["Sí, siempre","Sí, firmado por un médico","Sí, firmado por la policía","No, una emergencia médica no necesita el formulario"],"h1":"En una emergencia real, los papeles van después.","h2":"En Wyoming, un viaje al hospital por una emergencia médica no requiere el formulario de excepción.","p":"Correcto. Una emergencia médica no necesita formulario."},"zh":{"q":"在 Wyoming，持中级驾照的人因为医疗紧急情况在夜间开车去医院。需要例外表格吗？","o":["需要，每次都需要","需要，由医生签字","需要，由警察签字","不需要，医疗紧急情况不需要这张表格"],"h1":"在真正的紧急情况下，文件是次要的。","h2":"在 Wyoming，因为医疗紧急情况开车去医院，不需要例外表格。","p":"对。医疗紧急情况不需要表格。"},"vi":{"q":"Ở Wyoming, người có giấy phép trung cấp lái xe đến bệnh viện vào ban đêm vì cấp cứu y tế. Có cần mẫu đơn ngoại lệ không?","o":["Có, luôn luôn cần","Có, do bác sĩ ký","Có, do cảnh sát ký","Không, cấp cứu y tế không cần mẫu đơn"],"h1":"Khi thật sự khẩn cấp, giấy tờ là chuyện sau.","h2":"Ở Wyoming, lái xe đến bệnh viện vì cấp cứu y tế không cần mẫu đơn ngoại lệ.","p":"Đúng. Cấp cứu y tế không cần mẫu đơn."},"tl":{"q":"Sa Wyoming, nagmamaneho sa gabi papunta sa ospital ang may intermediate permit dahil sa medical emergency. Kailangan ba ang exception form?","o":["Oo, palagi","Oo, pirmado ng doktor","Oo, pirmado ng pulis","Hindi, hindi kailangan ng form sa medical emergency"],"h1":"Sa tunay na emergency, pangalawa lang ang papeles.","h2":"Sa Wyoming, hindi kailangan ng exception form sa pagpunta sa ospital dahil sa medical emergency.","p":"Tama. Walang form na kailangan sa medical emergency."},"ar":{"q":"في Wyoming، حامل التصريح المتوسط يقود إلى المستشفى في الليل بسبب حالة طبية طارئة. هل يحتاج إلى نموذج استثناء؟","o":["نعم، دائمًا","نعم، موقّع من طبيب","نعم، موقّع من الشرطة","لا، الحالة الطبية الطارئة لا تحتاج إلى النموذج"],"h1":"في الطوارئ الحقيقية، الأوراق تأتي في المرتبة الثانية.","h2":"في Wyoming، الذهاب إلى المستشفى بسبب حالة طبية طارئة لا يحتاج إلى نموذج الاستثناء.","p":"صحيح. الحالة الطبية الطارئة لا تحتاج إلى نموذج."},"ref":{"doc":"WY","page":null}},{"id":"wy-009","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, how many passengers under 18 who are not immediate family may an intermediate permit holder carry?","o":["None","One","Two","Three"],"h1":"It is the smallest number that is more than zero.","h2":"In Wyoming, an intermediate permit holder may carry no more than one passenger under 18 who is not an immediate family member.","p":"Right. Only one non-family passenger under 18."},"es":{"q":"En Wyoming, ¿cuántos pasajeros menores de 18 años que no son familia directa puede llevar quien tiene permiso intermedio?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Es el número más pequeño mayor que cero.","h2":"En Wyoming, quien tiene permiso intermedio puede llevar como máximo un pasajero menor de 18 años que no sea familiar directo.","p":"Correcto. Solo un pasajero menor de 18 que no sea familia."},"zh":{"q":"在 Wyoming，持中级驾照的人可以载几名不是直系亲属、未满 18 岁的乘客？","o":["一名也不可以","一名","两名","三名"],"h1":"它是比零大的最小数字。","h2":"在 Wyoming，持中级驾照的人最多只可以载一名不是直系亲属、未满 18 岁的乘客。","p":"对。只可以载一名不是家人、未满 18 岁的乘客。"},"vi":{"q":"Ở Wyoming, người có giấy phép trung cấp được chở bao nhiêu hành khách dưới 18 tuổi không phải là người thân trong gia đình?","o":["Không ai","Một","Hai","Ba"],"h1":"Đó là số nhỏ nhất lớn hơn không.","h2":"Ở Wyoming, người có giấy phép trung cấp được chở không quá một hành khách dưới 18 tuổi không phải là người thân trong gia đình.","p":"Đúng. Chỉ một hành khách dưới 18 tuổi không phải người nhà."},"tl":{"q":"Sa Wyoming, ilang pasaherong wala pang 18 at hindi malapit na kapamilya ang puwedeng isakay ng may intermediate permit?","o":["Wala","Isa","Dalawa","Tatlo"],"h1":"Ito ang pinakamaliit na bilang na higit sa zero.","h2":"Sa Wyoming, hindi hihigit sa isang pasaherong wala pang 18 at hindi malapit na kapamilya ang puwedeng isakay ng may intermediate permit.","p":"Tama. Isa lang na pasaherong wala pang 18 na hindi kapamilya."},"ar":{"q":"في Wyoming، كم راكبًا عمره أقل من 18 سنة وليس من العائلة المباشرة يمكن أن يحمل حامل التصريح المتوسط؟","o":["لا أحد","واحد","اثنان","ثلاثة"],"h1":"هو أصغر عدد أكبر من الصفر.","h2":"في Wyoming لا يمكن لحامل التصريح المتوسط أن يحمل أكثر من راكب واحد عمره أقل من 18 سنة وليس من العائلة المباشرة.","p":"صحيح. راكب واحد فقط عمره أقل من 18 سنة وليس من العائلة."},"ref":{"doc":"WY","page":14}},{"id":"wy-010","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, when does the passenger limit for an intermediate permit holder not apply?","o":["When a licensed adult age 18 or older sits in the front seat","On weekends","On rural roads","When the radio is off"],"h1":"An experienced adult beside you changes the rule.","h2":"In Wyoming, the passenger limit does not apply when a licensed adult who is at least 18 rides in the front seat.","p":"Right. A licensed adult in the front seat lifts the limit."},"es":{"q":"En Wyoming, ¿cuándo no aplica el límite de pasajeros para quien tiene permiso intermedio?","o":["Cuando un adulto con licencia de 18 años o más va en el asiento delantero","Los fines de semana","En caminos rurales","Cuando el radio está apagado"],"h1":"Un adulto con experiencia a su lado cambia la regla.","h2":"En Wyoming, el límite de pasajeros no aplica cuando un adulto con licencia de por lo menos 18 años va en el asiento delantero.","p":"Correcto. Un adulto con licencia adelante quita el límite."},"zh":{"q":"在 Wyoming，持中级驾照的人的乘客限制在什么情况下不适用？","o":["当一名 18 岁或以上、有驾照的成年人坐在前座时","在周末","在乡村道路上","当收音机关掉时"],"h1":"身边有一位有经验的成年人，规则就会改变。","h2":"在 Wyoming，当一名至少 18 岁、有驾照的成年人坐在前座时，乘客限制不适用。","p":"对。前座有一名有驾照的成年人，就没有这个限制。"},"vi":{"q":"Ở Wyoming, khi nào giới hạn hành khách của người có giấy phép trung cấp không áp dụng?","o":["Khi một người lớn có bằng lái, từ 18 tuổi trở lên, ngồi ở ghế trước","Vào cuối tuần","Trên đường nông thôn","Khi tắt radio"],"h1":"Có một người lớn có kinh nghiệm bên cạnh thì quy định thay đổi.","h2":"Ở Wyoming, giới hạn hành khách không áp dụng khi một người lớn có bằng lái, ít nhất 18 tuổi, ngồi ở ghế trước.","p":"Đúng. Một người lớn có bằng lái ở ghế trước thì không còn giới hạn."},"tl":{"q":"Sa Wyoming, kailan hindi umiiral ang limitasyon sa pasahero para sa may intermediate permit?","o":["Kapag may lisensiyadong adulto na 18 taong gulang pataas sa upuan sa harap","Tuwing weekend","Sa mga daan sa probinsiya","Kapag nakapatay ang radyo"],"h1":"Nagbabago ang patakaran kapag may karanasang adulto sa tabi mo.","h2":"Sa Wyoming, hindi umiiral ang limitasyon sa pasahero kapag may lisensiyadong adulto na hindi bababa sa 18 taong gulang sa upuan sa harap.","p":"Tama. Kapag may lisensiyadong adulto sa harap, wala na ang limitasyon."},"ar":{"q":"في Wyoming، متى لا ينطبق حد الركاب على حامل التصريح المتوسط؟","o":["عندما يجلس في المقعد الأمامي شخص بالغ عمره 18 سنة أو أكثر ومعه رخصة قيادة","في عطلة نهاية الأسبوع","على الطرق الريفية","عندما يكون الراديو مطفأً"],"h1":"وجود شخص بالغ له خبرة بجانبك يغيّر القاعدة.","h2":"في Wyoming لا ينطبق حد الركاب عندما يجلس في المقعد الأمامي شخص بالغ معه رخصة قيادة وعمره 18 سنة على الأقل.","p":"صحيح. شخص بالغ معه رخصة في المقعد الأمامي يرفع الحد."},"ref":{"doc":"WY","page":14}},{"id":"wy-011","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, how long must you hold an intermediate permit?","o":["30 days","3 months","Six months or until age 17","Until age 18"],"h1":"It is half a year, unless a birthday comes first.","h2":"In Wyoming you must hold the intermediate permit for at least six months or until you turn 17.","p":"Right. Six months or until 17."},"es":{"q":"En Wyoming, ¿cuánto tiempo debe tener el permiso intermedio?","o":["30 días","3 meses","Seis meses o hasta los 17 años","Hasta los 18 años"],"h1":"Es medio año, a menos que llegue antes un cumpleaños.","h2":"En Wyoming usted debe tener el permiso intermedio por lo menos seis meses o hasta cumplir 17 años.","p":"Correcto. Seis meses o hasta los 17."},"zh":{"q":"在 Wyoming，必须持有中级驾照多久？","o":["30 天","3 个月","六个月或到 17 岁","到 18 岁"],"h1":"它是半年，除非生日先到。","h2":"在 Wyoming，你必须持有中级驾照至少六个月，或者持有到你满 17 岁。","p":"对。六个月或到 17 岁。"},"vi":{"q":"Ở Wyoming, bạn phải giữ giấy phép trung cấp bao lâu?","o":["30 ngày","3 tháng","Sáu tháng hoặc đến 17 tuổi","Đến 18 tuổi"],"h1":"Đó là nửa năm, trừ khi sinh nhật đến trước.","h2":"Ở Wyoming, bạn phải giữ giấy phép trung cấp ít nhất sáu tháng hoặc cho đến khi bạn 17 tuổi.","p":"Đúng. Sáu tháng hoặc đến 17 tuổi."},"tl":{"q":"Sa Wyoming, gaano katagal mo dapat hawak ang intermediate permit?","o":["30 araw","3 buwan","Anim na buwan o hanggang 17 taong gulang","Hanggang 18 taong gulang"],"h1":"Kalahating taon ito, maliban kung mauna ang kaarawan.","h2":"Sa Wyoming, dapat mong hawak ang intermediate permit nang hindi bababa sa anim na buwan o hanggang mag-17 ka.","p":"Tama. Anim na buwan o hanggang 17."},"ar":{"q":"في Wyoming، كم مدة يجب أن تحمل التصريح المتوسط؟","o":["30 يومًا","3 أشهر","ستة أشهر أو حتى عمر 17 سنة","حتى عمر 18 سنة"],"h1":"هي نصف سنة، إلا إذا جاء عيد الميلاد أولًا.","h2":"في Wyoming يجب أن تحمل التصريح المتوسط ستة أشهر على الأقل أو حتى تبلغ 17 سنة.","p":"صحيح. ستة أشهر أو حتى 17 سنة."},"ref":{"doc":"WY","page":7}},{"id":"wy-012","scope":"WY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Wyoming, what is the highest speed limit on interstate highways?","o":["65 mph","70 mph","80 mph","90 mph"],"h1":"Some interstate parts are 75 mph. The top limit is a little higher.","h2":"In Wyoming the highest interstate speed limit is 80 mph, and some interstate sections are 75 mph, so always obey the posted sign.","p":"Right. The top limit on Wyoming interstates is 80 mph."},"es":{"q":"En Wyoming, ¿cuál es el límite de velocidad más alto en las autopistas interestatales?","o":["65 mph","70 mph","80 mph","90 mph"],"h1":"Algunas partes de la interestatal son de 75 mph. El límite más alto es un poco mayor.","h2":"En Wyoming el límite más alto en las interestatales es de 80 mph, y algunas partes son de 75 mph, así que siempre obedezca el letrero.","p":"Correcto. El límite más alto en las interestatales de Wyoming es de 80 mph."},"zh":{"q":"在 Wyoming，州际公路（interstate）上最高的限速是多少？","o":["65 mph","70 mph","80 mph","90 mph"],"h1":"有些州际公路路段是 75 mph。最高限速再高一点。","h2":"在 Wyoming，州际公路的最高限速是 80 mph，有些州际公路路段是 75 mph，所以一定要遵守路边标志上的限速。","p":"对。Wyoming 州际公路的最高限速是 80 mph。"},"vi":{"q":"Ở Wyoming, giới hạn tốc độ cao nhất trên xa lộ liên bang (interstate) là bao nhiêu?","o":["65 mph","70 mph","80 mph","90 mph"],"h1":"Một số đoạn xa lộ liên bang là 75 mph. Giới hạn cao nhất cao hơn một chút.","h2":"Ở Wyoming, giới hạn tốc độ cao nhất trên xa lộ liên bang là 80 mph, và một số đoạn là 75 mph, vì vậy luôn tuân theo biển báo.","p":"Đúng. Giới hạn cao nhất trên xa lộ liên bang ở Wyoming là 80 mph."},"tl":{"q":"Sa Wyoming, ano ang pinakamataas na speed limit sa mga interstate highway?","o":["65 mph","70 mph","80 mph","90 mph"],"h1":"May mga bahagi ng interstate na 75 mph. Medyo mas mataas ang pinakamataas na limit.","h2":"Sa Wyoming, 80 mph ang pinakamataas na speed limit sa interstate, at 75 mph ang ilang bahagi nito, kaya laging sundin ang nakapaskil na karatula.","p":"Tama. 80 mph ang pinakamataas na limit sa mga interstate sa Wyoming."},"ar":{"q":"في Wyoming، ما أعلى حد للسرعة على الطرق السريعة بين الولايات (interstate)؟","o":["65 mph","70 mph","80 mph","90 mph"],"h1":"بعض أجزاء الطرق السريعة بين الولايات حدها 75 mph. والحد الأعلى أكبر قليلًا.","h2":"في Wyoming أعلى حد للسرعة على الطرق السريعة بين الولايات هو 80 mph، وبعض الأجزاء حدها 75 mph، لذلك اتبع دائمًا اللافتة الموجودة.","p":"صحيح. أعلى حد على الطرق السريعة بين الولايات في Wyoming هو 80 mph."},"ref":{"doc":"WY","page":41}},{"id":"wy-013","scope":"WY","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Wyoming, what is the speed limit on a state highway that is not an interstate, when no other limit is posted?","o":["55 mph","70 mph","75 mph","80 mph"],"h1":"It is ten less than the interstate limit.","h2":"In Wyoming the speed limit on a state highway that is not an interstate is 70 mph unless another limit is posted.","p":"Right. State highways that are not interstates are 70 mph."},"es":{"q":"En Wyoming, ¿cuál es el límite de velocidad en una carretera estatal que no es interestatal, cuando no hay otro límite indicado?","o":["55 mph","70 mph","75 mph","80 mph"],"h1":"Es diez menos que el límite de la interestatal.","h2":"En Wyoming el límite de velocidad en una carretera estatal que no es interestatal es de 70 mph, a menos que haya otro límite indicado.","p":"Correcto. Las carreteras estatales que no son interestatales son de 70 mph."},"zh":{"q":"在 Wyoming，没有标出其他限速时，不是州际公路的州公路（state highway）限速是多少？","o":["55 mph","70 mph","75 mph","80 mph"],"h1":"它比州际公路的限速少十。","h2":"在 Wyoming，不是州际公路的州公路限速是 70 mph，除非标出其他限速。","p":"对。不是州际公路的州公路限速是 70 mph。"},"vi":{"q":"Ở Wyoming, giới hạn tốc độ trên quốc lộ tiểu bang (state highway) không phải xa lộ liên bang là bao nhiêu, khi không có biển báo giới hạn khác?","o":["55 mph","70 mph","75 mph","80 mph"],"h1":"Nó ít hơn giới hạn trên xa lộ liên bang mười.","h2":"Ở Wyoming, giới hạn tốc độ trên quốc lộ tiểu bang không phải xa lộ liên bang là 70 mph, trừ khi có biển báo giới hạn khác.","p":"Đúng. Quốc lộ tiểu bang không phải xa lộ liên bang là 70 mph."},"tl":{"q":"Sa Wyoming, ano ang speed limit sa state highway na hindi interstate, kapag walang ibang nakapaskil na limit?","o":["55 mph","70 mph","75 mph","80 mph"],"h1":"Sampu itong mas mababa kaysa sa limit sa interstate.","h2":"Sa Wyoming, 70 mph ang speed limit sa state highway na hindi interstate, maliban kung may ibang nakapaskil na limit.","p":"Tama. 70 mph ang mga state highway na hindi interstate."},"ar":{"q":"في Wyoming، ما حد السرعة على طريق الولاية السريع (state highway) الذي ليس طريقًا بين الولايات، عندما لا توجد لافتة بحد آخر؟","o":["55 mph","70 mph","75 mph","80 mph"],"h1":"هو أقل بعشرة من حد الطرق السريعة بين الولايات.","h2":"في Wyoming حد السرعة على طريق الولاية السريع الذي ليس طريقًا بين الولايات هو 70 mph، إلا إذا كانت هناك لافتة بحد آخر.","p":"صحيح. طرق الولاية السريعة التي ليست بين الولايات حدها 70 mph."},"ref":{"doc":"WY","page":41}},{"id":"wy-014","scope":"WY","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Wyoming, what is the speed limit on an unpaved road when no other limit is posted?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"It is fifteen less than on a paved road.","h2":"In Wyoming the speed limit on an unpaved road is 55 mph unless another limit is posted.","p":"Right. Unpaved roads are 55 mph."},"es":{"q":"En Wyoming, ¿cuál es el límite de velocidad en un camino sin pavimentar cuando no hay otro límite indicado?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Es quince menos que en un camino pavimentado.","h2":"En Wyoming el límite de velocidad en un camino sin pavimentar es de 55 mph, a menos que haya otro límite indicado.","p":"Correcto. Los caminos sin pavimentar son de 55 mph."},"zh":{"q":"在 Wyoming，没有标出其他限速时，没有铺路面的道路限速是多少？","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"它比有铺路面的道路少十五。","h2":"在 Wyoming，没有铺路面的道路限速是 55 mph，除非标出其他限速。","p":"对。没有铺路面的道路限速是 55 mph。"},"vi":{"q":"Ở Wyoming, giới hạn tốc độ trên đường không trải nhựa là bao nhiêu, khi không có biển báo giới hạn khác?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Nó ít hơn đường trải nhựa mười lăm.","h2":"Ở Wyoming, giới hạn tốc độ trên đường không trải nhựa là 55 mph, trừ khi có biển báo giới hạn khác.","p":"Đúng. Đường không trải nhựa là 55 mph."},"tl":{"q":"Sa Wyoming, ano ang speed limit sa daang hindi sementado, kapag walang ibang nakapaskil na limit?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Labinlima itong mas mababa kaysa sa sementadong daan.","h2":"Sa Wyoming, 55 mph ang speed limit sa daang hindi sementado, maliban kung may ibang nakapaskil na limit.","p":"Tama. 55 mph ang mga daang hindi sementado."},"ar":{"q":"في Wyoming، ما حد السرعة على طريق غير معبّد، عندما لا توجد لافتة بحد آخر؟","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"هو أقل بخمسة عشر من الطريق المعبّد.","h2":"في Wyoming حد السرعة على الطريق غير المعبّد هو 55 mph، إلا إذا كانت هناك لافتة بحد آخر.","p":"صحيح. الطرق غير المعبّدة حدها 55 mph."},"ref":{"doc":"WY","page":null}},{"id":"wy-015","scope":"WY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Wyoming, what is the speed limit in an urban area when no other limit is posted?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"It is ten more than a school zone.","h2":"In Wyoming the speed limit in urban areas is 30 mph unless another limit is posted.","p":"Right. Urban areas are 30 mph."},"es":{"q":"En Wyoming, ¿cuál es el límite de velocidad en una zona urbana cuando no hay otro límite indicado?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Es diez más que en una zona escolar.","h2":"En Wyoming el límite de velocidad en zonas urbanas es de 30 mph, a menos que haya otro límite indicado.","p":"Correcto. Las zonas urbanas son de 30 mph."},"zh":{"q":"在 Wyoming，没有标出其他限速时，城市地区的限速是多少？","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"它比学校区多十。","h2":"在 Wyoming，城市地区的限速是 30 mph，除非标出其他限速。","p":"对。城市地区限速是 30 mph。"},"vi":{"q":"Ở Wyoming, giới hạn tốc độ trong khu đô thị là bao nhiêu, khi không có biển báo giới hạn khác?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Nó nhiều hơn khu vực trường học mười.","h2":"Ở Wyoming, giới hạn tốc độ trong khu đô thị là 30 mph, trừ khi có biển báo giới hạn khác.","p":"Đúng. Khu đô thị là 30 mph."},"tl":{"q":"Sa Wyoming, ano ang speed limit sa lungsod (urban area), kapag walang ibang nakapaskil na limit?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Sampu itong mas mataas kaysa sa school zone.","h2":"Sa Wyoming, 30 mph ang speed limit sa lungsod, maliban kung may ibang nakapaskil na limit.","p":"Tama. 30 mph sa lungsod."},"ar":{"q":"في Wyoming، ما حد السرعة في المناطق الحضرية، عندما لا توجد لافتة بحد آخر؟","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"هو أكثر بعشرة من منطقة المدرسة.","h2":"في Wyoming حد السرعة في المناطق الحضرية هو 30 mph، إلا إذا كانت هناك لافتة بحد آخر.","p":"صحيح. المناطق الحضرية حدها 30 mph."},"ref":{"doc":"WY","page":41}},{"id":"wy-016","scope":"WY","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Wyoming, what is the speed limit in a signed school zone with a reduced limit?","o":["20 mph","15 mph","25 mph","30 mph"],"h1":"It is ten less than the urban limit.","h2":"In Wyoming the speed limit in a school zone with signs showing the reduced limit is 20 mph.","p":"Right. School zones are 20 mph."},"es":{"q":"En Wyoming, ¿cuál es el límite de velocidad en una zona escolar señalizada con límite reducido?","o":["20 mph","15 mph","25 mph","30 mph"],"h1":"Es diez menos que el límite urbano.","h2":"En Wyoming el límite de velocidad en una zona escolar con letreros de límite reducido es de 20 mph.","p":"Correcto. Las zonas escolares son de 20 mph."},"zh":{"q":"在 Wyoming，有标志标出降低限速的学校区（school zone），限速是多少？","o":["20 mph","15 mph","25 mph","30 mph"],"h1":"它比城市地区的限速少十。","h2":"在 Wyoming，有标志标出降低限速的学校区，限速是 20 mph。","p":"对。学校区限速是 20 mph。"},"vi":{"q":"Ở Wyoming, giới hạn tốc độ trong khu vực trường học (school zone) có biển báo giảm tốc độ là bao nhiêu?","o":["20 mph","15 mph","25 mph","30 mph"],"h1":"Nó ít hơn giới hạn trong khu đô thị mười.","h2":"Ở Wyoming, giới hạn tốc độ trong khu vực trường học có biển báo giảm tốc độ là 20 mph.","p":"Đúng. Khu vực trường học là 20 mph."},"tl":{"q":"Sa Wyoming, ano ang speed limit sa school zone na may karatula ng mas mababang limit?","o":["20 mph","15 mph","25 mph","30 mph"],"h1":"Sampu itong mas mababa kaysa sa limit sa lungsod.","h2":"Sa Wyoming, 20 mph ang speed limit sa school zone na may karatulang nagpapakita ng mas mababang limit.","p":"Tama. 20 mph sa mga school zone."},"ar":{"q":"في Wyoming، ما حد السرعة في منطقة المدرسة (school zone) التي فيها لافتات بحد مخفّض؟","o":["20 mph","15 mph","25 mph","30 mph"],"h1":"هو أقل بعشرة من حد المناطق الحضرية.","h2":"في Wyoming حد السرعة في منطقة المدرسة التي فيها لافتات تبيّن الحد المخفّض هو 20 mph.","p":"صحيح. مناطق المدارس حدها 20 mph."},"ref":{"doc":"WY","page":41}},{"id":"wy-017","scope":"WY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wyoming, a driver under 21 may not drive with a blood alcohol level of what amount or more?","o":[".05 percent",".02 percent",".08 percent",".10 percent"],"h1":"It is a tiny fraction of the adult limit.","h2":"In Wyoming a driver under 21 may not drive with a blood alcohol level of .02 percent or more.","p":"Right. Under 21, the limit is .02."},"es":{"q":"En Wyoming, ¿a partir de qué nivel de alcohol en la sangre no puede manejar un conductor menor de 21 años?","o":[".05 por ciento",".02 por ciento",".08 por ciento",".10 por ciento"],"h1":"Es una fracción muy pequeña del límite para adultos.","h2":"En Wyoming un conductor menor de 21 años no puede manejar con un nivel de alcohol en la sangre de .02 por ciento o más.","p":"Correcto. Para menores de 21, el límite es .02."},"zh":{"q":"在 Wyoming，未满 21 岁的司机血液酒精浓度达到多少或以上就不可以开车？","o":["0.05%","0.02%","0.08%","0.10%"],"h1":"它是成年人限制的很小一部分。","h2":"在 Wyoming，未满 21 岁的司机血液酒精浓度达到 0.02% 或以上就不可以开车。","p":"对。未满 21 岁，限制是 0.02%。"},"vi":{"q":"Ở Wyoming, tài xế dưới 21 tuổi không được lái xe khi nồng độ cồn trong máu từ mức nào trở lên?","o":[".05 phần trăm",".02 phần trăm",".08 phần trăm",".10 phần trăm"],"h1":"Đó là một phần rất nhỏ của giới hạn cho người lớn.","h2":"Ở Wyoming, tài xế dưới 21 tuổi không được lái xe khi nồng độ cồn trong máu từ .02 phần trăm trở lên.","p":"Đúng. Dưới 21 tuổi, giới hạn là .02."},"tl":{"q":"Sa Wyoming, hindi puwedeng magmaneho ang driver na wala pang 21 kapag ang alak sa dugo niya ay umabot sa anong antas o higit pa?","o":[".05 porsiyento",".02 porsiyento",".08 porsiyento",".10 porsiyento"],"h1":"Napakaliit na bahagi ito ng limit para sa adulto.","h2":"Sa Wyoming, hindi puwedeng magmaneho ang driver na wala pang 21 kapag .02 porsiyento o higit pa ang alak sa dugo niya.","p":"Tama. Kapag wala pang 21, .02 ang limit."},"ar":{"q":"في Wyoming، لا يجوز للسائق الذي عمره أقل من 21 سنة أن يقود إذا كانت نسبة الكحول في دمه تبلغ أي مقدار أو أكثر؟","o":[".05 بالمئة",".02 بالمئة",".08 بالمئة",".10 بالمئة"],"h1":"هي جزء صغير جدًا من حد البالغين.","h2":"في Wyoming لا يجوز للسائق الذي عمره أقل من 21 سنة أن يقود إذا كانت نسبة الكحول في دمه .02 بالمئة أو أكثر.","p":"صحيح. لمن عمره أقل من 21 سنة، الحد هو .02."},"ref":{"doc":"WY","page":22}},{"id":"wy-018","scope":"WY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wyoming, how long is the license suspension when a driver under 21 is found driving at .02 or more?","o":["7 days","30 days","One year","90 days"],"h1":"It is about three months.","h2":"In Wyoming, a driver under 21 caught driving at .02 or more has the license suspended for 90 days.","p":"Right. The suspension is 90 days."},"es":{"q":"En Wyoming, ¿cuánto dura la suspensión de la licencia cuando un conductor menor de 21 años maneja con .02 o más?","o":["7 días","30 días","Un año","90 días"],"h1":"Son unos tres meses.","h2":"En Wyoming, a un conductor menor de 21 años que maneja con .02 o más se le suspende la licencia por 90 días.","p":"Correcto. La suspensión es de 90 días."},"zh":{"q":"在 Wyoming，未满 21 岁的司机被发现血液酒精浓度在 0.02% 或以上开车，驾照会被吊销多久？","o":["7 天","30 天","一年","90 天"],"h1":"大约三个月。","h2":"在 Wyoming，未满 21 岁的司机被发现血液酒精浓度在 0.02% 或以上开车，驾照会被吊销 90 天。","p":"对。吊销 90 天。"},"vi":{"q":"Ở Wyoming, bằng lái bị đình chỉ bao lâu khi tài xế dưới 21 tuổi bị phát hiện lái xe với nồng độ cồn từ .02 trở lên?","o":["7 ngày","30 ngày","Một năm","90 ngày"],"h1":"Khoảng ba tháng.","h2":"Ở Wyoming, tài xế dưới 21 tuổi bị bắt khi lái xe với nồng độ cồn từ .02 trở lên sẽ bị đình chỉ bằng lái 90 ngày.","p":"Đúng. Bị đình chỉ 90 ngày."},"tl":{"q":"Sa Wyoming, gaano katagal ang suspensiyon ng lisensiya kapag nahuling nagmamaneho ang driver na wala pang 21 na may .02 o higit pa?","o":["7 araw","30 araw","Isang taon","90 araw"],"h1":"Mga tatlong buwan ito.","h2":"Sa Wyoming, sinususpinde nang 90 araw ang lisensiya ng driver na wala pang 21 na nahuling nagmamaneho na may .02 o higit pa.","p":"Tama. 90 araw ang suspensiyon."},"ar":{"q":"في Wyoming، كم مدة إيقاف الرخصة عندما يُضبط سائق عمره أقل من 21 سنة يقود ونسبة الكحول .02 أو أكثر؟","o":["7 أيام","30 يومًا","سنة واحدة","90 يومًا"],"h1":"هي حوالي ثلاثة أشهر.","h2":"في Wyoming، السائق الذي عمره أقل من 21 سنة ويُضبط يقود ونسبة الكحول .02 أو أكثر تُوقف رخصته 90 يومًا.","p":"صحيح. الإيقاف 90 يومًا."},"ref":{"doc":"WY","page":22}},{"id":"wy-019","scope":"WY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Wyoming, which speeding tickets always go on your driving record?","o":["Only tickets on interstates","Only tickets at night","Speeding in a school zone or construction zone","None of them"],"h1":"Think of places where children or workers may be near the road.","h2":"In Wyoming, a speeding violation in a school zone or a construction zone always goes on your driving record.","p":"Right. School and construction zones go on the record."},"es":{"q":"En Wyoming, ¿qué multas por exceso de velocidad siempre quedan en su historial de manejo?","o":["Solo las de autopistas interestatales","Solo las de noche","Las de exceso de velocidad en zona escolar o zona de obras","Ninguna"],"h1":"Piense en lugares donde puede haber niños o trabajadores cerca de la vía.","h2":"En Wyoming, una infracción por exceso de velocidad en una zona escolar o zona de obras siempre queda en su historial de manejo.","p":"Correcto. Las zonas escolares y de obras quedan en el historial."},"zh":{"q":"在 Wyoming，哪些超速罚单一定会记录在你的驾驶记录上？","o":["只有州际公路上的罚单","只有夜间的罚单","在学校区或施工区超速","都不会"],"h1":"想一想孩子或工人可能在路边的地方。","h2":"在 Wyoming，在学校区或施工区超速，一定会记录在你的驾驶记录上。","p":"对。学校区和施工区的超速会记录在驾驶记录上。"},"vi":{"q":"Ở Wyoming, loại vé phạt chạy quá tốc độ nào luôn được ghi vào hồ sơ lái xe của bạn?","o":["Chỉ vé phạt trên xa lộ liên bang","Chỉ vé phạt vào ban đêm","Chạy quá tốc độ trong khu vực trường học hoặc khu vực thi công","Không loại nào"],"h1":"Hãy nghĩ đến những nơi trẻ em hoặc công nhân có thể ở gần đường.","h2":"Ở Wyoming, vi phạm tốc độ trong khu vực trường học hoặc khu vực thi công luôn được ghi vào hồ sơ lái xe của bạn.","p":"Đúng. Khu vực trường học và khu vực thi công được ghi vào hồ sơ."},"tl":{"q":"Sa Wyoming, aling mga tiket sa sobrang bilis ang laging napupunta sa driving record mo?","o":["Mga tiket sa interstate lang","Mga tiket sa gabi lang","Sobrang bilis sa school zone o construction zone","Wala sa kanila"],"h1":"Isipin ang mga lugar kung saan maaaring malapit sa daan ang mga bata o manggagawa.","h2":"Sa Wyoming, laging napupunta sa driving record mo ang paglabag sa bilis sa school zone o construction zone.","p":"Tama. Napupunta sa record ang mga school zone at construction zone."},"ar":{"q":"في Wyoming، أي مخالفات السرعة تُسجّل دائمًا في سجل القيادة الخاص بك؟","o":["المخالفات على الطرق السريعة بين الولايات فقط","المخالفات في الليل فقط","السرعة الزائدة في منطقة مدرسة أو منطقة أعمال إنشاء","لا شيء منها"],"h1":"فكّر في الأماكن التي قد يكون فيها أطفال أو عمّال قرب الطريق.","h2":"في Wyoming، مخالفة السرعة في منطقة مدرسة أو منطقة أعمال إنشاء تُسجّل دائمًا في سجل القيادة الخاص بك.","p":"صحيح. مناطق المدارس ومناطق الإنشاء تُسجّل في السجل."},"ref":{"doc":"WY","page":null}},{"id":"wy-020","scope":"WY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wyoming, is texting while driving allowed?","o":["Yes, on rural roads","No, texting while driving is banned","Yes, if you are over 21","Only at speeds under 30 mph"],"h1":"Reading or sending a message takes your eyes off the road.","h2":"Wyoming bans texting while driving, so you may not write, send or read a text message while driving on a public road.","p":"Right. Texting while driving is banned."},"es":{"q":"En Wyoming, ¿se permite enviar mensajes de texto mientras maneja?","o":["Sí, en caminos rurales","No, está prohibido enviar mensajes mientras maneja","Sí, si es mayor de 21 años","Solo a menos de 30 mph"],"h1":"Leer o enviar un mensaje le quita la vista de la vía.","h2":"Wyoming prohíbe enviar mensajes de texto mientras maneja, así que usted no puede escribir, enviar ni leer un mensaje mientras maneja en una vía pública.","p":"Correcto. Está prohibido enviar mensajes mientras maneja."},"zh":{"q":"在 Wyoming，开车时可以发短信吗？","o":["可以，在乡村道路上","不可以，开车时发短信是被禁止的","可以，如果你超过 21 岁","只有车速低于 30 mph 时可以"],"h1":"看或发信息会让你的眼睛离开道路。","h2":"Wyoming 禁止开车时发短信，所以在公共道路上开车时，你不可以写、发送或阅读短信。","p":"对。开车时发短信是被禁止的。"},"vi":{"q":"Ở Wyoming, có được nhắn tin khi đang lái xe không?","o":["Có, trên đường nông thôn","Không, nhắn tin khi lái xe bị cấm","Có, nếu bạn trên 21 tuổi","Chỉ khi chạy dưới 30 mph"],"h1":"Đọc hoặc gửi tin nhắn làm mắt bạn rời khỏi đường.","h2":"Wyoming cấm nhắn tin khi lái xe, vì vậy bạn không được viết, gửi hoặc đọc tin nhắn khi lái xe trên đường công cộng.","p":"Đúng. Nhắn tin khi lái xe bị cấm."},"tl":{"q":"Sa Wyoming, pinapayagan ba ang pag-text habang nagmamaneho?","o":["Oo, sa mga daan sa probinsiya","Hindi, bawal ang pag-text habang nagmamaneho","Oo, kung lampas 21 ka na","Kapag mas mababa lang sa 30 mph ang bilis"],"h1":"Inaalis ng pagbasa o pagpapadala ng mensahe ang mata mo sa daan.","h2":"Bawal sa Wyoming ang pag-text habang nagmamaneho, kaya hindi ka puwedeng sumulat, magpadala o magbasa ng text habang nagmamaneho sa pampublikong daan.","p":"Tama. Bawal ang pag-text habang nagmamaneho."},"ar":{"q":"في Wyoming، هل يُسمح بكتابة الرسائل النصية أثناء القيادة؟","o":["نعم، على الطرق الريفية","لا، كتابة الرسائل أثناء القيادة ممنوعة","نعم، إذا كان عمرك أكثر من 21 سنة","فقط عندما تكون السرعة أقل من 30 mph"],"h1":"قراءة رسالة أو إرسالها تبعد عينيك عن الطريق.","h2":"تمنع Wyoming كتابة الرسائل النصية أثناء القيادة، لذلك لا يجوز لك أن تكتب أو ترسل أو تقرأ رسالة نصية أثناء القيادة على طريق عام.","p":"صحيح. كتابة الرسائل أثناء القيادة ممنوعة."},"ref":{"doc":"WY","page":89}},{"id":"wy-021","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, after a crash, when must you contact the police?","o":["Only when a car must be towed","Only when someone wants to sue","When someone is hurt or killed, or damage is $1,000 or more","Only when the crash happens on an interstate"],"h1":"Think about injuries and the dollar amount of the damage.","h2":"In Wyoming you must contact the police when a crash causes an injury, a death, or property damage of $1,000 or more.","p":"Right. Injury, death, or $1,000 or more in damage means you call the police."},"es":{"q":"En Wyoming, después de un choque, ¿cuándo debe usted avisar a la policía?","o":["Solo cuando hay que remolcar un auto","Solo cuando alguien quiere demandar","Cuando alguien resulta herido o muere, o el daño es de $1,000 o más","Solo cuando el choque ocurre en una autopista interestatal"],"h1":"Piense en los heridos y en el valor en dólares del daño.","h2":"En Wyoming usted debe avisar a la policía cuando un choque causa heridos, una muerte o daños a la propiedad de $1,000 o más.","p":"Correcto. Heridos, una muerte o $1,000 o más en daños significa que usted llama a la policía."},"zh":{"q":"在 Wyoming，发生车祸后，什么时候必须联系警察？","o":["只有车必须被拖走时","只有有人想起诉时","有人受伤或死亡，或损失达到 $1,000 或以上时","只有车祸发生在州际公路上时"],"h1":"想一想受伤情况和损失的金额。","h2":"在 Wyoming，如果车祸造成有人受伤、有人死亡，或财产损失达到 $1,000 或以上，你必须联系警察。","p":"对。有人受伤、死亡，或损失达到 $1,000 或以上，就要打电话给警察。"},"vi":{"q":"Ở Wyoming, sau một vụ tai nạn, khi nào bạn phải liên lạc với cảnh sát?","o":["Chỉ khi xe phải bị kéo đi","Chỉ khi có người muốn kiện","Khi có người bị thương hoặc tử vong, hoặc thiệt hại từ $1,000 trở lên","Chỉ khi tai nạn xảy ra trên xa lộ liên tiểu bang"],"h1":"Hãy nghĩ về người bị thương và số tiền thiệt hại.","h2":"Ở Wyoming, bạn phải liên lạc với cảnh sát khi tai nạn làm có người bị thương, có người tử vong, hoặc gây thiệt hại tài sản từ $1,000 trở lên.","p":"Đúng. Có người bị thương, tử vong, hoặc thiệt hại từ $1,000 trở lên thì bạn gọi cảnh sát."},"tl":{"q":"Sa Wyoming, pagkatapos ng banggaan, kailan mo dapat tawagan ang pulis?","o":["Kapag kailangan lang hilahin ang kotse","Kapag may gusto lang magdemanda","Kapag may nasaktan o namatay, o ang pinsala ay $1,000 o higit pa","Kapag nangyari lang ang banggaan sa interstate"],"h1":"Isipin ang mga nasaktan at ang halaga ng pinsala.","h2":"Sa Wyoming, dapat mong tawagan ang pulis kapag ang banggaan ay nagdulot ng pinsala sa tao, pagkamatay, o pinsala sa ari-arian na $1,000 o higit pa.","p":"Tama. Kapag may nasaktan, namatay, o $1,000 o higit pa ang pinsala, tawagan ang pulis."},"ar":{"q":"في Wyoming، بعد حادث سير، متى يجب أن تتصل بالشرطة؟","o":["فقط عندما يجب سحب السيارة","فقط عندما يريد أحد أن يرفع دعوى","عندما يُصاب أحد أو يموت، أو تكون الأضرار $1,000 أو أكثر","فقط عندما يقع الحادث على طريق سريع بين الولايات"],"h1":"فكّر في الإصابات وفي قيمة الأضرار بالدولار.","h2":"في Wyoming يجب أن تتصل بالشرطة عندما يسبب الحادث إصابة أو وفاة أو أضرارًا في الممتلكات قيمتها $1,000 أو أكثر.","p":"صحيح. إذا كانت هناك إصابة أو وفاة أو أضرار بقيمة $1,000 أو أكثر، فاتصل بالشرطة."},"ref":{"doc":"WY","page":67}},{"id":"wy-022","scope":"WY","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Wyoming, on a two-lane road posted at 45 mph or more, you pass a stopped emergency vehicle with its lights on. What must you do?","o":["Keep your speed and honk","Slow to 20 mph below the posted limit","Slow to 5 mph below the posted limit","Stop and wait until it leaves"],"h1":"On a two-lane road you cannot change lanes, so you slow down a lot.","h2":"In Wyoming, on a two-lane road posted at 45 mph or more, you must slow to 20 mph below the posted limit when passing a stopped emergency vehicle.","p":"Right. Wyoming's Move Over law says slow to 20 mph under the limit there."},"es":{"q":"En Wyoming, en una carretera de dos carriles con límite de 45 mph o más, usted pasa un vehículo de emergencia detenido con las luces encendidas. ¿Qué debe hacer?","o":["Mantener su velocidad y tocar la bocina","Bajar a 20 mph menos que el límite indicado","Bajar a 5 mph menos que el límite indicado","Detenerse y esperar a que se vaya"],"h1":"En una carretera de dos carriles no puede cambiar de carril, así que reduce mucho la velocidad.","h2":"En Wyoming, en una carretera de dos carriles con límite de 45 mph o más, usted debe bajar a 20 mph menos que el límite al pasar un vehículo de emergencia detenido.","p":"Correcto. La ley de Move Over de Wyoming pide bajar a 20 mph menos que el límite en ese caso."},"zh":{"q":"在 Wyoming，在限速 45 mph 或以上的双车道道路上，你经过一辆停着并亮着灯的紧急车辆。你必须怎么做？","o":["保持车速并按喇叭","减速到比限速低 20 mph","减速到比限速低 5 mph","停车，等它离开"],"h1":"在双车道道路上你不能换车道，所以要大幅减速。","h2":"在 Wyoming，在限速 45 mph 或以上的双车道道路上，经过停着的紧急车辆时，你必须减速到比限速低 20 mph。","p":"对。Wyoming 的 Move Over 法律规定，在这种道路上要减速到比限速低 20 mph。"},"vi":{"q":"Ở Wyoming, trên đường hai làn có tốc độ giới hạn 45 mph trở lên, bạn đi ngang qua một xe cấp cứu đang dừng và bật đèn. Bạn phải làm gì?","o":["Giữ tốc độ và bấm còi","Giảm xuống thấp hơn tốc độ giới hạn 20 mph","Giảm xuống thấp hơn tốc độ giới hạn 5 mph","Dừng lại và chờ cho đến khi xe đó đi"],"h1":"Trên đường hai làn bạn không thể đổi làn, nên bạn phải chạy chậm lại nhiều.","h2":"Ở Wyoming, trên đường hai làn có tốc độ giới hạn 45 mph trở lên, bạn phải giảm xuống thấp hơn tốc độ giới hạn 20 mph khi đi ngang qua xe cấp cứu đang dừng.","p":"Đúng. Luật Move Over của Wyoming nói phải giảm xuống thấp hơn giới hạn 20 mph ở đó."},"tl":{"q":"Sa Wyoming, sa daang may dalawang lane na may limit na 45 mph o higit pa, dadaan ka sa nakahintong emergency vehicle na nakabukas ang ilaw. Ano ang dapat mong gawin?","o":["Panatilihin ang bilis at bumusina","Bumagal hanggang 20 mph na mas mababa sa limit","Bumagal hanggang 5 mph na mas mababa sa limit","Huminto at maghintay hanggang umalis ito"],"h1":"Sa daang may dalawang lane, hindi ka makakalipat ng lane, kaya bumagal ka nang husto.","h2":"Sa Wyoming, sa daang may dalawang lane na may limit na 45 mph o higit pa, dapat kang bumagal hanggang 20 mph na mas mababa sa limit kapag dumadaan sa nakahintong emergency vehicle.","p":"Tama. Sinasabi ng Move Over law ng Wyoming na bumagal hanggang 20 mph na mas mababa sa limit doon."},"ar":{"q":"في Wyoming، على طريق بمسارين حدّ السرعة فيه 45 mph أو أكثر، تمر بجانب مركبة طوارئ متوقفة وأضواؤها تعمل. ماذا يجب أن تفعل؟","o":["حافظ على سرعتك واستخدم البوق","خفّف السرعة إلى 20 mph أقل من الحد المسموح","خفّف السرعة إلى 5 mph أقل من الحد المسموح","توقف وانتظر حتى تغادر"],"h1":"على طريق بمسارين لا يمكنك تغيير المسار، لذلك تخفف السرعة كثيرًا.","h2":"في Wyoming، على طريق بمسارين حدّ السرعة فيه 45 mph أو أكثر، يجب أن تخفف السرعة إلى 20 mph أقل من الحد المسموح عندما تمر بجانب مركبة طوارئ متوقفة.","p":"صحيح. قانون Move Over في Wyoming يقول خفّف السرعة إلى 20 mph أقل من الحد هناك."},"ref":{"doc":"WY","page":72}},{"id":"wy-023","scope":"WY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wyoming, until what age must a child ride in a child safety seat or booster, unless the seat belt fits properly?","o":["Until the 4th birthday","Until the 6th birthday","Until the 12th birthday","Until the 9th birthday"],"h1":"It is older than a preschool child, but younger than ten.","h2":"In Wyoming a child must use a child restraint until the 9th birthday, unless the lap and shoulder belt fit properly.","p":"Right. Wyoming's child restraint law covers children under 9."},"es":{"q":"En Wyoming, ¿hasta qué edad debe un niño viajar en un asiento de seguridad o elevador, a menos que el cinturón le quede bien?","o":["Hasta cumplir 4 años","Hasta cumplir 6 años","Hasta cumplir 12 años","Hasta cumplir 9 años"],"h1":"Es mayor que un niño de preescolar, pero menor de diez años.","h2":"En Wyoming un niño debe usar un sistema de retención infantil hasta cumplir 9 años, a menos que el cinturón de regazo y hombro le quede bien.","p":"Correcto. La ley de Wyoming sobre asientos infantiles cubre a los niños menores de 9 años."},"zh":{"q":"在 Wyoming，除非安全带合适，孩子必须坐儿童安全座椅或增高座椅到几岁？","o":["到 4 岁生日","到 6 岁生日","到 12 岁生日","到 9 岁生日"],"h1":"比学龄前儿童大，但比十岁小。","h2":"在 Wyoming，孩子必须使用儿童约束装置直到 9 岁生日，除非腰带和肩带合适。","p":"对。Wyoming 的儿童约束法律适用于 9 岁以下的孩子。"},"vi":{"q":"Ở Wyoming, trẻ em phải ngồi ghế an toàn trẻ em hoặc ghế nâng cho đến tuổi nào, trừ khi dây an toàn vừa vặn?","o":["Cho đến sinh nhật 4 tuổi","Cho đến sinh nhật 6 tuổi","Cho đến sinh nhật 12 tuổi","Cho đến sinh nhật 9 tuổi"],"h1":"Lớn hơn trẻ mẫu giáo, nhưng nhỏ hơn mười tuổi.","h2":"Ở Wyoming, trẻ em phải dùng ghế an toàn trẻ em cho đến sinh nhật 9 tuổi, trừ khi dây đai ngang hông và dây đai vai vừa vặn.","p":"Đúng. Luật ghế an toàn trẻ em của Wyoming áp dụng cho trẻ dưới 9 tuổi."},"tl":{"q":"Sa Wyoming, hanggang anong edad dapat sumakay ang bata sa child safety seat o booster, maliban kung tama ang lapat ng seat belt?","o":["Hanggang ika-4 na kaarawan","Hanggang ika-6 na kaarawan","Hanggang ika-12 na kaarawan","Hanggang ika-9 na kaarawan"],"h1":"Mas matanda ito sa batang preschool, pero mas bata sa sampu.","h2":"Sa Wyoming, dapat gumamit ang bata ng child restraint hanggang sa ika-9 na kaarawan niya, maliban kung tama ang lapat ng lap belt at shoulder belt.","p":"Tama. Sakop ng child restraint law ng Wyoming ang mga batang wala pang 9 taong gulang."},"ar":{"q":"في Wyoming، حتى أي عمر يجب أن يجلس الطفل في مقعد أمان للأطفال أو مقعد رافع، إلا إذا كان حزام الأمان مناسبًا له؟","o":["حتى عيد ميلاده الرابع","حتى عيد ميلاده السادس","حتى عيد ميلاده الثاني عشر","حتى عيد ميلاده التاسع"],"h1":"العمر أكبر من طفل ما قبل المدرسة، لكنه أصغر من عشر سنوات.","h2":"في Wyoming يجب أن يستخدم الطفل مقعد أمان للأطفال حتى عيد ميلاده التاسع، إلا إذا كان حزام الحضن وحزام الكتف مناسبين له.","p":"صحيح. قانون مقاعد الأطفال في Wyoming يشمل الأطفال تحت 9 سنوات."},"ref":{"doc":"WY","page":30}},{"id":"wy-024","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, what happens if an intermediate permit holder breaks the permit's rules, such as the night or passenger limits?","o":["A 30-day suspension","A warning letter only","A one-year suspension","A $5 fine only"],"h1":"The suspension is about one month.","h2":"In Wyoming, breaking the rules of an intermediate permit leads to a 30-day suspension.","p":"Right. Breaking the intermediate permit rules means a 30-day suspension."},"es":{"q":"En Wyoming, ¿qué pasa si quien tiene un permiso intermedio no cumple sus reglas, como los límites de noche o de pasajeros?","o":["Una suspensión de 30 días","Solo una carta de advertencia","Una suspensión de un año","Solo una multa de $5"],"h1":"La suspensión dura más o menos un mes.","h2":"En Wyoming, no cumplir las reglas del permiso intermedio lleva a una suspensión de 30 días.","p":"Correcto. No cumplir las reglas del permiso intermedio significa una suspensión de 30 días."},"zh":{"q":"在 Wyoming，如果持有中级驾照的人违反驾照规定，例如夜间或乘客限制，会怎么样？","o":["暂停 30 天","只收到一封警告信","暂停一年","只罚款 $5"],"h1":"暂停时间大约是一个月。","h2":"在 Wyoming，违反中级驾照的规定会导致驾照暂停 30 天。","p":"对。违反中级驾照的规定会被暂停 30 天。"},"vi":{"q":"Ở Wyoming, điều gì xảy ra nếu người có giấy phép trung cấp vi phạm quy định của giấy phép, như giới hạn ban đêm hoặc giới hạn hành khách?","o":["Bị đình chỉ 30 ngày","Chỉ nhận thư cảnh cáo","Bị đình chỉ một năm","Chỉ bị phạt $5"],"h1":"Thời gian đình chỉ khoảng một tháng.","h2":"Ở Wyoming, vi phạm quy định của giấy phép trung cấp sẽ bị đình chỉ 30 ngày.","p":"Đúng. Vi phạm quy định của giấy phép trung cấp nghĩa là bị đình chỉ 30 ngày."},"tl":{"q":"Sa Wyoming, ano ang mangyayari kung lumabag ang may intermediate permit sa mga patakaran ng permit, gaya ng limit sa gabi o sa pasahero?","o":["30 araw na suspensiyon","Sulat ng babala lang","Isang taong suspensiyon","$5 na multa lang"],"h1":"Mga isang buwan ang suspensiyon.","h2":"Sa Wyoming, ang paglabag sa mga patakaran ng intermediate permit ay nagdudulot ng 30 araw na suspensiyon.","p":"Tama. Ang paglabag sa mga patakaran ng intermediate permit ay 30 araw na suspensiyon."},"ar":{"q":"في Wyoming، ماذا يحدث إذا خالف حامل التصريح المتوسط قواعد التصريح، مثل قيود القيادة ليلًا أو عدد الركاب؟","o":["إيقاف لمدة 30 يومًا","رسالة تحذير فقط","إيقاف لمدة سنة","غرامة $5 فقط"],"h1":"مدة الإيقاف حوالي شهر واحد.","h2":"في Wyoming، مخالفة قواعد التصريح المتوسط تؤدي إلى إيقاف لمدة 30 يومًا.","p":"صحيح. مخالفة قواعد التصريح المتوسط تعني إيقافًا لمدة 30 يومًا."},"ref":{"doc":"WY","page":26}},{"id":"wy-025","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, a driver over 21 wants to renew a license. How early before it expires can they renew?","o":["Up to 30 days before","Up to 60 days before","Up to 120 days before","Up to one year before"],"h1":"It is about four months.","h2":"In Wyoming a driver over 21 may renew a license during the 120 days before it expires.","p":"Right. Drivers over 21 can renew up to 120 days early."},"es":{"q":"En Wyoming, un conductor mayor de 21 años quiere renovar su licencia. ¿Con cuánta anticipación puede renovarla antes de que venza?","o":["Hasta 30 días antes","Hasta 60 días antes","Hasta 120 días antes","Hasta un año antes"],"h1":"Son unos cuatro meses.","h2":"En Wyoming un conductor mayor de 21 años puede renovar su licencia durante los 120 días antes de que venza.","p":"Correcto. Los conductores mayores de 21 años pueden renovar hasta 120 días antes."},"zh":{"q":"在 Wyoming，一位超过 21 岁的司机想更新驾照。在驾照到期前最早多久可以更新？","o":["最早到期前 30 天","最早到期前 60 天","最早到期前 120 天","最早到期前一年"],"h1":"大约是四个月。","h2":"在 Wyoming，超过 21 岁的司机可以在驾照到期前的 120 天内更新驾照。","p":"对。超过 21 岁的司机最早可以提前 120 天更新。"},"vi":{"q":"Ở Wyoming, một tài xế trên 21 tuổi muốn gia hạn bằng lái. Họ có thể gia hạn sớm nhất bao lâu trước khi hết hạn?","o":["Tối đa 30 ngày trước","Tối đa 60 ngày trước","Tối đa 120 ngày trước","Tối đa một năm trước"],"h1":"Khoảng bốn tháng.","h2":"Ở Wyoming, tài xế trên 21 tuổi có thể gia hạn bằng lái trong 120 ngày trước khi bằng hết hạn.","p":"Đúng. Tài xế trên 21 tuổi có thể gia hạn sớm tối đa 120 ngày."},"tl":{"q":"Sa Wyoming, gustong mag-renew ng lisensiya ang isang driver na lampas 21. Gaano kaaga bago ito mag-expire puwede siyang mag-renew?","o":["Hanggang 30 araw bago","Hanggang 60 araw bago","Hanggang 120 araw bago","Hanggang isang taon bago"],"h1":"Mga apat na buwan ito.","h2":"Sa Wyoming, puwedeng mag-renew ng lisensiya ang driver na lampas 21 sa loob ng 120 araw bago ito mag-expire.","p":"Tama. Puwedeng mag-renew ang mga driver na lampas 21 hanggang 120 araw nang mas maaga."},"ar":{"q":"في Wyoming، سائق عمره أكثر من 21 سنة يريد تجديد رخصته. كم من الوقت قبل انتهائها يمكنه أن يجددها؟","o":["حتى 30 يومًا قبل انتهائها","حتى 60 يومًا قبل انتهائها","حتى 120 يومًا قبل انتهائها","حتى سنة قبل انتهائها"],"h1":"المدة حوالي أربعة أشهر.","h2":"في Wyoming يمكن للسائق الذي عمره أكثر من 21 سنة أن يجدد رخصته خلال الـ 120 يومًا التي تسبق انتهاءها.","p":"صحيح. يمكن للسائقين الذين عمرهم أكثر من 21 سنة التجديد قبل الموعد بـ 120 يومًا."},"ref":{"doc":"WY","page":10}},{"id":"wy-026","scope":"WY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wyoming, a driver 21 or older takes a breath or blood test and the result is 0.08 percent or more. What happens to the license?","o":["Nothing until a court date","It is suspended for 90 days","It is suspended for 7 days","It is suspended for 5 years"],"h1":"The suspension lasts about three months.","h2":"In Wyoming, a test result of 0.08 percent or more leads to a 90-day license suspension, and there may be criminal penalties too.","p":"Right. A result of 0.08 or more means a 90-day suspension."},"es":{"q":"En Wyoming, un conductor de 21 años o más se hace una prueba de aliento o de sangre y el resultado es 0.08 por ciento o más. ¿Qué pasa con la licencia?","o":["Nada hasta la fecha de la corte","Se suspende por 90 días","Se suspende por 7 días","Se suspende por 5 años"],"h1":"La suspensión dura unos tres meses.","h2":"En Wyoming, un resultado de 0.08 por ciento o más lleva a una suspensión de la licencia por 90 días, y también puede haber penas criminales.","p":"Correcto. Un resultado de 0.08 o más significa una suspensión de 90 días."},"zh":{"q":"在 Wyoming，一位 21 岁或以上的司机做了呼气或血液检测，结果是 0.08% 或以上。驾照会怎么样？","o":["在开庭前什么都不会发生","被暂停 90 天","被暂停 7 天","被暂停 5 年"],"h1":"暂停时间大约是三个月。","h2":"在 Wyoming，检测结果是 0.08% 或以上会导致驾照被暂停 90 天，还可能有刑事处罚。","p":"对。结果是 0.08 或以上就会被暂停 90 天。"},"vi":{"q":"Ở Wyoming, một tài xế từ 21 tuổi trở lên làm xét nghiệm hơi thở hoặc máu và kết quả là 0.08% trở lên. Điều gì xảy ra với bằng lái?","o":["Không có gì cho đến ngày ra tòa","Bị đình chỉ 90 ngày","Bị đình chỉ 7 ngày","Bị đình chỉ 5 năm"],"h1":"Thời gian đình chỉ khoảng ba tháng.","h2":"Ở Wyoming, kết quả xét nghiệm từ 0.08% trở lên sẽ làm bằng lái bị đình chỉ 90 ngày, và cũng có thể có hình phạt hình sự.","p":"Đúng. Kết quả từ 0.08 trở lên nghĩa là bị đình chỉ 90 ngày."},"tl":{"q":"Sa Wyoming, isang driver na 21 o mas matanda ang kumuha ng breath o blood test at ang resulta ay 0.08% o higit pa. Ano ang mangyayari sa lisensiya?","o":["Wala hanggang sa araw ng korte","Masususpinde ito nang 90 araw","Masususpinde ito nang 7 araw","Masususpinde ito nang 5 taon"],"h1":"Mga tatlong buwan ang suspensiyon.","h2":"Sa Wyoming, ang resulta ng test na 0.08% o higit pa ay nagdudulot ng 90 araw na suspensiyon ng lisensiya, at puwede ring may parusang kriminal.","p":"Tama. Ang resultang 0.08 o higit pa ay 90 araw na suspensiyon."},"ar":{"q":"في Wyoming، سائق عمره 21 سنة أو أكثر يُجري اختبار تنفس أو دم والنتيجة 0.08% أو أكثر. ماذا يحدث للرخصة؟","o":["لا شيء حتى موعد المحكمة","يتم إيقافها لمدة 90 يومًا","يتم إيقافها لمدة 7 أيام","يتم إيقافها لمدة 5 سنوات"],"h1":"مدة الإيقاف حوالي ثلاثة أشهر.","h2":"في Wyoming، نتيجة اختبار 0.08% أو أكثر تؤدي إلى إيقاف الرخصة لمدة 90 يومًا، وقد تكون هناك عقوبات جنائية أيضًا.","p":"صحيح. نتيجة 0.08 أو أكثر تعني إيقافًا لمدة 90 يومًا."},"ref":{"doc":"WY","page":37}},{"id":"wy-027","scope":"WY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wyoming, can a driver be convicted of driving under the influence with a blood alcohol level below 0.08 percent?","o":["No, never below 0.08 percent","Only if the driver is over 65","Only if there was a crash","Yes, from 0.05 percent with other evidence"],"h1":"A lower level can count when there are other signs of impairment.","h2":"In Wyoming a driver can be convicted of driving under the influence with a level of 0.05 percent when there is other evidence of impairment.","p":"Right. In Wyoming, 0.05 plus other evidence can lead to a conviction."},"es":{"q":"En Wyoming, ¿se puede condenar a un conductor por manejar bajo la influencia con un nivel de alcohol en la sangre menor de 0.08 por ciento?","o":["No, nunca por debajo de 0.08 por ciento","Solo si el conductor tiene más de 65 años","Solo si hubo un choque","Sí, desde 0.05 por ciento con otras pruebas"],"h1":"Un nivel más bajo puede contar cuando hay otras señales de que el conductor está afectado.","h2":"En Wyoming se puede condenar a un conductor por manejar bajo la influencia con un nivel de 0.05 por ciento cuando hay otras pruebas de que está afectado.","p":"Correcto. En Wyoming, 0.05 más otras pruebas puede llevar a una condena."},"zh":{"q":"在 Wyoming，如果血液酒精浓度低于 0.08%，司机会被判酒后驾驶吗？","o":["不会，低于 0.08% 永远不会","只有司机超过 65 岁时","只有发生了车祸时","会，从 0.05% 开始，并有其他证据时"],"h1":"有其他受影响的迹象时，较低的浓度也可能算数。","h2":"在 Wyoming，如果有其他证据显示司机受到影响，血液酒精浓度为 0.05% 的司机也可能被判酒后驾驶。","p":"对。在 Wyoming，0.05 加上其他证据就可能被定罪。"},"vi":{"q":"Ở Wyoming, tài xế có thể bị kết tội lái xe khi say nếu nồng độ cồn trong máu dưới 0.08% không?","o":["Không, không bao giờ khi dưới 0.08%","Chỉ khi tài xế trên 65 tuổi","Chỉ khi đã xảy ra tai nạn","Có, từ 0.05% khi có bằng chứng khác"],"h1":"Mức thấp hơn vẫn có thể bị tính khi có dấu hiệu khác cho thấy bị ảnh hưởng.","h2":"Ở Wyoming, tài xế có thể bị kết tội lái xe khi say với mức 0.05% khi có bằng chứng khác cho thấy bị ảnh hưởng.","p":"Đúng. Ở Wyoming, 0.05 cộng với bằng chứng khác có thể dẫn đến bị kết tội."},"tl":{"q":"Sa Wyoming, puwede bang mahatulan ang driver ng pagmamaneho nang lasing kung ang alcohol sa dugo niya ay mas mababa sa 0.08%?","o":["Hindi, hindi kailanman kapag mas mababa sa 0.08%","Kung lampas 65 lang ang driver","Kung may banggaan lang","Oo, mula 0.05% kapag may iba pang ebidensiya"],"h1":"Puwedeng bilangin ang mas mababang level kapag may iba pang palatandaan na apektado ang driver.","h2":"Sa Wyoming, puwedeng mahatulan ang driver ng pagmamaneho nang lasing sa level na 0.05% kapag may iba pang ebidensiya na apektado siya.","p":"Tama. Sa Wyoming, ang 0.05 kasama ang iba pang ebidensiya ay puwedeng humantong sa paghatol."},"ar":{"q":"في Wyoming، هل يمكن إدانة سائق بالقيادة تحت تأثير الكحول إذا كانت نسبة الكحول في دمه أقل من 0.08%؟","o":["لا، أبدًا تحت 0.08%","فقط إذا كان عمر السائق أكثر من 65 سنة","فقط إذا وقع حادث","نعم، من 0.05% مع أدلة أخرى"],"h1":"قد تُحسب النسبة الأقل عندما توجد علامات أخرى على التأثر.","h2":"في Wyoming يمكن إدانة السائق بالقيادة تحت تأثير الكحول بنسبة 0.05% عندما توجد أدلة أخرى على أنه متأثر.","p":"صحيح. في Wyoming، نسبة 0.05 مع أدلة أخرى قد تؤدي إلى الإدانة."},"ref":{"doc":"WY","page":37}},{"id":"wy-028","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, what eyesight do you need in both eyes to meet the vision standard for driving?","o":["20/40","20/20","20/80","20/200"],"h1":"Glasses or contact lenses may be used to reach it.","h2":"In Wyoming, you need 20/40 vision with both eyes, with or without glasses, to meet the vision standard.","p":"Right. The standard is 20/40 with both eyes."},"es":{"q":"En Wyoming, ¿qué visión necesita en ambos ojos para cumplir con el requisito de visión para manejar?","o":["20/40","20/20","20/80","20/200"],"h1":"Puede usar lentes o lentes de contacto para lograrlo.","h2":"En Wyoming, usted necesita una visión de 20/40 con ambos ojos, con o sin lentes, para cumplir con el requisito de visión.","p":"Correcto. El requisito es 20/40 con ambos ojos."},"zh":{"q":"在 Wyoming，双眼视力需要达到多少才符合驾驶的视力标准？","o":["20/40","20/20","20/80","20/200"],"h1":"可以戴眼镜或隐形眼镜来达到这个标准。","h2":"在 Wyoming，你的双眼视力需要达到 20/40（戴不戴眼镜都可以），才符合视力标准。","p":"对。标准是双眼 20/40。"},"vi":{"q":"Ở Wyoming, bạn cần thị lực hai mắt bao nhiêu để đạt tiêu chuẩn thị lực khi lái xe?","o":["20/40","20/20","20/80","20/200"],"h1":"Bạn có thể dùng kính hoặc kính áp tròng để đạt mức này.","h2":"Ở Wyoming, bạn cần thị lực 20/40 với cả hai mắt, có hoặc không có kính, để đạt tiêu chuẩn thị lực.","p":"Đúng. Tiêu chuẩn là 20/40 với cả hai mắt."},"tl":{"q":"Sa Wyoming, anong linaw ng paningin sa dalawang mata ang kailangan mo para pumasa sa pamantayan sa paningin para makapagmaneho?","o":["20/40","20/20","20/80","20/200"],"h1":"Puwedeng gumamit ng salamin o contact lens para maabot ito.","h2":"Sa Wyoming, kailangan mo ng 20/40 na paningin sa dalawang mata, may salamin man o wala, para pumasa sa pamantayan sa paningin.","p":"Tama. Ang pamantayan ay 20/40 sa dalawang mata."},"ar":{"q":"في Wyoming، ما قوة النظر التي تحتاجها في العينين معًا لتستوفي معيار النظر للقيادة؟","o":["20/40","20/20","20/80","20/200"],"h1":"يمكن استخدام النظارات أو العدسات اللاصقة للوصول إليها.","h2":"في Wyoming تحتاج إلى نظر 20/40 في العينين معًا، بنظارات أو بدونها، لتستوفي معيار النظر.","p":"صحيح. المعيار هو 20/40 في العينين معًا."},"ref":{"doc":"WY","page":8}},{"id":"wy-029","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, after you move to a new address, how soon must you tell the driver license office in writing?","o":["Within 30 days","Within 10 days","Within 60 days","Within 1 year"],"h1":"It is less than two weeks.","h2":"In Wyoming, you must notify the department in writing within 10 days after you change your address.","p":"Right. Report a new address within 10 days."},"es":{"q":"En Wyoming, después de cambiar de domicilio, ¿en cuánto tiempo debe avisar por escrito a la oficina de licencias?","o":["En 30 días","En 10 días","En 60 días","En 1 año"],"h1":"Es menos de dos semanas.","h2":"En Wyoming, usted debe avisar por escrito al departamento en 10 días después de cambiar de domicilio.","p":"Correcto. Informe su nuevo domicilio en 10 días."},"zh":{"q":"在 Wyoming，搬到新地址后，你必须在多长时间内书面通知驾照办公室？","o":["30 天内","10 天内","60 天内","1 年内"],"h1":"不到两个星期。","h2":"在 Wyoming，你更改地址后，必须在 10 天内书面通知驾照部门。","p":"对。新地址要在 10 天内报告。"},"vi":{"q":"Ở Wyoming, sau khi chuyển đến địa chỉ mới, bạn phải báo cho văn phòng bằng lái bằng văn bản trong bao lâu?","o":["Trong vòng 30 ngày","Trong vòng 10 ngày","Trong vòng 60 ngày","Trong vòng 1 năm"],"h1":"Ít hơn hai tuần.","h2":"Ở Wyoming, bạn phải báo cho cơ quan bằng văn bản trong vòng 10 ngày sau khi đổi địa chỉ.","p":"Đúng. Hãy báo địa chỉ mới trong vòng 10 ngày."},"tl":{"q":"Sa Wyoming, pagkatapos mong lumipat sa bagong address, gaano kabilis mo dapat sabihan nang nakasulat ang opisina ng driver license?","o":["Sa loob ng 30 araw","Sa loob ng 10 araw","Sa loob ng 60 araw","Sa loob ng 1 taon"],"h1":"Mas maikli ito sa dalawang linggo.","h2":"Sa Wyoming, dapat mong sabihan nang nakasulat ang departamento sa loob ng 10 araw pagkatapos mong magpalit ng address.","p":"Tama. Iulat ang bagong address sa loob ng 10 araw."},"ar":{"q":"في Wyoming، بعد انتقالك إلى عنوان جديد، خلال كم من الوقت يجب أن تُبلغ مكتب رخص القيادة كتابيًا؟","o":["خلال 30 يومًا","خلال 10 أيام","خلال 60 يومًا","خلال سنة واحدة"],"h1":"المدة أقل من أسبوعين.","h2":"في Wyoming يجب أن تُبلغ الإدارة كتابيًا خلال 10 أيام بعد تغيير عنوانك.","p":"صحيح. أبلغ عن العنوان الجديد خلال 10 أيام."},"ref":{"doc":"WY","page":8}},{"id":"wy-030","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, how many times may you take the written test in one day?","o":["Once","Three times","Twice","Five times"],"h1":"You get one more try the same day if the first one does not go well.","h2":"In Wyoming, a driver license applicant may take the written test twice in one day.","p":"Right. You may take the written test twice in one day."},"es":{"q":"En Wyoming, ¿cuántas veces puede tomar el examen escrito en un mismo día?","o":["Una vez","Tres veces","Dos veces","Cinco veces"],"h1":"Tiene un intento más el mismo día si el primero no sale bien.","h2":"En Wyoming, una persona que solicita la licencia puede tomar el examen escrito dos veces en un mismo día.","p":"Correcto. Puede tomar el examen escrito dos veces en un día."},"zh":{"q":"在 Wyoming，你一天可以参加几次笔试？","o":["一次","三次","两次","五次"],"h1":"如果第一次没考好，同一天你还有一次机会。","h2":"在 Wyoming，申请驾照的人一天可以参加两次笔试。","p":"对。你一天可以参加两次笔试。"},"vi":{"q":"Ở Wyoming, bạn được thi viết bao nhiêu lần trong một ngày?","o":["Một lần","Ba lần","Hai lần","Năm lần"],"h1":"Bạn được thử thêm một lần trong cùng ngày nếu lần đầu không tốt.","h2":"Ở Wyoming, người xin bằng lái được thi viết hai lần trong một ngày.","p":"Đúng. Bạn được thi viết hai lần trong một ngày."},"tl":{"q":"Sa Wyoming, ilang beses ka puwedeng kumuha ng written test sa isang araw?","o":["Isang beses","Tatlong beses","Dalawang beses","Limang beses"],"h1":"May isa ka pang pagkakataon sa parehong araw kung hindi maganda ang una.","h2":"Sa Wyoming, puwedeng kumuha ng written test nang dalawang beses sa isang araw ang nag-a-apply ng driver license.","p":"Tama. Puwede kang kumuha ng written test nang dalawang beses sa isang araw."},"ar":{"q":"في Wyoming، كم مرة يمكنك أن تأخذ الاختبار الكتابي في يوم واحد؟","o":["مرة واحدة","ثلاث مرات","مرتين","خمس مرات"],"h1":"لديك محاولة أخرى في اليوم نفسه إذا لم تنجح المحاولة الأولى.","h2":"في Wyoming يمكن لمن يتقدم لرخصة القيادة أن يأخذ الاختبار الكتابي مرتين في يوم واحد.","p":"صحيح. يمكنك أن تأخذ الاختبار الكتابي مرتين في يوم واحد."},"ref":{"doc":"WY","page":9}},{"id":"wy-031","scope":"WY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wyoming, you are coming up behind another vehicle at night. Within how many feet must you dim your headlights?","o":["100 feet","200 feet","500 feet","300 feet"],"h1":"It is less than the distance for an oncoming vehicle.","h2":"In Wyoming, you must dim your headlights when you are within 300 feet of the rear of a vehicle you are approaching.","p":"Right. Dim your lights within 300 feet of a vehicle ahead."},"es":{"q":"En Wyoming, usted se acerca de noche por detrás a otro vehículo. ¿A cuántos pies debe bajar las luces?","o":["100 pies","200 pies","500 pies","300 pies"],"h1":"Es menos que la distancia para un vehículo que viene de frente.","h2":"En Wyoming, usted debe bajar las luces cuando está a 300 pies o menos de la parte de atrás de un vehículo al que se acerca.","p":"Correcto. Baje las luces a 300 pies de un vehículo que va adelante."},"zh":{"q":"在 Wyoming，晚上你正在从后面接近另一辆车。你必须在多少英尺以内把大灯调暗？","o":["100 英尺","200 英尺","500 英尺","300 英尺"],"h1":"这个距离比对面来车时的距离短。","h2":"在 Wyoming，当你接近前面一辆车，距离它的车尾 300 英尺以内时，必须把大灯调暗。","p":"对。在前车 300 英尺以内要调暗车灯。"},"vi":{"q":"Ở Wyoming, bạn đang chạy đến gần phía sau một xe khác vào ban đêm. Bạn phải giảm đèn pha khi cách bao nhiêu feet?","o":["100 feet","200 feet","500 feet","300 feet"],"h1":"Khoảng cách này ngắn hơn khoảng cách với xe chạy ngược chiều.","h2":"Ở Wyoming, bạn phải giảm đèn pha khi bạn cách đuôi xe phía trước 300 feet hoặc gần hơn.","p":"Đúng. Hãy giảm đèn khi cách xe phía trước 300 feet."},"tl":{"q":"Sa Wyoming, papalapit ka sa likod ng ibang sasakyan sa gabi. Sa loob ng ilang talampakan mo dapat i-dim ang headlights mo?","o":["100 talampakan","200 talampakan","500 talampakan","300 talampakan"],"h1":"Mas maikli ito kaysa sa distansiya para sa paparating na sasakyan.","h2":"Sa Wyoming, dapat mong i-dim ang headlights mo kapag nasa loob ka ng 300 talampakan mula sa likod ng sasakyang nilalapitan mo.","p":"Tama. I-dim ang ilaw mo sa loob ng 300 talampakan mula sa sasakyan sa unahan."},"ar":{"q":"في Wyoming، أنت تقترب ليلًا من خلف سيارة أخرى. ضمن كم قدمًا يجب أن تخفض أضواءك الأمامية؟","o":["100 قدم","200 قدم","500 قدم","300 قدم"],"h1":"المسافة أقل من المسافة الخاصة بالسيارة القادمة من الاتجاه المقابل.","h2":"في Wyoming يجب أن تخفض أضواءك الأمامية عندما تكون على بعد 300 قدم أو أقل من مؤخرة السيارة التي تقترب منها.","p":"صحيح. اخفض أضواءك عندما تكون على بعد 300 قدم من السيارة التي أمامك."},"ref":{"doc":"WY","page":78}}];
